INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1,'Задание Канретада','C возвращением из мира смерти, герой. Было время, когда ты с гордостью $gстоял:стояла; среди своих собратьев, и меч твой был остер. Ныне же ты – лишь тень прошлого. Но встань передо мной, и я воскрешу легендарного рыцаря, которым ты некогда $gбыл:была;.$b$bЯ восполню твои силы, восстановлю оружие и подготовлю тебя к новым подвигам.','Поговорите с Канретадом, чтобы восстановить ваши таланты, оружие и средство передвижения.','Вернитесь к Канретаду.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание Канретада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','C возвращением из мира смерти, герой. Было время, когда ты с гордостью $gстоял:стояла; среди своих собратьев, и меч твой был остер. Ныне же ты – лишь тень прошлого. Но встань передо мной, и я воскрешу легендарного рыцаря, которым ты некогда $gбыл:была;.$b$bЯ восполню твои силы, восстановлю оружие и подготовлю тебя к новым подвигам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Канретадом, чтобы восстановить ваши таланты, оружие и средство передвижения.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Канретаду.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (2,'Коготь гиппогрифа Острокогтя','Могучий гиппогриф Острокоготь был убит, и коготь этой свирепой твари – свидетельство вашей победы.$b$bСенани Громовое Сердце в приюте Серебряного Ветра несомненно пожелает увидеть этот трофей – доказательство ваших деяний.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коготь гиппогрифа Острокогтя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могучий гиппогриф Острокоготь был убит, и коготь этой свирепой твари – свидетельство вашей победы.$b$bСенани Громовое Сердце в приюте Серебряного Ветра несомненно пожелает увидеть этот трофей – доказательство ваших деяний.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5,'Урчащий живот Трясунчика','Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев! Страшно хочется нормальной еды, и я за нее хорошо заплачу.$B$BУстрой мне пир, и не пожалеешь.$B$BГоворят, что шеф-повар Груаль в таверне "Алый ворон" делает превосходные темные пирожки с крабами...','Поговорите с шеф-поваром Груалем.','Значит, тебе нужны пирожки с крабами? Что ж, могу испечь...','О, посылка от моего брата? Великолепно! Сегодня мне по-настоящему светит удача!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урчащий живот Трясунчика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев! Страшно хочется нормальной еды, и я за нее хорошо заплачу.$B$BУстрой мне пир, и не пожалеешь.$B$BГоворят, что шеф-повар Груаль в таверне "Алый ворон" делает превосходные темные пирожки с крабами...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с шеф-поваром Груалем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, тебе нужны пирожки с крабами? Что ж, могу испечь...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, посылка от моего брата? Великолепно! Сегодня мне по-настоящему светит удача!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6,'Награда за голову Гаррика Тихокрада','Гаррик Тихокрад – головорез, который уже много недель не дает покоя нашим крестьянам и торговцам. Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом. Принесешь мне голову этого негодяя – получишь награду!$B$BНо будь $Gосторожен:осторожна;, $n. Гаррик собрал разбойничью шайку. До него непросто будет добраться.','Убейте Гаррика Тихокрада и принесите его голову заместителю судьи Виллему в Аббатство Североземья.','Ты $Gнашел:нашла; шайку Гаррика? Неужто мы, наконец, избавились от этого бандита?','Вернитесь к заместителю судьи Виллему в Долину Североземья, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда за голову Гаррика Тихокрада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гаррик Тихокрад – головорез, который уже много недель не дает покоя нашим крестьянам и торговцам. Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом. Принесешь мне голову этого негодяя – получишь награду!$B$BНо будь $Gосторожен:осторожна;, $n. Гаррик собрал разбойничью шайку. До него непросто будет добраться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гаррика Тихокрада и принесите его голову заместителю судьи Виллему в Аббатство Североземья.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; шайку Гаррика? Неужто мы, наконец, избавились от этого бандита?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заместителю судьи Виллему в Долину Североземья, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7,'Первое твое задание, $n, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.','Уничтожьте 6 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.','Ну, $gдобыл:добыла; мне банданы?','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первое твое задание, $n, – это зачистка. Северные леса наводнили кобольды. Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь. Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 кобольдов-вредителей. Вернитесь к маршалу Макбрайду.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, $gдобыл:добыла; мне банданы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8,'Выгодная сделка','Эй, $gприятель:подруга;! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! $b$bУ меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-ее-там. Неважно, какая у нее там фамилия! $b$bДа и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и $gсам:сама; сможешь там отдохнуть, если захочешь. По крайней мере, ты $gдолжен:должна; туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу.','Доставьте ненадписанное письмо Ренни – хозяйке таверны в Тирисфальских лесах.','Ого! Письмо? Отличная новость! Я давно жду весточки от моей старушки-матери из Могильника. Она настоящая святая – моя мать. Как она там поживает... $b$bЧто? Слишком фальшивлю? Не купился?$b$bНу так отстань... тебе абсолютно не обязательно знать, от кого это письмо. Давай, давай, иди отсюда! $b$bВозвращайся, когда будет что потратить... бродяга. $b$bИ вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости.','А? Что? Что это?$B$BОтрекшиеся... на аппетит они явно не жалуются. Располагайтесь как дома... да, дайте покой своим усталым косточкам. Меня зовут Ренни, если что-то понадобится – я к вашим услугам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выгодная сделка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $gприятель:подруга;! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками! $b$bУ меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-ее-там. Неважно, какая у нее там фамилия! $b$bДа и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире. Ты и $gсам:сама; сможешь там отдохнуть, если захочешь. По крайней мере, ты $gдолжен:должна; туда заглянуть... ну а за доставку письма я тебе хорошенько заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте ненадписанное письмо Ренни – хозяйке таверны в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ого! Письмо? Отличная новость! Я давно жду весточки от моей старушки-матери из Могильника. Она настоящая святая – моя мать. Как она там поживает... $b$bЧто? Слишком фальшивлю? Не купился?$b$bНу так отстань... тебе абсолютно не обязательно знать, от кого это письмо. Давай, давай, иди отсюда! $b$bВозвращайся, когда будет что потратить... бродяга. $b$bИ вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А? Что? Что это?$B$BОтрекшиеся... на аппетит они явно не жалуются. Располагайтесь как дома... да, дайте покой своим усталым косточкам. Меня зовут Ренни, если что-то понадобится – я к вашим услугам.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9,'Поля смерти','Взгляните, во что превратилось это место! Когда-то эти земли населяли честные крестьяне. Но проклятые воры выжили отсюда всех. Только не меня! Однако угодья захватили големы – дозорные полей.$b$bЕсли вы готовы поработать, я попросил бы вас пойти и убить 20 таких големов. Возвращайтесь за оплатой, когда все будет сделано. Когда расправитесь с теми, что обитают на моем поле, зачистите поля и моих соседей тоже.','Убейте 20 дозорных полей по просьбе фермера Сальдена.','Отличная работа, дружище. Вы полностью отработали свою плату. Кто знает, может быть, Западный Край снова расцветет.','А, я вижу, вы вернулись! Надеюсь, вы упорно работали над тем, чтобы очистить наши угодья от дозорных полей. Двадцати еще не набралось?','Вернитесь к фермеру Сальдену на ферму Сальдена, что в Западном Крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поля смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взгляните, во что превратилось это место! Когда-то эти земли населяли честные крестьяне. Но проклятые воры выжили отсюда всех. Только не меня! Однако угодья захватили големы – дозорные полей.$b$bЕсли вы готовы поработать, я попросил бы вас пойти и убить 20 таких големов. Возвращайтесь за оплатой, когда все будет сделано. Когда расправитесь с теми, что обитают на моем поле, зачистите поля и моих соседей тоже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 дозорных полей по просьбе фермера Сальдена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, дружище. Вы полностью отработали свою плату. Кто знает, может быть, Западный Край снова расцветет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, я вижу, вы вернулись! Надеюсь, вы упорно работали над тем, чтобы очистить наши угодья от дозорных полей. Двадцати еще не набралось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Сальдену на ферму Сальдена, что в Западном Крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10,'Спасение Холстомера','Ох, это ужасно! Я послал моего лучшего помощника, младшего геодезиста Холстомера в пустыню, на юго-восток отсюда. Именно там располагается Зияющая бездна. Вот, а теперь он пропал, и в последнем докладе шла речь о странных насекомых. Неужели они наводнили уже два основных района пустыни?$b$bПрошу тебя, доберись до Зияющей бездны и поищи там Холстомера! Его... или хотя бы оборудование. Боюсь, больше от бедняги ничего и не осталось.','Узнайте, что стало с младшим геодезистом Холстомером и приведите его или верните его оборудование старшему геодезисту Рудознатцу в Прибамбасск.','Ну, что тебе удалось узнать? Похоже, ты только что из боя... Жив ли Холстомер?','Вернитесь к старшему геодезисту Рудознатцу в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Холстомера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, это ужасно! Я послал моего лучшего помощника, младшего геодезиста Холстомера в пустыню, на юго-восток отсюда. Именно там располагается Зияющая бездна. Вот, а теперь он пропал, и в последнем докладе шла речь о странных насекомых. Неужели они наводнили уже два основных района пустыни?$b$bПрошу тебя, доберись до Зияющей бездны и поищи там Холстомера! Его... или хотя бы оборудование. Боюсь, больше от бедняги ничего и не осталось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, что стало с младшим геодезистом Холстомером и приведите его или верните его оборудование старшему геодезисту Рудознатцу в Прибамбасск.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что тебе удалось узнать? Похоже, ты только что из боя... Жив ли Холстомер?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему геодезисту Рудознатцу в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11,'Награда за гноллов из стаи Речной Лапы','На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях. К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться. Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов.$B$BАрмия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой. В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов.','Принесите 8 раскрашенных поручей гноллов в казармы заместителю судьи Рейнеру.','Вернитесь к заместителю судьи Рейнеру на лесную опушку, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда за гноллов из стаи Речной Лапы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях. К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться. Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов.$B$BАрмия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой. В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 раскрашенных поручей гноллов в казармы заместителю судьи Рейнеру.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заместителю судьи Рейнеру на лесную опушку, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (12,'Народное ополчение','У народного ополчения есть лишь одна цель: защитить земли Западного Края и вернуть в них мир. К сожалению, приходится это делать путем кровопролития.$b$bОдин из моих разведчиков сообщил о группе звероловов из Братства Справедливости, наводящих на местных жителей ужас и панику. У меня есть сообщения, что звероловов Братства замечали около рудника Янго к северо-западу отсюда, а также неподалеку от фермы Мольсена и тыквенной фермы Хмуроброва. Если ты хочешь присоединиться к ополчению, убей 15 звероловов и 15 контрабандистов из Братства Справедливости, а затем возвращайся ко мне.','Убейте 15 звероловов и 15 контрабандистов из Братства Справедливости и вернитесь к Гриану Камнегриву.','Отличная работа, $n. Мой разведчик был свидетелем твои доблестных деяний. Пока что с тобой очень приятно иметь дело.','Быть может, я недостаточно ясно выразился? Прошу прощения. Чтобы доказать, что ты $gдостоин:достойна; вступить в ряды народного ополчения и служить Свету, ты $gдолжен:должна; убить 15 звероловов и 15 контрабандистов из Братства Справедливости и вернуться ко мне, когда это будет сделано.','Вернитесь к Гриану Камнегриву на Сторожевой холм, что в Западном Крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Народное ополчение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У народного ополчения есть лишь одна цель: защитить земли Западного Края и вернуть в них мир. К сожалению, приходится это делать путем кровопролития.$b$bОдин из моих разведчиков сообщил о группе звероловов из Братства Справедливости, наводящих на местных жителей ужас и панику. У меня есть сообщения, что звероловов Братства замечали около рудника Янго к северо-западу отсюда, а также неподалеку от фермы Мольсена и тыквенной фермы Хмуроброва. Если ты хочешь присоединиться к ополчению, убей 15 звероловов и 15 контрабандистов из Братства Справедливости, а затем возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 звероловов и 15 контрабандистов из Братства Справедливости и вернитесь к Гриану Камнегриву.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $n. Мой разведчик был свидетелем твои доблестных деяний. Пока что с тобой очень приятно иметь дело.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Быть может, я недостаточно ясно выразился? Прошу прощения. Чтобы доказать, что ты $gдостоин:достойна; вступить в ряды народного ополчения и служить Свету, ты $gдолжен:должна; убить 15 звероловов и 15 контрабандистов из Братства Справедливости и вернуться ко мне, когда это будет сделано.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гриану Камнегриву на Сторожевой холм, что в Западном Крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (13,'Народное ополчение','Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и Поместья Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, $n, и пусть весь Западный Край узнает о силе Света.$b$bЗолотой карьер находится неподалеку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты $gубил:убила; 15 погромщиков и 15 мошенников из Братства Справедливости.','Убейте 15 погромщиков и 15 мошенников из Братства Справедливости и вернитесь к Гриану Камнегриву на Сторожевой холм.','Нет времени на разговоры, $N. Погромщики из братства Справедливости лишают жителей Западного края мира и процветания, которого они заслуживают. Удостоверься, что ты $Gубил:убила; как минимум 15 погромщиков и 15 мошенников. Это послужит остальным ясным намеком на то, что разбою здесь места нет.','Вернитесь к Гриану Камнегриву на Сторожевой холм, что в Западном Крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Народное ополчение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и Поместья Алекстона. Народное ополчение не потерпит этого. Разберись с этим немедленно, $n, и пусть весь Западный Край узнает о силе Света.$b$bЗолотой карьер находится неподалеку от побережья, к западу от башни. В качестве следующего этапа твоего обучения я хочу, чтобы ты $gубил:убила; 15 погромщиков и 15 мошенников из Братства Справедливости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 погромщиков и 15 мошенников из Братства Справедливости и вернитесь к Гриану Камнегриву на Сторожевой холм.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нет времени на разговоры, $N. Погромщики из братства Справедливости лишают жителей Западного края мира и процветания, которого они заслуживают. Удостоверься, что ты $Gубил:убила; как минимум 15 погромщиков и 15 мошенников. Это послужит остальным ясным намеком на то, что разбою здесь места нет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гриану Камнегриву на Сторожевой холм, что в Западном Крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (14,'Народное ополчение','Некоторые члены Братства Справедливости от нас ускользнули. Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого братства грабят и разоряют деревни вплоть до Южного Западного Края. Мы считаем, что они скрываются в Холмах Кинжалов, замышляя новые бесчинства. Убей этих негодяев от имени народного ополчения.','Убейте 15 разбойников, 5 налетчиков и 5 кастетчиков из Братства Справедливости. Вернитесь к Гриану Камнегриву на Сторожевой холм.','Я покинул разоренные земли Лордерона, вернувшись на свою родину... и застал ее в столь же ужасном состоянии. Но для Западного Края еще есть надежда. Проявленная тобой доблесть доказала, что ты с честью служишь нашему делу. С огромной гордостью я принимаю тебя в ряды народного ополчения. Да воссияет над тобой Свет!','$N, сейчас не время для пустой болтовни. Если вы все еще хотите показать себя народному ополчению, вам нужно убить членов Братства, о которых я уведомил вас ранее. Возвращайся ко мне, когда выполнишь свой долг.','Вернитесь к Гриану Камнегриву на Сторожевой холм, что в Западном Крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Народное ополчение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые члены Братства Справедливости от нас ускользнули. Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого братства грабят и разоряют деревни вплоть до Южного Западного Края. Мы считаем, что они скрываются в Холмах Кинжалов, замышляя новые бесчинства. Убей этих негодяев от имени народного ополчения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 разбойников, 5 налетчиков и 5 кастетчиков из Братства Справедливости. Вернитесь к Гриану Камнегриву на Сторожевой холм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я покинул разоренные земли Лордерона, вернувшись на свою родину... и застал ее в столь же ужасном состоянии. Но для Западного Края еще есть надежда. Проявленная тобой доблесть доказала, что ты с честью служишь нашему делу. С огромной гордостью я принимаю тебя в ряды народного ополчения. Да воссияет над тобой Свет!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, сейчас не время для пустой болтовни. Если вы все еще хотите показать себя народному ополчению, вам нужно убить членов Братства, о которых я уведомил вас ранее. Возвращайся ко мне, когда выполнишь свой долг.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гриану Камнегриву на Сторожевой холм, что в Западном Крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (15,'Разведка в руднике Горного эха','$n, мои разведчики доносят, что в эти края проникло гораздо больше кобольдов, чем мы рассчитывали. Группа кобольдов-рабочих разбила лагерь близ Рудника Горного Эха к северу отсюда.$B$BОтправляйся к шахте и уничтожь их. Насколько нам известно, кобольдов там много... Убей-ка штук восемь этих тварей, посмотри, сколько еще осталось, и доложи мне.','Уничтожьте 8 кобольдов-рабочих и вернитесь к маршалу Макбрайду.','Меня тревожат сообщения о кобольдах на нашем руднике. К добру это не приведет. Вот, это твоя награда. Когда будешь готова, приходи ко мне. Буду рад, если ты согласишься предпринять еще одну вылазку…','Ты $gбыл:была; в руднике? $gГотов:Готова; доложить об успехах?','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разведка в руднике Горного эха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мои разведчики доносят, что в эти края проникло гораздо больше кобольдов, чем мы рассчитывали. Группа кобольдов-рабочих разбила лагерь близ Рудника Горного Эха к северу отсюда.$B$BОтправляйся к шахте и уничтожь их. Насколько нам известно, кобольдов там много... Убей-ка штук восемь этих тварей, посмотри, сколько еще осталось, и доложи мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 кобольдов-рабочих и вернитесь к маршалу Макбрайду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меня тревожат сообщения о кобольдах на нашем руднике. К добру это не приведет. Вот, это твоя награда. Когда будешь готова, приходи ко мне. Буду рад, если ты согласишься предпринять еще одну вылазку…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gбыл:была; в руднике? $gГотов:Готова; доложить об успехах?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (16,'Жажда Джерарда','Работа фермера тяжела, от нее здорово пересыхает в глотке.$B$BЕсли ты дашь мне родниковой воды, могу предложить кое-что взамен.','Вернитесь к Джерарду Румпелю в Сумеречный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жажда Джерарда',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Работа фермера тяжела, от нее здорово пересыхает в глотке.$B$BЕсли ты дашь мне родниковой воды, могу предложить кое-что взамен.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джерарду Румпелю в Сумеречный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (17,'В Ульдаман за реактивом','Мне рассказали о недавно открытом растении, грибе-малиновике. Этот гриб растет целыми семейками на раскопках Ульдамана. Его можно отыскать в старых туннелях и глубинных, неизведанных зонах. Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься.$B$BОтыщи эти грибы и принеси мне дюжину. Только учти: они могут выпустить облако ядовитых спор, если ты их случайно встряхнешь.$B$BЕсли выполнишь мое поручение, я сделаю для тебя один из моих знаменитых восстановительных эликсиров!','Принесите 12 грибов-малиновиков Гхаку Целителю в Телcамар.','Ты принес грибы-малиновики, которые нужны мне для работы? Нет грибов – нет награды!','Вернитесь к Гхаку Целителю в Телcамар, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Ульдаман за реактивом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне рассказали о недавно открытом растении, грибе-малиновике. Этот гриб растет целыми семейками на раскопках Ульдамана. Его можно отыскать в старых туннелях и глубинных, неизведанных зонах. Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься.$B$BОтыщи эти грибы и принеси мне дюжину. Только учти: они могут выпустить облако ядовитых спор, если ты их случайно встряхнешь.$B$BЕсли выполнишь мое поручение, я сделаю для тебя один из моих знаменитых восстановительных эликсиров!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 грибов-малиновиков Гхаку Целителю в Телcамар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес грибы-малиновики, которые нужны мне для работы? Нет грибов – нет награды!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гхаку Целителю в Телcамар, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (18,'Братство воров','Тут возле Североземья недавно новая воровская шайка завелась. Зовут себя Братством Справедливости. Видели их за рекой, на востоке.$B$BНе знаю, что у них на уме, но наверняка ничего хорошего! Принеси мне их банданы, и в награду получишь оружие.','Принесите 8 красных холщовых бандан заместителю судьи Виллему к Аббатству Североземья.','Ну, $Gдобыл:добыла; мне банданы?','Вернитесь к заместителю судьи Виллему в Долину Североземья, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братство воров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тут возле Североземья недавно новая воровская шайка завелась. Зовут себя Братством Справедливости. Видели их за рекой, на востоке.$B$BНе знаю, что у них на уме, но наверняка ничего хорошего! Принеси мне их банданы, и в награду получишь оружие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 красных холщовых бандан заместителю судьи Виллему к Аббатству Североземья.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, $Gдобыл:добыла; мне банданы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заместителю судьи Виллему в Долину Североземья, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (19,'Тарил\'зун','Вестники и отступники из клана Черной горы постоянно устраивают засады на дороге между городом и крепостью Каменной Стражи. Их предводитель – орк по имени Тарил\'зун. Он уже натворил достаточно дел. Принеси мне его голову!','Принесите маршалу Маррису в Красногорье голову Тарил\'зуна.','Орки Черной горы по-прежнему не дают нам покоя. Избавь нас хотя бы от Тарил\'зуна!','Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тарил\'зун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вестники и отступники из клана Черной горы постоянно устраивают засады на дороге между городом и крепостью Каменной Стражи. Их предводитель – орк по имени Тарил\'зун. Он уже натворил достаточно дел. Принеси мне его голову!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите маршалу Маррису в Красногорье голову Тарил\'зуна.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Орки Черной горы по-прежнему не дают нам покоя. Избавь нас хотя бы от Тарил\'зуна!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (20,'Угроза Черной горы','К нам явились орки Черной горы из Пылающих степей и захватили крепость Каменной стражи. Они грабят области к северу от Озер, и жители тех земель бежали в город, набились в него, словно сельди в бочку.$B$BПомоги Приозерью избавиться от этой угрозы. Перебей орков Черной горы и принеси в доказательство десять иссеченных в бою топоров.$B$BХотя орки теснят нас с севера, до нас доходили вести об их появлении и в юго-восточной части Красногорья. Если встретишь их – убивай без колебаний.','Принесите маршалу Маррису в Приозерье 10 иссеченных в бою топоров.','Что ж, чем меньше орков, тем лучше. Большое тебе спасибо.','Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза Черной горы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К нам явились орки Черной горы из Пылающих степей и захватили крепость Каменной стражи. Они грабят области к северу от Озер, и жители тех земель бежали в город, набились в него, словно сельди в бочку.$B$BПомоги Приозерью избавиться от этой угрозы. Перебей орков Черной горы и принеси в доказательство десять иссеченных в бою топоров.$B$BХотя орки теснят нас с севера, до нас доходили вести об их появлении и в юго-восточной части Красногорья. Если встретишь их – убивай без колебаний.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите маршалу Маррису в Приозерье 10 иссеченных в бою топоров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, чем меньше орков, тем лучше. Большое тебе спасибо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Маррису в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (21,'Схватка у рудника Горного эха','Данные твоей предыдущей разведки подтвердились – на Руднике Горного Эха необходимо провести зачистку. Возвращайся на рудник и помоги очистить его от кобольдов. $B$BВремя дорого, $n. Чем дольше кобольды безнаказанно пробудут в руднике, тем сильнее они закрепятся в Североземье.','Уничтожьте 8 кобольдов-рудокопов и вернитесь к маршалу Макбрайду.','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Схватка у рудника Горного эха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Данные твоей предыдущей разведки подтвердились – на Руднике Горного Эха необходимо провести зачистку. Возвращайся на рудник и помоги очистить его от кобольдов. $B$BВремя дорого, $n. Чем дольше кобольды безнаказанно пробудут в руднике, тем сильнее они закрепятся в Североземье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 кобольдов-рудокопов и вернитесь к маршалу Макбрайду.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Макбрайду в Аббатство Североземья, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (22,'Пирожок из печени кровоклыка','Лук очищен. Чеснок раздавлен. Розмарин измельчен. Основа выпечена. Укроп нарезан. Соус вымешан до гладкости. Все, что мне еще нужно для моего знаменитого пирога – это 8 кусков печени кровоклыка!','Принесите Сальме Сальден 8 кусков печени кровоклыка, чтобы она могла испечь пирог.','Все что мне нужно для моего знаменитого мясного пирога, это 8 кусков печени кровоклыка!','Вернитесь к Сальме Сальден на ферму Сальдена, что в Западном Крае.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пирожок из печени кровоклыка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лук очищен. Чеснок раздавлен. Розмарин измельчен. Основа выпечена. Укроп нарезан. Соус вымешан до гладкости. Все, что мне еще нужно для моего знаменитого пирога – это 8 кусков печени кровоклыка!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Сальме Сальден 8 кусков печени кровоклыка, чтобы она могла испечь пирог.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все что мне нужно для моего знаменитого мясного пирога, это 8 кусков печени кровоклыка!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сальме Сальден на ферму Сальдена, что в Западном Крае.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (23,'Лапа Топтыжня','Принесите лапу Топтыжня капитану Таркану в приют Серебряного Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лапа Топтыжня',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите лапу Топтыжня капитану Таркану в приют Серебряного Ветра.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (25,'А теперь – угомонись','Ты бы это $Gвидел:видела;, |3-6($c)!$b$bЭльфы полагали, что их Приют Серебряного Ветра невозможно захватить. Учитывая, что на их стороне была целая армия водных элементалей, они были правы.$b$bПочти.$b$bОдин из наших магов умудрился призвать злобного элементаля, который обратил остальных в яростных, неуправляемых существ.$b$bХа, жаль, что тебя там не было – какие у них были лица!$b$b<Таркан хохочет.>$b$bОдна проблема – маг, призвавший эту тварь, погиб в бою. Теперь кто-то должен угомонить наше создание.','Истребите 12 злобных элементалей воды и Приливницу на озере Мистраль, после чего вернитесь к капитану Таркану в приют Серебряного Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','А теперь – угомонись',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты бы это $Gвидел:видела;, |3-6($c)!$b$bЭльфы полагали, что их Приют Серебряного Ветра невозможно захватить. Учитывая, что на их стороне была целая армия водных элементалей, они были правы.$b$bПочти.$b$bОдин из наших магов умудрился призвать злобного элементаля, который обратил остальных в яростных, неуправляемых существ.$b$bХа, жаль, что тебя там не было – какие у них были лица!$b$b<Таркан хохочет.>$b$bОдна проблема – маг, призвавший эту тварь, погиб в бою. Теперь кто-то должен угомонить наше создание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Истребите 12 злобных элементалей воды и Приливницу на озере Мистраль, после чего вернитесь к капитану Таркану в приют Серебряного Ветра.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (26,'Необходимый урок','$n, я с удовольствием наблюдал за твоими успехами. Ты непременно станешь $Gзнаменитым защитником:знаменитой защитницей; природы.$B$BПришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который дает тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить с Дендритом Блеском Звезд из Круга Кенария. Он будет твоим наставником.','Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне.','Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нем ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, ее надо заслужить.$B$BТебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика.$B$BГотовься – время испытания пришло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необходимый урок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я с удовольствием наблюдал за твоими успехами. Ты непременно станешь $Gзнаменитым защитником:знаменитой защитницей; природы.$B$BПришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который дает тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить с Дендритом Блеском Звезд из Круга Кенария. Он будет твоим наставником.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нем ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, ее надо заслужить.$B$BТебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика.$B$BГотовься – время испытания пришло.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (27,'Необходимый урок','$n, Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь $Gзнаменитым защитником:знаменитой защитницей; природы.$B$BПришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который дает тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звезд из Круга Кенария. Он будет твоим наставником.','Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне.','Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нем ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, ее надо заслужить.$B$BТебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика.$B$BГотовься – время испытания пришло.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необходимый урок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь $Gзнаменитым защитником:знаменитой защитницей; природы.$B$BПришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий. Об аспекте, который дает тебе власть над водой. Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звезд из Круга Кенария. Он будет твоим наставником.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дендритом Блеском Звезд в селении Ночная Гавань на Лунной поляне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой поклон юному друиду. Пришла пора тебе познать наш водный облик. В нем ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением... Но прежде чем овладеть этой способностью, ее надо заслужить.$B$BТебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды. Второе – испытание твоей решимости познать аспекты самого облика.$B$BГотовься – время испытания пришло.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (28,'Испытание озера','Вот твое первое испытание – исследуй глубины озера Элуне\'ара и найди безделушку святилища. Она быстро разрушается, так что немедля отнеси ее к святилищу Ремула. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны.$B$BНа все испытание тебе дается ограниченное количество времени, и возможно, тебе придется соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха.$B$BУдачи тебе, $n.','Найдите безделушку святилища в озера Элуне\'ара и отнесите ее в святилище Ремула на северо-западе Лунной поляны. Оказавшись там, воспользуйтесь безделушкой.$B$BПотом вам будет нужно поговорить с Таджарри в святилище, чтобы завершить испытание.','Что же, сдается мне, еще один друид успешно прошел Испытание Озера! Хвалю тебя, мой юный друг.$b$bКак я уже сказала, мое имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдал дань уважения этому месту.','Пройдите испытания Озера.','Вернитесь к Таджарри в Святилище Ремула, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание озера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот твое первое испытание – исследуй глубины озера Элуне\'ара и найди безделушку святилища. Она быстро разрушается, так что немедля отнеси ее к святилищу Ремула. Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны.$B$BНа все испытание тебе дается ограниченное количество времени, и возможно, тебе придется соревноваться с другими друидами, которые тоже ищут безделушки. Быстрота ума и ловкость тела помогут тебе добиться успеха.$B$BУдачи тебе, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите безделушку святилища в озера Элуне\'ара и отнесите ее в святилище Ремула на северо-западе Лунной поляны. Оказавшись там, воспользуйтесь безделушкой.$B$BПотом вам будет нужно поговорить с Таджарри в святилище, чтобы завершить испытание.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что же, сдается мне, еще один друид успешно прошел Испытание Озера! Хвалю тебя, мой юный друг.$b$bКак я уже сказала, мое имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище. Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело. Использовав здесь безделушку, ты отдал дань уважения этому месту.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Пройдите испытания Озера.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таджарри в Святилище Ремула, что на Лунной поляне.',`completedtext_loc8`);
