INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (328,'Спрятанный ключ','Хотя в записях нет ни слова о рядовом Торсене, в кожаном переплете одной из книг Ирода обнаруживается маленький латунный ключ.$b$bПовнимательнее изучив записи, вы находите упоминания "надежного сейфа". Этот сейф спрятан внутри Схрона, системы пещер позади поселка Курцена.$B$BЕсли найти его, быть может, удастся разрешить загадку обнаружения Торсена.','Откройте сейф букмекера Ирода маленьким латунным ключом.','Открыв сейф, вы понимаете, что именно здесь Герод хранил самые ценные монеты и прочие вещи.','Сейф окован бронзой. Выглядит он очень прочным и очень тяжелым.','Вернитесь к сейфу букмекера Ирода в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спрятанный ключ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя в записях нет ни слова о рядовом Торсене, в кожаном переплете одной из книг Ирода обнаруживается маленький латунный ключ.$b$bПовнимательнее изучив записи, вы находите упоминания "надежного сейфа". Этот сейф спрятан внутри Схрона, системы пещер позади поселка Курцена.$B$BЕсли найти его, быть может, удастся разрешить загадку обнаружения Торсена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте сейф букмекера Ирода маленьким латунным ключом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Открыв сейф, вы понимаете, что именно здесь Герод хранил самые ценные монеты и прочие вещи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сейф окован бронзой. Выглядит он очень прочным и очень тяжелым.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сейфу букмекера Ирода в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (329,'Шпион найден!','Среди ценностей в сундуке оказывается грязная, торопливо написанная записка. Это сведения о рядовом Торсене – где он патрулирует, с кем он говорит и как проводит время среди повстанцев. Записка подписана лишь одной буквой – М.$B$BЯсно одно, ее автор очень близко знаком с Торсеном, а это значит, что предатель – среди повстанцев.','Отнесите грязную записку лейтенанту Дорену в Лагерь Повстанцев.','Спасибо, $N. Эта записка позволит нам вычислить и уничтожить предателя!','Тебе удалось выяснить, кому была известна тайна Торсена? Среди нас есть предатель?','Поговорите с лейтенантом Дореном в Лагере Повстанцев, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шпион найден!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среди ценностей в сундуке оказывается грязная, торопливо написанная записка. Это сведения о рядовом Торсене – где он патрулирует, с кем он говорит и как проводит время среди повстанцев. Записка подписана лишь одной буквой – М.$B$BЯсно одно, ее автор очень близко знаком с Торсеном, а это значит, что предатель – среди повстанцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите грязную записку лейтенанту Дорену в Лагерь Повстанцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Эта записка позволит нам вычислить и уничтожить предателя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось выяснить, кому была известна тайна Торсена? Среди нас есть предатель?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лейтенантом Дореном в Лагере Повстанцев, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (330,'Расписание дежурств','Принесенная тобой записка подписана просто "-М".. Не пойму, что это значит.$B$BНо... в записке также говорится, что этот человек дежурил вместе с Торсеном на прошлой неделе. Значит, он и есть предатель!$B$BИди к капралу Сетману. Он занимается составлением расписания и скажет, кто дежурил с Торсеном.','Поговорите с капралом Сетманом.','А, да, я могу узнать. Посмотрим... на прошлой неделе…$B$B... Да, с Торсеном дежурил рядовой Мерль. Всю прошлую неделю у них совпадало расписание дежурств.','Поговорите с капралом Сетманом в Лагере Повстанцев, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расписание дежурств',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принесенная тобой записка подписана просто "-М".. Не пойму, что это значит.$B$BНо... в записке также говорится, что этот человек дежурил вместе с Торсеном на прошлой неделе. Значит, он и есть предатель!$B$BИди к капралу Сетману. Он занимается составлением расписания и скажет, кто дежурил с Торсеном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капралом Сетманом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, да, я могу узнать. Посмотрим... на прошлой неделе…$B$B... Да, с Торсеном дежурил рядовой Мерль. Всю прошлую неделю у них совпадало расписание дежурств.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капралом Сетманом в Лагере Повстанцев, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (331,'Доклад Дорену','Не просил ли лейтенант Дорен доложить ему о собранной информации по дежурствам?','Поговорите с лейтенантом Дореном в Лагере повстанцев.','Мне больно слышать, что нас предал Мерль. Он был храбрым солдатом, и мне казалось, что верным. С другой стороны, хорошо, что мы его нашли – с таким шпионом в наших рядах... мы недолго продержались бы против полковника Курцена.','Поговорите с лейтенантом Дореном в Лагере Повстанцев, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доклад Дорену',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не просил ли лейтенант Дорен доложить ему о собранной информации по дежурствам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с лейтенантом Дореном в Лагере повстанцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне больно слышать, что нас предал Мерль. Он был храбрым солдатом, и мне казалось, что верным. С другой стороны, хорошо, что мы его нашли – с таким шпионом в наших рядах... мы недолго продержались бы против полковника Курцена.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с лейтенантом Дореном в Лагере Повстанцев, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (332,'Реклама винного магазина','Если тебя интересует вино, так лучшее вино в Штормграде продает семейство Галлина! Это недалеко – в Торговом квартале, неподалеку от городских каналов.$B$BВозьми этот талон, отнеси его моей сестре Сюзетте и получишь бутылку нашего знаменитого "Даларан нуар". Не пожалеешь!','Отправляйтесь на винокурню Галлины и принесите Сюзетте Галлине талон на вино, чтобы получить бутылку вина бесплатно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реклама винного магазина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если тебя интересует вино, так лучшее вино в Штормграде продает семейство Галлина! Это недалеко – в Торговом квартале, неподалеку от городских каналов.$B$BВозьми этот талон, отнеси его моей сестре Сюзетте и получишь бутылку нашего знаменитого "Даларан нуар". Не пожалеешь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на винокурню Галлины и принесите Сюзетте Галлине талон на вино, чтобы получить бутылку вина бесплатно.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (333,'Харлан нуждается в помощи','Кажется, мы уже встречались. Наверное, насчет покупки брони и походной одежды. Кстати, ожидается суровая зима...$B$BА сегодня меня постигло настоящее огорчение: раскупили всю вязаную одежду. Мне нужна еще одна партия от нашего поставщика.$B$BЕсли ты отнесешь это послание Реме Шнайдер в ателье "Канал", моя признательность будет весьма велика.','Отправляйтесь в магазин одежды в районе каналов и принесите Реме Шнайдер заказ на ткани от Харлана Багли.','Вы принесли весточку от мистера Бэгли?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Харлан нуждается в помощи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, мы уже встречались. Наверное, насчет покупки брони и походной одежды. Кстати, ожидается суровая зима...$B$BА сегодня меня постигло настоящее огорчение: раскупили всю вязаную одежду. Мне нужна еще одна партия от нашего поставщика.$B$BЕсли ты отнесешь это послание Реме Шнайдер в ателье "Канал", моя признательность будет весьма велика.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в магазин одежды в районе каналов и принесите Реме Шнайдер заказ на ткани от Харлана Багли.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы принесли весточку от мистера Бэгли?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (334,'Посылка для Турмана','Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы. Конечно, |3-6($c) вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать...$B$BПрошу вас, $n! Отнесите моему сыну его швейные принадлежности! Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов.','Вы хотите купить одежду?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посылка для Турмана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы. Конечно, |3-6($c) вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать...$B$BПрошу вас, $n! Отнесите моему сыну его швейные принадлежности! Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы хотите купить одежду?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (335,'Благородный напиток','Лорд Вишлок наделал немалого переполоху среди Благородных домов. Он прознал о наших делах и теперь собирается добиться полного расследования. У меня есть план, согласно которому можно занять Вишлока другим делом, но понадобится твоя помощь.$b$bЕсть один цветочек под названием "слеза Тиллоа", он растет в садах Сталвана поблизости от Темнолесья. Еще мне понадобится мускусный корень, который можно найти только у подножия Каменной плотины в Болотине.','Принесите Зардету Черному Когтю слезу Тиллоа из Темнолесья и мускусный корень из Болотины.','Отлично! Это ровно то, что нужно!','Вишлок скоро наберет достаточно сил, чтобы доставить нам кучу неприятностей. Ты уже раздобыл слезу Тиллоа и мускусный корень?','Вернитесь к Зардету Черному Когтю в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благородный напиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лорд Вишлок наделал немалого переполоху среди Благородных домов. Он прознал о наших делах и теперь собирается добиться полного расследования. У меня есть план, согласно которому можно занять Вишлока другим делом, но понадобится твоя помощь.$b$bЕсть один цветочек под названием "слеза Тиллоа", он растет в садах Сталвана поблизости от Темнолесья. Еще мне понадобится мускусный корень, который можно найти только у подножия Каменной плотины в Болотине.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Зардету Черному Когтю слезу Тиллоа из Темнолесья и мускусный корень из Болотины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Это ровно то, что нужно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вишлок скоро наберет достаточно сил, чтобы доставить нам кучу неприятностей. Ты уже раздобыл слезу Тиллоа и мускусный корень?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зардету Черному Когтю в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (336,'Благородный напиток','У лорда Вишлока, как у всех людей, есть свои маленькие слабости. Например, он совсем не дурак выпить. Удивительное лицемерие! Старый ханжа целыми днями сражается с заведениями вроде нашего, а ночи напролет проводит наверху, да еще и не платит по счету. Ну, посмотрим, как ему понравится придуманный мной специально для него напиток: портер "Черный Коготь"! С ног сбивает – точно тебе говорю, $n!$b$bОтнеси ему это пойло и посмотри, придется ли оно лорду по вкусу. Старый хмырь наверняка шатается вокруг Зала просителей.','Отнесите портер "Черный коготь" лорду Вишлоку в Зал просителей.','Спасибо за чудесный портер! Вот, возьми пару монет. А теперь иди прочь и не мешай мне дегустировать!','Ты что, не видишь, как я занят? Я готовлю речь! Я значу очень много для будущего этой державы!$B$BО, а что это у тебя? Похоже на освежающий напиток...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благородный напиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У лорда Вишлока, как у всех людей, есть свои маленькие слабости. Например, он совсем не дурак выпить. Удивительное лицемерие! Старый ханжа целыми днями сражается с заведениями вроде нашего, а ночи напролет проводит наверху, да еще и не платит по счету. Ну, посмотрим, как ему понравится придуманный мной специально для него напиток: портер "Черный Коготь"! С ног сбивает – точно тебе говорю, $n!$b$bОтнеси ему это пойло и посмотри, придется ли оно лорду по вкусу. Старый хмырь наверняка шатается вокруг Зала просителей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите портер "Черный коготь" лорду Вишлоку в Зал просителей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за чудесный портер! Вот, возьми пару монет. А теперь иди прочь и не мешай мне дегустировать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты что, не видишь, как я занят? Я готовлю речь! Я значу очень много для будущего этой державы!$B$BО, а что это у тебя? Похоже на освежающий напиток...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (337,'Старинная историческая книга','Хотя обложка книги исцарапана и заляпана грязью, на корешке все еще можно прочитать заглавие – "История Штормграда". Открыв ее, вы видите на первой странице печать библиотеки Штормграда.$B$BПохоже, кто-то взял почитать эту книгу, да так и не вернул...','Вернуть книгу "История Штормграда" в библиотеку Штормграда.','О небо! Этой книги не видели на полках со времен восстановления Штормграда. Конечно, ее придется реставрировать, она в плохом состоянии, но я с радостью помещу ее в нашу коллекцию редких книг.$B$BБлагодарю вас, господин. Прошу, примите плату за возвращение книги!','О-о-о! Что это у вас за книга? Можно взглянуть?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старинная историческая книга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя обложка книги исцарапана и заляпана грязью, на корешке все еще можно прочитать заглавие – "История Штормграда". Открыв ее, вы видите на первой странице печать библиотеки Штормграда.$B$BПохоже, кто-то взял почитать эту книгу, да так и не вернул...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернуть книгу "История Штормграда" в библиотеку Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О небо! Этой книги не видели на полках со времен восстановления Штормграда. Конечно, ее придется реставрировать, она в плохом состоянии, но я с радостью помещу ее в нашу коллекцию редких книг.$B$BБлагодарю вас, господин. Прошу, примите плату за возвращение книги!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О-о-о! Что это у вас за книга? Можно взглянуть?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (338,'Зеленые холмы Тернистой долины','Господин Эрнестуэй так расстроится, когда узнает об этом!$B$BОн доверил мне рукопись романа "Зеленые холмы Тернистой долины". Все шло хорошо, но по лагерю пронесся сильный порыв ветра и разметал страницы!$B$BБольшую часть мне удалось собрать, но многие страницы унесло в джунгли. Найди все страницы, и мы снова соберем четыре главы.$B$BЯ сам все разложу! Когда соберешь все четыре главы, возвращайся.','Соберите все недостающие страницы романа "Зеленые холмы Тернистой долины". Когда у вас на руках окажутся все четыре главы, верните их Барнилу.','Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зеленые холмы Тернистой долины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Господин Эрнестуэй так расстроится, когда узнает об этом!$B$BОн доверил мне рукопись романа "Зеленые холмы Тернистой долины". Все шло хорошо, но по лагерю пронесся сильный порыв ветра и разметал страницы!$B$BБольшую часть мне удалось собрать, но многие страницы унесло в джунгли. Найди все страницы, и мы снова соберем четыре главы.$B$BЯ сам все разложу! Когда соберешь все четыре главы, возвращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите все недостающие страницы романа "Зеленые холмы Тернистой долины". Когда у вас на руках окажутся все четыре главы, верните их Барнилу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (339,'Глава I','Первая глава была необычайно интересной. Мастер Эрнестуэй предваряет рассказ знакомством со своими товарищами по охоте, в том числе и со мной! $b$bНо речь не об этом. Посмотрим, каких страниц не хватает. Кажется, страницы 1, 4, 6 и 8 все еще в джунглях!','Принесите 1, 4, 6 и 8 страницы книги "Зеленые холмы Тернистой долины" Барнилу Каменному Горшку, чтобы собрать всю первую главу.','Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глава I',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первая глава была необычайно интересной. Мастер Эрнестуэй предваряет рассказ знакомством со своими товарищами по охоте, в том числе и со мной! $b$bНо речь не об этом. Посмотрим, каких страниц не хватает. Кажется, страницы 1, 4, 6 и 8 все еще в джунглях!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1, 4, 6 и 8 страницы книги "Зеленые холмы Тернистой долины" Барнилу Каменному Горшку, чтобы собрать всю первую главу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (340,'Глава II','Вторая глава представляла собой сплошные увлекательные рассказы про охоту на пантер и тигров. Так и хочется самому себе наподдать за то, что упустил страницы!$B$BМне удалось собрать почти все, кроме 10, 11, 14 и 16.','Принесите 10, 11, 14 и 16 страницы книги "Зеленые холмы Тернистой долины" Барнилу Каменному Горшку, чтобы собрать всю вторую главу.','Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глава II',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вторая глава представляла собой сплошные увлекательные рассказы про охоту на пантер и тигров. Так и хочется самому себе наподдать за то, что упустил страницы!$B$BМне удалось собрать почти все, кроме 10, 11, 14 и 16.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10, 11, 14 и 16 страницы книги "Зеленые холмы Тернистой долины" Барнилу Каменному Горшку, чтобы собрать всю вторую главу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (341,'Глава III','Глава III была моей любимой. В ней рассказывается о том, как сэр Эрлджедин и леди Руак впервые подстрелили зверя из дворфийского ружья. А какое захватывающее у нее окончание! $B$BПохоже, нам недостает страниц 18, 20, 21 и 24. Они должны быть где-то неподалеку...','Принесите 18, 20, 21 и 24 страницы книги "Зеленые холмы Тернистой долины" Барнилу Каменному Горшку, чтобы собрать всю третью главу.','Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глава III',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глава III была моей любимой. В ней рассказывается о том, как сэр Эрлджедин и леди Руак впервые подстрелили зверя из дворфийского ружья. А какое захватывающее у нее окончание! $B$BПохоже, нам недостает страниц 18, 20, 21 и 24. Они должны быть где-то неподалеку...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 18, 20, 21 и 24 страницы книги "Зеленые холмы Тернистой долины" Барнилу Каменному Горшку, чтобы собрать всю третью главу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (342,'Глава IV','А, Глава IV, захватывающий финал! И как она закончилась! $b$bНам не хватает всего лишь трех страниц этой главы. А именно – 25, 26 и 27. Стоит найти их – и последняя глава готова.','Принесите 25, 26 и 27 страницы книги "Зеленые холмы Тернистой долины" Барнилу Каменному Горшку, чтобы собрать всю четвертую главу.','Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глава IV',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, Глава IV, захватывающий финал! И как она закончилась! $b$bНам не хватает всего лишь трех страниц этой главы. А именно – 25, 26 и 27. Стоит найти их – и последняя глава готова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 25, 26 и 27 страницы книги "Зеленые холмы Тернистой долины" Барнилу Каменному Горшку, чтобы собрать всю четвертую главу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Барнилу Каменному Горшку в лагерь Экспедиции Эрнестуэя, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (343,'Кстати, о стойкости духа','Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, "Как закалялось железо". Копия этой книги должна быть в Королевской библиотеке крепости Штормграда. Не могли бы вы заказать ее для меня? Да осенит вас благодать Света!$B$BКоролевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев. Поговорите с ним, он принесет для вас книгу.','Отправляйтесь в Королевскую библиотеку крепости Штормграда и поговорите с Милтоном Снопом. Он даст вам книгу по металлургии, которая интересует брата Кристофа.','Металлургия? Да, конечно, у нас много книг по данной отрасли знаний, и мы будем рады помочь брату Кристофу в подготовке лекции! Какая же книга его интересует?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кстати, о стойкости духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, "Как закалялось железо". Копия этой книги должна быть в Королевской библиотеке крепости Штормграда. Не могли бы вы заказать ее для меня? Да осенит вас благодать Света!$B$BКоролевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев. Поговорите с ним, он принесет для вас книгу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Королевскую библиотеку крепости Штормграда и поговорите с Милтоном Снопом. Он даст вам книгу по металлургии, которая интересует брата Кристофа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Металлургия? Да, конечно, у нас много книг по данной отрасли знаний, и мы будем рады помочь брату Кристофу в подготовке лекции! Какая же книга его интересует?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (344,'Брат Пакстон','"Как закалялось железо"? Конечно, я знаю такую книгу. Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном. Он много времени провел в горах Каз Модана, добывая руду. Отличный парень!$B$BНо о чем это я? Ах, да... "Как закалялось железо"! Боюсь, что книга отправилась в Аббатство Североземья. Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с нее копию для своей коллекции.$B$BУж сколько тому месяцев минуло... Интересно, почему он ее задерживает.','Поговорите с братом Пакстоном из Аббатства Североземья.','Коллега Шиф потерял свою книгу? Мда, неловко вышло... Книга действительно у меня, но я не закончил ее переписывать, так что мне пока что нужен оригинал!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брат Пакстон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Как закалялось железо"? Конечно, я знаю такую книгу. Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном. Он много времени провел в горах Каз Модана, добывая руду. Отличный парень!$B$BНо о чем это я? Ах, да... "Как закалялось железо"! Боюсь, что книга отправилась в Аббатство Североземья. Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с нее копию для своей коллекции.$B$BУж сколько тому месяцев минуло... Интересно, почему он ее задерживает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с братом Пакстоном из Аббатства Североземья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Коллега Шиф потерял свою книгу? Мда, неловко вышло... Книга действительно у меня, но я не закончил ее переписывать, так что мне пока что нужен оригинал!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (345,'Запас чернил','Я как раз собирался закончить свою работу над копией "Как закалялось железо", но...$B$BЯ пользуюсь только чернилами своего собственного изготовления. Они не текут, не выцветают и очень быстро сохнут. Увы, высыхают они тоже слишком быстро! Последняя моя бутылка чернил никуда не годится, а я еще не успел закончить работу... и сделать еще чернил я не могу!$B$BДля изготовления чернил мне нужна ретбанская руда из Красногорья. Старшина Ослоу из Приозерья – мой верный поставщик...','Поговорите со старшиной Ослоу из Приозерья и расспросите его о ретбанской руде.','Чего тебе надо? Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозерье латаем после нападения орков. Если тебе сдалась ретбанская руда, добудь ее $Gсам:сама;!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запас чернил',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я как раз собирался закончить свою работу над копией "Как закалялось железо", но...$B$BЯ пользуюсь только чернилами своего собственного изготовления. Они не текут, не выцветают и очень быстро сохнут. Увы, высыхают они тоже слишком быстро! Последняя моя бутылка чернил никуда не годится, а я еще не успел закончить работу... и сделать еще чернил я не могу!$B$BДля изготовления чернил мне нужна ретбанская руда из Красногорья. Старшина Ослоу из Приозерья – мой верный поставщик...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со старшиной Ослоу из Приозерья и расспросите его о ретбанской руде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чего тебе надо? Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозерье латаем после нападения орков. Если тебе сдалась ретбанская руда, добудь ее $Gсам:сама;!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (346,'Возвращение к Кристофу','Я закончил перепись и могу вернуть оригинал "Как закалялось железо". Спасибо за помощь, и передай, пожалуйста, Милтону мои извинения за долгую задержку.','Вернитесь к брату Кристофу на Соборную площадь. Отдайте ему книгу "Как закалялось железо".','Тебе удалось найти книгу?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Кристофу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я закончил перепись и могу вернуть оригинал "Как закалялось железо". Спасибо за помощь, и передай, пожалуйста, Милтону мои извинения за долгую задержку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к брату Кристофу на Соборную площадь. Отдайте ему книгу "Как закалялось железо".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти книгу?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (347,'Ретбанская руда','Ретбанская руда получила свое название по имени первооткрывателя, Барта Ретбана. Выплавленный металл мягче железа, но руда имеет приятный темный цвет, и многие переписчики используют ее для изготовления чернил. Добыть руду можно в пещерах Ретбана к северу отсюда.$B$BК сожалению, постоянные нападения орков отвлекают нас от добычи руды, и запасы наши иссякли. Скажу тебе еще вот что... Красногорские гноллы недавно поселились в пещерах Ретбана, и их работяги как раз добывают там руду.$B$BТак что если тебе нужна руда... ты знаешь, как добыть ее.','Добудьте 5 кусков ретбанской руды и принесите их брату Пакстону в библиотеку Североземского аббатства.','Как там моя ретбанская руда?','Вернитесь к брату Пакстону в Долину Североземья, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ретбанская руда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ретбанская руда получила свое название по имени первооткрывателя, Барта Ретбана. Выплавленный металл мягче железа, но руда имеет приятный темный цвет, и многие переписчики используют ее для изготовления чернил. Добыть руду можно в пещерах Ретбана к северу отсюда.$B$BК сожалению, постоянные нападения орков отвлекают нас от добычи руды, и запасы наши иссякли. Скажу тебе еще вот что... Красногорские гноллы недавно поселились в пещерах Ретбана, и их работяги как раз добывают там руду.$B$BТак что если тебе нужна руда... ты знаешь, как добыть ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 кусков ретбанской руды и принесите их брату Пакстону в библиотеку Североземского аббатства.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там моя ретбанская руда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к брату Пакстону в Долину Североземья, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (348,'Лихорадка Тернистой долины','Плохо... Мне... т-т-ак п-п-лохо.$B$BЯ п-подцепил... лихорадку Тернистой д-долины... Это смертельный вирус...$B$BЕдинственное лекарство... съесть сердце М-м-м-мок-ка Д-дикаря... неуловимой... белой гориллы...$B$BИщи знахаря Унбагва в с-с-скрытой пещере на южном мысу...$B$BПоспеши... я... умираю...','Найдите знахаря Унбагва и попросите его вызвать Мокка Дикаря. Принесите сердце Мокка Фину Горемыку.','Вернитесь к Фину Горемыку в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лихорадка Тернистой долины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плохо... Мне... т-т-ак п-п-лохо.$B$BЯ п-подцепил... лихорадку Тернистой д-долины... Это смертельный вирус...$B$BЕдинственное лекарство... съесть сердце М-м-м-мок-ка Д-дикаря... неуловимой... белой гориллы...$B$BИщи знахаря Унбагва в с-с-скрытой пещере на южном мысу...$B$BПоспеши... я... умираю...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите знахаря Унбагва и попросите его вызвать Мокка Дикаря. Принесите сердце Мокка Фину Горемыку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фину Горемыку в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (349,'Лихорадка Тернистой долины','врем текст 02 – описание','врем текст 02 – протокол','Вернитесь к знахарю Унбагве в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лихорадка Тернистой долины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','врем текст 02 – описание',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','врем текст 02 – протокол',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Унбагве в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (350,'Помощь старого друга','Марзон наверняка поддерживает контакт с Братством Справедливости, и у него есть выход на Лесковара...$B$BТеперь, когда ван Клиф и Тредд погибли, Лесковара будет нелегко посадить на скамью подсудимых, потому что без их показаний твое свидетельство ничего не будет значить; стоит также принять во внимание благородное происхождение и хорошие связи Лесковара. Ему, в сущности, наплевать на закон.$B$BТебе понадобится помощь. Я, увы, оказать ее не могу, но знаю того, кто может нам помочь. Найди Триаса в Торговом квартале.','Поговорите с Иллингом Триасом в Штормграде.','Опять Шоу?! Совести у него нет!..$B$BБратство Справедливости, говорите? Да вы просто мешок с хорошими новостями! Скажите еще, что Смертокрыл воскрес и напал на город...$B$BНу, ладно, выкладывайте все по порядку. И не пропускайте ни единой детали. Я хочу знать все.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь старого друга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Марзон наверняка поддерживает контакт с Братством Справедливости, и у него есть выход на Лесковара...$B$BТеперь, когда ван Клиф и Тредд погибли, Лесковара будет нелегко посадить на скамью подсудимых, потому что без их показаний твое свидетельство ничего не будет значить; стоит также принять во внимание благородное происхождение и хорошие связи Лесковара. Ему, в сущности, наплевать на закон.$B$BТебе понадобится помощь. Я, увы, оказать ее не могу, но знаю того, кто может нам помочь. Найди Триаса в Торговом квартале.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Иллингом Триасом в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Опять Шоу?! Совести у него нет!..$B$BБратство Справедливости, говорите? Да вы просто мешок с хорошими новостями! Скажите еще, что Смертокрыл воскрес и напал на город...$B$BНу, ладно, выкладывайте все по порядку. И не пропускайте ни единой детали. Я хочу знать все.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`) VALUES (351,'Вы находите какой-то странный яйцевидный металлический предмет. Повозившись с кнопками, вы пробуждаете яйцо, и оно превращается в гномский робот! Изнутри доносится голос.$b$b"Меня зовут Карлс, и мой автономный робот потерялся! За его находку полагается награда! Прошу, отнесите этот маяк к роботу. Я уже вычислил координаты. Он сломался возле Зияющей бездны в Танарисе".','Отнесите аварийный маяк к автономному роботу Карлса.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы находите какой-то странный яйцевидный металлический предмет. Повозившись с кнопками, вы пробуждаете яйцо, и оно превращается в гномский робот! Изнутри доносится голос.$b$b"Меня зовут Карлс, и мой автономный робот потерялся! За его находку полагается награда! Прошу, отнесите этот маяк к роботу. Я уже вычислил координаты. Он сломался возле Зияющей бездны в Танарисе".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите аварийный маяк к автономному роботу Карлса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (352,'<UNUSED>','Great Mammoda. Enormous, she was, with claws and teeth like swords. Now, I was caught off my guard, but I don\'t think being ready would have helped my cause much. One swipe and poof! Darkness. They say I\'m lucky to walk now...$b$bWell, not much enjoyment to be had in hearing that old story now, is there? Anyways, $n, if you\'d like to try yourself against her, the Lady of the Loch,') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Great Mammoda. Enormous, she was, with claws and teeth like swords. Now, I was caught off my guard, but I don\'t think being ready would have helped my cause much. One swipe and poof! Darkness. They say I\'m lucky to walk now...$b$bWell, not much enjoyment to be had in hearing that old story now, is there? Anyways, $n, if you\'d like to try yourself against her, the Lady of the Loch,',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (353,'Посылка для Грозовой Вершины','Грозовая Вершина – уважаемый клан дворфов, известный своими изысканными и утонченными вкусами. Неудивительно, что Грингер Грозовая Вершина, горный пехотинец Стальгорна, обратился ко мне, когда ему понадобилось оружие.$B$BЗаказ выполнен, но Грингер служит далеко отсюда, в Лок Модане. Если вы собираетесь на север, не возьметесь ли доставить груз?$b$BПо моим последним данным, горный пехотинец Грозовая Вершина остановился в северной сторожевой башне в Лок Модане.','Доставьте посылку горному пехотинцу Грозовой Вершине в Лок Модан.','Вы прибыли прямиком из Штормграда? Я слышал, что в человечьих землях обострилась ситуация с орками и грабителями. Там сейчас можно неплохо подзаработать – правда, |3-6($c)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посылка для Грозовой Вершины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грозовая Вершина – уважаемый клан дворфов, известный своими изысканными и утонченными вкусами. Неудивительно, что Грингер Грозовая Вершина, горный пехотинец Стальгорна, обратился ко мне, когда ему понадобилось оружие.$B$BЗаказ выполнен, но Грингер служит далеко отсюда, в Лок Модане. Если вы собираетесь на север, не возьметесь ли доставить груз?$b$BПо моим последним данным, горный пехотинец Грозовая Вершина остановился в северной сторожевой башне в Лок Модане.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте посылку горному пехотинцу Грозовой Вершине в Лок Модан.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы прибыли прямиком из Штормграда? Я слышал, что в человечьих землях обострилась ситуация с орками и грабителями. Там сейчас можно неплохо подзаработать – правда, |3-6($c)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (354,'Смерти в семье','Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... еще до чумы.$B$BКогда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону. А мы были дураками, но дураками преданными...$B$BИз-за гордыни Агамондов мы стали нежитью, а сами они служат Плети!$B$BСослужи Отрекшимся службу – убей Агамондов, ставших жертвами Чумы, и принеси мне их останки.','Принесите останки Грегора, останки Ниссы и останки Тармена Колману Фартингу в Брилл.','Месть сладка, не правда ли? Ты заметил хоть какие-то признаки свободной воли в Агамондах, когда убивал их? Надеюсь, что да. Надеюсь, они почувствовали страх, прежде чем упокоились навсегда.\n\nКонечно, глупо на это надеяться, но тем не менее.','Ты принес останки Агамондов? Эти проклятые твари уничтожены?','Вернитесь к Колману Фартингу в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерти в семье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... еще до чумы.$B$BКогда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону. А мы были дураками, но дураками преданными...$B$BИз-за гордыни Агамондов мы стали нежитью, а сами они служат Плети!$B$BСослужи Отрекшимся службу – убей Агамондов, ставших жертвами Чумы, и принеси мне их останки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите останки Грегора, останки Ниссы и останки Тармена Колману Фартингу в Брилл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Месть сладка, не правда ли? Ты заметил хоть какие-то признаки свободной воли в Агамондах, когда убивал их? Надеюсь, что да. Надеюсь, они почувствовали страх, прежде чем упокоились навсегда.\n\nКонечно, глупо на это надеяться, но тем не менее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес останки Агамондов? Эти проклятые твари уничтожены?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колману Фартингу в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (355,'Разговор с Севреном','Ты $gпринес:принесла; мне останки Агамондов и $gутолил:утолила; мою жажду мести. Но мельницы этой проклятой семейки все еще представляют собой угрозу не только для меня, но и для всех Отрекшихся.$B$BЯ рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично.','Поговорите с мировым судьей Севреном в Брилле.','Да?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Севреном',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпринес:принесла; мне останки Агамондов и $gутолил:утолила; мою жажду мести. Но мельницы этой проклятой семейки все еще представляют собой угрозу не только для меня, но и для всех Отрекшихся.$B$BЯ рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мировым судьей Севреном в Брилле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (356,'Патруль в арьергарде','Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них.$B$BНаш успех на Бастионе рассчитан на битву на один фронт: мы не можем допустить атаки с тыла и, уж конечно, не можем лишить наших защитников линии поставки припасов.$B$BОтправляйся на запад и убей любого приспешника Плети, которого встретишь. Обрати особое внимание на усадьбу Балнира – там настоящее гнездо этой Плети.','Убейте 8 кровоточащих ужасов и 8 странствующих духов.','Очень хорошо. Благодаря вашим усилиям Плеть еще долго не осмелится сунуться сюда. Я отправлю лестный отзыв моему начальнику, исполнителю Зуганду.','Будь у меня моя верная винтовка, вы были бы уже мертвы, |3-6($C)! Погодите, скоро мне на помощь приедет бригада паровых танков!','Вернитесь к верховному палачу Деррингтону в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Патруль в арьергарде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них.$B$BНаш успех на Бастионе рассчитан на битву на один фронт: мы не можем допустить атаки с тыла и, уж конечно, не можем лишить наших защитников линии поставки припасов.$B$BОтправляйся на запад и убей любого приспешника Плети, которого встретишь. Обрати особое внимание на усадьбу Балнира – там настоящее гнездо этой Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 кровоточащих ужасов и 8 странствующих духов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Благодаря вашим усилиям Плеть еще долго не осмелится сунуться сюда. Я отправлю лестный отзыв моему начальнику, исполнителю Зуганду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будь у меня моя верная винтовка, вы были бы уже мертвы, |3-6($C)! Погодите, скоро мне на помощь приедет бригада паровых танков!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Деррингтону в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (357,'Личность лича','На острове посреди озера Ясноводного, что к северу отсюда, обитает лич. Сам он – свободный Отрекшийся, но считает, что мы, да и вся остальная нежить, до сих пор находимся под контролем Плети, и велел своим прислужникам атаковать любого, кто приблизится.$B$BНо раз он Отрекшийся, он понадобится Королеве. А если он еще и специалист в некромантии, то его умения нам... весьма пригодятся.$B$BЧтобы понять, кто он и что умеет, мне нужно заглянуть в его книгу заклинаний. Прокрадись в его лагерь, достань ее, и принеси мне.','Принесите книгу лича Бетору Ледострелу в Подгород.','Вернитесь к Бетору Ледострелу в Тирисфальские леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Личность лича',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На острове посреди озера Ясноводного, что к северу отсюда, обитает лич. Сам он – свободный Отрекшийся, но считает, что мы, да и вся остальная нежить, до сих пор находимся под контролем Плети, и велел своим прислужникам атаковать любого, кто приблизится.$B$BНо раз он Отрекшийся, он понадобится Королеве. А если он еще и специалист в некромантии, то его умения нам... весьма пригодятся.$B$BЧтобы понять, кто он и что умеет, мне нужно заглянуть в его книгу заклинаний. Прокрадись в его лагерь, достань ее, и принеси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книгу лича Бетору Ледострелу в Подгород.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бетору Ледострелу в Тирисфальские леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (358,'Грабители могил','Братские могилы к юго-западу от Фермы Гаррена были вырыты, чтобы справиться с... внушительным количеством смертей в Тирисфале после прихода Чумы.$B$BТела в этих могилах еще не превратились в нежить, но теперь Плеть подослала гноллов-гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии. Это недопустимо!$B$BУ тебя будет два задания: убить гноллов-гнилошкуров возле братских могил и Фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь.','Убивайте грабителей могил и полукровок из стаи Гнилошкуров.$B$BПринесите мировому судье Севрену 8 образцов бальзамирующей лимфы.','Ты сделал то, о чем я просил? Убил этих псов и забрал у них лимфу?','Вернитесь к мировому судье Севрену в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грабители могил',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Братские могилы к юго-западу от Фермы Гаррена были вырыты, чтобы справиться с... внушительным количеством смертей в Тирисфале после прихода Чумы.$B$BТела в этих могилах еще не превратились в нежить, но теперь Плеть подослала гноллов-гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии. Это недопустимо!$B$BУ тебя будет два задания: убить гноллов-гнилошкуров возле братских могил и Фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте грабителей могил и полукровок из стаи Гнилошкуров.$B$BПринесите мировому судье Севрену 8 образцов бальзамирующей лимфы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты сделал то, о чем я просил? Убил этих псов и забрал у них лимфу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Севрену в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (359,'Обязанности Отрекшихся','Мне нужен свежий отчет с восточной базы наших стражей смерти.$B$BЯ хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль. На границе с Чумными землями нужно постоянно смотреть в оба! Нельзя, чтобы Плеть устроила здесь еще одну крепость.$B$BИди по дороге на юг, а на развилке сверни на восток, к базе. Поговори со стражем смерти Линнеей, у нее есть вся нужная мне информация.','Поговорите со стражем смерти Линнеей.','Севрену нужен отчет? Ну что же, защитники Бастиона сдерживают силы Плети, но часть из них все же проникает время от времени.\n\nПлеть видели к востоку от нашей базы, возле Усадьбы Балнира.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обязанности Отрекшихся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужен свежий отчет с восточной базы наших стражей смерти.$B$BЯ хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль. На границе с Чумными землями нужно постоянно смотреть в оба! Нельзя, чтобы Плеть устроила здесь еще одну крепость.$B$BИди по дороге на юг, а на развилке сверни на восток, к базе. Поговори со стражем смерти Линнеей, у нее есть вся нужная мне информация.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со стражем смерти Линнеей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Севрену нужен отчет? Ну что же, защитники Бастиона сдерживают силы Плети, но часть из них все же проникает время от времени.\n\nПлеть видели к востоку от нашей базы, возле Усадьбы Балнира.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (360,'Возвращение к мировому судье','Теперь возвращайся к мировому судье Севрену с той информацией, что я дала вам. Он очень ждет ее, так что поспеши.$B$BА если встретишь по пути приспешников Плети – немедленно убей их! Нечего им шастать по нашим землям.','Вернитесь к мировому судье Севрену в Брилл.','Неприятно слышать, что Плеть просачивается через Бастион. Король-лич и его слуги не собираются сдаваться.\n\nНо и мы не уступим. Мы не позволим ему захватить нас снова!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к мировому судье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь возвращайся к мировому судье Севрену с той информацией, что я дала вам. Он очень ждет ее, так что поспеши.$B$BА если встретишь по пути приспешников Плети – немедленно убей их! Нечего им шастать по нашим землям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к мировому судье Севрену в Брилл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неприятно слышать, что Плеть просачивается через Бастион. Король-лич и его слуги не собираются сдаваться.\n\nНо и мы не уступим. Мы не позволим ему захватить нас снова!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (361,'Недоставленное письмо','Это письмо, написанное Тарменом, старшим сыном Грегора Агамонда. Оно адресовано Иветте Фартинг, но, похоже, так до нее и не добралось...','Найдите Иветту Фартинг и вручите ей письмо от Тармена Агамонда.','О... мой бедный Тармен! Я ведь просила его уйти с этих мельниц со мной и моим отцом, но его преданность семье оказалась сильнее... Так я и знала! Я знала, что Брэнд желает ему зла! Будь прокляты эти Чума и Плеть!\n\nЛицо Иветты смягчается.\n\nНо стенания – удел слабых. Я Отрекшаяся, у меня есть свои цели, и любовь не входит в их число. Спасибо за то, что принесли мне письмо от некогда любимого человека, теперь я хотя бы знаю, что с ним сталось.\n\nНо та жизнь для меня окончена. Навсегда.','Да?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недоставленное письмо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это письмо, написанное Тарменом, старшим сыном Грегора Агамонда. Оно адресовано Иветте Фартинг, но, похоже, так до нее и не добралось...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Иветту Фартинг и вручите ей письмо от Тармена Агамонда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О... мой бедный Тармен! Я ведь просила его уйти с этих мельниц со мной и моим отцом, но его преданность семье оказалась сильнее... Так я и знала! Я знала, что Брэнд желает ему зла! Будь прокляты эти Чума и Плеть!\n\nЛицо Иветты смягчается.\n\nНо стенания – удел слабых. Я Отрекшаяся, у меня есть свои цели, и любовь не входит в их число. Спасибо за то, что принесли мне письмо от некогда любимого человека, теперь я хотя бы знаю, что с ним сталось.\n\nНо та жизнь для меня окончена. Навсегда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (362,'Мельницы с привидениями','Девлин Агамонд был младшим из двух сыновей в семье, и более непохожих братьев найти было невозможно. Тармен был высоким и учтивым, а его младший брат – слабым и острым на язык.$B$BКогда Мельницы Агамондов пали во время нашествия Чумы, я не удивился, услышав, что Девлин погиб одним из первых. На дороге, ведущей к Мельницам Агамондов, до сих пор можно услышать его безумное бормотание.$B$BЯ собираю останки Агамондов, и для полной коллекции мне не хватает лишь бедного Девлина. Найди его, уничтожь и принеси мне его кости.','Убейте Девлина Агамонда и принесите его останки Колману Фартингу в Брилл.','Спасибо. Кости Девлина станут отличным украшением для моего плаща.\n\nЕсли что-то может согреть мое холодное сердце, то это мысль о том, что Агамондов больше нет. Они предали меня и мою семью, когда пришла Чума – а теперь я клянусь, что растопчу их кости ногами!','Ты нашел Девлина?','Вернитесь к Колману Фартингу в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мельницы с привидениями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Девлин Агамонд был младшим из двух сыновей в семье, и более непохожих братьев найти было невозможно. Тармен был высоким и учтивым, а его младший брат – слабым и острым на язык.$B$BКогда Мельницы Агамондов пали во время нашествия Чумы, я не удивился, услышав, что Девлин погиб одним из первых. На дороге, ведущей к Мельницам Агамондов, до сих пор можно услышать его безумное бормотание.$B$BЯ собираю останки Агамондов, и для полной коллекции мне не хватает лишь бедного Девлина. Найди его, уничтожь и принеси мне его кости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Девлина Агамонда и принесите его останки Колману Фартингу в Брилл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо. Кости Девлина станут отличным украшением для моего плаща.\n\nЕсли что-то может согреть мое холодное сердце, то это мысль о том, что Агамондов больше нет. Они предали меня и мою семью, когда пришла Чума – а теперь я клянусь, что растопчу их кости ногами!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел Девлина?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колману Фартингу в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (363,'Резкое пробуждение','Ты вовремя $gпришел:пришла; в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи. $b$bМеня зовут Мордо, я смотритель склепа Похоронного Звона. А ты больше не $gраб:рабыня; Короля-лича. $b$bПоговори с жрецом Тени Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать.$B$BЧтобы выбраться из склепа, поднимайся наверх по ступенькам. Затем следуй вниз по дороге, пока не найдешь часовню.','Поговорите с жрецом Тени Сарвисом.','А, еще один живой мертвец! Должно быть, это настоящий шок – очнуться в склепе, в котором тебя встречает лишь холод... и Мордо. \n\nЯ все это читаю по твоему лицу. Позволь мне объяснить тебе наше... эээ... положение. \n\nНас освободила из-под контроля Короля-лича наша новая предводительница, Леди Сильвана. Темная Госпожа руководит нами в войне против ненавистной армии Плети и цепляющихся за эту землю людей, преследующих нас, словно ищейки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Резкое пробуждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты вовремя $gпришел:пришла; в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи. $b$bМеня зовут Мордо, я смотритель склепа Похоронного Звона. А ты больше не $gраб:рабыня; Короля-лича. $b$bПоговори с жрецом Тени Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать.$B$BЧтобы выбраться из склепа, поднимайся наверх по ступенькам. Затем следуй вниз по дороге, пока не найдешь часовню.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с жрецом Тени Сарвисом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, еще один живой мертвец! Должно быть, это настоящий шок – очнуться в склепе, в котором тебя встречает лишь холод... и Мордо. \n\nЯ все это читаю по твоему лицу. Позволь мне объяснить тебе наше... эээ... положение. \n\nНас освободила из-под контроля Короля-лича наша новая предводительница, Леди Сильвана. Темная Госпожа руководит нами в войне против ненавистной армии Плети и цепляющихся за эту землю людей, преследующих нас, словно ищейки.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (364,'Безмозглые твари','C тех пор, как первый Отрекшийся выполз из своей могилы, мы безостановочно ведем войну с армией Короля-лича. Проклятые мертвецы, мерзкие твари с севера, извращенные создания!$b$bХотя Король-лич больше не восседает на Ледяном троне, северная часть деревни все еще находится под осадой его рабов. Уничтожь их, не щади никого, кем бы они тебе не казались. Это больше не твои павшие братья и сестры.','Убейте 5 безмозглых зомби и 5 презренных вурдалаков.','Жаль, что нельзя привлечь Плеть на нашу сторону, ее несметные полчища пришлись бы как нельзя кстати в предстоящих битвах. \n\nНо так как договориться с ними нельзя, нам остается лишь уничтожить их.','В этой новой жизни ты далеко не продвинешься, если не в состоянии убить даже самых слабеньких зомби, $N. И не возвращайся, пока не сможешь доложить об успешном выполнении.','Вернитесь к жрецу Тени Сарвису в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безмозглые твари',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','C тех пор, как первый Отрекшийся выполз из своей могилы, мы безостановочно ведем войну с армией Короля-лича. Проклятые мертвецы, мерзкие твари с севера, извращенные создания!$b$bХотя Король-лич больше не восседает на Ледяном троне, северная часть деревни все еще находится под осадой его рабов. Уничтожь их, не щади никого, кем бы они тебе не казались. Это больше не твои павшие братья и сестры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 безмозглых зомби и 5 презренных вурдалаков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жаль, что нельзя привлечь Плеть на нашу сторону, ее несметные полчища пришлись бы как нельзя кстати в предстоящих битвах. \n\nНо так как договориться с ними нельзя, нам остается лишь уничтожить их.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В этой новой жизни ты далеко не продвинешься, если не в состоянии убить даже самых слабеньких зомби, $N. И не возвращайся, пока не сможешь доложить об успешном выполнении.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрецу Тени Сарвису в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (365,'Поля Горя','Кто это тут? $gНовенький:Новенькая:c; |3-6($c)? Если хочешь проявить себя перед Темной Госпожой, придется следовать обычаям Отрекшихся.$B$BК западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв.$B$BКак наберешь десяток, отнеси их аптекарю Юхану в Брилл.','Украдите 10 тыкв с западной фермы, к северу от Похоронного Звона. Потом отнесите эти тыквы аптекарю Юхану в Брилл.','Ты хорошо справился с заданием, |3-6($C), и тем самым доказал, что достоин примкнуть к армии Темной Госпожи.','Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поля Горя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто это тут? $gНовенький:Новенькая:c; |3-6($c)? Если хочешь проявить себя перед Темной Госпожой, придется следовать обычаям Отрекшихся.$B$BК западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу. К тому же Алый орден постоянно ходит дозором возле своей башни. Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв.$B$BКак наберешь десяток, отнеси их аптекарю Юхану в Брилл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите 10 тыкв с западной фермы, к северу от Похоронного Звона. Потом отнесите эти тыквы аптекарю Юхану в Брилл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хорошо справился с заданием, |3-6($C), и тем самым доказал, что достоин примкнуть к армии Темной Госпожи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (366,'Книга Гюнтера','Давным-давно Гюнтер, я и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана.$B$BМы с Гюнтером оба пали жертвами Чумы, но я полагал, что он так и сгинул в небытие или встал под знамена Короля-лича. Я рад, что он остался свободным.$B$BМы должны привлечь его на свою сторону. Я наложил на эту книгу заклинание, которое докажет ему, что я тоже свободен от Короля-лича. Надеюсь, что, убедившись в этом, он станет одним из нас.','Верните Гюнтеру книгу заклинаний. Его можно найти на острове, в приюте Гюнтера.','Моя книга?! Так это ты украл ее!\n\nНо... что это за новые чары на ней... Бетор? Он в Лордероне?\n\nЕсли он все еще "жив", то, может быть, ему тоже удалось вырваться из холодных объятий Короля-лича...','Твои хозяева глупцы! Незачем было подсылать тебя. Я никогда не стану рабом Плети!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Книга Гюнтера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно Гюнтер, я и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана.$B$BМы с Гюнтером оба пали жертвами Чумы, но я полагал, что он так и сгинул в небытие или встал под знамена Короля-лича. Я рад, что он остался свободным.$B$BМы должны привлечь его на свою сторону. Я наложил на эту книгу заклинание, которое докажет ему, что я тоже свободен от Короля-лича. Надеюсь, что, убедившись в этом, он станет одним из нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Гюнтеру книгу заклинаний. Его можно найти на острове, в приюте Гюнтера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моя книга?! Так это ты украл ее!\n\nНо... что это за новые чары на ней... Бетор? Он в Лордероне?\n\nЕсли он все еще "жив", то, может быть, ему тоже удалось вырваться из холодных объятий Короля-лича...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твои хозяева глупцы! Незачем было подсылать тебя. Я никогда не стану рабом Плети!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (367,'Новая чума','Леди Сильвана обратилась к Королевскому фармацевтическому обществу. Темная Госпожа считает, что при помощи наших знаний и новейшей магии мы сумеем найти ключ к свержению Артаса. Она хочет, чтобы мы вывели новую чуму – смертоноснее любой болезни Азерота, чтобы она уничтожила всю армию Артаса.$B$BВ своих изысканиях я обнаружил, что для этого потребуется кровь животных. Принесите мне 5 склянок крови пса Тьмы, чтобы я мог провести эксперимент.','Принесите аптекарю Юхану 5 склянок крови псов Тьмы.','Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая чума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Леди Сильвана обратилась к Королевскому фармацевтическому обществу. Темная Госпожа считает, что при помощи наших знаний и новейшей магии мы сумеем найти ключ к свержению Артаса. Она хочет, чтобы мы вывели новую чуму – смертоноснее любой болезни Азерота, чтобы она уничтожила всю армию Артаса.$B$BВ своих изысканиях я обнаружил, что для этого потребуется кровь животных. Принесите мне 5 склянок крови пса Тьмы, чтобы я мог провести эксперимент.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите аптекарю Юхану 5 склянок крови псов Тьмы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (368,'Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (369,'Новая чума','Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в котором сказано, что древняя чума унесла тысячи невинных жизней. Позже открыли, что возбудитель болезни сохранился благодаря яду ночных кругопрядов.$B$BПринесите мне немного яда злобных ночных кругопрядов, чтобы я мог закончить эксперимент. Хочу посмотреть, как среагирует ядовитый элемент с моим новым составом. Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах.','Принесите Аптекарю Юхану из города Брилл 4 образца яда злобного ночного кругопряда.','Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая чума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в котором сказано, что древняя чума унесла тысячи невинных жизней. Позже открыли, что возбудитель болезни сохранился благодаря яду ночных кругопрядов.$B$BПринесите мне немного яда злобных ночных кругопрядов, чтобы я мог закончить эксперимент. Хочу посмотреть, как среагирует ядовитый элемент с моим новым составом. Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Аптекарю Юхану из города Брилл 4 образца яда злобного ночного кругопряда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Юхану в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (370,'Война с Алым орденом','В документах палача Аррена содержится информация, нужная нам для того, чтобы истребить всех людей в наших землях. Судя по этим данным, Алый орден прислал в заброшенную башню на юго-западе от Брилла капитана Перрина с людьми.$B$BУбейте Перрина, трех фанатиков и трех миссионеров, а потом доложите мне.','Убейте капитана Перрина, 3 ревнителей и миссионеров Алого ордена по просьбе исполнителя Зуганда.','Темная Госпожа, без сомнения, обрадуется смерти капитана Перрина. Вы хорошо исполнили свой долг, |3-6($C).','Ты собрал 10 Алых перстней, |3-6($C)?','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война с Алым орденом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В документах палача Аррена содержится информация, нужная нам для того, чтобы истребить всех людей в наших землях. Судя по этим данным, Алый орден прислал в заброшенную башню на юго-западе от Брилла капитана Перрина с людьми.$B$BУбейте Перрина, трех фанатиков и трех миссионеров, а потом доложите мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте капитана Перрина, 3 ревнителей и миссионеров Алого ордена по просьбе исполнителя Зуганда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Темная Госпожа, без сомнения, обрадуется смерти капитана Перрина. Вы хорошо исполнили свой долг, |3-6($C).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал 10 Алых перстней, |3-6($C)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (371,'Война с Алым орденом','У нас до сих пор война, а Алый орден набирает силу. В отчете палача Аррена сказано, что его участники под предводительством капитана Вакона совершают набеги из разрушенной башни в юго-восточном Тирисфале, близ усадьбы Балнира.$B$BУбейте Вакона и пятерых келейников из Алого ордена – это должно нанести ордену сокрушающий удар!','Убейте капитана Вакона и пятерых келейников из Алого ордена по заданию палача Зуганда.','Смерть капитана Вакона значительно замедлит продвижение Алого ордена по Тирисфалю. Но есть и другие угрозы.','Ну что, как прошел обход?','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война с Алым орденом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас до сих пор война, а Алый орден набирает силу. В отчете палача Аррена сказано, что его участники под предводительством капитана Вакона совершают набеги из разрушенной башни в юго-восточном Тирисфале, близ усадьбы Балнира.$B$BУбейте Вакона и пятерых келейников из Алого ордена – это должно нанести ордену сокрушающий удар!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте капитана Вакона и пятерых келейников из Алого ордена по заданию палача Зуганда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смерть капитана Вакона значительно замедлит продвижение Алого ордена по Тирисфалю. Но есть и другие угрозы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, как прошел обход?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (372,'Война с Алым орденом','Алый орден совершает набеги из своей разрушенной башни в северном Тирисфале, за могилой Фаола. Согласно нашей информации, отвечает за эти набеги жестокий капитан Мелраш.$B$BЯ даю вам особенное и очень важное задание – убить Мелраша и двух его телохранителей во имя Темной Госпожи.','По просьбе палача Зуганда убейте капитана Мелраша и двух его телохранителей.','Вы отлично справились, |3-6($C). Чем больше на стороне Отрекшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса. У меня хорошие предчувствия на ваш счет.','Вы еще не исполнили свой долг, $C. Мы не можем ожидать выполнения плана Темной Госпожи, когда Алый орден будет докучать нашим солдатам. Заставь их умереть и исполни свой долг перед Сильваной!','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война с Алым орденом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Алый орден совершает набеги из своей разрушенной башни в северном Тирисфале, за могилой Фаола. Согласно нашей информации, отвечает за эти набеги жестокий капитан Мелраш.$B$BЯ даю вам особенное и очень важное задание – убить Мелраша и двух его телохранителей во имя Темной Госпожи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе палача Зуганда убейте капитана Мелраша и двух его телохранителей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы отлично справились, |3-6($C). Чем больше на стороне Отрекшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса. У меня хорошие предчувствия на ваш счет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы еще не исполнили свой долг, $C. Мы не можем ожидать выполнения плана Темной Госпожи, когда Алый орден будет докучать нашим солдатам. Заставь их умереть и исполни свой долг перед Сильваной!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (373,'Неотправленное письмо','Обыскав труп Эдвина ван Клифа, вы находите, среди прочих предметов, неотправленное письмо. Адрес таков: "Баросу Алекстону, главному архитектору Штормграда, в ратушу на Соборной площади".$B$BКажется, оно написано совсем недавно, и печать еще свежая...','Доставьте письмо городскому архитектору Баросу Алекстону в Штормград.','Да? Я могу чем-то вам помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неотправленное письмо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обыскав труп Эдвина ван Клифа, вы находите, среди прочих предметов, неотправленное письмо. Адрес таков: "Баросу Алекстону, главному архитектору Штормграда, в ратушу на Соборной площади".$B$BКажется, оно написано совсем недавно, и печать еще свежая...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте письмо городскому архитектору Баросу Алекстону в Штормград.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Я могу чем-то вам помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (374,'Доказательство верности','Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими.$B$BВариматас, лейтенант Темной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стерто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден.$B$BПомоги нам истребить их, |3-6($c). Принеси мне десять перстней членов ордена в доказательство верности Вариматасу и Темной Госпоже.','Принесите 10 перстней Алого ордена стражу смерти Буржесу в Брилл.','Вариматас будет гордиться тобой. Ты отлично служишь своим лидерам, |3-6($C).','Ты собрал 10 Алых перстней, |3-6($C)?','Вернитесь к стражу смерти Буржесу в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доказательство верности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими.$B$BВариматас, лейтенант Темной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стерто с лица земли. Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден.$B$BПомоги нам истребить их, |3-6($c). Принеси мне десять перстней членов ордена в доказательство верности Вариматасу и Темной Госпоже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 перстней Алого ордена стражу смерти Буржесу в Брилл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вариматас будет гордиться тобой. Ты отлично служишь своим лидерам, |3-6($C).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал 10 Алых перстней, |3-6($C)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Буржесу в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (375,'Смертельный холод','Так холодно... Чума нежити расползается по моим венам, как клубок ледяных змеев, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Темной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны.$B$BТеперь мои руки дрожат от холода. Если ты принесешь мне 5 шкурок сумеречницы и грубую нить, я сошью себе одеяло. Помоги мне, $n, чтобы я могла и дальше служить нашему делу.','Принесите 5 шкурок сумеречницы и грубую нить Гретхен Дедмар в Брилл.','Вернитесь к Гретхен Дедмар в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смертельный холод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так холодно... Чума нежити расползается по моим венам, как клубок ледяных змеев, и скоро я впаду в беспамятство. Но никакой злой рок не помешает мне нести службу нашей Темной Госпоже. Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны.$B$BТеперь мои руки дрожат от холода. Если ты принесешь мне 5 шкурок сумеречницы и грубую нить, я сошью себе одеяло. Помоги мне, $n, чтобы я могла и дальше служить нашему делу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 шкурок сумеречницы и грубую нить Гретхен Дедмар в Брилл.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гретхен Дедмар в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (376,'Obtain 4 Scavenger Paws and 4 Duskbat Wings.','Постарайся остаться невредимым, пока я не найду для тебя каких-нибудь доспехов.','Вернитесь к новобранцу Элрет в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Obtain 4 Scavenger Paws and 4 Duskbat Wings.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Постарайся остаться невредимым, пока я не найду для тебя каких-нибудь доспехов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к новобранцу Элрет в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (377,'Преступление и наказание','Мало того, что столица бросила Темнолесье на произвол судьбы, теперь Благородные дома плюнули на решение городского совета Темнолесья и заточили Декстрена Варда в тюрьму Штормграда – вместо того, чтобы обезглавить злодея по приказу лорда Чернодрева.$b$bВард продавал тела с кладбища Морбенту Скверну. Подобное преступление карается смертью. И все же Штормград объявил Варда своим пленником.$b$bУбей Варда в тюрьме Штормграда, принеси мне его руку, и я тебя вознагражу.','Принесите советнику Миллстайпу руку Декстрена Варда.','Так значит, Декстрен Вард наконец-то расплатился за свои преступления против человечества? Чем меньше швали, тем лучше, я так считаю. Хвала тебе, друг мой! Ты не только утешил семьи покойных, ты преподал наглядный урок продажным бюрократам из Благородных домов. Штормград должен прислушиваться к нашему голосу, или мы восстанем против его тирании.','Пока выродки вроде Декстрена Варда живут на этом свете, в мире нет места справедливости. Возвращайся, когда исполнишь приговор лорда Чернодрева. Тем самым мы утешим семьи покойных и – более того – преподадим урок Благородным домам.','Вернитесь к Члену совета Миллстайпу в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преступление и наказание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мало того, что столица бросила Темнолесье на произвол судьбы, теперь Благородные дома плюнули на решение городского совета Темнолесья и заточили Декстрена Варда в тюрьму Штормграда – вместо того, чтобы обезглавить злодея по приказу лорда Чернодрева.$b$bВард продавал тела с кладбища Морбенту Скверну. Подобное преступление карается смертью. И все же Штормград объявил Варда своим пленником.$b$bУбей Варда в тюрьме Штормграда, принеси мне его руку, и я тебя вознагражу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите советнику Миллстайпу руку Декстрена Варда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так значит, Декстрен Вард наконец-то расплатился за свои преступления против человечества? Чем меньше швали, тем лучше, я так считаю. Хвала тебе, друг мой! Ты не только утешил семьи покойных, ты преподал наглядный урок продажным бюрократам из Благородных домов. Штормград должен прислушиваться к нашему голосу, или мы восстанем против его тирании.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пока выродки вроде Декстрена Варда живут на этом свете, в мире нет места справедливости. Возвращайся, когда исполнишь приговор лорда Чернодрева. Тем самым мы утешим семьи покойных и – более того – преподадим урок Благородным домам.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Члену совета Миллстайпу в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (378,'Успокоить Гневливого','Ты $Gдоказал:доказала; свою преданность королю Магни, |3-6($c). И ты, так же как я, ненавидишь мерзавцев Черного Железа всем сердцем.$b$bЯ бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длиннокосом. Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола. А это значит, что Кам виноват в гибели брата Длиннокоса.$b$bПока что Кама Гневливого держат в тюрьме Штормграда. Но такие, как он, не достойны того, чтобы жить. Убей его, $n. Ради Грима! Принеси мне его голову!','Принесите голову Кама Гневливого Мотли Гармасону в Дун Модр.','Стало быть, Кам Гневливый на собственной шкуре узнал, каково это – принять мучительную смерть? Хорошо. С этими негодяями из клана Черного Железа только так и надо. Отлично потрудился, $C. Жертвы атаки на мост Тандола – это не первые и не последние невинные жертвы в нашем мире, объятом смятением и раздираемым войнами. Но теперь семьи погибших хотя бы утешатся тем, что предатель наказан. Брат Длиннокоса отомщен.','Вернитесь к Мотли Гармасону в Дун Модр, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Успокоить Гневливого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gдоказал:доказала; свою преданность королю Магни, |3-6($c). И ты, так же как я, ненавидишь мерзавцев Черного Железа всем сердцем.$b$bЯ бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длиннокосом. Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола. А это значит, что Кам виноват в гибели брата Длиннокоса.$b$bПока что Кама Гневливого держат в тюрьме Штормграда. Но такие, как он, не достойны того, чтобы жить. Убей его, $n. Ради Грима! Принеси мне его голову!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Кама Гневливого Мотли Гармасону в Дун Модр.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стало быть, Кам Гневливый на собственной шкуре узнал, каково это – принять мучительную смерть? Хорошо. С этими негодяями из клана Черного Железа только так и надо. Отлично потрудился, $C. Жертвы атаки на мост Тандола – это не первые и не последние невинные жертвы в нашем мире, объятом смятением и раздираемым войнами. Но теперь семьи погибших хотя бы утешатся тем, что предатель наказан. Брат Длиннокоса отомщен.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мотли Гармасону в Дун Модр, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (379,'Утолить жажду','Тебе нужен источник силы. Могу помочь. Что я хочу взамен? Пить! Принеси мне пять бурдюков с водой Скитальцев Пустыни, и я дам тебе 4711-FTZ.$b$bЗнаешь, где взять эти меха? Попробуй попросить их у кочевников Скитальцев Пустыни! Потом расскажешь, что из этого вышло.','Найдите 5 бурдюков с водой Скитальцев Пустыни главному инженеру Чепухастеру в Прибамбасск.','Отлично, вот тебе источник энергии. Честно говоря, он создан совсем не для исследовательского набора вроде этого, поэтому у тебя будет не так уж много времени, а потом все данные кирдыкнутся!$B$BКак только соберешь, все, что нужно, принеси эту штуковину мне, чтобы я отключил ее как надо. У тебя не больше двух часов на все про все.$B$BЕсли ты не успеешь, я, конечно, продам тебе еще один источник энергии. Ключевое слово – продам!','Ну как, кочевники поделились с тобой водой?','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утолить жажду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужен источник силы. Могу помочь. Что я хочу взамен? Пить! Принеси мне пять бурдюков с водой Скитальцев Пустыни, и я дам тебе 4711-FTZ.$b$bЗнаешь, где взять эти меха? Попробуй попросить их у кочевников Скитальцев Пустыни! Потом расскажешь, что из этого вышло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 бурдюков с водой Скитальцев Пустыни главному инженеру Чепухастеру в Прибамбасск.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, вот тебе источник энергии. Честно говоря, он создан совсем не для исследовательского набора вроде этого, поэтому у тебя будет не так уж много времени, а потом все данные кирдыкнутся!$B$BКак только соберешь, все, что нужно, принеси эту штуковину мне, чтобы я отключил ее как надо. У тебя не больше двух часов на все про все.$B$BЕсли ты не успеешь, я, конечно, продам тебе еще один источник энергии. Ключевое слово – продам!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, кочевники поделились с тобой водой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (380,'Паучья низина','Одна из наших самых серьезных проблем – это добыча природных ресурсов, необходимых для выживания. Золота было очень мало даже во времена расцвета власти Альянса. $b$bК северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придется действовать постепенно. $b$bОтправляйся туда – может быть, ты сможешь чем-то помочь нам, $n.','Палач Аррен хочет, чтобы вы убили 8 молодых ночных кругопрядов и 5 ночных кругопрядов.','Удалось ли тебе найти что-нибудь стоящее? Нет ничего постыдного в повторном использовании выброшенных вещей. Никто не станет ничего давать нам – мы, Отрекшиеся, сами себя обеспечим!','Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Паучья низина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна из наших самых серьезных проблем – это добыча природных ресурсов, необходимых для выживания. Золота было очень мало даже во времена расцвета власти Альянса. $b$bК северо-западу отсюда есть золотой рудник, но он весь кишит пауками. Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари. У меня не так много рабочих рук для этой задачи, так что придется действовать постепенно. $b$bОтправляйся туда – может быть, ты сможешь чем-то помочь нам, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Палач Аррен хочет, чтобы вы убили 8 молодых ночных кругопрядов и 5 ночных кругопрядов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе найти что-нибудь стоящее? Нет ничего постыдного в повторном использовании выброшенных вещей. Никто не станет ничего давать нам – мы, Отрекшиеся, сами себя обеспечим!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (381,'Алый орден','Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. $b$bМои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! $b$bБудь осторожен, нечестивое рвение делает их опасными противниками.','Принесите палачу Аррену 12 алых поручей, сняв их с новообращенных и посвященных из Алого ордена.','Они просто идиоты... копающие себе могилы.','Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Алый орден',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям. Теперь мы можем позаботится и о других делах. $b$bМои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда. Алый орден – достойная презрения организация, ведущая охоту на нас. Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар! $b$bБудь осторожен, нечестивое рвение делает их опасными противниками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите палачу Аррену 12 алых поручей, сняв их с новообращенных и посвященных из Алого ордена.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Они просто идиоты... копающие себе могилы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (382,'Красный гонец','В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из Монастыря к Похоронному Звону. Судя по этим сообщениям, гонец несет важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! $b$bА ты, $n, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти.','Убейте гонца Мевена Коргала в лагере Алого ордена, а потом сообщите перехваченные известия палачу Аррену.','Хмм... Ну-ка, посмотрим, что ты там нашел... \n\n<Аррен пробегает глазами документы, принесенные вами.> \n\nНовости об их успехах в борьбе с нами... Ценности не имеют. Донесения разведки... Новые приказы... "Продолжайте организацию лагеря около разрушенного города..." Ничего такого, о чем мы не знали бы... А это еще что? Карта местонахождения некоторых полевых командиров и агентов! Это можно будет использовать.','Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Красный гонец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из Монастыря к Похоронному Звону. Судя по этим сообщениям, гонец несет важную информацию. Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить! $b$bА ты, $n, наиболее квалифицированная особа, которую я могу послать на это задание. Найди гонца и принеси мне информацию, которую тебе удастся найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте гонца Мевена Коргала в лагере Алого ордена, а потом сообщите перехваченные известия палачу Аррену.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм... Ну-ка, посмотрим, что ты там нашел... \n\n<Аррен пробегает глазами документы, принесенные вами.> \n\nНовости об их успехах в борьбе с нами... Ценности не имеют. Донесения разведки... Новые приказы... "Продолжайте организацию лагеря около разрушенного города..." Ничего такого, о чем мы не знали бы... А это еще что? Карта местонахождения некоторых полевых командиров и агентов! Это можно будет использовать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Аррену в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (383,'Важные разведданные','Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно $gпомог:помогла; нам здесь, в Похоронном Звоне, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдется более серьезная работа. $b$bИди по дороге из Похоронного Звона на север. Вскоре после того, как дойдешь до Тирисфаля, наткнешься на перекресток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье "Остывший очаг".','Отнесите бумаги Алого ордена палачу Зуганду в Брилл.','Да? Что тебе нужно?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важные разведданные',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл. Обладая этой информацией, он сможет нанести решающий удар по Алому ордену. Ты сильно $gпомог:помогла; нам здесь, в Похоронном Звоне, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдется более серьезная работа. $b$bИди по дороге из Похоронного Звона на север. Вскоре после того, как дойдешь до Тирисфаля, наткнешься на перекресток. Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье "Остывший очаг".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите бумаги Алого ордена палачу Зуганду в Брилл.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Что тебе нужно?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (384,'Кабаньи ребрышки в пиве','Завсегдатаи моей таверны больше всего любят кабаньи ребрышки в пиве! Беда в том, что местный охотник, который снабжал меня кабаниной, теперь завербован в королевскую армию, чтобы помочь Альянсу.$B$bМожет, ты мне поможешь? Если принесешь мне немного ребер скального вепря и "Болтливое пиво" вон из той таверны, я открою тебе фамильный рецепт моих знаменитых ребрышек в пиве, не говоря уж о дармовой порции! Вся соль – в пиве!','Принесите 4 нежных свиных ребрышка и кружку "Болтливого пива" Рагнару Громовару в Каранос.','Сварено пиво, разлито по кружкам,$bЭй, не деритесь, друзья и подружки!$bКаждому выделим по половине$bВкуснейшей порции ребрышек в пиве!','Вернитесь к Рагнару Громовару на Мерцающий хребет, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кабаньи ребрышки в пиве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Завсегдатаи моей таверны больше всего любят кабаньи ребрышки в пиве! Беда в том, что местный охотник, который снабжал меня кабаниной, теперь завербован в королевскую армию, чтобы помочь Альянсу.$B$bМожет, ты мне поможешь? Если принесешь мне немного ребер скального вепря и "Болтливое пиво" вон из той таверны, я открою тебе фамильный рецепт моих знаменитых ребрышек в пиве, не говоря уж о дармовой порции! Вся соль – в пиве!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 нежных свиных ребрышка и кружку "Болтливого пива" Рагнару Громовару в Каранос.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сварено пиво, разлито по кружкам,$bЭй, не деритесь, друзья и подружки!$bКаждому выделим по половине$bВкуснейшей порции ребрышек в пиве!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рагнару Громовару на Мерцающий хребет, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (385,'Охота на кроколисков','Многие охотники приезжают к озеру Лок Модан поохотиться на знаменитых кроков. Всегда находятся торговцы, скупающие кроколисковые шкуры на одежду или доспехи, а есть и любители кроколискового мяса.$b$bМы тоже зарабатываем на этом, но не слишком много, потому что кроколисков не так просто одолеть, и к тому же они поселились на островах посреди озера Лок. Но если хочешь отправиться на охоту, я не стану тебя отговаривать. Это действительно незабываемо.$b$bЯ и сам в свое время...','Принесите Мареку Железносерду в Приют Странников 5 кусков мяса кроколиска и 6 шкур кроколиска.','Ты отлично $gпоохотился:поохотилась;, $n. За хорошую работу и платят хорошо!','Я не рассказывал, как кроколиск едва не откусил мне руку? Жуткая тварь была, зубы – как лезвия. Но мне повезло... Я заткнул ему пасть ножом. Этот нож я до сих пор храню...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на кроколисков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие охотники приезжают к озеру Лок Модан поохотиться на знаменитых кроков. Всегда находятся торговцы, скупающие кроколисковые шкуры на одежду или доспехи, а есть и любители кроколискового мяса.$b$bМы тоже зарабатываем на этом, но не слишком много, потому что кроколисков не так просто одолеть, и к тому же они поселились на островах посреди озера Лок. Но если хочешь отправиться на охоту, я не стану тебя отговаривать. Это действительно незабываемо.$b$bЯ и сам в свое время...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мареку Железносерду в Приют Странников 5 кусков мяса кроколиска и 6 шкур кроколиска.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты отлично $gпоохотился:поохотилась;, $n. За хорошую работу и платят хорошо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не рассказывал, как кроколиск едва не откусил мне руку? Жуткая тварь была, зубы – как лезвия. Но мне повезло... Я заткнул ему пасть ножом. Этот нож я до сих пор храню...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (386,'Что происходит?','Таргорр Ужасный служил под началом Гат\'Илзогга старшим палачом и даже среди жестоких орков отличался особой кровожадностью. По его прихоти отважных бойцов Королевства подвергали страшным пыткам. Его взяли в плен и поместили в тюрьму Штормграда, приговорив к смертной казни. Но происходит что-то странное. Один из знатных людей запретил его казнить. Уверен, дело нечисто.$b$bПоложи конец Таргорру Ужасному, $n. Отправляйся в тюрьму и обезглавь его, пока мы не пали жертвой предательства.','Принесите голову Таргорра Ужасного стражнику Бертону в Приозерье.','Вернитесь к стражнику Бертону в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что происходит?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Таргорр Ужасный служил под началом Гат\'Илзогга старшим палачом и даже среди жестоких орков отличался особой кровожадностью. По его прихоти отважных бойцов Королевства подвергали страшным пыткам. Его взяли в плен и поместили в тюрьму Штормграда, приговорив к смертной казни. Но происходит что-то странное. Один из знатных людей запретил его казнить. Уверен, дело нечисто.$b$bПоложи конец Таргорру Ужасному, $n. Отправляйся в тюрьму и обезглавь его, пока мы не пали жертвой предательства.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Таргорра Ужасного стражнику Бертону в Приозерье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражнику Бертону в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (387,'Подавление бунта','Бунт должен быть подавлен! И ты мне в этом поможешь. Если станет известно, что в тюрьме случился бунт, я потеряю работу. Это исключительная подлость! Самое важное сейчас – немедленно взять тюрьму под контроль. Ради безопасности Штормграда.$b$bНаказание за бунт в тюрьме – смертная казнь. Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдет в норму.','[Deprecated] Warden Thelwater of Stormwind wants you to kill 10 Prisoners, 8 Convicts, and 8 Insurgents in The Stockade.','$N, ты отлично проявил себя в тюрьме. Эта проблема куда сложнее, чем выглядит на первый взгляд, но ты отлично поработал, и я тебе очень благодарен.','Тюрьма по-прежнему под контролем бунтовщиков! Этим крысам из Братства Справедливости нужно показать, что это им даром не пройдет! Возвращайся и задай им жару!','Вернитесь к тюремщику Телвотеру в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подавление бунта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бунт должен быть подавлен! И ты мне в этом поможешь. Если станет известно, что в тюрьме случился бунт, я потеряю работу. Это исключительная подлость! Самое важное сейчас – немедленно взять тюрьму под контроль. Ради безопасности Штормграда.$b$bНаказание за бунт в тюрьме – смертная казнь. Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдет в норму.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[Deprecated] Warden Thelwater of Stormwind wants you to kill 10 Prisoners, 8 Convicts, and 8 Insurgents in The Stockade.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, ты отлично проявил себя в тюрьме. Эта проблема куда сложнее, чем выглядит на первый взгляд, но ты отлично поработал, и я тебе очень благодарен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тюрьма по-прежнему под контролем бунтовщиков! Этим крысам из Братства Справедливости нужно показать, что это им даром не пройдет! Возвращайся и задай им жару!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тюремщику Телвотеру в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (388,'Цвет крови','Кровь моя стынет в жилах от ужасного горя... Мой внук Мак... он был такой чудесный мальчик. Всего 14 лет. Когда армия ушла на фронт, он счел, что должен защитить город. Он был охранником в тюрьмe, куда прибыла партия заключенных из Братства Справедливости. Мак наказал некоторых заключенных за порчу шерстяного одеяла, из которого они изготовили головные повязки, знаки их банды. За это он получил нож в спину.$b$bЯ хочу мести. Принесите мне 10 этих проклятых шерстяных бандан. Они цвета крови...','Принесите Никове Раскол 10 красных шерстяных бандан.','Я вижу, вы вернулись, $C. Вы уже собрали 10 красных шерстяных бандан, принадлежавших этому отродью, Братству Справедливости?','Вернитесь к Никове Раскол в Старый город Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цвет крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кровь моя стынет в жилах от ужасного горя... Мой внук Мак... он был такой чудесный мальчик. Всего 14 лет. Когда армия ушла на фронт, он счел, что должен защитить город. Он был охранником в тюрьмe, куда прибыла партия заключенных из Братства Справедливости. Мак наказал некоторых заключенных за порчу шерстяного одеяла, из которого они изготовили головные повязки, знаки их банды. За это он получил нож в спину.$b$bЯ хочу мести. Принесите мне 10 этих проклятых шерстяных бандан. Они цвета крови...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Никове Раскол 10 красных шерстяных бандан.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я вижу, вы вернулись, $C. Вы уже собрали 10 красных шерстяных бандан, принадлежавших этому отродью, Братству Справедливости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Никове Раскол в Старый город Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (389,'Базиль Тредд','ван Клиф и я были членами гильдии каменщиков. Это мы восстанавливали Штормград после войны.$B$BКогда мы закончили работу, вельможи отказались платить нам за нее. Руководителям гильдии предложили места на государственной службе, но ван Клиф отказался, потому что превыше всего ценил интересы гильдии. Он поднял мятеж и покинул город, поклявшись отомстить.$b$bЕго лейтенант, Базиль Тредд, много знает о планах своего командира. Базиль содержится в плену в тюрьме.','Поговорите с надзирателем Телвотером в тюрьме.','Чего, во имя Света, тебе надо? Не видишь, тут и без тебя проблем хватает?\n\nБазиль Тредд?! Какое тебе дело до этого мерзавца? Или ты – из его поганых кровавых соратничков? Не будь у меня тут все камеры заняты, я бы тебя точно засунул в одну из них!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Базиль Тредд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','ван Клиф и я были членами гильдии каменщиков. Это мы восстанавливали Штормград после войны.$B$BКогда мы закончили работу, вельможи отказались платить нам за нее. Руководителям гильдии предложили места на государственной службе, но ван Клиф отказался, потому что превыше всего ценил интересы гильдии. Он поднял мятеж и покинул город, поклявшись отомстить.$b$bЕго лейтенант, Базиль Тредд, много знает о планах своего командира. Базиль содержится в плену в тюрьме.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с надзирателем Телвотером в тюрьме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чего, во имя Света, тебе надо? Не видишь, тут и без тебя проблем хватает?\n\nБазиль Тредд?! Какое тебе дело до этого мерзавца? Или ты – из его поганых кровавых соратничков? Не будь у меня тут все камеры заняты, я бы тебя точно засунул в одну из них!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (390,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (391,'Бунтовщики в тюрьме','Скажу тебе сразу, $n: я тебе ни капли не доверяю. Но в нынешней ситуации это не особо важно.$B$BЧто от тебя требуется: иди и поговори с Треддом. Если ты и вправду на нашей стороне, убей его и принеси мне его голову. А если ты на их стороне и не вернешься вовремя, то будешь долго, долго гнить заживо...','Убейте Базиля Тредда и принесите его голову Телвотеру в тюрьму Штормграда.','Без Тредда бунтовщики станут куда более управляемыми. Посмотрим...$B$BДолжен сказать, я уже через полчаса решил, что больше тебя не увижу… но, надо признать, я в тебе ошибся.$B$BДумаю, тебе не удалось из него ничего вытянуть... А вот я знаю пару вещей насчет деятельности Тредда, которые тебя могут заинтересовать.','Вернитесь к тюремщику Телвотеру в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бунтовщики в тюрьме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скажу тебе сразу, $n: я тебе ни капли не доверяю. Но в нынешней ситуации это не особо важно.$B$BЧто от тебя требуется: иди и поговори с Треддом. Если ты и вправду на нашей стороне, убей его и принеси мне его голову. А если ты на их стороне и не вернешься вовремя, то будешь долго, долго гнить заживо...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Базиля Тредда и принесите его голову Телвотеру в тюрьму Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Без Тредда бунтовщики станут куда более управляемыми. Посмотрим...$B$BДолжен сказать, я уже через полчаса решил, что больше тебя не увижу… но, надо признать, я в тебе ошибся.$B$BДумаю, тебе не удалось из него ничего вытянуть... А вот я знаю пару вещей насчет деятельности Тредда, которые тебя могут заинтересовать.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тюремщику Телвотеру в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (392,'Таинственный посетитель','Во время первого года заключения Тредда никто его не навещал. Мне казалось, что братство отказалось от него, поскольку он стал бесполезен.$B$BНо пару месяцев назад его стали постоянно навещать – раз, два в неделю. Посетитель был весьма странный. Такой тихий тип. У меня возникли подозрения, но все его документы были в полном порядке.$B$BСогласно документам, звали его Мелик; вот его описание. Не думаю, что он еще когда-нибудь придет к Тредду.','Отнесите запечатанное описание посетителя Тредда Баросу Алекстону в Штормград.','Мелик? Нет, это имя мне незнакомо и даже ни на какие мысли не наводит. Это может быть кто угодно! Бывший каменщик, один из членов Братства Справедливости... Хотя если он тесно связан с ними, как предполагает Телуотер, кто-нибудь может опознать его. Мне нужно подумать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Таинственный посетитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время первого года заключения Тредда никто его не навещал. Мне казалось, что братство отказалось от него, поскольку он стал бесполезен.$B$BНо пару месяцев назад его стали постоянно навещать – раз, два в неделю. Посетитель был весьма странный. Такой тихий тип. У меня возникли подозрения, но все его документы были в полном порядке.$B$BСогласно документам, звали его Мелик; вот его описание. Не думаю, что он еще когда-нибудь придет к Тредду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанное описание посетителя Тредда Баросу Алекстону в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мелик? Нет, это имя мне незнакомо и даже ни на какие мысли не наводит. Это может быть кто угодно! Бывший каменщик, один из членов Братства Справедливости... Хотя если он тесно связан с ними, как предполагает Телуотер, кто-нибудь может опознать его. Мне нужно подумать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (393,'Тень прошлого','Знаете ли, $n, мне так ничего и не пришло в голову. Зато я придумал, кто может нам помочь; если так и случится, я буду гордиться собой, но не стоит на это закладываться. Матиас Шоу из ШРУ – его можно найти в казармах Старого города. Шоу знает все уголки и закоулки этого города, всю его подноготную и тайные делишки.$B$BЕсли кто-то и знает, о ком речь, то только он.','Отнесите запечатанное описание посетителя Тредда Матиасу Шоу в Штормград.','Что это? Да, думаю, что знаю этого человека, но его зовут вовсе не Мелик. Наемные убийцы носят много масок, зовутся множеством имен и забывают их, как только они становятся не нужны. Этот человек также известен под именем Марзон; вероятно, это его очередной псевдоним.$B$BВ общем, он – наемный убийца, и я о нем довольно много знаю.$B$BМарзон сейчас работает на Грегора Лесковара – человека с репутацией, дурной даже для коррумпированного лорда Штормграда.','Приветствую. По какому делу вы ко мне явились, $C?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тень прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаете ли, $n, мне так ничего и не пришло в голову. Зато я придумал, кто может нам помочь; если так и случится, я буду гордиться собой, но не стоит на это закладываться. Матиас Шоу из ШРУ – его можно найти в казармах Старого города. Шоу знает все уголки и закоулки этого города, всю его подноготную и тайные делишки.$B$BЕсли кто-то и знает, о ком речь, то только он.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанное описание посетителя Тредда Матиасу Шоу в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Да, думаю, что знаю этого человека, но его зовут вовсе не Мелик. Наемные убийцы носят много масок, зовутся множеством имен и забывают их, как только они становятся не нужны. Этот человек также известен под именем Марзон; вероятно, это его очередной псевдоним.$B$BВ общем, он – наемный убийца, и я о нем довольно много знаю.$B$BМарзон сейчас работает на Грегора Лесковара – человека с репутацией, дурной даже для коррумпированного лорда Штормграда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую. По какому делу вы ко мне явились, $C?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (394,'Голова чудовища','Найди Шоу в Старом городе. Дай ему знать, что с Лесковаром покончено, а тебе все известно о заговоре лордов против города. Я думаю, он будет рад, что среди горожан Штормграда есть еще герои.$B$BДумаю, он отправит тебя на встречу с принцем или другим лордом. Не позволяй им запудрить себе мозги, $n. Власть имущие думают, что могут творить в городе что угодно, но пока они не всесильны.','Поговорите с Матиасом Шоу в Штормграде.','Значит, мертв? Ты скор на расправу, $n. Не хотел бы я стать твоим врагом.$B$BСмеется и кладет руку вам на плечо.$B$BНе прими за осуждение, $n. Я же глава наемных убийц, как я могу осуждать тебя за чистое убийство? По правде сказать, ты оказал людям Штормграда огромную услугу, и я благодарю тебя за это.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голова чудовища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Найди Шоу в Старом городе. Дай ему знать, что с Лесковаром покончено, а тебе все известно о заговоре лордов против города. Я думаю, он будет рад, что среди горожан Штормграда есть еще герои.$B$BДумаю, он отправит тебя на встречу с принцем или другим лордом. Не позволяй им запудрить себе мозги, $n. Власть имущие думают, что могут творить в городе что угодно, но пока они не всесильны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Матиасом Шоу в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, мертв? Ты скор на расправу, $n. Не хотел бы я стать твоим врагом.$B$BСмеется и кладет руку вам на плечо.$B$BНе прими за осуждение, $n. Я же глава наемных убийц, как я могу осуждать тебя за чистое убийство? По правде сказать, ты оказал людям Штормграда огромную услугу, и я благодарю тебя за это.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (395,'Гибель братства','Ах, да... Пока тебя не было, приходил Алекстон, хотел с тобой поговорить. Должно быть, это касалось Братства Справедливости.$b$B$n, позволь дать тебе совет: на твоем месте я бы по первой просьбе рассказал обо всем произошедшем в подробностях. Но при этом упомяни, что Лесковара сразила именно твоя рука. Можешь мне верить – я на таких вещах собаку съел.$B$BА что касается Триаса... ну, не говори о нем. Никогда. Если сможешь.','Поговорите с Баросом Алекстоном в Штормграде.','Приятно тебя видеть снова, $n. Мне довелось услышать о недавней кончине лорда Грегора Лесковара.$B$BЗначит, твоя миссия оказалась успешной. Я щедро награжу тебя за спасение и меня, и многих прочих от мести ван Клифа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гибель братства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, да... Пока тебя не было, приходил Алекстон, хотел с тобой поговорить. Должно быть, это касалось Братства Справедливости.$b$B$n, позволь дать тебе совет: на твоем месте я бы по первой просьбе рассказал обо всем произошедшем в подробностях. Но при этом упомяни, что Лесковара сразила именно твоя рука. Можешь мне верить – я на таких вещах собаку съел.$B$BА что касается Триаса... ну, не говори о нем. Никогда. Если сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Баросом Алекстоном в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно тебя видеть снова, $n. Мне довелось услышать о недавней кончине лорда Грегора Лесковара.$B$BЗначит, твоя миссия оказалась успешной. Я щедро награжу тебя за спасение и меня, и многих прочих от мести ван Клифа.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (396,'Аудиенция у короля','Я приготовил доклад для короля. Надеюсь, ты сумеешь преподнести его величеству все в лучшем виде. Не переживай так, король обязательно оценит твое благородное служение народу Штормграда и достойно наградит тебя.$B$BСрок твоей аудиенции близок, так что поторопись, чтобы не опоздать в крепость Штормграда.','Доставьте доклад Бароса Алекстона об уничтожении Братства Справедливости королю Вариану Ринну в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аудиенция у короля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я приготовил доклад для короля. Надеюсь, ты сумеешь преподнести его величеству все в лучшем виде. Не переживай так, король обязательно оценит твое благородное служение народу Штормграда и достойно наградит тебя.$B$BСрок твоей аудиенции близок, так что поторопись, чтобы не опоздать в крепость Штормграда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте доклад Бароса Алекстона об уничтожении Братства Справедливости королю Вариану Ринну в крепость Штормграда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (397,'За достойную службу','Я слышал, что Лорд Вишлок в восторге от напитка.$b$b$n, ты нам здорово $Gпомог:помогла;. Теперь чернокнижники Штормграда смогут заниматься своим делом без помех. За свою службу ты получишь достойный подарок. Поговори с Згги, моим слугой.','Поговорите с Згги, слугой Зардета Черного Когтя, чтобы получить награду.','Хозяин дал подарок для $N. Згги хотел бы оставить его себе, но Згги знает, что будет, если предать хозяина.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За достойную службу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, что Лорд Вишлок в восторге от напитка.$b$b$n, ты нам здорово $Gпомог:помогла;. Теперь чернокнижники Штормграда смогут заниматься своим делом без помех. За свою службу ты получишь достойный подарок. Поговори с Згги, моим слугой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Згги, слугой Зардета Черного Когтя, чтобы получить награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хозяин дал подарок для $N. Згги хотел бы оставить его себе, но Згги знает, что будет, если предать хозяина.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (398,'Разыскивается: Червеглаз','Разыскивается: Червеглаз!$B$BУжасное даже по меркам гноллов чудовище – Червеглаз – приговорен к смерти за его преступления против Отрекшихся. Этот гнусный злодей воровал трупы для армии Короля-лича. Червеглаза видели близ Фермы Гаррена, к северу от Брилла.$B$BГород Брилл предлагает награду всякому, кто сумеет прикончить негодяя и предъявить палачу Зуганду его лапу.$B$BМилосердие – удел слабых.','Убейте Червеглаза и отнесите палачу Зуганду в Брилл его лапу.','Да?','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разыскивается: Червеглаз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разыскивается: Червеглаз!$B$BУжасное даже по меркам гноллов чудовище – Червеглаз – приговорен к смерти за его преступления против Отрекшихся. Этот гнусный злодей воровал трупы для армии Короля-лича. Червеглаза видели близ Фермы Гаррена, к северу от Брилла.$B$BГород Брилл предлагает награду всякому, кто сумеет прикончить негодяя и предъявить палачу Зуганду его лапу.$B$BМилосердие – удел слабых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Червеглаза и отнесите палачу Зуганду в Брилл его лапу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (399,'Скромные дары прошлого','It seems an eternity since I was a boy working the farm in Westfall. They say you can never go back, and it\'s true. Doubly true in my case, my family\'s home has been burned down and taken over by transients.$b$bI have spoken with my father about the fate of some of my possessions, including my first compass. He was unable to save them. However, he also says that they should be hidden away on the farm.$b$bYou\'ll find the Alexston Farmstead west of Sentinel Hill. Perhaps you could go and retrieve it for me?','Обыщите дом Бароса Алекстона в Западном Крае, найдите компас и вернитесь на Соборную площадь Штормграда.','Благодарю вас, $n! Совершенно бесполезная вещь, не считая воспоминаний... Нет слов, как я благодарен за то, что принесли мне этот предмет; вам, конечно, трудно понять цену памяти о Западном Крае. Возьмите это в знак моей признательности...','$n! Вы нашли компас?','Вернитесь к Баросу Алекстону в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скромные дары прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','It seems an eternity since I was a boy working the farm in Westfall. They say you can never go back, and it\'s true. Doubly true in my case, my family\'s home has been burned down and taken over by transients.$b$bI have spoken with my father about the fate of some of my possessions, including my first compass. He was unable to save them. However, he also says that they should be hidden away on the farm.$b$bYou\'ll find the Alexston Farmstead west of Sentinel Hill. Perhaps you could go and retrieve it for me?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите дом Бароса Алекстона в Западном Крае, найдите компас и вернитесь на Соборную площадь Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю вас, $n! Совершенно бесполезная вещь, не считая воспоминаний... Нет слов, как я благодарен за то, что принесли мне этот предмет; вам, конечно, трудно понять цену памяти о Западном Крае. Возьмите это в знак моей признательности...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$n! Вы нашли компас?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баросу Алекстону в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (400,'Инструменты для Сталежара','Белдин Сталежар владеет местной ремонтной мастерской, и он лучший техник по осадным машинам! Но своего инструмента он не жалеет. Могу побиться об заклад, его тангенциальные вращатели выходят из строя быстрее, чем мы успеваем поставлять ему новые!$B$BМы только что выполнили его очередной заказ. Если ты его доставишь, я уверен, мастер заплатит тебе за труды.$B$BТы сможешь найти Сталежара к северо-востоку от Караноса. Кстати, это излюбленное местечко ветеранов-водителей осадных машин, так что держи ухо востро, когда там будешь, – вдруг какая работенка подвернется.','Доставьте инструменты Белдину Сталежару.','Хм? $GМал:Мала; ты еще для водителя осадной машины. Ну да ладно... Тебе что-нибудь починить надо?$B$BВозьми номерок и жди своей очереди. Я сейчас работаю над парой машин, и времени на еще одну работу у меня не будет как минимум пару дней.$B$BИли ты тут по другому вопросу?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Инструменты для Сталежара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Белдин Сталежар владеет местной ремонтной мастерской, и он лучший техник по осадным машинам! Но своего инструмента он не жалеет. Могу побиться об заклад, его тангенциальные вращатели выходят из строя быстрее, чем мы успеваем поставлять ему новые!$B$BМы только что выполнили его очередной заказ. Если ты его доставишь, я уверен, мастер заплатит тебе за труды.$B$BТы сможешь найти Сталежара к северо-востоку от Караноса. Кстати, это излюбленное местечко ветеранов-водителей осадных машин, так что держи ухо востро, когда там будешь, – вдруг какая работенка подвернется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте инструменты Белдину Сталежару.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хм? $GМал:Мала; ты еще для водителя осадной машины. Ну да ладно... Тебе что-нибудь починить надо?$B$BВозьми номерок и жди своей очереди. Я сейчас работаю над парой машин, и времени на еще одну работу у меня не будет как минимум пару дней.$B$BИли ты тут по другому вопросу?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (401,'Ожидание перевода','Я почти закончил работу над переводом записки. Она будет готова через несколько минут.','Подождите немного и снова поговорите с Широй Фон-Инди.','Ну вот. Готово…$B$BВокруг воцаряется душная тишина, словно на лес опустился темный тяжелый полог...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожидание перевода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я почти закончил работу над переводом записки. Она будет готова через несколько минут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подождите немного и снова поговорите с Широй Фон-Инди.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот. Готово…$B$BВокруг воцаряется душная тишина, словно на лес опустился темный тяжелый полог...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (402,'Шира занят','Прости, но сейчас трудный момент в жизни нашего города. У меня есть другие дела. Может быть позже, если мы все выживем, я закончу перевод.','Зайдите к Шире и выясните, занят ли он.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шира занят',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прости, но сейчас трудный момент в жизни нашего города. У меня есть другие дела. Может быть позже, если мы все выживем, я закончу перевод.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зайдите к Шире и выясните, занят ли он.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (403,'Охраняемый бочонок Громоваров','Этот бочонок эля охраняет Ярвен Громовар. Пока он в подвале, до бочек не добраться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охраняемый бочонок Громоваров',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот бочонок эля охраняет Ярвен Громовар. Пока он в подвале, до бочек не добраться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (404,'Грязная работа','Плеть проникла в Тирисфальские леса и заполонила всю местность к западу от Брилла, возле старого моста.$B$BОтправляйся туда и загони этих гниющих мертвецов обратно в землю, откуда они вылезли. Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти.','Принесите 7 гнилых когтей стражу смерти Диллинжеру в Брилл.','Отличная работа. Жаль, я не видел, как ты расправляешься с этими гнусными тварями!','Ты выполнил задание, которое я тебе дал? Принес мне гнилые когти?','Вернитесь к стражу смерти Диллинжеру в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязная работа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плеть проникла в Тирисфальские леса и заполонила всю местность к западу от Брилла, возле старого моста.$B$BОтправляйся туда и загони этих гниющих мертвецов обратно в землю, откуда они вылезли. Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 гнилых когтей стражу смерти Диллинжеру в Брилл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа. Жаль, я не видел, как ты расправляешься с этими гнусными тварями!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты выполнил задание, которое я тебе дал? Принес мне гнилые когти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Диллинжеру в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (405,'Блудный лич','Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, $n, как раз подходишь для этого.$B$BОтнеси эти приказы Бетору, а он расскажет, в чем состоит твоя миссия. Деталей я не знаю, могу сказать лишь то, что речь пойдет о найме заблудшего лича. Это очень опасное дело.$B$BПриготовься как следует, |3-6($c). Не подведи нас.$B$BБетора можно найти в Квартале Магов Подгорода.','Отнесите приказы Севрена Бетору Ледострелу в Подгород.','А, так тебя прислал мировой судья Севрен. Тогда да, дело у нас с тобой очень важное.\n\nУверен, Севрен выбрал того, кто справится с моим заданием, но… ладно, посмотрим.','Здравствуй. Либо ты не знаешь, кто я, либо у тебя ко мне очень срочное дело.\n\nПотому что иначе ты не посмел бы меня беспокоить…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Блудный лич',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, $n, как раз подходишь для этого.$B$BОтнеси эти приказы Бетору, а он расскажет, в чем состоит твоя миссия. Деталей я не знаю, могу сказать лишь то, что речь пойдет о найме заблудшего лича. Это очень опасное дело.$B$BПриготовься как следует, |3-6($c). Не подведи нас.$B$BБетора можно найти в Квартале Магов Подгорода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите приказы Севрена Бетору Ледострелу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, так тебя прислал мировой судья Севрен. Тогда да, дело у нас с тобой очень важное.\n\nУверен, Севрен выбрал того, кто справится с моим заданием, но… ладно, посмотрим.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Здравствуй. Либо ты не знаешь, кто я, либо у тебя ко мне очень срочное дело.\n\nПотому что иначе ты не посмел бы меня беспокоить…',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (406,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (407,'Поля Горя','Безвредные тыковки, да? Это только так кажется. Если мы хотим победить силы Артаса на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития.$B$BЧуть-чуть смекалки, и простая тыква превратится в шпиона Темной Госпожи. С помощью моей последней формулы эта тыква станет лакомым блюдом.$B$BВот недавно мы поймали еще одного ревнителя Алого ордена, сейчас он сидит в погребе таверны "Петля Висельника". Иди, отнеси ему эту тыкву.','Отнесите отравленную тыкву пленному ревнителю Алого ордена, которого держат в погребе таверны "Петля Висельника".','Благословенный Свет! Наконец-то еда! Сладенькая тыквочка...','Прочь, нечестивое созданье! Свет, защити меня! Алый орден избавит Азерот от таких...\n\nОй... Это что, еда для меня? Я умираю с голода...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поля Горя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Безвредные тыковки, да? Это только так кажется. Если мы хотим победить силы Артаса на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития.$B$BЧуть-чуть смекалки, и простая тыква превратится в шпиона Темной Госпожи. С помощью моей последней формулы эта тыква станет лакомым блюдом.$B$BВот недавно мы поймали еще одного ревнителя Алого ордена, сейчас он сидит в погребе таверны "Петля Висельника". Иди, отнеси ему эту тыкву.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите отравленную тыкву пленному ревнителю Алого ордена, которого держат в погребе таверны "Петля Висельника".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благословенный Свет! Наконец-то еда! Сладенькая тыквочка...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прочь, нечестивое созданье! Свет, защити меня! Алый орден избавит Азерот от таких...\n\nОй... Это что, еда для меня? Я умираю с голода...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (408,'Семейный склеп','Мельницы Агамондов превратились в крепость Плети. Самая важная точка – это Семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом. С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас.$B$BТы не $gдолжен:должна; допустить этого. Отправляйся в Семейную усыпальницу Агамондов и убей их неупокоенных предков.$B$BА заодно принеси мне череп капитана Даргола.','Убейте 8 стенающих прародительниц и 8 гниющих предков.$B$BУбейте капитана Даргола и принесите его череп мировому судье Севрену в Брилл.','Вернитесь к мировому судье Севрену в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семейный склеп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мельницы Агамондов превратились в крепость Плети. Самая важная точка – это Семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом. С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас.$B$BТы не $gдолжен:должна; допустить этого. Отправляйся в Семейную усыпальницу Агамондов и убей их неупокоенных предков.$B$BА заодно принеси мне череп капитана Даргола.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 стенающих прародительниц и 8 гниющих предков.$B$BУбейте капитана Даргола и принесите его череп мировому судье Севрену в Брилл.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Севрену в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (409,'Доказательство преданности','Ты говоришь, что $gнеподвластен:неподвластна; воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают. Но прежде чем я поверю тебе, ты $gдолжен:должна; доказать то, что являешься врагом Плети.$B$BНа южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара.$B$BВозьми из этого ящика манящую свечу, зажги ее на алтаре, и Лилит пробудится. Убей ее, и я поверю, что ты – враг Короля-лича.','Возьмите манящую свечу.$B$BВызовите Лилит Нефару и убейте ее.$B$BВернитесь на остров к Гюнтеру.','Невероятно! Ты убил Лилит Нефару и тем самым доказал, что являешься врагом Плети!\n\nЯ думал, что я – единственный из нежити, обладающий свободой воли, но теперь вижу, что есть и другие, кто не поддался влиянию Короля-лича.','Старый, побитый, окровавленный стол.','Вернитесь к Гюнтеру Чародею на Заставу Алого Ордена, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доказательство преданности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты говоришь, что $gнеподвластен:неподвластна; воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают. Но прежде чем я поверю тебе, ты $gдолжен:должна; доказать то, что являешься врагом Плети.$B$BНа южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара.$B$BВозьми из этого ящика манящую свечу, зажги ее на алтаре, и Лилит пробудится. Убей ее, и я поверю, что ты – враг Короля-лича.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите манящую свечу.$B$BВызовите Лилит Нефару и убейте ее.$B$BВернитесь на остров к Гюнтеру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно! Ты убил Лилит Нефару и тем самым доказал, что являешься врагом Плети!\n\nЯ думал, что я – единственный из нежити, обладающий свободой воли, но теперь вижу, что есть и другие, кто не поддался влиянию Короля-лича.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Старый, побитый, окровавленный стол.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гюнтеру Чародею на Заставу Алого Ордена, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (410,'Спящая тень','Вы ставите на стол Манящую свечу и зажигаете ее...','Это старый, побитый, окровавленный стол.','Вернитесь к обеденному столу Лилит в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спящая тень',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы ставите на стол Манящую свечу и зажигаете ее...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это старый, побитый, окровавленный стол.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к обеденному столу Лилит в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (411,'Возвращение блудного лича','Отнеси этот самоцвет Пустоты моему старому товарищу Бетору. С его помощью мы сможем общаться, а мне очень многое надо ему сказать.','Отнесите самоцвет Пустоты Бетору Ледострелу в Подгород.','Ты вернул книгу Гюнтеру? Что он сказал?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение блудного лича',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси этот самоцвет Пустоты моему старому товарищу Бетору. С его помощью мы сможем общаться, а мне очень многое надо ему сказать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите самоцвет Пустоты Бетору Ледострелу в Подгород.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернул книгу Гюнтеру? Что он сказал?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (412,'Операция "Перенаправление"','Мне следует вернуться в Гномреган и продолжить исследования, чтобы найти способ вылечить облученных гномов.$b$bНо я оставался в Караносе, потому что это мой город, и я хотел помочь защитить его от атак Мерзлогривов. Я занимался техобслуживанием и ремонтом паровых танков.$b$bПо какой-то причине падальщики Мерзлогривов стали таскать у меня гиромеханические шестерни, которые нужны для завершения ремонта. Все они на передовой Мерзлогривов. Не поможешь мне вернуть эти шестерни?','Принесите Раззлу Шустрецу 8 гиромеханических шестерней.','Вернитесь к Раззлу Шустрецу в Каранос.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Операция "Перенаправление"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне следует вернуться в Гномреган и продолжить исследования, чтобы найти способ вылечить облученных гномов.$b$bНо я оставался в Караносе, потому что это мой город, и я хотел помочь защитить его от атак Мерзлогривов. Я занимался техобслуживанием и ремонтом паровых танков.$b$bПо какой-то причине падальщики Мерзлогривов стали таскать у меня гиромеханические шестерни, которые нужны для завершения ремонта. Все они на передовой Мерзлогривов. Не поможешь мне вернуть эти шестерни?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Раззлу Шустрецу 8 гиромеханических шестерней.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Раззлу Шустрецу в Каранос.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (413,'"Мерцающий портер"','Хотелось бы мне, чтобы мой братец Велларт попробовал свежего "Мерцающего портера". Он горный пехотинец, их расквартировали в южной сторожевой башне, одной из двух на границе с озером Лок Модан.$B$BМожет, он и не такой пивовар, как остальные Ячменовары, но свое пиво он любит, и я знаю, что это тоже ему понравится.$B$BНе отнесешь ему вот этот бочонок "Мерцающего портера"?','Отнесите бочонок "Мерцающего портера" горному пехотинцу Ячменовару.','Горный пехотинец Ячменовар пробует "Мерцающий портер"... $B$BОх-х. Аж искры из глаз! Кажется, я даже в темноте видеть могу!','Привет, |3-6($c)! Что за дело привело тебя сюда?$B$BНадеюсь, что-нибудь стоящее. Я уже много дней не дрался хорошенько, да и этот бочонок эля уже почти пуст...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Мерцающий портер"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотелось бы мне, чтобы мой братец Велларт попробовал свежего "Мерцающего портера". Он горный пехотинец, их расквартировали в южной сторожевой башне, одной из двух на границе с озером Лок Модан.$B$BМожет, он и не такой пивовар, как остальные Ячменовары, но свое пиво он любит, и я знаю, что это тоже ему понравится.$B$BНе отнесешь ему вот этот бочонок "Мерцающего портера"?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите бочонок "Мерцающего портера" горному пехотинцу Ячменовару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Горный пехотинец Ячменовар пробует "Мерцающий портер"... $B$BОх-х. Аж искры из глаз! Кажется, я даже в темноте видеть могу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, |3-6($c)! Что за дело привело тебя сюда?$B$BНадеюсь, что-нибудь стоящее. Я уже много дней не дрался хорошенько, да и этот бочонок эля уже почти пуст...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (414,'Портер для Кэдрелла','Отнести бочонок "Мерцающего портера" горному пехотинцу Кэдреллу.','Ну-с, попробуем...$B$BКлянусь бородой Магни! Аж голова кругом пошла! И в теле легкость необыкновенная.$B$BСейчас полечу, как птичка!','Привет, |3-6($c), добро пожаловать в Телcамар!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Портер для Кэдрелла',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнести бочонок "Мерцающего портера" горному пехотинцу Кэдреллу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну-с, попробуем...$B$BКлянусь бородой Магни! Аж голова кругом пошла! И в теле легкость необыкновенная.$B$BСейчас полечу, как птичка!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, |3-6($c), добро пожаловать в Телcамар!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (415,'Новое пиво Регольда','Регольд Ячменовар, что живет в Поселке Пивоваров, спрашивал про тебя.$B$BОн хочет поговорить с тобой про свое новое пиво... Сказал вроде, что ты ему $Gпомог:помогла;. Можешь самолично вернуться в Поселок Пивоваров и спросить, что ему надо.$B$BМожет, тебя дармовая выпивка ждет...','Поговорите с Регольдом Ячменоваром.','$N! Помнишь тот звездолист, что ты $Gпринес:принесла; мне? Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно!$B$BВот, попробуй и скажи, как пошло...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое пиво Регольда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Регольд Ячменовар, что живет в Поселке Пивоваров, спрашивал про тебя.$B$BОн хочет поговорить с тобой про свое новое пиво... Сказал вроде, что ты ему $Gпомог:помогла;. Можешь самолично вернуться в Поселок Пивоваров и спросить, что ему надо.$B$BМожет, тебя дармовая выпивка ждет...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Регольдом Ячменоваром.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N! Помнишь тот звездолист, что ты $Gпринес:принесла; мне? Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно!$B$BВот, попробуй и скажи, как пошло...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (416,'Ловля крыс','К западу отсюда началось настоящее нашествие. Эти подземные крысы, кобольды-туннельщики, обосновались в предгорьях, устроили там свои логовища и оскверняют нашу прекрасную землю!$b$BИх необходимо истребить. Перебей их как можно больше, принеси в доказательство уши и получишь награду.$B$BКобольды-туннельщиков поселились на востоке отсюда, в районе Серебряных копей.','Принесите 8 ушей туннельщиков горному пехотинцу Грозовой Вершине на станцию Альгаз.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловля крыс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К западу отсюда началось настоящее нашествие. Эти подземные крысы, кобольды-туннельщики, обосновались в предгорьях, устроили там свои логовища и оскверняют нашу прекрасную землю!$b$BИх необходимо истребить. Перебей их как можно больше, принеси в доказательство уши и получишь награду.$B$BКобольды-туннельщиков поселились на востоке отсюда, в районе Серебряных копей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 ушей туннельщиков горному пехотинцу Грозовой Вершине на станцию Альгаз.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (417,'Месть пилота','Убейте Паршивого Когтя.$B$BПринесите его коготь и дневник Хилдельва пилоту Большеногу на заставу у Южных врат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть пилота',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Паршивого Когтя.$B$BПринесите его коготь и дневник Хилдельва пилоту Большеногу на заставу у Южных врат.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (418,'Телcамарские кровяные колбаски','Едоки в Телcамаре не переводятся – еще бы, детей полным-полно, после трудового дня работники ужинать хотят. Мы славимся кровяными колбасками. Но ты ведь их еще не $gпробовал:пробовала;?$b$bНет? Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение, |3-6($c).$b$bМне нужна медвежатина, все остальное уже есть. Добудь ее, а уж Видра сготовит все в лучшем виде!','Принесите Видре Жаркий Очаг в Телcамар 8 кусков медвежатины.','Поверь, со стороны готовка выглядит куда сложнее, чем на деле, но...$b$bХоть я и не встречала никого, кому бы захотелось научиться делать колбаски, но на всякий случай рецептик я тебе все же дам. Бери! Ешь, пока рот свеж!','Я давно собираюсь начать готовить; где же все компоненты?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Телcамарские кровяные колбаски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Едоки в Телcамаре не переводятся – еще бы, детей полным-полно, после трудового дня работники ужинать хотят. Мы славимся кровяными колбасками. Но ты ведь их еще не $gпробовал:пробовала;?$b$bНет? Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение, |3-6($c).$b$bМне нужна медвежатина, все остальное уже есть. Добудь ее, а уж Видра сготовит все в лучшем виде!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Видре Жаркий Очаг в Телcамар 8 кусков медвежатины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поверь, со стороны готовка выглядит куда сложнее, чем на деле, но...$b$bХоть я и не встречала никого, кому бы захотелось научиться делать колбаски, но на всякий случай рецептик я тебе все же дам. Бери! Ешь, пока рот свеж!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я давно собираюсь начать готовить; где же все компоненты?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (419,'Пропавший пилот','Мой друг и напарник, пилот осадной машины Мори Хилдельв, пропал в этих холмах. Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков мы загнали его машину на крутой холм, там она сломалась!$B$BХилдельв, по-прежнему уверенный, что руда в этих горах есть, оставил меня охранять наши машины, а сам пошел дальше пешком.$B$BНо прошло уже несколько дней, а ночью я слышал какой-то звериный вой севернее озера Хельмово Ложе, к западу от туннеля. Мори – парень-кремень, но мне тревожно.$B$BПрошу тебя, $n, найди его.','Пилот Большеног с заставы у Южных врат просит вас найти пилота Хилдельва.','Перед вами труп дворфа – изуродованный, застывший и сильно обглоданный горными хищниками. В руке он сжимает записную книжку с грубо нацарапанными записями Мори Хилдельва. Труп одет во все еще превосходно сохранившийся жилет бригадира.$B$BЭта мрачная сцена показывает, где встретил свой конец пилот Осадной машины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший пилот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой друг и напарник, пилот осадной машины Мори Хилдельв, пропал в этих холмах. Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков мы загнали его машину на крутой холм, там она сломалась!$B$BХилдельв, по-прежнему уверенный, что руда в этих горах есть, оставил меня охранять наши машины, а сам пошел дальше пешком.$B$BНо прошло уже несколько дней, а ночью я слышал какой-то звериный вой севернее озера Хельмово Ложе, к западу от туннеля. Мори – парень-кремень, но мне тревожно.$B$BПрошу тебя, $n, найди его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пилот Большеног с заставы у Южных врат просит вас найти пилота Хилдельва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Перед вами труп дворфа – изуродованный, застывший и сильно обглоданный горными хищниками. В руке он сжимает записную книжку с грубо нацарапанными записями Мори Хилдельва. Труп одет во все еще превосходно сохранившийся жилет бригадира.$B$BЭта мрачная сцена показывает, где встретил свой конец пилот Осадной машины.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (420,'Наблюдения Сенира','Трогги, поселившиеся в тоннелях, крайне враждебны: они без раздумий нападают на любого, кто только осмелится туда сунуться. С другой стороны, что-то мне подсказывает, что у тебя хватит сил и умения, чтобы с ними справиться.$b$bЕсли тебе хочется побеседовать с Сениром, то его можно отыскать в Караносе.$b$bА добраться туда и вовсе просто: пройдешь весь тоннель насквозь, а дальше шагай себе по дороге до самого до города Караноса.','Доставьте донесение Грелина Сениру Белобороду в Караносе.','А что это у нас тут такое? О, донесение от моего братца! Хм-м...\n\nГоворил я ему, нечего поминать королевское имя всуе, да только станет он меня слушать! С другой стороны, кое-кому в Совете не мешает попортить кровь. Ха!\n\nКак бы то ни было, думаю, мне нужно и свое донесение отправить в Стальгорн. Как-то запоздал я с этим делом. Все этот проклятый холод!\n\nСлушай, если тебе это интересно, у меня скоро может найтись для тебя кое-какая работенка...','О, приветствую! Как дела? Не хочешь пропустить стаканчик? В такой холод только этим и спасаешься.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наблюдения Сенира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Трогги, поселившиеся в тоннелях, крайне враждебны: они без раздумий нападают на любого, кто только осмелится туда сунуться. С другой стороны, что-то мне подсказывает, что у тебя хватит сил и умения, чтобы с ними справиться.$b$bЕсли тебе хочется побеседовать с Сениром, то его можно отыскать в Караносе.$b$bА добраться туда и вовсе просто: пройдешь весь тоннель насквозь, а дальше шагай себе по дороге до самого до города Караноса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте донесение Грелина Сениру Белобороду в Караносе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А что это у нас тут такое? О, донесение от моего братца! Хм-м...\n\nГоворил я ему, нечего поминать королевское имя всуе, да только станет он меня слушать! С другой стороны, кое-кому в Совете не мешает попортить кровь. Ха!\n\nКак бы то ни было, думаю, мне нужно и свое донесение отправить в Стальгорн. Как-то запоздал я с этим делом. Все этот проклятый холод!\n\nСлушай, если тебе это интересно, у меня скоро может найтись для тебя кое-какая работенка...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, приветствую! Как дела? Не хочешь пропустить стаканчик? В такой холод только этим и спасаешься.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (421,'Проявить себя','Леди Сильвана поручила Вариматасу завоевать земли людей и дворфов к югу. $b$bНо этот идиот Аругал – даларанский шарлатан, а ныне проклятая тварь из крепости Темного Клыка – позволил своей бездумной магии нанести ущерб стратегической цитадели Серебряного бора. $b$bМне нужен кто-то, искушенный в воинском деле, чтобы разрубить узел, завязанный Аругалом. Убейте 5 белоголовов Лунной Ярости и докажите, что вы – тот, кого я ищу. Этих мерзких зверей легко можно встретить у самой дороги, внизу под холмом.','Далар Ткач Рассвета из Гробницы хочет, чтобы вы убили 5 белоголовов Лунной Ярости.','Вы сослужили мне хорошую службу, |3-6($C). Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала.','Убит ли Ивар Нечистый? Если вы не готовы сделать это для меня и моего брата, убейте его ради Отрекшихся.','Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проявить себя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Леди Сильвана поручила Вариматасу завоевать земли людей и дворфов к югу. $b$bНо этот идиот Аругал – даларанский шарлатан, а ныне проклятая тварь из крепости Темного Клыка – позволил своей бездумной магии нанести ущерб стратегической цитадели Серебряного бора. $b$bМне нужен кто-то, искушенный в воинском деле, чтобы разрубить узел, завязанный Аругалом. Убейте 5 белоголовов Лунной Ярости и докажите, что вы – тот, кого я ищу. Этих мерзких зверей легко можно встретить у самой дороги, внизу под холмом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Далар Ткач Рассвета из Гробницы хочет, чтобы вы убили 5 белоголовов Лунной Ярости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы сослужили мне хорошую службу, |3-6($C). Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Убит ли Ивар Нечистый? Если вы не готовы сделать это для меня и моего брата, убейте его ради Отрекшихся.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (422,'Безрассудство Аругала','Раздобудьте книгу "Зелье Аругала" и принесите ее Далару Ткачу Рассвета в Гробницу.','Да, это именно та книга, которую я искал, |3-6($C). Если ваша приверженность делу Темной Госпожи не ослабела, вас ждет неплохое будущее среди Отрекшихся.','Чтобы понять, с чем мы имеем дело, |3-6($C), мне нужно внимательно изучить книгу "Зелье Аругала". Принесите его мне, или мне придется поискать себе достойного слугу','Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безрассудство Аругала',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте книгу "Зелье Аругала" и принесите ее Далару Ткачу Рассвета в Гробницу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это именно та книга, которую я искал, |3-6($C). Если ваша приверженность делу Темной Госпожи не ослабела, вас ждет неплохое будущее среди Отрекшихся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы понять, с чем мы имеем дело, |3-6($C), мне нужно внимательно изучить книгу "Зелье Аругала". Принесите его мне, или мне придется поискать себе достойного слугу',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (423,'Безрассудство Аругала','Изучив деятельность Аругала, я понял, что мои наихудшие подозрения верны. Старый хрыч был недостоин даже ночные горшки выносить в Даларане, не говоря уж о том, чтобы представлять Кирин-Тор в самый трудный час. Идиоты! $b$bДля усиления своей никудышной магии Аругал использовал заколдованные предметы. В первую очередь я должен изучить эти предметы. Отправляйся в путь и убивай обжор Лунной Ярости и чернозлобов Лунной Ярости, пока не наберешь столько заколдованных наручей, сколько потребуется для моих исследований. Эти злобные создания обитают к северу и к востоку отсюда.','Принесите Далару Ткачу Рассвета в Гробницу 6 наручей обжор Лунной Ярости и 3 наруча чернозлобов Лунной Ярости.','Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала. Вероятно, мне следовало поручить вам добыть больше наручей. \n\nТем не менее, вы отменно проявили себя, собирая эти, |3-6($C).','Мне понадобятся 6 наручей обжор и 3 наруча чернозлобов, чтобы я мог полностью разобраться с ситуацией и определиться с окончательным решением по Аругалу. А теперь – за дело. Убивайте обжор Лунной Ярости и чернозлобов Лунной Ярости, пока не наберете всего, что мне нужно.','Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безрассудство Аругала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изучив деятельность Аругала, я понял, что мои наихудшие подозрения верны. Старый хрыч был недостоин даже ночные горшки выносить в Даларане, не говоря уж о том, чтобы представлять Кирин-Тор в самый трудный час. Идиоты! $b$bДля усиления своей никудышной магии Аругал использовал заколдованные предметы. В первую очередь я должен изучить эти предметы. Отправляйся в путь и убивай обжор Лунной Ярости и чернозлобов Лунной Ярости, пока не наберешь столько заколдованных наручей, сколько потребуется для моих исследований. Эти злобные создания обитают к северу и к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Далару Ткачу Рассвета в Гробницу 6 наручей обжор Лунной Ярости и 3 наруча чернозлобов Лунной Ярости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала. Вероятно, мне следовало поручить вам добыть больше наручей. \n\nТем не менее, вы отменно проявили себя, собирая эти, |3-6($C).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне понадобятся 6 наручей обжор и 3 наруча чернозлобов, чтобы я мог полностью разобраться с ситуацией и определиться с окончательным решением по Аругалу. А теперь – за дело. Убивайте обжор Лунной Ярости и чернозлобов Лунной Ярости, пока не наберете всего, что мне нужно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (424,'Безрассудство Аругала','Мне потребуется больше времени на раскрытие темных тайн чар Аругала,чем я думал. $b$bНо тем временем мне нужно, чтобы вы помогли разрешить одну небольшую проблему, которую обнаружили наши разведчики. Похоже, Аругал распространил свою магию на Серебряный рудник, находящийся в холмах к юго-востоку отсюда. $b$bЭтот рудник стал бы ценным ресурсом для Вариматаса. $b$bЯ хочу, чтобы вы снесли голову с плеч пораженному скверной старшине рудника Мрачнону Белесому. После его смерти рудник будет нашим.','Убейте Мрачнона Белесого и принесите его голову Далару Ткачу Рассвета в Гробницу.','Великолепно. Рудник обеспечит нас отменными ресурсами для наших сил по мере нашего продвижения по Серебряному бору и далее по Азероту.','Убит ли Мрачнон Белесый? Вариматасу вряд ли понравится, если мы проигнорируем его повеление.','Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безрассудство Аругала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне потребуется больше времени на раскрытие темных тайн чар Аругала,чем я думал. $b$bНо тем временем мне нужно, чтобы вы помогли разрешить одну небольшую проблему, которую обнаружили наши разведчики. Похоже, Аругал распространил свою магию на Серебряный рудник, находящийся в холмах к юго-востоку отсюда. $b$bЭтот рудник стал бы ценным ресурсом для Вариматаса. $b$bЯ хочу, чтобы вы снесли голову с плеч пораженному скверной старшине рудника Мрачнону Белесому. После его смерти рудник будет нашим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Мрачнона Белесого и принесите его голову Далару Ткачу Рассвета в Гробницу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Рудник обеспечит нас отменными ресурсами для наших сил по мере нашего продвижения по Серебряному бору и далее по Азероту.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Убит ли Мрачнон Белесый? Вариматасу вряд ли понравится, если мы проигнорируем его повеление.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (425,'Ивар Нечистый','Нам с моим братом Квинном было поручено провести рекогносцировку в Серебряном бору и отчитаться перед верховным палачом Хадриком. Но далеко продвинуться мы не сумели: когда мы проходили через эту ферму, нас атаковал вурдалак Ивар Нечистый. $b$bНам удалось уйти от Ивара, но он успел как следует приложить Квинна. Мой брат поправляется от зелья, что вы ему дали, но Ивар может вернуться раньше, чем Квинн совсем встанет на ноги. $b$bУбейте Ивара, чтобы Квинн мог спокойно поправляться. Обычно Ивар торчит в том амбаре – поджидает, когда я утрачу бдительность.','Убейте Ивара Нечистого и принесите его голову Ран Йорик на делянку Ивара.','Убит ли Ивар Нечистый? Если вы не готовы сделать это для меня и моего брата, убейте его ради Отрекшихся.','Вернитесь к Ран Йорик в Серебряный бор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ивар Нечистый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам с моим братом Квинном было поручено провести рекогносцировку в Серебряном бору и отчитаться перед верховным палачом Хадриком. Но далеко продвинуться мы не сумели: когда мы проходили через эту ферму, нас атаковал вурдалак Ивар Нечистый. $b$bНам удалось уйти от Ивара, но он успел как следует приложить Квинна. Мой брат поправляется от зелья, что вы ему дали, но Ивар может вернуться раньше, чем Квинн совсем встанет на ноги. $b$bУбейте Ивара, чтобы Квинн мог спокойно поправляться. Обычно Ивар торчит в том амбаре – поджидает, когда я утрачу бдительность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ивара Нечистого и принесите его голову Ран Йорик на делянку Ивара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Убит ли Ивар Нечистый? Если вы не готовы сделать это для меня и моего брата, убейте его ради Отрекшихся.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ран Йорик в Серебряный бор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (426,'Нападение на мельницы','Плеть пытается основать базу на Мельницах Агамондов. Если им это удастся, они продолжат свои нападения в Тирисфале.$B$BПоступил приказ уничтожить всю Плеть на мельницах.$B$BОтправляйся туда и собери зазубренные ребра костетрясов-солдат и костеголовых солдат, а также почерневшие черепа мрачнооких скелетов-заклинателей.$B$BЧтобы добраться до мельниц, иди по дороге на запад. После того как перейдешь мост, поверни на север, и скоро увидишь ветряные мельницы.','Соберите 5 зазубренных ребер и 3 почерневших черепа для стража смерти Диллинджера в Брилле.','Вернитесь к стражу смерти Диллинжеру в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на мельницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плеть пытается основать базу на Мельницах Агамондов. Если им это удастся, они продолжат свои нападения в Тирисфале.$B$BПоступил приказ уничтожить всю Плеть на мельницах.$B$BОтправляйся туда и собери зазубренные ребра костетрясов-солдат и костеголовых солдат, а также почерневшие черепа мрачнооких скелетов-заклинателей.$B$BЧтобы добраться до мельниц, иди по дороге на запад. После того как перейдешь мост, поверни на север, и скоро увидишь ветряные мельницы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 зазубренных ребер и 3 почерневших черепа для стража смерти Диллинджера в Брилле.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Диллинжеру в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (427,'Война с Алым орденом','Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах.$B$BНо у стражей смерти есть заботы и поважнее: армия Короля-лича растет с каждой ночью. Нам нужен кто-то такой "инициативный", как ты, чтобы навсегда покончить с Алым орденом.$B$BДокажи мне, что $Gспособен:способна; служить Темной Госпоже: отправляйся на запад, к башне за усадьбой Соллиден, и убей 10 воинов из Алого ордена.','Убейте 10 воинов из Алого ордена по просьбе палача Зуганда.','Замечательно, |3-6($C). Ваши боевые умения не вызывают сомнений.','Если ты хочешь доказать свою ценность Темной Госпоже, убей 10 воинов из Алого ордена, $C.','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война с Алым орденом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом. Теперь мы знаем расположение всех их баз в Тирисфальских лесах.$B$BНо у стражей смерти есть заботы и поважнее: армия Короля-лича растет с каждой ночью. Нам нужен кто-то такой "инициативный", как ты, чтобы навсегда покончить с Алым орденом.$B$BДокажи мне, что $Gспособен:способна; служить Темной Госпоже: отправляйся на запад, к башне за усадьбой Соллиден, и убей 10 воинов из Алого ордена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 воинов из Алого ордена по просьбе палача Зуганда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно, |3-6($C). Ваши боевые умения не вызывают сомнений.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты хочешь доказать свою ценность Темной Госпоже, убей 10 воинов из Алого ордена, $C.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к палачу Зуганду в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (428,'Пропавшие ловчие смерти','Пару недель назад двое наших ловчих смерти – Ран и Квинн Йорик, ушли на разведывательное задание в северный Серебряный бор. С тех пор от них не было никаких известий. $b$bОни могли стать жертвами Плети, но даже если это так, мне нужно подтверждение. Найдите этих ловчих смерти. $b$bИх первой целью была разведка на полях в северной части Серебряного бора. Начните свои поиски там.','Найдите ловчих смерти Квинна Йорика и Ран Йорик.','Вы нашли нас! Еще чуть-чуть – и было бы уже поздно...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие ловчие смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пару недель назад двое наших ловчих смерти – Ран и Квинн Йорик, ушли на разведывательное задание в северный Серебряный бор. С тех пор от них не было никаких известий. $b$bОни могли стать жертвами Плети, но даже если это так, мне нужно подтверждение. Найдите этих ловчих смерти. $b$bИх первой целью была разведка на полях в северной части Серебряного бора. Начните свои поиски там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ловчих смерти Квинна Йорика и Ран Йорик.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы нашли нас! Еще чуть-чуть – и было бы уже поздно...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (429,'Звериные сердца','Мой брат Квинн был тяжело ранен вурдалаком, Иваром Нечистым, и я не знаю, сможет ли он как следует поправиться без помощи магии. Хотя я сама и не фармацевт, но знаю, что наши аптекари могут изготавливать исцеляющие зелья из обесцвеченных сердец воргов. $b$bСобери такие сердца и отнеси их аптекарю Ренферрелу к Гробнице, на юг отсюда. А потом возвращайся ко мне с зельем. $b$bМножество воргов водится между этим местом и садом Мальдена к востоку отсюда.','Соберите 6 обесцвеченных сердец ворга и принесите их аптекарю Ренферрелу в Гробницу.','Ренферрел берет у вас сердца.\n\nМеня тревожит известие о том, что наши стражи смерти потерпели неудачу в своей миссии. \n\nБудем надеяться, что таких неудач будет немного. \n\nЯ сейчас дам зелье, но вот вам рецепт – если стражам смерти понадобится дальнейшая помощь, быть может, вы сами сможете им ее оказать.','У меня мало времени, |3-6($C): Темная Госпожа возложила на меня тяжелую задачу.','Вернитесь к аптекарю Ренферрелу в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звериные сердца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой брат Квинн был тяжело ранен вурдалаком, Иваром Нечистым, и я не знаю, сможет ли он как следует поправиться без помощи магии. Хотя я сама и не фармацевт, но знаю, что наши аптекари могут изготавливать исцеляющие зелья из обесцвеченных сердец воргов. $b$bСобери такие сердца и отнеси их аптекарю Ренферрелу к Гробнице, на юг отсюда. А потом возвращайся ко мне с зельем. $b$bМножество воргов водится между этим местом и садом Мальдена к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 обесцвеченных сердец ворга и принесите их аптекарю Ренферрелу в Гробницу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ренферрел берет у вас сердца.\n\nМеня тревожит известие о том, что наши стражи смерти потерпели неудачу в своей миссии. \n\nБудем надеяться, что таких неудач будет немного. \n\nЯ сейчас дам зелье, но вот вам рецепт – если стражам смерти понадобится дальнейшая помощь, быть может, вы сами сможете им ее оказать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня мало времени, |3-6($C): Темная Госпожа возложила на меня тяжелую задачу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Ренферрелу в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (430,'Назад к Квинну','Вот зелье, которое должно помочь Квинну Йорику поправиться. $b$bА теперь, простите, мне нужно продолжить одно очень важное дело...','Отнесите зелье Квинна Квинну Йорику на делянку Ивара, к северу от Гробницы.','Моя сестра сказала, что вы поможете нам. Это правда?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад к Квинну',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот зелье, которое должно помочь Квинну Йорику поправиться. $b$bА теперь, простите, мне нужно продолжить одно очень важное дело...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите зелье Квинна Квинну Йорику на делянку Ивара, к северу от Гробницы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Моя сестра сказала, что вы поможете нам. Это правда?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (431,'Манящие свечи','Вы берете одну свечу и кладете ее в сумку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Манящие свечи',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы берете одну свечу и кладете ее в сумку.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (432,'Проклятые трогги!','Эти проклятые Светом трогги перевернули все мое рабочее место! Ты только глянь, еще одну бочку пороха разворотили!$b$bОх, прямо руки чешутся спуститься к ним да головы поотрывать! Всех бы поубивал!$b$bНо здоровье не позволяет, да еще это потрясение и злость... Они ничего мне не оставили!$b$bЯ бы сам их перебил, да рука уже не так тверда! Иди в карьер и перебей грязных тварей! Я заплачу! Ты только задай им шороху, перебей их!','Убейте 8 головоломов из племени Каменной Челюсти и 8 костегрызов из племени Каменной Челюсти в карьере Гол\'Болар.','Гр-р-р… Как я зол!','Вернитесь к штейгеру Камнелобу в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятые трогги!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти проклятые Светом трогги перевернули все мое рабочее место! Ты только глянь, еще одну бочку пороха разворотили!$b$bОх, прямо руки чешутся спуститься к ним да головы поотрывать! Всех бы поубивал!$b$bНо здоровье не позволяет, да еще это потрясение и злость... Они ничего мне не оставили!$b$bЯ бы сам их перебил, да рука уже не так тверда! Иди в карьер и перебей грязных тварей! Я заплачу! Ты только задай им шороху, перебей их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 головоломов из племени Каменной Челюсти и 8 костегрызов из племени Каменной Челюсти в карьере Гол\'Болар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гр-р-р… Как я зол!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Камнелобу в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (433,'Слуга народа','Будучи членом Сената и Лиги исследователей, я взял на себя заботу по изучению условий работы в карьере. Трогги совсем распоясались!$b$bОни просто разнесли весь карьер Гол\'Болар. Чем глубже мы копаем, тем больше их лезет наружу, уничтожая наше оборудование и заманивая горняков в подземные ловушки.$b$bМы должны выдворить их оттуда. Мои маги работают сверхурочно, чтобы наложить чары на эти руны возвращения. Если ты сможешь отнести руны захваченным шахтерам, они смогут безопасно вернуться на поверхность.','Раздайте руны возвращения 7 захваченным шахтерам в карьере Гол\'Болар.','Если мы сможем изгнать троггов из карьера Гол\'Болар, это будет первый шаг на долгом пути к избавлению от этой заразы.','Вернитесь к сенатору Меру Каменной Реликвии в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слуга народа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Будучи членом Сената и Лиги исследователей, я взял на себя заботу по изучению условий работы в карьере. Трогги совсем распоясались!$b$bОни просто разнесли весь карьер Гол\'Болар. Чем глубже мы копаем, тем больше их лезет наружу, уничтожая наше оборудование и заманивая горняков в подземные ловушки.$b$bМы должны выдворить их оттуда. Мои маги работают сверхурочно, чтобы наложить чары на эти руны возвращения. Если ты сможешь отнести руны захваченным шахтерам, они смогут безопасно вернуться на поверхность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздайте руны возвращения 7 захваченным шахтерам в карьере Гол\'Болар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если мы сможем изгнать троггов из карьера Гол\'Болар, это будет первый шаг на долгом пути к избавлению от этой заразы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сенатору Меру Каменной Реликвии в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (434,'Нападение!','Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Гвардия пропустит его без особых проблем.$B$BПока ты $Gсобирал:собирала; для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром. Я даже подкинул ему пару ложных слухов.$B$BЛесковар отпустит свою охрану и будет дожидаться Марзона в саду. Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения гвардейцев! После этого поговори с Триасом.','Спрячьтесь в саду и подслушайте разговор лорда Грегора Лесковара и Марзона Бесшумного Клинка. После этого убейте обоих и возвращайтесь к Иллингу Триасу в Штормград.','Сделано? Отлично. $n, благодарю вас за посильное участие. Вы оказали Штормовому Оплоту не одну услугу. С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса.$B$BПостарайтесь ни во что не вляпаться.','Да, $N? С Тирионом дела идут хорошо? Он проинформировал меня о ситуации, и я помог ему обманом заставить Марзона пойти в замок.$B$BМарзон был занозой для многих людей в Штормграде; многие из которых мои близкие друзья. Никто не ...','Подслушайте разговор Лесковара и Марзона','Вернитесь к Иллингу Триасу в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Гвардия пропустит его без особых проблем.$B$BПока ты $Gсобирал:собирала; для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром. Я даже подкинул ему пару ложных слухов.$B$BЛесковар отпустит свою охрану и будет дожидаться Марзона в саду. Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения гвардейцев! После этого поговори с Триасом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спрячьтесь в саду и подслушайте разговор лорда Грегора Лесковара и Марзона Бесшумного Клинка. После этого убейте обоих и возвращайтесь к Иллингу Триасу в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сделано? Отлично. $n, благодарю вас за посильное участие. Вы оказали Штормовому Оплоту не одну услугу. С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса.$B$BПостарайтесь ни во что не вляпаться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N? С Тирионом дела идут хорошо? Он проинформировал меня о ситуации, и я помог ему обманом заставить Марзона пойти в замок.$B$BМарзон был занозой для многих людей в Штормграде; многие из которых мои близкие друзья. Никто не ...',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Подслушайте разговор Лесковара и Марзона',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иллингу Триасу в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (435,'Сопровождая Эрланда','Волки там, снаружи, никуда не уйдут, и они злобно смотрят на меня каждый раз, когда я выхожу из двери. Должно быть, они невероятно голодны, раз смогли счесть меня пищей. $b$bЯ должен доложиться своей коллеге, ловчей смерти Ран Йорик. Но чтобы добраться до Ран, мне нужна помощь против этих волков.$b$bПожалуйста, проводите меня! Волков здесь очень много, так что наши шансы будут выше, если у вас есть готовые помочь друзья...','Проводите Эрланда, защищая его от волков, к Ран Йорик.','Ты вернул книгу Гюнтеру? Что он сказал?','Проводите Эрланда к Ран Йорик.','Вернитесь к Ран Йорик в Серебряный бор.','Проводите Эрланда к Ран Йорик.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сопровождая Эрланда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волки там, снаружи, никуда не уйдут, и они злобно смотрят на меня каждый раз, когда я выхожу из двери. Должно быть, они невероятно голодны, раз смогли счесть меня пищей. $b$bЯ должен доложиться своей коллеге, ловчей смерти Ран Йорик. Но чтобы добраться до Ран, мне нужна помощь против этих волков.$b$bПожалуйста, проводите меня! Волков здесь очень много, так что наши шансы будут выше, если у вас есть готовые помочь друзья...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите Эрланда, защищая его от волков, к Ран Йорик.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернул книгу Гюнтеру? Что он сказал?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводите Эрланда к Ран Йорик.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ран Йорик в Серебряный бор.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Проводите Эрланда к Ран Йорик.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (436,'Раскопки Сталекрута','Геолог Сталекрут возглавляет раскопки в древних руинах к востоку от озера. В последнее время дело продвигается медленно – и это учитывая, сколько мы послали туда припасов!$B$BСталекрут – надежный, честный дворф, который прежде всего болеет за результат, потому-то я и думаю, что кто-то решил ему помешать.$B$BОтправляйся к раскопкам Сталекрута и обратись к Магмару Рудоколу. Он ведет отчетность по раскопкам и сможет объяснить, чем вызвана задержка.$B$BЧтобы отыскать раскопки, обогни озеро с юга и направляйся на восток.','Обратитесь к исследователю Удару Топора.','Значит, Джерн хочет узнать, чем вызвана задержка?$B$BЖелезняк как раз пишет подробный отчет о своих последних достижениях, но я буду краток.$B$BДело в троггах!!!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раскопки Сталекрута',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Геолог Сталекрут возглавляет раскопки в древних руинах к востоку от озера. В последнее время дело продвигается медленно – и это учитывая, сколько мы послали туда припасов!$B$BСталекрут – надежный, честный дворф, который прежде всего болеет за результат, потому-то я и думаю, что кто-то решил ему помешать.$B$BОтправляйся к раскопкам Сталекрута и обратись к Магмару Рудоколу. Он ведет отчетность по раскопкам и сможет объяснить, чем вызвана задержка.$B$BЧтобы отыскать раскопки, обогни озеро с юга и направляйся на восток.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к исследователю Удару Топора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Джерн хочет узнать, чем вызвана задержка?$B$BЖелезняк как раз пишет подробный отчет о своих последних достижениях, но я буду краток.$B$BДело в троггах!!!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (437,'Мертвые поля','Первые отчеты наших разведчиков в Серебряном бору говорят о том, что Гнилошкуры устроили базу на заброшенном поле к северу отсюда – на Мертвом поле. Мы посылали против них небольшие группы, но им каждый раз помогала банши Плеть Ночи, которая своей магией обращала наших воинов в бегство. $b$bМы хотим уничтожить Плеть Ночи. $b$bОтправляйтесь на Мертвое поле и атакуйте Гнилошкуров. Убивайте их до тех пор, пока не покажется Плеть Ночи, а затем убейте и ее. $b$bСущность банши обратится в прах. Принесите мне этот прах в доказательство ее смерти.','Убивайте гноллов из стаи Гнилошкуров на Мертвом поле. $b$bКогда появится банши Плеть Ночи, убейте ее. $b$bСущность банши принесите верховному палачу Хадрику в Гробницу.','Войти на Мертвое поле','Вернитесь к верховному палачу Хадрику в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мертвые поля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первые отчеты наших разведчиков в Серебряном бору говорят о том, что Гнилошкуры устроили базу на заброшенном поле к северу отсюда – на Мертвом поле. Мы посылали против них небольшие группы, но им каждый раз помогала банши Плеть Ночи, которая своей магией обращала наших воинов в бегство. $b$bМы хотим уничтожить Плеть Ночи. $b$bОтправляйтесь на Мертвое поле и атакуйте Гнилошкуров. Убивайте их до тех пор, пока не покажется Плеть Ночи, а затем убейте и ее. $b$bСущность банши обратится в прах. Принесите мне этот прах в доказательство ее смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте гноллов из стаи Гнилошкуров на Мертвом поле. $b$bКогда появится банши Плеть Ночи, убейте ее. $b$bСущность банши принесите верховному палачу Хадрику в Гробницу.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Войти на Мертвое поле',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Хадрику в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (438,'Старая переправа','$n, мы обнаружили еще одно место, где угнездилась Плеть: это старая переправа. Переправа находится к востоку от Гробницы, и ее патрулируют многочисленные гноллы-гнилошкуры и различная нежить. $b$bПолагаю, Плеть захватила это место неспроста. Отправляйся к старой переправе и выясни, в чем там дело.','Отправляйтесь к старой переправе. $b$bПоищите причину присутствия там сил Плети.','В лодке находится куча спеленутых мертвых тел. А если смотреть на восток через озеро Лордамер, то напротив видна пристань на острове Фенриса. \n\nДолжно быть, разгадку этой тайны стоит искать на острове.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старая переправа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мы обнаружили еще одно место, где угнездилась Плеть: это старая переправа. Переправа находится к востоку от Гробницы, и ее патрулируют многочисленные гноллы-гнилошкуры и различная нежить. $b$bПолагаю, Плеть захватила это место неспроста. Отправляйся к старой переправе и выясни, в чем там дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к старой переправе. $b$bПоищите причину присутствия там сил Плети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В лодке находится куча спеленутых мертвых тел. А если смотреть на восток через озеро Лордамер, то напротив видна пристань на острове Фенриса. \n\nДолжно быть, разгадку этой тайны стоит искать на острове.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (439,'Необычная находка','Из кучи трупов торчит обнаженная рука. Это рука женщины – тронутая чумой, но относительно свежая. $b$bНа пальце надето кольцо. Вы снимаете кольцо и, осмотрев его, обнаруживаете гравировку: $b$b"Делии".','Принесите кольцо Делии верховному палачу Хадрику в Гробницу.','Говорите, это кольцо было надето на палец недавно погибшей женщины? \n\nВидимо, тело было поднято из общей могилы в Тирисфале, не иначе. Должно быть, гноллы-гнилошкуры таскают эти трупы на остров Фенриса!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычная находка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из кучи трупов торчит обнаженная рука. Это рука женщины – тронутая чумой, но относительно свежая. $b$bНа пальце надето кольцо. Вы снимаете кольцо и, осмотрев его, обнаруживаете гравировку: $b$b"Делии".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите кольцо Делии верховному палачу Хадрику в Гробницу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говорите, это кольцо было надето на палец недавно погибшей женщины? \n\nВидимо, тело было поднято из общей могилы в Тирисфале, не иначе. Должно быть, гноллы-гнилошкуры таскают эти трупы на остров Фенриса!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (440,'Кольцо с гравировкой','Если хотите найти мужа или возлюбленного Делии – того, кто подарил ей кольцо... поговорите с мировым судьей Севреном в Брилле. У него должны быть записи о недавних смертях и, если повезет, он сможет выяснить, кто такая Делия. $b$bНо я бы на это не рассчитывал. Тот, кто подарил ей кольцо, вероятно, уже мертв. Или, если он стал нежитью, то, возможно, ему больше нет дела до Делии.','Отнесите кольцо Делии мировому судье Севрену в Брилл.','Некая Делия жила в Брилле не так давно. Она была похоронена в общей могиле, но, если верить вашим словам, ее тело, должно быть, похитили гноллы из стаи Гнилошкуров и утащили в Серебряный бор. \n\nСтая Гнилошкуров, как и вся Плеть, должна быть уничтожена. Я верю, что ты предпримешь к этому надлежащие шаги.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо с гравировкой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хотите найти мужа или возлюбленного Делии – того, кто подарил ей кольцо... поговорите с мировым судьей Севреном в Брилле. У него должны быть записи о недавних смертях и, если повезет, он сможет выяснить, кто такая Делия. $b$bНо я бы на это не рассчитывал. Тот, кто подарил ей кольцо, вероятно, уже мертв. Или, если он стал нежитью, то, возможно, ему больше нет дела до Делии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кольцо Делии мировому судье Севрену в Брилл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Некая Делия жила в Брилле не так давно. Она была похоронена в общей могиле, но, если верить вашим словам, ее тело, должно быть, похитили гноллы из стаи Гнилошкуров и утащили в Серебряный бор. \n\nСтая Гнилошкуров, как и вся Плеть, должна быть уничтожена. Я верю, что ты предпримешь к этому надлежащие шаги.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (441,'Роли, который живет в Подгороде','У Делии был муж по имени Роли, проживающий ныне в Подгороде. Если кольцо действительно принадлежало Делии, которая жила здесь, в Брилле, то Роли узнает его. $b$bНайти Роли вы можете в Торговом квартале Подгорода.','Отнесите Роли кольцо Делии.','Мы знакомы?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Роли, который живет в Подгороде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Делии был муж по имени Роли, проживающий ныне в Подгороде. Если кольцо действительно принадлежало Делии, которая жила здесь, в Брилле, то Роли узнает его. $b$bНайти Роли вы можете в Торговом квартале Подгорода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Роли кольцо Делии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы знакомы?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (442,'Атака на остров Фенриса','А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса. $b$bТы снова $Gдолжен:должна; добраться до острова и уничтожить Тула Когтя Ворона. Мне нужна его голова!$b$bЯ посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача, $n. Ты $Gдолжен:должна; выйти $Gпобедителем:победительницей;!','Принесите верховному палачу Хадрику в Гробницу голову Тула Когтя Ворона.','Вернитесь к верховному палачу Хадрику в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака на остров Фенриса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса. $b$bТы снова $Gдолжен:должна; добраться до острова и уничтожить Тула Когтя Ворона. Мне нужна его голова!$b$bЯ посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача, $n. Ты $Gдолжен:должна; выйти $Gпобедителем:победительницей;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите верховному палачу Хадрику в Гробницу голову Тула Когтя Ворона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Хадрику в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (443,'Лимфа Гнилошкуров','Прежде чем мы совершим нападение на остров Фенриса, мы должны понять, кто стоит за Гнилошкурами. Наши аптекари считают, что их особенности связаны со странной жидкостью, текущей по их жилам. $b$bОтправляйся на остров Фенриса, к востоку от старой переправы, и собери лимфу гноллов-гнилошкуров, которых вы там встретите. Образцы нужны аптекарю Ренферрелу, который стоит неподалеку от Гробницы.','Принесите 8 бутылок лимфы Гнилошкуров аптекарю Ренферрелу рядом с Гробницей.','Отлично. Эта лимфа поможет нам понять природу гноллов-гнилошкуров, а также сможет показать нам, в чем их слабость... \n\n...если она у них есть...','Вернитесь к аптекарю Ренферрелу в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лимфа Гнилошкуров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем мы совершим нападение на остров Фенриса, мы должны понять, кто стоит за Гнилошкурами. Наши аптекари считают, что их особенности связаны со странной жидкостью, текущей по их жилам. $b$bОтправляйся на остров Фенриса, к востоку от старой переправы, и собери лимфу гноллов-гнилошкуров, которых вы там встретите. Образцы нужны аптекарю Ренферрелу, который стоит неподалеку от Гробницы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 бутылок лимфы Гнилошкуров аптекарю Ренферрелу рядом с Гробницей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Эта лимфа поможет нам понять природу гноллов-гнилошкуров, а также сможет показать нам, в чем их слабость... \n\n...если она у них есть...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Ренферрелу в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (444,'Происхождение Гнилошкуров','Я выпарил лимфу, которую ты $gпринес:принесла; мне, и разложил ее на основные компоненты. Мои выводы еще не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией. $b$bПока я продолжу ее изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород. Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров.$b$bИди же. Бетора ты найдешь в Квартале Магов Подгорода.','Отнесите образец лимфы Бетору Ледострелу в Подгород.','Эта субстанция наполнена могучими заклинаниями, с некоторыми из которых я не сталкивался вот уже долгое время... \n\nСекундочку – мне придется воспользоваться проясняющим заклинанием...','Мои исследования требуют серьезной концентрации. Так что, надеюсь, ваш визит не праздный.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Происхождение Гнилошкуров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я выпарил лимфу, которую ты $gпринес:принесла; мне, и разложил ее на основные компоненты. Мои выводы еще не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией. $b$bПока я продолжу ее изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород. Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров.$b$bИди же. Бетора ты найдешь в Квартале Магов Подгорода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите образец лимфы Бетору Ледострелу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта субстанция наполнена могучими заклинаниями, с некоторыми из которых я не сталкивался вот уже долгое время... \n\nСекундочку – мне придется воспользоваться проясняющим заклинанием...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мои исследования требуют серьезной концентрации. Так что, надеюсь, ваш визит не праздный.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (445,'Что у вас за дело ко мне, |3-6($C)?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что у вас за дело ко мне, |3-6($C)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (446,'Тул Коготь Ворона','Эта лимфа была создана моим давним коллегой, Тулом Когтем Ворона. До великой войны он был молодым и многообещающим магом, но когда вошел в силу Король-лич, Тул предал своих братьев и перешел на сторону Плети. $b$bЯ и не думал, что он все еще жив, и уж тем более – что он возглавляет набеги Гнилошкуров на нас! $b$bЯ знаю многие из его заклинаний и могу помочь сварить зелье для того, чтобы им противостоять. Отнеси этот свиток обратно к аптекарю Ренферрелу. Там содержатся заклятья, необходимые для изготовления зелья.','Отнесите свиток Бетора аптекарю Ренферрелу в Серебряный бор, в Гробницу.','Этот свиток весь пронизан могущественной магией. Я никогда не использовал таких сил в зельях... это будет сильнодействующая микстура, и она должна сослужить тебе хорошую службу, если ты решишься атаковать Тула в его крепости на острове Фенриса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тул Коготь Ворона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта лимфа была создана моим давним коллегой, Тулом Когтем Ворона. До великой войны он был молодым и многообещающим магом, но когда вошел в силу Король-лич, Тул предал своих братьев и перешел на сторону Плети. $b$bЯ и не думал, что он все еще жив, и уж тем более – что он возглавляет набеги Гнилошкуров на нас! $b$bЯ знаю многие из его заклинаний и могу помочь сварить зелье для того, чтобы им противостоять. Отнеси этот свиток обратно к аптекарю Ренферрелу. Там содержатся заклятья, необходимые для изготовления зелья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите свиток Бетора аптекарю Ренферрелу в Серебряный бор, в Гробницу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот свиток весь пронизан могущественной магией. Я никогда не использовал таких сил в зельях... это будет сильнодействующая микстура, и она должна сослужить тебе хорошую службу, если ты решишься атаковать Тула в его крепости на острове Фенриса.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (447,'Рецептура смерти','Силы Артаса неисчислимы. Но, создав новую чуму, мы могли бы раз и навсегда покончить как с армией Плети, так и с людьми. $b$bМои исследования показали, что паучья кровь в соединении с токсином, извлеченном из сердца бешеного медведя, дает смертельно опасный эликсир. Собери необходимые субстанции с пауков из Оплетающей Тьмы к северо-западу отсюда и с медведей, бродящих по Серебряному бору. Принеси реагенты в Подгород аптекарю Фаранеллу из Королевского фармацевтического общества.','Соберите 6 сердец медведя и 6 образцов Летящей крови и принесите их опытному аптекарю Фаранеллу в Подгород.','Приветствую вас, |3-6($C). Какое дело у вас к Королевскому фармацевтическому обществу?','Вернитесь к опытному аптекарю Фаранеллу в Район Фармацевтов, что в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рецептура смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Силы Артаса неисчислимы. Но, создав новую чуму, мы могли бы раз и навсегда покончить как с армией Плети, так и с людьми. $b$bМои исследования показали, что паучья кровь в соединении с токсином, извлеченном из сердца бешеного медведя, дает смертельно опасный эликсир. Собери необходимые субстанции с пауков из Оплетающей Тьмы к северо-западу отсюда и с медведей, бродящих по Серебряному бору. Принеси реагенты в Подгород аптекарю Фаранеллу из Королевского фармацевтического общества.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 сердец медведя и 6 образцов Летящей крови и принесите их опытному аптекарю Фаранеллу в Подгород.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую вас, |3-6($C). Какое дело у вас к Королевскому фармацевтическому обществу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к опытному аптекарю Фаранеллу в Район Фармацевтов, что в Подгороде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (448,'Доложиться Хадрику','Прежде чем вы нападете на остров Фенриса, доложитесь верховному палачу Хадрику. У него может быть дополнительная информация о том, что вам понадобится.','Доложитесь верховному палачу Хадрику в Гробнице.','Если то, что говорит Бетор, – правда, то Тул Коготь Ворона представляет собой силу, с которой нужно разобраться, причем разобраться срочно. \n\nВ качестве помощи можете подобрать себе что-нибудь из нашего здешнего арсенала...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доложиться Хадрику',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем вы нападете на остров Фенриса, доложитесь верховному палачу Хадрику. У него может быть дополнительная информация о том, что вам понадобится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь верховному палачу Хадрику в Гробнице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если то, что говорит Бетор, – правда, то Тул Коготь Ворона представляет собой силу, с которой нужно разобраться, причем разобраться срочно. \n\nВ качестве помощи можете подобрать себе что-нибудь из нашего здешнего арсенала...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`requestitemstext_loc8`) VALUES (449,'Хотя раны Квинна заживают, я хотела бы доставить наш отчет верховному палачу Хадрику как можно скорее. В нем содержится информация, которая жизненно важна для захвата Серебряного бора Отрекшимися.','Удалось ли вам прояснить судьбу стражей смерти?') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя раны Квинна заживают, я хотела бы доставить наш отчет верховному палачу Хадрику как можно скорее. В нем содержится информация, которая жизненно важна для захвата Серебряного бора Отрекшимися.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли вам прояснить судьбу стражей смерти?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (450,'Рецептура смерти','Вы можете еще послужить Королевскому фармацевтическому обществу, $n. $b$bКогда Аругал навел на лес свою никчемную магию, он наложил проклятие на одного из наших самых многообещающих сотрудников, аптекаря Берарда. Ставший безвольным слугой Аругала, теперь Берард для нас бесполезен. Но его находки могут быть ценными. Он изучал древнюю чуму, давным-давно погубившую всякую жизнь в озере Лордамер. $b$bРаздобудьте записи Берарда из его кабинета в таверне деревни Погребальных Костров и принесите аптекарю Ренферрелу.','Найдите в деревне Погребальных Костров записи Берарда и отнесите их в Гробницу аптекарю Ренферрелу.','Вернитесь к аптекарю Ренферрелу в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рецептура смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы можете еще послужить Королевскому фармацевтическому обществу, $n. $b$bКогда Аругал навел на лес свою никчемную магию, он наложил проклятие на одного из наших самых многообещающих сотрудников, аптекаря Берарда. Ставший безвольным слугой Аругала, теперь Берард для нас бесполезен. Но его находки могут быть ценными. Он изучал древнюю чуму, давным-давно погубившую всякую жизнь в озере Лордамер. $b$bРаздобудьте записи Берарда из его кабинета в таверне деревни Погребальных Костров и принесите аптекарю Ренферрелу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в деревне Погребальных Костров записи Берарда и отнесите их в Гробницу аптекарю Ренферрелу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Ренферрелу в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (451,'Рецептура смерти','Согласно записям Берарда, мох озерных тихоступов и озерных ползунов может оказаться полезным для решения нашей задачи по изготовлению новой отравы. Эти твари обитают на островах на озере Лордамер на востоке. $b$bОн также упоминает об очень редкой субстанции – твердой опухоли, обнаруженной им у мурлока из племени Злобного Плавника. Очевидно, эта опухоль столь редка, что Берарду удалось раздобыть лишь одну. $b$bСоберите образцы моха, а также редкую твердую опухоль и отнесите их аптекарю Фаранеллу в Подгород.','Принесите 6 образцов мха озерного ползуна, 6 образцов мха озерного тихоступа и твердую опухоль опытному аптекарю Фаранеллу в Подгород.','Вернитесь к опытному аптекарю Фаранеллу в Район Фармацевтов, что в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рецептура смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Согласно записям Берарда, мох озерных тихоступов и озерных ползунов может оказаться полезным для решения нашей задачи по изготовлению новой отравы. Эти твари обитают на островах на озере Лордамер на востоке. $b$bОн также упоминает об очень редкой субстанции – твердой опухоли, обнаруженной им у мурлока из племени Злобного Плавника. Очевидно, эта опухоль столь редка, что Берарду удалось раздобыть лишь одну. $b$bСоберите образцы моха, а также редкую твердую опухоль и отнесите их аптекарю Фаранеллу в Подгород.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 образцов мха озерного ползуна, 6 образцов мха озерного тихоступа и твердую опухоль опытному аптекарю Фаранеллу в Подгород.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к опытному аптекарю Фаранеллу в Район Фармацевтов, что в Подгороде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (452,'Засада в деревне','Ты очень вовремя $gдобрался:добралась; сюда, $n! $b$bСовет деревни Погребальных Костров вернется в любой момент. Аругалу же есть чем заняться в крепости. Он использует Совет как марионеток, чтобы держать лишенных разума и воли приспешников в деревне под своим полным контролем. Но я уверена, что без руководства Совета деревни Погребальных Костров сыны Аругала взбунтовались бы против своего предводителя. $b$bЯ не могу справиться со всем в этим в одиночку. Мне нужна твоя помощь. Вместе мы сможем погубить Cовет к вящей славе леди Сильваны.','Помогите ловчей смерти Фарлии уничтожить Совет деревни Погребальных Костров.','Помогите Фаэрлее уничтожить Совет деревни Погребальных Костров','Вернитесь к ловчей смерти Фарлии в Деревню Погребальных Костров, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засада в деревне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты очень вовремя $gдобрался:добралась; сюда, $n! $b$bСовет деревни Погребальных Костров вернется в любой момент. Аругалу же есть чем заняться в крепости. Он использует Совет как марионеток, чтобы держать лишенных разума и воли приспешников в деревне под своим полным контролем. Но я уверена, что без руководства Совета деревни Погребальных Костров сыны Аругала взбунтовались бы против своего предводителя. $b$bЯ не могу справиться со всем в этим в одиночку. Мне нужна твоя помощь. Вместе мы сможем погубить Cовет к вящей славе леди Сильваны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите ловчей смерти Фарлии уничтожить Совет деревни Погребальных Костров.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помогите Фаэрлее уничтожить Совет деревни Погребальных Костров',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчей смерти Фарлии в Деревню Погребальных Костров, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (453,'Поиски таинственного незнакомца','Удачи, $n. Надеюсь, ты найдешь этого парня, причем живым.$B$BСбежав за пределы Темнолесья, он мог пасть жертвой диких зверей.','Отыщите незнакомца. Его приметы:$B$BОн родом не из Темнолесья.$B$BОн – нервный тип.$B$BОн сбежал из Темнолесья и двинулся на запад.','Трясунчик вздыхает... $B$BДа, автор этой книги – я. Сумел-таки отыскать меня?$B$BНо если ты прочитаешь мои записи, то узнаешь только половину истории!','Кто ты?! Оставь меня в покое!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски таинственного незнакомца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Удачи, $n. Надеюсь, ты найдешь этого парня, причем живым.$B$BСбежав за пределы Темнолесья, он мог пасть жертвой диких зверей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите незнакомца. Его приметы:$B$BОн родом не из Темнолесья.$B$BОн – нервный тип.$B$BОн сбежал из Темнолесья и двинулся на запад.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Трясунчик вздыхает... $B$BДа, автор этой книги – я. Сумел-таки отыскать меня?$B$BНо если ты прочитаешь мои записи, то узнаешь только половину истории!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто ты?! Оставь меня в покое!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (454,'После засады','До этого... случая мы все время таскали туда-сюда бочки с порохом. Теперь придется поделить работу: Миран понесет часть бочек, а я присмотрю за остальными.$b$bМне не хочется отпускать Мирана одного. Когда он соберется в путь, проводи, пожалуйста, его.','Поговорите с Мираном.','Добрый день, |3-6($c).$b$bТы проводишь меня до раскопа? Отлично... После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Черного Железа.$b$bЯ почти готов, осталось только кое-что проверить. Когда ты соберешься в путь, скажи мне об этом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','После засады',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До этого... случая мы все время таскали туда-сюда бочки с порохом. Теперь придется поделить работу: Миран понесет часть бочек, а я присмотрю за остальными.$b$bМне не хочется отпускать Мирана одного. Когда он соберется в путь, проводи, пожалуйста, его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мираном.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добрый день, |3-6($c).$b$bТы проводишь меня до раскопа? Отлично... После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Черного Железа.$b$bЯ почти готов, осталось только кое-что проверить. Когда ты соберешься в путь, скажи мне об этом.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (455,'Альгазская битва','Орки из клана Драконьей Пасти бесчинствуют по всей Болотине. А сейчас они двинулись на Дун Альгаз! Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине.$B$BПопытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь! Чем больше, тем лучше! Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов.$B$BНайти Менетилов несложно: пройдешь через Дун Альгаз, потом – по дороге на север, а на развилке свернешь на запад.$B$BМы очень надеемся на тебя, $n. Не подведи нас.','Пройдите через Дун Альгаз.$B$BУбейте 8 разведчиков из клана Драконьей Пасти и 6 рубак из клана Драконьей Пасти.$B$BОб исполнении доложите Валстагу Сталезубу из Гавани Менетилов.','Ты идешь из озера Лок Модан? Что там орки? Как обстановка у Врат Альгаза?','Проникнуть в Дун Альгаз.','Вернитесь к Валстагу Сталезубу в Гавань Менетилов, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альгазская битва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орки из клана Драконьей Пасти бесчинствуют по всей Болотине. А сейчас они двинулись на Дун Альгаз! Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине.$B$BПопытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь! Чем больше, тем лучше! Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов.$B$BНайти Менетилов несложно: пройдешь через Дун Альгаз, потом – по дороге на север, а на развилке свернешь на запад.$B$BМы очень надеемся на тебя, $n. Не подведи нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите через Дун Альгаз.$B$BУбейте 8 разведчиков из клана Драконьей Пасти и 6 рубак из клана Драконьей Пасти.$B$BОб исполнении доложите Валстагу Сталезубу из Гавани Менетилов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты идешь из озера Лок Модан? Что там орки? Как обстановка у Врат Альгаза?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проникнуть в Дун Альгаз.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валстагу Сталезубу в Гавань Менетилов, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (456,'Природное равновесие','Мои приветствия, $n. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия. $b$bВесенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают.$b$bК несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. $gЮный:Юная:c; |3-6($c), помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия.','[Deprecated] Kill 3 Young Nightsabers and 3 Young Thistle Boars.','[Deprecated] Return to Conservator Ilthalaine in Shadowglen.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Природное равновесие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои приветствия, $n. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия. $b$bВесенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают.$b$bК несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить. $gЮный:Юная:c; |3-6($c), помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[Deprecated] Kill 3 Young Nightsabers and 3 Young Thistle Boars.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Conservator Ilthalaine in Shadowglen.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (457,'Естественное равновесие','Истребление детенышей в Тенистой долине – хорошее начало, $n. Однако нас ждет еще много работы.$b$bЛесные ресурсы очень быстро подойдут к концу, если вовремя не устранить проблему. Уничтожение лесного зверья – вынужденное зло во имя блага всех тех, кто населяет эти места. Отправляйся на северо-восток вглубь Тенистой долины и истреби облезлых ночных саблезубов и щетинистых вепрей, чтобы восстановить естественное равновесие.','Убейте 6 облезлых ночных саблезубов и щетинистых вепрей.','[Deprecated] Return to Conservator Ilthalain in Shadowglen.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Естественное равновесие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Истребление детенышей в Тенистой долине – хорошее начало, $n. Однако нас ждет еще много работы.$b$bЛесные ресурсы очень быстро подойдут к концу, если вовремя не устранить проблему. Уничтожение лесного зверья – вынужденное зло во имя блага всех тех, кто населяет эти места. Отправляйся на северо-восток вглубь Тенистой долины и истреби облезлых ночных саблезубов и щетинистых вепрей, чтобы восстановить естественное равновесие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 облезлых ночных саблезубов и щетинистых вепрей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Conservator Ilthalain in Shadowglen.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (458,'Защитница леса','Слава небесам, ты здесь, |3-6($c). Лесные духи нашептали мне удивительные вести. Будто бы таинственная защитница леса, Тариндрелла, снова вернулась в Тенистую долину. Ее присутствие не ощущалось в этих лесах с тех пор, как нас осенило благословение Тельдрассила. Должно быть, что-то случилось, раз она вернулась в эти края.$b$bНайди Тариндреллу и узнай, что за дело привело ее в нашу чащу. Одна из часовых видела ее на юго-западе от Альдрассила.','Найдите дриаду по имени Тариндрелла.','Я вижу, тебе удалось найти меня, $gюный:юная:r; |3-6($r)! Друид Мелитар мудро поступил, отправив тебя сюда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитница леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слава небесам, ты здесь, |3-6($c). Лесные духи нашептали мне удивительные вести. Будто бы таинственная защитница леса, Тариндрелла, снова вернулась в Тенистую долину. Ее присутствие не ощущалось в этих лесах с тех пор, как нас осенило благословение Тельдрассила. Должно быть, что-то случилось, раз она вернулась в эти края.$b$bНайди Тариндреллу и узнай, что за дело привело ее в нашу чащу. Одна из часовых видела ее на юго-западе от Альдрассила.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите дриаду по имени Тариндрелла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я вижу, тебе удалось найти меня, $gюный:юная:r; |3-6($r)! Друид Мелитар мудро поступил, отправив тебя сюда.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (459,'Демонические воры','Эти мерзкие мелкие грелли! Они снова крадут наш провиант.$B$BЕсли ты желаешь нам помочь, имей в виду – все, что они у нас сперли, наверняка валяется в их лагерях на западе отсюда. Я с радостью вознагражу тебя, если ты все это мне вернешь.','Верните украденные у Деллии бобы, воду и сумки.','Вернитесь к Деллии в Альдрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонические воры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти мерзкие мелкие грелли! Они снова крадут наш провиант.$B$BЕсли ты желаешь нам помочь, имей в виду – все, что они у нас сперли, наверняка валяется в их лагерях на западе отсюда. Я с радостью вознагражу тебя, если ты все это мне вернешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните украденные у Деллии бобы, воду и сумки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Деллии в Альдрассил.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (460,'В целости и сохранности','На вид ты не похож на гнилошкура. Это хорошо. А то я уже потерял надежду... $b$bМеня зовут Аларик, когда-то я был доверенным слугой и телохранителем Тула. Он использовал свою магию для "защиты" меня от Чумы Нежити, но вместо этого его заклинание повергло меня в нежитие – состояние, из которого я не могу уйти. А после создания этих проклятых гнилошкурых гноллов Туле обезглавил меня... и отдал гноллам мою голову в качестве игрушки! $b$bПожалуйста, воссоедини меня с телом. Я уверен, что гноллы закопали его в Крепости Фенриса, возле стойл, в ничем не примечательной могиле.','Отнесите голову Аларика на его могилу.','Видно, что эта могила была выкопана в спешке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В целости и сохранности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На вид ты не похож на гнилошкура. Это хорошо. А то я уже потерял надежду... $b$bМеня зовут Аларик, когда-то я был доверенным слугой и телохранителем Тула. Он использовал свою магию для "защиты" меня от Чумы Нежити, но вместо этого его заклинание повергло меня в нежитие – состояние, из которого я не могу уйти. А после создания этих проклятых гнилошкурых гноллов Туле обезглавил меня... и отдал гноллам мою голову в качестве игрушки! $b$bПожалуйста, воссоедини меня с телом. Я уверен, что гноллы закопали его в Крепости Фенриса, возле стойл, в ничем не примечательной могиле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите голову Аларика на его могилу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Видно, что эта могила была выкопана в спешке.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (461,'Замаскированный тайник','Я знаю об одной тайной нише в крепости, где хранится дорогой сердцу Тула и его давних коллег предмет. В ней также лежит нечто, что вы можете счесть полезным для себя. Возьмите меня туда! $b$bУглубление в стене находится в юго-западной башне крепости, позади пыльной полки. $b$bВозьмите мое тело, а сапоги оставьте здесь. Они мне все равно не по ноге...','Отнесите Аларика к замаскированной нише.','Вот мы и на месте, здесь открыто. Оставь меня здесь. Лучшие дни своей жизни я провел в этой крепости, и мысль об упокоении в этих стенах умиротворяет меня. \n\nХорошенько закрой нишу – я не хочу, чтобы эти гнилошкуры нашли меня. \n\nАх, да, и возьми вот это. Ты это заслуживаешь.','Вот это место! Поднесите меня поближе...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Замаскированный тайник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю об одной тайной нише в крепости, где хранится дорогой сердцу Тула и его давних коллег предмет. В ней также лежит нечто, что вы можете счесть полезным для себя. Возьмите меня туда! $b$bУглубление в стене находится в юго-западной башне крепости, позади пыльной полки. $b$bВозьмите мое тело, а сапоги оставьте здесь. Они мне все равно не по ноге...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Аларика к замаскированной нише.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот мы и на месте, здесь открыто. Оставь меня здесь. Лучшие дни своей жизни я провел в этой крепости, и мысль об упокоении в этих стенах умиротворяет меня. \n\nХорошенько закрой нишу – я не хочу, чтобы эти гнилошкуры нашли меня. \n\nАх, да, и возьми вот это. Ты это заслуживаешь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вот это место! Поднесите меня поближе...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (462,'<UNUSED>','Other than you, we sent two scouts through Algaz. Only one returned. Here\'s what he discovered:$B$BThe Dragonmaws sent one of their Lieutenants, Maruk Wyrmscale, to organize a crew of orcs in Algaz and cut off the land route to Menethil Harbor!$B$BWe have to stop this, now. Take out Maruk, and then report to Valstag Ironjaw in Menethil Harbor.$B$BMaruk is headquartered in a small cave, across a pond between the second and third tunnels of Algaz. Menethil is through Algaz, then west along the road.','Kill Maruk Wyrmscale$B$BReport to Valstag Ironjaw in Menethil Harbor.','Вернитесь к Валстагу Сталезубу в бухту Барадин, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Other than you, we sent two scouts through Algaz. Only one returned. Here\'s what he discovered:$B$BThe Dragonmaws sent one of their Lieutenants, Maruk Wyrmscale, to organize a crew of orcs in Algaz and cut off the land route to Menethil Harbor!$B$BWe have to stop this, now. Take out Maruk, and then report to Valstag Ironjaw in Menethil Harbor.$B$BMaruk is headquartered in a small cave, across a pond between the second and third tunnels of Algaz. Menethil is through Algaz, then west along the road.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Kill Maruk Wyrmscale$B$BReport to Valstag Ironjaw in Menethil Harbor.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валстагу Сталезубу в бухту Барадин, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (463,'Страж Природы','Ты ведь $Gслышал:слышала; рассказы о Страже Природы? Я даже подозреваю, что ты и разыскать его хочешь. Если так, то скажу тебе, что это чистое безумие! Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим.$B$BОн живет на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями.$B$BОставь-ка свои денежки мне – покойникам они все равно не нужны. Да и дядя-сторож может обломать зуб об твои золотые, когда будет перекусывать тебя надвое... Ты ведь не хочешь, чтобы бедняга потом мучился?','Найдите Стража Природы.','Что это за букашка ко мне пожаловала? Корни и папоротники говорят, что ты $Gпришел:пришла; с добрым умыслом... Меня по-разному называют, но не на всякое имя я откликаюсь. Зови меня Ретиль.$B$BА теперь внемли... Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страж Природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты ведь $Gслышал:слышала; рассказы о Страже Природы? Я даже подозреваю, что ты и разыскать его хочешь. Если так, то скажу тебе, что это чистое безумие! Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим.$B$BОн живет на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями.$B$BОставь-ка свои денежки мне – покойникам они все равно не нужны. Да и дядя-сторож может обломать зуб об твои золотые, когда будет перекусывать тебя надвое... Ты ведь не хочешь, чтобы бедняга потом мучился?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Стража Природы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это за букашка ко мне пожаловала? Корни и папоротники говорят, что ты $Gпришел:пришла; с добрым умыслом... Меня по-разному называют, но не на всякое имя я откликаюсь. Зови меня Ретиль.$B$BА теперь внемли... Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (464,'Боевые знамена','К концу Второй войны клан орков Драконьей Пасти потерял власть над красными драконами и был почти уничтожен. Драконы припомнили им все, гнали бывших хозяев аж до самого Грим Батола. Затем орки скрылись в горах к востоку от раскопа Вельгара.$B$BОтсидевшись в горах, они вновь набрали силу и теперь разбили лагерь к северо-востоку от Менетила.$B$BНапади на этот лагерь, внеси панику в ряды орков. В доказательство содеянного принеси мне боевые знамена клана.','Принесите 8 боевых знамен клана Драконьей Пасти капитану Крепкому Кулаку.','Ну что, ты показал оркам, почем фунт лиха?','Вернитесь к капитану Крепкому Кулаку в Гавань Менетилов, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые знамена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К концу Второй войны клан орков Драконьей Пасти потерял власть над красными драконами и был почти уничтожен. Драконы припомнили им все, гнали бывших хозяев аж до самого Грим Батола. Затем орки скрылись в горах к востоку от раскопа Вельгара.$B$BОтсидевшись в горах, они вновь набрали силу и теперь разбили лагерь к северо-востоку от Менетила.$B$BНапади на этот лагерь, внеси панику в ряды орков. В доказательство содеянного принеси мне боевые знамена клана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 боевых знамен клана Драконьей Пасти капитану Крепкому Кулаку.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, ты показал оркам, почем фунт лиха?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Крепкому Кулаку в Гавань Менетилов, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (465,'Гамбит Нек\'роша','Пока ты $Gсражался:сражалась; с кланом Драконьей Пасти, мы получили сведения об их планах.$B$BНек\'рош строит катапульты и планирует взять Менетил в осаду! А у нас тем временем вовсю идет битва при Дун Альгаз, и подкрепления ждать неоткуда!$B$BУничтожь катапульты, прошу тебя. Они стоят в лагере Драконьей Пасти.$B$BВозьми вот этот трут. Пробейся к катапультам и подожги их.$B$BПосле этого найди и убей Нек\'роша. Этот паршивец уже свое отжил...','Уничтожьте катапульты Драконьей Пасти.','Вы подносите трут к катапульте и высекаете искру...$B$BПламя охватывает катапульту и мигом перекидывается на другие!','Вот одна из катапульт. Поджигаем?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гамбит Нек\'роша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $Gсражался:сражалась; с кланом Драконьей Пасти, мы получили сведения об их планах.$B$BНек\'рош строит катапульты и планирует взять Менетил в осаду! А у нас тем временем вовсю идет битва при Дун Альгаз, и подкрепления ждать неоткуда!$B$BУничтожь катапульты, прошу тебя. Они стоят в лагере Драконьей Пасти.$B$BВозьми вот этот трут. Пробейся к катапультам и подожги их.$B$BПосле этого найди и убей Нек\'роша. Этот паршивец уже свое отжил...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте катапульты Драконьей Пасти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы подносите трут к катапульте и высекаете искру...$B$BПламя охватывает катапульту и мигом перекидывается на другие!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вот одна из катапульт. Поджигаем?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (466,'Поиски огневита','Я слышал о редком виде руды – огневите. Его добывают в Болотине, в пещере к северо-западу от Врат Альгаза. Огневит очень неустойчив – чуть что, сразу взрывается. Однако я уверен, что если правильно его выплавить, то можно делать из него мощнейшие снаряды для пушек!$B$BРаздобудь для меня огневитовую руду, а я пока поищу добровольца, который согласится принять участие в опытах.$B$BАх да, чтобы добыть руду, тебе нужны познания в горном деле. Если у тебя нет необходимых знаний, то... отправь в шахту кого-нибудь из знакомых рудокопов!','Принесите 6 партий огневитовой руды пилоту Камнекожицу в Дун Морог.','Вернитесь к пилоту Камнекожицу в Поселок Сталежара, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски огневита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал о редком виде руды – огневите. Его добывают в Болотине, в пещере к северо-западу от Врат Альгаза. Огневит очень неустойчив – чуть что, сразу взрывается. Однако я уверен, что если правильно его выплавить, то можно делать из него мощнейшие снаряды для пушек!$B$BРаздобудь для меня огневитовую руду, а я пока поищу добровольца, который согласится принять участие в опытах.$B$BАх да, чтобы добыть руду, тебе нужны познания в горном деле. Если у тебя нет необходимых знаний, то... отправь в шахту кого-нибудь из знакомых рудокопов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 партий огневитовой руды пилоту Камнекожицу в Дун Морог.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пилоту Камнекожицу в Поселок Сталежара, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (467,'Найдите Камнекожца','Пилот Камнекожиц любит свою осадную машину, как и все пилоты осадных машин! И он всегда рад найти новый способ повысить огневую мощь своих орудий.$B$BДо него дошли слухи о редкой руде, и он ищет кого-нибудь, кто добудет ее. И если тебе уже не терпится взяться за это дело, то найди Камнекожица в поселке Сталежара в Дун Мороге и спроси, чего он хочет.','Поговорите с пилотом Камнекожицем.','Привет, $n. Ты тут по моему делу, да? Приятно видеть, как $Gмолодой:молодая:r; |3-6($r) рвется на поиски приключений!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найдите Камнекожца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пилот Камнекожиц любит свою осадную машину, как и все пилоты осадных машин! И он всегда рад найти новый способ повысить огневую мощь своих орудий.$B$BДо него дошли слухи о редкой руде, и он ищет кого-нибудь, кто добудет ее. И если тебе уже не терпится взяться за это дело, то найди Камнекожица в поселке Сталежара в Дун Мороге и спроси, чего он хочет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с пилотом Камнекожицем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет, $n. Ты тут по моему делу, да? Приятно видеть, как $Gмолодой:молодая:r; |3-6($r) рвется на поиски приключений!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (468,'Отчитайтесь перед горным пехотинцем Рокхаром','Горный пехотинец Рокхар ищет добровольцев для похода через Дун Альгаз в Болотину!$B$BЕсли желаете омыть сапоги в болотной жиже и снискать приключений на свою голову – поговорите со Скальным Панцирником в Дун Альгаз. Это к северу отсюда, по дороге за сторожевой башней.','Поговорите с горным пехотинцем Рокхаром.','$C, ни больше, ни меньше! Желаешь отправиться с нами в разведку? Отлично!$B$BНадеюсь, у тебя есть все необходимое снаряжение, потому что эта "разведка" может обернуться и кое-чем похуже...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчитайтесь перед горным пехотинцем Рокхаром',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Горный пехотинец Рокхар ищет добровольцев для похода через Дун Альгаз в Болотину!$B$BЕсли желаете омыть сапоги в болотной жиже и снискать приключений на свою голову – поговорите со Скальным Панцирником в Дун Альгаз. Это к северу отсюда, по дороге за сторожевой башней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с горным пехотинцем Рокхаром.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$C, ни больше, ни меньше! Желаешь отправиться с нами в разведку? Отлично!$B$BНадеюсь, у тебя есть все необходимое снаряжение, потому что эта "разведка" может обернуться и кое-чем похуже...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (469,'Ежедневная доставка','Привет тебе, $Gстранник:путешественница;!$b$bНе лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок!$b$bНу а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана.$b$bЯ бы и сам отнес их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза.','Отнесите стопку кроколисковых шкур кожевнику Джеймсу Халлорану в Гавань Менетилов.','Хмм, да это же от Эйнара, да? Не вижу его уж который день, а шкуры присылает исправно. Опять поцапался со своей благоверной, к бабке не ходи!$b$bНадо бы подослать жену к Сиде – поговорить, чтобы та не выживала мужа из дому...','Не интересуется ли $Gдобрый:прелестная:c; |3-6($c) сапогами из кроколисковой кожи? Могу предложить отличные выделанные шкуры!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ежедневная доставка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $Gстранник:путешественница;!$b$bНе лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок!$b$bНу а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана.$b$bЯ бы и сам отнес их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите стопку кроколисковых шкур кожевнику Джеймсу Халлорану в Гавань Менетилов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм, да это же от Эйнара, да? Не вижу его уж который день, а шкуры присылает исправно. Опять поцапался со своей благоверной, к бабке не ходи!$b$bНадо бы подослать жену к Сиде – поговорить, чтобы та не выживала мужа из дому...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не интересуется ли $Gдобрый:прелестная:c; |3-6($c) сапогами из кроколисковой кожи? Могу предложить отличные выделанные шкуры!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (470,'Прожорливый слизнюк','Каждую неделю я хожу к Гробнице Железноборода, и в этот раз все было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась...$b$bЯ бросила в одного из них сумку, но он взял и засосал ее! Мне едва хватило времени, чтобы сбежать.$b$bА в сумке-то мои вещи!$b$bЯ даже не знаю, какой из этих гадов ее сожрал – они все одинаковые! Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что $Gсогласился:согласилась; помочь!','Отнимите сумку Сиды у неизвестного слизнюка возле гробницы Железноборода и верните ее хозяйке в Гавань Менетилов.','Спасибо большущее, $n! Я-то боялась, что ее больше не вернуть!$b$b Она вытряхивает из склизкой сумки содержимое и собирает мелочь в кучку. $b$bХм, чего-то я здесь самого нужного и не вижу... посмотри, может, тебе что-нибудь отсюда пригодится.','Где же моя сумочка?','Вернитесь к Сиде в Гавань Менетилов, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прожорливый слизнюк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каждую неделю я хожу к Гробнице Железноборода, и в этот раз все было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась...$b$bЯ бросила в одного из них сумку, но он взял и засосал ее! Мне едва хватило времени, чтобы сбежать.$b$bА в сумке-то мои вещи!$b$bЯ даже не знаю, какой из этих гадов ее сожрал – они все одинаковые! Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что $Gсогласился:согласилась; помочь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите сумку Сиды у неизвестного слизнюка возле гробницы Железноборода и верните ее хозяйке в Гавань Менетилов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо большущее, $n! Я-то боялась, что ее больше не вернуть!$b$b Она вытряхивает из склизкой сумки содержимое и собирает мелочь в кучку. $b$bХм, чего-то я здесь самого нужного и не вижу... посмотри, может, тебе что-нибудь отсюда пригодится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где же моя сумочка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сиде в Гавань Менетилов, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (471,'Тяжкая судьба помощника','Недавно я отправил помощника на болото за шкурами гигантских болотных кроколисков. Он не вернулся обратно, и я отправился на поиски... Скажем так: зрелище было не для слабонервных.$b$bЛекарь говорит, что мальчик выживет, и слава богу, но у меня-то работа стоит!$b$bЕсли у тебя есть желание поохотиться на кроколисков, я препятствовать не стану – особенно после того, что они сделали с моим помощником. Кроколиски водятся на побережье к северу отсюда, за поселением мурлоков.','Принесите 6 шкур гигантских кроколисков Джеймсу Халлорану в Гавань Менетилов.','Хмм... не думаю, что ты захочешь наняться ко мне в помощники, так ведь?$B$BХе-хе-хе! Да шучу я. Староват ты для этого, да и заметно, что у тебя на роду совсем другое написано. Благодарю тебя за помощь. Шкуры отменные – как раз подойдут мне для работы!','Вернитесь к Джеймсу Халлорану в Гавань Менетилов, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжкая судьба помощника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно я отправил помощника на болото за шкурами гигантских болотных кроколисков. Он не вернулся обратно, и я отправился на поиски... Скажем так: зрелище было не для слабонервных.$b$bЛекарь говорит, что мальчик выживет, и слава богу, но у меня-то работа стоит!$b$bЕсли у тебя есть желание поохотиться на кроколисков, я препятствовать не стану – особенно после того, что они сделали с моим помощником. Кроколиски водятся на побережье к северу отсюда, за поселением мурлоков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 шкур гигантских кроколисков Джеймсу Халлорану в Гавань Менетилов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм... не думаю, что ты захочешь наняться ко мне в помощники, так ведь?$B$BХе-хе-хе! Да шучу я. Староват ты для этого, да и заметно, что у тебя на роду совсем другое написано. Благодарю тебя за помощь. Шкуры отменные – как раз подойдут мне для работы!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джеймсу Халлорану в Гавань Менетилов, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (472,'Падение Дун Модра','Дворфы Черного Железа захватили Дун Модр!$b$bЯ тяжело ранен, |3-6($c). Почти все мои однополчане погибли! Подонки из клана Черного Железа набросились на нас, не успели мы оправиться после взрыва.$b$bНаш командир, Длиннокос, протрубил сигнал к отступлению. Во время бегства мне в спину попал топорик. Я потерял сознание...$b$bОчнулся уже в Менетиле, но меня волнует судьба остальных солдат. Надежда умирает последней... Может быть, Длиннокос тоже спасся! Иди в Дун Модр и отыщи его, |3-6($r)!','Отыщите Грима Длиннокоса возле Дун Модра.','Какие новости из Менетила принес нам добрый $C? Так-так-так, значит, тебя зовут $n. Приятно познакомиться.$B$BЧто ж, весть добрая. Слава Свету, что молодой Харло выжил. Ранение у него было очень тяжелое, и нам пришлось отправить его в город на единственном уцелевшем скакуне.$B$BОднако в целом ситуация безнадежная: Дун Модр пал, а от нашего славного полка остались лишь воспоминания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Дун Модра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дворфы Черного Железа захватили Дун Модр!$b$bЯ тяжело ранен, |3-6($c). Почти все мои однополчане погибли! Подонки из клана Черного Железа набросились на нас, не успели мы оправиться после взрыва.$b$bНаш командир, Длиннокос, протрубил сигнал к отступлению. Во время бегства мне в спину попал топорик. Я потерял сознание...$b$bОчнулся уже в Менетиле, но меня волнует судьба остальных солдат. Надежда умирает последней... Может быть, Длиннокос тоже спасся! Иди в Дун Модр и отыщи его, |3-6($r)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Грима Длиннокоса возле Дун Модра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какие новости из Менетила принес нам добрый $C? Так-так-так, значит, тебя зовут $n. Приятно познакомиться.$B$BЧто ж, весть добрая. Слава Свету, что молодой Харло выжил. Ранение у него было очень тяжелое, и нам пришлось отправить его в город на единственном уцелевшем скакуне.$B$BОднако в целом ситуация безнадежная: Дун Модр пал, а от нашего славного полка остались лишь воспоминания.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (473,'Доклад капитану Крепкому Кулаку','$n. Орки из клана Драконьей Пасти совсем озверели. Им уже мало одного Альгаза. Капитан Крепкий Кулак просил направлять к нему всех, кто готов оказать нам содействие в войне против орков. Он сейчас в крепости, в зале Войны.','Найдите капитана Крепкого Кулака и поговорите с ним.','$N. Валстаг вкратце рассказал мне о твоих победах над орками Драконьей Пасти в Дун Альгазе. Ты – $Gдостойный:достойная:r; |3-6($r). Нам такие нужны.$B$BИ у меня уже есть для тебя поручение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доклад капитану Крепкому Кулаку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n. Орки из клана Драконьей Пасти совсем озверели. Им уже мало одного Альгаза. Капитан Крепкий Кулак просил направлять к нему всех, кто готов оказать нам содействие в войне против орков. Он сейчас в крепости, в зале Войны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите капитана Крепкого Кулака и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N. Валстаг вкратце рассказал мне о твоих победах над орками Драконьей Пасти в Дун Альгазе. Ты – $Gдостойный:достойная:r; |3-6($r). Нам такие нужны.$B$BИ у меня уже есть для тебя поручение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (474,'Убить Нек\'роша','Катапульты сожжены. Теперь найди и убей вождя Нек\'роша.','Убейте вождя Нек\'роша.$B$BПринесите голову Нек\'роша капитану Крепкому Кулаку.','Ты уже убил Нек\'роша?','Вернитесь к капитану Крепкому Кулаку в Гавань Менетилов, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить Нек\'роша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Катапульты сожжены. Теперь найди и убей вождя Нек\'роша.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вождя Нек\'роша.$B$BПринесите голову Нек\'роша капитану Крепкому Кулаку.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже убил Нек\'роша?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Крепкому Кулаку в Гавань Менетилов, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (475,'Ветер тревоги','Ветер тревоги веет над лесом.$b$bГэролас Талветрен служит Великим смотрителем за спящими друидами-воронами в обители Бен\'этиль. Его долг – обеспечивать их безопасность, дабы их уговор с Изерой оставался в силе.$b$bНо вести от Гэроласа что-то задерживаются, и я начинаю волноваться. Отправляйся на восток в Деревню Звездного Ветра – мне нужен отчет Гэроласа, дабы я был спокоен, узнав, что мои братья и сестры спят спокойно.','Найдите Гэроласа Талветрена в Деревне Звездного Ветра.','Хвала лесным духам, ты здесь! Я знал, что Атридас забеспокоится и пришлет помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветер тревоги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ветер тревоги веет над лесом.$b$bГэролас Талветрен служит Великим смотрителем за спящими друидами-воронами в обители Бен\'этиль. Его долг – обеспечивать их безопасность, дабы их уговор с Изерой оставался в силе.$b$bНо вести от Гэроласа что-то задерживаются, и я начинаю волноваться. Отправляйся на восток в Деревню Звездного Ветра – мне нужен отчет Гэроласа, дабы я был спокоен, узнав, что мои братья и сестры спят спокойно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Гэроласа Талветрена в Деревне Звездного Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала лесным духам, ты здесь! Я знал, что Атридас забеспокоится и пришлет помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (476,'Порча Кривой Сосны','Племя Кривой Сосны поражено порчей!$b$bОни подстерегли меня в засаде, когда я выходил из обители Бен\'этиль и разграбили Деревню Звездного Ветра. Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны.$b$bЯ слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придется сделать тебе, $Gюный:юная:c; |3-6($c). Остается только надеяться, что безумные фурболги Кривой Сосны еще не уничтожили Бен\'этиль!','Вернитесь к Атридасу Медвежьей Шкуре в Доланаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порча Кривой Сосны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Кривой Сосны поражено порчей!$b$bОни подстерегли меня в засаде, когда я выходил из обители Бен\'этиль и разграбили Деревню Звездного Ветра. Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны.$b$bЯ слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придется сделать тебе, $Gюный:юная:c; |3-6($c). Остается только надеяться, что безумные фурболги Кривой Сосны еще не уничтожили Бен\'этиль!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Атридасу Медвежьей Шкуре в Доланаар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (477,'Пересечение границ','Как вы, должно быть, знаете, в деревне Янтарная мельница окопалась враждебная группа людей. Она держится там в основном за счет поддержки, которую они получают от волшебников Даларана. $b$bЯ не знаю, что они замышляют, но сам по себе интерес, проявленный ими к захолустной деревушке вроде Янтарной мельницы, показывает, что она имеет немаленькое значение. $b$bОни отправляют повозкой из Хилсбрада сундуки. Многое из привезенного складируется в небольшом лагере к северу от деревни Погребальных Костров. Раздобудьте содержимое одного такого сундука и принесите мне.','Раздобудьте содержимое одного из сундуков даларанских волшебников. Деревня Погребальных Костров находится на юге.','*С любопытством открыв крышку ящика, вы находите в нем множество тщательно упакованных предметов. На самом верху лежит связка пожелтевших от времени карт, на которых, судя по всему, изображено Серебряный бор и другие области западного Лордерона. \n\nПод картами обнаруживается подвеска таинственно-волшебного вида.*') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пересечение границ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как вы, должно быть, знаете, в деревне Янтарная мельница окопалась враждебная группа людей. Она держится там в основном за счет поддержки, которую они получают от волшебников Даларана. $b$bЯ не знаю, что они замышляют, но сам по себе интерес, проявленный ими к захолустной деревушке вроде Янтарной мельницы, показывает, что она имеет немаленькое значение. $b$bОни отправляют повозкой из Хилсбрада сундуки. Многое из привезенного складируется в небольшом лагере к северу от деревни Погребальных Костров. Раздобудьте содержимое одного такого сундука и принесите мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте содержимое одного из сундуков даларанских волшебников. Деревня Погребальных Костров находится на юге.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*С любопытством открыв крышку ящика, вы находите в нем множество тщательно упакованных предметов. На самом верху лежит связка пожелтевших от времени карт, на которых, судя по всему, изображено Серебряный бор и другие области западного Лордерона. \n\nПод картами обнаруживается подвеска таинственно-волшебного вида.*',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (478,'Карты и руны','*Вы быстро вытаскиваете подвеску из сундука и кладете крышку на место.*','Отнесите странную подвеску темному жрецу Алистеру в Гробницу.','Карты и эта... эта подвеска? Интересно. \n\nОчевидно, что волшебники Даларана почему-то интересуются Янтарной мельницей, но их цель по-прежнему остается неизвестной. \n\nМожет быть, Далар сможет выяснить, что они там ищут.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Карты и руны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Вы быстро вытаскиваете подвеску из сундука и кладете крышку на место.*',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите странную подвеску темному жрецу Алистеру в Гробницу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Карты и эта... эта подвеска? Интересно. \n\nОчевидно, что волшебники Даларана почему-то интересуются Янтарной мельницей, но их цель по-прежнему остается неизвестной. \n\nМожет быть, Далар сможет выяснить, что они там ищут.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (479,'Расследование в Янтарной мельнице','Далар пытается выяснить, каков источник магической силы этих волшебников. А пока что нам нужно замедлить их прогресс любым путем... $b$bМаги, окудники и заступники, несомненно, носят такие подвески. Добудьте их. $b$bЧтобы добраться до Янтарной мельницы, идите на юг по главной дороге, а на развилке сверните на восток.','Добудьте 8 подвесок Даларана и отнесите темному жрецу Алистеру в Гробницу.','Далар выяснил, что несмотря на замедление, процесс плетения чар зашел уже далеко. \n\nНекий очень могущественный волшебник направляет магическую энергию. Его нужно как можно скорее остановить.','Надо торопиться, нельзя дать их планам претвориться в жизнь – или мы можем перестать владеть Серебряным бором.','Вернитесь к темному жрецу Алистеру в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расследование в Янтарной мельнице',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Далар пытается выяснить, каков источник магической силы этих волшебников. А пока что нам нужно замедлить их прогресс любым путем... $b$bМаги, окудники и заступники, несомненно, носят такие подвески. Добудьте их. $b$bЧтобы добраться до Янтарной мельницы, идите на юг по главной дороге, а на развилке сверните на восток.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 подвесок Даларана и отнесите темному жрецу Алистеру в Гробницу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Далар выяснил, что несмотря на замедление, процесс плетения чар зашел уже далеко. \n\nНекий очень могущественный волшебник направляет магическую энергию. Его нужно как можно скорее остановить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надо торопиться, нельзя дать их планам претвориться в жизнь – или мы можем перестать владеть Серебряным бором.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному жрецу Алистеру в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (480,'Ткач','Верховный маг огромной силы отвечает за реактивацию энергетического узла. Они уже далеко зашли, так что единственный способ их остановить – это убить его. Это будет тяжело – безусловно, его защищают многочисленные маги и охранники. $b$bВам надо пойти и разобраться с ним, быстро. Когда он будет мертв, принесите мне его посох. Идите немедленно.','Убейте даларанского верховного мага, заберите его посох и отнесите темному жрецу Алистеру в Гробницу.','Вернитесь к темному жрецу Алистеру в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ткач',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный маг огромной силы отвечает за реактивацию энергетического узла. Они уже далеко зашли, так что единственный способ их остановить – это убить его. Это будет тяжело – безусловно, его защищают многочисленные маги и охранники. $b$bВам надо пойти и разобраться с ним, быстро. Когда он будет мертв, принесите мне его посох. Идите немедленно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте даларанского верховного мага, заберите его посох и отнесите темному жрецу Алистеру в Гробницу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному жрецу Алистеру в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (481,'Анализ Далара','Отнесите подвеску Далару Ткачу Рассвета – может быть, он сможет пролить какой-то свет на планы волшебников.','Отнесите подвеску рунической надписи Далару Ткачу Рассвета в Гробницу.','Интересно – похоже, новые махинации Кирин-Тора. Это могущественный артефакт. Такие часто использовали могучие волшебники Кирин-Тора для передачи магической энергии. \n\nТо, что они так много таких вещиц доставляют в Янтарную Мельницу, указывает на то, что затевается что-то серьезное. \n\nПосмотрим, сумею ли я проникнуть сквозь защиту и поточнее разузнать об их намерениях.','Слушаю вас, |3-6($C). Что это?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Анализ Далара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнесите подвеску Далару Ткачу Рассвета – может быть, он сможет пролить какой-то свет на планы волшебников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите подвеску рунической надписи Далару Ткачу Рассвета в Гробницу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интересно – похоже, новые махинации Кирин-Тора. Это могущественный артефакт. Такие часто использовали могучие волшебники Кирин-Тора для передачи магической энергии. \n\nТо, что они так много таких вещиц доставляют в Янтарную Мельницу, указывает на то, что затевается что-то серьезное. \n\nПосмотрим, сумею ли я проникнуть сквозь защиту и поточнее разузнать об их намерениях.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Слушаю вас, |3-6($C). Что это?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (482,'Планы Даларана','Конечно! Как же я мог забыть?$b$bЯнтарная мельница была одним из мест, отмеченных магами Кирин-Тора, и примечательна тем, что на территории деревни находится спящий энергетический узел. Волшебники, должно быть, планируют реактивировать узел и использовать его энергию для какой-то более серьезной цели. $b$bМы не можем позволить этому случиться... $b$bЧтобы активировать энергии этого места, понадобится много сил, и мы можем осложнить им задачу, стащив у волшебников подвески. $b$bПередайте эту информацию Алистеру, он спланирует дальнейшие действия.','Поговорите с темным жрецом Алистером в Гробнице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Планы Даларана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Конечно! Как же я мог забыть?$b$bЯнтарная мельница была одним из мест, отмеченных магами Кирин-Тора, и примечательна тем, что на территории деревни находится спящий энергетический узел. Волшебники, должно быть, планируют реактивировать узел и использовать его энергию для какой-то более серьезной цели. $b$bМы не можем позволить этому случиться... $b$bЧтобы активировать энергии этого места, понадобится много сил, и мы можем осложнить им задачу, стащив у волшебников подвески. $b$bПередайте эту информацию Алистеру, он спланирует дальнейшие действия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с темным жрецом Алистером в Гробнице.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (483,'Реликвии Пробуждения','Захватчиков Кривой Сосны видели в обители Бен\'этиль на западе, они крушили там все подряд.$b$bСпящие друиды могут так никогда и не выйти из Изумрудного Cна, так и не поняв, в какую западню угодили, если мы только им не поможем. Тонкий ритуал сна нельзя нарушить без реликвий Пробуждения.$b$bОтправляйся в обитель и найди талисман Когтя Ворона, Черное перо, Небесный сапфир и руну Размещения. Друиды хранят их в священных ларцах. Принеси их мне, и я подготовлю ритуал пробуждения.','Добудьте реликвии Пробуждения.','Вернитесь к Атридасу Медвежьей Шкуре в Доланаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвии Пробуждения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Захватчиков Кривой Сосны видели в обители Бен\'этиль на западе, они крушили там все подряд.$b$bСпящие друиды могут так никогда и не выйти из Изумрудного Cна, так и не поняв, в какую западню угодили, если мы только им не поможем. Тонкий ритуал сна нельзя нарушить без реликвий Пробуждения.$b$bОтправляйся в обитель и найди талисман Когтя Ворона, Черное перо, Небесный сапфир и руну Размещения. Друиды хранят их в священных ларцах. Принеси их мне, и я подготовлю ритуал пробуждения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте реликвии Пробуждения.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Атридасу Медвежьей Шкуре в Доланаар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (484,'Шкуры молодых кроколисков','Ты, наверное, $Gслышал:слышала; обо мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему континенту!$b$bУже $gвстречался:встречалась; с Эйнаром? Он – один из охотников, приносящих мне шкуры.$b$bВ последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков.$b$bУчитывая обстоятельства, я готов заплатить высшую цену за стопку шкур. Молодые кроколиски водятся на болотах прямо за городом.','Принесите 4 шкуры молодых кроколисков Джеймсу Халлорану в Гавань Менетилов.','Отлично, превосходно! Прекрасные шкуры, $n! Надо немедленно замочить их... но перед этим я хотел бы попросить тебя еще об одной услуге. Думаю, ты справишься.','$n, я ведь тебя посылал за шкурами? Где же они?','Вернитесь к Джеймсу Халлорану в Гавань Менетилов, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шкуры молодых кроколисков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты, наверное, $Gслышал:слышала; обо мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему континенту!$b$bУже $gвстречался:встречалась; с Эйнаром? Он – один из охотников, приносящих мне шкуры.$b$bВ последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков.$b$bУчитывая обстоятельства, я готов заплатить высшую цену за стопку шкур. Молодые кроколиски водятся на болотах прямо за городом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 шкуры молодых кроколисков Джеймсу Халлорану в Гавань Менетилов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, превосходно! Прекрасные шкуры, $n! Надо немедленно замочить их... но перед этим я хотел бы попросить тебя еще об одной услуге. Думаю, ты справишься.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$n, я ведь тебя посылал за шкурами? Где же они?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джеймсу Халлорану в Гавань Менетилов, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`) VALUES (485,'Вы обнаружили странный металлический предмет яйцевидной формы. Когда вы нажали на какую-то кнопку, яйцо вдруг ожило, открылось и превратилось в непонятный механизм, который проскрежетал механическим голосом:$B$B"Меня зовут Карлс Пропеллерз, и мой автономный робот поврежден. Просьба найти робота, вставить в него этот маяк, а потом вернуть мне за вознаграждение".$B$B"Я вычислил координаты робота – он попал в аварию в устье реки близ Осклизлой скалы".','Отнесите аварийный маяк к автономному роботу Карлса. Робот находится во Внутренних землях, в устье реки близ Осклизлой скалы.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы обнаружили странный металлический предмет яйцевидной формы. Когда вы нажали на какую-то кнопку, яйцо вдруг ожило, открылось и превратилось в непонятный механизм, который проскрежетал механическим голосом:$B$B"Меня зовут Карлс Пропеллерз, и мой автономный робот поврежден. Просьба найти робота, вставить в него этот маяк, а потом вернуть мне за вознаграждение".$B$B"Я вычислил координаты робота – он попал в аварию в устье реки близ Осклизлой скалы".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите аварийный маяк к автономному роботу Карлса. Робот находится во Внутренних землях, в устье реки близ Осклизлой скалы.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (486,'Урсал Изверг','Настало время спасти друидов-воронов. Если сейчас мы потерпим неудачу, $n, их сон станет вечным.$b$bЯ подготовлю реликвии Пробуждения и совершу обряд. Но чтобы у меня все получилось, тварь, виновная в их злоключениях, должна быть уничтожена.$b$bЭто Урсал Изверг разрушил дело наших братьев, и именно он должен теперь заплатить за свои злодеяния ради их освобождения. Иди по дороге на северо-запад, потом поверни на север к Расселине. Там будет логово Урсала.','Убейте Урсала Изверга.','Вернитесь к Атридасу Медвежьей Шкуре в Доланаар.','Урсал, внушающий ужас предводитель фурболгов из племени Кривой Сосны. Чтобы леса были очищены, Урсал должен умереть.','Урсал Изверг') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урсал Изверг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настало время спасти друидов-воронов. Если сейчас мы потерпим неудачу, $n, их сон станет вечным.$b$bЯ подготовлю реликвии Пробуждения и совершу обряд. Но чтобы у меня все получилось, тварь, виновная в их злоключениях, должна быть уничтожена.$b$bЭто Урсал Изверг разрушил дело наших братьев, и именно он должен теперь заплатить за свои злодеяния ради их освобождения. Иди по дороге на северо-запад, потом поверни на север к Расселине. Там будет логово Урсала.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Урсала Изверга.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Атридасу Медвежьей Шкуре в Доланаар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Урсал, внушающий ужас предводитель фурболгов из племени Кривой Сосны. Чтобы леса были очищены, Урсал должен умереть.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Урсал Изверг',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (487,'Дорога в Дарнас','Дорогу в Дарнас нужно охранять. Путники, направляющиеся из Доланаара в Дарнас, рассказывают о варварских нападениях пораженных порчей фурболгов из племени Кривой Сосны.$b$bКаждый день из Дарнаса и в Дарнас не доходят грузы и важные сообщения. Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам.$b$bВозьмись же за оружие во имя священного леса, |3-6($c). Их логово находится где-то над этой северной дорогой. Убей душителей из племени Кривой Сосны и возвращайся ко мне.','Убейте 8 душителей из племени Кривой Сосны.','На дороге все еще неспокойно, |3-6($c). Ступай же и убей 6 душителей из Кривой Сосны, а потом возвращайся ко мне.','Вернитесь к часовому Амаре Ночной Страннице, ее можно найти к западу от Доланаара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога в Дарнас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дорогу в Дарнас нужно охранять. Путники, направляющиеся из Доланаара в Дарнас, рассказывают о варварских нападениях пораженных порчей фурболгов из племени Кривой Сосны.$b$bКаждый день из Дарнаса и в Дарнас не доходят грузы и важные сообщения. Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам.$b$bВозьмись же за оружие во имя священного леса, |3-6($c). Их логово находится где-то над этой северной дорогой. Убей душителей из племени Кривой Сосны и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 душителей из племени Кривой Сосны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На дороге все еще неспокойно, |3-6($c). Ступай же и убей 6 душителей из Кривой Сосны, а потом возвращайся ко мне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Амаре Ночной Страннице, ее можно найти к западу от Доланаара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (488,'Просьба Зенна','Вижу, ты ищешь работенку. Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце $Gюному:юной:c; |3-2($c) вроде тебя.$b$bВидишь ли, $n, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесешь.$b$bМне часто бывают нужны определенные... ингредиенты. Принеси клыки ночного саблезуба, перья островной совы и мотки паутины чащобного тенетника.$b$bИ пусть это все останется между нами, |3-6($r).','Достаньте 2 клыка ночного саблезуба, 2 пера островной совы и 2 мотка паутины чащобного тенетника.','Вернитесь к Зенну Грязному Копыту, его можно найти возле Доланаара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Зенна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вижу, ты ищешь работенку. Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце $Gюному:юной:c; |3-2($c) вроде тебя.$b$bВидишь ли, $n, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесешь.$b$bМне часто бывают нужны определенные... ингредиенты. Принеси клыки ночного саблезуба, перья островной совы и мотки паутины чащобного тенетника.$b$bИ пусть это все останется между нами, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте 2 клыка ночного саблезуба, 2 пера островной совы и 2 мотка паутины чащобного тенетника.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зенну Грязному Копыту, его можно найти возле Доланаара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (489,'Искупление вины','Соберите 3 шишки Скверны.','Ну что ты за лапочка! Я знал, что ты мне еще пригодишься!','Вернитесь к Зенну Грязному Копыту, его можно найти возле Доланаара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искупление вины',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 шишки Скверны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что ты за лапочка! Я знал, что ты мне еще пригодишься!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зенну Грязному Копыту, его можно найти возле Доланаара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (490,'<UNUSED>','By strict orders from the Council of Darnassus, I am commissioning a bounty on the Gnarlpine Tribe. They are no longer friends of the forest. Their corruption has left them mindless threats to our people and the creatures of the glade.$b$bAs decreed by the Council, you shall be rewarded for removing the furbolg menaces from Kalidar. Bring to me their fangs as proof of your deeds.','Шейла Ночной Бриз у ворот Дарнаса просит принести ей 20 клыков фурболгов из племени Кривой Сосны.','Вернитесь к часовому Шейле Ночному Бризу в Тельдрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','By strict orders from the Council of Darnassus, I am commissioning a bounty on the Gnarlpine Tribe. They are no longer friends of the forest. Their corruption has left them mindless threats to our people and the creatures of the glade.$b$bAs decreed by the Council, you shall be rewarded for removing the furbolg menaces from Kalidar. Bring to me their fangs as proof of your deeds.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Шейла Ночной Бриз у ворот Дарнаса просит принести ей 20 клыков фурболгов из племени Кривой Сосны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Шейле Ночному Бризу в Тельдрассил.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (491,'Жезл для Бетора','Туле как-то рассказывал мне, что давным-давно он вместе с двумя товарищами создал магический жезл, сплетя его из трех принадлежащих им ученических жезлов. Он был символом их дружбы, и, хотя Тул презрел ее, с жезлом он расстаться не мог и не желал отдавать его другим. Поэтому он выкрал жезл и спрятал его в крепости Фенриса.$b$bЗдесь. Отнесите жезл Бетору Ледострелу, одному из прежних друзей Тула. Я уверен, он будет рад его получить.','Отнесите Сплетенный жезл Бетору Ледострелу в Квартал Магов Подгорода.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жезл для Бетора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Туле как-то рассказывал мне, что давным-давно он вместе с двумя товарищами создал магический жезл, сплетя его из трех принадлежащих им ученических жезлов. Он был символом их дружбы, и, хотя Тул презрел ее, с жезлом он расстаться не мог и не желал отдавать его другим. Поэтому он выкрал жезл и спрятал его в крепости Фенриса.$b$bЗдесь. Отнесите жезл Бетору Ледострелу, одному из прежних друзей Тула. Я уверен, он будет рад его получить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Сплетенный жезл Бетору Ледострелу в Квартал Магов Подгорода.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (492,'Новая чума','Один из стражей смерти сообщил, что недавно был захвачен еще один дворф-горный пехотинец. Обычно стражи смерти сажают пленных в погреб таверны "Петля Висельника", где им оказывается "достойный прием".$B$BПочему бы тебе не пойти и не угостить пленника специальным напитком, который я приготовил? В нем есть небольшая примесь того, что Темная Госпожа готовит для всего Азерота.','Отнесите особый напиток Юхана пленному горному пехотинцу.','Ах, наконец-то питье! Хоть это и не "Болтливое пиво", но я рад хоть чем-то промочить горло.','Будь у меня моя верная винтовка, вы были бы уже мертвы, |3-6($C)! Погодите, скоро мне на помощь приедет бригада паровых танков!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая чума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из стражей смерти сообщил, что недавно был захвачен еще один дворф-горный пехотинец. Обычно стражи смерти сажают пленных в погреб таверны "Петля Висельника", где им оказывается "достойный прием".$B$BПочему бы тебе не пойти и не угостить пленника специальным напитком, который я приготовил? В нем есть небольшая примесь того, что Темная Госпожа готовит для всего Азерота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите особый напиток Юхана пленному горному пехотинцу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, наконец-то питье! Хоть это и не "Болтливое пиво", но я рад хоть чем-то промочить горло.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будь у меня моя верная винтовка, вы были бы уже мертвы, |3-6($C)! Погодите, скоро мне на помощь приедет бригада паровых танков!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (493,'Путешествие в предгорья Хилсбрада','Темная Госпожа давит на Королевское фармацевтическое общество, чтобы оно поскорее разработало Новую чуму. Мы упорно трудимся и добились значительного прогресса. Мы уверены, что успех был бы достигнут значительно быстрее, если бы мы могли распространять информацию среди членов общества. $b$bПоэтому я хотел бы, чтобы вы доставили мои последние находки аптекарю Лидону в Мельницу Таррен – небольшой городок, расположенный в предгорьях Хилсбрада. Путь туда неблизкий. $b$bНаправляйтесь на юг и держитесь поближе к дорогам. Строго следуйте дорожным указателям!','Отнесите находки аптекаря Ренферрела аптекарю Лидону в деревню Мельница Таррен в предгорьях Хилсбрада.','А, отлично. Я в высшей степени уважаю аптекаря Ренферрела. Сгораю от нетерпения начать изучение его работы.','У вас ко мне какое-то дело?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в предгорья Хилсбрада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Темная Госпожа давит на Королевское фармацевтическое общество, чтобы оно поскорее разработало Новую чуму. Мы упорно трудимся и добились значительного прогресса. Мы уверены, что успех был бы достигнут значительно быстрее, если бы мы могли распространять информацию среди членов общества. $b$bПоэтому я хотел бы, чтобы вы доставили мои последние находки аптекарю Лидону в Мельницу Таррен – небольшой городок, расположенный в предгорьях Хилсбрада. Путь туда неблизкий. $b$bНаправляйтесь на юг и держитесь поближе к дорогам. Строго следуйте дорожным указателям!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите находки аптекаря Ренферрела аптекарю Лидону в деревню Мельница Таррен в предгорьях Хилсбрада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, отлично. Я в высшей степени уважаю аптекаря Ренферрела. Сгораю от нетерпения начать изучение его работы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас ко мне какое-то дело?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (494,'Время нанести удар','Молчи и слушай, |3-6($c).$B$BМеня направили сюда для наблюдения за Хилсбрадом. У меня разведывательная миссия. А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен. Скажи, что ловчая смерти Леш передала следующие слова:$B$B"Крик ворона на западе манит."$b$bСтупай по дороге на восток и обращай внимание на знаки. Торопись! Ступай в Мельницу Таррен со всей возможной поспешностью!','Отправляйтесь в Мельницу Таррен и доставьте послание ловчей смерти Леш верховному палачу Дарталии.','Крик ворона на западе манит?\n\nОтличные новости! Пора напасть на Хилсбрад. Мы сможем воплотить наш план уничтожения жизни. Вариматас будет доволен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время нанести удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Молчи и слушай, |3-6($c).$B$BМеня направили сюда для наблюдения за Хилсбрадом. У меня разведывательная миссия. А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен. Скажи, что ловчая смерти Леш передала следующие слова:$B$B"Крик ворона на западе манит."$b$bСтупай по дороге на восток и обращай внимание на знаки. Торопись! Ступай в Мельницу Таррен со всей возможной поспешностью!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Мельницу Таррен и доставьте послание ловчей смерти Леш верховному палачу Дарталии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Крик ворона на западе манит?\n\nОтличные новости! Пора напасть на Хилсбрад. Мы сможем воплотить наш план уничтожения жизни. Вариматас будет доволен.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (495,'Корона Воли','Муг\'тола и его отряд огров отправили в Альтеракскую долину за короной Воли для леди Сильваны. К сожалению, вместо того чтобы принести ее королеве, этот идиот решил ее примерить... наверное, огры не могут устоять перед блестящими побрякушками.$B$BЕго необдуманный поступок привел к неприятным последствиям. Корона Воли позволила Муг\'толу воспротивиться заклинанию подчинения, наложенному на него леди Сильваной.$B$BТемная Госпожа хочет, чтобы это стало уроком для остальных. Отправляйся на мельницу Таррен в Хилсбраде и поговори с лейтенантом Мелизарой.','Поговорите с Мелизарой в Мельнице Таррен в предгорьях Хилсбрада.','Тебя прислала Шарлиндра? Ну хорошо. Вскоре ты поймешь, что я не терплю пустой болтовни.\n\nМуг\'тол – наглец, и с ним мы разберемся быстро, тщательно и безжалостно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корона Воли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Муг\'тола и его отряд огров отправили в Альтеракскую долину за короной Воли для леди Сильваны. К сожалению, вместо того чтобы принести ее королеве, этот идиот решил ее примерить... наверное, огры не могут устоять перед блестящими побрякушками.$B$BЕго необдуманный поступок привел к неприятным последствиям. Корона Воли позволила Муг\'толу воспротивиться заклинанию подчинения, наложенному на него леди Сильваной.$B$BТемная Госпожа хочет, чтобы это стало уроком для остальных. Отправляйся на мельницу Таррен в Хилсбраде и поговори с лейтенантом Мелизарой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мелизарой в Мельнице Таррен в предгорьях Хилсбрада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислала Шарлиндра? Ну хорошо. Вскоре ты поймешь, что я не терплю пустой болтовни.\n\nМуг\'тол – наглец, и с ним мы разберемся быстро, тщательно и безжалостно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (496,'Эликсир Страдания','Ах, еще один мерзкий день на мельнице Таррен. От этого чистого воздуха у меня сразу портится настроение, $n.$b$bЧем скорее мы заразим здешних людей, тем лучше. Я провожу исследования различных смертоносных веществ, чтобы использовать их в моих составах, но собрать все времени не хватило.$B$BЕсли ты хочешь принести пользу, добудь для меня следующее: 10 языков серых медведей и очень редкую и труднодоступную лимфу паука-охотника. Медведи и пауки-охотники живут рядом с мельницей Таррен.','Аптекарь Лидон из Мельницы Таррен попросил принести ему 10 языков серых медведей и немного лимфы паука-охотника.','Я вижу, ты вернулся. Надеюсь, тебе удалось собрать нужные мне вещества. Еще один день без единой смерти совсем в тоску меня вгонит.','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир Страдания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, еще один мерзкий день на мельнице Таррен. От этого чистого воздуха у меня сразу портится настроение, $n.$b$bЧем скорее мы заразим здешних людей, тем лучше. Я провожу исследования различных смертоносных веществ, чтобы использовать их в моих составах, но собрать все времени не хватило.$B$BЕсли ты хочешь принести пользу, добудь для меня следующее: 10 языков серых медведей и очень редкую и труднодоступную лимфу паука-охотника. Медведи и пауки-охотники живут рядом с мельницей Таррен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аптекарь Лидон из Мельницы Таррен попросил принести ему 10 языков серых медведей и немного лимфы паука-охотника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я вижу, ты вернулся. Надеюсь, тебе удалось собрать нужные мне вещества. Еще один день без единой смерти совсем в тоску меня вгонит.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (497,'<UNUSED>','As a child, raised as a gladiator at Durnholde Keep, I was befriended by Taretha, the daughter of my wet nurse and mistress of the damned bastard Blackmoore.$b$bThe past is the past, $n, but reports of human movements in Hillsbrad reminded me of that time. I dispatched a small party to the area to investigate and to retrieve an... item... given to me by Taretha, if they could.$b$bA fruitless task, no doubt, but perhaps...$b$bThey should have returned by now, I want you to go to Tarren Mill to investigate.','Go to Tarren Mill and find out the status of the party sent by Thrall.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','As a child, raised as a gladiator at Durnholde Keep, I was befriended by Taretha, the daughter of my wet nurse and mistress of the damned bastard Blackmoore.$b$bThe past is the past, $n, but reports of human movements in Hillsbrad reminded me of that time. I dispatched a small party to the area to investigate and to retrieve an... item... given to me by Taretha, if they could.$b$bA fruitless task, no doubt, but perhaps...$b$bThey should have returned by now, I want you to go to Tarren Mill to investigate.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Go to Tarren Mill and find out the status of the party sent by Thrall.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (498,'Спасение','Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат.$b$bМы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей. Мы бились изо всех сил, но они сильно превосходили нас числом. В конце концов нескольких из нас взяли в плен, но мне удалось сбежать.$b$bДарнхольд находится на юго-востоке отсюда, по ту сторону реки. Там держат Друлла и Тог\'тара, освободи их.','Krusk in Tarren Mill needs you to free Drull and Tog\'thar from Durnholde Keep.','Ты $Gдолжен:должна; поторопиться, $C. Мне страшно подумать, что люди могут сделать с Друллом и Тог\'таром.','Вернитесь к Круску на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат.$b$bМы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей. Мы бились изо всех сил, но они сильно превосходили нас числом. В конце концов нескольких из нас взяли в плен, но мне удалось сбежать.$b$bДарнхольд находится на юго-востоке отсюда, по ту сторону реки. Там держат Друлла и Тог\'тара, освободи их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Krusk in Tarren Mill needs you to free Drull and Tog\'thar from Durnholde Keep.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдолжен:должна; поторопиться, $C. Мне страшно подумать, что люди могут сделать с Друллом и Тог\'таром.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Круску на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (499,'Эликсир Страдания','Мне понадобится совсем немного времени для создания того, что я хочу наречь эликсиром Страдания.$B$BВот, готово! Ах, ничто не доставляет столько радости в этих проклятых холмах, как принесение страдания в мир.$B$BПосмотрим, достигнут ли желанный эффект.$b$bДай попробовать моему помощнику Ампи то, что Темная Госпожа готовит людям и созданиям Плети.','Дайте Ампи эликсир Страдания.','Квак!','Ква!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир Страдания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне понадобится совсем немного времени для создания того, что я хочу наречь эликсиром Страдания.$B$BВот, готово! Ах, ничто не доставляет столько радости в этих проклятых холмах, как принесение страдания в мир.$B$BПосмотрим, достигнут ли желанный эффект.$b$bДай попробовать моему помощнику Ампи то, что Темная Госпожа готовит людям и созданиям Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дайте Ампи эликсир Страдания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Квак!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ква!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (500,'Награда Раздробленного Хребта','Огры из клана Раздробленного Хребта раскопали курган в Альтеракских горах, неподалеку от разрушенного города. Разведчики доносят, что они и сами руины захватили.$B$BМы не дадим им там вольготно расположиться; если они решат, что хорошо устроились, то следующим шагом спустятся с холмов и окажутся прямо рядом с нами!$B$BСтупай на север, в Альтеракские горы и убей побольше огров. Принеси мне грязные кости, которые они таскают с собой, и получишь неплохую награду.','Соберите 9 грязных костей у огров из клана Раздробленного Хребта в Альтеракских горах. Принесите их маршалу Редпату в Южнобережье.','Вернитесь к маршалу Редпату в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда Раздробленного Хребта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огры из клана Раздробленного Хребта раскопали курган в Альтеракских горах, неподалеку от разрушенного города. Разведчики доносят, что они и сами руины захватили.$B$BМы не дадим им там вольготно расположиться; если они решат, что хорошо устроились, то следующим шагом спустятся с холмов и окажутся прямо рядом с нами!$B$BСтупай на север, в Альтеракские горы и убей побольше огров. Принеси мне грязные кости, которые они таскают с собой, и получишь неплохую награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 9 грязных костей у огров из клана Раздробленного Хребта в Альтеракских горах. Принесите их маршалу Редпату в Южнобережье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Редпату в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (501,'Эликсир боли','О, $n... Луга Хилсбрада полны цветов, воздух свеж и приятен. Меня от этого просто тошнит! Я смотрю в мутное окно и мечтаю о наступлении дня, когда Новая чума принесет в мир заслуженную смерть!$B$BНо как бы мне ни хотелось сидеть и мечтать – прежде всего приказы Темной Госпожи. Помоги мне! В результате исследований я обнаружил, что из крови горного льва можно создать великолепный напиток смерти. Принеси мне немного крови, и мы повеселимся.','Принесите 10 сосудов крови горного льва аптекарю Лидону из Мельницы Таррен.','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир боли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, $n... Луга Хилсбрада полны цветов, воздух свеж и приятен. Меня от этого просто тошнит! Я смотрю в мутное окно и мечтаю о наступлении дня, когда Новая чума принесет в мир заслуженную смерть!$B$BНо как бы мне ни хотелось сидеть и мечтать – прежде всего приказы Темной Госпожи. Помоги мне! В результате исследований я обнаружил, что из крови горного льва можно создать великолепный напиток смерти. Принеси мне немного крови, и мы повеселимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 сосудов крови горного льва аптекарю Лидону из Мельницы Таррен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (502,'Эликсир боли','Ах, ничто так не радует, как запах свежей крови в предгорьях!$b$bСмешаем капелюшку этого и щепотку того, и пойдет веселье! Из этой крови я сделаю эликсир Боли. Если мои вычисления верны, то этот состав порадует леди Сильвану. Надо его испытать.$b$bОтнеси этот эликсир на самую северную ферму Хилсбрадских полей, что на юго-западе. Посмотрим, как мое "угощение" понравится собачке фермера Рея, Стэнли.','Напоите Стэнли эликсиром Боли.','Вы наливаете немного эликсира в ладонь и протягиваете ее Стэнли.','Ав?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир боли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, ничто так не радует, как запах свежей крови в предгорьях!$b$bСмешаем капелюшку этого и щепотку того, и пойдет веселье! Из этой крови я сделаю эликсир Боли. Если мои вычисления верны, то этот состав порадует леди Сильвану. Надо его испытать.$b$bОтнеси этот эликсир на самую северную ферму Хилсбрадских полей, что на юго-западе. Посмотрим, как мое "угощение" понравится собачке фермера Рея, Стэнли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Напоите Стэнли эликсиром Боли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы наливаете немного эликсира в ладонь и протягиваете ее Стэнли.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ав?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (503,'Гол\'дир','Судя по добытым тобой документам, Гол\'дира держат на большой базе Синдиката, расположенной на севере, вероятно, в Альтеракских горах. Он уж очень давно томится там в плену, пора освободить его.','Освободите Гол\'дира и возвращайтесь к Круску в Мельницу Таррен.','Дай мне ключ, |3-6($C), и я сам отомкну замок.','Найдите, где держат в плену Гол\'дира.','Вернитесь к Гол\'диру в Высокогорье, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гол\'дир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по добытым тобой документам, Гол\'дира держат на большой базе Синдиката, расположенной на севере, вероятно, в Альтеракских горах. Он уж очень давно томится там в плену, пора освободить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите Гол\'дира и возвращайтесь к Круску в Мельницу Таррен.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дай мне ключ, |3-6($C), и я сам отомкну замок.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите, где держат в плену Гол\'дира.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гол\'диру в Высокогорье, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (504,'Наемники клана Раздробленного Хребта','Ты уже $gпомерился:померилась; силой с ограми Раздробленного Хребта, а теперь я хочу нанести им настоящий удар...$B$BСтупай в руины Альтерака и отыщи там наемников из клана Раздробленного Хребта. Убей побольше этих тварей – только так им можно показать, что лучше держаться подальше от земель Альянса.','Убейте 10 солдат-наемников из клана Раздробленного Хребта и возвращайтесь к маршалу Редпату в Южнобережье.','Тебе нужно убить больше солдат-наемников, $N. Выполняя свою задачу, вы должны быть в горах, а не здесь с оружием в руках.','Вернитесь к маршалу Редпату в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наемники клана Раздробленного Хребта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gпомерился:померилась; силой с ограми Раздробленного Хребта, а теперь я хочу нанести им настоящий удар...$B$BСтупай в руины Альтерака и отыщи там наемников из клана Раздробленного Хребта. Убей побольше этих тварей – только так им можно показать, что лучше держаться подальше от земель Альянса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 солдат-наемников из клана Раздробленного Хребта и возвращайтесь к маршалу Редпату в Южнобережье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе нужно убить больше солдат-наемников, $N. Выполняя свою задачу, вы должны быть в горах, а не здесь с оружием в руках.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Редпату в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (505,'Убийцы из Синдиката','Меня недавно назначили мировым судьей в Южнобережье. Моего предшественника убили, и виновников так и не нашли. Впрочем, расследование показало, что скорее всего их нанял Синдикат – группа воров под командованием злодеев-дворян, бывшей знати павшего королевства Альтерак.$b$bЛагеря Синдиката расположены на Возвышенности Соферы и на Кинжале Коррана, на севере и на западе от захваченной Ордой Мельницы Таррен. Убей всех союзников Синдиката, которых встретишь в этих лагерях.','Убейте 12 преступников и 8 воров Синдиката и возвращайтесь к мировому судье Генри Малебу в Южнобережье.','Я полагаю, вы убили этих головорезов Синдиката?','Вернитесь к мировому судье Генри Малебу в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убийцы из Синдиката',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня недавно назначили мировым судьей в Южнобережье. Моего предшественника убили, и виновников так и не нашли. Впрочем, расследование показало, что скорее всего их нанял Синдикат – группа воров под командованием злодеев-дворян, бывшей знати павшего королевства Альтерак.$b$bЛагеря Синдиката расположены на Возвышенности Соферы и на Кинжале Коррана, на севере и на западе от захваченной Ордой Мельницы Таррен. Убей всех союзников Синдиката, которых встретишь в этих лагерях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 преступников и 8 воров Синдиката и возвращайтесь к мировому судье Генри Малебу в Южнобережье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я полагаю, вы убили этих головорезов Синдиката?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Генри Малебу в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (506,'Наследие Блэкмура','День или два назад ко мне пришел главарь этого Синдиката. Его звали Алиден Перенольд, и он нарек себя лордом этих земель. Он поверил мне свои планы о порабощении орков, выступивших против него, как и планировал его отец и учитель, ненавистный Блэкмур.$B$BКуда важнее то, что он привел с собой свою любовницу, девочку-тростинку по имени Элайза. У нее на шее висело ожерелье, который жаждет заполучить Вождь.$B$BСтупай, мне пора уходить, когда я закончу свои дела в лагере.','Отнесите собранные Гол\'диром сведения Круску на мельницу Таррен.','Надо же, какие наглецы эти люди! Мы покажем им, что орки не сдаются!\n\nОтныне это будет нашей целью наравне с тем украшением, которое стремится заполучить наш Вождь. Похоже, одной цели без другой не достичь.','Дай мне ключ, |3-6($C), и я сам отомкну замок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Блэкмура',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','День или два назад ко мне пришел главарь этого Синдиката. Его звали Алиден Перенольд, и он нарек себя лордом этих земель. Он поверил мне свои планы о порабощении орков, выступивших против него, как и планировал его отец и учитель, ненавистный Блэкмур.$B$BКуда важнее то, что он привел с собой свою любовницу, девочку-тростинку по имени Элайза. У нее на шее висело ожерелье, который жаждет заполучить Вождь.$B$BСтупай, мне пора уходить, когда я закончу свои дела в лагере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите собранные Гол\'диром сведения Круску на мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надо же, какие наглецы эти люди! Мы покажем им, что орки не сдаются!\n\nОтныне это будет нашей целью наравне с тем украшением, которое стремится заполучить наш Вождь. Похоже, одной цели без другой не достичь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дай мне ключ, |3-6($C), и я сам отомкну замок.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (507,'Лорд Алиден Перенольд','Очевидно, что Перенольда необходимо убить, избавив мир от его гнусной сущности. Его поместье расположено к северу отсюда, на берегах озера Лордамер. Твой долг, $n, добыть медальон для Вождя и вернуться сюда.','Убейте лорда Алидена Перенольда и допросите его любовницу Элайзу насчет ожерелья Тареты.','Нет, прошу вас, не убивайте меня! Я не хотела причинять зло вашему народу, он взял меня против воли! Пожалуйста... Пощадите меня!','Ч-что вам нужно?','Вернитесь к Элайзе в Высокогорье, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорд Алиден Перенольд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Очевидно, что Перенольда необходимо убить, избавив мир от его гнусной сущности. Его поместье расположено к северу отсюда, на берегах озера Лордамер. Твой долг, $n, добыть медальон для Вождя и вернуться сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Алидена Перенольда и допросите его любовницу Элайзу насчет ожерелья Тареты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет, прошу вас, не убивайте меня! Я не хотела причинять зло вашему народу, он взял меня против воли! Пожалуйста... Пощадите меня!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ч-что вам нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элайзе в Высокогорье, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (508,'Подарок Тареты','Ожерелье? Конечно же, можешь его забрать... Да, забирай! Мне не нужны воспоминания о нем... Просто оставь меня в покое...','Верните ожерелье Тареты Круску в деревню Мельница Таррен, что в Предгорьях Хилсбрада.','Странно, что вождь пошел на такие затраты ради этой мелочи. Я не всегда понимаю его мотивы, но я последую за ним, каковы бы ни были его приказы. Ты отлично $Gпоработал:поработала;, $N, и я не сомневаюсь, что вождь будет рад услышать о твоем успехе.','А, вот и ты, $N. Сопутствовала ли тебе удача?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок Тареты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ожерелье? Конечно же, можешь его забрать... Да, забирай! Мне не нужны воспоминания о нем... Просто оставь меня в покое...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните ожерелье Тареты Круску в деревню Мельница Таррен, что в Предгорьях Хилсбрада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Странно, что вождь пошел на такие затраты ради этой мелочи. Я не всегда понимаю его мотивы, но я последую за ним, каковы бы ни были его приказы. Ты отлично $Gпоработал:поработала;, $N, и я не сомневаюсь, что вождь будет рад услышать о твоем успехе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, вот и ты, $N. Сопутствовала ли тебе удача?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (509,'Эликсир агонии','Новый день, новый эликсир. Если бы я тут командовал, я бы позволил Плети и жалким людишкам сцепиться между собой. Им и так нравится убивать друг друга.$B$BУвы, Темная Госпожа хочет ускорить процесс, так почему бы не скрасить унылые дни распространением смерти и болезней по стране.$B$BВот мой план: иди-ка ты во Владение Нетандера на юге от Мельницы Таррен и на востоке от реки и Южнобережья. Принеси мне 6 цветков Грязного Рыла для нового эликсира.','Принесите 6 цветков Грязного Рыла аптекарю Лидону из Мельницы Таррен.','А, отвратительная вонь цветков Грязного Рыла. Хоть для чего-то эти грязные гноллы годятся.','Как дела во Владении Нетандера?','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир агонии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Новый день, новый эликсир. Если бы я тут командовал, я бы позволил Плети и жалким людишкам сцепиться между собой. Им и так нравится убивать друг друга.$B$BУвы, Темная Госпожа хочет ускорить процесс, так почему бы не скрасить унылые дни распространением смерти и болезней по стране.$B$BВот мой план: иди-ка ты во Владение Нетандера на юге от Мельницы Таррен и на востоке от реки и Южнобережья. Принеси мне 6 цветков Грязного Рыла для нового эликсира.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 цветков Грязного Рыла аптекарю Лидону из Мельницы Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, отвратительная вонь цветков Грязного Рыла. Хоть для чего-то эти грязные гноллы годятся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как дела во Владении Нетандера?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (510,'Зловещие планы','Среди документов вы находите список необходимых припасов. В их число входят самые простые вещи (еда, оружие, одежда) и несколько необычные (маски, масло, яд).$B$BВпрочем, более всего привлекает внимание срочность запроса – согласно документу, доставить все необходимое следует как можно скорее, чтобы "выполнить важную миссию, нацеленную против Южнобережья".','Отнесите зловещие планы мировому судье Южнобережья Малебу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зловещие планы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среди документов вы находите список необходимых припасов. В их число входят самые простые вещи (еда, оружие, одежда) и несколько необычные (маски, масло, яд).$B$BВпрочем, более всего привлекает внимание срочность запроса – согласно документу, доставить все необходимое следует как можно скорее, чтобы "выполнить важную миссию, нацеленную против Южнобережья".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите зловещие планы мировому судье Южнобережья Малебу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (511,'Зашифрованное письмо','Одно из писем на столе зашифровано.','Отнесите зашифрованное письмо хранителю мудрости Диббсу в Южнобережье.','Что это? Минуточку... Дай-ка взглянуть поближе.$B$B...$B$BХм, никогда не встречался с таким шифром, но, признаться, в этой области я не очень сведущ.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зашифрованное письмо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одно из писем на столе зашифровано.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите зашифрованное письмо хранителю мудрости Диббсу в Южнобережье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Минуточку... Дай-ка взглянуть поближе.$B$B...$B$BХм, никогда не встречался с таким шифром, но, признаться, в этой области я не очень сведущ.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (512,'Благородные смерти','Боюсь, что главари Синдиката жаждут гибели Южнобережья. Мы должны нанести удар первыми, пока они не успели воплотить свои планы.$b$bОтправляйся в руины Странбрада, в северной части Альтеракских гор. Мы полагаем, что именно там находится штаб-квартира Синдиката.$b$bНам известно, что эту шайку головорезов возглавляет бывшая знать Альтерака. Дворяне скрываются среди прочих посланников Синдиката, но отличить их можно по перстням-печаткам. Разумеется, прежде необходимо их убить.$B$BПринеси мне эти перстни.','Принесите 7 альтеракских перстней-печаток мировому судье Малебу в Южнобережье.','Вернитесь к мировому судье Генри Малебу в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благородные смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, что главари Синдиката жаждут гибели Южнобережья. Мы должны нанести удар первыми, пока они не успели воплотить свои планы.$b$bОтправляйся в руины Странбрада, в северной части Альтеракских гор. Мы полагаем, что именно там находится штаб-квартира Синдиката.$b$bНам известно, что эту шайку головорезов возглавляет бывшая знать Альтерака. Дворяне скрываются среди прочих посланников Синдиката, но отличить их можно по перстням-печаткам. Разумеется, прежде необходимо их убить.$B$BПринеси мне эти перстни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 альтеракских перстней-печаток мировому судье Малебу в Южнобережье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Генри Малебу в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (513,'Эликсир агонии','Я уже решил, что еще один день пройдет без капли радости, но тут ты $gпринес:принесла; мне цветки Грязного Рыла.$b$bДля начала я приготовлю из них отличную смесь. Потом нам понадобится помощь мастера-аптекаря Фаранелла из Подгорода. Он должен добавить туда коллоид разложения и тогда-то самое веселье и начнется!$b$bВот возьми этот состав Грязного Рыла и немедленно отнеси его аптекарю Фаранеллу.','Отнесите смесь из цветков Грязного Рыла опытному аптекарю Фаранеллу в Подгород.','Тебя послал аптекарь Лидон? Что ж ты сразу не сказал!\n\nНевзирая на угрюмый нрав, аптекарь Лидон – один из наших самых преданных и умелых сотрудников.\n\nОн прислал состав Грязного Рыла, какой умница! Я знаю, что замышляет наш друг из Хилсбрада. И мне нравится ход его мысли. Темная Госпожа порадуется наступлению новой чумы.','Видишь, я занят, |3-6($C)? Темная Госпожа велит вывести новую чуму, пока нас не одолела Плеть со стороны Нордскола. С юга же нас теснят люди, поэтому время сейчас – главная ценность. Надеюсь, ты не по пустякам меня тревожишь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир агонии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже решил, что еще один день пройдет без капли радости, но тут ты $gпринес:принесла; мне цветки Грязного Рыла.$b$bДля начала я приготовлю из них отличную смесь. Потом нам понадобится помощь мастера-аптекаря Фаранелла из Подгорода. Он должен добавить туда коллоид разложения и тогда-то самое веселье и начнется!$b$bВот возьми этот состав Грязного Рыла и немедленно отнеси его аптекарю Фаранеллу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите смесь из цветков Грязного Рыла опытному аптекарю Фаранеллу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал аптекарь Лидон? Что ж ты сразу не сказал!\n\nНевзирая на угрюмый нрав, аптекарь Лидон – один из наших самых преданных и умелых сотрудников.\n\nОн прислал состав Грязного Рыла, какой умница! Я знаю, что замышляет наш друг из Хилсбрада. И мне нравится ход его мысли. Темная Госпожа порадуется наступлению новой чумы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Видишь, я занят, |3-6($C)? Темная Госпожа велит вывести новую чуму, пока нас не одолела Плеть со стороны Нордскола. С юга же нас теснят люди, поэтому время сейчас – главная ценность. Надеюсь, ты не по пустякам меня тревожишь!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (514,'Письмо Грозовой Вершине','У меня есть коллега из Стальгорна, который может расшифровать это письмо. Ступай в Библиотеку в Зале Исследователей Стальгорна и поговори с геологом Грозовой Вершиной. Скажи ему, что тебя прислал я и покажи письмо. Если кто и может прочитать это во всех землях к северу от Пика Черной горы, то это он.','Отнесите хитро зашифрованное письмо геологу Грозовой Вершине в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Письмо Грозовой Вершине',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть коллега из Стальгорна, который может расшифровать это письмо. Ступай в Библиотеку в Зале Исследователей Стальгорна и поговори с геологом Грозовой Вершиной. Скажи ему, что тебя прислал я и покажи письмо. Если кто и может прочитать это во всех землях к северу от Пика Черной горы, то это он.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите хитро зашифрованное письмо геологу Грозовой Вершине в Стальгорн.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (515,'Эликсир агонии','Смесь из цветков Грязного Рыла? Гениально! Почему мне не пришло это в голову?$B$BПожалуй, я добавлю свой коллоид разложения в эту хитрую смесь.$b$bЧтобы активировать отраву в смеси, Лидону понадобится крепкое зелье тролльей крови, немного чешуи наги из клана Пронзающего Гребня и глаза мурлоков из клана Рваный Плавник с южного берега Хилсбрада. Когда ты принесешь ему все составляющие, он мигом все сделает. Ох, как мне не терпится узнать о результатах его эксперимента!','Отнесите микстуру из цветков Грязного Рыла, крепкое зелье тролльей крови, 5 чешуек нагов из клана Пронзающего Гребня и 5 глаз мурлоков из клана Рваный Плавник аптекарю Лидону в Мельницу Таррен.','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир агонии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смесь из цветков Грязного Рыла? Гениально! Почему мне не пришло это в голову?$B$BПожалуй, я добавлю свой коллоид разложения в эту хитрую смесь.$b$bЧтобы активировать отраву в смеси, Лидону понадобится крепкое зелье тролльей крови, немного чешуи наги из клана Пронзающего Гребня и глаза мурлоков из клана Рваный Плавник с южного берега Хилсбрада. Когда ты принесешь ему все составляющие, он мигом все сделает. Ох, как мне не терпится узнать о результатах его эксперимента!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите микстуру из цветков Грязного Рыла, крепкое зелье тролльей крови, 5 чешуек нагов из клана Пронзающего Гребня и 5 глаз мурлоков из клана Рваный Плавник аптекарю Лидону в Мельницу Таррен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (516,'Погибель Берена','Я получил сообщение, что группа нежити спряталась и готовит атаку против нас. Вооруженные этой информацией, мы можем повернуть все другой стороной и напасть первыми, подавив их планы в самом зародыше. $b$bК сожалению, моя информация весьма обрывочная. Говорят, они скрываются в месте, называемом Погибель Берена. Точное местонахождение неизвестно, но, похоже, это пещера где-то в холмах, недалеко от участка, занятого даларанскими волшебниками. $b$bЯ полагаюсь на твою изобретательность. Отыщи их и нанеси им сокрушительный удар.','Найдите Погибель Берена, убейте 6 чернорабочих Когтя Ворона и 6 стражей Когтя Ворона, а затем вернитесь в Гробницу к темному жрецу Алистеру.','Если наши разведчики и агенты продолжат предоставлять столь же ценную информацию, как эта, мы в мгновение ока очистим наши земли от армии Плети Короля-лича.','Вернитесь к темному жрецу Алистеру в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погибель Берена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я получил сообщение, что группа нежити спряталась и готовит атаку против нас. Вооруженные этой информацией, мы можем повернуть все другой стороной и напасть первыми, подавив их планы в самом зародыше. $b$bК сожалению, моя информация весьма обрывочная. Говорят, они скрываются в месте, называемом Погибель Берена. Точное местонахождение неизвестно, но, похоже, это пещера где-то в холмах, недалеко от участка, занятого даларанскими волшебниками. $b$bЯ полагаюсь на твою изобретательность. Отыщи их и нанеси им сокрушительный удар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Погибель Берена, убейте 6 чернорабочих Когтя Ворона и 6 стражей Когтя Ворона, а затем вернитесь в Гробницу к темному жрецу Алистеру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если наши разведчики и агенты продолжат предоставлять столь же ценную информацию, как эта, мы в мгновение ока очистим наши земли от армии Плети Короля-лича.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному жрецу Алистеру в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (517,'Эликсир агонии','Пришло время испытать новый эликсир. Но зачем же тратить хорошую, очень заразную болезнь на простых лягушек и собак? Давай устроим настоящее веселье во имя леди Сильваны.$B$BСтупай в Дун Гарок. Знаешь, это казармы, где вечно шныряют эти дворфишки. Укради у них бочонок "Землекопского портера". Получив его, я устрою веселую вечеринку!','Принесите бочонок "Землекопского портера" аптекарю Лидону из Мельницы Таррен.','Наконец-то! Теперь мы готовы действовать!','Иногда я впадаю в такую тоску в этом городишке, что открываю кувшин формальдегида и наслаждаюсь ароматом. Ампи начинает нервничать.\n\nНу что, удалось добыть бочку у дворфов? Честное слово, если я буду пялиться на этот эликсир целый день и ни на ком его не опробую, я закричу!','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир агонии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время испытать новый эликсир. Но зачем же тратить хорошую, очень заразную болезнь на простых лягушек и собак? Давай устроим настоящее веселье во имя леди Сильваны.$B$BСтупай в Дун Гарок. Знаешь, это казармы, где вечно шныряют эти дворфишки. Укради у них бочонок "Землекопского портера". Получив его, я устрою веселую вечеринку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите бочонок "Землекопского портера" аптекарю Лидону из Мельницы Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то! Теперь мы готовы действовать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Иногда я впадаю в такую тоску в этом городишке, что открываю кувшин формальдегида и наслаждаюсь ароматом. Ампи начинает нервничать.\n\nНу что, удалось добыть бочку у дворфов? Честное слово, если я буду пялиться на этот эликсир целый день и ни на ком его не опробую, я закричу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (518,'Корона Воли','Муг\'тол и огры Раздробленного Хребта захватили руины Альтерака. Наказать их всерьез будет нелегко, если не проредить сначала ряды огров.$B$BА уж потом мы продолжим.$B$BЯсно? Отлично. Выполняй.','Убейте 10 извергов из клана Раздробленного Хребта по поручению Мелизары из Мельницы Таррен.','Снег стал алым от крови огров, но мы не должны останавливаться, пока не втопчем дух и тело огров Раздробленного Хребта в грязь и снег.','Похоже, Луса такой же надоедливый, как и ты. Впрочем, неважно. Давай сюда набор. Мне нужно немного с ним поработать, чтобы знать, какие компоненты искать.\n\nТы ведь принес его?','Вернитесь к Мелизаре на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корона Воли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Муг\'тол и огры Раздробленного Хребта захватили руины Альтерака. Наказать их всерьез будет нелегко, если не проредить сначала ряды огров.$B$BА уж потом мы продолжим.$B$BЯсно? Отлично. Выполняй.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 извергов из клана Раздробленного Хребта по поручению Мелизары из Мельницы Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Снег стал алым от крови огров, но мы не должны останавливаться, пока не втопчем дух и тело огров Раздробленного Хребта в грязь и снег.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, Луса такой же надоедливый, как и ты. Впрочем, неважно. Давай сюда набор. Мне нужно немного с ним поработать, чтобы знать, какие компоненты искать.\n\nТы ведь принес его?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелизаре на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (519,'Корона Воли','Тарг, Навозер и Гломмус – лейтенанты Муг\'Тола. Они верны ему, хотя кто там разберет, что вынуждает огров быть верными.$B$BПринеси мне их головы, $n, и нам останется отрубить башку Муг\'Толу вместе с короной.','Убейте Тарга, Навозера и Гломмуса и принесите их головы Мелизаре из Мельницы Таррен.','...а я-то думала, что для начала огры зверски воняют.\n\nКогда ты принесешь мне голову Муг\'Тола, я прикажу отнести ее вместе с этими на пики Альтерака. Неплохой памятник тем, кто идет против воли Темной Госпожи.','Мне нужны их головы, а не оправдания.','Вернитесь к Мелизаре на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корона Воли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тарг, Навозер и Гломмус – лейтенанты Муг\'Тола. Они верны ему, хотя кто там разберет, что вынуждает огров быть верными.$B$BПринеси мне их головы, $n, и нам останется отрубить башку Муг\'Толу вместе с короной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Тарга, Навозера и Гломмуса и принесите их головы Мелизаре из Мельницы Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','...а я-то думала, что для начала огры зверски воняют.\n\nКогда ты принесешь мне голову Муг\'Тола, я прикажу отнести ее вместе с этими на пики Альтерака. Неплохой памятник тем, кто идет против воли Темной Госпожи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужны их головы, а не оправдания.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелизаре на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (520,'Корона Воли','Лейтенанты Муг\'Тола мертвы, и нам остается только убить его самого и забрать корону Воли. Нет сомнений, ему не захочется с ней расставаться. Скорее всего, он ждет тебя, учитывая... уменьшение числа его товарищей.$B$BОтыщи Муг\'Тола и принеси мне его голову вместе с короной. Положим конец сопротивлению Раздробленного Хребта.','Убейте Муг\'Тола и принесите его голову и корону Воли Мелизаре на мельницу Таррен.','Три головы у меня есть, а четвертой пока не видать. Это будет или голова Муг\'Тола, или твоя. Уж поверь мне на слово.','Вернитесь к Мелизаре на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корона Воли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лейтенанты Муг\'Тола мертвы, и нам остается только убить его самого и забрать корону Воли. Нет сомнений, ему не захочется с ней расставаться. Скорее всего, он ждет тебя, учитывая... уменьшение числа его товарищей.$B$BОтыщи Муг\'Тола и принеси мне его голову вместе с короной. Положим конец сопротивлению Раздробленного Хребта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Муг\'Тола и принесите его голову и корону Воли Мелизаре на мельницу Таррен.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Три головы у меня есть, а четвертой пока не видать. Это будет или голова Муг\'Тола, или твоя. Уж поверь мне на слово.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелизаре на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (521,'Корона Воли','Остается отнести корону Воли Шарлиндре в Подгород. Она уж передаст ее леди Сильване. Но даже не думай воспользоваться ей в личных целях, $n. Пусть тебе послужит уроком судьба Муг\'Тола.','Отнесите корону Воли Шарлиндре из Подгорода.','Да? О чем ты хочешь доложить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корона Воли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остается отнести корону Воли Шарлиндре в Подгород. Она уж передаст ее леди Сильване. Но даже не думай воспользоваться ей в личных целях, $n. Пусть тебе послужит уроком судьба Муг\'Тола.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите корону Воли Шарлиндре из Подгорода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? О чем ты хочешь доложить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (522,'Контракт убийцы','Это контракт на убийство мирового судьи Генри Малеба. Он был опечатан красным воском с характерным оттиском кольца.','Отнесите контракт убийцы мировому судье Малебу в Южнобережье.','<Малеб изучает контракт.>$B$BТеперь мне понятна подоплека последнего нападения на Южнобережье. Наверное, Синдикат хочет добраться до меня, как и до моего предшественника!','Я смотрю, ты тяжело дышишь! Есть, о чем доложить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контракт убийцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это контракт на убийство мирового судьи Генри Малеба. Он был опечатан красным воском с характерным оттиском кольца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите контракт убийцы мировому судье Малебу в Южнобережье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Малеб изучает контракт.>$B$BТеперь мне понятна подоплека последнего нападения на Южнобережье. Наверное, Синдикат хочет добраться до меня, как и до моего предшественника!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я смотрю, ты тяжело дышишь! Есть, о чем доложить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (523,'Смерть барона','Добытый тобой контракт был подписан бароном Вардусом, дворянином из бывшего королевства Альтерака, прославившегося холодным сердцем и необычайной жестокостью. Неудивительно, что за этим стоял барон.$B$BОтыщи его. Отыщи и сверши над ним суд. Должно быть, он прячется в одном из убежищ Синдиката – руинах Странбрада или долине на севере оттуда.','Принесите голову барона Вардуса мировому судье Малебу в Южнобережье.','Вернитесь к мировому судье Генри Малебу в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть барона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добытый тобой контракт был подписан бароном Вардусом, дворянином из бывшего королевства Альтерака, прославившегося холодным сердцем и необычайной жестокостью. Неудивительно, что за этим стоял барон.$B$BОтыщи его. Отыщи и сверши над ним суд. Должно быть, он прячется в одном из убежищ Синдиката – руинах Странбрада или долине на севере оттуда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову барона Вардуса мировому судье Малебу в Южнобережье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Генри Малебу в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (524,'Эликсир агонии','За соседней дверью стражи смерти держат нескольких заложников-фермеров. Верховный палач Дарталия подозревает, что среди них скрывается один из военных-стратегов. Очевидно, его нашли мертвым в Чумных землях. Дарталия всегда заботится обо мне и решила передать пленников мне в руки.$B$BПора устроить этим фермерам вечеринку. Ох, повеселимся!$B$BПоставь гниющий бочонок на ковер у них в комнате. Чумной напиток для всех!','Поставьте гниющий бочонок на ковер для плененных фермеров.','Вы ставите гниющий бочонок на пыльный ковер.','От ковра идет гнилостный запах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир агонии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За соседней дверью стражи смерти держат нескольких заложников-фермеров. Верховный палач Дарталия подозревает, что среди них скрывается один из военных-стратегов. Очевидно, его нашли мертвым в Чумных землях. Дарталия всегда заботится обо мне и решила передать пленников мне в руки.$B$BПора устроить этим фермерам вечеринку. Ох, повеселимся!$B$BПоставь гниющий бочонок на ковер у них в комнате. Чумной напиток для всех!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поставьте гниющий бочонок на ковер для плененных фермеров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы ставите гниющий бочонок на пыльный ковер.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','От ковра идет гнилостный запах.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (525,'Все больше тайн','Я расшифровал письмо, но не знаю, что с ним дальше делать. Вы нашли его у воров в предгорьях Альтерака? Очень странно...$B$BНадо доставить это письмо мировому судье Южнобережья. Хотя письмо и зашифровано, это ближайший город к горам Альтерака, и если назревает какая-то опасность, то они должны об этом узнать.','Доставьте расшифрованное письмо мировому судье Южнобережья Малебу.','<Малеб читает письмо.>$B$BЭто расшифровка письма, найденного вами в лагере Синдиката? Оно написано не вором, и даже не альтеракским аристократом.$B$BПохоже, у Синдиката есть связи с другими силами, и мне страшно подумать, что это за силы могут быть.','$N. Вы шли через предгорья и по горам? Какие вы принесли вести?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все больше тайн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я расшифровал письмо, но не знаю, что с ним дальше делать. Вы нашли его у воров в предгорьях Альтерака? Очень странно...$B$BНадо доставить это письмо мировому судье Южнобережья. Хотя письмо и зашифровано, это ближайший город к горам Альтерака, и если назревает какая-то опасность, то они должны об этом узнать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте расшифрованное письмо мировому судье Южнобережья Малебу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Малеб читает письмо.>$B$BЭто расшифровка письма, найденного вами в лагере Синдиката? Оно написано не вором, и даже не альтеракским аристократом.$B$BПохоже, у Синдиката есть связи с другими силами, и мне страшно подумать, что это за силы могут быть.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N. Вы шли через предгорья и по горам? Какие вы принесли вести?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (526,'Слитки светостали','Ты $Gнашел:нашла; только один слиток светостали – этого не хватит, чтобы выковать что-нибудь стоящее.$B$BВернись и поищи еще слитки. Думается, их растащили мурлоки, разграбившие корабль.','Найдите 5 слитков светостали и вернитесь к Глорину Стальному Лбу в Болотину.','А, ты $Gнашел:нашла; их! Теперь давай эту светосталь скуем в что-нибудь полезное?','Вы нашли нужное железо?','Вернитесь к Глорину Стальному Лбу в Гавань Менетилов, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слитки светостали',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gнашел:нашла; только один слиток светостали – этого не хватит, чтобы выковать что-нибудь стоящее.$B$BВернись и поищи еще слитки. Думается, их растащили мурлоки, разграбившие корабль.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 слитков светостали и вернитесь к Глорину Стальному Лбу в Болотину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, ты $Gнашел:нашла; их! Теперь давай эту светосталь скуем в что-нибудь полезное?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы нашли нужное железо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глорину Стальному Лбу в Гавань Менетилов, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (527,'Битва за Хилсбрад','Когда говоришь со мной, стой по стойке "смирно", |3-6($c).$b$bЯ нахожусь под прямым командованием Сильваны. Наша задача – сдерживать распространение чумы среди людей, покуда аптекари работают над составом новой чумы.$b$bПо нашим сведениям город Хилсбрад очень уязвим. Твое первое задание – прервать снабжение едой и прочим.$b$bОтправляйся на запад. Устрой налет на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца.','Убейте 6 хилсбрадских батраков, 6 хилсбрадских фермеров, фермеров Рея и Гетца и возвращайтесь к Дарталии которая ждет вас на мельнице Таррен.','Вольно, |3-6($C). Вижу, ты вернулся из боя. Мне доложили, что ты хорошо показал себя в Хилсбраде.','Повезло добыть ингредиенты? Надо сказать, нынче эти места просто кишат подонками из Альянса... По мне, они уже зашли слишком далеко...','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Хилсбрад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда говоришь со мной, стой по стойке "смирно", |3-6($c).$b$bЯ нахожусь под прямым командованием Сильваны. Наша задача – сдерживать распространение чумы среди людей, покуда аптекари работают над составом новой чумы.$b$bПо нашим сведениям город Хилсбрад очень уязвим. Твое первое задание – прервать снабжение едой и прочим.$b$bОтправляйся на запад. Устрой налет на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 хилсбрадских батраков, 6 хилсбрадских фермеров, фермеров Рея и Гетца и возвращайтесь к Дарталии которая ждет вас на мельнице Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вольно, |3-6($C). Вижу, ты вернулся из боя. Мне доложили, что ты хорошо показал себя в Хилсбраде.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Повезло добыть ингредиенты? Надо сказать, нынче эти места просто кишат подонками из Альянса... По мне, они уже зашли слишком далеко...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (528,'Битва за Хилсбрад','Убейте 15 хилсбрадских крестьян и вернитесь к Дарталии на мельницу Таррен.','Смерть все крепче сжимает костлявую руку на горле Хилсбрада. Битва идет хорошо.','У тебя есть заказы, $C. Перестань бездельничать здесь, на мельнице Таррен, когда есть работа в другом месте.','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Хилсбрад',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 хилсбрадских крестьян и вернитесь к Дарталии на мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смерть все крепче сжимает костлявую руку на горле Хилсбрада. Битва идет хорошо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть заказы, $C. Перестань бездельничать здесь, на мельнице Таррен, когда есть работа в другом месте.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (529,'Битва за Хилсбрад','Люди Хилсбрада оказывают нам неожиданное сопротивление. Кажется, проблема в кузнеце, снабжающем горожан оружием. Необходимо прервать цепь снабжения.$B$BУбей кузнеца Верринтана вместе с учениками и возвращайся с партией железа. Нам оно пригодится, когда мы одержим победу над Хилсбрадом и нападем на Южнобережье.','Убейте кузнеца Верринтана и 4 хилсбрадских учеников кузнеца.$B$BПринести партию железа Дарталии на мельницу Таррен.','Задание выполнено, |3-6($C). И, надо сказать, выполнено на славу.','Удалось ли тебе выполнить приказ, |3-6($C)? Мертв ли кузнец Веррингтан и его подмастерья? И где партия железа?','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Хилсбрад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Люди Хилсбрада оказывают нам неожиданное сопротивление. Кажется, проблема в кузнеце, снабжающем горожан оружием. Необходимо прервать цепь снабжения.$B$BУбей кузнеца Верринтана вместе с учениками и возвращайся с партией железа. Нам оно пригодится, когда мы одержим победу над Хилсбрадом и нападем на Южнобережье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте кузнеца Верринтана и 4 хилсбрадских учеников кузнеца.$B$BПринести партию железа Дарталии на мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Задание выполнено, |3-6($C). И, надо сказать, выполнено на славу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе выполнить приказ, |3-6($C)? Мертв ли кузнец Веррингтан и его подмастерья? И где партия железа?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (530,'Месть мужа','Когда-то Валдред был моим лучшим другом, а потом убил мою жену. Горевать я уже не способен, но до сих пор жажду мести. Если ты убьешь Валдреда и принесешь мне его проклятые руки, я тебя награжу.$B$BПо последним слухам, он был у Стены Седогрива в южном Серебряном бору. Небось, пытается сбежать в королевство Гилнеас.','Убейте Валдреда Морая.$B$BПринесите его руки Роли Андреану в Подгород.','А, хорошо. Этими руками была убита моя жена, Делия. С тех пор я думал только о мести, и вот ты стал моим оружием.\n\nВозьми кольцо, которое вернул мне ранее. Делия так давно умерла, что я не нуждаюсь в этой безделушке. Лучше я оставлю себе эти руки в память о предательстве друга.','Вернитесь к Роли Андреану в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть мужа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда-то Валдред был моим лучшим другом, а потом убил мою жену. Горевать я уже не способен, но до сих пор жажду мести. Если ты убьешь Валдреда и принесешь мне его проклятые руки, я тебя награжу.$B$BПо последним слухам, он был у Стены Седогрива в южном Серебряном бору. Небось, пытается сбежать в королевство Гилнеас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Валдреда Морая.$B$BПринесите его руки Роли Андреану в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, хорошо. Этими руками была убита моя жена, Делия. С тех пор я думал только о мести, и вот ты стал моим оружием.\n\nВозьми кольцо, которое вернул мне ранее. Делия так давно умерла, что я не нуждаюсь в этой безделушке. Лучше я оставлю себе эти руки в память о предательстве друга.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Роли Андреану в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (531,'Месть Вайрины','Ради всего святого! Не приноси в Приют такое... это негигиенично, неприлично, не... не... негигиенично!$b$BСкорее убери ее отсюда! Никому здесь не нужны твои страхолюдные трофеи!','Принесите голову Старины Черношкура Вайрине Быстрый Ветер в Приют странников.','Спасибо, что $gпомог:помогла; мне выполнить мой маленький план. Я много месяцев жаждала проучить этого надутого самовлюбленного мальчишку, а теперь нам это удалось! Вот, возьми, ты это $gзаслужил:заслужила;.','Молодец, $n! Мы его хорошенько проучили! Дай мне голову, я сама ей займусь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Вайрины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ради всего святого! Не приноси в Приют такое... это негигиенично, неприлично, не... не... негигиенично!$b$BСкорее убери ее отсюда! Никому здесь не нужны твои страхолюдные трофеи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Старины Черношкура Вайрине Быстрый Ветер в Приют странников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что $gпомог:помогла; мне выполнить мой маленький план. Я много месяцев жаждала проучить этого надутого самовлюбленного мальчишку, а теперь нам это удалось! Вот, возьми, ты это $gзаслужил:заслужила;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Молодец, $n! Мы его хорошенько проучили! Дай мне голову, я сама ей займусь.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (532,'Битва за Хилсбрад','В Хилсбраде царит паника. Думаю, он скоро падет. Но мы не должны ослаблять натиск, пока последние человеческие отродья не изжиты из этих холмов навеки.$B$BНевзирая на колоссальные потери, люди держатся вокруг своих вождей и не кладут оружия. Мы должны уничтожить их главу, мирового судью Бернсайда, и весь городской совет. Заодно уничтожь и их главный документ, Хилсбрадское официальное объявление. И раз уж на то пошло, укради и городскую книгу регистрации.','Убейте мирового судью Бернсайда, и 4 членов совета Хилсбрада. Уничтожьте Хилсбрадское официальное объявление. Украдите регистрационную книгу Хилсбрада. Возвращайтесь к Дарталии на мельницу Таррен.','Вести о твоих победах в Хилсбраде быстро разносятся. Отличная работа, |3-6($C).','Какие вести ты несешь?','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Хилсбрад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Хилсбраде царит паника. Думаю, он скоро падет. Но мы не должны ослаблять натиск, пока последние человеческие отродья не изжиты из этих холмов навеки.$B$BНевзирая на колоссальные потери, люди держатся вокруг своих вождей и не кладут оружия. Мы должны уничтожить их главу, мирового судью Бернсайда, и весь городской совет. Заодно уничтожь и их главный документ, Хилсбрадское официальное объявление. И раз уж на то пошло, укради и городскую книгу регистрации.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте мирового судью Бернсайда, и 4 членов совета Хилсбрада. Уничтожьте Хилсбрадское официальное объявление. Украдите регистрационную книгу Хилсбрада. Возвращайтесь к Дарталии на мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вести о твоих победах в Хилсбраде быстро разносятся. Отличная работа, |3-6($C).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие вести ты несешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (533,'Шпионская работа','Наконец-то до нас дошли сведения о местопребывании Гол\'дира. Люди постоянно меняли места его заключения, но мы смогли сузить область поиска до большого лагеря Синдиката на севере отсюда.$b$bСтупай туда, $n, и заполучи все доступные сведения.','Добудьте сведения о местонахождении Гол\'дира для Круска из Мельницы Таррен.','Наконец-то мы знаем, где держат Гол\'дира. В лагере неподалеку отсюда. Будем надеяться, что на сей раз они не успеют подготовиться как прошлый раз, когда нас застали в расплох.','Ну как, удалось что-нибудь узнать? Боюсь, надежды для Гол\'дира все меньше и меньше...','Вернитесь к Круску на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шпионская работа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то до нас дошли сведения о местопребывании Гол\'дира. Люди постоянно меняли места его заключения, но мы смогли сузить область поиска до большого лагеря Синдиката на севере отсюда.$b$bСтупай туда, $n, и заполучи все доступные сведения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сведения о местонахождении Гол\'дира для Круска из Мельницы Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то мы знаем, где держат Гол\'дира. В лагере неподалеку отсюда. Будем надеяться, что на сей раз они не успеют подготовиться как прошлый раз, когда нас застали в расплох.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось что-нибудь узнать? Боюсь, надежды для Гол\'дира все меньше и меньше...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Круску на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (534,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (535,'Валлик','Гр-рр... Раненый, умирающий, но не опускающий оружия.$b$bНе сомневаюсь, ты все равно убьешь меня, но если ты принесешь мне немного южнобережского портера – вы ведь такое тоже пьете? – я расскажу тебе то, что ты хочешь знать.','Принесите кружку южнобережского портера Валлику в лагерь Синдиката.','Принимая во внимание мою неминуемую смерть – думаю, могу с уверенностью сказать, что это самый вкусный напиток в моей жизни... Вот, возьми – когда я помру, мне это все равно не понадобится. \n\nНу, слушай!','Так что, ты принес мне чего-нибудь выпить или пришел просто покончить со мной?','Вернитесь к подручному Валлику на Возвышенность Соферы, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Валлик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гр-рр... Раненый, умирающий, но не опускающий оружия.$b$bНе сомневаюсь, ты все равно убьешь меня, но если ты принесешь мне немного южнобережского портера – вы ведь такое тоже пьете? – я расскажу тебе то, что ты хочешь знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите кружку южнобережского портера Валлику в лагерь Синдиката.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Принимая во внимание мою неминуемую смерть – думаю, могу с уверенностью сказать, что это самый вкусный напиток в моей жизни... Вот, возьми – когда я помру, мне это все равно не понадобится. \n\nНу, слушай!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так что, ты принес мне чего-нибудь выпить или пришел просто покончить со мной?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к подручному Валлику на Возвышенность Соферы, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (536,'На побережье','Меня перевели в Южнобережье из городской стражи Штормграда. Непонятно, как тут вообще люди живут... А как воняет со стороны пристани и днем и ночью!$b$bДа еще старый Редпат на мою голову... Он хочет, чтобы я занялся мурлоками. Ха!$b$bЯ едва могу заставить себя подойти к этим рыбам-переросткам на Западном побережье. Если ты разберешься с ними вместо меня, я буду очень признателен.','Убейте 10 волноловов из племени Порванного Плавника и 10 оракулов из племени Порванного Плавника по поручению лейтенанта Фаррена Оринеля из Южнобережья.','Надеюсь, этого хватит, чтобы убедить Крассена, что я – ха! – выполняю его приказы и избавляю Южнобережье от страшной и ужасной угрозы, жутких мурлоков! Нет ничего страшнее ярости рыбы-переростка!','Вернитесь к лейтенанту Фаррену Оринелю в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На побережье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня перевели в Южнобережье из городской стражи Штормграда. Непонятно, как тут вообще люди живут... А как воняет со стороны пристани и днем и ночью!$b$bДа еще старый Редпат на мою голову... Он хочет, чтобы я занялся мурлоками. Ха!$b$bЯ едва могу заставить себя подойти к этим рыбам-переросткам на Западном побережье. Если ты разберешься с ними вместо меня, я буду очень признателен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 волноловов из племени Порванного Плавника и 10 оракулов из племени Порванного Плавника по поручению лейтенанта Фаррена Оринеля из Южнобережья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, этого хватит, чтобы убедить Крассена, что я – ха! – выполняю его приказы и избавляю Южнобережье от страшной и ужасной угрозы, жутких мурлоков! Нет ничего страшнее ярости рыбы-переростка!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Фаррену Оринелю в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (537,'Темный совет','Это письмо от существа, называющего себя Нагазом, членом сообщества Недремлющего Аргуса. Не знаю, что это за Аргус, но если он в союзе с Синдикатом, то представляет собой угрозу.$B$BОтыщи Нагаза и упомянутых в письме темных магов Недремлющего Аргуса. Найди их и убей.$B$BИщи их в Высокогорье, на севере от Странбрада, где позиции Синдиката сильнее всего.$B$BЕсли повезет, ты найдешь там послов Недремлющего Аргуса.','Убейте 4 темных магов Недремлющего Аргуса.$B$BПринесите голову Нагаза мировому судье Южнобережья Малебу.','$GМолодец:Умница;, $N. Не хотелось бы, чтобы Недремлющий Аргус присоединился к Синдикату.$B$BХотя тебе и удалось убить их главаря в этих землях, ясно, что Нагаз был чьим-то слугой. Похоже, Недремлющий Аргус пустил корни по всему нашему континенту.$B$BИли по всему миру.','Удалось ли найти послов Недремлющего Аргуса?','Вернитесь к мировому судье Генри Малебу в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темный совет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это письмо от существа, называющего себя Нагазом, членом сообщества Недремлющего Аргуса. Не знаю, что это за Аргус, но если он в союзе с Синдикатом, то представляет собой угрозу.$B$BОтыщи Нагаза и упомянутых в письме темных магов Недремлющего Аргуса. Найди их и убей.$B$BИщи их в Высокогорье, на севере от Странбрада, где позиции Синдиката сильнее всего.$B$BЕсли повезет, ты найдешь там послов Недремлющего Аргуса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 темных магов Недремлющего Аргуса.$B$BПринесите голову Нагаза мировому судье Южнобережья Малебу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N. Не хотелось бы, чтобы Недремлющий Аргус присоединился к Синдикату.$B$BХотя тебе и удалось убить их главаря в этих землях, ясно, что Нагаз был чьим-то слугой. Похоже, Недремлющий Аргус пустил корни по всему нашему континенту.$B$BИли по всему миру.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли найти послов Недремлющего Аргуса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Генри Малебу в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (538,'Южнобережье','Доброго дня вам, $n. Если вы не против долгого путешествия, то у меня для вас найдется задание, которое поможет пополнить библиотеку Штормграда.$B$BВместе со старым королевством Альтерака во время войны погибла и огромнейшая библиотека. Жаль, что город разрушен, но вдвойне жаль, что пропал бесценный кладезь знаний! Мы должны восстановить все, что можем.$B$BЮжнобережье – ближайший к руинам Альтерака город. Отправляйтесь туда и поговорите с Хранителем мудрости Диббсом. Он направит вас к руинам, может быть, там вы сумеете найти книги...','Поговорите с Хранителем мудрости Диббсом в Южнобережье.','Да, конечно, я помню Милтона. Такой типичный книжный червь, будь он здоров...$B$BИ он совершенно прав. Руины Альтерака по-прежнему полны драгоценных документов, которые находятся под угрозой исчезновения!$B$BТеперь-то в Альтераке обитают огры, а их совершенно не волнуют памятники культуры...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Южнобережье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доброго дня вам, $n. Если вы не против долгого путешествия, то у меня для вас найдется задание, которое поможет пополнить библиотеку Штормграда.$B$BВместе со старым королевством Альтерака во время войны погибла и огромнейшая библиотека. Жаль, что город разрушен, но вдвойне жаль, что пропал бесценный кладезь знаний! Мы должны восстановить все, что можем.$B$BЮжнобережье – ближайший к руинам Альтерака город. Отправляйтесь туда и поговорите с Хранителем мудрости Диббсом. Он направит вас к руинам, может быть, там вы сумеете найти книги...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хранителем мудрости Диббсом в Южнобережье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, конечно, я помню Милтона. Такой типичный книжный червь, будь он здоров...$B$BИ он совершенно прав. Руины Альтерака по-прежнему полны драгоценных документов, которые находятся под угрозой исчезновения!$B$BТеперь-то в Альтераке обитают огры, а их совершенно не волнуют памятники культуры...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (539,'Битва за Хилсбрад','Согласно регистрационной книге Хилсбрада, Лазуритовый рудник находится в руках Альянса. Более того, львиную долю руды, идущей на вооружение Альянса, добывают именно там.$B$BХотя мы нанесли решительный удар по городу Хилсбраду, Альянс изо всех сил защищает свой рудник.$B$BРудник расположен на юге от Хилсбрада. Ступай туда и убей штейгера, человека по имени Бондс. Убей и его горняков. Альянс надолго запомнит этот урок.','Убейте штейгера Бондса и 10 хилсбрадских шахтеров и доложите о проделанной работе Дарталии, которая ждет вас на мельнице Таррен.','Темная Госпожа будет рада услышать, что у нее появился новый рудник, который поможет вооружить ее бойцов.','Тебе был дан прямой приказ атаковать Лазурную шахту. Надеюсь у тебя веская причина, по которой ты слоняешься по Мельнице Таррен, или я обезглавлю тебя за измену.','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Хилсбрад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Согласно регистрационной книге Хилсбрада, Лазуритовый рудник находится в руках Альянса. Более того, львиную долю руды, идущей на вооружение Альянса, добывают именно там.$B$BХотя мы нанесли решительный удар по городу Хилсбраду, Альянс изо всех сил защищает свой рудник.$B$BРудник расположен на юге от Хилсбрада. Ступай туда и убей штейгера, человека по имени Бондс. Убей и его горняков. Альянс надолго запомнит этот урок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте штейгера Бондса и 10 хилсбрадских шахтеров и доложите о проделанной работе Дарталии, которая ждет вас на мельнице Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Темная Госпожа будет рада услышать, что у нее появился новый рудник, который поможет вооружить ее бойцов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе был дан прямой приказ атаковать Лазурную шахту. Надеюсь у тебя веская причина, по которой ты слоняешься по Мельнице Таррен, или я обезглавлю тебя за измену.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (540,'Сохранение знаний','Мерзкие огры поселились в руинах Альтерака, и мне дурно при мысли, что они делают с драгоценными книгами из библиотеки. Спаси все, что можно!$B$BСтупай в руины Альтерака и поищи там фолианты, украденные ограми. Собери все, что сможешь и принеси мне. Больше всего меня интересует одна книга – "Рука Гри\'лека". В ней содержится древняя мудрость троллей, о которой я жажду узнать, а последняя копия этой книги находилась именно в руинах Альтерака.','Найдите 5 фолиантов и потертую кожаную книгу, называемую "Рука Гри\'лека", и принесите их хранителю мудрости Диббсу в Южнобережье.','Вернитесь к хранителю мудрости Диббсу в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сохранение знаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мерзкие огры поселились в руинах Альтерака, и мне дурно при мысли, что они делают с драгоценными книгами из библиотеки. Спаси все, что можно!$B$BСтупай в руины Альтерака и поищи там фолианты, украденные ограми. Собери все, что сможешь и принеси мне. Больше всего меня интересует одна книга – "Рука Гри\'лека". В ней содержится древняя мудрость троллей, о которой я жажду узнать, а последняя копия этой книги находилась именно в руинах Альтерака.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 фолиантов и потертую кожаную книгу, называемую "Рука Гри\'лека", и принесите их хранителю мудрости Диббсу в Южнобережье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю мудрости Диббсу в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (541,'Битва за Хилсбрад','Дворфы пришли на помощь людям? Проклятые мелкие твари!$B$BЧто ж, испытаем силу так называемого Альянса. Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев. Мы отлично знаем, где скрывается их цитадель в этих краях.$B$BОни построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина. Это местечко зовется Дун Гарок. Последняя цель этой битвы – осадить Дун Гарок, |3-6($c). Глава дворфов, капитан Железный Холм, должен умереть.','Отправляйтесь в Дун Гарок и убейте 8 горных пехотинцев, 4 стрелков, 2 жрецов и капитана Железный Холм. После возвращайтесь к Дарталии на мельницу Таррен.','Твои подвиги на поле битвы достойны высочайшей хвалы.','Дун Гарок тебе не по зубам, а? А я-то думала, ты доказал свою доблесть в Хилсбраде.$B$BЕсли ты не в силах выполнить это задание, я найду другого, кто достигнет цели. Что до тебя, не сомневаюсь, Темной Госпоже не помешают новые гробокопатели в Тирисфальских лесах.','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Хилсбрад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дворфы пришли на помощь людям? Проклятые мелкие твари!$B$BЧто ж, испытаем силу так называемого Альянса. Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев. Мы отлично знаем, где скрывается их цитадель в этих краях.$B$BОни построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина. Это местечко зовется Дун Гарок. Последняя цель этой битвы – осадить Дун Гарок, |3-6($c). Глава дворфов, капитан Железный Холм, должен умереть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Дун Гарок и убейте 8 горных пехотинцев, 4 стрелков, 2 жрецов и капитана Железный Холм. После возвращайтесь к Дарталии на мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои подвиги на поле битвы достойны высочайшей хвалы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дун Гарок тебе не по зубам, а? А я-то думала, ты доказал свою доблесть в Хилсбраде.$B$BЕсли ты не в силах выполнить это задание, я найду другого, кто достигнет цели. Что до тебя, не сомневаюсь, Темной Госпоже не помешают новые гробокопатели в Тирисфальских лесах.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (542,'Возвращение к Милтону','Мне понадобится время на изучение "Руки Гри\'лека", хотя я не сомневаюсь, что Милтону не терпится вернуть книги в коллекцию Штормграда.$B$bВот книги, добытые тобой в руинах Альтерака. Они уже упакованы и каталогизированы. Отнеси их Милтону Снопу в Штормград, он несомненно будет тебе признателен.','Отнесите фолианты Альтерака Милтону Снопу в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Милтону',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне понадобится время на изучение "Руки Гри\'лека", хотя я не сомневаюсь, что Милтону не терпится вернуть книги в коллекцию Штормграда.$B$bВот книги, добытые тобой в руинах Альтерака. Они уже упакованы и каталогизированы. Отнеси их Милтону Снопу в Штормград, он несомненно будет тебе признателен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите фолианты Альтерака Милтону Снопу в Штормград.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (542,'My oh my! Look at these! I can\'t believe they survived the ruination of Alterac. And all those ogres too!$B$BThank you, $n. Thank you so much! You have helped preserve human knowledge, and you add to the grandeur of the Royal Library of Stormwind.','$n, you\'ve returned! How did your foray into Alterac go? Did you bring anything back with you?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','My oh my! Look at these! I can\'t believe they survived the ruination of Alterac. And all those ogres too!$B$BThank you, $n. Thank you so much! You have helped preserve human knowledge, and you add to the grandeur of the Royal Library of Stormwind.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$n, you\'ve returned! How did your foray into Alterac go? Did you bring anything back with you?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (543,'Тиара Перенольда','Тиара Перенольда – старая семейная реликвия одного из древнейших семейств Альтерака, входившего в правящие круги до падения королевства. Говорят, что ее изготовили мастера Стальгорна, украсив лучшими изумрудами.$B$BКогда Альтерак пал, тиара была утеряна, хотя поговаривали, что огрский маг Грел\'борг Скряга нашел ее и теперь пытается разыскать на руинах Альтерака другие сокровища.$B$BМы надеемся, что вы отыщете тиару.','Найдите тиару Перенольда.','Вернитесь к графу Ремингтону Риджвеллу в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тиара Перенольда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тиара Перенольда – старая семейная реликвия одного из древнейших семейств Альтерака, входившего в правящие круги до падения королевства. Говорят, что ее изготовили мастера Стальгорна, украсив лучшими изумрудами.$B$BКогда Альтерак пал, тиара была утеряна, хотя поговаривали, что огрский маг Грел\'борг Скряга нашел ее и теперь пытается разыскать на руинах Альтерака другие сокровища.$B$BМы надеемся, что вы отыщете тиару.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите тиару Перенольда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к графу Ремингтону Риджвеллу в крепость Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (544,'Взлом тюрьмы','Я прибыл в Мельницу Таррен с исследовательскими целями, а пришлось разрешать кризис. Видишь ли, четверо Отрекшихся несколько месяцев назад бежали из Подгорода. Они предали своих братьев, но что еще хуже... они украли кое-что у Темной Госпожи.$B$BЭти воры вломились в надежное хранилище и похитили четыре артефакта, необходимых нашим аптекарям для исследований. Сильвана жаждет вернуть эти артефакты.$B$BВоры бежали из Подгорода в Даларан, и волшебники спрятали их в Лордамерских выселках.','Найдите предателей и отберите у них артефакты, а потом возвращайтесь к волхву Сиянью Бездны в Мельницу Таррен.','Удалось ли найти воров? И что куда важнее, вернуть похищенное?','Вернитесь к волхву Вурдену Сиянью Бездны на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взлом тюрьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прибыл в Мельницу Таррен с исследовательскими целями, а пришлось разрешать кризис. Видишь ли, четверо Отрекшихся несколько месяцев назад бежали из Подгорода. Они предали своих братьев, но что еще хуже... они украли кое-что у Темной Госпожи.$B$BЭти воры вломились в надежное хранилище и похитили четыре артефакта, необходимых нашим аптекарям для исследований. Сильвана жаждет вернуть эти артефакты.$B$BВоры бежали из Подгорода в Даларан, и волшебники спрятали их в Лордамерских выселках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите предателей и отберите у них артефакты, а потом возвращайтесь к волхву Сиянью Бездны в Мельницу Таррен.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли найти воров? И что куда важнее, вернуть похищенное?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волхву Вурдену Сиянью Бездны на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (545,'Даларанские патрули','Волшебники Даларана создали вокруг сердца своего города огромный магический купол. Некоторые говорят, что он призван защитить город от опасностей, которыми полнятся наши дни, другие же уверяют, будто волшебники захотели работать и строить планы в тишине и покое.$b$bМне лично наплевать, зачем соорудили этот купол. Меня интересуют развалины на окраинах города, где могут быть спрятаны ценные магические предметы.$B$bК сожалению, все окрестности патрулируют волшебники и порабощенные ими элементали.$b$bИтак, напади на них и возвращайся, когда существенно сократишь их число.','Убейте 6 даларанских призывателей и 12 порабощенных элементалей. Затем возвращайтесь к волхву Сиянью Бездны на мельницу Таррен.','Вернитесь к волхву Вурдену Сиянью Бездны на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Даларанские патрули',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волшебники Даларана создали вокруг сердца своего города огромный магический купол. Некоторые говорят, что он призван защитить город от опасностей, которыми полнятся наши дни, другие же уверяют, будто волшебники захотели работать и строить планы в тишине и покое.$b$bМне лично наплевать, зачем соорудили этот купол. Меня интересуют развалины на окраинах города, где могут быть спрятаны ценные магические предметы.$B$bК сожалению, все окрестности патрулируют волшебники и порабощенные ими элементали.$b$bИтак, напади на них и возвращайся, когда существенно сократишь их число.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 даларанских призывателей и 12 порабощенных элементалей. Затем возвращайтесь к волхву Сиянью Бездны на мельницу Таррен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волхву Вурдену Сиянью Бездны на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (546,'Сувениры смерти','Я слышал, что Дарталия призвала тебя в строй, чтобы выступить против людей Хилсбрада. Как я завидую...$B$BПока ты там развлекаешься – убиваешь людей, грабишь города, запугиваешь невинных – я торчу здесь, на страже мельницы Таррен.$B$BМожет, ты смилостивишься над старым стражем смерти? Видишь, я собираю коллекцию человеческих черепов, а тебе предстоит убить немало смертных. Набери в ходе битвы 30 черепов, принеси мне, и я тебе хорошо заплачу.','Страж смерти Самс из Мельницы Таррен попросил принести 30 человеческих черепов Хилсбрада.','Вернитесь к стражу смерти Самсу на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сувениры смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, что Дарталия призвала тебя в строй, чтобы выступить против людей Хилсбрада. Как я завидую...$B$BПока ты там развлекаешься – убиваешь людей, грабишь города, запугиваешь невинных – я торчу здесь, на страже мельницы Таррен.$B$BМожет, ты смилостивишься над старым стражем смерти? Видишь, я собираю коллекцию человеческих черепов, а тебе предстоит убить немало смертных. Набери в ходе битвы 30 черепов, принеси мне, и я тебе хорошо заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Страж смерти Самс из Мельницы Таррен попросил принести 30 человеческих черепов Хилсбрада.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Самсу на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (547,'Меч Гумберта','Верховный палач Дарталия послала меня наблюдать за Дун Гароком издалека. Я разбил лагерь подальше от дворфов. Но пришло утро, мне нужно было вскипятить воду, и я пошел за дровами.$b$bВернувшись, я обнаружил, что мои вещи пропали.$B$BОчевидно, ко мне заглянули дворфийские разведчики из Дун Гарока и украли их. Мне нужен мой меч! Если ты сможешь вернуть его, я буду очень признателен. Там так много дворфов... будет нелегко понять, кто же из них вор.','Найдите меч стража смерти Гумберта в Дун Гароке и верните его владельцу на мельнице Таррен.','Ты нашел его!\n\nАх, как приятно чувствовать в руке знакомую рукоять. Премного благодарен!','Вернитесь к стражу смерти Гумберту на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меч Гумберта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный палач Дарталия послала меня наблюдать за Дун Гароком издалека. Я разбил лагерь подальше от дворфов. Но пришло утро, мне нужно было вскипятить воду, и я пошел за дровами.$b$bВернувшись, я обнаружил, что мои вещи пропали.$B$BОчевидно, ко мне заглянули дворфийские разведчики из Дун Гарока и украли их. Мне нужен мой меч! Если ты сможешь вернуть его, я буду очень признателен. Там так много дворфов... будет нелегко понять, кто же из них вор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите меч стража смерти Гумберта в Дун Гароке и верните его владельцу на мельнице Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты нашел его!\n\nАх, как приятно чувствовать в руке знакомую рукоять. Премного благодарен!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Гумберту на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (548,'<NYI> <TXT> Подвеска Кровавого камня','Начало заданий линии Подвески Кровавого Камня...<NYI>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> Подвеска Кровавого камня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Начало заданий линии Подвески Кровавого Камня...<NYI>',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (549,'РАЗЫСКИВАЮТСЯ: сторонники Синдиката','По приказу леди Сильваны все члены организации, именуемой Синдикат, приговариваются к смертной казни. Всех пленных казнят. В настоящий момент организация собирает силы в руинах крепости Дарнхольд на юго-востоке от мельницы Таррен.$B$BВсем, предоставившим доказательства своих подвигов верховному палачу Дарталии, будет дарована щедрая награда.','Убейте 10 разбойников и 10 сторожей Синдиката и возвращайтесь за наградой к верховному палачу Дарталии в Мельницу Таррен.','Великолепно, |3-6($C). Такими темпами мы мигом очистим эти земли от синдикатской швали.','Что же заставило |3-3($C) покинуть поле битвы и прийти в Подгород?','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РАЗЫСКИВАЮТСЯ: сторонники Синдиката',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По приказу леди Сильваны все члены организации, именуемой Синдикат, приговариваются к смертной казни. Всех пленных казнят. В настоящий момент организация собирает силы в руинах крепости Дарнхольд на юго-востоке от мельницы Таррен.$B$BВсем, предоставившим доказательства своих подвигов верховному палачу Дарталии, будет дарована щедрая награда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 разбойников и 10 сторожей Синдиката и возвращайтесь за наградой к верховному палачу Дарталии в Мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, |3-6($C). Такими темпами мы мигом очистим эти земли от синдикатской швали.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что же заставило |3-3($C) покинуть поле битвы и прийти в Подгород?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (550,'Битва за Хилсбрад','Поскольку ты $gпроявил:проявила; немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование.$B$BОтнеси мое письмо Брагору Кровопалу в Подгород. Можешь гордиться собой, |3-6($c).','Отнесите запечатанное рекомендательное письмо Дарталии Брагору Кровопалу в Подгород.','Так это ты знаменитый |3-6($C), нанесший сокрушительный удар по силам Альянса в Предгорьях Хилсбрада? Вести о твоих славных подвигах дошли до Подгорода.\n\nЕсли ты и впредь будешь проявлять подобный героизм, то тебя ожидает великое будущее в рядах бойцов Темной Госпожи.\n\nХотя наша главная проблема – наступление с севера Плети Короля-лича, человеческий вопрос тоже не решен и мешает строить планы битвы. Однако ты сумел доказать, что люди могут пасть. И они падут.','Что же заставило |3-3($C) покинуть поле битвы и прийти в Подгород?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Хилсбрад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поскольку ты $gпроявил:проявила; немалое мужество и стойкость в битве за Хилсбрад, я написала это рекомендательное письмо, описывающее твой героизм. Пусть его прочитает высшее командование.$B$BОтнеси мое письмо Брагору Кровопалу в Подгород. Можешь гордиться собой, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанное рекомендательное письмо Дарталии Брагору Кровопалу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так это ты знаменитый |3-6($C), нанесший сокрушительный удар по силам Альянса в Предгорьях Хилсбрада? Вести о твоих славных подвигах дошли до Подгорода.\n\nЕсли ты и впредь будешь проявлять подобный героизм, то тебя ожидает великое будущее в рядах бойцов Темной Госпожи.\n\nХотя наша главная проблема – наступление с севера Плети Короля-лича, человеческий вопрос тоже не решен и мешает строить планы битвы. Однако ты сумел доказать, что люди могут пасть. И они падут.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что же заставило |3-3($C) покинуть поле битвы и прийти в Подгород?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (551,'Заколдованный пергамент','На этот пергамент наложено заклинание, из-за чего надписи на нем невозможно расшифровать. Вы можете разобрать только одно слово вверху страницы: $b$b$bНагаз$b$b','Отнесите заколдованный пергамент Хранителю мудрости Диббсу в Южнобережье, что в Предгорьях Хилсбрада.','Опять зашифрованные записки?$B$BХотел бы я уметь разгадывать шифры, чтобы разобрать все странные фрагменты записей, что доходят к нам из Альтерака. Но боюсь, мне не хватает знаний.','Ого... Ты хочешь что-то мне показать? Надеюсь, какое-нибудь легендарное сокровище, найденное высоко в горах?..') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заколдованный пергамент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этот пергамент наложено заклинание, из-за чего надписи на нем невозможно расшифровать. Вы можете разобрать только одно слово вверху страницы: $b$b$bНагаз$b$b',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите заколдованный пергамент Хранителю мудрости Диббсу в Южнобережье, что в Предгорьях Хилсбрада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Опять зашифрованные записки?$B$BХотел бы я уметь разгадывать шифры, чтобы разобрать все странные фрагменты записей, что доходят к нам из Альтерака. Но боюсь, мне не хватает знаний.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ого... Ты хочешь что-то мне показать? Надеюсь, какое-нибудь легендарное сокровище, найденное высоко в горах?..',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (552,'Месть Гелькулара','Мастер Гелькулар почти превратился в Короля Мертвых, когда его ритуальное логово в холмах обнаружила разъяренная толпа людей и зверски убила его. Хуже того, они похоронили моего учителя на кладбище Южнобережья.$B$BНемыслимое неуважение к великому волшебнику. Я его ученик, и хочу отомстить ненавистному городу.$B$BПервым делом нам понадобится жезл Гелькулара. Его ритуальное логово захватили йети. Жезл несомненно находится у одного из них.','Отберите у йети жезл Гелькулара и отнесите его новобранцу Тайлванду на мельницу Таррен.','Удалось ли тебе вернуть жезл Гелькулара? Там так много йети, что найти его будет нелегко. И все же без него не обойтись.','Вернитесь к новобранцу Тайлванду на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Гелькулара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мастер Гелькулар почти превратился в Короля Мертвых, когда его ритуальное логово в холмах обнаружила разъяренная толпа людей и зверски убила его. Хуже того, они похоронили моего учителя на кладбище Южнобережья.$B$BНемыслимое неуважение к великому волшебнику. Я его ученик, и хочу отомстить ненавистному городу.$B$BПервым делом нам понадобится жезл Гелькулара. Его ритуальное логово захватили йети. Жезл несомненно находится у одного из них.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите у йети жезл Гелькулара и отнесите его новобранцу Тайлванду на мельницу Таррен.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе вернуть жезл Гелькулара? Там так много йети, что найти его будет нелегко. И все же без него не обойтись.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к новобранцу Тайлванду на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (553,'Месть Гелькулара','Вот, возьми Гелькуларов жезл. Он тебе понадобится.$B$BГелькулар создал для своего заклятья 3 церемониальных погребальных костра. Пламя Азеля и пламя Вераза находятся в Пещерах предгорий. Пламя Узеля находится в пещере выше по склону, в северной части гор.$B$BГелькуларов жезл необходимо зарядить в каждом из этих костров. Завершив ритуал, вонзи жезл в гробницу Гелькулара в Южнобережье, надежно охраняемом человеческом городе на юге. Мы отомстим!','Зарядите жезл Гелькулара силой пламени Азеля, пламени Вераза и пламени Узеля.$B$BВонзите заряженный жезл в гробницу Гелькулара в Южнобережье.','Из-под земли доносится глухой грохот.','От гробницы Гелькулара исходит духовная энергия.','Разыщите могилу Гелькулара на Кладбище Южнобережья, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Гелькулара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, возьми Гелькуларов жезл. Он тебе понадобится.$B$BГелькулар создал для своего заклятья 3 церемониальных погребальных костра. Пламя Азеля и пламя Вераза находятся в Пещерах предгорий. Пламя Узеля находится в пещере выше по склону, в северной части гор.$B$BГелькуларов жезл необходимо зарядить в каждом из этих костров. Завершив ритуал, вонзи жезл в гробницу Гелькулара в Южнобережье, надежно охраняемом человеческом городе на юге. Мы отомстим!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зарядите жезл Гелькулара силой пламени Азеля, пламени Вераза и пламени Узеля.$B$BВонзите заряженный жезл в гробницу Гелькулара в Южнобережье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Из-под земли доносится глухой грохот.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','От гробницы Гелькулара исходит духовная энергия.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите могилу Гелькулара на Кладбище Южнобережья, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (554,'Расшифровщик Грозовая Вершина','Геолог Грозовая Вершина – мастер дешифрования и декодирования. Если ты отнесешь найденный пергамент ему, то при удачном стечении обстоятельств он сможет его прочитать. В настоящий момент Грозовая Вершина работает в штаб-квартире Геологов в Стальгорне.$B$BЕсли увидишь его, сообщи о нашем разговоре – в последнее время я много работы на него свалил.','Отнесите заколдованный пергамент геологу Грозовой Вершине в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расшифровщик Грозовая Вершина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Геолог Грозовая Вершина – мастер дешифрования и декодирования. Если ты отнесешь найденный пергамент ему, то при удачном стечении обстоятельств он сможет его прочитать. В настоящий момент Грозовая Вершина работает в штаб-квартире Геологов в Стальгорне.$B$BЕсли увидишь его, сообщи о нашем разговоре – в последнее время я много работы на него свалил.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите заколдованный пергамент геологу Грозовой Вершине в Стальгорн.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (555,'Нежный черепаховый суп','Ты скоро поймешь, что в Южнобережье готовят лучше, чем во всех землях к северу от Штормграда!$B$BСкажем, возьмем мой секретный рецепт черепахового супа. Иногда ко мне захаживают из самого Темнолесья, чтобы насладиться миской-другой. Правда, в последнее время мне не хватает ингредиентов. Я бы сам пошел к озеру Лордамер у Даларана и поохотился на тамошних хрустогрызов, но это слишком опасно. Если ты принесешь мне черепашьего мяса, я мигом сварю супчик.','Принесите 10 кусков черепашьего мяса шеф-повару Джессену в Южнобережье.','Все будут в восторге – здесь снова подают нежный черепаховый суп шеф-повара Джессена!','Вернитесь к шеф-повару Джессену в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нежный черепаховый суп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты скоро поймешь, что в Южнобережье готовят лучше, чем во всех землях к северу от Штормграда!$B$BСкажем, возьмем мой секретный рецепт черепахового супа. Иногда ко мне захаживают из самого Темнолесья, чтобы насладиться миской-другой. Правда, в последнее время мне не хватает ингредиентов. Я бы сам пошел к озеру Лордамер у Даларана и поохотился на тамошних хрустогрызов, но это слишком опасно. Если ты принесешь мне черепашьего мяса, я мигом сварю супчик.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 кусков черепашьего мяса шеф-повару Джессену в Южнобережье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все будут в восторге – здесь снова подают нежный черепаховый суп шеф-повара Джессена!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шеф-повару Джессену в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (556,'Каменные талисманы','Волшебники Даларана славятся своей связью с элементалями, могущественными созданиями из других измерений, которыми они управляют при помощи магических талисманов. Волхв Сиянье Бездны хотел бы изучить эти талисманы.$B$BСтупай на земли даларанских волшебников на западе от Хилсбрада и собери несколько талисманов.$B$BТакие талисманы носят многие жители Даларана, но я советую поискать их в выселках. Это гораздо безопаснее.','Отнесите 10 истертых каменных талисманов хранителю Бел\'варилу из Мельницы Таррен.','Вернитесь к хранителю Бел\'варилу на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменные талисманы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волшебники Даларана славятся своей связью с элементалями, могущественными созданиями из других измерений, которыми они управляют при помощи магических талисманов. Волхв Сиянье Бездны хотел бы изучить эти талисманы.$B$BСтупай на земли даларанских волшебников на западе от Хилсбрада и собери несколько талисманов.$B$BТакие талисманы носят многие жители Даларана, но я советую поискать их в выселках. Это гораздо безопаснее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 10 истертых каменных талисманов хранителю Бел\'варилу из Мельницы Таррен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Бел\'варилу на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (557,'Сковывающие браслеты','Пока что колдун изучает каменные талисманы, но вскоре ему понадобится и другая часть – браслеты, связующие Стихии. Элементали носят их на запястье, что заставляет их выполнять волю мага.$B$BУбей побольше духов в руинах Даларана и собери с них браслеты Земли, и колдун будет доволен.','Принесите 4 браслета Земли хранителю Бел\'варилу из Мельницы Таррен.','Вернитесь к хранителю Бел\'варилу на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сковывающие браслеты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока что колдун изучает каменные талисманы, но вскоре ему понадобится и другая часть – браслеты, связующие Стихии. Элементали носят их на запястье, что заставляет их выполнять волю мага.$B$BУбей побольше духов в руинах Даларана и собери с них браслеты Земли, и колдун будет доволен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 браслета Земли хранителю Бел\'варилу из Мельницы Таррен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Бел\'варилу на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (558,'Автограф Джайны','Говорят, что леди Джайна Праудмур из Терамора – одна из величайших героинь Альянса. Когда я вырасту, я тоже хочу стать героем Альянса!$b$bТы $gзнаком:знакома; с Джайной? Ты можешь взять у нее автограф для меня? Пожалуйста! Я не знаю, как ее попросить, у нее нет времени для таких, как я... другое дело ты! Ты – $gтакой же искатель:такая же искательница; приключений, как и она! Готов поспорить, что тебе получить у нее автограф – раз плюнуть!$b$bПожалуйста!','Отправляйтесь в Терамор и постарайтесь получить автограф леди Джайны Праудмур для своего подопечного.','Когда-нибудь, я хочу быть героем - как Джайна... Ну, мальчик, который герой.','Вернитесь к своему подопечному ребенку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Автограф Джайны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что леди Джайна Праудмур из Терамора – одна из величайших героинь Альянса. Когда я вырасту, я тоже хочу стать героем Альянса!$b$bТы $gзнаком:знакома; с Джайной? Ты можешь взять у нее автограф для меня? Пожалуйста! Я не знаю, как ее попросить, у нее нет времени для таких, как я... другое дело ты! Ты – $gтакой же искатель:такая же искательница; приключений, как и она! Готов поспорить, что тебе получить у нее автограф – раз плюнуть!$b$bПожалуйста!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Терамор и постарайтесь получить автограф леди Джайны Праудмур для своего подопечного.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда-нибудь, я хочу быть героем - как Джайна... Ну, мальчик, который герой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному ребенку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (559,'Доказательство Фаррена','Ты не поверишь, Редпата не устроили все убитые нами мурлоки – не скромничай, ты тоже $gприложил:приложила; к этому руку. Теперь он хочет от меня доказательств их смерти. Чтобы я отрубил холодные склизкие мурлочьи головы и принес пред его очи!','Соберите 10 голов мурлоков на Западном побережье по просьбе лейтенанта Фаррена Оринеля из Южнобережья.','Вернитесь к лейтенанту Фаррену Оринелю в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доказательство Фаррена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не поверишь, Редпата не устроили все убитые нами мурлоки – не скромничай, ты тоже $gприложил:приложила; к этому руку. Теперь он хочет от меня доказательств их смерти. Чтобы я отрубил холодные склизкие мурлочьи головы и принес пред его очи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 голов мурлоков на Западном побережье по просьбе лейтенанта Фаррена Оринеля из Южнобережья.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Фаррену Оринелю в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (560,'Доказательство Фаррена','Знаешь, мне даже прикасаться к этим головам не хочется... Раз уж они у тебя, отнеси их Редпату от моего имени, а?','Отнесите мешок с головами мурлоков маршалу Редпату в Южнобережье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доказательство Фаррена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, мне даже прикасаться к этим головам не хочется... Раз уж они у тебя, отнеси их Редпату от моего имени, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите мешок с головами мурлоков маршалу Редпату в Южнобережье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (561,'Доказательство Фаррена','Пожалуйста, сообщи лейтенанту Оринелю, что я хотел бы, чтобы он занялся нагами, заселившими Восточное побережье. Когда он добьется результатов, пусть лично доложит о них мне.','Поговорите с лейтенантом Фарреном Оринелем из Южнобережья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доказательство Фаррена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуйста, сообщи лейтенанту Оринелю, что я хотел бы, чтобы он занялся нагами, заселившими Восточное побережье. Когда он добьется результатов, пусть лично доложит о них мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с лейтенантом Фарреном Оринелем из Южнобережья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (562,'Эй, Штормград!','Мой бывший наставник из городской стражи Штормграда послал мне сообщение, что верховное командование Альянса обеспокоено появлением наг. По слухам, тот, кто хорошо проявит себя в этой области, получит повышение – или, по крайней мере, новое назначение.$B$BЕсть одна проблема... я не могу справиться с нагами. Разумеется, прекратить пьяную драку или скрутить воинственного вора я могу, но наги мне не по зубам. Помоги мне, $n!','Убейте 10 береговых охотников и 10 сирен из клана Пронзающего Гребня по просьбе лейтенанта Фаррена Оринеля из Южнобережья.','Я уже письмо написал майору Самуэльсону в Штормград. Теперь мне нужен результат.','Вернитесь к лейтенанту Фаррену Оринелю в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эй, Штормград!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой бывший наставник из городской стражи Штормграда послал мне сообщение, что верховное командование Альянса обеспокоено появлением наг. По слухам, тот, кто хорошо проявит себя в этой области, получит повышение – или, по крайней мере, новое назначение.$B$BЕсть одна проблема... я не могу справиться с нагами. Разумеется, прекратить пьяную драку или скрутить воинственного вора я могу, но наги мне не по зубам. Помоги мне, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 береговых охотников и 10 сирен из клана Пронзающего Гребня по просьбе лейтенанта Фаррена Оринеля из Южнобережья.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я уже письмо написал майору Самуэльсону в Штормград. Теперь мне нужен результат.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Фаррену Оринелю в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (563,'Новое назначение','Мне будет легко добиться, чтобы мое донесение прочитали. Новый капитан стражи, майор Самуэльсон, был моим учителем еще в Штормграде. Ему не составит труда перевести меня обратно в столицу. Но придется попросить тебя отнести мое донесение ему... Главное, чтобы старина Редпат ничего не узнал.','Отнесите донесение Фаррена майору Самуэльсону в крепость Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое назначение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне будет легко добиться, чтобы мое донесение прочитали. Новый капитан стражи, майор Самуэльсон, был моим учителем еще в Штормграде. Ему не составит труда перевести меня обратно в столицу. Но придется попросить тебя отнести мое донесение ему... Главное, чтобы старина Редпат ничего не узнал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите донесение Фаррена майору Самуэльсону в крепость Штормграда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (564,'Серьезная угроза','Ничто не злит меня так, как потеря отличных коней. И поверь, эти назойливые мертвяки, синдикатские бандюги и прочие ни на что не годные негодяи лишили нас множества лошадок.$B$BНо я готов поклясться могилой моего прадедушки, что главный враг коней – горные львы Альтерака. Вечно осложняют мою жизнь!$b$bТы считаешь себя героем? Тогда пойди разберись с ними!','Убейте 8 горных львов и 10 крупных горных львов по поручению Даррена Малвея из Южнобережья.','Отличные новости! Надо было сразу же найти нормального героя войны, чтобы он разобрался со зверюгами. Твой папка гордился бы тобой, $N.','Горные львы убивают наших лошадей налево и направо, а вот ты хочешь болтать о погоде и прочем. Ты $Gдолжен:должна; пойти и найти себе настоящего героя. Больше убийств и меньше болтовни.','Вернитесь к Даррену Малвею в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезная угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ничто не злит меня так, как потеря отличных коней. И поверь, эти назойливые мертвяки, синдикатские бандюги и прочие ни на что не годные негодяи лишили нас множества лошадок.$B$BНо я готов поклясться могилой моего прадедушки, что главный враг коней – горные львы Альтерака. Вечно осложняют мою жизнь!$b$bТы считаешь себя героем? Тогда пойди разберись с ними!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 горных львов и 10 крупных горных львов по поручению Даррена Малвея из Южнобережья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные новости! Надо было сразу же найти нормального героя войны, чтобы он разобрался со зверюгами. Твой папка гордился бы тобой, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Горные львы убивают наших лошадей налево и направо, а вот ты хочешь болтать о погоде и прочем. Ты $Gдолжен:должна; пойти и найти себе настоящего героя. Больше убийств и меньше болтовни.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Даррену Малвею в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (565,'Плащ из меха йети','Я, великий Бартоло, сделаю для тебя знаменитый во всем Альянсе, да и во всем мире, плащ из меха йети!$b$bОбыщи весь белый свет, и нигде прекрасней нет! Что, что я слышу, $gмаленький:маленькая:r; |3-6($r)? "Бартоло, твои плащи лучше всех!" Да, да! Мне не раз это говорили.$B$BБартоло нужен рулон шерсти, плащ жителя холмов от искусного кожевника, тонкая нить и мех йети, конечно! Принеси мне все составляющие, и ты станешь $gсчастливым обладателем:счастливой обладательницей; одного из моих плащей!','Принесите Бартоло Джинсетти из Южнобережья рулон шерсти, плащ жителя холмов, тонкую нить и 10 клоков меха йети.','Вернитесь к Бартоло Джинсетти в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плащ из меха йети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я, великий Бартоло, сделаю для тебя знаменитый во всем Альянсе, да и во всем мире, плащ из меха йети!$b$bОбыщи весь белый свет, и нигде прекрасней нет! Что, что я слышу, $gмаленький:маленькая:r; |3-6($r)? "Бартоло, твои плащи лучше всех!" Да, да! Мне не раз это говорили.$B$BБартоло нужен рулон шерсти, плащ жителя холмов от искусного кожевника, тонкая нить и мех йети, конечно! Принеси мне все составляющие, и ты станешь $gсчастливым обладателем:счастливой обладательницей; одного из моих плащей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Бартоло Джинсетти из Южнобережья рулон шерсти, плащ жителя холмов, тонкую нить и 10 клоков меха йети.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бартоло Джинсетти в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (566,'РАЗЫСКИВАЕТСЯ: Барон Вардус','По приказу верховного палача Дарталии, человек по имени барон Вардус разыскивается по обвинению в многочисленных преступлениях против Отрекшихся. Вардус является высокопоставленным членом преступной организации Синдикат.$b$bВ последний раз его видели в Высокогорье Альтеракских гор, к северу от мельницы Таррен.$B$BОн приговаривается к смертной казни. Для получения награды необходимо предоставить доказательства его гибели верховному палачу Дарталии.','Убейте барона Вардуса и принесите его голову верховному палачу Дарталии на мельницу Таррен.','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РАЗЫСКИВАЕТСЯ: Барон Вардус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По приказу верховного палача Дарталии, человек по имени барон Вардус разыскивается по обвинению в многочисленных преступлениях против Отрекшихся. Вардус является высокопоставленным членом преступной организации Синдикат.$b$bВ последний раз его видели в Высокогорье Альтеракских гор, к северу от мельницы Таррен.$B$BОн приговаривается к смертной казни. Для получения награды необходимо предоставить доказательства его гибели верховному палачу Дарталии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте барона Вардуса и принесите его голову верховному палачу Дарталии на мельницу Таррен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (567,'Вооружены и очень опасны!','Внимание: вооружены и очень опасны!$b$bСледующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы:$b$bКлерк Гораций Белоконь. Разыскивается за убийство стража смерти Томма.$b$BГорожанин Вилкс. Разыскивается за убийство аптекаря Эли.$b$BШахтер Хакетт. Разыскивается за убийство ловчего смерти Фрая.$b$BФермерша Калаба. Разыскивается за нападение из засады на караван с припасами из Подгорода.$b$bВсе перечисленные преступники скрываются, и найти их нелегко. Награда будет выдана при предъявлении доказательств их смерти.','Верховный палач Дарталия из Мельницы Таррен назначила награду за убийство клерка Горация Белоконя, гражданина Уилкса, шахтера Хакетта и фермерши Калабы.','Да ты неплохой охотник за головами, |3-6($C).','Да?','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вооружены и очень опасны!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимание: вооружены и очень опасны!$b$bСледующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы:$b$bКлерк Гораций Белоконь. Разыскивается за убийство стража смерти Томма.$b$BГорожанин Вилкс. Разыскивается за убийство аптекаря Эли.$b$BШахтер Хакетт. Разыскивается за убийство ловчего смерти Фрая.$b$BФермерша Калаба. Разыскивается за нападение из засады на караван с припасами из Подгорода.$b$bВсе перечисленные преступники скрываются, и найти их нелегко. Награда будет выдана при предъявлении доказательств их смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный палач Дарталия из Мельницы Таррен назначила награду за убийство клерка Горация Белоконя, гражданина Уилкса, шахтера Хакетта и фермерши Калабы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да ты неплохой охотник за головами, |3-6($C).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Дарталии на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (568,'Защита Гром\'гола','Тром\'ка, |3-6($c)!$B$BТы на удивление вовремя $gоказался:оказалась; в Гром\'голе. Как командир лагеря Вождя, я обязан защищать всех сторонников Орды в этих джунглях. Наша цель – обеспечить бесперебойное снабжение Каменора, а некоторые обитатели здешних мест нам мешают.$B$BЯ поручаю тебе сократить численность ящеров рядом с Гром\'голом. Добившись заметных успехов, возвращайся, и я дам тебе новое задание.','Командир Аггро\'гош из лагеря Гром\'гол поручил вам убить 15 ящеров-кнутохвостов.','Ты исполнил свой долг с честью, |3-6($C).','$C. Докажи мне, что воины Кровавого Скальпа пали от твоей руки.\n\nГде твои трофеи?','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Гром\'гола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тром\'ка, |3-6($c)!$B$BТы на удивление вовремя $gоказался:оказалась; в Гром\'голе. Как командир лагеря Вождя, я обязан защищать всех сторонников Орды в этих джунглях. Наша цель – обеспечить бесперебойное снабжение Каменора, а некоторые обитатели здешних мест нам мешают.$B$BЯ поручаю тебе сократить численность ящеров рядом с Гром\'голом. Добившись заметных успехов, возвращайся, и я дам тебе новое задание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Аггро\'гош из лагеря Гром\'гол поручил вам убить 15 ящеров-кнутохвостов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты исполнил свой долг с честью, |3-6($C).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$C. Докажи мне, что воины Кровавого Скальпа пали от твоей руки.\n\nГде твои трофеи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (569,'Защита Гром\'гола','Отправляясь в джунгли, мы не собирались воевать с местными племенами. Главное – снабжение Каменора. Увы, возник ряд сложностей. Местные огры заняли руины Мизжа на юго-востоке от Гром\'гола. Невзирая на многочисленные предупреждения, они продолжают нападать на наши караваны.$B$BЯ приказываю тебе разобраться с этими упертыми ограми.$B$BОтправляйся в развалины и попытайся выбить их оттуда. По крайней мере, преподай им хороший урок.','Командир Аггро\'гош из лагеря Гром\'гол поручил вам убить 10 огров-громил и 5 огров-знахарей.','Отлично. Ты с честью послужил вождю.','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Гром\'гола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отправляясь в джунгли, мы не собирались воевать с местными племенами. Главное – снабжение Каменора. Увы, возник ряд сложностей. Местные огры заняли руины Мизжа на юго-востоке от Гром\'гола. Невзирая на многочисленные предупреждения, они продолжают нападать на наши караваны.$B$BЯ приказываю тебе разобраться с этими упертыми ограми.$B$BОтправляйся в развалины и попытайся выбить их оттуда. По крайней мере, преподай им хороший урок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Аггро\'гош из лагеря Гром\'гол поручил вам убить 10 огров-громил и 5 огров-знахарей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Ты с честью послужил вождю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Аггро\'гошу в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (570,'Чары Мок\'тардина','Орда должна узнать о силе магии джунглей и подчинить ее себе. Мне уже удалось добиться успеха, и я могу пользоваться могучими заклинаниями. Я сделаю для тебя особую вещь, $gотважный:отважная:c; |3-6($c).$B$BПринеси мне когти тенебрюхих пантер и клык тигрицы. Учти, что клык должен быть безупречно ровным.$B$BЭти твари разгуливают по всем джунглям, но тебе не придется далеко ходить – просто перейди реку рядом с руинами Мизжа на юго-востоке.','Провозвестник Мок\'тардин из лагеря Гром\'гол попросил вас принести ему 8 когтей тенебрюхих пантер и безупречный тигриный клык.','Добрые ли вести ты несешь?','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чары Мок\'тардина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда должна узнать о силе магии джунглей и подчинить ее себе. Мне уже удалось добиться успеха, и я могу пользоваться могучими заклинаниями. Я сделаю для тебя особую вещь, $gотважный:отважная:c; |3-6($c).$B$BПринеси мне когти тенебрюхих пантер и клык тигрицы. Учти, что клык должен быть безупречно ровным.$B$BЭти твари разгуливают по всем джунглям, но тебе не придется далеко ходить – просто перейди реку рядом с руинами Мизжа на юго-востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Провозвестник Мок\'тардин из лагеря Гром\'гол попросил вас принести ему 8 когтей тенебрюхих пантер и безупречный тигриный клык.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добрые ли вести ты несешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (571,'Чары Мок\'тардина','Следующий компонент будет нелегко найти.$B$BЧтобы связать перья, когти и чистый клык, мне понадобится волшебный шнурок. Нам подойдет лишь сухожилие старой гориллы.$B$BЕго можно добыть только у старых горилл Мглистой долины. Они кормятся к востоку от Пиратской Бухты.$B$BТолько сухожилие должно быть в идеальном состоянии. Быть может, тебе понадобится убить нескольких зверей, чтобы понять, что именно мне нужно, но результат того стоит.','Принесите сухожилие старой гориллы провозвестнику Мок\'тардину в лагерь Гром\'гола.','Превосходное сухожилие, $N. Твои усилия скоро окупятся.','Была ли удача на твоей стороне, $N? Удалось ли тебе добыть сухожилие старой гориллы?','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чары Мок\'тардина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следующий компонент будет нелегко найти.$B$BЧтобы связать перья, когти и чистый клык, мне понадобится волшебный шнурок. Нам подойдет лишь сухожилие старой гориллы.$B$BЕго можно добыть только у старых горилл Мглистой долины. Они кормятся к востоку от Пиратской Бухты.$B$BТолько сухожилие должно быть в идеальном состоянии. Быть может, тебе понадобится убить нескольких зверей, чтобы понять, что именно мне нужно, но результат того стоит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сухожилие старой гориллы провозвестнику Мок\'тардину в лагерь Гром\'гола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходное сухожилие, $N. Твои усилия скоро окупятся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Была ли удача на твоей стороне, $N? Удалось ли тебе добыть сухожилие старой гориллы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (572,'Чары Мок\'тардина','То, что тебе удалось добыть у зверей из семейства кошачьих – лишь первое, что требуется для создания могущественного зачарованного предмета. Меж тем украшения джунглей, усиленные при помощи моих ритуалов, неплохо послужат тебе в деле помощи Орде и Вождю.$B$BТеперь же собери для меня перья тропических ловцов. Эти твари как правило прикрепляют перья на лапы. На юге от Гром\'гола, недалеко от большой арены, есть такое племя ящеров.','Принесите 10 перьев тропических ловцов провозвестнику Мок\'тардину в лагерь Гром\'гол.','Великолепно. Я немедленно их подготовлю.','Сопутствовал ли тебе успех в охоте?','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чары Мок\'тардина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, что тебе удалось добыть у зверей из семейства кошачьих – лишь первое, что требуется для создания могущественного зачарованного предмета. Меж тем украшения джунглей, усиленные при помощи моих ритуалов, неплохо послужат тебе в деле помощи Орде и Вождю.$B$BТеперь же собери для меня перья тропических ловцов. Эти твари как правило прикрепляют перья на лапы. На юге от Гром\'гола, недалеко от большой арены, есть такое племя ящеров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 перьев тропических ловцов провозвестнику Мок\'тардину в лагерь Гром\'гол.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Я немедленно их подготовлю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сопутствовал ли тебе успех в охоте?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (573,'Чары Мок\'тардина','Остается лишь одно составляющее, и я смогу наложить чары на колье.$B$BК югу отсюда, близко от западного побережья, высоко над утесами, располагается Святой источник. Он вызывает множество конфликтов среди религиозных ученых. Все расы Азерота утверждают, что воды освящены именно для их народа.$B$BВот мое последнее поручение: принеси мне воду Святого источника. Соблюдай осторожность. Сейчас его окрестности захватили наги. С ними тоже следует разобраться.','Провозвестник Мок\'тардин из лагеря Гром\'гол попросил вас принести ему воду Святого источника. Кроме того, он поручил вам убить 10 наг-исследователей.','Ты принес мне воду Святого источника, и я могу наложить чары на церемониальное колье.$B$BНоси его с гордостью, во имя Вождя и мощи Орды.','Я готов к зачаровыванию. Вы выполнили мое поручение?','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чары Мок\'тардина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остается лишь одно составляющее, и я смогу наложить чары на колье.$B$BК югу отсюда, близко от западного побережья, высоко над утесами, располагается Святой источник. Он вызывает множество конфликтов среди религиозных ученых. Все расы Азерота утверждают, что воды освящены именно для их народа.$B$BВот мое последнее поручение: принеси мне воду Святого источника. Соблюдай осторожность. Сейчас его окрестности захватили наги. С ними тоже следует разобраться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Провозвестник Мок\'тардин из лагеря Гром\'гол попросил вас принести ему воду Святого источника. Кроме того, он поручил вам убить 10 наг-исследователей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты принес мне воду Святого источника, и я могу наложить чары на церемониальное колье.$B$BНоси его с гордостью, во имя Вождя и мощи Орды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я готов к зачаровыванию. Вы выполнили мое поручение?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провозвестнику Мок\'тардину в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (574,'Особые войска','После удара по обычным партизанам Курцена тебе придется вступить в схватку с его особыми отрядами. Они либо выбираются в лес и убивают наших солдат, либо отсиживаются позади поселка Курцена, в пещере, называемой Схрон.$B$BЯ знакома со многими воинами Курцена, и все они отличаются прекрасной подготовкой, верностью и жестокостью. Задание непростое, $n.$B$BЕсли ты сможешь их одолеть, доложи об этом лейтенанту Дорену, моему командиру. Он захочет услышать об этом из первых уст.','Убейте 10 коммандос и 6 охотников за головами Курцена.$B$BДоложите об этом лейтенанту Дорену из Лагеря Повстанцев.','Вернитесь к лейтенанту Дорену в Лагерь Повстанцев, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Особые войска',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После удара по обычным партизанам Курцена тебе придется вступить в схватку с его особыми отрядами. Они либо выбираются в лес и убивают наших солдат, либо отсиживаются позади поселка Курцена, в пещере, называемой Схрон.$B$BЯ знакома со многими воинами Курцена, и все они отличаются прекрасной подготовкой, верностью и жестокостью. Задание непростое, $n.$B$BЕсли ты сможешь их одолеть, доложи об этом лейтенанту Дорену, моему командиру. Он захочет услышать об этом из первых уст.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 коммандос и 6 охотников за головами Курцена.$B$BДоложите об этом лейтенанту Дорену из Лагеря Повстанцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Дорену в Лагерь Повстанцев, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (575,'Спрос и предложение','"Лучший мастер-кожевник Южных морей и старого и нового мира." Вот как меня называют! Меня! Дриззлика! Лучшим коже... Кхе-кхе. Короче.$B$BМои товары славятся по всему свету как наилучшие по мнению всех экспертов!$B$BЯ только что получил заказ от директора Ридлвокса из Союза ремонтников на дюжину его любимых превосходных сапог. Не скрою, это самая популярная модель.$B$BЧтобы приступить к раскройке, мне нужны шкуры кроколисков. Их можно добыть у реки в Северной Тернистой долине.','Принесите 2 большие шкуры речного кроколиска Дриззлику из Пиратской Бухты.','Вернитесь к Дриззлику в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спрос и предложение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Лучший мастер-кожевник Южных морей и старого и нового мира." Вот как меня называют! Меня! Дриззлика! Лучшим коже... Кхе-кхе. Короче.$B$BМои товары славятся по всему свету как наилучшие по мнению всех экспертов!$B$BЯ только что получил заказ от директора Ридлвокса из Союза ремонтников на дюжину его любимых превосходных сапог. Не скрою, это самая популярная модель.$B$BЧтобы приступить к раскройке, мне нужны шкуры кроколисков. Их можно добыть у реки в Северной Тернистой долине.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 большие шкуры речного кроколиска Дриззлику из Пиратской Бухты.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дриззлику в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (576,'Смотри в оба','Стой! Кто идет?$B$BАррр, кому я нужен без волшебного глаза. Мало того, что я лишился зрения в бою! Но тогда мне свезло, и один волшебник зачаровал для меня особый стеклянный глаз, и я снова мог видеть.$B$BА вчера на меня по дороге накинулись пираты Кровавого Паруса и отобрали у меня глаз! Кажется, эти типы чувствуют себя в Пиратской Бухте как дома.$B$BНе поможешь старому морскому волку вернуть зрение?','Диззи Одноглазый из Пиратской Бухты попросил вас отобрать его глаз у пиратов Кровавого Паруса.','Вернитесь к Одноглазому Диззи в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смотри в оба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стой! Кто идет?$B$BАррр, кому я нужен без волшебного глаза. Мало того, что я лишился зрения в бою! Но тогда мне свезло, и один волшебник зачаровал для меня особый стеклянный глаз, и я снова мог видеть.$B$BА вчера на меня по дороге накинулись пираты Кровавого Паруса и отобрали у меня глаз! Кажется, эти типы чувствуют себя в Пиратской Бухте как дома.$B$BНе поможешь старому морскому волку вернуть зрение?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Диззи Одноглазый из Пиратской Бухты попросил вас отобрать его глаз у пиратов Кровавого Паруса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Одноглазому Диззи в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (577,'Немного разнообразия не помешает','Что ж, я раскроил основу сапог, получается превосходно, но на подбой шкур не хватит.$B$B"Что же делать, Дриззлик?" – спросишь ты. К счастью, ты говоришь со мной, и я скажу тебе, как мы поступим!$B$BПодбой все равно никто не видит, поэтому мы используем более толстую и дешевую шкуру кроколисков с озера Назферити.','Отнесите 5 шкур кроколисков-хрустогрызов Дриззлику в Пиратскую Бухту.','Превосходные сапоги Дриззлика – отличная работа, стопроцентная кожа морских кроколисков. Лучше не бывает!\n\nОписания заманчивей не придумаешь, верно?\n\nРазве что ты принес мне шкуры?','Вернитесь к Дриззлику в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Немного разнообразия не помешает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, я раскроил основу сапог, получается превосходно, но на подбой шкур не хватит.$B$B"Что же делать, Дриззлик?" – спросишь ты. К счастью, ты говоришь со мной, и я скажу тебе, как мы поступим!$B$BПодбой все равно никто не видит, поэтому мы используем более толстую и дешевую шкуру кроколисков с озера Назферити.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 5 шкур кроколисков-хрустогрызов Дриззлику в Пиратскую Бухту.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Превосходные сапоги Дриззлика – отличная работа, стопроцентная кожа морских кроколисков. Лучше не бывает!\n\nОписания заманчивей не придумаешь, верно?\n\nРазве что ты принес мне шкуры?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дриззлику в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (578,'Камень приливов','Если правду говорят о гоблине-маге и элементалях воды, живущих на острове, значит я могу заполучить Камень Приливов!$B$BНайди этот остров... И выясни, что происходит. И если ты хочешь узнать подробнее о Камне Приливов, отнеси эту записку в библиотеку Штормграда, они найдут тебе книгу, в которой я впервые прочитал эту легенду.$B$BНеужели Газбан в самом деле нашел Камень?..','По поручению барона Ревилгаза из Пиратской Бухты найдите остров, населенный духами Воды.','У троллей действительно были удивительные волшебные предметы, $N. И теперь, возможно, у меня есть возможность пополнить свою обширную коллекцию. Удалось ли вам найти источник слухов?','Найдите остров духов Воды','Вернитесь к барону Ревилгазу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камень приливов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если правду говорят о гоблине-маге и элементалях воды, живущих на острове, значит я могу заполучить Камень Приливов!$B$BНайди этот остров... И выясни, что происходит. И если ты хочешь узнать подробнее о Камне Приливов, отнеси эту записку в библиотеку Штормграда, они найдут тебе книгу, в которой я впервые прочитал эту легенду.$B$BНеужели Газбан в самом деле нашел Камень?..',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению барона Ревилгаза из Пиратской Бухты найдите остров, населенный духами Воды.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У троллей действительно были удивительные волшебные предметы, $N. И теперь, возможно, у меня есть возможность пополнить свою обширную коллекцию. Удалось ли вам найти источник слухов?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите остров духов Воды',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (579,'Библиотека Штормграда','Король Вариан уделяет огромное внимание просвещению и всемерно заботится о том, чтобы с ценных книг вовремя делались списки, доступные горожанам. Все просто: принесите мне библиотечный свиток, и я выдам вам копию любой имеющейся книги.','Вернитесь к Доналу Товальду в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Библиотека Штормграда',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Король Вариан уделяет огромное внимание просвещению и всемерно заботится о том, чтобы с ценных книг вовремя делались списки, доступные горожанам. Все просто: принесите мне библиотечный свиток, и я выдам вам копию любой имеющейся книги.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Доналу Товальду в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (580,'Потерянный грог Алкача Виски','На подходе к Отвесным скалам, как раз в тот момент, когда старые добрые Внутренние земли показались на горизонте, нас настигла жуткая буря. Мы думали – все, нам каюк, море нас проглотит.$B$BНо старый Алкач знает, что такое жидкая храбрость! У кэпа был ящик портвейна "Пупелливербос", который мы взяли трофеем у одного пирата по пути в Штормград.$B$BВ общем, когда с Внутренних земель налетел шторм, я налег на грог. И тут шхуну захлестнула большая волна и смыла бутылки за борт. Кэп всыплет мне по первое число, если ты не поможешь их найти.','Алкач Виски из Пиратской Бухты попросил вас принести ему потерянные бутылки портвейна "Пупелливербос".','Вернитесь к Алкачу Виски в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянный грог Алкача Виски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На подходе к Отвесным скалам, как раз в тот момент, когда старые добрые Внутренние земли показались на горизонте, нас настигла жуткая буря. Мы думали – все, нам каюк, море нас проглотит.$B$BНо старый Алкач знает, что такое жидкая храбрость! У кэпа был ящик портвейна "Пупелливербос", который мы взяли трофеем у одного пирата по пути в Штормград.$B$BВ общем, когда с Внутренних земель налетел шторм, я налег на грог. И тут шхуну захлестнула большая волна и смыла бутылки за борт. Кэп всыплет мне по первое число, если ты не поможешь их найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Алкач Виски из Пиратской Бухты попросил вас принести ему потерянные бутылки портвейна "Пупелливербос".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алкачу Виски в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (581,'Поиски Йеннику','Нас постиг злой рок. И коснулось это младшего сына моего вождя. Как у нас и заведено, мы отдали его на воспитание племени Гурубаши в Зул\'Гурубе, но после того, как племя Черного Копья последовало за орком Траллом, бедняга Йеннику оказался потерян для нас. Меня прислали в Тернистую долину из далекого Оргриммара на поиски сына вождя.$B$BЯ думаю, он в руках племени Кровавого Скальпа.$B$BЕсли ты хочешь помочь мне, напади на них. Они живут к северу отсюда. Собери их клыки и принеси мне.','Принесите 9 клыков тролля из племени Кровавого Скальпа Нимбойе в лагерь Гром\'гол.','$C. Докажи мне, что воины Кровавого Скальпа пали от твоей руки.\n\nГде твои трофеи?','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Йеннику',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нас постиг злой рок. И коснулось это младшего сына моего вождя. Как у нас и заведено, мы отдали его на воспитание племени Гурубаши в Зул\'Гурубе, но после того, как племя Черного Копья последовало за орком Траллом, бедняга Йеннику оказался потерян для нас. Меня прислали в Тернистую долину из далекого Оргриммара на поиски сына вождя.$B$BЯ думаю, он в руках племени Кровавого Скальпа.$B$BЕсли ты хочешь помочь мне, напади на них. Они живут к северу отсюда. Собери их клыки и принеси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 9 клыков тролля из племени Кровавого Скальпа Нимбойе в лагерь Гром\'гол.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$C. Докажи мне, что воины Кровавого Скальпа пали от твоей руки.\n\nГде твои трофеи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (582,'Охота за головами','Мы должны узнать, мертв ли Йеннику.$B$BУбей как можно больше охотников за головами из племени Кровавого Скальпа и забери у них сушеные головы. Набери как можно больше голов, и я осмотрю их, чтобы убедиться, что среди них нет головы Йеннику.$B$BЕсли племя Кровавого Скальпа убило Йеннику, да падет 600-летнее проклятье на душу их предводителя, Ган\'зулаха!$B$BСтупай, $n. Охотников за головами можно найти в Руинах Зуулдая и Зул\'Кунды, в северной части побережья.','Принесите Нимбойе из лагеря Гром\'гол 20 сушеных голов.','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота за головами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны узнать, мертв ли Йеннику.$B$BУбей как можно больше охотников за головами из племени Кровавого Скальпа и забери у них сушеные головы. Набери как можно больше голов, и я осмотрю их, чтобы убедиться, что среди них нет головы Йеннику.$B$BЕсли племя Кровавого Скальпа убило Йеннику, да падет 600-летнее проклятье на душу их предводителя, Ган\'зулаха!$B$BСтупай, $n. Охотников за головами можно найти в Руинах Зуулдая и Зул\'Кунды, в северной части побережья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Нимбойе из лагеря Гром\'гол 20 сушеных голов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (583,'Добро пожаловать в джунгли','Добро пожаловать в Тернистую долину!$b$bБыть может, ты не знаешь об этом, но этот дворф – сын единственного и неповторимого Хеминга Эрнестуэя, прославленного героя Альянса и великого охотника на крупную дичь. Подобно отцу, он не слишком жалует гостей, но на твою долю выпало немало приключений, |3-6($c).$b$bСтупай, поговори с ним. Яблочко от яблоньки, как говорится, далеко не падает... наверное, он сможет научить тебя охотиться.','Поговорите с Хемингом Эрнестуэем-младшим.','Поговорите с Хемингом Эрнестуэем-младшим в лагере экспедиции Эрнестуэя, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать в джунгли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в Тернистую долину!$b$bБыть может, ты не знаешь об этом, но этот дворф – сын единственного и неповторимого Хеминга Эрнестуэя, прославленного героя Альянса и великого охотника на крупную дичь. Подобно отцу, он не слишком жалует гостей, но на твою долю выпало немало приключений, |3-6($c).$b$bСтупай, поговори с ним. Яблочко от яблоньки, как говорится, далеко не падает... наверное, он сможет научить тебя охотиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хемингом Эрнестуэем-младшим.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хемингом Эрнестуэем-младшим в лагере экспедиции Эрнестуэя, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (584,'Головы племени Кровавого Скальпа','Я не нашел Йеннику среди голов, хвала Великому Змею за это. Но мы не сильно продвинулись в наших поисках.$B$BНеобходимо выяснить правду, и, боюсь, она известна лишь вождю племени Кровавого Скальпа и его знахарю. Они враги племени Черного Копья, и просто так говорить не будут, поэтому мы должны вырвать правду из их мертвых губ!$B$BПринеси мне головы Ган\'зулаха и Неззилока Зловещего и помести их в этот котел.$B$BЭти тролли живут в глубине Руин Зул\'Кунды. Принеси их головы... а уж говорить мы их заставим.','Принесите головы Ган\'зулаха и Неззилока и положите их в бурлящий котел в лагере Гром\'гол.','Вы кладете в котел головы Ган\'зулаха и Неззилока...','Зеленый отвар в котле бурлит.','Вернитесь к бурлящему котлу в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Головы племени Кровавого Скальпа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не нашел Йеннику среди голов, хвала Великому Змею за это. Но мы не сильно продвинулись в наших поисках.$B$BНеобходимо выяснить правду, и, боюсь, она известна лишь вождю племени Кровавого Скальпа и его знахарю. Они враги племени Черного Копья, и просто так говорить не будут, поэтому мы должны вырвать правду из их мертвых губ!$B$BПринеси мне головы Ган\'зулаха и Неззилока Зловещего и помести их в этот котел.$B$BЭти тролли живут в глубине Руин Зул\'Кунды. Принеси их головы... а уж говорить мы их заставим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите головы Ган\'зулаха и Неззилока и положите их в бурлящий котел в лагере Гром\'гол.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы кладете в котел головы Ган\'зулаха и Неззилока...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Зеленый отвар в котле бурлит.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бурлящему котлу в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (585,'Разговор с Неззилоком','<Голова Неззилока начинает говорить.>$B$BЭто правда. Я знаю, куда увели дитя Черного Копья. Ты $gодолел:одолела; меня и $gсвязал:связала; мой дух, но я все равно не буду говорить даром!$B$BПлемя Кровавого Скальпа враждует с племенем Дробителей Черепов. Чтобы добиться от меня ответа, укради 3 трофейных черепа у племени Дробителей Черепов и положи их к нам, чтобы мой дух обрел рабов в Пустоте. Один череп возьми в Балиа\'ма, другой – в Зиата\'джаи, а последний – в Зул\'Мамве.','Принесите в лагерь Гром\'гол трофей из Балиа\'ма, трофей из Зиата\'джаи и трофей из Зул\'Мамве и положите их в бурлящий котел.','Да. Ты сослужил мне добрую службу. Когда мой дух освободится, я войду в Пустоту и обрету трех отличных слуг!\n\nТы – гордость своего клана, |3-6($R), и умилостивил меня.','Я жду черепов...','Вернитесь к бурлящему котлу в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Неззилоком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Голова Неззилока начинает говорить.>$B$BЭто правда. Я знаю, куда увели дитя Черного Копья. Ты $gодолел:одолела; меня и $gсвязал:связала; мой дух, но я все равно не буду говорить даром!$B$BПлемя Кровавого Скальпа враждует с племенем Дробителей Черепов. Чтобы добиться от меня ответа, укради 3 трофейных черепа у племени Дробителей Черепов и положи их к нам, чтобы мой дух обрел рабов в Пустоте. Один череп возьми в Балиа\'ма, другой – в Зиата\'джаи, а последний – в Зул\'Мамве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите в лагерь Гром\'гол трофей из Балиа\'ма, трофей из Зиата\'джаи и трофей из Зул\'Мамве и положите их в бурлящий котел.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да. Ты сослужил мне добрую службу. Когда мой дух освободится, я войду в Пустоту и обрету трех отличных слуг!\n\nТы – гордость своего клана, |3-6($R), и умилостивил меня.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я жду черепов...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бурлящему котлу в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (586,'Разговор с Ган\'зулахом','<Голова Ган\'зулаха начинает говорить.>$B$BБудь ты $gпроклят:проклята;! И будь прокляты твои предки!!!$B$BЛишь кровь и месть остудят мою ярость, поэтому если ты этого добиваешься, то... сделай вот что:$B$BОтправляйся в сердце владений Дробителей Черепов на востоке. Убей самых лютых воинов, и если выживешь... брось вызов их вождю, Анатеку Жестокому. Ха! Принеси мне его разбитую броню, если сможешь!$B$BДа оторвет он у тебя руки и ноги и бросит медленно гнить. Да станешь ты добычей падальщиков!','Убейте 8 охотников, 6 охотников за головами и 4 берсерков из племени Дробителей Черепов.$B$BПринесите разбитую броню Анатека к бурлящему котлу в лагере Гром\'гол.','Хотя моя собственная плоть постепенно облезает с черепа, я чую твой страх.\n\nХа! Ты никогда не справишься с моим заданием...','Вернитесь к бурлящему котлу в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Ган\'зулахом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Голова Ган\'зулаха начинает говорить.>$B$BБудь ты $gпроклят:проклята;! И будь прокляты твои предки!!!$B$BЛишь кровь и месть остудят мою ярость, поэтому если ты этого добиваешься, то... сделай вот что:$B$BОтправляйся в сердце владений Дробителей Черепов на востоке. Убей самых лютых воинов, и если выживешь... брось вызов их вождю, Анатеку Жестокому. Ха! Принеси мне его разбитую броню, если сможешь!$B$BДа оторвет он у тебя руки и ноги и бросит медленно гнить. Да станешь ты добычей падальщиков!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 охотников, 6 охотников за головами и 4 берсерков из племени Дробителей Черепов.$B$BПринесите разбитую броню Анатека к бурлящему котлу в лагере Гром\'гол.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хотя моя собственная плоть постепенно облезает с черепа, я чую твой страх.\n\nХа! Ты никогда не справишься с моим заданием...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бурлящему котлу в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (587,'Понюшка табака','Ах, жизнь моряцкая! Не скажу, что она хороша, но это моя жизнь.$B$BПришвартовавшись в порту, я люблю выпить бутылочку грога и нюхнуть хорошего табачку. Вредные привычки, но что за пират без пороков, а?$B$BТолько представь, как я был разочарован, узнав, что местный травник распродал весь товар. Говорит, мол, новую поставку перехватили эти проклятые пираты Кровавого Паруса.$B$BГотов поспорить, что $gбесстрашный:бесстрашная:c; |3-6($c) вроде тебя сможет убедить их поделиться товаром, а?','Диг из Пиратской Бухты попросил принести ему 15 понюшек табаку.','Вернитесь к Дигу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Понюшка табака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, жизнь моряцкая! Не скажу, что она хороша, но это моя жизнь.$B$BПришвартовавшись в порту, я люблю выпить бутылочку грога и нюхнуть хорошего табачку. Вредные привычки, но что за пират без пороков, а?$B$BТолько представь, как я был разочарован, узнав, что местный травник распродал весь товар. Говорит, мол, новую поставку перехватили эти проклятые пираты Кровавого Паруса.$B$BГотов поспорить, что $gбесстрашный:бесстрашная:c; |3-6($c) вроде тебя сможет убедить их поделиться товаром, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Диг из Пиратской Бухты попросил принести ему 15 понюшек табаку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дигу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (588,'Судьба Йеннику','<Неззилок говорит.>$B$BТы $gсумел:сумела; угодить и мне, и вождю, и я скажу тебе то, что ты хочешь знать...$B$BЮный Йеннику навеки потерян для своего племени.$B$BЕго забрал к себе знахарь Занзил Отверженный. Теперь Занзил полностью подчинил себе его тело и душу, и лишь сильнейшая магия может освободить его.$B$BТы такой магией не владеешь, |3-6($c).$B$BБыть может, племя Черного Копья, ваши союзники, могло бы подарить надежду на спасение Йеннику. Но лично я сомневаюсь.','Поговорите с Кин\'вилаем.','Занзил Отверженный??\n\nЕсли Йеннику и правда попал в руки этого тролля, могущественного и злого знахаря, то надежды почти нет. Почти. Не больше букашечки.\n\nНо малая надежда лучше, чем совсем никакой.','Поговорите с Кин\'вилаем в лагере Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Йеннику',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Неззилок говорит.>$B$BТы $gсумел:сумела; угодить и мне, и вождю, и я скажу тебе то, что ты хочешь знать...$B$BЮный Йеннику навеки потерян для своего племени.$B$BЕго забрал к себе знахарь Занзил Отверженный. Теперь Занзил полностью подчинил себе его тело и душу, и лишь сильнейшая магия может освободить его.$B$BТы такой магией не владеешь, |3-6($c).$B$BБыть может, племя Черного Копья, ваши союзники, могло бы подарить надежду на спасение Йеннику. Но лично я сомневаюсь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кин\'вилаем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Занзил Отверженный??\n\nЕсли Йеннику и правда попал в руки этого тролля, могущественного и злого знахаря, то надежды почти нет. Почти. Не больше букашечки.\n\nНо малая надежда лучше, чем совсем никакой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кин\'вилаем в лагере Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (589,'Поющие кристаллы','Легенды повествуют о драгоценном камне, сокрытом в самом сердце Тернистой долины. Мы зовем его Оком разума, и он хранит в себе великую мощь. Если добыть этот камень, быть может, удастся вернуть Йеннику из тьмы.$B$BЯ попрошу духов джунглей помочь нам в поисках Ока разума. Тем временем отправляйся в рудник Хрустальной шахты на юго-востоке отсюда и добудь пульсирующие синие осколки из железозубых василисков. Осколки встречаются очень редко, но без их магии мы не сможем подчинить себе Око разума.','Принесите 3 пульсирующих синих осколка Кин\'вилаю в лагерь Гром\'гол.','Вернитесь к Кин\'вилаю в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поющие кристаллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Легенды повествуют о драгоценном камне, сокрытом в самом сердце Тернистой долины. Мы зовем его Оком разума, и он хранит в себе великую мощь. Если добыть этот камень, быть может, удастся вернуть Йеннику из тьмы.$B$BЯ попрошу духов джунглей помочь нам в поисках Ока разума. Тем временем отправляйся в рудник Хрустальной шахты на юго-востоке отсюда и добудь пульсирующие синие осколки из железозубых василисков. Осколки встречаются очень редко, но без их магии мы не сможем подчинить себе Око разума.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 пульсирующих синих осколка Кин\'вилаю в лагерь Гром\'гол.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кин\'вилаю в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (590,'Выгодная сделка','Что?$b$bЧТО?!$b$bДенег хочешь? Не должен я тебе никаких денег. $b$bПисьмо? Какое письмо? Может, еще и подеремся? Ну, $gприятель:подружка;, давай! Вот еще, деньги я должен...','Одержите победу в схватке с Кальвином Монтеччи в Похоронном Звоне.','Победите Кальвина Монтеччи.','Вернитесь к Кальвину Монтеччи в Похоронный Звон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выгодная сделка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что?$b$bЧТО?!$b$bДенег хочешь? Не должен я тебе никаких денег. $b$bПисьмо? Какое письмо? Может, еще и подеремся? Ну, $gприятель:подружка;, давай! Вот еще, деньги я должен...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу в схватке с Кальвином Монтеччи в Похоронном Звоне.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победите Кальвина Монтеччи.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кальвину Монтеччи в Похоронный Звон.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (591,'Вернитесь к Кин\'вилаю в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кин\'вилаю в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (592,'Спасение Йеннику','Победа! Ты $Gосвободил:освободила; Йеннику от воли Занзила и выполнил задание, которое я считал безнадежным.$B$BНаше племя будет воспевать твое имя, $N, и мы на каменных плитах напишем повесть о тебе, чтобы она никогда не забылась.','$N. Кин\'вилай сказал, что послал тебя за Йеннику.$B$BЭто правда? Тебе удалось поймать его душу?','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Йеннику',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Победа! Ты $Gосвободил:освободила; Йеннику от воли Занзила и выполнил задание, которое я считал безнадежным.$B$BНаше племя будет воспевать твое имя, $N, и мы на каменных плитах напишем повесть о тебе, чтобы она никогда не забылась.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N. Кин\'вилай сказал, что послал тебя за Йеннику.$B$BЭто правда? Тебе удалось поймать его душу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (593,'Вы прикасаетесь к его лбу самоцветом Души. Он вздрагивает, когда волшебный предмет всасывает его разум, оставляя лишь тело, бездушную оболочку.','Ошеломленный Йеннику стоит перед вами, его разум в другом месте...','Вернитесь к Йеннику в Тернистую долину.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы прикасаетесь к его лбу самоцветом Души. Он вздрагивает, когда волшебный предмет всасывает его разум, оставляя лишь тело, бездушную оболочку.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ошеломленный Йеннику стоит перед вами, его разум в другом месте...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йеннику в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (594,'Послание в бутылке','Записка написана красивым почерком. В ней значится:$B$BЛюбому, кто может мне помочь.$B$BПрошу тебя, не оставь меня в нужде. Великий Небогрив держит меня в плену на острове в Южных морях.$B$BПо ночам я смотрю на чужие звезды, полускрытые листвой деревьев, но в самую хорошую погоду на северо-западе я вижу Южное взморье и большие корабли на юго-западе.$B$BМолю тебя, мой будущий спаситель, помоги мне.','Отыщите автора послания в бутылке.','Разыщите автора этого послания в бутылке. Он должен быть где-то в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание в бутылке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Записка написана красивым почерком. В ней значится:$B$BЛюбому, кто может мне помочь.$B$BПрошу тебя, не оставь меня в нужде. Великий Небогрив держит меня в плену на острове в Южных морях.$B$BПо ночам я смотрю на чужие звезды, полускрытые листвой деревьев, но в самую хорошую погоду на северо-западе я вижу Южное взморье и большие корабли на юго-западе.$B$BМолю тебя, мой будущий спаситель, помоги мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите автора послания в бутылке.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите автора этого послания в бутылке. Он должен быть где-то в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (595,'Пираты Кровавого паруса','Ты не прочь подзаработать, а, $gприятель:подружка;? Понять не могу, зачем сухопутной крысе вроде тебя понадобилось помогать Разбойникам Черноводья, но не гнать же тебя в шею!$B$BМы только что бросили якорь в Пиратской Бухте, и уже прослышали, что наши соперники – гнусные, подлые пираты Кровавого Паруса – пустили корни в южной части Тернистой долины.$B$BВсе мои ребята слишком увлеклись грогом и девками! А мне нужен разведчик.$B$BОсмотри залив на севере от Пиратской Бухты рядом с Гибельным берегом и расскажи мне, что там творится.','Первый помощник Кразз попросил вас осмотреть залив на севере от Пиратской Бухты.','На крышке бочки лежит карта, на которой торопливо нацарапана пара слов, и несколько монет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пираты Кровавого паруса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не прочь подзаработать, а, $gприятель:подружка;? Понять не могу, зачем сухопутной крысе вроде тебя понадобилось помогать Разбойникам Черноводья, но не гнать же тебя в шею!$B$BМы только что бросили якорь в Пиратской Бухте, и уже прослышали, что наши соперники – гнусные, подлые пираты Кровавого Паруса – пустили корни в южной части Тернистой долины.$B$BВсе мои ребята слишком увлеклись грогом и девками! А мне нужен разведчик.$B$BОсмотри залив на севере от Пиратской Бухты рядом с Гибельным берегом и расскажи мне, что там творится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Первый помощник Кразз попросил вас осмотреть залив на севере от Пиратской Бухты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На крышке бочки лежит карта, на которой торопливо нацарапана пара слов, и несколько монет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (596,'Ожерелье кровавых костей','Меня послали в Гром\'гол на помощь Нимбойе, но... У меня здесь свои дела.$B$BПлемя Кровавого Скальпа – наш заклятый враг. Трофеи, собранные с врагов, дают власть над ними. Ты можешь помочь нашему племени, открыв охоту на врага.$B$BПлемя Кровавого Скальпа живет на севере отсюда. Убей побольше троллей этого племени и забери у них ожерелья Кровавых костей. Собери как можно больше, и я награжу тебя.','Принесите Кин\'вилаю 25 ожерелий Кровавых костей в лагерь Гром\'гол.','Когда-нибудь племя Черного Копья сокрушит Кровавый Скальп! Ты принес мне ожерелья наших врагов?','Вернитесь к Кин\'вилаю в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье кровавых костей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня послали в Гром\'гол на помощь Нимбойе, но... У меня здесь свои дела.$B$BПлемя Кровавого Скальпа – наш заклятый враг. Трофеи, собранные с врагов, дают власть над ними. Ты можешь помочь нашему племени, открыв охоту на врага.$B$BПлемя Кровавого Скальпа живет на севере отсюда. Убей побольше троллей этого племени и забери у них ожерелья Кровавых костей. Собери как можно больше, и я награжу тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Кин\'вилаю 25 ожерелий Кровавых костей в лагерь Гром\'гол.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда-нибудь племя Черного Копья сокрушит Кровавый Скальп! Ты принес мне ожерелья наших врагов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кин\'вилаю в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (597,'Пираты Кровавого паруса','Отнесите находку первому помощнику Краззу в Пиратскую Бухту.','Поговорите с первым помощником Краззом в Пиратской Бухте, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пираты Кровавого паруса',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите находку первому помощнику Краззу в Пиратскую Бухту.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с первым помощником Краззом в Пиратской Бухте, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (598,'Ожерелье расколотых костей','Раз ты $gпринес:принесла; трофеи от Кровавого Скальпа, у меня есть для тебя другое задание. На юго-востоке живет племя Дробителей Черепов, и мы воевали с ними много лет. Хотя племя Черного Копья давно не живет в Тернистой долине, мы не забыли раздоров с Дробителями Черепов.$B$BТак что начни на них охоту. Собери побольше ожерельев Расколотых костей и принеси их мне. Помоги нам, и заслужишь признательность племени Черного Копья.','Принесите 25 ожерелий Расколотых костей Кин\'вилаю в лагерь Гром\'гол.','Клан Дробителей Черепов проклянет день, когда они выступили против нас! Ты справился с моим заданием?','Вернитесь к Кин\'вилаю в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье расколотых костей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз ты $gпринес:принесла; трофеи от Кровавого Скальпа, у меня есть для тебя другое задание. На юго-востоке живет племя Дробителей Черепов, и мы воевали с ними много лет. Хотя племя Черного Копья давно не живет в Тернистой долине, мы не забыли раздоров с Дробителями Черепов.$B$BТак что начни на них охоту. Собери побольше ожерельев Расколотых костей и принеси их мне. Помоги нам, и заслужишь признательность племени Черного Копья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 25 ожерелий Расколотых костей Кин\'вилаю в лагерь Гром\'гол.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Клан Дробителей Черепов проклянет день, когда они выступили против нас! Ты справился с моим заданием?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кин\'вилаю в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (599,'Пираты Кровавого паруса','Лопни моя селезенка! Значит, пираты Кровавого Паруса собираются напасть на Пиратскую Бухту? Вот наглость-то! Этот город испокон века был в руках Пиратов Черноводья!$B$BЗначит, дела обстоят хуже, чем я думал. Немедленно расскажи об этом командиру флота Морскому Рогу! Этот старый морской волк шатается где-то по городу...','Сообщите о запланированном нападении Кровавого Паруса командиру флота Морскому Рогу.','Поговорите с командиром флота Морским Рогом в Пиратской Бухте, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пираты Кровавого паруса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лопни моя селезенка! Значит, пираты Кровавого Паруса собираются напасть на Пиратскую Бухту? Вот наглость-то! Этот город испокон века был в руках Пиратов Черноводья!$B$BЗначит, дела обстоят хуже, чем я думал. Немедленно расскажи об этом командиру флота Морскому Рогу! Этот старый морской волк шатается где-то по городу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите о запланированном нападении Кровавого Паруса командиру флота Морскому Рогу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром флота Морским Рогом в Пиратской Бухте, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (600,'Рудник Торговой Компании','Торговая Компания ведет операции в Тернистой долине, которые не дают трудолюбивым гоблинам вроде меня честно зарабатывать деньги! Пожалуйста, помоги мне!$B$BТорговая Компания обосновалась возле Хрустальной шахты к северу отсюда. Внутрь они проникнуть не могут из-за злобных василисков, но все равно умудряются добывать Поющие кристаллы в ближайших холмах.$B$BОтбери у них эти кристаллы, показав тем самым, что джунгли им не принадлежат.$B$BИ.. э... принеси в доказательство сами кристаллы!','Принесите Шиззи Пуззыриксу из Пиратской Бухты 10 синих Поющих кристаллов.','Вернитесь к Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рудник Торговой Компании',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Торговая Компания ведет операции в Тернистой долине, которые не дают трудолюбивым гоблинам вроде меня честно зарабатывать деньги! Пожалуйста, помоги мне!$B$BТорговая Компания обосновалась возле Хрустальной шахты к северу отсюда. Внутрь они проникнуть не могут из-за злобных василисков, но все равно умудряются добывать Поющие кристаллы в ближайших холмах.$B$BОтбери у них эти кристаллы, показав тем самым, что джунгли им не принадлежат.$B$BИ.. э... принеси в доказательство сами кристаллы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Шиззи Пуззыриксу из Пиратской Бухты 10 синих Поющих кристаллов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (601,'Элементали воды','Элементалей воды, несомненно, призвал Газбан, гоблин-волшебник, который нашел Камень Приливов, если верить слухам. Мы знаем, что на владельца камня накладывается проклятие, которое то стирает его из реальности, то возвращает обратно в наш мир...$B$BБыть может, нам удастся снять проклятье. Один даларанский маг может исследовать следы магии на браслетах элементалей. Отправляйся на остров и принеси несколько штук.','Принесите барону Ревилгазу в Пиратскую Бухту 6 браслетов элементалей воды.','Вернитесь к барону Ревилгазу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Элементали воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Элементалей воды, несомненно, призвал Газбан, гоблин-волшебник, который нашел Камень Приливов, если верить слухам. Мы знаем, что на владельца камня накладывается проклятие, которое то стирает его из реальности, то возвращает обратно в наш мир...$B$BБыть может, нам удастся снять проклятье. Один даларанский маг может исследовать следы магии на браслетах элементалей. Отправляйся на остров и принеси несколько штук.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите барону Ревилгазу в Пиратскую Бухту 6 браслетов элементалей воды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (602,'Магический анализ','Насколько я знаю, магам Даларана удалось восстановить свой разрушенный город и перенести его в небо над Нордсколом, оставив позади гигантский кратер. Но некоторые маги остались здесь, и один из них обязательно найдет время посмотреть на браслеты. Насколько я знаю магов, они не устоят перед возможностью разгадать запутанную магическую головоломку.$B$BВозьми сумку с браслетами элементалей воды и узнай, не прольют ли они свет на проклятие Камня. Лучше всего обратиться к верховному магу Ансарему Руноплету. Я уже имел с ним дело, и его знания велики.','Отнесите браслеты элементалей воды верховному магу Ансарему Руноплету в Даларан.','Поговорите с верховным магом Ансаремом Руноплетом в Даларанском кратере, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магический анализ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько я знаю, магам Даларана удалось восстановить свой разрушенный город и перенести его в небо над Нордсколом, оставив позади гигантский кратер. Но некоторые маги остались здесь, и один из них обязательно найдет время посмотреть на браслеты. Насколько я знаю магов, они не устоят перед возможностью разгадать запутанную магическую головоломку.$B$BВозьми сумку с браслетами элементалей воды и узнай, не прольют ли они свет на проклятие Камня. Лучше всего обратиться к верховному магу Ансарему Руноплету. Я уже имел с ним дело, и его знания велики.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите браслеты элементалей воды верховному магу Ансарему Руноплету в Даларан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным магом Ансаремом Руноплетом в Даларанском кратере, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (602,'The Stone of the Tides? Most interesting. It might surprise you to know that I wrote a tome--several years ago--pertaining to the legends of the Gurubashi Empire. I do know quite a bit about the Stone.$B$BAt least one of these bracers appears to have some magical residue I can analyze.$B$BLet\'s see what I can see...') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','The Stone of the Tides? Most interesting. It might surprise you to know that I wrote a tome--several years ago--pertaining to the legends of the Gurubashi Empire. I do know quite a bit about the Stone.$B$BAt least one of these bracers appears to have some magical residue I can analyze.$B$BLet\'s see what I can see...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (603,'Ключ Ансарема','Маг, который владеет Камнем, может умножить его силу при помощи некой точки фокуса... вроде алтаря. Чтобы не допустить этого, необходим предмет равной силы.$B$BКак ни странно, я знаю одну очень подходящую вещь: древний кинжал, еще одну из тролльских реликвий. Только есть... небольшая проблема.$B$BЯ нашел этот кинжал, странствуя по Тернистой долине, и отдал его своей своевольной дочери, которая сбежала в Пиратскую Бухту и стала пираткой.','Поговорите с Кателиной в Пиратской Бухте.','Поговорите с Кателиной в Пиратской Бухте, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключ Ансарема',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Маг, который владеет Камнем, может умножить его силу при помощи некой точки фокуса... вроде алтаря. Чтобы не допустить этого, необходим предмет равной силы.$B$BКак ни странно, я знаю одну очень подходящую вещь: древний кинжал, еще одну из тролльских реликвий. Только есть... небольшая проблема.$B$BЯ нашел этот кинжал, странствуя по Тернистой долине, и отдал его своей своевольной дочери, которая сбежала в Пиратскую Бухту и стала пираткой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кателиной в Пиратской Бухте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Кателиной в Пиратской Бухте, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (604,'Пираты Кровавого Паруса','Кразз высоко ценит твою преданность Разбойникам Черноводья. Я доверяю тебе задание, очень важное для нашего флота.$B$BПроникни на так называемый южный командный пост, который пираты Кровавого Паруса основали на Диком взморье. Разграбь весь лагерь и принеси мне их карты и записи приказов. Так мы выясним, что замышляют эти ублюдки.','Командир флота Морской Рог из Пиратской Бухты попросил вас убить 10 сорвиголов из шайки Кровавого Паруса и принести ему карты и приказы Кровавого Паруса.','Вернитесь к командиру флота Морскому Рогу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пираты Кровавого Паруса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кразз высоко ценит твою преданность Разбойникам Черноводья. Я доверяю тебе задание, очень важное для нашего флота.$B$BПроникни на так называемый южный командный пост, который пираты Кровавого Паруса основали на Диком взморье. Разграбь весь лагерь и принеси мне их карты и записи приказов. Так мы выясним, что замышляют эти ублюдки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир флота Морской Рог из Пиратской Бухты попросил вас убить 10 сорвиголов из шайки Кровавого Паруса и принести ему карты и приказы Кровавого Паруса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру флота Морскому Рогу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (605,'Осколки Поющих кристаллов','Поющие кристаллы добывают только в Тернистой долине, и некоторые покупатели готовы немало за них отсыпать. Кому их толкнуть, мне ясно, но проклятая Торговая Компания не дает собирать кристаллы честным предпринимателям вроде меня.$B$BЯ хочу тебя нанять.$B$BВасилиски Тернистой долины питаются этими кристаллами. Благодаря им у них прочная шкура, и иногда из нее можно добыть качественные кристаллы.$B$BГодится шкура любого василиска, но на северном побережье, южнее Зул\'Кунды, они не такие свирепые.','Принесите Шиззи Пуззыриксу 10 осколков Поющих кристаллов.','Вернитесь к Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осколки Поющих кристаллов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поющие кристаллы добывают только в Тернистой долине, и некоторые покупатели готовы немало за них отсыпать. Кому их толкнуть, мне ясно, но проклятая Торговая Компания не дает собирать кристаллы честным предпринимателям вроде меня.$B$BЯ хочу тебя нанять.$B$BВасилиски Тернистой долины питаются этими кристаллами. Благодаря им у них прочная шкура, и иногда из нее можно добыть качественные кристаллы.$B$BГодится шкура любого василиска, но на северном побережье, южнее Зул\'Кунды, они не такие свирепые.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Шиззи Пуззыриксу 10 осколков Поющих кристаллов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (606,'Напугать Трусишку','Вот кого я терпеть не могу, так это тех, кто не отдает карточные долги! Мне задолжали несколько партнеров по игре. Не поможешь собрать с них мзду?$B$BВо-первых, есть Филипп "Трусишка", который вечно торчит у причала. Он проиграл мне кругленькую сумму на прошлой неделе, и я хочу ее получить! Только для этого надо его хорошенько припугнуть.$B$BСтупай, поохоться на старых горилл Мглистой долины. Набери из них потрохов и отнеси Трусишке. Только не говори, что они обезьяньи, пусть в штаны со страху наложит!','Отнесите 5 потрохов горилл Мглистой долины Филиппу "Трусишке" в Пиратскую Бухту.','Ой! Это у тебя откуда? Нет, не рассказывай. Не хочу ничего знать!$B$BТебя кто прислал? Морской волк?','Эй, ты чего?! Как-то ты нехорошо смотришь, господин хороший.','Вернитесь к Филиппу "Трусишке" в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Напугать Трусишку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот кого я терпеть не могу, так это тех, кто не отдает карточные долги! Мне задолжали несколько партнеров по игре. Не поможешь собрать с них мзду?$B$BВо-первых, есть Филипп "Трусишка", который вечно торчит у причала. Он проиграл мне кругленькую сумму на прошлой неделе, и я хочу ее получить! Только для этого надо его хорошенько припугнуть.$B$BСтупай, поохоться на старых горилл Мглистой долины. Набери из них потрохов и отнеси Трусишке. Только не говори, что они обезьяньи, пусть в штаны со страху наложит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 5 потрохов горилл Мглистой долины Филиппу "Трусишке" в Пиратскую Бухту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой! Это у тебя откуда? Нет, не рассказывай. Не хочу ничего знать!$B$BТебя кто прислал? Морской волк?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эй, ты чего?! Как-то ты нехорошо смотришь, господин хороший.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Филиппу "Трусишке" в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (607,'Возвращение к Маккинли','Вот, возьмите этот кошель и отнесите его Морскому Волку. И передайте, что я собирался ему заплатить! Клянусь!!!$B$BЯ всего лишь немного перебрал и заблудился по пути, и... знаете, как бывает. Он поймет – не нужно применять силу!','Отнесите плату Трусишки "Морскому волку" Маккинли в Пиратской бухте.','Хе-хе, молодчина! А когда ты эти потроха ему показал, Трусишка небось в панику ударился?$B$BХа! У него все на лице написано. С ним в карты играть – все равно что жульничать!$B$BСпасибо за помощь, $n. А вот и твоя награда...','Так-так, $n. Принес Трусишкин должок?','Поговорите с "Морским волком" Маккинли в Пиратской Бухте, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Маккинли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, возьмите этот кошель и отнесите его Морскому Волку. И передайте, что я собирался ему заплатить! Клянусь!!!$B$BЯ всего лишь немного перебрал и заблудился по пути, и... знаете, как бывает. Он поймет – не нужно применять силу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите плату Трусишки "Морскому волку" Маккинли в Пиратской бухте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хе-хе, молодчина! А когда ты эти потроха ему показал, Трусишка небось в панику ударился?$B$BХа! У него все на лице написано. С ним в карты играть – все равно что жульничать!$B$BСпасибо за помощь, $n. А вот и твоя награда...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так-так, $n. Принес Трусишкин должок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с "Морским волком" Маккинли в Пиратской Бухте, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (608,'Пираты Кровавого Паруса','Ну и наглец этот Фираллон! Он бы и Озеро Хрустальное на лодке не переплыл, куда ему вести против нас весь свой флот!$B$BПираты Кровавого Паруса поплатятся за свою беспечность. Теперь мы знаем все их планы и нападем первыми.$B$BХотя зачем посылать целый флот, если хватит отряда отважных искателей приключений? $n, возьми с собой самых опытных бойцов, ступай на место высадки Фираллона и лиши пиратов Кровавого Паруса всех командиров. Весь флот отправится на дно следом за ними...','Командир флота Морской Рог из Пиратской Бухты попросил вас убить капитана Штиллеца, капитана Кильвателя и командира флота Фираллона.','Вернитесь к командиру флота Морскому Рогу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пираты Кровавого Паруса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну и наглец этот Фираллон! Он бы и Озеро Хрустальное на лодке не переплыл, куда ему вести против нас весь свой флот!$B$BПираты Кровавого Паруса поплатятся за свою беспечность. Теперь мы знаем все их планы и нападем первыми.$B$BХотя зачем посылать целый флот, если хватит отряда отважных искателей приключений? $n, возьми с собой самых опытных бойцов, ступай на место высадки Фираллона и лиши пиратов Кровавого Паруса всех командиров. Весь флот отправится на дно следом за ними...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир флота Морской Рог из Пиратской Бухты попросил вас убить капитана Штиллеца, капитана Кильвателя и командира флота Фираллона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру флота Морскому Рогу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (609,'Должники вуду','Список сокращается, но должники все еще остались.$B$BДалее идут Моури "Деревянная Нога" Вилкинс, Джон-Джон Ворон и Чаки "Недотепа".$B$BЭти паршивые собаки просрочили платежи на много месяцев, я-то думал, они поэтому из города сбежали! Потом, правда, мне сказали, что их прокляли и заколдовали, и они бродят по развалинам в джунглях. Но меня их судьба не волнует – мне бы свое вернуть!$B$BИх видели на северо-востоке отсюда, в руинах Абораза и руинах Жубуваля. Отыщи их и забери у них мои вещи.','Принесите деревянную ногу Моури, золотую подзорную трубу Джон-Джона и огромное кольцо Чаки "Морскому волку" Маккинли в Пиратскую Бухту.','Вернитесь к "Морскому волку" Маккинли в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Должники вуду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Список сокращается, но должники все еще остались.$B$BДалее идут Моури "Деревянная Нога" Вилкинс, Джон-Джон Ворон и Чаки "Недотепа".$B$BЭти паршивые собаки просрочили платежи на много месяцев, я-то думал, они поэтому из города сбежали! Потом, правда, мне сказали, что их прокляли и заколдовали, и они бродят по развалинам в джунглях. Но меня их судьба не волнует – мне бы свое вернуть!$B$BИх видели на северо-востоке отсюда, в руинах Абораза и руинах Жубуваля. Отыщи их и забери у них мои вещи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите деревянную ногу Моури, золотую подзорную трубу Джон-Джона и огромное кольцо Чаки "Морскому волку" Маккинли в Пиратскую Бухту.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к "Морскому волку" Маккинли в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (610,'"Красавчик" Дункан','Так тебя прислал мой ОТЕЦ? Я думала, старик давно махнул на меня рукой.$B$BЭто он виноват, что я сбежала. С чего он взял, что я только и мечтаю о скучной жизни среди заплесневелых книг и седых, горбатых и надутых магов!$B$BЕсли тебе нужен мой кинжал, можешь отобрать его у "Красавчика" Дункана, одного из пиратов Кровавого Паруса. Я думаю, что почувствовав металл между лопаток, Дункан охотно расстанется с кинжалом.','Отберите кинжал Кателины у "Красавчика" Дункана.','Вернитесь к Кателине Клинку в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Красавчик" Дункан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так тебя прислал мой ОТЕЦ? Я думала, старик давно махнул на меня рукой.$B$BЭто он виноват, что я сбежала. С чего он взял, что я только и мечтаю о скучной жизни среди заплесневелых книг и седых, горбатых и надутых магов!$B$BЕсли тебе нужен мой кинжал, можешь отобрать его у "Красавчика" Дункана, одного из пиратов Кровавого Паруса. Я думаю, что почувствовав металл между лопаток, Дункан охотно расстанется с кинжалом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите кинжал Кателины у "Красавчика" Дункана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кателине Клинку в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (611,'Проклятье приливов','Значит, ты ищешь какой-то алтарь? Я не так хорошо разбираюсь в развалинах, как мой отец, но мне приходилось слышать о затонувшем городе троллей рядом с островом, про который ты $gспрашивал:спрашивала;. Посмотри там.$B$BТы $gвернул:вернула; мне нож, поэтому можешь пока им воспользоваться... но не забудь принести его обратно, когда закончишь дела!','Уничтожьте Алтарь Приливов при помощи меча Кателины, убейте Газбана и принесите Камень Приливов и меч Кателины барону Ревилгазу.','Вернитесь к барону Ревилгазу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятье приливов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, ты ищешь какой-то алтарь? Я не так хорошо разбираюсь в развалинах, как мой отец, но мне приходилось слышать о затонувшем городе троллей рядом с островом, про который ты $gспрашивал:спрашивала;. Посмотри там.$B$BТы $gвернул:вернула; мне нож, поэтому можешь пока им воспользоваться... но не забудь принести его обратно, когда закончишь дела!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Алтарь Приливов при помощи меча Кателины, убейте Газбана и принесите Камень Приливов и меч Кателины барону Ревилгазу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (612,'<UNUSED>','It\'s a long shot, but perhaps you could try to convince Catelyn to part with her dagger? The heart of a collector, you know how it is?$b$bPerhaps if you mention that it\'s for me, she might be more well-disposed to sell it to me.','Return Catelyn\'s blade.','Вернитесь к Кателине Клинку в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','It\'s a long shot, but perhaps you could try to convince Catelyn to part with her dagger? The heart of a collector, you know how it is?$b$bPerhaps if you mention that it\'s for me, she might be more well-disposed to sell it to me.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Return Catelyn\'s blade.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кателине Клинку в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (613,'Вскрыть ногу Моури','Проклятье! Этот Моури поставил на свою ногу замок, и я не могу ее открыть! Его сокровища внутри, и именно их он мне должен!$B$BМне необходим ключ, чтобы вскрыть этот замок. Моури нередко играл в кости с ограми Мош\'Огг у них на холме на северо-востоке. Он успел рассказать мне, что ему пришлось спасаться бегством после прошлой игры, потому что больно много выиграл. Может быть, его ключ у огров.$b$bНо если так, придется убить целую толпу, чтобы его отыскать...','Принесите "Морскому Волку" Маккинли из Пиратской Бухты ключ Моури.','Вернитесь к "Морскому волку" Маккинли в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вскрыть ногу Моури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проклятье! Этот Моури поставил на свою ногу замок, и я не могу ее открыть! Его сокровища внутри, и именно их он мне должен!$B$BМне необходим ключ, чтобы вскрыть этот замок. Моури нередко играл в кости с ограми Мош\'Огг у них на холме на северо-востоке. Он успел рассказать мне, что ему пришлось спасаться бегством после прошлой игры, потому что больно много выиграл. Может быть, его ключ у огров.$b$bНо если так, придется убить целую толпу, чтобы его отыскать...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите "Морскому Волку" Маккинли из Пиратской Бухты ключ Моури.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к "Морскому волку" Маккинли в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (614,'Сундук капитана','Когда-то у меня был корабль, на котором я ходил до самого Кабестана в Калимдоре, и репутация у меня была безупречная.$B$BПока...$B$BПока не появились проклятые морские великаны! Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую Бухту. А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая. Наглец!$B$BГоворят, Горлаш бродит по берегу к востоку отсюда. Найди его и верни мой сундук! Благодарность моя не будет знать предела.','Верните Гекельберри Смоттсу из Пиратской Бухты его сундук.','Вернитесь к капитану Гекельбери Смоттсу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сундук капитана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда-то у меня был корабль, на котором я ходил до самого Кабестана в Калимдоре, и репутация у меня была безупречная.$B$BПока...$B$BПока не появились проклятые морские великаны! Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую Бухту. А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая. Наглец!$B$BГоворят, Горлаш бродит по берегу к востоку отсюда. Найди его и верни мой сундук! Благодарность моя не будет знать предела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Гекельберри Смоттсу из Пиратской Бухты его сундук.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гекельбери Смоттсу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (615,'Капитанская сабля','После того как эти проклятые великаны уничтожили мой корабль, я купил еще один. Назвал его "Месть Смоттса", запасся продовольствием, нанял команду и отправился в поисках этих злодеев. Найти-то я их нашел, но... они снова мне надавали по шее. "Месть Смоттса" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку.$B$BУ другого великана, Неголаша, моя сабля.$B$BСразись с Неголашем и принеси мне мою саблю!$B$BМожешь поговорить со Салагой, поваром с "Мести Смоттса", который выжил в последней битве. Он поможет тебе найти великана.','Поговорите с Салагой.','Привет, привет, $N. Капитан сказал мне, что ты будешь бороться с Неголашем, да?','Поговорите с Салагой в Пиратской Бухте, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Капитанская сабля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как эти проклятые великаны уничтожили мой корабль, я купил еще один. Назвал его "Месть Смоттса", запасся продовольствием, нанял команду и отправился в поисках этих злодеев. Найти-то я их нашел, но... они снова мне надавали по шее. "Месть Смоттса" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку.$B$BУ другого великана, Неголаша, моя сабля.$B$BСразись с Неголашем и принеси мне мою саблю!$B$BМожешь поговорить со Салагой, поваром с "Мести Смоттса", который выжил в последней битве. Он поможет тебе найти великана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Салагой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет, привет, $N. Капитан сказал мне, что ты будешь бороться с Неголашем, да?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Салагой в Пиратской Бухте, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (616,'Остров духов','Барон Ревилгаз велел мне не упускать слухов о странных событиях и местах в округе Пиратской Бухты и всей Тернистой долины. Обычно я не придаю большого значения историям про призраков и прочую чушь, но моряки в таверне говорили об острове элементалей недалеко от побережья. Мол, там духи Воды и сумасшедший призрак гоблина.$B$BЕсли тебе встретится Ревилгаз, перескажешь ему эту историю?','Поговорите с бароном Ревилгазом в Пиратской Бухте.','Интересно. Кажется, я недавно читал книгу, в которой говорилось о чем-то в этом духе…$B$BА, разумеется, легенды троллей. Если Кразек говорит правду, то вскоре к моей коллекции древних артефактов и реликвий добавится Камень Приливов.','Поговорите с бароном Ревилгазом в Пиратской Бухте, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остров духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Барон Ревилгаз велел мне не упускать слухов о странных событиях и местах в округе Пиратской Бухты и всей Тернистой долины. Обычно я не придаю большого значения историям про призраков и прочую чушь, но моряки в таверне говорили об острове элементалей недалеко от побережья. Мол, там духи Воды и сумасшедший призрак гоблина.$B$BЕсли тебе встретится Ревилгаз, перескажешь ему эту историю?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с бароном Ревилгазом в Пиратской Бухте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интересно. Кажется, я недавно читал книгу, в которой говорилось о чем-то в этом духе…$B$BА, разумеется, легенды троллей. Если Кразек говорит правду, то вскоре к моей коллекции древних артефактов и реликвий добавится Камень Приливов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с бароном Ревилгазом в Пиратской Бухте, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (617,'Вязанка акириса','Ищешь работу, $n? Если ты не боишься трудностей, могу тебе предложить одно дельце.$B$BУ меня есть дружбан, Гроу, который зашибает бешеные деньги, продавая то, что наги называют стеблями акириса. Это очень ценная морская водоросль. Он за нее отлично платит.$B$BПритащи мне 10 стеблей этой травки, и мы сторгуемся. Наги живут на берегу к северу отсюда.','Принесите каперу Блоудсу из Пиратской Бухты 10 вязанок акириса.','Вернитесь к каперу Блоудсу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вязанка акириса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ищешь работу, $n? Если ты не боишься трудностей, могу тебе предложить одно дельце.$B$BУ меня есть дружбан, Гроу, который зашибает бешеные деньги, продавая то, что наги называют стеблями акириса. Это очень ценная морская водоросль. Он за нее отлично платит.$B$BПритащи мне 10 стеблей этой травки, и мы сторгуемся. Наги живут на берегу к северу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите каперу Блоудсу из Пиратской Бухты 10 вязанок акириса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каперу Блоудсу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (618,'Бой с Неголашем','Неголаш – великан-обжора.$B$BКогда они уничтожили наш корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это мое коронное блюдо, рецепт я привез из самих Бесплодных земель!$B$BЕсли ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!','Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Смоттса.$B$BУбейте Неголаша и отнесите абордажную саблю Смоттса хозяину в Тернистую долину.','Ты $Gзабрал:забрала; саблю у Неголаша! Я не верил, что мне повезет, $N! Встретив тебя, моя удача вернулась, без сомнения!$B$BСпасибо! И если я когда-нибудь заполучу новый корабль, и ты захочешь прокатиться, то ты будешь на нем почетным гостем.','Ты $Gзаполучил:заполучила; мою саблю, $N?','Вернитесь к капитану Гекельбери Смоттсу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бой с Неголашем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неголаш – великан-обжора.$B$BКогда они уничтожили наш корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это мое коронное блюдо, рецепт я привез из самих Бесплодных земель!$B$BЕсли ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Смоттса.$B$BУбейте Неголаша и отнесите абордажную саблю Смоттса хозяину в Тернистую долину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gзабрал:забрала; саблю у Неголаша! Я не верил, что мне повезет, $N! Встретив тебя, моя удача вернулась, без сомнения!$B$BСпасибо! И если я когда-нибудь заполучу новый корабль, и ты захочешь прокатиться, то ты будешь на нем почетным гостем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gзаполучил:заполучила; мою саблю, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гекельбери Смоттсу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (619,'Приманка для Неголаша','Вы нагружаете лодку едой и выпивкой...','Это заброшенная спасательная шлюпка. На ее стороне потускневшими буквами написаны слова:$B$B"Месть Смоттса"','Вернитесь к разбитой спасательной шлюпке в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приманка для Неголаша',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы нагружаете лодку едой и выпивкой...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это заброшенная спасательная шлюпка. На ее стороне потускневшими буквами написаны слова:$B$B"Месть Смоттса"',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разбитой спасательной шлюпке в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (620,'Кушак с монограммой','Вдоль каймы кушака вышита монограмма "ГС".','Верните кушак с монограммой владельцу.','Привет. У тебя есть ко мне дело?','Разыщите владельца кушака с монограммой в Пиратской Бухте, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кушак с монограммой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вдоль каймы кушака вышита монограмма "ГС".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните кушак с монограммой владельцу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет. У тебя есть ко мне дело?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите владельца кушака с монограммой в Пиратской Бухте, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (621,'Тайна Занзила','Занзил Отверженный и его приспешники живут на руинах Жубуваля и Абораза на северо-востоке от Пиратской Бухты. Его изгнали из племени. Почему? Ну...$B$BЗанзил научился подчинять себе разум других, и его страшатся собственные командиры. Он заставляет своих приспешников принимать смесь из тропических растений, и она подавляет их волю и укрепляет тела.$B$BЭта смесь пригодилась бы любому, кто желает повелевать чужим разумом.$B$BПринеси мне образцы этой смеси, и уж я-то найду им применение.','Принесите Шиззи Пуззыриксу из Пиратской Бухты 12 образцов смеси Занзила.','Вернитесь к Шиззи Пуззыриксу на Пустынный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна Занзила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Занзил Отверженный и его приспешники живут на руинах Жубуваля и Абораза на северо-востоке от Пиратской Бухты. Его изгнали из племени. Почему? Ну...$B$BЗанзил научился подчинять себе разум других, и его страшатся собственные командиры. Он заставляет своих приспешников принимать смесь из тропических растений, и она подавляет их волю и укрепляет тела.$B$BЭта смесь пригодилась бы любому, кто желает повелевать чужим разумом.$B$BПринеси мне образцы этой смеси, и уж я-то найду им применение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Шиззи Пуззыриксу из Пиратской Бухты 12 образцов смеси Занзила.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шиззи Пуззыриксу на Пустынный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (622,'Возвращение к капралу Калебу','Пока тебя не было, я починил твой горшок и даже приделал к нему свисток. Больше того, смотри! На дне появился новый нож, который запросто рубит кости!$b$BДа-да, теперь этот горшок – настоящая радость повара! Не сомневаюсь, владелец будет доволен.','Отнесите целый горшок Кразека капралу Калебу в Лагерь Повстанцев.','Поговорите с капралом Калебом в Лагере Повстанцев, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к капралу Калебу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока тебя не было, я починил твой горшок и даже приделал к нему свисток. Больше того, смотри! На дне появился новый нож, который запросто рубит кости!$b$BДа-да, теперь этот горшок – настоящая радость повара! Не сомневаюсь, владелец будет доволен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите целый горшок Кразека капралу Калебу в Лагерь Повстанцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с капралом Калебом в Лагере Повстанцев, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (623,'Вязанка акириса','$n, раз уж ты здесь, я тебе вот что скажу. Пока тебя не было, я получил послание от Гроу. Его очень порадовала последняя поставка, и клиент немедленно захотел получить еще акириса.$B$BЯ собираюсь в Терамор не раньше, чем через неделю, но если ты не против двинуть в путь прямо сейчас, почему бы тебе не отвезти товар?$B$BИщешь приключений? Ты знаешь, где находятся Пылевые топи? Только будь $gосторожен:осторожна;, в Тераморе может быть опасно.','Принесите вязанку акириса каперу Грою в Терамор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вязанка акириса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, раз уж ты здесь, я тебе вот что скажу. Пока тебя не было, я получил послание от Гроу. Его очень порадовала последняя поставка, и клиент немедленно захотел получить еще акириса.$B$BЯ собираюсь в Терамор не раньше, чем через неделю, но если ты не против двинуть в путь прямо сейчас, почему бы тебе не отвезти товар?$B$BИщешь приключений? Ты знаешь, где находятся Пылевые топи? Только будь $gосторожен:осторожна;, в Тераморе может быть опасно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите вязанку акириса каперу Грою в Терамор.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (624,'Загадка Кортелло','Есть мост, изукрашен резьбою, красивый на нем узор$BК востоку от Мертвого Ветра и к югу от Красногорья$BПод ним тебя ждет подсказка ль, улика ль – как назовешь.$BИ будет на Болоте Печали лежать, пока не найдешь.','Разгадай загадку!','Намокший пергамент дает вам новую подсказку...','Ты скормил скоту все оскверненные кусочки? Погоди! А тому глупому человечишке, что сидит у них в клетке? Ему – нет, я надеюсь?\n\nУф! Было бы очень жаль!','Найдите улики в Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадка Кортелло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть мост, изукрашен резьбою, красивый на нем узор$BК востоку от Мертвого Ветра и к югу от Красногорья$BПод ним тебя ждет подсказка ль, улика ль – как назовешь.$BИ будет на Болоте Печали лежать, пока не найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разгадай загадку!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Намокший пергамент дает вам новую подсказку...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты скормил скоту все оскверненные кусочки? Погоди! А тому глупому человечишке, что сидит у них в клетке? Ему – нет, я надеюсь?\n\nУф! Было бы очень жаль!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите улики в Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (625,'Загадка Кортелло','Калимдор далекий ждет тебя давно,$BГде надеждам к сроку сбыться не дано.$BТы в Степях почуешь вкус пыли на губах,$BНу а в топях пылевых – лишь печаль и страх.$BНо на юго-запад путь тебя манит,$BМрак пещеры тайну для тебя хранит.','Разгадай загадку!','Найдите улики в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадка Кортелло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Калимдор далекий ждет тебя давно,$BГде надеждам к сроку сбыться не дано.$BТы в Степях почуешь вкус пыли на губах,$BНу а в топях пылевых – лишь печаль и страх.$BНо на юго-запад путь тебя манит,$BМрак пещеры тайну для тебя хранит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разгадай загадку!',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите улики в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (626,'Загадка Кортелло','Спеши же в славный Лордерон! Давно тебя он ждет.$BТам с мором, гибелью и тьмой сражается народ. $BПусть не страшит тебя война и битвы шум и гам – $BЗато задание свое исполнить сможешь там. $BВот берег Внутренних земель, где шумный водопад, $BТам, под водами его, тебя ждет дивный клад!','Разгадай загадку!','Найдите улики во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадка Кортелло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спеши же в славный Лордерон! Давно тебя он ждет.$BТам с мором, гибелью и тьмой сражается народ. $BПусть не страшит тебя война и битвы шум и гам – $BЗато задание свое исполнить сможешь там. $BВот берег Внутренних земель, где шумный водопад, $BТам, под водами его, тебя ждет дивный клад!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разгадай загадку!',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите улики во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (627,'Просьба Кразека','В Теснине Сухоусов – далеко на севере, на Нагорье Арати – есть пещера. Там добывают редкие полезные ископаемые – кровавые камни. Да, они там не лучшего качества, но даже самые плохие кровавые камни высоко ценятся... теми, кто знает что с ними делать.$B$BЯ – знаю.$B$BЯ починю твой разбитый горшок, но пока я работаю над ним, принеси мне образцы кровавого камня. Если ты принесешь их достаточно, я награжу тебя.$B$BАх, да, если ты не умеешь добывать полезные ископаемые... попроси кого-нибудь тебе помочь!','Принесите 4 партии бедной кровавой руды Кразеку в Пиратскую Бухту.','Вернитесь к Кразеку в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Кразека',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Теснине Сухоусов – далеко на севере, на Нагорье Арати – есть пещера. Там добывают редкие полезные ископаемые – кровавые камни. Да, они там не лучшего качества, но даже самые плохие кровавые камни высоко ценятся... теми, кто знает что с ними делать.$B$BЯ – знаю.$B$BЯ починю твой разбитый горшок, но пока я работаю над ним, принеси мне образцы кровавого камня. Если ты принесешь их достаточно, я награжу тебя.$B$BАх, да, если ты не умеешь добывать полезные ископаемые... попроси кого-нибудь тебе помочь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 партии бедной кровавой руды Кразеку в Пиратскую Бухту.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кразеку в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (628,'Эксельзиор','Подбой готов, осталось сделать верхний слой. На него идут только наилучшие шкуры взрослых кроколисков. Они крепче и представляют собой лучшую основу для узоров, которыми славится линия превосходных сапог.$B$BХотя найти эту ценную шкуру нелегко, мне подходит лишь шкура старого солоноводного кроколиска. Эти твари выходят лишь на защиту молоди, поэтому может понадобиться убить несколько молодых зверей, чтобы выманить нужного.','Принесите Дриззлику из Пиратской Бухты шкуру старого солоноводного кроколиска.','Вернитесь к Дриззлику в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эксельзиор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подбой готов, осталось сделать верхний слой. На него идут только наилучшие шкуры взрослых кроколисков. Они крепче и представляют собой лучшую основу для узоров, которыми славится линия превосходных сапог.$B$BХотя найти эту ценную шкуру нелегко, мне подходит лишь шкура старого солоноводного кроколиска. Эти твари выходят лишь на защиту молоди, поэтому может понадобиться убить несколько молодых зверей, чтобы выманить нужного.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Дриззлику из Пиратской Бухты шкуру старого солоноводного кроколиска.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дриззлику в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (629,'Коварный риф','Давным-давно вода затопила древний город троллей рядом с Гибельным берегом, что на северо-западе. Мы зовем это место Коварным рифом, потому что в развалинах поселились мурлоки, которые нападают на всех, кто осмелится приблизиться.$B$BСреди руин есть древняя табличка, повествующая о древнем герое троллей, Гри\'леке. Это сказание священно в племени Черного Копья, и хотя сама табличка слишком велика и ее не унесешь, я хочу получить хотя бы осколок, чтобы поместить его в святилище в нашем новом городе, Оргриммаре.','Принесите осколок таблички Кин\'вилаю в лагерь Гром\'гол.','Вернитесь к Кин\'вилаю в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коварный риф',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно вода затопила древний город троллей рядом с Гибельным берегом, что на северо-западе. Мы зовем это место Коварным рифом, потому что в развалинах поселились мурлоки, которые нападают на всех, кто осмелится приблизиться.$B$BСреди руин есть древняя табличка, повествующая о древнем герое троллей, Гри\'леке. Это сказание священно в племени Черного Копья, и хотя сама табличка слишком велика и ее не унесешь, я хочу получить хотя бы осколок, чтобы поместить его в святилище в нашем новом городе, Оргриммаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите осколок таблички Кин\'вилаю в лагерь Гром\'гол.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кин\'вилаю в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (630,'Послание в бутылке','$n, ты и те, кого ты сможешь позвать мне на помощь – моя последняя надежда. Меня держит в плену великий Король Мукла. Он повелевает зверями на этом острове, и они держат меня здесь помимо моей воли на этой цепи. Если ты сможешь убить моего мучителя и отыскать ключ к кандалам, я буду навеки у тебя в долгу.$B$BЯ часто слышу шаги Короля Муклы на юго-восточной стороне острова. Соблюдай осторожность, справиться с ним нелегко.','Убейте Короля Муклу, возвращайтесь с ключом к принцессе Пубе и освободите ее.','Вернитесь к принцессе Пубе на Остров Жагуаро, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание в бутылке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты и те, кого ты сможешь позвать мне на помощь – моя последняя надежда. Меня держит в плену великий Король Мукла. Он повелевает зверями на этом острове, и они держат меня здесь помимо моей воли на этой цепи. Если ты сможешь убить моего мучителя и отыскать ключ к кандалам, я буду навеки у тебя в долгу.$B$BЯ часто слышу шаги Короля Муклы на юго-восточной стороне острова. Соблюдай осторожность, справиться с ним нелегко.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Короля Муклу, возвращайтесь с ключом к принцессе Пубе и освободите ее.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцессе Пубе на Остров Жагуаро, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (631,'Мост Тандола','Я помню, как горы содрогнулись от ужаснейшего взрыва. Неслабо рвануло, скажу я тебе!$b$bНа мосту Тандола погибли лучшие из наших солдат. Длиннокос говорит, что дворфы Черного Железа еще заплатят нам за все до конца этой войны.$b$bНо сейчас у нас отчаянное положение, подкрепления все нет и нет. Длиннокос отправил Ржавого Засова на разведку к восточному мосту – посмотреть, можно ли защитить мост теми силами, которые сейчас у нас есть.$b$bПрошло уже несколько дней. Мы не можем отправить солдат на поиски – Дун Модр осажден...$b$bБыть может, ты согласишься поискать нашего разведчика?','Найдите Ржавого Засова для Рага Гармасона.','Вы натыкаетесь на труп дворфа. На шлеме отчетливо видна надпись: "Эбенезер Ржавый Засов".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мост Тандола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я помню, как горы содрогнулись от ужаснейшего взрыва. Неслабо рвануло, скажу я тебе!$b$bНа мосту Тандола погибли лучшие из наших солдат. Длиннокос говорит, что дворфы Черного Железа еще заплатят нам за все до конца этой войны.$b$bНо сейчас у нас отчаянное положение, подкрепления все нет и нет. Длиннокос отправил Ржавого Засова на разведку к восточному мосту – посмотреть, можно ли защитить мост теми силами, которые сейчас у нас есть.$b$bПрошло уже несколько дней. Мы не можем отправить солдат на поиски – Дун Модр осажден...$b$bБыть может, ты согласишься поискать нашего разведчика?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Ржавого Засова для Рага Гармасона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы натыкаетесь на труп дворфа. На шлеме отчетливо видна надпись: "Эбенезер Ржавый Засов".',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (632,'Мост Тандола','Кажется, бедняга Ржавый Засов попал в засаду дворфов Черного Железа. Возле его остывшего тела лежит клочок пергамента.$b$bРасскажите Рагу Гармасону о случившемся и передайте ему пергамент.','Принесите печальное известие Рагу Гармасону в Дун Модр в Болотину и отдайте ему пергамент, найденный возле трупа Ржавого Засова.','Какой ужас... Бедный, бедный Эбенезер.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мост Тандола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, бедняга Ржавый Засов попал в засаду дворфов Черного Железа. Возле его остывшего тела лежит клочок пергамента.$b$bРасскажите Рагу Гармасону о случившемся и передайте ему пергамент.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите печальное известие Рагу Гармасону в Дун Модр в Болотину и отдайте ему пергамент, найденный возле трупа Ржавого Засова.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой ужас... Бедный, бедный Эбенезер.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (633,'Мост Тандола','Во имя Света, только не это! Бедняга Ржавый Засов. Ты меня $Gопечалил:опечалила;, $n.$b$bНо его жертва будет не напрасной! В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал заложить взрывчатку под мостом Тандола на границе с Нагорьем Арати.$b$bЕсли ему удастся очередная диверсия, то мы лишимся поставок с севера! Взрыв нужно предотвратить. Сделай все возможное, чтобы спасти мост Тандола, и возвращайся ко мне.$b$bТы – наша единственная надежда.','Уничтожьте взрывчатку.','Мост спасен! Ты помог не только мне и королю Магни, но и всему народу Каз Модана!$B$BТеперь нужно продержаться до прибытия подкрепления...','Умоляю, избавься от проклятой взрывчатки, пока не поздно!','Вернитесь к Рагу Гармасону в Дун Модр, что в Болотине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мост Тандола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во имя Света, только не это! Бедняга Ржавый Засов. Ты меня $Gопечалил:опечалила;, $n.$b$bНо его жертва будет не напрасной! В пергаменте сказано, что Кам Гневливый – тот, кто организовал нападение, – приказал заложить взрывчатку под мостом Тандола на границе с Нагорьем Арати.$b$bЕсли ему удастся очередная диверсия, то мы лишимся поставок с севера! Взрыв нужно предотвратить. Сделай все возможное, чтобы спасти мост Тандола, и возвращайся ко мне.$b$bТы – наша единственная надежда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте взрывчатку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мост спасен! Ты помог не только мне и королю Магни, но и всему народу Каз Модана!$B$BТеперь нужно продержаться до прибытия подкрепления...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Умоляю, избавься от проклятой взрывчатки, пока не поздно!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рагу Гармасону в Дун Модр, что в Болотине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (634,'Просьба о помощи','Я попрошу тебя о еще одном одолжении, |3-6($c). Мы ожидаем подкрепление из Стальгорна. Рогго принес сведения о лагере воинов Альянса к северу отсюда. Они расположились на Нагорье Арати, возле Опорного пункта.$b$bОтправься туда и отыщи капитана Ниалс. Спроси у очаровательного капитана, не выделит ли Альянс нам отряд солдат, чтобы помочь отбить Дун Модр и мост Тандола.','Найдите капитана Ниалс в Опорном пункте на Нагорье Арати.','Передай мои соболезнования Длинной Косе и его солдатам. Я искренне опечален вестью о трагедии на мосту Тандола и падении Дун Модра...$B$BНо знайте, что и Стромгард пал! Именно поэтому мы сейчас стоим у Опорного пункта. Впереди – битва за наш великий город.$B$BДолг и честь не позволяют мне покинуть нагорье до тех пор, пока над Стромгардом не взовьется гордое знамя нашего короля! Придется Длинной Косе обходиться своими силами...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба о помощи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я попрошу тебя о еще одном одолжении, |3-6($c). Мы ожидаем подкрепление из Стальгорна. Рогго принес сведения о лагере воинов Альянса к северу отсюда. Они расположились на Нагорье Арати, возле Опорного пункта.$b$bОтправься туда и отыщи капитана Ниалс. Спроси у очаровательного капитана, не выделит ли Альянс нам отряд солдат, чтобы помочь отбить Дун Модр и мост Тандола.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите капитана Ниалс в Опорном пункте на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Передай мои соболезнования Длинной Косе и его солдатам. Я искренне опечален вестью о трагедии на мосту Тандола и падении Дун Модра...$B$BНо знайте, что и Стромгард пал! Именно поэтому мы сейчас стоим у Опорного пункта. Впереди – битва за наш великий город.$B$BДолг и честь не позволяют мне покинуть нагорье до тех пор, пока над Стромгардом не взовьется гордое знамя нашего короля! Придется Длинной Косе обходиться своими силами...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (635,'Горный кристалл','Осколок пульсирует у вас в руках...$B$bВам кажется, что он молит о чем-то, пытается передать послание того, кто нуждается в вашей помощи.$b$bВам является видение – в северных горах Арати из земли торчит сияющий кристалл.$b$bВас так и тянет к этому месту.','Найдите кристалл из видения.','Кристалл пульсирует, будто в него заключена живая сила.','Дай мне ключ, |3-6($C), и я сам отомкну замок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горный кристалл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осколок пульсирует у вас в руках...$B$bВам кажется, что он молит о чем-то, пытается передать послание того, кто нуждается в вашей помощи.$b$bВам является видение – в северных горах Арати из земли торчит сияющий кристалл.$b$bВас так и тянет к этому месту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите кристалл из видения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кристалл пульсирует, будто в него заключена живая сила.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дай мне ключ, |3-6($C), и я сам отомкну замок.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (636,'Легенды Земли <NYI>','В книге идет речь о принцессе элементалей, Мизраэль, и ее заточении глубоко под Нагорьем Арати.$b$bТам же говорится о тайной россыпи кристаллов на нагорье. Эти кристаллы Мизраэль – окна в темницу принцессы.$b$bЕсли отважная душа отыщет эти осколки, быть может, $gон:она; сможет поговорить с Мизраэль...','Найдите кристаллы Мизраэль.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легенды Земли <NYI>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В книге идет речь о принцессе элементалей, Мизраэль, и ее заточении глубоко под Нагорьем Арати.$b$bТам же говорится о тайной россыпи кристаллов на нагорье. Эти кристаллы Мизраэль – окна в темницу принцессы.$b$bЕсли отважная душа отыщет эти осколки, быть может, $gон:она; сможет поговорить с Мизраэль...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите кристаллы Мизраэль.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (637,'Письмо Салли Баллу','Промокший и потрепанный конверт разваливается в руках, и в ладонях остается письмо на нескольких страницах. Каждая буковка выведена с удивительной аккуратностью.$b$bПисьмо адресовано некой миссис Саре Балу из Стальгорна. Оно начинается: "Дорогая Сара..."','Отнесите письмо Салли Балу Саре Балу.','Неужели ты $Gвидел:видела; моего Салли подо льдом? Прошу, скажи, что это не так!$B$BДай-ка я прочитаю, что он написал...','Похоже, на твою долю выпало немало странствий и нелегких битв, $C. Да, лихие настали времена. Что нового творится в мире?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Письмо Салли Баллу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Промокший и потрепанный конверт разваливается в руках, и в ладонях остается письмо на нескольких страницах. Каждая буковка выведена с удивительной аккуратностью.$b$bПисьмо адресовано некой миссис Саре Балу из Стальгорна. Оно начинается: "Дорогая Сара..."',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо Салли Балу Саре Балу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неужели ты $Gвидел:видела; моего Салли подо льдом? Прошу, скажи, что это не так!$B$BДай-ка я прочитаю, что он написал...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, на твою долю выпало немало странствий и нелегких битв, $C. Да, лихие настали времена. Что нового творится в мире?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (638,'Троллебой','Торас Троллебой мертв, а Стромгард разрушен. Вол\'джин велел мне приложить все усилия, чтобы вырвать легендарный меч Трол\'калар из рук людей. Тогда мы сможем воспользоваться им в грядущих битвах с троллями Зул\'Гуруба.$b$bЗенгу, один из наших опытных охотников, отправился в Павший Молот в северо-восточной части Нагорья Арати, чтобы проследить за этим.','Отправляйтесь в Павший Молот и поговорите с Зенгу.','Как дела, $C? Вол\'джин дал нам непростое задание, и если ты хочешь предложить свою помощь, мы с радостью ее примем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Троллебой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Торас Троллебой мертв, а Стромгард разрушен. Вол\'джин велел мне приложить все усилия, чтобы вырвать легендарный меч Трол\'калар из рук людей. Тогда мы сможем воспользоваться им в грядущих битвах с троллями Зул\'Гуруба.$b$bЗенгу, один из наших опытных охотников, отправился в Павший Молот в северо-восточной части Нагорья Арати, чтобы проследить за этим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Павший Молот и поговорите с Зенгу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как дела, $C? Вол\'джин дал нам непростое задание, и если ты хочешь предложить свою помощь, мы с радостью ее примем.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (639,'Печать Cтрома','В древние времена тролли воевали с Араторской империей и нашим самым могучим противником, лордом Игнеусом Стромским по прозвищу Троллебой. Он бросался в бой с мечом Трол\'каларом в руке – "убийцей троллей", на их древнем наречии.$B$BНо теперь сыновья Троллебоя ослабели, а цитадель их разрушена.$B$BМеч защищен несколькими печатями, которые были распределены между выжившими защитниками Стромгарда, и мы должны их отыскать.$B$BПервую из печатей захватил Синдикат, должно быть, она находится у одного из их людей в Стромгарде.','Добудьте печать Строма для Зенгу в Павшем Молоте.','Отлично, дружище. Это хорошее начало для сбора всех печатей, которые нам понадобятся, чтобы извлечь Трол\'калар из могилы Троллебоя.','Вы еще не выяснили местонахождение первой печати? Скорее всего, она находится у кого-то из посланников Синдиката в Стромгарде.','Вернитесь к Зенгу в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Cтрома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В древние времена тролли воевали с Араторской империей и нашим самым могучим противником, лордом Игнеусом Стромским по прозвищу Троллебой. Он бросался в бой с мечом Трол\'каларом в руке – "убийцей троллей", на их древнем наречии.$B$BНо теперь сыновья Троллебоя ослабели, а цитадель их разрушена.$B$BМеч защищен несколькими печатями, которые были распределены между выжившими защитниками Стромгарда, и мы должны их отыскать.$B$BПервую из печатей захватил Синдикат, должно быть, она находится у одного из их людей в Стромгарде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте печать Строма для Зенгу в Павшем Молоте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, дружище. Это хорошее начало для сбора всех печатей, которые нам понадобятся, чтобы извлечь Трол\'калар из могилы Троллебоя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы еще не выяснили местонахождение первой печати? Скорее всего, она находится у кого-то из посланников Синдиката в Стромгарде.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зенгу в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (640,'Сломанная печать','Могила Тораса Троллебоя защищена тремя печатями, первую из которых вы уже раздобыли у Синдиката. Остальные две достать будет сложнее, поскольку ими владеет гораздо более сильное ополчение Стромгарда.$B$BПечать Торадина была разделена на одиннадцать частей сыном Тораса Галеном, а потом он распределил эти фрагменты между стромгардскими защитниками Соберите фрагменты и принесите их Тор\'гану, троллю-шаману, – он сможет восстановить целостность печати.','Добудьте у защитников Стромгарда 5 фрагментов печати, принесите их Тор\'гану в Павший Молот.','А, так вам нужно воссоздать печать! Это будет не слишком сложно... все фрагменты на месте, а магическую структуру будет легко преобразовать.\n\nПожалуй, вам бы лучше закрыть глаза.','Тром\'ка, |3-6($C). Зенгу сообщил, что вам нужна моя помощь.','Вернитесь к Тор\'гану в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сломанная печать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Могила Тораса Троллебоя защищена тремя печатями, первую из которых вы уже раздобыли у Синдиката. Остальные две достать будет сложнее, поскольку ими владеет гораздо более сильное ополчение Стромгарда.$B$BПечать Торадина была разделена на одиннадцать частей сыном Тораса Галеном, а потом он распределил эти фрагменты между стромгардскими защитниками Соберите фрагменты и принесите их Тор\'гану, троллю-шаману, – он сможет восстановить целостность печати.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте у защитников Стромгарда 5 фрагментов печати, принесите их Тор\'гану в Павший Молот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, так вам нужно воссоздать печать! Это будет не слишком сложно... все фрагменты на месте, а магическую структуру будет легко преобразовать.\n\nПожалуй, вам бы лучше закрыть глаза.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тром\'ка, |3-6($C). Зенгу сообщил, что вам нужна моя помощь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тор\'гану в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (641,'Печать Торадина','Восстановление прошло без сучка и задоринки. Теперь печать можно использовать, чтобы отпереть могилу Троллебоя. Верните печать Зенгу. Несомненно, у него найдутся еще для вас задания.','Принесите восстановленную печать Торадина Зенгу в Павший Молот.','Мы на полпути к тому, чтобы извлечь Трол\'калар из могилы Троллебоя. Мы не вполне уверены в том, где находится третья печать, поскольку владеющие ею, похоже, много передвигаются по нагорью Арати. Но я верю, что вам удастся ее отыскать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Торадина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Восстановление прошло без сучка и задоринки. Теперь печать можно использовать, чтобы отпереть могилу Троллебоя. Верните печать Зенгу. Несомненно, у него найдутся еще для вас задания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите восстановленную печать Торадина Зенгу в Павший Молот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы на полпути к тому, чтобы извлечь Трол\'калар из могилы Троллебоя. Мы не вполне уверены в том, где находится третья печать, поскольку владеющие ею, похоже, много передвигаются по нагорью Арати. Но я верю, что вам удастся ее отыскать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (642,'Плененная принцесса','Меня зовут Мизраэль. Я принцесса духов земли, и мои пленители – великаны – поймали меня в ловушку глубоко под Нагорьем Арати. С миром на поверхности я могу говорить только при помощи этих кристаллов.$B$BПожалуйста, помоги мне. У союзников гигантов – кобольдов из племени Сухоусов – есть такие же кристаллы, они находятся в Теснине Сухоусов, к востоку отсюда. Чтобы объединить их силу, нужно отобрать у кобольдов частицы Мизраэль.$B$BПрошу тебя, $n, помоги мне!','Соберите 12 частиц Мизраэль и принесите их к радужным осколкам в Теснине Сухоусов.','Ах, тебе удалось активировать те кристаллы. Я уже чувствую, что начинаю приходить в себя!\n\nНо, увы, до свободы еще далеко...','Эта группа кристаллов выглядит очень похожей на кристаллы Мизраэли. Однако они не излучают такое же чувство надежности и безопасности.','Разыщите радужные осколки в Теснине Сухоусов, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плененная принцесса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня зовут Мизраэль. Я принцесса духов земли, и мои пленители – великаны – поймали меня в ловушку глубоко под Нагорьем Арати. С миром на поверхности я могу говорить только при помощи этих кристаллов.$B$BПожалуйста, помоги мне. У союзников гигантов – кобольдов из племени Сухоусов – есть такие же кристаллы, они находятся в Теснине Сухоусов, к востоку отсюда. Чтобы объединить их силу, нужно отобрать у кобольдов частицы Мизраэль.$B$BПрошу тебя, $n, помоги мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 частиц Мизраэль и принесите их к радужным осколкам в Теснине Сухоусов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, тебе удалось активировать те кристаллы. Я уже чувствую, что начинаю приходить в себя!\n\nНо, увы, до свободы еще далеко...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эта группа кристаллов выглядит очень похожей на кристаллы Мизраэли. Однако они не излучают такое же чувство надежности и безопасности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите радужные осколки в Теснине Сухоусов, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (643,'Печать Аратора','Хотя принц едва ли может похвастаться властью над Стромгардом, не говоря уж обо всем Нагорье Арати, тем не менее он разъезжает с остатками своей кавалерии по всей области. Я не могу сказать, зачем он это делает, но кто поймет, как мыслят эти люди?$B$BКакова бы ни была причина, более важно то, что он отдал одну из своих печатей лейтенанту Храброгласу, командиру кавалерии. Найдите его и принесите мне эту печать.','Добудьте Печать Аратора и принесите ее Зенгу в Павший Молот.','Потеря командира кавалерийского отряда станет серьезным ударом для стромгардских защитников. К тому же – что еще лучше – это значит, что нам осталось найти лишь одну печать, чтобы заполучить себе Трол\'калар.','Вернитесь к Зенгу в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать Аратора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя принц едва ли может похвастаться властью над Стромгардом, не говоря уж обо всем Нагорье Арати, тем не менее он разъезжает с остатками своей кавалерии по всей области. Я не могу сказать, зачем он это делает, но кто поймет, как мыслят эти люди?$B$BКакова бы ни была причина, более важно то, что он отдал одну из своих печатей лейтенанту Храброгласу, командиру кавалерии. Найдите его и принесите мне эту печать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте Печать Аратора и принесите ее Зенгу в Павший Молот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потеря командира кавалерийского отряда станет серьезным ударом для стромгардских защитников. К тому же – что еще лучше – это значит, что нам осталось найти лишь одну печать, чтобы заполучить себе Трол\'калар.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зенгу в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (644,'Удачный денек, |3-6($C). Кровь рода Троллебоев больше не будет беспокоить мой народ, и печати, необходимые для извлечения Трол\'калара, теперь у нас в руках. Скоро, очень скоро мы ударим по ненавистным троллям Зул\'Гуруба.','Вернитесь к Зенгу в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Удачный денек, |3-6($C). Кровь рода Троллебоев больше не будет беспокоить мой народ, и печати, необходимые для извлечения Трол\'калара, теперь у нас в руках. Скоро, очень скоро мы ударим по ненавистным троллям Зул\'Гуруба.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зенгу в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (645,'Трол\'калар','Что это? Когда четыре печати оказались вместе, они соединились, образовав единую печать. Нет сомнений, что она сможет разбить охранные заклинания, наложенные на могилу Троллебоя.$B$BОстанки Троллебоя захоронены в святилище позади часовни в Стромгарде. Принесите же Трол\'калар.','Достаньте Трол\'калар из могилы Троллебоя в Стромгарде.','При совмещении линий на верхней стороне могилы Троллебоя с сияющими линиями печати Игнеуса вспышка света поглощает печать, и легендарный меч Трол\'калар освобождается из каменных объятий.','Углубления в камне на верхней стороне надгробия Троллебоя совпадают с сияющими линиями печати Игнеуса...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трол\'калар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что это? Когда четыре печати оказались вместе, они соединились, образовав единую печать. Нет сомнений, что она сможет разбить охранные заклинания, наложенные на могилу Троллебоя.$B$BОстанки Троллебоя захоронены в святилище позади часовни в Стромгарде. Принесите же Трол\'калар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте Трол\'калар из могилы Троллебоя в Стромгарде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','При совмещении линий на верхней стороне могилы Троллебоя с сияющими линиями печати Игнеуса вспышка света поглощает печать, и легендарный меч Трол\'калар освобождается из каменных объятий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Углубления в камне на верхней стороне надгробия Троллебоя совпадают с сияющими линиями печати Игнеуса...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (646,'Трол\'калар','Медленно угасает свет. Меч Трол\'калар, упрятанный в каменные ножны, освобожден.','Отнесите меч Трол\'калар Зенгу в Павший Молот.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трол\'калар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Медленно угасает свет. Меч Трол\'калар, упрятанный в каменные ножны, освобожден.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите меч Трол\'калар Зенгу в Павший Молот.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (647,'Самогон Маккрила','Ох, и хлебнул я вчера самогона! Узнай Длиннокос, что я отрубился на посту, он оторвал бы мне голову.$b$bБашка раскалывается, жуть. И в ушах гремит, будто осадные машины вокруг грохочут.$b$bОй-ой, а времени сколько! Я обещал мастеру-пивовару Бочкопузу из Южнобережья вернуть должок своим самогоном.$b$bА осталось до истечения срока действия долга всего 15 минут! Отнеси ему самогон, будь другом! И поскорее!','Отнесите самогон Маккрила мастеру-пивовару Бочкопузу в Южнобережье.','Ах, ничто не греет так, как глоток самогона Туманника Маккрила! А я-то думал, что этот паразит опять просрочит платеж. Спасибо, дружище! Огромное тебе спасибо!','Что хорошего скажешь, |3-6($r)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самогон Маккрила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, и хлебнул я вчера самогона! Узнай Длиннокос, что я отрубился на посту, он оторвал бы мне голову.$b$bБашка раскалывается, жуть. И в ушах гремит, будто осадные машины вокруг грохочут.$b$bОй-ой, а времени сколько! Я обещал мастеру-пивовару Бочкопузу из Южнобережья вернуть должок своим самогоном.$b$bА осталось до истечения срока действия долга всего 15 минут! Отнеси ему самогон, будь другом! И поскорее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите самогон Маккрила мастеру-пивовару Бочкопузу в Южнобережье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, ничто не греет так, как глоток самогона Туманника Маккрила! А я-то думал, что этот паразит опять просрочит платеж. Спасибо, дружище! Огромное тебе спасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что хорошего скажешь, |3-6($r)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (648,'Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (649,'За медовухой','Хочу я поручить тебе одно дельце. Если ты любишь добрую медовуху, как и я, оно тебе понравится. Медовуха!$b$bЭто напиток, балда!$b$bНа заброшенной заставе Орды хранится запас "Медовой зыби" Внутренних земель. Такого славного пойла нынче больше не делают! Один из этих балбесов, дружков Мальтона, знает туда дорогу. Сходи к нему, принеси бочонок медовухи и еще пару бутылок мне лично. Поговори с Мальтоном, он тебе все расскажет.','Поговорите с Мальтоном Дрофферсом в Оргриммаре.','А, это насчет медовухи, которая нужна папаше? Он собирается торговать ею в таверне. За настоящую "Медовую зыбь" можно выручить много денег... Я знаю того, кто может ее добыть. Он живет во Внутренних землях. Но вот какая штука: он того... эльф он. Высший.$B$BНо ты не бойся, он хороший высший эльф, он не из Альянса. То есть он хороший, как выпьет. А это дело он любит. Очень любит.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За медовухой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочу я поручить тебе одно дельце. Если ты любишь добрую медовуху, как и я, оно тебе понравится. Медовуха!$b$bЭто напиток, балда!$b$bНа заброшенной заставе Орды хранится запас "Медовой зыби" Внутренних земель. Такого славного пойла нынче больше не делают! Один из этих балбесов, дружков Мальтона, знает туда дорогу. Сходи к нему, принеси бочонок медовухи и еще пару бутылок мне лично. Поговори с Мальтоном, он тебе все расскажет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мальтоном Дрофферсом в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, это насчет медовухи, которая нужна папаше? Он собирается торговать ею в таверне. За настоящую "Медовую зыбь" можно выручить много денег... Я знаю того, кто может ее добыть. Он живет во Внутренних землях. Но вот какая штука: он того... эльф он. Высший.$B$BНо ты не бойся, он хороший высший эльф, он не из Альянса. То есть он хороший, как выпьет. А это дело он любит. Очень любит.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (650,'За медовухой','Отправляйся к эльфу по имени Гилверадин Ловчий Солнца. Он так разбирается в винах, что умеет по запаху определить не только сорт вина, но и какого оно урожая! Он может прислать медовуху. Шесть бутылок на продажу, две отцу... а может, и больше – он не откажется! В общем, забери медовуху и возвращайся сюда.$b$bГилверадин живет неподалеку от пристанища высших эльфов во Внутренних землях. С эльфами этими лучше не связываться, уж поверь мне!','Поговорите с Гилверадином Ловчим Солнца во Внутренних землях.','А, ты знаешь Мальтона? Он мой старинный собутыльник! Понимаешь, я нашел средство, преодолевающее все искусственные границы и условности. Это – выпивка! Если бы разумные существа выпивали, вместо того чтобы воевать, мир сделался бы куда лучше и чище.$B$BВпрочем, боюсь, ты здесь не затем, чтобы слушать лекции о благословенных свойствах алкоголя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За медовухой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отправляйся к эльфу по имени Гилверадин Ловчий Солнца. Он так разбирается в винах, что умеет по запаху определить не только сорт вина, но и какого оно урожая! Он может прислать медовуху. Шесть бутылок на продажу, две отцу... а может, и больше – он не откажется! В общем, забери медовуху и возвращайся сюда.$b$bГилверадин живет неподалеку от пристанища высших эльфов во Внутренних землях. С эльфами этими лучше не связываться, уж поверь мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гилверадином Ловчим Солнца во Внутренних землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, ты знаешь Мальтона? Он мой старинный собутыльник! Понимаешь, я нашел средство, преодолевающее все искусственные границы и условности. Это – выпивка! Если бы разумные существа выпивали, вместо того чтобы воевать, мир сделался бы куда лучше и чище.$B$BВпрочем, боюсь, ты здесь не затем, чтобы слушать лекции о благословенных свойствах алкоголя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (651,'Связывающие камни','Четыре связывающих камня разбросаны по Нагорью Арати. Эти камни пригвоздили меня к земле.$b$bЧтобы оковы исчезли, нужно снять замок с самого мощного из них – с Внутреннего связывающего камня. А чтобы это сделать, придется собрать ключи с остальных трех камней.$b$bЭти камни охраняют стражи, но если у тебя хватит ума – или удачи, – тебе удастся найти возможность их нейтрализовать.','Добудьте огненный ключ, резной ключ и громовой ключ с западного связывающего камня, восточного связывающего камня и внешнего связывающего камня.$b$bОтнесите ключи к внутреннему связывающему камню.','Перед вами внутренний связывающий камень. Это самый мощный из связывающих камней, и нужно открыть его, чтобы открылись замки остальных камней.','Отправляйтесь к внутреннему связывающему камню во Внутреннем Круге Обуздания, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связывающие камни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Четыре связывающих камня разбросаны по Нагорью Арати. Эти камни пригвоздили меня к земле.$b$bЧтобы оковы исчезли, нужно снять замок с самого мощного из них – с Внутреннего связывающего камня. А чтобы это сделать, придется собрать ключи с остальных трех камней.$b$bЭти камни охраняют стражи, но если у тебя хватит ума – или удачи, – тебе удастся найти возможность их нейтрализовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте огненный ключ, резной ключ и громовой ключ с западного связывающего камня, восточного связывающего камня и внешнего связывающего камня.$b$bОтнесите ключи к внутреннему связывающему камню.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Перед вами внутренний связывающий камень. Это самый мощный из связывающих камней, и нужно открыть его, чтобы открылись замки остальных камней.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отправляйтесь к внутреннему связывающему камню во Внутреннем Круге Обуздания, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (652,'Разбить краеугольный камень','Открыв замки связывающих камней, ты $gосвободил:освободила; меня от большей части моих оков, но кое-что еще удерживает меня. Это краеугольный камень, который ты видишь среди других камней круга. А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук.$b$bТы $gдолжен:должна; заполучить у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и использовать его для открытия краеугольного камня.$b$b$n, ты так много $gсделал:сделала;, чтобы мне помочь... Еще немножко... и моя благодарность потрясет все земные устои!','Найдите и убейте Фозрука. Принесите Жезл Порядка к краеугольному камню на Нагорье Арати.','Вы вставляете жезл в краеугольный камень. Земля под вами начинает дрожать...','Краеугольный камень заряжен сильнейшей геомантической энергией.','Вернитесь к Краеугольному камню у Внутреннего Круга Обуздания, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разбить краеугольный камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Открыв замки связывающих камней, ты $gосвободил:освободила; меня от большей части моих оков, но кое-что еще удерживает меня. Это краеугольный камень, который ты видишь среди других камней круга. А ключ от него держит при себе один из моих пленителей, каменный страж Фозрук.$b$bТы $gдолжен:должна; заполучить у Фозрука этот ключ, который каменные стражи называют Жезлом Порядка, и использовать его для открытия краеугольного камня.$b$b$n, ты так много $gсделал:сделала;, чтобы мне помочь... Еще немножко... и моя благодарность потрясет все земные устои!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и убейте Фозрука. Принесите Жезл Порядка к краеугольному камню на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы вставляете жезл в краеугольный камень. Земля под вами начинает дрожать...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Краеугольный камень заряжен сильнейшей геомантической энергией.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Краеугольному камню у Внутреннего Круга Обуздания, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (653,'Союзники Мизраэль','<Говорит Мизраэль.>$b$bСвободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы.$b$bНо в должный час я пойду против великанов, и они еще пожалеют о том, что отняли у меня свободу!$B$BВы $gблагородный союзник:благородная союзница;, $n. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность.$b$bПоговорите с Герриком Костохватом. Он обитает в Стальгорне, в Заброшенном гроте. Он знает, как меня можно призвать.','Поговорите с Герриком Костохватом в Заброшенном гроте в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союзники Мизраэль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Говорит Мизраэль.>$b$bСвободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы.$b$bНо в должный час я пойду против великанов, и они еще пожалеют о том, что отняли у меня свободу!$B$BВы $gблагородный союзник:благородная союзница;, $n. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность.$b$bПоговорите с Герриком Костохватом. Он обитает в Стальгорне, в Заброшенном гроте. Он знает, как меня можно призвать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Герриком Костохватом в Заброшенном гроте в Стальгорне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (654,'Полевые испытания в Танарисе','После подключения источника энергии набор для полевых испытаний начинает светиться и вибрировать. Похоже, он работает как надо.$b$bЯ позабочусь о доставке.$B$BВсе необходимые образцы ты можешь найти в пустыне Танарис.$B$BСобрав их, доложи о выполнении главному инженеру Чепухастеру.','Добудьте приемлемые образцы тканей 8 василисков, 8 гиен и 8 скорпионов. Отнесите набор для проведения испытаний главному инженеру Чепухастеру в Прибамбасск до окончания действия источника энергии.','Ну ладно, на удаление источника энергии мне понадобится пара секунд. После этого можешь делать все, что захочешь, не боясь потерять данные.','Ну что, все образцы $Gуспел:успела; собрать? Если не все, то помни, как только энергия закончится, все результаты пропадут и придется начать все с начала.$B$BЭй, не жди от меня сочувствия я думаю только об интересах Водной компании Прибамбасска, а если мне придется продавать источники энергии до возобновления поставок с ледяных ключей Дун Морога, то да будет так!','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полевые испытания в Танарисе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После подключения источника энергии набор для полевых испытаний начинает светиться и вибрировать. Похоже, он работает как надо.$b$bЯ позабочусь о доставке.$B$BВсе необходимые образцы ты можешь найти в пустыне Танарис.$B$BСобрав их, доложи о выполнении главному инженеру Чепухастеру.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте приемлемые образцы тканей 8 василисков, 8 гиен и 8 скорпионов. Отнесите набор для проведения испытаний главному инженеру Чепухастеру в Прибамбасск до окончания действия источника энергии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну ладно, на удаление источника энергии мне понадобится пара секунд. После этого можешь делать все, что захочешь, не боясь потерять данные.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, все образцы $Gуспел:успела; собрать? Если не все, то помни, как только энергия закончится, все результаты пропадут и придется начать все с начала.$B$BЭй, не жди от меня сочувствия я думаю только об интересах Водной компании Прибамбасска, а если мне придется продавать источники энергии до возобновления поставок с ледяных ключей Дун Морога, то да будет так!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (655,'Павший Молот','Воспоминания по-прежнему ярки, как будто все было вчера... Так много лет без надежды, прикованный к этой проклятой дыре деревом и сталью. И вот наконец появился вождь: Молот Рока блещет полуночными доспехами, высоко вздымает боевой молот...$B$BКак же это подло, как непереносимо, что удар труса мог сразить нашего величайшего героя. Враг наскочил сзади и пронзил его копьем... Я упал на колени. Какая могла быть надежда? Какая еще может быть надежда...','Поговорите с Тор\'ганом в Павшем Молоте.','А, вы говорите о Гор\'муле. Да, судя по вашим словам, похоже, он так и не оправился от смерти Молота Рока.\n\nГор\'муль был пленником здесь, когда Тралл и Оргрим вели битву за освобождение лагеря, но когда затряслась земля и наши братья сбежали, его оставили там. Лишенный малейшего проблеска надежды, он скитался, затерянный, в одиночестве, пока мы не вернулись сюда, чтобы вновь поселиться в Павшем Молоте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Павший Молот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воспоминания по-прежнему ярки, как будто все было вчера... Так много лет без надежды, прикованный к этой проклятой дыре деревом и сталью. И вот наконец появился вождь: Молот Рока блещет полуночными доспехами, высоко вздымает боевой молот...$B$BКак же это подло, как непереносимо, что удар труса мог сразить нашего величайшего героя. Враг наскочил сзади и пронзил его копьем... Я упал на колени. Какая могла быть надежда? Какая еще может быть надежда...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тор\'ганом в Павшем Молоте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, вы говорите о Гор\'муле. Да, судя по вашим словам, похоже, он так и не оправился от смерти Молота Рока.\n\nГор\'муль был пленником здесь, когда Тралл и Оргрим вели битву за освобождение лагеря, но когда затряслась земля и наши братья сбежали, его оставили там. Лишенный малейшего проблеска надежды, он скитался, затерянный, в одиночестве, пока мы не вернулись сюда, чтобы вновь поселиться в Павшем Молоте.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (656,'Призыв принцессы','Вы должны нанести поражение Мизраэль прежде, чем она обретет полную силу. Если вы этого не сделаете, то, как только она наберет достаточно сил, она кинется на своих пленителей! Есть такие, кто считает, что может ее контролировать, но если ее можно контролировать, с чего было великанам с самого начала заковывать ее в цепи?$B$BПотрясающая логика, да?$B$BЧтобы сразить Мизраэль, призовите ее у ее кристаллов, где вы в первый раз говорили с ней. Нанесите ей поражение и заберите ее мистические оковы, а потом подсоедините их к кристаллам Мизраэль.$B$BСделайте так – и она вновь будет поймана в ловушку.','Отправляйтесь к кристаллам Мизраэль, вызовите принцессу и победите ее.$B$BЗаберите ее мистические оковы и присоедините их к кристаллам.','Вернитесь к кристаллам Мизраэль во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв принцессы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы должны нанести поражение Мизраэль прежде, чем она обретет полную силу. Если вы этого не сделаете, то, как только она наберет достаточно сил, она кинется на своих пленителей! Есть такие, кто считает, что может ее контролировать, но если ее можно контролировать, с чего было великанам с самого начала заковывать ее в цепи?$B$BПотрясающая логика, да?$B$BЧтобы сразить Мизраэль, призовите ее у ее кристаллов, где вы в первый раз говорили с ней. Нанесите ей поражение и заберите ее мистические оковы, а потом подсоедините их к кристаллам Мизраэль.$B$BСделайте так – и она вновь будет поймана в ловушку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к кристаллам Мизраэль, вызовите принцессу и победите ее.$B$BЗаберите ее мистические оковы и присоедините их к кристаллам.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кристаллам Мизраэль во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (657,'Новая чума зарождается?','<Кви начинает просматривать папку.>$B$BЭто в самом деле интересно! Похоже, аптекарь Йорель проводил здесь, на ферме Го-Шека, какие-то смертельно опасные эксперименты. Я не знаю точно, какое это имеет отношение к Хилсбраду, но Фину не понравится, если мы проигнорируем такое дело.$B$BМы тут столкнулись с орками в ваше отсутствие, и теперь я не настолько хорошо себя чувствую, чтобы отправиться на помощь к Кинелори. Но если вы не против, проводите ее к ферме, где она собирается выкрасть результаты исследований, которые Йорель так и не отослал пока на Мельницу Таррен.','Поговорите с Кинелори на Ферме Го\'Шека, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая чума зарождается?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Кви начинает просматривать папку.>$B$BЭто в самом деле интересно! Похоже, аптекарь Йорель проводил здесь, на ферме Го-Шека, какие-то смертельно опасные эксперименты. Я не знаю точно, какое это имеет отношение к Хилсбраду, но Фину не понравится, если мы проигнорируем такое дело.$B$BМы тут столкнулись с орками в ваше отсутствие, и теперь я не настолько хорошо себя чувствую, чтобы отправиться на помощь к Кинелори. Но если вы не против, проводите ее к ферме, где она собирается выкрасть результаты исследований, которые Йорель так и не отослал пока на Мельницу Таррен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кинелори на Ферме Го\'Шека, что на Нагорье Арати.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (658,'Новая чума зарождается?','Так вас Фин послал узнать, как мы тут? Неудивительно – он слишком много беспокоится.$b$bМы уже много дней наблюдаем за этой фермой, и Кин уверяет, что недавно видела гонца, выходящего из вон того маленького домика с южной стороны.$b$bОна любительница поболтать, но я всегда доверяю ее ощущениям, когда мы бываем в опасных местах.$b$bА вы часом не следопыт, а? Мы думаем, что гонец может относить записки в деревню Мельница Таррен. Если бы мы могли заполучить эти документы, это пролило бы свет на события в Хилсбраде.','Найдите Отрекшегося-курьера и принесите обнаруженную у него запечатанную папку Кви близ фермы Го\'Шека.','Вернитесь к Кви на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая чума зарождается?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так вас Фин послал узнать, как мы тут? Неудивительно – он слишком много беспокоится.$b$bМы уже много дней наблюдаем за этой фермой, и Кин уверяет, что недавно видела гонца, выходящего из вон того маленького домика с южной стороны.$b$bОна любительница поболтать, но я всегда доверяю ее ощущениям, когда мы бываем в опасных местах.$b$bА вы часом не следопыт, а? Мы думаем, что гонец может относить записки в деревню Мельница Таррен. Если бы мы могли заполучить эти документы, это пролило бы свет на события в Хилсбраде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Отрекшегося-курьера и принесите обнаруженную у него запечатанную папку Кви близ фермы Го\'Шека.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кви на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (659,'Новая чума зарождается?','Приветствую, $n, приятно познакомиться. Я руковожу группой смельчаков, расследующих странные происшествия в этом районе.$b$bМоим родственникам в Хилсбраде недавно пришлось избавиться от своей собаки Стэнли, потому что животное таинственным образом выросло до невообразимых размеров и стало кидаться на каждого встречного.$b$bЯ уверен, что тут замешана нежить, и мы ищем доказательства.$b$bДве моих спутницы, Кви и Кинелори, отправились к ферме Го\'Шека, что находится на Нагорье Арати, и давно не подавали о себе вестей. Найдешь их? А то я начинаю беспокоиться.','Найдите Кви и Кинелори у фермы Го\'Шека на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая чума зарождается?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, $n, приятно познакомиться. Я руковожу группой смельчаков, расследующих странные происшествия в этом районе.$b$bМоим родственникам в Хилсбраде недавно пришлось избавиться от своей собаки Стэнли, потому что животное таинственным образом выросло до невообразимых размеров и стало кидаться на каждого встречного.$b$bЯ уверен, что тут замешана нежить, и мы ищем доказательства.$b$bДве моих спутницы, Кви и Кинелори, отправились к ферме Го\'Шека, что находится на Нагорье Арати, и давно не подавали о себе вестей. Найдешь их? А то я начинаю беспокоиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Кви и Кинелори у фермы Го\'Шека на Нагорье Арати.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (660,'Новая чума зарождается?','Ладно, $n. Если вы готовы, то и я тоже.$B$BПопробуем?','Защищайте Кинелори, пока она не вернется к Кви.','Защитите Кинелори.','Вернитесь к Кви на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая чума зарождается?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, $n. Если вы готовы, то и я тоже.$B$BПопробуем?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защищайте Кинелори, пока она не вернется к Кви.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите Кинелори.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кви на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (661,'Новая чума зарождается?','После ночной гулянки в таверне Кинелори выглядела похуже, чем сейчас. Видно, вы неплохо ее защищали.$B$BТо, что она принесла с фермы, должно как минимум дать Фину представление о том, что происходит здесь, в Арати. Для того чтобы удоствоериться, что после вашей атаки не последует ответного удара, мы здесь ненадолго задержимся. Вы не откажетесь отправиться обратно в Южнобережье и поговорить с Фином?','Найдите Фина Оделика в Южнобережье, что в Предгорье Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая чума зарождается?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После ночной гулянки в таверне Кинелори выглядела похуже, чем сейчас. Видно, вы неплохо ее защищали.$B$BТо, что она принесла с фермы, должно как минимум дать Фину представление о том, что происходит здесь, в Арати. Для того чтобы удоствоериться, что после вашей атаки не последует ответного удара, мы здесь ненадолго задержимся. Вы не откажетесь отправиться обратно в Южнобережье и поговорить с Фином?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Фина Оделика в Южнобережье, что в Предгорье Хилсбрада.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (662,'Поиски на глубине','О\'Брин повел корабли в бухту. Мы были уверены, что именно здесь будет найдено сокровище. "Вестник" причалил нормально, но когда "Девичья Блажь" и "Дух Серебряного бора" приблизились к берегу, вода начала быстро понижаться. Страннейшая вещь, я такого в жизни не видал!$B$BТе два корабля налетели на что-то... нечто вроде храма в рифе. Оба быстро затонули – это была настоящая трагедия.$b$bНужно найти судовые журналы и карты обоих кораблей, прежде чем мы отчалим. Мы не можем оставить эту информацию доступной для любопытных глаз!','Первый помощник Нилзликс хочет, чтобы вы достали карты и судовые журналы кораблей "Девичья Блажь" и "Дух Серебряного бора".','Вернитесь к первому помощнику Нилзликсу в Бухту Фальдира, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски на глубине',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О\'Брин повел корабли в бухту. Мы были уверены, что именно здесь будет найдено сокровище. "Вестник" причалил нормально, но когда "Девичья Блажь" и "Дух Серебряного бора" приблизились к берегу, вода начала быстро понижаться. Страннейшая вещь, я такого в жизни не видал!$B$BТе два корабля налетели на что-то... нечто вроде храма в рифе. Оба быстро затонули – это была настоящая трагедия.$b$bНужно найти судовые журналы и карты обоих кораблей, прежде чем мы отчалим. Мы не можем оставить эту информацию доступной для любопытных глаз!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Первый помощник Нилзликс хочет, чтобы вы достали карты и судовые журналы кораблей "Девичья Блажь" и "Дух Серебряного бора".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к первому помощнику Нилзликсу в Бухту Фальдира, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (663,'Эй, там!','Ой, кого видит Лоло! Это ж крошка-|3-6($c)! Лоло всегда начеку!$b$bДобро пожаловать в Бухту Фальдира. Капитан О\'Брин сказал, что мы задержимся тут лишь на несколько часов. Ровно настолько, сколько потребуется, чтобы добыть сокровище и отчалить обратно в Пиратскую Бухту.$b$bНо Лоло думает, мы тут надолго засели. Из нашей эскадры мы потеряли два корабля. Беднягу "Дух Серебряного бора" и несчастную "Девичью Блажь". На дне морском они теперь!$b$bЛоло думает, вам бы переговорить с капитаном О\'Брином, если вы тут и дальше слоняться собираетесь.','Поговорите с капитаном О\'Брином в бухте Фальдира, что на Нагорье Арати.','Хей, дружище.\n\nНу и жуть же была. Морской Рог отнимет у меня корабль, если проведает, что тут произошло.\n\nОдна из этих хитрых профессорских штучек указала на то, что поблизости от этой бухты лежит давно утерянный клад. Я привел "Вестник" к берегу, чтобы причалить, и сигнализировал "Духу Серебряного бора" и "Девичьей Блажи", чтобы они сделали то же самое.\n\nА потом вдруг море загрохотало. Вода понизилась, и оба корабля разбились, врезавшись в риф.\n\nНо это был не просто риф. Что-то было там, внизу...\n\nПомогите моей команде, и получите неплохое вознаграждение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эй, там!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ой, кого видит Лоло! Это ж крошка-|3-6($c)! Лоло всегда начеку!$b$bДобро пожаловать в Бухту Фальдира. Капитан О\'Брин сказал, что мы задержимся тут лишь на несколько часов. Ровно настолько, сколько потребуется, чтобы добыть сокровище и отчалить обратно в Пиратскую Бухту.$b$bНо Лоло думает, мы тут надолго засели. Из нашей эскадры мы потеряли два корабля. Беднягу "Дух Серебряного бора" и несчастную "Девичью Блажь". На дне морском они теперь!$b$bЛоло думает, вам бы переговорить с капитаном О\'Брином, если вы тут и дальше слоняться собираетесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном О\'Брином в бухте Фальдира, что на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хей, дружище.\n\nНу и жуть же была. Морской Рог отнимет у меня корабль, если проведает, что тут произошло.\n\nОдна из этих хитрых профессорских штучек указала на то, что поблизости от этой бухты лежит давно утерянный клад. Я привел "Вестник" к берегу, чтобы причалить, и сигнализировал "Духу Серебряного бора" и "Девичьей Блажи", чтобы они сделали то же самое.\n\nА потом вдруг море загрохотало. Вода понизилась, и оба корабля разбились, врезавшись в риф.\n\nНо это был не просто риф. Что-то было там, внизу...\n\nПомогите моей команде, и получите неплохое вознаграждение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (664,'Затонувшие печали','Ох, жизнь – ужасная штука. Я должен бы покоиться в водяной могиле, а не сидеть здесь у огня, наслаждаясь свежим воздухом.$B$BКоманда не жалела сил, чтобы спасти мою прекрасную "Девичью Блажь". Да упокоятся ребята в мире, благословенны их сердца.$B$BО\'Брину удалось выбраться на берег, а нам не повезло. Море просто опрокинулось на нас, клянусь вам.$b$bВот мы плывем – и вот следующая волна обрушивается на нас. А эти твари! Они убили всех, кто выжил. Подлое нагово отродье. Я вырубился и пришел в себя уже здесь.$b$bЯ жажду их мерзкой холодной крови!','Капитан Стальные Нервы из бухты Фальдира хочет, чтобы вы убили 10 налетчиков и 3 колдуний из клана Пронзающего Гребня.','Вернитесь к капитану Стальные Нервы в Бухту Фальдира, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувшие печали',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, жизнь – ужасная штука. Я должен бы покоиться в водяной могиле, а не сидеть здесь у огня, наслаждаясь свежим воздухом.$B$BКоманда не жалела сил, чтобы спасти мою прекрасную "Девичью Блажь". Да упокоятся ребята в мире, благословенны их сердца.$B$BО\'Брину удалось выбраться на берег, а нам не повезло. Море просто опрокинулось на нас, клянусь вам.$b$bВот мы плывем – и вот следующая волна обрушивается на нас. А эти твари! Они убили всех, кто выжил. Подлое нагово отродье. Я вырубился и пришел в себя уже здесь.$b$bЯ жажду их мерзкой холодной крови!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Стальные Нервы из бухты Фальдира хочет, чтобы вы убили 10 налетчиков и 3 колдуний из клана Пронзающего Гребня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Стальные Нервы в Бухту Фальдира, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (665,'Затонувшее сокровище','Теперь, когда мы настоящие полноценные разбойники Черноводья, мы должны помочь мистеру О\'Брину разыскать пропавшее эльфийское сокровище.$b$bПочти невозможно найти драгоценные камни в море без посторонней помощи. Доктор сконструировал специальные очки, которые должны помочь. Ему нужно зарядить эти очки энергией, извлеченной из заколдованного камня в пещере, расположенной выше по холму.$b$bНо эта пещера проклята! Когда мы подошли к ней, на нас напали. Защитите меня, и я смогу вытянуть энергию из камня и направить ее в очки.','Проводите профессора Физзлторпа в пещеру и обратно.','Защитите профессора Физзлторпа','Вернитесь к доктору Драксельмеру в Бухту Фальдира, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувшее сокровище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы настоящие полноценные разбойники Черноводья, мы должны помочь мистеру О\'Брину разыскать пропавшее эльфийское сокровище.$b$bПочти невозможно найти драгоценные камни в море без посторонней помощи. Доктор сконструировал специальные очки, которые должны помочь. Ему нужно зарядить эти очки энергией, извлеченной из заколдованного камня в пещере, расположенной выше по холму.$b$bНо эта пещера проклята! Когда мы подошли к ней, на нас напали. Защитите меня, и я смогу вытянуть энергию из камня и направить ее в очки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите профессора Физзлторпа в пещеру и обратно.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите профессора Физзлторпа',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к доктору Драксельмеру в Бухту Фальдира, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (666,'Затонувшее сокровище','Сокровища так долго лежали на дне морском, что покрылись известковым налетом, превратившись в большой камень. Но сила, влитая в эти очки, позволит вам легко определить их местонахождение.$b$bМаленькая гномская хитрость делает большие дела!$b$bВозьмите эти очки Ловца сокровищ, $n, посмотрите, может, вам удастся собрать какие-то из утерянных сокровищ для капитана О\'Брина.$b$bЯ бы и сам поплыл туда, но... эм... ну, у меня есть серьезные научные задачи, требующие срочного решения на надежной, сухой земле... да... вот.','Доктор Драксельмер в бухте Фальдира хочет, чтобы вы собрали 10 эльфийских самоцветов и вернули ему очки Ловца сокровищ, когда закончите.','Ну, и как работают очки? Все функционирует как надо? Можно подрегулировать, если есть необходимость.\n\nАх да, эти очки понадобятся мне, когда вы закончите. Я уверен, что капитан О\'Брин найдет им потом самое разнообразное применение.','Вернитесь к доктору Драксельмеру в Бухту Фальдира, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувшее сокровище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сокровища так долго лежали на дне морском, что покрылись известковым налетом, превратившись в большой камень. Но сила, влитая в эти очки, позволит вам легко определить их местонахождение.$b$bМаленькая гномская хитрость делает большие дела!$b$bВозьмите эти очки Ловца сокровищ, $n, посмотрите, может, вам удастся собрать какие-то из утерянных сокровищ для капитана О\'Брина.$b$bЯ бы и сам поплыл туда, но... эм... ну, у меня есть серьезные научные задачи, требующие срочного решения на надежной, сухой земле... да... вот.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доктор Драксельмер в бухте Фальдира хочет, чтобы вы собрали 10 эльфийских самоцветов и вернули ему очки Ловца сокровищ, когда закончите.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, и как работают очки? Все функционирует как надо? Можно подрегулировать, если есть необходимость.\n\nАх да, эти очки понадобятся мне, когда вы закончите. Я уверен, что капитан О\'Брин найдет им потом самое разнообразное применение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к доктору Драксельмеру в Бухту Фальдира, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (667,'Смерть со дна морского','Это плохо. Похоже, клан Пронзающего Гребня готовится к нападению.$B$BНаги известны своей жестокостью в бою. Они не остановятся, пока я не умру.$B$BНе то чтобы я ценил свою жизнь выше, чем жизни членов команды, но вы должны помочь защитить меня. Я единственный, кто знает морские пути, – команда просто не сможет вернуться в Пиратскую Бухту без меня.$B$BНаги придут с моря. Мне нужно, чтобы вы оставались здесь, со мной, чтобы отразить их атаку. Орудия к бою! Надо оттеснить их.$B$BГотовы, $n?','Защитите Мураша О\'Брина во время атаки наг.','Доволен ли Морской Рог? Держу пари, его ухмылка растянулась от Пиратской бухты до Кабестана!','Защитите Мураша О\'Брина.','Вернитесь к Мурашу О\'Брину в Бухту Фальдира, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть со дна морского',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это плохо. Похоже, клан Пронзающего Гребня готовится к нападению.$B$BНаги известны своей жестокостью в бою. Они не остановятся, пока я не умру.$B$BНе то чтобы я ценил свою жизнь выше, чем жизни членов команды, но вы должны помочь защитить меня. Я единственный, кто знает морские пути, – команда просто не сможет вернуться в Пиратскую Бухту без меня.$B$BНаги придут с моря. Мне нужно, чтобы вы оставались здесь, со мной, чтобы отразить их атаку. Орудия к бою! Надо оттеснить их.$B$BГотовы, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите Мураша О\'Брина во время атаки наг.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Доволен ли Морской Рог? Держу пари, его ухмылка растянулась от Пиратской бухты до Кабестана!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите Мураша О\'Брина.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мурашу О\'Брину в Бухту Фальдира, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (668,'Затонувшее сокровище','Не будем заставлять капитана О\'Брина ждать. Он захочет первым увидеть эти драгоценности. В конце концов, для того мы и здесь!$b$bА через несколько недель сотрудничества с этими пиратами мы с профессором поняли, что на нашем здоровье самым пагубным образом может сказаться, если нас застанут придерживающими их сокровища.$b$bВот, $n, отнесите все О\'Брину.','Отнесите эльфийские самоцветы капитану О\'Брину в бухту Фальдира, что на Нагорье Арати.','Так, значит, коротышки в конце концов оказались полезными? Я знал, что мы этих мальчиков-с-пальчик не напрасно взяли с собой!','Эй, |3-6($C). Что привело вас на мостик?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувшее сокровище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не будем заставлять капитана О\'Брина ждать. Он захочет первым увидеть эти драгоценности. В конце концов, для того мы и здесь!$b$bА через несколько недель сотрудничества с этими пиратами мы с профессором поняли, что на нашем здоровье самым пагубным образом может сказаться, если нас застанут придерживающими их сокровища.$b$bВот, $n, отнесите все О\'Брину.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите эльфийские самоцветы капитану О\'Брину в бухту Фальдира, что на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, значит, коротышки в конце концов оказались полезными? Я знал, что мы этих мальчиков-с-пальчик не напрасно взяли с собой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эй, |3-6($C). Что привело вас на мостик?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (669,'Затонувшее сокровище','Командир флота Морской Рог захочет сразу же услышать о нашей находке.$b$bНо, как видите, мы пока не в том положении, чтобы сняться отсюда. Не только прилив очень низок, но еще и эти проклятые твари, которым мы помешали, бдительно следят за нашими передвижениями.$b$bВы оказали бы большую услугу Пиратам Черноводья, если бы смогли сообщить флотовладельцу Морскому Рогу в Пиратскую Бухту, что мы отыскали сокровища и работаем над тем, чтобы достать еще. А этот образчик отвезите ему в качестве доказательства.','Доставьте образец эльфийского самоцвета командиру флота Морскому Рогу в Пиратскую Бухту, что в Тернистой долине.','А, узнаю старого доброго Мураша О\'Брина! Я знал, что это подходящий капитан для такого задания!','Что привело вас в Пиратскую бухту, |3-6($C)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувшее сокровище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Командир флота Морской Рог захочет сразу же услышать о нашей находке.$b$bНо, как видите, мы пока не в том положении, чтобы сняться отсюда. Не только прилив очень низок, но еще и эти проклятые твари, которым мы помешали, бдительно следят за нашими передвижениями.$b$bВы оказали бы большую услугу Пиратам Черноводья, если бы смогли сообщить флотовладельцу Морскому Рогу в Пиратскую Бухту, что мы отыскали сокровища и работаем над тем, чтобы достать еще. А этот образчик отвезите ему в качестве доказательства.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте образец эльфийского самоцвета командиру флота Морскому Рогу в Пиратскую Бухту, что в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, узнаю старого доброго Мураша О\'Брина! Я знал, что это подходящий капитан для такого задания!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело вас в Пиратскую бухту, |3-6($C)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (670,'Затонувшее сокровище','Слушайте, $n, у вас лицо искателя приключений. Мой флот застрял в Пиратской Бухте, пока мы не загрузимся.$b$bТам, да и не только там, творятся темные делишки, а мне нужно доставить кое-какую секретную корреспонденцию Мурашу О\'Брину, пришвартовавшемуся к побережью Арати.$b$bМогу ли я доверить вам доставку этого сообщения в целости и сохранности и надеяться на вашу готовность хранить это задание в секрете?','Отвезите письмо Морского Рога Мурашу О\'Брину в Бухту Фальдира, что на Нагорье Арати.','Спасибо, что проделали такой долгий и опасный путь. Благодарю вас от имени разбойников Черноводья.','Доволен ли Морской Рог? Держу пари, его ухмылка растянулась от Пиратской бухты до Кабестана!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувшее сокровище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушайте, $n, у вас лицо искателя приключений. Мой флот застрял в Пиратской Бухте, пока мы не загрузимся.$b$bТам, да и не только там, творятся темные делишки, а мне нужно доставить кое-какую секретную корреспонденцию Мурашу О\'Брину, пришвартовавшемуся к побережью Арати.$b$bМогу ли я доверить вам доставку этого сообщения в целости и сохранности и надеяться на вашу готовность хранить это задание в секрете?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отвезите письмо Морского Рога Мурашу О\'Брину в Бухту Фальдира, что на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что проделали такой долгий и опасный путь. Благодарю вас от имени разбойников Черноводья.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Доволен ли Морской Рог? Держу пари, его ухмылка растянулась от Пиратской бухты до Кабестана!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (671,'Выявление истинных намерений Синдиката отнимет у меня некоторое время, но их очевидное сотрудничество с темными демоническими силами меня беспокоит. Я расскажу вам, когда разузнаю.','Вернитесь к Тор\'гану в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выявление истинных намерений Синдиката отнимет у меня некоторое время, но их очевидное сотрудничество с темными демоническими силами меня беспокоит. Я расскажу вам, когда разузнаю.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тор\'гану в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (672,'Вызов духов','Мы пытались успокоить его, развеселить, рассказывать ему истории о нашем огромном городе Оргриммаре в Калимдоре, но его ничто не трогало.$B$BИстории о нашем молодом вожде, Тралле, который носит доспехи и молот Оргрима... но, быть может... Может быть! Демонстрация нашей новообретенной шаманской магии могла бы дать ему луч надежды. Попробовать стоит!$B$BМы могли бы сделать для него маленькую вещицу, да... Принесите мне несколько глаз ящера, и я посмотрю, что можно сделать.','Соберите 10 глаз ящеров нагорья с долгоногов и твердозубов нагорья, принесите их Тор\'гану в Павший Молот.','Отлично. Духи ящеров, от которых взяты эти глаза, предоставят носящему этот амулет свою силу.','Я создам амулет, который частично наделит Гор\'муля силой ящеров. Может быть, это пробудит в нем огонь жизни...','Вернитесь к Тор\'гану в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы пытались успокоить его, развеселить, рассказывать ему истории о нашем огромном городе Оргриммаре в Калимдоре, но его ничто не трогало.$B$BИстории о нашем молодом вожде, Тралле, который носит доспехи и молот Оргрима... но, быть может... Может быть! Демонстрация нашей новообретенной шаманской магии могла бы дать ему луч надежды. Попробовать стоит!$B$BМы могли бы сделать для него маленькую вещицу, да... Принесите мне несколько глаз ящера, и я посмотрю, что можно сделать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 глаз ящеров нагорья с долгоногов и твердозубов нагорья, принесите их Тор\'гану в Павший Молот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Духи ящеров, от которых взяты эти глаза, предоставят носящему этот амулет свою силу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я создам амулет, который частично наделит Гор\'муля силой ящеров. Может быть, это пробудит в нем огонь жизни...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тор\'гану в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (673,'Кровь моя пылает... все сильнее. Чернокнижника нужно остановить.','Вернитесь к Тор\'гану в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кровь моя пылает... все сильнее. Чернокнижника нужно остановить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тор\'гану в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (674,'Вызов духов','Вот, отнесите этот амулет Гор\'мулю и посмотрите, пробудит ли сила ящера в нем тот боевой огонь, который некогда пылал в его крови.','Отдайте амулет из когтя ящера Гор\'мулю. Его можно найти в Павшем Молоте, что на Нагорье Арати.','Что это? Отполированный кусок кости... Что мне пользы от полированной косточки? Разве безделушка способна вернуть Орде ее былую славу?','Какая может быть надежда, если рукой труса может быть убит сильнейший из сильных? Какая надежда, ответьте мне!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, отнесите этот амулет Гор\'мулю и посмотрите, пробудит ли сила ящера в нем тот боевой огонь, который некогда пылал в его крови.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте амулет из когтя ящера Гор\'мулю. Его можно найти в Павшем Молоте, что на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Отполированный кусок кости... Что мне пользы от полированной косточки? Разве безделушка способна вернуть Орде ее былую славу?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какая может быть надежда, если рукой труса может быть убит сильнейший из сильных? Какая надежда, ответьте мне!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (675,'Вызов духов','*Гор\'муль бросает амулет на землю.*$B$BВас Тор\'ган послал, да? Тьфу... Никак не могу понять, почему он жалеет меня. В сострадании мне было отказано, когда мне не позволили умереть вместе с моим вождем во время боя. Жестокий удар судьбы настиг меня...','Поговорите с Тор\'ганом в Павшем Молоте, что на Нагорье Арати.','Вижу, что не сработало. Тем не менее я чувствую, что демонстрация силы шаманов может помочь Гор\'мулю вернуть веру в себя. Сила амулета была недостаточно велика, чтобы показать ему нашу новообретенную мощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Гор\'муль бросает амулет на землю.*$B$BВас Тор\'ган послал, да? Тьфу... Никак не могу понять, почему он жалеет меня. В сострадании мне было отказано, когда мне не позволили умереть вместе с моим вождем во время боя. Жестокий удар судьбы настиг меня...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тор\'ганом в Павшем Молоте, что на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, что не сработало. Тем не менее я чувствую, что демонстрация силы шаманов может помочь Гор\'мулю вернуть веру в себя. Сила амулета была недостаточно велика, чтобы показать ему нашу новообретенную мощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (676,'Да падет молот','Слабаки... Все они слабаки. А ты, |3-6($c), куда смотришь? Думаешь, $gособенный:особенная;? Проверим?$B$BНа форт Павший Молот напали враги. Если не помочь нашим, им не устоять.$B$BВпрочем, не спеши. Прежде надо испытать твое искусство. На северо-востоке от Стромгарда в Арати есть курган, который заселило огрское племя Тяжелого Кулака. Когда одолеешь тамошних огров и мародеров, доложи об этом Драму Желчному в Павшем Молоте.','Убейте 8 огров из клана Тяжелого Кулака и 10 головорезов из клана Тяжелого Кулака, затем найдите Драма Желчного в Павшем Молоте на Нагорье Арати.','Значит, ты думаешь, что тебе хватит сил помочь Павшему Молоту? Да будет так.\n\nСальный послал тебя в огрский курган или в надежде, что ты там погибнешь, или полагая, что сможешь помочь нам. Так или иначе, ты здесь, а мне нужны солдаты. Натиск на наш форт не ослабевает.\n\nЕсли ты собираешься остаться в Павшем Молоте, то отдохни, а потом приходи ко мне. Чего-чего, а сражений на твою долю хватит.','У меня нет времени топор наточить, не говоря уж о том, чтобы покинуть форт и заняться теми тварями, которые убивают моих братьев.$B$BПохоже, опыта тебе не хватает даже для обычного рубаки, не говоря уж о полноценном. Что тебе нужно, $N?','Вернитесь к Драму Желчному в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Да падет молот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слабаки... Все они слабаки. А ты, |3-6($c), куда смотришь? Думаешь, $gособенный:особенная;? Проверим?$B$BНа форт Павший Молот напали враги. Если не помочь нашим, им не устоять.$B$BВпрочем, не спеши. Прежде надо испытать твое искусство. На северо-востоке от Стромгарда в Арати есть курган, который заселило огрское племя Тяжелого Кулака. Когда одолеешь тамошних огров и мародеров, доложи об этом Драму Желчному в Павшем Молоте.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 огров из клана Тяжелого Кулака и 10 головорезов из клана Тяжелого Кулака, затем найдите Драма Желчного в Павшем Молоте на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты думаешь, что тебе хватит сил помочь Павшему Молоту? Да будет так.\n\nСальный послал тебя в огрский курган или в надежде, что ты там погибнешь, или полагая, что сможешь помочь нам. Так или иначе, ты здесь, а мне нужны солдаты. Натиск на наш форт не ослабевает.\n\nЕсли ты собираешься остаться в Павшем Молоте, то отдохни, а потом приходи ко мне. Чего-чего, а сражений на твою долю хватит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня нет времени топор наточить, не говоря уж о том, чтобы покинуть форт и заняться теми тварями, которые убивают моих братьев.$B$BПохоже, опыта тебе не хватает даже для обычного рубаки, не говоря уж о полноценном. Что тебе нужно, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драму Желчному в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (677,'Призыв к оружию','Тролли племени Сухокожих и огры клана Тяжелого Кулака с Нагорья Арати объединились, чтобы выжить нас с этой земли, но мы не собираемся уступать ни им, ни кому угодно другому. Мы убьем их и покажем, что и мы здесь – у себя дома.$B$BТролли позорно бежали от нас; огры сожрали бы нас и спали бы на наших шкурах, если бы мы им позволили, – этим тварям нельзя жить.$B$BМы начнем атаковать троллей Сухокожих к югу отсюда. Убивай их пачками и возвращайся только тогда, когда их поселения будут залиты кровью.','Убейте 10 метателей топоров из племени Сухокожих, 10 охотников за головами из племени Сухокожих и 8 знахарей племени Сухокожих, а затем возвращайтесь к Драму Желчному на заставу Павшего Молота.','Я вижу боевые отметины на твоих доспехах, и пот струится по твоему лбу. Неплохо, в самом деле неплохо.','Если ты еще не $Gвыполнил:выполнила; мое задание – может быть, ты просто трус в душе и неумеха в бою.','Вернитесь к Драму Желчному в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли племени Сухокожих и огры клана Тяжелого Кулака с Нагорья Арати объединились, чтобы выжить нас с этой земли, но мы не собираемся уступать ни им, ни кому угодно другому. Мы убьем их и покажем, что и мы здесь – у себя дома.$B$BТролли позорно бежали от нас; огры сожрали бы нас и спали бы на наших шкурах, если бы мы им позволили, – этим тварям нельзя жить.$B$BМы начнем атаковать троллей Сухокожих к югу отсюда. Убивай их пачками и возвращайся только тогда, когда их поселения будут залиты кровью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 метателей топоров из племени Сухокожих, 10 охотников за головами из племени Сухокожих и 8 знахарей племени Сухокожих, а затем возвращайтесь к Драму Желчному на заставу Павшего Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я вижу боевые отметины на твоих доспехах, и пот струится по твоему лбу. Неплохо, в самом деле неплохо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты еще не $Gвыполнил:выполнила; мое задание – может быть, ты просто трус в душе и неумеха в бою.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драму Желчному в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (678,'Призыв к оружию','Твоя сила очевидна, $n. Теперь посмотрим, как ты справишься с настоящим врагом.$B$BУ клана Тяжелого Кулака есть логово к юго-западу отсюда по направлению к дворфийскому мосту, и, если я не ошибаюсь, их молотобойцы и маги должны стать для тебя более серьезным испытанием – по крайней мере, для нас они таковым являются по сию пору.$B$BУбей столько огров, сколько сможешь, и возвращайся ко мне во плоти, если добьешься успеха, или в виде призрака, если потерпишь неудачу. В любом случае я воздам хвалу твоей стойкости в бою.','Убейте 10 громил и 4 магов из клана Тяжелого Кулака, затем возвращайтесь к Драму Желчному на заставу Павшего Молота.','Ты не слабее кодо, а твоя готовность к битве достойна восхищения.','Доволен ли Морской Рог? Держу пари, его ухмылка растянулась от Пиратской бухты до Кабестана!','Вернитесь к Драму Желчному в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя сила очевидна, $n. Теперь посмотрим, как ты справишься с настоящим врагом.$B$BУ клана Тяжелого Кулака есть логово к юго-западу отсюда по направлению к дворфийскому мосту, и, если я не ошибаюсь, их молотобойцы и маги должны стать для тебя более серьезным испытанием – по крайней мере, для нас они таковым являются по сию пору.$B$BУбей столько огров, сколько сможешь, и возвращайся ко мне во плоти, если добьешься успеха, или в виде призрака, если потерпишь неудачу. В любом случае я воздам хвалу твоей стойкости в бою.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 громил и 4 магов из клана Тяжелого Кулака, затем возвращайтесь к Драму Желчному на заставу Павшего Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не слабее кодо, а твоя готовность к битве достойна восхищения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Доволен ли Морской Рог? Держу пари, его ухмылка растянулась от Пиратской бухты до Кабестана!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драму Желчному в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (679,'Призыв к оружию','Зверю вот-вот отрубят голову... и все же для решающего удара требуется огромная сила, $n. Уверен, именно ты можешь помочь нам нанести этот последний мощный удар. Руководящие этими атаками устроили свое логово прямо в руинах Стромгарда – вот яркий пример человеческой слабости...$B$BНайди и убей вождей клана Тяжелого Кулака и их прислужников-шаманов, пытающихся выжить нас с этих земель.','Убейте 7 шаманов клана Тяжелого Кулака и 3 вождей клана Тяжелого Кулака и возвращайтесь к Драму Желчному на заставу Павшего Молота.','Вернитесь к Драму Желчному в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зверю вот-вот отрубят голову... и все же для решающего удара требуется огромная сила, $n. Уверен, именно ты можешь помочь нам нанести этот последний мощный удар. Руководящие этими атаками устроили свое логово прямо в руинах Стромгарда – вот яркий пример человеческой слабости...$B$BНайди и убей вождей клана Тяжелого Кулака и их прислужников-шаманов, пытающихся выжить нас с этих земель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 шаманов клана Тяжелого Кулака и 3 вождей клана Тяжелого Кулака и возвращайтесь к Драму Желчному на заставу Павшего Молота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драму Желчному в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (680,'Настоящая угроза','Вы отлично служите моему мужу, |3-6($c), но он не знает, почему Павший Молот подвергается атакам.$b$bОр\'Калар – пешка в руках Муг\'Тола в Стромгарде – яро ненавидит моего мужа и ничего так не желает, как его смерти – за то, что тот нанес ему поражение много лет назад.$b$bМои гадатели сообщают, что Ор\'Калар устроил для мужа ловушку, поэтому я скрыла от него, что огр объявился в этих землях.$b$bМой муж ринется сломя голову, если узнает о местонахождении огра, а я хотела бы попросить вашей помощи в убийстве этой твари.','Убейте Ор\'Калара и принесите его голову Корин Желчной на заставу Павшего Молота.','Возле Башни Аратора – вот где вы найдете Ор\'Калара. С его смертью прекратятся атаки на Павший Молот, и жизнь моего мужа будет вне опасности.\n\nЯ вижу по вашим глазам, что вы считаете меня слабой – и даже бесчестной – из-за моего молчания. Однажды вы узнаете, что значит любить – как люблю я. Может быть, тогда вы поймете, что есть и другой вид силы и чести.\n\nА тем временем, выполните мою просьбу и убейте Ор\'Калара.','Вернитесь к Корин Желчной в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Настоящая угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы отлично служите моему мужу, |3-6($c), но он не знает, почему Павший Молот подвергается атакам.$b$bОр\'Калар – пешка в руках Муг\'Тола в Стромгарде – яро ненавидит моего мужа и ничего так не желает, как его смерти – за то, что тот нанес ему поражение много лет назад.$b$bМои гадатели сообщают, что Ор\'Калар устроил для мужа ловушку, поэтому я скрыла от него, что огр объявился в этих землях.$b$bМой муж ринется сломя голову, если узнает о местонахождении огра, а я хотела бы попросить вашей помощи в убийстве этой твари.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ор\'Калара и принесите его голову Корин Желчной на заставу Павшего Молота.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Возле Башни Аратора – вот где вы найдете Ор\'Калара. С его смертью прекратятся атаки на Павший Молот, и жизнь моего мужа будет вне опасности.\n\nЯ вижу по вашим глазам, что вы считаете меня слабой – и даже бесчестной – из-за моего молчания. Однажды вы узнаете, что значит любить – как люблю я. Может быть, тогда вы поймете, что есть и другой вид силы и чести.\n\nА тем временем, выполните мою просьбу и убейте Ор\'Калара.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корин Желчной в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (681,'Северное поместье','Мы ведем войну со Стромгардом и терпим в ней поражение. Мы делим наш некогда великий город с ограми и Синдикатом, каждая группировка бьется с другой, и конца этому не видно.$b$bНо наши силы иссякают, в то время как силы наших врагов – растут.$b$bНам нужна помощь из Южнобережья, но есть проблемы с доставкой припасов, поскольку Синдикат контролирует территорию между нами.$B$BПойдите на базу Синдиката в Северном поместье и убейте их. Тогда, может быть, давление на наши транспортные пути ослабеет, и доставлять припасы станет проще.','Убейте 10 проходимцев из Синдиката и 6 наемников Синдиката.$B$BЗатем вернитесь к капитану Ниалс в Опорном пункте.','Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Северное поместье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы ведем войну со Стромгардом и терпим в ней поражение. Мы делим наш некогда великий город с ограми и Синдикатом, каждая группировка бьется с другой, и конца этому не видно.$b$bНо наши силы иссякают, в то время как силы наших врагов – растут.$b$bНам нужна помощь из Южнобережья, но есть проблемы с доставкой припасов, поскольку Синдикат контролирует территорию между нами.$B$BПойдите на базу Синдиката в Северном поместье и убейте их. Тогда, может быть, давление на наши транспортные пути ослабеет, и доставлять припасы станет проще.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 проходимцев из Синдиката и 6 наемников Синдиката.$B$BЗатем вернитесь к капитану Ниалс в Опорном пункте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (682,'Знаки Стромгарда','Синдикат в Стромгарде воюет с силами нашего ополчения. Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев.$B$BМы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят!$B$BОтправляйтесь в район Стромгарда, контролируемый Синдикатом, и отберите у их бойцов наши знаки.','Принесите 7 знаков Стромгарда Капитану Ниалс в Опорный пункт.','Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Стромгарда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Синдикат в Стромгарде воюет с силами нашего ополчения. Чтобы побудить толпу биться с нашими более дисциплинированными войсками, руководство Синдиката объявило о награде за убийство наших солдат, предлагая золото за каждый знак Стромгарда, снятый с убитых ополченцев.$B$BМы хотим вернуть себе эти знаки – не можем же мы позволить головорезам брать трофеи с тел наших героически погибших ребят!$B$BОтправляйтесь в район Стромгарда, контролируемый Синдикатом, и отберите у их бойцов наши знаки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 знаков Стромгарда Капитану Ниалс в Опорный пункт.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (683,'Прошение Сары Балу','$n, у меня есть к вам маленькая просьба.$b$bВозьмите прошение, которое я написала на имя нашего великого государя стальгорнского, короля Магни Бронзоборода. Это небольшой труд для $Gтакого:такой;, как ты, $Gславного героя:славной девы;.$b$bМне в моем горе сейчас трудно будет предстать перед королем. Ты понимаешь меня.','Отнесите прошение Сары Балу королю Магни Бронзобороду в Стальгорн.','Подожите минутку, я прочту письмо...','Значит, вы – $N $C? Я наслышан о вашей доблестной службе Альянсу.$B$BЧто за дело привело вас ко мне ныне?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прошение Сары Балу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, у меня есть к вам маленькая просьба.$b$bВозьмите прошение, которое я написала на имя нашего великого государя стальгорнского, короля Магни Бронзоборода. Это небольшой труд для $Gтакого:такой;, как ты, $Gславного героя:славной девы;.$b$bМне в моем горе сейчас трудно будет предстать перед королем. Ты понимаешь меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите прошение Сары Балу королю Магни Бронзобороду в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Подожите минутку, я прочту письмо...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Значит, вы – $N $C? Я наслышан о вашей доблестной службе Альянсу.$B$BЧто за дело привело вас ко мне ныне?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (684,'Разыскивается: Марез Клобук','Назначена награда за голову Марез Клобук, высокопоставленной советницы и деятеля Синдиката. В последний раз ее видели на контролируемой Синдикатом территории Стромгарда.$B$BНаграду можно будет получить у капитана Ниалс.$B$BПредупреждение: Марез – опытная и коварная чернокнижница, замеченная в связях с демонами. Вооружена и очень опасна!','Принесите капитану Ниалс в Опорный пункт голову Марез.','Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разыскивается: Марез Клобук',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Назначена награда за голову Марез Клобук, высокопоставленной советницы и деятеля Синдиката. В последний раз ее видели на контролируемой Синдикатом территории Стромгарда.$B$BНаграду можно будет получить у капитана Ниалс.$B$BПредупреждение: Марез – опытная и коварная чернокнижница, замеченная в связях с демонами. Вооружена и очень опасна!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите капитану Ниалс в Опорный пункт голову Марез.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (685,'Разыскивается: Отто и лорд Соколиный Шлем','Ополчение Стромгарда уведомляет о назначении награды за головы лорда Соколиного Шлема и его телохранителя Отто. Соколиный Шлем руководит деятельностью Синдиката на Нагорье Арати, и его смерть внесла бы большую сумятицу.$B$BЕго телохранитель Отто, хотя и не является стратегической целью, представляет собой опасного противника, на счету которого – смерть десятков наших воинов.$B$BНаграды за их головы можно получить у капитана Ниалс.','Принесите головы Отто и лорда Соколиного Шлема капитану Ниалс в Опорный пункт.','Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разыскивается: Отто и лорд Соколиный Шлем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ополчение Стромгарда уведомляет о назначении награды за головы лорда Соколиного Шлема и его телохранителя Отто. Соколиный Шлем руководит деятельностью Синдиката на Нагорье Арати, и его смерть внесла бы большую сумятицу.$B$BЕго телохранитель Отто, хотя и не является стратегической целью, представляет собой опасного противника, на счету которого – смерть десятков наших воинов.$B$BНаграды за их головы можно получить у капитана Ниалс.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите головы Отто и лорда Соколиного Шлема капитану Ниалс в Опорный пункт.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ниалс на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (686,'Королевские почести','Вряд ли добрые дворфийские вдовы вроде госпожи Баллу понимают, что нам приходится терпеть тяготы войны ради высшего блага нашего народа. Гибель ее мужа, как и гибель всех дворфов, что сражаются за дело Альянса, тяжким бременем лежит на моей душе.$b$bМне не под силу вернуть ее супруга из Круговерти Пустоты, но я могу хотя бы почтить его память.$b$bЯ намерен заказать главному каменотесу Стальгорна Мраморщику памятник в честь Салли Балу.$b$bОтправляйтесь к нему сейчас же и передайте мои слова, |3-6($c). Вы будете моим вестником.','Поговорите с главным каменотесом Мраморщиком.','Значит, вас послал лично король Магни Бронзобород?$B$BПодумать только! Стало быть, дело важное!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королевские почести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вряд ли добрые дворфийские вдовы вроде госпожи Баллу понимают, что нам приходится терпеть тяготы войны ради высшего блага нашего народа. Гибель ее мужа, как и гибель всех дворфов, что сражаются за дело Альянса, тяжким бременем лежит на моей душе.$b$bМне не под силу вернуть ее супруга из Круговерти Пустоты, но я могу хотя бы почтить его память.$b$bЯ намерен заказать главному каменотесу Стальгорна Мраморщику памятник в честь Салли Балу.$b$bОтправляйтесь к нему сейчас же и передайте мои слова, |3-6($c). Вы будете моим вестником.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с главным каменотесом Мраморщиком.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, вас послал лично король Магни Бронзобород?$B$BПодумать только! Стало быть, дело важное!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (687,'Тельдарин Заблудший','Тельдарин Заблудший некогда был членом нашего ордена Сумеречного Молота. Однако он сошел с ума и отверг наше учение. Перед побегом он украл cвиток Мизраэль! Мы не смогли поймать его, но ходят слухи, что он совсем спятил и прячется в Бесплодных землях.$b$bЧтобы переманить на нашу сторону Госпожу, необходимо найти свиток. А для этого – найти Тельдарина.','Найдите Тельдарина Заблудшего.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тельдарин Заблудший',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тельдарин Заблудший некогда был членом нашего ордена Сумеречного Молота. Однако он сошел с ума и отверг наше учение. Перед побегом он украл cвиток Мизраэль! Мы не смогли поймать его, но ходят слухи, что он совсем спятил и прячется в Бесплодных землях.$b$bЧтобы переманить на нашу сторону Госпожу, необходимо найти свиток. А для этого – найти Тельдарина.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Тельдарина Заблудшего.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (688,'Союзники Мизраэль','<Говорит Мизраэль.>$B$BСвободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы.$B$BНо в должный час я пойду против великанов, и они еще пожалеют о том, что отняли у меня свободу!$B$BВы $gблагородный союзник:благородная союзница;, $n. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность.$B$BПоговорите с Заруком в Павшем Молоте. Он знает, как меня можно призвать.','Поговорите с Заруком в Павшем Молоте, что на Нагорье Арати.','Добро пожаловать, |3-6($C). Госпожа сообщила мне о вашем приближении, и если мы хотим вернуть ее на поверхность, нам нужно многое обсудить.','Возле Башни Аратора – вот где вы найдете Ор\'Калара. С его смертью прекратятся атаки на Павший Молот, и жизнь моего мужа будет вне опасности.\n\nЯ вижу по вашим глазам, что вы считаете меня слабой – и даже бесчестной – из-за моего молчания. Однажды вы узнаете, что значит любить – как люблю я. Может быть, тогда вы поймете, что есть и другой вид силы и чести.\n\nА тем временем, выполните мою просьбу и убейте Ор\'Калара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союзники Мизраэль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Говорит Мизраэль.>$B$BСвободна! Я СВОБОДНА! Я могу теперь набирать силу, скрывшись от моих пленителей. Потому что, если бы я предстала перед ними сейчас, они бы наверняка пересилили меня и вновь заключили бы в оковы.$B$BНо в должный час я пойду против великанов, и они еще пожалеют о том, что отняли у меня свободу!$B$BВы $gблагородный союзник:благородная союзница;, $n. Через некоторое время мне вновь понадобится ваша помощь. Когда я буду готова, нужно, чтобы вы призвали меня на поверхность.$B$BПоговорите с Заруком в Павшем Молоте. Он знает, как меня можно призвать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Заруком в Павшем Молоте, что на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать, |3-6($C). Госпожа сообщила мне о вашем приближении, и если мы хотим вернуть ее на поверхность, нам нужно многое обсудить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Возле Башни Аратора – вот где вы найдете Ор\'Калара. С его смертью прекратятся атаки на Павший Молот, и жизнь моего мужа будет вне опасности.\n\nЯ вижу по вашим глазам, что вы считаете меня слабой – и даже бесчестной – из-за моего молчания. Однажды вы узнаете, что значит любить – как люблю я. Может быть, тогда вы поймете, что есть и другой вид силы и чести.\n\nА тем временем, выполните мою просьбу и убейте Ор\'Калара.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (689,'Королевские почести','Значит, наш добрый король решил построить памятник в честь солдата по имени Салли Балу? И вы говорите, что бедный парень погиб на мосту Тандола?$b$bДа будет когда-нибудь мир в Азероте?$b$bКак бы то ни было, любое поручение нашего государя – дело первостепенной важности. Чтобы возвести действительно впечатляющий памятник на века, мне нужен самый лучший камень. Отправляйся на Холм Дарроу в Хилсбрад и привези мне альтеракского гранита.','Принесите главному каменотесу Стальгорна Мраморщику 5 кусков альтеракского гранита.','Замечательно! Лучше, чем я представить мог!$B$BА воображение у меня, между прочим...','$N, $N, $N! Говорите же, привезли ли вы мне достаточно альтеракского гранита, чтобы начать творить шедевр в честь Салли Баллу?','Вернитесь к главному камнетесу Мраморщику в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королевские почести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, наш добрый король решил построить памятник в честь солдата по имени Салли Балу? И вы говорите, что бедный парень погиб на мосту Тандола?$b$bДа будет когда-нибудь мир в Азероте?$b$bКак бы то ни было, любое поручение нашего государя – дело первостепенной важности. Чтобы возвести действительно впечатляющий памятник на века, мне нужен самый лучший камень. Отправляйся на Холм Дарроу в Хилсбрад и привези мне альтеракского гранита.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите главному каменотесу Стальгорна Мраморщику 5 кусков альтеракского гранита.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Лучше, чем я представить мог!$B$BА воображение у меня, между прочим...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, $N, $N! Говорите же, привезли ли вы мне достаточно альтеракского гранита, чтобы начать творить шедевр в честь Салли Баллу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному камнетесу Мраморщику в Стальгорн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (690,'Просьба Малина','Приветствую вас, $n. Вы похожи на искателя приключений, а у меня как раз есть задание, требующее склонности к авантюрам.$B$BВерховный маг Трелан, мой первый наставник, не так давно бежал из Стромгарда, что на Нагорье Арати, и просил меня помочь ему вернуть несколько предметов, которые он там оставил.$B$BГород был осажден, и Трелан попытался защитить Башню Аратора, но потерпел неудачу. У меня на нагорье есть агенты, но они просили дополнительной помощи. Вы согласитесь мне помочь?','Найдите Скуэрто в Опорном пункте на Нагорье Арати.','Так вас, значится, Малин прислал? А мне без разницы, пусть хоть сам Мурадин восстанет из мертвых и умчит вас отсюда на драконе... Я занят! Если вам что-нибудь нужно, обратитесь к Кретьену.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Малина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую вас, $n. Вы похожи на искателя приключений, а у меня как раз есть задание, требующее склонности к авантюрам.$B$BВерховный маг Трелан, мой первый наставник, не так давно бежал из Стромгарда, что на Нагорье Арати, и просил меня помочь ему вернуть несколько предметов, которые он там оставил.$B$BГород был осажден, и Трелан попытался защитить Башню Аратора, но потерпел неудачу. У меня на нагорье есть агенты, но они просили дополнительной помощи. Вы согласитесь мне помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Скуэрто в Опорном пункте на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так вас, значится, Малин прислал? А мне без разницы, пусть хоть сам Мурадин восстанет из мертвых и умчит вас отсюда на драконе... Я занят! Если вам что-нибудь нужно, обратитесь к Кретьену.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (691,'На вес золота','Верховный маг Малин послал нас со Скуэрто собирать для него реагенты. Я был в полном замешательстве и не знал, как приступить к делу, но теперь, когда вы здесь, думаю, моя проблема решена.$B$BВот что мне нужно: клыки троллей из племени Сухокожих, лекарские сумки племени Сухокожих и нож темного охотника.$B$BНе могли бы вы добыть это все для меня? Племя Сухокожих обитает к юго-востоку от Арати.','Найдите 10 клыков троллей племени Сухокожих, 4 лекарских сумки племени Сухокожих и нож Темного охотника и принесите их ученику Крайтену в Опорном пункте.','Вернитесь к ученику Крайтену на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На вес золота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный маг Малин послал нас со Скуэрто собирать для него реагенты. Я был в полном замешательстве и не знал, как приступить к делу, но теперь, когда вы здесь, думаю, моя проблема решена.$B$BВот что мне нужно: клыки троллей из племени Сухокожих, лекарские сумки племени Сухокожих и нож темного охотника.$B$BНе могли бы вы добыть это все для меня? Племя Сухокожих обитает к юго-востоку от Арати.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 10 клыков троллей племени Сухокожих, 4 лекарских сумки племени Сухокожих и нож Темного охотника и принесите их ученику Крайтену в Опорном пункте.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Крайтену на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (692,'Утраченные фрагменты','Свиток Мизраэль... Свиток Мизраэль?! Нет, уверяю вас, не стоит даже думать о нем! Его магия может вытащить Мизраэль на поверхность, и если вы это сделаете, нам грозит беда!$B$BИли... может быть, уже слишком поздно. Может быть, она уже свободна. Может быть, она уже собирается с силами, прежде чем обрушиться на нас. Если так, свиток вам НЕПРЕМЕННО ПОНАДОБИТСЯ!$B$B...как ужасно, что он уничтожен. Спятившие элементали похитили его и разорвали на клочки, а теперь дерутся за них.$B$BНо если бы вам удалось собрать эти фрагменты, может быть, нам удалось бы восстановить свиток...','Принесите рваный, мятый и обожженный фрагменты свитка Тельдарину Заблудшему.','Вернитесь к Тельдарину Заблудшему в Бесплодные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утраченные фрагменты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Свиток Мизраэль... Свиток Мизраэль?! Нет, уверяю вас, не стоит даже думать о нем! Его магия может вытащить Мизраэль на поверхность, и если вы это сделаете, нам грозит беда!$B$BИли... может быть, уже слишком поздно. Может быть, она уже свободна. Может быть, она уже собирается с силами, прежде чем обрушиться на нас. Если так, свиток вам НЕПРЕМЕННО ПОНАДОБИТСЯ!$B$B...как ужасно, что он уничтожен. Спятившие элементали похитили его и разорвали на клочки, а теперь дерутся за них.$B$BНо если бы вам удалось собрать эти фрагменты, может быть, нам удалось бы восстановить свиток...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите рваный, мятый и обожженный фрагменты свитка Тельдарину Заблудшему.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тельдарину Заблудшему в Бесплодные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (693,'Оружие получше кулаков','Здорово, $n.$B$BЯ выяснил, где оказалась первая вещь Трелана: Коргреш держит ее в Крепости Тяжелого Кулака. И судя по тому, как он кидался в своих потоками льда, чтобы заставить их держать строй, он, должно быть, уже близко подошел к пониманию того, как использовать мощь жезла на полную катушку.$B$BЧтобы добраться до Крепости Тяжелого Кулака, нужно идти на юг отсюда, а затем на восток от моста Тандола. Найдите этого огра и отберите у него жезл.$B$BА за время вашего отсутствия я соображу, что нам делать со Стромгардом.','Найдите заклинательный жезл Трелана и верните его Скуэрто в Опорный пункт.','Вернитесь к Скуэрто на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие получше кулаков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здорово, $n.$B$BЯ выяснил, где оказалась первая вещь Трелана: Коргреш держит ее в Крепости Тяжелого Кулака. И судя по тому, как он кидался в своих потоками льда, чтобы заставить их держать строй, он, должно быть, уже близко подошел к пониманию того, как использовать мощь жезла на полную катушку.$B$BЧтобы добраться до Крепости Тяжелого Кулака, нужно идти на юг отсюда, а затем на восток от моста Тандола. Найдите этого огра и отберите у него жезл.$B$BА за время вашего отсутствия я соображу, что нам делать со Стромгардом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите заклинательный жезл Трелана и верните его Скуэрто в Опорный пункт.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скуэрто на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (694,'Оборона Трелана','$gОтдохнул:Отдохнула;?$B$BВот наш следующий шаг: огры так и кишат вокруг башни Аратора в Стромгарде. Необходимо активировать защитные возможности башни, если вы хотите иметь хоть малейший шанс выстоять против них. Чтобы это сделать, нам понадобится несколько самоцветов, на которые наложил лапы шаман клана Тяжелого Кулака. Он стянул их из башни, но радость его преждевременна – камни недолго будут в его власти.$B$BДобудьте один из самоцветов и принесите его Крайтену – он знает заклинание, которое нужно наложить на эти камни, чтобы они работали как ключи.','Найдите лазурный агат и принесите его ученику Крайтену в Опорный пункт.','Вернитесь к ученику Крайтену на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона Трелана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gОтдохнул:Отдохнула;?$B$BВот наш следующий шаг: огры так и кишат вокруг башни Аратора в Стромгарде. Необходимо активировать защитные возможности башни, если вы хотите иметь хоть малейший шанс выстоять против них. Чтобы это сделать, нам понадобится несколько самоцветов, на которые наложил лапы шаман клана Тяжелого Кулака. Он стянул их из башни, но радость его преждевременна – камни недолго будут в его власти.$B$BДобудьте один из самоцветов и принесите его Крайтену – он знает заклинание, которое нужно наложить на эти камни, чтобы они работали как ключи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите лазурный агат и принесите его ученику Крайтену в Опорный пункт.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Крайтену на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (695,'Чары ученика','Вот, $n. Самоцвет нужно только прижать к одному из пьедесталов у основания башни, чтобы активировать ее защитные силы. Используйте его, когда будете готовы войти в башню и искать остальные принадлежащие Трелану предметы.$B$BУдачи вам. Я буду ждать вашего возвращения в лагере. Ах да, перед уходом поговорите со Скуэрто: он расскажет вам обо всем, что нужно.','Поговорите со Скуэрто в Опорном пункте, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чары ученика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, $n. Самоцвет нужно только прижать к одному из пьедесталов у основания башни, чтобы активировать ее защитные силы. Используйте его, когда будете готовы войти в башню и искать остальные принадлежащие Трелану предметы.$B$BУдачи вам. Я буду ждать вашего возвращения в лагере. Ах да, перед уходом поговорите со Скуэрто: он расскажет вам обо всем, что нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со Скуэрто в Опорном пункте, что на Нагорье Арати.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (696,'Атака на башню','Вот что тебе нужно найти: талисман Трелана, сферу Трелана да угольный агат Трелана.$B$BВсе эти три предмета должны быть в сундуках в башне, и ты спокойненько откроешь эти сундуки; главное – берегись огров.$B$BЗащитники башни не будут ими заниматься; придется тебе свое оружие держать наготове. Эти огры сообразят, что ты там и пытаешься обокрасть их – ясное дело, они решат задать тебе взбучку.$B$BБудь $gосторожен:осторожна; – и удачи!','Найдите талисман, сферу и угольный агат Трелана и принесите их Скуэрто в Опорный пункт.','Вернитесь к Скуэрто на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака на башню',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот что тебе нужно найти: талисман Трелана, сферу Трелана да угольный агат Трелана.$B$BВсе эти три предмета должны быть в сундуках в башне, и ты спокойненько откроешь эти сундуки; главное – берегись огров.$B$BЗащитники башни не будут ими заниматься; придется тебе свое оружие держать наготове. Эти огры сообразят, что ты там и пытаешься обокрасть их – ясное дело, они решат задать тебе взбучку.$B$BБудь $gосторожен:осторожна; – и удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите талисман, сферу и угольный агат Трелана и принесите их Скуэрто в Опорный пункт.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скуэрто на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (697,'Просьба Малина','Отвезите это письмо обратно в Штормград и скажите Малину, что мы с Крайтеном скоро будем дома. Он хорошо вознаградит вас за помощь нам, $n, в этом-то я не сомневаюсь.$B$BДоброго пути!','Отвезите запечатанное письмо верховному магу Малину в Квартал Магов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Малина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отвезите это письмо обратно в Штормград и скажите Малину, что мы с Крайтеном скоро будем дома. Он хорошо вознаградит вас за помощь нам, $n, в этом-то я не сомневаюсь.$B$BДоброго пути!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отвезите запечатанное письмо верховному магу Малину в Квартал Магов Штормграда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (697,'<Archmage Malin opens the letter, and his eyes grow wide.>$B$BBy the Light, you\'ve done it. How wonderful. Trelane will be so pleased. I\'m sure Kryten and Skuerto are just as excited as I am to have them on their way back to Stormwind.$B$BThank you, $n. Please, take this to help you in your journeys.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Archmage Malin opens the letter, and his eyes grow wide.>$B$BBy the Light, you\'ve done it. How wonderful. Trelane will be so pleased. I\'m sure Kryten and Skuerto are just as excited as I am to have them on their way back to Stormwind.$B$BThank you, $n. Please, take this to help you in your journeys.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (698,'Нехватка ресурсов','Я стараюсь добыть припасы для нашего поста на побережье, к востоку отсюда. Ток\'Кар делает, что может, но после несения караульной службы и приготовления пищи для солдат, времени у него остается немного.$B$BОни любят мясо острозубов, но у меня до сих пор не было возможности отправить им новую партию. Ты не $gмог:могла; бы помочь?$B$BМолодые острозубые кроколиски не так вкусны, как взрослые особи, так что дай им еще год-другой подрасти.','Принесите Ток\'Кару в Болотах Печали 8 сырых боков острозубых кроколисков.','Прекрасно! Свежее мясо к ужину! Спасибо, $N.$B$BНынешний вечерок будет куда приятнее прошлого – мы наедимся досыта.$B$BПускай Дар – орк на морду ужасный, зато добрый внутри.','Лок\'тар, $C. Путешествие через болота легким не назовешь. Ты действительно отважен, раз решился на это.','Вернитесь к Ток\'Кару на Тростниковую заставу, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нехватка ресурсов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я стараюсь добыть припасы для нашего поста на побережье, к востоку отсюда. Ток\'Кар делает, что может, но после несения караульной службы и приготовления пищи для солдат, времени у него остается немного.$B$BОни любят мясо острозубов, но у меня до сих пор не было возможности отправить им новую партию. Ты не $gмог:могла; бы помочь?$B$BМолодые острозубые кроколиски не так вкусны, как взрослые особи, так что дай им еще год-другой подрасти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ток\'Кару в Болотах Печали 8 сырых боков острозубых кроколисков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Свежее мясо к ужину! Спасибо, $N.$B$BНынешний вечерок будет куда приятнее прошлого – мы наедимся досыта.$B$BПускай Дар – орк на морду ужасный, зато добрый внутри.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лок\'тар, $C. Путешествие через болота легким не назовешь. Ты действительно отважен, раз решился на это.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ток\'Кару на Тростниковую заставу, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (699,'Нехватка ресурсов','Мурлоки на побережье представляют опасность, поэтому нас послали сюда отразить эту угрозу Каменору или, если силы врага окажутся слишком велики, поднять тревогу. Отдыхать нам особо некогда, и мы не откажемся от твоей помощи. $B$BИз когтей острозубого крепкохвата выходит неплохое оружие, если выделать их должным образом. Раздобудь немного для нас, и ты получишь оружие нашей работы в благодарность за свежее мясо и хорошую компанию.','Принесите 6 когтей острозубого крепкохвата Ток\'Кару на Болота Печали.','Рад видеть тебя живым и здоровым, $N.$B$BЭти когти нам весьма пригодятся, ведь чем больше оружия у нас будет в момент атаки, тем лучше.$B$BНачну работу над твоим экземпляром как можно скорее, много времени это не займет, я уже наловчился его изготавливать.','Добрая медовуха, костер, армия орков и запас оружия – это то, что надо! Я не жалею, что нас послали сюда охранять Каменор, но было бы неплохо однажды сделать здесь хороший бункер или хотя бы поставить башню.','Вернитесь к Ток\'Кару на Тростниковую заставу, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нехватка ресурсов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мурлоки на побережье представляют опасность, поэтому нас послали сюда отразить эту угрозу Каменору или, если силы врага окажутся слишком велики, поднять тревогу. Отдыхать нам особо некогда, и мы не откажемся от твоей помощи. $B$BИз когтей острозубого крепкохвата выходит неплохое оружие, если выделать их должным образом. Раздобудь немного для нас, и ты получишь оружие нашей работы в благодарность за свежее мясо и хорошую компанию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 когтей острозубого крепкохвата Ток\'Кару на Болота Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад видеть тебя живым и здоровым, $N.$B$BЭти когти нам весьма пригодятся, ведь чем больше оружия у нас будет в момент атаки, тем лучше.$B$BНачну работу над твоим экземпляром как можно скорее, много времени это не займет, я уже наловчился его изготавливать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добрая медовуха, костер, армия орков и запас оружия – это то, что надо! Я не жалею, что нас послали сюда охранять Каменор, но было бы неплохо однажды сделать здесь хороший бункер или хотя бы поставить башню.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ток\'Кару на Тростниковую заставу, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (700,'Королевские почести','Ах, какой прекрасный камень доставляют из Лордерона! Как жаль, что этот край лежит в разрухе.$b$bНо памятник получился весьма хорош! Думаю, король будет очень им доволен.$b$bТеперь же, будьте добры, пошлите государю весть, что памятник выполнен, как он и просил.','Доставьте известие королю Магни Бронзобороду.','Гранит – такая малость по сравнению с жизнью достойного дворфа. Но ни один дворф в этом мире не вечен.$B$BБудем надеяться, что этот мемориал станет напоминанием будущим поколениям великого Азерота. Мы никогда не забудем, что за них отдали жизнь отважные солдаты вроде Салли Баллу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королевские почести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, какой прекрасный камень доставляют из Лордерона! Как жаль, что этот край лежит в разрухе.$b$bНо памятник получился весьма хорош! Думаю, король будет очень им доволен.$b$bТеперь же, будьте добры, пошлите государю весть, что памятник выполнен, как он и просил.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте известие королю Магни Бронзобороду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гранит – такая малость по сравнению с жизнью достойного дворфа. Но ни один дворф в этом мире не вечен.$B$BБудем надеяться, что этот мемориал станет напоминанием будущим поколениям великого Азерота. Мы никогда не забудем, что за них отдали жизнь отважные солдаты вроде Салли Баллу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (701,'Коварство ящера','При наличии дополнительных компонентов я смогу изготовить предмет, который наделит Гор\'муля коварством ящера! Когда сила ящера проникнет в Гор\'муля, он узнает о нашем новом могуществе, и спящий в его душе воин снова пробудится!$b$bДля того чтобы создать предмет и соответствующее заклинание, мне потребуются сердца ящеров.','Добудьте для Тор\'гана 12 сердец ящера, вырвав их у плотоглотов нагорья.','Да, эти отлично подойдут. Я перенесу силу и дух ящеров в эту сферу. Она наделит Гор\'муля огненной силой и разумом ящеров.','Я все приготовил, теперь мне нужны лишь сердца ящера.','Вернитесь к Тор\'гану в Павший Молот, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коварство ящера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При наличии дополнительных компонентов я смогу изготовить предмет, который наделит Гор\'муля коварством ящера! Когда сила ящера проникнет в Гор\'муля, он узнает о нашем новом могуществе, и спящий в его душе воин снова пробудится!$b$bДля того чтобы создать предмет и соответствующее заклинание, мне потребуются сердца ящеров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте для Тор\'гана 12 сердец ящера, вырвав их у плотоглотов нагорья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, эти отлично подойдут. Я перенесу силу и дух ящеров в эту сферу. Она наделит Гор\'муля огненной силой и разумом ящеров.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я все приготовил, теперь мне нужны лишь сердца ящера.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тор\'гану в Павший Молот, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (702,'Коварство ящера','Возьмите эту сферу и используйте ее энергию, чтобы дух ящера вселился в Гор\'муля. Уверен, это взбодрит его дух и откроет новые горизонты жизни. Когда он вернется в нормальное состояние, мы сможем разъяснить ему, в каком положении находится нынче Орда, и тогда в наших непрекращающихся войнах мы сможем получить поддержку великого воина.','Отдайте сферу Тор\'гана Гор\'мулю. Его можно найти в Павшем Молоте, что на Нагорье Арати.','По крайней мере, на сей раз – что-то интересное. Оно излучает странную силу...','Это ты опять? Не хватало мне очередной порции жалости Тор\'гана.\n\nЧто ты принес на этот раз? Может, цветную ниточку? Или, может, веревку, чтобы я мог покончить со своим жалким существованием?..') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коварство ящера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьмите эту сферу и используйте ее энергию, чтобы дух ящера вселился в Гор\'муля. Уверен, это взбодрит его дух и откроет новые горизонты жизни. Когда он вернется в нормальное состояние, мы сможем разъяснить ему, в каком положении находится нынче Орда, и тогда в наших непрекращающихся войнах мы сможем получить поддержку великого воина.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте сферу Тор\'гана Гор\'мулю. Его можно найти в Павшем Молоте, что на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','По крайней мере, на сей раз – что-то интересное. Оно излучает странную силу...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это ты опять? Не хватало мне очередной порции жалости Тор\'гана.\n\nЧто ты принес на этот раз? Может, цветную ниточку? Или, может, веревку, чтобы я мог покончить со своим жалким существованием?..',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (703,'Жареные крылышки канюка','О, жареные крылышки канюка, я их просто обожаю! Такие нежные, сочные, с густым соусом, ммм... Стоит только почуять запах – просто слюнки текут! $B$BЯ прекрасно их готовлю – пальчики оближешь, как раз собирался сварганить их сегодня на ужин, но... У меня есть все, кроме основного ингредиента – крылышек! Добудешь мне крылышек – может, поделюсь рецептом!','Принесите 4 крылышка канюка Ригглфаззу.','Вернитесь к Ригглфаззу в Долину Клыков, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жареные крылышки канюка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, жареные крылышки канюка, я их просто обожаю! Такие нежные, сочные, с густым соусом, ммм... Стоит только почуять запах – просто слюнки текут! $B$BЯ прекрасно их готовлю – пальчики оближешь, как раз собирался сварганить их сегодня на ужин, но... У меня есть все, кроме основного ингредиента – крылышек! Добудешь мне крылышек – может, поделюсь рецептом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 крылышка канюка Ригглфаззу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ригглфаззу в Долину Клыков, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (704,'Судьба Эгмонда','Последний рапорт от Эгмонда был весьма тревожен, возможно, бедняги уже нет в живых! Он сообщил, что его землекопы обнаружили некие "древние погребальные урны" на раскопках близ Ульдамана. Боюсь, эта находка привлекла внимание троггов, так же как и идолы, найденные мною здесь. $B$BМне нужно получить эти урны для исследований. Отправляйся к раскопкам Ульдамана, собери урны и возвращайся ко мне','Принесите 4 резные каменные урны геологу Сталекруту в Лок Модан.','Вернитесь к геологу Сталекруту на Раскопки Сталекрута, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Эгмонда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последний рапорт от Эгмонда был весьма тревожен, возможно, бедняги уже нет в живых! Он сообщил, что его землекопы обнаружили некие "древние погребальные урны" на раскопках близ Ульдамана. Боюсь, эта находка привлекла внимание троггов, так же как и идолы, найденные мною здесь. $B$BМне нужно получить эти урны для исследований. Отправляйся к раскопкам Ульдамана, собери урны и возвращайся ко мне',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 резные каменные урны геологу Сталекруту в Лок Модан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Сталекруту на Раскопки Сталекрута, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (705,'В поисках жемчуга','Бесплодные земли – неприятное местечко, кишащее коварными хищниками и стервятниками. Жуткое, жуткое местечко, особенно для маленького гоблина. Чтобы выжить, приходится постоянно изворачиваться. $B$BУ меня есть секрет изготовления световых бомб. Я использую их, чтобы отпугивать хищников. Сейчас у меня заканчивается запас ингредиентов, а именно: порошок синего жемчуга. Добудь мне его, и вознаграждение не заставит себя ждать. $B$BНадеюсь, обувь у тебя прочная? Синий жемчуг можно найти в раковинах моллюсков на Коварном рифе. $B$BДа-да, том самом Коварном рифе в Тернистой долине!','Принесите 9 синих жемчужин Ригглфаззу в Бесплодные земли.','Вернитесь к Ригглфаззу в Долину Клыков, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках жемчуга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бесплодные земли – неприятное местечко, кишащее коварными хищниками и стервятниками. Жуткое, жуткое местечко, особенно для маленького гоблина. Чтобы выжить, приходится постоянно изворачиваться. $B$BУ меня есть секрет изготовления световых бомб. Я использую их, чтобы отпугивать хищников. Сейчас у меня заканчивается запас ингредиентов, а именно: порошок синего жемчуга. Добудь мне его, и вознаграждение не заставит себя ждать. $B$BНадеюсь, обувь у тебя прочная? Синий жемчуг можно найти в раковинах моллюсков на Коварном рифе. $B$BДа-да, том самом Коварном рифе в Тернистой долине!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 9 синих жемчужин Ригглфаззу в Бесплодные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ригглфаззу в Долину Клыков, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (706,'Чары яркого пламени','В бытность мою учеником Феранора Железной Лапы, я перенял у него технику усиления оружия с помощью наложения огненных чар. Слыхал, Феранор нынче работает в кузне при охотничьем отряде в Лордероне. $b$bНе буду пока забивать тебе голову подробностями, скажу только, что для наведения чар требуется очень редкий ингредиент – кровь из еще бьющегося сердца детеныша черного дракона. Мне надо занять себя чем-то в ожидании распоряжений из Стальгорна, так что если принесешь мне сердце, я продемонстрирую тебе свое умение. Драконов найдешь в долине Летлор.','Принесите сердце черного дракона Сигруну Рудотесу.','Вернитесь к Сигруну Рудотесу в Бесплодные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чары яркого пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В бытность мою учеником Феранора Железной Лапы, я перенял у него технику усиления оружия с помощью наложения огненных чар. Слыхал, Феранор нынче работает в кузне при охотничьем отряде в Лордероне. $b$bНе буду пока забивать тебе голову подробностями, скажу только, что для наведения чар требуется очень редкий ингредиент – кровь из еще бьющегося сердца детеныша черного дракона. Мне надо занять себя чем-то в ожидании распоряжений из Стальгорна, так что если принесешь мне сердце, я продемонстрирую тебе свое умение. Драконов найдешь в долине Летлор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сердце черного дракона Сигруну Рудотесу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сигруну Рудотесу в Бесплодные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (707,'Вы нужны Сталекруту!','$n. Я получил отчет геолога Сталекрута о ходе раскопок в Лок Модане. Ему нужен курьер для осуществления контроля за другими нашими земляными работами.$B$BБольше ничего сказать не могу, но если желаешь ноги поразмять, отправляйся к Сталекруту.','Поговорите с геологом Сталекрутом на раскопках Сталекрута близ озера Лок.','Значит, тебя послал Грозовая Вершина, да? Хорошо.$B$BУ меня есть для тебя важное поручение...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вы нужны Сталекруту!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n. Я получил отчет геолога Сталекрута о ходе раскопок в Лок Модане. Ему нужен курьер для осуществления контроля за другими нашими земляными работами.$B$BБольше ничего сказать не могу, но если желаешь ноги поразмять, отправляйся к Сталекруту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с геологом Сталекрутом на раскопках Сталекрута близ озера Лок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, тебя послал Грозовая Вершина, да? Хорошо.$B$BУ меня есть для тебя важное поручение...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (708,'Черный ящик','Поверхность этого металлического черного ящика изъедена ржавчиной, как будто его погружали в кислоту – похоже, он долго пролежал в желудке гигантского кондора. $B$BНа днище ящика выбит какой-то символ и надпись под ним: "Орудие #19 – Осадная бригада Стальгорна".','Отнесите заржавевший черный ящик в оружейную Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный ящик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поверхность этого металлического черного ящика изъедена ржавчиной, как будто его погружали в кислоту – похоже, он долго пролежал в желудке гигантского кондора. $B$BНа днище ящика выбит какой-то символ и надпись под ним: "Орудие #19 – Осадная бригада Стальгорна".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите заржавевший черный ящик в оружейную Стальгорна.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (709,'Лекарство от судьбы','О небеса милосердные! Сама судьба стучится в двери! Помяните мое слово! Рок! Фатум! $B$BНет, я не могу более ничего сказать... Не могу поминать их имен, чтобы они не услышали меня! Но если нам удастся хотя бы узнать о них больше... Может, мы сможем противостоять им! $B$BМожет быть... $B$BИди в Ульдаман – проклятье, я все же произнес это! Найди табличку... табличку Рьюнэха. Да, найди ее! Не заставляй меня повторять! $B$BОна там, в глубине, в древнем сундуке, более древнем, чем любая доселе найденная работа дворфов.','Принесите табличку Рьюн\'эха Тельдарину Заблудшему.','Вернитесь к Тельдарину Заблудшему в Удел Эгмонда, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лекарство от судьбы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О небеса милосердные! Сама судьба стучится в двери! Помяните мое слово! Рок! Фатум! $B$BНет, я не могу более ничего сказать... Не могу поминать их имен, чтобы они не услышали меня! Но если нам удастся хотя бы узнать о них больше... Может, мы сможем противостоять им! $B$BМожет быть... $B$BИди в Ульдаман – проклятье, я все же произнес это! Найди табличку... табличку Рьюнэха. Да, найди ее! Не заставляй меня повторять! $B$BОна там, в глубине, в древнем сундуке, более древнем, чем любая доселе найденная работа дворфов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите табличку Рьюн\'эха Тельдарину Заблудшему.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тельдарину Заблудшему в Удел Эгмонда, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (710,'Изучение стихий: Камень','Здесь, в Бесплодных землях, мне пришлось приостановить работу над моим последним изобретением – оковами Стихий. $B$BКогда они будут закончены, то позволят вызывать еще более мощных элементалей и управлять ими.Чтобы продолжить работу, мне нужны маленькие осколки камня, чтобы опробовать на них некоторые новые заклинания и механизмы. $B$BМаленькие осколки камня, которые можно собрать с младших каменных элементалей, как раз подойдут. Они водятся к западу отсюда, сбегай-ка туда быстренько.','Соберите 10 маленьких осколков камня и принесите Лотвилю Вериатусу в Бесплодные земли.','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение стихий: Камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, в Бесплодных землях, мне пришлось приостановить работу над моим последним изобретением – оковами Стихий. $B$BКогда они будут закончены, то позволят вызывать еще более мощных элементалей и управлять ими.Чтобы продолжить работу, мне нужны маленькие осколки камня, чтобы опробовать на них некоторые новые заклинания и механизмы. $B$BМаленькие осколки камня, которые можно собрать с младших каменных элементалей, как раз подойдут. Они водятся к западу отсюда, сбегай-ка туда быстренько.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 маленьких осколков камня и принесите Лотвилю Вериатусу в Бесплодные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (711,'Изучение стихий: Камень','$n, ты уже $gпроявил:проявила; себя более $gспособным:способной;, чем все мои ученики вместе взятые. $B$BТеперь мне потребуется сила твоих мускулов. У каменных элементалей при должной осторожности можно найти большие каменные глыбы. Они достаточно велики и тверды, чтобы отколоть от них куски, удобные для исследования. Ты найдешь их у подножия гор к западу или юго-востоку отсюда. $B$BМожешь не торопиться, я пока займусь исследованием более мелких кусочков, которые ты $gпринес:принесла; мне.','Принесите 3 больших куска камня Лотвилю Вериатусу в Бесплодные земли.','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение стихий: Камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты уже $gпроявил:проявила; себя более $gспособным:способной;, чем все мои ученики вместе взятые. $B$BТеперь мне потребуется сила твоих мускулов. У каменных элементалей при должной осторожности можно найти большие каменные глыбы. Они достаточно велики и тверды, чтобы отколоть от них куски, удобные для исследования. Ты найдешь их у подножия гор к западу или юго-востоку отсюда. $B$BМожешь не торопиться, я пока займусь исследованием более мелких кусочков, которые ты $gпринес:принесла; мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 больших куска камня Лотвилю Вериатусу в Бесплодные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (712,'Изучение стихий: Камень','$n, мне нужно, чтобы ты $gпринес:принесла; мне еще кое-что – браслеты каменных элементалей. Полагаю, с помощью этих браслетов можно оценить прочность моих кандалов. $B$BВ магическом кристалле я видел нескольких каменных элементалей к юго-западу отсюда. Недалеко от них я заметил еще и нескольких огров. $B$BПринеси-ка мне 5 браслетов, чтобы было с запасом. Мой Серво славится умением путать все реагенты и результаты исследований.','Принесите 5 браслетов Камня Лотвилю Вериатусу в Бесплодные земли.','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение стихий: Камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мне нужно, чтобы ты $gпринес:принесла; мне еще кое-что – браслеты каменных элементалей. Полагаю, с помощью этих браслетов можно оценить прочность моих кандалов. $B$BВ магическом кристалле я видел нескольких каменных элементалей к юго-западу отсюда. Недалеко от них я заметил еще и нескольких огров. $B$BПринеси-ка мне 5 браслетов, чтобы было с запасом. Мой Серво славится умением путать все реагенты и результаты исследований.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 браслетов Камня Лотвилю Вериатусу в Бесплодные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (713,'Охлаждение горячих голов','Послушай, я расскажу тебе о масле льда – это лучшее средство для того, чтобы уберечь мотор или механизмы от перегрева. $B$BЕго охлаждающая способность просто потрясает, а его долговечность в качестве смазочного материала просто не имеет равных. И это еще не все: оно позволяет сохранять чары на магических предметах. $B$BМне нужен сосуд этого масла, чтобы усилить магический потенциал кандалов моей работы и сделать их достаточно мощными, чтобы вызванный нами дух не прикончил нас на месте.$B$BБрокин, мой друг-гоблин, научит тебя, как изготовить масло. Ты найдешь его в Альтераке.','Найдите масло льда и принесите его Лотвилю Вериатусу в Бесплодные земли.','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охлаждение горячих голов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, я расскажу тебе о масле льда – это лучшее средство для того, чтобы уберечь мотор или механизмы от перегрева. $B$BЕго охлаждающая способность просто потрясает, а его долговечность в качестве смазочного материала просто не имеет равных. И это еще не все: оно позволяет сохранять чары на магических предметах. $B$BМне нужен сосуд этого масла, чтобы усилить магический потенциал кандалов моей работы и сделать их достаточно мощными, чтобы вызванный нами дух не прикончил нас на месте.$B$BБрокин, мой друг-гоблин, научит тебя, как изготовить масло. Ты найдешь его в Альтераке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите масло льда и принесите его Лотвилю Вериатусу в Бесплодные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (714,'Гиро...чего?','$n, ты $gсправился:справилась; со своей работой выше всяких похвал.$B$B*Мысли Лотвила явно витают где-то в его экспериментах.*$B$BБудешь у нас в Караносе, приходи ко мне работать, приму в любое время с распростертыми...$B$BОп-ля! Лови-лови, скорей! Да, спасибо.$B$BА сейчас мне нужна всего лишь одна малость. Довольно маленькая штуковина, но очень важная: гирохронатом.$B$BЕсли сможешь мне его добыть, я, наконец, смогу закончить этот эксперимент.','Принесите гирохронатом Лотвилю Вериатусу в Бесплодные земли.','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гиро...чего?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты $gсправился:справилась; со своей работой выше всяких похвал.$B$B*Мысли Лотвила явно витают где-то в его экспериментах.*$B$BБудешь у нас в Караносе, приходи ко мне работать, приму в любое время с распростертыми...$B$BОп-ля! Лови-лови, скорей! Да, спасибо.$B$BА сейчас мне нужна всего лишь одна малость. Довольно маленькая штуковина, но очень важная: гирохронатом.$B$BЕсли сможешь мне его добыть, я, наконец, смогу закончить этот эксперимент.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите гирохронатом Лотвилю Вериатусу в Бесплодные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (715,'Жидкий камень','Полагаю, все задачи, поставленные перед тобой Лотвилом, вскоре покажутся тебе очень простыми по сравнению с тем, что ждет впереди. С другой стороны, ты $gдоказал:доказала; свою приверженность наукам, которые так чтит Лотвил. Не поможешь ли ты, в таком случае, и мне? $B$BМне необходимо лечебное зелье и зелье невидимости. Похоже, и то, и другое может мне вскоре понадобиться, если Лотвил продолжит в том же духе. $B$BВзамен я дам тебе рецепт зелья, разработанный мной во время обучения у Лотвила. Рецепт основан на сведениях, собранных им во время экспериментов здесь, в Бесплодных землях.','Принесите зелье простой невидимости и лечебное зелье Люсьену Подай-Ключ в Бесплодные земли.','Вернитесь к Люсьену Подай-Ключ в Знойные Пески, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жидкий камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полагаю, все задачи, поставленные перед тобой Лотвилом, вскоре покажутся тебе очень простыми по сравнению с тем, что ждет впереди. С другой стороны, ты $gдоказал:доказала; свою приверженность наукам, которые так чтит Лотвил. Не поможешь ли ты, в таком случае, и мне? $B$BМне необходимо лечебное зелье и зелье невидимости. Похоже, и то, и другое может мне вскоре понадобиться, если Лотвил продолжит в том же духе. $B$BВзамен я дам тебе рецепт зелья, разработанный мной во время обучения у Лотвила. Рецепт основан на сведениях, собранных им во время экспериментов здесь, в Бесплодных землях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите зелье простой невидимости и лечебное зелье Люсьену Подай-Ключ в Бесплодные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Люсьену Подай-Ключ в Знойные Пески, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (716,'Камень – лучшая одежка!','Я знаю, каким скупым бывает Лотвил, $n, поэтому хочу сам вознаградить тебя за труды. Возможно, мой подарок даже поможет тебе защититься от того, что сулит это его новое изобретение... $B$BЯ собрал все неиспользованные камни, которые ты $gпринес:принесла;, и смогу сделать из них прекрасные наручи, которые наверняка тебе понадобятся. Разумеется, они будут магическими. $B$BНо мне потребуются украшенные узором бронзовые наручи, созданные кузнецом, чтобы я смог закончить работу.','Принесите украшенные узором бронзовые наручи Люсьену Подай-Ключ в Бесплодные земли.','Вернитесь к Люсьену Подай-Ключ в Знойные Пески, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камень – лучшая одежка!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, каким скупым бывает Лотвил, $n, поэтому хочу сам вознаградить тебя за труды. Возможно, мой подарок даже поможет тебе защититься от того, что сулит это его новое изобретение... $B$BЯ собрал все неиспользованные камни, которые ты $gпринес:принесла;, и смогу сделать из них прекрасные наручи, которые наверняка тебе понадобятся. Разумеется, они будут магическими. $B$BНо мне потребуются украшенные узором бронзовые наручи, созданные кузнецом, чтобы я смог закончить работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите украшенные узором бронзовые наручи Люсьену Подай-Ключ в Бесплодные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Люсьену Подай-Ключ в Знойные Пески, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (717,'Дрожь земли','Сейчас уже очевидно, что мы не можем быть уверены, что Чернохлыст и Гематус заключены в Летлоре надежно. Там обосновались черные драконы, кроме того, этим ограм удалось завладеть знаком земли – а это значит, что требуются куда более серьезные меры. $b$bДраконье узилище заперто тремя рунными камнями, которые можно заполучить только с помощью знака земли. Камни нужны, чтобы сломать печать на узилище. $b$bСломай печать и сделай так, чтобы драконы упокоились навек.','С помощью знака земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни. $b$bПоместите рунные камни на печать земли и освободите драконов Чернохлыста и Гематуса. $b$bУбейте драконов и принесите Гареку наручники Чернохлыста, цепи Гематуса и знак земли.','Вернитесь к Гареку в Карьер Тяжелоступа, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дрожь земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сейчас уже очевидно, что мы не можем быть уверены, что Чернохлыст и Гематус заключены в Летлоре надежно. Там обосновались черные драконы, кроме того, этим ограм удалось завладеть знаком земли – а это значит, что требуются куда более серьезные меры. $b$bДраконье узилище заперто тремя рунными камнями, которые можно заполучить только с помощью знака земли. Камни нужны, чтобы сломать печать на узилище. $b$bСломай печать и сделай так, чтобы драконы упокоились навек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью знака земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни. $b$bПоместите рунные камни на печать земли и освободите драконов Чернохлыста и Гематуса. $b$bУбейте драконов и принесите Гареку наручники Чернохлыста, цепи Гематуса и знак земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гареку в Карьер Тяжелоступа, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (718,'Миражи','В спешке покидая Ульдаман, мы были вынуждены бросить не одну повозку и ящик с припасами. Местные огры из лагеря Кош набросились на них, как стервятники на падаль. Хотя воняют огры не лучше... чем падаль, я имею в виду. $b$bВ общем, они растащили все наши обозы с оружием и прочим скарбом и... Короче, мне даже неловко об этом говорить, но мы тут остались слегка совсем без еды... $b$bНе $gмог:могла; ли бы ты нам помочь?','Верните ящик с припасами Сигруну Рудотесу.','Вернитесь к Сигруну Рудотесу в Бесплодные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Миражи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В спешке покидая Ульдаман, мы были вынуждены бросить не одну повозку и ящик с припасами. Местные огры из лагеря Кош набросились на них, как стервятники на падаль. Хотя воняют огры не лучше... чем падаль, я имею в виду. $b$bВ общем, они растащили все наши обозы с оружием и прочим скарбом и... Короче, мне даже неловко об этом говорить, но мы тут остались слегка совсем без еды... $b$bНе $gмог:могла; ли бы ты нам помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните ящик с припасами Сигруну Рудотесу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сигруну Рудотесу в Бесплодные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (719,'Дворф и его инструменты','Будь $gосторожен:осторожна;, $n! Повсюду шныряют дворфы Черного Железа – видимо, из клана Тенегорн. $B$BОни только что напали на наш раскоп и почитай всех там вырезали, включая моего шефа Тяжелоступа. Я едва ноги унес.$B$BРаскоп прямо к северу отсюда. Я вот прикидываю, как бы выручить оттуда часть наших припасов, особенно мою счастливую кирку.$B$BКак думаешь – сумеешь помочь? Наверняка кто-нибудь из этих гадов Черного Железа спер мою кирку!','Найдите счастливую кирку Ржанца и верните ее геологу Ржанцу к югу от карьера Тяжелоступа.','Вернитесь к геологу Ржанцу в Бесплодные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дворф и его инструменты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Будь $gосторожен:осторожна;, $n! Повсюду шныряют дворфы Черного Железа – видимо, из клана Тенегорн. $B$BОни только что напали на наш раскоп и почитай всех там вырезали, включая моего шефа Тяжелоступа. Я едва ноги унес.$B$BРаскоп прямо к северу отсюда. Я вот прикидываю, как бы выручить оттуда часть наших припасов, особенно мою счастливую кирку.$B$BКак думаешь – сумеешь помочь? Наверняка кто-нибудь из этих гадов Черного Железа спер мою кирку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите счастливую кирку Ржанца и верните ее геологу Ржанцу к югу от карьера Тяжелоступа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Ржанцу в Бесплодные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (720,'Предвестник надежды','<куском мела на карте нацарапаны слова>"Ржанец, они уводят меня в Ульдаман. Пришли помощь!$B-Тяжелоступ"','Найдите геолога Ржанца и сообщите, что Грез Тяжелоступ жив.','Поговорите с геологом Ржанцем в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предвестник надежды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<куском мела на карте нацарапаны слова>"Ржанец, они уводят меня в Ульдаман. Пришли помощь!$B-Тяжелоступ"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите геолога Ржанца и сообщите, что Грез Тяжелоступ жив.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с геологом Ржанцем в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (721,'Предвестник надежды','$n, ты сможешь разыскать его? Ты разыщешь Тяжелоступа? $B$BПроклятые дворфы из Тенегорна схватили его, чтобы выпытать, что он знает о раскопках поселения титанов. Если это случится, весь Стальгорн будет в большой опасности! $B$BДворфы Черного Железа уже давно разыскивают способы сотворения могущественных големов. Конечно, такова была цель и Тяжелоступа, но это только для того, чтобы остановить Черное Железо!$B$BВозможно, они сохранят ему жизнь, пока не вытянут из него все секреты. Поспеши, быть может, его еще удастся спасти!','Найдите Греза Тяжелоступа в Ульдамане.','О, я так ослабел... <кашляет> Подойди ко мне, $C?$B$BТебя прислал Рейдол? Клянусь Мурадином, парень вовсе не так туп, как кажется.<кашляет>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предвестник надежды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты сможешь разыскать его? Ты разыщешь Тяжелоступа? $B$BПроклятые дворфы из Тенегорна схватили его, чтобы выпытать, что он знает о раскопках поселения титанов. Если это случится, весь Стальгорн будет в большой опасности! $B$BДворфы Черного Железа уже давно разыскивают способы сотворения могущественных големов. Конечно, такова была цель и Тяжелоступа, но это только для того, чтобы остановить Черное Железо!$B$BВозможно, они сохранят ему жизнь, пока не вытянут из него все секреты. Поспеши, быть может, его еще удастся спасти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Греза Тяжелоступа в Ульдамане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, я так ослабел... <кашляет> Подойди ко мне, $C?$B$BТебя прислал Рейдол? Клянусь Мурадином, парень вовсе не так туп, как кажется.<кашляет>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (722,'Амулет тайн','Тебе не занимать смелости, раз ты $gявился:явилась; за мной в Ульдаман, |3-6($c).$B$BЕсли в самом деле хочешь помочь старику Тяжелоступу... *кашляет*... Найди мне мой амулет. $B$BЭто Чернотень... Его забрал Магреган Чернотень. Он здесь, в развалинах, я знаю... Этот амулет приведет их... *кашляет* прямо к свиткам, если их не остановить... Все в твоих руках, $n! Пожалуйста... верни амулет. $B$BЕсли свитки попадут к ним в лапы, Черное Железо сможет создавать еще более мощных големов. Я знаю, я это нутром чую!','Найдите амулет Тяжелоступа и верните его ему в Ульдаман.','Ха!<кхе, кхе>$B$BЯ знал, что ты справишься! <сморкается> Отличная работа, $N.<кашляет>','Клан Тенегорна очень опасен! Будь $Gосторожен:осторожна;. Вы должны найти амулет.','Вернитесь к Тяжелоступу Грез в Ульдаман.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амулет тайн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе не занимать смелости, раз ты $gявился:явилась; за мной в Ульдаман, |3-6($c).$B$BЕсли в самом деле хочешь помочь старику Тяжелоступу... *кашляет*... Найди мне мой амулет. $B$BЭто Чернотень... Его забрал Магреган Чернотень. Он здесь, в развалинах, я знаю... Этот амулет приведет их... *кашляет* прямо к свиткам, если их не остановить... Все в твоих руках, $n! Пожалуйста... верни амулет. $B$BЕсли свитки попадут к ним в лапы, Черное Железо сможет создавать еще более мощных големов. Я знаю, я это нутром чую!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите амулет Тяжелоступа и верните его ему в Ульдаман.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха!<кхе, кхе>$B$BЯ знал, что ты справишься! <сморкается> Отличная работа, $N.<кашляет>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Клан Тенегорна очень опасен! Будь $Gосторожен:осторожна;. Вы должны найти амулет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тяжелоступу Грез в Ульдаман.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (723,'Клятва верности','<Тяжелоступ едва дышит и, собрав последние силы, поизносит>$B$BНайди Ржанца, $n! Передай ему мой амулет... <кашляет> Он знает, что делать. <кашляет> Он знает, я искал истоки происхождения нашего народа, <кашляет> знает и то, что целью моей жизни было остановить клан Тенегорн. Нельзя позволить, чтобы они нашли свитки... <кашляет>','Отнесите амулет Тяжелоступа геологу Ржанцу в Бесплодные земли.','Амулет Тяжелоступа! Если раньше в моем сердце еще теплилась надежда, что он жив, то теперь ничто не снимет с моей души этот камень. Этот амулет – дело всей его жизни. Нельзя допустить, чтобы его смерть была напрасной!','Сегодня дурной день. Однако в Бесплодных землях каждый день убивает надежду.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клятва верности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Тяжелоступ едва дышит и, собрав последние силы, поизносит>$B$BНайди Ржанца, $n! Передай ему мой амулет... <кашляет> Он знает, что делать. <кашляет> Он знает, я искал истоки происхождения нашего народа, <кашляет> знает и то, что целью моей жизни было остановить клан Тенегорн. Нельзя позволить, чтобы они нашли свитки... <кашляет>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите амулет Тяжелоступа геологу Ржанцу в Бесплодные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Амулет Тяжелоступа! Если раньше в моем сердце еще теплилась надежда, что он жив, то теперь ничто не снимет с моей души этот камень. Этот амулет – дело всей его жизни. Нельзя допустить, чтобы его смерть была напрасной!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сегодня дурной день. Однако в Бесплодных землях каждый день убивает надежду.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (724,'Клятва верности','К кому же обратиться за советом... $B$BИсторик Карник! Конечно! $B$BОн сейчас в Стальгорне – он точно сможет помочь! Он искал потерянные артефакты вместе с Тяжелоступом в Ульдамане. $B$BПолагаю, в Тенегорне прознали, что эти двое располагают тайными сведениями. $B$BСообщи Карнику о том, как погиб Тяжелоступ, и передай ему амулет – а он расскажет, что делать дальше.','Отнесите амулет Тяжелоступа историку Карнику в Стальгорне.','О, а вот это совсем другой разговор! Возможно, ты еще не $Gосознал:осознала; всей серьезности происходящего, ведь так?$B$BМы оплачем Тяжелоступа позже.$B$BСейчас я объясню тебе, почему этот амулет так важен.','Так-так... Еще один путник, которому что-то нужно от дворфов...$B$BСтупай своей дорогой добрый господин у меня нет времени на праздную болтовню!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клятва верности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К кому же обратиться за советом... $B$BИсторик Карник! Конечно! $B$BОн сейчас в Стальгорне – он точно сможет помочь! Он искал потерянные артефакты вместе с Тяжелоступом в Ульдамане. $B$BПолагаю, в Тенегорне прознали, что эти двое располагают тайными сведениями. $B$BСообщи Карнику о том, как погиб Тяжелоступ, и передай ему амулет – а он расскажет, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите амулет Тяжелоступа историку Карнику в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, а вот это совсем другой разговор! Возможно, ты еще не $Gосознал:осознала; всей серьезности происходящего, ведь так?$B$BМы оплачем Тяжелоступа позже.$B$BСейчас я объясню тебе, почему этот амулет так важен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так-так... Еще один путник, которому что-то нужно от дворфов...$B$BСтупай своей дорогой добрый господин у меня нет времени на праздную болтовню!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (725,'Слухи об угрозе','$n, беги, найди советника Белграма как можно скорее. Расскажи ему, что $Gвидел:видела;, и спроси, что нам делать дальше. Отдашь ему эту записку, я изложил в ней все как можно подробней. $B$BА я пока побеседую с духом Тяжелоступа. Возможно, ему известно нечто, что сможет помочь нам пресечь безумные действия Тенегорнских прихвостней в Бесплодных землях. Теперь нам остается только молиться.','Найдите советника Белграма и отдайте ему записку.','А, весточка от историка Карника. Прекрасно.$B$BДля него у меня всегда найдется минутка.$B$B<Советник Белграм разворачивает записку и погружается в чтение.>','Слушаю тебя, $C.','Поговорите с советником Белграмом в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слухи об угрозе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, беги, найди советника Белграма как можно скорее. Расскажи ему, что $Gвидел:видела;, и спроси, что нам делать дальше. Отдашь ему эту записку, я изложил в ней все как можно подробней. $B$BА я пока побеседую с духом Тяжелоступа. Возможно, ему известно нечто, что сможет помочь нам пресечь безумные действия Тенегорнских прихвостней в Бесплодных землях. Теперь нам остается только молиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите советника Белграма и отдайте ему записку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, весточка от историка Карника. Прекрасно.$B$BДля него у меня всегда найдется минутка.$B$B<Советник Белграм разворачивает записку и погружается в чтение.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Слушаю тебя, $C.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с советником Белграмом в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (726,'Слухи об угрозе','<Когда советник Белграм дочитывает письмо до конца, его глаза в ужасе расширяются>$B$BЭто дурные вести... $B$BПожалуйста, вернись к историку Карнику и извести его именем короля, что он должен действовать быстро и рассудительно. Он должен остановить Тенегорн в Бесплодных землях.','Поговорите с историком Карником.','Ты действуешь по этому делу с поспешностью, которая сделала бы честь и королю, $N!$B$BХорошо. Я знаю, что делать с Кузней Теней.$B$BИх силы в Ульдамане будут рассеяны, если мы поразим их в самое сердце – ударим по крепости Ангор.','Поговорите с историком Карником в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слухи об угрозе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Когда советник Белграм дочитывает письмо до конца, его глаза в ужасе расширяются>$B$BЭто дурные вести... $B$BПожалуйста, вернись к историку Карнику и извести его именем короля, что он должен действовать быстро и рассудительно. Он должен остановить Тенегорн в Бесплодных землях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с историком Карником.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты действуешь по этому делу с поспешностью, которая сделала бы честь и королю, $N!$B$BХорошо. Я знаю, что делать с Кузней Теней.$B$BИх силы в Ульдамане будут рассеяны, если мы поразим их в самое сердце – ударим по крепости Ангор.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с историком Карником в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (727,'В Стальгорн за книгой Йагина','Эта табличка говорит о многом. И все же этого недостаточно! $B$BЕсть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу и самые мудрые из них изучают ее. Она содержит обширные знания, и в ней можно найти ключ к спасению! $B$BОтправляйся к Геррику Костохвату. Ты найдешь его в лавке в Стальгорне, в Заброшенном гроте. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси ее мне.','Отнесите печать Молота Геррику Костохвату в Заброшенный грот в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Стальгорн за книгой Йагина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта табличка говорит о многом. И все же этого недостаточно! $B$BЕсть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу и самые мудрые из них изучают ее. Она содержит обширные знания, и в ней можно найти ключ к спасению! $B$BОтправляйся к Геррику Костохвату. Ты найдешь его в лавке в Стальгорне, в Заброшенном гроте. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси ее мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите печать Молота Геррику Костохвату в Заброшенный грот в Стальгорн.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (728,'В Подгород за книгой Йагина','Эта табличка говорит о многом. И все же этого недостаточно! $B$BЕсть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу, и самые мудрые из них изучают ее. Она содержит обширные знания, и в ней можно найти ключ к спасению! $B$BОтправляйся к хранителю Бел\'дугуру в Лордерон. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси ее мне.','Отнесите печать Молота хранителю Бел\'дугуру в Подгород.','Будь $Gосторожен:осторожена;, $C. Многие на этом свете сомневаются в праведности наших дел. И многие из них сделали бы все возможное, чтобы уничтожить нас!$B$BТы $Gдолжен:должна; всегда сохранять бдительность, осторожность и терпение...','Ага, кто это у нас тут? $GНетерпеливый:Нетерпеливая; $C, чтобы взглянуть на мою коллекцию? Милости прошу!$B$BНо помни: во многом знании много печали, и преумножающий знания преумножает скорбь...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Подгород за книгой Йагина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта табличка говорит о многом. И все же этого недостаточно! $B$BЕсть книга – древняя книга Йагина. Те, от кого я бежал... Они хранят эту книгу, и самые мудрые из них изучают ее. Она содержит обширные знания, и в ней можно найти ключ к спасению! $B$BОтправляйся к хранителю Бел\'дугуру в Лордерон. Покажешь ему эту печать, и он примет тебя за своего. Попроси у него книгу Йагина и принеси ее мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите печать Молота хранителю Бел\'дугуру в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будь $Gосторожен:осторожена;, $C. Многие на этом свете сомневаются в праведности наших дел. И многие из них сделали бы все возможное, чтобы уничтожить нас!$B$BТы $Gдолжен:должна; всегда сохранять бдительность, осторожность и терпение...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ага, кто это у нас тут? $GНетерпеливый:Нетерпеливая; $C, чтобы взглянуть на мою коллекцию? Милости прошу!$B$BНо помни: во многом знании много печали, и преумножающий знания преумножает скорбь...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (729,'Рассеянный геолог','Мне была оказана большая честь, когда мастер Седоус назначил меня работать под руководством великого геолога Сомнамбулера. В академии в Стальгорне все знают о грандиозных открытиях Сомнамбулера.$b$bНо геолог довольно... ммм... рассеян... порой кажется, что он не от мира сего.$b$bМы обнаружили признаки некогда крупного поселения. Из-под земли выскочили ужасные големы и заполонили весь раскоп. Но Сомнамбулер, казалось, так ничего и не заметил. Я побежала обратно в Аубердин за помощью.$b$bПрошу тебя, отправляйся на юг и посмотри, все ли в порядке с геологом!','Отправляйтесь на юг, найдите геолога Сомнамбулера и узнайте, как у него дела.','Это ты, Холли? Мне нужна помощь, надо подолбить этот камень. Передай-ка мне мою щетку для камня – мне кажется, я тут что-то вижу.$B$BОй, да ты не Холли! Вряд ли ты $Gвидел:видела; мою щетку для камня...$B$BА, забудь об этом! Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашел. Куда же делась Холли?$B$BТак много нужно сделать! И где ж эта таинственная окаменелость... и моя щетка... и Холли...$B$BИ ты кто будешь... правда, это неважно, если ты хочешь помочь.$B$BДай знать, когда сможешь начать поиски.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассеянный геолог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне была оказана большая честь, когда мастер Седоус назначил меня работать под руководством великого геолога Сомнамбулера. В академии в Стальгорне все знают о грандиозных открытиях Сомнамбулера.$b$bНо геолог довольно... ммм... рассеян... порой кажется, что он не от мира сего.$b$bМы обнаружили признаки некогда крупного поселения. Из-под земли выскочили ужасные големы и заполонили весь раскоп. Но Сомнамбулер, казалось, так ничего и не заметил. Я побежала обратно в Аубердин за помощью.$b$bПрошу тебя, отправляйся на юг и посмотри, все ли в порядке с геологом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на юг, найдите геолога Сомнамбулера и узнайте, как у него дела.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это ты, Холли? Мне нужна помощь, надо подолбить этот камень. Передай-ка мне мою щетку для камня – мне кажется, я тут что-то вижу.$B$BОй, да ты не Холли! Вряд ли ты $Gвидел:видела; мою щетку для камня...$B$BА, забудь об этом! Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашел. Куда же делась Холли?$B$BТак много нужно сделать! И где ж эта таинственная окаменелость... и моя щетка... и Холли...$B$BИ ты кто будешь... правда, это неважно, если ты хочешь помочь.$B$BДай знать, когда сможешь начать поиски.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (730,'Неприятности на Темных берегах?','Приятно видеть! $c, $Gинтересующийся:интересующаяся:c; великими археологическими чудесами нашего мира!$b$bЧасто наши друзья из Альянса считают нашу работу чем-то вроде развлечения. Многие просто отказываются понимать. Великая, могущественная сила угрожает всему Азероту – от Лордерона до Калимдора.$b$bМеня очень беспокоит судьба группы, которую я отправил на Темные берега. От них уже несколько недель ни слова.$b$bОтправляйся в Аубердин и попробуй узнать, где они пропадают.','Отправьтесь в Аубердин и найдите следы дворфийской изыскательской группы.','Как же здорово, что главный археолог Седой Ус прислал вас...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприятности на Темных берегах?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приятно видеть! $c, $Gинтересующийся:интересующаяся:c; великими археологическими чудесами нашего мира!$b$bЧасто наши друзья из Альянса считают нашу работу чем-то вроде развлечения. Многие просто отказываются понимать. Великая, могущественная сила угрожает всему Азероту – от Лордерона до Калимдора.$b$bМеня очень беспокоит судьба группы, которую я отправил на Темные берега. От них уже несколько недель ни слова.$b$bОтправляйся в Аубердин и попробуй узнать, где они пропадают.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь в Аубердин и найдите следы дворфийской изыскательской группы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как же здорово, что главный археолог Седой Ус прислал вас...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (731,'Рассеянный геолог','Итак, Холли... А, да, верно, ты же не Холли. А где Холли?$b$bАй, ладно, это к делу не относится. Мы должны найти эту щетку для камня... то есть я имею в виду таинственную окаменелость! Мы должны найти эту окаменелость. Лига исследователей в Дарнасе захочет узнать, чем я тут занимаюсь.$b$bСообщи мне, когда будешь $Gготов:готова;, и начнем поиски этой щетки... ну, то есть окаменелости! Мы найдем какой-нибудь документ, чтобы в Лиге остались довольны.$b$bТак что, $Gготов:готова;?','Защищайте геолога Сомнамбулера, пока он ищет таинственную окаменелость, а затем вернитесь к археологу Холли в Аубердин.','Слава звездам, геолог Сомнамбулер в безопасности! Я же говорила тебе, какой он рассеянный. Не могу поверить, что он твердо хочет остаться там, где рядом повсюду рыщут жуткие твари!','Изыскатель жив?','Защитите геолога Сомнамбулера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассеянный геолог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, Холли... А, да, верно, ты же не Холли. А где Холли?$b$bАй, ладно, это к делу не относится. Мы должны найти эту щетку для камня... то есть я имею в виду таинственную окаменелость! Мы должны найти эту окаменелость. Лига исследователей в Дарнасе захочет узнать, чем я тут занимаюсь.$b$bСообщи мне, когда будешь $Gготов:готова;, и начнем поиски этой щетки... ну, то есть окаменелости! Мы найдем какой-нибудь документ, чтобы в Лиге остались довольны.$b$bТак что, $Gготов:готова;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защищайте геолога Сомнамбулера, пока он ищет таинственную окаменелость, а затем вернитесь к археологу Холли в Аубердин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава звездам, геолог Сомнамбулер в безопасности! Я же говорила тебе, какой он рассеянный. Не могу поверить, что он твердо хочет остаться там, где рядом повсюду рыщут жуткие твари!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Изыскатель жив?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите геолога Сомнамбулера.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (732,'Дрожь земли','Сигрун сказал, что ты $gоказал:оказала; ему неоценимую помощь. Возможно, мне она тоже понадобится. Меня прислал сюда мой господин, Крас из Кирин-Тора, чтобы прекратить беспорядки в низине Летлор. $b$bЯ не имею права разглашать поставленные передо мной задачи, но можешь не сомневаться – они имеют самое первостепенное значение.$b$bШайка бродячих огров, которых видели близ лагеря Бофф, украла предмет, именуемый знаком земли. Мне необходимо вернуть этот предмет. Принеси его мне, и я расскажу тебе больше.','Принесите знак земли Гареку.','Вернитесь к Гареку в Карьер Тяжелоступа, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дрожь земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сигрун сказал, что ты $gоказал:оказала; ему неоценимую помощь. Возможно, мне она тоже понадобится. Меня прислал сюда мой господин, Крас из Кирин-Тора, чтобы прекратить беспорядки в низине Летлор. $b$bЯ не имею права разглашать поставленные передо мной задачи, но можешь не сомневаться – они имеют самое первостепенное значение.$b$bШайка бродячих огров, которых видели близ лагеря Бофф, украла предмет, именуемый знаком земли. Мне необходимо вернуть этот предмет. Принеси его мне, и я расскажу тебе больше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите знак земли Гареку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гареку в Карьер Тяжелоступа, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (732,'Good tidings you bring bearing the Sign, $n. The Sign of the Earth was created by the Dark Iron dwarves of Angor Fortress to bind two of Deathwing\'s ruthless lieutenants, the twins Blacklash and Hematus.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Good tidings you bring bearing the Sign, $n. The Sign of the Earth was created by the Dark Iron dwarves of Angor Fortress to bind two of Deathwing\'s ruthless lieutenants, the twins Blacklash and Hematus.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (733,'Помогите кто чем может!','Да, туго нам придется, если мы не сможем раздобыть материалов для возведения простейших укреплений и других нужд. Заметил я, что у огров в этих землях полно металлолома. Возможно, легенды об осадных машинах, применявшихся в Бесплодных землях, не так уж далеки от истины...$b$bВ общем, геолог очень беспокоится за состояние нашего маленького лагеря, так что надо приниматься за работу как можно скорее. $b$bГлавный лагерь огров расположен рядом с Гротом Гнилобрюхих, к западу отсюда. Учти – расстояние приличное!','Принесите 7 кусков металлолома Сигруну.','Вернитесь к Сигруну Рудотесу в Бесплодные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помогите кто чем может!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, туго нам придется, если мы не сможем раздобыть материалов для возведения простейших укреплений и других нужд. Заметил я, что у огров в этих землях полно металлолома. Возможно, легенды об осадных машинах, применявшихся в Бесплодных землях, не так уж далеки от истины...$b$bВ общем, геолог очень беспокоится за состояние нашего маленького лагеря, так что надо приниматься за работу как можно скорее. $b$bГлавный лагерь огров расположен рядом с Гротом Гнилобрюхих, к западу отсюда. Учти – расстояние приличное!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 кусков металлолома Сигруну.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сигруну Рудотесу в Бесплодные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (734,'Сложная задача','Пекрасно, прекрасно... $B$B*Лотвил на секунду отрывает взгляд от кандалов*$B$BСбегай-ка к Люсьену, $n. Мне нужен зубец#5. Принеси его мне.','Поговорите с Люсьеном Подай-Ключ в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сложная задача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пекрасно, прекрасно... $B$B*Лотвил на секунду отрывает взгляд от кандалов*$B$BСбегай-ка к Люсьену, $n. Мне нужен зубец#5. Принеси его мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Люсьеном Подай-Ключ в Бесплодных землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (735,'Звезда, Рука и Сердце','Книга Йагина, да? Вы хотите написать в ней новую главу о нас? Ну да, не мне спрашивать.$B$BЯ помогу вам – у меня как раз есть дополнительный экземпляр. Мы ведь должны друг другу помогать, не так ли? Только так мы добьемся успеха.$B$BМне нужны три предмета силы. Принесите их мне – и получите книгу.$B$BНазваний предметов я вам не скажу – нас могут подслушивать. Но я их вам напишу.','Доставьте предметы, перечисленные в записке Костохвата, Геррику Костохвату в Стальгорн.','Вернитесь к Геррику Костохвату в Заброшенный грот в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звезда, Рука и Сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Книга Йагина, да? Вы хотите написать в ней новую главу о нас? Ну да, не мне спрашивать.$B$BЯ помогу вам – у меня как раз есть дополнительный экземпляр. Мы ведь должны друг другу помогать, не так ли? Только так мы добьемся успеха.$B$BМне нужны три предмета силы. Принесите их мне – и получите книгу.$B$BНазваний предметов я вам не скажу – нас могут подслушивать. Но я их вам напишу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте предметы, перечисленные в записке Костохвата, Геррику Костохвату в Стальгорн.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Геррику Костохвату в Заброшенный грот в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (736,'Звезда, Рука и Сердце','Тебе нужна книга Йагина? Планируешь собрать свое стадо? Ну, разумеется... и я с удовольствием помогу тебе, $gбрат:сестра;.$B$BВзамен я также попрошу тебя о помощи.$B$BМне нужны три предмета силы. Принеси их – и книга будет твоей.$B$BНазвать вслух эти предметы я не могу, но запишу их.$B$BДобудь мне все, что я укажу в списке. Если справишься с этим, значит, ты действительно $gдостоин:достойна; начать новую главу в истории нашего ордена.','Прочитайте записку Бел\'дугура. Принесите перечисленные в записке предметы Бел\'дугуру в Подгород.','Поразительно! Ты обладаешь или великим искусством, или удачей, иначе тебе не удалось бы добыть эти реликвии. Так или иначе, ты очень $Gпомог:помогла; нам.','Как продвигаются дела, $C?','Вернитесь к хранителю Бел\'дугуру на озеро Лордамер, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звезда, Рука и Сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужна книга Йагина? Планируешь собрать свое стадо? Ну, разумеется... и я с удовольствием помогу тебе, $gбрат:сестра;.$B$BВзамен я также попрошу тебя о помощи.$B$BМне нужны три предмета силы. Принеси их – и книга будет твоей.$B$BНазвать вслух эти предметы я не могу, но запишу их.$B$BДобудь мне все, что я укажу в списке. Если справишься с этим, значит, ты действительно $gдостоин:достойна; начать новую главу в истории нашего ордена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте записку Бел\'дугура. Принесите перечисленные в записке предметы Бел\'дугуру в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поразительно! Ты обладаешь или великим искусством, или удачей, иначе тебе не удалось бы добыть эти реликвии. Так или иначе, ты очень $Gпомог:помогла; нам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигаются дела, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Бел\'дугуру на озеро Лордамер, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (737,'Запретное знание','У меня есть для тебя книга, $n. Думаю, не стоит говорить, что с ней нужно обращаться очень бережно. И непременно держать подальше от рук врагов. $B$BВ этой книге содержится много секретов...$B$BОпасных секретов!','Отнесите книгу Йагина Тельдарину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запретное знание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть для тебя книга, $n. Думаю, не стоит говорить, что с ней нужно обращаться очень бережно. И непременно держать подальше от рук врагов. $B$BВ этой книге содержится много секретов...$B$BОпасных секретов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите книгу Йагина Тельдарину.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (738,'Найти Эгмонда','Геолог Эгмонд вел раскопки в Бесплодных землях, на юго-западе. Я говорю "вел", потому что, к несчастью, от него нет вестей уже не одну неделю. Его нужно найти. $B$BВ последний раз его видели на самом южном раскопе Бесплодных земель – он расположен за крепостью Ангор. Думаю, стоит начать поиски там.','Найдите Эгмонда.','Должно быть, этот скелет принадлежит Эгмонду. Его кости изломаны и выбелены солнцем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Эгмонда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Геолог Эгмонд вел раскопки в Бесплодных землях, на юго-западе. Я говорю "вел", потому что, к несчастью, от него нет вестей уже не одну неделю. Его нужно найти. $B$BВ последний раз его видели на самом южном раскопе Бесплодных земель – он расположен за крепостью Ангор. Думаю, стоит начать поиски там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Эгмонда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Должно быть, этот скелет принадлежит Эгмонду. Его кости изломаны и выбелены солнцем.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (739,'Мурдалок','Следы Эгмонда уводят на запад. Судя по кровавым следам на камнях и песке, дворф полз на коленях. $B$BИ здесь он умер. $B$BПод правой рукой мертвеца еле виднеется слово, нацарапанное на куске песчаника. $B$B"Мурдалок," – гласит надпись.','Уничтожьте убийцу Эгмонда, Мурдалока. $B$BУбейте 12 костегрызов из племени Каменного Свода. $B$BСообщите геологу Сталекруту в Лок Модане обо всем, что произошло.','Это горькая весть, $n! Он был силен и славно управлялся с молотом. Не сомневаюсь, прежде чем он пал от лап троггов, он уничтожил не одну мерзкую тварь.','У вас есть новости о судьбе Агмонда? Вы его нашли?','Вернитесь к геологу Сталекруту на Раскопки Сталекрута, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мурдалок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следы Эгмонда уводят на запад. Судя по кровавым следам на камнях и песке, дворф полз на коленях. $B$BИ здесь он умер. $B$BПод правой рукой мертвеца еле виднеется слово, нацарапанное на куске песчаника. $B$B"Мурдалок," – гласит надпись.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте убийцу Эгмонда, Мурдалока. $B$BУбейте 12 костегрызов из племени Каменного Свода. $B$BСообщите геологу Сталекруту в Лок Модане обо всем, что произошло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это горькая весть, $n! Он был силен и славно управлялся с молотом. Не сомневаюсь, прежде чем он пал от лап троггов, он уничтожил не одну мерзкую тварь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть новости о судьбе Агмонда? Вы его нашли?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Сталекруту на Раскопки Сталекрута, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (740,'<UNUSED>','This quest will take players into the Searing Gorge.$B$BStay tuned...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','This quest will take players into the Searing Gorge.$B$BStay tuned...',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (741,'Рассеянный геолог','Так геолог хочет отослать эту таинственную окаменелость Лиге исследователей в Дарнас? Мне не хотелось бы уезжать с Темных берегов без него.$b$bВот, $n, отвези эту таинственную окаменелость главному археологу Седоусу в Дарнас.','Отвезите таинственную окаменелость главному археологу Седоусу в Дарнас.','Ух ты! Только геолог Сомнамбулер мог сделать такое открытие!','Чем могу помочь, |3-6($r)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассеянный геолог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так геолог хочет отослать эту таинственную окаменелость Лиге исследователей в Дарнас? Мне не хотелось бы уезжать с Темных берегов без него.$b$bВот, $n, отвези эту таинственную окаменелость главному археологу Седоусу в Дарнас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отвезите таинственную окаменелость главному археологу Седоусу в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Только геолог Сомнамбулер мог сделать такое открытие!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем могу помочь, |3-6($r)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (742,'Большая охота','Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!$b$bОрде удалось закрепиться в землях к северу от Степей. И два наших форпоста – Застава Расщепленного Дерева и Застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на Заставе Расщепленного Дерева, к северу от Степей. Она ждет желающих принять участие в большой охоте!','Поговорите с Сенани Громосерд на Заставе Расщепленного Дерева в Ясеневом лесу.','Добро пожаловать на новое пограничье, $N. Ясеневый лес – край неограниченных возможностей, где юному |3-2($C) вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть.$B$BКак понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая охота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!$b$bОрде удалось закрепиться в землях к северу от Степей. И два наших форпоста – Застава Расщепленного Дерева и Застава Зорамского взморья – бьются во славу Орды! Те, кто жаждет подвигов, могут отправиться туда. Запомните: Сенани Громосерд находится на Заставе Расщепленного Дерева, к северу от Степей. Она ждет желающих принять участие в большой охоте!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сенани Громосерд на Заставе Расщепленного Дерева в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать на новое пограничье, $N. Ясеневый лес – край неограниченных возможностей, где юному |3-2($C) вроде тебя выпадает шанс показать себя. Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть.$B$BКак понимаю, ты здесь для того, чтобы побольше узнать об охоте. Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (743,'Соседство со стаей Неистовства Ветра','Спасибо, что $gвыбрал:выбрала; время поговорить со мной, $n. Я Руул, воин и учитель.$B$BПришло время пройти испытания и покинуть Мулгор.$B$BЕсли ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке. Они гнездятся вдоль гребня гор в стороне от дороги.$B$BЭти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе.','Принесите 8 когтей гарпий из стаи Неистовства Ветра Руулу Орлиному Когтю в деревню Кровавого Копыта.','Гарпии из клана Ярость Ветра – наши смертельные враги. Их ярость в битве сравнится лишь с их жаждой сырой плоти.','Вернитесь к Руулу Орлиному Когтю в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Соседство со стаей Неистовства Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо, что $gвыбрал:выбрала; время поговорить со мной, $n. Я Руул, воин и учитель.$B$BПришло время пройти испытания и покинуть Мулгор.$B$BЕсли ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке. Они гнездятся вдоль гребня гор в стороне от дороги.$B$BЭти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 когтей гарпий из стаи Неистовства Ветра Руулу Орлиному Когтю в деревню Кровавого Копыта.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гарпии из клана Ярость Ветра – наши смертельные враги. Их ярость в битве сравнится лишь с их жаждой сырой плоти.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руулу Орлиному Когтю в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (744,'Подготовка к церемонии','$n, вскоре мой брат предстанет перед вождем Кровавым Копытом, и мне выпала большая честь сделать для него головной убор.$B$BМне хотелось бы попросить тебя об одолжении – надо сделать одно дело, пока я буду красить эти кожаные полоски. Я просто не успею добыть достаточное количество перьев – так не поможешь ли ты мне в этом?$B$BПерья нужной величины можно найти у гарпий, что живут далеко на севере и северо-западе от Громового Утеса. Мне нужно всего-то 6 лазурных и 6 бронзовых перьев, чтобы закончить работу.','Добудьте 6 лазурных перьев и 6 бронзовых перьев.','Этот головной убор станет замечательным подарком моему брату!','Вернитесь к Эйану Орлиному Когтю в Лагерь Солнечного Пастбища, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка к церемонии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, вскоре мой брат предстанет перед вождем Кровавым Копытом, и мне выпала большая честь сделать для него головной убор.$B$BМне хотелось бы попросить тебя об одолжении – надо сделать одно дело, пока я буду красить эти кожаные полоски. Я просто не успею добыть достаточное количество перьев – так не поможешь ли ты мне в этом?$B$BПерья нужной величины можно найти у гарпий, что живут далеко на севере и северо-западе от Громового Утеса. Мне нужно всего-то 6 лазурных и 6 бронзовых перьев, чтобы закончить работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 лазурных перьев и 6 бронзовых перьев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Этот головной убор станет замечательным подарком моему брату!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эйану Орлиному Когтю в Лагерь Солнечного Пастбища, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (745,'Недобрые соседи','$n, нашей земле причиняют боль раздоры ее обитателей. Я надеюсь, что тебе не суждено увидеть столько войн, сколько выпало мне. И все же я вынужден просить тебя вступить в бой. Так ты поймешь, что малая угроза, если не искоренить ее, со временем разрастается.$B$BГноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора.$B$BСловами их не остановить.','Убейте 10 дубильщиков, 8 шкуродеров и 5 браконьеров из стаи Бледногривов и возвращайтесь к Бейну Кровавому Копыту в деревню Кровавого Копыта.','If the Palemanes had respected the land and its inhabitants more, this conflict would have never occurred.','Вернитесь к Бейну Кровавому Копыту в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недобрые соседи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, нашей земле причиняют боль раздоры ее обитателей. Я надеюсь, что тебе не суждено увидеть столько войн, сколько выпало мне. И все же я вынужден просить тебя вступить в бой. Так ты поймешь, что малая угроза, если не искоренить ее, со временем разрастается.$B$BГноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе. Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора.$B$BСловами их не остановить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 дубильщиков, 8 шкуродеров и 5 браконьеров из стаи Бледногривов и возвращайтесь к Бейну Кровавому Копыту в деревню Кровавого Копыта.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','If the Palemanes had respected the land and its inhabitants more, this conflict would have never occurred.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бейну Кровавому Копыту в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (746,'Дворфийские делишки','К северо-западу отсюда дворфы готовятся к раскопкам. Они думают, что тайны скрыты глубоко в земле, и это правда, но у нее надо учиться, а не осквернять бесконечными ямами.$B$BСобери инструменты дворфов, уничтожь их и принеси мне.$B$BЛомать инструменты можно в кузнице, которая есть в Громовом Утесе, но подойдет любая, даже та, что находится в дворфийском лагере.','Соберите 5 кирок геолога.$B$BСломайте их в кузнице. $B$BОтнесите 5 сломанных инструментов Бейну Кровавому Копыту в деревню Кровавого Копыта.','Вернитесь к Бейну Кровавому Копыту в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дворфийские делишки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К северо-западу отсюда дворфы готовятся к раскопкам. Они думают, что тайны скрыты глубоко в земле, и это правда, но у нее надо учиться, а не осквернять бесконечными ямами.$B$BСобери инструменты дворфов, уничтожь их и принеси мне.$B$BЛомать инструменты можно в кузнице, которая есть в Громовом Утесе, но подойдет любая, даже та, что находится в дворфийском лагере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 кирок геолога.$B$BСломайте их в кузнице. $B$BОтнесите 5 сломанных инструментов Бейну Кровавому Копыту в деревню Кровавого Копыта.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бейну Кровавому Копыту в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (747,'Охота начинается','Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем. Возможно, вскоре тебя позовут в Громовой Утес. Но прежде чем это случится, тебе придется доказать моему отцу, вождю Соколиному Ветру, что ты $Gдостоин:достойна; этой чести. $b$bНа плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы. Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды. Покажи, на что ты $gспособен:способна;, – поохоться на равнинных долгоногов и принеси мяса в деревню.','Принесите 7 перьев равнинных долгоногов и 7 кусков мяса равнинных долгоногов Груллу Соколиному Ветру в Лагерь Нараче.','Providing meat and feathers for the tribe is the first step in proving yourself as a hunter before the Chief.','Вернитесь к Груллу Соколиному Ветру в Лагерь Нараче, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота начинается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем. Возможно, вскоре тебя позовут в Громовой Утес. Но прежде чем это случится, тебе придется доказать моему отцу, вождю Соколиному Ветру, что ты $Gдостоин:достойна; этой чести. $b$bНа плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы. Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды. Покажи, на что ты $gспособен:способна;, – поохоться на равнинных долгоногов и принеси мяса в деревню.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 перьев равнинных долгоногов и 7 кусков мяса равнинных долгоногов Груллу Соколиному Ветру в Лагерь Нараче.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Providing meat and feathers for the tribe is the first step in proving yourself as a hunter before the Chief.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Груллу Соколиному Ветру в Лагерь Нараче, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (748,'Отравленная вода','Гоблины и их прислужники отравили наши священные колодцы! Это недопустимо.$B$BДля очищения колодцев придется создать тотемы, а ты пойдешь с ними к колодцам и проведешь очищающие ритуалы.$B$BНачнем мы с колодца Заиндевевшего Копыта. Земля сама поможет нам. Принеси мне лапы волков прерий и когти взрослых долгоногов. И тех, и других ты найдешь на юго-западе.','Принесите 6 лап волков прерий и 4 когтя равнинного долгонога Муллу Громовому Рогу в деревню Кровавого Копыта.','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отравленная вода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гоблины и их прислужники отравили наши священные колодцы! Это недопустимо.$B$BДля очищения колодцев придется создать тотемы, а ты пойдешь с ними к колодцам и проведешь очищающие ритуалы.$B$BНачнем мы с колодца Заиндевевшего Копыта. Земля сама поможет нам. Принеси мне лапы волков прерий и когти взрослых долгоногов. И тех, и других ты найдешь на юго-западе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 лап волков прерий и 4 когтя равнинного долгонога Муллу Громовому Рогу в деревню Кровавого Копыта.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (749,'Разграбленный караван','Морин Ловец Облаков попросил вас изучить содержимое ящиков с припасами в разграбленном караване.','Все стороны ящика опечатаны знаками рудникового отдела Торговой Компании. Сбоку прикреплены пометки, что содержимое должно быть обработано на одном из центральных заводов компании.','Ну как, нашел перепелятников? А где их перья?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разграбленный караван',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Морин Ловец Облаков попросил вас изучить содержимое ящиков с припасами в разграбленном караване.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все стороны ящика опечатаны знаками рудникового отдела Торговой Компании. Сбоку прикреплены пометки, что содержимое должно быть обработано на одном из центральных заводов компании.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, нашел перепелятников? А где их перья?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (750,'Охота продолжается','Любой искушенный в охоте таурен понимает, что ее смысл не заключается в убийстве любой подвернувшейся добычи. Живущие на равнине звери обеспечивают нас всем необходимым для выживания. Ты произведешь впечатление на старейшин, если принесешь им несколько шкур горных пум – они у нас очень высоко ценятся! $b$bНашим детям нужна одежда, да и шатры пора подлатать.','Принесите 10 шкур горных пум Груллу Соколиному Ветру.','Если ты сможешь добыть шкуры, я замолвлю о тебе словечко перед отцом, вождем Соколиным Ветром.','Вернитесь к Груллу Соколиному Ветру в Лагерь Нараче, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота продолжается',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Любой искушенный в охоте таурен понимает, что ее смысл не заключается в убийстве любой подвернувшейся добычи. Живущие на равнине звери обеспечивают нас всем необходимым для выживания. Ты произведешь впечатление на старейшин, если принесешь им несколько шкур горных пум – они у нас очень высоко ценятся! $b$bНашим детям нужна одежда, да и шатры пора подлатать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 шкур горных пум Груллу Соколиному Ветру.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты сможешь добыть шкуры, я замолвлю о тебе словечко перед отцом, вождем Соколиным Ветром.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Груллу Соколиному Ветру в Лагерь Нараче, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (751,'Разграбленный караван','Похоже, Торговая Компания в самом деле замыслила лишить нас всех природных ресурсов. Хорошо знать это наверняка, пожалуй, пришло время действовать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разграбленный караван',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, Торговая Компания в самом деле замыслила лишить нас всех природных ресурсов. Хорошо знать это наверняка, пожалуй, пришло время действовать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (752,'Скромная просьба','Все члены племени живут вместе в мире и гармонии. $b$bМы преданы друг другу и отвечаем друг за друга. Я обращаюсь к тебе со скромной просьбой. $b$bМоя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче. С тех пор прошло довольно много времени. Не поищешь ли ты ее, пока я занимаюсь делами племени?','Поищите матушку вождя Соколиный Ветер у источника к юго-востоку от Лагеря Нараче.','Ты проделал такой путь, чтобы помочь старушке? Да, похоже ты чтишь традиции нашего народа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скромная просьба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все члены племени живут вместе в мире и гармонии. $b$bМы преданы друг другу и отвечаем друг за друга. Я обращаюсь к тебе со скромной просьбой. $b$bМоя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче. С тех пор прошло довольно много времени. Не поищешь ли ты ее, пока я занимаюсь делами племени?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите матушку вождя Соколиный Ветер у источника к юго-востоку от Лагеря Нараче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты проделал такой путь, чтобы помочь старушке? Да, похоже ты чтишь традиции нашего народа.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (753,'Скромная просьба','В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше. Я еще могу принести пользу своему племени – просто иногда мне требуется чуть больше времени. $b$bДумаю, ты $gдостойный:достойная:c; |3-6($c). Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче. $b$bПомни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин.','Наберите кувшин воды из колодца.$b$bОтнесите кувшин вождю Соколиному Ветру в Лагерь Нараче, который находится к северо-западу от источника.','Ты принес мне этот кувшин по просьбе Великой матери Соколиный Ветер. \n\nТвоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придет день, когда мы будем гордиться тобой в Громовом Утесе.','Ты вернулся с равнины, как я понимаю? Есть ли вести от Великой матери Соколиный Ветер?','Вернитесь к вождю Соколиному Ветру в Лагерь Нараче, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скромная просьба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше. Я еще могу принести пользу своему племени – просто иногда мне требуется чуть больше времени. $b$bДумаю, ты $gдостойный:достойная:c; |3-6($c). Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче. $b$bПомни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наберите кувшин воды из колодца.$b$bОтнесите кувшин вождю Соколиному Ветру в Лагерь Нараче, который находится к северо-западу от источника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты принес мне этот кувшин по просьбе Великой матери Соколиный Ветер. \n\nТвоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придет день, когда мы будем гордиться тобой в Громовом Утесе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся с равнины, как я понимаю? Есть ли вести от Великой матери Соколиный Ветер?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Соколиному Ветру в Лагерь Нараче, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (754,'Очищение колодца Заиндевевшего Копыта','Я создал тотем для очищения Колодца Заиндевевшего Копыта. Отнеси его к колодцу и произведи ритуал очищения. Колодец находится на юго-востоке, и его охраняют мерзкие гоблины!$B$BЗадание непростое, но кому-то придется это сделать, иначе мы не сможем набирать там воду.$B$BУдачи тебе, $n.','Очистите колодец Заиндевевшего Копыта с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.','Не откладывай, $N. Заражение Колодца Заиндевевшего Копыта необходимо убрать!','Очистите Колодец Заиндевевшего Копыта','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение колодца Заиндевевшего Копыта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я создал тотем для очищения Колодца Заиндевевшего Копыта. Отнеси его к колодцу и произведи ритуал очищения. Колодец находится на юго-востоке, и его охраняют мерзкие гоблины!$B$BЗадание непростое, но кому-то придется это сделать, иначе мы не сможем набирать там воду.$B$BУдачи тебе, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Очистите колодец Заиндевевшего Копыта с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не откладывай, $N. Заражение Колодца Заиндевевшего Копыта необходимо убрать!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Очистите Колодец Заиндевевшего Копыта',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (755,'Обряды Матери-Земли','Твоя готовность выполнить скромную просьбу таурена из Нараче и твое желание обрести новые знания весьма похвальны, $n. Не сомневаюсь, придет день, и тебя, |3-6($c), назовут $gодним:одной; из величайших. $b$bНо сначала ты $gдолжен:должна; пройти три обряда Матери-Земли. $b$bПервым испытанием будет Обряд Силы. Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер. $b$bОбиталище провидца сокрыто в холмах к югу от Лагеря Нараче.','Отправьтесь к провидцу Серой Пасти, который живет к югу от Лагеря Нараче.','Тебя прислал вождь Соколиный Ветер? Обряды Матери-Земли гораздо сложнее, чем кажутся на первый взгляд...','Ты вернулся с равнины, как я понимаю? Есть ли вести от Великой матери Соколиный Ветер?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряды Матери-Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя готовность выполнить скромную просьбу таурена из Нараче и твое желание обрести новые знания весьма похвальны, $n. Не сомневаюсь, придет день, и тебя, |3-6($c), назовут $gодним:одной; из величайших. $b$bНо сначала ты $gдолжен:должна; пройти три обряда Матери-Земли. $b$bПервым испытанием будет Обряд Силы. Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер. $b$bОбиталище провидца сокрыто в холмах к югу от Лагеря Нараче.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь к провидцу Серой Пасти, который живет к югу от Лагеря Нараче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал вождь Соколиный Ветер? Обряды Матери-Земли гораздо сложнее, чем кажутся на первый взгляд...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся с равнины, как я понимаю? Есть ли вести от Великой матери Соколиный Ветер?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (756,'Тотем Громового Рога','Для создания Тотема очищения колодца Громового Рога тебе понадобятся когти хищников мулгорских равнин. Придется тебе убить несколько охотников прерий и пум плоскогорья, живущих на востоке и на западе, и принести мне их когти.','Принесите 6 когтей охотников прерий и 6 когтей пум плоскогорья Муллу Громовому Рогу.','Ну как, ты добыл когти, как я велел? С каждым часом Колодец Громового Рога загрязняется все больше!','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тотем Громового Рога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для создания Тотема очищения колодца Громового Рога тебе понадобятся когти хищников мулгорских равнин. Придется тебе убить несколько охотников прерий и пум плоскогорья, живущих на востоке и на западе, и принести мне их когти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 когтей охотников прерий и 6 когтей пум плоскогорья Муллу Громовому Рогу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, ты добыл когти, как я велел? С каждым часом Колодец Громового Рога загрязняется все больше!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (757,'Обряд силы','Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утеса.$b$bСначала ты $gдолжен:должна; пройти обряд Силы. Чтобы выдержать это испытание, ты $gдолжен:должна; доказать свою храбрость, убивая врагов племени. $b$bВоины племени Дыбогривов из Ежевичной лощины вторгаются в земли нашего племени. Они нападают на наших охотников и грабят деревню по ночам. $b$bПокажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства.','Убивайте дыбогривов в Ежевичной лощине и принесите 12 их поясов вождю Соколиному Ветру в Лагерь Нараче.','Ты прошел первый из обрядов Матери-Земли. Племя гордится тобой!','Вернитесь к вождю Соколиному Ветру в Лагерь Нараче, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряд силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утеса.$b$bСначала ты $gдолжен:должна; пройти обряд Силы. Чтобы выдержать это испытание, ты $gдолжен:должна; доказать свою храбрость, убивая врагов племени. $b$bВоины племени Дыбогривов из Ежевичной лощины вторгаются в земли нашего племени. Они нападают на наших охотников и грабят деревню по ночам. $b$bПокажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте дыбогривов в Ежевичной лощине и принесите 12 их поясов вождю Соколиному Ветру в Лагерь Нараче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты прошел первый из обрядов Матери-Земли. Племя гордится тобой!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Соколиному Ветру в Лагерь Нараче, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (758,'Очищение колодца Громового Рога','Тотем готов, $n. Остается лишь провести ритуал очищения.$B$BСтупай к колодцу Громового Рога на севере от деревни и проведи ритуал с помощью Тотема очищения колодца Громового Рога. После этого возвращайся ко мне.$B$BИ да пребудут с тобой духи.','Очистите колодец Громового Рога на севере от деревни с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.','Предки клана Громового Рога явились ко мне во сне и восхваляли тебя за очищение их колодца.\n\nОни просили передать тебе это в знак признательности…','Очистите колодец Громового Рога','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение колодца Громового Рога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тотем готов, $n. Остается лишь провести ритуал очищения.$B$BСтупай к колодцу Громового Рога на севере от деревни и проведи ритуал с помощью Тотема очищения колодца Громового Рога. После этого возвращайся ко мне.$B$BИ да пребудут с тобой духи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Очистите колодец Громового Рога на севере от деревни с помощью тотема очищения и возвращайтесь к Муллу Громовому Рогу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Предки клана Громового Рога явились ко мне во сне и восхваляли тебя за очищение их колодца.\n\nОни просили передать тебе это в знак признательности…',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Очистите колодец Громового Рога',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (759,'Тотем Буйногривых','Тебе осталось очистить лишь один колодец, названный в честь племени Буйногривых. Для этого тебе понадобятся зубы лютых хищников, могучих волков прерий. Ступай на север, поохоться на них и возвращайся.$B$BМогучие волки прерий водятся неподалеку от славного города Громового Утеса.','Отнесите 8 зубов могучего волка прерий Муллу Громовому Рогу в деревню Кровавого Копыта.','$N. Несешь ли ты зубы волков?','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тотем Буйногривых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе осталось очистить лишь один колодец, названный в честь племени Буйногривых. Для этого тебе понадобятся зубы лютых хищников, могучих волков прерий. Ступай на север, поохоться на них и возвращайся.$B$BМогучие волки прерий водятся неподалеку от славного города Громового Утеса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 8 зубов могучего волка прерий Муллу Громовому Рогу в деревню Кровавого Копыта.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N. Несешь ли ты зубы волков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (760,'Очищение колодца Буйногривых','Духи говорят о твоих успехах в деле очищения колодцев племен Заиндевевшего Копыта и Громового Рога, $gюный:юная; $n. Тотем Буйногривых готов, и ты можешь приступить к выполнению своего последнего задания.$B$BКолодец Буйногривых расположен на севере от Громового Утеса. Проведи ритуал! Избавь нашу землю от гоблинского яда! Пусть вода вновь станет чистой!','Очистите колодец Буйногривых с помощью тотема очищения колодца Буйногривых.','Очистите колодец Буйногривых','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение колодца Буйногривых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духи говорят о твоих успехах в деле очищения колодцев племен Заиндевевшего Копыта и Громового Рога, $gюный:юная; $n. Тотем Буйногривых готов, и ты можешь приступить к выполнению своего последнего задания.$B$BКолодец Буйногривых расположен на севере от Громового Утеса. Проведи ритуал! Избавь нашу землю от гоблинского яда! Пусть вода вновь станет чистой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Очистите колодец Буйногривых с помощью тотема очищения колодца Буйногривых.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Очистите колодец Буйногривых',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муллу Громовому Рогу в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (761,'Охота на перепелятников','Перепелятники – хитрые птицы. Их нелегко найти и убить. Связка перьев перепелятника – все равно что медаль для охотника, говорящая о его уме и решимости.$B$BЕсли ты хочешь взяться за это задание, ступай на равнины и убей нескольких перепелятников. $b$bПринеси мне их перья, и прославь свой клан этой победой.$B$BПерепелятники живут по всему Мулгору, но заметить их могут лишь очень зоркие глаза, а догнать – лишь резвые копыта.','Принесите 8 трофейных перьев перепелятника Харкену Тотему Ветра в деревне Кровавого Копыта.','Я знаю, набрать достаточно перьев было нелегко. Но тем самым ты показал, на что способен. Хорошо, что ты живешь у нас в деревне.','Ну как, нашел перепелятников? А где их перья?','Вернитесь к Харкену Тотему Ветра в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на перепелятников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перепелятники – хитрые птицы. Их нелегко найти и убить. Связка перьев перепелятника – все равно что медаль для охотника, говорящая о его уме и решимости.$B$BЕсли ты хочешь взяться за это задание, ступай на равнины и убей нескольких перепелятников. $b$bПринеси мне их перья, и прославь свой клан этой победой.$B$BПерепелятники живут по всему Мулгору, но заметить их могут лишь очень зоркие глаза, а догнать – лишь резвые копыта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 трофейных перьев перепелятника Харкену Тотему Ветра в деревне Кровавого Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю, набрать достаточно перьев было нелегко. Но тем самым ты показал, на что способен. Хорошо, что ты живешь у нас в деревне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, нашел перепелятников? А где их перья?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Харкену Тотему Ветра в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (762,'Посланник зла','Посол Инферний был отправлен в крепость Ангор самим Рагнаросом, чтобы надзирать за поисками потерянных артефактов Тенегорна в Ульдамане. $B$BНам и без того было непросто, а теперь я даже боюсь предположить, сколько артефактов они смогут найти и использовать против Стальгорна! $B$BЗадача проста, $n! Возвращайся в Бесплодные земли и уничтожь посла Инферния. Как только ты выполнишь это задание, возвращайся к советнику Белграму с доказательством своего успеха. $B$BТеперь все в твоих руках!','Убейте посла Инферния в крепости Ангор и принесите доказательство его смерти советнику Белграму в Стальгорн.','$N, твоя преданность Стальгорну и народу дворфов не будет забыта. Благодарю тебя за помощь.$B$BЯ извещу историка Карника о твоих успехах письмом и отправлю рабочих в Бесплодные земли, чтобы они возобновили работы на раскопках как можно скорее. Еще раз благодарю тебя.$B$BПрежде чем ты уйдешь, выполни еще одну просьбу от имени короля Бронзоборода.','Время дорого, $N. Рагнарос не будет ждать, когда мы подготовимся.','Вернитесь к советнику Белграму в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посланник зла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посол Инферний был отправлен в крепость Ангор самим Рагнаросом, чтобы надзирать за поисками потерянных артефактов Тенегорна в Ульдамане. $B$BНам и без того было непросто, а теперь я даже боюсь предположить, сколько артефактов они смогут найти и использовать против Стальгорна! $B$BЗадача проста, $n! Возвращайся в Бесплодные земли и уничтожь посла Инферния. Как только ты выполнишь это задание, возвращайся к советнику Белграму с доказательством своего успеха. $B$BТеперь все в твоих руках!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте посла Инферния в крепости Ангор и принесите доказательство его смерти советнику Белграму в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, твоя преданность Стальгорну и народу дворфов не будет забыта. Благодарю тебя за помощь.$B$BЯ извещу историка Карника о твоих успехах письмом и отправлю рабочих в Бесплодные земли, чтобы они возобновили работы на раскопках как можно скорее. Еще раз благодарю тебя.$B$BПрежде чем ты уйдешь, выполни еще одну просьбу от имени короля Бронзоборода.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Время дорого, $N. Рагнарос не будет ждать, когда мы подготовимся.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к советнику Белграму в Стальгорн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (763,'Обряды Матери-Земли','Чтобы продолжить прохождение обрядов Матери-Земли, ты $gдолжен:должна; выдержать еще два испытания. Тебе бы не помешало поднабраться опыта, $n.$b$bОтправляйся в деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утеса. $b$bОтнеси этот тотем Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоем путешествии.$b$bСледуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!','Отнесите тотем Соколиного Ветра Бейну Кровавому Копыту в деревню Кровавого Копыта. Следуйте по дороге из Лагеря Нараче.','О, весточка от моего старого друга, вождя Соколиного Ветра! Смотри-ка, он пишет мне, что ты |3-6($R) особой породы!','Что привело тебя в мою деревню, |3-6($C)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряды Матери-Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы продолжить прохождение обрядов Матери-Земли, ты $gдолжен:должна; выдержать еще два испытания. Тебе бы не помешало поднабраться опыта, $n.$b$bОтправляйся в деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна. Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утеса. $b$bОтнеси этот тотем Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоем путешествии.$b$bСледуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите тотем Соколиного Ветра Бейну Кровавому Копыту в деревню Кровавого Копыта. Следуйте по дороге из Лагеря Нараче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, весточка от моего старого друга, вождя Соколиного Ветра! Смотри-ка, он пишет мне, что ты |3-6($R) особой породы!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело тебя в мою деревню, |3-6($C)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (764,'Думаю, такой намек невозможно не понять, а? Торговая Компания не будет впредь так легко относиться к тауренам или заносчиво полагать, будто мы без лишних слов позволим похищать наши полезные ископаемые.','Меня душит злоба, как подумаю о мерзостях, которые была готова совершить Торговая Компания во имя прибыли.','Вернитесь к Морину Ловцу Облаков в Мулгор.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, такой намек невозможно не понять, а? Торговая Компания не будет впредь так легко относиться к тауренам или заносчиво полагать, будто мы без лишних слов позволим похищать наши полезные ископаемые.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Меня душит злоба, как подумаю о мерзостях, которые была готова совершить Торговая Компания во имя прибыли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морину Ловцу Облаков в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (765,'Бригадир Шумовик','Убейте бригадира Шумовика и принесите его планшет Морину Ловцу Облаков в деревню Кровавого Копыта.','Меня душит злоба, как подумаю о мерзостях, которые была готова совершить Торговая Компания во имя прибыли.','Вернитесь к Морину Ловцу Облаков в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бригадир Шумовик',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте бригадира Шумовика и принесите его планшет Морину Ловцу Облаков в деревню Кровавого Копыта.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Меня душит злоба, как подумаю о мерзостях, которые была готова совершить Торговая Компания во имя прибыли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морину Ловцу Облаков в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (766,'Маззранач','Дедушка рассказывал мне истории о своих встречах с долгоногом Маззраначем. О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах.$b$bИ вот ирония судьбы – мы столкнулись с ним, когда я странствовал по равнинам, и он здорово укусил меня за плечо. Мой дед ничуть не преувеличил, описывая это жуткое создание. Теперь, чтобы вылечить воспаленную рану, мне нужны части тел животных, которых непросто отыскать: сердце волка, бедро пумы, чешуя равнинного долгонога и потроха перепелятника.$B$BТоропись, время не ждет.','Принесите сердце волка прерий, бедренную кость пумы плоскогорья, чешую долгонога и потроха перепелятника Мауру Заклинателю Дождя в деревню Кровавого Копыта.','А, спасибо. Из этих компонентов я сделаю лекарство, которое остановит распространение инфекции и излечит меня. Я обязан тебе жизнью.\n\nНо пронзительный крик Маззранача и блеск его безжалостного клюва мне никогда не забыть…\n\nБудь осторожен во время своих странствий.','Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед…\n\nТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.','Вернитесь к Мауру Заклинателю Дождя в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маззранач',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дедушка рассказывал мне истории о своих встречах с долгоногом Маззраначем. О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах.$b$bИ вот ирония судьбы – мы столкнулись с ним, когда я странствовал по равнинам, и он здорово укусил меня за плечо. Мой дед ничуть не преувеличил, описывая это жуткое создание. Теперь, чтобы вылечить воспаленную рану, мне нужны части тел животных, которых непросто отыскать: сердце волка, бедро пумы, чешуя равнинного долгонога и потроха перепелятника.$B$BТоропись, время не ждет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сердце волка прерий, бедренную кость пумы плоскогорья, чешую долгонога и потроха перепелятника Мауру Заклинателю Дождя в деревню Кровавого Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, спасибо. Из этих компонентов я сделаю лекарство, которое остановит распространение инфекции и излечит меня. Я обязан тебе жизнью.\n\nНо пронзительный крик Маззранача и блеск его безжалостного клюва мне никогда не забыть…\n\nБудь осторожен во время своих странствий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед…\n\nТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мауру Заклинателю Дождя в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (767,'Обряд прозрения','Обряд прозрения, один из обрядов Матери-Земли, поможет тебе завоевать уважение старейшин Громового Утеса.$B$BНаш народ твердо усвоил, что кормящая нас земля – священна. Чтобы принять участие в этом ритуальном прозрении, поговори с духовным вождем деревни, Зарельманом Две Луны.','Поговорите с Зарельманом Две Луны в деревне Кровавого Копыта.','Я предчувствовал, что ты придешь ко мне, |3-6($C). Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли.','Ну как, нашел перепелятников? А где их перья?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряд прозрения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обряд прозрения, один из обрядов Матери-Земли, поможет тебе завоевать уважение старейшин Громового Утеса.$B$BНаш народ твердо усвоил, что кормящая нас земля – священна. Чтобы принять участие в этом ритуальном прозрении, поговори с духовным вождем деревни, Зарельманом Две Луны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зарельманом Две Луны в деревне Кровавого Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я предчувствовал, что ты придешь ко мне, |3-6($C). Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, нашел перепелятников? А где их перья?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (768,'Добывание шкур','Привет тебе, $Gюноша:девица;. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться. Да принесешь ты честь своему клану!$B$BЯ работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утеса.$B$BЕсли принесешь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью.','Принесите 12 кусков тонкой кожи Верену Долгоногу в Громовой Утес.','Ах, какая кожа! Из нее выйдут отличные товары.$B$BВот, Ахахаха. Возьми в знак благодарности...','Еще раз приветствую. Как проходит охота? У тебя есть для меня шкуры?','Вернитесь к Верену Долгоногу в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добывание шкур',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $Gюноша:девица;. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться. Да принесешь ты честь своему клану!$B$BЯ работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утеса.$B$BЕсли принесешь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 кусков тонкой кожи Верену Долгоногу в Громовой Утес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, какая кожа! Из нее выйдут отличные товары.$B$BВот, Ахахаха. Возьми в знак благодарности...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Еще раз приветствую. Как проходит охота? У тебя есть для меня шкуры?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верену Долгоногу в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (769,'Сумка из шкуры кодо','Эти кодо из Мулгора – твари крепкие и упрямые, а мы такие качества уважаем. Если ты дока в кожевничестве и хочешь научиться делать сумки из шкуры кодо, то принеси мне необходимые для моего дела припасы.$B$BИ тогда я поделюсь с тобой своими знаниями.','Принесите 4 куска легкой кожи и 4 мотка грубой нити Верену Высокому Страннику в Громовой Утес.','Добро. Спасибо, $N. Мое сердце распирает от гордости, когда я вижу молодежь, взыскующую мастерства в кожевничестве!','$GПринес:Принесла; мои припасы, $N?','Вернитесь к Верену Долгоногу в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумка из шкуры кодо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти кодо из Мулгора – твари крепкие и упрямые, а мы такие качества уважаем. Если ты дока в кожевничестве и хочешь научиться делать сумки из шкуры кодо, то принеси мне необходимые для моего дела припасы.$B$BИ тогда я поделюсь с тобой своими знаниями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 куска легкой кожи и 4 мотка грубой нити Верену Высокому Страннику в Громовой Утес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро. Спасибо, $N. Мое сердце распирает от гордости, когда я вижу молодежь, взыскующую мастерства в кожевничестве!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GПринес:Принесла; мои припасы, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Верену Долгоногу в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (770,'Поцарапанный демоном плащ','На потрепанной шкуре Призрачного Воя по-прежнему виден след от ужасной раны, полученной во время сражений волка с Пылающим Легионом.$B$BМожет быть, следует рассказать кому-нибудь в Лагере Солнечного Пастбища о кончине Призрачного Воя...','Отыщите кого-нибудь, кто слышал о Призрачном Вое.','Глазам своим стариковским не верю! Тебе удалось одолеть Призрачного Воя? Ты вырос в моих глазах, юный |3-6($C). Оказывается, ты превосходный охотник!\n\nПозволь предложить тебе кое-что. Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь мое оружие.\n\nПусть оно не знает промаха и дарует тебе славу.\n\nБудем надеяться, что дух Призрачного Воя упокоился с миром.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поцарапанный демоном плащ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На потрепанной шкуре Призрачного Воя по-прежнему виден след от ужасной раны, полученной во время сражений волка с Пылающим Легионом.$B$BМожет быть, следует рассказать кому-нибудь в Лагере Солнечного Пастбища о кончине Призрачного Воя...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите кого-нибудь, кто слышал о Призрачном Вое.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Глазам своим стариковским не верю! Тебе удалось одолеть Призрачного Воя? Ты вырос в моих глазах, юный |3-6($C). Оказывается, ты превосходный охотник!\n\nПозволь предложить тебе кое-что. Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь мое оружие.\n\nПусть оно не знает промаха и дарует тебе славу.\n\nБудем надеяться, что дух Призрачного Воя упокоился с миром.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (771,'Обряд прозрения','Чтобы пройти обряд Прозрения, тебе придется собрать некоторые реагенты для создания воды Провидцев.$b$bМне понадобятся камни, которых полно вокруг источников Мулгора. Я смешаю их с янтарным семенем, что роняют могучие деревья нашей земли.$B$BВ этих реагентах содержится магия, и если сварить их и выпить отвар перед костром племени, тебе явится видение. Следуй за ним, и оно приведет тебя к следующему этапу священного обряда.','Принесите 2 камня, лежащих у источника, и 2 янтарных семени Зарельману Две Луны в деревню Кровавого Копыта.','Вижу, ты научился собирать дань с нашей священной земли. Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев.','Когда ты принесешь мне достаточно камней и янтарного семени, я сделаю для тебя воду Провидцев.','Вернитесь к Зарельману Две Луны в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряд прозрения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы пройти обряд Прозрения, тебе придется собрать некоторые реагенты для создания воды Провидцев.$b$bМне понадобятся камни, которых полно вокруг источников Мулгора. Я смешаю их с янтарным семенем, что роняют могучие деревья нашей земли.$B$BВ этих реагентах содержится магия, и если сварить их и выпить отвар перед костром племени, тебе явится видение. Следуй за ним, и оно приведет тебя к следующему этапу священного обряда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 камня, лежащих у источника, и 2 янтарных семени Зарельману Две Луны в деревню Кровавого Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, ты научился собирать дань с нашей священной земли. Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда ты принесешь мне достаточно камней и янтарного семени, я сделаю для тебя воду Провидцев.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зарельману Две Луны в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (772,'Обряд прозрения','Я вручаю тебе воду Провидцев.$B$BВыпей ее перед костром племени. Когда священные воды вольются в тебя, из огня навстречу тебе шагнет видение.$B$BПосле этого следуй за ним навстречу своей судьбе...','Выпейте воду Провидцев перед костром племени в деревне Кровавого Копыта и следуйте за видением.','Не бойся, |3-6($C). Ты успешно прошел Обряд прозрения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряд прозрения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вручаю тебе воду Провидцев.$B$BВыпей ее перед костром племени. Когда священные воды вольются в тебя, из огня навстречу тебе шагнет видение.$B$BПосле этого следуй за ним навстречу своей судьбе...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпейте воду Провидцев перед костром племени в деревне Кровавого Копыта и следуйте за видением.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не бойся, |3-6($C). Ты успешно прошел Обряд прозрения.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (773,'Обряд мудрости') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряд мудрости',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (774,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (775,'Путешествие в Громовой Утес','Отныне тебя будут почитать в стенах нашего великого города. $GПрошедший:Прошедшая; обряды Матери-Земли заслуживает такой чести.$B$bВыполни последнее задание, отыщи благородного вождя Кэрна Кровавое Копыто, живущего на вершине высочайшего плато в Громовом Утесе.','Поговорите с Кэрном Кровавым Копытом в Громовом Утесе.','Привет тебе, юный |3-6($C). Вижу, тебе удалось отыскать дорогу ко мне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в Громовой Утес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отныне тебя будут почитать в стенах нашего великого города. $GПрошедший:Прошедшая; обряды Матери-Земли заслуживает такой чести.$B$bВыполни последнее задание, отыщи благородного вождя Кэрна Кровавое Копыто, живущего на вершине высочайшего плато в Громовом Утесе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кэрном Кровавым Копытом в Громовом Утесе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, юный |3-6($C). Вижу, тебе удалось отыскать дорогу ко мне.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (776,'Обряды Матери-Земли','Ты $gпрошел:прошла; обряды Матери-Земли и $gзаслужил:заслужила; достойное место среди жителей Громового Утеса.$B$BЧтобы сохранить это таким трудом заработанное место, тебе придется и дальше служить своему народу.$b$bМы охотники, $n. Внизу, в Мулгоре, есть могучий кодо по имени Арра\'чея. Выследи и убей его, проявив свое искусство охотника, и принеси мне рог Арра\'чеи.','Кэрн Кровавое Копыто из Громового Утеса попросил принести ему рог Арра\'чеи.','Отлично! Добрая охота.\n\nЯ пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо.\n\nТы оказал своему народу услугу.','Ты уже выследил Арра\'чею?','Вернитесь к Кэрну Кровавому Копыту в Золотые равнины, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряды Матери-Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпрошел:прошла; обряды Матери-Земли и $gзаслужил:заслужила; достойное место среди жителей Громового Утеса.$B$BЧтобы сохранить это таким трудом заработанное место, тебе придется и дальше служить своему народу.$b$bМы охотники, $n. Внизу, в Мулгоре, есть могучий кодо по имени Арра\'чея. Выследи и убей его, проявив свое искусство охотника, и принеси мне рог Арра\'чеи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Кэрн Кровавое Копыто из Громового Утеса попросил принести ему рог Арра\'чеи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Добрая охота.\n\nЯ пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо.\n\nТы оказал своему народу услугу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже выследил Арра\'чею?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кэрну Кровавому Копыту в Золотые равнины, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (777,'Сложная задача','Ну, теперь за дело! $B$BЯ буду здесь... в укрытии. $B$BЕсли хочешь, можешь присоединиться.','Принесите зубец #5 Лотвилу Вериатусу.','<Не отрывая взгляд от кандалов, Лотвил нетерпеливо протягивает руку.>$B$BНу? Давай сюда зубец!','Вернитесь к Лотвилю Вериатусу в Бесплодные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сложная задача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, теперь за дело! $B$BЯ буду здесь... в укрытии. $B$BЕсли хочешь, можешь присоединиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите зубец #5 Лотвилу Вериатусу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Не отрывая взгляд от кандалов, Лотвил нетерпеливо протягивает руку.>$B$BНу? Давай сюда зубец!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лотвилю Вериатусу в Бесплодные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (778,'Сложная задача','Ха! Сделано! $B$BЛюсьен, Серво, время пришло! $B$BТы $gготов:готова; стать $gсвидетелем:свидетельницей; запуска в эксплуатацию совершенной смеси алхимии, инженерной науки и древних тайн, $n? $B$BСейчас я призову могущественного элементаля. Это величайший день для всех нас!','Победите Стража Фам\'ретора и верните оковы Стихий Лотвила Лотвилу Вериатусу.','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сложная задача',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ха! Сделано! $B$BЛюсьен, Серво, время пришло! $B$BТы $gготов:готова; стать $gсвидетелем:свидетельницей; запуска в эксплуатацию совершенной смеси алхимии, инженерной науки и древних тайн, $n? $B$BСейчас я призову могущественного элементаля. Это величайший день для всех нас!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Стража Фам\'ретора и верните оковы Стихий Лотвила Лотвилу Вериатусу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (779,'Печать земли','Вернитесь к печати земли в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать земли',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к печати земли в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (780,'Боевые вепри','Боевые вепри из Ежевичной лощины, что к востоку отсюда, вторгаются в охотничьи угодья нашего племени. Их натаскивают свинобразы из племени Дыбогривов, наши заклятые враги. $b$bПойди и покажи гнусным тварям, кто хозяин в этих землях! Мы сварим из их боков и рыл славную похлебку для наших детишек!','Принесите 8 боков и 8 рыл боевых вепрей Груллу Соколиному Ветру.','Прекрасно! Мы сварим отличную похлебку, а для проклятых дыбогривов потеря нескольких боевых вепрей послужит уроком.','То, что боевые вепри творят в наших землях, уже переходит всякие границы. Сумел ли ты приструнить этих зверей? А бока и рыла принес?','Вернитесь к Груллу Соколиному Ветру в Лагерь Нараче, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые вепри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боевые вепри из Ежевичной лощины, что к востоку отсюда, вторгаются в охотничьи угодья нашего племени. Их натаскивают свинобразы из племени Дыбогривов, наши заклятые враги. $b$bПойди и покажи гнусным тварям, кто хозяин в этих землях! Мы сварим из их боков и рыл славную похлебку для наших детишек!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 боков и 8 рыл боевых вепрей Груллу Соколиному Ветру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Мы сварим отличную похлебку, а для проклятых дыбогривов потеря нескольких боевых вепрей послужит уроком.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','То, что боевые вепри творят в наших землях, уже переходит всякие границы. Сумел ли ты приструнить этих зверей? А бока и рыла принес?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Груллу Соколиному Ветру в Лагерь Нараче, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (781,'Нападение на Лагерь Нараче','Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения племени Дыбогривов на Лагерь Нараче. $b$bВождь Соколиный Ветер непременно должен об этом узнать!','Отнесите план нападения племени Дыбогривов вождю Соколиному Ветру в Лагерь Нараче.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на Лагерь Нараче',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения племени Дыбогривов на Лагерь Нараче. $b$bВождь Соколиный Ветер непременно должен об этом узнать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите план нападения племени Дыбогривов вождю Соколиному Ветру в Лагерь Нараче.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (782,'Разорванные союзы','От союзника Орды времен Второй войны, дракона Смертокрыла мы знаем, что два его лейтенанта, Чернохлыст и Гематус, были заточены в долине Летлор. Чтобы отстоять честь Орды и не допустить предательства, мы должны заставить замолчать наших растленных бывших союзников! $B$BМы наняли То\'груна и его шайку огров-наемников, чтобы они помогли нам получить знак земли – ключ, необходимый, чтобы открыть драконье узилище. Но То\'грун предал нас, забрав знак себе. Отправляйся в лагерь Бофф и отбери знак!','Убейте главаря То\'груна и принесите знак земли Горну в Каргат.','Теперь, когда от То\'груна остался лишь голый скелет, обглоданный стервятниками и выбеленный солнцем и ветром, огры, лишенные главаря, рассеются по пустыне. Так малая победа принесла с собой великую!$B$BЗнак Земли снова у нас, и мы сможем отомкнуть узилище черных драконов в долине Летлор. Мы спасем их от уготованного им вечного заключения, хотя и свершим их судьбу!','Предательство То\'груна... Неудивительно, что огры больше не в Орде. Более всего на свете я желаю их смерти и возвращения знака Земли!$B$BЕсли ты еще не расправился с их шайкой, поспеши в лагерь Бофф. Он расположен к юго-востоку от Каргата.','Вернитесь к Горну в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разорванные союзы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От союзника Орды времен Второй войны, дракона Смертокрыла мы знаем, что два его лейтенанта, Чернохлыст и Гематус, были заточены в долине Летлор. Чтобы отстоять честь Орды и не допустить предательства, мы должны заставить замолчать наших растленных бывших союзников! $B$BМы наняли То\'груна и его шайку огров-наемников, чтобы они помогли нам получить знак земли – ключ, необходимый, чтобы открыть драконье узилище. Но То\'грун предал нас, забрав знак себе. Отправляйся в лагерь Бофф и отбери знак!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте главаря То\'груна и принесите знак земли Горну в Каргат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда от То\'груна остался лишь голый скелет, обглоданный стервятниками и выбеленный солнцем и ветром, огры, лишенные главаря, рассеются по пустыне. Так малая победа принесла с собой великую!$B$BЗнак Земли снова у нас, и мы сможем отомкнуть узилище черных драконов в долине Летлор. Мы спасем их от уготованного им вечного заключения, хотя и свершим их судьбу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Предательство То\'груна... Неудивительно, что огры больше не в Орде. Более всего на свете я желаю их смерти и возвращения знака Земли!$B$BЕсли ты еще не расправился с их шайкой, поспеши в лагерь Бофф. Он расположен к юго-востоку от Каргата.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горну в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`questgivertextwindow_loc8`,`questturntextwindow_loc8`) VALUES (783,'Внутренняя угроза','Надеюсь, ты $gготов:готова; к подвигам, |3-6($c), потому что у нас тут такое творится! Смертокрыл со своими Сумеречными армиями напал на Азерот. Король призвал к оружию всех верных Альянсу горожан годных к воинской службе.$B$BСтража Штормграда с трудом поддерживает здесь мир: слишком многие наши находятся в дальних краях, и отовсюду приходят тревожные вести. Мы с радостью примем любую помощь от всех, кто готов защитить свой дом и своих близких.$B$BЕсли ты $gготов:готова; откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он где-то здесь, рядом с аббатством.','Поговорите с маршалом Макбрайдом.','Giver','Test') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внутренняя угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надеюсь, ты $gготов:готова; к подвигам, |3-6($c), потому что у нас тут такое творится! Смертокрыл со своими Сумеречными армиями напал на Азерот. Король призвал к оружию всех верных Альянсу горожан годных к воинской службе.$B$BСтража Штормграда с трудом поддерживает здесь мир: слишком многие наши находятся в дальних краях, и отовсюду приходят тревожные вести. Мы с радостью примем любую помощь от всех, кто готов защитить свой дом и своих близких.$B$BЕсли ты $gготов:готова; откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он где-то здесь, рядом с аббатством.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с маршалом Макбрайдом.',`objectives_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Giver',`questgivertextwindow_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Test',`questturntextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (784,'Бей предателей!','Люди из Кул-Тираса, ведомые адмиралом Праудмуром, вторглись в Дуротар, нарушив договор, который вождь заключил с Джайной Праудмур несколько лет назад, чтобы одолеть Архимонда.$b$bВторжение людей удалось отбить, крепость Тирагард пала. Но не так давно подкрепление под командой лейтенанта Бенедикта вновь захватило эту крепость. Нашей родине снова грозит опасность! Эти люди совершенно не чтут договоров!$b$bПокажи свою доблесть, $n. Отправляйся на юг, в крепость Тирагард, и уничтожь непрошеных гостей.','Убейте 10 моряков Кул-Тираса, 8 стражей бухты Кул-Тираса и лейтенанта Бенедикта и возвращайтесь к Га\'Току на Колючий Холм.','Твоя отвага скоро станет известна всем, |3-6($C)! Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара.','У тебя есть приказ, $N. Безопасность Дуротара находится под вопросом. Заверши свою задачу или будешь $Gпокрыт:покрыта; стыдом.$B$BПокажи свою честь, одержи победу над людьми из Тирагарда.','Вернитесь к Га\'Току в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бей предателей!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Люди из Кул-Тираса, ведомые адмиралом Праудмуром, вторглись в Дуротар, нарушив договор, который вождь заключил с Джайной Праудмур несколько лет назад, чтобы одолеть Архимонда.$b$bВторжение людей удалось отбить, крепость Тирагард пала. Но не так давно подкрепление под командой лейтенанта Бенедикта вновь захватило эту крепость. Нашей родине снова грозит опасность! Эти люди совершенно не чтут договоров!$b$bПокажи свою доблесть, $n. Отправляйся на юг, в крепость Тирагард, и уничтожь непрошеных гостей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 моряков Кул-Тираса, 8 стражей бухты Кул-Тираса и лейтенанта Бенедикта и возвращайтесь к Га\'Току на Колючий Холм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя отвага скоро станет известна всем, |3-6($C)! Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть приказ, $N. Безопасность Дуротара находится под вопросом. Заверши свою задачу или будешь $Gпокрыт:покрыта; стыдом.$B$BПокажи свою честь, одержи победу над людьми из Тирагарда.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Га\'Току в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (785,'Стратегический союз','Тралл – весьма мудрый и благородный лидер. Его навыки дипломата могут сравниться лишь с его отвагой на поле брани.$b$bТролли Черного Копья оказались бесценными союзниками для всего орочьего рода. И мы, из верности и чести, заключили с ними договор о взаимной обороне.$b$bИ вот вождь приказал удостовериться, что нашим друзьям в деревне Сен\'джин ничто не угрожает. Один из их самых опытных разведчиков, Лар Ночной Клык, охраняет их западные пределы.$b$bРазыщи Лара и спроси, не нужна ли ему помощь.','Разыщите Лара Ночного Клыка на западной окраине деревни Сен\'джин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стратегический союз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тралл – весьма мудрый и благородный лидер. Его навыки дипломата могут сравниться лишь с его отвагой на поле брани.$b$bТролли Черного Копья оказались бесценными союзниками для всего орочьего рода. И мы, из верности и чести, заключили с ними договор о взаимной обороне.$b$bИ вот вождь приказал удостовериться, что нашим друзьям в деревне Сен\'джин ничто не угрожает. Один из их самых опытных разведчиков, Лар Ночной Клык, охраняет их западные пределы.$b$bРазыщи Лара и спроси, не нужна ли ему помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите Лара Ночного Клыка на западной окраине деревни Сен\'джин.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (786,'Предотвращение агрессии племени Колкар','Говори потише, |3-6($c)! Кентавры из племени Колкар совсем близко, вон там, к западу от Утеса Колкара.$b$bПрошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!$b$bНельзя допустить, чтобы они это сделали! Достаточно ли ты $gхрабр:храбра;, чтобы напасть на Утес Колкар и уничтожить их планы?$b$bЯ заметил, что они хранятся у трех лидеров кентавров.','Лар Ночной Клык из деревни Сен\'джин хочет, чтобы вы уничтожили 3 плана нападения, которые хранятся в лагере кентавров, что на Утесе Колкар.','Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть. Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь.\n\nА кровопролитий в эти смутные времена и без того хватает.\n\nТы хорошо послужил своему народу, |3-6($C).','Кентавры постоянно изводят Орду своими набегами. Они намерены взять нашу родину в осаду! Этого нельзя допустить!','Вернитесь к Лару Ночному Клыку в Деревню Сен\'джин, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предотвращение агрессии племени Колкар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говори потише, |3-6($c)! Кентавры из племени Колкар совсем близко, вон там, к западу от Утеса Колкара.$b$bПрошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!$b$bНельзя допустить, чтобы они это сделали! Достаточно ли ты $gхрабр:храбра;, чтобы напасть на Утес Колкар и уничтожить их планы?$b$bЯ заметил, что они хранятся у трех лидеров кентавров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Лар Ночной Клык из деревни Сен\'джин хочет, чтобы вы уничтожили 3 плана нападения, которые хранятся в лагере кентавров, что на Утесе Колкар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть. Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь.\n\nА кровопролитий в эти смутные времена и без того хватает.\n\nТы хорошо послужил своему народу, |3-6($C).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кентавры постоянно изводят Орду своими набегами. Они намерены взять нашу родину в осаду! Этого нельзя допустить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лару Ночному Клыку в Деревню Сен\'джин, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (787,'Новая Орда','Тром\'ка, |3-6($c)! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов.$b$bОрда уже не такая, как раньше. Некогда я оставил ее: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти. Во время изгнания я попал в плен к людям, но вождь меня спас. Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся.$b$bГорнек скажет тебе, что делать дальше.','Зайти в Логово к Горнеку.','Еще один из новобранцев Эйтригга, хм? В каком плачевном положении мы оказались, если это лучшее, что может произвести Орда. Неважно. К тому времени, когда мы решим, что вы готовы покинуть Долину, вы будете гордиться собой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая Орда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тром\'ка, |3-6($c)! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов.$b$bОрда уже не такая, как раньше. Некогда я оставил ее: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти. Во время изгнания я попал в плен к людям, но вождь меня спас. Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся.$b$bГорнек скажет тебе, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зайти в Логово к Горнеку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще один из новобранцев Эйтригга, хм? В каком плачевном положении мы оказались, если это лучшее, что может произвести Орда. Неважно. К тому времени, когда мы решим, что вы готовы покинуть Долину, вы будете гордиться собой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (788,'Кабаньи клыки','Вот тебе первое поручение, чтобы ты $gнабрался:набралась; опыта и $gпоказал:показала; себя. Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему.$b$bПожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда.','Убейте 8 пятнистых вепрей и вернитесь в Логово к Горнеку.','Не рано ли ты $gвернулся:вернулась;, а, $n? Надеюсь, ты не будешь уверять, будто $gвыполнил:выполнила; все, что тебе было поручено?','Вернитесь к Горнеку в Долину Испытаний, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кабаньи клыки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот тебе первое поручение, чтобы ты $gнабрался:набралась; опыта и $gпоказал:показала; себя. Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему.$b$bПожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 пятнистых вепрей и вернитесь в Логово к Горнеку.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не рано ли ты $gвернулся:вернулась;, а, $n? Надеюсь, ты не будешь уверять, будто $gвыполнил:выполнила; все, что тебе было поручено?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горнеку в Долину Испытаний, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (789,'Жала скорпидов','Ядовитое жало скорпиона губит всех – и могучих воинов, и неопытных новичков. К северо-западу отсюда водится множество этих членистоногих. Принеси мне восемь их хвостов, чтобы доказать свою воинскую доблесть.$b$bИз яда жал скорпионов можно изготовить противоядие. Мы всегда держим его под рукой, специально для неосторожных юнцов вроде тебя...$b$bНо тебе-то оно не понадобится, а?','Добудьте 8 хвостов рабочих скорпидов и принесите их в Логово Горнеку.','У скорпиона панцирь прочный, но не настолько, чтобы сильный воин не сумел его пробить. Пусть рука твоя будет тверда, и душа не знает сомнений – тогда скорпионы окажутся легкой добычей!','Вернитесь к Горнеку в Долину Испытаний, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жала скорпидов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ядовитое жало скорпиона губит всех – и могучих воинов, и неопытных новичков. К северо-западу отсюда водится множество этих членистоногих. Принеси мне восемь их хвостов, чтобы доказать свою воинскую доблесть.$b$bИз яда жал скорпионов можно изготовить противоядие. Мы всегда держим его под рукой, специально для неосторожных юнцов вроде тебя...$b$bНо тебе-то оно не понадобится, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 хвостов рабочих скорпидов и принесите их в Логово Горнеку.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У скорпиона панцирь прочный, но не настолько, чтобы сильный воин не сумел его пробить. Пусть рука твоя будет тверда, и душа не знает сомнений – тогда скорпионы окажутся легкой добычей!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горнеку в Долину Испытаний, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (790,'Саркот','$C! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный. Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу.$b$bА вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида! Я сражался с ним на плато, к югу отсюда...','Убейте Саркота и принесите его коготь Хана\'зуа.','Да, убить его мне не удалось, но ранил я его серьезно. Пожалуй, мне есть чем гордиться. И это единственное, что утешает меня перед смертью. Как подумаю, как мало я сделал в жизни, такая злость берет!','Ох... Отец мой говаривал, что толку из меня не выйдет, и вот лежу я под деревом, помираю и думаю: прав был папаня…\n\nНо я хочу умереть, зная, что последний из моих врагов тоже мертв!','Вернитесь к Хана\'зуа в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Саркот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный. Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу.$b$bА вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида! Я сражался с ним на плато, к югу отсюда...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Саркота и принесите его коготь Хана\'зуа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, убить его мне не удалось, но ранил я его серьезно. Пожалуй, мне есть чем гордиться. И это единственное, что утешает меня перед смертью. Как подумаю, как мало я сделал в жизни, такая злость берет!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ох... Отец мой говаривал, что толку из меня не выйдет, и вот лежу я под деревом, помираю и думаю: прав был папаня…\n\nНо я хочу умереть, зная, что последний из моих врагов тоже мертв!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хана\'зуа в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (791,'Больше сумок – больше добычи!','Старость сделала меня бесполезным в бою. Теперь я служу Орде иным путем.$b$bЯ сижу здесь, на вышине, и смотрю, не появятся ли враги. Но по мере того, как наши силы растут, мне все реже и реже приходится трубить в сигнальный рог.$b$bА чтобы проводить время с пользой, я изготовляю разные вещи для молодых сильных воинов, которые защищают теперь нашу родину.$b$bЯ могу сделать тебе сумку для пожитков. Если такая вещь будет для тебя полезна, принеси мне отрез холста – эта ткань в ходу у людей и кентавров.','Принесите 8 лоскутов холста Фурлу Хмурому Лбу, стоящему на сторожевой башне Колючего Холма.','Когда мы заселяли эти земли, я гордо сражался плечом к плечу с вождем. Все мое тело покрыто шрамами.\n\nЯ отстаивал честь Орды своим боевым топором в день победы над Архимондом, когда по необходимости был заключен нечестивый союз с людьми и эльфами.\n\nНо моя должность стража открыла мне новый взгляд на вещи.','Вернитесь к Фурлу Хмурому Лбу в Колючий Холм, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше сумок – больше добычи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старость сделала меня бесполезным в бою. Теперь я служу Орде иным путем.$b$bЯ сижу здесь, на вышине, и смотрю, не появятся ли враги. Но по мере того, как наши силы растут, мне все реже и реже приходится трубить в сигнальный рог.$b$bА чтобы проводить время с пользой, я изготовляю разные вещи для молодых сильных воинов, которые защищают теперь нашу родину.$b$bЯ могу сделать тебе сумку для пожитков. Если такая вещь будет для тебя полезна, принеси мне отрез холста – эта ткань в ходу у людей и кентавров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 лоскутов холста Фурлу Хмурому Лбу, стоящему на сторожевой башне Колючего Холма.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда мы заселяли эти земли, я гордо сражался плечом к плечу с вождем. Все мое тело покрыто шрамами.\n\nЯ отстаивал честь Орды своим боевым топором в день победы над Архимондом, когда по необходимости был заключен нечестивый союз с людьми и эльфами.\n\nНо моя должность стража открыла мне новый взгляд на вещи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фурлу Хмурому Лбу в Колючий Холм, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (792,'Злобные фамилиары','Что ж, |3-6($c), надеюсь, у нас ты многому научишься.$b$bМеня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не все ладно!$b$bВ Долине Испытаний обосновался ковен Пылающего Клинка. Эти твари скрываются в пещере на северо-востоке, и их злобные фамилиары выбираются оттуда и сеют хаос.$b$bИтак, вот твое первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне.','Убейте 8 злобных фамилиаров и вернитесь к Зурите Востроглазой, которая ждет вас у Логова.','Ну что, собрала плоды?','Вернитесь к Зурите Востроглазой в Долину Испытаний, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злобные фамилиары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, |3-6($c), надеюсь, у нас ты многому научишься.$b$bМеня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не все ладно!$b$bВ Долине Испытаний обосновался ковен Пылающего Клинка. Эти твари скрываются в пещере на северо-востоке, и их злобные фамилиары выбираются оттуда и сеют хаос.$b$bИтак, вот твое первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 злобных фамилиаров и вернитесь к Зурите Востроглазой, которая ждет вас у Логова.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, собрала плоды?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зурите Востроглазой в Долину Испытаний, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (793,'Разорванные союзы','Печать земли удерживают три рунных камня, сокрытые в долине Летлор. Один спрятан в алмазном столпе, другой – в опаловом, третий – в аметистовом. С помощью знака земли ты сможешь извлечь рунные камни и разрушить печать земли. $b$bНо будь $gосторожен:осторожна;, $n, Чернохлыст и Гематус очень опасны. Ты $gдолжен:должна; убить их и принести мне их наручники. $B$BДолина расположена к востоку от Бесплодных земель. Не теряй бдительности – в низине множество драконов!','С помощью знака земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни. $b$bПоместите рунные камни на печать земли и освободите драконов Чернохлыста и Гематуса. $b$bУбейте драконов и принесите Горну наручники Чернохлыста, цепи Гематуса и знак земли.','Черные драконы вступают в союз с отступниками – орками Черной Горы. И тех, и других должно вернуть в лоно Орды или уничтожить. Теперь, когда мы покончили с Гематусом и Чернохлыстом, мы можем обратить взор на запад, на пик Черной Горы.','Немногие создания сравнятся по мощи и хитрости с драконами, и немногие драконы сравнятся по свирепости с Чернохлыстом и Гематусом.','Вернитесь к Горну к скелету Апокрифана, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разорванные союзы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Печать земли удерживают три рунных камня, сокрытые в долине Летлор. Один спрятан в алмазном столпе, другой – в опаловом, третий – в аметистовом. С помощью знака земли ты сможешь извлечь рунные камни и разрушить печать земли. $b$bНо будь $gосторожен:осторожна;, $n, Чернохлыст и Гематус очень опасны. Ты $gдолжен:должна; убить их и принести мне их наручники. $B$BДолина расположена к востоку от Бесплодных земель. Не теряй бдительности – в низине множество драконов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью знака земли активируйте алмазный, опаловый и аметистовый столпы и извлеките рунные камни. $b$bПоместите рунные камни на печать земли и освободите драконов Чернохлыста и Гематуса. $b$bУбейте драконов и принесите Горну наручники Чернохлыста, цепи Гематуса и знак земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Черные драконы вступают в союз с отступниками – орками Черной Горы. И тех, и других должно вернуть в лоно Орды или уничтожить. Теперь, когда мы покончили с Гематусом и Чернохлыстом, мы можем обратить взор на запад, на пик Черной Горы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Немногие создания сравнятся по мощи и хитрости с драконами, и немногие драконы сравнятся по свирепости с Чернохлыстом и Гематусом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горну к скелету Апокрифана, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (794,'Медальон Пылающего Клинка','С помощью ворожбы я узнала, что в глубине Грота Пылающего Клинка находится мощный магический предмет. Его стерегут звери и черная магия.$b$bЭтот предмет – медальон Пылающего Клинка. Твоя очередная задача – найти его и отнять у ковена.$b$bНо берегись: медальон может оказаться в руках одного из членов ковена, и этот чернокнижник будет куда могущественнее, чем фамилиары, с которыми тебе уже доводилось встречаться!$b$bСтупай, $n. Грот находится к северо-западу отсюда.','Принесите медальон Пылающего Клинка Зурите Востроглазой, стоящей у Логова.','Он у тебя! Молодец!\n\nТеперь у нас есть возможность вытеснить приспешников Пылающего Клинка из Долины Испытаний. Но, боюсь, этот грот – не единственный их оплот в наших землях.\n\nТак что эта встреча с ними была не последней.','Вернитесь к Зурите Востроглазой в Долину Испытаний, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медальон Пылающего Клинка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С помощью ворожбы я узнала, что в глубине Грота Пылающего Клинка находится мощный магический предмет. Его стерегут звери и черная магия.$b$bЭтот предмет – медальон Пылающего Клинка. Твоя очередная задача – найти его и отнять у ковена.$b$bНо берегись: медальон может оказаться в руках одного из членов ковена, и этот чернокнижник будет куда могущественнее, чем фамилиары, с которыми тебе уже доводилось встречаться!$b$bСтупай, $n. Грот находится к северо-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите медальон Пылающего Клинка Зурите Востроглазой, стоящей у Логова.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он у тебя! Молодец!\n\nТеперь у нас есть возможность вытеснить приспешников Пылающего Клинка из Долины Испытаний. Но, боюсь, этот грот – не единственный их оплот в наших землях.\n\nТак что эта встреча с ними была не последней.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зурите Востроглазой в Долину Испытаний, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (795,'Печать земли','Как только рунные камни оказались в предназначенных для них нишах, земля задрожала и печать разрушилась.','Перед вами печать Земли. В ней вы видите три потайные ниши для аметистового, опалового и алмазного рунных камней.','Вернитесь к печати земли в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать земли',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как только рунные камни оказались в предназначенных для них нишах, земля задрожала и печать разрушилась.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Перед вами печать Земли. В ней вы видите три потайные ниши для аметистового, опалового и алмазного рунных камней.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к печати земли в Бесплодных землях.',`completedtext_loc8`);
