INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (804,'Саркот','То, что ты $gсделал:сделала; ради меня, заставило меня воспрянуть духом. Я еще повоюю!$b$bНо пока что мне не добраться до Логова без посторонней помощи. Прошу тебя, $n, сходи в Логово, расскажи Горнеку, что я здесь. Может, он сумеет мне помочь.','Расскажите Горнеку о том, что Хана\'зуа в беде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Саркот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, что ты $gсделал:сделала; ради меня, заставило меня воспрянуть духом. Я еще повоюю!$b$bНо пока что мне не добраться до Логова без посторонней помощи. Прошу тебя, $n, сходи в Логово, расскажи Горнеку, что я здесь. Может, он сумеет мне помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расскажите Горнеку о том, что Хана\'зуа в беде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (805,'Донесение для деревни Сен\'джин','Твои испытания в борьбе с Пылающим Клинком подошли к концу... по крайней мере тут, в нашей Долине. Но я прошу тебя отнести известие о том, что ты теперь знаешь.$b$bСтупай в тролльскую деревню Сен\'джин, отыщи там мастера Гадрина. Отправляйся на восток, на развилке поверни направо.$b$bРасскажи Гадрину о чернокнижниках Пылающего Клинка и о том, что они уже проникли в Долину Испытаний. Узнай, не видно ли их в Сен\'джине.$b$bСтупай, $n, и не медли в пути! Боюсь, появление злодеев в гроте Пылающего Клинка – это только первая ласточка...','Поговорите с мастером Гадрином в деревне Сен\'джин.','Хм... Как это все не вовремя! Нет, у нас в Сен\'джине Пылающего Клинка пока не видно, однако на побережье, на островах Эхо, обосновалось иное зло.\n\nОрки – друзья троллей Черного Копья. Верные друзья. Мы хотели бы помочь оркам, но... сейчас нам самим нужна помощь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение для деревни Сен\'джин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои испытания в борьбе с Пылающим Клинком подошли к концу... по крайней мере тут, в нашей Долине. Но я прошу тебя отнести известие о том, что ты теперь знаешь.$b$bСтупай в тролльскую деревню Сен\'джин, отыщи там мастера Гадрина. Отправляйся на восток, на развилке поверни направо.$b$bРасскажи Гадрину о чернокнижниках Пылающего Клинка и о том, что они уже проникли в Долину Испытаний. Узнай, не видно ли их в Сен\'джине.$b$bСтупай, $n, и не медли в пути! Боюсь, появление злодеев в гроте Пылающего Клинка – это только первая ласточка...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером Гадрином в деревне Сен\'джин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... Как это все не вовремя! Нет, у нас в Сен\'джине Пылающего Клинка пока не видно, однако на побережье, на островах Эхо, обосновалось иное зло.\n\nОрки – друзья троллей Черного Копья. Верные друзья. Мы хотели бы помочь оркам, но... сейчас нам самим нужна помощь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (806,'Сгущаются черные тучи','Нельзя допустить, чтобы Пылающий Клинок закрепился в Дуротаре! Нужно уничтожить этих чернокнижников, прежде чем распространяемое ими зло расползется по нашей земле!$b$bЯ провел расследование и выяснил, что один из чернокнижников Пылающего Клинка, гоблин по имени Пшикс Черношквал, обосновался на Громовом хребте к северо-западу отсюда. Там он и его приспешники сеют хаос!$b$bНайди Пшикса, убей его и принеси мне его коготь в качестве доказательства.','Принесите коготь Пшикса Оргнилу Душегрызу из Колючего Холма.','Вернитесь к Оргнилу Душегрызу в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сгущаются черные тучи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нельзя допустить, чтобы Пылающий Клинок закрепился в Дуротаре! Нужно уничтожить этих чернокнижников, прежде чем распространяемое ими зло расползется по нашей земле!$b$bЯ провел расследование и выяснил, что один из чернокнижников Пылающего Клинка, гоблин по имени Пшикс Черношквал, обосновался на Громовом хребте к северо-западу отсюда. Там он и его приспешники сеют хаос!$b$bНайди Пшикса, убей его и принеси мне его коготь в качестве доказательства.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите коготь Пшикса Оргнилу Душегрызу из Колючего Холма.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Оргнилу Душегрызу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (807,'<UNUSED>','My scouts report that some of the Durotar wildlife have become infected with a demonic taint. They were seen to the north and west.$B$BThey wander among their brethren as normal beasts, but evil powers flow through them, and burning within each one is a heart scorched by black magic.$B$BThese beasts must be destroyed!$B$BIf you find such an animal while you explore Durotar, kill it and collect its Scorched Heart. Bring the hearts to me and I will have them studied, then destroyed.','Bring 5 Scorched Hearts to Orgnil Soulscar in Razor Hill.','Вернитесь к Оргнилу Душегрызу в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','My scouts report that some of the Durotar wildlife have become infected with a demonic taint. They were seen to the north and west.$B$BThey wander among their brethren as normal beasts, but evil powers flow through them, and burning within each one is a heart scorched by black magic.$B$BThese beasts must be destroyed!$B$BIf you find such an animal while you explore Durotar, kill it and collect its Scorched Heart. Bring the hearts to me and I will have them studied, then destroyed.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring 5 Scorched Hearts to Orgnil Soulscar in Razor Hill.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Оргнилу Душегрызу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (808,'Череп Миншины','Я слышу голос моего брата, Миншины. Он взывает ко мне из снов.$b$bЕго захватил в плен Залазан, чернокнижник с островов Эха на востоке. И теперь Миншина мертв.$b$bНо смерть не принесла ему свободы! Залазан заточил дух Миншины внутри его собственного черепа. В снах я вижу его рядом с другими черепами, в магическом кругу на самом большом из островов Эха. Пока его душа находится в этом месте, она обречена на вечные страдания.$b$bПрошу тебя, $n, отыщи этот круг и похить череп Миншины. Принеси его мне.$b$bОсвободи его!','Украдите череп Миншины из магического круга на островах Эха.$b$bПринесите его мастеру Гадрину в деревне Сен\'джин.','Вернитесь к мастеру Гадрину в деревню Сен\'джин, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Череп Миншины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышу голос моего брата, Миншины. Он взывает ко мне из снов.$b$bЕго захватил в плен Залазан, чернокнижник с островов Эха на востоке. И теперь Миншина мертв.$b$bНо смерть не принесла ему свободы! Залазан заточил дух Миншины внутри его собственного черепа. В снах я вижу его рядом с другими черепами, в магическом кругу на самом большом из островов Эха. Пока его душа находится в этом месте, она обречена на вечные страдания.$b$bПрошу тебя, $n, отыщи этот круг и похить череп Миншины. Принеси его мне.$b$bОсвободи его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите череп Миншины из магического круга на островах Эха.$b$bПринесите его мастеру Гадрину в деревне Сен\'джин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Гадрину в деревню Сен\'джин, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (809,'Ак\'Зелот','Со времен последней великой войны, когда Пылающий Легион потерпел поражение, я ищу источники демонической порчи, что воздействует на общество орков. И принесенный тобой ошейник подтверждает мои опасения!$b$bОн принадлежит Пылающему Клинку, культу, объединенному вокруг предмета, который наделен демонической силой. Этот предмет называется Демоново семя, и находится он в Степях, на Вершине Багрового Тумана. Его необходимо уничтожить!$b$bОтправляйся на форпост на границе Степей, к западу, и поговори с моим помощником, Ак\'Зелотом. Он скажет тебе, что делать дальше.','Поговорите с Ак\'Зелотом в Степях.','Вот как? Ниру хочет, чтобы Демоново семя было уничтожено? Странно…\n\nЧто ж, хорошо. Если такова его воля, я расскажу тебе, как уничтожить семя.','Чего тебе надо, молокосос? Если ты новобранец, давай сюда письмо, а иначе проваливай.','Уничтожьте Демоново семя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ак\'Зелот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Со времен последней великой войны, когда Пылающий Легион потерпел поражение, я ищу источники демонической порчи, что воздействует на общество орков. И принесенный тобой ошейник подтверждает мои опасения!$b$bОн принадлежит Пылающему Клинку, культу, объединенному вокруг предмета, который наделен демонической силой. Этот предмет называется Демоново семя, и находится он в Степях, на Вершине Багрового Тумана. Его необходимо уничтожить!$b$bОтправляйся на форпост на границе Степей, к западу, и поговори с моим помощником, Ак\'Зелотом. Он скажет тебе, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ак\'Зелотом в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот как? Ниру хочет, чтобы Демоново семя было уничтожено? Странно…\n\nЧто ж, хорошо. Если такова его воля, я расскажу тебе, как уничтожить семя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего тебе надо, молокосос? Если ты новобранец, давай сюда письмо, а иначе проваливай.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Уничтожьте Демоново семя.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (810,'<UNUSED>','You would do well to learn how dangerous this land can be, |3-6($c).$B$BThe wildlife here can teach us such things... if we are wise and observant.$B$BThe scorpids are a perfect example of survival in Durotar. If you are to survive, it would be wise to take on some of their characteristics as your own. Their hardened carapaces can protect you from the harshness of the sun, or even a deadly weapon.$B$BBring me 6 Small Scorpid Carapaces from the Clattering Scorpids, $n, and I shall see about rewarding you justly.','Bring 6 Small Scorpid Carapaces to Kor\'ghan in Sen\'jin Village.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','You would do well to learn how dangerous this land can be, |3-6($c).$B$BThe wildlife here can teach us such things... if we are wise and observant.$B$BThe scorpids are a perfect example of survival in Durotar. If you are to survive, it would be wise to take on some of their characteristics as your own. Their hardened carapaces can protect you from the harshness of the sun, or even a deadly weapon.$B$BBring me 6 Small Scorpid Carapaces from the Clattering Scorpids, $n, and I shall see about rewarding you justly.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring 6 Small Scorpid Carapaces to Kor\'ghan in Sen\'jin Village.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (811,'<UNUSED>','One of the other traits of the scorpids is their fierce loyalty. They will protect one another if they are in danger--you\'ve probably already seen this behavior in your first scorpid hunt.$B$BYou would do well to heed that lesson and adapt it for yourself: we are stronger as one; we are weak when we are divided into many.$B$BBring me 8 Large Scorpid Carapaces from the Armored Scorpids and I shall reward you for learning this wisdom.','Bring 8 Large Scorpid Carapaces to Kor\'ghan in Sen\'jin Village.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','One of the other traits of the scorpids is their fierce loyalty. They will protect one another if they are in danger--you\'ve probably already seen this behavior in your first scorpid hunt.$B$BYou would do well to heed that lesson and adapt it for yourself: we are stronger as one; we are weak when we are divided into many.$B$BBring me 8 Large Scorpid Carapaces from the Armored Scorpids and I shall reward you for learning this wisdom.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring 8 Large Scorpid Carapaces to Kor\'ghan in Sen\'jin Village.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (812,'Нужда в исцелении','А, $n... Ты как нельзя вовремя! Надеюсь на твое проворство.$b$bЯ сражался с несколькими ядохвостами, и один из них смог меня ужалить. Я чувствую, как слабею с каждой секундой... Боюсь, мне осталось не больше часа. Мне срочно нужна твоя помощь!$b$bКоргхан из Оргриммара умеет изготовлять противоядие. Найди его... Быстрее, $n! Долго мне не протянуть. Ищи его в Расселине Теней.','Найдите в Оргриммаре Кор\'гхана и добудьте сыворотку от яда ядохвоста. Принесите сыворотку Ринагу на северо-западной границе Дуротара.','Я даже рад, что не могу сейчас вернуться в Сен\'джин. Все смеялись бы над моей слабостью и глупостью!','Вернитесь к Ринагу к реке Строптивой, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нужда в исцелении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $n... Ты как нельзя вовремя! Надеюсь на твое проворство.$b$bЯ сражался с несколькими ядохвостами, и один из них смог меня ужалить. Я чувствую, как слабею с каждой секундой... Боюсь, мне осталось не больше часа. Мне срочно нужна твоя помощь!$b$bКоргхан из Оргриммара умеет изготовлять противоядие. Найди его... Быстрее, $n! Долго мне не протянуть. Ищи его в Расселине Теней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Оргриммаре Кор\'гхана и добудьте сыворотку от яда ядохвоста. Принесите сыворотку Ринагу на северо-западной границе Дуротара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я даже рад, что не могу сейчас вернуться в Сен\'джин. Все смеялись бы над моей слабостью и глупостью!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ринагу к реке Строптивой, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (813,'Поиски противоядия','Ядохвосты – одни из опаснейших скорпидов в Дуротаре! Со стороны Ринага было очень глупо охотиться на них, не имея при себе противоядия. Впрочем, сейчас его вразумлять уже поздно.$b$bПринеси мне несколько ядовитых желез ядохвоста от любых ядохвостов, каких найдешь у входа в Оргриммар, и я сделаю ему противоядие.$b$bТоропись, $n! Одному из наших нужна твоя помощь!','Принесите 4 ядовитых железы ядохвоста Кор\'гхану в Оргриммаре.','Не забывай, если ты на какую-то тварь охотишься, первым делом надо как следует изучить ее повадки! Это может спасти тебе жизнь.','Вернитесь к Кор\'гхану в Расселину Теней, что в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски противоядия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ядохвосты – одни из опаснейших скорпидов в Дуротаре! Со стороны Ринага было очень глупо охотиться на них, не имея при себе противоядия. Впрочем, сейчас его вразумлять уже поздно.$b$bПринеси мне несколько ядовитых желез ядохвоста от любых ядохвостов, каких найдешь у входа в Оргриммар, и я сделаю ему противоядие.$b$bТоропись, $n! Одному из наших нужна твоя помощь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 ядовитых железы ядохвоста Кор\'гхану в Оргриммаре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не забывай, если ты на какую-то тварь охотишься, первым делом надо как следует изучить ее повадки! Это может спасти тебе жизнь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кор\'гхану в Расселину Теней, что в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (814,'<UNUSED>','Cook and clean--that\'s all I do!$B$BYou want to eat, you get me some more meat! I don\'t have all day to hunt and prepare food for all these louses. You got to learn to pull your own weight around here if you wanna be treated equal.$B$BGet me some Chunks of Boar Meat if you want to make yourself useful... or you don\'t want to starve to death.','Bring 10 Chunks of Boar Meat to Cook Torka in Razor Hill.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Cook and clean--that\'s all I do!$B$BYou want to eat, you get me some more meat! I don\'t have all day to hunt and prepare food for all these louses. You got to learn to pull your own weight around here if you wanna be treated equal.$B$BGet me some Chunks of Boar Meat if you want to make yourself useful... or you don\'t want to starve to death.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring 10 Chunks of Boar Meat to Cook Torka in Razor Hill.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (815,'Хорошенький омлет','Ба! А я и позабыл, что надо готовить завтрак.$b$bСлушай, $n, сбегай-ка, раздобудь мне по-быстрому несколько яиц кнутохвостов, как минимум три штуки.$b$bИмей в виду, кровопалые кнутохвосты – твари свирепые и вполне могут убить, защищая свою кладку. Иногда они зарывают яйца слишком глубоко, чтобы их можно было беспрепятственно раздобыть, но если ты отправишься на острова Эха, к юго-востоку от деревни Сен\'джин, там эти яйца лежат повсюду.','Принесите 3 яйца кнутохвостов повару Торке в Колючий Холм.','Завтрак, обед, ужин! Какая, в сущности, разница? Все равно кто-то должен готовить еду, и этот кто-то – я!','Вернитесь к повару Торке в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хорошенький омлет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ба! А я и позабыл, что надо готовить завтрак.$b$bСлушай, $n, сбегай-ка, раздобудь мне по-быстрому несколько яиц кнутохвостов, как минимум три штуки.$b$bИмей в виду, кровопалые кнутохвосты – твари свирепые и вполне могут убить, защищая свою кладку. Иногда они зарывают яйца слишком глубоко, чтобы их можно было беспрепятственно раздобыть, но если ты отправишься на острова Эха, к юго-востоку от деревни Сен\'джин, там эти яйца лежат повсюду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 яйца кнутохвостов повару Торке в Колючий Холм.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Завтрак, обед, ужин! Какая, в сущности, разница? Все равно кто-то должен готовить еду, и этот кто-то – я!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повару Торке в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (816,'Пропавший, но не забытый','Прошу тебя, $n, может, хоть ты сумеешь мне помочь? Крон, мой сын, несколько дней тому назад отправился на охоту и до сих пор не вернулся! Он ушел на запад, в Степи, охотиться на кроколисков у реки Строптивой. Я боюсь, случилось худшее...$b$bКрон могуч, но гордость и упрямство всегда доводили его до беды. Я попросила его не охотиться на кроколисков, потому что они злобны и коварны! А он рассвирепел и хлопнул дверью.$b$bЕсли не сумеешь отыскать его – узнай хотя бы, что с ним случилось... даже если тебе придется заглянуть в брюхо каждому кроколиску на берегах Строптивой!','Принесите известие о судьбе, постигшей Крона, Майше Тор\'крен в усадьбу к северо-западу от Колючего Холма.','Я молюсь, чтобы Крон вернулся ко мне, но, боюсь, я уже знаю, что с ним случилось…','Вернитесь к Майше Тор\'крен на ферму Тор\'кренов, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший, но не забытый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу тебя, $n, может, хоть ты сумеешь мне помочь? Крон, мой сын, несколько дней тому назад отправился на охоту и до сих пор не вернулся! Он ушел на запад, в Степи, охотиться на кроколисков у реки Строптивой. Я боюсь, случилось худшее...$b$bКрон могуч, но гордость и упрямство всегда доводили его до беды. Я попросила его не охотиться на кроколисков, потому что они злобны и коварны! А он рассвирепел и хлопнул дверью.$b$bЕсли не сумеешь отыскать его – узнай хотя бы, что с ним случилось... даже если тебе придется заглянуть в брюхо каждому кроколиску на берегах Строптивой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите известие о судьбе, постигшей Крона, Майше Тор\'крен в усадьбу к северо-западу от Колючего Холма.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я молюсь, чтобы Крон вернулся ко мне, но, боюсь, я уже знаю, что с ним случилось…',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Майше Тор\'крен на ферму Тор\'кренов, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (817,'Полезная добыча','$n, у нас в большом ходу шкуры дуротарского тигра. Чего только из них не делают! И одеяла, и доспехи, и шатры. Вот почему мы охотимся на этих животных, но не истребляем их.$b$bВ общем, пришла пора в очередной раз сократить поголовье. Наши потребности растут, и запасов не хватает. Мне нужны новые шкуры.$b$bПринеси мне 4 шкуры дуротарских тигров, и получишь награду. Эти кошки водятся на островах к югу отсюда.','Принесите 4 шкуры дуротарских тигров Вель\'рину Клыку в деревне Сен\'джин.','Как сейчас помню свою первую охоту на тигров! Я решил поохотиться на самом большом из островов Эхо. Я затаился в тени и ждал почти целый день.\n\nМои мускулы были напряжены, и я был готов выстрелить в любую секунду! Как же я торжествовал, когда мой первый тигр был повержен!','Вернитесь к Вель\'рину Клыку в деревню Сен\'джин, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полезная добыча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, у нас в большом ходу шкуры дуротарского тигра. Чего только из них не делают! И одеяла, и доспехи, и шатры. Вот почему мы охотимся на этих животных, но не истребляем их.$b$bВ общем, пришла пора в очередной раз сократить поголовье. Наши потребности растут, и запасов не хватает. Мне нужны новые шкуры.$b$bПринеси мне 4 шкуры дуротарских тигров, и получишь награду. Эти кошки водятся на островах к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 шкуры дуротарских тигров Вель\'рину Клыку в деревне Сен\'джин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как сейчас помню свою первую охоту на тигров! Я решил поохотиться на самом большом из островов Эхо. Я затаился в тени и ждал почти целый день.\n\nМои мускулы были напряжены, и я был готов выстрелить в любую секунду! Как же я торжествовал, когда мой первый тигр был повержен!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вель\'рину Клыку в деревню Сен\'джин, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (818,'Растворитель','Да, глаза меня порой подводят, но все же пока я вижу достаточно отчетливо. И все чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда. И я не беру учеников. Нет нынче достойных ни среди троллей, ни среди орков.$b$bЧто? Ты $gдостоин:достойна;? Ну да, конечно... Это ты так думаешь.$b$bМне нужны кое-какие компоненты. Сумеешь ли ты их добыть?$b$bМне нужны невредимые глаза макрур и слизь крабов, их ты можешь собрать с любых макрур и крабов в Дуротаре. Вот принеси мне их, потом поговорим.','Принесите 4 невредимых глаза макрур и 8 фиалов со слизью крабов мастеру Ворналу в деревне Сен\'джин.','Вот-вот, сила и воля по-настоящему проявляются только со временем. Потеряешь терпение, дашь слабину – тут-то и вылезет твоя подлинная натура!','Вернитесь к мастеру Ворналу в деревню Сен\'джин, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растворитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, глаза меня порой подводят, но все же пока я вижу достаточно отчетливо. И все чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда. И я не беру учеников. Нет нынче достойных ни среди троллей, ни среди орков.$b$bЧто? Ты $gдостоин:достойна;? Ну да, конечно... Это ты так думаешь.$b$bМне нужны кое-какие компоненты. Сумеешь ли ты их добыть?$b$bМне нужны невредимые глаза макрур и слизь крабов, их ты можешь собрать с любых макрур и крабов в Дуротаре. Вот принеси мне их, потом поговорим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 невредимых глаза макрур и 8 фиалов со слизью крабов мастеру Ворналу в деревне Сен\'джин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вот-вот, сила и воля по-настоящему проявляются только со временем. Потеряешь терпение, дашь слабину – тут-то и вылезет твоя подлинная натура!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Ворналу в деревню Сен\'джин, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (819,'Да?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (820,'<UNUSED>','Truly a spirit of strength resides in your body--or maybe it was only luck, yes?$B$BThat is what the young rely on these days: luck... and the generosity of those more powerful than they. Not many take the time to find their own path. It\'s always begging for help... always the reward, and never the quest. I\'m sure you\'ll be the same.$B$BBut there is hope. I need one other thing for my potion, $n: 8 shimmerweed herbs. They can be found in Thunder Ridge to the northwest of Razor Hill.','Bring 8 Shimmerweed to Master Vornal in Sen\'jin Village.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Truly a spirit of strength resides in your body--or maybe it was only luck, yes?$B$BThat is what the young rely on these days: luck... and the generosity of those more powerful than they. Not many take the time to find their own path. It\'s always begging for help... always the reward, and never the quest. I\'m sure you\'ll be the same.$B$BBut there is hope. I need one other thing for my potion, $n: 8 shimmerweed herbs. They can be found in Thunder Ridge to the northwest of Razor Hill.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring 8 Shimmerweed to Master Vornal in Sen\'jin Village.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (821,'Принесите 5 клыков равнинного льва, 5 почек долгонога и 1 рог рокочущей ящерицы пивовару Дрону в Кабестан.','Ха-ха... Вот уж не думал, что снова сварю этот напиток!\n\nПрямо ностальгия охватила. Сразу вспомнилось, как я отключился после бочки эля Трогга. Спасибо. От воспоминаний даже на душе посветлело.','Как идут поиски?','Вернитесь к пивовару Дрону в Степи.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 клыков равнинного льва, 5 почек долгонога и 1 рог рокочущей ящерицы пивовару Дрону в Кабестан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха... Вот уж не думал, что снова сварю этот напиток!\n\nПрямо ностальгия охватила. Сразу вспомнилось, как я отключился после бочки эля Трогга. Спасибо. От воспоминаний даже на душе посветлело.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идут поиски?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пивовару Дрону в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (822,'Принесите 5 грозовых желез, 1 слюнную железу грозового змея и 1 печень кодо пивовару Дрону в Кабестан.','Ха-ха! Я знал, что ты не откажешься от этого напитка. Приходи, я еще тебе сварю. Главное – приноси все необходимое.','Вернитесь к пивовару Дрону в Кабестан, что в Степях.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 грозовых желез, 1 слюнную железу грозового змея и 1 печень кодо пивовару Дрону в Кабестан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха! Я знал, что ты не откажешься от этого напитка. Приходи, я еще тебе сварю. Главное – приноси все необходимое.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пивовару Дрону в Кабестан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (823,'Явиться к Оргнилу','У нас, в деревне Сен\'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала. Так что спасибо тебе. Однако принесенные тобой вести о Пылающем Клинке сулят неприятности всем.$b$bВ Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок. Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты $gузнал:узнала; в Долине Испытаний. Ему нужно это знать.$b$bКолючий Холм находится к северу отсюда.','Поговорите с Оргнилом Душегрызом на Колючем Холме.','Да? Тебе есть, о чем доложить? Ну так рассказывай, чего ты ждешь?!','Как сейчас помню свою первую охоту на тигров! Я решил поохотиться на самом большом из островов Эхо. Я затаился в тени и ждал почти целый день.\n\nМои мускулы были напряжены, и я был готов выстрелить в любую секунду! Как же я торжествовал, когда мой первый тигр был повержен!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Явиться к Оргнилу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас, в деревне Сен\'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала. Так что спасибо тебе. Однако принесенные тобой вести о Пылающем Клинке сулят неприятности всем.$b$bВ Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок. Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты $gузнал:узнала; в Долине Испытаний. Ему нужно это знать.$b$bКолючий Холм находится к северу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Оргнилом Душегрызом на Колючем Холме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да? Тебе есть, о чем доложить? Ну так рассказывай, чего ты ждешь?!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как сейчас помню свою первую охоту на тигров! Я решил поохотиться на самом большом из островов Эхо. Я затаился в тени и ждал почти целый день.\n\nМои мускулы были напряжены, и я был готов выстрелить в любую секунду! Как же я торжествовал, когда мой первый тигр был повержен!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (824,'Дже\'неу из Служителей Земли','Служители Земли – сообщество шаманов, посвятивших себя изучению и охране Стихий. Они забыли о безумных древних богах, древних легендах и преданиях больше, чем большинство ученых вообще знало.$B$BПовезло тебе, что я знаю кое-кого из Служителей Земли тут, в Ясеневом лесу. Иди на заставу Зорам\'гар на Зорамское взморье и покажи Дже\'неу Санкри свою находку. Если кто и поймет, что это за шар, так это он.','Отнесите оскверненную водяную сферу Дже\'неу Санкри в Непроглядную Пучину.','А, привет. Я много времени трачу на изучение воды – вернее, всех Стихий – так много, что порой не замечаю никого вокруг.\n\nВ чем тебе помочь разобраться?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дже\'неу из Служителей Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Служители Земли – сообщество шаманов, посвятивших себя изучению и охране Стихий. Они забыли о безумных древних богах, древних легендах и преданиях больше, чем большинство ученых вообще знало.$B$BПовезло тебе, что я знаю кое-кого из Служителей Земли тут, в Ясеневом лесу. Иди на заставу Зорам\'гар на Зорамское взморье и покажи Дже\'неу Санкри свою находку. Если кто и поймет, что это за шар, так это он.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите оскверненную водяную сферу Дже\'неу Санкри в Непроглядную Пучину.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, привет. Я много времени трачу на изучение воды – вернее, всех Стихий – так много, что порой не замечаю никого вокруг.\n\nВ чем тебе помочь разобраться?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (825,'Обломки кораблекрушения','Один из моих лучших разведчиков принес сообщение, что обломки кораблей Праудмура все еще плавают около побережья Дуротара, к востоку от крепости Тирагард.$b$bНи для кого не секрет, что люди, будучи в союзе с этими маленькими уродцами, гномами, неплохо овладели механикой. Нам нужно знать все о нашем предполагаемом противнике! К тому же, эти знания пригодятся и нашему народу.$b$bСплавай к обломкам, $n, и добудь мне инструменты Альянса.','Га\'Ток с Колючего Холма просит вас принести ему 3 комплекта инструментов гномов, найти которые можно в обломках кораблей у побережья.','Ты успешно выполнил поручение, |3-6($C). Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном.\n\nМолодец!','Когда мы узнаем, как люди управляют своей странной техникой, у нас будет куда больше шансов победить их в грядущих битвах.\n\nС новыми знаниями Орда станет сильнее!','Вернитесь к Га\'Току в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обломки кораблекрушения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из моих лучших разведчиков принес сообщение, что обломки кораблей Праудмура все еще плавают около побережья Дуротара, к востоку от крепости Тирагард.$b$bНи для кого не секрет, что люди, будучи в союзе с этими маленькими уродцами, гномами, неплохо овладели механикой. Нам нужно знать все о нашем предполагаемом противнике! К тому же, эти знания пригодятся и нашему народу.$b$bСплавай к обломкам, $n, и добудь мне инструменты Альянса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Га\'Ток с Колючего Холма просит вас принести ему 3 комплекта инструментов гномов, найти которые можно в обломках кораблей у побережья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты успешно выполнил поручение, |3-6($C). Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном.\n\nМолодец!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда мы узнаем, как люди управляют своей странной техникой, у нас будет куда больше шансов победить их в грядущих битвах.\n\nС новыми знаниями Орда станет сильнее!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Га\'Току в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (826,'Залазан','Знахарь Залазан живет на островах Эха на востоке. Эти острова мы когда-то называли родиной...$b$bА теперь он оттуда посылает троллей на материк, досаждая нашему народу и переманивая на свою сторону все новых приспешников.$b$bЕго нужно остановить!$b$bУничтожь Залазана и его слуг – бывших троллей Черного Копья, ныне потерянных для нас! Принеси мне его голову – и я буду знать, что владычеству зла пришел конец.','Убейте Залазана, убейте 8 троллей-вудуистов и 8 проклятых троллей.$b$bПринесите голову Залазана Гадрину.','Вернитесь к мастеру Гадрину в деревню Сен\'джин, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Залазан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знахарь Залазан живет на островах Эха на востоке. Эти острова мы когда-то называли родиной...$b$bА теперь он оттуда посылает троллей на материк, досаждая нашему народу и переманивая на свою сторону все новых приспешников.$b$bЕго нужно остановить!$b$bУничтожь Залазана и его слуг – бывших троллей Черного Копья, ныне потерянных для нас! Принеси мне его голову – и я буду знать, что владычеству зла пришел конец.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Залазана, убейте 8 троллей-вудуистов и 8 проклятых троллей.$b$bПринесите голову Залазана Гадрину.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Гадрину в деревню Сен\'джин, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (827,'Скала Черепа','$n! Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как Скала Черепа. Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками.$b$bЯ подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами. Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников.$b$bСтупай в Скалу Черепа и отбери у фанатиков, которых там найдешь, их ошейники. Принеси их мне, и я раскрою их тайну!','Отберите у фанатиков из Скалы Черепа обжигающие ошейники.$b$bПринесите их в лагерь Маргозу.','Отлично! В этих ошейниках и таится секрет Пылающего Клинка. И я его раскрою!','Вернитесь к Маргозу в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скала Черепа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как Скала Черепа. Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками.$b$bЯ подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами. Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников.$b$bСтупай в Скалу Черепа и отбери у фанатиков, которых там найдешь, их ошейники. Принеси их мне, и я раскрою их тайну!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите у фанатиков из Скалы Черепа обжигающие ошейники.$b$bПринесите их в лагерь Маргозу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! В этих ошейниках и таится секрет Пылающего Клинка. И я его раскрою!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маргозу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (828,'Маргоз','Один из наших шаманов, Маргоз, многое знает о Пылающем Клинке. Как-то он рассказывал о пещере, которая называется Скала Черепа, в горах у самого Оргриммара. Там окопалась большая шайка сектантов из клана Пылающего Клинка.$b$bПрежде чем отправиться к Скале Черепа, поговори с Маргозом. Он мудр, и к его советам стоит прислушиваться.$b$bТы найдешь его на северо-востоке, между побережьем и Сухой лощиной.$b$bСледуй его советам, $n, но, что бы он ни сказал, я прошу тебя – уничтожь этих сектантов!','Поговорите с Маргозом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маргоз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из наших шаманов, Маргоз, многое знает о Пылающем Клинке. Как-то он рассказывал о пещере, которая называется Скала Черепа, в горах у самого Оргриммара. Там окопалась большая шайка сектантов из клана Пылающего Клинка.$b$bПрежде чем отправиться к Скале Черепа, поговори с Маргозом. Он мудр, и к его советам стоит прислушиваться.$b$bТы найдешь его на северо-востоке, между побережьем и Сухой лощиной.$b$bСледуй его советам, $n, но, что бы он ни сказал, я прошу тебя – уничтожь этих сектантов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Маргозом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (829,'Ниру Огненный Клинок','Принесенные тобой обжигающие ошейники – это мощные инструменты демонов. И распознать их происхождение мне, как шаману, не под силу. Нужно, чтобы на них взглянул чернокнижник.$b$bОтнеси один обжигающий ошейник Ниру Огненному Клинку. Он искусный чернокнижник, но утверждает, что использует свою силу лишь затем, чтобы вредить демонам, а еще говорит, что его оккультные исследования идут на пользу Орде. Правда это или нет, а его помощь нам еще может понадобиться в борьбе с последователями демонов в Дуротаре.$b$bНиру можно найти в Оргриммаре, в Расселине Теней.','Отнесите один обжигающий ошейник Ниру Огненному Клинку в Оргриммаре.','О! Откуда у тебя это? Тебя прислал ко мне славный Маргоз из Колючего Холма, верно?\n\nНу-ка, дай взглянуть...','Мое почтение, |3-6($C). Чем могу я помочь тебе, сестра?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ниру Огненный Клинок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принесенные тобой обжигающие ошейники – это мощные инструменты демонов. И распознать их происхождение мне, как шаману, не под силу. Нужно, чтобы на них взглянул чернокнижник.$b$bОтнеси один обжигающий ошейник Ниру Огненному Клинку. Он искусный чернокнижник, но утверждает, что использует свою силу лишь затем, чтобы вредить демонам, а еще говорит, что его оккультные исследования идут на пользу Орде. Правда это или нет, а его помощь нам еще может понадобиться в борьбе с последователями демонов в Дуротаре.$b$bНиру можно найти в Оргриммаре, в Расселине Теней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите один обжигающий ошейник Ниру Огненному Клинку в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О! Откуда у тебя это? Тебя прислал ко мне славный Маргоз из Колючего Холма, верно?\n\nНу-ка, дай взглянуть...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мое почтение, |3-6($C). Чем могу я помочь тебе, сестра?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (830,'Приказы адмирала','Вы открываете потрепанный и выгоревший конверт и обнаруживаете документ официального вида. На нем – печать адмирала Праудмура.$b$bПохоже, это что-то важное. Может быть, Га\'току, командиру Колючего Холма, эта информация пригодится...','Отнесите приказы адмирала Праудмура Га\'току на Колючий Холм.','Ничего хорошего это не предвещает... Очень хорошо, что ты принес это мне.','У тебя озабоченный вид, |3-6($C). Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказы адмирала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы открываете потрепанный и выгоревший конверт и обнаруживаете документ официального вида. На нем – печать адмирала Праудмура.$b$bПохоже, это что-то важное. Может быть, Га\'току, командиру Колючего Холма, эта информация пригодится...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите приказы адмирала Праудмура Га\'току на Колючий Холм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ничего хорошего это не предвещает... Очень хорошо, что ты принес это мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя озабоченный вид, |3-6($C). Что у тебя там?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (831,'Приказы адмирала','Людям верить нельзя. Мы сражались плечом к плечу с ними, но в глубине души знали, что рано или поздно они нас предадут.$b$bАдмирал Праудмур был убит, но этого оказалось недостаточно, чтобы остановить предательство. Этот подлый человечишка успел как следует продумать и изложить свои планы на бумаге, прежде чем встретил заслуженную смерть.$b$bПохоже, что его владычество не закончится даже со смертью Бенедикта. Кто знает, когда следующая волна людей Праудмура обрушится на наши берега?$b$bЭти приказы нужно немедленно доставить в Оргриммар, Вол\'джину! Ты найдешь его в зале приемов Тралла.','Доставьте приказы адмирала Праудмура Вол\'джину в зал приемов Тралла в Оргриммаре.','О, сколько раз я умолял вождя не доверять людям! Однако тут речь не о личной гордости.\n\nТы достойно послужила Орде, |3-6($C).\n\nА теперь извини, мне нужно немедленно поговорить об этом с Траллом!','Ты что, не видишь? Я занят. Ну, докладывай. Но если дело не срочное...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказы адмирала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Людям верить нельзя. Мы сражались плечом к плечу с ними, но в глубине души знали, что рано или поздно они нас предадут.$b$bАдмирал Праудмур был убит, но этого оказалось недостаточно, чтобы остановить предательство. Этот подлый человечишка успел как следует продумать и изложить свои планы на бумаге, прежде чем встретил заслуженную смерть.$b$bПохоже, что его владычество не закончится даже со смертью Бенедикта. Кто знает, когда следующая волна людей Праудмура обрушится на наши берега?$b$bЭти приказы нужно немедленно доставить в Оргриммар, Вол\'джину! Ты найдешь его в зале приемов Тралла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте приказы адмирала Праудмура Вол\'джину в зал приемов Тралла в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, сколько раз я умолял вождя не доверять людям! Однако тут речь не о личной гордости.\n\nТы достойно послужила Орде, |3-6($C).\n\nА теперь извини, мне нужно немедленно поговорить об этом с Траллом!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты что, не видишь? Я занят. Ну, докладывай. Но если дело не срочное...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (832,'Пылающие тени','*Слова из амулета плавно перетекают в ваш разум.* $B$BГазз\'уз! $B$BГазз\'уз, докладывай! $B$BО том, что ты нашел в Скале Черепа, уже стало известно. Готовься к нападению!$B$BГовори, Газз\'уз! Говори, или я позабочусь о том, чтобы о твоем присутствии стало известно Ниру Огненному Клинку, а уж он-то тебя не пощадит!$B$BС Ниру тебе лучше не связываться...$B$BГазз\'уз, ты меня слышишь?','Отнесите этот амулет Ниру Огненному Клинку в Оргриммар.','<Нииру разглядывает Око Пылающей Тени.>$B$BЛюбопытно. Так ты говоришь, голос упоминал мое имя? Я, конечно, известен как непримиримый враг противников нашего вождя, но все же странно, что голос назвал именно меня. Тем более странно, что название секты, у членов которой ты нашел этот амулет, так похоже на мою фамилию.$B$BНадо изучить эту подвеску. Изучить и поразмыслить над тем, что значит это сообщение.$B$BСпасибо, $N, что сообщил мне об этом. Ты оказал своему народу серьезную услугу.','Ты хочешь рассказать мне о чем-то важном, по глазам вижу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пылающие тени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Слова из амулета плавно перетекают в ваш разум.* $B$BГазз\'уз! $B$BГазз\'уз, докладывай! $B$BО том, что ты нашел в Скале Черепа, уже стало известно. Готовься к нападению!$B$BГовори, Газз\'уз! Говори, или я позабочусь о том, чтобы о твоем присутствии стало известно Ниру Огненному Клинку, а уж он-то тебя не пощадит!$B$BС Ниру тебе лучше не связываться...$B$BГазз\'уз, ты меня слышишь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите этот амулет Ниру Огненному Клинку в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Нииру разглядывает Око Пылающей Тени.>$B$BЛюбопытно. Так ты говоришь, голос упоминал мое имя? Я, конечно, известен как непримиримый враг противников нашего вождя, но все же странно, что голос назвал именно меня. Тем более странно, что название секты, у членов которой ты нашел этот амулет, так похоже на мою фамилию.$B$BНадо изучить эту подвеску. Изучить и поразмыслить над тем, что значит это сообщение.$B$BСпасибо, $N, что сообщил мне об этом. Ты оказал своему народу серьезную услугу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь рассказать мне о чем-то важном, по глазам вижу!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (833,'Священное погребение','Лишь самых доблестных тауренов хоронят в Красных cкалах, на нашем священном кладбище. Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утес, и тем, кто отдал свои жизни на благо племени и вождей. $B$BПохоже, теперь на эту священную землю пала тень. Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их. $B$BПротив них поможет только сила, |3-6($c).','Убейте 8 злоумышленников из племени Дыбогривов в Красных cкалах.','Молодец. Ты проучил племя Дыбогривов. Теперь они сто раз подумают, прежде чем осквернять святые для нас места.','Злоумышленников надо изгнать с нашего священного кладбища, $N.','Вернитесь к Сказителю Тотему Дождя в Лагерь Солнечного Пастбища, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священное погребение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лишь самых доблестных тауренов хоронят в Красных cкалах, на нашем священном кладбище. Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утес, и тем, кто отдал свои жизни на благо племени и вождей. $B$BПохоже, теперь на эту священную землю пала тень. Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их. $B$BПротив них поможет только сила, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 злоумышленников из племени Дыбогривов в Красных cкалах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец. Ты проучил племя Дыбогривов. Теперь они сто раз подумают, прежде чем осквернять святые для нас места.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Злоумышленников надо изгнать с нашего священного кладбища, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сказителю Тотему Дождя в Лагерь Солнечного Пастбища, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (834,'Ветра пустыни','Я – Резлак, один из ребят Газлоу. Шеф послал меня на помощь оркам в Дуротаре. Все бы хорошо, если бы не проблемы с караванами. Точнее, с охраной караванов. Как ты думаешь, можно ли работать, когда караваны все время грабят?$b$bПоследний караван – они мне клялись, что уж он-то точно дойдет! – перехватили гарпии Пыльного Ветра в... как же его... Каньоне Колючего Ветра!$b$bА мне этот груз позарез нужен, я без него как без рук! Ступай по большому каньону на юг, там будет расселина, идущая с запада на восток...','Добудьте 5 мешков припасов.','О, то что надо! Наши припасы! Замечательно. Я смогу снова взяться за работу, как только найду кого-нибудь, кто донесет мне эти мешки.','Не пойми меня неправильно, я мастер своего дела, но ведь это же просто смешно! Что мне тут делать, песочные замки строить?','Вернитесь к Резлаку в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветра пустыни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я – Резлак, один из ребят Газлоу. Шеф послал меня на помощь оркам в Дуротаре. Все бы хорошо, если бы не проблемы с караванами. Точнее, с охраной караванов. Как ты думаешь, можно ли работать, когда караваны все время грабят?$b$bПоследний караван – они мне клялись, что уж он-то точно дойдет! – перехватили гарпии Пыльного Ветра в... как же его... Каньоне Колючего Ветра!$b$bА мне этот груз позарез нужен, я без него как без рук! Ступай по большому каньону на юг, там будет расселина, идущая с запада на восток...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 мешков припасов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, то что надо! Наши припасы! Замечательно. Я смогу снова взяться за работу, как только найду кого-нибудь, кто донесет мне эти мешки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не пойми меня неправильно, я мастер своего дела, но ведь это же просто смешно! Что мне тут делать, песочные замки строить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Резлаку в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (835,'Обеспечение безопасного сообщения','Газлоу мне как-то сказал: "Резлак, заруби себе на носу: если хочешь, чтобы что-то было сделано хорошо, сделай это сам".$b$bМы не можем и дальше терять караваны, так что я вынужден взять дело в собственные руки. Наши торговые пути заполонены гарпиями. Если удастся их перебить, дороги вновь станут безопасными.$b$bРазумеется, Газлоу учил меня и другому: "За соответствующую плату тебе сделают что угодно". Ну что, $n, возьмешься? Отлично... Советую начать с каньона на востоке.','Убейте 12 дуротарских гарпий. Подойдут любые разновидности гарпий.','Даже не верится, что такое мог говорить мой шеф, Газлоу, а ведь он мужик соображающий. "Не бойся рисковать, когда надо", – вот что он говорил.\n\nВедь гарпии так и будут нападать на нас и на караваны, пока мы что-нибудь с этим не сделаем, верно?','Вернитесь к Резлаку в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обеспечение безопасного сообщения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Газлоу мне как-то сказал: "Резлак, заруби себе на носу: если хочешь, чтобы что-то было сделано хорошо, сделай это сам".$b$bМы не можем и дальше терять караваны, так что я вынужден взять дело в собственные руки. Наши торговые пути заполонены гарпиями. Если удастся их перебить, дороги вновь станут безопасными.$b$bРазумеется, Газлоу учил меня и другому: "За соответствующую плату тебе сделают что угодно". Ну что, $n, возьмешься? Отлично... Советую начать с каньона на востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 дуротарских гарпий. Подойдут любые разновидности гарпий.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Даже не верится, что такое мог говорить мой шеф, Газлоу, а ведь он мужик соображающий. "Не бойся рисковать, когда надо", – вот что он говорил.\n\nВедь гарпии так и будут нападать на нас и на караваны, пока мы что-нибудь с этим не сделаем, верно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Резлаку в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (836,'Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (837,'Вторжение','Когда мы поселились здесь, свинобразы Иглогривых владели большей частью этих земель и оказались сущей напастью! Большую их часть нам мало-помалу удалось вытеснить, но в некоторых районах они окопались прочно.$b$bНо с нас уже довольно! Мы не можем больше терпеть присутствие Иглогривых в наших землях. Их лагеря – к западу отсюда. Они часто прячутся в зарослях колючек. Сегодня мы вытесним их из Дуротара – а завтра, глядишь, и из всего Калимдора!','Убейте 4 свинобразов из племени Иглогривых, 4 разведчиков из племени Иглогривых, 4 пылемутов из племени Иглогривых и 4 боевых стражей из племени Иглогривых по просьбе Га\'Тока из Колючего Холма.','Я расскажу всем, что Иглогривы прогнаны со своих обжитых мест, и что их жилища надо сжечь. Теперь, когда племя Иглогривых изгнано из Дуротара, границы нашей новой родины станут значительно безопаснее.','Хотя они действительно обладают неким интеллектом и организацией, но я считаю это просто удивительным, что Иглогривым удавалось удерживать столько территории на Калимдоре. Возможно, они более хитрый враг, нежели я думаю.','Вернитесь к Га\'Току в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда мы поселились здесь, свинобразы Иглогривых владели большей частью этих земель и оказались сущей напастью! Большую их часть нам мало-помалу удалось вытеснить, но в некоторых районах они окопались прочно.$b$bНо с нас уже довольно! Мы не можем больше терпеть присутствие Иглогривых в наших землях. Их лагеря – к западу отсюда. Они часто прячутся в зарослях колючек. Сегодня мы вытесним их из Дуротара – а завтра, глядишь, и из всего Калимдора!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 свинобразов из племени Иглогривых, 4 разведчиков из племени Иглогривых, 4 пылемутов из племени Иглогривых и 4 боевых стражей из племени Иглогривых по просьбе Га\'Тока из Колючего Холма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я расскажу всем, что Иглогривы прогнаны со своих обжитых мест, и что их жилища надо сжечь. Теперь, когда племя Иглогривых изгнано из Дуротара, границы нашей новой родины станут значительно безопаснее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хотя они действительно обладают неким интеллектом и организацией, но я считаю это просто удивительным, что Иглогривым удавалось удерживать столько территории на Калимдоре. Возможно, они более хитрый враг, нежели я думаю.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Га\'Току в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (838,'Некроситет','На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью Плети. В ее недрах наши враги спокойно проводят исследования, делаясь все сильнее. Путь преграждают двери, и без подходящего ключа внутрь не войти.$B$BАптекарь Дитерс многое знает о Некроситете и придумал, как достать ключ. Ты $gзарекомендовал:зарекомендовала; себя как человека с большими способностями, поэтому я доверяю тебе это задание. Обсуди подробности с аптекарем.','Поговорите с аптекарем Дитерсом из Бастиона, что в Западных Чумных землях.','Да, $C. Верховный палач упоминал, что тебе можно доверить тайну ключа. В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ, позволяющий отомкнуть двери в любой момент.$B$BДело, как всегда, будет непростым. Но судя по всему, тебя такими словами не напугать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Некроситет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью Плети. В ее недрах наши враги спокойно проводят исследования, делаясь все сильнее. Путь преграждают двери, и без подходящего ключа внутрь не войти.$B$BАптекарь Дитерс многое знает о Некроситете и придумал, как достать ключ. Ты $gзарекомендовал:зарекомендовала; себя как человека с большими способностями, поэтому я доверяю тебе это задание. Обсуди подробности с аптекарем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с аптекарем Дитерсом из Бастиона, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $C. Верховный палач упоминал, что тебе можно доверить тайну ключа. В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ, позволяющий отомкнуть двери в любой момент.$B$BДело, как всегда, будет непростым. Но судя по всему, тебя такими словами не напугать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (839,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (840,'Новобранец Орды','Хм, $gслабаком:слабенькой; тебя не назовешь...$b$bПослушай, моему приятелю Каргалу нужны новобранцы для службы в Степях. Ты ведь хочешь принести пользу Орде? Ну вот, это твой шанс.$b$bПередай Каргалу это письмо о найме – возможно, он его подпишет.','Отдайте Каргалу Боевому Шраму ваше письмо о найме.','Чего тебе надо, молокосос? Если ты новобранец, давай сюда письмо, а иначе проваливай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новобранец Орды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм, $gслабаком:слабенькой; тебя не назовешь...$b$bПослушай, моему приятелю Каргалу нужны новобранцы для службы в Степях. Ты ведь хочешь принести пользу Орде? Ну вот, это твой шанс.$b$bПередай Каргалу это письмо о найме – возможно, он его подпишет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте Каргалу Боевому Шраму ваше письмо о найме.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего тебе надо, молокосос? Если ты новобранец, давай сюда письмо, а иначе проваливай.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (841,'Еще один источник энергии?','Дай-ка я угадаю – ты не $gуспел:успела; осуществить свой страшный замысел, губительный для мироздания. Нет, еще лучше... Ты $gуронил:уронила; его в песок! Короче, в любом случае я могу продать тебе еще один источник энергии. Только на сей раз он обойдется в десять, да, ДЕСЯТЬ, бурдюков с водой Скитальцев Пустыни!$b$bВремена настали тяжелые, а источники энергии не растут на деревьях! Хм, а что, если росли бы? Может, нам сконструировать дерево источников энергии...','Принесите 10 бурдюков с водой Скитальцев Пустыни главному инженеру Чепухастеру в Прибамбасск в обмен на еще один источник энергии.','Ладно, вот еще один источник энергии. Очень советую применить его по назначению, если не хочешь добыть для меня еще десять мехов воды.','И где мои десять бурдюков с водой?','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще один источник энергии?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дай-ка я угадаю – ты не $gуспел:успела; осуществить свой страшный замысел, губительный для мироздания. Нет, еще лучше... Ты $gуронил:уронила; его в песок! Короче, в любом случае я могу продать тебе еще один источник энергии. Только на сей раз он обойдется в десять, да, ДЕСЯТЬ, бурдюков с водой Скитальцев Пустыни!$b$bВремена настали тяжелые, а источники энергии не растут на деревьях! Хм, а что, если росли бы? Может, нам сконструировать дерево источников энергии...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 бурдюков с водой Скитальцев Пустыни главному инженеру Чепухастеру в Прибамбасск в обмен на еще один источник энергии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ладно, вот еще один источник энергии. Очень советую применить его по назначению, если не хочешь добыть для меня еще десять мехов воды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И где мои десять бурдюков с водой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (842,'Рекрутский набор Перекрестка','<Каргал извлекает сильно помятое письмо из-за пазухи и подписывает его, а затем торжественно протягивает его вам.>$b$bНу, $gмолокосос:девчонка;, я увидел, что ты можешь быть грозным противником. Считай, что $gпринят:принята;. Теперь ты потребуешься нам в Перекрестке – если, конечно, доберешься туда $gживым:живой;. Следуй по дороге, ведущей отсюда на запад, а затем на развилке на юг. Если действительно хочешь помочь Орде, поговори с Халгой и отправляйся с ее следующим караваном. Отдашь письмо Сергре Черный Шип сразу же как прибудешь.','Отнесите подписанное письмо Сергре Черный Шип в Перекрестке. Можете присоединиться к ближайшему каравану, поговорив с Халгой Кровавый Глаз на Дальней заставе.','Ну-с, и кто у нас тут? Неужели Каргал снизошел до того, чтобы прислать мне очередного рекрута?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рекрутский набор Перекрестка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Каргал извлекает сильно помятое письмо из-за пазухи и подписывает его, а затем торжественно протягивает его вам.>$b$bНу, $gмолокосос:девчонка;, я увидел, что ты можешь быть грозным противником. Считай, что $gпринят:принята;. Теперь ты потребуешься нам в Перекрестке – если, конечно, доберешься туда $gживым:живой;. Следуй по дороге, ведущей отсюда на запад, а затем на развилке на юг. Если действительно хочешь помочь Орде, поговори с Халгой и отправляйся с ее следующим караваном. Отдашь письмо Сергре Черный Шип сразу же как прибудешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите подписанное письмо Сергре Черный Шип в Перекрестке. Можете присоединиться к ближайшему каравану, поговорив с Халгой Кровавый Глаз на Дальней заставе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну-с, и кто у нас тут? Неужели Каргал снизошел до того, чтобы прислать мне очередного рекрута?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (843,'Ответный удар Ганна','Ныне я брожу по дорогам родного края в одиночестве.$b$bДворфы Бейл Модана не чтят моих границ. Они постоянно устраивают взрывы, после которых остаются огромные ямы, а шумные механизмы разрывают мои холмы. Земли, некогда приютившие и питавшие мое племя, захвачены вредоносными дворфами.$B$BВсе попытки решить дело миром провалились. Пришло время для решительных действий.$B$BВыгони дворфов из раскопа в Бейл Модане и принеси мне записи Хазгорма, их главаря.','Ганн Каменное Копье попросил вас убить 15 бейл\'данских землечерпов и 5 бейл\'данских старшин.$b$bПринесите Ганну Каменному Копью записи Хазгорма.','Хазгорм заслужил свою судьбу. Мне нисколько его не жаль. Он явился в наши края незванным.\n\nБыть может, его смерть послужит предостережением тем, кто пытается нарушить наш покой.\n\nДай-ка я изучу записи этого дворфа...','С появлением в Бейл Модане дворфов многие ни в чем не повинные таурены лишились жизни или покинули родину предков. Я должен вернуть свои земли!','Вернитесь к Ганну Каменному Копью на Южный Золотой Путь, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ответный удар Ганна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ныне я брожу по дорогам родного края в одиночестве.$b$bДворфы Бейл Модана не чтят моих границ. Они постоянно устраивают взрывы, после которых остаются огромные ямы, а шумные механизмы разрывают мои холмы. Земли, некогда приютившие и питавшие мое племя, захвачены вредоносными дворфами.$B$BВсе попытки решить дело миром провалились. Пришло время для решительных действий.$B$BВыгони дворфов из раскопа в Бейл Модане и принеси мне записи Хазгорма, их главаря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ганн Каменное Копье попросил вас убить 15 бейл\'данских землечерпов и 5 бейл\'данских старшин.$b$bПринесите Ганну Каменному Копью записи Хазгорма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хазгорм заслужил свою судьбу. Мне нисколько его не жаль. Он явился в наши края незванным.\n\nБыть может, его смерть послужит предостережением тем, кто пытается нарушить наш покой.\n\nДай-ка я изучу записи этого дворфа...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С появлением в Бейл Модане дворфов многие ни в чем не повинные таурены лишились жизни или покинули родину предков. Я должен вернуть свои земли!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ганну Каменному Копью на Южный Золотой Путь, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (844,'Равнинные долгоноги','Тебе приходилось встречаться с равнинными долгоногами? Бесполезные животные. Летать не могут. Воняют. Мозгов с куриное яйцо. И такие бестолковые, что не могут отбежать в сторону от повозки. Мы уже о них столько колес сломали! Иногда мне кажется, что свинобразы специально сгоняют их на путь следования наших караванов, когда хотят устроить засаду.$B$BПорадуй меня, |3-6($c). Расчисти нам дорогу от этих безмозглых птиц, а в качестве доказательства выполненной работы принеси несколько клювов.','Соберите 7 клювов равнинных долгоногов.','Принес клювы долгоногов?','Доставьте клювы Халге Кровавый Глаз на Дальнюю заставу, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Равнинные долгоноги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе приходилось встречаться с равнинными долгоногами? Бесполезные животные. Летать не могут. Воняют. Мозгов с куриное яйцо. И такие бестолковые, что не могут отбежать в сторону от повозки. Мы уже о них столько колес сломали! Иногда мне кажется, что свинобразы специально сгоняют их на путь следования наших караванов, когда хотят устроить засаду.$B$BПорадуй меня, |3-6($c). Расчисти нам дорогу от этих безмозглых птиц, а в качестве доказательства выполненной работы принеси несколько клювов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 клювов равнинных долгоногов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принес клювы долгоногов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте клювы Халге Кровавый Глаз на Дальнюю заставу, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (845,'Жевры','Если ты хочешь послужить во славу Орды, нужно будет сначала немного потрудиться и показать свою силу. Хотя жевры – не самые страшные звери в Степях, но под удары их копыт лучше не подставляться, иначе пожалеешь. Как раз подойдут для того, чтобы ты $gсмог:смогла; поточить зубки. $B$BПоохоться на жевр на севере и на юге и собери их копыта. Принеси их мне, и, быть может, в следующий раз мы отправим тебя на более опасное задание.','Убивайте жевр-бегунов, пока не наберете 4 пары копыт жевры.','Сколько жевр тебе удалось убить?','Отнесите копыта Сергре Черный Шип в Перекресток в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жевры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты хочешь послужить во славу Орды, нужно будет сначала немного потрудиться и показать свою силу. Хотя жевры – не самые страшные звери в Степях, но под удары их копыт лучше не подставляться, иначе пожалеешь. Как раз подойдут для того, чтобы ты $gсмог:смогла; поточить зубки. $B$BПоохоться на жевр на севере и на юге и собери их копыта. Принеси их мне, и, быть может, в следующий раз мы отправим тебя на более опасное задание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте жевр-бегунов, пока не наберете 4 пары копыт жевры.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько жевр тебе удалось убить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите копыта Сергре Черный Шип в Перекресток в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (846,'Месть Ганна','Очевидно, что шахтеры не могут обойтись без взрывчатки и шумных землеройных машин. Мы думаем, что скоро туда направят нового старшину.$B$BПусть проклятые дворфы отведают собственного угощения. Согласно схемам, если смешать нитроглицерин с древесной сердцевиной и натриевой селитрой, получится взрывной заряд. Все компоненты есть у ружейников, солдат и офицеров из Крепости.$B$BСобери все необходимое и принеси мне. Я создам заряд, который дворфы не скоро забудут!','Ганн Каменное Копье попросил вас принести ему 6 сосудов с нитроглицерином, 6 пучков древесной сердцевины и 6 образцов натриевой селитры.','Вижу, ты зря времени не терял, |3-6($C).\n\nОчень скоро дворфов ожидает неприятный сюрприз!','Вернитесь к Ганну Каменному Копью на Южный Золотой Путь, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Ганна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Очевидно, что шахтеры не могут обойтись без взрывчатки и шумных землеройных машин. Мы думаем, что скоро туда направят нового старшину.$B$BПусть проклятые дворфы отведают собственного угощения. Согласно схемам, если смешать нитроглицерин с древесной сердцевиной и натриевой селитрой, получится взрывной заряд. Все компоненты есть у ружейников, солдат и офицеров из Крепости.$B$BСобери все необходимое и принеси мне. Я создам заряд, который дворфы не скоро забудут!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ганн Каменное Копье попросил вас принести ему 6 сосудов с нитроглицерином, 6 пучков древесной сердцевины и 6 образцов натриевой селитры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, ты зря времени не терял, |3-6($C).\n\nОчень скоро дворфов ожидает неприятный сюрприз!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ганну Каменному Копью на Южный Золотой Путь, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (847,'Коварство ящера','Эта... эта сила... Это и есть мощь шаманов, которую Тор\'Ган пытался мне показать? Должен сказать, весьма интересно. Скажите Тор\'Гану, что он меня убедил... на данный момент. Я выслушаю то, что он хочет мне сказать.','Поговорите с Тор\'ганом в Павшем Молоте, что на Нагорье Арати.','Когда чары спадут, я поговорю с Гор\'мулем. Благодарю вас за помощь в возвращении Гор\'муля к жизни. Я не сомневаюсь, что и он очень благодарен вам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коварство ящера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта... эта сила... Это и есть мощь шаманов, которую Тор\'Ган пытался мне показать? Должен сказать, весьма интересно. Скажите Тор\'Гану, что он меня убедил... на данный момент. Я выслушаю то, что он хочет мне сказать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тор\'ганом в Павшем Молоте, что на Нагорье Арати.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда чары спадут, я поговорю с Гор\'мулем. Благодарю вас за помощь в возвращении Гор\'муля к жизни. Я не сомневаюсь, что и он очень благодарен вам.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (848,'Споры грибов','Оазисы Степей скрывают немало тайн. В их водах разлита энергия жизни, питающая и укрепляющая растения и животных.$B$BИ меняющая их.$B$BНа северо-западе, у Забытых прудов, растут грибы, чьи споры мы, аптекари Лордерона, используем при создании снадобий.$B$BПринеси мне эти споры – и благодарность наша будет велика.','Соберите 5 порций спор грибов у Забытых прудов.','Отнесите споры аптекарю Хелбриму в Перекресток в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Споры грибов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оазисы Степей скрывают немало тайн. В их водах разлита энергия жизни, питающая и укрепляющая растения и животных.$B$BИ меняющая их.$B$BНа северо-западе, у Забытых прудов, растут грибы, чьи споры мы, аптекари Лордерона, используем при создании снадобий.$B$BПринеси мне эти споры – и благодарность наша будет велика.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 порций спор грибов у Забытых прудов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите споры аптекарю Хелбриму в Перекресток в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (849,'Месть Ганна','Изучив схемы Хазгорма, можно без труда создать взрывчатку.$B$BНу вот, готово. $b$bА теперь, $n, я дам тебе особое задание. Возьми взрывчатку и подорви ветролет в Бейл Модане.$B$BЭта машина не просто играет ключевую роль в снабжении раскопок, она служит и для военных целей. И что еще важнее – она воплощение мощи дворфов и оскорбление памяти моего племени.$B$BВыполни это задание, и я буду гордиться тобой! Ну и награду ты тоже получишь.','Уничтожьте ветролет в Бейл Модане и возвращайтесь к Ганну Каменному Копью.','Ну вот, теперь, когда дворфийский ветролет уничтожен, я ощущаю сладость мести.','Вернитесь к Ганну Каменному Копью на Южный Золотой Путь, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Ганна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изучив схемы Хазгорма, можно без труда создать взрывчатку.$B$BНу вот, готово. $b$bА теперь, $n, я дам тебе особое задание. Возьми взрывчатку и подорви ветролет в Бейл Модане.$B$BЭта машина не просто играет ключевую роль в снабжении раскопок, она служит и для военных целей. И что еще важнее – она воплощение мощи дворфов и оскорбление памяти моего племени.$B$BВыполни это задание, и я буду гордиться тобой! Ну и награду ты тоже получишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте ветролет в Бейл Модане и возвращайтесь к Ганну Каменному Копью.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну вот, теперь, когда дворфийский ветролет уничтожен, я ощущаю сладость мести.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ганну Каменному Копью на Южный Золотой Путь, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (850,'Главари племени Колкар','Сотни лет кентавры вставали на пути тауренов. В последнее время клан Колкар начал всерьез грозить безопасности Степей. Раньше им мешала побеждать их собственная неорганизованность, но недавно среди них появились новые вожди. Они создали из своих сородичей войско.$B$BЧтобы сохранить наши земли, мы должны убить вождей кентавров.$B$BПринеси мне голову Барака Кодобоя. Он живет в лагере к западу от Забытых прудов.$B$BКогда одержишь над ним верх, возвращайся.','Убейте Барака Кодобоя и отрубите ему голову.','Отнесите голову Кодобоя Телару Скитальцу к Забытым прудам в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главари племени Колкар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сотни лет кентавры вставали на пути тауренов. В последнее время клан Колкар начал всерьез грозить безопасности Степей. Раньше им мешала побеждать их собственная неорганизованность, но недавно среди них появились новые вожди. Они создали из своих сородичей войско.$B$BЧтобы сохранить наши земли, мы должны убить вождей кентавров.$B$BПринеси мне голову Барака Кодобоя. Он живет в лагере к западу от Забытых прудов.$B$BКогда одержишь над ним верх, возвращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Барака Кодобоя и отрубите ему голову.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите голову Кодобоя Телару Скитальцу к Забытым прудам в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (851,'Верог Дервиш','Найти кентавра Верога может быть нелегко, но ты уже знаешь, что в командном шатре всегда находится его подруга Винет. Это к западу отсюда. Если убить ее, Верог точно примчится.$b$bРегтар послал нас сюда, чтобы мы все разузнали, но он также сказал, что, если получится, нам надо использовать любую возможность нанести урон кентаврам. Перехитри Верога и убей его!','Убейте Винет, чтобы выманить кентавра Верога, и отрубите ему голову.','Принесите голову кентавра Верога Шузе в Застывший оазис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верог Дервиш',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Найти кентавра Верога может быть нелегко, но ты уже знаешь, что в командном шатре всегда находится его подруга Винет. Это к западу отсюда. Если убить ее, Верог точно примчится.$b$bРегтар послал нас сюда, чтобы мы все разузнали, но он также сказал, что, если получится, нам надо использовать любую возможность нанести урон кентаврам. Перехитри Верога и убей его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Винет, чтобы выманить кентавра Верога, и отрубите ему голову.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите голову кентавра Верога Шузе в Застывший оазис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (852,'Хэзрул Кровавая Отметина','Хэзрул Кровавая Отметина – глава кентаврского клана Колкар в Степях. Он свиреп, жесток и хитер. Одолев его, ты нанесешь серьезный урон клану, а значит, кентавры станут меньше угрожать нам.$B$BИтак, убей его. Принеси мне его голову, а я повешу ее на всеобщее обозрение на заставе – пусть нас боятся.$B$BХэзрул управляет своим народом из Цветущего оазиса на юге.','Убейте Хэзрула и отрубите ему голову.','Так Хэрзул повержен?','Принесите голову Хэзрула Регтару Вратам Смерти на его заставу в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хэзрул Кровавая Отметина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хэзрул Кровавая Отметина – глава кентаврского клана Колкар в Степях. Он свиреп, жесток и хитер. Одолев его, ты нанесешь серьезный урон клану, а значит, кентавры станут меньше угрожать нам.$B$BИтак, убей его. Принеси мне его голову, а я повешу ее на всеобщее обозрение на заставе – пусть нас боятся.$B$BХэзрул управляет своим народом из Цветущего оазиса на юге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Хэзрула и отрубите ему голову.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так Хэрзул повержен?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите голову Хэзрула Регтару Вратам Смерти на его заставу в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (854,'Путешествие в Перекресток','Я знал, что ты придешь, $gюный:юная:c; |3-6($c). Хотя, пожалуй, ты уже не так $gюн:юна;.$B$BДумаю, тебе пора двинуться вглубь этих земель. Я чую, что тебе предстоят великие свершения. $B$BСтупай в Перекресток. Наша судьба тесно связана с судьбой орков, а им нужна помощь. Иди по дороге на восток, а потом сверни на север, к Перекрестку. Отыщи Тхорка в стенах города, ибо с ним пребывает благословение Матери-Земли.','Поговорите с Тхорком на Перекрестке в Степях.','Я рад, что нам на помощь прибыли союзники из самого Громового Утеса. Добро пожаловать!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в Перекресток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знал, что ты придешь, $gюный:юная:c; |3-6($c). Хотя, пожалуй, ты уже не так $gюн:юна;.$B$BДумаю, тебе пора двинуться вглубь этих земель. Я чую, что тебе предстоят великие свершения. $B$BСтупай в Перекресток. Наша судьба тесно связана с судьбой орков, а им нужна помощь. Иди по дороге на восток, а потом сверни на север, к Перекрестку. Отыщи Тхорка в стенах города, ибо с ним пребывает благословение Матери-Земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тхорком на Перекрестке в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что нам на помощь прибыли союзники из самого Громового Утеса. Добро пожаловать!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (855,'Наручи кентавров','Сила кентавров зиждется на группе надежных, дисциплинированных воинов, которые могут управлять остальными кентаврами. Если мы сократим их количество, клан Колкар лишится разумного руководства, которое могло бы направить их гнев в нужное русло. В связи с этим у меня есть для тебя прибыльное задание.$B$BОтправляйся в Цветущий Оазис к югу отсюда, перебей мародеров и предвестников бури из племени Колкар и принеси мне их наручи. Возвращайся с трофеями, и Орда тебя наградит.','Соберите 10 наручей кентавров-мародеров и предвестниц бури из племени Колкар.','Отнесите наручи Регтару Вратам Смерти на его заставу в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наручи кентавров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сила кентавров зиждется на группе надежных, дисциплинированных воинов, которые могут управлять остальными кентаврами. Если мы сократим их количество, клан Колкар лишится разумного руководства, которое могло бы направить их гнев в нужное русло. В связи с этим у меня есть для тебя прибыльное задание.$B$BОтправляйся в Цветущий Оазис к югу отсюда, перебей мародеров и предвестников бури из племени Колкар и принеси мне их наручи. Возвращайся с трофеями, и Орда тебя наградит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 наручей кентавров-мародеров и предвестниц бури из племени Колкар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите наручи Регтару Вратам Смерти на его заставу в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (856,'<UNUSED>','Though you have reached the Barrens, your journey is not complete. You must continue on to the Crossroads, where you are needed most.$B$BFollow the road as you were, and turn left where the path gives you the choice. Follow it North until you see the walls of the Crossroads.$B$BJust before you enter, you should see the Ancestral Sage, he will have words of wisdom for you.','Continue down the road from Camp Taurajo.$B$BTurn left at the T intersection and continue North.$B$BFollow the path to the Ancestral Sage outside the Crossroads.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Though you have reached the Barrens, your journey is not complete. You must continue on to the Crossroads, where you are needed most.$B$BFollow the road as you were, and turn left where the path gives you the choice. Follow it North until you see the walls of the Crossroads.$B$BJust before you enter, you should see the Ancestral Sage, he will have words of wisdom for you.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Continue down the road from Camp Taurajo.$B$BTurn left at the T intersection and continue North.$B$BFollow the path to the Ancestral Sage outside the Crossroads.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (857,'Слеза Лун','Она была у меня в руках! В этих самых руках! И я хочу вернуть ее! Она моя!$B$BЕе откопали эти грязные землечерпы... как же прекрасна она была!.. Ее назвали слеза Лун. Первое серьезное открытие в Бейл Модане.$B$BОна должна достаться мне! Мне, говорю!$B$BГенерал Двукосса позавидовал силе, которую она мне давала, и запер ее в Крепости. Сказал, что эта вещь проклята. Дурак!$B$BЕе хотели заполучить и другие, мне пришлось их остановить. А этот мерзавец Двукосса прогнал меня.$B$BА я хочу ее вернуть. Она моя!','Фриглай Изгнанник попросил вас вернуть ему слезу Лун.','Наконец-то сила снова со мной! Со мной, говорю!','Где слеза Лун? Она мне нужна! Нужна, говорю!','Вернитесь к Фиглаю Изгнаннику в Бейл Модан, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слеза Лун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Она была у меня в руках! В этих самых руках! И я хочу вернуть ее! Она моя!$B$BЕе откопали эти грязные землечерпы... как же прекрасна она была!.. Ее назвали слеза Лун. Первое серьезное открытие в Бейл Модане.$B$BОна должна достаться мне! Мне, говорю!$B$BГенерал Двукосса позавидовал силе, которую она мне давала, и запер ее в Крепости. Сказал, что эта вещь проклята. Дурак!$B$BЕе хотели заполучить и другие, мне пришлось их остановить. А этот мерзавец Двукосса прогнал меня.$B$BА я хочу ее вернуть. Она моя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Фриглай Изгнанник попросил вас вернуть ему слезу Лун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то сила снова со мной! Со мной, говорю!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где слеза Лун? Она мне нужна! Нужна, говорю!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фиглаю Изгнаннику в Бейл Модан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (858,'Зажигание','Тебя случайно не Пароклапан прислал? У меня проблемы. Я запрыгнул внутрь, не подумав, что для запуска крошшера нужен ключ. Один из операторов спросил меня, все ли в порядке, и я впал в панику! Вместо того чтобы сказать, что я не взял с собой ключ, я заявил, что крошшер неисправен.$b$bНадо поскорее выбираться отсюда! Поднимись в комнату управления на вышке, у бригадира Зубовиззла должен быть ключ от этого шреддера.$B$BВыручи меня!','Добудьте ключ зажигания у бригадира Зубовиззла.','Скорее, надо выбираться отсюда, пока никто ничего не заподозрил!','Отнесите ключ от крошшера Зигзага на Нефтяное болото в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зажигание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя случайно не Пароклапан прислал? У меня проблемы. Я запрыгнул внутрь, не подумав, что для запуска крошшера нужен ключ. Один из операторов спросил меня, все ли в порядке, и я впал в панику! Вместо того чтобы сказать, что я не взял с собой ключ, я заявил, что крошшер неисправен.$b$bНадо поскорее выбираться отсюда! Поднимись в комнату управления на вышке, у бригадира Зубовиззла должен быть ключ от этого шреддера.$B$BВыручи меня!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ключ зажигания у бригадира Зубовиззла.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Скорее, надо выбираться отсюда, пока никто ничего не заподозрил!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите ключ от крошшера Зигзага на Нефтяное болото в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (859,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (860,'Сергра Черный Шип','Ежели хочешь вступить на путь охотника, то тогда тебе надо идти в Степи. Тамошние твари упрямы и яростны. Охотясь там, ты многому научишься, и дух твой окрепнет.$B$BПоговори с Сергрой Черный Шип. Она будет первой твоей наставницей в Степях.$B$BСергра сейчас в Перекрестке. Чтобы туда добраться, иди на восток от деревни Кровавого Копыта прямиком в Степи, затем на развилке сверни на север. И по дороге держи ухо востро – Степи весьма опасны для неопытных и беспечных.','Поговорите с Сергрой Черный Шип в Перекрестке.','Хочешь охотиться в Степях?\n\nГлаза у тебя горячие и молодые. Они еще не окосели от выслеживания добычи на тутошних пыльных равнинах.\n\nНо ты не бойся. Мы закалим твое тело и дух! И растолкуем, что охота – не просто выслеживание и добыча.\n\nГотовься. Твой путь начинается прямо сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сергра Черный Шип',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ежели хочешь вступить на путь охотника, то тогда тебе надо идти в Степи. Тамошние твари упрямы и яростны. Охотясь там, ты многому научишься, и дух твой окрепнет.$B$BПоговори с Сергрой Черный Шип. Она будет первой твоей наставницей в Степях.$B$BСергра сейчас в Перекрестке. Чтобы туда добраться, иди на восток от деревни Кровавого Копыта прямиком в Степи, затем на развилке сверни на север. И по дороге держи ухо востро – Степи весьма опасны для неопытных и беспечных.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сергрой Черный Шип в Перекрестке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хочешь охотиться в Степях?\n\nГлаза у тебя горячие и молодые. Они еще не окосели от выслеживания добычи на тутошних пыльных равнинах.\n\nНо ты не бойся. Мы закалим твое тело и дух! И растолкуем, что охота – не просто выслеживание и добыча.\n\nГотовься. Твой путь начинается прямо сейчас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (861,'Путь охотника','Вижу, ты любишь путешествовать. Когда-то и меня обуревала жажда странствий...$B$BСтранствий и охоты. Ведь охота – первая доблесть таурена.$B$BЕсли ты в самом деле желаешь избрать путь охотника, покажи мне свои умения и решительность. Принеси мне когти хищника плоскогорья. Эти звери сильны и хитры – подходящая добыча для $gмолодого:молодой:c; |3-1($c), $gизбравшего:избравшей; путь $gохотника:охотницы;.','Принесите 4 когтя хищника плоскогорья.','Вернитесь к Скорну Белому Облаку в Лагерь Солнечного Пастбища, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вижу, ты любишь путешествовать. Когда-то и меня обуревала жажда странствий...$B$BСтранствий и охоты. Ведь охота – первая доблесть таурена.$B$BЕсли ты в самом деле желаешь избрать путь охотника, покажи мне свои умения и решительность. Принеси мне когти хищника плоскогорья. Эти звери сильны и хитры – подходящая добыча для $gмолодого:молодой:c; |3-1($c), $gизбравшего:избравшей; путь $gохотника:охотницы;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 когтя хищника плоскогорья.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скорну Белому Облаку в Лагерь Солнечного Пастбища, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (862,'Похлебка из пещерной крысы','Должно быть, |3-2($c) вроде тебя в Степях голодно. Я вот постоянно хочу есть.$B$BЗнаешь, приготовлю-ка я тебе отличную похлебку. Для этого мне понадобится несколько пещерных крыс.$B$BПохоже, эти грязные дворфы в Бейл Модане увлечены празднованием. Так что ступай в Бейл Модан, это на юге, и принеси мне несколько пещерных крыс.$B$BТебе не стать закаленным бойцом, пока не набьешь руку на крысах! Ха-ха!','Принесите 8 пещерных крыс Грубу на востоке от Перекрестка.','Обычно я не ем этих грызунов, пока они такие... такие... свежие. Им надо полежать несколько недель, чтобы мяско стало с душком. Но ты, похоже, голоден.\n\nДай-ка я сварю тебе похлебку из пещерных крыс. Ну вот, готово.\n\nКушай на здоровье!','Ну что, достаточно пещерных крыс притащил?','Вернитесь к Грязнуле в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похлебка из пещерной крысы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, |3-2($c) вроде тебя в Степях голодно. Я вот постоянно хочу есть.$B$BЗнаешь, приготовлю-ка я тебе отличную похлебку. Для этого мне понадобится несколько пещерных крыс.$B$BПохоже, эти грязные дворфы в Бейл Модане увлечены празднованием. Так что ступай в Бейл Модан, это на юге, и принеси мне несколько пещерных крыс.$B$BТебе не стать закаленным бойцом, пока не набьешь руку на крысах! Ха-ха!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 пещерных крыс Грубу на востоке от Перекрестка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Обычно я не ем этих грызунов, пока они такие... такие... свежие. Им надо полежать несколько недель, чтобы мяско стало с душком. Но ты, похоже, голоден.\n\nДай-ка я сварю тебе похлебку из пещерных крыс. Ну вот, готово.\n\nКушай на здоровье!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, достаточно пещерных крыс притащил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грязнуле в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (863,'Бегство','Полагаю, я буду учиться по ходу дела... Вряд ли это так сложно. Тут пара кнопок, там рычаг-другой. Ну что, поехали?','Охраняйте Зигзага и похищенный гоблинский крошшер по пути из Нефтяного болота.','Мне очень надеюсь, что вам удастся добыть достаточно змеецвета в Пещерах Стенаний. Я многих туда посылала, но никто не вернулся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бегство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полагаю, я буду учиться по ходу дела... Вряд ли это так сложно. Тут пара кнопок, там рычаг-другой. Ну что, поехали?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Охраняйте Зигзага и похищенный гоблинский крошшер по пути из Нефтяного болота.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне очень надеюсь, что вам удастся добыть достаточно змеецвета в Пещерах Стенаний. Я многих туда посылала, но никто не вернулся.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (864,'Возвращение к аптекарю Зинг','Ну вот, источник энергии извлечен, и твои данные сохранились. Что ж, счастливого пути и все такое. Надеюсь, зловещий научный эксперимент удался.$B$B*Гоблин отворачивается от вас и погружается в дела Водной компании Прибамбасска. Вы кладете запечатанный набор для испытаний в надежное место и готовитесь отбыть в Подгород. Вас и запечатанный набор ждет аптекарь Зинг.*','Отнесите запечатанный набор для полевых испытаний аптекарю Зинг в Подгород.','Я немедленно займусь анализом данных. Быть может, безумие Чанна обернется моей гениальностью.$B$BЧто до тебя... Ты мне $Gполезен:полезна;, а я хорошо обращаюсь с полезными существами. Прими эту вещь, эти монетки, а в придачу к ним – мою благодарность.$B$BЗаглядывай время от времени – думаю, что мы еще поработаем вместе.','Добро пожаловать домой. Разумеется, в том случае, если ты несешь мне запечатанный набор для полевых испытаний. Если нет – я притворюсь, что не заметила твоей полной некомпетентности и не буду обрушивать на тебя свой гнев. Потому что ты пойдешь и сделаешь, что велено!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к аптекарю Зинг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, источник энергии извлечен, и твои данные сохранились. Что ж, счастливого пути и все такое. Надеюсь, зловещий научный эксперимент удался.$B$B*Гоблин отворачивается от вас и погружается в дела Водной компании Прибамбасска. Вы кладете запечатанный набор для испытаний в надежное место и готовитесь отбыть в Подгород. Вас и запечатанный набор ждет аптекарь Зинг.*',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанный набор для полевых испытаний аптекарю Зинг в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я немедленно займусь анализом данных. Быть может, безумие Чанна обернется моей гениальностью.$B$BЧто до тебя... Ты мне $Gполезен:полезна;, а я хорошо обращаюсь с полезными существами. Прими эту вещь, эти монетки, а в придачу к ним – мою благодарность.$B$BЗаглядывай время от времени – думаю, что мы еще поработаем вместе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать домой. Разумеется, в том случае, если ты несешь мне запечатанный набор для полевых испытаний. Если нет – я притворюсь, что не заметила твоей полной некомпетентности и не буду обрушивать на тебя свой гнев. Потому что ты пойдешь и сделаешь, что велено!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (865,'Всем рогам рог','Ящеры Степей умнее, чем прочие. Мне кажется, весь ум в рогах! Если так, эти рога можно стереть в порошок и сделать из них "умный напиток". Я мог бы продавать его за баснословные деньги!!!$B$BТы можешь мне помочь, если принесешь рог самого умного из них. Король Дерущий Коготь руководит целым выводком разумных ящеров, обитающих на утесах к северу от Кабестана. Принеси мне один из его рогов! И смотри, чтобы тебя не порвали на клочки, как и всех остальных, кого я отправлял туда!','Добудьте рог короля Дерущего Когтя.','Отнесите рог короля Дерущего Когтя Мебоку Миззриксу в Кабестан в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всем рогам рог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ящеры Степей умнее, чем прочие. Мне кажется, весь ум в рогах! Если так, эти рога можно стереть в порошок и сделать из них "умный напиток". Я мог бы продавать его за баснословные деньги!!!$B$BТы можешь мне помочь, если принесешь рог самого умного из них. Король Дерущий Коготь руководит целым выводком разумных ящеров, обитающих на утесах к северу от Кабестана. Принеси мне один из его рогов! И смотри, чтобы тебя не порвали на клочки, как и всех остальных, кого я отправлял туда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте рог короля Дерущего Когтя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите рог короля Дерущего Когтя Мебоку Миззриксу в Кабестан в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (866,'Образцы корней','Таких трав, как в Степях, нет нигде. Свойства у них по большей части те же, но вода оазисов оказывает на них особое влияние, и они все же отличаются от подобных им, хоть и не сильно.$B$BЯ хочу выяснить, в чем же состоит разница... и нельзя ли ей воспользоваться!$B$BЕсли ты владеешь искусством травничества, собери для меня образцы корней растений Степей, и я сравню их с травами из других регионов.','Соберите 8 образцов корней трав, растущих в Северных Степях.','Отнесите образцы Мебоку Миззриксу в Кабестан в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Образцы корней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Таких трав, как в Степях, нет нигде. Свойства у них по большей части те же, но вода оазисов оказывает на них особое влияние, и они все же отличаются от подобных им, хоть и не сильно.$B$BЯ хочу выяснить, в чем же состоит разница... и нельзя ли ей воспользоваться!$B$BЕсли ты владеешь искусством травничества, собери для меня образцы корней растений Степей, и я сравню их с травами из других регионов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 образцов корней трав, растущих в Северных Степях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите образцы Мебоку Миззриксу в Кабестан в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (867,'Гарпии-налетчицы','Раз уж ты здесь, |3-6($c), может быть, ты поможешь мне решить одну небольшую проблему. Нет больше сил терпеть нападения гарпий на наши караваны со съестными припасами. Пора сократить число проклятых гарпий, перерезав горло десятку-другому.$B$BНачать надо с низов, а потом постепенно разобраться с их командованием.$B$BДля начала займись гарпиями из стаи Зачарованного Крыла, поселившимися на северо-западе, и принеси мне 6 когтей Зачарованного Крыла. Будет уже неплохо...','Соберите 6 когтей гарпий из стаи Зачарованного Крыла.','Ну как, много ли гарпий удалось убить? Режь их, круши и бери трофеи. Мне нужно 8 когтей Зачарованного Крыла.','Отнесите когти Дарсоку Быстрому Ножу на его заставу в Северных Степях.','Сделай так, чтобы этих грязных созданий стало меньше.','Дарсок Быстрый Нож') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гарпии-налетчицы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж ты здесь, |3-6($c), может быть, ты поможешь мне решить одну небольшую проблему. Нет больше сил терпеть нападения гарпий на наши караваны со съестными припасами. Пора сократить число проклятых гарпий, перерезав горло десятку-другому.$B$BНачать надо с низов, а потом постепенно разобраться с их командованием.$B$BДля начала займись гарпиями из стаи Зачарованного Крыла, поселившимися на северо-западе, и принеси мне 6 когтей Зачарованного Крыла. Будет уже неплохо...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 когтей гарпий из стаи Зачарованного Крыла.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, много ли гарпий удалось убить? Режь их, круши и бери трофеи. Мне нужно 8 когтей Зачарованного Крыла.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите когти Дарсоку Быстрому Ножу на его заставу в Северных Степях.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Сделай так, чтобы этих грязных созданий стало меньше.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Дарсок Быстрый Нож',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (868,'Охота за яйцами','Эй, $n. Меня отправили в Перекресток присматривать за этими землями и сообщать начальству в Оргриммаре, что тут творится.$B$BВ частности, мне велено наблюдать за насекомовидными тварями на юге в Полях Великанов. Нам о них почти ничего не известно, а я хотел бы узнать о них побольше. Кажется, они умнее обычных животных.$B$BВозьми вспарывающий коготь и принеси несколько яиц этих тварей из их курганов, но будь осторожнее: они нападут на тебя, если заметят, что ты творишь.','Принесите 12 яиц силитидов и вспарывающий коготь Коррану в Перекресток.','Осторожно, яйца хрупкие. Разбитые мне не нужны.','Вернитесь к Коррану в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота за яйцами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $n. Меня отправили в Перекресток присматривать за этими землями и сообщать начальству в Оргриммаре, что тут творится.$B$BВ частности, мне велено наблюдать за насекомовидными тварями на юге в Полях Великанов. Нам о них почти ничего не известно, а я хотел бы узнать о них побольше. Кажется, они умнее обычных животных.$B$BВозьми вспарывающий коготь и принеси несколько яиц этих тварей из их курганов, но будь осторожнее: они нападут на тебя, если заметят, что ты творишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 яиц силитидов и вспарывающий коготь Коррану в Перекресток.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Осторожно, яйца хрупкие. Разбитые мне не нужны.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коррану в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (869,'Выследить вора','Вокруг обломков остались следы от огромных кривых когтей. По всей видимости, это следы ящера.$b$bВ первую минуту ты думаешь, что караван был атакован всадниками на ящерах, но уверенности в этом нет, да и следов, которые бы могли принадлежать другим существам, вокруг тоже не видно.$b$bСледы ведут на северо-восток к восточной стороне Тернистого холма. Может быть, именно там ты найдешь ответ на эту загадку?','Следы ведут к восточной стороне Тернистого холма. Идите по ним и вы все поймете.','Источник следов обнаружен','Следы ведут к восточной стороне Тернистого холма. Идите по ним и вы все поймете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выследить вора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вокруг обломков остались следы от огромных кривых когтей. По всей видимости, это следы ящера.$b$bВ первую минуту ты думаешь, что караван был атакован всадниками на ящерах, но уверенности в этом нет, да и следов, которые бы могли принадлежать другим существам, вокруг тоже не видно.$b$bСледы ведут на северо-восток к восточной стороне Тернистого холма. Может быть, именно там ты найдешь ответ на эту загадку?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Следы ведут к восточной стороне Тернистого холма. Идите по ним и вы все поймете.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Источник следов обнаружен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Следы ведут к восточной стороне Тернистого холма. Идите по ним и вы все поймете.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (870,'Забытые пруды','Ты чувствуешь, как дрожит земля, |3-6($c)? Неведомая сила разделила эти земли надвое. Но мы, друиды, чувствуем дрожь, вызванную совсем иными силами.$B$BВ прежде опустошенных и мертвых землях зарождается новая жизнь. Вокруг Перекрестка неожиданно возникли цветущие оазисы. Я чувствую, что из глубин к поверхности рвется какая-то сила. Но что питает ее?$B$BМы должны обнаружить источник этой силы. Отправляйся к Забытым прудам, к северо-западу от Перекрестка. Отыщи в их водах источник силы и возвращайся сюда.','Обследуйте дно Забытых прудов к северо-западу от Перекрестка.','И где же споры? Мне надо сварить определенное зелье для коллеги из Громового Утеса, для этого и требуются споры...','Исследуйте воды Забытых прудов.','Сообщите о своих находках Тонге Руническому Тотему. Его можно найти в Перекрестке, в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Забытые пруды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты чувствуешь, как дрожит земля, |3-6($c)? Неведомая сила разделила эти земли надвое. Но мы, друиды, чувствуем дрожь, вызванную совсем иными силами.$B$BВ прежде опустошенных и мертвых землях зарождается новая жизнь. Вокруг Перекрестка неожиданно возникли цветущие оазисы. Я чувствую, что из глубин к поверхности рвется какая-то сила. Но что питает ее?$B$BМы должны обнаружить источник этой силы. Отправляйся к Забытым прудам, к северо-западу от Перекрестка. Отыщи в их водах источник силы и возвращайся сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обследуйте дно Забытых прудов к северо-западу от Перекрестка.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И где же споры? Мне надо сварить определенное зелье для коллеги из Громового Утеса, для этого и требуются споры...',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Исследуйте воды Забытых прудов.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите о своих находках Тонге Руническому Тотему. Его можно найти в Перекрестке, в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (871,'Защита Дальней заставы','Все свинобразы – наши враги, $n. Просто одни из них причиняют нам больше неприятностей, чем другие.$B$BКлан Иглогривых в последнее время нередко нападает на наши караваны из Оргриммара, и терпеть это нет больше сил. Мои разведчики ищут главарей, но тем временем чем больший урон мы нанесем этим свиньям, тем лучше.$B$BСтупай на юг, где свинобразы нападают на наши лагеря возле реки. Отыщи их и убей скольких сможешь.','Убейте 8 водоискателей и 3 охотника племени Иглогривых.','Ты уже принес 6 колец лейтенантов гарпий? Пора свершить над ними суд и положить конец их нападениям на Орду.','Вернитесь к Каргалу на Дальнюю заставу в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Дальней заставы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все свинобразы – наши враги, $n. Просто одни из них причиняют нам больше неприятностей, чем другие.$B$BКлан Иглогривых в последнее время нередко нападает на наши караваны из Оргриммара, и терпеть это нет больше сил. Мои разведчики ищут главарей, но тем временем чем больший урон мы нанесем этим свиньям, тем лучше.$B$BСтупай на юг, где свинобразы нападают на наши лагеря возле реки. Отыщи их и убей скольких сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 водоискателей и 3 охотника племени Иглогривых.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже принес 6 колец лейтенантов гарпий? Пора свершить над ними суд и положить конец их нападениям на Орду.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каргалу на Дальнюю заставу в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (872,'Конец бесчинствам','Свиньи бесчинствуют на границе с Дуротаром? Не бывать этому! Знаешь, как говорят, $n: "Лучшая защита – это нападение."$B$BОдин из разведчиков проследил за свинобразами после нападения на последний отправленный караван, так что мы знаем, куда следует нанести удар. За нападения вдоль берега реки отвечает Криниг Грознорыл. Раздави его, |3-6($c). Убей Грознорыла и его приспешников. Пока Криниг жив, покоя не будет.$B$BИщи пещеру, это к югу от наших стойл.','Убейте 5 защитников и 5 терноплетов из племени Иглогривых, одолейте Кринига Грознорыла и возьмите его клык.','Принесите клык Кринига Грознорыла Каргалу Боевому Шраму на Дальнюю заставу в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец бесчинствам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Свиньи бесчинствуют на границе с Дуротаром? Не бывать этому! Знаешь, как говорят, $n: "Лучшая защита – это нападение."$B$BОдин из разведчиков проследил за свинобразами после нападения на последний отправленный караван, так что мы знаем, куда следует нанести удар. За нападения вдоль берега реки отвечает Криниг Грознорыл. Раздави его, |3-6($c). Убей Грознорыла и его приспешников. Пока Криниг жив, покоя не будет.$B$BИщи пещеру, это к югу от наших стойл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 защитников и 5 терноплетов из племени Иглогривых, одолейте Кринига Грознорыла и возьмите его клык.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите клык Кринига Грознорыла Каргалу Боевому Шраму на Дальнюю заставу в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (873,'Иша Авак','Великий Иша Авак – повелитель этих вод. Велика его сила, несокрушима гордость. Народ побережья страшится его, ибо он поглотил многих из их числа.$B$BНо я не боюсь его. Я благодарна провидению за то, что он есть. Бросить ему вызов – высокая честь, ибо он достойный противник.$B$BЕсли ты $gготов:готова;, плыви на поиски Иши Авака, Рока Глубин.$B$BЕго дух содержится в сердце, и услышав, как оно бьется, можно узнать многое о своей судьбе.','Принесите сердце Иши Авака Марен Небесной Провидице.','Не бойся вод, |3-6($R).','Вернитесь к Марен Небесной Провидице к Лестнице Прилива, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Иша Авак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Великий Иша Авак – повелитель этих вод. Велика его сила, несокрушима гордость. Народ побережья страшится его, ибо он поглотил многих из их числа.$B$BНо я не боюсь его. Я благодарна провидению за то, что он есть. Бросить ему вызов – высокая честь, ибо он достойный противник.$B$BЕсли ты $gготов:готова;, плыви на поиски Иши Авака, Рока Глубин.$B$BЕго дух содержится в сердце, и услышав, как оно бьется, можно узнать многое о своей судьбе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сердце Иши Авака Марен Небесной Провидице.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не бойся вод, |3-6($R).',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марен Небесной Провидице к Лестнице Прилива, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (874,'Марен Небесная Провидица','Ты $gпоохотился:поохотилась; на многих зверей Степей. Дух твой тверд. Но охотник должен быть готов ко всему, его не смутит никакой путь. Горы и болота не испугают его.$B$BИ даже море.$B$BНайди мою сестру, Марен. Она охотится на огромных водных тварей на побережье и многому научит тебя.$B$BИщи ее с осторожностью, потому что побережье Степей захвачено людьми.','Поговорите с Марен Небесной Провидицей.','Тебя прислал мой брат? Должно быть, ты произвел на него впечатление. А если тебя зауважал Джорн, то и я буду уважать.\n\nЖелаешь ли ты сделать следующий шаг на пути охотника?','Когда я вижу суккуба, мое сердце поет... Но в то же время я буквально чувствую, как моя душа иссыхает, утекает, как песок между пальцев.\n\nБудь осторожнее!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Марен Небесная Провидица',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпоохотился:поохотилась; на многих зверей Степей. Дух твой тверд. Но охотник должен быть готов ко всему, его не смутит никакой путь. Горы и болота не испугают его.$B$BИ даже море.$B$BНайди мою сестру, Марен. Она охотится на огромных водных тварей на побережье и многому научит тебя.$B$BИщи ее с осторожностью, потому что побережье Степей захвачено людьми.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Марен Небесной Провидицей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал мой брат? Должно быть, ты произвел на него впечатление. А если тебя зауважал Джорн, то и я буду уважать.\n\nЖелаешь ли ты сделать следующий шаг на пути охотника?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда я вижу суккуба, мое сердце поет... Но в то же время я буквально чувствую, как моя душа иссыхает, утекает, как песок между пальцев.\n\nБудь осторожнее!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (875,'Лейтенанты гарпий','Единственный способ остановить гарпий-налетчиц – уничтожить тех, кто ими командует. Гарпии подчиняются душегубкам из стаи Зачарованного Крыла. Если убить душегубок, то и с остальными справиться не составит труда.$b$bОтправляйся на Сухие холмы и убей душегубок. И пусть подыхают долго и мучительно, $n. Это научит их не связываться с Ордой.','Прекрасная работа, дружище. Думаю, ты достигнешь высокого положения в Орде.','Ты уже принес 6 колец лейтенантов гарпий? Пора свершить над ними суд и положить конец их нападениям на Орду.','Вернитесь к Дарсоку Быстрому Ножу на его заставу в Северных Степях.','Покажи этим грязным созданиям, что с Ордой шутки плохи.','Душегубка из стаи Зачарованного Крыла','Орда гордится такими, как ты.','Дарсок Быстрый Нож') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лейтенанты гарпий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Единственный способ остановить гарпий-налетчиц – уничтожить тех, кто ими командует. Гарпии подчиняются душегубкам из стаи Зачарованного Крыла. Если убить душегубок, то и с остальными справиться не составит труда.$b$bОтправляйся на Сухие холмы и убей душегубок. И пусть подыхают долго и мучительно, $n. Это научит их не связываться с Ордой.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасная работа, дружище. Думаю, ты достигнешь высокого положения в Орде.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже принес 6 колец лейтенантов гарпий? Пора свершить над ними суд и положить конец их нападениям на Орду.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дарсоку Быстрому Ножу на его заставу в Северных Степях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Покажи этим грязным созданиям, что с Ордой шутки плохи.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Душегубка из стаи Зачарованного Крыла',`questgivertargetname_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Орда гордится такими, как ты.',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Дарсок Быстрый Нож',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (876,'Серена Кровавое Перо','Гарпии, которых ты $gубил:убила;, упоминали о своем матриархе, Серене Кровавое Перо. Судя по тому, какую ненависть они испытывали к Орде, дело в какой-то давней вражде. Выследи Серену Кровавое Перо и покончи с ней раз и навсегда.','Убейте Серену Кровавое Перо и отрубите ей голову.','Ты ничего не получишь, пока я не увижу голову Серены.','Вернитесь к Дарсоку Быстрому Ножу в Северные Степи.','Убей ее. И не забудь ее голову.','Серена Кровавое Перо') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серена Кровавое Перо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гарпии, которых ты $gубил:убила;, упоминали о своем матриархе, Серене Кровавое Перо. Судя по тому, какую ненависть они испытывали к Орде, дело в какой-то давней вражде. Выследи Серену Кровавое Перо и покончи с ней раз и навсегда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Серену Кровавое Перо и отрубите ей голову.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты ничего не получишь, пока я не увижу голову Серены.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дарсоку Быстрому Ножу в Северные Степи.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убей ее. И не забудь ее голову.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Серена Кровавое Перо',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (877,'Застывший оазис','Быть может, и в других оазисах Степей есть расселины вроде той, что тебе удалось обнаружить в Забытых прудах? Коли так, скорее всего именно эти расселины – источник жизни оазисов.$B$BНадо проверить.$B$BВот, возьми эти семена. Сейчас они мертвые и бесплодные. Отнеси их в Застывший оазис на юго-востоке. Если там есть расселина, помести в нее семена... и понаблюдай. О результатах нужно будет доложить Тонге в Перекресток.','Проведите эксперимент с семенами в Застывшем оазисе.','Осторожно, яйца хрупкие. Разбитые мне не нужны.','Сообщите о своих находках Тонге Руническому Тотему. Его можно найти в Перекрестке, в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Застывший оазис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быть может, и в других оазисах Степей есть расселины вроде той, что тебе удалось обнаружить в Забытых прудах? Коли так, скорее всего именно эти расселины – источник жизни оазисов.$B$BНадо проверить.$B$BВот, возьми эти семена. Сейчас они мертвые и бесплодные. Отнеси их в Застывший оазис на юго-востоке. Если там есть расселина, помести в нее семена... и понаблюдай. О результатах нужно будет доложить Тонге в Перекресток.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проведите эксперимент с семенами в Застывшем оазисе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Осторожно, яйца хрупкие. Разбитые мне не нужны.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Сообщите о своих находках Тонге Руническому Тотему. Его можно найти в Перекрестке, в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (878,'Воюющие племена','Отомсти моим врагам. *фыркает* Помоги Кривозубу и Иглогривым, ослабив племя Дыбогривов. Оба племени духовно связаны с землей и ее мощью. *фыркает* Она дарует нам силу, необходимую для всего... и прежде всего – для войны.$B$BЕсли ты в самом деле хочешь узнать, кто причинил Тхорку и Орде так много страданий, помоги Кривозубу! Напади на духовных вождей Дыбогривов на севере; подорви их мощь, чтобы Иглогривые одолели своих соперников и покорили Степи.','Убейте 6 водоискателей, 12 терноплетов и 12 геомантов из племени Дыбогривов и возвращайтесь к Кривозубу в Лагерь Таурахо в Степях.','Да-да... Меня должна переполнять радость, фыркает ведь племя Дыбогривов испытало ту же боль, что и мой народ, |3-6($R). Но нет, радости нет места. фыркает\n\nТы помогаешь своим, и они чтят тебя. Кривозуб помогает своим – и что же? Они отвернулись от него. Его забыли, оставили гнить в клетке!\n\nЯ помогал им даже из-за решетки, но никто не пришел мне на помощь!','Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.','Вернитесь к Кривозубу в Лагерь Таурахо, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воюющие племена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отомсти моим врагам. *фыркает* Помоги Кривозубу и Иглогривым, ослабив племя Дыбогривов. Оба племени духовно связаны с землей и ее мощью. *фыркает* Она дарует нам силу, необходимую для всего... и прежде всего – для войны.$B$BЕсли ты в самом деле хочешь узнать, кто причинил Тхорку и Орде так много страданий, помоги Кривозубу! Напади на духовных вождей Дыбогривов на севере; подорви их мощь, чтобы Иглогривые одолели своих соперников и покорили Степи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 водоискателей, 12 терноплетов и 12 геомантов из племени Дыбогривов и возвращайтесь к Кривозубу в Лагерь Таурахо в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да... Меня должна переполнять радость, фыркает ведь племя Дыбогривов испытало ту же боль, что и мой народ, |3-6($R). Но нет, радости нет места. фыркает\n\nТы помогаешь своим, и они чтят тебя. Кривозуб помогает своим – и что же? Они отвернулись от него. Его забыли, оставили гнить в клетке!\n\nЯ помогал им даже из-за решетки, но никто не пришел мне на помощь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривозубу в Лагерь Таурахо, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (879,'Предатель в наших рядах','Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, |3-6($r). *фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрестке и в большей части Степей воцарится мир... *фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает*$B$BИмена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей. Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин. Убей их, |3-6($r), как они убили меня.','Убейте Нака, Куза и Лока Оркобоя и принесите их черепа Кривозубу в Лагерь Таурахо в Степях.','Дело сделано. Кривозуб считает, уж лучше так. фыркает Надо было убедиться фыркает, что я мертв, а не бросать меня здесь, во всеми забытой клетке.\n\nТебе осталось лишь одно дело, |3-6($R).','И как идет охота, |3-6($R)? фыркает Торк полагает, что знает, кто возглавляет набеги на его народ, фыркает но он поймет, как ошибался.\n\nМоя смерть неотвратима, но тебе удалось нанести серьезный урон моим врагам, и Кривозуб ни о чем не жалеет. фыркает','Вернитесь к Кривозубу в Лагерь Таурахо, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предатель в наших рядах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, |3-6($r). *фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрестке и в большей части Степей воцарится мир... *фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает*$B$BИмена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей. Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин. Убей их, |3-6($r), как они убили меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Нака, Куза и Лока Оркобоя и принесите их черепа Кривозубу в Лагерь Таурахо в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дело сделано. Кривозуб считает, уж лучше так. фыркает Надо было убедиться фыркает, что я мертв, а не бросать меня здесь, во всеми забытой клетке.\n\nТебе осталось лишь одно дело, |3-6($R).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И как идет охота, |3-6($R)? фыркает Торк полагает, что знает, кто возглавляет набеги на его народ, фыркает но он поймет, как ошибался.\n\nМоя смерть неотвратима, но тебе удалось нанести серьезный урон моим врагам, и Кривозуб ни о чем не жалеет. фыркает',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривозубу в Лагерь Таурахо, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (880,'Измененные существа','Важно знать, какое влияние оказывает обнаруженная тобой необычная энергия на животных и растения. В Застывшем оазисе обитает несколько видов хрустогрызов. Недавно их популяция увеличилась до невероятных размеров. Более того, эти ранее безобидные животные стали довольно агрессивными. Я испытал это на собственной шкуре, пока добирался сюда.$B$B<Джеррек потирает забинтованный палец.>$B$BЯ подозреваю, что эти изменения вызваны влиянием оазиса. Добудь несколько панцирей хрустогрызов из тех мест и отнеси их Тонге в Перекресток для исследований.','Принесите 6 измененных панцирей хрустогрызов, обитающих в Застывшем оазисе.','Как идет сбор панцирей? Много набрал?','Отнесите панцири Тонге Руническому Тотему в Перекресток в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Измененные существа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Важно знать, какое влияние оказывает обнаруженная тобой необычная энергия на животных и растения. В Застывшем оазисе обитает несколько видов хрустогрызов. Недавно их популяция увеличилась до невероятных размеров. Более того, эти ранее безобидные животные стали довольно агрессивными. Я испытал это на собственной шкуре, пока добирался сюда.$B$B<Джеррек потирает забинтованный палец.>$B$BЯ подозреваю, что эти изменения вызваны влиянием оазиса. Добудь несколько панцирей хрустогрызов из тех мест и отнеси их Тонге в Перекресток для исследований.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 измененных панцирей хрустогрызов, обитающих в Застывшем оазисе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идет сбор панцирей? Много набрал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите панцири Тонге Руническому Тотему в Перекресток в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (881,'Ичияки','Ичияки, Белый Туман на языке тауренов, король кошачьих обитателей саванны. Он подкрадывается к жертвам так незаметно, что его уподобили тонкому белому туману, который стелется над землей. Убивает он одним ударом – жертва не успевает ни испугаться, ни ощутить боли.$B$BТаурены говорят, что он воплощает собой одновременно милосердие и смерть.$B$BТы узнаешь это на своем опыте, потому что я отправляю тебя охотиться на Ичияки. Его логово располагается к северо-западу от Перекрестка, на северном склоне небольшой горы среди костей огромного кодо.$B$BСтупай. Добравшись до логова, протруби в этот рог. Протруби в рог, и он явится на зов.','Подуйте в рог возле логова Ичияки, убейте его или подчините.','Вернитесь к Сергре Черный Шип в Перекресток в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ичияки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ичияки, Белый Туман на языке тауренов, король кошачьих обитателей саванны. Он подкрадывается к жертвам так незаметно, что его уподобили тонкому белому туману, который стелется над землей. Убивает он одним ударом – жертва не успевает ни испугаться, ни ощутить боли.$B$BТаурены говорят, что он воплощает собой одновременно милосердие и смерть.$B$BТы узнаешь это на своем опыте, потому что я отправляю тебя охотиться на Ичияки. Его логово располагается к северо-западу от Перекрестка, на северном склоне небольшой горы среди костей огромного кодо.$B$BСтупай. Добравшись до логова, протруби в этот рог. Протруби в рог, и он явится на зов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подуйте в рог возле логова Ичияки, убейте его или подчините.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сергре Черный Шип в Перекресток в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (882,'Ишамухал','Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей. Он охотится не ради еды и не для удовольствия. Охота – его страсть. Он убивает потому, что сам убийца по природе.$B$BИменно о его природе тебе и предстоит узнать многое, $n, ибо твой путь теперь поведет тебя по когтистым следам Ишамухала.$B$BНачинай охоту. Убей его излюбленную добычу – жевру – и принеси его тушу к мертвому дереву на северо-западе от Кабестана. Ишамухал почует тушу и явится на ее запах.$B$BБудь $gготов:готова; к его появлению.','Принесите клык Ишамухала Джорну Искателю Неба в Лагерь Таурахо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ишамухал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей. Он охотится не ради еды и не для удовольствия. Охота – его страсть. Он убивает потому, что сам убийца по природе.$B$BИменно о его природе тебе и предстоит узнать многое, $n, ибо твой путь теперь поведет тебя по когтистым следам Ишамухала.$B$BНачинай охоту. Убей его излюбленную добычу – жевру – и принеси его тушу к мертвому дереву на северо-западе от Кабестана. Ишамухал почует тушу и явится на ее запах.$B$BБудь $gготов:готова; к его появлению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите клык Ишамухала Джорну Искателю Неба в Лагерь Таурахо.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (883,'Лакота\'мани','Копыто Лакота\'мани – символ силы великого кодо.','Принесите копыто Лакота\'мани Джорну в Лагерь Таурахо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лакота\'мани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Копыто Лакота\'мани – символ силы великого кодо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите копыто Лакота\'мани Джорну в Лагерь Таурахо.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (884,'Оватанка','При касании от хвоста Оватанки летят искры.','Принесите хвостовой зубец Оватанки Джорну Искателю Неба в Лагерь Таурахо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оватанка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При касании от хвоста Оватанки летят искры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите хвостовой зубец Оватанки Джорну Искателю Неба в Лагерь Таурахо.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (885,'Ваште Пауни','Пера Ваште Пауни больно касаться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ваште Пауни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пера Ваште Пауни больно касаться.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (886,'Оазисы Степей','Друиды Громового Утеса ощущают странную силу, просачивающуюся в Степи к, востоку от Мулгора.$B$BМы отправили найти источник этой силы Тонгу Рунического Тотема, но, похоже, ему нужна помощь.$B$BОтправляйся в Степи и поговори с Тонгой. Он будет в Перекрестке. Иди туда по дороге на восток от деревни Кровавого Копыта. Как попадешь в Степи, сверни на развилке на север. И продолжай идти, пока не упрешься в Перекресток.$B$BС дороги не сходи, $n, ибо Степи – край суровый.','Поговорите на Перекрестке с Тонгой Руническим Тотемом.','Мои собратья в Громовом Утесе мудро поступили, прислав тебя сюда, юный $C. Ибо тайну Степей мне в одиночку не раскрыть.$B$BБудем надеяться, что с твоей помощью мы найдем ответ на наш вопрос.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оазисы Степей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друиды Громового Утеса ощущают странную силу, просачивающуюся в Степи к, востоку от Мулгора.$B$BМы отправили найти источник этой силы Тонгу Рунического Тотема, но, похоже, ему нужна помощь.$B$BОтправляйся в Степи и поговори с Тонгой. Он будет в Перекрестке. Иди туда по дороге на восток от деревни Кровавого Копыта. Как попадешь в Степи, сверни на развилке на север. И продолжай идти, пока не упрешься в Перекресток.$B$BС дороги не сходи, $n, ибо Степи – край суровый.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите на Перекрестке с Тонгой Руническим Тотемом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои собратья в Громовом Утесе мудро поступили, прислав тебя сюда, юный $C. Ибо тайну Степей мне в одиночку не раскрыть.$B$BБудем надеяться, что с твоей помощью мы найдем ответ на наш вопрос.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (887,'Газлоу обещал повысить меня по службе, если я помогу ему разобраться с кабестанскими пиратами. Дело в шайке буканьеров, которая объявилась недавно и заняла Остров Битв, что к югу отсюда. Они ведь не просто пограбить приехали – а отомстить за старые обиды! На днях они напали на один из наших военных галеонов.$b$bЯ пока еще работаю над планом по разрешению ситуации, но Газлоу нужны результаты прямо сейчас. Отправляйся на Остров Битв и снеси пару-тройку голов, $gбудь добр:будь добра;.','Что происходит? Чем могу служить? Отправить груз, или, может быть, инженер понадобился?','Вернитесь к управляющему пристанью Головокружилкинсу в Кабестан.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Газлоу обещал повысить меня по службе, если я помогу ему разобраться с кабестанскими пиратами. Дело в шайке буканьеров, которая объявилась недавно и заняла Остров Битв, что к югу отсюда. Они ведь не просто пограбить приехали – а отомстить за старые обиды! На днях они напали на один из наших военных галеонов.$b$bЯ пока еще работаю над планом по разрешению ситуации, но Газлоу нужны результаты прямо сейчас. Отправляйся на Остров Битв и снеси пару-тройку голов, $gбудь добр:будь добра;.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что происходит? Чем могу служить? Отправить груз, или, может быть, инженер понадобился?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к управляющему пристанью Головокружилкинсу в Кабестан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (888,'[DEPRECATED]Украденное добро','Хоть я и хотел бы вернуть все товары, думаю, это невозможно. Но некоторые из них мне очень нужны!$B$BКак видишь, моя обсерватория почти готова, но ей не хватает двух малых линз. Первая из них прибыла с караваном из Дуротара, но вторую везли на корабле, который ограбили пираты. Кроме того, до меня так и не дошла партия сапог от Дриззлика из Пиратской Бухты!$B$BСтупай в пиратский лагерь и поищи их.','Верните Газлоу из Кабестана посылку с сапогами и линзу от телескопа.','Ну что, удалось найти мои вещи?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Украденное добро',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хоть я и хотел бы вернуть все товары, думаю, это невозможно. Но некоторые из них мне очень нужны!$B$BКак видишь, моя обсерватория почти готова, но ей не хватает двух малых линз. Первая из них прибыла с караваном из Дуротара, но вторую везли на корабле, который ограбили пираты. Кроме того, до меня так и не дошла партия сапог от Дриззлика из Пиратской Бухты!$B$BСтупай в пиратский лагерь и поищи их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Газлоу из Кабестана посылку с сапогами и линзу от телескопа.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось найти мои вещи?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (889,'Дух Ветра','Хорошо. Да ведет тебя дух Агамаггана, $R. Возвращайся, если захочешь вновь соприкоснуться с магией Агамаггана.','Принеси Кривозубу 10 кровавых осколков, и он одарит тебя большой скоростью. Ты сможешь перегнать жевр, и даже ветер тебе позавидует.$B$BПодействует это недолго, но облегчит странствия по Степям.','Вернитесь к Кривозубу в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух Ветра',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Да ведет тебя дух Агамаггана, $R. Возвращайся, если захочешь вновь соприкоснуться с магией Агамаггана.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принеси Кривозубу 10 кровавых осколков, и он одарит тебя большой скоростью. Ты сможешь перегнать жевр, и даже ветер тебе позавидует.$B$BПодействует это недолго, но облегчит странствия по Степям.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривозубу в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (890,'[DEPRECATED]Пропавший груз','Я уже сто лет жду последнего заказа из Пиратской Бухты! Наверняка его перехватили флибустьеры, но на всякий случай сходи в порт и спроси у Головокружилкинса, вдруг товары без моего ведома отнесли на склад?$B$BВот, отнеси мою учетную книжку Головокружилкинсу, пусть сверит со своими записями.','Отнесите учетную книжку Газлоу управляющему пристанью Головокружилкинсу.','А, так тебя прислал Газлоу? Минутку, дай-ка я загляну в свои записи, надо убедиться, что я не отправил товар Газлоу куда-то не туда.\n\nНебось, он ждет поставку сапог от Дриззлика...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Пропавший груз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже сто лет жду последнего заказа из Пиратской Бухты! Наверняка его перехватили флибустьеры, но на всякий случай сходи в порт и спроси у Головокружилкинса, вдруг товары без моего ведома отнесли на склад?$B$BВот, отнеси мою учетную книжку Головокружилкинсу, пусть сверит со своими записями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите учетную книжку Газлоу управляющему пристанью Головокружилкинсу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, так тебя прислал Газлоу? Минутку, дай-ка я загляну в свои записи, надо убедиться, что я не отправил товар Газлоу куда-то не туда.\n\nНебось, он ждет поставку сапог от Дриззлика...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (891,'Месть капитана','Вот и еще один мой корабль захватили рьяные людишки из Терамора!$B$BИх новый контр-адмирал обосновался здесь, у побережья. Он берет на абордаж или топит любой корабль, командир которого не согласен плясать под его дудку.$B$BОтправляйся на юг вдоль Торгового побережья и разыщи лагерь нового контр-адмирала. Принеси мне медали стражей бухты и матросов, а также уничтожь его лучших лейтенантов: Пира и Бакланда. Покажи им, что нападать на мой флот было большой ошибкой!','Соберите 10 тераморских медалей матросов и стражей бухты, а также убейте лейтенантов Пира и Бакланда.','Вернитесь к капитану Тало\'тасу Сияющему в Кабестан в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть капитана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот и еще один мой корабль захватили рьяные людишки из Терамора!$B$BИх новый контр-адмирал обосновался здесь, у побережья. Он берет на абордаж или топит любой корабль, командир которого не согласен плясать под его дудку.$B$BОтправляйся на юг вдоль Торгового побережья и разыщи лагерь нового контр-адмирала. Принеси мне медали стражей бухты и матросов, а также уничтожь его лучших лейтенантов: Пира и Бакланда. Покажи им, что нападать на мой флот было большой ошибкой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 тераморских медалей матросов и стражей бухты, а также убейте лейтенантов Пира и Бакланда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Тало\'тасу Сияющему в Кабестан в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (892,'[DEPRECATED]Пропавший груз','У меня в записях все в порядке, $n. Ступай к Газлоу и скажи, что ему не повезло. Не удивлюсь, если его товары прибрали к рукам пираты. $b$bЯ ничем не могу ему помочь. А, да... Скажи, что у меня есть для него кое-что из Нижней шахты, пусть приходит и забирает.','Верните Газлоу из Кабестана его регистр.','Вот непруха... Наверняка это корсары... Дыбоволос тут ни при чем, я уверен, он не стал бы так меня обманывать. В конце концов, он получает деньги за доставку.\n\nПохоже, мне придется вернуть себе кое-какие товары. Что скажешь?','Ну и что сказал Дыбоволос?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Пропавший груз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня в записях все в порядке, $n. Ступай к Газлоу и скажи, что ему не повезло. Не удивлюсь, если его товары прибрали к рукам пираты. $b$bЯ ничем не могу ему помочь. А, да... Скажи, что у меня есть для него кое-что из Нижней шахты, пусть приходит и забирает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Газлоу из Кабестана его регистр.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот непруха... Наверняка это корсары... Дыбоволос тут ни при чем, я уверен, он не стал бы так меня обманывать. В конце концов, он получает деньги за доставку.\n\nПохоже, мне придется вернуть себе кое-какие товары. Что скажешь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну и что сказал Дыбоволос?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (893,'Предпочитаемое оружие','Хотя говорят, что у свинобразов племени Иглогривых за Полями Великанов нет искусных кузнецов, они научились делать серьезное оружие. Мне хотелось бы получить несколько образцов, чтобы изучить их технику работы.$B$BЕсли ты стремишься к подвигам во славу Орды, добудь для меня их оружие. Мне понадобятся кинжал, жезл и щит. Этого вполне хватит!','Принесите стилет Иглогривых, обгоревший жезл Иглогривых и боевой щит Иглогривых Таттернаку Стальному Горну в Лагерь Таурахо в Степях.','Прекрасные, прекрасные образцы.\n\nСвинобразы куда более умелый народ, чем мне казалось.\n\nВот, возьми это и убирайся. Мне надо получше изучить это оружие. Похоже, мы недооценивали врага, а такие ошибки недопустимы.','У меня тоже есть сомнения насчет того, что жалкие иглогривые могли научиться кузнечному делу, но я выполняю приказы вождя, и потому стараюсь узнать побольше о племени Иглогривых.\n\nУ меня бывали задания и попротивней, но я с радостью выполняю их, чтобы служить народу орков.','Вернитесь к Таттернаку Стальному Горну в лагерь Таурахо, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предпочитаемое оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя говорят, что у свинобразов племени Иглогривых за Полями Великанов нет искусных кузнецов, они научились делать серьезное оружие. Мне хотелось бы получить несколько образцов, чтобы изучить их технику работы.$B$BЕсли ты стремишься к подвигам во славу Орды, добудь для меня их оружие. Мне понадобятся кинжал, жезл и щит. Этого вполне хватит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите стилет Иглогривых, обгоревший жезл Иглогривых и боевой щит Иглогривых Таттернаку Стальному Горну в Лагерь Таурахо в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасные, прекрасные образцы.\n\nСвинобразы куда более умелый народ, чем мне казалось.\n\nВот, возьми это и убирайся. Мне надо получше изучить это оружие. Похоже, мы недооценивали врага, а такие ошибки недопустимы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня тоже есть сомнения насчет того, что жалкие иглогривые могли научиться кузнечному делу, но я выполняю приказы вождя, и потому стараюсь узнать побольше о племени Иглогривых.\n\nУ меня бывали задания и попротивней, но я с радостью выполняю их, чтобы служить народу орков.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таттернаку Стальному Горну в лагерь Таурахо, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (894,'Самофланж','Торговая Компания устроила небольшой исследовательский центр к западу отсюда, сразу за Нефтяным болотом. Я не очень хорошо представляю, чем они занимаются, но до меня дошли сведения, что они проводят эксперименты со штукой под названием "самофланж".$B$BЧто еще за самофланж? Как бы то ни было, я хочу исследовать его, а значит, мне надо его заполучить.$B$BМне удалось достать копию их руководства по эксплуатации. Почитай его, там наверняка написано, как вытащить самофланж из терминала.','Получите доступ к терминалу в исследовательском центре Торговой Компании.','На панели управления в беспорядке разбросаны кнопки, рычаги и мигающие лампочки. Судя по маленькому индикатору, устройство работает в оптимальном режиме, а контрольные клапаны 1-3 открыты. В нижнем правом углу панели управления имеется небольшая замочная скважина.','Получите доступ к терминалу в исследовательском центре Торговой Компании в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самофланж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Торговая Компания устроила небольшой исследовательский центр к западу отсюда, сразу за Нефтяным болотом. Я не очень хорошо представляю, чем они занимаются, но до меня дошли сведения, что они проводят эксперименты со штукой под названием "самофланж".$B$BЧто еще за самофланж? Как бы то ни было, я хочу исследовать его, а значит, мне надо его заполучить.$B$BМне удалось достать копию их руководства по эксплуатации. Почитай его, там наверняка написано, как вытащить самофланж из терминала.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите доступ к терминалу в исследовательском центре Торговой Компании.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На панели управления в беспорядке разбросаны кнопки, рычаги и мигающие лампочки. Судя по маленькому индикатору, устройство работает в оптимальном режиме, а контрольные клапаны 1-3 открыты. В нижнем правом углу панели управления имеется небольшая замочная скважина.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Получите доступ к терминалу в исследовательском центре Торговой Компании в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (895,'РАЗЫСКИВАЕТСЯ: Капитан Шпрота','Что происходит? Чем могу служить? Отправить груз, или, может быть, инженер понадобился?','Принесите голову Шпроты Газлоу в Кабестан в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РАЗЫСКИВАЕТСЯ: Капитан Шпрота',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что происходит? Чем могу служить? Отправить груз, или, может быть, инженер понадобился?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите голову Шпроты Газлоу в Кабестан в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (896,'Если бы мы знали, кто именно нашел этот изумруд, дело выеденного яйца не стоило бы...','Отнесите изумруд Браку Трубореву в Лагерь Котельника в Северных Степях.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если бы мы знали, кто именно нашел этот изумруд, дело выеденного яйца не стоило бы...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите изумруд Браку Трубореву в Лагерь Котельника в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (897,'Жнец','Это странное, похожее на насекомое существо выглядит так, будто попало в Степи случайно.','Принесите голову Жнеца Джорну Заклинателю Небес.','Я ничего не могу сказать о природе этого существа, так как его дух ушел. Как ты уже $Gдогадался:догадалась;, оно не из Степей. Я боюсь, что это может предвещать мрачное будущее нашему народу...$B$BНо сейчас приготовься, давай надеяться, что время раскроет тайну этого существа.','Ты $Gказался:казалась; $Gвстревоженным:встревоженной;, $N. Как проходят твои уроки в Степях? Вы нашли что-то, что вас беспокоит?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жнец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это странное, похожее на насекомое существо выглядит так, будто попало в Степи случайно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Жнеца Джорну Заклинателю Небес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я ничего не могу сказать о природе этого существа, так как его дух ушел. Как ты уже $Gдогадался:догадалась;, оно не из Степей. Я боюсь, что это может предвещать мрачное будущее нашему народу...$B$BНо сейчас приготовься, давай надеяться, что время раскроет тайну этого существа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gказался:казалась; $Gвстревоженным:встревоженной;, $N. Как проходят твои уроки в Степях? Вы нашли что-то, что вас беспокоит?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (898,'Свобода!','Наконец-то! Кто-то пришел мне на помощь!$B$BПоверить не могу, что тебе удалось пройти мимо стражей. Фанатики из Терамора совсем спятили. Они потопили наш корабль и меня, единственного выжившего, взяли в плен. Меня назвали врагом и угрозой безопасности Альянса.$B$BЯ! Угроза великому и могучему Альянсу? Я был матросом на грузовом судне, возившем самогон из Кабестана в Пиратскую Бухту.$B$BДовольно болтать. Ты ведь поможешь мне вернуться в Кабестан? Скажи, когда решишь тронуться в путь, и мы совершим побег.','Проводите Гилтареса Огненный Цветок к капитану Сияющему в Кабестан.','Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.','Проводите Гилтареса Огненный Цветок в Кабестан.','Вернитесь к капитану Тало\'тасу Сияющему в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свобода!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то! Кто-то пришел мне на помощь!$B$BПоверить не могу, что тебе удалось пройти мимо стражей. Фанатики из Терамора совсем спятили. Они потопили наш корабль и меня, единственного выжившего, взяли в плен. Меня назвали врагом и угрозой безопасности Альянса.$B$BЯ! Угроза великому и могучему Альянсу? Я был матросом на грузовом судне, возившем самогон из Кабестана в Пиратскую Бухту.$B$BДовольно болтать. Ты ведь поможешь мне вернуться в Кабестан? Скажи, когда решишь тронуться в путь, и мы совершим побег.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите Гилтареса Огненный Цветок к капитану Сияющему в Кабестан.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводите Гилтареса Огненный Цветок в Кабестан.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Тало\'тасу Сияющему в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (899,'Огонь ненависти','Они убили мою жену. Они сожгли мою ферму. С той самой ночи я лишь странствую здесь, от восхода солнца до заката, с одной целью – убить как можно больше этих монстров. Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть.$B$BТы, |3-6($c), $gмог:могла; бы мне помочь. Убей их. Убей как можно больше этих тварей. Принеси мне их клыки, и мы вместе попируем на их могилах.','Соберите 30 клыков свинобразов.','Принесите клыки Манкрику на ферму Гроль\'дома в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огонь ненависти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они убили мою жену. Они сожгли мою ферму. С той самой ночи я лишь странствую здесь, от восхода солнца до заката, с одной целью – убить как можно больше этих монстров. Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть.$B$BТы, |3-6($c), $gмог:могла; бы мне помочь. Убей их. Убей как можно больше этих тварей. Принеси мне их клыки, и мы вместе попируем на их могилах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 30 клыков свинобразов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите клыки Манкрику на ферму Гроль\'дома в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (900,'Самофланж','В настоящий момент открыты три контрольных клапана. Судя по надписям на панели управления, их надо закрыть, прежде чем выключать прибор.','Закройте топливный распределительный клапан, перепускной клапан и главный клапан управления, а потом снова попытайтесь воспользоваться панелью управления.','Лампочки, относящиеся к трем управляющим клапанам, медленно гаснут. Зеленый огонек становится желтым, и теперь можно повернуть рычаг, выключающий прибор. Клапаны закрыты, и терминал можно отключить.','Вернитесь к панели управления, находящейся в исследовательском центре Торговой Компании в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самофланж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В настоящий момент открыты три контрольных клапана. Судя по надписям на панели управления, их надо закрыть, прежде чем выключать прибор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Закройте топливный распределительный клапан, перепускной клапан и главный клапан управления, а потом снова попытайтесь воспользоваться панелью управления.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лампочки, относящиеся к трем управляющим клапанам, медленно гаснут. Зеленый огонек становится желтым, и теперь можно повернуть рычаг, выключающий прибор. Клапаны закрыты, и терминал можно отключить.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к панели управления, находящейся в исследовательском центре Торговой Компании в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (901,'Самофланж','Прибор выключен, и вы можете открыть панель управления и достать самофланж из терминала. Все бы хорошо, но чтобы отпереть терминал, нужен ключ.','Возьмите у ремонтника Угрелова ключ от терминала.','Повернув ключ в замке, вы открываете панель управления. В верхней части терминала гаснет красная лампочка. Теперь он полностью обесточен.','Лампочки на панели потухли, стрелки всех приборов на нуле, все бездействует.','Вернитесь к панели управления, находящейся в исследовательском центре Торговой Компании в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самофланж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прибор выключен, и вы можете открыть панель управления и достать самофланж из терминала. Все бы хорошо, но чтобы отпереть терминал, нужен ключ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите у ремонтника Угрелова ключ от терминала.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Повернув ключ в замке, вы открываете панель управления. В верхней части терминала гаснет красная лампочка. Теперь он полностью обесточен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лампочки на панели потухли, стрелки всех приборов на нуле, все бездействует.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к панели управления, находящейся в исследовательском центре Торговой Компании в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (902,'Самофланж','Под панелью управления оказывается мешанина проводов, ламп и загадочных механических объектов – кажется, большая часть там вообще не нужна. Отодвинув их в сторону и сунув руку поглубже, вы находите самофланж. Одного усилия хватает, чтобы вытащить его из паза.','Отнесите самофланж Пароклапану в Лагерь Котельника, что в Северных Степях.','Это... Э... Любопытно... Да. Я пошлю его в Союз ремонтников Нижней шахты. Не сомневаюсь, что эту штуку исследуют и поймут, для чего она нужна.\n\nВпрочем, сначала надо самому посмотреть что к чему...','Верните самофланж Пароклапану в Лагерь Котельника, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самофланж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Под панелью управления оказывается мешанина проводов, ламп и загадочных механических объектов – кажется, большая часть там вообще не нужна. Отодвинув их в сторону и сунув руку поглубже, вы находите самофланж. Одного усилия хватает, чтобы вытащить его из паза.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите самофланж Пароклапану в Лагерь Котельника, что в Северных Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это... Э... Любопытно... Да. Я пошлю его в Союз ремонтников Нижней шахты. Не сомневаюсь, что эту штуку исследуют и поймут, для чего она нужна.\n\nВпрочем, сначала надо самому посмотреть что к чему...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Верните самофланж Пароклапану в Лагерь Котельника, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (903,'Охота на охотниц','Если хочешь доказать свою храбрость, придется сразиться с кем-то по-настоящему опасным. Охотницы саванны, живущие в Степях, – очень коварные звери. Сильные, могучие, хитрые... и смертельно опасные. В последнее время они стали нападать на разведчиков на подходе к городу, особенно с северо-восточной стороны.$B$BСоблюдай осторожность, $n, иначе можешь неожиданно превратиться из охотника в дичь.','Добудьте 5 когтей охотниц саванны.','Доставьте когти Сергре Черный Шип в Перекресток, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на охотниц',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хочешь доказать свою храбрость, придется сразиться с кем-то по-настоящему опасным. Охотницы саванны, живущие в Степях, – очень коварные звери. Сильные, могучие, хитрые... и смертельно опасные. В последнее время они стали нападать на разведчиков на подходе к городу, особенно с северо-восточной стороны.$B$BСоблюдай осторожность, $n, иначе можешь неожиданно превратиться из охотника в дичь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 когтей охотниц саванны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Доставьте когти Сергре Черный Шип в Перекресток, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (904,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (905,'В логово ящера','Поохотьтесь на яркочешуйчатых ящеров и соберите с них перья. Положите их в 3 гнезда яркочешуйчатых ящеров.','Осторожно, яйца хрупкие. Разбитые мне не нужны.','Вернитесь к Сергре Черный Шип в Перекресток в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В логово ящера',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поохотьтесь на яркочешуйчатых ящеров и соберите с них перья. Положите их в 3 гнезда яркочешуйчатых ящеров.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Осторожно, яйца хрупкие. Разбитые мне не нужны.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сергре Черный Шип в Перекресток в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (906,'Предатель в наших рядах','Отнеси голову Лока Тхорку на Перекресток, |3-6($r). *фыркает* Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в *фыркает* таких вещах. Но я не сомневаюсь, что он наградит тебя за совершенный подвиг. *фыркает*$B$BПока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана. Пока же прощай.','Отнесите череп Лока Тхорку на Перекресток.','Да, что такое?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предатель в наших рядах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси голову Лока Тхорку на Перекресток, |3-6($r). *фыркает* Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в *фыркает* таких вещах. Но я не сомневаюсь, что он наградит тебя за совершенный подвиг. *фыркает*$B$BПока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана. Пока же прощай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите череп Лока Тхорку на Перекресток.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, что такое?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (907,'Разъяренные рокочущие ящерицы','Пришло время выступить против рокочущих ящериц. Они столь огромны, что земля дрожит под их шагами. Сражаясь с ними, соблюдай осторожность: один неверный шаг – и они стопчут тебя.$B$BЯщерицы живут в южной части Степей. Их называют грозорылами, грозошкурами и громоголовами. Возвращайся ко мне с победой.','Я рад, что ты принес доказательство своего торжества. И особенно здорово, что у тебя все кости остались целы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разъяренные рокочущие ящерицы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время выступить против рокочущих ящериц. Они столь огромны, что земля дрожит под их шагами. Сражаясь с ними, соблюдай осторожность: один неверный шаг – и они стопчут тебя.$B$BЯщерицы живут в южной части Степей. Их называют грозорылами, грозошкурами и громоголовами. Возвращайся ко мне с победой.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что ты принес доказательство своего торжества. И особенно здорово, что у тебя все кости остались целы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (908,'Среди руин','Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины. Их присутствие приведет лишь к тому, что Стихии озлобятся на нас. Если это так и оставить, то они захватят эти места навсегда.$B$B$n, ступай в Непроглядную Пучину и найди в руинах глубинный камень. Он должен быть где-то поблизости в воде. В нем находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий. Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!','Принесите глубинный сердечник Дже\'нею Санкрия на заставу Зорам\'гар, что в Ясеневом лесу.','Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемая кладезь информации, которую мы сможем оттуда извлечь. Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить. Ты сегодня хорошо $Gпотрудился:потрудилась;, и Служители Земли весьма благодарны тебе за помощь. Ты и всей Орде $Gпомог:помогла;, и имеешь право гордиться собой.','Удалось ли вам найти ядро глубин? Без него мы не сможем понять, что такое Сумеречный Молот там, внизу.','Вернитесь к Дже\'неу Санкри в Ясеневый лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Среди руин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины. Их присутствие приведет лишь к тому, что Стихии озлобятся на нас. Если это так и оставить, то они захватят эти места навсегда.$B$B$n, ступай в Непроглядную Пучину и найди в руинах глубинный камень. Он должен быть где-то поблизости в воде. В нем находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий. Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите глубинный сердечник Дже\'нею Санкрия на заставу Зорам\'гар, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемая кладезь информации, которую мы сможем оттуда извлечь. Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить. Ты сегодня хорошо $Gпотрудился:потрудилась;, и Служители Земли весьма благодарны тебе за помощь. Ты и всей Орде $Gпомог:помогла;, и имеешь право гордиться собой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли вам найти ядро глубин? Без него мы не сможем понять, что такое Сумеречный Молот там, внизу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дже\'неу Санкри в Ясеневый лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (909,'Барон Акванис','Сраженный элементаль воды оставил после себя странную сферу. Вы предполагаете, что этот предмет каким-то образом подпитывал тварь энергией. Внутри сферы плещется грязная на вид жидкость. Сама сфера вроде бы не поддается никаким физическим воздействиям.$B$BЕсли кто и сможет понять, что это за штука, то это Дже\'неу Санкри из Служителей Земли. Он находится на заставе Орды Зорам\'гар в Ясеневом лесу.','Принесите странную водяную сферу Дже\'неу Санкри на заставу Зорам\'гар, что в Ясеневом лесу.','Ого... вот это находка, $N. Говоришь, ты $Gдобыл:добыла; это у барона Акваниса в Черных Глубинах? Барон Акванис давно уже считается оскверненной силой Стихии, а этот шар даст понять, что именно повергло его в скверну. Хотя я не удивлюсь, если это окажется клан Сумеречного Молота, зато мы узнаем, как они сумели это сделать. Хорошо, что ты $Gпринес:принесла; эту штуку мне. Прошу – прими это вместе с горячей благодарностью Служителей Земли.','О, привет еще раз, $N. Я, как всегда, взирал на морские волны и читал их письмена. Что привело тебя на форпост?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Барон Акванис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сраженный элементаль воды оставил после себя странную сферу. Вы предполагаете, что этот предмет каким-то образом подпитывал тварь энергией. Внутри сферы плещется грязная на вид жидкость. Сама сфера вроде бы не поддается никаким физическим воздействиям.$B$BЕсли кто и сможет понять, что это за штука, то это Дже\'неу Санкри из Служителей Земли. Он находится на заставе Орды Зорам\'гар в Ясеневом лесу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите странную водяную сферу Дже\'неу Санкри на заставу Зорам\'гар, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ого... вот это находка, $N. Говоришь, ты $Gдобыл:добыла; это у барона Акваниса в Черных Глубинах? Барон Акванис давно уже считается оскверненной силой Стихии, а этот шар даст понять, что именно повергло его в скверну. Хотя я не удивлюсь, если это окажется клан Сумеречного Молота, зато мы узнаем, как они сумели это сделать. Хорошо, что ты $Gпринес:принесла; эту штуку мне. Прошу – прими это вместе с горячей благодарностью Служителей Земли.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, привет еще раз, $N. Я, как всегда, взирал на морские волны и читал их письмена. Что привело тебя на форпост?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (910,'В порту','Я слышал, что между Кабестаном и Пиратской Бухтой плавают огромные корабли! Я бы хотел плавать по океану и сражаться в настоящих морских боях. Может быть, когда я вырасту, я стану великим моряком Орды! Да!$b$bПожалуйста, своди меня в Кабестан, посмотреть на порт. Обещаю, я буду хорошо себя вести и не упаду в воду. Мне так хочется увидеть корабли и почувствовать запах моря!','Отведите своего подопечного в порт Кабестана в Степях.','Ух ты, океан ОГРОМЕН! Там было много чаек и много других вещей. Там много шума и суеты, прям как я и ожидал. Пираты также расположены неподалеку. Клево!$B$BСпасибо, что $Gвзял:взяла; меня в Кабестан, $N. Там было действительно круто!','Мы уже на месте?','Сходить в порт Кабестана в Степях','Поговорите со своим подопечным орком-сиротой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В порту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, что между Кабестаном и Пиратской Бухтой плавают огромные корабли! Я бы хотел плавать по океану и сражаться в настоящих морских боях. Может быть, когда я вырасту, я стану великим моряком Орды! Да!$b$bПожалуйста, своди меня в Кабестан, посмотреть на порт. Обещаю, я буду хорошо себя вести и не упаду в воду. Мне так хочется увидеть корабли и почувствовать запах моря!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите своего подопечного в порт Кабестана в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты, океан ОГРОМЕН! Там было много чаек и много других вещей. Там много шума и суеты, прям как я и ожидал. Пираты также расположены неподалеку. Клево!$B$BСпасибо, что $Gвзял:взяла; меня в Кабестан, $N. Там было действительно круто!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы уже на месте?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сходить в порт Кабестана в Степях',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим подопечным орком-сиротой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (911,'Врата пограничья','Говорят, что Ясеневый лес – это новое пограничье, а врата к нему – Застава Мор\'шан. Здорово быть первооткрывателем, добывать все необходимое из первозданного леса! Говорят, что именно там будут греметь битвы между Ордой и Альянсом. Вот бы мне попасть туда!$b$bОтведи меня к заставе Мор\'шан, посмотреть на новое пограничье! Я хочу посмотреть, как Орда выгонит оттуда гадких ночных эльфов!','Отведите своего подопечного к Заставе Мор\'шан в северной части Степей на границе с Ясеневым лесом.','Ух ты, Ясеневый лес - это место, где происходят настоящие приключения! Ты когда-нибудь $Gсражался:сражалась; в Ясеневом лесу, $N? Когда я подрасту, стану героем, то я хочу прийти в Ясеневый лес и сражаться во славу Орды.$B$BСпасибо, что Gвзял:взяла; меня на фронт, $N. Ты $Gлучший:лучшая;!','Мы уже на месте?','Сходить на Заставу Мор\'шан в Степи.','Поговорите со своим подопечным орком-сиротой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Врата пограничья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что Ясеневый лес – это новое пограничье, а врата к нему – Застава Мор\'шан. Здорово быть первооткрывателем, добывать все необходимое из первозданного леса! Говорят, что именно там будут греметь битвы между Ордой и Альянсом. Вот бы мне попасть туда!$b$bОтведи меня к заставе Мор\'шан, посмотреть на новое пограничье! Я хочу посмотреть, как Орда выгонит оттуда гадких ночных эльфов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите своего подопечного к Заставе Мор\'шан в северной части Степей на границе с Ясеневым лесом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты, Ясеневый лес - это место, где происходят настоящие приключения! Ты когда-нибудь $Gсражался:сражалась; в Ясеневом лесу, $N? Когда я подрасту, стану героем, то я хочу прийти в Ясеневый лес и сражаться во славу Орды.$B$BСпасибо, что Gвзял:взяла; меня на фронт, $N. Ты $Gлучший:лучшая;!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы уже на месте?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сходить на Заставу Мор\'шан в Степи.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим подопечным орком-сиротой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (912,'Маска троггов из племени Камнедробов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маска троггов из племени Камнедробов',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (913,'Крик грозового змея','Грозовой змей – лютый зверь, $n. И все же ты уже $gготов:готова; бросить ему вызов. Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты.$B$BВыполни мое задание, и твое обучение подойдет к концу.','Задание выполнено? Тебе удалось убить грозового змея?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крик грозового змея',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грозовой змей – лютый зверь, $n. И все же ты уже $gготов:готова; бросить ему вызов. Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты.$B$BВыполни мое задание, и твое обучение подойдет к концу.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Задание выполнено? Тебе удалось убить грозового змея?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (914,'Повелители Змей','Друиды-змеи в Пещерах Стенаний поражены порчей. Когда-то они были частью ордена, давшего обет исцелить Степи, но теперь хотят перекроить эти земли в соответствии со своими извращенными представлениями о порядке.$B$BУ друидов-змей четыре предводителя и каждый обладает Камнем Сновидения. Даже теперь их лица преследуют меня в кошмарах. Убей предводителей друидов, принеси мне их камни, и в Степях снова воцарится мир.$B$BИди, $n, и разыщи их укрытия в Пещерах Стенаний.','Принесите камни Кобрана, Анакондры, Пифаса и Серпентиса Наре Буйногривой, на Громовой Утес.','Вернитесь к Наре Буйногривой в Золотые равнины, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелители Змей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друиды-змеи в Пещерах Стенаний поражены порчей. Когда-то они были частью ордена, давшего обет исцелить Степи, но теперь хотят перекроить эти земли в соответствии со своими извращенными представлениями о порядке.$B$BУ друидов-змей четыре предводителя и каждый обладает Камнем Сновидения. Даже теперь их лица преследуют меня в кошмарах. Убей предводителей друидов, принеси мне их камни, и в Степях снова воцарится мир.$B$BИди, $n, и разыщи их укрытия в Пещерах Стенаний.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите камни Кобрана, Анакондры, Пифаса и Серпентиса Наре Буйногривой, на Громовой Утес.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Наре Буйногривой в Золотые равнины, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (915,'Детям – мороженое!','МОРОЖЕНОЕ! Пожалуйста, пожалуйста, пожалуйста, купи мне немного мороженого!!! Я больше всего люблю клубничное, а самое вкусное клубничное мороженое делают Тигуль и Форор! Это мое самое любимое мороженое на свете!$b$bЯ пробовал его только один раз, когда меня водили на гонки на Мерцающей равнине, но говорят, его сейчас продают у нас в городе! Пожалуйста! Пожалуйста-препожалуйста! Преогромное пожалуйста!!!!','Купите своему подопечному клубничное мороженое. Кажется, мальчик предпочитает мороженое Тигуля и Форора.','Ммммммммм! Я люблю их клубничное мороженое! Тигуля и Форор определенно умеют делать его!$B$BСпасибо огромное, $N. Это лучшее угощение в мире!','Я бы хотел, чтобы у них было больше вкусов мороженого, кроме клубники, но я думаю, мне повезло, что клубника - моя любимая!','Вернитесь к своему подопечному орку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Детям – мороженое!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','МОРОЖЕНОЕ! Пожалуйста, пожалуйста, пожалуйста, купи мне немного мороженого!!! Я больше всего люблю клубничное, а самое вкусное клубничное мороженое делают Тигуль и Форор! Это мое самое любимое мороженое на свете!$b$bЯ пробовал его только один раз, когда меня водили на гонки на Мерцающей равнине, но говорят, его сейчас продают у нас в городе! Пожалуйста! Пожалуйста-препожалуйста! Преогромное пожалуйста!!!!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите своему подопечному клубничное мороженое. Кажется, мальчик предпочитает мороженое Тигуля и Форора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ммммммммм! Я люблю их клубничное мороженое! Тигуля и Форор определенно умеют делать его!$B$BСпасибо огромное, $N. Это лучшее угощение в мире!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я бы хотел, чтобы у них было больше вкусов мороженого, кроме клубники, но я думаю, мне повезло, что клубника - моя любимая!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному орку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (916,'Оскверненные пауки','[Deprecated] I came to Shadowglen to study the webwood spiders that dwell in the Shadowthread cave. I was told that with Teldrassil\'s recent blessing, they should be far less aggressive. It seems I was mislead.$B$BI recently retrieved some of their venom sacs, and was disturbed to find a very unhealthy corruption in them. Suffice to say, I\'m concerned what could occur if we let corrupted wildlife like this run rampant.$B$BI want you to reduce their population to buy some time.','[Deprecated] Kill 12 Webwood Spiders.','[Deprecated] Return to Gilshalan Windwalker at Aldrassil.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненные пауки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[Deprecated] I came to Shadowglen to study the webwood spiders that dwell in the Shadowthread cave. I was told that with Teldrassil\'s recent blessing, they should be far less aggressive. It seems I was mislead.$B$BI recently retrieved some of their venom sacs, and was disturbed to find a very unhealthy corruption in them. Suffice to say, I\'m concerned what could occur if we let corrupted wildlife like this run rampant.$B$BI want you to reduce their population to buy some time.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[Deprecated] Kill 12 Webwood Spiders.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Gilshalan Windwalker at Aldrassil.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (917,'Яйцо чащобного тенетника','Так, давай о деле. Может, ты мне еще немножечко пособишь? Необходимо добыть яйцо чащобного паука из этой пещеры, но пауки от этого в восторг не придут, понятно. Если достанешь яйцо и принесешь его Дирании, мы будем тебе очень и очень благодарны.','Добудьте яйцо чащобного тенетника.','Вернитесь к Дирании Серебряное Сияние в Альдрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яйцо чащобного тенетника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, давай о деле. Может, ты мне еще немножечко пособишь? Необходимо добыть яйцо чащобного паука из этой пещеры, но пауки от этого в восторг не придут, понятно. Если достанешь яйцо и принесешь его Дирании, мы будем тебе очень и очень благодарны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте яйцо чащобного тенетника.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дирании Серебряное Сияние в Альдрассил.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (918,'Саженцы древесника','Древесники Тельдрассила – духи Природы. Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе.$B$BПотому меня очень тревожит, что древесники становятся такими озлобленными.$B$BМне кажется, что дело в почве. Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников. Не $Gмог:могла; бы ты собрать для меня этих саженцев вокруг озера Аль\'Амет?','Принесите 6 саженцев древесников.','Вернитесь к Деналану к озеру Аль\'Амет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Саженцы древесника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древесники Тельдрассила – духи Природы. Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе.$B$BПотому меня очень тревожит, что древесники становятся такими озлобленными.$B$BМне кажется, что дело в почве. Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников. Не $Gмог:могла; бы ты собрать для меня этих саженцев вокруг озера Аль\'Амет?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 саженцев древесников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Деналану к озеру Аль\'Амет.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (919,'Ростки древесника','Вокруг вод озера Аль\'Амет прорастают маленькие древесники. Боюсь, им уже не помочь, нам придется выдернуть их из земли прежде, чем они станут слишком большими и начнут приносить беды.$B$BКогда будешь бродить вокруг озера, выдергивай каждый росток древесника, что попадется тебе по дороге. Помоги очистить нашу землю!','Принесите 10 ростков древесника.','Вернитесь к Деналану к озеру Аль\'Амет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ростки древесника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вокруг вод озера Аль\'Амет прорастают маленькие древесники. Боюсь, им уже не помочь, нам придется выдернуть их из земли прежде, чем они станут слишком большими и начнут приносить беды.$B$BКогда будешь бродить вокруг озера, выдергивай каждый росток древесника, что попадется тебе по дороге. Помоги очистить нашу землю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 ростков древесника.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Деналану к озеру Аль\'Амет.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (920,'Зов Тенарона','Ты $n, не так ли? До меня доходили слухи, что тебя искал Тенарон. Ты отыщешь его в самой верхней комнате на вершине Альдрассила.$b$bХоть мы и живем долго, не стоит заставлять Тенарона ждать.','Поговорите с Тенароном Хваткой Бури. Он ждет вас на вершине Альдрассила в Тенистой долине.','А, $n. Я думал, что ты быстрее откликнешься на мой призыв. У меня есть важное задание, которое я хочу поручить тебе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Тенарона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $n, не так ли? До меня доходили слухи, что тебя искал Тенарон. Ты отыщешь его в самой верхней комнате на вершине Альдрассила.$b$bХоть мы и живем долго, не стоит заставлять Тенарона ждать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тенароном Хваткой Бури. Он ждет вас на вершине Альдрассила в Тенистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, $n. Я думал, что ты быстрее откликнешься на мой призыв. У меня есть важное задание, которое я хочу поручить тебе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (921,'Телдрассил: венец Азерота','Пришла пора тебе отправиться на поиски приключений, $n. Однако прежде чем ты покинешь эти волшебные леса, тебе следует узнать побольше о нашей современной истории.$b$bУ меня есть для тебя одно задание. Отправляйся к лунному колодцу, расположенному к северу от Альдрассила, и наполни вот этот фиал колодезной водой. Находясь там, ты сможешь приобщиться к нашей магии, а также заглянуть в прошлое нашего народа.$B$BНабрав воды, поднимись по западному помосту на вершину Альдрассила и отдай фиал Тенарону Хватке Бури.','Наполните хрустальный фиал водой.','Тебе уже довелось услышать первую часть истории о последствиях битвы за гору Хиджал, однако еще многое нужно рассказать, и выполнение задания, данного мной тебе, будет продолжаться на протяжении всего твоего путешествия через Тельдрассил в Дарнас.','Лунные колодцы содержат воду Источника Вечности, древнего источника магии, который навлек на наш мир так много ужасов.$b$bДруиды пользуются свойствами колодцев, а Стражи чтят их как святилища Элуны, но использовать магию колодцев запрещено всем.','Поднимитесь по западному помосту на вершину Альдрассила и поговорите с Тенароном Хваткой Бури.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Телдрассил: венец Азерота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришла пора тебе отправиться на поиски приключений, $n. Однако прежде чем ты покинешь эти волшебные леса, тебе следует узнать побольше о нашей современной истории.$b$bУ меня есть для тебя одно задание. Отправляйся к лунному колодцу, расположенному к северу от Альдрассила, и наполни вот этот фиал колодезной водой. Находясь там, ты сможешь приобщиться к нашей магии, а также заглянуть в прошлое нашего народа.$B$BНабрав воды, поднимись по западному помосту на вершину Альдрассила и отдай фиал Тенарону Хватке Бури.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните хрустальный фиал водой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе уже довелось услышать первую часть истории о последствиях битвы за гору Хиджал, однако еще многое нужно рассказать, и выполнение задания, данного мной тебе, будет продолжаться на протяжении всего твоего путешествия через Тельдрассил в Дарнас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лунные колодцы содержат воду Источника Вечности, древнего источника магии, который навлек на наш мир так много ужасов.$b$bДруиды пользуются свойствами колодцев, а Стражи чтят их как святилища Элуны, но использовать магию колодцев запрещено всем.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поднимитесь по западному помосту на вершину Альдрассила и поговорите с Тенароном Хваткой Бури.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (922,'Релиан Зеленый Костер','$n, не $Gмог:могла; бы ты доставить один из тех саженцев, что ты $Gпринес:принесла; мне, моему другу, Релиану Зеленому Костру? Он друид, который живет в Родниковом шалаше. Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками. У него есть кое-какие идеи, и он будет очень рад поработать с таким образцом.$B$BБлагодарю тебя, $n. Твоя помощь просто неоценима. Надеюсь, что однажды ты увидишь плоды моих трудов.$B$BТы найдешь Родниковый шалаш возле дороги, идущей на запад из Доланаара, в направлении Дарнаса.','Принесите саженец древесника Релиану Зеленому Костру в Родниковый шалаш.','Привет тебе...$B$BЧем могу помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Релиан Зеленый Костер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, не $Gмог:могла; бы ты доставить один из тех саженцев, что ты $Gпринес:принесла; мне, моему другу, Релиану Зеленому Костру? Он друид, который живет в Родниковом шалаше. Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками. У него есть кое-какие идеи, и он будет очень рад поработать с таким образцом.$B$BБлагодарю тебя, $n. Твоя помощь просто неоценима. Надеюсь, что однажды ты увидишь плоды моих трудов.$B$BТы найдешь Родниковый шалаш возле дороги, идущей на запад из Доланаара, в направлении Дарнаса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите саженец древесника Релиану Зеленому Костру в Родниковый шалаш.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет тебе...$B$BЧем могу помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (923,'Мшистые опухоли','Древесники становятся все более злобными. Мы пытаемся найти источник этой беды, но пока... чтобы уберечь Тельдрассил, нам приходится уничтожать древесников, которым уже не поможешь. Те, что бродят вокруг Родникового озера на севере, поражены порчей сильнее всего. Их надо уничтожить!$B$BУничтожь всех древесников, которых там найдешь, и собери растущие на них мшистые опухоли. Принеси их мне, чтобы я мог их сжечь.','Соберите 5 мшистых опухолей.','Вернитесь к Релиану Зеленому в Родниковый шалаш.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мшистые опухоли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древесники становятся все более злобными. Мы пытаемся найти источник этой беды, но пока... чтобы уберечь Тельдрассил, нам приходится уничтожать древесников, которым уже не поможешь. Те, что бродят вокруг Родникового озера на севере, поражены порчей сильнее всего. Их надо уничтожить!$B$BУничтожь всех древесников, которых там найдешь, и собери растущие на них мшистые опухоли. Принеси их мне, чтобы я мог их сжечь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 мшистых опухолей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Релиану Зеленому в Родниковый шалаш.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (924,'Демоново семя','Демоново семя – страшное оружие Пылающего Легиона. Оно хранится в пещере на Вершине Багрового Тумана, над демоническим алтарем Огня.$B$BЯ подготовил силовые камни, которые разорвут связь Семени с Легионом.$B$BВозьми камень со стола и возложи его на алтарь Огня на Вершине Багрового Тумана. Отправляйся на запад, а на развилке сверни на север. Вершина окажется по левую руку от тебя. Безопаснее всего подниматься по северному склону. $B$BТоропись: сила камня постепенно иссякает.','Возьмите треснувший камень силы, возложите его на алтарь Огня до окончания его действия и возвращайтесь к Ак\'Зелоту.','Твоя цель достигнута. Тебе удалось уничтожить Демоново семя, как велел Ниру. Но это еще не конец…\n\nПосле уничтожения Демонова семени по всему астралу пошли волны небывалой силы. Их почувствовала не только я. Об этом узнают те, чью игрушку мы сломали…\n\nВпрочем, невзирая на грядущие испытания, я хочу вручить тебе кое-что. Ниру велел дать это в уплату и поблагодарить тебя.\n\nИтак, я благодарю тебя.','Семя Демона все еще существует. Я чувствую его силу...','Вернитесь к Ак\'Зелоту в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демоново семя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Демоново семя – страшное оружие Пылающего Легиона. Оно хранится в пещере на Вершине Багрового Тумана, над демоническим алтарем Огня.$B$BЯ подготовил силовые камни, которые разорвут связь Семени с Легионом.$B$BВозьми камень со стола и возложи его на алтарь Огня на Вершине Багрового Тумана. Отправляйся на запад, а на развилке сверни на север. Вершина окажется по левую руку от тебя. Безопаснее всего подниматься по северному склону. $B$BТоропись: сила камня постепенно иссякает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите треснувший камень силы, возложите его на алтарь Огня до окончания его действия и возвращайтесь к Ак\'Зелоту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя цель достигнута. Тебе удалось уничтожить Демоново семя, как велел Ниру. Но это еще не конец…\n\nПосле уничтожения Демонова семени по всему астралу пошли волны небывалой силы. Их почувствовала не только я. Об этом узнают те, чью игрушку мы сломали…\n\nВпрочем, невзирая на грядущие испытания, я хочу вручить тебе кое-что. Ниру велел дать это в уплату и поблагодарить тебя.\n\nИтак, я благодарю тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Семя Демона все еще существует. Я чувствую его силу...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ак\'Зелоту в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (925,'Отпечаток копыта Кэрна','Говорят, что Кэрн Кровавое Копыто – один из величайших героев Орды. Когда я вырасту, я тоже хочу стать героем Орды!$b$bТы $gзнаком:знакома; с Кэрном? Можешь взять у него отпечаток копыта для меня? Сам я стесняюсь, у него нет времени на таких, как я... другое дело ты! Ты $gтакой же искатель:такая же искательница; приключений, как и он! Я уверен, что тебе получить у него отпечаток копыта – проще простого!$b$bПожалуйста!','Отправляйтесь в Громовой Утес и постарайтесь получить отпечаток копыта Кэрна Кровавого Копыта для своего подопечного.','УХ ТЫ! Ты $Gдостал:достала; для меня отпечаток копыта Кэрна! Спасибо огромное! И... ого! Он написал личное сообщение здесь - мне! Я знал, что он будет действительно крутым, прям как я и думал! Может, когда-нибудь, я сам лично поблагодарю его... когда стану героем Орды!$B$BТы $Gлучший:лучшая;, $N. Спасибо, что $Gбыл:была; так $Gдобр:добра; ко мне.','Когда орки были одни и без друзей, таурены приветствовали их в чужой стране и делились с ними, ничего не прося взамен. Это честь, $N.','Вернитесь к своему подопечному орку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отпечаток копыта Кэрна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что Кэрн Кровавое Копыто – один из величайших героев Орды. Когда я вырасту, я тоже хочу стать героем Орды!$b$bТы $gзнаком:знакома; с Кэрном? Можешь взять у него отпечаток копыта для меня? Сам я стесняюсь, у него нет времени на таких, как я... другое дело ты! Ты $gтакой же искатель:такая же искательница; приключений, как и он! Я уверен, что тебе получить у него отпечаток копыта – проще простого!$b$bПожалуйста!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Громовой Утес и постарайтесь получить отпечаток копыта Кэрна Кровавого Копыта для своего подопечного.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','УХ ТЫ! Ты $Gдостал:достала; для меня отпечаток копыта Кэрна! Спасибо огромное! И... ого! Он написал личное сообщение здесь - мне! Я знал, что он будет действительно крутым, прям как я и думал! Может, когда-нибудь, я сам лично поблагодарю его... когда стану героем Орды!$B$BТы $Gлучший:лучшая;, $N. Спасибо, что $Gбыл:была; так $Gдобр:добра; ко мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда орки были одни и без друзей, таурены приветствовали их в чужой стране и делились с ними, ничего не прося взамен. Это честь, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному орку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (926,'Треснувший камень силы','Эти камни содержат магическую энергию, но они были умышленно разбиты. Они очень нестабильны и могут в скором времени самоуничтожиться, как только их уберут со стола.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Треснувший камень силы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти камни содержат магическую энергию, но они были умышленно разбиты. Они очень нестабильны и могут в скором времени самоуничтожиться, как только их уберут со стола.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (927,'Сердце, поросшее мхом','Сердце Черномшеца Злосмрадного поросло темным маслянистым мхом. Понять, что это сердце, можно лишь по тому, что оно медленно и ритмично пульсирует... Даже сейчас. $B$BВозможно, это заинтересует Деналана.','Принесите поросшее мхом сердце Деналану к озеру Аль\'Амет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце, поросшее мхом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сердце Черномшеца Злосмрадного поросло темным маслянистым мхом. Понять, что это сердце, можно лишь по тому, что оно медленно и ритмично пульсирует... Даже сейчас. $B$BВозможно, это заинтересует Деналана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите поросшее мхом сердце Деналану к озеру Аль\'Амет.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (928,'Тельдрассил: утраченное знание','Я мог бы поведать тебе еще многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждет тебя. Я перелил воду из фиала, принесенного тобой, в этот сосуд, чтобы ты $gотнес:отнесла; его Коритрасу.$b$bТы найдешь Коритраса у лунного колодца в Доланааре. Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернет на запад, следуй по пути, мощенному булыжниками.$b$bИ советую тебе не сходить с дороги, $n, – в последнее время в лесу появились опасные существа.','Отнесите частично наполненный сосуд Коритрасу Лунному Гневу в Доланаар.','А, понятно. Тебя послал Тенарон. Ну что ж, похоже, нам о многом нужно поговорить, многое сделать – но времени мало.$b$bДумаю, лучше не медлить и приступить к делу сейчас же.','Привет тебе, |3-6($c). Чем обязан удовольствию встречи с тобой?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тельдрассил: утраченное знание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я мог бы поведать тебе еще многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждет тебя. Я перелил воду из фиала, принесенного тобой, в этот сосуд, чтобы ты $gотнес:отнесла; его Коритрасу.$b$bТы найдешь Коритраса у лунного колодца в Доланааре. Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернет на запад, следуй по пути, мощенному булыжниками.$b$bИ советую тебе не сходить с дороги, $n, – в последнее время в лесу появились опасные существа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите частично наполненный сосуд Коритрасу Лунному Гневу в Доланаар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, понятно. Тебя послал Тенарон. Ну что ж, похоже, нам о многом нужно поговорить, многое сделать – но времени мало.$b$bДумаю, лучше не медлить и приступить к делу сейчас же.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет тебе, |3-6($c). Чем обязан удовольствию встречи с тобой?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (929,'Тельдрассил: отрицание Аспектов','Сначала позволь поведать тебе, какая стоит перед тобой задача. Друиды Дарнаса пользуются водой из лунных колодцев Тельдрассила, и время от временем их колодцы надо пополнять. При помощи этих специально изготовленных фиалов ты сможешь набирать воду из лунных колодцев.$b$bОтнеси этот сосуд к лунному колодцу у Деревни Звездного Ветра на востоке и набери из него немного воды, а затем возвращайся ко мне. Отнесись внимательно к урокам, которые дадут тебе лунные колодцы, мы все должны совершенствоваться.','Наполните нефритовый фиал.','Вернитесь к Коритрасу Лунному Гневу в Доланаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тельдрассил: отрицание Аспектов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сначала позволь поведать тебе, какая стоит перед тобой задача. Друиды Дарнаса пользуются водой из лунных колодцев Тельдрассила, и время от временем их колодцы надо пополнять. При помощи этих специально изготовленных фиалов ты сможешь набирать воду из лунных колодцев.$b$bОтнеси этот сосуд к лунному колодцу у Деревни Звездного Ветра на востоке и набери из него немного воды, а затем возвращайся ко мне. Отнесись внимательно к урокам, которые дадут тебе лунные колодцы, мы все должны совершенствоваться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните нефритовый фиал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коритрасу Лунному Гневу в Доланаар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (930,'Светящийся плод','Под ветками этого светящегося растения висит большой круглый плод.$B$BВы уверены, что Деналану захочется его изучить.','Принесите светящийся плод Деналану к озеру Аль\'Амет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Светящийся плод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Под ветками этого светящегося растения висит большой круглый плод.$B$BВы уверены, что Деналану захочется его изучить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите светящийся плод Деналану к озеру Аль\'Амет.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (931,'Мерцающий росток','Росток этого дерева мерцает в сумраке леса, распространяя вокруг себя изменчивое, пульсирующее свечение.$B$BНаверное. Деналана интересует именно такой образец.','Принесите мерцающий росток Деналану. Обычно его можно найти на берегу озера Аль\'Амет, но иногда он перемещается к Родниковому шалашу.','Ты что-то мне принесла?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мерцающий росток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Росток этого дерева мерцает в сумраке леса, распространяя вокруг себя изменчивое, пульсирующее свечение.$B$BНаверное. Деналана интересует именно такой образец.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мерцающий росток Деналану. Обычно его можно найти на берегу озера Аль\'Амет, но иногда он перемещается к Родниковому шалашу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты что-то мне принесла?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (932,'Извращенная ненависть','Должен предупредить тебя, $n, что это должно остаться только между нами. Сатиры и так уже причиняют нам немало неприятностей, а этот рыщет уж слишком близко к нашему дому.$B$BЕго зовут лорд Меленас. Он живет по соседству, в Пещере Бесов, где собрал шайку греллей-воинов. Его сердце чернее ночи, а замыслы – омерзительны.$B$BНайди его в пещере, прямо к северу отсюда, и принеси мне его голову!','Добудьте голову лорда Меленаса.','Вернитесь к Таллонкаю Гибкому Корню в Доланаар.','О предателе Меленасе не говорят, но само его присутствие служит горьким напоминанием о том, что доверие нужно заслужить.','Лорд Меленас') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Извращенная ненависть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должен предупредить тебя, $n, что это должно остаться только между нами. Сатиры и так уже причиняют нам немало неприятностей, а этот рыщет уж слишком близко к нашему дому.$B$BЕго зовут лорд Меленас. Он живет по соседству, в Пещере Бесов, где собрал шайку греллей-воинов. Его сердце чернее ночи, а замыслы – омерзительны.$B$BНайди его в пещере, прямо к северу отсюда, и принеси мне его голову!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте голову лорда Меленаса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таллонкаю Гибкому Корню в Доланаар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','О предателе Меленасе не говорят, но само его присутствие служит горьким напоминанием о том, что доверие нужно заслужить.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Лорд Меленас',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (934,'Венец Земли','Но не все было ладно с Тельдрассилом. Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие. Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила.$b$bНо пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-западу от Врат Дарнаса. Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне.','Наполните аметистовый фиал и принесите его Коритрасу Лунному Гневу в Доланаар.','Находиться в присутствии Древа-оракула... это все равно что увидеть воплощенную мудрость. Позволь мне продолжить...$B$BТельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена. Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности. Алекстраза также отказала Оленьему Шлему, а без ее благословения рост Тельдрассила стал непредсказуем, и в нем обнаружились изъяны...','Наряду с друидами, Древо Оракулов и древний $C внимательно следили за ростом Тельдрассила. Но хотя у нас есть новый дом, наша бессмертная жизнь так и не восстановлена.','Вернитесь к Коритрасу Лунному Гневу в Доланаар, что в Тельдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Венец Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Но не все было ладно с Тельдрассилом. Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие. Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила.$b$bНо пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-западу от Врат Дарнаса. Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните аметистовый фиал и принесите его Коритрасу Лунному Гневу в Доланаар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Находиться в присутствии Древа-оракула... это все равно что увидеть воплощенную мудрость. Позволь мне продолжить...$B$BТельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена. Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности. Алекстраза также отказала Оленьему Шлему, а без ее благословения рост Тельдрассила стал непредсказуем, и в нем обнаружились изъяны...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наряду с друидами, Древо Оракулов и древний $C внимательно следили за ростом Тельдрассила. Но хотя у нас есть новый дом, наша бессмертная жизнь так и не восстановлена.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коритрасу Лунному Гневу в Доланаар, что в Тельдрассиле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (935,'Воды Тельдрассила','Отнесите наполненный сосуд Коритрасу Лунному Гневу на перекресток перед Дарнасом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воды Тельдрассила',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите наполненный сосуд Коритрасу Лунному Гневу на перекресток перед Дарнасом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (936,'Помощь верховному друиду Руническому Тотему','Извини, |3-6($c), можно тебя на минутку?$b$bКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.$b$bЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.','Поговорите с верховным друидом Хамуулом Руническим Тотемом в Громовом Утесе.','Привет тебе, |3-6($C)! Рад, что ты хочешь помочь нам в наших исследованиях. Дел у нас много, и я оказал бы тебе дурную услугу, если бы не предупредил, что работа опасная. Надеюсь, тебя это не отпугнет... Впрочем, судя по твоему виду, тебе не впервой встречаться с опасностями.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь верховному друиду Руническому Тотему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Извини, |3-6($c), можно тебя на минутку?$b$bКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.$b$bЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным друидом Хамуулом Руническим Тотемом в Громовом Утесе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, |3-6($C)! Рад, что ты хочешь помочь нам в наших исследованиях. Дел у нас много, и я оказал бы тебе дурную услугу, если бы не предупредил, что работа опасная. Надеюсь, тебя это не отпугнет... Впрочем, судя по твоему виду, тебе не впервой встречаться с опасностями.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (937,'Зачарованная поляна','Соберите 6 поясов Кровавых перьев.','Поговорите с часовым Аранией Проблеск Cолнца на Поляне Оракула.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачарованная поляна',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 поясов Кровавых перьев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с часовым Аранией Проблеск Cолнца на Поляне Оракула.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (938,'Туманна','Мех самки саблезуба имеет характерный серый цвет, сливающийся с фоном окружающего леса. Вы видите, что она сильно пострадала: глубокие рваные раны видны на ее спине и брюхе.$b$bОна смотрит на вас, и в ее голубых глазах читается глубокая мудрость. Похоже, она хочет следовать за вами.','О, благодарю тебя, $n! Я так боялась, что уж больше не увижу мою Туманну, скорбела всем сердцем о ее гибели, о том, что навек разлучилась с моей верной спутницей... Я в неоплатном долгу перед тобой! Прими мою вечную благодарность.','Туманна... Это бла моя вина! Ведьмы застали меня врасплох... Я не должна была позволить им ее у вас...','Поговорите с часовым Аранией Проблеск Cолнца у Древа-оракула.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Туманна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мех самки саблезуба имеет характерный серый цвет, сливающийся с фоном окружающего леса. Вы видите, что она сильно пострадала: глубокие рваные раны видны на ее спине и брюхе.$b$bОна смотрит на вас, и в ее голубых глазах читается глубокая мудрость. Похоже, она хочет следовать за вами.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, благодарю тебя, $n! Я так боялась, что уж больше не увижу мою Туманну, скорбела всем сердцем о ее гибели, о том, что навек разлучилась с моей верной спутницей... Я в неоплатном долгу перед тобой! Прими мою вечную благодарность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Туманна... Это бла моя вина! Ведьмы застали меня врасплох... Я не должна была позволить им ее у вас...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с часовым Аранией Проблеск Cолнца у Древа-оракула.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (939,'Флейта Ксаварика','Вы рассматриваете простую деревянную флейту, которую подобрали, сразив Ксаварика.$B$BУзловатое дерево кажется твердым, но когда вы вертите ее в руках, все спирали и полоски на флейте вдруг начинают вращаться и двигаться. Вас внезапно охватывает нехорошее ощущение...$B$BВы встряхиваетесь, уверенные, что это просто игра воображения.$B$BНо, возможно, у других сатиров найдется разгадка тайны вашей находки. Отнесите ее друиду Эридане Грусти Ветра, которая живет в южной части Оскверненного леса.','Принесите флейту Ксаварика и 5 образцов уз скверны Нефритового Пламени Эридане Грусти Ветра в южную часть Оскверненного леса.','Вернитесь к Эридане Грусти Ветра в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Флейта Ксаварика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы рассматриваете простую деревянную флейту, которую подобрали, сразив Ксаварика.$B$BУзловатое дерево кажется твердым, но когда вы вертите ее в руках, все спирали и полоски на флейте вдруг начинают вращаться и двигаться. Вас внезапно охватывает нехорошее ощущение...$B$BВы встряхиваетесь, уверенные, что это просто игра воображения.$B$BНо, возможно, у других сатиров найдется разгадка тайны вашей находки. Отнесите ее друиду Эридане Грусти Ветра, которая живет в южной части Оскверненного леса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите флейту Ксаварика и 5 образцов уз скверны Нефритового Пламени Эридане Грусти Ветра в южную часть Оскверненного леса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эридане Грусти Ветра в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (940,'Тельдрассил','Шум леса донес до меня весть о твоих подвигах, $n. Когда я ощутила, что гарпии покинули свои гнездовья, великий покой распространился по лесу и его обитатели снова ощутили себя в безопасности. Я боялась посылать очередное сообщение верховному друиду, но теперь я знаю, что ты доставишь его ему в целости и сохранности.$b$bПередай ему письмо и знай, что лес будет охранять тебя по дороге в каменные джунгли.','Передайте отчет Древа-оракула верховному друиду Фэндралу Оленьему Шлему в Дарнас.','Я-то думал, почему Древо-оракул так долго не связывается со мной... Сдается мне, что как только мы решаем одну проблему, немедленно возникает другая, еще более сложная.$b$bБоюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернем себе бессмертие. $b$bТем не менее, ты славно $Gсправился:справилась; с заданием Древа-оракула, и за усердие тебе положена награда.','Хм-м... В тебе силен дух леса, |3-6($c). Что у тебя за дело к верховному друиду калдорай?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тельдрассил',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шум леса донес до меня весть о твоих подвигах, $n. Когда я ощутила, что гарпии покинули свои гнездовья, великий покой распространился по лесу и его обитатели снова ощутили себя в безопасности. Я боялась посылать очередное сообщение верховному друиду, но теперь я знаю, что ты доставишь его ему в целости и сохранности.$b$bПередай ему письмо и знай, что лес будет охранять тебя по дороге в каменные джунгли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте отчет Древа-оракула верховному друиду Фэндралу Оленьему Шлему в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я-то думал, почему Древо-оракул так долго не связывается со мной... Сдается мне, что как только мы решаем одну проблему, немедленно возникает другая, еще более сложная.$b$bБоюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернем себе бессмертие. $b$bТем не менее, ты славно $Gсправился:справилась; с заданием Древа-оракула, и за усердие тебе положена награда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хм-м... В тебе силен дух леса, |3-6($c). Что у тебя за дело к верховному друиду калдорай?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (941,'Сердце-семя','Я удалил этот смрадный мох с сердца, но оно все еще остается запятнанным...$B$BПопытайся посадить его в мою кадку. Она наполнена плодородной землей, которая может очистить и исцелить это сердце.','Посадите запятнанное сердце в кадку Деналана.','Вы сажаете сердце в кадку, и оно быстро в нее зарывается!\n\nЧерез несколько секунд оно снова выкапывается из земли – уже очищенное. Оно тихонько пульсирует... и вам хочется взять его в руки.','Кадка полна земли, специально подготовленной Деналаном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце-семя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я удалил этот смрадный мох с сердца, но оно все еще остается запятнанным...$B$BПопытайся посадить его в мою кадку. Она наполнена плодородной землей, которая может очистить и исцелить это сердце.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите запятнанное сердце в кадку Деналана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы сажаете сердце в кадку, и оно быстро в нее зарывается!\n\nЧерез несколько секунд оно снова выкапывается из земли – уже очищенное. Оно тихонько пульсирует... и вам хочется взять его в руки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кадка полна земли, специально подготовленной Деналаном.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (942,'Рассеянный геолог','"Эта окаменелость поразительно похожа на другую, которую я однажды видел в Стальгорне. Геолог по имени Бутылопуз приносил ее на ежегодную конференцию Лиги исследователей. Он был уверен, что в этой окаменелости скрыта мощь, которую можно каким-то образом высвободить.$b$bПоследнее, что я слышал, что Бутылопуз обосновался в таверне "Большая вода" и ждет, чтобы его сопроводили к раскопу Вельгара. Найдите его и покажите ему окаменелость, найденную Сомнамбулером. Может быть, он сумеет раскрыть секреты прошлого.','Отвезите таинственную окаменелость археологу Бутылопузу в Гавань Менетилов.','О боги! Так вы говорите, эта вещь происходит из далеких земель Калимдора?$B$BПоразительно! Просто поразительно!','Что это там у вас, дружище?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассеянный геолог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Эта окаменелость поразительно похожа на другую, которую я однажды видел в Стальгорне. Геолог по имени Бутылопуз приносил ее на ежегодную конференцию Лиги исследователей. Он был уверен, что в этой окаменелости скрыта мощь, которую можно каким-то образом высвободить.$b$bПоследнее, что я слышал, что Бутылопуз обосновался в таверне "Большая вода" и ждет, чтобы его сопроводили к раскопу Вельгара. Найдите его и покажите ему окаменелость, найденную Сомнамбулером. Может быть, он сумеет раскрыть секреты прошлого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отвезите таинственную окаменелость археологу Бутылопузу в Гавань Менетилов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О боги! Так вы говорите, эта вещь происходит из далеких земель Калимдора?$B$BПоразительно! Просто поразительно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это там у вас, дружище?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (943,'Рассеянный геолог','Геолог Вельгар, который сейчас находится на раскопе в Болотине, держит окаменелость у себя. Когда я обнаружил камень Релу, то был уверен, что это ключ к тайне окаменелости.$b$bПока я шел по дороге к Вельгару, на меня напали ящеры, и реликвия пропала. Не знаю, какая из крапчатых тварей проглотила ее, но если вам удастся ее вернуть, я смогу высвободить силу этих артефактов.$b$bПринесите мне и камень Релу, и окаменелость, хранящуюся у Вельгара.','Археолог Бутылопуз в Гавани Менетилов хочет, чтобы вы принесли ему камень Релу и окаменелость Бутылопуза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассеянный геолог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Геолог Вельгар, который сейчас находится на раскопе в Болотине, держит окаменелость у себя. Когда я обнаружил камень Релу, то был уверен, что это ключ к тайне окаменелости.$b$bПока я шел по дороге к Вельгару, на меня напали ящеры, и реликвия пропала. Не знаю, какая из крапчатых тварей проглотила ее, но если вам удастся ее вернуть, я смогу высвободить силу этих артефактов.$b$bПринесите мне и камень Релу, и окаменелость, хранящуюся у Вельгара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Археолог Бутылопуз в Гавани Менетилов хочет, чтобы вы принесли ему камень Релу и окаменелость Бутылопуза.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (944,'Меч Властителя','Очень странно, что наги появились здесь, на Темных берегах. Но еще страннее – клан Сумеречного Молота. Они поклоняются старым, очень старым богам этой земли. Богам, давным-давно низвергнутым.$b$bМеч Властителя, что к югу отсюда, – место, где пал один из этих древних богов.$b$bПойди туда и поищи других служителей культа Сумеречного Молота.$b$bВозьми этот фиал виденья. Используй его для создания гадальной чаши, когда разведаешь все у Меча Властителя. Посредством этой чаши поговори со мной.','Соберите информацию, а затем используйте фиал виденья для создания гадальной чаши. С помощью чаши поговорите с Ону.','Так ты $Gобнаружил:обнаружила; клан Сумеречного Молота у Меча Властителя?$B$BПлохо.$B$BДревний бог, пронзенный мечом, давно мертв, но это не значит, что исчезли и остатки его могущества.$B$BДолжно быть, клан Сумеречного Молота пытается найти его силу.','Меч Властителя, $N.$B$BОтправляйся туда, а потом снова свяжись со мной.','Отправляйтесь в Меч Властителя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меч Властителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Очень странно, что наги появились здесь, на Темных берегах. Но еще страннее – клан Сумеречного Молота. Они поклоняются старым, очень старым богам этой земли. Богам, давным-давно низвергнутым.$b$bМеч Властителя, что к югу отсюда, – место, где пал один из этих древних богов.$b$bПойди туда и поищи других служителей культа Сумеречного Молота.$b$bВозьми этот фиал виденья. Используй его для создания гадальной чаши, когда разведаешь все у Меча Властителя. Посредством этой чаши поговори со мной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите информацию, а затем используйте фиал виденья для создания гадальной чаши. С помощью чаши поговорите с Ону.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ты $Gобнаружил:обнаружила; клан Сумеречного Молота у Меча Властителя?$B$BПлохо.$B$BДревний бог, пронзенный мечом, давно мертв, но это не значит, что исчезли и остатки его могущества.$B$BДолжно быть, клан Сумеречного Молота пытается найти его силу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Меч Властителя, $N.$B$BОтправляйся туда, а потом снова свяжись со мной.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправляйтесь в Меч Властителя.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (945,'Спасение Терилун','Помогите!$b$bЯ бродила у Меча Властителя, как вдруг меня окружили эти жуткие сектанты. Счастье, что я умею отлично прятаться!!!$b$bМожете помочь мне отсюда выбраться? И еще, мне нужно будет сообщить моей сестре Тересиль, что я в порядке. Она в Ясеневом лесу, к югу отсюда, у святилища Эссины.','Помогите Терилун спастись, а потом сообщите Тересиль у святилища Эссины, что ее сестра в безопасности.','Моя сестра была – где? Терилун любит бродить по всяким местам, но все-таки! Это же очень далеко, да и Меч Властителя – вовсе не безопасное место...$B$BНу, спасибо вам, $n. С вашей стороны было очень любезно сообщить мне, что с ней все в порядке.','Помогите Терилун спастись из Меча Властителя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Терилун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помогите!$b$bЯ бродила у Меча Властителя, как вдруг меня окружили эти жуткие сектанты. Счастье, что я умею отлично прятаться!!!$b$bМожете помочь мне отсюда выбраться? И еще, мне нужно будет сообщить моей сестре Тересиль, что я в порядке. Она в Ясеневом лесу, к югу отсюда, у святилища Эссины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Терилун спастись, а потом сообщите Тересиль у святилища Эссины, что ее сестра в безопасности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моя сестра была – где? Терилун любит бродить по всяким местам, но все-таки! Это же очень далеко, да и Меч Властителя – вовсе не безопасное место...$B$BНу, спасибо вам, $n. С вашей стороны было очень любезно сообщить мне, что с ней все в порядке.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помогите Терилун спастись из Меча Властителя.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (946,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (947,'Пещерные грибы','Я тут составляю одно зелье, для которого нужны редкие грибы, растущие в одной-единственной пещере. Пещера эта находится за водопадом Скалистый, к востоку и чуть севернее в горах.$b$bЯ бы и сам туда пошел, но в Роще Древних мне порекомендовали держаться подальше от того места. Наши почтенные союзники чувствуют, что в этой пещере таится какое-то незнакомое зло.$b$bПрошу вас, $n, соберите для меня эти грибы. А в процессе заодно приглядитесь: может быть, вы сможете подтвердить опасения Дерев.','Принесите 5 ножек струпника и 1 мертвянку Баритасу Лунному Сумраку в Аубердин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пещерные грибы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тут составляю одно зелье, для которого нужны редкие грибы, растущие в одной-единственной пещере. Пещера эта находится за водопадом Скалистый, к востоку и чуть севернее в горах.$b$bЯ бы и сам туда пошел, но в Роще Древних мне порекомендовали держаться подальше от того места. Наши почтенные союзники чувствуют, что в этой пещере таится какое-то незнакомое зло.$b$bПрошу вас, $n, соберите для меня эти грибы. А в процессе заодно приглядитесь: может быть, вы сможете подтвердить опасения Дерев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 ножек струпника и 1 мертвянку Баритасу Лунному Сумраку в Аубердин.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (948,'Ону','Ону, древо мудрости из Рощи Древних, знает о вашем путешествии к Скалистому водопаду и хочет поговорить с вами. Роща расположена к югу отсюда, у подножья гор.$b$bДрева терпеливы и мудры, $n. Но если Ону ищет вашего совета касательно того, что вы видели у водопадов, то, боюсь, дело срочное.','Поговорите с Ону в Роще Древних.','$N. Ты здесь.$B$BХорошо.$B$BНам есть... что обсудить. Тебе и мне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ону',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ону, древо мудрости из Рощи Древних, знает о вашем путешествии к Скалистому водопаду и хочет поговорить с вами. Роща расположена к югу отсюда, у подножья гор.$b$bДрева терпеливы и мудры, $n. Но если Ону ищет вашего совета касательно того, что вы видели у водопадов, то, боюсь, дело срочное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ону в Роще Древних.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N. Ты здесь.$B$BХорошо.$B$BНам есть... что обсудить. Тебе и мне.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (949,'Лагерь Сумеречного Молота','Что замышляет клан Сумеречного Молота у Меча Властителя, неизвестно. Но наверняка что-то недоброе$B$BОбыщите их лагерь у Меча Властителя... Ищите то, что может помочь нам понять их намерения.$b$bВедь мы должны узнать об их целях раньше, чем они выработают план действий.','Найдите подсказку в лагере клана Сумеречного Молота, расположенном у Меча Властителя.','Книга написана от руки на древнем языке и прекрасно иллюстрирована.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что замышляет клан Сумеречного Молота у Меча Властителя, неизвестно. Но наверняка что-то недоброе$B$BОбыщите их лагерь у Меча Властителя... Ищите то, что может помочь нам понять их намерения.$b$bВедь мы должны узнать об их целях раньше, чем они выработают план действий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите подсказку в лагере клана Сумеречного Молота, расположенном у Меча Властителя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Книга написана от руки на древнем языке и прекрасно иллюстрирована.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (950,'Возвращение к Ону','Вглядываясь в сумеречный фолиант, можно сойти с ума. Буквы начинают плыть и плясать перед глазами даже после мельком брошенного взгляда, и некогда прекрасный орнамент принимает гротескные формы.$b$bВырвать одну страницу с безумными каракулями – вот и все, что вам удается сделать, пока вы не потеряли сознание.','Принесите Ону лист с безумными письменами.','Хаотичная, первобытная магия окружает этот пергамент с письменами. Я чувствую, что над ним потрудились древние силы.$B$BБудем надеяться, мы сумеем раскрыть цель деятельности клана Сумеречного Молота на Темном Берегу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Ону',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вглядываясь в сумеречный фолиант, можно сойти с ума. Буквы начинают плыть и плясать перед глазами даже после мельком брошенного взгляда, и некогда прекрасный орнамент принимает гротескные формы.$b$bВырвать одну страницу с безумными каракулями – вот и все, что вам удается сделать, пока вы не потеряли сознание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ону лист с безумными письменами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хаотичная, первобытная магия окружает этот пергамент с письменами. Я чувствую, что над ним потрудились древние силы.$B$BБудем надеяться, мы сумеем раскрыть цель деятельности клана Сумеречного Молота на Темном Берегу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (951,'Реликвии Матистры','Пергамент, который ты $Gобнаружил:обнаружила; близ Меча Властителя, – страница древнего текста... написанная эльфами! Она отягощена проклятиями и загрязнена скверной клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев.$b$bНаправляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии. Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов.','Принесите Ону в Рощу Древних 6 реликвий Матистры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвии Матистры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пергамент, который ты $Gобнаружил:обнаружила; близ Меча Властителя, – страница древнего текста... написанная эльфами! Она отягощена проклятиями и загрязнена скверной клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев.$b$bНаправляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии. Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ону в Рощу Древних 6 реликвий Матистры.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (952,'Роща Древних','Если уж у тебя нашлось время передать письмо для древа-оракула, то, мне кажется, для тебя не составит труда отнести донесение в Рощу Древних на Темные берега, прямо к югу от Аубердина.$b$bТы наверняка сможешь свободно добраться туда на гиппогрифе, я уверен, что ты сумеешь это сделать. Отнеси это Ону, древу мудрости. Он ждет от меня вести точно так же, как я ждал вести с Поляны Оракула.','Доставьте письмо Фэндрала Ону в Рощу Древних на Темные берега к югу от Аубердина.','А. $C. Чем может тебе помочь Ону?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Роща Древних',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если уж у тебя нашлось время передать письмо для древа-оракула, то, мне кажется, для тебя не составит труда отнести донесение в Рощу Древних на Темные берега, прямо к югу от Аубердина.$b$bТы наверняка сможешь свободно добраться туда на гиппогрифе, я уверен, что ты сумеешь это сделать. Отнеси это Ону, древу мудрости. Он ждет от меня вести точно так же, как я ждал вести с Поляны Оракула.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте письмо Фэндрала Ону в Рощу Древних на Темные берега к югу от Аубердина.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А. $C. Чем может тебе помочь Ону?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (953,'Падение Амет\'Арана','К востоку отсюда находятся руины Амет\'Арана. Сейчас их населяют неупокоенные духи высокорожденных, некогда живших в его стенах, но когда-то Амет\'Аран был местом, где слуги Азшары свободно практиковались в своей могучей магии.$b$bМеня послали исследовать эти руины, и я наткнулась на две большие таблички, на которых была неразборчиво начертана история Амет\'Арана и его падения. Пока я пыталась прочесть руны, на меня напали призраки, и я сбежала.$b$bПожалуйста, если можете, отправляйтесь в руины и расшифруйте таблички вместо меня.','Изучите таблички, рассказывающие об Амет\'Аране и его падении, а затем возвращайтесь к часовому Тише Лунный Клинок, находящейся на Темных берегах.','Когда вы изучите таблички и узнаете о падении Амет\'Арана, я пойду с этой информацией в Аубердин и сообщу Кругу Древних.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Амет\'Арана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К востоку отсюда находятся руины Амет\'Арана. Сейчас их населяют неупокоенные духи высокорожденных, некогда живших в его стенах, но когда-то Амет\'Аран был местом, где слуги Азшары свободно практиковались в своей могучей магии.$b$bМеня послали исследовать эти руины, и я наткнулась на две большие таблички, на которых была неразборчиво начертана история Амет\'Арана и его падения. Пока я пыталась прочесть руны, на меня напали призраки, и я сбежала.$b$bПожалуйста, если можете, отправляйтесь в руины и расшифруйте таблички вместо меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите таблички, рассказывающие об Амет\'Аране и его падении, а затем возвращайтесь к часовому Тише Лунный Клинок, находящейся на Темных берегах.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда вы изучите таблички и узнаете о падении Амет\'Арана, я пойду с этой информацией в Аубердин и сообщу Кругу Древних.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (954,'Башал\'Аран','Руины Башал\'Арана, расположенные к востоку отсюда, населены демоническими служителями зла. Злые духи и сатиры, обосновавшиеся там, питаются магическими энергиями Башал\'Арана, и силы их растут от постоянной подпитки энергией.$b$bНо при этом я заметил, что к одному святилищу они не приближаются. На западной стороне руин, на вершине небольшого утеса, распространяется странное синее свечение... Там и должно быть объяснение нежеланию демонов приближаться к этому месту.$b$bЯ хотел бы, чтобы вы его исследовали.','Найдите источник странного синего свечения в руинах Башал\'Арана.','Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезная |3-6($R)? На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение...\n\nНо, прошу вас, пусть мой грубый язык не заставит вас уйти. Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания.','Эти морские твари только недавно стали приплывать на отмели Темных берегов в таких тревожно больших количествах. Не могу сказать точно, но думаю, что это своего рода дурное предзнаменование. Извлечение образцов костей такой твари, что лежит к югу отсюда, поможет нам в Дарнасе оценить ситуацию!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башал\'Аран',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Руины Башал\'Арана, расположенные к востоку отсюда, населены демоническими служителями зла. Злые духи и сатиры, обосновавшиеся там, питаются магическими энергиями Башал\'Арана, и силы их растут от постоянной подпитки энергией.$b$bНо при этом я заметил, что к одному святилищу они не приближаются. На западной стороне руин, на вершине небольшого утеса, распространяется странное синее свечение... Там и должно быть объяснение нежеланию демонов приближаться к этому месту.$b$bЯ хотел бы, чтобы вы его исследовали.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите источник странного синего свечения в руинах Башал\'Арана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезная |3-6($R)? На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение...\n\nНо, прошу вас, пусть мой грубый язык не заставит вас уйти. Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти морские твари только недавно стали приплывать на отмели Темных берегов в таких тревожно больших количествах. Не могу сказать точно, но думаю, что это своего рода дурное предзнаменование. Извлечение образцов костей такой твари, что лежит к югу отсюда, поможет нам в Дарнасе оценить ситуацию!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (955,'Башал\'Аран','Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения. Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук.$b$bХотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты $gпомог:помогла; мне найти то, что держит меня здесь. Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на ее след.','Соберите 8 сережек греллей для Астериона в Башал\'Аране.','И правда... Грелли Башал\'Арана не владеют тем, что я ищу... Однако недавно они были в контакте с этим. Недавно... Я имею в виду по меркам твоего времени, не моего. Для меня "недавно" простирается глубоко в прошлое, почти что в другую эру...','Когда я получу серьги, я применю заклинание, чтобы обнаружить местонахождение связывающей меня печати. Веками я мечтал о свободе, которую принесло бы мне разрушение печати... Быть может, эти века таким грузом лежат на моем разуме, что я уже никогда не приду в себя...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башал\'Аран',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения. Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук.$b$bХотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты $gпомог:помогла; мне найти то, что держит меня здесь. Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на ее след.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 сережек греллей для Астериона в Башал\'Аране.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И правда... Грелли Башал\'Арана не владеют тем, что я ищу... Однако недавно они были в контакте с этим. Недавно... Я имею в виду по меркам твоего времени, не моего. Для меня "недавно" простирается глубоко в прошлое, почти что в другую эру...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда я получу серьги, я применю заклинание, чтобы обнаружить местонахождение связывающей меня печати. Веками я мечтал о свободе, которую принесло бы мне разрушение печати... Быть может, эти века таким грузом лежат на моем разуме, что я уже никогда не приду в себя...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (956,'Башал\'Аран','Если грелли вступали в тесный контакт с той силой, что запечатывает мою вечную тюрьму, то, подозреваю, я знаю, в чем дело. Несомнено эта печать находится во владении сатира, предводительствующего ими.$B$BЯ убежден, что моя догадка верна, $n. Она наверняка у одного из сатиров. Если ты сможешь ее добыть, то ты почти откроешь дверь моей темницы. Мне не сдержать слез...','Добудьте древнюю печать из лунного камня и принесите ее Астериону в Башал\'Аран.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башал\'Аран',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если грелли вступали в тесный контакт с той силой, что запечатывает мою вечную тюрьму, то, подозреваю, я знаю, в чем дело. Несомнено эта печать находится во владении сатира, предводительствующего ими.$B$BЯ убежден, что моя догадка верна, $n. Она наверняка у одного из сатиров. Если ты сможешь ее добыть, то ты почти откроешь дверь моей темницы. Мне не сдержать слез...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте древнюю печать из лунного камня и принесите ее Астериону в Башал\'Аран.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (957,'Башал\'Аран','Эта печать, заточившая меня, некогда была изготовлена руками одного из самых могущественных высокорожденных. В Амет\'Аране – точно таких же руинах к югу отсюда – до сих пор горит древнее синее пламя. В этом огне печать может быть уничтожена.$b$bБудь осторожнее в тех руинах, $n...','Уничтожьте древнюю печать из лунного камня у древнего пламени в Амет\'Аране, затем вернитесь к Астериону в Башал\'Аран.','По правде говоря, $n, я боюсь... Боюсь, что твой приход – и все это – лишь плод моего воспаленного воображения. Можешь ли ты понять, какая это мука? Я... Пожалуйста, ступай скорее.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башал\'Аран',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта печать, заточившая меня, некогда была изготовлена руками одного из самых могущественных высокорожденных. В Амет\'Аране – точно таких же руинах к югу отсюда – до сих пор горит древнее синее пламя. В этом огне печать может быть уничтожена.$b$bБудь осторожнее в тех руинах, $n...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте древнюю печать из лунного камня у древнего пламени в Амет\'Аране, затем вернитесь к Астериону в Башал\'Аран.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','По правде говоря, $n, я боюсь... Боюсь, что твой приход – и все это – лишь плод моего воспаленного воображения. Можешь ли ты понять, какая это мука? Я... Пожалуйста, ступай скорее.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (958,'Инструменты высокорожденных','$C. Вот задание, которое я вам поручаю.$b$bВидели ли вы руины Амет\'Арана? Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда. Когда-то Амет\'Аран служил домом для многих могущественных высокорожденных, а теперь это – памятник разрушению, совершенному их жалкими подражателями.$b$bМне говорили часовые, что духи высокорожденных по-прежнему обитают там и что они используют свои древние магические приспособления. Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить.','Добудьте 7 реликвий высокорожденных для Тандриса Ветропряда в Аубердине.','Хотя это, безусловно, лишь игра моего воображения, я чувствую себя так, будто бы ощущаю в этих реликвиях ядовитое дыхание магии высокорожденных. Я их уничтожу, чтобы давно уснувшее зло больше никогда не пробудилось.','Если бы инструменты их гибели были разрушены во время катаклизма, уничтожевшего наш мир... Тем не менее мы должны сделать все возможное, чтобы ужасы нашего прошлого не повторились в будущем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Инструменты высокорожденных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C. Вот задание, которое я вам поручаю.$b$bВидели ли вы руины Амет\'Арана? Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда. Когда-то Амет\'Аран служил домом для многих могущественных высокорожденных, а теперь это – памятник разрушению, совершенному их жалкими подражателями.$b$bМне говорили часовые, что духи высокорожденных по-прежнему обитают там и что они используют свои древние магические приспособления. Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 7 реликвий высокорожденных для Тандриса Ветропряда в Аубердине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хотя это, безусловно, лишь игра моего воображения, я чувствую себя так, будто бы ощущаю в этих реликвиях ядовитое дыхание магии высокорожденных. Я их уничтожу, чтобы давно уснувшее зло больше никогда не пробудилось.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если бы инструменты их гибели были разрушены во время катаклизма, уничтожевшего наш мир... Тем не менее мы должны сделать все возможное, чтобы ужасы нашего прошлого не повторились в будущем.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (959,'Неприятности в порту','Ой! $b$bКак видишь, у меня сегодня приключилась неприятность! Утром из Пиратской Бухты пришла поставка. И какая! Никогда не видел столько ящиков. Я хотел побыстрее закончить, поэтому поднимал больше, чем следовало. В конце концов все рухнуло на землю.$B$BНе успел я оглянуться, как эта тварь, Безумный Магглиш, схватил бутылку портвейна 99-летней выдержки и бросился наутек. Я гнался за ним до самых Пещер Стенаний, но внутрь я не ходок.$B$BМожет, тебе хватит пороху, чтобы найти его?','Оператор крана Биггльфузз из Кабестана попросил вас отнять бутылку портвейна 99-летней выдержки у Безумного Магглиша, который прячется в Пещерах Стенаний.','Портовый начальник не дает мне покоя с тех пор, как Безумный Магглиш скрылся с этой бутылкой. Судя по всему, портвейн предназначался в подарок Газлоу самим бароном Ревилгазом. \n\nЕсли у тебя довольно смелости и терпения для поисков Безумного Магглиша и похищенного портвейна, я щедро награжу тебя.','Вернитесь к оператору крана Биггльфуззу в Кабестан, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприятности в порту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ой! $b$bКак видишь, у меня сегодня приключилась неприятность! Утром из Пиратской Бухты пришла поставка. И какая! Никогда не видел столько ящиков. Я хотел побыстрее закончить, поэтому поднимал больше, чем следовало. В конце концов все рухнуло на землю.$B$BНе успел я оглянуться, как эта тварь, Безумный Магглиш, схватил бутылку портвейна 99-летней выдержки и бросился наутек. Я гнался за ним до самых Пещер Стенаний, но внутрь я не ходок.$B$BМожет, тебе хватит пороху, чтобы найти его?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оператор крана Биггльфузз из Кабестана попросил вас отнять бутылку портвейна 99-летней выдержки у Безумного Магглиша, который прячется в Пещерах Стенаний.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Портовый начальник не дает мне покоя с тех пор, как Безумный Магглиш скрылся с этой бутылкой. Судя по всему, портвейн предназначался в подарок Газлоу самим бароном Ревилгазом. \n\nЕсли у тебя довольно смелости и терпения для поисков Безумного Магглиша и похищенного портвейна, я щедро награжу тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оператору крана Биггльфуззу в Кабестан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (960,'Размышление Ону') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Размышление Ону',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (961,'Размышление Ону','Обнаружение культистов клана Сумеречного Молота беспокоит меня. Я должен поразмыслить об их намерениях...$B$BКогда у тебя будет больше информации, поговори со мной посредством гадальной чаши. Если тебе для создания чаши нужен фиал виденья, то... у меня есть еще.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Размышление Ону',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Обнаружение культистов клана Сумеречного Молота беспокоит меня. Я должен поразмыслить об их намерениях...$B$BКогда у тебя будет больше информации, поговори со мной посредством гадальной чаши. Если тебе для создания чаши нужен фиал виденья, то... у меня есть еще.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (962,'Змеецвет','Королевское фармацевтическое общество из великого Подгорода Лордерона направило меня сюда с очень необычной целью, $n. Возможно, вы сумеете помочь мне, а, стало быть, и Темной Госпоже в трудах на благо Отрекшихся.$b$bНе так давно я изучала редкий образец флоры под названием змеецвет. Я уверена, что в большом количестве это растение таит в себе великие возможности.$b$bУвы, змеецвет можно найти только в самых темных закоулках Пещер Стенаний, опасной системе подземелий в Степях.','Аптекарь Зама из Громового Утеса просит вас принести ей 10 змеецветов.','Мне очень надеюсь, что вам удастся добыть достаточно змеецвета в Пещерах Стенаний. Я многих туда посылала, но никто не вернулся.','Вернитесь к аптекарю Заме в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Змеецвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Королевское фармацевтическое общество из великого Подгорода Лордерона направило меня сюда с очень необычной целью, $n. Возможно, вы сумеете помочь мне, а, стало быть, и Темной Госпоже в трудах на благо Отрекшихся.$b$bНе так давно я изучала редкий образец флоры под названием змеецвет. Я уверена, что в большом количестве это растение таит в себе великие возможности.$b$bУвы, змеецвет можно найти только в самых темных закоулках Пещер Стенаний, опасной системе подземелий в Степях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аптекарь Зама из Громового Утеса просит вас принести ей 10 змеецветов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне очень надеюсь, что вам удастся добыть достаточно змеецвета в Пещерах Стенаний. Я многих туда посылала, но никто не вернулся.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Заме в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (963,'Во имя вечной любви','После битв за Источник Вечности я узнал, что Амет\'Аран разрушен, жители его погибли – в том числе и моя возлюбленная Анайя.$b$bЯ никогда не думал, что и через тысячи лет воспоминания об Анайе будут тревожить мои сны. Бродя в помрачении рассудка по лесам на Темных берегах, я очутился в руинах Амет\'Арана... где и увидел неупокоенный дух моей любимой.$b$bЕе нужно освободить, но у меня просто рука не поднимается. Нужно уничтожить ее призрак.','Освободите дух Анайи Вестницы Зари и принесите ее подвеску Кириллиану Белому Когтю в Аубердин.','Благодарю тебя, $n. Может быть, было бы лучше... если бы я сам это сделал. Но даже после прошедших тысячелетий у меня нет сил поднять руку на свою возлюбленную.$B$BПожалуйста, оставь меня наедине с моим горем...','С неизбывной печалью в сердце я последовал за Шан\'до Яростью Бури в долгий сон, и взял свою боль с собой в сны, и спал на протяжении тысячелетий.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во имя вечной любви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После битв за Источник Вечности я узнал, что Амет\'Аран разрушен, жители его погибли – в том числе и моя возлюбленная Анайя.$b$bЯ никогда не думал, что и через тысячи лет воспоминания об Анайе будут тревожить мои сны. Бродя в помрачении рассудка по лесам на Темных берегах, я очутился в руинах Амет\'Арана... где и увидел неупокоенный дух моей любимой.$b$bЕе нужно освободить, но у меня просто рука не поднимается. Нужно уничтожить ее призрак.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите дух Анайи Вестницы Зари и принесите ее подвеску Кириллиану Белому Когтю в Аубердин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, $n. Может быть, было бы лучше... если бы я сам это сделал. Но даже после прошедших тысячелетий у меня нет сил поднять руку на свою возлюбленную.$B$BПожалуйста, оставь меня наедине с моим горем...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С неизбывной печалью в сердце я последовал за Шан\'до Яростью Бури в долгий сон, и взял свою боль с собой в сны, и спал на протяжении тысячелетий.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (964,'Фрагменты скелетов','Чтобы отомкнуть двери Некроситета необходим Костяной ключ. Его делают из остатков скелета – точнее, нескольких скелетов – и вплавляют в прочнейший из металлов в подходящей форме. Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой.$b$bНо не будем отвлекаться, для начала нам понадобятся фрагменты скелетов. Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи.','Принесите 15 фрагментов скелетов аптекарю Дитерсу в Бастион в Западных Чумных землях.','Отличные образцы! Теперь моя очередь – я закалю их особым образом, чтобы они смогли вынести процесс отковки, через который им придется рано или поздно пройти.$B$BТеперь придется отыскать подходящую форму для отливки. Я знаю одного гоблина-кузнеца из Танариса, который в прошлом делал формы для не менее жутких вещей. Его девиз – как у всех гоблинов – кто платит, тот и музыку заказывает.','Убивай больше и чаще, $C. Нам понадобится солидный запас фрагментов скелетов для создания внешнего слоя ключа. Его же не зря называли Костяным ключом.','Вернитесь к аптекарю Дитерсу в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фрагменты скелетов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы отомкнуть двери Некроситета необходим Костяной ключ. Его делают из остатков скелета – точнее, нескольких скелетов – и вплавляют в прочнейший из металлов в подходящей форме. Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой.$b$bНо не будем отвлекаться, для начала нам понадобятся фрагменты скелетов. Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 15 фрагментов скелетов аптекарю Дитерсу в Бастион в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные образцы! Теперь моя очередь – я закалю их особым образом, чтобы они смогли вынести процесс отковки, через который им придется рано или поздно пройти.$B$BТеперь придется отыскать подходящую форму для отливки. Я знаю одного гоблина-кузнеца из Танариса, который в прошлом делал формы для не менее жутких вещей. Его девиз – как у всех гоблинов – кто платит, тот и музыку заказывает.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Убивай больше и чаще, $C. Нам понадобится солидный запас фрагментов скелетов для создания внешнего слоя ключа. Его же не зря называли Костяным ключом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Дитерсу в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (965,'Башня Алталакса','Привет тебе, $gюный:юная:r; |3-6($r). Меня зовут Элисса Звездный Ветер, и моя задача – защищать Аубердин от всякого вреда.$b$bС этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда.$b$bНо он уже давно должен был вернуться. Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью. Я была бы тебе очень благодарна, если бы ты $gсмог:смогла; найти его и удостовериться, что с ним все в порядке.','Найдите Балтула Удар Тени возле башни Алталакса на Темных берегах.','Тебя прислала Элисса? Это хорошо. У меня есть для нее тревожные вести, но не было возможности передать их ей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башня Алталакса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $gюный:юная:r; |3-6($r). Меня зовут Элисса Звездный Ветер, и моя задача – защищать Аубердин от всякого вреда.$b$bС этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда.$b$bНо он уже давно должен был вернуться. Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью. Я была бы тебе очень благодарна, если бы ты $gсмог:смогла; найти его и удостовериться, что с ним все в порядке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Балтула Удар Тени возле башни Алталакса на Темных берегах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислала Элисса? Это хорошо. У меня есть для нее тревожные вести, но не было возможности передать их ей.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (966,'Башня Алталакса','Группа чернокнижников обосновалась вокруг и внутри башни. Я хотел было вернуться в Аубердин и доложить Элиссе раньше, но побоялся, что могу что-то пропустить, пока буду отсутствовать.$b$bДелгрен подозревал, что подобная компания может собираться у башни, но не знал, зачем.$b$bНесколько обрывков свитков пергамента, которые носят с собой чернокнижники, попали в мои руки, но мне нужно знать больше, чтобы разгадать эту головоломку. Однако я предостерегаю вас от попытки вторгнуться в саму башню: чернокнижники, засевшие там, гораздо сильнее!','Соберите 4 свитка истрепанного пергамента для Балтула Удара Тени возле башни Алталакса.','Большое спасибо, $n. Это должно пролить некоторый свет на то, чем занимается это сборище чернокнижников...$B$BХмм... Клан Темной Нити... Никогда раньше не слышал о такой группе. Пока у нас нет никаких сведений об их истории, практически невозможно сказать, в чем могут заключаться их планы.$B$BБольше нельзя тянуть. Нужно немедленно предупредить Делгрена.','Нашли ли вы у них еще свитки? Я смогу составить более целостное представление об этом культе, если вы сможете их найти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башня Алталакса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Группа чернокнижников обосновалась вокруг и внутри башни. Я хотел было вернуться в Аубердин и доложить Элиссе раньше, но побоялся, что могу что-то пропустить, пока буду отсутствовать.$b$bДелгрен подозревал, что подобная компания может собираться у башни, но не знал, зачем.$b$bНесколько обрывков свитков пергамента, которые носят с собой чернокнижники, попали в мои руки, но мне нужно знать больше, чтобы разгадать эту головоломку. Однако я предостерегаю вас от попытки вторгнуться в саму башню: чернокнижники, засевшие там, гораздо сильнее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 свитка истрепанного пергамента для Балтула Удара Тени возле башни Алталакса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большое спасибо, $n. Это должно пролить некоторый свет на то, чем занимается это сборище чернокнижников...$B$BХмм... Клан Темной Нити... Никогда раньше не слышал о такой группе. Пока у нас нет никаких сведений об их истории, практически невозможно сказать, в чем могут заключаться их планы.$B$BБольше нельзя тянуть. Нужно немедленно предупредить Делгрена.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашли ли вы у них еще свитки? Я смогу составить более целостное представление об этом культе, если вы сможете их найти.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (967,'Башня Алталакса','Мой хозяин, Делгрен Очиститель – паладин, любезно предоставивший свою помощь в защите наших лесов от сил демонов и нежити. Он многое поведал мне о Божественном Свете и воинском искусстве.$b$bДелгрен должен немедленно узнать о деятельности клана.$b$bВы найдете его далеко на юге отсюда, на Заставе Мейстры в Ясеневом лесу. Поторопитесь – я боюсь, что угроза клана Темной Нити растет с каждым часом.','Доставьте письмо Балтула Делгрену Очистителю в Ясеневый лес.','Если позволите, я вам скажу: слишком уж вы хорошо экипированы для $Gпростого посланца:простой посланницы;, не так ли? Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадет мне в руки. Посмотрим, что он там пишет...$B$BДа, это тревожные новости. Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их.$B$BВначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников.','У вас ко мне какое-то дело, |3-6($c)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башня Алталакса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой хозяин, Делгрен Очиститель – паладин, любезно предоставивший свою помощь в защите наших лесов от сил демонов и нежити. Он многое поведал мне о Божественном Свете и воинском искусстве.$b$bДелгрен должен немедленно узнать о деятельности клана.$b$bВы найдете его далеко на юге отсюда, на Заставе Мейстры в Ясеневом лесу. Поторопитесь – я боюсь, что угроза клана Темной Нити растет с каждым часом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте письмо Балтула Делгрену Очистителю в Ясеневый лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если позволите, я вам скажу: слишком уж вы хорошо экипированы для $Gпростого посланца:простой посланницы;, не так ли? Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадет мне в руки. Посмотрим, что он там пишет...$B$BДа, это тревожные новости. Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их.$B$BВначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас ко мне какое-то дело, |3-6($c)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (968,'"Подземные Силы"','Хотя книга ужасно истрепана и исцарапана, ее название на обложке все же можно разобрать:$b$b"Подземные Силы".$b$bВ книге перечисляются непроизносимые имена со зловещими титулами, способами почитания и предпочтительными способами жертвоприношения... И среди этих жертвоприношений числятся живые разумные создания.$b$bНа внутренней стороне обложки написано: "Руны и Жребии Костохвата, Заброшенный грот, Стальгорн. Владелец: Геррик Костохват".$b$bЕсли Костохват торгует подобными книгами, может быть, он выкупит и эту?','Принесите книгу "Подземные Силы" Геррику Костохвату в Заброшенный грот в Стальгорне.','А, экземпляр "Подземных сил". Интересный текст, да уж. А кое-кто найдет его и полезным тоже...$B$BНо эта книга в ужасном состоянии. И поглядите-ка! Заметки на полях – почти на каждой странице!$B$BХм... Я помню этот экземпляр. Я продал его Болгару в прошлом году. Вы его... его $Gдруг:подруга;? Да, должно быть, так. У вас в глазах такой же огонь горит!$B$BНу, по определению, друг Болгара – мой друг. А мы должны поддерживать близких людей, правда?','Приветствую, $Gсударь:сударыня;.$B$BМогу ли я заинтересовать вас каким-то из моих фолиантов?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Подземные Силы"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя книга ужасно истрепана и исцарапана, ее название на обложке все же можно разобрать:$b$b"Подземные Силы".$b$bВ книге перечисляются непроизносимые имена со зловещими титулами, способами почитания и предпочтительными способами жертвоприношения... И среди этих жертвоприношений числятся живые разумные создания.$b$bНа внутренней стороне обложки написано: "Руны и Жребии Костохвата, Заброшенный грот, Стальгорн. Владелец: Геррик Костохват".$b$bЕсли Костохват торгует подобными книгами, может быть, он выкупит и эту?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книгу "Подземные Силы" Геррику Костохвату в Заброшенный грот в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, экземпляр "Подземных сил". Интересный текст, да уж. А кое-кто найдет его и полезным тоже...$B$BНо эта книга в ужасном состоянии. И поглядите-ка! Заметки на полях – почти на каждой странице!$B$BХм... Я помню этот экземпляр. Я продал его Болгару в прошлом году. Вы его... его $Gдруг:подруга;? Да, должно быть, так. У вас в глазах такой же огонь горит!$B$BНу, по определению, друг Болгара – мой друг. А мы должны поддерживать близких людей, правда?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $Gсударь:сударыня;.$B$BМогу ли я заинтересовать вас каким-то из моих фолиантов?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (969,'Да пребудет с тобой удача!','Ах, одного взгляда на тебя достаточно, чтобы сказать: ты захочешь себе талисман на удачу. Мау\'ари всегда все знает! $b$bНа юг пойди – найдешь ущелье, а в нем великанов, сделанных из кусков льда. Кристаллы можно отобрать у гигантов, но можешь собирать их и $gсам:сама; в ущелье. Эти кристаллы имеют отличную отражающую способность. $b$bПринеси мне 4 кристалла великанов Ледяного Молота, и я сделаю тебе такой талисман.','Соберите 4 кристалла великанов Ледяного Молота для знахарки Мау\'ари из Круговзора.','Вернитесь к знахарю Мау\'ари в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Да пребудет с тобой удача!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, одного взгляда на тебя достаточно, чтобы сказать: ты захочешь себе талисман на удачу. Мау\'ари всегда все знает! $b$bНа юг пойди – найдешь ущелье, а в нем великанов, сделанных из кусков льда. Кристаллы можно отобрать у гигантов, но можешь собирать их и $gсам:сама; в ущелье. Эти кристаллы имеют отличную отражающую способность. $b$bПринеси мне 4 кристалла великанов Ледяного Молота, и я сделаю тебе такой талисман.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 кристалла великанов Ледяного Молота для знахарки Мау\'ари из Круговзора.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Мау\'ари в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (970,'Башня Алталакса','Хмм, этот камень души наполнен какой-то темной магией. Давай-ка посмотрим, что у него внутри...','Ну, как, удалось добыть самоцвет души?','Вернитесь к Делгрену Очистителю на Заставу Мейстры, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башня Алталакса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм, этот камень души наполнен какой-то темной магией. Давай-ка посмотрим, что у него внутри...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как, удалось добыть самоцвет души?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делгрену Очистителю на Заставу Мейстры, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (971,'Знание в пучине','Насколько тебе известно, я собираю знания. Древние знания. Могучие знания. Знания, что отворяют пути, знания, что могут пробудить Тех-Что-Спят. Главное – правильно ими распорядиться.$B$BХодят слухи о старинном манускрипте Лоргалиса, будто бы он покоится в Непроглядной Пучине на западе. Некогда там жили наши предки, но они давно уже мертвы. Некогда это место было средоточием великого знания, ныне же город превратился в руины.$B$BНайди манускрипт в Непроглядной Пучине. Сделай это, и я не забуду твоей услуги. Даже после... скончания дней.','Принесите манускрипт Лоргалиса курсанту-часовому Иссаре в лагерь у Непроглядной Пучины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знание в пучине',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько тебе известно, я собираю знания. Древние знания. Могучие знания. Знания, что отворяют пути, знания, что могут пробудить Тех-Что-Спят. Главное – правильно ими распорядиться.$B$BХодят слухи о старинном манускрипте Лоргалиса, будто бы он покоится в Непроглядной Пучине на западе. Некогда там жили наши предки, но они давно уже мертвы. Некогда это место было средоточием великого знания, ныне же город превратился в руины.$B$BНайди манускрипт в Непроглядной Пучине. Сделай это, и я не забуду твоей услуги. Даже после... скончания дней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите манускрипт Лоргалиса курсанту-часовому Иссаре в лагерь у Непроглядной Пучины.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (972,'Сапта воды','Возьми сапту воды и отыщи оскверненную заводь в Серебряном бору. Я возлагаю на тебя большие надежды, Ахахаха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сапта воды',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возьми сапту воды и отыщи оскверненную заводь в Серебряном бору. Я возлагаю на тебя большие надежды, Ахахаха.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (973,'Башня Алталакса','Илкруд Магтрулл. Да, я знаю о нем. Это могучий орочий чернокнижник, который поселился в Святилище Огненной Расщелины, месте великого зла на юго-западе Ясеневого леса.$b$bДоныне он был не более чем досадной помехой, потому я и не трогал его, но, похоже, пришла пора с ним разобраться.','Принесите фолиант Илкруда Магтрулла Делгрену Очистителю на заставу Мейстры.','Ты сегодня $Gсвершил:свершила; великое дело, $n. Гордись – ты $Gсразил:сразила; могущественного чернокнижника.$b$bА теперь посмотрим, что мы можем узнать из записок Илкруда.','У тебя немного ошарашенный вид, $n. С тобой ничего не случилось?','Вернитесь к Делгрену Очистителю на Заставу Мейстры, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башня Алталакса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Илкруд Магтрулл. Да, я знаю о нем. Это могучий орочий чернокнижник, который поселился в Святилище Огненной Расщелины, месте великого зла на юго-западе Ясеневого леса.$b$bДоныне он был не более чем досадной помехой, потому я и не трогал его, но, похоже, пришла пора с ним разобраться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите фолиант Илкруда Магтрулла Делгрену Очистителю на заставу Мейстры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сегодня $Gсвершил:свершила; великое дело, $n. Гордись – ты $Gсразил:сразила; могущественного чернокнижника.$b$bА теперь посмотрим, что мы можем узнать из записок Илкруда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя немного ошарашенный вид, $n. С тобой ничего не случилось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делгрену Очистителю на Заставу Мейстры, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (974,'Найти источник','Эти горячие источники всегда были для меня загадкой! Откуда берется жар? $B$BЕсли учесть, что источники расположены совсем недалеко от Вулкана Огненного Венца, можно предположить, что их подогревает вулкан. Я разработал термометр, чтобы измерять температуру вулкана, и теперь хочу выяснить, в какой точке она наиболее высока. Термометр дает результаты по шкале Кракленгейта. $B$BВот, держи, отправляйся на хребет и выясни, где там точка с самой высокой температурой!','Выясните, где находится точка самой высокой температуры на Вулкане Огненного Венца, по просьбе Кракла из Кратера Ун\'Горо. $B$BДля измерения температуры щелкните по термометру правой кнопкой мыши. Проверяйте все горячие точки, пока не будет обнаружена точка с самой высокой температурой.','Да, корреляция температур вулкана и горячих источников очевидна. Конечно, надо бы еще раз проверить правильность уравнений, однако создается впечатление, что расстояние и температура... Хмм...','Я бы и сам пошел, но уж больно боюсь элементалей Огня!','Вернитесь к Краклу на Горячие источники Голакка, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти источник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти горячие источники всегда были для меня загадкой! Откуда берется жар? $B$BЕсли учесть, что источники расположены совсем недалеко от Вулкана Огненного Венца, можно предположить, что их подогревает вулкан. Я разработал термометр, чтобы измерять температуру вулкана, и теперь хочу выяснить, в какой точке она наиболее высока. Термометр дает результаты по шкале Кракленгейта. $B$BВот, держи, отправляйся на хребет и выясни, где там точка с самой высокой температурой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните, где находится точка самой высокой температуры на Вулкане Огненного Венца, по просьбе Кракла из Кратера Ун\'Горо. $B$BДля измерения температуры щелкните по термометру правой кнопкой мыши. Проверяйте все горячие точки, пока не будет обнаружена точка с самой высокой температурой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, корреляция температур вулкана и горячих источников очевидна. Конечно, надо бы еще раз проверить правильность уравнений, однако создается впечатление, что расстояние и температура... Хмм...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я бы и сам пошел, но уж больно боюсь элементалей Огня!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Краклу на Горячие источники Голакка, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (975,'Сокровище Мау\'ари','А теперь, прежде чем я дам тебе этот вот оберег, объясню, как им пользоваться. $b$bЕсли он у тебя с собой, окажется, что определенные предметы будут в добыче с тех созданий, с которыми ты бой вести будешь. А если нет, то и предметов не найдешь. Понятно? $b$bТы узнаешь их по имени – они называются э\'ко. Если найдешь такие – приноси Мау\'ари, она поможет тебе найти им применение. $b$bПостой-ка тут, пока я твой оберег доделаю.','Еще раз поговорите со знахаркой Мау\'ари через минуту, чтобы получить талисман на удачу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровище Мау\'ари',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь, прежде чем я дам тебе этот вот оберег, объясню, как им пользоваться. $b$bЕсли он у тебя с собой, окажется, что определенные предметы будут в добыче с тех созданий, с которыми ты бой вести будешь. А если нет, то и предметов не найдешь. Понятно? $b$bТы узнаешь их по имени – они называются э\'ко. Если найдешь такие – приноси Мау\'ари, она поможет тебе найти им применение. $b$bПостой-ка тут, пока я твой оберег доделаю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Еще раз поговорите со знахаркой Мау\'ари через минуту, чтобы получить талисман на удачу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (976,'Поставка для Аубердина','Делгрен попросил меня доставить письма и припасы часовому Звездный Ветер в Аубердин, но мне очень не хочется ехать в одиночку. В лесу опасные враги, а я не хочу, чтобы эти припасы и информация попали не в те руки.$b$bЕсли ты с остальными согласитесь охранять меня, то я смогу уехать прямо сейчас. Под вашей защитой я точно доставлю все это в Аубердин.','Поговорите с Делгреном Очистителем на заставе Мейстры после того, как проводите Фиро через Ясеневый лес.','Ты сегодня славно $Gпоработал:поработала;, |3-6($c). То, что мы отослали в Аубердин, срочно необходимо для отражения темной угрозы, наводнившей лес.$b$bПрими это вместе с моей сердечной благодарностью.','Часовым очень нужны припасы для подкрепления на Темных берегах.','Защитите Фиро Железнорука.','Вернитесь к Делгрену Очистителю на Заставу Мейстры, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поставка для Аубердина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Делгрен попросил меня доставить письма и припасы часовому Звездный Ветер в Аубердин, но мне очень не хочется ехать в одиночку. В лесу опасные враги, а я не хочу, чтобы эти припасы и информация попали не в те руки.$b$bЕсли ты с остальными согласитесь охранять меня, то я смогу уехать прямо сейчас. Под вашей защитой я точно доставлю все это в Аубердин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Делгреном Очистителем на заставе Мейстры после того, как проводите Фиро через Ясеневый лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сегодня славно $Gпоработал:поработала;, |3-6($c). То, что мы отослали в Аубердин, срочно необходимо для отражения темной угрозы, наводнившей лес.$b$bПрими это вместе с моей сердечной благодарностью.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Часовым очень нужны припасы для подкрепления на Темных берегах.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите Фиро Железнорука.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делгрену Очистителю на Заставу Мейстры, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (977,'Йети где-то рядом...','Теперь, когда мне есть чем прикрыть механические движущиеся части, мне нужна только одна вещь. Ну, точнее, две. Два рога! $b$bСамые большие рога – у патриархов и матриархов клана, так что, естественно, именно их-то я и хочу. Эта разновидность йети обитает в пещере к юго-востоку отсюда. Их там очень много, ты без труда их отыщешь. $b$bПомни, я хочу самые красивые рога – пожалуйста, не приноси ни побитых, ни сломанных!','Добудьте 2 безупречных рога йети для Уми Румпельшникер из Круговзора.','Вернитесь к Уми Румпельшникер в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Йети где-то рядом...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мне есть чем прикрыть механические движущиеся части, мне нужна только одна вещь. Ну, точнее, две. Два рога! $b$bСамые большие рога – у патриархов и матриархов клана, так что, естественно, именно их-то я и хочу. Эта разновидность йети обитает в пещере к юго-востоку отсюда. Их там очень много, ты без труда их отыщешь. $b$bПомни, я хочу самые красивые рога – пожалуйста, не приноси ни побитых, ни сломанных!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 2 безупречных рога йети для Уми Румпельшникер из Круговзора.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уми Румпельшникер в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (978,'Осененные луной дикие совухи','Перья диких совухов из Внутренних земель, кажется, содержат следы магии. Эти силы... непохоже, что создания способны их контролировать, больше похоже на то, что магия просто является частью их сущности. $b$bЗа время моих исследований я слыхал, что большая популяция дикосовухов населяет заснеженные земли Зимних Ключей. Вдруг у этих существ есть те же свойства? Пожалуйста, $n, помогите мне найти ответ. Отправляйтесь в Зимние Ключи, соберите выпавшие перья и возвращайтесь с ними ко мне.','Соберите в Зимних Ключах 10 осененных луной перьев и принесите их Эреласу Янтарному Небу в деревню Рут\'теран.','Теперь я могу сравнить перья между собой… Посмотрим-ка…','Вернитесь к Эреласу Янтарному Небу в деревню Рут\'теран, что в Тельдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осененные луной дикие совухи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перья диких совухов из Внутренних земель, кажется, содержат следы магии. Эти силы... непохоже, что создания способны их контролировать, больше похоже на то, что магия просто является частью их сущности. $b$bЗа время моих исследований я слыхал, что большая популяция дикосовухов населяет заснеженные земли Зимних Ключей. Вдруг у этих существ есть те же свойства? Пожалуйста, $n, помогите мне найти ответ. Отправляйтесь в Зимние Ключи, соберите выпавшие перья и возвращайтесь с ними ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите в Зимних Ключах 10 осененных луной перьев и принесите их Эреласу Янтарному Небу в деревню Рут\'теран.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь я могу сравнить перья между собой… Посмотрим-ка…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эреласу Янтарному Небу в деревню Рут\'теран, что в Тельдрассиле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (979,'В поисках Раншаллы','Да-да, на эти перья, похоже, наложены точно такие же чары, как и те, что я прежде заметил... Поскольку я совершенно не уверен в том, что именно мы нашли, я очень хочу, чтобы вы продолжили поиск ответов, $n. $b$bМоя коллега недавно отправилась в Зимние Ключи изучать там диких совухов в их естественной среде обитания. Может, вы нагоните ее и выясните, что ей удалось узнать?','Найдите Раншаллу в восточной части Зимних Ключей.','Привет! Вас прислал Эрелас?? Здорово, я как раз собиралась отправиться в пещеры, и я отнюдь не возражаю против компании.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Раншаллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да-да, на эти перья, похоже, наложены точно такие же чары, как и те, что я прежде заметил... Поскольку я совершенно не уверен в том, что именно мы нашли, я очень хочу, чтобы вы продолжили поиск ответов, $n. $b$bМоя коллега недавно отправилась в Зимние Ключи изучать там диких совухов в их естественной среде обитания. Может, вы нагоните ее и выясните, что ей удалось узнать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Раншаллу в восточной части Зимних Ключей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет! Вас прислал Эрелас?? Здорово, я как раз собиралась отправиться в пещеры, и я отнюдь не возражаю против компании.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (980,'Новые источники','Слыхал я, что существуют и другие горячие источники – в местечке Зимние Ключи, далеко к северу отсюда. И вот в чем загвоздка – в тех местах нет никаких вулканов! Очень любопытно... $B$BЧто ж, тут можно сделать лишь одно – отправиться в Зимние Ключи и поговорить с моей тамошней приятельницей. Ее зовут Донова Снегонора, она живет прямо рядом с источниками. $B$BНу, счастливой дороги! Еще раз спасибо за помощь с термометром.','Отправьтесь в Зимние Ключи и побеседуйте с Доновой Снегонорой.','Здравствуй, $n! Да, Кракл был совершенно прав...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые источники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слыхал я, что существуют и другие горячие источники – в местечке Зимние Ключи, далеко к северу отсюда. И вот в чем загвоздка – в тех местах нет никаких вулканов! Очень любопытно... $B$BЧто ж, тут можно сделать лишь одно – отправиться в Зимние Ключи и поговорить с моей тамошней приятельницей. Ее зовут Донова Снегонора, она живет прямо рядом с источниками. $B$BНу, счастливой дороги! Еще раз спасибо за помощь с термометром.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь в Зимние Ключи и побеседуйте с Доновой Снегонорой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуй, $n! Да, Кракл был совершенно прав...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (981,'Башня Алталакса','За всю проделанную вами работу вы заслужили хорошую награду. Возвращайтесь к Делгрену и скажите ему, что Атрикус Нарассин лежит, сраженный вашей рукой, а клан Темной Нити сокрушен, и остатки его рассеяны.','Поговорите с Делгреном Очистителем на Заставе Мейстры.','Я знал, что вы возьметесь за это задание, $n.$B$BЯ чувствую, вас ждут великие дела и что вам суждено исцелить многие недуги, что терзают наши земли. Примите мое благословение, $n, и этот дар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башня Алталакса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За всю проделанную вами работу вы заслужили хорошую награду. Возвращайтесь к Делгрену и скажите ему, что Атрикус Нарассин лежит, сраженный вашей рукой, а клан Темной Нити сокрушен, и остатки его рассеяны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Делгреном Очистителем на Заставе Мейстры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знал, что вы возьметесь за это задание, $n.$B$BЯ чувствую, вас ждут великие дела и что вам суждено исцелить многие недуги, что терзают наши земли. Примите мое благословение, $n, и этот дар.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (982,'Безбрежное море, глубокий океан','У побережья Темных берегов, к северу от нас, есть остатки двух потерпевших крушение кораблей – "Серебряной Зари" и "Туманной Пелены". Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина. Теперь корабли лежат на дне океана, став добычей мурлоков$B$BОба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в сейфах. Я хотел бы, чтобы вы добыли их для нас; это много значило бы для членов команды.','Добудьте сейф "Серебряной Зари" и сейф "Туманной Пелены" для Горбольда Стальной Руки в Аубердине. Оба предмета можно найти в останках потерпевших крушение кораблей к северу от деревни.','Вы оказали нам огромную услугу, $gюноша:девушка;. Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход.$B$BЧто же касается вас, прошу вас принять это. Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости.','Капитаны тех кораблей были славными ночными эльфами, и они заслужили лучшую участь, чем та, что им выпала. Может быть, внимание, проявленное к их личным ценностям, – наилучший способ позволить их душам обрести покой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безбрежное море, глубокий океан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У побережья Темных берегов, к северу от нас, есть остатки двух потерпевших крушение кораблей – "Серебряной Зари" и "Туманной Пелены". Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина. Теперь корабли лежат на дне океана, став добычей мурлоков$B$BОба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в сейфах. Я хотел бы, чтобы вы добыли их для нас; это много значило бы для членов команды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сейф "Серебряной Зари" и сейф "Туманной Пелены" для Горбольда Стальной Руки в Аубердине. Оба предмета можно найти в останках потерпевших крушение кораблей к северу от деревни.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы оказали нам огромную услугу, $gюноша:девушка;. Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход.$B$BЧто же касается вас, прошу вас принять это. Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Капитаны тех кораблей были славными ночными эльфами, и они заслужили лучшую участь, чем та, что им выпала. Может быть, внимание, проявленное к их личным ценностям, – наилучший способ позволить их душам обрести покой.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (983,'Жужжалка 827','Слушай! Помоги мне с моим последним изобретением, Жужжалкой. С ее помощью можно общаться на расстоянии!$b$bМожет быть, ты уже $gвидел:видела; их – такие ящики с рычагами. С ними одна проблема – за ними нужен постоянный уход.$b$bУ каждой из них есть своя проблема, но я нашел хитрое решение. Я поместил все машины в районе обитания существ, части которых нужны для починки каждой конкретной машины. Сейчас неисправна Жужжалка 827. Она находится чуть южнее Аубердина, совсем рядом с ним. Чтобы ее починить, нужно 6 ножек краба. Я заплачу...','Добудьте 6 ножек крабов и поместите их в Жужжалку 827.','Когда вы кладете ножки крабов в приемник машины, то слышите, как шестерни начинают их перемалывать. По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли свое место. Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины.\n\n"Алло! Уфф... Алло! Ты ее починила! Кстати, это Бацбах. Спасибо большое... Эй, не откажешься починить еще одну машинку?"','Жужжалка 827 хранит зловещее молчание. Единственный мигающий индикатор показывает, что в приемник нужно поместить 6 ножек крабов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жужжалка 827',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай! Помоги мне с моим последним изобретением, Жужжалкой. С ее помощью можно общаться на расстоянии!$b$bМожет быть, ты уже $gвидел:видела; их – такие ящики с рычагами. С ними одна проблема – за ними нужен постоянный уход.$b$bУ каждой из них есть своя проблема, но я нашел хитрое решение. Я поместил все машины в районе обитания существ, части которых нужны для починки каждой конкретной машины. Сейчас неисправна Жужжалка 827. Она находится чуть южнее Аубердина, совсем рядом с ним. Чтобы ее починить, нужно 6 ножек краба. Я заплачу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 ножек крабов и поместите их в Жужжалку 827.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда вы кладете ножки крабов в приемник машины, то слышите, как шестерни начинают их перемалывать. По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли свое место. Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины.\n\n"Алло! Уфф... Алло! Ты ее починила! Кстати, это Бацбах. Спасибо большое... Эй, не откажешься починить еще одну машинку?"',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Жужжалка 827 хранит зловещее молчание. Единственный мигающий индикатор показывает, что в приемник нужно поместить 6 ножек крабов.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (984,'Насколько велика угроза?','Некоторые из моих собратьев спаслись от порабощенных скверной фурболгов в Тельдрассиле, а я пообещал остановить злодеяния, пока кровь не полилась рекой... или не произошло чего-то еще хуже.$b$bЯ уже вижу признаки присутствия скверны на Темных берегах, но она еще не так распространилась. Я думаю, было бы логично продолжить исследования фурболгов. Может быть, вы разыщете один из их лагерей, а затем вернетесь ко мне, если увидите следы осквернения?','Найдите оскверненный лагерь фурболгов на Темных берегах и вернитесь к Терентису в Аубердин.','Найдите оскверненный лагерь фурболгов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Насколько велика угроза?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые из моих собратьев спаслись от порабощенных скверной фурболгов в Тельдрассиле, а я пообещал остановить злодеяния, пока кровь не полилась рекой... или не произошло чего-то еще хуже.$b$bЯ уже вижу признаки присутствия скверны на Темных берегах, но она еще не так распространилась. Я думаю, было бы логично продолжить исследования фурболгов. Может быть, вы разыщете один из их лагерей, а затем вернетесь ко мне, если увидите следы осквернения?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите оскверненный лагерь фурболгов на Темных берегах и вернитесь к Терентису в Аубердин.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите оскверненный лагерь фурболгов.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (985,'Насколько велика угроза?','Вы уже поднаторели в разведке на вражеских территориях, $n. Но способны ли вы не только следить за врагами, но и биться с ними?$b$bНе все искатели приключений предпочитают честную битву лицом к лицу искусству скрытности и уклонения.$b$bЕсли вы считаете, что готовы к сражению, то наибольшую угрозу нашему народу представляют сейчас фурболги в лагере к югу от Аубердина. Вы найдете там фурболгов Чернолесья. Убейте 8 землепроходцев и 5 заклинателей ветра, а потом возвращайтесь сюда, ко мне.','Убейте 8 землепроходцев и 5 заклинателей ветра из племени Чернолесья, а затем вернитесь к Терентису в Аубердин.','Не отдаляй руки своей от того, что должно быть сделано, дитя мое. Я знаю, какое омерзение внушает сама мысль об убийстве лесных созданий, но в данном случае – это необходимость. Никакого способа исцеления от этой скверны, отравившей лес, пока не нашлось, и мы должны сделать все возможное, чтобы остановить ее продвижение, пока средство не будет найдено.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Насколько велика угроза?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы уже поднаторели в разведке на вражеских территориях, $n. Но способны ли вы не только следить за врагами, но и биться с ними?$b$bНе все искатели приключений предпочитают честную битву лицом к лицу искусству скрытности и уклонения.$b$bЕсли вы считаете, что готовы к сражению, то наибольшую угрозу нашему народу представляют сейчас фурболги в лагере к югу от Аубердина. Вы найдете там фурболгов Чернолесья. Убейте 8 землепроходцев и 5 заклинателей ветра, а потом возвращайтесь сюда, ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 землепроходцев и 5 заклинателей ветра из племени Чернолесья, а затем вернитесь к Терентису в Аубердин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не отдаляй руки своей от того, что должно быть сделано, дитя мое. Я знаю, какое омерзение внушает сама мысль об убийстве лесных созданий, но в данном случае – это необходимость. Никакого способа исцеления от этой скверны, отравившей лес, пока не нашлось, и мы должны сделать все возможное, чтобы остановить ее продвижение, пока средство не будет найдено.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (986,'Пропавший хозяин','$n, ваше мастерство уже один раз сослужило мне хорошую службу в сложной ситуации. Могу ли я вновь возложить на вас задачу помочь Лютому Когтю и его хозяину Волкору? Я могу сделать для вас волшебный плащ, который позволит вам беспрепятственно ходить вблизи враждебных существ Темных берегов, пока вы будете искать Волкора.$b$bДля изготовления плаща, чтобы хватило материала, мне нужно 5 прекрасных шкур лунопарда, снятых со взрослых самцов или матриархов. Этих кошек можно найти около Петляющей реки, к югу отсюда, или еще дальше на юг, близ Ясеневого леса.','Найдите 5 прекрасных шкур лунопарда и принесите их Терентису в Аубердин.','В здравом уме я не позволю вам идти искать Волкора, пока не сошью для вас тот плащ.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший хозяин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ваше мастерство уже один раз сослужило мне хорошую службу в сложной ситуации. Могу ли я вновь возложить на вас задачу помочь Лютому Когтю и его хозяину Волкору? Я могу сделать для вас волшебный плащ, который позволит вам беспрепятственно ходить вблизи враждебных существ Темных берегов, пока вы будете искать Волкора.$b$bДля изготовления плаща, чтобы хватило материала, мне нужно 5 прекрасных шкур лунопарда, снятых со взрослых самцов или матриархов. Этих кошек можно найти около Петляющей реки, к югу отсюда, или еще дальше на юг, близ Ясеневого леса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 прекрасных шкур лунопарда и принесите их Терентису в Аубердин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В здравом уме я не позволю вам идти искать Волкора, пока не сошью для вас тот плащ.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (987,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (988,'<UNUSED>','I noticed the cloak you are wearing, $n. If you\'d be willing to sacrifice it, I can renew its magics, and use it to escape. The problem with that, though, is you\'ll be left here in the cave alone.$B$BAre you able to make it out of here on your own if we choose that course?$B$BI can assure you that Terenthis will reward you for aiding me, if that is your concern.$B$BThe choice is yours, but I could really use your help.','Speak to Volcor.','Вернитесь к Волкору в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','I noticed the cloak you are wearing, $n. If you\'d be willing to sacrifice it, I can renew its magics, and use it to escape. The problem with that, though, is you\'ll be left here in the cave alone.$B$BAre you able to make it out of here on your own if we choose that course?$B$BI can assure you that Terenthis will reward you for aiding me, if that is your concern.$B$BThe choice is yours, but I could really use your help.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to Volcor.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Волкору в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (989,'<UNUSED>','If we decide to fight our way out, the plan is simple: we\'ll make our way down to the road and kill any furbolgs that get in our way... or anything else that decides it wants to stop us.$B$BI wish there was another way, but sooner or later the furbolg threat would have to be dealt with. Better it be by our own hands, so we know the job is done.$B$BTake a moment to prepare any magic or weapons you have at your disposal, then speak to me again.','Speak to Volcor.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','If we decide to fight our way out, the plan is simple: we\'ll make our way down to the road and kill any furbolgs that get in our way... or anything else that decides it wants to stop us.$B$BI wish there was another way, but sooner or later the furbolg threat would have to be dealt with. Better it be by our own hands, so we know the job is done.$B$BTake a moment to prepare any magic or weapons you have at your disposal, then speak to me again.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to Volcor.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (990,'Путь в Ясеневый лес','$n, моя госпожа – Раэна Волкопас – ожидает тебя в городе Астранаар, что в Ясеневом лесу. Возможно, с твоей помощью мы сможем хотя бы немного ослабить порчу, пустившую здесь корни.$B$BОтправляйся отсюда на юг и держись дороги – ты легко найдешь путь, если будешь держаться этого направления.','Найдите в Ясеневом лесу Раэну Волкопас.','А, |3-6($c) с Темного Берега. Хорошо, что Селарин прислала тебя так быстро, $n. Прости, что тебе пришлось так спешить. Но с твоей помощью мы, возможно, сможем исправить положение.$B$BЯ бы начала с разговоров с другими жителями Астранаара. Многим наверняка понадобится твоя помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь в Ясеневый лес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, моя госпожа – Раэна Волкопас – ожидает тебя в городе Астранаар, что в Ясеневом лесу. Возможно, с твоей помощью мы сможем хотя бы немного ослабить порчу, пустившую здесь корни.$B$BОтправляйся отсюда на юг и держись дороги – ты легко найдешь путь, если будешь держаться этого направления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Ясеневом лесу Раэну Волкопас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, |3-6($c) с Темного Берега. Хорошо, что Селарин прислала тебя так быстро, $n. Прости, что тебе пришлось так спешить. Но с твоей помощью мы, возможно, сможем исправить положение.$B$BЯ бы начала с разговоров с другими жителями Астранаара. Многим наверняка понадобится твоя помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (991,'В поисках Терониса','Раэна Волкопас, моя подруга из Астранаара, попросила меня послать разведчика на запад к озеру Фалатим. Теронис ушел несколько дней назад, еще до нападения Орды.$B$BОн думает отыскать один предмет, который, по его мнению, ослабит нападения фурболгов на наш народ – это жезл, сделанный ныне покойным злым волшебником. $B$BПрежде чем уйти, он упомянул, что будет искать драгоценный камень для жезла.$B$BОн также говорил, что камень может находиться в святилище, построенном на острове посреди озера.$B$BК несчастью, теперь мы знаем, что озеро является источником некоей зловещей силы. Прошу тебя, $n, найди моего друга!','Найдите Терониса у озера Фалатим в Ясеневом лесу.','Покрытое ранами тело Терониса лежит на острове. По какой-то непонятной причине мурлоки бросили его здесь.$B$BГлубокие резаные раны явно оставлены оружием и когтями мурлоков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Терониса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раэна Волкопас, моя подруга из Астранаара, попросила меня послать разведчика на запад к озеру Фалатим. Теронис ушел несколько дней назад, еще до нападения Орды.$B$BОн думает отыскать один предмет, который, по его мнению, ослабит нападения фурболгов на наш народ – это жезл, сделанный ныне покойным злым волшебником. $B$BПрежде чем уйти, он упомянул, что будет искать драгоценный камень для жезла.$B$BОн также говорил, что камень может находиться в святилище, построенном на острове посреди озера.$B$BК несчастью, теперь мы знаем, что озеро является источником некоей зловещей силы. Прошу тебя, $n, найди моего друга!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Терониса у озера Фалатим в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Покрытое ранами тело Терониса лежит на острове. По какой-то непонятной причине мурлоки бросили его здесь.$B$BГлубокие резаные раны явно оставлены оружием и когтями мурлоков.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (992,'Исследование воды','У нас, в Водной компании Прибамбасска, образовалась вакансия на должность младшего геодезиста на временную работу. Интересуешься?$b$BКочевники захватили все наши колодцы, приходится искать альтернативные источники воды! В пустыне есть вода, надо только ее отыскать!$b$bВозьми это устройство для поиска воды и принеси мне пробу из пруда возле Заставы Скорбных Песков. Правда, это место на виду у троллей. Когда закончишь, принеси мне включенное устройство!','Воспользуйтесь нетронутым устройством для поиска воды возле пруда на Заставе Скорбных Песков. Забрав пробу, отнесите устройство старшему геодезисту Рудознатцу в Прибамбасск.','Что такое? На тебя напали какие-то мерзкие ползучие твари? Ох, плохо это для Водной компании Прибамбасска, ох плохо…\n\nНадо было раньше тебя предупредить насчет этих кошмарных насекомых, которые, кажется, выпивают всю воду в пустыне. Сначала я не придал им значения. Нам хватает проблем и с кочевниками, и мы решили, что это тоже их происки. Теперь мы знаем правду!','Вернитесь к старшему геодезисту Рудознатцу в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас, в Водной компании Прибамбасска, образовалась вакансия на должность младшего геодезиста на временную работу. Интересуешься?$b$BКочевники захватили все наши колодцы, приходится искать альтернативные источники воды! В пустыне есть вода, надо только ее отыскать!$b$bВозьми это устройство для поиска воды и принеси мне пробу из пруда возле Заставы Скорбных Песков. Правда, это место на виду у троллей. Когда закончишь, принеси мне включенное устройство!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь нетронутым устройством для поиска воды возле пруда на Заставе Скорбных Песков. Забрав пробу, отнесите устройство старшему геодезисту Рудознатцу в Прибамбасск.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что такое? На тебя напали какие-то мерзкие ползучие твари? Ох, плохо это для Водной компании Прибамбасска, ох плохо…\n\nНадо было раньше тебя предупредить насчет этих кошмарных насекомых, которые, кажется, выпивают всю воду в пустыне. Сначала я не придал им значения. Нам хватает проблем и с кочевниками, и мы решили, что это тоже их происки. Теперь мы знаем правду!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему геодезисту Рудознатцу в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (993,'Пропавший хозяин','Плащ готов, $n. Пришло время найти Волкора. Я могу только надеяться, что мы успеем.$b$bМагия, скрытая в плаще, если ее пробудить, продержится недолго: может быть, минут пять. $GСам:Сама; решай, когда использовать: я бы предложил подождать, пока не найдешь Лютого Когтя.$b$bЕсли то, что он сказал мне – правда, ты найдешь его хозяина в пещере к югу отсюда. Лютый Коготь будет ждать тебя у дороги. Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину.','Найдите Волкора на Темных берегах и отдайте ему зачарованный плащ лунопарда.','Чудесно! Терентис прислал мне помощь!$B$BО, посмотри-ка, еще и плащ...  кашляет  Ох... Больно. Спасибо, $n.$B$BФурболги ранили меня, прежде чем я сумел от них улизнуть. Дай мне еще минутку, и я буду в состоянии разговаривать дальше.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший хозяин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плащ готов, $n. Пришло время найти Волкора. Я могу только надеяться, что мы успеем.$b$bМагия, скрытая в плаще, если ее пробудить, продержится недолго: может быть, минут пять. $GСам:Сама; решай, когда использовать: я бы предложил подождать, пока не найдешь Лютого Когтя.$b$bЕсли то, что он сказал мне – правда, ты найдешь его хозяина в пещере к югу отсюда. Лютый Коготь будет ждать тебя у дороги. Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Волкора на Темных берегах и отдайте ему зачарованный плащ лунопарда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно! Терентис прислал мне помощь!$B$BО, посмотри-ка, еще и плащ...  кашляет  Ох... Больно. Спасибо, $n.$B$BФурболги ранили меня, прежде чем я сумел от них улизнуть. Дай мне еще минутку, и я буду в состоянии разговаривать дальше.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (994,'Спасение с помощью силы','Ладно, $n, силой так силой. Давайте убираться отсюда, как только вы будете готовы. Мы пробьемся к дороге – Лютый Коготь должен все еще ждать. А там мы уже сможем разделиться.$b$bТерентис сразу же захочет услышать ваш рассказ, поэтому вы направитесь в Аубердин, когда мы отсюда выберемся.','Защищайте Волкора, пока не доберетесь до дороги, а затем поговорите с Терентисом в Аубердине.','$N! Рад видеть вас $gживым и здоровым:живой и здоровой;. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Темном Берегу и за его пределами.','Защищайте Волкора, пока не доберетесь до дороги.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение с помощью силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, $n, силой так силой. Давайте убираться отсюда, как только вы будете готовы. Мы пробьемся к дороге – Лютый Коготь должен все еще ждать. А там мы уже сможем разделиться.$b$bТерентис сразу же захочет услышать ваш рассказ, поэтому вы направитесь в Аубердин, когда мы отсюда выберемся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защищайте Волкора, пока не доберетесь до дороги, а затем поговорите с Терентисом в Аубердине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N! Рад видеть вас $gживым и здоровым:живой и здоровой;. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Темном Берегу и за его пределами.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защищайте Волкора, пока не доберетесь до дороги.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (995,'Спасение с помощью скрытности','Ну, ладно... Если вы уверены, попробуем выскользнуть отсюда. Мы уйдем, как только вы будете готовы.$b$bНе забудьте после бегства отсюда вернуться к Терентису в Аубердин. А я туда отправлюсь сам по себе, потому что, вероятно, буду двигаться быстрее вас.','Совершите побег из пещеры фурболгов и встретьтесь в Аубердине с Терентисом.','$N! Рад видеть вас живым и здоровым. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Темном Берегу и за его пределами.','Да, $N?','Помогите Волкору сбежать из пещеры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение с помощью скрытности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, ладно... Если вы уверены, попробуем выскользнуть отсюда. Мы уйдем, как только вы будете готовы.$b$bНе забудьте после бегства отсюда вернуться к Терентису в Аубердин. А я туда отправлюсь сам по себе, потому что, вероятно, буду двигаться быстрее вас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Совершите побег из пещеры фурболгов и встретьтесь в Аубердине с Терентисом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N! Рад видеть вас живым и здоровым. Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Темном Берегу и за его пределами.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помогите Волкору сбежать из пещеры.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (996,'Оскверненный ветроцвет','Вернитесь к оскверненному ветроцвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный ветроцвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному ветроцвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (997,'Земля Деналана','Так ты идешь на юг? К озеру Аль\'Амет? Если да, то не выполнишь ли ты одну мою просьбу...$B$BМой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты. Ему нужна редкая земля из Дарнаса, но ее доставили в Доланаар с опозданием – только что.$B$BНе $gмог бы:могла бы; ты отнести ему эту землю?','Отнесите горсть редкой земли Деналану к озеру Аль\'Амет.','Ты что-то мне $Gпринес:принесла;?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Земля Деналана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так ты идешь на юг? К озеру Аль\'Амет? Если да, то не выполнишь ли ты одну мою просьбу...$B$BМой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты. Ему нужна редкая земля из Дарнаса, но ее доставили в Доланаар с опозданием – только что.$B$BНе $gмог бы:могла бы; ты отнести ему эту землю?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите горсть редкой земли Деналану к озеру Аль\'Амет.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты что-то мне $Gпринес:принесла;?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (998,'Оскверненный ветроцвет','Вернитесь к оскверненному ветроцвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный ветроцвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному ветроцвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (999,'Когда сны превращаются в кошмары') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда сны превращаются в кошмары',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1000,'Новое пограничье','Внимание, герои!$B$BКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора – запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!$B$BВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Хамуулу Руническому Тотему на вершину Старейшин Громового Утеса!','Обратитесь к верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин Громового Утеса по поводу помощи Кругу Кенария в исследовании границ Калимдора.','Здравствуй, |3-6($C).$B$BЯ рад, что героям, подобным тебе, небезразлична судьба природы. Слава о твоих великих деяниях летела впереди тебя, и тебе здесь рады. Узрев тебя, я исполнился уверенности, что Круг Кенария обретет нужную ему помощь.$B$BНаши связи с Кругом Кенария Лунной поляны превыше расовых и политических предрассудков. Помни это, трудясь во славу Круга, и будет тебе благо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое пограничье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимание, герои!$B$BКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора – запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!$B$BВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Хамуулу Руническому Тотему на вершину Старейшин Громового Утеса!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин Громового Утеса по поводу помощи Кругу Кенария в исследовании границ Калимдора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуй, |3-6($C).$B$BЯ рад, что героям, подобным тебе, небезразлична судьба природы. Слава о твоих великих деяниях летела впереди тебя, и тебе здесь рады. Узрев тебя, я исполнился уверенности, что Круг Кенария обретет нужную ему помощь.$B$BНаши связи с Кругом Кенария Лунной поляны превыше расовых и политических предрассудков. Помни это, трудясь во славу Круга, и будет тебе благо.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1001,'Жужжалка 411','Тоненький голосок пробивается откуда-то из глубины машины.$B$B"Бацбах у аппарата! Следующая Жужжалка находится к северу от Аубердина, прямо на берегу.$b$bИтак, номер той Жужжалки – 411, и для ее починки нужно три глаза крепкозуба. Эти твари водятся недалеко от берега! Крепкозубы Темных берегов... *И-ик!* Извини...$b$bКак и в прошлый раз, когда поместишь в Жужжалку то, что нужно, она выдаст тебе награду. *И-ик!* Что? Не, со мной все в порядке!"','Добудьте 3 глаза крепкозуба с крепкозубов Темных берегов, которые водятся в море неподалеку от Жужжалки 411.','Жужжалка оживает вскоре после того, как вы помещаете в нее глаза крепкозуба. После коротких помех вы слышите знакомый голосок.$B$B"Вино из крабов лучше всего..." И-ик! $B$B"Что? О, ты уже ее починил! Ух, какой ты бысшшштрый. Так шшшо, согласишшшься почшшшинить ешшше одну?"$b$bВы уверены, что слышите, как жидкость льется в емкость, а затем – звучные глотки.','Приемник машины открыт и, кажется, ждет, когда в него поместят 3 глаза крепкозуба.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жужжалка 411',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тоненький голосок пробивается откуда-то из глубины машины.$B$B"Бацбах у аппарата! Следующая Жужжалка находится к северу от Аубердина, прямо на берегу.$b$bИтак, номер той Жужжалки – 411, и для ее починки нужно три глаза крепкозуба. Эти твари водятся недалеко от берега! Крепкозубы Темных берегов... *И-ик!* Извини...$b$bКак и в прошлый раз, когда поместишь в Жужжалку то, что нужно, она выдаст тебе награду. *И-ик!* Что? Не, со мной все в порядке!"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 глаза крепкозуба с крепкозубов Темных берегов, которые водятся в море неподалеку от Жужжалки 411.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жужжалка оживает вскоре после того, как вы помещаете в нее глаза крепкозуба. После коротких помех вы слышите знакомый голосок.$B$B"Вино из крабов лучше всего..." И-ик! $B$B"Что? О, ты уже ее починил! Ух, какой ты бысшшштрый. Так шшшо, согласишшшься почшшшинить ешшше одну?"$b$bВы уверены, что слышите, как жидкость льется в емкость, а затем – звучные глотки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приемник машины открыт и, кажется, ждет, когда в него поместят 3 глаза крепкозуба.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1002,'Жужжалка 323','Жужжалка издает треск статических помех, и вы слышите голос Бацбаха.$b$b"Шшшледуюшшшая жужшшшалка – номер 323. Она к шшшеверу от Аубердина, но... а хде жшшше эль? Шшшто? О, она шшштоит на дороге, так шшшто ты легко ее найдешшшь около мосшшшт".$b$bБацбах что-то неразборчиво бормочет, а потом вы слышите отчетливый звук глотка.$b$b"В эту нужшшшно положшшшить клыки лунопардов... шшшесть".','Добудьте 6 клыков лунопарда и поместите их в Жужжалку 323.','Неожидано Жужжалка начинает работать, и вы отчетливо слышите, как клыки перемалываются внутри машины в муку.$B$B"Так шшшо, ты это шшшделал! Отлишшшные новосшшшти... И шшшо жшшше... ты не уходишшшь? А! Можшшшет, хочешшшь ешшше поработать?"','Хотя вы еще не поместили внутрь Жужжалки клыки лунопардов, вам кажется, что оттуда раздаются звуки статических разрядов и невнятное гномье бормотание. Может быть, кто-то уже успел починить машину?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жужжалка 323',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жужжалка издает треск статических помех, и вы слышите голос Бацбаха.$b$b"Шшшледуюшшшая жужшшшалка – номер 323. Она к шшшеверу от Аубердина, но... а хде жшшше эль? Шшшто? О, она шшштоит на дороге, так шшшто ты легко ее найдешшшь около мосшшшт".$b$bБацбах что-то неразборчиво бормочет, а потом вы слышите отчетливый звук глотка.$b$b"В эту нужшшшно положшшшить клыки лунопардов... шшшесть".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 клыков лунопарда и поместите их в Жужжалку 323.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неожидано Жужжалка начинает работать, и вы отчетливо слышите, как клыки перемалываются внутри машины в муку.$B$B"Так шшшо, ты это шшшделал! Отлишшшные новосшшшти... И шшшо жшшше... ты не уходишшшь? А! Можшшшет, хочешшшь ешшше поработать?"',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хотя вы еще не поместили внутрь Жужжалки клыки лунопардов, вам кажется, что оттуда раздаются звуки статических разрядов и невнятное гномье бормотание. Может быть, кто-то уже успел починить машину?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1003,'Жужжалка 525','Сквозь булькающий шум и звуки капающей жидкости, исходящие от машины, вы слышите неверный голос Бацбаха.$b$b"Шшшледуюшший далеко на юг по доррроге. Найти должно быть нетрудно... шшшразу рядом на обочшшине... возле огражшшдения. Думаю, я шшпрятал его в каких-то кусшшштах... Кусшшшты... Хи-хи... Да, Жужжшшалка 525 снимет сшшшедые шшшкальпы с этттих сшшшедых колючешшшшерстныхх медведей. Божшшшежшшш мой, шшшто за пойло. Гнусшшшные... Хи-хи-хи..."$b$bВы слышите звуки жадных глотков, и машина выключается. Затем, совершенно неожиданно, вновь оживает.$B$B"Четыре!"','Соберите 4 седых скальпа с седых колючешерстных медведей к югу от Аубердина и положите их в Жужжалку 525.','Так ты шшшшо, положшшил шшшкальпы внутрь? Хорошшшо... Шо? Агга, я шшшоображшшаю, шшшо могу разшшшговаривать шшш тобой и безшшш материалов в машшшине. Но я пррравду грил, когда шшшказшшшал, шшшо они шшшломались!$B$BШшшмотри, кроме шшшредшшштв коммунимакации эти жужжшшшалки ешшше варят и дишшштиллируют отличшшшное питье. Просшшшти зшшша обман, но Ночшшшные эльфы не одобряют торррговли моими напитками в сшшшвоих городах. Я оставлю нечшшшто осшшшобенное в этом яшшшике, шшшобы показать мою благодарносшшшть за твои усшшшилия. Насшшшлаждайся!','Вы слышите пение, раздающееся из Жужжалки 525.$B$B Хотя изшшш крабов сладкое винннцо, из млатозшшшуба эль хоть куда, и сшшшамогонка лунная вкусна, но нет ничшшего лучше пива медвежшшшьего, и сшшшкоро будет оно у меня! $B$BЗаслонка открыта и ждет добытых вами 4 седых скальпов, а песенка звучит снова и снова.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жужжалка 525',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сквозь булькающий шум и звуки капающей жидкости, исходящие от машины, вы слышите неверный голос Бацбаха.$b$b"Шшшледуюшший далеко на юг по доррроге. Найти должно быть нетрудно... шшшразу рядом на обочшшине... возле огражшшдения. Думаю, я шшпрятал его в каких-то кусшшштах... Кусшшшты... Хи-хи... Да, Жужжшшалка 525 снимет сшшшедые шшшкальпы с этттих сшшшедых колючешшшшерстныхх медведей. Божшшшежшшш мой, шшшто за пойло. Гнусшшшные... Хи-хи-хи..."$b$bВы слышите звуки жадных глотков, и машина выключается. Затем, совершенно неожиданно, вновь оживает.$B$B"Четыре!"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 седых скальпа с седых колючешерстных медведей к югу от Аубердина и положите их в Жужжалку 525.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ты шшшшо, положшшил шшшкальпы внутрь? Хорошшшо... Шо? Агга, я шшшоображшшаю, шшшо могу разшшшговаривать шшш тобой и безшшш материалов в машшшине. Но я пррравду грил, когда шшшказшшшал, шшшо они шшшломались!$B$BШшшмотри, кроме шшшредшшштв коммунимакации эти жужжшшшалки ешшше варят и дишшштиллируют отличшшшное питье. Просшшшти зшшша обман, но Ночшшшные эльфы не одобряют торррговли моими напитками в сшшшвоих городах. Я оставлю нечшшшто осшшшобенное в этом яшшшике, шшшобы показать мою благодарносшшшть за твои усшшшилия. Насшшшлаждайся!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы слышите пение, раздающееся из Жужжалки 525.$B$B Хотя изшшш крабов сладкое винннцо, из млатозшшшуба эль хоть куда, и сшшшамогонка лунная вкусна, но нет ничшшего лучше пива медвежшшшьего, и сшшшкоро будет оно у меня! $B$BЗаслонка открыта и ждет добытых вами 4 седых скальпов, а песенка звучит снова и снова.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1004,'Новое пограничье','Внимание, герои!$b$bКруг Кенария ищет отважных, которые помогут исследовать новое пограничье Калимдора! К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши. Круг нуждается в доблестных помощниках!$b$bВсе заинтересованные лица могут обращаться в Круг Кенария. Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утеса.','Поговорите с верховным друидом Хамуулом Руническим Тотемом на Вершине Старейшин Громового Утеса об исследовании пограничья Калимдора.','Здравствуй, |3-6($C)!$B$BПриятно видеть, что таким, как ты, небезразлично благополучие природы. Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады. Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается.$B$BНаша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий. Помни это, когда будешь действовать от имени Круга, – и добьешься успеха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое пограничье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимание, герои!$b$bКруг Кенария ищет отважных, которые помогут исследовать новое пограничье Калимдора! К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши. Круг нуждается в доблестных помощниках!$b$bВсе заинтересованные лица могут обращаться в Круг Кенария. Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утеса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным друидом Хамуулом Руническим Тотемом на Вершине Старейшин Громового Утеса об исследовании пограничья Калимдора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуй, |3-6($C)!$B$BПриятно видеть, что таким, как ты, небезразлично благополучие природы. Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады. Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается.$B$BНаша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий. Помни это, когда будешь действовать от имени Круга, – и добьешься успеха.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1005,'Шныряющие за стеной') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шныряющие за стеной',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1006,'Что скрывается за стеной') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что скрывается за стеной',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1007,'Древние статуэтки','Я хотел бы дать тебе поручение, |3-6($c).$B$BЯ на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги, выныривая из воды и вцепляясь в меня когтями! Остальное неважно – главное, что мне удалось сбежать.$B$BБеда в том, что я археолог, и прибыл сюда для того, чтобы раздобыть кое-какие артефакты затопленного города.$B$BМожет быть, ты отправишься вместо меня на северо-запад, к Зорамскому взморью, и отыщешь какие-нибудь древности? Не хочу напрасно подвергать себя опасностям.','Соберите 10 древних статуэток.','[Deprecated] Return to Talen at the Blackfathom Camp in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древние статуэтки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хотел бы дать тебе поручение, |3-6($c).$B$BЯ на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги, выныривая из воды и вцепляясь в меня когтями! Остальное неважно – главное, что мне удалось сбежать.$B$BБеда в том, что я археолог, и прибыл сюда для того, чтобы раздобыть кое-какие артефакты затопленного города.$B$BМожет быть, ты отправишься вместо меня на северо-запад, к Зорамскому взморью, и отыщешь какие-нибудь древности? Не хочу напрасно подвергать себя опасностям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 древних статуэток.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Talen at the Blackfathom Camp in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1008,'Зорамское взморье','По нашему северо-западному побережью, известному как Зорамское взморье, расползается зло.$B$BТам покоятся руины злосчастного города Зорам, разрушенного при Расколе и поглощенного морем. Для ночных эльфов он был утрачен на много веков. Утрачен и почти забыт.$B$BТеперь туда вернулись наги, и мы не знаем, почему. Но причина не так важна – мы должны перебить этих тварей и загнать их обратно в глубины!$B$BВозвращайся, когда выполнишь поручение.','Принесите 20 голов наг из клана Зловещего Хвоста Шиндрелл Огненный Всполох в Астранаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зорамское взморье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По нашему северо-западному побережью, известному как Зорамское взморье, расползается зло.$B$BТам покоятся руины злосчастного города Зорам, разрушенного при Расколе и поглощенного морем. Для ночных эльфов он был утрачен на много веков. Утрачен и почти забыт.$B$BТеперь туда вернулись наги, и мы не знаем, почему. Но причина не так важна – мы должны перебить этих тварей и загнать их обратно в глубины!$B$BВозвращайся, когда выполнишь поручение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 голов наг из клана Зловещего Хвоста Шиндрелл Огненный Всполох в Астранаар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1009,'Руузель','Боюсь, тайна этой древней статуэтки так и останется нераскрытой, если не найти ключа к этому древнему замку.$B$BЭтим ключом является кольцо – кольцо Зорама. Оно принадлежало правителям этого города до того, как волны Раскола поглотили его.$B$BДолгие годы кольцо считалось утраченным, пока наги недавно не нашли его.$B$BИх предводительница, Руузель, живет на острове на северной окраине Зорама. Прошу тебя, $n, добудь мне это кольцо!','Добудьте кольцо Зорама.','[Deprecated] Return to Talen at the Blackfathom Camp in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руузель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, тайна этой древней статуэтки так и останется нераскрытой, если не найти ключа к этому древнему замку.$B$BЭтим ключом является кольцо – кольцо Зорама. Оно принадлежало правителям этого города до того, как волны Раскола поглотили его.$B$BДолгие годы кольцо считалось утраченным, пока наги недавно не нашли его.$B$BИх предводительница, Руузель, живет на острове на северной окраине Зорама. Прошу тебя, $n, добудь мне это кольцо!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте кольцо Зорама.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Talen at the Blackfathom Camp in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (1010,'Батранов волос','Есть одна травка, что росла некогда в древних руинах Убежища Батрана, что вдоль дороги на востоке. Звалась эта травка Батранов волос и славилась тем, что лечила болезни души.$B$BУвы, теперь ее собирают прислужники Орды для своих зловещих целей.$B$BВ Астранааре болеет ребенок, и сдается мне, что это болезнь не телесная. Я обещал своему наставнику найти лекарство, но мне не под силу сражаться с воинами.$B$BНе сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос?','Соберите 8 стеблей Батранова волоса.','Ах, ты $Gпринес:принесла; эту травку! Теперь я сварю лекарство для ребенка, и будем молиться, чтобы отвар подействовал.$B$BИ... В Убежище Батрана – Отрекшиеся? Очень тревожная весть. Поистине, очень тревожная...','[Deprecated] Return to Evenar Stillwhisper at Orendil\'s Retreat in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Батранов волос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть одна травка, что росла некогда в древних руинах Убежища Батрана, что вдоль дороги на востоке. Звалась эта травка Батранов волос и славилась тем, что лечила болезни души.$B$BУвы, теперь ее собирают прислужники Орды для своих зловещих целей.$B$BВ Астранааре болеет ребенок, и сдается мне, что это болезнь не телесная. Я обещал своему наставнику найти лекарство, но мне не под силу сражаться с воинами.$B$BНе сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 стеблей Батранова волоса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, ты $Gпринес:принесла; эту травку! Теперь я сварю лекарство для ребенка, и будем молиться, чтобы отвар подействовал.$B$BИ... В Убежище Батрана – Отрекшиеся? Очень тревожная весть. Поистине, очень тревожная...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Evenar Stillwhisper at Orendil\'s Retreat in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1011,'Чума Отрекшихся','Отрекшиеся, нежить из Орды, проникли в Ясеневый лес, и рыщут среди развалин и курганов. Мы уверены, что их цель – распространить чуму по землям ночных эльфов. Мы должны убедиться в этом!$B$BОтрекшиеся разбили лагерь к югу отсюда, рядом с Обителью Дор\'Данил, где они готовят яды и заразу и разливают их по бутылкам. Проложи себе путь в этот лагерь и укради бутыль с заразой. Принеси ее сюда. Я исследую ее и узнаю, для чего она.','Принесите бутыль заразы Кайнету Штилю в Лесную Песнь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чума Отрекшихся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отрекшиеся, нежить из Орды, проникли в Ясеневый лес, и рыщут среди развалин и курганов. Мы уверены, что их цель – распространить чуму по землям ночных эльфов. Мы должны убедиться в этом!$B$BОтрекшиеся разбили лагерь к югу отсюда, рядом с Обителью Дор\'Данил, где они готовят яды и заразу и разливают их по бутылкам. Проложи себе путь в этот лагерь и укради бутыль с заразой. Принеси ее сюда. Я исследую ее и узнаю, для чего она.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите бутыль заразы Кайнету Штилю в Лесную Песнь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1012,'Безумные друиды','Друиды мертвы! Они были убиты своими же предводителями, которые сошли с ума в результате осквернения Сердца леса проклятыми ордынцами! Даже здесь я чувствую тень разложения, и потому не осмеливаюсь идти дальше.$B$BЯ слишком привязан к Ясеневому лесу и Сердцу леса, но ты... ты $Gмог:могла; бы спуститься в Обитель и сделать то, что должно быть сделано. Ты не заблудишься – я оставил для тебя след из хлебных крошек.$B$BЭто разрывает мне сердце, но я вынужден просить тебя убить некогда великих предводителей друидов – Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.','Убейте обезумевших друидов: Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.','Я ощутил, как утихает боль обители Дор-Даниль, и понял, что ты выполнил свою задачу.$B$BТяжелое дело выпало тебе, $n, ибо духи, которых ты уничтожил, всего лишь жертвы злобы Отрекшихся. Но с их погибелью, будем надеяться, и другие безумные духи обретут покой.','Страдания друидов Дор-Даниля все еще тревожат мои сны, $N. Вы должны уничтожить их предводителей!','[Deprecated] Return to Gaivan Shadewalker, pacing outside the entrance to the Dor\'Danil Barrow Den in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безумные друиды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друиды мертвы! Они были убиты своими же предводителями, которые сошли с ума в результате осквернения Сердца леса проклятыми ордынцами! Даже здесь я чувствую тень разложения, и потому не осмеливаюсь идти дальше.$B$BЯ слишком привязан к Ясеневому лесу и Сердцу леса, но ты... ты $Gмог:могла; бы спуститься в Обитель и сделать то, что должно быть сделано. Ты не заблудишься – я оставил для тебя след из хлебных крошек.$B$BЭто разрывает мне сердце, но я вынужден просить тебя убить некогда великих предводителей друидов – Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте обезумевших друидов: Таниэля Темный Лес, Этиля Зов Луны и Мавориса Проблеск Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я ощутил, как утихает боль обители Дор-Даниль, и понял, что ты выполнил свою задачу.$B$BТяжелое дело выпало тебе, $n, ибо духи, которых ты уничтожил, всего лишь жертвы злобы Отрекшихся. Но с их погибелью, будем надеяться, и другие безумные духи обретут покой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Страдания друидов Дор-Даниля все еще тревожат мои сны, $N. Вы должны уничтожить их предводителей!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Gaivan Shadewalker, pacing outside the entrance to the Dor\'Danil Barrow Den in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (1013,'Книга Ура','$n, в крепости Темного Клыка хранится книга – книга Ура, я хочу видеть ее в своей коллекции. Ур был великим магом Даларана до того, как оказался в рядах Плети, и его труды по иным мирам представляют большой интерес... для некоторых Отрекшихся.$B$BОтправляйся в крепость Темного Клыка и найди книгу. Принеси мне ее, и я сообщу о твоих заслугах Темной Госпоже.','Принесите книгу Ура хранителю Бел\'дугуру в Район Фармацевтов в Подгород.','Прекрасно. Эта книга будет прекрасным дополнением моей коллекции трудов Ура. Знания его были велики, однако ограниченность его сознания не давало ему обрести настоящую силу. Именно поэтому он не смог противостоять Плети. \n\nМы, Отрекшиеся, не можем позволить себе роскошь быть слабыми – ведь тогда нам не выжить... \n\nИ уж тем более не обрести власть.','Вернитесь к хранителю Бел\'дугуру в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Книга Ура',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, в крепости Темного Клыка хранится книга – книга Ура, я хочу видеть ее в своей коллекции. Ур был великим магом Даларана до того, как оказался в рядах Плети, и его труды по иным мирам представляют большой интерес... для некоторых Отрекшихся.$B$BОтправляйся в крепость Темного Клыка и найди книгу. Принеси мне ее, и я сообщу о твоих заслугах Темной Госпоже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книгу Ура хранителю Бел\'дугуру в Район Фармацевтов в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно. Эта книга будет прекрасным дополнением моей коллекции трудов Ура. Знания его были велики, однако ограниченность его сознания не давало ему обрести настоящую силу. Именно поэтому он не смог противостоять Плети. \n\nМы, Отрекшиеся, не можем позволить себе роскошь быть слабыми – ведь тогда нам не выжить... \n\nИ уж тем более не обрести власть.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Бел\'дугуру в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1014,'Смерть Аругалу!','Аругал по-прежнему сидит в крепости Темного Клыка. Мы не можем считать Серебряный бор стратегическим оплотом Темной Госпожи до тех пор, пока Аругал жив. $b$bЯ позабочусь о том, чтобы искоренить его магию, $n. Но сделать так, чтобы Аругал встретил заслуженную смерть – это я оставляю вам. $b$bОтправляйтесь в крепость Темного Клыка и положите конец скверным деяниям Аругала раз и навсегда. И принесите мне голову этого злодея!','Убейте Аругала и принесите его голову Далару Ткачу Рассвета в Гробницу.','Со смертью Аругала мы сможем укрепить власть Темной Госпожи в Лордероне.','Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть Аругалу!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Аругал по-прежнему сидит в крепости Темного Клыка. Мы не можем считать Серебряный бор стратегическим оплотом Темной Госпожи до тех пор, пока Аругал жив. $b$bЯ позабочусь о том, чтобы искоренить его магию, $n. Но сделать так, чтобы Аругал встретил заслуженную смерть – это я оставляю вам. $b$bОтправляйтесь в крепость Темного Клыка и положите конец скверным деяниям Аругала раз и навсегда. И принесите мне голову этого злодея!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Аругала и принесите его голову Далару Ткачу Рассвета в Гробницу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Со смертью Аругала мы сможем укрепить власть Темной Госпожи в Лордероне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Далару Ткачу Рассвета в Гробницу, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1015,'Новое пограничье','Внимание, герои!$B$BКруг Кенария ищет смельчаков, готовых исследовать окраины Калимдора! Забытые пустоши, полные неизвестных опасностей, лежат к западу от Tанариса и Прибамбасска. Круг Кенария призывает храбрых героев изучить эти земли.$B$BВсе желающие должны пройти собеседование в Круге Кенария. Обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнасе!','Поговорите с верховным друидом Фэндралом Оленьим Шлемом из дарнасского Анклава Кенария относительно призыва Круга Кенария к изучению окраин Калимдора.','С чего вы решили, что я собираюсь тратить время на таких, как вы, |3-6($C)? Хотя погодите...Дайте мне разобраться с моими повседневными обязанностями, и тогда, может быть, у меня для вас найдется пара минут. Нет, ну разумеется, благо Дарнасса, да что там – Тельдрассила! – это такая ерунда по сравнению с вашим желанием получить новую побрякушку...$B$BЭти недоумки из Лунной поляны, с их призывом на помощь, тратят мое время – не представляю, как выдержу все это?!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое пограничье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимание, герои!$B$BКруг Кенария ищет смельчаков, готовых исследовать окраины Калимдора! Забытые пустоши, полные неизвестных опасностей, лежат к западу от Tанариса и Прибамбасска. Круг Кенария призывает храбрых героев изучить эти земли.$B$BВсе желающие должны пройти собеседование в Круге Кенария. Обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнасе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным друидом Фэндралом Оленьим Шлемом из дарнасского Анклава Кенария относительно призыва Круга Кенария к изучению окраин Калимдора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С чего вы решили, что я собираюсь тратить время на таких, как вы, |3-6($C)? Хотя погодите...Дайте мне разобраться с моими повседневными обязанностями, и тогда, может быть, у меня для вас найдется пара минут. Нет, ну разумеется, благо Дарнасса, да что там – Тельдрассила! – это такая ерунда по сравнению с вашим желанием получить новую побрякушку...$B$BЭти недоумки из Лунной поляны, с их призывом на помощь, тратят мое время – не представляю, как выдержу все это?!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1016,'Отвоевать озеро','Мы бы с легкостью могли отстоять Приют Серебряного Ветра у Орды, если бы наши противники не подчинили себе наших защитников – элементалей воды озера Мистраль.$B$BОдин из шаманов призвал Приливницу, старого и злобного духа воды, которая исказила сущность наших элементалей и обратила их против нас самих. Теперь у нас не остается другого выхода, кроме как отступить к шпилю.$B$BПрошу тебя, отправляйся на восток и отвоюй озеро у Орды. Тогда, возможно, у нас появится шанс вернуть приют.','Убейте 12 злобных элементалей воды и Приливницу.','Поскольку тебе придется разрушить браслеты, чтобы убить элементалей, наверное трудно будет найти те самые, в которых содержится информация, которая нужна для гадального свитка. Ты можешь выменять нужные тебе браслеты у кого-нибудь другого, но, может, у тебя есть уже разгаданный свиток?','[Deprecated] Return to Sentinel Velene Starstrike at Stardust Spire in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвоевать озеро',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы бы с легкостью могли отстоять Приют Серебряного Ветра у Орды, если бы наши противники не подчинили себе наших защитников – элементалей воды озера Мистраль.$B$BОдин из шаманов призвал Приливницу, старого и злобного духа воды, которая исказила сущность наших элементалей и обратила их против нас самих. Теперь у нас не остается другого выхода, кроме как отступить к шпилю.$B$BПрошу тебя, отправляйся на восток и отвоюй озеро у Орды. Тогда, возможно, у нас появится шанс вернуть приют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 злобных элементалей воды и Приливницу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поскольку тебе придется разрушить браслеты, чтобы убить элементалей, наверное трудно будет найти те самые, в которых содержится информация, которая нужна для гадального свитка. Ты можешь выменять нужные тебе браслеты у кого-нибудь другого, но, может, у тебя есть уже разгаданный свиток?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Sentinel Velene Starstrike at Stardust Spire in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1017,'Маг-призыватель','Есть только один маг из нежити в Степях, способный наслать порчу на стольких элементалей воды. И он единственный, кому хватит дури попытаться это сделать. Сарилус Грязнорожденный, наверное, сидит на вершине Вершины Багрового Тумана, да смеется надо мной. $B$B$n, тебе придется проникнуть на вражескую территорию и уничтожить этого мерзавца. Мне надоела его бестолковость, и надо показать ему, что бывает с теми, кто донимает часовых. $B$BУничтожь его и принеси мне его голову. Но соблюдай осторожность, Орда может подкараулить тебя.','Убейте Сарилуса Грязнорожденного и принесите его голову часовому Велене Звездный Всполох в Приют Серебряного Ветра.','Дело сделано? Сарилус Грязнорожденный мертв?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маг-призыватель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть только один маг из нежити в Степях, способный наслать порчу на стольких элементалей воды. И он единственный, кому хватит дури попытаться это сделать. Сарилус Грязнорожденный, наверное, сидит на вершине Вершины Багрового Тумана, да смеется надо мной. $B$B$n, тебе придется проникнуть на вражескую территорию и уничтожить этого мерзавца. Мне надоела его бестолковость, и надо показать ему, что бывает с теми, кто донимает часовых. $B$BУничтожь его и принеси мне его голову. Но соблюдай осторожность, Орда может подкараулить тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Сарилуса Грязнорожденного и принесите его голову часовому Велене Звездный Всполох в Приют Серебряного Ветра.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дело сделано? Сарилус Грязнорожденный мертв?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1018,'Новое пограничье','Внимание, герои!$b$bКруг Кенария ищет отважных, которые помогут исследовать обширное новое пограничье Калимдора! К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши. Круг нуждается в доблестных помощниках!$b$bВсе заинтересованные лица могут обращаться в Круг Кенария. Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утеса.','Обратитесь к верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин Громового Утеса по поводу помощи Кругу Кенария в исследовании границ Калимдора.','Здравствуй, |3-6($C)!$B$BПриятно видеть, что таким, как ты, небезразлично благополучие природы. Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады. Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается.$B$BНаша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий. Помни это, когда будешь действовать от имени Круга, – и добьешься успеха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое пограничье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимание, герои!$b$bКруг Кенария ищет отважных, которые помогут исследовать обширное новое пограничье Калимдора! К западу от Танариса и Прибамбасска простираются неизведанные и опасные пустоши. Круг нуждается в доблестных помощниках!$b$bВсе заинтересованные лица могут обращаться в Круг Кенария. Дополнительные сведения можно получить у верховного друида Хамуула Рунического Тотема на Вершине Старейшин Громового Утеса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин Громового Утеса по поводу помощи Кругу Кенария в исследовании границ Калимдора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуй, |3-6($C)!$B$BПриятно видеть, что таким, как ты, небезразлично благополучие природы. Рассказы о твоих подвигах опережают тебя, и тебе здесь всегда рады. Твой приход внушает мне уверенность, что Круг Кенария получит помощь, в которой нуждается.$B$BНаша связь с Кругом Кенария на Лунной Поляне превыше расовых и политических противоречий. Помни это, когда будешь действовать от имени Круга, – и добьешься успеха.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1019,'Новое пограничье','Внимание, герои!$B$BКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора -запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!$B$BВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнасе!','Обратитесь в дарнасский анклав Кенария к верховному друиду Фэндралу Оленьему Шлему по поводу помощи Кругу Кенария в исследовании границ Калимдора.','С чего ты $Gрешил:решила;, что я буду утруждать себя беседой с $Gтаким:такой;, как ты, |3-6($C)? Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу! Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идет с важностью поиска этой пустяковины для твоей коллекции!$B$BСначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я еще и это сносить должен?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое пограничье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимание, герои!$B$BКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора -запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!$B$BВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнасе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь в дарнасский анклав Кенария к верховному друиду Фэндралу Оленьему Шлему по поводу помощи Кругу Кенария в исследовании границ Калимдора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С чего ты $Gрешил:решила;, что я буду утруждать себя беседой с $Gтаким:такой;, как ты, |3-6($C)? Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу! Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идет с важностью поиска этой пустяковины для твоей коллекции!$B$BСначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я еще и это сносить должен?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1020,'Лекарство Орендила','$n, это лекарство, благословенное светом Элуны, должно помочь больному ребенку. Отнеси его в Астранаар отцу ребенка, Пельтуру Белой Луне.$B$BЧтобы добраться до Астранаара, ступай по дороге сначала на юг, потом на восток. Но если хочешь добраться туда побыстрее – поговори с часовым Аваной.','Принесите лекарство Орендила Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.','Это от Орендила?$B$BОн славен знанием трав и лекарским искусством. Это лекарство вселяет в меня надежду, которой прежде у меня почти не было...','Прошу прощения, но у меня нет времени на разговоры. Мое дитя, моя Релара смертельно больна!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лекарство Орендила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, это лекарство, благословенное светом Элуны, должно помочь больному ребенку. Отнеси его в Астранаар отцу ребенка, Пельтуру Белой Луне.$B$BЧтобы добраться до Астранаара, ступай по дороге сначала на юг, потом на восток. Но если хочешь добраться туда побыстрее – поговори с часовым Аваной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите лекарство Орендила Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это от Орендила?$B$BОн славен знанием трав и лекарским искусством. Это лекарство вселяет в меня надежду, которой прежде у меня почти не было...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прошу прощения, но у меня нет времени на разговоры. Мое дитя, моя Релара смертельно больна!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1021,'Сатиры коварны! Дриады в опасности!','Послушай, я не знаю, кто ты, но мне нужна помощь. Мои сестры отправились отнять у одного сатира Ветвь Кенария. Они сказали, что скоро вернутся, но уже целых два дня прошло!$B$B$n, ты $Gдолжен:должна; найти их! Они искали развалины храма ночных эльфов в Ксавиане на северо-западе. Не знаю, что и думать. Найди Анилию, это она повела их на поиски.','Найдите в Ксавиане Анилию.','Судя по зияющей в боку ране, Анилия на грани смерти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сатиры коварны! Дриады в опасности!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, я не знаю, кто ты, но мне нужна помощь. Мои сестры отправились отнять у одного сатира Ветвь Кенария. Они сказали, что скоро вернутся, но уже целых два дня прошло!$B$B$n, ты $Gдолжен:должна; найти их! Они искали развалины храма ночных эльфов в Ксавиане на северо-западе. Не знаю, что и думать. Найди Анилию, это она повела их на поиски.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Ксавиане Анилию.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Судя по зияющей в боку ране, Анилия на грани смерти.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1022,'Воющая долина','Хотя мы затратили много средств и сил на то, чтобы вытеснить остатки демонов из Оскверненного леса на север, успехи наши невелики. Нам удалось не допустить большую часть демонов в Ясеневый лес.$b$bНа севере, у границы Оскверненного леса, разрушенное святилище Мел\'Тандрис захватили загадочные волколюди. Из-за их пронзительных воплей это место называют теперь Воющей долиной. Фолиант Мел\'Тандрис, что хранится в святилище может пролить свет на появление там волколюдей.','Отправляйтесь в Воющую долину, изучите фолиант Мел\'Тандрис, затем возвращайтесь к часовому Мелирии Ледяной Тени в Лесную Песнь.','Фолиант Мел\'Тандрис действует странным образом. События, которые он записывает, события, которые он показывает... Никто тольком не понимает, почему он делает то, что делает.$B$BТем не менее, понятно, что предмет, который получила жрица Звездная Песня – эта коса Элуны – требует дальнейшего исследования.','Фолиант святыни - загадочный объект. Это не книга в традиционном понимании. Листы фолианта были благословлены самой Мел\'Тандрис, и на их страницах записаны важные события.$B$BМне трудно это объяснить. Если вы пойдете в святыню, йо...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воющая долина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя мы затратили много средств и сил на то, чтобы вытеснить остатки демонов из Оскверненного леса на север, успехи наши невелики. Нам удалось не допустить большую часть демонов в Ясеневый лес.$b$bНа севере, у границы Оскверненного леса, разрушенное святилище Мел\'Тандрис захватили загадочные волколюди. Из-за их пронзительных воплей это место называют теперь Воющей долиной. Фолиант Мел\'Тандрис, что хранится в святилище может пролить свет на появление там волколюдей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Воющую долину, изучите фолиант Мел\'Тандрис, затем возвращайтесь к часовому Мелирии Ледяной Тени в Лесную Песнь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фолиант Мел\'Тандрис действует странным образом. События, которые он записывает, события, которые он показывает... Никто тольком не понимает, почему он делает то, что делает.$B$BТем не менее, понятно, что предмет, который получила жрица Звездная Песня – эта коса Элуны – требует дальнейшего исследования.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Фолиант святыни - загадочный объект. Это не книга в традиционном понимании. Листы фолианта были благословлены самой Мел\'Тандрис, и на их страницах записаны важные события.$B$BМне трудно это объяснить. Если вы пойдете в святыню, йо...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1023,'Пропавший камень','Осматривая вещи Терониса, вы находите дневник, который все еще в неплохом состоянии.$B$BВы берете дневник и оставляете труп Терониса. $B$BОстается только найти камень, который искал Теронис. Орендил говорила, что он где-то здесь. Возможно, его забрали эти щупальца...','Найдите светящийся самоцвет.','[Deprecated] Return to Orendil Broadleaf at Maestra\'s Post in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осматривая вещи Терониса, вы находите дневник, который все еще в неплохом состоянии.$B$BВы берете дневник и оставляете труп Терониса. $B$BОстается только найти камень, который искал Теронис. Орендил говорила, что он где-то здесь. Возможно, его забрали эти щупальца...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите светящийся самоцвет.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Orendil Broadleaf at Maestra\'s Post in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1024,'Посылка для дриад','А, вот и ты, $n. Я изучила записи Терониса, и пришла к выводу, что твоим следующим действием будет поиск остальных фрагментов созданного Дартолом жезла.$B$BЯ бы для начала пошла на восток вдоль дороги, ведущей к башне в Ночных лесах.$B$BДриада Шаэл\'дрин будет тебе лучшим проводником. Найди ее.$B$BВозьми с собой этот самоцвет – он может понадобиться Шаэл\'дрин, если она решит помочь тебе восстановить жезл.','Найдите Шаэлдрин у башни в Ночных лесах в Ясеневом лесу.','О, так тебя послала Раэна? Тогда это и правда серьезное дело. Чем я могу тебе помочь?','Здравствуй. Как поживаешь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посылка для дриад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, вот и ты, $n. Я изучила записи Терониса, и пришла к выводу, что твоим следующим действием будет поиск остальных фрагментов созданного Дартолом жезла.$B$BЯ бы для начала пошла на восток вдоль дороги, ведущей к башне в Ночных лесах.$B$BДриада Шаэл\'дрин будет тебе лучшим проводником. Найди ее.$B$BВозьми с собой этот самоцвет – он может понадобиться Шаэл\'дрин, если она решит помочь тебе восстановить жезл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Шаэлдрин у башни в Ночных лесах в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, так тебя послала Раэна? Тогда это и правда серьезное дело. Чем я могу тебе помочь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Здравствуй. Как поживаешь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1025,'Лучшая защита – нападение','Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе еще одно поручение, прежде чем ты отправишься к лунному колодцу.$B$BНа дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников. Их извращенный разум питается страхом, а кровожадность утоляется кровью невинных жертв.$B$BПомоги часовым защитить эти края, отплати этим чудовищам их же монетой.$B$BДумаю, их лагерь находится к югу от дороги... будь $Gосторожен:осторожна;.','Убейте 1 дозорного, 2 ведмедей, 10 тотемистов и 12 воинов из племени Гиблой Чащи, а затем вернитесь к Раэне Волкопас в Астранаар.','Славная работа, $n. Спасибо тебе.','Фурболги не всегда были нашими врагами, $N. Но времена меняются, и здесь, в темном лесу, уже не время покоя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучшая защита – нападение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе еще одно поручение, прежде чем ты отправишься к лунному колодцу.$B$BНа дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников. Их извращенный разум питается страхом, а кровожадность утоляется кровью невинных жертв.$B$BПомоги часовым защитить эти края, отплати этим чудовищам их же монетой.$B$BДумаю, их лагерь находится к югу от дороги... будь $Gосторожен:осторожна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 1 дозорного, 2 ведмедей, 10 тотемистов и 12 воинов из племени Гиблой Чащи, а затем вернитесь к Раэне Волкопас в Астранаар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Славная работа, $n. Спасибо тебе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Фурболги не всегда были нашими врагами, $N. Но времена меняются, и здесь, в темном лесу, уже не время покоя.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1026,'Поиски древка','Хотелось бы мне, чтобы у тебя были более хорошие новости.$B$BРаэна права, мне многое известно о творении Дартола и древнях этих краев – или было известно прежде. Теперь все они осквернены, их природа искажена.$B$BЕсли твоя цель – найти еще один фрагмент жезла, то тебе придется найти ключ, чтобы отпереть сундук, в котором он лежит.$B$BДеревянный ключ – на одном из древней к северо-востоку отсюда, близ Оскверненного леса в Воющей долине. Как только добудешь его, ищи небольшую лощинку в долине... Сундук должен быть спрятан где-то там.','Найдите деревянный ключ и с его помощью получите железное древко жезла Дартола.','Меня беспокоит то, что древни подверглись порче. Хотелось бы мне побольше сделать для них.','[Deprecated] Return to Shael\'dryn at Raynewood Tower in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски древка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотелось бы мне, чтобы у тебя были более хорошие новости.$B$BРаэна права, мне многое известно о творении Дартола и древнях этих краев – или было известно прежде. Теперь все они осквернены, их природа искажена.$B$BЕсли твоя цель – найти еще один фрагмент жезла, то тебе придется найти ключ, чтобы отпереть сундук, в котором он лежит.$B$BДеревянный ключ – на одном из древней к северо-востоку отсюда, близ Оскверненного леса в Воющей долине. Как только добудешь его, ищи небольшую лощинку в долине... Сундук должен быть спрятан где-то там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите деревянный ключ и с его помощью получите железное древко жезла Дартола.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Меня беспокоит то, что древни подверглись порче. Хотелось бы мне побольше сделать для них.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Shael\'dryn at Raynewood Tower in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (1027,'Притвориться мертвым','Найдите последний фрагмент жезла Дартола, Железное навершие.','Ты нашел последний фрагмент? Тебе очень повезло... И Раэне тоже.$B$BКак понимаю, нам надо попытаться собрать его, да?','[Deprecated] Return to Shael\'dryn at Raynewood Tower in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Притвориться мертвым',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите последний фрагмент жезла Дартола, Железное навершие.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты нашел последний фрагмент? Тебе очень повезло... И Раэне тоже.$B$BКак понимаю, нам надо попытаться собрать его, да?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Shael\'dryn at Raynewood Tower in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1028,'Раэна – санитар Ясеневого леса','Вот собранный жезл, $n. Восстановить его было просто... Труднее будет найти святилище, в котором жезл можно будет наполнить силой.$B$BНо при твоих целеустремленности и усердии, после всех твоих достижений тебе не слишком трудно будет его найти.$B$BСтупай на юго-восток – там очень мало торных дорог, так что будь осторожнее – и посматривай на север. Святилище скрыто в горах, что окружают эту долину.$B$BКак только ты окажешься там, положи жезл в святилище... а остальное сделает магия. Хе-хе.','Найдите потаенное святилище и снова наполните чарами жезл Дартола.','Когда свечение угасает, вы видите в купели святилища заново наполненный чарами жезл.','Вы ощущаете ненавязчивую, но мощную силу в святилище и окружающих деревьях.$B$BВы кладете жезл в святилище, и вас окутывает тихий звон, а святилище начинает светиться...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раэна – санитар Ясеневого леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот собранный жезл, $n. Восстановить его было просто... Труднее будет найти святилище, в котором жезл можно будет наполнить силой.$B$BНо при твоих целеустремленности и усердии, после всех твоих достижений тебе не слишком трудно будет его найти.$B$BСтупай на юго-восток – там очень мало торных дорог, так что будь осторожнее – и посматривай на север. Святилище скрыто в горах, что окружают эту долину.$B$BКак только ты окажешься там, положи жезл в святилище... а остальное сделает магия. Хе-хе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите потаенное святилище и снова наполните чарами жезл Дартола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда свечение угасает, вы видите в купели святилища заново наполненный чарами жезл.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы ощущаете ненавязчивую, но мощную силу в святилище и окружающих деревьях.$B$BВы кладете жезл в святилище, и вас окутывает тихий звон, а святилище начинает светиться...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1029,'Возвращение к Раэне','Советую тебе найти Раэну и сказать ей, что жезл воссоздан. Я уверена, она знает, куда тебе направиться дальше. $B$BБудь $gосторожен:осторожна;... сила, заключенная в этом жезле, может послужить как добру, так и злу. Надеюсь, вы с Раэной знаете, что делаете.$B$BУдачи, $n.','Вернитесь к Раэне Волкопас в Астранаар, что в Ясеневом лесу, и передайте ей жезл Дартола.','Ты собрал жезл, который отправил тебя искать Теронис? Это приятно слышать.$B$BТеронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Раэне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Советую тебе найти Раэну и сказать ей, что жезл воссоздан. Я уверена, она знает, куда тебе направиться дальше. $B$BБудь $gосторожен:осторожна;... сила, заключенная в этом жезле, может послужить как добру, так и злу. Надеюсь, вы с Раэной знаете, что делаете.$B$BУдачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Раэне Волкопас в Астранаар, что в Ясеневом лесу, и передайте ей жезл Дартола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты собрал жезл, который отправил тебя искать Теронис? Это приятно слышать.$B$BТеронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1030,'Жезл Дартола','Увы, я не могу точно знать, что Теронис собирался делать дальше, но если он сказал правду о силе жезла, то ты можешь с его помощью изменить облик, притворившись фурболгом.$B$BПолагаю, он намеревался использовать его мощь, чтобы подобраться поближе к этим мерзостным тварям, но даже не затронутые порчей существа убили бы его, не будь он осторожен. Изменив облик, Дартол намеревался поговорить с фурболгом, которого не коснулась рука скверны.$B$BЯ бы начала с существа по имени Кролг. Ищи его к юго-востоку от озера Мистраль.','Найдите Кролга в его хижине в Ясеневом лесу и поговорите с ним при помощи жезла преображения Дартола.','Да-да... ты мой сородич, но ты здоровый. Пока еще чистый.$B$BНе знаю, как уж тебе удалось избежать тех злодеяний, что ночные эльфы обрушили на наш народ, но я рад, что больше я не одинок.$B$BНынче порча бежит в жилах наших сородичей, малыш, порча, насланная на нас спесивыми ночными эльфами. Это они с нами такое сделали... Они виноваты в том, что меня изгнали из племени.$B$BПо ночам я по-прежнему вижу костры в темноте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жезл Дартола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Увы, я не могу точно знать, что Теронис собирался делать дальше, но если он сказал правду о силе жезла, то ты можешь с его помощью изменить облик, притворившись фурболгом.$B$BПолагаю, он намеревался использовать его мощь, чтобы подобраться поближе к этим мерзостным тварям, но даже не затронутые порчей существа убили бы его, не будь он осторожен. Изменив облик, Дартол намеревался поговорить с фурболгом, которого не коснулась рука скверны.$B$BЯ бы начала с существа по имени Кролг. Ищи его к юго-востоку от озера Мистраль.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Кролга в его хижине в Ясеневом лесу и поговорите с ним при помощи жезла преображения Дартола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да... ты мой сородич, но ты здоровый. Пока еще чистый.$B$BНе знаю, как уж тебе удалось избежать тех злодеяний, что ночные эльфы обрушили на наш народ, но я рад, что больше я не одинок.$B$BНынче порча бежит в жилах наших сородичей, малыш, порча, насланная на нас спесивыми ночными эльфами. Это они с нами такое сделали... Они виноваты в том, что меня изгнали из племени.$B$BПо ночам я по-прежнему вижу костры в темноте.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1031,'Ветвь Кенария','Анилия кладет руки вам на плечи и привлекает вас к себе. Задыхаясь, она показывает на находящуюся на севере арку, затем глаза ее закрываются, и из последних сил она шепчет: "Он забрал ее... Гелтарис..." И в душе вы понимаете, что Анилия умирает, жаждая, чтобы Ветвь Кенария была возвращена дриадам.','Добудьте Ветвь Кенария.','Анилия умерла? Нет, этого не может быть! Кажется, только вчера мы вместе бегали и играли в лесах!$B$BСчастливые дни теперь миновали...','Ты нашел их? Что сказала Анилия? Где она?','Вернитесь к Иллиане в Лесную Песнь, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветвь Кенария',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Анилия кладет руки вам на плечи и привлекает вас к себе. Задыхаясь, она показывает на находящуюся на севере арку, затем глаза ее закрываются, и из последних сил она шепчет: "Он забрал ее... Гелтарис..." И в душе вы понимаете, что Анилия умирает, жаждая, чтобы Ветвь Кенария была возвращена дриадам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте Ветвь Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Анилия умерла? Нет, этого не может быть! Кажется, только вчера мы вместе бегали и играли в лесах!$B$BСчастливые дни теперь миновали...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел их? Что сказала Анилия? Где она?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иллиане в Лесную Песнь, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1032,'Убийство сатиров!','Поверить не могу – Анилии нет! Как часто мы вместе резвились в лесах... Я почти ощущаю... печаль. $B$BЯ знаю, от чего мне станет лучше. Пожалуйста, убей сатиров, что отняли у меня Анилию! Принеси мне их рога в доказательство своего деяния, и я буду навек тебе благодарна.','Добудьте 16 рогов сатиров.','Спасибо тебе, $Gдобрый:добрая:r; |3-6($r). Душа моей сестры возрадуется твоим деяниям.','Пожалуйста, помоги мне отомстить за смерть Анилии.','Вернитесь к Иллиане в Лесную Песнь, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убийство сатиров!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поверить не могу – Анилии нет! Как часто мы вместе резвились в лесах... Я почти ощущаю... печаль. $B$BЯ знаю, от чего мне станет лучше. Пожалуйста, убей сатиров, что отняли у меня Анилию! Принеси мне их рога в доказательство своего деяния, и я буду навек тебе благодарна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 16 рогов сатиров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, $Gдобрый:добрая:r; |3-6($r). Душа моей сестры возрадуется твоим деяниям.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пожалуйста, помоги мне отомстить за смерть Анилии.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иллиане в Лесную Песнь, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1033,'Слеза Элуны','Я надеялся, что лекарство Орендила спасет Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери. Мы должны найти более мощное средство! К счастью, Орендил говорил мне, какие еще он попытается применить лекарства, если первое не поможет.$B$BСлеза Элуны – это такой камень, который можно найти только в одном месте – у обмелевшего озера Ирис, уничтоженном при извержении вулкана Громовой Вершины. Оно находится к востоку от Астранаара. Орендил сказал, что этот камень снимает порчу... прошу тебя, $n, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!','Найдите Слезу Элуны.','Вернитесь к Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слеза Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я надеялся, что лекарство Орендила спасет Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери. Мы должны найти более мощное средство! К счастью, Орендил говорил мне, какие еще он попытается применить лекарства, если первое не поможет.$B$BСлеза Элуны – это такой камень, который можно найти только в одном месте – у обмелевшего озера Ирис, уничтоженном при извержении вулкана Громовой Вершины. Оно находится к востоку от Астранаара. Орендил сказал, что этот камень снимает порчу... прошу тебя, $n, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Слезу Элуны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пельтуру Белой Луне в Астранаар, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1034,'Руины Звездной Пыли','Слеза Элуны немного облегчила страдания моей дочери. Кошмары стали реже ее мучить, хвала богине. Но... лихорадка все еще сжигает ее.$B$BОрендил рассказал мне о морозной пыли, которую находят среди руин Звездной Пыли. Может, она усмирит лихорадку Релары. Собери немного этой пыли, прошу тебя, и принеси ее мне.$B$BРуины Звездной Пыли находятся на юге, $n. Да ускорит твой шаг Элуна!','Принесите 5 горстей звездной пыли Пельтуру в Астранаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины Звездной Пыли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слеза Элуны немного облегчила страдания моей дочери. Кошмары стали реже ее мучить, хвала богине. Но... лихорадка все еще сжигает ее.$B$BОрендил рассказал мне о морозной пыли, которую находят среди руин Звездной Пыли. Может, она усмирит лихорадку Релары. Собери немного этой пыли, прошу тебя, и принеси ее мне.$B$BРуины Звездной Пыли находятся на юге, $n. Да ускорит твой шаг Элуна!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 горстей звездной пыли Пельтуру в Астранаар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1035,'Зеркало Небес','Лихорадка Релары прошла, но она еще очень слаба. Я не верю, что только время вернет ей былую силу. Мне кажется, тут нужна мощь лунного камня.$B$BМы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники.$B$BИх предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты $Gдолжен:должна; отнять лунные камни у Оракула.$B$BИ, боюсь, для этого тебе придется его убить.','Отнимите лунный камень Упавшего Неба у Чащобного Оракула и принесите его Пельтуру в Астранаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зеркало Небес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лихорадка Релары прошла, но она еще очень слаба. Я не верю, что только время вернет ей былую силу. Мне кажется, тут нужна мощь лунного камня.$B$BМы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники.$B$BИх предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты $Gдолжен:должна; отнять лунные камни у Оракула.$B$BИ, боюсь, для этого тебе придется его убить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнимите лунный камень Упавшего Неба у Чащобного Оракула и принесите его Пельтуру в Астранаар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (1036,'Суши весла, сухопутная крыса','Поговорите с командиром флота Фираллоном на борту "Кровавой завесы" на побережье Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суши весла, сухопутная крыса',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром флота Фираллоном на борту "Кровавой завесы" на побережье Тернистой долины.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1037,'Велинда Песнь Звезд','Велинда Песнь Звезд была моей предшественницей здесь, в Ясеневом лесу. Поначалу казалось, что она держит под контролем ситуацию в Оскверненном лесу, но понемногу ее усилия стали сходить на нет. И однажды она просто исчезла.$b$bМеня послали сюда продолжить ее труды. Но боюсь, я ничего не знаю об этой жрице. Возможно, Тин\'тель Танец Клинка, одна из командиров часовых, знает подробности ее исчезновения, о которых не знаю я.$b$bНаверняка она поймет значение такой информации.','Поговорите с Тин\'тель Танцем Клинка на Террасе Воинов в Дарнасе.','Велинда Песнь Звезд? То, что эта жрица пропала некоторое время назад, известно всем. Что касается событий, окружавших ее исчезновение... Чтобы поделиться такой информацией, мне нужна веская причина.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Велинда Песнь Звезд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Велинда Песнь Звезд была моей предшественницей здесь, в Ясеневом лесу. Поначалу казалось, что она держит под контролем ситуацию в Оскверненном лесу, но понемногу ее усилия стали сходить на нет. И однажды она просто исчезла.$b$bМеня послали сюда продолжить ее труды. Но боюсь, я ничего не знаю об этой жрице. Возможно, Тин\'тель Танец Клинка, одна из командиров часовых, знает подробности ее исчезновения, о которых не знаю я.$b$bНаверняка она поймет значение такой информации.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тин\'тель Танцем Клинка на Террасе Воинов в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Велинда Песнь Звезд? То, что эта жрица пропала некоторое время назад, известно всем. Что касается событий, окружавших ее исчезновение... Чтобы поделиться такой информацией, мне нужна веская причина.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1038,'Эффекты Велинды','Значит, это ты вычитал в фолианте Мел\'Тандрис? Думаю, ничего страшного не будет, если ты осмотришь ее вещи. Этот ключ позволит тебе отпереть сундук, в котором она держала свои пожитки в казарме часовых. Она вела дневник, и если что-то можно узнать, то только из него.$b$bДолжна тебе сказать, что часовые считают, что у нее была причина уйти, и ждут ее возвращения в любой момент. Эта жрица многими своими делами заслужила наше доверие.','Поищите в сундуке Велинды ее дневник, затем принесите его вместе с ключом Тинтэль Танцующий Клинок в Дарнас.','Что удалось найти?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эффекты Велинды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, это ты вычитал в фолианте Мел\'Тандрис? Думаю, ничего страшного не будет, если ты осмотришь ее вещи. Этот ключ позволит тебе отпереть сундук, в котором она держала свои пожитки в казарме часовых. Она вела дневник, и если что-то можно узнать, то только из него.$b$bДолжна тебе сказать, что часовые считают, что у нее была причина уйти, и ждут ее возвращения в любой момент. Эта жрица многими своими делами заслужила наше доверие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите в сундуке Велинды ее дневник, затем принесите его вместе с ключом Тинтэль Танцующий Клинок в Дарнас.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что удалось найти?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1039,'Порт в Степях','Кабестан – единственный порт в Степях. Скорее всего, Велинда нашла там торговое судно, которое шло в бухту Черноводья в Азероте. Мы ограничили сделки с гоблинами, которые руководят портом, но смотритель пристани наверняка знает, какие пассажиры взошли на борт, а какие сошли на берег.$b$bСледуй по дороге на юго-восток через Ясеневый лес, и попадешь в Степи. Смотри по сторонам, $n, эти края патрулируют солдаты Орды. Но в порту ты будешь в безопасности.','Поговорите с управляющим пристанью Головокружилкинсом в Кабестане.','|3-6($r)? Должен сказать, твоих сородичей тут у нас нечасто увидишь. Кого-то ищешь, да? Минуточку, сейчас гляну в своих учетных списках.$B$BЧерез порт проходит куча народу, так что подожди минутку, сделай милость.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порт в Степях',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кабестан – единственный порт в Степях. Скорее всего, Велинда нашла там торговое судно, которое шло в бухту Черноводья в Азероте. Мы ограничили сделки с гоблинами, которые руководят портом, но смотритель пристани наверняка знает, какие пассажиры взошли на борт, а какие сошли на берег.$b$bСледуй по дороге на юго-восток через Ясеневый лес, и попадешь в Степи. Смотри по сторонам, $n, эти края патрулируют солдаты Орды. Но в порту ты будешь в безопасности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с управляющим пристанью Головокружилкинсом в Кабестане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','|3-6($r)? Должен сказать, твоих сородичей тут у нас нечасто увидишь. Кого-то ищешь, да? Минуточку, сейчас гляну в своих учетных списках.$B$BЧерез порт проходит куча народу, так что подожди минутку, сделай милость.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1040,'Дорога до Пиратской Бухты','А, наконец-то, нашел. Надо было сразу сказать, что она проезжала здесь давно. Посмотрим.$B$BВелинда. Оплатила проезд до Пиратской Бухты на "Черной Скопе". Никаких дополнительных пометок нет – значит, она благополучно добралась до места назначения. $b$bБольше ничем я помочь не могу, хотя она спрашивала, какие средства передвижения есть по ту сторону моря, и я упомянул Раззгота, водящего караваны из Пиратской Бухты. Быть может, Велинда отправилась с ним. $b$bНу все, давай, иди. Не весь же день с тобой болтать.','Плывите в Пиратскую Бухту и поговорите с караванщиком Раззготом.','Да? Не похоже, чтобы ты хотел отправить какой-нибудь груз, так что ты либо хочешь устроиться подработать в мой караван – а сейчас работы нет, – либо не к тому обратился.$B$BЯ угадал?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога до Пиратской Бухты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, наконец-то, нашел. Надо было сразу сказать, что она проезжала здесь давно. Посмотрим.$B$BВелинда. Оплатила проезд до Пиратской Бухты на "Черной Скопе". Никаких дополнительных пометок нет – значит, она благополучно добралась до места назначения. $b$bБольше ничем я помочь не могу, хотя она спрашивала, какие средства передвижения есть по ту сторону моря, и я упомянул Раззгота, водящего караваны из Пиратской Бухты. Быть может, Велинда отправилась с ним. $b$bНу все, давай, иди. Не весь же день с тобой болтать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Плывите в Пиратскую Бухту и поговорите с караванщиком Раззготом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да? Не похоже, чтобы ты хотел отправить какой-нибудь груз, так что ты либо хочешь устроиться подработать в мой караван – а сейчас работы нет, – либо не к тому обратился.$B$BЯ угадал?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1041,'Путь каравана','Оказывается, я ошибался насчет тебя, а я это не часто признаю.$B$BОказывается, я помню эту Велинду. Не каждый день жрица ночных эльфов желает отправиться в путь со старым грязным – но превосходным для транспортировки товаров – караваном вроде моего.$B$BПо пути на север мы разделились, и она направилась в Темнолесье. Тамошний клерк ведет записи. Может, он знает что полезное.$B$BОсторожнее в джунглях, они даже в лучшие времена – опасное место.','Поговорите с клерком Далтри из Темнолесья.','В последние годы случилось много странного, и я стараюсь вести записи про всех чужаков. Никогда не узнаешь, что пригодится... Хотя когда эти записи оказываются нужны, добра не жди... Нет, про вашу Велинду я не хочу сказать ничего дурного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь каравана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оказывается, я ошибался насчет тебя, а я это не часто признаю.$B$BОказывается, я помню эту Велинду. Не каждый день жрица ночных эльфов желает отправиться в путь со старым грязным – но превосходным для транспортировки товаров – караваном вроде моего.$B$BПо пути на север мы разделились, и она направилась в Темнолесье. Тамошний клерк ведет записи. Может, он знает что полезное.$B$BОсторожнее в джунглях, они даже в лучшие времена – опасное место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с клерком Далтри из Темнолесья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В последние годы случилось много странного, и я стараюсь вести записи про всех чужаков. Никогда не узнаешь, что пригодится... Хотя когда эти записи оказываются нужны, добра не жди... Нет, про вашу Велинду я не хочу сказать ничего дурного.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1042,'Семья Карвин','Нет, у меня не сохранилось записей о пребывании Велинды Песни Звезд в Темнолесье... Хотя, прошу прощения за прямоту, не могу представить, чтобы жрица ночных эльфов снимала комнату в таверне, если ты понимаешь, о чем я.$b$bА вот о волко-людях я слышал, и не раз. Только недавно Калор явился в город, неся целую связку их голов. Он работает на Карвинов, которые охотятся на демонов и прочих чудовищ. Поговори с Джонатаном, главой их дома.','Поговорите с Джонатаном Карвином в Темнолесье.','Темные настали времена. Каждая ветвь в лесу нашептывает дурные вести, зло таится под каждым камнем.$B$BИ в такую пору незнакомец приходит в мой дом и задает вопросы про воргенов... Прощения за свои подозрения я просить не буду, зато потребую ответить на них.$B$BИ получу ответ.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семья Карвин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет, у меня не сохранилось записей о пребывании Велинды Песни Звезд в Темнолесье... Хотя, прошу прощения за прямоту, не могу представить, чтобы жрица ночных эльфов снимала комнату в таверне, если ты понимаешь, о чем я.$b$bА вот о волко-людях я слышал, и не раз. Только недавно Калор явился в город, неся целую связку их голов. Он работает на Карвинов, которые охотятся на демонов и прочих чудовищ. Поговори с Джонатаном, главой их дома.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джонатаном Карвином в Темнолесье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Темные настали времена. Каждая ветвь в лесу нашептывает дурные вести, зло таится под каждым камнем.$B$BИ в такую пору незнакомец приходит в мой дом и задает вопросы про воргенов... Прощения за свои подозрения я просить не буду, зато потребую ответить на них.$B$BИ получу ответ.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1043,'Коса Элуны','Кажется, ты говоришь правду... Я не до конца понимаю твои мотивы, но если ты $Gготов:готова; избавить Сумеречный лес хотя бы от небольшой части воргенов, я не буду допытываться. Важен результат.$b$bВоргены захватили рудник на юге. Они появились внезапно, но, насколько нам известно, нашествие началось именно с рудника.$b$bСтупай по своим делам, но если найдешь что-нибудь важное, расскажи об этом мне. Мы готовы принять любую помощь в нашей войне с силами зла.','Отыщите признаки местонахождения Косы Элуны и вернитесь к Джонатану Карвину в Темнолесье.','Интересные вещи ты рассказываешь, $C. Хотя семья Карвин не настолько влиятельна, чтобы добраться до корня проблемы и решить ее раз и навсегда, мы делаем все, что в наших силах, чтобы уменьшить число воргенов в Сумеречном лесу.$B$BЯ уже велел Калору уделить этому первоочередное внимание.','Лес опасен для неподготовленных. Держите оружие под рукой, а свой ум - еще ближе, иначе ваше следующее путешествие в лес с привидениями может оказаться последним.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коса Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, ты говоришь правду... Я не до конца понимаю твои мотивы, но если ты $Gготов:готова; избавить Сумеречный лес хотя бы от небольшой части воргенов, я не буду допытываться. Важен результат.$b$bВоргены захватили рудник на юге. Они появились внезапно, но, насколько нам известно, нашествие началось именно с рудника.$b$bСтупай по своим делам, но если найдешь что-нибудь важное, расскажи об этом мне. Мы готовы принять любую помощь в нашей войне с силами зла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите признаки местонахождения Косы Элуны и вернитесь к Джонатану Карвину в Темнолесье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интересные вещи ты рассказываешь, $C. Хотя семья Карвин не настолько влиятельна, чтобы добраться до корня проблемы и решить ее раз и навсегда, мы делаем все, что в наших силах, чтобы уменьшить число воргенов в Сумеречном лесу.$B$BЯ уже велел Калору уделить этому первоочередное внимание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лес опасен для неподготовленных. Держите оружие под рукой, а свой ум - еще ближе, иначе ваше следующее путешествие в лес с привидениями может оказаться последним.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1044,'Полученные ответы','Мы разберемся с воргенами, не беспокойся. Искореним зло, которое твоя подруга невольно принесла в наши леса. Мы не в обиде на нее. Странные вещи творятся в наши времена, $n, и тьма не ведает пощады.$B$BНе буду тебя задерживать. Уверен, многие захотят узнать о том, что ты $gобнаружил:обнаружила; в рудниках Сумеречного леса.','Вернитесь к Тин\'тель Танцу Клинка в Дарнас.','Так вот какова судьба Велинды? Верховная жрица огорчится, услышав об этом – они очень дружили до исчезновения Велинды. И все же Коса Элуны несомненно была дарована Велинде нашей богиней, и очень плохо, что этот священный предмет попал в недобрые руки.$B$BВпрочем, это отдельный разговор. Я премного благодарна тебе за твои достижения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полученные ответы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы разберемся с воргенами, не беспокойся. Искореним зло, которое твоя подруга невольно принесла в наши леса. Мы не в обиде на нее. Странные вещи творятся в наши времена, $n, и тьма не ведает пощады.$B$BНе буду тебя задерживать. Уверен, многие захотят узнать о том, что ты $gобнаружил:обнаружила; в рудниках Сумеречного леса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Тин\'тель Танцу Клинка в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так вот какова судьба Велинды? Верховная жрица огорчится, услышав об этом – они очень дружили до исчезновения Велинды. И все же Коса Элуны несомненно была дарована Велинде нашей богиней, и очень плохо, что этот священный предмет попал в недобрые руки.$B$BВпрочем, это отдельный разговор. Я премного благодарна тебе за твои достижения.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1045,'Новое украшение','Я уверен, что этот погибший волшебник, Дартол, намеревался использовать силу жезла для того, чтобы подчинить и уничтожить нас – точно так же, как ночные эльфы и орки. Но теперь у нас появился шанс использовать эту штуку по другому назначению.$B$BРэн Кровавый Клык – король всех фурболгов Ясеневого леса. Его племя обладает огромной силой и обитает в лагере на востоке.$B$BУбей их всех и принеси мне череп вождя. Пусть эта вещь хоть раз послужит благому делу.','Добудьте череп Рэна Кровавого Клыка и жезл Дартола.','Хорошая работа.$B$BЛес все еще осквернен, но мы по крайней мере знаем, что сделали хоть немного для того, чтобы вернуть его прежнюю красоту. Если пожелаешь снова вернуться ко мне, я буду рад обществу сородича.$B$BУдачи тебе. Возможно, наши племена снова встретятся в не столь жестокие времена.','Ты еще не $Gубил:убила; Рэна?$B$BДаже ночные эльфы не заслуживают его злобы. Его ненависть пылает даже ярче моей, но он уже не владеет собственным разумом. Он – угроза для всех исконных обитателей этого леса.','[Deprecated] Return to Krolg at Krolg\'s Hut in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое украшение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уверен, что этот погибший волшебник, Дартол, намеревался использовать силу жезла для того, чтобы подчинить и уничтожить нас – точно так же, как ночные эльфы и орки. Но теперь у нас появился шанс использовать эту штуку по другому назначению.$B$BРэн Кровавый Клык – король всех фурболгов Ясеневого леса. Его племя обладает огромной силой и обитает в лагере на востоке.$B$BУбей их всех и принеси мне череп вождя. Пусть эта вещь хоть раз послужит благому делу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте череп Рэна Кровавого Клыка и жезл Дартола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа.$B$BЛес все еще осквернен, но мы по крайней мере знаем, что сделали хоть немного для того, чтобы вернуть его прежнюю красоту. Если пожелаешь снова вернуться ко мне, я буду рад обществу сородича.$B$BУдачи тебе. Возможно, наши племена снова встретятся в не столь жестокие времена.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты еще не $Gубил:убила; Рэна?$B$BДаже ночные эльфы не заслуживают его злобы. Его ненависть пылает даже ярче моей, но он уже не владеет собственным разумом. Он – угроза для всех исконных обитателей этого леса.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Krolg at Krolg\'s Hut in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1046,'Истинная сила жезла','А теперь возьми жезл, воспользуйся его силой и поговори с моим братом, Ота Веном.$B$BОта сейчас находится среди других фурболгов, захваченных орками. Его содержат в огромной клетке на северной стороне Приюта Серебряного Ветра. Этот жезл поможет тебе убедить Ота и других фурболгов поднять восстание и выступить против Орды.$B$BЭто моя последняя просьба; выполнив ее, ты можешь идти дальше по дороге жизни. Но куда бы не завела тебя судьба, знай, что в моем лице ты $Gобрел:обрела; верного друга.','Используя жезл Дартола, поговорите с Ота Веном и уговорите его поднять восстание против ордынских захватчиков.','Часовые здесь, в Ясеневом лесу, делают что могут, но лишь благодаря таким |3-6($r)ям как ты, мы не сдаем своих позиций.','Восстание фурболгов началось.','[Deprecated] Speak with Raene Wolfrunner at Astranaar in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истинная сила жезла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь возьми жезл, воспользуйся его силой и поговори с моим братом, Ота Веном.$B$BОта сейчас находится среди других фурболгов, захваченных орками. Его содержат в огромной клетке на северной стороне Приюта Серебряного Ветра. Этот жезл поможет тебе убедить Ота и других фурболгов поднять восстание и выступить против Орды.$B$BЭто моя последняя просьба; выполнив ее, ты можешь идти дальше по дороге жизни. Но куда бы не завела тебя судьба, знай, что в моем лице ты $Gобрел:обрела; верного друга.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используя жезл Дартола, поговорите с Ота Веном и уговорите его поднять восстание против ордынских захватчиков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Часовые здесь, в Ясеневом лесу, делают что могут, но лишь благодаря таким |3-6($r)ям как ты, мы не сдаем своих позиций.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Восстание фурболгов началось.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Speak with Raene Wolfrunner at Astranaar in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1047,'Новое пограничье','Внимание, герои!$B$BКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора -запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!$B$BВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнасе!','Обратитесь в дарнасский анклав Кенария к верховному друиду Фэндралу Оленьему Шлему по поводу помощи Кругу Кенария в исследовании границ Калимдора.','С чего ты решил, что я буду утруждать себя беседой с таким, как ты, |3-6($C)? Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу! Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идет с важностью поиска этой пустяковины для твоей коллекции!$B$BСначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я еще и это сносить должен?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое пограничье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимание, герои!$B$BКруг Кенария ищет компетентных помощников для исследования нового обширного пограничья Калимдора -запретных диких краев, полных невообразимых опасностей, что лежат к западу от Танариса и Прибамбасска! Кругу нужны добровольные и честные помощники, что будут действовать в его интересах!$B$BВсе заинтересованные лица да обращаются в Круг Кенария! За дополнительной информацией обращайтесь к верховному друиду Фэндралу Оленьему Шлему в Дарнасе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь в дарнасский анклав Кенария к верховному друиду Фэндралу Оленьему Шлему по поводу помощи Кругу Кенария в исследовании границ Калимдора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С чего ты решил, что я буду утруждать себя беседой с таким, как ты, |3-6($C)? Вот сейчас я брошу мои великие каждодневные труды и стану искать для тебя эту безделицу! Ведь благополучие Дарнасса – нет, всего Тельдрассила – в сравнение не идет с важностью поиска этой пустяковины для твоей коллекции!$B$BСначала эти недоумки из Лунной поляны отнимают у меня время своими просьбами о помощи, а теперь я еще и это сносить должен?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1048,'В монастырь Алого ордена','Хотя Темную Госпожу больше всего тревожит продвижение Короля-лича на север, мое дело – заботиться о более насущных проблемах.$B$BИ главная из них – человечишки, зовущие себя Алым орденом. Тирисфальские леса кишмя кишат маленькими алыми муравьишками.$B$BОтправляйся в монастырь, |3-6($c), и избавь нас от верховного инквизитора Вайтмейн и ее подчиненных.','Убейте верховного инквизитора Вайтмейн, командира Алого ордена Могрейна, Ирода из Алого ордена и псаря Локси. Затем возвращайтесь к Вариматасу в Подгород.','Ты сослужил Темной Госпоже отличную службу, |3-6($C). Это задание было не из легких.\n\nЯ не забуду о твоей преданности Отрекшимся и стойкости в битве.','Я считаю, что для выживания в этом мире нужно помнить только одно правило: чем больше знаешь, тем больше видишь.\n\nУчись, наблюдай, и тогда разглядишь то, чего никто другой не увидит |3-6($R).','Вернитесь к Вариматасу в Королевский квартал, что в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В монастырь Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя Темную Госпожу больше всего тревожит продвижение Короля-лича на север, мое дело – заботиться о более насущных проблемах.$B$BИ главная из них – человечишки, зовущие себя Алым орденом. Тирисфальские леса кишмя кишат маленькими алыми муравьишками.$B$BОтправляйся в монастырь, |3-6($c), и избавь нас от верховного инквизитора Вайтмейн и ее подчиненных.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного инквизитора Вайтмейн, командира Алого ордена Могрейна, Ирода из Алого ордена и псаря Локси. Затем возвращайтесь к Вариматасу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сослужил Темной Госпоже отличную службу, |3-6($C). Это задание было не из легких.\n\nЯ не забуду о твоей преданности Отрекшимся и стойкости в битве.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я считаю, что для выживания в этом мире нужно помнить только одно правило: чем больше знаешь, тем больше видишь.\n\nУчись, наблюдай, и тогда разглядишь то, чего никто другой не увидит |3-6($R).',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вариматасу в Королевский квартал, что в Подгороде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1049,'"Компендиум павших"','Намерения Служителей Земли относительно наших пораженных болезнью братьев чисты. Но кому ведомы замыслы тех, кто нашептывает всякое Совету Старейшин?$b$bУ Отрекшихся, с которым мы ныне в союзе, вся история полна лжи. Слишком мы поторопились с союзом. Возможно, Кэрн прислушается к предупреждениям из Оргриммара.$b$bВ недрах Монастыря Алого ордена находится "Компендиум павших", который стерегут безумные фанатики-люди. В том, что они творят, сквозит безумие, однако их исследования могут оказаться для нас полезными.','Добудьте "Компендиум павших" из монастыря в Тирисфальских лесах и возвращайтесь к Ведуну Искателю Истины в Громовой Утес.','Кэрн – отважный и благородный вождь, и я доверил бы ему свою жизнь. Но есть и те, кому я в нынешние времена нипочем бы не доверился.\n\nКак только смогу собрать все возможные сведения, я сумею дать вождю небезосновательный совет.\n\nТебе удалось добраться до Тирисфальских лесов? Удалось проникнуть в Монастырь Алого ордена? "Компендиум павших" – лишь кусочек сложной мозаики...','Вернитесь к ведуну Искателю Истины в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Компендиум павших"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Намерения Служителей Земли относительно наших пораженных болезнью братьев чисты. Но кому ведомы замыслы тех, кто нашептывает всякое Совету Старейшин?$b$bУ Отрекшихся, с которым мы ныне в союзе, вся история полна лжи. Слишком мы поторопились с союзом. Возможно, Кэрн прислушается к предупреждениям из Оргриммара.$b$bВ недрах Монастыря Алого ордена находится "Компендиум павших", который стерегут безумные фанатики-люди. В том, что они творят, сквозит безумие, однако их исследования могут оказаться для нас полезными.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте "Компендиум павших" из монастыря в Тирисфальских лесах и возвращайтесь к Ведуну Искателю Истины в Громовой Утес.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кэрн – отважный и благородный вождь, и я доверил бы ему свою жизнь. Но есть и те, кому я в нынешние времена нипочем бы не доверился.\n\nКак только смогу собрать все возможные сведения, я сумею дать вождю небезосновательный совет.\n\nТебе удалось добраться до Тирисфальских лесов? Удалось проникнуть в Монастырь Алого ордена? "Компендиум павших" – лишь кусочек сложной мозаики...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведуну Искателю Истины в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1050,'"Мифология Титанов"','Будущее неотвратимо! Мы стремимся к нему подобно тому, как дождевые капли стремятся к Великому морю.$b$bНо, изучая прошедшее, мы узнаем, что ждет нас в грядущем, и готовимся к встрече с неведомым.$b$bПрежде чем великие беды обрушились на Лордерон, в Тирисфальских лесах находился оплот знаний. Ходят слухи, что в библиотеке старого монастыря хранится книга под названием "Мифология Титанов".$b$bПринеси ее мне – и, возможно, вместе мы сможем заглянуть в тайны прошлого!','Добудьте "Мифологию Титанов" из монастыря и принесите ее библиотекарю Мае Белокожке в Стальгорн.','Этот монастырь был духовной школой паладинов. Некогда он был цитаделью Света, а теперь попал в руки безумных фанатиков Алого ордена.$B$BОни считают, что у них благородная цель – очистить землю от нежити. Но безумие запятнало их деяния, и ныне они враги всем.$B$BПринеси мне "Мифологию Титанов", чтобы я могла изучить эту книгу. Я буду хранить ее здесь, в Стальгорне.$B$BОскверненные стены монастыря – не место для такого исторического сокровища.','Вернитесь к библиотекарю Мае Белокожке в Зал Исследователей, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Мифология Титанов"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Будущее неотвратимо! Мы стремимся к нему подобно тому, как дождевые капли стремятся к Великому морю.$b$bНо, изучая прошедшее, мы узнаем, что ждет нас в грядущем, и готовимся к встрече с неведомым.$b$bПрежде чем великие беды обрушились на Лордерон, в Тирисфальских лесах находился оплот знаний. Ходят слухи, что в библиотеке старого монастыря хранится книга под названием "Мифология Титанов".$b$bПринеси ее мне – и, возможно, вместе мы сможем заглянуть в тайны прошлого!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте "Мифологию Титанов" из монастыря и принесите ее библиотекарю Мае Белокожке в Стальгорн.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Этот монастырь был духовной школой паладинов. Некогда он был цитаделью Света, а теперь попал в руки безумных фанатиков Алого ордена.$B$BОни считают, что у них благородная цель – очистить землю от нежити. Но безумие запятнало их деяния, и ныне они враги всем.$B$BПринеси мне "Мифологию Титанов", чтобы я могла изучить эту книгу. Я буду хранить ее здесь, в Стальгорне.$B$BОскверненные стены монастыря – не место для такого исторического сокровища.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к библиотекарю Мае Белокожке в Зал Исследователей, что в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1051,'Месть Воррела','Моя воля свободна, и все же я не могу более служить Темной Госпоже. Я чувствую, что время, отпущенное мне в Азероте, подходит к концу. Жизненные силы покидают меня.$B$BДознаватель Вишас всему виной! Он пытал меня много недель! Мало того, он отобрал у меня обручальное кольцо и нацепил его на палец своей жене! Чудовище!$B$BЯ жажду мести!$B$BЭтот глупец похвалялся своей прекрасной женой Нэнси, что живет у озера Лордамер. Я хочу, чтобы ты $gотыскал:отыскала; девку и $gвытряс:вытрясла; из нее душу вместе с моим кольцом! Верни кольцо моей жене Монике, она живет в Мельнице Таррен.$B$BИсполни мою последнюю волю.','Верните обручальное кольцо Воррела Сенгутца Монике Сенгутц в Мельнице Таррен.','Воррел был мне добрым супругом...$B$BПроклятые смертные!$B$BНикогда нам более не быть вместе. По крайней мере, я найду утешение в свершенной тобой мести. Благодарю тебя.$B$BА теберь оставь меня наедине с моим горем.','Что тебе нужно, $Gстранник:странница;?','Вернитесь к Монике Сенгутц на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Воррела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя воля свободна, и все же я не могу более служить Темной Госпоже. Я чувствую, что время, отпущенное мне в Азероте, подходит к концу. Жизненные силы покидают меня.$B$BДознаватель Вишас всему виной! Он пытал меня много недель! Мало того, он отобрал у меня обручальное кольцо и нацепил его на палец своей жене! Чудовище!$B$BЯ жажду мести!$B$BЭтот глупец похвалялся своей прекрасной женой Нэнси, что живет у озера Лордамер. Я хочу, чтобы ты $gотыскал:отыскала; девку и $gвытряс:вытрясла; из нее душу вместе с моим кольцом! Верни кольцо моей жене Монике, она живет в Мельнице Таррен.$B$BИсполни мою последнюю волю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните обручальное кольцо Воррела Сенгутца Монике Сенгутц в Мельнице Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воррел был мне добрым супругом...$B$BПроклятые смертные!$B$BНикогда нам более не быть вместе. По крайней мере, я найду утешение в свершенной тобой мести. Благодарю тебя.$B$BА теберь оставь меня наедине с моим горем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе нужно, $Gстранник:странница;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Монике Сенгутц на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1052,'Путями Алого ордена','Мы, рыцари Алого ордена, заявляем свои права на укрепления от Дольного Очага до Тирисфальских лесов. Мы гордимся нашей борьбой за чистоту Лордерона!$b$bВы подтвердили свою репутацию, сражаясь против нежити в Пустошах. Но настоящая угроза исходит из Лордерона.$b$bОтправляйтесь в Восточные королевства, в город Южнобережье. Отнесите письмо с моими рекомендациями и печатью рыцарю Ролею Благочестивому. Он проводит вас в Монастырь Алого ордена.','Отнесите рекомендательное письмо брата Антона Ролею Благочестивому в Южнобережье.','Брат Антон по-прежнему проповедует идеи Алого ордена? О-ох...','Кто идет? Что вам от меня надо?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путями Алого ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы, рыцари Алого ордена, заявляем свои права на укрепления от Дольного Очага до Тирисфальских лесов. Мы гордимся нашей борьбой за чистоту Лордерона!$b$bВы подтвердили свою репутацию, сражаясь против нежити в Пустошах. Но настоящая угроза исходит из Лордерона.$b$bОтправляйтесь в Восточные королевства, в город Южнобережье. Отнесите письмо с моими рекомендациями и печатью рыцарю Ролею Благочестивому. Он проводит вас в Монастырь Алого ордена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите рекомендательное письмо брата Антона Ролею Благочестивому в Южнобережье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Брат Антон по-прежнему проповедует идеи Алого ордена? О-ох...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто идет? Что вам от меня надо?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1053,'Во имя Света!','Я всегда служил Алому ордену, гордился им и почитал служение за честь. Мне было чем гордиться, ведь мы спасали Азерот от нежити.$b$bНо после некоторого времени, проведенного в монастыре Тирисфальских лесов, я понял, что не ведал об истинных намерениях высшей иерархии ордена. Каждого, кто не принадлежит к ордену, они почитают грешниками. Невинных мужчин и женщин подвергают пыткам, полагая их нечистыми.$b$bВо имя Света, Алый орден должен быть сокрушен. И вам, $n, по силам остановить это чудовище.','Убейте верховного инквизитора Вайтмейн, командира Алого ордена Могрейна, Ирода из Алого ордена и псаря Локси, после этого вернитесь с докладом к Ролею Благочестивому в Южнобережье.','Хотя путь Света не приемлет убийств и кровопролитий, но в подобных случаях кровавая жертва служит благу королевства и всего мира.$B$BВаши деяния в монастыре помогли спасти множество невинных жизней. $n, я восхищаюсь вашей решительностью.','Разложение в монастыре не прекратится, пока высшие должностные лица не будут устранены.$B$BИменем Света убейте верховного инквизитора Вайтмейн, командующего Алого ордена Могрейна, Ирода, Чемпиона Алого ордена и псаря Локси.','Вернитесь к Ролею Благочестивому в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во имя Света!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я всегда служил Алому ордену, гордился им и почитал служение за честь. Мне было чем гордиться, ведь мы спасали Азерот от нежити.$b$bНо после некоторого времени, проведенного в монастыре Тирисфальских лесов, я понял, что не ведал об истинных намерениях высшей иерархии ордена. Каждого, кто не принадлежит к ордену, они почитают грешниками. Невинных мужчин и женщин подвергают пыткам, полагая их нечистыми.$b$bВо имя Света, Алый орден должен быть сокрушен. И вам, $n, по силам остановить это чудовище.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте верховного инквизитора Вайтмейн, командира Алого ордена Могрейна, Ирода из Алого ордена и псаря Локси, после этого вернитесь с докладом к Ролею Благочестивому в Южнобережье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хотя путь Света не приемлет убийств и кровопролитий, но в подобных случаях кровавая жертва служит благу королевства и всего мира.$B$BВаши деяния в монастыре помогли спасти множество невинных жизней. $n, я восхищаюсь вашей решительностью.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разложение в монастыре не прекратится, пока высшие должностные лица не будут устранены.$B$BИменем Света убейте верховного инквизитора Вайтмейн, командующего Алого ордена Могрейна, Ирода, Чемпиона Алого ордена и псаря Локси.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ролею Благочестивому в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1054,'Устранение угрозы','Прямо к северу от Астранаара живут фурболги Колючего Меха. Мои разведчики доносят, что в последние несколько месяцев они чрезвычайно умножились числом. Если они слишком расплодятся, то могут набраться наглости напасть на Астранаар!$B$BУбей их, сколько сможешь, главное – принеси мне череп их предводителя в знак того, что их усилия напрасны...пока. $B$BЯ останусь в Астранааре и буду ждать вестей от тебя. Да пребудет с тобой Элуна.','Принесите череп Дала Жилотяга Раэне Волкопас в Астранаар.','Из-за этой фурболгской заразы дни славы Ясеневого леса остались далеко в прошлом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Устранение угрозы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прямо к северу от Астранаара живут фурболги Колючего Меха. Мои разведчики доносят, что в последние несколько месяцев они чрезвычайно умножились числом. Если они слишком расплодятся, то могут набраться наглости напасть на Астранаар!$B$BУбей их, сколько сможешь, главное – принеси мне череп их предводителя в знак того, что их усилия напрасны...пока. $B$BЯ останусь в Астранааре и буду ждать вестей от тебя. Да пребудет с тобой Элуна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите череп Дала Жилотяга Раэне Волкопас в Астранаар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Из-за этой фурболгской заразы дни славы Ясеневого леса остались далеко в прошлом.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1055,'Раэна – санитар Ясеневого леса','Воссозданный жезл у вас в руках. Шаэл\'дрин захочет услышать о ваших успехах.','Вернитесь к Шаэл\'дрин у лунного колодца.','У тебя получилось, $n! Великолепно!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раэна – санитар Ясеневого леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воссозданный жезл у вас в руках. Шаэл\'дрин захочет услышать о ваших успехах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Шаэл\'дрин у лунного колодца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя получилось, $n! Великолепно!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1056,'Путешествие к Пику Каменного Когтя','Лесные духи говорят мне, что ты $Gотважен и легок на подъем:отважна и легка на подъем;.$b$bНа юге, неподалеку от озера Мистраль, находится туннель, именуемый Туннель Когтя. Через этот туннель ты попадешь в место, называемое Утес Ветрорезов, в Когтистых горах. Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберешься до Пика Каменного Когтя.$b$bТам ждет хранитель Албагорм. Выслушай его просьбу, |3-6($r).$b$bПутешествие будет опасным.','Отправляйтесь к хранителю Албагорму на Пик Каменного Когтя.','Наконец-то! Вижу, Фальдреас прислушался к духам лесов...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие к Пику Каменного Когтя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лесные духи говорят мне, что ты $Gотважен и легок на подъем:отважна и легка на подъем;.$b$bНа юге, неподалеку от озера Мистраль, находится туннель, именуемый Туннель Когтя. Через этот туннель ты попадешь в место, называемое Утес Ветрорезов, в Когтистых горах. Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберешься до Пика Каменного Когтя.$b$bТам ждет хранитель Албагорм. Выслушай его просьбу, |3-6($r).$b$bПутешествие будет опасным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к хранителю Албагорму на Пик Каменного Когтя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то! Вижу, Фальдреас прислушался к духам лесов...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1057,'Возвращение Обугленной долины','Несомненно, будучи защитником лесных духов, можешь догадаться, почему я так встревожен.$b$bЧтобы достигнуть этого пика, тебе пришлось пройти через горы, и, конечно же, от глаз твоих не ускользнуло искажение, постигшее эту землю. Алчность привела к уничтожению священных холмов.$b$bОбугленная долина на юге сожжена механической армией жадных промышленников. Хуже того, клан Смертельной Ярости, вторгшийся на эти земли, отказывается пропустить нас – а ведь мы могли бы начать восстановление тех краев!$b$bИзгони прочь злобных гарпий, $n!','Хранитель Албагорм с Пика Каменного Когтя просит вас убить 7 гарпий, 7 душительниц, 7 душегубок и 7 бродяжниц из стаи Кровавой Ярости.','Теперь, когда клан Смертельной Ярости понес большие потери, вероятно, и начнется истинная работа по восстановлению этих земель...','Предстоит проделать большую работу, прежде чем Обугленная долина сможет превратиться в пышный лес, которым она когда-то была.$B$BОчистите зону этих гнусных угроз, $N! Только тогда мы сможем вернуть то, что принадлежит природе.','Вернитесь к хранителю Албагорму на Пик Каменного Когтя, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение Обугленной долины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несомненно, будучи защитником лесных духов, можешь догадаться, почему я так встревожен.$b$bЧтобы достигнуть этого пика, тебе пришлось пройти через горы, и, конечно же, от глаз твоих не ускользнуло искажение, постигшее эту землю. Алчность привела к уничтожению священных холмов.$b$bОбугленная долина на юге сожжена механической армией жадных промышленников. Хуже того, клан Смертельной Ярости, вторгшийся на эти земли, отказывается пропустить нас – а ведь мы могли бы начать восстановление тех краев!$b$bИзгони прочь злобных гарпий, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Хранитель Албагорм с Пика Каменного Когтя просит вас убить 7 гарпий, 7 душительниц, 7 душегубок и 7 бродяжниц из стаи Кровавой Ярости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда клан Смертельной Ярости понес большие потери, вероятно, и начнется истинная работа по восстановлению этих земель...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Предстоит проделать большую работу, прежде чем Обугленная долина сможет превратиться в пышный лес, которым она когда-то была.$B$BОчистите зону этих гнусных угроз, $N! Только тогда мы сможем вернуть то, что принадлежит природе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Албагорму на Пик Каменного Когтя, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1058,'Лесная магия Джин\'Зила','Я в восхищении!$b$bТри маленьких клетки для трех маленьких эльфов. Ну-с, что бы нам сделать с нашими дорогими друзьями-древолюбами? Что ж, дадим им попробовать... как бы это они сказали... лесной магии!$b$bМне нужна добрая порция слизи Каменного Когтя. Принеси мне несколько сумеречных усиков этих ужасных кошек. И конечно же, потребуется множество глаз бегового оленя – глаз всегда не хватает! Да, и еще, последнее, чуть не забыл: драгоценную чешуйку волшебного дракончика.$b$bЖиво в Каменный Коготь, $n, чтобы я мог сварить немножко лесной магии!','Знахарь Джин\'Зил из Малака\'джина требует принести 5 порций слизи Каменного когтя, 5 сумеречных усиков, 30 глаз бегового оленя и чешуйку волшебного дракончика.','О, как счастливы будут эти маленькие лесные нимфы! Мы заставим их почувствовать себя как дома при помощи этого особого отвара!','Взгляни на наших маленьких друзей-эльфов! Заперты в клетках и не могут побродить по лесу!\n\nТебе удалось раздобыть для меня немного слизи? А как насчет усиков сумеречного бегуна? А разве у тебя еще нет чешуйки волшебного дракончика?\n\nА глаза? Мне нужно так много глаз! Невозможно составить доброе магическое лесное варево без хорошей порции глаз!','Вернитесь к знахарю Джин\'зилу в Малака\'джин, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лесная магия Джин\'Зила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я в восхищении!$b$bТри маленьких клетки для трех маленьких эльфов. Ну-с, что бы нам сделать с нашими дорогими друзьями-древолюбами? Что ж, дадим им попробовать... как бы это они сказали... лесной магии!$b$bМне нужна добрая порция слизи Каменного Когтя. Принеси мне несколько сумеречных усиков этих ужасных кошек. И конечно же, потребуется множество глаз бегового оленя – глаз всегда не хватает! Да, и еще, последнее, чуть не забыл: драгоценную чешуйку волшебного дракончика.$b$bЖиво в Каменный Коготь, $n, чтобы я мог сварить немножко лесной магии!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Знахарь Джин\'Зил из Малака\'джина требует принести 5 порций слизи Каменного когтя, 5 сумеречных усиков, 30 глаз бегового оленя и чешуйку волшебного дракончика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, как счастливы будут эти маленькие лесные нимфы! Мы заставим их почувствовать себя как дома при помощи этого особого отвара!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Взгляни на наших маленьких друзей-эльфов! Заперты в клетках и не могут побродить по лесу!\n\nТебе удалось раздобыть для меня немного слизи? А как насчет усиков сумеречного бегуна? А разве у тебя еще нет чешуйки волшебного дракончика?\n\nА глаза? Мне нужно так много глаз! Невозможно составить доброе магическое лесное варево без хорошей порции глаз!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Джин\'зилу в Малака\'джин, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1059,'Возвращение Обугленной долины','Мы одержали победу над кланом Смертельной Ярости. Но они скоро соберут силы и вернутся, если не предпринять решительные действия. $b$bДалеко на юге Пустошей находится земля, известная как Тысяча Игл. Если идти на запад Тысячи Игл до тех пор, пока не достигнешь границ густого леса Фералас, то встретишь друида по имени Фалфиндер Хранитель Дорог.$b$bЭтот сильный и мудрый друид способен призвать великих лесных духов, которые помогут в восстановлении Обугленной долины.$b$bПоведай ему о нашей беде! Отправляйся на его поиски немедленно!','Отправляйтесь к Фалфиндеру Хранителю Дорог, живущему на границе Тысячи Игл и Фераласа.','Хранитель Албагорм поступил мудро, прислав тебя со срочным известием.$B$BБудем надеяться, что мы успеем призвать помощь, и что эта помощь из великого леса прибудет в Обугленную долину не слишком поздно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение Обугленной долины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы одержали победу над кланом Смертельной Ярости. Но они скоро соберут силы и вернутся, если не предпринять решительные действия. $b$bДалеко на юге Пустошей находится земля, известная как Тысяча Игл. Если идти на запад Тысячи Игл до тех пор, пока не достигнешь границ густого леса Фералас, то встретишь друида по имени Фалфиндер Хранитель Дорог.$b$bЭтот сильный и мудрый друид способен призвать великих лесных духов, которые помогут в восстановлении Обугленной долины.$b$bПоведай ему о нашей беде! Отправляйся на его поиски немедленно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Фалфиндеру Хранителю Дорог, живущему на границе Тысячи Игл и Фераласа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хранитель Албагорм поступил мудро, прислав тебя со срочным известием.$B$BБудем надеяться, что мы успеем призвать помощь, и что эта помощь из великого леса прибудет в Обугленную долину не слишком поздно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1060,'[DEPRECATED]Письмо Джин\'Зилу','Ты $gсделал:сделала; мне много добра, $n. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что еще.$B$BГарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе. Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин\'Зилу.$B$BОн будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место.','Отнесите письмо Дарсока Джин\'Зилу в пещеру Малака\'джин в Когтистых горах.','А, письмо от Дарсока. Давно от него не было вестей.\n\nЗначит, последняя из Кровавых Перьев мертва? Отличные вести. Я хорошо помню, как мой друг Рокхан пошел убивать ее старшую сестру с этим психом из Мок\'Натала. Да, тогда я был молод, как ты сейчас.','На вид ты темная личность. Ты хочешь мне что-то показать?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Письмо Джин\'Зилу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсделал:сделала; мне много добра, $n. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что еще.$B$BГарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе. Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин\'Зилу.$B$BОн будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо Дарсока Джин\'Зилу в пещеру Малака\'джин в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, письмо от Дарсока. Давно от него не было вестей.\n\nЗначит, последняя из Кровавых Перьев мертва? Отличные вести. Я хорошо помню, как мой друг Рокхан пошел убивать ее старшую сестру с этим психом из Мок\'Натала. Да, тогда я был молод, как ты сейчас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На вид ты темная личность. Ты хочешь мне что-то показать?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1061,'Духи Каменного Когтя','Духи Когтистых гор разгневаны: гоблины и их приспешники разоряют и выжигают земли. Земля возопила, и те, кто способен слышать – услышали.$b$bВ Когтистые горы отправилась Сирит Камнеломм, многообещающий шаман Орды. Она сообщает, что гоблины вырубили много леса, и просит о помощи.$b$bОтправляйся в Когтистые горы, найди там Сирит. Чтобы туда добраться, ступай от Перекрестка в Степях по дороге на запад. Сирит стоит лагерем близ Долины Высокого леса.','Поговорите с Сирит Камнелом на границе Когтистых гор и Степей.','А, |3-6($C)! Очень кстати. Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи Каменного Когтя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духи Когтистых гор разгневаны: гоблины и их приспешники разоряют и выжигают земли. Земля возопила, и те, кто способен слышать – услышали.$b$bВ Когтистые горы отправилась Сирит Камнеломм, многообещающий шаман Орды. Она сообщает, что гоблины вырубили много леса, и просит о помощи.$b$bОтправляйся в Когтистые горы, найди там Сирит. Чтобы туда добраться, ступай от Перекрестка в Степях по дороге на запад. Сирит стоит лагерем близ Долины Высокого леса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сирит Камнелом на границе Когтистых гор и Степей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, |3-6($C)! Очень кстати. Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1062,'Вторжение гоблинов','Торговая Компания, которой управляют гоблины, вторглась в Когтистые горы. Они валят деревья, выжигают большие участки леса. Духи этих земель вне себя от боли и ярости. Мы должны остановить Торговую Компанию!$B$BОтправляйся на северо-запад, за Долину Высокого леса, к Утесу Ветрорезов. Ты найдешь гоблинов и их прислужников за работой – покажи же им, что Орда не позволит разорять Когтистые горы. Поговори с ними на том языке, который они лучше всего понимают...$B$BНа языке беспощадной силы!','Убейте 15 лесорубов Торговой Компании, затем вернитесь к Сирет Камнелом на границу Каменного Когтя и Степей.','У тебя какие-то новости от землепряда Магграна?','Вернитесь к Сирит Камнелом в Долину Высокого леса, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение гоблинов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Торговая Компания, которой управляют гоблины, вторглась в Когтистые горы. Они валят деревья, выжигают большие участки леса. Духи этих земель вне себя от боли и ярости. Мы должны остановить Торговую Компанию!$B$BОтправляйся на северо-запад, за Долину Высокого леса, к Утесу Ветрорезов. Ты найдешь гоблинов и их прислужников за работой – покажи же им, что Орда не позволит разорять Когтистые горы. Поговори с ними на том языке, который они лучше всего понимают...$B$BНа языке беспощадной силы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 лесорубов Торговой Компании, затем вернитесь к Сирет Камнелом на границу Каменного Когтя и Степей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя какие-то новости от землепряда Магграна?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сирит Камнелом в Долину Высокого леса, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1063,'[DEPRECATED] Мудрая старуха','Чтобы узнать, как окончательно успокоить духов Когтистых гор, нам нужно посоветоваться со старейшинами тауренов.$B$BЯ мало знаю о том, кто предводительствует тауренами, но одно имя мне известно: Магата. Говорят, она очень стара и много знает. Если кто из тауренов и может оказать нам помощь касательно духов, то это она.$B$BМагата живет в главном городе тауренов Громовом Утесе на Вершине Старейшин – это северо-восточная вершина города. Поговори с Магатой и расскажи ей о том, что творится в Когтистых горах.','Поговорите с Магатой в Громовом Утесе.','Я приветствую тебя. Ты ищешь совета?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Мудрая старуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы узнать, как окончательно успокоить духов Когтистых гор, нам нужно посоветоваться со старейшинами тауренов.$B$BЯ мало знаю о том, кто предводительствует тауренами, но одно имя мне известно: Магата. Говорят, она очень стара и много знает. Если кто из тауренов и может оказать нам помощь касательно духов, то это она.$B$BМагата живет в главном городе тауренов Громовом Утесе на Вершине Старейшин – это северо-восточная вершина города. Поговори с Магатой и расскажи ей о том, что творится в Когтистых горах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Магатой в Громовом Утесе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я приветствую тебя. Ты ищешь совета?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1064,'[DEPRECATED] Помощь Отрекшихся','Таурены в сродстве с этой землей, и мне больно слышать о том, что творится в Каменном Когте. Но я боюсь, что для исцеления этой земли нам прежде придется справиться с той заразой, что терзает нас самих.$B$BРазве не удача, что Отрекшиеся теперь с нами? Они много знают о заразных болезнях. Я уверена, что они смогут помочь нам и тем укрепят доверие между нашими народами.$B$BПоговори с аптекаршей Замой. Она – ученая и представитель Отрекшихся. Ты найдешь ее у Прудов Видений под Уступом Духов.','Поговорите с аптекаршей Замой у Прудов Видений в Громовом Утесе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Помощь Отрекшихся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Таурены в сродстве с этой землей, и мне больно слышать о том, что творится в Каменном Когте. Но я боюсь, что для исцеления этой земли нам прежде придется справиться с той заразой, что терзает нас самих.$B$BРазве не удача, что Отрекшиеся теперь с нами? Они много знают о заразных болезнях. Я уверена, что они смогут помочь нам и тем укрепят доверие между нашими народами.$B$BПоговори с аптекаршей Замой. Она – ученая и представитель Отрекшихся. Ты найдешь ее у Прудов Видений под Уступом Духов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с аптекаршей Замой у Прудов Видений в Громовом Утесе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1065,'[DEPRECATED] Путешествие на Мельницу Таррен','Нам придется прибегнуть к чрезвычайным мерам, чтобы избавить Каменный Коготь от Торговой Компании. Но только без кровопролития.$B$BУ одного моего коллеги может найтись то, что нам как раз для этого случая и нужно. Его зовут Лидон, он живет в городе Мельница Таррен в предгорьях Хилсбрада, в далеком краю Лордерон.$B$BЧтобы добраться до Хилсбрада, отправляйся на дирижабле в нашу столицу, Подгород. Оттуда иди на север в Тирисфальские леса, что к юго-западу от Серебряного бора, а затем на юг, в Хилсбрад.$B$BНайди Лидона и передай ему эту записку. Там написано, что нам от него нужно.','Принесите записку Замы аптекарю Лидону в Мельницу Таррен.','Записка от Замы? Наверняка ее сильно прижало, раз пишет в такую даль. Посмотрим...\n\nЗамечательно! Я знаю, что ей надо!','Ага, вы доставили мне новых подопытных?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Путешествие на Мельницу Таррен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам придется прибегнуть к чрезвычайным мерам, чтобы избавить Каменный Коготь от Торговой Компании. Но только без кровопролития.$B$BУ одного моего коллеги может найтись то, что нам как раз для этого случая и нужно. Его зовут Лидон, он живет в городе Мельница Таррен в предгорьях Хилсбрада, в далеком краю Лордерон.$B$BЧтобы добраться до Хилсбрада, отправляйся на дирижабле в нашу столицу, Подгород. Оттуда иди на север в Тирисфальские леса, что к юго-западу от Серебряного бора, а затем на юг, в Хилсбрад.$B$BНайди Лидона и передай ему эту записку. Там написано, что нам от него нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите записку Замы аптекарю Лидону в Мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Записка от Замы? Наверняка ее сильно прижало, раз пишет в такую даль. Посмотрим...\n\nЗамечательно! Я знаю, что ей надо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ага, вы доставили мне новых подопытных?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1066,'[DEPRECATED] Невинная кровь','Я создам яд, который остудит пыл Торговой Компании. Они станут слабыми и покорными. Это же решит проблемы Орды в Каменном Когте, да?$b$bНо для создания отравы мне понадобится кровь невинных, а ее нелегко найти.$b$bК счастью, Синдикат, группа грабителей, насчитывает в своих рядах несколько темных магов... а они собирают кровь невинных для своих нечистых целей.$b$bТемных магов Синдиката можно найти в крепости Дарнхольд на юго-востоке.','Принесите 5 фиалов крови невинных аптекарю Лидону в Мельницу Таррен.','Очень хорошо! Надеюсь, Синдикат не причинил тебе особых проблем?\n\nКак я и говорил, кровь невинных не так уж легко добыть. Нам повезло, что трудную часть работы взяли на себя маги Синдиката.\n\nА теперь подожди, я создам мой состав...','Тебе удалось найти темных магов Синдиката и принести кровь невинных?','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Невинная кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я создам яд, который остудит пыл Торговой Компании. Они станут слабыми и покорными. Это же решит проблемы Орды в Каменном Когте, да?$b$bНо для создания отравы мне понадобится кровь невинных, а ее нелегко найти.$b$bК счастью, Синдикат, группа грабителей, насчитывает в своих рядах несколько темных магов... а они собирают кровь невинных для своих нечистых целей.$b$bТемных магов Синдиката можно найти в крепости Дарнхольд на юго-востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 фиалов крови невинных аптекарю Лидону в Мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо! Надеюсь, Синдикат не причинил тебе особых проблем?\n\nКак я и говорил, кровь невинных не так уж легко добыть. Нам повезло, что трудную часть работы взяли на себя маги Синдиката.\n\nА теперь подожди, я создам мой состав...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти темных магов Синдиката и принести кровь невинных?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1067,'[DEPRECATED] Возвращение в Громовой Утес','Вот отрава. Если воспользоваться ей против Торговой Компании, результаты должны оказаться весьма благоприятными – возможно, удастся добиться даже распростанения новой заразы. Мне не терпится испытать свою работу в деле!$b$bВпрочем, прежде отнеси ее аптекарю Заме. Она должна придумать наиболее эффективный способ использования отравы.','Отнесите отраву Лидона аптекарю Заме в Громовой Утес.','Отрава от аптекаря Лидона? Замечательно. Если я знаю Лидона, она очень хорошо подействует на Торговую Компанию...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Возвращение в Громовой Утес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот отрава. Если воспользоваться ей против Торговой Компании, результаты должны оказаться весьма благоприятными – возможно, удастся добиться даже распростанения новой заразы. Мне не терпится испытать свою работу в деле!$b$bВпрочем, прежде отнеси ее аптекарю Заме. Она должна придумать наиболее эффективный способ использования отравы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите отраву Лидона аптекарю Заме в Громовой Утес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отрава от аптекаря Лидона? Замечательно. Если я знаю Лидона, она очень хорошо подействует на Торговую Компанию...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1068,'Механические измельчители','Есть связь между духовной магией шаманов и природной магией друидов. Именно поэтому мы, шаманы, можем слышать мольбы духов Каменного Когтя. Я могу разобрать не все, что они шепчут, однако одно послание – одно видение – было четким...$B$BВ этом видении я узрела на Утесе Ветрорезов, на северо-западе Долины Высокого леса, две человекоподобные машины, которые валили деревья с невероятной скоростью. Этих металлических тварей нужно остановить!$B$BВ явленном мне видении я заметила, что машины эти отмечены странными символами:$B$BXT:4 и XT:9.','Уничтожьте шреддеры XT:4 и XT:9, затем вернитесь к Сирит Камнелом на границу Когтистых гор и Степей.','Когда мой повелитель отправил меня на Пик Каменного Когтя, мне казалось, что нужно будет лишь погубить ночных эльфов, которые ползают по руинам нашего древнего храма Азшары, оскверняя святость этого места... но Хорданиус ускользнул от меня.','Вернитесь к Сирит Камнелом в Долину Высокого леса, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Механические измельчители',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть связь между духовной магией шаманов и природной магией друидов. Именно поэтому мы, шаманы, можем слышать мольбы духов Каменного Когтя. Я могу разобрать не все, что они шепчут, однако одно послание – одно видение – было четким...$B$BВ этом видении я узрела на Утесе Ветрорезов, на северо-западе Долины Высокого леса, две человекоподобные машины, которые валили деревья с невероятной скоростью. Этих металлических тварей нужно остановить!$B$BВ явленном мне видении я заметила, что машины эти отмечены странными символами:$B$BXT:4 и XT:9.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте шреддеры XT:4 и XT:9, затем вернитесь к Сирит Камнелом на границу Когтистых гор и Степей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда мой повелитель отправил меня на Пик Каменного Когтя, мне казалось, что нужно будет лишь погубить ночных эльфов, которые ползают по руинам нашего древнего храма Азшары, оскверняя святость этого места... но Хорданиус ускользнул от меня.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сирит Камнелом в Долину Высокого леса, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1069,'[DEPRECATED]Яйца мохового паука','В Пиратской Бухте фантастический спрос на омлеты из паучьих яиц! Проблема в том... что яиц в Бухте нет.$B$BЯ чую прибыль!$B$BНа Утесе Ветрорезов и в Сиширском каньоне, в Когтистых горах на северо-западе, живут моховые пауки. Принеси мне их яйца, и я неплохо заплачу!$B$BНа Утесе Ветрорезов паучьи кладки можно найти под оставшимися деревьями.$B$BВ Сиширском каньоне... хм, если у тебя слабый желудок, можешь собирать яйца только на Утесе Ветрорезов...','Принесите Мебоку Миззриксу из Кабестана 15 яиц мохового паука.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Яйца мохового паука',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Пиратской Бухте фантастический спрос на омлеты из паучьих яиц! Проблема в том... что яиц в Бухте нет.$B$BЯ чую прибыль!$B$BНа Утесе Ветрорезов и в Сиширском каньоне, в Когтистых горах на северо-западе, живут моховые пауки. Принеси мне их яйца, и я неплохо заплачу!$B$BНа Утесе Ветрорезов паучьи кладки можно найти под оставшимися деревьями.$B$BВ Сиширском каньоне... хм, если у тебя слабый желудок, можешь собирать яйца только на Утесе Ветрорезов...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мебоку Миззриксу из Кабестана 15 яиц мохового паука.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1070,'На страже в Когтистых горах','Привет тебе, $n.$B$BСудя по виду, ты много путешествуешь. Тебе приходилось бывать в Когтистых горах? Эта земля опустошена Торговой Компанией и прочими врагами ночных эльфов. $B$BНедавно часовой Волкопас послала туда мою подругу Келу Копье Тени, чтобы она узнала, что происходит в тех землях, однако до сих пор от нее нет вестей. Я еще беспокоюсь и потому, что Альянс отправил вместе с ней гнома-мага... это, несомненно, повод для тревоги.$B$BМожет быть, ты найдешь ее и пошлешь весточку мне?','Найдите Келу Копье Тени, которая наблюдает за долиной, выходящей к Утесу Ветрорезов в Когтистых горах.','А, так ты здесь по просьбе Тары из Ясеневого леса... я так скучаю по ней, по моей родине, по друзьям. Должно быть, ей хорошо среди часовых, раз прочие дела передает путникам. Я горжусь за нее.$B$BРада познакомиться с тобой, $n.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На страже в Когтистых горах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $n.$B$BСудя по виду, ты много путешествуешь. Тебе приходилось бывать в Когтистых горах? Эта земля опустошена Торговой Компанией и прочими врагами ночных эльфов. $B$BНедавно часовой Волкопас послала туда мою подругу Келу Копье Тени, чтобы она узнала, что происходит в тех землях, однако до сих пор от нее нет вестей. Я еще беспокоюсь и потому, что Альянс отправил вместе с ней гнома-мага... это, несомненно, повод для тревоги.$B$BМожет быть, ты найдешь ее и пошлешь весточку мне?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Келу Копье Тени, которая наблюдает за долиной, выходящей к Утесу Ветрорезов в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, так ты здесь по просьбе Тары из Ясеневого леса... я так скучаю по ней, по моей родине, по друзьям. Должно быть, ей хорошо среди часовых, раз прочие дела передает путникам. Я горжусь за нее.$B$BРада познакомиться с тобой, $n.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1071,'Отсрочка для гнома','Понимаешь ли, $n, я состою в Просвещенной Ассамблее Чародейства, Алхимии и Технических Наук, и моя цель... нет, мой ДОЛГ! – показать ночным эльфам, что единение магии, реактивов и механизмов поможет спасти их леса.$B$BОднако это тяжелая война, а гоблины, похоже, плодятся, словно кролики. У меня даже нет времени воплотить в жизнь свои новые изобретения!$B$BМне нужно время для планирования и организации. Но для этого мне потребуется твоя помощь – сдерживать натиск гоблинов у Утеса Ветрорезов к востоку отсюда...','Убейте 10 лесорубов и 10 лесозаготовителей Торговой Компании и вернитесь к Гаксиму Ржавошиппи в Каменный Коготь.','Спасибо тебе за помощь, $n. Да и вернуться тебе удалось как раз вовремя.$B$BКажется, я выработал идеальный план... взрывчатка. Нет, это не сам план, это его часть.$B$BПонимаешь ли, я использую сильные взрывчатые вещества – не волнуйся, они далеко не так опасны, как считается – для того, чтобы припугнуть гоблинов. Я смогу как следует нагнать на них страху, разместив в ключевых местах на границах горной местности заряды, однако в ближайшие несколько дней мне может не хватить материалов...','Как идет битва, $N?','Вернитесь к Гаксиму Ржавошиппи на Паучий тракт, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отсрочка для гнома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понимаешь ли, $n, я состою в Просвещенной Ассамблее Чародейства, Алхимии и Технических Наук, и моя цель... нет, мой ДОЛГ! – показать ночным эльфам, что единение магии, реактивов и механизмов поможет спасти их леса.$B$BОднако это тяжелая война, а гоблины, похоже, плодятся, словно кролики. У меня даже нет времени воплотить в жизнь свои новые изобретения!$B$BМне нужно время для планирования и организации. Но для этого мне потребуется твоя помощь – сдерживать натиск гоблинов у Утеса Ветрорезов к востоку отсюда...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 лесорубов и 10 лесозаготовителей Торговой Компании и вернитесь к Гаксиму Ржавошиппи в Каменный Коготь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе за помощь, $n. Да и вернуться тебе удалось как раз вовремя.$B$BКажется, я выработал идеальный план... взрывчатка. Нет, это не сам план, это его часть.$B$BПонимаешь ли, я использую сильные взрывчатые вещества – не волнуйся, они далеко не так опасны, как считается – для того, чтобы припугнуть гоблинов. Я смогу как следует нагнать на них страху, разместив в ключевых местах на границах горной местности заряды, однако в ближайшие несколько дней мне может не хватить материалов...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идет битва, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гаксиму Ржавошиппи на Паучий тракт, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1072,'Старый коллега','Устройство, о котором я думаю – моя самая продвинутая версия на сегодняшний день. Но мне нужно особое зелье, чтобы это устройство заработало. Я думаю, нам нужно добыть хороший состав, поскольку эта миссия может стать для тебя последней.$B$BА для этого нам нужно мощное взрывчатое вещество: нитромирглицероний.$B$BЕдинственный, кто может создать НГ-5, это мой старый приятель – Ломак Демонтирс. Поищи его в Городе Механиков.$B$BЕсли уговоришь его сделать для нас немного НГ-5, то я начну работать над размещением своих устройств.','Поговорите с Ломаком Демонтирсом в Стальгорне.','А-а-а... Тебя послал Гаксим, вот как? А откуда мне знать, что ты не врешь? Ась? Ась?..') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старый коллега',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Устройство, о котором я думаю – моя самая продвинутая версия на сегодняшний день. Но мне нужно особое зелье, чтобы это устройство заработало. Я думаю, нам нужно добыть хороший состав, поскольку эта миссия может стать для тебя последней.$B$BА для этого нам нужно мощное взрывчатое вещество: нитромирглицероний.$B$BЕдинственный, кто может создать НГ-5, это мой старый приятель – Ломак Демонтирс. Поищи его в Городе Механиков.$B$BЕсли уговоришь его сделать для нас немного НГ-5, то я начну работать над размещением своих устройств.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ломаком Демонтирсом в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А-а-а... Тебя послал Гаксим, вот как? А откуда мне знать, что ты не врешь? Ась? Ась?..',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1073,'Неумение + реактивы = потеха!','Ха-ха-ха!.. Тебе нужен нитромирглицероний, чтобы остановить гоблинов, уничтожающих лес?!$B$BМне все равно, знаешь ты Гаксима или нет... я дам тебе этот состав, чтобы посмотреть, как кого-нибудь разнесет на мелкие кусочки: или тебя, или гоблинов.$B$BНо есть проблемка: у меня кончились химикалии.$B$BНо вот что я тебе скажу: принесешь мне нужные зелья, и я прямо сразу же смешаю для тебя составчик.$B$BПо крайней мере, ты докажешь, что кое-что понимаешь в алхимии, прежде, чем я передам тебе образец своего величайшего творения.','Принесите 4 крохотных флакона с зельем маны и 2 слабых эликсира стойкости Ломаку Демонтирсу в Стальгорн.','Вот это подойдет.$B$BНе знай я тебя, я бы сказал, что ты кое-что понимаешь в алхимии... Ладненько, ладненько... в мире есть не только мечи и колдовство, верно?','Я не могу сделать нитромирглицероний без этих зелий... они жизненно важны для его создания.','Вернитесь к Ломаку Демонтирсу в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неумение + реактивы = потеха!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ха-ха-ха!.. Тебе нужен нитромирглицероний, чтобы остановить гоблинов, уничтожающих лес?!$B$BМне все равно, знаешь ты Гаксима или нет... я дам тебе этот состав, чтобы посмотреть, как кого-нибудь разнесет на мелкие кусочки: или тебя, или гоблинов.$B$BНо есть проблемка: у меня кончились химикалии.$B$BНо вот что я тебе скажу: принесешь мне нужные зелья, и я прямо сразу же смешаю для тебя составчик.$B$BПо крайней мере, ты докажешь, что кое-что понимаешь в алхимии, прежде, чем я передам тебе образец своего величайшего творения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 крохотных флакона с зельем маны и 2 слабых эликсира стойкости Ломаку Демонтирсу в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это подойдет.$B$BНе знай я тебя, я бы сказал, что ты кое-что понимаешь в алхимии... Ладненько, ладненько... в мире есть не только мечи и колдовство, верно?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не могу сделать нитромирглицероний без этих зелий... они жизненно важны для его создания.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ломаку Демонтирсу в Стальгорн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1074,'Неумение + реактивы = потеха!','Ну вот тебе, держи. Тока поосторожней... это летучая смесь.$B$BЕсли Гаксим тебе и вправду друг, передай ему от меня привет. А если нет – взлетишь на воздух, вот будет тебе потеха.','Отнесите нитромирглицероний Гаксиму Ржавошиппи в Каменный Коготь.','А, славно, славно, с возвращением.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неумение + реактивы = потеха!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот тебе, держи. Тока поосторожней... это летучая смесь.$B$BЕсли Гаксим тебе и вправду друг, передай ему от меня привет. А если нет – взлетишь на воздух, вот будет тебе потеха.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите нитромирглицероний Гаксиму Ржавошиппи в Каменный Коготь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, славно, славно, с возвращением.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1075,'Свиток от Маурена','Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, еще не объяснил этого?$B$BНу так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошел почти без твоего участия. Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвется НГ-5.$B$BНо мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен. Ты сможешь отыскать его там в квартале магов. Он человек, так что будь $gвнимателен:внимательна;, не ошибись.','Найдите в Штормграде Коллина Маурена.','Да, вот то заклинание, которое тебе нужно – оно позволит производить взрывы на расстоянии... хмм.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свиток от Маурена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, еще не объяснил этого?$B$BНу так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошел почти без твоего участия. Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвется НГ-5.$B$BНо мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен. Ты сможешь отыскать его там в квартале магов. Он человек, так что будь $gвнимателен:внимательна;, не ошибись.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Штормграде Коллина Маурена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, вот то заклинание, которое тебе нужно – оно позволит производить взрывы на расстоянии... хмм.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (1076,'Демоны в Западном Крае','А, кажется, я понял. Заклинание послания... полагаю, именно этого эффекта он хочет добиться. $B$BМне нужно создать свиток с запечатленным на нем заклинанием. Для этого мне нужен прах Пыледемона.$B$BПока я собираю остальные компоненты, почему бы тебе не отправиться в Западный Край и не найти там одно из этих мерзких существ? Они опасны, но я уверен, что ты со всем справишься, если желаешь участвовать в одном из экспериментов Гаксима.$B$BКогда ты вернешься, я буду здесь.','Принесите прах Пыледемона Коллину Маурену в Штормград.','Подожди несколько секунд, и нужный тебе свиток будет готов.','Вернитесь к Коллину Маурену в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демоны в Западном Крае',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, кажется, я понял. Заклинание послания... полагаю, именно этого эффекта он хочет добиться. $B$BМне нужно создать свиток с запечатленным на нем заклинанием. Для этого мне нужен прах Пыледемона.$B$BПока я собираю остальные компоненты, почему бы тебе не отправиться в Западный Край и не найти там одно из этих мерзких существ? Они опасны, но я уверен, что ты со всем справишься, если желаешь участвовать в одном из экспериментов Гаксима.$B$BКогда ты вернешься, я буду здесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите прах Пыледемона Коллину Маурену в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Подожди несколько секунд, и нужный тебе свиток будет готов.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коллину Маурену в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1077,'Особая посылка для Гаксима','Вот, $n. Это то, что нужно.$B$BКогда в следующий раз увидишь Гаксима, передай ему от меня привет. Хотелось бы мне узнать, как закончится эта история.$B$BВсего тебе хорошего.','Отнесите свиток с посланием Гаксиму Ржавошиппи в Каменный Коготь.','Хо-хо, ты уже обратно? У тебя оно есть? Заклинание, в смысле?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Особая посылка для Гаксима',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, $n. Это то, что нужно.$B$BКогда в следующий раз увидишь Гаксима, передай ему от меня привет. Хотелось бы мне узнать, как закончится эта история.$B$BВсего тебе хорошего.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите свиток с посланием Гаксиму Ржавошиппи в Каменный Коготь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хо-хо, ты уже обратно? У тебя оно есть? Заклинание, в смысле?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1078,'Поиск для Маурена','Путешественники постоянно спрашивают меня о Когтистых горах. Похоже, все ищут там приключений, причем самых разных: кому-то нужны виверны, кому-то – элементали, а у кого-то дела с Торговой Компанией.$B$BВ Обугленной долине, прячущейся среди пиков Когтистых гор, некогда обитали особые виды василисков: их чешуя, размолотая в порошок, была прекрасным реактивом для некоторых заклинаний, созданных мною. $B$BЕсли эти василиски еще живут там, мне надо заполучить хотя бы несколько чешуек.$B$BЕсли не очень торопишься, удели на это немного времени, я хорошо заплачу тебе.','Принесите 8 кристаллических чешуй Коллину Маурену в Штормград.','Вернитесь к Коллину Маурену в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиск для Маурена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Путешественники постоянно спрашивают меня о Когтистых горах. Похоже, все ищут там приключений, причем самых разных: кому-то нужны виверны, кому-то – элементали, а у кого-то дела с Торговой Компанией.$B$BВ Обугленной долине, прячущейся среди пиков Когтистых гор, некогда обитали особые виды василисков: их чешуя, размолотая в порошок, была прекрасным реактивом для некоторых заклинаний, созданных мною. $B$BЕсли эти василиски еще живут там, мне надо заполучить хотя бы несколько чешуек.$B$BЕсли не очень торопишься, удели на это немного времени, я хорошо заплачу тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 кристаллических чешуй Коллину Маурену в Штормград.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коллину Маурену в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (1079,'Секретная операция – Альфа','Так вот, $n, смотри и слушай внимательно. Все устройства доделаны и готовы к использованию.$B$BВозьми эти листы – здесь все объясняется про детонаторы, взрывчатку и про то, как их разместить.$B$BПомни, успех твоей миссии не зависит от того, сколько разрушений ты сможешь причинить. План "Альфа" увенчается успехом в том случае, если ты принесешь технические чертежи Торговой Компании, находящиеся на лесопилке к югу от Скалистого Озера.','Добудьте технические чертежи Торговой Компании с лесопилки на Утесе Ветрорезов.','Просто великолепно! Это сильный удар по Торговой Компании.$B$BМы сможем узнать уязвимые места их машин, а также использовать их разработки для наших собственных целей. Поистине, это великий день.','Вернитесь к Гаксиму Ржавошиппи на Паучий тракт, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секретная операция – Альфа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так вот, $n, смотри и слушай внимательно. Все устройства доделаны и готовы к использованию.$B$BВозьми эти листы – здесь все объясняется про детонаторы, взрывчатку и про то, как их разместить.$B$BПомни, успех твоей миссии не зависит от того, сколько разрушений ты сможешь причинить. План "Альфа" увенчается успехом в том случае, если ты принесешь технические чертежи Торговой Компании, находящиеся на лесопилке к югу от Скалистого Озера.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте технические чертежи Торговой Компании с лесопилки на Утесе Ветрорезов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Просто великолепно! Это сильный удар по Торговой Компании.$B$BМы сможем узнать уязвимые места их машин, а также использовать их разработки для наших собственных целей. Поистине, это великий день.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гаксиму Ржавошиппи на Паучий тракт, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1080,'Секретная операция – Бета','План Бета – почти то же, что и план Альфа. $n.$B$BМы проводим отвлекающий маневр, а потом похищаем их драгоценные письма.$B$BГлавное – получить письма... помни это.$B$BНа листках, которые я дал тебе, сказано, где поместить взрывчатку. Не погибни и вернись с добытыми письмами...','Добудьте документы Торговой Компании из Рудника Ветрорезов у восточного края Утеса Ветрорезов.','Вернитесь к Гаксиму Ржавошиппи на Паучий тракт, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секретная операция – Бета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','План Бета – почти то же, что и план Альфа. $n.$B$BМы проводим отвлекающий маневр, а потом похищаем их драгоценные письма.$B$BГлавное – получить письма... помни это.$B$BНа листках, которые я дал тебе, сказано, где поместить взрывчатку. Не погибни и вернись с добытыми письмами...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте документы Торговой Компании из Рудника Ветрорезов у восточного края Утеса Ветрорезов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гаксиму Ржавошиппи на Паучий тракт, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1081,'Приглашение от Тиранды','$n, я уверена, что Тиранда Шелест Ветра лично хотела бы поблагодарить тебя за участие в этой миссии.$B$BМожет быть, это и незаметно с первого взгляда, но деяния, совершенные с твоей помощью, способны помочь нам закрепиться в Когтистых горах.$B$BЕсли хочешь и далее помогать нам в борьбе, отправляйся на встречу с Тирандой в Храм Луны в Дарнасе.','Найдите в Дарнасе Тиранду Шелест Ветра.','Приветствую тебя, $N. Мне доводилось и прежде слышать твое имя, и я рада видеть, что, не взирая на твою молодость, ты уже $Gизбрал:избрала; свой путь.$B$BТы окажешь мне великую честь, если примешь это как дар в знак нашего уважения к тебе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приглашение от Тиранды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я уверена, что Тиранда Шелест Ветра лично хотела бы поблагодарить тебя за участие в этой миссии.$B$BМожет быть, это и незаметно с первого взгляда, но деяния, совершенные с твоей помощью, способны помочь нам закрепиться в Когтистых горах.$B$BЕсли хочешь и далее помогать нам в борьбе, отправляйся на встречу с Тирандой в Храм Луны в Дарнасе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Дарнасе Тиранду Шелест Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую тебя, $N. Мне доводилось и прежде слышать твое имя, и я рада видеть, что, не взирая на твою молодость, ты уже $Gизбрал:избрала; свой путь.$B$BТы окажешь мне великую честь, если примешь это как дар в знак нашего уважения к тебе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1082,'Новости для часового Тенисил','$n, твоя помощь здесь оказалась поистине бесценной.$B$BЧасовые Ясеневого леса вознаградят тебя, если ты уведомишь их, что я и Гаксим живы. Скажи им, что мы трудимся над тем, чтобы остановить Торговую Компанию и исцелить эти земли.$B$BНайди в Астранааре Тару Тенисил, она обрадуется твоему возвращению и хорошим новостям.','Вернитесь к часовому Тенисил в Ясеневый лес.','Благодарю тебя, $N. Ты $Gсослужил:сослужила; Стражам хорошую службу.$B$BЯ рада узнать, что Каэла... и даже Гаксим живы и здоровы.$B$BТы заслуживаешь нашего уважения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новости для часового Тенисил',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, твоя помощь здесь оказалась поистине бесценной.$B$BЧасовые Ясеневого леса вознаградят тебя, если ты уведомишь их, что я и Гаксим живы. Скажи им, что мы трудимся над тем, чтобы остановить Торговую Компанию и исцелить эти земли.$B$BНайди в Астранааре Тару Тенисил, она обрадуется твоему возвращению и хорошим новостям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к часовому Тенисил в Ясеневый лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, $N. Ты $Gсослужил:сослужила; Стражам хорошую службу.$B$BЯ рада узнать, что Каэла... и даже Гаксим живы и здоровы.$B$BТы заслуживаешь нашего уважения.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1083,'Разъяренные духи','Не могу сказать точно, что Торговая Компания сделала с Долиной, однако ясно, что обитающие там существа взяли над ними верх.$B$BПредставители Торговой Компании подожгли лес, они использовали свои убийственные изобретения для того, чтобы как можно сильнее опустошить Долину.$B$BНо в невежестве своем они также освободили нечто иное: пылающих духов, элементалей огня, камня и ярости.$B$BИ этой земле никогда не узреть улыбку Элуны, пока эти существа бродят на свободе.$B$BПринеси мне их дымящиеся угли, дабы доказать, что тебе удалось сократить число разъяренных духов.','Принесите 8 тлеющих углей от любых элементалей огня из Обугленной долины Келе Копье Тени в Когтистые горы.','Останки нашего врага... твоя сила сослужила нам добрую службу, $N. Благодарю тебя.','При первом взгляде на Горелую Долину на глаза мне навернулись слезы, $N.','Вернитесь к Келе Копью Тени на Паучий тракт, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разъяренные духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не могу сказать точно, что Торговая Компания сделала с Долиной, однако ясно, что обитающие там существа взяли над ними верх.$B$BПредставители Торговой Компании подожгли лес, они использовали свои убийственные изобретения для того, чтобы как можно сильнее опустошить Долину.$B$BНо в невежестве своем они также освободили нечто иное: пылающих духов, элементалей огня, камня и ярости.$B$BИ этой земле никогда не узреть улыбку Элуны, пока эти существа бродят на свободе.$B$BПринеси мне их дымящиеся угли, дабы доказать, что тебе удалось сократить число разъяренных духов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 тлеющих углей от любых элементалей огня из Обугленной долины Келе Копье Тени в Когтистые горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Останки нашего врага... твоя сила сослужила нам добрую службу, $N. Благодарю тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','При первом взгляде на Горелую Долину на глаза мне навернулись слезы, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келе Копью Тени на Паучий тракт, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1084,'Раны Дерев','Мне кажется очевидным, что защитники Долины – древни – вели какие-то дела с Торговой Компанией, прежде чем их оттеснили прочь. К несчастью, даже эти некогда великие охранители ныне впали в нечестие.$B$BГаксим полагает, что их падение каким-то образом связано с оружием, которое гоблины использовали во время отступления.$B$BЯ сказала ему, что возьму образец из тела раненого древня и отдам на изучение, чтобы понять, правда ли это.$B$BПринеси мне немного шрапнели, чтобы гном мог дать мне ответ...','Принесите образец ржавой шрапнели Келе Копье Тени в Каменный Коготь.','Спасибо, $N.Этого должно быть более чем достаточно, чтобы Гаксим выяснил, каким образом скверна пала на древней. Я немедленно передам ему этот образец.','По-моему, Гаксим найдет шрапнели применение вне зависимости от того, как Торговая компания использовала ее в прошлом.','Вернитесь к Келе Копью Тени в Когтистые горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раны Дерев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне кажется очевидным, что защитники Долины – древни – вели какие-то дела с Торговой Компанией, прежде чем их оттеснили прочь. К несчастью, даже эти некогда великие охранители ныне впали в нечестие.$B$BГаксим полагает, что их падение каким-то образом связано с оружием, которое гоблины использовали во время отступления.$B$BЯ сказала ему, что возьму образец из тела раненого древня и отдам на изучение, чтобы понять, правда ли это.$B$BПринеси мне немного шрапнели, чтобы гном мог дать мне ответ...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите образец ржавой шрапнели Келе Копье Тени в Каменный Коготь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N.Этого должно быть более чем достаточно, чтобы Гаксим выяснил, каким образом скверна пала на древней. Я немедленно передам ему этот образец.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','По-моему, Гаксим найдет шрапнели применение вне зависимости от того, как Торговая компания использовала ее в прошлом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келе Копью Тени в Когтистые горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1085,'На страже в Когтистых горах','Положение здесь, в Каменном Когте, явно не способствует совместной работе ночного эльфа и гнома.$B$BТорговая Компания опустошила эти земли, и большая часть моего времени уходит на то, чтобы положить предел уничтожению.$B$BНе суди Гаксима преждевременно; он понимает, что нам с ним необходимо трудиться вместе.$B$BЕсли ты хочешь помочь нам, то для начала поговори с Гаксимом.$B$BИзвини, что пока не могу отослать тебя обратно к Таре с хорошими новостямиI. Может быть, вскоре...','Поговорите с Гаксимом в Когтистых горах.','Предательская... предательская и опасная, вот какова эта земля.$B$BНо я тут для того, чтобы показать ночным эльфам, что ежели призвать на помощь старое доброе инженерное дело и чуточку магии, то так будет вернее.$B$BВидишь ли, если убрать магию совсем, то ночным эльфам это никак не поможет – они без нее не могут. И мир без нее не может. А вот если подкрепить магию инженерным делом да алхимией, то так оно будет правильнее. Возможностей просто масса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На страже в Когтистых горах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Положение здесь, в Каменном Когте, явно не способствует совместной работе ночного эльфа и гнома.$B$BТорговая Компания опустошила эти земли, и большая часть моего времени уходит на то, чтобы положить предел уничтожению.$B$BНе суди Гаксима преждевременно; он понимает, что нам с ним необходимо трудиться вместе.$B$BЕсли ты хочешь помочь нам, то для начала поговори с Гаксимом.$B$BИзвини, что пока не могу отослать тебя обратно к Таре с хорошими новостямиI. Может быть, вскоре...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гаксимом в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Предательская... предательская и опасная, вот какова эта земля.$B$BНо я тут для того, чтобы показать ночным эльфам, что ежели призвать на помощь старое доброе инженерное дело и чуточку магии, то так будет вернее.$B$BВидишь ли, если убрать магию совсем, то ночным эльфам это никак не поможет – они без нее не могут. И мир без нее не может. А вот если подкрепить магию инженерным делом да алхимией, то так оно будет правильнее. Возможностей просто масса.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1086,'[DEPRECATED] Аэропорт ветролетов','Отрава готова. Остается только ее доставить адресату. И это придется сделать тебе, $n.$B$BУ Торговой Компании есть средства доставки сообщений и легкого груза от штаб-квартиры до Когтистых гор. Скорее всего, это маленький аэропорт, подходящий не для дирижабля, а для ветролета. Обыщи все области Когтистых гор, находящиеся под контролем Торговой Компании, и найди этот аэропорт, если он существует. Как найдешь, помести туда отраву.$B$BПоложишь – беги оттуда.','Отнесите распылитель ядовитого тумана в аэропорт Торговой Компании и вернуться к аптекарю Заме.','Вы должны найти аэропорт Торговой компании, если он существует, $N.','Установите распылитель ядовитого тумана.','Вернитесь к аптекарю Заме в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Аэропорт ветролетов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отрава готова. Остается только ее доставить адресату. И это придется сделать тебе, $n.$B$BУ Торговой Компании есть средства доставки сообщений и легкого груза от штаб-квартиры до Когтистых гор. Скорее всего, это маленький аэропорт, подходящий не для дирижабля, а для ветролета. Обыщи все области Когтистых гор, находящиеся под контролем Торговой Компании, и найди этот аэропорт, если он существует. Как найдешь, помести туда отраву.$B$BПоложишь – беги оттуда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите распылитель ядовитого тумана в аэропорт Торговой Компании и вернуться к аптекарю Заме.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы должны найти аэропорт Торговой компании, если он существует, $N.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Установите распылитель ядовитого тумана.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Заме в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1087,'Наследие Кенария','Ты и представить себе не можешь, как я ненавижу эти омерзительные земли! Отродья Кенария и калдорайские друиды, обитающие на этом пике, используют свою жалкую силу, чтобы подавить поток магии, даже так далеко на юг от их гнусного обиталища... их драгоценных лесов.$b$bЯ так хочу вернуться в Джеденар и купаться в потоках магии, но мой господин не позволяет мне вернуться, пока моя работа здесь не будет завершена.$b$bНе сомневаюсь, что ты любишь ночных эльфов и их союзников не больше, чем я. Помоги мне, и мы оба внакладе не останемся.','Убейте 4 сыновей Кенария, 4 дочерей Кенария и 4 кенарийских ботаников по поручению Брайлин Огненной Длани из Приюта у Солнечного Камня.','Я уже это чувствую... да... прекрасная мощь... струящийся поток. Как же глупы калдораи, что отвергают дары этого мира, не дают магии свободно, словно песня, струиться по жилам.\n\nКак же скучна и бесцветна жизнь без этого огненного потока!','Здесь направленная магия похожа на вытягивание воды из колодца ведром, полным дыр.','Вернитесь к Брайлин Огненной Длани в Приют у Солнечного Камня в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Кенария',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты и представить себе не можешь, как я ненавижу эти омерзительные земли! Отродья Кенария и калдорайские друиды, обитающие на этом пике, используют свою жалкую силу, чтобы подавить поток магии, даже так далеко на юг от их гнусного обиталища... их драгоценных лесов.$b$bЯ так хочу вернуться в Джеденар и купаться в потоках магии, но мой господин не позволяет мне вернуться, пока моя работа здесь не будет завершена.$b$bНе сомневаюсь, что ты любишь ночных эльфов и их союзников не больше, чем я. Помоги мне, и мы оба внакладе не останемся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 сыновей Кенария, 4 дочерей Кенария и 4 кенарийских ботаников по поручению Брайлин Огненной Длани из Приюта у Солнечного Камня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уже это чувствую... да... прекрасная мощь... струящийся поток. Как же глупы калдораи, что отвергают дары этого мира, не дают магии свободно, словно песня, струиться по жилам.\n\nКак же скучна и бесцветна жизнь без этого огненного потока!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Здесь направленная магия похожа на вытягивание воды из колодца ведром, полным дыр.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брайлин Огненной Длани в Приют у Солнечного Камня в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1088,'Ордан','Они думали, что могут остановить течение магии. Но они ошиблись. Они думали, что смогут спрятать Ордана – но я заполучу его голову!$b$bМагия дает мне способность видеть истину. Да... вот он где. Скрещение путей... На вершине великого древа в Ясеневом лесу. Название... Приют в Ночных Лесах. Один из старших сыновей лесного бога. Они унесли его прочь с этого пика прежде, чем я смогла найти его, однако его время на исходе.$b$bПринеси мне его голову, и я поделюсь с тобой могуществом.','Принесите голову Ордана Брайлин Огненной Длани к Приюту у Солнечного Камня.','Когда мой повелитель отправил меня на Пик Каменного Когтя, мне казалось, что нужно будет лишь погубить ночных эльфов, которые ползают по руинам нашего древнего храма Азшары, оскверняя святость этого места... но Хорданиус ускользнул от меня.','Вернитесь к Брайлин Огненной Длани в Приют у Солнечного Камня в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ордан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они думали, что могут остановить течение магии. Но они ошиблись. Они думали, что смогут спрятать Ордана – но я заполучу его голову!$b$bМагия дает мне способность видеть истину. Да... вот он где. Скрещение путей... На вершине великого древа в Ясеневом лесу. Название... Приют в Ночных Лесах. Один из старших сыновей лесного бога. Они унесли его прочь с этого пика прежде, чем я смогла найти его, однако его время на исходе.$b$bПринеси мне его голову, и я поделюсь с тобой могуществом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Ордана Брайлин Огненной Длани к Приюту у Солнечного Камня.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда мой повелитель отправил меня на Пик Каменного Когтя, мне казалось, что нужно будет лишь погубить ночных эльфов, которые ползают по руинам нашего древнего храма Азшары, оскверняя святость этого места... но Хорданиус ускользнул от меня.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брайлин Огненной Длани в Приют у Солнечного Камня в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1089,'Логово','На Пике Каменного Когтя друиды построили Логово Когтя, где хранят множество могущественных предметов.$b$bОни продумали сложный план, чтобы не дать этим предметам попасть в чужие руки.$b$bК счастью, мне удалось... вытянуть некоторые подробности из одного из них.$b$bВ маленьком светильнике у входа в логово ты найдешь спрятанный там ключ Хранителя Врат – с его помощью ты сможешь открыть тайники, расположенные вокруг логова. А предметы из этих тайников помогут тебе открыть сокровищницу, размещенную в одном из центральных помещений.','Отправляйтесь к пещере на Пике Каменного Когтя. При помощи Ключа Хранителя Врат добудьте предметы, спрятанные друидами. Используйте эти предметы для того, чтобы открыть сокровищницу Логова Когтя.','Когда три ключа вошли каждый в свое отверстие, посреди мерцающего сияния появились несколько предметов.','Три замочных скважины вырезаны в камне.','Разыщите сокровищницу Логова Когтя, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Логово',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На Пике Каменного Когтя друиды построили Логово Когтя, где хранят множество могущественных предметов.$b$bОни продумали сложный план, чтобы не дать этим предметам попасть в чужие руки.$b$bК счастью, мне удалось... вытянуть некоторые подробности из одного из них.$b$bВ маленьком светильнике у входа в логово ты найдешь спрятанный там ключ Хранителя Врат – с его помощью ты сможешь открыть тайники, расположенные вокруг логова. А предметы из этих тайников помогут тебе открыть сокровищницу, размещенную в одном из центральных помещений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к пещере на Пике Каменного Когтя. При помощи Ключа Хранителя Врат добудьте предметы, спрятанные друидами. Используйте эти предметы для того, чтобы открыть сокровищницу Логова Когтя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда три ключа вошли каждый в свое отверстие, посреди мерцающего сияния появились несколько предметов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Три замочных скважины вырезаны в камне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите сокровищницу Логова Когтя, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (1090,'Приказы Геренцо','Знаешь, когда-то я был второй по важности персоной во всем этом деле. Все изменилось, когда главным стал Геренцо. Уволил моего начальника Зиза Физзикса, а меня послал работать в копях. Но Зиз велел мне оставаться здесь и собирать сведения. Его новое начальство хорошо заплатит нам, если мы узнаем, что планирует Геренцо.$b$bВ любом случае, я точно знаю, что Геренцо приказал добыть как можно больше этой золотисто-зеленой руды. Я могу раздобыть образец, а ты передашь его Зизу. Но пока я этим занимаюсь, следи, не покажется ли стража.','Возьмите образец загадочной руды у Пузника после того, как он ее добудет.','Охраняйте Пузника, пока он добывает таинственную руду','Поговорите с Пузником в Когтистых горах.','Охраняйте Пузника, пока он добывает таинственную руду') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказы Геренцо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, когда-то я был второй по важности персоной во всем этом деле. Все изменилось, когда главным стал Геренцо. Уволил моего начальника Зиза Физзикса, а меня послал работать в копях. Но Зиз велел мне оставаться здесь и собирать сведения. Его новое начальство хорошо заплатит нам, если мы узнаем, что планирует Геренцо.$b$bВ любом случае, я точно знаю, что Геренцо приказал добыть как можно больше этой золотисто-зеленой руды. Я могу раздобыть образец, а ты передашь его Зизу. Но пока я этим занимаюсь, следи, не покажется ли стража.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите образец загадочной руды у Пузника после того, как он ее добудет.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Охраняйте Пузника, пока он добывает таинственную руду',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Пузником в Когтистых горах.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Охраняйте Пузника, пока он добывает таинственную руду',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1091,'Новости для Каэлы','$n,отнеси эти письма Каэле. Уверен, что она захочет это узнать. По крайней мере, часовые точно захотят.$B$BИ обязательно расскажи ей о наших успехах и о том, что мы не добились бы ничего без чуточки магии.','Отнесите документы Торговой Компании Келе Копье Тени в Когтистые горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новости для Каэлы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n,отнеси эти письма Каэле. Уверен, что она захочет это узнать. По крайней мере, часовые точно захотят.$B$BИ обязательно расскажи ей о наших успехах и о том, что мы не добились бы ничего без чуточки магии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите документы Торговой Компании Келе Копье Тени в Когтистые горы.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1092,'Приказы Геренцо','Полагаю, мне тоже нужно убираться отсюда. Не пройдет много времени, как слухи о том, что произошло здесь, распространятся достаточно высоко, и вряд ли меня в следующий раз встретят там с добром да лаской.$b$bМне нужно выбраться наружу и встретиться с Зизом. Надеюсь, он мне подыщет новую работенку!!!$b$bЯ попытаюсь тут слегка подчистить за собой, но тебе придется доставить образец руды Зизу немедля. Он говорил мне, что разбил свой лагерь где-то за западном склоне Утеса Ветрорезов. Удачи!','Доставьте Неопознанную Руду Зизу Физзиксу в Когтистые горы.','А, я так и знал, что правильно сделал, когда сказал Пузнику остаться. Я уверен, что инженеры в Нижней шахте захотят на это взглянуть.\n\nКонечно, я собираюсь прихранить кусочек для себя, но если они чего-то не узнают, то это им и не повредит, верно?','Что это? Я могу помочь тебе?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказы Геренцо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полагаю, мне тоже нужно убираться отсюда. Не пройдет много времени, как слухи о том, что произошло здесь, распространятся достаточно высоко, и вряд ли меня в следующий раз встретят там с добром да лаской.$b$bМне нужно выбраться наружу и встретиться с Зизом. Надеюсь, он мне подыщет новую работенку!!!$b$bЯ попытаюсь тут слегка подчистить за собой, но тебе придется доставить образец руды Зизу немедля. Он говорил мне, что разбил свой лагерь где-то за западном склоне Утеса Ветрорезов. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте Неопознанную Руду Зизу Физзиксу в Когтистые горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, я так и знал, что правильно сделал, когда сказал Пузнику остаться. Я уверен, что инженеры в Нижней шахте захотят на это взглянуть.\n\nКонечно, я собираюсь прихранить кусочек для себя, но если они чего-то не узнают, то это им и не повредит, верно?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это? Я могу помочь тебе?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1093,'Супердровосек 6000','Ну, Торговая Компания и наломала дров! О чем они только думали? Гоблинская компания нанимает гнома!$b$bК счастью для меня, Пароклапан всегда может узнать гения с первого взгляда. Он нанял меня сразу же, как меня выгнали оттуда!$b$bМне сказали, что компания строит какие-то огромные лесорубные машины, и Клапан хочет, чтобы я украл для него чертежи. К несчастью, Геренцо – вот ведь злобный гном! – хочет меня убить... может быть, ты вместо меня украдешь чертежи? Они должны быть у кого-то из операторов компании.','Добудьте чертежи "Супердровосека 6000" для Зиза Физзикса с Когтистых гор.','Эй, это то, что я думаю? Отлично!\n\nНу-с, посмотрим... и как мне понимать эту ерунду?.. и чем только думают эти гномы? Удивительно, что они хотя бы колесо сумели соорудить, не говоря уж об этих их обожаемых ветролетах.','Тебе удалось добыть чертежи? Я хочу порадовать нового начальника. Надеюсь, как только он убедится в моей верности – ну, насколько его вообще можно убедить... гоблинский гонор, и все такое... – он найдет достойное применение моему гениальному уму.','Вернитесь к Зизу Физзиксу на Утес Ветрорезов, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Супердровосек 6000',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, Торговая Компания и наломала дров! О чем они только думали? Гоблинская компания нанимает гнома!$b$bК счастью для меня, Пароклапан всегда может узнать гения с первого взгляда. Он нанял меня сразу же, как меня выгнали оттуда!$b$bМне сказали, что компания строит какие-то огромные лесорубные машины, и Клапан хочет, чтобы я украл для него чертежи. К несчастью, Геренцо – вот ведь злобный гном! – хочет меня убить... может быть, ты вместо меня украдешь чертежи? Они должны быть у кого-то из операторов компании.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте чертежи "Супердровосека 6000" для Зиза Физзикса с Когтистых гор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эй, это то, что я думаю? Отлично!\n\nНу-с, посмотрим... и как мне понимать эту ерунду?.. и чем только думают эти гномы? Удивительно, что они хотя бы колесо сумели соорудить, не говоря уж об этих их обожаемых ветролетах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть чертежи? Я хочу порадовать нового начальника. Надеюсь, как только он убедится в моей верности – ну, насколько его вообще можно убедить... гоблинский гонор, и все такое... – он найдет достойное применение моему гениальному уму.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зизу Физзиксу на Утес Ветрорезов, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1094,'Дальнейшие указания','В этом конверте – все сведения, которые я смог собрать до того, как меня выкинули за дверь... Внутренние документы Торговой Компании, кое-какие руководства, технические бумажки... О, и, конечно, чертежи "Супердровосека 6000".$b$bПароклапан обосновался в Кабестане в Степях. Тебе не доставит труда разыскать его, это такой мелкий зеленый тип.','Доставьте запечатанный конверт Пароклапану в Кабестан, что в Степях.','Физзик, да? Не то, чтоб я ему верил, но, кажется, это правильные сведения. Что б я ни отдал, лишь бы Торговая Компания убралась подальше!\n\nХотя они притащили с собой кое-какие хорошие машины... не буду отрицать, что от их изобретений есть польза, когда эти изобретения применяем мы, а не кто-то другой...','Эй, привет! Чем могу быть полезен?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дальнейшие указания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом конверте – все сведения, которые я смог собрать до того, как меня выкинули за дверь... Внутренние документы Торговой Компании, кое-какие руководства, технические бумажки... О, и, конечно, чертежи "Супердровосека 6000".$b$bПароклапан обосновался в Кабестане в Степях. Тебе не доставит труда разыскать его, это такой мелкий зеленый тип.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте запечатанный конверт Пароклапану в Кабестан, что в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Физзик, да? Не то, чтоб я ему верил, но, кажется, это правильные сведения. Что б я ни отдал, лишь бы Торговая Компания убралась подальше!\n\nХотя они притащили с собой кое-какие хорошие машины... не буду отрицать, что от их изобретений есть польза, когда эти изобретения применяем мы, а не кто-то другой...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эй, привет! Чем могу быть полезен?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1095,'[DEPRECATED] Дальнейшие указания','В Нижней шахте было много разговоров про этого гнома, нанятого Торговой Компанией. Торговые олигархи не одобряют, что Раздунк связался с Геренцо.$B$BРидлвокс велел мне позаботиться об этой проблеме, и я не сомневаюсь, что это указание от одного из богатых торговых принцев. Разумеется, директор мне об этом не говорил. Скажем так, у меня такое подозрение.$B$BКак бы то ни было, Геренцо необходимо устранить, и Физзику придется хорошо поработать.','Отнесите Зизу Физзиксу в Когтистых горах новые приказы.','Убрать Геренцо? Я только за!\n\nГномы вообще неприятный народ, но, судя по всему, этот Геренцо хуже других. Он был одним из главных инженеров Гномрегана и работал над тайным проектом – каким именно, нам так и не удалось узнать, хоть мы и пытались пробраться в Дун Морог. В докладах говорилось, что этот тайный проект буквально взорвался им в лицо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Дальнейшие указания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Нижней шахте было много разговоров про этого гнома, нанятого Торговой Компанией. Торговые олигархи не одобряют, что Раздунк связался с Геренцо.$B$BРидлвокс велел мне позаботиться об этой проблеме, и я не сомневаюсь, что это указание от одного из богатых торговых принцев. Разумеется, директор мне об этом не говорил. Скажем так, у меня такое подозрение.$B$BКак бы то ни было, Геренцо необходимо устранить, и Физзику придется хорошо поработать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Зизу Физзиксу в Когтистых горах новые приказы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Убрать Геренцо? Я только за!\n\nГномы вообще неприятный народ, но, судя по всему, этот Геренцо хуже других. Он был одним из главных инженеров Гномрегана и работал над тайным проектом – каким именно, нам так и не удалось узнать, хоть мы и пытались пробраться в Дун Морог. В докладах говорилось, что этот тайный проект буквально взорвался им в лицо.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1096,'Геренцо Терминатрикс','Один раз я встречал Геренцо и, скажу тебе, видок у него отвратнее некуда. Такое впечатление, что его плоть гниет и отпадает, части его тела заменены металлическими деталями и механизмами.$b$bК северо-востоку отсюда, высоко над Скалистым озером, вблизи водяного колеса находится пункт, откуда Геренцо наблюдает за всей местностью. Я не смог бы найти дорогу наверх, не говоря уж о том, чтобы справиться с Геренцо... Но тебе, кажется, это вполне под силу.$b$bЕсли ты убьешь его по моей просьбе, то получишь щедрое вознаграждение!','Принесите механическую руку Геренцо Терминатрикса Зиззу Физзиксу в Когтистые горы.','Взгляни на эту штуковину... только гном мог с такой управляться. Не понимаю только, зачем отрезать руку и заменять ее этой штукой, если можно просто сохранить обе руки и приделать третью!\n\nГномы, я тебе скажу...\n\nГеренцо, по крайней мере, если и не мертв, то неисправен. Надеюсь, этого доказательства будет достаточно, и Пароклапан даст мне назначение в одну из мастерских Союза ремонтников в Прибамбасске или, может быть, даже в Нижней шахте.','Паровой Клапан потребует какое-нибудь доказательство того, что Геренцо мертв. Полагаю, его механическая рука вполне сгодится.','Вернитесь к Зизу Физзиксу на Утес Ветрорезов, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Геренцо Терминатрикс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один раз я встречал Геренцо и, скажу тебе, видок у него отвратнее некуда. Такое впечатление, что его плоть гниет и отпадает, части его тела заменены металлическими деталями и механизмами.$b$bК северо-востоку отсюда, высоко над Скалистым озером, вблизи водяного колеса находится пункт, откуда Геренцо наблюдает за всей местностью. Я не смог бы найти дорогу наверх, не говоря уж о том, чтобы справиться с Геренцо... Но тебе, кажется, это вполне под силу.$b$bЕсли ты убьешь его по моей просьбе, то получишь щедрое вознаграждение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите механическую руку Геренцо Терминатрикса Зиззу Физзиксу в Когтистые горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Взгляни на эту штуковину... только гном мог с такой управляться. Не понимаю только, зачем отрезать руку и заменять ее этой штукой, если можно просто сохранить обе руки и приделать третью!\n\nГномы, я тебе скажу...\n\nГеренцо, по крайней мере, если и не мертв, то неисправен. Надеюсь, этого доказательства будет достаточно, и Пароклапан даст мне назначение в одну из мастерских Союза ремонтников в Прибамбасске или, может быть, даже в Нижней шахте.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Паровой Клапан потребует какое-нибудь доказательство того, что Геренцо мертв. Полагаю, его механическая рука вполне сгодится.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зизу Физзиксу на Утес Ветрорезов, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1097,'Просьба Элмора','Поговорите с Гримандом Элмором в Штормграде.','Ты поможешь мне с доставкой? Замечательно!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Элмора',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гримандом Элмором в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты поможешь мне с доставкой? Замечательно!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1098,'Ловчие смерти в крепости Темного Клыка','Готовясь к нападению на крепость Темного Клыка, мы отправили на разведку двух ловчих смерти. Они не возвращаются вот уже много дней, но без их отчета нам не организовать успешного нападения!$b$bИтак, вот твое задание, $n. Отправляйся в крепость Темного Клыка на юге и найди ловчих смерти Адаманта и Винсента. Найди их и помоги им, если сможешь.$b$bЭто очень опасное и важное задание, $n. Не подведи нас.','Найдите ловчих смерти Адаманта и Винсента.','Перед вами лежит израненное тело Винсента.\n\nСтраж смерти Адамант написал отчет Хадреку... Но что бы ни хотел добавить к его словам Винсент, он унес это с собой в могилу.\n\nВ мертвой руке зажата небольшая безделушка...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловчие смерти в крепости Темного Клыка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Готовясь к нападению на крепость Темного Клыка, мы отправили на разведку двух ловчих смерти. Они не возвращаются вот уже много дней, но без их отчета нам не организовать успешного нападения!$b$bИтак, вот твое задание, $n. Отправляйся в крепость Темного Клыка на юге и найди ловчих смерти Адаманта и Винсента. Найди их и помоги им, если сможешь.$b$bЭто очень опасное и важное задание, $n. Не подведи нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ловчих смерти Адаманта и Винсента.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Перед вами лежит израненное тело Винсента.\n\nСтраж смерти Адамант написал отчет Хадреку... Но что бы ни хотел добавить к его словам Винсент, он унес это с собой в могилу.\n\nВ мертвой руке зажата небольшая безделушка...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (1099,'Гоблины победили!','Вернитесь к Грубоступу в Тысячу Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблины победили!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грубоступу в Тысячу Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1100,'Дневник Хмурня','Вы медленно открываете потрепанный дневник Хенрига Хмурня...','Прочитайте дневник Хенрига Хмурня.','Говорите, что нашли этот дневник у мертвого дворфа? Дайте мне на минутку, хочу взглянуть...','Вас что-то беспокоит... Случилась какая-то неприятность?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дневник Хмурня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы медленно открываете потрепанный дневник Хенрига Хмурня...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте дневник Хенрига Хмурня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говорите, что нашли этот дневник у мертвого дворфа? Дайте мне на минутку, хочу взглянуть...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вас что-то беспокоит... Случилась какая-то неприятность?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1101,'Хозяйка Лабиринтов','Бедный Гералат! И этот дворф... Хмурень. Каким он был храбрецом!$B$BНельзя, чтобы их усилия пропали даром. Эта карга... Чарлга Остробок... нужно ее убить.$B$BРазумеется, поход в Лабиринты Иглошкурых будет опасным, а за помощью в Дарнас посылать некогда. Так что тебе, $n, придется собрать отряд самостоятельно.$B$BПринеси мне медальон Чарлги Остробок в доказательство ее смерти.','Принесите медальон Чарлги Остробок Фалфиндеру Хранителю Путей в Таланааре.','Наконец-то старая карга умерла. Это отличная новость, $N!$B$BВ наше опасное время всегда приятно встретить такого храбреца, как ты.$B$BТеперь, когда прислужники Остробок мертвы, мы сможем продолжить наши исследования той области. Возможно, теперь мы сможем узнать, почему место упокоения Агамаггана подверглось такому осквернению.$B$BОднако, боюсь, здесь не обошлось без предательства...','Пока Чарлга Остробок собирает свои силы в Лабиринтах Иглошкурых, эти земли будут в огромной опасности.','Вернитесь к хранителю дорог Фалфинделу в Таланаар, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хозяйка Лабиринтов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бедный Гералат! И этот дворф... Хмурень. Каким он был храбрецом!$B$BНельзя, чтобы их усилия пропали даром. Эта карга... Чарлга Остробок... нужно ее убить.$B$BРазумеется, поход в Лабиринты Иглошкурых будет опасным, а за помощью в Дарнас посылать некогда. Так что тебе, $n, придется собрать отряд самостоятельно.$B$BПринеси мне медальон Чарлги Остробок в доказательство ее смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите медальон Чарлги Остробок Фалфиндеру Хранителю Путей в Таланааре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то старая карга умерла. Это отличная новость, $N!$B$BВ наше опасное время всегда приятно встретить такого храбреца, как ты.$B$BТеперь, когда прислужники Остробок мертвы, мы сможем продолжить наши исследования той области. Возможно, теперь мы сможем узнать, почему место упокоения Агамаггана подверглось такому осквернению.$B$BОднако, боюсь, здесь не обошлось без предательства...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пока Чарлга Остробок собирает свои силы в Лабиринтах Иглошкурых, эти земли будут в огромной опасности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю дорог Фалфинделу в Таланаар, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1102,'Отмщение грядет!','Кэрн – благородный вождь, объединивший наш народ здесь, в Громовом Утесе.$b$bНо я не могу так легко простить тех, кто изгнал нас с земель наших предков. Мой народ много десятилетий прожил в Южных Степях. Те края для нас священны. Но нас изгнали многочисленные враги.$b$bМесть ждет старую ведьму Чарлгу Острый Бок, которая повелевает нечестивым воинством в Лабиринтах Иглошкурых.$b$bПринеси мне сердце этой ведьмы, $n, и я смогу спокойно умереть.','Принесите сердце Чарлги Остробок Ольду Каменному Копью в Громовой Утес.','Как только я узнаю, что грязные твари Лабиринтов Иглошкурых изгнаны из их мерзкого логова, я упокоюсь с миром, зная, что месть свершилась.\n\nТы изгнал этих игрогривов из Лабиринтов? И подтвердишь свою весть, показав мне сердце этой ведьмы?','Вернитесь к Ольду Каменному Копью в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отмщение грядет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кэрн – благородный вождь, объединивший наш народ здесь, в Громовом Утесе.$b$bНо я не могу так легко простить тех, кто изгнал нас с земель наших предков. Мой народ много десятилетий прожил в Южных Степях. Те края для нас священны. Но нас изгнали многочисленные враги.$b$bМесть ждет старую ведьму Чарлгу Острый Бок, которая повелевает нечестивым воинством в Лабиринтах Иглошкурых.$b$bПринеси мне сердце этой ведьмы, $n, и я смогу спокойно умереть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сердце Чарлги Остробок Ольду Каменному Копью в Громовой Утес.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как только я узнаю, что грязные твари Лабиринтов Иглошкурых изгнаны из их мерзкого логова, я упокоюсь с миром, зная, что месть свершилась.\n\nТы изгнал этих игрогривов из Лабиринтов? И подтвердишь свою весть, показав мне сердце этой ведьмы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ольду Каменному Копью в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1103,'Зов Воды','Привет, $gбратан:сеструха;! Ты тута, чтобы очистить воду и доказать Ислен, что не лыком $gшит:шита;?$B$BЯ тока что прикончил оскверненного духа воды и как раз собираюсь сунуть его браслеты и остатки воды в жаровню.$B$BА эт што? А-а-а. Тьев понимает, бывает непруха. Что ж, Тьев нехило тебе поможет, если тебе снова нужен чистый водный дух.$B$BПринеси мне сапту воды от Ислен, покажи, что $gготов:готова; к новому заходу, а я уж приготовлю тебе, че нужно.','Принесите Тьеву Мордуну, который находится в Серебряном бору, сапту воды, если вам не удалось поговорить с низшим воплощением воды.','Хвала тебе, смелый |3-6($C). Рифы побережья Западного Края будут освещены благодаря твоим трудам. Множество жизней будет спасено, пока горит факел.$B$BМеня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы.','У тебя уже есть сапта, $Gбратан:сеструха;?$B$BЯ знаю другого, у кого появились проблемы после убийства оскверненного духа, похоже, он ждал слишком долго, и он вышел из мира духов очень быстро. Противно видеть, что случается с другими, поэтому я пожалуй подожду здесь немного, чтобы убедится, что больше никто не нуждается в моей помощи.','Вернитесь к Тьеву Мордуну в Серебряный бор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $gбратан:сеструха;! Ты тута, чтобы очистить воду и доказать Ислен, что не лыком $gшит:шита;?$B$BЯ тока что прикончил оскверненного духа воды и как раз собираюсь сунуть его браслеты и остатки воды в жаровню.$B$BА эт што? А-а-а. Тьев понимает, бывает непруха. Что ж, Тьев нехило тебе поможет, если тебе снова нужен чистый водный дух.$B$BПринеси мне сапту воды от Ислен, покажи, что $gготов:готова; к новому заходу, а я уж приготовлю тебе, че нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Тьеву Мордуну, который находится в Серебряном бору, сапту воды, если вам не удалось поговорить с низшим воплощением воды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала тебе, смелый |3-6($C). Рифы побережья Западного Края будут освещены благодаря твоим трудам. Множество жизней будет спасено, пока горит факел.$B$BМеня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя уже есть сапта, $Gбратан:сеструха;?$B$BЯ знаю другого, у кого появились проблемы после убийства оскверненного духа, похоже, он ждал слишком долго, и он вышел из мира духов очень быстро. Противно видеть, что случается с другими, поэтому я пожалуй подожду здесь немного, чтобы убедится, что больше никто не нуждается в моей помощи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тьеву Мордуну в Серебряный бор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1104,'Яд Соляных равнин','Я нарисовал уже столько чертежей нового болида! И все их надо непременно воплотить в реальность!!!$B$BЯ разрабатываю новое топливо, которое будет гореть жарко-прежарко! Пока что у меня не получается, но, кажется, я знаю, что мне может помочь...$B$BУ скорпидов с Мерцающей равнины совершенно особый яд, в нем чрезвычайно много солей. Он уникален! Как раз он-то мне и нужен.$B$BПринеси мне их яда и поверь: тогда наши болиды просто взлетят!','Принесите 6 порций соленого яда скорпида Пшиксу Медноштифу на Мерцающую равнину.','Привет-привет! Ну, где же яд?','Вернитесь к Пшиксу Медноштифу в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яд Соляных равнин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я нарисовал уже столько чертежей нового болида! И все их надо непременно воплотить в реальность!!!$B$BЯ разрабатываю новое топливо, которое будет гореть жарко-прежарко! Пока что у меня не получается, но, кажется, я знаю, что мне может помочь...$B$BУ скорпидов с Мерцающей равнины совершенно особый яд, в нем чрезвычайно много солей. Он уникален! Как раз он-то мне и нужен.$B$BПринеси мне их яда и поверь: тогда наши болиды просто взлетят!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 порций соленого яда скорпида Пшиксу Медноштифу на Мерцающую равнину.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет-привет! Ну, где же яд?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пшиксу Медноштифу в поселок Виражи на Миражах, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1105,'Крепкие панцири','Мой брат составляет новое топливо для болида. Он в этом деле просто гений! Правда, боюсь, его новое гениальное топливо разъест всю машину...$B$BПоэтому я хочу укрепить топливные баки.$B$BЗдесь, на равнинах, живут черепахи с очень прочными панцирями. Из них-то я и хочу сделать это покрытие – оно должно выдержать топливо моего брата.$B$BНу как, не желаешь ли взяться за эту работу и принести мне несколько панцирей?','Принесите 9 крепких черепашьих панцирей Виззлу Медноштифу на Мерцающую равнину.','Вернитесь к Виззлу Медноштифу в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепкие панцири',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой брат составляет новое топливо для болида. Он в этом деле просто гений! Правда, боюсь, его новое гениальное топливо разъест всю машину...$B$BПоэтому я хочу укрепить топливные баки.$B$BЗдесь, на равнинах, живут черепахи с очень прочными панцирями. Из них-то я и хочу сделать это покрытие – оно должно выдержать топливо моего брата.$B$BНу как, не желаешь ли взяться за эту работу и принести мне несколько панцирей?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 9 крепких черепашьих панцирей Виззлу Медноштифу на Мерцающую равнину.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виззлу Медноштифу в поселок Виражи на Миражах, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1106,'Мартек Изгой','Я разрабатываю новый двигатель, с которым мой болид помчится быстрее ветра! Помчится так, что даже сможет взлететь! Осталось мне сделать поршни, которые выдержат очень, очень высокое давление. Все мои испытания провалились потому, что я не смог сделать достаточно крепких поршней!$B$BНо есть тот, кто может мне помочь.$B$BЕго зовут Мартек Изгой. Он отличный кузнец и знает о металлах больше других. Вот, отвези ему это письмо, я знаю, он поможет мне!$B$BПравда, живет он далеко – в Азероте, в Бесплодных землях, в одном лагере с гоблином!$B$BНайди его!','Отнесите письмо Пшикса Мартеку Изгою в Бесплодные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мартек Изгой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я разрабатываю новый двигатель, с которым мой болид помчится быстрее ветра! Помчится так, что даже сможет взлететь! Осталось мне сделать поршни, которые выдержат очень, очень высокое давление. Все мои испытания провалились потому, что я не смог сделать достаточно крепких поршней!$B$BНо есть тот, кто может мне помочь.$B$BЕго зовут Мартек Изгой. Он отличный кузнец и знает о металлах больше других. Вот, отвези ему это письмо, я знаю, он поможет мне!$B$BПравда, живет он далеко – в Азероте, в Бесплодных землях, в одном лагере с гоблином!$B$BНайди его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо Пшикса Мартеку Изгою в Бесплодные земли.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1107,'Средство против трения','Наш болид – это самая быстрая машина на равнинах! Она такая быстрая, что... я боюсь, что от трения ее разнесет на куски.$B$BЧтобы этого не произошло, мне нужен материал для покрытия движущихся частей машины. Он должен быть твердым, но не хрупким, и выдерживать соляную коррозию, иначе на Мерцающей равнине он долго не протянет.$B$BСлышали когда-нибудь про Коварный риф, $n? Это у побережья Тернистой долины. Там обитает племя мурлоков под названием Соляная Чешуя, и их хвостовые плавники как нельзя лучше подойдут для моего материала.','Принесите 10 соленых хвостовых плавников Виззлу Медноштифту на Мерцающую равнину.','Эй, где там мои плавники? Если не защитить машину от ее же собственной скорости, долго она тут не протянет!','Вернитесь к Виззлу Медноштифу в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Средство против трения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш болид – это самая быстрая машина на равнинах! Она такая быстрая, что... я боюсь, что от трения ее разнесет на куски.$B$BЧтобы этого не произошло, мне нужен материал для покрытия движущихся частей машины. Он должен быть твердым, но не хрупким, и выдерживать соляную коррозию, иначе на Мерцающей равнине он долго не протянет.$B$BСлышали когда-нибудь про Коварный риф, $n? Это у побережья Тернистой долины. Там обитает племя мурлоков под названием Соляная Чешуя, и их хвостовые плавники как нельзя лучше подойдут для моего материала.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 соленых хвостовых плавников Виззлу Медноштифту на Мерцающую равнину.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эй, где там мои плавники? Если не защитить машину от ее же собственной скорости, долго она тут не протянет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виззлу Медноштифу в поселок Виражи на Миражах, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1108,'Индарилий','Я здесь не только потому, что хочу держаться ото всех подальше. В Бесплодных землях очень много металла, $n, но добыть его сумеет не всякий.$B$BЭтот металл называется индарилий, и говорят, что он обладает удивительной сопротивляемостью к температуре и механическим воздействиям. Как раз то, что нужно Пшиксу для его машины.$B$BНо я должен все проверить. Принесите мне немного индарилия, а я исследую его свойства.$B$BНастоящая индарилиевая руда залегает глубоко в шахтах Ульдамана, но трогги из племени Каменного Свода иногда тоже носят с собой обломки индарилия. Принесите их мне.','Принесите 10 пластин индарилия Мартеку Изгою в Бесплодные земли.','Вернитесь к Мартеку Изгою в Знойные Пески, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Индарилий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я здесь не только потому, что хочу держаться ото всех подальше. В Бесплодных землях очень много металла, $n, но добыть его сумеет не всякий.$B$BЭтот металл называется индарилий, и говорят, что он обладает удивительной сопротивляемостью к температуре и механическим воздействиям. Как раз то, что нужно Пшиксу для его машины.$B$BНо я должен все проверить. Принесите мне немного индарилия, а я исследую его свойства.$B$BНастоящая индарилиевая руда залегает глубоко в шахтах Ульдамана, но трогги из племени Каменного Свода иногда тоже носят с собой обломки индарилия. Принесите их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 пластин индарилия Мартеку Изгою в Бесплодные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мартеку Изгою в Знойные Пески, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1109,'Груды гуано','Как видишь, $n, в Королевском фармацевтическом обществе проводят весьма... любопытные эксперименты.$B$BПоскольку я мастер-аптекарь, в мои обязанности входит наблюдать за самыми интересными проектами. Работы полно, а времени в обрез!$B$BХоть ты и |3-6($c), но, судя по всему, немало $gстранствовал:странствовала;. Не поможешь мне?$B$BНам очень нужно редкое вещество. Оно на редкость мерзкое, и его получают только от особой разновидности летучих мышей, которые водятся в дыре под названием Лабиринты Иглошкурых. Принеси мне гуано летучих мышей Лабиринтов, и мы примемся за работу...','Принесите 1 кучку гуано летучей мыши Лабиринтов опытному аптекарю Фаранеллу в Подгород.','Вижу, ты вернулся. Удалось добыть гуано летучих мышей?','Вернитесь к опытному аптекарю Фаранеллу в Район Фармацевтов, что в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Груды гуано',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как видишь, $n, в Королевском фармацевтическом обществе проводят весьма... любопытные эксперименты.$B$BПоскольку я мастер-аптекарь, в мои обязанности входит наблюдать за самыми интересными проектами. Работы полно, а времени в обрез!$B$BХоть ты и |3-6($c), но, судя по всему, немало $gстранствовал:странствовала;. Не поможешь мне?$B$BНам очень нужно редкое вещество. Оно на редкость мерзкое, и его получают только от особой разновидности летучих мышей, которые водятся в дыре под названием Лабиринты Иглошкурых. Принеси мне гуано летучих мышей Лабиринтов, и мы примемся за работу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 кучку гуано летучей мыши Лабиринтов опытному аптекарю Фаранеллу в Подгород.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вижу, ты вернулся. Удалось добыть гуано летучих мышей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к опытному аптекарю Фаранеллу в Район Фармацевтов, что в Подгороде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1110,'Детали болида','Хе-хе, да тут такие гонки бывают, как же без происшествий! Вы только оглянитесь – все Мерцающие равнины просто усыпаны обломками разбитых болидов.$B$BИ за все эти детали гномы и гоблины могут хорошенько заплатить. Они вечно ищут, какую бы еще рухлядь привинтить на свои тачки.$B$BСтупайте и принесите мне побольше деталей, а я вам хорошенько заплачу.','Принестие 30 деталей болида Кравелу Углебороду на Мерцающую равнину.','Вернитесь к Кравелу Углебороду в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Детали болида',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хе-хе, да тут такие гонки бывают, как же без происшествий! Вы только оглянитесь – все Мерцающие равнины просто усыпаны обломками разбитых болидов.$B$BИ за все эти детали гномы и гоблины могут хорошенько заплатить. Они вечно ищут, какую бы еще рухлядь привинтить на свои тачки.$B$BСтупайте и принесите мне побольше деталей, а я вам хорошенько заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принестие 30 деталей болида Кравелу Углебороду на Мерцающую равнину.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кравелу Углебороду в поселок Виражи на Миражах, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1111,'Управляющий пристанью Головокружилкинс','Моя работа – выполнять запросы покупателей, а гномы заказали у меня набор деталей. Эти детали еще неделю назад прибыли в Кабестан, но я все никак туда не выберусь.$B$BМожет, ты туда смотаешься? Вот, надо будет найти управляющего пристанью Головокружилкинcа и отдать ему этот заказ.$B$BЕсли выполнишь мое поручение, я смогу доверить тебе и другие поручения.$B$BРазумеется, твой труд будет достойно вознагражден.','Отнесите заказ на детали Крейвела управляющему пристанью Головокружилкинcу в Кабестан, что в Степях.','Ах, да! Детали для Крейвела. Хорошо, что за ними пришли! Этот хлам валяется тут уже давно, я даже начал бояться, что он проржавеет!','Следующий! Так, ты отправитель или получатель?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Управляющий пристанью Головокружилкинс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя работа – выполнять запросы покупателей, а гномы заказали у меня набор деталей. Эти детали еще неделю назад прибыли в Кабестан, но я все никак туда не выберусь.$B$BМожет, ты туда смотаешься? Вот, надо будет найти управляющего пристанью Головокружилкинcа и отдать ему этот заказ.$B$BЕсли выполнишь мое поручение, я смогу доверить тебе и другие поручения.$B$BРазумеется, твой труд будет достойно вознагражден.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите заказ на детали Крейвела управляющему пристанью Головокружилкинcу в Кабестан, что в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, да! Детали для Крейвела. Хорошо, что за ними пришли! Этот хлам валяется тут уже давно, я даже начал бояться, что он проржавеет!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Следующий! Так, ты отправитель или получатель?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1112,'Детали для Крейвела','Вот посылка для Крейвела, $n. И когда отнесете, скажите ему... что если ему нужны еще особые заказы, то придется заплатить по всем счетам!','Отнесите Кравелу Углебороду его детали на Мерцающую равнину, что в Тысяче Игл.','Ура, детали! Надо отнести их гномам. Но сначала...\n\nВынем оттуда кое-что...','Вы уже забрали части из Кабестана?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Детали для Крейвела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот посылка для Крейвела, $n. И когда отнесете, скажите ему... что если ему нужны еще особые заказы, то придется заплатить по всем счетам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Кравелу Углебороду его детали на Мерцающую равнину, что в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура, детали! Надо отнести их гномам. Но сначала...\n\nВынем оттуда кое-что...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы уже забрали части из Кабестана?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1113,'Сердца Доблести','Зачем мне редкий вид гуано, спросишь ты. Отвечаю. Я хочу выяснить в ходе эксперимента, какое воздействие окажут друг на друга два диаметрально противоположных химических вещества, особенно если оба смешать с токсичным реагентом, чтобы результаты были... погаже.$b$bВ северо-восточной части Тирисфальских лесов располагается Монастырь Алого ордена. В его стенах и за их пределами живут ненормальные последователи Алого ордена. Кого из них ты убьешь – меня не волнует, у всех могут быть нужные мне сердца.','Опытный аптекарь Фаранелл из Подгорода просит принести ему 20 сердец Доблести.','Ты уже вернулся из Монастыря Алого ордена? Для этого восхитительного эксперимента мне понадобится много сердец!\n\nНе сомневаюсь, Вариматас и Темная Госпожа будут рады, избавившись от алого сброда.','Вернитесь к опытному аптекарю Фаранеллу в Район Фармацевтов, что в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердца Доблести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зачем мне редкий вид гуано, спросишь ты. Отвечаю. Я хочу выяснить в ходе эксперимента, какое воздействие окажут друг на друга два диаметрально противоположных химических вещества, особенно если оба смешать с токсичным реагентом, чтобы результаты были... погаже.$b$bВ северо-восточной части Тирисфальских лесов располагается Монастырь Алого ордена. В его стенах и за их пределами живут ненормальные последователи Алого ордена. Кого из них ты убьешь – меня не волнует, у всех могут быть нужные мне сердца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Опытный аптекарь Фаранелл из Подгорода просит принести ему 20 сердец Доблести.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся из Монастыря Алого ордена? Для этого восхитительного эксперимента мне понадобится много сердец!\n\nНе сомневаюсь, Вариматас и Темная Госпожа будут рады, избавившись от алого сброда.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к опытному аптекарю Фаранеллу в Район Фармацевтов, что в Подгороде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1114,'Заказ гномов','Ну вот, у меня есть все, что нужно. Осталось только отнести эти детали Пшиксу Медноштифу. Он уже давно их ждет – полагаю, он даже не заметит отсутствие одной маленькой детальки. Не стоит даже упоминать, что я ее забрал.$B$BЭта деталька совсем маленькая и ненужная.$B$BПравда-правда.','Отнесите хрупкие детали машины Пшиксу Медноштифу на Мерцающую равнину.','Вот они! Мои гидромеханизмы и усилительные болты! То, что нужно. Большое спасибо!','Принес мне что-нибудь? Здорово! Ну-ка, посмотрим...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ гномов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, у меня есть все, что нужно. Осталось только отнести эти детали Пшиксу Медноштифу. Он уже давно их ждет – полагаю, он даже не заметит отсутствие одной маленькой детальки. Не стоит даже упоминать, что я ее забрал.$B$BЭта деталька совсем маленькая и ненужная.$B$BПравда-правда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите хрупкие детали машины Пшиксу Медноштифу на Мерцающую равнину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот они! Мои гидромеханизмы и усилительные болты! То, что нужно. Большое спасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принес мне что-нибудь? Здорово! Ну-ка, посмотрим...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1115,'Сплетник','Ну вот, гномам услугу оказали, пора и гоблинам помочь!$B$BГоворят, что гоблинского пилота, Назза Парового Котла, раньше звали не так. Интересно, почему он сменил имя? Наверное, это секрет, и, скорее всего, он дорожит этим секретом.$B$BЕсли кто и знает правду, то только Кразек из Пиратской Бухты, на южном мысу Тернистой долины. Поговорите с Кразеком и разузнайте у него про нашего пилота-гоблина.$B$BЕсли вам удастся добыть у него ценную информацию, то мы все сможем извлечь из нее прибыль.','Поговорите с Кразеком в Пиратской Бухте, что в Тернистой долине.','Хотите узнать про Назза Парового Котла? Вроде это гонщик с Мерцающей равнины?\n\nДа, я могу кое-что разузнать про него, но это будет нелегко. И не сразу.\n\nИ не за бесплатно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сплетник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, гномам услугу оказали, пора и гоблинам помочь!$B$BГоворят, что гоблинского пилота, Назза Парового Котла, раньше звали не так. Интересно, почему он сменил имя? Наверное, это секрет, и, скорее всего, он дорожит этим секретом.$B$BЕсли кто и знает правду, то только Кразек из Пиратской Бухты, на южном мысу Тернистой долины. Поговорите с Кразеком и разузнайте у него про нашего пилота-гоблина.$B$BЕсли вам удастся добыть у него ценную информацию, то мы все сможем извлечь из нее прибыль.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кразеком в Пиратской Бухте, что в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хотите узнать про Назза Парового Котла? Вроде это гонщик с Мерцающей равнины?\n\nДа, я могу кое-что разузнать про него, но это будет нелегко. И не сразу.\n\nИ не за бесплатно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1116,'Сонная пыль в болоте','Вытащить информацию из Назза – дело непростое, $n. Очень непростое. Но, раз уж вы ради этого приехали аж с Мерцающей равнины, то... не хотите ли попутешествовать еще немного?$B$BСобрали бы для меня кое-что, пока я буду связываться со своими источниками, а?$B$BХм... Что бы вам такое поручить? А, вот: сонная пыль с дракончиков из Болота Печали. Да, сонная пыль – это именно то, что мне нужно.$B$BПринесите мне ее, $n, а я взамен поделюсь с вами необходимой информацией.','Принесите 10 щепоток сонной пыли Кразеку в Пиратскую Бухту. Сонную пыль можно собрать с дракончиков на Болоте Печали.','Вернитесь к Кразеку на Пустынный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сонная пыль в болоте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вытащить информацию из Назза – дело непростое, $n. Очень непростое. Но, раз уж вы ради этого приехали аж с Мерцающей равнины, то... не хотите ли попутешествовать еще немного?$B$BСобрали бы для меня кое-что, пока я буду связываться со своими источниками, а?$B$BХм... Что бы вам такое поручить? А, вот: сонная пыль с дракончиков из Болота Печали. Да, сонная пыль – это именно то, что мне нужно.$B$BПринесите мне ее, $n, а я взамен поделюсь с вами необходимой информацией.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 щепоток сонной пыли Кразеку в Пиратскую Бухту. Сонную пыль можно собрать с дракончиков на Болоте Печали.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кразеку на Пустынный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1117,'Сплетни для Крейвела','Мне пришлось кое-кому оказать услугу, кое-кому подарить бутылку редкого эльфийского вина, а кое-что даже разузнать самостоятельно! Однако я добыл вам всю необходимую информацию.$B$BВот, я написал тут несколько интересных фактов касательно Назза Парового Молота. Делайте с ними что хотите, а для меня эта информация слишком опасна.$B$BИ не говорите никому, откуда вы ее достали!','Отнесите письмо с гоблинскими сплетнями Кравелу Углебороду на Мерцающую равнину, что в Тысяче Игл.','Нашли что-нибудь на Назза Парового Молота? Есть у него какой-нибудь секрет?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сплетни для Крейвела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне пришлось кое-кому оказать услугу, кое-кому подарить бутылку редкого эльфийского вина, а кое-что даже разузнать самостоятельно! Однако я добыл вам всю необходимую информацию.$B$BВот, я написал тут несколько интересных фактов касательно Назза Парового Молота. Делайте с ними что хотите, а для меня эта информация слишком опасна.$B$BИ не говорите никому, откуда вы ее достали!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо с гоблинскими сплетнями Кравелу Углебороду на Мерцающую равнину, что в Тысяче Игл.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашли что-нибудь на Назза Парового Молота? Есть у него какой-нибудь секрет?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1118,'Назад в Пиратскую Бухту','$n, ты – $gхороший:хорошая:c; |3-6($c), ты сможешь выполнить это задание и не болтать о нем налево-направо.$B$BЯ разрабатываю новый план. Он довольно рискованный, но если все получится, то мы озолотимся! А ты как раз отлично сможешь мне помочь.$B$BДля начала тебе надо вернуться в Пиратскую Бухту. Прости, $gдорогой:дорогая; $n. Я знаю, что ты уже $gбыл:была; там по моему поручению, но в этот раз тебе надо будет поговорить с Шиззи Пуззыриксом.$B$BОтдай ему это письмо, а если он попросит помочь, то не откажи ему. Поверь, оно того стоит.','Отнесите план Крейвела Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад в Пиратскую Бухту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты – $gхороший:хорошая:c; |3-6($c), ты сможешь выполнить это задание и не болтать о нем налево-направо.$B$BЯ разрабатываю новый план. Он довольно рискованный, но если все получится, то мы озолотимся! А ты как раз отлично сможешь мне помочь.$B$BДля начала тебе надо вернуться в Пиратскую Бухту. Прости, $gдорогой:дорогая; $n. Я знаю, что ты уже $gбыл:была; там по моему поручению, но в этот раз тебе надо будет поговорить с Шиззи Пуззыриксом.$B$BОтдай ему это письмо, а если он попросит помочь, то не откажи ему. Поверь, оно того стоит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите план Крейвела Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1119,'Смесь Занзила и "Дурацкое Крепкое"','Я понял, как смешать смесь Занзила с пивом, чтобы получилось убойное пойло – "Дурацкое крепкое"! Наверное, это именно то, что нужно Крейвелу. Отнесите ему, пусть попробует. Расскажете потом, как все прошло!$B$BКстати, $n, эту брагу надо употребить как можно скорее – смесь Занзила оказывает на пивную закваску не очень хороший эффект, так что оно очень скоро выдохнется.','Отнесите "Дурацкое Крепкое" Крейвелу на Мерцающую равнину, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смесь Занзила и "Дурацкое Крепкое"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я понял, как смешать смесь Занзила с пивом, чтобы получилось убойное пойло – "Дурацкое крепкое"! Наверное, это именно то, что нужно Крейвелу. Отнесите ему, пусть попробует. Расскажете потом, как все прошло!$B$BКстати, $n, эту брагу надо употребить как можно скорее – смесь Занзила оказывает на пивную закваску не очень хороший эффект, так что оно очень скоро выдохнется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите "Дурацкое Крепкое" Крейвелу на Мерцающую равнину, что в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1120,'Напоить гномов','Надо напоить "Дурацким Крепким" одну из команд на пит-стопах. Хочешь посмотреть, как оно подействует на гномов? Тогда возьми эль и передай его начальнику гномского гаража.$B$BИ поторопись – эта бурда быстро выдыхается.','Отнесите "Дурацкое Крепкое" начальнику гномского гаража в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Напоить гномов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо напоить "Дурацким Крепким" одну из команд на пит-стопах. Хочешь посмотреть, как оно подействует на гномов? Тогда возьми эль и передай его начальнику гномского гаража.$B$BИ поторопись – эта бурда быстро выдыхается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите "Дурацкое Крепкое" начальнику гномского гаража в поселок Виражи на Миражах, что в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1121,'Напоить гоблинов','Надо напоить "Дурацким Крепким" одну из команд на пит-стопах. Хочешь посмотреть, как оно подействует на гоблинов? Тогда возьми эль и передай его начальнику гномского гаража.$B$BИ поторопись – эта бурда быстро выдыхается.','Отнесите "Дурацкое Крепкое" начальнику гномского гаража в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Напоить гоблинов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо напоить "Дурацким Крепким" одну из команд на пит-стопах. Хочешь посмотреть, как оно подействует на гоблинов? Тогда возьми эль и передай его начальнику гномского гаража.$B$BИ поторопись – эта бурда быстро выдыхается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите "Дурацкое Крепкое" начальнику гномского гаража в поселок Виражи на Миражах, что в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1122,'Возвращение к Пуззыриксу','"Дурацкое Крепкое" отлично сработало! Я сделал ставку на следующую гонку и... надеюсь, команда, которую вы напоили, не забыла поставить на своей машине номер.$B$BУ меня еще одно задание для вас: отнесите эту записку обратно Шиззи Пуззыриксу в Пиратскую Бухту. Наверняка он захочет узнать, что эксперимент удался.$B$BНадо будет заказать у него еще этой выпивки для следующих гонок!','Отнесите отчет о "Дурацком Крепком" Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Пуззыриксу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Дурацкое Крепкое" отлично сработало! Я сделал ставку на следующую гонку и... надеюсь, команда, которую вы напоили, не забыла поставить на своей машине номер.$B$BУ меня еще одно задание для вас: отнесите эту записку обратно Шиззи Пуззыриксу в Пиратскую Бухту. Наверняка он захочет узнать, что эксперимент удался.$B$BНадо будет заказать у него еще этой выпивки для следующих гонок!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите отчет о "Дурацком Крепком" Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1123,'Рабин Сатурна','Для этого эконом хранителя Лунной поляны Ремула – Рабин Сатурна – ищет помощи. Нужно обследовать обширные пустоши к западу от Танариса и Ун\'Горо. Он живет в Ночной гавани, главном поселении Лунной поляны.$B$BЯ хочу, чтобы ты $Gпонимал:понимала; всю важность твоего присутствия там. Между ночными эльфами Дарнаса и Кругом Кенария Лунной поляны существуют трения. Но ты будь выше расовых предрассудков и прибегай к мудрости предков при общении с Кругом, $n. Да пребудет с тобой удача.','Поговорите с Рабином Сатурной в селении Ночная гавань в Лунной поляне. Лунная поляна находится между Оскверненным лесом и Зимними Ключами, туда можно добраться по дороге, идущей от Крепости Древобрюхов.','Я Рабин Сатурна. От лица хранителя Ремула и всех обитателей сего священного места привествую тебя.$B$BЯ ценю твою заинтересованность и горячую готовность помочь Кругу Кенария. Таурены не раз показывали стойкую приверженность принципам Кенария, и благодаря им Орда может пользоваться безопасностью Лунной поляны. Ведь благо Азерота – наша общая цель.$B$BЗдесь ты среди друзей, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рабин Сатурна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для этого эконом хранителя Лунной поляны Ремула – Рабин Сатурна – ищет помощи. Нужно обследовать обширные пустоши к западу от Танариса и Ун\'Горо. Он живет в Ночной гавани, главном поселении Лунной поляны.$B$BЯ хочу, чтобы ты $Gпонимал:понимала; всю важность твоего присутствия там. Между ночными эльфами Дарнаса и Кругом Кенария Лунной поляны существуют трения. Но ты будь выше расовых предрассудков и прибегай к мудрости предков при общении с Кругом, $n. Да пребудет с тобой удача.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рабином Сатурной в селении Ночная гавань в Лунной поляне. Лунная поляна находится между Оскверненным лесом и Зимними Ключами, туда можно добраться по дороге, идущей от Крепости Древобрюхов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я Рабин Сатурна. От лица хранителя Ремула и всех обитателей сего священного места привествую тебя.$B$BЯ ценю твою заинтересованность и горячую готовность помочь Кругу Кенария. Таурены не раз показывали стойкую приверженность принципам Кенария, и благодаря им Орда может пользоваться безопасностью Лунной поляны. Ведь благо Азерота – наша общая цель.$B$BЗдесь ты среди друзей, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1124,'Пустошь','К западу от Кратера Ун\'Горо, за северо-западным гребнем, лежит суровый пустынный край – Силитус. Немногие помнят, что там в древности развернулась война между ночными эльфами и злобной, чужеродной силой. Зло было повержено и заключено в оковы, но мы подозреваем, что сейчас некие силы хотят пробудить этот... невыразимый ужас.$B$BНайди Лайо Звездного Всполоха, одного из наших разведчиков в Силитусе. Ищи его на Погосте Отважных, последнем приюте павших в этих пустынных краях. Передай ему это письмо, и он доверится тебе.','Поговорите с Лайо Зведным Всполохом близ кладбища Погост Отважных в Силитусе и покажите ему письмо Рабина.','Так тебя послал Рабин? Что же, чувствуй себя как дома... если хоть кто-то может назвать домом этот богами забытый край.\n\nВо времена великих бед меня еще не было среди живых, но в этих краях есть места, которые наяву рисуют жуткую картину позабытого прошлого. С твоей помощью Круг Кенария, может быть, покончит с угрозой, которая, как мы думали, исчезла много поколений назад.','Эти земли не прощают беспечности, $C). Что привело тебя в пустоши Силитуса?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пустошь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К западу от Кратера Ун\'Горо, за северо-западным гребнем, лежит суровый пустынный край – Силитус. Немногие помнят, что там в древности развернулась война между ночными эльфами и злобной, чужеродной силой. Зло было повержено и заключено в оковы, но мы подозреваем, что сейчас некие силы хотят пробудить этот... невыразимый ужас.$B$BНайди Лайо Звездного Всполоха, одного из наших разведчиков в Силитусе. Ищи его на Погосте Отважных, последнем приюте павших в этих пустынных краях. Передай ему это письмо, и он доверится тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лайо Зведным Всполохом близ кладбища Погост Отважных в Силитусе и покажите ему письмо Рабина.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так тебя послал Рабин? Что же, чувствуй себя как дома... если хоть кто-то может назвать домом этот богами забытый край.\n\nВо времена великих бед меня еще не было среди живых, но в этих краях есть места, которые наяву рисуют жуткую картину позабытого прошлого. С твоей помощью Круг Кенария, может быть, покончит с угрозой, которая, как мы думали, исчезла много поколений назад.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти земли не прощают беспечности, $C). Что привело тебя в пустоши Силитуса?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1125,'Духи Южного Ветра','На юго-западе находится очень грустное место – деревня Южного Ветра. Именно с нее мы и начнем, $n.$B$BСудя по всему, некогда она была базой ночных эльфов для военных действий в Силитусе. Ее давным-давно захватили силитиды. Страшно представить, что там творилось в момент захвата...$B$BПо руинам бесцельно бродят духи павших друидов и стражниц. Исследуй эти края и освободи страдающие души, как подобает.','Освободите в деревне Южного Ветра души 8 истерзанных друидов и 8 истерзанных часовых и вернитесь к Лайо Звездному Всполоху на кладбище Силитуса, Погост Отважных.','Я подозревал, что немалую роль в гибели деревни сыграл огромный улей в башне неподалеку. Похоже, проделанная тобой работа подтверждает мои подозрения, улей представляет опасность для всей нашей деятельности.$B$BБлагодарю тебя за милость, оказанную душам павших. Я знаю, как нелегко это сделать. И все же я хочу вновь воззвать к тебе о помощи...','Ни одно существо не должно мучиться, как неупокоенные души, неважно, Альянсу оно служило или Орде. Это доброе дело – освободить несчастных призраков, $N.','Вернитесь к Лайо Звездному Всполоху в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи Южного Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На юго-западе находится очень грустное место – деревня Южного Ветра. Именно с нее мы и начнем, $n.$B$BСудя по всему, некогда она была базой ночных эльфов для военных действий в Силитусе. Ее давным-давно захватили силитиды. Страшно представить, что там творилось в момент захвата...$B$BПо руинам бесцельно бродят духи павших друидов и стражниц. Исследуй эти края и освободи страдающие души, как подобает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите в деревне Южного Ветра души 8 истерзанных друидов и 8 истерзанных часовых и вернитесь к Лайо Звездному Всполоху на кладбище Силитуса, Погост Отважных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я подозревал, что немалую роль в гибели деревни сыграл огромный улей в башне неподалеку. Похоже, проделанная тобой работа подтверждает мои подозрения, улей представляет опасность для всей нашей деятельности.$B$BБлагодарю тебя за милость, оказанную душам павших. Я знаю, как нелегко это сделать. И все же я хочу вновь воззвать к тебе о помощи...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ни одно существо не должно мучиться, как неупокоенные души, неважно, Альянсу оно служило или Орде. Это доброе дело – освободить несчастных призраков, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лайо Звездному Всполоху в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1126,'Улей в башне','Пора заняться ульем в деревне Южного Ветра, и мне кажется, я знаю, как это лучше сделать. Я знаю по опыту, что ульи силитидов очень чувствительны к окружающей среде; этим объясняется их нападения при звуках призрачного воя.$b$bСредоточие силы силитидов – башня, та самая, вокруг которой вьются осы. Ступай к этой башне и пробуди весь улей. Доложи обо всем, что удастся узнать, но соблюдай осторожность! Если попадется что-нибудь полезное, неси сюда.','Осмотрите башню деревни Южного Ветра и отыщите способ разворошить улей. Принесите все необычное, что попадется при выполнении задания Лайо Звездному Всполоху на кладбище Силитуса, Погост Отважных.','Что за... Что это?$B$BОно имеет форму... ящика? А дрянью-то как заросло... Стой, здесь видна часть того, что внутри. Неужели под всей этой гадостью скрывается книга?$B$BКажется, тебе удалось найти кое-что интересное, $N… по крайней мере, хочется на это надеяться. Может быть, это дневник или журнал, оставшийся с древних времен, лежавший в целости и сохранности под покровом хитиновой скорлупы.$B$BКажется, я знаю способ выяснить, что это.','Ну как, получилось? По крайней мере ты $Gцел:цела;. Удалось что-нибудь отыскать?','Вернитесь к Лайо Звездному Всполоху в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Улей в башне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора заняться ульем в деревне Южного Ветра, и мне кажется, я знаю, как это лучше сделать. Я знаю по опыту, что ульи силитидов очень чувствительны к окружающей среде; этим объясняется их нападения при звуках призрачного воя.$b$bСредоточие силы силитидов – башня, та самая, вокруг которой вьются осы. Ступай к этой башне и пробуди весь улей. Доложи обо всем, что удастся узнать, но соблюдай осторожность! Если попадется что-нибудь полезное, неси сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите башню деревни Южного Ветра и отыщите способ разворошить улей. Принесите все необычное, что попадется при выполнении задания Лайо Звездному Всполоху на кладбище Силитуса, Погост Отважных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что за... Что это?$B$BОно имеет форму... ящика? А дрянью-то как заросло... Стой, здесь видна часть того, что внутри. Неужели под всей этой гадостью скрывается книга?$B$BКажется, тебе удалось найти кое-что интересное, $N… по крайней мере, хочется на это надеяться. Может быть, это дневник или журнал, оставшийся с древних времен, лежавший в целости и сохранности под покровом хитиновой скорлупы.$B$BКажется, я знаю способ выяснить, что это.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, получилось? По крайней мере ты $Gцел:цела;. Удалось что-нибудь отыскать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лайо Звездному Всполоху в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1127,'"Дурацкое Крепкое"','Говорите, вам нужно "Дурацкое Крепкое", да? Хотите снова отправиться на гонки?$B$BНу ладно, принесите мне еще смеси Занзила, и я наварю вам еще.','Принесите 12 порций смеси Занзила Шиззи Пуззыриксу в Пиратскую Бухту.','Очень хорошо! Вот твоя плата.$B$BИ вот еще кое-что... за твою осмотрительность.','У тебя уже есть смеси Занзила, $N?','Вернитесь к Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Дурацкое Крепкое"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорите, вам нужно "Дурацкое Крепкое", да? Хотите снова отправиться на гонки?$B$BНу ладно, принесите мне еще смеси Занзила, и я наварю вам еще.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 порций смеси Занзила Шиззи Пуззыриксу в Пиратскую Бухту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо! Вот твоя плата.$B$BИ вот еще кое-что... за твою осмотрительность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя уже есть смеси Занзила, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (1128,'<NYI> Команда гномов хочет пить','Вернитесь к начальнику гномского гаража в Тысячу Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Команда гномов хочет пить',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к начальнику гномского гаража в Тысячу Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (1129,'<NYI> Команда гоблинов хочет пить','Вернитесь к начальнику гоблинского гаража в Тысячу Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Команда гоблинов хочет пить',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к начальнику гоблинского гаража в Тысячу Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1130,'Весть от Мелора','$n, Мелор Каменное Копыто узнал о ваших подвигах и наметил для вас путь.$B$BЕсли вы хотите пройти его, отправляйтесь в Громовой Утес и поговорите с Мелором. Его можно найти на вершине Охотников.','Поговорите с Мелором Каменным Копытом в Громовом Утесе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Весть от Мелора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, Мелор Каменное Копыто узнал о ваших подвигах и наметил для вас путь.$B$BЕсли вы хотите пройти его, отправляйтесь в Громовой Утес и поговорите с Мелором. Его можно найти на вершине Охотников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мелором Каменным Копытом в Громовом Утесе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1131,'Сталезуб','Иногда мы охотимся ради еды. Иногда – ради чести. А иногда мы охотимся для того, чтобы усвоить уроки Матери-Земли.$B$BНо охота, на которую я хочу отправить вас, не имеет с этими вещами ничего общего. Вам нужно будет убить существо, не подчиняющееся божественной воле Матери-Земли.$B$BГиена по кличке Сталезуб бродит по Тысяче Игл, к югу от Степей. К этой зверюге прибиваются другие гиены, и вместе они держат всех остальных более мирных животных в страхе.$B$BНайдите Сталезуба, $n. Найдите и убейте его.','Принесите ребро Сталезуба Мелору Каменному Копыту в Громовой Утес.','Вернитесь к Мелору Каменному Копыту на Вершину Охотников, что в Громовом Утесе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сталезуб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иногда мы охотимся ради еды. Иногда – ради чести. А иногда мы охотимся для того, чтобы усвоить уроки Матери-Земли.$B$BНо охота, на которую я хочу отправить вас, не имеет с этими вещами ничего общего. Вам нужно будет убить существо, не подчиняющееся божественной воле Матери-Земли.$B$BГиена по кличке Сталезуб бродит по Тысяче Игл, к югу от Степей. К этой зверюге прибиваются другие гиены, и вместе они держат всех остальных более мирных животных в страхе.$B$BНайдите Сталезуба, $n. Найдите и убейте его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ребро Сталезуба Мелору Каменному Копыту в Громовой Утес.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелору Каменному Копыту на Вершину Охотников, что в Громовом Утесе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1132,'Фиора Длинноушка','О, как я хочу снова вернуться на море! Почувствовать поцелуй ветра, покачаться на волнах, как в детстве на руках у моей милой мамы!$B$BКак же вам повезло, |3-6($c), вы еще можете оказаться на морском берегу!$B$BЭто моя работа – рассказывать всем неутомимым искателем приключений Калимдора о море. Если хотите, садитесь на корабль и плывите в прелестный порт Аубердин. Там поговорите с моей коллегой, эльфийкой по имени Фиора Длинноушка.$B$BОна отправит вас в незабываемое путешествие по Калимдору!','Поговорите с Фиорой Длинноушкой в Аубердине.','Добрый день! Вы приплыли из Гавани Менетил по поручению мистера Флинта? О, мистер Флинт разбирается в людях! Если он послал вас сюда – значит, здесь ваше место.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фиора Длинноушка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, как я хочу снова вернуться на море! Почувствовать поцелуй ветра, покачаться на волнах, как в детстве на руках у моей милой мамы!$B$BКак же вам повезло, |3-6($c), вы еще можете оказаться на морском берегу!$B$BЭто моя работа – рассказывать всем неутомимым искателем приключений Калимдора о море. Если хотите, садитесь на корабль и плывите в прелестный порт Аубердин. Там поговорите с моей коллегой, эльфийкой по имени Фиора Длинноушка.$B$BОна отправит вас в незабываемое путешествие по Калимдору!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Фиорой Длинноушкой в Аубердине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добрый день! Вы приплыли из Гавани Менетил по поручению мистера Флинта? О, мистер Флинт разбирается в людях! Если он послал вас сюда – значит, здесь ваше место.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1133,'Путешествие в Астранаар','$n, отправляйся в Астранаар. Уверен, такому преданному стороннику Альянса будет, чем заняться в городе. Поговори там с Шиндрелл Огненный Всполох и предложи ей свои услуги.$B$BНе стоит говорить ей, кто тебя прислал. Шиндрелл меня не знает...','Поговорите с Шиндрелл Огненный Всполох в Астранааре.','Вы здесь, чтобы предложить помощь Альянсу, $n? любой помощи. Хотя красота все еще живет в Ясеневом лесу... война добралась и до этих мест.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в Астранаар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, отправляйся в Астранаар. Уверен, такому преданному стороннику Альянса будет, чем заняться в городе. Поговори там с Шиндрелл Огненный Всполох и предложи ей свои услуги.$B$BНе стоит говорить ей, кто тебя прислал. Шиндрелл меня не знает...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Шиндрелл Огненный Всполох в Астранааре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы здесь, чтобы предложить помощь Альянсу, $n? любой помощи. Хотя красота все еще живет в Ясеневом лесу... война добралась и до этих мест.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1134,'Величавые виверны Каменного Когтя','Между нами и Ордой война не объявлена, однако мир между нами очень хрупок. Мы часто обнаруживаем, что среди нас тайно действуют их агенты. $B$BОб одной такой операции мы узнали из скрытых источников в Тераморе. Эти источники утверждают, что орки собирают яд величавых виверн поблизости от Мутного Озера в Когтистых горах, на юге. А потом орочьи убийцы используют этот яд для тайных смертоносных ударов против сил Альянса!$B$BЕсли это правда, мы обязаны остановить их, $n. Мы должны лишить их источника яда.','Принесите 12 ядовитых желез любой величавой виверны Шиндрелл Огненный Всполох в Астранаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Величавые виверны Каменного Когтя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Между нами и Ордой война не объявлена, однако мир между нами очень хрупок. Мы часто обнаруживаем, что среди нас тайно действуют их агенты. $B$BОб одной такой операции мы узнали из скрытых источников в Тераморе. Эти источники утверждают, что орки собирают яд величавых виверн поблизости от Мутного Озера в Когтистых горах, на юге. А потом орочьи убийцы используют этот яд для тайных смертоносных ударов против сил Альянса!$B$BЕсли это правда, мы обязаны остановить их, $n. Мы должны лишить их источника яда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 ядовитых желез любой величавой виверны Шиндрелл Огненный Всполох в Астранаар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1135,'Яд из Скального гнездовья','Как ты уже знаешь, орки часто приручают виверн в качестве ездовых животных. Но мало кто слышал о том, что яд виверны порой может быть ценнее самого животного. Так что, если желаете немного поохотиться, то у меня есть для вас работа.$B$BВ Тысяче Игл – это к западу отсюда – есть место под названием Скальное гнездовье. Там живут виверны, яд которых очень силен и чрезвычайно высоко ценится.','Принесите из Скального гнездовья 10 ядовитых желез для Фиоры Длинноушки в Терамор.','О-о-о, некоторые чуть ли не лопаются от яда, $N! Такие обычно собирают с очень юных виверн или с плодовитых самок. Наверное, нелегко вам пришлось в Скальном гнездовье!','Нашли Скальное гнездовье, $N? Как вас встретили тамошние виверны?','Вернитесь к Фиоре Длинноушке в Туманный Предел, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яд из Скального гнездовья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты уже знаешь, орки часто приручают виверн в качестве ездовых животных. Но мало кто слышал о том, что яд виверны порой может быть ценнее самого животного. Так что, если желаете немного поохотиться, то у меня есть для вас работа.$B$BВ Тысяче Игл – это к западу отсюда – есть место под названием Скальное гнездовье. Там живут виверны, яд которых очень силен и чрезвычайно высоко ценится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите из Скального гнездовья 10 ядовитых желез для Фиоры Длинноушки в Терамор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О-о-о, некоторые чуть ли не лопаются от яда, $N! Такие обычно собирают с очень юных виверн или с плодовитых самок. Наверное, нелегко вам пришлось в Скальном гнездовье!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нашли Скальное гнездовье, $N? Как вас встретили тамошние виверны?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фиоре Длинноушке в Туманный Предел, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1136,'Ледочрев','$n, настало время тебе отправиться в далекие земли. Ты $gготов:готова; к этому путешествию. $b$bТебе поручается убить Ледочрева – йети, живущего в Альтеракских горах. Он отлично маскируется, его белая шкура сливается со снегами его горного обиталища. Увидеть его можно лишь изредка. $b$bНо я расскажу тебе, как приманить такое существо, как этот йети. Вот, возьми этот свиток: на нем я написал, как привлечь Ледочрева. $b$bА теперь ступай, $n. Путь предстоит долгий, впереди тебя ждут испытания. Задание будет выполнено, когда ты вернешься ко мне с гривой Ледочрева.','Принесите гриву Ледочрева Мелору Каменному Копыту в Громовой Утес.','Для того, чтобы найти и сразить Леочрева, нужно обладать силой и смекалкой, $N. Оба эти качества у тебя есть.$B$BТвой путь привел тебя в долины Тысячи Игл и в высокие горы Альтерака. Однажды он проведет тебя по всем странам матери-земли – ведь именно таков путь охотника.','$GБыл:Была; ли ты в Альтеракских горах, $N? Ты $Gвстретился:встретилась; лицом к лицу с неуловимым йети Ледочревом?','Вернитесь к Мелору Каменному Копыту на Вершину Охотников, что в Громовом Утесе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ледочрев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, настало время тебе отправиться в далекие земли. Ты $gготов:готова; к этому путешествию. $b$bТебе поручается убить Ледочрева – йети, живущего в Альтеракских горах. Он отлично маскируется, его белая шкура сливается со снегами его горного обиталища. Увидеть его можно лишь изредка. $b$bНо я расскажу тебе, как приманить такое существо, как этот йети. Вот, возьми этот свиток: на нем я написал, как привлечь Ледочрева. $b$bА теперь ступай, $n. Путь предстоит долгий, впереди тебя ждут испытания. Задание будет выполнено, когда ты вернешься ко мне с гривой Ледочрева.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите гриву Ледочрева Мелору Каменному Копыту в Громовой Утес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Для того, чтобы найти и сразить Леочрева, нужно обладать силой и смекалкой, $N. Оба эти качества у тебя есть.$B$BТвой путь привел тебя в долины Тысячи Игл и в высокие горы Альтерака. Однажды он проведет тебя по всем странам матери-земли – ведь именно таков путь охотника.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GБыл:Была; ли ты в Альтеракских горах, $N? Ты $Gвстретился:встретилась; лицом к лицу с неуловимым йети Ледочревом?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелору Каменному Копыту на Вершину Охотников, что в Громовом Утесе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1137,'Новости для Пшикса','Индарилий обладает невероятной сопротивляемостью нагреву! Наверняка он подойдет для поршней Пшикса. Но ему потребуется настоящая индарилиевая руда, а не эти пластинки...$B$BЭту руду нужно добывать в глубине Ульдамана, на северной границе Бесплодных земель, – там ее навалом.$B$BПередавайте Пшиксу Медноштифту привет и скажите ему все, о чем я поведал вам.$B$BСчастливого пути, $n. Думаю, мы с вами еще увидимся: как только Пшикс прознает про индарилий, он как пить дать отправит вас в Ульдаман.','Поговорите с Пшиксом Медноштифтом на Мерцающей равнине, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новости для Пшикса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Индарилий обладает невероятной сопротивляемостью нагреву! Наверняка он подойдет для поршней Пшикса. Но ему потребуется настоящая индарилиевая руда, а не эти пластинки...$B$BЭту руду нужно добывать в глубине Ульдамана, на северной границе Бесплодных земель, – там ее навалом.$B$BПередавайте Пшиксу Медноштифту привет и скажите ему все, о чем я поведал вам.$B$BСчастливого пути, $n. Думаю, мы с вами еще увидимся: как только Пшикс прознает про индарилий, он как пить дать отправит вас в Ульдаман.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Пшиксом Медноштифтом на Мерцающей равнине, что в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1138,'Дары моря','Мне нравятся крабы. Крабы – это деликатесные дары моря! Их можно печь, жарить на гриле, варить, делать из них бульон. Еще их можно жарить на сковороде, во фритюре и просто жарить. Есть крабовый салат, крабовый суп, краб тушеный, краб перченый, краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый десерт. Вот и... ну, и все.$b$bЯ здесь сейчас рыбу ужу, потому охотиться на сочных крабов мне некогда. Можешь извлечь кусочки отличного мяса из рифовых крабов и покрытых илом крабов. Их можно печь, жарить на гриле, варить...','Соберите 6 кусочков отличного крабьего мяса для Груббера Блумпа в Аубердине.','...краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый сюрприз. Вот и... ну, и все.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дары моря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нравятся крабы. Крабы – это деликатесные дары моря! Их можно печь, жарить на гриле, варить, делать из них бульон. Еще их можно жарить на сковороде, во фритюре и просто жарить. Есть крабовый салат, крабовый суп, краб тушеный, краб перченый, краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый десерт. Вот и... ну, и все.$b$bЯ здесь сейчас рыбу ужу, потому охотиться на сочных крабов мне некогда. Можешь извлечь кусочки отличного мяса из рифовых крабов и покрытых илом крабов. Их можно печь, жарить на гриле, варить...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 кусочков отличного крабьего мяса для Груббера Блумпа в Аубердине.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','...краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый сюрприз. Вот и... ну, и все.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1139,'Утерянные таблички Воли','Мы смогли сдержать клан Тенегорн, отрезав их силы от Пика Черной горы, но задание Тяжелоступа еще не выполнено. Его смерть не должна быть напрасной. Он мечтал найти табличку воли: камень, на котором высекли магические письмена сами титаны, чтобы вдохнуть жизнь в созданных ими существ, – по крайней мере, так гласят легенды. $B$BМы должны заполучить табличку воли прежде, чем до нее доберется клан Тенегорн. $B$BВозвращайся в Ульдаман, найди табличку и принеси ее мне незамедлительно.','Найдите табличку воли и принесите ее советнику Белграму в Стальгорн.','<При виде таблички советник Белграм изумленно качает головой>$B$B$N, это поразительно! Я прослежу, чтобы табличка была доставлена королевским магам как можно скорее. Они непременно пожелают проверить, что в легендах истина, а что ложь. Ты $Gпомог:помогла; нашему народу более, чем я смел надеяться!','Мы должны выполнить завет Тяжелоступа, $N! Я столь многим обязан ему.$B$BТвоя экспедиция в Ульдаман служет не только этой цели, но и благу всего рода дворфов! Если табличка попадет в руки Черного Железа, кто знает, какую армию големов они смогут создать!','Вернитесь к советнику Белграму в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утерянные таблички Воли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы смогли сдержать клан Тенегорн, отрезав их силы от Пика Черной горы, но задание Тяжелоступа еще не выполнено. Его смерть не должна быть напрасной. Он мечтал найти табличку воли: камень, на котором высекли магические письмена сами титаны, чтобы вдохнуть жизнь в созданных ими существ, – по крайней мере, так гласят легенды. $B$BМы должны заполучить табличку воли прежде, чем до нее доберется клан Тенегорн. $B$BВозвращайся в Ульдаман, найди табличку и принеси ее мне незамедлительно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите табличку воли и принесите ее советнику Белграму в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<При виде таблички советник Белграм изумленно качает головой>$B$B$N, это поразительно! Я прослежу, чтобы табличка была доставлена королевским магам как можно скорее. Они непременно пожелают проверить, что в легендах истина, а что ложь. Ты $Gпомог:помогла; нашему народу более, чем я смел надеяться!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы должны выполнить завет Тяжелоступа, $N! Я столь многим обязан ему.$B$BТвоя экспедиция в Ульдаман служет не только этой цели, но и благу всего рода дворфов! Если табличка попадет в руки Черного Железа, кто знает, какую армию големов они смогут создать!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к советнику Белграму в Стальгорн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1140,'Башня Алталакса','Орочьи письмена немногим лучше детских каракулей. Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов. $b$bИз каракулей Илкруда можно понять, что у Атрикуса еще оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса.$b$bПоосторожнее там, $n, от вида кровавых храмов сатиров содрогнется даже $Gтакой закаленный:такая закаленная:c; |3-6($c), как ты.','Освободите заточенные души высокорожденных на Ночной поляне и Сатирнааре, затем вернитесь к Делгрену Очистителю на заставу Мейстры.','Возможно, мы слишком долго терпели сатиров в этом лесу. Я поговорю с Элиссой насчет этого, когда в другой раз поеду в Аубердин.$B$BТем не менее, раз самоцветы души уничтожены, сила Атрикуса сильно уменьшится. Мы должны воспользоваться этой возможностью и уничтожить его и его культ.','Однажды я услышал шепот, что история сатиров каким-то образом связана с историей ночных эльфов, но я обнаружил, что мои уважаемые хозяева не хотят говорить об этом.','Вернитесь к Делгрену Очистителю на Заставу Мейстры, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башня Алталакса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орочьи письмена немногим лучше детских каракулей. Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов. $b$bИз каракулей Илкруда можно понять, что у Атрикуса еще оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса.$b$bПоосторожнее там, $n, от вида кровавых храмов сатиров содрогнется даже $Gтакой закаленный:такая закаленная:c; |3-6($c), как ты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите заточенные души высокорожденных на Ночной поляне и Сатирнааре, затем вернитесь к Делгрену Очистителю на заставу Мейстры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возможно, мы слишком долго терпели сатиров в этом лесу. Я поговорю с Элиссой насчет этого, когда в другой раз поеду в Аубердин.$B$BТем не менее, раз самоцветы души уничтожены, сила Атрикуса сильно уменьшится. Мы должны воспользоваться этой возможностью и уничтожить его и его культ.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Однажды я услышал шепот, что история сатиров каким-то образом связана с историей ночных эльфов, но я обнаружил, что мои уважаемые хозяева не хотят говорить об этом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делгрену Очистителю на Заставу Мейстры, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1141,'Семья и рыболовная удочка','Мне нравится рыбачить. Семья Блумп славится своими рыбаками. Меня зовут Груббер Блумп. Я рыбак.$b$bЕсть одна рыбка, которую я хотел бы поймать в этих водах – местная разновидность окуня. Я раньше ходил на окуня на лодке, но с тех пор как побережье оккупировали эти противные мурлоки, ни одна лодка в море не выходит. Боюсь, они и окуней всех съедят.$b$bСлушай, хочешь помочь мне наловить окуней? Я б тебе от чистого сердца подарил фамильную удочку семьи Блумп! Это очень хорошая удочка!','Поймайте 6 морских окуней с Темных берегов для Груббера Блумпа в Аубердине.','Из окуней с Темных берегов можно приготовить множество вкусных блюд. Окуни хороши на вкус, но ловить их, я думаю, еще приятнее.$B$BТы еще не наловил окуньков?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семья и рыболовная удочка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нравится рыбачить. Семья Блумп славится своими рыбаками. Меня зовут Груббер Блумп. Я рыбак.$b$bЕсть одна рыбка, которую я хотел бы поймать в этих водах – местная разновидность окуня. Я раньше ходил на окуня на лодке, но с тех пор как побережье оккупировали эти противные мурлоки, ни одна лодка в море не выходит. Боюсь, они и окуней всех съедят.$b$bСлушай, хочешь помочь мне наловить окуней? Я б тебе от чистого сердца подарил фамильную удочку семьи Блумп! Это очень хорошая удочка!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 6 морских окуней с Темных берегов для Груббера Блумпа в Аубердине.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Из окуней с Темных берегов можно приготовить множество вкусных блюд. Окуни хороши на вкус, но ловить их, я думаю, еще приятнее.$B$BТы еще не наловил окуньков?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1142,'Последнее желание','Мне недолго осталось жить... о, я так слаб...$b$bХмурен... храбрый дворф, он отправился... предупредить Фалфиндера...$B$BНо прежде, чем я умру... $B$BПожалуйста, верни моей жене ее подвеску... ее украл один из этих негодяев...$B$BПодвеска связывает нас... это очень важно... Пожалуйста, верни подвеску моей Трешале... в Дарнас... $B$BИ расскажи ей... о моей смерти.','Найдите подвеску Трешалы и верните ее Трешале Бурый Ручей в Дарнас.','Что привело тебя ко мне, |3-6($r)?','Вернитесь к Трешале Бурый Ручей в Анклав Кенария, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последнее желание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне недолго осталось жить... о, я так слаб...$b$bХмурен... храбрый дворф, он отправился... предупредить Фалфиндера...$B$BНо прежде, чем я умру... $B$BПожалуйста, верни моей жене ее подвеску... ее украл один из этих негодяев...$B$BПодвеска связывает нас... это очень важно... Пожалуйста, верни подвеску моей Трешале... в Дарнас... $B$BИ расскажи ей... о моей смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите подвеску Трешалы и верните ее Трешале Бурый Ручей в Дарнас.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело тебя ко мне, |3-6($r)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трешале Бурый Ручей в Анклав Кенария, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1143,'Башня Алталакса','Понятно. Ну если то, о чем вы говорите, – правда, то сейчас самое время нанести удар. Я уверен, что Атрикус обосновался на самом верху башни. Однако будьте осторожны, его окружает множество сильных колдунов, гораздо более опасных, чем те, с кем вы встречались ранее.','Убейте Атрикуса Нарассина и принесите его голову Балтулу Удару Тени у башни Алталакса.','Я надеюсь, что после смерти Атрикуса демонические силы в этом районе отступят. Я не сомневаюсь, что они перегруппируются и вернутся, но тогда мы будем еще лучше подготовлены, чтобы встретить эту угрозу лицом к лицу.','Атрикус Нарассин – древний и могущественный чернокнижник. Может быть, нам стоило бы подождать, пока сам Делгрен не придет на помощь, но он, очевидно, очень сильно верит в вас, раз уж послал вас в одиночку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башня Алталакса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понятно. Ну если то, о чем вы говорите, – правда, то сейчас самое время нанести удар. Я уверен, что Атрикус обосновался на самом верху башни. Однако будьте осторожны, его окружает множество сильных колдунов, гораздо более опасных, чем те, с кем вы встречались ранее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Атрикуса Нарассина и принесите его голову Балтулу Удару Тени у башни Алталакса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я надеюсь, что после смерти Атрикуса демонические силы в этом районе отступят. Я не сомневаюсь, что они перегруппируются и вернутся, но тогда мы будем еще лучше подготовлены, чтобы встретить эту угрозу лицом к лицу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Атрикус Нарассин – древний и могущественный чернокнижник. Может быть, нам стоило бы подождать, пока сам Делгрен не придет на помощь, но он, очевидно, очень сильно верит в вас, раз уж послал вас в одиночку.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1144,'Импортер Вилликс','Наконец-то, помощь пришла!$B$BТы не представляешь, как долго я уже здесь торчу! Уже и не помню, когда последний раз высовывал нос наружу.$B$BВидишь ли, я предприниматель. Как говорится, всегда ищу выгоду. Вот, прослышал, что Мебок Миззрикс дает хорошую цену за растущий здесь корень синелиста. Ну я и подумал, что на этом можно заработать неплохие денежки. Как видишь, я немножко ошибся!$B$BВытащи меня отсюда, я тебе хорошо заплачу!','Проводите импортера Вилликса до выхода из Лабиринтов Иглошкурых.','Уф... спасибо, дружище! А вот и обещанная награда – за мной не заржавеет!','Помогите Импортеру Вилликсу сбежать из Лабиринтов Иглошкурых.','Поговорите с импортером Вилликсом у выхода из Лабиринта Иглошкурых.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Импортер Вилликс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то, помощь пришла!$B$BТы не представляешь, как долго я уже здесь торчу! Уже и не помню, когда последний раз высовывал нос наружу.$B$BВидишь ли, я предприниматель. Как говорится, всегда ищу выгоду. Вот, прослышал, что Мебок Миззрикс дает хорошую цену за растущий здесь корень синелиста. Ну я и подумал, что на этом можно заработать неплохие денежки. Как видишь, я немножко ошибся!$B$BВытащи меня отсюда, я тебе хорошо заплачу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите импортера Вилликса до выхода из Лабиринтов Иглошкурых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уф... спасибо, дружище! А вот и обещанная награда – за мной не заржавеет!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помогите Импортеру Вилликсу сбежать из Лабиринтов Иглошкурых.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с импортером Вилликсом у выхода из Лабиринта Иглошкурых.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1145,'Рой растет','Многие путешественники, приходившие в Перекресток, помогали мне собирать яйца на Полях Великанов, а потом рассказывали, какие страшные твари там живут. Мне хватило этих рассказов, чтобы убедиться в том, что мой хозяин недооценил этих насекомых, и что на самом деле они гораздо опаснее.$B$BМне нужен кто-то, кто отправится в Оргриммар и встретится там с Белгромом Каменной Булавой. Это очень серьезное дело, которое можно поручить только ответственному посыльному.$B$BБелгрома почти всегда можно найти у цехового дома воинов.','Отнесите запечатанную записку Коррана Белгрому Каменной Булаве в Оргриммар.','А, записка от Коррана. Он служит уже давно и очень преданно. Я как раз собирался узнать, как у него дела в Перекрестке.','Я завидую вам, |3-6($C). Похоже, вы давно не бывали в Оргриммаре...\n\nЯ бы и сам отправился в путешествие, во славу Вождя, но Траллу я нужен здесь. Однако он очень мудрый правитель, и я верю ему. Я готов оставаться здесь столько, сколько буду ему нужен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рой растет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие путешественники, приходившие в Перекресток, помогали мне собирать яйца на Полях Великанов, а потом рассказывали, какие страшные твари там живут. Мне хватило этих рассказов, чтобы убедиться в том, что мой хозяин недооценил этих насекомых, и что на самом деле они гораздо опаснее.$B$BМне нужен кто-то, кто отправится в Оргриммар и встретится там с Белгромом Каменной Булавой. Это очень серьезное дело, которое можно поручить только ответственному посыльному.$B$BБелгрома почти всегда можно найти у цехового дома воинов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанную записку Коррана Белгрому Каменной Булаве в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, записка от Коррана. Он служит уже давно и очень преданно. Я как раз собирался узнать, как у него дела в Перекрестке.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я завидую вам, |3-6($C). Похоже, вы давно не бывали в Оргриммаре...\n\nЯ бы и сам отправился в путешествие, во славу Вождя, но Траллу я нужен здесь. Однако он очень мудрый правитель, и я верю ему. Я готов оставаться здесь столько, сколько буду ему нужен.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1146,'Рой растет','Значит, Корран пришел к похожему заключению относительно этих насекомых: они представляют собой гораздо большую угрозу, чем мы думали.$B$BНесколько дней назад из Тысячи Игл ко мне вернулся полумертвый охотник. Его с отрядом отправили на Мерцающую равнину, чтобы выгнать оттуда бригаду дворфов-археологов, но во время боя на месте раскопок появились эти насекомые и чуть было не положили весь отряд.$B$BГлавным у них был Моктар Крин, и сейчас они разбили лагерь на границе Мерцающей равнины. Отнесите ему это письмо.','Доставьте запечатанное письмо Белгрома Моктару Крину в Тысячу Игл.','Не обращайте внимания на это грохочущее эхо. Это всего лишь гонка гномов и гоблинов на Равнинах – они носятся на кошмарных машинах, созданных по всем правилам так называемой "науки". Однако в Тысяче Игл есть куда более серьезные опасности, одна из которых недавно унесла жизни большей части моего отряда.\n\nНо мы останемся здесь до тех пор, пока не получим известие от Белгрома из Оргриммара. До этого мы будем держать позицию и стоять на страже.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рой растет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, Корран пришел к похожему заключению относительно этих насекомых: они представляют собой гораздо большую угрозу, чем мы думали.$B$BНесколько дней назад из Тысячи Игл ко мне вернулся полумертвый охотник. Его с отрядом отправили на Мерцающую равнину, чтобы выгнать оттуда бригаду дворфов-археологов, но во время боя на месте раскопок появились эти насекомые и чуть было не положили весь отряд.$B$BГлавным у них был Моктар Крин, и сейчас они разбили лагерь на границе Мерцающей равнины. Отнесите ему это письмо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте запечатанное письмо Белгрома Моктару Крину в Тысячу Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не обращайте внимания на это грохочущее эхо. Это всего лишь гонка гномов и гоблинов на Равнинах – они носятся на кошмарных машинах, созданных по всем правилам так называемой "науки". Однако в Тысяче Игл есть куда более серьезные опасности, одна из которых недавно унесла жизни большей части моего отряда.\n\nНо мы останемся здесь до тех пор, пока не получим известие от Белгрома из Оргриммара. До этого мы будем держать позицию и стоять на страже.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1147,'Рой растет','Хмм. Значит, Белгром считает этих монстров опасными и хочет, чтобы их загнали в те глубины, из которых они некогда выползли.$B$BЕму, значит, недостаточно того, что мы убили всех дворфов из Лиги исследователей – надо посылать полумертвый отряд в новый бой! Сами мы не справимся, по крайней мере в таком состоянии. Карьер находится к югу отсюда, и дворфов там, скорее всего, больше нет. Не хочешь ли помочь нам своим клинком или посохом?','Убейте 5 силитидов-искателей, 5 силитидов-трутней и 5 силитидов-захватчиков, а потом вернитесь к Моктару Крину в Тысячу Игл.','Куча народу приезжает на Мерцающие равнины, чтобы посмотреть гонки. Думаю, мы найдем достаточно искателей приключений для того, чтобы избавиться от этих насекомых. А до тех пор мой отряд не сможет покинуть этот пост.','Вернитесь к Моктару Крину в Лагерь Железного Камня, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рой растет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хмм. Значит, Белгром считает этих монстров опасными и хочет, чтобы их загнали в те глубины, из которых они некогда выползли.$B$BЕму, значит, недостаточно того, что мы убили всех дворфов из Лиги исследователей – надо посылать полумертвый отряд в новый бой! Сами мы не справимся, по крайней мере в таком состоянии. Карьер находится к югу отсюда, и дворфов там, скорее всего, больше нет. Не хочешь ли помочь нам своим клинком или посохом?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 силитидов-искателей, 5 силитидов-трутней и 5 силитидов-захватчиков, а потом вернитесь к Моктару Крину в Тысячу Игл.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Куча народу приезжает на Мерцающие равнины, чтобы посмотреть гонки. Думаю, мы найдем достаточно искателей приключений для того, чтобы избавиться от этих насекомых. А до тех пор мой отряд не сможет покинуть этот пост.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моктару Крину в Лагерь Железного Камня, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1148,'Части роя','Вы тщательно осматриваете панцирь. Повращав его в руках, вы видите, что полоски хитинового покрытия переплетены совершенно неповторимым образом, что делает панцирь невероятно прочным. Вы никогда в жизни не видели ничего подобного. Вы осматриваете останки дальше и понимаете, что эти существа очень сильны и высокоразвиты.$B$BЕще раз взглянув на эти останки, вы думаете, что Коррану было бы интересно обследовать этих существ поподробнее. Это помогло бы ему понять, кто они и откуда взялись.','Добудьте 1 сердце, 5 шпор и 3 целых силитидских панциря для Коррана из Перекрестка.','Вернитесь к Коррану на Перекресток, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Части роя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы тщательно осматриваете панцирь. Повращав его в руках, вы видите, что полоски хитинового покрытия переплетены совершенно неповторимым образом, что делает панцирь невероятно прочным. Вы никогда в жизни не видели ничего подобного. Вы осматриваете останки дальше и понимаете, что эти существа очень сильны и высокоразвиты.$B$BЕще раз взглянув на эти останки, вы думаете, что Коррану было бы интересно обследовать этих существ поподробнее. Это помогло бы ему понять, кто они и откуда взялись.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 1 сердце, 5 шпор и 3 целых силитидских панциря для Коррана из Перекрестка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коррану на Перекресток, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1149,'Испытание веры','Итак, ты $gнашел:нашла; меня – или, возможно, тебя привела сама судьба? Это неважно. Теперь ты здесь, и перед тобой лежит новый путь.$B$BЛичность складывается из души, тела и разума. Какие-то стороны характера определяются культурными традициями, о наличии других мы можем только догадываться. Если согласишься, я испытаю некоторые присущие тебе качества.$B$BЕсли ты пройдешь испытание, то станешь сильнее, если же нет – познаешь всю бездну Пустоты.$B$BПервое испытание – это испытание веры.','Если ваша вера сильна, прыгните с досок над Тысячью Игл.','Истинную силу нашего духа мы можем познать лишь при встрече с непредвиденной бедой. Ты поверил в себя, хотя и не был уверен, что выживешь. Твой разум открыт, и твой дух готов встретить все, что ждет впереди.\n\nЕсли желаешь, можешь приступить к следующему испытанию.','Прямо из Кабестана, свеженькие лезвия для пил Песни Войны! Да, они у меня с собой.\n\n..Но чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!\n\nЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защищать себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.\n\nИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?','Вернитесь к Дорну Вольному Ловчему в Безветренный каньон, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание веры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, ты $gнашел:нашла; меня – или, возможно, тебя привела сама судьба? Это неважно. Теперь ты здесь, и перед тобой лежит новый путь.$B$BЛичность складывается из души, тела и разума. Какие-то стороны характера определяются культурными традициями, о наличии других мы можем только догадываться. Если согласишься, я испытаю некоторые присущие тебе качества.$B$BЕсли ты пройдешь испытание, то станешь сильнее, если же нет – познаешь всю бездну Пустоты.$B$BПервое испытание – это испытание веры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если ваша вера сильна, прыгните с досок над Тысячью Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Истинную силу нашего духа мы можем познать лишь при встрече с непредвиденной бедой. Ты поверил в себя, хотя и не был уверен, что выживешь. Твой разум открыт, и твой дух готов встретить все, что ждет впереди.\n\nЕсли желаешь, можешь приступить к следующему испытанию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прямо из Кабестана, свеженькие лезвия для пил Песни Войны! Да, они у меня с собой.\n\n..Но чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!\n\nЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защищать себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.\n\nИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорну Вольному Ловчему в Безветренный каньон, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1150,'Испытание выносливости','Хорошо, что ты не теряешь смелости несмотря ни на что. Твоя вера крепка, и теперь настало время испытать твою силу.$B$BСначала тебе надо пройти испытание выносливости. Отправляйся в Логово Легкоперых – оно к западу от Заставы Вольного Ветра. Проберись в самую глубину логова и уничтожь там все запасы еды. К тому времени местные гарпии будут в ярости, и если ты останешься в живых, с тобой прилетит сразиться их предводительница – Гренка Кровавый Визг. Убей ее и принеси мне ее коготь, чтобы пройти это испытание.','Принесите коготь Гренки Дорну Вольному Ловчему в Тысячу Игл.','Гренка была очень сильна даже для такого |3-1($R) как ты. Сегодня ты можешь по праву гордиться собой.\n\nВо время испытания веры ты показал силу своего духа, а сегодня подтвердил, что физически ты готов к битве. Гарпии Легкого Пера мертвы, и теперь настало время нового испытания.','Чтобы пройти все назначенные испытания, ты должен подготовиться морально, духовно и физически.\n\nМы слишком часто рвемся вперед неподготовленными. Я считаю своим долгом подготовить всех новичков, которые приходят ко мне, вне зависимости от их племени. Они должны знать, с чем им предстоит столкнуться за порогом родного дома.','Вернитесь к Дорну Вольному Ловчему в Безветренный каньон, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание выносливости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, что ты не теряешь смелости несмотря ни на что. Твоя вера крепка, и теперь настало время испытать твою силу.$B$BСначала тебе надо пройти испытание выносливости. Отправляйся в Логово Легкоперых – оно к западу от Заставы Вольного Ветра. Проберись в самую глубину логова и уничтожь там все запасы еды. К тому времени местные гарпии будут в ярости, и если ты останешься в живых, с тобой прилетит сразиться их предводительница – Гренка Кровавый Визг. Убей ее и принеси мне ее коготь, чтобы пройти это испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите коготь Гренки Дорну Вольному Ловчему в Тысячу Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гренка была очень сильна даже для такого |3-1($R) как ты. Сегодня ты можешь по праву гордиться собой.\n\nВо время испытания веры ты показал силу своего духа, а сегодня подтвердил, что физически ты готов к битве. Гарпии Легкого Пера мертвы, и теперь настало время нового испытания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы пройти все назначенные испытания, ты должен подготовиться морально, духовно и физически.\n\nМы слишком часто рвемся вперед неподготовленными. Я считаю своим долгом подготовить всех новичков, которые приходят ко мне, вне зависимости от их племени. Они должны знать, с чем им предстоит столкнуться за порогом родного дома.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорну Вольному Ловчему в Безветренный каньон, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1151,'Испытание силы','Во времена древних богов элементалей можно было встретить повсюду. Они поклонялись древним богам, а боги своей силой поддерживали связь духов с этим миром. Когда же древние боги были изгнаны, элементали тоже покинули этот мир и теперь являются сюда только по зову могущественных магов.$B$BНо есть и исключения. Некоторые духи были достаточно сильны для того, чтобы остаться в этом мире, и одного из них зовут Рок\'Алим.$B$BДля того чтобы испытать свою силу, найди в Тысяче Игл Рок\'Алима и убей его.','Принесите фрагменты Рок\'Алима Дорну Вольному Ловчему в Тысячу Игл.','Испытание силы пройдено. Вы показали свою силу и храбрость и теперь готовы к последнему испытанию, после которого эти ритуалы завершатся.','Племена кентавров зовут Рок\'Алима Крушителем – из-за грохота, который издают его кулаки, которые он обрушивает на тех, кто достаточно смел или глуп для того, чтобы оказаться у него на пути.','Вернитесь к Дорну Вольному Ловчему в Безветренный каньон, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во времена древних богов элементалей можно было встретить повсюду. Они поклонялись древним богам, а боги своей силой поддерживали связь духов с этим миром. Когда же древние боги были изгнаны, элементали тоже покинули этот мир и теперь являются сюда только по зову могущественных магов.$B$BНо есть и исключения. Некоторые духи были достаточно сильны для того, чтобы остаться в этом мире, и одного из них зовут Рок\'Алим.$B$BДля того чтобы испытать свою силу, найди в Тысяче Игл Рок\'Алима и убей его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите фрагменты Рок\'Алима Дорну Вольному Ловчему в Тысячу Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Испытание силы пройдено. Вы показали свою силу и храбрость и теперь готовы к последнему испытанию, после которого эти ритуалы завершатся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Племена кентавров зовут Рок\'Алима Крушителем – из-за грохота, который издают его кулаки, которые он обрушивает на тех, кто достаточно смел или глуп для того, чтобы оказаться у него на пути.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорну Вольному Ловчему в Безветренный каньон, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1152,'Испытание знаний','Твои испытания почти закончились, но проверку знаний проводить буду не я. Тебе придется посетить другие места и усвоить там новые уроки.$B$BЕсли ты $gготов:готова;, найди Брауга Тусклый Дух – это очень мудрый шаман. Внимательно выслушай его и выполни все, что он скажет, $n.$B$BБрауга можно найти около туннеля, соединяющего Когтистые горы и Ясеневый лес. И будь $gосторожен:осторожна;, $n, ночные эльфы могут помешать тебе.','Найдите Брауга Тусклый Дух возле входа в Туннель Когтя в Когтистых горах.','Гоблины терзают землю, ночные эльфы унижают младшие расы, а дни и ночи тем временем становятся все холоднее и холоднее. Отрекшиеся и орки – не единственные, кого нужно винить за конфликты, возникшие на землях Калимдора и Лордерона. Многие разумные расы причинили миру немало боли. Дорн знает об этом, и он отправил вас ко мне, потому что вы тоже способны это понять.\n\nСейчас вы стоите перед Браугом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание знаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои испытания почти закончились, но проверку знаний проводить буду не я. Тебе придется посетить другие места и усвоить там новые уроки.$B$BЕсли ты $gготов:готова;, найди Брауга Тусклый Дух – это очень мудрый шаман. Внимательно выслушай его и выполни все, что он скажет, $n.$B$BБрауга можно найти около туннеля, соединяющего Когтистые горы и Ясеневый лес. И будь $gосторожен:осторожна;, $n, ночные эльфы могут помешать тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Брауга Тусклый Дух возле входа в Туннель Когтя в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гоблины терзают землю, ночные эльфы унижают младшие расы, а дни и ночи тем временем становятся все холоднее и холоднее. Отрекшиеся и орки – не единственные, кого нужно винить за конфликты, возникшие на землях Калимдора и Лордерона. Многие разумные расы причинили миру немало боли. Дорн знает об этом, и он отправил вас ко мне, потому что вы тоже способны это понять.\n\nСейчас вы стоите перед Браугом.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1153,'Образец новой руды','$C, раньше вы часто помогали мне в разных делах. Пока что вождь доволен моими успехами и просит меня продолжать с новой решимостью. По закону чести, я должен рассказать вождю обо всем, что вы сделали для нас, но вначале я хотел бы снова попросить вас о помощи.$B$BНедавно я встречался с путешественниками, которые пришли с юга, из места под названием Тысяча Игл. Там они убили кобольда, у которого при себе был образец необычной руды, но они отказались его продавать. А он мне очень нужен для исследования!','Отберите неочищенный образец руды у землекопа или геодезиста из племени Камнерылов и принесите его Таттернаку Стальному Горну в Лагерь Таурахо в Степях.','Потом я встретился с путешественниками снова – с теми самыми, что не продали мне образец руды. Я плюнул в них за то, что они не стали помогать вождю.\n\nПусть они умрут в бою как трусы, а не как благородные воины, вставшие на сторону Орды.','Вернитесь к Таттернаку Стальному Горну в лагерь Таурахо, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Образец новой руды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, раньше вы часто помогали мне в разных делах. Пока что вождь доволен моими успехами и просит меня продолжать с новой решимостью. По закону чести, я должен рассказать вождю обо всем, что вы сделали для нас, но вначале я хотел бы снова попросить вас о помощи.$B$BНедавно я встречался с путешественниками, которые пришли с юга, из места под названием Тысяча Игл. Там они убили кобольда, у которого при себе был образец необычной руды, но они отказались его продавать. А он мне очень нужен для исследования!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите неочищенный образец руды у землекопа или геодезиста из племени Камнерылов и принесите его Таттернаку Стальному Горну в Лагерь Таурахо в Степях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Потом я встретился с путешественниками снова – с теми самыми, что не продали мне образец руды. Я плюнул в них за то, что они не стали помогать вождю.\n\nПусть они умрут в бою как трусы, а не как благородные воины, вставшие на сторону Орды.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таттернаку Стальному Горну в лагерь Таурахо, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1154,'Испытание знаний','Ты $gпрошел:прошла; испытание Дорна и хочешь пройти следующее? Что ж, хорошо. Но все предыдущие испытания были детскими играми. Физическую силу испытать легко – то ли дело сила разума!$B$BЛадно, объясню попроще: найди книгу, которую я назову, изучи ее и ответь на мой вопрос по ее содержимому.$B$BТы спросишь, что за книга? Она называется "Наследие Аспектов". Ее можно найти в глубине обители Дор\'Данил, это в южном Ясеневом лесу. Книгу охраняют мертвые друиды и их убийцы.','Найдите книгу "Наследие Аспектов" и вернитесь к Браугу Тусклому Духу ко входу в Туннель Когтя.','Это та самая книга, о которой я говорил. Полагаю, тебе известен ответ на мой вопрос – если только ты не поленился изучить книгу.\n\nКак только будешь готов, обратись ко мне, и я задам тебе вопрос.','Принеси мне книгу, когда прочитаешь ее. До этого я не буду задавать тебе вопросов.','Вернитесь к Браугу Тусклому Духу ко входу в Туннель Когтя, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание знаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпрошел:прошла; испытание Дорна и хочешь пройти следующее? Что ж, хорошо. Но все предыдущие испытания были детскими играми. Физическую силу испытать легко – то ли дело сила разума!$B$BЛадно, объясню попроще: найди книгу, которую я назову, изучи ее и ответь на мой вопрос по ее содержимому.$B$BТы спросишь, что за книга? Она называется "Наследие Аспектов". Ее можно найти в глубине обители Дор\'Данил, это в южном Ясеневом лесу. Книгу охраняют мертвые друиды и их убийцы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите книгу "Наследие Аспектов" и вернитесь к Браугу Тусклому Духу ко входу в Туннель Когтя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это та самая книга, о которой я говорил. Полагаю, тебе известен ответ на мой вопрос – если только ты не поленился изучить книгу.\n\nКак только будешь готов, обратись ко мне, и я задам тебе вопрос.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принеси мне книгу, когда прочитаешь ее. До этого я не буду задавать тебе вопросов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Браугу Тусклому Духу ко входу в Туннель Когтя, что в Когтистых горах.',`completedtext_loc8`);
