INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1158,'<NYI> <TXT> поговорить с Рабином Сатурной','x','x') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> поговорить с Рабином Сатурной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','x',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','x',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1159,'Испытание знаний','Превосходно, $n. Ты $gпрошел:прошла; первую часть испытания знаний, но еще один вопрос остался без ответа. Правда, задавать его буду не я.$B$BПоговори с Парквелом Финталласом в Лордероне – до того как пасть жертвой Чумы, он был великим историком среди людей. Он до сих пор стремится к просвещению, но уже по-другому.$B$BОн даст тебе задание, и только потом задаст вопрос – но до сих пор ты $gсправлялся:справлялась; хорошо, и, я уверен, трудностей у тебя не возникнет.','Найдите Парквела Финталласа в Подгороде.','Тебя прислал Брауг? Невероятно.\n\nПарквел критически осматривает вас.\n\nСправился в Дор\'Даниле, прошел испытание веры и совладал с могущественным элементалем? Ха! Да ты, наверное, наслушался разговоров в таверне и теперь нагло врешь мне! Думаешь, что сможешь пройти мое испытание? Ну что ж, хорошо... |3-6($C).') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание знаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Превосходно, $n. Ты $gпрошел:прошла; первую часть испытания знаний, но еще один вопрос остался без ответа. Правда, задавать его буду не я.$B$BПоговори с Парквелом Финталласом в Лордероне – до того как пасть жертвой Чумы, он был великим историком среди людей. Он до сих пор стремится к просвещению, но уже по-другому.$B$BОн даст тебе задание, и только потом задаст вопрос – но до сих пор ты $gсправлялся:справлялась; хорошо, и, я уверен, трудностей у тебя не возникнет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Парквела Финталласа в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Брауг? Невероятно.\n\nПарквел критически осматривает вас.\n\nСправился в Дор\'Даниле, прошел испытание веры и совладал с могущественным элементалем? Ха! Да ты, наверное, наслушался разговоров в таверне и теперь нагло врешь мне! Думаешь, что сможешь пройти мое испытание? Ну что ж, хорошо... |3-6($C).',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1160,'Испытание знаний','Я скажу тебе, что искать, и даже задам вопрос, но не потому, что тебе хочется проявить себя. Знания гораздо важнее силы. Даже если кто-то силой превосходит тебя, твои знания о мире могут оказаться куда полезнее.$B$BОтправляйся в монастырь на севере Тирисфальских лесов. В их библиотеке есть книга под названием "Истоки угрозы нежити" – по ней ныне обезумевшие паладины учатся истреблять моих собратьев.$B$BПринесите ее мне.','Найдите книгу "Истоки угрозы нежити" и отнесите ее Парквелу Финталласу в Подгород.','Это та самая книга, которую я велел тебе найти.\n\n*Парквел нежно проводит рукой по обложке, разглядывая ее.*\n\nЗначит, ты хочешь, чтобы я задал тебе вопрос, чтобы ты мог доказать, что твой дух так же силен, как и тело? Если ты хорошо изучил книгу, то я задам тебе вопрос, и с испытаниями будет покончено.','Надеюсь, ты доставил Алому ордену достаточно неприятностей перед тем, как украсть книгу.\n\nМое отношение к ним отнюдь не беспочвенно. Возможно, когда-то его участники и почитали Свет, но теперь они стремятся лишь уничтожить всех, кто не принадлежит к их религии. Они считают, что вся нежить – Отрекшиеся и все остальные – должна быть уничтожена, а тех, кто путешествует в земли нежити, они считают либо безумцами, либо рабами сильной магии. Идиоты. Идиоты и глупцы, все до единого.','Вернитесь к Парквелу Финталласу в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание знаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я скажу тебе, что искать, и даже задам вопрос, но не потому, что тебе хочется проявить себя. Знания гораздо важнее силы. Даже если кто-то силой превосходит тебя, твои знания о мире могут оказаться куда полезнее.$B$BОтправляйся в монастырь на севере Тирисфальских лесов. В их библиотеке есть книга под названием "Истоки угрозы нежити" – по ней ныне обезумевшие паладины учатся истреблять моих собратьев.$B$BПринесите ее мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите книгу "Истоки угрозы нежити" и отнесите ее Парквелу Финталласу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это та самая книга, которую я велел тебе найти.\n\n*Парквел нежно проводит рукой по обложке, разглядывая ее.*\n\nЗначит, ты хочешь, чтобы я задал тебе вопрос, чтобы ты мог доказать, что твой дух так же силен, как и тело? Если ты хорошо изучил книгу, то я задам тебе вопрос, и с испытаниями будет покончено.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты доставил Алому ордену достаточно неприятностей перед тем, как украсть книгу.\n\nМое отношение к ним отнюдь не беспочвенно. Возможно, когда-то его участники и почитали Свет, но теперь они стремятся лишь уничтожить всех, кто не принадлежит к их религии. Они считают, что вся нежить – Отрекшиеся и все остальные – должна быть уничтожена, а тех, кто путешествует в земли нежити, они считают либо безумцами, либо рабами сильной магии. Идиоты. Идиоты и глупцы, все до единого.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Парквелу Финталласу в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1161,'<NYI> <TXT> сплетни Тень Янтарной Луны','x','x') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> сплетни Тень Янтарной Луны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','x',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','x',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1162,'<NYI> <TXT> поговорить с Хамуулом Руническим Тотемом','x','x') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> поговорить с Хамуулом Руническим Тотемом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','x',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','x',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1163,'<NYI> <TXT> поговорить с Тирандой Шелест Ветра','x','x') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> поговорить с Тирандой Шелест Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','x',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','x',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1164,'Грабь награбленное','Воровка! Свинья! Кената все еще жива, ее семья живет и процветает, а я страдаю. Вот уж действительно Отрекшаяся!$B$BВсю мою семью забрала чума. Все наше имение тоже разорили во время войны. И теперь она и ее мерзкие дети имели наглость похитить у меня последние ценные вещи.$B$BСами вещи мне уже не нужны. Теперь я жажду мести!$B$BУбей этих проходимцев! Ступай в усадьбу Дабири в Арати, на северо-востоке от Опорного пункта.','Принесите головы Кенаты, Фардела и Марселя Дабири Генви Кэллоу в Подгород.','Ты стоишь передо мной, словно посланник Мести, и я склоняюсь в знак признательности.\n\nЖирная корова мертва, и я, зная, что ее потомки не будут топтать землю Азерота, могу потратить силы на что-нибудь более разумное. Надеюсь, прикончив их, ты ограбил усадьбу?','Убей их и принеси мне головы!','Вернитесь к Генви Кэллоу на озеро Лордамер, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грабь награбленное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воровка! Свинья! Кената все еще жива, ее семья живет и процветает, а я страдаю. Вот уж действительно Отрекшаяся!$B$BВсю мою семью забрала чума. Все наше имение тоже разорили во время войны. И теперь она и ее мерзкие дети имели наглость похитить у меня последние ценные вещи.$B$BСами вещи мне уже не нужны. Теперь я жажду мести!$B$BУбей этих проходимцев! Ступай в усадьбу Дабири в Арати, на северо-востоке от Опорного пункта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите головы Кенаты, Фардела и Марселя Дабири Генви Кэллоу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты стоишь передо мной, словно посланник Мести, и я склоняюсь в знак признательности.\n\nЖирная корова мертва, и я, зная, что ее потомки не будут топтать землю Азерота, могу потратить силы на что-нибудь более разумное. Надеюсь, прикончив их, ты ограбил усадьбу?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Убей их и принеси мне головы!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Генви Кэллоу на озеро Лордамер, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (1165,'<NYI> Руда для гонок','Вернитесь к Пшиксу Медноштифу в Тысячу Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Руда для гонок',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пшиксу Медноштифу в Тысячу Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1166,'[DEPRECATED]Overlord Mok\'Morokk\'s Concern','Твоя кланяться властитель Мок\'Морокк!$b$bРексар назначить меня правителем клана Каменного Молота!$b$bМоя хороший вождь! Моя бережет свой клан!$b$bБольшие драконы прилетать и жечь наш старый дом. Моя – умный огр! Моя найти здесь новый дом для свой клан. $b$bБросать старый дом так быстро, что забыть моя вещи. $gМаленький:Маленькая:r; |3-6($r), ты идти и приносить моя вещи. Идти на юг и приносить мой вкусный грог, мой табак и мой сейф. Я благодарить твоя, когда твоя сделать это. Твоя искать в Обители Пламени и в руинах Деревни Каменного Молота. Они быть там, моя уверен.','Принесите Мок\'Морокку его грог, табак и сейф в Гиблотопь.','Хороший |3-6($R). Моя скучать по этим вещам. Моя теперь дружить с твоя.','Моя хотеть свой грог. И свой табак. Где мой сейф? Твоя идти и приносить все властителю Мок\'Морокку. Моя слишком занят, моя управлять ограми.','Вернитесь к властителю Мок\'морокку в деревню Гиблотопь, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Overlord Mok\'Morokk\'s Concern',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя кланяться властитель Мок\'Морокк!$b$bРексар назначить меня правителем клана Каменного Молота!$b$bМоя хороший вождь! Моя бережет свой клан!$b$bБольшие драконы прилетать и жечь наш старый дом. Моя – умный огр! Моя найти здесь новый дом для свой клан. $b$bБросать старый дом так быстро, что забыть моя вещи. $gМаленький:Маленькая:r; |3-6($r), ты идти и приносить моя вещи. Идти на юг и приносить мой вкусный грог, мой табак и мой сейф. Я благодарить твоя, когда твоя сделать это. Твоя искать в Обители Пламени и в руинах Деревни Каменного Молота. Они быть там, моя уверен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мок\'Морокку его грог, табак и сейф в Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хороший |3-6($R). Моя скучать по этим вещам. Моя теперь дружить с твоя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Моя хотеть свой грог. И свой табак. Где мой сейф? Твоя идти и приносить все властителю Мок\'Морокку. Моя слишком занят, моя управлять ограми.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Мок\'морокку в деревню Гиблотопь, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1167,'Башня Алталакса','Прежде чем встретиться с Атрикусом, разумно было бы тебе посоветоваться с Балтулом. Не сомневаюсь, что он неусыпно следил за башней и может знать о недавних событиях.','Поговорите с Балтулом Ударом Тени возле башни Алталакса.','А, приятно снова свидеться, $n! Тут такие странные вещи творились, так что хорошо, что ты снова тут появился!$B$BОчень странные вещи, $n. Все казалось как обычно – ну, насколько тут вообще все может быть обычно – и вдруг на верхнем этаже башни как полыхнет! Потом начались вопли. Вопли раскалывали воздух, а в землю порой били молнии. Что все это может значить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башня Алталакса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем встретиться с Атрикусом, разумно было бы тебе посоветоваться с Балтулом. Не сомневаюсь, что он неусыпно следил за башней и может знать о недавних событиях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Балтулом Ударом Тени возле башни Алталакса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, приятно снова свидеться, $n! Тут такие странные вещи творились, так что хорошо, что ты снова тут появился!$B$BОчень странные вещи, $n. Все казалось как обычно – ну, насколько тут вообще все может быть обычно – и вдруг на верхнем этаже башни как полыхнет! Потом начались вопли. Вопли раскалывали воздух, а в землю порой били молнии. Что все это может значить?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1168,'Армия черных драконов','Мок\'Морокк велит всем ограм оставаться и охранять это место. Я думаю, ограм нужно убить армию черного дракона и вернуть старый дом.$B$BТы помогаешь ограм вернуться домой. Помогите ограм отомстить.','Вернитесь к Тхаргу в деревню Гиблотопь, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Армия черных драконов',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мок\'Морокк велит всем ограм оставаться и охранять это место. Я думаю, ограм нужно убить армию черного дракона и вернуть старый дом.$B$BТы помогаешь ограм вернуться домой. Помогите ограм отомстить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тхаргу в деревню Гиблотопь, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1169,'[DEPRECATED]Identifying the Brood','Пока этот трусливый глупец Мок\'Морокк упивается властью, а Тхарг борется с тоской и жаждой мести и оспаривает его власть над кланом, – я, кажется, единственный, кто хочет установить источник бед, обрушившихся на нас.$B$BПочему ты так озадаченно смотришь на меня, $n? $gДумал:Думала;, я буду говорить как неотесанный чурбан только потому, что я – огр?$b$bНо к делу. Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла.','Принесите Драз\'Зилбу в Деревню Гиблотопь 7 огненных языков и 7 пылающих сердец.','Рискованное было дельце, добывать все эти сердца и языки, а? Теперь я проникну в глубины тайн, чтобы выяснить, откуда на наш прежний дом свалилась такая напасть.','Теперь я смогу узнать, что за тварь напустила на нас свои отродья. Возможно, зная больше о захватчике, мы сможем понять, как уничтожить его раз и навсегда и поднять деревню Каменного Молота из руин. Конечно, заставить Мок\'Морокка оторвать свой толстый зад от земли, – уже само по себе героический поступок...','Вернитесь к Драз\'зилбу в деревню Гиблотопь, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Identifying the Brood',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока этот трусливый глупец Мок\'Морокк упивается властью, а Тхарг борется с тоской и жаждой мести и оспаривает его власть над кланом, – я, кажется, единственный, кто хочет установить источник бед, обрушившихся на нас.$B$BПочему ты так озадаченно смотришь на меня, $n? $gДумал:Думала;, я буду говорить как неотесанный чурбан только потому, что я – огр?$b$bНо к делу. Принеси мне сердца и языки дракончиков, только что вылупившихся из яиц, и я найду корни этого зла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Драз\'Зилбу в Деревню Гиблотопь 7 огненных языков и 7 пылающих сердец.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рискованное было дельце, добывать все эти сердца и языки, а? Теперь я проникну в глубины тайн, чтобы выяснить, откуда на наш прежний дом свалилась такая напасть.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Теперь я смогу узнать, что за тварь напустила на нас свои отродья. Возможно, зная больше о захватчике, мы сможем понять, как уничтожить его раз и навсегда и поднять деревню Каменного Молота из руин. Конечно, заставить Мок\'Морокка оторвать свой толстый зад от земли, – уже само по себе героический поступок...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драз\'зилбу в деревню Гиблотопь, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1170,'[DEPRECATED]The Brood of Onyxia','Деревня Каменный Молот была захвачена выводком Ониксии. Но почему дочь великого дракона Смертокрыла вторглась в наши земли? Вот что тревожнее всего!$b$bНеужели только для того, чтобы уничтожить небольшое поселение огров?$b$bПредупреди Мок\'Морокка. Нельзя сидеть сложа руки!','Поговорите с властителем Мок\'Морокком в Деревне Гиблотопь.','Почему ты говорить с моя про драконы? Моя не любить драконы. Моя не хотеть здесь никакие драконы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Brood of Onyxia',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Деревня Каменный Молот была захвачена выводком Ониксии. Но почему дочь великого дракона Смертокрыла вторглась в наши земли? Вот что тревожнее всего!$b$bНеужели только для того, чтобы уничтожить небольшое поселение огров?$b$bПредупреди Мок\'Морокка. Нельзя сидеть сложа руки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с властителем Мок\'Морокком в Деревне Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Почему ты говорить с моя про драконы? Моя не любить драконы. Моя не хотеть здесь никакие драконы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1171,'[DEPRECATED]The Brood of Onyxia','Твоя уходить. Твоя идти и сказать Драз\'Зилбу, мы оставаться здесь. Здесь нет никакой черный дракон.','Поговорите с Драз\'Зилбом в Деревне Гиблотопь.','Жалкий трус!$B$BМок\'Морокк выказывал силу, пока нашим вождем был Рексар. Но после его ухода Мок\'Морокк начал сам стремиться к власти. Он предпочитал требовать, вместо того чтобы руководить. Он не заботится о своих подданых, а наоборот хочет, чтобы мы заботились о нем.$B$BС этим надо что-то делать!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Brood of Onyxia',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя уходить. Твоя идти и сказать Драз\'Зилбу, мы оставаться здесь. Здесь нет никакой черный дракон.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Драз\'Зилбом в Деревне Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жалкий трус!$B$BМок\'Морокк выказывал силу, пока нашим вождем был Рексар. Но после его ухода Мок\'Морокк начал сам стремиться к власти. Он предпочитал требовать, вместо того чтобы руководить. Он не заботится о своих подданых, а наоборот хочет, чтобы мы заботились о нем.$B$BС этим надо что-то делать!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1172,'[DEPRECATED]The Brood of Onyxia','Потомки Ониксии распространились по всей Земле Драконов. Нельзя допустить, чтобы и остальные ее отродья вылупились на свет!$b$bПоспеши в Драконьи топи на юге Пылевых топей. Наверняка она устроила там свое логово. Найди яйца злой драконихи и уничтожь их!$b$bМы никогда не вернем себе деревню Каменного Молота, если вокруг будут продолжать плодиться драконы.$b$bА что касается Мок\'Морокка... касательно этого червя у меня есть особые планы.','Драз\'Зилб из Деревни Гиблотопь хочет, чтобы вы уничтожили 5 яиц Ониксии.','Прекрасно! Теперь Ониксия не скоро отложит очередную кладку.$B$BБлагодарю тебя, $N, от имени моего народа.$B$BЯ уже о многом просил тебя, но, может, ты окажешь последнюю услугу клану Каменного Молота.$B$BМок\'Морокк не достоин править нами. Тхарг стал бы отличным вождем, но он стар и изранен. Изгони силой из этих мест Мок\'Морокка. Только тогда мы сможем избрать нового вождя, который отведет нас на родину, в южные земли.','Тебе надо поспешать в Землю Драконов, $N. Пока Драконья топь завалена яйцами Ониксии, они всегда будут превосходить нас числом. Поторопись же.$B$BУничтожь ее яйца! Не дай драконьей заразе расползаться по нашим землям!','Вернитесь к Драз\'зилбу в деревню Гиблотопь, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Brood of Onyxia',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Потомки Ониксии распространились по всей Земле Драконов. Нельзя допустить, чтобы и остальные ее отродья вылупились на свет!$b$bПоспеши в Драконьи топи на юге Пылевых топей. Наверняка она устроила там свое логово. Найди яйца злой драконихи и уничтожь их!$b$bМы никогда не вернем себе деревню Каменного Молота, если вокруг будут продолжать плодиться драконы.$b$bА что касается Мок\'Морокка... касательно этого червя у меня есть особые планы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Драз\'Зилб из Деревни Гиблотопь хочет, чтобы вы уничтожили 5 яиц Ониксии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Теперь Ониксия не скоро отложит очередную кладку.$B$BБлагодарю тебя, $N, от имени моего народа.$B$BЯ уже о многом просил тебя, но, может, ты окажешь последнюю услугу клану Каменного Молота.$B$BМок\'Морокк не достоин править нами. Тхарг стал бы отличным вождем, но он стар и изранен. Изгони силой из этих мест Мок\'Морокка. Только тогда мы сможем избрать нового вождя, который отведет нас на родину, в южные земли.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе надо поспешать в Землю Драконов, $N. Пока Драконья топь завалена яйцами Ониксии, они всегда будут превосходить нас числом. Поторопись же.$B$BУничтожь ее яйца! Не дай драконьей заразе расползаться по нашим землям!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драз\'зилбу в деревню Гиблотопь, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1173,'[DEPRECATED]Challenge Overlord Mok\'Morokk','Ты осмеливаешься вызвать на поединок властителя Мок\'Морокка?$b$bХа!$b$bМеня хочет сокрушить $Gжалкий:жалкая:r; |3-6($r)!$B$BПриготовишься к трепке – скажи мне.','Победите Мок\'Морокка и сообщите об этом Драз\'Зилбу в Деревне Гиблотопь.','Эта трусливая туша, Мок\'Морокк, сбежал как испуганный младенец при виде розги. Ты $Gоказал:оказала; нам огромную услугу, $N.$B$BТеперь мой народ может выбрать себе нового лидера, того, кто поможет восстановить наши жилища и защитить их.','Я думал, ты собираешься выгнать Мок\'Морокка из деревни. Вместо этого вы пришли ко мне поболтать?','Изгнать владыку Мок\'Морокка из Деревни Гиблотопь','Вернитесь к Драз\'зилбу в деревню Гиблотопь, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Challenge Overlord Mok\'Morokk',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты осмеливаешься вызвать на поединок властителя Мок\'Морокка?$b$bХа!$b$bМеня хочет сокрушить $Gжалкий:жалкая:r; |3-6($r)!$B$BПриготовишься к трепке – скажи мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Мок\'Морокка и сообщите об этом Драз\'Зилбу в Деревне Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта трусливая туша, Мок\'Морокк, сбежал как испуганный младенец при виде розги. Ты $Gоказал:оказала; нам огромную услугу, $N.$B$BТеперь мой народ может выбрать себе нового лидера, того, кто поможет восстановить наши жилища и защитить их.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я думал, ты собираешься выгнать Мок\'Морокка из деревни. Вместо этого вы пришли ко мне поболтать?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Изгнать владыку Мок\'Морокка из Деревни Гиблотопь',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драз\'зилбу в деревню Гиблотопь, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (1174,'Гномы победили!','Вернитесь к Краззлу Шустрецу в Тысячу Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гномы победили!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Краззлу Шустрецу в Тысячу Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1175,'Помехи на трассе','После того как гоблинский болид "Красный Гром" столкнулся с василиском, Лихоезд нанял меня присматривать за трассой. Не знаю, что жрут местные животные, но они вырастают просто огромными, и нужно постоянно отпугивать их, чтобы они не забредали на трек во время гонки.$B$BЗнаете, что? Если желаете немного заработать, ступайте и избавьте нас от нескольких василисков.','Убейте 10 просоленных василисков, 10 просоленных хрусталисков и 6 просоленных взорней, после чего вернитесь к начальнику трассы Зерину на Мерцающую равнину.','Надеюсь, вы не убивали василисков прямо на трассе? Здесь тела разлагаются очень долго, а лопатой их убирать замучаешься.','Ну как, ты принес нужные кости? Я как раз хочу руль переделать, да неохота начинать, пока всех нужных запчастей нет.','Вернитесь к начальнику трассы Зерину в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помехи на трассе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как гоблинский болид "Красный Гром" столкнулся с василиском, Лихоезд нанял меня присматривать за трассой. Не знаю, что жрут местные животные, но они вырастают просто огромными, и нужно постоянно отпугивать их, чтобы они не забредали на трек во время гонки.$B$BЗнаете, что? Если желаете немного заработать, ступайте и избавьте нас от нескольких василисков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 просоленных василисков, 10 просоленных хрусталисков и 6 просоленных взорней, после чего вернитесь к начальнику трассы Зерину на Мерцающую равнину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, вы не убивали василисков прямо на трассе? Здесь тела разлагаются очень долго, а лопатой их убирать замучаешься.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, ты принес нужные кости? Я как раз хочу руль переделать, да неохота начинать, пока всех нужных запчастей нет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к начальнику трассы Зерину в поселок Виражи на Миражах, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1176,'Уменьшение веса','На гонках имеет значение абсолютно все! Будь то малейшее изменение мощности, небольшое ослабление колец натяжения или уменьшение веса болида – любую мелочь надо принимать в расчет.$B$BМы используем в своих болидах кости стервятников – они очень крепкие и легкие. К тому же их очень легко найти. Уж чего-чего – а стервятников на Мерцающих равнинах хватает.$B$BПринеси мне немного костей, и я хорошо заплачу тебе.','Добудьте 10 полых костей стервятника для Поззика с Мерцающей равнины.','Ну как, ты принес нужные кости? Я как раз хочу руль переделать, да неохота начинать, пока всех нужных запчастей нет.','Вернитесь к Поззику в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшение веса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На гонках имеет значение абсолютно все! Будь то малейшее изменение мощности, небольшое ослабление колец натяжения или уменьшение веса болида – любую мелочь надо принимать в расчет.$B$BМы используем в своих болидах кости стервятников – они очень крепкие и легкие. К тому же их очень легко найти. Уж чего-чего – а стервятников на Мерцающих равнинах хватает.$B$BПринеси мне немного костей, и я хорошо заплачу тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 полых костей стервятника для Поззика с Мерцающей равнины.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, ты принес нужные кости? Я как раз хочу руль переделать, да неохота начинать, пока всех нужных запчастей нет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Поззику в поселок Виражи на Миражах, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1177,'Моя голодный!','Моя – большой огр. $B$BМоя голодный.$b$bТвоя идти ловить рыба. Твоя принести Дробу еда.$b$bТвоя кормить Дроб, или Дроб есть твоя.','Принесите дробильщику Грязноногу, живущему на севере Пылевых топей, 8 голов мурлоков из клана Болотного Плавника.','Моя любить рыбья голова!$B$BМоя пока твоя не есть.','Дать мне еды или я есть твоя.','Вернитесь к дробильщику Грязноногу в Пылевые топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Моя голодный!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя – большой огр. $B$BМоя голодный.$b$bТвоя идти ловить рыба. Твоя принести Дробу еда.$b$bТвоя кормить Дроб, или Дроб есть твоя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите дробильщику Грязноногу, живущему на севере Пылевых топей, 8 голов мурлоков из клана Болотного Плавника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моя любить рыбья голова!$B$BМоя пока твоя не есть.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дать мне еды или я есть твоя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дробильщику Грязноногу в Пылевые топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1178,'Гоблинская поддержка','Наша гоночная команда – это гордость всей расы гоблинов! Вы удивитесь, узнав, что за личности в той или иной мере покровительствуют нашей команде.$B$BЗнаете Газлоу? Он собирает для нас детали по всему миру, а однажды даже разработал для нас новые костюмы!$B$BНесколько недель назад он пообещал прислать новый топливный регулятор, но посылка пока не пришла. Странно, обычно Газлоу держит свое слово... Может, вы не прочь съездить в Кабестан и спросить у него? Я бы не настаивал, но эти гномы нас догоняют!','Поговорите с Газлоу в Кабестане, что в Степях.','Вас прислал Поззик? Когда-то ведь он был одним из самых уважаемых механиков в Нижней шахте, но потом уволился и занялся гонками.\n\nПервое, что он сделал, придя в команду, – разработал две новых модели двигателей. Дела Союза ремонтников могут пострадать без Поззика, но ему уже нет до этого дела... Гонки для него все!','Ну как, ты принес нужные кости? Я как раз хочу руль переделать, да неохота начинать, пока всех нужных запчастей нет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинская поддержка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша гоночная команда – это гордость всей расы гоблинов! Вы удивитесь, узнав, что за личности в той или иной мере покровительствуют нашей команде.$B$BЗнаете Газлоу? Он собирает для нас детали по всему миру, а однажды даже разработал для нас новые костюмы!$B$BНесколько недель назад он пообещал прислать новый топливный регулятор, но посылка пока не пришла. Странно, обычно Газлоу держит свое слово... Может, вы не прочь съездить в Кабестан и спросить у него? Я бы не настаивал, но эти гномы нас догоняют!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Газлоу в Кабестане, что в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вас прислал Поззик? Когда-то ведь он был одним из самых уважаемых механиков в Нижней шахте, но потом уволился и занялся гонками.\n\nПервое, что он сделал, придя в команду, – разработал две новых модели двигателей. Дела Союза ремонтников могут пострадать без Поззика, но ему уже нет до этого дела... Гонки для него все!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, ты принес нужные кости? Я как раз хочу руль переделать, да неохота начинать, пока всех нужных запчастей нет.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1179,'Братья Медноштиф','Вы когда-нибудь слышали о Мерцающей равнине? Это огромное соляное плато в Калимдоре, южнее каньона Тысяча Игл. Это отличное место для гонок, потому что поверхность там совершенно... ну... равнинная!$B$BТам живет парочка гномов – мои друзья, они строят новый болид, и говорят, он жуть какой быстрый! Настолько быстрый, что их пилоты то и дело разбиваются и калечатся...$B$BОни заказали у меня несколько защитных шлемов, но у меня дела, и я не могу их отвезти.$B$BМожет быть, вы мне поможете?','Принесите ящик с защитными шлемами Виззлу Медноштифу на Мерцающую равнину, что в Тысяче Игл.','Ага! Длиннобородый прислал с вами наши шлемы! Ур-р-а-а-а!!!$B$BОсталось уговорить пилота сесть в наш болид...','Смотри куда прешь! Эй, эй, эй! Тут все хрупкое и важное, не вздумай ничего портить, а то мы не выиграем гонку!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья Медноштиф',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы когда-нибудь слышали о Мерцающей равнине? Это огромное соляное плато в Калимдоре, южнее каньона Тысяча Игл. Это отличное место для гонок, потому что поверхность там совершенно... ну... равнинная!$B$BТам живет парочка гномов – мои друзья, они строят новый болид, и говорят, он жуть какой быстрый! Настолько быстрый, что их пилоты то и дело разбиваются и калечатся...$B$BОни заказали у меня несколько защитных шлемов, но у меня дела, и я не могу их отвезти.$B$BМожет быть, вы мне поможете?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ящик с защитными шлемами Виззлу Медноштифу на Мерцающую равнину, что в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага! Длиннобородый прислал с вами наши шлемы! Ур-р-а-а-а!!!$B$BОсталось уговорить пилота сесть в наш болид...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Смотри куда прешь! Эй, эй, эй! Тут все хрупкое и важное, не вздумай ничего портить, а то мы не выиграем гонку!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1180,'Гоблинская поддержка','Вернемся к делу. Я обещал Поззику привезти новый топливный регулятор, но так и не получил его. Ревилгаз из Пиратской Бухты сказал, что выслал его, но, похоже, он куда-то улетучился.$b$bКоли так, ничего не попишешь, но по меньшей мере мы можем выяснить, отправляли его или нет.$B$BПоговори с управляющим пристанью Подгребаем по ту сторону моря, пусть заглянет в свои журналы.','Поговорите с управляющим пристанью Подгребаем в Пиратской Бухте.','Поставки в Кабестан? Дай-ка я загляну в записи…\n\nНет, последний груз, отправленный в Кабестан, если не считать оборудования и припасов, – это сапоги от Дриззлика. Никаких запчастей для гонок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинская поддержка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вернемся к делу. Я обещал Поззику привезти новый топливный регулятор, но так и не получил его. Ревилгаз из Пиратской Бухты сказал, что выслал его, но, похоже, он куда-то улетучился.$b$bКоли так, ничего не попишешь, но по меньшей мере мы можем выяснить, отправляли его или нет.$B$BПоговори с управляющим пристанью Подгребаем по ту сторону моря, пусть заглянет в свои журналы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с управляющим пристанью Подгребаем в Пиратской Бухте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поставки в Кабестан? Дай-ка я загляну в записи…\n\nНет, последний груз, отправленный в Кабестан, если не считать оборудования и припасов, – это сапоги от Дриззлика. Никаких запчастей для гонок.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (1181,'Гоблинская поддержка','Боюсь, тут я помочь уже не в силах, $n. Если ты хочешь узнать подробности, поговори с самим бароном. Никто не знает дела Ревилгаза лучше самого Ревилгаза.$B$BОн сейчас на верхнем этаже таверны на другой стороне залива.','Поговорите с бароном Ревилгазом в Пиратской Бухте.','А, разумеется, я понимаю, о чем ты. Нет, помочь не могу. Мои наемники должны были добыть чертежи топливного регулятора, но вернулись с пустыми руками.','Поговорите с бароном Ревилгазом в Пиратской Бухте, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинская поддержка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, тут я помочь уже не в силах, $n. Если ты хочешь узнать подробности, поговори с самим бароном. Никто не знает дела Ревилгаза лучше самого Ревилгаза.$B$BОн сейчас на верхнем этаже таверны на другой стороне залива.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с бароном Ревилгазом в Пиратской Бухте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, разумеется, я понимаю, о чем ты. Нет, помочь не могу. Мои наемники должны были добыть чертежи топливного регулятора, но вернулись с пустыми руками.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с бароном Ревилгазом в Пиратской Бухте, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1182,'Гоблинская поддержка','Видишь ли, крошшеры Торговой Компании возле озера Назферити (в Северной Тернистой долине) оборудовали новой моделью топливного регулятора. Я подумал, что Поззик мог бы воспользоваться им, узнай мы, как он устроен. К сожалению, Коззл, тамошний штейгер, оказался несколько умнее, чем я полагал.$B$BМожет быть, тебе больше повезет, и удастся получить чертежи. Я знаю, что он хранит их в доме, но скорее всего под замком.','Принесите чертежи топливного регулятора барону Ревилгазу из Пиратской Бухты.','А теперь, дай-ка я срисую чертежи для личного пользования, а эти отвези Поззику. Не хотелось бы, чтобы он подумал, будто один из спонсоров оставил его без поддержки.','Мне не хочется это признавать, но гномская команда очень сильная. Нашим ребятам надо дать пинка, чтобы шевелились.','Вернитесь к барону Ревилгазу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинская поддержка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь ли, крошшеры Торговой Компании возле озера Назферити (в Северной Тернистой долине) оборудовали новой моделью топливного регулятора. Я подумал, что Поззик мог бы воспользоваться им, узнай мы, как он устроен. К сожалению, Коззл, тамошний штейгер, оказался несколько умнее, чем я полагал.$B$BМожет быть, тебе больше повезет, и удастся получить чертежи. Я знаю, что он хранит их в доме, но скорее всего под замком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите чертежи топливного регулятора барону Ревилгазу из Пиратской Бухты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А теперь, дай-ка я срисую чертежи для личного пользования, а эти отвези Поззику. Не хотелось бы, чтобы он подумал, будто один из спонсоров оставил его без поддержки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне не хочется это признавать, но гномская команда очень сильная. Нашим ребятам надо дать пинка, чтобы шевелились.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Ревилгазу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1183,'Гоблинская поддержка','Все должно быть готово. Передай Поззику мои наилучшие пожелания и скажи, что если ему что понадобится, стоит только попросить. Буду ждать вестей о его новых рекордах!','Отнесите чертежи топливного регулятора Поззику на Мерцающую равнину.','Вернитесь к Поззику на Мерцающую равнину, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинская поддержка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все должно быть готово. Передай Поззику мои наилучшие пожелания и скажи, что если ему что понадобится, стоит только попросить. Буду ждать вестей о его новых рекордах!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите чертежи топливного регулятора Поззику на Мерцающую равнину.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Поззику на Мерцающую равнину, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1184,'Части роя','Вернитесь к Белгрому в Оргриммар и скажите, что Моктар в Тысяче Игл сделает все, что от него требуется. А еще скажите, что я постоянно учусь и набираюсь знаний. Он будет рад это услышать.','Вернитесь к Белгрому Каменной Булаве в Оргриммар.','Я очень ценю ваши усилия, |3-6($C). Вождю будет приятно услышать о том, как вы стараетесь для нас.\n\nО, разумеется, я назову ему ваше имя! Он часто говорит со мной и высоко ценит мое мнение.\n\nА теперь ступайте, у меня еще много дел. И если вдруг вы встретитесь с Корраном, и он расскажет вам что-нибудь еще об этих существах – сразу возвращайтесь ко мне. К этой угрозе нельзя относиться легкомысленно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Части роя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вернитесь к Белгрому в Оргриммар и скажите, что Моктар в Тысяче Игл сделает все, что от него требуется. А еще скажите, что я постоянно учусь и набираюсь знаний. Он будет рад это услышать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Белгрому Каменной Булаве в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я очень ценю ваши усилия, |3-6($C). Вождю будет приятно услышать о том, как вы стараетесь для нас.\n\nО, разумеется, я назову ему ваше имя! Он часто говорит со мной и высоко ценит мое мнение.\n\nА теперь ступайте, у меня еще много дел. И если вдруг вы встретитесь с Корраном, и он расскажет вам что-нибудь еще об этих существах – сразу возвращайтесь ко мне. К этой угрозе нельзя относиться легкомысленно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1185,'А под хитином было...','О, опять ты! В смысле, это ты – а ты, то есть, $N! Да, это ты!$B$BСлушай-ка!$B$BТа штука, что ты $Gнашел:нашла; в Силитусе, оказалась книгой. Дневник, написанный на очень древнем диалекте того, что теперь называется дарнассийским. Это займет некоторое время, но я намерен как следует в нем разобраться. Мне показалось, что тебе следует знать, что твоя находка оказалась просто бесценной для Круга.$B$BМать-медведица в восхищении, и все такое!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','А под хитином было...',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, опять ты! В смысле, это ты – а ты, то есть, $N! Да, это ты!$B$BСлушай-ка!$B$BТа штука, что ты $Gнашел:нашла; в Силитусе, оказалась книгой. Дневник, написанный на очень древнем диалекте того, что теперь называется дарнассийским. Это займет некоторое время, но я намерен как следует в нем разобраться. Мне показалось, что тебе следует знать, что твоя находка оказалась просто бесценной для Круга.$B$BМать-медведица в восхищении, и все такое!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1186,'Восемнадцатый пилот','Мне сейчас нужно приспособить этот новый регулятор топлива на один из наших болидов, но если вы хотите еще немного помочь нашей команде, поговорите с Раззериком. Это наш пилот, – гм, наш восемнадцатый пилот, если точнее, – и он тоже любит вносить в болид всяческие усовершенствования.$B$BОн, правда, малость двинутый, так что не удивляйтесь, если что.','Поговорите с Раззериком на Мерцающей равнине, что в Тысяче Игл.','Это ведь вы помогали Поззику, правда? Когда-то я тоже бегал по пит-лейну и выполнял мелкие поручения механиков.\n\nА теперь – взгляните на меня! Я – лучший пилот команды гоблинов!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восемнадцатый пилот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне сейчас нужно приспособить этот новый регулятор топлива на один из наших болидов, но если вы хотите еще немного помочь нашей команде, поговорите с Раззериком. Это наш пилот, – гм, наш восемнадцатый пилот, если точнее, – и он тоже любит вносить в болид всяческие усовершенствования.$B$BОн, правда, малость двинутый, так что не удивляйтесь, если что.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Раззериком на Мерцающей равнине, что в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это ведь вы помогали Поззику, правда? Когда-то я тоже бегал по пит-лейну и выполнял мелкие поручения механиков.\n\nА теперь – взгляните на меня! Я – лучший пилот команды гоблинов!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1187,'Доработка Раззерика','Поззик – отличный механик, это я знаю, но он боится просто прибавить мощности и вырваться вперед! А вот я не боюсь.$B$BПосле того как он закончит работать с болидом, я внесу кое-какие изменения от себя: немного ослаблю ограничители, сниму кое-какие детальки с корпуса и добавлю побольше топлива!$B$BЯ заказал сефориевый ускоритель у Шрива. Он работает в Гизмориуме, в Прибамбасске, но дирижабль, на котором летел мой ускоритель, разбился в Пылевых топях! А мне он нужен, как воздух!','Найдите сефориевый ускоритель для Раззерика на Мерцающей равнине.','Ты только глянь на эту красотищу! Пятнадцать фунтов чистой сефориевой силы! Как только я прицеплю это к своему болиду, он понесется так, что я обгоню гномов на два круга!','И как мне показаться на треке, если у меня нет никакого ускорителя? Это ж ерунда какая-то!','Вернитесь к Раззерику в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доработка Раззерика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поззик – отличный механик, это я знаю, но он боится просто прибавить мощности и вырваться вперед! А вот я не боюсь.$B$BПосле того как он закончит работать с болидом, я внесу кое-какие изменения от себя: немного ослаблю ограничители, сниму кое-какие детальки с корпуса и добавлю побольше топлива!$B$BЯ заказал сефориевый ускоритель у Шрива. Он работает в Гизмориуме, в Прибамбасске, но дирижабль, на котором летел мой ускоритель, разбился в Пылевых топях! А мне он нужен, как воздух!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите сефориевый ускоритель для Раззерика на Мерцающей равнине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты только глянь на эту красотищу! Пятнадцать фунтов чистой сефориевой силы! Как только я прицеплю это к своему болиду, он понесется так, что я обгоню гномов на два круга!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И как мне показаться на треке, если у меня нет никакого ускорителя? Это ж ерунда какая-то!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Раззерику в поселок Виражи на Миражах, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1188,'Безопасность превыше всего','Постойте-ка, что это? Шрив оставил включенным режим безопасности. Но это же ограничит мощность, которую я смогу выжать из этого ускорителя! Говорил же я ему, чтобы отключил! Плохо, плохо.$B$BВам придется отнести это в Гизмориум Прибамбасска и заставить Шрива все отключить!','Отнесите сефориевый ускоритель Шриву в Прибамбасск, что в Танарисе.','Только Раззерик мог по одному взгляду определить, что я поставил сюда предохранитель. Этот ускоритель почти полностью состоит из взрывчатого сефория. Я модифицировал его так, что его мощность будет увеличиваться по мере использования, но Раззерик ведь не успокоится, пока не взорвется вместе со своим драндулетом!','Знаете, в Гизмориуме есть все для починки любых механизмов! Чем могу помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безопасность превыше всего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Постойте-ка, что это? Шрив оставил включенным режим безопасности. Но это же ограничит мощность, которую я смогу выжать из этого ускорителя! Говорил же я ему, чтобы отключил! Плохо, плохо.$B$BВам придется отнести это в Гизмориум Прибамбасска и заставить Шрива все отключить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сефориевый ускоритель Шриву в Прибамбасск, что в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Только Раззерик мог по одному взгляду определить, что я поставил сюда предохранитель. Этот ускоритель почти полностью состоит из взрывчатого сефория. Я модифицировал его так, что его мощность будет увеличиваться по мере использования, но Раззерик ведь не успокоится, пока не взорвется вместе со своим драндулетом!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаете, в Гизмориуме есть все для починки любых механизмов! Чем могу помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1189,'Безопасность превыше всего','Вот, я сделал то, что просил Раззерик. Но скажите ему, чтобы он действовал как можно осторожнее: если он допустит хотя бы малейшую ошибку, болид не покатится вперед, а превратится в кучку пепла на треке.$B$BА нам бы совсем не хотелось искать потом девятнадцатого по счету пилота!','Верните модифицированный сефориевый ускоритель Раззерику на Мерцающую равнину, что в Тысяче Игл.','Так-то лучше! Вот бы увидеть рожи гномов, когда я стартую на этой малышке!\n\nЖалко, что я буду так занят установлением нового рекорда трассы!','Ты представляешь, Поззик подсунул мне в болид ведро с песком! Как я могу выжать максимальную скорость, если у меня под сиденьем целое ведро песка?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безопасность превыше всего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, я сделал то, что просил Раззерик. Но скажите ему, чтобы он действовал как можно осторожнее: если он допустит хотя бы малейшую ошибку, болид не покатится вперед, а превратится в кучку пепла на треке.$B$BА нам бы совсем не хотелось искать потом девятнадцатого по счету пилота!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните модифицированный сефориевый ускоритель Раззерику на Мерцающую равнину, что в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так-то лучше! Вот бы увидеть рожи гномов, когда я стартую на этой малышке!\n\nЖалко, что я буду так занят установлением нового рекорда трассы!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты представляешь, Поззик подсунул мне в болид ведро с песком! Как я могу выжать максимальную скорость, если у меня под сиденьем целое ведро песка?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1190,'Только вперед','Братья Медноштиф изобрели новый материал для изготовления машин – это единственное разумное объяснение. Их машины ездят быстрее прежнего, но их внешний вид и все остальные параметры ничуть не изменились.$B$BМы точно знаем, что Риззл Медноштиф никогда не расстается с чертежами своего изобретения.$B$BЯ скажу Замеку, чтобы устроил диверсию, – тогда ты сможешь выкрасть планы.','Дождитесь, пока Замек устроит диверсию, украдите чертежи Риззла и отнестие их Поззику на Мерцающую равнину, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только вперед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Братья Медноштиф изобрели новый материал для изготовления машин – это единственное разумное объяснение. Их машины ездят быстрее прежнего, но их внешний вид и все остальные параметры ничуть не изменились.$B$BМы точно знаем, что Риззл Медноштиф никогда не расстается с чертежами своего изобретения.$B$BЯ скажу Замеку, чтобы устроил диверсию, – тогда ты сможешь выкрасть планы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока Замек устроит диверсию, украдите чертежи Риззла и отнестие их Поззику на Мерцающую равнину, что в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1191,'Помеха Замека') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помеха Замека',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (1192,'Индарилиевая руда','Вернитесь к Поззику в Тысячу Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Индарилиевая руда',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Поззику в Тысячу Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1193,'Сломанная западня','Ториевое устройство беспрепятственно встает на место, создавая канал, в который нужно влить масло льда. Как только последние капли масла падают в канал, западня готова к работе.$B$BИ горе неосторожному огру, который подойдет слишком близко!','Перед вами большая сломанная ловушка. Судя по всему, огры пытались починить ловушку, но безуспешно. Рядом с ловушкой лежит поспешно написанная записка, и, как ни странно, в ней подробно описано, что именно нужно для ее ремонта: ториевое устройство и масло льда','Вернитесь к сломанной ловушке в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сломанная западня',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ториевое устройство беспрепятственно встает на место, создавая канал, в который нужно влить масло льда. Как только последние капли масла падают в канал, западня готова к работе.$B$BИ горе неосторожному огру, который подойдет слишком близко!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Перед вами большая сломанная ловушка. Судя по всему, огры пытались починить ловушку, но безуспешно. Рядом с ловушкой лежит поспешно написанная записка, и, как ни странно, в ней подробно описано, что именно нужно для ее ремонта: ториевое устройство и масло льда',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сломанной ловушке в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1194,'Чертежи Риззла','В чертежах Риззла описывается процесс переработки индарилиевой руды. Из его каракулей можно понять, что эта руда добывается в недрах Ульдамана в Бесплодных землях.$B$BОстальные записи посвящены теплопроводным свойствам индарилия.$B$BПачка бумаг придавлена каким-то камнем – скорее всего, это и есть необработанная индарилиевая руда.','Отнесите образец индарилиевой руды Поззику на Мерцающую равнину, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чертежи Риззла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В чертежах Риззла описывается процесс переработки индарилиевой руды. Из его каракулей можно понять, что эта руда добывается в недрах Ульдамана в Бесплодных землях.$B$BОстальные записи посвящены теплопроводным свойствам индарилия.$B$BПачка бумаг придавлена каким-то камнем – скорее всего, это и есть необработанная индарилиевая руда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите образец индарилиевой руды Поззику на Мерцающую равнину, что в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1195,'Священное пламя','Кентавры племени Галак в Тысяче Игл хранят один предмет, сохранившийся еще со времен сотворения кентавров.$b$bНам бы хотелось его получить, но для этого нужен фиал воды из одного из лунных колодцев ночных эльфов.$b$bЧтобы набрать воды, тебе надо сначала добыть один из фиалов дриад, что живут близ Приюта в Ночных Лесах в сердце Ясеневого леса. Лунный колодец есть у западного берега реки Фалфаррен, к югу от главной дороги, у которой ты сможешь наполнить фиал.','Принесите наполненный гравированный фиал Зангену Каменному Копыту в Громовой Утес.','Хорошо. Это как раз то, что просил Рау. Ты можешь отнести ему фиал? Тебе понравится в Иглах, честное слово!','Как только у нас будет наполненный фиал, мы отправим его моему помощнику, Рау, в Тысячу Игл. Он-то и просил фиал этой воды, так что ему лучше знать, что с ней делать.','Вернитесь к Зангену Каменному Копыту в Золотые равнины, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священное пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кентавры племени Галак в Тысяче Игл хранят один предмет, сохранившийся еще со времен сотворения кентавров.$b$bНам бы хотелось его получить, но для этого нужен фиал воды из одного из лунных колодцев ночных эльфов.$b$bЧтобы набрать воды, тебе надо сначала добыть один из фиалов дриад, что живут близ Приюта в Ночных Лесах в сердце Ясеневого леса. Лунный колодец есть у западного берега реки Фалфаррен, к югу от главной дороги, у которой ты сможешь наполнить фиал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите наполненный гравированный фиал Зангену Каменному Копыту в Громовой Утес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Это как раз то, что просил Рау. Ты можешь отнести ему фиал? Тебе понравится в Иглах, честное слово!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как только у нас будет наполненный фиал, мы отправим его моему помощнику, Рау, в Тысячу Игл. Он-то и просил фиал этой воды, так что ему лучше знать, что с ней делать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зангену Каменному Копыту в Золотые равнины, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1196,'Священное пламя','Отнеси наполненный фиал Рау Скальному Бегуну на Заставу Вольного Ветра на юго-востоке Тысячи Игл. Туда ты можешь добраться на Великом подъемнике, что возле южного обрыва Степей.$b$bНе удивлюсь, если ты и в дальнейшем будешь нам помогать.','Доставьте наполненный гравированный фиал Рау Скальному Бегуну на Заставу Вольного Ветра.','Хм, да, этот фиал очень пригодится для наших целей. Поскольку дриады и кентавры происходят от одного корня, вода лунных колодцев поможет нам пробить брешь в стене неугасимого огня, что окружает реликвию кентавров.','Хм, неужто тебя послал Занген?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священное пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси наполненный фиал Рау Скальному Бегуну на Заставу Вольного Ветра на юго-востоке Тысячи Игл. Туда ты можешь добраться на Великом подъемнике, что возле южного обрыва Степей.$b$bНе удивлюсь, если ты и в дальнейшем будешь нам помогать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте наполненный гравированный фиал Рау Скальному Бегуну на Заставу Вольного Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм, да, этот фиал очень пригодится для наших целей. Поскольку дриады и кентавры происходят от одного корня, вода лунных колодцев поможет нам пробить брешь в стене неугасимого огня, что окружает реликвию кентавров.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хм, неужто тебя послал Занген?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1197,'Священное пламя','Принесенной водой можно будет затушить пламя, охраняющее реликвию кентавров. Однако оно погаснет лишь ненадолго, так что тебе придется поспешить.$B$BСкала Треснувшего Копыта – поселение кентавров – находится к северу отсюда. Огонь горит в Оплоте Треснувшего Копыта – самой охраняемой части утеса.$B$BБудь $gосторожен:осторожна; – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность.','Принесите раздвоенное копыто Рау Скальному Бегуну на Заставу Вольного Ветра.','Жду не дождусь, когда смогу получить это раздвоенное копыто. Вы уже добыли его?','Вернитесь к Рау Скальному Бегуну на Заставу Вольного Ветра, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священное пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принесенной водой можно будет затушить пламя, охраняющее реликвию кентавров. Однако оно погаснет лишь ненадолго, так что тебе придется поспешить.$B$BСкала Треснувшего Копыта – поселение кентавров – находится к северу отсюда. Огонь горит в Оплоте Треснувшего Копыта – самой охраняемой части утеса.$B$BБудь $gосторожен:осторожна; – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите раздвоенное копыто Рау Скальному Бегуну на Заставу Вольного Ветра.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Жду не дождусь, когда смогу получить это раздвоенное копыто. Вы уже добыли его?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рау Скальному Бегуну на Заставу Вольного Ветра, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1198,'В поисках Талрида','В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине, что к западу отсюда.$b$bЯ должен собрать как можно больше сведений, чтобы мы могли понять, где и когда нужна наша помощь.$b$bУже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине. Разведчик Талрид до сих пор не вернулся.$b$bДругие мои разведчики заняты насущными делами.$b$bПомоги мне найти Талрида, $n.','Найдите разведчика Талрида из ордена Серебряного Рассвета в Непроглядной Пучине.','Хорошо, что Рассветный дозорный Шедласс прислал вас. В этом испоганенном месте и правда затевается коварный план.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Талрида',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине, что к западу отсюда.$b$bЯ должен собрать как можно больше сведений, чтобы мы могли понять, где и когда нужна наша помощь.$b$bУже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине. Разведчик Талрид до сих пор не вернулся.$b$bДругие мои разведчики заняты насущными делами.$b$bПомоги мне найти Талрида, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите разведчика Талрида из ордена Серебряного Рассвета в Непроглядной Пучине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что Рассветный дозорный Шедласс прислал вас. В этом испоганенном месте и правда затевается коварный план.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1199,'Наступление сумерек','Черпая силу из старинных обрядов, посвященных древним богам Хаоса, Сумеречный Молот пытается вернуть своих темных покровителей и распространить смерть и ужас по всему миру.$b$bМы думаем, что Сумеречный Молот вступил в союз с нагами, и теперь они накапливают силы в Непроглядной Пучине на западе.$b$bЧто бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться.$b$bОбъяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены.','Принесите 10 подвесок Сумерек часовому Алувин в лагерь у Непроглядной Пучины.','В Непроглядной Пучине некогда был древний храм ночных эльфов. Одно время там находился самый мощный лунный колодец. Кто знает, какое зло ныне клубится там, когда храм в руках Сумеречного Молота?$B$BУдалось ли тебе проредить их ряды?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наступление сумерек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Черпая силу из старинных обрядов, посвященных древним богам Хаоса, Сумеречный Молот пытается вернуть своих темных покровителей и распространить смерть и ужас по всему миру.$b$bМы думаем, что Сумеречный Молот вступил в союз с нагами, и теперь они накапливают силы в Непроглядной Пучине на западе.$b$bЧто бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться.$b$bОбъяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 подвесок Сумерек часовому Алувин в лагерь у Непроглядной Пучины.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В Непроглядной Пучине некогда был древний храм ночных эльфов. Одно время там находился самый мощный лунный колодец. Кто знает, какое зло ныне клубится там, когда храм в руках Сумеречного Молота?$B$BУдалось ли тебе проредить их ряды?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1200,'Злодейство в Непроглядной Пучине','Strength has left me. Your help is needed!$b$bLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.$b$bAku\'Mai, servant of the Old God, rose from the waters.$b$bThe Twilight\'s Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku\'Mai for power.$b$bSlay Kelris and bring his head to Ashelan at the Blackfathom Camp, $n, please.','Bring the head of Twilight Lord Kelris to Ashelan Northwood at the Blackfathom Camp.','Время дорого, $C. $B$BМоя задача в Дарнассе – обеспечить процветание Серебряного Рассвета и поражение злых сил, вторгшихся в Калимдор. $B$BГовори, зачем пришел или уходи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злодейство в Непроглядной Пучине',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Strength has left me. Your help is needed!$b$bLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from below and tainted the sacred moonwell.$b$bAku\'Mai, servant of the Old God, rose from the waters.$b$bThe Twilight\'s Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku\'Mai for power.$b$bSlay Kelris and bring his head to Ashelan at the Blackfathom Camp, $n, please.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Bring the head of Twilight Lord Kelris to Ashelan Northwood at the Blackfathom Camp.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Время дорого, $C. $B$BМоя задача в Дарнассе – обеспечить процветание Серебряного Рассвета и поражение злых сил, вторгшихся в Калимдор. $B$BГовори, зачем пришел или уходи.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1201,'Тераморские шпионы','Убейте 9 тераморских шпионов, потом вернитесь к Назиру Кровавому Копью в деревню Гиблотопь.','Ты нашел шпионов, $N?','Вернитесь к Назиру Кровавому Копью в деревню Гиблотопь, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тераморские шпионы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 тераморских шпионов, потом вернитесь к Назиру Кровавому Копью в деревню Гиблотопь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел шпионов, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Назиру Кровавому Копью в деревню Гиблотопь, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1202,'Доки Терамора','$n? Мы посылали двоих разведчиков украсть бумаги с корабля в одном из тераморских доков. Они добыли их, но были обнаружены, и им пришлось выбросить добычу в море.$b$bОдному из них удалось сбежать, но поднять документы со дна он не смог. Теперь я поручаю эту задачу тебе.$b$bБумаги лежат в сундучке, на дне моря возле тераморских доков. Найди их, $n, и принеси мне.','Браво, $N. Это было нелегко, но документы, которые ты $Gдобыл:добыла; – весьма ценны.','Ты $Gнашел:нашла; документы, $N? Информация содержащаяся в них, жизненно важна для Альянса, а значит необходима разведке Орды.','Вернитесь к Назиру Кровавому Копью в деревню Гиблотопь, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доки Терамора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n? Мы посылали двоих разведчиков украсть бумаги с корабля в одном из тераморских доков. Они добыли их, но были обнаружены, и им пришлось выбросить добычу в море.$b$bОдному из них удалось сбежать, но поднять документы со дна он не смог. Теперь я поручаю эту задачу тебе.$b$bБумаги лежат в сундучке, на дне моря возле тераморских доков. Найди их, $n, и принеси мне.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Браво, $N. Это было нелегко, но документы, которые ты $Gдобыл:добыла; – весьма ценны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; документы, $N? Информация содержащаяся в них, жизненно важна для Альянса, а значит необходима разведке Орды.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Назиру Кровавому Копью в деревню Гиблотопь, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1203,'Ярлу нужен клинок','Мне предстоит жестокая рубка. С кем, я тебе сказать не могу, но вот то, что мне для этого просто необходим добрый клинок, это к гадалке не ходи. Некоторые называют его меч, а я зову пляшущий клинок.$b$bПоможешь мне, а? Эти рыболюди, мурлоки или как их там... ну те, что живут к северу отсюда на побережье. Среди них есть один, они зовут его Костяная Чешуя, так вот он носит неплохой клинок. Он-то мне и нужен!$b$bГлавное, поторопись, то что я собираюсь рубить, ждать не станет...','Принесите меч Костяной Чешуи Ярлу "Болотному Глазу" в сторожку "Болотный огонек".','Это хороший клинок... Он хорошо танцует, – стало быть, это – хороший танцующий клинок! Спасибо-спасибо-спасибо!!! Таак. Теперь я его испробую...$B$BПозже. Я испробую его позже. Но все равно спасибо тебе!','Ты достал мне клинок?','Вернитесь к Ярлу "Болотному Глазу" в сторожку "Болотный огонек", что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярлу нужен клинок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне предстоит жестокая рубка. С кем, я тебе сказать не могу, но вот то, что мне для этого просто необходим добрый клинок, это к гадалке не ходи. Некоторые называют его меч, а я зову пляшущий клинок.$b$bПоможешь мне, а? Эти рыболюди, мурлоки или как их там... ну те, что живут к северу отсюда на побережье. Среди них есть один, они зовут его Костяная Чешуя, так вот он носит неплохой клинок. Он-то мне и нужен!$b$bГлавное, поторопись, то что я собираюсь рубить, ждать не станет...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите меч Костяной Чешуи Ярлу "Болотному Глазу" в сторожку "Болотный огонек".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это хороший клинок... Он хорошо танцует, – стало быть, это – хороший танцующий клинок! Спасибо-спасибо-спасибо!!! Таак. Теперь я его испробую...$B$BПозже. Я испробую его позже. Но все равно спасибо тебе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал мне клинок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ярлу "Болотному Глазу" в сторожку "Болотный огонек", что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1204,'Суп из глинистой черепахи с крабами','Я тут работаю над новым блюдом, оно будет называться "Суп из глинистой черепахи с крабами". Мне все еще не хватает основных ингредиентов, но я не уверен, что перенесу еще одну прогулку по Пылевым топям. $n, ты не окажешь мне услугу? Прежде всего, мне нужны языки глинистых черепах. Они водятся на побережье, в основном вокруг залива.$B$BНо мне не всякие языки сгодятся – я слышал, что у некоторых из этих черепах языки раздвоены. $B$BВот они-то и обладают тем непередаваемым вкусом, которым я хочу порадовать своих клиентов.','Принесите 8 раздвоенных языков глинистых черепах Моргану Штерну в Терамор.','Ну как? Удалось добыть необходимые мне языки?','Вернитесь к Моргану Штерну на Остров Терамор, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суп из глинистой черепахи с крабами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тут работаю над новым блюдом, оно будет называться "Суп из глинистой черепахи с крабами". Мне все еще не хватает основных ингредиентов, но я не уверен, что перенесу еще одну прогулку по Пылевым топям. $n, ты не окажешь мне услугу? Прежде всего, мне нужны языки глинистых черепах. Они водятся на побережье, в основном вокруг залива.$B$BНо мне не всякие языки сгодятся – я слышал, что у некоторых из этих черепах языки раздвоены. $B$BВот они-то и обладают тем непередаваемым вкусом, которым я хочу порадовать своих клиентов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 раздвоенных языков глинистых черепах Моргану Штерну в Терамор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Удалось добыть необходимые мне языки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моргану Штерну на Остров Терамор, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1205,'Волокун','Волокун – старый кроколиск из Пылевых топей. Ему давно уже пора сдохнуть.$B$BСкрипя старыми костями, он таскает свою огромную тушу по болоту. Хотя он все еще движется с силой и скоростью молодого животного, его неугасимый пламенный дух уже износил свое дряхлое тело.$b$bТы $Gдолжен:должна; освободить его от этой боли, $n. Даруй ему покой.','Принесите зуб кроколиска Волокуна Мелору в Громовой Утес.','Вернитесь к Мелору Каменному Копыту на Вершину Охотников, что в Громовом Утесе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волокун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волокун – старый кроколиск из Пылевых топей. Ему давно уже пора сдохнуть.$B$BСкрипя старыми костями, он таскает свою огромную тушу по болоту. Хотя он все еще движется с силой и скоростью молодого животного, его неугасимый пламенный дух уже износил свое дряхлое тело.$b$bТы $Gдолжен:должна; освободить его от этой боли, $n. Даруй ему покой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите зуб кроколиска Волокуна Мелору в Громовой Утес.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелору Каменному Копыту на Вершину Охотников, что в Громовом Утесе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1206,'Ярлу нужны глаза','Глазной сок очень вкусный, жаль только что большинство живых существ имеет всего по два глаза.$b$bНо вот у пауков их уже больше, гораздо больше. А сок из глаз пауков Мглистой пещеры обладает особенным мягким вкусом. Целехонькие паучьи глазки... прям уже чую их на языке.$b$bЭти пауки водятся к пещере к западу отсюда. Вот как ты думаешь, это пауки были названы по своей пещере или наоборот?','Принесите 20 целых глаз пауков Мглистой пещеры Ярлу "Болотному Глазу" в сторожку "Болотный огонек".','Ты $Gпринес:принесла; вкусные глазки... Паучьи глаза чисты как слеза.$B$BИх едят, а они глядят…$B$BВот те, что глядят, съешь последними, а то на болотах-то другой компании и нет.$B$BПривет, глазки мои маленькие, привеет! На вкус лучше курочки, с солью, с приправками...$B$BМмм...','Ну и где мои глаза?','Вернитесь к Ярлу "Болотному Глазу" в сторожку "Болотный огонек", что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярлу нужны глаза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глазной сок очень вкусный, жаль только что большинство живых существ имеет всего по два глаза.$b$bНо вот у пауков их уже больше, гораздо больше. А сок из глаз пауков Мглистой пещеры обладает особенным мягким вкусом. Целехонькие паучьи глазки... прям уже чую их на языке.$b$bЭти пауки водятся к пещере к западу отсюда. Вот как ты думаешь, это пауки были названы по своей пещере или наоборот?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 целых глаз пауков Мглистой пещеры Ярлу "Болотному Глазу" в сторожку "Болотный огонек".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпринес:принесла; вкусные глазки... Паучьи глаза чисты как слеза.$B$BИх едят, а они глядят…$B$BВот те, что глядят, съешь последними, а то на болотах-то другой компании и нет.$B$BПривет, глазки мои маленькие, привеет! На вкус лучше курочки, с солью, с приправками...$B$BМмм...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну и где мои глаза?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ярлу "Болотному Глазу" в сторожку "Болотный огонек", что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1218,'Лягушачьи лапки','Люблю болотную кухню. Жареные лягушачьи лапки и все такое...$b$bА вот как раз они-то у меня все вышли... Поместье кишит гигантскими болотными лягушками. Как думаешь, сможешь добыть их лапок? Дело-то в общем плевое, просто бьешь лягушку по башке и приносишь мне ее лапки.$b$bА я их тут потушу и поделюсь с тобой.$b$bТы как насчет тушеной лягушатинки?','Принесите 10 лапок болотных лягушек Ярлу "Болотному Глазу" с Пылевых топей.','Ага, вот и специи. Вот теперь жабятина вполне готова.','Специи. Без них жизнь была бы совсем пресной, как думаешь?','Вернитесь к Ярлу "Болотному Глазу" на Ведьмин холм, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лягушачьи лапки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Люблю болотную кухню. Жареные лягушачьи лапки и все такое...$b$bА вот как раз они-то у меня все вышли... Поместье кишит гигантскими болотными лягушками. Как думаешь, сможешь добыть их лапок? Дело-то в общем плевое, просто бьешь лягушку по башке и приносишь мне ее лапки.$b$bА я их тут потушу и поделюсь с тобой.$b$bТы как насчет тушеной лягушатинки?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 лапок болотных лягушек Ярлу "Болотному Глазу" с Пылевых топей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, вот и специи. Вот теперь жабятина вполне готова.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Специи. Без них жизнь была бы совсем пресной, как думаешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ярлу "Болотному Глазу" на Ведьмин холм, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1219,'[DEPRECATED]The Orc Report','Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. $B$BДонесение написано на орочьем... И по виду важное...','Доставьте орочье донесение лейтенанту Адену в Терамор.','Хм... Я не силен в орочьем, но это похоже... на отчет шпиона!','Вы что-то хотите мне сообщить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Orc Report',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. $B$BДонесение написано на орочьем... И по виду важное...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте орочье донесение лейтенанту Адену в Терамор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... Я не силен в орочьем, но это похоже... на отчет шпиона!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы что-то хотите мне сообщить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1220,'[DEPRECATED]Captain Vimes','Капитан Ваймс должен увидеть найденное тобой орочье донесение, $n. Он знает орочий язык, лучше чем кто либо из нас, и он должен быть осведомлен о том, что вблизи Терамора рыщут шпионы Орды.$b$bТы найдешь капитана в казармах в северо-восточной части острова Терамор.','Принесите шпионское донесение капитану Гаррану Ваймсу.','Донесение орочьего шпиона! Как тебе удалось его раздобыть? Впрочем, неважно, – давай-ка посмотрим, о чем там говорится...','У тебя что-то есть для меня?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Captain Vimes',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Капитан Ваймс должен увидеть найденное тобой орочье донесение, $n. Он знает орочий язык, лучше чем кто либо из нас, и он должен быть осведомлен о том, что вблизи Терамора рыщут шпионы Орды.$b$bТы найдешь капитана в казармах в северо-восточной части острова Терамор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите шпионское донесение капитану Гаррану Ваймсу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Донесение орочьего шпиона! Как тебе удалось его раздобыть? Впрочем, неважно, – давай-ка посмотрим, о чем там говорится...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя что-то есть для меня?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1221,'Корни Синелиста','Корень синелиста – признанный деликатес в любом уголке мира! Но растет он только здесь, в Степях, глубоко под землей в Лабиринтах Иглошкурых.$B$BК тому же клубни так сложно найти, если не знать точно где искать! Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землей. Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов!$B$BЗадачка, конечно, непростая, но если принесешь мне корней, я хорошо заплачу.','Возьмите ящик с отверстиями.$BВозьмите палочку-погонялочку для шмыгуносов.$BВозьмите справочник по шмыгуносам. $B$BВ Лабиринтах Иглошкурых выпустите шмыгуноса и воспользуйтесь палочкой-погонялочкой, чтобы он начал искать корни. $B$BПринесите 6 корней синелиста, палочку и ящик с отверстиями Мебоку Миззриксу в Кабестан.','Вернитесь к Мебоку Миззриксу в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корни Синелиста',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Корень синелиста – признанный деликатес в любом уголке мира! Но растет он только здесь, в Степях, глубоко под землей в Лабиринтах Иглошкурых.$B$BК тому же клубни так сложно найти, если не знать точно где искать! Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землей. Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов!$B$BЗадачка, конечно, непростая, но если принесешь мне корней, я хорошо заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите ящик с отверстиями.$BВозьмите палочку-погонялочку для шмыгуносов.$BВозьмите справочник по шмыгуносам. $B$BВ Лабиринтах Иглошкурых выпустите шмыгуноса и воспользуйтесь палочкой-погонялочкой, чтобы он начал искать корни. $B$BПринесите 6 корней синелиста, палочку и ящик с отверстиями Мебоку Миззриксу в Кабестан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мебоку Миззриксу в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1222,'Побег Вонючки','Ура! Наконец-то нашелся кто-то, кто не хочет меня съесть!$B$BНе могу отбиться от тутошнего зверья, а ты, $gпарень:подруга;, как раз мне в этом и поможешь.$b$bПовар Морган Штерн составляет рецепт нового блюда, и он послал меня сюда на поиски листьев болотного боба. Он, похоже, думает, что они вкусные.$b$bКак бы то ни было, пока я искал эти самые листья... меня окружили! Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать эти бобы!','Сопроводите "Вонючку" Игнаца, затем пообщайтесь с Морганом Штерном в Тераморе.','Мистер Игнац не так давно приносил листья болотного боба, и он расказал мне, что вы помогли ему выбраться из весьма затруднительной ситуации.$B$BБлагодарю вас, $n. Я попрошу своего дядю принять вас по-королевски, когда вы в следующий раз окажетесь в "Синем отшельнике", в Штормграде.','Вы видели мистера Игнатца? Некоторое время назад я отправил его в болото, и он не вернулся!','Помогите Вонючке найти листья болотного боба.','Вернитесь к Моргану Штерну в Терамор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег Вонючки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ура! Наконец-то нашелся кто-то, кто не хочет меня съесть!$B$BНе могу отбиться от тутошнего зверья, а ты, $gпарень:подруга;, как раз мне в этом и поможешь.$b$bПовар Морган Штерн составляет рецепт нового блюда, и он послал меня сюда на поиски листьев болотного боба. Он, похоже, думает, что они вкусные.$b$bКак бы то ни было, пока я искал эти самые листья... меня окружили! Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать эти бобы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите "Вонючку" Игнаца, затем пообщайтесь с Морганом Штерном в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мистер Игнац не так давно приносил листья болотного боба, и он расказал мне, что вы помогли ему выбраться из весьма затруднительной ситуации.$B$BБлагодарю вас, $n. Я попрошу своего дядю принять вас по-королевски, когда вы в следующий раз окажетесь в "Синем отшельнике", в Штормграде.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы видели мистера Игнатца? Некоторое время назад я отправил его в болото, и он не вернулся!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помогите Вонючке найти листья болотного боба.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моргану Штерну в Терамор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1238,'Потерянный рапорт','Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. $B$BЭто донесение шпиона, который провел многие недели в Тераморе.$b$bРасшифровав его, мы выяснили, что это донесение должно быть доставлено командиру орков-разведчиков в Деревню Гиблотопь.','Отнесите донесение шпиона Назиру Кровавому Копью в Деревню Гиблотопь.','Отлично, $N. Наш агент Марг Ночной Соглядатай был отправлен на разведку в Терамор.$B$BЭто его последний рапорт и, видимо, уже окончательно последний – судя по твоим словам, я боюсь, Марг навсегда остался в болотах...','У тебя что-то есть для меня?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянный рапорт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Просеивая землю, мы нашли отрубленную руку орка, сжимающую резную костяную трубку. А в трубке находился заляпаный грязью пергамент. $B$BЭто донесение шпиона, который провел многие недели в Тераморе.$b$bРасшифровав его, мы выяснили, что это донесение должно быть доставлено командиру орков-разведчиков в Деревню Гиблотопь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите донесение шпиона Назиру Кровавому Копью в Деревню Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N. Наш агент Марг Ночной Соглядатай был отправлен на разведку в Терамор.$B$BЭто его последний рапорт и, видимо, уже окончательно последний – судя по твоим словам, я боюсь, Марг навсегда остался в болотах...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя что-то есть для меня?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1239,'Отрубленная Голова','Стоило копнуть чуть глубже, и из земли показалась отрубленная голова орка. На его лице застыл оскал, а в темных глазах – вызов.','Принесите голову строптивого орка Назиру Кровавому Копью в Деревню Гиблотопь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отрубленная Голова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стоило копнуть чуть глубже, и из земли показалась отрубленная голова орка. На его лице застыл оскал, а в темных глазах – вызов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову строптивого орка Назиру Кровавому Копью в Деревню Гиблотопь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1240,'Тролль-знахарь','Мы должны выяснить обстоятельства смерти Марга! И единственный способ это сделать, $n, – воспользоваться магией троллей. $B$BОтнеси голову Марга Кин\'вилаю в лагерь Гром\'гол в Тернистой долине.$b$bКин\'вилай – самый могущественный из знахарей Черного Копья, если кто-то и сможет вызвать дух Ночного Соглядатая – то это он.','Принесите голову строптивого орка Кин\'вилаю в лагерь Гром\'гол в Тернистой долине.','Да, теперь я вижу. Дух Марга застрял в нашем мире, потому что его задание не было завершено.\n\nНу что ж, давай поговорим с этим сердитым орком...','Рядом с тобой вьется очень сердитый дух, брат. Что привело тебя к Кин\'вилаю?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролль-знахарь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны выяснить обстоятельства смерти Марга! И единственный способ это сделать, $n, – воспользоваться магией троллей. $B$BОтнеси голову Марга Кин\'вилаю в лагерь Гром\'гол в Тернистой долине.$b$bКин\'вилай – самый могущественный из знахарей Черного Копья, если кто-то и сможет вызвать дух Ночного Соглядатая – то это он.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову строптивого орка Кин\'вилаю в лагерь Гром\'гол в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, теперь я вижу. Дух Марга застрял в нашем мире, потому что его задание не было завершено.\n\nНу что ж, давай поговорим с этим сердитым орком...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рядом с тобой вьется очень сердитый дух, брат. Что привело тебя к Кин\'вилаю?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1241,'Пропавший дипломат','Некоторое время назад один из наших дипломатов был отправлен в Терамор для встречи с Джайной Праудмур. Он не вернулся.$B$BЯ подозреваю, что к этому приложило руку Братство Справедливости, но уверенности у меня пока что нет. Пока что нам удается скрывать факт исчезновения дипломата, но так продолжаться не может.$B$BАгенты королевской службы рыщут по городам, но я хочу задействовать и свои связи.$B$BНа Аллее Героев вы найдете моего старого друга, его зовут Йорген. Передайте ему эту записку и во всем его слушайтесь.','Найдите Йоргена в Штормграде.','Хм-м... Йорген смотрит на вас, прищурившись.$B$BХорошо. Придется вам помочь, хоть и не очень-то хочется. Долг есть долг.$B$BИ запомните одну простую вещь: вы знаете куда больше, чем уместно в вашем случае. Храните наши маленькие секреты и не болтайте по тавернам о том, что обнаружите. Ясно вам?','Хм-м, ну, надеюсь, у вас есть действительно достойный повод оторвать меня от рыбалки. Я не подаю нищим и не покупаю ничего у разносчиков...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторое время назад один из наших дипломатов был отправлен в Терамор для встречи с Джайной Праудмур. Он не вернулся.$B$BЯ подозреваю, что к этому приложило руку Братство Справедливости, но уверенности у меня пока что нет. Пока что нам удается скрывать факт исчезновения дипломата, но так продолжаться не может.$B$BАгенты королевской службы рыщут по городам, но я хочу задействовать и свои связи.$B$BНа Аллее Героев вы найдете моего старого друга, его зовут Йорген. Передайте ему эту записку и во всем его слушайтесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Йоргена в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм-м... Йорген смотрит на вас, прищурившись.$B$BХорошо. Придется вам помочь, хоть и не очень-то хочется. Долг есть долг.$B$BИ запомните одну простую вещь: вы знаете куда больше, чем уместно в вашем случае. Храните наши маленькие секреты и не болтайте по тавернам о том, что обнаружите. Ясно вам?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хм-м, ну, надеюсь, у вас есть действительно достойный повод оторвать меня от рыбалки. Я не подаю нищим и не покупаю ничего у разносчиков...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1242,'Пропавший дипломат','Возьмите записку для Иллинга Триаса. Ничего ему не рассказывайте, просто ведите себя вежливо и дождитесь ответа; не волнуйтесь, Триас ответит.$B$BЕще раз напоминаю вам, $n: дело серьезное, так что держите рот на замке.$B$BТриаса вы найдете в его магазине в Торговом квартале; магазин называется "Сыры Триаса". Удачи!','Доставьте запечатанную записку Йоргена Иллингу Триасу в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьмите записку для Иллинга Триаса. Ничего ему не рассказывайте, просто ведите себя вежливо и дождитесь ответа; не волнуйтесь, Триас ответит.$B$BЕще раз напоминаю вам, $n: дело серьезное, так что держите рот на замке.$B$BТриаса вы найдете в его магазине в Торговом квартале; магазин называется "Сыры Триаса". Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте запечатанную записку Йоргена Иллингу Триасу в Штормград.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1243,'Пропавший дипломат','Йорген, ах ты старый мерзавец... Ну и что со всем этим делать?$B$BЛадно, я разберусь... Да чтоб ему в Круговерть Пустоты угодить раньше времени!$B$BНу что, $n, займемся делом? Я задействую все свои контакты, но вам придется побегать.$B$BОтправляйтесь в поселение Темнолесье, которое находится в Сумеречном лесу, и найдите там дозорного Бакуса; он обычно патрулирует северную дорогу за городской стеной. Просто скажите ему, что Братство Справедливости опять зашевелилось, а вы присматриваете за ним по моей просьбе – и он вам поможет, чем сможет.','Отнесите запечатанное письмо дозорному Бакусу в Сумеречный лес.','Вас послал Триас, да? Другое дело...$B$BМожете гонять чудовищ, сколько вам заблагорассудится. Уверен, что для вас это не составит особого труда, какой бы ужас ни вылез на вас из сумерек...$B$BТак чего же желает мой дорогой друг в этот пасмурный день?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Йорген, ах ты старый мерзавец... Ну и что со всем этим делать?$B$BЛадно, я разберусь... Да чтоб ему в Круговерть Пустоты угодить раньше времени!$B$BНу что, $n, займемся делом? Я задействую все свои контакты, но вам придется побегать.$B$BОтправляйтесь в поселение Темнолесье, которое находится в Сумеречном лесу, и найдите там дозорного Бакуса; он обычно патрулирует северную дорогу за городской стеной. Просто скажите ему, что Братство Справедливости опять зашевелилось, а вы присматриваете за ним по моей просьбе – и он вам поможет, чем сможет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанное письмо дозорному Бакусу в Сумеречный лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вас послал Триас, да? Другое дело...$B$BМожете гонять чудовищ, сколько вам заблагорассудится. Уверен, что для вас это не составит особого труда, какой бы ужас ни вылез на вас из сумерек...$B$BТак чего же желает мой дорогой друг в этот пасмурный день?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (1244,'Пропавший дипломат','Опять братство?! Они вечно что-то вытворяют; даже если они затихли, мы считаем это недвусмысленной угрозой.$B$BКстати, сейчас я вспомнил, что последнюю пару недель их агенты так и кишат вокруг Участка Эддла. Это подозрительно – должно быть, назревает какая-то крупная заварушка.$B$BНе хотите порыскать там и установить, в чем же дело?$B$BФерма находится к югу от дороги из Западного Края как раз на входе в Сумеречный лес.','Найдите декларацию Братства Справедливости и верните ее дозорному Бакусу в Сумеречном лесу.','Вы вернулись, не вляпавшись ни в какие неприятности. Это само по себе достижение, не правда ли?$B$BНу, покажите, что принесли? Да, очень похоже на официальные документы Братства Справедливости. Но это может быть и подделкой, которую вам подсунули, чтобы одурачить и сбить со следа.','Вернитесь к дозорному Бакусу в Темнолесье, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Опять братство?! Они вечно что-то вытворяют; даже если они затихли, мы считаем это недвусмысленной угрозой.$B$BКстати, сейчас я вспомнил, что последнюю пару недель их агенты так и кишат вокруг Участка Эддла. Это подозрительно – должно быть, назревает какая-то крупная заварушка.$B$BНе хотите порыскать там и установить, в чем же дело?$B$BФерма находится к югу от дороги из Западного Края как раз на входе в Сумеречный лес.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите декларацию Братства Справедливости и верните ее дозорному Бакусу в Сумеречном лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы вернулись, не вляпавшись ни в какие неприятности. Это само по себе достижение, не правда ли?$B$BНу, покажите, что принесли? Да, очень похоже на официальные документы Братства Справедливости. Но это может быть и подделкой, которую вам подсунули, чтобы одурачить и сбить со следа.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Бакусу в Темнолесье, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1245,'Пропавший дипломат','О-ох, для обычной попытки ввести в заблуждение это слишком сложно. Отнесите этот документ Триасу, пусть поразмыслит над ним. И никому больше об этом не говорите. Кажется, это дело ни мне, ни ему не по плечу. Ну, посмотрим...$B$BИ, пожалуйста, $n, никому не говорите, что я вам помог. Если мое начальство поймет, что я о чем-то узнал и не поделился с ними, они могут меня запросто повесить.','Отнесите декларацию Братства Справедливости Иллингу Триасу в Штормград.','Да-а... весьма интересно. Йорген и Делавей молодцы, что навели меня на это.$B$BКажется, Братство Справедливости всерьез взялось за воплощение своих планов. Хм, а это что? "Кулак"? Знакомое имя...','Ой, да вы вернулись, и целиком, а не кусками в посылке! Разумеется, вы не за сыром явились, так давайте сразу перейдем к делу! Помог ли вам Бакус, или в Сумеречном лесу вы ничего не нашли?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О-ох, для обычной попытки ввести в заблуждение это слишком сложно. Отнесите этот документ Триасу, пусть поразмыслит над ним. И никому больше об этом не говорите. Кажется, это дело ни мне, ни ему не по плечу. Ну, посмотрим...$B$BИ, пожалуйста, $n, никому не говорите, что я вам помог. Если мое начальство поймет, что я о чем-то узнал и не поделился с ними, они могут меня запросто повесить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите декларацию Братства Справедливости Иллингу Триасу в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-а... весьма интересно. Йорген и Делавей молодцы, что навели меня на это.$B$BКажется, Братство Справедливости всерьез взялось за воплощение своих планов. Хм, а это что? "Кулак"? Знакомое имя...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ой, да вы вернулись, и целиком, а не кусками в посылке! Разумеется, вы не за сыром явились, так давайте сразу перейдем к делу! Помог ли вам Бакус, или в Сумеречном лесу вы ничего не нашли?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1246,'Пропавший дипломат','Вот что я об этом думаю... Дашель... Какой-то Дашель... Как его фамилия? Кулак! Дашель Каменный Кулак! В некоторых кругах его зовут просто Кулак, наверняка потому, что он не дурак подраться...$B$BЕго можно найти в Старом городе, прямо в центре. Поговорите с ним. Если понадобится, используйте меч или любой подручный тяжелый предмет, чтобы урезонить его, и не сомневайтесь. Если он так завязан в заговоре, как можно заключить по этим бумагам, то не расстанется с информацией по доброй воле...','Поговорите с Дашелем Каменным Кулаком в Штормграде.','Что?!$B$BМои дела тебя не касаются, ясно? Проваливай, нечего тебе здесь вынюхивать!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот что я об этом думаю... Дашель... Какой-то Дашель... Как его фамилия? Кулак! Дашель Каменный Кулак! В некоторых кругах его зовут просто Кулак, наверняка потому, что он не дурак подраться...$B$BЕго можно найти в Старом городе, прямо в центре. Поговорите с ним. Если понадобится, используйте меч или любой подручный тяжелый предмет, чтобы урезонить его, и не сомневайтесь. Если он так завязан в заговоре, как можно заключить по этим бумагам, то не расстанется с информацией по доброй воле...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дашелем Каменным Кулаком в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что?!$B$BМои дела тебя не касаются, ясно? Проваливай, нечего тебе здесь вынюхивать!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1247,'Пропавший дипломат','Ну... м-м... да... Я кое-что знаю о встрече на Участке Эддла. Она произошла несколько недель назад. Меня туда не приглашали, мое участие закончилось с провалом плана А, будь прокляты эти чертовы искатели приключений...$B$BПарень, с которым связан план Б, пришел из Менетила. Его зовут Пронырой. Это все, что мне удалось узнать из запасного плана.','Поговорите с Иллингом Триасом в Штормграде.','О, $n, приятно видеть вас в живых. Значит, с Дашелем все прошло хорошо?$B$BЯ тут еще раз перечитал их планы, и хотя в тексте не упоминается имя дипломата, которого они преследовали, речь идет о плане Б, который вступил в действие после провала первой попытки захватить его.$B$BЭтот Проныра, о котором упомянул Дашель, кажется, не имеет другого имени – непонятно, кто он; но нам хотя бы известно, что он из Менетила.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну... м-м... да... Я кое-что знаю о встрече на Участке Эддла. Она произошла несколько недель назад. Меня туда не приглашали, мое участие закончилось с провалом плана А, будь прокляты эти чертовы искатели приключений...$B$BПарень, с которым связан план Б, пришел из Менетила. Его зовут Пронырой. Это все, что мне удалось узнать из запасного плана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Иллингом Триасом в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, $n, приятно видеть вас в живых. Значит, с Дашелем все прошло хорошо?$B$BЯ тут еще раз перечитал их планы, и хотя в тексте не упоминается имя дипломата, которого они преследовали, речь идет о плане Б, который вступил в действие после провала первой попытки захватить его.$B$BЭтот Проныра, о котором упомянул Дашель, кажется, не имеет другого имени – непонятно, кто он; но нам хотя бы известно, что он из Менетила.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1248,'Пропавший дипломат','Один из моих знакомых переехал в Болотину, в портовый город Менетил. Думаю, что он поможет вам, если вы передадите ему привет и скажете, что работаете на меня. Зовут его Михаил; перед отъездом он говорил, что хочет стать барменом.$B$BПоговорите с ним, найдите этого Проныру и попробуйте разузнать еще что-нибудь насчет похищенного дипломата. Мы должны узнать, где его держат или хотя бы имя похищенного. Увы, в декларации ничего не говорится о том, что похитители собираются сделать с пленником после захвата.','Поговорите с Михаилом в Болотине.','Привет-привет, дорогой $n. Рады вас видеть. Не желаете ли эля? Или баранины?$B$BСкажите, чего бы вам хотелось, и я постараюсь выполнить все ваши пожелания. Меня зовут Михаил, я буду рад услужить вам.$B$BЭ? Что это? Триас? Прошу вас, говорите потише. Моим посетителям не обязательно слышать, о чем мы с вами говорим.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из моих знакомых переехал в Болотину, в портовый город Менетил. Думаю, что он поможет вам, если вы передадите ему привет и скажете, что работаете на меня. Зовут его Михаил; перед отъездом он говорил, что хочет стать барменом.$B$BПоговорите с ним, найдите этого Проныру и попробуйте разузнать еще что-нибудь насчет похищенного дипломата. Мы должны узнать, где его держат или хотя бы имя похищенного. Увы, в декларации ничего не говорится о том, что похитители собираются сделать с пленником после захвата.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Михаилом в Болотине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет-привет, дорогой $n. Рады вас видеть. Не желаете ли эля? Или баранины?$B$BСкажите, чего бы вам хотелось, и я постараюсь выполнить все ваши пожелания. Меня зовут Михаил, я буду рад услужить вам.$B$BЭ? Что это? Триас? Прошу вас, говорите потише. Моим посетителям не обязательно слышать, о чем мы с вами говорим.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1249,'Пропавший дипломат','Значит, вас послал Иллинг? О, это повод десятикратно умножить мое гостеприимство! Просите всего, чего пожелаете, постараюсь выполнить любую вашу просьбу!$b$BХм-м, Проныра, говорите? Не скажу, что мне знакомо это имя, но постараюсь что-нибудь разведать...$B$B$n, не оборачивайтесь прямо сейчас, но вон тот господин около двери слишком внимательно смотрит на нас и прислушивается к нашему разговору. На вашем месте я бы попробовал изловить его прежде, чем он уйдет отсюда.','Перехватите Яна Тапоке до его ухода и вернитесь к Михаилу.','Поймали его, да? Отлично! Знаете, а ведь это и есть тот самый Проныра! Я и сам удивился.$B$BДа, не думал я, что буду так скучать по всяким тайным расследованиям и азартным погоням. Верно говорят: сколько волка ни корми... Только не обмолвитесь про это Эллингу – он наверняка потащит меня обратно в Штормград, узнав, что я затосковал по былым денькам.$B$BХорошо, что мне удалось оказать вам хотя бы небольшую услугу во время вашего пребывания в Менетиле. Если еще что-нибудь понадобится, просто попросите.','Он ускользнул? Он выглядел немного подозрительно, когда наблюдал за нами.','Победите Яна Тапоке.','Вернитесь к Михаилу в таверну "Большая вода"в Гавани Менетилов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, вас послал Иллинг? О, это повод десятикратно умножить мое гостеприимство! Просите всего, чего пожелаете, постараюсь выполнить любую вашу просьбу!$b$BХм-м, Проныра, говорите? Не скажу, что мне знакомо это имя, но постараюсь что-нибудь разведать...$B$B$n, не оборачивайтесь прямо сейчас, но вон тот господин около двери слишком внимательно смотрит на нас и прислушивается к нашему разговору. На вашем месте я бы попробовал изловить его прежде, чем он уйдет отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Перехватите Яна Тапоке до его ухода и вернитесь к Михаилу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поймали его, да? Отлично! Знаете, а ведь это и есть тот самый Проныра! Я и сам удивился.$B$BДа, не думал я, что буду так скучать по всяким тайным расследованиям и азартным погоням. Верно говорят: сколько волка ни корми... Только не обмолвитесь про это Эллингу – он наверняка потащит меня обратно в Штормград, узнав, что я затосковал по былым денькам.$B$BХорошо, что мне удалось оказать вам хотя бы небольшую услугу во время вашего пребывания в Менетиле. Если еще что-нибудь понадобится, просто попросите.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он ускользнул? Он выглядел немного подозрительно, когда наблюдал за нами.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победите Яна Тапоке.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Михаилу в таверну "Большая вода"в Гавани Менетилов.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1250,'Пропавший дипломат','Братство Справедливости не столько мне платит, чтобы за них умирать. Они похитили короля. Да, настоящего короля Штормграда, а не какого-то там дипломата. Он направлялся в Терамор, чтобы побеседовать с Джайной Праудмур, это большая тайна и дело тоже нешуточное. Но тут встряло братство, у них был свой осведомитель.$B$BВ мои задачи входило только взять их человека на борт королевского корабля, когда он стоял у пристани. Парня звали Хендел, клянусь, это все, что я знаю!','Поговорите с Михаилом в Болотине.','КОРОЛЬ?! В смысле... король? Настоящий король? Вы шутите? Вы же не имеете в виду, что вы разыскиваете похитителей короля?! Я даже не в курсе, что он пропал. Теперь ясно, почему сейчас в Штормграде всем заправляет его сын.$B$BЯ прямо сейчас напишу Эллингу. Он должен знать, что вы встали на след.$B$BМне и в голову не приходило, что Джан может предать наш Штормград за деньги, пусть и немалые. Даже у вора должна быть честь!$B$BТеперь главное – найти этого Хендела – думаю, тут я могу помочь...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Братство Справедливости не столько мне платит, чтобы за них умирать. Они похитили короля. Да, настоящего короля Штормграда, а не какого-то там дипломата. Он направлялся в Терамор, чтобы побеседовать с Джайной Праудмур, это большая тайна и дело тоже нешуточное. Но тут встряло братство, у них был свой осведомитель.$B$BВ мои задачи входило только взять их человека на борт королевского корабля, когда он стоял у пристани. Парня звали Хендел, клянусь, это все, что я знаю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Михаилом в Болотине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','КОРОЛЬ?! В смысле... король? Настоящий король? Вы шутите? Вы же не имеете в виду, что вы разыскиваете похитителей короля?! Я даже не в курсе, что он пропал. Теперь ясно, почему сейчас в Штормграде всем заправляет его сын.$B$BЯ прямо сейчас напишу Эллингу. Он должен знать, что вы встали на след.$B$BМне и в голову не приходило, что Джан может предать наш Штормград за деньги, пусть и немалые. Даже у вора должна быть честь!$B$BТеперь главное – найти этого Хендела – думаю, тут я могу помочь...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1251,'[DEPRECATED]The Black Shield','Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остове камина – только это и осталось от таверны "Последний привал".$b$bЩит можно снять.','Принесите почерневший железный щит Крогу в Деревню Гиблотопь.','Люди всегда отличались странными вкусами в области украшательства. Но на кой вешать над камином простой металлический щит? Может, его повесили туда те, кто спалил таверну?\n\nПредупреждение? Угроза?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Black Shield',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остове камина – только это и осталось от таверны "Последний привал".$b$bЩит можно снять.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите почерневший железный щит Крогу в Деревню Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Люди всегда отличались странными вкусами в области украшательства. Но на кой вешать над камином простой металлический щит? Может, его повесили туда те, кто спалил таверну?\n\nПредупреждение? Угроза?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1252,'[DEPRECATED]Lieutenant Paval Reethe','Солнечный зайчик блеснул в глаза из-под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.$b$bПод якорем выбито имя владельца: "Лейтенант Павал Рит".','Принесите бляху Рита капитану Гаррану Ваймсу в Терамор.','День, когда мне приносят бляхи погибших стражей, светлым не назовешь.$B$BИногда они гибнут в битве, и мне приходится сообщать об их участи семье и близким... Иногда мы так и не знаем, что с ними сталось. А иногда знаем, и это еще хуже...','Ну как успехи с этой таверной? Удалось что-нибудь найти?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Lieutenant Paval Reethe',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Солнечный зайчик блеснул в глаза из-под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.$b$bПод якорем выбито имя владельца: "Лейтенант Павал Рит".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите бляху Рита капитану Гаррану Ваймсу в Терамор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','День, когда мне приносят бляхи погибших стражей, светлым не назовешь.$B$BИногда они гибнут в битве, и мне приходится сообщать об их участи семье и близким... Иногда мы так и не знаем, что с ними сталось. А иногда знаем, и это еще хуже...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как успехи с этой таверной? Удалось что-нибудь найти?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1253,'[DEPRECATED]The Black Shield','Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остатках камина – только это и осталось от таверны "Последний привал".$b$bЩит можно снять.','Принесите почерневший железный щит капитану Гаррану Ваймсу в Терамор.','Хмм... Я в устройстве оружия и доспехов не разбираюсь, я ими пользуюсь.$B$BЩит как щит, разве что огнем опалило.','Ты выяснил, что произошло с этой таверной?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Black Shield',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Железный щит, почерневший в пламени бушевавшего здесь пожара, висит на остатках камина – только это и осталось от таверны "Последний привал".$b$bЩит можно снять.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите почерневший железный щит капитану Гаррану Ваймсу в Терамор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм... Я в устройстве оружия и доспехов не разбираюсь, я ими пользуюсь.$B$BЩит как щит, разве что огнем опалило.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты выяснил, что произошло с этой таверной?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1258,'...с крабами','Еще один компонент моего нового рецепта – мясо гигантского краба. Крабы, которые водятся в Пылевых топях, – их называют костлявыми скальными крабами – отлично подойдут!$b$bКлешни этих крабов – важный элемент украшения блюда, поэтому они мне нужны целые и непоцарапанные. К сожалению, у краба всего две клешни, а то и одна, а мне для моих кулинарных экспериментов их нужно гораздо больше.$b$bТак что отправляйся на охоту в скалы, на берегах Терамора!','Принесите 12 безупречных крабьих клешней Моргану Штерну в Терамор.','Мои кулинарные эксперименты с языками глинистых черепах проходят весьма успешно. Надеюсь, твоя охота на крабов не менее удачна?','Вернитесь к Моргану Штерну на Остров Терамор, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','...с крабами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще один компонент моего нового рецепта – мясо гигантского краба. Крабы, которые водятся в Пылевых топях, – их называют костлявыми скальными крабами – отлично подойдут!$b$bКлешни этих крабов – важный элемент украшения блюда, поэтому они мне нужны целые и непоцарапанные. К сожалению, у краба всего две клешни, а то и одна, а мне для моих кулинарных экспериментов их нужно гораздо больше.$b$bТак что отправляйся на охоту в скалы, на берегах Терамора!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 безупречных крабьих клешней Моргану Штерну в Терамор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мои кулинарные эксперименты с языками глинистых черепах проходят весьма успешно. Надеюсь, твоя охота на крабов не менее удачна?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моргану Штерну на Остров Терамор, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1259,'[DEPRECATED]Lieutenant Paval Reethe','Лейтенант Павал Рит? Не припоминаю такого имени. Лучше всего вам будет поговорить с адъютантом Тезораном. У него хранятся все записи о тераморских стражниках – от их имен до предпочитаемого вооружения.$B$BУж он-то расскажет вам об этом Павале Рите.','Поговорите о Рите с адъютантом Тезораном в Тераморе.','Здравствуй, $N. Так тебе нужна информация об одном из нас? Как его бишь, Рит?$B$BСейчас проверю по своим записям.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Lieutenant Paval Reethe',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лейтенант Павал Рит? Не припоминаю такого имени. Лучше всего вам будет поговорить с адъютантом Тезораном. У него хранятся все записи о тераморских стражниках – от их имен до предпочитаемого вооружения.$B$BУж он-то расскажет вам об этом Павале Рите.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите о Рите с адъютантом Тезораном в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуй, $N. Так тебе нужна информация об одном из нас? Как его бишь, Рит?$B$BСейчас проверю по своим записям.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1260,'[DEPRECATED]Morgan Stern','Я составляю новое меню для ресторана. Сельская кухня с болотным душком. Думаю, посетителям "Печального отшельника" понравится!$b$bЯ послал своего племянника Моргана в Терамор, город на краю Пылевых топей. Там он собирает местные кулинарные рецепты, и мне хотелось бы знать, как его успехи.$b$bДолог путь до Терамора, и для меня тяжеловат. Но я думаю, что $Gтакой молодой:такая молодая:c; |3-6($c) с радостью ухватится за возможность совершить подобное путешествие.','Поговорите с Морганом Штерном в Тераморе.','А! Так вас послал мой дядя?$B$BНу что ж, я тут собирал для него рецепты и добился определенных успехов, но мне нужна помощь. $B$BНадеюсь, вы не боитесь ноги промочить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Morgan Stern',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я составляю новое меню для ресторана. Сельская кухня с болотным душком. Думаю, посетителям "Печального отшельника" понравится!$b$bЯ послал своего племянника Моргана в Терамор, город на краю Пылевых топей. Там он собирает местные кулинарные рецепты, и мне хотелось бы знать, как его успехи.$b$bДолог путь до Терамора, и для меня тяжеловат. Но я думаю, что $Gтакой молодой:такая молодая:c; |3-6($c) с радостью ухватится за возможность совершить подобное путешествие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Морганом Штерном в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А! Так вас послал мой дядя?$B$BНу что ж, я тут собирал для него рецепты и добился определенных успехов, но мне нужна помощь. $B$BНадеюсь, вы не боитесь ноги промочить?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1261,'Марг говорит','Ах ты, проклятый грязнокраб! Ты меня не достанешь! Ой, да я ж покойник! Видать, он все-таки достал меня.$b$bА как же моя миссия?! Ты, $n, $Gдолжен:должна; закончить ее. Я наблюдал за силами Альянса, высадившимися на берегу возле Терамора. На одном из солдат была подвеска, на которой было столько драгоценных камней, что не всякий вождь может себе позволить.$b$bТой ночью я пробрался в лагерь и украл эту подвеску. Но когда я возвращался в свой лагерь, этот проклятый грязнокраб прикончил меня!$b$b$n, ты $Gдолжен:должна; найти эту тварь и вернуть подвеску.','Принесите изукрашенную Подвеску Назиру в Деревню Гиблотопь.','Ты выяснил, что случилось с Маргом?','Вернитесь к Назиру Кровавому Копью в деревню Гиблотопь, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Марг говорит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах ты, проклятый грязнокраб! Ты меня не достанешь! Ой, да я ж покойник! Видать, он все-таки достал меня.$b$bА как же моя миссия?! Ты, $n, $Gдолжен:должна; закончить ее. Я наблюдал за силами Альянса, высадившимися на берегу возле Терамора. На одном из солдат была подвеска, на которой было столько драгоценных камней, что не всякий вождь может себе позволить.$b$bТой ночью я пробрался в лагерь и украл эту подвеску. Но когда я возвращался в свой лагерь, этот проклятый грязнокраб прикончил меня!$b$b$n, ты $Gдолжен:должна; найти эту тварь и вернуть подвеску.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите изукрашенную Подвеску Назиру в Деревню Гиблотопь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты выяснил, что случилось с Маргом?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Назиру Кровавому Копью в деревню Гиблотопь, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1262,'Сообщение для Зора','Странно, что украденная Маргом была у простого солдата. Возможно ее владелец маскировался, или, что вероятнее, солдаты сами ее стащили. $B$BЧто бы там ни было, эта подвеска принадлежала лицу благородного происхождения, и мы должны найти ее хозяина, если хотим разрешить эту загадку.$b$bОтнеси эту подвеску Зору Одинокое Дерево в Оргриммар. Он хорошо разбирается в интригах Альянса и, возможно, он в курсе, если эта подвеска известна в Штормграде.','Отнесите изукрашенную подвеску Зору Одинокому Дереву в Оргриммар.','Ты $gшел:шла; сюда аж из Деревни Гиблотопь, что в Пыльной трясине? Как там поживает Назир, как его дела?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сообщение для Зора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Странно, что украденная Маргом была у простого солдата. Возможно ее владелец маскировался, или, что вероятнее, солдаты сами ее стащили. $B$BЧто бы там ни было, эта подвеска принадлежала лицу благородного происхождения, и мы должны найти ее хозяина, если хотим разрешить эту загадку.$b$bОтнеси эту подвеску Зору Одинокое Дерево в Оргриммар. Он хорошо разбирается в интригах Альянса и, возможно, он в курсе, если эта подвеска известна в Штормграде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите изукрашенную подвеску Зору Одинокому Дереву в Оргриммар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gшел:шла; сюда аж из Деревни Гиблотопь, что в Пыльной трясине? Как там поживает Назир, как его дела?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1263,'Сожженная Таверна') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сожженная Таверна',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1264,'Пропавший дипломат','В начале каждого месяца стражи бухты Кул-Тираса получают жалованье и отправляются прочь из Терамора в отпуск. Многие из них приходят сюда – выпить, гульнуть, пообщаться с женщинами. Одна из таких компаний регулярно приходит в эту таверну. Мне кажется, что и этот Хендел был среди них.$B$BКомандир Самаул из Терамора может вам помочь в поисках Хендела, если тот до сих пор там. Самаул всецело верен леди Джайне, но если вы упомянете при нем имя Иллинга, то его помощь может оказаться весьма... сдержанной.','Найдите командира Самаула в Пылевых топях.','Рад встрече, $n. Я – командир Самаул, состою на службе в гвардии леди Джайны Праудмур в Тераморе.$B$BХотя я немного занят, вы можете задавать мне любые вопросы, которые вас интересуют. Не сочтите за повод для обиды, но я попрошу вас высказаться по возможности лаконично.$B$BНадеюсь, что вы проявите должную осторожность, если соберетесь за пределы города. Там, снаружи – огры, орки и мурлоки, а в южной части болота обитают черные драконы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В начале каждого месяца стражи бухты Кул-Тираса получают жалованье и отправляются прочь из Терамора в отпуск. Многие из них приходят сюда – выпить, гульнуть, пообщаться с женщинами. Одна из таких компаний регулярно приходит в эту таверну. Мне кажется, что и этот Хендел был среди них.$B$BКомандир Самаул из Терамора может вам помочь в поисках Хендела, если тот до сих пор там. Самаул всецело верен леди Джайне, но если вы упомянете при нем имя Иллинга, то его помощь может оказаться весьма... сдержанной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите командира Самаула в Пылевых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад встрече, $n. Я – командир Самаул, состою на службе в гвардии леди Джайны Праудмур в Тераморе.$B$BХотя я немного занят, вы можете задавать мне любые вопросы, которые вас интересуют. Не сочтите за повод для обиды, но я попрошу вас высказаться по возможности лаконично.$B$BНадеюсь, что вы проявите должную осторожность, если соберетесь за пределы города. Там, снаружи – огры, орки и мурлоки, а в южной части болота обитают черные драконы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1265,'Пропавший дипломат','Хендел? Да, я его знаю, но почему вас интересуют мои солдаты?$B$BИллинг отправил вас разыскать его? Звучит как-то странно. Эллинг не послал бы вас ко мне, если бы все было в порядке. Вы можете хранить свои секреты сколько угодно, только имейте в виду: мой долг – охранять эти земли. Если ваша деятельность может нарушить порядок, лучше сообщите заранее.$B$BДумаю, что Хендела вы найдете в первой по счету от Терамора башне. Будьте осторожны.','Обыщите сторожевой пост, чтобы найти следы рядового Хендела.','Человека, известного вам как Хендел, здесь нет. Все остальное, что можно узнать от леди Праудмур, я думаю, вы уже знаете. Она просила меня найти вас и оказать вам помощь в расследовании. Если вы готовы принять мои услуги, я сообщу вам, где можно найти рядового Хендела. Вдвоем мы сможем предать его в руки правосудия.','Да, $N?','Обследовать сторожевой пост','Вернитесь к верховному магу Тервошу в Пылевые топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хендел? Да, я его знаю, но почему вас интересуют мои солдаты?$B$BИллинг отправил вас разыскать его? Звучит как-то странно. Эллинг не послал бы вас ко мне, если бы все было в порядке. Вы можете хранить свои секреты сколько угодно, только имейте в виду: мой долг – охранять эти земли. Если ваша деятельность может нарушить порядок, лучше сообщите заранее.$B$BДумаю, что Хендела вы найдете в первой по счету от Терамора башне. Будьте осторожны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите сторожевой пост, чтобы найти следы рядового Хендела.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Человека, известного вам как Хендел, здесь нет. Все остальное, что можно узнать от леди Праудмур, я думаю, вы уже знаете. Она просила меня найти вас и оказать вам помощь в расследовании. Если вы готовы принять мои услуги, я сообщу вам, где можно найти рядового Хендела. Вдвоем мы сможем предать его в руки правосудия.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Обследовать сторожевой пост',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Тервошу в Пылевые топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1266,'Пропавший дипломат','Рядовой Хендел находится к западу отсюда, в составе гвардии, охраняющей тераморских разведчиков во время отдыха. Они пытаются выяснить местоположение деревни Гиблотопь, базы Орды, а заодно и приглядывают за нашими границами.$B$BВы найдете его без труда, просто поищите в палатках у дороги.$B$BУ меня есть и другие дела, но я догоню вас так быстро, как смогу. При необходимости вы сможете найти меня в башне леди Праудмур.','Найдите рядового Хендела в Пылевых топях.','Добрый день. Это опасное место для горожанина. Если вы цените свою жизнь, не стоит находиться здесь слишком долго.$B$BЗадавайте вопросы быстро, попробую вам помочь. Только смотрите по сторонам, не покажутся ли огры. По слухам, поблизости база Орды. Разведчики пытаются найти ее, но это дело небыстрое. Мы еще не добились успеха.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рядовой Хендел находится к западу отсюда, в составе гвардии, охраняющей тераморских разведчиков во время отдыха. Они пытаются выяснить местоположение деревни Гиблотопь, базы Орды, а заодно и приглядывают за нашими границами.$B$BВы найдете его без труда, просто поищите в палатках у дороги.$B$BУ меня есть и другие дела, но я догоню вас так быстро, как смогу. При необходимости вы сможете найти меня в башне леди Праудмур.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите рядового Хендела в Пылевых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добрый день. Это опасное место для горожанина. Если вы цените свою жизнь, не стоит находиться здесь слишком долго.$B$BЗадавайте вопросы быстро, попробую вам помочь. Только смотрите по сторонам, не покажутся ли огры. По слухам, поблизости база Орды. Разведчики пытаются найти ее, но это дело небыстрое. Мы еще не добились успеха.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1267,'Пропавший дипломат','Поговорите с леди Джайной Праудмур в Пылевых топях.','Сначала позвольте вас, $N, поблагодарить за все, что вы уже сделали. Вы оказали неоценимую услугу моим людям и всем обитателям Штормграда. Жаль, что наше знакомство не состоялось при более благоприятных обстоятельствах.$B$BНадеюсь, вы понимаете, что я не имею возможности публично выразить вам свою признательность, но знайте, что она поистине безгранична...$B$BВо время следующего визита в Терамор разыщите меня и я сделаю для вас все, что смогу.$B$B$N, позвольте еще раз поблагодарить вас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с леди Джайной Праудмур в Пылевых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сначала позвольте вас, $N, поблагодарить за все, что вы уже сделали. Вы оказали неоценимую услугу моим людям и всем обитателям Штормграда. Жаль, что наше знакомство не состоялось при более благоприятных обстоятельствах.$B$BНадеюсь, вы понимаете, что я не имею возможности публично выразить вам свою признательность, но знайте, что она поистине безгранична...$B$BВо время следующего визита в Терамор разыщите меня и я сделаю для вас все, что смогу.$B$B$N, позвольте еще раз поблагодарить вас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1268,'[DEPRECATED]Suspicious Hoofprints','Цепочка следов уходит от все еще дымящегося остова таверны "Последний привал". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчетливо.','Доложите о подозрительных следах возле таверны "Последний привал" Крогу из деревни Гиблотопь.','Следы копыт... Это может быть иглогрив, или даже кентавр. То, что они пришли в Степи, что-то да значит, и, сдается мне, они вполне способны сжечь таверну.\n\nК тому же кто бы это ни был, они не только сожгли здание, жена и детеныш владельца были убиты. Плохо дело... \n\nЛадно, я пошлю Кагоро посмотреть куда ведут следы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Suspicious Hoofprints',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Цепочка следов уходит от все еще дымящегося остова таверны "Последний привал". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчетливо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о подозрительных следах возле таверны "Последний привал" Крогу из деревни Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Следы копыт... Это может быть иглогрив, или даже кентавр. То, что они пришли в Степи, что-то да значит, и, сдается мне, они вполне способны сжечь таверну.\n\nК тому же кто бы это ни был, они не только сожгли здание, жена и детеныш владельца были убиты. Плохо дело... \n\nЛадно, я пошлю Кагоро посмотреть куда ведут следы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1269,'[DEPRECATED]Lieutenant Paval Reethe','Солнечный зайчик блеснул в глаза из под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.$b$bПод якорем выбито имя владельца: "Лейтенант Павал Рит".','Принесите бляху Рита Крогу в деревню Гиблотопь.','Я знаю этого человека, Павала Рита. Жалкий даже по меркам собственного племени. Покинул своих товарищей и теперь скрывается в лесу. \n\nЯ послал Огрона выследить его. Некоторые подозревают, что он крал припасы. Я видел что Огрон направляется на юго-восток.','Удалось найти хоть какие-то намеки на то. Что случилось в таверне "Последний привал"?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Lieutenant Paval Reethe',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Солнечный зайчик блеснул в глаза из под обломков. Вы достаете из-под мусора бляху с золотым якорем на белой эмали – символом Терамора.$b$bПод якорем выбито имя владельца: "Лейтенант Павал Рит".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите бляху Рита Крогу в деревню Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю этого человека, Павала Рита. Жалкий даже по меркам собственного племени. Покинул своих товарищей и теперь скрывается в лесу. \n\nЯ послал Огрона выследить его. Некоторые подозревают, что он крал припасы. Я видел что Огрон направляется на юго-восток.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти хоть какие-то намеки на то. Что случилось в таверне "Последний привал"?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1270,'Побег Вонючки','Ура! Наконец-то нашелся кто-то, кто не хочет меня съесть!$B$BНе могу отбиться от тутошнего зверья, а ты, $gпарень:подруга;, как раз мне в этом и поможешь. Гоблину из Кабестана по кличке Мебок Миззрикс нужны листья болотного боба для зелья или еще какой надобности, – меня это, честно говоря, не колышет: он неплохо платит, а я неплохо знаю болота, потому и впрягся.$b$bВот только не успел я еще найти эти листья, как меня уже окружили. Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать для Мебока эти листья.','Сопроводите "Вонючку" Игнаца, затем пообщайтесь с Мебоком Миззриксом в Кабестане.','Помогите Вонючке найти листья болотного боба.','Вернитесь к Мебоку Миззриксу в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег Вонючки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ура! Наконец-то нашелся кто-то, кто не хочет меня съесть!$B$BНе могу отбиться от тутошнего зверья, а ты, $gпарень:подруга;, как раз мне в этом и поможешь. Гоблину из Кабестана по кличке Мебок Миззрикс нужны листья болотного боба для зелья или еще какой надобности, – меня это, честно говоря, не колышет: он неплохо платит, а я неплохо знаю болота, потому и впрягся.$b$bВот только не успел я еще найти эти листья, как меня уже окружили. Мне до зарезу необходим кто-то кто поможет выбраться отсюда и прикроет спину, пока я буду искать для Мебока эти листья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите "Вонючку" Игнаца, затем пообщайтесь с Мебоком Миззриксом в Кабестане.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помогите Вонючке найти листья болотного боба.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мебоку Миззриксу в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1271,'Праздник в "Печальном отшельнике"','Мой племянник сказал, что ты $Gпомог:помогла; ему с его поисками в Пыльной трясине, а заодно и вытащил его компаньона из неслабой передряги. Мы, Штерны, держимся друг дружки и не забываем наших друзей!$B$BТак что мой руки, $N, сегодня пируем в твою честь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Праздник в "Печальном отшельнике"',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой племянник сказал, что ты $Gпомог:помогла; ему с его поисками в Пыльной трясине, а заодно и вытащил его компаньона из неслабой передряги. Мы, Штерны, держимся друг дружки и не забываем наших друзей!$B$BТак что мой руки, $N, сегодня пируем в твою честь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1272,'Найти Рита <CHANGE INTO GOSSIP>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Рита <CHANGE INTO GOSSIP>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1273,'[DEPRECATED]Questioning Reethe','Это было непросто, но я все-таки нашел этот Рит. Неплохо он прятаться... Для человек. $b$bОгрон боится, что человек свихнуться, – слишком много времени на болоте, Твоя идти с Огрон и спрашивать человека все, что хотеть.','Пойдите с Огроном и поговорите с Ритом, потом вернитесь к Крогу в Деревню Гиблотопь.','Пфф. Это хорошо, что Рит больше не будет прятаться на болоте, но это плохо, что люди такие хрупкие существа, что могут помереть от одной маленькой стрелы.\n\nСдается мне, что мы зашли в тупик и нужно поискать разгадку где-нибудь еще.','Вы нашли Рита?','Вместе с Огроном допросите Рита.','Вернитесь к Крогу в Пылевые топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Questioning Reethe',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это было непросто, но я все-таки нашел этот Рит. Неплохо он прятаться... Для человек. $b$bОгрон боится, что человек свихнуться, – слишком много времени на болоте, Твоя идти с Огрон и спрашивать человека все, что хотеть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пойдите с Огроном и поговорите с Ритом, потом вернитесь к Крогу в Деревню Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пфф. Это хорошо, что Рит больше не будет прятаться на болоте, но это плохо, что люди такие хрупкие существа, что могут помереть от одной маленькой стрелы.\n\nСдается мне, что мы зашли в тупик и нужно поискать разгадку где-нибудь еще.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы нашли Рита?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Вместе с Огроном допросите Рита.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крогу в Пылевые топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1274,'Пропавший дипломат','Простите, $gсэр:мадам;. Епископ Делавей попросил меня разыскать любителя приключений, который мог бы помочь ему, оказав услугу весьма деликатного свойства.$B$BЕсли вы без лишнего шума проберетесь в крепость Штормграда и обратитесь к епископу, он наверняка примет вашу помощь. Прошу вас, храните это в тайне, ибо все это дело большой важности.','Найдите епископа Делавея в крепости Штормграда.','Здравствуйте, $n. Я – епископ Делавей.$B$BДайте-ка, я угадаю, почему вы здесь! Наверняка потому, что откликнулись на просьбу юного Томаса, который предложил вам оказать мне услугу. Он всегда стремится помочь мне.$B$BБоюсь, я еще не успел все сформулировать, так что простите мне некоторую невнятность изложения... И, прошу вас, храните все это в тайне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Простите, $gсэр:мадам;. Епископ Делавей попросил меня разыскать любителя приключений, который мог бы помочь ему, оказав услугу весьма деликатного свойства.$B$BЕсли вы без лишнего шума проберетесь в крепость Штормграда и обратитесь к епископу, он наверняка примет вашу помощь. Прошу вас, храните это в тайне, ибо все это дело большой важности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите епископа Делавея в крепости Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуйте, $n. Я – епископ Делавей.$B$BДайте-ка, я угадаю, почему вы здесь! Наверняка потому, что откликнулись на просьбу юного Томаса, который предложил вам оказать мне услугу. Он всегда стремится помочь мне.$B$BБоюсь, я еще не успел все сформулировать, так что простите мне некоторую невнятность изложения... И, прошу вас, храните все это в тайне.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1275,'Исследование порчи','Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора?$b$bЯ боюсь, что эльфы крови могут претерпеть такую же трансформацию. Азерот не может позволить себе породить еще одну расу злобных монстров.$B$BЯ хотел бы изучить ствол мозга сатиров и наг, чтобы понять, на что обрекают себя Син\'дорай. И сатиров, и наг можно найти в Непроглядной Пучине, на западе.','Релвин Тень Звезды в лагере у Непроглядной Пучины хочет, чтобы вы принесли ему 8 оскверненных стволов мозга.','Вы проделали долгий путь и, несомненно, столкнулись с огромной опасностью.$B$BВаши действия были самоотверженными. Ваша помощь – на благо всему Азероту. Я благодарю вас, $n, за все, что вы сделали.$B$BА теперь прошу меня простить, но мне нужно работать...','Когда у меня будет достачно образцов для изучения, я смогу начать настоящее исследование. Имея оскверненные стволы мозга как сатиров, так и нагов из Непроглядной Пучины, я смогу сопоставить их мутации.$B$BБыть может, полученные знания помогут нам не допустить окончательного перехода на сторону зла эльфов крови.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование порчи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора?$b$bЯ боюсь, что эльфы крови могут претерпеть такую же трансформацию. Азерот не может позволить себе породить еще одну расу злобных монстров.$B$BЯ хотел бы изучить ствол мозга сатиров и наг, чтобы понять, на что обрекают себя Син\'дорай. И сатиров, и наг можно найти в Непроглядной Пучине, на западе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Релвин Тень Звезды в лагере у Непроглядной Пучины хочет, чтобы вы принесли ему 8 оскверненных стволов мозга.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы проделали долгий путь и, несомненно, столкнулись с огромной опасностью.$B$BВаши действия были самоотверженными. Ваша помощь – на благо всему Азероту. Я благодарю вас, $n, за все, что вы сделали.$B$BА теперь прошу меня простить, но мне нужно работать...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда у меня будет достачно образцов для изучения, я смогу начать настоящее исследование. Имея оскверненные стволы мозга как сатиров, так и нагов из Непроглядной Пучины, я смогу сопоставить их мутации.$B$BБыть может, полученные знания помогут нам не допустить окончательного перехода на сторону зла эльфов крови.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1276,'[DEPRECATED]The Black Shield','А, вспомнил! Мозарн – знаменитый кузнец из Громового Утеса. Я же помню, что слышал это имя прежде!$b$bЕсли мне не изменяет память, Служители Земли наградили меня оружием его работы, хорошее было оружие.$b$bВозможно, он расскажет тебе больше о щите, вышедшем из его рук.$b$bЯ не уверен, что эта информация важна, но, поскольку мы так и не знаем ничего о Рите, пренебрегать ей было бы неразумно.','Покажите потемневший железный щит Мозарну из Громового Утеса.','Привет, $C. Я могу чем-то помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Black Shield',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, вспомнил! Мозарн – знаменитый кузнец из Громового Утеса. Я же помню, что слышал это имя прежде!$b$bЕсли мне не изменяет память, Служители Земли наградили меня оружием его работы, хорошее было оружие.$b$bВозможно, он расскажет тебе больше о щите, вышедшем из его рук.$b$bЯ не уверен, что эта информация важна, но, поскольку мы так и не знаем ничего о Рите, пренебрегать ей было бы неразумно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите потемневший железный щит Мозарну из Громового Утеса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $C. Я могу чем-то помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1277,'<nyi> <TXT> Следы кентавров.','Kагоро выяснил, что эти следы кентавров принадлежат нескольким идиотам из Мародона','Избейте их.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<nyi> <TXT> Следы кентавров.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Kагоро выяснил, что эти следы кентавров принадлежат нескольким идиотам из Мародона',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Избейте их.',`objectives_loc8`);
