INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1281,'Песня Джима <CHANGE TO GOSSIP>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Песня Джима <CHANGE TO GOSSIP>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1282,'[DEPRECATED]They Call Him Smiling Jim','Ничего не могу с собой поделать, мне так жаль старину Джима... Он не всегда был таким... Когда-то он держал таверну на болотах, дивное было местечко.$b$bСлушай, я не в настроении говорить об этом. Если тебе нужна информация, поговори с капитаном Ваймсом. Он сидит на верхнем этаже в Цитадели, знаешь, эти большие казармы, к востоку от башни леди Джайны.','Поговорите с капитаном Гарраном Ваймсом на верхнем этаже Цитадели.','Настоящее его имя – Джеймс Хьяль. Он открыл таверну на краю Степей, хотел сделать уютное местечко для отдыха путешественников.$B$BМожет, он слишком многого хотел, но некоторое время дела в таверне шли хорошо. Потом мы потеряли контроль за дорогами через болота, и здесь стали шататься огры, а Джеймс был слишком упрям, он не захотел бросить свое детище ради безопасности. Теперь таверна "Последний привал" сгорела до основания. Мы пытались разобраться, но особых успехов не достигли, поэтому твою помощь примем с благодарностью. Если хочешь помочь – посмотри, вдруг что найдешь на развалинах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]They Call Him Smiling Jim',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ничего не могу с собой поделать, мне так жаль старину Джима... Он не всегда был таким... Когда-то он держал таверну на болотах, дивное было местечко.$b$bСлушай, я не в настроении говорить об этом. Если тебе нужна информация, поговори с капитаном Ваймсом. Он сидит на верхнем этаже в Цитадели, знаешь, эти большие казармы, к востоку от башни леди Джайны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Гарраном Ваймсом на верхнем этаже Цитадели.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Настоящее его имя – Джеймс Хьяль. Он открыл таверну на краю Степей, хотел сделать уютное местечко для отдыха путешественников.$B$BМожет, он слишком многого хотел, но некоторое время дела в таверне шли хорошо. Потом мы потеряли контроль за дорогами через болота, и здесь стали шататься огры, а Джеймс был слишком упрям, он не захотел бросить свое детище ради безопасности. Теперь таверна "Последний привал" сгорела до основания. Мы пытались разобраться, но особых успехов не достигли, поэтому твою помощь примем с благодарностью. Если хочешь помочь – посмотри, вдруг что найдешь на развалинах.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1283,'Пожар в "Последнем привале"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожар в "Последнем привале"',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1284,'[DEPRECATED]Suspicious Hoofprints','Цепочка следов уходит от все еще дымящегося остова таверны "Последний привал". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчетливо.','Доложите о подозрительных следах возле таверны "Последний привал" капитану Гаррану Ваймсу из Терамора.','Следы копыт, говоришь? В последнее время в этих краях зашевелились кентавры. Наши разведчики во время вылазки в Степи заметили несколько их лагерей и поселений.$B$BЯ пошлю одного из наших охотников, Фальграна Гастила, посмотреть, куда ведут эти следы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Suspicious Hoofprints',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Цепочка следов уходит от все еще дымящегося остова таверны "Последний привал". В отличие от других следов, еле заметных на мягкой болотистой почве, эти видны отчетливо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о подозрительных следах возле таверны "Последний привал" капитану Гаррану Ваймсу из Терамора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Следы копыт, говоришь? В последнее время в этих краях зашевелились кентавры. Наши разведчики во время вылазки в Степи заметили несколько их лагерей и поселений.$B$BЯ пошлю одного из наших охотников, Фальграна Гастила, посмотреть, куда ведут эти следы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1285,'[DEPRECATED]Daelin\'s Men','Реддон... Редпат... А! Вот он! Лейтененат Павал Рит.$b$bВсупил в ряды тераморской стражи вместе с остальными новобранцами, которые пришли из-за моря вместе с леди Праудмур. Зачислен в морские пехотинцы Кул-Тираса в возрасте шестнадцати лет. Отличная служба, поощрения...$b$bЧислится пропавшим без вести.','Вернитесь с информацией о Рите к капитану Гаррану Ваймсу в Терамор.','Пропал без вести? В переводе с языка Тезорана, это значит – предатель.$B$BНе сомневаюсь, что это один из тех глупцов, слепо преданных адмиралу Даэлину и готовых ради него предать собственную страну. Забавно, правда? Дезертиры обвиняют нас в предательстве дела Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Daelin\'s Men',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Реддон... Редпат... А! Вот он! Лейтененат Павал Рит.$b$bВсупил в ряды тераморской стражи вместе с остальными новобранцами, которые пришли из-за моря вместе с леди Праудмур. Зачислен в морские пехотинцы Кул-Тираса в возрасте шестнадцати лет. Отличная служба, поощрения...$b$bЧислится пропавшим без вести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь с информацией о Рите к капитану Гаррану Ваймсу в Терамор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пропал без вести? В переводе с языка Тезорана, это значит – предатель.$B$BНе сомневаюсь, что это один из тех глупцов, слепо преданных адмиралу Даэлину и готовых ради него предать собственную страну. Забавно, правда? Дезертиры обвиняют нас в предательстве дела Альянса.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1286,'[DEPRECATED]The Deserters','Удержаться здесь, на болотах, было нелегко. Но, благодаря решимости и отваге, мы смогли возвести несколько оборонительных сторожевых башен в округе.$b$bПо последним донесениям наших разведчиков, группа дезертиров засела в Разрушенной башне, к юго-востоку от таверны. $B$BЗа главного у них, кажется, Балос Хакен. Посмотрим, может удастся получить от него какие-то сведения. $B$BНо будь с ним осторожнее, $n, он – тертый вояка.','Расспросите о Рите Балоса Хакена и его дезертиров в Пылевых топях.','Тебя Ваймс прислал? Вечно он спихивает на других всю грязную работу...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Deserters',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Удержаться здесь, на болотах, было нелегко. Но, благодаря решимости и отваге, мы смогли возвести несколько оборонительных сторожевых башен в округе.$b$bПо последним донесениям наших разведчиков, группа дезертиров засела в Разрушенной башне, к юго-востоку от таверны. $B$BЗа главного у них, кажется, Балос Хакен. Посмотрим, может удастся получить от него какие-то сведения. $B$BНо будь с ним осторожнее, $n, он – тертый вояка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расспросите о Рите Балоса Хакена и его дезертиров в Пылевых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя Ваймс прислал? Вечно он спихивает на других всю грязную работу...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1287,'[DEPRECATED]The Deserters','Рит? Этот трус?$b$bМы вышвырнули его из лагеря, потому что он настаивал на налете на деревню огров Гиблотопь, чтобы пограбить их запасы. Нас не так много, чтобы рассчитывать справиться с этими безмозглыми тварями. $b$bОн настолько часто зарывался, что мы решили, что с нас хватит, и прогнали его.$b$bВот, я помог тебе, почему бы теперь тебе не забыть о нашей встрече?','Поговорите о Рите с капитаном Гарраном Ваймсом в Тераморе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Deserters',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рит? Этот трус?$b$bМы вышвырнули его из лагеря, потому что он настаивал на налете на деревню огров Гиблотопь, чтобы пограбить их запасы. Нас не так много, чтобы рассчитывать справиться с этими безмозглыми тварями. $b$bОн настолько часто зарывался, что мы решили, что с нас хватит, и прогнали его.$b$bВот, я помог тебе, почему бы теперь тебе не забыть о нашей встрече?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите о Рите с капитаном Гарраном Ваймсом в Тераморе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1288,'Донесение Ваймса','Хорошая работа, $n. Для любителя просто отличная. $b$bЛеди Праудмур просила, чтобы я держал ее в курсе, но я некоторое время не имел возможности с ней пообщаться.$b$bЯ собирался отправить ей рапорт позже, – но мне кажется уместным вместо этого послать к ней тебя. Ты куда лучше меня ответишь на все ее вопросы.','Отнесите донесение Ваймса леди Джайне Праудмур в Терамор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение Ваймса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошая работа, $n. Для любителя просто отличная. $b$bЛеди Праудмур просила, чтобы я держал ее в курсе, но я некоторое время не имел возможности с ней пообщаться.$b$bЯ собирался отправить ей рапорт позже, – но мне кажется уместным вместо этого послать к ней тебя. Ты куда лучше меня ответишь на все ее вопросы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите донесение Ваймса леди Джайне Праудмур в Терамор.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1289,'<nyi> Доклад Ваймса','Итак, судя по докладу капитана Ваймса, ты весьма $gпомог:помогла; нам в этом расследовании, благодарю тебя.$b$bЯ с чистой совестью могу оставить дальнейшую судьбу этого дела в таких надежных руках. Поэтому прошу тебя вернуться к капитану Ваймсу и помочь ему в раскрытии этого преступления.','Вернитесь к капитану Ваймсу в Терамор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<nyi> Доклад Ваймса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, судя по докладу капитана Ваймса, ты весьма $gпомог:помогла; нам в этом расследовании, благодарю тебя.$b$bЯ с чистой совестью могу оставить дальнейшую судьбу этого дела в таких надежных руках. Поэтому прошу тебя вернуться к капитану Ваймсу и помочь ему в раскрытии этого преступления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к капитану Ваймсу в Терамор.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1290,'В поисках Мозарна','Поговори с бугаем Комаком. Но вопросов не задавай – убьет.','Говори.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Мозарна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поговори с бугаем Комаком. Но вопросов не задавай – убьет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Говори.',`objectives_loc8`);
