INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1301,'[DEPRECATED]James Hyal','Перед тем, как перебраться сюда, в "Печальный отшельник", я обучался, у одного из лучших поваров которых я когда-либо встречал. Его звали Джеймс Хьяль, и все чего я добился в этой жизни, это только благодаря ему.$B$BИнтересно, как-то он там сейчас? Они вместе со своим братом Винсентом работали в таверне, в Гавани Менетилов, но я давно о нем ничего не слышал.$B$BЕсли вдруг ненароком встретишь его, кланяйся от меня.','Поговорите с Винсентом Хьялем в Гавани Менетилов.','Джеймс? Так он еще когда уехал отсюда.$B$BВолна патриотизма накрыла, наверное. Можно понять. Многие после всего этого безумия, творящегося в Лордероне, последовали за море за Джайной Праудмур.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]James Hyal',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед тем, как перебраться сюда, в "Печальный отшельник", я обучался, у одного из лучших поваров которых я когда-либо встречал. Его звали Джеймс Хьяль, и все чего я добился в этой жизни, это только благодаря ему.$B$BИнтересно, как-то он там сейчас? Они вместе со своим братом Винсентом работали в таверне, в Гавани Менетилов, но я давно о нем ничего не слышал.$B$BЕсли вдруг ненароком встретишь его, кланяйся от меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Винсентом Хьялем в Гавани Менетилов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Джеймс? Так он еще когда уехал отсюда.$B$BВолна патриотизма накрыла, наверное. Можно понять. Многие после всего этого безумия, творящегося в Лордероне, последовали за море за Джайной Праудмур.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1302,'[DEPRECATED]James Hyal','Мой брат Джеймс ушел за море с леди Праудмур. Последнее, что я слышал, было то, что по окончании боев он там открыл таверну. Но, где бы он ни находился, я уверен, что дела у него идут хорошо. Он ведь, знаете ли, великолепный повар.$b$bЯ некоторое время не имел о нем известий – видать, с таверной было много хлопот – но я уверен, что клерк в Тераморе сможет указать вам, где искать моего брата. Клерка вы найдете на верхнем этаже крепости в центре города, как же ее... А! Цитадель, вот как она называется.','Поговорите с клерком Лендри в Цитадели в Тераморе.','Джеймс Хьяль, Джеймс Хьяль... Что-то знакомое...$B$BА, точно! Случай с "Последним привалом". Если ты хоть что-то об этом знаешь, то пойди и расскажи капитану Ваймсу. Он ведет расследование.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]James Hyal',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой брат Джеймс ушел за море с леди Праудмур. Последнее, что я слышал, было то, что по окончании боев он там открыл таверну. Но, где бы он ни находился, я уверен, что дела у него идут хорошо. Он ведь, знаете ли, великолепный повар.$b$bЯ некоторое время не имел о нем известий – видать, с таверной было много хлопот – но я уверен, что клерк в Тераморе сможет указать вам, где искать моего брата. Клерка вы найдете на верхнем этаже крепости в центре города, как же ее... А! Цитадель, вот как она называется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с клерком Лендри в Цитадели в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Джеймс Хьяль, Джеймс Хьяль... Что-то знакомое...$B$BА, точно! Случай с "Последним привалом". Если ты хоть что-то об этом знаешь, то пойди и расскажи капитану Ваймсу. Он ведет расследование.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1318,'Неоконченное дело Гордоков','Ну, раз ты теперь король, может, попробуешь добыть сокровище Гордоков у того паскудного эльфа, который называет себя принцем, а? Тот король, что был до тебя, это дело профукал – так же, как и все прочие короли до него, с тех самых пор, как Тортелдрин, тот паскудный эльф, спер его у одного из королей!$b$bА вещица-то была ценная: латная рукавица Мощи Гордока! И в старых байках говорится, что воротить ее сможет только настоящий король Гордок. А еще говорится, что паскудный эльф до сих пор шляется где-то тут. Отыщи его, и будет тебе крутая рукавица, которую ты будешь носить по гроб жизни!','Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.$b$bПо словам Давигрома, в "старых байках" говорится, что Тортелдрин – "страшный эльф", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков.','Вернитесь к капитану Давигрому на Остров Фенриса, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неоконченное дело Гордоков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, раз ты теперь король, может, попробуешь добыть сокровище Гордоков у того паскудного эльфа, который называет себя принцем, а? Тот король, что был до тебя, это дело профукал – так же, как и все прочие короли до него, с тех самых пор, как Тортелдрин, тот паскудный эльф, спер его у одного из королей!$b$bА вещица-то была ценная: латная рукавица Мощи Гордока! И в старых байках говорится, что воротить ее сможет только настоящий король Гордок. А еще говорится, что паскудный эльф до сих пор шляется где-то тут. Отыщи его, и будет тебе крутая рукавица, которую ты будешь носить по гроб жизни!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.$b$bПо словам Давигрома, в "старых байках" говорится, что Тортелдрин – "страшный эльф", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Давигрому на Остров Фенриса, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1319,'[DEPRECATED]The Black Shield','Увы, но я не смогу помочь тебе, $n. Впрочем, я знаю, кто сможет. Каз Дваждыдвац – один из лучших наших кузнецов. Его можно найти на кузне.$b$bПокажи ему щит и послушай, что он скажет.','Покажите потемневший железный Щит Казу Дваждыдвацу из Терамора.','Хмм... Интересная железяка. Это точно не моя работа, и я не знаю ни одного кузнеца по эту сторону моря, из чьих рук она могла бы выйти.','На что взглянуть?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Black Shield',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Увы, но я не смогу помочь тебе, $n. Впрочем, я знаю, кто сможет. Каз Дваждыдвац – один из лучших наших кузнецов. Его можно найти на кузне.$b$bПокажи ему щит и послушай, что он скажет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите потемневший железный Щит Казу Дваждыдвацу из Терамора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм... Интересная железяка. Это точно не моя работа, и я не знаю ни одного кузнеца по эту сторону моря, из чьих рук она могла бы выйти.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На что взглянуть?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1320,'[DEPRECATED]The Black Shield','Чуть было не просмотрел... Кожаный ремень на тыльной стороне щита сгорел, но, сдается мне, он был приспособлен под крупную руку. Скорее всего, тауренскую.$b$bВот, в общем, и все, что я могу тебе сказать. Передай капитану Ваймсу, что я сожалею, но больше ничем не могу ему помочь.','Поговорите с капитаном Гарраном Ваймсом в Тераморе.','Узнать удалось немного, но и это сгодится. Будем надеяться, что вскоре прояснятся остальные части этой головоломки, и мы сможем увидеть полную картину произошедшего.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Black Shield',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чуть было не просмотрел... Кожаный ремень на тыльной стороне щита сгорел, но, сдается мне, он был приспособлен под крупную руку. Скорее всего, тауренскую.$b$bВот, в общем, и все, что я могу тебе сказать. Передай капитану Ваймсу, что я сожалею, но больше ничем не могу ему помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Гарраном Ваймсом в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Узнать удалось немного, но и это сгодится. Будем надеяться, что вскоре прояснятся остальные части этой головоломки, и мы сможем увидеть полную картину произошедшего.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1321,'[DEPRECATED]The Black Shield','Хмм... Я не вижу в этом щите ничего необычного. Нужно попросить До\'гола, нашего кузнеца, взглянуть на него. Может быть, До\'гол сможет рассказать нам больше, хотя я бы не надеялся на это...','Покажите потемневший железный щит До\'голу из Деревни Гиблотопь.','Что это у тебя тут, |3-6($C)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Black Shield',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хмм... Я не вижу в этом щите ничего необычного. Нужно попросить До\'гола, нашего кузнеца, взглянуть на него. Может быть, До\'гол сможет рассказать нам больше, хотя я бы не надеялся на это...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите потемневший железный щит До\'голу из Деревни Гиблотопь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя тут, |3-6($C)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1322,'[DEPRECATED]The Black Shield','Хммм... Тут, на ободе щита, оказывается, есть надпись, но прочитать ее трудно, она почти вся обгорела.$b$bМне нужна кислота, чтобы слегка отчистить ее. Яд пауков Мглистой пещеры подойдет. Эти пауки водятся в старых копях – Мглистой пещере к северо-западу от деревни. Принеси мне немного их ядовитых желез, и я смогу отчистить этот щит.','Добудьте 5 ядовитых желез Паука Черного Тумана для До\'гола из Деревни Гиблотопь.','Ты добыл яд этих пауков?','Вернитесь к До\'голу в деревню Гиблотопь, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Black Shield',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хммм... Тут, на ободе щита, оказывается, есть надпись, но прочитать ее трудно, она почти вся обгорела.$b$bМне нужна кислота, чтобы слегка отчистить ее. Яд пауков Мглистой пещеры подойдет. Эти пауки водятся в старых копях – Мглистой пещере к северо-западу от деревни. Принеси мне немного их ядовитых желез, и я смогу отчистить этот щит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 ядовитых желез Паука Черного Тумана для До\'гола из Деревни Гиблотопь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты добыл яд этих пауков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к До\'голу в деревню Гиблотопь, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1323,'[DEPRECATED]The Black Shield','Сдается мне, что с кислотой я переборщил. Теперь осторожно потрем щит...$b$bХмм. Прочесть сложновато, но, похоже, тут написано имя: Мозарн. Никогда о таком не слышал. Надо спросить Крога, он знаком с кучей народу.','Поговорите с Крогом в Деревне Гиблотопь.','Мозарн? Звучит знакомо... Но поручиться не могу. Может быть вспомню попозже.\n\nСкорее всего, это имя не имеет значения. Щит мог попасть туда откуда угодно и с какой угодно целью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Black Shield',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сдается мне, что с кислотой я переборщил. Теперь осторожно потрем щит...$b$bХмм. Прочесть сложновато, но, похоже, тут написано имя: Мозарн. Никогда о таком не слышал. Надо спросить Крога, он знаком с кучей народу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Крогом в Деревне Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мозарн? Звучит знакомо... Но поручиться не могу. Может быть вспомню попозже.\n\nСкорее всего, это имя не имеет значения. Щит мог попасть туда откуда угодно и с какой угодно целью.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1324,'Пропавший дипломат','Что?! Вы приходите сюда, обвиняете меня в пособничестве Братству Справедливости и надеетесь, что я буду стоять столбом и позволю себя убить? Меня, между прочим, давно насчет вас предупреждали...','Победите рядового Хендела в Пылевых топях.','Уверяю вас, что мы все огорчены текущими событиями, но просим позволить забрать его назад в Терамор, чтобы задать несколько вопросов. Это поможет в поисках короля.$B$BЛеди Праудмур отблагодарит вас за помощь. Обратитесь к ней при первой возможности.','И снова здравствуйте, $N. Надеюсь, ты не против помощи, но мы не могли допустить, чтобы Хендел сбежал или, что еще хуже, умер.','Победить рядового Хендела.','Вернитесь к верховному магу Тервошу в Пылевые топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что?! Вы приходите сюда, обвиняете меня в пособничестве Братству Справедливости и надеетесь, что я буду стоять столбом и позволю себя убить? Меня, между прочим, давно насчет вас предупреждали...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите рядового Хендела в Пылевых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уверяю вас, что мы все огорчены текущими событиями, но просим позволить забрать его назад в Терамор, чтобы задать несколько вопросов. Это поможет в поисках короля.$B$BЛеди Праудмур отблагодарит вас за помощь. Обратитесь к ней при первой возможности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И снова здравствуйте, $N. Надеюсь, ты не против помощи, но мы не могли допустить, чтобы Хендел сбежал или, что еще хуже, умер.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победить рядового Хендела.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Тервошу в Пылевые топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1338,'Заказ Грозовой Вершины','Есть один дворф-бронник, чья работа меня глубоко восхищает. Его зовут Фьюрен Длиннобород, и такого искусника еще поискать. Мне нужен новый щит, и я хотел бы сделать заказ у него!$B$BПроблема в том... что он живет далеко на юге, в Квартале Дворфов в Штормграде. В человеческих землях! Представления не имею, зачем он поселился так далеко от Стальгорна. Должно быть, люди платят немалую мзду, лишь бы удержать его у себя!$B$BЕсли ты любишь путешествовать и не прочь подзаработать, может, передашь мой заказ Фьюрену?','Отнесите заказ Грозовой Вершины Фьюрену Длиннобороду в Штормград.','Письмо из дворфийских земель? Интересно, кто это пишет мне из такой дали…$B$BПозволь взглянуть на заказ.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заказ Грозовой Вершины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть один дворф-бронник, чья работа меня глубоко восхищает. Его зовут Фьюрен Длиннобород, и такого искусника еще поискать. Мне нужен новый щит, и я хотел бы сделать заказ у него!$B$BПроблема в том... что он живет далеко на юге, в Квартале Дворфов в Штормграде. В человеческих землях! Представления не имею, зачем он поселился так далеко от Стальгорна. Должно быть, люди платят немалую мзду, лишь бы удержать его у себя!$B$BЕсли ты любишь путешествовать и не прочь подзаработать, может, передашь мой заказ Фьюрену?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите заказ Грозовой Вершины Фьюрену Длиннобороду в Штормград.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Письмо из дворфийских земель? Интересно, кто это пишет мне из такой дали…$B$BПозволь взглянуть на заказ.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1339,'Задание Грозовой Вершины','Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие. Сможет ли |3-6($r) вроде тебя справиться с его поручением?$b$BЕсли ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне.','Поговорите с горным пехотинцем Грозовой Вершиной.','Верно. У меня есть одно дельце, но самому мне недосуг – не могу покинуть пост. Путь неблизкий, придется поработать ногами.$B$BЗато отличная возможность поискать приключений!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание Грозовой Вершины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие. Сможет ли |3-6($r) вроде тебя справиться с его поручением?$b$BЕсли ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с горным пехотинцем Грозовой Вершиной.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Верно. У меня есть одно дельце, но самому мне недосуг – не могу покинуть пост. Путь неблизкий, придется поработать ногами.$B$BЗато отличная возможность поискать приключений!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1358,'Образец для Хелбрима','Мой коллега из Калимдора, аптекарь Хелбрим, исследует воздействие лордеронских ядов на тамошних зверей. Он наверняка хотел бы иметь препарат из волчьего сердца, что мне прислал Ренферрел. $b$bХелбрим обосновался в Степях, в деревне под названием Перекресток. Чтобы до него добраться, вам нужно будет на дирижабле добраться до орочьей столицы Оргриммара, а потом пешком проследовать на юг, в Дуротар. Направляйтесь на запад, в Степи, и вскоре дойдете до Перекрестка.','Принесите образец сердца волка аптекарю Хелбриму в Степи.','У вас есть для меня посылочка?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Образец для Хелбрима',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой коллега из Калимдора, аптекарь Хелбрим, исследует воздействие лордеронских ядов на тамошних зверей. Он наверняка хотел бы иметь препарат из волчьего сердца, что мне прислал Ренферрел. $b$bХелбрим обосновался в Степях, в деревне под названием Перекресток. Чтобы до него добраться, вам нужно будет на дирижабле добраться до орочьей столицы Оргриммара, а потом пешком проследовать на юг, в Дуротар. Направляйтесь на запад, в Степи, и вскоре дойдете до Перекрестка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите образец сердца волка аптекарю Хелбриму в Степи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть для меня посылочка?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1359,'Посылка для Зинг','Волчьи сердца, которые вы собрали, обладают качеством, невиданным доселе в подобных образцах. Это сила яда, которая должна быть смертельной даже для тех самых волков, в груди которых бьются эти сердца! $b$bЭто просто невероятно, и мы должны продолжить исследование. Я сохранил несколько полученных препаратов. Отнесите их моей коллеге, аптекарю Зинг. Ее можно найти в главном представительстве нашего Общества в Подгороде.','Отнесите образцы сердца волка аптекарю Зинг в Подгород.','Ах да, препараты сердец, о которых говорил Ренферрел. Я хочу поскорее начать экспериментировать с ними... Обнаружение новых форм ядов всгда вызывает живейший интерес в Королевском фармацевтическом обществе.','Вы мне что-то принесли?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посылка для Зинг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волчьи сердца, которые вы собрали, обладают качеством, невиданным доселе в подобных образцах. Это сила яда, которая должна быть смертельной даже для тех самых волков, в груди которых бьются эти сердца! $b$bЭто просто невероятно, и мы должны продолжить исследование. Я сохранил несколько полученных препаратов. Отнесите их моей коллеге, аптекарю Зинг. Ее можно найти в главном представительстве нашего Общества в Подгороде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите образцы сердца волка аптекарю Зинг в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах да, препараты сердец, о которых говорил Ренферрел. Я хочу поскорее начать экспериментировать с ними... Обнаружение новых форм ядов всгда вызывает живейший интерес в Королевском фармацевтическом обществе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы мне что-то принесли?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1360,'Возвращенные сокровища','Я неплохо зарабатывал горнорабочим на ульдаманском раскопе в Бесплодных землях, пока не появились эти клятые трогги. Я едва сумел спасти свою шкуру, но в суматохе потерял самое дорогое, что у меня было. Уверен, что трогги не добрались до моего сокровища, поскольку оно в сундуке, но сундук-то в самой их гуще.$B$BЕсли ты принесешь его мне, то не поскуплюсь ни на деньги, ни на хвалу! Сундучок с моим именем находится в конце Северного зала. Вот туда тебе и надо попасть.','Достаньте сокровище Крома Крепкорука из сундука в северном зале Ульдамана и принесите ему в Стальгорн.','Ах, я снова счастлив! Спасибо тебе огромное.$B$BМожет, кому из дворфов дороже всего блеск металла, а кому – сверкание драгоценных камней, но Крепкорук без своей драгоценной пивной кружки вряд ли может считаться Крепкоруком!','Ну, тебе удалось надавать этим троггам и добраться до моего сундука?','Вернитесь к Крому Крепкоруку в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращенные сокровища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я неплохо зарабатывал горнорабочим на ульдаманском раскопе в Бесплодных землях, пока не появились эти клятые трогги. Я едва сумел спасти свою шкуру, но в суматохе потерял самое дорогое, что у меня было. Уверен, что трогги не добрались до моего сокровища, поскольку оно в сундуке, но сундук-то в самой их гуще.$B$BЕсли ты принесешь его мне, то не поскуплюсь ни на деньги, ни на хвалу! Сундучок с моим именем находится в конце Северного зала. Вот туда тебе и надо попасть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте сокровище Крома Крепкорука из сундука в северном зале Ульдамана и принесите ему в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, я снова счастлив! Спасибо тебе огромное.$B$BМожет, кому из дворфов дороже всего блеск металла, а кому – сверкание драгоценных камней, но Крепкорук без своей драгоценной пивной кружки вряд ли может считаться Крепкоруком!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, тебе удалось надавать этим троггам и добраться до моего сундука?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крому Крепкоруку в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1361,'Регтар Врата Смерти','Регтар Врата Смерти, воин Орды, набирает агентов для похода в земли Пустошей. Любой желающий может поговорить с ним и попробовать записаться в отряд. Найти Регтара можно в Степях, в одном из укрытий к западу от Перекрестка.$B$BНе следует забывать, что в Пустошах не затихают битвы, поэтому без оружия там нечего делать.','Поговорите с Регтаром Врата Смерти.','Да, я набираю добровольцев. Тех, кто готов отправиться в Пустоши и сражаться с кентаврами. Я изложу ситуацию вкратце, чтобы ты скорее мог приступить к выполнению задания.','Потрошительница из стаи Кровавой Ярости – ужасное существо! Ты, несомненно, найдешь ее у подножия западных холмов в Обугленной долине.\n\nБез нее гарпии будут бессильны... и мы уж точно сможем избавиться от них!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Регтар Врата Смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Регтар Врата Смерти, воин Орды, набирает агентов для похода в земли Пустошей. Любой желающий может поговорить с ним и попробовать записаться в отряд. Найти Регтара можно в Степях, в одном из укрытий к западу от Перекрестка.$B$BНе следует забывать, что в Пустошах не затихают битвы, поэтому без оружия там нечего делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Регтаром Врата Смерти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я набираю добровольцев. Тех, кто готов отправиться в Пустоши и сражаться с кентаврами. Я изложу ситуацию вкратце, чтобы ты скорее мог приступить к выполнению задания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Потрошительница из стаи Кровавой Ярости – ужасное существо! Ты, несомненно, найдешь ее у подножия западных холмов в Обугленной долине.\n\nБез нее гарпии будут бессильны... и мы уж точно сможем избавиться от них!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1362,'Кентавры Пустошей','Кентавры из клана Колкар изначально жили в Пустошах, но теперь они все чаще появляются в Степях. Это известный факт, и Орда послала своих агентов разбираться с ними.$B$BОднако же пока клан Колкар силен в Пустошах, эти кентавры всегда будут для нас угрозой. Думаю, пора от них избавиться. Главное – безопасность!$B$BПоговори с Фелгуром Бью-Двоих: ты его найдешь на Заставе Скитающихся Духов в Пустошах. Его отправили туда для сбора информации о кентаврах. Думаю, он лучше всех знает, как справиться с кланом Колкар.','Найдите на Заставе Скитающихся Духов в Пустошах Фелгура Бью-Двоих и поговорите с ним.','Тебя Регтар сюда прислал? Значит, ты и будешь решать проблему кентавров? Что ж, хорошо.\n\nНадеюсь, ты успел отдохнуть. Не знаю уж, удастся нам разобраться с этими тварями, или нет, но за то, что это будет долгая и тяжкая драка, могу ручаться.\n\nПрисядь и послушай меня...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кентавры Пустошей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кентавры из клана Колкар изначально жили в Пустошах, но теперь они все чаще появляются в Степях. Это известный факт, и Орда послала своих агентов разбираться с ними.$B$BОднако же пока клан Колкар силен в Пустошах, эти кентавры всегда будут для нас угрозой. Думаю, пора от них избавиться. Главное – безопасность!$B$BПоговори с Фелгуром Бью-Двоих: ты его найдешь на Заставе Скитающихся Духов в Пустошах. Его отправили туда для сбора информации о кентаврах. Думаю, он лучше всех знает, как справиться с кланом Колкар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите на Заставе Скитающихся Духов в Пустошах Фелгура Бью-Двоих и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя Регтар сюда прислал? Значит, ты и будешь решать проблему кентавров? Что ж, хорошо.\n\nНадеюсь, ты успел отдохнуть. Не знаю уж, удастся нам разобраться с этими тварями, или нет, но за то, что это будет долгая и тяжкая драка, могу ручаться.\n\nПрисядь и послушай меня...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1363,'Задание Мазена','Я слежу за тем, чтобы все фолианты и свитки в библиотеке Академии Тайных Наук и Искусств постоянно находились под присмотром. Кто знает, сколько глупостей может натворить непосвященный, заполучив тайные трактаты по магии?$b$bНапример, на прошлой неделе мой помощник Деллис допустил одну оплошность... Он неплохой работник и хорошо ориентируется в пределах библиотеки, но совершенно теряется, стоит ему выйти за ворота Штормграда... Пожалуйста, помогите Деллису разобраться с его затруднением.','Поговорите с послушником Деллисом в Штормграде.','Да не виноват я! Клянусь, не виноват!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание Мазена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слежу за тем, чтобы все фолианты и свитки в библиотеке Академии Тайных Наук и Искусств постоянно находились под присмотром. Кто знает, сколько глупостей может натворить непосвященный, заполучив тайные трактаты по магии?$b$bНапример, на прошлой неделе мой помощник Деллис допустил одну оплошность... Он неплохой работник и хорошо ориентируется в пределах библиотеки, но совершенно теряется, стоит ему выйти за ворота Штормграда... Пожалуйста, помогите Деллису разобраться с его затруднением.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с послушником Деллисом в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да не виноват я! Клянусь, не виноват!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1364,'Задание Мазена','Указания мастера Мазена были совсем простыми: доставить важное сочинение дозорному Махару Ба в Крепость Стражей Пустоты.$b$bНо мне раньше не доводилось бывать в Выжженных землях! Путешествие было просто ужасным...$b$bНеподалеку от Болота Печали я свернул куда-то не туда и оказался окружен жуткими тварями, похожими на растения. Они напали на меня, и я сбежал. Представьте себе, при этом я потерял сочинение! Думаю, его забрала одна из этих тварей.$b$bНе могу ли я попросить вас найти документ и доставить его Махару Ба?','Верните "Рассуждения Кадгара о пространственной сходимости" и доставьте сочинение дозорному Махару Ба в Крепость Стражей Пустоты.','Какое счастье!$B$BДо сего момента я считал, что мой запрос на "Рассуждения Кадгара о пространственной сходимости", который я отправлял в Академию Тайных Наук и Искусств, был отклонен мастером Мазеном.$B$BОн, должно быть, просто потонул в запросах, поскольку последнее время происходит множество странных событий.$B$BТеперь прошу меня простить – мне пора приступить к исследованиям. Понимаете, сама возможность прикоснуться к творению величайшего Кадгара повергает меня в трепет...','Что привело вас в Крепость Стражей Пустоты, |3-6($C)?','Вернитесь к дозорному Махару Ба в Крепость Стражей Пустоты, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание Мазена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Указания мастера Мазена были совсем простыми: доставить важное сочинение дозорному Махару Ба в Крепость Стражей Пустоты.$b$bНо мне раньше не доводилось бывать в Выжженных землях! Путешествие было просто ужасным...$b$bНеподалеку от Болота Печали я свернул куда-то не туда и оказался окружен жуткими тварями, похожими на растения. Они напали на меня, и я сбежал. Представьте себе, при этом я потерял сочинение! Думаю, его забрала одна из этих тварей.$b$bНе могу ли я попросить вас найти документ и доставить его Махару Ба?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните "Рассуждения Кадгара о пространственной сходимости" и доставьте сочинение дозорному Махару Ба в Крепость Стражей Пустоты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какое счастье!$B$BДо сего момента я считал, что мой запрос на "Рассуждения Кадгара о пространственной сходимости", который я отправлял в Академию Тайных Наук и Искусств, был отклонен мастером Мазеном.$B$BОн, должно быть, просто потонул в запросах, поскольку последнее время происходит множество странных событий.$B$BТеперь прошу меня простить – мне пора приступить к исследованиям. Понимаете, сама возможность прикоснуться к творению величайшего Кадгара повергает меня в трепет...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело вас в Крепость Стражей Пустоты, |3-6($C)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Махару Ба в Крепость Стражей Пустоты, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1365,'Вождь Дез\'хеп','Племя Колкар – не единственные кентавры в Пустошах. На этих пустынных равнинах поселилось множество племен, ведущих друг с другом бесконечную войну. Наше счастье, что они дерутся между собой: кентавры сильны и яростны в битве, и, если бы они объединились, нам тяжело было бы выстоять против них.$B$BМы должны покончить с ними прежде, чем они объединятся.$B$BТвое первое задание – расколоть племя Колкар. Для этого нужно убить их предводителя Дез\'хепа.$B$BДеревня клана Колкар находится к северо-востоку отсюда. Иди, и да пребудет с тобой удача.','Принесите Фелгуру Бью-Двоих голову вождя Дез\'хепа.','Отлично. Быстрый и точный удар по клану Колкар стал весьма эффектной демонстрацией силы, а сила – это именно то, что кентавры понимают лучше всего.\n\nСмерть вождя клана Колкар не только расколет клан, но и станет предостережением для всех прочих кентавров.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь Дез\'хеп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Колкар – не единственные кентавры в Пустошах. На этих пустынных равнинах поселилось множество племен, ведущих друг с другом бесконечную войну. Наше счастье, что они дерутся между собой: кентавры сильны и яростны в битве, и, если бы они объединились, нам тяжело было бы выстоять против них.$B$BМы должны покончить с ними прежде, чем они объединятся.$B$BТвое первое задание – расколоть племя Колкар. Для этого нужно убить их предводителя Дез\'хепа.$B$BДеревня клана Колкар находится к северо-востоку отсюда. Иди, и да пребудет с тобой удача.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Фелгуру Бью-Двоих голову вождя Дез\'хепа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Быстрый и точный удар по клану Колкар стал весьма эффектной демонстрацией силы, а сила – это именно то, что кентавры понимают лучше всего.\n\nСмерть вождя клана Колкар не только расколет клан, но и станет предостережением для всех прочих кентавров.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1366,'Награда за кентавров','Тебе удалось устрашить кентавров; теперь пришло время пустить им кровь. Странствуя по Пустоши, охоться на кентавров. Их клан меня не волнует: просто убей их и принеси мне уши. Пригоршни ушей!$B$BЧем меньше кентавров, тем слабее их решимость: пусть навсегда расстанутся с мыслью завоевать эти земли!$B$BДоброй охоты, $n.','Принесите в Пустоши 15 ушей кентавров и отдайте Фелгуру Бью-Двоих.','Теперь-то кентавры навсегда запомнят твое имя! Уверен, они уважают и страшатся тебя. Уверен, благодаря тебе они не забудут и того знамени, под которым ты вступал в бой.\n\nЗнамя Орды!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда за кентавров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось устрашить кентавров; теперь пришло время пустить им кровь. Странствуя по Пустоши, охоться на кентавров. Их клан меня не волнует: просто убей их и принеси мне уши. Пригоршни ушей!$B$BЧем меньше кентавров, тем слабее их решимость: пусть навсегда расстанутся с мыслью завоевать эти земли!$B$BДоброй охоты, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите в Пустоши 15 ушей кентавров и отдайте Фелгуру Бью-Двоих.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь-то кентавры навсегда запомнят твое имя! Уверен, они уважают и страшатся тебя. Уверен, благодаря тебе они не забудут и того знамени, под которым ты вступал в бой.\n\nЗнамя Орды!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1367,'Союз с племенем Маграм','Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть. Мы заключим союз с одним из племен, и так найдем способ одолеть всех остальных.$B$BЕсли ты решишь заключить союз с племенем Маграм, уничтожь их кровных врагов – племя Гелкис. Так ты завоюешь уважение племени Маграм. Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Варугом. Ты найдешь его на окраине деревни Маграм в юго-восточной части Пустошей.','Заслужите дружественное отношение племени Маграм, а затем поговорите с Варугом.','Кентавры племени Гелкис кричат от ужаса, заслышав твое имя, $N. Они страшатся и ненавидят тебя. Ненавидят так же, как племя Маграм!$B$BМожет, ты и не слабее нас. Может, ты даже $Gдостоин:достойна; того, чтобы мы с тобой говорили. Посмотрим...','Уходи! Маграм не разговаривает со слабыми. Мы убиваем их!$B$BЕсли хочешь поговорить со мной, покажи мне, что ты силен. Возвращайся, когда поубиваешь Гелкис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союз с племенем Маграм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть. Мы заключим союз с одним из племен, и так найдем способ одолеть всех остальных.$B$BЕсли ты решишь заключить союз с племенем Маграм, уничтожь их кровных врагов – племя Гелкис. Так ты завоюешь уважение племени Маграм. Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Варугом. Ты найдешь его на окраине деревни Маграм в юго-восточной части Пустошей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заслужите дружественное отношение племени Маграм, а затем поговорите с Варугом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кентавры племени Гелкис кричат от ужаса, заслышав твое имя, $N. Они страшатся и ненавидят тебя. Ненавидят так же, как племя Маграм!$B$BМожет, ты и не слабее нас. Может, ты даже $Gдостоин:достойна; того, чтобы мы с тобой говорили. Посмотрим...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уходи! Маграм не разговаривает со слабыми. Мы убиваем их!$B$BЕсли хочешь поговорить со мной, покажи мне, что ты силен. Возвращайся, когда поубиваешь Гелкис.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1368,'Союз с племенем Гелкис','Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть. Мы заключим союз с одним из племен, и так найдем способ одолеть всех остальных.$B$BЕсли ты решишь заключить союз с племенем Гелкис, уничтожь их кровных врагов – племя Маграм. Так ты завоюешь уважение племени Гелкис. Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Утой Мудрой. Ты найдешь ее на окраине деревни Гелкис в юго-западной части Пустошей.','Заслужите дружественное отношение племени Гелкис, а затем поговорите с Утой Мудрой.','Земля говорит со мной, земля говорит, что ты $Gубил:убила; многих из племени Маграм. Это хорошо.$B$BЕсли хочешь быть другом племени Гелкис, слушай. Я буду говорить с тобой. У меня есть для тебя дело.','Ваши две ноги ступают на землю Гелкис. Тебе здесь не рады!$B$BДокажи, что ты ищешь дружбы с Гелки. Убейте кентавра Маграма. Вернитесь, когда земля будет залита кровью Маграма.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союз с племенем Гелкис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы победить кентавров, мы должны обратить против них их же собственную ненависть. Мы заключим союз с одним из племен, и так найдем способ одолеть всех остальных.$B$BЕсли ты решишь заключить союз с племенем Гелкис, уничтожь их кровных врагов – племя Маграм. Так ты завоюешь уважение племени Гелкис. Когда кентавры будут достаточно доверять тебе, постарайся встретиться с Утой Мудрой. Ты найдешь ее на окраине деревни Гелкис в юго-западной части Пустошей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заслужите дружественное отношение племени Гелкис, а затем поговорите с Утой Мудрой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Земля говорит со мной, земля говорит, что ты $Gубил:убила; многих из племени Маграм. Это хорошо.$B$BЕсли хочешь быть другом племени Гелкис, слушай. Я буду говорить с тобой. У меня есть для тебя дело.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ваши две ноги ступают на землю Гелкис. Тебе здесь не рады!$B$BДокажи, что ты ищешь дружбы с Гелки. Убейте кентавра Маграма. Вернитесь, когда земля будет залита кровью Маграма.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1369,'Осколки слез','Племя Гелкис считает, что нас защищает матерь кентавров Терадрас. Они глупы. Кентавров никто не защищает. Маграм не нужна защита! Мы сильнее всех!$B$BПусть племя Гелкис поймет, насколько они глупы. Отправляйся в их деревню, прямиком к пещере. В этой пещере они хранят кристаллы – слезы Терадрас. Уничтожь эти кристаллы! Принеси мне их осколки!','Для поддержания отношений с племенем Маграм принесите осколки 3 кристаллов слез Варугу в деревню Маграм.','Ага! Вот они, Слезы! Теперь племя Гелкис поймет, что Терадрас не защитит их. Она не станет плакать, когда мы сокрушим их! Маграм будут править здесь!$B$BТы хорошо $Gсделал:сделала;, выбрав нашу сторону, $N. Мы – самые сильные.','Если ты нам не враг, то сделаешь то, о чем я прошу!','Вернитесь к Варугу в деревню Маграм, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осколки слез',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Гелкис считает, что нас защищает матерь кентавров Терадрас. Они глупы. Кентавров никто не защищает. Маграм не нужна защита! Мы сильнее всех!$B$BПусть племя Гелкис поймет, насколько они глупы. Отправляйся в их деревню, прямиком к пещере. В этой пещере они хранят кристаллы – слезы Терадрас. Уничтожь эти кристаллы! Принеси мне их осколки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Для поддержания отношений с племенем Маграм принесите осколки 3 кристаллов слез Варугу в деревню Маграм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага! Вот они, Слезы! Теперь племя Гелкис поймет, что Терадрас не защитит их. Она не станет плакать, когда мы сокрушим их! Маграм будут править здесь!$B$BТы хорошо $Gсделал:сделала;, выбрав нашу сторону, $N. Мы – самые сильные.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты нам не враг, то сделаешь то, о чем я прошу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варугу в деревню Маграм, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1370,'Похищение припасов','Когда мы не воюем, то охотимся, чтобы добыть мяса. Мясо дает нам силу. Сытый воюет лучше голодного. Сытый сильнее. Сытый победит.$B$BПлемя Маграм поступает так же. Они запасают мясо, чтобы воевать дольше. Если нападешь на их деревню на востоке и заберешь их припасы, Маграм станут слабыми.','Принесите 6 мешков недосушенного мяса в деревню Гелкис и отдайте Уте Мудрой.','Хорошо. Я слышу, как урчит в брюхе у голодных Маграм! Слышу это даже здесь!$B$BЯ отдам это мясо племени Гелкис. Мы будем воевать много дней без отдыха.$B$BТо, что ты $Gсделал:сделала;, хорошо для племени Гелкис.','Когда докажешь, что верен клану Гелкис, возвращайся. Будем говорить.','Вернитесь к Уте Мудрой в деревню Гелкис, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищение припасов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда мы не воюем, то охотимся, чтобы добыть мяса. Мясо дает нам силу. Сытый воюет лучше голодного. Сытый сильнее. Сытый победит.$B$BПлемя Маграм поступает так же. Они запасают мясо, чтобы воевать дольше. Если нападешь на их деревню на востоке и заберешь их припасы, Маграм станут слабыми.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 мешков недосушенного мяса в деревню Гелкис и отдайте Уте Мудрой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Я слышу, как урчит в брюхе у голодных Маграм! Слышу это даже здесь!$B$BЯ отдам это мясо племени Гелкис. Мы будем воевать много дней без отдыха.$B$BТо, что ты $Gсделал:сделала;, хорошо для племени Гелкис.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда докажешь, что верен клану Гелкис, возвращайся. Будем говорить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уте Мудрой в деревню Гелкис, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1371,'Игрушка для Варуга','Давным-давно один маленький гном пришел в Пустоши со своей тележной, запряженной лошадью и нагруженной множеством странных вещей. Занятных вещей. Некоторые горели разноцветным огнем. Некоторые двигались, не будучи при этом живыми. Я убил этого маленького гнома, но перед этим... он заставил меня посмеяться.$B$BЯ оставил себе одну вещицу с его тележки – ту, которая понравилась мне больше всего. Это был деревянный человек, который махал на меня руками, пока я не ударил его, да так, что тот сломался.$B$BЯ хочу нового деревянного человека! Доставай его, где хочешь, но принеси мне!','Для поддержания отношений с племенем Маграм принесите усовершенствованный манекен-мишень Варугу в деревню Маграм.','Да! Именно такой человек у меня и был! Он снова будет двигаться. Снова будет веселить меня!','Если ты нам не враг, то сделаешь то, о чем я прошу!','Вернитесь к Варугу в деревню Маграм, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игрушка для Варуга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно один маленький гном пришел в Пустоши со своей тележной, запряженной лошадью и нагруженной множеством странных вещей. Занятных вещей. Некоторые горели разноцветным огнем. Некоторые двигались, не будучи при этом живыми. Я убил этого маленького гнома, но перед этим... он заставил меня посмеяться.$B$BЯ оставил себе одну вещицу с его тележки – ту, которая понравилась мне больше всего. Это был деревянный человек, который махал на меня руками, пока я не ударил его, да так, что тот сломался.$B$BЯ хочу нового деревянного человека! Доставай его, где хочешь, но принеси мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Для поддержания отношений с племенем Маграм принесите усовершенствованный манекен-мишень Варугу в деревню Маграм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да! Именно такой человек у меня и был! Он снова будет двигаться. Снова будет веселить меня!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты нам не враг, то сделаешь то, о чем я прошу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варугу в деревню Маграм, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1372,'Правда и только правда','По приказу Вариматаса нашу экспедицию направили на изучение нижнего Азерота.$B$BОтправившись на разведку, я заметил лазутчика, подобравшегося к Приюту Бродяги. Не успел я скрутить его, как некоторые наши орочьи... братья... захватили его и уволокли в Каменор, крепость на Болоте Печали.$b$BЯ хочу... помочь... нашим братьям-оркам. Они не заметили наш лагерь, но я все равно собираюсь оказать им услугу.$B$BФаустин поможет тебе сделать... сыворотку правды для нашего друга в Каменоре.','Поговорите с аптекарем Фаустином в Приюте Бродяги.','Зредус как раз перед твоим приходом рассказал мне об этом любопытном маленьком лазутчике.$B$BЭто и правда проблема. Нам вовсе не нужен нахал, вынюхивающий, что да как.$B$BУверен, орки Каменора с интересом выслушают его. Поскольку они, хм, наши союзники, мы должны помочь им добыть информацию от этого человека.$B$BПомоги мне, $N, – и мы доставим в Каменор сыворотку правды.$B$BЗа Орду!$B$BЭ-э... я правильно выразился?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правда и только правда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По приказу Вариматаса нашу экспедицию направили на изучение нижнего Азерота.$B$BОтправившись на разведку, я заметил лазутчика, подобравшегося к Приюту Бродяги. Не успел я скрутить его, как некоторые наши орочьи... братья... захватили его и уволокли в Каменор, крепость на Болоте Печали.$b$BЯ хочу... помочь... нашим братьям-оркам. Они не заметили наш лагерь, но я все равно собираюсь оказать им услугу.$B$BФаустин поможет тебе сделать... сыворотку правды для нашего друга в Каменоре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с аптекарем Фаустином в Приюте Бродяги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зредус как раз перед твоим приходом рассказал мне об этом любопытном маленьком лазутчике.$B$BЭто и правда проблема. Нам вовсе не нужен нахал, вынюхивающий, что да как.$B$BУверен, орки Каменора с интересом выслушают его. Поскольку они, хм, наши союзники, мы должны помочь им добыть информацию от этого человека.$B$BПомоги мне, $N, – и мы доставим в Каменор сыворотку правды.$B$BЗа Орду!$B$BЭ-э... я правильно выразился?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1373,'Онгеку','Тебе еще предстоит свершить многое. Война племен Гелкис и Маграм тебя не затронет: в это время ты будешь далеко отсюда.$B$BЗемля раскрывает множество тайн тем, кто умеет слушать ее; и одна из них – тайна красного кристалла, который называют дренетистом. Это камень нездешнего происхождения; он из тех земель, где горы парят в небе, где правят демоны...$B$BПринеси мне осколок дренетиста: о, с ним сила моей магии возрастет во много раз!.. Осколок можно отыскать на Болоте Печали: его хранит один из Заблудших, Онгеку.','Для поддержания отношений с племенем Гелкис принесите осколок дренетиста Уте Мудрой в деревню Гелкис.','О да, это и есть тот осколок, о котором шептала мне земля... Я ощущаю его магическую силу – ту силу, которую я направлю против врагов племени Гелкис.$B$BТебе удалось исполнить еще одно наше задание, $N. Возможно, со временем племя Гелкис сможет по праву считать тебя другом.','Докажи, что ты – подлинный друг племени Гелкис, $N.','Вернитесь к Уте Мудрой в деревню Гелкис, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Онгеку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе еще предстоит свершить многое. Война племен Гелкис и Маграм тебя не затронет: в это время ты будешь далеко отсюда.$B$BЗемля раскрывает множество тайн тем, кто умеет слушать ее; и одна из них – тайна красного кристалла, который называют дренетистом. Это камень нездешнего происхождения; он из тех земель, где горы парят в небе, где правят демоны...$B$BПринеси мне осколок дренетиста: о, с ним сила моей магии возрастет во много раз!.. Осколок можно отыскать на Болоте Печали: его хранит один из Заблудших, Онгеку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Для поддержания отношений с племенем Гелкис принесите осколок дренетиста Уте Мудрой в деревню Гелкис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да, это и есть тот осколок, о котором шептала мне земля... Я ощущаю его магическую силу – ту силу, которую я направлю против врагов племени Гелкис.$B$BТебе удалось исполнить еще одно наше задание, $N. Возможно, со временем племя Гелкис сможет по праву считать тебя другом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Докажи, что ты – подлинный друг племени Гелкис, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уте Мудрой в деревню Гелкис, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1374,'Вождь Джен','Земля говорит со мной. Земля знает, что племя Маграм утратило былую силу. Пришло время покончить с их вождем!$B$BПринеси мне голову Джена, вождя племени Маграм!','Принесите голову вождя Джена Уте Мудрой в деревню Гелкис.','Вождь Джехн был силен, но глуп. Он полагал, что наделен великой силой, но забыл, что магия Земли могущественнее любого смертного. Лишившись вождя, племя Маграм впадет в ничтожество, и племя Гелкис восторжествует!','Докажи, что ты – подлинный друг племени Гелкис, $N.','Вернитесь к Уте Мудрой в деревню Гелкис, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь Джен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Земля говорит со мной. Земля знает, что племя Маграм утратило былую силу. Пришло время покончить с их вождем!$B$BПринеси мне голову Джена, вождя племени Маграм!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову вождя Джена Уте Мудрой в деревню Гелкис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вождь Джехн был силен, но глуп. Он полагал, что наделен великой силой, но забыл, что магия Земли могущественнее любого смертного. Лишившись вождя, племя Маграм впадет в ничтожество, и племя Гелкис восторжествует!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Докажи, что ты – подлинный друг племени Гелкис, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уте Мудрой в деревню Гелкис, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1375,'Вождь Шак','Ты помогаешь племени Маграм. Это хорошо. Ты мне нравишься. А теперь пойди и убей вождя племени Гелкис! Вождь Шак – мне нужна его голова! Я хочу видеть его голову, я буду смотреть на нее и смеяться!','Для поддержания отношений с племенем Маграм принесите голову вождя Шака Варугу в деревню Маграм.','Вождь Шак мертв! Я насажу его голову на пику, чтобы любоваться ею каждый день! Пусть мертвые глаза Шака видят мощь племени Маграм!','Делай то, что нужно племени Маграм, и я помогу тебе.','Вернитесь к Варугу в деревню Маграм, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь Шак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты помогаешь племени Маграм. Это хорошо. Ты мне нравишься. А теперь пойди и убей вождя племени Гелкис! Вождь Шак – мне нужна его голова! Я хочу видеть его голову, я буду смотреть на нее и смеяться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Для поддержания отношений с племенем Маграм принесите голову вождя Шака Варугу в деревню Маграм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вождь Шак мертв! Я насажу его голову на пику, чтобы любоваться ею каждый день! Пусть мертвые глаза Шака видят мощь племени Маграм!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Делай то, что нужно племени Маграм, и я помогу тебе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варугу в деревню Маграм, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1380,'Вождь Храта','Ты $Gпомог:помогла; нам справиться с племенем Маграм, $n; теперь помоги нам одолеть племя Мародин! Убей их предводителя! Убей Храту!$B$BЧтобы вызвать его на бой, ты $Gдолжен:должна; протрубить в боевой рог племени Мародин; а рог этот ты найдешь, поднявшись на высокий утес в Долине Копий.$B$BТолько запомни: чтобы протрубить в рог, тебе нужно разыскать мундштук, а это нелегко, потому что найти такие мундштуки можно только у кентавров, пользующихся особым доверием племени...$B$BО чем это я? Ах, да: когда ты протрубишь в рог, кентавры явятся на бой, и тебе придется убивать их, пока не доберешься до самого Храты.$B$BА у вождя Храты есть фрагмент... некоего ключа. Принеси его мне...','Для поддержания отношений с племенем Гелкис принесите фрагмент Ключа Мародина Уте Мудрой в деревню Гелкис.','Он мертв! Вождь Храта мертв! Теперь племя Мародин падет! И когда этой землей станет править племя Гелкис – клянусь, мы не забудем тебя, $N. Духи земли будут вечно славить твое имя!','Надеюсь, вождь Храта мертв? А фрагмент ключа – он у тебя?','Вернитесь к Уте Мудрой в деревню Гелкис, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь Храта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gпомог:помогла; нам справиться с племенем Маграм, $n; теперь помоги нам одолеть племя Мародин! Убей их предводителя! Убей Храту!$B$BЧтобы вызвать его на бой, ты $Gдолжен:должна; протрубить в боевой рог племени Мародин; а рог этот ты найдешь, поднявшись на высокий утес в Долине Копий.$B$BТолько запомни: чтобы протрубить в рог, тебе нужно разыскать мундштук, а это нелегко, потому что найти такие мундштуки можно только у кентавров, пользующихся особым доверием племени...$B$BО чем это я? Ах, да: когда ты протрубишь в рог, кентавры явятся на бой, и тебе придется убивать их, пока не доберешься до самого Храты.$B$BА у вождя Храты есть фрагмент... некоего ключа. Принеси его мне...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Для поддержания отношений с племенем Гелкис принесите фрагмент Ключа Мародина Уте Мудрой в деревню Гелкис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он мертв! Вождь Храта мертв! Теперь племя Мародин падет! И когда этой землей станет править племя Гелкис – клянусь, мы не забудем тебя, $N. Духи земли будут вечно славить твое имя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, вождь Храта мертв? А фрагмент ключа – он у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уте Мудрой в деревню Гелкис, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1381,'Вождь Храта','Вождь племени Гелкис мертв; пришел черед племени Мародин! Убей их вождя, Храту!$B$BЕго не так просто отыскать, нет... Чтобы вызвать его на бой, ты $Gдолжен:должна; протрубить в боевой рог клана Мародин; а рог этот ты найдешь, поднявшись на высокий утес в Долине Копий. Только запомни: чтобы протрубить в рог, тебе нужно убить кентавра из племени Мародин и забрать у него мундштук.И вот когда ты протрубишь в рог, кентавры явятся на бой, и тебе придется убивать их, пока не доберешься до самого Храты. А у Храты есть фрагмент ключа. Он нужен мне, этот фрагмент. Принеси его. Принеси мне.','Для поддержания отношений с племенем Маграм принесите фрагмент Ключа Мародина Варугу в деревню Маграм.','Вождь Храта мертв! Теперь Маграм – сильнейшее из племен! Мы сокрушим всех! Мы будем править в Пустошах!$B$BМы не забудем тебя, $N, и в тот час, когда сотни будут гибнуть под нашими копытами, мы пощадим тебя.','Сделай, что я говорю. Докажи, что ты – достойный союзник племени Маграм!','Вернитесь к Варугу в деревню Маграм, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь Храта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вождь племени Гелкис мертв; пришел черед племени Мародин! Убей их вождя, Храту!$B$BЕго не так просто отыскать, нет... Чтобы вызвать его на бой, ты $Gдолжен:должна; протрубить в боевой рог клана Мародин; а рог этот ты найдешь, поднявшись на высокий утес в Долине Копий. Только запомни: чтобы протрубить в рог, тебе нужно убить кентавра из племени Мародин и забрать у него мундштук.И вот когда ты протрубишь в рог, кентавры явятся на бой, и тебе придется убивать их, пока не доберешься до самого Храты. А у Храты есть фрагмент ключа. Он нужен мне, этот фрагмент. Принеси его. Принеси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Для поддержания отношений с племенем Маграм принесите фрагмент Ключа Мародина Варугу в деревню Маграм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вождь Храта мертв! Теперь Маграм – сильнейшее из племен! Мы сокрушим всех! Мы будем править в Пустошах!$B$BМы не забудем тебя, $N, и в тот час, когда сотни будут гибнуть под нашими копытами, мы пощадим тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сделай, что я говорю. Докажи, что ты – достойный союзник племени Маграм!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варугу в деревню Маграм, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1382,'Странный союз','На наше счастье, племена кентавров постоянно враждуют. Если бы они объединились, никто не сумел бы их остановить. Да, нам сильно повезло – и мы должны обратить это везение себе на пользу.$B$BПлемя Гелкис ведет жестокую войну с племенем Маграм. Если мы атакуем поселение Маграм, то, возможно, сумеем заключить союз с племенем Гелкис.$B$BВ юго-западной части Пустошей, неподалеку от лагерей племени Гелкис, ты сможешь найти Уту Мудрую. Возможно, поговорив с ней, ты сумеешь заключить союз...','Заслужите дружественное отношение племени Гелкис, а затем поговорите с Утой Мудрой.','В племени Гелкис говорят о тебе. Твои руки в крови проклятых Маграм. Это хорошо.$B$BЯ буду говорить с тобой. Скажи, что ты можешь сделать для племени Гелкис – и что племя может сделать для тебя.','Прочь! Кентавры племени Гелкис не желают видеть тебя! Уходи!$B$BИди, убей Маграм, много Маграм – тогда будем говорить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странный союз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На наше счастье, племена кентавров постоянно враждуют. Если бы они объединились, никто не сумел бы их остановить. Да, нам сильно повезло – и мы должны обратить это везение себе на пользу.$B$BПлемя Гелкис ведет жестокую войну с племенем Маграм. Если мы атакуем поселение Маграм, то, возможно, сумеем заключить союз с племенем Гелкис.$B$BВ юго-западной части Пустошей, неподалеку от лагерей племени Гелкис, ты сможешь найти Уту Мудрую. Возможно, поговорив с ней, ты сумеешь заключить союз...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заслужите дружественное отношение племени Гелкис, а затем поговорите с Утой Мудрой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В племени Гелкис говорят о тебе. Твои руки в крови проклятых Маграм. Это хорошо.$B$BЯ буду говорить с тобой. Скажи, что ты можешь сделать для племени Гелкис – и что племя может сделать для тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прочь! Кентавры племени Гелкис не желают видеть тебя! Уходи!$B$BИди, убей Маграм, много Маграм – тогда будем говорить.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1383,'Правда и только правда','Я знаю подходящую сыворотку. Она обойдется с правдой именно так, как с ней следует обходиться.$B$BЧтобы сделать ее, мне понадобится несколько сердец пантер тени из болота. Кроме того, мне нужен мох хозяина болота, обитающего неподалеку. Не сомневаюсь, что ты сумеешь уговорить его поделиться с тобой.$B$BИ последнее, что необходимо мне для составления сыворотки, это кровь мечтательного дракончика, вроде тех, что живут рядом с пещерой Итара в болоте.$b$bА теперь иди!','Принесите аптекарю Фаустину в Приют Бродяги 5 сердец пантер тени, мох хозяина болота и немного крови зеленого дракончика.','Великолепно, $N! И как раз вовремя. Судя по тому, что говорит Зредус, лазутчик оправился от ран и готов к допросу.$B$BПогоди, сейчас я приготовлю отра... то есть сыворотку правды.','Лазутчик в Каменоре несомненно... расколется... после того, как напьется моей сыворотки. Ха-ха!$B$BОднако компоненты достать сложно. Пантеры Тени часто встречаются на Болоте, но собрать достаточно сердец – непростая задача. А хозяин болота может быть очень несговорчивым.$B$BДа и достать опухоль странника глубин – та еще задачка, но зато с ней можно провести такую реакцию, что мало не покажется.','Вернитесь к аптекарю Фаустину в Поместье Мистмантла, что в Сумеречном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правда и только правда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю подходящую сыворотку. Она обойдется с правдой именно так, как с ней следует обходиться.$B$BЧтобы сделать ее, мне понадобится несколько сердец пантер тени из болота. Кроме того, мне нужен мох хозяина болота, обитающего неподалеку. Не сомневаюсь, что ты сумеешь уговорить его поделиться с тобой.$B$BИ последнее, что необходимо мне для составления сыворотки, это кровь мечтательного дракончика, вроде тех, что живут рядом с пещерой Итара в болоте.$b$bА теперь иди!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите аптекарю Фаустину в Приют Бродяги 5 сердец пантер тени, мох хозяина болота и немного крови зеленого дракончика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, $N! И как раз вовремя. Судя по тому, что говорит Зредус, лазутчик оправился от ран и готов к допросу.$B$BПогоди, сейчас я приготовлю отра... то есть сыворотку правды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лазутчик в Каменоре несомненно... расколется... после того, как напьется моей сыворотки. Ха-ха!$B$BОднако компоненты достать сложно. Пантеры Тени часто встречаются на Болоте, но собрать достаточно сердец – непростая задача. А хозяин болота может быть очень несговорчивым.$B$BДа и достать опухоль странника глубин – та еще задачка, но зато с ней можно провести такую реакцию, что мало не покажется.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Фаустину в Поместье Мистмантла, что в Сумеречном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1384,'Набег на племя Колкар','Кентавры из племени Колкар полагают, что сильны в магии. Они ничего не понимают в магии! Они не распознают ее, даже если их носом в магию ткнуть!..$B$BКто-то должен доказать им, что в отношении магии они просто дети неразумные. Думаю, этим кем-то будешь ты. Отправляйся в деревню Колкар, что на северо-восток отсюда. Отними у кентавров их обереги и принеси их мне. Я брошу их в огонь, и это согреет мне сердце.','Для поддержания отношений с племенем Гелкис принесите 10 грубых оберегов Уте Мудрой в деревню Гелкис.','Ты $Gсделал:сделала; доброе дело для племени Гелкис. Клан Колкар слаб, он обречен и сгинет. Их жалкая магия не поможет им. Ты $Gпоказал:показала; им это – и страх сделает их еще слабее!$B$BВ этих землях слабаки долго не живут.','Где обереги? Они у тебя? Теперь-то эти кентавры поняли, как они слабы?','Вернитесь к Уте Мудрой в деревню Гелкис, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Набег на племя Колкар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кентавры из племени Колкар полагают, что сильны в магии. Они ничего не понимают в магии! Они не распознают ее, даже если их носом в магию ткнуть!..$B$BКто-то должен доказать им, что в отношении магии они просто дети неразумные. Думаю, этим кем-то будешь ты. Отправляйся в деревню Колкар, что на северо-восток отсюда. Отними у кентавров их обереги и принеси их мне. Я брошу их в огонь, и это согреет мне сердце.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Для поддержания отношений с племенем Гелкис принесите 10 грубых оберегов Уте Мудрой в деревню Гелкис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсделал:сделала; доброе дело для племени Гелкис. Клан Колкар слаб, он обречен и сгинет. Их жалкая магия не поможет им. Ты $Gпоказал:показала; им это – и страх сделает их еще слабее!$B$BВ этих землях слабаки долго не живут.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где обереги? Они у тебя? Теперь-то эти кентавры поняли, как они слабы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уте Мудрой в деревню Гелкис, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1385,'Политика силы','Пустоши – земля, пожираемая огнем войны. Кентавры враждуют между собой; мы страшимся того, что победившее племя пойдет войной на наши крепости и разрушит их. Мы не можем этого допустить.$B$BМы должны научиться побеждать кентавров, а для этого нам придется заключить союз с одним из их племен. Племя Маграм издревле враждует с племенем Гелкис. Если ты начнешь войну с племенем Гелкис, возможно, племя Маграм задумается о том, что неплохо бы иметь такого воина на своей стороне.$B$BЗавоюй расположение племени Маграм, а затем отправляйся в деревню племени в юго-восточной части Пустошей и поговори с Варугом.','Заслужите дружественное отношение племени Маграм, а затем поговорите с Варугом.','Многие из племени Гелкис пали от твоей руки. Мне это нравится. Может, ты сумеешь сделать что-то еще, что мне понравится. Может, ты сумеешь стать другом племени Маграм.','Уходи прочь, не то Маграм сокрушат тебя! Хочешь стать нашим другом – убивай кентавров племени Гелкис!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Политика силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пустоши – земля, пожираемая огнем войны. Кентавры враждуют между собой; мы страшимся того, что победившее племя пойдет войной на наши крепости и разрушит их. Мы не можем этого допустить.$B$BМы должны научиться побеждать кентавров, а для этого нам придется заключить союз с одним из их племен. Племя Маграм издревле враждует с племенем Гелкис. Если ты начнешь войну с племенем Гелкис, возможно, племя Маграм задумается о том, что неплохо бы иметь такого воина на своей стороне.$B$BЗавоюй расположение племени Маграм, а затем отправляйся в деревню племени в юго-восточной части Пустошей и поговори с Варугом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заслужите дружественное отношение племени Маграм, а затем поговорите с Варугом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Многие из племени Гелкис пали от твоей руки. Мне это нравится. Может, ты сумеешь сделать что-то еще, что мне понравится. Может, ты сумеешь стать другом племени Маграм.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уходи прочь, не то Маграм сокрушат тебя! Хочешь стать нашим другом – убивай кентавров племени Гелкис!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1386,'Нападение на племя Колкар','Клан Колкар полагает, что он силен; мы смеемся над ними – и убиваем их со смехом! Ты тоже их убиваешь. Покажи, что умеешь убивать их не хуже, чем мы. Клан Колкар должен умереть. Иди на север. Убей их. Убей их всех!','Для поддержания отношений с племенем Маграм вы должны убить 12 кентавров из племени Колкар, 12 разведчиков из племени Колкар и 6 извергов из племени Колкар, а затем вернуться к Варугу в деревню Маграм.','Теперь клан Колкар страшится тебя. Скажи, ты $Gсмеялся:смеялась;, когда убивал их? Когда убиваешь, надо смеяться, тогда враги увидят, что они слабы.','Вы боитесь Колкара? Почему ты их не убиваешь? Может ты $Gразучился:разучилась; убивать. Поторопись и убей Колкара, пока они не умерли!','Вернитесь к Варугу в деревню Маграм, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на племя Колкар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Колкар полагает, что он силен; мы смеемся над ними – и убиваем их со смехом! Ты тоже их убиваешь. Покажи, что умеешь убивать их не хуже, чем мы. Клан Колкар должен умереть. Иди на север. Убей их. Убей их всех!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Для поддержания отношений с племенем Маграм вы должны убить 12 кентавров из племени Колкар, 12 разведчиков из племени Колкар и 6 извергов из племени Колкар, а затем вернуться к Варугу в деревню Маграм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь клан Колкар страшится тебя. Скажи, ты $Gсмеялся:смеялась;, когда убивал их? Когда убиваешь, надо смеяться, тогда враги увидят, что они слабы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы боитесь Колкара? Почему ты их не убиваешь? Может ты $Gразучился:разучилась; убивать. Поторопись и убей Колкара, пока они не умерли!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варугу в деревню Маграм, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1387,'Награда за кентавров','Раса кентавров состоит из множества кланов. У каждого из них – свой вождь и свои законы, но есть одна черта, которая объединяет их всех: жестокость.$B$BЕсли мы хотим обрести мир, нам следует изгнать кентавров из этих земель. Тебе предстоит исполнить это нелегкое задание.$B$BВ своих странствиях по Пустоши ты будешь убивать кентавров и собирать их уши. Чем больше ушей, тем лучше. Принеси их мне.$B$BЕсли, $n, ты исполнишь это во славу и во имя Альянса, мы будем на шаг ближе к завершению этой войны.','Принесите в город Высота Найджела 15 ушей кентавров и отдайте их капралу Мелкису.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда за кентавров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раса кентавров состоит из множества кланов. У каждого из них – свой вождь и свои законы, но есть одна черта, которая объединяет их всех: жестокость.$B$BЕсли мы хотим обрести мир, нам следует изгнать кентавров из этих земель. Тебе предстоит исполнить это нелегкое задание.$B$BВ своих странствиях по Пустоши ты будешь убивать кентавров и собирать их уши. Чем больше ушей, тем лучше. Принеси их мне.$B$BЕсли, $n, ты исполнишь это во славу и во имя Альянса, мы будем на шаг ближе к завершению этой войны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите в город Высота Найджела 15 ушей кентавров и отдайте их капралу Мелкису.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1388,'Правда и только правда','Я знал, что старина Фаустин что-нибудь придумает! Ты ему очень $Gпомог:помогла;, я даже не сомневаюсь.$B$BА теперь к делу, верно?','Не сомневаюсь, что ты очень помог нашему дорогому другу, аптекарю Фаустину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правда и только правда',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знал, что старина Фаустин что-нибудь придумает! Ты ему очень $Gпомог:помогла;, я даже не сомневаюсь.$B$BА теперь к делу, верно?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не сомневаюсь, что ты очень помог нашему дорогому другу, аптекарю Фаустину.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1389,'Кристаллы дренетиста','Заблудшие, живущие в Болотном пристанище, на вид ничем от нас не отличаются, но на самом деле это чудовища... лишившиеся рассудка в пути до Азерота. Когда-то они были нашими братьями. Теперь они живут в Болотном пристанище, к востоку отсюда, захватывая и убивая любого, кто попадется под руку.$B$BСейчас они украли одну из наших святынь – кристаллы дренетиста.$B$BУ нас не хватает сил ворваться в Святилище и вернуть себе нашу реликвию, но без нее... мы тоже вскоре утратим свой путь.','Принесите 6 кристаллов дренетиста Магтуру в Убежище в Болоте Печали.','Благодарю тебя, $N. Мы перед тобой в долгу.','Ну, и где кристаллы?','Вернитесь к Магтуру на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристаллы дренетиста',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Заблудшие, живущие в Болотном пристанище, на вид ничем от нас не отличаются, но на самом деле это чудовища... лишившиеся рассудка в пути до Азерота. Когда-то они были нашими братьями. Теперь они живут в Болотном пристанище, к востоку отсюда, захватывая и убивая любого, кто попадется под руку.$B$BСейчас они украли одну из наших святынь – кристаллы дренетиста.$B$BУ нас не хватает сил ворваться в Святилище и вернуть себе нашу реликвию, но без нее... мы тоже вскоре утратим свой путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 кристаллов дренетиста Магтуру в Убежище в Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, $N. Мы перед тобой в долгу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, и где кристаллы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Магтуру на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1390,'<nyi> Упал на нож и так семь раз.','Спасибо за проделанную работу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<nyi> Упал на нож и так семь раз.',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за проделанную работу!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1391,'Правда и только правда','Мы должны действовать тайно. В конце концов ты же не можешь войти и заставить этого олуха выпить состав Фаустина?$B$BНо от выпивки ни один человек не откажется. Я возьму сыворотку Фаустина и замешаю ее в эль. Сомнений нет, бедняга без колебаний выпьет предложенную бурду.$B$BСпеши в Каменор на Болото Печали, $n. И никому не рассказывай о нашем задании...','Отнесите бражку Зредуса секретному агенту Марксену в Каменор.','Ты $Gпринес:принесла; мне попить? Как мило с твоей стороны. Мне не давали даже губы смочить вот уже несколько дней. Позволь мне утолить жажду, и я расскажу обо всем, что узнал...','Прошу, смилуйся надо мной! У меня есть сведения, которые не касаются Альянса. Хотя я не сторонник Орды, вы столкнулись с предательством, которое я хочу разоблачить!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правда и только правда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны действовать тайно. В конце концов ты же не можешь войти и заставить этого олуха выпить состав Фаустина?$B$BНо от выпивки ни один человек не откажется. Я возьму сыворотку Фаустина и замешаю ее в эль. Сомнений нет, бедняга без колебаний выпьет предложенную бурду.$B$BСпеши в Каменор на Болото Печали, $n. И никому не рассказывай о нашем задании...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите бражку Зредуса секретному агенту Марксену в Каменор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпринес:принесла; мне попить? Как мило с твоей стороны. Мне не давали даже губы смочить вот уже несколько дней. Позволь мне утолить жажду, и я расскажу обо всем, что узнал...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прошу, смилуйся надо мной! У меня есть сведения, которые не касаются Альянса. Хотя я не сторонник Орды, вы столкнулись с предательством, которое я хочу разоблачить!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1392,'Нобору Дубина','Нобору много месяцев не давал житья дренеям Прибежища, и его дубина стала символом жестокости, которую они претерпели от рук Заблудших.','Принесите дубину Нобору главе Убежища на Болото Печали.','Приветствую. И добро пожаловать в Убежище!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нобору Дубина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нобору много месяцев не давал житья дренеям Прибежища, и его дубина стала символом жестокости, которую они претерпели от рук Заблудших.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите дубину Нобору главе Убежища на Болото Печали.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую. И добро пожаловать в Убежище!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (1393,'Побег Галена','Помогите! Эти твари хотят меня съесть!$B$BЕсли ты поможешь мне выбраться отсюда, то получишь великое сокровище! Оно лежит в моем лагере, в болотах к северу от Каменора, но только я знаю, как открыть сейф, в котором оно находится.$B$BЕсли ты поможешь мне, я научу тебя, как открыть этот сейф.','Замочная скважина этого сейфа залита черной смолой. Открыть его невозможно.\n\nНо Гален рассказал вам о секретном замке на днище сейфа... \n\n... Быстро осмотрев сейф, вы находите задвижку. Задвижка отодвинута, и сейф открывается.','Выведите Галена из Болотного пристанища.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег Галена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помогите! Эти твари хотят меня съесть!$B$BЕсли ты поможешь мне выбраться отсюда, то получишь великое сокровище! Оно лежит в моем лагере, в болотах к северу от Каменора, но только я знаю, как открыть сейф, в котором оно находится.$B$BЕсли ты поможешь мне, я научу тебя, как открыть этот сейф.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замочная скважина этого сейфа залита черной смолой. Открыть его невозможно.\n\nНо Гален рассказал вам о секретном замке на днище сейфа... \n\n... Быстро осмотрев сейф, вы находите задвижку. Задвижка отодвинута, и сейф открывается.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Выведите Галена из Болотного пристанища.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1394,'Финальное испытание','Ты хорошо $gсправился:справилась;, $n. Ты $gпрошел:прошла; все мои испытания и те, что были до этого. Возвращайся к Дорну в Тысячу Игл. Он непременно заметит перемены, произошедшие с твоим телом, разумом и духом, и поймет, что твои усилия достойны награды.$B$BВсегда храни в себе ту гармонию, которой ты $gдостиг:достигла; в этих испытаниях, $n, и тогда в будущем Дорн сможет испытать тебя еще раз.','Поговорите с Дорном Вольным Ловчим в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Финальное испытание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты хорошо $gсправился:справилась;, $n. Ты $gпрошел:прошла; все мои испытания и те, что были до этого. Возвращайся к Дорну в Тысячу Игл. Он непременно заметит перемены, произошедшие с твоим телом, разумом и духом, и поймет, что твои усилия достойны награды.$B$BВсегда храни в себе ту гармонию, которой ты $gдостиг:достигла; в этих испытаниях, $n, и тогда в будущем Дорн сможет испытать тебя еще раз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дорном Вольным Ловчим в Тысяче Игл.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1395,'Поставки для Стражей Пустоты','Этот ящик с камнями силы нужно доставить в Крепость Стражей Пустоты, в Выжженные земли. Их сила будет сохраняться не так-то долго, так что мы не можем отправить их следующим караваном. $B$BТебе следует отнести их как можно скорее.$B$BОтдай их интенданту Лунгерцу в Крепости Стражей Пустоты. Чтобы достичь крепости, тебе следует направиться на восток через Перевал Мертвого Ветра, затем далее через Болото Печали, потом свернуть на юг через Выжженные земли.$B$BОднако осторожнее, $n. Твой путь проляжет через опасные земли, но цель должна быть достигнута.','Отнесите ящик камней силы интенданту Лунгерцу, прежде чем камни утратят силу.','Приветствую! Не обращай внимания на всю эту суматоху, это обычное дело в Крепости Стражей Пустоты.$B$BУ тебя что-то для меня есть?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поставки для Стражей Пустоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот ящик с камнями силы нужно доставить в Крепость Стражей Пустоты, в Выжженные земли. Их сила будет сохраняться не так-то долго, так что мы не можем отправить их следующим караваном. $B$BТебе следует отнести их как можно скорее.$B$BОтдай их интенданту Лунгерцу в Крепости Стражей Пустоты. Чтобы достичь крепости, тебе следует направиться на восток через Перевал Мертвого Ветра, затем далее через Болото Печали, потом свернуть на юг через Выжженные земли.$B$BОднако осторожнее, $n. Твой путь проляжет через опасные земли, но цель должна быть достигнута.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик камней силы интенданту Лунгерцу, прежде чем камни утратят силу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую! Не обращай внимания на всю эту суматоху, это обычное дело в Крепости Стражей Пустоты.$B$BУ тебя что-то для меня есть?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1396,'Атака тварей','Мой караван направлялся к восточному побережью, но до места так и не добрался. Заблудшие атаковали нас, перебив стражу и уничтожив припасы.$B$BВыжить удалось только мне. Я обещал сохранить оставшиеся товары, но вокруг полно чудовищ. Прошу тебя, помоги мне защитить мой лагерь!','Убейте 8 молодых острозубых кроколисков, 10 ткачей скорби и 10 болотных ягуаров и потом вернитесь к дозорному Биггсу на Болоте Печали.','Судя по звукам, твари убрались. Благодарю тебя, $N. Теперь-то, надеюсь, они не вернутся!','Болотные твари наседают, $N. Ты $Gдолжен:должна; спасти лагерь!','Вернитесь к дозорному Биггсу на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака тварей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой караван направлялся к восточному побережью, но до места так и не добрался. Заблудшие атаковали нас, перебив стражу и уничтожив припасы.$B$BВыжить удалось только мне. Я обещал сохранить оставшиеся товары, но вокруг полно чудовищ. Прошу тебя, помоги мне защитить мой лагерь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 молодых острозубых кроколисков, 10 ткачей скорби и 10 болотных ягуаров и потом вернитесь к дозорному Биггсу на Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Судя по звукам, твари убрались. Благодарю тебя, $N. Теперь-то, надеюсь, они не вернутся!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Болотные твари наседают, $N. Ты $Gдолжен:должна; спасти лагерь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Биггсу на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1397,'<nyi> Спасены!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<nyi> Спасены!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1398,'Плавник','Я – твой должник,$n, В твоей груди бьется великодушное сердце. А теперь – смею ли еще раз попросить тебя о помощи?$B$BЧтобы добраться до Стражей Пустоты, я должен починить эту повозку, а для этого мне необходимо дерево. Сухое, прямое дерево, а не те рыхлые и скрюченные кусты, которые растут на болотах.$B$BОтправляйся на восточное побережье, поищи там плавник хорошо просушенный солнцем и принеси его мне.','Принести 8 кусков сухого плавника дозорному Биггсу на Болоте Печали.','Дерево легкое, но крепкое. Спасибо, $N, это подойдет.','Ты $Gнашел:нашла; хоть немного плавника, $N?','Вернитесь к дозорному Биггсу на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плавник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я – твой должник,$n, В твоей груди бьется великодушное сердце. А теперь – смею ли еще раз попросить тебя о помощи?$B$BЧтобы добраться до Стражей Пустоты, я должен починить эту повозку, а для этого мне необходимо дерево. Сухое, прямое дерево, а не те рыхлые и скрюченные кусты, которые растут на болотах.$B$BОтправляйся на восточное побережье, поищи там плавник хорошо просушенный солнцем и принеси его мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принести 8 кусков сухого плавника дозорному Биггсу на Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дерево легкое, но крепкое. Спасибо, $N, это подойдет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; хоть немного плавника, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Биггсу на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1418,'Ника Алый Шрам','Бесплодные земли суровы. Они примыкают к территории Альянса возле озера Лок Модан, потому сообщение между Каменором и форпостом Каргата часто оказывается перерезанным. $n, у тебя есть шанс проявить себя. Отправляйся в Бесплодные земли и поговори с Никой Алый Шрам, главой разведчиков Каргатского форпоста, а затем принеси мне ее доклад.','Поговорите с Никой Алый Шрам.','Хелгруму нужен доклад, а? Я посылала гонца в Каменор около трех дней назад. Он что, не добрался? Если в Каменоре нет моего донесения, сдается мне, гонец сгинул. Будем надеяться, что следующий, кого я пошлю, будет лучше подготовлен, ну или более удачлив.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ника Алый Шрам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бесплодные земли суровы. Они примыкают к территории Альянса возле озера Лок Модан, потому сообщение между Каменором и форпостом Каргата часто оказывается перерезанным. $n, у тебя есть шанс проявить себя. Отправляйся в Бесплодные земли и поговори с Никой Алый Шрам, главой разведчиков Каргатского форпоста, а затем принеси мне ее доклад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Никой Алый Шрам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хелгруму нужен доклад, а? Я посылала гонца в Каменор около трех дней назад. Он что, не добрался? Если в Каменоре нет моего донесения, сдается мне, гонец сгинул. Будем надеяться, что следующий, кого я пошлю, будет лучше подготовлен, ну или более удачлив.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1419,'Койоты-воры','Ну и как тебе Бесплодные земли, |3-6($c)? Жара, пылища, стаи всяких тварей? У тебя есть шанс прочувствовать все прелести этих земель еще лучше.$B$BСкальные койоты – наглые твари. Наглые настолько, что пробираются в Каргат и воруют наши припасы. Помоги нам избавиться от них!$B$BПринеси мне их челюсти, если ты соберешь достаточно много, я поверю, что ты и вправду знаешь Бесплодные земли.','Принесите 30 челюстей койотов Нике Алый Шрам в Каргат.','Впечатляющий набор челюстей, $N. Теперь-то эти койоты поостерегутся подбираться к нашим припасам.$B$BОтлично! Койоты из Бесплодных земель – не такая уж легкая добыча. Теперь я уверена – ты сможешь тут выжить.','Ты $Gпринес:принесла; челюсти?','[Deprecated] Return to Neeka Bloodscar at Kargath in Badlands.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Койоты-воры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну и как тебе Бесплодные земли, |3-6($c)? Жара, пылища, стаи всяких тварей? У тебя есть шанс прочувствовать все прелести этих земель еще лучше.$B$BСкальные койоты – наглые твари. Наглые настолько, что пробираются в Каргат и воруют наши припасы. Помоги нам избавиться от них!$B$BПринеси мне их челюсти, если ты соберешь достаточно много, я поверю, что ты и вправду знаешь Бесплодные земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 30 челюстей койотов Нике Алый Шрам в Каргат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляющий набор челюстей, $N. Теперь-то эти койоты поостерегутся подбираться к нашим припасам.$B$BОтлично! Койоты из Бесплодных земель – не такая уж легкая добыча. Теперь я уверена – ты сможешь тут выжить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; челюсти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Neeka Bloodscar at Kargath in Badlands.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1420,'Донесение Хелгруму','Я написала новое донесение для Хелгрума из Каменора, отнеси его ему. $B$BИ если ты считаешь себя гонцом – не сбейся с пути и не попадись врагам!','Отнесите донесение Ники Хелгруму Быстроногому в Каменор.','Благодарю тебя, $N. Из донесения Ники я понял, что Альянс озабочен собственными проблемами, и, может статься, что кое-какие враги у нас общие.','Ты $Gвернулся:вернулась;! Донесение при тебе?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение Хелгруму',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я написала новое донесение для Хелгрума из Каменора, отнеси его ему. $B$BИ если ты считаешь себя гонцом – не сбейся с пути и не попадись врагам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите донесение Ники Хелгруму Быстроногому в Каменор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, $N. Из донесения Ники я понял, что Альянс озабочен собственными проблемами, и, может статься, что кое-какие враги у нас общие.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;! Донесение при тебе?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1421,'Пропавший караван','Я был оглушен во время атаки Заблудших, но, прежде чем потерять сознание, я видел, как одну из наших повозок угоняли к Болотному пристанищу, поселению Заблудших на севере.$B$BВ этой повозке находился сундук с наиболее ценными реагентами, предназначающимися для магов Крепости Стражей Пустоты. $n, найди сундук, добудь эти реактивы и верни их мне.','Найдите похищенный из каравана сундук в Болотном пристанище, добудьте реагенты магов и принесите их дозорному Биггсу.','Браво! С этими реактивами волшебники Крепости Стражей Пустоты смогут продолжить работу. Я не знаю, чем они там занимаются, знаю только, что это связано с Темным порталом в Бесплодных землях и напрямую касается безопасности всего Альянса.','Ты $Gдостал:достала; реактивы, $N?','Вернитесь к дозорному Биггсу на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший караван',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я был оглушен во время атаки Заблудших, но, прежде чем потерять сознание, я видел, как одну из наших повозок угоняли к Болотному пристанищу, поселению Заблудших на севере.$B$BВ этой повозке находился сундук с наиболее ценными реагентами, предназначающимися для магов Крепости Стражей Пустоты. $n, найди сундук, добудь эти реактивы и верни их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите похищенный из каравана сундук в Болотном пристанище, добудьте реагенты магов и принесите их дозорному Биггсу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Браво! С этими реактивами волшебники Крепости Стражей Пустоты смогут продолжить работу. Я не знаю, чем они там занимаются, знаю только, что это связано с Темным порталом в Бесплодных землях и напрямую касается безопасности всего Альянса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдостал:достала; реактивы, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Биггсу на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1422,'Угроза с моря','Пока я буду работть над твоим оружием, почему бы тебе не поговорить с Катором? Он, говорил, что ему нужна помощь с патрулированием побережья, и тебе бы лучше поддерживать боевую форму, а не напиваться с теми недоделками, что торчат в нашем лагере.','Поговорите с Катором на Болоте Печали.','Помолчи немного, |3-6($C). Даже сквозь глухой рокот моря все еще слышно отвратительное бульканье, заменяющее рыболюдям речь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза с моря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока я буду работть над твоим оружием, почему бы тебе не поговорить с Катором? Он, говорил, что ему нужна помощь с патрулированием побережья, и тебе бы лучше поддерживать боевую форму, а не напиваться с теми недоделками, что торчат в нашем лагере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Катором на Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Помолчи немного, |3-6($C). Даже сквозь глухой рокот моря все еще слышно отвратительное бульканье, заменяющее рыболюдям речь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1423,'Потерянные припасы','Этот бочонок мал, зато прочен. Его швы залиты желтым пахучим воском, а на торце выдавлены слова:$B$BИНТЕНДАНТ ЛУНГЕРЦ$B$BКРЕПОСТЬ СТРАЖЕЙ ПУСТОТЫ','Принесите потерянные припасы интенданту Лунгерцу.','У тебя что-то есть для меня?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянные припасы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот бочонок мал, зато прочен. Его швы залиты желтым пахучим воском, а на торце выдавлены слова:$B$BИНТЕНДАНТ ЛУНГЕРЦ$B$BКРЕПОСТЬ СТРАЖЕЙ ПУСТОТЫ',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите потерянные припасы интенданту Лунгерцу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя что-то есть для меня?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1424,'Озеро Слез','Вождь послал нас разузнать, что творится в Храме Атал\'Хаккара.$B$BТролли Атал\'ай – племя темных заклинателей, известных тем, что используют запретную магию. Можешь себе представить, как мы были поражены, когда узнали что храм затоплен.$B$BТеперь его сторожат зеленые драконы, которые утверждают, что они защитники Азерота.$B$BМы должны выяснить, что произошло. Исследуй окрестности озера Слез и собери артефакты Атал\'ай. С их помощью я смогу собрать всю картину воедино.','Соберите 5 артефактов Атал\'ай для Фелзерула из Каменора.','Твое усердие в происках артефактов Аталаи достойно похвалы, |3-6($C).','Никто не знает, что темные обряды творились в Храме Атал\'Хаккара. Но мы знаем, что там применялись мощные чары.$B$BИ мы должны выяснить все, что сможем, об этой магии. Возможно, заклинания Атал\'ай будут полезны и Орде.$B$BКак только ты принесешь достаточно артефактов Атал\'ай в окрестностях озера Слез, мы поймем, что замышляли тролли и что именно привело к такому исходу.','Вернитесь к Фел\'зерулу на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Озеро Слез',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вождь послал нас разузнать, что творится в Храме Атал\'Хаккара.$B$BТролли Атал\'ай – племя темных заклинателей, известных тем, что используют запретную магию. Можешь себе представить, как мы были поражены, когда узнали что храм затоплен.$B$BТеперь его сторожат зеленые драконы, которые утверждают, что они защитники Азерота.$B$BМы должны выяснить, что произошло. Исследуй окрестности озера Слез и собери артефакты Атал\'ай. С их помощью я смогу собрать всю картину воедино.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 артефактов Атал\'ай для Фелзерула из Каменора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твое усердие в происках артефактов Аталаи достойно похвалы, |3-6($C).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Никто не знает, что темные обряды творились в Храме Атал\'Хаккара. Но мы знаем, что там применялись мощные чары.$B$BИ мы должны выяснить все, что сможем, об этой магии. Возможно, заклинания Атал\'ай будут полезны и Орде.$B$BКак только ты принесешь достаточно артефактов Атал\'ай в окрестностях озера Слез, мы поймем, что замышляли тролли и что именно привело к такому исходу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фел\'зерулу на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1425,'Доставка груза','Пока я чиню эту повозку, $n, выполни для меня еще одно, последнее задание. $B$BЯ собрал наиболее важные припасы, уцелевшие после набегов огров. Доставь их в Крепость Стражей Пустоты. Она выстроена в холмах, на севере Выжженных земель, для наблюдения за Темным порталом.$B$BДобраться туда можно по восточной дороге. Когда она разветвится, сверни на юг к Выжженным землям, а потом налево на следующей развилке. Не сходи с дороги,$n, и не теряй бдительности','Доставьте груз в Крепость Стражей Пустоты интенданту Лунгерцу.','Что? Груз из каравана Биггса? Мы думали, он пропал вместе с караваном.$B$BСпасибо, $N. Надеюсь там кристаллы Азоры, этот реактив, нам крайне необходим, а наш запас подходит к концу.','У тебя ко мне какое-то дело?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка груза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока я чиню эту повозку, $n, выполни для меня еще одно, последнее задание. $B$BЯ собрал наиболее важные припасы, уцелевшие после набегов огров. Доставь их в Крепость Стражей Пустоты. Она выстроена в холмах, на севере Выжженных земель, для наблюдения за Темным порталом.$B$BДобраться туда можно по восточной дороге. Когда она разветвится, сверни на юг к Выжженным землям, а потом налево на следующей развилке. Не сходи с дороги,$n, и не теряй бдительности',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте груз в Крепость Стражей Пустоты интенданту Лунгерцу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Груз из каравана Биггса? Мы думали, он пропал вместе с караваном.$B$BСпасибо, $N. Надеюсь там кристаллы Азоры, этот реактив, нам крайне необходим, а наш запас подходит к концу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя ко мне какое-то дело?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1426,'Угроза с моря','Мне не нравится ни море, ни твари, что лезут из его глубин. Море могущественно, но слепо, бесчувственно и жестоко. С какой радостью я истреблял бы этих рыболюдей сотнями, будь у меня возможность. Но мне принесет и некоторую радость зрелище их гибели от рук тех, кто выполняет волю Орды.$B$BОт твоих рук, |3-6($c). Скольких ты сможешь убить? Хочешь ли рискнуть и сразиться с сильнейшими из них?','Убейте 10 болотных мурлоков, 10 болотных чернильщиков и 10 болотных трупоедов, затем вернитесь к Котору в Болото Печали.','Море безбрежно и безжалостно, но ты $Gзапятнал:запятнала; его кровью его собственных порождений. Рыболюди знают, что такое боль. Их тупость заставит их сплотить ряды после того разгрома, который ты им $Gучинил:учинила;, и это хорошо.$B$BПусть их булькающие крики заглушают шум моря по ночам. А я буду улыбаться каждый раз как услышу, что кто-то из них замолк.$B$BВозвращайся ко мне, если вдруг захочется поубивать еще рыболюдей. Я с удовольствием тебя вознагражу за это.','Я терпелив. Терпелив и вечен как старая замшелая каменюга с Дренора. Рыболюди больше не потревожат наших границ, по крайней мере, пока я жив. Будь у меня армия, я бы очистил этот мир, как и прочие миры, от этих тварей. Мне противно даже говорить о них.','Вернитесь к Катору на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза с моря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне не нравится ни море, ни твари, что лезут из его глубин. Море могущественно, но слепо, бесчувственно и жестоко. С какой радостью я истреблял бы этих рыболюдей сотнями, будь у меня возможность. Но мне принесет и некоторую радость зрелище их гибели от рук тех, кто выполняет волю Орды.$B$BОт твоих рук, |3-6($c). Скольких ты сможешь убить? Хочешь ли рискнуть и сразиться с сильнейшими из них?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 болотных мурлоков, 10 болотных чернильщиков и 10 болотных трупоедов, затем вернитесь к Котору в Болото Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Море безбрежно и безжалостно, но ты $Gзапятнал:запятнала; его кровью его собственных порождений. Рыболюди знают, что такое боль. Их тупость заставит их сплотить ряды после того разгрома, который ты им $Gучинил:учинила;, и это хорошо.$B$BПусть их булькающие крики заглушают шум моря по ночам. А я буду улыбаться каждый раз как услышу, что кто-то из них замолк.$B$BВозвращайся ко мне, если вдруг захочется поубивать еще рыболюдей. Я с удовольствием тебя вознагражу за это.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я терпелив. Терпелив и вечен как старая замшелая каменюга с Дренора. Рыболюди больше не потревожат наших границ, по крайней мере, пока я жив. Будь у меня армия, я бы очистил этот мир, как и прочие миры, от этих тварей. Мне противно даже говорить о них.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катору на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1427,'Угроза с моря','Прежде чем пойти отдохнуть, пообщайся с Ток\'Каром. Пока тебя не было, он, наверняка, закончил работу над обещанным тебе оружием. Было бы неплохо, если бы ты опробовал его на рыболюдях, когда созреешь...уж доставь мне удовольствие.','Поговорите с Ток\'Каром в Болоте Печали.','О! $N, ты $Gвернулся:вернулась;! Хорошо. Я как раз закончил партию оружия против мурлоков. За свежее мясо кусак и за то, что заставил Катара улыбаться, выбери себе одно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза с моря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем пойти отдохнуть, пообщайся с Ток\'Каром. Пока тебя не было, он, наверняка, закончил работу над обещанным тебе оружием. Было бы неплохо, если бы ты опробовал его на рыболюдях, когда созреешь...уж доставь мне удовольствие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ток\'Каром в Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О! $N, ты $Gвернулся:вернулась;! Хорошо. Я как раз закончил партию оружия против мурлоков. За свежее мясо кусак и за то, что заставил Катара улыбаться, выбери себе одно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1428,'Продолжающаяся угроза','Мне приятно видеть, что ненависть, которую ты испытываешь к рыболюдям, все растет, как и моя.$B$BНайди их на побережье, а потом когда битва будет закончена, возвращайся, и мы решим, как вознаградить тебя за усердие.','Убейте 10 болотных чернильщиков, 10 болотных трупоедов и 10 болотных оракулов, затем вернитесь к Котору в Болоте Печали.','Отлично, |3-6($C). Но мне мало этой крови. Пусть все рыболюди исчезнут с лица земли.','Только когда море и все его порождения, особенно эти отвратительные рыболюди упокоятся, я буду счастлив...','Вернитесь к Катору на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Продолжающаяся угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне приятно видеть, что ненависть, которую ты испытываешь к рыболюдям, все растет, как и моя.$B$BНайди их на побережье, а потом когда битва будет закончена, возвращайся, и мы решим, как вознаградить тебя за усердие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 болотных чернильщиков, 10 болотных трупоедов и 10 болотных оракулов, затем вернитесь к Котору в Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, |3-6($C). Но мне мало этой крови. Пусть все рыболюди исчезнут с лица земли.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Только когда море и все его порождения, особенно эти отвратительные рыболюди упокоятся, я буду счастлив...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катору на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1429,'Изгнанник Атал\'ай','Пока ты $Gсражался:сражалась; с опасностями озера Слез, один из моих разведчиков вернулся со свитком из сушеного мяса с кровавыми письменами. Мне кажется это официальный приговор жрецу племени Атал\'ай. Этот жрец был приговорен племенем к участи худшей, чем смерть, – он был изгнан на север во Внутренние земли, жить среди троллей племени Сухокожих. Я соберу эти артефакты, а тебе предстоит найти изгнанника и выяснить их назначение. После этого возвращайся ко мне.','Принесите сверток с артефактами Атал\'ай к изгнаннику Атал\'ай во Внутренние земли.','Ты $Gпринес:принесла; мне артефакты призыва Атал\'ай? Я вижу, Джаммал\'ан Пророк ведет своих последователей из Чертога Крови навстречу выбранному ими року. Интересно, вернулся ли Хаккар в свой храм? Встретили ли они свою судьбу?','Для того чтобы прийти сюда, нужна большая смелость. Ну или большая глупость...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изгнанник Атал\'ай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $Gсражался:сражалась; с опасностями озера Слез, один из моих разведчиков вернулся со свитком из сушеного мяса с кровавыми письменами. Мне кажется это официальный приговор жрецу племени Атал\'ай. Этот жрец был приговорен племенем к участи худшей, чем смерть, – он был изгнан на север во Внутренние земли, жить среди троллей племени Сухокожих. Я соберу эти артефакты, а тебе предстоит найти изгнанника и выяснить их назначение. После этого возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сверток с артефактами Атал\'ай к изгнаннику Атал\'ай во Внутренние земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпринес:принесла; мне артефакты призыва Атал\'ай? Я вижу, Джаммал\'ан Пророк ведет своих последователей из Чертога Крови навстречу выбранному ими року. Интересно, вернулся ли Хаккар в свой храм? Встретили ли они свою судьбу?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Для того чтобы прийти сюда, нужна большая смелость. Ну или большая глупость...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1430,'Свежее мясо','Среди моих покупателей крайне высок спрос на сочное крабье мясо, особенно мясо чудовищного краба. $B$BЕсли ты планируешь направиться на побережье, то можешь еще и с выгодой прогуляться туда, если ты принесешь мне несколько крабьих ног, чтобы я переправил их в Оргриммар. $B$BПобережье находится к востоку отсюда, а крабы там просто кишат, что на берегу, что под водой.','Принесите 10 ног чудовищного краба Дару на Болото Печали.','О! Замечательно, я жду не дождусь, когда попробую крабье мясо, должным образом приготовленное на открытом огне. Возьми с собой в дорогу малую толику, вкус просто несравненный!','У меня тут бочонок вина ожидает твоего возвращения, $N, по мне товар прежде надо на вкус попробовать, а потом уж отсылать заказчику.','Вернитесь к Дару в Каменор, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свежее мясо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среди моих покупателей крайне высок спрос на сочное крабье мясо, особенно мясо чудовищного краба. $B$BЕсли ты планируешь направиться на побережье, то можешь еще и с выгодой прогуляться туда, если ты принесешь мне несколько крабьих ног, чтобы я переправил их в Оргриммар. $B$BПобережье находится к востоку отсюда, а крабы там просто кишат, что на берегу, что под водой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 ног чудовищного краба Дару на Болото Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О! Замечательно, я жду не дождусь, когда попробую крабье мясо, должным образом приготовленное на открытом огне. Возьми с собой в дорогу малую толику, вкус просто несравненный!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня тут бочонок вина ожидает твоего возвращения, $N, по мне товар прежде надо на вкус попробовать, а потом уж отсылать заказчику.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дару в Каменор, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1431,'Отношения с Альянсом','Слушай внимательно, |3-6($c). Мне нужно рассказать тебе кое-что, очень важное для нашего народа, но далеко не очевидное.$b$bМы – народ гордый, и война с людьми истощила даже терпение Тралла. Наш вождь мудр и рассудителен, и интересы нашего народа для него превыше всего. В то же время он тонкий дипломат. Он умеет обращаться с людьми.$b$bЕсли тебе это интересно, поговори с Кельдраном. Его лачуга стоит у западного входа в город.','Поговорите с Кельдрином в Оргриммаре.','Мы охотно приняли бы в дар шерстяную ткань. Если ты дашь нам 60 отрезов, Оргриммар будет тебе чрезвычайно признателен за щедрость. 60 отрезов нам вполне бы хватило – вместе с дарами от прочих пожертвователей этого было бы достаточно, чтобы продолжать работу.\n\nЕсли у тебя при себе имеется 60 отрезов шерсти и ты готов ее пожертвовать, я могу ее принять прямо сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отношения с Альянсом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай внимательно, |3-6($c). Мне нужно рассказать тебе кое-что, очень важное для нашего народа, но далеко не очевидное.$b$bМы – народ гордый, и война с людьми истощила даже терпение Тралла. Наш вождь мудр и рассудителен, и интересы нашего народа для него превыше всего. В то же время он тонкий дипломат. Он умеет обращаться с людьми.$b$bЕсли тебе это интересно, поговори с Кельдраном. Его лачуга стоит у западного входа в город.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кельдрином в Оргриммаре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы охотно приняли бы в дар шерстяную ткань. Если ты дашь нам 60 отрезов, Оргриммар будет тебе чрезвычайно признателен за щедрость. 60 отрезов нам вполне бы хватило – вместе с дарами от прочих пожертвователей этого было бы достаточно, чтобы продолжать работу.\n\nЕсли у тебя при себе имеется 60 отрезов шерсти и ты готов ее пожертвовать, я могу ее принять прямо сейчас.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1432,'Отношения с Альянсом','Альянс все расширяет свои владения в Калимдоре. Из-за этого может сложиться впечатление, что Орда вступает в союз с Пылающим Легионом. Вождь не может этого допустить. И я, с его благословения, буду отвечать за их изгнание.$b$bУ меня есть свои агенты в Пустошах, на Заставе Скитающихся Духов – это к северу от большого Кладбища кодо. Ступай на юг от Обугленной долины в Когтистых горах, и увидишь заставу. Когда прибудешь туда, разыщи Такату Стального Клинка.','Поговорите с Такатой Стальным Клинком в Пустошах.','Приветствую, |3-6($C)! У тебя есть вести из Оргриммара? Это хорошо.\n\nВ здешних краях все провоняло демонами – сильнее, чем кентавровым навозом. Конелюди вопят, что это их земли, но тут есть силы, с которыми им никак не справиться.\n\nПолучается, что мы вроде как помогаем кентаврам. Это мне не по нутру, но все это на благо Орды, так что я выполняю свой долг перед вождем, даже если ради этого приходится поддерживать чернокнижников.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отношения с Альянсом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянс все расширяет свои владения в Калимдоре. Из-за этого может сложиться впечатление, что Орда вступает в союз с Пылающим Легионом. Вождь не может этого допустить. И я, с его благословения, буду отвечать за их изгнание.$b$bУ меня есть свои агенты в Пустошах, на Заставе Скитающихся Духов – это к северу от большого Кладбища кодо. Ступай на юг от Обугленной долины в Когтистых горах, и увидишь заставу. Когда прибудешь туда, разыщи Такату Стального Клинка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Такатой Стальным Клинком в Пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую, |3-6($C)! У тебя есть вести из Оргриммара? Это хорошо.\n\nВ здешних краях все провоняло демонами – сильнее, чем кентавровым навозом. Конелюди вопят, что это их земли, но тут есть силы, с которыми им никак не справиться.\n\nПолучается, что мы вроде как помогаем кентаврам. Это мне не по нутру, но все это на благо Орды, так что я выполняю свой долг перед вождем, даже если ради этого приходится поддерживать чернокнижников.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1433,'Отношения с Альянсом','Чернокнижники Пылающего Клинка преданы злу до мозга костей. Души их осквернены, и единственный способ их остановить – это уничтожить.$b$bКельдрин отправил со мной Маурина, потому что он знает многое о Пылающем Клинке и разбирается в уловках чернокнижников.$b$bОн борется с Клинком, а на мою долю остаются прочие козни демонов тут, в Пустошах.$b$bПоговори с Маурином, он посвятит тебя в свои планы.','Поговорите с Маурином Костоломом в Пустошах.','Ах, да! Нам всегда пригодится помощь тех, кто предан вождю.\n\nМеня зовут Майрин. Я здесь по просьбе Кельдрина и нашего юного вождя, Тралла. Мальчику нужна помощь в борьбе против врагов, угрожающих его власти.\n\nПодойди-ка поближе, |3-6($C). Я изложу тебе свои планы касательно ликвидации этого гнойного нарыва, Пылающего Клинка.','Спутник-таурен предупредил меня, что сатиры – не совсем то, чем кажутся. Он считает, что зло в них исказило их истинную природу. Но сам я такого не видел.\n\nЯ вижу только, как они безжалостно убивают слабых и оскверняют души тех, кто обращается к темным силам.\n\nИ я буду уничтожать их, пока вождь не поручит мне другое дело. Жалости к ним я не испытываю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отношения с Альянсом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чернокнижники Пылающего Клинка преданы злу до мозга костей. Души их осквернены, и единственный способ их остановить – это уничтожить.$b$bКельдрин отправил со мной Маурина, потому что он знает многое о Пылающем Клинке и разбирается в уловках чернокнижников.$b$bОн борется с Клинком, а на мою долю остаются прочие козни демонов тут, в Пустошах.$b$bПоговори с Маурином, он посвятит тебя в свои планы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Маурином Костоломом в Пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, да! Нам всегда пригодится помощь тех, кто предан вождю.\n\nМеня зовут Майрин. Я здесь по просьбе Кельдрина и нашего юного вождя, Тралла. Мальчику нужна помощь в борьбе против врагов, угрожающих его власти.\n\nПодойди-ка поближе, |3-6($C). Я изложу тебе свои планы касательно ликвидации этого гнойного нарыва, Пылающего Клинка.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Спутник-таурен предупредил меня, что сатиры – не совсем то, чем кажутся. Он считает, что зло в них исказило их истинную природу. Но сам я такого не видел.\n\nЯ вижу только, как они безжалостно убивают слабых и оскверняют души тех, кто обращается к темным силам.\n\nИ я буду уничтожать их, пока вождь не поручит мне другое дело. Жалости к ним я не испытываю.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1434,'Опоганенные сатиры','Влияние демонов возникает не на пустом месте. Нужен какой-то изъян, который позволяет злу войти в тебя.$b$bМожет быть, слабость духа, или излишнее стремление к власти, или жажда мести... Когда мы поддаемся боли, то позволяем злу взять над нами верх – такому злу, как сатиры.$b$bОни связаны с Пылающим Клинком, и Тралл хочет, чтобы их перебили. Разыщи их на северо-востоке и возвращайся ко мне, когда сумеешь их изгнать.','Убейте 7 разбойников из племени Ярой Ненависти, 7 скверноподданных племени Ярой Ненависти, 7 предателей из племени Ярой Ненависти и 7 адских сатиров из племени Ярой Ненависти и вернитесь к Такате Стальному Клинку в Пустоши.','Молодец, |3-6($C)! В тебе есть доблесть и преданность делу.\n\nКогда мы покончим с нашими делами в Пустошах, вождь непременно узнает о том, что ты помогал нам выполнять его волю.\n\nБлагодарю тебя!','Что у вас за новости, |3-6($C)? Ах, неужели это письмо от моего брата? Ну что ж, давайте его сюда!','Вернитесь к Такате Стальному Клинку на Заставу Скитающихся Духов, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опоганенные сатиры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Влияние демонов возникает не на пустом месте. Нужен какой-то изъян, который позволяет злу войти в тебя.$b$bМожет быть, слабость духа, или излишнее стремление к власти, или жажда мести... Когда мы поддаемся боли, то позволяем злу взять над нами верх – такому злу, как сатиры.$b$bОни связаны с Пылающим Клинком, и Тралл хочет, чтобы их перебили. Разыщи их на северо-востоке и возвращайся ко мне, когда сумеешь их изгнать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 разбойников из племени Ярой Ненависти, 7 скверноподданных племени Ярой Ненависти, 7 предателей из племени Ярой Ненависти и 7 адских сатиров из племени Ярой Ненависти и вернитесь к Такате Стальному Клинку в Пустоши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, |3-6($C)! В тебе есть доблесть и преданность делу.\n\nКогда мы покончим с нашими делами в Пустошах, вождь непременно узнает о том, что ты помогал нам выполнять его волю.\n\nБлагодарю тебя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что у вас за новости, |3-6($C)? Ах, неужели это письмо от моего брата? Ну что ж, давайте его сюда!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Такате Стальному Клинку на Заставу Скитающихся Духов, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1435,'Сжигание душ','Этих жалких тварей лучше всего предать смерти. Но, когда имеешь дело с теми, кто присягнул тьме, недостаточно просто убивать.$b$bВозьми этот самоцвет. Приведи его в действие, когда один из негодяев клана Пылающего Клинка будет близок к смерти. Заклятие вытянет оскверненный дух из жертвы, и у тебя в руках окажется одушевленный самоцвет.$b$bПринеси мне эти одушевленные самоцветы, я с ними разберусь.$b$bСтупай же, и постарайся избегнуть смерти!','Верните пылающий самоцвет и 15 одушевленных самоцветов Маурину Костолому в Пустошах.','А, ты $Gвернулся:вернулась; с победой! Это хорошо. Давай сюда самоцветы, я их спрячу в надежное место…$B$BУ меня больше нет для тебя поручений, |3-6($C). Отдохнешь – поговори с Такатой. Возможно, у него найдется для тебя дело – а может, он попросит тебя вернуться в Оргриммар и сообщить Кельдрану, как идут дела у нас в Пустошах.','Я пытался сделать заклятие как можно более простым. Вытянуть душу твоей жертвы из умирающего тела должно быть детской игрой. Но не рассчитывай, что магия самоцвета сама убьет твоего врага. Активировать камень нужно только тогда, когда враг уже умирает, иначе ничего не получится.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сжигание душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этих жалких тварей лучше всего предать смерти. Но, когда имеешь дело с теми, кто присягнул тьме, недостаточно просто убивать.$b$bВозьми этот самоцвет. Приведи его в действие, когда один из негодяев клана Пылающего Клинка будет близок к смерти. Заклятие вытянет оскверненный дух из жертвы, и у тебя в руках окажется одушевленный самоцвет.$b$bПринеси мне эти одушевленные самоцветы, я с ними разберусь.$b$bСтупай же, и постарайся избегнуть смерти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните пылающий самоцвет и 15 одушевленных самоцветов Маурину Костолому в Пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, ты $Gвернулся:вернулась; с победой! Это хорошо. Давай сюда самоцветы, я их спрячу в надежное место…$B$BУ меня больше нет для тебя поручений, |3-6($C). Отдохнешь – поговори с Такатой. Возможно, у него найдется для тебя дело – а может, он попросит тебя вернуться в Оргриммар и сообщить Кельдрану, как идут дела у нас в Пустошах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я пытался сделать заклятие как можно более простым. Вытянуть душу твоей жертвы из умирающего тела должно быть детской игрой. Но не рассчитывай, что магия самоцвета сама убьет твоего врага. Активировать камень нужно только тогда, когда враг уже умирает, иначе ничего не получится.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1436,'Отношения с Альянсом','Дела идут на лад, $n. Быть может, если мы продолжим одерживать победы над демонами и их приспешниками, вождь разрешит нам вернуться домой еще до начала следующего сезона.$b$bВозвращайся к Кельдрану и расскажи, чего нам удалось добиться. Уверен, он вознаградит тебя за труды. Он будет горд, узнав, что вождь ценит его усилия.','Поговорите с Кельдраном в Оргриммаре.','Тебе удалось добиться успеха, да еще какого, $N! Спасибо тебе.$B$BБлагодарю тебя за труды, за потраченное время и за то, что ты с пониманием $Gотнесся:отнеслась; к моей просьбе. Тралл стремится к миру между Ордой и Альянсом и потому заботится, чтобы мы выглядели достойно в глазах противника. Не следует провоцировать новые конфликты.$B$BЯ твой должник!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отношения с Альянсом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дела идут на лад, $n. Быть может, если мы продолжим одерживать победы над демонами и их приспешниками, вождь разрешит нам вернуться домой еще до начала следующего сезона.$b$bВозвращайся к Кельдрану и расскажи, чего нам удалось добиться. Уверен, он вознаградит тебя за труды. Он будет горд, узнав, что вождь ценит его усилия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кельдраном в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось добиться успеха, да еще какого, $N! Спасибо тебе.$B$BБлагодарю тебя за труды, за потраченное время и за то, что ты с пониманием $Gотнесся:отнеслась; к моей просьбе. Тралл стремится к миру между Ордой и Альянсом и потому заботится, чтобы мы выглядели достойно в глазах противника. Не следует провоцировать новые конфликты.$B$BЯ твой должник!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1437,'Расследование Валарриэля','Приветствую тебя, $n. Я – Валарриэль. Я прибыл сюда, чтобы установить местопребывание двух пропавших торговцев из почтенной дарнасской семьи – дома Малем. Глава дома опасается самого худшего; я обязан выяснить все, что могу, о его пропавших детях. Правда, поиски Тираниса и Далинды я еще не начал, но надеюсь, что не задержусь здесь надолго.$B$BПоследнее, что мне довелось слышать о них – то, что несколько недель назад они миновали Когтистые горы.$B$BЕсли найдешь их повозку, прошу тебя, немедленно дай мне знать.','Отправляйтесь в Пустоши и попытайтесь отыскать повозку Тираниса и Далинды Малем.','Судя по виду повозки, она подверглась воздействию как грубой силы, так и чар. Похоже, битва была короткой, и у одной из сторон не было никаких шансов – не было даже возможности отразить удар. Ни трупов, ни следов крови нигде не видно.$B$BКто бы ни напал на торговцев, действовал он весьма умело...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расследование Валарриэля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $n. Я – Валарриэль. Я прибыл сюда, чтобы установить местопребывание двух пропавших торговцев из почтенной дарнасской семьи – дома Малем. Глава дома опасается самого худшего; я обязан выяснить все, что могу, о его пропавших детях. Правда, поиски Тираниса и Далинды я еще не начал, но надеюсь, что не задержусь здесь надолго.$B$BПоследнее, что мне довелось слышать о них – то, что несколько недель назад они миновали Когтистые горы.$B$BЕсли найдешь их повозку, прошу тебя, немедленно дай мне знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Пустоши и попытайтесь отыскать повозку Тираниса и Далинды Малем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Судя по виду повозки, она подверглась воздействию как грубой силы, так и чар. Похоже, битва была короткой, и у одной из сторон не было никаких шансов – не было даже возможности отразить удар. Ни трупов, ни следов крови нигде не видно.$B$BКто бы ни напал на торговцев, действовал он весьма умело...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1438,'Расследование Валарриэля','Постарайся разыскать Далинду и Тираниса. Начни поиски с той самой крепости, о которой ты $Gговорил:говорила;, а я пока что свяжусь с Дарнасом и изложу ситуацию. Что бы ты ни $Gобнаружил:обнаружила;, немедленно дай мне знать.$B$BЯ хотел еще кое-что сказать тебе, $n. Дело в том, что мое начальство весьма обеспокоено действиями Тираниса и причинами, которые заставили его отправиться сюда. Чрезвычайно важно найти Далинду и доставить ее домой. Целой и невредимой, по возможности. А вот Тираниса следовало бы сначала... проверить.','Найдите в Пустошах Далинду Малем.','Благодарение Элуне, хоть кто-то пришел на помощь! Прошу тебя, $C, помоги мне. Орки Пылающего Клинка схватили меня и моего брата Тираниса и притащили сюда. Мне кажется, они собираются принести меня в жертву своим хозяевам-демонам!..$B$BЯ знала, что наше путешествие в Пустоши – это ошибка, но Тиранис так настаивал... в последнее время он особенно увлекся потаенными знаниями, хотя многим это не нравилось. Он решил отправиться в эти края именно после того, как узнал, что здесь появляются демоны...$B$BБоюсь, с ним случилось что-то скверное... очень скверное!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расследование Валарриэля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Постарайся разыскать Далинду и Тираниса. Начни поиски с той самой крепости, о которой ты $Gговорил:говорила;, а я пока что свяжусь с Дарнасом и изложу ситуацию. Что бы ты ни $Gобнаружил:обнаружила;, немедленно дай мне знать.$B$BЯ хотел еще кое-что сказать тебе, $n. Дело в том, что мое начальство весьма обеспокоено действиями Тираниса и причинами, которые заставили его отправиться сюда. Чрезвычайно важно найти Далинду и доставить ее домой. Целой и невредимой, по возможности. А вот Тираниса следовало бы сначала... проверить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Пустошах Далинду Малем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарение Элуне, хоть кто-то пришел на помощь! Прошу тебя, $C, помоги мне. Орки Пылающего Клинка схватили меня и моего брата Тираниса и притащили сюда. Мне кажется, они собираются принести меня в жертву своим хозяевам-демонам!..$B$BЯ знала, что наше путешествие в Пустоши – это ошибка, но Тиранис так настаивал... в последнее время он особенно увлекся потаенными знаниями, хотя многим это не нравилось. Он решил отправиться в эти края именно после того, как узнал, что здесь появляются демоны...$B$BБоюсь, с ним случилось что-то скверное... очень скверное!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1439,'Поиски Тираниса','Орки перебили нашу охрану и слуг, а потом приволокли нас сюда. Ты представить себе не можешь, что с ними сделали! Я думала, нас тоже прикончат на месте – но, как выяснилось, у орков были на нас другие планы.$B$BТиранис пытался поговорить с ними. Наверное, он думал, что его знания тайных искусств произведут на орков впечатление. Не знаю уж, почему.$B$BПрошу тебя, помоги! Я не могу уйти, пока не узнаю, что случилось с моим братом. Найди его – или хотя бы узнай о его судьбе. Умоляю!..','Разыщите в Пустошах Тираниса Малема.','Это ужасно!.. Но, полагаю, у тебя не было другого выхода. Если бы не ты, его все равно убили бы... Наверное, я должна поблагодарить тебя. Прости, если это звучит не слишком искренне: думаю, ты понимаешь, почему.$B$BТеперь, когда я знаю, какая судьба постигла моего несчастного брата, думаю, пора бежать отсюда. Если ты еще не передумал, я с радостью воспользуюсь твоей помощью и покину это страшное место.$B$BКогда будешь готов, скажи мне: мы тут же отправимся в путь.','Боюсь, Тиранис попытается узнать тайны Пылающего Клинка и стать одним из них, если, конечно, они это позволят. Его всегда восхищала та власть, которую дает магия – и никогда он не думал о цене этой власти...$B$BНе знаю, как мне вернуться к семье, когда душа Тираниса подвергается такой опасности... Наш народ считает преступлением даже изучение подобной магии, а уж если Тиранис преобразится в одно из тех существ, с которыми му ведем войну...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Тираниса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орки перебили нашу охрану и слуг, а потом приволокли нас сюда. Ты представить себе не можешь, что с ними сделали! Я думала, нас тоже прикончат на месте – но, как выяснилось, у орков были на нас другие планы.$B$BТиранис пытался поговорить с ними. Наверное, он думал, что его знания тайных искусств произведут на орков впечатление. Не знаю уж, почему.$B$BПрошу тебя, помоги! Я не могу уйти, пока не узнаю, что случилось с моим братом. Найди его – или хотя бы узнай о его судьбе. Умоляю!..',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите в Пустошах Тираниса Малема.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это ужасно!.. Но, полагаю, у тебя не было другого выхода. Если бы не ты, его все равно убили бы... Наверное, я должна поблагодарить тебя. Прости, если это звучит не слишком искренне: думаю, ты понимаешь, почему.$B$BТеперь, когда я знаю, какая судьба постигла моего несчастного брата, думаю, пора бежать отсюда. Если ты еще не передумал, я с радостью воспользуюсь твоей помощью и покину это страшное место.$B$BКогда будешь готов, скажи мне: мы тут же отправимся в путь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Боюсь, Тиранис попытается узнать тайны Пылающего Клинка и стать одним из них, если, конечно, они это позволят. Его всегда восхищала та власть, которую дает магия – и никогда он не думал о цене этой власти...$B$BНе знаю, как мне вернуться к семье, когда душа Тираниса подвергается такой опасности... Наш народ считает преступлением даже изучение подобной магии, а уж если Тиранис преобразится в одно из тех существ, с которыми му ведем войну...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (1440,'Возвращение к Валарриэлю','Итак, время пришло?.. Ценю твои усилия и благодарю тебя за все, что ты $Gсделал:сделала; для меня и моей семьи. Что ж, если ты $Gготов:готова;, то и мне тут больше нечего делать. Отправимся в путь по первому твоему слову.','Выведите Далинду Малем из Крепости Громового Топора, а затем вернитесь в Пустоши к Валлариелю Истребителю Демонов.','Благодарю тебя, $n. Далинда благополучно добралась до Высоты Найджела и чувствует себя гораздо лучше, чем я смел надеяться. Я даже не надеялся на столь благополучный исход! То, что ей удалось добраться сюда своими силами – добрый знак. Надеюсь, с тобой тоже все в порядке?..$B$BМне жаль, что Тиранис не вернулся; однако все, что с ним произошло, было плодом его собственных решений. Далинде придется с этим смириться – и, к тому же, разбираться с последствиями его действий, когда она вернется в Дарнасс.','Спасите Далинду Малем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Валарриэлю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, время пришло?.. Ценю твои усилия и благодарю тебя за все, что ты $Gсделал:сделала; для меня и моей семьи. Что ж, если ты $Gготов:готова;, то и мне тут больше нечего делать. Отправимся в путь по первому твоему слову.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выведите Далинду Малем из Крепости Громового Топора, а затем вернитесь в Пустоши к Валлариелю Истребителю Демонов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, $n. Далинда благополучно добралась до Высоты Найджела и чувствует себя гораздо лучше, чем я смел надеяться. Я даже не надеялся на столь благополучный исход! То, что ей удалось добраться сюда своими силами – добрый знак. Надеюсь, с тобой тоже все в порядке?..$B$BМне жаль, что Тиранис не вернулся; однако все, что с ним произошло, было плодом его собственных решений. Далинде придется с этим смириться – и, к тому же, разбираться с последствиями его действий, когда она вернется в Дарнасс.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Спасите Далинду Малем.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1441,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1442,'Поиск самоцвета Кора','День добрый, $n. Чем могу помочь $Gидущему:идущей; путем Света?$B$BАх да, кузнец Стилвелл... давно не виделись. Я хорошо его помню, хотя давно о нем не слышал.$B$BОн никогда не казался мне злодеем, поэтому остается думать, что его стремление получить самоцвет Кора благородно.$B$BЕсли вам и правда нужен самоцвет, то придется направиться на северо-запад Ясеневого леса. Там, среди древних развалин, вы обнаружите Непроглядную Пучину. В их недрах таятся наги, и они до сих пор используют такие самоцветы. Не ходите туда в одиночку, |3-6($c).','Принесите самоцвет Кора Тандрису Ветропряду на Темных берегах.','Действительно, это тот самый камень, который хочет получить Стилвелл, но, прежде чем я отдам его вам, надо очистить камень от скверны – мерзкие наги наполняют самоцветы силой, но своей, злобной силой.$B$BПусть Стилвелл знает, что мощь камня чиста, и он хорошо послужит в любом ритуале.$B$BЯ надеюсь, вы понимаете, что делаете, $C, ибо в руках у вас не игрушка.','Я с трудом поверил бы в чистые намерения того, кто ищет самоцвет Кора, не будь это искатель святого пути. Но таким, как вы, я доверяю даже больше, чем собственным сородичам. И я не стану судить о вашем ордене по деяниям ваших падших собратьев.','Вернитесь к Тандрису Ветропряду в Аубердин, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиск самоцвета Кора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','День добрый, $n. Чем могу помочь $Gидущему:идущей; путем Света?$B$BАх да, кузнец Стилвелл... давно не виделись. Я хорошо его помню, хотя давно о нем не слышал.$B$BОн никогда не казался мне злодеем, поэтому остается думать, что его стремление получить самоцвет Кора благородно.$B$BЕсли вам и правда нужен самоцвет, то придется направиться на северо-запад Ясеневого леса. Там, среди древних развалин, вы обнаружите Непроглядную Пучину. В их недрах таятся наги, и они до сих пор используют такие самоцветы. Не ходите туда в одиночку, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите самоцвет Кора Тандрису Ветропряду на Темных берегах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Действительно, это тот самый камень, который хочет получить Стилвелл, но, прежде чем я отдам его вам, надо очистить камень от скверны – мерзкие наги наполняют самоцветы силой, но своей, злобной силой.$B$BПусть Стилвелл знает, что мощь камня чиста, и он хорошо послужит в любом ритуале.$B$BЯ надеюсь, вы понимаете, что делаете, $C, ибо в руках у вас не игрушка.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я с трудом поверил бы в чистые намерения того, кто ищет самоцвет Кора, не будь это искатель святого пути. Но таким, как вы, я доверяю даже больше, чем собственным сородичам. И я не стану судить о вашем ордене по деяниям ваших падших собратьев.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тандрису Ветропряду в Аубердин, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1443,'Облава') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Облава',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1444,'Возвращение к Фел\'зерулу','Джаммал\'ан Пророк приговорил меня к изгнанию из Храма Атал\'Хаккара. Некогда я считал верховного жреца достойным главой храма.$b$bЕго непоколебимая вера в свое пророчество может привести к гибели Атал\'ай, если уже не привела.$b$bНо стоило мне высказать мои сомнения, я был заклеймен как еретик и изгнан из храма.$b$bПринесенные тобой артефакты безопасны... Но если Джаммал\'ан нашел нужный для ритуала призыва фетиш, то всему миру угрожает смертельная опасность.','Вернитесь в Каменор к Фел\'зерулу.','Мы же виделись совсем недавно, |3-6($C). Надеюсь, твое путешествие было удачным. Что тебе поведал изгнанник-Атал\'ай во внутренних землях?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Фел\'зерулу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Джаммал\'ан Пророк приговорил меня к изгнанию из Храма Атал\'Хаккара. Некогда я считал верховного жреца достойным главой храма.$b$bЕго непоколебимая вера в свое пророчество может привести к гибели Атал\'ай, если уже не привела.$b$bНо стоило мне высказать мои сомнения, я был заклеймен как еретик и изгнан из храма.$b$bПринесенные тобой артефакты безопасны... Но если Джаммал\'ан нашел нужный для ритуала призыва фетиш, то всему миру угрожает смертельная опасность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Каменор к Фел\'зерулу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы же виделись совсем недавно, |3-6($C). Надеюсь, твое путешествие было удачным. Что тебе поведал изгнанник-Атал\'ай во внутренних землях?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1445,'Храм Атал\'Хаккара','Так он говорил о пророчестве Джаммал\'ана?$b$bДуховный вождь Атал\'ай верит, что когда однажды, Хаккар вернется в Азерот из Пустоты, он дарует племени бессмертие.$b$bПо мне дураком надо быть, чтобы раньше срока вызывать светопреставление.$b$bНо ты говоришь, этот изгой упоминал о зачарованных амулетах? А вот это уже напрямую меня касается. Если среди них окажется ключ к ритуалу Атал\'ай, который и привел ко всей этой заварухе, мы должны понять его тайную силу.$b$bОтправляйся в Храм и добудь амулеты!','Соберите 20 фетишей Хаккара и принесите их Фел\'зерулу в Каменор.','Отважный |3-6($C), ты $Gдоказал:доказала;, что являешься одним из лучших воинов Орды.$B$BТеперь-то мы разберемся с этими амулетами!','Если фетиши Атал\'ай способны призвать Хаккара и исполнить пророчество Джаммал\'ана, мы должны заполучить их. Орда должна познать их силу!','Вернитесь к Фел\'зерулу на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Храм Атал\'Хаккара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так он говорил о пророчестве Джаммал\'ана?$b$bДуховный вождь Атал\'ай верит, что когда однажды, Хаккар вернется в Азерот из Пустоты, он дарует племени бессмертие.$b$bПо мне дураком надо быть, чтобы раньше срока вызывать светопреставление.$b$bНо ты говоришь, этот изгой упоминал о зачарованных амулетах? А вот это уже напрямую меня касается. Если среди них окажется ключ к ритуалу Атал\'ай, который и привел ко всей этой заварухе, мы должны понять его тайную силу.$b$bОтправляйся в Храм и добудь амулеты!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 фетишей Хаккара и принесите их Фел\'зерулу в Каменор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отважный |3-6($C), ты $Gдоказал:доказала;, что являешься одним из лучших воинов Орды.$B$BТеперь-то мы разберемся с этими амулетами!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если фетиши Атал\'ай способны призвать Хаккара и исполнить пророчество Джаммал\'ана, мы должны заполучить их. Орда должна познать их силу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фел\'зерулу на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1446,'Джаммал\'ан Пророк','Мои товарищи из племени Сухокожих не любят, когда чужаки приходят к ним домой.$B$BЯ? А у меня и дома-то нет. Я жил в племени Атал\'ай на Болоте Печали, но был изгнан оттуда.$B$BУ нашего духовного лидера по имени Джаммал\'ан, было, как он сам говорил, "видение". Он решил, что если призвать бога Хаккара, то он дарует Атал\'ай бессмертие.$B$BЯ настоятельно рекомендовал ему проявить осторожность, потому это "видение" могло быть всего лишь манипуляцией, обманом!$B$BЯ хочу отомстить за свое изгнание. Принесите мне голову Джаммал\'ана. Может быть, тогда мой народ освободится!','Принесите изгнаннику Атал\'ай из Внутренних земель голову Джаммал\'ана.','Теперь, когда Джаммал\'ана нет, у меня появилась возможность вернуться к своему народу.$B$BС таким духовным лидером, как Джаммал\'ан, племя Атал\'ай было обречено.','Вернитесь к изгнаннику племени Атал\'ай в Шадра\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джаммал\'ан Пророк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои товарищи из племени Сухокожих не любят, когда чужаки приходят к ним домой.$B$BЯ? А у меня и дома-то нет. Я жил в племени Атал\'ай на Болоте Печали, но был изгнан оттуда.$B$BУ нашего духовного лидера по имени Джаммал\'ан, было, как он сам говорил, "видение". Он решил, что если призвать бога Хаккара, то он дарует Атал\'ай бессмертие.$B$BЯ настоятельно рекомендовал ему проявить осторожность, потому это "видение" могло быть всего лишь манипуляцией, обманом!$B$BЯ хочу отомстить за свое изгнание. Принесите мне голову Джаммал\'ана. Может быть, тогда мой народ освободится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите изгнаннику Атал\'ай из Внутренних земель голову Джаммал\'ана.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Теперь, когда Джаммал\'ана нет, у меня появилась возможность вернуться к своему народу.$B$BС таким духовным лидером, как Джаммал\'ан, племя Атал\'ай было обречено.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к изгнаннику племени Атал\'ай в Шадра\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1447,'Пропавший дипломат','В Штормград приходили многие твои коллеги, |3-6($c), были среди них умные, были и круглые дураки, но подобных тебе нет, не было и не надо... $B$BЧего ты от меня хочешь?','Победите Дашеля Каменного Кулака в Штормграде.','У тебя явно была причина прийти ко мне. Так в чем дело?','Я вовсе не хотел тебя оскорбить, $C. Мы же друзья? Никаких проблем?','Победить Дашеля Каменного Кулака.','Поговорите с Дашелем Каменным Кулаком в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший дипломат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Штормград приходили многие твои коллеги, |3-6($c), были среди них умные, были и круглые дураки, но подобных тебе нет, не было и не надо... $B$BЧего ты от меня хочешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Дашеля Каменного Кулака в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя явно была причина прийти ко мне. Так в чем дело?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я вовсе не хотел тебя оскорбить, $C. Мы же друзья? Никаких проблем?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победить Дашеля Каменного Кулака.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Дашелем Каменным Кулаком в Штормграде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1448,'В поисках Храма','Когда-то я был так же молод и полон сил, как вы, |3-6($c).$b$bТеперь я стар и не могу больше странствовать по миру. О, сколько я всего повидал!$b$bНо была одна загадка, которая до сих пор волнует меня. Во время моего последнего путешествия Лига исследователей направила меня на поиски Храма Атал\'Хаккара. Говорили, что он расположен где-то на Болоте Печали.$b$bПоскольку я уже был стар и немощен, то облетел эти земли на грифоне, но ничего не нашел.$b$bНе поможете ли старому дворфу? Может быть, вам повезет больше?','Найдите Храм Атал\'Хаккара и сообщите о его местонахождении Брохану Бочкопузу из Штормграда.','Храм Атал\'Хаккара скрыт в глубинах озера Слез? И охраняется зелеными драконами?$B$BЭто чудесное открытие, $C! Очевидно, что-то ужасное случилось с этим храмом...','Я путешествовал по всему миру, от джунглей Азерота до снежных вершин Каз Модана.$B$BРаньше я никогда не попросил бы о помощи, но мои старые кости ноют и не позволяют пуститься в путь.$B$BЕдинственное, что позволит мне умереть со спокойной душой – знание о том, что я все же выполнил последнее задание Лиги Исследователей.$B$BЕсли вы поможете мне в поисках Храма Атал\'Хаккара, то я буду вечно признателен вам, $C!$B$BИсследуйте Болото Печали и возвращайтесь с рассказом о своих находках!','Найти Храм Атал\'Хаккара.','Вернитесь к Брохану Бочкопузу в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Храма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда-то я был так же молод и полон сил, как вы, |3-6($c).$b$bТеперь я стар и не могу больше странствовать по миру. О, сколько я всего повидал!$b$bНо была одна загадка, которая до сих пор волнует меня. Во время моего последнего путешествия Лига исследователей направила меня на поиски Храма Атал\'Хаккара. Говорили, что он расположен где-то на Болоте Печали.$b$bПоскольку я уже был стар и немощен, то облетел эти земли на грифоне, но ничего не нашел.$b$bНе поможете ли старому дворфу? Может быть, вам повезет больше?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Храм Атал\'Хаккара и сообщите о его местонахождении Брохану Бочкопузу из Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Храм Атал\'Хаккара скрыт в глубинах озера Слез? И охраняется зелеными драконами?$B$BЭто чудесное открытие, $C! Очевидно, что-то ужасное случилось с этим храмом...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я путешествовал по всему миру, от джунглей Азерота до снежных вершин Каз Модана.$B$BРаньше я никогда не попросил бы о помощи, но мои старые кости ноют и не позволяют пуститься в путь.$B$BЕдинственное, что позволит мне умереть со спокойной душой – знание о том, что я все же выполнил последнее задание Лиги Исследователей.$B$BЕсли вы поможете мне в поисках Храма Атал\'Хаккара, то я буду вечно признателен вам, $C!$B$BИсследуйте Болото Печали и возвращайтесь с рассказом о своих находках!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найти Храм Атал\'Хаккара.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брохану Бочкопузу в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1449,'Во Внутренние земли','Как я уже говорил, я пытался обнаружить храм, осматривая окрестности с высоты. Строго говоря, я был не один...$b$bЯ нанял грифона в небезызвестном питомнике на Заоблачном пике во Внутренних землях. Птицей управлял один из лучших пилотов, но в воздухе он выпал из седла и свалился в болото...$b$bМоя старая дырявая память не сохранила его имени, но хозяин питомника должен понять, о ком идет речь.$b$bОтправляйтесь туда и найдите Фалстада Громового Молота.$b$bХорошо бы узнать, что случилось с тем пилотом...','Поговорите с Верховным таном Фалстадом Громовым Молотом на Заоблачном пике во Внутренних землях.','Чего тебе, парень? Не видишь – и без тебя забот хватает? Чем болтаться тут без толку, лучше займись делом, |3-6($r).$B$BЧто-что случилось... Тролли лезут из всех щелей, вот что! Ну говори уже, с чем пришел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во Внутренние земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как я уже говорил, я пытался обнаружить храм, осматривая окрестности с высоты. Строго говоря, я был не один...$b$bЯ нанял грифона в небезызвестном питомнике на Заоблачном пике во Внутренних землях. Птицей управлял один из лучших пилотов, но в воздухе он выпал из седла и свалился в болото...$b$bМоя старая дырявая память не сохранила его имени, но хозяин питомника должен понять, о ком идет речь.$b$bОтправляйтесь туда и найдите Фалстада Громового Молота.$b$bХорошо бы узнать, что случилось с тем пилотом...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховным таном Фалстадом Громовым Молотом на Заоблачном пике во Внутренних землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чего тебе, парень? Не видишь – и без тебя забот хватает? Чем болтаться тут без толку, лучше займись делом, |3-6($r).$B$BЧто-что случилось... Тролли лезут из всех щелей, вот что! Ну говори уже, с чем пришел.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1450,'Укротитель грифонов Разящий Коготь','Так, значит, ты $gтот парень:та девчонка;, $gкоторого:которую; наняли эти старые развалины из Лиги исследователей?$b$bТак, слушай меня, |3-6($c). Я понятия не имею, кто у них там развлекался, летая над Азеротом! Я что, похож на Разящего Когтя? Похож?$b$bЕсли тебя интересуют грифоны, так поговори с укротителем! Если я увижу тебя без дела, то завалю по уши настоящей работой.$b$bДавай-давай, топай отсюда.','Поговорите с укротителем грифонов Разящим Когтем в питомнике на Заоблачном пике.','Да, конечно, я прекрасно помню о том, как послал одного из пилотов отвезти Брохана Бочкопуза.$B$BЛиге Исследователей всегда найдется место в моем сердце. Мой отец участвовал в экспедиции первой исследовательской команды, обнаружившей Ульдаман.$B$BС Броханом я отправил своего лучшего всадника на грифоне по имени Рапсод Землекоп.$B$BАх, что за всадник это был! Ну, до поры...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротитель грифонов Разящий Коготь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, значит, ты $gтот парень:та девчонка;, $gкоторого:которую; наняли эти старые развалины из Лиги исследователей?$b$bТак, слушай меня, |3-6($c). Я понятия не имею, кто у них там развлекался, летая над Азеротом! Я что, похож на Разящего Когтя? Похож?$b$bЕсли тебя интересуют грифоны, так поговори с укротителем! Если я увижу тебя без дела, то завалю по уши настоящей работой.$b$bДавай-давай, топай отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с укротителем грифонов Разящим Когтем в питомнике на Заоблачном пике.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, конечно, я прекрасно помню о том, как послал одного из пилотов отвезти Брохана Бочкопуза.$B$BЛиге Исследователей всегда найдется место в моем сердце. Мой отец участвовал в экспедиции первой исследовательской команды, обнаружившей Ульдаман.$B$BС Броханом я отправил своего лучшего всадника на грифоне по имени Рапсод Землекоп.$B$BАх, что за всадник это был! Ну, до поры...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1451,'Рапсод Землекоп','Рапсод всегда любил поддать лишнего. Не поймите меня неправильно: мы, дворфы этого питомника, все любим порой принять на грудь пинту-другую доброго эля.$b$bНо старина Землекоп любил это дело больше, чем грифоны любят летать – порой ужас что получалось. Никто не умел летать так, как Рапсод...$b$bАвария с этим вашим приятелем Броханом была только первым звоночком. После этого Землекоп покатился под горку, пришлось его уволить.$b$bГоворят, он открыл пивнушку к югу отсюда...','Найдите Рапсода Землекопа во Внутренних землях.','И-ик!$B$BЯ ж прям на вас смотрю, чего это вас так мотыляет из стороны в сторону? У меня аж морская болезнь начинается, ха-ха!$B$BИ-ик!$B$BО! Чувствуете, дорогуша? Земля так и ходит ходуном. Надо выпить!$B$BИк-к!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рапсод Землекоп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рапсод всегда любил поддать лишнего. Не поймите меня неправильно: мы, дворфы этого питомника, все любим порой принять на грудь пинту-другую доброго эля.$b$bНо старина Землекоп любил это дело больше, чем грифоны любят летать – порой ужас что получалось. Никто не умел летать так, как Рапсод...$b$bАвария с этим вашим приятелем Броханом была только первым звоночком. После этого Землекоп покатился под горку, пришлось его уволить.$b$bГоворят, он открыл пивнушку к югу отсюда...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Рапсода Землекопа во Внутренних землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И-ик!$B$BЯ ж прям на вас смотрю, чего это вас так мотыляет из стороны в сторону? У меня аж морская болезнь начинается, ха-ха!$B$BИ-ик!$B$BО! Чувствуете, дорогуша? Земля так и ходит ходуном. Надо выпить!$B$BИк-к!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1452,'Калимдорский коктейль','Ик!$b$bВас послал этот старый пень Брохан? Как вспомню ту историю, так... И-ик!$b$bЧтобы рассказать, что там со мной случилось над этим болотом, понадобится выпить капельку для храбрости. Полный ужас, вы не поверите! Ик!$b$bВот что я скажу – притащите-ка мне индри... гринди... эн-гре-де-ен-ты для калимдорского коктейля, и вы обо всем услышите!$b$bЗначится, что нужно мне... Потроха руха из Танариса, печень гроддока, печень сталемеха из Фераласа... Да.$b$bКалимдорский коктейль развяжет мне язык!','Принесите Рапсоду Землекопу 3 куска потрохов руха, 3 печени гроддока и 3 печени сталемеха.','Как я погляжу, у вас этих потрошков полные карманы! И какая беда принесла вас из Калимдора-то?$B$BСейчас подождите, я сделаю вытяжку, и тогда уж расскажу все, что вы пожелаете.$B$BИк!$B$BМеня дрожь пробирает, когда вспоминаю это клятое болото.$B$BИк!$B$BСейчас, сейчас, почти готово дело...','Пробовали болтливое пиво? Один из моих любимых сортов, надо сказать... Ик!$B$BНо если вы хотите, чтобы я вспомнил все детали того... ик... душераздирающего полета, потребуется что-то покрепче, и-ик, да...$B$BМне так представляется, что потрошка и печенки вы мне не торопитесь нести?$B$BИк!','Вернитесь к Рапсоду Землекопу во Внутренние земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Калимдорский коктейль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ик!$b$bВас послал этот старый пень Брохан? Как вспомню ту историю, так... И-ик!$b$bЧтобы рассказать, что там со мной случилось над этим болотом, понадобится выпить капельку для храбрости. Полный ужас, вы не поверите! Ик!$b$bВот что я скажу – притащите-ка мне индри... гринди... эн-гре-де-ен-ты для калимдорского коктейля, и вы обо всем услышите!$b$bЗначится, что нужно мне... Потроха руха из Танариса, печень гроддока, печень сталемеха из Фераласа... Да.$b$bКалимдорский коктейль развяжет мне язык!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Рапсоду Землекопу 3 куска потрохов руха, 3 печени гроддока и 3 печени сталемеха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как я погляжу, у вас этих потрошков полные карманы! И какая беда принесла вас из Калимдора-то?$B$BСейчас подождите, я сделаю вытяжку, и тогда уж расскажу все, что вы пожелаете.$B$BИк!$B$BМеня дрожь пробирает, когда вспоминаю это клятое болото.$B$BИк!$B$BСейчас, сейчас, почти готово дело...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пробовали болтливое пиво? Один из моих любимых сортов, надо сказать... Ик!$B$BНо если вы хотите, чтобы я вспомнил все детали того... ик... душераздирающего полета, потребуется что-то покрепче, и-ик, да...$B$BМне так представляется, что потрошка и печенки вы мне не торопитесь нести?$B$BИк!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рапсоду Землекопу во Внутренние земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1453,'Дела Поисковой корпорации в Пустошах','Надо сделать одну работу в Пустошах, $n. Это жуткое место, опоганенное кентаврами и прочими грязными тварями. Но если ты ищешь честную работенку на неделю, то отправляйся туда, найди Крелдига Унгора и скажи, что это я тебя прислал.$B$BТы найдешь его на Высоте Найджела – он прячется в укромном лагере в горах северных Пустошей. Держись к востоку от выхода из Когтистых гор. Будь начеку, иначе можешь проскочить мимо лагеря.','Поговорите с Крелдигом Унгором в Пустошах.','Рад видеть, что у Горной корпорации нет недостатка ни в работе, ни в искателях приключений, готовых прийти на помощь.$B$BЯ – Крелдиг, $n. Это хорошо, что ты взялся помочь Горной корпорации. В эти дни все что-то ищут – кто фамильные драгоценности потерял, кто магический предмет, кто любимых. Да мало ли что. Но если за дело берется Горная корпорация, то по сходной цене она найдет все что угодно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дела Поисковой корпорации в Пустошах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо сделать одну работу в Пустошах, $n. Это жуткое место, опоганенное кентаврами и прочими грязными тварями. Но если ты ищешь честную работенку на неделю, то отправляйся туда, найди Крелдига Унгора и скажи, что это я тебя прислал.$B$BТы найдешь его на Высоте Найджела – он прячется в укромном лагере в горах северных Пустошей. Держись к востоку от выхода из Когтистых гор. Будь начеку, иначе можешь проскочить мимо лагеря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Крелдигом Унгором в Пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад видеть, что у Горной корпорации нет недостатка ни в работе, ни в искателях приключений, готовых прийти на помощь.$B$BЯ – Крелдиг, $n. Это хорошо, что ты взялся помочь Горной корпорации. В эти дни все что-то ищут – кто фамильные драгоценности потерял, кто магический предмет, кто любимых. Да мало ли что. Но если за дело берется Горная корпорация, то по сходной цене она найдет все что угодно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1454,'Пожитки Карнитола','Здравствуй, $n. Присаживайся... $b$bМое первое задание касается мага Карнитола – это какой-то тип из благородных, живет в Штормграде. Говорит, на его корабль напали морские великаны, и было это все у северо-западного берега Пустошей. Вместе со слугами этот тип попытался вытащить на берег один из самых ценных сундуков, но когда великаны набросились на них толпой, почел за благо телепортировать себя и своих куда подальше, а сундук бросил.$B$BТак вот, Карнитол хочет, чтобы мы нашли его сундук со всем содержимым и доставили ему в Штормград.','Найдите в Пустошах сундук Карнитола.','Похоже, сундук вовсе не пострадал от морской воды...$B$BОднако он взломан. Если тут и были магические охранные ловушки, то они явно успели сработать: края сундука обожжены.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожитки Карнитола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, $n. Присаживайся... $b$bМое первое задание касается мага Карнитола – это какой-то тип из благородных, живет в Штормграде. Говорит, на его корабль напали морские великаны, и было это все у северо-западного берега Пустошей. Вместе со слугами этот тип попытался вытащить на берег один из самых ценных сундуков, но когда великаны набросились на них толпой, почел за благо телепортировать себя и своих куда подальше, а сундук бросил.$B$BТак вот, Карнитол хочет, чтобы мы нашли его сундук со всем содержимым и доставили ему в Штормград.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Пустошах сундук Карнитола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, сундук вовсе не пострадал от морской воды...$B$BОднако он взломан. Если тут и были магические охранные ловушки, то они явно успели сработать: края сундука обожжены.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1455,'Пожитки Карнитола','Любопытно, кто – или что – все же открыло этот сундук?.. Судя по длинным глубоким царапинам на боках и крышке, это был не человек и не великан... Непохоже также, чтобы отметины оставил меч или кинжал.$B$BКроме всего прочего, сундук пуст. Абсолютно и непоправимо пуст.$B$BДелать нечего: остается только закрыть сундук и уйти. Крелдиг будет крайне разочарован.','Вернитесь в Пустоши к Крелдигу Унгору.','Ну-с, $n, с возвращением на Высоту Найджела. Расскажи-ка, что тебе удалось обнаружить...$B$BКак?! Ничего?.. Ну, дорогуша, из ничего и не выйдет ничего: боюсь, за пустой сундук никто платить не станет.$B$BРасскажи-ка мне побольше об этих самых отметинах... царапинах, которые ты заметил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожитки Карнитола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Любопытно, кто – или что – все же открыло этот сундук?.. Судя по длинным глубоким царапинам на боках и крышке, это был не человек и не великан... Непохоже также, чтобы отметины оставил меч или кинжал.$B$BКроме всего прочего, сундук пуст. Абсолютно и непоправимо пуст.$B$BДелать нечего: остается только закрыть сундук и уйти. Крелдиг будет крайне разочарован.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Пустоши к Крелдигу Унгору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну-с, $n, с возвращением на Высоту Найджела. Расскажи-ка, что тебе удалось обнаружить...$B$BКак?! Ничего?.. Ну, дорогуша, из ничего и не выйдет ничего: боюсь, за пустой сундук никто платить не станет.$B$BРасскажи-ка мне побольше об этих самых отметинах... царапинах, которые ты заметил.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1456,'Пожитки Карнитола','Любопытно, очень любопытно...$B$BЧто ж, может, для нас еще не все потеряно.$B$BЕсли идти по тому же берегу на север, в сторону острова Раназжар, там будут развалины построек ночных эльфов. Понятное дело, развалины эти теперь под водой; к тому же, там поселились наги из клана Скользящего Плавника. Сдается мне, эти наги замешаны в истории с сундуком.$B$BЕсли разведчики наг решились зайти так далеко на юг, значит они очень сильны. Так что пожитки Карнитола, как мне кажется, надо поискать у сильнейших среди наг: волноловов или морских ведьм.','Найдите сумку для книг, принадлежащую Карнитолу, и отнесите ее в Пустоши Крелдигу Унгору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожитки Карнитола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Любопытно, очень любопытно...$B$BЧто ж, может, для нас еще не все потеряно.$B$BЕсли идти по тому же берегу на север, в сторону острова Раназжар, там будут развалины построек ночных эльфов. Понятное дело, развалины эти теперь под водой; к тому же, там поселились наги из клана Скользящего Плавника. Сдается мне, эти наги замешаны в истории с сундуком.$B$BЕсли разведчики наг решились зайти так далеко на юг, значит они очень сильны. Так что пожитки Карнитола, как мне кажется, надо поискать у сильнейших среди наг: волноловов или морских ведьм.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите сумку для книг, принадлежащую Карнитолу, и отнесите ее в Пустоши Крелдигу Унгору.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1457,'Пожитки Карнитола','Послушай, доставь-ка вещички Карнитола Ройттену в Стальгорн: он тебе неплохо заплатит.$B$BТолько ты с ним поосторожнее, не то ты ему понравишься сверх всякой меры и он решит тебя взять к нам, как это называется, на полную ставку!$B$BНет, я ничего не говорю, $n; ты молодчина!$B$BТолько будь поосторожнее на обратном пути и поторапливайся: Карнитол – не самый терпеливый тип... зато платит от души!','Отнесите сумку для книг, принадлежащую Карнитолу, в Стальгорн, и отдайте ее Ройттену Камнемолоту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожитки Карнитола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, доставь-ка вещички Карнитола Ройттену в Стальгорн: он тебе неплохо заплатит.$B$BТолько ты с ним поосторожнее, не то ты ему понравишься сверх всякой меры и он решит тебя взять к нам, как это называется, на полную ставку!$B$BНет, я ничего не говорю, $n; ты молодчина!$B$BТолько будь поосторожнее на обратном пути и поторапливайся: Карнитол – не самый терпеливый тип... зато платит от души!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сумку для книг, принадлежащую Карнитолу, в Стальгорн, и отдайте ее Ройттену Камнемолоту.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1458,'Реагенты для Поисковой корпорации','Одна из моих задач здесь – сбор реагентов для Скрытного Кудесника, гномского мага из Караноса. Ройттен-то, небось, думает, что это – раз плюнуть, коли уж мы все равно тут торчим, а дело не из простых, да и рук не хватает...$B$BПервые несколько реагентов добыть не так уж сложно, а я готов заплатить неплохие деньги тому, кто мне поможет.$B$BМне нужны рога и когти сатиров Ярой Ненависти: они тут недалеко обитают, на востоке. Ты мне их сначала принеси, а потом мы займемся остальным списком.','Принесите 10 когтей и 10 рогов сатиров племени Ярой Ненависти в Пустоши Крелдигу Унгору.','Отвратные они твари, эти сатиры, точно? Поговаривают, что они как-то связаны с ночными эльфами, но мне в это как-то не слишком верится.$B$BСдается мне, эти слухи пошли из-за того, что один эльф несколько лет назад втянул их в войну. После этой войны весь мир поменялся. Опаснее стал, да и страшнее тоже...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реагенты для Поисковой корпорации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна из моих задач здесь – сбор реагентов для Скрытного Кудесника, гномского мага из Караноса. Ройттен-то, небось, думает, что это – раз плюнуть, коли уж мы все равно тут торчим, а дело не из простых, да и рук не хватает...$B$BПервые несколько реагентов добыть не так уж сложно, а я готов заплатить неплохие деньги тому, кто мне поможет.$B$BМне нужны рога и когти сатиров Ярой Ненависти: они тут недалеко обитают, на востоке. Ты мне их сначала принеси, а потом мы займемся остальным списком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 когтей и 10 рогов сатиров племени Ярой Ненависти в Пустоши Крелдигу Унгору.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Отвратные они твари, эти сатиры, точно? Поговаривают, что они как-то связаны с ночными эльфами, но мне в это как-то не слишком верится.$B$BСдается мне, эти слухи пошли из-за того, что один эльф несколько лет назад втянул их в войну. После этой войны весь мир поменялся. Опаснее стал, да и страшнее тоже...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1459,'Реагенты для Поисковой корпорации','А следующее по списку Скрытного Кудесника у нас... Погоди-ка... А, да, вот оно.$B$BНу, не то чтобы это было большой редкостью, но тут наш дорогой друг сподобился дать подобные разъяснения. Ему понадобился яд скорпиона и шкура кодо. А вот тут вот, меленькими буковками, видишь? – тут написано, что яд-то может быть от любого скорпиона, а шкура ему нужна непременно со старого кодо, но ни в коем случае не с умирающего или дряхлого.$B$BОх уж эти мне маги... вечно у них какие-то заскоки.','Принесите 7 фиалов скорпионьего яда и 3 шкуры старого кодо в Пустоши Крелдигу Унгору.','Ты уж извини, что я тебе не сказал, где искать скорпионов и кодо. Я здешние места не особо знаю, да и времени у меня не было все тут обследовать...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реагенты для Поисковой корпорации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А следующее по списку Скрытного Кудесника у нас... Погоди-ка... А, да, вот оно.$B$BНу, не то чтобы это было большой редкостью, но тут наш дорогой друг сподобился дать подобные разъяснения. Ему понадобился яд скорпиона и шкура кодо. А вот тут вот, меленькими буковками, видишь? – тут написано, что яд-то может быть от любого скорпиона, а шкура ему нужна непременно со старого кодо, но ни в коем случае не с умирающего или дряхлого.$B$BОх уж эти мне маги... вечно у них какие-то заскоки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 фиалов скорпионьего яда и 3 шкуры старого кодо в Пустоши Крелдигу Унгору.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уж извини, что я тебе не сказал, где искать скорпионов и кодо. Я здешние места не особо знаю, да и времени у меня не было все тут обследовать...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1460,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1461,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (1462,'Сапта земли','Попросите у провидицы Воронье Перо еще одну сапту земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сапта земли',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попросите у провидицы Воронье Перо еще одну сапту земли.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1463,'Сапта земли','Поговорите с Канагой заклинателем земли, чтобы получить еще один сапту земли.','Я даю вам сапту земли по доброй воле. Ты уже однажды проявил себя, но, думаю, в будущем тебе следует быть осторожнее.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сапта земли',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Канагой заклинателем земли, чтобы получить еще один сапту земли.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я даю вам сапту земли по доброй воле. Ты уже однажды проявил себя, но, думаю, в будущем тебе следует быть осторожнее.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1464,'Сапта огня','Поговорите с Телфом Джоламом, чтобы получить еще одну сапту огня.','Пусть огонь неугасимо пылает в твоем сердце, $N!Стихии ждут тебя.','Поговорите с Телфом Джоламом, чтобы получить еще одну сапту огня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сапта огня',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Телфом Джоламом, чтобы получить еще одну сапту огня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть огонь неугасимо пылает в твоем сердце, $N!Стихии ждут тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поговорите с Телфом Джоламом, чтобы получить еще одну сапту огня.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1465,'Расследование Валарриэля','При осмотре повозки удается найти подвеску, а также следы, ведущие на юг – туда, где над фортом поднимается легкий дымок, заставляющий думать не о пожаре и горящих домах, а об очаге или костре, на котором готовится пища. Должно быть, если Малемы еще живы, их увели в том направлении.$B$BВаларриэль непременно должен увидеть подвеску – и об этих признаках жизни на юге ему тоже нужно рассказать...','Принесите подвеску Малемов в Пустоши Валарриелю Истребителю Демонов.','Я в ярости! Подумать только, какой провал!..$B$BИ ведь этих двоих предупреждали, что здесь крайне опасно. А теперь они оба пропали... И хорошо, если живы.$B$BГоворишь, ты видел следы, ведущие к ближнему форту?.. Что ж, возможно, у нас все еще есть шанс...$B$BМестные жители говорят, что в этой крепости обосновались орки Пылающего Клинка – те, что служат демонам. Я вовсе не хочу сказать, что вся Орда придерживается подобных верований – но это сейчас неважно, а важно то, что эти орки непременно убьют тебя, если увидят, что ты пытаешься что-то разведать неподалеку от их форта.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расследование Валарриэля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При осмотре повозки удается найти подвеску, а также следы, ведущие на юг – туда, где над фортом поднимается легкий дымок, заставляющий думать не о пожаре и горящих домах, а об очаге или костре, на котором готовится пища. Должно быть, если Малемы еще живы, их увели в том направлении.$B$BВаларриэль непременно должен увидеть подвеску – и об этих признаках жизни на юге ему тоже нужно рассказать...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите подвеску Малемов в Пустоши Валарриелю Истребителю Демонов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я в ярости! Подумать только, какой провал!..$B$BИ ведь этих двоих предупреждали, что здесь крайне опасно. А теперь они оба пропали... И хорошо, если живы.$B$BГоворишь, ты видел следы, ведущие к ближнему форту?.. Что ж, возможно, у нас все еще есть шанс...$B$BМестные жители говорят, что в этой крепости обосновались орки Пылающего Клинка – те, что служат демонам. Я вовсе не хочу сказать, что вся Орда придерживается подобных верований – но это сейчас неважно, а важно то, что эти орки непременно убьют тебя, если увидят, что ты пытаешься что-то разведать неподалеку от их форта.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1466,'Реагенты для Поисковой корпорации','Это последнее в списке. Врать не буду, задание не из приятных; к тому же оно наверняка займет у тебя больше времени, чем предыдущие.$B$BНу ладно, хватит болтать. Вот гляди: Скрытный Кудесник тут пишет, что ему нужны мозги любых пожирателей маны или охотников на магов... крылья Пустоты ему еще нужны, от любой Девы, Сестры или Колдуньи Пустоты... и еще... кровь тюремщика судеб ему еще нужна, причем кровь капитана или их лорда.$B$BПростенькое такое заданьице, точно? Слушай, я тебе вот что скажу: если ты откажешься, я пойму.','Принесите 10 мозгов гончих Скверны, 10 крыльев пустоты и 10 фиалов крови тюремщика судеб в Пустоши Крелдигу Унгору.','Я даже и представить себе не мог, что все эти демонические твари обитают тут, в Пустошах. Мне все как-то казалось, что после ухода эльфов тут кентавры живут...$B$BИнтересно, как здесь эти твари оказались и чего им тут надо?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реагенты для Поисковой корпорации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это последнее в списке. Врать не буду, задание не из приятных; к тому же оно наверняка займет у тебя больше времени, чем предыдущие.$B$BНу ладно, хватит болтать. Вот гляди: Скрытный Кудесник тут пишет, что ему нужны мозги любых пожирателей маны или охотников на магов... крылья Пустоты ему еще нужны, от любой Девы, Сестры или Колдуньи Пустоты... и еще... кровь тюремщика судеб ему еще нужна, причем кровь капитана или их лорда.$B$BПростенькое такое заданьице, точно? Слушай, я тебе вот что скажу: если ты откажешься, я пойму.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 мозгов гончих Скверны, 10 крыльев пустоты и 10 фиалов крови тюремщика судеб в Пустоши Крелдигу Унгору.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я даже и представить себе не мог, что все эти демонические твари обитают тут, в Пустошах. Мне все как-то казалось, что после ухода эльфов тут кентавры живут...$B$BИнтересно, как здесь эти твари оказались и чего им тут надо?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1467,'Реагенты для Поисковой корпорации','Хочешь плату получить? Так за этим тебе придется вернуться в Стальгорн и потолковать со стариной Ройттеном. Думаю, он будет рад отделаться, наконец, от коробки Кудесника. Отдашь ему вот это, и получишь свою награду. $B$BДа ты не беспокойся: когда я вернусь, то всяко замолвлю за тебя словечко. Мне тоже не больно-то хочется торчать в этих самых Пустошах.','Доставьте коробку Скрытного Кудесника в Стальгорн Ройттену Камнемолоту.','О, а вот и посылка для Скрытного Кудесника, прямиком из Пустошей! Прекрасно! Ценю твою работу, $C: к тому же, тебе удалось уложиться в срок. Приятно было с тобой работать.$B$BВот тут твоя плата. И пусть все знают, что Горная корпорация всегда оплачивает услуги своих работников по высшему разряду!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реагенты для Поисковой корпорации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь плату получить? Так за этим тебе придется вернуться в Стальгорн и потолковать со стариной Ройттеном. Думаю, он будет рад отделаться, наконец, от коробки Кудесника. Отдашь ему вот это, и получишь свою награду. $B$BДа ты не беспокойся: когда я вернусь, то всяко замолвлю за тебя словечко. Мне тоже не больно-то хочется торчать в этих самых Пустошах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте коробку Скрытного Кудесника в Стальгорн Ройттену Камнемолоту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, а вот и посылка для Скрытного Кудесника, прямиком из Пустошей! Прекрасно! Ценю твою работу, $C: к тому же, тебе удалось уложиться в срок. Приятно было с тобой работать.$B$BВот тут твоя плата. И пусть все знают, что Горная корпорация всегда оплачивает услуги своих работников по высшему разряду!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1468,'Детская неделя','Можешь ли ты помочь нам позаботиться о сиротах? Да благословят тебя боги! Твоя помощь неоценима.$B$BВозьми этот свисток. Ты сможешь использовать его только во время Детской недели. Свистни в него – и сможешь поговорить с ребенком, о котором будешь заботиться. Свистни еще раз – ребенок уйдет.$B$BВсе очень просто, $n: используй свисток и заботься о ребенке. Любой сирота будет рад встрече с тобой.','Воспользуйтесь детской свистулькой. Присматривайте за сиротой в течение всей Детской недели.','Э... ну, привет. Меня зовут Рандис, ты будешь за мной присматривать, да? А ты – $Gискатель:искательница; приключений? Мама и папа тоже были такими. Значит, ты меня поймешь!B$BДавай играть! Воспитатели мне сказали, что ты мне будешь вроде $Gстаршего:старшей; $Gбрата:сестры;. Это здорово! Если бы у меня были настоящие братишки и сестренки...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Детская неделя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Можешь ли ты помочь нам позаботиться о сиротах? Да благословят тебя боги! Твоя помощь неоценима.$B$BВозьми этот свисток. Ты сможешь использовать его только во время Детской недели. Свистни в него – и сможешь поговорить с ребенком, о котором будешь заботиться. Свистни еще раз – ребенок уйдет.$B$BВсе очень просто, $n: используй свисток и заботься о ребенке. Любой сирота будет рад встрече с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь детской свистулькой. Присматривайте за сиротой в течение всей Детской недели.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Э... ну, привет. Меня зовут Рандис, ты будешь за мной присматривать, да? А ты – $Gискатель:искательница; приключений? Мама и папа тоже были такими. Значит, ты меня поймешь!B$BДавай играть! Воспитатели мне сказали, что ты мне будешь вроде $Gстаршего:старшей; $Gбрата:сестры;. Это здорово! Если бы у меня были настоящие братишки и сестренки...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1469,'Рапсодия о болоте','Перед тем как лететь, я выпил полный бочонок портера. Ик!$b$bЧто это был за полет! Я несся по воздуху, а Брохан болтался за моей спиной, но храма мы не видели. Ик!$b$bИ не нашли бы мы его никогда, если бы я не нагрузился так, что сверзился из седла. Упал в воду, пошел прямо на дно. А тут, откуда ни возьмись, целое стадо отвратительных троллей! Конечно, я постарался убраться оттуда как можно быстрее. Еле выбрался, однако прихватил с собой вот этот сувенир. Держите, отнесете его Брохану и расскажете, что храм этот его – там, под водой. Ик!','Отнесите фрагмент таблички Атал\'ай Брохану Бочкопузу в Штормград.','Рапсод Землекоп! Точно! Как я мог забыть такое имя?$B$BТак он все это время знал о том, что храм затонул? Что ж, это точно сэкономит вам время.$B$BНо предмет, сделанный Атал\'ай... Вот это находка!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рапсодия о болоте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед тем как лететь, я выпил полный бочонок портера. Ик!$b$bЧто это был за полет! Я несся по воздуху, а Брохан болтался за моей спиной, но храма мы не видели. Ик!$b$bИ не нашли бы мы его никогда, если бы я не нагрузился так, что сверзился из седла. Упал в воду, пошел прямо на дно. А тут, откуда ни возьмись, целое стадо отвратительных троллей! Конечно, я постарался убраться оттуда как можно быстрее. Еле выбрался, однако прихватил с собой вот этот сувенир. Держите, отнесете его Брохану и расскажете, что храм этот его – там, под водой. Ик!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите фрагмент таблички Атал\'ай Брохану Бочкопузу в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рапсод Землекоп! Точно! Как я мог забыть такое имя?$B$BТак он все это время знал о том, что храм затонул? Что ж, это точно сэкономит вам время.$B$BНо предмет, сделанный Атал\'ай... Вот это находка!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1470,'Приоткрывая завесу','Приветствую тебя, дитя. Вижу, ты только вступаешь на пути чернокнижия, мощь его не дается тебе пока. Я чувствую, как велико твое желание учиться. $b$bДа, ты будешь учиться. $b$bВ невежестве нет силы. Знание – вот залог нашего могущества. Знания позволяют нам контролировать хаотическую магию и тварей Бездны, склоняя их к своей воле. $b$bЯ покажу тебе, как подчинять себе слугу, но сначала принеси мне три черепа скелетов-костетрясов, бродящих близ покинутой кузницы.','Принесите Вении Мартанд 3 черепа гремучих скелетов.','Твои силы пока малы, но мне кажется, что ты уже начинаешь ощущать скрытые возможности. \n\nДаже мертвый может почувствовать себя живым, когда эта сила циркулирует в нас.','Вернитесь к Вении Мартанд в Паучью низину, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приоткрывая завесу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, дитя. Вижу, ты только вступаешь на пути чернокнижия, мощь его не дается тебе пока. Я чувствую, как велико твое желание учиться. $b$bДа, ты будешь учиться. $b$bВ невежестве нет силы. Знание – вот залог нашего могущества. Знания позволяют нам контролировать хаотическую магию и тварей Бездны, склоняя их к своей воле. $b$bЯ покажу тебе, как подчинять себе слугу, но сначала принеси мне три черепа скелетов-костетрясов, бродящих близ покинутой кузницы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Вении Мартанд 3 черепа гремучих скелетов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твои силы пока малы, но мне кажется, что ты уже начинаешь ощущать скрытые возможности. \n\nДаже мертвый может почувствовать себя живым, когда эта сила циркулирует в нас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вении Мартанд в Паучью низину, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1471,'Оковы','Ты наверняка уже $gвидел:видела; круг призыва. Только в его пределы ты можешь вызвать демона Бездны.$b$bПри помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии.$B$bПодчиненный демон Бездны будет неразрывно связан с тобой. Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва. Ты сможешь пользоваться им, когда захочешь.','При помощи Рун Призыва вызовите и подчините себе демона Бездны, а потом верните Руны Призыва Карендину Халгару в Квартале Магов Подгорода.','Надеюсь, ты преуспеешь в своих начинаниях, $N. Впрочем, если тебе не удастся задуманное, мое недовольство покажется тебе сущим пустяком.','Вернитесь к Карендину Халгару в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оковы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты наверняка уже $gвидел:видела; круг призыва. Только в его пределы ты можешь вызвать демона Бездны.$b$bПри помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии.$B$bПодчиненный демон Бездны будет неразрывно связан с тобой. Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва. Ты сможешь пользоваться им, когда захочешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи Рун Призыва вызовите и подчините себе демона Бездны, а потом верните Руны Призыва Карендину Халгару в Квартале Магов Подгорода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты преуспеешь в своих начинаниях, $N. Впрочем, если тебе не удастся задуманное, мое недовольство покажется тебе сущим пустяком.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карендину Халгару в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1472,'Пожиратель Душ','Суккубы – пожирательницы душ, разбивающие сердца и вводящие мужчин в искушение. Существа, исполненные зла и изощренной хитрости.$b$bПросто так их в наш мир не выманишь.$b$bМы обратим их собственную силу в слабость. Суккубы не смогут устоять перед соблазном завладеть душами добрых, целомудренных и любящих мужчин, и явятся в Азерот. Тогда можно будет побороть их и подчинить себе.$b$bСтупай в Храм и поговори с моим помощником, Годриком Фарсаном. Он поможет тебе подобрать приманку.','Поговорите с Годриком Фарсаном в Храме Проклятых.','Тебя прислал Карендин? Говоришь, ты $N?$B$BНе думай, что я просто беспомощный слепец. Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожиратель Душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Суккубы – пожирательницы душ, разбивающие сердца и вводящие мужчин в искушение. Существа, исполненные зла и изощренной хитрости.$b$bПросто так их в наш мир не выманишь.$b$bМы обратим их собственную силу в слабость. Суккубы не смогут устоять перед соблазном завладеть душами добрых, целомудренных и любящих мужчин, и явятся в Азерот. Тогда можно будет побороть их и подчинить себе.$b$bСтупай в Храм и поговори с моим помощником, Годриком Фарсаном. Он поможет тебе подобрать приманку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Годриком Фарсаном в Храме Проклятых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Карендин? Говоришь, ты $N?$B$BНе думай, что я просто беспомощный слепец. Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1473,'Создание Бездны','Похоже, ты $gготов:готова; призвать демона Бездны.$b$bЭти твари появляются из Круговерти Пустоты, лежащей за пределами мира. Если ты не сможешь подчинить себе вызванного демона, он разорвет тебя на части.$b$bПервого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре.$b$bК сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда. Принеси книгу, и я наделю тебя знаниями.','Найдите гримуар Эгалина и отнесите его Карендину Халгару в Храм Проклятых.','А, великолепно. Вероятно, Перрин не догадывался, какие знания скрывает в себе этот фолиант.\n\nМы больше не допустим хищения книги. Смотри: вот схема заклинания, объясняющая, как следует направлять энергию.','Эгалин был моим учителем. Он повелевал вызванным им демоном Бездны без малейших затруднений.$B$BКогда пришел мой черед подчинить себе эту тварь, я был слишком самоуверенным. Не обманывайся своим мнимым могуществом, Эккетзул, с этой тварью ни на секунду нельзя терять бдительности.','Вернитесь к Карендину Халгару в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Создание Бездны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, ты $gготов:готова; призвать демона Бездны.$b$bЭти твари появляются из Круговерти Пустоты, лежащей за пределами мира. Если ты не сможешь подчинить себе вызванного демона, он разорвет тебя на части.$b$bПервого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре.$b$bК сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда. Принеси книгу, и я наделю тебя знаниями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите гримуар Эгалина и отнесите его Карендину Халгару в Храм Проклятых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, великолепно. Вероятно, Перрин не догадывался, какие знания скрывает в себе этот фолиант.\n\nМы больше не допустим хищения книги. Смотри: вот схема заклинания, объясняющая, как следует направлять энергию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эгалин был моим учителем. Он повелевал вызванным им демоном Бездны без малейших затруднений.$B$BКогда пришел мой черед подчинить себе эту тварь, я был слишком самоуверенным. Не обманывайся своим мнимым могуществом, Эккетзул, с этой тварью ни на секунду нельзя терять бдительности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карендину Халгару в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1474,'Оковы','При помощи этих сердец наложи заклинание на круг призыва, чтобы открыть дверь в наш мир для суккуба. Твои силы возросли, и они понадобятся тебе, чтобы одолеть демоницу.$b$bОстерегайся ее чар, $n, даже сила воли может не защитить от них. Если ты победишь, суккуб вернется в Бездну, а я научу тебя заклинанию, которое позволит тебе вызывать ее в любой момент.','При помощи Чистых Сердец призовите и подчините себе суккуба, а потом верните Чистые Сердца Карендину Халгару в Квартале Магов Подгорода.','И снова ты $Gсправился:справилась; с заданием. Давно мне не встречались чернокнижники с такими задатками. Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям.$B$BА теперь я хочу научить тебя заклинанию призва личного суккуба.','Суккуб – один из самых опасных обитателей Бездны, поскольку быстро подчиняет себе слабых духом.$B$BНикогда не забывай об этом.','Вернитесь к Карендину Халгару в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оковы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При помощи этих сердец наложи заклинание на круг призыва, чтобы открыть дверь в наш мир для суккуба. Твои силы возросли, и они понадобятся тебе, чтобы одолеть демоницу.$b$bОстерегайся ее чар, $n, даже сила воли может не защитить от них. Если ты победишь, суккуб вернется в Бездну, а я научу тебя заклинанию, которое позволит тебе вызывать ее в любой момент.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи Чистых Сердец призовите и подчините себе суккуба, а потом верните Чистые Сердца Карендину Халгару в Квартале Магов Подгорода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И снова ты $Gсправился:справилась; с заданием. Давно мне не встречались чернокнижники с такими задатками. Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям.$B$BА теперь я хочу научить тебя заклинанию призва личного суккуба.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Суккуб – один из самых опасных обитателей Бездны, поскольку быстро подчиняет себе слабых духом.$B$BНикогда не забывай об этом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карендину Халгару в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1475,'В Храме Атал\'Хаккара','Храм Атал\'Хаккара посвящен древнему божеству Хаккару Свежевателю Душ. Храм охраняет злобное племя троллей Атал\'ай, и он, если верить слухам, неприступен.$b$bТеперь, когда он затонул, добывать в нем артефакты стало еще сложнее. Но это именно то, о чем я вас прошу, $n.$b$bПомогите мне собрать целые таблички Атал\'ай. Принесите их мне, и я вернусь в Лигу Исследователей героем. Вместе мы добьемся успеха!','Соберите 10 табличек Атал\'ай для Брохана Бочкопуза из Штормграда.','Таблички Атал\'ай! Благодарю, $N!$B$BКогда я доставлю их в Лигу Исследователей, наши имена войдут в историю. Вы помогли старому дворфу выполнить его последнее задание, и я бесконечно признателен вам за это!','Поскольку для меня наступили не лучшие времена, я обращаюсь к вам, Кавару. Если б только мои старые кости позволяли мне преодолеть Болото Печали и добраться до затопленного храма, я бы непременно сражался рядом с вами!$B$BВ былые времена гордость не позволила бы мне просить вас о помощи, но ныне я слишком стар, чтобы справиться сам. Прошу, помогите мне! Я хочу уйти в отставку, выполнив последнее поручение Лиги Исследователей.','Вернитесь к Брохану Бочкопузу в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Храме Атал\'Хаккара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Храм Атал\'Хаккара посвящен древнему божеству Хаккару Свежевателю Душ. Храм охраняет злобное племя троллей Атал\'ай, и он, если верить слухам, неприступен.$b$bТеперь, когда он затонул, добывать в нем артефакты стало еще сложнее. Но это именно то, о чем я вас прошу, $n.$b$bПомогите мне собрать целые таблички Атал\'ай. Принесите их мне, и я вернусь в Лигу Исследователей героем. Вместе мы добьемся успеха!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 табличек Атал\'ай для Брохана Бочкопуза из Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Таблички Атал\'ай! Благодарю, $N!$B$BКогда я доставлю их в Лигу Исследователей, наши имена войдут в историю. Вы помогли старому дворфу выполнить его последнее задание, и я бесконечно признателен вам за это!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поскольку для меня наступили не лучшие времена, я обращаюсь к вам, Кавару. Если б только мои старые кости позволяли мне преодолеть Болото Печали и добраться до затопленного храма, я бы непременно сражался рядом с вами!$B$BВ былые времена гордость не позволила бы мне просить вас о помощи, но ныне я слишком стар, чтобы справиться сам. Прошу, помогите мне! Я хочу уйти в отставку, выполнив последнее поручение Лиги Исследователей.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брохану Бочкопузу в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1476,'Чистые сердца','Добрые и честные люди? Разве они существуют?$b$bПосле долгих поисков и расспросов мне удалось найти только двоих.$b$bПервый из них – Далин Искусник. Он посвятил свою жизнь заботе о лордеронских беженцах, которых отказалась принять родня в Стене Седогрива.$b$bВторой – Комер Виллард. Он верен своей утраченной любви и бродит по Болотине в поисках супруги.$b$bПринеси их сердца Карендину. Но сначала я покажу тебе твоих жертв.','Принесите сердца Далина Искусника и Комера Вилларда Карендину Халгару в Храм Проклятых.','А с виду доброе сердце ничем не отличается от любого другого, да?$B$BМожет быть, мы просто... по-другому смотрим на мир. Но эти сердца прекрасно подойдут. Не сомневаюсь, их чистота привлечет суккуба.','Я приятно удивлен тем, как быстро ты справляешься с заданиями, $N. Принеси мне сердца, и я преисполнюсь еще большего уважения.','Вернитесь к Карендину Халгару в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чистые сердца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добрые и честные люди? Разве они существуют?$b$bПосле долгих поисков и расспросов мне удалось найти только двоих.$b$bПервый из них – Далин Искусник. Он посвятил свою жизнь заботе о лордеронских беженцах, которых отказалась принять родня в Стене Седогрива.$b$bВторой – Комер Виллард. Он верен своей утраченной любви и бродит по Болотине в поисках супруги.$b$bПринеси их сердца Карендину. Но сначала я покажу тебе твоих жертв.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сердца Далина Искусника и Комера Вилларда Карендину Халгару в Храм Проклятых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А с виду доброе сердце ничем не отличается от любого другого, да?$B$BМожет быть, мы просто... по-другому смотрим на мир. Но эти сердца прекрасно подойдут. Не сомневаюсь, их чистота привлечет суккуба.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я приятно удивлен тем, как быстро ты справляешься с заданиями, $N. Принеси мне сердца, и я преисполнюсь еще большего уважения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карендину Халгару в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1477,'Важные поставки','Наши маги проводят исследования в Крепости Стражей Пустоты, в Выжженных землях – исследования, жизненно важные для понимания Темного портала. Они почти постоянно требуют поставок, однако доставлять что бы то ни было в крепость крайне сложно.$B$BМы просим твоей помощи в обеспечении прибытия поставок в Крепость Стражей Пустоты. Сдай рапорт начальнику стражи Соригелу в Темнолесье и сделай то, о чем он попросит. Но это задание приведет тебя во враждебные земли, $n. Приготовься к любым опасностям.','Поговорите с начальником стражи Соригелом в Темнолесье, что в Сумеречном лесу.','Тебя послал Андромах? Очень хорошо. У меня для тебя важное задание...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важные поставки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши маги проводят исследования в Крепости Стражей Пустоты, в Выжженных землях – исследования, жизненно важные для понимания Темного портала. Они почти постоянно требуют поставок, однако доставлять что бы то ни было в крепость крайне сложно.$B$BМы просим твоей помощи в обеспечении прибытия поставок в Крепость Стражей Пустоты. Сдай рапорт начальнику стражи Соригелу в Темнолесье и сделай то, о чем он попросит. Но это задание приведет тебя во враждебные земли, $n. Приготовься к любым опасностям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с начальником стражи Соригелом в Темнолесье, что в Сумеречном лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал Андромах? Очень хорошо. У меня для тебя важное задание...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1478,'Призыв Халгара','А, $n! Я только что получил новости от Карендина Халгара – он хочет поговорить с вами насчет дальнейшего обучения.$B$BМожете гордиться собой! Не каждый день мастер Халгар решает самолично проинструктировать юного чернокнижника.$B$BЕго можно найти в Квартале Магов Подгорода, возле Храма Проклятых.','Поговорите с Карендином Халгаром в Подгороде.','Я полагаю, ты уже собрал достаточно погибельника?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв Халгара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $n! Я только что получил новости от Карендина Халгара – он хочет поговорить с вами насчет дальнейшего обучения.$B$BМожете гордиться собой! Не каждый день мастер Халгар решает самолично проинструктировать юного чернокнижника.$B$BЕго можно найти в Квартале Магов Подгорода, возле Храма Проклятых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Карендином Халгаром в Подгороде.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я полагаю, ты уже собрал достаточно погибельника?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1479,'Ветвь Вечности','Я слышал, что ночные эльфы устроили банк прямо внутри дерева, которое похоже на медведя! Круто! Ночные эльфы очень милые, а как они любят природу! Но медведи – это совсем здорово!$b$bСводи меня посмотреть на древо-медведя в Дарнас! Пожалуйста! Мы можем доплыть туда на корабле, много времени это не займет. Пожалуйста, пожалуйста, пожалуйста!','Отведите сироту к банку Дарнаса. Банк находится в дупле дерева, которое называется Ветвь Вечности.','Разве мы уже там?','Отправиться в банк Дарнаса, известный также как Ветвь Вечности.','Поговорите со своим подопечным ребенком-сиротой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветвь Вечности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, что ночные эльфы устроили банк прямо внутри дерева, которое похоже на медведя! Круто! Ночные эльфы очень милые, а как они любят природу! Но медведи – это совсем здорово!$b$bСводи меня посмотреть на древо-медведя в Дарнас! Пожалуйста! Мы можем доплыть туда на корабле, много времени это не займет. Пожалуйста, пожалуйста, пожалуйста!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите сироту к банку Дарнаса. Банк находится в дупле дерева, которое называется Ветвь Вечности.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разве мы уже там?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправиться в банк Дарнаса, известный также как Ветвь Вечности.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим подопечным ребенком-сиротой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1480,'Осквернитель душ','Эта рваная кожа пахнет гнилью, и она на удивление мягкая и гибкая для такого сухого и хрупкого на вид материала.$b$bЕсли ее развернуть, на ней видны красные письмена на непонятном наречии. А внизу – очень отчетливый отдельный символ, должно быть, подпись.$b$bМожет быть, Маурин сумеет объяснить, что это такое?','Отнесите рваную демонскую кожу Маурину Костолому в Пустоши.','Да, $N, это действительно чужой язык, и весьма древний. Он отчасти напоминает эредан, но отличия несомненны. Если не ошибаюсь, это нечто вроде договора... Да, вот этот символ – подпись демона: лорд Азреток.','Чернокнижники Пылающего Клинка начинают понимать, насколько они бессильны. Их магия не внушает ничего, кроме презрения.$B$BВсей своей силой они обязаны тем, кому служат, а вовсе не истинному знанию и пониманию законов магии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернитель душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта рваная кожа пахнет гнилью, и она на удивление мягкая и гибкая для такого сухого и хрупкого на вид материала.$b$bЕсли ее развернуть, на ней видны красные письмена на непонятном наречии. А внизу – очень отчетливый отдельный символ, должно быть, подпись.$b$bМожет быть, Маурин сумеет объяснить, что это такое?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите рваную демонскую кожу Маурину Костолому в Пустоши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $N, это действительно чужой язык, и весьма древний. Он отчасти напоминает эредан, но отличия несомненны. Если не ошибаюсь, это нечто вроде договора... Да, вот этот символ – подпись демона: лорд Азреток.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чернокнижники Пылающего Клинка начинают понимать, насколько они бессильны. Их магия не внушает ничего, кроме презрения.$B$BВсей своей силой они обязаны тем, кому служат, а вовсе не истинному знанию и пониманию законов магии.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1481,'Осквернитель душ','Пожалуй, я сумею отыскать этого повелителя демонов, если найду нужные реагенты.$b$bОднако если он действительно так могуществен, мне понадобятся предметы, собранные со смертельно опасных тварей...$b$bПрежде всего мне придется снять заклятия, которые защищают его от соглядатаев. Для этого нужен скальп сатира, но не первого попавшегося, а тенелова племени Ярой Ненависти.$b$bИщи их в древних развалинах на северо-востоке Пустошей.','Принесите скальп тенелова Маурину Костолому в Пустошах.','Что, |3-6($C), тенеловы тебя не убили? Неплохо, очень неплохо.$B$BДа, этот скальп мне подходит. Пока тебя не было, мне удалось собрать остальные необходимые реагенты.$B$BЯ почти готов. Мне необходима только точка приложения заклинания – тот предмет, в котором мы увидим повелителя демонов и место, где он находится.','Смотри, $R, принеси именно тот скальп, что надо! Мы оба погибнем, если используем неправильные реагенты. Повелитель демонов наверняка защищен заклинаниями, которые убивают непрошеных соглядатаев!$B$BДовольно с меня былых мучений.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернитель душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуй, я сумею отыскать этого повелителя демонов, если найду нужные реагенты.$b$bОднако если он действительно так могуществен, мне понадобятся предметы, собранные со смертельно опасных тварей...$b$bПрежде всего мне придется снять заклятия, которые защищают его от соглядатаев. Для этого нужен скальп сатира, но не первого попавшегося, а тенелова племени Ярой Ненависти.$b$bИщи их в древних развалинах на северо-востоке Пустошей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите скальп тенелова Маурину Костолому в Пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, |3-6($C), тенеловы тебя не убили? Неплохо, очень неплохо.$B$BДа, этот скальп мне подходит. Пока тебя не было, мне удалось собрать остальные необходимые реагенты.$B$BЯ почти готов. Мне необходима только точка приложения заклинания – тот предмет, в котором мы увидим повелителя демонов и место, где он находится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Смотри, $R, принеси именно тот скальп, что надо! Мы оба погибнем, если используем неправильные реагенты. Повелитель демонов наверняка защищен заклинаниями, которые убивают непрошеных соглядатаев!$B$BДовольно с меня былых мучений.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1482,'Осквернитель душ','Кристалл оракула нам подойдет. Их делают наги для своих оракулов.$b$bК северо-западу отсюда, на побережье, есть обширный коралловый риф, где поселились наги. Там можно найти и оракулов. Но Скользящий Плавник смертельно опасен и встретит тебя отнюдь не с распростертыми объятиями. Так что смотри, осторожнее, и постарайся убраться оттуда побыстрее.$b$bА когда вернешься, мы попробуем отыскать этого лорда Азретока.','Принесите кристалл оракула Маурину Костолому в Пустоши.','Драгоценный кристалл оракула! Безупречный... великолепный…$B$BЧто ж, начнем немедленно. Нам следует отыскать этого повелителя демонов.$B$BОтступи на шаг, |3-6($C), и давай посмотрим, как выглядит Азреток и где его искать.','Мне нужен кристалл оракула, $C. Если мы найдем и уничтожим этого лорда Азретока, вождь будет весьма признателен нам обоим. Так что давай работать вместе, чтобы быстрее управиться с этим делом и добиться расположения вождя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернитель душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кристалл оракула нам подойдет. Их делают наги для своих оракулов.$b$bК северо-западу отсюда, на побережье, есть обширный коралловый риф, где поселились наги. Там можно найти и оракулов. Но Скользящий Плавник смертельно опасен и встретит тебя отнюдь не с распростертыми объятиями. Так что смотри, осторожнее, и постарайся убраться оттуда побыстрее.$b$bА когда вернешься, мы попробуем отыскать этого лорда Азретока.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите кристалл оракула Маурину Костолому в Пустоши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Драгоценный кристалл оракула! Безупречный... великолепный…$B$BЧто ж, начнем немедленно. Нам следует отыскать этого повелителя демонов.$B$BОтступи на шаг, |3-6($C), и давай посмотрим, как выглядит Азреток и где его искать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужен кристалл оракула, $C. Если мы найдем и уничтожим этого лорда Азретока, вождь будет весьма признателен нам обоим. Так что давай работать вместе, чтобы быстрее управиться с этим делом и добиться расположения вождя.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1483,'[DEPRECATED] Зиз Физзикс','Торговая Компания переманила лучшие гоблинские умы, но порой у нас появляется возможность вернуть свое. $B$BНекоторое время назад подразделение Торговой Компании в Когтистых горах приняло на работу Геренцо Терминатрикса – гнома! Это так ошарашило другого инженера, Зиза Физзикса, что он умолял меня найти ему новую работу в Союзе ремонтников. Я дал ему несколько заданий, но ему может понадобиться помощь.$B$BНе навестишь его? Он живет у западного края Утеса Ветрорезов.','Поговорите с Зизом Физзиксом на Утесе Ветрорезов.','Я думал, что начальство Торговой Компании – настоящие тираны, но потом я познакомился с Пароклапаном, он хуже их всех!\n\nХа! И все же это лучше, чем сидеть без работы... Или, хуже того, работать с этим Геренцо. Если ты хочешь мне помочь, дело для тебя найдется.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Зиз Физзикс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Торговая Компания переманила лучшие гоблинские умы, но порой у нас появляется возможность вернуть свое. $B$BНекоторое время назад подразделение Торговой Компании в Когтистых горах приняло на работу Геренцо Терминатрикса – гнома! Это так ошарашило другого инженера, Зиза Физзикса, что он умолял меня найти ему новую работу в Союзе ремонтников. Я дал ему несколько заданий, но ему может понадобиться помощь.$B$BНе навестишь его? Он живет у западного края Утеса Ветрорезов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зизом Физзиксом на Утесе Ветрорезов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я думал, что начальство Торговой Компании – настоящие тираны, но потом я познакомился с Пароклапаном, он хуже их всех!\n\nХа! И все же это лучше, чем сидеть без работы... Или, хуже того, работать с этим Геренцо. Если ты хочешь мне помочь, дело для тебя найдется.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1484,'Осквернитель душ','Это существо куда опаснее, чем мне казалось! Неудивительно, что Таката сомневается, что мне удастся его одолеть. Он будет оскорблен, если не сообщить ему о том, что случилось.$b$bПоговори с мечником, скажи, что хочешь убить демона, если он разрешит, но особо не настаивай. Пусть думает, будто это его собственная идея.','Поговорите с Такатой Стальным Клинком в Пустошах.','Да, я видел, что только что произошло между Муарином и повелителем демонов! Похоже, это существо, даже в видении, обладает куда большим могуществом, чем мой соратник-чернокнижник. Сумеет ли он одолеть этого монстра? Лучше бы я занялся этим сам... Но вождю я нужен здесь. Я опозорю свой клан, если оставлю свои здешние обязанности и отправлюсь добывать себе славу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернитель душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это существо куда опаснее, чем мне казалось! Неудивительно, что Таката сомневается, что мне удастся его одолеть. Он будет оскорблен, если не сообщить ему о том, что случилось.$b$bПоговори с мечником, скажи, что хочешь убить демона, если он разрешит, но особо не настаивай. Пусть думает, будто это его собственная идея.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Такатой Стальным Клинком в Пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я видел, что только что произошло между Муарином и повелителем демонов! Похоже, это существо, даже в видении, обладает куда большим могуществом, чем мой соратник-чернокнижник. Сумеет ли он одолеть этого монстра? Лучше бы я занялся этим сам... Но вождю я нужен здесь. Я опозорю свой клан, если оставлю свои здешние обязанности и отправлюсь добывать себе славу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1485,'Злобные фамилиары','Чернокнижники, бывшие здесь до нас, внушили Орде недоверие к нам. Нас терпят, но недолюбливают.$b$bОднако это не заставило чернокнижников сплотиться. Многие предпочитают жить и заниматься магией в уединении. Я не буду принуждать тебя избрать тот или иной путь, а всего лишь помогу тебе сделать очередной шаг.$b$bНо прежде чем я научу тебя искусству призывания, принеси мне шесть голов злобных фамилиаров из той пещеры на северо-востоке.','Принесите Рузану 6 голов злобных фамилиаров.','Во время обучения ты научишься вызывать самых разных существ. Все они по-своему полезны, даже если на первый взгляд это не очевидно.\n\nПусть малый рост беса тебя не смущает. Ты уже знаешь, как опасны они бывают.','Важно уметь контролировать существ, которых ты будешь призывать с помощью магии. Интересующихся ремеслом чернокнижников и так мало, поэтому я не позволю тебе рисковать жизнью прежде, чем увижу, что ты к этому готов.','Вернитесь к Рузану в Долину Испытаний, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злобные фамилиары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чернокнижники, бывшие здесь до нас, внушили Орде недоверие к нам. Нас терпят, но недолюбливают.$b$bОднако это не заставило чернокнижников сплотиться. Многие предпочитают жить и заниматься магией в уединении. Я не буду принуждать тебя избрать тот или иной путь, а всего лишь помогу тебе сделать очередной шаг.$b$bНо прежде чем я научу тебя искусству призывания, принеси мне шесть голов злобных фамилиаров из той пещеры на северо-востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Рузану 6 голов злобных фамилиаров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во время обучения ты научишься вызывать самых разных существ. Все они по-своему полезны, даже если на первый взгляд это не очевидно.\n\nПусть малый рост беса тебя не смущает. Ты уже знаешь, как опасны они бывают.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Важно уметь контролировать существ, которых ты будешь призывать с помощью магии. Интересующихся ремеслом чернокнижников и так мало, поэтому я не позволю тебе рисковать жизнью прежде, чем увижу, что ты к этому готов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рузану в Долину Испытаний, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1486,'Шкуры загадочных существ','Пока Наралекс погружался в свои кошмары все глубже, из-под Степей в Пещеры Стенаний пришли какие-то странные животные.$b$bЭти искаженные существа наделены странными, потусторонними силами. В то время как зло в их природе, я уверен, что из их существования можно извлечь некоторую пользу здесь в Калимдоре. Я верю, что из их кожи наши кожевники смастерят что-нибудь стоящее.$b$bЕсли эта задача тебе по вкусу, отправляйся в пещеры и принеси мне немного искаженных шкур.','Принесите 20 искаженных шкур Налпаку в Пещерах Стенаний.','Я весьма заинтересован в том, чтобы исследовать шкуры этих тварей, наводнивших Пещеры Стенаний. Как успехи, |3-6($C)?','Вернитесь к Налпаку в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шкуры загадочных существ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока Наралекс погружался в свои кошмары все глубже, из-под Степей в Пещеры Стенаний пришли какие-то странные животные.$b$bЭти искаженные существа наделены странными, потусторонними силами. В то время как зло в их природе, я уверен, что из их существования можно извлечь некоторую пользу здесь в Калимдоре. Я верю, что из их кожи наши кожевники смастерят что-нибудь стоящее.$b$bЕсли эта задача тебе по вкусу, отправляйся в пещеры и принеси мне немного искаженных шкур.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 искаженных шкур Налпаку в Пещерах Стенаний.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я весьма заинтересован в том, чтобы исследовать шкуры этих тварей, наводнивших Пещеры Стенаний. Как успехи, |3-6($C)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Налпаку в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1487,'Искоренение Скверны','Цели у Наралекса были самые благие.$b$bНаш лидер стремился впасть в Изумрудный Сон, и вновь превратить эти выжженные земли в тот пышный лес, которым они когда-то являлись. Но что-то пошло не так.$b$bМечта Наралекса превратилась в кошмар, и порченые твари заселили пещеры.$b$bВ то время как некоторые приспешники Наралекса стремятся пробудить нашего мастера, я забочусь о том, чтобы избавить эти пещеры от заполонивших их тварей.$b$bОтправляйся туда, $n. и уничтожь порченое семя.','Убейте для Эбру 7 загадочных опустошителей, 7 загадочных гадюк, 7 загадочных шаркунов и 7 загадочных страхозубов.','Как послушник Наралекса я не могу не отметить твоей храбрости. Твоя помощь – это всего лишь первый шаг в очищении Степей от порчи.\n\nБлагодарю тебя, и да пребудет тобой удача.','$N, нам, ученикам Наралекса, нужна твоя помощь. Наше число сокращается, наш лидер попал в ловушку своего ужасного кошмара. У нас нет сил, необходимых для борьбы с порочными созданиями, которые теперь обитают в этих пещерах.$B$BОтправляйся туда, и уничтожь порченое семя.','Вернитесь к Эбру в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искоренение Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Цели у Наралекса были самые благие.$b$bНаш лидер стремился впасть в Изумрудный Сон, и вновь превратить эти выжженные земли в тот пышный лес, которым они когда-то являлись. Но что-то пошло не так.$b$bМечта Наралекса превратилась в кошмар, и порченые твари заселили пещеры.$b$bВ то время как некоторые приспешники Наралекса стремятся пробудить нашего мастера, я забочусь о том, чтобы избавить эти пещеры от заполонивших их тварей.$b$bОтправляйся туда, $n. и уничтожь порченое семя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте для Эбру 7 загадочных опустошителей, 7 загадочных гадюк, 7 загадочных шаркунов и 7 загадочных страхозубов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как послушник Наралекса я не могу не отметить твоей храбрости. Твоя помощь – это всего лишь первый шаг в очищении Степей от порчи.\n\nБлагодарю тебя, и да пребудет тобой удача.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, нам, ученикам Наралекса, нужна твоя помощь. Наше число сокращается, наш лидер попал в ловушку своего ужасного кошмара. У нас нет сил, необходимых для борьбы с порочными созданиями, которые теперь обитают в этих пещерах.$B$BОтправляйся туда, и уничтожь порченое семя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эбру в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1488,'Осквернитель душ','Я ничего не знаю об этом лорде Азретоке, однако согласен с Маурином: его следует остановить, особенно если он пытается подчинить себе Пылающий Клинок.$b$bТвое стремление служить вождю уже не требует доказательств, и я готов доверить тебе собрать отряд, чтобы убить Азретока и его слугу чернокнижника.$b$bКогда будете готовы выступать, отправляйтесь на юг, а покончите с ними – возвращайтесь ко мне.','Убейте лорда Азретока и Джуккара Грим\'рода и вернитесь к Такате Стальному Клинку в Пустоши.','Эта победа очень важна для нас, $N. Все мы радуемся вашему успеху. Теперь я думаю, что наше будущее не так беспросветно, как мне казалось.$B$BДемоны будут повержены, Пылающий Клинок потерпит крах, и в один прекрасный день у нас снова будет свой дом!','Слава Орде! Смерть врагам!$B$B$N, демоны Пустошей сейчас сделались опаснее, чем когда бы то ни было. Моя надежда вернуться к вождю тает: этих злобных тварей становится все больше и больше!$B$BАх, если бы нам приходилось иметь дело с одними только кентаврами!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернитель душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я ничего не знаю об этом лорде Азретоке, однако согласен с Маурином: его следует остановить, особенно если он пытается подчинить себе Пылающий Клинок.$b$bТвое стремление служить вождю уже не требует доказательств, и я готов доверить тебе собрать отряд, чтобы убить Азретока и его слугу чернокнижника.$b$bКогда будете готовы выступать, отправляйтесь на юг, а покончите с ними – возвращайтесь ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Азретока и Джуккара Грим\'рода и вернитесь к Такате Стальному Клинку в Пустоши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта победа очень важна для нас, $N. Все мы радуемся вашему успеху. Теперь я думаю, что наше будущее не так беспросветно, как мне казалось.$B$BДемоны будут повержены, Пылающий Клинок потерпит крах, и в один прекрасный день у нас снова будет свой дом!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Слава Орде! Смерть врагам!$B$B$N, демоны Пустошей сейчас сделались опаснее, чем когда бы то ни было. Моя надежда вернуться к вождю тает: этих злобных тварей становится все больше и больше!$B$BАх, если бы нам приходилось иметь дело с одними только кентаврами!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1489,'Хамуул Рунический Тотем','На раковинах, что ты мне принес, присутствует порча, которой я никогда раньше не видел. Я уверен, что причины ее возникновения кроются в воде оазиса, и я уже предчувствую, чем это грозит этим землям.$B$BИсточник этой порчи в Пещерах Стенаний, но прежде чем отправиться туда, поговори с Хамуулом Руническим Тотемом, старшим друидом. Я послал ему весточку о том, что творится в Степях. Он мудр и сможет дать тебе дельный совет.$B$BНайдешь его в Громовом Утесе, на Вершине Старейшин.','Поговорите с Хамуулом Руническим Тотемом.','Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед…\n\nТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хамуул Рунический Тотем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На раковинах, что ты мне принес, присутствует порча, которой я никогда раньше не видел. Я уверен, что причины ее возникновения кроются в воде оазиса, и я уже предчувствую, чем это грозит этим землям.$B$BИсточник этой порчи в Пещерах Стенаний, но прежде чем отправиться туда, поговори с Хамуулом Руническим Тотемом, старшим друидом. Я послал ему весточку о том, что творится в Степях. Он мудр и сможет дать тебе дельный совет.$B$BНайдешь его в Громовом Утесе, на Вершине Старейшин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хамуулом Руническим Тотемом.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед…\n\nТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1490,'Нара Буйногривая','Я вошел в сновидения и увидел там орден друидов, обитающих в Пещерах Стенаний. Когда-то их цели были благородными. Но теперь они отклонились от первоначального пути и стали слугами порчи просачивающейся из Степей.$B$BЯ уже стар, и мои силы не бесконечны. Я не мог дольше оставаться в сновидениях, хотя и хотел узнать больше об этих друидах. Но Нара молода и сильна духом, и она осталась там, когда я вынужден был уйти.$B$BПоговори с ней, $n, ты найдешь ее в дальней палатке.','Поговорите с Нарой Буйногривой.','Могу я тебе чем-то помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нара Буйногривая',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вошел в сновидения и увидел там орден друидов, обитающих в Пещерах Стенаний. Когда-то их цели были благородными. Но теперь они отклонились от первоначального пути и стали слугами порчи просачивающейся из Степей.$B$BЯ уже стар, и мои силы не бесконечны. Я не мог дольше оставаться в сновидениях, хотя и хотел узнать больше об этих друидах. Но Нара молода и сильна духом, и она осталась там, когда я вынужден был уйти.$B$BПоговори с ней, $n, ты найдешь ее в дальней палатке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Нарой Буйногривой.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Могу я тебе чем-то помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1491,'Умный напиток','Ладно, рога ящеров не сработали. Ничего страшного, с первого раза никому не удается разбогатеть. Кроме того, мне удалось придумать кое-что получше! $B$BСуществует вещество, именуемое воющей субстанцией, и мне кажется, именно из-за него в Степях такие странные растения и животные. Принеси мне немного субстанции, и я попробую добавить ее в напиток!$B$BНасколько я знаю, это вещество накапливается в эктоплазматических существах в Пещерах Стенаний на западе. Убей несколько существ из пещер и собери из них субстанцию.','Добудьте 6 порций воющей субстанции.','Где моя воющая субстанция?','Отнесите субстанцию Мебоку Миззириксу в Кабестан в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Умный напиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, рога ящеров не сработали. Ничего страшного, с первого раза никому не удается разбогатеть. Кроме того, мне удалось придумать кое-что получше! $B$BСуществует вещество, именуемое воющей субстанцией, и мне кажется, именно из-за него в Степях такие странные растения и животные. Принеси мне немного субстанции, и я попробую добавить ее в напиток!$B$BНасколько я знаю, это вещество накапливается в эктоплазматических существах в Пещерах Стенаний на западе. Убей несколько существ из пещер и собери из них субстанцию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 порций воющей субстанции.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где моя воющая субстанция?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите субстанцию Мебоку Миззириксу в Кабестан в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1492,'[DEPRECATED]Управляющий пристанью Головокружилкинс','Мне нужно послать ящик зелий, реагентов и прочего своим партнерам из Старого Света. У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл.$B$BНе $gмог:могла; бы ты отнести ящик управляющему пристанью Головокружилкинcу? А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья.','Отнесите надежный ящик управляющему пристанью Головокружилкинcу в Кабестан.','Небольшой ящик. Да, пожалуй, для него найдется место на корабле. Он отплывет в ближайший прилив, это достаточно скоро? Великолепно. Надо только записать его в мой регистр.\n\nНу вот, все готово. Пока, |3-6($C).','Желаешь отплыть на ближайшем корабле или послать товар на ту сторону света?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Управляющий пристанью Головокружилкинс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно послать ящик зелий, реагентов и прочего своим партнерам из Старого Света. У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл.$B$BНе $gмог:могла; бы ты отнести ящик управляющему пристанью Головокружилкинcу? А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите надежный ящик управляющему пристанью Головокружилкинcу в Кабестан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Небольшой ящик. Да, пожалуй, для него найдется место на корабле. Он отплывет в ближайший прилив, это достаточно скоро? Великолепно. Надо только записать его в мой регистр.\n\nНу вот, все готово. Пока, |3-6($C).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Желаешь отплыть на ближайшем корабле или послать товар на ту сторону света?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1498,'Путь защиты','Одна из основных задач воина... защита. Мы – щит Орды, заслоняющий собой наших более слабых братьев. Если ты хочешь вступить в наши ряды, докажи мне, что не струсишь.$b$bСтупай в Дуротар, на Громовой хребет, где живут бурешкуры и рокочущие ящерицы. Поохоться на них, докажи, что ты сильнее их! Выстой против них и принеси мне в доказательство побольше оплавленных чешуек.$b$bКак только принесешь, я возьмусь тебя учить.','Принесите 5 оплавленных чешуек Уззеку из Форпоста в Степях.','А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты $Gкрепкий:крепкая;. А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости.$B$BУчись хорошенько, $N. Вскоре тебе предстоит новый урок.','Ну как, $Gпринес:принесла; чешуйки? Если ты не можешь выстоять против рокочущих ящериц, я не буду тебя учить.','Вернитесь к Уззеку в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь защиты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна из основных задач воина... защита. Мы – щит Орды, заслоняющий собой наших более слабых братьев. Если ты хочешь вступить в наши ряды, докажи мне, что не струсишь.$b$bСтупай в Дуротар, на Громовой хребет, где живут бурешкуры и рокочущие ящерицы. Поохоться на них, докажи, что ты сильнее их! Выстой против них и принеси мне в доказательство побольше оплавленных чешуек.$b$bКак только принесешь, я возьмусь тебя учить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 оплавленных чешуек Уззеку из Форпоста в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты $Gкрепкий:крепкая;. А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости.$B$BУчись хорошенько, $N. Вскоре тебе предстоит новый урок.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, $Gпринес:принесла; чешуйки? Если ты не можешь выстоять против рокочущих ящериц, я не буду тебя учить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уззеку в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1499,'Злобные фамилиары','Зурита часто посылает таких новичков, как ты, приструнить этих тварей. Тебе уже доводилось сражаться с коварными фамилиарами.$b$bДумаю, тебе не помешает набраться опыта, помогая Зурите. Не забудь ей сказать, что ты $gпомогал:помогала; разобраться с бесами – возможно, у нее найдется для тебя награда.','Поговорите с Зуритой Востроглазой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злобные фамилиары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зурита часто посылает таких новичков, как ты, приструнить этих тварей. Тебе уже доводилось сражаться с коварными фамилиарами.$b$bДумаю, тебе не помешает набраться опыта, помогая Зурите. Не забудь ей сказать, что ты $gпомогал:помогала; разобраться с бесами – возможно, у нее найдется для тебя награда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зуритой Востроглазой.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1500,'Пробуждение Наралекса') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение Наралекса',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (1501,'Создание Бездны','Чернокнижников осталось так мало... Мы многим рискуем, но наш риск оправдан! Если ты хочешь принести пользу Орде и вождю, пора тебе научиться новому заклинанию призыва.$b$bДля начала добудь табличку Верги. Чернокнижники Пылающего Клинка похитили ее и хранят у себя в логове, под скалой Черепа к востоку от города. После этого я покажу тебе руны, необходимые для призыва демона Бездны.','Добудьте табличку Верги для Ган\'рула Кровавого Глаза в Оргриммаре.','Молодец. Надеюсь, во время твоего визита в логово чернокнижники Пылающего Клинка сильно пострадали?\n\nОни причинили немало вреда вождю, да и нам, чернокнижникам, тоже.','Вернитесь к Ган\'рулу Кровавому Глазу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Создание Бездны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чернокнижников осталось так мало... Мы многим рискуем, но наш риск оправдан! Если ты хочешь принести пользу Орде и вождю, пора тебе научиться новому заклинанию призыва.$b$bДля начала добудь табличку Верги. Чернокнижники Пылающего Клинка похитили ее и хранят у себя в логове, под скалой Черепа к востоку от города. После этого я покажу тебе руны, необходимые для призыва демона Бездны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте табличку Верги для Ган\'рула Кровавого Глаза в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец. Надеюсь, во время твоего визита в логово чернокнижники Пылающего Клинка сильно пострадали?\n\nОни причинили немало вреда вождю, да и нам, чернокнижникам, тоже.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ган\'рулу Кровавому Глазу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1502,'Тун\'грим Огневзор','Воину пристало владеть хорошим оружием. Самое лучшее оружие делает орк по имени Тун\'грим Огневзор. Это отшельник, который живет на вершине холма к востоку от Перекрестка.$b$bЕсли тебе нужно оружие, воин, отправляйся к Тун\'гриму. Чтобы добраться до его жилища, иди на запад до Перекрестка, а потом сверни на восток, в сторону холмов. Он разбил лагерь на самой вершине.','Поговорите с Тун\'гримом Огневзором из Степей.','Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу. Например, тебе что-то от меня нужно.$B$BИ раз ты $Gдобрался:добралась; до моего жилища, то я могу предположить, что именно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тун\'грим Огневзор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воину пристало владеть хорошим оружием. Самое лучшее оружие делает орк по имени Тун\'грим Огневзор. Это отшельник, который живет на вершине холма к востоку от Перекрестка.$b$bЕсли тебе нужно оружие, воин, отправляйся к Тун\'гриму. Чтобы добраться до его жилища, иди на запад до Перекрестка, а потом сверни на восток, в сторону холмов. Он разбил лагерь на самой вершине.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тун\'гримом Огневзором из Степей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу. Например, тебе что-то от меня нужно.$B$BИ раз ты $Gдобрался:добралась; до моего жилища, то я могу предположить, что именно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1503,'Стальные слитки','Я дам тебе оружие, $n, но прежде помоги мне. Несколько дней назад с северо-запада на меня напало племя Иглогривых. Биться со мной они побоялись, но зная, какое у меня плохое зрение, одни отвлекли меня своим пофыркиванием, а другие ограбили мой лагерь! Трусы!$b$bОни украли железный сундук, в котором лежали стальные слитки. Если ты сможешь вернуть их, я дам тебе нужное оружие.$b$bНайди мой сундук в одном из лагерей иглогривов и принеси мне стальные слитки.','Принесите стальные слитки Тун\'гриму Огневзору из Степей.','Вот они! И все мои слиточки на месте, что и неудивительно. Откуда иглогривым знать, что делать с такой отличной сталью.$B$BСпасибо, $N. Вот твоя награда. Пусть она служит тебе верой и правдой.','Ты $Gпринес:принесла; мне стальные слитки?','Вернитесь к Тунгриму Огневзору на Тернистый холм, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стальные слитки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я дам тебе оружие, $n, но прежде помоги мне. Несколько дней назад с северо-запада на меня напало племя Иглогривых. Биться со мной они побоялись, но зная, какое у меня плохое зрение, одни отвлекли меня своим пофыркиванием, а другие ограбили мой лагерь! Трусы!$b$bОни украли железный сундук, в котором лежали стальные слитки. Если ты сможешь вернуть их, я дам тебе нужное оружие.$b$bНайди мой сундук в одном из лагерей иглогривов и принеси мне стальные слитки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите стальные слитки Тун\'гриму Огневзору из Степей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот они! И все мои слиточки на месте, что и неудивительно. Откуда иглогривым знать, что делать с такой отличной сталью.$B$BСпасибо, $N. Вот твоя награда. Пусть она служит тебе верой и правдой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне стальные слитки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тунгриму Огневзору на Тернистый холм, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1504,'Оковы','Посмотри на табличку Верги. Изображенные на ней знаки понадобятся тебе для призыва. Отнеси это в круг в шатре Ниру Огненного Клинка на другом конце пещеры. Там ты сможешь вызвать демона Бездны.$b$bТебе нужно будет одолеть его любыми физическими и магическими средствами. А после этого возвращайся ко мне со знаками Призыва, и я покажу тебе, как подчинить это существо своей воле.','Используя знаки Призыва, призовите и подчините своей воле демона Бездны. Верните знаки Призыва Ган\'рулу Кровавому Глазу в Оргриммаре.','Вернитесь к Ган\'рулу Кровавому Глазу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оковы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посмотри на табличку Верги. Изображенные на ней знаки понадобятся тебе для призыва. Отнеси это в круг в шатре Ниру Огненного Клинка на другом конце пещеры. Там ты сможешь вызвать демона Бездны.$b$bТебе нужно будет одолеть его любыми физическими и магическими средствами. А после этого возвращайся ко мне со знаками Призыва, и я покажу тебе, как подчинить это существо своей воле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используя знаки Призыва, призовите и подчините своей воле демона Бездны. Верните знаки Призыва Ган\'рулу Кровавому Глазу в Оргриммаре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ган\'рулу Кровавому Глазу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1505,'Ветеран Уззек','Орда чтит своих воинов, потому что никто не сомневается в их силе. Но истинному величию чуждо самодовольство. Никогда не упускай случая поучиться новому.$b$bОтыщи Уззека. Он прошел через много сражений и теперь обучает молодых воинов боевым приемам. Он живет к югу от Форпоста, орочьего гарнизона на границе Степей и Дуротара.','Поговорите с Уззеком в Форпосте.','Приветствую тебя. Ты здесь для обучения?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветеран Уззек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда чтит своих воинов, потому что никто не сомневается в их силе. Но истинному величию чуждо самодовольство. Никогда не упускай случая поучиться новому.$b$bОтыщи Уззека. Он прошел через много сражений и теперь обучает молодых воинов боевым приемам. Он живет к югу от Форпоста, орочьего гарнизона на границе Степей и Дуротара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Уззеком в Форпосте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую тебя. Ты здесь для обучения?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1506,'Призыв от Ган\'рула','Эй, ты! Ты ведь $n, верно?$b$bНадеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Гарнул. Ты найдешь его среди старших чернокнижников в Расселине Теней.$b$bНасколько я знаю Ган\'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое.','Найдите Ган\'рула Кровавого Глаза в Оргриммаре и поговорите с ним.','Ага, хорошо. Я опасался, что Офек не сумеет с тобой связаться.\n\nТебе пора продолжить свое обучение на чернокнижника. Все прочие дела пока отложи.\n\nНадеюсь, с этим проблем не будет?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв от Ган\'рула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты! Ты ведь $n, верно?$b$bНадеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Гарнул. Ты найдешь его среди старших чернокнижников в Расселине Теней.$b$bНасколько я знаю Ган\'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Ган\'рула Кровавого Глаза в Оргриммаре и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, хорошо. Я опасался, что Офек не сумеет с тобой связаться.\n\nТебе пора продолжить свое обучение на чернокнижника. Все прочие дела пока отложи.\n\nНадеюсь, с этим проблем не будет?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1507,'Пожиратель Душ','Пора тебе научиться новому колдовству. Ты научишься вызывать суккуба, демона в женском обличье. Это существо способно зачаровывать и подчинять себе слабых духом. Но не бойся! Я уверен, тебя ей не одолеть.$b$bЧтобы приманить суккуба, нужен предмет, в котором воплощена искренняя любовь и преданность. Тебе нужно найти такую вещь.$b$bГде? Ну, потолкуй с Казулом. Чего не знает этот старый чернокнижник, того и знать не стоит.','Поговорите с Казулом в Расселине Теней.','Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожиратель Душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора тебе научиться новому колдовству. Ты научишься вызывать суккуба, демона в женском обличье. Это существо способно зачаровывать и подчинять себе слабых духом. Но не бойся! Я уверен, тебя ей не одолеть.$b$bЧтобы приманить суккуба, нужен предмет, в котором воплощена искренняя любовь и преданность. Тебе нужно найти такую вещь.$b$bГде? Ну, потолкуй с Казулом. Чего не знает этот старый чернокнижник, того и знать не стоит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Казулом в Расселине Теней.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1508,'Слепой Казул','Хмм... Но ты, конечно, здесь не за этим.$b$bРаз Ган\'рул отправил тебя ко мне, тебе, должно быть, нужно вызвать суккуба, и ты ищешь приманку...$b$bНу, если ты согласишься довериться слепому поводырю, то слушай. Среди утесов Оргриммара, к западу от башни ветрокрылов, живет Занкайя. Она ждет возращения мужа.$b$bСтупай к ней.','Поговорите с Занкайей в Оргриммаре.','У тебя есть весточка от Дограна? Он должен был вернуться уже несколько дней тому назад, а о нем до сих пор ни слуху, ни духу...','Скорее, надо выбираться отсюда, пока никто ничего не заподозрил!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слепой Казул',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хмм... Но ты, конечно, здесь не за этим.$b$bРаз Ган\'рул отправил тебя ко мне, тебе, должно быть, нужно вызвать суккуба, и ты ищешь приманку...$b$bНу, если ты согласишься довериться слепому поводырю, то слушай. Среди утесов Оргриммара, к западу от башни ветрокрылов, живет Занкайя. Она ждет возращения мужа.$b$bСтупай к ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Занкайей в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя есть весточка от Дограна? Он должен был вернуться уже несколько дней тому назад, а о нем до сих пор ни слуху, ни духу...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Скорее, надо выбираться отсюда, пока никто ничего не заподозрил!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1509,'Вести о Догране','Моего супруга, Дограна, не так давно отправили служить в Перекресток. Это было повышение по службе, он так гордился...$b$bМне, конечно, было грустно, но ему я этого не показывала. Грустно и тревожно. Степи – не Оргриммар, это опасное место, и я боялась худшего...$b$bОн должен был вернуться неделю назад, а от него до сих пор нет никаких вестей!$b$bМожет, ты сходишь в Перекресток, разузнаешь о нем? Он служил вместе с Газрогом, и Газрог, наверное, до сих пор там...','Поговорите с Газрогом в Перекрестке.','Занкайя? Жена Дограна, да?\n\nСлышать-то я о нем слышал, но это не те новости, которые стоит ей передавать.\n\nДа нет, не убили его. Но он ранен и сейчас в плену у иглогривов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вести о Догране',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моего супруга, Дограна, не так давно отправили служить в Перекресток. Это было повышение по службе, он так гордился...$b$bМне, конечно, было грустно, но ему я этого не показывала. Грустно и тревожно. Степи – не Оргриммар, это опасное место, и я боялась худшего...$b$bОн должен был вернуться неделю назад, а от него до сих пор нет никаких вестей!$b$bМожет, ты сходишь в Перекресток, разузнаешь о нем? Он служил вместе с Газрогом, и Газрог, наверное, до сих пор там...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Газрогом в Перекрестке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Занкайя? Жена Дограна, да?\n\nСлышать-то я о нем слышал, но это не те новости, которые стоит ей передавать.\n\nДа нет, не убили его. Но он ранен и сейчас в плену у иглогривов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1510,'Вести о Догране','Он был в Лагере Таурахо, где мы пытались извести иглогривов. Он повел нескольких рубак на одно из их стойбищ, и там его тяжело ранили. Остальные вернулись и попытались его выручить. Но он был в плохом состоянии, раны загноились, и ребята побоялись его трогать.$b$bОни отправили сюда послание, просили троллей из Малака\'джина у Когтистых гор прислать целительное зелье. Мы послали за зельем, но гонец пока не вернулся.','Поговорите с Кен\'зиглой в Малака\'джине.','$R? Надеюсь, ты не за тем, другим? А то он добрался не очень... благополучно. Общение с гоблинами не довело его до добра.\n\nОн успел сказать, что приехал за целительным зельем, но больше ничего вразумительного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вести о Догране',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Он был в Лагере Таурахо, где мы пытались извести иглогривов. Он повел нескольких рубак на одно из их стойбищ, и там его тяжело ранили. Остальные вернулись и попытались его выручить. Но он был в плохом состоянии, раны загноились, и ребята побоялись его трогать.$b$bОни отправили сюда послание, просили троллей из Малака\'джина у Когтистых гор прислать целительное зелье. Мы послали за зельем, но гонец пока не вернулся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кен\'зиглой в Малака\'джине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$R? Надеюсь, ты не за тем, другим? А то он добрался не очень... благополучно. Общение с гоблинами не довело его до добра.\n\nОн успел сказать, что приехал за целительным зельем, но больше ничего вразумительного.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1511,'Зелье Кен\'зиглы','Я так и думал, что за зельем явится кто-нибудь еще!$b$bВот оно, $n, бери. Имей в виду, сразу все ему не давай, пусть выпьет половину! Этого ему хватит, чтобы передвигаться. А иначе он истечет кровью. На следующее утро пусть выпьет вторую половину.$b$bОтнеси это Логмару в Лагерь Таурахо. Судя по тому, что сказал мне первый гонец, Логмар знает, где Догран.','Отнесите зелье Кен\'зиглы рубаке Логмару в Лагерь Таурахо.','О, как нельзя более кстати! А то Догран уже умирает там, в плену.\n\nЭто нужно доставить ему немедленно. Но большинство моих рубак сейчас на задании...','Да, чего тебе?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зелье Кен\'зиглы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я так и думал, что за зельем явится кто-нибудь еще!$b$bВот оно, $n, бери. Имей в виду, сразу все ему не давай, пусть выпьет половину! Этого ему хватит, чтобы передвигаться. А иначе он истечет кровью. На следующее утро пусть выпьет вторую половину.$b$bОтнеси это Логмару в Лагерь Таурахо. Судя по тому, что сказал мне первый гонец, Логмар знает, где Догран.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите зелье Кен\'зиглы рубаке Логмару в Лагерь Таурахо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, как нельзя более кстати! А то Догран уже умирает там, в плену.\n\nЭто нужно доставить ему немедленно. Но большинство моих рубак сейчас на задании...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, чего тебе?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1512,'Дар любви','Занкайя молода и красива. Зачем ей калека? Несправедливо это будет.$b$bОставь меня, $n. Спасибо тебе. Я предпочел бы умереть в славной битве, а не влачить это жалкое существование.$b$bИ прошу тебя, не говори об этом моей супруге... Не хочу, чтобы она чувствовала себя виноватой.','Отнесите подвеску, испачканную грязью, Ган\'рулу Кровавому Глазу в Оргриммар.','А, вот и ты! Ну что, готов встретиться с суккубом?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар любви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Занкайя молода и красива. Зачем ей калека? Несправедливо это будет.$b$bОставь меня, $n. Спасибо тебе. Я предпочел бы умереть в славной битве, а не влачить это жалкое существование.$b$bИ прошу тебя, не говори об этом моей супруге... Не хочу, чтобы она чувствовала себя виноватой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите подвеску, испачканную грязью, Ган\'рулу Кровавому Глазу в Оргриммар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, вот и ты! Ну что, готов встретиться с суккубом?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1513,'Оковы','Отнеси это к кругу призыва в шатре Ниру, $n. Вызови гнусного суккуба и покажи ему, кто здесь хозяин. Я верю в силу твоей магии. Но все же будь осторожнее: гордость и самоуверенность погубили немало многообещающих чернокнижников.$b$bКогда подчинишь суккуба, верни подвеску мне. Нужно будет сообщить Занкайе о случившемся.','Призовите и подчините суккуба с помощью подвески Дограна. Вернуть подвеску Ган\'рулу Кровавому Глазу в Оргриммаре.','Получилось! Впрочем, я ничего другого и не ждал, ведь ты – мой лучший ученик.\n\nТеперь я с радостью покажу тебе, как вызывать усмиренного суккуба. Ступай, тебе многому нужно научиться. Я рассчитываю, что к нашей следующей встрече ты уже по-настоящему подчинишь своего суккуба.\n\nС печальной историей Дограна и Занкайи разберутся те, кто постарше тебя. Но ты ее не забывай: она послужит хорошей защитой от хитростей темного демона, который явился к тебе сегодня.','Когда я вижу суккуба, мое сердце поет... Но в то же время я буквально чувствую, как моя душа иссыхает, утекает, как песок между пальцев.\n\nБудь осторожнее!','Вернитесь к Ган\'рулу Кровавому Глазу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оковы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси это к кругу призыва в шатре Ниру, $n. Вызови гнусного суккуба и покажи ему, кто здесь хозяин. Я верю в силу твоей магии. Но все же будь осторожнее: гордость и самоуверенность погубили немало многообещающих чернокнижников.$b$bКогда подчинишь суккуба, верни подвеску мне. Нужно будет сообщить Занкайе о случившемся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите и подчините суккуба с помощью подвески Дограна. Вернуть подвеску Ган\'рулу Кровавому Глазу в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Получилось! Впрочем, я ничего другого и не ждал, ведь ты – мой лучший ученик.\n\nТеперь я с радостью покажу тебе, как вызывать усмиренного суккуба. Ступай, тебе многому нужно научиться. Я рассчитываю, что к нашей следующей встрече ты уже по-настоящему подчинишь своего суккуба.\n\nС печальной историей Дограна и Занкайи разберутся те, кто постарше тебя. Но ты ее не забывай: она послужит хорошей защитой от хитростей темного демона, который явился к тебе сегодня.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда я вижу суккуба, мое сердце поет... Но в то же время я буквально чувствую, как моя душа иссыхает, утекает, как песок между пальцев.\n\nБудь осторожнее!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ган\'рулу Кровавому Глазу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (1514,'Оскверненный ветроцвет','Вернитесь к оскверненному ветроцвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный ветроцвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному ветроцвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1515,'Догран в плену','Ну, раз уж ты здесь и хочешь завершить свое дело, останавливать тебя я не буду. Но своих воинов я с тобой отпустить не cмогу, ступай в одиночку.$b$bДограна держат в лагере иглогривов, к северу отсюда. Ищи две хижины, стоящие рядом. Иглогривы его стерегут – если, конечно, его еще не убили, или он не умер от ран.$b$bУдачи тебе!','Отнесите зелье Кен\'зиглы Дограну в Степях.','Тьфу, гадость…\n\nОднако сил у меня прибавляется. Пожалуй, я теперь смогу уковылять отсюда... Однако похоже, что ногу мне придется отнять. И руку тоже.','Ууф-ф...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Догран в плену',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, раз уж ты здесь и хочешь завершить свое дело, останавливать тебя я не буду. Но своих воинов я с тобой отпустить не cмогу, ступай в одиночку.$b$bДограна держат в лагере иглогривов, к северу отсюда. Ищи две хижины, стоящие рядом. Иглогривы его стерегут – если, конечно, его еще не убили, или он не умер от ран.$b$bУдачи тебе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите зелье Кен\'зиглы Дограну в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тьфу, гадость…\n\nОднако сил у меня прибавляется. Пожалуй, я теперь смогу уковылять отсюда... Однако похоже, что ногу мне придется отнять. И руку тоже.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ууф-ф...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1516,'Зов Земли','Что ж, |3-6($c), пора! Ты $gнабрался:набралась; сил, твой дух стоек, как сама Земля. А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости.$b$bСтихия земли будет управлять твоей судьбой, станет частью тебя. $gГотов:Готова; ли ты? Тебе придется предстать перед самой Землей. И тогда ты увидишь многое, что ведомо лишь шаманам.$b$bРазыщи на севере ловцов скверны и добудь два их копыта. А потом возвращайся ко мне, и мы обсудим твое будущее.','Принесите Канаге заклинателю земли 2 копыта ловцов Скверны.','Великолепно! Твой успех доказывает: ты действительно $Gготов:готова;.$B$BСреди стихий именно Земля – основа всего сущего. Это твоя сила, твоя выносливость и твое терпение. Земля защитит тебя, если ты будешь относиться к ней с должным почтением. Но и Земля, как все прочие стихии, может быть своенравной.$B$BТеперь я сделаю для тебя сапту. Прими ее – и постигнешь свой путь!','Терпение – вот величайшая добродетель! Все на земле меняется: горы превращаются в пустыни, реки становятся ущельями. И лишь сама Земля остается неизменной. Она не любит нетерпеливых.$B$BТеперь Земля зовет тебя: приближается время решительной схватки! Когда ты достигнешь успеха и вернешься ко мне, ты будешь куда ближе к целостности.$B$BДругие будут завидовать твоей мудрости и ненавидеть тебя за свое невежество.','Вернитесь к Канаге заклинателю земли в Долину Испытаний, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, |3-6($c), пора! Ты $gнабрался:набралась; сил, твой дух стоек, как сама Земля. А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости.$b$bСтихия земли будет управлять твоей судьбой, станет частью тебя. $gГотов:Готова; ли ты? Тебе придется предстать перед самой Землей. И тогда ты увидишь многое, что ведомо лишь шаманам.$b$bРазыщи на севере ловцов скверны и добудь два их копыта. А потом возвращайся ко мне, и мы обсудим твое будущее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Канаге заклинателю земли 2 копыта ловцов Скверны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Твой успех доказывает: ты действительно $Gготов:готова;.$B$BСреди стихий именно Земля – основа всего сущего. Это твоя сила, твоя выносливость и твое терпение. Земля защитит тебя, если ты будешь относиться к ней с должным почтением. Но и Земля, как все прочие стихии, может быть своенравной.$B$BТеперь я сделаю для тебя сапту. Прими ее – и постигнешь свой путь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Терпение – вот величайшая добродетель! Все на земле меняется: горы превращаются в пустыни, реки становятся ущельями. И лишь сама Земля остается неизменной. Она не любит нетерпеливых.$B$BТеперь Земля зовет тебя: приближается время решительной схватки! Когда ты достигнешь успеха и вернешься ко мне, ты будешь куда ближе к целостности.$B$BДругие будут завидовать твоей мудрости и ненавидеть тебя за свое невежество.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Канаге заклинателю земли в Долину Испытаний, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1517,'Зов Земли','Сапта – это напиток, который связывает душу со стихией. Сама магия растворена в нем. И сильные духом благодаря ему способны зреть стихии, которых никто более не видит. Твой дух будет связан со стихией сапты. Лишь немногие избранные шаманы знают рецепт этого напитка.$b$bЗапомни: сапту можно пить лишь в священном месте, и нигде более!$b$bОтыщи Священный Камень к юго-западу отсюда. Он находится в конце Потайной тропы. Выпей там сапту, а дальше... увидишь!','Найдите Священный Камень и выпейте рядом с ним сапту Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сапта – это напиток, который связывает душу со стихией. Сама магия растворена в нем. И сильные духом благодаря ему способны зреть стихии, которых никто более не видит. Твой дух будет связан со стихией сапты. Лишь немногие избранные шаманы знают рецепт этого напитка.$b$bЗапомни: сапту можно пить лишь в священном месте, и нигде более!$b$bОтыщи Священный Камень к юго-западу отсюда. Он находится в конце Потайной тропы. Выпей там сапту, а дальше... увидишь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Священный Камень и выпейте рядом с ним сапту Земли.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (1518,'Зов Земли','Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались. Он создаст тотем для тебя, и этот камушек будет сердцем тотема. Он невелик, но со временем ты поймешь, что размер не имеет значения. Иногда малое оказывается долговечнее большого.$b$bБудь $gтерпелив:терпелива;, $n. Оставайся $gсильным:сильной;. И ищи мудрости. В конце концов ты станешь единым целым с Землей – чти же ее, и она будет чтить тебя.','Отнесите необработанный кварц Канаге заклинателю земли в Долину Испытаний.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались. Он создаст тотем для тебя, и этот камушек будет сердцем тотема. Он невелик, но со временем ты поймешь, что размер не имеет значения. Иногда малое оказывается долговечнее большого.$b$bБудь $gтерпелив:терпелива;, $n. Оставайся $gсильным:сильной;. И ищи мудрости. В конце концов ты станешь единым целым с Землей – чти же ее, и она будет чтить тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите необработанный кварц Канаге заклинателю земли в Долину Испытаний.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1519,'Зов Земли','Время настало, $gюный:юная:c; |3-6($c). Тело твое возмужало, а дух закалился, как сама земля. Я вижу, ты $gобрел:обрела; мудрость.$B$BЗемля ведет и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой. Но тебе придется пройти испытания. Если ты $gготов:готова;, твоему взору откроется то, о чем известно лишь нашему народу. $B$BНайди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах. Возвращайся ко мне, когда соберешь достаточно мази для изготовления зелья.','Принесите 2 порции ритуальной мази провидице Воронье Перо в Лагерь Нараче.','Отлично, $N. Ты $Gвернулся:вернулась; – а значит, $Gготов:готова; к следующему шагу.$B$BСтихия земли – это основа всех вещей. Это твоя сила, твоя выносливость и твое терпение. Мать-Земля защитит тебя, но к ней должно относиться с уважением. Она – основа жизни, и следуя ее законам, ты приумножишь мудрость. Никогда не забывай тайны, которые она разделит с тобой.$B$BТеперь я приготовлю для тебя сапту земли, который откроет перед тобой новые пути.','Земле не занимать терпения, она будет ждать, покуда ты не будешь $Gготов:готова;, ибо она знает, что с течением времени все разрушается и возрождается вновь. Это круговорот бытия. Горы превращаются в пустыни, реки становятся каньонами. Земля – самая упрямая и самая мудрая из стихий.$B$BТы $gдолжен:должна; прежде всего научиться терпению и выносливости. Земля призывает тебя, потому что знает – ты $gготов:готова;. Если ты преуспеешь, то родишься заново и навсегда распрощаешься со своим невежеством.','Вернитесь к провидице Воронье Перо на Плато Красного Облака, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время настало, $gюный:юная:c; |3-6($c). Тело твое возмужало, а дух закалился, как сама земля. Я вижу, ты $gобрел:обрела; мудрость.$B$BЗемля ведет и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой. Но тебе придется пройти испытания. Если ты $gготов:готова;, твоему взору откроется то, о чем известно лишь нашему народу. $B$BНайди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах. Возвращайся ко мне, когда соберешь достаточно мази для изготовления зелья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 порции ритуальной мази провидице Воронье Перо в Лагерь Нараче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N. Ты $Gвернулся:вернулась; – а значит, $Gготов:готова; к следующему шагу.$B$BСтихия земли – это основа всех вещей. Это твоя сила, твоя выносливость и твое терпение. Мать-Земля защитит тебя, но к ней должно относиться с уважением. Она – основа жизни, и следуя ее законам, ты приумножишь мудрость. Никогда не забывай тайны, которые она разделит с тобой.$B$BТеперь я приготовлю для тебя сапту земли, который откроет перед тобой новые пути.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Земле не занимать терпения, она будет ждать, покуда ты не будешь $Gготов:готова;, ибо она знает, что с течением времени все разрушается и возрождается вновь. Это круговорот бытия. Горы превращаются в пустыни, реки становятся каньонами. Земля – самая упрямая и самая мудрая из стихий.$B$BТы $gдолжен:должна; прежде всего научиться терпению и выносливости. Земля призывает тебя, потому что знает – ты $gготов:готова;. Если ты преуспеешь, то родишься заново и навсегда распрощаешься со своим невежеством.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провидице Воронье Перо на Плато Красного Облака, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1520,'Зов Земли','Сапта – это напиток, призванный объединить твой дух со стихиями. Сотворенное с помощью магии зелье позволит тем, чье сознание открыто, видить стихии так, как их никто не видел ранее. Твой дух будет навеки связан со стихией, для которой был создан сапта – и лишь немногим из нашего племени известен секрет его изготовления. $B$BСапта должна быть выпита в только в священном месте и более нигде. $B$BНайди шаманское святилище к востоку отсюда и выпей сапту там.','Найдите Дольмен Кодо и выпейте сапту земли.','Ах... $N... Земля ликует от того, что ты $Gпришел:пришла; сюда.$B$BТеперь ты $Gсвязан:связана; с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твое терпение, и весь мир – основа твоей сущности.$B$BДля прохождения этого обряда довольно было смиренно предстать перед землей. Но другие обряды потребуют более активных действий. Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сапта – это напиток, призванный объединить твой дух со стихиями. Сотворенное с помощью магии зелье позволит тем, чье сознание открыто, видить стихии так, как их никто не видел ранее. Твой дух будет навеки связан со стихией, для которой был создан сапта – и лишь немногим из нашего племени известен секрет его изготовления. $B$BСапта должна быть выпита в только в священном месте и более нигде. $B$BНайди шаманское святилище к востоку отсюда и выпей сапту там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Дольмен Кодо и выпейте сапту земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах... $N... Земля ликует от того, что ты $Gпришел:пришла; сюда.$B$BТеперь ты $Gсвязан:связана; с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твое терпение, и весь мир – основа твоей сущности.$B$BДля прохождения этого обряда довольно было смиренно предстать перед землей. Но другие обряды потребуют более активных действий. Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий. Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1521,'Зов Земли','Возьми этот грубый кварц и отнеси его провидице Воронье Перо в доказательство того, что мы говорили с тобой. Она создаст для тебя тотем, и этот камень станет его сердцем. Тебе может показаться, что он мал, но со временем ты поймешь, что размер не имеет значения. Иногда малое оказывается долговечнее большого.$b$bБудь $gтерпелив:терпелива;, $n. Оставайся $gсильным:сильной;. И ищи мудрости. Так угодно земле. В конце концов ты станешь единым целым с землей – чти же ее, и она будет чтить тебя.','Отнесите грубый кварц провидице Воронье Перо в Лагерь Нараче.','Прекрасно!$B$BТотем, который я сделаю для тебя – не просто символ. Он обладает тайными свойствами. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретешь, тем больше способностей земли станет тебе доступно.$B$BНаставники в Калимдоре скажут тебе, когда ты будешь $Gготов:готова; к новым знаниям.$B$BА пока возьми этот тотем Земли...','Приветствую тебя, $N. Ты бы не $gвернулась:вернулся; ко мне, если бы не выполнил задания. Позволь мне первой поздравить тебя с выбором первой дороги – первой из четырех, которым отныне ты будешь следовать во всех своих путешествиях.$B$BЕсли у тебя есть камень, который дала тебе земля, я отдам тебе обещанный тотем. Если же нет, мне жаль тебя. Посвятившему себя служению стихиям должно иметь гордость.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми этот грубый кварц и отнеси его провидице Воронье Перо в доказательство того, что мы говорили с тобой. Она создаст для тебя тотем, и этот камень станет его сердцем. Тебе может показаться, что он мал, но со временем ты поймешь, что размер не имеет значения. Иногда малое оказывается долговечнее большого.$b$bБудь $gтерпелив:терпелива;, $n. Оставайся $gсильным:сильной;. И ищи мудрости. Так угодно земле. В конце концов ты станешь единым целым с землей – чти же ее, и она будет чтить тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите грубый кварц провидице Воронье Перо в Лагерь Нараче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно!$B$BТотем, который я сделаю для тебя – не просто символ. Он обладает тайными свойствами. Его можно использовать для сосредоточения заклинаний Земли. Чем больше мудрости ты обретешь, тем больше способностей земли станет тебе доступно.$B$BНаставники в Калимдоре скажут тебе, когда ты будешь $Gготов:готова; к новым знаниям.$B$BА пока возьми этот тотем Земли...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя, $N. Ты бы не $gвернулась:вернулся; ко мне, если бы не выполнил задания. Позволь мне первой поздравить тебя с выбором первой дороги – первой из четырех, которым отныне ты будешь следовать во всех своих путешествиях.$B$BЕсли у тебя есть камень, который дала тебе земля, я отдам тебе обещанный тотем. Если же нет, мне жаль тебя. Посвятившему себя служению стихиям должно иметь гордость.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1522,'Зов Огня','Огонь с тобой, дружище! Шо, я смотрю, пути Земли тебе уже знакомы? Значит, пора тебе перетереть с Краналом.$b$bКранал живет к северу от Перекрестка, в Степях. По части стихий он очень крут, и путям Огня тебя научит на раз... если ты, конечно, $gготов:готова; к этому.$b$bНайти его – как нефиг делать, только смотри, слишком далеко не ходи, а не то к эльфам занесет.','Найдите в Степях Кранала Фисса.','Что, тебя Сеарн прислал, да?$B$BНу, на Сеарна положиться можно. Значит, ты уже $Gготов:готова; вкусить следующую сапту – сапту огня.$B$BДа, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Однако, имей терпение, $N. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огонь с тобой, дружище! Шо, я смотрю, пути Земли тебе уже знакомы? Значит, пора тебе перетереть с Краналом.$b$bКранал живет к северу от Перекрестка, в Степях. По части стихий он очень крут, и путям Огня тебя научит на раз... если ты, конечно, $gготов:готова; к этому.$b$bНайти его – как нефиг делать, только смотри, слишком далеко не ходи, а не то к эльфам занесет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Степях Кранала Фисса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, тебя Сеарн прислал, да?$B$BНу, на Сеарна положиться можно. Значит, ты уже $Gготов:готова; вкусить следующую сапту – сапту огня.$B$BДа, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Однако, имей терпение, $N. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1523,'Зов Огня','Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание, $n! Пока тебе хватало терпения в твоих занятиях, однако пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты $gготов:готова; платить за это.$b$bОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!','Найдите в Степях Кранала Фисса.','Хм, тебя Ксанис прислал ко мне?$B$BНу что ж, Ксанису всегда можно доверять. Должно быть ты уже $Gготов:готова; принять участие в следующей сапе, cапте-огня.$B$BВижу в твоих глазах, огненное желание. Ты $Gпопробовал:попробовала; власть на вкус, и теперь, ты $Gготов:готова; к большему. Терпение, $N. Помни чему учила тебя Земля. Мощь и разрушение, ты всегда $Gдолжен:должна; знать, когда нужно остановить руку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание, $n! Пока тебе хватало терпения в твоих занятиях, однако пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты $gготов:готова; платить за это.$b$bОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Степях Кранала Фисса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм, тебя Ксанис прислал ко мне?$B$BНу что ж, Ксанису всегда можно доверять. Должно быть ты уже $Gготов:готова; принять участие в следующей сапе, cапте-огня.$B$BВижу в твоих глазах, огненное желание. Ты $Gпопробовал:попробовала; власть на вкус, и теперь, ты $Gготов:готова; к большему. Терпение, $N. Помни чему учила тебя Земля. Мощь и разрушение, ты всегда $Gдолжен:должна; знать, когда нужно остановить руку.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1524,'Зов Огня','У тебя достаточно сил, чтобы управлять тотемом огня, но это еще не значит, что ты $gготов:готова; к этому.$b$bВдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране. Отыщи путь на вершину, и найдешь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени.$b$bОтнеси ему этот факел – это знак, что ты пытаешься приручить огонь. Верни мне этот факел зажженным от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотем огня.','Отнесите факел Дремлющего Пламени Телфу Джуламу в Дуротаре.','Привет тебе, $N! Ты находишься в святилище Дремлющего Пламени. Только те, кто достаточно сведущ в шаманском искусстве, способны постичь тайны этого места и силу, которую оно содержит. Мне жаль отсылать тебя ни с чем после того, как тебе пришлось проделать весь этот путь – ведь он отнюдь не безопасен! – однако я – хранитель святилища, и не могу позволить бродить здесь кому попало.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя достаточно сил, чтобы управлять тотемом огня, но это еще не значит, что ты $gготов:готова; к этому.$b$bВдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране. Отыщи путь на вершину, и найдешь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени.$b$bОтнеси ему этот факел – это знак, что ты пытаешься приручить огонь. Верни мне этот факел зажженным от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотем огня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите факел Дремлющего Пламени Телфу Джуламу в Дуротаре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет тебе, $N! Ты находишься в святилище Дремлющего Пламени. Только те, кто достаточно сведущ в шаманском искусстве, способны постичь тайны этого места и силу, которую оно содержит. Мне жаль отсылать тебя ни с чем после того, как тебе пришлось проделать весь этот путь – ведь он отнюдь не безопасен! – однако я – хранитель святилища, и не могу позволить бродить здесь кому попало.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1525,'Зов Огня','Но ты ведь здесь не затем, чтобы выслушивать лекции по истории, верно? Тебе нужно Неугасимое Пламя и тотем Огня!$b$bПервый шаг – это создать сапту, чтобы связать тебя со стихией огня.$b$bЯ могу изготовить тебе сапту, но для этого нужны две вещи. Во-первых – огненная смола, распространенное вещество, которое обычно носят при себе заклинатели Иглогривых в восточных Степях.$b$bА вот второй компонент добыть куда сложнее: это мешочек с реагентами, какие носят чернокнижники Пылающего Клинка. Их можно отыскать в пещере над ущельями к северо-востоку от Колючего Холма.','Принесите 1 порцию огненной смолы и 1 мешочек с реагентами Телфу Джуламу в Дуротаре.','У меня достаточно ингредиентов, чтобы изготовить сапту огня, если ты только раздобудешь мешочек с реактивами и немного огненной смолы. Фанатики из клана Пылающего Клинка носят при себе большую часть необходимых компонентов, так что разыскивать что-то еще обычно не приходится.$B$BСапты всегда изготовляются из ингредиентов, тесно связанных с соответствующими стихиями. Нашу задачу упрощает то, что чернокнижники всегда имеют дело с огнем.','Вернитесь к Телфу Джуламу в Святилище Дремлющего Пламени, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Но ты ведь здесь не затем, чтобы выслушивать лекции по истории, верно? Тебе нужно Неугасимое Пламя и тотем Огня!$b$bПервый шаг – это создать сапту, чтобы связать тебя со стихией огня.$b$bЯ могу изготовить тебе сапту, но для этого нужны две вещи. Во-первых – огненная смола, распространенное вещество, которое обычно носят при себе заклинатели Иглогривых в восточных Степях.$b$bА вот второй компонент добыть куда сложнее: это мешочек с реагентами, какие носят чернокнижники Пылающего Клинка. Их можно отыскать в пещере над ущельями к северо-востоку от Колючего Холма.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 порцию огненной смолы и 1 мешочек с реагентами Телфу Джуламу в Дуротаре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня достаточно ингредиентов, чтобы изготовить сапту огня, если ты только раздобудешь мешочек с реактивами и немного огненной смолы. Фанатики из клана Пылающего Клинка носят при себе большую часть необходимых компонентов, так что разыскивать что-то еще обычно не приходится.$B$BСапты всегда изготовляются из ингредиентов, тесно связанных с соответствующими стихиями. Нашу задачу упрощает то, что чернокнижники всегда имеют дело с огнем.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Телфу Джуламу в Святилище Дремлющего Пламени, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1526,'Зов Огня','Сапта огня готова. Пришло тебе время встретиться лицом к лицу со стихией пламени! Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление. Оно не нападет на тебя, пока ты не будешь $gготов:готова; к этому, однако оно поймет, что ты его видишь.$b$bПостарайся поразить его как можно быстрее, $n, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберет! Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел.','Сразитесь с низшим воплощением огня и поместите светящийся уголек в жаровню в святилище Неугасимого Пламени.','Когда вы бросаете уголек в жаровню, в чаше вспыхивает жаркое белое пламя. Вы ощущаете, как по телу разливается огонь сапты, перед глазами ритмично бьется пламя. \n\nВы опускаете факел в чашу, и он мгновенно вспыхивает.','Жаровня высотой примерно в треть вашего роста выглядит вполне обычной, если не считать того, что она покрыта письменами. Металл блестит, как новенький, чаша вверху жаровни прохладная на ощупь...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сапта огня готова. Пришло тебе время встретиться лицом к лицу со стихией пламени! Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление. Оно не нападет на тебя, пока ты не будешь $gготов:готова; к этому, однако оно поймет, что ты его видишь.$b$bПостарайся поразить его как можно быстрее, $n, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберет! Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сразитесь с низшим воплощением огня и поместите светящийся уголек в жаровню в святилище Неугасимого Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда вы бросаете уголек в жаровню, в чаше вспыхивает жаркое белое пламя. Вы ощущаете, как по телу разливается огонь сапты, перед глазами ритмично бьется пламя. \n\nВы опускаете факел в чашу, и он мгновенно вспыхивает.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Жаровня высотой примерно в треть вашего роста выглядит вполне обычной, если не считать того, что она покрыта письменами. Металл блестит, как новенький, чаша вверху жаровни прохладная на ощупь...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1527,'Зов Огня','Крепко сжимая факел, вы отступаете от жаровни, оборачиваетесь и окидываете взглядом весь Дуротар. Вас охватывает восторг. Пламя факела рвется и трепещет на ветру.$b$bИ вот вы начинаете спускаться обратно по тропе, ведущей в Степи, возвращаясь к Краналу Фиссу.','Принесите факел Неугасимого Пламени Краналу Фиссу в Степи.','Да, $N? Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крепко сжимая факел, вы отступаете от жаровни, оборачиваетесь и окидываете взглядом весь Дуротар. Вас охватывает восторг. Пламя факела рвется и трепещет на ветру.$b$bИ вот вы начинаете спускаться обратно по тропе, ведущей в Степи, возвращаясь к Краналу Фиссу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите факел Неугасимого Пламени Краналу Фиссу в Степи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N? Что у тебя там?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1528,'Зов Воды','Вода – твое будущее, дружище. Вижу, ты уже $gпокорил:покорила; огонь и, кажись, $gготов:готова; поговорить с Ислен.$B$BИслен живет на побережье ентих Степей. Топай на юг, вдоль реки Строптивая, не промахнешься – ищи нехилую акулу! Ислен – великая повелительница духов, и она научит тебя сути воды... если ты $gготов:готова;.$B$BТы ее запростяк найдешь, только на юг слишком далеко не заходи: Ислен живет рядом с Кабестаном.','Отыщите в Степях Ислену Заклинательницу Воды.','Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.\n\nПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.','Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вода – твое будущее, дружище. Вижу, ты уже $gпокорил:покорила; огонь и, кажись, $gготов:готова; поговорить с Ислен.$B$BИслен живет на побережье ентих Степей. Топай на юг, вдоль реки Строптивая, не промахнешься – ищи нехилую акулу! Ислен – великая повелительница духов, и она научит тебя сути воды... если ты $gготов:готова;.$B$BТы ее запростяк найдешь, только на юг слишком далеко не заходи: Ислен живет рядом с Кабестаном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите в Степях Ислену Заклинательницу Воды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.\n\nПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мой флот в опасности! Капитан Гордостанная и ее проклятые канониры постоянно стреляют по кораблям из своей крепости Северной стражи. Я хочу, чтобы ее солдаты расплатились за наглость. Принеси мне полную горсть медалей, снятых с ее приспешников, и я буду знать, что мои павшие бойцы отомщены.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1529,'Зов Воды','Много воды утекло со времени последнего испытания. Ты $gпроявил:проявила; немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.$B$BОтыщи Ислену Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, $n.','Отыщите в Степях Ислену Заклинательницу Воды.','Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.$B$BПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много воды утекло со времени последнего испытания. Ты $gпроявил:проявила; немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.$B$BОтыщи Ислену Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите в Степях Ислену Заклинательницу Воды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.$B$BПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1530,'Зов Воды','Первым делом ты $gдолжен:должна; понять, что вода означает возрождение. $b$bВода течет, разрушает и очищает все сущее. Ты увидишь, что вода – великий целитель, но только чистая вода.$B$BПознав, что оскверненная вода разрушает все кругом, ты поймешь и то, как вода важна для мироздания.$B$BЕсли же ты хочешь получить сапту воды, отыщи Брин в южной части Степей. На ее дом постоянно нападают иглогривы.','Отыщите Брин на Хребте Черных Шипов в Южных Степях.','Да?\n\nМ-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредет в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты? У всех нас свои причины действовать так или иначе. У меня другой вопрос – что заставило простого |3-1($R) отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие?\n\nГотова поспорить, что мы оба знаем ответ на этот вопрос.','Тебе удалось добраться до гнезд?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первым делом ты $gдолжен:должна; понять, что вода означает возрождение. $b$bВода течет, разрушает и очищает все сущее. Ты увидишь, что вода – великий целитель, но только чистая вода.$B$BПознав, что оскверненная вода разрушает все кругом, ты поймешь и то, как вода важна для мироздания.$B$BЕсли же ты хочешь получить сапту воды, отыщи Брин в южной части Степей. На ее дом постоянно нападают иглогривы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Брин на Хребте Черных Шипов в Южных Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да?\n\nМ-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредет в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты? У всех нас свои причины действовать так или иначе. У меня другой вопрос – что заставило простого |3-1($R) отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие?\n\nГотова поспорить, что мы оба знаем ответ на этот вопрос.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добраться до гнезд?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1531,'Зов Воздуха','Ты делаешь успехи, дружище. Я верю, что ты $gдостоин:достойна; тотема воздуха, но сначала надо отыскать Пратту Заклинательницу Туч в Тысяче Игл. Отнесись к ней с уважением, и она расскажет, как получить тотем.$B$BИди на юг, через Степи, а когда попадешь в Тысячу Игл, сверни на восток. Пратт прячется в пещере вместе со своим парнем. Ха-ха! Только не рассказывай ей, что я проболтался тебе об этом, а то она рассердится.','Найдите Пратту Заклинательницу Туч в Тысяче Игл.','Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотем. Возвращайся, когда будешь $Gготов:готова; продолжить обучение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты делаешь успехи, дружище. Я верю, что ты $gдостоин:достойна; тотема воздуха, но сначала надо отыскать Пратту Заклинательницу Туч в Тысяче Игл. Отнесись к ней с уважением, и она расскажет, как получить тотем.$B$BИди на юг, через Степи, а когда попадешь в Тысячу Игл, сверни на восток. Пратт прячется в пещере вместе со своим парнем. Ха-ха! Только не рассказывай ей, что я проболтался тебе об этом, а то она рассердится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Пратту Заклинательницу Туч в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотем. Возвращайся, когда будешь $Gготов:готова; продолжить обучение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1532,'Зов Воздуха','Все ветра Калимдора спешат к тебе навстречу, и скоро ты займешь достойное место среди наших самых выдающихся $gбратьев:сестер;. Я чрезвычайно горжусь твоими успехами и вижу, что тебя ждет великое будущее.$B$BДух воздуха покорить нелегко, но я верю, что ты сумеешь преодолеть любые препятствия на своем пути.$B$BОтправляйся на самый юг Степей, в Тысячу Игл. Там, на востоке, ты найдешь Пратту Заклинательницу Туч, и она продолжит твое обучение.','Найдите Пратту Заклинательницу Туч в Тысяче Игл.','Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотем. Возвращайся, когда будешь $Gготов:готова; продолжить обучение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все ветра Калимдора спешат к тебе навстречу, и скоро ты займешь достойное место среди наших самых выдающихся $gбратьев:сестер;. Я чрезвычайно горжусь твоими успехами и вижу, что тебя ждет великое будущее.$B$BДух воздуха покорить нелегко, но я верю, что ты сумеешь преодолеть любые препятствия на своем пути.$B$BОтправляйся на самый юг Степей, в Тысячу Игл. Там, на востоке, ты найдешь Пратту Заклинательницу Туч, и она продолжит твое обучение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Пратту Заклинательницу Туч в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотем. Возвращайся, когда будешь $Gготов:готова; продолжить обучение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1533,'*NYI* Зов воздуха') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','*NYI* Зов воздуха',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1534,'Зов Воды','Возьми этот бурдюк и ступай в густой лес, который ночные эльфы зовут Ясеневым. Он находится далеко на севере от Степей.$B$BДобравшись до леса, отправляйся в его западную часть. Возле гряды, отделяющей Когтистые горы от Ясеневого леса, за озером Мистраль, располагается священное место, руины Звездной Пыли. В центре озера, на островке, есть маленький фонтан. Прежде чем возвращаться к Ислен, принеси мне воду из этого источника.','Наполните пустой синий бурдюк для воды в руинах Звездной Пыли и отнесите воду Брин из Степей.','Чудесно. Теперь у меня есть все три пробы воды, и я могу наполнить фиал чистейшей водой, которую только способно найти живое существо. Она понадобится тебе на следующем этапе.$B$BЯ рада, что среди избравших наш путь есть такие, как ты, $N. Все шаманы гордятся тобой, и я надеюсь вскоре услышать о твоих подвигах.','Ты уже несешь мне воду, $N? Говорят, что руины охраняют огромные порождения природы, которые не жалуют гостей, но, вероятно, это всего лишь легенды, призванные отпугивать врагов ночных эльфов.$B$BИ все же соблюдай осторожность.','Вернитесь к Брин на Хребет Черных Шипов, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми этот бурдюк и ступай в густой лес, который ночные эльфы зовут Ясеневым. Он находится далеко на севере от Степей.$B$BДобравшись до леса, отправляйся в его западную часть. Возле гряды, отделяющей Когтистые горы от Ясеневого леса, за озером Мистраль, располагается священное место, руины Звездной Пыли. В центре озера, на островке, есть маленький фонтан. Прежде чем возвращаться к Ислен, принеси мне воду из этого источника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните пустой синий бурдюк для воды в руинах Звездной Пыли и отнесите воду Брин из Степей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно. Теперь у меня есть все три пробы воды, и я могу наполнить фиал чистейшей водой, которую только способно найти живое существо. Она понадобится тебе на следующем этапе.$B$BЯ рада, что среди избравших наш путь есть такие, как ты, $N. Все шаманы гордятся тобой, и я надеюсь вскоре услышать о твоих подвигах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже несешь мне воду, $N? Говорят, что руины охраняют огромные порождения природы, которые не жалуют гостей, но, вероятно, это всего лишь легенды, призванные отпугивать врагов ночных эльфов.$B$BИ все же соблюдай осторожность.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брин на Хребет Черных Шипов, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1535,'Зов Воды','Чтобы обрести понимание и получить от меня сапту, тебе предстоит отыскать чистейшую воду. Принося мне образцы, обращай внимание на окружающий мир – какие существа зависят от этой воды и охраняют ее. Как она влияет на леса и пустыни. Ты увидишь, как влага, дающая жизнь сущему, вынуждает различных существ отнимать эту жизнь у других.$B$BНачнем с малого: ниже моего домика есть пруд с драгоценной влагой.','Наполните пустой коричневый бурдюк для воды в источнике ниже хижины Брин и отнесите ей воду.','Я предполагала, что если ты возьмешься набирать воду, кровопролития не избежать. Жаль, что иглогривы не понимают, что все живые существа связаны между собой, а жадность лишь усиливает боль и страдания их собственного народа. О, сколь многого они достигли бы, забыв о спорах и объединившись.\n\nДа, для них это плохо, но для других обитателей Степей – скорее хорошо.','Я готова дать тебе следующее задание. Ты уже наполнила бурдюк?\n\nЯ знаю, как ревниво иглогривы относятся к водопоям. Ведь даже малый источник для них – настоящее сокровище. Они устраивают пир, если Степи осчастливит хоть небольшой дождь. Вода для них священна, ведь здесь ее очень мало. Ясно?','Вернитесь к Брин на Хребет Черных Шипов, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы обрести понимание и получить от меня сапту, тебе предстоит отыскать чистейшую воду. Принося мне образцы, обращай внимание на окружающий мир – какие существа зависят от этой воды и охраняют ее. Как она влияет на леса и пустыни. Ты увидишь, как влага, дающая жизнь сущему, вынуждает различных существ отнимать эту жизнь у других.$B$BНачнем с малого: ниже моего домика есть пруд с драгоценной влагой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните пустой коричневый бурдюк для воды в источнике ниже хижины Брин и отнесите ей воду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я предполагала, что если ты возьмешься набирать воду, кровопролития не избежать. Жаль, что иглогривы не понимают, что все живые существа связаны между собой, а жадность лишь усиливает боль и страдания их собственного народа. О, сколь многого они достигли бы, забыв о спорах и объединившись.\n\nДа, для них это плохо, но для других обитателей Степей – скорее хорошо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я готова дать тебе следующее задание. Ты уже наполнила бурдюк?\n\nЯ знаю, как ревниво иглогривы относятся к водопоям. Ведь даже малый источник для них – настоящее сокровище. Они устраивают пир, если Степи осчастливит хоть небольшой дождь. Вода для них священна, ведь здесь ее очень мало. Ясно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брин на Хребет Черных Шипов, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1536,'Зов Воды','Давным-давно мы с несколькими спутниками отправились в предгорья Хилсбрада. Нам пришлось отбиваться от навязчивых людей, поселившихся в тех краях, и в итоге мы оказались в городке, захваченном Отрекшимися, – Мельнице Таррен.$B$BИ удивительное дело – в центре города обнаружился маленький источник свежей родниковой воды. Не думаю, что пораженные чумой жители города осознают его ценность – это малый луч света в царстве тьмы.$B$BНабери воду из этого источника в этот бурдюк и принеси мне.','Наполните пустой красный бурдюк для воды в Мельнице Таррен и отнесите воду Брин в Степи.','Хорошо, $N. Ты изо всех сил стараешься выполнить порученные тебе задания и добиваешься успеха.$B$BЕще одна проба воды, и я смогу создать реактив, необходимый для сапты. Ислен будет довольна.','Источник, оставшийся чистым в центре такого города, напомнил мне о сказках, услышанных в детстве. Даже во времена великой боли и скорби остается место надежде, пусть самой малой. Тралл – последняя надежда орков. Он выжил, пройдя сквозь суровые испытания, и вывел наш народ из тьмы собственной силой и решимостью.$B$BНе думаю, чтобы на долю хотя бы одного орка выпало столько страданий, но в то же время ни одному орку не была дарована такая сила.','Вернитесь к Брин на Хребет Черных Шипов, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно мы с несколькими спутниками отправились в предгорья Хилсбрада. Нам пришлось отбиваться от навязчивых людей, поселившихся в тех краях, и в итоге мы оказались в городке, захваченном Отрекшимися, – Мельнице Таррен.$B$BИ удивительное дело – в центре города обнаружился маленький источник свежей родниковой воды. Не думаю, что пораженные чумой жители города осознают его ценность – это малый луч света в царстве тьмы.$B$BНабери воду из этого источника в этот бурдюк и принеси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните пустой красный бурдюк для воды в Мельнице Таррен и отнесите воду Брин в Степи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, $N. Ты изо всех сил стараешься выполнить порученные тебе задания и добиваешься успеха.$B$BЕще одна проба воды, и я смогу создать реактив, необходимый для сапты. Ислен будет довольна.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Источник, оставшийся чистым в центре такого города, напомнил мне о сказках, услышанных в детстве. Даже во времена великой боли и скорби остается место надежде, пусть самой малой. Тралл – последняя надежда орков. Он выжил, пройдя сквозь суровые испытания, и вывел наш народ из тьмы собственной силой и решимостью.$B$BНе думаю, чтобы на долю хотя бы одного орка выпало столько страданий, но в то же время ни одному орку не была дарована такая сила.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брин на Хребет Черных Шипов, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1537,'<NYI> Зов воздуха') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Зов воздуха',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1538,'*NYI* Зов воздуха') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','*NYI* Зов воздуха',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1558,'Каменная плотина','В Стальгорне живут все дворфы и гномы. Рядом есть местечко, которое зовется озером Лок Модан, и именно там дворфы отгрохали здоровенную дамбу. Говорят, это одна из самых больших построек в мире. Во как!$b$bПожалуйста, своди меня к озеру Лок Модан, посмотреть на дамбу! Как она называется? Кажется, Каминная дамба? Нет, камин – это что-то не то. В общем, она большая. И на огромный водопад хочется посмотреть. Обещаю, я не буду подходить к нему слишком близко!','Отведите сироту к Каменной плотине у озера Лок Модан. Пусть постоит в центре дамбы и полюбуется огромным водопадом.','Вау, плотина СИЛЬНО больше, чем я думал! Я почти не слышу себя за шумом падающей воды! Эй, как вы думаете - вода когда-нибудь закончится? Интересно, что бы произошло, если эта дамба когда-нибудь грохнется! Вау, это было бы страшно!$B$BСпасибо, что сводил меня к плотине. Это было очень любезно с твоей стороны. Я прошу только не наклоняться слишком далеко!','Разве мы уже там?','Сходить на Каменную плотину возле озера Лок Модан.','Поговорите со своим подопечным ребенком-сиротой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменная плотина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Стальгорне живут все дворфы и гномы. Рядом есть местечко, которое зовется озером Лок Модан, и именно там дворфы отгрохали здоровенную дамбу. Говорят, это одна из самых больших построек в мире. Во как!$b$bПожалуйста, своди меня к озеру Лок Модан, посмотреть на дамбу! Как она называется? Кажется, Каминная дамба? Нет, камин – это что-то не то. В общем, она большая. И на огромный водопад хочется посмотреть. Обещаю, я не буду подходить к нему слишком близко!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите сироту к Каменной плотине у озера Лок Модан. Пусть постоит в центре дамбы и полюбуется огромным водопадом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вау, плотина СИЛЬНО больше, чем я думал! Я почти не слышу себя за шумом падающей воды! Эй, как вы думаете - вода когда-нибудь закончится? Интересно, что бы произошло, если эта дамба когда-нибудь грохнется! Вау, это было бы страшно!$B$BСпасибо, что сводил меня к плотине. Это было очень любезно с твоей стороны. Я прошу только не наклоняться слишком далеко!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разве мы уже там?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сходить на Каменную плотину возле озера Лок Модан.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим подопечным ребенком-сиротой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1559,'Секрет изготовления световой бомбы','Так ты у нас инженер, да? Ну что ж, за то, что $Gнашел:нашла; для меня жемчужины, вот тебе секрет изготовления световых бомб.$B$BТы с ними только уж поосторожней, как бы $Gсамому:самой; не ослепнуть!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секрет изготовления световой бомбы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ты у нас инженер, да? Ну что ж, за то, что $Gнашел:нашла; для меня жемчужины, вот тебе секрет изготовления световых бомб.$B$BТы с ними только уж поосторожней, как бы $Gсамому:самой; не ослепнуть!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1560,'Задание Туги','Я заблудился!$b$BМоя жена, Торта, отправила меня за обедом, но я не туда свернул.$b$BОтведи меня обратно к Торте! Она ждет меня на юге от Порта Хитрой Шестеренки.','Сопроводите Тугу к его жене, Торте.','Отвести Тугу к Торте.','Вернитесь к Торте в Порт Хитрой Шестеренки, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание Туги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я заблудился!$b$BМоя жена, Торта, отправила меня за обедом, но я не туда свернул.$b$BОтведи меня обратно к Торте! Она ждет меня на юге от Порта Хитрой Шестеренки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите Тугу к его жене, Торте.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отвести Тугу к Торте.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торте в Порт Хитрой Шестеренки, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1578,'Помощь фронту','Горная пехота озера Лок Модан без передышки сражается с троггами! Им нужен постоянный подвоз новых доспехов и оружия, иначе с троггами не справиться.$B$BМой коллега Торвальд как раз и поехал туда – за тем чтобы у солдат было доброе снаряжение. Так что если бы вы могли изготовить несколько медных топоров и плетеных поясов и доставить их Торвальду, он был бы очень вам благодарен. Он даже может поделиться с вами своими знаниями.$B$BТорвальда вы найдете в южной сторожевой башне озера Лок Модан.','Отнесите 6 медных топоров и 6 медных плетеных поясов Торвальду в южную сторожевую башню озера Лок Модан.','Ох, прости! Я и не понял, что ты $Gпришел:пришла; помочь в деле вооружения наших войск. Изготовленные тобой вещи очень нам помогут!$B$BВот чертежи кое-каких доспехов. Надеюсь, они тебе пригодятся.','У меня нет времени на болтовню. Говори, какое у тебя ко мне дело?','Вернитесь к Торвальду Подземной Кузне к Северным вратам, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь фронту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Горная пехота озера Лок Модан без передышки сражается с троггами! Им нужен постоянный подвоз новых доспехов и оружия, иначе с троггами не справиться.$B$BМой коллега Торвальд как раз и поехал туда – за тем чтобы у солдат было доброе снаряжение. Так что если бы вы могли изготовить несколько медных топоров и плетеных поясов и доставить их Торвальду, он был бы очень вам благодарен. Он даже может поделиться с вами своими знаниями.$B$BТорвальда вы найдете в южной сторожевой башне озера Лок Модан.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 6 медных топоров и 6 медных плетеных поясов Торвальду в южную сторожевую башню озера Лок Модан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, прости! Я и не понял, что ты $Gпришел:пришла; помочь в деле вооружения наших войск. Изготовленные тобой вещи очень нам помогут!$B$BВот чертежи кое-каких доспехов. Надеюсь, они тебе пригодятся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня нет времени на болтовню. Говори, какое у тебя ко мне дело?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торвальду Подземной Кузне к Северным вратам, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1579,'Суперразъемы','Я прибыл в Аубердин в поисках тишины и покоя. Я хочу заниматься своими изобретениями там, где царит покой, потому что после ночных попоек мне совсем не нравится гомон Стальгорна!$B$BТак что я отправился на корабле в Аубердин... и по дороге слегка перебрал. Я уронил за борт мой ящик с суперразъемами!$B$BТочно не знаю, где я их потерял, но если ты попытаешься выловить их в океане, может, тебе повезет...','Принесите Бацбаху Кривошипу в Аубердин 8 суперразъемов.','Ах, не могу поверить, что тебе удалось их найти! Должно быть, ты $gсамый везучий:самая везучая:r; |3-6($r) на Калимдоре!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суперразъемы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прибыл в Аубердин в поисках тишины и покоя. Я хочу заниматься своими изобретениями там, где царит покой, потому что после ночных попоек мне совсем не нравится гомон Стальгорна!$B$BТак что я отправился на корабле в Аубердин... и по дороге слегка перебрал. Я уронил за борт мой ящик с суперразъемами!$B$BТочно не знаю, где я их потерял, но если ты попытаешься выловить их в океане, может, тебе повезет...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Бацбаху Кривошипу в Аубердин 8 суперразъемов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, не могу поверить, что тебе удалось их найти! Должно быть, ты $gсамый везучий:самая везучая:r; |3-6($r) на Калимдоре!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1580,'Электропеллеры','Мы знаем, что тебе везет, но... насколько сильно везет, $n?$B$BОднажды ночью я бродил по дорогам Темных берегов. Я искал речку или озеро, пригодные для испытания моей самодвижущейся и взрывающейся подсадной утки и, думаю, был слегка пьян... поскольку потерял сознание и пришел в себя в Аубердине спустя несколько часов. Мои волосы были опалены, а сумка с электропеллерами исчезла! Должно быть, я уронил ее в воду!$B$BМне нужны эти электропеллеры! Может быть, тебе удастся выловить их из какого-нибудь водоема на Темных берегах?..','Принесите 12 электропеллеров Бацбаху Кривошипу в Аубердин.','Ну как, нашел хоть один электропеллер? Они нужны мне, чтобы продолжить мои ислледования о подсадных утках...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Электропеллеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы знаем, что тебе везет, но... насколько сильно везет, $n?$B$BОднажды ночью я бродил по дорогам Темных берегов. Я искал речку или озеро, пригодные для испытания моей самодвижущейся и взрывающейся подсадной утки и, думаю, был слегка пьян... поскольку потерял сознание и пришел в себя в Аубердине спустя несколько часов. Мои волосы были опалены, а сумка с электропеллерами исчезла! Должно быть, я уронил ее в воду!$B$BМне нужны эти электропеллеры! Может быть, тебе удастся выловить их из какого-нибудь водоема на Темных берегах?..',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 электропеллеров Бацбаху Кривошипу в Аубердин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, нашел хоть один электропеллер? Они нужны мне, чтобы продолжить мои ислледования о подсадных утках...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1581,'Эликсиры для клана Режущего Листа','Наша лавочка трав и алхимических снадобий процветает, но мой муж проводит столько времени за изготовлением эликсиров, что почти забыл про личную жизнь!$B$BТы нам не поможешь?$B$BЕсли ты привезешь мне партию уже готовых эликсиров, я охотно куплю их у тебя. У меня есть некоторые редкие травы, которые могут оказаться полезными для тебя.','Доставьте 6 эликсиров львиной силы и 2 слабых эликсира защиты Сирел Остролист в Доланаар.','Вернитесь к Сирел Остролист в Тельдрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсиры для клана Режущего Листа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша лавочка трав и алхимических снадобий процветает, но мой муж проводит столько времени за изготовлением эликсиров, что почти забыл про личную жизнь!$B$BТы нам не поможешь?$B$BЕсли ты привезешь мне партию уже готовых эликсиров, я охотно куплю их у тебя. У меня есть некоторые редкие травы, которые могут оказаться полезными для тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте 6 эликсиров львиной силы и 2 слабых эликсира защиты Сирел Остролист в Доланаар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сирел Остролист в Тельдрассил.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1582,'Жилет лунного сияния','У нас, жителей Дарнаса, в особенности у ремесленников, работы невпроворот. Молодым искателям приключений неймется испытать себя во всякой глухомани, так что нам постоянно нужен подвоз материалов.$B$BЕсли ты поможешь мне выполнить заказ на кожаные изделия, я, может, научу тебя более совершенной технике работы с кожей.','Принесите 1 пару тисненых кожаных перчаток, 5 пар тисненых кожаных сапог и 5 тисненых кожаных плащей Лотериас в Дарнас.','Да, славные изделия. У тебя искусные руки и острый глаз. Из тебя может получиться неплохой кожевник.$B$BСлушай, $N. Давай-ка я покажу тебе выкройку жилета Лунного сияния.','Приветствую, $N.','Вернитесь к Лотериас в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жилет лунного сияния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас, жителей Дарнаса, в особенности у ремесленников, работы невпроворот. Молодым искателям приключений неймется испытать себя во всякой глухомани, так что нам постоянно нужен подвоз материалов.$B$BЕсли ты поможешь мне выполнить заказ на кожаные изделия, я, может, научу тебя более совершенной технике работы с кожей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 пару тисненых кожаных перчаток, 5 пар тисненых кожаных сапог и 5 тисненых кожаных плащей Лотериас в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, славные изделия. У тебя искусные руки и острый глаз. Из тебя может получиться неплохой кожевник.$B$BСлушай, $N. Давай-ка я покажу тебе выкройку жилета Лунного сияния.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лотериас в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1598,'Украденная книга','Ах, это ты! Тебя зовут $n, верно?$b$bНадеюсь, ты точно $gуверен:уверена;, что желаешь стать $Gчернокнижником:чернокнижницей;, поскольку если ты не умеешь постоять за себя, среди нас тебе делать нечего.$b$bЯ буду тебя обучать, но сначала я должна убедиться, что ты достаточно $gсилен:сильна;.$b$bВ здешнем аббатстве обучался один послушник, который сбежал и вступил в Братство Справедливости. Почему меня это волнует? А потому, что он стянул из аббатства кое-какие важные книги.$b$bОдну из них я сама хотела бы иметь. Братство прячет эту книгу – "Силы Бездны" – в своем шатре на виноградниках. Принеси ее мне.','Принесите книгу "Силы Бездны" Друзилле ла Салле.','Замечательно... Мне никогда не удавалось добраться до этой книги, его держали в охраняемом крыле библиотеки, и было бы подозрительно, если бы я стала рыскать вокруг.\n\nЛадно, ты отлично потрудилась, и я уверена, что ты сумеешь справиться со своим собственным бесом. Пора показать тебе, как его вызывать!','Было бы слишком опасно самой пытаться украсть эту книгу из аббатства. Какая удача, что этот простофиля сделал всю грязную работу за меня!','Вернитесь к Друзилле ла Салле в Долину Североземья, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Украденная книга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, это ты! Тебя зовут $n, верно?$b$bНадеюсь, ты точно $gуверен:уверена;, что желаешь стать $Gчернокнижником:чернокнижницей;, поскольку если ты не умеешь постоять за себя, среди нас тебе делать нечего.$b$bЯ буду тебя обучать, но сначала я должна убедиться, что ты достаточно $gсилен:сильна;.$b$bВ здешнем аббатстве обучался один послушник, который сбежал и вступил в Братство Справедливости. Почему меня это волнует? А потому, что он стянул из аббатства кое-какие важные книги.$b$bОдну из них я сама хотела бы иметь. Братство прячет эту книгу – "Силы Бездны" – в своем шатре на виноградниках. Принеси ее мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книгу "Силы Бездны" Друзилле ла Салле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно... Мне никогда не удавалось добраться до этой книги, его держали в охраняемом крыле библиотеки, и было бы подозрительно, если бы я стала рыскать вокруг.\n\nЛадно, ты отлично потрудилась, и я уверена, что ты сумеешь справиться со своим собственным бесом. Пора показать тебе, как его вызывать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Было бы слишком опасно самой пытаться украсть эту книгу из аббатства. Какая удача, что этот простофиля сделал всю грязную работу за меня!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Друзилле ла Салле в Долину Североземья, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1599,'В начале славных дел','Тут все шепчутся о каком-то новом чернокнижнике; наверное, это ты и есть. Должно быть, ты вызываешь кое у кого сильную симпатию, раз меня попросили отвлечься от моих изысканий и посвятить некоторое время занятиям с тобой.$b$bНе беспокойся: я не ставлю это тебе в вину.$b$bЧто ж, самое простое из заклинаний призыва позволяет вызвать беса. Но прежде чем я преподам тебе этот урок, мне хотелось бы получить доказательства того, что у тебя достаточно как физической, так и магической силы...$b$bПринеси мне три оберега из перьев. Ты получишь их, если расправишься с новобранцами племени Мерзлогривов в пещере, что к юго-западу отсюда.','Добудьте 3 оберега из перьев и отнесите их Аламару Мрачнну в Старую Наковальню.','Прекрасно, прекрасно! В самом деле, $N, неплохая работа. Возможно, те, кто тебя рекомендовал, и не ошиблись...$B$BВпрочем, это не мне решать. Поживем – увидим. Будем надеяться, что первый же вызванный бес не вырвет тебе сердце и не сожрет внутренности – думаю, подобное могло бы серьезно повредить твоей карьере. Пока у меня есть основания полагать, что в качестве чернокнижника ты сумеешь прожить хотя бы несколько месяцев.$B$BКстати, $N, хотел тебе дать тебе совет по поводу бесов. Запомни, размер – еще не главное: даже самый глупый таурен знает, что бесы наделены весьма сильной магией.','Обереги из перьев наделены своего рода магической силой. Было бы интересно провести соответствующие исследования... Да уж, троллям удалось меня удивить.','Вернитесь к Аламару Мрачнну в Туннель Холодной долины, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В начале славных дел',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тут все шепчутся о каком-то новом чернокнижнике; наверное, это ты и есть. Должно быть, ты вызываешь кое у кого сильную симпатию, раз меня попросили отвлечься от моих изысканий и посвятить некоторое время занятиям с тобой.$b$bНе беспокойся: я не ставлю это тебе в вину.$b$bЧто ж, самое простое из заклинаний призыва позволяет вызвать беса. Но прежде чем я преподам тебе этот урок, мне хотелось бы получить доказательства того, что у тебя достаточно как физической, так и магической силы...$b$bПринеси мне три оберега из перьев. Ты получишь их, если расправишься с новобранцами племени Мерзлогривов в пещере, что к юго-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 оберега из перьев и отнесите их Аламару Мрачнну в Старую Наковальню.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, прекрасно! В самом деле, $N, неплохая работа. Возможно, те, кто тебя рекомендовал, и не ошиблись...$B$BВпрочем, это не мне решать. Поживем – увидим. Будем надеяться, что первый же вызванный бес не вырвет тебе сердце и не сожрет внутренности – думаю, подобное могло бы серьезно повредить твоей карьере. Пока у меня есть основания полагать, что в качестве чернокнижника ты сумеешь прожить хотя бы несколько месяцев.$B$BКстати, $N, хотел тебе дать тебе совет по поводу бесов. Запомни, размер – еще не главное: даже самый глупый таурен знает, что бесы наделены весьма сильной магией.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обереги из перьев наделены своего рода магической силой. Было бы интересно провести соответствующие исследования... Да уж, троллям удалось меня удивить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аламару Мрачнну в Туннель Холодной долины, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1618,'Экипирование Красногорья','Не только мы, дворфы, сражаемся денно и нощно – люди, наши союзники, тоже не прохлаждаются!$B$BНа Красногорье время от времени устраивают налеты орки Черной горы, а снаряжения туда всегда мало поставляется. Если ты им поможешь, то местный кузнец Вернер Осгуд наверняка научит тебя паре хитростей.','По просьбе Тормуса Подземной Кузни отнесите 4 рунических медных пояса и 4 тяжелые медные кувалды Вернеру Осгуду в Красногорье.','Спасибо, $N. Это чрезвычайно мне поможет. Орки Черной Горы нападают со стороны крепости Каменной Стражи, а гноллы Красногорья шныряют в северных предгорьях, и мне постоянно приходится чинить доспехи и делать новое оружие для наших войск.$B$BТо, что ты $Gпринес:принесла, даст мне хоть небольшую передышку. И у меня будет время кое-чему тебя научить...','Надеюсь, ты $Gпринес:принесла; добрые вести из Стальгорна? Я уже не знаю, что мне делать!','Поговорите с Вернером Осгудом в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экипирование Красногорья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не только мы, дворфы, сражаемся денно и нощно – люди, наши союзники, тоже не прохлаждаются!$B$BНа Красногорье время от времени устраивают налеты орки Черной горы, а снаряжения туда всегда мало поставляется. Если ты им поможешь, то местный кузнец Вернер Осгуд наверняка научит тебя паре хитростей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Тормуса Подземной Кузни отнесите 4 рунических медных пояса и 4 тяжелые медные кувалды Вернеру Осгуду в Красногорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Это чрезвычайно мне поможет. Орки Черной Горы нападают со стороны крепости Каменной Стражи, а гноллы Красногорья шныряют в северных предгорьях, и мне постоянно приходится чинить доспехи и делать новое оружие для наших войск.$B$BТо, что ты $Gпринес:принесла, даст мне хоть небольшую передышку. И у меня будет время кое-чему тебя научить...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты $Gпринес:принесла; добрые вести из Стальгорна? Я уже не знаю, что мне делать!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Вернером Осгудом в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1638,'Обучение воина','Ты в самом деле неплохой воин, $n, но лет тебе мало, и еще многому придется научиться.$b$bПоговори с Гарри Берлгардом – обычно он сидит в "Свинье и Свистке", в Старом городе Штормграда. Гарри опытный боец и неплохой учитель. Он покажет тебе несколько приемов, глядишь, и подольше проживешь.','Поговорите с Гарри Берлгардом в Штормграде.','О-хо! Выпей со мной, $N. С первого взгляда ты кажешься $Gкрепким:крепкой;, посмотрим, что с тобой сделает несколько кружек крепкого пива!!!$B$BИли... А, да ты поучиться хочешь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение воина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты в самом деле неплохой воин, $n, но лет тебе мало, и еще многому придется научиться.$b$bПоговори с Гарри Берлгардом – обычно он сидит в "Свинье и Свистке", в Старом городе Штормграда. Гарри опытный боец и неплохой учитель. Он покажет тебе несколько приемов, глядишь, и подольше проживешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гарри Берлгардом в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О-хо! Выпей со мной, $N. С первого взгляда ты кажешься $Gкрепким:крепкой;, посмотрим, что с тобой сделает несколько кружек крепкого пива!!!$B$BИли... А, да ты поучиться хочешь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1639,'Бартлби Пьянь','Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься.$b$bВидишь, в конце бара стоит выпивка? Бартлби тоже видишь? Добудь эту кружку.$b$bХа, если ты $gзнаком:знакома; с ним, то догадаешься, что так просто он ее не отдаст.','Поговорите с Бартлби.','Эй, $Gкрасавчик:красавица;! Что таким как ты делать в "Свинье и свистке"? Осторожнее, неровен час, ноготь сломаешь...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бартлби Пьянь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься.$b$bВидишь, в конце бара стоит выпивка? Бартлби тоже видишь? Добудь эту кружку.$b$bХа, если ты $gзнаком:знакома; с ним, то догадаешься, что так просто он ее не отдаст.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бартлби.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эй, $Gкрасавчик:красавица;! Что таким как ты делать в "Свинье и свистке"? Осторожнее, неровен час, ноготь сломаешь...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1640,'Побить Бартлби','Что ты хочешь? Да ты $gспятил:спятила;!$b$bЭту кружку ты получишь только через мой труп...','Побейте Бартлби и снова поговорите с ним.','А ты крепче, чем кажешься с первого взгляда.','Эту кружку ты получишь только через мой труп...','Побить Бартлби','Поговорите с Бартлби в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побить Бартлби',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ты хочешь? Да ты $gспятил:спятила;!$b$bЭту кружку ты получишь только через мой труп...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Побейте Бартлби и снова поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А ты крепче, чем кажешься с первого взгляда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эту кружку ты получишь только через мой труп...',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Побить Бартлби',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Бартлби в Штормграде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1641,'Фолиант Божественности','Здесь, в Штормграде, я – наставник паладинов. Я – тот, кто ведет их стезей добродетели к Истинному Свету, дабы они защищали Азерот от нашествия нежити и иных бедствий.$B$BИ для тебя пришло время сделать первый шаг на пути праведности. Если ты решишься принять этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, чего от тебя ожидают. Постигнув мудрость, заключенную в этой книге, ты откроешь в себе новые, удивительные способности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здесь, в Штормграде, я – наставник паладинов. Я – тот, кто ведет их стезей добродетели к Истинному Свету, дабы они защищали Азерот от нашествия нежити и иных бедствий.$B$BИ для тебя пришло время сделать первый шаг на пути праведности. Если ты решишься принять этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, чего от тебя ожидают. Постигнув мудрость, заключенную в этой книге, ты откроешь в себе новые, удивительные способности.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1642,'Фолиант Божественности','Во всех своих деяниях паладин должен быть достоин того Света, которому мы служим и который дарует нам силу. Для таких, как мы, стремление к божественности не означает желания стать богами: мы лишь стремимся творить добро.$B$BНыне наступили тяжелые времена: мы избраны для того, чтобы сражаться со злом и повергнуть его. Однако помни: не борьба со злом отличает нас от прочих жителей Азерота. Сострадание, терпение, отвага и помощь ближним – для паладина все это значит не меньше, чем искусство воина.$B$BНикогда не забывай об этом!','Найдите в Штормграде Даториана Ралла и поговорите с ним.','И снова рад приветствовать тебя, $N. Как идет изучение Фолианта Божественности?$B$BПомни: тебе предстоит пройти испытание. Каждого из нас ждет множество свершений – как в городе, так и в иных землях. Всегда есть люди, нуждающиеся в помощи, сострадании и понимании, всегда есть враждебные твари, которых необходимо уничтожать во благо людей.$B$BДокажи, что ты можешь помогать своим ближним – в особенности тем, кому меньше повезло в жизни. Тем самым ты докажешь, что твои помыслы чисты и что ты воистину служишь Свету.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во всех своих деяниях паладин должен быть достоин того Света, которому мы служим и который дарует нам силу. Для таких, как мы, стремление к божественности не означает желания стать богами: мы лишь стремимся творить добро.$B$BНыне наступили тяжелые времена: мы избраны для того, чтобы сражаться со злом и повергнуть его. Однако помни: не борьба со злом отличает нас от прочих жителей Азерота. Сострадание, терпение, отвага и помощь ближним – для паладина все это значит не меньше, чем искусство воина.$B$BНикогда не забывай об этом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Штормграде Даториана Ралла и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И снова рад приветствовать тебя, $N. Как идет изучение Фолианта Божественности?$B$BПомни: тебе предстоит пройти испытание. Каждого из нас ждет множество свершений – как в городе, так и в иных землях. Всегда есть люди, нуждающиеся в помощи, сострадании и понимании, всегда есть враждебные твари, которых необходимо уничтожать во благо людей.$B$BДокажи, что ты можешь помогать своим ближним – в особенности тем, кому меньше повезло в жизни. Тем самым ты докажешь, что твои помыслы чисты и что ты воистину служишь Свету.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1643,'Фолиант Божественности','Итак, $n, твоя задача – найти в Штормграде того, кто нуждается в помощи. Того, кто чист сердцем и помыслами. Возможно, это тот, кто сам помогает другим. Возможно – тот, кто нуждается в наставнике. Как бы то ни было, намерения того, кого ты ищешь, будут благородны, и он во всем будет полагаться на тебя.$B$BТы возвратишься ко мне, когда исполнишь это задание, и мы поговорим о твоем пути – а равно и о том, что значит быть паладином Света.','Обыщите Торговый квартал и найдите Стефани Тернер.','О, привет, $Gдорогой:милашка;. Что, все ищешь приключений? Я так рада, что у тебя все в порядке!$B$BЯ? А что я? Ну, с учетом обстоятельств, у меня тоже дела идут неплохо...$B$BПравда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать? Но ничего, мы справимся. Под "нами" я имею в виду себя и своего мужа, конечно. Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, $n, твоя задача – найти в Штормграде того, кто нуждается в помощи. Того, кто чист сердцем и помыслами. Возможно, это тот, кто сам помогает другим. Возможно – тот, кто нуждается в наставнике. Как бы то ни было, намерения того, кого ты ищешь, будут благородны, и он во всем будет полагаться на тебя.$B$BТы возвратишься ко мне, когда исполнишь это задание, и мы поговорим о твоем пути – а равно и о том, что значит быть паладином Света.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите Торговый квартал и найдите Стефани Тернер.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, привет, $Gдорогой:милашка;. Что, все ищешь приключений? Я так рада, что у тебя все в порядке!$B$BЯ? А что я? Ну, с учетом обстоятельств, у меня тоже дела идут неплохо...$B$BПравда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать? Но ничего, мы справимся. Под "нами" я имею в виду себя и своего мужа, конечно. Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1644,'Фолиант Божественности','Да будут благословенны эти несчастные! Многие из них потеряли родных во время набегов нежити...$B$BМой муж Джон помогает мне доставать ткань, чтобы я могла шить сироткам одежду, но увы, на это у меня не хватает времени, ведь их нужно сначала накормить и дать им кров.$B$BЧто? Правда? Ты хочешь мне помочь? Благодарение Вечному Свету! Благодарю тебя, $n!$B$BЕсли бы у меня был лен на одежки малышам, их жизнь стала бы хоть немного легче...','Принесите 10 отрезов льна в Штормград и отдайте Стефани Тернер.','Ах, $N, благодарю, благодарю тебя!$B$BДетишки так рады будут, да и у меня будет побольше времени на них. Надеюсь, теперь Джон сможет возвратиться поскорее.$B$BПрими мою искреннюю признательность, $N. Я всегда верила, что в сердцах людей есть место милосердию. Да пребудет с тобой Извечный Свет.','Надеюсь, моему Джону в Стальгорне повезет. Он терпеть не может дальние поездки – ведь ему приходится оставлять меня одну с детьми, – но знает, что это необходимо. У Джона такое доброе сердце...$B$BИногда нам бывает и полегче, но этот год поистине выдался самым тяжелым на моей памяти. Возможно, это знак того, что в мире что-то меняется, кто знает?..','Вернитесь к Стефани Тернер в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да будут благословенны эти несчастные! Многие из них потеряли родных во время набегов нежити...$B$BМой муж Джон помогает мне доставать ткань, чтобы я могла шить сироткам одежду, но увы, на это у меня не хватает времени, ведь их нужно сначала накормить и дать им кров.$B$BЧто? Правда? Ты хочешь мне помочь? Благодарение Вечному Свету! Благодарю тебя, $n!$B$BЕсли бы у меня был лен на одежки малышам, их жизнь стала бы хоть немного легче...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 отрезов льна в Штормград и отдайте Стефани Тернер.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, $N, благодарю, благодарю тебя!$B$BДетишки так рады будут, да и у меня будет побольше времени на них. Надеюсь, теперь Джон сможет возвратиться поскорее.$B$BПрими мою искреннюю признательность, $N. Я всегда верила, что в сердцах людей есть место милосердию. Да пребудет с тобой Извечный Свет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, моему Джону в Стальгорне повезет. Он терпеть не может дальние поездки – ведь ему приходится оставлять меня одну с детьми, – но знает, что это необходимо. У Джона такое доброе сердце...$B$BИногда нам бывает и полегче, но этот год поистине выдался самым тяжелым на моей памяти. Возможно, это знак того, что в мире что-то меняется, кто знает?..',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стефани Тернер в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1645,'Фолиант Божественности','Приятно встретить тебя, $N. Я направляю паладинов на путь высших добродетелей, когда они посвящают себя Свету и защите Азерота от Плети и прочих бед.$B$BПришла пора сделать первый шаг по пути истинных добродетелей. Если ты принимаешь этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, что тебя ждет. Если ты это поймешь и окажешься способным $Gучеником:ученицей;, то откроешь путь к великим возможностям.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно встретить тебя, $N. Я направляю паладинов на путь высших добродетелей, когда они посвящают себя Свету и защите Азерота от Плети и прочих бед.$B$BПришла пора сделать первый шаг по пути истинных добродетелей. Если ты принимаешь этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, что тебя ждет. Если ты это поймешь и окажешься способным $Gучеником:ученицей;, то откроешь путь к великим возможностям.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1646,'Фолиант Божественности','Паладин во всех делах своих должен быть проявлением Света, который есть источник нашей силы. Стремление к божественности для нас не означает стремления стать божеством – мы стремимся к добру во всех деяниях наших.$B$BХотя в эти тяжелые времена мы призваны сокрушать зло, тебе всегда следует помнить: лишь помогая другим, ты выделяешься среди других обитателей Азерота. Сочувствие, терпение, отвага – все эти достоинства значат для паладина не меньше, чем сила в сражении.$B$BУсвой же это и помни всегда.','Поговорите с Тизой Боевой Горн в Стальгорне.','С возвращением, $N. Надеюсь, ты $Gнашел:нашла; время на прочтение книги?$B$BТогда ты $Gдолжен:должна; быть $Gготов:готова; к испытанию. Есть задания, которые необходимо сделать по всему нашему городу и на наших землях; акты сострадания и понимания; люди, которые нуждаются в помощи; существа, которых необходимо убить.$B$BДоказав что у тебя есть терпение, особенно в помощи людям, которые менее удачливы, ты докажешь, что ты слуга Света.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Паладин во всех делах своих должен быть проявлением Света, который есть источник нашей силы. Стремление к божественности для нас не означает стремления стать божеством – мы стремимся к добру во всех деяниях наших.$B$BХотя в эти тяжелые времена мы призваны сокрушать зло, тебе всегда следует помнить: лишь помогая другим, ты выделяешься среди других обитателей Азерота. Сочувствие, терпение, отвага – все эти достоинства значат для паладина не меньше, чем сила в сражении.$B$BУсвой же это и помни всегда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тизой Боевой Горн в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С возвращением, $N. Надеюсь, ты $Gнашел:нашла; время на прочтение книги?$B$BТогда ты $Gдолжен:должна; быть $Gготов:готова; к испытанию. Есть задания, которые необходимо сделать по всему нашему городу и на наших землях; акты сострадания и понимания; люди, которые нуждаются в помощи; существа, которых необходимо убить.$B$BДоказав что у тебя есть терпение, особенно в помощи людям, которые менее удачливы, ты докажешь, что ты слуга Света.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1647,'Фолиант Божественности','Твоя задача, $n, найти в Стальгорне кого-нибудь, кто нуждается в помощи. Того, кто чист душой и помыслами. Может быть, того, кто сам помогает другим. Того, кто нуждается в совете. Кто бы то ни был, у него должны быть благородные стремления и он должен полагаться на твою доброту.$B$BСделай это и по выполнении возвращайся ко мне. Тогда мы еще поговорим о твоем пути и о том, что значит быть паладином Света. Я останусь в храме до твоего возвращения. Мое наставничество нужно и другим паладинам.','Найдите во внешнем кольце Стальгорна Джона Тернера.','СИРОТСКИЙ ПРИЮТ ШТОРМ... о, простите, я вовсе не хотел кричать на вас, сударь.$B$BМеня зовут Джон Тернер. Как поживаете?$B$BРад, искренне рад слышать, что у вас все хорошо. А у меня был трудный день, я тоскую по жене, но такова цена, которую приходится платить, чтобы накормить голодные рты и одеть нагих.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя задача, $n, найти в Стальгорне кого-нибудь, кто нуждается в помощи. Того, кто чист душой и помыслами. Может быть, того, кто сам помогает другим. Того, кто нуждается в совете. Кто бы то ни был, у него должны быть благородные стремления и он должен полагаться на твою доброту.$B$BСделай это и по выполнении возвращайся ко мне. Тогда мы еще поговорим о твоем пути и о том, что значит быть паладином Света. Я останусь в храме до твоего возвращения. Мое наставничество нужно и другим паладинам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите во внешнем кольце Стальгорна Джона Тернера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','СИРОТСКИЙ ПРИЮТ ШТОРМ... о, простите, я вовсе не хотел кричать на вас, сударь.$B$BМеня зовут Джон Тернер. Как поживаете?$B$BРад, искренне рад слышать, что у вас все хорошо. А у меня был трудный день, я тоскую по жене, но такова цена, которую приходится платить, чтобы накормить голодные рты и одеть нагих.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1648,'Фолиант Божественности','Мы с женой держим в Штормграде сиротский приют, по большей части для детей, потерявших родителей во время нападений Плети в последние десять лет. Я приезжаю в Стальгорн примерно раз в месяц и занимаюсь сбором средств у здешних горожан, а также прошу помощи у различных организаций.$B$BНынешняя поездка была мучительно медленной и не слишком продуктивной.$B$BЕсли бы мне удалось добыть еще немного льняной ткани для одежды, я бы смог, наконец, отправить посылку домой.','Принесите 10 отрезов льняной ткани Джону Тернеру в Стальгорн.','Это так прекрасно с вашей стороны, $N. Снова большое вам спасибо.$B$BВы благородный человек, что так помогли мне. Не удивительно, что вы избрали путь Света. Хотел бы я, чтобы был какой-либо способ отплатить вам за все, что вы сделали... что? Это наименьшее что вы могли сделать? Видите? Это как раз то, о чем я говорю, $N, вы благородны до самого конца.$B$BБерегите себя, и да охранит вас Свет в ваших путешествиях.','Из-за притока торговцев здесь и по всему Азероту стало меньше товаров, которые мы используем для изготовления одежды для детей нашего приюта. Помогать мне собирать белье, чтобы моя жена могла сшить для них новую одежду, очень благородно с твоей стороны, $N. Спасибо.$B$BНадеюсь, скоро смогу вернуться домой к жене.','Вернитесь к Джону Тернеру в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с женой держим в Штормграде сиротский приют, по большей части для детей, потерявших родителей во время нападений Плети в последние десять лет. Я приезжаю в Стальгорн примерно раз в месяц и занимаюсь сбором средств у здешних горожан, а также прошу помощи у различных организаций.$B$BНынешняя поездка была мучительно медленной и не слишком продуктивной.$B$BЕсли бы мне удалось добыть еще немного льняной ткани для одежды, я бы смог, наконец, отправить посылку домой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 отрезов льняной ткани Джону Тернеру в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это так прекрасно с вашей стороны, $N. Снова большое вам спасибо.$B$BВы благородный человек, что так помогли мне. Не удивительно, что вы избрали путь Света. Хотел бы я, чтобы был какой-либо способ отплатить вам за все, что вы сделали... что? Это наименьшее что вы могли сделать? Видите? Это как раз то, о чем я говорю, $N, вы благородны до самого конца.$B$BБерегите себя, и да охранит вас Свет в ваших путешествиях.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Из-за притока торговцев здесь и по всему Азероту стало меньше товаров, которые мы используем для изготовления одежды для детей нашего приюта. Помогать мне собирать белье, чтобы моя жена могла сшить для них новую одежду, очень благородно с твоей стороны, $N. Спасибо.$B$BНадеюсь, скоро смогу вернуться домой к жене.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джону Тернеру в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1649,'Отвага и сопутствующие ей достоинства подобны драгоценным металлам. Нужно беречь их, когда находишь, ибо цена их велика, но также необходимо копить и приумножать их. Тогда они образуют крепчайший сплав, зачастую выдерживающий даже самые сильные удары.$b$bТвои сила, вера и храбрость должны быть испытаны. Тебе надлежит научиться хранить веру в любых обстоятельствах и понять, что с помощью сил Света ты сможешь преодолеть те препятствия, которые не по силам другим.','Поговорите с Даторианом Раллом в Штормграде.','Ты просишь испытать твою отвагу? Прекрасно!$B$BДля тебя в городе и в окрестностях найдется немало заданий. Нам как раз нужен кто-нибудь с твоими способностями.$B$BЭто испытание не будет легким, $n! Оно, как и многое в нашей профессии, может привести к гибели. Церковь всегда готова поддержать своих слуг, но без жертв невозможно определить, достоин ли $c служить правому делу.$B$BЧувствуешь ли ты в себе готовность к испытанию?') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отвага и сопутствующие ей достоинства подобны драгоценным металлам. Нужно беречь их, когда находишь, ибо цена их велика, но также необходимо копить и приумножать их. Тогда они образуют крепчайший сплав, зачастую выдерживающий даже самые сильные удары.$b$bТвои сила, вера и храбрость должны быть испытаны. Тебе надлежит научиться хранить веру в любых обстоятельствах и понять, что с помощью сил Света ты сможешь преодолеть те препятствия, которые не по силам другим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Даторианом Раллом в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты просишь испытать твою отвагу? Прекрасно!$B$BДля тебя в городе и в окрестностях найдется немало заданий. Нам как раз нужен кто-нибудь с твоими способностями.$B$BЭто испытание не будет легким, $n! Оно, как и многое в нашей профессии, может привести к гибели. Церковь всегда готова поддержать своих слуг, но без жертв невозможно определить, достоин ли $c служить правому делу.$B$BЧувствуешь ли ты в себе готовность к испытанию?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1650,'Отлично! Отсутствие сомнений говорит о твоей готовности к испытаниям. Да будет так!$b$bВ самом конце Долгого Берега стоит небольшой домик с окнами на океан. Там живет чета Стилвеллов. Джордан – великолепный кузнец, и сейчас он собирается в Стальгорн, чтобы навестить дворфов. Но его жена Дафна остается дома одна, без защиты...$B$bДонесения говорят, что Братство Справедливости захватило почти весь край. Дафне может понадобиться защита от злодеев. Отправляйся туда.','Найдите Дафну Стилвелл в Западном Крае.','Здравствуй, $n. Я полагаю, что со всем этим оружием в руках ты хочешь либо захватить мои земли, либо Церковь наконец-то послала мне защитника на время поездки Джордана.$B$BПозволь представиться: я – Дафна Стилвелл. Очень приятно!$B$BТвое прибытие очень кстати: с восхода солнца я уже прикончила с полдюжины этих мерзавцев. До этого они не особо торопились, но сейчас они наверняка заметили тебя, а значит, будут здесь с минуты на минуту...') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично! Отсутствие сомнений говорит о твоей готовности к испытаниям. Да будет так!$b$bВ самом конце Долгого Берега стоит небольшой домик с окнами на океан. Там живет чета Стилвеллов. Джордан – великолепный кузнец, и сейчас он собирается в Стальгорн, чтобы навестить дворфов. Но его жена Дафна остается дома одна, без защиты...$B$bДонесения говорят, что Братство Справедливости захватило почти весь край. Дафне может понадобиться защита от злодеев. Отправляйся туда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Дафну Стилвелл в Западном Крае.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуй, $n. Я полагаю, что со всем этим оружием в руках ты хочешь либо захватить мои земли, либо Церковь наконец-то послала мне защитника на время поездки Джордана.$B$BПозволь представиться: я – Дафна Стилвелл. Очень приятно!$B$BТвое прибытие очень кстати: с восхода солнца я уже прикончила с полдюжины этих мерзавцев. До этого они не особо торопились, но сейчас они наверняка заметили тебя, а значит, будут здесь с минуты на минуту...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1651,'Бьюсь об заклад, они скоро вернутся – так что приготовься.$b$bВ доме есть пистолет, я возьму его и при необходимости помогу тебе, но лучше рассчитывай только на свои силы.$b$bНе знаю, сколько их будет, но уверена, что больше, чем в прошлый раз.$b$bМоли Свет благословить тебя, потому что... Слышишь? Они идут!$b$bУкроемся за домом!','Защитите Дафну Стилвелл от нападения Братства Справедливости. Проследите, чтобы ни ее, ни ваша душа в случае смерти не покинули свои тела, иначе испытание не будет засчитано.$b$BПосле победы поговорите с Дафной Стилвелл.','$N, мы победили! Благодарю тебя за помощь. Это было просто великолепно! Я и не думала, что $c может справиться с таким количеством врагов зараз.$B$BТвоя выдающаяся храбрость перед лицом превосходящих сил потрясла меня...','Защитите Дафну Стилвелл.','Вернитесь к Дафне Стилвелл в Западный Край.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бьюсь об заклад, они скоро вернутся – так что приготовься.$b$bВ доме есть пистолет, я возьму его и при необходимости помогу тебе, но лучше рассчитывай только на свои силы.$b$bНе знаю, сколько их будет, но уверена, что больше, чем в прошлый раз.$b$bМоли Свет благословить тебя, потому что... Слышишь? Они идут!$b$bУкроемся за домом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите Дафну Стилвелл от нападения Братства Справедливости. Проследите, чтобы ни ее, ни ваша душа в случае смерти не покинули свои тела, иначе испытание не будет засчитано.$b$BПосле победы поговорите с Дафной Стилвелл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, мы победили! Благодарю тебя за помощь. Это было просто великолепно! Я и не думала, что $c может справиться с таким количеством врагов зараз.$B$BТвоя выдающаяся храбрость перед лицом превосходящих сил потрясла меня...',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите Дафну Стилвелл.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дафне Стилвелл в Западный Край.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1652,'Прошу, возвращайся к Даториану и передай ему, что теперь со мной все в порядке – благодаря тебе и Церкви.$b$bОн пошлет весть в Стальгорн, чтобы мой Джордан не волновался за меня.$b$bОх, как я соскучилась по своему мужу! Жду не дождусь его возвращения...','Поговорите с Даторианом Раллом в Штормграде.','Вот мы и встретились снова. Я вижу, что дух твой бодр. Дом четы Стивеллов теперь в безопасности, а из твоего рассказа ясно, что ему теперь еще долго ничего не будет угрожать. Отлично!$B$BДафна и Джордан немало помогли Церкви. Отправить тебя на их защиту – весьма скромная ответная услуга.$B$BТы получишь награду за проявленную отвагу.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу, возвращайся к Даториану и передай ему, что теперь со мной все в порядке – благодаря тебе и Церкви.$b$bОн пошлет весть в Стальгорн, чтобы мой Джордан не волновался за меня.$b$bОх, как я соскучилась по своему мужу! Жду не дождусь его возвращения...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Даторианом Раллом в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот мы и встретились снова. Я вижу, что дух твой бодр. Дом четы Стивеллов теперь в безопасности, а из твоего рассказа ясно, что ему теперь еще долго ничего не будет угрожать. Отлично!$B$BДафна и Джордан немало помогли Церкви. Отправить тебя на их защиту – весьма скромная ответная услуга.$B$BТы получишь награду за проявленную отвагу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1653,'Испытание доблести','Вообще я не сомневаюсь, что Джордан захочет лично отблагодарить тебя, и раз уж мне надо сообщить ему, что его жена в безопасности, то, думаю, лучше всего тебя посланником и отправить.$B$BДжордан был паладином Света, до того как приверженность отцовскому ремеслу увлекла его на другой путь, – а потому он хорошо знает наш образ жизни и считается одним из самых надежных наших приверженцев.$B$BОн должен еще быть в Стальгорне – он любит работать днем за воротами, там где с гор тянет холодным воздухом.','Поговорите с Джорданом Стилвеллом в Стальгорне.','Добрый день, $n. Вижу, ты служишь Свету?$B$BЧто это? Тебя послал Даториан?! Моя жена, как она? Я так и знал – стоит уехать, сразу беды нагрянут. Скажи мне, она... о, хвала Свету. Я так счастлив, что она в безопасности. Это Братство Справедливости было опасным еще до нынешних своих налетов, но теперь уж королевские советники не смогут этой угрозы отрицать.$B$BЧто еще велел передать Даториан?$B$BИменно ты и назначен был оберегать мою жену? Тогда еще раз прими мою благодарность, $n. Не могу придумать лучшего испытания доблести, чем это.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание доблести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вообще я не сомневаюсь, что Джордан захочет лично отблагодарить тебя, и раз уж мне надо сообщить ему, что его жена в безопасности, то, думаю, лучше всего тебя посланником и отправить.$B$BДжордан был паладином Света, до того как приверженность отцовскому ремеслу увлекла его на другой путь, – а потому он хорошо знает наш образ жизни и считается одним из самых надежных наших приверженцев.$B$BОн должен еще быть в Стальгорне – он любит работать днем за воротами, там где с гор тянет холодным воздухом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джорданом Стилвеллом в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добрый день, $n. Вижу, ты служишь Свету?$B$BЧто это? Тебя послал Даториан?! Моя жена, как она? Я так и знал – стоит уехать, сразу беды нагрянут. Скажи мне, она... о, хвала Свету. Я так счастлив, что она в безопасности. Это Братство Справедливости было опасным еще до нынешних своих налетов, но теперь уж королевские советники не смогут этой угрозы отрицать.$B$BЧто еще велел передать Даториан?$B$BИменно ты и назначен был оберегать мою жену? Тогда еще раз прими мою благодарность, $n. Не могу придумать лучшего испытания доблести, чем это.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1654,'Испытание доблести','Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар. Пойми меня правильно, все будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода.$B$BЯ скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света. Но тебе придется добыть необходимые для ковки предметы. Я уже набросал список, так что остается только, чтобы некто отважный и искусный принес их мне. Что скажешь, |3-6($c)?','Возьмите список Джордана, добудьте немного древесины белокаменного дуба, партию очищенной руды Бэйлора, кузнечный молот Джордана и самоцвет Кора и отдайте их Джордану Стилвеллу в Стальгорне.','Предметы эти нелегко добыть, но, смею тебя заверить, оружие, которое я для тебя сделаю, сторицей окупит твои труды.$B$BЭто будет лучшая моя работа и лишь малая награда за все, что ты сделал для меня.','Вернитесь к Джордану Стилвеллу ко Вратам Стальгорна, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание доблести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар. Пойми меня правильно, все будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода.$B$BЯ скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света. Но тебе придется добыть необходимые для ковки предметы. Я уже набросал список, так что остается только, чтобы некто отважный и искусный принес их мне. Что скажешь, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите список Джордана, добудьте немного древесины белокаменного дуба, партию очищенной руды Бэйлора, кузнечный молот Джордана и самоцвет Кора и отдайте их Джордану Стилвеллу в Стальгорне.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Предметы эти нелегко добыть, но, смею тебя заверить, оружие, которое я для тебя сделаю, сторицей окупит твои труды.$B$BЭто будет лучшая моя работа и лишь малая награда за все, что ты сделал для меня.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джордану Стилвеллу ко Вратам Стальгорна, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1655,'Партия руды Балора','Доставьте партию руды для Джордана Балору Крепкоруку к озеру Лок Модан.','Ну-ну, надо же! Знал бы я, что ты и правда прямо туда и пойдешь и навтыкаешь этим ограм, я бы дал тебе целый список, что оттуда принести. Но ведь ты тут не за тем, чтобы за меня работу делать, верно?$B$BА сделка есть сделка. Джордан хотел получить свою руду, и он ее получит.$B$BПередай ему приветик от меня, и доброй тебе дороги, $C.','Ну, что, удалось? Огры получили от тебя по полной, да?','Вернитесь к Балору Крепкоруку в Лок Модан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Партия руды Балора',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте партию руды для Джордана Балору Крепкоруку к озеру Лок Модан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну-ну, надо же! Знал бы я, что ты и правда прямо туда и пойдешь и навтыкаешь этим ограм, я бы дал тебе целый список, что оттуда принести. Но ведь ты тут не за тем, чтобы за меня работу делать, верно?$B$BА сделка есть сделка. Джордан хотел получить свою руду, и он ее получит.$B$BПередай ему приветик от меня, и доброй тебе дороги, $C.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что, удалось? Огры получили от тебя по полной, да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Балору Крепкоруку в Лок Модан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1656,'Незаконченное задание','$n, умоляю, помоги мне! У меня еще есть дело здесь, на плато – я прохожу обряд Силы, – а мой отец требует, чтобы я срочно доставила эти меха в таверну в деревне Кровавого Копыта! $B$BКак же мне выполнить сразу обе задачи – завершить ритуал и отнести меха?! Не отнесешь ли ты их вместо меня?$B$BТаверна – такое милое и уютное местечко, там есть все, чего может пожелать притомившийся путник. Даю слово, тебе понравится!','Отнесите сверток мехов хозяину таверны Кауту в деревню Кровавого Копыта.','Ah, the furs I was expecting. Thank you.$B$BThese came faster than I had expected. They will make good blankets for anyone who wishes to stay here.$B$BPlease feel free to stay as long as you like. My inn is always open and all of our people are welcome here. And don\'t underestimate a good night\'s rest, it can make a great difference while you\'re out traveling.','Yes, young one? What can Kauth do for you?$B$BThe journey here from the Mesa can be a tremendous burden for some, but a welcome sight for others. Which is it for you, I wonder?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Незаконченное задание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, умоляю, помоги мне! У меня еще есть дело здесь, на плато – я прохожу обряд Силы, – а мой отец требует, чтобы я срочно доставила эти меха в таверну в деревне Кровавого Копыта! $B$BКак же мне выполнить сразу обе задачи – завершить ритуал и отнести меха?! Не отнесешь ли ты их вместо меня?$B$BТаверна – такое милое и уютное местечко, там есть все, чего может пожелать притомившийся путник. Даю слово, тебе понравится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сверток мехов хозяину таверны Кауту в деревню Кровавого Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ah, the furs I was expecting. Thank you.$B$BThese came faster than I had expected. They will make good blankets for anyone who wishes to stay here.$B$BPlease feel free to stay as long as you like. My inn is always open and all of our people are welcome here. And don\'t underestimate a good night\'s rest, it can make a great difference while you\'re out traveling.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Yes, young one? What can Kauth do for you?$B$BThe journey here from the Mesa can be a tremendous burden for some, but a welcome sight for others. Which is it for you, I wonder?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1657,'Подпортим воздух в Южнобережье','Сделайте ваш праздник Тыквовина незабываемым... насолив нашим врагам на Южнобережье!$B$BВозьмите специально собранную бомбу-вонючку – она наполнена невероятно зловонным веществом, запах которого не вынесет ни одно тупое животное, включая людей. Вам нужно будет бросить ее в самый центр Южнобережья, так что готовьтесь к драке с Альянсом!$B$BА когда сделаете этот шаг к нашему освобождению, возвращайтесь ко мне!','Бросьте три бомбы-вонючки Отрекшихся в центр Южнобережья в Хилсбраде и вернитесь к зовущей Тьму Янке на фестиваль Плетеного человека в Тирисфальских лесах.','О, отличная работа! Надеюсь, Альянс задохнётся от нашего подарочка, как мы задыхались от гнёта Плети!$B$BТы правильно $Gуловил:уловила; идею Тыквовина, $N, и за это я благодарю тебя. В добавок, позволь поделиться с тобой некоторыми угощениями Тыквовина. Думаю, ты найдёшь их просто потрясающими!','Вы доставили наш «подарок» народу Южнобережья?$B$B<Призыватель тьмы Янка злобно смеется.>','Вернитесь к зовущей Тьму Янке на Руины Лордерона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подпортим воздух в Южнобережье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сделайте ваш праздник Тыквовина незабываемым... насолив нашим врагам на Южнобережье!$B$BВозьмите специально собранную бомбу-вонючку – она наполнена невероятно зловонным веществом, запах которого не вынесет ни одно тупое животное, включая людей. Вам нужно будет бросить ее в самый центр Южнобережья, так что готовьтесь к драке с Альянсом!$B$BА когда сделаете этот шаг к нашему освобождению, возвращайтесь ко мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте три бомбы-вонючки Отрекшихся в центр Южнобережья в Хилсбраде и вернитесь к зовущей Тьму Янке на фестиваль Плетеного человека в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, отличная работа! Надеюсь, Альянс задохнётся от нашего подарочка, как мы задыхались от гнёта Плети!$B$BТы правильно $Gуловил:уловила; идею Тыквовина, $N, и за это я благодарю тебя. В добавок, позволь поделиться с тобой некоторыми угощениями Тыквовина. Думаю, ты найдёшь их просто потрясающими!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы доставили наш «подарок» народу Южнобережья?$B$B<Призыватель тьмы Янка злобно смеется.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к зовущей Тьму Янке на Руины Лордерона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1658,'Испортить праздник Плетеного человека','Мне нужны храбрецы, готовые отправиться в Тирисфальские леса на фестиваль Плетеного человека. Не скрою, это очень опасно. Стража на фестивале будет особенно бдительна и свирепа. И все же надо выяснить, велик ли в этом году фестиваль, и сколько бед Отрекшиеся причинят нам во время Тыквовина.$b$bЕсли тебе хватит пороху, ступай в Тирисфаль и разведай, что да как. Я прослежу, чтобы тебе хорошо заплатили за принесенную информацию.','Отыщите место проведения фестиваля Плетеного человека в Тирисфальских лесах и возвращайтесь в Южнобережье к сержанту Дыгалу.','Молодец, $n. Фестиваль Плетеного Человечка будет источником неприятностей, пока в руинах Лордерона живут омерзительные Отрекшиеся. Не им бы жить на развалинах некогда гордого королевства, вот что я скажу…$B$BВот, возьми несколько монет, тебе ведь придется чинить доспехи. Ну и в честь праздника угощайся, чем хочешь. Счастливого Тыквовина, пусть он пройдет в Южнобережье как можно спокойнее.','Разведайте, что происходит на фестивале Плетеного человека','Вернитесь к сержанту Дыгалу в Предгорья Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испортить праздник Плетеного человека',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужны храбрецы, готовые отправиться в Тирисфальские леса на фестиваль Плетеного человека. Не скрою, это очень опасно. Стража на фестивале будет особенно бдительна и свирепа. И все же надо выяснить, велик ли в этом году фестиваль, и сколько бед Отрекшиеся причинят нам во время Тыквовина.$b$bЕсли тебе хватит пороху, ступай в Тирисфаль и разведай, что да как. Я прослежу, чтобы тебе хорошо заплатили за принесенную информацию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите место проведения фестиваля Плетеного человека в Тирисфальских лесах и возвращайтесь в Южнобережье к сержанту Дыгалу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $n. Фестиваль Плетеного Человечка будет источником неприятностей, пока в руинах Лордерона живут омерзительные Отрекшиеся. Не им бы жить на развалинах некогда гордого королевства, вот что я скажу…$B$BВот, возьми несколько монет, тебе ведь придется чинить доспехи. Ну и в честь праздника угощайся, чем хочешь. Счастливого Тыквовина, пусть он пройдет в Южнобережье как можно спокойнее.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Разведайте, что происходит на фестивале Плетеного человека',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Дыгалу в Предгорья Хилсбрада.',`completedtext_loc8`);
