INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1661,'Фолиант благородства','Приветствую тебя, $n! Я несказанно рад тому, что могу называть тебя $gБратом:Сестрой;: твое посвящение – радость для всех нас.$b$bПришло время вручить тебе великий дар. Но знай: сейчас я даю его тебе, не требуя ничего взамен; но потом настанет час, когда всем паладинам придется немало потрудиться для того, чтобы получить его.$b$bПриходи в любое время – я отдам тебе твой подарок.','Поговорите с Даторианом Раллом в Штормграде.','Поздравляю! Да пребудет с тобой Свет!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант благородства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $n! Я несказанно рад тому, что могу называть тебя $gБратом:Сестрой;: твое посвящение – радость для всех нас.$b$bПришло время вручить тебе великий дар. Но знай: сейчас я даю его тебе, не требуя ничего взамен; но потом настанет час, когда всем паладинам придется немало потрудиться для того, чтобы получить его.$b$bПриходи в любое время – я отдам тебе твой подарок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Даторианом Раллом в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поздравляю! Да пребудет с тобой Свет!',`offerrewardtext_loc8`);
