INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1665,'Кружка Бартлби','Ладно, бери мою кружку. Стой! Дай-ка я хотя бы допью... Ну вот. Бери.','Отнесите кружку Бартлби Баргарду.','А вот и кружка! Да уж, он не хотел с ней расставаться, но ты умеешь настоять на своем. Молодец.$b$bПриступим к обучению...','Я наблюдал за твоей дракой с Бартлби. Неплохо! Удалось отобрать кружку?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кружка Бартлби',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, бери мою кружку. Стой! Дай-ка я хотя бы допью... Ну вот. Бери.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кружку Бартлби Баргарду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А вот и кружка! Да уж, он не хотел с ней расставаться, но ты умеешь настоять на своем. Молодец.$b$bПриступим к обучению...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я наблюдал за твоей дракой с Бартлби. Неплохо! Удалось отобрать кружку?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1666,'Маршал Хаггард','Ты $gосвоил:освоила; несколько новых приемов, но без хорошего оружия тебе не обойтись. Думаю, тебе мог бы помочь маршал Хаггард.$b$bОн живет в своем поместье в Элвиннском лесу, возле лесозаготовок Восточной Долины. Он ушел в отставку, но за время службы собрал недурную коллекцию оружия.$b$bСкажи, что тебя прислал я, и если повезет, он поделится лишним оружием.','Поговорите с маршалом Хаггардом.','Кто это? Баргард, это ты? Подойди поближе. Глаза у меня уже не те. Ты так $gподкрался:подкралась;, что я принял тебя за гнолла!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маршал Хаггард',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gосвоил:освоила; несколько новых приемов, но без хорошего оружия тебе не обойтись. Думаю, тебе мог бы помочь маршал Хаггард.$b$bОн живет в своем поместье в Элвиннском лесу, возле лесозаготовок Восточной Долины. Он ушел в отставку, но за время службы собрал недурную коллекцию оружия.$b$bСкажи, что тебя прислал я, и если повезет, он поделится лишним оружием.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с маршалом Хаггардом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кто это? Баргард, это ты? Подойди поближе. Глаза у меня уже не те. Ты так $gподкрался:подкралась;, что я принял тебя за гнолла!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1667,'Джек Мертвозуб','Тебя ведь прислал Баргард? Да, у меня есть запасное оружие, но сначала я хочу дать тебе задание...$b$bНекоторое время назад меня обманул злодей из Братства Справедливости, Джек Мертвозуб. Он пришел в темноте, одетый в гербовую накидку Штормграда, и я принял его за маршала Дугхана. Джек сказал, что ему нужен мой старый знак маршала, и я, не раздумывая, отдал его... а потом он захохотал и сбежал, прежде, чем я успел его схватить!$b$bВерни мне мой знак! Джек Мертвозуб наверняка прячет его в лагере на юге.','Добыть знак маршала Хаггарда из лагеря Джека Мертвозуба и вернуться к маршалу Хаггарду.','Ура, мой знак у тебя! Я боялся, что лишился его навсегда, а шваль из Братства Справедливости получила возможность изображать из себя представителей власти. Тебе же удалось предотвратить невиданный разгул преступности.$b$bВот мое оружие, которое лежит без дела с тех времен, как я был маршалом. Я его регулярно чистил его, и оно в отличной форме, выбирай!','Мой знак у тебя? Страшно подумать, какие преступления может совершить Джек с его помощью.','Вернитесь к маршалу Хаггарду на Озеро Каменных Столбов, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джек Мертвозуб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя ведь прислал Баргард? Да, у меня есть запасное оружие, но сначала я хочу дать тебе задание...$b$bНекоторое время назад меня обманул злодей из Братства Справедливости, Джек Мертвозуб. Он пришел в темноте, одетый в гербовую накидку Штормграда, и я принял его за маршала Дугхана. Джек сказал, что ему нужен мой старый знак маршала, и я, не раздумывая, отдал его... а потом он захохотал и сбежал, прежде, чем я успел его схватить!$b$bВерни мне мой знак! Джек Мертвозуб наверняка прячет его в лагере на юге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добыть знак маршала Хаггарда из лагеря Джека Мертвозуба и вернуться к маршалу Хаггарду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура, мой знак у тебя! Я боялся, что лишился его навсегда, а шваль из Братства Справедливости получила возможность изображать из себя представителей власти. Тебе же удалось предотвратить невиданный разгул преступности.$b$bВот мое оружие, которое лежит без дела с тех времен, как я был маршалом. Я его регулярно чистил его, и оно в отличной форме, выбирай!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мой знак у тебя? Страшно подумать, какие преступления может совершить Джек с его помощью.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Хаггарду на Озеро Каменных Столбов, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1678,'Веджрек','Хорошему воину пристало быть стойким. Я научу тебя новым приемам, но прежде докажи, что сможешь справиться с серьезными противниками.$b$bВеджрек – один из самых сильных троллей в наших краях. Ему-то ты и бросишь вызов. Он живет в хижине в предгорьях, чуть южнее Форта Мерзлогривов.$b$bПринеси мне голову Веджрека, и я поверю, что ты не лыком $gшит:шита;.','Принесите голову Веджрека Марену Грозовой Вершине в Стальгорн.','Вернитесь к Марену Грозовой Вершине в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Веджрек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошему воину пристало быть стойким. Я научу тебя новым приемам, но прежде докажи, что сможешь справиться с серьезными противниками.$b$bВеджрек – один из самых сильных троллей в наших краях. Ему-то ты и бросишь вызов. Он живет в хижине в предгорьях, чуть южнее Форта Мерзлогривов.$b$bПринеси мне голову Веджрека, и я поверю, что ты не лыком $gшит:шита;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Веджрека Марену Грозовой Вершине в Стальгорн.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марену Грозовой Вершине в Стальгорн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1679,'Марен Грозовая Вершина','Привет тебе, воин! Ты $gнаделен:наделена; многими талантами, но тебе предстоит многому научиться, и лучше учителя, чем Марен Грозовая Вершина, не найдешь.$b$bМарен в Оружейной, в Палатах Войны Стальгорна. Как только ты решишь сделать очередной шаг на пути воина, поговори с ним.','Поговорите с Мареном Грозовой Вершиной.','А, $n. Я слышал твое имя от воинов Дун Морога. Надеюсь, ты не все время проводишь в пивных?','Вы переключились?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Марен Грозовая Вершина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, воин! Ты $gнаделен:наделена; многими талантами, но тебе предстоит многому научиться, и лучше учителя, чем Марен Грозовая Вершина, не найдешь.$b$bМарен в Оружейной, в Палатах Войны Стальгорна. Как только ты решишь сделать очередной шаг на пути воина, поговори с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мареном Грозовой Вершиной.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, $n. Я слышал твое имя от воинов Дун Морога. Надеюсь, ты не все время проводишь в пивных?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы переключились?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1680,'Тормус Подземная Кузня','Ты уже $gосвоил:освоила; несколько приемов, пора заняться твоим оружием. Поговори с Тормусом Подземной Кузней. Он скует тебе оружие по вкусу.$b$bТормус живет здесь, в Стальгорне, в Великой Кузне.','Поговорите с Тормусом Подземной Кузней.','Тебя прислал Марен? Да, я могу сковать тебе превосходное оружие... Но услуга за услугу.$b$bНе бойся. Конечно, задание будет опасным, ты можешь погибнуть, но разве не к этому стремятся все воины?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тормус Подземная Кузня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gосвоил:освоила; несколько приемов, пора заняться твоим оружием. Поговори с Тормусом Подземной Кузней. Он скует тебе оружие по вкусу.$b$bТормус живет здесь, в Стальгорне, в Великой Кузне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тормусом Подземной Кузней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Марен? Да, я могу сковать тебе превосходное оружие... Но услуга за услугу.$b$bНе бойся. Конечно, задание будет опасным, ты можешь погибнуть, но разве не к этому стремятся все воины?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1681,'Мастерская Сталекрута','У моего наставника, Стурги Сталекрута, была мастерская на юге от озера Хельмова ложа в восточной части Дун Морога. Он был лучшим учителем кузнечного дела.$b$bНо однажды ученики принесли ему странную руду. Мастер Сталекрут назвал ее мрачной рудой и с радостью с ней работал, но увы, вскоре на них напал отряд дворфов Черного Железа. Они поубивали всех!$b$bСтупай в мастерскую Сталекрута, $n, и отомсти за смерть моего учителя. И принеси мне груз мрачной руды.','Принесите мрачную руду Тормусу Подземной Кузне в Стальгорн.','Тебе удалось пробраться в поселок Сталекрута? А мрачная руда у тебя?','Вернитесь к Тормусу Подземной Кузне в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастерская Сталекрута',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У моего наставника, Стурги Сталекрута, была мастерская на юге от озера Хельмова ложа в восточной части Дун Морога. Он был лучшим учителем кузнечного дела.$b$bНо однажды ученики принесли ему странную руду. Мастер Сталекрут назвал ее мрачной рудой и с радостью с ней работал, но увы, вскоре на них напал отряд дворфов Черного Железа. Они поубивали всех!$b$bСтупай в мастерскую Сталекрута, $n, и отомсти за смерть моего учителя. И принеси мне груз мрачной руды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мрачную руду Тормусу Подземной Кузне в Стальгорн.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось пробраться в поселок Сталекрута? А мрачная руда у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тормусу Подземной Кузне в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1682,'Оружие из серой стали','Вот тебе оружие, только что с наковальни. На него пошла добытая тобой мрачная руда!$b$bЧто же, $n, выбирай!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие из серой стали',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот тебе оружие, только что с наковальни. На него пошла добытая тобой мрачная руда!$b$bЧто же, $n, выбирай!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1683,'Ворлус Подлое Копыто','Прежде чем браться за твое обучение, я хочу испытать твою храбрость.$B$bСатир Ворлус Подлое Копыто обнаружил один из наших лунных колодцев, тот, что на юго-востоке от обители Бен\'этиль. Он плещется в его светлых водах, оскверняя их своим присутствием.$b$bОтыщи Ворлуса и убей его. В доказательство принеси мне его рог, и я возьмусь учить тебя.$b$bОтыскать дорогу к колодцу очень трудно, но тот, кто ищет, тот всегда найдет.','Принесите рог Ворлуса Эланарии из Дарнаса.','Прекрасно сделано, $N. Как приятно знать, что Ворлус побежден и наш лунный колодец очищен. Приятно видеть юных воинов, стремящихся защитить от порчи наш любимый Тельдрассил.$B$BТеперь, давай начнем обучение...','У тебя есть рог, $N? Наш лунный колодец свободен от демона Ворлуса?','Вернитесь к Эланарии на Террасу Воинов, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ворлус Подлое Копыто',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем браться за твое обучение, я хочу испытать твою храбрость.$B$bСатир Ворлус Подлое Копыто обнаружил один из наших лунных колодцев, тот, что на юго-востоке от обители Бен\'этиль. Он плещется в его светлых водах, оскверняя их своим присутствием.$b$bОтыщи Ворлуса и убей его. В доказательство принеси мне его рог, и я возьмусь учить тебя.$b$bОтыскать дорогу к колодцу очень трудно, но тот, кто ищет, тот всегда найдет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите рог Ворлуса Эланарии из Дарнаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно сделано, $N. Как приятно знать, что Ворлус побежден и наш лунный колодец очищен. Приятно видеть юных воинов, стремящихся защитить от порчи наш любимый Тельдрассил.$B$BТеперь, давай начнем обучение...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть рог, $N? Наш лунный колодец свободен от демона Ворлуса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эланарии на Террасу Воинов, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1684,'Эланария','Приветствую тебя, воин. Ты растешь над собой, но профессия воина не так проста, как кажется. Тебе нужен хороший учитель.$b$bВ Дарнасе, на Террасе Воинов, живет Эланария. Поучись у нее.','Поговорите с Эланарией.','Приветствую, $N. Говорят, что ты подаешь надежды. Но надо еще убедиться есть ли у тебя сила воли, необходимая выбравшему путь воина.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эланария',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, воин. Ты растешь над собой, но профессия воина не так проста, как кажется. Тебе нужен хороший учитель.$b$bВ Дарнасе, на Террасе Воинов, живет Эланария. Поучись у нее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эланарией.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую, $N. Говорят, что ты подаешь надежды. Но надо еще убедиться есть ли у тебя сила воли, необходимая выбравшему путь воина.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1685,'Приглашение Гакина','И вот так всегда. Я разыскивал тебя весь день, но так и не смог найти; а сейчас, когда я вовсе этого не ожидал, ты появляешься как из-под земли.$b$BЯ уже и так слишком много времени потратил на твои поиски, так что буду краток. Наставник Гакин призывает тебя для дополнительных занятий – и, думаю, тебе стоит поторопиться.$b$BТы найдешь его в подвале таверны "Забитый ягненок". К слову сказать, не стоит много болтать об этом месте...','Встретьтесь с Гакином Темнопрядом в квартале магов Штормграда.','Наконец-то ты здесь. Мне следовало послать за тобой кого-нибудь более расторопного, чем Ремен.$B$BНу, неважно.$B$BКогда у тебя было последнее занятие? Слишком давно, слишком... А ты знаешь, что у плохо обученного чернокнижника мало шансов сохранить голову на плечах?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приглашение Гакина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И вот так всегда. Я разыскивал тебя весь день, но так и не смог найти; а сейчас, когда я вовсе этого не ожидал, ты появляешься как из-под земли.$b$BЯ уже и так слишком много времени потратил на твои поиски, так что буду краток. Наставник Гакин призывает тебя для дополнительных занятий – и, думаю, тебе стоит поторопиться.$b$BТы найдешь его в подвале таверны "Забитый ягненок". К слову сказать, не стоит много болтать об этом месте...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Гакином Темнопрядом в квартале магов Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то ты здесь. Мне следовало послать за тобой кого-нибудь более расторопного, чем Ремен.$B$BНу, неважно.$B$BКогда у тебя было последнее занятие? Слишком давно, слишком... А ты знаешь, что у плохо обученного чернокнижника мало шансов сохранить голову на плечах?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1686,'Тень Элуры','Ты многому $gнаучился:научилась;, $n. Пора создать для тебя настоящее оружие. Оружие воина.$b$bТебе придется отправиться за ним на Темные берега.$b$bДавным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой.$b$bДля начала тебе придется одержать верх над стражем элунита, тенью Элуры. Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза. Победи ее, забери у нее медальон и собери со дна ящики с элунитом.','Принесите 8 партий элунитовой руды и медальон Элуры Эланарии из Дарнаса.','Браво, $N.$B$BТы $Gдал:дала; Тени Элуры так долго ожидаемый мир, и мы используем этот элунит чтобы сделать тебе оружие.','Ты $Gпобедил:победила; Тень Элуры, $N? У тебя есть потерянная элунитовая руда?','Вернитесь к Эланарии на Террасу Воинов, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тень Элуры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты многому $gнаучился:научилась;, $n. Пора создать для тебя настоящее оружие. Оружие воина.$b$bТебе придется отправиться за ним на Темные берега.$b$bДавным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой.$b$bДля начала тебе придется одержать верх над стражем элунита, тенью Элуры. Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза. Победи ее, забери у нее медальон и собери со дна ящики с элунитом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 партий элунитовой руды и медальон Элуры Эланарии из Дарнаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Браво, $N.$B$BТы $Gдал:дала; Тени Элуры так долго ожидаемый мир, и мы используем этот элунит чтобы сделать тебе оружие.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпобедил:победила; Тень Элуры, $N? У тебя есть потерянная элунитовая руда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эланарии на Террасу Воинов, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1687,'Маяк с привидениями','Попечительницы сирот рассказывают нам сказки на ночь. Иногда даже про привидений. Это очень круто! Мне запомнилась история про призрака, жившего в маяке Западного Края. Говорят, он был капитаном пиратского корабля, но корабль захватили другие пираты. Правда, интересно?$b$bОтведи меня к этому маяку! Я хочу посмотреть на призрак капитана! Обещаю не отходить от тебя ни на шаг!','Отведите сироту к маяку на побережье Западного Края.','Разве мы уже там?','Сходить к маяку Западного Края.','Поговорите со своим подопечным ребенком-сиротой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маяк с привидениями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Попечительницы сирот рассказывают нам сказки на ночь. Иногда даже про привидений. Это очень круто! Мне запомнилась история про призрака, жившего в маяке Западного Края. Говорят, он был капитаном пиратского корабля, но корабль захватили другие пираты. Правда, интересно?$b$bОтведи меня к этому маяку! Я хочу посмотреть на призрак капитана! Обещаю не отходить от тебя ни на шаг!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите сироту к маяку на побережье Западного Края.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разве мы уже там?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сходить к маяку Западного Края.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим подопечным ребенком-сиротой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1688,'Сурена Каледон','I had a student named Surena Caledon. She stood where you stand now, eager to learn of warlock magic, and possessing no small bit of talent. More than that she was young and pleasing to the eye. Had I seen it then, the traitorous trollop!$b$bThe thieving wench ran off with a thug, Erlan Drudgemoor. While her loss is of little importance, I gifted her a bloodstone choker that I must have.$b$bHer life means nothing to me now. You will find her at the Brackwell Pumpkin Patch. Retrieve what is mine.','Верните колье Кровавого камня Гакину Темной Вязи в Штормград.','Сурена была талантлива, но не настолько, чтобы овладеть чарами самостоятельно. Печально видеть, как погибают молодые и талантливые, но иногда без этого нельзя.$B$BНадеюсь, усилия, вложенные в тебя, прахом не пойдут...','Старики и мудрецы тоже подвластны чарам молодости и красоты, $N. Это совет, который стоит запомнить на всю оставшуюся жизнь.','Вернитесь к Гакину Темнопряду в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сурена Каледон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','I had a student named Surena Caledon. She stood where you stand now, eager to learn of warlock magic, and possessing no small bit of talent. More than that she was young and pleasing to the eye. Had I seen it then, the traitorous trollop!$b$bThe thieving wench ran off with a thug, Erlan Drudgemoor. While her loss is of little importance, I gifted her a bloodstone choker that I must have.$b$bHer life means nothing to me now. You will find her at the Brackwell Pumpkin Patch. Retrieve what is mine.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните колье Кровавого камня Гакину Темной Вязи в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сурена была талантлива, но не настолько, чтобы овладеть чарами самостоятельно. Печально видеть, как погибают молодые и талантливые, но иногда без этого нельзя.$B$BНадеюсь, усилия, вложенные в тебя, прахом не пойдут...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Старики и мудрецы тоже подвластны чарам молодости и красоты, $N. Это совет, который стоит запомнить на всю оставшуюся жизнь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гакину Темнопряду в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1689,'Оковы','Вернув мое колье и обманув Сурену, ты $Gдоказал:доказала;, что не уступаешь ей в таланте.$b$bПоэтому я уверен, что тебе не помешает обучение. Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше.$b$bЯ научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоем распоряжении. Используй магию колье в кругу призыва.','С помощью колье Кровавого камня призовите и подчините демона Бездны, затем верните колье Кровавого камня Гакину Темнопряду.','Тебе удалось даже больше, чем я ожидал, $N. На это я и надеялся. Теперь ты можешь научиться управлять покоренным тобой демоном. Он станет твоим помощником в предстоящих испытаниях. Сейчас мне нечему больше учить тебя, но я уверен, что мы с тобой, $N, еще увидимся...','Я не могу показать тебе, как управлять демоном Бездны, пока ты не подчинишь его своей воле.','Вернитесь к Гакину Темнопряду в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оковы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вернув мое колье и обманув Сурену, ты $Gдоказал:доказала;, что не уступаешь ей в таланте.$b$bПоэтому я уверен, что тебе не помешает обучение. Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше.$b$bЯ научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоем распоряжении. Используй магию колье в кругу призыва.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью колье Кровавого камня призовите и подчините демона Бездны, затем верните колье Кровавого камня Гакину Темнопряду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось даже больше, чем я ожидал, $N. На это я и надеялся. Теперь ты можешь научиться управлять покоренным тобой демоном. Он станет твоим помощником в предстоящих испытаниях. Сейчас мне нечему больше учить тебя, но я уверен, что мы с тобой, $N, еще увидимся...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не могу показать тебе, как управлять демоном Бездны, пока ты не подчинишь его своей воле.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гакину Темнопряду в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1690,'Расправа над Скитальцами Пустыни','Эй, ты! Пора оказать услугу Водной компании Прибамбасска.$b$bКочевники Скитальцев Пустыни захватили почти все колодцы пустыни Танарис! Без них у нас мигом закончится вода. Если ты хочешь заслужить нашу признательность, расправься с этими варварами!$b$bСтупай на восток и прикончи 10 бандитов и 10 воров из шайки Скитальцев Пустыни, а на обратном пути доложись мне. Никому не миновать расправы... или как там говорится... А, неважно, иди себе!','Убейте 10 бандитов и 10 воров из шайки Скитальцев Пустыни на востоке от Прибамбасска и возвращайтесь к главному инженеру Чепухастеру.','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расправа над Скитальцами Пустыни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты! Пора оказать услугу Водной компании Прибамбасска.$b$bКочевники Скитальцев Пустыни захватили почти все колодцы пустыни Танарис! Без них у нас мигом закончится вода. Если ты хочешь заслужить нашу признательность, расправься с этими варварами!$b$bСтупай на восток и прикончи 10 бандитов и 10 воров из шайки Скитальцев Пустыни, а на обратном пути доложись мне. Никому не миновать расправы... или как там говорится... А, неважно, иди себе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 бандитов и 10 воров из шайки Скитальцев Пустыни на востоке от Прибамбасска и возвращайтесь к главному инженеру Чепухастеру.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1691,'Еще одна расправа над Скитальцами Пустыни','Теперь тебе придется схватиться с кочевниками посильнее. Ты неплохо $gпоработал:поработала;, но если отбивать у этих гадов наши колодцы, лучше бы противников было поменьше!$b$bНа сей раз выступи против разбойников, убийц и темных магов. Их можно найти на востоке и юго-востоке отсюда.$b$bНе буду тебе лгать – справиться с ними нелегко. Зато в случае успеха мы очень скоро сможем вернуть себе принадлежащее нам по праву!','Убейте 10 темных магов, 8 разбойников и 6 убийц из шайки Скитальцев Пустыни по поручению главного инженера Чепухастера из Прибамбасска.','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще одна расправа над Скитальцами Пустыни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь тебе придется схватиться с кочевниками посильнее. Ты неплохо $gпоработал:поработала;, но если отбивать у этих гадов наши колодцы, лучше бы противников было поменьше!$b$bНа сей раз выступи против разбойников, убийц и темных магов. Их можно найти на востоке и юго-востоке отсюда.$b$bНе буду тебе лгать – справиться с ними нелегко. Зато в случае успеха мы очень скоро сможем вернуть себе принадлежащее нам по праву!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 темных магов, 8 разбойников и 6 убийц из шайки Скитальцев Пустыни по поручению главного инженера Чепухастера из Прибамбасска.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (1691,'Top notch work, $n... top notch! You\'ve thinned down the nomad population to a point where we can actually take the fight to them!$B$BIf you haven\'t already, talk to Spigot Operator Luglunket here; he gives a bounty on any of the Wastewander water pouches you may have run across while bringing those nomads to justice!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Top notch work, $n... top notch! You\'ve thinned down the nomad population to a point where we can actually take the fight to them!$B$BIf you haven\'t already, talk to Spigot Operator Luglunket here; he gives a bounty on any of the Wastewander water pouches you may have run across while bringing those nomads to justice!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1692,'Кузнец Матиль','Я сложила собранный тобой элунит в сундук. Отнеси его кузнецу Матилю, мы сделаем из него элунитовое оружие.$b$bМатиль на юге отсюда, на другой стороне этого здания.','Отнесите сундук элунита кузнецу Матилю.','А, элунитовая руда. Работать с этим металлом – одно удовольствие, ведь он благословлен самой богиней Элуной. Выковать элунитовое оружие – великая честь.$B$BПодожди, я сейчас примусь за работу...','Привет тебе, $Gюный:юная; $C. Чем могу тебе служить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кузнец Матиль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сложила собранный тобой элунит в сундук. Отнеси его кузнецу Матилю, мы сделаем из него элунитовое оружие.$b$bМатиль на юге отсюда, на другой стороне этого здания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сундук элунита кузнецу Матилю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, элунитовая руда. Работать с этим металлом – одно удовольствие, ведь он благословлен самой богиней Элуной. Выковать элунитовое оружие – великая честь.$B$BПодожди, я сейчас примусь за работу...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет тебе, $Gюный:юная; $C. Чем могу тебе служить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1693,'Оружие из элунита','Это оружие я выковал из принесенного тобой элунита. Можешь взять себе любое.$B$BБольшое спасибо. Работать с элунитом – не только удовольствие, но и великая честь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие из элунита',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это оружие я выковал из принесенного тобой элунита. Можешь взять себе любое.$B$BБольшое спасибо. Работать с элунитом – не только удовольствие, но и великая честь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1698,'Йорус Ячменовар','Йорус Ячменовар бросил вызов всем воинам Альянса. Он ждет в таверне Приозерья, что в Красногорье, и сулит щедрую награду всем, прошедшим испытание.','Поговорите с Йорусом Ячменоваром.','Ха! Значит, до тебя дошли вести о моем вызове, а?$b$bЧто ж, садись и слушай. Пей и наслаждайся... Может быть, это твоя последняя выпивка в этой жизни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Йорус Ячменовар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Йорус Ячменовар бросил вызов всем воинам Альянса. Он ждет в таверне Приозерья, что в Красногорье, и сулит щедрую награду всем, прошедшим испытание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Йорусом Ячменоваром.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Значит, до тебя дошли вести о моем вызове, а?$b$bЧто ж, садись и слушай. Пей и наслаждайся... Может быть, это твоя последняя выпивка в этой жизни.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1699,'Ретбанский вызов','Я называю мое испытание Ретбанским вызовом. Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться. Элементарно! Есть, правда, несколько "но"...$b$BВернуться тебе придется в течение часа.$b$bТам полно красногорских гноллов.$b$bПеред тем, как тронуться в путь, тебе придется глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменоваров!$b$bЧто скажешь? Пещеры Ретбана находятся в холмах на севере от Приозерья. Ты $gготов:готова; принять Ретбанский вызов?','Войдите в пещеры Ретбана, доберитесь до первой развилки и вернитесь к Йорусу Ячменовару за отведенное время.$b$bВы не должны умирать и освобождать свой дух.','Войдите в пещеры Ретбана','Вернитесь к Йорусу Ячменовару на Озеро Безмолвия, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ретбанский вызов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я называю мое испытание Ретбанским вызовом. Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться. Элементарно! Есть, правда, несколько "но"...$b$BВернуться тебе придется в течение часа.$b$bТам полно красногорских гноллов.$b$bПеред тем, как тронуться в путь, тебе придется глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменоваров!$b$bЧто скажешь? Пещеры Ретбана находятся в холмах на севере от Приозерья. Ты $gготов:готова; принять Ретбанский вызов?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в пещеры Ретбана, доберитесь до первой развилки и вернитесь к Йорусу Ячменовару за отведенное время.$b$bВы не должны умирать и освобождать свой дух.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Войдите в пещеры Ретбана',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йорусу Ячменовару на Озеро Безмолвия, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1700,'Гриманд Элмор','Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Гриманду Элмору. Он живет здесь, в Квартале Дворфов, в оружейном магазине. Он гордится своим искусством и совсем не обрадуется моему открытию...','Отнесите записки Фьюрена Гриманду Элмору.','Это написал Фьюрен? Как он смел! Да я его всему сам научил! Яйца курицу не учат! Нахал!$B$BХм-м-м... Но в этих записях что-то есть... Надо попробовать...','Приветствую, добро пожаловать. Чем могу помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гриманд Элмор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Гриманду Элмору. Он живет здесь, в Квартале Дворфов, в оружейном магазине. Он гордится своим искусством и совсем не обрадуется моему открытию...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите записки Фьюрена Гриманду Элмору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это написал Фьюрен? Как он смел! Да я его всему сам научил! Яйца курицу не учат! Нахал!$B$BХм-м-м... Но в этих записях что-то есть... Надо попробовать...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, добро пожаловать. Чем могу помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1701,'Закаленный доспех','Ну вот, я дал тебе отличный щит, но это еще не все. Я знаю секрет изготовления очень прочного доспеха. Это нелегко, и мне потребуются редкие материалы, но если тебе не лень за ними поохотиться, доспех получится несравненный.$b$bЧто скажешь? Если ты не боишься трудностей, я выдам тебе список необходимых материалов и где их искать.','Соберите все необходимые материалы для Фьюрена Длинноборода и отнесите их в Штормград.','Тебе удалось добыть все необходимое? Вот это да! Я опасался, что химеры слопают тебя с потрохами!$B$BЧто ж, займемся доспехами...','Как охота на падальщиков? Удалось добыть нужные материалы?','Вернитесь к Фьюрену Длиннобороду в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закаленный доспех',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, я дал тебе отличный щит, но это еще не все. Я знаю секрет изготовления очень прочного доспеха. Это нелегко, и мне потребуются редкие материалы, но если тебе не лень за ними поохотиться, доспех получится несравненный.$b$bЧто скажешь? Если ты не боишься трудностей, я выдам тебе список необходимых материалов и где их искать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите все необходимые материалы для Фьюрена Длинноборода и отнесите их в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось добыть все необходимое? Вот это да! Я опасался, что химеры слопают тебя с потрохами!$B$BЧто ж, займемся доспехами...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как охота на падальщиков? Удалось добыть нужные материалы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фьюрену Длиннобороду в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1702,'Щитник','Да, приняв Ретбанский вызов, ты $gпоказал:показала;, на что $gспособен:способна;. Я свое слово держу. Ты получишь обещанную награду...$b$bТолько она в Штормграде.$b$bПоговори с моим другом, Фьюреном Длиннобородом. Он живет в Квартале Дворфов. Его щиты славятся во всей округе, а мне он должен услугу.$b$bВот, отнеси Фьюрену этот бочонок жгучего пива Ячменоваров и попроси взамен щит. Он плохого не даст.','Отнесите бочонок жгучего пива Фьюрену Длиннобороду.','А, жгучее пиво Ячменевца. Отличный напиток! Значит, ты от Йоруса, а?$b$bКонечно я дам тебе щит, да еще какой! Такого нигде не найти, честное слово!','Привет! Меня мучает жажда, а тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Щитник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, приняв Ретбанский вызов, ты $gпоказал:показала;, на что $gспособен:способна;. Я свое слово держу. Ты получишь обещанную награду...$b$bТолько она в Штормграде.$b$bПоговори с моим другом, Фьюреном Длиннобородом. Он живет в Квартале Дворфов. Его щиты славятся во всей округе, а мне он должен услугу.$b$bВот, отнеси Фьюрену этот бочонок жгучего пива Ячменоваров и попроси взамен щит. Он плохого не даст.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите бочонок жгучего пива Фьюрену Длиннобороду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, жгучее пиво Ячменевца. Отличный напиток! Значит, ты от Йоруса, а?$b$bКонечно я дам тебе щит, да еще какой! Такого нигде не найти, честное слово!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет! Меня мучает жажда, а тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1703,'Матиль','Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Матилю. Он живет довольно далеко, в Дарнасе, но несомненно будет рад, если я поделюсь с ним своими открытиями.','Отнесите Матилю записки Фьюрена.','Это интересно, очень интересно. Мой коллега Фьюрен, сделал грандиозное открытие.$B$BСпасибо, $N. Это будет честью для меня, применять новые технологии к моим разработкам.','Приветствую тебя, $C.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Матиль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Матилю. Он живет довольно далеко, в Дарнасе, но несомненно будет рад, если я поделюсь с ним своими открытиями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Матилю записки Фьюрена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это интересно, очень интересно. Мой коллега Фьюрен, сделал грандиозное открытие.$B$BСпасибо, $N. Это будет честью для меня, применять новые технологии к моим разработкам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя, $C.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1704,'Клацморт Гайкокрут','Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Клацморту Гайкокруту. Он живет в Стальгорне, и когда услышит о моем открытии... Он бороду себе выдернет от восторга!','Отнесите записки Фьюрена Клацморту Гайкокруту.','Ну и ну! Поразительные записи мне прислали! Больше того... Они ошеломляющие и невероятные, я едва на ногах стою от восторга!$B$BФьюрен совершил прорыв в кузнечном деле! Да-да, самый настоящий прорыв! Мне не терпится испробовать новую технологию!','Добрый день, или утро, или вечер. Какая разница! Ты ко мне по делу?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клацморт Гайкокрут',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Клацморту Гайкокруту. Он живет в Стальгорне, и когда услышит о моем открытии... Он бороду себе выдернет от восторга!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите записки Фьюрена Клацморту Гайкокруту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну и ну! Поразительные записи мне прислали! Больше того... Они ошеломляющие и невероятные, я едва на ногах стою от восторга!$B$BФьюрен совершил прорыв в кузнечном деле! Да-да, самый настоящий прорыв! Мне не терпится испробовать новую технологию!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добрый день, или утро, или вечер. Какая разница! Ты ко мне по делу?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1705,'Пылающая кровь','Может, этот Фьюрен и совершил открытие, но мне надо проверить, так ли это. Попробую-ка я сделать такие доспехи. Если ты поможешь добыть все материалы, можешь забрать доспех себе.$b$bМне понадобится горящая кровь и горящий камень.$b$bЕдинственное место, где можно добыть эти материалы – Сумеречный лес. Горящая кровь есть у воргенов из стаи Ночной Погибели из пещеры Роланда, а горящий камень хранит у себя их главарь, Кишкодер.$B$BИ не мешкай, во имя Света.','Принесите 20 сосудов горящей крови и 1 горящий камень Гриманду Элмору из Штормграда.','Недурно! А теперь, прошу прощения, мне тоже надо поработать...','Ну как, удалось добыть горящую кровь и камень? Без них доспехов не сделаешь.','Вернитесь к Гриманду Эльмору в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пылающая кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может, этот Фьюрен и совершил открытие, но мне надо проверить, так ли это. Попробую-ка я сделать такие доспехи. Если ты поможешь добыть все материалы, можешь забрать доспех себе.$b$bМне понадобится горящая кровь и горящий камень.$b$bЕдинственное место, где можно добыть эти материалы – Сумеречный лес. Горящая кровь есть у воргенов из стаи Ночной Погибели из пещеры Роланда, а горящий камень хранит у себя их главарь, Кишкодер.$B$BИ не мешкай, во имя Света.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 сосудов горящей крови и 1 горящий камень Гриманду Элмору из Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Недурно! А теперь, прошу прощения, мне тоже надо поработать...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось добыть горящую кровь и камень? Без них доспехов не сделаешь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гриманду Эльмору в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1706,'Доспехи Гриманда','Глазам своим не верю! Технология Фьюрена оказалась удачной, и этот доспех способен выдержать серьезную нагрузку.$B$BДержи, $N. И огромное тебе спасибо. Если бы ты не $Gпринес:принесла; мне все необходимые материалы, я бы так и не поверил в открытие Фьюрина.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доспехи Гриманда',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Глазам своим не верю! Технология Фьюрена оказалась удачной, и этот доспех способен выдержать серьезную нагрузку.$B$BДержи, $N. И огромное тебе спасибо. Если бы ты не $Gпринес:принесла; мне все необходимые материалы, я бы так и не поверил в открытие Фьюрина.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1707,'Награда за воду','Привет тебе, $n. Меня зовут Живец, и у меня есть для тебя важная работа! Ура!$b$bЯ опытный оператор крана, и ничто не порадует меня так, как бурдюки с водой Скитальцев Пустыни, которые могут попасться тебе в пустыне, у кочевников. Все равно это наша вода – мерзкие кочевники ее украли! Водная компания Прибамбасска предлагает в награду полевой набор за каждые пять бурдюков. А главное, ты поможешь Прибамбасску!','Принесите 5 бурдюков Скитальцев Пустыни оператору крана Тормозиллеру в Прибамбасск.','Вернитесь к оператору крана Тормозиллеру в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда за воду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $n. Меня зовут Живец, и у меня есть для тебя важная работа! Ура!$b$bЯ опытный оператор крана, и ничто не порадует меня так, как бурдюки с водой Скитальцев Пустыни, которые могут попасться тебе в пустыне, у кочевников. Все равно это наша вода – мерзкие кочевники ее украли! Водная компания Прибамбасска предлагает в награду полевой набор за каждые пять бурдюков. А главное, ты поможешь Прибамбасску!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 бурдюков Скитальцев Пустыни оператору крана Тормозиллеру в Прибамбасск.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оператору крана Тормозиллеру в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1708,'Железный коралл','Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах. Раз ты $gпомог:помогла; Фьюрену, а он мне, я разрешу тебе забрать их себе!$b$BЧтобы довести работу до конца, мне необходим особый коралл, выжженный. Он растет лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине.$b$bПринеси мне побольше таких кораллов, и я примусь за работу. И поторапливайся, $n, у меня руки чешутся, так хочется взяться за дело.','Принесите 20 партий выжженного коралла Клацморту Гайкокруту в Стальгорн.','Вот, то что нужно! $GМолодец:Умница;! А теперь дай-ка я их расплавлю и расплющу. Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет!$B$BНу-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!','Привет-привет, $N! Ты несешь мне выжженные кораллы? Мне не терпится взяться за работу!','Вернитесь к Клацморту Гайкокруту в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Железный коралл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах. Раз ты $gпомог:помогла; Фьюрену, а он мне, я разрешу тебе забрать их себе!$b$BЧтобы довести работу до конца, мне необходим особый коралл, выжженный. Он растет лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине.$b$bПринеси мне побольше таких кораллов, и я примусь за работу. И поторапливайся, $n, у меня руки чешутся, так хочется взяться за дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 партий выжженного коралла Клацморту Гайкокруту в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, то что нужно! $GМолодец:Умница;! А теперь дай-ка я их расплавлю и расплющу. Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет!$B$BНу-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет-привет, $N! Ты несешь мне выжженные кораллы? Мне не терпится взяться за работу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Клацморту Гайкокруту в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1709,'Творение Клацморта','Вот твои доспехи, $N. Идея Фьюрена отлично сработала. Идеально! Чудесно, если правду сказать!$B$BПо этой броне можно осадные орудия прокатить, и она сохранит форму!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Творение Клацморта',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот твои доспехи, $N. Идея Фьюрена отлично сработала. Идеально! Чудесно, если правду сказать!$B$BПо этой броне можно осадные орудия прокатить, и она сохранит форму!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1710,'Высохшая скорлупа','Мой коллега, Фьюрен Долгобород, совершил многообещающее открытие. Я хотел бы испытать его на новых доспехах, мне кажется, результат превзойдет все ожидания.$b$bНе поможешь? Если ты принесешь мне все необходимые материалы, я и для тебя сделаю такие доспехи.$b$bМне понадобится высохшая на солнце скорлупа яиц виверн Скального Гнездовья из Тысячи Игл. Скорлупу можно найти под их гнездами. Как наберешь достаточно, возвращайся.','Принесите 20 кусков высохшей на солнце скорлупы Матилю из Дарнаса.','Ах, спасибо тебе! Это прекрасно подойдет!$B$BЯ начну создавать броню немедленно.','У тебя есть ракушки, $N? Они довольно прочные, и их можно обработать лаком, которым я буду покрывать звенья моей новой кольчужной брони.','Вернитесь к Матилю на Террасу Воинов, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Высохшая скорлупа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой коллега, Фьюрен Долгобород, совершил многообещающее открытие. Я хотел бы испытать его на новых доспехах, мне кажется, результат превзойдет все ожидания.$b$bНе поможешь? Если ты принесешь мне все необходимые материалы, я и для тебя сделаю такие доспехи.$b$bМне понадобится высохшая на солнце скорлупа яиц виверн Скального Гнездовья из Тысячи Игл. Скорлупу можно найти под их гнездами. Как наберешь достаточно, возвращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 кусков высохшей на солнце скорлупы Матилю из Дарнаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, спасибо тебе! Это прекрасно подойдет!$B$BЯ начну создавать броню немедленно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть ракушки, $N? Они довольно прочные, и их можно обработать лаком, которым я буду покрывать звенья моей новой кольчужной брони.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матилю на Террасу Воинов, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1711,'Доспехи Матиля','Я закончил с твоей броней и я доволен. Новый способ Фьюрена прекрасно сочетается с моим и я уверен,что эта броня будет довольно устойчивой.$B$BСпасибо,$N.И пусть она сослужит тебе хорошую службу в будущих сражениях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доспехи Матиля',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я закончил с твоей броней и я доволен. Новый способ Фьюрена прекрасно сочетается с моим и я уверен,что эта броня будет довольно устойчивой.$B$BСпасибо,$N.И пусть она сослужит тебе хорошую службу в будущих сражениях.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1712,'Циклониан','Я давно наблюдаю за этими местами, в надежде дожить до падения великого Циклониана. Увы, мне до сих пор не встретился герой, готовый схватиться с повелителем ветра.$b$bМожет быть, этим героем окажешься ты?$b$bДокажи, что ты великий воин – собери все предметы, необходимые для призыва Циклониана. Тогда, быть может, тебе удастся одолеть его и завладеть сердцем Вихря.$b$bЕсли это свершится, я вложу силу сердца в оружие и вручу его тебе.$b$bВот список нужных компонентов.','Принесите Бат\'ра Стражу Ветра все предметы из его списка.','Ты $Gсумел:сумела; собрать все необходимое для заклинания призыва, доказав тем самым свою силу и ловкость. Но следующий шаг будет гораздо опаснее.$B$BБудем надеяться, что сила тебя не покинет.','Ты уже все $Gсобрал:собрала;, $N? Принеси все компоненты, иначе я не поверю, что тебе хватит сил одолеть Циклониана.','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Циклониан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я давно наблюдаю за этими местами, в надежде дожить до падения великого Циклониана. Увы, мне до сих пор не встретился герой, готовый схватиться с повелителем ветра.$b$bМожет быть, этим героем окажешься ты?$b$bДокажи, что ты великий воин – собери все предметы, необходимые для призыва Циклониана. Тогда, быть может, тебе удастся одолеть его и завладеть сердцем Вихря.$b$bЕсли это свершится, я вложу силу сердца в оружие и вручу его тебе.$b$bВот список нужных компонентов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Бат\'ра Стражу Ветра все предметы из его списка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсумел:сумела; собрать все необходимое для заклинания призыва, доказав тем самым свою силу и ловкость. Но следующий шаг будет гораздо опаснее.$B$BБудем надеяться, что сила тебя не покинет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже все $Gсобрал:собрала;, $N? Принеси все компоненты, иначе я не поверю, что тебе хватит сил одолеть Циклониана.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1713,'Призыв','Я готов провести ритуал призыва Циклониана. Потом тебе предстоит победить его и забрать у него из груди сердце Вихря. После этого я создам оружие, которое вберет в себя силу Циклониана.$b$b$n, $gготов:готова; ли ты выступить против повелителя ветра?','Принесите сердце Вихря Бат\'ра Стражу Ветра.','Ты $Gсправился:справилась;! Циклониан повержен, а у тебя в руках сердце Вихря!','$N, мне нужно сердце Вихря!','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я готов провести ритуал призыва Циклониана. Потом тебе предстоит победить его и забрать у него из груди сердце Вихря. После этого я создам оружие, которое вберет в себя силу Циклониана.$b$b$n, $gготов:готова; ли ты выступить против повелителя ветра?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сердце Вихря Бат\'ра Стражу Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсправился:справилась;! Циклониан повержен, а у тебя в руках сердце Вихря!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, мне нужно сердце Вихря!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1714,'Субстанция Изгнанников','Обереги медленно опускаются на дно котла…$B$BИз глубины поднимается большой пузырь воздуха, лопается и…$B$B... на поверхности оказывается оплавленный камень.','Котел бурлит, и его пары так и манят...','Вернитесь к котлу Бат\'ры в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Субстанция Изгнанников',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Обереги медленно опускаются на дно котла…$B$BИз глубины поднимается большой пузырь воздуха, лопается и…$B$B... на поверхности оказывается оплавленный камень.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Котел бурлит, и его пары так и манят...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к котлу Бат\'ры в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1715,'Таверна "Забитый ягненок"','Хмм. В прежние времена все чернокнижники Каз Модан обучались под присмотром мастеров Гномрегана, но теперь, когда все мы вынуждены ютиться в этой крысиной норе под названием Стальгорн и Магни решил не спускать с нас глаз, нам приходится отсылать наших новичков на обучение в Штормград.$b$bПо счастью, Гакин не растяпа, так что ты все равно узнаешь все, что тебе надо, но я просто киплю!$b$bКороче, ты найдешь Гакина в подвале "Забитого ягненка" в Штормграде.','Обратитесь к Гакину Темнопряду из Квартала Магов Штормграда.','Так тебя послал Злобноверт? Нет, пора бы уже этим стальгорнским растяпам как-то разобраться с ситуацией. Штормград не резиновый, и наставников тут сколько есть, и не больше. Если сюда повалит народ, то рано или поздно мы привлечем к себе внимание.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Таверна "Забитый ягненок"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хмм. В прежние времена все чернокнижники Каз Модан обучались под присмотром мастеров Гномрегана, но теперь, когда все мы вынуждены ютиться в этой крысиной норе под названием Стальгорн и Магни решил не спускать с нас глаз, нам приходится отсылать наших новичков на обучение в Штормград.$b$bПо счастью, Гакин не растяпа, так что ты все равно узнаешь все, что тебе надо, но я просто киплю!$b$bКороче, ты найдешь Гакина в подвале "Забитого ягненка" в Штормграде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Гакину Темнопряду из Квартала Магов Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так тебя послал Злобноверт? Нет, пора бы уже этим стальгорнским растяпам как-то разобраться с ситуацией. Штормград не резиновый, и наставников тут сколько есть, и не больше. Если сюда повалит народ, то рано или поздно мы привлечем к себе внимание.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1716,'Пожиратель Душ','Суккуб – пожирательница душ, разбивающая сердца и пленяющая умы... Она не несет ничего, кроме зла! Ты научишься призывать и контролировать ее. Для этого нужна приманка.$b$bСуккуб клюнет только на символ чистой любви. Когда она явится на зов, тебе нужно будет подчинить ее. Однако... нелегко найти что-либо способное приманить суккуба. Поговори с Такаром Провидцем. Ты найдешь его в калимдорских Степях возле Лагеря Таурахо.','Поговорите с Такаром Провидцем в Степях.','$N, как вы добрались? Вы проделали долгий путь, чтобы поговорить со мной. Но не бойтесь: я знаю, зачем Гакин прислал вас. Это было мудро с его стороны, потому что я могу вам помочь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожиратель Душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Суккуб – пожирательница душ, разбивающая сердца и пленяющая умы... Она не несет ничего, кроме зла! Ты научишься призывать и контролировать ее. Для этого нужна приманка.$b$bСуккуб клюнет только на символ чистой любви. Когда она явится на зов, тебе нужно будет подчинить ее. Однако... нелегко найти что-либо способное приманить суккуба. Поговори с Такаром Провидцем. Ты найдешь его в калимдорских Степях возле Лагеря Таурахо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Такаром Провидцем в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, как вы добрались? Вы проделали долгий путь, чтобы поговорить со мной. Но не бойтесь: я знаю, зачем Гакин прислал вас. Это было мудро с его стороны, потому что я могу вам помочь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1717,'Приглашение Гакина','$n! Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать.$b$bТы давненько уже не $Gпроходил:проходила; очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде. Он будет тебя ждать.','Обратитесь к Гакину Темнопряду из Квартала Магов Штормграда.','Хорошо, что кто-то, наконец, поймал тебя, $N. Я уже опасался худшего. В тебя вложено слишком много и было бы жалко тебя потерять.$B$BМы еще поговорим на эту тему позднее.. Твоя тренировка более важна в данный момент.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приглашение Гакина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать.$b$bТы давненько уже не $Gпроходил:проходила; очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде. Он будет тебя ждать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Гакину Темнопряду из Квартала Магов Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что кто-то, наконец, поймал тебя, $N. Я уже опасался худшего. В тебя вложено слишком много и было бы жалко тебя потерять.$B$BМы еще поговорим на эту тему позднее.. Твоя тренировка более важна в данный момент.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1718,'Островитянин','Ты становишься недурным воином, $n. Пришло время помериться силой с братьями по оружию.$b$bНедалеко от побережья Степей, к югу от Кабестана, есть остров. Он называется Островом Битв. Это место встречи воинов.$b$bМесто встречи и дружеских схваток.$b$bПоговори со старшим воином острова, Кланноком Маклеодом. Если он сочтет тебя $gдостойным:достойной; дальнейшего обучения, то поможет тебе сделать очередной шаг на пути воина.$b$bДо Острова Битв можно добраться по песчаной отмели вдоль Торгового побережья.','Поговорите с Кланноком Маклеодом.','Привет тебе, воин. Хорошо, что тебе удалось добраться до Острова Битв. Надеюсь, он тебе нравится...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Островитянин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты становишься недурным воином, $n. Пришло время помериться силой с братьями по оружию.$b$bНедалеко от побережья Степей, к югу от Кабестана, есть остров. Он называется Островом Битв. Это место встречи воинов.$b$bМесто встречи и дружеских схваток.$b$bПоговори со старшим воином острова, Кланноком Маклеодом. Если он сочтет тебя $gдостойным:достойной; дальнейшего обучения, то поможет тебе сделать очередной шаг на пути воина.$b$bДо Острова Битв можно добраться по песчаной отмели вдоль Торгового побережья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кланноком Маклеодом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, воин. Хорошо, что тебе удалось добраться до Острова Битв. Надеюсь, он тебе нравится...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1719,'Побоище','Если ты хочешь учиться у меня, тебе придется пройти испытание: Побоище. Через него проходят все молодые воины, вообразившие себя великими. А величие надо доказывать.$b$bДля начала пройди сквозь ту толпу и встань на решетку. Это будет знак Пруттику Плоскоголову, что ты готов. Он сразу пришлет тебе соперника.$b$bКогда ты одолеешь всех, он позовет Большого Вилла. Убей его и вернись ко мне за отведенное время.','Убейте Большого Вилла и поговорите с Кланноком Маклеодом на Острове Битв.','Молодец, $N. Ты $Gпрошел:прошла; испытание Побоищем!$B$BТы могучий воин, и учить тебя – великая честь...','Встать на решетку, чтобы начать Побоище','Вернитесь к Кланноку Маклеоду в Великое море, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побоище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты хочешь учиться у меня, тебе придется пройти испытание: Побоище. Через него проходят все молодые воины, вообразившие себя великими. А величие надо доказывать.$b$bДля начала пройди сквозь ту толпу и встань на решетку. Это будет знак Пруттику Плоскоголову, что ты готов. Он сразу пришлет тебе соперника.$b$bКогда ты одолеешь всех, он позовет Большого Вилла. Убей его и вернись ко мне за отведенное время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Большого Вилла и поговорите с Кланноком Маклеодом на Острове Битв.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $N. Ты $Gпрошел:прошла; испытание Побоищем!$B$BТы могучий воин, и учить тебя – великая честь...',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Встать на решетку, чтобы начать Побоище',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кланноку Маклеоду в Великое море, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1738,'Сердцедрево','Готовясь к твоему приходу, я на скорую руку оглядел весь мир, проник взглядом сквозь пелену времени и нашел то, что тебе нужно.$b$bВо время Войны древних двое влюбленных вместе пали в битве. Там, где перестали биться их сердца, выросло дерево, известное как сердцедрево – символ их бессмертной любви.$b$bЭтого должно быть достаточно, чтобы привлечь суккуба. Руины Ордиль-Арана, где растет сердцедрево, находятся в северо-западной части Ясеневого леса.','Раздобудьте в Ясеневом лесу сердцедрево и принесите его Гакину Темнопряду в Квартал магов Штормграда.','Да, сердцедрево нам подойдет. Дай-ка я немного обработаю древесину...$B$BТакар – настоящий кладезь премудростей; с таким не пропадешь, правда? Если б я только мог убедить его вернуться к цивилизации...','Как проходят поиски, $N?','Вернитесь к Гакину Темнопряду в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердцедрево',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Готовясь к твоему приходу, я на скорую руку оглядел весь мир, проник взглядом сквозь пелену времени и нашел то, что тебе нужно.$b$bВо время Войны древних двое влюбленных вместе пали в битве. Там, где перестали биться их сердца, выросло дерево, известное как сердцедрево – символ их бессмертной любви.$b$bЭтого должно быть достаточно, чтобы привлечь суккуба. Руины Ордиль-Арана, где растет сердцедрево, находятся в северо-западной части Ясеневого леса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте в Ясеневом лесу сердцедрево и принесите его Гакину Темнопряду в Квартал магов Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, сердцедрево нам подойдет. Дай-ка я немного обработаю древесину...$B$BТакар – настоящий кладезь премудростей; с таким не пропадешь, правда? Если б я только мог убедить его вернуться к цивилизации...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как проходят поиски, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гакину Темнопряду в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1739,'Оковы','С помощью сердцевины сердцедрева ты сможешь открыть портал и призвать суккуба в круг призыва. Круг находится в подвале.$b$bНе забывай об осторожности, $n, суккубы подчиняли себе и самых стойких заклинателей.$b$bПосле того как вызовешь демона и вернешь его обратно в Бездну, возвращайся ко мне и я научу тебя, как обращаться с суккубом.','Призовите и подчините суккуба, используя сердцевину сердцедрева, затем верните сердцевину сердцедрева Гакину Темнопряду. Он будет ждать вас в "Забитом ягненке".','Неплохо, $N, неплохо... Я не ошибся, когда решил обучать тебя. Твои успехи меня не разочаровывают.$B$BПора научить тебя обращению с только что подчиненным суккубом. Только не забывай про осторожность!','Иногда я удивляюсь, как же Сурена, которая не была суккубом, ухитрилась так заморочить мне голову? Эх... Может быть, дело и не только в ней...','Вернитесь к Гакину Темнопряду в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оковы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С помощью сердцевины сердцедрева ты сможешь открыть портал и призвать суккуба в круг призыва. Круг находится в подвале.$b$bНе забывай об осторожности, $n, суккубы подчиняли себе и самых стойких заклинателей.$b$bПосле того как вызовешь демона и вернешь его обратно в Бездну, возвращайся ко мне и я научу тебя, как обращаться с суккубом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите и подчините суккуба, используя сердцевину сердцедрева, затем верните сердцевину сердцедрева Гакину Темнопряду. Он будет ждать вас в "Забитом ягненке".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо, $N, неплохо... Я не ошибся, когда решил обучать тебя. Твои успехи меня не разочаровывают.$B$BПора научить тебя обращению с только что подчиненным суккубом. Только не забывай про осторожность!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Иногда я удивляюсь, как же Сурена, которая не была суккубом, ухитрилась так заморочить мне голову? Эх... Может быть, дело и не только в ней...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гакину Темнопряду в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1740,'Шар Соран\'рука','Когда демоны Легиона попадают в немилость, их души заключают в сферы и раздают магам и чернокнижникам.$B$BМногих из них носили в Азероте их слуги. Даже расколотые на части, эти сферы хранят в себе силу демонов, заключенных внутри. Шар Соран\'рука был расколот надвое. Одну из частей раздробили на еще более мелкие фрагменты послушники Сумеречного Молота в Непроглядной Пучине. А другая, большая часть, досталась волшебнику из крепости Темного Клыка. Найди их, и я смогу воссоздать этот шар.','Соберите 3 фрагмента Соран\'рука и 1 большой фрагмент Соран\'рука и принесите их Доану Кархану в Степи.','Да... Этот шар не так уж сильно раскололи, и передо мной почти все осколки. Воссоздать их, сделав Соран\'рука единым целым, несложно.\n\nЯ посвятил всю жизнь изучению и восстановлению сфер Пылающего Легиона. Ты оказал мне большую услугу, позволив изучить эти осколки, и я верну их тебе, полностью восстановив, придав им любую форму по твоему выбору.','Мне понадобилось много лет, чтобы собрать все части сферы Заргейна, но она служит мне верой и правдой, как будет служить тебе шар Соран\'рука','Вернитесь к Доану Кархану в Южные Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шар Соран\'рука',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда демоны Легиона попадают в немилость, их души заключают в сферы и раздают магам и чернокнижникам.$B$BМногих из них носили в Азероте их слуги. Даже расколотые на части, эти сферы хранят в себе силу демонов, заключенных внутри. Шар Соран\'рука был расколот надвое. Одну из частей раздробили на еще более мелкие фрагменты послушники Сумеречного Молота в Непроглядной Пучине. А другая, большая часть, досталась волшебнику из крепости Темного Клыка. Найди их, и я смогу воссоздать этот шар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 фрагмента Соран\'рука и 1 большой фрагмент Соран\'рука и принесите их Доану Кархану в Степи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... Этот шар не так уж сильно раскололи, и передо мной почти все осколки. Воссоздать их, сделав Соран\'рука единым целым, несложно.\n\nЯ посвятил всю жизнь изучению и восстановлению сфер Пылающего Легиона. Ты оказал мне большую услугу, позволив изучить эти осколки, и я верну их тебе, полностью восстановив, придав им любую форму по твоему выбору.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне понадобилось много лет, чтобы собрать все части сферы Заргейна, но она служит мне верой и правдой, как будет служить тебе шар Соран\'рука',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Доану Кархану в Южные Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1758,'Фолиант заговора','Простой круг призыва не поможет тебе вызвать на бой охотника скверны.$B$BЯ и трое моих послушников поможем тебе создать магические круги. Тебе также понадобится фолиант заговора, который мы давно утратили. Его написала первая группа чернокнижников, умудрившихся вызвать охотника скверны без посторонней помощи.$B$BС этим тебе поможет Кром Крепкорук. Теперь он – главный чернокнижник, и целыми днями он сидит в библиотеке Стальгорна, оберегая древние тексты.','Поговорите с Кромом Крепкоруком в Стальгорне.','Фолиант Заговора? Хм-м... Знакомое название. Я его никогда не видел – а уж поверьте, я помню все прочитанные книги.$B$BХм…$B$BА, да! Я видел ссылки на этот фолиант в библиотечных каталогах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант заговора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Простой круг призыва не поможет тебе вызвать на бой охотника скверны.$B$BЯ и трое моих послушников поможем тебе создать магические круги. Тебе также понадобится фолиант заговора, который мы давно утратили. Его написала первая группа чернокнижников, умудрившихся вызвать охотника скверны без посторонней помощи.$B$BС этим тебе поможет Кром Крепкорук. Теперь он – главный чернокнижник, и целыми днями он сидит в библиотеке Стальгорна, оберегая древние тексты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кромом Крепкоруком в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фолиант Заговора? Хм-м... Знакомое название. Я его никогда не видел – а уж поверьте, я помню все прочитанные книги.$B$BХм…$B$BА, да! Я видел ссылки на этот фолиант в библиотечных каталогах.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1778,'Фолиант Божественности','Я намереваюсь скоро вернуться домой. Надеюсь, у Стефани в Штормграде дела идут хорошо. Не терпится снова увидеться с ней. До следующей встречи, |3-6($c).','Поговорите с Тизой Боевой Горн в Стальгорне.','Итак, ты быстро $Gвернулся:вернулась;, а? И чего же ты $Gдостиг:достигла; за это время?$B$BИтак, ты $Gпомог:помогла; достойному делу? Возможно ты уже $Gзаслужил:заслужила; уважение граждан Азерота. Скажи мне кому ты $Gпомог:помогла; – и я скажу кто ты…$B$BУдивительно, $N , ты действительно следуешь пути Света.$B$BТакая жертва будет обязательно вознаграждена в свое время..') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я намереваюсь скоро вернуться домой. Надеюсь, у Стефани в Штормграде дела идут хорошо. Не терпится снова увидеться с ней. До следующей встречи, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тизой Боевой Горн в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, ты быстро $Gвернулся:вернулась;, а? И чего же ты $Gдостиг:достигла; за это время?$B$BИтак, ты $Gпомог:помогла; достойному делу? Возможно ты уже $Gзаслужил:заслужила; уважение граждан Азерота. Скажи мне кому ты $Gпомог:помогла; – и я скажу кто ты…$B$BУдивительно, $N , ты действительно следуешь пути Света.$B$BТакая жертва будет обязательно вознаграждена в свое время..',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1779,'Фолиант Божественности','Я хочу, чтобы ты $Gвзял:взяла; это, $n. Это называется знак Жизни.$B$BТы $Gпоказал:показала; свое милосердие и терпение, а теперь я хочу, чтобы ты $Gпроявил:проявила; себя не только как воин, но и как $Gцелитель:целительница;.$B$BМой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Черного Железа. Он едва ноги унес – сейчас лечит свои раны у одного из наших жрецов.$B$BВозьми Символ и поговори с ним. Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор. Да пребудет с тобой Свет.','Возьмите знак Жизни и поговорите с Майридоном Боевым Горном в Стальгорне.','*кашляет*$B$BДоброго тебе здравия, |3-6($C). Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона. Так что сила твоего знака Жизни пока мне не нужна.$B$BЗначит, моя женушка тебя послала потолковать со мной, да? Славно, славно. У меня найдется времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы ты $Gвзял:взяла; это, $n. Это называется знак Жизни.$B$BТы $Gпоказал:показала; свое милосердие и терпение, а теперь я хочу, чтобы ты $Gпроявил:проявила; себя не только как воин, но и как $Gцелитель:целительница;.$B$BМой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Черного Железа. Он едва ноги унес – сейчас лечит свои раны у одного из наших жрецов.$B$BВозьми Символ и поговори с ним. Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор. Да пребудет с тобой Свет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите знак Жизни и поговорите с Майридоном Боевым Горном в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*кашляет*$B$BДоброго тебе здравия, |3-6($C). Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона. Так что сила твоего знака Жизни пока мне не нужна.$B$BЗначит, моя женушка тебя послала потолковать со мной, да? Славно, славно. У меня найдется времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1780,'Фолиант Божественности','Я сегодня же отнесу это детям. Ты можешь не тревожиться, |3-6($c). Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения $gдоказал:доказала;, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается.$B$BДоброго пути!','Найдите в Штормграде Даториана Ралла и поговорите с ним.','Ты уже здесь, $N? Однако, странствия заняли у тебя не так много времени, как я полагал. И что же тебе удалось свершить за время, проведенное вдали от Храма? Может быть, тебе довелось сражаться за справедливость? Или удалось постичь смысл милосердия? Или помочь кому-либо из нуждающихся жителей Азерота? Расскажи мне все...$B$BЧто ж, $N, это производит впечатление. Поверь, это поистине поступки того, кто следует путем Света и ставит благо других выше своего собственного.$B$BРано или поздно такое самопожертвование всегда вознаграждается.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сегодня же отнесу это детям. Ты можешь не тревожиться, |3-6($c). Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения $gдоказал:доказала;, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается.$B$BДоброго пути!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Штормграде Даториана Ралла и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты уже здесь, $N? Однако, странствия заняли у тебя не так много времени, как я полагал. И что же тебе удалось свершить за время, проведенное вдали от Храма? Может быть, тебе довелось сражаться за справедливость? Или удалось постичь смысл милосердия? Или помочь кому-либо из нуждающихся жителей Азерота? Расскажи мне все...$B$BЧто ж, $N, это производит впечатление. Поверь, это поистине поступки того, кто следует путем Света и ставит благо других выше своего собственного.$B$BРано или поздно такое самопожертвование всегда вознаграждается.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1781,'Фолиант Божественности','Прими этот знак Жизни, $n.$B$BТебе удалось обрести милосердие и терпение: пришло время узнать, хватит ли у тебя сил, чтобы воспользоваться одним из величайших даров Света. $B$BМой друг Газин недавно вернулся из Элвиннского леса с острова Героев, где он едва не расстался с жизнью после стычки с магами Братства Справедливости. Сейчас он у алтаря: надеюсь, служителям удастся исцелить его раны.$B$BВозьми этот Символ и поговори с Газином. Если сумеешь помочь ему, мы продолжим нашу беседу. Да пребудет с тобой извечный Свет!','Отнесите знак Жизни Газину Тенорму в Штормград.','*кашляет*$B$BЯ рад встрече с тобой, |3-6($C). Не обращай внимания на мои раны: добрые служители Света смогут обо всем позаботиться. Сила знака Жизни, которого ты держишь в руках, мне без надобности... по крайней мере пока.$B$BЗначит, Даториан послал тебя поговорить со мной, да? Что ж, это правильно. Я тебе расскажу, что случилось со мной и моим другом Хензом. Если нам повезет и тебе хватит сил и умения, ты еще сможешь всех нас спасти...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прими этот знак Жизни, $n.$B$BТебе удалось обрести милосердие и терпение: пришло время узнать, хватит ли у тебя сил, чтобы воспользоваться одним из величайших даров Света. $B$BМой друг Газин недавно вернулся из Элвиннского леса с острова Героев, где он едва не расстался с жизнью после стычки с магами Братства Справедливости. Сейчас он у алтаря: надеюсь, служителям удастся исцелить его раны.$B$BВозьми этот Символ и поговори с Газином. Если сумеешь помочь ему, мы продолжим нашу беседу. Да пребудет с тобой извечный Свет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите знак Жизни Газину Тенорму в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*кашляет*$B$BЯ рад встрече с тобой, |3-6($C). Не обращай внимания на мои раны: добрые служители Света смогут обо всем позаботиться. Сила знака Жизни, которого ты держишь в руках, мне без надобности... по крайней мере пока.$B$BЗначит, Даториан послал тебя поговорить со мной, да? Что ж, это правильно. Я тебе расскажу, что случилось со мной и моим другом Хензом. Если нам повезет и тебе хватит сил и умения, ты еще сможешь всех нас спасти...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1782,'Доспехи Фьюрена','Вот твои доспехи, $N. Они выдержат любой удар, не будь я Фьюрен Длиннобород!$B$BИ спасибо большое. Я многому научился, работая с принесенными тобой материалами. Думаю, в один прекрасный день я совершу новое открытие!$B$BА результаты этого я отправлю другим кузнецам Альянса.$B$BЯ скажу им, что ты мне очень $Gпомог:помогла;, может быть, они тоже решат отблагодарить тебя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доспехи Фьюрена',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот твои доспехи, $N. Они выдержат любой удар, не будь я Фьюрен Длиннобород!$B$BИ спасибо большое. Я многому научился, работая с принесенными тобой материалами. Думаю, в один прекрасный день я совершу новое открытие!$B$BА результаты этого я отправлю другим кузнецам Альянса.$B$BЯ скажу им, что ты мне очень $Gпомог:помогла;, может быть, они тоже решат отблагодарить тебя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1783,'Фолиант Божественности','Мы выслеживали дворфов Черного Железа, что окопались к югу от озера Хельмово Ложе. Мы знали, что они затевают недоброе, потому мы с Нармом решили подобраться поближе, чтобы посмотреть, как их капитан раздает приказы своим воинам.$B$BМы с Нармом воспользовались случаем и пристукнули нескольких, но они оказались крепче, чем мы думали, и набросились на нас толпой. Нарм велел мне бежать за помощью, и вот я здесь.$B$BНарму нужна помощь. И я не успокоюсь, пока он ее не получит.$B$BТы ведь поможешь ему, $n?','Возьмите знак Жизни и воскресите Нарма Фолка в Дун Мороге.','Не знаю, как мне отблагодарить тебя, $Gбрат:сестра;!$B$BВидать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни.$B$BДа, это правда, я пал в бою с дворфами Черного Железа, пытаясь получить одну из их бумаг. Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты $Gпоявился:появилась;. То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы выслеживали дворфов Черного Железа, что окопались к югу от озера Хельмово Ложе. Мы знали, что они затевают недоброе, потому мы с Нармом решили подобраться поближе, чтобы посмотреть, как их капитан раздает приказы своим воинам.$B$BМы с Нармом воспользовались случаем и пристукнули нескольких, но они оказались крепче, чем мы думали, и набросились на нас толпой. Нарм велел мне бежать за помощью, и вот я здесь.$B$BНарму нужна помощь. И я не успокоюсь, пока он ее не получит.$B$BТы ведь поможешь ему, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите знак Жизни и воскресите Нарма Фолка в Дун Мороге.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не знаю, как мне отблагодарить тебя, $Gбрат:сестра;!$B$BВидать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни.$B$BДа, это правда, я пал в бою с дворфами Черного Железа, пытаясь получить одну из их бумаг. Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты $Gпоявился:появилась;. То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1784,'Фолиант Божественности','Прежде чем я пал в бою, мы с Майридоном почти одолели одного из соглядатаев из клана Черного Железа возле того небольшого домика. Мы видели, как их капитан раздавал им бумаги с приказами, и хотели убить его и забрать эти бумаги.$B$BКое-кто в совете Стальгорна до сих пор не верит в присутствие дворфов Черного Железа в Дун Морог. Захватив одну из этих бумаг, мы не только получим доказательства их вылазок, но и поймем, что они затевают.$B$BДобудь один из приказов и отнеси Майридону, $n.','Добудьте послание дворфов Черного Железа возле Хельмова Ложа и вернитесь к Майридону Боевому Горну в Стальгорн.','Хаха! Тебе удалось! Ты $Gспас:спасла; Нарма и $Gнашел:нашла; доказательство, которое нужно моей жене, чтобы показать его в совете. Ты просто единственное благословление Света, если я в них хоть что-то понимаю... не считая, конечно, моей жены.$B$BПрими снова мою благодарность, $N.','Ты $Gвернулся:вернулась;! Я рада это видеть, $N. Мои раны зажили, и я почти готов вернуться на озеро Хельмова Ложе, как только не смогу убедить жену, что со мной все будет в порядке.','Вернитесь к Майридону Боевому Горну в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем я пал в бою, мы с Майридоном почти одолели одного из соглядатаев из клана Черного Железа возле того небольшого домика. Мы видели, как их капитан раздавал им бумаги с приказами, и хотели убить его и забрать эти бумаги.$B$BКое-кто в совете Стальгорна до сих пор не верит в присутствие дворфов Черного Железа в Дун Морог. Захватив одну из этих бумаг, мы не только получим доказательства их вылазок, но и поймем, что они затевают.$B$BДобудь один из приказов и отнеси Майридону, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте послание дворфов Черного Железа возле Хельмова Ложа и вернитесь к Майридону Боевому Горну в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хаха! Тебе удалось! Ты $Gспас:спасла; Нарма и $Gнашел:нашла; доказательство, которое нужно моей жене, чтобы показать его в совете. Ты просто единственное благословление Света, если я в них хоть что-то понимаю... не считая, конечно, моей жены.$B$BПрими снова мою благодарность, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;! Я рада это видеть, $N. Мои раны зажили, и я почти готов вернуться на озеро Хельмова Ложе, как только не смогу убедить жену, что со мной все будет в порядке.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Майридону Боевому Горну в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1785,'Фолиант Божественности','Вижу, моя женушка прямо пышет гордостью. Я бы на твоем месте поскакал прямо к ней. Сдается, она хочет перекинуться с тобой парой слов.$B$BДа хранит тебя Свет, $Gславный:славная:c; |3-6($c). Я буду искать тебя на боле боя против Плети и этой Черного Железа, когда придет пора.','Поговорите с Тизой Боевой Горн в Стальгорне.','Сегодня ты $Gоказал:оказала; большую услугу Стальгорну, $N. Я горда, что ты среди нас, и если ты $Gготов:готова;, я хотела бы благословить тебя этим свитком. Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни.$B$BЯ научу тебя возрождать к жизни твоих соратников. Используй это умение мудро, $N, и прими благодарность от меня, моего мужа и всего Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вижу, моя женушка прямо пышет гордостью. Я бы на твоем месте поскакал прямо к ней. Сдается, она хочет перекинуться с тобой парой слов.$B$BДа хранит тебя Свет, $Gславный:славная:c; |3-6($c). Я буду искать тебя на боле боя против Плети и этой Черного Железа, когда придет пора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тизой Боевой Горн в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодня ты $Gоказал:оказала; большую услугу Стальгорну, $N. Я горда, что ты среди нас, и если ты $Gготов:готова;, я хотела бы благословить тебя этим свитком. Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни.$B$BЯ научу тебя возрождать к жизни твоих соратников. Используй это умение мудро, $N, и прими благодарность от меня, моего мужа и всего Стальгорна.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1786,'Фолиант Божественности','Мы с Хензом добрались до острова Героев – он находится посреди Озера Каменных Столбов, в северо-восточной части Элвиннского леса. Мы слышали, что Братство Справедливости проникло в наши земли, и должны предоставить доказательства этого вторжения королевским советникам.$B$BМы засекли двоих из этих подонков, когда они просматривали кое-какие документы, и напали на них. Увы, магов было больше, и нас заставили отступить.$B$BХенз прикрывал меня, и мне удалось бежать... проклятый глупец, отвагу проявить решил!..$B$BИ вот он там так и остался. Хенз, я имею в виду. Может, ты сумеешь помочь, $n?','Возьмите знак Жизни, пойдите в Элвиннский лес и воскресите Хенза Фолка.','Прими мою благодарность, $Gбрат:сестра;.$B$BВ твоих руках я вижу знак Жизни – тебя послал Даториан или Газин.$B$BМы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи. Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побежден...$B$BНо тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, $N, можешь мне поверить. Это свидетельство крепости твоей веры...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с Хензом добрались до острова Героев – он находится посреди Озера Каменных Столбов, в северо-восточной части Элвиннского леса. Мы слышали, что Братство Справедливости проникло в наши земли, и должны предоставить доказательства этого вторжения королевским советникам.$B$BМы засекли двоих из этих подонков, когда они просматривали кое-какие документы, и напали на них. Увы, магов было больше, и нас заставили отступить.$B$BХенз прикрывал меня, и мне удалось бежать... проклятый глупец, отвагу проявить решил!..$B$BИ вот он там так и остался. Хенз, я имею в виду. Может, ты сумеешь помочь, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите знак Жизни, пойдите в Элвиннский лес и воскресите Хенза Фолка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прими мою благодарность, $Gбрат:сестра;.$B$BВ твоих руках я вижу знак Жизни – тебя послал Даториан или Газин.$B$BМы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи. Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побежден...$B$BНо тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, $N, можешь мне поверить. Это свидетельство крепости твоей веры...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1787,'Фолиант Божественности','У нас еще будет время поговорить о Символе. Сейчас важнее заполучить те бумаги, которые мы видели у Братства Справедливости. Если бумаги будут у нас, мы сможем доказать, что братство проникло в Элвиннский лес – а может, и узнать что-нибудь о его планах.$B$BУвы, $n, навряд ли я сейчас могу считаться воином. Сможешь ли ты пойти в бой в одиночку? Сумеешь ли ты добыть то, что нам так необходимо?$B$BЕсли это тебе удастся, отнеси бумаги Газину и сообщи ему, что со мной все хорошо.','Найдите волшебников из Братства Справедливости в Элвиннском лесу, заберите у них бумаги и отнести Газину Тенорму в Штормград.','Великолепно! Тебе удалось спасти Хенза и выполнить задание. Теперь я знаю: воистину, Свет озаряет твой путь, $N!','А, это ты, $N? С Хензом все в порядке? Тебе удалось добиться успеха?$B$BЯ вижу, острову Героев не страшно никакое братство, пока в твоих руках оружие, а с нами пребывает сила Света. Однако решение за королем и его советниками...','Вернитесь к Газину Тенорму в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас еще будет время поговорить о Символе. Сейчас важнее заполучить те бумаги, которые мы видели у Братства Справедливости. Если бумаги будут у нас, мы сможем доказать, что братство проникло в Элвиннский лес – а может, и узнать что-нибудь о его планах.$B$BУвы, $n, навряд ли я сейчас могу считаться воином. Сможешь ли ты пойти в бой в одиночку? Сумеешь ли ты добыть то, что нам так необходимо?$B$BЕсли это тебе удастся, отнеси бумаги Газину и сообщи ему, что со мной все хорошо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите волшебников из Братства Справедливости в Элвиннском лесу, заберите у них бумаги и отнести Газину Тенорму в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Тебе удалось спасти Хенза и выполнить задание. Теперь я знаю: воистину, Свет озаряет твой путь, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, это ты, $N? С Хензом все в порядке? Тебе удалось добиться успеха?$B$BЯ вижу, острову Героев не страшно никакое братство, пока в твоих руках оружие, а с нами пребывает сила Света. Однако решение за королем и его советниками...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Газину Тенорму в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1788,'Фолиант Божественности','После того как Даториан ознакомится с этими бумагами, я передам их королевским советникам; однако прежде тебе стоит поговорить с Даторианом. Думаю, он тоже хотел бы поблагодарить тебя.$B$BТвоя помощь поистине неоценима, $n. Надеюсь, это не последняя наша встреча. Я горжусь нашей дружбой.','Найдите в Штормграде Даториана Ралла и поговорите с ним.','Что ж, $N, полагаю, ты можешь гордиться своими свершениями.$B$BСкажу больше: ты можешь также гордиться своими способностями. Далеко не каждый может использовать силу, которой наделен знак Жизни. Если в твоих силах призвать исцеляющую силу Света, ты $Gдостоин:достойна; того, чтобы принять величайший дар паладинов, – дар воскрешения.$B$BТы сможешь возвращать к жизни павших спутников так же, как $Gвернул:вернула; к жизни Хенза.$B$BГорний Свет озарил тебя, $N, открой же ему душу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как Даториан ознакомится с этими бумагами, я передам их королевским советникам; однако прежде тебе стоит поговорить с Даторианом. Думаю, он тоже хотел бы поблагодарить тебя.$B$BТвоя помощь поистине неоценима, $n. Надеюсь, это не последняя наша встреча. Я горжусь нашей дружбой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Штормграде Даториана Ралла и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, $N, полагаю, ты можешь гордиться своими свершениями.$B$BСкажу больше: ты можешь также гордиться своими способностями. Далеко не каждый может использовать силу, которой наделен знак Жизни. Если в твоих силах призвать исцеляющую силу Света, ты $Gдостоин:достойна; того, чтобы принять величайший дар паладинов, – дар воскрешения.$B$BТы сможешь возвращать к жизни павших спутников так же, как $Gвернул:вернула; к жизни Хенза.$B$BГорний Свет озарил тебя, $N, открой же ему душу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1789,'Знак Жизни','Поспеши, $N, еще одна жизнь висит на волоске.$B$BЕсли по каким-то причинам тебе не удастся спасти Майридона и Нарма, возвращайся ко мне, и дам тебе еще один символ Жизни.$B$BНе путай мою помощь с благотворительностью, тебе нужно доказать, что ты достойный |3-6($C) и отказ, может отразиться в будущем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак Жизни',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поспеши, $N, еще одна жизнь висит на волоске.$B$BЕсли по каким-то причинам тебе не удастся спасти Майридона и Нарма, возвращайся ко мне, и дам тебе еще один символ Жизни.$B$BНе путай мою помощь с благотворительностью, тебе нужно доказать, что ты достойный |3-6($C) и отказ, может отразиться в будущем.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1790,'Знак Жизни','Поспеши, $N! Слишком много жизней зависит от твоего успеха или неудачи.$B$BЕсли ты не сумеешь помочь Газину и Хензу, возвращайся: я дам тебе новый знак Жизни.$B$BНе думай, что я помогаю тебе просто так, нет: тебе, как и всякому другому паладину, нужно доказать, что ты достоин своего звания. Постоянные неудачи – не лучшая рекомендация...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак Жизни',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поспеши, $N! Слишком много жизней зависит от твоего успеха или неудачи.$B$BЕсли ты не сумеешь помочь Газину и Хензу, возвращайся: я дам тебе новый знак Жизни.$B$BНе думай, что я помогаю тебе просто так, нет: тебе, как и всякому другому паладину, нужно доказать, что ты достоин своего звания. Постоянные неудачи – не лучшая рекомендация...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1791,'Страж Ветра','Что ж, ты $gосвоил:освоила; стойку берсерка, теперь нужно подобрать тебе оружие.$b$bПоговори с Бат\'ра Стражем Ветра, троллем-отшельником, живущим между Альтеракскими горами и Западными Чумными землями. Он опытный оружейник и могущественный шаман.$b$bЕсли ты захочешь встретиться с Бат\'рой, отправляйся к реке, что течет вдоль восточного края Мельницы Таррен. Иди вдоль нее на север – Бат\'ра разбил лагерь рядом с руинами на берегу реки.','Поговорите с Бат\'ра Стражем Ветра.','Тебе пришлось проделать долгий путь, $юный:юная $C. Как у тебя горят глаза! Тебе ведь нужно мощное оружие?$B$BЯ помогу тебе... в обмен на твою помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страж Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, ты $gосвоил:освоила; стойку берсерка, теперь нужно подобрать тебе оружие.$b$bПоговори с Бат\'ра Стражем Ветра, троллем-отшельником, живущим между Альтеракскими горами и Западными Чумными землями. Он опытный оружейник и могущественный шаман.$b$bЕсли ты захочешь встретиться с Бат\'рой, отправляйся к реке, что течет вдоль восточного края Мельницы Таррен. Иди вдоль нее на север – Бат\'ра разбил лагерь рядом с руинами на берегу реки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бат\'ра Стражем Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе пришлось проделать долгий путь, $юный:юная $C. Как у тебя горят глаза! Тебе ведь нужно мощное оружие?$B$BЯ помогу тебе... в обмен на твою помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1792,'Оружие вихря','У меня есть сердце Вихря, и я могу подобрать ему вместилище по твоему выбору.$B$BВозьми любое оружие, и знай, что его сила – сила Циклониана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие вихря',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У меня есть сердце Вихря, и я могу подобрать ему вместилище по твоему выбору.$B$BВозьми любое оружие, и знай, что его сила – сила Циклониана.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1793,'Фолиант Отваги','Теперь доказано, что ты – приверженец сил Света, $N, но времена наступают все более опасные, и поэтому важно знать, какая сила скрывается в твоем сердце. Когда демоны, драконы или какое другое зло ступят на нашу землю, тогда и подвергнется испытанию твой дух. Достанет ли у тебя сил?$B$BХрабрость в любой ситуации – такая же неотъемлемая часть сущности паладина, как Свет, доспех и оружие. Необходимость защищать слабых и не терять веры – вот еще два урока, которые ты $Gдолжен:должна; усвоить, пока проходишь обучение в Соборе Света.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Отваги',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь доказано, что ты – приверженец сил Света, $N, но времена наступают все более опасные, и поэтому важно знать, какая сила скрывается в твоем сердце. Когда демоны, драконы или какое другое зло ступят на нашу землю, тогда и подвергнется испытанию твой дух. Достанет ли у тебя сил?$B$BХрабрость в любой ситуации – такая же неотъемлемая часть сущности паладина, как Свет, доспех и оружие. Необходимость защищать слабых и не терять веры – вот еще два урока, которые ты $Gдолжен:должна; усвоить, пока проходишь обучение в Соборе Света.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (1794,'Фолиант Отваги') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Отваги',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1795,'Оковы','Если ты $gготов:готова;, давай приступим. Начну с объяснений.$B$BСначала мы создадим основной круг призыва. После этого мои послушники создадут больший круг при помощи жезлов направления.$B$BЗатем ты прочтешь заклинание из фолианта заговора, и на зов явится охотник скверны. Будь $gосторожен:осторожна;, $n. Охотник скверны – сильный враг, не теряй головы.','Призовите и одолейте охотника скверны при помощи фолианта заговора и верните фолиант Страхаду Фарсану из Кабестана.','Впечатляюще, $N. Когда я сражался с охотником скверны, то едва выжил. Предчувствую, что ты станешь одним из сильнейших чернокнижников нашей эры.','Каждый $C должен иметь в своем распоряжении охотника скверны. Хотя их сложно приручить, обретенное могущество стоит затраченных усилий.','Вернитесь к Страхаду Фарсану в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оковы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты $gготов:готова;, давай приступим. Начну с объяснений.$B$BСначала мы создадим основной круг призыва. После этого мои послушники создадут больший круг при помощи жезлов направления.$B$BЗатем ты прочтешь заклинание из фолианта заговора, и на зов явится охотник скверны. Будь $gосторожен:осторожна;, $n. Охотник скверны – сильный враг, не теряй головы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите и одолейте охотника скверны при помощи фолианта заговора и верните фолиант Страхаду Фарсану из Кабестана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляюще, $N. Когда я сражался с охотником скверны, то едва выжил. Предчувствую, что ты станешь одним из сильнейших чернокнижников нашей эры.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Каждый $C должен иметь в своем распоряжении охотника скверны. Хотя их сложно приручить, обретенное могущество стоит затраченных усилий.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Страхаду Фарсану в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (1796,'Материалы для зачарованного золотого кровавого одеяния','Первым делом я помогу тебе создать одеяние. Ты принесешь мне несколько необходимых составляющих, а уж работать над ними будем вместе. В итоге, если ты справишься, разумеется, ты получишь первый из многих предметов, которые одарят тебя могуществом и помогут в борьбе против сил Тьмы.$B$BДля начала тебе нужны одеяния Тайны. Их может сшить портной или их можно купить... еще лучше сделать их самому, но это сложно. Короче, для начала принеси мне эти одеяния.','Принесите одеяния Тайны Менаре Расщепительнице Бездны в Степи.','Вернитесь к Менаре Расщепительнице Бездны в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Материалы для зачарованного золотого кровавого одеяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первым делом я помогу тебе создать одеяние. Ты принесешь мне несколько необходимых составляющих, а уж работать над ними будем вместе. В итоге, если ты справишься, разумеется, ты получишь первый из многих предметов, которые одарят тебя могуществом и помогут в борьбе против сил Тьмы.$B$BДля начала тебе нужны одеяния Тайны. Их может сшить портной или их можно купить... еще лучше сделать их самому, но это сложно. Короче, для начала принеси мне эти одеяния.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите одеяния Тайны Менаре Расщепительнице Бездны в Степи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менаре Расщепительнице Бездны в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1798,'В поисках Страхада','Пришло время научить тебя вызывать охотника скверны, $n. Здесь у меня нет ни реагентов, ни предметов, необходимых для обучения, так что придется тебе найти другого учителя – Страхада Фарсана.$b$bОн проживает в гоблинском порту Кабестане. Я извещу его о том, что ты появишься.','Поговорите со Страхадом Фарсаном в Степях.','$N? Ах да, конечно. Наше новое чудо. Но, боюсь, настоящее чудо вряд ли успеет стать легендой при жизни.$B$BВпрочем, неважно – ты здесь для того, чтобы пройти обучение, а не слушать, как я шучу сам с собой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Страхада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время научить тебя вызывать охотника скверны, $n. Здесь у меня нет ни реагентов, ни предметов, необходимых для обучения, так что придется тебе найти другого учителя – Страхада Фарсана.$b$bОн проживает в гоблинском порту Кабестане. Я извещу его о том, что ты появишься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со Страхадом Фарсаном в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N? Ах да, конечно. Наше новое чудо. Но, боюсь, настоящее чудо вряд ли успеет стать легендой при жизни.$B$BВпрочем, неважно – ты здесь для того, чтобы пройти обучение, а не слушать, как я шучу сам с собой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (1799,'Части шара Орахила','Отлично, приступим.$B$BПервым делом ступай внутрь и поговори с моими послушниками. Тебе предстоит избрать свой путь – они объяснят подробнее.$B$BПотом придется отправиться в Пустоши и отыскать сферу Подземного огня у одного из чернокнижников Поля Маннорок. Именно эту сферу необходимо очистить при помощи мага по имени Табета в южной части Пылевых топей. Она поможет тебе ради меня.$B$BИ не возвращайся, пока не выполнишь оба задания.','Поговорите с послушниками Менары в башне над Кабестаном и изберите свой путь.$B$BПосле этого принесите Табете в Пылевые топи сферу Подземного огня.','А, так тебя послала Менара. Ну, хорошо... Располагайся, чувствуй себя как дома. Впрочем, ты, должно быть, спешишь? Быть может, ищешь утраченную силу? Может, я ошибаюсь, и скверна все же коснулась тебя.','Вернитесь к Табете на Трясину, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Части шара Орахила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично, приступим.$B$BПервым делом ступай внутрь и поговори с моими послушниками. Тебе предстоит избрать свой путь – они объяснят подробнее.$B$BПотом придется отправиться в Пустоши и отыскать сферу Подземного огня у одного из чернокнижников Поля Маннорок. Именно эту сферу необходимо очистить при помощи мага по имени Табета в южной части Пылевых топей. Она поможет тебе ради меня.$B$BИ не возвращайся, пока не выполнишь оба задания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с послушниками Менары в башне над Кабестаном и изберите свой путь.$B$BПосле этого принесите Табете в Пылевые топи сферу Подземного огня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, так тебя послала Менара. Ну, хорошо... Располагайся, чувствуй себя как дома. Впрочем, ты, должно быть, спешишь? Быть может, ищешь утраченную силу? Может, я ошибаюсь, и скверна все же коснулась тебя.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на Трясину, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1800,'Тронный зал Лордерона','Если мы хорошо себя ведем, то попечительницы сирот рассказывают нам на ночь сказки про славные сражения и про мирные времена. В одной из легенд говорилось о том, как пал Лордерон и как злобный Артас убил своего отца, чтобы захватить трон.$b$bКакой злодей! Когда я вырасту и стану великим воином Орды, я никогда не буду делать зла!$b$bЯ хочу посмотреть на его тронный зал! Он находится как раз перед входом в Подгород.','Отведите своего подопечного в старый тронный зал Лордерона, который находится как раз у входа в Подгород.','Эта тронная комната наводит ужас, $N! Хоть даже она и пуста, но в этих стенах чувствуется, что великое зло. Я чувствую гнев... но также и горечь. Я понимаю, почему няньки рассказывают нам подобные истории; я никогда не предам свой народ подобным образом!$B$BБлагодарю тебя за то, что ты $Gпроводил:проводила; меня в тронную комнату, $N. Я многому научился здесь.','Мы уже на месте?','Отправляйтесь в тронный зал Лордерона, который находится у входа в Подгород.','Поговорите со своим подопечным орком-сиротой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тронный зал Лордерона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы хорошо себя ведем, то попечительницы сирот рассказывают нам на ночь сказки про славные сражения и про мирные времена. В одной из легенд говорилось о том, как пал Лордерон и как злобный Артас убил своего отца, чтобы захватить трон.$b$bКакой злодей! Когда я вырасту и стану великим воином Орды, я никогда не буду делать зла!$b$bЯ хочу посмотреть на его тронный зал! Он находится как раз перед входом в Подгород.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите своего подопечного в старый тронный зал Лордерона, который находится как раз у входа в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта тронная комната наводит ужас, $N! Хоть даже она и пуста, но в этих стенах чувствуется, что великое зло. Я чувствую гнев... но также и горечь. Я понимаю, почему няньки рассказывают нам подобные истории; я никогда не предам свой народ подобным образом!$B$BБлагодарю тебя за то, что ты $Gпроводил:проводила; меня в тронную комнату, $N. Я многому научился здесь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы уже на месте?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправляйтесь в тронный зал Лордерона, который находится у входа в Подгород.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите со своим подопечным орком-сиротой.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1801,'Фолиант заговора','Простой круг призыва не поможет тебе вызвать на бой охотника Скверны.$B$BЯ и трое моих послушников поможем тебе создать магические круги. Тебе также понадобится фолиант заговора, который мы давно утратили. Его написала первая группа чернокнижников, умудрившихся вызвать охотника Скверны без посторонней помощи.$B$BС этим тебе поможет Йорах Аннисон. Он работает в Подгороде картографом, но все равно знает о древних текстах куда больше моего.','Поговорите с Джорахом Аннисоном в Подгороде.','Картография! Картинки, далекие от реальности. Они мне не нужны. \n\nКниги – повествование, описание! В них и только в них следует искать правду. Я обменял бы все свои карты на одну книгу о возвышении некромантии или сагу о торжестве Темной Госпожи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант заговора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Простой круг призыва не поможет тебе вызвать на бой охотника Скверны.$B$BЯ и трое моих послушников поможем тебе создать магические круги. Тебе также понадобится фолиант заговора, который мы давно утратили. Его написала первая группа чернокнижников, умудрившихся вызвать охотника Скверны без посторонней помощи.$B$BС этим тебе поможет Йорах Аннисон. Он работает в Подгороде картографом, но все равно знает о древних текстах куда больше моего.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джорахом Аннисоном в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Картография! Картинки, далекие от реальности. Они мне не нужны. \n\nКниги – повествование, описание! В них и только в них следует искать правду. Я обменял бы все свои карты на одну книгу о возвышении некромантии или сагу о торжестве Темной Госпожи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1802,'Фолиант заговора','Он был утрачен, но есть кое-какие соображения насчет того, где он может находиться сейчас.$b$bС него сделали только одну копию и отнеслись к ней совершенно по-варварски: большая часть книги была вырвана из переплета. Ходят слухи, что она каким-то образом попала в руки одного кентавра из Тысячи Игл.$b$bОстальное было утрачено в прибрежных краях к западу от Южнобережья, откуда книгу должны были переправить морем в Гавань Менетилов. Судно так и не прибыло.$b$bА за мои сведения я попрошу одно: когда найдешь книгу, дай мне заглянуть в нее хотя бы одним глазком.','Добудьте заплесневелый фолиант и потрепанный манускрипт для Крома Крепкорука из Стальгорна.','С ума сойти! Теперь я один из немногих, что сумел хоть мельком заглянуть в нее.$B$BНе терпится повнимательнее изучить этот текст. Какой великий день, $N! Позволь мне еще раз заглянуть в нее прежде, чем уйдешь. Уверен, что Страхад охотно пришлет мне копию.','Так слухи оказались верны, $N?','Вернитесь к Крому Крепкоруку в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант заговора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Он был утрачен, но есть кое-какие соображения насчет того, где он может находиться сейчас.$b$bС него сделали только одну копию и отнеслись к ней совершенно по-варварски: большая часть книги была вырвана из переплета. Ходят слухи, что она каким-то образом попала в руки одного кентавра из Тысячи Игл.$b$bОстальное было утрачено в прибрежных краях к западу от Южнобережья, откуда книгу должны были переправить морем в Гавань Менетилов. Судно так и не прибыло.$b$bА за мои сведения я попрошу одно: когда найдешь книгу, дай мне заглянуть в нее хотя бы одним глазком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте заплесневелый фолиант и потрепанный манускрипт для Крома Крепкорука из Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С ума сойти! Теперь я один из немногих, что сумел хоть мельком заглянуть в нее.$B$BНе терпится повнимательнее изучить этот текст. Какой великий день, $N! Позволь мне еще раз заглянуть в нее прежде, чем уйдешь. Уверен, что Страхад охотно пришлет мне копию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так слухи оказались верны, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крому Крепкоруку в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1803,'Фолиант заговора','А! Вижу, наши вкусы сходятся. Поиски фолианта заговора – достойное занятие. Знаешь ли ты, что он некогда хранился в стенах Лордерона? Правда, эти варвары поглумились над ним, вырвали больше половины страниц. Кто мог совершить такую мерзость?$b$bИтак, половина потеряна, хотя говорят, будто она попала в руки кентавров из Тысячи Игл.$b$bОстальную часть должны были перевезти в Стальгорн, но она потерялась при перевозке где-то на берегу моря к западу от Южнобережья.','Отыщите заплесневелый фолиант и потрепанный манускрипт для Йораха Аннисона из Подгорода.','Может быть, фолиант Заговора и упоминался в сказках, но даже в самых невероятных историях есть доля правды.','Вернитесь к Йораху Аннисону в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант заговора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А! Вижу, наши вкусы сходятся. Поиски фолианта заговора – достойное занятие. Знаешь ли ты, что он некогда хранился в стенах Лордерона? Правда, эти варвары поглумились над ним, вырвали больше половины страниц. Кто мог совершить такую мерзость?$b$bИтак, половина потеряна, хотя говорят, будто она попала в руки кентавров из Тысячи Игл.$b$bОстальную часть должны были перевезти в Стальгорн, но она потерялась при перевозке где-то на берегу моря к западу от Южнобережья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите заплесневелый фолиант и потрепанный манускрипт для Йораха Аннисона из Подгорода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Может быть, фолиант Заговора и упоминался в сказках, но даже в самых невероятных историях есть доля правды.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йораху Аннисону в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1804,'Фолиант заговора','Как же не хочется его выпускать из рук! Но он – твоя находка, и ты, конечно же, свершишь при его помощи куда более важные дела. Только, сделай милость, не забудь сказать Страхаду, что я хочу получить копию.$b$bПока тебя не было, он прислал для тебя письмо. Он пишет, что для призыва духов необходимо достать три жезла направления.$b$bОн-то не знает, где их искать, но зато я знаю! Последний раз их использовали орки клана Драконьей Пасти в Болотине. Я бы поискал у их заклинателей!','Принесите восстановленный Фолиант Заговора и три жезла направления Страхаду Фарсану в Кабестан.','Отлично! Фолиант Заговора и три практически нетронутых жезла направления.$B$BЗабавно выходит. Давно молодые чернокнижники не приручали охотников Скверны.','Давно не видел тебя здесь. Ты нашел фолиант и жезлы?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант заговора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как же не хочется его выпускать из рук! Но он – твоя находка, и ты, конечно же, свершишь при его помощи куда более важные дела. Только, сделай милость, не забудь сказать Страхаду, что я хочу получить копию.$b$bПока тебя не было, он прислал для тебя письмо. Он пишет, что для призыва духов необходимо достать три жезла направления.$b$bОн-то не знает, где их искать, но зато я знаю! Последний раз их использовали орки клана Драконьей Пасти в Болотине. Я бы поискал у их заклинателей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите восстановленный Фолиант Заговора и три жезла направления Страхаду Фарсану в Кабестан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Фолиант Заговора и три практически нетронутых жезла направления.$B$BЗабавно выходит. Давно молодые чернокнижники не приручали охотников Скверны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Давно не видел тебя здесь. Ты нашел фолиант и жезлы?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1805,'Фолиант заговора','Это один из самых интересных текстов, что мне приходилось изучать за последние несколько лет. Выбор здесь небогат – большинство книг посвящено географии, и я все до дыр зачитал. Надеюсь, Страхад пришлет мне копию.$b$bКстати, он прислал весточку, пока тебя не было. Чтобы выполнить очередную задачу, тебе понадобится три жезла направления.$b$bВ благодарность за то, что ты $gдал:дала; мне взглянуть на этот текст, открою тайну: жезлы можно найти у орков клана Драконьей Пасти в Болотине.','Принесите восстановленный фолиант и три жезла направления Страхаду Фарсану в Кабестан.','Отлично! Фолиант Заговора и три практически нетронутых жезла направления.$B$BЗабавно выходит. Давно молодые чернокнижники не приручали охотников Скверны.','Да, $N? Чем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант заговора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это один из самых интересных текстов, что мне приходилось изучать за последние несколько лет. Выбор здесь небогат – большинство книг посвящено географии, и я все до дыр зачитал. Надеюсь, Страхад пришлет мне копию.$b$bКстати, он прислал весточку, пока тебя не было. Чтобы выполнить очередную задачу, тебе понадобится три жезла направления.$b$bВ благодарность за то, что ты $gдал:дала; мне взглянуть на этот текст, открою тайну: жезлы можно найти у орков клана Драконьей Пасти в Болотине.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите восстановленный фолиант и три жезла направления Страхаду Фарсану в Кабестан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Фолиант Заговора и три практически нетронутых жезла направления.$B$BЗабавно выходит. Давно молодые чернокнижники не приручали охотников Скверны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N? Чем я могу тебе помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1806,'Испытание доблести','Почему бы нам не пойти прямо в кузню и не начать работу? Я уже ждал тебя и подготовился, так что времени это много не займет.$B$BКогда все будет закончено, ты будешь гораздо лучше $Gподготовлен:подготовлена; к защите дела Света, уж за это я ручаюсь.$B$BНе утаю, $n, я даже немного завидую твоим деяниям. Но осознание того, что я по-своему помогу тебе, и немало помогу, все же радует меня.','Подождите, пока Джордан Стилвелл не закончит изготовление оружия.','Вот оно, $n. Оружие, достойное защитника Света вроде тебя. Я дал ему имя в честь великого дворфского паладина, моего друга. Его звали Вериган... Бош Вериган. Прошу, прими его в благодарность от меня и моей жены. Мы очень обязаны тебе. Мир станет лучше, если по земле ходят такие, как ты!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание доблести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Почему бы нам не пойти прямо в кузню и не начать работу? Я уже ждал тебя и подготовился, так что времени это много не займет.$B$BКогда все будет закончено, ты будешь гораздо лучше $Gподготовлен:подготовлена; к защите дела Света, уж за это я ручаюсь.$B$BНе утаю, $n, я даже немного завидую твоим деяниям. Но осознание того, что я по-своему помогу тебе, и немало помогу, все же радует меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подождите, пока Джордан Стилвелл не закончит изготовление оружия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот оно, $n. Оружие, достойное защитника Света вроде тебя. Я дал ему имя в честь великого дворфского паладина, моего друга. Его звали Вериган... Бош Вериган. Прошу, прими его в благодарность от меня и моей жены. Мы очень обязаны тебе. Мир станет лучше, если по земле ходят такие, как ты!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1818,'Разговор с Диллинджером','Мне сказали, что у стража смерти Диллинджера есть работа для таких, как ты. Если ты хочешь доказать свою ценность Темной Госпоже, немедленно отправляйся к нему.$b$bСтраж смерти Диллинджер стоит на посту в западном конце Брилла, рядом с кладбищем.','Поговорите со стражем смерти Диллинджером в Брилле.','Ты хочешь получить задание? Отлично. У меня есть одно. Довольно важное. Заодно и свою силу нам покажешь... И решимость защищать дело Отрекшихся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Диллинджером',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне сказали, что у стража смерти Диллинджера есть работа для таких, как ты. Если ты хочешь доказать свою ценность Темной Госпоже, немедленно отправляйся к нему.$b$bСтраж смерти Диллинджер стоит на посту в западном конце Брилла, рядом с кладбищем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со стражем смерти Диллинджером в Брилле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хочешь получить задание? Отлично. У меня есть одно. Довольно важное. Заодно и свою силу нам покажешь... И решимость защищать дело Отрекшихся.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1819,'Улаг Колун','Когда Тирисфальские леса наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению. Он обладал свободной волей и звал себя Улаг Колун. Впрочем, несмотря на свободу воли, его подчинил себе Король-лич.$b$bМы надеялись избавить Улага от чар, но не смогли. Довольно ему томиться в темнице плоти. Освободи его.$b$bДля этого его придется убить.$b$bВоспользуйся переключателем в мавзолее к северу отсюда. Это позволит снять с Улага магические путы.$b$bСними их и... будь $gготов:готова;!','Убейте Улага Колуна и поговорите со стражем смерти Диллинджером.','Молодец, $N. Улаг был серьезным сторонником Плети. Тебе удалось доказать стражам смерти и через них Темной Госпоже, что ты опытный и умелый воин и заслуживаешь дальнейшего обучения.','Твоя задача еще не выполнена, $N. $C не должен показывать страх...','Вернитесь к стражу смерти Диллинжеру в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Улаг Колун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Тирисфальские леса наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению. Он обладал свободной волей и звал себя Улаг Колун. Впрочем, несмотря на свободу воли, его подчинил себе Король-лич.$b$bМы надеялись избавить Улага от чар, но не смогли. Довольно ему томиться в темнице плоти. Освободи его.$b$bДля этого его придется убить.$b$bВоспользуйся переключателем в мавзолее к северу отсюда. Это позволит снять с Улага магические путы.$b$bСними их и... будь $gготов:готова;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Улага Колуна и поговорите со стражем смерти Диллинджером.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $N. Улаг был серьезным сторонником Плети. Тебе удалось доказать стражам смерти и через них Темной Госпоже, что ты опытный и умелый воин и заслуживаешь дальнейшего обучения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твоя задача еще не выполнена, $N. $C не должен показывать страх...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Диллинжеру в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1820,'Разговор с Колманом','Тебе удалось услужить Темной Госпоже, пришло время услужить одному из ее подданных.$B$BКолману Фартингу нужен воин, который сможет отомстить врагам Отрекшихся.$b$bКоулман сидит в таверне "Петля висельника", в восточной части Брилла.','Поговорите с Колманом Фартингом.','Да, это правда. Мне нужна помощь закаленного воина. Средств у меня немного, зато ты послужишь не только мне, но и делу Отрекшихся. Так что если ты справишься, наградой будет почет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Колманом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось услужить Темной Госпоже, пришло время услужить одному из ее подданных.$B$BКолману Фартингу нужен воин, который сможет отомстить врагам Отрекшихся.$b$bКоулман сидит в таверне "Петля висельника", в восточной части Брилла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Колманом Фартингом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это правда. Мне нужна помощь закаленного воина. Средств у меня немного, зато ты послужишь не только мне, но и делу Отрекшихся. Так что если ты справишься, наградой будет почет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1821,'Наследие Агамондов','При жизни я служил семье Агамондов, и именно из-за них и умер! Поделом им, они стали теперь безмозглыми прислужниками Короля-лича.$b$bМне же хочется лишить их остатков чести. Ступай в Семейную усыпальницу Агамондов и принеси их фамильное оружие: меч, топор, кинжал и палицу.$B$BСклеп находится на севере, позади Мельниц Агамондов. Его стерегут бойцы Плети и сами неупокоенные хозяева.','Принесите Колману Фартингу фамильный топор Агамондов, фамильный меч Агамондов, фамильную палицу Агамондов, фамильный кинжал Агамондов.','А! Вот оно! Итак, проклятые земли Агамондов лишены остатков чести и памяти. Отныне семьи воистину не существует!','Тебе удалось принести фамильное оружие?','Вернитесь к Колману Фартингу в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Агамондов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При жизни я служил семье Агамондов, и именно из-за них и умер! Поделом им, они стали теперь безмозглыми прислужниками Короля-лича.$b$bМне же хочется лишить их остатков чести. Ступай в Семейную усыпальницу Агамондов и принеси их фамильное оружие: меч, топор, кинжал и палицу.$B$BСклеп находится на севере, позади Мельниц Агамондов. Его стерегут бойцы Плети и сами неупокоенные хозяева.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Колману Фартингу фамильный топор Агамондов, фамильный меч Агамондов, фамильную палицу Агамондов, фамильный кинжал Агамондов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А! Вот оно! Итак, проклятые земли Агамондов лишены остатков чести и памяти. Отныне семьи воистину не существует!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось принести фамильное оружие?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колману Фартингу в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1822,'Фамильное оружие','Я оставлю принесенное тобой оружие на память о понесенных потерях. Впрочем, ты можешь выбрать наиболее полюбившуюся тебе вещь и оставить ее себе.$B$BДа послужит она тебе лучше, чем прежним проклятым владельцами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фамильное оружие',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я оставлю принесенное тобой оружие на память о понесенных потерях. Впрочем, ты можешь выбрать наиболее полюбившуюся тебе вещь и оставить ее себе.$B$BДа послужит она тебе лучше, чем прежним проклятым владельцами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1823,'Разговор с Ругой','Ты уже опытный воин, и имя твое на слуху у многих. Может быть, ты хочешь пройти испытание Руги Тотема Ярости? Коли так, отправляйся в Лагерь Таурахо, в Степи.$b$bОн ждет всех воинов, что готовы принять его вызов.','Поговорите с Ругой Тотемом Ярости.','Ты хочешь пройти испытание, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Ругой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже опытный воин, и имя твое на слуху у многих. Может быть, ты хочешь пройти испытание Руги Тотема Ярости? Коли так, отправляйся в Лагерь Таурахо, в Степи.$b$bОн ждет всех воинов, что готовы принять его вызов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ругой Тотемом Ярости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хочешь пройти испытание, $N?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1824,'Испытание на Полях Великанов','Чтобы пройти это испытание, тебе придется отправиться на юг, к Полям Великанов. Там ты встретишь полчища ползучих существ, похожих на насекомых. Они явились в Степи незваными, и мне они совсем не нравятся.$b$bПринеси их усики. Главное, чтобы они все еще дергались, поэтому тебе придется поторопиться. Добудь мне усики за отведенное время, и я сочту, что испытание пройдено.','Принесите 5 дергающихся усиков Руге Тотему Ярости в Лагерь Таурахо.','Отличная работа, $N! Ты $Gпрошел:прошла; испытание на Полях Великанов, сделав тем самым еще один шаг по тропе воина.','Ну как, усики у тебя? Коли так, давай их скорее сюда, а то они скоро перестанут дергаться...','Вернитесь к Руге Тотему Ярости в лагерь Таурахо, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание на Полях Великанов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы пройти это испытание, тебе придется отправиться на юг, к Полям Великанов. Там ты встретишь полчища ползучих существ, похожих на насекомых. Они явились в Степи незваными, и мне они совсем не нравятся.$b$bПринеси их усики. Главное, чтобы они все еще дергались, поэтому тебе придется поторопиться. Добудь мне усики за отведенное время, и я сочту, что испытание пройдено.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 дергающихся усиков Руге Тотему Ярости в Лагерь Таурахо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N! Ты $Gпрошел:прошла; испытание на Полях Великанов, сделав тем самым еще один шаг по тропе воина.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, усики у тебя? Коли так, давай их скорее сюда, а то они скоро перестанут дергаться...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руге Тотему Ярости в лагерь Таурахо, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1825,'Разговор с Тун\'гримом','Слухи о твоих доблестных подвигах во славу Орды дошли до знаменитого орочьего кузнеца, Тун\'грима Огневзора. Он хотел бы сделать для тебя доспехи, но тебе надо как можно скорее с ним встретиться.$b$bТун\'грим живет на востоке от Перекрестка, что в Степях.','Поговорите с Тун\'гримом Огневзором из Степей.','Да, ты $Gпришел:пришла;. Отлично, нам с тобой многое придется обсудить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Тун\'гримом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слухи о твоих доблестных подвигах во славу Орды дошли до знаменитого орочьего кузнеца, Тун\'грима Огневзора. Он хотел бы сделать для тебя доспехи, но тебе надо как можно скорее с ним встретиться.$b$bТун\'грим живет на востоке от Перекрестка, что в Степях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тун\'гримом Огневзором из Степей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, ты $Gпришел:пришла;. Отлично, нам с тобой многое придется обсудить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1838,'Доспехи Жестокости','Я наслышан о твоей силе и доблести и хочу сделать для тебя броню, которая охранит тебя в бесчисленных сражениях.$b$bВпрочем, создание такой брони – само по себе подвиг. Мне понадобится твоя помощь, а также помощь других кузнецов Орды.$b$bВозьми этот список. Я составлял его не одну ночь, напряженно вглядываясь в пергамент почти незрячими глазами. Принеси мне все перечисленное, и я создам тебе первую часть доспеха.','Принесите Тун\'гриму Огневзору 15 закопченных железных слитков, 10 мер толченого азурита, 10 железных слитков и сосуд флогистона.','Ты $Gпринес:принесла; все, что я просил. Теперь дело за мной...','Ты все предметы из списка принес, $N?','Вернитесь к Тунгриму Огневзору на Тернистый холм, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доспехи Жестокости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я наслышан о твоей силе и доблести и хочу сделать для тебя броню, которая охранит тебя в бесчисленных сражениях.$b$bВпрочем, создание такой брони – само по себе подвиг. Мне понадобится твоя помощь, а также помощь других кузнецов Орды.$b$bВозьми этот список. Я составлял его не одну ночь, напряженно вглядываясь в пергамент почти незрячими глазами. Принеси мне все перечисленное, и я создам тебе первую часть доспеха.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Тун\'гриму Огневзору 15 закопченных железных слитков, 10 мер толченого азурита, 10 железных слитков и сосуд флогистона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпринес:принесла; все, что я просил. Теперь дело за мной...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты все предметы из списка принес, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тунгриму Огневзору на Тернистый холм, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1839,'Ула\'елек и рукавицы Жестокости','Кузнец-тролль по имени Ула\'елек готов выковать для тебя рукавицы Жестокости. Он живет в Дуротаре, в деревне Сен\'джин, вместе со своими собратьями из племени Черного Копья, и с нетерпением ждет твоего прихода.','Поговорите с Ула\'елеком из Дуротара.','Привет тебе, $N. Старый Тунгрим предупредил меня о твоем приходе, но умолчи он, я не удивился бы твоему появлению.$B$BДухи следят за каждым твоим шагом, юный воин, и они говорят, что от твоей руки пало немало врагов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ула\'елек и рукавицы Жестокости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кузнец-тролль по имени Ула\'елек готов выковать для тебя рукавицы Жестокости. Он живет в Дуротаре, в деревне Сен\'джин, вместе со своими собратьями из племени Черного Копья, и с нетерпением ждет твоего прихода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ула\'елеком из Дуротара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, $N. Старый Тунгрим предупредил меня о твоем приходе, но умолчи он, я не удивился бы твоему появлению.$B$BДухи следят за каждым твоим шагом, юный воин, и они говорят, что от твоей руки пало немало врагов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1840,'Орм Каменное Копыто и шлем Жестокости','Искусство Орма Каменного Копыта пользуется заслуженным уважением. Он и сделает тебе шлем Жестокости.$b$bЕго можно найти в Громовом Утесе, рядом с прудом и центральным тотемом города.','Обратитесь к Орму Каменному Копыту из Громового Утеса.','Привет тебе, воин. Я Орм. Тунгрим сказал, что тебе нужен шлем. Это правда?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орм Каменное Копыто и шлем Жестокости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Искусство Орма Каменного Копыта пользуется заслуженным уважением. Он и сделает тебе шлем Жестокости.$b$bЕго можно найти в Громовом Утесе, рядом с прудом и центральным тотемом города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Орму Каменному Копыту из Громового Утеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, воин. Я Орм. Тунгрим сказал, что тебе нужен шлем. Это правда?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1841,'Велора Нители и набедренники Жестокости','Говорят, что при жизни Велора Нители была одним из лучших кузнецов Лордерона. Кажется, она и после смерти не лишилась таланта. Поговори с Велорой, она сделает тебе набедренники Жестокости.$b$bВелора трудится в Подгороде Лордерона, в торговом квартале.','Поговорите с Велорой Нители из Подгорода.','Тебе нужны набедренники? Отлично!$B$BХм... Тогда кто из нас будет их делать?$B$BШутка. Смешно? Я вот не понимаю... Чувство юмора я утратила одновременно с обонянием. Примерно в те времена, как перестала дышать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Велора Нители и набедренники Жестокости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что при жизни Велора Нители была одним из лучших кузнецов Лордерона. Кажется, она и после смерти не лишилась таланта. Поговори с Велорой, она сделает тебе набедренники Жестокости.$b$bВелора трудится в Подгороде Лордерона, в торговом квартале.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Велорой Нители из Подгорода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе нужны набедренники? Отлично!$B$BХм... Тогда кто из нас будет их делать?$B$BШутка. Смешно? Я вот не понимаю... Чувство юмора я утратила одновременно с обонянием. Примерно в те времена, как перестала дышать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1842,'Копыта сатиров','Я могу сделать для тебя пару рукавиц Жестокости, напитав их магической силой. Но прежде тебе придется добыть эту самую силу.$b$bВ северо-восточной части Ясеневого леса живут сатиры. Их привлекла туда сила леса. Они питаются его первозданной чистотой, искажая и оскверняя ее. Сатиров, вобравших в себя особенно много магии Ясеневого леса можно отличить от других по разбухшим, нераздвоенным копытам.$b$bВ этих копытах содержится великая сила. Они понадобятся мне для создания рукавиц.','Принесите 7 целых копыт сатиров Ула\'елеку в Дуротар, в деревню Сен\'джин.','Ага, вот и они! Сатиры похитили силу Ясеневого леса, а их сила вольется в мое творение...','Копыта уже у тебя, $N? Помни, они полны сильнейшей магии.','Вернитесь к Ула\'елеку в деревню Сен\'джин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Копыта сатиров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я могу сделать для тебя пару рукавиц Жестокости, напитав их магической силой. Но прежде тебе придется добыть эту самую силу.$b$bВ северо-восточной части Ясеневого леса живут сатиры. Их привлекла туда сила леса. Они питаются его первозданной чистотой, искажая и оскверняя ее. Сатиров, вобравших в себя особенно много магии Ясеневого леса можно отличить от других по разбухшим, нераздвоенным копытам.$b$bВ этих копытах содержится великая сила. Они понадобятся мне для создания рукавиц.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 целых копыт сатиров Ула\'елеку в Дуротар, в деревню Сен\'джин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, вот и они! Сатиры похитили силу Ясеневого леса, а их сила вольется в мое творение...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Копыта уже у тебя, $N? Помни, они полны сильнейшей магии.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ула\'елеку в деревню Сен\'джин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1843,'Рукавицы Жестокости','Спасибо, $N. Эти рукавицы – мое величайшее достижение. Возьми их. Ты окажешь мне честь, если пойдешь в них в бой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рукавицы Жестокости',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Эти рукавицы – мое величайшее достижение. Возьми их. Ты окажешь мне честь, если пойдешь в них в бой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1844,'Рог химеры','Я сделаю тебе шлем, но прежде докажи, что $gдостоин:достойна; его.$b$bВ северо-западной части Когтистых гор лежит Обугленная долина. Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все живущие там существа исполнены боли и отчаяния.$b$bТуда тебе и придется отправиться, $n.$b$bСтупай в Обугленную долину и найди там химеру-матриарха. Избавь ее от страданий. Принеси в доказательство ее гибели гальванизированный рог, и я сделаю тебе шлем.','Принести Орму Каменному Копыту из Громового Утеса гальванизированный рог.','Что же, задание выполнено, $N. Теперь я не сомневаюсь в твоей решимости и храбрости. Ты $Gзаслужил:заслужила; шлем...','Ну и где рог? Ты избавил матриарха от страданий?','Вернитесь к Орму Каменному Копыту в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рог химеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сделаю тебе шлем, но прежде докажи, что $gдостоин:достойна; его.$b$bВ северо-западной части Когтистых гор лежит Обугленная долина. Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все живущие там существа исполнены боли и отчаяния.$b$bТуда тебе и придется отправиться, $n.$b$bСтупай в Обугленную долину и найди там химеру-матриарха. Избавь ее от страданий. Принеси в доказательство ее гибели гальванизированный рог, и я сделаю тебе шлем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принести Орму Каменному Копыту из Громового Утеса гальванизированный рог.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что же, задание выполнено, $N. Теперь я не сомневаюсь в твоей решимости и храбрости. Ты $Gзаслужил:заслужила; шлем...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну и где рог? Ты избавил матриарха от страданий?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орму Каменному Копыту в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1845,'Шлем Жестокости','Возьми этот шлем.$B$BТебя привели ко мне великие свершения, и если Матери-земле будет угодно... тебе предстоит немало подвигов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шлем Жестокости',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возьми этот шлем.$B$BТебя привели ко мне великие свершения, и если Матери-земле будет угодно... тебе предстоит немало подвигов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1846,'Берцовые кости','Чтобы создать набедренники жестокости, мне понадобятся прочные берцовые кости. У орков из клана Драконьей Пасти крепкие ноги. Они-то мне и нужны.$b$bНо только самые прочные. Непременно проверь их, прежде чем счесть подходящими. Если ты сможешь сломать их голыми руками, значит, они не достаточно прочные.','Принесите 8 крепких берцовых костей Драконьей Пасти Велоре Нители в Подгород.','$GМолодец:Умница;! На вид они крепкие. Пожалуй, подойдут. Орки не возражали? Сильно жаловались?$B$BОпять я пошутила. Ты не смеешься.$B$BЧто-то у меня не так с чувством юмора...','Я жду, когда ты принесешь берцовые кости, $N. Из них выйдет отличная основа для набедренников.','Вернитесь к Велоре Нители в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Берцовые кости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы создать набедренники жестокости, мне понадобятся прочные берцовые кости. У орков из клана Драконьей Пасти крепкие ноги. Они-то мне и нужны.$b$bНо только самые прочные. Непременно проверь их, прежде чем счесть подходящими. Если ты сможешь сломать их голыми руками, значит, они не достаточно прочные.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 крепких берцовых костей Драконьей Пасти Велоре Нители в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;! На вид они крепкие. Пожалуй, подойдут. Орки не возражали? Сильно жаловались?$B$BОпять я пошутила. Ты не смеешься.$B$BЧто-то у меня не так с чувством юмора...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я жду, когда ты принесешь берцовые кости, $N. Из них выйдет отличная основа для набедренников.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Велоре Нители в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1847,'Набедренники Жестокости','Вот твои набедренники, $N. Ну как, подходят? Или надо что-то менять? Мне хочется угодить заказчику! По крайней мере всегда хотелось.$B$BТеперь ремесло утратило прежнюю прелесть. Но все лучше, чем быть безмозглым рабом Плети!$B$BНаверное.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Набедренники Жестокости',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот твои набедренники, $N. Ну как, подходят? Или надо что-то менять? Мне хочется угодить заказчику! По крайней мере всегда хотелось.$B$BТеперь ремесло утратило прежнюю прелесть. Но все лучше, чем быть безмозглым рабом Плети!$B$BНаверное.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1848,'Хауберк жестокости','Тебе несомненно пришлось пролить немало крови, чтобы справиться с моим заданием, $N. Вот плод твоих трудов.$B$BНоси с удовольствием. Как-нибудь заходи, расскажешь, как он тебе пригодился в бою.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хауберк жестокости',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе несомненно пришлось пролить немало крови, чтобы справиться с моим заданием, $N. Вот плод твоих трудов.$B$BНоси с удовольствием. Как-нибудь заходи, расскажешь, как он тебе пригодился в бою.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1858,'Изувеченная Длань','Загляни в сумку Тазана и принеси мне то, что найдешь внутри. Замок там непростой, так что постарайся раздобыть ключ.$b$bНа трупе Тазана ключа не было? Значит, он его кому-то отдал... Ах, ну да, конечно. У него был помощник, Гамон. Он пьяница, так что ищи его в тавернах. Возможно, тебе удастся потихоньку утащить у него ключ.','Украдите ключ Тазана, откройте сумку Тазана и отнесите содержимое сумки Терзоку в Расселину Теней в Оргриммаре.','Так-так, интересно... Что ж, $N, ты полностью $Gоправдал:оправдала; мое доверие. Отныне можешь считать себя членом клана Изувеченной Длани. И возьми это. Думаю, он тебе очень пригодится в будущем.','Не ужасно ли это: держать в руках то, что тебе нужно, и не иметь возможности его достать?','Вернитесь к Терзоку в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изувеченная Длань',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Загляни в сумку Тазана и принеси мне то, что найдешь внутри. Замок там непростой, так что постарайся раздобыть ключ.$b$bНа трупе Тазана ключа не было? Значит, он его кому-то отдал... Ах, ну да, конечно. У него был помощник, Гамон. Он пьяница, так что ищи его в тавернах. Возможно, тебе удастся потихоньку утащить у него ключ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите ключ Тазана, откройте сумку Тазана и отнесите содержимое сумки Терзоку в Расселину Теней в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так-так, интересно... Что ж, $N, ты полностью $Gоправдал:оправдала; мое доверие. Отныне можешь считать себя членом клана Изувеченной Длани. И возьми это. Думаю, он тебе очень пригодится в будущем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не ужасно ли это: держать в руках то, что тебе нужно, и не иметь возможности его достать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Терзоку в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1859,'Терзок','Говори тише, $n! Ну да, я знаю твое имя. Мне сказали, чтобы я ждал одного орка, и дали описание твоей внешности.$b$bСудя по тому, что о тебе рассказывают, ты неплохо держишься в открытом бою, но можешь прибегнуть и к хитрости, верно?$b$bВ общем, сходи в Оргриммар, поговори с Терзоком. У него есть для тебя предложение.','Поговорите с Терзоком в Расселине Теней в Оргриммаре.','А, это ты! Очень хорошо, что Каплак сумел тебя перехватить.$B$BНам нужно поговорить кое о чем, не в последнюю очередь – о твоем будущем в Раздробленной Руке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Терзок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говори тише, $n! Ну да, я знаю твое имя. Мне сказали, чтобы я ждал одного орка, и дали описание твоей внешности.$b$bСудя по тому, что о тебе рассказывают, ты неплохо держишься в открытом бою, но можешь прибегнуть и к хитрости, верно?$b$bВ общем, сходи в Оргриммар, поговори с Терзоком. У него есть для тебя предложение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Терзоком в Расселине Теней в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, это ты! Очень хорошо, что Каплак сумел тебя перехватить.$B$BНам нужно поговорить кое о чем, не в последнюю очередь – о твоем будущем в Раздробленной Руке.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1860,'Поговорите с Джиннией','У нас, магов, есть одна задача, которая жизненно важна для безопасности Штормграда и Элвиннского леса.$b$bПодробности ты можешь узнать у Джиннии Пушки. Она работает в Башне магов, в районе магов в Штормграде. Не мешкай.','Поговорите с Джиннией Пушкой в Штормграде.','Тебя послали мне на подмогу, $N? Хорошо. Приятно видеть, что молодые маги рады внести свой вклад в общее дело…$B$BКакое дело, спросишь ты? Вырастешь – узнаешь. Обязательно узнаешь... со временем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поговорите с Джиннией',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас, магов, есть одна задача, которая жизненно важна для безопасности Штормграда и Элвиннского леса.$b$bПодробности ты можешь узнать у Джиннии Пушки. Она работает в Башне магов, в районе магов в Штормграде. Не мешкай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джиннией Пушкой в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послали мне на подмогу, $N? Хорошо. Приятно видеть, что молодые маги рады внести свой вклад в общее дело…$B$BКакое дело, спросишь ты? Вырастешь – узнаешь. Обязательно узнаешь... со временем.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1861,'Зеркальное озеро','Этот мир пал жертвой магических войн, в результате которых нарушилось течение магической энергии. Мы попытались просчитать дальнейшие последствия, и многие из нас опасаются худшего!$b$bНо об этом мы поговорим позже. Для начала надо собрать все доступные сведения.$b$bВозьми этот сосуд, отправляйся к подножию водопада у Зеркального озера, что на юго-западе от Врат Штормграда, и принеси мне пробу тамошней воды. Я хочу исследовать ее на предмет заражения тлетворной магией.','Отнесите пробу воды из Зеркального озера Джиннии Пушке из Штормграда.','Спасибо, $N. Я исследую магические свойства этой воды. Будем надеяться, что их не окажется, а то, неровен час, окажется, что магия повлияла на всех, кто пил много воды из Зеркального озера.$B$BВозьми эту сферу или этот посох в знак моей благодарности за услугу. Пускай они служат тебе верой и правдой.','Ты $Gпринес:принесла; мне пробу, $N? Магические потоки Штормграда и Элвиннского леса ощутимо изменились, и я должна знать, что проникает в нашу воду.','Вернитесь к Джиннии Пушке в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зеркальное озеро',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот мир пал жертвой магических войн, в результате которых нарушилось течение магической энергии. Мы попытались просчитать дальнейшие последствия, и многие из нас опасаются худшего!$b$bНо об этом мы поговорим позже. Для начала надо собрать все доступные сведения.$b$bВозьми этот сосуд, отправляйся к подножию водопада у Зеркального озера, что на юго-западе от Врат Штормграда, и принеси мне пробу тамошней воды. Я хочу исследовать ее на предмет заражения тлетворной магией.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите пробу воды из Зеркального озера Джиннии Пушке из Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Я исследую магические свойства этой воды. Будем надеяться, что их не окажется, а то, неровен час, окажется, что магия повлияла на всех, кто пил много воды из Зеркального озера.$B$BВозьми эту сферу или этот посох в знак моей благодарности за услугу. Пускай они служат тебе верой и правдой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне пробу, $N? Магические потоки Штормграда и Элвиннского леса ощутимо изменились, и я должна знать, что проникает в нашу воду.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джиннии Пушке в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (1878,'Награда за воду','Вернитесь к оператору крана Тормозиллеру в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда за воду',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оператору крана Тормозиллеру в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1879,'Поговорите с Бинк','$n! Бинк, моя коллега-гном из Стальгорна, прислала мне весточку. У нее возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет. Ты $gготов:готова; ей помочь, $n?$B$BЕсли да, то поговори с ней. Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна.','Поговорите с Бинк из Стальгорна.','О, я вижу в тебе неплохие задатки, да-да! Но чтобы стать хорошим магом, одних задатков мало. А не сликшом хороший маг – плохой маг. А из-за плохих магов и возникают все проблемы!$B$BОй, кажется, я немного забегаю вперед. Начнем сначала!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поговорите с Бинк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Бинк, моя коллега-гном из Стальгорна, прислала мне весточку. У нее возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет. Ты $gготов:готова; ей помочь, $n?$B$BЕсли да, то поговори с ней. Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бинк из Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, я вижу в тебе неплохие задатки, да-да! Но чтобы стать хорошим магом, одних задатков мало. А не сликшом хороший маг – плохой маг. А из-за плохих магов и возникают все проблемы!$B$BОй, кажется, я немного забегаю вперед. Начнем сначала!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1880,'Маг-тастический гизмонитор','Мы, маги, не просто щелкаем пальчиками и создаем забавные искорки! Мы контролируем поток магической энергии, основной ткани мироздания! Для этого требуется осторожность и решимость. И знания... Невероятно много знаний!$B$bОдно из моих устройств, маг-тастический гизмонитор, позволяет собирать и хранить множество знаний! Но увы, он утрачен! Когда мы бежали из Гномрегана, я оставила его в сундуке в одном из домишек за пределами города. Теперь там кишмя кишат лепрогномы!$b$bПрошу тебя, $n, верни мне гизмонитор!"','Верните Бинк маг-тастический гизмонитор.','О, радость! Создавая гизмонитор, я и не догадывалась, в какую зависимость от него попаду! Теперь я могу возобновить свои исследования.$B$BСпасибо, $N! Вот, смотри. Это мой первый набор магических инструментов. Они не так блестят, как новые, зато проверены временем. Выбирай любой из них – все они могут тебе пригодиться.','Тебе удалось найти мой гизмонитор? Нужно найти его, пока источник питания не разрядился!','Вернитесь к Бинк в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маг-тастический гизмонитор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы, маги, не просто щелкаем пальчиками и создаем забавные искорки! Мы контролируем поток магической энергии, основной ткани мироздания! Для этого требуется осторожность и решимость. И знания... Невероятно много знаний!$B$bОдно из моих устройств, маг-тастический гизмонитор, позволяет собирать и хранить множество знаний! Но увы, он утрачен! Когда мы бежали из Гномрегана, я оставила его в сундуке в одном из домишек за пределами города. Теперь там кишмя кишат лепрогномы!$b$bПрошу тебя, $n, верни мне гизмонитор!"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Бинк маг-тастический гизмонитор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, радость! Создавая гизмонитор, я и не догадывалась, в какую зависимость от него попаду! Теперь я могу возобновить свои исследования.$B$BСпасибо, $N! Вот, смотри. Это мой первый набор магических инструментов. Они не так блестят, как новые, зато проверены временем. Выбирай любой из них – все они могут тебе пригодиться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти мой гизмонитор? Нужно найти его, пока источник питания не разрядился!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бинк в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1881,'Разговор с Анастасией','У Анастасии Хартвелл есть задание, которое тебе как раз по плечу. Поговори с ней. Она живет в квартале магов в Подгороде. Готовься выполнить первое задание для магов Отрекшихся.','Поговорите с Анастасией Хартвелл.','Привет тебе, $N. Ты правильно $Gпоступил:поступила;, откликнувшись на мой зов, но еще правильнее будет меня выслушать...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Анастасией',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Анастасии Хартвелл есть задание, которое тебе как раз по плечу. Поговори с ней. Она живет в квартале магов в Подгороде. Готовься выполнить первое задание для магов Отрекшихся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Анастасией Хартвелл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, $N. Ты правильно $Gпоступил:поступила;, откликнувшись на мой зов, но еще правильнее будет меня выслушать...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1882,'Усадьба Балнира','Чумные земли – гнусное место, творение Короля-лича. Он отравил землю, осквернил и убил все живое. Хотя в убийственной силе чумы есть что-то привлекательное, мы, маги Отрекшихся, считаем ее неуправляемой и недопустимой.$b$bДля начала надо понять, проникла ли она в Тирисфаль. Отправляйся в усадьбу Балнира в восточной части Тирисфаля. В саду растут цветы – львиный зев. Собери их и возвращайся.','Принесите львиный зев Бальнира Анастасии Хартвелл в Магический Квартал Подгорода.','Отличные цветы. Я отправлю их на изучение нашим аптекарям. Пусть поищут в них скверну Проклятых земель.$B$BМолодец, $N. Я предлагаю тебе выбрать награду – сферу или посох. И то, и другое может тебе здорово пригодиться.','Ну и где львиный зев? Этот цветок вбирает в себя магическую энергию, поэтому изучение этих растений поблизости от Чумных земель даст нам возможность понять, добралась ли чума нежити до Тирисфальских лесов.','Вернитесь к Анастасии Хартвелл в Тирисфальские леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Усадьба Балнира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чумные земли – гнусное место, творение Короля-лича. Он отравил землю, осквернил и убил все живое. Хотя в убийственной силе чумы есть что-то привлекательное, мы, маги Отрекшихся, считаем ее неуправляемой и недопустимой.$b$bДля начала надо понять, проникла ли она в Тирисфаль. Отправляйся в усадьбу Балнира в восточной части Тирисфаля. В саду растут цветы – львиный зев. Собери их и возвращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите львиный зев Бальнира Анастасии Хартвелл в Магический Квартал Подгорода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные цветы. Я отправлю их на изучение нашим аптекарям. Пусть поищут в них скверну Проклятых земель.$B$BМолодец, $N. Я предлагаю тебе выбрать награду – сферу или посох. И то, и другое может тебе здорово пригодиться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну и где львиный зев? Этот цветок вбирает в себя магическую энергию, поэтому изучение этих растений поблизости от Чумных земель даст нам возможность понять, добралась ли чума нежити до Тирисфальских лесов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анастасии Хартвелл в Тирисфальские леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1883,'Разговор с Ун\'Тувой','Ун\'Тува, маг деревни Сен\'джин, обнаружил изменения в потоках магической энергии Дуротара и просит тебя о помощи. Поговори с ним и сделай все, что сможешь.$b$bПриди к нему на помощь, и со временем тебе откроются великие тайны.','Поговорите с Ун\'Тувой.','Привет тебе, $N. Хвала тебе, ибо ты $Gответил:ответила; на мой зов о помощи. Будем надеяться, что ты справишься с заданием...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Ун\'Тувой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ун\'Тува, маг деревни Сен\'джин, обнаружил изменения в потоках магической энергии Дуротара и просит тебя о помощи. Поговори с ним и сделай все, что сможешь.$b$bПриди к нему на помощь, и со временем тебе откроются великие тайны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ун\'Тувой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, $N. Хвала тебе, ибо ты $Gответил:ответила; на мой зов о помощи. Будем надеяться, что ты справишься с заданием...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1884,'Груды джуджу','Оказывается, нормальное течение магической энергии в Дуротаре нарушил чернокнижник Залазан с островов Эха. Для этого он разместил оскверненные фетиши, груды джуджу, среди домов центрального острова Эха.$b$bИз-за этого болеет здешнее зверье, а чернокнижники и пришельцы из преисподней, таящиеся во тьме, набираются силы.$b$bНеобходимо уничтожить эти груды джуджу, $n, прежде чем наши земли изменятся до неузнаваемости.','Уничтожьте 4 груды джуджу и вернитесь к Ун\'Туве из деревни Сен\'джин.','Я чувствую, что груды джуджу уничтожены. При удаче все труды Залазана пойдут насмарку и в Дуротаре восстановится нормальное течение магической энергии.$B$BТвой подвиг во имя Орды достоин всяческой хвалы!','Торопись, $N. Уничтожь проклятые груды джуджу!','Вернитесь к Ун\'туве в деревню Сен\'джин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Груды джуджу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оказывается, нормальное течение магической энергии в Дуротаре нарушил чернокнижник Залазан с островов Эха. Для этого он разместил оскверненные фетиши, груды джуджу, среди домов центрального острова Эха.$b$bИз-за этого болеет здешнее зверье, а чернокнижники и пришельцы из преисподней, таящиеся во тьме, набираются силы.$b$bНеобходимо уничтожить эти груды джуджу, $n, прежде чем наши земли изменятся до неузнаваемости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 4 груды джуджу и вернитесь к Ун\'Туве из деревни Сен\'джин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я чувствую, что груды джуджу уничтожены. При удаче все труды Залазана пойдут насмарку и в Дуротаре восстановится нормальное течение магической энергии.$B$BТвой подвиг во имя Орды достоин всяческой хвалы!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Торопись, $N. Уничтожь проклятые груды джуджу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ун\'туве в деревню Сен\'джин.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1885,'Меннит Каркад','$n? Вот уж не ожидал тебя увидеть после того, как тобой заинтересовался сам Каркад. Ничего нельзя сказать наперед...$B$BВ любом случае, тебе лучше встретиться с ним, и поскорее. Лучше тебе не знать, что стало с теми несколькими глупцами, которые проигнорировали вызов от него.','Поговорите с Меннитом Каркадом в Квартале Разбойников Подгорода.','Хм. Несомненно, вы пришли сюда по первому моему зову, так? Не ожидал ничего иного от перспективного стража смерти.','Будь у меня моя верная винтовка, вы были бы уже мертвы, |3-6($C)! Погодите, скоро мне на помощь приедет бригада паровых танков!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меннит Каркад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n? Вот уж не ожидал тебя увидеть после того, как тобой заинтересовался сам Каркад. Ничего нельзя сказать наперед...$B$BВ любом случае, тебе лучше встретиться с ним, и поскорее. Лучше тебе не знать, что стало с теми несколькими глупцами, которые проигнорировали вызов от него.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Меннитом Каркадом в Квартале Разбойников Подгорода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм. Несомненно, вы пришли сюда по первому моему зову, так? Не ожидал ничего иного от перспективного стража смерти.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будь у меня моя верная винтовка, вы были бы уже мертвы, |3-6($C)! Погодите, скоро мне на помощь приедет бригада паровых танков!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1886,'Принесите рекомендательное письмо Астора Менниту Каркаду в Квартал Разбойников Подгорода.','Пришел доложить об успехе?','Вернитесь к Менниту Каркаду на Руины Лордерона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите рекомендательное письмо Астора Менниту Каркаду в Квартал Разбойников Подгорода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пришел доложить об успехе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менниту Каркаду на Руины Лордерона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (1898,'Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал. Мне приходилось встречаться с Андроном, он не настолько умен, чтобы заподозрить неладное.$b$bЛорд Вариматас подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно. Хорошо бы также получить доказательства.$b$bПоговори с Андроном и вытяни из него эти сведения. Его можно найти в лавке неподалеку от Района Фармацевтов.','Поговорите с Андроном Гантом в Подгороде.','Ах да, я ждал тебя. Полагаю, наши общие знакомые довольны переданными сведениями?\n\nБоюсь, тебя спрашивать без толку, вряд ли тебя обременяют лишними знаниями. К чему доверять гонцу слишком много тайн?','Добрый день. Чем могу помочь?') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал. Мне приходилось встречаться с Андроном, он не настолько умен, чтобы заподозрить неладное.$b$bЛорд Вариматас подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно. Хорошо бы также получить доказательства.$b$bПоговори с Андроном и вытяни из него эти сведения. Его можно найти в лавке неподалеку от Района Фармацевтов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Андроном Гантом в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах да, я ждал тебя. Полагаю, наши общие знакомые довольны переданными сведениями?\n\nБоюсь, тебя спрашивать без толку, вряд ли тебя обременяют лишними знаниями. К чему доверять гонцу слишком много тайн?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добрый день. Чем могу помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1899,'Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной. Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочел бы иметь дело с тобой.','Отнесите гроссбух Андрона Менниту Каркаду в Квартал Разбойников Подгорода.','Ну и ну, я и не рассчитывал вытянуть столько информации из Андрона. Дай-ка я изучу этот гроссбух повнимательнее и дам тебе следующее задание.','Как твои успехи?','Вернитесь к Менниту Каркаду на Руины Лордерона, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной. Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочел бы иметь дело с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите гроссбух Андрона Менниту Каркаду в Квартал Разбойников Подгорода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну и ну, я и не рассчитывал вытянуть столько информации из Андрона. Дай-ка я изучу этот гроссбух повнимательнее и дам тебе следующее задание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как твои успехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менниту Каркаду на Руины Лордерона, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (1918,'Оскверненная стихия','Да, в чем дело?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненная стихия',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, в чем дело?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1919,'Задание Джиннии','Ты набираешься знаний и опыта, $gюный:юная; $n. Ты $gготов:готова; приступить к подлинному обучению и принять участие в непрекращающейся тайной войне?$b$bЕсли да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда. У нее есть для тебя задание, которое впервые приоткроет окно в невидимый мир.','Поговорите с Джиннией Пушкой в Штормграде.','$N, у меня есть для тебя задание. Да-да, прямо здесь, в квартале магов. Слушай внимательно, не будем терять время даром.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание Джиннии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты набираешься знаний и опыта, $gюный:юная; $n. Ты $gготов:готова; приступить к подлинному обучению и принять участие в непрекращающейся тайной войне?$b$bЕсли да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда. У нее есть для тебя задание, которое впервые приоткроет окно в невидимый мир.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джиннией Пушкой в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, у меня есть для тебя задание. Да-да, прямо здесь, в квартале магов. Слушай внимательно, не будем терять время даром.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1920,'Печальный отшельник','Сообщают о беспорядках в таверне "Печальный отшельник", что в квартале магов. Там бродят странные невидимые существа. Чувствую, там образовался провал маны.$b$bОтправляйся туда и поймай этих тварей. Чтобы они стали видимыми, воспользуйся заклятьем проявления, одолей их и посади в шкатулки-духоловки. Как только наберешь достаточно этих тварей, возвращайся ко мне с заполненными и пустыми шкатулками и свитком заклятия.','Возьмите свиток заклинания проявления и ящик с шкатулками-духоловками за спиной у Джиннии Пушки. Принесите 3 заполненных шкатулки-духоловки Джиннии в Башню магов.','Ну ты $Gмолодец:умница;! Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир.$B$BТы приносишь сообществу магов все больше пользы, $N.','Вы захватили существ, $N? Их нужно изучить, чтобы понять причину, по которой они появились.','Вернитесь к Джиннии Пушке в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печальный отшельник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сообщают о беспорядках в таверне "Печальный отшельник", что в квартале магов. Там бродят странные невидимые существа. Чувствую, там образовался провал маны.$b$bОтправляйся туда и поймай этих тварей. Чтобы они стали видимыми, воспользуйся заклятьем проявления, одолей их и посади в шкатулки-духоловки. Как только наберешь достаточно этих тварей, возвращайся ко мне с заполненными и пустыми шкатулками и свитком заклятия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите свиток заклинания проявления и ящик с шкатулками-духоловками за спиной у Джиннии Пушки. Принесите 3 заполненных шкатулки-духоловки Джиннии в Башню магов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну ты $Gмолодец:умница;! Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир.$B$BТы приносишь сообществу магов все больше пользы, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы захватили существ, $N? Их нужно изучить, чтобы понять причину, по которой они появились.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джиннии Пушке в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1921,'Сбор материалов','За верную службу своим собратьям-магам тебе полагается одеяние волшебника. Его вполне может сшить Уинн Ларсон, если ты принесешь ей все необходимое.$b$bСамо одеяние шьется из льна, который легко найти, но кроме него понадобятся заряженные самоцветы Расселины, а их добывают исключительно на Серебряных копях у озера Лок Модан. Горняки дворфов не смогли забрать их, и они лежат в ящиках по всему руднику.$b$bНабери льна, добудь самоцветы и принеси их Уинн Ларсон в суконную лавку Ларсона в район магов.','Отнесите 10 кусков льна и 6 заряженных самоцветов Расселины Уинн Ларсон в Штормград.','Да, превосходный лен. Из него выйдет отличная ряса. А после того, как я разошью ее самоцветами, получится настоящее одеяние для мага!','Привет, $N. Джинния сказала мне, что вы придете. У вас есть что-что для меня?','Вернитесь к Уинн Ларсон в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор материалов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За верную службу своим собратьям-магам тебе полагается одеяние волшебника. Его вполне может сшить Уинн Ларсон, если ты принесешь ей все необходимое.$b$bСамо одеяние шьется из льна, который легко найти, но кроме него понадобятся заряженные самоцветы Расселины, а их добывают исключительно на Серебряных копях у озера Лок Модан. Горняки дворфов не смогли забрать их, и они лежат в ящиках по всему руднику.$b$bНабери льна, добудь самоцветы и принеси их Уинн Ларсон в суконную лавку Ларсона в район магов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 10 кусков льна и 6 заряженных самоцветов Расселины Уинн Ларсон в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, превосходный лен. Из него выйдет отличная ряса. А после того, как я разошью ее самоцветами, получится настоящее одеяние для мага!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $N. Джинния сказала мне, что вы придете. У вас есть что-что для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уинн Ларсон в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1938,'Трактат Ура по темной магии','Давным-давно в этой башне жили три мага, и один из них поддался искушению и занялся темными искусствами. Его уговаривали отказаться от черной магии, но тщетно. И он был изгнан.$b$bНовое пристанище изгнанного мага – башня Илгалара в Красногорье. Он унес с собой ценную книгу – Трактат Ура по темной магии.$b$bМы, маги Штормграда, хотим вернуть себе эту книгу. Отправляйся в башню Илгалара, найди этот фолиант в библиотеке и принеси мне.','Принесите Трактат Ура по темной магии верховному колдуну Андромату из Штормграда.','Я опасался, что Моргант спрятал книгу где-то еще или же нашел способ открыть ее и прочесть.$B$BХорошо, что он не успел, и что все печати, наложенные на этот трактат, сохранились в целости.','Ты $Gнашел:нашла; книгу, $N? Непосвященный в темной магии вряд ли сможет извлечь из книги хоть что-то полезное для себя. Но неосторожное обращение с ней может привести к ужасным последствиям!','Вернитесь к верховному колдуну Андромату в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трактат Ура по темной магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно в этой башне жили три мага, и один из них поддался искушению и занялся темными искусствами. Его уговаривали отказаться от черной магии, но тщетно. И он был изгнан.$b$bНовое пристанище изгнанного мага – башня Илгалара в Красногорье. Он унес с собой ценную книгу – Трактат Ура по темной магии.$b$bМы, маги Штормграда, хотим вернуть себе эту книгу. Отправляйся в башню Илгалара, найди этот фолиант в библиотеке и принеси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Трактат Ура по темной магии верховному колдуну Андромату из Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я опасался, что Моргант спрятал книгу где-то еще или же нашел способ открыть ее и прочесть.$B$BХорошо, что он не успел, и что все печати, наложенные на этот трактат, сохранились в целости.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; книгу, $N? Непосвященный в темной магии вряд ли сможет извлечь из книги хоть что-то полезное для себя. Но неосторожное обращение с ней может привести к ужасным последствиям!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному колдуну Андромату в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1939,'Верховный колдун Андромат','С тобой хочет поговорить верховный колдун Андромат. Он находится на верхнем этаже Башни магов, в квартале магов Штормграда.$b$bОбязательно поговори с ним, ведь Андромат – один из самых могущественных магов за пределами Даларана. Его совет стоит десяти других.','Поговорите с верховным колдуном Андроматом.','Привет тебе, $N. Рад тебя видеть. Надеюсь, у тебя найдется время выслушать старика...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верховный колдун Андромат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тобой хочет поговорить верховный колдун Андромат. Он находится на верхнем этаже Башни магов, в квартале магов Штормграда.$b$bОбязательно поговори с ним, ведь Андромат – один из самых могущественных магов за пределами Даларана. Его совет стоит десяти других.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным колдуном Андроматом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, $N. Рад тебя видеть. Надеюсь, у тебя найдется время выслушать старика...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1940,'Безупречная паутина','Пожалуй, следует наградить тебя за безупречную службу. Пора тебе обзавестись одеянием, которое пристало носить магу твоего уровня. Если тебе удастся собрать все необходимые материалы, одеяние у тебя будет.$b$bСтупай в Сумеречный лес и убей побольше пауков, падальщиков-отшельников. Набери их паутины, только учти, годится лишь самая лучшая. Набрав достаточно паутины, отнеси ее Уинн Ларсон, которой принадлежит магазин "Суконная лавка Ларсона" в Квартале Магов. Она сошьет тебе одеяние.','Принесите 8 кусков безупречной паутины Уинн Ларсон в Штормград.','Неплохая паутина. Я немедленно примусь за работу!','Ах, да. Маги из Башни магов предупредили меня о твоем приходе. Ты несешь мне нужную паутину?','Вернитесь к Уинн Ларсон в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречная паутина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуй, следует наградить тебя за безупречную службу. Пора тебе обзавестись одеянием, которое пристало носить магу твоего уровня. Если тебе удастся собрать все необходимые материалы, одеяние у тебя будет.$b$bСтупай в Сумеречный лес и убей побольше пауков, падальщиков-отшельников. Набери их паутины, только учти, годится лишь самая лучшая. Набрав достаточно паутины, отнеси ее Уинн Ларсон, которой принадлежит магазин "Суконная лавка Ларсона" в Квартале Магов. Она сошьет тебе одеяние.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 кусков безупречной паутины Уинн Ларсон в Штормград.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохая паутина. Я немедленно примусь за работу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ах, да. Маги из Башни магов предупредили меня о твоем приходе. Ты несешь мне нужную паутину?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уинн Ларсон в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1941,'Одеяние из ткани маны','Вот твое одеяние. Один из моих шедевров! Носи на здоровье, а если тебя спросят, кто шил... Посоветуй им обратиться в суконную лавку Ларсона!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одеяние из ткани маны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот твое одеяние. Один из моих шедевров! Носи на здоровье, а если тебя спросят, кто шил... Посоветуй им обратиться в суконную лавку Ларсона!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1942,'Одеяние волшебного плетения','Твое одеяние готово! Отличный шелк тебе достался... Ты уж прости, одеяние получилось довольно короткое, часть шелка я себе оставила.$B$BШучу, шучу. Оно тебе идеально подойдет, причем будет уместно смотреться как в бою, так и на торжественном обеде. Наслаждайся!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одеяние волшебного плетения',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твое одеяние готово! Отличный шелк тебе достался... Ты уж прости, одеяние получилось довольно короткое, часть шелка я себе оставила.$B$BШучу, шучу. Оно тебе идеально подойдет, причем будет уместно смотреться как в бою, так и на торжественном обеде. Наслаждайся!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1943,'Разговор с Дейно','Магу Дейно нужна твоя помощь, $n. Она живет в Оргриммаре, в пристанище Темнотерна.','Поговорите с Дейно.','Хорошо, что ты здесь. Я хочу дать тебе довольно сложное задание. Оно жизненно важно для всего сообщества магов. Помоги мне, и маги отплатят тебе сторицей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Дейно',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Магу Дейно нужна твоя помощь, $n. Она живет в Оргриммаре, в пристанище Темнотерна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дейно.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты здесь. Я хочу дать тебе довольно сложное задание. Оно жизненно важно для всего сообщества магов. Помоги мне, и маги отплатят тебе сторицей.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1944,'Воды Ксавиана','В восточной части Ясеневого леса раскинулся прославленный город Ксавиан. Ученые всех народов слышали легенды о хранимом в нем древнем знании. Говорят, что воды Ксавиана содержат немало магической энергии.$B$BМне нужна проба воды из Ксавиана.$b$bВозьми этот сосуд и ступай туда. Набери воды у подножия самого большого водопада и возвращайся ко мне. Соблюдай осторожность – руины древнего города заполонили сатиры, им не нравится, когда в их дела встревают маги.','Принесите пробу воды из Ксавиана Дейно в Оргриммар.','А, отлично. Надеюсь, сатиры Ксавиана тебе не слишком сильно помешали?$B$BСпасибо, $N. Я немедленно займусь изучением пробы воды из Ксавиана.','Хорошо, что сосуд уцелел, $N. А вода в нем есть? Мне не терпится изучить ее свойства.','Вернитесь к Дейно в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воды Ксавиана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В восточной части Ясеневого леса раскинулся прославленный город Ксавиан. Ученые всех народов слышали легенды о хранимом в нем древнем знании. Говорят, что воды Ксавиана содержат немало магической энергии.$B$BМне нужна проба воды из Ксавиана.$b$bВозьми этот сосуд и ступай туда. Набери воды у подножия самого большого водопада и возвращайся ко мне. Соблюдай осторожность – руины древнего города заполонили сатиры, им не нравится, когда в их дела встревают маги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите пробу воды из Ксавиана Дейно в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, отлично. Надеюсь, сатиры Ксавиана тебе не слишком сильно помешали?$B$BСпасибо, $N. Я немедленно займусь изучением пробы воды из Ксавиана.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хорошо, что сосуд уцелел, $N. А вода в нем есть? Мне не терпится изучить ее свойства.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дейно в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1945,'Смеющиеся сестры','За верную службу тебе полагается новое одеяние, если ты принесешь все необходимые материалы.$b$bТебе придется вернуться в Ясеневый лес за локонами волос cмеющихся сестер – дриад, бродящих возле Приюта в Ночных Лесах.$b$bДобыв их волосы, отнеси их Кил\'хале, троллю-портному с Перекрестка, что в Степях. Он-то и сошьет тебе одеяние.','Принесите 12 волос cмеющихся сестер Кил\'хале с Перекрестка.','А, из этих волос выйдет отличное одеяние. Жаль, что приходится убивать Смеющихся сестер ради добычи волос, впрочем, добровольно они их все равно не отдали бы.$B$BЖаль, но не очень.','Привет тебе, $N. Дейно предупредила меня о твоем появлении. Она сказала, что ты принесешь волосы Смеющихся сестер. Это правда?','Вернитесь к Кил\'хале на Перекресток, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смеющиеся сестры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За верную службу тебе полагается новое одеяние, если ты принесешь все необходимые материалы.$b$bТебе придется вернуться в Ясеневый лес за локонами волос cмеющихся сестер – дриад, бродящих возле Приюта в Ночных Лесах.$b$bДобыв их волосы, отнеси их Кил\'хале, троллю-портному с Перекрестка, что в Степях. Он-то и сошьет тебе одеяние.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 волос cмеющихся сестер Кил\'хале с Перекрестка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, из этих волос выйдет отличное одеяние. Жаль, что приходится убивать Смеющихся сестер ради добычи волос, впрочем, добровольно они их все равно не отдали бы.$B$BЖаль, но не очень.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет тебе, $N. Дейно предупредила меня о твоем появлении. Она сказала, что ты принесешь волосы Смеющихся сестер. Это правда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кил\'хале на Перекресток, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1946,'Одеяние из кружева Пустоты','Вот твое пустокружево. Оно прочное и удобное и хранит в себе магию волос Смеющейся сестрички.$B$BНаслаждайся. Если понравится, не забудь упомянуть об этом в разговоре с Дейно. Вот уж с кем бы не хотелось ссориться...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одеяние из кружева Пустоты',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот твое пустокружево. Оно прочное и удобное и хранит в себе магию волос Смеющейся сестрички.$B$BНаслаждайся. Если понравится, не забудь упомянуть об этом в разговоре с Дейно. Вот уж с кем бы не хотелось ссориться...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1947,'Путь в болото','Пришло время заслужить магический жезл. Для начала поговори с отшельницей из Пылевых топей, человеком по имени Табета. Она живет в хижине в глубине болота, на западе от Терамора.$b$bЕе познания велики, и она сможет дать тебе добрый совет. Хижина Табеты находится чуть севернее руин Деревни Каменного Молота.','Поговорите с Табетой.','Вот твое пустокружево. Оно прочное и удобное и хранит в себе магию волос Смеющейся сестрички.$B$BНаслаждайся. Если понравится, не забудь упомянуть об этом в разговоре с Дейно. Вот уж с кем бы не хотелось ссориться...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь в болото',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время заслужить магический жезл. Для начала поговори с отшельницей из Пылевых топей, человеком по имени Табета. Она живет в хижине в глубине болота, на западе от Терамора.$b$bЕе познания велики, и она сможет дать тебе добрый совет. Хижина Табеты находится чуть севернее руин Деревни Каменного Молота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Табетой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот твое пустокружево. Оно прочное и удобное и хранит в себе магию волос Смеющейся сестрички.$B$BНаслаждайся. Если понравится, не забудь упомянуть об этом в разговоре с Дейно. Вот уж с кем бы не хотелось ссориться...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1948,'Волшебные предметы','Создать жезл мага не так-то просто. Приходится искать редкие компоненты, да и собирать его надо так, чтобы он вмещал побольше магической энергии. Собери все необходимое и принеси мне.$b$bЯ составила список компонентов и заодно указала, где их искать. Четко следуй моим указаниям, в противном случае при создании жезла может случиться большая неприятность!','Принесите 1 нефрит и шипастый жезл Молний Табете в Пылевые топи.','Ага! Тебе удалось найти нефрит и сделать шипастый жезл! $GМолодец:Умница;!$B$BУ тебя что, из ушей дым идет? Наверное, ты $Gподошел:подошла; слишком близко, когда молния била в заготовки. Такое случается. Не расстраивайся, получить удар молнии – хорошая примета!','Здравствуй, $N. Ты все компоненты принес?','Вернитесь к Табете на Трясину, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебные предметы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Создать жезл мага не так-то просто. Приходится искать редкие компоненты, да и собирать его надо так, чтобы он вмещал побольше магической энергии. Собери все необходимое и принеси мне.$b$bЯ составила список компонентов и заодно указала, где их искать. Четко следуй моим указаниям, в противном случае при создании жезла может случиться большая неприятность!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 нефрит и шипастый жезл Молний Табете в Пылевые топи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага! Тебе удалось найти нефрит и сделать шипастый жезл! $GМолодец:Умница;!$B$BУ тебя что, из ушей дым идет? Наверное, ты $Gподошел:подошла; слишком близко, когда молния била в заготовки. Такое случается. Не расстраивайся, получить удар молнии – хорошая примета!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Здравствуй, $N. Ты все компоненты принес?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на Трясину, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1949,'Великие тайны','Для создания жезла мне нужно прочитать некоторые разделы одной книги. Называется она "Обряды власти", а написал ее волхв Тирт.$b$bУ меня ее нет, да и ни в одной библиотеке ее не сыскать. Поэтому придется тебе найти Тирта и одолжить книгу у него.$b$bУдачи. Когда-то он был великим магом и ученым, но теперь большую часть времени проводит у гоночной трассы на Мерцающей равнине, пьет и играет в азартные игры.','Поговорите с волхвом Тиртом на Мерцающей равнине.','Что? Говори громче! У меня не такой острый слух, как бывало.$B$BНадеюсь, ты несешь мне кружку свежего эля или верные сведениями о следующей гонке! Если нет, проваливай... А то у меня наготове жезл превращения!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великие тайны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для создания жезла мне нужно прочитать некоторые разделы одной книги. Называется она "Обряды власти", а написал ее волхв Тирт.$b$bУ меня ее нет, да и ни в одной библиотеке ее не сыскать. Поэтому придется тебе найти Тирта и одолжить книгу у него.$b$bУдачи. Когда-то он был великим магом и ученым, но теперь большую часть времени проводит у гоночной трассы на Мерцающей равнине, пьет и играет в азартные игры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с волхвом Тиртом на Мерцающей равнине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Говори громче! У меня не такой острый слух, как бывало.$B$BНадеюсь, ты несешь мне кружку свежего эля или верные сведениями о следующей гонке! Если нет, проваливай... А то у меня наготове жезл превращения!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (1950,'Волшебное слово','Я помогу тебе с книгой, но сначала окажи мне услугу!$b$bНужная тебе книга заодно и магический сейф. Он открывается особой фразой, и ее-то я и забыл! Обычно мне напоминает помощник, но он куда-то запропал.$b$bЕсли тебе нужна книга, найди моего помощника! Поспрашивай у зрителей, вдруг кто-то его видел. Притащи его сюда или выбей из него волшебные слова!','Узнайте волшебные слова, отпирающие сейф Тирта и вернитесь к Тирту.','Ах да, припоминаю…$B$BЯ и правда наложил на Джонсона проклятье. Не помню, зачем я это сделал, но так ему и надо, маленькому нахалу!','Чего ты ждешь? Мне нужно мое магическое слово!','Обнаружить секретную фразу','Вернитесь к волхву Тирту в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебное слово',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я помогу тебе с книгой, но сначала окажи мне услугу!$b$bНужная тебе книга заодно и магический сейф. Он открывается особой фразой, и ее-то я и забыл! Обычно мне напоминает помощник, но он куда-то запропал.$b$bЕсли тебе нужна книга, найди моего помощника! Поспрашивай у зрителей, вдруг кто-то его видел. Притащи его сюда или выбей из него волшебные слова!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте волшебные слова, отпирающие сейф Тирта и вернитесь к Тирту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах да, припоминаю…$B$BЯ и правда наложил на Джонсона проклятье. Не помню, зачем я это сделал, но так ему и надо, маленькому нахалу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего ты ждешь? Мне нужно мое магическое слово!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Обнаружить секретную фразу',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волхву Тирту в поселок Виражи на Миражах, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1951,'Обряды власти','Хм... Оказывается, книги-то у меня и нет! Видишь ли, мне пришлось отдать последнюю копию "Обрядов власти" за игорные долги какому-то жрецу...$B$BОдному из Алого ордена. Наверное, он унес ее в монастырь в Тирисфальские леса!$b$bЕсли тебе так нужна книга, придется сходить за ней в монастырь. Прости за доставленные неудобства. Я в последнее время сам не свой...','Принесите книгу "Обряды власти" Табете в Пылевых топях.','Вот она! То что нужно для последнего обряда создания жезла! Надеюсь, поиски были не слишком сложными?','Приветствую, $N. У тебя ли книга Обряды силы?','Вернитесь к Табете на Трясину, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обряды власти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм... Оказывается, книги-то у меня и нет! Видишь ли, мне пришлось отдать последнюю копию "Обрядов власти" за игорные долги какому-то жрецу...$B$BОдному из Алого ордена. Наверное, он унес ее в монастырь в Тирисфальские леса!$b$bЕсли тебе так нужна книга, придется сходить за ней в монастырь. Прости за доставленные неудобства. Я в последнее время сам не свой...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книгу "Обряды власти" Табете в Пылевых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот она! То что нужно для последнего обряда создания жезла! Надеюсь, поиски были не слишком сложными?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $N. У тебя ли книга Обряды силы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на Трясину, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1952,'Магический жезл','Пойду, займусь созданием жезлов.','Поговорите с Табетой по завершении ритуала.','Ну вот, жезлы готовы. Выбирай любой!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магический жезл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пойду, займусь созданием жезлов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Табетой по завершении ритуала.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот, жезлы готовы. Выбирай любой!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1953,'Возвращение на болота','Пришло время поговорить с Табетой... отшельницей из Пылевых топей. Она научит тебя создавать могущественные магические инструмены.$b$bХижина Табеты находится в глубинах Пылевых топей, западнее Терамора.','Поговорите с Табетой.','Ах, да. Тебе нужна сфера или жезл? Ну, хорошо. Я помогу тебе.$B$BВпрочем, знай. Это очень опасно и может привести к твоей гибели.$B$BИли моей гибели. В общем, кому-то умереть придется…$B$BБудем надеяться, что не нам, а?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение на болота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время поговорить с Табетой... отшельницей из Пылевых топей. Она научит тебя создавать могущественные магические инструмены.$b$bХижина Табеты находится в глубинах Пылевых топей, западнее Терамора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Табетой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, да. Тебе нужна сфера или жезл? Ну, хорошо. Я помогу тебе.$B$BВпрочем, знай. Это очень опасно и может привести к твоей гибели.$B$BИли моей гибели. В общем, кому-то умереть придется…$B$BБудем надеяться, что не нам, а?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1954,'Сфера подземного огня','Первым делом тебе нужно заполучить сферу силы. У чернокнижников Пылающего Клинка очень подходящие сферы... Жаль, что в каждой из них заключен демон! Но это поправимо, и даже очень.$b$bОтправляйся в Пустоши и отбери сферу Подземного огня у призывателя из клана Пылающего Клинка. Призыватели живут на Поле Маннорок.$b$bКак получишь сферу, возвращайся.','Принесите сферу Подземного огня Табете из Пылевых топей.','Ага, недурная сфера. Не в том смысле недурная, как охлажденная вода с соком в жаркий день.$B$BБолее того, она вовсе НЕ недурная, если посмотреть повнимательнее. Да не вода, сфера!$B$BСосредоточься, $N! Иначе с этим заданием не справиться!','Сфера Подземного огня у тебя, $N?','Вернитесь к Табете на Трясину, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сфера подземного огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первым делом тебе нужно заполучить сферу силы. У чернокнижников Пылающего Клинка очень подходящие сферы... Жаль, что в каждой из них заключен демон! Но это поправимо, и даже очень.$b$bОтправляйся в Пустоши и отбери сферу Подземного огня у призывателя из клана Пылающего Клинка. Призыватели живут на Поле Маннорок.$b$bКак получишь сферу, возвращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сферу Подземного огня Табете из Пылевых топей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, недурная сфера. Не в том смысле недурная, как охлажденная вода с соком в жаркий день.$B$BБолее того, она вовсе НЕ недурная, если посмотреть повнимательнее. Да не вода, сфера!$B$BСосредоточься, $N! Иначе с этим заданием не справиться!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сфера Подземного огня у тебя, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на Трясину, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1955,'Поединок с демоном','У нас есть сфера призывателя, остается изгнать из нее демона. С этим я легко справлюсь.$B$BТебе придется куда труднее. Как только демон изойдет из сферы, убей его.$B$BГлавное – не медлить. Если ты провозишься слишком долго, он вернется в сферу и нам придется начать сначала!$B$BГотовься к схватке, $n. Вспомни самые сильные заклинания и держи под рукой зелья. Если у тебя есть друг, можешь позвать его. Сражение будет нелегким.','Убейте демона сферы, а потом поговорите с Табетой.','Великолепно, $N. Тебе удалось преподать этому демону урок, который он надолго запомнит.$B$BТеперь он трижды подумает, прежде чем вновь сунуться в наш мир. Однако если это произойдет, единственной целью демона будет найти того дерзкого смертного, что одолел его когда-то. Скорее всего, он вернется с приятелями. Огромными, жуткими приятелями, жаждущими твоей крови.$B$BНу что, $N, тебе уже страшно?','Вам придется убить этого демона, чтобы удалить его заразу со сферы, $N.','Вернитесь к Табете на Трясину, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поединок с демоном',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас есть сфера призывателя, остается изгнать из нее демона. С этим я легко справлюсь.$B$BТебе придется куда труднее. Как только демон изойдет из сферы, убей его.$B$BГлавное – не медлить. Если ты провозишься слишком долго, он вернется в сферу и нам придется начать сначала!$B$BГотовься к схватке, $n. Вспомни самые сильные заклинания и держи под рукой зелья. Если у тебя есть друг, можешь позвать его. Сражение будет нелегким.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте демона сферы, а потом поговорите с Табетой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, $N. Тебе удалось преподать этому демону урок, который он надолго запомнит.$B$BТеперь он трижды подумает, прежде чем вновь сунуться в наш мир. Однако если это произойдет, единственной целью демона будет найти того дерзкого смертного, что одолел его когда-то. Скорее всего, он вернется с приятелями. Огромными, жуткими приятелями, жаждущими твоей крови.$B$BНу что, $N, тебе уже страшно?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вам придется убить этого демона, чтобы удалить его заразу со сферы, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на Трясину, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1956,'Сила Ульдамана','Демон уничтожен, остается завладеть источником энергии. К сожалению, самые лучшие источники энергии – старые, и заполучить их нелегко. Судьба любит над нами подшутить, а?$b$bИтак, тебе придется отправиться в Ульдаман и победить тамошнего обсидианового часового. Он большой и сильный, а уж какой у него источник энергии!$b$bУдачи тебе, $n. Ну, а если она от тебя отвернется... приятно было познакомиться.','Добудьте обсидиановый источник силы и принесите его Табете в Пылевые топи.','Ты $Gсделал:сделала; это? $GМолодец:Умница;.$B$BЯ общалась с некоторыми моими коллегами и когда я случайно назвала твое имя, то они сказали: "Да, мы знаем $N, и $Gон:она; не поддается стрессу, даже в критических ситуациях".$B$BНо когда я сказала, что послала тебя в Ульдаман против обсидианового стражника, они не поверили, что ты выполнишь задачу. А я сказала им – вот увидите!$B$BЧто-ж, мы им показали, не так ли?','Ты был в Ульдамане, $N? Вы победили обсидианового стража?','Вернитесь к Табете на Трясину, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила Ульдамана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Демон уничтожен, остается завладеть источником энергии. К сожалению, самые лучшие источники энергии – старые, и заполучить их нелегко. Судьба любит над нами подшутить, а?$b$bИтак, тебе придется отправиться в Ульдаман и победить тамошнего обсидианового часового. Он большой и сильный, а уж какой у него источник энергии!$b$bУдачи тебе, $n. Ну, а если она от тебя отвернется... приятно было познакомиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте обсидиановый источник силы и принесите его Табете в Пылевые топи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсделал:сделала; это? $GМолодец:Умница;.$B$BЯ общалась с некоторыми моими коллегами и когда я случайно назвала твое имя, то они сказали: "Да, мы знаем $N, и $Gон:она; не поддается стрессу, даже в критических ситуациях".$B$BНо когда я сказала, что послала тебя в Ульдаман против обсидианового стражника, они не поверили, что ты выполнишь задачу. А я сказала им – вот увидите!$B$BЧто-ж, мы им показали, не так ли?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты был в Ульдамане, $N? Вы победили обсидианового стража?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на Трясину, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1957,'Волнолов маны','Мы почти закончили, осталось самое опасное.$B$BНужно вдохнуть силу в пустую сферу призывателя. Для этого придется обуздать энергию провала Маны. Я произнесу заклинание, оно временно создаст нужный нам провал, из которого хлынут твари, волноловы маны. Тебе придется одолеть их, и тогда я смогу собрать воедино их силу.$b$bТвоя задача – убить достаточно волноловов маны, пока провал открыт, а я уж соберу всю энергию в твою сферу.','Убейте 12 волноловов маны за отведенное время.','Надо же, ты $Gсправился:справилась;! Я в тебе не сомневалась! Ну ладно, чуть-чуть сомневалась, даже не чуть-чуть... Но не так уж сильно.$B$BЧестно.','Вы не убили необходимое количество всплесков маны, $N.','Вернитесь к Табете на Трясину, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волнолов маны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы почти закончили, осталось самое опасное.$B$BНужно вдохнуть силу в пустую сферу призывателя. Для этого придется обуздать энергию провала Маны. Я произнесу заклинание, оно временно создаст нужный нам провал, из которого хлынут твари, волноловы маны. Тебе придется одолеть их, и тогда я смогу собрать воедино их силу.$b$bТвоя задача – убить достаточно волноловов маны, пока провал открыт, а я уж соберу всю энергию в твою сферу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 волноловов маны за отведенное время.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надо же, ты $Gсправился:справилась;! Я в тебе не сомневалась! Ну ладно, чуть-чуть сомневалась, даже не чуть-чуть... Но не так уж сильно.$B$BЧестно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы не убили необходимое количество всплесков маны, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на Трясину, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1958,'Небесная сила','Ты $Gдолжен:должна; гордиться собой, $N. Не многие справились с теми трудностями, с которыми пришлось тебе столкнуться.$B$BНебесная сфера готова или я могу сделать посох. Все зависит от тебя. Я бы предпочла сферу, но кто я такая, чтобы судить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небесная сила',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gдолжен:должна; гордиться собой, $N. Не многие справились с теми трудностями, с которыми пришлось тебе столкнуться.$B$BНебесная сфера готова или я могу сделать посох. Все зависит от тебя. Я бы предпочла сферу, но кто я такая, чтобы судить?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (1959,'Задание Анастасии','Маги Подгорода заметили в городе выплеск магической энергии и обратились к чародеям Орды с просьбой выяснить, что же происходит.$b$bПодробности тебе расскажет Анастасия Хартвелл. Поговори с ней, она живет в Квартале Магов Подгорода.','Поговорите с Анастасией Хартвелл.','Это правда. В нашем городе произошел выплеск магической энергии. Мы не поняли, что именно произошло, и даже к добру это или к худу. Не хватает информации…$B$BЧто подводит нас к разговору о задании.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание Анастасии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Маги Подгорода заметили в городе выплеск магической энергии и обратились к чародеям Орды с просьбой выяснить, что же происходит.$b$bПодробности тебе расскажет Анастасия Хартвелл. Поговори с ней, она живет в Квартале Магов Подгорода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Анастасией Хартвелл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это правда. В нашем городе произошел выплеск магической энергии. Мы не поняли, что именно произошло, и даже к добру это или к худу. Не хватает информации…$B$BЧто подводит нас к разговору о задании.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1960,'Лавка алхимика','В лавке алхимика Алжернона, что в Районе Фармацевтов, происходит что-то странное. Там бродят странные невидимые существа, сотканные из магической энергии.$b$bВозьми у меня за спиной шкатулки-духоловки и свиток с нужным заклинанием. Воспользуйся свитком в лавке, подчини этих существ и загони их в шкатулки. Как только наберешь достаточно, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием.','Возьмите свиток заклинания проявления и ящик с шкатулками-духоловками за спиной у Анастасии Хартвелл. Принесите 3 заполненных шкатулки-духоловки, ящик со шкатулками духоловками и заклинание Проявления Анастасии в Подгород.','Отлично, $N. Лучшие умы Подгорода займутся изучением невидимых тварей. Мы выясним, откуда они взялись в нашем городе.$B$BЕсли дело в возникновении провала Маны, потребуется определить, случайно он возник или нет. Если не случайно,а в результате действий враждебных сил, нам придется готовиться к появлению более серьезных противников.','Ну, в чем же там дело, $N? Тебе удалось поймать невидимых тварей?','Вернитесь к Анастасии Хартвелл в Тирисфальские леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лавка алхимика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В лавке алхимика Алжернона, что в Районе Фармацевтов, происходит что-то странное. Там бродят странные невидимые существа, сотканные из магической энергии.$b$bВозьми у меня за спиной шкатулки-духоловки и свиток с нужным заклинанием. Воспользуйся свитком в лавке, подчини этих существ и загони их в шкатулки. Как только наберешь достаточно, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите свиток заклинания проявления и ящик с шкатулками-духоловками за спиной у Анастасии Хартвелл. Принесите 3 заполненных шкатулки-духоловки, ящик со шкатулками духоловками и заклинание Проявления Анастасии в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N. Лучшие умы Подгорода займутся изучением невидимых тварей. Мы выясним, откуда они взялись в нашем городе.$B$BЕсли дело в возникновении провала Маны, потребуется определить, случайно он возник или нет. Если не случайно,а в результате действий враждебных сил, нам придется готовиться к появлению более серьезных противников.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, в чем же там дело, $N? Тебе удалось поймать невидимых тварей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анастасии Хартвелл в Тирисфальские леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1961,'Сбор материалов','Тебе пора обзавестись первым облачением мага, $n. Одеяние – знак твоего особого положения, свидетельство твоего достоинства.$b$bДля создания нужного одеяния тебе понадобятся самоцветы маны от даларанских магов из Серебряного бора. Они верят примерно в то же, во что и мы, поэтому убивать их нехорошо, но раз они не могут противостоять нам, значит жизни они не заслуживают.$b$bОтнеси камни и несколько кусков льна Джозефу Грегориану в суконную лавку Квартала Магов.','Принесите 10 кусков льна и 6 даларанских самоцветов маны Джозефу Грегориану.','Отличный материал. Оценить качество самоцветов я не могу, но вскоре мы узнаем, подходят ли они для создания одеяний из чароткани...','Анастасия сказала что приготовила дизайн для твоей одеяния. Ты $Gпринес:принесла; самоцветы и лен?','Вернитесь к Джозефу Грегориану в Тирисфальские леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор материалов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе пора обзавестись первым облачением мага, $n. Одеяние – знак твоего особого положения, свидетельство твоего достоинства.$b$bДля создания нужного одеяния тебе понадобятся самоцветы маны от даларанских магов из Серебряного бора. Они верят примерно в то же, во что и мы, поэтому убивать их нехорошо, но раз они не могут противостоять нам, значит жизни они не заслуживают.$b$bОтнеси камни и несколько кусков льна Джозефу Грегориану в суконную лавку Квартала Магов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 кусков льна и 6 даларанских самоцветов маны Джозефу Грегориану.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличный материал. Оценить качество самоцветов я не могу, но вскоре мы узнаем, подходят ли они для создания одеяний из чароткани...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Анастасия сказала что приготовила дизайн для твоей одеяния. Ты $Gпринес:принесла; самоцветы и лен?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джозефу Грегориану в Тирисфальские леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (1962,'Одеяние из огненной чароткани','Вот твое новое одеяние, $N. Носи на здоровье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одеяние из огненной чароткани',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот твое новое одеяние, $N. Носи на здоровье.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1963,'Изувеченная Длань','Вождь слишком хитрит и осторожничает. Он не хочет пускать в ход всю мощь Орды. Изувеченная Длань вернет Орде былую гордость!$b$bМы тайно копим силы и исподтишка наносим удары неосторожным врагам. Докажи свою доблесть, выполни мое задание!$b$bТролль по имени Тазан торгует с пиратами близ Кабестана. У него есть нужные мне сведения. Убей его и принеси мне его сумку.','Убейте Тазана и принесите его сумку Терзоку в Расселину Теней в Оргриммаре.','Хм. Я, конечно, рад слышать, что Тазана больше нет в живых, однако от запертой сумки проку мало. Нам нужно то, что внутри!$B$BВот и второе задание для того, кто стремится вступить в клан Изувеченной Длани!','Только глупец может подумать, будто открытый удар топором опаснее кинжала в спину!','Вернитесь к Терзоку в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изувеченная Длань',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вождь слишком хитрит и осторожничает. Он не хочет пускать в ход всю мощь Орды. Изувеченная Длань вернет Орде былую гордость!$b$bМы тайно копим силы и исподтишка наносим удары неосторожным врагам. Докажи свою доблесть, выполни мое задание!$b$bТролль по имени Тазан торгует с пиратами близ Кабестана. У него есть нужные мне сведения. Убей его и принеси мне его сумку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Тазана и принесите его сумку Терзоку в Расселину Теней в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм. Я, конечно, рад слышать, что Тазана больше нет в живых, однако от запертой сумки проку мало. Нам нужно то, что внутри!$B$BВот и второе задание для того, кто стремится вступить в клан Изувеченной Длани!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Только глупец может подумать, будто открытый удар топором опаснее кинжала в спину!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Терзоку в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (1978,'Отнесите гроссбух Андрона Вариматасу в Зал Темной Госпожи в Подгороде.','Да?') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите гроссбух Андрона Вариматасу в Зал Темной Госпожи в Подгороде.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1998,'Фенвик Татрос','Убейте Фенвика Татроса и принесите его голову Менниту Каркаду в Квартал Разбойников Подгорода.','Я целиком положился на тебя. Выполни распоряжение лорда Вариматаса.','Вернитесь к Менниту Каркаду в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фенвик Татрос',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Фенвика Татроса и принесите его голову Менниту Каркаду в Квартал Разбойников Подгорода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я целиком положился на тебя. Выполни распоряжение лорда Вариматаса.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менниту Каркаду в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (1999,'Профессиональные инструменты','Отыщите отчет о состоянии Даларана и отдайте его Менниту Каркаду в Квартале Разбойников Подгорода.','Прекрасно, $N. Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал.$B$BВижу, я был прав, положившись на тебя. Поверь, $Gмальчик:девочка; G$мой:моя;, ты далеко пойдешь.','Удалось отыскать документы, $N?','Вернитесь к Менниту Каркаду в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Профессиональные инструменты',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите отчет о состоянии Даларана и отдайте его Менниту Каркаду в Квартале Разбойников Подгорода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, $N. Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал.$B$BВижу, я был прав, положившись на тебя. Поверь, $Gмальчик:девочка; G$мой:моя;, ты далеко пойдешь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось отыскать документы, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менниту Каркаду в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2000,'Рокар Тень Клинка','Слишком много ты бездельничаешь, $n. Пора тебе научиться чему-нибудь новому. Сегодня ночью пятерых из наших нашли мертвыми в расселине в Оргриммаре, и почти никаких следов. У нас есть враги, которые действуют против нас нашими же методами.$b$bТебе пора научиться взламывать замки.$b$bУвы, мои руки не очень подходят для этого ремесла. Отыщи Рокара, он живет в холмах возле Дуротара. Он уже стар, но, думаю, все еще не потерял форму.','Поговорите с Рокаром Тенью Клинка в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рокар Тень Клинка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слишком много ты бездельничаешь, $n. Пора тебе научиться чему-нибудь новому. Сегодня ночью пятерых из наших нашли мертвыми в расселине в Оргриммаре, и почти никаких следов. У нас есть враги, которые действуют против нас нашими же методами.$b$bТебе пора научиться взламывать замки.$b$bУвы, мои руки не очень подходят для этого ремесла. Отыщи Рокара, он живет в холмах возле Дуротара. Он уже стар, но, думаю, все еще не потерял форму.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рокаром Тенью Клинка в Дуротаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2018,'Испытание Рокара','Что, очередной ученик Терзока? Ну, может, я и впрямь смогу тебя кое-чему научить. Не то, чтобы мне было до тебя дело, просто неохота, чтобы твоя смерть была на моей совести.$b$bНо сначала докажи, что ты этого $gдостоин:достойна;.$b$bДолжен тебе сказать, $n, что я недолюбливаю эту Торговую Компанию. Здешние земли напоминают мне Дренор, а эти гоблины их губят. Может быть, если убить их наблюдателя в Нефтяном болоте, их планы потерпят крах?','Убейте надзирателя Глибби и отдайте его свисток Рокару Тени Клинка в Дуротаре.','Вернитесь к Рокару Тени Клинка в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание Рокара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что, очередной ученик Терзока? Ну, может, я и впрямь смогу тебя кое-чему научить. Не то, чтобы мне было до тебя дело, просто неохота, чтобы твоя смерть была на моей совести.$b$bНо сначала докажи, что ты этого $gдостоин:достойна;.$b$bДолжен тебе сказать, $n, что я недолюбливаю эту Торговую Компанию. Здешние земли напоминают мне Дренор, а эти гоблины их губят. Может быть, если убить их наблюдателя в Нефтяном болоте, их планы потерпят крах?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте надзирателя Глибби и отдайте его свисток Рокару Тени Клинка в Дуротаре.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рокару Тени Клинка в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2019,'Профессиональные инструменты','Ну вот, $n. Думаю, они тебе пригодятся. Я их сделал своими руками, так что могу поклясться: лучших отмычек не бывает.$b$bМожешь не рассказывать, зачем они тебе. Планы Терзока меня не интересуют, я теперь в отставке и хочу жить спокойно.$b$bЕсли вдруг тебе понадобятся новые отмычки, приходи ко мне. Но лучше береги эти!','Вернитесь к Терзоку в Расселину Теней в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Профессиональные инструменты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, $n. Думаю, они тебе пригодятся. Я их сделал своими руками, так что могу поклясться: лучших отмычек не бывает.$b$bМожешь не рассказывать, зачем они тебе. Планы Терзока меня не интересуют, я теперь в отставке и хочу жить спокойно.$b$bЕсли вдруг тебе понадобятся новые отмычки, приходи ко мне. Но лучше береги эти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Терзоку в Расселину Теней в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (2020,'<UNUSED>','Now here\'s the locky lock.','Вернитесь к Терзоку в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Now here\'s the locky lock.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Терзоку в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2038,'Пропавшее снаряжение Бинглза','Мало того, что они вторглись в наши края, эти трогги с ближайшего острова напали на меня и украли мои инструменты и особую взрывчатку – сорвиголовку Подрывайстера. Без гирокоптера и взрывчатки движению не обойтись!$B$BВерни мне инструменты и отыщи сорвиголовку, $n. За Гномреган!','Найдите и верните Бинглзу гаечный ключ Бинглза, отвертку Бинглза, молот Бинглза и сорвиголовку Бинглза.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшее снаряжение Бинглза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мало того, что они вторглись в наши края, эти трогги с ближайшего острова напали на меня и украли мои инструменты и особую взрывчатку – сорвиголовку Подрывайстера. Без гирокоптера и взрывчатки движению не обойтись!$B$BВерни мне инструменты и отыщи сорвиголовку, $n. За Гномреган!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и верните Бинглзу гаечный ключ Бинглза, отвертку Бинглза, молот Бинглза и сорвиголовку Бинглза.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2039,'Найти Бинглза','Мы потеряли связь с Бинглзом! Он был отправлен в разведывательный полет над Гномреганом, и уже неделю от него нет никаких известий. Я знаю только то, что он отправился в разведку и потерпел крушение.$B$BПоследний раз его видели над озером Лок. Возможно, ты сможешь выяснить, что с ним, $n.','Найдите Бинглза Подрывайстера в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Бинглза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы потеряли связь с Бинглзом! Он был отправлен в разведывательный полет над Гномреганом, и уже неделю от него нет никаких известий. Я знаю только то, что он отправился в разведку и потерпел крушение.$B$BПоследний раз его видели над озером Лок. Возможно, ты сможешь выяснить, что с ним, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Бинглза Подрывайстера в Лок Модане.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2040,'Битва под землей','Гномреган захватили трогги! Ситуация крайне тяжелая, но, быть может, вы cможете помочь, $n.$b$bГлубоко под землей, в Мертвых копях, находится действующий гоблинский крошшер. Найдите его и принесите его источник питания. С его помощью мы сможем обеспечить наши автогиробуроройки достаточной энергией, чтобы пробиться через каменные границы Гномрегана и открыть дорогу армии гномов!','Принесите Шони Молшунье в Штормград зубчатый спрек-механизм гномов из Мертвых копей.','Вы нашли зубчатый спрек-механизм гномов, $N?','Вернитесь к Шони Молшунье в Квартал Дворфов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва под землей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гномреган захватили трогги! Ситуация крайне тяжелая, но, быть может, вы cможете помочь, $n.$b$bГлубоко под землей, в Мертвых копях, находится действующий гоблинский крошшер. Найдите его и принесите его источник питания. С его помощью мы сможем обеспечить наши автогиробуроройки достаточной энергией, чтобы пробиться через каменные границы Гномрегана и открыть дорогу армии гномов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Шони Молшунье в Штормград зубчатый спрек-механизм гномов из Мертвых копей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы нашли зубчатый спрек-механизм гномов, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шони Молшунье в Квартал Дворфов Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2041,'Разговор с Шони','Возможно... Возможно, вы поможете нам в битве за Гномреган.$B$BВ Штормграде вы найдете командира нашей подземной штурмовой группы, Шони Молшунью. Шони нужна помощь в сооружении автогиробуророек.$B$BВы найдете ее среди дворфов в Штормграде.$B$BУдачи, $n.','Поговорите с Шони Молшуньей в Квартале Дворфов в Штормграде.','Вы с известиями от центрального командования?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Шони',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно... Возможно, вы поможете нам в битве за Гномреган.$B$BВ Штормграде вы найдете командира нашей подземной штурмовой группы, Шони Молшунью. Шони нужна помощь в сооружении автогиробуророек.$B$BВы найдете ее среди дворфов в Штормграде.$B$BУдачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Шони Молшуньей в Квартале Дворфов в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы с известиями от центрального командования?',`offerrewardtext_loc8`);
