INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2078,'Месть Гиромачта','Эй, сухопутное создание, нужно, чтоб ты $gнашел:нашла; моего первого помощника.$B$BБерешь этот ключ, вставляешь ему в башку и ведешь сюда, чтобы он опять служил своему кэпу.$B$BЭтим мурлокам и их главарю не шибко понравится, когда ими займется мой первый помощник!','Найдите первого помощника Гелхака, Бешенатора 4100, и отведите его к Гелхаку.','Да-а-а... А ты, оказывается, больше, чем желторотая собачья акула, крыса ты сухопутная.$B$BКэп тебя, может, даже пустит палубу драить, если так и дальше пойдет...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Гиромачта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, сухопутное создание, нужно, чтоб ты $gнашел:нашла; моего первого помощника.$B$BБерешь этот ключ, вставляешь ему в башку и ведешь сюда, чтобы он опять служил своему кэпу.$B$BЭтим мурлокам и их главарю не шибко понравится, когда ими займется мой первый помощник!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите первого помощника Гелхака, Бешенатора 4100, и отведите его к Гелхаку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-а-а... А ты, оказывается, больше, чем желторотая собачья акула, крыса ты сухопутная.$B$BКэп тебя, может, даже пустит палубу драить, если так и дальше пойдет...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2098,'Помощь Гиромачту','Жизнь пирата нелегка, сухопутное ты создание. Это не только грабежи да пьянки! Увы, мой корабль затонул совсем рядом с берегом из-за этих мерзких жесткозубов.$B$BПервое, что мне нужно, – это чтоб мой первый помощник был в рабочем состоянии!$B$BКогда меня вынесло на берег, ключ от моего первого помощника сломался от удара о скалы, и его части растащили обитающие на Темных берегах звери. Краем глаза я заметил разъяренных крабов, свирепых лесных долгоходов и мурлоков, обшаривающих останки корабля...','Отыщите три фрагмента ключа и отнесите их Гелхаку Гиромачту.','Ах ты ж, акула собачья! Тебе удалось все найти! Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждет!$B$BА кстати, ты не $gвидел:видела; моего первого помощника?','Эй, $gсухопутник:сухопутница;, еще не нашелся мой сломанный ключ?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Гиромачту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жизнь пирата нелегка, сухопутное ты создание. Это не только грабежи да пьянки! Увы, мой корабль затонул совсем рядом с берегом из-за этих мерзких жесткозубов.$B$BПервое, что мне нужно, – это чтоб мой первый помощник был в рабочем состоянии!$B$BКогда меня вынесло на берег, ключ от моего первого помощника сломался от удара о скалы, и его части растащили обитающие на Темных берегах звери. Краем глаза я заметил разъяренных крабов, свирепых лесных долгоходов и мурлоков, обшаривающих останки корабля...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите три фрагмента ключа и отнесите их Гелхаку Гиромачту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах ты ж, акула собачья! Тебе удалось все найти! Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждет!$B$BА кстати, ты не $gвидел:видела; моего первого помощника?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эй, $gсухопутник:сухопутница;, еще не нашелся мой сломанный ключ?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2118,'Зачумленные земли','Болезнь расползается по Темным берегам, захватывая сознания и тела всех, до кого добирается.$B$BНа медведей-осотников она подействовала особенно жестоко. Некогда благородные звери стали инструментами разрушения, бешеными и неистовыми. Возможно, у меня есть средство от этой напасти.$B$BОтнеси в лес эту ловушку и положи ее на землю. Любой бешеный колючешерстный медведь, попавший в нее, станет на короткий период времени послушным. В таком состоянии он будет следовать за тобой. Приведи его сюда, $n.','Поймайте бешеного колючешерстного медведя отведите его Тарнариуну.$B$BЕсли вам не удастся поймать зверя и вы потеряете ловушку, вернитесь к Тарнариуну Целителю Деревьев и попросите у него еще одну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачумленные земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Болезнь расползается по Темным берегам, захватывая сознания и тела всех, до кого добирается.$B$BНа медведей-осотников она подействовала особенно жестоко. Некогда благородные звери стали инструментами разрушения, бешеными и неистовыми. Возможно, у меня есть средство от этой напасти.$B$BОтнеси в лес эту ловушку и положи ее на землю. Любой бешеный колючешерстный медведь, попавший в нее, станет на короткий период времени послушным. В таком состоянии он будет следовать за тобой. Приведи его сюда, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте бешеного колючешерстного медведя отведите его Тарнариуну.$B$BЕсли вам не удастся поймать зверя и вы потеряете ловушку, вернитесь к Тарнариуну Целителю Деревьев и попросите у него еще одну.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (2138,'Избавление от заразы','Как я и боялся, целительное средство не действует.$B$BМеня очень печалит, что я вынужден приговаривать к смерти создания природы, но больных колючешерстных медведей придется истребить.$b$bВозвращайтесь в лес и уничтожьте 20 бешеных колючешерстных медведей, $n. Скорее всего, это не остановит зло, но хотя бы ненадолго замедлит наступление заразы на наш лес и его обитателей.','Очистите лес от 20 бешеных колючешерстных медведей и возвращайтесь к Тарнариуну Исцелителю Деревьев на Темные берега.','Задание выполнено?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Избавление от заразы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как я и боялся, целительное средство не действует.$B$BМеня очень печалит, что я вынужден приговаривать к смерти создания природы, но больных колючешерстных медведей придется истребить.$b$bВозвращайтесь в лес и уничтожьте 20 бешеных колючешерстных медведей, $n. Скорее всего, это не остановит зло, но хотя бы ненадолго замедлит наступление заразы на наш лес и его обитателей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Очистите лес от 20 бешеных колючешерстных медведей и возвращайтесь к Тарнариуну Исцелителю Деревьев на Темные берега.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Задание выполнено?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2139,'Надежда Тарнариуна','За выживание нашего народа и безопасность наших земель мы платим высокую цену, $n.$B$BВы пролили кровь слуг природы; вы сразили множество больных зверей. Народ Аубердина в долгу перед вами, поскольку боль истерзанного леса немного утихла – пусть и ненадолго.$B$BУ меня есть для вас последнее задание, но предупреждаю: вам снова придется убивать. Надеюсь, это последний раз, когда мне приходится побуждать вас к этому, $n. В пещере к северо-востоку отсюда, близ Башал\'Арана, живет мать-медведица. Убейте ее.','Найдите и убейте мать-медведицу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надежда Тарнариуна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За выживание нашего народа и безопасность наших земель мы платим высокую цену, $n.$B$BВы пролили кровь слуг природы; вы сразили множество больных зверей. Народ Аубердина в долгу перед вами, поскольку боль истерзанного леса немного утихла – пусть и ненадолго.$B$BУ меня есть для вас последнее задание, но предупреждаю: вам снова придется убивать. Надеюсь, это последний раз, когда мне приходится побуждать вас к этому, $n. В пещере к северо-востоку отсюда, близ Башал\'Арана, живет мать-медведица. Убейте ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и убейте мать-медведицу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (2158,'Отдых и покой','Каждому путнику рано или поздно нужно отдохнуть и восстановить силы – а для этого нет места лучше, чем таверна "Гордость льва".$B$BТам всем заправляет мой лучший друг Фарли. Скажи ему, что ты от меня – может, он даже скидки тебе даст на еду и выпивку.$B$BНайти "Гордость льва" несложно: нужно просто идти по дороге на юг. Не бойся, с пути не собьешься!','Побеседуйте с Фарли, хозяином "Гордости льва".','Ну, добыла мне банданы?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отдых и покой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каждому путнику рано или поздно нужно отдохнуть и восстановить силы – а для этого нет места лучше, чем таверна "Гордость льва".$B$BТам всем заправляет мой лучший друг Фарли. Скажи ему, что ты от меня – может, он даже скидки тебе даст на еду и выпивку.$B$BНайти "Гордость льва" несложно: нужно просто идти по дороге на юг. Не бойся, с пути не собьешься!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Побеседуйте с Фарли, хозяином "Гордости льва".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, добыла мне банданы?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2159,'Посылка в Доланаар','Привет тебе, $Gюный:юная:c; |3-6($c). Не окажешь ли ты мне услугу? У меня тут сверток с травами, который надо доставить в Доланаар. Но я еще не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться.$B$BНе отнесешь ли ты посылку? Ее надо доставить Кельдамиру, хозяину таверны в Доланааре. Таверна стоит у дороги к югу отсюда.','Отнесите посылку хозяину таверны Кельдамиру в Доланааре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посылка в Доланаар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $Gюный:юная:c; |3-6($c). Не окажешь ли ты мне услугу? У меня тут сверток с травами, который надо доставить в Доланаар. Но я еще не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться.$B$BНе отнесешь ли ты посылку? Ее надо доставить Кельдамиру, хозяину таверны в Доланааре. Таверна стоит у дороги к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите посылку хозяину таверны Кельдамиру в Доланааре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (2160,'Припасы для Таннока','Похоже, тебе не впервой путешествовать, и трудности в дороге тебя не пугают. Что ж, раз уж ты все равно собираешься в путь, может, заодно прихватишь и посылочку в Каранос? Ее нужно отдать хозяину таверны.$b$bТы ведь не можешь не заглянуть в таверну. После всего, что тебя ожидает в пути – а ожидает тебя много чего, уж можешь мне поверить, – ты наверняка захочешь отдохнуть и перевести дух.$b$bТак вот, я тебя и прошу – передай кое-что помощнику хозяина; его зовут Таннок Молот Стужи. Я сам в одиночку до Караноса не доберусь, а патруля горных пехотинцев еще ждать и ждать...','Отнесите ящик с припасами хозяину таверны Танноку Молоту Стужи в Караносе.','А, привет-привет! Заходи, садись у огня: тут и согреешься, и доброго эля выпьешь, с дороги-то...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы для Таннока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, тебе не впервой путешествовать, и трудности в дороге тебя не пугают. Что ж, раз уж ты все равно собираешься в путь, может, заодно прихватишь и посылочку в Каранос? Ее нужно отдать хозяину таверны.$b$bТы ведь не можешь не заглянуть в таверну. После всего, что тебя ожидает в пути – а ожидает тебя много чего, уж можешь мне поверить, – ты наверняка захочешь отдохнуть и перевести дух.$b$bТак вот, я тебя и прошу – передай кое-что помощнику хозяина; его зовут Таннок Молот Стужи. Я сам в одиночку до Караноса не доберусь, а патруля горных пехотинцев еще ждать и ждать...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик с припасами хозяину таверны Танноку Молоту Стужи в Караносе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, привет-привет! Заходи, садись у огня: тут и согреешься, и доброго эля выпьешь, с дороги-то...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2161,'Ноша батрака','Извини... Ты не $gмог:могла; бы мне помочь?$b$bУ меня тут тяжеленная сумка с припасами. Я шел по дороге, на меня нападали и скорпиды, и пауки, и еще более страшные твари! Я нес припасы в Долину Испытаний, потому что думал, что они там нужны, а я люблю помогать. Но оказалось, что припасы им не нужны! И вот мне придется тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут...$b$bНе $gмог:могла; бы ты отнести посылку вместо меня? Я ведь простой батрак, а ты-то – герой! Ты, небось, ничего не боишься...$b$bОтнеси эту сумку хозяину таверны Гроску. Спасибо тебе большое!','Отнесите сумку Укора хозяину таверны Гроску в Колючий Холм.','Ah, this is the food Ukor brought to the Valley of Trials.  Did they not need it?  Well, I guess they like to starve you heroes in training.  Builds spirit, they say!$B$BThank you for returning the food.  I\'ll stick it back on the shelves... but here, let me offer you some refreshment first!$B$BAnd don\'t forget to rest here in the inn.  You may be a brave $c ready to take on the world, but if your energy is sapped you won\'t be doing yourself, or the Horde, much good.','Welcome to Razor Hill!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ноша батрака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Извини... Ты не $gмог:могла; бы мне помочь?$b$bУ меня тут тяжеленная сумка с припасами. Я шел по дороге, на меня нападали и скорпиды, и пауки, и еще более страшные твари! Я нес припасы в Долину Испытаний, потому что думал, что они там нужны, а я люблю помогать. Но оказалось, что припасы им не нужны! И вот мне придется тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут...$b$bНе $gмог:могла; бы ты отнести посылку вместо меня? Я ведь простой батрак, а ты-то – герой! Ты, небось, ничего не боишься...$b$bОтнеси эту сумку хозяину таверны Гроску. Спасибо тебе большое!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сумку Укора хозяину таверны Гроску в Колючий Холм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ah, this is the food Ukor brought to the Valley of Trials.  Did they not need it?  Well, I guess they like to starve you heroes in training.  Builds spirit, they say!$B$BThank you for returning the food.  I\'ll stick it back on the shelves... but here, let me offer you some refreshment first!$B$BAnd don\'t forget to rest here in the inn.  You may be a brave $c ready to take on the world, but if your energy is sapped you won\'t be doing yourself, or the Horde, much good.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Welcome to Razor Hill!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (2178,'Спокойная жизнь долгоногов','Чувствуете этот восхитительный аромат? Это мой секретный рецепт, $n – свежесваренная похлебка из долгонога. Настоящий деликатес!$b$bНе хотите ли узнать рецепт?$b$bНо прежде, чем я вас научу готовить это блюдо, вы должны доказать мне, что умеете управляться с долгоногами.$B$BНет, я вовсе не жду, что вы пойдете, приручите себе одного и приедете ко мне на нем верхом! Но если бы вы могли убить несколько птиц и принести мне их сочного мяса, это, пожалуй, убедило бы меня показать вам, как же готовится похлебка из долгонога.','Принесите 5 кусков мяса долгонога Аландариан Песне Ночи в Аубердин.','Мой горшок пуст, а я проголодалась! Что ж вы так долго?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спокойная жизнь долгоногов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чувствуете этот восхитительный аромат? Это мой секретный рецепт, $n – свежесваренная похлебка из долгонога. Настоящий деликатес!$b$bНе хотите ли узнать рецепт?$b$bНо прежде, чем я вас научу готовить это блюдо, вы должны доказать мне, что умеете управляться с долгоногами.$B$BНет, я вовсе не жду, что вы пойдете, приручите себе одного и приедете ко мне на нем верхом! Но если бы вы могли убить несколько птиц и принести мне их сочного мяса, это, пожалуй, убедило бы меня показать вам, как же готовится похлебка из долгонога.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 кусков мяса долгонога Аландариан Песне Ночи в Аубердин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мой горшок пуст, а я проголодалась! Что ж вы так долго?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2198,'Рассыпавшееся ожерелье','Вы нашли потускневшее ожерелье, хотя даже то, что оно потускнело, не может исказить искусную, даже отчасти магическую работу создателя. Ожерелье было разрушено, поскольку в собранном виде в нем явно не хватает трех драгоценных камней. На обратной стороне ожерелья – почти стершаяся печать Стальгорна. Ниже печати – выгравированы три небольших буквы: "ТдК".$B$BЕсли вы хотите восстановить ожерелье, вы будете должны узнать о его происхождении. Возможно печать и эти буквы, помогут вам в этом.','Найдите создателя ожерелья, чтобы узнать, чего оно стоит.','Да, я – тот ювелир, который создал это ожерелье. Но больше ты из меня ничего клещами не вытянешь. За все надо платить, приятель, и информация не исключение. Если ты хочешь, чтобы я тебе помог, придется сначала помочь мне.','Ты ошибся гномом, приятель! Меня там и близко не было. Ты ничего не докажешь!$B$BПодожди, а тебе вообще, чего надо??? Что за... Где ты это взял?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассыпавшееся ожерелье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы нашли потускневшее ожерелье, хотя даже то, что оно потускнело, не может исказить искусную, даже отчасти магическую работу создателя. Ожерелье было разрушено, поскольку в собранном виде в нем явно не хватает трех драгоценных камней. На обратной стороне ожерелья – почти стершаяся печать Стальгорна. Ниже печати – выгравированы три небольших буквы: "ТдК".$B$BЕсли вы хотите восстановить ожерелье, вы будете должны узнать о его происхождении. Возможно печать и эти буквы, помогут вам в этом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите создателя ожерелья, чтобы узнать, чего оно стоит.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я – тот ювелир, который создал это ожерелье. Но больше ты из меня ничего клещами не вытянешь. За все надо платить, приятель, и информация не исключение. Если ты хочешь, чтобы я тебе помог, придется сначала помочь мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты ошибся гномом, приятель! Меня там и близко не было. Ты ничего не докажешь!$B$BПодожди, а тебе вообще, чего надо??? Что за... Где ты это взял?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2199,'Мудрость за деньги','Я прославленный в нашем Стальгорне ювелир! Ну, был прославленным... У меня сейчас трудные времена, и все из-за козней конкурента! Дурная репутация в нашем ремесле приводит к финансовому краху. И в результате мое доброе, но недавно опороченное имя теперь медного гроша не стоит.$B$BЯ хочу, чтобы ты $Gпринес:принесла; мне пять серебряных слитков, чтобы я сумел закончить заказ – первый за целую вечность!$B$BЕсли ты принесешь мне серебряные слитки, я отвечу на твои вопросы по поводу ожерелья.','Принесите пять серебряных слитков Талвашу дель Кисселю в Стальгорн.','Для меня теперь нет дороже друга, и плевать, что скажут другие... шучу, шучу! Правда, спасибо тебе огромное!$B$BИтак, ожерелье, которое теперь у тебя, – одно из лучших моих творений, но в нем не хватает трех драгоценных камней, что помогали удерживать в нем магическую силу. Некоторое время назад я сделал его для одного паладина. Он по личному побуждению отправился в поход, дабы выжечь "злую скверну" с раскопа в Бесплодных землях, в месте, называемом Ульдаман.$B$BВ общем... этот $c погиб в Ульдамане, и это стало началом моих горестей.','Ты принес мне пять серебряных слитков, как я просил? Я поделюсь с тобой моей печальной повестью об ожерелье, коим ты ныне владеешь... Но только после того, как я получу слитки! Неужели ты не поможешь бедному гному?','Вернитесь к Талвашу дель Кисселю в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мудрость за деньги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прославленный в нашем Стальгорне ювелир! Ну, был прославленным... У меня сейчас трудные времена, и все из-за козней конкурента! Дурная репутация в нашем ремесле приводит к финансовому краху. И в результате мое доброе, но недавно опороченное имя теперь медного гроша не стоит.$B$BЯ хочу, чтобы ты $Gпринес:принесла; мне пять серебряных слитков, чтобы я сумел закончить заказ – первый за целую вечность!$B$BЕсли ты принесешь мне серебряные слитки, я отвечу на твои вопросы по поводу ожерелья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите пять серебряных слитков Талвашу дель Кисселю в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Для меня теперь нет дороже друга, и плевать, что скажут другие... шучу, шучу! Правда, спасибо тебе огромное!$B$BИтак, ожерелье, которое теперь у тебя, – одно из лучших моих творений, но в нем не хватает трех драгоценных камней, что помогали удерживать в нем магическую силу. Некоторое время назад я сделал его для одного паладина. Он по личному побуждению отправился в поход, дабы выжечь "злую скверну" с раскопа в Бесплодных землях, в месте, называемом Ульдаман.$B$BВ общем... этот $c погиб в Ульдамане, и это стало началом моих горестей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес мне пять серебряных слитков, как я просил? Я поделюсь с тобой моей печальной повестью об ожерелье, коим ты ныне владеешь... Но только после того, как я получу слитки! Неужели ты не поможешь бедному гному?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талвашу дель Кисселю в Болотину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2200,'Назад в Ульдаман','Мой конкурент распустил слухи, что мое ожерелье проклято и что оно-то и сгубило паладина. Нечего и говорить, что покупателей на проклятые ювелирные изделия больше не нашлось.$B$B$n, я предлагаю тебе сделку – найди драгоценные камни, и я восстановлю ожерелье, а ты расскажешь всем, что на моих изделиях НЕТ никакого проклятия!$B$BПопытайся найти разгадку гибели паладина в Ульдамане – может, его тело все еще там, ведь он последний владел этим ожерельем! Когда ты найдешь камни, воспользуйся вот этим – так ты сможешь связаться со мной в Стальгорне.','Выясните, где именно в Ульдамане находится ожерелье Талваша. Убитый паладин, о котором он упоминал, был последним владельцем этого ожерелья.','В дневнике говорится, что после больших усилий $c выяснил, где находятся все три камня:$B$BРубин спрятан дворфами Тенегорна на огражденной завалами территории во время сражения с троггами за контроль над Ульдаманом.$B$BТопаз трогги спрятали в вазе, под боком у несколько неожиданных поселенцев Ульдамана – дворфов Альянса!$B$BНаконец, сапфир забрал себе старейшина троггов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад в Ульдаман',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой конкурент распустил слухи, что мое ожерелье проклято и что оно-то и сгубило паладина. Нечего и говорить, что покупателей на проклятые ювелирные изделия больше не нашлось.$B$B$n, я предлагаю тебе сделку – найди драгоценные камни, и я восстановлю ожерелье, а ты расскажешь всем, что на моих изделиях НЕТ никакого проклятия!$B$BПопытайся найти разгадку гибели паладина в Ульдамане – может, его тело все еще там, ведь он последний владел этим ожерельем! Когда ты найдешь камни, воспользуйся вот этим – так ты сможешь связаться со мной в Стальгорне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните, где именно в Ульдамане находится ожерелье Талваша. Убитый паладин, о котором он упоминал, был последним владельцем этого ожерелья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В дневнике говорится, что после больших усилий $c выяснил, где находятся все три камня:$B$BРубин спрятан дворфами Тенегорна на огражденной завалами территории во время сражения с троггами за контроль над Ульдаманом.$B$BТопаз трогги спрятали в вазе, под боком у несколько неожиданных поселенцев Ульдамана – дворфов Альянса!$B$BНаконец, сапфир забрал себе старейшина троггов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2201,'Время собирать камни','Дневник паладина дает, скорее всего, единственную подсказку, о том, где искать камни из ожерелья. Если верить записям паладина, то придется иметь дело с дворфами Стальгорна и троггами, борющимися за контроль над раскопками в Ульдамане.$B$BВооружившись этим знанием, отнесись к поискам этих камней серьезно. Когда ты найдешь камни, сообщи об этом Талвашу через фиал Видения и следуй полученным от него инструкциям.','Найдите рубин, сапфир, и топаз, которые спрятаны в разных местах Ульдамана. Когда найдете, свяжитесь с Талвашем дель Кисселем, используя фиал Видения, который он предоставил.$B$BИз дневника вы узнали следующее:$B*Рубин укрыт в забаррикадированном Тенегорне.$B*Топаз спрятан в урне в одной из областей, занятых троггами, недалеко от расположения дворфов Альянса.$B$B*Сапфир присвоил себе Гримлок, лидер троггов.','Ух ты! Да это и вправду три потерянных камня. Отличная работа! Но, к сожалению, это еще не все.$B$BНет, я не пытаюсь тебя надуть, поверь мне, $C. Дело в особенностях создания магической бижутерии – настоящей магической бижутерии от Талваша де Кисселя! Для того чтобы создать подобную вещь, нужен большой запас магической энергии, которой в этом ожерелье уже не осталось.','Образ Талваша появляется на поверхности воды в чаше.$B$B"Ого! Да ты еще жив! Удалось ли тебе найти камни? Я так надеюсь, что тебе удастся спасти мою репутацию. Умоляю тебя, скажи, что ты не терял времени даром и вызываешь меня не для того, чтобы просто поболтать. Подобные сеансы стоят недешево, а я сейчас весьма стеснен в средствах."','Вернитесь к гадальной чаше Талваша.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время собирать камни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дневник паладина дает, скорее всего, единственную подсказку, о том, где искать камни из ожерелья. Если верить записям паладина, то придется иметь дело с дворфами Стальгорна и троггами, борющимися за контроль над раскопками в Ульдамане.$B$BВооружившись этим знанием, отнесись к поискам этих камней серьезно. Когда ты найдешь камни, сообщи об этом Талвашу через фиал Видения и следуй полученным от него инструкциям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите рубин, сапфир, и топаз, которые спрятаны в разных местах Ульдамана. Когда найдете, свяжитесь с Талвашем дель Кисселем, используя фиал Видения, который он предоставил.$B$BИз дневника вы узнали следующее:$B*Рубин укрыт в забаррикадированном Тенегорне.$B*Топаз спрятан в урне в одной из областей, занятых троггами, недалеко от расположения дворфов Альянса.$B$B*Сапфир присвоил себе Гримлок, лидер троггов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Да это и вправду три потерянных камня. Отличная работа! Но, к сожалению, это еще не все.$B$BНет, я не пытаюсь тебя надуть, поверь мне, $C. Дело в особенностях создания магической бижутерии – настоящей магической бижутерии от Талваша де Кисселя! Для того чтобы создать подобную вещь, нужен большой запас магической энергии, которой в этом ожерелье уже не осталось.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Образ Талваша появляется на поверхности воды в чаше.$B$B"Ого! Да ты еще жив! Удалось ли тебе найти камни? Я так надеюсь, что тебе удастся спасти мою репутацию. Умоляю тебя, скажи, что ты не терял времени даром и вызываешь меня не для того, чтобы просто поболтать. Подобные сеансы стоят недешево, а я сейчас весьма стеснен в средствах."',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к гадальной чаше Талваша.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2202,'В Ульдаман за реактивом','Мне рассказали о недавно открытом растении, грибе-малиновике. Этот гриб растет целыми семействами на раскопках Ульдамана. Его можно отыскать в старых туннелях и самых глубоких местах, не потревоженных исследователями. Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься.$B$BОтыщи эти грибы и принеси мне дюжину. Только учти: одно неосторожное движение, и они выпустят облако ядовитых спор.$B$BВыполнишь мое поручение – я сделаю для тебя один из моих знаменитых восстановительных эликсиров!','Принести 12 грибов-малиновиков Джаркалу Замшелому Клыку в Каргат.','$GМолодец:Умница;, $N, ты снова $Gпоказал:показала;, на что $Gспособен:способна;! Эти грибы очень пригодятся для моих исследований!$B$BА теперь, как я и обещал, можешь насладиться вкусом одного из самых действенных восстановительных составов из моих личных запасов...$B$BЕсли ты тоже увлекаешься алхимией, мы можем вдобавок поговорить о других делах. В любом случае, благодарю за помощь!','Ты $Gпринес:принесла; грибы-малиновики для моих алхимических исследований? Нет грибов – нет награды!','Вернитесь к Джаркалу Замшелому Клыку в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Ульдаман за реактивом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне рассказали о недавно открытом растении, грибе-малиновике. Этот гриб растет целыми семействами на раскопках Ульдамана. Его можно отыскать в старых туннелях и самых глубоких местах, не потревоженных исследователями. Мне хотелось бы изучить возможности его применения в алхимии, и здесь-то ты мне и пригодишься.$B$BОтыщи эти грибы и принеси мне дюжину. Только учти: одно неосторожное движение, и они выпустят облако ядовитых спор.$B$BВыполнишь мое поручение – я сделаю для тебя один из моих знаменитых восстановительных эликсиров!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принести 12 грибов-малиновиков Джаркалу Замшелому Клыку в Каргат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N, ты снова $Gпоказал:показала;, на что $Gспособен:способна;! Эти грибы очень пригодятся для моих исследований!$B$BА теперь, как я и обещал, можешь насладиться вкусом одного из самых действенных восстановительных составов из моих личных запасов...$B$BЕсли ты тоже увлекаешься алхимией, мы можем вдобавок поговорить о других делах. В любом случае, благодарю за помощь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; грибы-малиновики для моих алхимических исследований? Нет грибов – нет награды!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джаркалу Замшелому Клыку в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2203,'Пробежка по Бесплодным землям-2','Ты $gоказал:оказала; мне неоценимую помощь, |3-6($c). Надо бы в награду дать тебе рецепт эликсира, который ты $gпробовал:пробовала;... Но прежде я дам тебе еще одно опасное задание. Вот моя просьба.$B$BВ этом сейфе находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опаленного дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне.$B$BДобудь мне кровь дракона, и я отдам тебе рецепт.','Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Джаркалу Замшелому Клыку в Каргат.','Между нами, алхимиками, говоря, ты просто $Gгерой:героиня;! Вот, возьми этот рецепт. Пусть он принесет тебе успех и богатство, как и мне!','Ты уже $Gнаполнил:наполнила; сосуды кровью опаленных драконов-стражей? Знаю, задание опасное... но в случае успеха тебя ждет рецепт восстановительного эликсира. Игра стоит свеч, мой друг... игра стоит свеч...','Вернитесь к Джаркалу Замшелому Клыку в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробежка по Бесплодным землям-2',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gоказал:оказала; мне неоценимую помощь, |3-6($c). Надо бы в награду дать тебе рецепт эликсира, который ты $gпробовал:пробовала;... Но прежде я дам тебе еще одно опасное задание. Вот моя просьба.$B$BВ этом сейфе находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опаленного дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне.$B$BДобудь мне кровь дракона, и я отдам тебе рецепт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Джаркалу Замшелому Клыку в Каргат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Между нами, алхимиками, говоря, ты просто $Gгерой:героиня;! Вот, возьми этот рецепт. Пусть он принесет тебе успех и богатство, как и мне!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gнаполнил:наполнила; сосуды кровью опаленных драконов-стражей? Знаю, задание опасное... но в случае успеха тебя ждет рецепт восстановительного эликсира. Игра стоит свеч, мой друг... игра стоит свеч...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джаркалу Замшелому Клыку в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2204,'Восстановление ожерелья','Тебе понадобится немного "магической силы" для ожерелья, и Ульдаман – лучшее место, чтобы ее раздобыть. Там бегает множество магических созданий. Поймай самое крупное и злобное, вынь из него источник магической силы и принеси его мне. Я уверен, что смогу вплавить его в ожерелье.$B$BБез источника силы, ожерелье починить невозможно. Возвращайся ко мне в Стальгорн, когда раздобудешь что-нибудь подходящее и мы быстро наладим для тебя эту вещь.','Добудьте источник энергии из самого мощного волшебного создания, которое найдете в Ульдамане и доставьте его Талвашу дель Кисселю в Стальгорн.','Отлично! – Я рад видеть и тебя и этот источник силы в целости и сохранности. Теперь, когда драгоценные камни возвращены на сове место, восстановить само ожерелье, займет не больше минуты... Как только я это сделаю, оно станет твоим!$B$BВолнуешься, да? просто дрожишь от нетерпения? Тааак, на чем я в прошлый раз сосредотачивал фокус заклинания...','Ты не останавливался даже чтобы привести себя в порядок после Ульдамана, так ведь? Пришел прямо сюда благоухая подземельными ароматами. Что ж будем надеяться, что все эти жертвы были принесены не напрасно.$B$BУдалось тебе добыть источник силы для ожерелья?','[Deprecated] Return to Talvash del Kissel at the Mystic Ward in Ironforge.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстановление ожерелья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе понадобится немного "магической силы" для ожерелья, и Ульдаман – лучшее место, чтобы ее раздобыть. Там бегает множество магических созданий. Поймай самое крупное и злобное, вынь из него источник магической силы и принеси его мне. Я уверен, что смогу вплавить его в ожерелье.$B$BБез источника силы, ожерелье починить невозможно. Возвращайся ко мне в Стальгорн, когда раздобудешь что-нибудь подходящее и мы быстро наладим для тебя эту вещь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте источник энергии из самого мощного волшебного создания, которое найдете в Ульдамане и доставьте его Талвашу дель Кисселю в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! – Я рад видеть и тебя и этот источник силы в целости и сохранности. Теперь, когда драгоценные камни возвращены на сове место, восстановить само ожерелье, займет не больше минуты... Как только я это сделаю, оно станет твоим!$B$BВолнуешься, да? просто дрожишь от нетерпения? Тааак, на чем я в прошлый раз сосредотачивал фокус заклинания...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты не останавливался даже чтобы привести себя в порядок после Ульдамана, так ведь? Пришел прямо сюда благоухая подземельными ароматами. Что ж будем надеяться, что все эти жертвы были принесены не напрасно.$B$BУдалось тебе добыть источник силы для ожерелья?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Talvash del Kissel at the Mystic Ward in Ironforge.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2205,'Выход на ШРУ','Значок? А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам. Ты выглядишь так, что Матиас может принять тебя за $gторговца:торговку; сыром. Тебя, детка, вряд ли можно счесть настоящим разбойником. Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена.$B$BК делу! Доставь этот пакет Матиасу: возможно, у него тоже найдется для тебя пара заданий.$B$BНе задерживайся!','Доставьте пакет от Керина Сильвиуса мастеру Матиасу Шоу в казармы Штормграда.','Итак, тебе удалось меня отыскать. Глядя на тебя, я бы сказал, что для тебя это было серьезным испытанием как физических сил, так и умственных способностей.\n\nНу что, попросить Рензика показать тебе, где здесь постоялый двор, или ты сразу приступишь к работе?','Чем могу служить, $C?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выход на ШРУ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значок? А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам. Ты выглядишь так, что Матиас может принять тебя за $gторговца:торговку; сыром. Тебя, детка, вряд ли можно счесть настоящим разбойником. Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена.$B$BК делу! Доставь этот пакет Матиасу: возможно, у него тоже найдется для тебя пара заданий.$B$BНе задерживайся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте пакет от Керина Сильвиуса мастеру Матиасу Шоу в казармы Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, тебе удалось меня отыскать. Глядя на тебя, я бы сказал, что для тебя это было серьезным испытанием как физических сил, так и умственных способностей.\n\nНу что, попросить Рензика показать тебе, где здесь постоялый двор, или ты сразу приступишь к работе?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем могу служить, $C?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2206,'Держи-хватай!','С каждой минутой, что вы ошиваетесь тут, в казармах, ваша жизнь становится короче на 60 секунд.','Вернитесь к мастеру Матиасу Шоу в ШРУ, что в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Держи-хватай!',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С каждой минутой, что вы ошиваетесь тут, в казармах, ваша жизнь становится короче на 60 секунд.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Матиасу Шоу в ШРУ, что в Штормграде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2218,'Путь к спасению','Еще одна заблудшая душа, стало быть, ищет наставничества? Полагаю, ты хочешь найти смысл жизни – смысл твоей жизни. Я тысячу раз видел, как другие герои искали работу.$B$BЧто же, сегодня тебе повезло. У Хограла найдется лекарство для твоего недуга.$B$BВот что ты сделаешь: иди по этой дороге до Стальгорна и там зайди в Заброшенный грот. Как окажешься там, найди воровскую гильдию и переговори с Хальфданом Чернобородом. Он укажет тебе путь к спасению.','Поговорите с Хальфданом Чернобородом в Стальгорне.','Стало быть, ты считаешь себя $Gнастоящим:настоящей; $Gмерзавцем:мерзавкой;? $GДостойным:Достойной; оказаться среди немногих избранных ребят Черной Бороды – стать офицером Тайного Круга?B$BТолько $Gнастоящий:настоящая; $Gпрохвост:прохвостка; так высоко себя ценит!$B$BТаких мы и ищем! Добро пожаловать, $N!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь к спасению',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще одна заблудшая душа, стало быть, ищет наставничества? Полагаю, ты хочешь найти смысл жизни – смысл твоей жизни. Я тысячу раз видел, как другие герои искали работу.$B$BЧто же, сегодня тебе повезло. У Хограла найдется лекарство для твоего недуга.$B$BВот что ты сделаешь: иди по этой дороге до Стальгорна и там зайди в Заброшенный грот. Как окажешься там, найди воровскую гильдию и переговори с Хальфданом Чернобородом. Он укажет тебе путь к спасению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хальфданом Чернобородом в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стало быть, ты считаешь себя $Gнастоящим:настоящей; $Gмерзавцем:мерзавкой;? $GДостойным:Достойной; оказаться среди немногих избранных ребят Черной Бороды – стать офицером Тайного Круга?B$BТолько $Gнастоящий:настоящая; $Gпрохвост:прохвостка; так высоко себя ценит!$B$BТаких мы и ищем! Добро пожаловать, $N!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2238,'Простая уловка','Понимаешь, король выгребает из шахты руду и камни. Таких богатств ни один гном за десять жизней не увидит.$B$BУ Тайного Круга есть свои жизненные ценности, $n. И эти ценности – драгоценности. Просекаешь?$B$BТеперь сдается нам, что королю надо бы поделиться, но так чтобы "Вонючая Борода" не знал, что мы берем свою долю, – ты улавливаешь нить?$B$BНам надо, чтобы ты $Gпереговорил:переговорила; с Онином Макмолотом неподалеку от Гномрегана и $Gвернулся:вернулась; с ответом. Этот хитрый дворф спрятался среди прокаженных. Так что поосторожнее.','Найдите Онина Макмолота возле Гномрегана.','Тсссс! Тише, балда. Нас подслушивают.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Простая уловка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понимаешь, король выгребает из шахты руду и камни. Таких богатств ни один гном за десять жизней не увидит.$B$BУ Тайного Круга есть свои жизненные ценности, $n. И эти ценности – драгоценности. Просекаешь?$B$BТеперь сдается нам, что королю надо бы поделиться, но так чтобы "Вонючая Борода" не знал, что мы берем свою долю, – ты улавливаешь нить?$B$BНам надо, чтобы ты $Gпереговорил:переговорила; с Онином Макмолотом неподалеку от Гномрегана и $Gвернулся:вернулась; с ответом. Этот хитрый дворф спрятался среди прокаженных. Так что поосторожнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Онина Макмолота возле Гномрегана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тсссс! Тише, балда. Нас подслушивают.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2239,'Донесение Онина','Рудник? Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день.$B$BМои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол\'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться.$B$BВсе в этом донесении, |3-6($r). Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг.','Доставьте донесение Онина Хальфдану в Стальгорн.','Большой крюк? Клянусь собственной бородой!$B$BТы $Gпостарался:постаралась; на славу, $N. Возьми вот этот кинжал и ступай. Круг призовет тебя снова, когда будет готов третий шаг.$B$BЧто такое третий шаг? Да тот, что идет после второго, а именно – хороший пинок тебе под зад.$B$BХочешь?','Ну, как тебе запашок лепрогнома? Чего ухмыляешься?$B$BНу, какие вести от Онина?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение Онина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рудник? Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день.$B$BМои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол\'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться.$B$BВсе в этом донесении, |3-6($r). Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте донесение Онина Хальфдану в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большой крюк? Клянусь собственной бородой!$B$BТы $Gпостарался:постаралась; на славу, $N. Возьми вот этот кинжал и ступай. Круг призовет тебя снова, когда будет готов третий шаг.$B$BЧто такое третий шаг? Да тот, что идет после второго, а именно – хороший пинок тебе под зад.$B$BХочешь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как тебе запашок лепрогнома? Чего ухмыляешься?$B$BНу, какие вести от Онина?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2240,'Потайной чертог','Теперь вернемся к насущным задачам.$B$BТебе предстоит исследовать чертог Хаз\'Мула. Проблема в том, что он находится за огромной, запертой дверью! К счастью, я знаю, как ее открыть.$B$BЯ записал все в своем дневнике, здесь на столе. Моя группа и я заперты здесь... Так что ты, $n, $gдолжен:должна; найти для нас чертог Хаз-Мула!$B$BПрочитай мой дневник и отправляйся в чертог. Потом доложи геологу Грозовой Вершине в Стальгорне.','Прочитайте журнал Бейлога, исследуйте потайной чертог и потом доложите об увиденном геологу Грозовой Вершине.','Вы видели чертог Хаз\'Мула? Потрясающе! Бейлог был уверен, что он существовал, но я, честно говоря, сомневался.$B$BСпасибо, $n. Теперь то, что вы обнаружили сподвигнет наших лидеров приложить все усилия к тому, чтобы отвоевать Ульдаман. А когда это место снова вернется под руку Стальгорна, все тайны Чертога Хаз\'Мула будут нашими!','Вам есть о чем сообщить?','Исследуйте потайной чертог','Вернитесь к геологу Грозовой Вершине в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потайной чертог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь вернемся к насущным задачам.$B$BТебе предстоит исследовать чертог Хаз\'Мула. Проблема в том, что он находится за огромной, запертой дверью! К счастью, я знаю, как ее открыть.$B$BЯ записал все в своем дневнике, здесь на столе. Моя группа и я заперты здесь... Так что ты, $n, $gдолжен:должна; найти для нас чертог Хаз-Мула!$B$BПрочитай мой дневник и отправляйся в чертог. Потом доложи геологу Грозовой Вершине в Стальгорне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте журнал Бейлога, исследуйте потайной чертог и потом доложите об увиденном геологу Грозовой Вершине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы видели чертог Хаз\'Мула? Потрясающе! Бейлог был уверен, что он существовал, но я, честно говоря, сомневался.$B$BСпасибо, $n. Теперь то, что вы обнаружили сподвигнет наших лидеров приложить все усилия к тому, чтобы отвоевать Ульдаман. А когда это место снова вернется под руку Стальгорна, все тайны Чертога Хаз\'Мула будут нашими!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вам есть о чем сообщить?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Исследуйте потайной чертог',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Грозовой Вершине в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2241,'Катись, яблочко...','Говорят, что я обезумел от любви.$B$BДа, я все время думаю о Сиарне. Да, мой дом полон рисунков и картин, с которых на меня смотрит Сиарна. Да, я часто целыми днями крошки в рот не беру, не сплю, не пью, а все плачу о нашей несбывшейся любви. Что в этом плохого?$B$BИ вот теперь она отказывается меня видеть. МЕНЯ! Я пытался письма ей писать, так она не желает ни с кем разговаривать, если только это не разбойник.$B$BНе отнесешь ли ты ей от меня этот цветок? И не забудь сказать ей, что он от Джаннока.','Отнесите розу Джаннока Сиарне в Дарнас.','Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать! Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться...\n\nНе хочешь ли подрядиться на одно дельце, |3-6($C)?','Какая прелесть! Ты принесла цветочки на собственную могилу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Катись, яблочко...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что я обезумел от любви.$B$BДа, я все время думаю о Сиарне. Да, мой дом полон рисунков и картин, с которых на меня смотрит Сиарна. Да, я часто целыми днями крошки в рот не беру, не сплю, не пью, а все плачу о нашей несбывшейся любви. Что в этом плохого?$B$BИ вот теперь она отказывается меня видеть. МЕНЯ! Я пытался письма ей писать, так она не желает ни с кем разговаривать, если только это не разбойник.$B$BНе отнесешь ли ты ей от меня этот цветок? И не забудь сказать ей, что он от Джаннока.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите розу Джаннока Сиарне в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать! Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться...\n\nНе хочешь ли подрядиться на одно дельце, |3-6($C)?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какая прелесть! Ты принесла цветочки на собственную могилу!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2242,'Зов судьбы','Нам кажется, что одно существо могло бы помочь нам понять, что происходит с лесами Тельдрассила. Увы, уговорить это существо может оказаться опасным делом.$B$BЭто сатир. Он скрывается на ветви на опушке Поляны Оракула. Пока всех, кто подходил к этому сатиру – с угрозами или добрым словом, – постигала мрачная судьба. Может, надо подкрасться к нему незаметно, $n?$B$BУзнай, что у Сетира Древнего в сумках, и возвращайся ко мне.','Найдите Сетира Древнего и принесите все, что сумеете найти, Сиарне.','Вернитесь к Сиарне на Террасу Торговцев, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов судьбы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам кажется, что одно существо могло бы помочь нам понять, что происходит с лесами Тельдрассила. Увы, уговорить это существо может оказаться опасным делом.$B$BЭто сатир. Он скрывается на ветви на опушке Поляны Оракула. Пока всех, кто подходил к этому сатиру – с угрозами или добрым словом, – постигала мрачная судьба. Может, надо подкрасться к нему незаметно, $n?$B$BУзнай, что у Сетира Древнего в сумках, и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Сетира Древнего и принесите все, что сумеете найти, Сиарне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сиарне на Террасу Торговцев, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2258,'$GМолодец:Умница;, $N. Этого мне должно хватить на некоторое время. Вот обещанная плата.$B$BЕсли ты не против получить новое задание, то вот – мне нужны еще кое-какие реактивы. Некоторые из них можно найти только в глубинах ульдаманского раскопа. Добыть их нелегко, но и плата за помощь будет немалая.$B$BМожет быть, кое-что получше блестящих монет!','Ты $Gпринес:принесла; все необходимое? Пока не принесешь, платить не буду.','Вернитесь к Джаркалу Замшелому Клыку в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N. Этого мне должно хватить на некоторое время. Вот обещанная плата.$B$BЕсли ты не против получить новое задание, то вот – мне нужны еще кое-какие реактивы. Некоторые из них можно найти только в глубинах ульдаманского раскопа. Добыть их нелегко, но и плата за помощь будет немалая.$B$BМожет быть, кое-что получше блестящих монет!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; все необходимое? Пока не принесешь, платить не буду.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джаркалу Замшелому Клыку в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2259,'Эрион Шепот Тени','Не бойся, $n, я не стану посылать тебя к Сиарне. Эрион требует твоего присутствия в Анклаве Кенария. Не медли!','Встретьтесь в Дарнасе с Эрионом Шепотом Тени.','Пора идти дальше, |3-6($R), – мир ждет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эрион Шепот Тени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не бойся, $n, я не стану посылать тебя к Сиарне. Эрион требует твоего присутствия в Анклаве Кенария. Не медли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь в Дарнасе с Эрионом Шепотом Тени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пора идти дальше, |3-6($R), – мир ждет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2260,'Директива Эриона','Весть о ваших деяниях получила широкую огласку, $n. Настолько далеко, что даже разведка Штормграда желает лично побеседовать с вами.$B$BДорога не беспошлинная и небезопасная, но возможность стажироваться в ШРУ – это вам не жук чихнул!$B$BВас ждет целый новый мир, $n. Отправляйтесь в Старый город Штормграда и поговорите с Рензиком Ножом в штаб-квартире ШРУ.','Отправляйтесь в Штормград и посоветуйтесь с Рензиком Ножом.','Вы откликнулись на призыв ШРУ, $N, и проделали долгий путь от дальних берегов, чтобы вступить в наши ряды. Однако вам многому предстоит научиться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Директива Эриона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Весть о ваших деяниях получила широкую огласку, $n. Настолько далеко, что даже разведка Штормграда желает лично побеседовать с вами.$B$BДорога не беспошлинная и небезопасная, но возможность стажироваться в ШРУ – это вам не жук чихнул!$B$BВас ждет целый новый мир, $n. Отправляйтесь в Старый город Штормграда и поговорите с Рензиком Ножом в штаб-квартире ШРУ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Штормград и посоветуйтесь с Рензиком Ножом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы откликнулись на призыв ШРУ, $N, и проделали долгий путь от дальних берегов, чтобы вступить в наши ряды. Однако вам многому предстоит научиться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2278,'Платиновые диски','Главные сокровища этого чертога – четыре огромных платиновых диска, каждый из которых украшен многочисленными символами неизвестного происхождения. Когда вы касаетесь их, у вас покалывает пальцы, и перед вами возникает каменный страж.$B$B"Приветствую! Я – хранитель знаний. Создание земельников было подробно описано и сохранено на Дисках Норганнона."$B$BВы проникли в сокровищницу никому прежде неизвестных знаний!','Поговорите с каменным стражем и запомните все, что он расскажем вам. Когда он закончит свой пересказ событий древности, активируйте диски Норганнона.','Прослушав инструкции каменного стража, вы снова получаете доступ к Дискам Норганнона, теперь уже зная историю создания земельников, троггов и дворфов. Из глубины дисков доносится слабый гул. Каменный страж говорит: $B$B"Ваша личная копия дисков готова. Дотроньтесь до дисков еще раз, чтобы получить ее".','Голос каменного стража, кажется, проникает прямо в твою душу:$B$BТы $Gдолжен:должна; сначала дождаться распознания данных Дисков Норганонна; как только ты выполнишь это требование, тебе будет разрешено получить портативную версию сохраненных данных. Пожалуйста убедись, что ты полностью исследовал информацию в пределах этого хранилища.','Выслушайте каменного стража','Воспользуйтесь дисками Норганнона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Платиновые диски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Главные сокровища этого чертога – четыре огромных платиновых диска, каждый из которых украшен многочисленными символами неизвестного происхождения. Когда вы касаетесь их, у вас покалывает пальцы, и перед вами возникает каменный страж.$B$B"Приветствую! Я – хранитель знаний. Создание земельников было подробно описано и сохранено на Дисках Норганнона."$B$BВы проникли в сокровищницу никому прежде неизвестных знаний!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с каменным стражем и запомните все, что он расскажем вам. Когда он закончит свой пересказ событий древности, активируйте диски Норганнона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прослушав инструкции каменного стража, вы снова получаете доступ к Дискам Норганнона, теперь уже зная историю создания земельников, троггов и дворфов. Из глубины дисков доносится слабый гул. Каменный страж говорит: $B$B"Ваша личная копия дисков готова. Дотроньтесь до дисков еще раз, чтобы получить ее".',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Голос каменного стража, кажется, проникает прямо в твою душу:$B$BТы $Gдолжен:должна; сначала дождаться распознания данных Дисков Норганонна; как только ты выполнишь это требование, тебе будет разрешено получить портативную версию сохраненных данных. Пожалуйста убедись, что ты полностью исследовал информацию в пределах этого хранилища.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Выслушайте каменного стража',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь дисками Норганнона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2279,'Платиновые диски','Вы прикасаетесь к Дискам Норганнона, и пальцы снова покалывает. Диски издают странный скрежещущий гул, и ваш мешок вдруг становится тяжелее. Внутри вы обнаруживаете миниатюрную копию дисков.$B$BНесомненно, для увлекающихся историей Азерота это – неслыханная ценность. Лига исследователей из Стальгорна как раз из таких. Возможно, они найдут применение этим дискам.','Отнесите миниатюрную копию дисков Норганнона в Лигу исследователей в Стальгорне.','Что это у вас там... ох мать моя... Откуда вы это взяли?$B$BНет, правда?$B$BВы кому-нибудь еще об этом расказывали?$B$BПРАВДА?!$B$BМой дорогой $C, Вы, возможно, только что совершили открытие года в области археологии! Богов ради! Кого я пытаюсь надуть, открытие столетия! Если эти диски – то, о чем я думаю, то они будут тем ключом, который мы так долго искали! Теперь мы сможем раз и навсегда доказать магическое происхождение дворфов!','Да, могу я вам чем-нибудь помочь? Я, вообще-то занят, в настоящий момент, делом, которое представляет немалую важность для всей Лиги. Но я весь внимание.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Платиновые диски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы прикасаетесь к Дискам Норганнона, и пальцы снова покалывает. Диски издают странный скрежещущий гул, и ваш мешок вдруг становится тяжелее. Внутри вы обнаруживаете миниатюрную копию дисков.$B$BНесомненно, для увлекающихся историей Азерота это – неслыханная ценность. Лига исследователей из Стальгорна как раз из таких. Возможно, они найдут применение этим дискам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите миниатюрную копию дисков Норганнона в Лигу исследователей в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это у вас там... ох мать моя... Откуда вы это взяли?$B$BНет, правда?$B$BВы кому-нибудь еще об этом расказывали?$B$BПРАВДА?!$B$BМой дорогой $C, Вы, возможно, только что совершили открытие года в области археологии! Богов ради! Кого я пытаюсь надуть, открытие столетия! Если эти диски – то, о чем я думаю, то они будут тем ключом, который мы так долго искали! Теперь мы сможем раз и навсегда доказать магическое происхождение дворфов!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, могу я вам чем-нибудь помочь? Я, вообще-то занят, в настоящий момент, делом, которое представляет немалую важность для всей Лиги. Но я весь внимание.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2280,'Платиновые диски','Вы прикасаетесь к Дискам Норганнона, и пальцы снова покалывает. Диски издают странный скрежещущий гул.$b$bВнезапно вы чувствуете, что ваш мешок становится тяжелее. Внутри вы обнаруживаете миниатюрную копию дисков!$B$BНесомненно, для увлекающихся историей Азерота это – неслыханная ценность. Кто-то наверняка заинтересуется вашей находкой!','Отнесите миниатюрную копию дисков Норганнона тому, кому это будет весьма интересно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Платиновые диски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы прикасаетесь к Дискам Норганнона, и пальцы снова покалывает. Диски издают странный скрежещущий гул.$b$bВнезапно вы чувствуете, что ваш мешок становится тяжелее. Внутри вы обнаруживаете миниатюрную копию дисков!$B$BНесомненно, для увлекающихся историей Азерота это – неслыханная ценность. Кто-то наверняка заинтересуется вашей находкой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите миниатюрную копию дисков Норганнона тому, кому это будет весьма интересно.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2281,'Встречи в Красногорье','Посылать тебя в бой равноценно убийству. Рензику не нужны лишние покойники. Но тебе, $n, бояться нечего: для тебя найдется не такое опасное дело.$B$BОтправляйся в Красногорье и поговори там с Люцием – этот тип связан с ШРУ. Он постоянно отирается у пристани в Приозерье вместе с остальными бездельниками.','Пойдите к Приозерью в Красногорье и поговорите с Люцием.','Что, $n, не слишком-то у тебя ловкие пальчики, верно? Ну, да не беспокойся: я и не из таких делал отличных разбойников!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встречи в Красногорье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посылать тебя в бой равноценно убийству. Рензику не нужны лишние покойники. Но тебе, $n, бояться нечего: для тебя найдется не такое опасное дело.$B$BОтправляйся в Красногорье и поговори там с Люцием – этот тип связан с ШРУ. Он постоянно отирается у пристани в Приозерье вместе с остальными бездельниками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пойдите к Приозерью в Красногорье и поговорите с Люцием.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, $n, не слишком-то у тебя ловкие пальчики, верно? Ну, да не беспокойся: я и не из таких делал отличных разбойников!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2282,'Лесопилка Альтера','Я долгие годы обучал молодых воров. В конце концов не всякому плуту от рождения достается ловкость и проворство, как у старого Люция.$B$BРядом с дорогой стоит лесопилка Альтера. Я оставил там сундук, а в нем – кое-что важное. Принеси его мне! Возвращайся с добычей, и получишь Воровской сертификат.','Откройте сейф Люция, достаньте Руну Воровства и вернитесь к Люцию в Приозерье.','Я забыл предупредить тебя насчет орков?$B$BГоворят, в последнее время они все время толкутся вокруг мельницы.','Вернитесь к Люцию в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лесопилка Альтера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я долгие годы обучал молодых воров. В конце концов не всякому плуту от рождения достается ловкость и проворство, как у старого Люция.$B$BРядом с дорогой стоит лесопилка Альтера. Я оставил там сундук, а в нем – кое-что важное. Принеси его мне! Возвращайся с добычей, и получишь Воровской сертификат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте сейф Люция, достаньте Руну Воровства и вернитесь к Люцию в Приозерье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я забыл предупредить тебя насчет орков?$B$BГоворят, в последнее время они все время толкутся вокруг мельницы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Люцию в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2283,'Пропавшее ожерелье','У нас есть для тебя работа – если у тебя, конечно, хватит пороху за нее взяться!$b$bВ глубине Бесплодных земель есть раскопки Ульдамана. Говорят, недавно там откинул копыта какой-то идиот-паладин. При нем было очень ценное ожерелье с тремя самоцветами: рубином, сапфиром и топазом.$b$bКороче, нам нужно это ожерелье, и мы готовы за него заплатить – чистым серебром! Если оно попорченное – ничего, как-нибудь починим.','Найдите на раскопках Ульдамана драгоценное ожерелье (возможно, поврежденное) и принесите его в Оргриммар Драну Дрофферсу.','О-о, добыча! Отсюда чую, оно здесь... Дай-ка взглянуть…$B$BЭй, что это ты нам подсовываешь? Тут же камней не хватает. Ты что $Gдумал:думала;, мы не заметим? Даже Мальтон увидел бы, что камней нету!$B$BНу, может, это и не ты их $Gспер:сперла;... Но ведь ожерелье без них ничего не стоит! Не-ет, твоя работа еще не окончена!','Ну что, оно у тебя, это ожерелье? Если его у тебя нет, не получишь ни гроша!','Вернитесь к Драну Дрофферсу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшее ожерелье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас есть для тебя работа – если у тебя, конечно, хватит пороху за нее взяться!$b$bВ глубине Бесплодных земель есть раскопки Ульдамана. Говорят, недавно там откинул копыта какой-то идиот-паладин. При нем было очень ценное ожерелье с тремя самоцветами: рубином, сапфиром и топазом.$b$bКороче, нам нужно это ожерелье, и мы готовы за него заплатить – чистым серебром! Если оно попорченное – ничего, как-нибудь починим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите на раскопках Ульдамана драгоценное ожерелье (возможно, поврежденное) и принесите его в Оргриммар Драну Дрофферсу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О-о, добыча! Отсюда чую, оно здесь... Дай-ка взглянуть…$B$BЭй, что это ты нам подсовываешь? Тут же камней не хватает. Ты что $Gдумал:думала;, мы не заметим? Даже Мальтон увидел бы, что камней нету!$B$BНу, может, это и не ты их $Gспер:сперла;... Но ведь ожерелье без них ничего не стоит! Не-ет, твоя работа еще не окончена!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, оно у тебя, это ожерелье? Если его у тебя нет, не получишь ни гроша!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драну Дрофферсу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2284,'Пропавшее ожерелье, этап 2','Эти камни наверняка остались где-то в Ульдамане! Это так же верно, как то, что Мальтон – балбес. Вернись и разыщи их!$b$bКак я уже говорил, если то, что нам рассказывали, правда, в нем были рубин, сапфир и топаз. Найди их и вставь обратно в ожерелье.$b$bГде они? А кто ж их знает? Может, тебе повезет отыскать труп того паладина. Может, они до сих пор при нем – если его, конечно, не обчистили.','Разыщите ключ к местонахождению самоцветов в глубинах Ульдамана.','Похоже, вам-таки удалось отыскать останки паладина, о которых говорил Дран. Обыскав их, вы находите дневник паладина. Дневник в плохом состоянии, большая часть страниц перепачкана запекшейся кровью. Но и оставшийся текст – сплошная галиматья. Похоже, это язык людей.$B$BПридется вам найти кого-то, кто сможет это перевести.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшее ожерелье, этап 2',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти камни наверняка остались где-то в Ульдамане! Это так же верно, как то, что Мальтон – балбес. Вернись и разыщи их!$b$bКак я уже говорил, если то, что нам рассказывали, правда, в нем были рубин, сапфир и топаз. Найди их и вставь обратно в ожерелье.$b$bГде они? А кто ж их знает? Может, тебе повезет отыскать труп того паладина. Может, они до сих пор при нем – если его, конечно, не обчистили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите ключ к местонахождению самоцветов в глубинах Ульдамана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, вам-таки удалось отыскать останки паладина, о которых говорил Дран. Обыскав их, вы находите дневник паладина. Дневник в плохом состоянии, большая часть страниц перепачкана запекшейся кровью. Но и оставшийся текст – сплошная галиматья. Похоже, это язык людей.$B$BПридется вам найти кого-то, кто сможет это перевести.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2298,'Королевская облава','И вот собрались мы уже разрабатывать фазу III, когда вломились несколько болванов Магни, стали нести какую-то чушь насчет воровства и что они арестуют некоторых членов Тайного Круга.$B$BДа только поди возьми старика Черную Бороду! Разборка пошла нешуточная, и каким-то образом всплыло твое имя!$B$BХочешь совет? Бери первого грифона из Стальгорна и дуй в Штормград. Иди в Старый город и там переговори с моим старым приятелем Рензиком Ножом.','Отправляйтесь в Штормград и найдите Рензика Ножа.','Всегда рад видеть в наших рядах ребят Хальфдана!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королевская облава',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И вот собрались мы уже разрабатывать фазу III, когда вломились несколько болванов Магни, стали нести какую-то чушь насчет воровства и что они арестуют некоторых членов Тайного Круга.$B$BДа только поди возьми старика Черную Бороду! Разборка пошла нешуточная, и каким-то образом всплыло твое имя!$B$BХочешь совет? Бери первого грифона из Стальгорна и дуй в Штормград. Иди в Старый город и там переговори с моим старым приятелем Рензиком Ножом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Штормград и найдите Рензика Ножа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Всегда рад видеть в наших рядах ребят Хальфдана!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2299,'К Хальфдану!','Где тебя носило, $n? Хальфдан всюду тебя искал. Мы уж подумали, что король забил тебя в кандалы.$B$BДуй в Стальгорн как можно быстрее и поговори с Хальфданом!','Отправляйтесь в Стальгорн и поговорите с Хальфданом Чернобородом.','Говори тише, $N, стража может услышать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К Хальфдану!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Где тебя носило, $n? Хальфдан всюду тебя искал. Мы уж подумали, что король забил тебя в кандалы.$B$BДуй в Стальгорн как можно быстрее и поговори с Хальфданом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Стальгорн и поговорите с Хальфданом Чернобородом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говори тише, $N, стража может услышать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2300,'ШРУ','Слушай, рыбка, тебя тут Рензик искал.$B$BНа твоем месте я не заставлял бы его ждать – все-таки он правая рука Матиаса...','Отправляйтесь в Штормград и разыщите Рензика Ножа.','Как насчет того, чтобы приступить к работе? Или хочешь сначала вздремнуть?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ШРУ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, рыбка, тебя тут Рензик искал.$B$BНа твоем месте я не заставлял бы его ждать – все-таки он правая рука Матиаса...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Штормград и разыщите Рензика Ножа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как насчет того, чтобы приступить к работе? Или хочешь сначала вздремнуть?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2318,'Трудности перевода','Зайдя в окончательный тупик, ты приходишь к выводу, что тебе нужна книга, написанная на понятном тебе языке. Перевести ее, к сожалению, может далеко не каждый. Ближайший к тебе такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных землях. Начать, пожалуй, стоит оттуда.','Найдите кого-нибудь, кто сможет перевести для вас дневник паладина. Ближайший к вам такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных землях.','Могучий|3-6($C), я знаю зачем Вы здесь, в Бесплодных землях. Я знаю, что Вам нужны мои умения по части языков. Вы – в поисках частей того ожерелья, которое вы нашли в Ульдамане.$B$BУдивлены? Не стоит – знать такие вещи – моя работа. Вместо этого давайте обсудим, что Вы сделаете для того, чтобы перевести дневник. Доверяйте мне – я – единственный, кто может перевести его.$B$BТак что позвольте мне сделать вам лучшее предложение, чем может Дран Дрофферз и можете без помех продолжать переговоры с ними. Заинтригованы?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трудности перевода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зайдя в окончательный тупик, ты приходишь к выводу, что тебе нужна книга, написанная на понятном тебе языке. Перевести ее, к сожалению, может далеко не каждый. Ближайший к тебе такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных землях. Начать, пожалуй, стоит оттуда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите кого-нибудь, кто сможет перевести для вас дневник паладина. Ближайший к вам такой умелец, скорее всего, найдется в Каргате, форпосте в Бесплодных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Могучий|3-6($C), я знаю зачем Вы здесь, в Бесплодных землях. Я знаю, что Вам нужны мои умения по части языков. Вы – в поисках частей того ожерелья, которое вы нашли в Ульдамане.$B$BУдивлены? Не стоит – знать такие вещи – моя работа. Вместо этого давайте обсудим, что Вы сделаете для того, чтобы перевести дневник. Доверяйте мне – я – единственный, кто может перевести его.$B$BТак что позвольте мне сделать вам лучшее предложение, чем может Дран Дрофферз и можете без помех продолжать переговоры с ними. Заинтригованы?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2338,'Трудности перевода','Скупщикам Дрофферсу и Сыновьям не хватит умения, чтобы восстановить чары на ожерелье, а вот я могу это сделать. Только дай мне изучить его, чтобы я научился делать подобные. Одолжи мне его на время, а я переведу для тебя дневник. Пока будешь искать камни, я как раз успею изучить ожерелье. $B$BЭто выгодно нам обоим. Ну, что скажешь?','Одолжите ожерелье Джаркалу. Взамен он переведет дневник.','Благодарю тебя, секрет ожерелий разгадать несложно, если иметь достаточно времени, чтобы изучить всего одно из них.$B$BА теперь погоди еще минутку, я произнесу заклинание, чтобы быстро перевести дневник с человеческого языка на понятный тебе. Я тролль слова, спроси кого хочешь в Орде, и тебе скажут: Джаркалу Замшелому Клыку можно доверять! Ну-с, приступим...','Молодец, $Gумненький:умненькая; $C, чуешь свою выгоду! Так мы оба получим то, что нам нужно, а скупщики Дрофферс и Сыновья будут думать, что и они получили свое.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трудности перевода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скупщикам Дрофферсу и Сыновьям не хватит умения, чтобы восстановить чары на ожерелье, а вот я могу это сделать. Только дай мне изучить его, чтобы я научился делать подобные. Одолжи мне его на время, а я переведу для тебя дневник. Пока будешь искать камни, я как раз успею изучить ожерелье. $B$BЭто выгодно нам обоим. Ну, что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одолжите ожерелье Джаркалу. Взамен он переведет дневник.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, секрет ожерелий разгадать несложно, если иметь достаточно времени, чтобы изучить всего одно из них.$B$BА теперь погоди еще минутку, я произнесу заклинание, чтобы быстро перевести дневник с человеческого языка на понятный тебе. Я тролль слова, спроси кого хочешь в Орде, и тебе скажут: Джаркалу Замшелому Клыку можно доверять! Ну-с, приступим...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Молодец, $Gумненький:умненькая; $C, чуешь свою выгоду! Так мы оба получим то, что нам нужно, а скупщики Дрофферс и Сыновья будут думать, что и они получили свое.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2339,'Найти самоцветы и источник энергии','Вот и перевод, ты можешь $gсам:сама; прочесть его. Там говорится, что рубин спрятан дворфами, топаз спрятали трогги, а сапфир прикарманил трогг по имени Гримлок. $B$BПослушай-ка, тебе потребуется источник энергии, чтобы ожерелье вновь заработало. Дран Дрофферс об этом даже не подозревает. Чтобы найти такой источник, отправляйся в Ульдаман, спустись в самую глубину и убей самую сильную тварь, которую сможешь найти. $B$BУверен, у нее ты и найдешь источник энергии!','Добудьте все три самоцвета и источник энергии для ожерелья из Ульдамана и принесите их Джаркалу Замшелому Клыку в Каргат. Джаркал считает, что источник энергии можно найти у самой сильной твари в Ульдамане. $B$BИз дневника следует... $B* Рубин спрятан на огражденной завалами территории Тенегорна. $B*Топаз спрятан в урне на территорях троггов под боком у дворфов Альянса.$B*Сапфир забрал Гримлок, старейшина троггов.','Отлично, |3-6($C)! Скоро мы пожнем плоды наших трудов. Я закончил работу над ожерельем и уверен, что теперь смогу создать такое же.$B$BНо сначала я использую специальное заклинание, чтобы быстро исследовать эти самоцветы, прежде чем ты унесешь их и ожерелье в Оргриммар. Это займет всего пару минут.','Путешествие в Ульдаман в твоих интересах – тебе нужны самоцветы и источник энергии, чтобы вернуть ожерелью волшебную силу.$B$BТы доставишь камни головорезам в Оргриммар, а я сохраню источник энергии, поскольку именно он заставит ожерелье снова работать...','Вернитесь к Джаркалу Замшелому Клыку в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти самоцветы и источник энергии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот и перевод, ты можешь $gсам:сама; прочесть его. Там говорится, что рубин спрятан дворфами, топаз спрятали трогги, а сапфир прикарманил трогг по имени Гримлок. $B$BПослушай-ка, тебе потребуется источник энергии, чтобы ожерелье вновь заработало. Дран Дрофферс об этом даже не подозревает. Чтобы найти такой источник, отправляйся в Ульдаман, спустись в самую глубину и убей самую сильную тварь, которую сможешь найти. $B$BУверен, у нее ты и найдешь источник энергии!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте все три самоцвета и источник энергии для ожерелья из Ульдамана и принесите их Джаркалу Замшелому Клыку в Каргат. Джаркал считает, что источник энергии можно найти у самой сильной твари в Ульдамане. $B$BИз дневника следует... $B* Рубин спрятан на огражденной завалами территории Тенегорна. $B*Топаз спрятан в урне на территорях троггов под боком у дворфов Альянса.$B*Сапфир забрал Гримлок, старейшина троггов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, |3-6($C)! Скоро мы пожнем плоды наших трудов. Я закончил работу над ожерельем и уверен, что теперь смогу создать такое же.$B$BНо сначала я использую специальное заклинание, чтобы быстро исследовать эти самоцветы, прежде чем ты унесешь их и ожерелье в Оргриммар. Это займет всего пару минут.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Путешествие в Ульдаман в твоих интересах – тебе нужны самоцветы и источник энергии, чтобы вернуть ожерелью волшебную силу.$B$BТы доставишь камни головорезам в Оргриммар, а я сохраню источник энергии, поскольку именно он заставит ожерелье снова работать...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джаркалу Замшелому Клыку в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2340,'Принести самоцветы','Ожерелье будет работать, только если самоцветы будут в сродстве с металлом оправы. Этот источник энергии поможет вернуть ожерелью магическую силу... Надеюсь. $B$BЯ с удовольствием предоставлю тебе камни, подходящие к ожерелью, если окажется, что источник энергии действительно работает. $B$BОтправляйся в Оргриммар и выполни, что $gобещал:обещала; скупщикам Дрофферсу и Сыновьям. Никому не сообщай о наших договоренностях, и, возможно, к твоему возвращению я приготовлю сюрприз.','Доставьте ожерелье и драгоценности Драну Дрофферсу в Оргриммар.','Ну, все в порядке. Я могу оставить себе и мешок? Спасибо, премного благодарен.$B$BИ все же лучший трофей – это ожерелье! Не строй такую кислую мину, оно было бы тебе не к лицу!$B$BСделка есть сделка, поэтому вот твоя награда за принесенные трофеи. Что ж, с этим покончено, можешь заглядывать иногда, если понадобится работа. А пока будь $Gлюбезен:любезна;, покинь помещение!','Смотри-ка, кто пришел, кто потратил свое драгоценное время, чтобы заглянуть к Драну Дрофферсу! Будем надеяться, твой визит не станет пустой тратой времени для меня. Пока не получу, что просил, платить не буду, имей это в виду. И можешь не сомневаться – перепроверю все, что ты принес дважды и трижды!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Принести самоцветы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ожерелье будет работать, только если самоцветы будут в сродстве с металлом оправы. Этот источник энергии поможет вернуть ожерелью магическую силу... Надеюсь. $B$BЯ с удовольствием предоставлю тебе камни, подходящие к ожерелью, если окажется, что источник энергии действительно работает. $B$BОтправляйся в Оргриммар и выполни, что $gобещал:обещала; скупщикам Дрофферсу и Сыновьям. Никому не сообщай о наших договоренностях, и, возможно, к твоему возвращению я приготовлю сюрприз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте ожерелье и драгоценности Драну Дрофферсу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, все в порядке. Я могу оставить себе и мешок? Спасибо, премного благодарен.$B$BИ все же лучший трофей – это ожерелье! Не строй такую кислую мину, оно было бы тебе не к лицу!$B$BСделка есть сделка, поэтому вот твоя награда за принесенные трофеи. Что ж, с этим покончено, можешь заглядывать иногда, если понадобится работа. А пока будь $Gлюбезен:любезна;, покинь помещение!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Смотри-ка, кто пришел, кто потратил свое драгоценное время, чтобы заглянуть к Драну Дрофферсу! Будем надеяться, твой визит не станет пустой тратой времени для меня. Пока не получу, что просил, платить не буду, имей это в виду. И можешь не сомневаться – перепроверю все, что ты принес дважды и трижды!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2341,'Пропавшее ожерелье, этап 3','Полдела сделано. Дран и Мальтон Дрофферсы уже ссорятся из-за новой добычи. Теперь нужно сходить в Бесплодные земли – возможно, у Джаркала Замшелого Клыка из Каргата найдется для вас особая награда...','Навестите Джаркала Замшелого Клыка в Каргате.','Источник силы, полученный от тебя, превзошел все мои ожидания! Мне удалось сделать два ожерелья – тебе и мне, – и в нем осталось достаточно энергии, чтобы сделать как минимум еще три! Я на этом неплохо наживусь, а семейка Дрофферсов ничего и не узнает!$B$BВот, держи. Я тебе очень благодарен... а это знак моей благодарности!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшее ожерелье, этап 3',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полдела сделано. Дран и Мальтон Дрофферсы уже ссорятся из-за новой добычи. Теперь нужно сходить в Бесплодные земли – возможно, у Джаркала Замшелого Клыка из Каргата найдется для вас особая награда...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Навестите Джаркала Замшелого Клыка в Каргате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Источник силы, полученный от тебя, превзошел все мои ожидания! Мне удалось сделать два ожерелья – тебе и мне, – и в нем осталось достаточно энергии, чтобы сделать как минимум еще три! Я на этом неплохо наживусь, а семейка Дрофферсов ничего и не узнает!$B$BВот, держи. Я тебе очень благодарен... а это знак моей благодарности!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2342,'Возвращенные сокровища','Гарреттам не пристало мести загоны для летучих мышей такой метлой! Мерзкая работенка позволила мне заработать немного денег, и я хочу истратить их на улучшение своего положения.$b$bФамильное "оружие" Гарреттов заперто в нашем сундуке в Южном зале Ульдамана. Там наша семья трудилась долгие годы. Без него я застряну тут навеки – в буквальном смысле – и буду мести за проклятыми летучими мышами до скончания веков.$b$bПринеси мне наше сокровище! Помоги вернуть то, что положено мне по праву рождения!','Принесите Патрику Гарретту в Подгород фамильное сокровище из сундука в Южном зале Ульдамана.','Наконец-то – метла, достойная Гарретта. Не зря я потратил на тебя деньги!$B$BВы слышите меня, летучие мыши? Теперь у меня есть истинное оружие семьи Гарреттов! Трепещите, проклятые пискуны!','Уборке нет конца... летучие мыши смеются надо мной и моей метлой. Скажи, ты ведь принесешь мне фамильное сокровище? Я готов отдать тебе все мое серебро – неужели этого недостаточно?!','Вернитесь к Патрику Гарретту в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращенные сокровища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гарреттам не пристало мести загоны для летучих мышей такой метлой! Мерзкая работенка позволила мне заработать немного денег, и я хочу истратить их на улучшение своего положения.$b$bФамильное "оружие" Гарреттов заперто в нашем сундуке в Южном зале Ульдамана. Там наша семья трудилась долгие годы. Без него я застряну тут навеки – в буквальном смысле – и буду мести за проклятыми летучими мышами до скончания веков.$b$bПринеси мне наше сокровище! Помоги вернуть то, что положено мне по праву рождения!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Патрику Гарретту в Подгород фамильное сокровище из сундука в Южном зале Ульдамана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то – метла, достойная Гарретта. Не зря я потратил на тебя деньги!$B$BВы слышите меня, летучие мыши? Теперь у меня есть истинное оружие семьи Гарреттов! Трепещите, проклятые пискуны!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уборке нет конца... летучие мыши смеются надо мной и моей метлой. Скажи, ты ведь принесешь мне фамильное сокровище? Я готов отдать тебе все мое серебро – неужели этого недостаточно?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Патрику Гарретту в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2358,'Рога Незры','Много лет назад рога Незры были похищены из поместья Черный Ворон. Я искал их по всем морям и континентам и только теперь выяснил, что они все время находились у этих ничтожных тварей.$B$BУбей всех орков Черной горы, которые встретятся тебе на пути, забери у них рога Незры и возвращайся ко мне в Приозерье.$B$BОкажи мне эту услугу, и заслужишь благодарность всех Черных Воронов.','Верните рога Незры Арантиру в Приозерье.','Отказать Черному Ворону в артефакте значило бы отказать в собственное существование. Молодец, |3-6($C). Вы еще можете прогуляться среди убийц Черного Ворона.$B$BКогда я был молодым |3-6($C), путешествующим по Темным берегам, я обнаружил чай, который восполняет энергию в бою. Он хорошо служил мне на протяжении многих лет, и теперь я передаю вам вкус чая из чертополоха. Выпей его, когда устанешь, $N, и снова сражайся отважно!','У тебя есть рога принца демонов?','Вернитесь к Арантиру в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рога Незры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много лет назад рога Незры были похищены из поместья Черный Ворон. Я искал их по всем морям и континентам и только теперь выяснил, что они все время находились у этих ничтожных тварей.$B$BУбей всех орков Черной горы, которые встретятся тебе на пути, забери у них рога Незры и возвращайся ко мне в Приозерье.$B$BОкажи мне эту услугу, и заслужишь благодарность всех Черных Воронов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните рога Незры Арантиру в Приозерье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отказать Черному Ворону в артефакте значило бы отказать в собственное существование. Молодец, |3-6($C). Вы еще можете прогуляться среди убийц Черного Ворона.$B$BКогда я был молодым |3-6($C), путешествующим по Темным берегам, я обнаружил чай, который восполняет энергию в бою. Он хорошо служил мне на протяжении многих лет, и теперь я передаю вам вкус чая из чертополоха. Выпей его, когда устанешь, $N, и снова сражайся отважно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть рога принца демонов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Арантиру в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2359,'Башня Клейвена','Я за этой башней уже не первую неделю наблюдаю, $n. Недавно прошла крупная поставка из Сумеречного леса, а вместе с ней явились эти стражи.$b$bКто такие? Мы можем только гадать. Одно я тебе скажу: это не люди.$b$bКак бы то ни было, там был сундук – и, как я полагаю, эта мерзость именно его и охраняет. А ключ от сундука – у того зомби с шипами.$b$bДобудь этот ключ, проберись в башню и выясни, что находится в том сундуке. Находку отнесешь Матиасу.','Добудьте ключ Башни Братства Справедливости, проберитесь в башню и выясните, каково содержимое сундука из Сумеречного леса. Отнесите найденные вещи Матиасу Шоу в Штормград. Почитайте дневник Кеарнен, чтобы больше узнать о башне.','Это объясняет присутствие мертвяков из Братства Справедливости, которых вы с Кеарнен видели рядом с башней. Это может объяснить и вовлеченность Торговой Компании в дела Братства Справедливости и эти странные поставки из Сумеречного леса.$B$BКак явствует из этой книги, тролли Занзила в Тернистой долине нашли возможность поднимать мертвых с помощью зелий... выражаясь точнее – ядов.$B$BВы бесполезны для ШРУ, если у вас нет четкого представления о ядах, $N, особенно когда рецепт того, как поднимать нежить, почти у нас в руках.','Есть какие-то новости от посланницы Кеарнен?','Вернитесь к мастеру Матиасу Шоу в ШРУ, что в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башня Клейвена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я за этой башней уже не первую неделю наблюдаю, $n. Недавно прошла крупная поставка из Сумеречного леса, а вместе с ней явились эти стражи.$b$bКто такие? Мы можем только гадать. Одно я тебе скажу: это не люди.$b$bКак бы то ни было, там был сундук – и, как я полагаю, эта мерзость именно его и охраняет. А ключ от сундука – у того зомби с шипами.$b$bДобудь этот ключ, проберись в башню и выясни, что находится в том сундуке. Находку отнесешь Матиасу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ключ Башни Братства Справедливости, проберитесь в башню и выясните, каково содержимое сундука из Сумеречного леса. Отнесите найденные вещи Матиасу Шоу в Штормград. Почитайте дневник Кеарнен, чтобы больше узнать о башне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это объясняет присутствие мертвяков из Братства Справедливости, которых вы с Кеарнен видели рядом с башней. Это может объяснить и вовлеченность Торговой Компании в дела Братства Справедливости и эти странные поставки из Сумеречного леса.$B$BКак явствует из этой книги, тролли Занзила в Тернистой долине нашли возможность поднимать мертвых с помощью зелий... выражаясь точнее – ядов.$B$BВы бесполезны для ШРУ, если у вас нет четкого представления о ядах, $N, особенно когда рецепт того, как поднимать нежить, почти у нас в руках.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть какие-то новости от посланницы Кеарнен?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Матиасу Шоу в ШРУ, что в Штормграде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2360,'Матиас и Братство Справедливости','Произошло то, чего я ожидал, $n. Разведотдел ШРУ сообщает, что Братство Справедливости что-то затевает в Западном Крае.$b$bСкладывается впечатление, что братство захватило покинутую сторожевую башню Альянса к юго-востоку от Сторожевого холма и использует ее как базу для ввоза контрабанды из Красногорья.$b$bОтправляйтесь в Западный Край и свяжитесь с агентом Кеарнен для подробного доклада. Она там прячется, неподалеку от башни.$b$bИ кстати, $n, если вас раскроют – вы никогда не слышали о ШРУ...','Найдите агента Кеарнен в Западном Крае и поговорите с ней.','Наконец-то Матиас прислал еще одного агента мне в помощь. Ну, надеюсь, он готов к вороху неприятных новостей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Матиас и Братство Справедливости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Произошло то, чего я ожидал, $n. Разведотдел ШРУ сообщает, что Братство Справедливости что-то затевает в Западном Крае.$b$bСкладывается впечатление, что братство захватило покинутую сторожевую башню Альянса к юго-востоку от Сторожевого холма и использует ее как базу для ввоза контрабанды из Красногорья.$b$bОтправляйтесь в Западный Край и свяжитесь с агентом Кеарнен для подробного доклада. Она там прячется, неподалеку от башни.$b$bИ кстати, $n, если вас раскроют – вы никогда не слышали о ШРУ...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите агента Кеарнен в Западном Крае и поговорите с ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то Матиас прислал еще одного агента мне в помощь. Ну, надеюсь, он готов к вороху неприятных новостей.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (2361,'Восстановление ожерелья','Я с великой радостью вручаю тебе это ожерелье, $Gмогучий:могучая; |3-6($C). Ты $Gоказал:оказала; мне неоценимую услугу, и я благодарен тебе за это. Носи же его с гордостью и не забывай при этом все время упоминать о том, кто сделал его для тебя!$B$BДа, если еще добавишь, что на ожерелье нет проклятия, это будет великолепно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстановление ожерелья',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я с великой радостью вручаю тебе это ожерелье, $Gмогучий:могучая; |3-6($C). Ты $Gоказал:оказала; мне неоценимую услугу, и я благодарен тебе за это. Носи же его с гордостью и не забывай при этом все время упоминать о том, кто сделал его для тебя!$B$BДа, если еще добавишь, что на ожерелье нет проклятия, это будет великолепно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2378,'Поиски Изувеченной Длани','Отправляйтесь в Оргриммар и поговорите с Шентулом в Расселине Теней.','Так вот кого могучие союзники прислали Шентулу... Не впечатляет…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Изувеченной Длани',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Оргриммар и поговорите с Шентулом в Расселине Теней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так вот кого могучие союзники прислали Шентулу... Не впечатляет…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2379,'Зандо\'зан','Одной твоей решимости еще недостаточно, чтобы преодолеть препятствия, которые ждут впереди.$b$bПоговори с Зандо\'заном, чтобы начать учиться на агента Изувеченной Длани.$b$bЛишь овладев навыками незаметности и коварства, ты сможешь сделать следующий шаг.','Поговорите с Зандо\'заном в Расселине Теней.','Быть может, Зандо\'зан ошибся. Зандо\'зан просит прощения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандо\'зан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одной твоей решимости еще недостаточно, чтобы преодолеть препятствия, которые ждут впереди.$b$bПоговори с Зандо\'заном, чтобы начать учиться на агента Изувеченной Длани.$b$bЛишь овладев навыками незаметности и коварства, ты сможешь сделать следующий шаг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зандо\'заном в Расселине Теней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Быть может, Зандо\'зан ошибся. Зандо\'зан просит прощения.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2380,'В Оргриммар!','Ты, конечно, далеко еще не специалист по скрытности и всяким уловкам, однако же тебе есть куда расти. По крайней мере, начальство явно обратило на тебя внимание: сам великий Шентул запомнил твое имя!$b$bСтупай на север – эта дорога ведет в Оргриммар. Отыщи там в Расселине Теней Шентула и поговори с ним.','Поговорите с Шентулом в Расселине Теней в Оргриммаре.','Очень важно, чтобы Изувеченная Длань сохраняла бдительность перед лицом перемен, которые Тралл намеревается ввести в Орде. Числом тут не возьмешь – для нас главное незаметность и разнообразные уловки!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Оргриммар!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты, конечно, далеко еще не специалист по скрытности и всяким уловкам, однако же тебе есть куда расти. По крайней мере, начальство явно обратило на тебя внимание: сам великий Шентул запомнил твое имя!$b$bСтупай на север – эта дорога ведет в Оргриммар. Отыщи там в Расселине Теней Шентула и поговори с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Шентулом в Расселине Теней в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень важно, чтобы Изувеченная Длань сохраняла бдительность перед лицом перемен, которые Тралл намеревается ввести в Орде. Числом тут не возьмешь – для нас главное незаметность и разнообразные уловки!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2381,'Что ж, по крайней мере, ты пока цел. А сокровище нашел?','Вернитесь к Рениксу Презренному в Кабестан, что в Степях.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ж, по крайней мере, ты пока цел. А сокровище нашел?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рениксу Презренному в Кабестан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2382,'Реникс из Кабестана','Зандо\'зан это видел! Да, день близок! Смерть Тралла... кинжал в его спине, яд в его кубке... Но Зандо\'зан слишком много болтает.$b$b$n! У Зандо\'зана есть поручение для тебя! $n $gдолжен:должна; отправиться в Кабестан, к востоку от Перекрестка, и поговорить с Рениксом Презренным. Ступай!','Поговорите с Рениксом Презренным в Кабестане, что в Степях.','Как, опять? Предыдущие пятеро, кого прислал ко мне этот чокнутый тролль, пошли на корм акулам. Ну что ж, будем надеяться, что тебе повезет…','У вас есть для меня посылочка?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реникс из Кабестана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зандо\'зан это видел! Да, день близок! Смерть Тралла... кинжал в его спине, яд в его кубке... Но Зандо\'зан слишком много болтает.$b$b$n! У Зандо\'зана есть поручение для тебя! $n $gдолжен:должна; отправиться в Кабестан, к востоку от Перекрестка, и поговорить с Рениксом Презренным. Ступай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рениксом Презренным в Кабестане, что в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как, опять? Предыдущие пятеро, кого прислал ко мне этот чокнутый тролль, пошли на корм акулам. Ну что ж, будем надеяться, что тебе повезет…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть для меня посылочка?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2398,'Потерянные дворфы','Раскопки в Ульдамане не всегда были захвачены троггами. Изначально мы, дворфы Стальгорна, вели здесь работы, но потом... Потом появились эти твари. Они прибыли столь быстро и в таком количестве, что дворфы не смогли ничего поделать.$B$BЧестно говоря, их нападение было настолько внезапным, что многие наши люди могли не успеть вырваться из осады. Боюсь, они по сей день остаются в ловушке в тылу врага.$B$BМой друг Бейлог руководил небольшим отрядом дворфов в глубине раскопа прямо перед нападением троггов. Если он и его ребята живы, то я хочу, чтобы ты $gнашел:нашла; их.','Найдите Бейлога в Ульдамане.','Ты как раз вовремя! Я уже боялся, что проспорю Олафу!$B$BОн бился об заклад, что его борода достанет до колен, прежде чем мы увидим живое лицо, |3-6($r).$B$BИ вот, ты здесь, а бороде Олафа еще до колен осталась пара дюймов.$B$BСпасибо, $n! Я обязательно поделюсь с тобой выигрышем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянные дворфы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раскопки в Ульдамане не всегда были захвачены троггами. Изначально мы, дворфы Стальгорна, вели здесь работы, но потом... Потом появились эти твари. Они прибыли столь быстро и в таком количестве, что дворфы не смогли ничего поделать.$B$BЧестно говоря, их нападение было настолько внезапным, что многие наши люди могли не успеть вырваться из осады. Боюсь, они по сей день остаются в ловушке в тылу врага.$B$BМой друг Бейлог руководил небольшим отрядом дворфов в глубине раскопа прямо перед нападением троггов. Если он и его ребята живы, то я хочу, чтобы ты $gнашел:нашла; их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Бейлога в Ульдамане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты как раз вовремя! Я уже боялся, что проспорю Олафу!$B$BОн бился об заклад, что его борода достанет до колен, прежде чем мы увидим живое лицо, |3-6($r).$B$BИ вот, ты здесь, а бороде Олафа еще до колен осталась пара дюймов.$B$BСпасибо, $n! Я обязательно поделюсь с тобой выигрышем.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (2399,'Росток папоротника','Папоротник, который Деналан посадил у себя в саду, проклюнулся и вырос. Ростки так и просят, чтобы их скорее собрали...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Росток папоротника',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Папоротник, который Деналан посадил у себя в саду, проклюнулся и вырос. Ростки так и просят, чтобы их скорее собрали...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2418,'Силовые камни','Есть у меня зуб на этих дворфов Тенегорна! Пару лет назад они пригласили меня в крепость Ангор, чтобы я исследовал для них два образца прелюбопытнейших камней, привезенных с ульдаманского раскопа. Я провел исследования, и вообрази, что это было? Энергия! Каждый камень был мощнейшим источником энергии в сжатом, потенцированном виде – нужно только знать, как правильно высвободить ее! Чего только не найдешь в Ульдамане... $B$BВ общем, как только я рассказал об этом дворфам, они вышвырнули меня из крепости и направились в Ульдаман за чудесными камнями. $B$BМне бы такие, знаешь ли, тоже пригодились. Принеси мне несколько обоих видов, и я щедро вознагражу тебя.','Принесите 8 дентриевых силовых камней и 8 энелиевых силовых камней Ригглфаззу в Бесплодные земли.','Вернитесь к Ригглфаззу в Долину Клыков, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силовые камни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть у меня зуб на этих дворфов Тенегорна! Пару лет назад они пригласили меня в крепость Ангор, чтобы я исследовал для них два образца прелюбопытнейших камней, привезенных с ульдаманского раскопа. Я провел исследования, и вообрази, что это было? Энергия! Каждый камень был мощнейшим источником энергии в сжатом, потенцированном виде – нужно только знать, как правильно высвободить ее! Чего только не найдешь в Ульдамане... $B$BВ общем, как только я рассказал об этом дворфам, они вышвырнули меня из крепости и направились в Ульдаман за чудесными камнями. $B$BМне бы такие, знаешь ли, тоже пригодились. Принеси мне несколько обоих видов, и я щедро вознагражу тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 дентриевых силовых камней и 8 энелиевых силовых камней Ригглфаззу в Бесплодные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ригглфаззу в Долину Клыков, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2438,'Изумрудный ловец снов','Некогда Гэролас Талветрен, страж друидов обители Бен\'этиль, подарил мне изумрудного ловца снов. Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит.$B$BУвы, мне не удалось забрать его из моего шкафчика в Деревне Звездного Ветра... Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там.$B$BМожет, тебе удастся добыть моего ловца снов, |3-6($c)?','Добудьте изумрудного ловца снов.','Вернитесь к Таллонкаю Гибкому Корню в Доланаар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изумрудный ловец снов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некогда Гэролас Талветрен, страж друидов обители Бен\'этиль, подарил мне изумрудного ловца снов. Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит.$B$BУвы, мне не удалось забрать его из моего шкафчика в Деревне Звездного Ветра... Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там.$B$BМожет, тебе удастся добыть моего ловца снов, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте изумрудного ловца снов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таллонкаю Гибкому Корню в Доланаар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2439,'Платиновые диски','Это невероятная находка. Согласно этим дискам, Древние Титаны, или Создатели, имеют отношение к нашему чудесному возникновению! Нам нужно уделить как можно больше времени их изучению.$B$BА вас, $Gгероический:героическая:c; |3-6($c), прошу принять этот сертификат и отнести его Дините Каменной Мантии в хранилище. По нему вы получите то, что, на мой взгляд, будет достойной наградой за такую находку!$B$BКогда будете готовы, возвращайтесь ко мне – у Лиги исследователей еще много работы для вас!','Отнесите наградной сертификат Дините Каменной Мантии в хранилище Стальгорна.','Ах, сертификат Лиги Исследователей... и весьма ценный, смею заметить.$B$BЛига Исследователей дает мне полномочия предложить вам выбрать себе награду прямо из хранилища. Награда ваша, так что выбирайте – либо пять больших флаконов с лечебным зельем, либо пять средних флаконов с зельем маны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Платиновые диски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это невероятная находка. Согласно этим дискам, Древние Титаны, или Создатели, имеют отношение к нашему чудесному возникновению! Нам нужно уделить как можно больше времени их изучению.$B$BА вас, $Gгероический:героическая:c; |3-6($c), прошу принять этот сертификат и отнести его Дините Каменной Мантии в хранилище. По нему вы получите то, что, на мой взгляд, будет достойной наградой за такую находку!$B$BКогда будете готовы, возвращайтесь ко мне – у Лиги исследователей еще много работы для вас!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите наградной сертификат Дините Каменной Мантии в хранилище Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, сертификат Лиги Исследователей... и весьма ценный, смею заметить.$B$BЛига Исследователей дает мне полномочия предложить вам выбрать себе награду прямо из хранилища. Награда ваша, так что выбирайте – либо пять больших флаконов с лечебным зельем, либо пять средних флаконов с зельем маны.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2440,'Платиновые диски','Я сосредоточу свои усилия на исследовании этих дисков, и со временем они раскроют мне свою тайну.$B$BА тебя $n, я награжу за то, что ты $Gобратил:обратила; на них мое внимание. Отнеси этот сертификат Бене Заиндевевшее Копыто, наставнице алхимиков в Громовом Утесе. Она даст тебе один интересный предмет, который наверняка тебе понравится, а еще она даст тебе на выбор зелий из моих личных запасов.$B$BВозвращайся поскорее, ибо я чувствую, что мы стоим на пороге великого открытия.','Отнесите наградной сертификат Бене Заиндевевшее Копыто в Громовой Утес.','Что же, $N, ты, видать, $Gугодил:угодила; Ведуну Искателю Истины, принеся ему ту штуку. Так что вдобавок ты получишь в награду зелья из его личного хранилища. Можешь выбрать или 5 наилучших целебных зелий, либо 5 сильных зелий маны.','Привет тебе, $C! Ты $Gпришел:пришла; сюда учиться алхимии или за чем-то еще?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Платиновые диски',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сосредоточу свои усилия на исследовании этих дисков, и со временем они раскроют мне свою тайну.$B$BА тебя $n, я награжу за то, что ты $Gобратил:обратила; на них мое внимание. Отнеси этот сертификат Бене Заиндевевшее Копыто, наставнице алхимиков в Громовом Утесе. Она даст тебе один интересный предмет, который наверняка тебе понравится, а еще она даст тебе на выбор зелий из моих личных запасов.$B$BВозвращайся поскорее, ибо я чувствую, что мы стоим на пороге великого открытия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите наградной сертификат Бене Заиндевевшее Копыто в Громовой Утес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что же, $N, ты, видать, $Gугодил:угодила; Ведуну Искателю Истины, принеся ему ту штуку. Так что вдобавок ты получишь в награду зелья из его личного хранилища. Можешь выбрать или 5 наилучших целебных зелий, либо 5 сильных зелий маны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет тебе, $C! Ты $Gпришел:пришла; сюда учиться алхимии или за чем-то еще?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2458,'Надежное прикрытие','Торговая Компания... Доводилось тебе слышать про такую?$b$bМы в течение года пытались внедрить агента в их ряды. Это было непросто, но мы преуспели.$b$bНедавно мы получили сведения, что Торговая Компания затевает что-то крупное. Ступай к башне Торговой Компании, которая стоит к северу от Нефтяного болота, и свяжись с нашим тайным агентом, надсмотрщиком Физзулом.$b$bКогда найдешь башню, используй это сигнальное ружье, потом подойди к Физзулу и отдай ему честь, как принято в Изувеченной Длани.','Отыщите башню Торговой Компании к северу от Нефтяного болота и вступите в контакт с тайным агентом Изувеченной Длани, надсмотрщиком Физзулом.$b$bВозле башни выстрелите из сигнального ружья ДВА раза, потом подойдите к надсмотрщику Физзулу и отдайте честь, как принято в Изувеченной Длани (команда /честь).$b$bВсе нужно делать строго по порядку – Физзул убивает всех, кто кажется ему подозрительным.','Приятно видеть в здешних местах еще одного агента Изувеченной Длани! Вот только боюсь, как бы твоих вспышек не заметил кто-то лишний.$B$BВ следующий раз, когда тебе нужно будет со мной поговорить, дважды свистни в этот свисток, и я пойму, что это свои.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надежное прикрытие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Торговая Компания... Доводилось тебе слышать про такую?$b$bМы в течение года пытались внедрить агента в их ряды. Это было непросто, но мы преуспели.$b$bНедавно мы получили сведения, что Торговая Компания затевает что-то крупное. Ступай к башне Торговой Компании, которая стоит к северу от Нефтяного болота, и свяжись с нашим тайным агентом, надсмотрщиком Физзулом.$b$bКогда найдешь башню, используй это сигнальное ружье, потом подойди к Физзулу и отдай ему честь, как принято в Изувеченной Длани.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите башню Торговой Компании к северу от Нефтяного болота и вступите в контакт с тайным агентом Изувеченной Длани, надсмотрщиком Физзулом.$b$bВозле башни выстрелите из сигнального ружья ДВА раза, потом подойдите к надсмотрщику Физзулу и отдайте честь, как принято в Изувеченной Длани (команда /честь).$b$bВсе нужно делать строго по порядку – Физзул убивает всех, кто кажется ему подозрительным.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно видеть в здешних местах еще одного агента Изувеченной Длани! Вот только боюсь, как бы твоих вспышек не заметил кто-то лишний.$B$BВ следующий раз, когда тебе нужно будет со мной поговорить, дважды свистни в этот свисток, и я пойму, что это свои.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (2459,'Фероситас Пожиратель Снов','Изумруд... Он пропал! Мой ловец снов поврежден!$B$BК северу от деревни Звездного Ветра засела шайка мистиков из племени Кривой Сосны. Я слышал, что их вожак, Фероситас Пожиратель Снов, носил ожерелье, которое светится зеленым в ночи. Теперь, глядя на своего ловца снов, я уверен, что это он украл мой изумруд... Он не понимает, что его сила для него бесполезна.$B$BНайди этот пропавший драгоценный камень, $n. И раз уж ты здесь, истреби заодно и этих зловредных мистиков.','Убейте 7 мистиков из племени Кривой Сосны и найдите пропавший самоцвет.','Пусть Фероситас и эти мистики Кривой Сосны вернут то, что принадлежит мне! Прошу тебя, отними у них изумруд, чтобы я мог восстановить своего ловца снов.','Вернитесь к Таллонкаю Гибкому Корню в Доланаар.','Порча, поразившая племя Кривой Сосны, ставит под угрозу судьбу всех спящих друидов ночных эльфов. Их хрупкие тела уязвимы.','Фероситас Пожиратель Снов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фероситас Пожиратель Снов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изумруд... Он пропал! Мой ловец снов поврежден!$B$BК северу от деревни Звездного Ветра засела шайка мистиков из племени Кривой Сосны. Я слышал, что их вожак, Фероситас Пожиратель Снов, носил ожерелье, которое светится зеленым в ночи. Теперь, глядя на своего ловца снов, я уверен, что это он украл мой изумруд... Он не понимает, что его сила для него бесполезна.$B$BНайди этот пропавший драгоценный камень, $n. И раз уж ты здесь, истреби заодно и этих зловредных мистиков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 мистиков из племени Кривой Сосны и найдите пропавший самоцвет.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пусть Фероситас и эти мистики Кривой Сосны вернут то, что принадлежит мне! Прошу тебя, отними у них изумруд, чтобы я мог восстановить своего ловца снов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таллонкаю Гибкому Корню в Доланаар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Порча, поразившая племя Кривой Сосны, ставит под угрозу судьбу всех спящих друидов ночных эльфов. Их хрупкие тела уязвимы.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Фероситас Пожиратель Снов',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2460,'Приветствие Изувеченной Длани','Теперь, когда ты – разбойник Изувеченной Длани, тебе следует обучиться особому приветствию. Это знак, по которому мы опознаем своих.$b$bСмотри и повторяй за мной.','Повторите приветствие Изувеченной Длани вслед за Шентулом.','$GМолодец:Умница;, $N! Теперь мы можем продолжать.','Приветствие Изувеченной Длани выполнено','Вернитесь к Шентулу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приветствие Изувеченной Длани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты – разбойник Изувеченной Длани, тебе следует обучиться особому приветствию. Это знак, по которому мы опознаем своих.$b$bСмотри и повторяй за мной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Повторите приветствие Изувеченной Длани вслед за Шентулом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N! Теперь мы можем продолжать.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приветствие Изувеченной Длани выполнено',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шентулу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2478,'Миссия: выполнима, но с трудом','Тебе придется украсть ключ от башни у штейгера Силиксиза. Смотри не потеряй его: он мне еще пригодится.$B$BНе забудь: яд ослабил всех в этой башне. Покажи, на что ты $gспособен:способна;, неси хаос и разрушение в стены башни. Убей всех – жалости тут нет места!$B$BКогда внутри останутся лишь кровавые ошметки, возьми сейф Галливикса и укради из него запас смеси Занзила. Отнеси голову Галливикса и смесь Шентулу в Оргриммар.','Украдите ключ от башни у штейгера Силиксиза, убейте двух мертвяков-мутантов Торговой Компании, двух патрульных Торговой Компании и двух смотрителей Торговой Компании.$B$BЛиквидируйте старшего мастера Галливикса, взломайте замок на его сейфе и украдите запас измененной смеси Занзила. Отнесите запас смеси и голову Галливикса Шентулу в Оргриммар и получите следующие указания.','Бедный Физзул, он был прекрасным агентом, одним из лучших. Увы, мы заплатили за победу высокую цену, $N. Да, работа агента Изувеченной Длани опасна.$B$BНо ты отлично $Gсправился:справилась; с заданием, |3-6($C). Хорошо, что тебе удалось выжить. Ты ведь можешь и дальше служить нам.','Докладывай, $N.','Вернитесь к Шентулу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Миссия: выполнима, но с трудом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе придется украсть ключ от башни у штейгера Силиксиза. Смотри не потеряй его: он мне еще пригодится.$B$BНе забудь: яд ослабил всех в этой башне. Покажи, на что ты $gспособен:способна;, неси хаос и разрушение в стены башни. Убей всех – жалости тут нет места!$B$BКогда внутри останутся лишь кровавые ошметки, возьми сейф Галливикса и укради из него запас смеси Занзила. Отнеси голову Галливикса и смесь Шентулу в Оргриммар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите ключ от башни у штейгера Силиксиза, убейте двух мертвяков-мутантов Торговой Компании, двух патрульных Торговой Компании и двух смотрителей Торговой Компании.$B$BЛиквидируйте старшего мастера Галливикса, взломайте замок на его сейфе и украдите запас измененной смеси Занзила. Отнесите запас смеси и голову Галливикса Шентулу в Оргриммар и получите следующие указания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бедный Физзул, он был прекрасным агентом, одним из лучших. Увы, мы заплатили за победу высокую цену, $N. Да, работа агента Изувеченной Длани опасна.$B$BНо ты отлично $Gсправился:справилась; с заданием, |3-6($C). Хорошо, что тебе удалось выжить. Ты ведь можешь и дальше служить нам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Докладывай, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шентулу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2479,'Помощь Хинотта','Отнеси образчик этой смеси Сержу Хинотту на Мельницу Таррен.$b$bЕсли кто сможет тебя исцелить, так это Серж. Он тебя обучит всему, что связано с ядами, – если, конечно, выживешь.','Пойдите на Мельницу Таррен в предгорьях Хилсбрада и доставьте образчик смеси Занзила Сержу Хинотту.$b$bСядьте на дирижабль, идущий до Подгорода, и летите вдоль дороги на юг, через Серебряный бор в сторону Хилсбрада. Следите за знаками.','О, |3-6($C), $Gкакой:какая; ты $Gбледненький:бледненькая;! А чем это от тебя так мерзко благоухает? Я должен выяснить!','Это что такое???') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Хинотта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси образчик этой смеси Сержу Хинотту на Мельницу Таррен.$b$bЕсли кто сможет тебя исцелить, так это Серж. Он тебя обучит всему, что связано с ядами, – если, конечно, выживешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пойдите на Мельницу Таррен в предгорьях Хилсбрада и доставьте образчик смеси Занзила Сержу Хинотту.$b$bСядьте на дирижабль, идущий до Подгорода, и летите вдоль дороги на юг, через Серебряный бор в сторону Хилсбрада. Следите за знаками.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, |3-6($C), $Gкакой:какая; ты $Gбледненький:бледненькая;! А чем это от тебя так мерзко благоухает? Я должен выяснить!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это что такое???',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (2480,'Помощь Хинотта','Никогда не видел таких отличных результатов действия яда! Занзил, говоришь? Не слыхал о таком... Однако пора уже приступать к созданию состава.$b$bИтак, я должен вылечить тебя и научить пользоваться этим ядом?$b$bДай мне пару минут на изучение токсина, $n.','Дождитесь, пока Серж Хинотт доделает лекарство.','Лекарство готово! Выпей это противоядие, и наступление безумия остановится. Впрочем, с запахом ничего не поделаешь.','Лекарство готово','Поговорите с Сержем Хиноттом на Мельнице Таррен, что в Предгорьях Хилсбрада.','Лекарство готово') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Хинотта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Никогда не видел таких отличных результатов действия яда! Занзил, говоришь? Не слыхал о таком... Однако пора уже приступать к созданию состава.$b$bИтак, я должен вылечить тебя и научить пользоваться этим ядом?$b$bДай мне пару минут на изучение токсина, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока Серж Хинотт доделает лекарство.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лекарство готово! Выпей это противоядие, и наступление безумия остановится. Впрочем, с запахом ничего не поделаешь.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Лекарство готово',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Сержем Хиноттом на Мельнице Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Лекарство готово',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2498,'Возвращение к Деналану','Я только что получил известие, что Деналан с озера Аль\'Амет узнал, что могло послужить причиной возникновения опухоли, поражающей древесников. Пожалуйста, поговори с ним и скажи, что тебя прислал я.$B$BТоропись, $n, ему нужна наша помощь.','Релиан Зеленый Костер хочет, чтобы вы поговорили с Деналаном у озера Аль\'Амет.','Ах, так, значит, Релиан послал тебя мне в помощь. Хорошо, что ты так скоро пришла.\n\nЯ обнаружил нечто чрезвычайно тревожное!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Деналану',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я только что получил известие, что Деналан с озера Аль\'Амет узнал, что могло послужить причиной возникновения опухоли, поражающей древесников. Пожалуйста, поговори с ним и скажи, что тебя прислал я.$B$BТоропись, $n, ему нужна наша помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Релиан Зеленый Костер хочет, чтобы вы поговорили с Деналаном у озера Аль\'Амет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, так, значит, Релиан послал тебя мне в помощь. Хорошо, что ты так скоро пришла.\n\nЯ обнаружил нечто чрезвычайно тревожное!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (2499,'Дубохмур','Я во всем разобрался! И сразу бросился сюда, чтобы найти тебя. На самом деле все так просто... порча переходит от одного древесника к другому, но только один из них является истинным источником.$b$bЭто Дубохмур, он поражен такой огромной опухолью, каких я еще и не видел. Я бы даже сказал гигантской.$b$bРаньше Дубохмур жил в пещере возле моего озера, но потом перебрался в закоулок северо-восточнее Родниковой реки. $n, найди Дубохмура и сними эту опухоль. Избавь мою землю от источника порчи!','Снимите гигантскую опухоль с Дубохмура.','Тебе удалось найти Дубохмура, |3-6($R)?','Вернитесь к Деналану в Родниковый шалаш.','Затянувшаяся болезнь Дубохмура – жестокое напоминание о том, как глубоко может распространиться порча, поразившая Тельдрассил.','Дубохмур') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дубохмур',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я во всем разобрался! И сразу бросился сюда, чтобы найти тебя. На самом деле все так просто... порча переходит от одного древесника к другому, но только один из них является истинным источником.$b$bЭто Дубохмур, он поражен такой огромной опухолью, каких я еще и не видел. Я бы даже сказал гигантской.$b$bРаньше Дубохмур жил в пещере возле моего озера, но потом перебрался в закоулок северо-восточнее Родниковой реки. $n, найди Дубохмура и сними эту опухоль. Избавь мою землю от источника порчи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Снимите гигантскую опухоль с Дубохмура.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти Дубохмура, |3-6($R)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Деналану в Родниковый шалаш.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Затянувшаяся болезнь Дубохмура – жестокое напоминание о том, как глубоко может распространиться порча, поразившая Тельдрассил.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Дубохмур',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2500,'Пробежка по Бесплодным землям','$C, я хотел бы воспользоваться твоими услугами. Я довольно известный алхимик, и мне понадобились кое-какие реагенты, которые можно отыскать в Бесплодных землях.$B$BВот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей. Очевидно, что их можно добыть у самих тварей, но если ты не $gлюбитель:любительница; сражений, можешь попросить о помощи друзей.$B$BЯ неплохо заплачу, если ты принесешь мне все необходимое.$B$BЧто скажешь?','Добудьте в Бесплодных землях реагенты для Гхака Целителя и отнесите их ему в Телcамар.','Ты принес все необходимое? Пока не принесешь, платить не буду.','Вернитесь к Гхаку Целителю на Хребет Седых Лап, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробежка по Бесплодным землям',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, я хотел бы воспользоваться твоими услугами. Я довольно известный алхимик, и мне понадобились кое-какие реагенты, которые можно отыскать в Бесплодных землях.$B$BВот что мне нужно: пять вторых желудков канюка, десять клыков скального койота и пять осколков каменных элементалей. Очевидно, что их можно добыть у самих тварей, но если ты не $gлюбитель:любительница; сражений, можешь попросить о помощи друзей.$B$BЯ неплохо заплачу, если ты принесешь мне все необходимое.$B$BЧто скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте в Бесплодных землях реагенты для Гхака Целителя и отнесите их ему в Телcамар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес все необходимое? Пока не принесешь, платить не буду.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гхаку Целителю на Хребет Седых Лап, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2501,'Пробежка по Бесплодным землям-2','Ты не раз меня $gвыручал:выручала;, $n. Я хотел бы дать тебе в награду рецепт зелья, которое ты уже $gпробовал:пробовала;, но взамен попрошу выполнить опасное поручение.$B$BВ этом сейфе находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опаленного дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне.$B$BДобудь мне кровь дракона, и я отдам тебе рецепт.','Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Гхаку Целителю в Телcамар.','Между нами, алхимиками, говоря, ты просто $Gгерой:героиня;! Вот, возьми этот рецепт. Пусть он принесет тебе успех и богатство, как и мне!','Ты уже $Gнаполнил:наполнила; сосуды кровью опаленных драконов-стражей? Знаю, задание опасное... но в случае успеха тебя ждет рецепт восстановительного эликсира. Игра стоит свеч, мой друг... игра стоит свеч...','Вернитесь к Гхаку Целителю в Телcамар, что в Лок Модане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробежка по Бесплодным землям-2',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не раз меня $gвыручал:выручала;, $n. Я хотел бы дать тебе в награду рецепт зелья, которое ты уже $gпробовал:пробовала;, но взамен попрошу выполнить опасное поручение.$B$BВ этом сейфе находятся три волшебных сосуда; они зачарованы так, чтобы вытянуть кровь у опаленного дракона-стража. Если воспользоваться ими, зверь разозлится, поэтому соблюдай осторожность. Когда наполнишь все три, принеси их мне.$B$BДобудь мне кровь дракона, и я отдам тебе рецепт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните пустые волшебные сосуды кровью опаленных драконов-стражей в Бесплодных землях и принесите их Гхаку Целителю в Телcамар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Между нами, алхимиками, говоря, ты просто $Gгерой:героиня;! Вот, возьми этот рецепт. Пусть он принесет тебе успех и богатство, как и мне!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gнаполнил:наполнила; сосуды кровью опаленных драконов-стражей? Знаю, задание опасное... но в случае успеха тебя ждет рецепт восстановительного эликсира. Игра стоит свеч, мой друг... игра стоит свеч...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гхаку Целителю в Телcамар, что в Лок Модане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (2518,'Слезы Луны','Некогда леди Сатра была дорога Элуне. Эта изящная и чистая душой паучиха ткала серебряные свои нити под светом луны, ловя в свои сети вечерний туман. Его серебристые капли обладали великой целительной силой, их хранили в этом храме.$B$BНо недавно Сатру постигло безумие. Теперь и ее потомство под угрозой.$B$BНайди леди Сатру, $n, и положи конец ее страданиям. Она обитает к северо-востоку отсюда, у реки. Возьми ее серебристые паутинные железы и принеси их мне.','Добудьте серебристые паутинные железы леди Сатры.','В великой печали даю я тебе это поручение, но у нас нет надежды исцелить леди Сатру.$B$BМы надеемся, что если принести серебряные паутинные железы в жертву Элуне, то она благословит Сатру, и та возродится с покоем в душе.','Вернитесь к жрице А\'мууре на Поляну Оракула.','Порча и безумие могут поразить даже самых чистых созданий Элуны. Наша миссия – помочь уйти с миром тем, кто в этом нуждается.','Леди Сатра') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слезы Луны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некогда леди Сатра была дорога Элуне. Эта изящная и чистая душой паучиха ткала серебряные свои нити под светом луны, ловя в свои сети вечерний туман. Его серебристые капли обладали великой целительной силой, их хранили в этом храме.$B$BНо недавно Сатру постигло безумие. Теперь и ее потомство под угрозой.$B$BНайди леди Сатру, $n, и положи конец ее страданиям. Она обитает к северо-востоку отсюда, у реки. Возьми ее серебристые паутинные железы и принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте серебристые паутинные железы леди Сатры.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В великой печали даю я тебе это поручение, но у нас нет надежды исцелить леди Сатру.$B$BМы надеемся, что если принести серебряные паутинные железы в жертву Элуне, то она благословит Сатру, и та возродится с покоем в душе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице А\'мууре на Поляну Оракула.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Порча и безумие могут поразить даже самых чистых созданий Элуны. Наша миссия – помочь уйти с миром тем, кто в этом нуждается.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Леди Сатра',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2519,'Храм Луны','Одному некогда великому существу из нашего леса нужна помощь, |3-6($r). $B$BЭто трудное дело, но его надо сделать.$B$BПожалуйста, разыщи нашу жрицу А\'мууру, она все тебе объяснит. Ищи ее к юго-востоку отсюда, в Храме Луны.','Сестра Аквинна хочет, чтобы вы поговорили со жрицей А\'муурой из Храма Луны.','Стало быть, тебя прислала сестра Аквинна?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Храм Луны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одному некогда великому существу из нашего леса нужна помощь, |3-6($r). $B$BЭто трудное дело, но его надо сделать.$B$BПожалуйста, разыщи нашу жрицу А\'мууру, она все тебе объяснит. Ищи ее к юго-востоку отсюда, в Храме Луны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сестра Аквинна хочет, чтобы вы поговорили со жрицей А\'муурой из Храма Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стало быть, тебя прислала сестра Аквинна?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (2520,'Жертвоприношение Сатры','Теперь ты $Gдолжен:должна; закончить дело, порученное тебе. Возьми эти паутинные железы и принеси их в жертву во имя Элуны. Пусть великая паучиха обретет покой.$B$BВнутри этого храма ты найдешь центральный фонтан. Там ты оставишь жертвоприношение. Святые воды смоют порчу, что повергла Сатру в безумие.$B$BКогда закончишь дело, возвращайся ко мне.','Жрица А\'муура просит вас положить серебристые паутинные железы леди Сатры у фонтана в храме и затем вернуться к ней.','Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновленным духом.$B$BДа примет Элуна ту жертву, что ты $Gпринес:принесла; ей.','Совершите жертвоприношение у источника') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жертвоприношение Сатры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты $Gдолжен:должна; закончить дело, порученное тебе. Возьми эти паутинные железы и принеси их в жертву во имя Элуны. Пусть великая паучиха обретет покой.$B$BВнутри этого храма ты найдешь центральный фонтан. Там ты оставишь жертвоприношение. Святые воды смоют порчу, что повергла Сатру в безумие.$B$BКогда закончишь дело, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Жрица А\'муура просит вас положить серебристые паутинные железы леди Сатры у фонтана в храме и затем вернуться к ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновленным духом.$B$BДа примет Элуна ту жертву, что ты $Gпринес:принесла; ей.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Совершите жертвоприношение у источника',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2521,'Служба для Кум\'иши','$R, может ли твой ничтожный мозг понять уникальность безупречной сферы из дренетиста? Некоторые дренеи тратили всю свою жизнь на поиски одного-единственного кристалла – и все лишь для того, чтобы встретиться с ужасной судьбой, не достигнув своей цели.$B$BИ вот ты стоишь перед Кум\'ишей, знаешь, что требуется Кум\'ише. Ты все еще желаешь помочь? Отлично, |3-6($r)... Если ты в какой-нибудь момент своего путешествия через эти земли найдешь безупречную сферу из дренетиста, верни ее мне и я вознагражу тебя так, как тебе не грезилось в самых безумных мечтаниях.','Если в своем путешествии по Выжженным землям вы найдете безупречную сферу из дренетиста, отнесите ее Кум\'ише Коллекционеру. $B$BБудьте внимательны: этот камень – один из самых редких кристаллов во всем Азероте. Любое существо в этих землях может владеть безупречной сферой из дренетиста. $B$BВы будете вознаграждены за каждую безупречную сферу из дренетиста, которую доставите Кум\'ише.','Не обманывают ли меня глаза? Невозможно! Откуда... Каким образом...$B$BБыть может, теперь откроется разлом и мы сможем вернуться на родину.','Я посвятил свою жизнь поискам безупречной сферы из дренейского аметиста. Всю жизнь, $R!','Вернитесь к Кум\'ише Коллекционеру в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Служба для Кум\'иши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$R, может ли твой ничтожный мозг понять уникальность безупречной сферы из дренетиста? Некоторые дренеи тратили всю свою жизнь на поиски одного-единственного кристалла – и все лишь для того, чтобы встретиться с ужасной судьбой, не достигнув своей цели.$B$BИ вот ты стоишь перед Кум\'ишей, знаешь, что требуется Кум\'ише. Ты все еще желаешь помочь? Отлично, |3-6($r)... Если ты в какой-нибудь момент своего путешествия через эти земли найдешь безупречную сферу из дренетиста, верни ее мне и я вознагражу тебя так, как тебе не грезилось в самых безумных мечтаниях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если в своем путешествии по Выжженным землям вы найдете безупречную сферу из дренетиста, отнесите ее Кум\'ише Коллекционеру. $B$BБудьте внимательны: этот камень – один из самых редких кристаллов во всем Азероте. Любое существо в этих землях может владеть безупречной сферой из дренетиста. $B$BВы будете вознаграждены за каждую безупречную сферу из дренетиста, которую доставите Кум\'ише.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не обманывают ли меня глаза? Невозможно! Откуда... Каким образом...$B$BБыть может, теперь откроется разлом и мы сможем вернуться на родину.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я посвятил свою жизнь поискам безупречной сферы из дренейского аметиста. Всю жизнь, $R!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кум\'ише Коллекционеру в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2522,'Для коллекции Кум\'иши','Хотя заклинание портала ни к чему не привело, я по-прежнему надеюсь, что моя следующая попытка будет успешной.$B$BНадежда дренеев столь же сильна, как твоя жадность до безделушек, |3-6($r). Возвращайся в те проклятые земли и найди еще одну безупречную сферу из дренетиста.$B$BНу конечно же, брать или не брать на себя эту задачу – выбираешь только ты *усмешка*.','Найдите безупречную сферу из дренетиста и верните ее Кум\'ише Коллекционеру.','Просто поразительно. Я сомневался, что тебе удастся найти еще одну сферу, но вот она – пульсирует у меня в ладонях.$B$BОтлично сделано, $N!$B$BЕсли найдешь еще – а я верю, что это возможно – то принеси мне, и я вознагражу тебя.','Вы нашли еще одну безупречную сферу из дренетиста?','Вернитесь к Кум\'ише Коллекционеру в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Для коллекции Кум\'иши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя заклинание портала ни к чему не привело, я по-прежнему надеюсь, что моя следующая попытка будет успешной.$B$BНадежда дренеев столь же сильна, как твоя жадность до безделушек, |3-6($r). Возвращайся в те проклятые земли и найди еще одну безупречную сферу из дренетиста.$B$BНу конечно же, брать или не брать на себя эту задачу – выбираешь только ты *усмешка*.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите безупречную сферу из дренетиста и верните ее Кум\'ише Коллекционеру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Просто поразительно. Я сомневался, что тебе удастся найти еще одну сферу, но вот она – пульсирует у меня в ладонях.$B$BОтлично сделано, $N!$B$BЕсли найдешь еще – а я верю, что это возможно – то принеси мне, и я вознагражу тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы нашли еще одну безупречную сферу из дренетиста?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кум\'ише Коллекционеру в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (2523,'Оскверненный песнецвет','Вернитесь к оскверненному песнецвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный песнецвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному песнецвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2541,'Спящий друид','Шаман племени Кривой Сосны, который живет в этих местах, нашел способ разлучать дух спящего друида с физическим телом. Этот фурболг оживил мое тело и заставил его нападать на любого, кто пытается обследовать обитель Бен\'этиль. Теперь мне не выйти из Изумрудного Сна, и я не могу прекратить это!$B$BПомоги мне! У шамана Кривой Сосны есть при себе странный оберег, который он использует во время ритуала, и я хотел бы исследовать его. Прошу тебя, $n, принеси его мне!','Принесите шаманский оберег вуду Обену Яростному Когтю в обитель Бен\'этиль.','Если бы я смог осмотреть этот оберег, я смог бы понять суть чар. Удалось тебе его найти?','Вернитесь к Обену Яростному Когтю в Тельдрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спящий друид',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шаман племени Кривой Сосны, который живет в этих местах, нашел способ разлучать дух спящего друида с физическим телом. Этот фурболг оживил мое тело и заставил его нападать на любого, кто пытается обследовать обитель Бен\'этиль. Теперь мне не выйти из Изумрудного Сна, и я не могу прекратить это!$B$BПомоги мне! У шамана Кривой Сосны есть при себе странный оберег, который он использует во время ритуала, и я хотел бы исследовать его. Прошу тебя, $n, принеси его мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите шаманский оберег вуду Обену Яростному Когтю в обитель Бен\'этиль.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если бы я смог осмотреть этот оберег, я смог бы понять суть чар. Удалось тебе его найти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Обену Яростному Когтю в Тельдрассил.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (2561,'Друид-медведь','Изучив этот оберег, $n, я понял, что надо сделать. Пожалуйста, возьми его и сделай, как я прошу.$B$BТебе придется собраться с духом и проникнуть в самые глухие закоулки обители Бен\'этиль. Там ты найдешь мое лишенное души тело... Хотя я и скорблю о том, что мне сейчас придется поведать тебе, я не вижу другого способа освободиться от власти племени Кривой Сосны.$B$BЧтобы я мог сбежать от них, ты $Gдолжен:должна; уничтожить мое физическое тело. Как только это будет сделано, примени к моему трупу амулет вуду. После этого возвращайся ко мне.','Уничтожьте лишенное души тело Обена Яростного Когтя, а затем воспользуйтесь оберегом вуду.','Освободите душу Обена Яростного Когтя.','Вернитесь к Обену Яростному Когтю обитель Бен\'этиль.','Его душа и тело разделены, и есть только одна возможность избавить этого спящего друида от вечных мук.','Яростный Коготь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друид-медведь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изучив этот оберег, $n, я понял, что надо сделать. Пожалуйста, возьми его и сделай, как я прошу.$B$BТебе придется собраться с духом и проникнуть в самые глухие закоулки обители Бен\'этиль. Там ты найдешь мое лишенное души тело... Хотя я и скорблю о том, что мне сейчас придется поведать тебе, я не вижу другого способа освободиться от власти племени Кривой Сосны.$B$BЧтобы я мог сбежать от них, ты $Gдолжен:должна; уничтожить мое физическое тело. Как только это будет сделано, примени к моему трупу амулет вуду. После этого возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте лишенное души тело Обена Яростного Когтя, а затем воспользуйтесь оберегом вуду.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Освободите душу Обена Яростного Когтя.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Обену Яростному Когтю обитель Бен\'этиль.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Его душа и тело разделены, и есть только одна возможность избавить этого спящего друида от вечных мук.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Яростный Коготь',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2581,'Челюсти гиены-хохотуна','Хорошо известно, что челюсти гиены невероятно сильны, но чтобы они были способны прокусить три дюйма ториевой стали? Невозможно, невероятно, и тем не менее я видел это своими глазами.$B$BОтправляйся в Выжженные земли и принеси мне три челюсти гиены-ухмыльника. А пока ищешь гиен, высматривай также кабанов и скорпоков: для дополнения к изначальной эссенции требуется также два обожженных легких вепря и одна клешня скорпока.','Принесите три челюсти гиены, два обожженных легких вепря и одну клешню скорпока волшебнику крови Дразиалу.','Как самочувствие, $N? Ты излучаешь ауру гиены-ухмыльника – силу, с которой никто из смертных не сравнится!$B$BК несчастью, из принесенных тобой компонентов я смогу сделать эссенции только на одну таблетку. Если тебе понадобится еще одна таблетка, мне нужно будет больше компонентов.','Отвратительно пахнешь, $N. Что серные поля – такое милое место для прогулки? И где мои компоненты?','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Челюсти гиены-хохотуна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо известно, что челюсти гиены невероятно сильны, но чтобы они были способны прокусить три дюйма ториевой стали? Невозможно, невероятно, и тем не менее я видел это своими глазами.$B$BОтправляйся в Выжженные земли и принеси мне три челюсти гиены-ухмыльника. А пока ищешь гиен, высматривай также кабанов и скорпоков: для дополнения к изначальной эссенции требуется также два обожженных легких вепря и одна клешня скорпока.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три челюсти гиены, два обожженных легких вепря и одну клешню скорпока волшебнику крови Дразиалу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как самочувствие, $N? Ты излучаешь ауру гиены-ухмыльника – силу, с которой никто из смертных не сравнится!$B$BК несчастью, из принесенных тобой компонентов я смогу сделать эссенции только на одну таблетку. Если тебе понадобится еще одна таблетка, мне нужно будет больше компонентов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Отвратительно пахнешь, $N. Что серные поля – такое милое место для прогулки? И где мои компоненты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2582,'Ярость веков','О, $n, добро пожаловать, давно не виделись. Похоже, тебе понравился эффект крепкого, действенного зелья, извлеченного из гиены-ухмыльника. Однако осторожнее: если непосредственным эффектом является титанический прилив сил, то долгосрочный эффект, сказывающийся на твоем духе и рассудке, может быть опасным. $B$BКстати говоря, тебе нужно еще зелья? Тогда принеси мне еще три челюсти гиены, два обожженных легких вепря и одну клешню скорпока.','Принесите три челюсти гиены, два обожженных легких вепря и одну клешню скорпока волшебнику крови Дразиалу.','Вот, возьми! И помни, что использовать это зелье надо расчетливо. Если понадобится еще, приходи ко мне после того, как израсходуешь порцию, которую я тебе только что выдал.','Тебе удалось добыть органы этих тварей?','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярость веков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, $n, добро пожаловать, давно не виделись. Похоже, тебе понравился эффект крепкого, действенного зелья, извлеченного из гиены-ухмыльника. Однако осторожнее: если непосредственным эффектом является титанический прилив сил, то долгосрочный эффект, сказывающийся на твоем духе и рассудке, может быть опасным. $B$BКстати говоря, тебе нужно еще зелья? Тогда принеси мне еще три челюсти гиены, два обожженных легких вепря и одну клешню скорпока.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три челюсти гиены, два обожженных легких вепря и одну клешню скорпока волшебнику крови Дразиалу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, возьми! И помни, что использовать это зелье надо расчетливо. Если понадобится еще, приходи ко мне после того, как израсходуешь порцию, которую я тебе только что выдал.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть органы этих тварей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2583,'Жизненная сила вепря','В этих опаленных землях водятся два вида кабанов: углегривый кабан и зловепрь.$B$BСудя по всему, стойкость этих тварей такова, что делает их почти неуязвимыми, поскольку другие животные считают, что вепрей слишком трудно убить, следовательно, на них не стоит даже тратить усилий.$B$BНам нужно провести дальнейшие исследования, $n. Если ты принесешь мне три обожженных легких вепря, две клешни скорпока и один мозг василиска, я создам отличный эликсир на основе вытяжки из этого материала. И первым делом проверю на тебе!','Принесите три обожженных легких вепря, две клешни скорпока и один мозг василиска волшебнику крови Дразиалу.','Дух вепря озаряет твое существование, $N! Может быть, ты веришь, что тебе дарована неуязвимость, как и этим тварям?','Так где органы, $N!?','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жизненная сила вепря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этих опаленных землях водятся два вида кабанов: углегривый кабан и зловепрь.$B$BСудя по всему, стойкость этих тварей такова, что делает их почти неуязвимыми, поскольку другие животные считают, что вепрей слишком трудно убить, следовательно, на них не стоит даже тратить усилий.$B$BНам нужно провести дальнейшие исследования, $n. Если ты принесешь мне три обожженных легких вепря, две клешни скорпока и один мозг василиска, я создам отличный эликсир на основе вытяжки из этого материала. И первым делом проверю на тебе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три обожженных легких вепря, две клешни скорпока и один мозг василиска волшебнику крови Дразиалу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дух вепря озаряет твое существование, $N! Может быть, ты веришь, что тебе дарована неуязвимость, как и этим тварям?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так где органы, $N!?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2584,'Дух вепря','Когда я впервые выдал тебе этот эликсир, $n, я уже понимал, что одна-две порции не удовлетворят твой аппетит. Даже сейчас я вижу в твоих глазах этот голод. Сей состав имеет одно побочное свойство – он дает привыкание, которому, похоже, не может сопротивляться даже самая сильная воля.$B$BЧто ж, пусть так! Если тебе требуется еще порция смеси с легочной вытяжкой, отправляйся обратно в пустоши и принеси мне три обожженных легких вепря, две клешни скорпока и один мозг василиска.','Принесите три обожженных легких вепря, две клешни скорпока и один мозг василиска волшебнику крови Дразиалу.','Хочу предупредить тебя, $N, не пытайся смешивать созданные мною составы. Химические свойства состава, недавно принятого тобою, всегда возобладают над предшествующими заклинаниями, таким образом, эффект другого зелья будет сведен на нет.','Так где органы, $N!?','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух вепря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я впервые выдал тебе этот эликсир, $n, я уже понимал, что одна-две порции не удовлетворят твой аппетит. Даже сейчас я вижу в твоих глазах этот голод. Сей состав имеет одно побочное свойство – он дает привыкание, которому, похоже, не может сопротивляться даже самая сильная воля.$B$BЧто ж, пусть так! Если тебе требуется еще порция смеси с легочной вытяжкой, отправляйся обратно в пустоши и принеси мне три обожженных легких вепря, две клешни скорпока и один мозг василиска.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три обожженных легких вепря, две клешни скорпока и один мозг василиска волшебнику крови Дразиалу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хочу предупредить тебя, $N, не пытайся смешивать созданные мною составы. Химические свойства состава, недавно принятого тобою, всегда возобладают над предшествующими заклинаниями, таким образом, эффект другого зелья будет сведен на нет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так где органы, $N!?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2585,'Решительный удар','Тебе приходилось видеть их сражение, $n? Я имею в виду скорпоков. Видеть грациозность и ловкость, с которой они движутся? Решительность, с которой они наносят удары?$B$BЕсли бы мы только могли выделить эту ловкость и заключить ее в оболочку, мы были бы богаты вне всякого... я хочу сказать... это было бы благо для всего научного соообщества. $B$BПомоги мне, $n, и я выделю для тебя порцию настойки.$B$BДля того чтобы создать стабильное вещество, мне потребуется три клешни скорпока, две меры потрохов стервятника и одно обожженное легкое вепря.','Принесите три клешни скорпока, две единицы потрохов стервятника и одно обожженное легкое вепря волшебнику крови Дразиалу.','Потрясающе. Анализ этой эссенции был самым сложным.$B$BВозьми щепотку этой солевой вытяжки и положи ее под язык. Ты испытаешь легкое чувство эйфории, после которого наступит состояние невероятной ловкости и быстроты.','Так где органы, $N!?','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решительный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе приходилось видеть их сражение, $n? Я имею в виду скорпоков. Видеть грациозность и ловкость, с которой они движутся? Решительность, с которой они наносят удары?$B$BЕсли бы мы только могли выделить эту ловкость и заключить ее в оболочку, мы были бы богаты вне всякого... я хочу сказать... это было бы благо для всего научного соообщества. $B$BПомоги мне, $n, и я выделю для тебя порцию настойки.$B$BДля того чтобы создать стабильное вещество, мне потребуется три клешни скорпока, две меры потрохов стервятника и одно обожженное легкое вепря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три клешни скорпока, две единицы потрохов стервятника и одно обожженное легкое вепря волшебнику крови Дразиалу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе. Анализ этой эссенции был самым сложным.$B$BВозьми щепотку этой солевой вытяжки и положи ее под язык. Ты испытаешь легкое чувство эйфории, после которого наступит состояние невероятной ловкости и быстроты.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так где органы, $N!?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2586,'Скорпоковая соль','Ты $gжив:жива;! Это поистине хорошая новость! Полагаю, тебе нужно еще скорпоковой настойки?$B$BОтлично, $n, тогда снова ступай в пустоши и не возвращайся, пока не заполучишь три клешни скорпока, две меры потрохов стервятника и одно обожженное легкое вепря.','Принесите три клешни скорпока, две меры потрохов стервятника и одно обожженное легкое вепря волшебнику крови Дразиалу.','Отличная работа, $N. Вот одна мера настойки для тебя, а оставшиеся девять будут использованы для моих исследований.$B$BВ любой момент, когда тебе понадобится скорпоковая настойка, возвращайся ко мне, и мы заключим сделку.','Так где органы, $N!?','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скорпоковая соль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gжив:жива;! Это поистине хорошая новость! Полагаю, тебе нужно еще скорпоковой настойки?$B$BОтлично, $n, тогда снова ступай в пустоши и не возвращайся, пока не заполучишь три клешни скорпока, две меры потрохов стервятника и одно обожженное легкое вепря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три клешни скорпока, две меры потрохов стервятника и одно обожженное легкое вепря волшебнику крови Дразиалу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Вот одна мера настойки для тебя, а оставшиеся девять будут использованы для моих исследований.$B$BВ любой момент, когда тебе понадобится скорпоковая настойка, возвращайся ко мне, и мы заключим сделку.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так где органы, $N!?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнику крови Дразиалу в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2601,'Укус василиска','Эти пустоши кишат василисками Красного камня, $n. Эти василиски отлично приспособились к местным условиям, их тут больше, чем любых других диких животных. $B$BЯ наблюдала издали, как они охотятся и ведут свою повседневную жизнь – мыслительный процесс у этих тварей, похоже, куда более сложный, чем у некоторых из тех существ, которых мы называем разумными.$B$BЯ должна изучить их мозги!$B$BРаздобудь для меня десять их мозгов, $n. Однако для опытов мне понадобятся еще потроха двух стервятников, которые дадут основу для раствора.','Принесите десять мозгов василиска и потроха двух стервятников волшебнице крови Линоре.','Замечательно, $N! Предлагаю тебе отведать на вкус внутреннюю суть василисков красного камня.$B$BЕсли этот состав тебе понравится, всегда можно сделать еще... за определенную плату.','Удалось ли тебе добыть нужные органы?','Вернитесь к волшебнице крови Линоре в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укус василиска',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти пустоши кишат василисками Красного камня, $n. Эти василиски отлично приспособились к местным условиям, их тут больше, чем любых других диких животных. $B$BЯ наблюдала издали, как они охотятся и ведут свою повседневную жизнь – мыслительный процесс у этих тварей, похоже, куда более сложный, чем у некоторых из тех существ, которых мы называем разумными.$B$BЯ должна изучить их мозги!$B$BРаздобудь для меня десять их мозгов, $n. Однако для опытов мне понадобятся еще потроха двух стервятников, которые дадут основу для раствора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите десять мозгов василиска и потроха двух стервятников волшебнице крови Линоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно, $N! Предлагаю тебе отведать на вкус внутреннюю суть василисков красного камня.$B$BЕсли этот состав тебе понравится, всегда можно сделать еще... за определенную плату.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе добыть нужные органы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Линоре в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2602,'Непогрешимый разум','Твое сосредоточение ушло так скоро? Нужно провести еще больше исследований!$B$BАх да, $n, цена остается прежней. Отправляйся в Выжженные земли и возвращайся ко мне с десятью мозгами тварей Красного Камня и потрохами двух стервятников.','Принесите десять мозгов василиска и потроха двух стервятников волшебнице крови Линоре.','Да, да, $N, дай мне минутку, и нужные тебе составы будут готовы к употреблению.$B$BВот, возьми... и помни, $N, что нельзя даже пытаться употреблять эти экспериментальные составы слишком часто. Результат будет катастрофическим.','Удалось ли тебе добыть нужные органы?','Вернитесь к волшебнице крови Линоре в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Непогрешимый разум',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твое сосредоточение ушло так скоро? Нужно провести еще больше исследований!$B$BАх да, $n, цена остается прежней. Отправляйся в Выжженные земли и возвращайся ко мне с десятью мозгами тварей Красного Камня и потрохами двух стервятников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите десять мозгов василиска и потроха двух стервятников волшебнице крови Линоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, да, $N, дай мне минутку, и нужные тебе составы будут готовы к употреблению.$B$BВот, возьми... и помни, $N, что нельзя даже пытаться употреблять эти экспериментальные составы слишком часто. Результат будет катастрофическим.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе добыть нужные органы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Линоре в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2603,'Стойкость стервятника','В этих опаленных землях смерть воистину крылата, |3-6($r). Я много раз наблюдала, как черные убийцы и костеглоды пируют на телах павших исследователей – иногда пожирая наиболее отвратительные и разложившиеся останки трупов. Удивительно все же, как их внутренние органы справляются с заразой, царящей в этих землях?$B$BПомоги мне в моих исследованиях, $n! Мне нужны потроха! Понадобятся также две челюсти гиены в качестве основы для состава.$B$BТвои усилия будут вознаграждены вдвойне.','Принесите потроха десяти стервятников и две челюсти гиены волшебнице крови Линоре.','Превосходно! Я немедленно приступаю к работе. Возможно, удастся найти лекарство от множества недугов, существующих в этом мире!$B$BАх да, твоя награда – конечно, если тебе опять понадобится зелье, возвращайся ко мне, я дам тебе новое поручение.','Не трать зря мое время, $N. Нам нечего обсуждать, пока ты не принесешь то, что мне требуется.','Вернитесь к волшебнице крови Линоре в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стойкость стервятника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этих опаленных землях смерть воистину крылата, |3-6($r). Я много раз наблюдала, как черные убийцы и костеглоды пируют на телах павших исследователей – иногда пожирая наиболее отвратительные и разложившиеся останки трупов. Удивительно все же, как их внутренние органы справляются с заразой, царящей в этих землях?$B$BПомоги мне в моих исследованиях, $n! Мне нужны потроха! Понадобятся также две челюсти гиены в качестве основы для состава.$B$BТвои усилия будут вознаграждены вдвойне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите потроха десяти стервятников и две челюсти гиены волшебнице крови Линоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Я немедленно приступаю к работе. Возможно, удастся найти лекарство от множества недугов, существующих в этом мире!$B$BАх да, твоя награда – конечно, если тебе опять понадобится зелье, возвращайся ко мне, я дам тебе новое поручение.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не трать зря мое время, $N. Нам нечего обсуждать, пока ты не принесешь то, что мне требуется.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Линоре в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2604,'Духовное превосходство','Я вижу, внутреннее пламя угасло. Как по-твоему, длилась ли эта духовная эйфория хотя бы час?$B$BЕсли ты желаешь получить еще зелья из потрошков, то изволь снабдить меня сырьем! Отправляйся обратно, $n. И не возвращайся, пока не наберешь десять мер потрохов и две челюсти.','Принесите потроха десяти стервятников и две челюсти гиены волшебнице крови Линоре.','Возможно, когда-нибудь я смогу выделить активные компоненты этой эссенции и получить куда более эффективный результат. К несчастью, пока тебе придется довольствоваться тем, что я в состоянии сделать на настоящий момент. Если понадобится еще зелье из потрошков, возвращайся ко мне.','Не трать зря мое время, $N. Нам нечего обсуждать, пока ты не принесешь то, что мне требуется.','Вернитесь к волшебнице крови Линоре в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духовное превосходство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вижу, внутреннее пламя угасло. Как по-твоему, длилась ли эта духовная эйфория хотя бы час?$B$BЕсли ты желаешь получить еще зелья из потрошков, то изволь снабдить меня сырьем! Отправляйся обратно, $n. И не возвращайся, пока не наберешь десять мер потрохов и две челюсти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите потроха десяти стервятников и две челюсти гиены волшебнице крови Линоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возможно, когда-нибудь я смогу выделить активные компоненты этой эссенции и получить куда более эффективный результат. К несчастью, пока тебе придется довольствоваться тем, что я в состоянии сделать на настоящий момент. Если понадобится еще зелье из потрошков, возвращайся ко мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не трать зря мое время, $N. Нам нечего обсуждать, пока ты не принесешь то, что мне требуется.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Линоре в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2605,'Жаждущий гоблин','Слышь, у меня возникла мысль. Я слышал о странных тварях, собирателях росы, живущих на юго-западе... Говорят, они хранят воду в особых железах.$b$bМне кажется, что из этих желез я бы сделал напиток, который утолил бы мою жажду! Ты не поможешь мне, $n?$b$bНайди кактусовый сад, именно там пасутся собиратели росы.','Добудьте насыщенную влагой железу и принесите ее Синю Гогельмогелю в Прибамбасск.','Вернитесь к Синю Гогельмогелю в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жаждущий гоблин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слышь, у меня возникла мысль. Я слышал о странных тварях, собирателях росы, живущих на юго-западе... Говорят, они хранят воду в особых железах.$b$bМне кажется, что из этих желез я бы сделал напиток, который утолил бы мою жажду! Ты не поможешь мне, $n?$b$bНайди кактусовый сад, именно там пасутся собиратели росы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте насыщенную влагой железу и принесите ее Синю Гогельмогелю в Прибамбасск.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Синю Гогельмогелю в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2606,'Хороший вкус','Фу! Ну и гадость! Да, идея была неудачная...$b$bСтой, что такое? О, знаю, ты считаешь, что не стоит отказываться от этой штуки. Ладно.$b$BЭээ... У меня есть идея! Гениально! Отнеси эту росу моей подруге Поливалке – она отличный повар. Скажи, что мы тут задумали, пусть придумает, как улучшить вкус.$b$bЯ хочу сказать, что такая дрянь по крайней мере, должна пробирать до мозга костей... А пока ей до мозга далеко...','Поговорите с Поливалкой в Прибамбасске по поручению Синя Гогельмогеля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хороший вкус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Фу! Ну и гадость! Да, идея была неудачная...$b$bСтой, что такое? О, знаю, ты считаешь, что не стоит отказываться от этой штуки. Ладно.$b$BЭээ... У меня есть идея! Гениально! Отнеси эту росу моей подруге Поливалке – она отличный повар. Скажи, что мы тут задумали, пусть придумает, как улучшить вкус.$b$bЯ хочу сказать, что такая дрянь по крайней мере, должна пробирать до мозга костей... А пока ей до мозга далеко...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Поливалкой в Прибамбасске по поручению Синя Гогельмогеля.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2607,'Прикосновение Занзила','Похоже, что информации у вас даже больше, чем я ожидал. Как-то странно все оборачивается, $n.$b$bЛекарство? Хм-м... Спуститесь в подвал и поговорите с Доком Миксиль-Пиксилем – он, вероятно, сможет помочь.','Поговорите с Доком Миксиль-Пиксилем в подвале казарм.','Как раз вовремя! Просто положите сыр на стол и проваливайте. Осборн заплатит вам на выходе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикосновение Занзила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, что информации у вас даже больше, чем я ожидал. Как-то странно все оборачивается, $n.$b$bЛекарство? Хм-м... Спуститесь в подвал и поговорите с Доком Миксиль-Пиксилем – он, вероятно, сможет помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Доком Миксиль-Пиксилем в подвале казарм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как раз вовремя! Просто положите сыр на стол и проваливайте. Осборн заплатит вам на выходе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2608,'Прикосновение Занзила','Ох, вы так выглядите – точь-в-точь мертвец. Поправочка – я видел мертвецов, вы выглядите еще хуже. Вы, $gсударь:сударыня;, будете предсмертной отрыжкой самой смерти.$b$bХа! Слышал, Нетронь? Запиши-ка это!$b$b*Кашляет.* Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови. Не беспокойтесь, больно лишь первые... раз пятьдесят или около того... Ложитесь, и приступим к лечению, $n!','Лягте на землю (действие /lay) для осмотра Доком Миксиль-Пиксилем – он не сможет подобрать лекарство, пока не найдет причину болезни.','Позвольте, я минутку посовещаюсь со своими коллегами, $N. Доктор Монтгомери, мистер Ноарм, все на консилиум!','Когда ты будешь $Gготов:готова; к обследованию, я лягу на землю, и я начну кровопускание.','Позвольте врачу поставить диагноз.','Вернитесь к доку Миксилю-Пиксилю в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикосновение Занзила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, вы так выглядите – точь-в-точь мертвец. Поправочка – я видел мертвецов, вы выглядите еще хуже. Вы, $gсударь:сударыня;, будете предсмертной отрыжкой самой смерти.$b$bХа! Слышал, Нетронь? Запиши-ка это!$b$b*Кашляет.* Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови. Не беспокойтесь, больно лишь первые... раз пятьдесят или около того... Ложитесь, и приступим к лечению, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Лягте на землю (действие /lay) для осмотра Доком Миксиль-Пиксилем – он не сможет подобрать лекарство, пока не найдет причину болезни.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Позвольте, я минутку посовещаюсь со своими коллегами, $N. Доктор Монтгомери, мистер Ноарм, все на консилиум!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда ты будешь $Gготов:готова; к обследованию, я лягу на землю, и я начну кровопускание.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Позвольте врачу поставить диагноз.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к доку Миксилю-Пиксилю в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2609,'Прикосновение Занзила','Однозначно, $n. У вас чтотит.$b$bК счастью, от чтотита у меня есть средство.$b$bИ вот что мне понадобится для его изготовления: букетик простых полевых цветов, одна освинцованная колба, одна бронзовая трубка и последнее – но немаловажное! – нитка светлого зеленовато-желтого шелка. Старушка Эмма оставила для меня катушку таких ниток в "Тончайшей пряже". Эту лавку можно найти, если идти вдоль каналов.$b$bА теперь поспешите, $n, и постарайтесь ни к кому не прикасаться, пока вас не вылечат. Кстати, доктор Монтгомери сказал, что вам нужно душ принять... это его слова, не мои!','Принесите Доку Миксиль-Пиксилю один букетик простых полевых цветов, одну освинцованную колбу, одну бронзовую трубку и одну катушку светлого зеленовато-желтого шелка. Чтотит, знаете ли, сам собой не проходит.','Что я делаю? А на что похоже то, что я делаю? Я продумываю, как вылечить ваш чтотит! И нечего так возмущенно на меня смотреть, $N! Еще несколько секунд... Готово! Побрызгайте на себя этим лечебным средством с... эээ... необыкновенным запахом – и вы в полном порядке!','Если хотите вылечить свой чтотит, придется приложить побольше усилий, $N. Где компоненты исцеляющего средства?','Вернитесь к доку Миксилю-Пиксилю на Аллею Героев, что в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикосновение Занзила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Однозначно, $n. У вас чтотит.$b$bК счастью, от чтотита у меня есть средство.$b$bИ вот что мне понадобится для его изготовления: букетик простых полевых цветов, одна освинцованная колба, одна бронзовая трубка и последнее – но немаловажное! – нитка светлого зеленовато-желтого шелка. Старушка Эмма оставила для меня катушку таких ниток в "Тончайшей пряже". Эту лавку можно найти, если идти вдоль каналов.$b$bА теперь поспешите, $n, и постарайтесь ни к кому не прикасаться, пока вас не вылечат. Кстати, доктор Монтгомери сказал, что вам нужно душ принять... это его слова, не мои!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Доку Миксиль-Пиксилю один букетик простых полевых цветов, одну освинцованную колбу, одну бронзовую трубку и одну катушку светлого зеленовато-желтого шелка. Чтотит, знаете ли, сам собой не проходит.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что я делаю? А на что похоже то, что я делаю? Я продумываю, как вылечить ваш чтотит! И нечего так возмущенно на меня смотреть, $N! Еще несколько секунд... Готово! Побрызгайте на себя этим лечебным средством с... эээ... необыкновенным запахом – и вы в полном порядке!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если хотите вылечить свой чтотит, придется приложить побольше усилий, $N. Где компоненты исцеляющего средства?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к доку Миксилю-Пиксилю на Аллею Героев, что в Штормграде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2621,'Опозоренный','Сожалею. Это все, что у меня есть. Одно неверное решение, приведшее к массе плохих последствий. Если бы я только дождался тех приказов! Может быть, там было бы сказано подробно обо всех ужасах, ожидающих нас в этих проклятых землях? Может быть, нам дали бы другое задание или выслали бы подкрепление? Но в конечном итоге, это моя вина. Все это – моя вина. $B$BИ вот я стою здесь, ожидая приказов. Я должен знать. Я должен знать, каковы эти приказы. $B$BКомандир-посланник Руаг находится в Каменоре. Найди его и узнай, что стало с приказами.','Поговорите с командиром разведотряда Руагом в Каменоре, что в Болоте Печали.','Хватка Тралла... Эта история все еще свежа в моей памяти.$B$B*Командир Руаг качает головой.*$B$BУжасная вещь – то, что случилось с этим подразделением. Орда потеряла немало своих лучших солдат, когда этот батальон был уничтожен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опозоренный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сожалею. Это все, что у меня есть. Одно неверное решение, приведшее к массе плохих последствий. Если бы я только дождался тех приказов! Может быть, там было бы сказано подробно обо всех ужасах, ожидающих нас в этих проклятых землях? Может быть, нам дали бы другое задание или выслали бы подкрепление? Но в конечном итоге, это моя вина. Все это – моя вина. $B$BИ вот я стою здесь, ожидая приказов. Я должен знать. Я должен знать, каковы эти приказы. $B$BКомандир-посланник Руаг находится в Каменоре. Найди его и узнай, что стало с приказами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром разведотряда Руагом в Каменоре, что в Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хватка Тралла... Эта история все еще свежа в моей памяти.$B$B*Командир Руаг качает головой.*$B$BУжасная вещь – то, что случилось с этим подразделением. Орда потеряла немало своих лучших солдат, когда этот батальон был уничтожен.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2622,'Пропавшие приказы','Приказы? Зачем тебе понадобились эти приказы?$B$BЧто ты подразумеваешь, $n? Конечно, я передал эти приказы! Солдаты, с которыми я их послал, попали в засаду и были безжалостно забиты до смерти мурлоками. Выжил только один – если это называется выжить. Он едва может говорить, не может ходить, его приходится кормить через трубку. Если хочешь знать, что случилось с приказами, поговори с Бенгором. Я знаю, он где-то неподалеку... и вот еще что, $n, следи, куда суешь свой нос – его ведь и откусить могут.','Поговорите с Бенгором в Каменоре, что в Болоте Печали.','Болот... ный... гово... говорун...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие приказы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приказы? Зачем тебе понадобились эти приказы?$B$BЧто ты подразумеваешь, $n? Конечно, я передал эти приказы! Солдаты, с которыми я их послал, попали в засаду и были безжалостно забиты до смерти мурлоками. Выжил только один – если это называется выжить. Он едва может говорить, не может ходить, его приходится кормить через трубку. Если хочешь знать, что случилось с приказами, поговори с Бенгором. Я знаю, он где-то неподалеку... и вот еще что, $n, следи, куда суешь свой нос – его ведь и откусить могут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бенгором в Каменоре, что в Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Болот... ный... гово... говорун...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2623,'Болотный говорун','Приказы были отданы командиром-посланником. Мы приняли... приняли приказы. На пути в Выжженные земли – засада.$B$BМурлоки... много мурлоков... Одного звали Болотный Говорун. Вырвал приказы у меня из рук, ударил копьем мне в голову. Восток... пещера...$B$B*Бенгор теряет сознание.*','Заберите приказы Вождя и верните их павшему герою Орды.','Ожидаю приказов.','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Болотный говорун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приказы были отданы командиром-посланником. Мы приняли... приняли приказы. На пути в Выжженные земли – засада.$B$BМурлоки... много мурлоков... Одного звали Болотный Говорун. Вырвал приказы у меня из рук, ударил копьем мне в голову. Восток... пещера...$B$B*Бенгор теряет сознание.*',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите приказы Вождя и верните их павшему герою Орды.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ожидаю приказов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2641,'Маленький секрет Поливалки','Когда я была маленькая, у нас в семье готовила моя сестра. Это было ужасно! Половину ее творений я даже в рот взять не могла... пока не отыскала свой "маленький секрет"! Добавь его в любую еду и... получится вкуснятина!$b$BЧто за секрет, спросишь ты. Это гриб, называемый фиалковый траган. Если хочешь помочь мне превратить эту дрянь во что-то съедобное, отправляйся во Внутренние земли и поищи там маленькое озерцо.$b$bИ не забывай, фиалковый траган растет только под водой.','Найдите фиалковый траган и вернитесь к Поливалке в Прибамбасск.','Вернитесь к Поливалке в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маленький секрет Поливалки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я была маленькая, у нас в семье готовила моя сестра. Это было ужасно! Половину ее творений я даже в рот взять не могла... пока не отыскала свой "маленький секрет"! Добавь его в любую еду и... получится вкуснятина!$b$BЧто за секрет, спросишь ты. Это гриб, называемый фиалковый траган. Если хочешь помочь мне превратить эту дрянь во что-то съедобное, отправляйся во Внутренние земли и поищи там маленькое озерцо.$b$bИ не забывай, фиалковый траган растет только под водой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите фиалковый траган и вернитесь к Поливалке в Прибамбасск.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Поливалке в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2661,'Посылка для Синя','Вот фиалковый порошок, $n. Отнеси его Синю и скажи ему, что он мой должник!','Отнесите фиалковый порошок Синю Гогельмогелю в Прибамбасск.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посылка для Синя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот фиалковый порошок, $n. Отнеси его Синю и скажи ему, что он мой должник!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите фиалковый порошок Синю Гогельмогелю в Прибамбасск.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2662,'Эликсир Гогельмогеля','А теперь вмешаем этот порошок в росу.$b$bЗаходи через пару минут... когда я доведу до совершенства великолепный эликсир Гогельмогеля!','Синь Гогельмогель хочет поговорить с вами после завершения работы над эликсиром.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир Гогельмогеля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь вмешаем этот порошок в росу.$b$bЗаходи через пару минут... когда я доведу до совершенства великолепный эликсир Гогельмогеля!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Синь Гогельмогель хочет поговорить с вами после завершения работы над эликсиром.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2681,'Камни, что связывают нас','Одних лишь твоих сил не хватит, чтобы одолеть Разелиха и его приспешников.$B$BСобери подходящую группу искателей приключений и освободи моих подчиненных от вечных мук! Тебе нужно разбить восемнадцать камней.$B$BСражайся отважно и умри с честью, $n.','Освободите девять Слуг Разелиха, трех Слуг Севины, трех Слуг Аллистария и трех Слуг Грола. Когда ваша задача будет выполнена, возвращайтесь к павшему герою. Вы должны оставаться поблизости от камней, иначе процесс не будет завершен.','Тебе это удалось, $N! Несчастные, истерзанные души наконец-то обретут покой.$B$BНо наша работа еще не завершена, $N. Нам еще многое нужно обсудить и еще больше сделать.','Да, это нелегкая задача, $N. Но не сдавайся!','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камни, что связывают нас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одних лишь твоих сил не хватит, чтобы одолеть Разелиха и его приспешников.$B$BСобери подходящую группу искателей приключений и освободи моих подчиненных от вечных мук! Тебе нужно разбить восемнадцать камней.$B$BСражайся отважно и умри с честью, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите девять Слуг Разелиха, трех Слуг Севины, трех Слуг Аллистария и трех Слуг Грола. Когда ваша задача будет выполнена, возвращайтесь к павшему герою. Вы должны оставаться поблизости от камней, иначе процесс не будет завершен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе это удалось, $N! Несчастные, истерзанные души наконец-то обретут покой.$B$BНо наша работа еще не завершена, $N. Нам еще многое нужно обсудить и еще больше сделать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, это нелегкая задача, $N. Но не сдавайся!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2701,'Герои древних времен','Пожалуйста, забери отсюда реликвию древности. Мы больше ни на что не можем использовать ее.$B$BМожет быть, она послужит тебе в борьбе против Легиона.','Откройте шкатулку и возьмите награду.','Искристый блеск на какое-то время ослепляет вас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Герои древних времен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуйста, забери отсюда реликвию древности. Мы больше ни на что не можем использовать ее.$B$BМожет быть, она послужит тебе в борьбе против Легиона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте шкатулку и возьмите награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Искристый блеск на какое-то время ослепляет вас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2702,'Герои древних времен','Твои благородство и героизм – высокая честь для меня, $n.$B$BИ для тебя – не менее высокая...','Поговорите с капралом Тундом Треснувшее Копыто.','Поистине, ты оказываешь честь нам всем. Одних лишь благодарностей будет недостаточно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Герои древних времен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои благородство и героизм – высокая честь для меня, $n.$B$BИ для тебя – не менее высокая...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капралом Тундом Треснувшее Копыто.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поистине, ты оказываешь честь нам всем. Одних лишь благодарностей будет недостаточно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2721,'Кирит','Как только завершается одна часть твоих приключений, $n, начинается другая.$B$BОдин из моих подчиненных пропал без вести – затерялся где-то в Выжженных землях. Я, конечно же, говорю о лейтенанте Кирите. $B$BКак я упоминал ранее, мы оба были в плену у Аллистария и подвергались мучениям, но увы несчастному Кириту – его сила воли оказалась недостаточно велика. Из своей клетки я слышал происходящее: крики боли разносились по пещерным залам. С тех пор Кирита и след простыл.','Узнайте, что стало с лейтенантом Киритом.','Требор? Тебя послал Требор?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кирит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только завершается одна часть твоих приключений, $n, начинается другая.$B$BОдин из моих подчиненных пропал без вести – затерялся где-то в Выжженных землях. Я, конечно же, говорю о лейтенанте Кирите. $B$BКак я упоминал ранее, мы оба были в плену у Аллистария и подвергались мучениям, но увы несчастному Кириту – его сила воли оказалась недостаточно велика. Из своей клетки я слышал происходящее: крики боли разносились по пещерным залам. С тех пор Кирита и след простыл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте, что стало с лейтенантом Киритом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Требор? Тебя послал Требор?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (2741,'Супер Яйц-О-Матик','Вернитесь к Яйц-О-Матику в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Супер Яйц-О-Матик',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Яйц-О-Матику в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2742,'Рин\'джи в ловушке','Эй, |3-6($r)!$B$BРин\'джи потерял топор, и его схватили! Пожалуйста, помоги Рин\'джи сбежать. Я знаю, что не $gкаждый:каждая:r; |3-6($r) любит троллей, но я тебя очень прошу! Мне надо выйти отсюда!$B$BУ меня кое-что есть, и очень хорошее, если поможешь мне, я тебе это подарю...$B$BРин\'джи спрятал свой секрет в Отвесных скалах.','Выведите Рин\'джи из Сторожки Кель\'Данил, а потом найдите то, что он спрятал в Отвесных скалах, на востоке.','Эта табличка, наверное, и есть тот самый "секрет", о котором говорил Рин\'джи.$B$BОна покрыта странными письменами, которые вам совершенно не знакомы.','Рин\'джи напуган!','Проводить Рин\'джи в безопасное место.','Найдите секрет Рин\'джи на Отвесных скалах, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рин\'джи в ловушке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, |3-6($r)!$B$BРин\'джи потерял топор, и его схватили! Пожалуйста, помоги Рин\'джи сбежать. Я знаю, что не $gкаждый:каждая:r; |3-6($r) любит троллей, но я тебя очень прошу! Мне надо выйти отсюда!$B$BУ меня кое-что есть, и очень хорошее, если поможешь мне, я тебе это подарю...$B$BРин\'джи спрятал свой секрет в Отвесных скалах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выведите Рин\'джи из Сторожки Кель\'Данил, а потом найдите то, что он спрятал в Отвесных скалах, на востоке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта табличка, наверное, и есть тот самый "секрет", о котором говорил Рин\'джи.$B$BОна покрыта странными письменами, которые вам совершенно не знакомы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рин\'джи напуган!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводить Рин\'джи в безопасное место.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Найдите секрет Рин\'джи на Отвесных скалах, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2743,'Покров Тьмы','Не будем тратить слов, |3-6($r); мое время здесь ограничено.$B$BТебе следует уничтожить троицу силы, связанную с повелителем демонов Разелихом. Это деяние не настолько просто, как задача по освобождению проклятой души.$B$B*Кирит ухмыляется.*$B$BВидишь ли, каждый из прислужников Разелиха носит на шее треть амулета, при помощи которого был создан Разелих. Тот же самый амулет понадобится тебе для призвания сего архидемона.$B$BВозвращайся к Требору и поведай ему, что требуется для призвания Разелиха. Он подскажет тебе, что делать дальше.','Вернитесь к павшему герою Орды со своими находками.','Повелитель демонов проявляет хитрость почти столь же расчетливую, как и его жестокость, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покров Тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не будем тратить слов, |3-6($r); мое время здесь ограничено.$B$BТебе следует уничтожить троицу силы, связанную с повелителем демонов Разелихом. Это деяние не настолько просто, как задача по освобождению проклятой души.$B$B*Кирит ухмыляется.*$B$BВидишь ли, каждый из прислужников Разелиха носит на шее треть амулета, при помощи которого был создан Разелих. Тот же самый амулет понадобится тебе для призвания сего архидемона.$B$BВозвращайся к Требору и поведай ему, что требуется для призвания Разелиха. Он подскажет тебе, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к павшему герою Орды со своими находками.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Повелитель демонов проявляет хитрость почти столь же расчетливую, как и его жестокость, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2744,'Охотник на демонов','Эта троица находится под покровительством Разелиха.$B$BВ обмен на их службу Разелих даровал каждому из них почти безграничную власть над Выжженными землями. Кусочки амулета связаны с жизненной силой их владельцев и дают им бессмертие. Пока они остаются в Выжженных землях, их нельзя убить и их жизнь продлится до конца мира.$B$BНо есть некто, способный оказать тебе помощь в дальнейшем, $n. Отправляйся в Азшару и найди там охотника на демонов, Лорама Многонога. Поиск следует вести на островах.','Поговорите в Азшаре с Лорамом Многоногом.','Я помогу тебе. Однако мне кажется, что ты не совсем понимаешь, против чего сражаешься.','Что ты здесь делаешь?','Поговорите с Лорамом','Вернитесь к Лораму Многоногу на Залив Бурь, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охотник на демонов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта троица находится под покровительством Разелиха.$B$BВ обмен на их службу Разелих даровал каждому из них почти безграничную власть над Выжженными землями. Кусочки амулета связаны с жизненной силой их владельцев и дают им бессмертие. Пока они остаются в Выжженных землях, их нельзя убить и их жизнь продлится до конца мира.$B$BНо есть некто, способный оказать тебе помощь в дальнейшем, $n. Отправляйся в Азшару и найди там охотника на демонов, Лорама Многонога. Поиск следует вести на островах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Азшаре с Лорамом Многоногом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я помогу тебе. Однако мне кажется, что ты не совсем понимаешь, против чего сражаешься.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ты здесь делаешь?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поговорите с Лорамом',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лораму Многоногу на Залив Бурь, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2745,'Проникновение в крепость','Хм-м, интересная история, причем не из тех, на которые можно наплевать. Да, помочь-то я вам могу, но то, что вам нужно будет сделать, это свершить правосудие... частично незаконным путем, если уж вы хотите довести дело до конца.$b$bС Лесковаром и Марзоном нужно разобраться – и быстро. Как думаете, вы на это способны?$b$bРешать вам. Если да, то поскорее отправляйтесь в крепость и найдите там моего старинного друга – гнома по имени Тирион. Он уже пару недель как наблюдает за Лесковаром. Он сможет помочь вам покончить с этим делом.','Поговорите с Тирионом в крепости Штормграда.','Какого?! Не подкрадывайтесь ко мне вот так! И говорите тише! На кой вы, спрашивается, во имя Теней, так ко мне подкрадываетесь? Не видите, что ли – я занят, безмозглое вы создание!$B$BЧто вы имеете в виду, спрашивая, что я делаю? Жду открытия следующего Темного портала, а вы что подумали? Выкладывайте, с чем пришли, и валите отсюда... пока стражники не заметили, что мы тут вдвоем в кустах прячемся. Мне нужно блюсти репутацию.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проникновение в крепость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм-м, интересная история, причем не из тех, на которые можно наплевать. Да, помочь-то я вам могу, но то, что вам нужно будет сделать, это свершить правосудие... частично незаконным путем, если уж вы хотите довести дело до конца.$b$bС Лесковаром и Марзоном нужно разобраться – и быстро. Как думаете, вы на это способны?$b$bРешать вам. Если да, то поскорее отправляйтесь в крепость и найдите там моего старинного друга – гнома по имени Тирион. Он уже пару недель как наблюдает за Лесковаром. Он сможет помочь вам покончить с этим делом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тирионом в крепости Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какого?! Не подкрадывайтесь ко мне вот так! И говорите тише! На кой вы, спрашивается, во имя Теней, так ко мне подкрадываетесь? Не видите, что ли – я занят, безмозглое вы создание!$B$BЧто вы имеете в виду, спрашивая, что я делаю? Жду открытия следующего Темного портала, а вы что подумали? Выкладывайте, с чем пришли, и валите отсюда... пока стражники не заметили, что мы тут вдвоем в кустах прячемся. Мне нужно блюсти репутацию.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2746,'Все по порядку','Триас хочет поторопить события, так? Ладно, мы это сделаем, но сейчас я не готов. И, кстати, сложную часть я беру на себя, а ручки пачкать будете вы, это понятно? Отлично.$b$bЗначит, мне нужно, чтобы вы мне кое-что принесли, чтобы я смог воплотить в жизнь свой план. У меня есть мысль об отличной маскировке, при помощи которой этот робот-шпион пройдет мимо стражников.$b$bПринесите мне немного шелка и пару яблок. Где достать шелк – думайте сами, а вот подходящие яблоки есть у Клары в ее маленьком хозяйстве сразу за городской чертой.','Принесите Тириону в Штормград 3 отреза шелка и 2 свежих яблока Клары.','Я наблюдаю за Лесковаром вот уже две недели. Триас никогда ему не доверял, но мы и не подозревали, что он втянут во что-то, связанное с Братством Справедливости. Мы отслеживали то, что могло связывать его с Сумеречным Молотом. В любом случае, он становится более опасным, чем допустимо для этого города, и тут-то мы и вступаем в дело.$B$BПринесите мне указанные предметы, и мы сможем осуществить мой план.','Вернитесь к Тириону в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все по порядку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Триас хочет поторопить события, так? Ладно, мы это сделаем, но сейчас я не готов. И, кстати, сложную часть я беру на себя, а ручки пачкать будете вы, это понятно? Отлично.$b$bЗначит, мне нужно, чтобы вы мне кое-что принесли, чтобы я смог воплотить в жизнь свой план. У меня есть мысль об отличной маскировке, при помощи которой этот робот-шпион пройдет мимо стражников.$b$bПринесите мне немного шелка и пару яблок. Где достать шелк – думайте сами, а вот подходящие яблоки есть у Клары в ее маленьком хозяйстве сразу за городской чертой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Тириону в Штормград 3 отреза шелка и 2 свежих яблока Клары.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я наблюдаю за Лесковаром вот уже две недели. Триас никогда ему не доверял, но мы и не подозревали, что он втянут во что-то, связанное с Братством Справедливости. Мы отслеживали то, что могло связывать его с Сумеречным Молотом. В любом случае, он становится более опасным, чем допустимо для этого города, и тут-то мы и вступаем в дело.$B$BПринесите мне указанные предметы, и мы сможем осуществить мой план.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тириону в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (2747,'Необычное яйцо','Вернитесь к Кургль Поскакушке в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычное яйцо',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кургль Поскакушке в Танарис.',`completedtext_loc8`);
