INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (2750,'Плохое яйцо','Вернитесь к Кургль Поскакушке в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плохое яйцо',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кургль Поскакушке в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2751,'Варварские доспехи','Двадцать поколений Омошей держали в руках этот молот, $n! Сколько тонн металла мы перековали! Но, увы, на мне наш род завершится. У меня нет потомства.$b$bЯ не могу допустить, чтобы тайные чертежи и приемы Омошей умерли вместе со мной!$b$bДокажи Орокку, что ты годишься в кузнецы, $n. Принеси ему 2 украшенных узором бронзовых наруча, 2 бронзовых длинных меча и 2 острых когтя. Принеси их Орокку, и мы продолжим обучение.','Наш род иссякнет, но, возможно, легенды об Омошах будут жить!$B$BДа, $N, ты настоящий кузнец! Главная награда для кузнеца – видеть оружие и доспехи своей работы обагренными кровью врагов!$B$BПусть изготовленная тобою кираса ржавеет только от вражеской крови!','Бронзы, $N! Еще бронзы!','Вернитесь к Орокку Омошу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Варварские доспехи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Двадцать поколений Омошей держали в руках этот молот, $n! Сколько тонн металла мы перековали! Но, увы, на мне наш род завершится. У меня нет потомства.$b$bЯ не могу допустить, чтобы тайные чертежи и приемы Омошей умерли вместе со мной!$b$bДокажи Орокку, что ты годишься в кузнецы, $n. Принеси ему 2 украшенных узором бронзовых наруча, 2 бронзовых длинных меча и 2 острых когтя. Принеси их Орокку, и мы продолжим обучение.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наш род иссякнет, но, возможно, легенды об Омошах будут жить!$B$BДа, $N, ты настоящий кузнец! Главная награда для кузнеца – видеть оружие и доспехи своей работы обагренными кровью врагов!$B$BПусть изготовленная тобою кираса ржавеет только от вражеской крови!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Бронзы, $N! Еще бронзы!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орокку Омошу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2752,'За железным наплечьем','У тебя внимательные глаза, $n. Ты вбираешь мудрость Омошей, точно губка!$b$bТри урока дам я тебе.$b$bВернись к наковальне и сделай для Орокка 4 бронзовых боевых топора и 4 бронзовых боевых молота. Лишь тогда узнаешь ты, как изготовить железное наплечье!','Принесите Орокку Омошу в Оргриммар 4 бронзовых боевых топора и 4 бронзовых боевых молота.','Орокк гордится тобой, $N. Вот, читай, как изготовить железное оплечье!','Продемонстрируй мне свое усердие, |3-6($R)','Вернитесь к Орокку Омошу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За железным наплечьем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя внимательные глаза, $n. Ты вбираешь мудрость Омошей, точно губка!$b$bТри урока дам я тебе.$b$bВернись к наковальне и сделай для Орокка 4 бронзовых боевых топора и 4 бронзовых боевых молота. Лишь тогда узнаешь ты, как изготовить железное наплечье!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Орокку Омошу в Оргриммар 4 бронзовых боевых топора и 4 бронзовых боевых молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Орокк гордится тобой, $N. Вот, читай, как изготовить железное оплечье!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Продемонстрируй мне свое усердие, |3-6($R)',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орокку Омошу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2753,'Тяжелая поступь','Орокк научит тебя еще двум вещам, $n. Да, я знаю, тебе тяжело, но надо продолжать – во имя Омошей!$b$bПринеси 4 зеленых железных шлема, 4 пары зеленых железных наручей и 2 пары зеленых железных поножей – и я научу тебя тому, что будет страшить твоих врагов!','Принесите 4 зеленых железных шлема, 4 пары зеленых железных наручей и 2 пары зеленых железных поножей Орокку Омошу в Оргриммар.','Ты напоминаешь Орокку его деда, Горокка Омоша! Вот, читай, учись делать железные сапоги.','Их черепа будут трещать под твоими сапогами!','Вернитесь к Орокку Омошу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжелая поступь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орокк научит тебя еще двум вещам, $n. Да, я знаю, тебе тяжело, но надо продолжать – во имя Омошей!$b$bПринеси 4 зеленых железных шлема, 4 пары зеленых железных наручей и 2 пары зеленых железных поножей – и я научу тебя тому, что будет страшить твоих врагов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 зеленых железных шлема, 4 пары зеленых железных наручей и 2 пары зеленых железных поножей Орокку Омошу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты напоминаешь Орокку его деда, Горокка Омоша! Вот, читай, учись делать железные сапоги.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Их черепа будут трещать под твоими сапогами!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орокку Омошу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2754,'Рога безумия','Это последнее, чему научит тебя Орокк, $n. Но прежде принеси Орокку 2 прочных железных кувалды, 2 пары посеребренных бронзовых сапог и две пары посеребренных бронзовых рукавиц.$b$bТы узнаешь, как приятно видеть страх в глазах врагов при одном твоем появлении!','Принесите Орокку Омошу в Оргриммар 2 прочных железных кувалды, 2 пары посеребренных бронзовых сапог и 2 пары посеребренных бронзовых рукавиц.','Потрясающе, $N! Теперь ты знаешь все секреты Омошей!','Ну-ка, $N, покажи железу, кто тут главный!','Вернитесь к Орокку Омошу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рога безумия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это последнее, чему научит тебя Орокк, $n. Но прежде принеси Орокку 2 прочных железных кувалды, 2 пары посеребренных бронзовых сапог и две пары посеребренных бронзовых рукавиц.$b$bТы узнаешь, как приятно видеть страх в глазах врагов при одном твоем появлении!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Орокку Омошу в Оргриммар 2 прочных железных кувалды, 2 пары посеребренных бронзовых сапог и 2 пары посеребренных бронзовых рукавиц.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе, $N! Теперь ты знаешь все секреты Омошей!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну-ка, $N, покажи железу, кто тут главный!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орокку Омошу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2755,'Радости Омоша','Научитесь танцу Радости Омошей.','Давненько Орокк не плясал танец Радости Омошей! Ну, $N, смотри и учись!','Выучите танец радости Омошей.','Вернитесь к Орокку Омошу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Радости Омоша',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Научитесь танцу Радости Омошей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давненько Орокк не плясал танец Радости Омошей! Ну, $N, смотри и учись!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Выучите танец радости Омошей.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орокку Омошу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2756,'Старые обычаи','В былые легендарные времена Атурк сокрушил бы черепа своих врагов и истер кости в мелкий порошок! Но эти дни давно миновали, |3-6($r). Вождь требует мира между кланами, и старых врагов мы теперь даже пальцем тронуть не смеем.$b$bДаже не верится! Но такова воля Тралла.$b$bНу, довольно жалоб! Ты здесь, чтобы учиться – и ты будешь учиться! Принеси 4 стальные кирасы и 4 стальных латных шлема, и узнаешь вкус войны!','Принесите 4 стальные кирасы и 4 стальных латных шлема Атурку Наковальне в Оргриммар.','Похоже ты еще жив, $N. Как разочаровывающе. Разве ты не знаешь, что самой славной наградой является смерть на поле битвы! А я вот здесь, по приказу Тралла учу детишек мастерить. Смотри и учись... дитя...','Атурк, как время, никого не ждет! Торопись, $Gдурак:дура;!','Вернитесь к Атурку Наковальне на Аллею Чести в Оргриммар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старые обычаи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В былые легендарные времена Атурк сокрушил бы черепа своих врагов и истер кости в мелкий порошок! Но эти дни давно миновали, |3-6($r). Вождь требует мира между кланами, и старых врагов мы теперь даже пальцем тронуть не смеем.$b$bДаже не верится! Но такова воля Тралла.$b$bНу, довольно жалоб! Ты здесь, чтобы учиться – и ты будешь учиться! Принеси 4 стальные кирасы и 4 стальных латных шлема, и узнаешь вкус войны!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 стальные кирасы и 4 стальных латных шлема Атурку Наковальне в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже ты еще жив, $N. Как разочаровывающе. Разве ты не знаешь, что самой славной наградой является смерть на поле битвы! А я вот здесь, по приказу Тралла учу детишек мастерить. Смотри и учись... дитя...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Атурк, как время, никого не ждет! Торопись, $Gдурак:дура;!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Атурку Наковальне на Аллею Чести в Оргриммар',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2757,'Вперед, в Пиратскую Бухту!','Слышь, будешь болтаться здесь – так ничему и не научишься!$b$bВот я знаю мужика, который знает мужика, который ошивается возле кузницы в Пиратской Бухте. Покажи ему этот значок, и он тебе про мифрил все расскажет!$b$bЧего-чего? Оставь это грудным младенцам, $n, тебе пора двигаться дальше!$b$bЕсли тебя это интересует, его звать Макгеван.','Поговорите с Макгеваном в Пиратской Бухте.','Клянусь задницей Черного Копыта! Наконец хоть кто-то достойный Ордена мифрила!','Экий редкий зверь к нам пожаловал! Ну-ка, покажи свой значок...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед, в Пиратскую Бухту!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слышь, будешь болтаться здесь – так ничему и не научишься!$b$bВот я знаю мужика, который знает мужика, который ошивается возле кузницы в Пиратской Бухте. Покажи ему этот значок, и он тебе про мифрил все расскажет!$b$bЧего-чего? Оставь это грудным младенцам, $n, тебе пора двигаться дальше!$b$bЕсли тебя это интересует, его звать Макгеван.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Макгеваном в Пиратской Бухте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клянусь задницей Черного Копыта! Наконец хоть кто-то достойный Ордена мифрила!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Экий редкий зверь к нам пожаловал! Ну-ка, покажи свой значок...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2758,'Происхождение кузнечного искусства','Когда я был примерно в твоем возрасте, дворф по имени Гальван взял меня под свою опеку и обучил меня способам ковки доспехов. Перед своим отъездом в Пиратскую Бухту он заставил меня пообещать, что я буду до конца дней своих обучать всех, у кого будет желание и решимость овладеть кузнечным ремеслом. Так я и поступил.$b$bИтак, теперь настало твое время чему-нибудь научиться. Сделай мне шесть пар золотых чешуйчатых наручей – и узнаешь, откуда есть пошло кузнечное дело, $n.','Принесите 6 пар золотых чешуйчатых наручей Ханку Молоту в Штормград.','Может быть, ты станешь одним из наследников Гальвана!','Вернитесь к Ханку Молоту в Квартал Дворфов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Происхождение кузнечного искусства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я был примерно в твоем возрасте, дворф по имени Гальван взял меня под свою опеку и обучил меня способам ковки доспехов. Перед своим отъездом в Пиратскую Бухту он заставил меня пообещать, что я буду до конца дней своих обучать всех, у кого будет желание и решимость овладеть кузнечным ремеслом. Так я и поступил.$b$bИтак, теперь настало твое время чему-нибудь научиться. Сделай мне шесть пар золотых чешуйчатых наручей – и узнаешь, откуда есть пошло кузнечное дело, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 пар золотых чешуйчатых наручей Ханку Молоту в Штормград.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Может быть, ты станешь одним из наследников Гальвана!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ханку Молоту в Квартал Дворфов Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2759,'В поисках Гальвана','Хотя Гальван покинул Пиратскую Бухту много лет назад, члены ордена по-прежнему остаются в городе, надеясь однажды найти кого-нибудь, достойного внимания мастера.$b$bВозьми этот знак и отдай его Макгевану в Пиратской Бухте.$b$bЕсли ты действительно с этим справишься, он поймет, что ты $gдостоин:достойна;. Я в тебя верю, $n!','Поговорите с Макгеваном в Пиратской Бухте.','Клянусь гривой Черного Копыта – наконец-то появился хоть кто-то, достойный Ордена мифрила!','Редкая ты, должно быть, птица, дружище. Дай-ка мне глянуть на этот знак...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Гальвана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя Гальван покинул Пиратскую Бухту много лет назад, члены ордена по-прежнему остаются в городе, надеясь однажды найти кого-нибудь, достойного внимания мастера.$b$bВозьми этот знак и отдай его Макгевану в Пиратской Бухте.$b$bЕсли ты действительно с этим справишься, он поймет, что ты $gдостоин:достойна;. Я в тебя верю, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Макгеваном в Пиратской Бухте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клянусь гривой Черного Копыта – наконец-то появился хоть кто-то, достойный Ордена мифрила!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Редкая ты, должно быть, птица, дружище. Дай-ка мне глянуть на этот знак...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2760,'Орден Мифрила','Большинство наших новобранцев так и не добрались до Пиратской Бухты, $n. Блеска эмблемы оказывается достаточно, чтобы пробудить алчность даже в самых стойких кузнецах. Дураки, эмблема эта – капля в море по сравнению со стоимостью предметов, которые ты увидишь!$B$BНайди Гальвана Древнего и покажи ему эту булавку. Он живет далеко на севере, между Зул-Гурубом и холмом Мош\'Огг.','Поговорите с Гальваном Древним в Тернистой долине.','А, прошло много лет, с тех пор, как я в последний раз видел достойных принятия в Орден мифрила. Начнем же!','Приветствую! Подойди ближе покажи Гальвану, что у тебя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орден Мифрила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большинство наших новобранцев так и не добрались до Пиратской Бухты, $n. Блеска эмблемы оказывается достаточно, чтобы пробудить алчность даже в самых стойких кузнецах. Дураки, эмблема эта – капля в море по сравнению со стоимостью предметов, которые ты увидишь!$B$BНайди Гальвана Древнего и покажи ему эту булавку. Он живет далеко на севере, между Зул-Гурубом и холмом Мош\'Огг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гальваном Древним в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, прошло много лет, с тех пор, как я в последний раз видел достойных принятия в Орден мифрила. Начнем же!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую! Подойди ближе покажи Гальвану, что у тебя.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2761,'Плавим, не плавим, плавим, не плавим...','Многие кузнецы считают, что горное дело и кузнечное ремесло – две разные вещи; но что за кузнец без металла? Как же, это невозможно! Опытный кузнец должен быть и опытным горняком.$B$BПокажи Гальвану, на что ты $gспособен:способна;, $n. Принеси мне сорок слитков железа и сорок слитков мифрила. За это Гальван научит тебя создавать изысканные мифриловые штаны!','Принесите сорок мифриловых слитков и сорок железных слитков Гальвану Древнему из Тернистой долины.','Твои работы безупречны! Ты начинаешь понимать основы минералогии Гальвана! Возьми это и научись всему, чему сможешь.','Когда хорошо поработаешь, мышцы ноют и тело ломит!','Вернитесь к Гальвану Древнему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плавим, не плавим, плавим, не плавим...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие кузнецы считают, что горное дело и кузнечное ремесло – две разные вещи; но что за кузнец без металла? Как же, это невозможно! Опытный кузнец должен быть и опытным горняком.$B$BПокажи Гальвану, на что ты $gспособен:способна;, $n. Принеси мне сорок слитков железа и сорок слитков мифрила. За это Гальван научит тебя создавать изысканные мифриловые штаны!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сорок мифриловых слитков и сорок железных слитков Гальвану Древнему из Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои работы безупречны! Ты начинаешь понимать основы минералогии Гальвана! Возьми это и научись всему, чему сможешь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда хорошо поработаешь, мышцы ноют и тело ломит!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гальвану Древнему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2762,'Обманное серебро','Говорят, что истинное серебро прочнее мифрила. Гальван не будет спорить с такой оценкой, но вопреки названию, истинное серебро далеко от истины! Мифрил куда благороднее! ХА! И тем не менее, на сей раз тебе придется найти это обманное серебро.$B$BПринеси мне сорок мифриловых слитков и пять слитков истинного серебра. Взамен я научу тебя искусству изготовления изысканных мифриловых перчаток, и что куда важнее, ты узнаешь, что истинному серебру веры нет.','Принесите сорок мифриловых слитков и пять слитков истинного серебра Гальвану Древнему из Тернистой долины.','Нелегко с ним справиться, а? Я об истинном серебре. Гальван потратил не меньше десяти лет в горах Альтерака, прежде чем усвоил этот урок. Возьми это и научись, чему сможешь!','Когда хорошо поработаешь, мышцы ноют и тело ломит!','Вернитесь к Гальвану Древнему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обманное серебро',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что истинное серебро прочнее мифрила. Гальван не будет спорить с такой оценкой, но вопреки названию, истинное серебро далеко от истины! Мифрил куда благороднее! ХА! И тем не менее, на сей раз тебе придется найти это обманное серебро.$B$BПринеси мне сорок мифриловых слитков и пять слитков истинного серебра. Взамен я научу тебя искусству изготовления изысканных мифриловых перчаток, и что куда важнее, ты узнаешь, что истинному серебру веры нет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сорок мифриловых слитков и пять слитков истинного серебра Гальвану Древнему из Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нелегко с ним справиться, а? Я об истинном серебре. Гальван потратил не меньше десяти лет в горах Альтерака, прежде чем усвоил этот урок. Возьми это и научись, чему сможешь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда хорошо поработаешь, мышцы ноют и тело ломит!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гальвану Древнему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2763,'Могущество камней','Для нашего ремесла очень важно научиться добывать драгоценные камни. Немногие камни драгоценнее цитрина. Он во много раз усиливает ту магию, которую мы вкладываем в наши творения.$B$BНа сей раз мы усилим сорок слитков мифрила четырьмя цитринами. В результате ты получишь лучшее представление о магической гемологии и научишься создавать изысканные мифриловые наплечники.','Принесите сорок мифриловых слитков и 4 цитрина Гальвану Древнему из Тернистой долины.','Когда хорошо поработаешь, мышцы ноют и тело ломит!','Вернитесь к Гальвану Древнему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Могущество камней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для нашего ремесла очень важно научиться добывать драгоценные камни. Немногие камни драгоценнее цитрина. Он во много раз усиливает ту магию, которую мы вкладываем в наши творения.$B$BНа сей раз мы усилим сорок слитков мифрила четырьмя цитринами. В результате ты получишь лучшее представление о магической гемологии и научишься создавать изысканные мифриловые наплечники.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сорок мифриловых слитков и 4 цитрина Гальвану Древнему из Тернистой долины.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда хорошо поработаешь, мышцы ноют и тело ломит!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гальвану Древнему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2764,'Лучший ученик Гальвана','Если ты $gготов:готова; покинуть Гальвана, отправляйся в Прибамбасск.$B$BТам живет мой лучший ученик, Трентон Молот Света. Он научит тебя обращению с изысканным мифрилом. Впрочем, можешь остаться здесь и поучиться еще!$B$BАх да, Прибамбасск находится в Танарисе!','Поговорите с Трентоном Молотом Света из Прибамбасска.','Тебя прислал Гальван Древний?\n\nТрентон кланяется\n\nЭто большая честь – познакомиться с еще одним из его учеников!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучший ученик Гальвана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты $gготов:готова; покинуть Гальвана, отправляйся в Прибамбасск.$B$BТам живет мой лучший ученик, Трентон Молот Света. Он научит тебя обращению с изысканным мифрилом. Впрочем, можешь остаться здесь и поучиться еще!$B$BАх да, Прибамбасск находится в Танарисе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Трентоном Молотом Света из Прибамбасска.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Гальван Древний?\n\nТрентон кланяется\n\nЭто большая честь – познакомиться с еще одним из его учеников!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2765,'Кузнец-умелец!','Я с первого взгляда понял, что ты станешь $gодним из моих лучших учеников:одной из моих лучших учениц;! Ты без колебаний $gотдал:отдала; Макгевану вещь, наделенную силой, лишь бы только встретиться со мной. Подобная слепая вера и преданность искусству должна быть вознаграждена.$B$BТы $gстал:стала; настоящим экспертом в кузнечном деле. Насладись же наградой!','Получите награду у Гальвана Древнего!','Что ж, ты в самом деле заслужил украшение, наделенное большей силой, чем то, которым пришлось пожертвовать на пути сюда. Пользуйся на здоровье, $n.','Вы победитель','Вернитесь к Гальвану Древнему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кузнец-умелец!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я с первого взгляда понял, что ты станешь $gодним из моих лучших учеников:одной из моих лучших учениц;! Ты без колебаний $gотдал:отдала; Макгевану вещь, наделенную силой, лишь бы только встретиться со мной. Подобная слепая вера и преданность искусству должна быть вознаграждена.$B$BТы $gстал:стала; настоящим экспертом в кузнечном деле. Насладись же наградой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите награду у Гальвана Древнего!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, ты в самом деле заслужил украшение, наделенное большей силой, чем то, которым пришлось пожертвовать на пути сюда. Пользуйся на здоровье, $n.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Вы победитель',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гальвану Древнему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2766,'Найти КПХ-22/FE!','Перед вами странный металлический предмет яйцевидной формы. Вы понажимали на кнопочки – и внезапно яйцо ожило и раскрылось. Очевидно, это какой-то гномский приборчик! Из механического яйца раздается искаженный разрядами голос:$b$b"Меня зовут Карлс Пропеллерз. Мой автономный робот попал в аварию! Обнаруживший его получит награду! Прошу вас, доставьте этот маячок к роботу!$b$bЯ вычислил координаты робота – он находится в пещере рядом с Долиной Свирепого Утеса!"','Отнесите аварийный маяк к автономному роботу Карлса, в пещеру рядом с Долиной Свирепого Утеса.','Вы помещаете яйцо... то есть аварийный маяк... внутрь цыпленка... то есть автономного робота.$B$BВнутри робота слышится гудение и жужжание. Он пытается подняться на ноги. После того как робот оживает, снова слышится голос Карлса, но на этот раз изнутри робота:$B$B"Ну что ж, по крайней мере, OOX-22/FE работает. Однако он нуждается в серьезном ремонте! Нести его вы не сможете, он слишком тяжелый... О! У меня идея! Не согласитесь ли вы его проводить?"','Больше всего это похоже на обломки... механического цыпленка. Изнутри яйца снова раздается голосок: "Да, отличная работа! Это мой автономный робот. Сенсоры показывают, что без подзарядки он не заведется и не долетит в Пиратскую бухту на починку... Иди вперед и положи маяк в робота – дальше он сам все сделает!"') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти КПХ-22/FE!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перед вами странный металлический предмет яйцевидной формы. Вы понажимали на кнопочки – и внезапно яйцо ожило и раскрылось. Очевидно, это какой-то гномский приборчик! Из механического яйца раздается искаженный разрядами голос:$b$b"Меня зовут Карлс Пропеллерз. Мой автономный робот попал в аварию! Обнаруживший его получит награду! Прошу вас, доставьте этот маячок к роботу!$b$bЯ вычислил координаты робота – он находится в пещере рядом с Долиной Свирепого Утеса!"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите аварийный маяк к автономному роботу Карлса, в пещеру рядом с Долиной Свирепого Утеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы помещаете яйцо... то есть аварийный маяк... внутрь цыпленка... то есть автономного робота.$B$BВнутри робота слышится гудение и жужжание. Он пытается подняться на ноги. После того как робот оживает, снова слышится голос Карлса, но на этот раз изнутри робота:$B$B"Ну что ж, по крайней мере, OOX-22/FE работает. Однако он нуждается в серьезном ремонте! Нести его вы не сможете, он слишком тяжелый... О! У меня идея! Не согласитесь ли вы его проводить?"',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Больше всего это похоже на обломки... механического цыпленка. Изнутри яйца снова раздается голосок: "Да, отличная работа! Это мой автономный робот. Сенсоры показывают, что без подзарядки он не заведется и не долетит в Пиратскую бухту на починку... Иди вперед и положи маяк в робота – дальше он сам все сделает!"',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2767,'Спасти КПХ-22/FE!','Из динамика снова слышится искаженный разрядами голос гнома:$b$b"Мне необходимо перегнать КПХ-22/FE в просторное и безопасное место, чтобы начать длительную процедуру подготовки к взлету. Проводите робота из того места, где вы его обнаружили, в... ну, скажем, на большую дорогу! Это самое подходящее место, и там достаточно просторно, чтобы аппарату было где развернуться.$b$bПроводите робота в порт, а затем сообщите об этом мне. Я живу в Пиратской Бухте, меня зовут Карлс Пропеллерз. Конец связи!"','Проводите КПX-22/FE в безопасное место, затем сообщите об этом Карлсу Пропеллерзу в Пиратской Бухте.','О, спаситель! Вы доставили на место OOX-22/FE! У меня просто слов нет, настолько я вам благодарен! Моя серия автономных роботов постоянно нуждается в усовершенствованиях, однако ваша помощь сберегла мне немало часов кропотливой работы, и дорогостоящих деталей вдобавок!$B$BПрошу вас, выбирайте любую из этих готовых моделей. Еще раз спасибо вам, $N! Мы с моими роботами – ваши должники!','Да, я Оглторп Обнотикус, мастер-изобретатель к вашим услугам! Могу я вам чем-то помочь?','Проводить КПX-22/FE в безопасное место','Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасти КПХ-22/FE!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из динамика снова слышится искаженный разрядами голос гнома:$b$b"Мне необходимо перегнать КПХ-22/FE в просторное и безопасное место, чтобы начать длительную процедуру подготовки к взлету. Проводите робота из того места, где вы его обнаружили, в... ну, скажем, на большую дорогу! Это самое подходящее место, и там достаточно просторно, чтобы аппарату было где развернуться.$b$bПроводите робота в порт, а затем сообщите об этом мне. Я живу в Пиратской Бухте, меня зовут Карлс Пропеллерз. Конец связи!"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите КПX-22/FE в безопасное место, затем сообщите об этом Карлсу Пропеллерзу в Пиратской Бухте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, спаситель! Вы доставили на место OOX-22/FE! У меня просто слов нет, настолько я вам благодарен! Моя серия автономных роботов постоянно нуждается в усовершенствованиях, однако ваша помощь сберегла мне немало часов кропотливой работы, и дорогостоящих деталей вдобавок!$B$BПрошу вас, выбирайте любую из этих готовых моделей. Еще раз спасибо вам, $N! Мы с моими роботами – ваши должники!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, я Оглторп Обнотикус, мастер-изобретатель к вашим услугам! Могу я вам чем-то помочь?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводить КПX-22/FE в безопасное место',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2768,'Изыскательский жезл','Сержант Блай обокрал меня! Он сказал, что он только одолжит, но он украл мой драгоценный изыскательский жезл!!! Без этого жезла как я буду знать, где бурить новые скважины под воду??$B$BНайди Блая и принеси мне мой жезл! Я услышал, что он вынудил его компашку низкопробных авантюристов идти за сокровищами в Зул\'Фаррак, – город, расположенный на западе. Держу пари, там ты его и найдешь.$B$BНадеюсь, что он уже повстречался с троллями, потому что если тебе придется драться с ним за мой жезл, то схватка выйдет нешуточная.','Принесите изыскательский жезл главному инженеру Чепухастеру в Прибамбасск.','Ты нашел Блая? Ты принес мой изыскательский стержень?','Вернитесь к главному инженеру Чепухастеру в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изыскательский жезл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сержант Блай обокрал меня! Он сказал, что он только одолжит, но он украл мой драгоценный изыскательский жезл!!! Без этого жезла как я буду знать, где бурить новые скважины под воду??$B$BНайди Блая и принеси мне мой жезл! Я услышал, что он вынудил его компашку низкопробных авантюристов идти за сокровищами в Зул\'Фаррак, – город, расположенный на западе. Держу пари, там ты его и найдешь.$B$BНадеюсь, что он уже повстречался с троллями, потому что если тебе придется драться с ним за мой жезл, то схватка выйдет нешуточная.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите изыскательский жезл главному инженеру Чепухастеру в Прибамбасск.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел Блая? Ты принес мой изыскательский стержень?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Чепухастеру в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2769,'Братья Медноштиф','Вы еще не встречались с братьями Медноштиф? Они на Мерцающей равнине в Калимдоре гоняют на своем болиде наперегонки с гоблинами. Обычно они выигрывают, что неудивительно: гоблинские машины взрываются так часто, что едва дотягивают до финишной черты!$B$BНо братья Медноштиф все равно постоянно ищут новые способы сделать свою машину еще более скоростной, и Виззл сказал мне, что ему нужен очень редкий компонент для очередных экспериментов.$B$BПохоже, ему надо с этим помочь. Спросите его на этот счет.','Поговорите с Виззлом Медноштифом на Мерцающей равнине.','Так ты хочешь мне помочь? Отлично!$B$BМне для эксперимента нужна одна штука, и отважный $C вроде тебя добудет ее без труда!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья Медноштиф',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы еще не встречались с братьями Медноштиф? Они на Мерцающей равнине в Калимдоре гоняют на своем болиде наперегонки с гоблинами. Обычно они выигрывают, что неудивительно: гоблинские машины взрываются так часто, что едва дотягивают до финишной черты!$B$BНо братья Медноштиф все равно постоянно ищут новые способы сделать свою машину еще более скоростной, и Виззл сказал мне, что ему нужен очень редкий компонент для очередных экспериментов.$B$BПохоже, ему надо с этим помочь. Спросите его на этот счет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Виззлом Медноштифом на Мерцающей равнине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ты хочешь мне помочь? Отлично!$B$BМне для эксперимента нужна одна штука, и отважный $C вроде тебя добудет ее без труда!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2770,'Газ\'рилла','В пустыне Танарис есть город троллей – Зул\'Фаррак, в глубине которого находится священный бассейн. Из этого бассейна тролли призывают огромное чудовище, Газ\'риллу! Злобная энергия пронизывает это чудовище насквозь, до самых кончиков его чешуи. И именно эту энергию я хочу использовать в своей машине!$B$BПринеси мне наэлектризованную чешую Газ\'риллы.$B$BНо только помни, что тролли держат способ призывания этого монстра в тайне, и просто так они с ней не расстанутся.','Принесите искрящую чешую Газ\'риллы Виззлу Медноштифу на Мерцающую равнину.','Вы принесли чешую? Мне не терпится извлечь из нее максимум пользы!','Вернитесь к Виззлу Медноштифу в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Газ\'рилла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В пустыне Танарис есть город троллей – Зул\'Фаррак, в глубине которого находится священный бассейн. Из этого бассейна тролли призывают огромное чудовище, Газ\'риллу! Злобная энергия пронизывает это чудовище насквозь, до самых кончиков его чешуи. И именно эту энергию я хочу использовать в своей машине!$B$BПринеси мне наэлектризованную чешую Газ\'риллы.$B$BНо только помни, что тролли держат способ призывания этого монстра в тайне, и просто так они с ней не расстанутся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите искрящую чешую Газ\'риллы Виззлу Медноштифу на Мерцающую равнину.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы принесли чешую? Мне не терпится извлечь из нее максимум пользы!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виззлу Медноштифу в поселок Виражи на Миражах, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2771,'Голова на плечах','Похоже, таков был замысел учителя. Меня он научил делать одни предметы, а тебя другие.$b$bУчитель мудр, $n! Мы обучим друг друга!$b$bНаучи меня делать мифриловые капюшоны и изысканные мифриловые наплечники, а я покажу тебе, как куется изысканный мифриловый шлем.','Принесите два мифриловых капюшона и один изысканный мифриловый наплечник Трентону Молоту Света.','Вернитесь к Трентону Молоту Света в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голова на плечах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, таков был замысел учителя. Меня он научил делать одни предметы, а тебя другие.$b$bУчитель мудр, $n! Мы обучим друг друга!$b$bНаучи меня делать мифриловые капюшоны и изысканные мифриловые наплечники, а я покажу тебе, как куется изысканный мифриловый шлем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите два мифриловых капюшона и один изысканный мифриловый наплечник Трентону Молоту Света.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трентону Молоту Света в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2772,'Мир у твоих ног','На прошлогодних соревнованиях по кузнечному делу все зрители видели, как трусливый пес из Торговой Компании подставил мне подножку. Им и невдомек, как я умудрился выиграть соревнования: правильно, благодаря изысканным мифриловым сапогам!$b$bНа соревнованиях этого года мне понадобятся изысканные мифриловые штаны, потому что в конкурсе участвует крошшер Торговой Компании! Научи меня делать штаны, а я научу тебя делать сапоги!','Принесите две пары тяжелых мифриловых сапог и одни изысканные мифриловые штаны Трентону Молоту Света.','Вернитесь к Трентону Молоту Света в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мир у твоих ног',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На прошлогодних соревнованиях по кузнечному делу все зрители видели, как трусливый пес из Торговой Компании подставил мне подножку. Им и невдомек, как я умудрился выиграть соревнования: правильно, благодаря изысканным мифриловым сапогам!$b$bНа соревнованиях этого года мне понадобятся изысканные мифриловые штаны, потому что в конкурсе участвует крошшер Торговой Компании! Научи меня делать штаны, а я научу тебя делать сапоги!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите две пары тяжелых мифриловых сапог и одни изысканные мифриловые штаны Трентону Молоту Света.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трентону Молоту Света в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2773,'Мифриловый парень','В этих краях меня зовут Мифриловым Парнем. Я продаю изысканный мифрил искателям приключений со всего света.$b$b*Трентон переходит на шепот.*$b$bИм и невдомек, что я не умею делать изысканные мифриловые перчатки. Ш-ш-ш! Пусть это останется между нами.$b$bНаучи меня делать такие перчатки, а я взамен покажу тебе последнее, чему обучил меня Гальван: изысканную мифриловую кирасу.','Принесите две тяжелых мифриловых кирасы и одни изысканные мифриловые перчатки Трентону Молоту Света.','Вернитесь к Трентону Молоту Света в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мифриловый парень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этих краях меня зовут Мифриловым Парнем. Я продаю изысканный мифрил искателям приключений со всего света.$b$b*Трентон переходит на шепот.*$b$bИм и невдомек, что я не умею делать изысканные мифриловые перчатки. Ш-ш-ш! Пусть это останется между нами.$b$bНаучи меня делать такие перчатки, а я взамен покажу тебе последнее, чему обучил меня Гальван: изысканную мифриловую кирасу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите две тяжелых мифриловых кирасы и одни изысканные мифриловые перчатки Трентону Молоту Света.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трентону Молоту Света в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2781,'РАЗЫСКИВАЕТСЯ: Калиф Жало Скорпида','РАЗЫСКИВАЕТСЯ: Калиф Жало Скорпида!$b$bВодная компания Прибамбасска предлагает награду за голову Калифа Жало Скорпида, главы Скитальцев Пустыни. Он обвиняется в:$B$B1. Убийстве сотрудников Водной компании Прибамбасска!$B2. Похищении ресурсов Водной компании Прибамбасска!$B3. Захвате собственности Водной компании Прибамбасска!$B$BПринесите доказательство гибели Калифа Жало Скорпида главному инженеру Чепухастеру и получите награду!','Принесите голову Калифа Жало Скорпида главному инженеру Чепухастеру в Прибамбасск.','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РАЗЫСКИВАЕТСЯ: Калиф Жало Скорпида',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','РАЗЫСКИВАЕТСЯ: Калиф Жало Скорпида!$b$bВодная компания Прибамбасска предлагает награду за голову Калифа Жало Скорпида, главы Скитальцев Пустыни. Он обвиняется в:$B$B1. Убийстве сотрудников Водной компании Прибамбасска!$B2. Похищении ресурсов Водной компании Прибамбасска!$B3. Захвате собственности Водной компании Прибамбасска!$B$BПринесите доказательство гибели Калифа Жало Скорпида главному инженеру Чепухастеру и получите награду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Калифа Жало Скорпида главному инженеру Чепухастеру в Прибамбасск.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному инженеру Чепухастеру в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2782,'Секрет Рин\'джи','Табличка покрыта письменами троллей из племени Сухокожих. Да, секрет Рин\'джи и впрямь оказался очень загадочным.$B$BВозможно, эта табличка представляет собой немалую ценность, хотя может быть и с точностью до наоборот. Тролль из племени Сухокожих в беде мог пообещать что угодно, лишь бы его спасли...','Отнесите табличку Оран Змеиные Кольца в Квартал Магов Подгорода. Оран – известная ученая, изучающая троллей из племени Сухокожих, и она наверняка сумеет прочесть надписи на табличке.','Хм, какая необычная табличка... Где вы ее взяли, $N?','Хм, и что же это?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секрет Рин\'джи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Табличка покрыта письменами троллей из племени Сухокожих. Да, секрет Рин\'джи и впрямь оказался очень загадочным.$B$BВозможно, эта табличка представляет собой немалую ценность, хотя может быть и с точностью до наоборот. Тролль из племени Сухокожих в беде мог пообещать что угодно, лишь бы его спасли...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите табличку Оран Змеиные Кольца в Квартал Магов Подгорода. Оран – известная ученая, изучающая троллей из племени Сухокожих, и она наверняка сумеет прочесть надписи на табличке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм, какая необычная табличка... Где вы ее взяли, $N?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хм, и что же это?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2783,'Незначительные разногласия','Мы сражаемся не с тем врагом, $n.$B$BИстинная сила этих земель продолжает наращивать свою мощь и численность, пока мы ссоримся с орками из-за клочка выжженной земли. $B$BНеужели мы продолжим воевать в этих землях против Орды лишь для того, чтобы в один ужасный день пасть от руки Пылающего Легиона? Тогда все наши усилия будут тщетны.$B$BНадо отбросить прочь мелкие разногласия, $n, и поговорить с павшим героем Орды. Он знает правду о Выжженных землях.','Поговорите с павшим героем Орды на границе Выжженных земель и болот.','Альянс желает помочь?$B$BЯ не думал, что этот день когда-либо наступит вновь. День, когда Альянс будет сражаться плечом к плечу с Ордой против общего врага.$B$BДа будет так... мы объединимся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Незначительные разногласия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы сражаемся не с тем врагом, $n.$B$BИстинная сила этих земель продолжает наращивать свою мощь и численность, пока мы ссоримся с орками из-за клочка выжженной земли. $B$BНеужели мы продолжим воевать в этих землях против Орды лишь для того, чтобы в один ужасный день пасть от руки Пылающего Легиона? Тогда все наши усилия будут тщетны.$B$BНадо отбросить прочь мелкие разногласия, $n, и поговорить с павшим героем Орды. Он знает правду о Выжженных землях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с павшим героем Орды на границе Выжженных земель и болот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Альянс желает помочь?$B$BЯ не думал, что этот день когда-либо наступит вновь. День, когда Альянс будет сражаться плечом к плечу с Ордой против общего врага.$B$BДа будет так... мы объединимся.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2784,'Попавший в немилость','Выслушай мою историю, |3-6($r).','Послушайте, как павший герой Орды рассказывает свою историю.','Будучи духом, я бессилен что-либо сделать. Помоги мне, $N. Дай мне возможность снова обрести свою честь.','Послушай, что я скажу.','Печальная история','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Попавший в немилость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Выслушай мою историю, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Послушайте, как павший герой Орды рассказывает свою историю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будучи духом, я бессилен что-либо сделать. Помоги мне, $N. Дай мне возможность снова обрести свою честь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Послушай, что я скажу.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Печальная история',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2801,'Печальная история','Прежде чем мы продолжим, тебе следует услышать мою историю.','Послушайте, как павший герой Орды рассказывает свою историю.','Ожидаю приказов.','Печальная история','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печальная история',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем мы продолжим, тебе следует услышать мою историю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Послушайте, как павший герой Орды рассказывает свою историю.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ожидаю приказов.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Печальная история',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2821,'Знак качества','У меня принцип простой: если что делаешь, делай как можно лучше – и никаких компромиссов! А тот, кто станет говорить, будто качество не имеет значения, того гляди, продаст тебе недвижимость в Дун Мороге с видом на море!$b$bИ вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их в Долине Свирепого Утеса. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?','Принесите 10 толстых шкур йети Пратту Макгруббену в Крепость Оперенной Луны.','Ну что, видишь, каковы эти шкуры? Надо тебе сказать, что после специальной обработки они делаются прочнее железа! Немногие про это знают, а вот я, с помощью своих особых дубильных составов, смогу делать из них вещи несравненного качества! Ну да, и все это – благодаря тебе.$B$BПожалуйста, $N, выбирай себе любое из моих готовых изделий.','Принеси десять толстых шкур йети – и получишь любое из моих изделий! А мои вещи на редкость добротные, это все знают!$B$BЕсли не знаешь, где отыскать йети, я тебе подскажу. Ищи у Забытого берега, близ Долины Свирепого Утеса.','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак качества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня принцип простой: если что делаешь, делай как можно лучше – и никаких компромиссов! А тот, кто станет говорить, будто качество не имеет значения, того гляди, продаст тебе недвижимость в Дун Мороге с видом на море!$b$bИ вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их в Долине Свирепого Утеса. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 толстых шкур йети Пратту Макгруббену в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что, видишь, каковы эти шкуры? Надо тебе сказать, что после специальной обработки они делаются прочнее железа! Немногие про это знают, а вот я, с помощью своих особых дубильных составов, смогу делать из них вещи несравненного качества! Ну да, и все это – благодаря тебе.$B$BПожалуйста, $N, выбирай себе любое из моих готовых изделий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принеси десять толстых шкур йети – и получишь любое из моих изделий! А мои вещи на редкость добротные, это все знают!$B$BЕсли не знаешь, где отыскать йети, я тебе подскажу. Ищи у Забытого берега, близ Долины Свирепого Утеса.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2822,'Знак качества','Я горжусь своим мастерством. Мои вещи сразу видно! А тот, кто станет говорить, будто качество не имеет значения, пожалуй, захочет убедить тебя и в том, будто земля не хранит тайн!$b$bИ вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их к западу отсюда, в Долине Свирепого Утеса. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?','Принесите 10 толстых шкур йети Джангору Быстрому Страннику в Лагерь Мохаче.','О, отлично! Надо тебе сказать, что эти шкуры после специальной обработки делаются прочнее железа! Правда, подобрать состав для дубления не так-то просто, но все равно, я уверен, что мои вещи, изготовленные из них, будут еще лучше прежнего.$B$BЧто до тебя, $N, – ты воистину $Gбесценный:бесценная; $Gпомощник:помощница;! Пожалуйста, выбирай себе любое из моих готовых изделий.','Ну что, удалось тебе добыть десять толстых шкур йети? Мои кожаные изделия не знают себе равных, и ты получишь в уплату одно из них, только принеси шкуры.$B$BЕсли не знаешь, где отыскать йети, я тебе подскажу. Ищи к западу отсюда, у Забытого берега, близ Долины Свирепого Утеса.','Вернитесь к Джангору Быстрому Страннику в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак качества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я горжусь своим мастерством. Мои вещи сразу видно! А тот, кто станет говорить, будто качество не имеет значения, пожалуй, захочет убедить тебя и в том, будто земля не хранит тайн!$b$bИ вот недавно в поисках качественных материалов я обнаружил толстые шкуры йети. Йети – это существа, которые водятся в Фераласе. Особенно много их к западу отсюда, в Долине Свирепого Утеса. За каждые десять шкур ты получишь одно из моих кожаных изделий. Ну что, по рукам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 толстых шкур йети Джангору Быстрому Страннику в Лагерь Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, отлично! Надо тебе сказать, что эти шкуры после специальной обработки делаются прочнее железа! Правда, подобрать состав для дубления не так-то просто, но все равно, я уверен, что мои вещи, изготовленные из них, будут еще лучше прежнего.$B$BЧто до тебя, $N, – ты воистину $Gбесценный:бесценная; $Gпомощник:помощница;! Пожалуйста, выбирай себе любое из моих готовых изделий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе добыть десять толстых шкур йети? Мои кожаные изделия не знают себе равных, и ты получишь в уплату одно из них, только принеси шкуры.$B$BЕсли не знаешь, где отыскать йети, я тебе подскажу. Ищи к западу отсюда, у Забытого берега, близ Долины Свирепого Утеса.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джангору Быстрому Страннику в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2841,'Техновойны','О-о, гномьи технологии! Еще пару лет назад они использовались в основном в анекдотах. Да уж, времена изменились! Теперь они выстроили такую машину, которая лучше, чем все наши крошшеры вместе взятые! Мне нужны ее чертежи, $n!$b$bУвы, эти бумаги хранятся в сейфе Анжинера Термоштепселя. А что хуже всего – код от сейфа известен только самому Термоштепселю!$b$bДелай что хочешь, $n, но добудь этот код, открой сейф и достань оттуда эти чертежи!','Добудьте в Гномрегане чертежи боевой машины и код от сейфа Термоштепселя в Гномрегане и принесите их Ноггу в Оргриммар.','Не вижу чертежей! Они спрятаны у тебя под одеждой или ты вернулся с пустыми руками и только понапрасну меня раздражаешь?','Вернитесь к Ноггу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Техновойны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О-о, гномьи технологии! Еще пару лет назад они использовались в основном в анекдотах. Да уж, времена изменились! Теперь они выстроили такую машину, которая лучше, чем все наши крошшеры вместе взятые! Мне нужны ее чертежи, $n!$b$bУвы, эти бумаги хранятся в сейфе Анжинера Термоштепселя. А что хуже всего – код от сейфа известен только самому Термоштепселю!$b$bДелай что хочешь, $n, но добудь этот код, открой сейф и достань оттуда эти чертежи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте в Гномрегане чертежи боевой машины и код от сейфа Термоштепселя в Гномрегане и принесите их Ноггу в Оргриммар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не вижу чертежей! Они спрятаны у тебя под одеждой или ты вернулся с пустыми руками и только понапрасну меня раздражаешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ноггу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2842,'Главный инженер Скути','Как только Керноби сообщил нам о новой гномской машине, мы со Скути принялись строить "Транстелепорт-6000" – лучший способ добраться до Гномрегана.$b$bОн уже готов, $n. Если хочешь его испытать, ступай в Пиратскую Бухту и поговори со Скути у Гнезда Ветрокрылов. Из Кабестана туда можно добраться на лодке.$b$bНет, разумеется, ты можешь попробовать добраться до Гномрегана через горы Дун Морог, кишащие дворфами!','Поговорите со Скути в Пиратской Бухте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главный инженер Скути',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только Керноби сообщил нам о новой гномской машине, мы со Скути принялись строить "Транстелепорт-6000" – лучший способ добраться до Гномрегана.$b$bОн уже готов, $n. Если хочешь его испытать, ступай в Пиратскую Бухту и поговори со Скути у Гнезда Ветрокрылов. Из Кабестана туда можно добраться на лодке.$b$bНет, разумеется, ты можешь попробовать добраться до Гномрегана через горы Дун Морог, кишащие дворфами!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со Скути в Пиратской Бухте.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2843,'Поехалиии!','Пока импульсный повторитель у тебя с собой, стоит только ступить на площадку, и перенесешься в Гномреган.$B$BМожет быть, ощущения будут необычные, но ни одно из них не останется навсегда... Теперь.$B$BЧуть не забыл самое главное – как вернуться назад. Когда ты решишь уносить ноги, поднимись на площадку транстелепорта в Гномрегане!$B$BА теперь я настрою импульсный повторитель на твой рост и вес.','Дождитесь, пока Скути настроит гоблинский импульсный повторитель.','Готово! Когда соберешься с духом, просто ступи на площадку.','Готово!','Гоблинский импульсный повторитель','Вернитесь к Скути в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поехалиии!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока импульсный повторитель у тебя с собой, стоит только ступить на площадку, и перенесешься в Гномреган.$B$BМожет быть, ощущения будут необычные, но ни одно из них не останется навсегда... Теперь.$B$BЧуть не забыл самое главное – как вернуться назад. Когда ты решишь уносить ноги, поднимись на площадку транстелепорта в Гномрегане!$B$BА теперь я настрою импульсный повторитель на твой рост и вес.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока Скути настроит гоблинский импульсный повторитель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Готово! Когда соберешься с духом, просто ступи на площадку.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Готово!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Гоблинский импульсный повторитель',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скути в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2844,'Великан-опекун','Нет от меня никакого толку, $n! Я должен был стеречь мою маленькую подружку, Шаю, а она взяла и убежала! Я даже не знаю, как это вышло: в последний раз, как я ее видел, мы шли через развалины к северу отсюда.$b$bВсе было хорошо, а потом я поворачиваюсь, а ее нет!$b$bИ теперь я даже и не знаю, чего мне делать-то. Что мне делать, $n? Я так переживаю!$b$bСлушай, а может, ты сходишь ее поищешь? У тебя-то ноги куда резвее моих!','Найдите потерявшуюся ночную эльфийку.','Ой, как хорошо, что ты меня $Gнашел:нашла;! По правде говоря, я немножко заблудилась... Но тут очень красиво, правда?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великан-опекун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет от меня никакого толку, $n! Я должен был стеречь мою маленькую подружку, Шаю, а она взяла и убежала! Я даже не знаю, как это вышло: в последний раз, как я ее видел, мы шли через развалины к северу отсюда.$b$bВсе было хорошо, а потом я поворачиваюсь, а ее нет!$b$bИ теперь я даже и не знаю, чего мне делать-то. Что мне делать, $n? Я так переживаю!$b$bСлушай, а может, ты сходишь ее поищешь? У тебя-то ноги куда резвее моих!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите потерявшуюся ночную эльфийку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, как хорошо, что ты меня $Gнашел:нашла;! По правде говоря, я немножко заблудилась... Но тут очень красиво, правда?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2845,'Шая-бродяжница','Не поможешь ли ты мне отыскать моего друга, Камнедробителя? Он должен был следить за мной... Но со мной иногда случается, что я ухожу, куда глаза глядят. Вокруг столько интересного, я увлекаюсь, забываю обо всем на свете, и...$b$bНо есть одна вещь, которая обязательно привлекает мое внимание.$b$bВ этом сундучке хранится колокольчик. Он мне очень дорог. Мне ужасно нравится его звон. Так что, если я вдруг куда-нибудь уйду, позвони в колокольчик, и я тотчас прибегу обратно!','Достаньте из сундучка колокольчик Шаи.$b$bПроводите Шаю Листогон в лагерь Камнедробителя.','Шо? Так говоришь, этот колокольчик помогает найти Шай, когда она убежала? Вот это да!$B$BНу, $N, раз я стольким тебе обязан, на, держи!','Ох, я так из-за тебя переволновался! Спасибо большое, $N, что $Gпривел:привела; Шай домой!','Проводить Шаю Листогон в лагерь Камнедробителя.','Вернитесь к Камнедробителю к Двум Колоссам, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шая-бродяжница',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не поможешь ли ты мне отыскать моего друга, Камнедробителя? Он должен был следить за мной... Но со мной иногда случается, что я ухожу, куда глаза глядят. Вокруг столько интересного, я увлекаюсь, забываю обо всем на свете, и...$b$bНо есть одна вещь, которая обязательно привлекает мое внимание.$b$bВ этом сундучке хранится колокольчик. Он мне очень дорог. Мне ужасно нравится его звон. Так что, если я вдруг куда-нибудь уйду, позвони в колокольчик, и я тотчас прибегу обратно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Достаньте из сундучка колокольчик Шаи.$b$bПроводите Шаю Листогон в лагерь Камнедробителя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Шо? Так говоришь, этот колокольчик помогает найти Шай, когда она убежала? Вот это да!$B$BНу, $N, раз я стольким тебе обязан, на, держи!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ох, я так из-за тебя переволновался! Спасибо большое, $N, что $Gпривел:привела; Шай домой!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводить Шаю Листогон в лагерь Камнедробителя.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Камнедробителю к Двум Колоссам, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2846,'Тиара Глубин','Давным-давно у меня была прекрасная драгоценность – Тиара Глубин. Это была не просто красивая безделушка, она была наделена великой силой, предназначенной для тех, кто умел с ней обращаться.$B$BКогда слух о моей тиаре достиг ушей гидроманта Велраты, она решила заполучить ее и послала своих подручных выкрасть ее у меня!$B$BЯ хочу вернуть то, что принадлежит мне. Отправляйся в Зул\'Фаррак, город троллей в пустыне Танарис, найди там Велрату и забери у нее мою тиару. Возвращайся ко мне и заслужишь мою вечную благодарность.','Принесите Тиару Глубин Табете в Пылевых топях.','Вернитесь к Табете на Трясину, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тиара Глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно у меня была прекрасная драгоценность – Тиара Глубин. Это была не просто красивая безделушка, она была наделена великой силой, предназначенной для тех, кто умел с ней обращаться.$B$BКогда слух о моей тиаре достиг ушей гидроманта Велраты, она решила заполучить ее и послала своих подручных выкрасть ее у меня!$B$BЯ хочу вернуть то, что принадлежит мне. Отправляйся в Зул\'Фаррак, город троллей в пустыне Танарис, найди там Велрату и забери у нее мою тиару. Возвращайся ко мне и заслужишь мою вечную благодарность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Тиару Глубин Табете в Пылевых топях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на Трясину, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2847,'Дикарские кожаные доспехи','$n, ты уже $gопытный кожевник:опытная кожевница;. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это дикарские кожаные доспехи. В них используются загадочная и непостоянная сила дикой лозы, который можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах.$b$bЯ научу тебя делать эти доспехи, но для этого тебе придется потрудиться. Для начала мне нужно просто десять кусков плотной кожи. Принеси ее, потом обсудим дальнейшее.','Принесите 10 кусков плотной кожи Пратту Макгруббену в Крепость Оперенной Луны.','Ну, $N, я рад, что ты уже с нами, так сказать, на борту. Ты получишь начальные знания в создании дикарских кожаных доспехов и, как я говорил, практически даром. За работу же!','Как я уже сказал, ты будешь работать на меня, пока узнаешь о дикой кожаной броне. Поскольку дикие лозы одновременно и могущественны, и хаотичны, они дают случайное, но сильное преимущество для и без того прочной брони, которую вы будете делать. Однако мне было нелегко получить это знание.$B$BПервоначальная стоимость начала этого процесса - десять кусков толстой кожи.$B$BКак только это будет сделано, мы приступим к работе, которую вам нужно проделать, чтобы получить шаблоны.','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарские кожаные доспехи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты уже $gопытный кожевник:опытная кожевница;. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это дикарские кожаные доспехи. В них используются загадочная и непостоянная сила дикой лозы, который можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах.$b$bЯ научу тебя делать эти доспехи, но для этого тебе придется потрудиться. Для начала мне нужно просто десять кусков плотной кожи. Принеси ее, потом обсудим дальнейшее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 кусков плотной кожи Пратту Макгруббену в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, $N, я рад, что ты уже с нами, так сказать, на борту. Ты получишь начальные знания в создании дикарских кожаных доспехов и, как я говорил, практически даром. За работу же!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как я уже сказал, ты будешь работать на меня, пока узнаешь о дикой кожаной броне. Поскольку дикие лозы одновременно и могущественны, и хаотичны, они дают случайное, но сильное преимущество для и без того прочной брони, которую вы будете делать. Однако мне было нелегко получить это знание.$B$BПервоначальная стоимость начала этого процесса - десять кусков толстой кожи.$B$BКак только это будет сделано, мы приступим к работе, которую вам нужно проделать, чтобы получить шаблоны.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2848,'Дикарские кожаные наплечники','Дикарские кожаные наплечники обеспечивают превосходную защиту как плеч, так и верхней части руки. Как и все дикарские кожаные доспехи, они прошиты дикой лозой, что придает им мощные, но непостоянные магические свойства.$b$bДля изготовления изделия по этой выкройке мне потребуется шесть комплектов накладок из плотной кожи и дикий виноград. Для тебя это не слишком сложное задание...','Принесите 6 комплектов накладок из плотной кожи и дикую лозу Макгруббену в Крепость Оперенной Луны.','Да, $N, это хорошие, надежные наборы для усиления брони. Если я чего требую не только от себя, но и от своих подмастерьев, так это высокого качества!$B$BТы неплохо $Gпотрудился:потрудилась;, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне.','Ну что, $Gпринес:принесла; ли ты шесть наборов для усиления брони их толстой кожи и дикий виноград, как я просил?$B$BИзготовление брони из толстой кожи – дело непростое и трудоемкое, но это помогает набить руку перед тем, как взяться за более сложные вещи, например, дикарские кожаные доспехи.$B$BТак что если я заставляю тебя всем этим заниматься, то не просто так...','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарские кожаные наплечники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дикарские кожаные наплечники обеспечивают превосходную защиту как плеч, так и верхней части руки. Как и все дикарские кожаные доспехи, они прошиты дикой лозой, что придает им мощные, но непостоянные магические свойства.$b$bДля изготовления изделия по этой выкройке мне потребуется шесть комплектов накладок из плотной кожи и дикий виноград. Для тебя это не слишком сложное задание...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 комплектов накладок из плотной кожи и дикую лозу Макгруббену в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $N, это хорошие, надежные наборы для усиления брони. Если я чего требую не только от себя, но и от своих подмастерьев, так это высокого качества!$B$BТы неплохо $Gпотрудился:потрудилась;, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $Gпринес:принесла; ли ты шесть наборов для усиления брони их толстой кожи и дикий виноград, как я просил?$B$BИзготовление брони из толстой кожи – дело непростое и трудоемкое, но это помогает набить руку перед тем, как взяться за более сложные вещи, например, дикарские кожаные доспехи.$B$BТак что если я заставляю тебя всем этим заниматься, то не просто так...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2849,'Дикарский кожаный жилет','Дикарский кожаный жилет – основа любых дикарских кожаных доспехов. Основа жилета переплетена диким виноградом, что дает максимальную защиту торса и позволяет использовать мощную магию растения.$b$bДля изготовления изделия по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикая лоза. Изготовить это непросто, но, думаю, ты справишься.','Принесите 2 черепашьих чешуйчатых кирасы, 2 пары черепашьих чешуйчатых перчаток и дикую лозу Пратту Макгруббену в Крепость Оперенной Луны.','Да, $N, неплохие вещицы! За одно умение и старание, вложенное в них, можно получить несколько лишних серебряных монет.$B$BНу что, мой приказ выполнен, вот и твоя награда. Теперь ты умеешь изготовлять дикарские кожаные жилеты!','Ну что, где те черепашьи чешуйчатые кирасы и перчатки, что я велел принести? И не забудь про дикий виноград!$B$BЕще работая с простейшими выкройками, мы понимаем, что сложное и простое строится по одним и тем же принципам. Таким образом, изготовление черепашьих чешуйчатых кирас подготавливает тебя к созданию дикарского кожаного жилета.$B$BЧто до перчаток... ну, перчатки пригодятся мне самому! Не забывай, ты работаешь на меня!','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарский кожаный жилет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дикарский кожаный жилет – основа любых дикарских кожаных доспехов. Основа жилета переплетена диким виноградом, что дает максимальную защиту торса и позволяет использовать мощную магию растения.$b$bДля изготовления изделия по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикая лоза. Изготовить это непросто, но, думаю, ты справишься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 черепашьих чешуйчатых кирасы, 2 пары черепашьих чешуйчатых перчаток и дикую лозу Пратту Макгруббену в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $N, неплохие вещицы! За одно умение и старание, вложенное в них, можно получить несколько лишних серебряных монет.$B$BНу что, мой приказ выполнен, вот и твоя награда. Теперь ты умеешь изготовлять дикарские кожаные жилеты!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где те черепашьи чешуйчатые кирасы и перчатки, что я велел принести? И не забудь про дикий виноград!$B$BЕще работая с простейшими выкройками, мы понимаем, что сложное и простое строится по одним и тем же принципам. Таким образом, изготовление черепашьих чешуйчатых кирас подготавливает тебя к созданию дикарского кожаного жилета.$B$BЧто до перчаток... ну, перчатки пригодятся мне самому! Не забывай, ты работаешь на меня!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2850,'Дикарский кожаный шлем','Дикарский кожаный шлем обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы. Как и во всех дикарских кожаных доспехах, в основу шлема вплетен дикий виноград, наделяющий его мощными, но непостоянными магическими свойствами. Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится!$b$bНо для изготовления изделия по этой выкройке мне понадобятся 2 ночных мундира, 2 ночных головных повязки и дикая лоза. Принеси это все, и выкройка твоя!','Принесите 2 ночных мундира, 2 ночных головных повязки и дикую лозу Пратту Макгруббену в Крепость Оперенной Луны.','Да, это Ночное снаряжение – именно то, что я просил тебя принести, $N. Впрочем, от кожевника твоего уровня я другого и не ждал.$B$BТы $Gдостоин:достойна; уметь изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь ее с пользой.','Мне нужны туники и повязки на голову, а еще мне нужен этот кусок дикой лозы, прежде чем я поделюсь с тобой знаниями о диких кожаных шлемах.$B$BГоловные уборы очень популярны среди искателей приключений, будь то обезоруживающая простая повязка на голову или полностью закрывающий шлем. Основы создания ценных головных уборов остаются неизменными, независимо от внешнего вида снаряжения.','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарский кожаный шлем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дикарский кожаный шлем обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы. Как и во всех дикарских кожаных доспехах, в основу шлема вплетен дикий виноград, наделяющий его мощными, но непостоянными магическими свойствами. Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится!$b$bНо для изготовления изделия по этой выкройке мне понадобятся 2 ночных мундира, 2 ночных головных повязки и дикая лоза. Принеси это все, и выкройка твоя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 ночных мундира, 2 ночных головных повязки и дикую лозу Пратту Макгруббену в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это Ночное снаряжение – именно то, что я просил тебя принести, $N. Впрочем, от кожевника твоего уровня я другого и не ждал.$B$BТы $Gдостоин:достойна; уметь изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь ее с пользой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужны туники и повязки на голову, а еще мне нужен этот кусок дикой лозы, прежде чем я поделюсь с тобой знаниями о диких кожаных шлемах.$B$BГоловные уборы очень популярны среди искателей приключений, будь то обезоруживающая простая повязка на голову или полностью закрывающий шлем. Основы создания ценных головных уборов остаются неизменными, независимо от внешнего вида снаряжения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2851,'Дикарские кожаные сапоги','Тебе известно уже немало, $n. Но многое еще остается постичь. Теперь ты узнаешь о дикарских кожаных сапогах – ведь без обуви не обходится ни один доспех.$b$bНоге в них удобно и приятно, и дальний путь в них не так тяжел. Мягкая же подошва позволяет при необходимости ступать беззвучно.$b$bДля их изготовления по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог. И два экземпляра дикого винограда – запомни, два, а не один! Добудешь все это – дай мне знать.','Принесите 2 пары ночных штанов, 2 пары ночных сапог и 2 экземпляра дикой лозы Пратту Макгруббену в Крепость Оперенной Луны.','Итак, ты $Gвыполнил:выполнила; комплексный заказ и как всегда $Gсделал:сделала; это профессионально. Так что получи эту выкройку и мою благодарность!','Прежде чем получить выкройку, нужно оформить заказ на штаны, сапоги и дикие лозы, $N. Вы закончили?$B$BС самых первых пар обуви мы учимся делать, мы начинаем понимать, что качественные ботинки должны сочетать комфорт и функциональность на грани бритвы. С обоими способами мы можем создавать предметы, которые позволяют владельцу игнорировать усталость, которая может нанести вред тем, кто носит товары более низкого качества.','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарские кожаные сапоги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе известно уже немало, $n. Но многое еще остается постичь. Теперь ты узнаешь о дикарских кожаных сапогах – ведь без обуви не обходится ни один доспех.$b$bНоге в них удобно и приятно, и дальний путь в них не так тяжел. Мягкая же подошва позволяет при необходимости ступать беззвучно.$b$bДля их изготовления по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог. И два экземпляра дикого винограда – запомни, два, а не один! Добудешь все это – дай мне знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 пары ночных штанов, 2 пары ночных сапог и 2 экземпляра дикой лозы Пратту Макгруббену в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, ты $Gвыполнил:выполнила; комплексный заказ и как всегда $Gсделал:сделала; это профессионально. Так что получи эту выкройку и мою благодарность!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прежде чем получить выкройку, нужно оформить заказ на штаны, сапоги и дикие лозы, $N. Вы закончили?$B$BС самых первых пар обуви мы учимся делать, мы начинаем понимать, что качественные ботинки должны сочетать комфорт и функциональность на грани бритвы. С обоими способами мы можем создавать предметы, которые позволяют владельцу игнорировать усталость, которая может нанести вред тем, кто носит товары более низкого качества.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2852,'Дикарские кожаные поножи','Ну, $n, теперь, когда с простыми предметами покончено, мы можем перейти к более сложным вещам. Дикарские кожаные поножи – одна из наиболее прочных и надежных разновидностей кожаного доспеха. Они отлично защищают и живот, и ноги, и прочие важные части тела. А поскольку в них вшита еще и дикая лоза, дающая дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи.$b$bДля изготовления изделия по этой выкройке мне понадобятся два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей, и два экземпляра дикого винограда.','Принесите два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей и два экземпляра дикой лозы Пратту Макгруббену в Крепость Оперенной Луны.','Хм. Ты опять $Gвыполнил:выполнила; приказ. Возможно, в один прекрасный день я приду к тебе за знаниями, а, $N?$B$BВот выкройка поножей, вместе с моими благодарностями.','У вас есть наручи и шлемы из черепашьей чешуи? Не забудь про две дикие лозы, которые мне нужны!$B$BК настоящему времени вы начинаете осознавать потенциальную силу, заключенную в дикой кожаной броне. Доспехи, не имеющие границ в применении, почти бесценны для кожевников. Ограничения заключаются только в количестве ресурсов для изготовления изделий, а не в качестве готовой продукции!','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарские кожаные поножи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, $n, теперь, когда с простыми предметами покончено, мы можем перейти к более сложным вещам. Дикарские кожаные поножи – одна из наиболее прочных и надежных разновидностей кожаного доспеха. Они отлично защищают и живот, и ноги, и прочие важные части тела. А поскольку в них вшита еще и дикая лоза, дающая дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи.$b$bДля изготовления изделия по этой выкройке мне понадобятся два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей, и два экземпляра дикого винограда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей и два экземпляра дикой лозы Пратту Макгруббену в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм. Ты опять $Gвыполнил:выполнила; приказ. Возможно, в один прекрасный день я приду к тебе за знаниями, а, $N?$B$BВот выкройка поножей, вместе с моими благодарностями.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть наручи и шлемы из черепашьей чешуи? Не забудь про две дикие лозы, которые мне нужны!$B$BК настоящему времени вы начинаете осознавать потенциальную силу, заключенную в дикой кожаной броне. Доспехи, не имеющие границ в применении, почти бесценны для кожевников. Ограничения заключаются только в количестве ресурсов для изготовления изделий, а не в качестве готовой продукции!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2853,'Мастер школы Дикаря','Что ж, $n, ты – образец прилежания. Остался только один предмет из дикарских кожаных доспехов, который ты не умеешь изготовлять. Я не стану заставлять тебя трудиться, чтобы ее получить: ты и так сполна $gрасплатился:расплатилась; за все. Однако же сам я тебе его дать не могу. Ты получишь награду от моего наставника, того, кто посвятил в тайны нашего ремесла меня самого. $b$bОтнеси эту записку Телонису. Он обучает кожевников в Дарнасе. Покажи ему записку, и пусть он приветствует тебя как $gравного:равную;, подобно мне самому.','Отдайте письмо Пратта Телонису, главному кожевнику Дарнаса.','А, ты от Пратта! Он, конечно, человек, но временами напоминает мне нас, ночных эльфов. Он действительно гениальный кожевенник! И если он тебя так расхваливает, это говорит в твою пользу.$B$BНасколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов? Позволь же, я завершу твое обучение, дав тебе вот эту выкройку. Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!','Приветствую, $R... Судя по твоему внешнему виду, ты – кожевник, как и я. Ты $Gпришел:пришла; чтобы учиться, или у тебя ко мне другое дело?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер школы Дикаря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, $n, ты – образец прилежания. Остался только один предмет из дикарских кожаных доспехов, который ты не умеешь изготовлять. Я не стану заставлять тебя трудиться, чтобы ее получить: ты и так сполна $gрасплатился:расплатилась; за все. Однако же сам я тебе его дать не могу. Ты получишь награду от моего наставника, того, кто посвятил в тайны нашего ремесла меня самого. $b$bОтнеси эту записку Телонису. Он обучает кожевников в Дарнасе. Покажи ему записку, и пусть он приветствует тебя как $gравного:равную;, подобно мне самому.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте письмо Пратта Телонису, главному кожевнику Дарнаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, ты от Пратта! Он, конечно, человек, но временами напоминает мне нас, ночных эльфов. Он действительно гениальный кожевенник! И если он тебя так расхваливает, это говорит в твою пользу.$B$BНасколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов? Позволь же, я завершу твое обучение, дав тебе вот эту выкройку. Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $R... Судя по твоему внешнему виду, ты – кожевник, как и я. Ты $Gпришел:пришла; чтобы учиться, или у тебя ко мне другое дело?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2854,'Дикарские кожаные доспехи','$n, ты уже $gопытный кожевник:опытная кожевница;. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это дикарские кожаные доспехи. В них используется загадочная и непостоянная сила дикой лозы, который можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах.$b$bЯ научу тебя делать эти доспехи, но для этого тебе придется потрудиться. Для начала мне нужно просто десять кусков плотной кожи. Принеси ее, потом обсудим дальнейшее.','Принесите 10 кусков плотной кожи Джангору Быстрому Страннику в Лагерь Мохаче.','Ну что ж, $N, я рад, что ты теперь $Gмой:моя; $Gученик:ученица;. Ты $Gпоступил:поступила; разумно, избрав ремесло кожевника: когда ты научишься изготовлять дикарские кожаные доспехи, у тебя отбою не будет от тех, кто одевается в кожу.$B$BНу, за работу! С чего мы начнем?','Будем честны друг с другом, каковы шансы новичка изучить искусство создания дикарских кожаных доспехов? Никаких. Как ты $Gдолжен:должна; понимать, собрать по крохам кусочки этого древнего знания стоило мне совсем недешево. Кроме того, на эксперименты с нестойким веществом, вырабатываемом этими растениями, у меня ушло очень много времени.$B$BВ общем, я не могу позволить себе раздавать свои знания налево и направо.$B$BНамек достаточно тонкий?','Вернитесь к Джангору Быстрому Страннику в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарские кожаные доспехи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты уже $gопытный кожевник:опытная кожевница;. Я владею искусством изготовления того, что весьма пригодилось бы и тебе. Это дикарские кожаные доспехи. В них используется загадочная и непостоянная сила дикой лозы, который можно отыскать в густых зарослях или получить от некоторых существ. Другого подобного доспеха мастер твоего уровня изготовить не в силах.$b$bЯ научу тебя делать эти доспехи, но для этого тебе придется потрудиться. Для начала мне нужно просто десять кусков плотной кожи. Принеси ее, потом обсудим дальнейшее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 кусков плотной кожи Джангору Быстрому Страннику в Лагерь Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что ж, $N, я рад, что ты теперь $Gмой:моя; $Gученик:ученица;. Ты $Gпоступил:поступила; разумно, избрав ремесло кожевника: когда ты научишься изготовлять дикарские кожаные доспехи, у тебя отбою не будет от тех, кто одевается в кожу.$B$BНу, за работу! С чего мы начнем?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будем честны друг с другом, каковы шансы новичка изучить искусство создания дикарских кожаных доспехов? Никаких. Как ты $Gдолжен:должна; понимать, собрать по крохам кусочки этого древнего знания стоило мне совсем недешево. Кроме того, на эксперименты с нестойким веществом, вырабатываемом этими растениями, у меня ушло очень много времени.$B$BВ общем, я не могу позволить себе раздавать свои знания налево и направо.$B$BНамек достаточно тонкий?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джангору Быстрому Страннику в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2855,'Дикарские кожаные наплечники','Дикарские кожаные наплечники обеспечивают превосходную защиту как плеч, так и верхней части руки. Как и все дикарские кожаные доспехи, они прошиты дикиой лозой, что придает им мощные, но непостоянные магические свойства.$b$bДля изготовления изделия по этой выкройке мне потребуется шесть комплектов накладок из плотной кожи и дикий виноград. Для тебя это не слишком сложное задание...','Принесите 6 комплектов накладок из плотной кожи и дикую лозу Джангору Быстрому Страннику в Лагерь Мохаче.','Да, $N, это хорошие, надежные доспехи. Если я чего требую не только от себя, но и от своих учеников, так это высокого качества!$B$BТы неплохо $Gпотрудился:потрудилась;, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне.','Ну и где шесть накладок из плотной кожи, которые я просил?$B$BСделать заплатку, это тоже искусство. Ты $Gдолжен:должна; прикрепить ее к готовому изделию аккуратно и тщательно, чтобы не повредить его. Эта аккуратность потребуется тебе при создании дикарской кожаной брони.$B$BКаждый урок имеет цель, как видишь.','Вернитесь к Джангору Быстрому Страннику в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарские кожаные наплечники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дикарские кожаные наплечники обеспечивают превосходную защиту как плеч, так и верхней части руки. Как и все дикарские кожаные доспехи, они прошиты дикиой лозой, что придает им мощные, но непостоянные магические свойства.$b$bДля изготовления изделия по этой выкройке мне потребуется шесть комплектов накладок из плотной кожи и дикий виноград. Для тебя это не слишком сложное задание...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 комплектов накладок из плотной кожи и дикую лозу Джангору Быстрому Страннику в Лагерь Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $N, это хорошие, надежные доспехи. Если я чего требую не только от себя, но и от своих учеников, так это высокого качества!$B$BТы неплохо $Gпотрудился:потрудилась;, и заслуживаешь того, чтобы получить эту выкройку. Надеюсь, она позволит тебе добиться не меньшего уважения, чем мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну и где шесть накладок из плотной кожи, которые я просил?$B$BСделать заплатку, это тоже искусство. Ты $Gдолжен:должна; прикрепить ее к готовому изделию аккуратно и тщательно, чтобы не повредить его. Эта аккуратность потребуется тебе при создании дикарской кожаной брони.$B$BКаждый урок имеет цель, как видишь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джангору Быстрому Страннику в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2856,'Дикарский кожаный жилет','Дикарский кожаный жилет – основа любых дикарских кожаных доспехов. Основа жилета переплетена диким виноградом, что дает максимальную защиту торса и позволяет использовать мощную магию растения.$b$bДля изготовления предмета по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикая лоза. Изготовить это непросто, но, думаю, ты справишься.','Принесите 2 черепашьих чешуйчатых кирасы, 2 пары черепашьих чешуйчатых перчаток и дикую лозу Джангору Быстрому Страннику в Лагерь Мохаче.','Да, $N, неплохие вещицы! Судя по умению и старанию, с какими они изготовлены, ты всерьез относишься к своему ремеслу.$B$BНу что, мой приказ выполнен, вот и твоя награда. Теперь ты умеешь изготовлять дикарские кожаные жилеты!','Ты $Gпринес:принесла;? $GПринес:Принесла; мне кирасу из черепашьего панциря и перчатки как я и хотел? И также не забудь про дикую лозу!$B$BДаже в ранних разработках мы старались варьировать цвета и узоры вышивки, также экспериментировали с выкройкой и представляли себе каким должен выглядеть он, наш идеальный продукт. Результатом этих экспериментов и стала выкройка которую ты видишь - наш дикарский кожаный жилет.$B$BНе забывай, ты же работаешь на меня!','Вернитесь к Джангору Быстрому Страннику в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарский кожаный жилет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дикарский кожаный жилет – основа любых дикарских кожаных доспехов. Основа жилета переплетена диким виноградом, что дает максимальную защиту торса и позволяет использовать мощную магию растения.$b$bДля изготовления предмета по этой выкройке мне потребуется две черепашьих чешуйчатых кирасы, две пары черепашьих чешуйчатых перчаток и дикая лоза. Изготовить это непросто, но, думаю, ты справишься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 черепашьих чешуйчатых кирасы, 2 пары черепашьих чешуйчатых перчаток и дикую лозу Джангору Быстрому Страннику в Лагерь Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $N, неплохие вещицы! Судя по умению и старанию, с какими они изготовлены, ты всерьез относишься к своему ремеслу.$B$BНу что, мой приказ выполнен, вот и твоя награда. Теперь ты умеешь изготовлять дикарские кожаные жилеты!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла;? $GПринес:Принесла; мне кирасу из черепашьего панциря и перчатки как я и хотел? И также не забудь про дикую лозу!$B$BДаже в ранних разработках мы старались варьировать цвета и узоры вышивки, также экспериментировали с выкройкой и представляли себе каким должен выглядеть он, наш идеальный продукт. Результатом этих экспериментов и стала выкройка которую ты видишь - наш дикарский кожаный жилет.$B$BНе забывай, ты же работаешь на меня!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джангору Быстрому Страннику в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2857,'Дикарский кожаный шлем','Дикарский кожаный шлем обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы. Как и во всех дикарских кожаных доспехах, в основу шлема вплетен дикий виноград, наделяющий его мощными, но непостоянными магическими свойствами. Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится!$b$bНо для изготовления изделия по этой выкройке мне понадобятся 2 ночных мундира, 2 ночных головных повязки и дикая лоза. Принеси это все, и выкройка твоя!','Принесите 2 ночных мундира, 2 ночных головных повязки и дикую лозу Джангору Быстрому Страннику в Лагере Мохаче.','Да, это Ночное снаряжение – именно то, что я просил тебя принести, $N. Впрочем, от кожевника твоего уровня я другого и не ждал.$B$BТы достоин того, чтобы изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь ее с пользой.','Мне нужны туники и повязки на голову, а еще мне нужен этот кусок дикой лозы, прежде чем я поделюсь с тобой знаниями о диких кожаных шлемах.$B$BГоловные уборы очень популярны среди искателей приключений, будь то обезоруживающая простая повязка на голову или полностью закрывающий шлем. Основы создания ценных головных уборов остаются неизменными, независимо от внешнего вида снаряжения.','Вернитесь к Джангору Быстрому Страннику в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарский кожаный шлем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дикарский кожаный шлем обеспечивает лучшую защиту головы, при этом не менее удобен, чем обычные шлемы. Как и во всех дикарских кожаных доспехах, в основу шлема вплетен дикий виноград, наделяющий его мощными, но непостоянными магическими свойствами. Тем, кто ходит в кожаных доспехах, эта вещица наверняка пригодится!$b$bНо для изготовления изделия по этой выкройке мне понадобятся 2 ночных мундира, 2 ночных головных повязки и дикая лоза. Принеси это все, и выкройка твоя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 ночных мундира, 2 ночных головных повязки и дикую лозу Джангору Быстрому Страннику в Лагере Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это Ночное снаряжение – именно то, что я просил тебя принести, $N. Впрочем, от кожевника твоего уровня я другого и не ждал.$B$BТы достоин того, чтобы изготовлять дикарские кожаные шлемы. Вот тебе выкройка. Надеюсь, ты применишь ее с пользой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужны туники и повязки на голову, а еще мне нужен этот кусок дикой лозы, прежде чем я поделюсь с тобой знаниями о диких кожаных шлемах.$B$BГоловные уборы очень популярны среди искателей приключений, будь то обезоруживающая простая повязка на голову или полностью закрывающий шлем. Основы создания ценных головных уборов остаются неизменными, независимо от внешнего вида снаряжения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джангору Быстрому Страннику в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2858,'Дикарские кожаные сапоги','Тебе известно уже немало, $n. Но многое еще остается постичь. Теперь ты узнаешь о дикарских кожаных сапогах – ведь без обуви не обходится ни один доспех.$b$bНоге в них удобно и приятно, и дальний путь в них не так тяжел. Мягкая же подошва позволяет при необходимости ступать беззвучно.$b$bДля изготовления их по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог. И два экземпляра дикого винограда – запомни, два, а не один! Добудешь все это – продолжим.','Принесите 2 пары ночных штанов, 2 пары ночных сапог и 2 экземпляра дикой лозы Джангору Быстрому Страннику в Лагере Мохаче.','И снова ты выполняешь непростой заказ с искусством опытного профессионала! Ты $Gзаслужил:заслужила; эту выкройку, равно как и мою благодарность.','Изучать рецепты на штаны и сапоги надо с их производных - то есть изучать то, с чего они делаются. Немалую роль в этом играет дикая лоза. $GУсвоил:Усвоила; это, $N?','Вернитесь к Джангору Быстрому Страннику в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарские кожаные сапоги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе известно уже немало, $n. Но многое еще остается постичь. Теперь ты узнаешь о дикарских кожаных сапогах – ведь без обуви не обходится ни один доспех.$b$bНоге в них удобно и приятно, и дальний путь в них не так тяжел. Мягкая же подошва позволяет при необходимости ступать беззвучно.$b$bДля изготовления их по выкройке мне потребуются две пары ночных штанов и две пары ночных сапог. И два экземпляра дикого винограда – запомни, два, а не один! Добудешь все это – продолжим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 пары ночных штанов, 2 пары ночных сапог и 2 экземпляра дикой лозы Джангору Быстрому Страннику в Лагере Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И снова ты выполняешь непростой заказ с искусством опытного профессионала! Ты $Gзаслужил:заслужила; эту выкройку, равно как и мою благодарность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Изучать рецепты на штаны и сапоги надо с их производных - то есть изучать то, с чего они делаются. Немалую роль в этом играет дикая лоза. $GУсвоил:Усвоила; это, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джангору Быстрому Страннику в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2859,'Дикарские кожаные поножи','Ну, $n, теперь мы можем перейти к более сложным вещам. Дикарские кожаные поножи – одна из наиболее прочных и надежных разновидностей кожаного доспеха. Они отлично защищают ноги. А поскольку в них вшита еще и дикая лоза, дающая дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи.$b$bДля изготовления изделия по этой выкройке мне понадобятся два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей, и два экземпляра дикого винограда.','Принесите два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей и два экземпляра дикой лозы Джангору Быстрому Страннику в Лагерь Мохаче.','Ну что, мой приказ снова выполнен отлично. Может, в один прекрасный день уже я явлюсь к тебе, как ученик к учителю, а, $N?$B$BВот выкройка поножей, а с ней и моя благодарность. Пусти полученные знания в дело, и пусть твои изделия будут достойны твоих способностей!','Ну? $GДобыл:Добыла; наручи и шлем из черепашьего панциря? Чего ты возишься?$B$BТы уже $Gдолжен:должна; понимать потенциал кожаной брони. Великолепная броня, настоящий вызов кожевеннику. Каким искусным мастером надо быть чтобы изготавливать такую гибкую но в то же время прочную броню!','Вернитесь к Джангору Быстрому Страннику в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикарские кожаные поножи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, $n, теперь мы можем перейти к более сложным вещам. Дикарские кожаные поножи – одна из наиболее прочных и надежных разновидностей кожаного доспеха. Они отлично защищают ноги. А поскольку в них вшита еще и дикая лоза, дающая дополнительную защиту, любой искатель приключений скажет тебе спасибо за такие поножи.$b$bДля изготовления изделия по этой выкройке мне понадобятся два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей, и два экземпляра дикого винограда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите два шлема из черепашьего панциря, две пары черепашьих чешуйчатых наручей и два экземпляра дикой лозы Джангору Быстрому Страннику в Лагерь Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что, мой приказ снова выполнен отлично. Может, в один прекрасный день уже я явлюсь к тебе, как ученик к учителю, а, $N?$B$BВот выкройка поножей, а с ней и моя благодарность. Пусти полученные знания в дело, и пусть твои изделия будут достойны твоих способностей!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну? $GДобыл:Добыла; наручи и шлем из черепашьего панциря? Чего ты возишься?$B$BТы уже $Gдолжен:должна; понимать потенциал кожаной брони. Великолепная броня, настоящий вызов кожевеннику. Каким искусным мастером надо быть чтобы изготавливать такую гибкую но в то же время прочную броню!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джангору Быстрому Страннику в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2860,'Мастер школы Дикаря','Что ж, $n, теперь ты знаешь все, чему я мог тебя научить. Однако остался еще один предмет из дикарских кожаных доспехов, выкройки которого у тебя нет. Я не стану заставлять тебя трудиться, чтобы ее получить: ты и так сполна $gрасплатился:расплатилась; за все. Однако же отдать тебе его сам я не могу.$b$bТы получишь награду от моей наставницы, той, которая посвятила в тайны нашего ремесла меня самого. Отнеси эту записку Уне. Она обучает кожевников в Громовом Утесе. Покажи ей записку, и пусть она приветствует тебя как $gравного:равную;, подобно мне самому.','Отдайте письмо Джангора Уне, главному кожевнику Громового Утеса.','А, ты от Джангора! Приятно видеть, что у одного из моих лучших учеников теперь свои ученики…$B$BДжангор – очень талантливый и добросовестный кожевенник. И если он тебя так расхваливает, это говорит в твою пользу.$B$BНасколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов? Позволь же, я завершу твое обучение, дав тебе вот эту выкройку. Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!','Приветствую, $R... Судя по твоему внешнему виду, ты – кожевник, как и я. Ты $Gпришел:пришла; чтобы учиться, или у тебя ко мне другое дело?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер школы Дикаря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, $n, теперь ты знаешь все, чему я мог тебя научить. Однако остался еще один предмет из дикарских кожаных доспехов, выкройки которого у тебя нет. Я не стану заставлять тебя трудиться, чтобы ее получить: ты и так сполна $gрасплатился:расплатилась; за все. Однако же отдать тебе его сам я не могу.$b$bТы получишь награду от моей наставницы, той, которая посвятила в тайны нашего ремесла меня самого. Отнеси эту записку Уне. Она обучает кожевников в Громовом Утесе. Покажи ей записку, и пусть она приветствует тебя как $gравного:равную;, подобно мне самому.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте письмо Джангора Уне, главному кожевнику Громового Утеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, ты от Джангора! Приятно видеть, что у одного из моих лучших учеников теперь свои ученики…$B$BДжангор – очень талантливый и добросовестный кожевенник. И если он тебя так расхваливает, это говорит в твою пользу.$B$BНасколько я понимаю, он обучил тебя секретам дикарских кожаных доспехов? Позволь же, я завершу твое обучение, дав тебе вот эту выкройку. Пользуйся ею с умом: немного на свете тех, кто владеет тайной изготовления дикарских кожаных плащей!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $R... Судя по твоему внешнему виду, ты – кожевник, как и я. Ты $Gпришел:пришла; чтобы учиться, или у тебя ко мне другое дело?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2861,'Миссия Табеты','Ходят слухи, что у Табеты, мага, живущего в Пылевых топях, серьезный зуб на одну песчаную троллиху из Зул\'Фаррака. Если ты поговоришь с Табетой, она, конечно, расскажет тебе больше.$B$BИ захвати с собой друзей, $n. Если она пошлет тебя в Зул\'Фаррак, а скорее всего так и будет, то лучше тебе там в одиночку не появляться.$B$BТы найдешь дом Табеты к западу от Терамора и к северу от руин Каменного Молота.','Поговорите с Табетой в Пылевых топях.','Да. Верно. У меня большой зуб на эту троллиху. И не один.$B$BХочешь помочь мне?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Миссия Табеты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, что у Табеты, мага, живущего в Пылевых топях, серьезный зуб на одну песчаную троллиху из Зул\'Фаррака. Если ты поговоришь с Табетой, она, конечно, расскажет тебе больше.$B$BИ захвати с собой друзей, $n. Если она пошлет тебя в Зул\'Фаррак, а скорее всего так и будет, то лучше тебе там в одиночку не появляться.$B$BТы найдешь дом Табеты к западу от Терамора и к северу от руин Каменного Молота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Табетой в Пылевых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да. Верно. У меня большой зуб на эту троллиху. И не один.$B$BХочешь помочь мне?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2862,'Война с племенем Древолапов','О, эти гноллы... Сказать, что они отравляют нам жизнь – значит ничего не сказать! Мы здесь постоянно живем под угрозой нападения! Я не знаю, всегда ли они жили в Фераласе, или пришли сюда откуда-то еще, но если мы не будем противостоять им достаточно решительно, нам здесь не жить.$b$bА в последнее время гноллы совершенно озверели! Нам необходима твоя помощь, чтобы сократить их численность. Принеси мне десяток их грив, и я щедро вознагражу тебя за труды.$b$bСтупай!','Принесите 10 грив гноллов-древолапов Хадокену Быстрому Страннику в Лагере Мохаче.','Неплохое начало, $N! Таких воинов, как ты, еще поискать!$B$BЯ ведь давал такое задание не только тебе. И до тебя немало бойцов сражались с гноллами, и в былые времена наших усилий хватало, чтобы заставить их отступить. Однако в последнее время они упорно прут на север, в наши земли. Гноллы бьются так отчаянно... как будто им некуда отступать!$B$BОднако у меня есть один план. Возможно, он позволит раз и навсегда покончить с этой войной...','Мы отражаем их нападения, а они все лезут и лезут! Их явно что-то гонит... Или, может быть, кто-то? А, $N, ты уже $Gвернулся:вернулась;? Ну что, гривы при тебе?','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война с племенем Древолапов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, эти гноллы... Сказать, что они отравляют нам жизнь – значит ничего не сказать! Мы здесь постоянно живем под угрозой нападения! Я не знаю, всегда ли они жили в Фераласе, или пришли сюда откуда-то еще, но если мы не будем противостоять им достаточно решительно, нам здесь не жить.$b$bА в последнее время гноллы совершенно озверели! Нам необходима твоя помощь, чтобы сократить их численность. Принеси мне десяток их грив, и я щедро вознагражу тебя за труды.$b$bСтупай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 грив гноллов-древолапов Хадокену Быстрому Страннику в Лагере Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохое начало, $N! Таких воинов, как ты, еще поискать!$B$BЯ ведь давал такое задание не только тебе. И до тебя немало бойцов сражались с гноллами, и в былые времена наших усилий хватало, чтобы заставить их отступить. Однако в последнее время они упорно прут на север, в наши земли. Гноллы бьются так отчаянно... как будто им некуда отступать!$B$BОднако у меня есть один план. Возможно, он позволит раз и навсегда покончить с этой войной...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы отражаем их нападения, а они все лезут и лезут! Их явно что-то гонит... Или, может быть, кто-то? А, $N, ты уже $Gвернулся:вернулась;? Ну что, гривы при тебе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2863,'Истребление вожаков','План состоит в том, чтобы одним махом истребить всех предводителей гноллов. Если нам удастся это сделать, в рядах гноллов воцарится хаос. А возможно, до этих блохастых тварей даже дойдет, что с нами лучше не связываться!$b$bТебе, $n, я поручаю истребить пятерых вожаков гноллов. Только сделать это нужно в течение часа, иначе весь план пойдет насмарку!','Убейте в течение часа 5 вожаков стаи Древолапов и вернитесь к Хадокену Быстрому Страннику.','Тебе удалось выполнить мою просьбу. $GМолодец:Умница;, $N! Вот, прими эту небольшую награду за свои труды.$B$BТеперь, когда число гноллов сократилось, и их вожаки перебиты, эти твари дважды подумают, прежде чем решатся снова напасть на лагерь! Однако проблемы это не решает...$B$BГноллы не могли так озвереть безо всякой причины! И я хочу выяснить, в чем дело, прежде, чем они пришли в себя.','Время уходит, $N! Если вы здесь не для того, чтобы сообщить, что вы уничтожили Альфа, значит, вы зря теряете время!','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление вожаков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','План состоит в том, чтобы одним махом истребить всех предводителей гноллов. Если нам удастся это сделать, в рядах гноллов воцарится хаос. А возможно, до этих блохастых тварей даже дойдет, что с нами лучше не связываться!$b$bТебе, $n, я поручаю истребить пятерых вожаков гноллов. Только сделать это нужно в течение часа, иначе весь план пойдет насмарку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте в течение часа 5 вожаков стаи Древолапов и вернитесь к Хадокену Быстрому Страннику.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось выполнить мою просьбу. $GМолодец:Умница;, $N! Вот, прими эту небольшую награду за свои труды.$B$BТеперь, когда число гноллов сократилось, и их вожаки перебиты, эти твари дважды подумают, прежде чем решатся снова напасть на лагерь! Однако проблемы это не решает...$B$BГноллы не могли так озвереть безо всякой причины! И я хочу выяснить, в чем дело, прежде, чем они пришли в себя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Время уходит, $N! Если вы здесь не для того, чтобы сообщить, что вы уничтожили Альфа, значит, вы зря теряете время!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2864,'Тран\'рек','У моего кузена Тран\'река сейчас большие проблемы. Он обещал мне партию панцирей скарабея еще неделю назад, но так и не поставил. Он мой кузен, так что я не хотел бы посылать кого-то в Прибамбасск выколачивать из него свои деньги или груз.$B$BМожешь поговорить с ним за меня? Скажи ему, что он должен доставить мне этот груз – иначе придется отвечать, как и всем остальным... $B$BПрибамбасск находится на севере пустыни Танарис в Калимдоре.','Поговорите с Тран\'реком в Прибамбасске.','Привет!$B$BТак ты общался с моим кузеном Кразеком? Ну и как он там? Надеюсь, что в Бухте контрабандистов к нему хорошо относятся…$B$BПанцири скарабея, говоришь? Дай мне рассказать тебе одну историю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тран\'рек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У моего кузена Тран\'река сейчас большие проблемы. Он обещал мне партию панцирей скарабея еще неделю назад, но так и не поставил. Он мой кузен, так что я не хотел бы посылать кого-то в Прибамбасск выколачивать из него свои деньги или груз.$B$BМожешь поговорить с ним за меня? Скажи ему, что он должен доставить мне этот груз – иначе придется отвечать, как и всем остальным... $B$BПрибамбасск находится на севере пустыни Танарис в Калимдоре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тран\'реком в Прибамбасске.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет!$B$BТак ты общался с моим кузеном Кразеком? Ну и как он там? Надеюсь, что в Бухте контрабандистов к нему хорошо относятся…$B$BПанцири скарабея, говоришь? Дай мне рассказать тебе одну историю.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2865,'Панцири скарабеев','У скарабеев Танариса очень твердый панцирь, достаточно твердый, чтобы использовать их как строительный материал много для чего. Очень много!$B$BЭти панцири, настолько полезная вещь, что ради них скарабеев извели практически под корень.$B$BЯ знаю, где они еще водятся, и я поделюсь с тобой, если ты пообещаешь принести мне их панцири, обещаешь?$B$BТак вот. Колония скарабеев находится в Зул\'Фарраке. Видимо до троллей еще не дошло, насколько полезны их панцири.$B$BТак что все твои! Отправляйся в Зул\'Фаррак и принеси мне целых панцирей скарабеев.','Принести 5 целых панцирей скарабея Тран\'реку в Прибамбасск.','Принес? Мой кузен в Пиратской бухте очень ждет этих панцирей. А он не любит ждать!','Вернитесь к Тран\'реку в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Панцири скарабеев',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У скарабеев Танариса очень твердый панцирь, достаточно твердый, чтобы использовать их как строительный материал много для чего. Очень много!$B$BЭти панцири, настолько полезная вещь, что ради них скарабеев извели практически под корень.$B$BЯ знаю, где они еще водятся, и я поделюсь с тобой, если ты пообещаешь принести мне их панцири, обещаешь?$B$BТак вот. Колония скарабеев находится в Зул\'Фарраке. Видимо до троллей еще не дошло, насколько полезны их панцири.$B$BТак что все твои! Отправляйся в Зул\'Фаррак и принеси мне целых панцирей скарабеев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принести 5 целых панцирей скарабея Тран\'реку в Прибамбасск.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принес? Мой кузен в Пиратской бухте очень ждет этих панцирей. А он не любит ждать!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тран\'реку в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2866,'Руины Соларсаля','К югу от нас находятся руины Соларсаля. Это развалины очень древнего города. Мы уже обследовали руины, но пока не нашли там ничего примечательного и оставили их в покое.$b$bОднако не так давно в этих развалинах поселились наги из клана Гребня Ненависти, причем в угрожающих количествах. Поначалу мы решили, что они готовят нападение. Возможно, они его действительно готовят, но нам кажется, что там происходит что-то еще.$b$bСтупай туда, осмотри развалины и обрати внимание на все, что покажется подозрительным. Удачи, $n!','Обследуйте руины Соларсаля на предмет присутствия наг.','Внимательно изучив беседку, вы обнаруживаете следующее.$B$BВо-первых, беседка явно новая, и не похожа на окружающие руины. Во-вторых, столбы беседки исписаны мелкими значками. Значки повторяются, но что это за письмена и что они означают, вам непонятно. Ну и, в-третьих, камень беседки – теплый на ощупь.$B$BДа, все это, несомненно, подозрительно!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины Соларсаля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К югу от нас находятся руины Соларсаля. Это развалины очень древнего города. Мы уже обследовали руины, но пока не нашли там ничего примечательного и оставили их в покое.$b$bОднако не так давно в этих развалинах поселились наги из клана Гребня Ненависти, причем в угрожающих количествах. Поначалу мы решили, что они готовят нападение. Возможно, они его действительно готовят, но нам кажется, что там происходит что-то еще.$b$bСтупай туда, осмотри развалины и обрати внимание на все, что покажется подозрительным. Удачи, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обследуйте руины Соларсаля на предмет присутствия наг.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Внимательно изучив беседку, вы обнаруживаете следующее.$B$BВо-первых, беседка явно новая, и не похожа на окружающие руины. Во-вторых, столбы беседки исписаны мелкими значками. Значки повторяются, но что это за письмена и что они означают, вам непонятно. Ну и, в-третьих, камень беседки – теплый на ощупь.$B$BДа, все это, несомненно, подозрительно!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2867,'Возвращение в Крепость Оперенной Луны','Теперь, когда вы обнаружили странную беседку в глубине руин Соларсаля, настало время вернуться в Крепость Оперенной Луны и доложить генералу Шандрисе Оперенной Луне о своем открытии.','Вернитесь в Крепость Оперенной Луны к Шандрисе Оперенной Луне и доложите о находке.','С возвращением, $N! Обнаруженная тобой беседка действительно весьма... подозрительна. Очевидно, что даже если наги и не замышляют нападения, их присутствие не сулит нам ничего хорошего. Ну, как бы то ни было, вот твоя заслуженная награда.$B$BСудя по всему, Крепость Оперенной Луны отчаянно нуждается в помощи для борьбы с нагами из клана Гребня Ненависти. Я бы хотела дать тебе еще одно поручение, если ты не против...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Крепость Оперенной Луны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда вы обнаружили странную беседку в глубине руин Соларсаля, настало время вернуться в Крепость Оперенной Луны и доложить генералу Шандрисе Оперенной Луне о своем открытии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Крепость Оперенной Луны к Шандрисе Оперенной Луне и доложите о находке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С возвращением, $N! Обнаруженная тобой беседка действительно весьма... подозрительна. Очевидно, что даже если наги и не замышляют нападения, их присутствие не сулит нам ничего хорошего. Ну, как бы то ни было, вот твоя заслуженная награда.$B$BСудя по всему, Крепость Оперенной Луны отчаянно нуждается в помощи для борьбы с нагами из клана Гребня Ненависти. Я бы хотела дать тебе еще одно поручение, если ты не против...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (2868,'<TXT> Сушеное сердце','Засунь этого урода в какую-нибудь троллью могилу в затонувшем храме и будет тебе счастье!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<TXT> Сушеное сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Засунь этого урода в какую-нибудь троллью могилу в затонувшем храме и будет тебе счастье!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2869,'Борьба с Гребнем Ненависти','На данный момент самое разумное – рассчитывать на то, что наги в любом случае попытаются захватить остров. И нам нужно предотвратить эту угрозу, пока не стало поздно.$b$bПринеси мне десять штук чешуи Гребня Ненависти. Как их добыть – думаю, ясно? У тебя будет случай поохотиться на наг, и количество их воинов на острове Сардор уменьшится. И то, и другое нам на пользу!','Принесите 10 штук чешуи наг из клана Гребня Ненависти Латроникусу Лунному Копью в Крепость Оперенной Луны.','Да-да, эта чешуя вполне годится. Думаю, мы отправим ее Пратту. Может быть, он сумеет изготовить из нее что-нибудь полезное.$B$BА для тебя у меня есть еще одно задание. Но сначала вот твоя награда за труды. Твоя служба генералу и всей Крепости Оперенной Луны очень ценна перед лицом грозящей нам опасности.','Если ты здесь затем, чтобы отчитаться о выполнении задания, $N, то отлично: где мои десять штук чешуи? А если ты просто так, поболтать, то мне сейчас не до этого.$B$BЗнай, мы, ночные эльфы – народ мирный! Мы стремимся лишь к поддержанию мира и гармонии. Однако это не значит, что мы не готовы защищать свои интересы. Это мой долг перед генералом Лунное Перо, и перед всей крепостью!','Вернитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с Гребнем Ненависти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На данный момент самое разумное – рассчитывать на то, что наги в любом случае попытаются захватить остров. И нам нужно предотвратить эту угрозу, пока не стало поздно.$b$bПринеси мне десять штук чешуи Гребня Ненависти. Как их добыть – думаю, ясно? У тебя будет случай поохотиться на наг, и количество их воинов на острове Сардор уменьшится. И то, и другое нам на пользу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 штук чешуи наг из клана Гребня Ненависти Латроникусу Лунному Копью в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да, эта чешуя вполне годится. Думаю, мы отправим ее Пратту. Может быть, он сумеет изготовить из нее что-нибудь полезное.$B$BА для тебя у меня есть еще одно задание. Но сначала вот твоя награда за труды. Твоя служба генералу и всей Крепости Оперенной Луны очень ценна перед лицом грозящей нам опасности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты здесь затем, чтобы отчитаться о выполнении задания, $N, то отлично: где мои десять штук чешуи? А если ты просто так, поболтать, то мне сейчас не до этого.$B$BЗнай, мы, ночные эльфы – народ мирный! Мы стремимся лишь к поддержанию мира и гармонии. Однако это не значит, что мы не готовы защищать свои интересы. Это мой долг перед генералом Лунное Перо, и перед всей крепостью!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2870,'Борьба с лордом Шалзару','$n, мы получили новые донесения разведчиков, и теперь неплохо представляем себе, как устроено войско наг. Высшее командование состоит из особ королевской крови. Именно они-то всем и заправляют.$b$bНам стало известно имя одного из самых жестоких наг, лорда Шалзару. Разведка докладывает, что во время недавних раскопок, которые наги проводили в пещере к югу от основных руин на острове Ужаса, он лично обнаружил некую загадочную реликвию.$b$bЕго необходимо остановить. Убей его, и принеси мне этот предмет, чтобы мы могли его изучить.','Убейте лорда Шалзару и принесите обнаруженную им таинственную реликвию Латроникусу Лунному Копью в Крепость Оперенной Луны.','Отлично, $N! Гибель лорда Шалзару повергнет наг в смятение – надолго, если не навсегда. Так что теперь они представляют значительно меньшую угрозу, чем прежде, и все это – благодаря тебе!$B$BВот тебе новая награда из сокровищницы замка. Эта награда заслужена тобой – вся, вплоть до последней монеты! Добро пожаловать в Крепость Оперенной Луны в любое время, друг мой.$B$BДа, $N, и прежде, чем ты уйдешь... еще одна просьба...','Смерть лорда Шалзару заставит их отложить выполнение своих планов на несколько недель, если не на несколько месяцев. Кроме того, обнаруженная им реликвия весьма любопытна…$B$BНу что, $N, удалось тебе выполнить задание?','Вернитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с лордом Шалзару',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мы получили новые донесения разведчиков, и теперь неплохо представляем себе, как устроено войско наг. Высшее командование состоит из особ королевской крови. Именно они-то всем и заправляют.$b$bНам стало известно имя одного из самых жестоких наг, лорда Шалзару. Разведка докладывает, что во время недавних раскопок, которые наги проводили в пещере к югу от основных руин на острове Ужаса, он лично обнаружил некую загадочную реликвию.$b$bЕго необходимо остановить. Убей его, и принеси мне этот предмет, чтобы мы могли его изучить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лорда Шалзару и принесите обнаруженную им таинственную реликвию Латроникусу Лунному Копью в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! Гибель лорда Шалзару повергнет наг в смятение – надолго, если не навсегда. Так что теперь они представляют значительно меньшую угрозу, чем прежде, и все это – благодаря тебе!$B$BВот тебе новая награда из сокровищницы замка. Эта награда заслужена тобой – вся, вплоть до последней монеты! Добро пожаловать в Крепость Оперенной Луны в любое время, друг мой.$B$BДа, $N, и прежде, чем ты уйдешь... еще одна просьба...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Смерть лорда Шалзару заставит их отложить выполнение своих планов на несколько недель, если не на несколько месяцев. Кроме того, обнаруженная им реликвия весьма любопытна…$B$BНу что, $N, удалось тебе выполнить задание?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2871,'Доставка реликвии','Не возьмешься ли ты доставить эту реликвию моей жене Вестии? Я был бы тебе очень признателен. Она не только почтенная жрица, но и одна из наиболее сведущих ученых. Я лично не пойму, что это за штука, хоть меня озолоти. Но уж если моя жена в ней не разберется, значит, не разберется никто.$b$bОна вон там, неподалеку. Занимается, небось. Спасибо, $n!','Доставьте таинственную реликвию Вестии Лунное Копье в Крепость Оперенной Луны.','Интересно... Так говоришь, это вещь из руин Соларсаля? Ну да, Латро прав: мне следовало на это взглянуть... Такое впечатление, что эта вещь – не оттуда. С другой стороны, на работу наг это тоже не похоже. Далеко не столь чуждое…$B$BМне потребуется некоторое время на то, чтобы с ней разобраться. А когда я завершу свои исследования, возможно, ты мне снова пригодишься – если ты, конечно, окажешься в это время поблизости.$B$BНа, возьми это – у нас таких вещиц много, а тебе она, думаю, пригодится!','Да, чем могу помочь? Постой-постой, это ты – тот самый $R, который помогает генералу Лунное Перо и моему Латро разобраться с нагами? Я – Вестия, жена Латро... то есть Латроникуса. Очень рада познакомиться!$B$BНо прошу прощения – ведь ты, конечно, здесь по делу? Ты мне что-то $Gпринес:принесла;?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка реликвии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не возьмешься ли ты доставить эту реликвию моей жене Вестии? Я был бы тебе очень признателен. Она не только почтенная жрица, но и одна из наиболее сведущих ученых. Я лично не пойму, что это за штука, хоть меня озолоти. Но уж если моя жена в ней не разберется, значит, не разберется никто.$b$bОна вон там, неподалеку. Занимается, небось. Спасибо, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте таинственную реликвию Вестии Лунное Копье в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интересно... Так говоришь, это вещь из руин Соларсаля? Ну да, Латро прав: мне следовало на это взглянуть... Такое впечатление, что эта вещь – не оттуда. С другой стороны, на работу наг это тоже не похоже. Далеко не столь чуждое…$B$BМне потребуется некоторое время на то, чтобы с ней разобраться. А когда я завершу свои исследования, возможно, ты мне снова пригодишься – если ты, конечно, окажешься в это время поблизости.$B$BНа, возьми это – у нас таких вещиц много, а тебе она, думаю, пригодится!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, чем могу помочь? Постой-постой, это ты – тот самый $R, который помогает генералу Лунное Перо и моему Латро разобраться с нагами? Я – Вестия, жена Латро... то есть Латроникуса. Очень рада познакомиться!$B$BНо прошу прощения – ведь ты, конечно, здесь по делу? Ты мне что-то $Gпринес:принесла;?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2872,'Долг Столи','Мой давний приятель Столи должен мне особую бутылку рома. Он держит бар в Порту Хитрой Шестеренки в Танарисе, и клялся, что ром у него крепче, чем во всей Пиратской Бухте. Он даже заявил, что удвоит свой долг мне, если я попробую его напиток и не соглашусь с ним!$b$bДумаю, он потом пожалел о своих словах, потому и не шлет мне ром. Но я ничего не забываю, поэтому поговори с ним вместо меня...','Поговорите со Столи из Порта Хитрой Шестеренки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долг Столи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой давний приятель Столи должен мне особую бутылку рома. Он держит бар в Порту Хитрой Шестеренки в Танарисе, и клялся, что ром у него крепче, чем во всей Пиратской Бухте. Он даже заявил, что удвоит свой долг мне, если я попробую его напиток и не соглашусь с ним!$b$bДумаю, он потом пожалел о своих словах, потому и не шлет мне ром. Но я ничего не забываю, поэтому поговори с ним вместо меня...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со Столи из Порта Хитрой Шестеренки.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2873,'Посылка Столи','Я должен старине Маккинли из Пиратской Бухты немного рома. Проблема в том, что ром у меня закончился! Капитан Куэрго украл последнюю партию и прячет в стенах огороженного пиратского поселения на юге.$b$bЕсли ты отыщешь мою партию рома, я смогу доказать Маккинли, что калимдорская выпивка в сто раз лучше пойла из Пиратской Бухты!','Отыщите партию товара Столи и возвратите ее хозяину в Порт Хитрой Шестеренки.','Вернитесь к Столи в Южные моря, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посылка Столи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я должен старине Маккинли из Пиратской Бухты немного рома. Проблема в том, что ром у меня закончился! Капитан Куэрго украл последнюю партию и прячет в стенах огороженного пиратского поселения на юге.$b$bЕсли ты отыщешь мою партию рома, я смогу доказать Маккинли, что калимдорская выпивка в сто раз лучше пойла из Пиратской Бухты!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите партию товара Столи и возвратите ее хозяину в Порт Хитрой Шестеренки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Столи в Южные моря, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (2873,'Did you find my shipment of rum, $n?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Did you find my shipment of rum, $n?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2874,'Ром для Маккинли','Еще раз спасибо за помощь, $n. Вот тебе бутылка картельского рома. Отнеси ее Маккинли, пора развеять его заблуждения относительно рома из Пиратской Бухты.','Отнесите бутылку Столи "Морскому волку" Маккинли в Пиратскую Бухту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ром для Маккинли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще раз спасибо за помощь, $n. Вот тебе бутылка картельского рома. Отнеси ее Маккинли, пора развеять его заблуждения относительно рома из Пиратской Бухты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите бутылку Столи "Морскому волку" Маккинли в Пиратскую Бухту.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2875,'РАЗЫСКИВАЕТСЯ: Андре Огнебородый','Злобный пират Андре Огнебородый разыскивается за преступления против картеля Хитрой Шестеренки и Прибамбасска.$B$BСогласно указу правящего совета, все лица, прочитавшие данный документ, уполномочены применять любые меры при задержании Андре и его пособников.$b$bСогласно следующему указу, если Андре скончается или по иным причинам не сможет предстать перед судом, его может представлять его голова. Предоставление упомянутой головы начальнику отдела безопасности Чепухастеру повлечет за собой заключение весьма выгодного и ответственного контракта.','Принесите голову Андре Огнебородого начальнику отдела безопасности Чепухастеру в Порт Хитрой Шестеренки','Вернитесь к начальнику отдела безопасности Чепухастеру в Порт Хитрой Шестеренки, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РАЗЫСКИВАЕТСЯ: Андре Огнебородый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Злобный пират Андре Огнебородый разыскивается за преступления против картеля Хитрой Шестеренки и Прибамбасска.$B$BСогласно указу правящего совета, все лица, прочитавшие данный документ, уполномочены применять любые меры при задержании Андре и его пособников.$b$bСогласно следующему указу, если Андре скончается или по иным причинам не сможет предстать перед судом, его может представлять его голова. Предоставление упомянутой головы начальнику отдела безопасности Чепухастеру повлечет за собой заключение весьма выгодного и ответственного контракта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Андре Огнебородого начальнику отдела безопасности Чепухастеру в Порт Хитрой Шестеренки',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к начальнику отдела безопасности Чепухастеру в Порт Хитрой Шестеренки, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2876,'Расписание кораблей','В свитке приводится список рейсов между Портом Хитрой Шестеренки и Пиратской Бухтой. Там перечислены все прошлые и будущие грузы с указанием названий кораблей, везущих их. Напротив некоторых стоит большой крестик, напротив других заметки "ОТЛИЧНАЯ ДОБЫЧА" и "СИЛЬНАЯ ОХРАНА".$b$bКое-кто из Порта Хитрой Шестеренки очень заинтересуется этим документом.','Сообщите о корабельном расписании руководству Порта Хитрой Шестеренки.','Ох, похоже это список рейсов, причем здесь указаны дни и часы отбытия и прибытия! Если эти сведения попали в руки капитана пиратского корабля, у нас будут большие неприятности!$B$BТы их у пирата нашел? Дурные вести…$B$BСпасибо, $N. Я рад, что ты $Gнашел:нашла; этот документ и $Gотправил:отправила; пирата кормить рыб!','Я смотрю, ты тяжело дышишь! У тебя какие-то новости?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расписание кораблей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В свитке приводится список рейсов между Портом Хитрой Шестеренки и Пиратской Бухтой. Там перечислены все прошлые и будущие грузы с указанием названий кораблей, везущих их. Напротив некоторых стоит большой крестик, напротив других заметки "ОТЛИЧНАЯ ДОБЫЧА" и "СИЛЬНАЯ ОХРАНА".$b$bКое-кто из Порта Хитрой Шестеренки очень заинтересуется этим документом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите о корабельном расписании руководству Порта Хитрой Шестеренки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, похоже это список рейсов, причем здесь указаны дни и часы отбытия и прибытия! Если эти сведения попали в руки капитана пиратского корабля, у нас будут большие неприятности!$B$BТы их у пирата нашел? Дурные вести…$B$BСпасибо, $N. Я рад, что ты $Gнашел:нашла; этот документ и $Gотправил:отправила; пирата кормить рыб!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я смотрю, ты тяжело дышишь! У тебя какие-то новости?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2877,'Большая уборка на Осклизлой скале','Мы, клан Громового Молота, помним прошлое куда лучше, чем наши братья из Стальгорна. Если хочешь, чтобы к тебе тут хорошо относились, не бойся грязной работы!$B$BОрда забросила одну из своих баз во Внутренних землях, она находится на Осклизлой скале. Сейчас эту базу заполонили слизнюки и пиявки, у нас были на нее планы, но пока там кишат эти твари, мы не можем занять эту позицию.$B$BВот тебе, собственно, и работка! Отправляйся туда и убей по 10 зеленых слякочей и нефритовых слизнюков, а потом доложи мне, как все прошло. Бегом!','Убейте 10 зеленых слякочей и 10 нефритовых слизнюков, после чего доложитесь Фраггару Громовой Мантии, который ждет вас на Заоблачном пике.','Нет, подумать только, как вы здорово помогли Громовому Молоту! Вы отлично работаете, а мы это ценим.$B$BВаша маленькая зачистка куда важнее, чем может показаться на первый взгляд. Осталось еще истребить слизнюков и пиявок, и тогда мы сможем распространить свое влияние еще дальше. Новые друзья на Заоблочном Пике – это, конечно, хорошо, но, как говорится, не дружбой единой, так что вот вам еще кое-что, вдобавок.','Не пытайся договориться о предстоящей миссии, $R! Если бы боги хотели, чтобы эти илы были убиты, они бы уже чудом это сделали, не так ли?!','Вернитесь к Фраггару Громовой Мантии на Заоблачный пик, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая уборка на Осклизлой скале',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы, клан Громового Молота, помним прошлое куда лучше, чем наши братья из Стальгорна. Если хочешь, чтобы к тебе тут хорошо относились, не бойся грязной работы!$B$BОрда забросила одну из своих баз во Внутренних землях, она находится на Осклизлой скале. Сейчас эту базу заполонили слизнюки и пиявки, у нас были на нее планы, но пока там кишат эти твари, мы не можем занять эту позицию.$B$BВот тебе, собственно, и работка! Отправляйся туда и убей по 10 зеленых слякочей и нефритовых слизнюков, а потом доложи мне, как все прошло. Бегом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 зеленых слякочей и 10 нефритовых слизнюков, после чего доложитесь Фраггару Громовой Мантии, который ждет вас на Заоблачном пике.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет, подумать только, как вы здорово помогли Громовому Молоту! Вы отлично работаете, а мы это ценим.$B$BВаша маленькая зачистка куда важнее, чем может показаться на первый взгляд. Осталось еще истребить слизнюков и пиявок, и тогда мы сможем распространить свое влияние еще дальше. Новые друзья на Заоблочном Пике – это, конечно, хорошо, но, как говорится, не дружбой единой, так что вот вам еще кое-что, вдобавок.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не пытайся договориться о предстоящей миссии, $R! Если бы боги хотели, чтобы эти илы были убиты, они бы уже чудом это сделали, не так ли?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фраггару Громовой Мантии на Заоблачный пик, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (2878,'Оскверненный песнецвет','Вернитесь к оскверненному песнецвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный песнецвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному песнецвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2879,'Посох равноденствия','Это, должно быть, посох Равноденствия! Этот посох, на самом деле, является ключом, которым некогда отмыкали Монолит Равноденствия в Руинах Яростного Ветра, на материке к западу от Сонных Ветвей.$b$bОтыщите четыре огня, которые все еще пылают среди руин: Самха, Имбел, Бильтан и Лахасса. Добудьте их суть, встаньте перед Монолитом и зарядите посох их силой. Если это действительно посох Равноденствия, вы сумеете отпереть Монолит и достать из него священный артефакт.','Зарядите посох Трояса и отыщите Монолит Равноденствия.','Заряженный посох буквально вырывается из рук. Невероятная мощь отдается дрожью во всем теле.$B$BВы касаетесь холодной поверхности Монолита…$B$BОтворяется небольшая дверка, за ней виднеется артефакт.$B$BВсе пространство вокруг Монолита Равноденствия озаряется светом.','Монолит Равноденствия безмолвно высится среди руин. Что же может быть внутри него?','Вернитесь к Монолиту Равноденствия у Двух Колоссов, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посох равноденствия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это, должно быть, посох Равноденствия! Этот посох, на самом деле, является ключом, которым некогда отмыкали Монолит Равноденствия в Руинах Яростного Ветра, на материке к западу от Сонных Ветвей.$b$bОтыщите четыре огня, которые все еще пылают среди руин: Самха, Имбел, Бильтан и Лахасса. Добудьте их суть, встаньте перед Монолитом и зарядите посох их силой. Если это действительно посох Равноденствия, вы сумеете отпереть Монолит и достать из него священный артефакт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зарядите посох Трояса и отыщите Монолит Равноденствия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Заряженный посох буквально вырывается из рук. Невероятная мощь отдается дрожью во всем теле.$B$BВы касаетесь холодной поверхности Монолита…$B$BОтворяется небольшая дверка, за ней виднеется артефакт.$B$BВсе пространство вокруг Монолита Равноденствия озаряется светом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Монолит Равноденствия безмолвно высится среди руин. Что же может быть внутри него?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Монолиту Равноденствия у Двух Колоссов, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2880,'Ожерелья троллей','Я скажу прямо, $n – мы НЕ принадлежим к Альянсу! Клан Громового Молота – это независимая организация, и мы относимся хорошо только к тем, кто заслужил это своими делами, а не пустой высокопарной болтовней!$B$BЕсли вы хотите, чтобы вас тут уважали, – докажите, что вы достойны! В холмах Внутренних земель поселились мерзкие тролли, которые иногда носят племенные ожерелья. Принесите мне пять таких ожерелий, и тогда я, возможно, поверю, что с вами можно иметь дело.','Принесите 5 тролльих ожерелий Фраггару Громовой Мантии на Заоблачный пик.','Вот, о чем я и говорил! Эти ожерелья доказывают, что вы не боитесь черной работы, а клан Громового Молота это ценит.$B$BПродолжайте в том же духе, и заслужите наше уважение.','Мне нужно пять ожерелий, которые носят эти тролли. Если непонятно, то поясню, что проще всего снять ожерелье с мертвого тролля.$B$BДокажите, что вы друг Громового Молота.','Вернитесь к Фраггару Громовой Мантии на Заоблачный пик, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелья троллей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я скажу прямо, $n – мы НЕ принадлежим к Альянсу! Клан Громового Молота – это независимая организация, и мы относимся хорошо только к тем, кто заслужил это своими делами, а не пустой высокопарной болтовней!$B$BЕсли вы хотите, чтобы вас тут уважали, – докажите, что вы достойны! В холмах Внутренних земель поселились мерзкие тролли, которые иногда носят племенные ожерелья. Принесите мне пять таких ожерелий, и тогда я, возможно, поверю, что с вами можно иметь дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 тролльих ожерелий Фраггару Громовой Мантии на Заоблачный пик.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, о чем я и говорил! Эти ожерелья доказывают, что вы не боитесь черной работы, а клан Громового Молота это ценит.$B$BПродолжайте в том же духе, и заслужите наше уважение.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно пять ожерелий, которые носят эти тролли. Если непонятно, то поясню, что проще всего снять ожерелье с мертвого тролля.$B$BДокажите, что вы друг Громового Молота.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фраггару Громовой Мантии на Заоблачный пик, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2881,'Ожерелья троллей','Чем больше ожерелий, тем меньше троллей во Внутренних Землях! Вы $Gмолодец:умница;, $N. Так держать!','Вы уже выполнили мое задание, но если вы захотите принести мне еще тролльих ожерелий, то я с радостью приму их. Это поможет вам заслужить хорошее отношение Громового Молота – если вы нам помогаете, то и мы с радостью поможем вам!$B$BПриносите по пять ожерелий, $N.','Вернитесь к Фраггару Громовой Мантии во Внутренние земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелья троллей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чем больше ожерелий, тем меньше троллей во Внутренних Землях! Вы $Gмолодец:умница;, $N. Так держать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы уже выполнили мое задание, но если вы захотите принести мне еще тролльих ожерелий, то я с радостью приму их. Это поможет вам заслужить хорошее отношение Громового Молота – если вы нам помогаете, то и мы с радостью поможем вам!$B$BПриносите по пять ожерелий, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фраггару Громовой Мантии во Внутренние земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2882,'"Золото Куэрго"','На карте изображена южная часть берега, а ниже имеется элегантная подпись...$B$B$BЮжней Шестеренки,$bНа юге от дома$bНайдешь ты флаг, мачту и кости – знакомо?$bКопай прямо там, если смелости хватит –$bЗа все тебе "Злато Куэрго" отплатит. $bПоищешь ты ключ и конечно найдешь,$bНо прежде немало крови прольешь.','Найдите "Золото Куэрго"!','Вернитесь к пиратским сокровищам!..') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Золото Куэрго"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На карте изображена южная часть берега, а ниже имеется элегантная подпись...$B$B$BЮжней Шестеренки,$bНа юге от дома$bНайдешь ты флаг, мачту и кости – знакомо?$bКопай прямо там, если смелости хватит –$bЗа все тебе "Злато Куэрго" отплатит. $bПоищешь ты ключ и конечно найдешь,$bНо прежде немало крови прольешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите "Золото Куэрго"!',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пиратским сокровищам!..',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2902,'Разведка планов Древолапов','Гноллы, конечно, умом не блещут, но в последнее время в их деятельности прослеживаются признаки тщательного планирования. Если бы удалось добыть эти планы, возможно, нам было бы проще понять, отчего они так зашевелились в последнее время.$b$bПрошу тебя, вернись в лагеря Древолапов и попытайся найти что-нибудь похожее на боевые планы. Наверняка у них есть что-то в этом духе: в последнее время они действуют чересчур согласованно. Отыщи эти планы, и возвращайся ко мне.','Найдите гноллские боевые планы в гноллских лагерях к югу от Лагеря Мохаче.','Да, это те самые планы, которые просил отыскать Хадокен Быстрый Странник. Множество стрелок, очевидно, обозначают передвижения войск, однако большая часть этих стрелок направлена не на север, к Лагерю Мохаче, а на юг.$B$BВ углу карты нарисовано нечто вроде крупного насекомого, окруженного разнообразными значками. Судя по всему, гноллов действительно донимают какие-то насекомые...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разведка планов Древолапов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гноллы, конечно, умом не блещут, но в последнее время в их деятельности прослеживаются признаки тщательного планирования. Если бы удалось добыть эти планы, возможно, нам было бы проще понять, отчего они так зашевелились в последнее время.$b$bПрошу тебя, вернись в лагеря Древолапов и попытайся найти что-нибудь похожее на боевые планы. Наверняка у них есть что-то в этом духе: в последнее время они действуют чересчур согласованно. Отыщи эти планы, и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите гноллские боевые планы в гноллских лагерях к югу от Лагеря Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это те самые планы, которые просил отыскать Хадокен Быстрый Странник. Множество стрелок, очевидно, обозначают передвижения войск, однако большая часть этих стрелок направлена не на север, к Лагерю Мохаче, а на юг.$B$BВ углу карты нарисовано нечто вроде крупного насекомого, окруженного разнообразными значками. Судя по всему, гноллов действительно донимают какие-то насекомые...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2903,'Планы битвы','Теперь, когда планы гноллов добыты, вам остается только вернуться с ними в Лагерь Мохаче к Хадокену Быстрому Страннику. Быть может, он или еще кто-нибудь сумеет разобраться, что замышляют гноллы?','Отнесите планы битвы Древолапов Хадокену Быстрому Страннику в Лагерь Мохаче.','О, это именно то, что нам нужно! Я, правда, не мастак разбирать всякие каракули, однако я на своем веку повидал достаточно планов битв, чтобы понять, что творится у гноллов. Похоже, сейчас они ведут войну на два фронта. Один противник – это мы... но, судя по всему, основные их силы брошены на юг.$B$BТут все не так просто! Возможно, пора выяснить, с кем же они воюют.','С возвращением, $N. Ну что, удалось тебе обнаружить какие-нибудь планы?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Планы битвы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда планы гноллов добыты, вам остается только вернуться с ними в Лагерь Мохаче к Хадокену Быстрому Страннику. Быть может, он или еще кто-нибудь сумеет разобраться, что замышляют гноллы?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите планы битвы Древолапов Хадокену Быстрому Страннику в Лагерь Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, это именно то, что нам нужно! Я, правда, не мастак разбирать всякие каракули, однако я на своем веку повидал достаточно планов битв, чтобы понять, что творится у гноллов. Похоже, сейчас они ведут войну на два фронта. Один противник – это мы... но, судя по всему, основные их силы брошены на юг.$B$BТут все не так просто! Возможно, пора выяснить, с кем же они воюют.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С возвращением, $N. Ну что, удалось тебе обнаружить какие-нибудь планы?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2904,'Катавасия','<Керноби стонет> Э-э... Что случилось?$B$BПоследнее, что я помню, это как меня похитили дворфы Черного Железа, избили до полусмерти и бросили сюда, к этим омерзительным троггам.$B$BВытащи меня отсюда, $n!$B$BСделаем так: выведи меня к выходу; если нам удастся выбраться живыми, пойдешь в Пиратскую Бухту и скажешь Скути, что я был в Кабестане и предупредил Оловеня, что дворфы Черного Железа тоже как-то связаны с работой над суперроботом.$B$BИдем!','Отведите Керноби к Часовому ходу. Затем отправляйтесь с донесением к Скути в Пиратскую Бухту.','А? Керноби жив??','Спасение Керноби','Вернитесь к Скути в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Катавасия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Керноби стонет> Э-э... Что случилось?$B$BПоследнее, что я помню, это как меня похитили дворфы Черного Железа, избили до полусмерти и бросили сюда, к этим омерзительным троггам.$B$BВытащи меня отсюда, $n!$B$BСделаем так: выведи меня к выходу; если нам удастся выбраться живыми, пойдешь в Пиратскую Бухту и скажешь Скути, что я был в Кабестане и предупредил Оловеня, что дворфы Черного Железа тоже как-то связаны с работой над суперроботом.$B$BИдем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите Керноби к Часовому ходу. Затем отправляйтесь с донесением к Скути в Пиратскую Бухту.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А? Керноби жив??',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Спасение Керноби',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скути в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2922,'Промыть мозг Техботу','Когда пал наш родной город Гномреган, с Техботом, видимо от расстройства, приключилось короткое замыкание. Бедный мой маленький друг! Он так помогал мне и моим коллегам! В него встроена куча полезных прибамбасов на все случаи жизни, объем памяти просто огромен, но все это теперь совершенно бесполезно – его мозг из позитронного стал негатронным! Все заложенные в него программы теперь работают наоборот. Мой бедный сумасшедший робот теперь бродит по Гномрегану.$B$BМожет, тебе удастся изловить его и извлечь его ядро памяти. Тогда я смогу разобраться в причинах поломки и, возможно, устраню ее.','Принесите ядро памяти Техбота мехмастеру Замыкальцу в Стальгорн.','Ну как, нашел Техбота?','Вернитесь к Мехмастеру Замыкальцу в Город Механиков в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Промыть мозг Техботу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда пал наш родной город Гномреган, с Техботом, видимо от расстройства, приключилось короткое замыкание. Бедный мой маленький друг! Он так помогал мне и моим коллегам! В него встроена куча полезных прибамбасов на все случаи жизни, объем памяти просто огромен, но все это теперь совершенно бесполезно – его мозг из позитронного стал негатронным! Все заложенные в него программы теперь работают наоборот. Мой бедный сумасшедший робот теперь бродит по Гномрегану.$B$BМожет, тебе удастся изловить его и извлечь его ядро памяти. Тогда я смогу разобраться в причинах поломки и, возможно, устраню ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ядро памяти Техбота мехмастеру Замыкальцу в Стальгорн.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, нашел Техбота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мехмастеру Замыкальцу в Город Механиков в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2923,'Мехмастер Замыкалец','Мехмастер Замыкалец крайне опечален судьбой своего творения – Техбота. Помнится, Техбот был когда-то для гномов весьма полезным инструментом, однако теперь Большая Искра говорит, что он сломан.$B$BОчень жаль. Но быть может, его еще возможно починить.$B$BПоговори об этом с Мехмастером Замыкальцем в Городе Механиков в Стальгорне. Он будет рад любой помощи.','Поговорите с механомастером Большой Искрой.','Да, это правда. Мой Техбот совсем вышел из строя! Ты сможешь мне помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мехмастер Замыкалец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мехмастер Замыкалец крайне опечален судьбой своего творения – Техбота. Помнится, Техбот был когда-то для гномов весьма полезным инструментом, однако теперь Большая Искра говорит, что он сломан.$B$BОчень жаль. Но быть может, его еще возможно починить.$B$BПоговори об этом с Мехмастером Замыкальцем в Городе Механиков в Стальгорне. Он будет рад любой помощи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с механомастером Большой Искрой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это правда. Мой Техбот совсем вышел из строя! Ты сможешь мне помочь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2924,'Базовый элемент','Базовый элемент – практически универсальная деталь, широко используемая механиками и кузнецами Гномрегана. Однако в спешке покидая город, никто из нас не догадался прихватить с собой эти детали. Мне просто необходимо пополнить мои запасы!$B$BПожалуйста, отправляйся в Гномреган и добудь мне побольше этих бесценных артефактов. Ты найдешь их в подземельях нашего города – обычно они хранятся в контейнерах-экстраполяторах.$B$BУмоляю тебя, поторопись!','Принесите 12 базовых элементов Клацморту Гайкокруту в Стальгорн.','Ну как, нашел механизмы?','Вернитесь к Клацморту Гайкокруту в Город Механиков в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Базовый элемент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Базовый элемент – практически универсальная деталь, широко используемая механиками и кузнецами Гномрегана. Однако в спешке покидая город, никто из нас не догадался прихватить с собой эти детали. Мне просто необходимо пополнить мои запасы!$B$BПожалуйста, отправляйся в Гномреган и добудь мне побольше этих бесценных артефактов. Ты найдешь их в подземельях нашего города – обычно они хранятся в контейнерах-экстраполяторах.$B$BУмоляю тебя, поторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 базовых элементов Клацморту Гайкокруту в Стальгорн.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, нашел механизмы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Клацморту Гайкокруту в Город Механиков в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2925,'Базовые элементы Клацморта','Мой друг, гном Клацморт Гайкокрут из Стальгорна, прислал мне письмо, в котором сообщает, что ему необходима помощь. Ему нужно отправиться в Гномреган, некогда величайший город гномов, который был осквернен, и теперь его населяют лишь безумные гномы и их жуткие изобретения.$B$BЯ не могу покинуть Дарнас, но душа моя болит за друга. Если ты сможешь помочь ему вместо меня, благодарности моей не будет предела.$B$BТы найдешь Клацморта в Городе Механиков в Стальгорне.','Поговорите с Клацмортом Гайкокрутом в Стальгорне.','Да! Да! Мне очень нужна помощь в Гномрегане! И |3-6($C) вроде тебя как раз подойдет!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Базовые элементы Клацморта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой друг, гном Клацморт Гайкокрут из Стальгорна, прислал мне письмо, в котором сообщает, что ему необходима помощь. Ему нужно отправиться в Гномреган, некогда величайший город гномов, который был осквернен, и теперь его населяют лишь безумные гномы и их жуткие изобретения.$B$BЯ не могу покинуть Дарнас, но душа моя болит за друга. Если ты сможешь помочь ему вместо меня, благодарности моей не будет предела.$B$BТы найдешь Клацморта в Городе Механиков в Стальгорне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Клацмортом Гайкокрутом в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да! Да! Мне очень нужна помощь в Гномрегане! И |3-6($C) вроде тебя как раз подойдет!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2926,'Новая формула','С самого дня нашего бегства из города Гноарн только о том и думает, как выставить троггов из Гномрегана и очистить город от заражения.$B$BУ нас с Раззлом есть некоторые идеи на этот счет, однако похоже, что воплотить их в жизнь сможет только настоящий безумец. Мы еще не знаем, сработает ли наш замысел – надо все как следует проверить! Для этого нам потребуются радиоактивные осадки, оставляемые облученными троггами в Гномрегане. Это зеленая светящаяся субстанция. Наполни ею эту склянку и принеси мне!','Соберите радиоактивный осадок, оставляемый облученными захватчиками и облученными погромщиками в пустую освинцованную склянку для проб. Принесите наполненную склянку Оззи Триггервольту в Каранос.','Прекрасно! Теперь пришла пора опробовать нашу новую формулу. Если этот метод сработает, я не только смогу вылечить этого несчастного лепрогнома, но и вернуть свою утраченную шевелюру! Ну-ка, отойди в сторонку!','Разве не понятно?! Мы пытаемся спасти целый народ! Нам необходимо изучить радиоактивный осадок! Ради будущего всех гномов!','Вернитесь к Оззи Триггервольту в Каранос, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая формула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С самого дня нашего бегства из города Гноарн только о том и думает, как выставить троггов из Гномрегана и очистить город от заражения.$B$BУ нас с Раззлом есть некоторые идеи на этот счет, однако похоже, что воплотить их в жизнь сможет только настоящий безумец. Мы еще не знаем, сработает ли наш замысел – надо все как следует проверить! Для этого нам потребуются радиоактивные осадки, оставляемые облученными троггами в Гномрегане. Это зеленая светящаяся субстанция. Наполни ею эту склянку и принеси мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите радиоактивный осадок, оставляемый облученными захватчиками и облученными погромщиками в пустую освинцованную склянку для проб. Принесите наполненную склянку Оззи Триггервольту в Каранос.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Теперь пришла пора опробовать нашу новую формулу. Если этот метод сработает, я не только смогу вылечить этого несчастного лепрогнома, но и вернуть свою утраченную шевелюру! Ну-ка, отойди в сторонку!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разве не понятно?! Мы пытаемся спасти целый народ! Нам необходимо изучить радиоактивный осадок! Ради будущего всех гномов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Оззи Триггервольту в Каранос, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2927,'На другой день','Вы ведь не думаете, что я всегда был лысым? Нет, $Gсударь:сударыня;! Эту трагическую утрату волос вызвала утечка радиации в Гномрегане. До тех пор я был единственным кудрявым гномом во всем Азероте.$B$B*Гноарн потрясает в воздухе кулаком.*$B$BБудь прокляты эти проклятые грязные трогги, будь они все прокляты!!!$B$BМожет, еще не поздно, $n. Мы еще можем исправить дело – я хочу сказать, спасти город! Поговорите с Оззи Триггервольтом в Караносе. Они со своим партнером Раззлом как раз пытаются решить эту проблему.','Поговорите с Оззи Триггервольтом в Караносе, что в Дун Мороге.','Я думал, что утрата волос нашим выдающимся главой убьет его, так нет, выжил!$B$BЯ стоял рядом с ним, когда тот схватил дозу. И эти замечательные коричневые локоны посыпались на пол прядями! Клочьями! Ужас произошедшего только усилился, когда у Гроана крыша поехала! Да! Гроан, не веря глазам своим, коснулся лысой головы, и во взгляде его загорелась месть, $n! И тогда он обрушился на троггов!$B$B Оззи ежится. ') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На другой день',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы ведь не думаете, что я всегда был лысым? Нет, $Gсударь:сударыня;! Эту трагическую утрату волос вызвала утечка радиации в Гномрегане. До тех пор я был единственным кудрявым гномом во всем Азероте.$B$B*Гноарн потрясает в воздухе кулаком.*$B$BБудь прокляты эти проклятые грязные трогги, будь они все прокляты!!!$B$BМожет, еще не поздно, $n. Мы еще можем исправить дело – я хочу сказать, спасти город! Поговорите с Оззи Триггервольтом в Караносе. Они со своим партнером Раззлом как раз пытаются решить эту проблему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Оззи Триггервольтом в Караносе, что в Дун Мороге.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я думал, что утрата волос нашим выдающимся главой убьет его, так нет, выжил!$B$BЯ стоял рядом с ним, когда тот схватил дозу. И эти замечательные коричневые локоны посыпались на пол прядями! Клочьями! Ужас произошедшего только усилился, когда у Гроана крыша поехала! Да! Гроан, не веря глазам своим, коснулся лысой головы, и во взгляде его загорелась месть, $n! И тогда он обрушился на троггов!$B$B Оззи ежится. ',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2928,'Сооружение автогиробуророек','Это ужасно, $n. У нас, видно, не хватит запчастей, чтобы собрать всю партию автогиробуророек, которую пора отправить в Дун Морог.$b$bЧто нам точно нужно – так это детали, $n. И для добычи этих деталей не найти места лучше, чем Гномреган! Я слышала, что роботы и механизмы, оставшиеся там, бродят по городу как овцы на вольном пастбище.$b$bЯ хочу от вас, чтобы вы отправились в Гномреган и распотрошили этих роботов на запчасти. Двух дюжин деталей должно хватить.','Принесите Шони в Штормград 24 горсти механических внутренностей роботов.','Если бы речь шла о гонках, вы бы уже проиграли.','Вернитесь к Шони Молшунье в Квартал Дворфов Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сооружение автогиробуророек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это ужасно, $n. У нас, видно, не хватит запчастей, чтобы собрать всю партию автогиробуророек, которую пора отправить в Дун Морог.$b$bЧто нам точно нужно – так это детали, $n. И для добычи этих деталей не найти места лучше, чем Гномреган! Я слышала, что роботы и механизмы, оставшиеся там, бродят по городу как овцы на вольном пастбище.$b$bЯ хочу от вас, чтобы вы отправились в Гномреган и распотрошили этих роботов на запчасти. Двух дюжин деталей должно хватить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Шони в Штормград 24 горсти механических внутренностей роботов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если бы речь шла о гонках, вы бы уже проиграли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шони Молшунье в Квартал Дворфов Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2929,'Великое предательство','Я доверял Термоштепселю, |3-6($r). Никогда я не думал, что он предаст меня и весь гномий род. И ради чего? Ради власти? Богатства? Все это он и так со временем получил бы. Теперь мы лишились родного дома, а этот безумец остался там править. Король без королевства...$B$BМы вернем Гномреган, $n. Мы не остановимся, пока город снова не станет нашим! Если ты хочешь присоединиться к нашей борьбе, выполни совсем простое поручение – убей предателя. Уничтожь Анжинера Термоштепселя.','Отправляйтесь в Гномреган и убейте Анжинера Термоштепселя. Вернитесь к главному механику Меггакруту.','Я рад, что последнее, что он видел в своей жизни, была твоя стопа, попирающая его преступную голову, |3-6($r)! Теперь, когда Термоштепсель мертв, наши планы по возвращению Гномрегана на шаг приблизились к осуществлению!','Задание выполнено? Он просил о снисхождении? Пощады??','Вернитесь к главному механику Меггакруту в Новый Город Механиков в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великое предательство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я доверял Термоштепселю, |3-6($r). Никогда я не думал, что он предаст меня и весь гномий род. И ради чего? Ради власти? Богатства? Все это он и так со временем получил бы. Теперь мы лишились родного дома, а этот безумец остался там править. Король без королевства...$B$BМы вернем Гномреган, $n. Мы не остановимся, пока город снова не станет нашим! Если ты хочешь присоединиться к нашей борьбе, выполни совсем простое поручение – убей предателя. Уничтожь Анжинера Термоштепселя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Гномреган и убейте Анжинера Термоштепселя. Вернитесь к главному механику Меггакруту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что последнее, что он видел в своей жизни, была твоя стопа, попирающая его преступную голову, |3-6($r)! Теперь, когда Термоштепсель мертв, наши планы по возвращению Гномрегана на шаг приблизились к осуществлению!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Задание выполнено? Он просил о снисхождении? Пощады??',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному механику Меггакруту в Новый Город Механиков в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2930,'Спасение данных','Когда мы бежали из Гномрегана, то оставили там столько данных! Жизненно важных данных!$B$BМне нужны данные с радужной перфокарты чрезвычайно секретного терминала матричного перфографа 3005-D, что находится в глубинах Гномрегана. Тебе нужно добраться до терминала, но сначала надо получить допуск... а для этого надо добраться до терминалов низшего уровня защиты – моделей -A, -B и -C. А для ЭТОГО тебе понадобятся перфокарты допуска, начиная с белой... а все перфокарты остались в городе.$B$BЭто же катастрофа! Ты можешь помочь нам?','Принесите радужную перфокарту главному механику Чугунотрубзу в Стальгорн.','Вы принесли призматическую перфокарту?','Вернитесь к главному механику Чугонотрубзу в Город Механиков в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение данных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда мы бежали из Гномрегана, то оставили там столько данных! Жизненно важных данных!$B$BМне нужны данные с радужной перфокарты чрезвычайно секретного терминала матричного перфографа 3005-D, что находится в глубинах Гномрегана. Тебе нужно добраться до терминала, но сначала надо получить допуск... а для этого надо добраться до терминалов низшего уровня защиты – моделей -A, -B и -C. А для ЭТОГО тебе понадобятся перфокарты допуска, начиная с белой... а все перфокарты остались в городе.$B$BЭто же катастрофа! Ты можешь помочь нам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите радужную перфокарту главному механику Чугунотрубзу в Стальгорн.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы принесли призматическую перфокарту?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному механику Чугонотрубзу в Город Механиков в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2931,'Поручение Чугонотрубза','Стальгорнский главный механик Чугунотрубз ищет искателей приключений! Он собирает отряд для проникновения в Гномреган с целью возвращения данных чрезвычайной важности и секретности.$B$BХотя Чугунотрубз и не состоит в Просвещенной ассамблее чарологии, алхимии и инженерных наук, подобно мне, но он гном толковый, и если он считает это дело важным, то, по моим подсчетам, оно с вероятностью 84 процента важное!$B$BШансы хорошие!','Поговорите с главным механиком Чугунотрубзом в Стальгорне.','Я готовлю миссию в Гномреган для возвращения важных данных. Если вы пришли помочь, то слушайте!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поручение Чугонотрубза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стальгорнский главный механик Чугунотрубз ищет искателей приключений! Он собирает отряд для проникновения в Гномреган с целью возвращения данных чрезвычайной важности и секретности.$B$BХотя Чугунотрубз и не состоит в Просвещенной ассамблее чарологии, алхимии и инженерных наук, подобно мне, но он гном толковый, и если он считает это дело важным, то, по моим подсчетам, оно с вероятностью 84 процента важное!$B$BШансы хорошие!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с главным механиком Чугунотрубзом в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я готовлю миссию в Гномреган для возвращения важных данных. Если вы пришли помочь, то слушайте!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2932,'Предупреждение','Когда-то тролли из племени Сухокожих были на стороне Орды, но потом они предали Тралла... и это не должно сойти им с рук!$B$BВот, возьмите мою пику и отправляйтесь во Внутренние земли, это далеко на севере. Сначала найдите Мельницу Таррен – поселение наших союзников, Отрекшихся, а оттуда идите на северо-восток.$B$BВо Внутренних землях убейте 20 троллей из племени Сухокожих, насадите их черепа на мою пику и воткните ее в землю в одной из их деревенек – Хири\'вата или Зун\'вата.$B$BПусть видят, что за свои действия надо отвечать!','Соберите черепа троллей из племени Сухокожих и насадите их на пику Нимбойи, после чего установите пику с тролльими черепами в центре одной из их деревень во Внутренних землях и возвращайтесь к Нимбойе в Тернистую долину.','До меня дошли вести о ваших подвигах. Это жестокий поступок, но почетный. Надеюсь, тролли Сухокожих внимут нашему предупреждению.','Вы не выполнили мою задачу, $N.','Оставить предупреждение','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупреждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда-то тролли из племени Сухокожих были на стороне Орды, но потом они предали Тралла... и это не должно сойти им с рук!$B$BВот, возьмите мою пику и отправляйтесь во Внутренние земли, это далеко на севере. Сначала найдите Мельницу Таррен – поселение наших союзников, Отрекшихся, а оттуда идите на северо-восток.$B$BВо Внутренних землях убейте 20 троллей из племени Сухокожих, насадите их черепа на мою пику и воткните ее в землю в одной из их деревенек – Хири\'вата или Зун\'вата.$B$BПусть видят, что за свои действия надо отвечать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите черепа троллей из племени Сухокожих и насадите их на пику Нимбойи, после чего установите пику с тролльими черепами в центре одной из их деревень во Внутренних землях и возвращайтесь к Нимбойе в Тернистую долину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','До меня дошли вести о ваших подвигах. Это жестокий поступок, но почетный. Надеюсь, тролли Сухокожих внимут нашему предупреждению.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы не выполнили мою задачу, $N.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Оставить предупреждение',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нимбойе в лагерь Гром\'гол, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2933,'Бутыли с ядом','В этих бутылках содержится очень сильный зеленый яд.$B$BСудя по количеству бутылок в деревне, тролли Сухокожих очень дорожат им. Возможно, аптекарь на Мельнице Таррен тоже заинтересуется этим ядом.','Принесите флакон с ядом аптекарю на Мельницу Таррен.','О, что это? Похоже на яд... яд какого-то паукообразного, да? Где же вы его взяли?','Приветствую, $Gмилый:милая; $C! За весь этот длинный день у меня не было ни одного удачного эксперимента. Надеюсь услышать от вас хорошие новости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бутыли с ядом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этих бутылках содержится очень сильный зеленый яд.$B$BСудя по количеству бутылок в деревне, тролли Сухокожих очень дорожат им. Возможно, аптекарь на Мельнице Таррен тоже заинтересуется этим ядом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите флакон с ядом аптекарю на Мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, что это? Похоже на яд... яд какого-то паукообразного, да? Где же вы его взяли?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $Gмилый:милая; $C! За весь этот длинный день у меня не было ни одного удачного эксперимента. Надеюсь услышать от вас хорошие новости.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2934,'Неповрежденная ядовитая железа','Мне нужен свежий образец того яда, что вы приносили мне. Пауки, с которых он был собран, водятся во Внутренних землях – охотьтесь на них, пока вам не удастся добыть неповрежденную ядовитую железу, а потом принесите ее мне. Больше всего пауков живет в тролльем городе Шадра\'Алоре.$B$BИ не задерживайтесь, $n – ядовитая железа нужна мне предельно свежей.','Принесите неповрежденную ядовитую железу аптекарю Лидону на Мельницу Таррен.','О, замечательно! Яд свежий и, я уверен, чрезвычайно смертоносный! Спасибо!','Ну как, удалось добыть неповрежденную ядовитую железу, $N? Мне не терпится начать эксперименты с этим ядом, и у меня есть для этого целый выводок маленьких миленьких животных!','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неповрежденная ядовитая железа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужен свежий образец того яда, что вы приносили мне. Пауки, с которых он был собран, водятся во Внутренних землях – охотьтесь на них, пока вам не удастся добыть неповрежденную ядовитую железу, а потом принесите ее мне. Больше всего пауков живет в тролльем городе Шадра\'Алоре.$B$BИ не задерживайтесь, $n – ядовитая железа нужна мне предельно свежей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите неповрежденную ядовитую железу аптекарю Лидону на Мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, замечательно! Яд свежий и, я уверен, чрезвычайно смертоносный! Спасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось добыть неповрежденную ядовитую железу, $N? Мне не терпится начать эксперименты с этим ядом, и у меня есть для этого целый выводок маленьких миленьких животных!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2935,'Разговор с мастером Гадрином','Яд этих пауков не так силен, как тот, что вы приносили раньше. Наверное, тот яд был от другого паука.$B$BМне нужен свежий образец того яда, а чтобы узнать, откуда он, нужно поговорить с троллем, который много знает о племени Сухокожих – это мастер Гадрин в деревне Сен\'джин. Отправляйтесь в Дуротар и поговорите с ним. Он вполне может знать, откуда тролли племени Сухокожих берут этот яд.','Поговорите с мастером Гадрином в деревне Сен\'джин.','А, так вам нужен свежий яд пауков Сухокожих? Ну что ж, присядьте... вам не понравится то, что я сейчас скажу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с мастером Гадрином',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яд этих пауков не так силен, как тот, что вы приносили раньше. Наверное, тот яд был от другого паука.$B$BМне нужен свежий образец того яда, а чтобы узнать, откуда он, нужно поговорить с троллем, который много знает о племени Сухокожих – это мастер Гадрин в деревне Сен\'джин. Отправляйтесь в Дуротар и поговорите с ним. Он вполне может знать, откуда тролли племени Сухокожих берут этот яд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером Гадрином в деревне Сен\'джин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, так вам нужен свежий яд пауков Сухокожих? Ну что ж, присядьте... вам не понравится то, что я сейчас скажу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2936,'Паучья богиня','Тролли Сухокожих поклоняются паучьей богине, и самый сильный яд берут у нее. Так что если вам нужен этот яд, нужно будет призвать ее.$B$BДля этого требуется знать ее истинное имя – оно начертано на табличке в тролльем городе Зул\'Фарраке, это в Танарисе. Табличка находится у гробницы, которую охраняет Тека Мученик.$B$BСразитесь с Текой и прочитайте на табличке имя паучьей богини, а потом возвращайтесь ко мне.','Прочитайте надписи на табличке Теки, узнайте имя паучьей богини, которой поклоняются тролли Сухокожих, а потом возвращайтесь к мастеру Гадрину.','Элорта но Шадра... Произносите это имя лишь шепотом, потому что один его звук повергает духов в смятение.$B$BЯ напишу его на бумаге и сотворю для вас заклинание призыва.','Вы знаете имя паучьего бога?','Узнать имя паучьей богини','Вернитесь к мастеру Гадрину в деревню Сен\'джин, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Паучья богиня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли Сухокожих поклоняются паучьей богине, и самый сильный яд берут у нее. Так что если вам нужен этот яд, нужно будет призвать ее.$B$BДля этого требуется знать ее истинное имя – оно начертано на табличке в тролльем городе Зул\'Фарраке, это в Танарисе. Табличка находится у гробницы, которую охраняет Тека Мученик.$B$BСразитесь с Текой и прочитайте на табличке имя паучьей богини, а потом возвращайтесь ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте надписи на табличке Теки, узнайте имя паучьей богини, которой поклоняются тролли Сухокожих, а потом возвращайтесь к мастеру Гадрину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Элорта но Шадра... Произносите это имя лишь шепотом, потому что один его звук повергает духов в смятение.$B$BЯ напишу его на бумаге и сотворю для вас заклинание призыва.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы знаете имя паучьего бога?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Узнать имя паучьей богини',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Гадрину в деревню Сен\'джин, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2937,'Призыв Шадры','Возьмите этот пергамент и прочитайте написанное на нем заклинание около алтаря Шадра\'Алора – это в самом сердце владений племени Сухокожих. Это заклинание призовет Шадру – паучью богиню.','Убейте Шадру у алтаря Шадра\'Алора и принесите ее яд аптекарю Лидону на Мельницу Таррен.','Лучше и быть не могло!','Достали яд?','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв Шадры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьмите этот пергамент и прочитайте написанное на нем заклинание около алтаря Шадра\'Алора – это в самом сердце владений племени Сухокожих. Это заклинание призовет Шадру – паучью богиню.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Шадру у алтаря Шадра\'Алора и принесите ее яд аптекарю Лидону на Мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лучше и быть не могло!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Достали яд?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лидону на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2938,'Яд в Подгород','Этот яд, который вы нашли у троллей Сухокожих, просто поразителен! Одной капли хватило, чтобы убить две дюжины кроликов. Ну, конечно, эти кролики были такие маленькие, что все уместились у меня на ладони, так что и организмы их особо не могли сопротивляться токсину... Но, тем не менее, яд просто убойный!$B$BЯ хотел бы отправить образец моему коллеге, аптекарю Фаранеллу в Подгород. Наверняка он захочет испытать его самостоятельно.','Отнесите сверток опытному аптекарю Фаранеллу в Подгород.','Очень хорошо. Лидон говорил, что яд в этом свертке – самый смертоносный из тех, что ему встречались, и теперь он в срочном порядке ищет способ его применения.$B$BНадеюсь, применений ему найдется немало.$B$BСпасибо, $N. Вы оказали Королевскому Фармацевтическому Обществу неоценимую услугу.','Мне сказали, что вы скоро будете, $N. Принесли мне письмо?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яд в Подгород',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот яд, который вы нашли у троллей Сухокожих, просто поразителен! Одной капли хватило, чтобы убить две дюжины кроликов. Ну, конечно, эти кролики были такие маленькие, что все уместились у меня на ладони, так что и организмы их особо не могли сопротивляться токсину... Но, тем не менее, яд просто убойный!$B$BЯ хотел бы отправить образец моему коллеге, аптекарю Фаранеллу в Подгород. Наверняка он захочет испытать его самостоятельно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сверток опытному аптекарю Фаранеллу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Лидон говорил, что яд в этом свертке – самый смертоносный из тех, что ему встречались, и теперь он в срочном порядке ищет способ его применения.$B$BНадеюсь, применений ему найдется немало.$B$BСпасибо, $N. Вы оказали Королевскому Фармацевтическому Обществу неоценимую услугу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне сказали, что вы скоро будете, $N. Принесли мне письмо?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2939,'В поисках знаний','Руины Фераласа могут быть очень опасны, но зато они способны немало рассказать нам о том, что здесь произошло.$b$bВот, к примеру, несколько дней тому назад, копаясь в развалинах к югу отсюда, я обнаружил одну вещицу. На вид – обычный посох, но меня не покидает ощущение, что посох этот не простой. Мы с Ангелас уже давно корпим над книгами, но так ничего о нем и не узнали.$b$bУ меня есть коллега в Дарнасе, которая, возможно, сумеет сообщить нам что-нибудь полезное. $n, быть может, вы сходите к ней и попросите нам помочь?','Поговорите с Дарин Добрый Ветер в деревне Рут\'теран.','А, так ты от Трояса Лунного Бриза?$B$B*Бормочет себе под нос*$B$BВот вечно он меня донимает: ему все время кажется, что он обнаружил что-то чрезвычайно важное…$B$BПослушай, $N, я буду говорить откровенно. Троясу каждый раз кажется, будто он нашел в этих развалинах невесть какую диковинку. На самом же деле все, что там было ценного, давно уже растащили огры либо гарпии.$B$BТы, конечно, можешь порыться в библиотеке, но не думаю, что ты сумеешь найти что-то, что тебе пригодится.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках знаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Руины Фераласа могут быть очень опасны, но зато они способны немало рассказать нам о том, что здесь произошло.$b$bВот, к примеру, несколько дней тому назад, копаясь в развалинах к югу отсюда, я обнаружил одну вещицу. На вид – обычный посох, но меня не покидает ощущение, что посох этот не простой. Мы с Ангелас уже давно корпим над книгами, но так ничего о нем и не узнали.$b$bУ меня есть коллега в Дарнасе, которая, возможно, сумеет сообщить нам что-нибудь полезное. $n, быть может, вы сходите к ней и попросите нам помочь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дарин Добрый Ветер в деревне Рут\'теран.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, так ты от Трояса Лунного Бриза?$B$B*Бормочет себе под нос*$B$BВот вечно он меня донимает: ему все время кажется, что он обнаружил что-то чрезвычайно важное…$B$BПослушай, $N, я буду говорить откровенно. Троясу каждый раз кажется, будто он нашел в этих развалинах невесть какую диковинку. На самом же деле все, что там было ценного, давно уже растащили огры либо гарпии.$B$BТы, конечно, можешь порыться в библиотеке, но не думаю, что ты сумеешь найти что-то, что тебе пригодится.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2940,'"Фералас: История"','Книга выглядит так, как будто ее не открывали годами. Переплет потерт и запылен, страницы пожелтели... Тем не менее, проглядев ее, вы убеждаетесь, что это именно то, что нужно было Троясу.$b$bВы берете книгу, но соображаете, что неплохо было бы спросить разрешения прежде, чем ее уносить.','Попросите Дарин Добрый Ветер одолжить вам книгу.','Ты хочешь взять "Историю Фераласа"?$B$BДай подумать…$B$BХорошо, я разрешу тебе позаимствовать эту книгу, $N, если ты сначала окажешь мне одну услугу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Фералас: История"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Книга выглядит так, как будто ее не открывали годами. Переплет потерт и запылен, страницы пожелтели... Тем не менее, проглядев ее, вы убеждаетесь, что это именно то, что нужно было Троясу.$b$bВы берете книгу, но соображаете, что неплохо было бы спросить разрешения прежде, чем ее уносить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попросите Дарин Добрый Ветер одолжить вам книгу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хочешь взять "Историю Фераласа"?$B$BДай подумать…$B$BХорошо, я разрешу тебе позаимствовать эту книгу, $N, если ты сначала окажешь мне одну услугу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2941,'В обмен на книгу','Я в свое время занималась самыми разными предметами, а вот сейчас меня очень интересуют хрустогрызы, которые обитают на побережье Внутренних земель. Мне особенно хочется посмотреть на одного из них: гигантскую черепаху, которую зовут Гаммерита. Я бы отправилась туда сама, но не могу отвлекаться от своих исследований. Добудь мне хотя бы изображение, ладно?$b$bОтнеси это письмо Кургль Поскакушке, которая живет в Танарисе. Она изобрела для меня машинку, которая может делать картинки. Кажется, Гурдл называет это "снимками"...','Отнесите письмо Кургль Поскакушке в Танарис.','А, ты $Gодин:одна; из $Gстудентов:студенток; Дарин? Она очень сведущий историк, $N. Тебе повезло, что ты занимаешься под ее руководством.$B$BНу, давай я покажу тебе свой супер-хвататель. Он тебе понравится!','Письмо – мне?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В обмен на книгу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я в свое время занималась самыми разными предметами, а вот сейчас меня очень интересуют хрустогрызы, которые обитают на побережье Внутренних земель. Мне особенно хочется посмотреть на одного из них: гигантскую черепаху, которую зовут Гаммерита. Я бы отправилась туда сама, но не могу отвлекаться от своих исследований. Добудь мне хотя бы изображение, ладно?$b$bОтнеси это письмо Кургль Поскакушке, которая живет в Танарисе. Она изобрела для меня машинку, которая может делать картинки. Кажется, Гурдл называет это "снимками"...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо Кургль Поскакушке в Танарис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, ты $Gодин:одна; из $Gстудентов:студенток; Дарин? Она очень сведущий историк, $N. Тебе повезло, что ты занимаешься под ее руководством.$B$BНу, давай я покажу тебе свой супер-хвататель. Он тебе понравится!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Письмо – мне?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2942,'Завтрашний камень','Как только артефакт извлечен из Монолита, вы ощущаете, что энергия посоха Равноденствия идет на убыль.','Верните искрящийся камень и посох Равноденствия Троясу Лунному Бризу в Крепость Оперенной Луны.','Я с самого вашего ухода не отрывался от книги, $N. Так вот: добытый вами камень называется Завтрашний камень. Для чего он нужен, я пока точно не знаю, однако понятно, что пустяковую вещь так прятать не стали бы.$B$BЯ буду продолжать свои исследования. Надеюсь, что я и в будущем смогу на вас рассчитывать, $N. Спасибо вам за все!','Я рад, что вы вернулись, $N! Ну что, удалось вам что-нибудь найти?','Вернитесь к Троясу Лунному Бризу в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завтрашний камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только артефакт извлечен из Монолита, вы ощущаете, что энергия посоха Равноденствия идет на убыль.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните искрящийся камень и посох Равноденствия Троясу Лунному Бризу в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я с самого вашего ухода не отрывался от книги, $N. Так вот: добытый вами камень называется Завтрашний камень. Для чего он нужен, я пока точно не знаю, однако понятно, что пустяковую вещь так прятать не стали бы.$B$BЯ буду продолжать свои исследования. Надеюсь, что я и в будущем смогу на вас рассчитывать, $N. Спасибо вам за все!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я рад, что вы вернулись, $N! Ну что, удалось вам что-нибудь найти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Троясу Лунному Бризу в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2943,'Возвращение к Троясу','Вот книга, $n. Пожалуйста, обращайся с ней бережно!$b$bНу, ступай. Наверно, Трояс тебя уже заждался.','Доставьте книгу Троясу Лунному Бризу в Крепость Оперенной Луны.','Книга у вас! Чудесно!','А, $N! Ну что, вы побывали в Дарнассе?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Троясу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот книга, $n. Пожалуйста, обращайся с ней бережно!$b$bНу, ступай. Наверно, Трояс тебя уже заждался.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте книгу Троясу Лунному Бризу в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Книга у вас! Чудесно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, $N! Ну что, вы побывали в Дарнассе?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2944,'Суперщелк FX','Ты $gпервый:первая;, кто увидит мое новое изобретение – "Суперщелк FX"! Тебе нужно только навести его на предмет, который ты хочешь запечатлеть, и нажать на кнопку!$b$bКак там звать ту черепашку из Внутренних земель, которую ты ищешь? Гаммерита? На вот, бери и снимай. Я уверена, что Дарин будет в восторге от снимка.$b$bУдачно пощелкать!','Сделайте снимок Гаммериты с помощью "Суперщелк FX" и вернитесь к Дарин Добрый Ветер в деревне Рут\'теран.','О да! Изобретение Гурдл оправдало все мои ожидания!$B$BТы только не зазнавайся, $N, но имей в виду, что я тобой довольна.$B$BТак, где же я оставила эту книгу...','А, $N, вот наконец и ты! У тебя с собой прибор, который изготовила для меня Гурдл? Отлично!','Вернитесь к Дарин Доброму Ветру в деревню Рут\'теран, что в Тельдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суперщелк FX',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпервый:первая;, кто увидит мое новое изобретение – "Суперщелк FX"! Тебе нужно только навести его на предмет, который ты хочешь запечатлеть, и нажать на кнопку!$b$bКак там звать ту черепашку из Внутренних земель, которую ты ищешь? Гаммерита? На вот, бери и снимай. Я уверена, что Дарин будет в восторге от снимка.$b$bУдачно пощелкать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сделайте снимок Гаммериты с помощью "Суперщелк FX" и вернитесь к Дарин Добрый Ветер в деревне Рут\'теран.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да! Изобретение Гурдл оправдало все мои ожидания!$B$BТы только не зазнавайся, $N, но имей в виду, что я тобой довольна.$B$BТак, где же я оставила эту книгу...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, $N, вот наконец и ты! У тебя с собой прибор, который изготовила для меня Гурдл? Отлично!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дарин Доброму Ветру в деревню Рут\'теран, что в Тельдрассиле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2945,'Покрытое грязью кольцо','С тела одного из дворфов Черного Железа вы сняли предмет, напоминающий кольцо. Сложно сказать, что это за кольцо, поскольку оно покрыто толстым слоем окаменевшей грязи. Носить его едва ли возможно. Однако вы уверены, что под слоем грязи скрывается драгоценный металл, а может, еще и самоцвет.$B$BПожалуй, стоит попытаться отчистить всю эту грязь.','Придумайте, как отчистить кольцо, покрытое грязью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покрытое грязью кольцо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тела одного из дворфов Черного Железа вы сняли предмет, напоминающий кольцо. Сложно сказать, что это за кольцо, поскольку оно покрыто толстым слоем окаменевшей грязи. Носить его едва ли возможно. Однако вы уверены, что под слоем грязи скрывается драгоценный металл, а может, еще и самоцвет.$B$BПожалуй, стоит попытаться отчистить всю эту грязь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Придумайте, как отчистить кольцо, покрытое грязью.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2946,'Посмотрим, что будет дальше','Мы хотим, чтобы вы доставили диски, обнаруженные вами, к запечатанным воротам Ульдума. Мы... мы не знаем, что с вами там может случиться.$B$BДа, мы знаем, что звучит рискованно. Но может ведь и ничего не случиться? Может, вам придется что-то с этими дисками сделать. Возможно, эти диски откроют ворота. Не бойтесь экспериментировать и будьте готовы ко всему.$B$BКогда справитесь с заданием, возвращайтесь в Стальгорн. Нам будет что проанализировать!','Принесите миниатюрные платиновые диски к воротам Ульдума в Танарисе и проверьте, имеют ли диски отношение к воротам.','Когда вы прикасаетесь к постаменту, ульдаманские диски в вашем заплечном мешке начинают гудеть и светиться. Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража.\n\n\\"Приветствую вас. Я – страж входа. Среди дисков доступа не хватает Ульдумских пластин. Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа. Благодарю за внимание\\".','Какой знакомый постамент. Возможно, он тут неспроста...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посмотрим, что будет дальше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы хотим, чтобы вы доставили диски, обнаруженные вами, к запечатанным воротам Ульдума. Мы... мы не знаем, что с вами там может случиться.$B$BДа, мы знаем, что звучит рискованно. Но может ведь и ничего не случиться? Может, вам придется что-то с этими дисками сделать. Возможно, эти диски откроют ворота. Не бойтесь экспериментировать и будьте готовы ко всему.$B$BКогда справитесь с заданием, возвращайтесь в Стальгорн. Нам будет что проанализировать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите миниатюрные платиновые диски к воротам Ульдума в Танарисе и проверьте, имеют ли диски отношение к воротам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда вы прикасаетесь к постаменту, ульдаманские диски в вашем заплечном мешке начинают гудеть и светиться. Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража.\n\n\\"Приветствую вас. Я – страж входа. Среди дисков доступа не хватает Ульдумских пластин. Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа. Благодарю за внимание\\".',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какой знакомый постамент. Возможно, он тут неспроста...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2947,'Возвращение кольца','Открыв коробку, вы видите именно то, что и предполагали – сияющее кольцо! Вы чувствуете исходящие от него волны магической силы.$B$BНа внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Стальгорна, а рядом с ним выгравированы инициалы: "ТдК". Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира... Оставить кольцо себе или вернуть владельцу... Непростое решение!','Вы можете оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение кольца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Открыв коробку, вы видите именно то, что и предполагали – сияющее кольцо! Вы чувствуете исходящие от него волны магической силы.$B$BНа внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Стальгорна, а рядом с ним выгравированы инициалы: "ТдК". Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира... Оставить кольцо себе или вернуть владельцу... Непростое решение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вы можете оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (2948,'Гномское усовершенствование','Слушайте $n, конечно, это ваше кольцо... но я вам лучшее сделаю! Дизайн, как я уже сказал, уж очень прост. Теперь я уже намного искуснее, и всего за каких-то тридцать серебряников я вам из него шедевр сделаю! Ну, чуть побольше тридцати, честно говоря...$B$BСейчас я в затруднении, все мои запасы материалов иссякли. Если вы принесете мне слиток серебра и моховой агат, то я нанесу на кольцо решетчатый узор из серебра и агата, и оно станет гораздо более стильным!$B$BПоверьте мне!','Принесите сверкающее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Талвашу дель Кисселю в Стальгорн.','Вы принесли нужные материалы? Я бы не стал просить, если бы удача не покинула меня...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гномское усовершенствование',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушайте $n, конечно, это ваше кольцо... но я вам лучшее сделаю! Дизайн, как я уже сказал, уж очень прост. Теперь я уже намного искуснее, и всего за каких-то тридцать серебряников я вам из него шедевр сделаю! Ну, чуть побольше тридцати, честно говоря...$B$BСейчас я в затруднении, все мои запасы материалов иссякли. Если вы принесете мне слиток серебра и моховой агат, то я нанесу на кольцо решетчатый узор из серебра и агата, и оно станет гораздо более стильным!$B$BПоверьте мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сверкающее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Талвашу дель Кисселю в Стальгорн.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы принесли нужные материалы? Я бы не стал просить, если бы удача не покинула меня...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2949,'Возвращение кольца','Открыв коробку, появившуюся в окошке Чистера 5200, вы видите сияющее кольцо! Надев кольцо на палец, вы чувствуете исходящие от него волны магической силы.$B$BНа внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Оргриммара, а рядом с ним выгравированы три буквы: "НОГ" – это явно начало имени, но даже после чистки прочесть его целиком невозможно. Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира... Оставить кольцо себе или вернуть владельцу... Непростое решение!','Вы можете оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца.','Кольцо из Гномрегана? Очень любопытно... Нет, его сделал не я.$B$BГномреганская штучка – н-да, неплохо для горстки болванов. Подумать только, эти ходячие недоразумения вдруг научились делать машины лучше нас...$B$BЧто, кольцо было у дворфа Черного Железа? Еще интереснее... Возможно, гномы сперли и подправили чертежи их жутких големов – я бы этому совсем не удивился. Значит, теперь дворфы жаждут мести. Очень любопытно...','Ничего, уж мы найдем управу на этих мерзких маленьких гномов. Я даже не сомневаюсь, что это они сперли у нас эту машину! Проклятые создания... А? Чего изволите?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение кольца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Открыв коробку, появившуюся в окошке Чистера 5200, вы видите сияющее кольцо! Надев кольцо на палец, вы чувствуете исходящие от него волны магической силы.$B$BНа внутренней стороне кольца стоит маленькое, но вполне различимое клеймо Оргриммара, а рядом с ним выгравированы три буквы: "НОГ" – это явно начало имени, но даже после чистки прочесть его целиком невозможно. Это могут быть инициалы владельца, а может – изготовившего кольцо ювелира... Оставить кольцо себе или вернуть владельцу... Непростое решение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вы можете оставить кольцо себе, а можете попытаться найти того, чьи инициалы выгравированы на внутренней стороне кольца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кольцо из Гномрегана? Очень любопытно... Нет, его сделал не я.$B$BГномреганская штучка – н-да, неплохо для горстки болванов. Подумать только, эти ходячие недоразумения вдруг научились делать машины лучше нас...$B$BЧто, кольцо было у дворфа Черного Железа? Еще интереснее... Возможно, гномы сперли и подправили чертежи их жутких големов – я бы этому совсем не удивился. Значит, теперь дворфы жаждут мести. Очень любопытно...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ничего, уж мы найдем управу на этих мерзких маленьких гномов. Я даже не сомневаюсь, что это они сперли у нас эту машину! Проклятые создания... А? Чего изволите?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2950,'Переделка кольца','Нет-нет-нет, я не собираюсь утверждать, что это моя работа! Обычно я такого не делаю. Но твое сообщение насчет дворфов Черного Железа чрезвычайно полезно. Так и быть, я переделаю для тебя это кольцо, и оно станет куда лучше, чем мог предполагать его создатель. Наверно, это был какой-нибудь гном...$b$bПринеси мне слиток серебра, моховой агат и тридцать серебряных монет – за труды. Я украшу кольцо серебряной решеткой, вправлю в него агат, и это значительно усилит его магические свойства. Интересует?','Принесите сверкающее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Ноггу в Огргиммар.','Вот оно, твое кольцо, лучше прежнего. Еще раз спасибо за сведения об этих дворфах Черного Железа. Это объясняет, откуда вдруг у гномов взялись гоблинские идеи...','Ну что, есть у тебя нужные материалы? Без того, о чем я просил, я это кольцо улучшить не смогу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переделка кольца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет-нет-нет, я не собираюсь утверждать, что это моя работа! Обычно я такого не делаю. Но твое сообщение насчет дворфов Черного Железа чрезвычайно полезно. Так и быть, я переделаю для тебя это кольцо, и оно станет куда лучше, чем мог предполагать его создатель. Наверно, это был какой-нибудь гном...$b$bПринеси мне слиток серебра, моховой агат и тридцать серебряных монет – за труды. Я украшу кольцо серебряной решеткой, вправлю в него агат, и это значительно усилит его магические свойства. Интересует?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сверкающее золотое кольцо, слиток серебра, моховой агат и 30 серебряных монет Ноггу в Огргиммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот оно, твое кольцо, лучше прежнего. Еще раз спасибо за сведения об этих дворфах Черного Железа. Это объясняет, откуда вдруг у гномов взялись гоблинские идеи...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, есть у тебя нужные материалы? Без того, о чем я просил, я это кольцо улучшить не смогу!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2951,'Чистер 5200!','Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений. Небольшая табличка, прикрепленная к устройству, гласит: "Чистер 5200".$B$BВаши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер 5200 легко справится с этой проблемой! Опустите в щель приемника три серебряные монеты и подождите пару минут, пока Чистер 5200 наводит лоск на ваши украшения.','Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200.','Вы кладете покрытый грязью предмет и три серебряные монеты в Чистер 5200, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует.','Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.','Вернитесь к Чистеру 5200 в Гномреган.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чистер 5200!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений. Небольшая табличка, прикрепленная к устройству, гласит: "Чистер 5200".$B$BВаши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер 5200 легко справится с этой проблемой! Опустите в щель приемника три серебряные монеты и подождите пару минут, пока Чистер 5200 наводит лоск на ваши украшения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы кладете покрытый грязью предмет и три серебряные монеты в Чистер 5200, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чистеру 5200 в Гномреган.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (2952,'Чистер 5200!','Проглотив кольцо, машина несколько минут с гудением вертит его в своих недрах и наконец останавливается, звенящим звуком оповестив вас о том, что работа закончена. Окошко приемника открывается, и вы видите в нем аккуратно завернутую коробочку. Видимо, машина выдает очищенные предметы в подарочной упаковке. Ну, даже если кольцо не удалось очистить, вы получили довольно миленькую коробочку за свои деньги...$B$BЧто ж, посмотрим...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чистер 5200!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Проглотив кольцо, машина несколько минут с гудением вертит его в своих недрах и наконец останавливается, звенящим звуком оповестив вас о том, что работа закончена. Окошко приемника открывается, и вы видите в нем аккуратно завернутую коробочку. Видимо, машина выдает очищенные предметы в подарочной упаковке. Ну, даже если кольцо не удалось очистить, вы получили довольно миленькую коробочку за свои деньги...$B$BЧто ж, посмотрим...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2953,'Работа для Чистера','Приемник Чистера 5200 пуст. Чтобы машина заработала, требуется загрязненный предмет и три серебряные монетки.','Вернитесь к Чистеру 5200 в Предгорья Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работа для Чистера',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приемник Чистера 5200 пуст. Чтобы машина заработала, требуется загрязненный предмет и три серебряные монетки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чистеру 5200 в Предгорья Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (2954,'Каменный Страж','"Приветствую. Я охраняю вход. Если в вашем наборе дисков нет Ульдумских пластин, вы не сможете посетить комплекс Ульдум."$b$bДолжно быть, появление Каменного Стража Норганнона и есть та реакция, на которую рассчитывали те, кто послал вас в пустыню Танарис с платиновыми дисками. Прежде чем продолжить путь, вам предстоит узнать историю Каменного Стража.','Узнайте назначение Каменного Стража Норганнона, затем коснитесь пьедестала Ульдума в пустыне Танарис.','В голосе Каменного Стража звучит сила и власть:\n\n\\"Когда ты коснешья пьедестала, диски вернутся к тебе. Получив же Ульдумские пластины и воссоединив их с имеющимися дисками, ты сможешь войти в Ульдум.\\"','Чтобы продолжить, следует узнать назначение Каменного Стража...','Узнайте назначение Каменного Стража Норганнона','Воспользуйтесь пьедесталом Ульдума в Танарисе.','Узнайте назначение Каменного Стража Норганнона') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменный Страж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Приветствую. Я охраняю вход. Если в вашем наборе дисков нет Ульдумских пластин, вы не сможете посетить комплекс Ульдум."$b$bДолжно быть, появление Каменного Стража Норганнона и есть та реакция, на которую рассчитывали те, кто послал вас в пустыню Танарис с платиновыми дисками. Прежде чем продолжить путь, вам предстоит узнать историю Каменного Стража.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте назначение Каменного Стража Норганнона, затем коснитесь пьедестала Ульдума в пустыне Танарис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В голосе Каменного Стража звучит сила и власть:\n\n\\"Когда ты коснешья пьедестала, диски вернутся к тебе. Получив же Ульдумские пластины и воссоединив их с имеющимися дисками, ты сможешь войти в Ульдум.\\"',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы продолжить, следует узнать назначение Каменного Стража...',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Узнайте назначение Каменного Стража Норганнона',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь пьедесталом Ульдума в Танарисе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Узнайте назначение Каменного Стража Норганнона',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2962,'Сильное зеленое свечение','Этого образца не только недостаточно для опытов, он еще и загрязнен.$B$BНам нужно более сильное зеленое свечение. Для наших целей эти трогги явно недостаточно облучены. Вам придется отправиться в Гномреган и принести некоторое количество радиоактивных образцов прямо с носителей. Я говорю об облученных слизнюках, шнырюках и ужасниках. Будьте начеку: образцы хранить очень трудно. Возможно, придется сделать несколько попыток, пока вы не принесете достаточное количество образцов.','Отправляйтесь в Гномреган и принесите высокорадиоактивные образцы. Внимание: отходы нестабильны и довольно быстро разрушаются.$B$BВерните Оззи тяжелую освинцованную склянку для проб, когда задача будет выполнена.','Оззи рассматривает вас. Впечатляюще, у вас не отвалилась ни одна конечность! Ну-с, посмотрим, на что сгодится эта проба!','Хм, вы не светитесь. Хороший знак.','Вернитесь к Оззи Триггервольту в Каранос, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сильное зеленое свечение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этого образца не только недостаточно для опытов, он еще и загрязнен.$B$BНам нужно более сильное зеленое свечение. Для наших целей эти трогги явно недостаточно облучены. Вам придется отправиться в Гномреган и принести некоторое количество радиоактивных образцов прямо с носителей. Я говорю об облученных слизнюках, шнырюках и ужасниках. Будьте начеку: образцы хранить очень трудно. Возможно, придется сделать несколько попыток, пока вы не принесете достаточное количество образцов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Гномреган и принесите высокорадиоактивные образцы. Внимание: отходы нестабильны и довольно быстро разрушаются.$B$BВерните Оззи тяжелую освинцованную склянку для проб, когда задача будет выполнена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Оззи рассматривает вас. Впечатляюще, у вас не отвалилась ни одна конечность! Ну-с, посмотрим, на что сгодится эта проба!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хм, вы не светитесь. Хороший знак.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Оззи Триггервольту в Каранос, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2963,'Ульдумские чудеса','И снова примите мои поздравления, $n! Ваша ульдаманская находка привела всю Лигу исследователей в такое возбуждение! Лига пыталась разгадать тайны найденных вами миниатюрных платиновых дисков. Ваше неожиданное прибытие сюда, в Зал, дает мне возможность сказать вам, что мы, похоже, наткнулись на нечто великое!$B$BИсторик Карник нашел важные сведения по поводу истинного происхождения Долины Стражей в пустыне Танарис. Он хочет поговорить с вами как можно скорее!','Поговорите с историком Карником в Зале Исследователей в Стальгорне.','Я счастлив, что вы не оставляете интереса к исследованиям, $n! Ваши прирожденные талант и отвага помогут нам приоткрыть завесу таких тайн, что мы и надеяться не смели!$B$BДиски Норганнона из Ульдамана служили хранилищем обширных знаний. Вы, так сказать, только чуть копнули. У Создателей, как говорят, в Азероте имелись и другие хранилища. Это подводит нас к проблеме Ульдума...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ульдумские чудеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И снова примите мои поздравления, $n! Ваша ульдаманская находка привела всю Лигу исследователей в такое возбуждение! Лига пыталась разгадать тайны найденных вами миниатюрных платиновых дисков. Ваше неожиданное прибытие сюда, в Зал, дает мне возможность сказать вам, что мы, похоже, наткнулись на нечто великое!$B$BИсторик Карник нашел важные сведения по поводу истинного происхождения Долины Стражей в пустыне Танарис. Он хочет поговорить с вами как можно скорее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с историком Карником в Зале Исследователей в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я счастлив, что вы не оставляете интереса к исследованиям, $n! Ваши прирожденные талант и отвага помогут нам приоткрыть завесу таких тайн, что мы и надеяться не смели!$B$BДиски Норганнона из Ульдамана служили хранилищем обширных знаний. Вы, так сказать, только чуть копнули. У Создателей, как говорят, в Азероте имелись и другие хранилища. Это подводит нас к проблеме Ульдума...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2964,'Новое задание','Что сказать, $n... мы зашли в тупик. Мы знаем, что нам нужно – Ульдумские пластины – но где их взять, не имеем ни малейшего понятия. Необходимо провести серьезное исследование и выработать план действий. У меня есть пара идей, и я надеюсь, что вскоре мы наймем тебя и отправим за пластинами.$b$bОб этом необходимо сообщить старшему исследователю; он без сомнения пожелает лично поблагодарить тебя за помощь Лиге.','Поговорите со старшим исследователем Магелласом в Стальгорне.','Значит, мы все согласны – лучший план действий – это выждать, пока мы сможем сузить зону поиска. Мы зашли настолько далеко благодаря тебе, $n, и я надеюсь, что именно ты сумеешь отомкнуть для нас Ульдум!\n\nПозволь вручить тебе заслуженный гонорар и небольшую премию. Заглядывай к нам время от времени... Ульдум ждет тебя!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое задание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что сказать, $n... мы зашли в тупик. Мы знаем, что нам нужно – Ульдумские пластины – но где их взять, не имеем ни малейшего понятия. Необходимо провести серьезное исследование и выработать план действий. У меня есть пара идей, и я надеюсь, что вскоре мы наймем тебя и отправим за пластинами.$b$bОб этом необходимо сообщить старшему исследователю; он без сомнения пожелает лично поблагодарить тебя за помощь Лиге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со старшим исследователем Магелласом в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, мы все согласны – лучший план действий – это выждать, пока мы сможем сузить зону поиска. Мы зашли настолько далеко благодаря тебе, $n, и я надеюсь, что именно ты сумеешь отомкнуть для нас Ульдум!\n\nПозволь вручить тебе заслуженный гонорар и небольшую премию. Заглядывай к нам время от времени... Ульдум ждет тебя!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2965,'Ульдумские чудеса','Ах, $n, как удачно, что ты снова $Gпришел:пришла; ко мне! Твоя ульдаманская находка вызвала ожесточенные споры среди мудрецов. Я сам только что спорил с друидом, Нарой Буйногривой, когда меня вдруг осенило – ее недавние приключения могут быть весьма важны в смысле определения следующего нашего шага в разгадке этой тайны!$B$BЯ бы хотел, чтобы ты $Gпоговорил:поговорила; с ней о ее путешествии в Долину Стражей в пустыне Танарис. Она ждет тебя на Вершине Старейшин.','Поговорите с Нарой Буйногривой на Вершине Старейшин Громового Утеса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ульдумские чудеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах, $n, как удачно, что ты снова $Gпришел:пришла; ко мне! Твоя ульдаманская находка вызвала ожесточенные споры среди мудрецов. Я сам только что спорил с друидом, Нарой Буйногривой, когда меня вдруг осенило – ее недавние приключения могут быть весьма важны в смысле определения следующего нашего шага в разгадке этой тайны!$B$BЯ бы хотел, чтобы ты $Gпоговорил:поговорила; с ней о ее путешествии в Долину Стражей в пустыне Танарис. Она ждет тебя на Вершине Старейшин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Нарой Буйногривой на Вершине Старейшин Громового Утеса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2966,'Посмотрим, что будет дальше','Мы с Ведуном Искателем Истины хотели бы, чтобы ты $Gдоставил:доставила; эти миниатюрные диски к запечатанным воротам Ульдума. Мы... мы не знаем, что может после этого случиться.$B$BДа, мы понимаем, это может показаться рискованным. Но может ведь и ничего не случиться? Может, тебе придется что-то с этими дисками сделать. Возможно, эти диски откроют ворота. Не бойся испытать их и будь $Gготов:готова; ко всему.$B$BУзнай, что получится, и возвращайся ко мне. Нам есть много о чем поговорить.','Принесите миниатюрные платиновые диски к воротам Ульдума в Танарисе и проверьте, имеют ли диски отношение к воротам.','Когда вы прикасаетесь к постаменту, улдаманские диски в вашем заплечном мешке начинают гудеть и светиться. Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража.\n\n"Приветствую вас. Я – страж входа. Среди дисков доступа не хватает Ульдумских пластин. Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа. Благодарю за внимание".','Какой знакомый постамент торчит из горячего песка. Возможно, он тут неспроста...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посмотрим, что будет дальше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с Ведуном Искателем Истины хотели бы, чтобы ты $Gдоставил:доставила; эти миниатюрные диски к запечатанным воротам Ульдума. Мы... мы не знаем, что может после этого случиться.$B$BДа, мы понимаем, это может показаться рискованным. Но может ведь и ничего не случиться? Может, тебе придется что-то с этими дисками сделать. Возможно, эти диски откроют ворота. Не бойся испытать их и будь $Gготов:готова; ко всему.$B$BУзнай, что получится, и возвращайся ко мне. Нам есть много о чем поговорить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите миниатюрные платиновые диски к воротам Ульдума в Танарисе и проверьте, имеют ли диски отношение к воротам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда вы прикасаетесь к постаменту, улдаманские диски в вашем заплечном мешке начинают гудеть и светиться. Знакомое покалывание ощущается в руках, и перед вратами Ульдума оживает изваяние Каменного стража.\n\n"Приветствую вас. Я – страж входа. Среди дисков доступа не хватает Ульдумских пластин. Пожалуйста, дополните набор дисков этими пластинами и повторите последовательность доступа. Благодарю за внимание".',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какой знакомый постамент торчит из горячего песка. Возможно, он тут неспроста...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2967,'Возвращение в Громовой Утес','Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски.$b$bОбретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Громовой Утес к Наре Буйногривой, сообщить ей о совершенных открытиях.','Поговорите с Нарой Буйногривой в Громовом Утесе.','Тебе не хватило дисков? Забавно. Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке.\n\nЕсли нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум! Не знаю, радоваться такой возможности или ужасаться.\n\nБыть может, нам придется пожертвовать всем ради сохранения глубинных тайн земли, грозящих нам всем великими опасностями, хм, в тайне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Громовой Утес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски.$b$bОбретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Громовой Утес к Наре Буйногривой, сообщить ей о совершенных открытиях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Нарой Буйногривой в Громовом Утесе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе не хватило дисков? Забавно. Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке.\n\nЕсли нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум! Не знаю, радоваться такой возможности или ужасаться.\n\nБыть может, нам придется пожертвовать всем ради сохранения глубинных тайн земли, грозящих нам всем великими опасностями, хм, в тайне.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2968,'Новое задание','Что сказать, $n... мы оказались в тупиковой ситуации. Мы знаем, что нам нужно – Ульдумские пластины – но где их взять, не имеем ни малейшего понятия. Необходимо провести серьезное исследование и выработать план действий. У меня есть пара идей, и я надеюсь, что вскоре мы наймем тебя и отправим за пластинами.$b$bОб этом необходимо сообщить Ведуну Искателю Истины; он без сомнения пожелает лично поблагодарить тебя за услышанный зов.','Поговорите с Ведуном Искателем Истины в Громовом Утесе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое задание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что сказать, $n... мы оказались в тупиковой ситуации. Мы знаем, что нам нужно – Ульдумские пластины – но где их взять, не имеем ни малейшего понятия. Необходимо провести серьезное исследование и выработать план действий. У меня есть пара идей, и я надеюсь, что вскоре мы наймем тебя и отправим за пластинами.$b$bОб этом необходимо сообщить Ведуну Искателю Истины; он без сомнения пожелает лично поблагодарить тебя за услышанный зов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ведуном Искателем Истины в Громовом Утесе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2969,'Свободу всем живым существам!','Гнусные таурены из клана Зловещего Тотема ловят чудесных дракончиков, $n! Мы с Джер\'Кай понятия не имеем, что они собираются с ними делать, но явно ничего хорошего!$b$bУ нас просто не хватит сил, чтобы прорваться в лагерь и освободить пленных дракончиков, но, может быть, с твоей помощью...$b$bЕсли ты согласишься помочь, и у тебя есть надежные товарищи, отопри клетку вот этим ключом и выпусти бедных зверушек на волю! Только постарайся, чтобы все сумели улететь живыми... Конечно, я тоже буду с тобой! А Джер\'Кай останется здесь.','Освободите летучих хамелеонов из вольера в лагере Зловещего Тотема с помощью ключа от бамбуковой клетки. Необходимо, чтобы Кинда Лунная Пряжа и как минимум 6 хамелеонов остались живы.$b$bУ вас в запасе 6 минут. После этого Кинда решит, что пора отступать, и задание останется невыполненным.','Хвала Элуне, $N! Ты настоящий подарок судьбы! Нам с Джер\'Кай в одиночку никогда бы не удалось спасти бедных дракончиков.$B$BПожалуйста, поговори теперь с Джер\'Кай. А мне нужно приготовиться к мести! Если дракончики на свободе, это ещё не значит, что таурены не наловят новых! Так что мы с Джер\'Кай собираемся перейти в наступление.','Мы не можем позволить клану Зловещего Тотема уничтожить этих прекрасных существ. Их надо освободить из плена!','Спасите от плена как минимум 6 летучих хамелеонов','Вернитесь к Кинде Лунной Пряже в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свободу всем живым существам!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гнусные таурены из клана Зловещего Тотема ловят чудесных дракончиков, $n! Мы с Джер\'Кай понятия не имеем, что они собираются с ними делать, но явно ничего хорошего!$b$bУ нас просто не хватит сил, чтобы прорваться в лагерь и освободить пленных дракончиков, но, может быть, с твоей помощью...$b$bЕсли ты согласишься помочь, и у тебя есть надежные товарищи, отопри клетку вот этим ключом и выпусти бедных зверушек на волю! Только постарайся, чтобы все сумели улететь живыми... Конечно, я тоже буду с тобой! А Джер\'Кай останется здесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите летучих хамелеонов из вольера в лагере Зловещего Тотема с помощью ключа от бамбуковой клетки. Необходимо, чтобы Кинда Лунная Пряжа и как минимум 6 хамелеонов остались живы.$b$bУ вас в запасе 6 минут. После этого Кинда решит, что пора отступать, и задание останется невыполненным.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала Элуне, $N! Ты настоящий подарок судьбы! Нам с Джер\'Кай в одиночку никогда бы не удалось спасти бедных дракончиков.$B$BПожалуйста, поговори теперь с Джер\'Кай. А мне нужно приготовиться к мести! Если дракончики на свободе, это ещё не значит, что таурены не наловят новых! Так что мы с Джер\'Кай собираемся перейти в наступление.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы не можем позволить клану Зловещего Тотема уничтожить этих прекрасных существ. Их надо освободить из плена!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Спасите от плена как минимум 6 летучих хамелеонов',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кинде Лунной Пряже в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2970,'Небольшое возмездие','Как тебе уже говорила Кинда, мы с ней собираемся напасть на тауренов из клана Зловещего Тотема. Мы без труда уложим несколько тауренов, не подвергаясь опасности сами, но мы были бы очень рады, если бы и ты $gприсоединился:присоединилась; к нам.$b$bТот лагерь, что внизу, тебе известен, но дальше на восток есть еще несколько. Постарайся причинить тауренам максимальный ущерб. Ну, а после того, как они отведают стрел Кинды и твоего собственного оружия, мы можем встретиться здесь снова.','Убейте 12 натуралистов из племени Зловещего Тотема, 10 налетчиков из племени Зловещего Тотема и 6 шаманов из племени Зловещего Тотема, а затем вернитесь к Джер\'ке Лунной Пряже в Фералас.','Да, $N, Кайдел была права насчет тебя: у тебя талант к этому делу! Ты – куда более $Gопытный:опытная; искатель приключений, чем мы обе. Спасибо, что ты с нами!$B$BЭтот клан Зловещего Тотема куда опаснее остальных тауренов. Подозреваю, что их боятся даже собственные сородичи!$B$BВпрочем, об этом потом.','Кайдел нужно время, чтобы подготовиться, но у нас с тобой и так счет идет на десятки! Клан Зловещего Тотема обнаружил наше присутствие, и теперь они закопошились, как гадюки!$B$BОни сделают все, что в их силах, чтобы избавиться от нас. Так что смотри, осторожнее! Теперь, когда ты с нами, они будут охотиться и на тебя.','Вернитесь к Джер\'ке Лунной Пряже в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небольшое возмездие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как тебе уже говорила Кинда, мы с ней собираемся напасть на тауренов из клана Зловещего Тотема. Мы без труда уложим несколько тауренов, не подвергаясь опасности сами, но мы были бы очень рады, если бы и ты $gприсоединился:присоединилась; к нам.$b$bТот лагерь, что внизу, тебе известен, но дальше на восток есть еще несколько. Постарайся причинить тауренам максимальный ущерб. Ну, а после того, как они отведают стрел Кинды и твоего собственного оружия, мы можем встретиться здесь снова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 натуралистов из племени Зловещего Тотема, 10 налетчиков из племени Зловещего Тотема и 6 шаманов из племени Зловещего Тотема, а затем вернитесь к Джер\'ке Лунной Пряже в Фералас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $N, Кайдел была права насчет тебя: у тебя талант к этому делу! Ты – куда более $Gопытный:опытная; искатель приключений, чем мы обе. Спасибо, что ты с нами!$B$BЭтот клан Зловещего Тотема куда опаснее остальных тауренов. Подозреваю, что их боятся даже собственные сородичи!$B$BВпрочем, об этом потом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кайдел нужно время, чтобы подготовиться, но у нас с тобой и так счет идет на десятки! Клан Зловещего Тотема обнаружил наше присутствие, и теперь они закопошились, как гадюки!$B$BОни сделают все, что в их силах, чтобы избавиться от нас. Так что смотри, осторожнее! Теперь, когда ты с нами, они будут охотиться и на тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джер\'ке Лунной Пряже в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2971,'<UNUSED>','[PH] Описание','[PH] Log Description','[PH] Log Bullet Entry','Вернитесь к взрывнику Ими Фитилюшке на Хилсбрадские поля, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[PH] Описание',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PH] Log Description',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','[PH] Log Bullet Entry',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к взрывнику Ими Фитилюшке на Хилсбрадские поля, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2972,'Небольшое возмездие','Здесь, в глуши, у нас с Киндой нет особых возможностей тебя вознаградить. Но разумеется, без награды мы тебя не отпустим! Вот, возьми мой перстень с печаткой. Если когда-нибудь окажешься в ветвях Тельдрассила, зайди в храм в центре Дарнаса. Там ты найдешь нашу верховную жрицу, Тиранду Шелест Ветра. Кольцо будет для нее знаком, что с нами все в порядке, и что тебе можно доверять.$b$bМы обе благодарим тебя, $n!','Отнесите перстень-печатку Джер\'Кай верховной жрице Тиранде Шелест Ветра в Дарнасе.','Прекрасная история, $N! Мы очень рады, что ты $Gпомог:помогла; не только драконьему племени, но и одной из наших жриц. Джер\'Кай поступила правильно, прислав тебя к нам. Я позабочусь о том, чтобы вернуть ей ее кольцо – в Фералас в ближайшее время отправятся наши разведчики. Пусть заодно разведают и это...$B$BСпасибо тебе еще раз. Чувствуй себя у нас, как дома!','Привет тебе, дитя мое! Мы рады видеть в нашем храме столь закаленных искателей приключений. Если у тебя есть время, быть может, ты поделишься парочкой историй с менее опытными странниками? Многим из них наверняка пойдет на пользу твоя мудрость.$B$BОх, прости меня! Как это неучтиво с моей стороны! Ведь ты пришел в наш храм за помощью, а я пристаю к тебе с пустяками... Прости меня, пожалуйста. Чем могут тебе помочь служители Света?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небольшое возмездие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, в глуши, у нас с Киндой нет особых возможностей тебя вознаградить. Но разумеется, без награды мы тебя не отпустим! Вот, возьми мой перстень с печаткой. Если когда-нибудь окажешься в ветвях Тельдрассила, зайди в храм в центре Дарнаса. Там ты найдешь нашу верховную жрицу, Тиранду Шелест Ветра. Кольцо будет для нее знаком, что с нами все в порядке, и что тебе можно доверять.$b$bМы обе благодарим тебя, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите перстень-печатку Джер\'Кай верховной жрице Тиранде Шелест Ветра в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасная история, $N! Мы очень рады, что ты $Gпомог:помогла; не только драконьему племени, но и одной из наших жриц. Джер\'Кай поступила правильно, прислав тебя к нам. Я позабочусь о том, чтобы вернуть ей ее кольцо – в Фералас в ближайшее время отправятся наши разведчики. Пусть заодно разведают и это...$B$BСпасибо тебе еще раз. Чувствуй себя у нас, как дома!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет тебе, дитя мое! Мы рады видеть в нашем храме столь закаленных искателей приключений. Если у тебя есть время, быть может, ты поделишься парочкой историй с менее опытными странниками? Многим из них наверняка пойдет на пользу твоя мудрость.$B$BОх, прости меня! Как это неучтиво с моей стороны! Ведь ты пришел в наш храм за помощью, а я пристаю к тебе с пустяками... Прости меня, пожалуйста. Чем могут тебе помочь служители Света?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2973,'Новый сверкающий плащ','Приятно познакомиться, |3-6($c). Мы с товарищами прибыли сюда, в Фералас, по заданию из Оргриммара.$b$bМоя супруга, Коррин, очень любит новые наряды. Я хочу пошить ей новый плащ из прозрачных крылышек чудесных дракончиков. Не согласишься ли ты мне помочь? Те летучие хамелеоны с роскошными крыльями, что мне нужны, водятся к западу от Лагеря Мохаче.','Принесите 10 радужных крыльев летучих хамелеонов Кригу Головорубу в Лагерь Мохаче.','Отлично, |3-6($C)! Да, это то, что надо. Этого вполне хватит на плащ для Коррин, а может, и останется! Спасибо тебе.$B$BНу что, надеюсь, охота была не очень опасной? А то ведь Фералас ошибок не прощает.$B$BСпасибо еще раз, |3-6($C)!','Летучие хамелеоны могут быть очень опасны, когда на них нападают. Так что смотри в оба, |3-6($R)! Тем более, опасаться приходится не только дракончиков, но и тамошних ночных эльфов.$B$BКогда наберешь нужное количество крыльев, дай мне знать, уж я в долгу не останусь!','Вернитесь к Кригу Головорубу на Штормовое озеро, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый сверкающий плащ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приятно познакомиться, |3-6($c). Мы с товарищами прибыли сюда, в Фералас, по заданию из Оргриммара.$b$bМоя супруга, Коррин, очень любит новые наряды. Я хочу пошить ей новый плащ из прозрачных крылышек чудесных дракончиков. Не согласишься ли ты мне помочь? Те летучие хамелеоны с роскошными крыльями, что мне нужны, водятся к западу от Лагеря Мохаче.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 радужных крыльев летучих хамелеонов Кригу Головорубу в Лагерь Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, |3-6($C)! Да, это то, что надо. Этого вполне хватит на плащ для Коррин, а может, и останется! Спасибо тебе.$B$BНу что, надеюсь, охота была не очень опасной? А то ведь Фералас ошибок не прощает.$B$BСпасибо еще раз, |3-6($C)!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Летучие хамелеоны могут быть очень опасны, когда на них нападают. Так что смотри в оба, |3-6($R)! Тем более, опасаться приходится не только дракончиков, но и тамошних ночных эльфов.$B$BКогда наберешь нужное количество крыльев, дай мне знать, уж я в долгу не останусь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кригу Головорубу на Штормовое озеро, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2974,'Зловещее открытие','Как? Таурены, здесь, в этих краях? Да ты шутишь! И как они выглядели?$b$bКлан Зловещего Тотема! Тебе повстречались именно они. Белгром, один из наших старших, очень ими интересуется... Даже награду за них назначил!$b$bВозвращайся туда, |3-6($c)! Возвращайся, и принеси мне их рога – чем больше, тем лучше! С кланом Зловещего Тотема шутки плохи, и недооценивать их не стоит. Ступай и перебей их, сколько сможешь. Пусть реки Фераласа побагровеют от их темной крови!','Принесите 20 рогов Зловещего Тотема Кригу Головорубу в Лагерь Мохаче.','Отличные рога, |3-6($C)! $GМолодец:Умница;! Я заберу их у тебя и сообщу о твоих деяниях Белгрому, как только вернусь в Оргриммар. Ты $Gпомог:помогла; мне уже дважды, и я тебя запомню. Быть может, когда-нибудь и я тебе помогу! Удачи.','Клан Зловещего Тотема – злой клан, $C. Я серьезно. Если тебе удалось обнаружить их гнездо, самое лучшее – нанести упреждающий удар, прежде, чем они попытаются захватить наши владения и сравнять с землей наши деревни.','Вернитесь к Кригу Головорубу на Штормовое озеро, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зловещее открытие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как? Таурены, здесь, в этих краях? Да ты шутишь! И как они выглядели?$b$bКлан Зловещего Тотема! Тебе повстречались именно они. Белгром, один из наших старших, очень ими интересуется... Даже награду за них назначил!$b$bВозвращайся туда, |3-6($c)! Возвращайся, и принеси мне их рога – чем больше, тем лучше! С кланом Зловещего Тотема шутки плохи, и недооценивать их не стоит. Ступай и перебей их, сколько сможешь. Пусть реки Фераласа побагровеют от их темной крови!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 рогов Зловещего Тотема Кригу Головорубу в Лагерь Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные рога, |3-6($C)! $GМолодец:Умница;! Я заберу их у тебя и сообщу о твоих деяниях Белгрому, как только вернусь в Оргриммар. Ты $Gпомог:помогла; мне уже дважды, и я тебя запомню. Быть может, когда-нибудь и я тебе помогу! Удачи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Клан Зловещего Тотема – злой клан, $C. Я серьезно. Если тебе удалось обнаружить их гнездо, самое лучшее – нанести упреждающий удар, прежде, чем они попытаются захватить наши владения и сравнять с землей наши деревни.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кригу Головорубу на Штормовое озеро, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2975,'Огры Фераласа','Присутствие огров из клана Гордунни не может оставаться незамеченным. Оглядись вокруг, $n! Само их существование уродует эту землю. Необходимо оттеснить их назад, пока они не продвинулись еще дальше в Фералас.$b$bСтупай на север вдоль реки, и увидишь их заставу. Задай им жару, $n! Пусть видят, что им тут не рады.','Убейте 10 огров из клана Гордунни, 10 огров-магов из клана Гордунни и 5 громил из клана Гордунни по просьбе Роки Орхан из Лагеря Мохаче.','Отлично, $N! Еще немного, и эта земля исцелится. Мы не сдадимся!','Быстро двигайся, $N. Или задание, которое я просил, слишком сложное?','Вернитесь к Роке Орхан на Штормовое озеро, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огры Фераласа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Присутствие огров из клана Гордунни не может оставаться незамеченным. Оглядись вокруг, $n! Само их существование уродует эту землю. Необходимо оттеснить их назад, пока они не продвинулись еще дальше в Фералас.$b$bСтупай на север вдоль реки, и увидишь их заставу. Задай им жару, $n! Пусть видят, что им тут не рады.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 огров из клана Гордунни, 10 огров-магов из клана Гордунни и 5 громил из клана Гордунни по просьбе Роки Орхан из Лагеря Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! Еще немного, и эта земля исцелится. Мы не сдадимся!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Быстро двигайся, $N. Или задание, которое я просил, слишком сложное?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Роке Орхан на Штормовое озеро, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2976,'Зловещее открытие','Чего еще?$b$bАх, я говорил о награде? Ну что ж, поделом мне – пора бы и научиться держать язык за зубами...$b$bНу, в конце концов, это ты $gсделал:сделала; всю работу, тебе и награда полагается. Забирай рога. Я велю упаковать их в ящик. Отыщи на Аллее Чести Белгрома Каменную Булаву. Он расспросит тебя о том, что ты $gвидел:видела;, и выдаст заслуженную награду.$b$bПока, |3-6($c)! Еще раз спасибо за все.','Отнесите ящик с рогами клана Зловещего Тотема Белгрому Каменной Булаве в Оргриммар.','Клан Зловещего Тотема?! Интересно... Так говоришь, ты $Gнаткнулся:наткнулась; на них во время охоты в Фераласе? В самом деле?$B$BТвои новости очень важны для нас, |3-6($C). Расскажи все как было, а я пока отсчитаю твою награду.$B$BДа, и пока ты не $Gушел:ушла;: имей в виду, я тебе очень признателен за эту информацию.','Поживей, $C! У меня сегодня еще много дел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зловещее открытие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чего еще?$b$bАх, я говорил о награде? Ну что ж, поделом мне – пора бы и научиться держать язык за зубами...$b$bНу, в конце концов, это ты $gсделал:сделала; всю работу, тебе и награда полагается. Забирай рога. Я велю упаковать их в ящик. Отыщи на Аллее Чести Белгрома Каменную Булаву. Он расспросит тебя о том, что ты $gвидел:видела;, и выдаст заслуженную награду.$b$bПока, |3-6($c)! Еще раз спасибо за все.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик с рогами клана Зловещего Тотема Белгрому Каменной Булаве в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клан Зловещего Тотема?! Интересно... Так говоришь, ты $Gнаткнулся:наткнулась; на них во время охоты в Фераласе? В самом деле?$B$BТвои новости очень важны для нас, |3-6($C). Расскажи все как было, а я пока отсчитаю твою награду.$B$BДа, и пока ты не $Gушел:ушла;: имей в виду, я тебе очень признателен за эту информацию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поживей, $C! У меня сегодня еще много дел.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2977,'Возвращение в Стальгорн','Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски.$b$bОбретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Стальгорн и сообщить Лиге исследователей о совершенных открытиях.','Поговорите с историком Карником из Стальгорна.','Тебе не хватило дисков? Забавно. Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке.\n\nЕсли нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум! Только представь – у нас появится возможность исследовать место, где трудились Создатели, не роясь в земле!\n\nХотя землю рыть тоже неплохо... вполне...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Стальгорн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы снова вступаете на пьедестал; неожиданно у вас в заплечном мешке опять материализуются платиновые диски.$b$bОбретя знания Каменного Стража и вернув себе диски, вам пора возвращаться в Стальгорн и сообщить Лиге исследователей о совершенных открытиях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с историком Карником из Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе не хватило дисков? Забавно. Похоже, диски Норганнона – всего лишь часть полного набора, один из ключей в связке.\n\nЕсли нам удастся найти Ульдумские пластины, мы можем получить доступ в сам Ульдум! Только представь – у нас появится возможность исследовать место, где трудились Создатели, не роясь в земле!\n\nХотя землю рыть тоже неплохо... вполне...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (2978,'Свиток Гордунни','Вы берете в руки запачканный свиток и обнаруживаете, что на нем изображена какая-то встреча или церемония. Рока Орхан наверняка заинтересуется этим свитком и тем, что он означает для Гордунни...','Отнести свиток Гордунни Роке Орхан в Лагерь Мохаче.','Этот свиток... Ты $Gнашел:нашла; его в Поселении Гордунни?','Что это?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свиток Гордунни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы берете в руки запачканный свиток и обнаруживаете, что на нем изображена какая-то встреча или церемония. Рока Орхан наверняка заинтересуется этим свитком и тем, что он означает для Гордунни...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнести свиток Гордунни Роке Орхан в Лагерь Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот свиток... Ты $Gнашел:нашла; его в Поселении Гордунни?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2979,'Темный обряд','$n, похоже, они готовят какой-то темный обряд! Насколько я понимаю, проводить его будут маги-лорды из клана Гордунни.$b$bОтыщи одного из таких магов-лордов, и добудь у него магическую сферу.$b$bВ такой сфере сокрыта великая мощь, и она поможет нам больше узнать об этом обряде и о магии, которой владеют Гордунни.','Добудьте сферу Гордунни по просьбе Роки Орхан из Лагеря Мохаче.','Эта сфера поможет нам получить информацию о Гордунни... И мы используем эту информацию, чтобы разгромить их!','Нам нужно понять, почему Гордунни здесь, $N.','Вернитесь к Роке Орхан на Штормовое озеро, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темный обряд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, похоже, они готовят какой-то темный обряд! Насколько я понимаю, проводить его будут маги-лорды из клана Гордунни.$b$bОтыщи одного из таких магов-лордов, и добудь у него магическую сферу.$b$bВ такой сфере сокрыта великая мощь, и она поможет нам больше узнать об этом обряде и о магии, которой владеют Гордунни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сферу Гордунни по просьбе Роки Орхан из Лагеря Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта сфера поможет нам получить информацию о Гордунни... И мы используем эту информацию, чтобы разгромить их!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам нужно понять, почему Гордунни здесь, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Роке Орхан на Штормовое озеро, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2980,'Огры Фераласа','Теперь, когда ты $gпоказал:показала; себя настоящим бойцом, я надеюсь, тебе хватит мужества выполнить и следующее задание.$b$bОтправляйся в Высокогорные дебри, к юго-западу отсюда. Это земля, которая некогда принадлежала ночным эльфам. Там увидишь заброшенные и разрушенные здания. Когда увидишь среди руин засохшие деревья и оскверненную почву, знай: там и живут Гордунни. Прогони их прочь!$b$bЭти огры куда опаснее тех, с которыми тебе, $n, доводилось сталкиваться прежде. Так что будь осторожнее!','Убейте 10 шаманов из клана Гордунни, 10 чернокнижников из клана Гордунни и 5 извергов из клана Гордунни по просьбе Роки Орхан из Лагеря Мохаче.','Да, $N, ты воистину надежный и верный союзник!','Ты $Gнашел:нашла; руины, $N?','Вернитесь к Роке Орхан на Штормовое озеро, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огры Фераласа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты $gпоказал:показала; себя настоящим бойцом, я надеюсь, тебе хватит мужества выполнить и следующее задание.$b$bОтправляйся в Высокогорные дебри, к юго-западу отсюда. Это земля, которая некогда принадлежала ночным эльфам. Там увидишь заброшенные и разрушенные здания. Когда увидишь среди руин засохшие деревья и оскверненную почву, знай: там и живут Гордунни. Прогони их прочь!$b$bЭти огры куда опаснее тех, с которыми тебе, $n, доводилось сталкиваться прежде. Так что будь осторожнее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 шаманов из клана Гордунни, 10 чернокнижников из клана Гордунни и 5 извергов из клана Гордунни по просьбе Роки Орхан из Лагеря Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $N, ты воистину надежный и верный союзник!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; руины, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Роке Орхан на Штормовое озеро, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2981,'Опасность в Фераласе','Что, |3-6($c), хочешь показать себя? Фералас для этого самое подходящее место! Главная сила там – племя огров, именуемое Гордунни, и их становится все больше и больше. Их надо остановить, пока они не вытеснили из Фераласа нас!$b$bВ Лагере Мохаче в Фераласе живет моя знакомая воительница по имени Рока Орхан. Ступай к ней. Она подробнее расскажет тебе о создавшемся положении.','Поговорите с Рокой Орхан в Лагере Мохаче.','А, тебя прислал Белгром! Ты как нельзя более вовремя, |3-6($R).\n\nЯ расскажу, что у нас тут творится, а ты уж решай, по зубам ли тебе это... Хотя если тебя прислал Белгром, значит, сомневаться в твоей доблести не приходится.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасность в Фераласе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что, |3-6($c), хочешь показать себя? Фералас для этого самое подходящее место! Главная сила там – племя огров, именуемое Гордунни, и их становится все больше и больше. Их надо остановить, пока они не вытеснили из Фераласа нас!$b$bВ Лагере Мохаче в Фераласе живет моя знакомая воительница по имени Рока Орхан. Ступай к ней. Она подробнее расскажет тебе о создавшемся положении.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рокой Орхан в Лагере Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, тебя прислал Белгром! Ты как нельзя более вовремя, |3-6($R).\n\nЯ расскажу, что у нас тут творится, а ты уж решай, по зубам ли тебе это... Хотя если тебя прислал Белгром, значит, сомневаться в твоей доблести не приходится.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2982,'Высокогорные дебри','Места там опасные, и все же мы с Троясом исследовали руины в лесах Фераласа.$b$bНо в последнее время Трояс ходил в Высокогорные дебри в одиночку. Я серьезно за него беспокоюсь! Эти земли захвачены ограми из клана Гордунни, а они не дают спуску тем, кто забредает на их территорию!$b$bЯ надеялась, что вы, может быть, согласитесь побывать в развалинах на юго-востоке и перебить часть огров? Тогда эти места станут не такими опасными. Я вам буду очень признательна!','Убейте 8 чернокнижников из клана Гордунни, 8 шаманов из клана Гордунни и 8 громил из клана Гордунни по просьбе Ангелас Лунный Бриз.','О, как я вам благодарна!$B$BТолько, пожалуйста, Троясу об этом ни слова!','Будь осторожен с Гордунни, $N. Их магия, кажется, сеет хаос на самой земле, на которой они стоят.','Вернитесь к Ангелас Лунный Бриз в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Высокогорные дебри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Места там опасные, и все же мы с Троясом исследовали руины в лесах Фераласа.$b$bНо в последнее время Трояс ходил в Высокогорные дебри в одиночку. Я серьезно за него беспокоюсь! Эти земли захвачены ограми из клана Гордунни, а они не дают спуску тем, кто забредает на их территорию!$b$bЯ надеялась, что вы, может быть, согласитесь побывать в развалинах на юго-востоке и перебить часть огров? Тогда эти места станут не такими опасными. Я вам буду очень признательна!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 чернокнижников из клана Гордунни, 8 шаманов из клана Гордунни и 8 громил из клана Гордунни по просьбе Ангелас Лунный Бриз.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, как я вам благодарна!$B$BТолько, пожалуйста, Троясу об этом ни слова!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будь осторожен с Гордунни, $N. Их магия, кажется, сеет хаос на самой земле, на которой они стоят.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ангелас Лунный Бриз в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2983,'Зов Огня','Много времени прошло с тех пор, как ты $gпрошел:прошла; последнее испытание, $n. Пока тебе хватало терпения в твоих занятиях, однако пришло время обрести новую силу... подлинную силу! Стихия огня – твоя, если только ты $gготов:готова; заплатить за это знание.$b$bОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!','Найдите в Степях Кранала Фисса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много времени прошло с тех пор, как ты $gпрошел:прошла; последнее испытание, $n. Пока тебе хватало терпения в твоих занятиях, однако пришло время обрести новую силу... подлинную силу! Стихия огня – твоя, если только ты $gготов:готова; заплатить за это знание.$b$bОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Степях Кранала Фисса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2984,'Зов Огня','Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание, $n! Пока тебе хватало терпения в твоих занятиях, однако пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты $gготов:готова; платить за это.$b$bОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!','Найдите в Степях Кранала Фисса.','Что, тебя Нарм прислал, да?$B$BНу, на Нарма положиться можно. Значит, ты уже $Gготов:готова; вкусить следующую сапту – сапту огня.$B$BДа, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение, $N. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание, $n! Пока тебе хватало терпения в твоих занятиях, однако пришло время сделать новый шаг. Пора учиться разрушению и хаосу. Тебе следует овладеть стихией огня – если только ты $gготов:готова; платить за это.$b$bОтыщи в Степях Кранала Фисса. Он живет в небольшой хижине к северу от Перекрестка. Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Степях Кранала Фисса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, тебя Нарм прислал, да?$B$BНу, на Нарма положиться можно. Значит, ты уже $Gготов:готова; вкусить следующую сапту – сапту огня.$B$BДа, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг... Но терпение, $N. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2985,'Зов Воды','Похоже, ты $gготов:готова; к новому испытанию, $n. Ты $gпроявил:проявила; немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.$B$BОтыщи Ислену Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, $n.','Отыщите в Степях Ислену Заклинательницу Воды.','Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.\n\nПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, ты $gготов:готова; к новому испытанию, $n. Ты $gпроявил:проявила; немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.$B$BОтыщи Ислену Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите в Степях Ислену Заклинательницу Воды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ветер следует за тобой, по земле ты шагаешь твердо, а дух уже согрет огнем – я бы сказала, что пришло время познать чистоту воды.\n\nПуть твой был долог, и сила духа позволит тебе пройти еще дальше. Но первый шаг делать тебе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (2986,'Зов Воды','Много воды утекло со времени последнего испытания. Ты $gпроявил:проявила; немало упорства в учении и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.$B$BОтыщи Ислену Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, $n.','Отыщите в Степях Ислену Заклинательницу Воды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много воды утекло со времени последнего испытания. Ты $gпроявил:проявила; немало упорства в учении и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды.$B$BОтыщи Ислену Заклинательницу Воды. Она живет в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите в Степях Ислену Заклинательницу Воды.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2987,'Кобальт Гордунни','Я только что прибыл сюда, в Фералас. Я слышал, что у огров из клана Гордунни, обитающих в здешних чащобах, попадаются интересные минералы. Неизвестно, к чему они им, но уж, разумеется, по доброй воле они ими делиться не собираются! Наоборот, норовят спрятать, чтобы бизнесменам вроде меня труднее было до них добраться.$b$bЕсли вы согласитесь помочь, то вот вам моя лопатка. Ступайте в Поселение Гордунни к северу отсюда и накопайте мне образцов кобальта Гордунни. Ищите: где блеснет синим, там и ройте!','Добудьте 12 образцов кобальта Гордунни для Орвина Гиззмика из Лагеря Мохаче.','Отлично! Захвачу это с собой, когда снова отправлюсь в путь. Я наверняка сумею найти кого-то, кто выложит за эти образцы кругленькую сумму!$B$BБлагодарю вас, $N. Вот, возьмите за труды.','Ну что, вперед, за работу!$B$BА мне надо много где побывать, много кого повидать... Время – деньги!','Вернитесь к Орвину Гиззмику на Штормовое озеро, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кобальт Гордунни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я только что прибыл сюда, в Фералас. Я слышал, что у огров из клана Гордунни, обитающих в здешних чащобах, попадаются интересные минералы. Неизвестно, к чему они им, но уж, разумеется, по доброй воле они ими делиться не собираются! Наоборот, норовят спрятать, чтобы бизнесменам вроде меня труднее было до них добраться.$b$bЕсли вы согласитесь помочь, то вот вам моя лопатка. Ступайте в Поселение Гордунни к северу отсюда и накопайте мне образцов кобальта Гордунни. Ищите: где блеснет синим, там и ройте!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 12 образцов кобальта Гордунни для Орвина Гиззмика из Лагеря Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Захвачу это с собой, когда снова отправлюсь в путь. Я наверняка сумею найти кого-то, кто выложит за эти образцы кругленькую сумму!$B$BБлагодарю вас, $N. Вот, возьмите за труды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, вперед, за работу!$B$BА мне надо много где побывать, много кого повидать... Время – деньги!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орвину Гиззмику на Штормовое озеро, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2988,'Тролльи клетки','Пропал сын нашего самого лучшего грифона! Наследник Быстрокрыла, Остроклюв, пропал несколько дней назад, когда охотился вместе с родителями. Я думаю, его похитили тролли!$B$BПомогите нам! Остроклюва могут держать в клетке в одной из двух деревенек Сухокожих.','Проверьте клетки в двух деревнях Сухокожих и возвращайтесь к дрессировщику грифонов Разящему Когтю.','Остроклюва в деревнях нет? Хм... это плохо. От этого грифона должно было произойти их следующее поколение, и если он погибнет, то наш флот понесет огромные потери...','Ты $Gобыскивал:обыскала; клетки, $N? Мы должны найти Остроклюва!','Вернитесь к укротителю грифонов Разящему Когтю на Заоблачный пик, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролльи клетки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пропал сын нашего самого лучшего грифона! Наследник Быстрокрыла, Остроклюв, пропал несколько дней назад, когда охотился вместе с родителями. Я думаю, его похитили тролли!$B$BПомогите нам! Остроклюва могут держать в клетке в одной из двух деревенек Сухокожих.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проверьте клетки в двух деревнях Сухокожих и возвращайтесь к дрессировщику грифонов Разящему Когтю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Остроклюва в деревнях нет? Хм... это плохо. От этого грифона должно было произойти их следующее поколение, и если он погибнет, то наш флот понесет огромные потери...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gобыскивал:обыскала; клетки, $N? Мы должны найти Остроклюва!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю грифонов Разящему Когтю на Заоблачный пик, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2989,'Алтарь Зула','У троллей племени Сухокожих Остроклюва нет... Значит, его забрали тролли из племени Порочной Ветви. Поищите детеныша грифона у Алтаря Зула – это на западной границе территории этого клана.','Осмотрите вершину Алтаря Зула и возвращайтесь к укротителю грифонов Разящему Когтю.','Остроклюва там не было? Это плохая, но и хорошая новость...$B$BХорошо, что его не было на алтаре Зула – там тролли из клана Порочной Ветви совершают свои жертвоприношения.$B$BСпасибо за помощь, но, боюсь, вам предстоит еще одна, более тяжелая работа.','Скорее, $N! Племя Порочной Ветви держит у себя Остроклюва, нужно немедленно освободить его!','Осмотреть алтарь Зула','Вернитесь к укротителю грифонов Разящему Когтю на Заоблачный пик, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Алтарь Зула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У троллей племени Сухокожих Остроклюва нет... Значит, его забрали тролли из племени Порочной Ветви. Поищите детеныша грифона у Алтаря Зула – это на западной границе территории этого клана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотрите вершину Алтаря Зула и возвращайтесь к укротителю грифонов Разящему Когтю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Остроклюва там не было? Это плохая, но и хорошая новость...$B$BХорошо, что его не было на алтаре Зула – там тролли из клана Порочной Ветви совершают свои жертвоприношения.$B$BСпасибо за помощь, но, боюсь, вам предстоит еще одна, более тяжелая работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Скорее, $N! Племя Порочной Ветви держит у себя Остроклюва, нужно немедленно освободить его!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Осмотреть алтарь Зула',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю грифонов Разящему Когтю на Заоблачный пик, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2990,'Тадиус Мрачная Тень','Отнесите это перо Тадиусу Мрачной Тени, прорицателю. Он давно ушел с Заоблачного пика в поисках темных знаний, но в душе он все еще с нами, с кланом Громового Молота!$B$BВозможно, он поможет нам разыскать Остроклюва.$B$BЭто перо нашли в гнезде, где был детеныш грифона, и если вы отдадите его Тадиусу, то он сможет при помощи своего прорицания узнать, где находится сам Остроклюв.$B$BУдачи, $n. Тадиуса можно найти в Выжженных землях, в башне магов в крепости Стражей Пустоты.','Принесите перо Остроклюва Тадиусу Мрачной Тени в Выжженные земли.','Ах, да. Это перо грифона, но не обычного, а великого, способного на великие дела... Если, конечно, он доживет до зрелого возраста.$B$BХотите найти его? Что ж, тогда слушайте, храбрый |3-6($C).') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тадиус Мрачная Тень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнесите это перо Тадиусу Мрачной Тени, прорицателю. Он давно ушел с Заоблачного пика в поисках темных знаний, но в душе он все еще с нами, с кланом Громового Молота!$B$BВозможно, он поможет нам разыскать Остроклюва.$B$BЭто перо нашли в гнезде, где был детеныш грифона, и если вы отдадите его Тадиусу, то он сможет при помощи своего прорицания узнать, где находится сам Остроклюв.$B$BУдачи, $n. Тадиуса можно найти в Выжженных землях, в башне магов в крепости Стражей Пустоты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите перо Остроклюва Тадиусу Мрачной Тени в Выжженные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, да. Это перо грифона, но не обычного, а великого, способного на великие дела... Если, конечно, он доживет до зрелого возраста.$B$BХотите найти его? Что ж, тогда слушайте, храбрый |3-6($C).',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (2991,'Медальон Некрума','Я найду вам вашего грифона, но вначале вы должны кое-что сделать для меня. В Зул\'Фарраке живет тролль по имени Некрум Кишкожуй, и мне очень-очень нужен его медальон, для изучения. Принесите мне тот медальон, а я найду вам Остроклюва.$B$BЗул\'Фаррак лежит за океаном, на западе, в пустыне Танарис.','Принесите медальон Некрума Тадиусу Мрачной Тени в Выжженные земли.','Вернитесь к Тадиусу Мрачной Тени в Крепость Стражей Пустоты, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медальон Некрума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я найду вам вашего грифона, но вначале вы должны кое-что сделать для меня. В Зул\'Фарраке живет тролль по имени Некрум Кишкожуй, и мне очень-очень нужен его медальон, для изучения. Принесите мне тот медальон, а я найду вам Остроклюва.$B$BЗул\'Фаррак лежит за океаном, на западе, в пустыне Танарис.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите медальон Некрума Тадиусу Мрачной Тени в Выжженные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тадиусу Мрачной Тени в Крепость Стражей Пустоты, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (2992,'Прорицание','Посторонитесь-ка, мне нужно место, чтобы выполнить ритуал прорицания. Я установлю связь между этим пером и его владельцем, а потом попытаюсь найти и самого Остроклюва.$B$BЕсли все пойдет по плану, то должно получиться, а если нет... Вы, на всякий случай, закройте глаза.','Дождитесь, пока Мрачная Тень не закончит ритуал прорицания.','Ритуал прошел успешно. Я видел Остроклюва и могу сказать, где его найти.','Дождаться, пока Мрачная Тень закончит','Вернитесь к Тадиусу Мрачной Тени в Крепость Стражей Пустоты, что в Выжженных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорицание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посторонитесь-ка, мне нужно место, чтобы выполнить ритуал прорицания. Я установлю связь между этим пером и его владельцем, а потом попытаюсь найти и самого Остроклюва.$B$BЕсли все пойдет по плану, то должно получиться, а если нет... Вы, на всякий случай, закройте глаза.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока Мрачная Тень не закончит ритуал прорицания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ритуал прошел успешно. Я видел Остроклюва и могу сказать, где его найти.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Дождаться, пока Мрачная Тень закончит',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тадиусу Мрачной Тени в Крепость Стражей Пустоты, что в Выжженных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2993,'Назад во Внутренние земли','Остроклюва держат в клетке, на самом верху Джинта\'Алора, что во Внутренних землях. Ключ от его клетки находится у коварной жрицы племени Порочной Ветви Ведьмисы.$B$BНу вот, я закончил. Желаю удачи в бою, $n.','Поговорите с укротителем грифонов Разящим Когтем.','Вы поговорили с Мрачной Тенью? Что он сказал?$B$BЧто? Остроклюв у троллей Порочной Ветви? Это немыслимо! Мы непременно должны его спасти!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад во Внутренние земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остроклюва держат в клетке, на самом верху Джинта\'Алора, что во Внутренних землях. Ключ от его клетки находится у коварной жрицы племени Порочной Ветви Ведьмисы.$B$BНу вот, я закончил. Желаю удачи в бою, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с укротителем грифонов Разящим Когтем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы поговорили с Мрачной Тенью? Что он сказал?$B$BЧто? Остроклюв у троллей Порочной Ветви? Это немыслимо! Мы непременно должны его спасти!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2994,'Спасение Остроклюва','Мы должны спасти Остроклюва!$B$BПробейтесь в верхнюю часть Джинта\'Алора, отберите ключ у коварной жрицы Ведьмисы, а потом найдите и освободите Остроклюва!','Пробейтесь в верхнюю часть Джинта\'Алора, убейте коварную жрицу Ведьмису, возьмите у нее ключ от клетки и освободите Остроклюва.','Быстроветр и Острокоготь минуту назад вернулись вместе со своим детенышем, и теперь от него не отходят. Ох, как гляну на них, аж слеза прошибает...$B$BЯ даже не знаю, чем мы можем отблагодарить вас, $n. Грифоны Заоблачного Пика и их всадники навсегда запомнят ваше имя.','Спасите Остроклюва!','Вернитесь к укротителю грифонов Разящему Когтю на Заоблачный пик, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Остроклюва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны спасти Остроклюва!$B$BПробейтесь в верхнюю часть Джинта\'Алора, отберите ключ у коварной жрицы Ведьмисы, а потом найдите и освободите Остроклюва!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пробейтесь в верхнюю часть Джинта\'Алора, убейте коварную жрицу Ведьмису, возьмите у нее ключ от клетки и освободите Остроклюва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Быстроветр и Острокоготь минуту назад вернулись вместе со своим детенышем, и теперь от него не отходят. Ох, как гляну на них, аж слеза прошибает...$B$BЯ даже не знаю, чем мы можем отблагодарить вас, $n. Грифоны Заоблачного Пика и их всадники навсегда запомнят ваше имя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Спасите Остроклюва!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю грифонов Разящему Когтю на Заоблачный пик, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (2995,'Линии связи','Сторожка Кель\'Данил – центр сообщения высших эльфов Внутренних земель. Их посланники пытаются установить отношения с другими расами и делятся с ними сведениями о троллях из племени Сухокожих, обитающих в южной части Внутренних земель. Все документы, связанные с этим, хранятся в сторожке.$b$bМы не хотим, чтобы Высокодолье заключало союзы с другими народами, $n.$B$BУничтожь документы Высокодолья. Есть мнение, что рукописи не горят... у тебя есть шанс проверить, так ли это.','Сожгите отчет Высокодолья, заметки Высокодолья и записи Высокодолья.','Великолепно. Пока эльфы будут восстанавливать утраченную информацию, мы сможем еще навсегда отрезать их от остального мира…','Ключ к успеху - держать эльфов Высокой долины в изоляции. Вы нашли домик?','Вернитесь к Оран Змеиные Кольца в деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Линии связи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сторожка Кель\'Данил – центр сообщения высших эльфов Внутренних земель. Их посланники пытаются установить отношения с другими расами и делятся с ними сведениями о троллях из племени Сухокожих, обитающих в южной части Внутренних земель. Все документы, связанные с этим, хранятся в сторожке.$b$bМы не хотим, чтобы Высокодолье заключало союзы с другими народами, $n.$B$BУничтожь документы Высокодолья. Есть мнение, что рукописи не горят... у тебя есть шанс проверить, так ли это.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите отчет Высокодолья, заметки Высокодолья и записи Высокодолья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Пока эльфы будут восстанавливать утраченную информацию, мы сможем еще навсегда отрезать их от остального мира…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ключ к успеху - держать эльфов Высокой долины в изоляции. Вы нашли домик?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Оран Змеиные Кольца в деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (2996,'В поисках Страхада','Я многому тебя научил, теперь тебе нужен новый наставник. Он живет в Кабестане, его зовут Страхад. Он человек, но он отнюдь не слаб. Он невелик ростом, но силен! Ты уже можешь вызывать более могущественных существ, и он научит тебя этому. Ступай к нему. Он живет в Кабестане, над портом, рядом с башней.','Поговорите со Страхадом Фарсаном в Кабестане.','Мы охотно приняли бы в дар шерстяную ткань. Если ты дашь нам 60 отрезов, Оргриммар будет тебе чрезвычайно признателен за щедрость. 60 отрезов нам вполне бы хватило – вместе с дарами от прочих пожертвователей этого было бы достаточно, чтобы продолжать работу.\n\nЕсли у тебя при себе имеется 60 отрезов шерсти и ты готов ее пожертвовать, я могу ее принять прямо сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Страхада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я многому тебя научил, теперь тебе нужен новый наставник. Он живет в Кабестане, его зовут Страхад. Он человек, но он отнюдь не слаб. Он невелик ростом, но силен! Ты уже можешь вызывать более могущественных существ, и он научит тебя этому. Ступай к нему. Он живет в Кабестане, над портом, рядом с башней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со Страхадом Фарсаном в Кабестане.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы охотно приняли бы в дар шерстяную ткань. Если ты дашь нам 60 отрезов, Оргриммар будет тебе чрезвычайно признателен за щедрость. 60 отрезов нам вполне бы хватило – вместе с дарами от прочих пожертвователей этого было бы достаточно, чтобы продолжать работу.\n\nЕсли у тебя при себе имеется 60 отрезов шерсти и ты готов ее пожертвовать, я могу ее принять прямо сейчас.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2997,'Фолиант Божественности','Привет, $n. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морог, но когда тебе выпадет свободная минутка, посети Стальгорн и поговори с одной из самых почитаемых наших сестер – Тизой Боевой Горн. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от тебя.$B$BТы можешь найти ее на верхнем этаже Зала Тайн, что в Палатах Магии. Удачи тебе, $n.','Поговорите с Тизой Боевой Горн в Стальгорне.','Привет тебе, $N. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $n. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морог, но когда тебе выпадет свободная минутка, посети Стальгорн и поговори с одной из самых почитаемых наших сестер – Тизой Боевой Горн. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от тебя.$B$BТы можешь найти ее на верхнем этаже Зала Тайн, что в Палатах Магии. Удачи тебе, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тизой Боевой Горн в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, $N. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2998,'Фолиант Божественности','Приветствую тебя, $Gбрат мой:сестра моя;. Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе. Он считает, что тебе пора пройти некое испытание... Он вообще весьма неплохо о тебе отзывался, надо сказать.$B$BНа твоем месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдется на это время. Ищи его в Соборе Света: там он проводит большую часть времени.','Найдите Даториана Ралла в Штормграде и поговорите с ним.','Как красив Штормград, не правда ли?..$B$BТвой визит в это время более чем уместен, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $Gбрат мой:сестра моя;. Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе. Он считает, что тебе пора пройти некое испытание... Он вообще весьма неплохо о тебе отзывался, надо сказать.$B$BНа твоем месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдется на это время. Ищи его в Соборе Света: там он проводит большую часть времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Даториана Ралла в Штормграде и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как красив Штормград, не правда ли?..$B$BТвой визит в это время более чем уместен, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (2999,'Фолиант Божественности','Привет, $n. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морог, но когда тебе выпадет свободная минутка, поднимись наверх и поговори с одной из наших самых почитаемых сестер – Тизой Боевой Горн. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что от тебя ожидается.','Поговорите с Тизой Боевой Горн в Стальгорне.','Привет тебе, $N. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $n. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морог, но когда тебе выпадет свободная минутка, поднимись наверх и поговори с одной из наших самых почитаемых сестер – Тизой Боевой Горн. Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что от тебя ожидается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тизой Боевой Горн в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, $N. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3000,'Фолиант Божественности','Привет, $n. Я знаю, что ты рук не покладаешь, помогая жителям Азерота, но когда тебе выпадет свободная минутка, вернись в Стальгорн и поговори с Тизой Боевой Горн. Она одна из тех, к кому обращаются самые молодые дворфийские паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от всех нас.$B$BТы можешь найти ее на верхнем этаже Зала Тайн, что в Палатах Магии.','Поговорите с Тизой Боевой Горн в Стальгорне.','Приветствую и добро пожаловать, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $n. Я знаю, что ты рук не покладаешь, помогая жителям Азерота, но когда тебе выпадет свободная минутка, вернись в Стальгорн и поговори с Тизой Боевой Горн. Она одна из тех, к кому обращаются самые молодые дворфийские паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от всех нас.$B$BТы можешь найти ее на верхнем этаже Зала Тайн, что в Палатах Магии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тизой Боевой Горн в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую и добро пожаловать, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3001,'В поисках Страхада','Я многому тебя научил, и теперь тебе нужен новый наставник. Он живет в Кабестане, его зовут Страхад. Это человек, но отнюдь не слабый. Также у нас нет причин смотреть на него как на потенциального врага... по крайней мере, пока что. Он обладает силой и заслуживает уважения. Я чувствую в тебе готовность призывать более могущественных существ, и он может обучить тебя этому.','Поговорите со Страхадом Фарсаном в Кабестане.','Всегда жизнь в Кабестане, бьет ключом, не так ли. Ну так, на то он и порт. Столько всяких тайн, столько приключений, столько невежества…$B$BЯ вижу ненависть в твоих глазах, $N? Хорошо, мы найдем ей полезное применение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Страхада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я многому тебя научил, и теперь тебе нужен новый наставник. Он живет в Кабестане, его зовут Страхад. Это человек, но отнюдь не слабый. Также у нас нет причин смотреть на него как на потенциального врага... по крайней мере, пока что. Он обладает силой и заслуживает уважения. Я чувствую в тебе готовность призывать более могущественных существ, и он может обучить тебя этому.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со Страхадом Фарсаном в Кабестане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Всегда жизнь в Кабестане, бьет ключом, не так ли. Ну так, на то он и порт. Столько всяких тайн, столько приключений, столько невежества…$B$BЯ вижу ненависть в твоих глазах, $N? Хорошо, мы найдем ей полезное применение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3002,'Сфера Гордунни','Я, конечно, хорошо знаю своих врагов, и все же я – только воительница, $n. Я даже приблизительно не представляю, на что способна эта сфера.$b$bНо я знаю одного мага в Оргриммаре, который сможет рассказать нам о ней больше. Отнеси сферу к нему!','Отнести сферу Гордунни Утель\'наю в Пристанище Темнотерна в Оргриммаре.','Да, $N, занятная вещица…$B$BЭтот шар весьма могуществен, но и очень опасен!','Что это у тебя, $R?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сфера Гордунни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я, конечно, хорошо знаю своих врагов, и все же я – только воительница, $n. Я даже приблизительно не представляю, на что способна эта сфера.$b$bНо я знаю одного мага в Оргриммаре, который сможет рассказать нам о ней больше. Отнеси сферу к нему!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнести сферу Гордунни Утель\'наю в Пристанище Темнотерна в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $N, занятная вещица…$B$BЭтот шар весьма могуществен, но и очень опасен!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя, $R?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (3022,'Не кантовать!','$n, я вижу, как ты $gпредан:предана; сему достойному делу. Да, конечно, ты можешь мне помочь!$b$bОтнеси этот ящик с яйцами Эреласу Янтарному Небу. Он друид, и заботится об этих яйцах, помогает вылупиться маленьким гиппогрифам и обучает их. Его можно найти в Тельдрассиле, в маленькой деревушке Рут\'теран на юге.','Отнесите тщательно упакованный ящик Эреласу Янтарному Небу в деревню Рут\'теран.','Еще одна посылочка от Кургль?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не кантовать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я вижу, как ты $gпредан:предана; сему достойному делу. Да, конечно, ты можешь мне помочь!$b$bОтнеси этот ящик с яйцами Эреласу Янтарному Небу. Он друид, и заботится об этих яйцах, помогает вылупиться маленьким гиппогрифам и обучает их. Его можно найти в Тельдрассиле, в маленькой деревушке Рут\'теран на юге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите тщательно упакованный ящик Эреласу Янтарному Небу в деревню Рут\'теран.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Еще одна посылочка от Кургль?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (3023,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3042,'Троллье месиво','The Sandfury trolls of Zul\'Farrak make a tempering agent from sandstones, and I can use that to temper the goods I craft. It is highly prized by connoisseurs, so if you bring me a good supply of the temper, then I\'ll reward you well.$B$BZul\'Farrak is northwest of Gadgetzan. Good luck.','Принесите 20 фиалов с Тролльим месивом.','Принес?','Вернитесь к Трентону Молоту Света в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Троллье месиво',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','The Sandfury trolls of Zul\'Farrak make a tempering agent from sandstones, and I can use that to temper the goods I craft. It is highly prized by connoisseurs, so if you bring me a good supply of the temper, then I\'ll reward you well.$B$BZul\'Farrak is northwest of Gadgetzan. Good luck.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 фиалов с Тролльим месивом.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принес?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трентону Молоту Света в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3062,'Темное сердце','Эдана Коготь Ненависти – царица гарпий из стаи Студеных Ключей, что обитают в руинах к западу отсюда. Эдана – это воплощенное зло. Я слышал, что сердце у нее каменное. Она не ведает иных чувств, кроме ненависти, которую питает ко всему живому. Сразись с Эданой и принеси мне ее темное сердце!$b$bЯ слышал, что гарпии носят при себе рог. Если затрубить в него у камней Когтя Ненависти, в северной части руин, появится царица.$b$bПредставь, как она удивится, когда обнаружит, что это был зов не ее сородичей, но самой смерти!','Принесите темное сердце Эданы Коготь Ненависти Тало Терновому Копыту.','Ну, вот теперь я точно знаю, что Эдана мертва! А это сердце я оставлю себе на память о твоем подвиге, $N. Спасибо тебе!','Ненависть, которую распространяет вокруг себя Эдана, необходимо остановить!','Вернитесь к Тало Терновому Копыту в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темное сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эдана Коготь Ненависти – царица гарпий из стаи Студеных Ключей, что обитают в руинах к западу отсюда. Эдана – это воплощенное зло. Я слышал, что сердце у нее каменное. Она не ведает иных чувств, кроме ненависти, которую питает ко всему живому. Сразись с Эданой и принеси мне ее темное сердце!$b$bЯ слышал, что гарпии носят при себе рог. Если затрубить в него у камней Когтя Ненависти, в северной части руин, появится царица.$b$bПредставь, как она удивится, когда обнаружит, что это был зов не ее сородичей, но самой смерти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите темное сердце Эданы Коготь Ненависти Тало Терновому Копыту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, вот теперь я точно знаю, что Эдана мертва! А это сердце я оставлю себе на память о твоем подвиге, $N. Спасибо тебе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ненависть, которую распространяет вокруг себя Эдана, необходимо остановить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тало Терновому Копыту в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3063,'Месть стае Студеных Ключей','В свое время я был закаленным охотником. Не было на свете такого зверя, которого я бы боялся. До тех пор, пока...$b$bЯ был один в лесу, точил свой клинок после жаркой битвы, и тут на меня напали из засады! Меня окружили гарпии, я еле сумел добраться до безопасного места.$b$bЯ еще и теперь как наяву слышу их вопли...$b$bИ с тех пор я уже никогда не мог стать прежним. В душе у меня кипит ненависть – все эти годы я жажду сквитаться с ними!$b$bГарпии из стаи Студеных Ключей водятся к западу отсюда. Отомсти за меня, $n.','Убейте 4 гарпий из стаи Студеных Ключей, 4 разбойниц из стаи Студеных Ключей, 4 зовущих из стаи Студеных Ключей и 4 убийц из стаи Студеных Ключей по просьбе Тало Тернового Копыта.','Спасибо тебе, $N. Ты возвращаешь покой душе старого таурена.','Крылья гарпий Студеных Ключей черные, как ночь; не своди с них глаз, чтобы они не исчезли во тьме.','Вернитесь к Тало Терновому Копыту в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть стае Студеных Ключей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В свое время я был закаленным охотником. Не было на свете такого зверя, которого я бы боялся. До тех пор, пока...$b$bЯ был один в лесу, точил свой клинок после жаркой битвы, и тут на меня напали из засады! Меня окружили гарпии, я еле сумел добраться до безопасного места.$b$bЯ еще и теперь как наяву слышу их вопли...$b$bИ с тех пор я уже никогда не мог стать прежним. В душе у меня кипит ненависть – все эти годы я жажду сквитаться с ними!$b$bГарпии из стаи Студеных Ключей водятся к западу отсюда. Отомсти за меня, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 гарпий из стаи Студеных Ключей, 4 разбойниц из стаи Студеных Ключей, 4 зовущих из стаи Студеных Ключей и 4 убийц из стаи Студеных Ключей по просьбе Тало Тернового Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, $N. Ты возвращаешь покой душе старого таурена.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Крылья гарпий Студеных Ключей черные, как ночь; не своди с них глаз, чтобы они не исчезли во тьме.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тало Терновому Копыту в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (3064,'<NYI> <TXT> Пиратские шляпы','Мне нужны пиратские шляпы на продажу. Принеси их как можно больше!','Принесите 20 целых пиратских шляп Юрбе Крутипроб.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> Пиратские шляпы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужны пиратские шляпы на продажу. Принеси их как можно больше!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 целых пиратских шляп Юрбе Крутипроб.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3065,'Простая табличка','А, $n! Тебе тут пергамент прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Франга, наставника воинов. Он хочет с тобой поговорить. Он обычно сидит в тени у входа в Логово.','Прочтите простую табличку и поговорите с Франгом в Долине Испытаний.','Наша долина – подходящее место, чтобы упражняться в воинских навыках. Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что $gготов:готова; продолжать обучение – возвращайся ко мне. Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!','А, еще $Gодин:одна:r; |3-6($r) в наших рядах! Ты мне подходишь.$b$bС топором тебе пока не управиться, но копье тоже сгодится.$b$bДобро пожаловать в Долину Испытаний!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Простая табличка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $n! Тебе тут пергамент прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Франга, наставника воинов. Он хочет с тобой поговорить. Он обычно сидит в тени у входа в Логово.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите простую табличку и поговорите с Франгом в Долине Испытаний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наша долина – подходящее место, чтобы упражняться в воинских навыках. Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что $gготов:готова; продолжать обучение – возвращайся ко мне. Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, еще $Gодин:одна:r; |3-6($r) в наших рядах! Ты мне подходишь.$b$bС топором тебе пока не управиться, но копье тоже сгодится.$b$bДобро пожаловать в Долину Испытаний!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3082,'Каменная табличка','А, $n! Тебе тут табличку прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Джен\'шан, наставницы охотников. Она хочет с тобой поговорить.','Поговорите с Джен\'шан в Долине Испытаний.','Теперь мы учим их пути охотника, а они учат нас другим вещам. Мы теперь одна раса... почти. Мы давнишние союзники. Не забывай об этом, а Джен\'шан не забудет о тебе.$b$bДжен\'шан научит тебя ремеслу охотника – хорошо научит! Помни: охотника в племени всегда уважают. И тебя ждет большое будущее – помни это!$b$bБудет надо – приходи к Джен\'шан. Она тебя научит всему, чему сможет, когда ты будешь $gготов:готова;.','Джен\'шан видит перед собой $gмогучего охотника:могучую охотницу;! Духи довольны.$b$bТропа охотника – один из древнейших путей этого мира. Орда обратилась к нам, когда пыталась выжить на Азероте. Ее воины попросили обучить их, открыть им наши тайны. Да, они уже были сильны: среди них были и грозные шаманы, и отважные воины. Но путь охотника еще не был их путем...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каменная табличка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $n! Тебе тут табличку прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Джен\'шан, наставницы охотников. Она хочет с тобой поговорить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джен\'шан в Долине Испытаний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь мы учим их пути охотника, а они учат нас другим вещам. Мы теперь одна раса... почти. Мы давнишние союзники. Не забывай об этом, а Джен\'шан не забудет о тебе.$b$bДжен\'шан научит тебя ремеслу охотника – хорошо научит! Помни: охотника в племени всегда уважают. И тебя ждет большое будущее – помни это!$b$bБудет надо – приходи к Джен\'шан. Она тебя научит всему, чему сможет, когда ты будешь $gготов:готова;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Джен\'шан видит перед собой $gмогучего охотника:могучую охотницу;! Духи довольны.$b$bТропа охотника – один из древнейших путей этого мира. Орда обратилась к нам, когда пыталась выжить на Азероте. Ее воины попросили обучить их, открыть им наши тайны. Да, они уже были сильны: среди них были и грозные шаманы, и отважные воины. Но путь охотника еще не был их путем...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3083,'Табличка с письменами','А, $n! Тебе тут табличку прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить.','Прочтите табличку с письменами и поговорите с Руагом в Долине Испытаний.','Ну а до тех пор будешь у меня в обучении. Я тебе расскажу, что к чему. Когда решишь, что $gготов:готова;, приходи ко мне, и я тобой займусь. А пока упражняйся в том, что уже умеешь. Все твои навыки должны быть отточены, как бритва! Никогда не знаешь, в какой момент пригодится какое-нибудь пустяковое умение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Табличка с письменами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $n! Тебе тут табличку прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите табличку с письменами и поговорите с Руагом в Долине Испытаний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну а до тех пор будешь у меня в обучении. Я тебе расскажу, что к чему. Когда решишь, что $gготов:готова;, приходи ко мне, и я тобой займусь. А пока упражняйся в том, что уже умеешь. Все твои навыки должны быть отточены, как бритва! Никогда не знаешь, в какой момент пригодится какое-нибудь пустяковое умение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3084,'Руническая табличка','А, $n! Тебе тут табличку прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить.','Поговорите с Шикрик в Долине Испытаний.','Ты, вероятно, уже знаешь, что могущество нам дают стихии. Огонь, земля, вода и воздух – вот наши орудия.$b$bНаша сила исходит от духов предков. Мы должны вести наш народ. Для городов и деревень, где мы бываем, мы должны стать тем же, чем стал Тралл для всей Орды. У нас будут просить совета и защиты. Но чтобы этого добиться, тебе потребуется немало трудов. Когда ты почувствуешь, что у тебя накопилось достаточно сил, приходи ко мне, и я научу тебя всему, чему смогу.','А, $n! Рада видеть тебя здесь. У меня немало дел, и учеников хватает, но каждый раз, как ко мне является кто-то из твоего племени, я чувствую, что круг замкнулся: ведь когда-то я сама училась у одного из ваших шаманов!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руническая табличка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $n! Тебе тут табличку прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Шикрик в Долине Испытаний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты, вероятно, уже знаешь, что могущество нам дают стихии. Огонь, земля, вода и воздух – вот наши орудия.$b$bНаша сила исходит от духов предков. Мы должны вести наш народ. Для городов и деревень, где мы бываем, мы должны стать тем же, чем стал Тралл для всей Орды. У нас будут просить совета и защиты. Но чтобы этого добиться, тебе потребуется немало трудов. Когда ты почувствуешь, что у тебя накопилось достаточно сил, приходи ко мне, и я научу тебя всему, чему смогу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, $n! Рада видеть тебя здесь. У меня немало дел, и учеников хватает, но каждый раз, как ко мне является кто-то из твоего племени, я чувствую, что круг замкнулся: ведь когда-то я сама училась у одного из ваших шаманов!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3085,'Освященная табличка','А, $n! Тебе тут табличку прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Кен\'джая, наставника жрецов. Он хочет с тобой поговорить.','Прочтите освященную табличку и поговорите с Кен\'джаем у Логова в Долине Испытаний.','Почаще пускай в ход полученные знания и увидишь, что духи повинуются тебе все лучше и лучше... В какой-то момент тебе поможет старый Кен\'джай! Приходи потолковать с мной, когда будешь $gготов:готова;. И если духи согласятся, мы научим тебя кое-чему еще... но только если они согласятся!$b$bНу, ступай, потолкуй со другими здешними жителями. И про меня не забывай.','А-а, ты здесь! Хорошо-хорошо! Духи предупреждали меня, что скоро ты явишься повидаться с Кен\'джаем. Я рад приветствовать тебя в Долине Испытаний. Это место недолго будет тебе домом, но постарайся научиться здесь всему, чему можно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освященная табличка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $n! Тебе тут табличку прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Кен\'джая, наставника жрецов. Он хочет с тобой поговорить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите освященную табличку и поговорите с Кен\'джаем у Логова в Долине Испытаний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Почаще пускай в ход полученные знания и увидишь, что духи повинуются тебе все лучше и лучше... В какой-то момент тебе поможет старый Кен\'джай! Приходи потолковать с мной, когда будешь $gготов:готова;. И если духи согласятся, мы научим тебя кое-чему еще... но только если они согласятся!$b$bНу, ступай, потолкуй со другими здешними жителями. И про меня не забывай.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А-а, ты здесь! Хорошо-хорошо! Духи предупреждали меня, что скоро ты явишься повидаться с Кен\'джаем. Я рад приветствовать тебя в Долине Испытаний. Это место недолго будет тебе домом, но постарайся научиться здесь всему, чему можно.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (3086,'Табличка с тайными знаками','А, $n! Тебе тут табличку прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Май\'ах, наставницы магов. Она хочет с тобой поговорить.','Прочтите табличку с тайными знаками и поговорите с Май\'ах у входа в Логово в Долине Испытаний.','Ага, $n, ты уже нравишься Май\'ах! Неплохо, неплохо. Уважай Май\'ах, и Май\'ах будет уважать тебя. Ну, хватит про это. Ты здесь, чтобы учиться магии, а не слушать болтовню Май\'ах.$b$bЧему Май\'ах тебя не сможет научить, так это одному: как остановить демонов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Табличка с тайными знаками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $n! Тебе тут табличку прислали, пока тебя не было.$b$bПрочитай, когда время будет. Это, кажется, от Май\'ах, наставницы магов. Она хочет с тобой поговорить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите табличку с тайными знаками и поговорите с Май\'ах у входа в Логово в Долине Испытаний.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ага, $n, ты уже нравишься Май\'ах! Неплохо, неплохо. Уважай Май\'ах, и Май\'ах будет уважать тебя. Ну, хватит про это. Ты здесь, чтобы учиться магии, а не слушать болтовню Май\'ах.$b$bЧему Май\'ах тебя не сможет научить, так это одному: как остановить демонов.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3095,'Простой свиток','А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника воинов Даннала. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.','Прочитайте простой свиток и поговорите с Данналом Штерном в Похоронном Звоне.','Я здесь, чтобы обучать тебя по мере того, как ты будешь набираться опыта... приходи как только захочешь. Я беру минимальную плату за уроки и научу тебя всему, чему смогу, чтобы ты $gбыл достойным бойцом:была достойной воительницей;. $b$bА теперь иди и проверь свои боевые навыки. Многое ты поймешь $gсам:сама; со временем, а кое-что я и вовсе не вправе поведать тебе. Просто знай, что в будущем Сильване потребуются помощники – такие, как ты. Ты станешь главной опорой нашего освобождения. Помни об этом.','Итак, ты $gприбыл:прибыла;. Хорошо. Я слышал, что еще нескольким удалось избежать "смерти" и они направляются сюда. Возможно, подобная живучесть пригодится им и в будущем. $b$bБлагодари Сильвану за свою свободу... свободу тела и духа. Хотя тебя по-прежнему мучают чума и ее последствия, ты можешь теперь передвигаться свободно – на вид ты в полном порядке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Простой свиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника воинов Даннала. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте простой свиток и поговорите с Данналом Штерном в Похоронном Звоне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я здесь, чтобы обучать тебя по мере того, как ты будешь набираться опыта... приходи как только захочешь. Я беру минимальную плату за уроки и научу тебя всему, чему смогу, чтобы ты $gбыл достойным бойцом:была достойной воительницей;. $b$bА теперь иди и проверь свои боевые навыки. Многое ты поймешь $gсам:сама; со временем, а кое-что я и вовсе не вправе поведать тебе. Просто знай, что в будущем Сильване потребуются помощники – такие, как ты. Ты станешь главной опорой нашего освобождения. Помни об этом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Итак, ты $gприбыл:прибыла;. Хорошо. Я слышал, что еще нескольким удалось избежать "смерти" и они направляются сюда. Возможно, подобная живучесть пригодится им и в будущем. $b$bБлагодари Сильвану за свою свободу... свободу тела и духа. Хотя тебя по-прежнему мучают чума и ее последствия, ты можешь теперь передвигаться свободно – на вид ты в полном порядке.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3096,'Зашифрованный свиток','А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника разбойников Давида Триаса. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.','Прочитайте зашифрованный свиток и поговорите с Давидом Триасом в Похоронном Звоне.','Большую часть времени я провожу здесь, в таверне, присматриваясь к новым лицам и новым возможностям. Не суй свой нос, куда не следует, а я сделаю все возможное, чтобы научить тебя кой-чему. Возвращайся ко мне, когда захочешь – посмотрим, будешь ли ты готов выучить пару новых трюков.','Значит, тебе все же удалось!.. Отлично, с течением времени нам требуется все больше разбойников. Тенеловы, возможно, захотят отыскать тебя, когда решат, что настал нужный момент, так что не пропадай и не делай ничего такого, о чем мог бы потом пожалеть. Им нужны способные агенты... а не жалкие карманники и дураки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зашифрованный свиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника разбойников Давида Триаса. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте зашифрованный свиток и поговорите с Давидом Триасом в Похоронном Звоне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большую часть времени я провожу здесь, в таверне, присматриваясь к новым лицам и новым возможностям. Не суй свой нос, куда не следует, а я сделаю все возможное, чтобы научить тебя кой-чему. Возвращайся ко мне, когда захочешь – посмотрим, будешь ли ты готов выучить пару новых трюков.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Значит, тебе все же удалось!.. Отлично, с течением времени нам требуется все больше разбойников. Тенеловы, возможно, захотят отыскать тебя, когда решат, что настал нужный момент, так что не пропадай и не делай ничего такого, о чем мог бы потом пожалеть. Им нужны способные агенты... а не жалкие карманники и дураки.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3097,'Священный свиток','А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника жрецов Дьюстена. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.','Прочитайте священный свиток и поговорите с темным священником Дьюстеном в церкви Похоронного Звона.','Есть лишь одно, что ты должен знать: мы выжили благодаря лишь силе воли. В нас есть вера, отличающая нас от других, и с помощью нашей силы мы сможем в корне изменить весь Азерот. Слабые придут, чтобы положиться на тебя. Прокаженные будут звать тебя $gГосподином:Госпожой;. А невежественный будет просить тебя об обучении. Моя обязанность – обеспечить тебя необходимыми инструментами, чтобы, когда придет время, ты $gбыл готов:была готова;. По мере накопления опыта навещай меня. Я научу тебя большему, когда настанет время.','Итак, меж огня, чумы, беспорядков и еще худших бед, еще $gодин "верный":одна "верная"; стучит в мою дверь. Что ж, позволь поприветствовать тебя, |3-6($c). И дай мне минутку, чтобы я объяснил тебе пару вещей, прежде чем ты решишь, что пора отправляться на поиски того, что притягивает тебя: Священный Свет позабыл о тебе, духи твоих предков – всего лишь сказки, а создания Хаоса не желают тебя. $b$bТы понимаешь, о чем я?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священный свиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника жрецов Дьюстена. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте священный свиток и поговорите с темным священником Дьюстеном в церкви Похоронного Звона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Есть лишь одно, что ты должен знать: мы выжили благодаря лишь силе воли. В нас есть вера, отличающая нас от других, и с помощью нашей силы мы сможем в корне изменить весь Азерот. Слабые придут, чтобы положиться на тебя. Прокаженные будут звать тебя $gГосподином:Госпожой;. А невежественный будет просить тебя об обучении. Моя обязанность – обеспечить тебя необходимыми инструментами, чтобы, когда придет время, ты $gбыл готов:была готова;. По мере накопления опыта навещай меня. Я научу тебя большему, когда настанет время.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Итак, меж огня, чумы, беспорядков и еще худших бед, еще $gодин "верный":одна "верная"; стучит в мою дверь. Что ж, позволь поприветствовать тебя, |3-6($c). И дай мне минутку, чтобы я объяснил тебе пару вещей, прежде чем ты решишь, что пора отправляться на поиски того, что притягивает тебя: Священный Свет позабыл о тебе, духи твоих предков – всего лишь сказки, а создания Хаоса не желают тебя. $b$bТы понимаешь, о чем я?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3098,'Покрытый письменами свиток','А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями Плети, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставницы магов Изабеллы. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.','Прочитайте свиток, покрытый письменами, и поговорите с Изабеллой в церкви Похоронного Звона.','Тебе стоит возвращаться ко мне почаще, если ты хочешь обрести достаточно сил для уничтожения наших недругов. Законы магии по-прежнему относятся и к тебе, $N. Ты узнаешь, что скверна следует за тобой по пятам, аки тать в ночи. Ты узнаешь, что ее прикосновение сродни пагубной страсти. Она будет льнуть к тебе, как трепетный любовник. И все же ты можешь избежать ее. Скверна обретет власть над тобой, только если ты ей это позволишь.$B$BА сейчас иди... возвращайся, когда силы твои возрастут.','Я знал, что ты придешь ко мне, $N. Не потому, что у тебя нет желания идти своим путем, а потому, что мы родственные души. Мы оба чувствовали боль. Мы оба страдали. И теперь мы хотим, чтобы власть вернула нам то, что мы знаем: эту землю, наши жизни, наши судьбы. Но тебе еще многому предстоит научиться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покрытый письменами свиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями Плети, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставницы магов Изабеллы. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте свиток, покрытый письменами, и поговорите с Изабеллой в церкви Похоронного Звона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе стоит возвращаться ко мне почаще, если ты хочешь обрести достаточно сил для уничтожения наших недругов. Законы магии по-прежнему относятся и к тебе, $N. Ты узнаешь, что скверна следует за тобой по пятам, аки тать в ночи. Ты узнаешь, что ее прикосновение сродни пагубной страсти. Она будет льнуть к тебе, как трепетный любовник. И все же ты можешь избежать ее. Скверна обретет власть над тобой, только если ты ей это позволишь.$B$BА сейчас иди... возвращайся, когда силы твои возрастут.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я знал, что ты придешь ко мне, $N. Не потому, что у тебя нет желания идти своим путем, а потому, что мы родственные души. Мы оба чувствовали боль. Мы оба страдали. И теперь мы хотим, чтобы власть вернула нам то, что мы знаем: эту землю, наши жизни, наши судьбы. Но тебе еще многому предстоит научиться.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3099,'Грязный свиток','А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника чернокнижников Максимиллиона. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.','Прочитайте свиток и поговорите с Максимиллионом в Похоронном Звоне.','Я говорил, что раб всегда останется рабом, кто бы ни был хозяином. Помнишь? Мы оба знаем, что именно этот тип контроля – этот самый вид силы – зовет нас. Мы хотим, чтобы существа служили нам. Мы знаем, что мы более могуществены и заслуживаем большего уважения, чем другие оказывают нам... и теперь мы хотим взять свое. \n\nЯ буду твоим союзником в этой борьбе – борьбе за нашу собственную свободу. Свободу искать своих собственных союзников. Когда почувствуешь, что время настало, возвращайся ко мне – и я научу тебя всему, что знаю.','Приветствую тебя, брат. Я знал, что твое появление – лишь вопрос времени. \n\nТо, что я сказал, заинтересовало тебя, не правда ли? Я задел правильную струну... нечто внутри тебя знало, что сказанное мною – правда. Хорошо. \n\nЗнай же: я не предаю Сильвану. Если уж на то пошло, она сама признала бы мою правоту, потому что ее собственные воззрения поставили Отрекшихся в то положение, в каком они находятся сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязный свиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, вот и ты! Пока ты $gразбирался:разбиралась; с безмозглыми тварями, тебе тут свиток прислали. Я думаю, в нем что-то важное, поскольку на нем, похоже, стоит печать наставника чернокнижников Максимиллиона. Я бы на твоем месте потратил время на его изучение, прежде чем пускаться в дальнейший путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте свиток и поговорите с Максимиллионом в Похоронном Звоне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я говорил, что раб всегда останется рабом, кто бы ни был хозяином. Помнишь? Мы оба знаем, что именно этот тип контроля – этот самый вид силы – зовет нас. Мы хотим, чтобы существа служили нам. Мы знаем, что мы более могуществены и заслуживаем большего уважения, чем другие оказывают нам... и теперь мы хотим взять свое. \n\nЯ буду твоим союзником в этой борьбе – борьбе за нашу собственную свободу. Свободу искать своих собственных союзников. Когда почувствуешь, что время настало, возвращайся ко мне – и я научу тебя всему, что знаю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя, брат. Я знал, что твое появление – лишь вопрос времени. \n\nТо, что я сказал, заинтересовало тебя, не правда ли? Я задел правильную струну... нечто внутри тебя знало, что сказанное мною – правда. Хорошо. \n\nЗнай же: я не предаю Сильвану. Если уж на то пошло, она сама признала бы мою правоту, потому что ее собственные воззрения поставили Отрекшихся в то положение, в каком они находятся сейчас.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3112,'Записка','Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне.','Прочитайте записку и поговорите с Траном Корманом в Холодной долине.','Да-да, теперь я окончательно понял, чего хотят гномы. И знаешь что? Даю слово, я сделаю все возможное, чтобы ты и твои родичи смогли отвоевать свой дом.\n\nДа, вот  еще что: когда почувствуешь, что готова к обучению, приходи к старине Трану – я с радостью поделюсь с тобой всем, что знаю. Конечно, не за просто так, но ты можешь не беспокоиться: цена невысока. Ну, до встречи!','О, а вот и еще один <гном>, отправляющийся на поиски приключений... Решимость в глазах, сжатые кулаки...\n\nНу ладно, ладно, успокойся, я вовсе не собирался тебя дразнить. Я, не поверишь, даже уважаю твою решимость. Судьба гномов мне отнюдь не безразлична – я вместе с вами скорблю о потере Гномрегана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Записка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте записку и поговорите с Траном Корманом в Холодной долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да, теперь я окончательно понял, чего хотят гномы. И знаешь что? Даю слово, я сделаю все возможное, чтобы ты и твои родичи смогли отвоевать свой дом.\n\nДа, вот  еще что: когда почувствуешь, что готова к обучению, приходи к старине Трану – я с радостью поделюсь с тобой всем, что знаю. Конечно, не за просто так, но ты можешь не беспокоиться: цена невысока. Ну, до встречи!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, а вот и еще один <гном>, отправляющийся на поиски приключений... Решимость в глазах, сжатые кулаки...\n\nНу ладно, ладно, успокойся, я вовсе не собирался тебя дразнить. Я, не поверишь, даже уважаю твою решимость. Судьба гномов мне отнюдь не безразлична – я вместе с вами скорблю о потере Гномрегана.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3113,'Зашифрованная записка','Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне.','Прочтите зашифрованную записку. Найдите Сольма Харгрина в Холодной долине и поговорите с ним.','Я стараюсь не привлекать к себе особого внимания, так что если где-то что-то и пропадает, наша репутация от этого не страдает. Если тебе потребуется чему-нибудь подучиться или еще что, приходи в любое время.$b$bНу, мы ведь с тобой друг друга понимаем? Мы-то знаем, что бывают времена, когда верить можно только семье... и такие времена сейчас настали, верно? Гномреган... захвачен, и, думаю, это была не последняя беда, которая на нас свалилась... но мы с тобой всегда прикроем друг другу спину, да?','Рад тебя здесь видеть – это значит, мое послание нашло адресата. Прости, что заставил тебя поверить, будто это послание от кого-то свыше. Понимаешь, таким, как мы, сейчас лучше держаться вместе.$b$bМногим кажется, что двум разбойникам в одном городе не ужиться, но я думаю, мы отлично сработаемся. Как ты считаешь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зашифрованная записка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите зашифрованную записку. Найдите Сольма Харгрина в Холодной долине и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я стараюсь не привлекать к себе особого внимания, так что если где-то что-то и пропадает, наша репутация от этого не страдает. Если тебе потребуется чему-нибудь подучиться или еще что, приходи в любое время.$b$bНу, мы ведь с тобой друг друга понимаем? Мы-то знаем, что бывают времена, когда верить можно только семье... и такие времена сейчас настали, верно? Гномреган... захвачен, и, думаю, это была не последняя беда, которая на нас свалилась... но мы с тобой всегда прикроем друг другу спину, да?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рад тебя здесь видеть – это значит, мое послание нашло адресата. Прости, что заставил тебя поверить, будто это послание от кого-то свыше. Понимаешь, таким, как мы, сейчас лучше держаться вместе.$b$bМногим кажется, что двум разбойникам в одном городе не ужиться, но я думаю, мы отлично сработаемся. Как ты считаешь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (3114,'Таинственная записка','Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Маррик, наставник магов. Если представится случай, отыщи его в Старой Наковальне.','Прочитайте таинственную записку. Найдите в Холодной долине Маррика Нуррибита и поговорите с ним.','Ну да, |3-6($r), я слушаю. В чем дело? Давай же, говори, в конце концов! Только учти, что после пары-тройки стаканов слух у меня становится не очень.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Таинственная записка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти ее, когда будет время. Думаю, записку прислал Маррик, наставник магов. Если представится случай, отыщи его в Старой Наковальне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте таинственную записку. Найдите в Холодной долине Маррика Нуррибита и поговорите с ним.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну да, |3-6($r), я слушаю. В чем дело? Давай же, говори, в конце концов! Только учти, что после пары-тройки стаканов слух у меня становится не очень.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3116,'Простой знак','Этот знак был передан мне посланником нашей наставницы воинов, Алайссии. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Алайссии.','Поговорите с Алайссией в Альдрассиле, что в Тенистой долине.','Вскоре ты увидишь на ветвях нашего дома представителей других рас – но не поддавайся предубеждению. Они здесь приняты как гости. Они помогут нам, когда смогут помочь. Не все они действуют из альтруизма, однако всем им можно в некоторой степени доверять. $B$BНо все это сейчас не в счет. Мы должны подумать о тебе и о том, как ты сможешь помочь нашему народу. Я здесь именно ради этого. Я буду учить тебя действовать как воин по мере того, как ты будешь обретать силу. Возвращайся ко мне, когда пожелаешь, – и я сделаю все возможное, чтобы помочь тебе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Простой знак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот знак был передан мне посланником нашей наставницы воинов, Алайссии. Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Алайссии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Алайссией в Альдрассиле, что в Тенистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вскоре ты увидишь на ветвях нашего дома представителей других рас – но не поддавайся предубеждению. Они здесь приняты как гости. Они помогут нам, когда смогут помочь. Не все они действуют из альтруизма, однако всем им можно в некоторой степени доверять. $B$BНо все это сейчас не в счет. Мы должны подумать о тебе и о том, как ты сможешь помочь нашему народу. Я здесь именно ради этого. Я буду учить тебя действовать как воин по мере того, как ты будешь обретать силу. Возвращайся ко мне, когда пожелаешь, – и я сделаю все возможное, чтобы помочь тебе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3121,'Странная просьба','Для начала мне понадобится помощь Ксераша Огненного Клинка из павильона Лорисс, что рядом с лагерем Мохаче! Он изготовил состав, который нужен мне для... ну, потом увидишь.$b$bВ общем, отправляйся к Огненному Клинку. Да, и захвати с собой вот это. Это мумифицированная голова, которую я обещал Ксерашу в обмен на его травки. Какой-то злосчастный дворф, с которым я повстречался в лесу... Думаю, Ксераш останется доволен.','Отнесите сушеную голову Ксерашу Огненному Клинку в павильон Лорисс в Фераласе.','О, я давно ждал, когда Узери ее пришлет…$B$BА вот и смесь трав, которую я изготовил для его... экспериментов.','Да?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странная просьба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для начала мне понадобится помощь Ксераша Огненного Клинка из павильона Лорисс, что рядом с лагерем Мохаче! Он изготовил состав, который нужен мне для... ну, потом увидишь.$b$bВ общем, отправляйся к Огненному Клинку. Да, и захвати с собой вот это. Это мумифицированная голова, которую я обещал Ксерашу в обмен на его травки. Какой-то злосчастный дворф, с которым я повстречался в лесу... Думаю, Ксераш останется доволен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сушеную голову Ксерашу Огненному Клинку в павильон Лорисс в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, я давно ждал, когда Узери ее пришлет…$B$BА вот и смесь трав, которую я изготовил для его... экспериментов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3122,'Возвращение к знахарю Узер\'и','Вот травы, $n. Отнеси их знахарю Узер\'и.$b$bИ, пожалуйста, передай ему, что сушеная голова – то, что надо.','Отнесите знахарю Узер\'и в Фералас мешочек для трав Ксераша.','Да, $N, это именно то, что мне нужно, чтобы изготовить сосуд уменьшения! Скоро увидим, так ли могущественны мои последние заклинания, как я рассчитывал!$B$BТак, минутку... Мне надо совершить ритуал и использовать травы...','Ну что, $Gпоговорил:поговорила; с Нееру?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к знахарю Узер\'и',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот травы, $n. Отнеси их знахарю Узер\'и.$b$bИ, пожалуйста, передай ему, что сушеная голова – то, что надо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите знахарю Узер\'и в Фералас мешочек для трав Ксераша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $N, это именно то, что мне нужно, чтобы изготовить сосуд уменьшения! Скоро увидим, так ли могущественны мои последние заклинания, как я рассчитывал!$B$BТак, минутку... Мне надо совершить ритуал и использовать травы...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $Gпоговорил:поговорила; с Нееру?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3123,'Испытание сосуда','Это будет испытание – испытание придуманного мною ритуала и твоих способностей. Возьми этот сосуд, $n. С его помощью ты сможешь уменьшать и помещать внутрь него разных существ.$b$bОтправляйся в дикие земли и отыщи диких существ. Медведи-сталемехи и длиннозубы-охотники станут твоей первой добычей, $n. Убивай этих существ и с помощью сосуда уменьшения возьми их души в плен, пока они не успели ускользнуть.','Убейте 10 медведей-сталемехов или длиннозубов-охотников, и используйте сосуд уменьшения, чтобы уменьшить и пленить их.$b$bОтнесите 10 уменьшенных зверей знахарю Узер\'и в Фералас.','Дух существа, преданного насильственной смерти, может вырваться на волю и попытаться отомстить. А помещая их в сосуд уменьшения, мы препятствуем духу вырваться на свободу. И теперь мы можем использовать его, как нам угодно!','Ну что, удалось тебе взять в плен дикосовухов?$B$BЕсли тебе это удастся, мы сможем подчинять себе и других существ Фераласа...','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание сосуда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это будет испытание – испытание придуманного мною ритуала и твоих способностей. Возьми этот сосуд, $n. С его помощью ты сможешь уменьшать и помещать внутрь него разных существ.$b$bОтправляйся в дикие земли и отыщи диких существ. Медведи-сталемехи и длиннозубы-охотники станут твоей первой добычей, $n. Убивай этих существ и с помощью сосуда уменьшения возьми их души в плен, пока они не успели ускользнуть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 медведей-сталемехов или длиннозубов-охотников, и используйте сосуд уменьшения, чтобы уменьшить и пленить их.$b$bОтнесите 10 уменьшенных зверей знахарю Узер\'и в Фералас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дух существа, преданного насильственной смерти, может вырваться на волю и попытаться отомстить. А помещая их в сосуд уменьшения, мы препятствуем духу вырваться на свободу. И теперь мы можем использовать его, как нам угодно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе взять в плен дикосовухов?$B$BЕсли тебе это удастся, мы сможем подчинять себе и других существ Фераласа...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3124,'Уменьшенный гиппогриф','Ты уже $gдоказал:доказала;, что на тебя можно положиться, и ты умеешь обращаться с сосудами уменьшения. Теперь я попрошу тебя пленить другое создание.$b$bГиппогрифы в течение многих лет были верными спутниками ночных эльфов, и души их тверды и преданны.$b$bТвоя задача – убить 10 блеклоперых гиппогрифов, быстро уменьшить их и загнать в сосуды, чтобы сохранить таким образом их души. Гиппогрифов можно найти в Высокогорных дебрях, к югу отсюда.','Убейте 10 блеклоперых гиппогрифов любого вида, затем используйте сосуд уменьшения, чтобы уменьшить и пленить их.','Если мы убьем существо и позволим его духу ускользнуть, оно может превратиться в куда более могущественное создание! И тогда оно будет вечно грозить нам местью.$B$BЯ поручил тебе опасную работу, $N. Но тебе удалось с ней справиться.','Ну что, удалось тебе взять в плен гиппогрифов?','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшенный гиппогриф',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gдоказал:доказала;, что на тебя можно положиться, и ты умеешь обращаться с сосудами уменьшения. Теперь я попрошу тебя пленить другое создание.$b$bГиппогрифы в течение многих лет были верными спутниками ночных эльфов, и души их тверды и преданны.$b$bТвоя задача – убить 10 блеклоперых гиппогрифов, быстро уменьшить их и загнать в сосуды, чтобы сохранить таким образом их души. Гиппогрифов можно найти в Высокогорных дебрях, к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 блеклоперых гиппогрифов любого вида, затем используйте сосуд уменьшения, чтобы уменьшить и пленить их.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если мы убьем существо и позволим его духу ускользнуть, оно может превратиться в куда более могущественное создание! И тогда оно будет вечно грозить нам местью.$B$BЯ поручил тебе опасную работу, $N. Но тебе удалось с ней справиться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе взять в плен гиппогрифов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3125,'Уменьшенный чудесный дракончик','$n, теперь я попрошу тебя отловить существо, которое на вид кажется довольно хилым, но дух его могуч, а это – именно то, что нам надо. Чудесные дракончики, о которых я говорю, были союзниками ночных эльфов. Нам надо поймать такого дракончика, чтобы Орда тоже могла воспользоваться силой его духа.$b$bУбей 8 летучих хамелеонов или радужных дракончиков, и плени их души. Эти существа водятся к западу отсюда.','Убейте 8 летучих хамелеонов или радужных дракончиков. Используйте сосуд уменьшения, чтобы заключить в них духи павших чудесных дракончиков.','Спасибо, $N! Теперь нам будет доступна сила духа лесных дракончиков.$B$BНадеюсь, ты не откажешься поработать на меня еще немного?','Спасибо, $N! Теперь нам будет доступна сила духа чудесных дракончиков.$B$BНадеюсь, ты не откажешься поработать на меня еще немного?','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшенный чудесный дракончик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, теперь я попрошу тебя отловить существо, которое на вид кажется довольно хилым, но дух его могуч, а это – именно то, что нам надо. Чудесные дракончики, о которых я говорю, были союзниками ночных эльфов. Нам надо поймать такого дракончика, чтобы Орда тоже могла воспользоваться силой его духа.$b$bУбей 8 летучих хамелеонов или радужных дракончиков, и плени их души. Эти существа водятся к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 летучих хамелеонов или радужных дракончиков. Используйте сосуд уменьшения, чтобы заключить в них духи павших чудесных дракончиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N! Теперь нам будет доступна сила духа лесных дракончиков.$B$BНадеюсь, ты не откажешься поработать на меня еще немного?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Спасибо, $N! Теперь нам будет доступна сила духа чудесных дракончиков.$B$BНадеюсь, ты не откажешься поработать на меня еще немного?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3126,'Уменьшенный древень','Следующей нашей добычей, $n, станут бродячие лесные великаны, живые деревья. Ночные эльфы считают древней своими союзниками в борьбе против Орды. Движения древней медлительны, но в качестве защитников они незаменимы!$b$bИ вскоре мы сможем использовать их мощь в своих целях.$b$bОтыщи 3 бродячих лесных древней, убей их и используй этот сосуд уменьшения, чтобы пленить их души!','Убейте 3 бродячих лесных древней. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших древней.','Спасибо, $N! Наше собрание уменьшенных существ почти готово...','Ну что, удалось тебе взять в плен души бродячих древней?','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшенный древень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следующей нашей добычей, $n, станут бродячие лесные великаны, живые деревья. Ночные эльфы считают древней своими союзниками в борьбе против Орды. Движения древней медлительны, но в качестве защитников они незаменимы!$b$bИ вскоре мы сможем использовать их мощь в своих целях.$b$bОтыщи 3 бродячих лесных древней, убей их и используй этот сосуд уменьшения, чтобы пленить их души!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 бродячих лесных древней. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших древней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N! Наше собрание уменьшенных существ почти готово...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе взять в плен души бродячих древней?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3127,'Уменьшенный горный великан','Последнее, что от тебя потребуется – это отправиться на северо-запад и отыскать основного противника.$b$bКогда Пылающий Легион явился в мир, горные великаны спустились с гор, чтобы помогать ночным эльфам. Ты без труда обнаружишь их: они огромного роста, и когда они поблизости, земля начинает дрожать под ногами.$b$bЯ жажду подчинить себе подобную мощь! Убей 7 горных великанов и используй сосуд уменьшения, чтобы пленить их могучие души!','Убейте 7 сухопутных бродяг или скальных великанов. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших скальных великанов.','Только представь себе, $N, какими возможностями мы теперь обладаем! С теми материалами, которые тебе удалось собрать, я могу сколько угодно уловлять души этих созданий.','Ну что, удалось тебе взять в плен горных великанов?','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшенный горный великан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последнее, что от тебя потребуется – это отправиться на северо-запад и отыскать основного противника.$b$bКогда Пылающий Легион явился в мир, горные великаны спустились с гор, чтобы помогать ночным эльфам. Ты без труда обнаружишь их: они огромного роста, и когда они поблизости, земля начинает дрожать под ногами.$b$bЯ жажду подчинить себе подобную мощь! Убей 7 горных великанов и используй сосуд уменьшения, чтобы пленить их могучие души!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 сухопутных бродяг или скальных великанов. Используйте сосуд уменьшения, чтобы уменьшить и пленить павших скальных великанов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Только представь себе, $N, какими возможностями мы теперь обладаем! С теми материалами, которые тебе удалось собрать, я могу сколько угодно уловлять души этих созданий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе взять в плен горных великанов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3128,'Натуральные ингредиенты','Для выполнения моего замысла мне нужны некоторые материалы... Будешь выполнять другие мои поручения – поищи заодно и то, что я тебя попрошу.$b$bВо-первых, расколотый ствол фераласского древня. Во-вторых, покрытые коркой минералы – эти можно добыть у горных великанов и чудесных дракончиков на западе. Кроме этого, добудь мне упругих сухожилий совухов из Внутренних земель либо гиппогрифов из Фераласа. И, наконец, мне потребуется большое количество металлических фрагментов, какие найдутся у любого из перечисленных созданий.','Принесите 2 расколотых бревна, 6 минералов, покрытых коркой, 20 кусков упругих сухожилий и 40 металлических фрагментов знахарю Узер\'и в Лагерь Мохаче.','Отлично! Все это, вкупе с духами животных, позволит мне изготовить именно то, что нужно!','Ну что, удалось тебе собрать нужные материалы?','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Натуральные ингредиенты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для выполнения моего замысла мне нужны некоторые материалы... Будешь выполнять другие мои поручения – поищи заодно и то, что я тебя попрошу.$b$bВо-первых, расколотый ствол фераласского древня. Во-вторых, покрытые коркой минералы – эти можно добыть у горных великанов и чудесных дракончиков на западе. Кроме этого, добудь мне упругих сухожилий совухов из Внутренних земель либо гиппогрифов из Фераласа. И, наконец, мне потребуется большое количество металлических фрагментов, какие найдутся у любого из перечисленных созданий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 расколотых бревна, 6 минералов, покрытых коркой, 20 кусков упругих сухожилий и 40 металлических фрагментов знахарю Узер\'и в Лагерь Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Все это, вкупе с духами животных, позволит мне изготовить именно то, что нужно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе собрать нужные материалы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Узер\'и в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3129,'Оружие духа','Вселить дух животного в оружие – процесс непростой! Теперь, когда у меня есть все необходимые материалы и души пойманных тобой созданий, я могу приступить к делу. Погоди немного, я скоро вернусь.','Подождите, пока знахарь Узер\'и готовит оружие.','Ну что ж, $N, выбирай, что тебе больше по нраву! В это оружие навечно заточены души могучих созданий.$B$BТеперь их сила – твоя сила.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вселить дух животного в оружие – процесс непростой! Теперь, когда у меня есть все необходимые материалы и души пойманных тобой созданий, я могу приступить к делу. Погоди немного, я скоро вернусь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подождите, пока знахарь Узер\'и готовит оружие.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что ж, $N, выбирай, что тебе больше по нраву! В это оружие навечно заточены души могучих созданий.$B$BТеперь их сила – твоя сила.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3130,'Борьба с Гребнем Ненависти','В данный момент я собираюсь направить тебя к своему заместителю, Латроникусу. Он следит за боевыми приготовлениями наг. Сама же я буду продолжать осуществлять общее наблюдение. Как бы мне ни хотелось нанести им удар всеми имеющимися у нас силами, оставить крепость беззащитной перед атаками Орды – а может быть, и кого-то похуже, – не представляется разумным.$b$bКак бы то ни было, Латроникус тебя ждет. Пока что ты $gпоказал:показала; себя молодцом, $n. Продолжай в том же духе!$b$bМожешь идти.','Явитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны.','Что ж, $N, отлично: я ценю готовность сражаться в тех, с кем имею дело.$B$BГенерал Лунное Перо поручила мне подготовить нападение на наг. Мои планы состоят из двух частей: во-первых, мы ослабим их силы и лишим командования, а во-вторых, выясним, что же они делают в этих развалинах. С твоей помощью мы сумеем задать нагам перцу, не ослабляя защиты крепости.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба с Гребнем Ненависти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В данный момент я собираюсь направить тебя к своему заместителю, Латроникусу. Он следит за боевыми приготовлениями наг. Сама же я буду продолжать осуществлять общее наблюдение. Как бы мне ни хотелось нанести им удар всеми имеющимися у нас силами, оставить крепость беззащитной перед атаками Орды – а может быть, и кого-то похуже, – не представляется разумным.$b$bКак бы то ни было, Латроникус тебя ждет. Пока что ты $gпоказал:показала; себя молодцом, $n. Продолжай в том же духе!$b$bМожешь идти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, $N, отлично: я ценю готовность сражаться в тех, с кем имею дело.$B$BГенерал Лунное Перо поручила мне подготовить нападение на наг. Мои планы состоят из двух частей: во-первых, мы ослабим их силы и лишим командования, а во-вторых, выясним, что же они делают в этих развалинах. С твоей помощью мы сумеем задать нагам перцу, не ослабляя защиты крепости.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (3141,'Лорам','Так ты хочешь вступить в сражение с демонами? Тебе лучше для начала услышать то, что я скажу.','Послушайте, как Лорам Многоног рассказывает свою историю.','Да будет так...','Не перебивай меня, $R.','История Лорама','Вернитесь к Лораму Многоногу на Залив Бурь, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так ты хочешь вступить в сражение с демонами? Тебе лучше для начала услышать то, что я скажу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Послушайте, как Лорам Многоног рассказывает свою историю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да будет так...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не перебивай меня, $R.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','История Лорама',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лораму Многоногу на Залив Бурь, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3161,'Газ\'рилльское украшение','Я ученый, но в душе – кладоискатель!$b$bДавным-давно, когда в этих землях жили тролли, они обожествляли Газ\'риллу, огромную гидру, и создали множество украшений в форме ее тела. Их вырезали из особого материала, я называю его "газ\'риллий" в честь богини-гидры.$b$bЯ и сам ухитрился найти несколько образцов, но для исследований этого не хватает – может, ты мне еще принесешь?$b$bЯ даже создал детектор, позволяющий мигом обнаружить газ\'риллий! Надень его и приступай к поискам!','Марвон Клепальщик из Танариса поручил собрать 30 газ\'рилловых украшений.','Вернитесь к Марвону Клепальщику к Разбитой Колонне, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Газ\'рилльское украшение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я ученый, но в душе – кладоискатель!$b$bДавным-давно, когда в этих землях жили тролли, они обожествляли Газ\'риллу, огромную гидру, и создали множество украшений в форме ее тела. Их вырезали из особого материала, я называю его "газ\'риллий" в честь богини-гидры.$b$bЯ и сам ухитрился найти несколько образцов, но для исследований этого не хватает – может, ты мне еще принесешь?$b$bЯ даже создал детектор, позволяющий мигом обнаружить газ\'риллий! Надень его и приступай к поискам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Марвон Клепальщик из Танариса поручил собрать 30 газ\'рилловых украшений.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марвону Клепальщику к Разбитой Колонне, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3181,'Рог чудовища','Гигантский рог испещрен многочисленными сколами и царапинами, кроме того, из него торчит непонятный металлический предмет. $B$BОсмотрев рог более внимательно, вы понимаете, что металлический предмет есть ничто иное как обух секиры, сорванный с рукояти. На нем виднеется гравировка:$B$B"Принадлежит горному пехотинцу Щебеночке".$B$BКогда вы пытаетесь вытащить обух секиры из рога, он рассыпается на кусочки. $B$BОпаньки...','Отнести гигантский рог Маргульи горному пехотинцу Щебеночке.','Что это у тебя? Бессовестная подделка, вестимо!$B$BЯ встречалась с Марголом один на один, и могу ответственно заявить тебе – рог у него раз в восемь больше, чем вот эта твоя закорючка! Небось, $Gвыдрал:выдрала; ее из какого-нибудь несчастного грозорыла в Степях. Нет, $Gмилый:милая;, ты не обманешь Щебеночку!','Нет, я не открою тебе ворота.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рог чудовища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гигантский рог испещрен многочисленными сколами и царапинами, кроме того, из него торчит непонятный металлический предмет. $B$BОсмотрев рог более внимательно, вы понимаете, что металлический предмет есть ничто иное как обух секиры, сорванный с рукояти. На нем виднеется гравировка:$B$B"Принадлежит горному пехотинцу Щебеночке".$B$BКогда вы пытаетесь вытащить обух секиры из рога, он рассыпается на кусочки. $B$BОпаньки...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнести гигантский рог Маргульи горному пехотинцу Щебеночке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это у тебя? Бессовестная подделка, вестимо!$B$BЯ встречалась с Марголом один на один, и могу ответственно заявить тебе – рог у него раз в восемь больше, чем вот эта твоя закорючка! Небось, $Gвыдрал:выдрала; ее из какого-нибудь несчастного грозорыла в Степях. Нет, $Gмилый:милая;, ты не обманешь Щебеночку!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нет, я не открою тебе ворота.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3182,'Подтверждение подлинности','Ты думаешь, я поверю этим россказням? Если бы это был настоящий рог, из него до сих пор торчал бы обух моей секиры.$B$BВот что, неси-ка свою подделку смотрителю Ториусу в Стальгорн. Если он признает, что твои слова – правда, он даст тебе доказательство. Принеси его мне, и я дам тебе ключ к Тлеющему ущелью.$B$BИди, иди!','Отнесите гигантский рог Маргульи смотрителю Ториусу в Стальгорн.','Что это?$B$BЯ не могу поверить! Вы понимаете, что это, |3-6($R)? Это же рог Маргола Яростеня! Маргола, причины гибели множества археологов, оказавшихся в Тлеющем ущелье.$B$BМожно мне оставить его себе?','Приветствую вас, $N! Желаете экскурсию по музею?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подтверждение подлинности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты думаешь, я поверю этим россказням? Если бы это был настоящий рог, из него до сих пор торчал бы обух моей секиры.$B$BВот что, неси-ка свою подделку смотрителю Ториусу в Стальгорн. Если он признает, что твои слова – правда, он даст тебе доказательство. Принеси его мне, и я дам тебе ключ к Тлеющему ущелью.$B$BИди, иди!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите гигантский рог Маргульи смотрителю Ториусу в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это?$B$BЯ не могу поверить! Вы понимаете, что это, |3-6($R)? Это же рог Маргола Яростеня! Маргола, причины гибели множества археологов, оказавшихся в Тлеющем ущелье.$B$BМожно мне оставить его себе?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую вас, $N! Желаете экскурсию по музею?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3201,'Наконец-то!','Не может быть, чтобы Щебеночка усомнилась в подлинности рога. Между нами говоря, думаю, она просто ревнует. Я знаю, она хотела убить чудовище сама.$B$BТак вам, значит, нужно доказательство. Разумеется, вы принесли музею столь ценный дар, что я почту за честь написать для вас свидетельство. $B$B*Смотритель Ториус начинает заполнять огромный документ* $B$BНу вот, можете показать его Щебеночке.','Отнесите доказательство содеянного горному пехотинцу Щебеночке.','Не понимаю, как $Gмог:могла; $Gтакой:такая; $Gслабак:слабачка;, как ты, одолеть Маргола, но я хозяйка своего слова.$B$BНо если после этого с тобой случится что-то нехорошее, пеняй на себя!','Глазам своим не верю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наконец-то!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не может быть, чтобы Щебеночка усомнилась в подлинности рога. Между нами говоря, думаю, она просто ревнует. Я знаю, она хотела убить чудовище сама.$B$BТак вам, значит, нужно доказательство. Разумеется, вы принесли музею столь ценный дар, что я почту за честь написать для вас свидетельство. $B$B*Смотритель Ториус начинает заполнять огромный документ* $B$BНу вот, можете показать его Щебеночке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите доказательство содеянного горному пехотинцу Щебеночке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не понимаю, как $Gмог:могла; $Gтакой:такая; $Gслабак:слабачка;, как ты, одолеть Маргола, но я хозяйка своего слова.$B$BНо если после этого с тобой случится что-то нехорошее, пеняй на себя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Глазам своим не верю.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3221,'Беседа с Ренферрелом','Поговорите с аптекарем Ренферрелом в Гробнице.','О, хорошо, что вы пришли. Касательно тех волчьих сердец, что вы мне ранее принесли – есть один момент, требующий вашего внимания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беседа с Ренферрелом',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с аптекарем Ренферрелом в Гробнице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, хорошо, что вы пришли. Касательно тех волчьих сердец, что вы мне ранее принесли – есть один момент, требующий вашего внимания.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (3241,'<NYI> <TXT><redux> Вершина Багрового Тумана','Соберите тотемы Вершины Багрового Тумана, потому что там теперь гадко, и хорошеньким чистым тотемам там не место.','Принесите тотемы Тонге Руническому Тотему.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT><redux> Вершина Багрового Тумана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Соберите тотемы Вершины Багрового Тумана, потому что там теперь гадко, и хорошеньким чистым тотемам там не место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите тотемы Тонге Руническому Тотему.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3261,'[DEPRECATED in 4.x] Джорн Заклинатель Небес','Вот и закончились наши уроки, $n. Не останавливайся на достигнутом, ступай в Лагерь Таурахо на юге и поговори с Джорном Заклинателем Небес. Он станет твоим новым учителем.','Приветствую тебя, юноша. Ты избрал путь охотника?\n\nЗамечательно. Начнем с азов.','Я весьма заинтересован в том, чтобы исследовать шкуры этих тварей, наводнивших Пещеры Стенаний. Как успехи, |3-6($C)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED in 4.x] Джорн Заклинатель Небес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот и закончились наши уроки, $n. Не останавливайся на достигнутом, ступай в Лагерь Таурахо на юге и поговори с Джорном Заклинателем Небес. Он станет твоим новым учителем.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую тебя, юноша. Ты избрал путь охотника?\n\nЗамечательно. Начнем с азов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я весьма заинтересован в том, чтобы исследовать шкуры этих тварей, наводнивших Пещеры Стенаний. Как успехи, |3-6($C)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (3281,'[DEPRECATED] Похищенное серебро','Ящеров-то ты $gубил:убила;, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров. Скорее всего они утащили похищенное серебро именно туда.$B$BОтправляйся в логово мерзких тварей и поищи наше серебро. Как найдешь – сразу возвращайся ко мне.','Принесите украденное серебро Газрогу в Перекресток.','И где серебро?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Похищенное серебро',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ящеров-то ты $gубил:убила;, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров. Скорее всего они утащили похищенное серебро именно туда.$B$BОтправляйся в логово мерзких тварей и поищи наше серебро. Как найдешь – сразу возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите украденное серебро Газрогу в Перекресток.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И где серебро?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3301,'Муура Рунический Тотем','Одна из моих соплеменниц, Муура Рунический Тотем, отправилась в Серебряный бор на помощь нашим союзникам-нежити. Серебряный бор – больной, вымирающий лес, и Муура надеялась вдохнуть в него новую жизнь. Может быть, необычные обитатели Степей подскажут ей, как лучше выполнить задачу.$B$BВозьми образец добытых тобой панцирей и отнеси его Мууре в Серебряный бор. Она остановилась в Гробнице. При удаче, осмотрев панцирь, она придумает, как исцелить это погибающее место.','Поговорите с Муурой Руническим Тотемом в Гробнице, что в Серебряном бору.','Я чувствую, от тебя пахнет пылью Степей, |3-6($C). Ты издалека пришел.','Поговорите с Муурой Рунический Тотем в Гробнице в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Муура Рунический Тотем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна из моих соплеменниц, Муура Рунический Тотем, отправилась в Серебряный бор на помощь нашим союзникам-нежити. Серебряный бор – больной, вымирающий лес, и Муура надеялась вдохнуть в него новую жизнь. Может быть, необычные обитатели Степей подскажут ей, как лучше выполнить задачу.$B$BВозьми образец добытых тобой панцирей и отнеси его Мууре в Серебряный бор. Она остановилась в Гробнице. При удаче, осмотрев панцирь, она придумает, как исцелить это погибающее место.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Муурой Руническим Тотемом в Гробнице, что в Серебряном бору.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую, от тебя пахнет пылью Степей, |3-6($C). Ты издалека пришел.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Муурой Рунический Тотем в Гробнице в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (3321,'Не ее ли ищете?','Ты много $gсделал:сделала; для Ордена, $n. Обычный искатель приключений не выдержал бы такой нагрузки. Ни я, ни Гальван не сомневаемся, что ты $gстал одним:стала одной; из нас.$b$bПоэтому мне кажется, что ты заслуживаешь награды. Сущий пустяк, побрякушку. Может быть, ты знаешь о ее свойствах. Должно быть, именно из-за них ты и $gпришел:пришла; к нам.','Дождитесь, пока Трентон закончит работу.','Понаблюдать за работой Трентона','Вернитесь к Трентону Молоту Света в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не ее ли ищете?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты много $gсделал:сделала; для Ордена, $n. Обычный искатель приключений не выдержал бы такой нагрузки. Ни я, ни Гальван не сомневаемся, что ты $gстал одним:стала одной; из нас.$b$bПоэтому мне кажется, что ты заслуживаешь награды. Сущий пустяк, побрякушку. Может быть, ты знаешь о ее свойствах. Должно быть, именно из-за них ты и $gпришел:пришла; к нам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока Трентон закончит работу.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Понаблюдать за работой Трентона',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Трентону Молоту Света в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (3321,'Rise and be recognized, $n, blacksmith of the Mithril Order.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Rise and be recognized, $n, blacksmith of the Mithril Order.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3341,'Да сгинет Хладовей','В Степях есть уголок, заросший кошмарными колючками. Он называется Курганы Иглошкурых. Хотя с первого взгляда это место не показалось нам опасным, по последним сведениям все куда серьезнее...$B$BЖивущие в холмах свинобразы поддались злому влиянию Плети. Теперь их действиями руководит лич по имени Амненнар Хладовей.$B$BУ Амненнара прямая телепатическая связь с Нер\'зулом; мы должны прервать ее, $n. Да сгинет Хладовей!','Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп.','Вернитесь к Эндрю Браунеллу в Тирисфальские леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Да сгинет Хладовей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Степях есть уголок, заросший кошмарными колючками. Он называется Курганы Иглошкурых. Хотя с первого взгляда это место не показалось нам опасным, по последним сведениям все куда серьезнее...$B$BЖивущие в холмах свинобразы поддались злому влиянию Плети. Теперь их действиями руководит лич по имени Амненнар Хладовей.$B$BУ Амненнара прямая телепатическая связь с Нер\'зулом; мы должны прервать ее, $n. Да сгинет Хладовей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эндрю Браунеллу в Тирисфальские леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3361,'Беда беженца','Найдите ящик, сундук и ведро с гайками, принадлежащие Феликсу.','Вернитесь к Феликсу Ремонтуару в лагерь Белоборода, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беда беженца',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ящик, сундук и ведро с гайками, принадлежащие Феликсу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Феликсу Ремонтуару в лагерь Белоборода, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3362,'Долина Кактусов','Ты когда-нибудь $gбыл:была; в Долине Кактусов? Это опасное место, $n.$b$bТам такие жуткие твари, я к ним и близко не подойду! Бугристые шипокожи и терновые корнеплеты, кажется так они зовутся...$b$bТак или иначе, я хочу попасть в эту долину, но пока там столько шипокожей, ноги моей там не будет. Вот зачем ты мне $gнужен:нужна; – если перебить часть этих тварей, я могу и решиться на поход. Что скажешь, $n? Поможешь мне?','Тран\'рек из Прибамбасска велит убить 8 бугристых шипокожей и 8 терновых корнеплетов.','Вернитесь к Тран\'реку в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долина Кактусов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты когда-нибудь $gбыл:была; в Долине Кактусов? Это опасное место, $n.$b$bТам такие жуткие твари, я к ним и близко не подойду! Бугристые шипокожи и терновые корнеплеты, кажется так они зовутся...$b$bТак или иначе, я хочу попасть в эту долину, но пока там столько шипокожей, ноги моей там не будет. Вот зачем ты мне $gнужен:нужна; – если перебить часть этих тварей, я могу и решиться на поход. Что скажешь, $n? Поможешь мне?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тран\'рек из Прибамбасска велит убить 8 бугристых шипокожей и 8 терновых корнеплетов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тран\'реку в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (3363,'Оскверненный песнецвет','Вернитесь к оскверненному песнецвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный песнецвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному песнецвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3364,'Жгучая бражка','Я уже давно должен был доставить эту отличнейшую жгучую бражку в Старую Наковальню Дарнану Мехорезу, да только сначала мне нужно было завезти немного Грелину. Боюсь, к тому времени, как я доберусь до Старой Наковальни, остынет бражка-то!$b$bТы на ногу полегче моего будешь, как я погляжу; вот я и подумал... эта кружка останется горячей еще минут пять, а Дарнан вовсе не охлажденную бражку заказывал, – не пиво, чай! – так что отправляйся-ка ты в путь. Старая Наковальня – это такое поселение в скалах к северо-востоку отсюда.$b$bБлагодарю заранее... и вот еще что, $n: не забудь вернуть мою кружку!','Отнести жгучую бражку в Старую Наковальню и передать ее Дарнану Мехорезу. Это надо сделать за пять минут, пока бражка не остыла!','Отлично! Это именно то, что нужно! Ты погоди пока, эту штуку пить надо, пока не остыла, иначе вкуса того не будет.','Ну да. Я и есть Дарнан Мехорез. И какое у тебя ко мне дело?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жгучая бражка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже давно должен был доставить эту отличнейшую жгучую бражку в Старую Наковальню Дарнану Мехорезу, да только сначала мне нужно было завезти немного Грелину. Боюсь, к тому времени, как я доберусь до Старой Наковальни, остынет бражка-то!$b$bТы на ногу полегче моего будешь, как я погляжу; вот я и подумал... эта кружка останется горячей еще минут пять, а Дарнан вовсе не охлажденную бражку заказывал, – не пиво, чай! – так что отправляйся-ка ты в путь. Старая Наковальня – это такое поселение в скалах к северо-востоку отсюда.$b$bБлагодарю заранее... и вот еще что, $n: не забудь вернуть мою кружку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнести жгучую бражку в Старую Наковальню и передать ее Дарнану Мехорезу. Это надо сделать за пять минут, пока бражка не остыла!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Это именно то, что нужно! Ты погоди пока, эту штуку пить надо, пока не остыла, иначе вкуса того не будет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну да. Я и есть Дарнан Мехорез. И какое у тебя ко мне дело?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (3365,'Возвращение кружки','Ох, хорошо-то как! Все эти прохладительные напитки – полная ерунда: в морозный денек нет ничего лучше глотка горячей бражки! Даже на душе теплее становится!$b$bВот, держи, $n; сделай доброе дело, отнеси эту кружку Нори, ладно?','Отнесите кружку хозяину – Нори по прозвищу Гордый Штрек. Он обитает в Холодной долине.','Я так понимаю, жгучая бражка попала к старине Дарнану как раз вовремя! А как моя кружка? Надеюсь, ты не забыла, что ее надо было принести обратно?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение кружки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, хорошо-то как! Все эти прохладительные напитки – полная ерунда: в морозный денек нет ничего лучше глотка горячей бражки! Даже на душе теплее становится!$b$bВот, держи, $n; сделай доброе дело, отнеси эту кружку Нори, ладно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кружку хозяину – Нори по прозвищу Гордый Штрек. Он обитает в Холодной долине.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я так понимаю, жгучая бражка попала к старине Дарнану как раз вовремя! А как моя кружка? Надеюсь, ты не забыла, что ее надо было принести обратно?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`) VALUES (3366,'Светящийся осколок','Светящийся осколок ярко-зеленый, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство.$B$BПожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке.','Отправляйтесь в Кабестан и выясните, какие секреты скрывает кошмарный осколок.','Поговорите с кем-нибудь о кошмарном осколке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Светящийся осколок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Светящийся осколок ярко-зеленый, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство.$B$BПожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Кабестан и выясните, какие секреты скрывает кошмарный осколок.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поговорите с кем-нибудь о кошмарном осколке.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (3367,'Камни Сунтары','<Из груди Дориуса вырывается стон> $B$BЯ тяжело ранен, |3-6($r). Ужасно кружится голова... Думаю, у меня внутреннее кровотечение... $B$BМне нужно добраться обратно в Стальгорн. Помоги мне, $n.','Помогите Дориусу вернуться в Стальгорн.','Письмо выронил Дориус, когда падал.','Мне не дойти...','Сопровождение Дориуса','Заберите опаленное письмо в Тлеющем ущелье.','Сопровождение Дориуса') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камни Сунтары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Из груди Дориуса вырывается стон> $B$BЯ тяжело ранен, |3-6($r). Ужасно кружится голова... Думаю, у меня внутреннее кровотечение... $B$BМне нужно добраться обратно в Стальгорн. Помоги мне, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Дориусу вернуться в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Письмо выронил Дориус, когда падал.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне не дойти...',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сопровождение Дориуса',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Заберите опаленное письмо в Тлеющем ущелье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Сопровождение Дориуса',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (3368,'Камни Сунтары','Брат! $B$BЕсли ты читаешь эти строки, меня уже нет в живых. Не знаю, кто доставил тебе письмо, но непременно поблагодари и вознагради его. $B$BТеперь о камнях: они существуют и сейчас находятся у клана Черного Железа. С помощью этих камней их главарь, Латорик Черный, удерживает моих соратников по экспедиции в плену. Лишенные рассудка, они день и ночь трудятся над созданием монстра, именуемого Обсидионом. $B$BСпаси их, брат. Это моя последняя воля. $B$BДориус.','Доставьте опаленное письмо Ториусу в Стальгорн. Его можно найти в Зале Исследователей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камни Сунтары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Брат! $B$BЕсли ты читаешь эти строки, меня уже нет в живых. Не знаю, кто доставил тебе письмо, но непременно поблагодари и вознагради его. $B$BТеперь о камнях: они существуют и сейчас находятся у клана Черного Железа. С помощью этих камней их главарь, Латорик Черный, удерживает моих соратников по экспедиции в плену. Лишенные рассудка, они день и ночь трудятся над созданием монстра, именуемого Обсидионом. $B$BСпаси их, брат. Это моя последняя воля. $B$BДориус.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте опаленное письмо Ториусу в Стальгорн. Его можно найти в Зале Исследователей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3369,'Тебя послала Фалла? Давай-ка, взглянем на этот осколок…\n\nХамуул вглядывается в осколок.\n\nОх... Боги…\n\nСпасибо, что принес это мне. О таких вещах вслух не говорят, но я все же предупрежу тебя, есть вещи, с которыми ты можешь не справиться.\n\nЗапомни, в Изумрудном сне все не то, чем кажется...\n\nВозможно в будущем мы встретимся вновь.','Могу я тебе чем-то помочь?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послала Фалла? Давай-ка, взглянем на этот осколок…\n\nХамуул вглядывается в осколок.\n\nОх... Боги…\n\nСпасибо, что принес это мне. О таких вещах вслух не говорят, но я все же предупрежу тебя, есть вещи, с которыми ты можешь не справиться.\n\nЗапомни, в Изумрудном сне все не то, чем кажется...\n\nВозможно в будущем мы встретимся вновь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Могу я тебе чем-то помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3370,'Кошмары','Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Но это осколок не сна, а скорее кошмара.$B$BНе хочу тревожить тебя, $n, но лучше будет, отдать его кому-то из старших друидов, как только сможешь.$B$BМатренгил Медвежья Лапа из Круга Кенария, вот кого тебе надо найти. Отправляйся в Дарнас, точнее сказать не могу.','Принесите кошмарный осколок Матренгилу Медвежьей Лапе в Дарнас.','Тебя послала Фалла? Давай-ка, взглянем на этот осколок…$B$BМатренгил вглядывается в осколок.$B$BОх... Боги…$B$BСпасибо, что принес это мне. О таких вещах вслух не говорят, но я все же предупрежу тебя, есть вещи, с которыми ты можешь не справиться.$B$BЗапомни, в Изумрудном сне все не то, чем кажется...$B$BВозможно в будущем мы встретимся вновь.','Могу я тебе чем-то помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кошмары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Но это осколок не сна, а скорее кошмара.$B$BНе хочу тревожить тебя, $n, но лучше будет, отдать его кому-то из старших друидов, как только сможешь.$B$BМатренгил Медвежья Лапа из Круга Кенария, вот кого тебе надо найти. Отправляйся в Дарнас, точнее сказать не могу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите кошмарный осколок Матренгилу Медвежьей Лапе в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послала Фалла? Давай-ка, взглянем на этот осколок…$B$BМатренгил вглядывается в осколок.$B$BОх... Боги…$B$BСпасибо, что принес это мне. О таких вещах вслух не говорят, но я все же предупрежу тебя, есть вещи, с которыми ты можешь не справиться.$B$BЗапомни, в Изумрудном сне все не то, чем кажется...$B$BВозможно в будущем мы встретимся вновь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Могу я тебе чем-то помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3371,'Правосудие дворфов','Теперь в груди моей зияет черная дыра – там, где было когда-то сердце... Я никогда не смогу смириться с гибелью Дориуса, $n. Я сделаю все, чтобы его последняя воля была исполнена – тех, на ком его кровь, должна настигнуть суровая кара. $B$BВозвращайся в Тлеющее ущелье и исполни волю Дориуса – освободи его соратников. Дворфы Черного Железа заставляют своих рабов трудиться в раскаленной шахте, именуемой Шлаковой Ямой.','Вернитесь в Тлеющее ущелье и найдите археологов Дориуса.','Оставь меня, спасай остальных!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правосудие дворфов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь в груди моей зияет черная дыра – там, где было когда-то сердце... Я никогда не смогу смириться с гибелью Дориуса, $n. Я сделаю все, чтобы его последняя воля была исполнена – тех, на ком его кровь, должна настигнуть суровая кара. $B$BВозвращайся в Тлеющее ущелье и исполни волю Дориуса – освободи его соратников. Дворфы Черного Железа заставляют своих рабов трудиться в раскаленной шахте, именуемой Шлаковой Ямой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Тлеющее ущелье и найдите археологов Дориуса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Оставь меня, спасай остальных!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3372,'Отпусти их','Отпусти их, |3-6($r). Даже когда их тела совсем обессилят, власть Сунтары заставляет их достичь цели любой ценой. $B$BВсе дело в алтаре Сунтары. Отправляйся на северо-запад, там, в холмах над пещерой... Сумеречный Молот хранит реликвию. Добудь ее и возложи на алтарь Сунтары.$B$B*С этими словами умирающий археолог испускает дух*.','Найдите таинственный артефакт, охраняемый идолослужителями Сумеречного Молота в северо-западной области Тлеющего ущелья и возложите его на алтарь Сунтары в Шлаковой Яме.','Вы возлагаете таинственный артефакт на алтарь Сунтары.','Алтарь пуст.','Вернитесь к алтарю Сунтары на Гряду Огненной стражи, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отпусти их',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отпусти их, |3-6($r). Даже когда их тела совсем обессилят, власть Сунтары заставляет их достичь цели любой ценой. $B$BВсе дело в алтаре Сунтары. Отправляйся на северо-запад, там, в холмах над пещерой... Сумеречный Молот хранит реликвию. Добудь ее и возложи на алтарь Сунтары.$B$B*С этими словами умирающий археолог испускает дух*.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите таинственный артефакт, охраняемый идолослужителями Сумеречного Молота в северо-западной области Тлеющего ущелья и возложите его на алтарь Сунтары в Шлаковой Яме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы возлагаете таинственный артефакт на алтарь Сунтары.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Алтарь пуст.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алтарю Сунтары на Гряду Огненной стражи, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3373,'Сущность Эраникуса','Вы касаетесь камня и слышите голос, звучащий в вашем сознании.$B$B"Услышь мою мольбу, о $gсмертный:смертная;. Имя мне Эраникус из народа зеленых драконов. Мои попытки положить конец богохульным деяниям троллей закончились неудачей. Я вдохнул частицу своей души в этот кристалл. Однако я чувствую, что моя связь с Изумрудным Сном теряется, и меня поглощает хаос. Пожалуйста, помести этот кристалл в купель сущности в моем логове – пусть магия очистит мое сознание от скверны и спасет меня!"','Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме.','Вы помещаете камень в купель сущности. $B$B"Благодарю тебя, смертный теперь я... О нет! Не может быть! Скверна проклятого бога проникла даже в эту купель! Умоляю! Я чувствую, как сознание покидает меня! БОЛЬНО! Я чувствую, как мою душу поглощает вечный кошмар!"$B$B"Умоляю тебя, смертный, Найди одного из зеленых драконов, чтобы он смог прекратить мои мучения! Помоги мне! Я обречен на вечную агонию... Пощади!"','Приблизившись к купели, о которой говорил Эраникус, вы снова слышите его голос. $B$B"Да, смертный эта купель освободит неоскверненную частицу моего разума, заключенную в этот камень. Помести его в купель и позволь магии зеленых драконов очистить мою сущность от скверны. только тогда я обрету истинную свободу и только тогда драконы вновь обретут власть над Аталаи."') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сущность Эраникуса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы касаетесь камня и слышите голос, звучащий в вашем сознании.$B$B"Услышь мою мольбу, о $gсмертный:смертная;. Имя мне Эраникус из народа зеленых драконов. Мои попытки положить конец богохульным деяниям троллей закончились неудачей. Я вдохнул частицу своей души в этот кристалл. Однако я чувствую, что моя связь с Изумрудным Сном теряется, и меня поглощает хаос. Пожалуйста, помести этот кристалл в купель сущности в моем логове – пусть магия очистит мое сознание от скверны и спасет меня!"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы помещаете камень в купель сущности. $B$B"Благодарю тебя, смертный теперь я... О нет! Не может быть! Скверна проклятого бога проникла даже в эту купель! Умоляю! Я чувствую, как сознание покидает меня! БОЛЬНО! Я чувствую, как мою душу поглощает вечный кошмар!"$B$B"Умоляю тебя, смертный, Найди одного из зеленых драконов, чтобы он смог прекратить мои мучения! Помоги мне! Я обречен на вечную агонию... Пощади!"',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приблизившись к купели, о которой говорил Эраникус, вы снова слышите его голос. $B$B"Да, смертный эта купель освободит неоскверненную частицу моего разума, заключенную в этот камень. Помести его в купель и позволь магии зеленых драконов очистить мою сущность от скверны. только тогда я обрету истинную свободу и только тогда драконы вновь обретут власть над Аталаи."',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3374,'Сущность Эраникуса','Принесите камень Клятвы драконьего выводка Изеры и скованную сущность Эраникуса на Болото Печали. Там вам придется сделать выбор: помогать Драконам Изеры или нет.','Выбор сделан, начало положено. Пока, на мой взгляд, ты $выбирал:выбирала; верный путь. С нынешнего момента от твоих деяний будет зависеть, будет ли так и впредь.','Вот мы снова и на распутье, $N. Пришло время делать выбор. Что ты $Gрешил:решила;, $Gсмертный:смертная;?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сущность Эраникуса',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите камень Клятвы драконьего выводка Изеры и скованную сущность Эраникуса на Болото Печали. Там вам придется сделать выбор: помогать Драконам Изеры или нет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выбор сделан, начало положено. Пока, на мой взгляд, ты $выбирал:выбирала; верный путь. С нынешнего момента от твоих деяний будет зависеть, будет ли так и впредь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вот мы снова и на распутье, $N. Пришло время делать выбор. Что ты $Gрешил:решила;, $Gсмертный:смертная;?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3375,'Запасной фиал','Хм... тебе нужен еще один фиал виденья? Шутишь? А куда ты $Gдел:дела; прежний?! У нас и так забот полон рот, |3-6($r). Эти фиалы на деревьях не растут! Хорошо бы, чтобы росли, я тогда пошел бы да сорвал, потому как другого-то у меня нет!$B$BА чтобы сделать тебе новый, мне нужно следующее: зелье маны, кусок угля и немного сладкого нектара. И не спрашивай зачем, просто принеси, я и тебе сделаю новый.','Принесите зелье маны, уголь и сладкий нектар Талвашу дель Кисселю в Стальгорн, чтобы получить запасной фиал виденья Талваша.','Могучий искатель приключений все принес. Слава мне! Кстати, я соврал – у меня был запасной фиал. Вот.$B$BА чего ты $Gожидал:ожидала;?! "Нате-пожалуйста вам другой! Мне, дураку, делать больше нечего, кроме как задарма раздавать магические устройства связи искателям приключений!" Но ты не беспокойся, все, что ты мне $Gдал:дала;, пойдет на изготовление для тебя очередного фиала, когда ты и этот посеешь.$B$BПожалуйста, пусть я ошибусь в тебе – не потеряй еще и этот, ладно?','Чтобы сделать еще один фиал, мне нужно зелье маны, кусок угля и немного сладкого нектара.$B$BИ безграничное терпение.','Вернитесь к Талвашу дель Кисселю в Палаты Магии, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запасной фиал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм... тебе нужен еще один фиал виденья? Шутишь? А куда ты $Gдел:дела; прежний?! У нас и так забот полон рот, |3-6($r). Эти фиалы на деревьях не растут! Хорошо бы, чтобы росли, я тогда пошел бы да сорвал, потому как другого-то у меня нет!$B$BА чтобы сделать тебе новый, мне нужно следующее: зелье маны, кусок угля и немного сладкого нектара. И не спрашивай зачем, просто принеси, я и тебе сделаю новый.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите зелье маны, уголь и сладкий нектар Талвашу дель Кисселю в Стальгорн, чтобы получить запасной фиал виденья Талваша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Могучий искатель приключений все принес. Слава мне! Кстати, я соврал – у меня был запасной фиал. Вот.$B$BА чего ты $Gожидал:ожидала;?! "Нате-пожалуйста вам другой! Мне, дураку, делать больше нечего, кроме как задарма раздавать магические устройства связи искателям приключений!" Но ты не беспокойся, все, что ты мне $Gдал:дала;, пойдет на изготовление для тебя очередного фиала, когда ты и этот посеешь.$B$BПожалуйста, пусть я ошибусь в тебе – не потеряй еще и этот, ладно?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы сделать еще один фиал, мне нужно зелье маны, кусок угля и немного сладкого нектара.$B$BИ безграничное терпение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талвашу дель Кисселю в Палаты Магии, что в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3376,'Сразить Остроклыка!','$n – я слыхала о тебе, $n. Возможно, именно тебе удастся то, что не удалось другим. $B$BМы, таурены, сделали это место своим домом, но это далось нам дорогой ценой. Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами. Я хочу, чтобы ты $Gпринес:принесла; мне голову их вождя! $B$BТы найдешь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда.','Принесите голову вождя Остроклыка Терновой Мантии Храбрецу Перу Ветра на плато Красного Облака.','Вернитесь к храбрецу Перу Ветра в Лагерь Нараче, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сразить Остроклыка!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n – я слыхала о тебе, $n. Возможно, именно тебе удастся то, что не удалось другим. $B$BМы, таурены, сделали это место своим домом, но это далось нам дорогой ценой. Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами. Я хочу, чтобы ты $Gпринес:принесла; мне голову их вождя! $B$BТы найдешь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову вождя Остроклыка Терновой Мантии Храбрецу Перу Ветра на плато Красного Облака.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к храбрецу Перу Ветра в Лагерь Нараче, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (3377,'Молитва к Элуне','Мне нужна твоя помощь, $gсмертный:смертная;. Выслушай меня!','Выслушайте Замеля.','Я смирился с тем, что отныне моя судьба – эта клетка, но молитву нужно найти!','Дай мне закончить.','История Замеля','Вернитесь к Замелю Лунному Репью на Гряду Огненной стражи, что в Тлеющем ущелье.','История Замеля') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитва к Элуне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужна твоя помощь, $gсмертный:смертная;. Выслушай меня!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Замеля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я смирился с тем, что отныне моя судьба – эта клетка, но молитву нужно найти!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дай мне закончить.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','История Замеля',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Замелю Лунному Репью на Гряду Огненной стражи, что в Тлеющем ущелье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','История Замеля',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3378,'Молитва к Элуне','Ты поможешь мне, $gсмертный:смертная;? Ты отыщешь молитву Элуне?$B$BКак я говорил, молитва выгравирована на золотой табличке, которая теперь, видимо, у одного из этих мерзких идолопоклонников. $B$BЕсли ты сможешь отыскать ее, отнеси табличку Астарии Ловцу Звезд в Дарнас. Пусть я пришел к вере после того, как совершил много зла этому миру и его обитателям, моя молитва должна быть услышана. А на прощение своих грехов я не надеюсь...','Найдите молитву Элуне и принесите ее Астарии Ловцу Звезд в Дарнас.','Элуна улыбается тебе, $N. Ты $Gвозвратил:возвратила; к ней потерянную душу. Прими это в знак нашей благодарности.','Что привело тебя в Храм Луны, $N?','Вернитесь к Астарии Устремленной к Звездам в Храмовые сады, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитва к Элуне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты поможешь мне, $gсмертный:смертная;? Ты отыщешь молитву Элуне?$B$BКак я говорил, молитва выгравирована на золотой табличке, которая теперь, видимо, у одного из этих мерзких идолопоклонников. $B$BЕсли ты сможешь отыскать ее, отнеси табличку Астарии Ловцу Звезд в Дарнас. Пусть я пришел к вере после того, как совершил много зла этому миру и его обитателям, моя молитва должна быть услышана. А на прощение своих грехов я не надеюсь...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите молитву Элуне и принесите ее Астарии Ловцу Звезд в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Элуна улыбается тебе, $N. Ты $Gвозвратил:возвратила; к ней потерянную душу. Прими это в знак нашей благодарности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело тебя в Храм Луны, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Астарии Устремленной к Звездам в Храмовые сады, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3379,'Мастер Тени','Пауки, которые водятся в Тлеющем ущелье, производят бесценный тенешелк. Как ты знаешь, тенешелк необходим для нашего ремесла. $B$BНе так давно в этих землях появилась шайка браконьеров, бессовестно убивающих пауков в погоне за сиюминутной прибылью. Твоя задача проста: найти их и прикончить. $B$BНачни поиски с северных пределов. $B$BЕсли потребуется помощь, обращайся к Пожару.','Убейте банду похитителей тенешелка, хозяйничающую в Тлеющем ущелье. Нилит полагает, что их пятеро. Вернитесь к Нилит по выполнению задания.','Отличная работа, $N. Прими это в награду – уверена, подобной работы из тенеткани тебе еще не встречалось!','Какая информация у вас есть?','Вернитесь к Нилите Локрав в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер Тени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пауки, которые водятся в Тлеющем ущелье, производят бесценный тенешелк. Как ты знаешь, тенешелк необходим для нашего ремесла. $B$BНе так давно в этих землях появилась шайка браконьеров, бессовестно убивающих пауков в погоне за сиюминутной прибылью. Твоя задача проста: найти их и прикончить. $B$BНачни поиски с северных пределов. $B$BЕсли потребуется помощь, обращайся к Пожару.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте банду похитителей тенешелка, хозяйничающую в Тлеющем ущелье. Нилит полагает, что их пятеро. Вернитесь к Нилит по выполнению задания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Прими это в награду – уверена, подобной работы из тенеткани тебе еще не встречалось!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какая информация у вас есть?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нилите Локрав в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3380,'Затонувший храм','Этот мир полон беспокойных духов, $n. Среди них есть такие, которые были поражены скверной, будучи прикованными к местам, в которых таится древнее зло.$B$BСлыхала я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.$B$BЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Он облазил многие развалины и останки древних поселений. А недавно он отправился изучать развалины строений троллей в Танарисе.','Найдите Марвона Клепальщика в Танарисе.','О да, я видел затонувший храм собственными глазами. Хочешь узнать о нем побольше?$B$BУж я сразу узнаю настоящего искателя приключений!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувший храм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот мир полон беспокойных духов, $n. Среди них есть такие, которые были поражены скверной, будучи прикованными к местам, в которых таится древнее зло.$B$BСлыхала я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.$B$BЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Он облазил многие развалины и останки древних поселений. А недавно он отправился изучать развалины строений троллей в Танарисе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Марвона Клепальщика в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да, я видел затонувший храм собственными глазами. Хочешь узнать о нем побольше?$B$BУж я сразу узнаю настоящего искателя приключений!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3381,'Встреча с господином','О, $gюный:юная:r; |3-6($r) $gпочтил:почтила; визитом Саната. О, это прекрасный день! Я так польщен! Благодарю тебя... $B$BНадеюсь, ты не столь $gсамонадеян:самонадеянна;, чтобы принять мой сарказм за чистую монету? Скажу прямо: ты мне не нравишься. Но речь сейчас не о том, хочу ли видеть тебя я, но о том, желает ли видеть тебя мой господин. $B$BПринеси мне пару перьев гиппогрифа для моих стрел, и я пропущу тебя к господину. Он принимает только тех, кто доказал, что на что-то годен.','Принесите 2 неповрежденных пера гиппогрифа Санату Лим-Йо в Азшару, если хотите говорить с его господином.','Два пера, как я и просил. И совсем не плохие.$B$BТогда готовы?Просто скажите слово и в путь.$B$BА, ещё запомните …мой хозяин не любит слабоумных, но он очень великодушен к тем, кто ему нравится.','Надеюсь, ты не столь $Gсамонадеян:самонадеяна;, чтобы принять мой сарказм за чистую монету? Скажу прямо: ты мне не нравишься. Однако, речь сейчас не о том, хочу ли видеть тебя я, но о том, желает ли видеть тебя мой господин.$B$BПринеси мне пару перьев гиппогрифа для моих стрел, и я пропущу тебя к господину. Он принимает только тех, кто доказал, что на что-то годен.','Вернитесь к Санату Лим-Йо в Азшару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с господином',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, $gюный:юная:r; |3-6($r) $gпочтил:почтила; визитом Саната. О, это прекрасный день! Я так польщен! Благодарю тебя... $B$BНадеюсь, ты не столь $gсамонадеян:самонадеянна;, чтобы принять мой сарказм за чистую монету? Скажу прямо: ты мне не нравишься. Но речь сейчас не о том, хочу ли видеть тебя я, но о том, желает ли видеть тебя мой господин. $B$BПринеси мне пару перьев гиппогрифа для моих стрел, и я пропущу тебя к господину. Он принимает только тех, кто доказал, что на что-то годен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 неповрежденных пера гиппогрифа Санату Лим-Йо в Азшару, если хотите говорить с его господином.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Два пера, как я и просил. И совсем не плохие.$B$BТогда готовы?Просто скажите слово и в путь.$B$BА, ещё запомните …мой хозяин не любит слабоумных, но он очень великодушен к тем, кто ему нравится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты не столь $Gсамонадеян:самонадеяна;, чтобы принять мой сарказм за чистую монету? Скажу прямо: ты мне не нравишься. Однако, речь сейчас не о том, хочу ли видеть тебя я, но о том, желает ли видеть тебя мой господин.$B$BПринеси мне пару перьев гиппогрифа для моих стрел, и я пропущу тебя к господину. Он принимает только тех, кто доказал, что на что-то годен.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Санату Лим-Йо в Азшару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (3382,'На абордаж!','Мы плыли вдоль берега, в поисках места, где бросить якорь. Солнце зашло не более часа назад, и тут они на нас напали. Проклятые наги! $B$BНе знаю, что им было нужно, но они явно этого не нашли. Почему я в этом уверена? Потому что они вернулись! Я оставила пару своих людей охранять долину, чтобы они предупредили нас в случае атаки. $B$BМне жаль, что ты $gоказался втянутым:оказалась втянутой; в эту заварушку, но увы, ничего уже нельзя сделать. $B$BТы $gготов:готова; биться не на жизнь, а на смерть?','Защитите капитана Ванессу Белтис, ее команду и пассажиров "Покорителя Горизонтов" от нападения наг. Капитан Ванесса Белтис должна выжить.','Победа! Спасибо тебе! Уф... это был самый жаркий бой за всю мою жизнь. Не знаю как тебя благодарить!$B$BКак жаль, что так много моих людей погибло в этой схватке.$B$BПожалуйста, поговори с моими пассажирами. Многие прибыли сюда по делу и наверняка кому-то из них понадобится помощь. Возможно, тебе будет это интересно. Еще раз благодарю тебя!$B$B','Ну что, ты $Gговорил:говорила; с Андроном? Он редко покидает Подгород, так что не думаю, что его будет сложно найти.','Защитите капитана Ванессу Белтис от нападения наг.','Вернитесь к капитану Ванессе Белтис в Азшару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На абордаж!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы плыли вдоль берега, в поисках места, где бросить якорь. Солнце зашло не более часа назад, и тут они на нас напали. Проклятые наги! $B$BНе знаю, что им было нужно, но они явно этого не нашли. Почему я в этом уверена? Потому что они вернулись! Я оставила пару своих людей охранять долину, чтобы они предупредили нас в случае атаки. $B$BМне жаль, что ты $gоказался втянутым:оказалась втянутой; в эту заварушку, но увы, ничего уже нельзя сделать. $B$BТы $gготов:готова; биться не на жизнь, а на смерть?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите капитана Ванессу Белтис, ее команду и пассажиров "Покорителя Горизонтов" от нападения наг. Капитан Ванесса Белтис должна выжить.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Победа! Спасибо тебе! Уф... это был самый жаркий бой за всю мою жизнь. Не знаю как тебя благодарить!$B$BКак жаль, что так много моих людей погибло в этой схватке.$B$BПожалуйста, поговори с моими пассажирами. Многие прибыли сюда по делу и наверняка кому-то из них понадобится помощь. Возможно, тебе будет это интересно. Еще раз благодарю тебя!$B$B',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, ты $Gговорил:говорила; с Андроном? Он редко покидает Подгород, так что не думаю, что его будет сложно найти.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите капитана Ванессу Белтис от нападения наг.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ванессе Белтис в Азшару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (3383,'<UNUSED>','Вернитесь к капитану Ванессе Белтис в Азшару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ванессе Белтис в Азшару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (3384,'<UNUSED>','Вернитесь к Роланду Сделайсамзу на Опустошенный берег, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Роланду Сделайсамзу на Опустошенный берег, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3385,'Черный рынок','Они называют себя Черным рынком – шайка головорезов, которые готовы купить, продать и украсть что угодно, если цена будет подходящей.$B$BИ что еще хуже, $n, они устроили себе логово в Тлеющем ущелье. Искусный торговец Ковиц – их главарь. У него есть связи с местными дворфами клана Черного Железа.$B$BМы должны нанести по ним мощный удар и недвусмысленно дать понять, что здесь им не рады. Убей торговца Ковица и его прихвостня Лязгуна. Принеси мне сумку торговца.$B$BОтправляйся в Котлован немедля!','Убейте торговца Ковица и его прихвостня Лязгуна. Снимите с тела сумку и вернитесь к Нилит.','Ты $Gнанес:нанесла; решающий удар по Черному рынку. Теперь эти бандиты дважды подумают, прежде чем отправлять сюда кого-то из своих.$B$BЯ осмотрела сумку – в ней нет ничего полезного. Если тебе приглянется что-то из его барахла, можешь смело оставить себе.','Торговец еще коптит небо?','Вернитесь к Нилите Локрав в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черный рынок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они называют себя Черным рынком – шайка головорезов, которые готовы купить, продать и украсть что угодно, если цена будет подходящей.$B$BИ что еще хуже, $n, они устроили себе логово в Тлеющем ущелье. Искусный торговец Ковиц – их главарь. У него есть связи с местными дворфами клана Черного Железа.$B$BМы должны нанести по ним мощный удар и недвусмысленно дать понять, что здесь им не рады. Убей торговца Ковица и его прихвостня Лязгуна. Принеси мне сумку торговца.$B$BОтправляйся в Котлован немедля!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте торговца Ковица и его прихвостня Лязгуна. Снимите с тела сумку и вернитесь к Нилит.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gнанес:нанесла; решающий удар по Черному рынку. Теперь эти бандиты дважды подумают, прежде чем отправлять сюда кого-то из своих.$B$BЯ осмотрела сумку – в ней нет ничего полезного. Если тебе приглянется что-то из его барахла, можешь смело оставить себе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Торговец еще коптит небо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нилите Локрав в Тлеющее ущелье.',`completedtext_loc8`);
