INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (3441,'Божественное воздаяние','Выслушай меня, $gcтранник:странница;.','Выслушайте Каларана Ветрореза.','Тебе все ясно, |3-6($N)? Ты готов действовать?','Позвольте мне закончить го... $R.','История Каларана.','Вернитесь к Каларану Ветрорезу в Котлован, что в Тлеющем ущелье.','История Каларана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Божественное воздаяние',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Выслушай меня, $gcтранник:странница;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Каларана Ветрореза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе все ясно, |3-6($N)? Ты готов действовать?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Позвольте мне закончить го... $R.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','История Каларана.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каларану Ветрорезу в Котлован, что в Тлеющем ущелье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','История Каларана.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3442,'Неугасимое пламя','Ты $gпринял:приняла; правильное решение, $n. $B$BНадо нанести удар по самому уязвимому месту – четырем сторожевым башням. $B$BТебе потребуется особый факел, чтобы поджечь их. Над его изготовлением придется потрудиться, кроме того, нужно добыть необходимые ингредиенты. $B$BПринеси мне четыре сердца пламени и четыре меры масла големов, и тогда я сделаю для тебя факел, чье пламя будет неугасимым. $B$BЧтобы достать эти ингредиенты, ищи големов и элементалей.','Принести 4 сердца пламени и 4 меры масла големов Каларану Ветрорезу.','Прекрасно, $N. Все готово к работе.','Ты $Gсобрал:собрала; материалы?','Вернитесь к Каларану Ветрорезу в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неугасимое пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпринял:приняла; правильное решение, $n. $B$BНадо нанести удар по самому уязвимому месту – четырем сторожевым башням. $B$BТебе потребуется особый факел, чтобы поджечь их. Над его изготовлением придется потрудиться, кроме того, нужно добыть необходимые ингредиенты. $B$BПринеси мне четыре сердца пламени и четыре меры масла големов, и тогда я сделаю для тебя факел, чье пламя будет неугасимым. $B$BЧтобы достать эти ингредиенты, ищи големов и элементалей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принести 4 сердца пламени и 4 меры масла големов Каларану Ветрорезу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, $N. Все готово к работе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсобрал:собрала; материалы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каларану Ветрорезу в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3443,'Древко факела','Чтобы удержать неугасимое пламя факела, нам необходимо создать особое древко и наложить защитные чары. Начнем с древка.$B$BВ Котловане надсмотрщики и работорговцы из клана Черного Железа используют оружие из зачарованного тория – особенно прочного сплава. Если ты принесешь мне восемь окованных торием кинжалов, я смогу выплавить торий и использовать его для укрепления древка.','Принесите 8 окованных торием кинжалов Каларану Ветрорезу.','Отличная работа, $N, я просто поражен! Ты не $Gзадумывался:задумывалась; о смене профессии? Чтобы стать, скажем, детективом? Ну или старьевщиком? Или примкнуть к этим глупеньким гномам, ползающим по побережьям с металлоискателями в поисках сокровищ? Это ведь наверняка твое призвание!','Восемь, $N, мне нужно восемь кинжалов!','Вернитесь к Каларану Ветрорезу в Котлован, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древко факела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы удержать неугасимое пламя факела, нам необходимо создать особое древко и наложить защитные чары. Начнем с древка.$B$BВ Котловане надсмотрщики и работорговцы из клана Черного Железа используют оружие из зачарованного тория – особенно прочного сплава. Если ты принесешь мне восемь окованных торием кинжалов, я смогу выплавить торий и использовать его для укрепления древка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 окованных торием кинжалов Каларану Ветрорезу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N, я просто поражен! Ты не $Gзадумывался:задумывалась; о смене профессии? Чтобы стать, скажем, детективом? Ну или старьевщиком? Или примкнуть к этим глупеньким гномам, ползающим по побережьям с металлоискателями в поисках сокровищ? Это ведь наверняка твое призвание!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Восемь, $N, мне нужно восемь кинжалов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каларану Ветрорезу в Котлован, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3444,'Круглый камень','Мне приходилось бывать в преддвериях затонувшего храма. Зло, таящееся в этом жутком месте, окутывает всякого, кто входит туда. Я едва смог выбраться обратно, увязая в липкой грязи, покрывающей пол. Помню, есть там огромный круглый зал со множеством высеченных из камня змей.$B$BНе так давно мне попал в руки круглый камень, на котором была высечена подобная змея. Я велел послать его в мою мастерскую в Кабестане. Забери его оттуда, и возможно, я смогу ответить на твои вопросы.','Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане.','Да, это тот самый камень.$B$BЗатонувший храм так и стоит у меня перед глазами...','Кабестан не очень далеко отсюда, $N. Поездка не должна занять много времени.','Вернитесь к Марвону Клепальщику к Разбитой Колонне, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Круглый камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне приходилось бывать в преддвериях затонувшего храма. Зло, таящееся в этом жутком месте, окутывает всякого, кто входит туда. Я едва смог выбраться обратно, увязая в липкой грязи, покрывающей пол. Помню, есть там огромный круглый зал со множеством высеченных из камня змей.$B$BНе так давно мне попал в руки круглый камень, на котором была высечена подобная змея. Я велел послать его в мою мастерскую в Кабестане. Забери его оттуда, и возможно, я смогу ответить на твои вопросы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это тот самый камень.$B$BЗатонувший храм так и стоит у меня перед глазами...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кабестан не очень далеко отсюда, $N. Поездка не должна занять много времени.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марвону Клепальщику к Разбитой Колонне, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3445,'Затонувший храм','Слыхала я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.$B$BЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Также как и мы с Троясом, он облазал многие развалины и останки древних поселений. Говорят, что он отправился изучать развалины строений троллей в Танарисе.$B$BУдачи в поисках, о нем давненько ничего не слышали!','Найдите Марвона Клепальщика в Танарисе.','О да, я видел затонувший храм собственными глазами. Хочешь узнать о нем побольше?$B$BУж я сразу узнаю настоящего искателя приключений!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затонувший храм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слыхала я о храме, сокрытом в глубинах болот – он был погружен туда силами, величие которых недоступно сознанию простого смертного.$B$BЕсли хочешь узнать больше о затонувшем храме, отыщи гоблина по имени Марвон Клепальщик. Также как и мы с Троясом, он облазал многие развалины и останки древних поселений. Говорят, что он отправился изучать развалины строений троллей в Танарисе.$B$BУдачи в поисках, о нем давненько ничего не слышали!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Марвона Клепальщика в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да, я видел затонувший храм собственными глазами. Хочешь узнать о нем побольше?$B$BУж я сразу узнаю настоящего искателя приключений!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3446,'Во глубине болот','В храме я видел круглый зал с шестью галереями, каждую из которых украшала змея, высеченная из камня. Я всего лишь дотронулся до одной из них и угодил в ловушку! Произошел сильнейший взрыв – мне несказанно повезло, что я остался цел. Лежа там, на краю галереи, я заметил еще одну статую в самом низу зала – что-то вроде алтаря. Алтарь Хаккара, полагаю.$B$BПоложи этот знак на алтарь в Затонувшем храме – думаю, это поможет открыть его секреты.','Найдите алтарь Хаккара в затонувшем храме на Болоте Печали.','Вы помещаете круглый камень в углубление и слышите негромкий щелчок. \n\nТеперь камень на положенном ему месте... Но что же делать дальше? \n\nПожалуй, стоит осмотреть алтарь...','Осмотрев статую со всех сторон, вы замечаете небольшое углубление, по форме и размеру совпадающее со знаком, который дал вам Марвон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во глубине болот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В храме я видел круглый зал с шестью галереями, каждую из которых украшала змея, высеченная из камня. Я всего лишь дотронулся до одной из них и угодил в ловушку! Произошел сильнейший взрыв – мне несказанно повезло, что я остался цел. Лежа там, на краю галереи, я заметил еще одну статую в самом низу зала – что-то вроде алтаря. Алтарь Хаккара, полагаю.$B$BПоложи этот знак на алтарь в Затонувшем храме – думаю, это поможет открыть его секреты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите алтарь Хаккара в затонувшем храме на Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы помещаете круглый камень в углубление и слышите негромкий щелчок. \n\nТеперь камень на положенном ему месте... Но что же делать дальше? \n\nПожалуй, стоит осмотреть алтарь...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Осмотрев статую со всех сторон, вы замечаете небольшое углубление, по форме и размеру совпадающее со знаком, который дал вам Марвон.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3447,'Тайна камня','Все, что я видел в Затонувшем храме, сохранилось в моей памяти лишь урывками, но я постараюсь рассказать тебе все как можно подробней. Круг статуй, сокрытый в храме – весьма опасное место, но я уверен, что там спрятан ключ к великим сокровищам.$B$BКогда я подошел к главному алтарю, в зале зажглись огни. Если тебе удастся разгадать, что они значат, возможно, сумеешь понять и тайны, которые скрывает эта комната.$B$BОднако я должен предупредить тебя, $n. В храме заключено великое зло. Какие бы сокровища там не скрывались, древние силы будут яростно защищать их от посягательств.','Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй.','Глаз идола ярко сияют даже в полумраке, царящем в храме. Кажется, внутри спрятано что-то блестящее. Вы просовываете руку внутрь статуи и хватаете то, что там лежит. Теперь сокровище Аталаи – ваше!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна камня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все, что я видел в Затонувшем храме, сохранилось в моей памяти лишь урывками, но я постараюсь рассказать тебе все как можно подробней. Круг статуй, сокрытый в храме – весьма опасное место, но я уверен, что там спрятан ключ к великим сокровищам.$B$BКогда я подошел к главному алтарю, в зале зажглись огни. Если тебе удастся разгадать, что они значат, возможно, сумеешь понять и тайны, которые скрывает эта комната.$B$BОднако я должен предупредить тебя, $n. В храме заключено великое зло. Какие бы сокровища там не скрывались, древние силы будут яростно защищать их от посягательств.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Глаз идола ярко сияют даже в полумраке, царящем в храме. Кажется, внутри спрятано что-то блестящее. Вы просовываете руку внутрь статуи и хватаете то, что там лежит. Теперь сокровище Аталаи – ваше!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3448,'Передача поручения','Недавно мне доверили задачу исследования Азшары – некогда прекрасного края, который эльфы называли домом. Это было в те времена, когда они занимались магией. Теперь же это место скорее опасно, чем прекрасно, но это не остановит нас. Мы перевернем его по камушку, чтобы разгадать загадки нашего прошлого.$B$BМой товарищ Тимор предложил мне помощь в исследованиях, поскольку это и его самого особенно интересует.$B$BУ него здесь в городе есть небольшой дом рядом с Залом Тайн.','Поговорите с Тимором в Стальгорне.','Ах, так вас послал Карик? Я как раз ждал от него известий. Я тут такое узнал об Азшаре... Я знаю, что ночные эльфы живут невероятно долго, но все порой забывают о некоторых... неприятных событиях в их жизни. Это не критика, всего лишь замечание.$B$BДавным-давно там существовали города, возведенные эльфами, которые много знали о магии и других утраченных искусствах. Поскольку я такие вещи изучаю, я начал свои исследования. И открытия мои просто ошеломляющи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Передача поручения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно мне доверили задачу исследования Азшары – некогда прекрасного края, который эльфы называли домом. Это было в те времена, когда они занимались магией. Теперь же это место скорее опасно, чем прекрасно, но это не остановит нас. Мы перевернем его по камушку, чтобы разгадать загадки нашего прошлого.$B$BМой товарищ Тимор предложил мне помощь в исследованиях, поскольку это и его самого особенно интересует.$B$BУ него здесь в городе есть небольшой дом рядом с Залом Тайн.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тимором в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, так вас послал Карик? Я как раз ждал от него известий. Я тут такое узнал об Азшаре... Я знаю, что ночные эльфы живут невероятно долго, но все порой забывают о некоторых... неприятных событиях в их жизни. Это не критика, всего лишь замечание.$B$BДавным-давно там существовали города, возведенные эльфами, которые много знали о магии и других утраченных искусствах. Поскольку я такие вещи изучаю, я начал свои исследования. И открытия мои просто ошеломляющи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3449,'Чародейские руны','Некоторые эльфы в старину почитали магию не меньше самой Элуны. Их самые могущественные маги создали руны и таблички, в которых были перечислены законы чародейства и разгадки их открытий. Они, как правило, выставляли их на всеобщее обозрение, чтобы все могли над ними поразмышлять.$B$BЯ был бы очень рад получить прорисовки этих рун из руин Эльдарата. Чтобы сделать прорисовки, я дам вам готовальню, но найти их должны вы сами. Будьте осторожны, не только лига исследователей имеет свои интересы в Эльдарате.','При помощи готовальни сделайте прорисовки руны Бет\'Амары, руны Джин\'йаэль, руны Маркри и руны Саэл\'Хаи. Отправляйтесь на маленький островок близ южного полуострова Азшары и дайте сигнал пилоту Зиггсу Зажигателю забрать их.','Вернитесь к пилоту Зиггсу Зажигателю к памятнику Гребню Ворона, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чародейские руны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые эльфы в старину почитали магию не меньше самой Элуны. Их самые могущественные маги создали руны и таблички, в которых были перечислены законы чародейства и разгадки их открытий. Они, как правило, выставляли их на всеобщее обозрение, чтобы все могли над ними поразмышлять.$B$BЯ был бы очень рад получить прорисовки этих рун из руин Эльдарата. Чтобы сделать прорисовки, я дам вам готовальню, но найти их должны вы сами. Будьте осторожны, не только лига исследователей имеет свои интересы в Эльдарате.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи готовальни сделайте прорисовки руны Бет\'Амары, руны Джин\'йаэль, руны Маркри и руны Саэл\'Хаи. Отправляйтесь на маленький островок близ южного полуострова Азшары и дайте сигнал пилоту Зиггсу Зажигателю забрать их.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пилоту Зиггсу Зажигателю к памятнику Гребню Ворона, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3450,'Легкая доставка','Я хочу, чтобы эти прорисовки были доставлены мне в башню, но вам незачем лично проделывать весь этот путь. Пусть их просто доставят из Азшары по воздуху.$B$BУ Зиггса Зажигателя есть перед мной должок, к тому же он скоро окажется в тех местах – он назначен патрулировать побережье. Поговорите с ним перед отъездом. Он даст вам сигнальное ружье, чтобы вы могли подать ему сигнал. Когда добудете прорисовки, отправляйтесь в условленное место и отдайте их ему, чтобы он доставил их в мою башню в целости и сохранности. Он должен быть в ангаре в Палатах Войны.','Поговорите с Зиггсом Зажигателем в Стальгорне.','Чем могу помочь, $n? Я как бы занят сейчас – готовлю аппаратик свой к долгому полету. Я тут зашел поговорить с водителями танков – мне нужны гривы вендиго, чтобы кабину утеплить, а у них обычно есть.$B$BТак что уделить вам могу не больше минуты... один парень только что пошел в депо Поселок Сталежара, чтобы посмотреть, найдутся ли у них для меня гривы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легкая доставка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу, чтобы эти прорисовки были доставлены мне в башню, но вам незачем лично проделывать весь этот путь. Пусть их просто доставят из Азшары по воздуху.$B$BУ Зиггса Зажигателя есть перед мной должок, к тому же он скоро окажется в тех местах – он назначен патрулировать побережье. Поговорите с ним перед отъездом. Он даст вам сигнальное ружье, чтобы вы могли подать ему сигнал. Когда добудете прорисовки, отправляйтесь в условленное место и отдайте их ему, чтобы он доставил их в мою башню в целости и сохранности. Он должен быть в ангаре в Палатах Войны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зиггсом Зажигателем в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чем могу помочь, $n? Я как бы занят сейчас – готовлю аппаратик свой к долгому полету. Я тут зашел поговорить с водителями танков – мне нужны гривы вендиго, чтобы кабину утеплить, а у них обычно есть.$B$BТак что уделить вам могу не больше минуты... один парень только что пошел в депо Поселок Сталежара, чтобы посмотреть, найдутся ли у них для меня гривы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3451,'Сигнал "Взять на борт!"','А, так вас послал Тимор? Да, есть у меня перед ним должок. Это что? Ах, поганец! Ладно, я ему помогу. Значит, вам нужны сигнальное ружье и условленная точка... да легко.$B$BБлиз южного мыса Азшары есть небольшой островок, где мы соорудили посадочную площадку. Берете ружье и даете оттуда сигнал. Я вижу сигнал и прилетаю забрать это... ну, что ему надо.','Поговорите с Зиггсом Зажигателем в Стальгорне и получите от него сигнальное ружье.','Вот вам сигнальное ружье. Когда дадите сигнал, запаситесь терпением – в нем всего два патрона, а мне потребуется несколько минут, чтобы добраться до вас, в зависимости от того, насколько далеко над морем я буду. Выстрелите из ружья – и полюбуйтесь на море.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сигнал "Взять на борт!"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, так вас послал Тимор? Да, есть у меня перед ним должок. Это что? Ах, поганец! Ладно, я ему помогу. Значит, вам нужны сигнальное ружье и условленная точка... да легко.$B$BБлиз южного мыса Азшары есть небольшой островок, где мы соорудили посадочную площадку. Берете ружье и даете оттуда сигнал. Я вижу сигнал и прилетаю забрать это... ну, что ему надо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зиггсом Зажигателем в Стальгорне и получите от него сигнальное ружье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот вам сигнальное ружье. Когда дадите сигнал, запаситесь терпением – в нем всего два патрона, а мне потребуется несколько минут, чтобы добраться до вас, в зависимости от того, насколько далеко над морем я буду. Выстрелите из ружья – и полюбуйтесь на море.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3452,'Защита пламени','Работа над факелом близится к завершению. Не хватет лишь одного компонента. $B$BВ горах к северо-западу отсюда есть большой лагерь Сумеречного Молота. Говорят, они носят при себе некие символы и идолов в дань уважения своему богу. Полагаю, в этих символах и идолах заключены чары достаточной силы для создания магической брони. Принеси мне знак Рагнароса, и я попытаюсь извлечь из него его магическую силу, чтобы создать защитные чары для факела.','Найдите знак Рагнароса и принесите его Каларану Ветрорезу.','Символ источает злые чары – именно они и требуются для завершения работы над факелом.','Без подходящего источника темной энергии, факел воздаяния не может быть завершен.','Вернитесь к Каларану Ветрорезу в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Работа над факелом близится к завершению. Не хватет лишь одного компонента. $B$BВ горах к северо-западу отсюда есть большой лагерь Сумеречного Молота. Говорят, они носят при себе некие символы и идолов в дань уважения своему богу. Полагаю, в этих символах и идолах заключены чары достаточной силы для создания магической брони. Принеси мне знак Рагнароса, и я попытаюсь извлечь из него его магическую силу, чтобы создать защитные чары для факела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите знак Рагнароса и принесите его Каларану Ветрорезу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Символ источает злые чары – именно они и требуются для завершения работы над факелом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Без подходящего источника темной энергии, факел воздаяния не может быть завершен.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каларану Ветрорезу в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (3453,'Факел воздаяния','Мне нужно несколько минут, чтобы сложить вместе все части и наложить чары.','Подождите, пока Каларан Ветрорез закончит факел Воздаяния.','Есть еще одно, последнее задание, которое ты $Gдолжен:должна; выполнить.','Не прерывай процесс воссоединения.','Создание факела','Вернитесь к Каларану Ветрорезу в Тлеющее ущелье.','Создание факела') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Факел воздаяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно несколько минут, чтобы сложить вместе все части и наложить чары.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подождите, пока Каларан Ветрорез закончит факел Воздаяния.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Есть еще одно, последнее задание, которое ты $Gдолжен:должна; выполнить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не прерывай процесс воссоединения.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Создание факела',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каларану Ветрорезу в Тлеющее ущелье.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Создание факела',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3454,'Факел воздаяния','Факел готов и отныне связан со своим владельцем. Возьми его, $n.','Возьмите факел воздаяния.','Вы хватаете факел обеими руками и ощущаете исходящие от него волны гнева и ненависти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Факел воздаяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Факел готов и отныне связан со своим владельцем. Возьми его, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите факел воздаяния.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы хватаете факел обеими руками и ощущаете исходящие от него волны гнева и ненависти.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3461,'Возвращение к Тимору','Тимор не оставил мне ничего, чтобы вам заплатить, потому предлагаю вам обсудить награду лично с ним, когда вернетесь в Стальгорн. Я уверен, что он до сих пор у себя в Палатах Магии. Постучитесь и потребуйте щедрой платы, потому как местечко-то не для пикника... это уж точно.$B$BВсе же благодарю вас, что вы ему помогли, и желаю удачи.$B$BОй, готовальня мне ни к чему. Почему бы вам просто не отдать ее лично Тимору, когда вы с ним встретитесь?','Принесите Тимору его готовальню назад в Стальгорн.','Отлично! Я так рад это слышать.\n\nКак мне не терпится вернуться в мою башню и поработать над прорисовками... Я так завидую вам! Побывать в Азшаре... думаю, это мечта всех изучающих чародейские науки.\n\nЛадно, хотя мы и не говорили о награде, поскольку вы работаете на лигу Исследователей, но вы ее заслуживаете.','Вы вернулись! Замечательно. А готовальню мою принесли?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Тимору',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тимор не оставил мне ничего, чтобы вам заплатить, потому предлагаю вам обсудить награду лично с ним, когда вернетесь в Стальгорн. Я уверен, что он до сих пор у себя в Палатах Магии. Постучитесь и потребуйте щедрой платы, потому как местечко-то не для пикника... это уж точно.$B$BВсе же благодарю вас, что вы ему помогли, и желаю удачи.$B$BОй, готовальня мне ни к чему. Почему бы вам просто не отдать ее лично Тимору, когда вы с ним встретитесь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Тимору его готовальню назад в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Я так рад это слышать.\n\nКак мне не терпится вернуться в мою башню и поработать над прорисовками... Я так завидую вам! Побывать в Азшаре... думаю, это мечта всех изучающих чародейские науки.\n\nЛадно, хотя мы и не говорили о награде, поскольку вы работаете на лигу Исследователей, но вы ее заслуживаете.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы вернулись! Замечательно. А готовальню мою принесли?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3462,'Оруженосец Малтрейк','Поговори с моим посыльным, оруженосцем Малтрейком. Он объяснит тебе, как использовать факел.','Поговорите с оруженосцем Малтрейком.','Ты готов нанести удар?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оруженосец Малтрейк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поговори с моим посыльным, оруженосцем Малтрейком. Он объяснит тебе, как использовать факел.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с оруженосцем Малтрейком.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты готов нанести удар?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3463,'Задай им жару!','Слушай меня внимательно, $n. Четыре башни нельзя разрушить, но если поджечь их с помощью факела воздаяния, пламя не угаснет очень долго – и это пламя нельзя будет унять никакими силами. $B$BПока башни горят, ни один страж или караульный не сможет подняться на них – а значит, первая линия обороны противника фактически будет прорвана. $B$BТы $gдолжен:должна; пробраться в башни и поджечь их с помощью факела воздаяния. И берегись патрульных Черного Железа!','Подожгите северную, южную, восточную и западную сторожевые башни с помощью факела воздаяния.','Отлично! С тобой можно идти в разведку, $N!','Ты $Gпотерял:потеряла; дорогу, $N?','Вернитесь к оруженосцу Малтрейку в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задай им жару!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай меня внимательно, $n. Четыре башни нельзя разрушить, но если поджечь их с помощью факела воздаяния, пламя не угаснет очень долго – и это пламя нельзя будет унять никакими силами. $B$BПока башни горят, ни один страж или караульный не сможет подняться на них – а значит, первая линия обороны противника фактически будет прорвана. $B$BТы $gдолжен:должна; пробраться в башни и поджечь их с помощью факела воздаяния. И берегись патрульных Черного Железа!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подожгите северную, южную, восточную и западную сторожевые башни с помощью факела воздаяния.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! С тобой можно идти в разведку, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпотерял:потеряла; дорогу, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оруженосцу Малтрейку в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3481,'Безделушки...','Похоже, сундук заперт.','Откройте сундук.','Замок открывается, как только вы прикасаетесь к нему. Любопытно, сколько же может быть внутри сокровищ? Есть только один способ узнать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безделушки...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, сундук заперт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте сундук.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замок открывается, как только вы прикасаетесь к нему. Любопытно, сколько же может быть внутри сокровищ? Есть только один способ узнать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (3482,'<NYI> <TXT> Щербатая черная коробка','Это задание "Черный ящик" в версии для Орды','Отнесите этот ящик Крейвелу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> Щербатая черная коробка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это задание "Черный ящик" в версии для Орды',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите этот ящик Крейвелу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (3483,'Сигнал "Взять на борт!"','Еще одно сигнальное ружье, да? Это можно.$B$BИ не забудьте – южная оконечность Азшары. Этот крохотный островок переделан в посадочную площадку. Вы ее не пропустите, если окажетесь в нужном месте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сигнал "Взять на борт!"',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще одно сигнальное ружье, да? Это можно.$B$BИ не забудьте – южная оконечность Азшары. Этот крохотный островок переделан в посадочную площадку. Вы ее не пропустите, если окажетесь в нужном месте.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3501,'Счет идет на большие числа','Быть может, ты никогда не найдешь безупречную сферу из дренетиста, однако во время скитаний по этим землям тебе, несомненно, удастся обнаружить различные несовершенные фрагменты дренетиста.$B$BХотя сомнительно, что Кум\'иша сможет использовать эти несовершенные фрагменты для возвращения домой, эти осколки могут сослужить иную, весьма полезную службу для дренеев.$B$BПринеси любой несовершенный фрагмент дренетиста, который найдешь, и я вознагражу тебя.','Принесите Кум\'ише несовершенные фрагменты дренетиста и получите награду за каждый из них.','Ты разочаровываешь меня, |3-6($R). Такой большой, а роняет слюни над грудой хлама? Какое жалкое зрелище! Забирай свою награду и прочь с глаз моих!','Повезло ли тебе в поисках?','Вернитесь к Кум\'ише Коллекционеру в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Счет идет на большие числа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быть может, ты никогда не найдешь безупречную сферу из дренетиста, однако во время скитаний по этим землям тебе, несомненно, удастся обнаружить различные несовершенные фрагменты дренетиста.$B$BХотя сомнительно, что Кум\'иша сможет использовать эти несовершенные фрагменты для возвращения домой, эти осколки могут сослужить иную, весьма полезную службу для дренеев.$B$BПринеси любой несовершенный фрагмент дренетиста, который найдешь, и я вознагражу тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Кум\'ише несовершенные фрагменты дренетиста и получите награду за каждый из них.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты разочаровываешь меня, |3-6($R). Такой большой, а роняет слюни над грудой хлама? Какое жалкое зрелище! Забирай свою награду и прочь с глаз моих!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Повезло ли тебе в поисках?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кум\'ише Коллекционеру в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3502,'Дренейский хлам','Ну-с, узрев проявление этой ненасытной жадности, я не могу сдержать отвращение.$B$BИ тем не менее я не намерен долго задерживаться на твоем пристрастии к материальным благам.$B$BЗа каждый несовершенный фрагмент дренетиста, который ты принесешь, я вознагражу тебя каким-нибудь хламом. Моя груда хлама будет уменьшаться, а твоя – расти. На Дреноре такая ситуация называлась "все в выигрыше".','Принесите Кум\'ише несовершенные фрагменты дренетиста. У любого вида монстров в Выжженных землях могут быть эти фрагменты.','Ты разочаровываешь меня, |3-6($R). Такой большой, а роняет слюни над грудой хлама? Какое жалкое зрелище! Забирай свою награду и прочь с глаз моих.$B$BЗнакомые слова? А как же – я повторяю их тысячу раз на дню.$B$BО, как мне отвратителен этот мир!','Ты разочаровываешь меня, $R. $GТакой:Такая; $Gбольшой:большая;, а роняет слюни над грудой хлама? Какое жалкое зрелище! Забирай свою награду и прочь с глаз моих.$B$BЗнакомые слова? А как же – я повторяю их тысячу раз на дню.$B$BО, как мне отвратителен этот мир!','Вернитесь к Кум\'ише Коллекционеру в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дренейский хлам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну-с, узрев проявление этой ненасытной жадности, я не могу сдержать отвращение.$B$BИ тем не менее я не намерен долго задерживаться на твоем пристрастии к материальным благам.$B$BЗа каждый несовершенный фрагмент дренетиста, который ты принесешь, я вознагражу тебя каким-нибудь хламом. Моя груда хлама будет уменьшаться, а твоя – расти. На Дреноре такая ситуация называлась "все в выигрыше".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Кум\'ише несовершенные фрагменты дренетиста. У любого вида монстров в Выжженных землях могут быть эти фрагменты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты разочаровываешь меня, |3-6($R). Такой большой, а роняет слюни над грудой хлама? Какое жалкое зрелище! Забирай свою награду и прочь с глаз моих.$B$BЗнакомые слова? А как же – я повторяю их тысячу раз на дню.$B$BО, как мне отвратителен этот мир!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты разочаровываешь меня, $R. $GТакой:Такая; $Gбольшой:большая;, а роняет слюни над грудой хлама? Какое жалкое зрелище! Забирай свою награду и прочь с глаз моих.$B$BЗнакомые слова? А как же – я повторяю их тысячу раз на дню.$B$BО, как мне отвратителен этот мир!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кум\'ише Коллекционеру в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (3503,'Встреча с господином','Да, уж не вернуть тех дней, когда я мог требовать с желающих видеть моего господина все, что заблагорассудится. Теперь-то я отправляю к нему любой сброд – только попроси!$B$BКак меня это бесит! Но приказы не обсуждаются. Я могу потешить себя лишь глумясь над твоей безвкусной одеждой и жалким выражением лица. Впрочем, мне и это уже наскучило!$B$BИ необходимость трепаться тут с тобой меня бесит! Будешь телепортироваться к господину или нет?!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с господином',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, уж не вернуть тех дней, когда я мог требовать с желающих видеть моего господина все, что заблагорассудится. Теперь-то я отправляю к нему любой сброд – только попроси!$B$BКак меня это бесит! Но приказы не обсуждаются. Я могу потешить себя лишь глумясь над твоей безвкусной одеждой и жалким выражением лица. Впрочем, мне и это уже наскучило!$B$BИ необходимость трепаться тут с тобой меня бесит! Будешь телепортироваться к господину или нет?!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3504,'Предательница','Предательница и воровка! Других слов для нее у меня нет!$b$bНаверное, я сделал большую ошибку, $n. Я доверился эльфу крови. Хуже того – я доверился бабе!$b$bОна уверяла, будто в Азшаре хранятся несметные сокровища... могущественные артефакты... Все, что нужно, – это отправить с ней нескольких воинов для охраны, и она меня щедро вознаградит. Ну, и кто остался в дураках? Она их всех перебила!$b$bЯ жажду мести, $n. Но посылать туда других воинов я уже не могу. Найди Аг\'тора в Храбростане, к северу от лагеря Халдарр. Он тебе скажет, что делать дальше.','Отнесите запечатанное письмо Аг\'тору Кровопалу в Азшару.','Мы уже многих посылали против нее и ее приспешников, но они слишком сильны! Никто из посланных не вернулся. Наверное, некоторые погибли, но большинство, подозреваю, просто сбежали. Трусы!$B$BОднако теперь, когда прибыло подкрепление, у нас снова появилась надежда. Быть может, мы все-таки сумеем с ней разобраться.$B$BНу так что, ты с нами?','А-а, Белгром наконец-то прислал кого-то стороннего, не из своих солдат?$B$BРаньше в этом лагере было двенадцать воинов, $N но теперь они все мертвы! Эта магичка, Римтори, погубила всех! Белгрома она обвела вокруг пальца... собственно, она его соблазнила. Не мое это дело, но, между нами говоря, стерва она изрядная. Потому я и продолжаю помогать Белгрому. На его месте я бы, наверное, сделал то же самое.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предательница',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Предательница и воровка! Других слов для нее у меня нет!$b$bНаверное, я сделал большую ошибку, $n. Я доверился эльфу крови. Хуже того – я доверился бабе!$b$bОна уверяла, будто в Азшаре хранятся несметные сокровища... могущественные артефакты... Все, что нужно, – это отправить с ней нескольких воинов для охраны, и она меня щедро вознаградит. Ну, и кто остался в дураках? Она их всех перебила!$b$bЯ жажду мести, $n. Но посылать туда других воинов я уже не могу. Найди Аг\'тора в Храбростане, к северу от лагеря Халдарр. Он тебе скажет, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанное письмо Аг\'тору Кровопалу в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы уже многих посылали против нее и ее приспешников, но они слишком сильны! Никто из посланных не вернулся. Наверное, некоторые погибли, но большинство, подозреваю, просто сбежали. Трусы!$B$BОднако теперь, когда прибыло подкрепление, у нас снова появилась надежда. Быть может, мы все-таки сумеем с ней разобраться.$B$BНу так что, ты с нами?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А-а, Белгром наконец-то прислал кого-то стороннего, не из своих солдат?$B$BРаньше в этом лагере было двенадцать воинов, $N но теперь они все мертвы! Эта магичка, Римтори, погубила всех! Белгрома она обвела вокруг пальца... собственно, она его соблазнила. Не мое это дело, но, между нами говоря, стерва она изрядная. Потому я и продолжаю помогать Белгрому. На его месте я бы, наверное, сделал то же самое.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (3505,'[DEPRECATED 4.x] Предательница','Так я и думал.$b$bМы начнем наступать на ее приспешников от южных утесов северного полуострова Азшары. Убивайте их, не зная пощады – пусть знают, кого предали!$b$bНасчет ее самой пока не тревожьтесь – она проводит большую часть времени, рыская по Азшаре вместе со своими телохранителями. После того как перебьете ее работников, стоит отыскать ее личный лагерь. Нужно сначала разведать, откуда можно на нее напасть. Может быть, стоит как-нибудь выманить ее из лагеря...','Вы начинаете листать страницы и обнаруживаете, что одна из них заложена узкой ленточкой черного шелка.$B$BВы пытаетесь разобрать непонятные слова и видите на одной из страниц схему. Присмотревшись, вы понимаете, что кристаллы, круг и некоторые другие компоненты, лежащие на земле, расположены так же, как на рисунке.','Заглавие этой книги написано золотом по черной кожаной обложке: кальдорайский фолиант Призыва. Открыв книгу, вы обнаружили, что она древняя, но превосходно сохранилась.$B$BТекст, по-видимому, на каком-то древнем языке... кальдорайском, наверное?$B$BИнстинкт подсказывает вам, что, когда вы покончите с местью, сюда стоит вернуться снова.','Найдите лагерь волхва Римтори.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED 4.x] Предательница',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так я и думал.$b$bМы начнем наступать на ее приспешников от южных утесов северного полуострова Азшары. Убивайте их, не зная пощады – пусть знают, кого предали!$b$bНасчет ее самой пока не тревожьтесь – она проводит большую часть времени, рыская по Азшаре вместе со своими телохранителями. После того как перебьете ее работников, стоит отыскать ее личный лагерь. Нужно сначала разведать, откуда можно на нее напасть. Может быть, стоит как-нибудь выманить ее из лагеря...',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы начинаете листать страницы и обнаруживаете, что одна из них заложена узкой ленточкой черного шелка.$B$BВы пытаетесь разобрать непонятные слова и видите на одной из страниц схему. Присмотревшись, вы понимаете, что кристаллы, круг и некоторые другие компоненты, лежащие на земле, расположены так же, как на рисунке.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Заглавие этой книги написано золотом по черной кожаной обложке: кальдорайский фолиант Призыва. Открыв книгу, вы обнаружили, что она древняя, но превосходно сохранилась.$B$BТекст, по-видимому, на каком-то древнем языке... кальдорайском, наверное?$B$BИнстинкт подсказывает вам, что, когда вы покончите с местью, сюда стоит вернуться снова.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите лагерь волхва Римтори.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3506,'Предательница','Вы поразмыслили еще немного, и вам на ум пришло сразу несколько идей, одна из которых заставила улыбнуться: возможно, если вы уничтожите кристаллы, подлая эльфийка, погубившая стольких орков, достаточно разозлится?$b$bВы продолжаете разбирать текст и рисунки и понимаете, что один из кристаллов связан с создателем круга – прочие же связаны с куда более жуткими тварями.$b$bВы закрываете книгу и начинаете прикидывать, какой из кристаллов следует уничтожить.','Уничтожьте кристалл средоточия чар, связанный с волхвом Римтори, затем убейте ее. Отнесите голову Римтори Аг\'тору Кроволапу в Азшаре.','Ага!!! Невероятно!$B$BТебе это удалось! То-то Белгром обрадуется! Наконец-то души десятков наших воинов упокоятся в мире. Спасибо тебе, $N.','Ну что, $N, много тебе удалось перебить этих эльфов-предателей?$B$BЯ надеюсь, что именно у тебя хватит сил поставить эту мерзавку на колени! За все, что она натворила, она заслуживает самой мучительной смерти!','Вернитесь к Аг\'тору Кровопалу в Азшару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предательница',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы поразмыслили еще немного, и вам на ум пришло сразу несколько идей, одна из которых заставила улыбнуться: возможно, если вы уничтожите кристаллы, подлая эльфийка, погубившая стольких орков, достаточно разозлится?$b$bВы продолжаете разбирать текст и рисунки и понимаете, что один из кристаллов связан с создателем круга – прочие же связаны с куда более жуткими тварями.$b$bВы закрываете книгу и начинаете прикидывать, какой из кристаллов следует уничтожить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте кристалл средоточия чар, связанный с волхвом Римтори, затем убейте ее. Отнесите голову Римтори Аг\'тору Кроволапу в Азшаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага!!! Невероятно!$B$BТебе это удалось! То-то Белгром обрадуется! Наконец-то души десятков наших воинов упокоятся в мире. Спасибо тебе, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $N, много тебе удалось перебить этих эльфов-предателей?$B$BЯ надеюсь, что именно у тебя хватит сил поставить эту мерзавку на колени! За все, что она натворила, она заслуживает самой мучительной смерти!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аг\'тору Кровопалу в Азшару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3507,'[DEPRECATED 4.x] Предательница','Вернись в Оргриммар к Белгрому. Он захочет увидеть ее голову своими глазами! Мы там тоже скоро будем.$b$bУдачный у нас денек! Спасибо за помощь, $n.','Поговорите с Белгромом Каменной Булавой в Оргриммаре.','Ха-ха-ха! Вот и ты, жалкая девчонка! Я плюю на твои останки!$B$BСпасибо, $N. Я благодарю тебя от всей души! Это воистину великий день!$B$BБудь это в моей власти, я наградил бы тебя целым королевством! Но, может быть, ты согласишься на это?$B$B<Белгром смотрит на голову |3-6($C), который предал его.>$B$BХа-ха! Глупая эльфийка! Вот что с тобой стало! В парусиновом мешке, голова отдельно, тело отдельно! Не надо было предавать Белгрома!','Да, $C, я тебя помню. Я просил тебя отправиться в Азшару и уничтожить ту негодяйку, которая предала меня! Кажется, будто это было много лун тому назад... Только не говори мне, что Аг\'тор и остальные тоже мертвы!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED 4.x] Предательница',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вернись в Оргриммар к Белгрому. Он захочет увидеть ее голову своими глазами! Мы там тоже скоро будем.$b$bУдачный у нас денек! Спасибо за помощь, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Белгромом Каменной Булавой в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха-ха! Вот и ты, жалкая девчонка! Я плюю на твои останки!$B$BСпасибо, $N. Я благодарю тебя от всей души! Это воистину великий день!$B$BБудь это в моей власти, я наградил бы тебя целым королевством! Но, может быть, ты согласишься на это?$B$B<Белгром смотрит на голову |3-6($C), который предал его.>$B$BХа-ха! Глупая эльфийка! Вот что с тобой стало! В парусиновом мешке, голова отдельно, тело отдельно! Не надо было предавать Белгрома!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C, я тебя помню. Я просил тебя отправиться в Азшару и уничтожить ту негодяйку, которая предала меня! Кажется, будто это было много лун тому назад... Только не говори мне, что Аг\'тор и остальные тоже мертвы!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3508,'Минуя охрану','Тебе свойственна безрассудная храбрость, $n. Это ценное качество твоего рода – слепо кидаться в битву, почти не имея шансов на успех. Я помогу тебе, хотя бы только ради того, чтобы увидеть смерть приспешников Разелиха. $B$BОднако для того, чтобы пробиться через охранные чары, окружающие их, требуется время, равно как и использование редких артефактов.$B$BНе нарушай тишину, я должен исполнить ритуал просветления. Сведения, которые я получу, помогут мне отковать оружие великой мощи.','Подождите, пока Лорам завершит заклинание просветления.','Необходимо отыскать имя зверя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Минуя охрану',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе свойственна безрассудная храбрость, $n. Это ценное качество твоего рода – слепо кидаться в битву, почти не имея шансов на успех. Я помогу тебе, хотя бы только ради того, чтобы увидеть смерть приспешников Разелиха. $B$BОднако для того, чтобы пробиться через охранные чары, окружающие их, требуется время, равно как и использование редких артефактов.$B$BНе нарушай тишину, я должен исполнить ритуал просветления. Сведения, которые я получу, помогут мне отковать оружие великой мощи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подождите, пока Лорам завершит заклинание просветления.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Необходимо отыскать имя зверя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3509,'Имя Зверя','Существует лишь один способ причинить вред повелителю демонов и его приспешникам. Следует выковать оружие силы, несущее его истинное имя.$B$BКогда такое оружие будет выковано, демон и все, кем он повелевает, станут уязвимы. $B$BВ Азшаре обитает меньшее божество: лорд Арккорок. Тебе следует найти его. Однако осторожнее: его слуги не остановятся ни перед чем, чтобы убить тебя, если обнаружат.$B$BНесомненно, за такие сведения придется заплатить.','Поговорите в Азшаре с лордом Арккороком. Начните поиски у кромки воды, чтобы найти Храм Арккоран.','Повелитель демонов?$B$B<Лорд Арккорос смеется.>$B$BБыть может, кое-кто сможет помочь тебе этими сведениями, но сначала ты должен помочь кое-кому.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Имя Зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Существует лишь один способ причинить вред повелителю демонов и его приспешникам. Следует выковать оружие силы, несущее его истинное имя.$B$BКогда такое оружие будет выковано, демон и все, кем он повелевает, станут уязвимы. $B$BВ Азшаре обитает меньшее божество: лорд Арккорок. Тебе следует найти его. Однако осторожнее: его слуги не остановятся ни перед чем, чтобы убить тебя, если обнаружат.$B$BНесомненно, за такие сведения придется заплатить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Азшаре с лордом Арккороком. Начните поиски у кромки воды, чтобы найти Храм Арккоран.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Повелитель демонов?$B$B<Лорд Арккорос смеется.>$B$BБыть может, кое-кто сможет помочь тебе этими сведениями, но сначала ты должен помочь кое-кому.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3510,'Имя Зверя','Она убивает моих детей. Она называет себя повелительницей океанов. Фальшивая богиня, и ничего более. Сокруши ее и принеси мне все ее головы.$B$BЗа это ты получишь то имя, которое тебе нужно, и кое-что еще, не менее важное.$B$BОна бродит вокруг гнезда... Она зовется Хетайра.$B$B<Лорд Арккорок указывает на юго-запад.>$B$BИди!','Убейте Хетайру и принесите окровавленную голову Хетайры, разбитую голову Хетайры и покрытую синяками голову Хетайры лорду Арккороку.','Наконец-то хоть кто-то достойный мудрости Арккороса!','<Лорд Арккорос склоняется, чтобы лучше видеть тебя.>$B$BГде они?','Вернитесь к лорду Арккороку в Храм Арккоран, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Имя Зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Она убивает моих детей. Она называет себя повелительницей океанов. Фальшивая богиня, и ничего более. Сокруши ее и принеси мне все ее головы.$B$BЗа это ты получишь то имя, которое тебе нужно, и кое-что еще, не менее важное.$B$BОна бродит вокруг гнезда... Она зовется Хетайра.$B$B<Лорд Арккорок указывает на юго-запад.>$B$BИди!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Хетайру и принесите окровавленную голову Хетайры, разбитую голову Хетайры и покрытую синяками голову Хетайры лорду Арккороку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то хоть кто-то достойный мудрости Арккороса!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Лорд Арккорос склоняется, чтобы лучше видеть тебя.>$B$BГде они?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Арккороку в Храм Арккоран, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3511,'Имя Зверя','Как и обещал, я открою тебе имя Повелителя демонов Разелиха Осквернителя. Однако сначала я должен приготовить кое-что необычайно важное для твоего путешествия.$B$BДля создания оружия, которое ты ищешь, необходим состав для закалки. Подожди немного, я выжму кровь из этих голов.$B$B<Лорд Арккорок сжимает головы между своими гигантскими ладонями, выдавливая из них кровь.>$B$BДоставь этот состав для закалки Лораму вместе с именем зверя: Рах\'лих.','Отнесите состав для закалки Лораму Многоногу.','Этот состав содержит протравку, необходимую нам для отковки оружия. Это еще один шаг к созданию сего оружия.','С возвращением! Я рад видеть тебя, $R. Тебе удалось узнать подлинное имя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Имя Зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как и обещал, я открою тебе имя Повелителя демонов Разелиха Осквернителя. Однако сначала я должен приготовить кое-что необычайно важное для твоего путешествия.$B$BДля создания оружия, которое ты ищешь, необходим состав для закалки. Подожди немного, я выжму кровь из этих голов.$B$B<Лорд Арккорок сжимает головы между своими гигантскими ладонями, выдавливая из них кровь.>$B$BДоставь этот состав для закалки Лораму вместе с именем зверя: Рах\'лих.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите состав для закалки Лораму Многоногу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот состав содержит протравку, необходимую нам для отковки оружия. Это еще один шаг к созданию сего оружия.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С возвращением! Я рад видеть тебя, $R. Тебе удалось узнать подлинное имя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3512,'Судя по словам Эраникуса...','$n, нашим первым шагом будет разработка способа связаться с Эраникусом через этот камень. Он сейчас находится на зыбкой грани между сном и смертью, в сетях кошмаров. Хотя принесенная тобою сущность сильно поражена порчей, все еще есть шанс, что мы дотянемся до Эраникуса.$B$BТебе придется отправиться далеко на север и к востоку от Зимних ключей разыскать нашего смертного союзника, Умбранса Ищущего Духов. Он умеет говорить с мертвыми. Хотя Эраникус и не вполне мертв, этот человек все же сможет нам помочь.','Отправляйтесь в восточную часть Зимних Ключей и поговорите с Умбрансом Ищущим Духов.','Хорошо, что Итар послал тебя ко мне. Хотя Эраникус и не мертв в общем смысле этого слова, я смогу поговорить с ним. Но прямо сейчас я не могу помочь тебе...$B$BЯ с удовольствием это сделаю, но сначала мне самому нужна помощь того, кто, в отличие от меня, не скован старческой немощью. Мой наиболее ценный гадальный инструмент был у меня украден, и, пока я не заполучу его обратно, я бессилен помочь Эраникусу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судя по словам Эраникуса...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, нашим первым шагом будет разработка способа связаться с Эраникусом через этот камень. Он сейчас находится на зыбкой грани между сном и смертью, в сетях кошмаров. Хотя принесенная тобою сущность сильно поражена порчей, все еще есть шанс, что мы дотянемся до Эраникуса.$B$BТебе придется отправиться далеко на север и к востоку от Зимних ключей разыскать нашего смертного союзника, Умбранса Ищущего Духов. Он умеет говорить с мертвыми. Хотя Эраникус и не вполне мертв, этот человек все же сможет нам помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в восточную часть Зимних Ключей и поговорите с Умбрансом Ищущим Духов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что Итар послал тебя ко мне. Хотя Эраникус и не мертв в общем смысле этого слова, я смогу поговорить с ним. Но прямо сейчас я не могу помочь тебе...$B$BЯ с удовольствием это сделаю, но сначала мне самому нужна помощь того, кто, в отличие от меня, не скован старческой немощью. Мой наиболее ценный гадальный инструмент был у меня украден, и, пока я не заполучу его обратно, я бессилен помочь Эраникусу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3513,'Свиток с рунами','Свиток официального вида перевязан серебристой лентой. Несомненно, кому-то он был бы весьма интересен, но кому?$B$BНа севере, рядом с границей Ясеневого леса, есть застава, и если в свитке идет речь о ночных эльфах, именно туда его и надо отнести.','Отнесите свиток с рунами в северную сторожевую башню Степей.','Та-ак... И где ты это нашел?','Что это?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свиток с рунами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Свиток официального вида перевязан серебристой лентой. Несомненно, кому-то он был бы весьма интересен, но кому?$B$BНа севере, рядом с границей Ясеневого леса, есть застава, и если в свитке идет речь о ночных эльфах, именно туда его и надо отнести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите свиток с рунами в северную сторожевую башню Степей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Та-ак... И где ты это нашел?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3514,'Мощь Орды','Это послание от коварной дриады Ринтариэль, Хранительницы Ключей Логова Когтя на Пике Каменного Когтя.$B$BОна уже не встретится с гонцом, у которого ты нашел этот свиток, хе-хе, но так просто им это не пройдет. Орда не потерпит такого нахальства.$B$BСтупай в Логово Когтя, $n. Убей Ринтариэль и покажи это всем. Возьми с собой флаг Орды и установи его в Логове Когтя у всех на виду. В другой раз они трижды подумают, прежде чем снова соваться в наши земли.','Убейте предводительницу Логова Когтя, Ринтариэль Хранительницу Ключей.','Да ты $Gсилен:сильна;! Это большое дело – лишить Логово Когтя Ринтариэль. Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса. Они подумают дважды, чем прежде чем снова соваться к нам.$B$BСпасибо.','Мы не можем позволить Альянсу на нашей земле, $N. Сделайте это известным.','Вернитесь к Кадраку на Заставу Мор\'шан, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мощь Орды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это послание от коварной дриады Ринтариэль, Хранительницы Ключей Логова Когтя на Пике Каменного Когтя.$B$BОна уже не встретится с гонцом, у которого ты нашел этот свиток, хе-хе, но так просто им это не пройдет. Орда не потерпит такого нахальства.$B$BСтупай в Логово Когтя, $n. Убей Ринтариэль и покажи это всем. Возьми с собой флаг Орды и установи его в Логове Когтя у всех на виду. В другой раз они трижды подумают, прежде чем снова соваться в наши земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте предводительницу Логова Когтя, Ринтариэль Хранительницу Ключей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да ты $Gсилен:сильна;! Это большое дело – лишить Логово Когтя Ринтариэль. Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса. Они подумают дважды, чем прежде чем снова соваться к нам.$B$BСпасибо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы не можем позволить Альянсу на нашей земле, $N. Сделайте это известным.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кадраку на Заставу Мор\'шан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (3515,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (3516,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3517,'Тайненькое знаньице','Ты знаешь, $n, я, в общем, неплохо устроилась в Азшаре. У наказания Белгрома, обрушившегося на мою голову, есть свои положительные стороны. $B$BЯ тут полазала по окрестностям и обнаружила просто уйму ценностей, валяющихся без дела. $B$BЕсли интересно, могу рассказать подробнее и даже поделюсь прибылью, если поможешь мне добыть кое-что. $B$BВ руинах Эльдарата к востоку отсюда сокрыты четыре таблички. Каждая из них носит имя мага высокорожденных. Принеси мне их, и мы поговорим о дальнейшем сотрудничестве.','Найдите таблички Бет\'Амары, Джин\'яэль, Маркри и Саэль\'Хай и принесите их Джедиге в Азшару.','Отлично, $N, ты $Gпринес:принесла; все таблички, и они в хорошем состоянии. Мы получим за них хорошую цену.$B$BНу, не будем тратить время зря. Пора обменять таблички на денежки!','У меня есть знакомые, которые готовы отвалить за таблички неплохой куш. Я скажу тебе, кому нужно их доставить. Только без дураков, получишь свою долю после того, как принесешь мне расписку от клиента.$B$BПоторапливайся, время не ждет! А не то найду еще кого-нибудь в помощники!','Вернитесь к Джедиге в Азшару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайненькое знаньице',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты знаешь, $n, я, в общем, неплохо устроилась в Азшаре. У наказания Белгрома, обрушившегося на мою голову, есть свои положительные стороны. $B$BЯ тут полазала по окрестностям и обнаружила просто уйму ценностей, валяющихся без дела. $B$BЕсли интересно, могу рассказать подробнее и даже поделюсь прибылью, если поможешь мне добыть кое-что. $B$BВ руинах Эльдарата к востоку отсюда сокрыты четыре таблички. Каждая из них носит имя мага высокорожденных. Принеси мне их, и мы поговорим о дальнейшем сотрудничестве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите таблички Бет\'Амары, Джин\'яэль, Маркри и Саэль\'Хай и принесите их Джедиге в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N, ты $Gпринес:принесла; все таблички, и они в хорошем состоянии. Мы получим за них хорошую цену.$B$BНу, не будем тратить время зря. Пора обменять таблички на денежки!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня есть знакомые, которые готовы отвалить за таблички неплохой куш. Я скажу тебе, кому нужно их доставить. Только без дураков, получишь свою долю после того, как принесешь мне расписку от клиента.$B$BПоторапливайся, время не ждет! А не то найду еще кого-нибудь в помощники!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джедиге в Азшару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3518,'Доставка Магате','Первую табличку нужно отнести таурену по имени Магата. Ты найдешь ее среди старейшин Громового Утеса. Она самая ярая сторонница заключения союза тауренов с Отрекшимися, ибо считает, что именно таурены и их обычаи могут помочь Отрекшимся вновь найти путь к обретению человеческой природы. $B$BОтнеси ей табличку Бет\'Амары. Тауренка считает, что может найти в табличке способ, как помочь Отрекшимся... ну да, по крайней мере она в это верит.','Отнесите табличку Бет\'Амары Магате в Громовой Утес.','О, наконец-то! Табличка Бет\'Амары! А я уж гадала, неужели орк не сдержала обещания, или, чего доброго, бедняжка нашла кончину в Азшаре. Я рада, что ей удалось.$B$BБет\'Амара был одним из самых могущественных алхимиков высокорожденных. Говорят, что он единственный овладел искусством трансмутации металлов.','Приветствую тебя, $N Чем я могу помочь тебе? Говори быстрее, у меня много дел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка Магате',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первую табличку нужно отнести таурену по имени Магата. Ты найдешь ее среди старейшин Громового Утеса. Она самая ярая сторонница заключения союза тауренов с Отрекшимися, ибо считает, что именно таурены и их обычаи могут помочь Отрекшимся вновь найти путь к обретению человеческой природы. $B$BОтнеси ей табличку Бет\'Амары. Тауренка считает, что может найти в табличке способ, как помочь Отрекшимся... ну да, по крайней мере она в это верит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите табличку Бет\'Амары Магате в Громовой Утес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, наконец-то! Табличка Бет\'Амары! А я уж гадала, неужели орк не сдержала обещания, или, чего доброго, бедняжка нашла кончину в Азшаре. Я рада, что ей удалось.$B$BБет\'Амара был одним из самых могущественных алхимиков высокорожденных. Говорят, что он единственный овладел искусством трансмутации металлов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя, $N Чем я могу помочь тебе? Говори быстрее, у меня много дел.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3519,'Друг в беде','Ох... меня сильно покусала паучиха по имени Гитьис Зловещая, когда я обследовал паучиную пещеру. Похоже, я серьезно отравлен. Помоги мне!$B$BПожалуйста, дай знать Дирании Серебряному Сиянию. Она сможет помочь мне.$B$BСпеши... Как голова кружится...','Поговорите с Диранией Серебряным Сиянием в Тенистой долине.','Ох, какая беда, а я-то думала, что это сегодня Иверрона не видно... Предупреждала же я его насчет пауков!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друг в беде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох... меня сильно покусала паучиха по имени Гитьис Зловещая, когда я обследовал паучиную пещеру. Похоже, я серьезно отравлен. Помоги мне!$B$BПожалуйста, дай знать Дирании Серебряному Сиянию. Она сможет помочь мне.$B$BСпеши... Как голова кружится...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Диранией Серебряным Сиянием в Тенистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, какая беда, а я-то думала, что это сегодня Иверрона не видно... Предупреждала же я его насчет пауков!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3520,'Духи крикунов','Мне нужны духи дольных крикунов из Фераласа. Они родственники старого-престарого бога и напрямую связаны с ним.$b$bВозьми ежевичный посох и ступай в Фералас. Отыщи в южной и центральной части дольных крикунов и одержи над ними верх. Потом помаши моим посохом над их телами. Таким образом ты выманишь их души. Коснись каждой из душ и собери их сущности.$b$bПринеси мне посох и собранные сущности, и я расскажу тебе о том древнем боге.','Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе\'кинье в Порт Хитрой Шестеренки.','Вернитесь к Йе\'кинье в Порт Хитрой Шестеренки, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи крикунов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужны духи дольных крикунов из Фераласа. Они родственники старого-престарого бога и напрямую связаны с ним.$b$bВозьми ежевичный посох и ступай в Фералас. Отыщи в южной и центральной части дольных крикунов и одержи над ними верх. Потом помаши моим посохом над их телами. Таким образом ты выманишь их души. Коснись каждой из душ и собери их сущности.$b$bПринеси мне посох и собранные сущности, и я расскажу тебе о том древнем боге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе\'кинье в Порт Хитрой Шестеренки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йе\'кинье в Порт Хитрой Шестеренки, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (3521,'Противоядие для Иверрона','[Deprecated] I\'m really worried about my friend Iverron. He\'s been gone for nearly a day and I fear he may have been poisoned... or worse.$B$BI want you to gather the materials to make an antidote just in case. Gather hyacinth mushrooms from the base of the nearby trees, moonpetal lilies from around the water, and a webwood ichor from one of the spiders to the north.$B$BMixing it all together is simple enough, even if he\'s poisoned. He was heading north to Shadowthread Cave, hopefully you can find him near there.','[Deprecated] Collect 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, and 1 Webwood Ichor.','Хвала Элуне – ты так быстро $Gсобрал:собрала; все ингредиенты!$B$BПодожди минутку, сейчас я приготовлю противоядие.','[Deprecated] Find Iverron near Shadowthread Cave.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Противоядие для Иверрона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[Deprecated] I\'m really worried about my friend Iverron. He\'s been gone for nearly a day and I fear he may have been poisoned... or worse.$B$BI want you to gather the materials to make an antidote just in case. Gather hyacinth mushrooms from the base of the nearby trees, moonpetal lilies from around the water, and a webwood ichor from one of the spiders to the north.$B$BMixing it all together is simple enough, even if he\'s poisoned. He was heading north to Shadowthread Cave, hopefully you can find him near there.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[Deprecated] Collect 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, and 1 Webwood Ichor.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала Элуне – ты так быстро $Gсобрал:собрала; все ингредиенты!$B$BПодожди минутку, сейчас я приготовлю противоядие.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Find Iverron near Shadowthread Cave.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (3522,'Противоядие для Иверрона','Противоядие готово, $n. Пожалуйста, проследи, чтобы Иверрон его выпил.$B$BИ запомни – это важно: противоядие будет обладать своими целебными свойствами в течение пяти минут. Необходимо доставить его до истечения этого времени.$B$BПоторопись, во имя Элуны!','Отнесите противоядие Иверрону, прежде чем оно потеряет свои целебные свойства. Иверрона можно найти около пещеры, что к северу отсюда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Противоядие для Иверрона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Противоядие готово, $n. Пожалуйста, проследи, чтобы Иверрон его выпил.$B$BИ запомни – это важно: противоядие будет обладать своими целебными свойствами в течение пяти минут. Необходимо доставить его до истечения этого времени.$B$BПоторопись, во имя Элуны!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите противоядие Иверрону, прежде чем оно потеряет свои целебные свойства. Иверрона можно найти около пещеры, что к северу отсюда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (3523,'Плеть и Курганы','Благодарю, что $gспас:спасла; меня! Имя мне Белнистраз. Не хотелось бы закончить жизнь столь бесславно – быть сожранным одной из омерзительных тварей Плети. Да-да, ты не $gослышался:ослышалась;, Плеть вступила в союз с местными свинобразами.$B$BПослушай... вместо того, чтобы бежать, спасая собственную жизнь, я бы предпочел вступить с врагом в бой, чтобы защитить невинных. Не желаешь ли ты мне помочь? Это опасно, но ты явно не из тех, кто пасует перед трудностями.','Если вы хотите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы, который он дал вам.','Я далек от политики. Мне нет дела до того, связан ли ты с Ордой или Альянсом. Все, чего я хочу – уничтожить прямую и неотвратимую угрозу всем расам этого мира. \n\nЕсли ты хочешь стать героем для всех народов, отдай мне Камень клятвы, который получил от меня в знак своего согласия. Я... не из здешних мест; у нас принято скреплять договоренности Камнем клятвы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плеть и Курганы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодарю, что $gспас:спасла; меня! Имя мне Белнистраз. Не хотелось бы закончить жизнь столь бесславно – быть сожранным одной из омерзительных тварей Плети. Да-да, ты не $gослышался:ослышалась;, Плеть вступила в союз с местными свинобразами.$B$BПослушай... вместо того, чтобы бежать, спасая собственную жизнь, я бы предпочел вступить с врагом в бой, чтобы защитить невинных. Не желаешь ли ты мне помочь? Это опасно, но ты явно не из тех, кто пасует перед трудностями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы, который он дал вам.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я далек от политики. Мне нет дела до того, связан ли ты с Ордой или Альянсом. Все, чего я хочу – уничтожить прямую и неотвратимую угрозу всем расам этого мира. \n\nЕсли ты хочешь стать героем для всех народов, отдай мне Камень клятвы, который получил от меня в знак своего согласия. Я... не из здешних мест; у нас принято скреплять договоренности Камнем клятвы.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3524,'Останки на берегу','Громадные морские твари выбрасываются на пески Темных берегов и лежат там, пока не умирают. В последнее время останки этих тварей выносит на берег все чаще и чаще. Меня послали сюда из Храма Луны для расследования ситуации, но наличие мурлоков у береговой линии затрудняет мою задачу.$B$BОдни такие останки лежат на юге от Аубердина, совсем рядом, но вокруг очень много злобных мурлоков из племени Серой Мглы. Можешь сходить туда и принести мне для изучения кости этой твари?','Соберите кости морской твари, выброшенной на берег к югу от Аубердина, и принесите их Гвеннид Блай\'Леггонд в Аубердин.','Я надеюсь, что мурлоки не слишком досаждали вам, пока вы собирали для нас эти кости! Я непременно следующим же гиппогрифом доставлю их в Дарнасс. Храм Луны снабдил меня некоторыми средствами, которыми я могла бы расплачиваться за помощь; пожалуйста, примите немного денег вместе с нашей благодарностью.$B$BВаш успех побуждает меня предложить вам возможность и дальше оказывать помощь Храму Луны, если вы заинтересованы в этом...','Эти морские твари только недавно стали приплывать на отмели Темных берегов в таких тревожно больших количествах. Не могу сказать точно, но думаю, что это своего рода дурное предзнаменование. Извлечение образцов костей такой твари, что лежит к югу отсюда, поможет нам в Дарнасе оценить ситуацию!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Останки на берегу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Громадные морские твари выбрасываются на пески Темных берегов и лежат там, пока не умирают. В последнее время останки этих тварей выносит на берег все чаще и чаще. Меня послали сюда из Храма Луны для расследования ситуации, но наличие мурлоков у береговой линии затрудняет мою задачу.$B$BОдни такие останки лежат на юге от Аубердина, совсем рядом, но вокруг очень много злобных мурлоков из племени Серой Мглы. Можешь сходить туда и принести мне для изучения кости этой твари?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите кости морской твари, выброшенной на берег к югу от Аубердина, и принесите их Гвеннид Блай\'Леггонд в Аубердин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я надеюсь, что мурлоки не слишком досаждали вам, пока вы собирали для нас эти кости! Я непременно следующим же гиппогрифом доставлю их в Дарнасс. Храм Луны снабдил меня некоторыми средствами, которыми я могла бы расплачиваться за помощь; пожалуйста, примите немного денег вместе с нашей благодарностью.$B$BВаш успех побуждает меня предложить вам возможность и дальше оказывать помощь Храму Луны, если вы заинтересованы в этом...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти морские твари только недавно стали приплывать на отмели Темных берегов в таких тревожно больших количествах. Не могу сказать точно, но думаю, что это своего рода дурное предзнаменование. Извлечение образцов костей такой твари, что лежит к югу отсюда, поможет нам в Дарнасе оценить ситуацию!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (3525,'Уничтожить идола','Рядом с входом ты увидишь идола – свинобразы используют его как жертвенный очаг. Эти твари на самом деле пожирают своих пленников из Степей. Я должен разбить идола, чтобы они более никогда не могли его использовать, но мне потребуется твоя помощь. Сопроводи меня к идолу. Там я проведу ритуал, но при этом я даже не смогу говорить с тобой, не говоря уж о том, чтобы самому защитить себя. Тебе придется держать оборону, пока я буду проводить ритуал. Если меня убьют раньше, чем я закончу, это будет означать крах всех наших планов.$B$BТы $gготов:готова;?','Сопроводите Белнистраза к идолу свинобразов в Курганах Иглошкурых. $B$BЗащищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола.','Белнистраз исчезает, оставив на месте себя пылающее зарево. Вы видите в пламени очертания огромного крылатого красного дракона. Рокочущий голос Белнистраза наполняет ваше сознание.\n\n"Я всегда верил в вашу смелость, смертные. Благодаря тебе кровавым делам, вершимым здесь этими тварями, пришел конец. Моя вера в мужественность смертных созданий сегодня укрепилась. Прими эту награду – она достойна героя."','Я далек от политики. Мне нет дела до того, связан ли ты с Ордой или Альянсом. Все, чего я хочу – уничтожить прямую и неотвратимую угрозу всем расам этого мира. \n\nЕсли ты хочешь стать героем для всех народов, отдай мне Камень клятвы, который получил от меня в знак своего согласия. Я... не из здешних мест; у нас принято скреплять договоренности Камнем клятвы.','Защищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола.','Вернитесь к жаровне Белнистраза, что в Курганах Иглошкурых.','Защищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить идола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рядом с входом ты увидишь идола – свинобразы используют его как жертвенный очаг. Эти твари на самом деле пожирают своих пленников из Степей. Я должен разбить идола, чтобы они более никогда не могли его использовать, но мне потребуется твоя помощь. Сопроводи меня к идолу. Там я проведу ритуал, но при этом я даже не смогу говорить с тобой, не говоря уж о том, чтобы самому защитить себя. Тебе придется держать оборону, пока я буду проводить ритуал. Если меня убьют раньше, чем я закончу, это будет означать крах всех наших планов.$B$BТы $gготов:готова;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите Белнистраза к идолу свинобразов в Курганах Иглошкурых. $B$BЗащищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Белнистраз исчезает, оставив на месте себя пылающее зарево. Вы видите в пламени очертания огромного крылатого красного дракона. Рокочущий голос Белнистраза наполняет ваше сознание.\n\n"Я всегда верил в вашу смелость, смертные. Благодаря тебе кровавым делам, вершимым здесь этими тварями, пришел конец. Моя вера в мужественность смертных созданий сегодня укрепилась. Прими эту награду – она достойна героя."',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я далек от политики. Мне нет дела до того, связан ли ты с Ордой или Альянсом. Все, чего я хочу – уничтожить прямую и неотвратимую угрозу всем расам этого мира. \n\nЕсли ты хочешь стать героем для всех народов, отдай мне Камень клятвы, который получил от меня в знак своего согласия. Я... не из здешних мест; у нас принято скреплять договоренности Камнем клятвы.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жаровне Белнистраза, что в Курганах Иглошкурых.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Защищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3526,'Гоблинское инженерное дело','Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов!$B$BПрочитай этот учебник, $n. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса.','Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.','Что же, $N, ты $Gнашел:нашла; подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (повторяю: ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела.$B$BДержи ушки на макушке, $N, тогда чему-нибудь научишься.','Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинское инженерное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов!$B$BПрочитай этот учебник, $n. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что же, $N, ты $Gнашел:нашла; подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (повторяю: ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела.$B$BДержи ушки на макушке, $N, тогда чему-нибудь научишься.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3527,'Пророчество Мошару','Древнее пророчество Мошару повествует о том, как взять в плен сущность бога Хаккара. Пророчество записали на двух табличках и отнесли в тролльский город Зул\'Фаррак, что к западу от Прибамбасска.$b$bПринеси мне таблички Мошару!$b$bПервая табличка находится у давно умершего тролля Теки Мученика. Говорят, что его истязатели превратились в скарабеев и до сих пор ползают по его святилищу.$b$bВторая табличка – у гидроманта Велраты, рядом со священным озером Газ\'риллы.$b$bДобудешь таблички – сразу приходи.','Принесите первую и вторую таблички Мошару Йе\'кинье в Танарис.','Ты несешь мне таблички пророчества Мошару?$B$BЯ хочу изучить их и понять, как сковать сущность Хаккара!','Вернитесь к Йе\'кинье в Порт Хитрой Шестеренки, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пророчество Мошару',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древнее пророчество Мошару повествует о том, как взять в плен сущность бога Хаккара. Пророчество записали на двух табличках и отнесли в тролльский город Зул\'Фаррак, что к западу от Прибамбасска.$b$bПринеси мне таблички Мошару!$b$bПервая табличка находится у давно умершего тролля Теки Мученика. Говорят, что его истязатели превратились в скарабеев и до сих пор ползают по его святилищу.$b$bВторая табличка – у гидроманта Велраты, рядом со священным озером Газ\'риллы.$b$bДобудешь таблички – сразу приходи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите первую и вторую таблички Мошару Йе\'кинье в Танарис.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты несешь мне таблички пророчества Мошару?$B$BЯ хочу изучить их и понять, как сковать сущность Хаккара!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йе\'кинье в Порт Хитрой Шестеренки, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3528,'Бог Хаккар','Пришло время брать в плен сущность аватары Хаккара.$b$bОтнеси яйцо Хаккара в святилище Падшего Бога в Затонувшем храме Азерота. Призови силу яйца и разбуди мертвого бога.$b$bОн пошлет против тебя своих прислужников. Одолей их и нацеди из них крови Хаккари. Угаси при помощи этой крови вечный огонь, в котором заключен дух Хаккара. Когда пламя погаснет, в мир войдет аватара Хаккара.$b$BПобеди его и помести его сущность в яйцо Хаккара.','Отнесите заполненное яйцо Хаккара Йе\'кинье в Танарис.','Вернитесь к Йе\'кинье в Порт Хитрой Шестеренки, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бог Хаккар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время брать в плен сущность аватары Хаккара.$b$bОтнеси яйцо Хаккара в святилище Падшего Бога в Затонувшем храме Азерота. Призови силу яйца и разбуди мертвого бога.$b$bОн пошлет против тебя своих прислужников. Одолей их и нацеди из них крови Хаккари. Угаси при помощи этой крови вечный огонь, в котором заключен дух Хаккара. Когда пламя погаснет, в мир войдет аватара Хаккара.$b$BПобеди его и помести его сущность в яйцо Хаккара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите заполненное яйцо Хаккара Йе\'кинье в Танарис.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йе\'кинье в Порт Хитрой Шестеренки, что в Танарисе.',`completedtext_loc8`);
