INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3541,'Доставка Джес\'римону','В Оргриммаре есть у меня скупщик краденого. У него притон в Волоке. Этого скользкого типа нелегко найти, если не знать точно где искать. Запомни: искать следует в одном из самых высоких зданий. $B$BТолько сделай мне одолжение, не ори на весь Калимдор, где он и чем занимается – это было бы... весьма неприятно для нас обоих. $B$BОн готов заплатить очень хорошую цену за табличку Джин\'яэль. Не знаю, зачем уж она ему сдалась, но $gвидел:видела; бы ты, как у него загорелись глаза, когда я упомянула, что знаю, где ее найти!','Отнесите табличку Джин\'яэль Джес\'римону в Оргриммар.','Ага, Джедига прислала мне посылку... Великолепно, я ждал ее.$B$BДа, Джедига славная бабенка! Свирепая как волчица... что может быть лучше?$B$BКак я погляжу, табличка в целости и сохранности. А что это значит, $N? Значит, посыльный получит на магарыч!','Ну, что тебе нужно, $N? У меня на сегодня уйма дел, и ты в их число не входишь. Впрочем, если будешь путаться под ногами, найдется и на тебя минутка!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка Джес\'римону',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Оргриммаре есть у меня скупщик краденого. У него притон в Волоке. Этого скользкого типа нелегко найти, если не знать точно где искать. Запомни: искать следует в одном из самых высоких зданий. $B$BТолько сделай мне одолжение, не ори на весь Калимдор, где он и чем занимается – это было бы... весьма неприятно для нас обоих. $B$BОн готов заплатить очень хорошую цену за табличку Джин\'яэль. Не знаю, зачем уж она ему сдалась, но $gвидел:видела; бы ты, как у него загорелись глаза, когда я упомянула, что знаю, где ее найти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите табличку Джин\'яэль Джес\'римону в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, Джедига прислала мне посылку... Великолепно, я ждал ее.$B$BДа, Джедига славная бабенка! Свирепая как волчица... что может быть лучше?$B$BКак я погляжу, табличка в целости и сохранности. А что это значит, $N? Значит, посыльный получит на магарыч!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что тебе нужно, $N? У меня на сегодня уйма дел, и ты в их число не входишь. Впрочем, если будешь путаться под ногами, найдется и на тебя минутка!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3542,'Доставка Андрону Ганту','Теперь ты отправишься к Андрону Ганту. Он обретается в Подгороде, недалеко от Района Фармацевтов. $B$BЭтот был более многословен, когда я спросила, зачем ему нужна табличка. Маги Подгорода хотят изучить некоторые тайные заклинания высокорожденных. Они считают, что табличка им в этом поможет. Маркри был очень талантлив в чарах призыва различных существ, особенно элементалей. $B$BОтнеси ему табличку Маркри и возвращайся за своей долей.','Отнесите табличку Маркри Андрону Ганту в Подгород.','Вот, возьми пару монет... *ик*... купи себе новую броню... или шляпу.$B$BНичего не жаль для хороших посыльных!','Ого... <ик> вот так сюрприз! <ик> Да у меня гости! <ик> Чем, так сказать, могу?.. <ик>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка Андрону Ганту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты отправишься к Андрону Ганту. Он обретается в Подгороде, недалеко от Района Фармацевтов. $B$BЭтот был более многословен, когда я спросила, зачем ему нужна табличка. Маги Подгорода хотят изучить некоторые тайные заклинания высокорожденных. Они считают, что табличка им в этом поможет. Маркри был очень талантлив в чарах призыва различных существ, особенно элементалей. $B$BОтнеси ему табличку Маркри и возвращайся за своей долей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите табличку Маркри Андрону Ганту в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, возьми пару монет... *ик*... купи себе новую броню... или шляпу.$B$BНичего не жаль для хороших посыльных!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ого... <ик> вот так сюрприз! <ик> Да у меня гости! <ик> Чем, так сказать, могу?.. <ик>',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3561,'Доставка верховному магу Ксилему','Последнюю табличку надлежит доставить весьма опасному человеку, $n. Можешь не сомневаться, я доверяю ему куда меньше,чем кому-либо из тех, к кому я тебя отправляла. $B$BВерховный маг Ксилем живет в башне в холмах, возвышающихся над Азшарой. Он человек, однако он не похож на людей, которых мне приходилось встречать... или убивать. Он необычайно властен. Я не смею спросить его, что он собирается делать с табличкой. $B$BОн сказал мне, что страж его, Санат, поможет мне попасть в его башню, когда я буду готова предстать перед ним. Ищи Саната на севере.','Отнесите табличку Саэль\'Хай верховному магу Ксилему в Азшару.','О, табличка Саэль\'Хай... как давно я мечтал изучить ее!$B$BБлагодарю тебя, $N. Скажи Джедиге, что я доволен работой. Орк заслужила свою награду.','Зачем ты $Gявился:явилась; ко мне, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка верховному магу Ксилему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последнюю табличку надлежит доставить весьма опасному человеку, $n. Можешь не сомневаться, я доверяю ему куда меньше,чем кому-либо из тех, к кому я тебя отправляла. $B$BВерховный маг Ксилем живет в башне в холмах, возвышающихся над Азшарой. Он человек, однако он не похож на людей, которых мне приходилось встречать... или убивать. Он необычайно властен. Я не смею спросить его, что он собирается делать с табличкой. $B$BОн сказал мне, что страж его, Санат, поможет мне попасть в его башню, когда я буду готова предстать перед ним. Ищи Саната на севере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите табличку Саэль\'Хай верховному магу Ксилему в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, табличка Саэль\'Хай... как давно я мечтал изучить ее!$B$BБлагодарю тебя, $N. Скажи Джедиге, что я доволен работой. Орк заслужила свою награду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Зачем ты $Gявился:явилась; ко мне, $N?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3562,'[DEPRECATED] Плата Магаты Джедиге','Отнеси это послание Джедиге. Скажи ей, что я заплачу ей лично, когда она придет ко мне.$B$BСтупай скорее, $n. Скажи своей госпоже, что награда ожидает ее.','Отнесите записку Магаты Джедиге в Азшару.','А, отлично. Она поступила вполне разумно. По крайней мене по отношению к тебе. Я побаивалась, что она сделает с тобой что-нибудь неприятное, чтобы наказать меня за высокомерие. Она любит, чтобы к ней являлись лично, а не отправляли мальчиков на побегушках. Похоже, она действительно обрадовалась табличке.$B$BЧто ж, посмотрим.','Что сказала Магата? Старая карга наверняка выбрала словечко покрепче...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Плата Магаты Джедиге',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси это послание Джедиге. Скажи ей, что я заплачу ей лично, когда она придет ко мне.$B$BСтупай скорее, $n. Скажи своей госпоже, что награда ожидает ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите записку Магаты Джедиге в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, отлично. Она поступила вполне разумно. По крайней мене по отношению к тебе. Я побаивалась, что она сделает с тобой что-нибудь неприятное, чтобы наказать меня за высокомерие. Она любит, чтобы к ней являлись лично, а не отправляли мальчиков на побегушках. Похоже, она действительно обрадовалась табличке.$B$BЧто ж, посмотрим.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что сказала Магата? Старая карга наверняка выбрала словечко покрепче...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3563,'Плата Джес\'римона Джедиге','Отнеси это послание Джедиге. Скажи ей, что я доволен ее работой.$B$BСкажи, чтобы скорее возвращалась в Оргриммар – Джес\'римон достойно наградит ее. $B$BПередай ей это, и, возможно, впредь я буду давать тебе поручения, $n.','Доставьте записку Джес\'римона Джедиге в Азшару.','Судя по этому письму, Джесримон весьма доволен нашей работой...$B$BЗнал бы он как я довольна работой, которую он мне дает... Ну, теперь у меня есть еще одна причина задержаться в Азшаре.$B$BВот, забирай свою долю.','Ты $Gговорил:говорила; с Джес\'римоном?$B$BСреди троллей он реальный кабан, однако за работу платит хорошо и аккуратно.$B$BЕсли сможешь выдержать его манеры, непременно заработаешь хороший барыш на выполнении его поручений.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плата Джес\'римона Джедиге',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси это послание Джедиге. Скажи ей, что я доволен ее работой.$B$BСкажи, чтобы скорее возвращалась в Оргриммар – Джес\'римон достойно наградит ее. $B$BПередай ей это, и, возможно, впредь я буду давать тебе поручения, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте записку Джес\'римона Джедиге в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Судя по этому письму, Джесримон весьма доволен нашей работой...$B$BЗнал бы он как я довольна работой, которую он мне дает... Ну, теперь у меня есть еще одна причина задержаться в Азшаре.$B$BВот, забирай свою долю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gговорил:говорила; с Джес\'римоном?$B$BСреди троллей он реальный кабан, однако за работу платит хорошо и аккуратно.$B$BЕсли сможешь выдержать его манеры, непременно заработаешь хороший барыш на выполнении его поручений.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3564,'Плата Андрона Джедиге','Вот *ик!* держи *ик!* Это для Джедиги. И ты это, *ик* заходи, если что!','Доставьте записку Андрона Джедиге в Азшару.','Ха-ха! Что ты $Gсказал:сказала; ему, когда отдавал табличку, $N? Он заплатил нам едва ли не дважды сверх уговоренного! Нет, я конечно, не жалуюсь... Ты $Gсказал:сказала; ему, что я изменила условия сделки? Или этот пьянчуга опять шары залил и не соображал, что делает?$B$BНу, уже неважно. Вот, держи свою долю – с премией!','Ну что, ты $Gговорил:говорила; с Андроном? Он редко покидает Подгород, так что не думаю, что его будет сложно найти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плата Андрона Джедиге',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот *ик!* держи *ик!* Это для Джедиги. И ты это, *ик* заходи, если что!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте записку Андрона Джедиге в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха! Что ты $Gсказал:сказала; ему, когда отдавал табличку, $N? Он заплатил нам едва ли не дважды сверх уговоренного! Нет, я конечно, не жалуюсь... Ты $Gсказал:сказала; ему, что я изменила условия сделки? Или этот пьянчуга опять шары залил и не соображал, что делает?$B$BНу, уже неважно. Вот, держи свою долю – с премией!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, ты $Gговорил:говорила; с Андроном? Он редко покидает Подгород, так что не думаю, что его будет сложно найти.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3565,'Плата Ксилема Джедиге','Что еще? Ах да, оплата. Конечно. $B$BВот, возьми и выметайся. Уверен, Джедига ждет не дождется твоего возвращения.','Доставь записку Ксилема Джедиге в Азшару.','Что, в самом деле не случилось ничего неприятного? И он отдал тебе деньги не торгуясь? Ушам не верю... Я, честно признаться, ожидала какого-то подвоха. Похоже, с ним все же можно иметь дело.$B$BВот, держи свою награду. Спасибо за помощь.','Ну, что сказал тебе Ксилем? Ничего с тобой не сделал? Не пытался заманить тебя к себе в услужение?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плата Ксилема Джедиге',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что еще? Ах да, оплата. Конечно. $B$BВот, возьми и выметайся. Уверен, Джедига ждет не дождется твоего возвращения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставь записку Ксилема Джедиге в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, в самом деле не случилось ничего неприятного? И он отдал тебе деньги не торгуясь? Ушам не верю... Я, честно признаться, ожидала какого-то подвоха. Похоже, с ним все же можно иметь дело.$B$BВот, держи свою награду. Спасибо за помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что сказал тебе Ксилем? Ничего с тобой не сделал? Не пытался заманить тебя к себе в услужение?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3566,'Восстань, Обсидион!','Это... была... ловушка... $B$BПрости... меня... $B$BТы $gдолжен:должна; убить предателя... Отомсти ему за нас... За Ториуса...','Убейте Латорика Черного и Обсидиона и принесите голову Латорика и сердце Обсидиона Ториусу в Стальгорн.','<Ториус бледнеет.>$B$BЭтого не может быть... Мой единокровный брат! Неужели он мог это сделать?!$B$B<Лицо Ториуса искажает ярость>$B$BОн предал меня, он предал Стальгорн! Видимо, влияние Древних Богов еще сильно в этих землях. Боюсь, если даже мой брат – некогда благородный и уважаемый человек – так легко поддался воле Рагнароса, никто их нас не может чувствовать себя в безопасности!','Я не верю! Ты можешь доказать, что это не ложь?','Вернитесь к смотрителю Ториусу в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстань, Обсидион!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это... была... ловушка... $B$BПрости... меня... $B$BТы $gдолжен:должна; убить предателя... Отомсти ему за нас... За Ториуса...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Латорика Черного и Обсидиона и принесите голову Латорика и сердце Обсидиона Ториусу в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ториус бледнеет.>$B$BЭтого не может быть... Мой единокровный брат! Неужели он мог это сделать?!$B$B<Лицо Ториуса искажает ярость>$B$BОн предал меня, он предал Стальгорн! Видимо, влияние Древних Богов еще сильно в этих землях. Боюсь, если даже мой брат – некогда благородный и уважаемый человек – так легко поддался воле Рагнароса, никто их нас не может чувствовать себя в безопасности!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не верю! Ты можешь доказать, что это не ложь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к смотрителю Ториусу в Стальгорн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (3567,'Умный в гору не пойдет...','Хочешь посмотреть, какой вид открывается во-он оттуда, с тех Двух Колоссов? Могу тебя туда отправить, |3-6($R).$B$BТолько подумай заранее, как потом будешь спускаться. Это путешествие в один конец.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Умный в гору не пойдет...',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хочешь посмотреть, какой вид открывается во-он оттуда, с тех Двух Колоссов? Могу тебя туда отправить, |3-6($R).$B$BТолько подумай заранее, как потом будешь спускаться. Это путешествие в один конец.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (3568,'Разносчик заразы','Видишь этого несчастного таурена? Она недавно побывала в Азшаре. Среди руин Эльдарата она была ранена в бою с нагами.$B$BОтбившись от них, она решила отдохнуть на берегу и попила водички из приливной заводи. Теперь ее тошнит... помимо всего прочего.$B$BМне нужно выяснить, что она пила. Возьми этот ящик, в нем несколько помеченных фиалов. Наполни их из разных заводей и возвращайся.','Наполните все 4 пустых фиала из приливных заводей в руинах Эльдарата и возвращайтесь к химику Карабосу.','Чудесно. Ты успел вернуться до ее гибели. Славно, славно.\n\nЗначит, пора приступать.\n\nЯ некоторое время изучал симптомы ее болезни, и теперь дело совсем плохо. Удивительно, как она на ногах держится. Ее уже три или четыре раза вырвало... запах просто чудесный.\n\nДай-ка я состряпаю что-нибудь для нашей... подруги.','Вернитесь к химику Карабосу в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разносчик заразы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь этого несчастного таурена? Она недавно побывала в Азшаре. Среди руин Эльдарата она была ранена в бою с нагами.$B$BОтбившись от них, она решила отдохнуть на берегу и попила водички из приливной заводи. Теперь ее тошнит... помимо всего прочего.$B$BМне нужно выяснить, что она пила. Возьми этот ящик, в нем несколько помеченных фиалов. Наполни их из разных заводей и возвращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните все 4 пустых фиала из приливных заводей в руинах Эльдарата и возвращайтесь к химику Карабосу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно. Ты успел вернуться до ее гибели. Славно, славно.\n\nЗначит, пора приступать.\n\nЯ некоторое время изучал симптомы ее болезни, и теперь дело совсем плохо. Удивительно, как она на ногах держится. Ее уже три или четыре раза вырвало... запах просто чудесный.\n\nДай-ка я состряпаю что-нибудь для нашей... подруги.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к химику Карабосу в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3569,'Разносчик заразы','Отнеси эликсир Терсе – вдруг он ей поможет? Пока она не выпьет его, точно не скажешь.','Дайте эликсир Карабоса Терсе Песне Ветра в Подгороде.','Химик Карабос – само гостеприимство... даже не по себе стало. Но если он говорит, что есть шанс излечиться, выбора нет. Искать другие лекарства нет времени. Ни жрецы, ни шаманы не смогли мне помочь.\n\nБудем надеяться, что Мать-земля сохранит мою душу.','Я пришла в Подгород, потому что слышала, что алхимики давно работают над созданием лекарств, которые могут исцелить их собственную болезнь. Я надеялась, что они и мне помогут.\n\nХотя я чувствую себя не в своей тарелке, выбора нет – боль раздирает меня изнутри, и мне срочно нужна помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разносчик заразы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси эликсир Терсе – вдруг он ей поможет? Пока она не выпьет его, точно не скажешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дайте эликсир Карабоса Терсе Песне Ветра в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Химик Карабос – само гостеприимство... даже не по себе стало. Но если он говорит, что есть шанс излечиться, выбора нет. Искать другие лекарства нет времени. Ни жрецы, ни шаманы не смогли мне помочь.\n\nБудем надеяться, что Мать-земля сохранит мою душу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я пришла в Подгород, потому что слышала, что алхимики давно работают над созданием лекарств, которые могут исцелить их собственную болезнь. Я надеялась, что они и мне помогут.\n\nХотя я чувствую себя не в своей тарелке, выбора нет – боль раздирает меня изнутри, и мне срочно нужна помощь.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (3570,'Разносчик заразы','Я и не думал, что эликсир сработает так быстро. Спасибо, $N. Займусь-ка работой над остальными образцами. Уверен, вскоре леди Сильвана и Отрекшиеся будут их активно использовать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разносчик заразы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я и не думал, что эликсир сработает так быстро. Спасибо, $N. Займусь-ка работой над остальными образцами. Уверен, вскоре леди Сильвана и Отрекшиеся будут их активно использовать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (3581,'<UNUSED>','Imagine yourself racing across the plains, through forests and over mountains, the wind in your face... Traveling over unseen territory; the wonder of the road ahead, your destiny resting just over the horizon.$B$BAlways remember that on hoof, many things are achievable; as a Tauren, you will be granted the swiftness of Plainsrunning. There is no limit to the distances you might go.','Speak to Saern Priderunner again to learn the Plainsrunning skill.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Imagine yourself racing across the plains, through forests and over mountains, the wind in your face... Traveling over unseen territory; the wonder of the road ahead, your destiny resting just over the horizon.$B$BAlways remember that on hoof, many things are achievable; as a Tauren, you will be granted the swiftness of Plainsrunning. There is no limit to the distances you might go.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to Saern Priderunner again to learn the Plainsrunning skill.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3601,'Оскорбленный Ким\'джаель','Ким\'джаель оскорблен до глубины души! Знаешь, что на самом деле Ким\'джаель значит для эльфов крови, $n? Я для них всего лишь букашка! Маленькое безвредное создание, на которое можно и наступить – не жалко! $B$BОни наняли меня, чтобы я обшарил для них место, где, как они сказали, спрятано сокровище. Ну ты понимаешь, при слове "сокровище" я утратил бдительность и купился на их посулы! Конечно же, они предали меня и даже пытались прикончить! $B$BНикогда нельзя верить мерзким эльфам крови! $B$BМне удалось уйти живым, но у негодяев осталось все мое снаряжение! Пожалуйста, забери его у них!','Обыщите Талассийское поселение и найдите компас, прицел, плюшевого цыпленка и центробежный растягиватель Ким\'джаеля. Верните все это Ким\'джаелю в Азшару.','Ха! Так им и надо!$B$BВот это круто! Теперь-то они знают, что значит предавать своих партнеров! Особенно гоблинов!$B$BНу, теперь о твоей награде... я же сказал, значит, заплачу.$B$BВот, держи... может, пригодится.','Мерзкие эльфы крови! Да-да, если бы я был таким же большим и сильным, как ты, уж я бы научил их хорошим манерам. Я поскольку я может и сильный, но легкий, я лучше заплачу тебе, чтобы ты $Gсделал:сделала; это за меня.','Вернитесь к Ким\'джаелю в Талассийское поселение, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскорбленный Ким\'джаель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ким\'джаель оскорблен до глубины души! Знаешь, что на самом деле Ким\'джаель значит для эльфов крови, $n? Я для них всего лишь букашка! Маленькое безвредное создание, на которое можно и наступить – не жалко! $B$BОни наняли меня, чтобы я обшарил для них место, где, как они сказали, спрятано сокровище. Ну ты понимаешь, при слове "сокровище" я утратил бдительность и купился на их посулы! Конечно же, они предали меня и даже пытались прикончить! $B$BНикогда нельзя верить мерзким эльфам крови! $B$BМне удалось уйти живым, но у негодяев осталось все мое снаряжение! Пожалуйста, забери его у них!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите Талассийское поселение и найдите компас, прицел, плюшевого цыпленка и центробежный растягиватель Ким\'джаеля. Верните все это Ким\'джаелю в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Так им и надо!$B$BВот это круто! Теперь-то они знают, что значит предавать своих партнеров! Особенно гоблинов!$B$BНу, теперь о твоей награде... я же сказал, значит, заплачу.$B$BВот, держи... может, пригодится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мерзкие эльфы крови! Да-да, если бы я был таким же большим и сильным, как ты, уж я бы научил их хорошим манерам. Я поскольку я может и сильный, но легкий, я лучше заплачу тебе, чтобы ты $Gсделал:сделала; это за меня.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ким\'джаелю в Талассийское поселение, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3602,'Азшарит','Древние скальные великаны из южных регионов Азшары для поддержания существования поглощают камни и каменные образования. Продуктом переработки такой "пищи" являются чрезвычайно податливые, но при этом необычайно прочные кристаллы, известные как азшарит. $B$BНа южной гряде находятся целые залежи азшарита, однако его почти никому не удавалось добыть из-за чрезвычайной жестокости великанов.$B$BТебе следует отправиться на юг и раздобыть азшарита столько, чтобы его хватило для создания оружия. Мои гончие скверны помогут в розыске кристаллов.','Найдите в южной Азшаре двадцать кристаллов азшарита. Вы можете использовать Гончих Скверны, которые помогут вам "вынюхивать" местонахождение хорошо сокрытых залежей. $B$BКогда задача будет завершена, возвращайтесь к Лораму Многоногу.','Твои задачи в Азшаре завершены. Теперь я должен подготовить все необходимое для следующего шага твоего пути.','Зло не спит, и глуп тот, кто думает иначе. Отдохнешь после смерти. Принеси же мне кристаллы.','Вернитесь к Лораму Многоногу на Залив Бурь, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Азшарит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древние скальные великаны из южных регионов Азшары для поддержания существования поглощают камни и каменные образования. Продуктом переработки такой "пищи" являются чрезвычайно податливые, но при этом необычайно прочные кристаллы, известные как азшарит. $B$BНа южной гряде находятся целые залежи азшарита, однако его почти никому не удавалось добыть из-за чрезвычайной жестокости великанов.$B$BТебе следует отправиться на юг и раздобыть азшарита столько, чтобы его хватило для создания оружия. Мои гончие скверны помогут в розыске кристаллов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в южной Азшаре двадцать кристаллов азшарита. Вы можете использовать Гончих Скверны, которые помогут вам "вынюхивать" местонахождение хорошо сокрытых залежей. $B$BКогда задача будет завершена, возвращайтесь к Лораму Многоногу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои задачи в Азшаре завершены. Теперь я должен подготовить все необходимое для следующего шага твоего пути.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Зло не спит, и глуп тот, кто думает иначе. Отдохнешь после смерти. Принеси же мне кристаллы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лораму Многоногу на Залив Бурь, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3621,'Создание отравы Скверны','Оружие готово к отковке. Тебе следует отнести закаленный азшарит к тому, кто может обуздать энергию скверны.$B$BВ Тернистой долине живет такой кузнец. Гальван Древний, глава Ордена Мифрила, создаст оружие по твоему заказу. Ты можешь найти его становище между Зул\'Гурубом и холмом Мош\'Огг.$B$BПусть решительность и вера помогут тебе пройти это испытание. А если ты погибнешь, знай, что твой Бог тебе улыбается.','Отнести груз Гальвану Древнему в Тернистую долину.','Могу лишь вообразить, через что тебе пришлось пройти, чтобы раздобыть эти материалы. Немногим удавалось вернуться живыми из Азшары, не говоря уж о том, чтобы встретиться лицом к лицу с полубогами и демонами.','Вот как, Лорамус? Прошло много лет с тех пор, как я в последний раз слышал это имя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Создание отравы Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оружие готово к отковке. Тебе следует отнести закаленный азшарит к тому, кто может обуздать энергию скверны.$B$BВ Тернистой долине живет такой кузнец. Гальван Древний, глава Ордена Мифрила, создаст оружие по твоему заказу. Ты можешь найти его становище между Зул\'Гурубом и холмом Мош\'Огг.$B$BПусть решительность и вера помогут тебе пройти это испытание. А если ты погибнешь, знай, что твой Бог тебе улыбается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнести груз Гальвану Древнему в Тернистую долину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Могу лишь вообразить, через что тебе пришлось пройти, чтобы раздобыть эти материалы. Немногим удавалось вернуться живыми из Азшары, не говоря уж о том, чтобы встретиться лицом к лицу с полубогами и демонами.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вот как, Лорамус? Прошло много лет с тех пор, как я в последний раз слышал это имя.',`requestitemstext_loc8`);
