INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (3625,'Зачарованное азшаритовое оружие, отравленное Скверной','$n, для создания оружия необходимо время.$B$BВдобавок, ты можешь использовать силу оружия Проклятия Скверны лишь раз в три минуты. Длительность действия, ослабляющего Разелиха Осквернителя и его приспешников, может быть различной. Именно поэтому следует высвобождать силу Проклятия Скверны лишь в нужный момент!$B$BТеперь дай мне время на создания оружия для тебя, $n.','Подождите, пока Гальван закончит отковывать оружие.','<Гальван вытирает пот со лба..>$B$BНикогда еще не существовало более подходящего оружия для убиения демона, $N.','Если вмешиваться в процесс, то оружие может получиться с изъяном. Терпение, $N.','Оружие выковано.','Вернитесь к Гальвану Древнему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачарованное азшаритовое оружие, отравленное Скверной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, для создания оружия необходимо время.$B$BВдобавок, ты можешь использовать силу оружия Проклятия Скверны лишь раз в три минуты. Длительность действия, ослабляющего Разелиха Осквернителя и его приспешников, может быть различной. Именно поэтому следует высвобождать силу Проклятия Скверны лишь в нужный момент!$B$BТеперь дай мне время на создания оружия для тебя, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подождите, пока Гальван закончит отковывать оружие.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гальван вытирает пот со лба..>$B$BНикогда еще не существовало более подходящего оружия для убиения демона, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если вмешиваться в процесс, то оружие может получиться с изъяном. Терпение, $N.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Оружие выковано.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гальвану Древнему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3626,'Возвращение в Выжженные земли','Час возмездия близок, $n. Тебе следует вернуться в Выжженные земли вместе с твоим новообретенным оружием и поговорить с Павшим героем Орды о том, как достичь твоей главной цели.','Вернитесь к Павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.','Похоже, сражения закалили тебя, $N. Но достаточно ли в тебе силы и решимости, чтобы противостоять Разелиху и его приспешникам?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Выжженные земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Час возмездия близок, $n. Тебе следует вернуться в Выжженные земли вместе с твоим новообретенным оружием и поговорить с Павшим героем Орды о том, как достичь твоей главной цели.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, сражения закалили тебя, $N. Но достаточно ли в тебе силы и решимости, чтобы противостоять Разелиху и его приспешникам?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3627,'Воссоединить расколотый амулет','Чтобы добраться до Осквернителя, тебе следует сначала уничтожить троицу силы и собрать осколки амулета. Когда у тебя в руках будут все три осколка, возвращайся ко мне, и я скажу, что делать дальше.$B$BИди, $n! В Выжженные земли! Севина, Аллистарий и Грол должны погибнуть!','Убейте Грола Разрушителя, леди Севину и верховного мага Аллистария. С их трупов заберите Амулет Грола, Амулет Севины и Амулет Аллистария.$B$BПомните о том, что нужно использовать зачарованное азшаритовое оружие, отравленное Скверной, чтобы ослабить троицу! Их нельзя убить иначе – но используйте оружие разумно...','Амулет Разелиха Осквернителя наконец-то собран воедино. Но Разелих чует, что цепь его власти порвана. Он знает, что ты собираешься убить его...','Три должны образовать один, один должен осветить путь.','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воссоединить расколотый амулет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы добраться до Осквернителя, тебе следует сначала уничтожить троицу силы и собрать осколки амулета. Когда у тебя в руках будут все три осколка, возвращайся ко мне, и я скажу, что делать дальше.$B$BИди, $n! В Выжженные земли! Севина, Аллистарий и Грол должны погибнуть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Грола Разрушителя, леди Севину и верховного мага Аллистария. С их трупов заберите Амулет Грола, Амулет Севины и Амулет Аллистария.$B$BПомните о том, что нужно использовать зачарованное азшаритовое оружие, отравленное Скверной, чтобы ослабить троицу! Их нельзя убить иначе – но используйте оружие разумно...',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Амулет Разелиха Осквернителя наконец-то собран воедино. Но Разелих чует, что цепь его власти порвана. Он знает, что ты собираешься убить его...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Три должны образовать один, один должен осветить путь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3628,'Демон, имя тебе Рах\'лих','Логово Разелиха находится на вершине самой высокой горы Выжженных земель. Единственный способ достигнуть логова – это использовать телепортирующие руны поблизости от горы. Пока у тебя есть этот амулет, ты свободно можешь переместиться в логово. А достигнув логова, призови зверя. Ключ к этому – твой амулет, $n. Используй его на Алтаре Осквернителя.$B$BЕсли одолеешь Осквернителя, принеси его рог. Он станет символом надежды для всех, кто увидит его – доказательством того, что в этом раздираемом войнами мире еще есть герои!','Уничтожьте Разелиха Осквернителя и вернитесь к Павшему герою Орды с Отрубленным Рогом Осквернителя. Вам также понадобится вернуть Оберег Осквернителя, чтобы Павший герой мог уничтожить его, дабы оберег не попал к тому, кто использует его во зло.','Сегодняшний день останется в памяти навеки. Демонический повелитель Выжженных земель наконец-то пал!','Больше нечего бояться.','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демон, имя тебе Рах\'лих',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Логово Разелиха находится на вершине самой высокой горы Выжженных земель. Единственный способ достигнуть логова – это использовать телепортирующие руны поблизости от горы. Пока у тебя есть этот амулет, ты свободно можешь переместиться в логово. А достигнув логова, призови зверя. Ключ к этому – твой амулет, $n. Используй его на Алтаре Осквернителя.$B$BЕсли одолеешь Осквернителя, принеси его рог. Он станет символом надежды для всех, кто увидит его – доказательством того, что в этом раздираемом войнами мире еще есть герои!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Разелиха Осквернителя и вернитесь к Павшему герою Орды с Отрубленным Рогом Осквернителя. Вам также понадобится вернуть Оберег Осквернителя, чтобы Павший герой мог уничтожить его, дабы оберег не попал к тому, кто использует его во зло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодняшний день останется в памяти навеки. Демонический повелитель Выжженных земель наконец-то пал!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Больше нечего бояться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3629,'Гоблинское инженерное дело','В инженерном деле есть две дисциплины: гномская и гоблинская. Я – честный учитель, и только поэтому упомянул гоблинское инженерное дело. Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер.$b$b$n, почитай этот справочник. Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск. Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого.','Если вы хотите узнать больше о гоблинском инженерном деле, отнесите справочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.','Хорошо, $N, ты $Gвыбрал:выбрала; правильный путь. Не смотри на похвальбу гномов, разве они умеют обращаться с взрывчатыми веществами... в их зараженном радиацией городе Гномрегане так уже не думают, хе-хе-хе... Я покажу тебе, что такое настоящая гоблинская инженерия.$B$BДержи свои глаза широко открытыми, $N, и учись.','Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинское инженерное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В инженерном деле есть две дисциплины: гномская и гоблинская. Я – честный учитель, и только поэтому упомянул гоблинское инженерное дело. Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер.$b$b$n, почитай этот справочник. Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск. Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите узнать больше о гоблинском инженерном деле, отнесите справочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, $N, ты $Gвыбрал:выбрала; правильный путь. Не смотри на похвальбу гномов, разве они умеют обращаться с взрывчатыми веществами... в их зараженном радиацией городе Гномрегане так уже не думают, хе-хе-хе... Я покажу тебе, что такое настоящая гоблинская инженерия.$B$BДержи свои глаза широко открытыми, $N, и учись.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (3630,'Гномское инженерное дело','В инженерном деле есть две дисциплины: гномская и гоблинская. Гномское инженерное дело пока что зарекомендовала себя лучшей из двух. В ней речь идет о конструировании чудесных штучек и приспособлений, которые украшают жизнь!$B$B$n, почитай этот справочник. Если ты захочешь больше узнать о гномском инженерном деле, то отнеси его мехмастеру Замыкальцу в Стальгорн. Помни – выбор твой не подлежит пересмотру, и изучить другую дисциплину ты не сможешь, так что удостоверься в своем выборе, прежде чем выполнять его задание!','Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн.','Да-да, чем я могу сегодня тебе помочь? Конечно же, я могу отвлечься на это, ведь я целый день стою здесь, пока наш любимый город лежит в обломках, заполненный радикоактивными газами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гномское инженерное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В инженерном деле есть две дисциплины: гномская и гоблинская. Гномское инженерное дело пока что зарекомендовала себя лучшей из двух. В ней речь идет о конструировании чудесных штучек и приспособлений, которые украшают жизнь!$B$B$n, почитай этот справочник. Если ты захочешь больше узнать о гномском инженерном деле, то отнеси его мехмастеру Замыкальцу в Стальгорн. Помни – выбор твой не подлежит пересмотру, и изучить другую дисциплину ты не сможешь, так что удостоверься в своем выборе, прежде чем выполнять его задание!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да-да, чем я могу сегодня тебе помочь? Конечно же, я могу отвлечься на это, ведь я целый день стою здесь, пока наш любимый город лежит в обломках, заполненный радикоактивными газами.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3631,'Призыв коня Скверны','Хммм. Я сказал бы, что ты еще $Gне готов:не готова;, но тут не мне решать. Страад думает иначе, а решает он... пока.$B$BОн хочет с тобой говорить, причем срочно. Он пока все еще в Степях над Кабестаном, в своей маленькой башне со своими учениками.$B$BДолго не тяни.','Поговорите в Кабестане со Страхадом Фарсаном.','Значит, ты снова $Gрешил:решила; пожаловать меня своим визитом. Очень мило с твоей стороны.$B$BМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв коня Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хммм. Я сказал бы, что ты еще $Gне готов:не готова;, но тут не мне решать. Страад думает иначе, а решает он... пока.$B$BОн хочет с тобой говорить, причем срочно. Он пока все еще в Степях над Кабестаном, в своей маленькой башне со своими учениками.$B$BДолго не тяни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Кабестане со Страхадом Фарсаном.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты снова $Gрешил:решила; пожаловать меня своим визитом. Очень мило с твоей стороны.$B$BМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3632,'Гномское инженерное дело','На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Гномская намного сильнее! Она занимается конструированием чудесных штучек и устройств, которые делают лучше нашу жизнь!$B$B$n, прочтите эту инструкцию. Если вы желаете узнать побольше о гномском инженерном деле, отнесите этот справочник мехмастеру Замыкальцу – он здесь, в Стальгорне. Помните: если выберете гномское инженерное дело, то это с концами, другим направлением вы заниматься не сможете, так что подумайте хорошенько, прежде чем выполнить его поручение!','Возьмите Справочник по инженерным дисциплинам и отнесите его мехмастеру Замыкальцу в Стальгорн.','А, юный инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!','Да-да, чем я могу сегодня тебе помочь? Конечно же, я могу отвлечься на это, ведь я целый день стою здесь, пока наш любимый город лежит в обломках, заполненный радикоактивными газами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гномское инженерное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Гномская намного сильнее! Она занимается конструированием чудесных штучек и устройств, которые делают лучше нашу жизнь!$B$B$n, прочтите эту инструкцию. Если вы желаете узнать побольше о гномском инженерном деле, отнесите этот справочник мехмастеру Замыкальцу – он здесь, в Стальгорне. Помните: если выберете гномское инженерное дело, то это с концами, другим направлением вы заниматься не сможете, так что подумайте хорошенько, прежде чем выполнить его поручение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите Справочник по инженерным дисциплинам и отнесите его мехмастеру Замыкальцу в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, юный инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да-да, чем я могу сегодня тебе помочь? Конечно же, я могу отвлечься на это, ведь я целый день стою здесь, пока наш любимый город лежит в обломках, заполненный радикоактивными газами.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3633,'Гоблинское инженерное дело','Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов!$B$BПрочитай этот учебник, $n. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса.','Если вы хотите узнать о гоблинском инженерном деле, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск, что в Танарисе.','Что же, $N, ты $Gнашел:нашла; подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (ключевое слово – ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела.$B$BДержи ушки на макушке, $N, и чему-нибудь научишься.','Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинское инженерное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Инженерам-умельцам приходится выбирать между двумя школами инженерного дела: гномской и гоблинской. Очевидно, что наиболее талантливые инженеры предпочитают гоблинскую. Покори же мир с помощью отборной взрывчатки и фантастических механизмов!$B$BПрочитай этот учебник, $n. Если ты хочешь поучиться гоблинскому инженерному делу, поговори с Никсом Шепружином в Прибамбасске. Помни: сделав выбор единожды, ты не сможешь передумать. Поэтому хорошо подумай, прежде чем браться за задание Никса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите узнать о гоблинском инженерном деле, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск, что в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что же, $N, ты $Gнашел:нашла; подходящего учителя! Любой болван может освоить основы инженерного дела – как доказали гномы и их радиоактивный Гномреган. Требуется острый ум и верная рука (ключевое слово – ВЕРНАЯ), чтобы освоить премудрости гоблинского инженерного дела.$B$BДержи ушки на макушке, $N, и чему-нибудь научишься.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3634,'Гномское инженерное дело','На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.$B$B$n, прочти эту инструкцию. Если ты желаешь узнать побольше о гномском инженерном деле, отнеси этот справочник мехмастеру Замыкальцу в Стальгорн. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься другим направлением, так что подумай хорошенько, прежде чем выполнить поручение Замыкальца!','Если хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите мехмастеру Замыкальцу в Стальгорн.','А, юный инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!','Да-да, чем я могу сегодня тебе помочь? Конечно же, я могу отвлечься на это, ведь я целый день стою здесь, пока наш любимый город лежит в обломках, заполненный радикоактивными газами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гномское инженерное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.$B$B$n, прочти эту инструкцию. Если ты желаешь узнать побольше о гномском инженерном деле, отнеси этот справочник мехмастеру Замыкальцу в Стальгорн. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься другим направлением, так что подумай хорошенько, прежде чем выполнить поручение Замыкальца!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите мехмастеру Замыкальцу в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, юный инженер желает изучать единственное истинное направление в инженерном деле! Простите мне мою горячность, любезный друг. В нашем горестном положении всегда очень радостно встретить инженера, отозвавшегося на чистый зов истинного искусства!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да-да, чем я могу сегодня тебе помочь? Конечно же, я могу отвлечься на это, ведь я целый день стою здесь, пока наш любимый город лежит в обломках, заполненный радикоактивными газами.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3635,'Гномское инженерное дело','На высоких уровнях инженерное дело расходится на два направления: гномскую и гоблинскую. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Гномы занимаются конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.$B$B$n, прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую Бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько, прежде чем выполнить поручение Карлса!','Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту.','Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решетку.$B$BМы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способный ученик, я обучу тебя всему, что знаю.','Эй, ты! Если собираешься жаловаться, что мой автономный робот пробил стену твоего дома, можешь сразу обращаться к адвокату. Или ты по другому поводу?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гномское инженерное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На высоких уровнях инженерное дело расходится на два направления: гномскую и гоблинскую. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Гномы занимаются конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.$B$B$n, прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую Бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько, прежде чем выполнить поручение Карлса!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решетку.$B$BМы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способный ученик, я обучу тебя всему, что знаю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эй, ты! Если собираешься жаловаться, что мой автономный робот пробил стену твоего дома, можешь сразу обращаться к адвокату. Или ты по другому поводу?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3636,'Нести свет','Плеть постоянно досаждает силам Альянса. Думаю, $n, ты знаешь об этом не хуже меня. В последнее время нам удалось сделать пару интересных находок.$B$BВ Степях есть жуткие заросли терновника, называемые Курганы Иглошкурых. Сначала казалось, что там обитают только иглогривы, но теперь выясняется, что в этих зарослях гнездятся самые разнообразные чудовища. Управляет ими лич по имени Амненнар Хладовей.$B$BВо имя Света, $n! Изгони зло с холмов Иглошкурых!','Убейте Амненнара Хладовея в Курганах Иглошкурых.','Спасибо, $n. Теперь Плеть подумает дважды, прежде чем выпускать на нас своих гадов.$B$BДа хранит тебя Свет!','Спасибо, $N. Теперь Плеть подумает дважды, прежде чем выпускать на нас своих гадов.$B$BДа хранит тебя Свет!','Вернитесь к архиепископу Бенедикту в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нести свет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Плеть постоянно досаждает силам Альянса. Думаю, $n, ты знаешь об этом не хуже меня. В последнее время нам удалось сделать пару интересных находок.$B$BВ Степях есть жуткие заросли терновника, называемые Курганы Иглошкурых. Сначала казалось, что там обитают только иглогривы, но теперь выясняется, что в этих зарослях гнездятся самые разнообразные чудовища. Управляет ими лич по имени Амненнар Хладовей.$B$BВо имя Света, $n! Изгони зло с холмов Иглошкурых!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Амненнара Хладовея в Курганах Иглошкурых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $n. Теперь Плеть подумает дважды, прежде чем выпускать на нас своих гадов.$B$BДа хранит тебя Свет!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Спасибо, $N. Теперь Плеть подумает дважды, прежде чем выпускать на нас своих гадов.$B$BДа хранит тебя Свет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к архиепископу Бенедикту в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3637,'Гномское инженерное дело','На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.$B$B$n, прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую Бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько прежде, чем выполнить поручение Карлса!','Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту.','Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решетку.$B$BМы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способный ученик, я обучу тебя всему, что знаю.','Эй, ты! Если собираешься жаловаться, что мой автономный робот пробил стену твоего дома, можешь сразу обращаться к адвокату. Или ты по другому поводу?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гномское инженерное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На высоких уровнях инженерное дело расходится на два направления: на гномское и гоблинское. Хотя, на мой взгляд, это пустая трата времени, я должен рассказать тебе о гномском инженерном деле. Она занимается конструированием разных штучек и устройств, которые должны изменить мир, но редко работают.$B$B$n, прочти этот учебник. Если ты хочешь научиться делать металлические пресс-папье, отнеси его Карлсу Пропеллерзу в Пиратскую Бухту. Помни: выбрав гномское инженерное дело, ты не сможешь заниматься инженерным делом другой школы, так что подумай хорошенько прежде, чем выполнить поручение Карлса!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, тебе захотелось поучиться гномскому инженерному делу? Что ж, я очень подходящий гном. Хотя гномреганская правящая клика пытается преследовать тех, кто, по их мнению, слишком умный, знания нельзя посадить за решетку.$B$BМы с ними отлично понимаем, что после того, как я покинул Гномреган, они лишились одного из величайших гномов-инженеров наших дней. Если ты – способный ученик, я обучу тебя всему, что знаю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эй, ты! Если собираешься жаловаться, что мой автономный робот пробил стену твоего дома, можешь сразу обращаться к адвокату. Или ты по другому поводу?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3638,'Договор о неразглашении','Гоблинское инженерное дело нацелено на получение высоких прибылей и огромной взрывной силы! Наши чертежи позволяют нам создавать мощные бомбы и прочее оружие, и в справочнике, что у тебя в руках, об этом написано.$B$BНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только ты займешься гоблинским инженерным делом, то все. Доступа к гномскому инженерному делу не будет.$B$BЕсли ты по-прежнему хочешь заняться гоблинским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне. Но сначала подумай хорошенько.','Если вы согласны заниматься гоблинским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Никсу Шепружину в Прибамбасске.','Вернитесь к Никсу Шепружину в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Договор о неразглашении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гоблинское инженерное дело нацелено на получение высоких прибылей и огромной взрывной силы! Наши чертежи позволяют нам создавать мощные бомбы и прочее оружие, и в справочнике, что у тебя в руках, об этом написано.$B$BНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только ты займешься гоблинским инженерным делом, то все. Доступа к гномскому инженерному делу не будет.$B$BЕсли ты по-прежнему хочешь заняться гоблинским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне. Но сначала подумай хорошенько.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы согласны заниматься гоблинским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Никсу Шепружину в Прибамбасске.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Никсу Шепружину в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3639,'Покажи свою работу','Блеск в твоих глазах выдает тебя с головой – ты любишь взрывать! Ты опытный инженер, тут вопросов нет, $n. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гоблинскоориентированную технику для будущих трудов. Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек твердого динамита и пять взрывоопасных овец – и смотри $gсам:сама; не подорвись!$B$BСдай мне эти предметы, и я признаю тебя истинным гоблином-инженером!','Принесите 20 больших железных бомб, 20 шашек твердого динамита и 5 взрывоопасных овец Никсу Шепружину в Прибамбасск.','Вернитесь к Никсу Шепружину в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покажи свою работу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Блеск в твоих глазах выдает тебя с головой – ты любишь взрывать! Ты опытный инженер, тут вопросов нет, $n. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гоблинскоориентированную технику для будущих трудов. Мне нужны следующие образцы: двадцать больших железных бомб, двадцать шашек твердого динамита и пять взрывоопасных овец – и смотри $gсам:сама; не подорвись!$B$BСдай мне эти предметы, и я признаю тебя истинным гоблином-инженером!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 больших железных бомб, 20 шашек твердого динамита и 5 взрывоопасных овец Никсу Шепружину в Прибамбасск.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Никсу Шепружину в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3640,'Договор о неразглашении','Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у вас в руках, об этом написано.$B$BНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только вы займетесь гномским инженерным делом, то все. Доступа к гоблинскому инженерному делу не будет.$B$BЕсли вы по-прежнему хотите заняться гномским инженерным делом, подпишите этот документ о пожизненном неразглашении тайн и снова обратитесь ко мне. Хорошенько подумайте, $n.','Щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к мехмастеру Замыкальцу в Стальгорне.','Добро пожаловать в клуб, $N! Скоро вы получите доступ к наиболее передовым разработкам во всем Азероте.$B$BТеперь, когда вы посвятили себя этому искусству, пора испытать ваши навыки гномского инженерного дела. С этого мгновения мы будем помогать вам разрабатывать план предельного раскрытия ваших талантов гномского инженера!','Если вы подписали документ и готовы отдать его мне, тогда вот что я вам скажу.$B$BТайны, которые я вам доверю, настолько важны, что подписание Договора о неразглашении просто жизненно необходимо. Я сам такой подписывал, как и мои брат и сестра. Вы попадете в очень приятную компанию, инженер $N!','Вернитесь к Мехмастеру Замыкальцу в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Договор о неразглашении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у вас в руках, об этом написано.$B$BНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только вы займетесь гномским инженерным делом, то все. Доступа к гоблинскому инженерному делу не будет.$B$BЕсли вы по-прежнему хотите заняться гномским инженерным делом, подпишите этот документ о пожизненном неразглашении тайн и снова обратитесь ко мне. Хорошенько подумайте, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к мехмастеру Замыкальцу в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в клуб, $N! Скоро вы получите доступ к наиболее передовым разработкам во всем Азероте.$B$BТеперь, когда вы посвятили себя этому искусству, пора испытать ваши навыки гномского инженерного дела. С этого мгновения мы будем помогать вам разрабатывать план предельного раскрытия ваших талантов гномского инженера!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если вы подписали документ и готовы отдать его мне, тогда вот что я вам скажу.$B$BТайны, которые я вам доверю, настолько важны, что подписание Договора о неразглашении просто жизненно необходимо. Я сам такой подписывал, как и мои брат и сестра. Вы попадете в очень приятную компанию, инженер $N!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мехмастеру Замыкальцу в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3641,'Покажи свою работу','Если ты $gготов:готова; приступить к изготовлению потрясающих изделий – то ты $gобратился:обратилась; по адресу! Ты опытный инженер, тут вопросов нет, $n. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.$B$BСдай мне эти предметы, и я признаю тебя истинным гномом-инженером.','Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени мехмастеру Замыкальцу в Стальгорн.','Вот ваш первый ччленский билет гильдии гномов-инженеров!$B$BБилет оплачивается вперед за четырнадцать дней. Через две недели срок действия истечет. Когда это произойдет, вы заплатите очередную пошлину любому наставнику гномской инженери и получите продление. Без билета ваше членство будет временно приостановлено, и вы не будете иметь доступа к новым чертежам.$B$BЭто никак не повлияет на уже обретенные вами знания: если уж стал гномским инженером, то это навсегда.','Как только я получу на рассмотрение ваши искусные инженерные изделия, я выдам вам настоящий членский билет гильдии гномов-инженеров! Пока он будет действителен, вы будете иметь неограниченный допуск к любому наставнику по гномскому инженерному делу в мире.','Вернитесь к Мехмастеру Замыкальцу в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покажи свою работу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты $gготов:готова; приступить к изготовлению потрясающих изделий – то ты $gобратился:обратилась; по адресу! Ты опытный инженер, тут вопросов нет, $n. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.$B$BСдай мне эти предметы, и я признаю тебя истинным гномом-инженером.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени мехмастеру Замыкальцу в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот ваш первый ччленский билет гильдии гномов-инженеров!$B$BБилет оплачивается вперед за четырнадцать дней. Через две недели срок действия истечет. Когда это произойдет, вы заплатите очередную пошлину любому наставнику гномской инженери и получите продление. Без билета ваше членство будет временно приостановлено, и вы не будете иметь доступа к новым чертежам.$B$BЭто никак не повлияет на уже обретенные вами знания: если уж стал гномским инженером, то это навсегда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как только я получу на рассмотрение ваши искусные инженерные изделия, я выдам вам настоящий членский билет гильдии гномов-инженеров! Пока он будет действителен, вы будете иметь неограниченный допуск к любому наставнику по гномскому инженерному делу в мире.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мехмастеру Замыкальцу в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3642,'Договор о неразглашении','Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у тебя в руках, об этом написано.$B$BНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только ты займешься гномским инженерным делом, то все. Доступа к гоблинскому инженерному делу не будет.$B$BЕсли ты по-прежнему хочешь заняться гномским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне. Но сначала подумай хорошенько.','Если вы согласны заниматься гномским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Карлсу Пропеллерзу в Пиратской Бухте.','Добро пожаловать в клуб, $N! Скоро вы получите доступ к наиболее передовым разработкам во всем Азероте.$B$BТеперь, когда вы посвятили себя этому искусству, пора испытать ваши навыки гномского инженерного дела. С этого мгновения мы будем помогать вам разрабатывать план предельного раскрытия ваших талантов гномского инженера!','Если ты подписал документ и готов отдать его мне, тогда вот что я скажу.$B$BХотя я не согласен с политикой Гномрегана – и особенно этого глупца, мехмастера Замыкальца – с политической точки зрения, документ о неразглашении превыше всего! Ты должен избрать свой путь и следовать им всю свою жизнь.','Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Договор о неразглашении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гномское инженерное дело стоит на пороге открытия теории, которая послужит нашим нуждам! Наши чертежи позволяют нам сооружать устройства, контролирующие мир вокруг нас, и в справочнике, что у тебя в руках, об этом написано.$B$BНо этот справочник также содержит древнюю клятву хранить наши чертежи в тайне. Как только ты займешься гномским инженерным делом, то все. Доступа к гоблинскому инженерному делу не будет.$B$BЕсли ты по-прежнему хочешь заняться гномским инженерным делом, подпиши этот документ о пожизненном неразглашении тайн и снова обращайся ко мне. Но сначала подумай хорошенько.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы согласны заниматься гномским инженерным делом, щелкните правой кнопкой мыши по Договору о неразглашении и еще раз обратитесь к Карлсу Пропеллерзу в Пиратской Бухте.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в клуб, $N! Скоро вы получите доступ к наиболее передовым разработкам во всем Азероте.$B$BТеперь, когда вы посвятили себя этому искусству, пора испытать ваши навыки гномского инженерного дела. С этого мгновения мы будем помогать вам разрабатывать план предельного раскрытия ваших талантов гномского инженера!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты подписал документ и готов отдать его мне, тогда вот что я скажу.$B$BХотя я не согласен с политикой Гномрегана – и особенно этого глупца, мехмастера Замыкальца – с политической точки зрения, документ о неразглашении превыше всего! Ты должен избрать свой путь и следовать им всю свою жизнь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3643,'Покажи свою работу','Если ты $gготов:готова; приступить к изготовлению потрясающих изделий – то ты $gобратился:обратилась; по адресу! Ты опытный инженер, тут вопросов нет, $n. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.$B$BСдай мне эти предметы, и я признаю тебя истинным гномом-инженером.','Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени Карлсу Пропеллерзу в Пиратскую Бухту.','Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покажи свою работу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты $gготов:готова; приступить к изготовлению потрясающих изделий – то ты $gобратился:обратилась; по адресу! Ты опытный инженер, тут вопросов нет, $n. Но я надеюсь проанализировать твои работы, чтобы найти способ отточить гномскоориентированную технику ваших будущих трудов. Мне нужны следующие образцы: шесть мифриловых трубок, точный прицел и два усовершенствованных манекена-мишени.$B$BСдай мне эти предметы, и я признаю тебя истинным гномом-инженером.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 мифриловых трубок, точный прицел и 2 усовершенствованных манекена-мишени Карлсу Пропеллерзу в Пиратскую Бухту.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлсу Пропеллерзу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3644,'Продление членского билета','Поскольку ты занимаешься гоблинским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гоблинским чертежам соотвествующих наставников.$B$BБилет будет действителен две недели, по истечении которых придется снова заплатить.','Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Продление членского билета',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поскольку ты занимаешься гоблинским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гоблинским чертежам соотвествующих наставников.$B$BБилет будет действителен две недели, по истечении которых придется снова заплатить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3645,'Продление членского билета','Поскольку ты занимаешься гномским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гномским чертежам соотвествующих наставников.$B$BБилет будет действителен две недели, по истечении которых придется снова заплатить.','Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Продление членского билета',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поскольку ты занимаешься гномским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гномским чертежам соотвествующих наставников.$B$BБилет будет действителен две недели, по истечении которых придется снова заплатить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3646,'Продление членского билета','Поскольку ты занимаешься гоблинским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гоблинским чертежам соответствующих наставников.$B$BБилет будет действителен две недели, по истечении которых придется снова заплатить! Если ты хочешь иметь доступ к чертежам, не просрочивай платежи.','Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Продление членского билета',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поскольку ты занимаешься гоблинским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гоблинским чертежам соответствующих наставников.$B$BБилет будет действителен две недели, по истечении которых придется снова заплатить! Если ты хочешь иметь доступ к чертежам, не просрочивай платежи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3647,'Продление членского билета','Поскольку ты занимаешься гномским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гномским чертежам соотвествующих наставников.$B$BБилет будет действителен две недели, по истечении которых придется снова заплатить.','Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Продление членского билета',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поскольку ты занимаешься гномским инженерным делом и у всех на хорошем счету, то я могу восстановить просроченный членский билет за два золотых. Как только ты заплатишь пошлину, то немедленно получишь новый членский билет. Это даст тебе доступ к гномским чертежам соотвествующих наставников.$B$BБилет будет действителен две недели, по истечении которых придется снова заплатить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы продлить членский билет, тебе придется заплатить пошлину в размере двух золотых.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3661,'Любимцы Элуны?','Дикие совухи – очень непредсказуемые существа, $n. Они могут быть мягкими и пушистыми, но если что-то дорогое для них окажется под угрозой, в них проснется настоящий зверь!$B$BГоворят, что этих животных создала сама Элуна, и я хочу узнать, правда это, или нет.$B$BМного диких совухов обитает во Внутренних землях – целые популяции примитивных, злобных и диких совухов. Не хотите ли отправиться туда и принести мне их перьев?','Соберите во Внутренних землях 15 перьев диких совухов и отнесите их Эреласу Янтарному Небу в деревню Рут\'теран.','Вернитесь к Эреласу Янтарному Небу в деревню Рут\'теран, что в Тельдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любимцы Элуны?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дикие совухи – очень непредсказуемые существа, $n. Они могут быть мягкими и пушистыми, но если что-то дорогое для них окажется под угрозой, в них проснется настоящий зверь!$B$BГоворят, что этих животных создала сама Элуна, и я хочу узнать, правда это, или нет.$B$BМного диких совухов обитает во Внутренних землях – целые популяции примитивных, злобных и диких совухов. Не хотите ли отправиться туда и принести мне их перьев?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите во Внутренних землях 15 перьев диких совухов и отнесите их Эреласу Янтарному Небу в деревню Рут\'теран.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эреласу Янтарному Небу в деревню Рут\'теран, что в Тельдрассиле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3681,'Фолиант Божественности','Я вынужден прервать твое путешествие, |3-6($r). Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения.$B$BЕсли бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов.$B$BНайди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света.','Разыщите в Штормграде Даториана Ралла и поговорите с ним.','Добро пожаловать в Собор Света, |3-6($C).') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант Божественности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вынужден прервать твое путешествие, |3-6($r). Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения.$B$BЕсли бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов.$B$BНайди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите в Штормграде Даториана Ралла и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Собор Света, |3-6($C).',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3701,'Дымящиеся руины Тауриссана','Отправляйтесь в дымящиеся руины Тауриссана в Пылающих степях и соберите как можно больше информации.$B$BГоворят, все руины просто усыпаны таинственными реликвиями. Возможно, вам надо начать поиски здесь, $n. Опасайтесь таурисанских стражей-убийц, что стерегут руины, охраняя все тайны, какие там могут быть.','Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессон.','Ох ты! Эта информация многое объясняет касательно Тауриссана.$B$BНо предстоит узнать еще больше!','Ты $Gдобыл:добыла; новую информацию?','Вернитесь к королевскому историку Аркессон к Высокому трону, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дымящиеся руины Тауриссана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отправляйтесь в дымящиеся руины Тауриссана в Пылающих степях и соберите как можно больше информации.$B$BГоворят, все руины просто усыпаны таинственными реликвиями. Возможно, вам надо начать поиски здесь, $n. Опасайтесь таурисанских стражей-убийц, что стерегут руины, охраняя все тайны, какие там могут быть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пойдите в руины Тауриссана в Пылающих степях и добудьте информацию из таурисанских реликвий. Вернитесь к королевскому историку Аркессон.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох ты! Эта информация многое объясняет касательно Тауриссана.$B$BНо предстоит узнать еще больше!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдобыл:добыла; новую информацию?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королевскому историку Аркессон к Высокому трону, что в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (3702,'Дымящиеся руины Тауриссана','Не желаете ли услышать краткий обзор истории дворфов Черного Железа?','Узнайте от королевского историка Аркессон историю Тауриссана.','Продолжим?','Позвольте мне закончить рассказ об истории Тауриссана.','Выслушайте историю о Тауриссане.','Вернитесь к королевскому историку Аркессон в Дун Морог.','Выслушайте историю о Тауриссане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дымящиеся руины Тауриссана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не желаете ли услышать краткий обзор истории дворфов Черного Железа?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте от королевского историка Аркессон историю Тауриссана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Продолжим?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Позвольте мне закончить рассказ об истории Тауриссана.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Выслушайте историю о Тауриссане.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королевскому историку Аркессон в Дун Морог.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Выслушайте историю о Тауриссане.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (3721,'Тебе удалось выручить всех трех моих роботов серии ООХ! Ты $Gсделал:сделала; все, что требовалось и даже больше, поэтому я хочу особым образом отблагодарить тебя за помощь. Это миниатюрная версия того же робота, с которым ты $Gпровел:провела; так много времени и $Gполюбил:полюбила;, ООХ!$B$BОбычно я никому не дарю такие опасные устройства, но ты $Gоказал:оказала; мне неоценимую помощь. Кроме того у этой тварюшки отключены боевые механизмы и устройство самонаведения.$B$BА в остальном это полноценный ООХ!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось выручить всех трех моих роботов серии ООХ! Ты $Gсделал:сделала; все, что требовалось и даже больше, поэтому я хочу особым образом отблагодарить тебя за помощь. Это миниатюрная версия того же робота, с которым ты $Gпровел:провела; так много времени и $Gполюбил:полюбила;, ООХ!$B$BОбычно я никому не дарю такие опасные устройства, но ты $Gоказал:оказала; мне неоценимую помощь. Кроме того у этой тварюшки отключены боевые механизмы и устройство самонаведения.$B$BА в остальном это полноценный ООХ!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3741,'Ожерелье Хилари','Моя подруга Хилари потеряла ожелелье, и мы никак не можем отыскать его. Мы весь день сидели на одном и том же месте, удили рыбу, и уже все кругом обыскали. Наверное, оно упало в воду. Родители не разрешают нам плавать в озере... Мама говорит, что под водой водятся чудовища, но вы ведь их не боитесь, правда?$B$BПожалуйста, достаньте нам ожерелье.','Найдите ожерелье Хилари и верните его Хилари в Приозерье.','Спасибо, что достали мне ожерелье, $Gгосподин:госпожа; |3-6($c)... Вы очень добры! Моя кошечка тоже хочет сказать "спасибо" – верно, Эфси?','Привет. Я очень переживаю из-за пропажи ожерелья. Ведь его мне папа привез! Кстати, он говорит, что в озере водятся чудовища. Вы уже их победили?','Вернитесь к Хилари в Приозерье, что в Красногорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье Хилари',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя подруга Хилари потеряла ожелелье, и мы никак не можем отыскать его. Мы весь день сидели на одном и том же месте, удили рыбу, и уже все кругом обыскали. Наверное, оно упало в воду. Родители не разрешают нам плавать в озере... Мама говорит, что под водой водятся чудовища, но вы ведь их не боитесь, правда?$B$BПожалуйста, достаньте нам ожерелье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ожерелье Хилари и верните его Хилари в Приозерье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что достали мне ожерелье, $Gгосподин:госпожа; |3-6($c)... Вы очень добры! Моя кошечка тоже хочет сказать "спасибо" – верно, Эфси?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет. Я очень переживаю из-за пропажи ожерелья. Ведь его мне папа привез! Кстати, он говорит, что в озере водятся чудовища. Вы уже их победили?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хилари в Приозерье, что в Красногорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3761,'Земля Ун\'Горо','Говорят, что почва из Кратера Ун\'Горо наделена мощными магическими свойствами. Кругу Кенария нужно много этой почвы для исследований. Ступай в страшные окрестности Ун\'Горо и добудь земли побольше.$B$BЭта богатая почва порой лежит большими грудами, а иногда ее находят у некоторых тварей. Относи землю к Геду – ищи кучки земли и таурена, раздающего команды. Он не злой, просто постарайся его не слишком донимать.','Принесите 20 образцов почвы из Кратера Ун\'Горо Геду на Вершину Старейшин Громового Утеса.','Ладно, $Gрядовой:рядовая; $N, и не пытайся помогать мне сваливать эту землю в кучу! Если бы Великие духи этого хотели, то прямо тут и устроили бы чудо, что, не так?!$B$BВерховный друид Рунический Тотем опять хочет с тобой говорить, но чтобы выполнить его очередное поручение, тебе нужно разбираться в травничестве на уровне подмастерья. Но если ты еще не $Gдоучился:доучилась;, он все равно тебе дельце подберет.','Вольно, рядовой. Если ты собираешься выгрузить землю из Ун\'Горо – то жди команды! Если нет – кругом и марш отсюда!','Вернитесь к Геду, находящемуся у колодца Буйногривых в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Земля Ун\'Горо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что почва из Кратера Ун\'Горо наделена мощными магическими свойствами. Кругу Кенария нужно много этой почвы для исследований. Ступай в страшные окрестности Ун\'Горо и добудь земли побольше.$B$BЭта богатая почва порой лежит большими грудами, а иногда ее находят у некоторых тварей. Относи землю к Геду – ищи кучки земли и таурена, раздающего команды. Он не злой, просто постарайся его не слишком донимать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 образцов почвы из Кратера Ун\'Горо Геду на Вершину Старейшин Громового Утеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ладно, $Gрядовой:рядовая; $N, и не пытайся помогать мне сваливать эту землю в кучу! Если бы Великие духи этого хотели, то прямо тут и устроили бы чудо, что, не так?!$B$BВерховный друид Рунический Тотем опять хочет с тобой говорить, но чтобы выполнить его очередное поручение, тебе нужно разбираться в травничестве на уровне подмастерья. Но если ты еще не $Gдоучился:доучилась;, он все равно тебе дельце подберет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вольно, рядовой. Если ты собираешься выгрузить землю из Ун\'Горо – то жди команды! Если нет – кругом и марш отсюда!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Геду, находящемуся у колодца Буйногривых в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3762,'Помощь верховному друиду Руническому Тотему','Извини, |3-6($c), можно тебя на минутку?$b$bКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.$b$bЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.','Поговорите с верховным друидом Хамуулом Руническим Тотемом в Громовом Утесе.','Привет тебе, |3-6($C). Я рад, что ты хочешь помочь нам в наших исследованиях. Сделать предстоит многое, и я дурно поступил бы, если бы сказал, что труды наши не сулят опасности. Надеюсь, это тебя не отпугнет... но, судя по твоему виду, тебе и прежде приходилось сталкиваться с опасностями.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь верховному друиду Руническому Тотему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Извини, |3-6($c), можно тебя на минутку?$b$bКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.$b$bЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным друидом Хамуулом Руническим Тотемом в Громовом Утесе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, |3-6($C). Я рад, что ты хочешь помочь нам в наших исследованиях. Сделать предстоит многое, и я дурно поступил бы, если бы сказал, что труды наши не сулят опасности. Надеюсь, это тебя не отпугнет... но, судя по твоему виду, тебе и прежде приходилось сталкиваться с опасностями.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3763,'Помощь верховному друиду Оленьему Шлему','Простите, |3-6($c), не уделите ли вы мне крупицу вашего времени?$B$BДарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит не кто иной, как сам верховный друид Фэндрал Олений Шлем.$B$BПрошу вас, если вам интересно, поговорите с ним лично в Анклаве Кенария в Дарнасе.','Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.','Что же, |3-6($C)... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.$B$BИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь верховному друиду Оленьему Шлему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Простите, |3-6($c), не уделите ли вы мне крупицу вашего времени?$B$BДарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит не кто иной, как сам верховный друид Фэндрал Олений Шлем.$B$BПрошу вас, если вам интересно, поговорите с ним лично в Анклаве Кенария в Дарнасе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что же, |3-6($C)... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.$B$BИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3764,'Земля Ун\'Горо','Говорят, что почва из Кратера Ун\'Горо наделена мощными магическими свойствами. Я хочу знать, насколько эти слухи преувеличены. Ступай в заросший Кратер Ун\'Горо и добудь хороших образцов земли для наших исследований.$B$BТебе может показаться, что это дело не достойно тебя, но такое поведение не завоюет тебе приязни ни с моей стороны, ни со стороны Круга Кенария. Принеси образцы земли Дженалю, который наверняка сидит без дела вон за тем деревом – ищи кучки земли, и найдешь его. Снабжением занимается он, не я.','Принесите 20 образцов почвы из Кратера Ун\'Горо Дженалю в дарнасский Анклав Кенария.','А, опять эта грязь. Верховный друид требует с каждого искателя приключений по двадцать кучек – двадцать кучек ему и будет. И пусть те, кто строит нам козни, топает по обочине!','Вернитесь к Дженалю в Анклав Кенария, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Земля Ун\'Горо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что почва из Кратера Ун\'Горо наделена мощными магическими свойствами. Я хочу знать, насколько эти слухи преувеличены. Ступай в заросший Кратер Ун\'Горо и добудь хороших образцов земли для наших исследований.$B$BТебе может показаться, что это дело не достойно тебя, но такое поведение не завоюет тебе приязни ни с моей стороны, ни со стороны Круга Кенария. Принеси образцы земли Дженалю, который наверняка сидит без дела вон за тем деревом – ищи кучки земли, и найдешь его. Снабжением занимается он, не я.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 образцов почвы из Кратера Ун\'Горо Дженалю в дарнасский Анклав Кенария.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, опять эта грязь. Верховный друид требует с каждого искателя приключений по двадцать кучек – двадцать кучек ему и будет. И пусть те, кто строит нам козни, топает по обочине!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дженалю в Анклав Кенария, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3765,'Проблема за морем','Штормград – невероятно суматошный город.$b$bЯ прибыл сюда издалека в поисках помощи. Говорят, отважные искатели приключений нередко бродят по этим улицам.$b$bМой брат Гершала на Темных берегах нуждается в помощи. Он обитает в приморском городке Аубердине.$b$bЭто путешествие будет долгим и насыщенным. Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, |3-6($c).','Отправляйтесь в Аубердин к Гершалу Шепоту Ночи.','О, вас прислал мой брат Аргос? Должно быть, вы устали от долгого пути. Но нам очень о многом нужно поговорить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблема за морем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Штормград – невероятно суматошный город.$b$bЯ прибыл сюда издалека в поисках помощи. Говорят, отважные искатели приключений нередко бродят по этим улицам.$b$bМой брат Гершала на Темных берегах нуждается в помощи. Он обитает в приморском городке Аубердине.$b$bЭто путешествие будет долгим и насыщенным. Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Аубердин к Гершалу Шепоту Ночи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, вас прислал мой брат Аргос? Должно быть, вы устали от долгого пути. Но нам очень о многом нужно поговорить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3781,'Изучение рассветницы','При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун\'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен разгадать его тайну.$B$BОтнеси это вниз, Матренгилу, и он даст тебе семена, чтобы ты $Gмог:могла; начать работу. Если все израсходуешь, тебе придется купить у него еще семян.','Отнесите расписку верховного друида в получении семян Матренгилу Медвежьей Лапе в дарнасский Анклав Кенария.','Да, расписка на двадцать пакетиков семян. Если все изведешь, еще достанем. Хотя производить семена Тарлендриса в большом количестве – дело, увы, недешевое. Потому Круг Кенария и просит помощи в частичном возмещении стоимости.$B$BТе, кто находит рассветницу и приносит нам, видит, что награда верховного друида с лихвой окупает труды.','Да пребудут с тобой мир и спокойствие. Как понимаю, ты с поручением от самого верховного друида?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение рассветницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун\'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен разгадать его тайну.$B$BОтнеси это вниз, Матренгилу, и он даст тебе семена, чтобы ты $Gмог:могла; начать работу. Если все израсходуешь, тебе придется купить у него еще семян.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите расписку верховного друида в получении семян Матренгилу Медвежьей Лапе в дарнасский Анклав Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, расписка на двадцать пакетиков семян. Если все изведешь, еще достанем. Хотя производить семена Тарлендриса в большом количестве – дело, увы, недешевое. Потому Круг Кенария и просит помощи в частичном возмещении стоимости.$B$BТе, кто находит рассветницу и приносит нам, видит, что награда верховного друида с лихвой окупает труды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да пребудут с тобой мир и спокойствие. Как понимаю, ты с поручением от самого верховного друида?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3782,'Изучение рассветницы','При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун\'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен раскрыть его тайну для Круга.$B$BОтнеси эту расписку моей дочери Башане Рунический Тотем, и она даст тебе семена, чтобы ты $Gмог:могла; начать работу. Если все израсходуешь, тебе придется купить у нее еще семян.','Отнесите расписку в получении семян Башане Руническому Тотему в Громовой Утес.','Да, расписка на двадцать пакетиков семян. Если все израсходуешь, у меня есть еще на продажу.$B$BУвы, $N, производить семена Тарлендриса в большом количестве дорого. Потому Круг Кенария и просит помощи в частичном возмещении стоимости.$B$BТе, кто находит рассветницу и приносит нам, видит, что награда верховного друида с лихвой окупает труды.','Да пребудут с тобой мир и спокойствие. Как понимаю, ты с поручением от самого верховного друида?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение рассветницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При помощи того, что мы называем сумой вечного цветения, мы посадили семена Тарлендриса в почву из Кратера Ун\'Горо. Из этих семян проросло множество редких полезных трав. И одна из них – рассветница, таинственное растение, о котором мы мало что знаем. Я намерен раскрыть его тайну для Круга.$B$BОтнеси эту расписку моей дочери Башане Рунический Тотем, и она даст тебе семена, чтобы ты $Gмог:могла; начать работу. Если все израсходуешь, тебе придется купить у нее еще семян.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите расписку в получении семян Башане Руническому Тотему в Громовой Утес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, расписка на двадцать пакетиков семян. Если все израсходуешь, у меня есть еще на продажу.$B$BУвы, $N, производить семена Тарлендриса в большом количестве дорого. Потому Круг Кенария и просит помощи в частичном возмещении стоимости.$B$BТе, кто находит рассветницу и приносит нам, видит, что награда верховного друида с лихвой окупает труды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да пребудут с тобой мир и спокойствие. Как понимаю, ты с поручением от самого верховного друида?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3783,'Йети где-то рядом...','У моих друзей всегда замечательные идеи. И я никогда не думала, что смогу сравниться с ними в оригинальности мышления... до сегодняшнего дня! У меня возник потрясающий план! Если обещаешь никому не говорить, я расскажу тебе его по секрету... $B$BЯ хочу сделать механического йети! Мои друзья с ума сойдут, когда увидят, что я смогла смастерить!$b$bДля начала мне понадобится толстый мех йети с холмов Ледополоха. Ты мне поможешь? Йети водятся к юго-востоку отсюда.','Соберите 10 толстых кусков меха йети для Уми Румпельшникер из Круговзора.','Вернитесь к Уми Румпельшникер в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Йети где-то рядом...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У моих друзей всегда замечательные идеи. И я никогда не думала, что смогу сравниться с ними в оригинальности мышления... до сегодняшнего дня! У меня возник потрясающий план! Если обещаешь никому не говорить, я расскажу тебе его по секрету... $B$BЯ хочу сделать механического йети! Мои друзья с ума сойдут, когда увидят, что я смогла смастерить!$b$bДля начала мне понадобится толстый мех йети с холмов Ледополоха. Ты мне поможешь? Йети водятся к юго-востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 толстых кусков меха йети для Уми Румпельшникер из Круговзора.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уми Румпельшникер в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3784,'Помощь верховному друиду Руническому Тотему','Извини, |3-6($c), можно тебя на минутку?$b$bКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.$b$bЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.','Поговорите с верховным друидом Хамуулом Руническим Тотемом на Уступе Древних Громового Утеса.','Приветствую, |3-6($C)! Я рад, что тебя заинтересовало наше исследование. Дел очень много, и я обманул бы тебя, сказав, что речь идет о безопасном задании. Надеюсь, тебя так просто не напугать... По твоему виду можно предположить, что тебе приходилось сталкиваться с опасностями.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь верховному друиду Руническому Тотему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Извини, |3-6($c), можно тебя на минутку?$b$bКругу Кенария в Громовом Утесе требуются такие закаленные путешественники, как ты, для участия в чрезвычайно важном исследовании. Подробностей я не знаю, но могу сказать, что возглавляет этот проект Хамуул Рунический Тотем.$b$bЕсли тебя это интересует, отправляйся в Громовый Утес на Вершину Старейшин и поговори с самим Хамуулом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным друидом Хамуулом Руническим Тотемом на Уступе Древних Громового Утеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую, |3-6($C)! Я рад, что тебя заинтересовало наше исследование. Дел очень много, и я обманул бы тебя, сказав, что речь идет о безопасном задании. Надеюсь, тебя так просто не напугать... По твоему виду можно предположить, что тебе приходилось сталкиваться с опасностями.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3785,'Изучение рассветницы','Это сума вечного цветения для семян Тарлендриса. Еще тебе понадобится почва из Кратера Ун\'Горо как удобрение для семян. Когда достанешь все, что надо, просто используй суму, она позаботится обо всем.$B$BКогда у тебя будет достаточно рассветницы, принеси ее мне сюда, в анклав. И не тревожь верховного друида: он эльф занятой, не стоит всякий раз отрывать его от дела!','При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций почвы Ун\'Горо попытайтесь прорастить рассветницу.$B$BПринесите 10 рассветниц Матренгилу Медвежьей Лапе в Дарнас.','Очень хорошо, $N, я непременно отнесу их лично верховному друиду, когда они ему понадобятся. А пока прими это в знак признательности от Круга Кенария.$B$BНам рассветница нужна всегда. Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить.','Ну что, $N, удалось вырастить рассветницу для архиважных исследований верховного друида? Его труды во благо Круга Кенария чрезвычайно важны, и твоя помощь будет весьма кстати!','Вернитесь к Матренгилу Медвежьей Лапе в Анклав Кенария, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение рассветницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это сума вечного цветения для семян Тарлендриса. Еще тебе понадобится почва из Кратера Ун\'Горо как удобрение для семян. Когда достанешь все, что надо, просто используй суму, она позаботится обо всем.$B$BКогда у тебя будет достаточно рассветницы, принеси ее мне сюда, в анклав. И не тревожь верховного друида: он эльф занятой, не стоит всякий раз отрывать его от дела!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций почвы Ун\'Горо попытайтесь прорастить рассветницу.$B$BПринесите 10 рассветниц Матренгилу Медвежьей Лапе в Дарнас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо, $N, я непременно отнесу их лично верховному друиду, когда они ему понадобятся. А пока прими это в знак признательности от Круга Кенария.$B$BНам рассветница нужна всегда. Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $N, удалось вырастить рассветницу для архиважных исследований верховного друида? Его труды во благо Круга Кенария чрезвычайно важны, и твоя помощь будет весьма кстати!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матренгилу Медвежьей Лапе в Анклав Кенария, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3786,'Изучение рассветницы','Вот сума вечного цветения для семян Тарлендриса. Еще тебе понадобится почва из Кратера Ун\'Горо как удобрение для семян. Когда достанешь все, что надо, просто используй суму, а уж она сама позаботится обо всем.$B$BКогда у тебя будет достаточно рассветницы, принеси ее мне сюда на Вершину Старейшин. И не утруждай верховного друида – он очень занят исследованиями, да и других забот у него полон рот.','При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций почвы Ун\'Горо попытайтесь прорастить рассветницу.$B$BПринесите 10 рассветниц Башане Руническому Тотему в Громовой Утес.','Очень хорошо, $N, я непременно отнесу их лично верховному друиду, когда они ему понадобятся. А пока прими это в знак признательности от Круга Кенария.$B$BНам рассветница нужна всегда. Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить.','Добро пожаловать $N. Ты $Gвырастил:вырастила; рассветницы для наиважнейших исследований верховного друида? С каждым днем таинственные свойства Кратера Ун\'Горо становятся все понятнее благодаря помощи таких, как ты!','Вернитесь к Башане Руническому Тотему в Золотые равнины, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение рассветницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот сума вечного цветения для семян Тарлендриса. Еще тебе понадобится почва из Кратера Ун\'Горо как удобрение для семян. Когда достанешь все, что надо, просто используй суму, а уж она сама позаботится обо всем.$B$BКогда у тебя будет достаточно рассветницы, принеси ее мне сюда на Вершину Старейшин. И не утруждай верховного друида – он очень занят исследованиями, да и других забот у него полон рот.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи сумы вечного цветения, пакетика семян Тарлендриса и двух порций почвы Ун\'Горо попытайтесь прорастить рассветницу.$B$BПринесите 10 рассветниц Башане Руническому Тотему в Громовой Утес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо, $N, я непременно отнесу их лично верховному друиду, когда они ему понадобятся. А пока прими это в знак признательности от Круга Кенария.$B$BНам рассветница нужна всегда. Если ты желаешь и дальше помогать нам, приноси любую рассветницу, какую сумеешь вырастить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать $N. Ты $Gвырастил:вырастила; рассветницы для наиважнейших исследований верховного друида? С каждым днем таинственные свойства Кратера Ун\'Горо становятся все понятнее благодаря помощи таких, как ты!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Башане Руническому Тотему в Золотые равнины, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3787,'Просьба друида','Простите, $Gдруг мой:уважаемая госпожа;...$b$bМой коллега хотел бы поговорить с вами касательно проводимых вами совместно с Кругом Кенария исследований. Он друид, зовут его Квинтис Ночной Костер, и живет он в Крепости Оперенной Луны в Фераласе. Он хотел бы посоветоваться с вами насчет рассветницы... и он очень хотел бы, чтобы этот разговор не дошел до ушей верховного друида.$b$bЕсли вы заинтересовались, поговорите с Кинтисом; не сомневайтесь, он расскажет вам все подробно.','Поговорите с Квинтисом Ночным Костром в Крепости Оперенной Луны.','Благодарю вас за ваш визит, $Gусталый:усталая; $Gпутник:путница;! Позвольте представиться: я – Квинтис Ночной Костер, друид и скромный слуга Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперенная Луна и Протекторат – вы, может быть, о нас слыхали) и я хотели бы поговорить с вами о той работе, которую вы проводите для Фэндрала Оленьего Шлема в Дарнассе.$B$BПрежде чем мы пойдем дальше, я хотел бы попросить вас, чтобы этот разговор остался строго между нами. Если вы с этим согласны, мы можем продолжать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба друида',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Простите, $Gдруг мой:уважаемая госпожа;...$b$bМой коллега хотел бы поговорить с вами касательно проводимых вами совместно с Кругом Кенария исследований. Он друид, зовут его Квинтис Ночной Костер, и живет он в Крепости Оперенной Луны в Фераласе. Он хотел бы посоветоваться с вами насчет рассветницы... и он очень хотел бы, чтобы этот разговор не дошел до ушей верховного друида.$b$bЕсли вы заинтересовались, поговорите с Кинтисом; не сомневайтесь, он расскажет вам все подробно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Квинтисом Ночным Костром в Крепости Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю вас за ваш визит, $Gусталый:усталая; $Gпутник:путница;! Позвольте представиться: я – Квинтис Ночной Костер, друид и скромный слуга Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперенная Луна и Протекторат – вы, может быть, о нас слыхали) и я хотели бы поговорить с вами о той работе, которую вы проводите для Фэндрала Оленьего Шлема в Дарнассе.$B$BПрежде чем мы пойдем дальше, я хотел бы попросить вас, чтобы этот разговор остался строго между нами. Если вы с этим согласны, мы можем продолжать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3788,'Просьба друида','Простите, друг мой...$b$bОдин мой коллега хотел бы побеседовать с вами об исследованиях, которые вы ведете в сотрудничестве с Кругом Кенария. Это друид по имени Квинтис Ночной Костер. Он проживает здесь же, в Крепости Оперенной Луны. Он хотел бы поговорить с вами насчет рассветницы... а главное, очень просит вас, чтобы эта беседа не дошла до ушей верховного друида.$b$bЕсли вас это интересует, поговорите с ним, и вам все станет ясно.','Поговорите с друидом по имени Квинтис Ночной Костер в Крепости Оперенной Луны.','Благодарю вас, что явились ко мне, $Gусталый:усталая; $Gпутник:путница;! Позвольте представиться. Я – Квинтис Ночной Костер, друид и смиренный служитель Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперенная Луна и Протекторат – быть может, вы о нас слышали), и я хотел поговорить с вами о работе, которую вы ведете в Дарнассе по поручению Фэндрала Оленьего Шлема.$B$BНо прежде, чем мы продолжим наш разговор, я хотел бы вас попросить, чтобы эта беседа осталась между нами. Если вы не против, то мы можем перейти к делу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба друида',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Простите, друг мой...$b$bОдин мой коллега хотел бы побеседовать с вами об исследованиях, которые вы ведете в сотрудничестве с Кругом Кенария. Это друид по имени Квинтис Ночной Костер. Он проживает здесь же, в Крепости Оперенной Луны. Он хотел бы поговорить с вами насчет рассветницы... а главное, очень просит вас, чтобы эта беседа не дошла до ушей верховного друида.$b$bЕсли вас это интересует, поговорите с ним, и вам все станет ясно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с друидом по имени Квинтис Ночной Костер в Крепости Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю вас, что явились ко мне, $Gусталый:усталая; $Gпутник:путница;! Позвольте представиться. Я – Квинтис Ночной Костер, друид и смиренный служитель Малфуриона и Круга Кенария. Мои коллеги (генерал Шандриса Оперенная Луна и Протекторат – быть может, вы о нас слышали), и я хотел поговорить с вами о работе, которую вы ведете в Дарнассе по поручению Фэндрала Оленьего Шлема.$B$BНо прежде, чем мы продолжим наш разговор, я хотел бы вас попросить, чтобы эта беседа осталась между нами. Если вы не против, то мы можем перейти к делу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3789,'Помощь верховному друиду Оленьему Шлему','$C, простите, но нельзя ли отвлечь вас на минутку от ваших дел?$B$BКруг Кенария в Дарнасе приглашает искателей приключений для участия в жизненно важном проекте. Я не знаю всех подробностей, собственно, могу сказать только, что верховный друид Фэндрал Олений Шлем рассылает это приглашение.$B$BЕсли вас это интересует, обратитесь к нему напрямую, вы найдете его в дарнасском Анклаве Кенария.','Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.','Что же, $C... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.$B$BИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь верховному друиду Оленьему Шлему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, простите, но нельзя ли отвлечь вас на минутку от ваших дел?$B$BКруг Кенария в Дарнасе приглашает искателей приключений для участия в жизненно важном проекте. Я не знаю всех подробностей, собственно, могу сказать только, что верховный друид Фэндрал Олений Шлем рассылает это приглашение.$B$BЕсли вас это интересует, обратитесь к нему напрямую, вы найдете его в дарнасском Анклаве Кенария.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что же, $C... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.$B$BИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3790,'Помощь верховному друиду Оленьему Шлему','Простите, |3-6($c), не уделите ли вы мне крупицу вашего времени?$B$BДарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит ни кто иной, как сам верховный друид Фэндрал Олений Шлем.$B$BПрошу вас, если вам интересно, поговорите с ним лично в Анклаве Кенария в Дарнасе.','Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.','Что же, |3-6($C)... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.$B$BИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь верховному друиду Оленьему Шлему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Простите, |3-6($c), не уделите ли вы мне крупицу вашего времени?$B$BДарнасский Круг Кенария набирает опытных искателей приключений – вроде вас – для помощи в жизненно важном исследовательском проекте. Подробностей я не знаю, но могу сказать, что исследованиями руководит ни кто иной, как сам верховный друид Фэндрал Олений Шлем.$B$BПрошу вас, если вам интересно, поговорите с ним лично в Анклаве Кенария в Дарнасе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что же, |3-6($C)... поскольку вам сказали, что этими исследованиями руковожу лично я, то вы, несомненно, прибыли сюда так быстро, как могли.$B$BИ раз уж вы здесь, постарайтесь запомнить мои пояснения с первого раза, ибо повторять я не буду.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3791,'Тайна рассветницы','$n, я буду с вами откровенен. Меня интересует – точнее, тревожит вопрос, почему верховный друид в Дарнасе пользуется именем и возможностями Круга Кенария для того, чтобы добывать огромное количество рассветницы. Я – исследователь, и специализируюсь на проклятиях. И я слышал, что рассветница в соответствующих условиях приобретает те же свойства, что и прочие травы, используемые в примитивных проклятиях.$b$bЯ хотел бы узнать об этом подробнее. И мне нужна ваша помощь. Принесите мне десять рассветниц, и я буду у вас в долгу!','Принесите 10 рассветниц друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.','Какое... какое странное ощущение вызывают у меня эти растения! Во имя Элуны, что же затеял Олений Шлем?$B$BНу, как бы то ни было, спасибо вам за помощь. Вот кое-что... ну, понимаете, за труды. Мои исследования, несомненно, затянутся, и мне потребуется еще немало такой травы. Раз уж я этим занялся, пожалуй, стоит проверить, пригодна ли рассветница для использования в алхимии. И тем не менее мне не по себе от этих растений...','Мне нужно десять рассветниц – этого должно хватить как минимум для первоначальных исследований. Конечно, поначалу немалое количество материала будет потрачено на тупиковые эксперименты, но такова уж природа научного исследования!','Вернитесь к Квинтису Ночному Костру в Крепость Оперенной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна рассветницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я буду с вами откровенен. Меня интересует – точнее, тревожит вопрос, почему верховный друид в Дарнасе пользуется именем и возможностями Круга Кенария для того, чтобы добывать огромное количество рассветницы. Я – исследователь, и специализируюсь на проклятиях. И я слышал, что рассветница в соответствующих условиях приобретает те же свойства, что и прочие травы, используемые в примитивных проклятиях.$b$bЯ хотел бы узнать об этом подробнее. И мне нужна ваша помощь. Принесите мне десять рассветниц, и я буду у вас в долгу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 рассветниц друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какое... какое странное ощущение вызывают у меня эти растения! Во имя Элуны, что же затеял Олений Шлем?$B$BНу, как бы то ни было, спасибо вам за помощь. Вот кое-что... ну, понимаете, за труды. Мои исследования, несомненно, затянутся, и мне потребуется еще немало такой травы. Раз уж я этим занялся, пожалуй, стоит проверить, пригодна ли рассветница для использования в алхимии. И тем не менее мне не по себе от этих растений...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно десять рассветниц – этого должно хватить как минимум для первоначальных исследований. Конечно, поначалу немалое количество материала будет потрачено на тупиковые эксперименты, но такова уж природа научного исследования!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Квинтису Ночному Костру в Крепость Оперенной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3792,'Рассветница для Крепости Оперенной Луны','Спасибо, $N. Я их пока припрячу. У меня, конечно, нет таких значительных средств, как у Оленьего Шлема, однако я все же способен вознаградить вас за труды! Тем более, кто знает, что может случиться, если Олений Шлем будет получать все больше рассветницы... Тут что-то нечисто, помяните мои слова!$B$BНе забывайте, что от лишней рассветницы я никогда не откажусь. Приносите по пять штук за раз, и я их возьму.','А, здравствуйте, $N! Мои исследования продвигаются неплохо, но, если у вас найдется еще пять рассветниц, я бы с удовольствием их у вас приобрел. Хотя, конечно, с удовольствием – это только фигура речи: чем больше я имею с нею дело, тем сильнее мне не по себе. И тем не менее я не намерен отказываться от дальнейших экспериментов!','Вернитесь к Квинтису Ночному Костру в Крепость Оперенной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассветница для Крепости Оперенной Луны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Я их пока припрячу. У меня, конечно, нет таких значительных средств, как у Оленьего Шлема, однако я все же способен вознаградить вас за труды! Тем более, кто знает, что может случиться, если Олений Шлем будет получать все больше рассветницы... Тут что-то нечисто, помяните мои слова!$B$BНе забывайте, что от лишней рассветницы я никогда не откажусь. Приносите по пять штук за раз, и я их возьму.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, здравствуйте, $N! Мои исследования продвигаются неплохо, но, если у вас найдется еще пять рассветниц, я бы с удовольствием их у вас приобрел. Хотя, конечно, с удовольствием – это только фигура речи: чем больше я имею с нею дело, тем сильнее мне не по себе. И тем не менее я не намерен отказываться от дальнейших экспериментов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Квинтису Ночному Костру в Крепость Оперенной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3801,'Наследие Черного Железа','Привет тебе, $n. Я Франклорн Искусник. Да, тот самый Франклорн Искусник, который придумал, как тесать камень. За долгие странствия по терзаемому войнами миру тебе несомненно случалось проходить сквозь мои творения или стоять на них.$b$bДолжно быть, тебе интересно, откуда я здесь и что мне от тебя нужно. Логичные вопросы.$b$bРазумеется, мне нужна твоя помощь. В обмен на нее я дарую тебе ключ, открывающий путь в глубины моего проклятого города.','Чтобы получить ключ от города, поговорите с Франклорном Искусником у гробницы Искусника на Черной горе.','Жадность ли привела тебя сюда или слепая верность, от твоего предприятия будет благо нам всем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Черного Железа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $n. Я Франклорн Искусник. Да, тот самый Франклорн Искусник, который придумал, как тесать камень. За долгие странствия по терзаемому войнами миру тебе несомненно случалось проходить сквозь мои творения или стоять на них.$b$bДолжно быть, тебе интересно, откуда я здесь и что мне от тебя нужно. Логичные вопросы.$b$bРазумеется, мне нужна твоя помощь. В обмен на нее я дарую тебе ключ, открывающий путь в глубины моего проклятого города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Чтобы получить ключ от города, поговорите с Франклорном Искусником у гробницы Искусника на Черной горе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жадность ли привела тебя сюда или слепая верность, от твоего предприятия будет благо нам всем.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3802,'Наследие Черного Железа','Финий Темнострой находится за Кольцом Закона в Зале Ремесла. Убей ничтожную тварь и забери Железного Друга.$b$bОтнеси Железного Друга в святилище Тауриссана и помести молот в предначертанное ему место: в руки статуи, воздвигнутой в мою честь.$b$bПосле этого откроется тайное отделение, в котором я спрятал главный ключ. А главное, Железный Друг навеки останется в моих руках. Если они предпримут попытку забрать его, то статуя и молот рассыплются и исчезнут вовек.','Убейте Финия Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника.','Молот легко встает на место, в руку массивного монумента Черного Железа. У основания статуи открывается тайное отделение. Внутри оказывается...','Статуя зловеще нависает над вами.','Вернитесь к монументу Франклорну Искуснику в святилище Тауриссан в Глубинах Черной горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Черного Железа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Финий Темнострой находится за Кольцом Закона в Зале Ремесла. Убей ничтожную тварь и забери Железного Друга.$b$bОтнеси Железного Друга в святилище Тауриссана и помести молот в предначертанное ему место: в руки статуи, воздвигнутой в мою честь.$b$bПосле этого откроется тайное отделение, в котором я спрятал главный ключ. А главное, Железный Друг навеки останется в моих руках. Если они предпримут попытку забрать его, то статуя и молот рассыплются и исчезнут вовек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Финия Темностроя и добудьте великий молот, Железный Друг. Отнесите Железного Друга в святилище Тауриссана и вложите его в руки статуи Франклорна Искусника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молот легко встает на место, в руку массивного монумента Черного Железа. У основания статуи открывается тайное отделение. Внутри оказывается...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Статуя зловеще нависает над вами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к монументу Франклорну Искуснику в святилище Тауриссан в Глубинах Черной горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3803,'Рассветница для Дарнаса','Великолепно! Верховный друид, несомненно, обрадуется этой рассветнице. Правда, должен признать... даже находиться рядом с ней с ней не особо приятно. Представляю, как тяжело верховному друиду все время возиться с этой травой!$B$BА это для тебя, $N. Круг Кенария благодарит тебя за безотказную помощь.','Верховному друиду постоянно не хватает рассветницы для проведения исследований Круга Кенария. Мы принимаем ее партиями по десять пучков и в награду даем несколько полезных вещей. Когда соберешь десять пучков, сообщи мне, и я достойно награжу тебя.','Вернитесь к Матренгилу Медвежьей Лапе в Тельдрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассветница для Дарнаса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Верховный друид, несомненно, обрадуется этой рассветнице. Правда, должен признать... даже находиться рядом с ней с ней не особо приятно. Представляю, как тяжело верховному друиду все время возиться с этой травой!$B$BА это для тебя, $N. Круг Кенария благодарит тебя за безотказную помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Верховному друиду постоянно не хватает рассветницы для проведения исследований Круга Кенария. Мы принимаем ее партиями по десять пучков и в награду даем несколько полезных вещей. Когда соберешь десять пучков, сообщи мне, и я достойно награжу тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матренгилу Медвежьей Лапе в Тельдрассил.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3804,'Рассветница для Громового Утеса','Великолепно – эта рассветница несомненно поможет нам в будущем! Мы знаем, что и ночные эльфы проводят подобные исследования трав, хотя непонятно, для чего будут они использовать результаты – если, конечно, что-нибудь найдут. Верховный друид считает, что рассветница будет нам нужна до тех пор, пока мы на узнаем тайну этого растения.$B$BА это для тебя, $N. Круг Кенария благодарит тебя за неустанную помощь.','Верховный друид постоянно ищет дополнительные источники рассветницы для исследовательского проекта Круга Кенария в Кратере Ун\'Горо. Мы берем их партиями по десять штук и в награду даем несколько полезных вещей. Когда наберешь десять штук, сообщи мне, и я достойно награжу тебя.','Вернитесь к Башане Руническому Тотему в Пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассветница для Громового Утеса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно – эта рассветница несомненно поможет нам в будущем! Мы знаем, что и ночные эльфы проводят подобные исследования трав, хотя непонятно, для чего будут они использовать результаты – если, конечно, что-нибудь найдут. Верховный друид считает, что рассветница будет нам нужна до тех пор, пока мы на узнаем тайну этого растения.$B$BА это для тебя, $N. Круг Кенария благодарит тебя за неустанную помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Верховный друид постоянно ищет дополнительные источники рассветницы для исследовательского проекта Круга Кенария в Кратере Ун\'Горо. Мы берем их партиями по десять штук и в награду даем несколько полезных вещей. Когда наберешь десять штук, сообщи мне, и я достойно награжу тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Башане Руническому Тотему в Пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3821,'Скала Молота Ужаса','Несколько недель назад Ша\'ни была отправлена в Пылающие степи, чтобы исследовать странные ритуалы огров клана Огненного Чрева – что-то эти огры оживились в последнее время. $B$BКлинозуб сообщил мне, что от ее группы с тех пор не было вестей, и что главное сейчас – заняться неотложными делами. Представляешь?! А речь, между прочим, о моей жене! $B$BЯ не вправе оставить свой пост, но я должен знать, что случилось с Ша\'ни! Отправляйся в Пылающие степи и найди ее!','Отправляйтесь в Пылающие степи и выясните, что сталось с Ша\'ни Гордый Клык.','Бедный мой Талтрак...$B$BА мы ведь хотели уехать во Внутренние земли вместе с родителями, когда закончим службу. Теперь этим мечтам не суждено сбыться!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скала Молота Ужаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несколько недель назад Ша\'ни была отправлена в Пылающие степи, чтобы исследовать странные ритуалы огров клана Огненного Чрева – что-то эти огры оживились в последнее время. $B$BКлинозуб сообщил мне, что от ее группы с тех пор не было вестей, и что главное сейчас – заняться неотложными делами. Представляешь?! А речь, между прочим, о моей жене! $B$BЯ не вправе оставить свой пост, но я должен знать, что случилось с Ша\'ни! Отправляйся в Пылающие степи и найди ее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Пылающие степи и выясните, что сталось с Ша\'ни Гордый Клык.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бедный мой Талтрак...$B$BА мы ведь хотели уехать во Внутренние земли вместе с родителями, когда закончим службу. Теперь этим мечтам не суждено сбыться!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3822,'Кром\'Грул','Они захватили весь мой взвод, $n. И всех, кроме меня, убили.$b$bИх главарь, Кром\'Грул, оставил меня для совершения какого-то обряда.$b$bМеня приковали к этому алтарю и жестоко пытали. Через час мучений мое физическое тело умерло. Тогда эта тварь вырвала у меня из носа обручальное кольцо и напялила на свой палец. В жизни не встречала подобного варварства!$b$bНайди Кром\'Грула и убей его! Отнеси мое кольцо Талтраку.$b$bИ, $n, скажи ему, что мы снова встретимся... в следующей жизни.','Заберите ноздревое кольцо Ша\'ни у Кром\'Грула и верните его Тал\'траку из Каргата. Обыщите различные пещеры и рудники скалы Молота Ужаса.','<Талтрак опускается на пол.>$B$BМы собирались уехать во Внутренние земли. Она рассказывала? Это было ее последнее задание.$B$B<Талтрак плачет.>$B$BОно мне не нужно, $N. Оставь его себе или выброси, мне все равно! Теперь кольцо ничего для меня не значит. Без нее оно ничто...','Тебе удалось найти Ша\'ни? С ней все в порядке?','Вернитесь к Тал\'траку Гордому Клыку в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кром\'Грул',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они захватили весь мой взвод, $n. И всех, кроме меня, убили.$b$bИх главарь, Кром\'Грул, оставил меня для совершения какого-то обряда.$b$bМеня приковали к этому алтарю и жестоко пытали. Через час мучений мое физическое тело умерло. Тогда эта тварь вырвала у меня из носа обручальное кольцо и напялила на свой палец. В жизни не встречала подобного варварства!$b$bНайди Кром\'Грула и убей его! Отнеси мое кольцо Талтраку.$b$bИ, $n, скажи ему, что мы снова встретимся... в следующей жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите ноздревое кольцо Ша\'ни у Кром\'Грула и верните его Тал\'траку из Каргата. Обыщите различные пещеры и рудники скалы Молота Ужаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Талтрак опускается на пол.>$B$BМы собирались уехать во Внутренние земли. Она рассказывала? Это было ее последнее задание.$B$B<Талтрак плачет.>$B$BОно мне не нужно, $N. Оставь его себе или выброси, мне все равно! Теперь кольцо ничего для меня не значит. Без нее оно ничто...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти Ша\'ни? С ней все в порядке?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тал\'траку Гордому Клыку в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3823,'Угасание Огненного Чрева','Мы должны нанести удар первыми!$b$bБуду краток.$b$bОгры Огненного Чрева – союзники орков Черной горы в Пылающих степях. Рука об руку они охраняют богатую полезными ископаемыми скалу Молота Ужаса и линии снабжения.$b$bОставь свой след в истории, $n. Смети их охрану и возвращайся ко мне.$b$b<Орелий хватается за воздух, будто кого-то душит.>$b$bЯ тебя прибью, Винки!','Убейте 15 огров-магов, 7 огров и 7 громил из клана Огненного Чрева.','Потрясающе, солдат! Оркам и ограм понадобится несколько минут или даже часов, чтобы оправиться от удара!','На твоей форме крови почти не хватает, солдат!','Вернитесь к Орелию в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угасание Огненного Чрева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны нанести удар первыми!$b$bБуду краток.$b$bОгры Огненного Чрева – союзники орков Черной горы в Пылающих степях. Рука об руку они охраняют богатую полезными ископаемыми скалу Молота Ужаса и линии снабжения.$b$bОставь свой след в истории, $n. Смети их охрану и возвращайся ко мне.$b$b<Орелий хватается за воздух, будто кого-то душит.>$b$bЯ тебя прибью, Винки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 огров-магов, 7 огров и 7 громил из клана Огненного Чрева.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе, солдат! Оркам и ограм понадобится несколько минут или даже часов, чтобы оправиться от удара!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На твоей форме крови почти не хватает, солдат!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орелию в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3824,'Гор\'теш Жестокий','Говорю же, они колеблются! Пора нанести решительный удар.$B$BМы должны убить жестокого вождя, Гор\'теша. И что еще важнее, мне нужна его голова для третьей фазы операции против огров Огненного Чрева.$B$BИ помни, солдат, Гор\'теш правит не из скалы Молота Ужаса, но из строения орков Черной горы на западе от нее.$B$BИтак, приказы тебе даны ясные. Найди Гор\'теша и отруби ему башку. Потом возвращайся ко мне.$B$BЗАТКНИСЬ, Винки!','Завладейте головой Гор\'теша.','Только посмотрите на нее. Какая мерзость! Когда остатки огров Огненного Чрева увидят этот жирный чайник на вершине собственной скалы, начнется паника!$B$B<Орелиус хохочет.>','О радость, о счастье! Ты несешь его голову?','Вернитесь к Орелию в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гор\'теш Жестокий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорю же, они колеблются! Пора нанести решительный удар.$B$BМы должны убить жестокого вождя, Гор\'теша. И что еще важнее, мне нужна его голова для третьей фазы операции против огров Огненного Чрева.$B$BИ помни, солдат, Гор\'теш правит не из скалы Молота Ужаса, но из строения орков Черной горы на западе от нее.$B$BИтак, приказы тебе даны ясные. Найди Гор\'теша и отруби ему башку. Потом возвращайся ко мне.$B$BЗАТКНИСЬ, Винки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Завладейте головой Гор\'теша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Только посмотрите на нее. Какая мерзость! Когда остатки огров Огненного Чрева увидят этот жирный чайник на вершине собственной скалы, начнется паника!$B$B<Орелиус хохочет.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О радость, о счастье! Ты несешь его голову?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орелию в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3825,'Голова огра на палочке = вечеринка','Осталось только одно задание, солдат.$b$bЯ позволил себе вольность – нанизал голову Гор\'теша на пику. Тебе остается отнести ее на вершину скалы Молота Ужаса и воткнуть в землю. Стоит только сделать это, как трусливые огры бросятся куда глаза глядят! Когда ты повеселишься от души, возвращайся ко мне, и я награжу тебя за проделанную работу.$b$b*Кажется, Орелий теряет связь с реальностью.*','Отнесите голову Гор\'теша на вершину скалы Молота Ужаса. Поищите кучу рыхлой земли и воткните в нее пику.','Отличная работа, солдат! Поразительная! Ах, я получу медаль за храбрость, то есть, я хочу сказать, ты получишь недурную награду!','Ну как? Ты $Gзарисовал:зарисовала; повальное бегство огров?','Вернитесь к Орелию в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голова огра на палочке = вечеринка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осталось только одно задание, солдат.$b$bЯ позволил себе вольность – нанизал голову Гор\'теша на пику. Тебе остается отнести ее на вершину скалы Молота Ужаса и воткнуть в землю. Стоит только сделать это, как трусливые огры бросятся куда глаза глядят! Когда ты повеселишься от души, возвращайся ко мне, и я награжу тебя за проделанную работу.$b$b*Кажется, Орелий теряет связь с реальностью.*',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите голову Гор\'теша на вершину скалы Молота Ужаса. Поищите кучу рыхлой земли и воткните в нее пику.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, солдат! Поразительная! Ах, я получу медаль за храбрость, то есть, я хочу сказать, ты получишь недурную награду!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как? Ты $Gзарисовал:зарисовала; повальное бегство огров?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орелию в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3841,'Бездомный сиротка','О, $n, привет! Я так рада видеть тебя снова! Как твое путешествие в Дарнас?$b$bА у нас тут приятные новости! Пока тебя не было, мы сумели многого добиться. Мы даже спасли целую кладку яиц! К сожалению, самка погибла прежде, чем мы подоспели...$b$bСлушай, хочешь себе такого дракончика? Детеныши скоро должны вылупиться, и им понадобится $gхороший папа:хорошая мама;. Ну, что скажешь?$b$bЕсли тебя это действительно интересует, возьми одно из яиц и ступай к Квентину, который находится на Мерцающей равнине, возле гоночной трассы. Он тебе скажет, что делать дальше.','Поговорите с Квентином в Тысяче Игл.','О, яйцо летучего хамелеона! И вот-вот должно проклюнуться, если я не ошибаюсь. Удивительно, как тебе удалось его добыть, да еще в таком хорошем состоянии? В Фераласе в наше время эти животные почти не делают кладок... Насколько я понимаю, в тамошних лесах развелась уйма браконьеров, которые охотятся на этих прекрасных созданий и убивают их. Какая жалость, не правда ли?$B$BНо откуда у тебя это яйцо?','А, $R, привет!$B$BТы не думай, я тут не ради гонок... хотя зрелище, конечно, занимательное.$B$BЯ прибыл сюда, в Тысячу Игл, чтобы выяснить, можно ли спасти эти земли. Для меня это своего рода личный подвиг: добиться, чтобы эта пустыня вновь расцвела и зазеленела! Может быть, мне все же удастся обнаружить неподалеку источники воды...$B$BТы ведь не $Gмог:могла; не заметить, какой резкий переход наблюдается между Фераласом и Тысячей Игл? Тут наверняка не обошлось без магии...\r\n') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бездомный сиротка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, $n, привет! Я так рада видеть тебя снова! Как твое путешествие в Дарнас?$b$bА у нас тут приятные новости! Пока тебя не было, мы сумели многого добиться. Мы даже спасли целую кладку яиц! К сожалению, самка погибла прежде, чем мы подоспели...$b$bСлушай, хочешь себе такого дракончика? Детеныши скоро должны вылупиться, и им понадобится $gхороший папа:хорошая мама;. Ну, что скажешь?$b$bЕсли тебя это действительно интересует, возьми одно из яиц и ступай к Квентину, который находится на Мерцающей равнине, возле гоночной трассы. Он тебе скажет, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Квентином в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, яйцо летучего хамелеона! И вот-вот должно проклюнуться, если я не ошибаюсь. Удивительно, как тебе удалось его добыть, да еще в таком хорошем состоянии? В Фераласе в наше время эти животные почти не делают кладок... Насколько я понимаю, в тамошних лесах развелась уйма браконьеров, которые охотятся на этих прекрасных созданий и убивают их. Какая жалость, не правда ли?$B$BНо откуда у тебя это яйцо?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, $R, привет!$B$BТы не думай, я тут не ради гонок... хотя зрелище, конечно, занимательное.$B$BЯ прибыл сюда, в Тысячу Игл, чтобы выяснить, можно ли спасти эти земли. Для меня это своего рода личный подвиг: добиться, чтобы эта пустыня вновь расцвела и зазеленела! Может быть, мне все же удастся обнаружить неподалеку источники воды...$B$BТы ведь не $Gмог:могла; не заметить, какой резкий переход наблюдается между Фераласом и Тысячей Игл? Тут наверняка не обошлось без магии...\r\n',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3842,'Инкубатор','Кинда и Джер\'ка? Занятно... Жаль, что летучие хамелеоны не смогут оценить все, что эти девушки для них делают. Очень, очень способные девочки...$b$bТак значит, они дали тебе это яйцо в подарок? Что ж, теперь оно твое и ты за него отвечаешь. Оно, похоже, вот-вот проклюнется, но нужно еще позаботиться о том, чтобы детеныш вылупился здоровым.$b$bДля заклинания, которое будет защищать яйцо, мне требуется только два эликсира стойкости. Остальные компоненты у меня уже есть.','Принесите 2 эликсира стойкости Квентину в Тысячу Игл.','Великолепно! Это то, что надо. Сейчас, я смешаю все компоненты, и мы поглядим, как будет себя чувствовать детеныш...','Чем дольше я здесь нахожусь, тем сильнее мне хочется поучаствовать в этих гонках, $N. Просто крышу сносит…$B$BНу что, удалось тебе добыть эликсиры? Как только я смогу поручиться за здоровье детеныша, я верну яйцо тебе, и оно останется у тебя, пока не проклюнется.$B$BСообщи мне, как добудешь их.','Вернитесь к Квентину в поселок Виражи на Миражах, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Инкубатор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кинда и Джер\'ка? Занятно... Жаль, что летучие хамелеоны не смогут оценить все, что эти девушки для них делают. Очень, очень способные девочки...$b$bТак значит, они дали тебе это яйцо в подарок? Что ж, теперь оно твое и ты за него отвечаешь. Оно, похоже, вот-вот проклюнется, но нужно еще позаботиться о том, чтобы детеныш вылупился здоровым.$b$bДля заклинания, которое будет защищать яйцо, мне требуется только два эликсира стойкости. Остальные компоненты у меня уже есть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 эликсира стойкости Квентину в Тысячу Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Это то, что надо. Сейчас, я смешаю все компоненты, и мы поглядим, как будет себя чувствовать детеныш...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем дольше я здесь нахожусь, тем сильнее мне хочется поучаствовать в этих гонках, $N. Просто крышу сносит…$B$BНу что, удалось тебе добыть эликсиры? Как только я смогу поручиться за здоровье детеныша, я верну яйцо тебе, и оно останется у тебя, пока не проклюнется.$B$BСообщи мне, как добудешь их.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Квентину в поселок Виражи на Миражах, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3843,'Новый член семьи','Великолепный экземпляр, $n! Если это создание благополучно вылупится на свет, у тебя будет прекрасный, здоровый питомец!$b$bНо если ты рассчитываешь оставить его себе, я бы посоветовал сделать еще одну вещь. Отправляйся на Заоблачный пик во Внутренних землях, и поговори там с дворфом по имени Агнар Зверопас. Он большой специалист по дрессировке животных, и объяснит тебе, что нужно делать дальше.$b$bТолько ступай скорее, $n, яйцо хрупкое и без должного ухода долго не протянет!','Отнесите хрупкое яйцо летучего хамелеона во Внутренние земли и поговорите с Агнаром Зверопасом. У вас есть на это всего 1 час. В противном случае детеныш в яйце умрет.','Так-так-так... Таких мелких я даже и не видел. Лесной дракончик, если не ошибаюсь... точнее, летучий хамелеон. Отлично, отлично!$B$BНу, чтобы этот малыш благополучно выжил и вырос крепким и здоровым, нужно раздобыть для него еды! Хорошо, что ты вовремя до меня $Gдобрался:добралась;!','Привет, $N. Чем могу пригодиться?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый член семьи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Великолепный экземпляр, $n! Если это создание благополучно вылупится на свет, у тебя будет прекрасный, здоровый питомец!$b$bНо если ты рассчитываешь оставить его себе, я бы посоветовал сделать еще одну вещь. Отправляйся на Заоблачный пик во Внутренних землях, и поговори там с дворфом по имени Агнар Зверопас. Он большой специалист по дрессировке животных, и объяснит тебе, что нужно делать дальше.$b$bТолько ступай скорее, $n, яйцо хрупкое и без должного ухода долго не протянет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите хрупкое яйцо летучего хамелеона во Внутренние земли и поговорите с Агнаром Зверопасом. У вас есть на это всего 1 час. В противном случае детеныш в яйце умрет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так-так-так... Таких мелких я даже и не видел. Лесной дракончик, если не ошибаюсь... точнее, летучий хамелеон. Отлично, отлично!$B$BНу, чтобы этот малыш благополучно выжил и вырос крепким и здоровым, нужно раздобыть для него еды! Хорошо, что ты вовремя до меня $Gдобрался:добралась;!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $N. Чем могу пригодиться?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3844,'Тайна, покрытая мраком','На берегу вы видите разбитый плот. Если учесть, что пруд очень мал, непонятно, как мог оказаться в нем плот, да еще такой побитый непогодой. Хотя, более пристальный взгляд на деревья дает возможность предположить, что уровень воды здесь не постоянный... $B$BВозможно, если приглядеться повнимательней, можно отыскать ключ к загадке...','Осмотритесь и попытайтесь выяснить, кому мог бы принадлежать разбитый плот.','На дне пруда виднеется какой-то сверток.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна, покрытая мраком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На берегу вы видите разбитый плот. Если учесть, что пруд очень мал, непонятно, как мог оказаться в нем плот, да еще такой побитый непогодой. Хотя, более пристальный взгляд на деревья дает возможность предположить, что уровень воды здесь не постоянный... $B$BВозможно, если приглядеться повнимательней, можно отыскать ключ к загадке...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осмотритесь и попытайтесь выяснить, кому мог бы принадлежать разбитый плот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На дне пруда виднеется какой-то сверток.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3845,'Тайна, покрытая мраком','Вы вытаскиваете сумку на берег, в надежде, что ее содержимое укажет вам на то, откуда она могла взяться и кому бы могла принадлежать. $B$BВсе же немногие путники забредают в Укрытие Маршалла...','Изучите найденное в сумке и верните владельцу.','О, а вот это, похоже, и в самом деле мне знакомо!','Приветствую! Простите, а мы не встречались раньше? Ваше лицо выглядит знакомым...','Вернитесь к Линкену в Укрытие Маршалла, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна, покрытая мраком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы вытаскиваете сумку на берег, в надежде, что ее содержимое укажет вам на то, откуда она могла взяться и кому бы могла принадлежать. $B$BВсе же немногие путники забредают в Укрытие Маршалла...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите найденное в сумке и верните владельцу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, а вот это, похоже, и в самом деле мне знакомо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую! Простите, а мы не встречались раньше? Ваше лицо выглядит знакомым...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линкену в Укрытие Маршалла, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (3861,'Куд-кудаааа!','"Куд... куд... куд... КУДАХ!$B$BКуд... куд... куд."$B$BКурица смотрит на вас одним глазом, затем начинает скрести когтями землю. Кажется, она пытается что-то написать, но вы не можете разобрать буквы. Может быть... С-А-Л-Ь-Д-Е-Н? Не дожидаясь расспросов, курица разворачивается и отправляется по своим куриным делам.','Найдите немного цыплячьего корма и вернитесь к вашей курочке-подружке. Когда найдете курицу, покажите, как вы рады ее видеть (эмоция "/рад"), а потом накормите специальным цыплячьим кормом.','"Куд-кудааа!!!"$B$BКурица начинает жадно клевать корм, который вы рассыпали перед ней.$B$BЧерез несколько мгновений она испуганно оглядывается по сторонам. Начинает скрести лапой и суетиться. Она что, яйца снести хочет? Вы думаете, что надо бы заглянуть под нее.','Вернитесь к курице.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Куд-кудаааа!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Куд... куд... куд... КУДАХ!$B$BКуд... куд... куд."$B$BКурица смотрит на вас одним глазом, затем начинает скрести когтями землю. Кажется, она пытается что-то написать, но вы не можете разобрать буквы. Может быть... С-А-Л-Ь-Д-Е-Н? Не дожидаясь расспросов, курица разворачивается и отправляется по своим куриным делам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите немного цыплячьего корма и вернитесь к вашей курочке-подружке. Когда найдете курицу, покажите, как вы рады ее видеть (эмоция "/рад"), а потом накормите специальным цыплячьим кормом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','"Куд-кудааа!!!"$B$BКурица начинает жадно клевать корм, который вы рассыпали перед ней.$B$BЧерез несколько мгновений она испуганно оглядывается по сторонам. Начинает скрести лапой и суетиться. Она что, яйца снести хочет? Вы думаете, что надо бы заглянуть под нее.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к курице.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3881,'Спасение экспедиции','Не знаю, какими судьбами ты $gоказался:оказалась; здесь, но ты для нас $gжеланный:желанная; $gгость:гостья;! Меня зовут Виллиден Маршалл, я здесь с независимой исследовательской экспедицией. Последняя и самая важная наша кампания столкнулась с многочисленными трудностями. Пожалуй, наиболее существенным нашим просчетом было то, что мы недооценили опасность, которую несет в себе дикая природа Кратера Ун\'Горо. $B$BНам пришлось в спешке покинуть наши главные стоянки в северо-восточной и юго-западной областях кратера, побросав жизненно важные припасы. С твоей силой, ты $gмог:могла; бы помочь нам их вернуть, правда?','Принесите ящик с провизией и исследовательское оборудование Виллидену Маршаллу в Кратер Ун\'Горо.','Если мы вообще хотим выжить в этом жутком месте, нам нужна провизия. А спасение хоть каких-то из наших исследовательских инструментов было бы просто манной небесной!','Вернитесь к Виллидену Маршаллу в Укрытие Маршалла, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение экспедиции',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, какими судьбами ты $gоказался:оказалась; здесь, но ты для нас $gжеланный:желанная; $gгость:гостья;! Меня зовут Виллиден Маршалл, я здесь с независимой исследовательской экспедицией. Последняя и самая важная наша кампания столкнулась с многочисленными трудностями. Пожалуй, наиболее существенным нашим просчетом было то, что мы недооценили опасность, которую несет в себе дикая природа Кратера Ун\'Горо. $B$BНам пришлось в спешке покинуть наши главные стоянки в северо-восточной и юго-западной областях кратера, побросав жизненно важные припасы. С твоей силой, ты $gмог:могла; бы помочь нам их вернуть, правда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ящик с провизией и исследовательское оборудование Виллидену Маршаллу в Кратер Ун\'Горо.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если мы вообще хотим выжить в этом жутком месте, нам нужна провизия. А спасение хоть каких-то из наших исследовательских инструментов было бы просто манной небесной!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виллидену Маршаллу в Укрытие Маршалла, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3882,'Игра в кости','Думаешь, раз в экспедиции Маршалла я ответственный за раскопки, то мне страшно нравится копаться в земле? Нет, я, конечно, мог бы придумать более паршивое занятие, но сейчас что-то ничего не приходит в голову.$B$BМы должны были вести раскопки в местечке под названием Путь Ужаса – неплохое название, не находишь? Искать, значит, там дохлых стегодонов и деметродонов... А их там, между прочим, и живых полным полно! Вил и Хол, видишь ли, хотят изучать это гиблое место, поэтому мы должны исправно поставлять им кости динозавров. Между нами говоря, живые для этих целей сгодились бы не хуже!','Принесите 8 костей динозавра Искру Пустокопу в Кратер Ун\'Горо.','Прекрасно, отличные кости, ну просто прелесть, что за кости!\n\nСПАСИБО, ЧТО ВЫРЫЛ ДЛЯ НАС ЭТИ ДРЕВНЕЙШИЕ КОСТИ И НЕ ОХОТИЛСЯ НА ЖИВОТНЫХ, ЧТО МОГЛО БЫ НАНЕСТИ НЕПОПРАВИМЫЙ УЩЕРБ ОКРУЖАЮЩЕЙ СРЕДЕ! \n\nТихо, тихо, не спорь со мной, мне совершенно неинтересно, где ты на самом деле их взял, так что давай замнем этот вопрос за ясностью. Вот, возьми это в награду и держи рот на замке, хорошо?','Можешь думать обо мне что хочешь, но эти лабораторные крысы даже не поймут, принадлежат ли принесенные им кости древним динозаврам или тем, которые пытались сожрать нас вместе с палатками прошлой ночью! Выбраться бы отсюда живым...','Вернитесь к Искру Пустокопу в Укрытие Маршалла, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игра в кости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаешь, раз в экспедиции Маршалла я ответственный за раскопки, то мне страшно нравится копаться в земле? Нет, я, конечно, мог бы придумать более паршивое занятие, но сейчас что-то ничего не приходит в голову.$B$BМы должны были вести раскопки в местечке под названием Путь Ужаса – неплохое название, не находишь? Искать, значит, там дохлых стегодонов и деметродонов... А их там, между прочим, и живых полным полно! Вил и Хол, видишь ли, хотят изучать это гиблое место, поэтому мы должны исправно поставлять им кости динозавров. Между нами говоря, живые для этих целей сгодились бы не хуже!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 костей динозавра Искру Пустокопу в Кратер Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, отличные кости, ну просто прелесть, что за кости!\n\nСПАСИБО, ЧТО ВЫРЫЛ ДЛЯ НАС ЭТИ ДРЕВНЕЙШИЕ КОСТИ И НЕ ОХОТИЛСЯ НА ЖИВОТНЫХ, ЧТО МОГЛО БЫ НАНЕСТИ НЕПОПРАВИМЫЙ УЩЕРБ ОКРУЖАЮЩЕЙ СРЕДЕ! \n\nТихо, тихо, не спорь со мной, мне совершенно неинтересно, где ты на самом деле их взял, так что давай замнем этот вопрос за ясностью. Вот, возьми это в награду и держи рот на замке, хорошо?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Можешь думать обо мне что хочешь, но эти лабораторные крысы даже не поймут, принадлежат ли принесенные им кости древним динозаврам или тем, которые пытались сожрать нас вместе с палатками прошлой ночью! Выбраться бы отсюда живым...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Искру Пустокопу в Укрытие Маршалла, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3883,'Экология чужих','То, что мы потерпели неудачу, еще не значит, что исследования надо прекратить! Мы изучали насекомых Гориши в южной части кратера, прежде чем были вынуждены ретироваться сюда. Их присутствие чуждо для экологии Ун\'Горо, и мы должны разобраться почему. $B$BВ их ульях должны быть инкубаторы для личинок. Эти места можно определить по свисающим гроздьям личинок. Возьми образец стены улья рядом с инкубатором вот в этот фиал и принеси его мне на исследование. Но будь $gосторожен:осторожна;!','Воспользуйтесь фиалом для образцов, чтобы взять образец материала со стены улья из одного из инкубаторов Гориши в Кратере Ун\'Горо. Ищите в ульях комнаты со свисающими гроздьями личинок. $B$BПринесите образец материала стены улья Холании Маршалл в Кратер Ун\'Горо.','О, прекрасно, ты очень $Gпомог:помогла; мне. Хотелось бы мне дать тебе большую награду, но жизнь на лоне дикой природы накладывает свои ограничения. Однако могу заверить, без твоей помощи наши исследования были бы невозможны.','Ты $Gпринес:принесла; мне образец для исследования, $N?','Вернитесь к Холании Маршалл в Укрытие Маршалла, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экология чужих',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, что мы потерпели неудачу, еще не значит, что исследования надо прекратить! Мы изучали насекомых Гориши в южной части кратера, прежде чем были вынуждены ретироваться сюда. Их присутствие чуждо для экологии Ун\'Горо, и мы должны разобраться почему. $B$BВ их ульях должны быть инкубаторы для личинок. Эти места можно определить по свисающим гроздьям личинок. Возьми образец стены улья рядом с инкубатором вот в этот фиал и принеси его мне на исследование. Но будь $gосторожен:осторожна;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь фиалом для образцов, чтобы взять образец материала со стены улья из одного из инкубаторов Гориши в Кратере Ун\'Горо. Ищите в ульях комнаты со свисающими гроздьями личинок. $B$BПринесите образец материала стены улья Холании Маршалл в Кратер Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, прекрасно, ты очень $Gпомог:помогла; мне. Хотелось бы мне дать тебе большую награду, но жизнь на лоне дикой природы накладывает свои ограничения. Однако могу заверить, без твоей помощи наши исследования были бы невозможны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне образец для исследования, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Холании Маршалл в Укрытие Маршалла, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3884,'Дневник Вилидена','Вы обнаружили изорванный дневник. Кое-какие страницы еще можно прочесть, в том числе и форзац, на котором значится имя Виллидена Маршалла. Если верить написанному в дневнике, Виллидена можно найти где-то на севере кратера, куда он и его товарищи были вынуждены бежать от диких зверей, напавших на их главную стоянку.','Верните дневник Виллидену Маршаллу, который находится где-то в Кратере Ун\'Горо.','Вы только взгляните на это! Мой дневник! Я думал, он утерян навсегда, как в все, что нам пришлось бросить в базовом лагере. Спасибо, что вернул мне его!','Приветствую! Мы с коллегами рады видеть собрата по разуму после стольких недель общения с диким зверьем! Что привело тебя в Кратер Ун\'Горо?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дневник Вилидена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы обнаружили изорванный дневник. Кое-какие страницы еще можно прочесть, в том числе и форзац, на котором значится имя Виллидена Маршалла. Если верить написанному в дневнике, Виллидена можно найти где-то на севере кратера, куда он и его товарищи были вынуждены бежать от диких зверей, напавших на их главную стоянку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните дневник Виллидену Маршаллу, который находится где-то в Кратере Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы только взгляните на это! Мой дневник! Я думал, он утерян навсегда, как в все, что нам пришлось бросить в базовом лагере. Спасибо, что вернул мне его!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую! Мы с коллегами рады видеть собрата по разуму после стольких недель общения с диким зверьем! Что привело тебя в Кратер Ун\'Горо?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (3885,'<NYI> <TXT> Путешествие в Прибамбасск','Сопроводи меня и Дадангу!','Сопроводите Петру и Дадангу.','Сопроводить Петру и Дадангу!','Вернитесь к Петре Гроссен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> Путешествие в Прибамбасск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сопроводи меня и Дадангу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите Петру и Дадангу.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сопроводить Петру и Дадангу!',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Петре Гроссен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3901,'Kill 8 Rattlecage Skeletons.','Значит, тебе все же удалось!.. Отлично, с течением времени нам требуется все больше разбойников. Тенеловы, возможно, захотят отыскать тебя, когда решат, что настал нужный момент, так что не пропадай и не делай ничего такого, о чем мог бы потом пожалеть. Им нужны способные агенты... а не жалкие карманники и дураки.','Вернитесь к жрецу Тени Сарвису в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Kill 8 Rattlecage Skeletons.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Значит, тебе все же удалось!.. Отлично, с течением времени нам требуется все больше разбойников. Тенеловы, возможно, захотят отыскать тебя, когда решат, что настал нужный момент, так что не пропадай и не делай ничего такого, о чем мог бы потом пожалеть. Им нужны способные агенты... а не жалкие карманники и дураки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрецу Тени Сарвису в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3902,'Удалось ли тебе найти что-нибудь стоящее? Нет ничего постыдного в повторном использовании выброшенных вещей. Никто не станет ничего давать нам – мы, Отрекшиеся, сами себя обеспечим!','Вернитесь к стражу смерти Салтену в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе найти что-нибудь стоящее? Нет ничего постыдного в повторном использовании выброшенных вещей. Никто не станет ничего давать нам – мы, Отрекшиеся, сами себя обеспечим!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу смерти Салтену в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3903,'Милли Осворт','Ты $Gпоказал:показала; себя $Gнадежным:надежной:c; |3-6($c), $n. Да и тяжелой работы не боишься, не правда ли?$B$BУ меня есть подруга, Милли Осворт. У нее какие-то проблемы. Она вместе со своим фургоном находится по другую сторону аббатства, у стойл. Думаю, ей очень пригодится твоя помощь.','Поговорите с Милли Осворт.','О, заместитель судьи Виллем просил тебя поговорить со мной? Он отважный $r и всегда готов помочь, но дела не дают ему покинуть Аббатство Североземья, да к тому же, боюсь, нынешняя моя проблема ему не по плечу. Возможно, ты мне поможешь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Милли Осворт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gпоказал:показала; себя $Gнадежным:надежной:c; |3-6($c), $n. Да и тяжелой работы не боишься, не правда ли?$B$BУ меня есть подруга, Милли Осворт. У нее какие-то проблемы. Она вместе со своим фургоном находится по другую сторону аббатства, у стойл. Думаю, ей очень пригодится твоя помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Милли Осворт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, заместитель судьи Виллем просил тебя поговорить со мной? Он отважный $r и всегда готов помочь, но дела не дают ему покинуть Аббатство Североземья, да к тому же, боюсь, нынешняя моя проблема ему не по плечу. Возможно, ты мне поможешь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (3904,'Урожай Милли','Шайка бандитов, это Братство Справедливости, проникла в Виноградники Североземья во время сбора урожая! Я сообщила об этом стражникам, и они заверили меня, что разберутся с этим делом, но... я боюсь за виноград! Если мой урожай не украдут грабители, так наши стражники потопчут!$B$BПрошу тебя, помоги мне! Я собрала большую часть винограда в корзины, но оставила их в виноградниках на юго-востоке.$B$BПринеси мне мой виноград, пожалуйста!','Принесите 8 корзин с виноградом Милли Осворт в Аббатство Североземья.','Вернитесь к Милли Осворт в Долину Североземья, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урожай Милли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Шайка бандитов, это Братство Справедливости, проникла в Виноградники Североземья во время сбора урожая! Я сообщила об этом стражникам, и они заверили меня, что разберутся с этим делом, но... я боюсь за виноград! Если мой урожай не украдут грабители, так наши стражники потопчут!$B$BПрошу тебя, помоги мне! Я собрала большую часть винограда в корзины, но оставила их в виноградниках на юго-востоке.$B$BПринеси мне мой виноград, пожалуйста!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 корзин с виноградом Милли Осворт в Аббатство Североземья.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Милли Осворт в Долину Североземья, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3905,'Извещение о получении партии винограда','Теперь, когда мой урожай спасен, отнеси это извещение о получении партии винограда брату Нилзу. Он ведает съестными припасами в Североземье, и я уверена, что он обрадуется, узнав, что у него будет свежий виноград.$B$BБрата Нилза ты найдешь в аббатстве, в звоннице – он там любит... дегустировать вино.','Отнесите извещение о получении партии винограда брату Нилзу в Аббатство Североземья.','Так, что у нас тут...$B$BХвала Свету! Виноград Милли спасен! Когда она сказала мне, что эти бандиты разнесли ее виноградники, я чуть не впал в уныние, но моя вера в Свет не дрогнула!$B$BИ благодаря твоей отваге теперь у нас есть виноград для вина! Да хранит тебя Свет, $n!','Сдается мне, ты в хорошем настроении! Сядь, отдохни тут немножко. Хочешь вина?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Извещение о получении партии винограда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мой урожай спасен, отнеси это извещение о получении партии винограда брату Нилзу. Он ведает съестными припасами в Североземье, и я уверена, что он обрадуется, узнав, что у него будет свежий виноград.$B$BБрата Нилза ты найдешь в аббатстве, в звоннице – он там любит... дегустировать вино.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите извещение о получении партии винограда брату Нилзу в Аббатство Североземья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, что у нас тут...$B$BХвала Свету! Виноград Милли спасен! Когда она сказала мне, что эти бандиты разнесли ее виноградники, я чуть не впал в уныние, но моя вера в Свет не дрогнула!$B$BИ благодаря твоей отваге теперь у нас есть виноград для вина! Да хранит тебя Свет, $n!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сдается мне, ты в хорошем настроении! Сядь, отдохни тут немножко. Хочешь вина?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3906,'Дисгармония пламени','Старейшины говорят, духи стихий в последнее время неспокойны. Дворфы Черного Железа вызвали в наш мир злобного духа, и теперь он угрожает вечной засухой нашим землям. Мы должны найти причину беспокойства духов. $B$BОтправляйся к Черной горе, через пропасть Пламени, прямо в карьер. Найди там владыку огня – Подчинителя Пирона – и положи конец его злодеяниям!','Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду.','Не может быть... Не может быть! Уничтожение Пирона лишь приоткрыло завесу над истинным положением вещей. В глубинах Черной горы скрываются еще более коварные силы.','Духи стихий все еще пребывают в беспокойстве, $N?','Вернитесь к Громосерду в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дисгармония пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старейшины говорят, духи стихий в последнее время неспокойны. Дворфы Черного Железа вызвали в наш мир злобного духа, и теперь он угрожает вечной засухой нашим землям. Мы должны найти причину беспокойства духов. $B$BОтправляйся к Черной горе, через пропасть Пламени, прямо в карьер. Найди там владыку огня – Подчинителя Пирона – и положи конец его злодеяниям!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь в карьер у Черной горы и уничтожьте Подчинителя Пирона. По выполнению вернитесь к Громосерду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не может быть... Не может быть! Уничтожение Пирона лишь приоткрыло завесу над истинным положением вещей. В глубинах Черной горы скрываются еще более коварные силы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Духи стихий все еще пребывают в беспокойстве, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Громосерду в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3907,'Дисгармония пламени','Я чувствую скверну в воздухе, $n! Источник ее скрывается в глубинах Черной горы. $B$BИмя его в стонах земли и ветра: лорд Опалитель... Но это еще не все: кто-то или что-то повелевает им. Сам он – лишь инструмент в более могущественных руках. $B$BНайди его и выясни, где скрывается его повелитель. Возвращайся ко мне, когда все разузнаешь.','Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию.','<Громосерд хватает табличку Каринья>$B$BРагнарос... здесь...$B$BСтарейшины были правы, страшась зла, исходящего от Черной горы. Могущественный служитель Древних Богов! В НАШЕМ МИРЕ! Мы должны оценить наши позиции здесь, в Каргате. Нужно решить, стоит ли остаться и драться или бежать в страхе перед новым Расколом.$B$BЛучше больше не приближайся к Черной горе, $N. В ее глубинах кроется куда более великое зло, чем все, что встречалось тебе раньше.','Вскоре пламя поглотит эти земли. Торопись, $N!','Вернитесь к Громосерду в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дисгармония пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я чувствую скверну в воздухе, $n! Источник ее скрывается в глубинах Черной горы. $B$BИмя его в стонах земли и ветра: лорд Опалитель... Но это еще не все: кто-то или что-то повелевает им. Сам он – лишь инструмент в более могущественных руках. $B$BНайди его и выясни, где скрывается его повелитель. Возвращайся ко мне, когда все разузнаешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ступайте в глубины Черной горы и выследите лорда Опалителя. Убейте его и принесите Громосерду все, что может дать какую-то информацию.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Громосерд хватает табличку Каринья>$B$BРагнарос... здесь...$B$BСтарейшины были правы, страшась зла, исходящего от Черной горы. Могущественный служитель Древних Богов! В НАШЕМ МИРЕ! Мы должны оценить наши позиции здесь, в Каргате. Нужно решить, стоит ли остаться и драться или бежать в страхе перед новым Расколом.$B$BЛучше больше не приближайся к Черной горе, $N. В ее глубинах кроется куда более великое зло, чем все, что встречалось тебе раньше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вскоре пламя поглотит эти земли. Торопись, $N!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Громосерду в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3908,'Тайна, покрытая мраком','Видишь ли, я совершенно не представляю, как здесь оказался – просто тайна, покрытая мраком! Мне кажется, я вообще ничего не помню...$B$BЭти вещи все же кажутся мне знакомыми... $B$BМой меч. Я должен был как-то укрепить его, но совершенно не помню зачем? Мне жаль, что не могу сказать тебе больше, но я и в самом деле ничего не помню. $B$BВ любом случае, я знаю куда это отнести – к Донове Снегоноре в Зимние Ключи. Она может закалить меч в местных горячих источниках.','Отнесите меч Линкена Донове Снегоноре.','Ну конечно, я могу закалить меч. А пока я работаю, расскажи мне, что так задержало Линкена. Обычно он не забывает о важных вещах.','Ого! Неужели Линкен наконец-то собрался прислать мне свой меч?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна, покрытая мраком',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь ли, я совершенно не представляю, как здесь оказался – просто тайна, покрытая мраком! Мне кажется, я вообще ничего не помню...$B$BЭти вещи все же кажутся мне знакомыми... $B$BМой меч. Я должен был как-то укрепить его, но совершенно не помню зачем? Мне жаль, что не могу сказать тебе больше, но я и в самом деле ничего не помню. $B$BВ любом случае, я знаю куда это отнести – к Донове Снегоноре в Зимние Ключи. Она может закалить меч в местных горячих источниках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите меч Линкена Донове Снегоноре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну конечно, я могу закалить меч. А пока я работаю, расскажи мне, что так задержало Линкена. Обычно он не забывает о важных вещах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ого! Неужели Линкен наконец-то собрался прислать мне свой меч?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3909,'Эликсир Видере','Что такое? Линкен ЗАБЫЛ ВСЕ? $B$BЯсно, потеря памяти... $B$BВот его меч. Он не закончен. Я знаю, кто может закончить его, но... поговорить с ним – непростая задача. $B$BОднако я знаю, кто сможет тебе помочь. Не буду сейчас вдаваться в подробности, скажу только, что тебе необходимо любым способом заполучить эликсир Видере. Единственный, кто может помочь тебе в этом – Греган Пивоплюй. Его нелегко отыскать, но говорят, что недавно его видели в лесах Фераласа.','Найдите Грегана Пивоплюя на севере Фераласа. Выясните у него, как получить эликсир Видере, и вернитесь к Донове Снегоноре.','Мне нужна одна склянка эликсира, чтобы проверить, правильный ли это состав... Да, это он.','Уже $Gвернулся:вернулась;?','Вернитесь к Донове Снегоноре в Зимние Ключи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир Видере',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что такое? Линкен ЗАБЫЛ ВСЕ? $B$BЯсно, потеря памяти... $B$BВот его меч. Он не закончен. Я знаю, кто может закончить его, но... поговорить с ним – непростая задача. $B$BОднако я знаю, кто сможет тебе помочь. Не буду сейчас вдаваться в подробности, скажу только, что тебе необходимо любым способом заполучить эликсир Видере. Единственный, кто может помочь тебе в этом – Греган Пивоплюй. Его нелегко отыскать, но говорят, что недавно его видели в лесах Фераласа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Грегана Пивоплюя на севере Фераласа. Выясните у него, как получить эликсир Видере, и вернитесь к Донове Снегоноре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне нужна одна склянка эликсира, чтобы проверить, правильный ли это состав... Да, это он.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уже $Gвернулся:вернулась;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Донове Снегоноре в Зимние Ключи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (3910,'<NYI> <TXT> Вылазка в Ун\'Горо','Добро пожаловать в Прибамбасск! Отведи нас домой...','Сопроводите Петру и Дадангу в Ун\'Горо.','Проводить Петру и Дадангу!','Вернитесь к Петре Гроссен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> Вылазка в Ун\'Горо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в Прибамбасск! Отведи нас домой...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите Петру и Дадангу в Ун\'Горо.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводить Петру и Дадангу!',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Петре Гроссен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3911,'Последний элемент','У меня есть работа для тех, кто не боится сунуться в глубины, $n! $B$BКлан Черного Железа научился создавать чрезвычайно мощных големов. $B$BИсходя из отчетов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу. $B$BПодумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют... Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без нее можешь не возвращаться! По усердию и награда.','Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности стихий. Стоит начать поиски с големов и их создателей. Вивиан Лягроб также бормотала что-то про элементалей.','Замечательно! Я немедленно отправлю их курьером в Подгород!$B$BДля вас - оплата, как и было обещано.','Покажи мне их!','Вернитесь к темному магу Вивиане Лягроб к скелету Апокрифана, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний элемент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть работа для тех, кто не боится сунуться в глубины, $n! $B$BКлан Черного Железа научился создавать чрезвычайно мощных големов. $B$BИсходя из отчетов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу. $B$BПодумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют... Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без нее можешь не возвращаться! По усердию и награда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности стихий. Стоит начать поиски с големов и их создателей. Вивиан Лягроб также бормотала что-то про элементалей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Я немедленно отправлю их курьером в Подгород!$B$BДля вас - оплата, как и было обещано.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Покажи мне их!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному магу Вивиане Лягроб к скелету Апокрифана, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3912,'Встречаемся на кладбище','Этот эликсир позволит тебе говорить с существами, которые обычно незримы. $B$BВозьми эликсир Видере и меч Линкена и отправляйся на кладбище на окраине Прибамбасска в Танарисе. Будешь на месте, выпей эликсир. Результат может показаться тебе неожиданным, но не впадай в панику. $B$BВ том обличье, которое ты примешь, отправляйся на север, в горы. Тот, кто тебе нужен, скрывается в скалистых ущельях. Его имя Гаэриан. $B$BПомни, ты сможешь поговорить с ним только переменив облик...','Отправляйтесь на кладбище на окраине Прибамбасска и выпейте там эликсир Видере. Далее, следуя инструкциям Доновы, найдите Гаэриана.','Давненько никто не говорил со мной...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встречаемся на кладбище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот эликсир позволит тебе говорить с существами, которые обычно незримы. $B$BВозьми эликсир Видере и меч Линкена и отправляйся на кладбище на окраине Прибамбасска в Танарисе. Будешь на месте, выпей эликсир. Результат может показаться тебе неожиданным, но не впадай в панику. $B$BВ том обличье, которое ты примешь, отправляйся на север, в горы. Тот, кто тебе нужен, скрывается в скалистых ущельях. Его имя Гаэриан. $B$BПомни, ты сможешь поговорить с ним только переменив облик...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на кладбище на окраине Прибамбасска и выпейте там эликсир Видере. Далее, следуя инструкциям Доновы, найдите Гаэриана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давненько никто не говорил со мной...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3913,'Замогильная история','Когда вернешься на кладбище, $n, увидишь там могильный камень, стоящий особняком. Под ним скрываются многие секреты! $B$BОтодвинь его, и тайны откроются тебе!','Воскресните, найдите могильный камень, о котором говорил Гаэриан.','Камень отодвинут в сторону, под ним находится небольшое углубление. Положив в него меч Линкена, вы понимаете, что меч идеально ложится туда.','Похоже, это тот самый камень, о котором говорил Гаэриан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Замогильная история',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда вернешься на кладбище, $n, увидишь там могильный камень, стоящий особняком. Под ним скрываются многие секреты! $B$BОтодвинь его, и тайны откроются тебе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воскресните, найдите могильный камень, о котором говорил Гаэриан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Камень отодвинут в сторону, под ним находится небольшое углубление. Положив в него меч Линкена, вы понимаете, что меч идеально ложится туда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, это тот самый камень, о котором говорил Гаэриан.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3914,'Меч Линкена','Вокруг меча вспыхивает ослепительно яркое пламя. После того как оно угасло, вы можете снова взять меч. Он изменился!','Доставьте превосходный меч Линкена Линкену в Кратер Ун\'Горо.','Мой меч, он закончен!$B$BВспомнить бы еще, на что он мне сдался...$B$BДай-ка я пока заплачу тебе за работу.','О! Твое лицо мне знакомо! Постой, я угадаю!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меч Линкена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вокруг меча вспыхивает ослепительно яркое пламя. После того как оно угасло, вы можете снова взять меч. Он изменился!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте превосходный меч Линкена Линкену в Кратер Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой меч, он закончен!$B$BВспомнить бы еще, на что он мне сдался...$B$BДай-ка я пока заплачу тебе за работу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О! Твое лицо мне знакомо! Постой, я угадаю!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3921,'Венаки Бенике','Похоже, я тут немного напортачил – один из нагрузочных флюксоров, кажется, попал под спицы дерегуляторного привода. Такое несложно починить. Я знаю одного спеца по поршневым приводам трехкратного расширения, который с радостью займется починкой. Отнеси сломанный самофланж Венаки Бенике, которая живет к югу от заставы Мор\'шан – она его в три счета подлатает. $B$BТебе даже не придется идти пешком! Я как раз хотел протестировать свое новое телепортирующее устройство...','Отнесите разбитый самофланж Венаки Бенике. Обратитесь к Браку, чтобы он телепортировал вас прямо к ней.','Что это? Самофланж, говоришь? Что такое самофланж??\n\nА... Посмотри, как он вибрирует, когда берешь его в руки. А внутри жужжат сложные шестеренки. Ух ты! Мне хочется починить его и узнать, зачем он тебе?','Я очень занята, |3-6($C). Если ты пришел не по важному делу, иди своей дорогой...','Отнесите разбитый и сломанный самофланж Венаки Бенике в Северные Степи. Поговорите с Браком, чтобы телепортироваться прямо к ней.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Венаки Бенике',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, я тут немного напортачил – один из нагрузочных флюксоров, кажется, попал под спицы дерегуляторного привода. Такое несложно починить. Я знаю одного спеца по поршневым приводам трехкратного расширения, который с радостью займется починкой. Отнеси сломанный самофланж Венаки Бенике, которая живет к югу от заставы Мор\'шан – она его в три счета подлатает. $B$BТебе даже не придется идти пешком! Я как раз хотел протестировать свое новое телепортирующее устройство...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите разбитый самофланж Венаки Бенике. Обратитесь к Браку, чтобы он телепортировал вас прямо к ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Самофланж, говоришь? Что такое самофланж??\n\nА... Посмотри, как он вибрирует, когда берешь его в руки. А внутри жужжат сложные шестеренки. Ух ты! Мне хочется починить его и узнать, зачем он тебе?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я очень занята, |3-6($C). Если ты пришел не по важному делу, иди своей дорогой...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите разбитый и сломанный самофланж Венаки Бенике в Северные Степи. Поговорите с Браком, чтобы телепортироваться прямо к ней.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (3922,'Металлические заготовки','Я хочу починить этот самофланж, но для этого мне понадобятся некоторые запчасти. У меня кончились семнадцати с половиной миллиметровые заготовки для деталей, а для работы таких понадобится целая куча.$B$BБлижайшие места, где их можно достать – это исследовательская станция неподалеку отсюда и Нефтяное болото на востоке. Торговая Компания обычно хранит их в ведрах с инструментами. Ступай в одно из этих мест и поищи эти штуковины, а потом возвращайся, когда наберешь достаточно.','Соберите 10 металлических заготовок для деталей вокруг Нефтяного болота.','О, ты принес их! Теперь я могу приступить к работе...','Принесите металлические заготовки Венаки Бенике в Северные Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Металлические заготовки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу починить этот самофланж, но для этого мне понадобятся некоторые запчасти. У меня кончились семнадцати с половиной миллиметровые заготовки для деталей, а для работы таких понадобится целая куча.$B$BБлижайшие места, где их можно достать – это исследовательская станция неподалеку отсюда и Нефтяное болото на востоке. Торговая Компания обычно хранит их в ведрах с инструментами. Ступай в одно из этих мест и поищи эти штуковины, а потом возвращайся, когда наберешь достаточно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 металлических заготовок для деталей вокруг Нефтяного болота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, ты принес их! Теперь я могу приступить к работе...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите металлические заготовки Венаки Бенике в Северные Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3923,'[DEPRECATED] Рилли Грязегоб','Увы, у меня ничего не вышло. Я добавила в самофланж несколько новых индикаторов, чтобы проверить его структурную целостность, и согласно им, структурная целостность на нуле. Я могу добавить пару циферблатов и рычаг-другой, но... Думаю, станет только хуже.$B$BОтнеси самофланж Рилли Грязегобу. Он работал на Торговую Компанию, и уж если Рилли не сможет починить эту штуку, то пиши пропало.$B$BОн работает в механической мастерской Ногга в Оргриммаре, на Аллее Чести.','Отнесите разбитый и сломанный самофланж Рилли Грязегобу в Оргриммар.','Что это? Надо же, самофланж. Откуда он у тебя? Неужели ты рыскал по владениям Торговой Компании в Степях?\n\nИнтересно, это говорит о смелости или о глупости?','Осторожно! Голову береги! Не стой под стрелой!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED] Рилли Грязегоб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Увы, у меня ничего не вышло. Я добавила в самофланж несколько новых индикаторов, чтобы проверить его структурную целостность, и согласно им, структурная целостность на нуле. Я могу добавить пару циферблатов и рычаг-другой, но... Думаю, станет только хуже.$B$BОтнеси самофланж Рилли Грязегобу. Он работал на Торговую Компанию, и уж если Рилли не сможет починить эту штуку, то пиши пропало.$B$BОн работает в механической мастерской Ногга в Оргриммаре, на Аллее Чести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите разбитый и сломанный самофланж Рилли Грязегобу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Надо же, самофланж. Откуда он у тебя? Неужели ты рыскал по владениям Торговой Компании в Степях?\n\nИнтересно, это говорит о смелости или о глупости?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Осторожно! Голову береги! Не стой под стрелой!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3924,'[DEPRECATED]Руководство по самофланжу','Думаю, я смогу починить самофланж, но для этого мне понадобится руководство пользователя. В Торговой Компании у меня был соперник, начальник Медноклин. Он ревностно хранил тайны самофланжа и лишь частицы знания доверял самым надежным своим сторонникам. Я не входил в число избранных...$B$BНачальник Медноклин работает в северо-восточной части Степей, на Каменном карьере.','Отнесите руководство по самофланжу Рилли Грязегобу в Оргриммар.','Ты принес руководство! Мне не терпится узнать, как починить самофланж! Я говорил с Пароклапаном из Кабестана, и он просил поблагодарить тебя за услуги и вознаградить за них.\n\nЯ тоже весьма признателен, и если починю-таки эту штуку, сразу тебе сообщу...','Где руководство?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Руководство по самофланжу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, я смогу починить самофланж, но для этого мне понадобится руководство пользователя. В Торговой Компании у меня был соперник, начальник Медноклин. Он ревностно хранил тайны самофланжа и лишь частицы знания доверял самым надежным своим сторонникам. Я не входил в число избранных...$B$BНачальник Медноклин работает в северо-восточной части Степей, на Каменном карьере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите руководство по самофланжу Рилли Грязегобу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты принес руководство! Мне не терпится узнать, как починить самофланж! Я говорил с Пароклапаном из Кабестана, и он просил поблагодарить тебя за услуги и вознаградить за них.\n\nЯ тоже весьма признателен, и если починю-таки эту штуку, сразу тебе сообщу...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где руководство?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3941,'Помощь гномов','Думай, голова! Думай, шапку подарю... Я помню, что явился сюда с какой-то очень серьезной целью. Но совсем не помню с какой!$B$BЕсть идея, $n! Вон там, в пещерах живет гномесса по имени Джей Ди, я помню, она была очень добра ко мне, когда я впервые оказался здесь. Может, она сможет что-то рассказать. $B$BСпроси ее! Только осторожней, она все время возится с этими ужасными светящимися кристаллами, которых полно в этом кратере. Не знаю, зачем уж он ей нужны...','Найдите Джей Ди Колли в Укрытии Маршалла.','Стой на месте, не шевелись... Я испытываю новую комбинацию кристаллов...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь гномов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думай, голова! Думай, шапку подарю... Я помню, что явился сюда с какой-то очень серьезной целью. Но совсем не помню с какой!$B$BЕсть идея, $n! Вон там, в пещерах живет гномесса по имени Джей Ди, я помню, она была очень добра ко мне, когда я впервые оказался здесь. Может, она сможет что-то рассказать. $B$BСпроси ее! Только осторожней, она все время возится с этими ужасными светящимися кристаллами, которых полно в этом кратере. Не знаю, зачем уж он ей нужны...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Джей Ди Колли в Укрытии Маршалла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стой на месте, не шевелись... Я испытываю новую комбинацию кристаллов...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3942,'Память Линкена','О, Линкен? Да, смешной парень... Когда он впервые оказался здесь, бормотал всякую ерунду. Наверное, кто-то как следует двинул бедняге по голове! $B$BОднако кое-что из той чепухи, которую он нес, крепко засело у меня в памяти. Помню, он говорил, что делает какой-то тотем, и что ему необходимо поговорить с какой-то Эриданой Грустью Ветра... кажется, в месте, называемом Оскверненный лес. Думаю, если хочешь узнать больше, тебе следует отправиться прямиком к этой Эридане.','Найдите Эридану Грусть Ветра на юге Оскверненного леса.','Приветствую тебя, |3-6($C). Могу ли я чем-то помочь тебе?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Память Линкена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, Линкен? Да, смешной парень... Когда он впервые оказался здесь, бормотал всякую ерунду. Наверное, кто-то как следует двинул бедняге по голове! $B$BОднако кое-что из той чепухи, которую он нес, крепко засело у меня в памяти. Помню, он говорил, что делает какой-то тотем, и что ему необходимо поговорить с какой-то Эриданой Грустью Ветра... кажется, в месте, называемом Оскверненный лес. Думаю, если хочешь узнать больше, тебе следует отправиться прямиком к этой Эридане.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Эридану Грусть Ветра на юге Оскверненного леса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую тебя, |3-6($C). Могу ли я чем-то помочь тебе?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (3961,'Приключения Линкена','Лично я полагаю, что Линкен явился сюда, чтобы избавить нас от Яропламеня... Он кажется простым парнем, однако он совсем не интересуется моими экспериментами и механизмами, как большинство гномов. Должно быть, в глубине души он истинный воин. $B$BОтдай тотем ему. Возможно, это поможет ему вспомнить, зачем он пришел сюда.','Отнесите серебряный тотем Аквамонтоса Линкену в Укрытие Маршалла.','Джей Ди вообще хоть чем-нибудь помогла тебе?','О, привет, $N!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приключения Линкена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лично я полагаю, что Линкен явился сюда, чтобы избавить нас от Яропламеня... Он кажется простым парнем, однако он совсем не интересуется моими экспериментами и механизмами, как большинство гномов. Должно быть, в глубине души он истинный воин. $B$BОтдай тотем ему. Возможно, это поможет ему вспомнить, зачем он пришел сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите серебряный тотем Аквамонтоса Линкену в Укрытие Маршалла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Джей Ди вообще хоть чем-нибудь помогла тебе?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, привет, $N!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (3962,'Один в поле не воин','$n, я наконец-то вспомнил... Я пришел сюда, чтобы сразиться с Яропламенем! Это и есть цель моего путешествия! $B$BНо я больше не герой... потому что герой стоит передо мной. Теперь ты $gдолжен:должна; закончить начатое. $B$BЯропламень стережет артефакт, именуемый Золотым пламенем. В нем кроется сила более мощная, чем что-либо мне известное, поэтому этот артефакт не должен попасть в дурные руки.$B$BИ мой тебе совет – не ходи $gодин:одна;. Один в поле не воин.','Отправляйтесь к Вулкану Огненного Венца, к югу от Укрытия Маршалла. $B$BНайдите Яропламеня и разрушьте его защитную ауру с помощью тотема. Когда дух будет сражен, заберите из пещеры Золотое пламя.','Спасибо, $N.$B$BТеперь Золотое пламя будет возвращено на мою родину, где мы сможем защитить его от посягающих на него негодяев.$B$BЕсли бы не ты, я до сих пор не помнил бы, кто я такой и зачем пришел! Я хочу отблагодарить тебя!$B$BБери все что нравится!','Яропламень почти неуязвим благодаря защитной ауре, создаваемой Золотым пламенем. Только тебе под силу разрушить ауру с помощью серебряного тотема Аквамонтоса.','Вернитесь к Линкену в Укрытие Маршалла, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Один в поле не воин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я наконец-то вспомнил... Я пришел сюда, чтобы сразиться с Яропламенем! Это и есть цель моего путешествия! $B$BНо я больше не герой... потому что герой стоит передо мной. Теперь ты $gдолжен:должна; закончить начатое. $B$BЯропламень стережет артефакт, именуемый Золотым пламенем. В нем кроется сила более мощная, чем что-либо мне известное, поэтому этот артефакт не должен попасть в дурные руки.$B$BИ мой тебе совет – не ходи $gодин:одна;. Один в поле не воин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Вулкану Огненного Венца, к югу от Укрытия Маршалла. $B$BНайдите Яропламеня и разрушьте его защитную ауру с помощью тотема. Когда дух будет сражен, заберите из пещеры Золотое пламя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N.$B$BТеперь Золотое пламя будет возвращено на мою родину, где мы сможем защитить его от посягающих на него негодяев.$B$BЕсли бы не ты, я до сих пор не помнил бы, кто я такой и зачем пришел! Я хочу отблагодарить тебя!$B$BБери все что нравится!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Яропламень почти неуязвим благодаря защитной ауре, создаваемой Золотым пламенем. Только тебе под силу разрушить ауру с помощью серебряного тотема Аквамонтоса.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Линкену в Укрытие Маршалла, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (3981,'Командир Гор\'шак','Бедняга Гаргал... Он даже не успел ничего понять как – бац! – стрела вонзилась прямо ему в башку... Он и прежде гением не был, а теперь уж... $B$B*Гэлмав скорбно морщится.* $B$BКогда мы вытащили стрелу, заметили записку, прикрученную к древку. В ней не было ничего, кроме грубо нацарапанной картинки, изображающей, видимо, орка за решеткой, и подписи командира Гор\'шака. $B$BЕсли он еще жив и находится в Глубинах, ты $gдолжен:должна; отыскать его. $B$BЛовушка? Проклятье, какая еще ловушка, что ты несешь?! Отправляйся немедленно!','Найдите командира Гор\'шака в Глубинах Черной горы. $B$BСудя по рисунку в записке, искать следует в темнице где-то вроде того.','У нас мало времени. Слушай внимательно, |3-6($R). Сведения, которые я сообщу тебе, совершенно секретны и не подлежат разглашению.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Командир Гор\'шак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бедняга Гаргал... Он даже не успел ничего понять как – бац! – стрела вонзилась прямо ему в башку... Он и прежде гением не был, а теперь уж... $B$B*Гэлмав скорбно морщится.* $B$BКогда мы вытащили стрелу, заметили записку, прикрученную к древку. В ней не было ничего, кроме грубо нацарапанной картинки, изображающей, видимо, орка за решеткой, и подписи командира Гор\'шака. $B$BЕсли он еще жив и находится в Глубинах, ты $gдолжен:должна; отыскать его. $B$BЛовушка? Проклятье, какая еще ловушка, что ты несешь?! Отправляйся немедленно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите командира Гор\'шака в Глубинах Черной горы. $B$BСудя по рисунку в записке, искать следует в темнице где-то вроде того.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У нас мало времени. Слушай внимательно, |3-6($R). Сведения, которые я сообщу тебе, совершенно секретны и не подлежат разглашению.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (3982,'Что происходит?','Меня прислал сюда Тралл, и я нахожусь под его покровительством. Неужели ты думаешь, что эти фигляры смогли бы меня поймать? Я разведчик, и я им поддался специально, чтобы собрать информацию.$B$B*Гор\'шак понижает голос.*$B$BИмператор Тауриссан похитил принцессу Стальгорна. Она сейчас здесь, в этом городе! Надо думать, когда старый Магни об этом узнал, его чуть удар не хватил.$B$B*Гор\'шак смеется.*$B$BТихо! Слышишь? Это стражники! ЗАЩИЩАЙСЯ!','Защитите Гор\'шака.','На этот раз все обошлось. Но теперь они поднимут тревогу... и пришлют за тобой еще стражников.','Защищайся, $Gпридурок:дура;!','Вступите в схватку со стражниками и останьтесь в живых.','Вернитесь к командиру Гор\'шаку в Глубины Черной горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что происходит?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня прислал сюда Тралл, и я нахожусь под его покровительством. Неужели ты думаешь, что эти фигляры смогли бы меня поймать? Я разведчик, и я им поддался специально, чтобы собрать информацию.$B$B*Гор\'шак понижает голос.*$B$BИмператор Тауриссан похитил принцессу Стальгорна. Она сейчас здесь, в этом городе! Надо думать, когда старый Магни об этом узнал, его чуть удар не хватил.$B$B*Гор\'шак смеется.*$B$BТихо! Слышишь? Это стражники! ЗАЩИЩАЙСЯ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите Гор\'шака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На этот раз все обошлось. Но теперь они поднимут тревогу... и пришлют за тобой еще стражников.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Защищайся, $Gпридурок:дура;!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Вступите в схватку со стражниками и останьтесь в живых.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Гор\'шаку в Глубины Черной горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4001,'Что происходит?','Пока что мне не удалось толком поговорить с Караном из темницы напротив. Однако я все-таки смог убедить его в том, что я – то есть мы – не обидим его и не сделаем ему ничего плохого.$B$BПоговори с ним и попробуй узнать о принцессе и ее похитителях. Всю информацию, которую удастся собрать, передай вождю.$B$BТралл не хочет, чтобы с принцессой что-то случилось. У него даже есть план, как вернуть ее в целости и сохранности в Стальгорн, и Карану все это уже известно... Иди!','Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар.$B$BВы вспоминаете слова Гор\'шака о том, что Карана держат в темнице напротив.','Сейчас у Орды есть шанс изменить политическую ситуацию в нашем мире, истерзанном войной. Причем изменить радикально. Раз и навсегда. Слушай внимательно, $N.$B$BПостарайся, чтобы все получилось. Провал в этом деле смерти подобен.','Что привело тебя в это мрачное место?','Информация, полученная от Карана','Вернитесь к Траллу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что происходит?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока что мне не удалось толком поговорить с Караном из темницы напротив. Однако я все-таки смог убедить его в том, что я – то есть мы – не обидим его и не сделаем ему ничего плохого.$B$BПоговори с ним и попробуй узнать о принцессе и ее похитителях. Всю информацию, которую удастся собрать, передай вождю.$B$BТралл не хочет, чтобы с принцессой что-то случилось. У него даже есть план, как вернуть ее в целости и сохранности в Стальгорн, и Карану все это уже известно... Иди!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с дворфом по имени Каран Могучий Молот и соберите информацию о похищении принцессы Мойры Бронзобород. Передайте информацию Траллу в Оргриммар.$B$BВы вспоминаете слова Гор\'шака о том, что Карана держат в темнице напротив.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сейчас у Орды есть шанс изменить политическую ситуацию в нашем мире, истерзанном войной. Причем изменить радикально. Раз и навсегда. Слушай внимательно, $N.$B$BПостарайся, чтобы все получилось. Провал в этом деле смерти подобен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело тебя в это мрачное место?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Информация, полученная от Карана',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4002,'Восточные королевства','Принесенные тобой сведения чрезвычайно ценны, $n.$b$bЯ – вождь, и мой долг – действовать на благо Орды, так, чтобы грядущие поколения не были обречены на безнадежное прозябание!$b$bИ вот нам выпала возможность определить судьбу будущих союзов. Выступив на помощь дворфам, мы значительно укрепим свои взаимоотношения с Восточными королевствами. Вот почему твой долг – вернуться с победой!$b$b$gГотов:Готова; ли ты?','Поговорите с Траллом.','Все, $N. Отныне пути назад нет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восточные королевства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принесенные тобой сведения чрезвычайно ценны, $n.$b$bЯ – вождь, и мой долг – действовать на благо Орды, так, чтобы грядущие поколения не были обречены на безнадежное прозябание!$b$bИ вот нам выпала возможность определить судьбу будущих союзов. Выступив на помощь дворфам, мы значительно укрепим свои взаимоотношения с Восточными королевствами. Вот почему твой долг – вернуться с победой!$b$b$gГотов:Готова; ли ты?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Траллом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все, $N. Отныне пути назад нет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4003,'Спасение принцессы','Этот удар, нанесенный дворфам Черного Железа, способен потрясти их королевство до основания.$b$bПринцесса находится под контролем императора Тауриссана. Чтобы ее освободить, необходимо убить императора. Имей в виду, твоя задача вдвойне опасна: пока принцесса находится во власти императора, она нападет на тебя, не раздумывая.$b$bНи в коем случае не причиняй ей вреда!!!','Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия.','<Принцесса Мойра в страхе съеживается.>','Вернитесь к принцессе Мойре Бронзобород в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение принцессы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот удар, нанесенный дворфам Черного Железа, способен потрясти их королевство до основания.$b$bПринцесса находится под контролем императора Тауриссана. Чтобы ее освободить, необходимо убить императора. Имей в виду, твоя задача вдвойне опасна: пока принцесса находится во власти императора, она нападет на тебя, не раздумывая.$b$bНи в коем случае не причиняй ей вреда!!!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте императора Даграна Тауриссана и освободите принцессу Мойру Бронзобород от его черного заклятия.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Принцесса Мойра в страхе съеживается.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцессе Мойре Бронзобород в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4004,'Спасенная принцесса','Ты $gубил:убила; моего мужа, |3-6($r)! Мой ребенок родится на свет без отца!$B$B*Принцесса Мойра указывает на вас.*$B$BИстинно говорю тебе, это дитя станет следующим королем Стальгорна. И тогда берегись! Этим преступным деянием ты $gнавлек:навлекла; на себя проклятие. Возмездие настигнет тебя и твой род. Всех вас будут травить до скончания дней!$B$B*Вы уверены, что принцесса Мойра до сих пор пребывает под действием чар Тауриссана.*$B$BОставь меня, |3-6($r). Поторопись к своему нанимателю. Наверняка он с нетерпением ждет вестей об исполнении его гнусных замыслов.','Вернитесь к Траллу в крепость Громмаш, что в Оргриммаре.','<Тралл поражен вашим рассказом. Он явно не ожидал ничего подобного.>$B$BСтало быть, надо ждать новой угрозы. Магни уже немолод, кто знает, сколько ему осталось. А если Магни не станет, дорога к трону Стальгорна будет открыта для еще не рожденного отпрыска Черного Железа.$B$BТы $Gисполнил:исполнила; мое поручение и получишь награду.$B$BА теперь оставь меня, $N! Мне надо посовещаться с Сильваной и Кэрном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасенная принцесса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gубил:убила; моего мужа, |3-6($r)! Мой ребенок родится на свет без отца!$B$B*Принцесса Мойра указывает на вас.*$B$BИстинно говорю тебе, это дитя станет следующим королем Стальгорна. И тогда берегись! Этим преступным деянием ты $gнавлек:навлекла; на себя проклятие. Возмездие настигнет тебя и твой род. Всех вас будут травить до скончания дней!$B$B*Вы уверены, что принцесса Мойра до сих пор пребывает под действием чар Тауриссана.*$B$BОставь меня, |3-6($r). Поторопись к своему нанимателю. Наверняка он с нетерпением ждет вестей об исполнении его гнусных замыслов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Траллу в крепость Громмаш, что в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тралл поражен вашим рассказом. Он явно не ожидал ничего подобного.>$B$BСтало быть, надо ждать новой угрозы. Магни уже немолод, кто знает, сколько ему осталось. А если Магни не станет, дорога к трону Стальгорна будет открыта для еще не рожденного отпрыска Черного Железа.$B$BТы $Gисполнил:исполнила; мое поручение и получишь награду.$B$BА теперь оставь меня, $N! Мне надо посовещаться с Сильваной и Кэрном.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4005,'Аквамонтос','Возьми этот мешок с припасами и отнеси в Танарис. Отправляйся в Бухту Сорванных Парусов и найди круг камней. $B$BВстав в этот круг, прочти заклинание из книги Аквора и вызови единственное создание, способное превратить собранные тобой предметы в тотем, с помощью которого можно сразить Яропламеня! $B$BАквамонтос не любит, когда его будят, но помни, ты $gдолжен:должна; быть внутри круга, когда будешь читать заклинание!','Отнесите книгу Аквора, серебристые когти и сердце Железнолесья в Танарис. $B$BВоспользуйтесь книгой для призыва Аквамонтоса. $B$BПо получении тотема, отнести его Джей Ди Колли в Укрытие Маршалла.','Яропламень, говоришь...$B$BДа, я знаю, этот могучий элементаль обитает в опаленном центре кратера. Мы все стараемся держаться от этого места подальше – никому не удавалось проникнуть сквозь ауру этого создания. Многие смельчаки нашли свою смерть в расщелинах сердца кратера.','Так ты $Gвернулся:вернулась;... Хмм... Дай-ка мне взглянуть...','Вернитесь к Джей Ди Колли в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аквамонтос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми этот мешок с припасами и отнеси в Танарис. Отправляйся в Бухту Сорванных Парусов и найди круг камней. $B$BВстав в этот круг, прочти заклинание из книги Аквора и вызови единственное создание, способное превратить собранные тобой предметы в тотем, с помощью которого можно сразить Яропламеня! $B$BАквамонтос не любит, когда его будят, но помни, ты $gдолжен:должна; быть внутри круга, когда будешь читать заклинание!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите книгу Аквора, серебристые когти и сердце Железнолесья в Танарис. $B$BВоспользуйтесь книгой для призыва Аквамонтоса. $B$BПо получении тотема, отнести его Джей Ди Колли в Укрытие Маршалла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Яропламень, говоришь...$B$BДа, я знаю, этот могучий элементаль обитает в опаленном центре кратера. Мы все стараемся держаться от этого места подальше – никому не удавалось проникнуть сквозь ауру этого создания. Многие смельчаки нашли свою смерть в расщелинах сердца кратера.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так ты $Gвернулся:вернулась;... Хмм... Дай-ка мне взглянуть...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джей Ди Колли в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4021,'Контратака!','Орда благодарит тебя за неустанную борьбу с кланом Колкар, но сами кентавры в ярости. Я получил сообщение, что отряд клана Колкар оставил свой дом в Пустошах и прибыл в Степи, движимый местью. Более того, они прямо сейчас подбираются к нам с запада!$B$BВыступи против захватчиков из племени Колкар и положи конец опасности, грозящей Степям. Убивай их, пока не появится их вождь, предводитель Кром\'зар. Одолей его и принеси в доказательство кусок его знамени.$B$BНе подведи меня, $n.','Убивайте кентвров из племени Колкар, пока не появится Кром\'зар. Одержите над ним верх и добудьте кусок знамени Кром\'зара.','Где знамя?','Отнесите знамя Регтару Вратам Смерти в Северные Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контратака!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда благодарит тебя за неустанную борьбу с кланом Колкар, но сами кентавры в ярости. Я получил сообщение, что отряд клана Колкар оставил свой дом в Пустошах и прибыл в Степи, движимый местью. Более того, они прямо сейчас подбираются к нам с запада!$B$BВыступи против захватчиков из племени Колкар и положи конец опасности, грозящей Степям. Убивай их, пока не появится их вождь, предводитель Кром\'зар. Одолей его и принеси в доказательство кусок его знамени.$B$BНе подведи меня, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убивайте кентвров из племени Колкар, пока не появится Кром\'зар. Одержите над ним верх и добудьте кусок знамени Кром\'зара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где знамя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите знамя Регтару Вратам Смерти в Северные Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4022,'Вкус пламени','Стая знает о твоей работе в Тлеющем ущелье.$b$bПокажи ее, |3-6($r). Шкуру, $gкретин безмозглый:кретинка безмозглая;.','Покажите Цирусу Раскаивателю сброшенную кожу черного дракона, полученную от Каларана Ветрореза.','<Цирус изучает шкуру.>$B$BНу что ж, тебе удалось доказать, что ты хоть на что-то $Gпригоден:пригодна;, $Gсмертный:смертная;.','<Глаза Цируса вспыхивают, как две пылающих сферы.>','Доказательство представлено','Поговорите с Цирусом Раскаивателем на Скользкой скале, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вкус пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стая знает о твоей работе в Тлеющем ущелье.$b$bПокажи ее, |3-6($r). Шкуру, $gкретин безмозглый:кретинка безмозглая;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите Цирусу Раскаивателю сброшенную кожу черного дракона, полученную от Каларана Ветрореза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Цирус изучает шкуру.>$B$BНу что ж, тебе удалось доказать, что ты хоть на что-то $Gпригоден:пригодна;, $Gсмертный:смертная;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Глаза Цируса вспыхивают, как две пылающих сферы.>',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Доказательство представлено',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Цирусом Раскаивателем на Скользкой скале, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4023,'Вкус пламени','Ты ищешь Стаю? Принеси мне доказательства того, что ты $gдостоин:достойна; этого знания, $gсмертный:смертная;.','Покажите Цирусу Раскаивателю доказательство своих деяний.$b$bВозникает чувство, что Цирус заранее сомневается в ваших качествах.','<Цирус изучает шкуру.>$B$BНу что ж, тебе удалось доказать, что ты хоть на что-то $Gпригоден:пригодна;, $Gсмертный:смертная;.','<Глаза Цируса вспыхивают, как две пылающих сферы.>','Вернитесь к Цирусу Раскаивателю на Скользкую скалу, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вкус пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты ищешь Стаю? Принеси мне доказательства того, что ты $gдостоин:достойна; этого знания, $gсмертный:смертная;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите Цирусу Раскаивателю доказательство своих деяний.$b$bВозникает чувство, что Цирус заранее сомневается в ваших качествах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Цирус изучает шкуру.>$B$BНу что ж, тебе удалось доказать, что ты хоть на что-то $Gпригоден:пригодна;, $Gсмертный:смертная;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Глаза Цируса вспыхивают, как две пылающих сферы.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цирусу Раскаивателю на Скользкую скалу, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4024,'Вкус пламени','Я хочу попробовать обжигающие языки пламени огненной горы. Чтобы сквозь меня текла лава Черной горы. Я жажду этого обжигающего тепла.$b$bБаэл-Гар живет в глубинах Черной горы. Он воплощение пламени, порождение огня Рагнароса. Убей Бейл\'Гора и возьми из его дымящихся останков частицу его внутреннего огня.$b$bЧтобы взять, не обжигаясь, этот огонь, воспользуйся драконьей шкурой.$b$bДобейся успеха, и награда будет велика.','Отправьтесь в глубины Черной горы и убейте Бейл\'Гора.$b$bИзвестно лишь то, что великан живет в глубинах. Воспользуйтесь измененной сброшенной шкурой черного дракона и возьмите из останков Бейл\'Гора сущность Огня.$b$bОтнесите пойманную сущность Огня Цирусу Раскаивателю.','<Цирус выхватывает сущность Огня у вас из рук.>$B$BДА!$B$BБери награду и убирайся. Долой с глаз моих!','Пал ли от твоей руки великан?','Вернитесь к Цирусу Раскаивателю на Скользкую скалу, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вкус пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу попробовать обжигающие языки пламени огненной горы. Чтобы сквозь меня текла лава Черной горы. Я жажду этого обжигающего тепла.$b$bБаэл-Гар живет в глубинах Черной горы. Он воплощение пламени, порождение огня Рагнароса. Убей Бейл\'Гора и возьми из его дымящихся останков частицу его внутреннего огня.$b$bЧтобы взять, не обжигаясь, этот огонь, воспользуйся драконьей шкурой.$b$bДобейся успеха, и награда будет велика.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь в глубины Черной горы и убейте Бейл\'Гора.$b$bИзвестно лишь то, что великан живет в глубинах. Воспользуйтесь измененной сброшенной шкурой черного дракона и возьмите из останков Бейл\'Гора сущность Огня.$b$bОтнесите пойманную сущность Огня Цирусу Раскаивателю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Цирус выхватывает сущность Огня у вас из рук.>$B$BДА!$B$BБери награду и убирайся. Долой с глаз моих!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пал ли от твоей руки великан?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цирусу Раскаивателю на Скользкую скалу, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4041,'Эликсир Видере','Ну что, удалось тебе обойти старого Миблона, а?','Эликсир Видере? Ну да, смогу, конечно, только принеси сначала мне эвокорень.$B$BВ травках и алхимии я разбираюсь неплохо... Вот послушай, как я однажды трансмутировал в золото сыр, которым собирался пообедать... Эй, ты куда?','Вернитесь к Грегану Пивоплюю в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эликсир Видере',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну что, удалось тебе обойти старого Миблона, а?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эликсир Видере? Ну да, смогу, конечно, только принеси сначала мне эвокорень.$B$BВ травках и алхимии я разбираюсь неплохо... Вот послушай, как я однажды трансмутировал в золото сыр, которым собирался пообедать... Эй, ты куда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грегану Пивоплюю в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4061,'Восстание машин','Впервые мы увидели эти машины, когда начали набеги в Тлеющее ущелье. Потом выяснилось, что их привозят из Пылающих степей, вероятно, из глубин Черной горы. Нам нужна твоя помощь, $n. $B$BДля выполнения первого задания отправляйся в Пылающие степи и извлеки осколки элементалей из каменных машин и малых каменных созданий, которых там найдешь. Когда соберешь достаточно, возвращайся ко мне, и я попробую разобраться, откуда они происходят.','Отправляйтесь в Пылающие степи и соберите 10 осколков элементалей для верховной жрицы Теодоры Мальвадании. $B$BТеодора упоминала, что осколки можно найти у элементалей и големов.','<Теодора раскладывает перед собой осколки и рассматривает их в огромную лупу.>$B$BПрелюбопытно... На каждом из этих осколков выгравированы... инициалы.','Отнесись к этому заданию со всей серьезностью, $N!','Вернитесь к верховной жрице Теодоре Мальвадании в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстание машин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Впервые мы увидели эти машины, когда начали набеги в Тлеющее ущелье. Потом выяснилось, что их привозят из Пылающих степей, вероятно, из глубин Черной горы. Нам нужна твоя помощь, $n. $B$BДля выполнения первого задания отправляйся в Пылающие степи и извлеки осколки элементалей из каменных машин и малых каменных созданий, которых там найдешь. Когда соберешь достаточно, возвращайся ко мне, и я попробую разобраться, откуда они происходят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Пылающие степи и соберите 10 осколков элементалей для верховной жрицы Теодоры Мальвадании. $B$BТеодора упоминала, что осколки можно найти у элементалей и големов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Теодора раскладывает перед собой осколки и рассматривает их в огромную лупу.>$B$BПрелюбопытно... На каждом из этих осколков выгравированы... инициалы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Отнесись к этому заданию со всей серьезностью, $N!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховной жрице Теодоре Мальвадании в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4062,'Восстание машин','Г.Л.А. $B$BЭти инициалы выгравированы на осколках элементалей. Под ними выгравирована надпись, видимо, указующая на ранг машины. Механизмы, уничтоженные тобой в Пылающих степях, имели четвертый ранг. Полагаю, это один их низших рангов. $B$BВозьми этот образец осколка и отнеси его Лотвилю Вериатусу в лагерь на востоке. Он ученый, весьма признанный в сферах изучения cтихий. Возможно, он поможет нам советом.','Отнесите образец осколка элементаля Лотвилю Вериатусу. $B$BТеодора упоминала, что его лагерь находится на востоке.','<Лотвил неожиданно бледнеет>$B$BЯ узнаю эти знаки...','Что это у тебя, $R?','Поговорите с Лотвилем Вериатусом в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстание машин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Г.Л.А. $B$BЭти инициалы выгравированы на осколках элементалей. Под ними выгравирована надпись, видимо, указующая на ранг машины. Механизмы, уничтоженные тобой в Пылающих степях, имели четвертый ранг. Полагаю, это один их низших рангов. $B$BВозьми этот образец осколка и отнеси его Лотвилю Вериатусу в лагерь на востоке. Он ученый, весьма признанный в сферах изучения cтихий. Возможно, он поможет нам советом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите образец осколка элементаля Лотвилю Вериатусу. $B$BТеодора упоминала, что его лагерь находится на востоке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Лотвил неожиданно бледнеет>$B$BЯ узнаю эти знаки...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя, $R?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Лотвилем Вериатусом в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4063,'Восстание машин','Неужели это Аргелмах? Не может быть! Он же мертв уже много лет! Почему я так в этом уверен? Да потому что это я убил его! $B$BЭтот презренный дворф имел маниакальную страсть к извращению моих изобретений – над которыми я, к слову, корпел годами! – и использованию их для своих мерзких делишек. Надо же, самые мерзкие создания всегда самые живучие! $B$BЕсли это и правда работа Аргелмаха, то он должен быть уничтожен. И мне потребуются образцы его последних творений. Если у меня будут образцы, возможно, я смогу придумать, как подавить восстание. Видимо, Аргелмах теперь в глубинах Черной горы под охраной своих творений.','Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилу. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии.','Что это?! Голова... Она не из плоти и крови! Это какое-то создание из черного железа! Аргелмах был ЕЩЕ ОДНОЙ машиной! Полагаю, в таком случае нам рано праздновать победу – на его место вскоре придет другой!','Так это и в самом деле был он? Так он жив?','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстание машин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неужели это Аргелмах? Не может быть! Он же мертв уже много лет! Почему я так в этом уверен? Да потому что это я убил его! $B$BЭтот презренный дворф имел маниакальную страсть к извращению моих изобретений – над которыми я, к слову, корпел годами! – и использованию их для своих мерзких делишек. Надо же, самые мерзкие создания всегда самые живучие! $B$BЕсли это и правда работа Аргелмаха, то он должен быть уничтожен. И мне потребуются образцы его последних творений. Если у меня будут образцы, возможно, я смогу придумать, как подавить восстание. Видимо, Аргелмах теперь в глубинах Черной горы под охраной своих творений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и убейте повелителя големов Аргелмаха. Принесите его голову Лотвилу. Также соберите 10 невредимых ядер стихий с беспощадных големов и созданий-завоевателей, охраняющих Аргелмаха. Информация передана посредством телепатии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это?! Голова... Она не из плоти и крови! Это какое-то создание из черного железа! Аргелмах был ЕЩЕ ОДНОЙ машиной! Полагаю, в таком случае нам рано праздновать победу – на его место вскоре придет другой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так это и в самом деле был он? Так он жив?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лотвилю Вериатусу в Знойные Пески, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4081,'УНИЧТОЖИТЬ НА МЕСТЕ: Дворфы Черного Железа','По приказу полководца Клинозуба, командира каргатского экспедиционного отряда: $B$BВсе силы генерала Кузни Гнева в Глубинах Черной горы должны быть истреблены. $B$BКлан Кузни Гнева – беспощадные убийцы, ответственные за уничтожение 109-ого подразделения каргатского экспедиционного отряда. Необходимо сохранять бдительность. $B$BТот, кто сможет разбить передовые войска генерала Кузни Гнева в Глубинах Черной горы, будет представлен к награде.','Отправляйтесь в глубины Черной горы и уничтожьте подлых агрессоров! $B$BПо приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания.','Небось, после такого Кузня Гнева в штаны наложил! Теперь проходи, проходи, солдат. У меня еще масса дел!$B$BСмотри внимательно на объявления, для тебя может найтись еще работенка.','Что это, $R? Разве ты не видишь, что у меня есть взвод?','Вернитесь к полководцу Клинозубу в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','УНИЧТОЖИТЬ НА МЕСТЕ: Дворфы Черного Железа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По приказу полководца Клинозуба, командира каргатского экспедиционного отряда: $B$BВсе силы генерала Кузни Гнева в Глубинах Черной горы должны быть истреблены. $B$BКлан Кузни Гнева – беспощадные убийцы, ответственные за уничтожение 109-ого подразделения каргатского экспедиционного отряда. Необходимо сохранять бдительность. $B$BТот, кто сможет разбить передовые войска генерала Кузни Гнева в Глубинах Черной горы, будет представлен к награде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в глубины Черной горы и уничтожьте подлых агрессоров! $B$BПо приказу полководца Клинозуба уничтожьте 15 охранников, 10 надсмотрщиков и 5 пехотинцев из клана Ярости Горна. Вернитесь сразу по выполнении задания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Небось, после такого Кузня Гнева в штаны наложил! Теперь проходи, проходи, солдат. У меня еще масса дел!$B$BСмотри внимательно на объявления, для тебя может найтись еще работенка.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это, $R? Разве ты не видишь, что у меня есть взвод?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Клинозубу в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4082,'УНИЧТОЖИТЬ НА МЕСТЕ: Высокопоставленные чины Черного Железа','Приказ полководца Клинозуба, командира Каргатского экспедиционного корпуса: $B$BГлава разведывательного подразделения Каргатского экспедиционного корпуса, гроссмейстер Лекслорт вернулся с рапортом о месторасположении высокопоставленных чинов Черного Железа. В центре города, за закрытыми воротами они обучают своих солдат уничтожать наших собратьев. Отправляйся в Глубины Черной горы и уничтожь их! $B$BВ случае успешного выполнения задания будешь $gпредставлен:представлена; к награде.','Отправляйтесь в глубины Черной горы и уничтожьте подлых агрессоров! $B$BПо приказу полководца Клинозуба уничтожьте 10 медиков, 10 солдат и 10 офицеров из клана Ярости Горна. Вернитесь сразу по выполнении задания.','Не сомневаюсь, генерал Кузня Гнева теперь... в гневе. Возвращайся ко мне, когда получишь третью награду, и мы приступим к операции "Смерть Кузне Гнева". Пока не буду вдаваться в детали, но могу заверить наперед, что точно кто-нибудь умрет!','Снова ты? Я должен передать это тебе, $N, ты $Gупорный:упорная;.','Вернитесь к полководцу Клинозубу в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','УНИЧТОЖИТЬ НА МЕСТЕ: Высокопоставленные чины Черного Железа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приказ полководца Клинозуба, командира Каргатского экспедиционного корпуса: $B$BГлава разведывательного подразделения Каргатского экспедиционного корпуса, гроссмейстер Лекслорт вернулся с рапортом о месторасположении высокопоставленных чинов Черного Железа. В центре города, за закрытыми воротами они обучают своих солдат уничтожать наших собратьев. Отправляйся в Глубины Черной горы и уничтожь их! $B$BВ случае успешного выполнения задания будешь $gпредставлен:представлена; к награде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в глубины Черной горы и уничтожьте подлых агрессоров! $B$BПо приказу полководца Клинозуба уничтожьте 10 медиков, 10 солдат и 10 офицеров из клана Ярости Горна. Вернитесь сразу по выполнении задания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не сомневаюсь, генерал Кузня Гнева теперь... в гневе. Возвращайся ко мне, когда получишь третью награду, и мы приступим к операции "Смерть Кузне Гнева". Пока не буду вдаваться в детали, но могу заверить наперед, что точно кто-нибудь умрет!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Снова ты? Я должен передать это тебе, $N, ты $Gупорный:упорная;.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Клинозубу в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4083,'Призрачный кубок','Драгоценные камни беззвучно падают в глубину кубка...','Призрачный кубок парит в воздухе, медленно поднимаясь и опускаясь... как будто следуя ритмам биения умирающего сердца.','Вернитесь к призрачному кубку в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призрачный кубок',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Драгоценные камни беззвучно падают в глубину кубка...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Призрачный кубок парит в воздухе, медленно поднимаясь и опускаясь... как будто следуя ритмам биения умирающего сердца.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призрачному кубку в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4084,'Серебряное сердце','Я не знаю, о ком ты говоришь, $n. $B$BНо если твой друг искал меня, я знаю, что ему было нужно. $B$BВ сердце Кратера Ун\'Горо скрывается зло в чистейшей его форме – это элементаль, именуемый Яропламень. Он защищен аурой, разрушить которую не под силам никому... $B$BНикому, кроме обладателя еще большей силы. Я научу тебя, как справиться с этой задачей, $n. $B$BСначала сделай, что я попрошу. Собери и принеси мне 11 серебристых когтей и 1 сердце Железнолесья – ты найдешь их у созданий Оскверненного леса.','Добудьте 11 серебристых когтей и 1 сердце Железнолесья для Эриданы Грусти Ветра из Оскверненного леса.','Прекрасно, $N. Вижу, ты всегда $Gготов:готова; помогать друзьям.','Я расскажу тебе о том, как сразить Яропламень, но прежде принеси мне то, что чем я просила тебя.','Вернитесь к Эридане Грусти Ветра в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серебряное сердце',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не знаю, о ком ты говоришь, $n. $B$BНо если твой друг искал меня, я знаю, что ему было нужно. $B$BВ сердце Кратера Ун\'Горо скрывается зло в чистейшей его форме – это элементаль, именуемый Яропламень. Он защищен аурой, разрушить которую не под силам никому... $B$BНикому, кроме обладателя еще большей силы. Я научу тебя, как справиться с этой задачей, $n. $B$BСначала сделай, что я попрошу. Собери и принеси мне 11 серебристых когтей и 1 сердце Железнолесья – ты найдешь их у созданий Оскверненного леса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 11 серебристых когтей и 1 сердце Железнолесья для Эриданы Грусти Ветра из Оскверненного леса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, $N. Вижу, ты всегда $Gготов:готова; помогать друзьям.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я расскажу тебе о том, как сразить Яропламень, но прежде принеси мне то, что чем я просила тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эридане Грусти Ветра в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4101,'Очищение Оскверненного леса','Растения дают жизнь Оскверненному лесу, но даже они поражены порчей. Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или кого не знаю. Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария!$B$BК северу отсюда лежат Пещеры Железнолесья. Тамошние Криводревы-элементали поражены порчей так, что исцелить их уже нет надежды. Прошу тебя – принеси мне их застывший сок – его называют кровавым янтарем – чтобы я могла изучить его в надежде спасти другие формы здешней жизни.','Принесите 15 кровавых янтарей Аратандис Серебряному Небу в Оскверненный лес.','Вернитесь к Аратандис Серебряному Небу в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Оскверненного леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Растения дают жизнь Оскверненному лесу, но даже они поражены порчей. Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или кого не знаю. Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария!$B$BК северу отсюда лежат Пещеры Железнолесья. Тамошние Криводревы-элементали поражены порчей так, что исцелить их уже нет надежды. Прошу тебя – принеси мне их застывший сок – его называют кровавым янтарем – чтобы я могла изучить его в надежде спасти другие формы здешней жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 15 кровавых янтарей Аратандис Серебряному Небу в Оскверненный лес.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аратандис Серебряному Небу в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4102,'Очищение Оскверненного леса','Растения дают жизнь Оскверненному лесу, но даже они поражены порчей. Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или не знаю. Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария!$B$BК северу отсюда лежат Пещеры Железнолесья. Тамошние Криводревы-элементали поражены порчей так, что исцелить их уже нет надежды. Прошу тебя, принеси мне их застывший сок – его называют кровавым янтарем, – чтобы я могла изучить его в надежде спасти другие формы здешней жизни.','Принесите 15 кровавых янтарей Майбессе Речному Ветру в Оскверненный лес.','Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Оскверненный лес. Ты $Gдоказал:доказала; мне, что $Gготов:готова; сделать все для Круга Кенария. Теперь я доверяю тебе.$B$BМожет показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель – спасение бесчисленных живых существ – оправдывает средства. Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов. которые я смогу сделать.','Оскверненный лес страдает, $N – а вместе с ним и я! Я должна быть уверена во всем – если мои знания попадут не в те руки, это обернется бедой для всего Оскверненного леса.$B$BПринеси мне кровавый янтарь с убитых Криводревов-элементалей, и я поверю, что ты искренне помогаешь мне в поисках средства борьбы с порчей.','Вернитесь к Майбессе Речному Ветру в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Оскверненного леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Растения дают жизнь Оскверненному лесу, но даже они поражены порчей. Я знаю способ исцелить их, но эти знания я не могу передать тому, к кому не питаю доверия или не знаю. Докажи мне, что ты от чистого сердца помогаешь Кругу Кенария!$B$BК северу отсюда лежат Пещеры Железнолесья. Тамошние Криводревы-элементали поражены порчей так, что исцелить их уже нет надежды. Прошу тебя, принеси мне их застывший сок – его называют кровавым янтарем, – чтобы я могла изучить его в надежде спасти другие формы здешней жизни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 15 кровавых янтарей Майбессе Речному Ветру в Оскверненный лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот кровавый янтарь поможет мне найти средство борьбы с порчей, поразившей Оскверненный лес. Ты $Gдоказал:доказала; мне, что $Gготов:готова; сделать все для Круга Кенария. Теперь я доверяю тебе.$B$BМожет показаться странным, что доказательством твоей преданности послужило истребление элементалей, но наша цель – спасение бесчисленных живых существ – оправдывает средства. Теперь мы с тобой можем заняться спасением жизней при помощи бальзамов. которые я смогу сделать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Оскверненный лес страдает, $N – а вместе с ним и я! Я должна быть уверена во всем – если мои знания попадут не в те руки, это обернется бедой для всего Оскверненного леса.$B$BПринеси мне кровавый янтарь с убитых Криводревов-элементалей, и я поверю, что ты искренне помогаешь мне в поисках средства борьбы с порчей.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Майбессе Речному Ветру в Оскверненный лес.',`completedtext_loc8`);
