INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (4119,'Оскверненный ночной дракон','Вернитесь к оскверненному ночному дракону в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный ночной дракон',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному ночному дракону в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4120,'Сила порчи','Я – охотник, и всегда стремлюсь превзойти силой своих противников. Запомни, $n: всегда можно обратить ситуацию в свою пользу, если хорошо знаешь врага.$b$bК северу от Ясеневого леса есть место, называемое Оскверненный лес. Тамошние звери запятнаны веществом, которое именуется скверной. Медведи и волки от него совершенно взбесились, но в то же время скверна сделала их сильнее обычного.$b$bСтупай, $n. Отправляйся в Оскверненный лес, чтобы встретиться с этими тварями лицом к лицу.','Убейте 12 гризли злобных когтей и 12 опустошителей-сквернолапов в Оскверненном лесу по просьбе Тало Тернового Копыта из Лагеря Мохаче.','Судя по твоему описанию, эти твари отличаются безоглядной свирепостью…$B$BОставайся начеку, $N. Тебе стоит как можно больше узнать о порче. Врага нужно знать в лицо!','Все, к чему прикасается Скверна, излучает странное зеленое свечение ... Я чувствую, что это зло, но в то же время очень мощное.','Вернитесь к Тало Терновому Копыту в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила порчи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я – охотник, и всегда стремлюсь превзойти силой своих противников. Запомни, $n: всегда можно обратить ситуацию в свою пользу, если хорошо знаешь врага.$b$bК северу от Ясеневого леса есть место, называемое Оскверненный лес. Тамошние звери запятнаны веществом, которое именуется скверной. Медведи и волки от него совершенно взбесились, но в то же время скверна сделала их сильнее обычного.$b$bСтупай, $n. Отправляйся в Оскверненный лес, чтобы встретиться с этими тварями лицом к лицу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 гризли злобных когтей и 12 опустошителей-сквернолапов в Оскверненном лесу по просьбе Тало Тернового Копыта из Лагеря Мохаче.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Судя по твоему описанию, эти твари отличаются безоглядной свирепостью…$B$BОставайся начеку, $N. Тебе стоит как можно больше узнать о порче. Врага нужно знать в лицо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все, к чему прикасается Скверна, излучает странное зеленое свечение ... Я чувствую, что это зло, но в то же время очень мощное.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тало Терновому Копыту в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4121,'Опасное положение','Ты в самом деле надеешься добраться до точки встречи, держа меня в плену? Ты и правда рассчитываешь, ворвавшись в крепость Черной горы и похитив главную ценность клана, удрать $gнезамеченным:незамеченной;?$b$bДа тебя в порошок сотрут!','Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью.$b$bЛекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму.$b$bТакже отдайте Лекслорту ториевые оковы.','Твой подвиг не пропадет втуне. Ты $Gзаслужил:заслужила; эту награду. Теперь Вождь поведает тебе о последнем задании.','Давай сюда этого предателя, $N.','Доставка пленника','Вернитесь к Лекслорту в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасное положение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты в самом деле надеешься добраться до точки встречи, держа меня в плену? Ты и правда рассчитываешь, ворвавшись в крепость Черной горы и похитив главную ценность клана, удрать $gнезамеченным:незамеченной;?$b$bДа тебя в порошок сотрут!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отконвоируйте пленника, Грарка Лорктуба, через Пылающие степи и Черную гору к Тлеющему ущелью.$b$bЛекслорт что-то говорил насчет того, что по другую сторону будут ждать его ребята, которые уведут Грарка в тюрьму.$b$bТакже отдайте Лекслорту ториевые оковы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твой подвиг не пропадет втуне. Ты $Gзаслужил:заслужила; эту награду. Теперь Вождь поведает тебе о последнем задании.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Давай сюда этого предателя, $N.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Доставка пленника',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лекслорту в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4122,'Грарк Лоркруб','Я шел за ним через Тлеющее ущелье, через горы и Пылающие степи. Предателя поймали на месте преступления, когда тот передавал оркам Черной горы сверхсекретную информацию о деятельности нашего отряда. Я говорю о Грарке Лоркрубе. $B$BОн теперь в Пылающих степях, под их надежной охраной – по крайней мере, он сам так думает. $B$BВозьми эти оковы, $n. Найди Грарка, надень на него эти оковы и доставь сюда. Награда будет достойной.','Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы. $B$BПо обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника.','Разве ты не понимаешь, какую силу можно обрести, присоединившись к армии Черной горы?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грарк Лоркруб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я шел за ним через Тлеющее ущелье, через горы и Пылающие степи. Предателя поймали на месте преступления, когда тот передавал оркам Черной горы сверхсекретную информацию о деятельности нашего отряда. Я говорю о Грарке Лоркрубе. $B$BОн теперь в Пылающих степях, под их надежной охраной – по крайней мере, он сам так думает. $B$BВозьми эти оковы, $n. Найди Грарка, надень на него эти оковы и доставь сюда. Награда будет достойной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь в Пылающие степи и найдите Грарка Лоркруба. Лекслорт упоминал, что в последний раз предателя видели в крепости Черной горы. $B$BПо обнаружении Грарка Лоркруба закуйте его в ториевые оковы и затем доставьте его от Черной горы к Тлеющему ущелью, Лекслорт и его подчиненные займутся допросом преступника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разве ты не понимаешь, какую силу можно обрести, присоединившись к армии Черной горы?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4123,'Сердце горы','Сколько лет я ищу этот камень! Он называется "сердце горы". Размером как раз с твой кулак. Дворфы Черного Железа прячут его в своих тайных подвалах. Я пытался его купить, предлагал им хорошую цену, но они не продают!$B$BПридется забрать его силой, другого способа я не вижу.$B$BТебе надо пробиться на нижний ярус Глубин Черной горы, взломать потайной сейф и забрать сердце. Для того чтобы добраться до тайника, тебе придется сразиться с тамошним стражником. Его зовут Хватка Смерти, и он появится только тогда, когда ты вскроешь все сундуки и сейфы!$B$BУдачи.','Принесите сердце горы Максворту Суперблеску в Пылающие степи.','Ты принес сердце горы? Для меня его ценность поистине безгранична.','Вернитесь к Максворту Суперблеску на Скалу Молота Ужаса, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце горы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сколько лет я ищу этот камень! Он называется "сердце горы". Размером как раз с твой кулак. Дворфы Черного Железа прячут его в своих тайных подвалах. Я пытался его купить, предлагал им хорошую цену, но они не продают!$B$BПридется забрать его силой, другого способа я не вижу.$B$BТебе надо пробиться на нижний ярус Глубин Черной горы, взломать потайной сейф и забрать сердце. Для того чтобы добраться до тайника, тебе придется сразиться с тамошним стражником. Его зовут Хватка Смерти, и он появится только тогда, когда ты вскроешь все сундуки и сейфы!$B$BУдачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сердце горы Максворту Суперблеску в Пылающие степи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес сердце горы? Для меня его ценность поистине безгранична.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Максворту Суперблеску на Скалу Молота Ужаса, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4124,'Пропавший курьер','Моему соратнику, Гинро Пылающему Очагу, нужна помощь. Он ищет курьера и пакеты, которые тот вез. Курьер пропал примерно неделю назад; наши собственные поиски результата не дали. Мы зашли в тупик. Пришлось объявить курьера пропавшим без вести.$b$bЕсли у тебя есть свободное время, пожалуйста, поговори с Гинро. Он должен быть где-то здесь. Возможно, он у себя.','Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.','Ты от Латро, я так понимаю? Я думаю, что дело глухо, но готов принять любую помощь. Должен признаться... я буду рад, когда вопрос решится хоть как-то. Я каждое утро выезжаю в лес разыскивать следы Раскала, и каждый вечер возвращаюсь домой с пустыми руками!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший курьер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моему соратнику, Гинро Пылающему Очагу, нужна помощь. Он ищет курьера и пакеты, которые тот вез. Курьер пропал примерно неделю назад; наши собственные поиски результата не дали. Мы зашли в тупик. Пришлось объявить курьера пропавшим без вести.$b$bЕсли у тебя есть свободное время, пожалуйста, поговори с Гинро. Он должен быть где-то здесь. Возможно, он у себя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты от Латро, я так понимаю? Я думаю, что дело глухо, но готов принять любую помощь. Должен признаться... я буду рад, когда вопрос решится хоть как-то. Я каждое утро выезжаю в лес разыскивать следы Раскала, и каждый вечер возвращаюсь домой с пустыми руками!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4125,'Пропавший курьер','Прошла примерно неделя с тех пор, как Раскал, курьер, отправился в Таланаар. Фералас он знает, как свои пять пальцев – он был здесь с нами с самого начала, с тех пор, как генерал Оперенная Луна привела сюда экспедиционный корпус. Я знаю, что он собирался взять весельную лодку и проплыть вдоль побережья Фераласа, чтобы миновать лагерь Орды.$b$bЕго лодки я так и не обнаружил – но, возможно, тебе это удастся. Может быть, она спрятана либо потонула. А между тем именно лодка может помочь выяснить, где Раскал. Если найдешь что-нибудь, дай мне знать.','Отыщите лодку курьера, которая должна находиться где-то на побережье Фераласа.','Вы обнаружили затонувшую лодку. Сквозь мутноватую воду видны дыры, зияющие в левом борту. Кажется, будто лодка буквально ободрана до своего деревянного остова. Такое впечатление, что лодку пытались перекусить пополам. На правом борту нарисован небольшой герб Крепости Оперенной Луны.$B$BВ иле, скопившемся на дне лодки, блеснул металл...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший курьер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошла примерно неделя с тех пор, как Раскал, курьер, отправился в Таланаар. Фералас он знает, как свои пять пальцев – он был здесь с нами с самого начала, с тех пор, как генерал Оперенная Луна привела сюда экспедиционный корпус. Я знаю, что он собирался взять весельную лодку и проплыть вдоль побережья Фераласа, чтобы миновать лагерь Орды.$b$bЕго лодки я так и не обнаружил – но, возможно, тебе это удастся. Может быть, она спрятана либо потонула. А между тем именно лодка может помочь выяснить, где Раскал. Если найдешь что-нибудь, дай мне знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите лодку курьера, которая должна находиться где-то на побережье Фераласа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы обнаружили затонувшую лодку. Сквозь мутноватую воду видны дыры, зияющие в левом борту. Кажется, будто лодка буквально ободрана до своего деревянного остова. Такое впечатление, что лодку пытались перекусить пополам. На правом борту нарисован небольшой герб Крепости Оперенной Луны.$B$BВ иле, скопившемся на дне лодки, блеснул металл...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4126,'Харли Чернопых','Подонки Черного Железа под предводительством гнусного Харли Чернопыха украли рецепт нашего лучшего светлого громоварского! Подлые твари! Они не достойны такого прекрасного напитка!$B$B$n, у меня есть для тебя работа. Отправляйся в Глубины Черной горы в Пылающих степях, уничтожь все бочонки со светлым громоварским, какие сумеешь найти, и забери у мерзавцев наш рецепт!$B$BПереверни все Глубины, но найди этот рецепт!','Найдите украденный рецепт Громоваров и верните его Рагнару Громовару в Каранос.','Вернитесь к Рагнару Громовару на Мерцающий хребет, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Харли Чернопых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подонки Черного Железа под предводительством гнусного Харли Чернопыха украли рецепт нашего лучшего светлого громоварского! Подлые твари! Они не достойны такого прекрасного напитка!$B$B$n, у меня есть для тебя работа. Отправляйся в Глубины Черной горы в Пылающих степях, уничтожь все бочонки со светлым громоварским, какие сумеешь найти, и забери у мерзавцев наш рецепт!$B$BПереверни все Глубины, но найди этот рецепт!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите украденный рецепт Громоваров и верните его Рагнару Громовару в Каранос.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рагнару Громовару на Мерцающий хребет, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4127,'Разбитая лодка','Копаясь в иле, вы нащупываете рукоятку ножа. Похоже, тот, кто плыл на лодке, его потерял. Рядом валяются обломки самой лодки...$b$bВы берете нож с собой: Гинро Пылающий Очаг из Крепости Оперенной Луны велел вам принести ему все, что может помочь разгадать тайну. Однако вас не покидает ощущение, что вы тут не одни...','Вернитесь в Крепость Оперенной Луны и покажите Гинро Пылающему Очагу выброшенный нож, который вы нашли.','Интересно... Похоже, это нож Раскала. Так говоришь, он валялся на дне, рядом с обломками его лодки? Ну, может быть, этой находки и недостаточно, чтобы делать какие-то выводы. Но у нас есть один необычный способ узнать побольше…$B$BДоводилось ли тебе слышать о сверхзнании?','А, $N! С возвращением. Надеюсь, тебе удалось узнать что-нибудь о судьбе Раскала? Даже если его судьба трагична...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разбитая лодка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Копаясь в иле, вы нащупываете рукоятку ножа. Похоже, тот, кто плыл на лодке, его потерял. Рядом валяются обломки самой лодки...$b$bВы берете нож с собой: Гинро Пылающий Очаг из Крепости Оперенной Луны велел вам принести ему все, что может помочь разгадать тайну. Однако вас не покидает ощущение, что вы тут не одни...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Крепость Оперенной Луны и покажите Гинро Пылающему Очагу выброшенный нож, который вы нашли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интересно... Похоже, это нож Раскала. Так говоришь, он валялся на дне, рядом с обломками его лодки? Ну, может быть, этой находки и недостаточно, чтобы делать какие-то выводы. Но у нас есть один необычный способ узнать побольше…$B$BДоводилось ли тебе слышать о сверхзнании?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, $N! С возвращением. Надеюсь, тебе удалось узнать что-нибудь о судьбе Раскала? Даже если его судьба трагична...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4128,'Рагнар Громовар','Здравствуй, $n. Ходят слухи, что кто-то украл у Рагнара Громовара его драгоценный эль. Бедолага рвет и мечет! Ему нужен отважный и дерзкий наемник, который возьмется за это дело. Рагнар готов хорошо заплатить.$B$BЕсли тебе интересно, переговори с ним. Он сейчас в своей "Громоварке" в Караносе. Это в Дун Мороге.','Переговорите с Рагнаром Громоваром.','Да, ты $Gправ:права;, я не просто рассержен. Я в бешенстве! Меня обокрали! Эти скоты сперли наш старый фамильный рецепт! Да как они только посмели?! Я и раньше-то их ненавидел... этих поганых дворфов из клана Черного Железа! А теперь... ох, как я зол!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рагнар Громовар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, $n. Ходят слухи, что кто-то украл у Рагнара Громовара его драгоценный эль. Бедолага рвет и мечет! Ему нужен отважный и дерзкий наемник, который возьмется за это дело. Рагнар готов хорошо заплатить.$B$BЕсли тебе интересно, переговори с ним. Он сейчас в своей "Громоварке" в Караносе. Это в Дун Мороге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Переговорите с Рагнаром Громоваром.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, ты $Gправ:права;, я не просто рассержен. Я в бешенстве! Меня обокрали! Эти скоты сперли наш старый фамильный рецепт! Да как они только посмели?! Я и раньше-то их ненавидел... этих поганых дворфов из клана Черного Железа! А теперь... ох, как я зол!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4129,'Тайна ножа','У нас в крепости живет друид, Квинтис Ночной Костер, который умеет... много всего. В частности, он владеет сверхзнанием – способностью узнавать на ощупь историю предмета. Не спрашивай, как он это делает – я в этом не разбираюсь, и разбираться не хочу. Я знаю только две вещи: во-первых, я видел, как это работает, а во-вторых, этот друид у меня в долгу.$b$bКороче, тащи этот ножик к Квинту, в его жилище на дереве, и передай, что должок, который за ним числится, будет уплачен, если он разберется с этой штукой.','Отнесите выброшенный нож к друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.','Спасибо, $N.$B$BКонечно, сверхзнание точным искусством не назовешь, с какой стороны ни взгляни, но все же в былые времена я не раз с его помощью разбирался в ситуациях, которые все прочие сочли безнадежными. Думаю, на этот раз оно поможет нам хотя бы отчасти понять, что произошло с Раскалом.$B$BВремени это много не займет, но легким и приятным это дело не назовешь. Так что будь $Gготов:готова; прийти мне на помощь.','Ты от Гинро, да? Ох, нелегкая это работа... впрочем, долг платежом красен. А они еще издеваются, говорят, мол, не везет в карты – повезет в любви... Впрочем, мне везет скорее в постижении тайн природы.$B$BНет, конечно, я это сделаю. Возможно, это именно то, чего нам недостает, чтобы узнать о судьбе Раскала. Давай сюда нож, и возьмемся за дело.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна ножа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас в крепости живет друид, Квинтис Ночной Костер, который умеет... много всего. В частности, он владеет сверхзнанием – способностью узнавать на ощупь историю предмета. Не спрашивай, как он это делает – я в этом не разбираюсь, и разбираться не хочу. Я знаю только две вещи: во-первых, я видел, как это работает, а во-вторых, этот друид у меня в долгу.$b$bКороче, тащи этот ножик к Квинту, в его жилище на дереве, и передай, что должок, который за ним числится, будет уплачен, если он разберется с этой штукой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите выброшенный нож к друиду по имени Квинтис Ночной Костер в Крепости Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N.$B$BКонечно, сверхзнание точным искусством не назовешь, с какой стороны ни взгляни, но все же в былые времена я не раз с его помощью разбирался в ситуациях, которые все прочие сочли безнадежными. Думаю, на этот раз оно поможет нам хотя бы отчасти понять, что произошло с Раскалом.$B$BВремени это много не займет, но легким и приятным это дело не назовешь. Так что будь $Gготов:готова; прийти мне на помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты от Гинро, да? Ох, нелегкая это работа... впрочем, долг платежом красен. А они еще издеваются, говорят, мол, не везет в карты – повезет в любви... Впрочем, мне везет скорее в постижении тайн природы.$B$BНет, конечно, я это сделаю. Возможно, это именно то, чего нам недостает, чтобы узнать о судьбе Раскала. Давай сюда нож, и возьмемся за дело.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4130,'Сверхзнание','Извини, меня до сих пор немного пошатывает. Как бы то ни было, я увидел несколько полезных вещей.$b$bРаскал вытащил два больших кожаных заплечных мешка из своей лодки и направился прочь от воды. Однако потом вернулся к лодке. Вижу скальпы гноллов... он наткнулся на гноллов – кажется, это тот клан, который называют Древолапами. Он чем-то очень озабочен, даже вроде бы напуган. Раскал настолько поглощен своими мыслями, что не замечает, как у него за спиной материализуются элементали воды. И... и все. Больше я ничего не увидел.$b$bИзвини, $n. Мне необходимо отдохнуть. Расскажи Гину о том, что я видел. Ему следует это знать...','Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.','Спасибо, что $Gрассказал:рассказала; мне о видениях Кинта, $N. Так и быть, в следующий раз, как мы с ним сядем за карты, постараюсь быть к нему подобрее.$B$BНу, в бою Раскал никому не уступит, и гноллы – не те, кто может его обеспокоить, тем более, напугать. Но, может быть, эти новые сведения тебе все же пригодятся?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сверхзнание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Извини, меня до сих пор немного пошатывает. Как бы то ни было, я увидел несколько полезных вещей.$b$bРаскал вытащил два больших кожаных заплечных мешка из своей лодки и направился прочь от воды. Однако потом вернулся к лодке. Вижу скальпы гноллов... он наткнулся на гноллов – кажется, это тот клан, который называют Древолапами. Он чем-то очень озабочен, даже вроде бы напуган. Раскал настолько поглощен своими мыслями, что не замечает, как у него за спиной материализуются элементали воды. И... и все. Больше я ничего не увидел.$b$bИзвини, $n. Мне необходимо отдохнуть. Расскажи Гину о том, что я видел. Ему следует это знать...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гинро Пылающим Очагом в Крепости Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что $Gрассказал:рассказала; мне о видениях Кинта, $N. Так и быть, в следующий раз, как мы с ним сядем за карты, постараюсь быть к нему подобрее.$B$BНу, в бою Раскал никому не уступит, и гноллы – не те, кто может его обеспокоить, тем более, напугать. Но, может быть, эти новые сведения тебе все же пригодятся?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4131,'Гноллы из стаи Древолапов','Возможно, Раскала сцапали наши "друзья" из клана Древолапов, но что-то мне подсказывает, что дело было не так. И все равно начать лучше всего с их лагерей.$b$bКонечно, хотелось бы иметь более отчетливые сведения, но пока что у нас нет ничего, кроме смутного указания на лагеря гноллов. Я знаю, что гноллы хранят у себя награбленное и дерутся из-за добычи. Возможно, они просто наткнулись на заплечные мешки, которые упоминал Кинт. Прежде я не рисковал соваться к гноллам, но теперь, когда у нас есть сведения, полученные от Кинта, попробовать стоит.','Обыщите лагеря Древолапов в южном Фераласе в поисках вещей курьера либо самого курьера.','На ближайшем дереве висят два больших кожаных мешка. На обоих виднеется метка Крепости Оперенной Луны...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гноллы из стаи Древолапов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, Раскала сцапали наши "друзья" из клана Древолапов, но что-то мне подсказывает, что дело было не так. И все равно начать лучше всего с их лагерей.$b$bКонечно, хотелось бы иметь более отчетливые сведения, но пока что у нас нет ничего, кроме смутного указания на лагеря гноллов. Я знаю, что гноллы хранят у себя награбленное и дерутся из-за добычи. Возможно, они просто наткнулись на заплечные мешки, которые упоминал Кинт. Прежде я не рисковал соваться к гноллам, но теперь, когда у нас есть сведения, полученные от Кинта, попробовать стоит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите лагеря Древолапов в южном Фераласе в поисках вещей курьера либо самого курьера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На ближайшем дереве висят два больших кожаных мешка. На обоих виднеется метка Крепости Оперенной Луны...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4132,'Операция:смерть Кузне Гнева','Ты $gпроделал:проделала; отличную работу, $n! Теперь пришло время для последнего задания. $B$BГенерал Кузня Гнева, ответственный за атаки Черного Железа на 109-ое подразделение Каргатского экспедиционного корпуса и массовые убийства наших солдат, должен понести наказание. $B$BЭто непростое задание, но в случае успеха труды окупятся сторицей.','Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания.','Наконец-то! Возмездие настигло негодяя! Ты отлично $Gсражался:сражалась;, $N! Носи этот медальон как символ твоих заслуг перед Ордой и Каргатским экспедиционным корпусом.','Был ли уничтожен Мясник Черной горы?','Вернитесь к полководцу Клинозубу в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Операция:смерть Кузне Гнева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпроделал:проделала; отличную работу, $n! Теперь пришло время для последнего задания. $B$BГенерал Кузня Гнева, ответственный за атаки Черного Железа на 109-ое подразделение Каргатского экспедиционного корпуса и массовые убийства наших солдат, должен понести наказание. $B$BЭто непростое задание, но в случае успеха труды окупятся сторицей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Глубины Черной горы и убейте генерала Кузню Гнева. Вернитесь к полководцу Клинозубу по выполнении задания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то! Возмездие настигло негодяя! Ты отлично $Gсражался:сражалась;, $N! Носи этот медальон как символ твоих заслуг перед Ордой и Каргатским экспедиционным корпусом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Был ли уничтожен Мясник Черной горы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Клинозубу в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4133,'Вивиана Лягроб','Тенемагу Вивиан Лягроб нужна твоя помощь. Она сейчас в Бесплодных землях, на сторожевой заставе Каргат. Там недавно прошел слух о небезызвестном напитке, сваренном дворфами Черного Железа в Глубинах Черной горы, – вот она и отправилась проверить.$B$BПоговори с Вивиан. Она тебя ждет.','Переговорите с тенемагом Вивиан Лягроб в Каргате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вивиана Лягроб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тенемагу Вивиан Лягроб нужна твоя помощь. Она сейчас в Бесплодных землях, на сторожевой заставе Каргат. Там недавно прошел слух о небезызвестном напитке, сваренном дворфами Черного Железа в Глубинах Черной горы, – вот она и отправилась проверить.$B$BПоговори с Вивиан. Она тебя ждет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Переговорите с тенемагом Вивиан Лягроб в Каргате.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4134,'Украденный рецепт громоварского','Ходят слухи, что Харли Чернопых из клана Черного Железа украл рецепт эля. Говорят, этот эль, иначе – светлое громоварское – придает великую силу и храбрость тому, кто его употребит. Нам хотелось бы изучить состав этого напитка. Может быть, мы найдем и другое применение его удивительным свойствам... подходящее для целей Отрекшихся.$B$BОтправляйся в Глубины Черной горы, найди Харли, забери у него рецепт светлого громоварского и принеси его мне.$B$BВозможно, тебе придется выманить Харли из укрытия. Для этого пригрози ему уничтожением его драгоценного эля.','Принесите рецепт светлого громоварского Вивиан Лягроб в Каргат.','Вот и славно. Я отошлю рецепт в Район Фармацевтов. Его там изучат, и со временем мы раскроем его секреты. И, возможно, придет такой день, когда дворфы Альянса с удивлением обнаружат, что волшебные свойства их тайного напитка против них же и обернулись!$B$BПо-моему, это будет забавно. Видимо, смерть как-то странно влияет на чувство юмора... ты не находишь?','Ты $Gдобыл:добыла; рецепт, $N?','Вернитесь к темному магу Вивиане Лягроб к скелету Апокрифана, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Украденный рецепт громоварского',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, что Харли Чернопых из клана Черного Железа украл рецепт эля. Говорят, этот эль, иначе – светлое громоварское – придает великую силу и храбрость тому, кто его употребит. Нам хотелось бы изучить состав этого напитка. Может быть, мы найдем и другое применение его удивительным свойствам... подходящее для целей Отрекшихся.$B$BОтправляйся в Глубины Черной горы, найди Харли, забери у него рецепт светлого громоварского и принеси его мне.$B$BВозможно, тебе придется выманить Харли из укрытия. Для этого пригрози ему уничтожением его драгоценного эля.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите рецепт светлого громоварского Вивиан Лягроб в Каргат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и славно. Я отошлю рецепт в Район Фармацевтов. Его там изучат, и со временем мы раскроем его секреты. И, возможно, придет такой день, когда дворфы Альянса с удивлением обнаружат, что волшебные свойства их тайного напитка против них же и обернулись!$B$BПо-моему, это будет забавно. Видимо, смерть как-то странно влияет на чувство юмора... ты не находишь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдобыл:добыла; рецепт, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному магу Вивиане Лягроб к скелету Апокрифана, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4135,'Гудящая Бездна','В рюкзаках находится два предмета: во-первых, посылка, адресованная в Таланаар, а во-вторых – записка, адресованная неизвестно кому.$b$bВ записке, набросанной торопливым почерком, говорится об обнаружении коварных насекомоподобных существ к югу от лагерей гноллов, в лесах, известных как "Гудящая Бездна". Автор сообщает, что намерен лично проникнуть туда, поскольку речь может идти о серьезной опасности, грозящей всему Фераласу. Записка подписана "Раскал из Оперенной Луны".$b$bПохоже, вам наконец-то удалось выяснить, куда делся Раскал...','Продолжайте поиски Раскала (или его останков) в Гудящей Бездне. Согласно записке, Гудящая Бездна находится к югу от лагерей стаи Древолапов.','Вам удалось обнаружить огромный кокон непонятного происхождения. Сам кокон мягкий и слизистый, но изнутри в разных местах выпирает что-то твердое. Размеры кокона позволяют предположить, что внутри может находиться гуманоид среднего роста... и сквозь стенки кокона действительно просвечивают очертания фигуры гуманоида!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гудящая Бездна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В рюкзаках находится два предмета: во-первых, посылка, адресованная в Таланаар, а во-вторых – записка, адресованная неизвестно кому.$b$bВ записке, набросанной торопливым почерком, говорится об обнаружении коварных насекомоподобных существ к югу от лагерей гноллов, в лесах, известных как "Гудящая Бездна". Автор сообщает, что намерен лично проникнуть туда, поскольку речь может идти о серьезной опасности, грозящей всему Фераласу. Записка подписана "Раскал из Оперенной Луны".$b$bПохоже, вам наконец-то удалось выяснить, куда делся Раскал...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Продолжайте поиски Раскала (или его останков) в Гудящей Бездне. Согласно записке, Гудящая Бездна находится к югу от лагерей стаи Древолапов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вам удалось обнаружить огромный кокон непонятного происхождения. Сам кокон мягкий и слизистый, но изнутри в разных местах выпирает что-то твердое. Размеры кокона позволяют предположить, что внутри может находиться гуманоид среднего роста... и сквозь стенки кокона действительно просвечивают очертания фигуры гуманоида!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4136,'Риббли Крутипроб','Мой братец Риббли всегда только и делал, что тянул денежки из семьи и тратил их на какие-то поганые махинации.$B$BПохоже, последний его проект оказался поганее прочих, потому что барон Ревилгаз из Пиратской Бухты назначил награду за голову бедняжки Риббли. Ты даже не представляешь, как возрадовались все Крутипробы! Наш малыш Риббли наконец хоть чего-то да стоит!$B$BНо сейчас он скрывается в Глубинах Черной горы. Найди его и приведи ко мне!$B$BА если он не пойдет добром... ну что ж, не пойдет – и не надо... тогда принеси мне его голову.','Принесите голову Риббли Юке Крутипроб в Пылающие степи.','Ты привел Риббли? Хотя меня больше интересует не столько он сам, сколько его голова.','Вернитесь к Юке Крутипроб в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Риббли Крутипроб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой братец Риббли всегда только и делал, что тянул денежки из семьи и тратил их на какие-то поганые махинации.$B$BПохоже, последний его проект оказался поганее прочих, потому что барон Ревилгаз из Пиратской Бухты назначил награду за голову бедняжки Риббли. Ты даже не представляешь, как возрадовались все Крутипробы! Наш малыш Риббли наконец хоть чего-то да стоит!$B$BНо сейчас он скрывается в Глубинах Черной горы. Найди его и приведи ко мне!$B$BА если он не пойдет добром... ну что ж, не пойдет – и не надо... тогда принеси мне его голову.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Риббли Юке Крутипроб в Пылающие степи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты привел Риббли? Хотя меня больше интересует не столько он сам, сколько его голова.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Юке Крутипроб в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4141,'Муиджин и Ларион','Видишь Лариона вон там? Это ОН виноват, что мы застряли здесь! $B$BЯ говорил ему, что мы идем не туда, но разве он меня слушал? И представляешь, после этого он еще и не желает со мной разговаривать! Ну, пока он не передумает, я позабавлюсь! $B$BТы $gзаметил:заметила; здесь таких странных созданий, похожих на цветы? На самом деле это довольно умные зверушки. Думаю, их можно надрессировать на всякие фокусы. $B$BВ первую очередь, мне нужны образцы для изучения. Сможешь принести мне несколько?','Соберите 15 кровоцветов и принесите их Муиджину.','Надеюсь, они не доставили тебе забот, $N? Крайне дикие создания!$B$BОднажды я попытался перепрыгнуть через один такой цветочек, так он напал на меня! Растения не должны так себя вести...','Ну, $N, ты $Gсам:сама; $Gнарвался:нарвалась;...','Вернитесь к Муиджину в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Муиджин и Ларион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь Лариона вон там? Это ОН виноват, что мы застряли здесь! $B$BЯ говорил ему, что мы идем не туда, но разве он меня слушал? И представляешь, после этого он еще и не желает со мной разговаривать! Ну, пока он не передумает, я позабавлюсь! $B$BТы $gзаметил:заметила; здесь таких странных созданий, похожих на цветы? На самом деле это довольно умные зверушки. Думаю, их можно надрессировать на всякие фокусы. $B$BВ первую очередь, мне нужны образцы для изучения. Сможешь принести мне несколько?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 кровоцветов и принесите их Муиджину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, они не доставили тебе забот, $N? Крайне дикие создания!$B$BОднажды я попытался перепрыгнуть через один такой цветочек, так он напал на меня! Растения не должны так себя вести...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, $N, ты $Gсам:сама; $Gнарвался:нарвалась;...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муиджину в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4142,'Визит к Грегану','Не знаю, что и сказать тебе, $n. У этих растений, видимо, имеются зачатки разума. $B$BВпрочем, я не специалист. Однако знаю, к кому обратиться за действительно профессиональным мнением. $B$BОтправляйся в Фералас и найди там моего приятеля по имени Греган Пивоплюй. Он на таких вещах собаку съел. $B$BУверен, Греган сможет дать нам действительно дельный совет. Думаю, искать его лучше где-нибудь в лесу – парень никак не городской житель.','Отнесите кровоцвет Грегану Пивоплюю в Фералас.','Надеюсь, они не доставили тебе забот, $N? Крайне дикие создания!$B$BОднажды я попытался перепрыгнуть через один такой цветочек, так он напал на меня! Растения не должны так себя вести...','Я живу здесь, в лесу... Очень, знаешь ли, спокойно и благостно.$B$BПо крайней мере я сам так думал. Теперь ко мне шастает столько гостей, сколько я не видал в худшие дни в Стальгорне! Просто проходной двор какой-то!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Визит к Грегану',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, что и сказать тебе, $n. У этих растений, видимо, имеются зачатки разума. $B$BВпрочем, я не специалист. Однако знаю, к кому обратиться за действительно профессиональным мнением. $B$BОтправляйся в Фералас и найди там моего приятеля по имени Греган Пивоплюй. Он на таких вещах собаку съел. $B$BУверен, Греган сможет дать нам действительно дельный совет. Думаю, искать его лучше где-нибудь в лесу – парень никак не городской житель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кровоцвет Грегану Пивоплюю в Фералас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, они не доставили тебе забот, $N? Крайне дикие создания!$B$BОднажды я попытался перепрыгнуть через один такой цветочек, так он напал на меня! Растения не должны так себя вести...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я живу здесь, в лесу... Очень, знаешь ли, спокойно и благостно.$B$BПо крайней мере я сам так думал. Теперь ко мне шастает столько гостей, сколько я не видал в худшие дни в Стальгорне! Просто проходной двор какой-то!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4143,'Туман зла','Честно говоря, $n, мне никогда прежде не доводилось видеть подобных растений. Возможно, имеет смысл наведаться в этот кратер... $B$BВ любом случае, думаю, что знаю, что именно ищет Муиджин. Ему нужен туман Аталаи. Это жуткая субстанция, которую весьма сложно собрать, однако именно этот туман необходим ему, чтобы управлять маленькими монстрами. $B$BТебе нужно найти Храм Атал\'Хаккара на Болоте Печали. Туман Аталаи можно собрать с обитающих там глубинных скрытней, мракочервей и слизнюков. Удачи тебе, $n!','Соберите 5 образцов тумана Аталаи и принесите их Муиджину в Кратер Ун\'Горо.','Признаю, мне очень боязно прикасаться с этой штуке, $N! Но раз Греган утверждает, что она работает, надо попробовать.','$N, все еще не разговаривает со мной! Надо же, надулся, как мышь на крупу.','Вернитесь к Муиджину в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Туман зла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Честно говоря, $n, мне никогда прежде не доводилось видеть подобных растений. Возможно, имеет смысл наведаться в этот кратер... $B$BВ любом случае, думаю, что знаю, что именно ищет Муиджин. Ему нужен туман Аталаи. Это жуткая субстанция, которую весьма сложно собрать, однако именно этот туман необходим ему, чтобы управлять маленькими монстрами. $B$BТебе нужно найти Храм Атал\'Хаккара на Болоте Печали. Туман Аталаи можно собрать с обитающих там глубинных скрытней, мракочервей и слизнюков. Удачи тебе, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 образцов тумана Аталаи и принесите их Муиджину в Кратер Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Признаю, мне очень боязно прикасаться с этой штуке, $N! Но раз Греган утверждает, что она работает, надо попробовать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, все еще не разговаривает со мной! Надо же, надулся, как мышь на крупу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муиджину в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4144,'Ростки кровоцвета','Ну, приступим, $N! Уж это привлечет внимание Лариона, будь $Gуверен:уверена;!','Слушай мой план, $N: пойди и собери для меня немного побегов кровоцвета – молодых, которые еще не успели полностью развиться. А потом посмотрим, как они отреагируют на туман Аталаи.$B$BТы думаешь, я слишком злопамятен? Ну, в общем так и есть.$B$BНа самом деле, я знаю дорогу отсюда, но пока Ларион не признает мою правоту, я отсюда не уйду.$B$BНу, иди, принеси мне побегов, и мы славно повеселимся!','Вернитесь к Муиджину в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ростки кровоцвета',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, приступим, $N! Уж это привлечет внимание Лариона, будь $Gуверен:уверена;!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Слушай мой план, $N: пойди и собери для меня немного побегов кровоцвета – молодых, которые еще не успели полностью развиться. А потом посмотрим, как они отреагируют на туман Аталаи.$B$BТы думаешь, я слишком злопамятен? Ну, в общем так и есть.$B$BНа самом деле, я знаю дорогу отсюда, но пока Ларион не признает мою правоту, я отсюда не уйду.$B$BНу, иди, принеси мне побегов, и мы славно повеселимся!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муиджину в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4145,'Ларион и Муиджин','Видишь там Муиджина? Это ОН виноват, что мы потерялись! $B$BЯ знал дорогу, но он настоял на том, чтобы пойти "коротким путем" и вот! Мы застряли в этой дыре! $B$BЧто еще хуже, он теперь взялся натравливать на меня этих проклятых паразитов – кровоцветов! Я так зол, что не собираюсь говорить с ним. А эти паразиты – просто последняя капля! $B$BДумаю, в первую очередь мы перекроем ему снабжение! Пойди-ка, поохоться на кровоцветы, а потом возвращайся ко мне.','Уничтожьте 5 кровоцветов-хлестунов, 5 кровоцветов-крепкозубов, 5 кровоцветов-живодеров и 5 кровоцветов-звероловов по просьбе Лариона из Укрытия Маршалла.','Спасибо за помощь, $N, однако боюсь, у меня плохие новости...','$N должен сначала извиниться, прежде чем я снова с ним поговорю!','Вернитесь к Лариону в Укрытие Маршалла, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ларион и Муиджин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь там Муиджина? Это ОН виноват, что мы потерялись! $B$BЯ знал дорогу, но он настоял на том, чтобы пойти "коротким путем" и вот! Мы застряли в этой дыре! $B$BЧто еще хуже, он теперь взялся натравливать на меня этих проклятых паразитов – кровоцветов! Я так зол, что не собираюсь говорить с ним. А эти паразиты – просто последняя капля! $B$BДумаю, в первую очередь мы перекроем ему снабжение! Пойди-ка, поохоться на кровоцветы, а потом возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 кровоцветов-хлестунов, 5 кровоцветов-крепкозубов, 5 кровоцветов-живодеров и 5 кровоцветов-звероловов по просьбе Лариона из Укрытия Маршалла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь, $N, однако боюсь, у меня плохие новости...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N должен сначала извиниться, прежде чем я снова с ним поговорю!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лариону в Укрытие Маршалла, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4146,'Питание для шокера','Тебе повезло, $n! Я тут работала над кой-какими собственными изобретениями, пока Марвон в отъезде. И вот моя последняя разработка – антижучиный шокер ближнего действия! Его надо совсем чуть-чуть поправить, и можно смело использовать против кровоцветов-паразитов. С удовольствием подарю тебе одну из моих тестовых моделей, однако для нее необходимо питание – туман Аталаи. Его можно собрать в Храме Атал\'Хаккара с обитающих там трясинных скрытней, мракочервей и слизнюков.','Доставьте незаряженный шокер и 5 образцов тумана Аталаи Лариону в Укрытие Маршалла.','Так Марвона там не было? И что же ты оттуда $Gпринес:принесла;?','Эти твари меня достали, $N! Просто достали!','Вернитесь к Лариону в Укрытие Маршалла, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Питание для шокера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе повезло, $n! Я тут работала над кой-какими собственными изобретениями, пока Марвон в отъезде. И вот моя последняя разработка – антижучиный шокер ближнего действия! Его надо совсем чуть-чуть поправить, и можно смело использовать против кровоцветов-паразитов. С удовольствием подарю тебе одну из моих тестовых моделей, однако для нее необходимо питание – туман Аталаи. Его можно собрать в Храме Атал\'Хаккара с обитающих там трясинных скрытней, мракочервей и слизнюков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте незаряженный шокер и 5 образцов тумана Аталаи Лариону в Укрытие Маршалла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так Марвона там не было? И что же ты оттуда $Gпринес:принесла;?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти твари меня достали, $N! Просто достали!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лариону в Укрытие Маршалла, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4147,'Мастерская Марвона','Мне удалось проследить за Муиджином – он и впрямь выращивает эти проклятые растения! $B$BДумаю, единственным решением будет... Нет, говорить с ним бесполезно, надо готовиться к ответному удару! $B$BНам потребуется помощь моего друга Марвона, у него мастерская в Кабестане.','Отправьтесь к Марвону Клепальщику в его мастерскую в Кабестане.','Марвона здесь давно нет, $N. Он отправился в Танарис, изучать развалины древних поселений троллей.$B$BА зачем он был тебе нужен?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастерская Марвона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне удалось проследить за Муиджином – он и впрямь выращивает эти проклятые растения! $B$BДумаю, единственным решением будет... Нет, говорить с ним бесполезно, надо готовиться к ответному удару! $B$BНам потребуется помощь моего друга Марвона, у него мастерская в Кабестане.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь к Марвону Клепальщику в его мастерскую в Кабестане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Марвона здесь давно нет, $N. Он отправился в Танарис, изучать развалины древних поселений троллей.$B$BА зачем он был тебе нужен?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4148,'Антикровоцветный шокер','Похоже, это устройство прекрасно сработает, $N. Помни, как только заметишь где-нибудь этих паразитов, немедленно используй шокер!','Чтобы шокер заработал, необходим образец его цели – кровоцвета. Отправляйся в кратер и принеси мне побег кровоцвета, а я уж настрою прибор на милых маленьких дружков Майджина...$B$BЕсли бы он не был так упрям, мы давно уже выбрались бы из этого проклятого места... Но пока я должен показать ему, что его шуточки меня ничуть не беспокоят!','Вернитесь к Лариону в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Антикровоцветный шокер',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, это устройство прекрасно сработает, $N. Помни, как только заметишь где-нибудь этих паразитов, немедленно используй шокер!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы шокер заработал, необходим образец его цели – кровоцвета. Отправляйся в кратер и принеси мне побег кровоцвета, а я уж настрою прибор на милых маленьких дружков Майджина...$B$BЕсли бы он не был так упрям, мы давно уже выбрались бы из этого проклятого места... Но пока я должен показать ему, что его шуточки меня ничуть не беспокоят!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лариону в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4161,'Калдорайский рецепт','Давным-давно ночные эльфы назывались калдорай, "дети звезд". Изучение прошлого – важный шаг на пути |3-1($c), $n, так что слушай внимательно все, что я расскажу тебе.$B$BКалдорай всегда гордились тем, что живут в гармонии с природой. Это означает, что мы берем у природы только то, что нам необходимо, и воздаем ей сторицей. Это равновесие позволяло нам добиться многого, $n.$B$BСтупай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне.','Принесите 7 маленьких паучьих лапок.','Return to Zarrin in Dolanaar.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Калдорайский рецепт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно ночные эльфы назывались калдорай, "дети звезд". Изучение прошлого – важный шаг на пути |3-1($c), $n, так что слушай внимательно все, что я расскажу тебе.$B$BКалдорай всегда гордились тем, что живут в гармонии с природой. Это означает, что мы берем у природы только то, что нам необходимо, и воздаем ей сторицей. Это равновесие позволяло нам добиться многого, $n.$B$BСтупай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 маленьких паучьих лапок.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Zarrin in Dolanaar.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4181,'Гоблинское инженерное дело','В инженерном деле есть две дисциплины: гномская и гоблинская. Я – честный учитель, и только поэтому упомянул гоблинское инженерное дело. Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер.$b$b$n, почитай этот справочник. Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск. Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого.','Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.','Что же, $N, ты разумно поступаешь, прося у меня наставничества! Любой дурак может стать экспертом в азах инженерного дела – что прекрасно видно на примере гномов и их радиоактивного Гномрегана. Для овладения гоблинским инженерным делом требуется крепкая соображаловка и твердая (повторяю – ТВЕРДАЯ) рука.$B$BДержи ушки на макушке, $N, может, что и усвоишь.','Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гоблинское инженерное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В инженерном деле есть две дисциплины: гномская и гоблинская. Я – честный учитель, и только поэтому упомянул гоблинское инженерное дело. Видишь ли, гоблины обожают делать всякие взрывоопасные штучки и редко заботятся о том, что окажется на пути такой штучки – даже если это будет сам инженер.$b$b$n, почитай этот справочник. Если хочешь узнать, как эффектно покончить с собой, отнеси его к Никсу Шепружину в Прибамбасск. Помни – выбор твой не подлежит пересмотру, сменить дисциплину ты не сможешь; так что прежде, чем выполнить задание, что даст тебе Никс, убедись, что ты хочешь именно этого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что же, $N, ты разумно поступаешь, прося у меня наставничества! Любой дурак может стать экспертом в азах инженерного дела – что прекрасно видно на примере гномов и их радиоактивного Гномрегана. Для овладения гоблинским инженерным делом требуется крепкая соображаловка и твердая (повторяю – ТВЕРДАЯ) рука.$B$BДержи ушки на макушке, $N, может, что и усвоишь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Новичков я чую за версту – лучше, чем самый качественный порох. Ты ведь желаешь приобщиться к великому искусству изготовления взрывчатки?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4182,'Драконья угроза','Жизнь в Пылающих степях никогда не бывает спокойной.$b$bТолько посмотри вокруг! Мы не знаем, что случилось с этими строениями, но до большого взрыва все это было частью Красногорья.$b$bНо довольно скулить! У нас есть более насущная проблема. Может быть, ты $gзаметил:заметила; драконов под этим хребтом. Необходимо вынудить их отступить. Убей как можно больше и возвращайся. Если ты добьешься успеха, я дам тебе другое задание.','Убейте 15 детенышей черного дракона, 10 черных драконоидов, 4 черных драконид и 1 черного дракона.','Добрая охота, $N. Ну, раз ты можешь справиться с драконами и их прихвостнями, пора поговорить о более насущных проблемах.','Как проходит охота на драконов?','Вернитесь к Хелендису Речному Мысу в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Драконья угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жизнь в Пылающих степях никогда не бывает спокойной.$b$bТолько посмотри вокруг! Мы не знаем, что случилось с этими строениями, но до большого взрыва все это было частью Красногорья.$b$bНо довольно скулить! У нас есть более насущная проблема. Может быть, ты $gзаметил:заметила; драконов под этим хребтом. Необходимо вынудить их отступить. Убей как можно больше и возвращайся. Если ты добьешься успеха, я дам тебе другое задание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 детенышей черного дракона, 10 черных драконоидов, 4 черных драконид и 1 черного дракона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добрая охота, $N. Ну, раз ты можешь справиться с драконами и их прихвостнями, пора поговорить о более насущных проблемах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как проходит охота на драконов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хелендису Речному Мысу в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4183,'Подлинные хозяева','Мы всегда думали, что орки Черной горы такие жестокие от природы. Оказывается, дело обстоит иначе.$B$BДа, их и правда ведет в бой жажда крови и любовь к сражениям, но руководят ими черные драконы. Мы подозреваем, что именно они возбуждают в них ярость и злобу.$B$BОтнеси это письмо мировому судье Соломону. Он скажет, что делать.$B$B<Хелендис протягивает вам запечатанное письмо.>','Отправьтесь в Приозерье, что в Красногорье, и доставьте письмо Хелендиса Речного Мыса мировому судье Соломону.','<Мировой судья Соломон распечатывает письмо от Хелендиса и начинает читать.>','Приветствую тебя, $N. Мы уже встречались? Твое лицо кажется мне знакомым.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подлинные хозяева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы всегда думали, что орки Черной горы такие жестокие от природы. Оказывается, дело обстоит иначе.$B$BДа, их и правда ведет в бой жажда крови и любовь к сражениям, но руководят ими черные драконы. Мы подозреваем, что именно они возбуждают в них ярость и злобу.$B$BОтнеси это письмо мировому судье Соломону. Он скажет, что делать.$B$B<Хелендис протягивает вам запечатанное письмо.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь в Приозерье, что в Красногорье, и доставьте письмо Хелендиса Речного Мыса мировому судье Соломону.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мировой судья Соломон распечатывает письмо от Хелендиса и начинает читать.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя, $N. Мы уже встречались? Твое лицо кажется мне знакомым.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4184,'Подлинные хозяева','Дурные вести, $n. Нетрудно прийти в отчаяние, узнав, что твои смертельные враги – всего лишь пешки куда более страшного противника. Приозерью не пережить натиска орков Черной горы и черных драконов. Если падет Приозерье, следующим будет Темнолесье, а что потом? Златоземье? Сам Штормград?$B$BНемедленно отнеси это сообщение королю Вариану Ринну в Штормград! Если мы и этим не добьемся от столицы помощи, то не добьемся никакими силами, и все пропало.','Передайте обращение Соломона королю Вариану Ринну.$B$BКороль Ринн пребывает в крепости Штормграда.','Драконы? Быть того не может!','Что привело тебя в Крепость Штормграда?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подлинные хозяева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дурные вести, $n. Нетрудно прийти в отчаяние, узнав, что твои смертельные враги – всего лишь пешки куда более страшного противника. Приозерью не пережить натиска орков Черной горы и черных драконов. Если падет Приозерье, следующим будет Темнолесье, а что потом? Златоземье? Сам Штормград?$B$BНемедленно отнеси это сообщение королю Вариану Ринну в Штормград! Если мы и этим не добьемся от столицы помощи, то не добьемся никакими силами, и все пропало.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте обращение Соломона королю Вариану Ринну.$B$BКороль Ринн пребывает в крепости Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Драконы? Быть того не может!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что привело тебя в Крепость Штормграда?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (4185,'Подлинные хозяева','Грустную картину нарисовал Соломон. Тем не менее, мы не можем позволить себе посылать наши и без того скудные войска на помощь Приозерью, основываясь только на догадках. Мне понадобится доказательство правоты его заявлений, прежде чем я смогу предпринять какие-то действия.$b$bПоговорите с леди Престор, $n. Она женщина ученая и много чего знает о драконах и драконидах. Возможно, она сможет пролить какой-то свет на эту ситуацию.','Поговорите с Верховным лордом Болваром Фордрагоном после беседы с леди Катраной Престор.','<Болвар подпирает рукой подбородок, как бы глубоко задумавшись.>$B$BВ то время как я уважаю позицию леди Престор, я уверен, что для этой дилеммы есть решение, которое могло бы развеять все наши тревоги.','<Болвар пристально смотрит на вас.>','Совет от госпожи Престор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подлинные хозяева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грустную картину нарисовал Соломон. Тем не менее, мы не можем позволить себе посылать наши и без того скудные войска на помощь Приозерью, основываясь только на догадках. Мне понадобится доказательство правоты его заявлений, прежде чем я смогу предпринять какие-то действия.$b$bПоговорите с леди Престор, $n. Она женщина ученая и много чего знает о драконах и драконидах. Возможно, она сможет пролить какой-то свет на эту ситуацию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховным лордом Болваром Фордрагоном после беседы с леди Катраной Престор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Болвар подпирает рукой подбородок, как бы глубоко задумавшись.>$B$BВ то время как я уважаю позицию леди Престор, я уверен, что для этой дилеммы есть решение, которое могло бы развеять все наши тревоги.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Болвар пристально смотрит на вас.>',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Совет от госпожи Престор',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4186,'Подлинные хозяева','Я намерен наделить вас полномочиями представителя, действующего от имени Штормграда, $n.$b$bВозвращайтесь к мировому судье Соломону в Приозерье и передайте ему этот указ.','Отнесите указ Ринна мировому судье Соломону в Приозерье.','Ну, полагаю, могло быть и хуже...$B$B<Мировой судья изучает вас взглядом.>$B$BПохоже, что судьба Озер ложится теперь на ваши плечи.$B$B<Вы замечаете, что мировой судья часто-часто моргает. Кажется, он плачет.>','Есть какие-то новости от лорда Болвара?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подлинные хозяева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я намерен наделить вас полномочиями представителя, действующего от имени Штормграда, $n.$b$bВозвращайтесь к мировому судье Соломону в Приозерье и передайте ему этот указ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите указ Ринна мировому судье Соломону в Приозерье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, полагаю, могло быть и хуже...$B$B<Мировой судья изучает вас взглядом.>$B$BПохоже, что судьба Озер ложится теперь на ваши плечи.$B$B<Вы замечаете, что мировой судья часто-часто моргает. Кажется, он плачет.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть какие-то новости от лорда Болвара?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4201,'Приворотное зелье','О, терзания и муки неразделенной любви! Мои чары не действуют на возлюбленного. Рядовой Камнеузл отвергает меня! Это невыносимо!$B$BТы $gдолжен:должна; мне помочь! Мы, суккубы, хорошо разбираемся в любовных делах, и я могу приготовить волшебное зелье, которое разрушит железную стену вокруг непреклонного сердца Камнеузла. Для того чтобы сварить это зелье, мне нужна трава кровь Грома, серебряные слитки скальных великанов Азшары и вода из источников Голакка в Кратере Ун\'Горо. Воду можешь набрать в этот сосуд.$B$BПрошу тебя, $n, помоги моей бедной истерзанной душе обрести радость и счастье!','Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы.','Ты принес все, что нужно? Боль в моем сердце растет с каждым днем!','Вернитесь к госпоже Нагмаре в Глубины Черной горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приворотное зелье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, терзания и муки неразделенной любви! Мои чары не действуют на возлюбленного. Рядовой Камнеузл отвергает меня! Это невыносимо!$B$BТы $gдолжен:должна; мне помочь! Мы, суккубы, хорошо разбираемся в любовных делах, и я могу приготовить волшебное зелье, которое разрушит железную стену вокруг непреклонного сердца Камнеузла. Для того чтобы сварить это зелье, мне нужна трава кровь Грома, серебряные слитки скальных великанов Азшары и вода из источников Голакка в Кратере Ун\'Горо. Воду можешь набрать в этот сосуд.$B$BПрошу тебя, $n, помоги моей бедной истерзанной душе обрести радость и счастье!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 листа крови Грома, 10 огромных серебряных слитков и наполненный сосуд Нагмары госпоже Нагмаре в Глубины Черной горы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес все, что нужно? Боль в моем сердце растет с каждым днем!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к госпоже Нагмаре в Глубины Черной горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (4221,'Оскверненный ветроцвет','Вернитесь к оскверненному ветроцвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный ветроцвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному ветроцвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (4222,'Оскверненный ветроцвет','Вернитесь к оскверненному ветроцвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный ветроцвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному ветроцвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4223,'Подлинные хозяева','*Мировой судья вздыхает.*$B$BВозвращайся в Пылающие степи, $n. Как представитель Штормграда ты $gдолжен:должна; предстать перед маршалом Максвеллом. Удачи.','Поговорите с маршалом Максвеллом в Пылающих степях.','<Маршал Максвелл смеется.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подлинные хозяева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Мировой судья вздыхает.*$B$BВозвращайся в Пылающие степи, $n. Как представитель Штормграда ты $gдолжен:должна; предстать перед маршалом Максвеллом. Удачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с маршалом Максвеллом в Пылающих степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Маршал Максвелл смеется.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4224,'Подлинные хозяева','Что? Думаешь, ты $Gпервый:первая;? Сколько же еще мы должны потерять солдат прежде, чем Штормград начнет шевелиться?$B$BМы собрали целую кучу разведданных касательно угрозы со стороны Черной горы до того, как потеряли нашего командира, маршала Виндзора. С ним пропала и вся наша бесценная информация.$B$BНам просто необходимы эти документы. Поговори с Джоном-Оборванцем, $n. Он был при Виндзоре, когда на них налетел рейд Черной горы. Последний раз его видели в пещере к северу отсюда.','Поговорите с Джоном-Оборванцем.','Я мог бы тебя предупредить, но разве это интересно?','Ты уже $Gпоговорил:поговорила; с Джоном?','История Джона-Оборванца','Вернитесь к маршалу Максвеллу в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подлинные хозяева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что? Думаешь, ты $Gпервый:первая;? Сколько же еще мы должны потерять солдат прежде, чем Штормград начнет шевелиться?$B$BМы собрали целую кучу разведданных касательно угрозы со стороны Черной горы до того, как потеряли нашего командира, маршала Виндзора. С ним пропала и вся наша бесценная информация.$B$BНам просто необходимы эти документы. Поговори с Джоном-Оборванцем, $n. Он был при Виндзоре, когда на них налетел рейд Черной горы. Последний раз его видели в пещере к северу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джоном-Оборванцем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я мог бы тебя предупредить, но разве это интересно?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gпоговорил:поговорила; с Джоном?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','История Джона-Оборванца',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Максвеллу в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4241,'Маршал Винздор','Значит, этот жалкий трус говорит, что Виндзор жив?$B$BГотовься, тебе предстоит отправиться на его поиски. Если Виндзор жив, спаси его. Если мертв – принеси мне доказательства его гибели.$B$B*Максвелл смеется.*$B$BТебе, наверное, надоело это слышать?','Отправляйтесь на Черную гору на северо-западе и войдите в Глубины Черной горы. Узнайте, что сталось с маршалом Виндзором.$B$BКажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу.','Где он! Я убью его!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маршал Винздор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, этот жалкий трус говорит, что Виндзор жив?$B$BГотовься, тебе предстоит отправиться на его поиски. Если Виндзор жив, спаси его. Если мертв – принеси мне доказательства его гибели.$B$B*Максвелл смеется.*$B$BТебе, наверное, надоело это слышать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Черную гору на северо-западе и войдите в Глубины Черной горы. Узнайте, что сталось с маршалом Виндзором.$B$BКажется, Джон-Оборванец говорил о том, что Виндзора утащили в темницу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Где он! Я убью его!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4242,'Утраченная надежда','Болвар – жалкий дурак. Я собирал все его драгоценные "доказательства" только для того, чтобы засунуть их ему же в глотку.$B$BНедоумок! Слепой идиот! Доказательство стоит в двух шагах от него, а он ушами хлопает.$B$BЧто касается собранных мною сведений – вся информация утрачена, причем безвозвратно.$B$BЕсли я все-таки найду Железогубитель и выберусь из этого лабиринта, я первым делом отправлюсь в Штормград и вломлю ему молотом промеж глаз, этому подлому змею.$B$BОставь меня, $n.','Сообщите маршалу Максвеллу плохие новости. Его можно найти в Дозоре Морганы, что в Пылающих степях.','Вполне очевидно, что он повредился рассудком.$B$B<Максвелл скорбно склоняет голову.>$B$BПечально, когда благородный и доблестный воин превращается в невменяемого идиота. Как я понимаю, мы зашли в тупик...$B$BНо ты хорошо $Gпотрудился:потрудилась;, $N. И получишь награду.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утраченная надежда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Болвар – жалкий дурак. Я собирал все его драгоценные "доказательства" только для того, чтобы засунуть их ему же в глотку.$B$BНедоумок! Слепой идиот! Доказательство стоит в двух шагах от него, а он ушами хлопает.$B$BЧто касается собранных мною сведений – вся информация утрачена, причем безвозвратно.$B$BЕсли я все-таки найду Железогубитель и выберусь из этого лабиринта, я первым делом отправлюсь в Штормград и вломлю ему молотом промеж глаз, этому подлому змею.$B$BОставь меня, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите маршалу Максвеллу плохие новости. Его можно найти в Дозоре Морганы, что в Пылающих степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вполне очевидно, что он повредился рассудком.$B$B<Максвелл скорбно склоняет голову.>$B$BПечально, когда благородный и доблестный воин превращается в невменяемого идиота. Как я понимаю, мы зашли в тупик...$B$BНо ты хорошо $Gпотрудился:потрудилась;, $N. И получишь награду.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4243,'В поисках Чи-Та 3','Увы, что-то случилось с одним из моих величайших изобретений. Ты ведь $gвидел:видела; моих механических белок? Так вот, чтобы подобраться поближе к обезьянам, обитающим в Кратере Ун\'Горо, я создала механическую обезьяну, которая должна была смешаться со стаей. Я назвала ее Чи-Та 3. Ее глаза были сделаны из магических кристаллов, так что я могла видеть все, что видит она. Она успела добраться до Пещеры Лишайников – это логово обезьян к востоку отсюда – и там я потеряла с ней контакт. Последним, что я видела, был вожак стаи, который подбежал поздороваться с ней. $B$BТы поможешь мне разыскать ее?','Найдите Чи-Та 3 в Кратере Ун\'Горо.','Осмотрев Чи-Та 3, вы обнаруживаете две глубоких вмятины в творении инженерного искусства Карны. Одна вмятина украшает плечо робота, другая зияет на голове.$B$BПохоже, энергии в машине не осталось.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Чи-Та 3',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Увы, что-то случилось с одним из моих величайших изобретений. Ты ведь $gвидел:видела; моих механических белок? Так вот, чтобы подобраться поближе к обезьянам, обитающим в Кратере Ун\'Горо, я создала механическую обезьяну, которая должна была смешаться со стаей. Я назвала ее Чи-Та 3. Ее глаза были сделаны из магических кристаллов, так что я могла видеть все, что видит она. Она успела добраться до Пещеры Лишайников – это логово обезьян к востоку отсюда – и там я потеряла с ней контакт. Последним, что я видела, был вожак стаи, который подбежал поздороваться с ней. $B$BТы поможешь мне разыскать ее?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Чи-Та 3 в Кратере Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Осмотрев Чи-Та 3, вы обнаруживаете две глубоких вмятины в творении инженерного искусства Карны. Одна вмятина украшает плечо робота, другая зияет на голове.$B$BПохоже, энергии в машине не осталось.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4244,'В поисках Чи-Та 3','Внимательно осмотрев робота, вы замечаете отодвигающуюся панель, над которой значится: "Заменить мифриловую обшивку, затем выключить и включить питание". $B$BИнтересно, получится ли починить Чи-Ту 3 и доставить ее Карне Сомнамбулер в Укрытие Маршалла... $B$BНе попробуешь – не узнаешь.','Найдите мифриловую обшивку и вернитесь к Чи-Та 3 в Кратер Ун\'Горо.','Вы снова отдвигаете панель на спине Чи-Та 3 и осторожно вынимаете обгоревшую мифриловую обшивку, заменяя ее новой. Если действительно считать, что это и была основная причина поломки, то осталось лишь включить питание.','Панель, в которую необходимо вставить мифриловую обшивку, все еще закрыта. Чи-Та 3 лежит неподвижно.','Вернитесь к Чи-Та 3 в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Чи-Та 3',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимательно осмотрев робота, вы замечаете отодвигающуюся панель, над которой значится: "Заменить мифриловую обшивку, затем выключить и включить питание". $B$BИнтересно, получится ли починить Чи-Ту 3 и доставить ее Карне Сомнамбулер в Укрытие Маршалла... $B$BНе попробуешь – не узнаешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите мифриловую обшивку и вернитесь к Чи-Та 3 в Кратер Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы снова отдвигаете панель на спине Чи-Та 3 и осторожно вынимаете обгоревшую мифриловую обшивку, заменяя ее новой. Если действительно считать, что это и была основная причина поломки, то осталось лишь включить питание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Панель, в которую необходимо вставить мифриловую обшивку, все еще закрыта. Чи-Та 3 лежит неподвижно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чи-Та 3 в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4245,'В поисках Чи-Та 3','Установив тумблер в положение "выкл.", вы оглядываетесь, чтобы удостовериться, что все готово к тому, чтобы доставить Чи-Та 3 назад к Карне Сомнамбулер. Убедившись, что горилл поблизости нет, вы собираетесь включить робота. $B$BЭто ваш последний шанс. Вы уверены, что хотите сделать именно это?','Доставьте Чи-Та 3 назад Карне Сомнамбулер в Кратер Ун\'Горо.','Ах, тебе удалось, какое счастье! Спасибо, $N!$B$BО, моя бедняжечка! Как тебе досталось! Ничего, я починю тебя, будешь как новенькая!$B$BЕще раз благодарю тебя, $N, твоя помощь неоценима.','Вы смогли помочь? Уничтоженная мифриловая оболочка, о которой вы упомянули, была хорошим предположением о том, что случилось. Я уверен, что если вы замените это, она снова активируется и сможет вернуться домой.','Защищать Чи-Та 3, пока она не будет доставлена Карне Сомнамбулер.','Вернитесь к Карне Сомнамбулер в Смоляные ямы Лаккари, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Чи-Та 3',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Установив тумблер в положение "выкл.", вы оглядываетесь, чтобы удостовериться, что все готово к тому, чтобы доставить Чи-Та 3 назад к Карне Сомнамбулер. Убедившись, что горилл поблизости нет, вы собираетесь включить робота. $B$BЭто ваш последний шанс. Вы уверены, что хотите сделать именно это?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте Чи-Та 3 назад Карне Сомнамбулер в Кратер Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, тебе удалось, какое счастье! Спасибо, $N!$B$BО, моя бедняжечка! Как тебе досталось! Ничего, я починю тебя, будешь как новенькая!$B$BЕще раз благодарю тебя, $N, твоя помощь неоценима.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы смогли помочь? Уничтоженная мифриловая оболочка, о которой вы упомянули, была хорошим предположением о том, что случилось. Я уверен, что если вы замените это, она снова активируется и сможет вернуться домой.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защищать Чи-Та 3, пока она не будет доставлена Карне Сомнамбулер.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карне Сомнамбулер в Смоляные ямы Лаккари, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4261,'Древний дух','Оскверненный лес был некогда местом мирным и безмятежным... Пока сюда не пришел Легион. Эти огненные големы, разрушения, хаос...$B$BЧереп Гул\'дана сделал так, что ничто не смогло уберечься от порчи. $B$BДаже сейчас, будучи духом, я ощущаю себя в ловушке, ощущаю страдания этого края. Помоги мне найти путь домой. Прошу тебя, $n, пообещай, что ты уведешь древний дух отсюда, туда, где я, наконец, обрету покой.$B$BКак только я освобожусь, найди Кайнета Штиля, друида, что живет в Лесной Песне, к востоку отсюда.','Сопроводите Арая в безопасное место, затем поговорите с Кайнетом Штилем в Лесной Песне на востоке Ясеневого леса.','Сопроводите Арая в безопасное место.','Вернитесь к Кайнету Штилю в Лесную Песнь, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древний дух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оскверненный лес был некогда местом мирным и безмятежным... Пока сюда не пришел Легион. Эти огненные големы, разрушения, хаос...$B$BЧереп Гул\'дана сделал так, что ничто не смогло уберечься от порчи. $B$BДаже сейчас, будучи духом, я ощущаю себя в ловушке, ощущаю страдания этого края. Помоги мне найти путь домой. Прошу тебя, $n, пообещай, что ты уведешь древний дух отсюда, туда, где я, наконец, обрету покой.$B$BКак только я освобожусь, найди Кайнета Штиля, друида, что живет в Лесной Песне, к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите Арая в безопасное место, затем поговорите с Кайнетом Штилем в Лесной Песне на востоке Ясеневого леса.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сопроводите Арая в безопасное место.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайнету Штилю в Лесную Песнь, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4262,'Подчинитель Пирон','Последние пять магов, которые отправились на разведку к Черной горе вернулись довольно хрустящими и с перманентной завивкой – или хуже того.$b$b*Джалинда берет с земли щепотку пепла и пускает по ветру.*$B$BА больше всего неприятностей нам причиняет один тип, подчинитель Пирон. Необходимо остановить этого элементаля, чтобы наша экспедиция могла пробраться в глубины Черной горы.$b$bОн охраняет вход в каменоломни Черной горы.','Убейте подчинителя Пирона.$b$bКажется, Джалинда говорила, что Пирон охраняет каменоломню. Может, поискать его там?','Опалитель? О, небо…','<Джалинда, кажется, смотрит вам в голову.>','Вернитесь к Джалинде Тирлипуньке в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подчинитель Пирон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последние пять магов, которые отправились на разведку к Черной горе вернулись довольно хрустящими и с перманентной завивкой – или хуже того.$b$b*Джалинда берет с земли щепотку пепла и пускает по ветру.*$B$BА больше всего неприятностей нам причиняет один тип, подчинитель Пирон. Необходимо остановить этого элементаля, чтобы наша экспедиция могла пробраться в глубины Черной горы.$b$bОн охраняет вход в каменоломни Черной горы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте подчинителя Пирона.$b$bКажется, Джалинда говорила, что Пирон охраняет каменоломню. Может, поискать его там?',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Опалитель? О, небо…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Джалинда, кажется, смотрит вам в голову.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джалинде Тирлипуньке в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4263,'Опалитель!','Ты $gуверен:уверена;, что Пирон сказал перед смертью "Опалитель"?$b$b*Джалинда судорожно сглатывает.*$b$bВедь лорд Опалитель – прислужник Рагнароса! О небо, небо... Что же нам делать?$b$bКак ты думаешь, справишься с еще одним заданием? Мне больше некого послать, $n!$b$bНам никогда не одолеть врагов, если Опалитель будет и дальше воскрешать Пирона из пепла.$b$bТебе придется отыскать и уничтожить лорда Опалителя!','Отыщите и уничтожьте лорда Опалителя в глубинах Черной горы!','О небо! Ты $Gуверен:уверена;, что Опалитель сказал перед смертью "Рагнарос"?$B$B<Джалинда протягивает вам что-то и морщит лоб в раздумье.>','Лорд мертв??','Вернитесь к Джалинде Тирлипуньке в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опалитель!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gуверен:уверена;, что Пирон сказал перед смертью "Опалитель"?$b$b*Джалинда судорожно сглатывает.*$b$bВедь лорд Опалитель – прислужник Рагнароса! О небо, небо... Что же нам делать?$b$bКак ты думаешь, справишься с еще одним заданием? Мне больше некого послать, $n!$b$bНам никогда не одолеть врагов, если Опалитель будет и дальше воскрешать Пирона из пепла.$b$bТебе придется отыскать и уничтожить лорда Опалителя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите и уничтожьте лорда Опалителя в глубинах Черной горы!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О небо! Ты $Gуверен:уверена;, что Опалитель сказал перед смертью "Рагнарос"?$B$B<Джалинда протягивает вам что-то и морщит лоб в раздумье.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лорд мертв??',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джалинде Тирлипуньке в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4264,'Измятая записка','Лист помят и испачкан, и текст почти не читается, но вам все-таки удалось разобрать несколько фраз:$B$B"...по иронии судьбы...$B$B...упадок распавшегося Альянса...$B$B...если бы не усердие генерала Кузни Гнева, мы никогда не сумели бы найти ключ к шифру...$B$B...Аргелмах почти завершил расшифровку записок Виндзора.$B$BНаш владыка восстанет из бездны и сокрушит всех, кто остался...$B$BИмператор Дагран Тауриссан".','Не исключено, что ваша находка заинтересует маршала Виндзора. Может быть, все не так плохо, и надежда еще жива.','<Маршал Виндзор читает записку.>','<Маршал Виндзор заметил смятый листок у вас в руке.>$B$BЧто это там у тебя, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Измятая записка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лист помят и испачкан, и текст почти не читается, но вам все-таки удалось разобрать несколько фраз:$B$B"...по иронии судьбы...$B$B...упадок распавшегося Альянса...$B$B...если бы не усердие генерала Кузни Гнева, мы никогда не сумели бы найти ключ к шифру...$B$B...Аргелмах почти завершил расшифровку записок Виндзора.$B$BНаш владыка восстанет из бездны и сокрушит всех, кто остался...$B$BИмператор Дагран Тауриссан".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Не исключено, что ваша находка заинтересует маршала Виндзора. Может быть, все не так плохо, и надежда еще жива.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Маршал Виндзор читает записку.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Маршал Виндзор заметил смятый листок у вас в руке.>$B$BЧто это там у тебя, $N?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (4265,'Освобожденный из улья','Когда вы прикасаетесь к кокону, он немного раскрывается, и вы видите внутри ночного эльфа, который, как ни странно, все еще жив, и даже, кажется, цел и невредим, только в глубоком обмороке. Когда вы вытаскиваете его из кокона, он шевелится и приходит в себя.$B$B"Слава Элуне! Я спасен! Спасибо тебе, друг. Я... Меня зовут Раскал. Эти жуки парализовали меня, и очнулся я уже в коконе. Тебя из крепости прислали, да?"$b$bПохоже, вы нашли пропавшего курьера...','Освободите Раскала из улья Зукк\'аш.$b$bВернитесь к Гинро Пылающему Очагу в Крепости Оперенной Луны и сообщите ему, что Раскал жив и здоров.','С возвращением, $N! Раскал не так давно явился ко мне и сообщил обо всем, что произошло.$B$BЯ... да что там, вся наша крепость не знает, как тебя благодарить за твои подвиги. Раскал погиб бы, если бы не твоя своевременная помощь. А ведь ты помогаешь нам не ради платы, как какой-нибудь наемник! Ты – подлинный герой. Знай, что отныне Гинро Пылающий Очаг – твой друг до скончания веков!','Тебе есть о чем сообщить, $N?','Освободите Раскала','Вернитесь к Гинро Пылающему Очагу в Крепость Оперенной Луны, что в Фераласе.','Освободите Раскала') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освобожденный из улья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда вы прикасаетесь к кокону, он немного раскрывается, и вы видите внутри ночного эльфа, который, как ни странно, все еще жив, и даже, кажется, цел и невредим, только в глубоком обмороке. Когда вы вытаскиваете его из кокона, он шевелится и приходит в себя.$B$B"Слава Элуне! Я спасен! Спасибо тебе, друг. Я... Меня зовут Раскал. Эти жуки парализовали меня, и очнулся я уже в коконе. Тебя из крепости прислали, да?"$b$bПохоже, вы нашли пропавшего курьера...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите Раскала из улья Зукк\'аш.$b$bВернитесь к Гинро Пылающему Очагу в Крепости Оперенной Луны и сообщите ему, что Раскал жив и здоров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С возвращением, $N! Раскал не так давно явился ко мне и сообщил обо всем, что произошло.$B$BЯ... да что там, вся наша крепость не знает, как тебя благодарить за твои подвиги. Раскал погиб бы, если бы не твоя своевременная помощь. А ведь ты помогаешь нам не ради платы, как какой-нибудь наемник! Ты – подлинный герой. Знай, что отныне Гинро Пылающий Очаг – твой друг до скончания веков!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе есть о чем сообщить, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Освободите Раскала',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гинро Пылающему Очагу в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Освободите Раскала',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4266,'Благодарность за отвагу','$n, генерал Шандриса Оперенная Луна хотела бы поговорить с тобой лично. Несомненно, она хочет поблагодарить тебя за все, что ты $gсделал:сделала; для крепости, но, насколько я знаю, она также хотела бы поговорить с тобой о тех насекомоподобных тварях, которых вы с Раскалом видели в южном Фераласе. Сообщения об этих насекомых, которых именуют Зукк\'аш, звучат... скажем так: устрашающе.$b$bГенерал Оперенная Луна ждет тебя в главном здании.','Поговорите с Шандрисой Оперенной Луной в Крепости Оперенной Луны.','$N, я от души благодарю тебя за всю оказанную тобой помощь. Твоя отвага перед лицом превосходящих сил противника достойна награды в тысячу раз большей. Тем не менее, я надеюсь, что ты примешь в дар от всей крепости хотя бы это.$B$BА теперь, если можно... я хотела бы попросить тебя еще об одной услуге. Сейчас, когда здесь, в Фераласе, обнаружен улей Цуккаш, думаю, это задание следует поручить именно тебе...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодарность за отвагу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, генерал Шандриса Оперенная Луна хотела бы поговорить с тобой лично. Несомненно, она хочет поблагодарить тебя за все, что ты $gсделал:сделала; для крепости, но, насколько я знаю, она также хотела бы поговорить с тобой о тех насекомоподобных тварях, которых вы с Раскалом видели в южном Фераласе. Сообщения об этих насекомых, которых именуют Зукк\'аш, звучат... скажем так: устрашающе.$b$bГенерал Оперенная Луна ждет тебя в главном здании.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Шандрисой Оперенной Луной в Крепости Оперенной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, я от души благодарю тебя за всю оказанную тобой помощь. Твоя отвага перед лицом превосходящих сил противника достойна награды в тысячу раз большей. Тем не менее, я надеюсь, что ты примешь в дар от всей крепости хотя бы это.$B$BА теперь, если можно... я хотела бы попросить тебя еще об одной услуге. Сейчас, когда здесь, в Фераласе, обнаружен улей Цуккаш, думаю, это задание следует поручить именно тебе...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4267,'Возвышение силитидов','Я доверяю тебе копию отчета Раскала о вторжении в юго-восточный Фералас. Полный доклад будет отправлен на хранение в Дарнас, а эту копию отнеси, пожалуйста, представителю Протектората. Ее зовут Грацина Сила Духа; это жрица, которая живет в храме Луны в Дарнасе. Она обладает обширными познаниями о подобных существах, так что, если она ознакомится с этим докладом, это пойдет на пользу всем нам.$b$bМожешь идти, $n. Удачи тебе, и да хранит нас Элуна!','Отнесите донесение Раскала Грацине Силе Духа в Дарнасе.','Нам, ночным эльфам, немало известно об ужасах, описанных в этом докладе. Сандрис поступила мудро, отправив ко мне доклад – и тебя с ним.$B$BЭти твари стремительно заполонят весь Фералас. Можно сказать, что это одна из самых страшных опасностей, какие нам когда-либо грозили! Насекомые, с которыми столкнулись вы с курьером, называются силитидами. Они – всего лишь орудие одной из величайших угроз, с какими встречались как Альянс, так и Орда.$B$BМолюсь, чтобы у нас хватило решимости разгромить их прежде, чем они уничтожат нас!','Добро пожаловать в наш благословенный храм! Я узнала о твоем приходе из предсказания. Тот доклад, что просила тебя отнести Шандрисе Оперенной Луне, у тебя с собой?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвышение силитидов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я доверяю тебе копию отчета Раскала о вторжении в юго-восточный Фералас. Полный доклад будет отправлен на хранение в Дарнас, а эту копию отнеси, пожалуйста, представителю Протектората. Ее зовут Грацина Сила Духа; это жрица, которая живет в храме Луны в Дарнасе. Она обладает обширными познаниями о подобных существах, так что, если она ознакомится с этим докладом, это пойдет на пользу всем нам.$b$bМожешь идти, $n. Удачи тебе, и да хранит нас Элуна!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите донесение Раскала Грацине Силе Духа в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нам, ночным эльфам, немало известно об ужасах, описанных в этом докладе. Сандрис поступила мудро, отправив ко мне доклад – и тебя с ним.$B$BЭти твари стремительно заполонят весь Фералас. Можно сказать, что это одна из самых страшных опасностей, какие нам когда-либо грозили! Насекомые, с которыми столкнулись вы с курьером, называются силитидами. Они – всего лишь орудие одной из величайших угроз, с какими встречались как Альянс, так и Орда.$B$BМолюсь, чтобы у нас хватило решимости разгромить их прежде, чем они уничтожат нас!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать в наш благословенный храм! Я узнала о твоем приходе из предсказания. Тот доклад, что просила тебя отнести Шандрисе Оперенной Луне, у тебя с собой?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4281,'Посылка в Таланаар','Сверток, который вы нашли в лагере гноллов-древолапов, следовало доставить в небольшой путевой лагерь Таланаар на юго-востоке Фераласа. Неизвестно, какая судьба постигла курьера, однако сверток так и остался недоставленным!$b$bОсмотрев пакет, вы видите на нем имя "Хранитель дорог Фалфиндер". Возможно, это имя адресата?','Отнесите недоставленную посылку Хранителю дорог Фалфиндеру в Таланаар.','Слава Элуне! Наконец-то пришла посылка из Крепости Оперенной Луны!$B$BНо раз ее $Gпринес:принесла; ты, значит, с нашим курьером, Раскалом, что-то случилось? Надеюсь, что все уладится... Насколько я знаю, в последнее время гноллы из клана Древолапов очень боятся чего-то, что происходит на юге. Может быть, Раскал заблудился в глуши? Будь осторожнее.$B$BНу, как бы то ни было, спасибо тебе еще раз. А вот и плата за доставку!','Добро пожаловать в Таланаар, $C. Тебе нужна какая-нибудь помощь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посылка в Таланаар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сверток, который вы нашли в лагере гноллов-древолапов, следовало доставить в небольшой путевой лагерь Таланаар на юго-востоке Фераласа. Неизвестно, какая судьба постигла курьера, однако сверток так и остался недоставленным!$b$bОсмотрев пакет, вы видите на нем имя "Хранитель дорог Фалфиндер". Возможно, это имя адресата?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите недоставленную посылку Хранителю дорог Фалфиндеру в Таланаар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава Элуне! Наконец-то пришла посылка из Крепости Оперенной Луны!$B$BНо раз ее $Gпринес:принесла; ты, значит, с нашим курьером, Раскалом, что-то случилось? Надеюсь, что все уладится... Насколько я знаю, в последнее время гноллы из клана Древолапов очень боятся чего-то, что происходит на юге. Может быть, Раскал заблудился в глуши? Будь осторожнее.$B$BНу, как бы то ни было, спасибо тебе еще раз. А вот и плата за доставку!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать в Таланаар, $C. Тебе нужна какая-нибудь помощь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4282,'Проблеск надежды','<Маршал Виндзор возбужденно потрясает запиской.>$B$BТы понимаешь, что это значит, $n?$B$BМожет быть, еще не все потеряно! Насколько я понял, информацией завладели два дворфа Черного Железа – генерал Кузня Гнева и повелитель големов Аргелмах. Однако есть у меня подозрение, что они ее не отдадут, даже если мы их очень вежливо попросим.$B$BНадеюсь, ты $gготов:готова; сражаться.$B$BРазыщи этих двоих негодяев! Убей их обоих и верни мне утерянную информацию.','Верните маршалу Виндзору утерянную информацию.$B$BМаршал уверен, что информацией завладели повелитель големов Аргелмах и генерал Кузня Гнева.','<Маршал Виндзор выхватывает у вас из рук таблички.>$B$BУходим!','Уже очень скоро все это закончится.','Вернитесь к маршалу Винздору в Промерзшую пещеру, что в Глубинах Черной горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблеск надежды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Маршал Виндзор возбужденно потрясает запиской.>$B$BТы понимаешь, что это значит, $n?$B$BМожет быть, еще не все потеряно! Насколько я понял, информацией завладели два дворфа Черного Железа – генерал Кузня Гнева и повелитель големов Аргелмах. Однако есть у меня подозрение, что они ее не отдадут, даже если мы их очень вежливо попросим.$B$BНадеюсь, ты $gготов:готова; сражаться.$B$BРазыщи этих двоих негодяев! Убей их обоих и верни мне утерянную информацию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните маршалу Виндзору утерянную информацию.$B$BМаршал уверен, что информацией завладели повелитель големов Аргелмах и генерал Кузня Гнева.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Маршал Виндзор выхватывает у вас из рук таблички.>$B$BУходим!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уже очень скоро все это закончится.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Винздору в Промерзшую пещеру, что в Глубинах Черной горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4283,'ПЯТЬДЕСЯТ! АГА!','Открою тебе тайну, солдат. Подойди-ка поближе.$B$BЯ ЕДИНСТВЕННЫЙ, КТО ЕЩЕ НЕ СПЯТИЛ!$B$BПосмотри на остальных. Ты веришь, что они ненормальные? А так оно и есть! ПСИХИ! СУМАСШЕДШИЕ!$B$B*Орелий понижает голос.*$B$BНо пусть это останется между нами – тобой, мной и моим приятелем, капитаном Мигом.$B$B*Орелий хватается за воздух и будто прижимает кого-то к себе.*$B$BВ общееем... помимо ушей огров, я собираю их солдатские медальоны. Сегодня на повестке дня орки. Пятьдесят штук. ИДИ!$B$B*Орелий трубит в рог.*$B$BЗАТКНИСЬ!','Найдите 50 медальонов Черной горы.','Ты $Gсправился:справилась;! И вот твоя награда: ПОЧЕШИ МНЕ ЖИВОТИК! ДАВАЙ! ЧЕШИ!','<Орелиус говорит в довольно большое отрезанное ухо огра.>$B$BПылающие степи – центру. Центр, прием.','Вернитесь к Орелию в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ПЯТЬДЕСЯТ! АГА!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Открою тебе тайну, солдат. Подойди-ка поближе.$B$BЯ ЕДИНСТВЕННЫЙ, КТО ЕЩЕ НЕ СПЯТИЛ!$B$BПосмотри на остальных. Ты веришь, что они ненормальные? А так оно и есть! ПСИХИ! СУМАСШЕДШИЕ!$B$B*Орелий понижает голос.*$B$BНо пусть это останется между нами – тобой, мной и моим приятелем, капитаном Мигом.$B$B*Орелий хватается за воздух и будто прижимает кого-то к себе.*$B$BВ общееем... помимо ушей огров, я собираю их солдатские медальоны. Сегодня на повестке дня орки. Пятьдесят штук. ИДИ!$B$B*Орелий трубит в рог.*$B$BЗАТКНИСЬ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 50 медальонов Черной горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсправился:справилась;! И вот твоя награда: ПОЧЕШИ МНЕ ЖИВОТИК! ДАВАЙ! ЧЕШИ!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Орелиус говорит в довольно большое отрезанное ухо огра.>$B$BПылающие степи – центру. Центр, прием.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орелию в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4284,'Кристаллы силы','Уверена, ты $gвидел:видела; их, $n. Они повсюду! $B$BТы не понимаешь, о чем я? О кристаллах, конечно! Большинство их просто игнорирует, но я чувствую, что в них заключена какая-то сила. Я уже давно провожу с ними эксперименты, но пока, видимо, так же далека от разгадки, как и в первые дни исследований... Впрочем, я не теряю надежды! $B$BСейчас у меня почти вышел запас кристаллов. Не поможешь ли мне его восполнить?','Соберите по 7 кристаллов силы каждого цвета: красных, синих, желтых и зеленых. Принесите их Джей Ди Колли в Укрытие Маршалла.','Вернитесь к Джей Ди Колли в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристаллы силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уверена, ты $gвидел:видела; их, $n. Они повсюду! $B$BТы не понимаешь, о чем я? О кристаллах, конечно! Большинство их просто игнорирует, но я чувствую, что в них заключена какая-то сила. Я уже давно провожу с ними эксперименты, но пока, видимо, так же далека от разгадки, как и в первые дни исследований... Впрочем, я не теряю надежды! $B$BСейчас у меня почти вышел запас кристаллов. Не поможешь ли мне его восполнить?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите по 7 кристаллов силы каждого цвета: красных, синих, желтых и зеленых. Принесите их Джей Ди Колли в Укрытие Маршалла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джей Ди Колли в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4285,'Северный пилон','Что бы это могло быть? Я все время думаю об этой загадке! $B$BЭти слухи о хрустальных пилонах просто сводят меня с ума! Можешь считать меня наивной дурочкой, но я верю почти всему, что мне рассказывают. $B$BВ общем, слыхала я, что один из пилонов находится совсем неподалеку отсюда – где-то на севере. Пожалуйста, разыщи его, $n! Я уверена, пилоны существуют!','Отыщите Северный хрустальный пилон в Кратере Ун\'Горо.','Я знаю, что все эти рассказы – правда, $N.','Ты $Gбыл:была; у пилона, $N?','Найти и исследовать северный хрустальный пилон.','Вернитесь к Джей Ди Колли в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Северный пилон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что бы это могло быть? Я все время думаю об этой загадке! $B$BЭти слухи о хрустальных пилонах просто сводят меня с ума! Можешь считать меня наивной дурочкой, но я верю почти всему, что мне рассказывают. $B$BВ общем, слыхала я, что один из пилонов находится совсем неподалеку отсюда – где-то на севере. Пожалуйста, разыщи его, $n! Я уверена, пилоны существуют!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Северный хрустальный пилон в Кратере Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю, что все эти рассказы – правда, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gбыл:была; у пилона, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найти и исследовать северный хрустальный пилон.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джей Ди Колли в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4286,'За сокровищем – с кулаками','Капитан Винки уверяет, что дворфы Черного Железа в глубинах Черной Скалы загребли все лучшее добро. Верно, Миг?$b$b<Орелий, как может, изображает пирата.>$b$bВот видишь? Иди туда и принеси мне образцы их добра.$b$bТряхни стариной и отправляйся вглубь!','Добудьте 20 поясных сумок дворфов Черного Железа.','<Орелиус роется в груде поясных сумок.>$B$BВЕЛИКОЛЕПНО!$B$B<Орелиус сует нос в кучу и принюхивается.>$B$BВОСХИТИТЕЛЬНО! Только посмотри на это добро!$B$BВозьми одну себе, здесь их полно.','Не беспокой меня, $N. Нам с Винкей надо кое с кем встретиться.','Вернитесь к Орелию в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За сокровищем – с кулаками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Капитан Винки уверяет, что дворфы Черного Железа в глубинах Черной Скалы загребли все лучшее добро. Верно, Миг?$b$b<Орелий, как может, изображает пирата.>$b$bВот видишь? Иди туда и принеси мне образцы их добра.$b$bТряхни стариной и отправляйся вглубь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 20 поясных сумок дворфов Черного Железа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Орелиус роется в груде поясных сумок.>$B$BВЕЛИКОЛЕПНО!$B$B<Орелиус сует нос в кучу и принюхивается.>$B$BВОСХИТИТЕЛЬНО! Только посмотри на это добро!$B$BВозьми одну себе, здесь их полно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не беспокой меня, $N. Нам с Винкей надо кое с кем встретиться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орелию в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4287,'Восточный пилон','За время моего пребывания здесь, до меня не раз доходили странные слухи о таинственных хрустальных пилонах, сокрытых в кратере. Полагаю, они довольно велики. $B$BНе могу отделаться от мысли, что в этих слухах есть доля истины, и эти пилоны как-то связаны с обнаруженными нами кристаллами... $B$BУдовлетвори мое любопытство, поищи пилон в восточной области кратера.','Отыщите Восточный хрустальный пилон в Кратере Ун\'Горо.','Ун\'Горо такое странное место, $N! Входишь – и будто оказываешься в другом мире!','Ты $Gбыл:была; у пилона, $N?','Найти и исследовать Восточный хрустальный пилон','Вернитесь к Джей Ди Колли в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восточный пилон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За время моего пребывания здесь, до меня не раз доходили странные слухи о таинственных хрустальных пилонах, сокрытых в кратере. Полагаю, они довольно велики. $B$BНе могу отделаться от мысли, что в этих слухах есть доля истины, и эти пилоны как-то связаны с обнаруженными нами кристаллами... $B$BУдовлетвори мое любопытство, поищи пилон в восточной области кратера.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Восточный хрустальный пилон в Кратере Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ун\'Горо такое странное место, $N! Входишь – и будто оказываешься в другом мире!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gбыл:была; у пилона, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найти и исследовать Восточный хрустальный пилон',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джей Ди Колли в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4288,'Западный пилон','Мои опыты пока не принесли никаких положительных результатов, $n. Теперь я возлагаю надежды лишь на то, что ты сможешь найти один из пилонов, о существовании которых я слыхала. $B$BВозможно, если смешать определенные цвета... Впрочем, я тороплю события. Необходимо сначала найти его. $B$BИсследуй западную область кратера, $n, говорят, пилон находится именно там.','Отыщите Западный хрустальный пилон.','В стенах кратера много ниш и пещер. Попробуй обыскать извилистые тропинки в тех местах, если больше ничего не можешь придумать.','Ты $Gбыл:была; у пилона, $N?','Найти и исследовать Западный хрустальный пилон','Вернитесь к Джей Ди Колли в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Западный пилон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои опыты пока не принесли никаких положительных результатов, $n. Теперь я возлагаю надежды лишь на то, что ты сможешь найти один из пилонов, о существовании которых я слыхала. $B$BВозможно, если смешать определенные цвета... Впрочем, я тороплю события. Необходимо сначала найти его. $B$BИсследуй западную область кратера, $n, говорят, пилон находится именно там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Западный хрустальный пилон.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В стенах кратера много ниш и пещер. Попробуй обыскать извилистые тропинки в тех местах, если больше ничего не можешь придумать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gбыл:была; у пилона, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найти и исследовать Западный хрустальный пилон',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джей Ди Колли в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4289,'Обезьяны Ун\'Горо','В этом кратере встречается множество странных зверей – они похожи на тех, что водятся на моей родине, но выглядят более... породистыми. Я не могу объяснить это, но мне кажется, это место – средоточие силы Матери-Природы. Я воздаю ей хвалу всякий раз, как встречаю одно из ее прекрасных созданий в этом кратере. $B$BЕсли ты тоже хочешь достигнуть просветления, отправляйся на север. Там ты найдешь огромных обезьян, помериться силами с которыми сочтет за честь самый искусный воин. Принеси мне их шкуры, докажи свою силу!','Принесите 2 шкуры Ун\'Горской гориллы, 2 шкуры Ун\'Горского топтуна и 2 шкуры Ун\'Горского рокотуна землепроходцу Торве к входу в Кратер Ун\'Горо.','Значит, тебе хватило сил одолеть обезьян Ун\'Горо. Это славно. Конечно, это не такая сложная задача, как сражение с Лар\'корви, и все же немалая победа.$B$BМое племя обрадуется шкурам, из них получатся прекрасные одежды! Ты $Gпомог:помогла; мне и $Gпоказал:показала; себя $Gдостойным:достойной;.$B$BПрежде чем ты отправишься далее, воздадим хвалу Матери-Земле и поблагодарим духов обезьян, убитых тобой – они должны знать, что их смерть была не напрасна!','Что, неужели $Gсдался:сдалась;, $N?$B$BНе падай духом. Выследить и сразить обезьяну Ун\'Горо – не простая задача, даже для великого охотника.','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезьяны Ун\'Горо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом кратере встречается множество странных зверей – они похожи на тех, что водятся на моей родине, но выглядят более... породистыми. Я не могу объяснить это, но мне кажется, это место – средоточие силы Матери-Природы. Я воздаю ей хвалу всякий раз, как встречаю одно из ее прекрасных созданий в этом кратере. $B$BЕсли ты тоже хочешь достигнуть просветления, отправляйся на север. Там ты найдешь огромных обезьян, помериться силами с которыми сочтет за честь самый искусный воин. Принеси мне их шкуры, докажи свою силу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 шкуры Ун\'Горской гориллы, 2 шкуры Ун\'Горского топтуна и 2 шкуры Ун\'Горского рокотуна землепроходцу Торве к входу в Кратер Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, тебе хватило сил одолеть обезьян Ун\'Горо. Это славно. Конечно, это не такая сложная задача, как сражение с Лар\'корви, и все же немалая победа.$B$BМое племя обрадуется шкурам, из них получатся прекрасные одежды! Ты $Gпомог:помогла; мне и $Gпоказал:показала; себя $Gдостойным:достойной;.$B$BПрежде чем ты отправишься далее, воздадим хвалу Матери-Земле и поблагодарим духов обезьян, убитых тобой – они должны знать, что их смерть была не напрасна!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что, неужели $Gсдался:сдалась;, $N?$B$BНе падай духом. Выследить и сразить обезьяну Ун\'Горо – не простая задача, даже для великого охотника.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4290,'Добыча Лар\'корви','Однажды мой брат имел неосторожность отрезать кусок мяса от добычи Лар\'корви, когда того не было рядом. Однако оказалось, что Лар\'корви наблюдал за моим братом из укрытия. Он преследовал моего брата долгие недели, разрушая все на своем пути. Наконец, брат мой в страхе решил покинуть кратер. $B$BНо Лар\'корви настиг его недалеко от этого места и убил его. $B$BЕсли хочешь привлечь к себе внимание Лар\'корви, найди его свежеубитую добычу и отрежь от нее кусок мяса. $B$BЗатем возвращайся ко мне.','Найдите последнюю добычу Лар\'корви, украдите кусок трупа жесткозуба и вернитесь к землепроходцу Торве в Кратер Ун\'Горо.','Этот кусок послужит хорошей приманкой, $N. Похоже, удача в охоте сопутствует Лар\'корви. Однако странно, где он смог найти жесткозуба в этих краях...$B$BЯ сохраню это для тебя до тех пор, пока ты не будешь $Gготов:готова; встретиться с чудовищем. Не волнуйся за меня – полагаю, ты уже $Gуспел:успела; так разозлить Лар\'корви, что он не станет убивать меня раньше, чем вкусит твоей плоти.','Не относись к этому заданию легкомысленно, $N. Если ты и вправду желаешь встретиться с чудовищем, ты должен быть очень осторожен и рассудителен. Необходима немалая сила и сноровка, чтобы победить Лар\'корви.','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добыча Лар\'корви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Однажды мой брат имел неосторожность отрезать кусок мяса от добычи Лар\'корви, когда того не было рядом. Однако оказалось, что Лар\'корви наблюдал за моим братом из укрытия. Он преследовал моего брата долгие недели, разрушая все на своем пути. Наконец, брат мой в страхе решил покинуть кратер. $B$BНо Лар\'корви настиг его недалеко от этого места и убил его. $B$BЕсли хочешь привлечь к себе внимание Лар\'корви, найди его свежеубитую добычу и отрежь от нее кусок мяса. $B$BЗатем возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите последнюю добычу Лар\'корви, украдите кусок трупа жесткозуба и вернитесь к землепроходцу Торве в Кратер Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот кусок послужит хорошей приманкой, $N. Похоже, удача в охоте сопутствует Лар\'корви. Однако странно, где он смог найти жесткозуба в этих краях...$B$BЯ сохраню это для тебя до тех пор, пока ты не будешь $Gготов:готова; встретиться с чудовищем. Не волнуйся за меня – полагаю, ты уже $Gуспел:успела; так разозлить Лар\'корви, что он не станет убивать меня раньше, чем вкусит твоей плоти.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не относись к этому заданию легкомысленно, $N. Если ты и вправду желаешь встретиться с чудовищем, ты должен быть очень осторожен и рассудителен. Необходима немалая сила и сноровка, чтобы победить Лар\'корви.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4291,'Запах Лар\'корви','Я удивлен, что Лар\'корви не вышел к тебе, $n! И все же у меня есть задумка, как выманить его. $B$BПоскольку Лар\'корви – доминирующий самец в своей стае, он может выбирать любую самку. А выбирает он многих! Ты найдешь много кладок равазавров к западу отсюда. Подберись к ним поближе и спровоцируй самок атаковать тебя. В их головах находятся железы, источающие жуткий запах – так эти твари оповещают своих самцов о готовности к размножению. Принеси мне две такие железы.','Принесите 2 феромонные железы равазавра землепроходцу Торве в преддверие Кратера Ун\'Горо.','Это отличные образцы, $N. С их помощью мы сможем выманить Лар\'корви. Мне не терпится узнать, чем закончится твой бой с чудовищем. Это огромная тварь с зубами, подобными булатным клинкам. Ты посмотришь в его глаза и познаешь, каков взгляд смерти.','Будь осторожен $N. Когда подберешься близко к яйцам, самки ринутся защищать их. Они могут быть не менее опасны, чем сам Лар\'корви, если почувствуют угрозу своему потомству. Но если тебе удастся добыть железы, мы точно сможем выманить Лар\'корви из его логова.','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запах Лар\'корви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я удивлен, что Лар\'корви не вышел к тебе, $n! И все же у меня есть задумка, как выманить его. $B$BПоскольку Лар\'корви – доминирующий самец в своей стае, он может выбирать любую самку. А выбирает он многих! Ты найдешь много кладок равазавров к западу отсюда. Подберись к ним поближе и спровоцируй самок атаковать тебя. В их головах находятся железы, источающие жуткий запах – так эти твари оповещают своих самцов о готовности к размножению. Принеси мне две такие железы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 феромонные железы равазавра землепроходцу Торве в преддверие Кратера Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это отличные образцы, $N. С их помощью мы сможем выманить Лар\'корви. Мне не терпится узнать, чем закончится твой бой с чудовищем. Это огромная тварь с зубами, подобными булатным клинкам. Ты посмотришь в его глаза и познаешь, каков взгляд смерти.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будь осторожен $N. Когда подберешься близко к яйцам, самки ринутся защищать их. Они могут быть не менее опасны, чем сам Лар\'корви, если почувствуют угрозу своему потомству. Но если тебе удастся добыть железы, мы точно сможем выманить Лар\'корви из его логова.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4292,'Приманка для Лар\'корви','Это самая сложная часть нашего плана. К северу отсюда есть узкая тропинка, ведущая в горы. Именно там я в последний раз видел Лар\'корви. Ты легко узнаешь это место – там повсюду разбросаны дочиста обглоданные кости крупных животных, имевших неосторожность подойти слишком близко к логову Лар\'корви. Положишь там принесенное с собой мясо. Затем полей мясо вот этим составом. Если это не выманит к тебе Лар\'корви, то я не знаю, чем еще его можно заманить.','С помощью предметов из мешочка Торвы выманите Лар\'корви и сразите его. Принесите голову Лар\'корви землепроходцу Торве ко входу в Кратер Ун\'Горо.','Хвала Матери-Земле! Ты $Gсправился:справилась;!Ты $Gпоказал:показала; себя $Gвеликим:великой;, $N. Твой дух силен. Твоей храбрости нет равных. А сила твоя укрепилась. Я склоняюсь пред твоим мастерством.$B$BТолько самым великим из моих предков были под силу подобные свершения.','Не дай своему страху побороть тебя, $N! Страх – великий предатель, с ним нужно бороться.$B$BВозьми это мясо и потри его железой самки чудовища. И тогда сама смерть предстанет перед тобой.','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приманка для Лар\'корви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это самая сложная часть нашего плана. К северу отсюда есть узкая тропинка, ведущая в горы. Именно там я в последний раз видел Лар\'корви. Ты легко узнаешь это место – там повсюду разбросаны дочиста обглоданные кости крупных животных, имевших неосторожность подойти слишком близко к логову Лар\'корви. Положишь там принесенное с собой мясо. Затем полей мясо вот этим составом. Если это не выманит к тебе Лар\'корви, то я не знаю, чем еще его можно заманить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью предметов из мешочка Торвы выманите Лар\'корви и сразите его. Принесите голову Лар\'корви землепроходцу Торве ко входу в Кратер Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала Матери-Земле! Ты $Gсправился:справилась;!Ты $Gпоказал:показала; себя $Gвеликим:великой;, $N. Твой дух силен. Твоей храбрости нет равных. А сила твоя укрепилась. Я склоняюсь пред твоим мастерством.$B$BТолько самым великим из моих предков были под силу подобные свершения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не дай своему страху побороть тебя, $N! Страх – великий предатель, с ним нужно бороться.$B$BВозьми это мясо и потри его железой самки чудовища. И тогда сама смерть предстанет перед тобой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4293,'Проба слизи...','Оскверненный лес находится далеко на севере от Степей – даже дальше, чем Ясеневый лес. Вокруг тамошних заводей, благословленных касанием Скверны, полно слизнюков. Плеть наводнила эти земли инферналами и прочими демонами. Судя по всему, в это время слизнюки и полезли из-под земли.$B$BСобери образцы слизнюков Оскверненного леса – мы проверим их при помощи моего оборудования и создадим контрольную группу, чтобы сопоставить ее с другими принесенными тобой образцами.','Возьмите на пробу образцы слизи из Оскверненного леса. Воспользуйтесь тестовым оборудованием химика Барабоса в Подгороде, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему.','Великолепно. Эти пробы прекрасно подойдут. Благодарю за помощь.$B$BСобрав все образцы слизи, мы сможем двинуться дальше. Я начинаю подозревать, что леди Сильвана не зря заинтересовалась этими существами. Более того, сама того не зная, она, похоже, оказалась на грани великого открытия. Эти пробы очень интересны. А как они прореагировали с моими препаратами... хм, да, нам есть над чем поработать.','Мне нужно не меньше пяти проб слизи для контрольной группы. Продолжай собирать образцы слизи, пока не предоставишь мне все необходимое. Так велела леди Сильвана...','Вернитесь к химику Барабосу в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проба слизи...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оскверненный лес находится далеко на севере от Степей – даже дальше, чем Ясеневый лес. Вокруг тамошних заводей, благословленных касанием Скверны, полно слизнюков. Плеть наводнила эти земли инферналами и прочими демонами. Судя по всему, в это время слизнюки и полезли из-под земли.$B$BСобери образцы слизнюков Оскверненного леса – мы проверим их при помощи моего оборудования и создадим контрольную группу, чтобы сопоставить ее с другими принесенными тобой образцами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите на пробу образцы слизи из Оскверненного леса. Воспользуйтесь тестовым оборудованием химика Барабоса в Подгороде, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Эти пробы прекрасно подойдут. Благодарю за помощь.$B$BСобрав все образцы слизи, мы сможем двинуться дальше. Я начинаю подозревать, что леди Сильвана не зря заинтересовалась этими существами. Более того, сама того не зная, она, похоже, оказалась на грани великого открытия. Эти пробы очень интересны. А как они прореагировали с моими препаратами... хм, да, нам есть над чем поработать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно не меньше пяти проб слизи для контрольной группы. Продолжай собирать образцы слизи, пока не предоставишь мне все необходимое. Так велела леди Сильвана...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к химику Барабосу в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4294,'...и образцы слизнюков','Тебе приходилось слышать о Кратере Ун\'Горо? Он расположен рядом с пустыней Танарис. Великолепное место: тамошние буйные заросли буквально кишат жизнью! А какие там растения...$B$BИменно туда тебе и следует отправиться. До меня дошли слухи, что в этих местах сохранилась практически девственная природа. Исследователи лишь недавно добрались до них, и далеко не все тайны еще раскрыты.$b$BЯ хочу, чтобы ты $Gпринес:принесла; мне образцы живущих там слизнюков. Если слухи правдивы и их не тронула порча, я смогу узнать, откуда появились эти существа.','Возьмите на пробу образцы слизи из Кратера Ун\'Горо. Воспользуйтесь тестовым оборудованием химика Барабоса в Катакомбах, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему.','Удивительно! Кратер Ун\'Горо таит куда больше секретов, чем я думал. Интересно, какие еще открытия нас ждут?$B$BПоразительно... Изумительно чистые образцы. Хм, что бы это значило? Похоже, по природе они относятся скорее к стихиям... но непростым. Они напоминают мне... о Древних богах. Мы находили их следы по всему Азероту – вдруг и эти существа каким-то образом связаны с ними?$B$BНадо продолжать исследования.','Да, $N? Как успехи?','Вернитесь к химику Барабосу в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','...и образцы слизнюков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе приходилось слышать о Кратере Ун\'Горо? Он расположен рядом с пустыней Танарис. Великолепное место: тамошние буйные заросли буквально кишат жизнью! А какие там растения...$B$BИменно туда тебе и следует отправиться. До меня дошли слухи, что в этих местах сохранилась практически девственная природа. Исследователи лишь недавно добрались до них, и далеко не все тайны еще раскрыты.$b$BЯ хочу, чтобы ты $Gпринес:принесла; мне образцы живущих там слизнюков. Если слухи правдивы и их не тронула порча, я смогу узнать, откуда появились эти существа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите на пробу образцы слизи из Кратера Ун\'Горо. Воспользуйтесь тестовым оборудованием химика Барабоса в Катакомбах, чтобы отобрать 5 наиболее чистых образцов и отдайте их ему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Удивительно! Кратер Ун\'Горо таит куда больше секретов, чем я думал. Интересно, какие еще открытия нас ждут?$B$BПоразительно... Изумительно чистые образцы. Хм, что бы это значило? Похоже, по природе они относятся скорее к стихиям... но непростым. Они напоминают мне... о Древних богах. Мы находили их следы по всему Азероту – вдруг и эти существа каким-то образом связаны с ними?$B$BНадо продолжать исследования.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N? Как успехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к химику Барабосу в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4295,'Эль для Камнеузла','Это что? Ага! Пахнет элем Черного Железа! Пусть я пьян и мало что соображаю, но скажу тебе, добрый сэр: ты настоящий друг!','Кружечка доброго эля Черного Железа была бы сейчас очень кстати! Быстрее, а то я уже начинаю трезветь! А когда я трезвею, у меня сразу мутится зрение... и все расплывается... и ты почему-то становишься очень $Gпохожим:похожей; на того |3-6($R), которого я грохнул на прошлой неделе.','Вернитесь к рядовому Камнеузлу в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эль для Камнеузла',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это что? Ага! Пахнет элем Черного Железа! Пусть я пьян и мало что соображаю, но скажу тебе, добрый сэр: ты настоящий друг!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кружечка доброго эля Черного Железа была бы сейчас очень кстати! Быстрее, а то я уже начинаю трезветь! А когда я трезвею, у меня сразу мутится зрение... и все расплывается... и ты почему-то становишься очень $Gпохожим:похожей; на того |3-6($R), которого я грохнул на прошлой неделе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рядовому Камнеузлу в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4296,'Табличка Семерых','Я прибыл в Пылающие степи из-за легенд о Семерых. Это были дворфы, прославленные знаниями и силой, а значит – и богатством.$b$bИменно к богатству я и стремлюсь!$b$bУзнай мы побольше про Семерых, могли бы оба разбогатеть. Говорят, что в руинах Тауриссана есть табличка Семерых, содержащая знания древних дворфов. Найди ее, перепиши текст и принеси мне. И мы оба узнаем ее тайны!','Перепишите текст с таблички Семерых.','А, ты $Gнашел:нашла; табличку! И как хорошо переписан текст! Ты точно |3-6($C), а не $Gпереписчик:переписчица;?$B$BВот, возьми,$N. Это обещанные деньги.','Удалось переписать мудрость Семерых? Раскрыла ли табличка их тайны?','Вернитесь к Максворту Суперблеску в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Табличка Семерых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прибыл в Пылающие степи из-за легенд о Семерых. Это были дворфы, прославленные знаниями и силой, а значит – и богатством.$b$bИменно к богатству я и стремлюсь!$b$bУзнай мы побольше про Семерых, могли бы оба разбогатеть. Говорят, что в руинах Тауриссана есть табличка Семерых, содержащая знания древних дворфов. Найди ее, перепиши текст и принеси мне. И мы оба узнаем ее тайны!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Перепишите текст с таблички Семерых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, ты $Gнашел:нашла; табличку! И как хорошо переписан текст! Ты точно |3-6($C), а не $Gпереписчик:переписчица;?$B$BВот, возьми,$N. Это обещанные деньги.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось переписать мудрость Семерых? Раскрыла ли табличка их тайны?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Максворту Суперблеску в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4297,'Покормить малыша','Летучие хамелеоны всеядны: это значит, что они питаются как животной, так и растительной пищей. Твое яйцо вот-вот проклюнется, и мы должны быть к этому готовы. Лучшая еда для этих малявок – это мясо, свежее, сочное мясо! Хочешь – верь, хочешь – нет. Почему – я так и не выяснил, но, кажется, это имеет какое-то отношение к замыслу Элуны относительно эльфов. Возможно, они должны были быть защитниками... не знаю.$b$bЯйцо я пока покараулю, а ты сходи и добудь мне свеженьких окороков среброгривых бродяг. Ими-то мы и покормим малыша, когда он вылупится.','Принесите 5 окороков среброгривого бродяги Агнару Зверопасу во Внутренних землях.','Да, это мясо вполне годится. А тем временем, если я не ошибаюсь, твой дракончик начинает вылупляться! Ну, как тебе это? В смысле, каково быть $Gпапой:мамой;? Груз ответственности не давит пока?','Ну что, $N, $Gдобыл:добыла; ли ты мясо? А то твой дракончик вот-вот вылупится. И если он не поест как следует, едва появившись на свет, он и недели не проживет, а это будет жаль.$B$BПо правде говоря, $N, мне вообще жаль отдавать тебе это яйцо. Так не заставляй меня жалеть об этом еще больше!','Вернитесь к Агнару Зверопасу во Внутренние земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покормить малыша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Летучие хамелеоны всеядны: это значит, что они питаются как животной, так и растительной пищей. Твое яйцо вот-вот проклюнется, и мы должны быть к этому готовы. Лучшая еда для этих малявок – это мясо, свежее, сочное мясо! Хочешь – верь, хочешь – нет. Почему – я так и не выяснил, но, кажется, это имеет какое-то отношение к замыслу Элуны относительно эльфов. Возможно, они должны были быть защитниками... не знаю.$b$bЯйцо я пока покараулю, а ты сходи и добудь мне свеженьких окороков среброгривых бродяг. Ими-то мы и покормим малыша, когда он вылупится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 окороков среброгривого бродяги Агнару Зверопасу во Внутренних землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это мясо вполне годится. А тем временем, если я не ошибаюсь, твой дракончик начинает вылупляться! Ну, как тебе это? В смысле, каково быть $Gпапой:мамой;? Груз ответственности не давит пока?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $N, $Gдобыл:добыла; ли ты мясо? А то твой дракончик вот-вот вылупится. И если он не поест как следует, едва появившись на свет, он и недели не проживет, а это будет жаль.$B$BПо правде говоря, $N, мне вообще жаль отдавать тебе это яйцо. Так не заставляй меня жалеть об этом еще больше!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Агнару Зверопасу во Внутренние земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4298,'У вас появился малыш!','Ух ты, да он уже вылупляется!','Поговорите с Агнаром Зверопасом во Внутренних землях.','Вот, бери яйцо... Тебе лучше держать его при себе, чтобы вылупившийся детеныш сразу привязался к тебе. Тогда он будет считать тебя $Gсвоим:своей; $Gпапочкой:мамочкой;.$B$BНу все, $N, поздравляю! У тебя теперь все равно что собственный ребенок!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У вас появился малыш!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ух ты, да он уже вылупляется!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Агнаром Зверопасом во Внутренних землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, бери яйцо... Тебе лучше держать его при себе, чтобы вылупившийся детеныш сразу привязался к тебе. Тогда он будет считать тебя $Gсвоим:своей; $Gпапочкой:мамочкой;.$B$BНу все, $N, поздравляю! У тебя теперь все равно что собственный ребенок!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4299,'<NYI> <TXT>Гробница Семерых','Найдите Гробницу Семерых и положите туда Энигматрон-ПХ83.','Поместите Энигматрон-ПХ83 в Гробницу Семерых и вернитесь к Максворту Суперблеску.','Установить Энигматрон-ПХ83','Вернитесь к Максворту Суперблеску на Скалу Молота Ужаса, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT>Гробница Семерых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Найдите Гробницу Семерых и положите туда Энигматрон-ПХ83.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поместите Энигматрон-ПХ83 в Гробницу Семерых и вернитесь к Максворту Суперблеску.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Установить Энигматрон-ПХ83',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Максворту Суперблеску на Скалу Молота Ужаса, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4300,'Костяные клинки','Да, если так подумать, то, пожалуй, для тебя есть работенка. Джес\'римону пригодится твоя помощь.$b$bВ Кратере Ун\'Горо водятся ящеры – с когтями острыми, как бритва. У большинства ящеров когти черные, как смерть, но у некоторых ящеров они белые. У Раздробленной Руки имеются... клиенты, которые очень ценят оружие, изготовленное из таких когтей. Принеси побольше белых когтей, и Джес\'римон заплатит тебе по совести. А если сделаешь это быстро, то получишь кое-что сверху.','Принесите 8 белых когтей равазавра Джес\'римону в Оргриммаре.','Да, это то, что надо! Спасибо, $N. И тебе удалось уложиться в срок... это замечательно.$B$BБыть может, мы сумеем изготовить из этих когтей оружие и для тебя. Что скажешь?','Клиенты недовольны, $N. Где же обещанные когти?','Вернитесь к Джес\'римону в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Костяные клинки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, если так подумать, то, пожалуй, для тебя есть работенка. Джес\'римону пригодится твоя помощь.$b$bВ Кратере Ун\'Горо водятся ящеры – с когтями острыми, как бритва. У большинства ящеров когти черные, как смерть, но у некоторых ящеров они белые. У Раздробленной Руки имеются... клиенты, которые очень ценят оружие, изготовленное из таких когтей. Принеси побольше белых когтей, и Джес\'римон заплатит тебе по совести. А если сделаешь это быстро, то получишь кое-что сверху.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 белых когтей равазавра Джес\'римону в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это то, что надо! Спасибо, $N. И тебе удалось уложиться в срок... это замечательно.$B$BБыть может, мы сумеем изготовить из этих когтей оружие и для тебя. Что скажешь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Клиенты недовольны, $N. Где же обещанные когти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джес\'римону в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4301,'Могучая У\'ча','Пока ты $gисследовал:исследовала; Ун\'Горо, я встретил и других созданий, охота на которых доставит удовольствие такому мастеру как ты. Одно из них – огромная обезьяна, я видел ее в стае других обезьян к северу отсюда. Ты уже $gбывал:бывала; в этой пещере раньше, однако не могу ручаться, что выйдешь из этой схватки $gживым:живой;, если действительно возьмешься за это задание. $B$BЯ назвал эту обезьяну Уча, она одна из самых могучих детей Матери-Природы. Убей ее, и я буду отстаивать твое право называть себя $gвеликим охотником:великой охотницей;.','Принесите шкуру У\'чи землепроходцу Торве ко входу в Кратер Ун\'Горо.','Отлично, $N! Я доволен. Сегодня ты $Gсовершил:совершила; великое деяние.$B$BУча была одной из самых огромных обезьян, виденных мною за всю жизнь. То, что ты $Gсмог:смога; сразить ее, говорит о твоей собственной силе и храбрости.$B$BПрими это в знак моего уважения. Ты $Gзаслужил:заслужила; это.','Уча... Это был великолепный зверь. Она была огромной и рыжей, а зубы ее были подобны кинжалам. Ее руки толщиной спорили со стволами деревьев, а двигалась она так быстро, что ей позавидовал бы и горный лев! Тебе повезло встретить столь мощное создание для испытания своей храбрости – многим поколениям в моем племени не посчастливилось повстречать ничего подобного.','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Могучая У\'ча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gисследовал:исследовала; Ун\'Горо, я встретил и других созданий, охота на которых доставит удовольствие такому мастеру как ты. Одно из них – огромная обезьяна, я видел ее в стае других обезьян к северу отсюда. Ты уже $gбывал:бывала; в этой пещере раньше, однако не могу ручаться, что выйдешь из этой схватки $gживым:живой;, если действительно возьмешься за это задание. $B$BЯ назвал эту обезьяну Уча, она одна из самых могучих детей Матери-Природы. Убей ее, и я буду отстаивать твое право называть себя $gвеликим охотником:великой охотницей;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите шкуру У\'чи землепроходцу Торве ко входу в Кратер Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! Я доволен. Сегодня ты $Gсовершил:совершила; великое деяние.$B$BУча была одной из самых огромных обезьян, виденных мною за всю жизнь. То, что ты $Gсмог:смога; сразить ее, говорит о твоей собственной силе и храбрости.$B$BПрими это в знак моего уважения. Ты $Gзаслужил:заслужила; это.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уча... Это был великолепный зверь. Она была огромной и рыжей, а зубы ее были подобны кинжалам. Ее руки толщиной спорили со стволами деревьев, а двигалась она так быстро, что ей позавидовал бы и горный лев! Тебе повезло встретить столь мощное создание для испытания своей храбрости – многим поколениям в моем племени не посчастливилось повстречать ничего подобного.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4321,'Давай-ка разберемся','То, что ты $gрассказал:рассказала; мне о пилонах, весьма интересно... $B$BДай мне минутку, мне нужно сделать некоторые расчеты... Зайди ко мне через пару минут, я смогу дать ответ на твой вопрос.','Поговорите с Джей Ди Колли через пару минут.','Так вот, $N! Все это очень интересно... Надюсь, мои диаграммы верны! Я собрала все сведения в эту книгу и отдам ее тебе.$B$BПолагаю, теперь я могу ответить на все твои вопросы о кристаллах, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Давай-ка разберемся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, что ты $gрассказал:рассказала; мне о пилонах, весьма интересно... $B$BДай мне минутку, мне нужно сделать некоторые расчеты... Зайди ко мне через пару минут, я смогу дать ответ на твой вопрос.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джей Ди Колли через пару минут.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так вот, $N! Все это очень интересно... Надюсь, мои диаграммы верны! Я собрала все сведения в эту книгу и отдам ее тебе.$B$BПолагаю, теперь я могу ответить на все твои вопросы о кристаллах, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4322,'Побег!','Пора выбираться отсюда, $n. Помоги мне забрать мои вещи со склада и освободить моих друзей. Если у нас все получится и нам удастся отсюда сбежать, отправляйся в Дозор Морганы и расскажи обо всем маршалу Максвеллу. Он тебе скажет, что делать дальше.','Помогите маршалу Виндзору забрать вещи и освободить его друзей, после чего вернитесь к маршалу Максвеллу и получите дальнейшие инструкции.','Поразительно, $N. Просто невероятно. Виндзор был здесь буквально перед твоим приходом. Ворвался, как ураган, весь такой разгоряченный и буйный. Его притязания поистине грандиозны, но он заявляет, что у него есть на то основания. Сейчас он направляется в Штормград и собирается бросить вызов Болвару и... госпоже Престор.','Ты выглядишь $Gизмученным:измученной;, $N. Возможно, тебе стоит присесть у огня и расслабиться.','Побег!','Вернитесь к маршалу Максвеллу в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора выбираться отсюда, $n. Помоги мне забрать мои вещи со склада и освободить моих друзей. Если у нас все получится и нам удастся отсюда сбежать, отправляйся в Дозор Морганы и расскажи обо всем маршалу Максвеллу. Он тебе скажет, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите маршалу Виндзору забрать вещи и освободить его друзей, после чего вернитесь к маршалу Максвеллу и получите дальнейшие инструкции.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поразительно, $N. Просто невероятно. Виндзор был здесь буквально перед твоим приходом. Ворвался, как ураган, весь такой разгоряченный и буйный. Его притязания поистине грандиозны, но он заявляет, что у него есть на то основания. Сейчас он направляется в Штормград и собирается бросить вызов Болвару и... госпоже Престор.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты выглядишь $Gизмученным:измученной;, $N. Возможно, тебе стоит присесть у огня и расслабиться.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Побег!',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Максвеллу в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4323,'*NYI* *TXT* Убить этих гиен!!!','Мне нужны шкуры гиены, да не какие-нибудь, а самые лучшие! Принеси мне шкуры пятнистых гиен, и я дам тебе чего-нибудь ценного, йоу.','Принесите 7 шкур пятнистой гиены TESTTAUREN на Заставу Вольного Ветра.','Return to [PH] TESTTAUREN.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','*NYI* *TXT* Убить этих гиен!!!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужны шкуры гиены, да не какие-нибудь, а самые лучшие! Принеси мне шкуры пятнистых гиен, и я дам тебе чего-нибудь ценного, йоу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 шкур пятнистой гиены TESTTAUREN на Заставу Вольного Ветра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to [PH] TESTTAUREN.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4324,'Юка Крутипроб','Риббли, мой младший братец, всю жизнь был никчемным придурком и позором для всей семьи, но в итоге оказалось, что он тоже чего-то да стоит и может пригодиться. Но понимаешь, какое дело... чтобы приставить его к работе, нам понадобится твоя помощь.$B$BМоя сестра Юка искала его почти месяц, и в итоге ей удалось узнать, что он прячется в Пылающих степях. Ей нужен наемник, и она обратилась ко мне за помощью.$B$BНе хочешь взяться за это дело? Если берешься, тогда тебе надо переговорить с сестрой. Ты найдешь ее в Пламенеющем Стяге, в пещере к северо-западу от скалы Молота Ужаса.','Переговорите с Юкой Крутипроб в Пылающих степях.','Да, я ищу брата. Его надо найти и вернуть.$B$BПриведи его ко мне. А если он будет сопротивляться... тогда принеси мне хотя бы его голову.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Юка Крутипроб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Риббли, мой младший братец, всю жизнь был никчемным придурком и позором для всей семьи, но в итоге оказалось, что он тоже чего-то да стоит и может пригодиться. Но понимаешь, какое дело... чтобы приставить его к работе, нам понадобится твоя помощь.$B$BМоя сестра Юка искала его почти месяц, и в итоге ей удалось узнать, что он прячется в Пылающих степях. Ей нужен наемник, и она обратилась ко мне за помощью.$B$BНе хочешь взяться за это дело? Если берешься, тогда тебе надо переговорить с сестрой. Ты найдешь ее в Пламенеющем Стяге, в пещере к северо-западу от скалы Молота Ужаса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Переговорите с Юкой Крутипроб в Пылающих степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я ищу брата. Его надо найти и вернуть.$B$BПриведи его ко мне. А если он будет сопротивляться... тогда принеси мне хотя бы его голову.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4341,'Каран Могучий Молот','Вы были в дымящихся руинах Тауриссана? А вам не попадался этот жалкий бездельник Каран Могучий Молот? Это дворф, который был должен охранять мою девочку!$B$B*Король всхлипывает.*$B$BИ теперь она пропала, $n!$B$BМои воины обшарили всю Степь. Им удалось узнать только то, что моя дочка может быть в Глубинах. Может, она уже погибла!$B$BА Каран, видимо, сидит там в плену... найдите его! Я хочу получить ответ!','Пойдите в Глубины Черной горы и найдите Карана Могучего Молота.$B$BКороль упомянул, что Каран сидит там в плену – может, стоит поискать темницу.','Прошу, позволь мне объясниться!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каран Могучий Молот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы были в дымящихся руинах Тауриссана? А вам не попадался этот жалкий бездельник Каран Могучий Молот? Это дворф, который был должен охранять мою девочку!$B$B*Король всхлипывает.*$B$BИ теперь она пропала, $n!$B$BМои воины обшарили всю Степь. Им удалось узнать только то, что моя дочка может быть в Глубинах. Может, она уже погибла!$B$BА Каран, видимо, сидит там в плену... найдите его! Я хочу получить ответ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пойдите в Глубины Черной горы и найдите Карана Могучего Молота.$B$BКороль упомянул, что Каран сидит там в плену – может, стоит поискать темницу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прошу, позволь мне объясниться!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4342,'Рассказ Карана','Пожалуйста, выслушай меня, а потом будешь судить!','Выслушайте рассказ Карана Могучего Молота.','Как ты сам понимаешь, я ничего не мог сделать.','Дай мне закончить рассказ.','Выслушайте рассказ Карана.','Вернитесь к Карану Могучему Молоту в Глубины Черной горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассказ Карана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуйста, выслушай меня, а потом будешь судить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте рассказ Карана Могучего Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как ты сам понимаешь, я ничего не мог сделать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дай мне закончить рассказ.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Выслушайте рассказ Карана.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карану Могучему Молоту в Глубины Черной горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (4343,'Оскверненный ветроцвет','Вернитесь к оскверненному ветроцвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный ветроцвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному ветроцвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4361,'Недобрые вести','Расскажи обо всем королю Магни, $n. Он знает, что делать.','Вернитесь в Стальгорн и сообщите нехорошие новости королю Магни Бронзобороду.','Король Магни в ярости бьет кулаком по столу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недобрые вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расскажи обо всем королю Магни, $n. Он знает, что делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Стальгорн и сообщите нехорошие новости королю Магни Бронзобороду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Король Магни в ярости бьет кулаком по столу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4362,'Судьба королевства','Похоже, и моя судьба, и судьба королевства Стальгорн ныне в руках моего старинного врага Даграна Тауриссана.$B$BВозможно, вы моя последняя надежда, $n. Вы должны спасти мою драгоценную дочь Мойру!$B$BЕсть только один путь наверняка разрушить лежащее на Мойре заклятие Тауриссана – убить его.$B$BНо умоляю, $n, не причиняйте ей вреда! Помните, она под властью Тауриссана! Все, что она будет делать или говорить, – результат злого заклятия Тауриссана!','Вернитесь в Глубины Черной горы и освободите принцессу Мойру Бронзобород от злобного императора Даграна Тауриссана.','Вернитесь к принцессе Мойре Бронзобород в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба королевства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, и моя судьба, и судьба королевства Стальгорн ныне в руках моего старинного врага Даграна Тауриссана.$B$BВозможно, вы моя последняя надежда, $n. Вы должны спасти мою драгоценную дочь Мойру!$B$BЕсть только один путь наверняка разрушить лежащее на Мойре заклятие Тауриссана – убить его.$B$BНо умоляю, $n, не причиняйте ей вреда! Помните, она под властью Тауриссана! Все, что она будет делать или говорить, – результат злого заклятия Тауриссана!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Глубины Черной горы и освободите принцессу Мойру Бронзобород от злобного императора Даграна Тауриссана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцессе Мойре Бронзобород в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4363,'Королевский сюрприз','Тауриссан был великим и доблестным дворфом. Ты $gразрушил:разрушила; мою жизнь и жизнь моего будущего ребенка!$B$B*Вы уверены, что принцесса до сих пор пребывает под действием чар императора.*$B$BВозвращайся в Стальгорн и скажи моему отцу, что наследником королевства будет дворф Черного Железа.$B$BНравится это ему или нет, но именно так все и будет!','Вернитесь в Стальгорн и переговорите с королем Магни Бронзобородом.','<Король Магни Бронзобород явно расстроен.>$B$BСдается мне, даже в смерти Тауриссан победил.$B$BБольше я не нуждаюсь в твоих услугах, $N. Но прежде чем ты покинешь нас, выбери себе награду из королевских сокровищниц.$B$B<Король садится на трон и погружается в раздумья.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королевский сюрприз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тауриссан был великим и доблестным дворфом. Ты $gразрушил:разрушила; мою жизнь и жизнь моего будущего ребенка!$B$B*Вы уверены, что принцесса до сих пор пребывает под действием чар императора.*$B$BВозвращайся в Стальгорн и скажи моему отцу, что наследником королевства будет дворф Черного Железа.$B$BНравится это ему или нет, но именно так все и будет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Стальгорн и переговорите с королем Магни Бронзобородом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Король Магни Бронзобород явно расстроен.>$B$BСдается мне, даже в смерти Тауриссан победил.$B$BБольше я не нуждаюсь в твоих услугах, $N. Но прежде чем ты покинешь нас, выбери себе награду из королевских сокровищниц.$B$B<Король садится на трон и погружается в раздумья.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4381,'Кристалл восстановления','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.','Табличка пилона позволяет сочетать зеленые и желтые кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для исцеления себя или своих союзников.','Вернитесь к Северному хрустальному пилону в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристалл восстановления',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Табличка пилона позволяет сочетать зеленые и желтые кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для исцеления себя или своих союзников.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Северному хрустальному пилону в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4382,'Кристалл силы духа','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.','Табличка пилона позволяет сочетать зеленые и синие кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для укрепления своего духа.','Вернитесь к Восточному хрустальному пилону в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристалл силы духа',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Табличка пилона позволяет сочетать зеленые и синие кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для укрепления своего духа.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Восточному хрустальному пилону в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4383,'Кристалл-хранитель','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.','Табличка пилона позволяет сочетать зеленые и красные кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для усиления защиты от физических повреждений.','Вернитесь к Западному хрустальному пилону в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристалл-хранитель',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Табличка пилона позволяет сочетать зеленые и красные кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для усиления защиты от физических повреждений.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Западному хрустальному пилону в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4384,'Кристалл-губитель','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.','Табличка пилона позволяет сочетать красные и синие кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для ослабления обороны противника.','Вернитесь к Западному хрустальному пилону в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристалл-губитель',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Табличка пилона позволяет сочетать красные и синие кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для ослабления обороны противника.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Западному хрустальному пилону в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4385,'Обжигающий кристалл','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.','Табличка пилона позволяет сочетать красные и желтые кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для производства мощного взрыва, наносящего серьезный ущерб силам противника.','Вернитесь к Северному хрустальному пилону в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обжигающий кристалл',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Табличка пилона позволяет сочетать красные и желтые кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для производства мощного взрыва, наносящего серьезный ущерб силам противника.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Северному хрустальному пилону в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4386,'Кристальная спираль','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.','Табличка пилона позволяет сочетать синие и желтые кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для создания щита, наносящего повреждения противнику.','Вернитесь к Восточному хрустальному пилону в Кратер Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристальная спираль',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы аккуратно выстраиваете кристаллы в табличке. Когда последний из них занимает свое место, вспыхивает яркий свет, и кристаллы оказываются сплавлены воедино.$B$BТеперь полученное сочетание – ваше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Табличка пилона позволяет сочетать синие и желтые кристаллы Силы.$B$BСогласно книге Джей Ди, это сочетание можно использовать для создания щита, наносящего повреждения противнику.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Восточному хрустальному пилону в Кратер Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (4401,'Оскверненный песнецвет','Вернитесь к оскверненному песнецвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный песнецвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному песнецвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4402,'Кактусовый десерт Галгара','Ну и жарища у нас в долине!$b$b*Галгар утирает пот со лба.*$b$bБыли бы у меня плоды кактуса, я бы изготовил свой знаменитый кактусовый десерт! Ничто не освежает лучше этого восхитительного лакомства.$b$bЗнаешь что, $n? Принеси-ка мне шесть плодов кактуса, и я изготовлю тебе несколько порций кактусового десерта. Они тебе пригодятся в путешествиях. Плоды кактуса можно собрать со здешних кактусов.','Принесите Галгару 6 плодов кактуса. Не забудьте, их можно найти возле кактусов.','Ну что, собрала плоды?','Вернитесь к Галгару в Долину Испытаний, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кактусовый десерт Галгара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну и жарища у нас в долине!$b$b*Галгар утирает пот со лба.*$b$bБыли бы у меня плоды кактуса, я бы изготовил свой знаменитый кактусовый десерт! Ничто не освежает лучше этого восхитительного лакомства.$b$bЗнаешь что, $n? Принеси-ка мне шесть плодов кактуса, и я изготовлю тебе несколько порций кактусового десерта. Они тебе пригодятся в путешествиях. Плоды кактуса можно собрать со здешних кактусов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Галгару 6 плодов кактуса. Не забудьте, их можно найти возле кактусов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, собрала плоды?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галгару в Долину Испытаний, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (4403,'Оскверненный ветроцвет','Вернитесь к оскверненному ветроцвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный ветроцвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному ветроцвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4421,'Порча Нефритового Пламени','Мало кто отваживается искать здесь приключений... Порча, поразившая Оскверненный лес, расползается, поражая все без разбору.$B$BЯ, состоя в Изумрудном Круге, ищу способ исцелить эти земли, но есть те, кто радуется ее мучениям.$B$BЯ говорю о сатирах из племени Нефритового Пламени, что живут к северо-западу отсюда, в руинах Констелласа. Ими предводительствует особенно жестокий сатир по имени Ксаватрас. Они продолжают поражать заразой любое живое существо, которое попадается им на пути.$B$BМы должны защитить этот край – ведь некогда он был нашим. Срази Ксаватраса и уничтожь его приспешников.','Убейте 11 скверноподданных, 9 тенеловов, 9 разбойников из племени Нефритового Пламени и Ксаватраса. Возвращайтесь к Эридане Грусти Ветра в Оскверненный лес по выполнении задания.','Вернитесь к Эридане Грусти Ветра в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порча Нефритового Пламени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мало кто отваживается искать здесь приключений... Порча, поразившая Оскверненный лес, расползается, поражая все без разбору.$B$BЯ, состоя в Изумрудном Круге, ищу способ исцелить эти земли, но есть те, кто радуется ее мучениям.$B$BЯ говорю о сатирах из племени Нефритового Пламени, что живут к северо-западу отсюда, в руинах Констелласа. Ими предводительствует особенно жестокий сатир по имени Ксаватрас. Они продолжают поражать заразой любое живое существо, которое попадается им на пути.$B$BМы должны защитить этот край – ведь некогда он был нашим. Срази Ксаватраса и уничтожь его приспешников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 11 скверноподданных, 9 тенеловов, 9 разбойников из племени Нефритового Пламени и Ксаватраса. Возвращайтесь к Эридане Грусти Ветра в Оскверненный лес по выполнении задания.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эридане Грусти Ветра в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4441,'Древа в узах скверны','Флейта, найденная тобой, вырезана из древесины сторожевого древа, верного союзника ночных эльфов.$B$BСатиры поражают порчей все, на что наталкиваются, в том числе и древа, для которых Оскверненный лес был домом родным. Из-за скверны дух древа попал в узы и теперь терзается, не в силах освободиться. Эти узы скверны, что ты $gнашел:нашла;, наверняка с этим связаны.$B$BМы должны попытаться очистить эту флейту от скверны, $n. Принеси мне благословенной воды из дарнасского Храма Луны.','Отправляйтесь в Дарнас и наберите в фиал Эриданы благословенной воды из Храма Луны. Возвращайтесь к Эридане с полным фиалом.','Вернитесь к Эридане Грусти Ветра в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древа в узах скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Флейта, найденная тобой, вырезана из древесины сторожевого древа, верного союзника ночных эльфов.$B$BСатиры поражают порчей все, на что наталкиваются, в том числе и древа, для которых Оскверненный лес был домом родным. Из-за скверны дух древа попал в узы и теперь терзается, не в силах освободиться. Эти узы скверны, что ты $gнашел:нашла;, наверняка с этим связаны.$B$BМы должны попытаться очистить эту флейту от скверны, $n. Принеси мне благословенной воды из дарнасского Храма Луны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Дарнас и наберите в фиал Эриданы благословенной воды из Храма Луны. Возвращайтесь к Эридане с полным фиалом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эридане Грусти Ветра в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4442,'Очищение явлено!','При помощи сей воды Элуны я попытаюсь смыть скверну с этой флейты. Мы должны покончить со страданиями...$B$BДа направит мою руку Элуна и да укрепит она мое сердце.$B$BПодожди немного – потом поговорим.','Через мгновение заговорите с Эриданой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение явлено!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При помощи сей воды Элуны я попытаюсь смыть скверну с этой флейты. Мы должны покончить со страданиями...$B$BДа направит мою руку Элуна и да укрепит она мое сердце.$B$BПодожди немного – потом поговорим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Через мгновение заговорите с Эриданой.',`objectives_loc8`);
