INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4449,'Попался!','Эй! Эй, ты, там! Иди скорей сюда! $B$BПомоги мне! Я спасался бегством от дворфов Черного Железа и попытался спрятаться от них здесь. Проклятые геологи со своей проклятой магией! Они увидели, что я здесь прячусь, и заперли меня здесь! Проучи, проучи этих проклятых геологов! И... это... добудь мне несколько лоскутков шелка... так... вдруг пригодится...','Убейте 8 геологов из клана Черного Железа и принесите 15 отрезов шелка тому, кто заперт в отхожем месте в Тлеющем ущелье.','О, какое облегчение! Как я рад, $N! Тебе удалось отомстить проклятым геологам? Их наглость не знала границ, однако. Не знаю как благодарить тебя! Ты это... погоди минутку, мне тут надо закончить некоторые дела...','Я здесь весь день! Дай мне эти лоскутки шелковой ткани! Я имею в виду геологам. Задай этим геологам! Они заслужили то, чтобы почувствовать мой, хорошо... твой гнев.','Вернитесь к деревянному туалету в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Попался!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй! Эй, ты, там! Иди скорей сюда! $B$BПомоги мне! Я спасался бегством от дворфов Черного Железа и попытался спрятаться от них здесь. Проклятые геологи со своей проклятой магией! Они увидели, что я здесь прячусь, и заперли меня здесь! Проучи, проучи этих проклятых геологов! И... это... добудь мне несколько лоскутков шелка... так... вдруг пригодится...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 геологов из клана Черного Железа и принесите 15 отрезов шелка тому, кто заперт в отхожем месте в Тлеющем ущелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, какое облегчение! Как я рад, $N! Тебе удалось отомстить проклятым геологам? Их наглость не знала границ, однако. Не знаю как благодарить тебя! Ты это... погоди минутку, мне тут надо закончить некоторые дела...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я здесь весь день! Дай мне эти лоскутки шелковой ткани! Я имею в виду геологам. Задай этим геологам! Они заслужили то, чтобы почувствовать мой, хорошо... твой гнев.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к деревянному туалету в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4450,'Учетная книга из Танариса','Ты знаешь, мне это кое-что напоминает.$B$BНе хочешь закончить за меня одну работенку, за которую я взялся в Танарисе? Это пара пустяков...$B$BКринкель Сталлер из Прибамбасска искал какие-то вещи – некоторые здесь, в Тлеющем ущелье, а некоторые в других местах. Может, глянешь на список? Ты наверняка сможешь что-нибудь найти.$B$BЕсли тебе это интересно, я просуну его учетную книгу под дверь. Отнесешь ее ему вместе с разыскиваемыми вещами, когда соберешь их все.','Возьмите учетную книгу Кринкеля Сталлера и найдите все перечисленные в ней вещи. Затем отнесите их и книгу Кринкелю Сталлеру в Танарис.','Ого, да ты $Gсмог:смогла; выполнить эту работу! Прекрасно. Полагаю, теперь ты попросишь меня выковать для тебя что-нибудь.$B$BУ меня есть превосходное оружие и доспехи. Благодарю тебя, |3-6($C)!$B$BДумаю, ты $Gзаслужил:заслужила;... хммм... что-нибудь полезное.','Да-да? Чем я могу помочь тебе, $R? Я ужасно занят, у меня полно капризных клиентов, которым вынь да положь немедленно их заказ. Так что давай пошустрей со своими делами. Не хочу показаться грубым, но у меня совершенно нет времени на пустую болтовню!','Вернитесь к Кринкелю Сталлеру в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Учетная книга из Танариса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты знаешь, мне это кое-что напоминает.$B$BНе хочешь закончить за меня одну работенку, за которую я взялся в Танарисе? Это пара пустяков...$B$BКринкель Сталлер из Прибамбасска искал какие-то вещи – некоторые здесь, в Тлеющем ущелье, а некоторые в других местах. Может, глянешь на список? Ты наверняка сможешь что-нибудь найти.$B$BЕсли тебе это интересно, я просуну его учетную книгу под дверь. Отнесешь ее ему вместе с разыскиваемыми вещами, когда соберешь их все.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите учетную книгу Кринкеля Сталлера и найдите все перечисленные в ней вещи. Затем отнесите их и книгу Кринкелю Сталлеру в Танарис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ого, да ты $Gсмог:смогла; выполнить эту работу! Прекрасно. Полагаю, теперь ты попросишь меня выковать для тебя что-нибудь.$B$BУ меня есть превосходное оружие и доспехи. Благодарю тебя, |3-6($C)!$B$BДумаю, ты $Gзаслужил:заслужила;... хммм... что-нибудь полезное.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да-да? Чем я могу помочь тебе, $R? Я ужасно занят, у меня полно капризных клиентов, которым вынь да положь немедленно их заказ. Так что давай пошустрей со своими делами. Не хочу показаться грубым, но у меня совершенно нет времени на пустую болтовню!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кринкелю Сталлеру в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4451,'Ключ к свободе','Маленький медный ключик выглядит совершенно непритязательно. Единственное, что выдает его значимость, – надпись, выгравированная на бородке: $B$B"Служебные помещения Черного Железа – изготовление дубликатов строжайше запрещено".$B$BУ вас нет ни малейшего представления, что это за ключ и куда ведет открываемая им дверь.','Найдите дверь в Тлеющем ущелье, к которой подходит ключ от дома Грязнули.','Вот те на! Чтоб мне провалиться! Ты $Gнашел:нашл; ключ! Я знал, что проклятые дворфы Черного Железа спрятали его, после того как заперли меня в этой дыре! О, благодарю тебя, $N! Скорее открой дверь и выпусти старика Локида на свободу!','<кашель> Кто там? Не видите что ли, занято!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключ к свободе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Маленький медный ключик выглядит совершенно непритязательно. Единственное, что выдает его значимость, – надпись, выгравированная на бородке: $B$B"Служебные помещения Черного Железа – изготовление дубликатов строжайше запрещено".$B$BУ вас нет ни малейшего представления, что это за ключ и куда ведет открываемая им дверь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите дверь в Тлеющем ущелье, к которой подходит ключ от дома Грязнули.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот те на! Чтоб мне провалиться! Ты $Gнашел:нашл; ключ! Я знал, что проклятые дворфы Черного Железа спрятали его, после того как заперли меня в этой дыре! О, благодарю тебя, $N! Скорее открой дверь и выпусти старика Локида на свободу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<кашель> Кто там? Не видите что ли, занято!',`requestitemstext_loc8`);
