INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4463,'Манускрипт размышления','Забирай свою безделушку, неразумная тварь. Оставь меня в покое!','Принеси все составляющие, $Gсмертный:смертная;.$B$BКроме того, я потребую с тебя тридцать золотых за создание этой безделушки.','Вернитесь к Матредису Огнезвезду в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Манускрипт размышления',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Забирай свою безделушку, неразумная тварь. Оставь меня в покое!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принеси все составляющие, $Gсмертный:смертная;.$B$BКроме того, я потребую с тебя тридцать золотых за создание этой безделушки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матредису Огнезвезду в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
