INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (4467,'Оскверненный ветроцвет','Вернитесь к оскверненному ветроцвету в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный ветроцвет',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к оскверненному ветроцвету в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4481,'Манускрипт здоровья','Это вызов его памяти... Смертный оканчивает работу всей его жизни.$B$BЗабирай свою безделушку и убирайся!','За все в этом мире приходится платить. Цена искомого предмета – тридцать золотых.$B$BЕстественно, большую часть собранных тобой компонентов я оставлю себе. Но не беспокойся, свою игрушку ты получишь.','Вернитесь к Матредису Огнезвезду в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Манускрипт здоровья',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это вызов его памяти... Смертный оканчивает работу всей его жизни.$B$BЗабирай свою безделушку и убирайся!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','За все в этом мире приходится платить. Цена искомого предмета – тридцать золотых.$B$BЕстественно, большую часть собранных тобой компонентов я оставлю себе. Но не беспокойся, свою игрушку ты получишь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матредису Огнезвезду в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4482,'Манускрипт упорства','Кариэль потребовалось несколько жизней, чтобы завершить текущую библиотеку, $R.Все для чего? Чтобы его ученик мог стоять в Пылающих степях и убивать свои исследования, чтобы утолить нескончаемую тайную жажду ... Прокляните эту гнусную зависимость.$B$BМне противно ваше отсутствие сострадания и ненасытная жадность. Уходи!','Тридцать золотых, $R. Тридцать золота и необходимые компоненты.','Вернитесь к Матредису Огнезвезду в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Манускрипт упорства',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кариэль потребовалось несколько жизней, чтобы завершить текущую библиотеку, $R.Все для чего? Чтобы его ученик мог стоять в Пылающих степях и убивать свои исследования, чтобы утолить нескончаемую тайную жажду ... Прокляните эту гнусную зависимость.$B$BМне противно ваше отсутствие сострадания и ненасытная жадность. Уходи!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тридцать золотых, $R. Тридцать золота и необходимые компоненты.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матредису Огнезвезду в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4483,'Манускрипт устойчивости','Прочие манускрипты рассеяны по свету. По таким уголкам, куда ты не осмелишься войти. Которых бы лучше и не было.$B$BЯ выпью из этих составляющих силу. А ты получишь то, что останется...','Если тебе нужна стойкость, мне нужно тридцать золотых.','Вернитесь к Матредису Огнезвезду в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Манускрипт устойчивости',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прочие манускрипты рассеяны по свету. По таким уголкам, куда ты не осмелишься войти. Которых бы лучше и не было.$B$BЯ выпью из этих составляющих силу. А ты получишь то, что останется...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если тебе нужна стойкость, мне нужно тридцать золотых.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матредису Огнезвезду в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4484,'Манускрипт ненасытности','Голова болит... Сила бескрайних пределов вселенной... Ахххх!$B$B<Матредис кривится от боли.>$B$BБери, что тебе нужно, и уходи!','Не трать попусту мое время, $R. Давай мне все, что нужно. Тридцать золотых и компоненты.','Вернитесь к Матредису Огнезвезду в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Манускрипт ненасытности',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Голова болит... Сила бескрайних пределов вселенной... Ахххх!$B$B<Матредис кривится от боли.>$B$BБери, что тебе нужно, и уходи!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не трать попусту мое время, $R. Давай мне все, что нужно. Тридцать золотых и компоненты.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матредису Огнезвезду в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4485,'Фолиант благородства','Приветствую, $n. Я вижу, твоя решимость по-прежнему сильна, как и твоя вера.$b$bДумаю, настало время тебе поговорить с Даторианом Раллом в Штормграде. Ты $Gдолжен:должна; получить еще несколько уроков, и я чувствую, ты к ним $Gготов:готова;.$b$bНайди Даториана в Соборе Света – и пожалуйста, $n, отнесись к его урокам серьезно. Ты $Gдобился:добилась; своего положения благодаря скромности и упорному труду, так не разочаруй нас – не становись $Gвысокомерным:высокомерной;.$b$bУдачи тебе.','Поговорите с Даторианом Раллом в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант благородства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, $n. Я вижу, твоя решимость по-прежнему сильна, как и твоя вера.$b$bДумаю, настало время тебе поговорить с Даторианом Раллом в Штормграде. Ты $Gдолжен:должна; получить еще несколько уроков, и я чувствую, ты к ним $Gготов:готова;.$b$bНайди Даториана в Соборе Света – и пожалуйста, $n, отнесись к его урокам серьезно. Ты $Gдобился:добилась; своего положения благодаря скромности и упорному труду, так не разочаруй нас – не становись $Gвысокомерным:высокомерной;.$b$bУдачи тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Даторианом Раллом в Штормграде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4486,'Фолиант благородства','Ну-ка, ну-ка, поглядите на могучего паладина во всей красе!$b$bПрошу прощения, $n, я не в обиду... Просто иногда немного завидую твоим достижениям. Тиза говорит, что в этом – моя слабость, и я обещал ей, что искореню этот недостаток. Но пока не преуспел, $Gсам:сама; понимаешь.$b$bНо вот почему я хотел с тобой поговорить: Даториан Ралл из Штормграда сообщил, что хочет встретиться с тобой в Соборе Света, когда ты будешь к этому $Gготов:готова;. Звучало веско. Звучало так, как будто что-то эдакое происходит.','Поговорите с Даторианом Раллом в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фолиант благородства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну-ка, ну-ка, поглядите на могучего паладина во всей красе!$b$bПрошу прощения, $n, я не в обиду... Просто иногда немного завидую твоим достижениям. Тиза говорит, что в этом – моя слабость, и я обещал ей, что искореню этот недостаток. Но пока не преуспел, $Gсам:сама; понимаешь.$b$bНо вот почему я хотел с тобой поговорить: Даториан Ралл из Штормграда сообщил, что хочет встретиться с тобой в Соборе Света, когда ты будешь к этому $Gготов:готова;. Звучало веско. Звучало так, как будто что-то эдакое происходит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Даторианом Раллом в Штормграде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4487,'Призыв коня Скверны','Ага, хорошо, что ты здесь. Я посылал $gсуккуба:инфернала;, чтобы подогреть твой интерес, но, похоже, ты $Gуспел:успела; оказаться здесь раньше, чем $gона добралась:он добрался; до тебя. Ладно.$B$BТут недавно пошли разговоры о твоем растущем могуществе – и это очень хорошо для тебя, а для других, наверное, не очень. Короче, я думаю, что ты уже достаточно $Gзарекомендовал:зарекомендовала; себя и потому заслуживаешь... хе-хе... подарочка.$B$BВ Степях над Кабестаном ты найдешь человека по имени Страхад. Уверен, вы уже встречались.','Поговорите в Кабестане со Страхадом Фарсаном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв коня Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ага, хорошо, что ты здесь. Я посылал $gсуккуба:инфернала;, чтобы подогреть твой интерес, но, похоже, ты $Gуспел:успела; оказаться здесь раньше, чем $gона добралась:он добрался; до тебя. Ладно.$B$BТут недавно пошли разговоры о твоем растущем могуществе – и это очень хорошо для тебя, а для других, наверное, не очень. Короче, я думаю, что ты уже достаточно $Gзарекомендовал:зарекомендовала; себя и потому заслуживаешь... хе-хе... подарочка.$B$BВ Степях над Кабестаном ты найдешь человека по имени Страхад. Уверен, вы уже встречались.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Кабестане со Страхадом Фарсаном.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4488,'Призыв коня Скверны','О, $n, ты $Gпочтил:почтила; нас своим присутствием. Какая честь!$B$BНадеюсь, ты не думаешь, что мы будем тебя облизывать с ног до головы. Может, ты и быстро набираешь могущество, но ты все еще дитя малое в том, что касается истинного знания и мудрости. Если не поостережешься, тебя охватит одержимость, и воля твоя ослабеет.$B$BНо ближе к делу – Страхад желает говорить с тобой. Он по-прежнему живет в башне над Кабестаном в Степях. Советую не тянуть канитель.','Поговорите в Кабестане со Страхадом Фарсаном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв коня Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, $n, ты $Gпочтил:почтила; нас своим присутствием. Какая честь!$B$BНадеюсь, ты не думаешь, что мы будем тебя облизывать с ног до головы. Может, ты и быстро набираешь могущество, но ты все еще дитя малое в том, что касается истинного знания и мудрости. Если не поостережешься, тебя охватит одержимость, и воля твоя ослабеет.$B$BНо ближе к делу – Страхад желает говорить с тобой. Он по-прежнему живет в башне над Кабестаном в Степях. Советую не тянуть канитель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Кабестане со Страхадом Фарсаном.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4489,'Призыв коня Скверны','А, |3-6($r)! Иди сюда!$B$BТебя ведь зовут $n, не так ли?$B$BЯ так и думал. Короче: твоя мощь растет, и это было замечено. Теперь пора наградить тебя за старания.$B$BИди в Степи. Там, над Кабестаном, ищи Страхада Фарсана – может, помнишь его? У него есть для тебя кое-что. Это много времени не займет.','Поговорите в Кабестане со Страхадом Фарсаном.','Значит, ты снова $Gрешил:решила; пожаловать меня своим визитом. Очень мило с твоей стороны.$B$BМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв коня Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, |3-6($r)! Иди сюда!$B$BТебя ведь зовут $n, не так ли?$B$BЯ так и думал. Короче: твоя мощь растет, и это было замечено. Теперь пора наградить тебя за старания.$B$BИди в Степи. Там, над Кабестаном, ищи Страхада Фарсана – может, помнишь его? У него есть для тебя кое-что. Это много времени не займет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Кабестане со Страхадом Фарсаном.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты снова $Gрешил:решила; пожаловать меня своим визитом. Очень мило с твоей стороны.$B$BМои помощники все гадали – придешь или нет? Я говорил им – несомненно, придет. Когда речь заходит о могуществе, летишь как мотылек на свечу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4490,'Призыв коня Скверны','Я бы наградил тебя за терпение да усердие. Но, знаешь ли, в будущем призывание коня Скверны будет куда труднее. Придется заслужить награду... и это будет непросто.$B$BПока же получи способность призывать эту тварь и пользуйся ей по своему усмотрению.','Поговорите в Кабестане со Страхадом Фарсаном, чтобы получить способность призывать коня Скверны.','Удачи, $N. Надеюсь встретиться с тобой в будущем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв коня Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бы наградил тебя за терпение да усердие. Но, знаешь ли, в будущем призывание коня Скверны будет куда труднее. Придется заслужить награду... и это будет непросто.$B$BПока же получи способность призывать эту тварь и пользуйся ей по своему усмотрению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Кабестане со Страхадом Фарсаном, чтобы получить способность призывать коня Скверны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Удачи, $N. Надеюсь встретиться с тобой в будущем.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (4491,'Дружеская помощь','Уф... Как здесь жарко! $B$BЯ тут прогуливался по окрестностям, как вдруг накатила эта жуткая жара. Похоже, у меня тепловой удар. $B$BПомоги мне добраться до моей подруги Мучи в Укрытие Маршалла. Думаю, я сумею дойти, если кто-то будет вести меня. $B$BЕсли я вдруг потеряю сознание, просто плесни мне в лицо воды из фляги Мучи. Думаю, этого будет достаточно...','Отведите Ринго к Муче Кусора в Укрытие Маршалла. $B$BЕсли Ринго потеряет сознание, плесните на него воды из фляги Спрэггл, чтобы привести его в чувство.','Да, Ринго совсем плох, $N, но я рада, что он вернулся в целости и сохранности...$B$BСпасибо, что $Gразыскал:разыскала; его!','О, я так волновалась за Ринго!','Доставить Ринго к Муче Кусора в Укрытие Маршалла.','Вернитесь к Муче Кусоре в Укрытие Маршалла, что в Кратере Ун\'Горо.','Доставить Ринго к Муче Кусора в Укрытие Маршалла.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дружеская помощь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уф... Как здесь жарко! $B$BЯ тут прогуливался по окрестностям, как вдруг накатила эта жуткая жара. Похоже, у меня тепловой удар. $B$BПомоги мне добраться до моей подруги Мучи в Укрытие Маршалла. Думаю, я сумею дойти, если кто-то будет вести меня. $B$BЕсли я вдруг потеряю сознание, просто плесни мне в лицо воды из фляги Мучи. Думаю, этого будет достаточно...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите Ринго к Муче Кусора в Укрытие Маршалла. $B$BЕсли Ринго потеряет сознание, плесните на него воды из фляги Спрэггл, чтобы привести его в чувство.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, Ринго совсем плох, $N, но я рада, что он вернулся в целости и сохранности...$B$BСпасибо, что $Gразыскал:разыскала; его!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, я так волновалась за Ринго!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Доставить Ринго к Муче Кусора в Укрытие Маршалла.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муче Кусоре в Укрытие Маршалла, что в Кратере Ун\'Горо.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Доставить Ринго к Муче Кусора в Укрытие Маршалла.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4492,'Потерялся!','Помоги мне, $n! Мой друг Ринго отправился сегодня исследовать вулкан к югу отсюда, и его что-то долго нет! Я очень беспокоюсь. $B$BТы сможешь найти его? Вот, возьми с собой эту флягу, думаю она ему пригодится!','Найдите Ринго на Вулкане Огненного Венца.','О, я так рад, что ты $Gнашел:нашла; меня!','Кто... Кто здесь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерялся!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помоги мне, $n! Мой друг Ринго отправился сегодня исследовать вулкан к югу отсюда, и его что-то долго нет! Я очень беспокоюсь. $B$BТы сможешь найти его? Вот, возьми с собой эту флягу, думаю она ему пригодится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Ринго на Вулкане Огненного Венца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, я так рад, что ты $Gнашел:нашла; меня!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто... Кто здесь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (4493,'Нашествие силитидов','Поговорите с алхимиком Пестычинсом в Прибамбасске.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нашествие силитидов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с алхимиком Пестычинсом в Прибамбасске.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4494,'Нашествие силитидов','Поговорите с алхимиком Пестычинсом в Прибамбасске.','Да, я так понимаю, тебя Зилзибин прислал? Твой опыт воистину бесценен: до тебя я не встречал никого, кому доводилось сражаться с этими тварями. Что касается идеи Зиба насчет Кратера Ун\'Горо... Может быть, он и прав. Ун\'Горо – это таинственные и опасные джунгли к западу отсюда. Может быть, мы действительно подошли на шаг ближе к разрешению загадки силитидов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нашествие силитидов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с алхимиком Пестычинсом в Прибамбасске.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я так понимаю, тебя Зилзибин прислал? Твой опыт воистину бесценен: до тебя я не встречал никого, кому доводилось сражаться с этими тварями. Что касается идеи Зиба насчет Кратера Ун\'Горо... Может быть, он и прав. Ун\'Горо – это таинственные и опасные джунгли к западу отсюда. Может быть, мы действительно подошли на шаг ближе к разрешению загадки силитидов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (4495,'Добрый друг','Мой друг по имени Иверрон обычно навещает меня в одно и то же время каждый день. Странно, что сегодня он вообще не пришел – он задерживается уже на несколько часов.$B$BПризнаться, $n, я несколько волнуюсь. Иверрон проводит много времени возле пещеры к северу отсюда, и я знаю, насколько там опасно – это ведь логово пауков!$B$BПослушай, если ты вдруг направляешься в ту сторону, то не поищешь ли Иверрона?','Найдите Иверрона возле пещеры на севере.','А, это ты, юный |3-6($C. Вижу, ты желаешь продолжить свое обучение. Это хорошо.\n\nСкажи, известно ли тебе, что такое Изумрудный Сон? Хотя, возможно, ты еще к этому не готова... Ну ладно, всему свое время.\n\nПока что обсудим другие вопросы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добрый друг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой друг по имени Иверрон обычно навещает меня в одно и то же время каждый день. Странно, что сегодня он вообще не пришел – он задерживается уже на несколько часов.$B$BПризнаться, $n, я несколько волнуюсь. Иверрон проводит много времени возле пещеры к северу отсюда, и я знаю, насколько там опасно – это ведь логово пауков!$B$BПослушай, если ты вдруг направляешься в ту сторону, то не поищешь ли Иверрона?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Иверрона возле пещеры на севере.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, это ты, юный |3-6($C. Вижу, ты желаешь продолжить свое обучение. Это хорошо.\n\nСкажи, известно ли тебе, что такое Изумрудный Сон? Хотя, возможно, ты еще к этому не готова... Ну ладно, всему свое время.\n\nПока что обсудим другие вопросы.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4496,'Путаница в джунглях','Исследования показали, что силитиды подобны пчелам – стоит убить королеву улья, и остальные без нее пропадут. Я создам приманку, которая позволит тебе выманить королеву. Выманив ее, сразись с ней.$b$bВпрочем, для начала нам понадобятся некоторые реагенты. Отправляйся на запад, в ульи силитидов в Кратере Ун\'Горо и принеси ароматическую железу одного из мерзких жуков. Кроме того мне понадобятся образцы почвы из кратера.','Принесите ароматическую железу Гориши и 5 образцов земли из Кратера Ун\'Горо алхимику Пестычинсу в Прибамбасск.','Вернитесь к алхимику Пестычинсу в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путаница в джунглях',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Исследования показали, что силитиды подобны пчелам – стоит убить королеву улья, и остальные без нее пропадут. Я создам приманку, которая позволит тебе выманить королеву. Выманив ее, сразись с ней.$b$bВпрочем, для начала нам понадобятся некоторые реагенты. Отправляйся на запад, в ульи силитидов в Кратере Ун\'Горо и принеси ароматическую железу одного из мерзких жуков. Кроме того мне понадобятся образцы почвы из кратера.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ароматическую железу Гориши и 5 образцов земли из Кратера Ун\'Горо алхимику Пестычинсу в Прибамбасск.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алхимику Пестычинсу в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4501,'Опасайся терродактилей','Требуется: опытный боец для устранения угрозы со стороны терродактилей, населяющих Кратер Ун\'Горо. Популяция этих тварей растет, они уже представляют серьезную угрозу забредшим в кратер путникам. $B$BНеобходимо уменьшить популяцию, убив 10 терродактилей. $B$BВыполнивших задание просьба обращаться за наградой к Муче Кусора.','Убейте 10 терродактилей, затем поговорите со Мучей Кусора в Укрытии Маршалла.','Я просто в шоке от жутедактилей! Спасибо тебе, $n! Теперь я хотя бы смогу спокойно высунуть нос из Укрытия Маршалла!','Сказать по правде, я не особо беспокоился о странных существах ... До того дня, когда я увидел, что это написано на стороне большого камня.$B$BОстерегайтесь ПТЕРОДАКТЕЛЕЙ$B$BКто мог это написать? Я не знаю, но это слишком жутко, чтобы просто игнорировать!','Вернитесь к Муче Кусоре в Укрытие Маршалла, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасайся терродактилей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Требуется: опытный боец для устранения угрозы со стороны терродактилей, населяющих Кратер Ун\'Горо. Популяция этих тварей растет, они уже представляют серьезную угрозу забредшим в кратер путникам. $B$BНеобходимо уменьшить популяцию, убив 10 терродактилей. $B$BВыполнивших задание просьба обращаться за наградой к Муче Кусора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 терродактилей, затем поговорите со Мучей Кусора в Укрытии Маршалла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я просто в шоке от жутедактилей! Спасибо тебе, $n! Теперь я хотя бы смогу спокойно высунуть нос из Укрытия Маршалла!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сказать по правде, я не особо беспокоился о странных существах ... До того дня, когда я увидел, что это написано на стороне большого камня.$B$BОстерегайтесь ПТЕРОДАКТЕЛЕЙ$B$BКто мог это написать? Я не знаю, но это слишком жутко, чтобы просто игнорировать!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муче Кусоре в Укрытие Маршалла, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4502,'Вулканическая активность','Я многому научилась у Марвона Клепальщика. Но он уже так давно уехал, что я подумываю начать собственные эксперименты.$B$BЯ недавно читала о Кратере Ун\'Горо и странной вулканической деятельности в его центре. Мне думается, что многое можно было бы узнать, если бы мне удалось заполучить для исследований немного пепла из тамошних элементалей.$B$BТы не против добыть немного пепла для меня, раз уж все равно туда направляешься?','Добудьте 9 образцов пепла Ун\'Горо из элементалей огня, что водятся вокруг вулкана в Кратере Ун\'Горо, и доставьте их Лив Быстрочин в Кабестан.','Вернитесь к Лив Быстрочин в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вулканическая активность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я многому научилась у Марвона Клепальщика. Но он уже так давно уехал, что я подумываю начать собственные эксперименты.$B$BЯ недавно читала о Кратере Ун\'Горо и странной вулканической деятельности в его центре. Мне думается, что многое можно было бы узнать, если бы мне удалось заполучить для исследований немного пепла из тамошних элементалей.$B$BТы не против добыть немного пепла для меня, раз уж все равно туда направляешься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 9 образцов пепла Ун\'Горо из элементалей огня, что водятся вокруг вулкана в Кратере Ун\'Горо, и доставьте их Лив Быстрочин в Кабестан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лив Быстрочин в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4503,'Крылолет Шиззла','Я работаю над ветролетом! $B$BИ вот, застрял здесь и не могу выбраться! С удовольствием тормознул бы грифона или ветрокрыла, чтобы подбросили меня до Прибамбасска, да только ужасно боюсь этих тварей! $B$BТы мне не поможешь? Мне осталось сделать только крылья, и я думаю, что чешуя терродактиля или деметродона была бы идеальным материалом. Однако маленькому гоблину не под силу справиться со столь грозными хищниками! А ты на вид весьма $gкрут:крута;! Может, попытаешься добыть мне чешуек?','Принесите 8 чешуй перепончатого деметродона 8 чешуй перепончатого терродактиля Шиззлу в Укрытие Маршалла.','Да, эта чешуя подходит просто превосходно! С помощью этих чешуек мне уж точно удастся поднять мое творение в воздух!$B$BБлагодарю тебя!','Как вы лодку назовете, так она и поплывет! Нужно хорошее имя моему летательному аппарату! Я назову его... Крылолет!','Вернитесь к Шиззлу в Укрытие Маршалла, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крылолет Шиззла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я работаю над ветролетом! $B$BИ вот, застрял здесь и не могу выбраться! С удовольствием тормознул бы грифона или ветрокрыла, чтобы подбросили меня до Прибамбасска, да только ужасно боюсь этих тварей! $B$BТы мне не поможешь? Мне осталось сделать только крылья, и я думаю, что чешуя терродактиля или деметродона была бы идеальным материалом. Однако маленькому гоблину не под силу справиться со столь грозными хищниками! А ты на вид весьма $gкрут:крута;! Может, попытаешься добыть мне чешуек?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 чешуй перепончатого деметродона 8 чешуй перепончатого терродактиля Шиззлу в Укрытие Маршалла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, эта чешуя подходит просто превосходно! С помощью этих чешуек мне уж точно удастся поднять мое творение в воздух!$B$BБлагодарю тебя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как вы лодку назовете, так она и поплывет! Нужно хорошее имя моему летательному аппарату! Я назову его... Крылолет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шиззлу в Укрытие Маршалла, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4504,'Суперлипучка','Я всегда искал способ быстро заработать. Если ты поможешь воплотить мою последнюю идею, я поделюсь с тобой доходами. Что ты на это скажешь?$b$bТак я и думал!$b$bСтупай к смоляным ямам в северной части Кратера Ун\'Горо и принеси мне смолы. Но не просто смолы, а смолы из зверей, живущих вокруг этих ям. Обычная смола недостаточно липкая.$b$bВ растениеподобных существах присутствует хлорофилл, и смола, смешанная с ним, делается сверхлипкой.','Отнесите 12 образцов сверхлипкой смолы Тран\'реку в Прибамбасск.','Тран\'рек гений, прочь сомненья – этот суперклей с руками оторвут!','Вернитесь к Тран\'реку в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суперлипучка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я всегда искал способ быстро заработать. Если ты поможешь воплотить мою последнюю идею, я поделюсь с тобой доходами. Что ты на это скажешь?$b$bТак я и думал!$b$bСтупай к смоляным ямам в северной части Кратера Ун\'Горо и принеси мне смолы. Но не просто смолы, а смолы из зверей, живущих вокруг этих ям. Обычная смола недостаточно липкая.$b$bВ растениеподобных существах присутствует хлорофилл, и смола, смешанная с ним, делается сверхлипкой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 12 образцов сверхлипкой смолы Тран\'реку в Прибамбасск.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тран\'рек гений, прочь сомненья – этот суперклей с руками оторвут!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тран\'реку в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4505,'Источник порчи','Говорят, будто я слишком жестока... Но ведь это только потому, что я жажду добыть для Орды преимущество перед Альянсом любым способом.$B$BСейчас меня прежде всего интересует лунный колодец в руинах Констелласа, к югу отсюда, который охраняют сатиры из племени Нефритового Пламени. Этот лунный колодец, некогда символ возрождения этих несносных ночных эльфов, ныне осквернен, и порождает все больше сатиров.$B$BУ меня есть одна мысль, $n, и мне хотелось бы получить пробу воды оттуда... для моей любимой кошечки.','Принесите образец оскверненной воды из лунного колодца сатиров Нефритового Пламени Винне Хеззард на Заставу Отравленной Крови.','Очень хорошо.Нам надо найти способ использовать эту порчу против наших врагов...','Это чрезвычайно важно. Ступай не медля!','Вернитесь к Винне Хеззард на Заставу Отравленной Крови, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник порчи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, будто я слишком жестока... Но ведь это только потому, что я жажду добыть для Орды преимущество перед Альянсом любым способом.$B$BСейчас меня прежде всего интересует лунный колодец в руинах Констелласа, к югу отсюда, который охраняют сатиры из племени Нефритового Пламени. Этот лунный колодец, некогда символ возрождения этих несносных ночных эльфов, ныне осквернен, и порождает все больше сатиров.$B$BУ меня есть одна мысль, $n, и мне хотелось бы получить пробу воды оттуда... для моей любимой кошечки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите образец оскверненной воды из лунного колодца сатиров Нефритового Пламени Винне Хеззард на Заставу Отравленной Крови.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо.Нам надо найти способ использовать эту порчу против наших врагов...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это чрезвычайно важно. Ступай не медля!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Винне Хеззард на Заставу Отравленной Крови, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4506,'Зараженные саблезубы','Эта оскверненная вода может помочь нам, $n. От одной ее капли мои котятки выросли вдвое и даже стали сильнее... кое в чем. Эти кошечки могут оказаться полезными...$B$BВот, $n. Возьми эту кошачью переноску и выпусти котеночка, что сидит внутри возле лунного колодца, что в руинах Констелласа. Хе-хе... результаты тебе наверняка понравятся!$B$BПотом принеси кошечку ко мне обратно, а я уж возмещу тебе затраты времени.','Отнесите котенка Винны к оскверненному лунному колодцу, выпустите его, затем снова принесите Винне.$B$BКак только вернетесь к Винне, щелкните мышкой по котенку, чтобы выпустить его.','Верните оскверненную кошку Винне Хеззард.','Вернитесь к Винне Хеззард на Заставу Отравленной Крови, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зараженные саблезубы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта оскверненная вода может помочь нам, $n. От одной ее капли мои котятки выросли вдвое и даже стали сильнее... кое в чем. Эти кошечки могут оказаться полезными...$B$BВот, $n. Возьми эту кошачью переноску и выпусти котеночка, что сидит внутри возле лунного колодца, что в руинах Констелласа. Хе-хе... результаты тебе наверняка понравятся!$B$BПотом принеси кошечку ко мне обратно, а я уж возмещу тебе затраты времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите котенка Винны к оскверненному лунному колодцу, выпустите его, затем снова принесите Винне.$B$BКак только вернетесь к Винне, щелкните мышкой по котенку, чтобы выпустить его.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Верните оскверненную кошку Винне Хеззард.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Винне Хеззард на Заставу Отравленной Крови, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (4507,'Пешка берет королеву','Вот и приманка. Внутри улья должен быть какой-то кристалл. Мы думаем, что силитиды пользуются им для вещания по всему улью. Где он? Я бы поискал в инкубаторах.$b$bЕсли положить приманку на этот кристалл, непременно явится королева. Но предупреждаю, без охраны она не ходит. Убей ее и вынь из нее мозг. Как ни гадко это звучит, его необходимо изучить. Удачи, $n!','Призовите и сразите королеву улья Гориши.$b$bПринесите мозг королевы Гориши алхимику Пестычинсу в Прибамбасск.','Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока наше отношение к тебе не изменится, ты сможешь купить эти мантии у любого интенданта Серебряного Рассвета.$B$BЗа Рассвет, $Gбрат:сестра; $Gмой:моя;!','Вернитесь к алхимику Пестычинсу в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пешка берет королеву',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот и приманка. Внутри улья должен быть какой-то кристалл. Мы думаем, что силитиды пользуются им для вещания по всему улью. Где он? Я бы поискал в инкубаторах.$b$bЕсли положить приманку на этот кристалл, непременно явится королева. Но предупреждаю, без охраны она не ходит. Убей ее и вынь из нее мозг. Как ни гадко это звучит, его необходимо изучить. Удачи, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите и сразите королеву улья Гориши.$b$bПринесите мозг королевы Гориши алхимику Пестычинсу в Прибамбасск.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока наше отношение к тебе не изменится, ты сможешь купить эти мантии у любого интенданта Серебряного Рассвета.$B$BЗа Рассвет, $Gбрат:сестра; $Gмой:моя;!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алхимику Пестычинсу в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4508,'Затишье перед бурей','Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что-либо предпринять. Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты.$b$bОтнеси мой последний отчет Грацине Силе Духа, в Дарнас; она ведь по-прежнему в Храме Луны? У нее много друзей среди важных шишек Альянса; если удастся привлечь их внимание, быть может мы и выживем.','Отнесите отчет Пестычинса о ситуации в Ун\'Горо Грацине Силе Духа в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затишье перед бурей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что-либо предпринять. Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты.$b$bОтнеси мой последний отчет Грацине Силе Духа, в Дарнас; она ведь по-прежнему в Храме Луны? У нее много друзей среди важных шишек Альянса; если удастся привлечь их внимание, быть может мы и выживем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите отчет Пестычинса о ситуации в Ун\'Горо Грацине Силе Духа в Дарнас.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4509,'Затишье перед бурей','Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что-либо предпринять. Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты.$b$bОтнеси мой последний отчет Зилзибину Барабанному Бою, в Оргриммар; он ведь по-прежнему там? У него много друзей среди важных шишек Орды; если удастся привлечь их внимание, быть может мы и выживем.','Отнесите отчет Пестычинса о ситуации в Ун\'Горо Зилзибину Барабанному Бою в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затишье перед бурей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все исследования, да и знания, полученные нами сегодня, как можно скорее должны дойти до тех, кто в силах что-либо предпринять. Прибамбасску не выстоять одному, невзирая на наши многочисленные таланты.$b$bОтнеси мой последний отчет Зилзибину Барабанному Бою, в Оргриммар; он ведь по-прежнему там? У него много друзей среди важных шишек Орды; если удастся привлечь их внимание, быть может мы и выживем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите отчет Пестычинса о ситуации в Ун\'Горо Зилзибину Барабанному Бою в Оргриммар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4509,'While I genuinely appreciate this, I am not sure what good it will do us. The Horde ignores threats from any source other than the Alliance. While Thrall himself might take action were the facts presented to him, he is beset on all sides by conflicting advice. These fools would have us chase our own imaginary tails were they to think it might catch the Alliance unawares!$B$BYou have seen the threat yourself, $n. We must remain committed to defeating the silithid!','They are fools, $n! They cannot even think to look around them for a greater threat; their irrational hatred of the Alliance will be our undoing. I do not know how much more proof I can give them of the silithid threat short of dropping them in one of the hives so they can see for themselves!$B$BI\'m sorry, you bring news for my attention?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','While I genuinely appreciate this, I am not sure what good it will do us. The Horde ignores threats from any source other than the Alliance. While Thrall himself might take action were the facts presented to him, he is beset on all sides by conflicting advice. These fools would have us chase our own imaginary tails were they to think it might catch the Alliance unawares!$B$BYou have seen the threat yourself, $n. We must remain committed to defeating the silithid!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','They are fools, $n! They cannot even think to look around them for a greater threat; their irrational hatred of the Alliance will be our undoing. I do not know how much more proof I can give them of the silithid threat short of dropping them in one of the hives so they can see for themselves!$B$BI\'m sorry, you bring news for my attention?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4510,'Затишье перед бурей','$n, твоя помощь просто неоценима. Придет время, и, думается, я снова буду вынуждена обратиться к тебе за содействием в борьбе против силитидов. Мы должны осмыслить все, что узнали в Ун\'Горо. Опасаюсь, что мои предположения по поводу того, что силитиды родом из Ун\'Горо, неверны... и где-то их гораздо больше.$B$BОтнеси эту бумагу Идриане в банк. Она выдаст тебе кое-что из моего хранилища в знак моей признательности. Благодарю тебя за помощь, $Gотважный:отважная:c; |3-6($c).','Отнесите банковскую расписку Идриане в банк Дарнаса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затишье перед бурей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, твоя помощь просто неоценима. Придет время, и, думается, я снова буду вынуждена обратиться к тебе за содействием в борьбе против силитидов. Мы должны осмыслить все, что узнали в Ун\'Горо. Опасаюсь, что мои предположения по поводу того, что силитиды родом из Ун\'Горо, неверны... и где-то их гораздо больше.$B$BОтнеси эту бумагу Идриане в банк. Она выдаст тебе кое-что из моего хранилища в знак моей признательности. Благодарю тебя за помощь, $Gотважный:отважная:c; |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите банковскую расписку Идриане в банк Дарнаса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4511,'Затишье перед бурей','Спасибо тебе, $n. Без тебя у нас бы ничего не вышло. Несомненно, вскоре придет время, когда я снова попрошу твоей помощи в борьбе с силитидами. Придется пересмотреть то, что известно нам по Ун\'Горо. Боюсь, мое предположение, что силитиды происходят из Ун\'Горо, оказалось ложным. Где-то есть другое гнездо, куда более крупное.$b$bОтнеси эту записку Карусу в банк. Он выдаст тебе кое-что, что может считаться знаком моей благодарности. Спасибо за помощь, $gмогучий:могучая:c; |3-6($c)!','Отнесите банковскую расписку Карусу в банк Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затишье перед бурей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо тебе, $n. Без тебя у нас бы ничего не вышло. Несомненно, вскоре придет время, когда я снова попрошу твоей помощи в борьбе с силитидами. Придется пересмотреть то, что известно нам по Ун\'Горо. Боюсь, мое предположение, что силитиды происходят из Ун\'Горо, оказалось ложным. Где-то есть другое гнездо, куда более крупное.$b$bОтнеси эту записку Карусу в банк. Он выдаст тебе кое-что, что может считаться знаком моей благодарности. Спасибо за помощь, $gмогучий:могучая:c; |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите банковскую расписку Карусу в банк Оргриммара.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4512,'Долгий путь слизнюка','Но больше всего я изучал слизнюков. Я понимаю, что звучит нелепо, но их же почти не осталось!$B$BНе так давно я помогал одной даме из Менетила искать ее сумку – так слизнюки эту сумку сожрали. Я видел, что члены Королевского фармацевтического общества Подгорода собирают образцы этих тварей. Я хочу понять, почему! Откуда они их берут?$B$BЯ слышал, что они водятся в Оскверненном лесу. Мне нужны экземпляры этих слизнюков для продолжения исследований. Я дам вам банки, а вы возьмете образцы мертвых существ.','Принесите 6 флаконов с образцами нечистых слизнюков и 6 флаконов с образцами проклятых слизнюков Ларису Обалдую в Стальгорн.','Некоторые мои эксперименты дают просто невероятные результаты. Думаю, еще немного, и я смогу понять природу этих тварей и выяснить, какую роль они сыграли в происхождении жизни в Азероте... если, конечно, они вообще имеют отоношение к Азероту.$B$BОдна из величайших моих теорий – не слишком популярных – гласит, что слизнюки и слизь не связаны собственно с происхождением нашей планеты. Они, скорее, ее выделения.$B$BНо я не могу ни доказать ее, ни опровергнуть, пока не получу побольше образцов.','Вернитесь к Ларису Обалдую в библиотеку Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долгий путь слизнюка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Но больше всего я изучал слизнюков. Я понимаю, что звучит нелепо, но их же почти не осталось!$B$BНе так давно я помогал одной даме из Менетила искать ее сумку – так слизнюки эту сумку сожрали. Я видел, что члены Королевского фармацевтического общества Подгорода собирают образцы этих тварей. Я хочу понять, почему! Откуда они их берут?$B$BЯ слышал, что они водятся в Оскверненном лесу. Мне нужны экземпляры этих слизнюков для продолжения исследований. Я дам вам банки, а вы возьмете образцы мертвых существ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 флаконов с образцами нечистых слизнюков и 6 флаконов с образцами проклятых слизнюков Ларису Обалдую в Стальгорн.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Некоторые мои эксперименты дают просто невероятные результаты. Думаю, еще немного, и я смогу понять природу этих тварей и выяснить, какую роль они сыграли в происхождении жизни в Азероте... если, конечно, они вообще имеют отоношение к Азероту.$B$BОдна из величайших моих теорий – не слишком популярных – гласит, что слизнюки и слизь не связаны собственно с происхождением нашей планеты. Они, скорее, ее выделения.$B$BНо я не могу ни доказать ее, ни опровергнуть, пока не получу побольше образцов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ларису Обалдую в библиотеку Стальгорна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4513,'Долгий путь слизнюка','Принесите 10 флаконов c образцами чистых слизнюков Ларису Обалдую в Стальгорн.$B$BЕсли будет трудно их найти, возможно, стоит попытаться добиться от Лариса подсказки.','Как много нужно обдумать. Но что это значит? И как это влияет на жизнь народов Азерота?','Вернитесь к Ларису Обалдую в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долгий путь слизнюка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 флаконов c образцами чистых слизнюков Ларису Обалдую в Стальгорн.$B$BЕсли будет трудно их найти, возможно, стоит попытаться добиться от Лариса подсказки.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как много нужно обдумать. Но что это значит? И как это влияет на жизнь народов Азерота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ларису Обалдую в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4521,'Одичавшие стражи','Зимние Ключи расположены как раз за Древобрюхами на северо-востоке Оскверненного леса. Приходилось там бывать?$B$BЯ слышал, что эти края заселены существами, которых называют дикими совухами. Эти животные, как известно, охраняли тайны ночных эльфов.$B$BМы должны выяснить, какие тайны хранятся в Зимних Ключах.$B$BЯ слышал что лохматые совухи водятся к югу от этой дороги, а те, которых называют бешеными совухами, населяют центр Зимних Ключей. Убей их и расчисть дорогу.','Убейте для Трулла Баловня Судьбы 15 бешеных совухов и 15 лохматых совухов.','Отличные новости, $N. Теперь, когда эти твари не стоят у нас на пути, мы можем проникнуть в Зимние Ключи. Ты $Gготов:готова;?','Сообщите мне после того, как вы выполните задание, которое я вам дал.','Вернитесь к Труллу Баловню Судьбы на Заставу Отравленной Крови, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одичавшие стражи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зимние Ключи расположены как раз за Древобрюхами на северо-востоке Оскверненного леса. Приходилось там бывать?$B$BЯ слышал, что эти края заселены существами, которых называют дикими совухами. Эти животные, как известно, охраняли тайны ночных эльфов.$B$BМы должны выяснить, какие тайны хранятся в Зимних Ключах.$B$BЯ слышал что лохматые совухи водятся к югу от этой дороги, а те, которых называют бешеными совухами, населяют центр Зимних Ключей. Убей их и расчисть дорогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте для Трулла Баловня Судьбы 15 бешеных совухов и 15 лохматых совухов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные новости, $N. Теперь, когда эти твари не стоят у нас на пути, мы можем проникнуть в Зимние Ключи. Ты $Gготов:готова;?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сообщите мне после того, как вы выполните задание, которое я вам дал.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Труллу Баловню Судьбы на Заставу Отравленной Крови, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (4541,'<NYI> <TXT>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4542,'Письмо на Заставу Вольного Ветра','Кентавры стали все чаще нападать на эти земли, и об этом нужно срочно доложить на Заставу Вольного Ветра! Отправляйтесь туда, найдите дозорного утесов Долгорога и отдайте ему это письмо. Форт находится к юго-востоку отсюда.$B$BНо будьте осторожны: неподалеку есть поселение клана Зловещий Тотем, и его члены в последнее время ведут себя беспокойно','Отнесите срочное послание дозорному утесов Долгорогу на Заставу Вольного Ветра.','Опять плохие новости! Эти кентавры зашли слишком далеко! Они напали на один из моих караванов и убили всех погонщиков! Это неслыханно, они должны за это заплатить!','Что вы хотели, |3-6($C)? Срочное послание? Для меня?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Письмо на Заставу Вольного Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кентавры стали все чаще нападать на эти земли, и об этом нужно срочно доложить на Заставу Вольного Ветра! Отправляйтесь туда, найдите дозорного утесов Долгорога и отдайте ему это письмо. Форт находится к юго-востоку отсюда.$B$BНо будьте осторожны: неподалеку есть поселение клана Зловещий Тотем, и его члены в последнее время ведут себя беспокойно',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите срочное послание дозорному утесов Долгорогу на Заставу Вольного Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Опять плохие новости! Эти кентавры зашли слишком далеко! Они напали на один из моих караванов и убили всех погонщиков! Это неслыханно, они должны за это заплатить!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что вы хотели, |3-6($C)? Срочное послание? Для меня?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4561,'Образцы на пробу из Кратера Ун\'Горо','Вы берете чашку Петри с пробой слизи. Выяснить, достаточно ли образец чистый, можно только одним способом – открыть колбы и самостоятельно исследовать их содержимое. В конце концов вы должны найти пробу, которая устроит химика Барабоса.?','Вы наполняете слизью, добытой в Кратере Ун\'Горо, различные колбы и мензурки, стоящие на столе. Все начинает бурлить и брызгаться, а слизь меняет цвет. Потом процесс замедляется, жидкость перестает кипеть, и вы видите маленькую чашечку Петри с пробой измененной слизи и какие-то ошметки.','Вернитесь к испытательному оборудованию.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Образцы на пробу из Кратера Ун\'Горо',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы берете чашку Петри с пробой слизи. Выяснить, достаточно ли образец чистый, можно только одним способом – открыть колбы и самостоятельно исследовать их содержимое. В конце концов вы должны найти пробу, которая устроит химика Барабоса.?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы наполняете слизью, добытой в Кратере Ун\'Горо, различные колбы и мензурки, стоящие на столе. Все начинает бурлить и брызгаться, а слизь меняет цвет. Потом процесс замедляется, жидкость перестает кипеть, и вы видите маленькую чашечку Петри с пробой измененной слизи и какие-то ошметки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к испытательному оборудованию.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (4581,'Кайнет Штиль','Друид Кайнет Штиль прислал мне весточку. Он хотел бы получить отчет обо всем, что творится у нас на побережье и в лесах вокруг Астранаара. Он опасается, что по Ясеневому лесу расползается порча... Может, он и прав.$B$BВот, отнеси ему мой отчет. Ты найдешь его в святилище Лесной Песни, в лесах Ночной Песни к востоку отсюда.','Отнесите записку Шиндрелл Кайнету Штилю в Лесную Песнь.','Ты что-то мне принес?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кайнет Штиль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друид Кайнет Штиль прислал мне весточку. Он хотел бы получить отчет обо всем, что творится у нас на побережье и в лесах вокруг Астранаара. Он опасается, что по Ясеневому лесу расползается порча... Может, он и прав.$B$BВот, отнеси ему мой отчет. Ты найдешь его в святилище Лесной Песни, в лесах Ночной Песни к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите записку Шиндрелл Кайнету Штилю в Лесную Песнь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты что-то мне принес?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4601,'Чистер 5200!','Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений. Небольшая табличка, прикрепленная к устройству, гласит: "Чистер 5200".$B$BВаши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер 5200 легко справится с этой проблемой! Опустите в щель приемника три серебряные монеты и подождите пару минут, пока Чистер 5200 наводит лоск на ваши украшения.','Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200.','Вы кладете покрытый грязью предмет и три серебряные монеты в Чистер 5200, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует.','Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.','Вернитесь к Чистеру 5200 в Предгорья Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чистер 5200!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений. Небольшая табличка, прикрепленная к устройству, гласит: "Чистер 5200".$B$BВаши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер 5200 легко справится с этой проблемой! Опустите в щель приемника три серебряные монеты и подождите пару минут, пока Чистер 5200 наводит лоск на ваши украшения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Опустите покрытый грязью предмет и три серебряные монеты в Чистер 5200.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы кладете покрытый грязью предмет и три серебряные монеты в Чистер 5200, и машина начинает работать, с гудением отскребая въевшуюся грязь. Металлический корпус аппарата скрипит и вибрирует.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, что в механизм следует положить предмет, нуждающийся в очистке, и три серебряных монеты.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Чистеру 5200 в Предгорья Хилсбрада.',`completedtext_loc8`);
