INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4621,'Стоять, Адмирал!','Слышь, ты, морской волк... Нам, пиратам Кровавого Паруса, жить да поживать бы, когда бы не Пиратская Бухта. Ух, мы порезвились бы вдоволь! А если б ты $gпырнул:пырнула; ножом командира флота Морского Рога,чихали бы мы тогда на его посудины! Если б ты $gпырнул:пырнула; ножом барона Ревилгаза, мы б и их закона не боялись.$B$BВ общем, коль хочешь стать у нас почетным адмиралом – да, АДМИРАЛОМ, я не шучу, прирежь обоих, и все дела. Иди, $Gпарень:девица;, возвращайся, когда дело будет сделано.','Стой... Адмирал $N! Ты пират пиратов, $Gпарень:девица;!$B$BМеня аж до печенки пробирает от гордости, когда я вручаю тебе эту шляпу. Ты ничего подобного нигде не найдешь, и все, кто глянут на тебя сразу поймут, вот идет адмирал флота Кровавого Паруса!','Ты опять тут, сухопутная крыса? Ты $Gвыполнил:выполнила; мой приказ? Только попробуй нас предать, живо полетишь за борт.$B$BГрррррр...','Вернитесь к командиру флота Фираллону в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стоять, Адмирал!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слышь, ты, морской волк... Нам, пиратам Кровавого Паруса, жить да поживать бы, когда бы не Пиратская Бухта. Ух, мы порезвились бы вдоволь! А если б ты $gпырнул:пырнула; ножом командира флота Морского Рога,чихали бы мы тогда на его посудины! Если б ты $gпырнул:пырнула; ножом барона Ревилгаза, мы б и их закона не боялись.$B$BВ общем, коль хочешь стать у нас почетным адмиралом – да, АДМИРАЛОМ, я не шучу, прирежь обоих, и все дела. Иди, $Gпарень:девица;, возвращайся, когда дело будет сделано.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стой... Адмирал $N! Ты пират пиратов, $Gпарень:девица;!$B$BМеня аж до печенки пробирает от гордости, когда я вручаю тебе эту шляпу. Ты ничего подобного нигде не найдешь, и все, кто глянут на тебя сразу поймут, вот идет адмирал флота Кровавого Паруса!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты опять тут, сухопутная крыса? Ты $Gвыполнил:выполнила; мой приказ? Только попробуй нас предать, живо полетишь за борт.$B$BГрррррр...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру флота Фираллону в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4641,'Твое место в мире','Ну вот, $n, ты и $gстал взрослым... достаточно взрослым:стала взрослой... достаточно взрослой;, чтобы сражаться во имя Орды и во славу вождя.$b$b*Калтунк меряет вас взглядом.*$b$bДа, ты вполне годишься!$b$bРазумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного.$b$b*Калтунк хохочет.*$b$bОтправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, $gюный:юная:c; |3-6($c). Горнека ты найдешь в Логове, на западе.','Поговорите с Горнеком. Вы помните, как Калтунк отметил на карте его местонахождение и упомянул, что Горнек живет в Логове, здании, расположенном на западе.','Очередной рекрут Калтунка?$b$bВидно, плохи наши дела, если у нас нет никого получше. Ну, ничего. К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится $Gбравый воитель:бравая воительница; Орды!','Панцирь скорпида не такой толстый, чтобы сдерживать силу решительного воина. Бейте сильно и без сомнений, и скорпиды должны оказаться легкой добычей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Твое место в мире',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, $n, ты и $gстал взрослым... достаточно взрослым:стала взрослой... достаточно взрослой;, чтобы сражаться во имя Орды и во славу вождя.$b$b*Калтунк меряет вас взглядом.*$b$bДа, ты вполне годишься!$b$bРазумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного.$b$b*Калтунк хохочет.*$b$bОтправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, $gюный:юная:c; |3-6($c). Горнека ты найдешь в Логове, на западе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Горнеком. Вы помните, как Калтунк отметил на карте его местонахождение и упомянул, что Горнек живет в Логове, здании, расположенном на западе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очередной рекрут Калтунка?$b$bВидно, плохи наши дела, если у нас нет никого получше. Ну, ничего. К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится $Gбравый воитель:бравая воительница; Орды!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Панцирь скорпида не такой толстый, чтобы сдерживать силу решительного воина. Бейте сильно и без сомнений, и скорпиды должны оказаться легкой добычей.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4642,'Слияние','В этом сосуде находится слизнюк, созданный из пробы, которую ты $Gпринес:принесла; из Оскверненного леса. Отнеси его к Кратеру Ун\'Горо и отыщи чистого слизнюка. Подберись поближе, выпусти наш экземпляр и посмотри, что они сделают друг с другом.$B$BПо завершении эксперимента принеси мне пробу того, что останется. Я буду ждать тебя здесь, в Районе Фармацевтов.','Принесите образец перемешанной слизи химику Барабосу в Подгород.','О, великолепно, $N. Великолепно.$B$BНу и дела. Кто бы подумал, что они будут взаимодействовать таким образом... Придется посвятить побольше времени изучению феноменов окружающей среды, которые вызывают в этих тварях подобные изменения.$B$BА теперь я вернусь к своим исследованиям. Быть может, вскоре свидимся. Пока же – всего наилучшего.','Как идет эксперимент, $N? Я вернусь к изучению принесенных тобой проб, поскольку начинаю понимать, почему ими так заинтересовалась леди Сильвана. Если они в самом деле часть Древних богов, то кто знает, какую пользу они могли бы принести нам...','Вернитесь к химику Барабосу в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слияние',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом сосуде находится слизнюк, созданный из пробы, которую ты $Gпринес:принесла; из Оскверненного леса. Отнеси его к Кратеру Ун\'Горо и отыщи чистого слизнюка. Подберись поближе, выпусти наш экземпляр и посмотри, что они сделают друг с другом.$B$BПо завершении эксперимента принеси мне пробу того, что останется. Я буду ждать тебя здесь, в Районе Фармацевтов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите образец перемешанной слизи химику Барабосу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, великолепно, $N. Великолепно.$B$BНу и дела. Кто бы подумал, что они будут взаимодействовать таким образом... Придется посвятить побольше времени изучению феноменов окружающей среды, которые вызывают в этих тварях подобные изменения.$B$BА теперь я вернусь к своим исследованиям. Быть может, вскоре свидимся. Пока же – всего наилучшего.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идет эксперимент, $N? Я вернусь к изучению принесенных тобой проб, поскольку начинаю понимать, почему ими так заинтересовалась леди Сильвана. Если они в самом деле часть Древних богов, то кто знает, какую пользу они могли бы принести нам...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к химику Барабосу в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4661,'Проба – образцы из Оскверненного леса','Вы берете чашку Петри с пробой слизи. Выяснить, достаточно ли образец чистый, можно только одним способом – открыть колбы и самостоятельно исследовать их содержимое. В конце концов вы должны найти пробу, которая устроит химика Барабоса.','Вы наполняете слизью, добытой в Оскверненном лесу, различные колбы и мензурки, стоящие на столе. Все начинает бурлить и брызгаться, а слизь меняет цвет. Потом процесс замедляется, жидкость перестает кипеть, и вы видите маленькую чашечку Петри с пробой измененной слизи и какие-то ошметки.','Вернитесь к испытательному оборудованию.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проба – образцы из Оскверненного леса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы берете чашку Петри с пробой слизи. Выяснить, достаточно ли образец чистый, можно только одним способом – открыть колбы и самостоятельно исследовать их содержимое. В конце концов вы должны найти пробу, которая устроит химика Барабоса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы наполняете слизью, добытой в Оскверненном лесу, различные колбы и мензурки, стоящие на столе. Все начинает бурлить и брызгаться, а слизь меняет цвет. Потом процесс замедляется, жидкость перестает кипеть, и вы видите маленькую чашечку Петри с пробой измененной слизи и какие-то ошметки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к испытательному оборудованию.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (4681,'Останки на берегу','Та тварь на берегу – не единственная на Темных берегах. Вдоль побережья их еще много, да и в воде тоже. Я хотела бы, чтобы вы исследовали другие известные нам останки. Мне сообщили, что они находятся в воде, непосредственно к западу от Аубердина, возле затонувшего судна. Возвращайтесь ко мне с тем, что вам удастся найти полезного для нас.$b$bКстати, в ваших странствиях вы можете найти и другие подобные останки. Если вы обнаружите что-то, обязательно принесите нам для дальнейших исследований!','Извлеките останки морской черепахи из скелета морской черепахи, лежащего в воде к западу от Аубердина, а затем поговорите с Гвеннид Блай\'Леггонд в Аубердине.','Когда вы исследуете останки твари, лежащие в воде к западу отсюда, я, наверное, смогу представить надлежащий отчет в Храм Луны в Дарнассе. Возможно, тогда мы приблизимся к пониманию того, почему эти несчастные создания выбирают такую смерть, выбрасываясь на отмели на Темном Берегу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Останки на берегу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Та тварь на берегу – не единственная на Темных берегах. Вдоль побережья их еще много, да и в воде тоже. Я хотела бы, чтобы вы исследовали другие известные нам останки. Мне сообщили, что они находятся в воде, непосредственно к западу от Аубердина, возле затонувшего судна. Возвращайтесь ко мне с тем, что вам удастся найти полезного для нас.$b$bКстати, в ваших странствиях вы можете найти и другие подобные останки. Если вы обнаружите что-то, обязательно принесите нам для дальнейших исследований!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Извлеките останки морской черепахи из скелета морской черепахи, лежащего в воде к западу от Аубердина, а затем поговорите с Гвеннид Блай\'Леггонд в Аубердине.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда вы исследуете останки твари, лежащие в воде к западу отсюда, я, наверное, смогу представить надлежащий отчет в Храм Луны в Дарнассе. Возможно, тогда мы приблизимся к пониманию того, почему эти несчастные создания выбирают такую смерть, выбрасываясь на отмели на Темном Берегу.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4701,'Устранение опасности','Тебе несомненно приходилось видеть воргов, которыми командуют орки Черной горы.$b$bВот что интересно – сколько мы их ни убиваем, их не делается меньше. Разведчики доносят, что воргов растят и обучают на Пике Черной горы, в столице орков этого клана. Отправляйся туда и поищи источник опасности. Отыщи... и уничтожь.$b$bУдачи, $n. Да хранит тебя Кенарий...','Отправьтесь на Пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами.','Не думай о том, страдала ли она, $N. Этого зверя осквернило касание темной магии. Ты оказал Альянсу огромную услугу и получишь за нее награду.','Вы обнаружили и разобрались с источником слова «угроза»?','Вернитесь к Хелендису Речному Мысу в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Устранение опасности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе несомненно приходилось видеть воргов, которыми командуют орки Черной горы.$b$bВот что интересно – сколько мы их ни убиваем, их не делается меньше. Разведчики доносят, что воргов растят и обучают на Пике Черной горы, в столице орков этого клана. Отправляйся туда и поищи источник опасности. Отыщи... и уничтожь.$b$bУдачи, $n. Да хранит тебя Кенарий...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь на Пик Черной горы и уничтожьте источник опасности. Хелендис кричит вам вслед одно имя: Халикон. Именно его упоминали орки в связи с воргами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не думай о том, страдала ли она, $N. Этого зверя осквернило касание темной магии. Ты оказал Альянсу огромную услугу и получишь за нее награду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы обнаружили и разобрались с источником слова «угроза»?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хелендису Речному Мысу в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4721,'Одичавшие стражи','Гонцы вернулись из Зимних Ключей с сообщением о том, что в его южной части есть группа небольших пещер. У них сложилось впечатление, что этот район обжили дикие совухи. Если они охраняют что-то важное, то, я думаю, именно там мы это и найдем.$b$bС этими дикими совухами вам будет справиться намного сложнее, чем в предыдущий раз, $n. Эти создания, похоже, ввергает в безумие та самая вещь, которую они столь яростно защищают.','Убейте для Трулла Баловня Судьбы из Оскверненного леса 10 яростных совухов в Зимних Ключах.','Вот что я уважаю – так это хорошую работу, $N. Теперь мы можем дальше действовать в Зимних Ключах.','Вы знаете свои заказы, $N.','Вернитесь к Труллу Баловню Судьбы на Заставу Отравленной Крови, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одичавшие стражи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гонцы вернулись из Зимних Ключей с сообщением о том, что в его южной части есть группа небольших пещер. У них сложилось впечатление, что этот район обжили дикие совухи. Если они охраняют что-то важное, то, я думаю, именно там мы это и найдем.$b$bС этими дикими совухами вам будет справиться намного сложнее, чем в предыдущий раз, $n. Эти создания, похоже, ввергает в безумие та самая вещь, которую они столь яростно защищают.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте для Трулла Баловня Судьбы из Оскверненного леса 10 яростных совухов в Зимних Ключах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот что я уважаю – так это хорошую работу, $N. Теперь мы можем дальше действовать в Зимних Ключах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы знаете свои заказы, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Труллу Баловню Судьбы на Заставу Отравленной Крови, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4722,'Выброшенная на берег морская черепаха','Вы наткнулись на останки морской черепахи, некоторое время назад выбросившейся на Темные берега. Плоть ее уже объели мурлоки, обосновавшиеся неподалеку от останков. Вы можете набрать достаточное количество образцов, которые пригодятся Гвеннид Блай\'Леггонд.','Отнесите останки морской черепахи Гвеннид Блай\'Леггонд в Аубердин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выброшенная на берег морская черепаха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы наткнулись на останки морской черепахи, некоторое время назад выбросившейся на Темные берега. Плоть ее уже объели мурлоки, обосновавшиеся неподалеку от останков. Вы можете набрать достаточное количество образцов, которые пригодятся Гвеннид Блай\'Леггонд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите останки морской черепахи Гвеннид Блай\'Леггонд в Аубердин.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4723,'Выброшенная на берег морская тварь','Останки гигантского крепкозуба – намного больших размеров, чем можно было бы ожидать на Темных берегах, – лежат у побережья Туманного предела. Как это существо очутилось здесь, неизвестно; мурлоки, объедающие тушу, кажутся слишком слабыми и неспособными даже толпой притащить ее сюда.$B$BВ то время как некоторая часть костей уже начисто обглодана, останков еще достаточно, чтобы набрать образцов для Гвеннид Блай\'Леггонд.','Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выброшенная на берег морская тварь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Останки гигантского крепкозуба – намного больших размеров, чем можно было бы ожидать на Темных берегах, – лежат у побережья Туманного предела. Как это существо очутилось здесь, неизвестно; мурлоки, объедающие тушу, кажутся слишком слабыми и неспособными даже толпой притащить ее сюда.$B$BВ то время как некоторая часть костей уже начисто обглодана, останков еще достаточно, чтобы набрать образцов для Гвеннид Блай\'Леггонд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4724,'Праматерь стаи','Ходят слухи, что ворги, управляемые орками Черной горы, – создания сверхъестественных сил. Говорят также, что это не настоящие ворги, а потомство пса-демона, подаренное оркам властителем преисподней. $B$BПравда куда более проста, но не менее ужасна. Ворги Черной горы – потомство Халикон, огромной праматери воргов. Каков из себя ее самец? Вряд ли кто из видевших его выжил, чтобы поведать об этом. $B$BНужно нанести удар по самому сердцу логова воргов. Уничтожь Халикон. И прошу тебя, не забывай об осторожности!','Убейте Халикон, праматерь стаи воргов Кровавого Топора.','Бешеные щенки? Гизрул Поработитель? И ты стоишь передо мной $Gживехонький:живехонькая; и рассказываешь об этом?! Глазам не верю! Ты $Gзаслужил:заслужила; свою награду!','Убитая хозяйка стаи, мы можем начать прореживать словесные стражи Шпиля и, в конце концов, продвинуться в город.','Вернитесь к Галамаву Стрелку в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Праматерь стаи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, что ворги, управляемые орками Черной горы, – создания сверхъестественных сил. Говорят также, что это не настоящие ворги, а потомство пса-демона, подаренное оркам властителем преисподней. $B$BПравда куда более проста, но не менее ужасна. Ворги Черной горы – потомство Халикон, огромной праматери воргов. Каков из себя ее самец? Вряд ли кто из видевших его выжил, чтобы поведать об этом. $B$BНужно нанести удар по самому сердцу логова воргов. Уничтожь Халикон. И прошу тебя, не забывай об осторожности!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Халикон, праматерь стаи воргов Кровавого Топора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бешеные щенки? Гизрул Поработитель? И ты стоишь передо мной $Gживехонький:живехонькая; и рассказываешь об этом?! Глазам не верю! Ты $Gзаслужил:заслужила; свою награду!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Убитая хозяйка стаи, мы можем начать прореживать словесные стражи Шпиля и, в конце концов, продвинуться в город.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Галамаву Стрелку в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4725,'Выброшенная на берег морская черепаха','Еще одни останки морской черепахи лежат прямо на берегу. К панцирю прикреплена упряжь. Скорее всего, черепаху выгнали на берег неизвестные нам твари; она не выбросилась на берег сама, хотя другие останки и наводят на эту мысль. Теперь останками черепахи завладели мурлоки племени Серой Мглы, питающиеся мертвечиной.$B$BОбследуя упряжь, вы обнаруживаете ящик со странными пометками. Может быть, Гвеннид Блай\'Леггонд из Аубердина сможет что-то понять?','Отнесите ящик со странными пометками Гвеннид Блай\'Леггонд в Аубердин.','Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Темного Берега.$B$BЯ отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и еще раз спасибо за вашу помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выброшенная на берег морская черепаха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще одни останки морской черепахи лежат прямо на берегу. К панцирю прикреплена упряжь. Скорее всего, черепаху выгнали на берег неизвестные нам твари; она не выбросилась на берег сама, хотя другие останки и наводят на эту мысль. Теперь останками черепахи завладели мурлоки племени Серой Мглы, питающиеся мертвечиной.$B$BОбследуя упряжь, вы обнаруживаете ящик со странными пометками. Может быть, Гвеннид Блай\'Леггонд из Аубердина сможет что-то понять?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик со странными пометками Гвеннид Блай\'Леггонд в Аубердин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Темного Берега.$B$BЯ отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и еще раз спасибо за вашу помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4726,'Сущность детеныша дракона','Я уже несколько недель изучаю драконов в Пылающих степях, и кажется, наконец-то наметился определенный прорыв! Я создала устройство – Драко-инкарцинатор 900. Оно может поймать сущность детеныша дракона!$b$bПо крайней мере, я на это рассчитываю.$b$bВозьми это устройство и испытай его на детеныше дракона в Пылающих степях. Пока он будет под воздействием инкарцинатора, одолей его и выпусти из него сущность.$b$bЕсли это сработает, будет замечательно! И принеси мне образцы на изучение!','Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.','Вернитесь к Тинки Кипеллер в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сущность детеныша дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже несколько недель изучаю драконов в Пылающих степях, и кажется, наконец-то наметился определенный прорыв! Я создала устройство – Драко-инкарцинатор 900. Оно может поймать сущность детеныша дракона!$b$bПо крайней мере, я на это рассчитываю.$b$bВозьми это устройство и испытай его на детеныше дракона в Пылающих степях. Пока он будет под воздействием инкарцинатора, одолей его и выпусти из него сущность.$b$bЕсли это сработает, будет замечательно! И принеси мне образцы на изучение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 сущностей детенышей драконов и Драко-инкарцинатор 900 Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тинки Кипеллер в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4727,'Выброшенная на берег морская черепаха','Скелет морской черепахи лежит на песчаной отмели на севере Темных берегов. Мурлоки племени Серой Мглы либо не нашли ее тушу, либо по каким-то причинам не рискнули приблизиться к ней. В любом случае, от черепахи осталось достаточно, чтобы взять образцы для Гвеннид Блай\'Леггонд, проводящей расследование по поручению Храма Луны.','Отнесите останки морской черепахи Гвеннид Блай\'Леггонд в Аубердин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выброшенная на берег морская черепаха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скелет морской черепахи лежит на песчаной отмели на севере Темных берегов. Мурлоки племени Серой Мглы либо не нашли ее тушу, либо по каким-то причинам не рискнули приблизиться к ней. В любом случае, от черепахи осталось достаточно, чтобы взять образцы для Гвеннид Блай\'Леггонд, проводящей расследование по поручению Храма Луны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите останки морской черепахи Гвеннид Блай\'Леггонд в Аубердин.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4728,'Выброшенная на берег морская тварь','Растерзанные останки того, что на вид кажется похожим на гигантское морское млекопитающее, лежат на берегу. Около них валяется тачка и различные инструменты, как будто кто-то раньше уже пытался изучать останки. Хотя мурлоки основательно растащили скелет, останков достаточно, чтобы найти подходящий образец костей для Гвеннид Блай\'Леггонд в Аубердине.','Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.','О, я уверена, вы обнаружили останки твари, которые уже изучались Лигой Исследователей. Они работают здесь, на Темном Берегу, и упоминали, что изучали одну из выбросившихся на берег тварей, пока их не прогнали мурлоки. Похоже, вам удалось добиться успеха там, где и мы, и они потерпели фиаско. Пожалуйста, примите эту скромную плату от имени Храма Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выброшенная на берег морская тварь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Растерзанные останки того, что на вид кажется похожим на гигантское морское млекопитающее, лежат на берегу. Около них валяется тачка и различные инструменты, как будто кто-то раньше уже пытался изучать останки. Хотя мурлоки основательно растащили скелет, останков достаточно, чтобы найти подходящий образец костей для Гвеннид Блай\'Леггонд в Аубердине.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, я уверена, вы обнаружили останки твари, которые уже изучались Лигой Исследователей. Они работают здесь, на Темном Берегу, и упоминали, что изучали одну из выбросившихся на берег тварей, пока их не прогнали мурлоки. Похоже, вам удалось добиться успеха там, где и мы, и они потерпели фиаско. Пожалуйста, примите эту скромную плату от имени Храма Луны.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4729,'Редкие звери Киблера','Должно быть, тебе интересно, что я здесь делаю? Взгляни на клетки! Разве не ясно?$b$bЯ очень люблю животных, но по роду занятий я торговец. Я разыскиваю и приручаю редких зверей, чтобы богатые и знаменитые клиенты могли сделать их своими питомцами.$b$bТеперь ты, наверное, хочешь спросить: "Чем тебе помочь, Киблер?" Отвечаю: возьми эту клетку и поймай несколько щенков-воргов. За это я приручу одного из них и отдам тебе!','Отправьтесь на Пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру.','Киблер яростно спорит с Опусом.','Вернитесь к Киблеру в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Редкие звери Киблера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, тебе интересно, что я здесь делаю? Взгляни на клетки! Разве не ясно?$b$bЯ очень люблю животных, но по роду занятий я торговец. Я разыскиваю и приручаю редких зверей, чтобы богатые и знаменитые клиенты могли сделать их своими питомцами.$b$bТеперь ты, наверное, хочешь спросить: "Чем тебе помочь, Киблер?" Отвечаю: возьми эту клетку и поймай несколько щенков-воргов. За это я приручу одного из них и отдам тебе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь на Пик Черной горы и отыщите там щенков воргов легиона Кровавого Топора. Посадите маленьких тварей в клетку и отнесите Киблеру.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Киблер яростно спорит с Опусом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киблеру в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4730,'Выброшенная на берег морская тварь','Полуразложившиеся тело твари, похожей на огромное морское млекопитающее, лежит на берегу. Группа мурлоков, более сильных, чем обитающие ближе к Аубердину, обосновалась вокруг погибшего создания. Останков достаточно, чтобы отобрать образцы костей, которые можно отнести Гвеннид Блай\'Леггонд.','Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.','Кости, которые вы принесли, принадлежат мирным морским млекопитающим, обитающим в водах, окружающих корни Тельдрассила. Им, насколько известно, никогда не было свойственно выбрасываться на берег, как это делают крепкозубы. Хотела бы я знать, почему они так ведут себя. Что ж, может быть, изучение их останков принесет свои плоды, и мы что-то узнаем.$B$BИ снова спасибо вам за помощь. Пожалуйста, примите это вознаграждение от имени Храма Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выброшенная на берег морская тварь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полуразложившиеся тело твари, похожей на огромное морское млекопитающее, лежит на берегу. Группа мурлоков, более сильных, чем обитающие ближе к Аубердину, обосновалась вокруг погибшего создания. Останков достаточно, чтобы отобрать образцы костей, которые можно отнести Гвеннид Блай\'Леггонд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кости, которые вы принесли, принадлежат мирным морским млекопитающим, обитающим в водах, окружающих корни Тельдрассила. Им, насколько известно, никогда не было свойственно выбрасываться на берег, как это делают крепкозубы. Хотела бы я знать, почему они так ведут себя. Что ж, может быть, изучение их останков принесет свои плоды, и мы что-то узнаем.$B$BИ снова спасибо вам за помощь. Пожалуйста, примите это вознаграждение от имени Храма Луны.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4731,'Выброшенная на берег морская черепаха','Еще одни останки морской черепахи лежат у береговой линии. На панцире есть упряжь, которая еще частично держится. Возможно, несчастная тварь не сама выбросилась на берег (что кажется наиболее вероятным по отношению к другим погибшим тварям), а была пригнана к береговой линии неизвестными существами. Могучие мурлоки племени Серой Мглы сделали остов этой твари своим жилищем.$B$BОбследуя упряжь, вы обнаруживаете ящик со странными пометками. Возможно, Гвеннид Блай\'Леггонд сумеет что-то разобрать?','Отнесите ящик со странными пометками Гвеннид Блай\'Леггонд в Аубердин.','Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Темного Берега.$B$BЯ отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и еще раз спасибо за вашу помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выброшенная на берег морская черепаха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще одни останки морской черепахи лежат у береговой линии. На панцире есть упряжь, которая еще частично держится. Возможно, несчастная тварь не сама выбросилась на берег (что кажется наиболее вероятным по отношению к другим погибшим тварям), а была пригнана к береговой линии неизвестными существами. Могучие мурлоки племени Серой Мглы сделали остов этой твари своим жилищем.$B$BОбследуя упряжь, вы обнаруживаете ящик со странными пометками. Возможно, Гвеннид Блай\'Леггонд сумеет что-то разобрать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик со странными пометками Гвеннид Блай\'Леггонд в Аубердин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я слышала о такой сбруе, которую вы нашли на черепашьем панцире. Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу. Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Темного Берега.$B$BЯ отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и еще раз спасибо за вашу помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4732,'Выброшенная на берег морская черепаха','Вы обнаружили тело морской черепахи, выбросившейся на Темные берега некоторое время назад. Оно почти дочиста объедено мурлоками племени Серой Мглы – теми самыми, что поселились вокруг останков. Но похоже, что несколько подходящих образцов для Гвиннед Блай\'Леггонд вы сможете отобрать.','Отнесите останки морской черепахи Гвеннид Блай\'Леггонд в Аубердин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выброшенная на берег морская черепаха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы обнаружили тело морской черепахи, выбросившейся на Темные берега некоторое время назад. Оно почти дочиста объедено мурлоками племени Серой Мглы – теми самыми, что поселились вокруг останков. Но похоже, что несколько подходящих образцов для Гвиннед Блай\'Леггонд вы сможете отобрать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите останки морской черепахи Гвеннид Блай\'Леггонд в Аубердин.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4733,'Выброшенная на берег морская тварь','Останки животного, похожего на гигантского крепкозуба, лежат, вынесенные на отмель в скалистой Сумрачной Излучине. Этот крепкозуб в несколько раз больше любого из тех, что обитают в здешних водах. Откуда бы это создание ни приплыло, вряд ли оно родом с Темных берегов.$B$BХотя туша животного уже потеряла целостность, останков достаточно, чтобы найти подходящие образцы для Гвеннид Блай\'Леггонд.','Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выброшенная на берег морская тварь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Останки животного, похожего на гигантского крепкозуба, лежат, вынесенные на отмель в скалистой Сумрачной Излучине. Этот крепкозуб в несколько раз больше любого из тех, что обитают в здешних водах. Откуда бы это создание ни приплыло, вряд ли оно родом с Темных берегов.$B$BХотя туша животного уже потеряла целостность, останков достаточно, чтобы найти подходящие образцы для Гвеннид Блай\'Леггонд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кости морской твари Гвеннид Блай\'Леггонд в Аубердин.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4734,'Заморозка яйца','$n, я работаю над созданием нового устройства, яйцехладоскопа! Оно предназначено для того, чтобы направить сгусток холода на яйцо дракона... и заморозить его! Можешь испытать эту штуку?$B$BГоворят, что на Пике Черной горы у драконов есть Гнездовье, в котором полно яиц. Подходящее место для испытаний! Заморозь яйцо и расскажи, сработал прибор или нет.$B$BНе беспокойся. Замороженные драконьи яйца совершенно безобидны. А вот остальных надо опасаться!','Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье на Пике Черной горы.','Сработало? Великолепно! Я так и знала!$B$BПока тебя не было, я создала новую модель яйцехладоскопа. С куда большим радиусом действия.$B$BВозьми его, вдруг случайно забредешь на пик Черной горы.','Ну как, $Gиспытал:испытала; яйцехладоскоп?','Испытать модель яйцехладоскопа','Вернитесь к Тинки Кипеллер в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заморозка яйца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я работаю над созданием нового устройства, яйцехладоскопа! Оно предназначено для того, чтобы направить сгусток холода на яйцо дракона... и заморозить его! Можешь испытать эту штуку?$B$BГоворят, что на Пике Черной горы у драконов есть Гнездовье, в котором полно яиц. Подходящее место для испытаний! Заморозь яйцо и расскажи, сработал прибор или нет.$B$BНе беспокойся. Замороженные драконьи яйца совершенно безобидны. А вот остальных надо опасаться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте прототип яйцехладоскопа на одном из яиц в Гнездовье на Пике Черной горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сработало? Великолепно! Я так и знала!$B$BПока тебя не было, я создала новую модель яйцехладоскопа. С куда большим радиусом действия.$B$BВозьми его, вдруг случайно забредешь на пик Черной горы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, $Gиспытал:испытала; яйцехладоскоп?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Испытать модель яйцехладоскопа',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тинки Кипеллер в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4735,'Сбор яиц','$n, я, наконец, готова исследовать настоящие яйца драконов! Возьми это устройство-коллекционер. Он предназначен для захвата драконьего яйца и подготовки его к транспортировке. Возвращайся в Гнездовье и собери при помощи этой штуки несколько яиц.$B$BНе забудь, первым делом их надо заморозить, иначе из них могут вылупиться драконы, не успеешь собрать!$B$BКак только наберешь достаточно яиц, неси их мне!','Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.','Ух ты! Яйца! Значит, устройство-коллекционер сработало! Я гений!$B$BСпасибо, $N. Мой заказчик очень порадуется яйцам...','Ты несешь мне яйца, $N? Мой заказчик прослышал, что ты занимаешься их сбором, и очень хочет их получить!','Вернитесь к Тинки Кипеллер в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор яиц',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я, наконец, готова исследовать настоящие яйца драконов! Возьми это устройство-коллекционер. Он предназначен для захвата драконьего яйца и подготовки его к транспортировке. Возвращайся в Гнездовье и собери при помощи этой штуки несколько яиц.$B$BНе забудь, первым делом их надо заморозить, иначе из них могут вылупиться драконы, не успеешь собрать!$B$BКак только наберешь достаточно яиц, неси их мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 драконьих яиц и устройство-коллекционер Тинки Кипеллер в Пламенеющий Стяг в Пылающих степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Яйца! Значит, устройство-коллекционер сработало! Я гений!$B$BСпасибо, $N. Мой заказчик очень порадуется яйцам...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты несешь мне яйца, $N? Мой заказчик прослышал, что ты занимаешься их сбором, и очень хочет их получить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тинки Кипеллер в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4736,'Поиски Менары Расщепительницы Бездны','А, привет, $n. Твое обучение идет неплохо. Настолько неплохо, что, я думаю, пришло время вознаградить тебя за прилежание – и за то, что сила магии все еще не поработила тебя.$B$BЕсли тебя заинтересовали мои слова, поговори с Менарой Расщепительницей Бездны из Кабестана. В настоящий момент она живет в башне Страхада Фарсана, построенной на утесе над городом.$B$BОна не очень доброжелательно настроена, поэтому похвалы от нее не жди. Но если ты будешь стараться, твои усилия не пропадут втуне.','Поговорите с Менарой Расщепительницей Бездны в Степях.','А, тебя прислал Остротерн. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.$B$BНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.$B$BВижу, ты многому $Gнаучился:научилась;, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Менары Расщепительницы Бездны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, привет, $n. Твое обучение идет неплохо. Настолько неплохо, что, я думаю, пришло время вознаградить тебя за прилежание – и за то, что сила магии все еще не поработила тебя.$B$BЕсли тебя заинтересовали мои слова, поговори с Менарой Расщепительницей Бездны из Кабестана. В настоящий момент она живет в башне Страхада Фарсана, построенной на утесе над городом.$B$BОна не очень доброжелательно настроена, поэтому похвалы от нее не жди. Но если ты будешь стараться, твои усилия не пропадут втуне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Менарой Расщепительницей Бездны в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, тебя прислал Остротерн. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.$B$BНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.$B$BВижу, ты многому $Gнаучился:научилась;, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4737,'Поиски Менары Расщепительницы Бездны','Ха! Я вижу, ты стремишься к могуществу. Не сомневаюсь, рано или поздно ты падешь жертвой соблазна и жажды магии.$B$BПфа! Ты $gглуп:глупа;! Время покажет, что я был прав, – ничто другое, одно лишь время...$B$BНо мне кажется, что не все согласны с Зевростом. Менара готова создать предметы, которые помогут тебе обрести могущество и обуздать собственную силу. Если хочешь, ступай в Кабестан. Она живет в башне над городом.','Поговорите с Менарой Расщепительницей Бездны в Степях.','А, тебя прислал Зеврост. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.\n\nНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.\n\nВижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Менары Расщепительницы Бездны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ха! Я вижу, ты стремишься к могуществу. Не сомневаюсь, рано или поздно ты падешь жертвой соблазна и жажды магии.$B$BПфа! Ты $gглуп:глупа;! Время покажет, что я был прав, – ничто другое, одно лишь время...$B$BНо мне кажется, что не все согласны с Зевростом. Менара готова создать предметы, которые помогут тебе обрести могущество и обуздать собственную силу. Если хочешь, ступай в Кабестан. Она живет в башне над городом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Менарой Расщепительницей Бездны в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, тебя прислал Зеврост. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.\n\nНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.\n\nВижу, ты многому научился, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4738,'Поиски Менары Расщепительницы Бездны','Пойми одно, $n: я считаю, что ты не $gготов:готова; к такой ответственности. Я уверена, что вовлекать новичков в создание любых предметов силы, тем более, непроверенных, недопустимо.$B$BНо решать не мне, а сильным мира сего, которые хотят наделить тебя такими дарами.$B$BЕсли ты хочешь узнать побольше, советую поговорить с Менарой Расщепительницей Бездны из Кабестана. Обычно ее можно найти в башне над портом.','Поговорите с Менарой Расщепительницей Бездны в Степях.','А, тебя прислала Демизетта. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.$B$BНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.$B$BВижу, ты многому $Gнаучился:научилась;, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Менары Расщепительницы Бездны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пойми одно, $n: я считаю, что ты не $gготов:готова; к такой ответственности. Я уверена, что вовлекать новичков в создание любых предметов силы, тем более, непроверенных, недопустимо.$B$BНо решать не мне, а сильным мира сего, которые хотят наделить тебя такими дарами.$B$BЕсли ты хочешь узнать побольше, советую поговорить с Менарой Расщепительницей Бездны из Кабестана. Обычно ее можно найти в башне над портом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Менарой Расщепительницей Бездны в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, тебя прислала Демизетта. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.$B$BНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.$B$BВижу, ты многому $Gнаучился:научилась;, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4739,'Поиски Менары Расщепительницы Бездны','$C! Да, ты!$B$BВижу, ты не полностью $gэкипирован:экипирована;, хотя уверенности и $gподнабрался:поднабралась;. Да-да, теперь я это понимаю.$B$BМенара Расщепительница Бездны научит тебя нескольким вещам. Она немало времени посвящает обучению молодежи тайным искусствам. Тем, кто проходит ее испытания, она даже дает дары.$B$BЕсли хочешь поучиться, ступай в город Кабестан в Степях. Она живет над городом в башне Страхада.','Поговорите с Менарой Расщепительницей Бездны в Степях.','А, тебя прислал Каэл. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.$B$BНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.$B$BВижу, ты многому $Gнаучился:научилась;, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Менары Расщепительницы Бездны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C! Да, ты!$B$BВижу, ты не полностью $gэкипирован:экипирована;, хотя уверенности и $gподнабрался:поднабралась;. Да-да, теперь я это понимаю.$B$BМенара Расщепительница Бездны научит тебя нескольким вещам. Она немало времени посвящает обучению молодежи тайным искусствам. Тем, кто проходит ее испытания, она даже дает дары.$B$BЕсли хочешь поучиться, ступай в город Кабестан в Степях. Она живет над городом в башне Страхада.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Менарой Расщепительницей Бездны в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, тебя прислал Каэл. Хорошо. Значит, вести обо мне распространяются по всей земле, и ученики приходят сами. Приятно.$B$BНаш брат всегда старается держаться вместе, независимо от расы. Это особенно важно, учитывая, что те, с кем мы по большей части имеем дело, не преминут воспользоваться нашей слабостью и вырваться из-под контроля.$B$BВижу, ты многому $Gнаучился:научилась;, и если хочешь, я создам для тебя инструменты, которые помогут раскрыться твоему таланту.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (4740,'РАЗЫСКИВАЕТСЯ: Глубомрак!','Внимание!$B$BНазначена награда за голову мурлока, именуемого "Глубомрак". Эта злобная тварь повинна в смерти как минимум одного часового и подозревается в потоплении как минимум двух грузовых судов в прибрежных водах Темных берегов!$B$BГлубомрака в последний раз видели в поселении мурлоков к югу от Аубердина, и, судя по всему, он охраняет хижины своих сородичей. Награда за голову Глубомрака ждет смельчака у часового Глинды Нал\'Шии в Аубердине.$B$BСовет Аубердина','Найдите и убейте мурлока, известного как Глубомрак. Предполагается, что это существо охраняет и защищает хижины мурлоков в поселении к югу от Аубердина, у воды.$B$BО смерти Глубомрака доложите часовому Глинде Нал\'Шии в Аубердине.','Приветствую вас, |3-6($c). Чем часовые могут помочь вам? Вы пришли узнать о награде за голову Глубомрака?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РАЗЫСКИВАЕТСЯ: Глубомрак!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимание!$B$BНазначена награда за голову мурлока, именуемого "Глубомрак". Эта злобная тварь повинна в смерти как минимум одного часового и подозревается в потоплении как минимум двух грузовых судов в прибрежных водах Темных берегов!$B$BГлубомрака в последний раз видели в поселении мурлоков к югу от Аубердина, и, судя по всему, он охраняет хижины своих сородичей. Награда за голову Глубомрака ждет смельчака у часового Глинды Нал\'Шии в Аубердине.$B$BСовет Аубердина',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и убейте мурлока, известного как Глубомрак. Предполагается, что это существо охраняет и защищает хижины мурлоков в поселении к югу от Аубердина, у воды.$B$BО смерти Глубомрака доложите часовому Глинде Нал\'Шии в Аубердине.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую вас, |3-6($c). Чем часовые могут помочь вам? Вы пришли узнать о награде за голову Глубомрака?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4741,'Одичавшие стражи','В северных областях Зимних Ключей дикие совухи совсем озверели. Необходимо положить этому конец!$B$BУменьши численность осененных луной совухов, а заодно исследуешь местность, где они обитают.$B$BМеста там дикие, но ты справишься. Возвращайся, когда убьешь 13 совухов.','По заданию Трулла Баловня Судьбы из Оскверненного леса убейте 13 осененных луной совухов.','Сдается мне, тебе нравится эта работенка. Думаю, мы стараемся не напрасно.','Только не говори мне, что $Gструсил:струсила;, отправляйся!','Вернитесь к Труллу Баловню Судьбы на Заставу Отравленной Крови, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одичавшие стражи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В северных областях Зимних Ключей дикие совухи совсем озверели. Необходимо положить этому конец!$B$BУменьши численность осененных луной совухов, а заодно исследуешь местность, где они обитают.$B$BМеста там дикие, но ты справишься. Возвращайся, когда убьешь 13 совухов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Трулла Баловня Судьбы из Оскверненного леса убейте 13 осененных луной совухов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сдается мне, тебе нравится эта работенка. Думаю, мы стараемся не напрасно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Только не говори мне, что $Gструсил:струсила;, отправляйся!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Труллу Баловню Судьбы на Заставу Отравленной Крови, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4742,'Печать вознесения','Видишь, в этой печати есть три простых углубления. В них надо вставить три камня власти; после этого властитель Змейталак, владыка нижней крепости, должен будет закалить печать в пламени черных драконов.$B$BНайди эти камни! И помни, $gсмертный:смертная;: шансы, что у кого-то из трех генералов нижней крепости будет при себе нужный нам камень, невелики. Не отступайся! Ищи, будь $gвнимателен:внимательна; и не теряй решимости!','Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения.$B$BКамни могут быть у трех генералов: у воеводы Вуна из племени Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора.','<Образ Ваелана на миг расплывается мутным пятном.>$B$B<Камни, которые вы принесли, исчезли.>$B$BТеперь все готово к тому, чтобы печать вознесения обрела свою силу. Пора приступать к завершающему этапу.','Мужество и терпение превыше всего, $N!','Вернитесь к Ваелану на Вершину Черной горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать вознесения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь, в этой печати есть три простых углубления. В них надо вставить три камня власти; после этого властитель Змейталак, владыка нижней крепости, должен будет закалить печать в пламени черных драконов.$B$BНайди эти камни! И помни, $gсмертный:смертная;: шансы, что у кого-то из трех генералов нижней крепости будет при себе нужный нам камень, невелики. Не отступайся! Ищи, будь $gвнимателен:внимательна; и не теряй решимости!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите самоцвет Тлеющего Терновника, самоцвет Черной Вершины и самоцвет Кровавого Топора. Верните их Ваелану вместе с простой печатью Вознесения.$B$BКамни могут быть у трех генералов: у воеводы Вуна из племени Тлеющего Терновника, у вождя Омокка из клана Черной Вершины и у повелителя Змейталака из клана Кровавого Топора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Образ Ваелана на миг расплывается мутным пятном.>$B$B<Камни, которые вы принесли, исчезли.>$B$BТеперь все готово к тому, чтобы печать вознесения обрела свою силу. Пора приступать к завершающему этапу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мужество и терпение превыше всего, $N!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ваелану на Вершину Черной горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4743,'Печать вознесения','Очень немногие черные драконы из верхней крепости способны закалить печать в пламени своего дыхания. Змейталак – один из них, но его волю сломить невозможно.$B$BТебе надо добраться до Драконьих топей в Пылевых топях. Там ты найдешь древнего дракона, известного под именем Огнебор. Ты $gдолжен:должна; сломить его волю, $n. И когда он ослабнет, тебе нужно будет воспользоваться этой сферой. Но помни, $gсмертный:смертная;: его разум силен, и ты сможешь удерживать его под контролем не более нескольких секунд. За эти секунды тебе нужно успеть закалить печать.','Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю.$B$BКак только воля великого зверя ослабнет, надо немедленно положить перед ним заготовку печати вознесения и воспользоваться сферой Энергии дракона, чтобы подчинить себе его разум и направить его пламя на заготовку.','Стой спокойно. Я наложу последнее защитное заклинание.$B$B<Глаза Ваелана превращаются в два огненных шара.>$B$BТеперь печать Вознесения обрела свою полную силу...$B$BЯ вложил в артефакт очень мощные защитные чары. В минуту предельного отчаяния, когда тебе покажется, что все потеряно, призови силу красных драконов и используй ее для защиты.','Не теряй времени, $N. Нефариан тяжко трудится, чтобы впустить зло в наш мир.','Вернитесь к Ваелану на Вершину Черной горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать вознесения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Очень немногие черные драконы из верхней крепости способны закалить печать в пламени своего дыхания. Змейталак – один из них, но его волю сломить невозможно.$B$BТебе надо добраться до Драконьих топей в Пылевых топях. Там ты найдешь древнего дракона, известного под именем Огнебор. Ты $gдолжен:должна; сломить его волю, $n. И когда он ослабнет, тебе нужно будет воспользоваться этой сферой. Но помни, $gсмертный:смертная;: его разум силен, и ты сможешь удерживать его под контролем не более нескольких секунд. За эти секунды тебе нужно успеть закалить печать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в Драконьи топи в Пылевых топях. Найдите Огнебора и бейте его, не жалея, чтобы сломить его волю.$B$BКак только воля великого зверя ослабнет, надо немедленно положить перед ним заготовку печати вознесения и воспользоваться сферой Энергии дракона, чтобы подчинить себе его разум и направить его пламя на заготовку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стой спокойно. Я наложу последнее защитное заклинание.$B$B<Глаза Ваелана превращаются в два огненных шара.>$B$BТеперь печать Вознесения обрела свою полную силу...$B$BЯ вложил в артефакт очень мощные защитные чары. В минуту предельного отчаяния, когда тебе покажется, что все потеряно, призови силу красных драконов и используй ее для защиты.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не теряй времени, $N. Нефариан тяжко трудится, чтобы впустить зло в наш мир.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ваелану на Вершину Черной горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4761,'Тандрис Ветропряд','При разведке в лагере фурболгов вы обнаружили информацию, которую нужно довести до сведения Тандриса Ветропряда. Он любезно согласился исполнять обязанности старейшины в Аубердине, мудростью своей направляя повседневную жизнь деревни. Прошу вас поделиться с ним вашими находками в деле фурболгов.$b$bЯ уверен, что у него есть свои идеи по поводу источника наведенной на них порчи. Может быть, вы сможете вместе с ним выработать план восстановления природного равновесия!','Поговорите с Тандрисом Ветропрядом в Аубердине.','Рад нашей встрече, |3-6($c). Ваше расследование ситуации с фурболгами как нельзя кстати. Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящихся к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведенной на сами леса. Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тандрис Ветропряд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При разведке в лагере фурболгов вы обнаружили информацию, которую нужно довести до сведения Тандриса Ветропряда. Он любезно согласился исполнять обязанности старейшины в Аубердине, мудростью своей направляя повседневную жизнь деревни. Прошу вас поделиться с ним вашими находками в деле фурболгов.$b$bЯ уверен, что у него есть свои идеи по поводу источника наведенной на них порчи. Может быть, вы сможете вместе с ним выработать план восстановления природного равновесия!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тандрисом Ветропрядом в Аубердине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад нашей встрече, |3-6($c). Ваше расследование ситуации с фурболгами как нельзя кстати. Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящихся к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведенной на сами леса. Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (4762,'Река Скалистая','Воды реки Скалистой исполнились злобы и порчи. Река впадает в Туманный предел, и я боюсь, что скоро беда затронет и Аубердин. Я подозреваю, что в загрязнении повинны фурболги Чернолесья, живущие в верховьях реки, но я также полагаю, что они не являются подлинной причиной этой порчи.$b$bВозьмите эту пробирку и отправляйтесь к устью реки, что к северу отсюда. Идите вверх по реке до первого водопада и там возьмите пробу воды. Ориентиром вам послужит высокий мост через реку. Когда возьмете пробу, вернитесь ко мне в Аубердин.','Отправляйтесь на север от Аубердина, к первому водопаду вверх по реке Скалистой, и там возьмите пробу.$B$BС пробой воды Скалистой реки возвращайтесь в Аубердин к Тандрису Ветропряду.','Загрязнение реки Скалистой – лишь первое проявление тревожной тенденции здесь, на Темном Берегу. Проба, которую вы добудете, поможет нам составить план... как я начинаю подозревать, план атаки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Река Скалистая',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воды реки Скалистой исполнились злобы и порчи. Река впадает в Туманный предел, и я боюсь, что скоро беда затронет и Аубердин. Я подозреваю, что в загрязнении повинны фурболги Чернолесья, живущие в верховьях реки, но я также полагаю, что они не являются подлинной причиной этой порчи.$b$bВозьмите эту пробирку и отправляйтесь к устью реки, что к северу отсюда. Идите вверх по реке до первого водопада и там возьмите пробу воды. Ориентиром вам послужит высокий мост через реку. Когда возьмете пробу, вернитесь ко мне в Аубердин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на север от Аубердина, к первому водопаду вверх по реке Скалистой, и там возьмите пробу.$B$BС пробой воды Скалистой реки возвращайтесь в Аубердин к Тандрису Ветропряду.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Загрязнение реки Скалистой – лишь первое проявление тревожной тенденции здесь, на Темном Берегу. Проба, которую вы добудете, поможет нам составить план... как я начинаю подозревать, план атаки.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (4763,'Порабощенные фурболги Чернолесья','Мы узнали, что источником порчи, наведенной на фурболгов, являются сатиры. Они держат своих жертв в повиновении с помощью талисманов, через которые направляют магию. Если для фурболгов еще есть шансы на спасение, мы должны выманить сатиров-поработителей и отнять у них талисманы!$b$bНаполни эту чашу из нашего Лунного колодца и стащи образцы пищи фурболгов из их северного лагеря. Смешай все и поставь чашу возле большого костра у реки; любой фурболг, поевший из этой чаши, на некоторое время очистится, что привлечет внимание сатира... которого нужно убить!','Наполните пустую чашу Очищения из Лунного колодца Аубердина.$B$BСоберите образцы фруктов, орехов и зерна в расположенных на севере лагерях фурболгов.$B$BСмешайте все в чаше и поместите ее возле ближайшего к реке Скалистой большого костра в северном лагере, вызвав таким образом сатира.$B$BСнимите с него Талисман Скверны и принесите его Тандрису Ветропряду в Аубердин.','Талисман Скверны – это жуткое приспособление, которое служит для нарушения природного баланса. Когда вы найдете этот предмет среди того, чем сатир мучает фурболгов, и принесете его мне для уничтожения, можно будет считать, что мы одержали великую победу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порабощенные фурболги Чернолесья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы узнали, что источником порчи, наведенной на фурболгов, являются сатиры. Они держат своих жертв в повиновении с помощью талисманов, через которые направляют магию. Если для фурболгов еще есть шансы на спасение, мы должны выманить сатиров-поработителей и отнять у них талисманы!$b$bНаполни эту чашу из нашего Лунного колодца и стащи образцы пищи фурболгов из их северного лагеря. Смешай все и поставь чашу возле большого костра у реки; любой фурболг, поевший из этой чаши, на некоторое время очистится, что привлечет внимание сатира... которого нужно убить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните пустую чашу Очищения из Лунного колодца Аубердина.$B$BСоберите образцы фруктов, орехов и зерна в расположенных на севере лагерях фурболгов.$B$BСмешайте все в чаше и поместите ее возле ближайшего к реке Скалистой большого костра в северном лагере, вызвав таким образом сатира.$B$BСнимите с него Талисман Скверны и принесите его Тандрису Ветропряду в Аубердин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Талисман Скверны – это жуткое приспособление, которое служит для нарушения природного баланса. Когда вы найдете этот предмет среди того, чем сатир мучает фурболгов, и принесете его мне для уничтожения, можно будет считать, что мы одержали великую победу!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4764,'Пряжка Роковой оснастки','Высоко в горах, на Пике Черной горы, есть чертог, который некогда звался Залом Сокровищ. Именно там дворфы Черного Железа хранили свои реликвии, трофеи и предметы искусства.$b$bЭто было давно. Говорят, что зал обрушился, и теперь используется... менее достойно. Но я думаю, что там остались дворфийские реликвии.$b$bОдна из них – пряжка Роковой оснастки. Ее поверхность так плотно инкрустирована редкими самоцветами, что любой дворф начинает плакать от одного ее вида.$b$bИменно эта пряжка и станет твоей целью, $n.','Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи.','Вернитесь к Майре Светлое Крыло в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пряжка Роковой оснастки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Высоко в горах, на Пике Черной горы, есть чертог, который некогда звался Залом Сокровищ. Именно там дворфы Черного Железа хранили свои реликвии, трофеи и предметы искусства.$b$bЭто было давно. Говорят, что зал обрушился, и теперь используется... менее достойно. Но я думаю, что там остались дворфийские реликвии.$b$bОдна из них – пряжка Роковой оснастки. Ее поверхность так плотно инкрустирована редкими самоцветами, что любой дворф начинает плакать от одного ее вида.$b$bИменно эта пряжка и станет твоей целью, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите пряжку Роковой оснастки Майре Светлое Крыло в Пылающие степи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Майре Светлое Крыло в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (4765,'Доставить Риджвеллу','Я упаковала пряжку Роковой оснастки в ящик для отправки в Штормград. $n, ты мне очень $gпомог:помогла;, но я хочу попросить еще об одной услуге.$b$bДоставь этот ящик графу Ремингтону Риджвеллу. Он в Крепости Ветров. Не сомневаюсь, он обрадуется.','Отнесите ящик Риджвелла Ремингтону Риджвеллу в крепость Штормграда.','Мне доложили о прибытии вестника. Вестника с даром с пика Черной горы.\n\nЭто ты?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставить Риджвеллу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я упаковала пряжку Роковой оснастки в ящик для отправки в Штормград. $n, ты мне очень $gпомог:помогла;, но я хочу попросить еще об одной услуге.$b$bДоставь этот ящик графу Ремингтону Риджвеллу. Он в Крепости Ветров. Не сомневаюсь, он обрадуется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик Риджвелла Ремингтону Риджвеллу в крепость Штормграда.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне доложили о прибытии вестника. Вестника с даром с пика Черной горы.\n\nЭто ты?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4766,'Майра Светлое Крыло','Мой агент, Майра, отправилась в Пылающие степи, чтобы обыскать развалины города Тауриссана. В разрушенном обиталище дворфов Черного Железа таится множество ценных вещей... которые украсят наш семейный музей.$b$bМайара говорит, что кое-что нашла, но ей нужна помощь. Правда, это находится не в Тауриссане. Вместо этого требуется устроить вылазку на Пик Черной горы.$b$bПодробности мне неизвестны, но если тебя заинтересовало мое предложение, поговори с Майрой в Пылающих степях.','Поговорите с Майрой Светлое Крыло в Дозоре Морганы, что в Пылающих степях.','Ты из Штормграда? Чудесно – я знаю об одном предмете искусства, который Ремингтон любой ценой захочет заполучить в свой музей. Но это будет нелегко.$B$BТут-то ты и понадобишься.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Майра Светлое Крыло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой агент, Майра, отправилась в Пылающие степи, чтобы обыскать развалины города Тауриссана. В разрушенном обиталище дворфов Черного Железа таится множество ценных вещей... которые украсят наш семейный музей.$b$bМайара говорит, что кое-что нашла, но ей нужна помощь. Правда, это находится не в Тауриссане. Вместо этого требуется устроить вылазку на Пик Черной горы.$b$bПодробности мне неизвестны, но если тебя заинтересовало мое предложение, поговори с Майрой в Пылающих степях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Майрой Светлое Крыло в Дозоре Морганы, что в Пылающих степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты из Штормграда? Чудесно – я знаю об одном предмете искусства, который Ремингтон любой ценой захочет заполучить в свой музей. Но это будет нелегко.$B$BТут-то ты и понадобишься.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (4767,'Ветрокрыл','Мне велели набрать новых виверн, чтобы выдрессировать их и использовать в качестве ездовых животных. Их поголовье постоянно растет, и я надеюсь, что когда-нибудь сам смогу стать всадником на ветрокрыле. Однако виверны пользуются большим спросом, и нам их постоянно не хватает. Может быть, вы, $n, сможете мне помочь?$B$BЯ хочу попросить вас отправиться в Скальное гнездовье и набрать с кладок виверн немного яиц. Отсюда ступайте на северо-запад, держитесь поближе к стене каньона – и увидите дорогу, ведущую наверх. Но будьте очень осторожны: виверны не любят чужаков, а уж за свои кладки они будут готовы разорвать кого угодно.','Соберите в Скальном гнездовье 10 яиц виверн и отнесите их Элу на Заставу Вольного Ветра.','Отлично! Детеныши из этих яиц помогут мне осуществить задуманное! Возьмите это в знак моей признательности, пусть вам всегда везет на любой охоте, |3-6($C).','Вернитесь к Элу на Заставу Вольного Ветра, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветрокрыл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне велели набрать новых виверн, чтобы выдрессировать их и использовать в качестве ездовых животных. Их поголовье постоянно растет, и я надеюсь, что когда-нибудь сам смогу стать всадником на ветрокрыле. Однако виверны пользуются большим спросом, и нам их постоянно не хватает. Может быть, вы, $n, сможете мне помочь?$B$BЯ хочу попросить вас отправиться в Скальное гнездовье и набрать с кладок виверн немного яиц. Отсюда ступайте на северо-запад, держитесь поближе к стене каньона – и увидите дорогу, ведущую наверх. Но будьте очень осторожны: виверны не любят чужаков, а уж за свои кладки они будут готовы разорвать кого угодно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите в Скальном гнездовье 10 яиц виверн и отнесите их Элу на Заставу Вольного Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Детеныши из этих яиц помогут мне осуществить задуманное! Возьмите это в знак моей признательности, пусть вам всегда везет на любой охоте, |3-6($C).',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элу на Заставу Вольного Ветра, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4768,'Табличка Темнокамня','Табличка Темного Камня – это записки покойного дворфа Урхельда Темного Камня. Он был величайшим алхимиком древности, но современники считали его сумасшедшим и не придавали значения его изысканиям.$B$BИзвестно, что он записал результаты своих трудов. Вырезал их на табличках. И у меня есть основания предполагать, что одна из этих табличек хранится на Пике Черной горы, в зале, который когда-то назывался залом Удачи. Как его называют сейчас, я не знаю, ибо многие уходили в Черную Скалу, но немногие вернулись назад.$B$BЕсли тебя не пугают опасности Пика Черной горы, принеси мне табличку, и я щедро тебя награжу.','Принесите табличку Темного Камня тенемагу Вивиан Лягроб в Каргат.','Превосходно. Для того чтобы разобраться со всеми формулами, мне потребуется не один день, но я уверена, что результат будет стоить затраченного труда.$B$BСпасибо, $N. Ты $Gоказал:оказала; нам поистине неоценимую услугу.','Тебе удалось разыскать табличку, $N? Мне не терпится приступить к изучению ее секретов.','Вернитесь к темному магу Вивиане Лягроб к скелету Апокрифана, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Табличка Темнокамня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Табличка Темного Камня – это записки покойного дворфа Урхельда Темного Камня. Он был величайшим алхимиком древности, но современники считали его сумасшедшим и не придавали значения его изысканиям.$B$BИзвестно, что он записал результаты своих трудов. Вырезал их на табличках. И у меня есть основания предполагать, что одна из этих табличек хранится на Пике Черной горы, в зале, который когда-то назывался залом Удачи. Как его называют сейчас, я не знаю, ибо многие уходили в Черную Скалу, но немногие вернулись назад.$B$BЕсли тебя не пугают опасности Пика Черной горы, принеси мне табличку, и я щедро тебя награжу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите табличку Темного Камня тенемагу Вивиан Лягроб в Каргат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно. Для того чтобы разобраться со всеми формулами, мне потребуется не один день, но я уверена, что результат будет стоить затраченного труда.$B$BСпасибо, $N. Ты $Gоказал:оказала; нам поистине неоценимую услугу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось разыскать табличку, $N? Мне не терпится приступить к изучению ее секретов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному магу Вивиане Лягроб к скелету Апокрифана, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4769,'Вивиан Лягроб и табличка Темнокамня','Вивиан Лягроб прислала мне весть из Каргата, что в Бесплодных землях. Она выяснила, что на Пике Черной горы хранится один древний текст, который может помочь нам в изысканиях. Однако это всего лишь догадка, требующая подтверждения. Нужно, чтобы кто-то добыл этот текст. Но сразу скажу: это будет непросто.$B$BЕсли возьмешься за эту работу, обратись к Вивиан в Каргат.','Переговорите с темным магом Вивианой Лягроб.','Верно. У меня есть основания предполагать, что в Пике Черной горы хранится табличка, на которой записаны древние алхимические рецептуры. Я рада, что ты обратился ко мне, ибо мне нужна помощь. Я должна получить эту табличку.\n\nСадись и устраивайся поудобнее, я сейчас объясню, что к чему.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вивиан Лягроб и табличка Темнокамня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вивиан Лягроб прислала мне весть из Каргата, что в Бесплодных землях. Она выяснила, что на Пике Черной горы хранится один древний текст, который может помочь нам в изысканиях. Однако это всего лишь догадка, требующая подтверждения. Нужно, чтобы кто-то добыл этот текст. Но сразу скажу: это будет непросто.$B$BЕсли возьмешься за эту работу, обратись к Вивиан в Каргат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Переговорите с темным магом Вивианой Лягроб.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Верно. У меня есть основания предполагать, что в Пике Черной горы хранится табличка, на которой записаны древние алхимические рецептуры. Я рада, что ты обратился ко мне, ибо мне нужна помощь. Я должна получить эту табличку.\n\nСадись и устраивайся поудобнее, я сейчас объясню, что к чему.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4770,'Путь домой','Пожалуйста, |3-6($c), помогите мне! Я уже несколько дней прячусь в этом Скальном гнездовье, и за это время не встретил ни одного знакомого лица! Я пришел сюда изучать виверн и, похоже, немного переборщил – пришлось спасаться от них бегством, вот тогда-то я и заблудился.$B$BМне срочно нужно вернуться на заставу Белого Плеса! Мотега не знает, что я потерялся, а когда узнает, что я полез в Скальное гнездовье один, он мне голову оторвет!$B$BЗастава прямо к востоку отсюда... пожалуйста, проводите меня туда!','Выведите Паоку Ходячую Гору из Скального гнездовья, а потом поговорите с Мотегой Огненной Гривой на заставе Белого Плеса.','Что?! Да если б я знал, что Паока Ходячая Гора полезет в Скальное гнездовье, я бы цепями приковал его к тотему! Его отец был против того, чтобы он ехал со мной в Тысячу Игл. Мы собирались изучать различных животных, населяющих эти прекрасные земли.\n\nЯ очень признателен вам за то, что вы помогли Паоке. Надеюсь, это покроет все ваши затраты.','Выведите Паоку из Скального гнездовья','Вернитесь к Мотеге Огненной Гриве в Тысячу Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь домой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуйста, |3-6($c), помогите мне! Я уже несколько дней прячусь в этом Скальном гнездовье, и за это время не встретил ни одного знакомого лица! Я пришел сюда изучать виверн и, похоже, немного переборщил – пришлось спасаться от них бегством, вот тогда-то я и заблудился.$B$BМне срочно нужно вернуться на заставу Белого Плеса! Мотега не знает, что я потерялся, а когда узнает, что я полез в Скальное гнездовье один, он мне голову оторвет!$B$BЗастава прямо к востоку отсюда... пожалуйста, проводите меня туда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выведите Паоку Ходячую Гору из Скального гнездовья, а потом поговорите с Мотегой Огненной Гривой на заставе Белого Плеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что?! Да если б я знал, что Паока Ходячая Гора полезет в Скальное гнездовье, я бы цепями приковал его к тотему! Его отец был против того, чтобы он ехал со мной в Тысячу Игл. Мы собирались изучать различных животных, населяющих эти прекрасные земли.\n\nЯ очень признателен вам за то, что вы помогли Паоке. Надеюсь, это покроет все ваши затраты.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Выведите Паоку из Скального гнездовья',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мотеге Огненной Гриве в Тысячу Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4771,'Рассветный гамбит','Я поместила рассветный гамбит в ящик, в котором были драконьи яйца. Ты $gдолжен:должна; отнести его в самую глубину Некроситета.$B$BВектус, маг из нежити, руководит группой студентов Плети. Доставь рассветный гамбит в комнату, которую они называют демонстрационной. Если все пойдет как надо, устройство уничтожит всю нежить, находящуюся в этот момент в комнате.$B$BПосле этого уничтожить Вектуса будет проще пареной репы. Так ведь?','Отнесите рассветный гамбит в демонстрационную комнату в Некроситете. Уничтожьте Вектуса и возвращайтесь к Бетине Биггльцинк.','Я поместила "Рассветный гамбит" в ящик, в котором были драконьи яйца. Ты $Gдолжен:должна; отнести его в самую глубину Некроситета.$B$BВектус, маг из нежити, руководит группой студентов Плети. Доставь "Рассветный гамбит" в комнату, которую они называют смотровой. Если все пойдет как надо, устройство уничтожит всю нежить, находящуюся в этот момент в комнате.$B$BПосле этого уничтожить Вектуса будет проще пареной репы. Так ведь?','Помните, $N - мы должны быть терпеливыми, но твердыми в своих убеждениях!','Отнесите рассветный гамбит','Вернитесь к Бетине Биггльцинк в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рассветный гамбит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я поместила рассветный гамбит в ящик, в котором были драконьи яйца. Ты $gдолжен:должна; отнести его в самую глубину Некроситета.$B$BВектус, маг из нежити, руководит группой студентов Плети. Доставь рассветный гамбит в комнату, которую они называют демонстрационной. Если все пойдет как надо, устройство уничтожит всю нежить, находящуюся в этот момент в комнате.$B$BПосле этого уничтожить Вектуса будет проще пареной репы. Так ведь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите рассветный гамбит в демонстрационную комнату в Некроситете. Уничтожьте Вектуса и возвращайтесь к Бетине Биггльцинк.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я поместила "Рассветный гамбит" в ящик, в котором были драконьи яйца. Ты $Gдолжен:должна; отнести его в самую глубину Некроситета.$B$BВектус, маг из нежити, руководит группой студентов Плети. Доставь "Рассветный гамбит" в комнату, которую они называют смотровой. Если все пойдет как надо, устройство уничтожит всю нежить, находящуюся в этот момент в комнате.$B$BПосле этого уничтожить Вектуса будет проще пареной репы. Так ведь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Помните, $N - мы должны быть терпеливыми, но твердыми в своих убеждениях!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отнесите рассветный гамбит',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бетине Биггльцинк в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4781,'Материалы для зачарованного золотого кровавого одеяния','Следующее задание не сложнее первого, но тебе все равно потребуется помощь.$B$BДля вышивки мне нужна золотая нить, но ее не так просто найти, и мало кто знает, как ее делать. К счастью, этот секрет ведом одному из тех, кто верен нашему делу и старается помогать тем, кто стремится пополнить наши ряды.$B$BОтнеси золотой слиток Зиску Ладноскрою в Пиратскую Бухту. Он отличный портной и с радостью спрядет для тебя нить. Золотые слитки могут изготавливать опытные горняки. Обратись к ним.','Отнесите слиток золота Зиску Ладноскрою в Тернистую долину.','Великолепно. Я рад, что ты сумел так быстро заручиться помощью горняка. Или ты сам справился? Так или иначе, молодчина. Нить из этого слитка выйдет превосходная.\n\nНа ее изготовление понадобится время, поэтому возвращайся немного позже – честно говоря, я послал слиток одной принцессе, запертой в башне, которая только и делает, что прядет золотые нити... нет, честно. Я не шучу... ладно, шучу.','Да-да, золотые слитки. Принеси мне слиток, и тогда поговорим про нить. А пока я советую сосредоточиться на обучении. Самые суровые испытания еще впереди. Поверь, сколько ты ни занимайся, сколько ни копи силу, ее все равно будет не хватать.','Вернитесь к Зиску Ладноскрою в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Материалы для зачарованного золотого кровавого одеяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следующее задание не сложнее первого, но тебе все равно потребуется помощь.$B$BДля вышивки мне нужна золотая нить, но ее не так просто найти, и мало кто знает, как ее делать. К счастью, этот секрет ведом одному из тех, кто верен нашему делу и старается помогать тем, кто стремится пополнить наши ряды.$B$BОтнеси золотой слиток Зиску Ладноскрою в Пиратскую Бухту. Он отличный портной и с радостью спрядет для тебя нить. Золотые слитки могут изготавливать опытные горняки. Обратись к ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите слиток золота Зиску Ладноскрою в Тернистую долину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Я рад, что ты сумел так быстро заручиться помощью горняка. Или ты сам справился? Так или иначе, молодчина. Нить из этого слитка выйдет превосходная.\n\nНа ее изготовление понадобится время, поэтому возвращайся немного позже – честно говоря, я послал слиток одной принцессе, запертой в башне, которая только и делает, что прядет золотые нити... нет, честно. Я не шучу... ладно, шучу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да-да, золотые слитки. Принеси мне слиток, и тогда поговорим про нить. А пока я советую сосредоточиться на обучении. Самые суровые испытания еще впереди. Поверь, сколько ты ни занимайся, сколько ни копи силу, ее все равно будет не хватать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зиску Ладноскрою в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4782,'Материалы для зачарованного золотого кровавого одеяния','Возвращайся к Менаре и скажи ей, что работа предстоит долгая, но я постараюсь ради нее... и ради тебя. Передай ей, что пока ты собираешь остальные материалы, я закончу делать нить. Тогда ты придешь и заберешь ее.$B$BУдачи, $n. Ах, да, передай привет Страхаду, раз уж будешь рядом. Старый болван... как его угораздило построить башню рядом с Кабестаном?','Возвращайтесь к Менаре Расщепительнице Бездны в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Материалы для зачарованного золотого кровавого одеяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возвращайся к Менаре и скажи ей, что работа предстоит долгая, но я постараюсь ради нее... и ради тебя. Передай ей, что пока ты собираешь остальные материалы, я закончу делать нить. Тогда ты придешь и заберешь ее.$B$BУдачи, $n. Ах, да, передай привет Страхаду, раз уж будешь рядом. Старый болван... как его угораздило построить башню рядом с Кабестаном?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к Менаре Расщепительнице Бездны в Степи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4783,'Материалы для зачарованного золотого кровавого одеяния','Следующие материалы можно найти в Пустошах, далеко на западе от Степей, за Когтистыми горами.$B$BТам все еще царит хаос со времен Раскола. Это место, где предстоит серьезное испытание твоей силе и хитрости – там бродят омерзительные твари и приспешники Пылающего Легиона.$B$BПринеси мне кровь сатиров племени Ярой Ненависти, что обитают на северо-востоке, и простой камень Преисподней от младших инферналов Поля Маннорок.$B$BИ то, и другое понадобится для создания одеяния.','Принесите 10 фиалов крови сатира племени Ярой Ненависти и 1 простой камень Преисподней в Степи, Менаре Расщепительнице Бездны.','Вернитесь к Менаре Расщепительнице Бездны в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Материалы для зачарованного золотого кровавого одеяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следующие материалы можно найти в Пустошах, далеко на западе от Степей, за Когтистыми горами.$B$BТам все еще царит хаос со времен Раскола. Это место, где предстоит серьезное испытание твоей силе и хитрости – там бродят омерзительные твари и приспешники Пылающего Легиона.$B$BПринеси мне кровь сатиров племени Ярой Ненависти, что обитают на северо-востоке, и простой камень Преисподней от младших инферналов Поля Маннорок.$B$BИ то, и другое понадобится для создания одеяния.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 фиалов крови сатира племени Ярой Ненависти и 1 простой камень Преисподней в Степи, Менаре Расщепительнице Бездны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менаре Расщепительнице Бездны в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4784,'Материалы для зачарованного золотого кровавого одеяния','Осталось отыскать три составляющих, $n, и твое одеяние будет готово.$B$BВо-первых, нить из чистого золота, которую делает Зиск. Отправляйся к нему в Пиратскую Бухту и принеси нить.$B$BВо-вторых, нужны тлеющие угли элементалей огня с Нагорья Арати. Если я правильно помню, духов можно найти в западной части нагорья, рядом со стеной Торадина.$B$BИ, наконец, мне нужен осколок души, созданный тобой.$B$BСобрав все составляющие, возвращайся в башню, и я закончу работу над одеянием.','Принесите Менаре Расщепительнице Бездны в Степи нить из чистого золота, 2 тлеющих угля и осколок души.','Вернитесь к Менаре Расщепительнице Бездны в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Материалы для зачарованного золотого кровавого одеяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осталось отыскать три составляющих, $n, и твое одеяние будет готово.$B$BВо-первых, нить из чистого золота, которую делает Зиск. Отправляйся к нему в Пиратскую Бухту и принеси нить.$B$BВо-вторых, нужны тлеющие угли элементалей огня с Нагорья Арати. Если я правильно помню, духов можно найти в западной части нагорья, рядом со стеной Торадина.$B$BИ, наконец, мне нужен осколок души, созданный тобой.$B$BСобрав все составляющие, возвращайся в башню, и я закончу работу над одеянием.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Менаре Расщепительнице Бездны в Степи нить из чистого золота, 2 тлеющих угля и осколок души.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менаре Расщепительнице Бездны в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (4785,'Нить из чистого золота','Вот, бери. И пожалуйста, передай от нас привет Менаре.$B$BМы ждем от тебя великих свершений. Быть может, когда Легион падет на колени, прозвучит твое имя и хвала твоей силе. Жду не дождусь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нить из чистого золота',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, бери. И пожалуйста, передай от нас привет Менаре.$B$BМы ждем от тебя великих свершений. Быть может, когда Легион падет на колени, прозвучит твое имя и хвала твоей силе. Жду не дождусь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4786,'Завершенное одеяние','А теперь я завершу работу над одеянием. Это займет немного времени. Не уходи далеко.','Дождитесь, пока Менара Расщепительница Бездны закончит работу над вашим одеянием, и еще раз поговорите с ней.','Готово. Прими это одеяние и носи его с честью.\n\nТы хорошо поработал, и я предвижу, что тебя ждут великие дела. Помни: чтобы справиться с искушением скверны, которое подстерегает каждого, ступившего на путь магии, понадобится сильная воля и немалая стойкость. Пока ты не лишился воли, тебя ждут великие успехи.','Дождитесь, пока Менара Расщепительница Бездны закончит работу над вашим одеянием.','Вернитесь к Менаре Расщепительнице Бездны в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завершенное одеяние',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А теперь я завершу работу над одеянием. Это займет немного времени. Не уходи далеко.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока Менара Расщепительница Бездны закончит работу над вашим одеянием, и еще раз поговорите с ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Готово. Прими это одеяние и носи его с честью.\n\nТы хорошо поработал, и я предвижу, что тебя ждут великие дела. Помни: чтобы справиться с искушением скверны, которое подстерегает каждого, ступившего на путь магии, понадобится сильная воля и немалая стойкость. Пока ты не лишился воли, тебя ждут великие успехи.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Дождитесь, пока Менара Расщепительница Бездны закончит работу над вашим одеянием.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менаре Расщепительнице Бездны в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4787,'Древнее яйцо','В пророчестве Мошару говорится о древнем яйце. Это реликвия тех времен, когда тролли правили громадными империями, и в нем заключена сила, которая сможет сдержать сущность Хаккара. Пожалуй, это единственный способ избавить наш мир от зла.$b$bПринеси мне древнее яйцо, $n. Говорят, оно спрятано в Джинта\'Алоре, что во Внутренних землях, в пещере за амфитеатром в верхней части города.','Принесите древнее яйцо Йе\'кинье в Танарис.','Ты несешь древнее яйцо? Я чувствую, как просыпаются великие силы. Боюсь, время у нас на исходе.','Вернитесь к Йе\'кинье в Порт Хитрой Шестеренки, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древнее яйцо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В пророчестве Мошару говорится о древнем яйце. Это реликвия тех времен, когда тролли правили громадными империями, и в нем заключена сила, которая сможет сдержать сущность Хаккара. Пожалуй, это единственный способ избавить наш мир от зла.$b$bПринеси мне древнее яйцо, $n. Говорят, оно спрятано в Джинта\'Алоре, что во Внутренних землях, в пещере за амфитеатром в верхней части города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите древнее яйцо Йе\'кинье в Танарис.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты несешь древнее яйцо? Я чувствую, как просыпаются великие силы. Боюсь, время у нас на исходе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йе\'кинье в Порт Хитрой Шестеренки, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4788,'Последние таблички','Пока я изучаю третью и четвертую таблички Мошару, отыщи пятую и шестую! Это будет нелегко, потому что они в руках троллей из племени Тлеющего Терновника на Пике Черной горы. Этот пик – огненная гора между Пылающими степями и Тлеющим ущельем.$b$bУдачи, $n. Она тебе понадобится.','Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе.','Невероятно! Ты их $Gнашел:нашела;! Ты настоящий герой, $N!$B$BИ это очень удачно, потому что судя по предыдущим табличкам... без героя нам не обойдтись. Грядет такое...','Ты уже $Gдобрался:добралась; до Черной Скалы? Пятая и шестая таблички у тебя?','Вернитесь к геологу Железному Башмаку в Южные моря, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последние таблички',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока я изучаю третью и четвертую таблички Мошару, отыщи пятую и шестую! Это будет нелегко, потому что они в руках троллей из племени Тлеющего Терновника на Пике Черной горы. Этот пик – огненная гора между Пылающими степями и Тлеющим ущельем.$b$bУдачи, $n. Она тебе понадобится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите пятую и шестую таблички Мошару геологу Железному Башмаку в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно! Ты их $Gнашел:нашела;! Ты настоящий герой, $N!$B$BИ это очень удачно, потому что судя по предыдущим табличкам... без героя нам не обойдтись. Грядет такое...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gдобрался:добралась; до Черной Скалы? Пятая и шестая таблички у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Железному Башмаку в Южные моря, что в Танарисе.',`completedtext_loc8`);
