INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4808,'Фелнок Сталлист','Мне придется попросить тебя еще об одной услуге.$b$bВ результате исследования добытых тобой сущностей, я поняла, как можно заморозить яйца драконов и сохранить их! Мне нужно испытать собственную теорию, но первым делом понадобятся кое-какие приспособления. Мой коллега, Фелнок Сталлист, умеет их делать.$b$bОтнеси это письмо Фелноку и объясни ему, что мне нужно. Фелнок живет в городе Круговзоре, в Зимних Ключах.','Отнесите письмо Тинки Фелноку Сталлисту в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фелнок Сталлист',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне придется попросить тебя еще об одной услуге.$b$bВ результате исследования добытых тобой сущностей, я поняла, как можно заморозить яйца драконов и сохранить их! Мне нужно испытать собственную теорию, но первым делом понадобятся кое-какие приспособления. Мой коллега, Фелнок Сталлист, умеет их делать.$b$bОтнеси это письмо Фелноку и объясни ему, что мне нужно. Фелнок живет в городе Круговзоре, в Зимних Ключах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо Тинки Фелноку Сталлисту в Круговзор, что в Зимних Ключах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4809,'Рога хладнокрылов','У меня есть почти все, что нужно Тинки, не хватает только одного важного компонента – рогов хладнокрылов. Рога этих химер – великолепный источник стужи, но годятся только безупречные рога без единой трещинки! Чтобы выполнить заказ Тинки мне нужно несколько таких рогов.$b$bДобудь их, и я соберу посылку для Тинки.','Добудьте 8 безупречных рогов хладнокрыла.','Вернитесь к Фелноку Сталлисту в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рога хладнокрылов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть почти все, что нужно Тинки, не хватает только одного важного компонента – рогов хладнокрылов. Рога этих химер – великолепный источник стужи, но годятся только безупречные рога без единой трещинки! Чтобы выполнить заказ Тинки мне нужно несколько таких рогов.$b$bДобудь их, и я соберу посылку для Тинки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 безупречных рогов хладнокрыла.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фелноку Сталлисту в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4810,'Возвращение к Тинки','Ну вот, все готово и запаковано! Доброго пути, не забудь передать Тинки, что она мой должник!','Отнесите ящик Фелнока Тинки Кипеллер в Пылающие степи. Ее можно найти возле Пламенеющего Стяга.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Тинки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, все готово и запаковано! Доброго пути, не забудь передать Тинки, что она мой должник!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик Фелнока Тинки Кипеллер в Пылающие степи. Ее можно найти возле Пламенеющего Стяга.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (4811,'Красный кристалл','К востоку отсюда становится все больше враждебно настроенных лунных совухов. Когда-то их считали милыми и спокойными, почти мистическими созданиями. В то время как кое-кто продолжает почитать их, тревога о безопасности Аубердина вынуждает меня смотреть на вещи более реалистично.$B$BЯ получила сообщения, что лунных совухов привлекает большой красный кристалл, находящийся в горной гряде на востоке Темных берегов. Никто не только не знает, что это за кристалл, но есть ли он на самом деле. Я хочу, чтобы вы установили его местонахождение и доложили мне о том, что обнаружите.','Направляйтесь на восток от Аубердина и поищите большой красный кристалл в горной гряде на востоке Темных берегов. Вернитесь с докладом к часовому Глинде Нал\'Шие в Аубердин.','Что вы можете сказать о том красном кристалле? Он действительно существует?','Найти большой красный кристалл на восточном хребте Темных берегов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Красный кристалл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К востоку отсюда становится все больше враждебно настроенных лунных совухов. Когда-то их считали милыми и спокойными, почти мистическими созданиями. В то время как кое-кто продолжает почитать их, тревога о безопасности Аубердина вынуждает меня смотреть на вещи более реалистично.$B$BЯ получила сообщения, что лунных совухов привлекает большой красный кристалл, находящийся в горной гряде на востоке Темных берегов. Никто не только не знает, что это за кристалл, но есть ли он на самом деле. Я хочу, чтобы вы установили его местонахождение и доложили мне о том, что обнаружите.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Направляйтесь на восток от Аубердина и поищите большой красный кристалл в горной гряде на востоке Темных берегов. Вернитесь с докладом к часовому Глинде Нал\'Шие в Аубердин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что вы можете сказать о том красном кристалле? Он действительно существует?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найти большой красный кристалл на восточном хребте Темных берегов',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4812,'Пока струится вода...','Возьмите эту пустую колбу и наполните ее водой из лунного колодца в Аубердине. Ее могучая магия должна помочь нам разгадать структуру кристалла. Чтобы это сделать, просто облейте кристалл, а остальное должно произойти само собой.$B$BХотя я не думаю, чтобы вам что-то угрожало, я все же попрошу вас быть осторожнее. За горами на востоке находится Оскверненный лес, и если этот кристалл как-то связан с тем местом (как я подозреваю), он может оказаться очень опасным.','Наполните пустую колбу для воды в Лунном колодце Аубердина, а затем исследуйте красный кристалл, находящийся в горной гряде на востоке Темных берегов.','Вы снова добрались до таинственного кристалла. Откупорив флакон с водой лунного колодца, вы аккуратно выливаете его содержимое на верхушку кристалла. Пока вода струится по его граням, вы видете, как непроглядная поверхность кристалла становится прозрачной...','На фоне лесного пейзажа Темного Берега кристалл выглядит совершенно чужеродным. Вам кажется, что откуда-то изнутри кристалла до вас доносится чуть слышное жужжание.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пока струится вода...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьмите эту пустую колбу и наполните ее водой из лунного колодца в Аубердине. Ее могучая магия должна помочь нам разгадать структуру кристалла. Чтобы это сделать, просто облейте кристалл, а остальное должно произойти само собой.$B$BХотя я не думаю, чтобы вам что-то угрожало, я все же попрошу вас быть осторожнее. За горами на востоке находится Оскверненный лес, и если этот кристалл как-то связан с тем местом (как я подозреваю), он может оказаться очень опасным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните пустую колбу для воды в Лунном колодце Аубердина, а затем исследуйте красный кристалл, находящийся в горной гряде на востоке Темных берегов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы снова добрались до таинственного кристалла. Откупорив флакон с водой лунного колодца, вы аккуратно выливаете его содержимое на верхушку кристалла. Пока вода струится по его граням, вы видете, как непроглядная поверхность кристалла становится прозрачной...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На фоне лесного пейзажа Темного Берега кристалл выглядит совершенно чужеродным. Вам кажется, что откуда-то изнутри кристалла до вас доносится чуть слышное жужжание.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4813,'Скрытые фрагменты','С помощью воды Лунного колодца выяснилось, что в кристалле заключено несколько мелких фрагментов костей, а также половина челюсти. Кажется, челюсть принадлежала гуманоиду, но точно нельзя сказать, не разбив кристалл, – а это даже для самой мощной магии может оказаться почти непосильной задачей.$B$BЗадание выполнено, и все, что вам остается, – это вернуться в Аубердин и доложить обо всем часовому Глинде Нал\'Шие.','Доложите о результатах ваших изысканий часовому Глинде Нал\'Шие в Аубердине.','Да, похоже, что, хотя мы и знаем теперь о кристалле больше, в результате возникло множество новых вопросов.$B$BЯ пойду с добытой вами информацией в совет Аубердина. Может быть, они подскажут, что делать дальше с этим кристаллом. Если вообще есть о чем говорить – пока что угроза слишком далеко на востоке, чтобы принимаеть ее всерьез.$B$BЧто же касается вас, возьмите это. Считайте это наградой за хорошо проделанную работу, $n.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скрытые фрагменты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С помощью воды Лунного колодца выяснилось, что в кристалле заключено несколько мелких фрагментов костей, а также половина челюсти. Кажется, челюсть принадлежала гуманоиду, но точно нельзя сказать, не разбив кристалл, – а это даже для самой мощной магии может оказаться почти непосильной задачей.$B$BЗадание выполнено, и все, что вам остается, – это вернуться в Аубердин и доложить обо всем часовому Глинде Нал\'Шие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о результатах ваших изысканий часовому Глинде Нал\'Шие в Аубердине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, похоже, что, хотя мы и знаем теперь о кристалле больше, в результате возникло множество новых вопросов.$B$BЯ пойду с добытой вами информацией в совет Аубердина. Может быть, они подскажут, что делать дальше с этим кристаллом. Если вообще есть о чем говорить – пока что угроза слишком далеко на востоке, чтобы принимаеть ее всерьез.$B$BЧто же касается вас, возьмите это. Считайте это наградой за хорошо проделанную работу, $n.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4821,'Странное яйцо','Ходят слухи, что здесь, в Тысяче Игл, появилось яйцо какого-то странного существа. Но те, кто видел его, не смогли подойти достаточно близко и рассмотреть яйцо поподробнее. Его охраняют змеи, да так, словно это яйцо – их собственное!$B$BЯ хочу, чтобы вы нашли его и принесли мне для изучения. Говорят, что оно находится в логове змеев, но вообще-то таких гнезд несколько, они разбросаны вдоль стен каньона к югу и северо-востоку от заставы.','Принесите странное яйцо Хагару Грозовому Копыту на Заставу Вольного Ветра.','Наконец-то я получил это таинственное яйцо... Дайте-ка взглянуть на него... Что... что это?!','Мне нужно узнать побольше об этом таинственном яйце. Кто знает, что может из него вылупиться...','Вернитесь к Хагару Грозовому Копыту на Заставу Вольного Ветра, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странное яйцо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, что здесь, в Тысяче Игл, появилось яйцо какого-то странного существа. Но те, кто видел его, не смогли подойти достаточно близко и рассмотреть яйцо поподробнее. Его охраняют змеи, да так, словно это яйцо – их собственное!$B$BЯ хочу, чтобы вы нашли его и принесли мне для изучения. Говорят, что оно находится в логове змеев, но вообще-то таких гнезд несколько, они разбросаны вдоль стен каньона к югу и северо-востоку от заставы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите странное яйцо Хагару Грозовому Копыту на Заставу Вольного Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то я получил это таинственное яйцо... Дайте-ка взглянуть на него... Что... что это?!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно узнать побольше об этом таинственном яйце. Кто знает, что может из него вылупиться...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хагару Грозовому Копыту на Заставу Вольного Ветра, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4822,'Детям – мороженое!','МОРОЖЕНОЕ! Пожалуйста, пожалуйста, пожалуйста, купи мне немного мороженого!!! Я больше всего люблю клубничное, а самое вкусное клубничное мороженое делают Тигуль и Форор! Это мое самое любимое мороженое на свете!$b$bЯ пробовал его только один раз, когда меня водили на гонки на Мерцающей равнине, но говорят, его сейчас продают у нас в городе! Пожалуйста! Пожалуйста-препожалуйста! Преогромное пожалуйста!!!!','Купите своему подопечному клубничное мороженое. Кажется, мальчик предпочитает мороженое Тигуля и Форора.','У них наверное много и других вкусов, кроме клубники, но клубничное мое любимое!','Вернитесь к своему подопечному ребенку-сироте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Детям – мороженое!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','МОРОЖЕНОЕ! Пожалуйста, пожалуйста, пожалуйста, купи мне немного мороженого!!! Я больше всего люблю клубничное, а самое вкусное клубничное мороженое делают Тигуль и Форор! Это мое самое любимое мороженое на свете!$b$bЯ пробовал его только один раз, когда меня водили на гонки на Мерцающей равнине, но говорят, его сейчас продают у нас в городе! Пожалуйста! Пожалуйста-препожалуйста! Преогромное пожалуйста!!!!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите своему подопечному клубничное мороженое. Кажется, мальчик предпочитает мороженое Тигуля и Форора.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У них наверное много и других вкусов, кроме клубники, но клубничное мое любимое!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к своему подопечному ребенку-сироте.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4841,'Упокоение кентавров','$n, я поручаю вам охоту на этих кентавров. Отомстите им за нас как следует – вырежьте весь их лагерь к северу от Заставы Вольного Ветра. Пусть рука ваша будет тверда!','Убейте 12 разведчиков, 10 пастухов и 6 ветроловок из племени Галак, после чего вернитесь к дозорному утесов Долгорогу на Заставу Вольного Ветра.','$N, вы убили слишком мало кентавров! Продолжайте охоту, а уж я в долгу не останусь.','Вернитесь к дозорному утесов Долгорогу на Заставу Вольного Ветра, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упокоение кентавров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я поручаю вам охоту на этих кентавров. Отомстите им за нас как следует – вырежьте весь их лагерь к северу от Заставы Вольного Ветра. Пусть рука ваша будет тверда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 разведчиков, 10 пастухов и 6 ветроловок из племени Галак, после чего вернитесь к дозорному утесов Долгорогу на Заставу Вольного Ветра.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, вы убили слишком мало кентавров! Продолжайте охоту, а уж я в долгу не останусь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному утесов Долгорогу на Заставу Вольного Ветра, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4842,'Выяснение причин','По правде говоря, хотя в Зимних Ключах вулканов нет, я думаю, для возникновения этих горячих источников есть не менее опасные причины...$b$bВпрочем, наверное, ты $gсам:сама; захочешь все увидеть. Тебе нужно будет пересечь все Зимние Ключи, до самого юга этого края. Там, где воздух станет плотным и удушливым, а небо потемнеет, ты как раз и найдешь то, что я считаю причиной возникновения горячих ключей.$b$bСходи взглянуть. Я уверена, ты вернешься с кучей вопросов.','Последуйте указаниям Доновы Снегоноры, а затем вернитесь к ней.','Да, демоны добрались до Теснины Зловещего Шепота. Я уверена, мы наблюдаем следы их присутствия. И я собираюсь и дальше наблюдать на горячими ключами, чтобы узнать о них больше.$B$BЯ немного подожду, чтобы ты $Gнабрался:набралась; сил, а потом снова привлеку тебя к исследованию Теснины Зловещего Шепота.','У воды в ключах очень странные свойства...я по-прежнему не очень понимаю, что все это значит…','Отыщите Теснину Зловещего Шепота.','Вернитесь к Донове Снегоноре в Зимние Ключи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выяснение причин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По правде говоря, хотя в Зимних Ключах вулканов нет, я думаю, для возникновения этих горячих источников есть не менее опасные причины...$b$bВпрочем, наверное, ты $gсам:сама; захочешь все увидеть. Тебе нужно будет пересечь все Зимние Ключи, до самого юга этого края. Там, где воздух станет плотным и удушливым, а небо потемнеет, ты как раз и найдешь то, что я считаю причиной возникновения горячих ключей.$b$bСходи взглянуть. Я уверена, ты вернешься с кучей вопросов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Последуйте указаниям Доновы Снегоноры, а затем вернитесь к ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, демоны добрались до Теснины Зловещего Шепота. Я уверена, мы наблюдаем следы их присутствия. И я собираюсь и дальше наблюдать на горячими ключами, чтобы узнать о них больше.$B$BЯ немного подожду, чтобы ты $Gнабрался:набралась; сил, а потом снова привлеку тебя к исследованию Теснины Зловещего Шепота.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У воды в ключах очень странные свойства...я по-прежнему не очень понимаю, что все это значит…',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отыщите Теснину Зловещего Шепота.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Донове Снегоноре в Зимние Ключи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4861,'Разъяренные дикие совухи','Эй, послушай, $gпаренек:девчушка;! Меня какие-то кровожадные дикие совухи гнали всю дорогу из моего лагеря! Подозреваю, я слишком близко подобрался к разгадке того, что же они там охраняют. $b$bЯ еле ноги унес оттуда. Боюсь, мой коллега оказался менее везучим. Ты как, не против того, чтобы бросить вызов диким совухам и отправиться в мой лагерь? Очень уж дороги мне мои припасы, а также я хотел бы вернуть амулет, который извлек вчера во время раскопок.','Найдите разоренный лагерь Джерона Гранильщика и его припасы на юге Зимних Ключей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разъяренные дикие совухи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, послушай, $gпаренек:девчушка;! Меня какие-то кровожадные дикие совухи гнали всю дорогу из моего лагеря! Подозреваю, я слишком близко подобрался к разгадке того, что же они там охраняют. $b$bЯ еле ноги унес оттуда. Боюсь, мой коллега оказался менее везучим. Ты как, не против того, чтобы бросить вызов диким совухам и отправиться в мой лагерь? Очень уж дороги мне мои припасы, а также я хотел бы вернуть амулет, который извлек вчера во время раскопок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите разоренный лагерь Джерона Гранильщика и его припасы на юге Зимних Ключей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4862,'Товар на любителя','Верь – не верь, но есть народ, который готов отлично заплатить за необычную зверушку, причем чем она злее, тем лучше!$b$bЯ послал на Пик Черной горы Блестяшку, чтобы собрать паучьи яйца, но она уже несколько недель не возвращается. Может, ты придешь ей на выручку?$b$bВот что, $n. Ступай-ка туда и принеси мне паучьи яйца. Я тебе не только хорошо заплачу, но еще и приручу для тебя одного паучка!','Отправьтесь на Пик Черной горы и принесите Киблеру 15 яиц скального паука.$b$bСудя по всему, яйца надо искать недалеко от пауков.','Какой урожай! Что за яйца! Они принесут мне несколько хорошеньких золотых монеток.\n\nКак и обещано, вот тебе зверушка. Смотри, чтобы она тебя не цапнула!','У тебя в сумке лежат паучьи яйца или ты так, поболтать, зашла?','Вернитесь к Киблеру в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Товар на любителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верь – не верь, но есть народ, который готов отлично заплатить за необычную зверушку, причем чем она злее, тем лучше!$b$bЯ послал на Пик Черной горы Блестяшку, чтобы собрать паучьи яйца, но она уже несколько недель не возвращается. Может, ты придешь ей на выручку?$b$bВот что, $n. Ступай-ка туда и принеси мне паучьи яйца. Я тебе не только хорошо заплачу, но еще и приручу для тебя одного паучка!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь на Пик Черной горы и принесите Киблеру 15 яиц скального паука.$b$bСудя по всему, яйца надо искать недалеко от пауков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой урожай! Что за яйца! Они принесут мне несколько хорошеньких золотых монеток.\n\nКак и обещано, вот тебе зверушка. Смотри, чтобы она тебя не цапнула!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя в сумке лежат паучьи яйца или ты так, поболтать, зашла?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киблеру в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4863,'Разъяренные дикие совухи','Вы озираетесь, но видите ничего такого, чтобы могло понадобиться Джерону. Но заметно, что найденный вами ящик был вскрыт силой, как будто тут не обошлось без диких совухов...$B$BВзглянув на восток, вы замечаете покинутый фургон. Стоит посмотреть не осталось ли там каких-то вещей Джерона.','Найдите опрокинутый фургон Джерона Гранильщика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разъяренные дикие совухи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы озираетесь, но видите ничего такого, чтобы могло понадобиться Джерону. Но заметно, что найденный вами ящик был вскрыт силой, как будто тут не обошлось без диких совухов...$B$BВзглянув на восток, вы замечаете покинутый фургон. Стоит посмотреть не осталось ли там каких-то вещей Джерона.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите опрокинутый фургон Джерона Гранильщика.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4864,'Разъяренные дикие совухи','Изучив содержимое ящика, вы решаете, что Джарону могут пригодиться лежащие там инструменты. Однако среди них нет и следа амулета.$b$bПохоже, дикие совухи обитают к северу и к востоку отсюда, и вы решаете, что ваш следующий шаг – встретить этих существ лицом к лицу и забрать у них амулет.','Подберите Припасы Джерона из снега, и найдите дикого совуха, похитившего амулет, о котором говорил Джерон.$b$bПринесите Припасы и Ожерелье Синих перьев Джерону Гранильщику в его дом в Зимних Ключах.','Вернитесь к Джерону Гранильщику в Деревню Звездопада, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разъяренные дикие совухи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изучив содержимое ящика, вы решаете, что Джарону могут пригодиться лежащие там инструменты. Однако среди них нет и следа амулета.$b$bПохоже, дикие совухи обитают к северу и к востоку отсюда, и вы решаете, что ваш следующий шаг – встретить этих существ лицом к лицу и забрать у них амулет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подберите Припасы Джерона из снега, и найдите дикого совуха, похитившего амулет, о котором говорил Джерон.$b$bПринесите Припасы и Ожерелье Синих перьев Джерону Гранильщику в его дом в Зимних Ключах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джерону Гранильщику в Деревню Звездопада, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4865,'Змеиная дикость','Если бы я не видел это собственными глазами, то ни за что бы не поверил! Месть обрушилась на Тысячу Игл!$B$B*Хагар утирает лоб.*$B$B$n, надо действовать быстро! Скорее, иди и поговори с Мотегой Огненной Гривой, он на заставе Белого Плеса, это к северо-западу отсюда, прямо возле дороги. Он подскажет нам, что делать!','Расскажите о найденном Мотеге Огненной Гриве на Заставе Белого Плеса, что в Тысяче Игл.','Отмщение! Значит, легенда об Арикаре не врет! Да, эту проблему следует разрешить немедленно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Змеиная дикость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если бы я не видел это собственными глазами, то ни за что бы не поверил! Месть обрушилась на Тысячу Игл!$B$B*Хагар утирает лоб.*$B$B$n, надо действовать быстро! Скорее, иди и поговори с Мотегой Огненной Гривой, он на заставе Белого Плеса, это к северо-западу отсюда, прямо возле дороги. Он подскажет нам, что делать!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расскажите о найденном Мотеге Огненной Гриве на Заставе Белого Плеса, что в Тысяче Игл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отмщение! Значит, легенда об Арикаре не врет! Да, эту проблему следует разрешить немедленно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4866,'Материнское молоко','Должно быть, это один из сильнейших ядов на свете!$b$bВо время одной из вылазок на Пик Черной горы я слышал, как орки говорят о его смертоносности. Они называют его "материнское молоко" в честь Дымной Паутины, огромной паучихи, поселившейся в одной из пещер Лабиринта.$b$bИ вот что мне нужно от тебя: образец молока из твоих собственных вен. Ядовитая железа не подойдет! Поэтому дай ей отравить себя, а потом возвращайся!$b$bА я тебя... подою!$b$B<Потирает руки в нетерпении.>','Найдите в самом сердце Пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд.','Из этого выйдет потрясный эль!$B$BА ты что $Gдумал:думала;? Что я сделаю яд или что-то такое?$B$BНу, дети пошли...','<Джон-Оборванец щипает вас.>','Вас подоили','Вернитесь к Джону-Оборванцу в Пламенеющий Стяг, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Материнское молоко',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, это один из сильнейших ядов на свете!$b$bВо время одной из вылазок на Пик Черной горы я слышал, как орки говорят о его смертоносности. Они называют его "материнское молоко" в честь Дымной Паутины, огромной паучихи, поселившейся в одной из пещер Лабиринта.$b$bИ вот что мне нужно от тебя: образец молока из твоих собственных вен. Ядовитая железа не подойдет! Поэтому дай ей отравить себя, а потом возвращайся!$b$bА я тебя... подою!$b$B<Потирает руки в нетерпении.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в самом сердце Пика Черной горы мать Дымную Паутину. Сражайтесь с ней, пока она не введет вам свой яд. Скорее всего ее также придется убить. Когда яд будет в вас, вернитесь к Джону-Оборванцу, чтобы он смог добыть яд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Из этого выйдет потрясный эль!$B$BА ты что $Gдумал:думала;? Что я сделаю яд или что-то такое?$B$BНу, дети пошли...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Джон-Оборванец щипает вас.>',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Вас подоили',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джону-Оборванцу в Пламенеющий Стяг, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4867,'Аррок Смертный Вопль','Ар-рх! Трудно говорить!$B$BВозьми эту записку! Принеси мне мой амулет!','Прочитайте записку Вароша. Принесите Варошу его амулет.','Я уже чувствую, как ко мне возвращаются силы! И проклятие Аррока уже не разрушает мой разум.$B$BСпасибо, $N! Я не люблю быть кому-то обязанным, но должен признать: ты мне очень $Gпомог:помогла;.$B$BЖелаю удачи в походе на Пик Черной горы. Это безрассудство, если ты думаешь, что сможешь дойти до вершины, хотя твоя смелость поистине не знает границ.','А, вот и ты! Ты $Gпринес:принесла; мой амулет?','Return to Warosh at Blackrock Spire in Blackrock Mountain.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аррок Смертный Вопль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ар-рх! Трудно говорить!$B$BВозьми эту записку! Принеси мне мой амулет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочитайте записку Вароша. Принесите Варошу его амулет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уже чувствую, как ко мне возвращаются силы! И проклятие Аррока уже не разрушает мой разум.$B$BСпасибо, $N! Я не люблю быть кому-то обязанным, но должен признать: ты мне очень $Gпомог:помогла;.$B$BЖелаю удачи в походе на Пик Черной горы. Это безрассудство, если ты думаешь, что сможешь дойти до вершины, хотя твоя смелость поистине не знает границ.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, вот и ты! Ты $Gпринес:принесла; мой амулет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Warosh at Blackrock Spire in Blackrock Mountain.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4881,'Убийственный заговор','Таурен по имени Канати Серое Облако собрался разбить в Тысяче Игл охотничий лагерь. Мы должны убить его и опустошить лагерь, уничтожив всех его сторонников. Собираемся на маленькой заставе к юго-западу от Великого подъемника.','Предупредите Канати Серое Облако на заставе Белого Плеса, что на него готовится покушение.','Они хотят меня убить? Пусть приходят, я покажу им, как дерутся таурены!','Прямо из Кабестана, свеженькие лезвия для пил Песни Войны! Да, они у меня с собой.\n\n..Но чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!\n\nЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защищать себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.\n\nИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убийственный заговор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Таурен по имени Канати Серое Облако собрался разбить в Тысяче Игл охотничий лагерь. Мы должны убить его и опустошить лагерь, уничтожив всех его сторонников. Собираемся на маленькой заставе к юго-западу от Великого подъемника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предупредите Канати Серое Облако на заставе Белого Плеса, что на него готовится покушение.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они хотят меня убить? Пусть приходят, я покажу им, как дерутся таурены!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прямо из Кабестана, свеженькие лезвия для пил Песни Войны! Да, они у меня с собой.\n\n..Но чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!\n\nЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защищать себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.\n\nИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4882,'Умение хранить секреты','Вы не можете понять, важна ли ваша находка – ожерелье, упавшее с шеи недавно убитого дикого совуха. Оно источает яркий пульсирующий свет.$b$bМожет быть, Трулл Баловень Судьбы сможет что-то рассказать – похоже, он очень много знает о диких совухах. Возможно, стоит его расспросить об этом ожерелье?','Отнесите ожерелье синих перьев Труллу Баловню Судьбы на Заставу Отравленной Крови.','Важная находка?','Хотите еще о чем-то сообщить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Умение хранить секреты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы не можете понять, важна ли ваша находка – ожерелье, упавшее с шеи недавно убитого дикого совуха. Оно источает яркий пульсирующий свет.$b$bМожет быть, Трулл Баловень Судьбы сможет что-то рассказать – похоже, он очень много знает о диких совухах. Возможно, стоит его расспросить об этом ожерелье?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ожерелье синих перьев Труллу Баловню Судьбы на Заставу Отравленной Крови.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Важная находка?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хотите еще о чем-то сообщить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4883,'Умение хранить секреты','Хотя я располагаю некоторыми сведениями о совухах, с которыми ты $gборолся:боролась; в Зимних Ключах, однако об их магии мне ничего не известно. Но я знаю кое-кого, кто с удовольствием изучит это ожерелье и скорее всего сумеет рассказать тебе о его свойствах.$B$BНара Буйногривая из Громового Утеса настоящий эксперт в подобных вещах, тебе стоит поговорить с ней. Удачи, $n!','Отнесите ожерелье синих перьев Наре Буйногривой.','Полагаю, у энергии этого ожерелья лишь один источник, $N.$B$B<Нара закрывает глаза и замолкает на мгновение.>$B$BДикосовухи, обманутые и испуганные существа, не всегда были такими. Они были созданы для того чтобы служить ночным эльфам. Богиня ночных эльфов Элуна сотворила их, чтобы охранять священные места.$B$BКонечно, это кажется неважным, однако я призываю тебя взглянуть глубже.$B$BВ свое время ты поймешь. Спасибо, что $Gпринес:принесла; мне это ожерелье, $N.','Чем я могу помочь тебе, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Умение хранить секреты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя я располагаю некоторыми сведениями о совухах, с которыми ты $gборолся:боролась; в Зимних Ключах, однако об их магии мне ничего не известно. Но я знаю кое-кого, кто с удовольствием изучит это ожерелье и скорее всего сумеет рассказать тебе о его свойствах.$B$BНара Буйногривая из Громового Утеса настоящий эксперт в подобных вещах, тебе стоит поговорить с ней. Удачи, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ожерелье синих перьев Наре Буйногривой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Полагаю, у энергии этого ожерелья лишь один источник, $N.$B$B<Нара закрывает глаза и замолкает на мгновение.>$B$BДикосовухи, обманутые и испуганные существа, не всегда были такими. Они были созданы для того чтобы служить ночным эльфам. Богиня ночных эльфов Элуна сотворила их, чтобы охранять священные места.$B$BКонечно, это кажется неважным, однако я призываю тебя взглянуть глубже.$B$BВ свое время ты поймешь. Спасибо, что $Gпринес:принесла; мне это ожерелье, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем я могу помочь тебе, $N?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4901,'Стражи алтаря','На самой вершине гребня находится, как я полагаю, алтарь богини Элуны. Насколько я знаю, нам нужно зажечь пять факелов – в каждой пещере, и тогда мы получим доступ к алтарю.$b$bЯ расшифровала заклинания, вырезанных на камне в древних руинах Кел\'Терила, которые, как я думаю, являются ключом к активации алтаря. Помогите мне зажечь факелы, пока я буду читать заклинание.$b$bЕсли у нас все получится, вы сможете доложить Эреласу о результатах!','Защитите Раншаллу, пока она пытается активировать алтарь Элуны. Сообщите о ваших находках Эреласу Янтарному Небу в деревне Рут\'теран.','Раскройте секрет алтаря Элуны.','Вернитесь к Эреласу Янтарному Небу в деревню Рут\'теран, что в Тельдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стражи алтаря',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На самой вершине гребня находится, как я полагаю, алтарь богини Элуны. Насколько я знаю, нам нужно зажечь пять факелов – в каждой пещере, и тогда мы получим доступ к алтарю.$b$bЯ расшифровала заклинания, вырезанных на камне в древних руинах Кел\'Терила, которые, как я думаю, являются ключом к активации алтаря. Помогите мне зажечь факелы, пока я буду читать заклинание.$b$bЕсли у нас все получится, вы сможете доложить Эреласу о результатах!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите Раншаллу, пока она пытается активировать алтарь Элуны. Сообщите о ваших находках Эреласу Янтарному Небу в деревне Рут\'теран.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Раскройте секрет алтаря Элуны.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эреласу Янтарному Небу в деревню Рут\'теран, что в Тельдрассиле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4902,'Питомцы Элуны','Это поразительно!$b$bМне всегда было интересно, какова же истина... Что ж, вы просто обязаны поделиться этими сведениями! Сразу же отправляйтесь к верховному друиду Фэндралу Оленьему Шлему – вы найдете его в Дарнасе, в Круге Кенария. Расскажите ему подробно о случившемся – так же, как рассказали мне. Я уверен, что ему будет очень интересно!$b$bЭто важная информация, $n!','Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Питомцы Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это поразительно!$b$bМне всегда было интересно, какова же истина... Что ж, вы просто обязаны поделиться этими сведениями! Сразу же отправляйтесь к верховному друиду Фэндралу Оленьему Шлему – вы найдете его в Дарнасе, в Круге Кенария. Расскажите ему подробно о случившемся – так же, как рассказали мне. Я уверен, что ему будет очень интересно!$b$bЭто важная информация, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4903,'Приказ полководца','По приказу полководца Клинозуба следующие жители Пика Черной горы подлежат уничтожению: $B$BОсобо опасный преступник вождь Омокк. $B$BЖестокий и беспощадный тролль воевода Вун.$B$BПовелитель Змейталак, десятник в малом городе.$B$BТакже необходимо доставить в штаб все найденные при них документы. $B$BУспех – слава и награда.$B$BПоражение – позор и забвенье.','Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат.','<Зеленые щеки полководца на минуту покрываются мертвенной бледностью.>','<Полководец Клинозуб приветствует вас.>','Вернитесь к полководцу Клинозубу в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ полководца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По приказу полководца Клинозуба следующие жители Пика Черной горы подлежат уничтожению: $B$BОсобо опасный преступник вождь Омокк. $B$BЖестокий и беспощадный тролль воевода Вун.$B$BПовелитель Змейталак, десятник в малом городе.$B$BТакже необходимо доставить в штаб все найденные при них документы. $B$BУспех – слава и награда.$B$BПоражение – позор и забвенье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вождя Омокка, воеводу Вуна и повелителя Змейталака. Найденные при них важные бумаги Черной горы доставьте полководцу Клинозубу в Каргат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Зеленые щеки полководца на минуту покрываются мертвенной бледностью.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Полководец Клинозуб приветствует вас.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к полководцу Клинозубу в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4904,'Долгожданная свобода','Арнак хотел жениться на мне, и поэтому похитил меня, когда я отвергла его предложение. Мой брат пытался остановить его, но Арнак оказался сильнее. Он... он убил моего брата и привел меня сюда. Мой бедный брат...$B$B$n, не могли бы вы вывести меня с Пика Темного Облака? Я хочу назад, к Талье! Она, наверное, с ума сходит от беспокойства.','Выведите Лакоту Песню Ветра с Пика Темного Облака, а потом поговорите с Талией Янтарной Шкурой на Заставе Вольного Ветра.','Вы выяснили, что задумал клан Зловещего Тотема?','Выведите Лакоту Песню Ветра с Пика Темного Облака.','Вернитесь к Талии Янтарной Шкуре на Заставу Вольного Ветра, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долгожданная свобода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Арнак хотел жениться на мне, и поэтому похитил меня, когда я отвергла его предложение. Мой брат пытался остановить его, но Арнак оказался сильнее. Он... он убил моего брата и привел меня сюда. Мой бедный брат...$B$B$n, не могли бы вы вывести меня с Пика Темного Облака? Я хочу назад, к Талье! Она, наверное, с ума сходит от беспокойства.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выведите Лакоту Песню Ветра с Пика Темного Облака, а потом поговорите с Талией Янтарной Шкурой на Заставе Вольного Ветра.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы выяснили, что задумал клан Зловещего Тотема?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Выведите Лакоту Песню Ветра с Пика Темного Облака.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талии Янтарной Шкуре на Заставу Вольного Ветра, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4905,'<UNUSED>','Defend Kanati Greycloud against the Centaur Assassins.','Defend Kanati Greycloud') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Defend Kanati Greycloud against the Centaur Assassins.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Defend Kanati Greycloud',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4906,'Снова порча!','Другой лагерь сатиров угрожает северной части Оскверненного леса. Тамошними сатирами предводительствует жестокий Ксаварик. Эти подлые предатели и обманщики радуются, поражая порчей тварей Оскверненного леса.$B$BКсаватрас и его приспешники – только часть большого плана по созданию оскверненного лунного колодца. А затем всем этим воспользуется Ксаварик.$B$BТеперь, когда Ксаватрас уже не мешается у нас под ногами, заверши это дело, $n. Отправляйся на север и срази Ксаварика.','Эридана Грусть Ветра из Оскверненного леса просит вас убить 8 призывателей огня, 8 предателей и 8 плутов из племени Нефритового Пламени, а также Ксаварика. По выполнении задания возвращайтесь к Эридане.','Вернитесь к Эридане Грусти Ветра в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снова порча!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Другой лагерь сатиров угрожает северной части Оскверненного леса. Тамошними сатирами предводительствует жестокий Ксаварик. Эти подлые предатели и обманщики радуются, поражая порчей тварей Оскверненного леса.$B$BКсаватрас и его приспешники – только часть большого плана по созданию оскверненного лунного колодца. А затем всем этим воспользуется Ксаварик.$B$BТеперь, когда Ксаватрас уже не мешается у нас под ногами, заверши это дело, $n. Отправляйся на север и срази Ксаварика.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Эридана Грусть Ветра из Оскверненного леса просит вас убить 8 призывателей огня, 8 предателей и 8 плутов из племени Нефритового Пламени, а также Ксаварика. По выполнении задания возвращайтесь к Эридане.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эридане Грусти Ветра в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4907,'Тинки Кипеллер','Привет, $n. Помнишь Тинки Кипеллер? Она-то тебя помнит! Она послала мне весточку, чтобы я передал тебе при случае. Ей снова нужна твоя помощь. Кажется, это опять связано с изучением драконов.$b$bСтупай в Пылающие степи, в Пламенеющий Стяг, и поговори с ней.','Поговорите с Тинки Кипеллер. Ее можно найти возле Пламенеющего Стяга в Пылающих степях.','Фелнок не ошибся! Мне снова нужна твоя помощь, и на сей раз... задание будет опасным.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тинки Кипеллер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $n. Помнишь Тинки Кипеллер? Она-то тебя помнит! Она послала мне весточку, чтобы я передал тебе при случае. Ей снова нужна твоя помощь. Кажется, это опять связано с изучением драконов.$b$bСтупай в Пылающие степи, в Пламенеющий Стяг, и поговори с ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тинки Кипеллер. Ее можно найти возле Пламенеющего Стяга в Пылающих степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фелнок не ошибся! Мне снова нужна твоя помощь, и на сей раз... задание будет опасным.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4921,'Пропавшая без вести','Мы бились в маленьком лагере тауренов и разделились в бою – на нее наседали разом трое дыбогривов. Силы были неравны. Я отвлек на себя очень многих и увидел, что набежали новые враги и одолевают ее. Впав в ярость, я бросился на врагов, но они с легкостью одержали надо мной верх.$B$BЯ пришел в себя и увидел, что таурен-друид ухаживает за мной, – он набрел на меня на Золотом пути.$B$BПрошу тебя, |3-6($c), узнай что-нибудь о моей жене.','Отыщите жену Манкрика и возвращайтесь к нему в Перекресток.','Понятно. Спасибо, |3-6($C).') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшая без вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы бились в маленьком лагере тауренов и разделились в бою – на нее наседали разом трое дыбогривов. Силы были неравны. Я отвлек на себя очень многих и увидел, что набежали новые враги и одолевают ее. Впав в ярость, я бросился на врагов, но они с легкостью одержали надо мной верх.$B$BЯ пришел в себя и увидел, что таурен-друид ухаживает за мной, – он набрел на меня на Золотом пути.$B$BПрошу тебя, |3-6($c), узнай что-нибудь о моей жене.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите жену Манкрика и возвращайтесь к нему в Перекресток.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Понятно. Спасибо, |3-6($C).',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4941,'Мудрость Эйтригга','Ренд жив? $B$BБыть того не может! Я думал, он погиб несколько десятков лет назад. $B$BТебе нужно обратиться за советом к Эйтриггу, $n! Никто не знает о Черной горе больше него, и если то, что написано здесь, правда, Эйтриггу стоит об этом знать. Никому нельзя отказывать в праве на месть. $B$BКогда поговоришь с Эйтриггом, ступай к вождю за указаниями.','Поговорите с Эйтриггом в Оргриммаре. После этого обратитесь к вождю Траллу. $B$BВ последний раз Эйтригг был в зале приемов Тралла.','<Тралл, похоже, весьма встревожен услышанным.>','Ты не видишь, что я занят?','Совет с Эйтриггом','Вернитесь к Траллу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мудрость Эйтригга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ренд жив? $B$BБыть того не может! Я думал, он погиб несколько десятков лет назад. $B$BТебе нужно обратиться за советом к Эйтриггу, $n! Никто не знает о Черной горе больше него, и если то, что написано здесь, правда, Эйтриггу стоит об этом знать. Никому нельзя отказывать в праве на месть. $B$BКогда поговоришь с Эйтриггом, ступай к вождю за указаниями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эйтриггом в Оргриммаре. После этого обратитесь к вождю Траллу. $B$BВ последний раз Эйтригг был в зале приемов Тралла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тралл, похоже, весьма встревожен услышанным.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты не видишь, что я занят?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Совет с Эйтриггом',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4961,'Очищение шара Орахила','А, сфера призывателя – так вот откуда исходит искажение. Если ты хочешь ей пользоваться, придется изгнать из нее демона. С этим я легко справлюсь.$B$BТебе придется куда труднее. Как только демон выйдет из сферы, убей его.$B$BИ спеши. Если ты будешь возиться слишком долго, он вернется в сферу, и нам придется начать сначала!$B$BПодготовься к схватке, $n. Вспомни самые сильные заклинания и держи под рукой зелья. Если у тебя есть друг, можешь позвать его. Сражение будет нелегким.','Убейте демона сферы, а потом поговорите с Табетой.','Великолепно, $N. Тебе удалось преподать этому демону урок, который он надолго запомнит. Могущества и умения тебе не занимать. Полагаю, пришло время вернуться к Менаре с очищенным шаром и найти ему доброе применение.$B$BУдачи, |3-6($C). Быть может, наши пути еще пересекутся.','Вам придется убить этого демона, чтобы навсегда удалить его присутствие из сферы, $N.','Вернитесь к Табете на ферму, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение шара Орахила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, сфера призывателя – так вот откуда исходит искажение. Если ты хочешь ей пользоваться, придется изгнать из нее демона. С этим я легко справлюсь.$B$BТебе придется куда труднее. Как только демон выйдет из сферы, убей его.$B$BИ спеши. Если ты будешь возиться слишком долго, он вернется в сферу, и нам придется начать сначала!$B$BПодготовься к схватке, $n. Вспомни самые сильные заклинания и держи под рукой зелья. Если у тебя есть друг, можешь позвать его. Сражение будет нелегким.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте демона сферы, а потом поговорите с Табетой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, $N. Тебе удалось преподать этому демону урок, который он надолго запомнит. Могущества и умения тебе не занимать. Полагаю, пришло время вернуться к Менаре с очищенным шаром и найти ему доброе применение.$B$BУдачи, |3-6($C). Быть может, наши пути еще пересекутся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вам придется убить этого демона, чтобы навсегда удалить его присутствие из сферы, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на ферму, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4962,'Осколок гончей Скверны','Итак, ты $gвыбрал:выбрала; гончую скверны. Отлично.$B$BВозьми этот рубин, он позволит подчинить ее душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он все сделает за тебя.$B$BСоветую отправиться в Пустоши и попробовать подчинить одну из тамошних гончих скверны. Они отлично подойдут.$B$BКогда добьешься успеха, отнеси плененного духа и рубин Менаре.','Возьмите рубин Сквернолова и поймайте в него одну из гончих скверны в Пустошах. Добившись успеха, отнесите плененный дух Гончей Скверны и рубин Сквернолова Менаре Расщепительнице Бездны из Степей.','Вернитесь к Менаре Расщепительнице Бездны в Кабестан, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осколок гончей Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, ты $gвыбрал:выбрала; гончую скверны. Отлично.$B$BВозьми этот рубин, он позволит подчинить ее душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он все сделает за тебя.$B$BСоветую отправиться в Пустоши и попробовать подчинить одну из тамошних гончих скверны. Они отлично подойдут.$B$BКогда добьешься успеха, отнеси плененного духа и рубин Менаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите рубин Сквернолова и поймайте в него одну из гончих скверны в Пустошах. Добившись успеха, отнесите плененный дух Гончей Скверны и рубин Сквернолова Менаре Расщепительнице Бездны из Степей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менаре Расщепительнице Бездны в Кабестан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (4963,'Осколок инфернала','Итак, ты $gвыбрал:выбрала; инфернала. Отлично.$B$BВозьми этот изумруд, он позволит подчинить его душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он все сделает за тебя.$B$BСоветую отправиться в Пустоши и попробовать подчинить одного из инферналов. Они отлично подойдут.$B$BКогда добьешься успеха, отнеси плененного духа и изумруд Менаре.','Возьмите Пылающий изумруд и поймайте в него одного из инферналов в Пустошах. Добившись успеха, отнесите плененный дух инфернала и пылающий изумруд Менаре Расщепительнице Бездны из Степей.','Вернитесь к Менаре Расщепительнице Бездны в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осколок инфернала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, ты $gвыбрал:выбрала; инфернала. Отлично.$B$BВозьми этот изумруд, он позволит подчинить его душу. Делай, как обычно: когда тварь окажется на пороге смерти, воспользуйся камнем, и он все сделает за тебя.$B$BСоветую отправиться в Пустоши и попробовать подчинить одного из инферналов. Они отлично подойдут.$B$BКогда добьешься успеха, отнеси плененного духа и изумруд Менаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите Пылающий изумруд и поймайте в него одного из инферналов в Пустошах. Добившись успеха, отнесите плененный дух инфернала и пылающий изумруд Менаре Расщепительнице Бездны из Степей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менаре Расщепительнице Бездны в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4964,'Завершение шара Дар\'орахила','Я немедленно займусь твоим шаром. Надо вселить в него нового демона. После этого у меня будет выбор: превратить его в сферу или в посох. Я всегда считала, что соответствие избранному оружию чернокнижника – это главное... Не вижу причин менять свое мнение.','Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар\'орахила, и еще раз поговорите с ней.','Готово. А теперь скажи, что ты предпочитаешь,: посох, который займет обе руки, или шар, который позволит тебе пользоваться кинжалом или мечом.$B$BСражение с огненным големом – суровое испытание. Нет сомнений, что этот предмет славно послужит тебе в будущем. Прилежно изучай тайные искусства, $N. Я буду ждать вестей о твоих подвигах.','Дождитесь, пока Менара Расщепительница Бездны закончит работу над избранным предметом.','Вернитесь к Менаре Расщепительнице Бездны в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завершение шара Дар\'орахила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я немедленно займусь твоим шаром. Надо вселить в него нового демона. После этого у меня будет выбор: превратить его в сферу или в посох. Я всегда считала, что соответствие избранному оружию чернокнижника – это главное... Не вижу причин менять свое мнение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар\'орахила, и еще раз поговорите с ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Готово. А теперь скажи, что ты предпочитаешь,: посох, который займет обе руки, или шар, который позволит тебе пользоваться кинжалом или мечом.$B$BСражение с огненным големом – суровое испытание. Нет сомнений, что этот предмет славно послужит тебе в будущем. Прилежно изучай тайные искусства, $N. Я буду ждать вестей о твоих подвигах.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Дождитесь, пока Менара Расщепительница Бездны закончит работу над избранным предметом.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менаре Расщепительнице Бездны в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4965,'Знание шара Орахила','Так-так-так... приятно видеть, как ты набираешься могущества, $n. Мне кажется, ты $gготов:готова; поговорить с Менарой Расщепительницей Бездны в Степях. Если вы раньше не встречались, то, поверь мне, другого такого специалиста по созданию предметов – особенно сфер, в которые можно заключить демона – не найти.$B$BИнтересно? Тогда поищи ее. Она живет в башне Страхада над Кабестаном.','Поговорите с Менарой Расщепительницей Бездны в Степях.','А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь.$B$BПриятно видеть, что не все наши сородичи стремятся к одним лишь знаниям.$B$BИтак, думаешь, ты $Gготов:готова;, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знание шара Орахила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так-так-так... приятно видеть, как ты набираешься могущества, $n. Мне кажется, ты $gготов:готова; поговорить с Менарой Расщепительницей Бездны в Степях. Если вы раньше не встречались, то, поверь мне, другого такого специалиста по созданию предметов – особенно сфер, в которые можно заключить демона – не найти.$B$BИнтересно? Тогда поищи ее. Она живет в башне Страхада над Кабестаном.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Менарой Расщепительницей Бездны в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь.$B$BПриятно видеть, что не все наши сородичи стремятся к одним лишь знаниям.$B$BИтак, думаешь, ты $Gготов:готова;, $N?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4966,'Защитить Канати Серое Облако','Кентавров намного больше, чем я думал, $n. Пожалуйста, помогите мне отбиться от них.','Защитите Канати Серое Облако от нападения кентавров.','Прямо из Кабестана, свеженькие лезвия для пил Песни Войны! Да, они у меня с собой.\n\n..Но чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!\n\nЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защищать себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.\n\nИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?','Защитить Канати Серое Облако','Вернитесь к Канати Серому Облаку на Заставу Белого Плеса, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитить Канати Серое Облако',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кентавров намного больше, чем я думал, $n. Пожалуйста, помогите мне отбиться от них.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите Канати Серое Облако от нападения кентавров.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прямо из Кабестана, свеженькие лезвия для пил Песни Войны! Да, они у меня с собой.\n\n..Но чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!\n\nЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защищать себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.\n\nИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитить Канати Серое Облако',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Канати Серому Облаку на Заставу Белого Плеса, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4967,'Знание шара Орахила','Ты так и не $gпоумнел:поумнела; и по-прежнему стремишься в западню. Да, говорю я дерзко. Я смотрю на тебя и смеюсь. Ты жалкий червь!$B$BНо мое мнение не имеет значения. Главное, что думают те, кто желает иметь с тобой дело! И в данном случае наделенные силой полагают, что ты заслуживаешь большего.$B$BЕсли ты к чему-то стремишься, поговори с Менарой Расщепительницей Бездны в башне над Кабестаном. Кажется, ты с ней уже $gвстречался:встречалась;.','Поговорите с Менарой Расщепительницей Бездны в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знание шара Орахила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты так и не $gпоумнел:поумнела; и по-прежнему стремишься в западню. Да, говорю я дерзко. Я смотрю на тебя и смеюсь. Ты жалкий червь!$B$BНо мое мнение не имеет значения. Главное, что думают те, кто желает иметь с тобой дело! И в данном случае наделенные силой полагают, что ты заслуживаешь большего.$B$BЕсли ты к чему-то стремишься, поговори с Менарой Расщепительницей Бездны в башне над Кабестаном. Кажется, ты с ней уже $gвстречался:встречалась;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Менарой Расщепительницей Бездны в Степях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4968,'Знание шара Орахила','Хм-м... Тебе удалось добиться немалого... Поразительно. Я думала, что ты давно $gсошел:сошла; с ума, $Gраздираемый:раздираемая; скверной магией, просочившейся в твою душу. Тогда, пожалуй, двинемся дальше?$B$BЕсли ты хочешь испытать свое искусство, отыщи Менару Расщепительницу Бездны в башне Страхада над Кабестаном. Она поможет тебе сделать следующий шаг.','Поговорите с Менарой Расщепительницей Бездны в Степях.','А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь.$B$BПриятно видеть, что не все наши сородичи стремятся к одним лишь знаниям.$B$BИтак, думаешь, ты $Gготов:готова;, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знание шара Орахила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм-м... Тебе удалось добиться немалого... Поразительно. Я думала, что ты давно $gсошел:сошла; с ума, $Gраздираемый:раздираемая; скверной магией, просочившейся в твою душу. Тогда, пожалуй, двинемся дальше?$B$BЕсли ты хочешь испытать свое искусство, отыщи Менару Расщепительницу Бездны в башне Страхада над Кабестаном. Она поможет тебе сделать следующий шаг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Менарой Расщепительницей Бездны в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, ты ищешь чего-то более... вещественного. Я помогу тебе, если хочешь.$B$BПриятно видеть, что не все наши сородичи стремятся к одним лишь знаниям.$B$BИтак, думаешь, ты $Gготов:готова;, $N?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4969,'Знание шара Орахила','Ха-ха! Ты растешь над собой, $gюный:юная:c; |3-6($c).$B$BСо временем инферналы и повелители ужаса склонятся перед тобой!$B$BПока же тебе приходится полагаться на оружие, скованное руками смертных.$B$BПохоже, ты $gготов:готова; создать еще одно. Если хочешь, с тобой может поговорить Менара Расщепительница Бездны! Она живет неподалеку от башни Страхада над портовым городом Кабестан. Отправляйся туда, как решишь, что время уже пришло.','Поговорите с Менарой Расщепительницей Бездны в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знание шара Орахила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ха-ха! Ты растешь над собой, $gюный:юная:c; |3-6($c).$B$BСо временем инферналы и повелители ужаса склонятся перед тобой!$B$BПока же тебе приходится полагаться на оружие, скованное руками смертных.$B$BПохоже, ты $gготов:готова; создать еще одно. Если хочешь, с тобой может поговорить Менара Расщепительница Бездны! Она живет неподалеку от башни Страхада над портовым городом Кабестан. Отправляйся туда, как решишь, что время уже пришло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Менарой Расщепительницей Бездны в Степях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4970,'Накормить ледопардов','Если хочешь достойно проявить себя, начни с простого, но очень важного дела. $b$bДобудь в окрестностях мясо химер и медведей-щербозубов. Принеси его мне, чтобы я мог кормить им ледопардов, которых я дрессирую.','Соберите 5 кусков мяса медведей-щеброзубов и 5 кусков мяса хладнокрылых химер для Риверна Холодного Ветра в Зимних Ключах.','Спасибо за помощь, $N. Мое мнение о вас со временем становится все лучше.','Дисциплина и собранность – вот твоя цель! Я могу попросить сделать простую вещь много раз – и каждый раз ты $Gдолжен:должна; выполнить ее наилучшим образом.','Вернитесь к Риверну Холодному Ветру на Уступ Ледопардов, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Накормить ледопардов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хочешь достойно проявить себя, начни с простого, но очень важного дела. $b$bДобудь в окрестностях мясо химер и медведей-щербозубов. Принеси его мне, чтобы я мог кормить им ледопардов, которых я дрессирую.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 кусков мяса медведей-щеброзубов и 5 кусков мяса хладнокрылых химер для Риверна Холодного Ветра в Зимних Ключах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь, $N. Мое мнение о вас со временем становится все лучше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дисциплина и собранность – вот твоя цель! Я могу попросить сделать простую вещь много раз – и каждый раз ты $Gдолжен:должна; выполнить ее наилучшим образом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риверну Холодному Ветру на Уступ Ледопардов, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4971,'Вопрос времени','Кто-то вмешался в ход времени в Андорале! Скорее всего, это дело рук Плети. Я могу попытаться сохранить неизменным ход времени здесь и исправить повреждения, но мне не должны мешать. В этом ты мне и поможешь.$b$bВ Андорале поселились временные паразиты, падальщики, питающиеся обрывками потока времени. Их можно обнаружить только по синему сиянию. Они очень мешают мне. Пожалуйста, $n, искорени этих паразитов, воспользовавшись временным переместителем.','Воспользуйтесь временным переместителем рядом с одним из амбаров Андорала и найдите временных паразитов.$b$bУбейте 10 временных паразитов и верните временной переместитель Хроми в Андоральскую таверну в Западных Чумных землях.','Там, где кто-то вмешивается в ход времени, непременно появляются временные паразиты. Я чувствую, что их немало, и они мне очень мешают.$B$BЕсли ты искоренишь хотя бы часть, мне будет гораздо проще разрешить сложившуюся ситуацию. Я почувствую, когда ты справишься с моим заданием.','Вернитесь к Хроми на Руины Андорала, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вопрос времени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто-то вмешался в ход времени в Андорале! Скорее всего, это дело рук Плети. Я могу попытаться сохранить неизменным ход времени здесь и исправить повреждения, но мне не должны мешать. В этом ты мне и поможешь.$b$bВ Андорале поселились временные паразиты, падальщики, питающиеся обрывками потока времени. Их можно обнаружить только по синему сиянию. Они очень мешают мне. Пожалуйста, $n, искорени этих паразитов, воспользовавшись временным переместителем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь временным переместителем рядом с одним из амбаров Андорала и найдите временных паразитов.$b$bУбейте 10 временных паразитов и верните временной переместитель Хроми в Андоральскую таверну в Западных Чумных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Там, где кто-то вмешивается в ход времени, непременно появляются временные паразиты. Я чувствую, что их немало, и они мне очень мешают.$B$BЕсли ты искоренишь хотя бы часть, мне будет гораздо проще разрешить сложившуюся ситуацию. Я почувствую, когда ты справишься с моим заданием.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроми на Руины Андорала, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4972,'Отсчет времени','Мне нужно отправить тебя в мир за пределами этой комнаты, $n. Сейчас все объясню.$b$bВидишь, как эта комната отличается от остального Андорала? Мои драконы существуют во многих пластах реальности и времени. Чтобы исправить ущерб, нанесенный Андоралу, я действую из другого временного пласта, чтобы не загрязнить его сверх меры. Для продолжения работ мне необходимы особые устройства, оставшиеся со времен прихода чумы. Они находятся в сейфах в руинах некогда гордого города.','Найдите 5 часов Андорала, спрятанных в сейфы среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях.','Временные устройства, которые я ищу, очень просты. По большей части это просто часы, и их стрелки остановились в тот миг, когда в Андорале вспыхнула чума.$B$BВремя нескончамо, а часы, которые ты мне принесешь так и будут стоять... пока мы не справимся с временной аномалией.','Вернитесь к Хроми на Руины Андорала, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отсчет времени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно отправить тебя в мир за пределами этой комнаты, $n. Сейчас все объясню.$b$bВидишь, как эта комната отличается от остального Андорала? Мои драконы существуют во многих пластах реальности и времени. Чтобы исправить ущерб, нанесенный Андоралу, я действую из другого временного пласта, чтобы не загрязнить его сверх меры. Для продолжения работ мне необходимы особые устройства, оставшиеся со времен прихода чумы. Они находятся в сейфах в руинах некогда гордого города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 часов Андорала, спрятанных в сейфы среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Временные устройства, которые я ищу, очень просты. По большей части это просто часы, и их стрелки остановились в тот миг, когда в Андорале вспыхнула чума.$B$BВремя нескончамо, а часы, которые ты мне принесешь так и будут стоять... пока мы не справимся с временной аномалией.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроми на Руины Андорала, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4973,'Отсчет времени','Если ты $gготов:готова; еще раз оказать мне помощь, я попрошу тебя принести еще пять часов из руин Андорала. Это очень поможет мне на равных бороться со злобной силой, пытающейся изменить ход времени.$b$bВзамен часов ты получишь еще один дар, который, мне кажется, здорово пригодится тебе в будущем.','Найдите 5 часов Андорала, спрятанных в сундуки среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях.','Часы Андорала, как и те, на башне, остановились в три часа. Именно в это время чума распространилась по всему городу, лишая жизни несчастных жителей.$B$BКак ни печалимся мы о событиях того дня, они уже вошли в историю, без них не было бы сегодняшнего дня, такого, каким видите его вы, смертные. Бронзовые драконы должны хранить линию времени!','Вернитесь к Хроми на Руины Андорала, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отсчет времени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты $gготов:готова; еще раз оказать мне помощь, я попрошу тебя принести еще пять часов из руин Андорала. Это очень поможет мне на равных бороться со злобной силой, пытающейся изменить ход времени.$b$bВзамен часов ты получишь еще один дар, который, мне кажется, здорово пригодится тебе в будущем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 часов Андорала, спрятанных в сундуки среди руин. Принесите их Хроми в таверну Андорала в Западных Чумных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Часы Андорала, как и те, на башне, остановились в три часа. Именно в это время чума распространилась по всему городу, лишая жизни несчастных жителей.$B$BКак ни печалимся мы о событиях того дня, они уже вошли в историю, без них не было бы сегодняшнего дня, такого, каким видите его вы, смертные. Бронзовые драконы должны хранить линию времени!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроми на Руины Андорала, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4974,'За Орду!','Ренд осмеливается делать подобные заявления, потому что он пользуется поддержкой черных драконов.$B$BТы, $n, проникнешь в Залы Вознесения, найдешь там "вождя" Ренда Чернорука и уничтожишь его – ВО ИМЯ ОРДЫ!!!$b$b*Тралл ударяет кулаком по своему трону.*$b$bВ следующий раз, как я увижу тебя в своих покоях, ты торжествующе поднимешь ввысь его отрубленную голову и вручишь ее своему вождю. Выполни это – и станешь одним из героев Орды!','Отправляйтесь на Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар.','Тебе удалось нанести силам Черной горы сокрушительный удар, $N! Теперь, когда их вождь убит, воинство Черной горы снова ввергнуто в хаос.$B$BНаградой за твой героизм будет процветание народа Калимдора!','<Тралл рычит.>','Вернитесь к Траллу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За Орду!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ренд осмеливается делать подобные заявления, потому что он пользуется поддержкой черных драконов.$B$BТы, $n, проникнешь в Залы Вознесения, найдешь там "вождя" Ренда Чернорука и уничтожишь его – ВО ИМЯ ОРДЫ!!!$b$b*Тралл ударяет кулаком по своему трону.*$b$bВ следующий раз, как я увижу тебя в своих покоях, ты торжествующе поднимешь ввысь его отрубленную голову и вручишь ее своему вождю. Выполни это – и станешь одним из героев Орды!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Пик Черной горы и убейте вождя Ренда Чернорука. Принесите его голову в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось нанести силам Черной горы сокрушительный удар, $N! Теперь, когда их вождь убит, воинство Черной горы снова ввергнуто в хаос.$B$BНаградой за твой героизм будет процветание народа Калимдора!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Тралл рычит.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (4975,'Завершение шара Дар\'орахила','Я немедленно займусь твоим шаром. Надо вселить в него нового демона. После этого у меня будет выбор: превратить его в сферу или в посох. Я всегда считала, что соответствие избранному оружию чернокнижника – это главное... Не вижу причин менять свое мнение.','Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар\'орахила, и еще раз поговорите с ней.','Готово, $N. Просто скажи, что же ты предпочитаешь – посох, который занимает обе руки, или сферу, с которой ты можешь использовать кинжал или что-то еще в своей правой руке.$B$BЖелаю тебе всяческих успехов в совершенствовании твоих искусств, $N.','Дождитесь, пока Менара Расщепительница Бездны закончит работу над избранным предметом.','Вернитесь к Менаре Расщепительнице Бездны в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завершение шара Дар\'орахила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я немедленно займусь твоим шаром. Надо вселить в него нового демона. После этого у меня будет выбор: превратить его в сферу или в посох. Я всегда считала, что соответствие избранному оружию чернокнижника – это главное... Не вижу причин менять свое мнение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока Менара Расщепительница Бездны закончит работу над шаром Дар\'орахила, и еще раз поговорите с ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Готово, $N. Просто скажи, что же ты предпочитаешь – посох, который занимает обе руки, или сферу, с которой ты можешь использовать кинжал или что-то еще в своей правой руке.$B$BЖелаю тебе всяческих успехов в совершенствовании твоих искусств, $N.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Дождитесь, пока Менара Расщепительница Бездны закончит работу над избранным предметом.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Менаре Расщепительнице Бездны в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4976,'Возвращение к Менаре','Теперь, когда демон изгнан, ты можешь отнести шар Менаре в Кабестан, $n. Передай ей от меня привет, да и $gсам:сама; не робей. Надеюсь, что тебе удастся противостоять искушениям скверны, которые, несомненно, будут подстерегать тебя на избранном пути.$B$BЖелаю удачи.','Отнесите очищенную сферу инфернала Менаре Расщепительнице Бездны в Степи.','Отлично, $N. Подходящая сфера.$B$BОсталось одно – решить, какого демона следует заключить в нее. Решишь – считай, новый предмет силы у тебя в кармане.','Как идут поиски, $N?$B$BТабета более чем полезна когда речь заходит о магии. Я уверена что ей не составит труда помочь тебе, если ты конечно найдешь ее.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Менаре',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда демон изгнан, ты можешь отнести шар Менаре в Кабестан, $n. Передай ей от меня привет, да и $gсам:сама; не робей. Надеюсь, что тебе удастся противостоять искушениям скверны, которые, несомненно, будут подстерегать тебя на избранном пути.$B$BЖелаю удачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите очищенную сферу инфернала Менаре Расщепительнице Бездны в Степи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N. Подходящая сфера.$B$BОсталось одно – решить, какого демона следует заключить в нее. Решишь – считай, новый предмет силы у тебя в кармане.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идут поиски, $N?$B$BТабета более чем полезна когда речь заходит о магии. Я уверена что ей не составит труда помочь тебе, если ты конечно найдешь ее.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (4981,'Агент Блестяшка','Никогда нельзя верить гоблинам! Рано или поздно все приходят к этому выводу, $n. $B$BЕе зовут Блестяшка, она была одним из лучших наших агентов. Потом оказалось, что стерва вела двойную игру – работала на какого-то типа по имени Киблер, нелегально торгующего экзотическими животными в Пылающих степях, и использовала средства Орды для финансирования своих махинаций! $B$BОна должна быть доставлена ко мне живой. $B$BПоследний раз ее видели у Пика Черной горы. $B$BИ смотри, чтобы она не заговорила тебе зубы!','Отправьтесь к Пику Черной горы и выясните, что сталось с Блестяшкой.','Я не буду лгать тебе, |3-6($R). Мне были нужны деньги! Киблер хорошо платит – куда больше, чем в Каргатском экспедиционном корпусе в лучшие его годы.$B$BНо можешь не сомневаться, я верна присяге! Думаешь, зачем я здесь? Чтобы таскать этому придурку-гоблину яйца экзотических зверушек или еще для каких глупостей? Нужно быть очень крупным идиотом, чтобы явиться в пик Черной горы отлавливать зверье! Не думаю, что на свете много таких сумасшедших.$B$B<Блестяшка заливисто хохочет.>$B$BВот что я тебе скажу, такие просто не должны размножаться, да-да!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Агент Блестяшка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Никогда нельзя верить гоблинам! Рано или поздно все приходят к этому выводу, $n. $B$BЕе зовут Блестяшка, она была одним из лучших наших агентов. Потом оказалось, что стерва вела двойную игру – работала на какого-то типа по имени Киблер, нелегально торгующего экзотическими животными в Пылающих степях, и использовала средства Орды для финансирования своих махинаций! $B$BОна должна быть доставлена ко мне живой. $B$BПоследний раз ее видели у Пика Черной горы. $B$BИ смотри, чтобы она не заговорила тебе зубы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь к Пику Черной горы и выясните, что сталось с Блестяшкой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не буду лгать тебе, |3-6($R). Мне были нужны деньги! Киблер хорошо платит – куда больше, чем в Каргатском экспедиционном корпусе в лучшие его годы.$B$BНо можешь не сомневаться, я верна присяге! Думаешь, зачем я здесь? Чтобы таскать этому придурку-гоблину яйца экзотических зверушек или еще для каких глупостей? Нужно быть очень крупным идиотом, чтобы явиться в пик Черной горы отлавливать зверье! Не думаю, что на свете много таких сумасшедших.$B$B<Блестяшка заливисто хохочет.>$B$BВот что я тебе скажу, такие просто не должны размножаться, да-да!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (4982,'Вещи Блестяшки','По ночам, когда городская стража не особенно ревностно исполняет свои обязанности, я незаметно брожу по улицам и беру на заметку все, что может иметь хоть какую-то ценность для стратегических планов К.Э.К. Все подмечаю и все записываю.$B$BНо вчера ночью случился прокол. В темноте я запнулась о натянутую веревку, и включился сигнал тревоги. Пришлось срочно прятать все оборудование для разведки и мчаться в укрытие. И что самое ужасное, сейчас мне уже не удастся забрать свои вещи из тайника. В городе ввели усиленный режим патрулирования! Вся информация утрачена.$B$BРазыщи мои вещи, верни их мне, и я тихо-мирно вернусь в К.Э.К.','Найдите вещи Блестяшки и верните их владелице. Блестяшка сказала, что она спрятала свое оборудование где-то на нижнем ярусе подземелья.','Ой, $Gмолодчина:умница;! Когда я передам Лекслорту эти планы, он позабудет обо всех страшных угрозах в мой адрес и уж точно не станет спускать с меня шкуру.$B$B$N, ты $Gмой:моя; $Gгерой:героиня;!','Ну, как успехи?','Вернитесь к Блестяшке в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вещи Блестяшки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По ночам, когда городская стража не особенно ревностно исполняет свои обязанности, я незаметно брожу по улицам и беру на заметку все, что может иметь хоть какую-то ценность для стратегических планов К.Э.К. Все подмечаю и все записываю.$B$BНо вчера ночью случился прокол. В темноте я запнулась о натянутую веревку, и включился сигнал тревоги. Пришлось срочно прятать все оборудование для разведки и мчаться в укрытие. И что самое ужасное, сейчас мне уже не удастся забрать свои вещи из тайника. В городе ввели усиленный режим патрулирования! Вся информация утрачена.$B$BРазыщи мои вещи, верни их мне, и я тихо-мирно вернусь в К.Э.К.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите вещи Блестяшки и верните их владелице. Блестяшка сказала, что она спрятала свое оборудование где-то на нижнем ярусе подземелья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, $Gмолодчина:умница;! Когда я передам Лекслорту эти планы, он позабудет обо всех страшных угрозах в мой адрес и уж точно не станет спускать с меня шкуру.$B$B$N, ты $Gмой:моя; $Gгерой:героиня;!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как успехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Блестяшке в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4983,'Донесение Блестяшки','Передай этот рапорт Лекслорту. Теперь я верну себе доброе имя, потому что мое донесение, безусловно, сослужит хорошую службу К.Э.К. и даст им значительное стратегическое преимущество в борьбе с этими орками.$B$BПойти с тобой, говоришь? У меня много работы, недосуг мне носиться туда-сюда. Беги, донесение надо доставить как можно скорее!','Передайте донесение Блестяшки гроссмейстеру Лекслорту в Каргат.','Все-таки надо отдать ей должное;, хитрая бестия снова сумела выкрутиться! Ее донесение содержит бесценную информацию, которая очень поможет в наших делах с орками Черной Горы.$B$BРазумеется, ты не останешься без награды. Всякий труд должен быть оплачен.','Где эта гоблинша?!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение Блестяшки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Передай этот рапорт Лекслорту. Теперь я верну себе доброе имя, потому что мое донесение, безусловно, сослужит хорошую службу К.Э.К. и даст им значительное стратегическое преимущество в борьбе с этими орками.$B$BПойти с тобой, говоришь? У меня много работы, недосуг мне носиться туда-сюда. Беги, донесение надо доставить как можно скорее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте донесение Блестяшки гроссмейстеру Лекслорту в Каргат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все-таки надо отдать ей должное;, хитрая бестия снова сумела выкрутиться! Ее донесение содержит бесценную информацию, которая очень поможет в наших делах с орками Черной Горы.$B$BРазумеется, ты не останешься без награды. Всякий труд должен быть оплачен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где эта гоблинша?!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (4984,'Страдания природы','Хотя бороться с Плетью в одиночку бесполезно, я все равно прибыл в эти земли, чтобы лечить израненную природу. Чума поражает зверей и травы, не ведая пощады. Прошу, продолжи мое дело.$b$bНесчастных животных не спасти, остается прекратить их страдания. Ступай, отыщи больных волков и прикончи их. Прошу тебя, $n, избавь их от мучений – и мне тоже станет полегче.','Убейте 8 больных волков и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях.','Я... Чую, что души убитых волков обрели покой. Мы с ними благодарны тебе за милосердие.$B$BНо в этом проклятом месте страдают не только волки. Мне вновь придется просить тебя о помощи.','Вернитесь к Мулгрису Глубокой Реке на озеро Дарроумир, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страдания природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя бороться с Плетью в одиночку бесполезно, я все равно прибыл в эти земли, чтобы лечить израненную природу. Чума поражает зверей и травы, не ведая пощады. Прошу, продолжи мое дело.$b$bНесчастных животных не спасти, остается прекратить их страдания. Ступай, отыщи больных волков и прикончи их. Прошу тебя, $n, избавь их от мучений – и мне тоже станет полегче.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 больных волков и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я... Чую, что души убитых волков обрели покой. Мы с ними благодарны тебе за милосердие.$B$BНо в этом проклятом месте страдают не только волки. Мне вновь придется просить тебя о помощи.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мулгрису Глубокой Реке на озеро Дарроумир, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (4985,'Страдания природы','На востоке отсюда, рядом с границей Восточных Чумных земель, некогда жили гордые и могучие гризли. Чума затронула и их. Теперь они бродят по округе, страдая от застывающих мышц и гниющей плоти и меха.$b$bПрошу тебя, избавь их от страданий. Единственное исцеление для них – быстрая смерть. Ты можешь даровать ее.','Убейте 8 болезненных гризли и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях.','Я чувствую, что гризли упокоились с миром. Вот... вот моя последняя просьба. Я записал ее.. на этой ветви, чувствуя, что дни мои сочтены.$B$BЯ не ошибся, мне и верно приходит конец. Еще раз спасибо, брат... все живые существа этой проклятой земли обрели покой... теперь мой черед. $B$BС этими словами друид испускает тяжелый вздох, сменяющийся предсмертным хрипом. На полу остается лишь безжизненное тело.','Вернитесь к Мулгрису Глубокой Реке на озеро Дарроумир, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страдания природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На востоке отсюда, рядом с границей Восточных Чумных земель, некогда жили гордые и могучие гризли. Чума затронула и их. Теперь они бродят по округе, страдая от застывающих мышц и гниющей плоти и меха.$b$bПрошу тебя, избавь их от страданий. Единственное исцеление для них – быстрая смерть. Ты можешь даровать ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 болезненных гризли и вернитесь к Мулгрису Глубокой Реке в Удел Страданий в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я чувствую, что гризли упокоились с миром. Вот... вот моя последняя просьба. Я записал ее.. на этой ветви, чувствуя, что дни мои сочтены.$B$BЯ не ошибся, мне и верно приходит конец. Еще раз спасибо, брат... все живые существа этой проклятой земли обрели покой... теперь мой черед. $B$BС этими словами друид испускает тяжелый вздох, сменяющийся предсмертным хрипом. На полу остается лишь безжизненное тело.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мулгрису Глубокой Реке на озеро Дарроумир, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (4986,'Покрытая письменами дубовая ветвь','В безжизненной руке друида-таурена – удивительно живая дубовая ветвь. Внимательно осмотрев ее, вы видите вырезанные на ней друидические символы.$b$bСхватившись за ветвь, вы замечаете, что она слишком теплая для простой ветви. У вас в подсознании возникает образ древа Тельдрассила, точнее, самого Дарнаса. Более того, в голове так и вертятся слова "Круг Кенария". Кажется, в ветку вложили знания, куда ее лучше отнести.','Судя по магии, вложенной в покрытую письменами дубовую ветвь, друид-таурен желал отнести ее в Круг Кенария в Дарнасе. Попросите о помощи одного из тамошних друидов.','Это... Это странно. Тот друид – друид-таурен, надо же – передал тебе ценнейшие сведения о чуме Плети. Удивительно, зачем таурену понадобилось добровольно передавать подобные сведения ). Надеюсь, ты говоришь правду. Не сомневайся, мы воспользуемся этими данными. Значит, таурены не так далеко отпали от Кенария, как полагает Фэндрал...$B$BКхе-кхе, да. Прими это в знак признательности Круга Кенария.','Приветствую тебя от имени Круга Кенария, |3-6($C). Что за дела привели тебя к нам?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покрытая письменами дубовая ветвь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В безжизненной руке друида-таурена – удивительно живая дубовая ветвь. Внимательно осмотрев ее, вы видите вырезанные на ней друидические символы.$b$bСхватившись за ветвь, вы замечаете, что она слишком теплая для простой ветви. У вас в подсознании возникает образ древа Тельдрассила, точнее, самого Дарнаса. Более того, в голове так и вертятся слова "Круг Кенария". Кажется, в ветку вложили знания, куда ее лучше отнести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Судя по магии, вложенной в покрытую письменами дубовую ветвь, друид-таурен желал отнести ее в Круг Кенария в Дарнасе. Попросите о помощи одного из тамошних друидов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это... Это странно. Тот друид – друид-таурен, надо же – передал тебе ценнейшие сведения о чуме Плети. Удивительно, зачем таурену понадобилось добровольно передавать подобные сведения ). Надеюсь, ты говоришь правду. Не сомневайся, мы воспользуемся этими данными. Значит, таурены не так далеко отпали от Кенария, как полагает Фэндрал...$B$BКхе-кхе, да. Прими это в знак признательности Круга Кенария.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя от имени Круга Кенария, |3-6($C). Что за дела привели тебя к нам?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (4987,'Покрытая письменами дубовая ветвь','В безжизненной руке друида-таурена – удивительно живая дубовая ветвь. Внимательно осмотрев ее, вы видите вырезанные на ней друидические символы.$b$bСхватившись за ветвь, вы замечаете, что она слишком теплая для простой ветви. У вас в подсознании возникает образ Громового Утеса в Мулгоре, точнее, Вершины Старейшин. Более того, в голове так и вертятся слова "Круг Кенария". Кажется, в ветку вложили знания, куда ее лучше отнести.','Судя по магии, записанной в покрытую письменами дубовую ветвь, друид-таурен желал отнести ее в Круг Кенария в Громовом Утесе. Попросите о помощи одного из тамошних друидов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покрытая письменами дубовая ветвь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В безжизненной руке друида-таурена – удивительно живая дубовая ветвь. Внимательно осмотрев ее, вы видите вырезанные на ней друидические символы.$b$bСхватившись за ветвь, вы замечаете, что она слишком теплая для простой ветви. У вас в подсознании возникает образ Громового Утеса в Мулгоре, точнее, Вершины Старейшин. Более того, в голове так и вертятся слова "Круг Кенария". Кажется, в ветку вложили знания, куда ее лучше отнести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Судя по магии, записанной в покрытую письменами дубовую ветвь, друид-таурен желал отнести ее в Круг Кенария в Громовом Утесе. Попросите о помощи одного из тамошних друидов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5001,'Вещи Блестяшки','Обычно я стараюсь не связываться с такими, как ты, |3-6($r), но, похоже, сейчас я застряла между троллем и горным завалом. Видишь ли, я выполняю важное задание для Орды. Однако та информация, которую мне удалось раздобыть, касается также и благополучия Альянса. Поверь мне, я не питаю симпатий к Альянсу, но угроза Черной горы – это гораздо серьезнее, чем какая-то там толпа грязных орков.$B$BПомоги мне найти мои вещи, а я передам тебе сведения, которые могут оказаться полезными для твоих сородичей.$B$BНу что, по рукам?','Найдите вещи Блестяшки и верните их владелице. Удачи!','Ой, спасибо! И где ж они были?!','Ну, как успехи?','Вернитесь к Блестяшке в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вещи Блестяшки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обычно я стараюсь не связываться с такими, как ты, |3-6($r), но, похоже, сейчас я застряла между троллем и горным завалом. Видишь ли, я выполняю важное задание для Орды. Однако та информация, которую мне удалось раздобыть, касается также и благополучия Альянса. Поверь мне, я не питаю симпатий к Альянсу, но угроза Черной горы – это гораздо серьезнее, чем какая-то там толпа грязных орков.$B$BПомоги мне найти мои вещи, а я передам тебе сведения, которые могут оказаться полезными для твоих сородичей.$B$BНу что, по рукам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите вещи Блестяшки и верните их владелице. Удачи!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, спасибо! И где ж они были?!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как успехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Блестяшке в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5002,'Донесение Максвелла','Я – честная гоблинша и хозяйка своего слова, |3-6($r). А теперь слушай внимательно...$B$BЭтих орков используют в основном в качестве вьючных животных или пушечного мяса для черных драконов!$B$BИх предводитель не кто иной, как Нефариан, сын Смертокрыла. Также мне удалось узнать, где именно в крепости засели приспешники Нефариана.$B$BОтнеси эту карту маршалу Максвеллу в Пылающие степи. Я там отметила все места, где найти этих извергов.','Передайте маршалу Максвеллу информацию Блестяшки.','Что ж, это лишь подтверждает уже известную нам информацию. Тем не менее здесь есть интересные сведения, которые нам пригодятся.\n\nОтметки на карте – это хорошее подспорье. Так мы быстрее разберемся с угрозой Черной горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение Максвелла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я – честная гоблинша и хозяйка своего слова, |3-6($r). А теперь слушай внимательно...$B$BЭтих орков используют в основном в качестве вьючных животных или пушечного мяса для черных драконов!$B$BИх предводитель не кто иной, как Нефариан, сын Смертокрыла. Также мне удалось узнать, где именно в крепости засели приспешники Нефариана.$B$BОтнеси эту карту маршалу Максвеллу в Пылающие степи. Я там отметила все места, где найти этих извергов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте маршалу Максвеллу информацию Блестяшки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, это лишь подтверждает уже известную нам информацию. Тем не менее здесь есть интересные сведения, которые нам пригодятся.\n\nОтметки на карте – это хорошее подспорье. Так мы быстрее разберемся с угрозой Черной горы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5021,'Лучше поздно, чем никогда','"Доставьте посылку... Доставьте ее, пока я не очутилась в ловушке!"$B$BПо всему дому разносятся причитания напуганной женщины. Привидение скорчилось в углу на втором этаже. Кажется, она не понимает, что вокруг, да и вас едва замечает.$b$b"Ты хочешь доставить мою посылку? Прошу тебя, сделай это, пока хуже не стало. Я собиралась уехать отсюда. Должно быть, там все еще стоит мой конь... или я опоздала?"','Судя по сбивчивым объяснениям призрачной женщины, она хочет доставить посылку. Бедняга уверяет, что посылка лежала там, где стоял ее конь. Где именно это было, женщина не сказала.','В сарае на полу лежит посылка. Вы могли бы пройти мимо, но она бросается в глаза среди развалин. Быть может, именно о ней говорила Джанис Фелстоун...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучше поздно, чем никогда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Доставьте посылку... Доставьте ее, пока я не очутилась в ловушке!"$B$BПо всему дому разносятся причитания напуганной женщины. Привидение скорчилось в углу на втором этаже. Кажется, она не понимает, что вокруг, да и вас едва замечает.$b$b"Ты хочешь доставить мою посылку? Прошу тебя, сделай это, пока хуже не стало. Я собиралась уехать отсюда. Должно быть, там все еще стоит мой конь... или я опоздала?"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Судя по сбивчивым объяснениям призрачной женщины, она хочет доставить посылку. Бедняга уверяет, что посылка лежала там, где стоял ее конь. Где именно это было, женщина не сказала.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В сарае на полу лежит посылка. Вы могли бы пройти мимо, но она бросается в глаза среди развалин. Быть может, именно о ней говорила Джанис Фелстоун...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5022,'Лучше поздно, чем никогда','Вы берете посылку, стирая с нее слой пыли и грязи. Она адресована Эмме Фелстоун из Штормграда; посылка должна была быть доставлена четыре года назад.$b$bХотя вы не уверены, что Эмма Фелстоун жива, всем известно, что в Штормграде существует реестр жителей города. Справки можно наводить у королевских представителей Переписи Штормграда.','Выясните у королевских представителей Переписи Штормграда местонахождение Эммы Фелстоун. Офицера-переписчика можно найти в Ратуше.','Говорите, посылка для Эммы Фелстоун? И четыре года назад она жила в Штормграде? Посмотрим…$B$BСудя по всему, четыре города назад в городе и верно жила некая Эмма Фелстоун. Скорее всего жила. Я ориентируюсь по переписи, имевшей место пять лет назад, но никаких записей о том, что она уехала, нет. Но это не значит, что Эмма все еще здесь.$B$BМинуточку... уж не старушке ли Эмме адресована эта посылка?','Добро пожаловать в отдел переписи Штормграда. Если вы хотите навести справки о жителях города, то пришли по адресу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучше поздно, чем никогда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы берете посылку, стирая с нее слой пыли и грязи. Она адресована Эмме Фелстоун из Штормграда; посылка должна была быть доставлена четыре года назад.$b$bХотя вы не уверены, что Эмма Фелстоун жива, всем известно, что в Штормграде существует реестр жителей города. Справки можно наводить у королевских представителей Переписи Штормграда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните у королевских представителей Переписи Штормграда местонахождение Эммы Фелстоун. Офицера-переписчика можно найти в Ратуше.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говорите, посылка для Эммы Фелстоун? И четыре года назад она жила в Штормграде? Посмотрим…$B$BСудя по всему, четыре города назад в городе и верно жила некая Эмма Фелстоун. Скорее всего жила. Я ориентируюсь по переписи, имевшей место пять лет назад, но никаких записей о том, что она уехала, нет. Но это не значит, что Эмма все еще здесь.$B$BМинуточку... уж не старушке ли Эмме адресована эта посылка?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать в отдел переписи Штормграда. Если вы хотите навести справки о жителях города, то пришли по адресу.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5023,'Лучше поздно, чем никогда','Вы берете посылку, стирая с нее слой пыли и грязи. Она адресована Иеремии Фелстоуну из Лордерона; посылка была подготовлена к отправке четыре года назад.$b$bХотя вы не уверены, что Иеремия Фелстоун жив, всем известно, что в Подгороде, прежде именовавшемся Лордероном, существует реестр жителей города. Справки можно наводить у королевских инспекторов Переписи Подгорода.','Поговорите с королевскими инспекторами Подгорода и наведите справки о Иеремии Фелстоуне. Офицера-переписчика можно найти рядом с пунктом регистрации гильдий и гербовых накидок.','Посылка для Иеремии Фелстоуна... В Лордерон... Пожалуй, я смогу помочь.$B$BДо наступления чумы Иеремия Фелстоун жил в городе. Бывший Иеремия Фелстоун – многие представители нежити изменили фамилии, чтобы избавиться от прошлого. Так произошло и в этом случае. Иеремения Фелстоун стал Иеремией Пэйсоном.$B$BМинуточку... разве это не он продает тараканов?','Тебе требуется помощь переписчика Подгорода или ты просто хочешь узнать, не умер ли твой давний знакомый? Ко мне с такими вопросами часто обращаются.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучше поздно, чем никогда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы берете посылку, стирая с нее слой пыли и грязи. Она адресована Иеремии Фелстоуну из Лордерона; посылка была подготовлена к отправке четыре года назад.$b$bХотя вы не уверены, что Иеремия Фелстоун жив, всем известно, что в Подгороде, прежде именовавшемся Лордероном, существует реестр жителей города. Справки можно наводить у королевских инспекторов Переписи Подгорода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королевскими инспекторами Подгорода и наведите справки о Иеремии Фелстоуне. Офицера-переписчика можно найти рядом с пунктом регистрации гильдий и гербовых накидок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посылка для Иеремии Фелстоуна... В Лордерон... Пожалуй, я смогу помочь.$B$BДо наступления чумы Иеремия Фелстоун жил в городе. Бывший Иеремия Фелстоун – многие представители нежити изменили фамилии, чтобы избавиться от прошлого. Так произошло и в этом случае. Иеремения Фелстоун стал Иеремией Пэйсоном.$B$BМинуточку... разве это не он продает тараканов?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе требуется помощь переписчика Подгорода или ты просто хочешь узнать, не умер ли твой давний знакомый? Ко мне с такими вопросами часто обращаются.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5041,'Снабжение Перекрестка','Найдите 5 ящиков с припасами с Перекрестка в пещере Иглогривых.','Отнесите припасы Халге Кровавый Глаз на Дальнюю заставу в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снабжение Перекрестка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 ящиков с припасами с Перекрестка в пещере Иглогривых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите припасы Халге Кровавый Глаз на Дальнюю заставу в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5042,'Сила Агамаггана','Ах, если бы Кривозуб мог видеть, как ты наказал предавших его! <фыркает>$B$BБлагодарю тебя, ведь, собирая эти осколки, ты $Gубил:убила; еще нескольких иглогривов Дыбогривов. Продолжай в том же духе, и я вновь буду помогать тебе. <фыркает>','Если ты желаешь обрести силу Агамаггана, $R, принеси мне 4 кровавых осколка.$B$BВраги будут трепетать перед тобой, когда я благословлю тебя. <фыркает>$B$BЛишь величайшим воинам племени Иглогривых дарована такая сила!','Вернитесь к Кривозубу в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила Агамаггана',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, если бы Кривозуб мог видеть, как ты наказал предавших его! <фыркает>$B$BБлагодарю тебя, ведь, собирая эти осколки, ты $Gубил:убила; еще нескольких иглогривов Дыбогривов. Продолжай в том же духе, и я вновь буду помогать тебе. <фыркает>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты желаешь обрести силу Агамаггана, $R, принеси мне 4 кровавых осколка.$B$BВраги будут трепетать перед тобой, когда я благословлю тебя. <фыркает>$B$BЛишь величайшим воинам племени Иглогривых дарована такая сила!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривозубу в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5043,'Ловкость Агамаггана','Да будет верной твоя цель и метким оружие, |3-6($R).$B$BДух Агамаггана пребывает с тобой. <фыркает> Возвращайся, если захочешь. Кривозуб снова благословит тебя, если будет на то воля великого кабаньего бога. <фыркает>','Величайшие разведчики моего племени издавна отличались несравненной меткостью, и ни одному разбойнику <фыркает> даже и не снилась подобная стремительность в битве.$B$BПринеси мне 4 кровавых осколка, и превзойдешь ловкостью любого иглогрива.','Вернитесь к Кривозубу в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловкость Агамаггана',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да будет верной твоя цель и метким оружие, |3-6($R).$B$BДух Агамаггана пребывает с тобой. <фыркает> Возвращайся, если захочешь. Кривозуб снова благословит тебя, если будет на то воля великого кабаньего бога. <фыркает>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Величайшие разведчики моего племени издавна отличались несравненной меткостью, и ни одному разбойнику <фыркает> даже и не снилась подобная стремительность в битве.$B$BПринеси мне 4 кровавых осколка, и превзойдешь ловкостью любого иглогрива.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривозубу в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5044,'Мудрость Агамаггана','Теперь враги будут трепетать от одного твоего вида, |3-6($R). <фыркает>$B$BПоведай Кривозубу о своих битвах, когда мы встретимся в следующий раз – в этой жизни или в следующей. <фыркает>','Сила Агамаггана помогает шаманам и рудознатцам иглогривов <фыркает> в бою и во время проведения ритуалов.$B$BЕсли ты тоже желаешь обрести благословение Агамаггана, принеси мне 4 кровавых осколка, и Кривозуб тебе поможет. <фыркает>','Вернитесь к Кривозубу в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мудрость Агамаггана',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь враги будут трепетать от одного твоего вида, |3-6($R). <фыркает>$B$BПоведай Кривозубу о своих битвах, когда мы встретимся в следующий раз – в этой жизни или в следующей. <фыркает>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сила Агамаггана помогает шаманам и рудознатцам иглогривов <фыркает> в бою и во время проведения ритуалов.$B$BЕсли ты тоже желаешь обрести благословение Агамаггана, принеси мне 4 кровавых осколка, и Кривозуб тебе поможет. <фыркает>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривозубу в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5045,'Высокий дух','Наши величайшие воины и величайшие шаманы <фыркает> позавидовали бы твоей силе воли, |3-6($R).$B$BТеперь, зная, что иглогривам не остановить тебя, ты нанесешь еще больший урон племени Вздыбленной Щетины. <фыркает>','Высокий дух – благо для всех воинов. <фыркает> Он ведет к победе, даже когда надежды уже нет. Племя Иглогривых знает об этом. <фыркает> Мы ценим свою связь с Агамагганом больше доблести <фыркает> в бою.$B$BПринеси мне 4 кровавых осколка, и ты получишь благословение духа перед тем, как идти в бой. <фыркает>','Вернитесь к Кривозубу в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Высокий дух',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наши величайшие воины и величайшие шаманы <фыркает> позавидовали бы твоей силе воли, |3-6($R).$B$BТеперь, зная, что иглогривам не остановить тебя, ты нанесешь еще больший урон племени Вздыбленной Щетины. <фыркает>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Высокий дух – благо для всех воинов. <фыркает> Он ведет к победе, даже когда надежды уже нет. Племя Иглогривых знает об этом. <фыркает> Мы ценим свою связь с Агамагганом больше доблести <фыркает> в бою.$B$BПринеси мне 4 кровавых осколка, и ты получишь благословение духа перед тем, как идти в бой. <фыркает>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривозубу в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5046,'Иглошкура','В бой, |3-6($R)!','Идущему в бой <фыркает> защита не помешает. Кости должны быть крепкими, а шкура толстой. <фыркает> Мое племя отлично знает об этом, и, помимо дарованных нам от природы игл и толстой шкуры, <фыркает> мы защищаем себя и другими способами. Перед тем как идти на войну, мы просим Агамаггана защитить нас от урона.$B$BПринеси мне 4 кровавых осколка, <фыркает> и я дарую тебе ту же защиту.','Вернитесь к Кривозубу в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Иглошкура',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В бой, |3-6($R)!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Идущему в бой <фыркает> защита не помешает. Кости должны быть крепкими, а шкура толстой. <фыркает> Мое племя отлично знает об этом, и, помимо дарованных нам от природы игл и толстой шкуры, <фыркает> мы защищаем себя и другими способами. Перед тем как идти на войну, мы просим Агамаггана защитить нас от урона.$B$BПринеси мне 4 кровавых осколка, <фыркает> и я дарую тебе ту же защиту.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривозубу в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5047,'Айс Вентурон, к вашим услугам!','Разыщи Малифоя Черномолота в Круговзоре, |3-6($c). Скажи ему, что с Вентуроном все в порядке и что костюмчик исправно работает.$B$BИ передай ему вот что...$B$B<Вентурон вручает вам ярко светящийся кусок мяса.>$B$BЯ его вырезал из внутренностей одной зверюги во время своих вынужденных каникул.$B$BГотов поспорить, Малифой очень подробно тебе растолкует, что можно сделать с мясом этого чудища!$B$BКстати, ты знаешь, где Круговзор? Это в Зимних Ключах.','Переговорите с Малифоем Черномолотом в Круговзоре.','Он жив? Костюм цел? А что это там у тебя?','Да?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Айс Вентурон, к вашим услугам!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разыщи Малифоя Черномолота в Круговзоре, |3-6($c). Скажи ему, что с Вентуроном все в порядке и что костюмчик исправно работает.$B$BИ передай ему вот что...$B$B<Вентурон вручает вам ярко светящийся кусок мяса.>$B$BЯ его вырезал из внутренностей одной зверюги во время своих вынужденных каникул.$B$BГотов поспорить, Малифой очень подробно тебе растолкует, что можно сделать с мясом этого чудища!$B$BКстати, ты знаешь, где Круговзор? Это в Зимних Ключах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Переговорите с Малифоем Черномолотом в Круговзоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он жив? Костюм цел? А что это там у тебя?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5048,'Добросердечная Эмма','Это злобная старушенция и к тому же, весьма вероятно, уже с катушек съехала... Но записи указывают, что старушка Эмма как раз вполне может являться той самой Эммой Фелстоун.$b$bВозможно, вы видели старушку Эмму бредущей по городу – она разговаривает сама с собой, иногда неся совершенно невнятный вздор. Но она никому и ничему не мешает, так что горожане, в большинстве своем, оставили ее в покое.$b$bОбдумав все, я бы сказал, что старушка Эмма и в самом деле – Эмма Фелстоун. Можете сами спросить у нее, не Фелстоун ли ее фамилия.','Найдите в Штормграде старушку Эмму и узнайте, действительно ли она – Эмма Фелстоун. Если да, то, может, ей понравится та посылочка, что собрала для нее Джанис Фелстоун.','Мое имя и в самом деле Эмма Фелстоун – но меня впервые так называют за много лет. Кто... кто вы?$B$BВы говорите, что знали... мою сестру?! Она до сих пор жива? Да что это я – конечно же, нет. Когда чума охватила Лордерон, я ожидала самого худшего. Так много моих родственников погибло... или еще хуже того. И вот я здесь, сумасшедшая старушка Эмма, одна-одинешенька. Кто же вы – разоритель могил или что? Ищете следующую жертву?$B$BЧто... у вас посылка для меня от сестры?','Я поросила бы вас не топтать мою лужайку, но, как видите, у меня ее нет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добросердечная Эмма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это злобная старушенция и к тому же, весьма вероятно, уже с катушек съехала... Но записи указывают, что старушка Эмма как раз вполне может являться той самой Эммой Фелстоун.$b$bВозможно, вы видели старушку Эмму бредущей по городу – она разговаривает сама с собой, иногда неся совершенно невнятный вздор. Но она никому и ничему не мешает, так что горожане, в большинстве своем, оставили ее в покое.$b$bОбдумав все, я бы сказал, что старушка Эмма и в самом деле – Эмма Фелстоун. Можете сами спросить у нее, не Фелстоун ли ее фамилия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Штормграде старушку Эмму и узнайте, действительно ли она – Эмма Фелстоун. Если да, то, может, ей понравится та посылочка, что собрала для нее Джанис Фелстоун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мое имя и в самом деле Эмма Фелстоун – но меня впервые так называют за много лет. Кто... кто вы?$B$BВы говорите, что знали... мою сестру?! Она до сих пор жива? Да что это я – конечно же, нет. Когда чума охватила Лордерон, я ожидала самого худшего. Так много моих родственников погибло... или еще хуже того. И вот я здесь, сумасшедшая старушка Эмма, одна-одинешенька. Кто же вы – разоритель могил или что? Ищете следующую жертву?$B$BЧто... у вас посылка для меня от сестры?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я поросила бы вас не топтать мою лужайку, но, как видите, у меня ее нет.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5049,'Грусть Иеремии','Мне удалось выяснить, что тот, кого ты ищешь, – он же получатель посылки – это Иеремия Пейсон, продавец тараканов в Подгороде.$b$bМне всегда казалось, что для торговли тараканами нужны особые личные качества. Не сомневаюсь, тебя ждут великие дела, |3-6($c). Ступай, меняй мир к лучшему. Впрочем, позволь и мне поучаствовать в столь великих событиях и приоткрыть завесу тайны: он находится недалеко от банка, в стороне от одной из дорожек.','Найдите в Подгороде Иеремию Пейсона и выясните, в самом ли деле он Иеремия Фелстоун. Если да, передайте ему посылку от Джанис Фелстоун.','Я не пользовался этим именем много лет... Да, некогда, до того прекрасного момента, когда я влился в ряды нежити, меня так звали.$B$BТак ты $Gзнал:знала; мою сестру... или, точнее, недавно $Gговорил:говорила; с моей сестрой?$B$BОна умерла.$B$BЧетыре года назад.$B$BЗнаешь, не будь у меня такие хрупкие кости, я бы с радостью тебя пнул. Глумишься над чужим горем?$B$BЧто... у тебя посылка от моей сестры?!','Всякий раз, как кто-то наступает на таракана, я плачу. Не доводи меня до слез.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грусть Иеремии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне удалось выяснить, что тот, кого ты ищешь, – он же получатель посылки – это Иеремия Пейсон, продавец тараканов в Подгороде.$b$bМне всегда казалось, что для торговли тараканами нужны особые личные качества. Не сомневаюсь, тебя ждут великие дела, |3-6($c). Ступай, меняй мир к лучшему. Впрочем, позволь и мне поучаствовать в столь великих событиях и приоткрыть завесу тайны: он находится недалеко от банка, в стороне от одной из дорожек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Подгороде Иеремию Пейсона и выясните, в самом ли деле он Иеремия Фелстоун. Если да, передайте ему посылку от Джанис Фелстоун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не пользовался этим именем много лет... Да, некогда, до того прекрасного момента, когда я влился в ряды нежити, меня так звали.$B$BТак ты $Gзнал:знала; мою сестру... или, точнее, недавно $Gговорил:говорила; с моей сестрой?$B$BОна умерла.$B$BЧетыре года назад.$B$BЗнаешь, не будь у меня такие хрупкие кости, я бы с радостью тебя пнул. Глумишься над чужим горем?$B$BЧто... у тебя посылка от моей сестры?!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Всякий раз, как кто-то наступает на таракана, я плачу. Не доводи меня до слез.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5050,'Оберег удачи','Кажется, мое мнение насчет тебя было ошибочным и мне следует извиниться. Сестра прислала мне ряд личных вещей, в том числе – ха-ха – документы на ферму Фелстоун. Я пока не стану предъявлять на нее права.$b$bЕсли призрак моей сестры не может упокоиться и привязан к ферме... может быть, ты вернешь ей это? Это половина оберега; вторую носил ее муж.$b$bМожет быть, тогда она обретет покой?','Отнесите половинку талисмана Джанис Фелстоун в Западные Чумные земли.','Вы отдаете половинку талисмана призраку. Джанис выжидающе смотрит на вас.$B$B"Милый, а где твоя половина талисмана? Нам не быть вместе, не собрав его воедино. Милый... Ты меня видишь?"','Джон, милый... Это ты? Мне так холодно...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оберег удачи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, мое мнение насчет тебя было ошибочным и мне следует извиниться. Сестра прислала мне ряд личных вещей, в том числе – ха-ха – документы на ферму Фелстоун. Я пока не стану предъявлять на нее права.$b$bЕсли призрак моей сестры не может упокоиться и привязан к ферме... может быть, ты вернешь ей это? Это половина оберега; вторую носил ее муж.$b$bМожет быть, тогда она обретет покой?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите половинку талисмана Джанис Фелстоун в Западные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы отдаете половинку талисмана призраку. Джанис выжидающе смотрит на вас.$B$B"Милый, а где твоя половина талисмана? Нам не быть вместе, не собрав его воедино. Милый... Ты меня видишь?"',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Джон, милый... Это ты? Мне так холодно...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5051,'Вторая половина','Несчастный призрак продолжает причитать:$B$B"Мне холодно, Джон. Принеси мне свой оберег, и мы снова будем вместе! Скорее, Джон, пока чума не превратила нас в жутких тварей! Я не вижу тебя, Джон... Но знаю, ты рядом. Я чувствую."$b$bБыть может, если найти вторую половину оберега и собрать его воедино, душа Джанис Фелстоун обретет покой.','Отыщите вторую половину оберега удачи на ферме Фелстоун в Западных Чумных землях и соберите его.$b$bОтдайте оберег удачи Джанис Фелстоун.','Вы отдаете целый оберег Удачи призраку Джанис Фелстоун. Взяв его в руки, она моментально преображается. Призрачный облик слегка мерцает, а девушка устремляет на вас ясный, хоть и грустный, взор.$B$B"Ты освободил меня... Мне больше не нужен этот оберег. Возьми его, быть может он принесет тебе не меньшее утешение, чем мне."','Джон, не давайся в руки вурдалаков... Не отдавай им меня... Гнусные вурдалаки, оберег защитит нас.','Вернитесь к Джанис Фелстоун на Поле Джанис, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторая половина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несчастный призрак продолжает причитать:$B$B"Мне холодно, Джон. Принеси мне свой оберег, и мы снова будем вместе! Скорее, Джон, пока чума не превратила нас в жутких тварей! Я не вижу тебя, Джон... Но знаю, ты рядом. Я чувствую."$b$bБыть может, если найти вторую половину оберега и собрать его воедино, душа Джанис Фелстоун обретет покой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите вторую половину оберега удачи на ферме Фелстоун в Западных Чумных землях и соберите его.$b$bОтдайте оберег удачи Джанис Фелстоун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы отдаете целый оберег Удачи призраку Джанис Фелстоун. Взяв его в руки, она моментально преображается. Призрачный облик слегка мерцает, а девушка устремляет на вас ясный, хоть и грустный, взор.$B$B"Ты освободил меня... Мне больше не нужен этот оберег. Возьми его, быть может он принесет тебе не меньшее утешение, чем мне."',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Джон, не давайся в руки вурдалаков... Не отдавай им меня... Гнусные вурдалаки, оберег защитит нас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джанис Фелстоун на Поле Джанис, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5052,'Кровавые осколки Агамаггана','Кровь повлияла не только на шипы *фыркает*, но и на другие аспекты земли: среди прочих минералов попадаются кроваво-красные камни. Племя Дыбогривов выкапывает эти осколки и носит с собой как тотемы *фыркает*, и они дают им силы в бою и помогают творить заклинания. *фыркает*$B$BСекреты их магии мне известны.$B$BПринеси Кривозубу один кровавый осколок, и ты все поймешь. Принеси Кривозубу много осколков, и он благословит тебя. Сильна магия иглогривов, ведь это магия самого Агамаггана! *фыркает*','Принесите кровавый осколок Кривозубу в Лагерь Таурахо в Степи.$B$BСоберите побольше кровавых осколков, и он одарит вас силой, дарованной ему Агамагганом.','Да, ты понимаешь. фыркает Мои слова для тебя – не пустой звук, |3-6($R). Быть может, Кривозуб и заключен в клетку, но что клетка для силы Агамаггана! фыркает\n\nКасание осколка, какое забытое ощущение, |3-6($R). \n\nЗнаешь, каково это – чувствовать себя отрезанным от силы?\n\nНо об этом в другой раз. Я обещал поделиться с тобой сведениями. Я обещал тебе силу Агамаггана. Мой народ отвернулся от Кривозуба. Теперь они падут от твоей руки. фыркает','Наши племена селятся в тех областях Степей, где растут колючки, фыркает потому что это священные места. И первейшее из них – это земли Иглошкурых. Тело Агамаггана составляет все эти земли, но особенно хранимы холмы, потому что вход в них сделан из его огромной пасти! фыркает Она поглощает всех неверных и выплевывает их тела, когда он хорошенько прожует их! фыркает\n\nАгамагган оставил свое тело, чтобы защитить нас, и щедро делится своим духом, чтобы мы защищали его. фыркает','Вернитесь к Кривозубу в лагерь Таурахо, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровавые осколки Агамаггана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кровь повлияла не только на шипы *фыркает*, но и на другие аспекты земли: среди прочих минералов попадаются кроваво-красные камни. Племя Дыбогривов выкапывает эти осколки и носит с собой как тотемы *фыркает*, и они дают им силы в бою и помогают творить заклинания. *фыркает*$B$BСекреты их магии мне известны.$B$BПринеси Кривозубу один кровавый осколок, и ты все поймешь. Принеси Кривозубу много осколков, и он благословит тебя. Сильна магия иглогривов, ведь это магия самого Агамаггана! *фыркает*',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите кровавый осколок Кривозубу в Лагерь Таурахо в Степи.$B$BСоберите побольше кровавых осколков, и он одарит вас силой, дарованной ему Агамагганом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, ты понимаешь. фыркает Мои слова для тебя – не пустой звук, |3-6($R). Быть может, Кривозуб и заключен в клетку, но что клетка для силы Агамаггана! фыркает\n\nКасание осколка, какое забытое ощущение, |3-6($R). \n\nЗнаешь, каково это – чувствовать себя отрезанным от силы?\n\nНо об этом в другой раз. Я обещал поделиться с тобой сведениями. Я обещал тебе силу Агамаггана. Мой народ отвернулся от Кривозуба. Теперь они падут от твоей руки. фыркает',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наши племена селятся в тех областях Степей, где растут колючки, фыркает потому что это священные места. И первейшее из них – это земли Иглошкурых. Тело Агамаггана составляет все эти земли, но особенно хранимы холмы, потому что вход в них сделан из его огромной пасти! фыркает Она поглощает всех неверных и выплевывает их тела, когда он хорошенько прожует их! фыркает\n\nАгамагган оставил свое тело, чтобы защитить нас, и щедро делится своим духом, чтобы мы защищали его. фыркает',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кривозубу в лагерь Таурахо, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5053,'<UNUSED>','This quest will send you mail to your mail box. Just hit complete.','Test quest to see if mail is sent to your mailbox. Just hit complete, then go check your mail.$B$BHave a nice day.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','This quest will send you mail to your mail box. Just hit complete.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Test quest to see if mail is sent to your mailbox. Just hit complete, then go check your mail.$B$BHave a nice day.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5054,'Урсиус из щербозубов','В заснеженных горах Зимних Ключей, на северо-западе, умелый охотник идет по следу своей добычи... Я говорю о медведе-щербозубе Урсиусе – звере ловком и умном.$b$bЯ посылаю тебя в бой против него. Он бродит по холмам к северо-западу от Круговзора. Найди его и начни охоту на него – раньше, чем он поймет твои намерения.$b$bВсе, кто шли на Урсиуса, вскоре понимали, что они добыча, а отнюдь не охотники. Так что будь начеку.','По просьбе Шторма Призрачное Копыто в Круговзоре в Зимних Ключах убейте Урсиуса.','Вернитесь к Шторму Призрачное Копыто в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урсиус из щербозубов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В заснеженных горах Зимних Ключей, на северо-западе, умелый охотник идет по следу своей добычи... Я говорю о медведе-щербозубе Урсиусе – звере ловком и умном.$b$bЯ посылаю тебя в бой против него. Он бродит по холмам к северо-западу от Круговзора. Найди его и начни охоту на него – раньше, чем он поймет твои намерения.$b$bВсе, кто шли на Урсиуса, вскоре понимали, что они добыча, а отнюдь не охотники. Так что будь начеку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Шторма Призрачное Копыто в Круговзоре в Зимних Ключах убейте Урсиуса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шторму Призрачное Копыто в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5055,'Хладнокрылая Брумеран','Умная и ловкая Брумеран тихо скользит по заснеженным просторам южных окраин Зимних Ключей. Но пусть тебя не обманывает ее грация – она отнюдь не безопасна. Все, кто встает у нее на пути, расплачиваются за это – частенько своими собственными жизнями.$b$bНайди Брумеран среди хладнокрылых химер. Срази ее, а затем возвращайся ко мне.','Убейте Брумеран по просьбе Шторма Призрачное Копыто в Круговзоре в Зимних Ключах.','Вернитесь к Шторму Призрачное Копыто в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хладнокрылая Брумеран',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Умная и ловкая Брумеран тихо скользит по заснеженным просторам южных окраин Зимних Ключей. Но пусть тебя не обманывает ее грация – она отнюдь не безопасна. Все, кто встает у нее на пути, расплачиваются за это – частенько своими собственными жизнями.$b$bНайди Брумеран среди хладнокрылых химер. Срази ее, а затем возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Брумеран по просьбе Шторма Призрачное Копыто в Круговзоре в Зимних Ключах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шторму Призрачное Копыто в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5056,'Ши-Ротам','На севере Зимних Ключей, в районе, который называют Уступ Ледопардов, обитают огромные кошки. Их предводительница известна под именем Ши-Ротам. Если тебе удастся сразить матриарха ледопардов, ты завоюешь уважение в глазах своих сородичей.$b$bОтправляйся обратно в глушь. Придя на место, добудь священного мяса ледопардов. Найди камень Ши-Ротам и помести мясо на него. Мясо растерзанных подданных заставит их предводительницу Ши-Ротам явиться в гневе.$b$bБудь $gготов:готова; встретиться с ней лицом к лицу и сразить ее.','Убейте Ши-Ротам для Шторма Призрачное Копыто.','Вернитесь к Шторму Призрачное Копыто в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ши-Ротам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На севере Зимних Ключей, в районе, который называют Уступ Ледопардов, обитают огромные кошки. Их предводительница известна под именем Ши-Ротам. Если тебе удастся сразить матриарха ледопардов, ты завоюешь уважение в глазах своих сородичей.$b$bОтправляйся обратно в глушь. Придя на место, добудь священного мяса ледопардов. Найди камень Ши-Ротам и помести мясо на него. Мясо растерзанных подданных заставит их предводительницу Ши-Ротам явиться в гневе.$b$bБудь $gготов:готова; встретиться с ней лицом к лицу и сразить ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Ши-Ротам для Шторма Призрачное Копыто.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шторму Призрачное Копыто в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5057,'Прежние свершения','Еще раньше, чем вы пришли ко мне поговорить, $n, я слышал о ваших деяниях... что у вас есть непреодолимое желание проявить себя, что вы |3-6($c) с отменными способностями, и теперь я знаю, что все это было правдой.$b$bТе, кто добивается таких успехов, заслуживают признания. Отнесите этот знак в Громовой Утес моему другу Мелору Каменному Копыту. Уверен, что он вспомнит и вас, и ваши подвиги. Расскажите ему о своих недавних достижениях. И никогда не забывайте о том, что свершили сегодня.','Отнесите Знак Шторма Призрачное Копыто Мелору Каменное Копыто в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прежние свершения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще раньше, чем вы пришли ко мне поговорить, $n, я слышал о ваших деяниях... что у вас есть непреодолимое желание проявить себя, что вы |3-6($c) с отменными способностями, и теперь я знаю, что все это было правдой.$b$bТе, кто добивается таких успехов, заслуживают признания. Отнесите этот знак в Громовой Утес моему другу Мелору Каменному Копыту. Уверен, что он вспомнит и вас, и ваши подвиги. Расскажите ему о своих недавних достижениях. И никогда не забывайте о том, что свершили сегодня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Знак Шторма Призрачное Копыто Мелору Каменное Копыто в Громовой Утес.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5058,'Дневник миссис Далсон') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дневник миссис Далсон',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5059,'Под замком','С помощью ключа, найденного у скелета, бывшего когда-то миссис Далсон, вы отпираете дверь туалета. Оттуда выпрыгивает кровожадный вурдалак, запертый там неизвестно сколько времени.$B$BПо его чудовищному крику при виде вас становится очевидно, что фермера Далсона уже поздно спасать.','Дверь туалета затрещала от неистовых попыток ее выломать. Сейчас она заперта снаружи.$B$BПостучав по двери, вы услышали хриплый рык изнутри! Чтобы это ни было, оно явно недружелюбно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под замком',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С помощью ключа, найденного у скелета, бывшего когда-то миссис Далсон, вы отпираете дверь туалета. Оттуда выпрыгивает кровожадный вурдалак, запертый там неизвестно сколько времени.$B$BПо его чудовищному крику при виде вас становится очевидно, что фермера Далсона уже поздно спасать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дверь туалета затрещала от неистовых попыток ее выломать. Сейчас она заперта снаружи.$B$BПостучав по двери, вы услышали хриплый рык изнутри! Чтобы это ни было, оно явно недружелюбно.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5060,'Под замком','Вернитесь к запертому шкафу в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под замком',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к запертому шкафу в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5061,'Водный облик','Ты $Gзавершил:завершила; обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Матренгилу Медвежьей Лапе в Дарнас. Покажи ему свою подвеску и докажи, что ты $Gготов:готова; усвоить его уроки. Он завершит твое обучение, благодаря которому ты станешь $Gединым:единой; с водой.$B$BДоброго пути, $Gюный друид:дева-друид;. Мы еще встретимся.','Вернитесь в Дарнас и покажите Матренгилу Медвежьей Лапе свою подвеску Морского Льва.','Великолепно, $N. Ты $Gготов:готова; принимать водный облик, и я с радостью научу тебя.$B$BА также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это. Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия.','Весть о твоем возвращении в Дарнасс опередила тебя, хотя я хочу увидеть доказательства того, что ты $Gусвоил:усвоила; уроки Лунной поляны прежде, чем стану учить тебя принимать водный облик.$B$BЕсть ли у тебя подвеска Морского Льва?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Водный облик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gзавершил:завершила; обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик. Теперь возвращайся к своему наставнику, Матренгилу Медвежьей Лапе в Дарнас. Покажи ему свою подвеску и докажи, что ты $Gготов:готова; усвоить его уроки. Он завершит твое обучение, благодаря которому ты станешь $Gединым:единой; с водой.$B$BДоброго пути, $Gюный друид:дева-друид;. Мы еще встретимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Дарнас и покажите Матренгилу Медвежьей Лапе свою подвеску Морского Льва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, $N. Ты $Gготов:готова; принимать водный облик, и я с радостью научу тебя.$B$BА также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это. Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Весть о твоем возвращении в Дарнасс опередила тебя, хотя я хочу увидеть доказательства того, что ты $Gусвоил:усвоила; уроки Лунной поляны прежде, чем стану учить тебя принимать водный облик.$B$BЕсть ли у тебя подвеска Морского Льва?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5062,'Священное пламя','Арикара очень опасна, и мы должны как можно быстрее разделаться с ней. Для того чтобы привлечь это чудовище, тебе нужно будет разжечь священный огонь жизни.$B$BСобери немного редкой огненной агавы и отнеси ее Магате Зловещий Тотем. Она живет в Громовом Утесе, на Вершине Старейшин. Магата – очень могущественная шаманка, владеющая тайной приготовления зачарованного порошка из огненной агавы.$B$BОгненную агаву можно собрать на Кипящем озере, это к востоку отсюда.','Соберите 10 листов огненной агавы и поговорите с Магатой Зловещим Тотемом на Вершине Старейшин в Громовом Утесе.','Прекрасно, вы собрали достаточно огненной агавы. Эта редкая трава растет лишь в Тысяче Игл, и она поможет мне разбудить священное пламя жизни.$B$B<Магата начинает зачаровывать огненную агаву.>','Значит, Мотега Огненная Грива сообщает об Арикаре... Хм, это дурные вести.$B$B<Магата оглядывается вокруг.>$B$BАрикара – это смертоносная тварь, рожденная лишь для того, чтобы мстить тем, кто совершает злодеяния.$B$B<Магата улыбается.>','Вернитесь к Магате Зловещему Тотему в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священное пламя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Арикара очень опасна, и мы должны как можно быстрее разделаться с ней. Для того чтобы привлечь это чудовище, тебе нужно будет разжечь священный огонь жизни.$B$BСобери немного редкой огненной агавы и отнеси ее Магате Зловещий Тотем. Она живет в Громовом Утесе, на Вершине Старейшин. Магата – очень могущественная шаманка, владеющая тайной приготовления зачарованного порошка из огненной агавы.$B$BОгненную агаву можно собрать на Кипящем озере, это к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 листов огненной агавы и поговорите с Магатой Зловещим Тотемом на Вершине Старейшин в Громовом Утесе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, вы собрали достаточно огненной агавы. Эта редкая трава растет лишь в Тысяче Игл, и она поможет мне разбудить священное пламя жизни.$B$B<Магата начинает зачаровывать огненную агаву.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Значит, Мотега Огненная Грива сообщает об Арикаре... Хм, это дурные вести.$B$B<Магата оглядывается вокруг.>$B$BАрикара – это смертоносная тварь, рожденная лишь для того, чтобы мстить тем, кто совершает злодеяния.$B$B<Магата улыбается.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Магате Зловещему Тотему в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5063,'Шапка Алого Ученого','Головного убора лучше этого тебе, быть может, и не придется увидеть. Из безупречной звериной шкуры наши опытные мастера изготовят потрясающую шляпу, о какой может только мечтать любой иллюзионист!$b$bПятьдесят золотых и предметы по списку – и твою голову украсит шапка Алого Ученого.$b$b*Безупречная звериная шкура.$B$B*Истлевшая шовная нить поганища.$B$B*Чародейские кристаллы.$B$B*Зачарованная алая нить.$B$BИ УЗРИШЬ ТЫ ЧУДО!','Для изготовления шапки Алого Ученого вам нужно принести Малифою Черномолоту 1 Безупречную звериную шкуру; 5 истлевших шовных нитей поганища; 8 чародейских кристаллов; 5 зачарованных алых нитей. $B$BВы также должны будете уплатить 50 золотых монет за изготовление головного убора.','Изумительно! Мне бы потребовались недели, чтобы собрать все это... и как тебе удалось найти нетронутую звериную шкуру?!$B$BНоси с удовольствием, $N!','Если у тебя нет всего, что мне нужно, ты зря тратишь мое время.','Вернитесь к Малифому Черномолоту в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шапка Алого Ученого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Головного убора лучше этого тебе, быть может, и не придется увидеть. Из безупречной звериной шкуры наши опытные мастера изготовят потрясающую шляпу, о какой может только мечтать любой иллюзионист!$b$bПятьдесят золотых и предметы по списку – и твою голову украсит шапка Алого Ученого.$b$b*Безупречная звериная шкура.$B$B*Истлевшая шовная нить поганища.$B$B*Чародейские кристаллы.$B$B*Зачарованная алая нить.$B$BИ УЗРИШЬ ТЫ ЧУДО!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Для изготовления шапки Алого Ученого вам нужно принести Малифою Черномолоту 1 Безупречную звериную шкуру; 5 истлевших шовных нитей поганища; 8 чародейских кристаллов; 5 зачарованных алых нитей. $B$BВы также должны будете уплатить 50 золотых монет за изготовление головного убора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Изумительно! Мне бы потребовались недели, чтобы собрать все это... и как тебе удалось найти нетронутую звериную шкуру?!$B$BНоси с удовольствием, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя нет всего, что мне нужно, ты зря тратишь мое время.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малифому Черномолоту в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5064,'Наблюдение за Зловещим Тотемом','$n, ты уже $gпомог:помогла; нам, поэтому я доверю тебе еще одно важное задание. Клан Зловещий Тотем явно что-то замышляет: недавно мы видели, как в их поселение приходили какие-то странные путники. Потом нам удалось узнать, что важные записи они хранят в трех разных сундуках Пика Темного Облака.$B$BЕсли тебе удастся достать эти документы, я щедро тебя вознагражу.','Найдите и заберите три тайные записки на Пике Темного Облака.','Вы выяснили, что задумал клан Зловещего Тотема?','Вернитесь к дозорному утесов Долгорогу на Заставу Вольного Ветра, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наблюдение за Зловещим Тотемом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты уже $gпомог:помогла; нам, поэтому я доверю тебе еще одно важное задание. Клан Зловещий Тотем явно что-то замышляет: недавно мы видели, как в их поселение приходили какие-то странные путники. Потом нам удалось узнать, что важные записи они хранят в трех разных сундуках Пика Темного Облака.$B$BЕсли тебе удастся достать эти документы, я щедро тебя вознагражу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и заберите три тайные записки на Пике Темного Облака.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы выяснили, что задумал клан Зловещего Тотема?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному утесов Долгорогу на Заставу Вольного Ветра, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5065,'Утраченные таблички Мошару','Тот тролль обманул тебя. В тех двух табличках шла речь о пленении сущности Хаккара, но легенда этим не исчерпывается. Я долго изучал этот вопрос, и обнаружил, что табличек Мошару шесть, а не две! Шесть!$b$bИ боюсь, нас не порадует то, что в них записано.$b$bНайди третью и четвертую таблички. Они находятся в Восточных Чумных землях, у троллей из племени Моходеров. Найди их и принеси мне.','Принесите третью и четвертую таблички Мошару геологу Железному Башмаку в Танарис.','Ты $Gнашел:нашла; их! Отлично!$B$BСпасибо, $N. Я изучу эти тексты и расшифрую их значение.$B$BДля тебя же у меня есть еще одно задание...','Ты $Gпринес:принесла; мне таблички? Боюсь, в них написано о великой опасности, грозящей нашему миру.','Вернитесь к геологу Железному Башмаку в Порт Хитрой Шестеренки, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утраченные таблички Мошару',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тот тролль обманул тебя. В тех двух табличках шла речь о пленении сущности Хаккара, но легенда этим не исчерпывается. Я долго изучал этот вопрос, и обнаружил, что табличек Мошару шесть, а не две! Шесть!$b$bИ боюсь, нас не порадует то, что в них записано.$b$bНайди третью и четвертую таблички. Они находятся в Восточных Чумных землях, у троллей из племени Моходеров. Найди их и принеси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите третью и четвертую таблички Мошару геологу Железному Башмаку в Танарис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gнашел:нашла; их! Отлично!$B$BСпасибо, $N. Я изучу эти тексты и расшифрую их значение.$B$BДля тебя же у меня есть еще одно задание...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне таблички? Боюсь, в них написано о великой опасности, грозящей нашему миру.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Железному Башмаку в Порт Хитрой Шестеренки, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5066,'Призыв к оружию: Чумные земли!','Слушайте, слушайте все! Я обращаюсь к героям, и да услышат они мою речь!$B$BКороль Штормграда призывает к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Стало известно, что над Чумными землями вновь сгущаются тучи!$B$BГерои королевства! Ищите командира Ашлама Неутомимого! Его гарнизон вы найдете в Лагере Промозглого Ветра на севере Альтеракских гор!','Найдите командира Ашлама Неутомимого в Лагере Промозглого Ветра на севере Альтеракских гор.','Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Чумные земли!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушайте, слушайте все! Я обращаюсь к героям, и да услышат они мою речь!$B$BКороль Штормграда призывает к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Стало известно, что над Чумными землями вновь сгущаются тучи!$B$BГерои королевства! Ищите командира Ашлама Неутомимого! Его гарнизон вы найдете в Лагере Промозглого Ветра на севере Альтеракских гор!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите командира Ашлама Неутомимого в Лагере Промозглого Ветра на севере Альтеракских гор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5067,'Поножи Тайны','В то время как изготовление такого предмета еще никому не удавалось, считается, что это все же возможно – при удачном стечении обстоятельств.$b$bЕсли искатель тайных знаний желает наделить поножи могучей силой, вот что должно быть найдено:$b$b*Безупречная звериная шкура.$B$B*Истлевшая шовная нить поганища.$B$B*Арканитовые Слитки.$B$B*Бальзамировочный состав Ледяного Шепота.$B$BИ УЗРИШЬ ТЫ ЧУДО!','Для изготовления поножей Тайны вам нужно принести Малифою Черномолоту следующее: 1 безупречную звериную шкуру; 5 истлевших шовных нитей поганища, 5 арканитовых слитков, 5 порций бальзамировочного состава Ледяного Шепота; $B$BВам придется также заплатить 50 золотых монет за изготовление этого предмета.','Никогда не видел лучших поножей! Носи с удовольствием!','Если у тебя нет всего, что мне нужно, ты зря тратишь мое время.','Вернитесь к Малифому Черномолоту в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поножи Тайны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В то время как изготовление такого предмета еще никому не удавалось, считается, что это все же возможно – при удачном стечении обстоятельств.$b$bЕсли искатель тайных знаний желает наделить поножи могучей силой, вот что должно быть найдено:$b$b*Безупречная звериная шкура.$B$B*Истлевшая шовная нить поганища.$B$B*Арканитовые Слитки.$B$B*Бальзамировочный состав Ледяного Шепота.$B$BИ УЗРИШЬ ТЫ ЧУДО!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Для изготовления поножей Тайны вам нужно принести Малифою Черномолоту следующее: 1 безупречную звериную шкуру; 5 истлевших шовных нитей поганища, 5 арканитовых слитков, 5 порций бальзамировочного состава Ледяного Шепота; $B$BВам придется также заплатить 50 золотых монет за изготовление этого предмета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Никогда не видел лучших поножей! Носи с удовольствием!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя нет всего, что мне нужно, ты зря тратишь мое время.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малифому Черномолоту в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5068,'Кираса кровавой жажды','Говорят, что кираса кровавой жажды была создана лишь один раз, и изготовлена она была для легендарной убийцы Гароны. Суждено ли еще одному подобному доспеху увидеть свет? Сомнительно...$b$bИ все же! Наши мастера могут воспроизвести этот доспех, если дать им необходимые компоненты:$b$b*Безупречную звериную шкуру.$B$B*Истлевшая шовная нить поганища.$B$B*Арканитовые Слитки.$B$B*Шкуру тени.$B$BИ УЗРИШЬ ТЫ ЧУДО!','Для изготовления кирасы кровавой жажды вам нужно будет принести Малифою Чернобойцу следующее: 1 безупречную звериную шкуру; 10 истлевших шовных нитей поганища; 5 арканитовых слитков; 5 шкур тени.$B$BВы также должны будете уплатить 50 золотых монет за изготовление доспеха.','Я уж думал, что не доживу до этого дня.$B$BДостижение такого масштаба может превзойти лишь награда за него.','Если у тебя нет всего, что мне нужно, ты зря тратишь мое время.','Вернитесь к Малифому Черномолоту в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кираса кровавой жажды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что кираса кровавой жажды была создана лишь один раз, и изготовлена она была для легендарной убийцы Гароны. Суждено ли еще одному подобному доспеху увидеть свет? Сомнительно...$b$bИ все же! Наши мастера могут воспроизвести этот доспех, если дать им необходимые компоненты:$b$b*Безупречную звериную шкуру.$B$B*Истлевшая шовная нить поганища.$B$B*Арканитовые Слитки.$B$B*Шкуру тени.$B$BИ УЗРИШЬ ТЫ ЧУДО!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Для изготовления кирасы кровавой жажды вам нужно будет принести Малифою Чернобойцу следующее: 1 безупречную звериную шкуру; 10 истлевших шовных нитей поганища; 5 арканитовых слитков; 5 шкур тени.$B$BВы также должны будете уплатить 50 золотых монет за изготовление доспеха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уж думал, что не доживу до этого дня.$B$BДостижение такого масштаба может превзойти лишь награда за него.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя нет всего, что мне нужно, ты зря тратишь мое время.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малифому Черномолоту в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5081,'Миссия Максвелла','Эти сведения заполняют последние пробелы в наших данных о Пике Черной горы.$b$bМы должны напасть со всей решительностью, $n.$b$BПервым делом нужно убить их воеводу, Вуна. Без его боевых планов орки Черной горы будут ввергнуты в хаос.$b$BСледом должен умереть вождь огров, Омокк. Трусливые огры Черной горы окажутся беспомощны.$b$bИ, наконец, повелитель всей цитадели зла: Змейталак. Когда он умрет, командование будет обезглавлено.','Отправляйтесь на Пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака.','Отличная работа, $N. По меньшей мере нам удалось выиграть время – а на счету каждая минута.','Статус?','Вернитесь к маршалу Максвеллу в Дозор Морганы, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Миссия Максвелла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти сведения заполняют последние пробелы в наших данных о Пике Черной горы.$b$bМы должны напасть со всей решительностью, $n.$b$BПервым делом нужно убить их воеводу, Вуна. Без его боевых планов орки Черной горы будут ввергнуты в хаос.$b$BСледом должен умереть вождь огров, Омокк. Трусливые огры Черной горы окажутся беспомощны.$b$bИ, наконец, повелитель всей цитадели зла: Змейталак. Когда он умрет, командование будет обезглавлено.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Пик Черной горы и устраните воеводу Вуна, вождя Омокка и повелителя Змейталака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. По меньшей мере нам удалось выиграть время – а на счету каждая минута.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Статус?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Максвеллу в Дозор Морганы, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5082,'Угроза со стороны Зимней Спячки','Сюда в Зимние Ключи я пришла, чтобы изучать Источники ледяного огня. Я заметила, что у воды здесь какие-то... странные свойства. Мне пока не удалось определить источник этих свойств, да и, по правде говоря, в последнее время у меня возникли кое-какие сложности, из-за фурболгов племени Зимней Спячки.$b$bИх, кажется, тянет к источникам – так же, как и меня. Они яростно защищают воду и не подпускают меня близко к двум большим ключам к северу отсюда.$b$bЯ хотела бы продолжить свои изыскания. Ты не поможешь мне?','По просьбе Доновы Снегоноры из Зимних Ключей убейте 8 землепроходцев, 8 дозорных и 8 тотемистов из племени Зимней Спячки.','Вернитесь к Донове Снегоноре в Зимние Ключи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза со стороны Зимней Спячки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сюда в Зимние Ключи я пришла, чтобы изучать Источники ледяного огня. Я заметила, что у воды здесь какие-то... странные свойства. Мне пока не удалось определить источник этих свойств, да и, по правде говоря, в последнее время у меня возникли кое-какие сложности, из-за фурболгов племени Зимней Спячки.$b$bИх, кажется, тянет к источникам – так же, как и меня. Они яростно защищают воду и не подпускают меня близко к двум большим ключам к северу отсюда.$b$bЯ хотела бы продолжить свои изыскания. Ты не поможешь мне?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Доновы Снегоноры из Зимних Ключей убейте 8 землепроходцев, 8 дозорных и 8 тотемистов из племени Зимней Спячки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Донове Снегоноре в Зимние Ключи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5083,'Огненная вода Зимней Спячки','Тот сосуд, что вы нашли у фурболга племени Зимней Спячки, пуст, но внутри осталось несколько капель странной зеленой жидкости. Он почти сияет.$b$bОбнаружили ли вы нечто важное?$b$bВозможно, Донова Снегонора могла бы что-то вам разъяснить, поскольку она уже довольно давно живет у горячих ключей.','Принесите Донове Снегоноре пустую флягу из-под огненной воды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огненная вода Зимней Спячки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тот сосуд, что вы нашли у фурболга племени Зимней Спячки, пуст, но внутри осталось несколько капель странной зеленой жидкости. Он почти сияет.$b$bОбнаружили ли вы нечто важное?$b$bВозможно, Донова Снегонора могла бы что-то вам разъяснить, поскольку она уже довольно давно живет у горячих ключей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Донове Снегоноре пустую флягу из-под огненной воды.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5084,'Поддавшиеся порче','Зеленая жидкость... немного напоминает мне жижу, которую я видела, когда пробиралась через Оскверненный лес. И я видела несколько гонцов племени Зимней Спячки, входящих во владения Древобрюхов... Возможно, это имеет отношение к той склянке, что вы нашли, $n.$b$bСразу за Крепостью Древобрюхов, в Оскверненном лесу, живет большая группа фурболгов. Они зовутся племенем Мертвого Леса, и давно попали под власть скверны. Да, фурболги этого племени совершенно безумны. Может, сходишь и поищешь свидетельства того, что между племенами Зимней Спячки и Мертвого Леса есть какое-то сообщение?','Исследуйте поселение фурболгов племени Мертвого Леса в северной части Оскверненного леса в поисках ключа к разгадке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддавшиеся порче',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зеленая жидкость... немного напоминает мне жижу, которую я видела, когда пробиралась через Оскверненный лес. И я видела несколько гонцов племени Зимней Спячки, входящих во владения Древобрюхов... Возможно, это имеет отношение к той склянке, что вы нашли, $n.$b$bСразу за Крепостью Древобрюхов, в Оскверненном лесу, живет большая группа фурболгов. Они зовутся племенем Мертвого Леса, и давно попали под власть скверны. Да, фурболги этого племени совершенно безумны. Может, сходишь и поищешь свидетельства того, что между племенами Зимней Спячки и Мертвого Леса есть какое-то сообщение?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте поселение фурболгов племени Мертвого Леса в северной части Оскверненного леса в поисках ключа к разгадке.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5085,'Таинственная слизь','Зеленая субстанция внутри котла кажется точно такой же, какую вы обнаружили в сосуде. Это странное слизистое вещество может оказаться таким же полным скверны, как и фурболги, что его изготовили...$b$bЕсли фурболги племени Зимней Спячки его используют, значит ли это, что вскоре они окажутся в таком же состоянии, как и племя Мертвого леса?$b$bЛучше всего сообщить об этих находках Донове, прихватив и образец жидкости из котла.','Вернитесь к Донове и сообщите ей о своих находках.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Таинственная слизь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зеленая субстанция внутри котла кажется точно такой же, какую вы обнаружили в сосуде. Это странное слизистое вещество может оказаться таким же полным скверны, как и фурболги, что его изготовили...$b$bЕсли фурболги племени Зимней Спячки его используют, значит ли это, что вскоре они окажутся в таком же состоянии, как и племя Мертвого леса?$b$bЛучше всего сообщить об этих находках Донове, прихватив и образец жидкости из котла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Донове и сообщите ей о своих находках.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5086,'Ядовитый Ужас','Я изучила образцы, с которыми вы вернулись, и хотя точно пока ничего сказать не могу, я думаю, что в них есть следы ядовитых компонентов. Однако единственный способ узнать наверняка – это найти что-то для сравнения.$b$bЯ думаю, что фурболги Мертвого Леса могут собирать эти компоненты с других зараженных скверной существ в Оскверненном лесу: в частности, с элементалей, населяющих Железнолесье, которых называют ядовитым ужасом.$b$bСобери для меня несколько образцов для сравнения, но будь $gосторожен:осторожна; – там очень опасно!','Соберите 3 капли ядовитого ужаса и принесите их Донове Снегоноре в Зимние Ключи.','Вернитесь к Донове Снегоноре в Зимние Ключи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ядовитый Ужас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я изучила образцы, с которыми вы вернулись, и хотя точно пока ничего сказать не могу, я думаю, что в них есть следы ядовитых компонентов. Однако единственный способ узнать наверняка – это найти что-то для сравнения.$b$bЯ думаю, что фурболги Мертвого Леса могут собирать эти компоненты с других зараженных скверной существ в Оскверненном лесу: в частности, с элементалей, населяющих Железнолесье, которых называют ядовитым ужасом.$b$bСобери для меня несколько образцов для сравнения, но будь $gосторожен:осторожна; – там очень опасно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 капли ядовитого ужаса и принесите их Донове Снегоноре в Зимние Ключи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Донове Снегоноре в Зимние Ключи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5087,'Гонцы Зимней Спячки','Очень интересно, $n...$b$bЕсли эту ядовитую субстанцию смешать с водой из горячих ключей, она потеряет свою токсичность, и остается лишь способность временно воздействовать на тех, кто такую смесь употребляет. Наверное, из-за этого племя Зимней Спячки и защищает источники столь яростно: они необходимы фурболгам для очистки огненной воды.$b$bМы должны положить этому конец: прекратить контакты между племенами Зимней Спячки и Мертвого Леса. Группа гонцов курсирует между поселением Зимней Спячки и Оскверненным лесом. Найди их, убей и забери то, что у них будет с собой.','Найдите гонцов из племени Зимней Спячки и не позвольте им донести их груз до их деревни.','Вернитесь к Донове Снегоноре в Зимние Ключи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гонцы Зимней Спячки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Очень интересно, $n...$b$bЕсли эту ядовитую субстанцию смешать с водой из горячих ключей, она потеряет свою токсичность, и остается лишь способность временно воздействовать на тех, кто такую смесь употребляет. Наверное, из-за этого племя Зимней Спячки и защищает источники столь яростно: они необходимы фурболгам для очистки огненной воды.$b$bМы должны положить этому конец: прекратить контакты между племенами Зимней Спячки и Мертвого Леса. Группа гонцов курсирует между поселением Зимней Спячки и Оскверненным лесом. Найди их, убей и забери то, что у них будет с собой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите гонцов из племени Зимней Спячки и не позвольте им донести их груз до их деревни.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Донове Снегоноре в Зимние Ключи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (5088,'Арикара','Возьмите этот зачарованный порошок и зажгите священный огонь жизни в Тысяче Игл. Сделать это нужно на Пике Темного Облака, на отдельной скале, где находится местное кладбище.$B$BЯ зачаровала порошок так, чтобы он привлек Арикару, $n.$B$BБоюсь, что она охотится за Кэрном Кровавым Копытом – из-за него обычаи тауренов претерпели слишком много изменений, и это могло разозлить чудовище. Поспешите, |3-6($c), вы можете не успеть!','Убейте Арикару и в качестве доказательства принесите ее останки вместе с воспламеняющим порошком Мотеге Огненной Гриве на заставу Белого Плеса.','Ерунда какая-то. Зачем Арикаре охотиться за Кэрном Кровавым Копытом? Но Магата не может ошибаться, она наша самая могущественная шаманка.\n\nМотега качает головой.\n\nВ любом случае, вы очень помогли Орде, и деяние ваше не останется незамеченным. Пожалуйста, выберите себе любую награду.','Зажгите священный огонь жизни.','Вернитесь к Мотеге Огненной Гриве на Заставу Белого Плеса, что в Тысяче Игл.','Зажгите священный огонь жизни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арикара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьмите этот зачарованный порошок и зажгите священный огонь жизни в Тысяче Игл. Сделать это нужно на Пике Темного Облака, на отдельной скале, где находится местное кладбище.$B$BЯ зачаровала порошок так, чтобы он привлек Арикару, $n.$B$BБоюсь, что она охотится за Кэрном Кровавым Копытом – из-за него обычаи тауренов претерпели слишком много изменений, и это могло разозлить чудовище. Поспешите, |3-6($c), вы можете не успеть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Арикару и в качестве доказательства принесите ее останки вместе с воспламеняющим порошком Мотеге Огненной Гриве на заставу Белого Плеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ерунда какая-то. Зачем Арикаре охотиться за Кэрном Кровавым Копытом? Но Магата не может ошибаться, она наша самая могущественная шаманка.\n\nМотега качает головой.\n\nВ любом случае, вы очень помогли Орде, и деяние ваше не останется незамеченным. Пожалуйста, выберите себе любую награду.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Зажгите священный огонь жизни.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мотеге Огненной Гриве на Заставу Белого Плеса, что в Тысяче Игл.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Зажгите священный огонь жизни.',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5089,'Распоряжения генерала Драккисата','Вы обыскали труп убитого драконида и обнаружили записку, содержание которой показалось вам важным: письмо от его непосредственного начальника, генерала Драккисата, в котором упоминается некий протокол.$B$BВнутренний голос подсказывает, что это письмо следует показать маршалу Максвеллу.','Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи.','Мда... теперь все усложняется...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распоряжения генерала Драккисата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы обыскали труп убитого драконида и обнаружили записку, содержание которой показалось вам важным: письмо от его непосредственного начальника, генерала Драккисата, в котором упоминается некий протокол.$B$BВнутренний голос подсказывает, что это письмо следует показать маршалу Максвеллу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите приказ генерала Драккисата маршалу Максвеллу в Пылающие степи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мда... теперь все усложняется...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5090,'Призыв к оружию: Чумные земли!','Слушайте все! Все герои – слушайте!$B$BШтормград призывает всех к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Новая опасность надвигается из руин Чумных земель!$B$BГерои королевства – собирайтесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра к северу от Альтеракских гор!','Разыщите командира Ашлама Неутомимого в Лагере Промозглого Ветра к северу от Альтеракских гор.','Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Чумные земли!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушайте все! Все герои – слушайте!$B$BШтормград призывает всех к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Новая опасность надвигается из руин Чумных земель!$B$BГерои королевства – собирайтесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра к северу от Альтеракских гор!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите командира Ашлама Неутомимого в Лагере Промозглого Ветра к северу от Альтеракских гор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5091,'Призыв к оружию: Чумные земли!','Слушайте все! Все герои – слушайте!$B$BШтормград призывает всех к оружию! Все, кто способен держать оружие, – на защиту севера Восточных королевств против черной угрозы Плети! Новая опасность надвигается из руин Чумных земель!$B$BГерои королевства – собирайтесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра к северу от Альтеракских гор!','Разыщите командира Ашлама Неутомимого в Лагере Промозглого Ветра к северу от Альтеракских гор.','Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Чумные земли!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушайте все! Все герои – слушайте!$B$BШтормград призывает всех к оружию! Все, кто способен держать оружие, – на защиту севера Восточных королевств против черной угрозы Плети! Новая опасность надвигается из руин Чумных земель!$B$BГерои королевства – собирайтесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра к северу от Альтеракских гор!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите командира Ашлама Неутомимого в Лагере Промозглого Ветра к северу от Альтеракских гор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (5092,'Зачистка территории','Поскольку западная и северная дороги, ведущие в Андорал, хорошо укреплены, я подумываю о нападении с востока, как наименее защищенной стороны. Плеть рассчитывает на защиту нежити, наводнившей холм Печали.$b$bПервым заданием будет зачистка холма Печали. Убей побольше скелетов и вурдалаков; по выполнении задания возвращайся ко мне!','Убейте 10 скелетов-живодеров и 10 слюнявых вурдалаков на холме Печали.$b$bВернитесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра в Западных Чумных землях.','Задание выполнено, $n! Отлично, отлично!$B$BПозволь наградить тебя за труды звонкой монетой из казны Штормграда. Советую потратить награду на подготовку к следующей битве... Ведь тебе придется войти в руины Андорала.$B$BГотовься! Будь бдителен!','Вернитесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка территории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поскольку западная и северная дороги, ведущие в Андорал, хорошо укреплены, я подумываю о нападении с востока, как наименее защищенной стороны. Плеть рассчитывает на защиту нежити, наводнившей холм Печали.$b$bПервым заданием будет зачистка холма Печали. Убей побольше скелетов и вурдалаков; по выполнении задания возвращайся ко мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 скелетов-живодеров и 10 слюнявых вурдалаков на холме Печали.$b$bВернитесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Задание выполнено, $n! Отлично, отлично!$B$BПозволь наградить тебя за труды звонкой монетой из казны Штормграда. Советую потратить награду на подготовку к следующей битве... Ведь тебе придется войти в руины Андорала.$B$BГотовься! Будь бдителен!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5093,'Призыв к оружию: Чумные земли!','Внимайте моим словам, о герои! Орда призывает к решительным действиям!$b$bВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.$b$bХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лесов!','Отыщите верховного палача Деррингтона. Его базовый лагерь находится у Бастиона, к востоку от Тирисфальских лесов и Подгорода.','Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Чумные земли!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимайте моим словам, о герои! Орда призывает к решительным действиям!$b$bВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.$b$bХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лесов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите верховного палача Деррингтона. Его базовый лагерь находится у Бастиона, к востоку от Тирисфальских лесов и Подгорода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Чумные земли, герой. Здесь одна из самых опасных границ Азерота, тем более когда с севера и северо-востока нам грозит Плеть. Я рад слышать, что зов долга и служения великому добру прозвучал не напрасно!$B$BЕсли вы готовы к тяжелому труду, то на краю Чумных земель всем героям найдется дело.',`offerrewardtext_loc8`);
