INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5206,'Мародеры Дарроушира','Хроми утверждает, что собранные тобой реликвии могут служить реагентами для мощных чар. Однако требуется еще один ингредиент: черепа воинов Плети, участвовавших в битве при Дарроушире.$B$BВозьми этот кристалл и отправляйся за черепами лучших воителей Плети. Кристалл заколдован: он резонирует, если поднести его к черепу воителя, участвовавшего в битве.$B$BИди, $n. Ты найдешь воителей Плети на Ядовитой поляне к северу отсюда и в Грибной долине на западе.','Принесите 5 резонирующих черепов и загадочный кристалл Карлину Редпату в Восточные Чумные земли.','Отлично, у нас есть черепа!$B$BХоть я и не совсем понимаю, зачем именно они нужны, я чувствую исходящую от них силу и то, что они связаны с моей родной деревней, Дарроушир.','Ты $Gпринес:принесла; черепа? Хроми говорит, они необходимы для заклятия, а заклятие поможет нам спасти Дарроушир.','Вернитесь к Карлину Редпату в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мародеры Дарроушира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хроми утверждает, что собранные тобой реликвии могут служить реагентами для мощных чар. Однако требуется еще один ингредиент: черепа воинов Плети, участвовавших в битве при Дарроушире.$B$BВозьми этот кристалл и отправляйся за черепами лучших воителей Плети. Кристалл заколдован: он резонирует, если поднести его к черепу воителя, участвовавшего в битве.$B$BИди, $n. Ты найдешь воителей Плети на Ядовитой поляне к северу отсюда и в Грибной долине на западе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 резонирующих черепов и загадочный кристалл Карлину Редпату в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, у нас есть черепа!$B$BХоть я и не совсем понимаю, зачем именно они нужны, я чувствую исходящую от них силу и то, что они связаны с моей родной деревней, Дарроушир.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; черепа? Хроми говорит, они необходимы для заклятия, а заклятие поможет нам спасти Дарроушир.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлину Редпату в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
