INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5210,'Брат Карлин','С помощью магии я дополнила Анналы Дарроушира – теперь они содержат сведения и о том, что случилось после битвы. И там говорится, что еще один из рода Редпатов пережил предательство Джозефа. Его имя Карлин, он сейчас в восточных пределах Чумных земель, в Часовне Последней Надежды.$B$BОтправляйся к нему и передай ему книгу.','Отнесите дополненные Анналы Дарроушира Карлину Редпату в Восточные Чумные земли.','Что это за книга? Анналы Дарроушира? О, там был мой дом... пока не пришла Плеть! Зачем ты $Gпринес:принесла; мне эту книгу?$B$BЧто это? Смотри, на последних страницах рассказывается о том, что случилось уже после битвы! Здесь говорится и обо мне, и о моем брате Джозефе... Неужели это правда?$B$BЯ должен знать!','Ты $Gпришел:пришла; с запада? Что там происходит? Я знаю, что Андорал пал, но добралось ли воинство Плети до Тирисфаля?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брат Карлин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С помощью магии я дополнила Анналы Дарроушира – теперь они содержат сведения и о том, что случилось после битвы. И там говорится, что еще один из рода Редпатов пережил предательство Джозефа. Его имя Карлин, он сейчас в восточных пределах Чумных земель, в Часовне Последней Надежды.$B$BОтправляйся к нему и передай ему книгу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите дополненные Анналы Дарроушира Карлину Редпату в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это за книга? Анналы Дарроушира? О, там был мой дом... пока не пришла Плеть! Зачем ты $Gпринес:принесла; мне эту книгу?$B$BЧто это? Смотри, на последних страницах рассказывается о том, что случилось уже после битвы! Здесь говорится и обо мне, и о моем брате Джозефе... Неужели это правда?$B$BЯ должен знать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпришел:пришла; с запада? Что там происходит? Я знаю, что Андорал пал, но добралось ли воинство Плети до Тирисфаля?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5211,'Защитники Дарроушира','Многие защищавшие Дарроушир пали в битве. И многие из них восстали из мертвых, примкнув к Плети! Ты $gдолжен:должна; отыскать эти несчастные души и избавить их от страданий.$B$BКаннибалы-вурдалаки, бормочущие вурдалаки, болезненные живодеры – многие из них были добрыми жителями Дарроушира. Уничтожив их тела, ты освободишь их души.$B$BТы найдешь их в Чумном лесу, Перекрестке Корина и прочих опорных пунктах Плети в Восточных Чумных землях.','Освободите 15 духов Дарроушира и возвращайтесь к Карлину Редпату.','Рад слышать, что истерзанные души моих сородичей с твоей помощью обрели свободу. Ты пролил бальзам на мои раны – теперь я знаю, что хоть кто-то из моих павших сородичей освободился от ига Плети.','Бедные защитники Дарроушира взывают ко мне во сне, $N. Вы должны освободить их!','Вернитесь к Карлину Редпату в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитники Дарроушира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие защищавшие Дарроушир пали в битве. И многие из них восстали из мертвых, примкнув к Плети! Ты $gдолжен:должна; отыскать эти несчастные души и избавить их от страданий.$B$BКаннибалы-вурдалаки, бормочущие вурдалаки, болезненные живодеры – многие из них были добрыми жителями Дарроушира. Уничтожив их тела, ты освободишь их души.$B$BТы найдешь их в Чумном лесу, Перекрестке Корина и прочих опорных пунктах Плети в Восточных Чумных землях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 15 духов Дарроушира и возвращайтесь к Карлину Редпату.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад слышать, что истерзанные души моих сородичей с твоей помощью обрели свободу. Ты пролил бальзам на мои раны – теперь я знаю, что хоть кто-то из моих павших сородичей освободился от ига Плети.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Бедные защитники Дарроушира взывают ко мне во сне, $N. Вы должны освободить их!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карлину Редпату в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5212,'Плоть не лжет','Аптекари Отрекшихся не единственные в этом мире, кто искушен в науках.$B$BЯ уже много лет изучаю эту заразу, |3-6($r). Ранее я полагала, что активность чумы со временем уменьшается, однако то, что наблюдается в Чумных землях, поражает воображение.$B$BЗдесь вирус со временем становится все более активным!$B$BЯ должна продолжать исследования! Вирус наиболее активен в первые дни после заражения, поэтому мне нужны образцы тканей, пораженных совсем недавно. Отправляйся в Стратхольм и снабди меня препаратами для исследований, $n.','Принесите 10 образцов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, сойдут ткани любой твари из Стратхольма.','В химическом составе вируса приизошли какие-то изменения. Я должна продолжать исследования.','Некоторые считают, что у меня параноя, а я вот отвечу: \\"Бди! Вирус не дремлет!\\"','Вернитесь к Бетине Биггльцинк в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плоть не лжет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Аптекари Отрекшихся не единственные в этом мире, кто искушен в науках.$B$BЯ уже много лет изучаю эту заразу, |3-6($r). Ранее я полагала, что активность чумы со временем уменьшается, однако то, что наблюдается в Чумных землях, поражает воображение.$B$BЗдесь вирус со временем становится все более активным!$B$BЯ должна продолжать исследования! Вирус наиболее активен в первые дни после заражения, поэтому мне нужны образцы тканей, пораженных совсем недавно. Отправляйся в Стратхольм и снабди меня препаратами для исследований, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 образцов чумной плоти из Стратхольма Бетине Биггльцинк. Предположительно, сойдут ткани любой твари из Стратхольма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В химическом составе вируса приизошли какие-то изменения. Я должна продолжать исследования.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Некоторые считают, что у меня параноя, а я вот отвечу: \\"Бди! Вирус не дремлет!\\"',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бетине Биггльцинк в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5213,'Вирус чумы','Тебе предстоит углубиться еще дальше в кварталы Стратхольма, $n. $B$BЗа первыми воротами ты увидишь зиккураты. Известно, что твари Плети черпают из этих сооружений великую силу. Обыщи зиккураты и расскажи мне обо всем, что там увидишь.','Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк.','Мы на пороге открытия! Скоро мы узнаем, на чем основана устойчивость вируса чумы.','Вернитесь к Бетине Биггльцинк в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вирус чумы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе предстоит углубиться еще дальше в кварталы Стратхольма, $n. $B$BЗа первыми воротами ты увидишь зиккураты. Известно, что твари Плети черпают из этих сооружений великую силу. Обыщи зиккураты и расскажи мне обо всем, что там увидишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Стратхольм и исследуйте зиккураты. Доставьте сведения о Плети Бетине Биггльцинк.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы на пороге открытия! Скоро мы узнаем, на чем основана устойчивость вируса чумы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бетине Биггльцинк в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (5214,'О, мои милые папироски, как я по вам скучал...','Вернитесь к Дымку Лару в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, мои милые папироски, как я по вам скучал...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дымку Лару в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5215,'Котлы Плети','В пределах бывшего Лордерона спрятано восемь котлов – четыре здесь, на западе, и еще четыре – на востоке. Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети.$b$bКел\'Тузад слишком силен, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды. Моя помощница, верховная жрица Макдонелл, поможет тебе выполнить задание; она продолжит инструктаж.','Поговорите с верховной жрицей Макдонелл в лагере Промозглого Ветра в Западных Чумных землях.','Да осияет тебя Свет в наши темные времена, |3-6($C). Я рада, что смогу помочь тебе в борьбе с планами Плети.$B$BНаша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети. Для этого придется взять пробы из всех котлов в Западных Чумных землях.$B$BГотовься к славной битве против жестокой Плети!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Котлы Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В пределах бывшего Лордерона спрятано восемь котлов – четыре здесь, на западе, и еще четыре – на востоке. Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети.$b$bКел\'Тузад слишком силен, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды. Моя помощница, верховная жрица Макдонелл, поможет тебе выполнить задание; она продолжит инструктаж.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховной жрицей Макдонелл в лагере Промозглого Ветра в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да осияет тебя Свет в наши темные времена, |3-6($C). Я рада, что смогу помочь тебе в борьбе с планами Плети.$B$BНаша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети. Для этого придется взять пробы из всех котлов в Западных Чумных землях.$B$BГотовься к славной битве против жестокой Плети!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5216,'Цель: поле Джанис','Из четырех котлов Западных Чумных земель проще всего подобраться к тому, что в поле Джанис. Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать.$b$bОтправляйся на поле Джанис, что на востоке отсюда и на северо-западе от Андорала, и вступи в схватку с тамошним Хранителем котла. У него есть ключ, который даст доступ к котлу. Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества.','Отправляйтесь на поле Джанис в Западные Чумные земли, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис.','Ключ, который вы забрали у Хранителя котла Желчня входит в замочную скважину и немедленно исчезает. И все же, кажется, отныне вы сможете открывать панель доступа без ключа. Изнутри доносится гнусный запах. В котле бурлит смесь неизвестных веществ.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.','Откройте панель котла Плети на поле Джанис, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: поле Джанис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из четырех котлов Западных Чумных земель проще всего подобраться к тому, что в поле Джанис. Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать.$b$bОтправляйся на поле Джанис, что на востоке отсюда и на северо-западе от Андорала, и вступи в схватку с тамошним Хранителем котла. У него есть ключ, который даст доступ к котлу. Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на поле Джанис в Западные Чумные земли, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ключ, который вы забрали у Хранителя котла Желчня входит в замочную скважину и немедленно исчезает. И все же, кажется, отныне вы сможете открывать панель доступа без ключа. Изнутри доносится гнусный запах. В котле бурлит смесь неизвестных веществ.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Откройте панель котла Плети на поле Джанис, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5217,'Возвращение в Лагерь Промозглого Ветра','Вы наполняете бутыль из котла ядовитой жижей. Вроде бы должно хватить.$b$bЗаполучив яд, пора возвращаться к верховной жрице Макдонелл в лагерь Промозглого Ветра.','Принесите полную бутылку с поля Джанис верховной жрице Макдонелл в лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Лагерь Промозглого Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы наполняете бутыль из котла ядовитой жижей. Вроде бы должно хватить.$b$bЗаполучив яд, пора возвращаться к верховной жрице Макдонелл в лагерь Промозглого Ветра.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите полную бутылку с поля Джанис верховной жрице Макдонелл в лагерь Промозглого Ветра, что в Западных Чумных землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5218,'Котел поля Джанис','Вернитесь к котлу Плети в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Котел поля Джанис',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к котлу Плети в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5219,'Цель: Слезы Далсона','Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слезы Далсона. Но сегодня не время лить слезы, |3-6($c). Мы должны нанести удар по котлу и получить к нему доступ!$B$BОтправляйся в Слезы Далсона, к северу от Андорала, и убей Хранителя котла. Забери у него ключ, как и в прошлый раз, и получи доступ к самому котлу. Наполни эту бутылку ядом, ведь в каждом из котлов бурлит свое варево.','Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.','Неприятного вида ключ, найденный в останках Хранителя котла, легко входит в замочную скважину и исчезает. Вы получили постоянный доступ у котлу. По переплетенным трубкам течет гнусная тягучая жижа.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.','Вернитесь к котлу Плети в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: Слезы Далсона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слезы Далсона. Но сегодня не время лить слезы, |3-6($c). Мы должны нанести удар по котлу и получить к нему доступ!$B$BОтправляйся в Слезы Далсона, к северу от Андорала, и убей Хранителя котла. Забери у него ключ, как и в прошлый раз, и получи доступ к самому котлу. Наполни эту бутылку ядом, ведь в каждом из котлов бурлит свое варево.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неприятного вида ключ, найденный в останках Хранителя котла, легко входит в замочную скважину и исчезает. Вы получили постоянный доступ у котлу. По переплетенным трубкам течет гнусная тягучая жижа.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к котлу Плети в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (5220,'Возвращение в Лагерь Промозглого Ветра','Вы наполняете бутыль из котла зловонной жижей. Вроде бы должно хватить.$b$bЗаполучив яд, пора возвращаться к верховной жрице Макдонелл в лагерь Промозглого Ветра.','Принесите полную бутылку с поля Слез Далсона верховной жрице Макдонелл из лагеря Промозглого Ветра, что в Западных Чумных землях.','Мы знаем, что в каждом из котлов замешаны составляющие, распространяющие заразу. Также нам известно, что нужно для составления противоядий для каждого из котлов. Какие компоненты нужны для котла с поля Слез Далсона не определить без образца зелья. Действуй.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Лагерь Промозглого Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы наполняете бутыль из котла зловонной жижей. Вроде бы должно хватить.$b$bЗаполучив яд, пора возвращаться к верховной жрице Макдонелл в лагерь Промозглого Ветра.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите полную бутылку с поля Слез Далсона верховной жрице Макдонелл из лагеря Промозглого Ветра, что в Западных Чумных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы знаем, что в каждом из котлов замешаны составляющие, распространяющие заразу. Также нам известно, что нужно для составления противоядий для каждого из котлов. Какие компоненты нужны для котла с поля Слез Далсона не определить без образца зелья. Действуй.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5221,'Котел Слез Далсона','Вернитесь к котлу Плети в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Котел Слез Далсона',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к котлу Плети в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5222,'Цель: Удел Страданий','Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остается еще два! Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество!$b$bНа сей раз твоя цель – котел Удела Страданий. Он совсем рядом с разрушенными стенами Андорала, чуть восточнее. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Наполни эту бутылку из котла.$b$bДоброй охоты, $n!','Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.','Коснувшись панели доступа, ключ Хранителя котла исчезает, как и в прошлый раз. Внутри бурлит омерзительно пахнующая жидкость.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.','Откройте панель котла Плети на озере Дарроумир, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: Удел Страданий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остается еще два! Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество!$b$bНа сей раз твоя цель – котел Удела Страданий. Он совсем рядом с разрушенными стенами Андорала, чуть восточнее. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Наполни эту бутылку из котла.$b$bДоброй охоты, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Коснувшись панели доступа, ключ Хранителя котла исчезает, как и в прошлый раз. Внутри бурлит омерзительно пахнующая жидкость.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для верховной жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Откройте панель котла Плети на озере Дарроумир, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5223,'Возвращение в лагерь Промозглого Ветра','Вы аккуратно закручиваете бутылку. Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке.$b$bЗаполучив яд, пора возвращаться верховной жрице Макдонелл в Лагерь Промозглого Ветра.','Принесите полную бутылку с Призрачной фермы верховной жрице Макдонелл в Лагерь Промозглого Ветра, в Западные Чумные земли.','Еще одно задание выполнено без сучка, без задоринки! Итак, у нас есть доступ вот уже к трем котлам! Если бы не страшная некромантская власть Кел\'Тузада в этих землях, я бы сказала, что нам удастся полностью нейтрализовать их!$B$BАлхимик Арбингтон вскоре сообщит, что требуется добавить в этот котел – и другие, подвластные нам – чтобы справиться с чумой нежити. Итак, настало время добраться до последнего из западных котлов!','Как только мы исследуем образец из котла Удела Страданий, у нас появится третий способ нанести сокрушительный урон Плети, подобрав правильное противодействующее вещество!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в лагерь Промозглого Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы аккуратно закручиваете бутылку. Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке.$b$bЗаполучив яд, пора возвращаться верховной жрице Макдонелл в Лагерь Промозглого Ветра.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите полную бутылку с Призрачной фермы верховной жрице Макдонелл в Лагерь Промозглого Ветра, в Западные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще одно задание выполнено без сучка, без задоринки! Итак, у нас есть доступ вот уже к трем котлам! Если бы не страшная некромантская власть Кел\'Тузада в этих землях, я бы сказала, что нам удастся полностью нейтрализовать их!$B$BАлхимик Арбингтон вскоре сообщит, что требуется добавить в этот котел – и другие, подвластные нам – чтобы справиться с чумой нежити. Итак, настало время добраться до последнего из западных котлов!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как только мы исследуем образец из котла Удела Страданий, у нас появится третий способ нанести сокрушительный урон Плети, подобрав правильное противодействующее вещество!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5224,'Котел Удела Страданий','Вернитесь к котлу Плети в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Котел Удела Страданий',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к котлу Плети в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5225,'Цель: пустошь Гаррона','Последний оставшийся котел находится на ферме, которая теперь зовется пустошью Гаррона. Его охраняют сильные прислужники Плети, по большей части призраки и духи. С ними шутки плохи, $n.$B$BПустошь Гаррона находится далеко на северо-востоке от Бастиона, близко от границы Восточных Чумных земель. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Вот, возьми эту пустую бутылку, заполни ее из котла и принеси мне. Да укроет тебя тьма своим крылом, |3-6($c).','Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с пустоши Гаррона.','Коснувшись панели доступа у основания, ключ Хранителя котла Душегнева исчезает. Раздается негромкий щелчок, и панель распахивается, открывая доступ к зловредным ядам.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.','Изучите котел Плети в Пустоши Гаррона, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: пустошь Гаррона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последний оставшийся котел находится на ферме, которая теперь зовется пустошью Гаррона. Его охраняют сильные прислужники Плети, по большей части призраки и духи. С ними шутки плохи, $n.$B$BПустошь Гаррона находится далеко на северо-востоке от Бастиона, близко от границы Восточных Чумных земель. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Вот, возьми эту пустую бутылку, заполни ее из котла и принеси мне. Да укроет тебя тьма своим крылом, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с пустоши Гаррона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Коснувшись панели доступа у основания, ключ Хранителя котла Душегнева исчезает. Раздается негромкий щелчок, и панель распахивается, открывая доступ к зловредным ядам.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для высшей жрицы Макдонелл с Берега Промозглого Ветра не составляет труда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Изучите котел Плети в Пустоши Гаррона, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (5226,'Возвращение в лагерь Промозглого Ветра','Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку.$b$bЗаполучив яд, пора возвращаться к верховной жрице Макдонелл из лагеря Промозглого Ветра.','Отнесите полную бутылку с пустоши Гаррона верховной жрице Макдонелл из лагеря Промозглого Ветра, что в Западных Чумных землях.','На пустоши Гаррона находится последний котел на востоке, к которому у нас еще нет доступа. Получив образцы зелья чумы из этого котла, мы сможем внести необходимые компоненты в четыре сосуда! Плети придется нелегко, даже сила Кел\'Тузада ее не спасет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в лагерь Промозглого Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку.$b$bЗаполучив яд, пора возвращаться к верховной жрице Макдонелл из лагеря Промозглого Ветра.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите полную бутылку с пустоши Гаррона верховной жрице Макдонелл из лагеря Промозглого Ветра, что в Западных Чумных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На пустоши Гаррона находится последний котел на востоке, к которому у нас еще нет доступа. Получив образцы зелья чумы из этого котла, мы сможем внести необходимые компоненты в четыре сосуда! Плети придется нелегко, даже сила Кел\'Тузада ее не спасет.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5227,'Котел в пустоши Гаррона','Вернитесь к котлу Плети в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Котел в пустоши Гаррона',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к котлу Плети в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5228,'Котлы Плети','В пределах бывшего Лордерона спрятано восемь котлов – четыре здесь, на западе, и еще четыре – на востоке. Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети.$b$bКел\'Тузад слишком силен, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды. Моя помощница, жрица Тени Вандис, поможет тебе выполнить задание; она продолжит инструктаж.','Поговорите со жрицей Тени Вандис в Бастионе, что в Западных Чумных землях.','Да благословит тебя Тьма, брат |3-6($R). Я помогу тебе организовать нападение на котлы Плети.$B$BНаша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети. Для этого придется взять пробы из всех котлов в Западных Чумных землях.$B$BТебя ждет героическая схватка с Плетью!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Котлы Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В пределах бывшего Лордерона спрятано восемь котлов – четыре здесь, на западе, и еще четыре – на востоке. Они испускают ядовитые пары, распространяя чуму нежити по всей земле на радость Плети.$b$bКел\'Тузад слишком силен, чтобы взять да и угасить пламя под этими котлами, но, быть может, мы сможем придумать способ использовать их для собственной выгоды. Моя помощница, жрица Тени Вандис, поможет тебе выполнить задание; она продолжит инструктаж.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со жрицей Тени Вандис в Бастионе, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да благословит тебя Тьма, брат |3-6($R). Я помогу тебе организовать нападение на котлы Плети.$B$BНаша цель – таким образом изменить состав яда в котлах, чтобы он стал погибелью приспешников Плети. Для этого придется взять пробы из всех котлов в Западных Чумных землях.$B$BТебя ждет героическая схватка с Плетью!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5229,'Цель: поле Джанис','Из четырех котлов Западных Чумных земель проще всего подобраться к тому, что в поле Джанис. Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать.$b$bОтправляйся на поле Джанис, что на востоке отсюда и на северо-западе от Андорала, и вступи в схватку с тамошним Хранителем котла. У него есть ключ, который даст доступ к котлу. Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества.','Отправляйтесь на поле Джанис в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис.','Ключ, который вы забрали у Хранителя котла Желчня входит в замочную скважину и немедленно исчезает. И все же, кажется, отныне вы сможете открывать панель доступа без ключа. Изнутри доносится гнусный запах. В котле бурлит смесь неизвестных веществ.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис с вершины Холодного Ветра не составляет труда.','Панель доступа к котлу остается надежно закрытой. Чтобы открыть его, вам нужно будет найти ключ.','Откройте панель котла Плети на поле Джанис, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: поле Джанис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из четырех котлов Западных Чумных земель проще всего подобраться к тому, что в поле Джанис. Его охраняют менее опытные воины Плети, хотя не стоит их недооценивать.$b$bОтправляйся на поле Джанис, что на востоке отсюда и на северо-западе от Андорала, и вступи в схватку с тамошним Хранителем котла. У него есть ключ, который даст доступ к котлу. Отперев панель доступа, набери в бутылку образец ядов из котла; они понадобятся нам, чтобы подобрать противодействующие вещества.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на поле Джанис в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Джанис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ключ, который вы забрали у Хранителя котла Желчня входит в замочную скважину и немедленно исчезает. И все же, кажется, отныне вы сможете открывать панель доступа без ключа. Изнутри доносится гнусный запах. В котле бурлит смесь неизвестных веществ.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис с вершины Холодного Ветра не составляет труда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Панель доступа к котлу остается надежно закрытой. Чтобы открыть его, вам нужно будет найти ключ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Откройте панель котла Плети на поле Джанис, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5230,'Возвращение в Бастион','Вы наполняете бутыль из котла ядовитой жижей. Вроде бы должно хватить.$b$bЗаполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион.','Принесите полную бутылку с поля Джанис жрице Тени Вандис в Бастион, что в Западных Чумных землях.','$GМолодец:Умница;, $N! Аптекарь Дитерс мигом проведет анализ этой дряни и составит противодействующее вещество. Надо будет внести его в котел и постараться, чтобы побольше испарений попало в воздух. Кто знает, может удастся ослабить Плеть.$B$BЭто будет нелегко – придется постоянно устраивать набеги на котлы и добавлять в них необходимые реагенты. И все же у нас есть шанс получить в решающей битве преимущество перед Плетью!','Добро пожаловать в Бастион, $N. Наслаждайся ощущением безопасности. Как дела с котлами?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Бастион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы наполняете бутыль из котла ядовитой жижей. Вроде бы должно хватить.$b$bЗаполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите полную бутылку с поля Джанис жрице Тени Вандис в Бастион, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N! Аптекарь Дитерс мигом проведет анализ этой дряни и составит противодействующее вещество. Надо будет внести его в котел и постараться, чтобы побольше испарений попало в воздух. Кто знает, может удастся ослабить Плеть.$B$BЭто будет нелегко – придется постоянно устраивать набеги на котлы и добавлять в них необходимые реагенты. И все же у нас есть шанс получить в решающей битве преимущество перед Плетью!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать в Бастион, $N. Наслаждайся ощущением безопасности. Как дела с котлами?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5231,'Цель: Слезы Далсона','Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слезы Далсона. Но сегодня не время лить слезы, |3-6($c). Мы должны нанести удар по котлу и получить к нему доступ!$B$BОтправляйся в Слезы Далсона, к северу от Андорала, и убей Хранителя котла. Забери у него ключ, как и в прошлый раз, и получи доступ к самому котлу. Наполни эту бутылку ядом, ведь в каждом из котлов бурлит свое варево.','Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.','Неприятного вида ключ, найденный в останках Хранителя котла, легко входит в замочную скважину и исчезает. Вы получили постоянный доступ у котлу. По переплетенным трубкам течет гнусная тягучая жижа.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис из Бастиона не составляет труда.','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.','Откройте панель котла Плети в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: Слезы Далсона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из чумных котлов расположен на поле бывшей фермы, которую ныне зовут Слезы Далсона. Но сегодня не время лить слезы, |3-6($c). Мы должны нанести удар по котлу и получить к нему доступ!$B$BОтправляйся в Слезы Далсона, к северу от Андорала, и убей Хранителя котла. Забери у него ключ, как и в прошлый раз, и получи доступ к самому котлу. Наполни эту бутылку ядом, ведь в каждом из котлов бурлит свое варево.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Слезы Далсона в Западных Чумных землях, найдите и одолейте Хранителя котла, взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка c поля Слез Далсона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неприятного вида ключ, найденный в останках Хранителя котла, легко входит в замочную скважину и исчезает. Вы получили постоянный доступ у котлу. По переплетенным трубкам течет гнусная тягучая жижа.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис из Бастиона не составляет труда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Откройте панель котла Плети в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5232,'Возвращение в Бастион','Вы наполняете бутыль из котла зловонной жижей. Вроде бы должно хватить.$b$bЗаполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион.','Отнесите полную бутылку с поля Слез Далсона жрице Тени Вандис в Бастион в Западных Чумных землях.','А, мне будет чем заняться. $GМолодец:Умница;, $N!$B$BИтак, следующий шаг ясен. Мы должны составить список компонентов, которые будет необходимо смешать с зельем чумы, чтобы добиться от него обратного действия.$B$BДля этого придется поместить эти составляющие непосредственно в котел. Аптекарь Дитерс знает гораздо больше чем я, поэтому в ближайшее время поговори с ним.','Мы знаем, что в каждом из котлов замешаны составляющие, распространяющие заразу. Также нам известно, что нужно для составления противоядий для каждого из котлов. Какие компоненты нужны для котла с поля Слез Далсона не определить без образца зелья. Действуй.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Бастион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы наполняете бутыль из котла зловонной жижей. Вроде бы должно хватить.$b$bЗаполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите полную бутылку с поля Слез Далсона жрице Тени Вандис в Бастион в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, мне будет чем заняться. $GМолодец:Умница;, $N!$B$BИтак, следующий шаг ясен. Мы должны составить список компонентов, которые будет необходимо смешать с зельем чумы, чтобы добиться от него обратного действия.$B$BДля этого придется поместить эти составляющие непосредственно в котел. Аптекарь Дитерс знает гораздо больше чем я, поэтому в ближайшее время поговори с ним.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы знаем, что в каждом из котлов замешаны составляющие, распространяющие заразу. Также нам известно, что нужно для составления противоядий для каждого из котлов. Какие компоненты нужны для котла с поля Слез Далсона не определить без образца зелья. Действуй.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5233,'Цель: Удел Страданий','Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остается еще два! Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество!$b$bНа сей раз твоя цель – котел Удела Страданий. Он совсем рядом с разрушенными стенами Андорала, чуть восточнее. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Наполни эту бутылку из котла.$b$bДоброй охоты, $n!','Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.','Коснувшись панели доступа, ключ Хранителя котла исчезает, как и в прошлый раз. Внутри бурлит омерзительно пахнующая жидкость.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис из Бастиона не составляет труда.','Панель доступа к котлу остается надежно закрытой. Чтобы открыть его, вам нужно будет найти ключ.','Откройте панель котла Плети на озере Дарроумир, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: Удел Страданий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось открыть уже два котла; теперь у тебя к ним неограниченный доступ, но остается еще два! Если справиться и с ними, то у нас будет больше шансов успешно внести противодействующее вещество!$b$bНа сей раз твоя цель – котел Удела Страданий. Он совсем рядом с разрушенными стенами Андорала, чуть восточнее. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Наполни эту бутылку из котла.$b$bДоброй охоты, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Удел Страданий в Западных Чумных землях. Найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с Удела Страданий.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Коснувшись панели доступа, ключ Хранителя котла исчезает, как и в прошлый раз. Внутри бурлит омерзительно пахнующая жидкость.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис из Бастиона не составляет труда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Панель доступа к котлу остается надежно закрытой. Чтобы открыть его, вам нужно будет найти ключ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Откройте панель котла Плети на озере Дарроумир, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5234,'Возвращение в Бастион','Вы аккуратно закручиваете бутылку. Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке.$b$bЗаполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион.','Принесите полную бутылку с Призрачной фермы жрице Тени Вандис в Бастион, что в Западных Чумных землях.','Еще одно задание выполнено без сучка, без задоринки! Итак, у нас есть доступ вот уже к трем котлам! Если бы не страшная некромантская власть Кел\'Тузада в этих землях, я бы сказала, что нам удастся полностью нейтрализовать их!$B$BАптекарь Дитерс вскоре сообщит, что требуется добавить в этот котел – и другие, подвластные нам – чтобы справиться с чумой нежити. Итак, настало время добраться до последнего из западных котлов!','Как только мы исследуем образец из котла Удела Страданий, у нас появится третий способ нанести сокрушительный урон Плети, подобрав правильное противодействующее вещество!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Бастион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы аккуратно закручиваете бутылку. Образец гнусной жижи, бурлящей в котле, плещется в хрупкой стеклянной оболочке.$b$bЗаполучив яд, пора возвращаться ко жрице Тени Вандис в Бастион.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите полную бутылку с Призрачной фермы жрице Тени Вандис в Бастион, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще одно задание выполнено без сучка, без задоринки! Итак, у нас есть доступ вот уже к трем котлам! Если бы не страшная некромантская власть Кел\'Тузада в этих землях, я бы сказала, что нам удастся полностью нейтрализовать их!$B$BАптекарь Дитерс вскоре сообщит, что требуется добавить в этот котел – и другие, подвластные нам – чтобы справиться с чумой нежити. Итак, настало время добраться до последнего из западных котлов!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как только мы исследуем образец из котла Удела Страданий, у нас появится третий способ нанести сокрушительный урон Плети, подобрав правильное противодействующее вещество!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5235,'Цель: пустошь Гаррона','Последний оставшийся котел находится на ферме, которая теперь зовется пустошью Гаррона. Его охраняют сильные прислужники Плети, по большей части призраки и духи. С ними шутки плохи, $n.$B$BПустошь Гаррона находится далеко на востоке от Бастиона, близко к границам Восточных Чумных земель. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Вот, возьми эту пустую бутылку, заполни ее из котла и принеси мне. Да укроет тебя тьма своим крылом, |3-6($c).','Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с пустоши Гаррона.','Коснувшись панели доступа у основания, ключ Хранителя котла Душегнева исчезает. Раздается негромкий щелчок, и панель распахивается, открывая доступ к зловредным ядам.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис из Бастиона не составляет труда.','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.','Откройте панель котла Плети в Пустоши Гаррона, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: пустошь Гаррона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последний оставшийся котел находится на ферме, которая теперь зовется пустошью Гаррона. Его охраняют сильные прислужники Плети, по большей части призраки и духи. С ними шутки плохи, $n.$B$BПустошь Гаррона находится далеко на востоке от Бастиона, близко к границам Восточных Чумных земель. И вновь тебе придется убить Хранителя котла и забрать у него ключ. Вот, возьми эту пустую бутылку, заполни ее из котла и принеси мне. Да укроет тебя тьма своим крылом, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на пустошь Гаррона в Западных Чумных землях, найдите и одолейте Хранителя котла. Взяв у него ключ, доберитесь до самого котла. Чтобы взять образец яда из котла, вам понадобится пустая бутылка с пустоши Гаррона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Коснувшись панели доступа у основания, ключ Хранителя котла Душегнева исчезает. Раздается негромкий щелчок, и панель распахивается, открывая доступ к зловредным ядам.$B$BБутылка отлично помещается под небольшой кран, так что набрать в нее образец яда для жрицы Тени Вандис из Бастиона не составляет труда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Панель доступа к котлу по-прежнему надежно закреплена. Без ключа ее не открыть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Откройте панель котла Плети в Пустоши Гаррона, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5236,'Возвращение в Бастион','Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку.$b$bЗаполучив яд, пора возвращаться к жрице Тени Вандис в Бастион.','Отнесите полную бутылку с пустоши Гаррона жрице Тени Вандис в Бастион в Западных Чумных землях.','Поздравляю, $N, тебе удалось обеспечить нам доступ к последнему из котлов! Аптекарь Дитерс вскоре составит список компонентов, которые необходимо добавить в него.$B$BЧто до тебя, я не сомневаюсь, что верховный палач Деррингтон пожелает лично поблагодарить тебя за помощь. Без тебя наша борьба с Плетью была обречена. Спасибо, могучий |3-6($C).','На пустоши Гаррона находится последний котел на западе, к которому у нас еще нет доступа. Получив образцы зелья чумы из этого котла, мы сможем внести необходимые компоненты в четыре сосуда! Плети придется нелегко, даже сила Кел\'Тузада ее не спасет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Бастион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы тщательно перекрываете кран на панели управления, и остатки гнусной жижи медленно стекают в пустую бутылку.$b$bЗаполучив яд, пора возвращаться к жрице Тени Вандис в Бастион.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите полную бутылку с пустоши Гаррона жрице Тени Вандис в Бастион в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поздравляю, $N, тебе удалось обеспечить нам доступ к последнему из котлов! Аптекарь Дитерс вскоре составит список компонентов, которые необходимо добавить в него.$B$BЧто до тебя, я не сомневаюсь, что верховный палач Деррингтон пожелает лично поблагодарить тебя за помощь. Без тебя наша борьба с Плетью была обречена. Спасибо, могучий |3-6($C).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На пустоши Гаррона находится последний котел на западе, к которому у нас еще нет доступа. Получив образцы зелья чумы из этого котла, мы сможем внести необходимые компоненты в четыре сосуда! Плети придется нелегко, даже сила Кел\'Тузада ее не спасет.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5237,'Задание выполнено!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание выполнено!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (5237,'$n, your successful re-engineering of the cauldrons is a tremendous victory for us!$B$B$B$BLet all within my presence hear: for service to the Kingdom of Stormwind and to the Alliance above and beyond the call of duty - in the face of overwhelming odds and incredible danger, might I add - I give $n this, and I extend upon him our undying gratitude as a true hero of the Alliance. Cheers, I say!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$n, your successful re-engineering of the cauldrons is a tremendous victory for us!$B$B$B$BLet all within my presence hear: for service to the Kingdom of Stormwind and to the Alliance above and beyond the call of duty - in the face of overwhelming odds and incredible danger, might I add - I give $n this, and I extend upon him our undying gratitude as a true hero of the Alliance. Cheers, I say!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5238,'Задание выполнено!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание выполнено!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5241,'Дядюшка Карлин','Ты знаешь, иногда по ночам мне слышится плач дядюшки Карлина – как будто бы плач доносится откуда-то издалека, с востока.$B$BА вдруг он плачет обо мне... $n, пожалуйста, разыщи моего дядюшку и скажи ему, что со мной все в порядке.$B$BСкажи, что я здесь, жду его и очень скучаю по сказкам, которые он рассказывал мне на ночь... особенно той, про кроликов и черничное варенье. Она была такая забавная!','Найдите Карлина Редпата.','Ты видел Памелу? Она жива?$B$BПогибла?! Бедная моя девочка! За что твой дух осужден скитаться в этом жестоком мире... Почему тебя не стало во цвете лет, а я все еще копчу небо! Как бы я хотел вместо тебя отдать жизнь и призраком бродить по руинам Дарроушира!$B$BСудьбу не изменить... Спасибо тебе, $n. Теперь мой долг – месть, я осознаю это ясно как никогда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дядюшка Карлин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты знаешь, иногда по ночам мне слышится плач дядюшки Карлина – как будто бы плач доносится откуда-то издалека, с востока.$B$BА вдруг он плачет обо мне... $n, пожалуйста, разыщи моего дядюшку и скажи ему, что со мной все в порядке.$B$BСкажи, что я здесь, жду его и очень скучаю по сказкам, которые он рассказывал мне на ночь... особенно той, про кроликов и черничное варенье. Она была такая забавная!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Карлина Редпата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты видел Памелу? Она жива?$B$BПогибла?! Бедная моя девочка! За что твой дух осужден скитаться в этом жестоком мире... Почему тебя не стало во цвете лет, а я все еще копчу небо! Как бы я хотел вместо тебя отдать жизнь и призраком бродить по руинам Дарроушира!$B$BСудьбу не изменить... Спасибо тебе, $n. Теперь мой долг – месть, я осознаю это ясно как никогда.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5242,'Окончательный удар','Увы, я вижу только один путь покончить с угрозой Оскверненному лесу – прямую атаку. Других путей в Оплот Теней нет, телепортировать тебя внутрь я тоже не могу. Единственный путь – прямой путь в бездну... и я также знаю, кого тебе следует искать в этой бездне. Его зовут Скверн\'дан... Владыка теней Скверн\'дан. Его власть там, внизу, смертоносна... Он – голова змеи. Убей его и двух его суккубов-прислужниц, и вернись ко мне. Это Скверн\'дан заключил союз с Легионом. Его надо остановить!','Убейте Моору и Салию и принесите голову Владыки теней Скверн\'дана Грете Замшелому Копыту в Оскверненный лес.','Вернитесь к Грете Замшелому Копыту в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Окончательный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Увы, я вижу только один путь покончить с угрозой Оскверненному лесу – прямую атаку. Других путей в Оплот Теней нет, телепортировать тебя внутрь я тоже не могу. Единственный путь – прямой путь в бездну... и я также знаю, кого тебе следует искать в этой бездне. Его зовут Скверн\'дан... Владыка теней Скверн\'дан. Его власть там, внизу, смертоносна... Он – голова змеи. Убей его и двух его суккубов-прислужниц, и вернись ко мне. Это Скверн\'дан заключил союз с Легионом. Его надо остановить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Моору и Салию и принесите голову Владыки теней Скверн\'дана Грете Замшелому Копыту в Оскверненный лес.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грете Замшелому Копыту в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5243,'Святая вода','Я склонен рассматривать свое бытие в форме нежити как род болезни, |3-6($r). Болезни, которая требует лечения. Впрочем, для Серебряного Рассвета это не болезнь, а истинное благословение. Действительно, нет лучше орудия против язычников Плети, чем нежить.$B$BКоллеги чтят меня за мои деяния, однако почести ничего не значат для меня.$B$BЕсли ты хочешь содействовать делу Серебряного Рассвета, у меня есть для тебя работа.$B$BОтправляйся в Стратхольм и пополни наши запасы святой воды. Искать ее следует в брошенных ящиках с припасами.','Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Барталомею Чтимому, как только воды будет достаточно.','Отлично, |3-6($r). Ты доказал, что терпим к ближнему и непримирим в борьбе против приспешников Кел\'Тузада.','Учти, далеко не все ящики припасов в разрушенном городе остались в целости и сохранности. Воины Плети боятся святой воды, однако она не является препятствием для диких зверей.','Вернитесь к Леониду Барталомею Чтимому в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святая вода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я склонен рассматривать свое бытие в форме нежити как род болезни, |3-6($r). Болезни, которая требует лечения. Впрочем, для Серебряного Рассвета это не болезнь, а истинное благословение. Действительно, нет лучше орудия против язычников Плети, чем нежить.$B$BКоллеги чтят меня за мои деяния, однако почести ничего не значат для меня.$B$BЕсли ты хочешь содействовать делу Серебряного Рассвета, у меня есть для тебя работа.$B$BОтправляйся в Стратхольм и пополни наши запасы святой воды. Искать ее следует в брошенных ящиках с припасами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на север, в Стратхольм. Обыщите брошенные ящики с припасами и соберите 5 мер святой воды Стратхольма. Возвращайтесь к Леониду Барталомею Чтимому, как только воды будет достаточно.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, |3-6($r). Ты доказал, что терпим к ближнему и непримирим в борьбе против приспешников Кел\'Тузада.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Учти, далеко не все ящики припасов в разрушенном городе остались в целости и сохранности. Воины Плети боятся святой воды, однако она не является препятствием для диких зверей.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Леониду Барталомею Чтимому в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5244,'Руины Кел\'Терила','История Кел\'Терила – это история проклятой расы, прикованной к месту, где был совершен неудавшийся ритуал...$b$bВысокорожденные, которых вы найдете там, когда-то похитили священный артефакт, будучи уверенными, что смогут вытянуть его мощь, перелить ее в себя и стать еще более могущественными. Из-за их действий реликвия взорвалась, а куски ее ушли под лед озера...$b$bЕсли хотите узнать больше, поговорите с Джероном Гранильщиком. Он был там недавно и сможет рассказать вам обо всем.','Поговорите с Джероном Гранильщиком в деревне Звездопада.','Ну, конечно, я могу подробно рассказать про Кел\'Терил. Имей в виду, я не историк – но могу рассказать тебе о том, что я сам там видел…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины Кел\'Терила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','История Кел\'Терила – это история проклятой расы, прикованной к месту, где был совершен неудавшийся ритуал...$b$bВысокорожденные, которых вы найдете там, когда-то похитили священный артефакт, будучи уверенными, что смогут вытянуть его мощь, перелить ее в себя и стать еще более могущественными. Из-за их действий реликвия взорвалась, а куски ее ушли под лед озера...$b$bЕсли хотите узнать больше, поговорите с Джероном Гранильщиком. Он был там недавно и сможет рассказать вам обо всем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джероном Гранильщиком в деревне Звездопада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, конечно, я могу подробно рассказать про Кел\'Терил. Имей в виду, я не историк – но могу рассказать тебе о том, что я сам там видел…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5245,'Беспокойные духи Кел\'Терила','[Deprecated] The highborne spirits are miserable creatures, that\'s for sure. They are still searching for pieces of the very thing that has cursed them to Kel\'Theril forever -- the stolen relic.$B$BIf you are that interested, take my pick and go south to the lake, see if you can gather the pieces of it from within the ice.$B$B','[Deprecated] Use Gormir\'s Pick to find the four Highborne Relic Fragments.','[Deprecated] Return to Gormir Stoneshaper at Starfall Village in Winterspring.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беспокойные духи Кел\'Терила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[Deprecated] The highborne spirits are miserable creatures, that\'s for sure. They are still searching for pieces of the very thing that has cursed them to Kel\'Theril forever -- the stolen relic.$B$BIf you are that interested, take my pick and go south to the lake, see if you can gather the pieces of it from within the ice.$B$B',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[Deprecated] Use Gormir\'s Pick to find the four Highborne Relic Fragments.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Gormir Stoneshaper at Starfall Village in Winterspring.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5246,'Фрагменты прошлого','Я не понимала... Простите мои жестокие слова, |3-6($c).$b$bЯ не хочу вспоминать об ошибках своих предков, но если ваша просьба искренна, я помогу.$b$b*Аврора изучает фрагменты.*$b$bЯ уверена, что это – Кристалл Зин-Малора, артефакт, содержащий в себе могучие силы тайной магии. Возможно, его использовали и во благо, но из-за злых намерений тех, кто его похитил, кристалл раскололся.$b$bОтправляйтесь в Храм Зин-Малор в Азшаре – я могу лишь надеяться, что книга все еще там.','Найдите Священные письмена высокорожденных в Храме Зин-Малор, в Азшаре и принесите их Авроре Зову Небес к Башне Северного перевалa, в Восточных Чумных землях.','Вернитесь к Авроре Зов Небес в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фрагменты прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не понимала... Простите мои жестокие слова, |3-6($c).$b$bЯ не хочу вспоминать об ошибках своих предков, но если ваша просьба искренна, я помогу.$b$b*Аврора изучает фрагменты.*$b$bЯ уверена, что это – Кристалл Зин-Малора, артефакт, содержащий в себе могучие силы тайной магии. Возможно, его использовали и во благо, но из-за злых намерений тех, кто его похитил, кристалл раскололся.$b$bОтправляйтесь в Храм Зин-Малор в Азшаре – я могу лишь надеяться, что книга все еще там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Священные письмена высокорожденных в Храме Зин-Малор, в Азшаре и принесите их Авроре Зову Небес к Башне Северного перевалa, в Восточных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Авроре Зов Небес в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5247,'Фрагменты прошлого','Я смогу помочь вам, если воссоздание артефакта действительно является вашим желанием.$b$bЧтобы воссоединить фрагменты, мне потребуются вещи, обладающие сильными магическими свойствами. Слитки зачарованного тория и пять кристаллов восстановления... Также вам нужно будет набрать воды из... необычного источника... Найдите Зловещий пруд на Пути Элдрета в Забытом Городе, что в Фераласе, и наполните этот фиал.$b$bПока вас не будет, я попытаюсь извлечь из этих страниц знание, как восполнить урон, нанесенный этой реликвии.','Принесите зачарованный слиток тория, 5 кристаллов Восстановления и фиал пугающей воды Авроре Зову Небес к башне Северного Перевала, в Восточных Чумных землях.','Вернитесь к Авроре Зов Небес в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фрагменты прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я смогу помочь вам, если воссоздание артефакта действительно является вашим желанием.$b$bЧтобы воссоединить фрагменты, мне потребуются вещи, обладающие сильными магическими свойствами. Слитки зачарованного тория и пять кристаллов восстановления... Также вам нужно будет набрать воды из... необычного источника... Найдите Зловещий пруд на Пути Элдрета в Забытом Городе, что в Фераласе, и наполните этот фиал.$b$bПока вас не будет, я попытаюсь извлечь из этих страниц знание, как восполнить урон, нанесенный этой реликвии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите зачарованный слиток тория, 5 кристаллов Восстановления и фиал пугающей воды Авроре Зову Небес к башне Северного Перевала, в Восточных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Авроре Зов Небес в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5248,'Измученный воспоминаниями о прошлом','$n, Я скорблю о том, что раса эльфов была разрушена, подобно этому кристаллу. Я не знаю, соберутся ли когда-нибудь эти осколки воедино, и все же то, что я могу помочь тебе, уменьшает мою скорбь.$B$BМы не должны забывать о прошлом, $n...$B$BПожалуйста верни кристалл Зин-Малора к озеру Кел\'Терил. Найди там духа высокорожденного, который, так же как и я, сожалеет о допущенных ошибках и скажи ему, что мы стремимся все исправить.','Отнесите кристалл Зин-Малора к озеру Кел\'Терил в Зимних Ключах и найдите духа высокорожденного, который согласится с вами поговорить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Измученный воспоминаниями о прошлом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, Я скорблю о том, что раса эльфов была разрушена, подобно этому кристаллу. Я не знаю, соберутся ли когда-нибудь эти осколки воедино, и все же то, что я могу помочь тебе, уменьшает мою скорбь.$B$BМы не должны забывать о прошлом, $n...$B$BПожалуйста верни кристалл Зин-Малора к озеру Кел\'Терил. Найди там духа высокорожденного, который, так же как и я, сожалеет о допущенных ошибках и скажи ему, что мы стремимся все исправить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кристалл Зин-Малора к озеру Кел\'Терил в Зимних Ключах и найдите духа высокорожденного, который согласится с вами поговорить.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5249,'В Зимние Ключи!','В Зимних Ключах, к северу отсюда, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения.$b$bРабота здесь отнимает все мое время, так что у меня давно уже не было возможности самой добраться до Зимних Ключей. Но вам-то ничто не мешает!$b$bКогда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в деревне Звездопада и очень много знает о тех местах.','Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.','Друг Иви Росистой Листвы? Приятно познакомиться, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Зимние Ключи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Зимних Ключах, к северу отсюда, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения.$b$bРабота здесь отнимает все мое время, так что у меня давно уже не было возможности самой добраться до Зимних Ключей. Но вам-то ничто не мешает!$b$bКогда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в деревне Звездопада и очень много знает о тех местах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Друг Иви Росистой Листвы? Приятно познакомиться, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5250,'Звездопад','В Зимних Ключах, к северу от Оскверненного леса, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения.$b$bЯ так занята своими исследованиями здесь, что у меня давно уже не было возможности самой добраться до Зимних ключей. Но у вас-то нет никаких причин для отказа от путешествия туда и изучения руин.$b$bКогда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в Звездопаде и очень много знает о том районе.$b$bСкажите ему, что вы $gмой ученик:моя ученица;.','Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.','Ученик Дарин Доброго Ветра? Приятно познакомиться с вами, $n.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звездопад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Зимних Ключах, к северу от Оскверненного леса, много древних эльфийских руин. Это суровая земля, но она хранит множество секретов, и там есть места, которые стоят изучения.$b$bЯ так занята своими исследованиями здесь, что у меня давно уже не было возможности самой добраться до Зимних ключей. Но у вас-то нет никаких причин для отказа от путешествия туда и изучения руин.$b$bКогда будете там, поищите Вунда Ночного Охотника. Большую часть времени он проводит в Звездопаде и очень много знает о том районе.$b$bСкажите ему, что вы $gмой ученик:моя ученица;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Зимних Ключах деревню Звездопада и поговорите там с Вундом Ночным Охотником.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ученик Дарин Доброго Ветра? Приятно познакомиться с вами, $n.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5251,'Архивариус','Впадать в крайности всегда опасно, $n. Взять, к примеру, Алый орден. Неужели такой слепой фанатизм способен привести к чему-то хорошему? Скольких невинных убили они во имя Света.$B$BЭто просто святотатство!$B$BВот что, один из этих негодяев мне особенно интересен – это архивариус Галфорд из Стратхольма. Этот человек отвечает за самые ценные документы ордена. Уничтожь его и сожги его архивы! Если справишься с этим, получишь достойную награду.','Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив.','Отличная работа, $n! Ты уничтожил разведданные, собираемые Алым орденом годами! Алые будут в ярости...','Помните, $N - мы должны быть терпеливыми, но твердыми в своих убеждениях!','Вернитесь к герцогу Николасу Зверенхоффу в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Архивариус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Впадать в крайности всегда опасно, $n. Взять, к примеру, Алый орден. Неужели такой слепой фанатизм способен привести к чему-то хорошему? Скольких невинных убили они во имя Света.$B$BЭто просто святотатство!$B$BВот что, один из этих негодяев мне особенно интересен – это архивариус Галфорд из Стратхольма. Этот человек отвечает за самые ценные документы ордена. Уничтожь его и сожги его архивы! Если справишься с этим, получишь достойную награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Стратхольм и отыщите архивариуса Галфорда из Алого ордена. Убейте его и сожгите архив.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $n! Ты уничтожил разведданные, собираемые Алым орденом годами! Алые будут в ярости...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Помните, $N - мы должны быть терпеливыми, но твердыми в своих убеждениях!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к герцогу Николасу Зверенхоффу в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5252,'Раскаявшийся высокорожденный','Кри... кристалл...$b$bЗдешние высокорожденные находятся в плену своего жалкого сущессствования...$b$bЯ полон горрречи, но я понимаю, в чем моя ошибка. И хотя изменить прошлое нееевозможно, теперь я обрел покой, зная, что тебе удалосссь добыть кристалл Зин-Малора...$b$bТы $gдолжен:должна; вернуть крисссталл...$b$bОн должен быть воззвращен.','Поговорите с Вундом Ночным Охотником в деревне Звездопада и узнайте у него, куда нужно поместить кристалл Зин-Малора.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раскаявшийся высокорожденный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кри... кристалл...$b$bЗдешние высокорожденные находятся в плену своего жалкого сущессствования...$b$bЯ полон горрречи, но я понимаю, в чем моя ошибка. И хотя изменить прошлое нееевозможно, теперь я обрел покой, зная, что тебе удалосссь добыть кристалл Зин-Малора...$b$bТы $gдолжен:должна; вернуть крисссталл...$b$bОн должен быть воззвращен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Вундом Ночным Охотником в деревне Звездопада и узнайте у него, куда нужно поместить кристалл Зин-Малора.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5253,'Кристалл Зин-Малора','Впечатляюще, $n. $B$BКристалл Зин-Малора никогда не вернется в храм, лежащий в руинах. Но я полагаю, что твои усилия уничтожить зло минувших лет не должно пойти прахом.$B$BНайди верховного друида Фэндрала Олений Шлем в Дарнасе, $n, и отдай ему кристалл. Он должен находится в руках тех, кто не злоупотребит его мощью. К тому же только самые сильные маги смогут управиться с артефактом такой мощи.','Доставьте Кристалл Зин-Малора верховному друиду Фэндралу Оленьему Шлему в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристалл Зин-Малора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Впечатляюще, $n. $B$BКристалл Зин-Малора никогда не вернется в храм, лежащий в руинах. Но я полагаю, что твои усилия уничтожить зло минувших лет не должно пойти прахом.$B$BНайди верховного друида Фэндрала Олений Шлем в Дарнасе, $n, и отдай ему кристалл. Он должен находится в руках тех, кто не злоупотребит его мощью. К тому же только самые сильные маги смогут управиться с артефактом такой мощи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте Кристалл Зин-Малора верховному друиду Фэндралу Оленьему Шлему в Дарнас.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5261,'Иган Меховщик','Иган Меховщик ищет охотника на зараженных волков. Это добрая новость, поскольку в последнее время в Долине Североземья появилось слишком много больных животных.$B$BЕсли тебе это интересно, то поговори с Иганом. Он за углом аббатства, если свернуть налево.','Поговорите с Иганом Меховщиком.','Что? Ищу ли я охотников на волков? Ну да, так и есть. А ты, наверное, ищешь работу?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Иган Меховщик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иган Меховщик ищет охотника на зараженных волков. Это добрая новость, поскольку в последнее время в Долине Североземья появилось слишком много больных животных.$B$BЕсли тебе это интересно, то поговори с Иганом. Он за углом аббатства, если свернуть налево.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Иганом Меховщиком.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Ищу ли я охотников на волков? Ну да, так и есть. А ты, наверное, ищешь работу?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5262,'Ошеломляющая истина','В воздухе еще вихрится пыль, а вы пытаетесь собраться с мыслями и осознать произошедшее. Весь ужас вашего положения все еще не укладывается в голове.$B$BВерховный рыцарь оказался демоном! И не просто демоном, а братом самого Вариматаса, верховного правителя Подгорода.$B$BВы бережно укладываете голову повелителя ужаса в суму. Разумеется, никто не поверит рассказанному вами без вещественных доказательств.$B$BНадо сообщить герцогу Николасу Зверенхоффу как можно скорее!','Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли.','Неужели все это время Алым Маршем правил демон! Все это время они служили злу, сами не подозревая об этом!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ошеломляющая истина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В воздухе еще вихрится пыль, а вы пытаетесь собраться с мыслями и осознать произошедшее. Весь ужас вашего положения все еще не укладывается в голове.$B$BВерховный рыцарь оказался демоном! И не просто демоном, а братом самого Вариматаса, верховного правителя Подгорода.$B$BВы бережно укладываете голову повелителя ужаса в суму. Разумеется, никто не поверит рассказанному вами без вещественных доказательств.$B$BНадо сообщить герцогу Николасу Зверенхоффу как можно скорее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите голову Бальназара герцогу Николасу Зверенхоффу в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неужели все это время Алым Маршем правил демон! Все это время они служили злу, сами не подозревая об этом!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5263,'Быстрее, выше, сильнее','Ты $gпроявил:проявила; прирожденную склонность к разрушению и умеешь следовать приказам. Эти похвальные качества весьма редко сочетаются. Полагаю, ты можешь стать совершенным орудием высшего промысла.$B$B*Зверенхофф сжимает кулаки*$B$BКел\'Тузад усадил своего мальчика на побегушках править в Стратхольме. Докажи мне свою верность и доблесть. Уничтожь барона Ривендера и принеси мне его голову.','Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу.','Давно мне не приходилось объявлять о новых героях. Ты будешь первым, кого лорд Максвелл удостоит аудиенции за много лет.','На руках барона кровь стольких людей, скольких ты не видел в своей жизни.','Вернитесь к герцогу Николасу Зверенхоффу в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Быстрее, выше, сильнее',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпроявил:проявила; прирожденную склонность к разрушению и умеешь следовать приказам. Эти похвальные качества весьма редко сочетаются. Полагаю, ты можешь стать совершенным орудием высшего промысла.$B$B*Зверенхофф сжимает кулаки*$B$BКел\'Тузад усадил своего мальчика на побегушках править в Стратхольме. Докажи мне свою верность и доблесть. Уничтожь барона Ривендера и принеси мне его голову.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Стратхольм и убейте барона Ривендера. Принесите его голову герцогу Николасу Зверенхоффу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давно мне не приходилось объявлять о новых героях. Ты будешь первым, кого лорд Максвелл удостоит аудиенции за много лет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На руках барона кровь стольких людей, скольких ты не видел в своей жизни.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к герцогу Николасу Зверенхоффу в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5264,'Лорд Максвелл Тиросс','Тебе оказана большая честь, $n.$B$BЛорд Максвелл хочет наградить тебя за твои заслуги перед Серебряным Рассветом!$B$BПоверь мне, это большая честь – Максвелл уже много лет не удостаивал никого аудиенции.','Поговорите с лордом Максвеллом Тироссом. Вы найдете его внутри храма.','Ты для нас очень ценный союзник, $N, и ты получишь достойную награду.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорд Максвелл Тиросс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе оказана большая честь, $n.$B$BЛорд Максвелл хочет наградить тебя за твои заслуги перед Серебряным Рассветом!$B$BПоверь мне, это большая честь – Максвелл уже много лет не удостаивал никого аудиенции.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с лордом Максвеллом Тироссом. Вы найдете его внутри храма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты для нас очень ценный союзник, $N, и ты получишь достойную награду.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5265,'Серебряный Оплот','Серебряный Оплот уже много лет закрыт и запечатан. Много лет не находилось достойных войти в него и прикоснуться к силе Серебряного Рассвета – до сегодняшнего дня.$B$BСеребряный Оплот распахнул врата перед тобой, $n.','Откройте Серебряный Оплот и получите награду.','Ух ты...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серебряный Оплот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Серебряный Оплот уже много лет закрыт и запечатан. Много лет не находилось достойных войти в него и прикоснуться к силе Серебряного Рассвета – до сегодняшнего дня.$B$BСеребряный Оплот распахнул врата перед тобой, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте Серебряный Оплот и получите награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5281,'Мятущиеся души','Многие погибли во время битвы при Стратхольме. Многие предпочли расстаться с жизнью, бросившись в полымя пожара, чем повергнуться порче и примкнуть к Плети.$B$BТеперь они скитаются по улицам Стратхольма в обличье бесплотных призраков.$B$BМы должны помочь им, $n.$B$BУ меня есть помощник по имени Эган, он спец по призракам и духам. Найди его. Он, вероятно, сейчас в Восточных Чумных землях близ Стратхольма, проверяет свои изобретения.','Найдите Эгана. В последний раз его видели недалеко от Стратхольма.','Неужели Ален нашел кого-то, у кого будет довольно храбрости помочь мне?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мятущиеся души',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие погибли во время битвы при Стратхольме. Многие предпочли расстаться с жизнью, бросившись в полымя пожара, чем повергнуться порче и примкнуть к Плети.$B$BТеперь они скитаются по улицам Стратхольма в обличье бесплотных призраков.$B$BМы должны помочь им, $n.$B$BУ меня есть помощник по имени Эган, он спец по призракам и духам. Найди его. Он, вероятно, сейчас в Восточных Чумных землях близ Стратхольма, проверяет свои изобретения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Эгана. В последний раз его видели недалеко от Стратхольма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неужели Ален нашел кого-то, у кого будет довольно храбрости помочь мне?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5282,'Мятущиеся души','Только безграничная ненависть к Плети поддерживает во мне силы и желание жить. Но я не фанатик. Не такой, как этот сброд из Алого ордена – они скорее убьют невинную нежить, чем удостоят хоть каплей сочувствия.$B$BВозьми мой излучатель. С его помощью ты сможешь освободить истерзанные души, обреченные на скитания в Стратхольме.$B$BСтреляй в призраков, бродящих по улицам. Освободи их!','Стреляйте в призрачных и неупокоенных горожан на улицах Стратхольма из бластера Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу.$B$BОсвободите 15 неупокоенных душ и возвращайтесь к Эгану.','<Эган утирает скупую слезу>$B$B$GВидел:Видела; ли ты мою матушку, $N? Она обрела свободу?$B$BТы просто образец благородства. Прими эту скромную награду за труды...','Сострадание - это то, что отличает нас от животных, $N. Помни, это...','Вернитесь к Эгану в Чумной лес, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мятущиеся души',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только безграничная ненависть к Плети поддерживает во мне силы и желание жить. Но я не фанатик. Не такой, как этот сброд из Алого ордена – они скорее убьют невинную нежить, чем удостоят хоть каплей сочувствия.$B$BВозьми мой излучатель. С его помощью ты сможешь освободить истерзанные души, обреченные на скитания в Стратхольме.$B$BСтреляй в призраков, бродящих по улицам. Освободи их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Стреляйте в призрачных и неупокоенных горожан на улицах Стратхольма из бластера Эгана. Когда душа вырвется из призрачной оболочки, выстрелите в нее еще раз, и она обретет свободу.$B$BОсвободите 15 неупокоенных душ и возвращайтесь к Эгану.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Эган утирает скупую слезу>$B$B$GВидел:Видела; ли ты мою матушку, $N? Она обрела свободу?$B$BТы просто образец благородства. Прими эту скромную награду за труды...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сострадание - это то, что отличает нас от животных, $N. Помни, это...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эгану в Чумной лес, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5283,'Искусство изготовления брони','Ты $Gпринял:приняла; верное решение.$B$BМы со стариной Железнусом друг друга не перевариваем. Этот кустарь косорукий знает, кто тут настоящий мастер.$B$BВеликие войны не выигрываются без хорошего доспеха. Когда дойдет до дела, никакой меч не спасет.$B$BИ никак иначе, так что возьмемся-ка за работу. Тебе нужно только показать мне, что у тебя есть природный талант к делу. Потом я выкую из тебя настоящего бронника и как следует отшлифую. Знаешь, как делать мифрил изысканным, а?','Изготовьте и отдайте Грумнусу 4 изысканных мифриловых шлема, 2 изысканных мифриловых сапога и 1 изысканную мифриловую кирасу.','Вернитесь к Грумнусу Сталевару в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искусство изготовления брони',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gпринял:приняла; верное решение.$B$BМы со стариной Железнусом друг друга не перевариваем. Этот кустарь косорукий знает, кто тут настоящий мастер.$B$BВеликие войны не выигрываются без хорошего доспеха. Когда дойдет до дела, никакой меч не спасет.$B$BИ никак иначе, так что возьмемся-ка за работу. Тебе нужно только показать мне, что у тебя есть природный талант к делу. Потом я выкую из тебя настоящего бронника и как следует отшлифую. Знаешь, как делать мифрил изысканным, а?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изготовьте и отдайте Грумнусу 4 изысканных мифриловых шлема, 2 изысканных мифриловых сапога и 1 изысканную мифриловую кирасу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грумнусу Сталевару в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5284,'Путь оружейника','Если станешь кузнецом, то к тебе очень часто будут обращаться за снаряжением всякие там герои и искатели приключений. Хотя порой работы невпроворот, спина ноет и дышать нечем, плата покрывает все с лихвой.$B$BДа, вот еще, $n, у кузнецов всегда водится золотишко!$B$BЕсли хочешь стать $Gодним:одной; из нас, тебе придется доказать, что ты сможешь заработать для меня пару звонких монет – то есть показать, что ты $Gусвоил:усвоила; все, чтобы стать специалистом по изготовлению оружия высшего качества. Приступай к работе!','Сделайте и отдайте Железнусу 4 палаша лунной стали, 4 массивных железных топора, 2 тяжелых мифриловых топора и 2 большие черные палицы.','Как раз вовремя! Заказчики уже ждут.\n\nДавай сюда свои изделия да слушай внимательнее. Сейчас ты делаешь первый шаг в карьере оружейника.','Железнус деловито складывает золотые монеты в аккуратные столбики.','Вернитесь к Железнусу Хладосталю в Великую Кузню в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь оружейника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если станешь кузнецом, то к тебе очень часто будут обращаться за снаряжением всякие там герои и искатели приключений. Хотя порой работы невпроворот, спина ноет и дышать нечем, плата покрывает все с лихвой.$B$BДа, вот еще, $n, у кузнецов всегда водится золотишко!$B$BЕсли хочешь стать $Gодним:одной; из нас, тебе придется доказать, что ты сможешь заработать для меня пару звонких монет – то есть показать, что ты $Gусвоил:усвоила; все, чтобы стать специалистом по изготовлению оружия высшего качества. Приступай к работе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сделайте и отдайте Железнусу 4 палаша лунной стали, 4 массивных железных топора, 2 тяжелых мифриловых топора и 2 большие черные палицы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как раз вовремя! Заказчики уже ждут.\n\nДавай сюда свои изделия да слушай внимательнее. Сейчас ты делаешь первый шаг в карьере оружейника.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Железнус деловито складывает золотые монеты в аккуратные столбики.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Железнусу Хладосталю в Великую Кузню в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5301,'Искусство изготовления брони','Моя работа приносит мне подлинное удовлетворение! Когда я вижу гордого воина Орды, защищенного моими доспехами, я понимаю, зачем родился на свет. Это как наваждение, $n, я без этого просто жить не могу.$b$bКонечно, этому я тебя научить не смогу – я могу только указать тебе путь. Ведь кузнечное ремесло, как и любая жизненная стезя, – это путешествие.$b$bЕсли ты хочешь стать $gодним:одной; из избранных, я, конечно, готов тебя учить. Но сначала тебе нужно выполнить мое задание.','Чтобы присоединиться к школе Брони, изготовьте и отдайте Окотосу 4 изысканных мифриловых шлема, 2 пары изысканных мифриловых сапог и 1 изысканную мифриловую кирасу.','Это последний шаг перед тем, как ты начнешь свою новую карьеру в школе Брони, $N. Если ты колеблешься, сейчас твой последний шанс отступить. А иначе готовься к жизни, полной славы!','Я буду ковать сталь, пока мое дыхание не иссякнет.','Вернитесь к Окофусу Жарбулату в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искусство изготовления брони',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя работа приносит мне подлинное удовлетворение! Когда я вижу гордого воина Орды, защищенного моими доспехами, я понимаю, зачем родился на свет. Это как наваждение, $n, я без этого просто жить не могу.$b$bКонечно, этому я тебя научить не смогу – я могу только указать тебе путь. Ведь кузнечное ремесло, как и любая жизненная стезя, – это путешествие.$b$bЕсли ты хочешь стать $gодним:одной; из избранных, я, конечно, готов тебя учить. Но сначала тебе нужно выполнить мое задание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Чтобы присоединиться к школе Брони, изготовьте и отдайте Окотосу 4 изысканных мифриловых шлема, 2 пары изысканных мифриловых сапог и 1 изысканную мифриловую кирасу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это последний шаг перед тем, как ты начнешь свою новую карьеру в школе Брони, $N. Если ты колеблешься, сейчас твой последний шанс отступить. А иначе готовься к жизни, полной славы!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я буду ковать сталь, пока мое дыхание не иссякнет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Окофусу Жарбулату в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5302,'Путь оружейника','В один прекрасный день я создам легендарный молот. Молот, достойный вождя!$b$bЭто труд всей моей жизни, $n. Мое главное и единственное увлечение. Я вижу, что ты можешь стать $gодним:одной; из нас – оружейником! И я помогу тебе в этом, если хочешь.$b$bТебе нужно только выполнить простое задание. При твоем мастерстве оно и впрямь несложное.','Изготовьте и отдайте Боргошу 4 палаша лунной стали, 4 массивных железных топора, 2 тяжелых мифриловых топора и 2 больших черных палицы.','Это последний шанс отказаться перед тем, как ты начнешь новую карьеру, $N. $GГотов:готова; ли ты к пути оружейника? Слава и почести ждут тебя.','Во славу Орды!','Вернитесь к Боргошу Сгибателю в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь оружейника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В один прекрасный день я создам легендарный молот. Молот, достойный вождя!$b$bЭто труд всей моей жизни, $n. Мое главное и единственное увлечение. Я вижу, что ты можешь стать $gодним:одной; из нас – оружейником! И я помогу тебе в этом, если хочешь.$b$bТебе нужно только выполнить простое задание. При твоем мастерстве оно и впрямь несложное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изготовьте и отдайте Боргошу 4 палаша лунной стали, 4 массивных железных топора, 2 тяжелых мифриловых топора и 2 больших черных палицы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это последний шанс отказаться перед тем, как ты начнешь новую карьеру, $N. $GГотов:готова; ли ты к пути оружейника? Слава и почести ждут тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Во славу Орды!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Боргошу Сгибателю в Оргриммар.',`completedtext_loc8`);
