INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5304,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5305,'Секрет безмятежности','В казематах Бастиона Алого ордена таится секрет безмятежности. Молотобоец из Багрового Легиона охраняет эту тайну. Срази его и принеси мне его фартук. За это я наделю тебя знанием о том, как изготовить зачарованный боевой молот!','Отправляйтесь в Стратхольм и убейте Молотобойца из Багрового легиона. Возьмите его фартук и возвращайтесь к Лилит.','Его фартук! Где он?','Вернитесь к Лилит Гибкой в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секрет безмятежности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В казематах Бастиона Алого ордена таится секрет безмятежности. Молотобоец из Багрового Легиона охраняет эту тайну. Срази его и принеси мне его фартук. За это я наделю тебя знанием о том, как изготовить зачарованный боевой молот!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Стратхольм и убейте Молотобойца из Багрового легиона. Возьмите его фартук и возвращайтесь к Лилит.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Его фартук! Где он?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лилит Гибкой в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5306,'Змеекамень Пленяющей Духов','Пусть ее красота не обманывает тебя, |3-6($c). Пленяющая Духов Вос\'гаджин безумна и смертельно опасна. $b$b<Килрам указывает на шрам у себя на лице.>$b$bДа, это ее рук дело – "удар любви", как она выразилась. $b$bНаконец настал момент для отмщения. $b$bВос\'гаджин ты найдешь на Пике Черной горы. Убей ее и принеси мне ее змеекамень. Сделай это, и я научу тебя секретам изготовления Лезвия Рассвета.','Отправляйтесь на Пик Черной горы, убейте Темную охотницу Вос\'гаджин. Заберите у нее змеекамень и принесите Килраму.','Знание – сила!','Легенда гласит, что если хотя бы раз применить змеекамень Вос\'гаджин, лезвие топора останется острым на тысячу лет!','Вернитесь к Килраму в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Змеекамень Пленяющей Духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пусть ее красота не обманывает тебя, |3-6($c). Пленяющая Духов Вос\'гаджин безумна и смертельно опасна. $b$b<Килрам указывает на шрам у себя на лице.>$b$bДа, это ее рук дело – "удар любви", как она выразилась. $b$bНаконец настал момент для отмщения. $b$bВос\'гаджин ты найдешь на Пике Черной горы. Убей ее и принеси мне ее змеекамень. Сделай это, и я научу тебя секретам изготовления Лезвия Рассвета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Пик Черной горы, убейте Темную охотницу Вос\'гаджин. Заберите у нее змеекамень и принесите Килраму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знание – сила!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Легенда гласит, что если хотя бы раз применить змеекамень Вос\'гаджин, лезвие топора останется острым на тысячу лет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Килраму в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (5307,'Порча','Если я краток с вами, значит, на то есть причины. Чертежи для создания великого меча порчи были похищены Черной Стражей: элитным отрядом скелетов барона Ривендера. $b$bДа, именно, Ривендера из Стратхольма. $b$bОружейник Черной Стражи хранит теперь эти чертежи как зеницу ока. $b$bУбейте его и принесите доказательство его смерти, и в благодарность я научу вас тому, что нужно для изготовления пылающей рапиры!','Найдите в Стратхольме оружейника Черной Стражи и уничтожьте его. Возьмите его Знак Черной Стражи и принесите Сирилу Плетебою.','Меч – самый лучший выбор, это же очевидно!','Вернитесь к Сирилу Плетебое в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порча',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если я краток с вами, значит, на то есть причины. Чертежи для создания великого меча порчи были похищены Черной Стражей: элитным отрядом скелетов барона Ривендера. $b$bДа, именно, Ривендера из Стратхольма. $b$bОружейник Черной Стражи хранит теперь эти чертежи как зеницу ока. $b$bУбейте его и принесите доказательство его смерти, и в благодарность я научу вас тому, что нужно для изготовления пылающей рапиры!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Стратхольме оружейника Черной Стражи и уничтожьте его. Возьмите его Знак Черной Стражи и принесите Сирилу Плетебою.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меч – самый лучший выбор, это же очевидно!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сирилу Плетебое в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (5321,'Спящий пробудился','Я шел к Заставе Мейстры, чтобы встретиться с Лиладрис Лунная Река, но решил остановиться здесь и немного вздремнуть. С тех пор как я очнулся от Изумрудного Сна, я все время такой сонный...$B$B*зевает*$b$bНе откажетесь проводить меня? Я так понимаю, Застава Мейстры находится к югу отсюда, в Ясеневом лесу, у дороги. Путь может быть опасен; я надеюсь, у вас есть друзья, которые смогут составить нам компанию.$B$BДа, и вот еще что: я могу заснуть по дороге, так что если вам нужно будет меня разбудить, сделайте это с помощью моего рога. Он в этом сундуке.','Сопроводите Керлониана Вечный Сумрак к Лиладрис Лунной Реке на Заставу Мейстры в Ясеневом лесу.','Прибыл ли Керлониан?','Сопроводите Керлониана Вечный Сумрак на Заставу Мейстры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спящий пробудился',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я шел к Заставе Мейстры, чтобы встретиться с Лиладрис Лунная Река, но решил остановиться здесь и немного вздремнуть. С тех пор как я очнулся от Изумрудного Сна, я все время такой сонный...$B$B*зевает*$b$bНе откажетесь проводить меня? Я так понимаю, Застава Мейстры находится к югу отсюда, в Ясеневом лесу, у дороги. Путь может быть опасен; я надеюсь, у вас есть друзья, которые смогут составить нам компанию.$B$BДа, и вот еще что: я могу заснуть по дороге, так что если вам нужно будет меня разбудить, сделайте это с помощью моего рога. Он в этом сундуке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите Керлониана Вечный Сумрак к Лиладрис Лунной Реке на Заставу Мейстры в Ясеневом лесу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прибыл ли Керлониан?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сопроводите Керлониана Вечный Сумрак на Заставу Мейстры.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5341,'Сокровище Баровых','В Некроситете находятся сокровища семейства Баровых. Я, Алексий Баров, один из двух оставшихся наследников нашего дома. Второй – мой брат, Велдон.$b$bЭтот жалкий трус бежал во время войны и по-прежнему длит свое никчемное существование в человеческом обличье.$b$bСейчас он ищет документы, чтобы унаследовать все состояние. Доберись до этих документов раньше моего брата, и я озолочу тебя!','Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову.','Отличная работа, |3-6($R). Теперь главное – подтвердить мое право наследования...','Кланяйся, $R. В конце концов, я дворянин, а ты – деревенщина без гроша за душой.','Вернитесь к Алексию Барову в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровище Баровых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Некроситете находятся сокровища семейства Баровых. Я, Алексий Баров, один из двух оставшихся наследников нашего дома. Второй – мой брат, Велдон.$b$bЭтот жалкий трус бежал во время войны и по-прежнему длит свое никчемное существование в человеческом обличье.$b$bСейчас он ищет документы, чтобы унаследовать все состояние. Доберись до этих документов раньше моего брата, и я озолочу тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Алексию Барову.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, |3-6($R). Теперь главное – подтвердить мое право наследования...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кланяйся, $R. В конце концов, я дворянин, а ты – деревенщина без гроша за душой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алексию Барову в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5342,'Последний из Баровых','Естественно, пока мой брат жив, могут возникать вопросы о порядке наследования. Я не допущу этого.$b$bПолагаю, ты, шваль, не побоишься замарать руки убийством.$b$bЗадание простое, надеюсь, ты справишься; если хочешь получить награду.$b$bУэлдон сидит под крылышком у Альянса в лагере Промозглого Ветра на востоке. Убей его и принеси мне голову.$b$b*Алексий зевает.*$b$bДавай-давай, иди.','Отправляйтесь в лагерь Промозглого Ветра, на земли Альянса, и убейте Вэлдона Барова. Отнесите его голову Алексию Барову.$b$bСоблюдайте осторожность – скорее всего, Вэлдона охраняют подхалимы из Альянса.','Чудесно! Теперь лишь в моих руках мощь и все сокровища дома Баровых.$B$B<Алекси швыряет в вас большим мешком.>$B$BСдачу оставь себе, животное.','Обеспечишь мне получение наследства, получишь свою долю.','Вернитесь к Алексию Барову в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний из Баровых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Естественно, пока мой брат жив, могут возникать вопросы о порядке наследования. Я не допущу этого.$b$bПолагаю, ты, шваль, не побоишься замарать руки убийством.$b$bЗадание простое, надеюсь, ты справишься; если хочешь получить награду.$b$bУэлдон сидит под крылышком у Альянса в лагере Промозглого Ветра на востоке. Убей его и принеси мне голову.$b$b*Алексий зевает.*$b$bДавай-давай, иди.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в лагерь Промозглого Ветра, на земли Альянса, и убейте Вэлдона Барова. Отнесите его голову Алексию Барову.$b$bСоблюдайте осторожность – скорее всего, Вэлдона охраняют подхалимы из Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно! Теперь лишь в моих руках мощь и все сокровища дома Баровых.$B$B<Алекси швыряет в вас большим мешком.>$B$BСдачу оставь себе, животное.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обеспечишь мне получение наследства, получишь свою долю.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Алексию Барову в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5343,'Сокровище Баровых','Милый братец Алексий. И зачем я, глупец, пощадил его? Я смотрел в лицо врага, нежити, и оставил его в живых.$b$b<Уэлдон сплевывает.>$b$bОн хочет отобрать МОЕ сокровище. Не бывать тому!$b$bНайди документы на мои владения, прежде чем эта мерзость дотянется до них своими костлявыми ручками, и получишь большую награду. Документы находятся в руинах Некроситета. Поспеши!','Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Вэлдону Барову.','Позаботься о моей будущем, а я позабочусь о твоем.','Вернитесь к Вэлдону Барову в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровище Баровых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Милый братец Алексий. И зачем я, глупец, пощадил его? Я смотрел в лицо врага, нежити, и оставил его в живых.$b$b<Уэлдон сплевывает.>$b$bОн хочет отобрать МОЕ сокровище. Не бывать тому!$b$bНайди документы на мои владения, прежде чем эта мерзость дотянется до них своими костлявыми ручками, и получишь большую награду. Документы находятся в руинах Некроситета. Поспеши!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Некроситет и добудьте сокровище семьи Баровых. Оно состоит из четырех документов: на Каэр Дарроу, на Брилл, на Мельницу Таррен и на Южнобережье. После выполнения задания вернитесь к Вэлдону Барову.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Позаботься о моей будущем, а я позабочусь о твоем.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вэлдону Барову в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5344,'Последний из Баровых','Документы у меня в руках, осталось только одно. Алексия придется убить. Когда он умрет, я смогу вздохнуть спокойно, не ожидая гибели от руки наемного убийцы.$b$bЗадание простое. Алексий находится под покровительством Орды – в Бастионе.$b$bНет, я не требую, чтобы ты прямо $gвзял и убил:взяла и убила; его, мне голова нужна! А как ты ее получишь... твое дело. Подобные размышления ниже моего аристократического достоинства.','Отправляйтесь в Бастион – на земли Орды – и убейте Алексия Барова. Отнесите его голову Вэлдону Барову.$b$bСоблюдайте осторожность – скорее всего, Алексия охраняет ордынская мразь.','О радость, о счастье! Наконец-то черная овца в стаде семьи Баровых мертва, и я получил наследство!$B$BВозьми деньги и убирайся, деревенщина.','Ты хочешь денег, да?','Вернитесь к Вэлдону Барову в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний из Баровых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Документы у меня в руках, осталось только одно. Алексия придется убить. Когда он умрет, я смогу вздохнуть спокойно, не ожидая гибели от руки наемного убийцы.$b$bЗадание простое. Алексий находится под покровительством Орды – в Бастионе.$b$bНет, я не требую, чтобы ты прямо $gвзял и убил:взяла и убила; его, мне голова нужна! А как ты ее получишь... твое дело. Подобные размышления ниже моего аристократического достоинства.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Бастион – на земли Орды – и убейте Алексия Барова. Отнесите его голову Вэлдону Барову.$b$bСоблюдайте осторожность – скорее всего, Алексия охраняет ордынская мразь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О радость, о счастье! Наконец-то черная овца в стаде семьи Баровых мертва, и я получил наследство!$B$BВозьми деньги и убирайся, деревенщина.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь денег, да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вэлдону Барову в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5361,'Семейное древо','Мой брат, Натака, находится на Заставе Скитающихся Духов в Пустошах. Я хотел бы попросить вас... не доставите ли ему этот отчет? С тех пор, как я писал ему последний раз, прошел целый год, и вот сейчас кентавры опять что-то затевают. Мой брат должен узнать обо всем.$B$BВам нужно будет отправиться в Когтистые горы – это к северу от Перекрестка, а потом свернуть на запад, в Обугленную долину. Пустоши находятся южнее долины. Следуйте по дороге на юг, и скоро увидите Заставу Скитающихся Духов.','Доставьте отчет стража утеса Долгорога Натаке Длинному Рогу на Заставу Скитающихся Духов в Пустоши.','Не знаю, как вы связаны с моим братом, но, вижу, он вам доверяет, |3-6($C).\n\nЯ – Натака Длинный Рог, и я приветствую вас на Заставе Скитающихся Духов! $C нам здесь точно не помешает. Поговорите с другими, наверняка у них найдется работа для вас.','Что у вас за новости, |3-6($C)? Ах, неужели это письмо от моего брата? Ну что ж, давайте его сюда!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семейное древо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой брат, Натака, находится на Заставе Скитающихся Духов в Пустошах. Я хотел бы попросить вас... не доставите ли ему этот отчет? С тех пор, как я писал ему последний раз, прошел целый год, и вот сейчас кентавры опять что-то затевают. Мой брат должен узнать обо всем.$B$BВам нужно будет отправиться в Когтистые горы – это к северу от Перекрестка, а потом свернуть на запад, в Обугленную долину. Пустоши находятся южнее долины. Следуйте по дороге на юг, и скоро увидите Заставу Скитающихся Духов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте отчет стража утеса Долгорога Натаке Длинному Рогу на Заставу Скитающихся Духов в Пустоши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не знаю, как вы связаны с моим братом, но, вижу, он вам доверяет, |3-6($C).\n\nЯ – Натака Длинный Рог, и я приветствую вас на Заставе Скитающихся Духов! $C нам здесь точно не помешает. Поговорите с другими, наверняка у них найдется работа для вас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что у вас за новости, |3-6($C)? Ах, неужели это письмо от моего брата? Ну что ж, давайте его сюда!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5381,'Рука Ируксоса','В руки Пылающего Клинка попала демоническая шкатулка, в которой хранится могущественный артефакт – Рука Ируксоса. Орки Пылающего Клинка используют ее, чтобы открывать демонические порталы на Поле Маннорок. Мы должны остановить нашествие демонов, захлестывающее наш мир!$B$BРасколи красный кристалл в Крепости Громового Топора этой киркой демонов: так ты сможешь добыть демоническую шкатулку.','Добудьте в Крепости Громового Топора демоническую шкатулку, а затем принесите ее и кирку демонов Тайге Мудрой Гриве в Деревню Ночных Охотников.','О, демоническая шкатулка... Наконец-то я увидел ее. Послушай, |3-6($C), дай-ка ее мне, и я ее открою... и покажу тебе Руку Ируксоса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рука Ируксоса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В руки Пылающего Клинка попала демоническая шкатулка, в которой хранится могущественный артефакт – Рука Ируксоса. Орки Пылающего Клинка используют ее, чтобы открывать демонические порталы на Поле Маннорок. Мы должны остановить нашествие демонов, захлестывающее наш мир!$B$BРасколи красный кристалл в Крепости Громового Топора этой киркой демонов: так ты сможешь добыть демоническую шкатулку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте в Крепости Громового Топора демоническую шкатулку, а затем принесите ее и кирку демонов Тайге Мудрой Гриве в Деревню Ночных Охотников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, демоническая шкатулка... Наконец-то я увидел ее. Послушай, |3-6($C), дай-ка ее мне, и я ее открою... и покажу тебе Руку Ируксоса.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5382,'Доктор Теолен Крастинов по прозвищу Мясник','Крастинов виновен в тысячах смертей. Справедливость должна восторжествовать – пусть он вкусит собственного блюда.$b$bНайди его и заставь испытать мучения его бессчетных жертв. Когда он умрет, сожги наши останки. Пусть обратятся в пепел, $n.','Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркоффов. Выполнив задание, возвращайтесь к Еве Саркофф.','Душа моя исцелена, $n. Ты оказал нам с мужем огромную услугу, но это еще не все.','Мясника должно остановить!','Вернитесь к Еве Саркофф на озеро Дарроумир, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доктор Теолен Крастинов по прозвищу Мясник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крастинов виновен в тысячах смертей. Справедливость должна восторжествовать – пусть он вкусит собственного блюда.$b$bНайди его и заставь испытать мучения его бессчетных жертв. Когда он умрет, сожги наши останки. Пусть обратятся в пепел, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Некроситете доктора Теолена Крастинова. Убейте его, затем сожгите останки Евы и Люсьена Саркоффов. Выполнив задание, возвращайтесь к Еве Саркофф.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Душа моя исцелена, $n. Ты оказал нам с мужем огромную услугу, но это еще не все.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мясника должно остановить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Еве Саркофф на озеро Дарроумир, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5383,'Мешок ужасов Крастинова','Вы открываете мешок. Внутри – различные инструменты пытки. Ваше внимание привлекает странный предмет – сосуд крови, все еще теплый.$b$bПожалуй, Саркофф могла бы заинтересоваться вашей находкой.','Отнесите мешок ужасов Еве Саркофф в Каэр Дарроу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мешок ужасов Крастинова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы открываете мешок. Внутри – различные инструменты пытки. Ваше внимание привлекает странный предмет – сосуд крови, все еще теплый.$b$bПожалуй, Саркофф могла бы заинтересоваться вашей находкой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите мешок ужасов Еве Саркофф в Каэр Дарроу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5384,'Киртонос Глашатай','Вот она, $n.$B$B*Ева указывает на сосуд в мешке.*$b$bКровь невинных. Чистейшая кровь, умилостивление хозяина Крастинова.$b$bПри помощи этой крови можно вызвать Киртоноса, и именно она поможет его уничтожить.$b$bОтнести эту кровь на балкон, помести в жаровню. Киртонос явится на зов – он не сможет устоять. Когда он явится, обрушь на него ярость и гнев тысяч невинно убиенных.$b$bЕсли ты добьешься успеха, мы на славу отблагодарим тебя.','Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос.$b$bСражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф.','Киртонос мертв, и страшная глава истории Некроситета подошла к концу. Но твои деяния не окончены. Многие узнали о твоих подвигах. Возьми это, $n. Это часть нашей сущности. При ее помощи ты сможешь связаться с другими павшими душами Каэр Дарроу.','Соблюдай осторожность, Киртонос – опытный боец.','Вернитесь к Еве Саркофф на озеро Дарроумир, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Киртонос Глашатай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот она, $n.$B$B*Ева указывает на сосуд в мешке.*$b$bКровь невинных. Чистейшая кровь, умилостивление хозяина Крастинова.$b$bПри помощи этой крови можно вызвать Киртоноса, и именно она поможет его уничтожить.$b$bОтнести эту кровь на балкон, помести в жаровню. Киртонос явится на зов – он не сможет устоять. Когда он явится, обрушь на него ярость и гнев тысяч невинно убиенных.$b$bЕсли ты добьешься успеха, мы на славу отблагодарим тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Некроситет с кровью невинных. Найдите балкон и вылейте кровь в жаровню. На зов явится Киртонос.$b$bСражайтесь как герой, не сдавайтесь! Уничтожьте Киртоноса и возвращайтесь к Еве Саркофф.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Киртонос мертв, и страшная глава истории Некроситета подошла к концу. Но твои деяния не окончены. Многие узнали о твоих подвигах. Возьми это, $n. Это часть нашей сущности. При ее помощи ты сможешь связаться с другими павшими душами Каэр Дарроу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Соблюдай осторожность, Киртонос – опытный боец.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Еве Саркофф на озеро Дарроумир, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5385,'Останки Трея Светогорна','Вы осторожно поднимаете мешок и собираетесь возвращаться к Джессире Лунной Радуге на границу Ясеневого леса и Оскверненного леса. Вы надеетесь, что паладин будет с почестями погребен, когда его останки будут доставлены его друзьям.','Принесите останки Трея Светогорна Джессире Лунной Радуге в Оскверненный лес.','Тебе удалось! Хвала Элуне и всем силам, что ты почитаешь, $N! Сегодня ты $Gсовершил:совершила; деяние благое и почетное. Я уверена, что Арконарин возрадуется, узнав, что ты не только $Gспас:спасла; ее, но так же $Gубил:убила; тварь, которая истязала одного из лучших ее друзей.$B$BЯ бы хотела сделать для тебя больше, но прошу тебя – прими эту скромную награду.','Как дела в Джеденаре, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Останки Трея Светогорна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы осторожно поднимаете мешок и собираетесь возвращаться к Джессире Лунной Радуге на границу Ясеневого леса и Оскверненного леса. Вы надеетесь, что паладин будет с почестями погребен, когда его останки будут доставлены его друзьям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите останки Трея Светогорна Джессире Лунной Радуге в Оскверненный лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось! Хвала Элуне и всем силам, что ты почитаешь, $N! Сегодня ты $Gсовершил:совершила; деяние благое и почетное. Я уверена, что Арконарин возрадуется, узнав, что ты не только $Gспас:спасла; ее, но так же $Gубил:убила; тварь, которая истязала одного из лучших ее друзей.$B$BЯ бы хотела сделать для тебя больше, но прошу тебя – прими эту скромную награду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как дела в Джеденаре, $N?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (5386,'Дорога рыбка к обеду','Давненько на Заставе Скитающихся Духов не наслаждались запахом жареной рыбки... Тролли, живущие в Деревне Ночных Охотников – отличные рыбаки, вот только из-за разбушевавшихся в наших краях кентавров мне никак не выкроить времени, чтобы добраться до них.$B$BПослушай-ка, окажи мне услугу: отправляйся в Деревню Ночных Охотников. Разыщи там Джинар\'Зиллена, потолкуй с ним и принеси мне рыбок-кровобрюхов: я их просто обожаю! К югу отсюда идет дорога: она приведет тебя на запад, аккурат в деревню троллей.','Отправляйтесь в Деревню Ночных Охотников и поговорите с Джинар\'Зилленом, а затем принесите Натаке Длинному Рогу 2 рыбы-кровобрюха.','У меня копыта подергиваются и слюни текут от нетерпения, как подумаю о жареном кровобрюхе... Ты ведь принес мне кровобрюха, верно?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога рыбка к обеду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давненько на Заставе Скитающихся Духов не наслаждались запахом жареной рыбки... Тролли, живущие в Деревне Ночных Охотников – отличные рыбаки, вот только из-за разбушевавшихся в наших краях кентавров мне никак не выкроить времени, чтобы добраться до них.$B$BПослушай-ка, окажи мне услугу: отправляйся в Деревню Ночных Охотников. Разыщи там Джинар\'Зиллена, потолкуй с ним и принеси мне рыбок-кровобрюхов: я их просто обожаю! К югу отсюда идет дорога: она приведет тебя на запад, аккурат в деревню троллей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Деревню Ночных Охотников и поговорите с Джинар\'Зилленом, а затем принесите Натаке Длинному Рогу 2 рыбы-кровобрюха.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня копыта подергиваются и слюни текут от нетерпения, как подумаю о жареном кровобрюхе... Ты ведь принес мне кровобрюха, верно?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5401,'Жетон Серебряного Рассвета') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жетон Серебряного Рассвета',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (5401,'All who fight evil on behalf of the Argent Dawn must don our commission. Wearing such will earn your right to claim rewards our quartermasters have to offer.$B$BWhile under commission, you\'ll be able to acquire Scourgestones from slain Scourge; these are marks of insignia that they sometimes possess. Procure these insignia and bring them to me. For each set you turn in, you will receive our marker of heroism - the Argent Dawn Valor Token.$B$BAchieve your destiny, $C - join the fight today!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','All who fight evil on behalf of the Argent Dawn must don our commission. Wearing such will earn your right to claim rewards our quartermasters have to offer.$B$BWhile under commission, you\'ll be able to acquire Scourgestones from slain Scourge; these are marks of insignia that they sometimes possess. Procure these insignia and bring them to me. For each set you turn in, you will receive our marker of heroism - the Argent Dawn Valor Token.$B$BAchieve your destiny, $C - join the fight today!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5402,'Камни приспешников плети','Вернитесь к офицеру Чистосердой из ордена Серебряного Рассвета в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камни приспешников плети',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к офицеру Чистосердой из ордена Серебряного Рассвета в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (5402,'Congratulations, $n - I am pleased to award you with an Argent Dawn valor token!$B$BThe tokens serve two purposes. One - they can be used to further your standing within the Argent Dawn; to do so may avail you options and rewards that are reserved for our honored and revered allies. Two - they can be given to our quartermasters, along with coin, as payment for some of the Dawn\'s more prized items.$B$BWhatever you decide, know that you are earning your commission. Well done!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Congratulations, $n - I am pleased to award you with an Argent Dawn valor token!$B$BThe tokens serve two purposes. One - they can be used to further your standing within the Argent Dawn; to do so may avail you options and rewards that are reserved for our honored and revered allies. Two - they can be given to our quartermasters, along with coin, as payment for some of the Dawn\'s more prized items.$B$BWhatever you decide, know that you are earning your commission. Well done!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5403,'Камни захватчиков Плети','Вернитесь к офицеру Чистосердой из ордена Серебряного Рассвета в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камни захватчиков Плети',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к офицеру Чистосердой из ордена Серебряного Рассвета в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (5403,'Congratulations, $n - I am pleased to award you with an Argent Dawn valor token!$B$BEach valor token handed out to worthy recipients is a sign of the tide turning against the Scourge. With more and more heroes fighting the Scourge in their own lands, the Argent Dawn will assuredly be at the forefront when the time comes to wage war on the ultimate evil of the Scourge. I hope that the valor you\'ve shown what it took to acquiring your token will carry the day then as well!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Congratulations, $n - I am pleased to award you with an Argent Dawn valor token!$B$BEach valor token handed out to worthy recipients is a sign of the tide turning against the Scourge. With more and more heroes fighting the Scourge in their own lands, the Argent Dawn will assuredly be at the forefront when the time comes to wage war on the ultimate evil of the Scourge. I hope that the valor you\'ve shown what it took to acquiring your token will carry the day then as well!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5404,'Камни осквернителей Плети','Вернитесь к офицеру Чистосердой из ордена Серебряного Рассвета в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камни осквернителей Плети',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к офицеру Чистосердой из ордена Серебряного Рассвета в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (5404,'Congratulations, $n - I am pleased to award you with an Argent Dawn valor token!$B$BTo acquire a valor token in such a manner indicates that you are a true hero in the cause of good. We value all effort brought to bear against the Scourge, but to take down one of their leaders is to truly deliver onto them a crushing defeat!$B$BFor the Dawn, my brother!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Congratulations, $n - I am pleased to award you with an Argent Dawn valor token!$B$BTo acquire a valor token in such a manner indicates that you are a true hero in the cause of good. We value all effort brought to bear against the Scourge, but to take down one of their leaders is to truly deliver onto them a crushing defeat!$B$BFor the Dawn, my brother!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5405,'Жетон Серебряного Рассвета') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жетон Серебряного Рассвета',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5406,'Камни осквернителей Плети','Вернитесь к офицеру Гарушу из ордена Серебряного Рассвета в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камни осквернителей Плети',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к офицеру Гарушу из ордена Серебряного Рассвета в Западные Чумные земли.',`completedtext_loc8`);
