INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5408,'Камни приспешников плети','Вернитесь к офицеру Гарушу из ордена Серебряного Рассвета в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камни приспешников плети',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к офицеру Гарушу из ордена Серебряного Рассвета в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5421,'Рыбка в ведерке','Я награжу любого, кто хоть немного облегчит мою жизнь... Чем меньше у меня работы, тем лучше, дружище!$B$BЗдесь неподалеку, в деревне Ночных Охотников, прямо за пристанью, я расставил ловушки на моллюсков. Много, много ловушек! Будь так $gлюбезен:любезна;, сделай за меня мою работу: собери улов и принеси мне, а я уж тебя награжу кое-чем нужным... ну, ты $gпонял:поняла;, да?','Соберите 5 моллюсков в ловушках возле деревни Ночных Охотников и вернитесь с ними к Джинар\'Зиллену.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рыбка в ведерке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я награжу любого, кто хоть немного облегчит мою жизнь... Чем меньше у меня работы, тем лучше, дружище!$B$BЗдесь неподалеку, в деревне Ночных Охотников, прямо за пристанью, я расставил ловушки на моллюсков. Много, много ловушек! Будь так $gлюбезен:любезна;, сделай за меня мою работу: собери улов и принеси мне, а я уж тебя награжу кое-чем нужным... ну, ты $gпонял:поняла;, да?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 моллюсков в ловушках возле деревни Ночных Охотников и вернитесь с ними к Джинар\'Зиллену.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5441,'Ленивые батраки','Проклятые батраки! Им велено валить лес, но они все время пытаются отлынивать. Мне нужен кто-то, кто их приструнит. Ты, |3-6($r), мне, пожалуй, годишься. На тебе дубинку – ступай и всыпь этим бездельникам. Хороший тумак заставит их взяться за ум! Управишься – не забудь вернуть дубинку.$b$bПроклятые лентяи...','Проучите ленивых батраков дубинкой штейгера. Разбудите 5 батраков, потом верните дубинку штейгеру Тазз\'рилу в Долине Испытаний.','Отлично, отлично! В следующий раз будут знать, как дрыхнуть на работе! Спасибо за помощь!','Негодяи, бездельники…\n\nЧто? Где моя дубинка? Ну что, удалось тебе всыпать этим лентяям?','Вернитесь к штейгеру Тазз\'рилу в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ленивые батраки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проклятые батраки! Им велено валить лес, но они все время пытаются отлынивать. Мне нужен кто-то, кто их приструнит. Ты, |3-6($r), мне, пожалуй, годишься. На тебе дубинку – ступай и всыпь этим бездельникам. Хороший тумак заставит их взяться за ум! Управишься – не забудь вернуть дубинку.$b$bПроклятые лентяи...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проучите ленивых батраков дубинкой штейгера. Разбудите 5 батраков, потом верните дубинку штейгеру Тазз\'рилу в Долине Испытаний.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, отлично! В следующий раз будут знать, как дрыхнуть на работе! Спасибо за помощь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Негодяи, бездельники…\n\nЧто? Где моя дубинка? Ну что, удалось тебе всыпать этим лентяям?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Тазз\'рилу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5461,'Рас Ледяной Шепот – человек','Нежить боится жизни не меньше, чем живые – смерти. Ступившие на путь не-жизни нередко уничтожают все свидетельства прежнего бытия.$b$bК сожалению, для создания артефакта, способного превратить Раса Ледяного Шепота в смертного, мы должны отыскать какой-нибудь предмет, сохранившийся со времени его настоящей жизни.$b$bОтправляйся в разрушенный город Стромгард, родину Ледяного Шепота, и найди такой предмет. Удачи тебе, $n.','Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье Мардуку.','Честно говоря, я сомневался, что эта вещь вообще существует. Перед нами открывается удивительная возможность – главное, ее не пропустить.$B$BГотовься, $N, ведь то, о чем я тебя попрошу, низведет тебя в самые глубины Преисподней.','Да, книгу Воспоминаний нелегко найти, $N.','Вернитесь к мировому судье Мардуку на озеро Дарроумир, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рас Ледяной Шепот – человек',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нежить боится жизни не меньше, чем живые – смерти. Ступившие на путь не-жизни нередко уничтожают все свидетельства прежнего бытия.$b$bК сожалению, для создания артефакта, способного превратить Раса Ледяного Шепота в смертного, мы должны отыскать какой-нибудь предмет, сохранившийся со времени его настоящей жизни.$b$bОтправляйся в разрушенный город Стромгард, родину Ледяного Шепота, и найди такой предмет. Удачи тебе, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в высокогорья Арати, в руины Стромгарда. Поищите в Стромгарде книгу воспоминаний. Если удастся ее отыскать, отнесите ее мировому судье Мардуку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Честно говоря, я сомневался, что эта вещь вообще существует. Перед нами открывается удивительная возможность – главное, ее не пропустить.$B$BГотовься, $N, ведь то, о чем я тебя попрошу, низведет тебя в самые глубины Преисподней.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, книгу Воспоминаний нелегко найти, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Мардуку на озеро Дарроумир, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5462,'Рас Ледяной Шепот – гибель','Оскверненной душе можно противопоставить особые памятные предметы.$b$bГоворят, будто Ледяной Шепот встал под знамена Короля-лича в Стратхольме. Он добровольно лишил себя жизни с целью влиться в ряды нежити.$b$bИменно в тех землях следует искать память о его человеческом облике.$b$bВ часовне Последней Надежды ты найдешь Леонида Барталомея Чтимого, некогда бывшего рабом Плети, освобожденного королевой банши, но отдавшего свою верность Серебряному Рассвету. Быть может, он знает больше, чем я. В путь!','Отправляйтесь в часовню Последней Надежды в Восточных Чумных землях и найдите Леонида Барталомея Чтимого. Покажите ему книгу воспоминаний и расскажите обо всем, о чем удалось узнать.','Не задавай вопросов, если не хочешь узнать ответы.','Не задавай вопросов, если не хочешь узнать ответы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рас Ледяной Шепот – гибель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оскверненной душе можно противопоставить особые памятные предметы.$b$bГоворят, будто Ледяной Шепот встал под знамена Короля-лича в Стратхольме. Он добровольно лишил себя жизни с целью влиться в ряды нежити.$b$bИменно в тех землях следует искать память о его человеческом облике.$b$bВ часовне Последней Надежды ты найдешь Леонида Барталомея Чтимого, некогда бывшего рабом Плети, освобожденного королевой банши, но отдавшего свою верность Серебряному Рассвету. Быть может, он знает больше, чем я. В путь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в часовню Последней Надежды в Восточных Чумных землях и найдите Леонида Барталомея Чтимого. Покажите ему книгу воспоминаний и расскажите обо всем, о чем удалось узнать.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не задавай вопросов, если не хочешь узнать ответы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не задавай вопросов, если не хочешь узнать ответы.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5463,'Дар Менетила','Рас Ледяной Шепот некогда тоже был человеком. Я собственными глазами видел, как он вручил свою бессмертную душу Королю-личу. Он приставил к своему горлу кинжал и с улыбкой перерезал себе глотку от уха до уха. Его мертвое тело упало в центр пентаграммы. Король-лич бросил взгляд на мертвого мага, и в ту же секунду Рас Ледяной Шепот восстал в обличье лича.$B$B*Леонид опускает глаза на мгновенье и снова продолжает рассказ*$B$BДа, |3-6($r), я помню. У того, что ты ищешь, есть имя – Дар Менетила: это земля, благословленная Королем-личом – священное место Плети.','Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу воспоминаний на оскверненную землю.','Вы кладете книгу на оскверненную землю.','От Дара Менетила веет могильным холодом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар Менетила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рас Ледяной Шепот некогда тоже был человеком. Я собственными глазами видел, как он вручил свою бессмертную душу Королю-личу. Он приставил к своему горлу кинжал и с улыбкой перерезал себе глотку от уха до уха. Его мертвое тело упало в центр пентаграммы. Король-лич бросил взгляд на мертвого мага, и в ту же секунду Рас Ледяной Шепот восстал в обличье лича.$B$B*Леонид опускает глаза на мгновенье и снова продолжает рассказ*$B$BДа, |3-6($r), я помню. У того, что ты ищешь, есть имя – Дар Менетила: это земля, благословленная Королем-личом – священное место Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Стратхольм и отыщите Дар Менетила. Положите книгу воспоминаний на оскверненную землю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы кладете книгу на оскверненную землю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','От Дара Менетила веет могильным холодом.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5464,'Дар Менетила','Души падших цепляются за любое олицетворение их прежное жизни и превращают любой значимый для них предмет в Книгу Души. Вы поднимаете предмет и прячете в сумку.','Отнесите Книгу Души Леониду Барталомею в Восточные Чумные земли.','Как эта душа цепляется за книгу, также она будет цепляться и за человеческое обличье Раса Ледяного Шепота.','<Леонид вздрагивает>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дар Менетила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Души падших цепляются за любое олицетворение их прежное жизни и превращают любой значимый для них предмет в Книгу Души. Вы поднимаете предмет и прячете в сумку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Книгу Души Леониду Барталомею в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как эта душа цепляется за книгу, также она будет цепляться и за человеческое обличье Раса Ледяного Шепота.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Леонид вздрагивает>',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5465,'Книга души','Отнеси книгу Мардуку, $n, он расскажет тебе, что делать дальше.','Возвращайтесь к мировому судье Мардуку в Каэр Дарроу. Покажите ему Книгу Души.','Признаться, я ожидал вновь увидеть тебя в обличье несчастного призрака.','Неужели тебе удалось сделать невозможное?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Книга души',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси книгу Мардуку, $n, он расскажет тебе, что делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к мировому судье Мардуку в Каэр Дарроу. Покажите ему Книгу Души.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Признаться, я ожидал вновь увидеть тебя в обличье несчастного призрака.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели тебе удалось сделать невозможное?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5466,'Рас Ледяной Шепот – лич','Осталось одно задание, $n – бросить вызов личу Расу Ледяному Шепоту.$b$bВоспользуйся против него силой Книги – не знай пощады! Терпи удары, которые обрушит на тебя злобная тварь. Не бойся боли!$b$bКогда ритуал будет завершен, Рас снова станет смертным. Именно в этот момент его необходимо убить. Срази злодея и забери его голову','Отыщите в Некроситете Раса Ледяного Шепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Ледяного Шепота. Отнесите голову мировому судье Мардуку.','Десять тысяч душ возопили единым гласом! Ты $Gнанес:нанесла; смертельный удар Плети и ее хозяевам.','На твоих плечах покоится бремя тысяч неупокоенных душ, $N.','Вернитесь к мировому судье Мардуку на озеро Дарроумир, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рас Ледяной Шепот – лич',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осталось одно задание, $n – бросить вызов личу Расу Ледяному Шепоту.$b$bВоспользуйся против него силой Книги – не знай пощады! Терпи удары, которые обрушит на тебя злобная тварь. Не бойся боли!$b$bКогда ритуал будет завершен, Рас снова станет смертным. Именно в этот момент его необходимо убить. Срази злодея и забери его голову',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите в Некроситете Раса Ледяного Шепота. Найдя его, воспользуйтесь Книгой Души против его посмертного облика. Если удастся превратить Раса в смертного, убейте его и заберите человеческую голову Раса Ледяного Шепота. Отнесите голову мировому судье Мардуку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Десять тысяч душ возопили единым гласом! Ты $Gнанес:нанесла; смертельный удар Плети и ее хозяевам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На твоих плечах покоится бремя тысяч неупокоенных душ, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мировому судье Мардуку на озеро Дарроумир, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5481,'Задание Толстяка','Хозяину надо растения. У нас большие руки, цветы рвать никак. Ты нам помогать, мы тебя не трогать. Нам надо мракоцвет, он растет тут и у дороги.$B$BТы соберешь – отнеси хозяину Холланду на кладбище в Брилл.','Соберите 3 ветки мракоцвета для младшего аптекаря Холланда на кладбище Брилла.','Что это? Мракоцвет?! Зачем он мне сдался?! Эта тупая гора мяса собирает ромашки и привлекает – сколько, Темная Госпожа знает, – к этому делу таких простаков, как ты! Без обид.\n\nЛадно, главное, что ты здесь. Я не собираюсь тратить свое время на то, чтобы объяснить этому поганищу элементарные вещи. Так что, может, ты соберешь для меня этот проклятый погибельник?','Где это никчемное поганище? Ты принес мне то, что мне нужно? Если нет, то иди и не возвращайся, пока не соберешь достаточно цветков!','Вернитесь к младшему аптекарю Холланду в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание Толстяка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хозяину надо растения. У нас большие руки, цветы рвать никак. Ты нам помогать, мы тебя не трогать. Нам надо мракоцвет, он растет тут и у дороги.$B$BТы соберешь – отнеси хозяину Холланду на кладбище в Брилл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 3 ветки мракоцвета для младшего аптекаря Холланда на кладбище Брилла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Мракоцвет?! Зачем он мне сдался?! Эта тупая гора мяса собирает ромашки и привлекает – сколько, Темная Госпожа знает, – к этому делу таких простаков, как ты! Без обид.\n\nЛадно, главное, что ты здесь. Я не собираюсь тратить свое время на то, чтобы объяснить этому поганищу элементарные вещи. Так что, может, ты соберешь для меня этот проклятый погибельник?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где это никчемное поганище? Ты принес мне то, что мне нужно? Если нет, то иди и не возвращайся, пока не соберешь достаточно цветков!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к младшему аптекарю Холланду в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5482,'Погибельник','Теперь ты понимаешь, в каком затруднительном положении я нахожусь, $n? Это нечто все еще ходит там и собирает не те растения. Я непременно отблагодарю тебя, если ты соберешь то, что мне нужно. Принеси мне погибельник, и я щедро тебя награжу.$B$BНасколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла. Поторопись – и будь $gосторожен:осторожна; – в тех местах полно гноллов.','Соберите 10 веток погибельника для младшего аптекаря Холланда.','Я полагаю, ты уже собрал достаточно погибельника?','Вернитесь к младшему аптекарю Холланду в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погибельник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты понимаешь, в каком затруднительном положении я нахожусь, $n? Это нечто все еще ходит там и собирает не те растения. Я непременно отблагодарю тебя, если ты соберешь то, что мне нужно. Принеси мне погибельник, и я щедро тебя награжу.$B$BНасколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла. Поторопись – и будь $gосторожен:осторожна; – в тех местах полно гноллов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 веток погибельника для младшего аптекаря Холланда.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я полагаю, ты уже собрал достаточно погибельника?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к младшему аптекарю Холланду в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5501,'Собиратель костей','Мы тут на золотой жиле сидим, на золотой жиле! Знаешь, что это? Кости кодо!.. Кости кодо изменят мир раз и навсегда! У меня масса клиентов, которые делают из этих костей мебель, музыкальные инструменты – даже взрывчатый порошок, чтоб тебе знать!$B$BСюда приходит караван, забирает у меня кости, а потом караванщики продают их в Деревне Ночных Охотников. И неплохая выручка, да, очень неплохая... Если пойдешь на юг отсюда, то доберешься прямиком до Кладбища кодо. Принеси мне десяток костей, а я дам тебе кое-что взамен. Ну что, идет?','Принесите 10 костей с Кладбища кодо в хижину Кормека и отдайте Биббли Скобкофузу.','Ну, где они, мои косточки, где же они? Караван вот-вот придет. Всего десять костей – и это будет мой звездный час, клянусь чем угодно! Вот увидишь!','Вернитесь к Биббли Скобкофузу в Пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собиратель костей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы тут на золотой жиле сидим, на золотой жиле! Знаешь, что это? Кости кодо!.. Кости кодо изменят мир раз и навсегда! У меня масса клиентов, которые делают из этих костей мебель, музыкальные инструменты – даже взрывчатый порошок, чтоб тебе знать!$B$BСюда приходит караван, забирает у меня кости, а потом караванщики продают их в Деревне Ночных Охотников. И неплохая выручка, да, очень неплохая... Если пойдешь на юг отсюда, то доберешься прямиком до Кладбища кодо. Принеси мне десяток костей, а я дам тебе кое-что взамен. Ну что, идет?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 костей с Кладбища кодо в хижину Кормека и отдайте Биббли Скобкофузу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, где они, мои косточки, где же они? Караван вот-вот придет. Всего десять костей – и это будет мой звездный час, клянусь чем угодно! Вот увидишь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Биббли Скобкофузу в Пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5502,'Опекун Орды','Ты $gбыл:была; очень $gдобр:добра; ко мне, $n. Я и представить не мог, что Детская неделя пройдет так весело. Спасибо.$b$bВот бы всем ребятам в приюте повезло, как мне, – мы сделали столько всего интересного! Как ты думаешь, сможем мы еще раз найти Бухса Забабахса и купить у него стойку с пластиковыми мечами? Думаю, он так и ходит со своей тележкой по главной дороге Волока. Тогда и остальные ребята в приюте тоже смогут повеселиться!$b$bА после этого я вернусь домой.','Может духи благословят тебя, $N. Ты $Gсделал:сделала; для сиротки больше, чем кто либо. Спасибо. Ты воплощение того, что значит быть героем Орды!$B$BПожалуйста, если у тебя будет время, можешь заходить к нам. Я знаю, что сиротка будет очень рад, как и я.','Мне очень приятно видеть тебя снова, $N. Никаких не было не приятностей во время Детской недели?','Вернитесь к попечительнице сирот Батлвейл в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опекун Орды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gбыл:была; очень $gдобр:добра; ко мне, $n. Я и представить не мог, что Детская неделя пройдет так весело. Спасибо.$b$bВот бы всем ребятам в приюте повезло, как мне, – мы сделали столько всего интересного! Как ты думаешь, сможем мы еще раз найти Бухса Забабахса и купить у него стойку с пластиковыми мечами? Думаю, он так и ходит со своей тележкой по главной дороге Волока. Тогда и остальные ребята в приюте тоже смогут повеселиться!$b$bА после этого я вернусь домой.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Может духи благословят тебя, $N. Ты $Gсделал:сделала; для сиротки больше, чем кто либо. Спасибо. Ты воплощение того, что значит быть героем Орды!$B$BПожалуйста, если у тебя будет время, можешь заходить к нам. Я знаю, что сиротка будет очень рад, как и я.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне очень приятно видеть тебя снова, $N. Никаких не было не приятностей во время Детской недели?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к попечительнице сирот Батлвейл в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5503,'Жетон Серебряного Рассвета') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жетон Серебряного Рассвета',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5504,'Оплечья Рассвета','Тебе причитается награда за верную службу Серебряному Рассвету, $n. Тебе удалось завоевать всеобщее почтение. Мне поручено передать – ты можешь купить один из самых наших ценных предметов – оплечье защиты от магии.$b$bЕсли прикрепить его к доспехам, твое сопротивление силам одного из направлений магии возрастет. За это оплечье я попрошу от тебя не менее 10 знаков доблести Серебряного Рассвета.','Принесите 10 знаков доблести Серебряного Рассвета интенданту Хасане в Бастион, что в Западных Чумных землях.','Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока отношение нашего ордена к тебе не изменится, ты сможешь купить оплечья у любого интенданта Серебряного Рассвета.$B$BЗа Рассвет, $Gбрат:сестра; $Gмой:моя;!','А, $Gблагородный:благородная; $C! Ты $Gпринес:принесла; мне знаки доблести? Как только ты передашь мне все десять, я предложу на выбор наши оплечья.','Вернитесь к интенданту Хасне из ордена Серебряного Рассвета в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оплечья Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе причитается награда за верную службу Серебряному Рассвету, $n. Тебе удалось завоевать всеобщее почтение. Мне поручено передать – ты можешь купить один из самых наших ценных предметов – оплечье защиты от магии.$b$bЕсли прикрепить его к доспехам, твое сопротивление силам одного из направлений магии возрастет. За это оплечье я попрошу от тебя не менее 10 знаков доблести Серебряного Рассвета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 знаков доблести Серебряного Рассвета интенданту Хасане в Бастион, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока отношение нашего ордена к тебе не изменится, ты сможешь купить оплечья у любого интенданта Серебряного Рассвета.$B$BЗа Рассвет, $Gбрат:сестра; $Gмой:моя;!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, $Gблагородный:благородная; $C! Ты $Gпринес:принесла; мне знаки доблести? Как только ты передашь мне все десять, я предложу на выбор наши оплечья.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Хасне из ордена Серебряного Рассвета в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (5505,'Ключ от Некроситета','Ну, вот, готово, $N – это ключ от Некроситета. Я не сомеваюсь, что он позволит тебе проникнуть в пределы школы. Впрочем, есть лишь один способ узнать наверняка. И не теряй времени даром.$B$BУдачи тебе, герой. Да рассеют твои победы мрак!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключ от Некроситета',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, вот, готово, $N – это ключ от Некроситета. Я не сомеваюсь, что он позволит тебе проникнуть в пределы школы. Впрочем, есть лишь один способ узнать наверняка. И не теряй времени даром.$B$BУдачи тебе, герой. Да рассеют твои победы мрак!',`requestitemstext_loc8`);
