INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5513,'Оплечья Рассвета','Тебе причитается награда за верную службу Серебряному Рассвету, $n. Тебе удалось завоевать всеобщее почтение. Мне поручено передать – ты можешь купить один из самых ценных наших предметов – оплечье защиты от магии.$b$bЕсли прикрепить его к доспехам, твое сопротивление силам одного из пяти направлений магии возрастет. За это оплечье я попрошу от тебя не менее 10 знаков доблести Серебряного Рассвета.','Принесите 10 знаков доблести Серебряного Рассвета интенданту Бричлок в Часовню Последней Надежды в Восточные Чумные земли.','Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока отношение нашего ордена к тебе не изменится, ты сможешь купить оплечья у любого интенданта Серебряного Рассвета.\n\nЗа Рассвет, брат мой!','А, благородный $C)! Ты принес мне знаки доблести? Как только ты передашь мне все десять, я предложу на выбор наши оплечья.','Вернитесь к интенданту Миранде Бричлок в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оплечья Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе причитается награда за верную службу Серебряному Рассвету, $n. Тебе удалось завоевать всеобщее почтение. Мне поручено передать – ты можешь купить один из самых ценных наших предметов – оплечье защиты от магии.$b$bЕсли прикрепить его к доспехам, твое сопротивление силам одного из пяти направлений магии возрастет. За это оплечье я попрошу от тебя не менее 10 знаков доблести Серебряного Рассвета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 знаков доблести Серебряного Рассвета интенданту Бричлок в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поразительно – не зря всех восхищает твоя преданность Серебряному Рассвету. Теперь я с радостью предлагаю на выбор наши оплечья. Пока отношение нашего ордена к тебе не изменится, ты сможешь купить оплечья у любого интенданта Серебряного Рассвета.\n\nЗа Рассвет, брат мой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, благородный $C)! Ты принес мне знаки доблести? Как только ты передашь мне все десять, я предложу на выбор наши оплечья.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Миранде Бричлок в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5514,'Форма денег стоит','Тебе нужно поговорить с гоблином по имени Кринкель Сталлер. Он работает в Прибамбасске, в пустыне Танарис. Ему под силу сделать такую форму, но это обойдется недешево. Мы просим тебя не скупиться и заплатить ему.$b$bЯ алхимик, а не банкир. Будь у меня золото, я бы здесь не сидел.$B$bНу вот, опять я брякнул что-то не то. Ладно.$b$bТебя ждет Прибамбасск! Удачи!','Отнесите Кринкелю Сталлеру из Прибамбасска прочные фрагменты скелета и 15 золотых монет.','Дитерс сказал, что ты выполняешь обязательства... и ты это $Gсделал:сделала;. Сделка есть сделка. Я вставлю фрагменты прямо при тебе…$B$BДитерс уже обработал их? Хорошо, это сбережет тебе время так как мне не придется посылать тебя обратно в Бастион.','Да, я знаю, кто ты и зачем $Gпришел:пришла;. Дитерс послал мне весточку. Сразу перейдем к делу?$B$BУ меня есть форма, в которой можно изготовить нужный тебе ключ, но она обойдется недешево – 15 золотых. Деньги вперед и не пытайся торговаться. Я сложу в форму фрагменты скелетов и покажу, как можно отлить его, не зная ничего о кузнечном деле... и все это бесплатно.$B$BПусть не говорят, что наемники за копейку удавятся!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Форма денег стоит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно поговорить с гоблином по имени Кринкель Сталлер. Он работает в Прибамбасске, в пустыне Танарис. Ему под силу сделать такую форму, но это обойдется недешево. Мы просим тебя не скупиться и заплатить ему.$b$bЯ алхимик, а не банкир. Будь у меня золото, я бы здесь не сидел.$B$bНу вот, опять я брякнул что-то не то. Ладно.$b$bТебя ждет Прибамбасск! Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Кринкелю Сталлеру из Прибамбасска прочные фрагменты скелета и 15 золотых монет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дитерс сказал, что ты выполняешь обязательства... и ты это $Gсделал:сделала;. Сделка есть сделка. Я вставлю фрагменты прямо при тебе…$B$BДитерс уже обработал их? Хорошо, это сбережет тебе время так как мне не придется посылать тебя обратно в Бастион.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, я знаю, кто ты и зачем $Gпришел:пришла;. Дитерс послал мне весточку. Сразу перейдем к делу?$B$BУ меня есть форма, в которой можно изготовить нужный тебе ключ, но она обойдется недешево – 15 золотых. Деньги вперед и не пытайся торговаться. Я сложу в форму фрагменты скелетов и покажу, как можно отлить его, не зная ничего о кузнечном деле... и все это бесплатно.$B$BПусть не говорят, что наемники за копейку удавятся!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5515,'Мешок ужасов Крастинова','Мы сбросили с себя тяжелое бремя, но твое задание все еще не исполнено. Повелитель Крастинова, Киртонос, все еще жив.$b$bВпрочем, прежде чем бросить ему вызов, необходимо придумать, как его вызвать.$b$bГоворят, что кровь невинных от Крастинова к Киртоносу переправляет Джандис Барова.$b$bНайди ее в затопленных коридорах Некроситета и убей. Принеси все улики, которые только найдешь.','Найдите в Некроситете Джандис Барову и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф.','Мешок ужасов!','Эва то появляется, то исчезает.','Вернитесь к Еве Саркофф на озеро Дарроумир, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мешок ужасов Крастинова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы сбросили с себя тяжелое бремя, но твое задание все еще не исполнено. Повелитель Крастинова, Киртонос, все еще жив.$b$bВпрочем, прежде чем бросить ему вызов, необходимо придумать, как его вызвать.$b$bГоворят, что кровь невинных от Крастинова к Киртоносу переправляет Джандис Барова.$b$bНайди ее в затопленных коридорах Некроситета и убей. Принеси все улики, которые только найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Некроситете Джандис Барову и уничтожьте ее. Заберите мешок ужасов Крастинова. Отнесите мешок Еве Саркофф.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мешок ужасов!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эва то появляется, то исчезает.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Еве Саркофф на озеро Дарроумир, что в Западных Чумных землях.',`completedtext_loc8`);
