INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5517,'Многоцветная мантия Рассвета','$gБрат:Сестра; $n – нет числа твоим деяниям во славу Серебряного Рассвета. В знак признательности я готова расстаться с одной из наших знаменитых многоцветных мантий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные мантии Рассвета предназначены лишь для наших величайших героев!$b$bПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.','Принесите 25 знаков доблести Серебряного Рассвета интенданту Бричлок в Часовню Последней Надежды в Восточные Чумные земли.','Что и говорить, твои подвиги весьма впечатляют, $N – прими же многоцветное оплечье Рассвета!$B$BПока в Серебряном Рассвете тебя превозносят, ты можешь покупать дополнительные многоцветные оплечья у любого из интендантов Рассвета.','Приветствую, $Gмогучий:могучая; $C! Вы принесли знаки доблести, о которых я просил? Как только вы передадите их мне, я дам вам вашу собственную Многоцветную драгоценность рассвета.','Вернитесь к интенданту Миранде Бричлок в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Многоцветная мантия Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gБрат:Сестра; $n – нет числа твоим деяниям во славу Серебряного Рассвета. В знак признательности я готова расстаться с одной из наших знаменитых многоцветных мантий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные мантии Рассвета предназначены лишь для наших величайших героев!$b$bПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 25 знаков доблести Серебряного Рассвета интенданту Бричлок в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что и говорить, твои подвиги весьма впечатляют, $N – прими же многоцветное оплечье Рассвета!$B$BПока в Серебряном Рассвете тебя превозносят, ты можешь покупать дополнительные многоцветные оплечья у любого из интендантов Рассвета.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $Gмогучий:могучая; $C! Вы принесли знаки доблести, о которых я просил? Как только вы передадите их мне, я дам вам вашу собственную Многоцветную драгоценность рассвета.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Миранде Бричлок в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5518,'Броня огров Гордока','Если вы собираетесь сразиться с королем этой помойки – а думаю, что без этого не обойтись, – тогда вам придется миновать капитана Давигрома. Конечно, можно его просто убить. Но возможно, вам стоит оставить его в живых.$b$bВы спросите – каким образом? Я сижу здесь уже довольно долго, и успел придумать, как можно изготовить личину огра, которая продержится достаточно долго, чтобы обмануть этих остолопов. Но, увы, больше чем на десять минут ее не хватит. Принесите мне все, что нужно, и я вам ее изготовлю. Торопиться-то мне все равно некуда...','Принесите 4 рулона рунической ткани, 8 кусков грубой кожи, 2 мотка рунной нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе Гордока в Забытом Городе.','Ага, ты $Gуложился:уложилась; в срок... и $Gдоставил:доставила; то, что надо. <Широкая ухмылка появляется на лице гоблина.> Секундочку…$B$BИмей в виду – у тебя есть только десять минут, пока костюм не развалится. Используй его вовремя.','Из всего, что мне нужно, пожалуй, труднее всего добыть огрскую дубильную кислоту. Может быть, наверху найдется? Мне самому туда не дойти, с этим ядром на цепи не больно-то побегаешь.$B$BВ общем, принесите мне все, что нужно, и я изготовлю вам огрскую личину, которая заставит капитана Давигрома принять вас за одного из своих.','Вернитесь к Уззлу Наперстяку в Забытый Город.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Броня огров Гордока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если вы собираетесь сразиться с королем этой помойки – а думаю, что без этого не обойтись, – тогда вам придется миновать капитана Давигрома. Конечно, можно его просто убить. Но возможно, вам стоит оставить его в живых.$b$bВы спросите – каким образом? Я сижу здесь уже довольно долго, и успел придумать, как можно изготовить личину огра, которая продержится достаточно долго, чтобы обмануть этих остолопов. Но, увы, больше чем на десять минут ее не хватит. Принесите мне все, что нужно, и я вам ее изготовлю. Торопиться-то мне все равно некуда...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 рулона рунической ткани, 8 кусков грубой кожи, 2 мотка рунной нити и огрскую дубильную кислоту Уззлу Наперстяку. Он прикован в секторе Гордока в Забытом Городе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, ты $Gуложился:уложилась; в срок... и $Gдоставил:доставила; то, что надо. <Широкая ухмылка появляется на лице гоблина.> Секундочку…$B$BИмей в виду – у тебя есть только десять минут, пока костюм не развалится. Используй его вовремя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Из всего, что мне нужно, пожалуй, труднее всего добыть огрскую дубильную кислоту. Может быть, наверху найдется? Мне самому туда не дойти, с этим ядром на цепи не больно-то побегаешь.$B$BВ общем, принесите мне все, что нужно, и я изготовлю вам огрскую личину, которая заставит капитана Давигрома принять вас за одного из своих.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уззлу Наперстяку в Забытый Город.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5519,'Броня огров Гордока','А вот тебе и штучка, $N. У тебя есть десять минут... Успеха! Если ты найдешь ключ, дай мне знать во что бы то ни стало!','Вам снова нужна личина, да? Ну, мне сейчас не к спеху – принесите мне то же, что и в прошлый раз, и я изготовлю вам еще одну огрскую личину.','Вернитесь к Уззлу Наперстяку в Забытый Город.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Броня огров Гордока',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А вот тебе и штучка, $N. У тебя есть десять минут... Успеха! Если ты найдешь ключ, дай мне знать во что бы то ни стало!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вам снова нужна личина, да? Ну, мне сейчас не к спеху – принесите мне то же, что и в прошлый раз, и я изготовлю вам еще одну огрскую личину.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уззлу Наперстяку в Забытый Город.',`completedtext_loc8`);
