INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5521,'Многоцветная мантия Рассвета','$gБрат:Сестра; $n – нет числа твоим деяниям во славу Серебряного Рассвета. В знак признательности я готова расстаться с одной из наших знаменитых многоцветных мантий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные мантии Рассвета предназначены лишь для наших величайших героев!$b$bПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.','Принесите 25 знаков доблести Серебряного Рассвета интенданту Искре Света из лагеря Промозглого Ветра.','Что и говорить, твои подвиги весьма впечатляют, $N – прими же многоцветное оплечье Рассвета!$B$BПока в Серебряном Рассвете тебя превозносят, ты можешь покупать дополнительные многоцветные оплечья у любого из интендантов Рассвета.','Приветствую, $Gмогучий:могучая; $C! Вы принесли знаки доблести, о которых я просил? Как только вы передадите их мне, я дам вам вашу собственную Многоцветную драгоценность рассвета.','Вернитесь к интенданту Искромету из ордена Серебряного Рассвета в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Многоцветная мантия Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gБрат:Сестра; $n – нет числа твоим деяниям во славу Серебряного Рассвета. В знак признательности я готова расстаться с одной из наших знаменитых многоцветных мантий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные мантии Рассвета предназначены лишь для наших величайших героев!$b$bПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 25 знаков доблести Серебряного Рассвета интенданту Искре Света из лагеря Промозглого Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что и говорить, твои подвиги весьма впечатляют, $N – прими же многоцветное оплечье Рассвета!$B$BПока в Серебряном Рассвете тебя превозносят, ты можешь покупать дополнительные многоцветные оплечья у любого из интендантов Рассвета.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $Gмогучий:могучая; $C! Вы принесли знаки доблести, о которых я просил? Как только вы передадите их мне, я дам вам вашу собственную Многоцветную драгоценность рассвета.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Искромету из ордена Серебряного Рассвета в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5522,'Леонид Барталомей','Я получила весть от своего господина Вектуса. На самом деле... не напрямую от него, но от некого Леонида Барталомея. Я не знаю его, однако он видел моего господина – а никто не может видеть моего господина, если он сам этого не пожелает.$B$BЛеонид сказал мне, что Вектусу необходимы драконьи яйца. Доставь их ему в Часовню Последней Надежды в Восточные Чумные земли.$B$BАй! За что? Разве Вектус не доверяет мне? Не обращай внимания, я не тебе. Просто доставь яйца куда следует и сообщи Леониду, что я сделала все, как было приказано.','Принесите охлажденные яйца Леониду Барталомею в Восточные Чумные земли.','А, очень хорошо. Ты не $Gзнал:знала;, что $Gработал:работала; на силы зла... но теперь я открою тебе правду. И боюсь, что я не служу этому хозяину. Я есть Леонид Барталомей, известный как "Чтимый" моему начальству в Серебряном Рассвете.$B$BЯ обманул Тинки, чтобы она послала тебя и посылку с драконьими яйцами ко мне. Моя уловка удалась, яйца не достигли назначения, и громадная мощь не попала в руки врага.','Ага, ты ведь $Gодин:одна; из тех, кто $Gустроил:устроила; заварушку в Пике Черной горы? $Gпринес:принесла; то, о чем я просил?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Леонид Барталомей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я получила весть от своего господина Вектуса. На самом деле... не напрямую от него, но от некого Леонида Барталомея. Я не знаю его, однако он видел моего господина – а никто не может видеть моего господина, если он сам этого не пожелает.$B$BЛеонид сказал мне, что Вектусу необходимы драконьи яйца. Доставь их ему в Часовню Последней Надежды в Восточные Чумные земли.$B$BАй! За что? Разве Вектус не доверяет мне? Не обращай внимания, я не тебе. Просто доставь яйца куда следует и сообщи Леониду, что я сделала все, как было приказано.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите охлажденные яйца Леониду Барталомею в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, очень хорошо. Ты не $Gзнал:знала;, что $Gработал:работала; на силы зла... но теперь я открою тебе правду. И боюсь, что я не служу этому хозяину. Я есть Леонид Барталомей, известный как "Чтимый" моему начальству в Серебряном Рассвете.$B$BЯ обманул Тинки, чтобы она послала тебя и посылку с драконьими яйцами ко мне. Моя уловка удалась, яйца не достигли назначения, и громадная мощь не попала в руки врага.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ага, ты ведь $Gодин:одна; из тех, кто $Gустроил:устроила; заварушку в Пике Черной горы? $Gпринес:принесла; то, о чем я просил?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5523,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5524,'Многоцветная мантия Рассвета','$gБрат:Сестра; $n – нет числа твоим деяниям во славу Серебряного Рассвета. В знак признательности я готова расстаться с одной из наших знаменитых многоцветных мантий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные мантии Рассвета предназначены лишь для наших величайших героев!$b$bПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.','Принесите 25 знаков доблести Серебряного Рассвета интенданту Хасане в Бастион, что в Западных Чумных землях.','Что и говорить, твои подвиги весьма впечатляют, $N – прими же многоцветное оплечье Рассвета!$B$BПока в Серебряном Рассвете тебя превозносят, ты можешь покупать дополнительные многоцветные оплечья у любого из интендантов Рассвета.','Приветствую, $Gмогучий:могучая; $C! Вы принесли знаки доблести, о которых я просил? Как только вы передадите их мне, я дам вам вашу собственную Многоцветную драгоценность рассвета.','Вернитесь к интенданту Хасне из ордена Серебряного Рассвета в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Многоцветная мантия Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gБрат:Сестра; $n – нет числа твоим деяниям во славу Серебряного Рассвета. В знак признательности я готова расстаться с одной из наших знаменитых многоцветных мантий Рассвета – тех самых, которые защищают от всех видов магии. Многоцветные мантии Рассвета предназначены лишь для наших величайших героев!$b$bПринеси мне двадцать пять знаков доблести, и получишь одно из лучших наших изделий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 25 знаков доблести Серебряного Рассвета интенданту Хасане в Бастион, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что и говорить, твои подвиги весьма впечатляют, $N – прими же многоцветное оплечье Рассвета!$B$BПока в Серебряном Рассвете тебя превозносят, ты можешь покупать дополнительные многоцветные оплечья у любого из интендантов Рассвета.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $Gмогучий:могучая; $C! Вы принесли знаки доблести, о которых я просил? Как только вы передадите их мне, я дам вам вашу собственную Многоцветную драгоценность рассвета.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Хасне из ордена Серебряного Рассвета в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5525,'Освободите Нотта!','Вы для меня – номер один во всем мире! Все остальные – после вас! Ох, большое вам спасибо, что освободили меня!$B$BЯ знал, я знал, что меня ждет более достойная участь, чем пойти на обед какому-нибудь огру!','Эта вещь называется ключ от оков Гордока – по крайней мере, так называют его эти остроумцы. Думаю, такой ключ может быть у любого из огров, но у кого именно – сказать не возьмусь. Есть вероятность, что такие ключи имеются у стражников...$B$BНо о чем я говорю? Он у вас есть, да? Он при вас?!','Вернитесь к Уззлу Наперстяку в Забытый Город.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освободите Нотта!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы для меня – номер один во всем мире! Все остальные – после вас! Ох, большое вам спасибо, что освободили меня!$B$BЯ знал, я знал, что меня ждет более достойная участь, чем пойти на обед какому-нибудь огру!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эта вещь называется ключ от оков Гордока – по крайней мере, так называют его эти остроумцы. Думаю, такой ключ может быть у любого из огров, но у кого именно – сказать не возьмусь. Есть вероятность, что такие ключи имеются у стражников...$B$BНо о чем я говорю? Он у вас есть, да? Он при вас?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уззлу Наперстяку в Забытый Город.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5526,'Осколки сквернита','Твои знания об Эльдре\'Таласе – Забытом Городе – в Фераласе теперь очень пригодятся, $n. Именно в восточной части этого разрушенного города властвует нечестивый Алззин Перевертень. Ступай же туда со всей поспешностью и посмотри в лицо ожидающей тебя опасности. $B$BПлод Изобилия, ныне оскверненный и ставший Сквернитом, должен находиться неподалеку от Алззина. Когда он упадет, собери столько субстанции Сквернита, сколько сможешь. Закрой его в реликварий и принеси мне.$B$BУдачи тебе, и быстроты Кенария.','Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Перевертня. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне.','Кончено, бравый $C, и теперь Круг Кенария в долгу перед тобой. Война, конечно, еще далека от завершения и битвы нам еще предстоят.$B$BПожалуйста, возьми это в знак нашей благодарности, $N. Спасибо тебе.','Имея в своем распоряжении запечатанный реликварий Чистоты, мы сможем не только устранить угрозу порчи, но и подойти к изучению этого проклятия со всей ответственностью. Возможно, мы даже сумеем разработать новые средства борьбы с порчей, что постоянно угрожает Азероту.$B$BЯ знаю, что Мили не согласилась бы ни на что иное...','Вернитесь к Рабину Сатурне в Ночную Гавань, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осколки сквернита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои знания об Эльдре\'Таласе – Забытом Городе – в Фераласе теперь очень пригодятся, $n. Именно в восточной части этого разрушенного города властвует нечестивый Алззин Перевертень. Ступай же туда со всей поспешностью и посмотри в лицо ожидающей тебя опасности. $B$BПлод Изобилия, ныне оскверненный и ставший Сквернитом, должен находиться неподалеку от Алззина. Когда он упадет, собери столько субстанции Сквернита, сколько сможешь. Закрой его в реликварий и принеси мне.$B$BУдачи тебе, и быстроты Кенария.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Сквернит в Забытом Городе и подберите его осколок. Есть шанс, что вам удастся его добыть, только убив Алззина Перевертня. Крепко заприте осколок в реликварии Чистоты, затем верните его Рабину Сатурне в Ночную Гавань в Лунной поляне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кончено, бравый $C, и теперь Круг Кенария в долгу перед тобой. Война, конечно, еще далека от завершения и битвы нам еще предстоят.$B$BПожалуйста, возьми это в знак нашей благодарности, $N. Спасибо тебе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Имея в своем распоряжении запечатанный реликварий Чистоты, мы сможем не только устранить угрозу порчи, но и подойти к изучению этого проклятия со всей ответственностью. Возможно, мы даже сумеем разработать новые средства борьбы с порчей, что постоянно угрожает Азероту.$B$BЯ знаю, что Мили не согласилась бы ни на что иное...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рабину Сатурне в Ночную Гавань, что на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5527,'Реликварий Чистоты','Первый шаг – найти вместилище, способное удержать чрезвычайно оскверненную субстанцию и оградить обладателя от ее влияния. Единственное известное мне приспособление, в котором, возможно держать такую дрянь, как Сквернит, – это реликварий Чистоты.$B$BВ сердце пустошей Силитуса находятся руины поселения Ночных эльфов, деревня Южного Ветра. Я знаю, что реликварий хранился там много лет назад. Если хочешь помочь нам достичь успеха, обыщи эти руины в надежде найти его.','Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне.','Вернитесь к Рабину Сатурне в Ночную Гавань, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликварий Чистоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первый шаг – найти вместилище, способное удержать чрезвычайно оскверненную субстанцию и оградить обладателя от ее влияния. Единственное известное мне приспособление, в котором, возможно держать такую дрянь, как Сквернит, – это реликварий Чистоты.$B$BВ сердце пустошей Силитуса находятся руины поселения Ночных эльфов, деревня Южного Ветра. Я знаю, что реликварий хранился там много лет назад. Если хочешь помочь нам достичь успеха, обыщи эти руины в надежде найти его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Силитус и найдите реликварий Чистоты в руинах деревни Южного Ветра. Если вам удастся его найти, возвращайтесь к Рабину Сатурне в Ночную Гавань в Лунной поляне.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рабину Сатурне в Ночную Гавань, что на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (5528,'Лучшее пойло Гордока','Ну, ты теперь у нас большая шишка, так попробуй задаром моего лучшего пойла! Оно и сил добавляет, и голову кружит! Пей, пей, начальник – попробуй, сам увидишь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучшее пойло Гордока',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, ты теперь у нас большая шишка, так попробуй задаром моего лучшего пойла! Оно и сил добавляет, и голову кружит! Пей, пей, начальник – попробуй, сам увидишь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5529,'Зачумленные детеныши дракона','До Серебряного Рассвета дошли слухи о том, что Плеть создает собственную армию драконов! Мы должны этому помешать – с помощью драконов Плеть сможет беспрепятственно перемещаться по всему Азероту!$B$BИх некроманты выращивают проклятых драконов в Некроситете, посреди озера Дарроумир.$B$BОтправляйся в Некроситет и убей как можно больше драконьих детенышей, пока они не успели вырасти и превратиться в неуязвимых монстров!','Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды.','$GМолодец:Умница;, $N! Пройдет много времени, прежде чем они смогут вырастить ещё одну группу драконов.$B$B...По крайней мере, я надеюсь на это!','Иди в Некроситет, $N. Достань зачумленных детенышей дракона, прежде чем они вырастут!','Вернитесь к Бетине Биггльцинк в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачумленные детеныши дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До Серебряного Рассвета дошли слухи о том, что Плеть создает собственную армию драконов! Мы должны этому помешать – с помощью драконов Плеть сможет беспрепятственно перемещаться по всему Азероту!$B$BИх некроманты выращивают проклятых драконов в Некроситете, посреди озера Дарроумир.$B$BОтправляйся в Некроситет и убей как можно больше драконьих детенышей, пока они не успели вырасти и превратиться в неуязвимых монстров!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 зачумленных детенышей дракона, затем возвращайтесь к Бетине Биггльцинк в Часовню Последней Надежды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N! Пройдет много времени, прежде чем они смогут вырастить ещё одну группу драконов.$B$B...По крайней мере, я надеюсь на это!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Иди в Некроситет, $N. Достань зачумленных детенышей дракона, прежде чем они вырастут!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бетине Биггльцинк в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5530,'Ожерелье Рассвета','Вернитесь к интенданту Миранде Бричлок в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье Рассвета',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Миранде Бричлок в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5531,'Бетина Биггльцинк','Яйца, которые ты $gпринес:принесла; мне, должны были быть использованы Плетью для создания чудовищных проклятых драконов. Охлажденные яйца черных драконов были бы бесценны для их опытов – это несомненно позволило бы Плети достичь своей подлой цели гораздо быстрее.$B$BОтнеси яйца Бетине Биггльцинк – она сведуща в науках и алхимии. Она обеспечила нас оружием против Плети. С твоей помощью мы нанесем этим тварям решающий удар.','Принесите охлажденные яйца Бетине Биггльцинк.','Вот они. И в такой красивой коробочке. Отличный размер!$B$BМы будем держать эти яйца в безопасном месте, пока не изучим их. А теперь задача для тебя.$B$BЯ сконструировала устройство, которое уничтожает ученых нежити в Некроситете. Они тоже изучают драконов в попытках создать зараженного дракона и мы должны остановить их изыскания!$B$BЯ называю это устройство Рассветный гамбит, потому что... я не знаю, честно говоря, что оно работает.$B$BНу что, попробуешь?','Приветствую тебя, $N. Что ты $Gпринес:принесла; мне, драконьи яйца? Посмотрим, посмотрим...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бетина Биггльцинк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яйца, которые ты $gпринес:принесла; мне, должны были быть использованы Плетью для создания чудовищных проклятых драконов. Охлажденные яйца черных драконов были бы бесценны для их опытов – это несомненно позволило бы Плети достичь своей подлой цели гораздо быстрее.$B$BОтнеси яйца Бетине Биггльцинк – она сведуща в науках и алхимии. Она обеспечила нас оружием против Плети. С твоей помощью мы нанесем этим тварям решающий удар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите охлажденные яйца Бетине Биггльцинк.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот они. И в такой красивой коробочке. Отличный размер!$B$BМы будем держать эти яйца в безопасном месте, пока не изучим их. А теперь задача для тебя.$B$BЯ сконструировала устройство, которое уничтожает ученых нежити в Некроситете. Они тоже изучают драконов в попытках создать зараженного дракона и мы должны остановить их изыскания!$B$BЯ называю это устройство Рассветный гамбит, потому что... я не знаю, честно говоря, что оно работает.$B$BНу что, попробуешь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя, $N. Что ты $Gпринес:принесла; мне, драконьи яйца? Посмотрим, посмотрим...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (5532,'Кольцо Рассвета','Вернитесь к интенданту Миранде Бричлок в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо Рассвета',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Миранде Бричлок в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5533,'Некроситет','На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью плети. В ее недрах наши враги спокойно проводят исследования и делаются все сильнее. Путь преграждают двери, и без подходящего ключа внутрь не войти.$B$BАлхимик Арбингтон многое знает о Некроситете и придумал, как достать ключ. Ты $gзарекомендовал:зарекомендовала; себя как человека с большими способностями, поэтому я доверяю тебе это задание. Обсуди подробности с алхимиком.','Поговорите с алхимиком Арбингтоном на берегу Промозглого Ветра, что в Западных Чумных землях.','Рад встрече, |3-6($C). В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ... который отомкнет входную дверь.$B$BПредставляю, какие кошмары таятся за ней, $n. Не понимаю, как герои вроде тебя решаются на такие подвиги...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Некроситет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На острове Каэр Дарроу располагается Некроситет – школа, которая одновременно служит цитаделью плети. В ее недрах наши враги спокойно проводят исследования и делаются все сильнее. Путь преграждают двери, и без подходящего ключа внутрь не войти.$B$BАлхимик Арбингтон многое знает о Некроситете и придумал, как достать ключ. Ты $gзарекомендовал:зарекомендовала; себя как человека с большими способностями, поэтому я доверяю тебе это задание. Обсуди подробности с алхимиком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с алхимиком Арбингтоном на берегу Промозглого Ветра, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад встрече, |3-6($C). В последнее время я посвятил большую часть времени изучению Некроситета, и, кажется, знаю способ, как добыть ключ... который отомкнет входную дверь.$B$BПредставляю, какие кошмары таятся за ней, $n. Не понимаю, как герои вроде тебя решаются на такие подвиги...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5534,'"Пропавшее"оборудование Ким\'джаеля','Что?! Ты в своем уме?! Чем ты еще $gнедоволен:недовольна;?! $B$BТы хоть представляешь, сколько стоят эти гранаты? За них дают... ладно, не важно... Хочешь денег? Хорошо. Прежде докажи мне, что ты $gценный работник:ценная работница;.$B$BОтправляйся в руины Эльдарата и принеси мне некую руну, которую искали эльфы крови. Полагаю, она у наг.','Найдите некую руну, которую хранят наги в руинах Эльдарата и принесите ее Ким\'джаелю в Азшару.','Хаха! Чудесно!$B$BЯ был уверен, что ты найдешь это и Волхв Римтори – это та корова, что наняла меня – уже роет копытами землю, так хочет эти руны. Ха! Я сделал вас, вонючие эльфы крови! Ким‘джаель! Ха! Я покажу вам кто тут крыса!$B$BХорошо $Gпоработал;поработала;, $N. $GМолодец:Умница;. А теперь я позолочу тебе ручку. $GМолодец:Умница;!','Ну, $N? Где моя руна? Ты же хочешь денег? Так вот сначала поработай!$B$BНе то не получишь уговоренную сумму. Что, мы ни о чем не договаривались? А, ну прекрасно. Тогда советую поторопиться, а не то получишь сильно меньше, чем ожидаешь.','Вернитесь к Ким\'джаелю в Талассийское поселение, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Пропавшее"оборудование Ким\'джаеля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что?! Ты в своем уме?! Чем ты еще $gнедоволен:недовольна;?! $B$BТы хоть представляешь, сколько стоят эти гранаты? За них дают... ладно, не важно... Хочешь денег? Хорошо. Прежде докажи мне, что ты $gценный работник:ценная работница;.$B$BОтправляйся в руины Эльдарата и принеси мне некую руну, которую искали эльфы крови. Полагаю, она у наг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите некую руну, которую хранят наги в руинах Эльдарата и принесите ее Ким\'джаелю в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хаха! Чудесно!$B$BЯ был уверен, что ты найдешь это и Волхв Римтори – это та корова, что наняла меня – уже роет копытами землю, так хочет эти руны. Ха! Я сделал вас, вонючие эльфы крови! Ким‘джаель! Ха! Я покажу вам кто тут крыса!$B$BХорошо $Gпоработал;поработала;, $N. $GМолодец:Умница;. А теперь я позолочу тебе ручку. $GМолодец:Умница;!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, $N? Где моя руна? Ты же хочешь денег? Так вот сначала поработай!$B$BНе то не получишь уговоренную сумму. Что, мы ни о чем не договаривались? А, ну прекрасно. Тогда советую поторопиться, а не то получишь сильно меньше, чем ожидаешь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ким\'джаелю в Талассийское поселение, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5535,'Беспокойные духи','Давным-давно высокорожденные были самыми могущественными адептами тайной магии, когда либо существовавшими среди ночных эльфов. Порча, которая охватывает каждого, кто имеет дело с тайной магией, принесла много горя народу ночных эльфов и всему Азероту. $B$BЯ обещал Часовым, что буду освобождать встреченных мной духов от их смертных связей. Если поможешь мне в этом, я награжу тебя. $B$BДухи скитаются в святилище Песни Теней к северо-востоку отсюда.','Уничтожьте по 6 теней высокорожденных обоих полов и возвращайтесь к Ло\'хату в Азшару.','Вернитесь к Ло\'хату к реке Строптивой, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беспокойные духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно высокорожденные были самыми могущественными адептами тайной магии, когда либо существовавшими среди ночных эльфов. Порча, которая охватывает каждого, кто имеет дело с тайной магией, принесла много горя народу ночных эльфов и всему Азероту. $B$BЯ обещал Часовым, что буду освобождать встреченных мной духов от их смертных связей. Если поможешь мне в этом, я награжу тебя. $B$BДухи скитаются в святилище Песни Теней к северо-востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте по 6 теней высокорожденных обоих полов и возвращайтесь к Ло\'хату в Азшару.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ло\'хату к реке Строптивой, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5536,'Земли, полные ненависти','Сатиры, искаженные и зловредные порождения ночных эльфов, ныне оскверняют священные земли, по которым некогда ступал Кенарий. Конечно, не в моих силах помочь эльфам справиться со всеми этими отвратительными созданиями, однако я поклялся Матери-Земле помочь эльфам избавиться от сатиров хотя бы здесь. $B$BНадеюсь, ты поможешь мне в этом деле. $B$BК северо-востоку отсюда ты найдешь клан Халдарр. Возвращайся ко мне, когда испытаешь свою силу.','Уничтожьте 6 сатиров, 2 плутов Халдарра и 2 скверноподданных из племени Халдарр и возвращайтесь к Ло\'хату к границе Ясеневого леса.','Вернитесь к Ло\'хату к реке Строптивой, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Земли, полные ненависти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сатиры, искаженные и зловредные порождения ночных эльфов, ныне оскверняют священные земли, по которым некогда ступал Кенарий. Конечно, не в моих силах помочь эльфам справиться со всеми этими отвратительными созданиями, однако я поклялся Матери-Земле помочь эльфам избавиться от сатиров хотя бы здесь. $B$BНадеюсь, ты поможешь мне в этом деле. $B$BК северо-востоку отсюда ты найдешь клан Халдарр. Возвращайся ко мне, когда испытаешь свою силу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 6 сатиров, 2 плутов Халдарра и 2 скверноподданных из племени Халдарр и возвращайтесь к Ло\'хату к границе Ясеневого леса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ло\'хату к реке Строптивой, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5537,'Фрагменты скелетов','Чтобы отомкнуть двери Некроситета необходим Костяной ключ. Его делают из остатков скелета – точнее, нескольких скелетов – и вплавляют в прочнейший из металлов в подходящей форме. Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой.$b$bНо не будем отвлекаться, для начала нам понадобятся фрагменты скелетов. Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи.','Принесите 15 фрагментов скелетов алхимику Арбингтону в Берег Промозглого Ветра в Западных Чумных землях.','Отличные образцы! Теперь моя очередь – я закалю их особым образом, чтобы они смогли вынести процесс отковки, через который им придется рано или поздно пройти.$B$BТеперь придется отыскать подходящую форму для отливки. Я знаю одного гоблина-кузнеца из Танариса, который в прошлом делал формы для не менее жутких вещей. Его девиз – как у всех гоблинов – кто платит, тот и музыку заказывает.','Как бы гнусно это ни звучало, для создания ключа нам нужен солидный запас фрагментов скелетов. Недаром его назвали Костяным ключом','Вернитесь к алхимику Арбингтону в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фрагменты скелетов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы отомкнуть двери Некроситета необходим Костяной ключ. Его делают из остатков скелета – точнее, нескольких скелетов – и вплавляют в прочнейший из металлов в подходящей форме. Чтобы ключ заработал, необходим перстень власти одного из тех существ, что могут открыть портал данной им силой.$b$bНо не будем отвлекаться, для начала нам понадобятся фрагменты скелетов. Для этой цели подойдут скелеты внутри Андорала, да и те, что снаружи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 15 фрагментов скелетов алхимику Арбингтону в Берег Промозглого Ветра в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные образцы! Теперь моя очередь – я закалю их особым образом, чтобы они смогли вынести процесс отковки, через который им придется рано или поздно пройти.$B$BТеперь придется отыскать подходящую форму для отливки. Я знаю одного гоблина-кузнеца из Танариса, который в прошлом делал формы для не менее жутких вещей. Его девиз – как у всех гоблинов – кто платит, тот и музыку заказывает.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как бы гнусно это ни звучало, для создания ключа нам нужен солидный запас фрагментов скелетов. Недаром его назвали Костяным ключом',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алхимику Арбингтону в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5538,'Форма денег стоит','Тебе нужно поговорить с гоблином по имени Кринкель Сталлер. Он работает в Прибамбасске, в пустыне Танарис. Ему под силу сделать такую форму, но это обойдется недешево. Мы просим тебя не скупиться и заплатить ему.$b$bЯ алхимик, а не банкир. Будь у меня золото, я бы здесь не сидел.$B$bНу вот, опять я брякнул что-то не то. Ладно.$b$bТебя ждет Прибамбасск! Удачи!','Отнесите Кринкелю Сталлеру из Прибамбасска прочные фрагменты скелета и 15 золотых монет.','Арбингтон сказал, что ты принесешь все необходимое, и так оно и оказалось! Сделка есть сделка. Дай-ка я сложу фрагменты скелетов в форму.$B$BАрбингтон их заранее закалил? Великолепно... В противном случае тебе пришлось бы тащиться обратно на Берег Промозглого Ветра.','Да, я знаю, кто ты и зачем пришел. Арбингтон послал мне весточку. Сразу перейдем к делу?$B$BУ меня есть форма, в которой можно изготовить нужный тебе ключ, но она обойдется недешево – 15 золотых. Деньги вперед и не пытайся торговаться. Я сложу в форму фрагменты скелетов и покажу, как можно отлить его, не зная ничего о кузнечном деле... и все это бесплатно.$B$BПусть не говорят, что наемники за копейку удавятся!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Форма денег стоит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно поговорить с гоблином по имени Кринкель Сталлер. Он работает в Прибамбасске, в пустыне Танарис. Ему под силу сделать такую форму, но это обойдется недешево. Мы просим тебя не скупиться и заплатить ему.$b$bЯ алхимик, а не банкир. Будь у меня золото, я бы здесь не сидел.$B$bНу вот, опять я брякнул что-то не то. Ладно.$b$bТебя ждет Прибамбасск! Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Кринкелю Сталлеру из Прибамбасска прочные фрагменты скелета и 15 золотых монет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Арбингтон сказал, что ты принесешь все необходимое, и так оно и оказалось! Сделка есть сделка. Дай-ка я сложу фрагменты скелетов в форму.$B$BАрбингтон их заранее закалил? Великолепно... В противном случае тебе пришлось бы тащиться обратно на Берег Промозглого Ветра.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, я знаю, кто ты и зачем пришел. Арбингтон послал мне весточку. Сразу перейдем к делу?$B$BУ меня есть форма, в которой можно изготовить нужный тебе ключ, но она обойдется недешево – 15 золотых. Деньги вперед и не пытайся торговаться. Я сложу в форму фрагменты скелетов и покажу, как можно отлить его, не зная ничего о кузнечном деле... и все это бесплатно.$B$BПусть не говорят, что наемники за копейку удавятся!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5541,'Боеприпасы для Громострела','Хегнар Громострел продает ружья у дороги в Старую Наковальню. Стрелки и пушкари много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны.$B$BНо... Последний ящик с боеприпасами, что я ему послал, пропал по дороге. Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, там на него напали вендиго... и этот дурак бросил боеприпасы для Громострела!$B$B$n, $Gне мог бы ты:не могла бы ты; найти их и вернуть Громострелу? Он их ждет, и наверняка у него боеприпасы уже на исходе.','Доставьте боеприпасы Хегнару Громострелу в Дун Мороге.','Надеюсь, ты не за боеприпасами $gпришел:пришла;, потому как они у меня почти закончились!','Вернитесь к Хегнару Громострелу в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боеприпасы для Громострела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хегнар Громострел продает ружья у дороги в Старую Наковальню. Стрелки и пушкари много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны.$B$BНо... Последний ящик с боеприпасами, что я ему послал, пропал по дороге. Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, там на него напали вендиго... и этот дурак бросил боеприпасы для Громострела!$B$B$n, $Gне мог бы ты:не могла бы ты; найти их и вернуть Громострелу? Он их ждет, и наверняка у него боеприпасы уже на исходе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте боеприпасы Хегнару Громострелу в Дун Мороге.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты не за боеприпасами $gпришел:пришла;, потому как они у меня почти закончились!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хегнару Громострелу в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5542,'Псы-демоны','Если ты собираешься здесь оставаться, придется тебе поработать в уплату за проживание. У нас есть ряд докучающих обстоятельств, с которыми неплохо бы разобраться.$b$bНачни с чумных псов и их отродий.$b$bЯ не многим смогу тебе отплатить, но горячую пищу и приятную беседу гарантирую.','Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу.','Хорошо сработано, $N. Заходи. Отдохни. Давай поедим и поговорим о давно минувших днях!','Не жалей собак-демонов, $R. Они мерзости!','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Псы-демоны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты собираешься здесь оставаться, придется тебе поработать в уплату за проживание. У нас есть ряд докучающих обстоятельств, с которыми неплохо бы разобраться.$b$bНачни с чумных псов и их отродий.$b$bЯ не многим смогу тебе отплатить, но горячую пищу и приятную беседу гарантирую.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 карликовых чумных псов, 5 чумных псов и 5 бесноватых чумных псов. По выполнении задания вернитесь к Тириону Фордрингу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо сработано, $N. Заходи. Отдохни. Давай поедим и поговорим о давно минувших днях!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не жалей собак-демонов, $R. Они мерзости!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5543,'Окровавленные небеса','Горе тем, кто в глупости своей бродит по Чумным землям. В здешних лесах таится много опасностей – от Алого ордена, который убивает всех, кроме своих сторонников, до Плети, которая всегда рада пополнить свои ряды новой нежитью.$b$bДаже звери и птицы превратились в отвратительных хищных чудовищ. Я прошу тебя уничтожить тех, что нападают с небес – чумных нетопырей.','Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу.','Ты сияющий пример достоинства, $R! Прошло много времени с тех пор, как я чувствовал, что кровь героев течет по моим венам. Твои подвиги вдохновляют!','Не недооценивай крылатых паразитов, $R. Чума дала им сверхъестественные способности.','Вернитесь к Тириону Фордрингу в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Окровавленные небеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Горе тем, кто в глупости своей бродит по Чумным землям. В здешних лесах таится много опасностей – от Алого ордена, который убивает всех, кроме своих сторонников, до Плети, которая всегда рада пополнить свои ряды новой нежитью.$b$bДаже звери и птицы превратились в отвратительных хищных чудовищ. Я прошу тебя уничтожить тех, что нападают с небес – чумных нетопырей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 чумных нетопырей и вернитесь к Тириону Фордрингу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сияющий пример достоинства, $R! Прошло много времени с тех пор, как я чувствовал, что кровь героев течет по моим венам. Твои подвиги вдохновляют!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не недооценивай крылатых паразитов, $R. Чума дала им сверхъестественные способности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тириону Фордрингу в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5544,'Мясо личинок-трупоедов','$R, у меня еда на исходе. Мне стыдно признаться, но угостить тебя нечем.$b$bНе поможешь старику? Единственные твари в этих краях, которых не поразила чума, это личинки-трупоеды. Они довольно гадкие, зато их мясо хранится много месяцев. Мне необходимо запасти несколько сотен фунтов на зиму!','Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите их мяса. Возвращайтесь к Тириону Фордрингу, когда насобираете 15 кусков мяса червей-трупоедов.','Да пребудет с тобою свет! Благословляю тебя!','Ты постепенно привыкнешь к вкусу, $R.','Вернитесь к Тириону Фордрингу в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мясо личинок-трупоедов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$R, у меня еда на исходе. Мне стыдно признаться, но угостить тебя нечем.$b$bНе поможешь старику? Единственные твари в этих краях, которых не поразила чума, это личинки-трупоеды. Они довольно гадкие, зато их мясо хранится много месяцев. Мне необходимо запасти несколько сотен фунтов на зиму!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите личинок-падальщиков и падальщиков-пожирателей. Убейте побольше и наберите их мяса. Возвращайтесь к Тириону Фордрингу, когда насобираете 15 кусков мяса червей-трупоедов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да пребудет с тобою свет! Благословляю тебя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты постепенно привыкнешь к вкусу, $R.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тириону Фордрингу в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5545,'Тридцать три несчастья','У меня большие неприятности. Приближается срок поставки древесины, а я не успеваю ее отправить. Самое обидное, что она уже заготовлена – но волки и медведи, расплодившиеся к северу отсюда, не дают моим работникам ее забрать.$B$BЯ уже договорилась с заместителем судьи Рейнером насчет зверья, но мне нужен кто-нибудь, кто доставит сюда эти дрова. Если ты принесешь мне восемь вязанок, я все успею.','Принесите 8 вязанок дров Раелен на Лесопилку Восточной долины.','Вернитесь к бригадиру Раелен на Лесопилку Восточной долины в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тридцать три несчастья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня большие неприятности. Приближается срок поставки древесины, а я не успеваю ее отправить. Самое обидное, что она уже заготовлена – но волки и медведи, расплодившиеся к северу отсюда, не дают моим работникам ее забрать.$B$BЯ уже договорилась с заместителем судьи Рейнером насчет зверья, но мне нужен кто-нибудь, кто доставит сюда эти дрова. Если ты принесешь мне восемь вязанок, я все успею.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 вязанок дров Раелен на Лесопилку Восточной долины.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадиру Раелен на Лесопилку Восточной долины в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5561,'Отлов кодо','Гоблин Биббли считает, что только он и умеет делать деньги в Пустошах. Ха! Единственный караван, который не боится идти через эти края, полностью зависит от меня. С тех пор как я научился омолаживать кодо и управлять старыми и умирающими зверями с помощью моего энергетического инкапсулятора, мы трое – я, караванщик Корк и Риггер – создали что-то вроде компании.$B$BВот, держи инкапсулятор: он действует на древних или старых кодо. Они сразу становятся ручными и следуют за тобой. А дальше все просто: приручишь кодо – веди его ко мне.','Приведите три прирученных кодо Смиду Заржавеню в лагерь Заржавня. Не забудьте вернуть ему энергетический инкапсулятор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отлов кодо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гоблин Биббли считает, что только он и умеет делать деньги в Пустошах. Ха! Единственный караван, который не боится идти через эти края, полностью зависит от меня. С тех пор как я научился омолаживать кодо и управлять старыми и умирающими зверями с помощью моего энергетического инкапсулятора, мы трое – я, караванщик Корк и Риггер – создали что-то вроде компании.$B$BВот, держи инкапсулятор: он действует на древних или старых кодо. Они сразу становятся ручными и следуют за тобой. А дальше все просто: приручишь кодо – веди его ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приведите три прирученных кодо Смиду Заржавеню в лагерь Заржавня. Не забудьте вернуть ему энергетический инкапсулятор.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5581,'Порталы Легиона','Вот тебе Рука Ируксоса.$B$BЯ самолично добыл ее у одного из вождей Пылающего Клинка.$B$BЕсли ты возьмешься закрыть порталы демонов на поле Маннорок – а именно об этом я и хочу тебя попросить, – она тебе пригодится.$B$BУгроза от демонов с каждым днем все серьезнее. Нужно закрыть порталы, чтобы прекратить их нашествие в наш мир.','Закройте 6 порталов на поле Маннорок и возвращайтесь к Фелгуру Бью-Двоих на Заставу Скитающихся Духов.','Твоими стараниями нам удалось сдержать натиск врага, |3-6($R).$B$BСпасибо.','Удалось ли тебе закрыть порталы демонов на Поле Маннорок?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порталы Легиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот тебе Рука Ируксоса.$B$BЯ самолично добыл ее у одного из вождей Пылающего Клинка.$B$BЕсли ты возьмешься закрыть порталы демонов на поле Маннорок – а именно об этом я и хочу тебя попросить, – она тебе пригодится.$B$BУгроза от демонов с каждым днем все серьезнее. Нужно закрыть порталы, чтобы прекратить их нашествие в наш мир.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Закройте 6 порталов на поле Маннорок и возвращайтесь к Фелгуру Бью-Двоих на Заставу Скитающихся Духов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоими стараниями нам удалось сдержать натиск врага, |3-6($R).$B$BСпасибо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе закрыть порталы демонов на Поле Маннорок?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5582,'Здоровая чешуя дракона','Это чешуйка была взята у пораженного проклятой чумой драконьего детеныша. Однако в отличие от других чешуек, изъязвленных и покрытых слизью, эта выглядит совершенно здоровой.$B$BЛюбопытное явление. Бетина Биггльцинк непременно захочет на это взглянуть.','Отнесите здоровую чешую дракона Бетине Биггльцинк в Часовню Последней Надежды в Восточные Чумные земли.','Превосходно! Это будет бесценным для продолжения моих исследований махинаций Плети. Спасибо, $N, если ты найдешь еще парочку чешуек, пожалуйста, принеси их мне!','$N, у тебя что-то есть для меня?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Здоровая чешуя дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это чешуйка была взята у пораженного проклятой чумой драконьего детеныша. Однако в отличие от других чешуек, изъязвленных и покрытых слизью, эта выглядит совершенно здоровой.$B$BЛюбопытное явление. Бетина Биггльцинк непременно захочет на это взглянуть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите здоровую чешую дракона Бетине Биггльцинк в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Это будет бесценным для продолжения моих исследований махинаций Плети. Спасибо, $N, если ты найдешь еще парочку чешуек, пожалуйста, принеси их мне!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, у тебя что-то есть для меня?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5601,'Сестренка Памела','Во время войны я бежала в Лордерон – мне посчастливилось спастись до того, как полчища Плети прошли по моим родным местам и превратили их в зачумленные руины. Мне повезло, но судьба была не столь благосклонна к моей семье. Боюсь, все они погибли во время битвы при Дарроушире.$B$BДеревня Дарроушир была частью Восточных королевств, теперь это еще одни развалины в южных пределах Восточных Чумных земель. Не $gмог:могла; бы ты узнать, что сталось с моей семьей? Я так волнуюсь за них, особенно за мою сестренку Памелу.$B$BПожалуйста, отыщи ее!','Найдите Памелу Редпат в Дарроушире.','Где моя сестра Джессика? Она покинула меня так давно, когда я была ещё совсем маленькой девочкой. Она так плакала, когда уходила... Не знаю, почему, может, разбила коленку?$B$BРаньше мы с Джессикой вместе играли, и танцевали, и собирали цветы... А иногда мы прятались за дверью и ждали, когда отец придет домой, чтобы выскочить и напугать его. Я хочу, чтобы она вернулась!$B$BМожет, если вернется она, то вернется и папа, и остальные, и мы снова будем вместе играть...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сестренка Памела',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время войны я бежала в Лордерон – мне посчастливилось спастись до того, как полчища Плети прошли по моим родным местам и превратили их в зачумленные руины. Мне повезло, но судьба была не столь благосклонна к моей семье. Боюсь, все они погибли во время битвы при Дарроушире.$B$BДеревня Дарроушир была частью Восточных королевств, теперь это еще одни развалины в южных пределах Восточных Чумных земель. Не $gмог:могла; бы ты узнать, что сталось с моей семьей? Я так волнуюсь за них, особенно за мою сестренку Памелу.$B$BПожалуйста, отыщи ее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Памелу Редпат в Дарроушире.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Где моя сестра Джессика? Она покинула меня так давно, когда я была ещё совсем маленькой девочкой. Она так плакала, когда уходила... Не знаю, почему, может, разбила коленку?$B$BРаньше мы с Джессикой вместе играли, и танцевали, и собирали цветы... А иногда мы прятались за дверью и ждали, когда отец придет домой, чтобы выскочить и напугать его. Я хочу, чтобы она вернулась!$B$BМожет, если вернется она, то вернется и папа, и остальные, и мы снова будем вместе играть...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5621,'Облачение Луны','Мне нужна твоя помощь, $n. Я должна оставаться здесь, чтобы обучать других, но ты $Gмог бы:могла бы; помочь одной из наших раненых часовых к югу от Доланаара. Ее ранили, когда она патрулировала город, и ей нужна наша помощь. Ее зовут Шайя.$B$BКогда найдешь ее, исцели ее раны и укрепи ее тело заклятиями. По крайней мере, это защитит ее от бед на некоторое время. Когда выполнишь свой долг перед Элуной, возвращайся ко мне.','Найдите стража Шайю и исцелите ее раны при помощи малого исцеления (ранг 2). Потом скажите ей Слово силы: "Стойкость". Затем вернитесь к Лорне Утреннему Свету в Доланаар.','Ты хорошо $Gпослужил:послужила; Элуне. Я благодарю тебя за это.$B$BПожалуйста, прими это одеяние, как символ моей благодарности. Оно символизирует то, что ты $Gзаслужил:заслужила; свое место в наших кругах. Если желаешь, носи его с гордостью, но мы признаем тебя своим в любом обличии.$B$BСпасибо, $N, и да благословит тебя великая Элуна.','Наши заклинания Укрепления очень сильны, $N. Они позволяют нашим товарищам получать дальнейшие травмы от всех типов атак и выживать в ситуациях, когда они обычно падают. Но это ничто по сравнению с нашими способностями к лечению.','Вернитесь к Лорне Утреннему Свету на озеро Аль\'Амет, что в Тельдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Облачение Луны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужна твоя помощь, $n. Я должна оставаться здесь, чтобы обучать других, но ты $Gмог бы:могла бы; помочь одной из наших раненых часовых к югу от Доланаара. Ее ранили, когда она патрулировала город, и ей нужна наша помощь. Ее зовут Шайя.$B$BКогда найдешь ее, исцели ее раны и укрепи ее тело заклятиями. По крайней мере, это защитит ее от бед на некоторое время. Когда выполнишь свой долг перед Элуной, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите стража Шайю и исцелите ее раны при помощи малого исцеления (ранг 2). Потом скажите ей Слово силы: "Стойкость". Затем вернитесь к Лорне Утреннему Свету в Доланаар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хорошо $Gпослужил:послужила; Элуне. Я благодарю тебя за это.$B$BПожалуйста, прими это одеяние, как символ моей благодарности. Оно символизирует то, что ты $Gзаслужил:заслужила; свое место в наших кругах. Если желаешь, носи его с гордостью, но мы признаем тебя своим в любом обличии.$B$BСпасибо, $N, и да благословит тебя великая Элуна.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наши заклинания Укрепления очень сильны, $N. Они позволяют нашим товарищам получать дальнейшие травмы от всех типов атак и выживать в ситуациях, когда они обычно падают. Но это ничто по сравнению с нашими способностями к лечению.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лорне Утреннему Свету на озеро Аль\'Амет, что в Тельдрассиле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5622,'Во имя Элуны','$n, тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине. Там ты разыщешь Лорну Утренний Свет. Она расскажет тебе больше о пути Элуны, и с ее помощью ты получишь свое первое облачение, говорящее о твоем статусе $gжреца:жрицы; Элуны.$B$BБудь $Gосторожен:осторожна;, и да хранит тебя в пути Элуна!','Поговорите в Тельдрассиле с Лорной Утренний Свет.','Я рада знать, что Шанда послала тебя найти меня, $N. Обучение молодых жрецов, следующих пути Луны приносит мне большое удовольствие.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во имя Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине. Там ты разыщешь Лорну Утренний Свет. Она расскажет тебе больше о пути Элуны, и с ее помощью ты получишь свое первое облачение, говорящее о твоем статусе $gжреца:жрицы; Элуны.$B$BБудь $Gосторожен:осторожна;, и да хранит тебя в пути Элуна!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Тельдрассиле с Лорной Утренний Свет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рада знать, что Шанда послала тебя найти меня, $N. Обучение молодых жрецов, следующих пути Луны приносит мне большое удовольствие.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5623,'Во имя Света','Приветствую тебя, $gюный жрец:юная жрица;. Пришло время узнать больше о нашей вере. После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту. Знания ее велики; к тому же она уже слышала о тебе и о твоем стремлении к Истинному Свету. Она готова поделиться с тобой своей мудростью.','Поговорите с жрицей Жозеттой в Элвиннском лесу.','Я рада твоему прибытию, $N. У нас есть, что обсудить касательно твоего будущего и твоего пути по дороге Света.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во имя Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $gюный жрец:юная жрица;. Пришло время узнать больше о нашей вере. После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту. Знания ее велики; к тому же она уже слышала о тебе и о твоем стремлении к Истинному Свету. Она готова поделиться с тобой своей мудростью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с жрицей Жозеттой в Элвиннском лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рада твоему прибытию, $N. У нас есть, что обсудить касательно твоего будущего и твоего пути по дороге Света.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5624,'Облачение Света','Обычно я подвергаю всех последователей Света небольшому испытанию. Так я выясняю, достойны ли они своего первого облачения – символа того, что церковь их принимает и поддерживает.$B$BНо сейчас ситуация немного отличается. Один из жителей Златоземья видел раненого стража на берегу озера к востоку отсюда. Этого стража зовут Робертс. Найди его, исцели его раны, придай ему стойкости и вернись сюда. Если ты справишься, я сочту твое испытание завершенным.','Разыщите стражника Робертса и исцелите его раны при помощи быстрого исцеления.','Прекрасно, $N. Вылечив стражника ты тем самым $Gпомог:помогла; городу, сделав жизнь в нем безопаснее. Рад видеть что ты уже $Gизучил:изучила; кое-какие свои способности, и даже умеешь их использовать. Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несет нашу эмблему... и любой, кто взглянет на нее, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить ее – твое дело... Это не обязательно.','Как ты уже $Gпонял:поняла;, наша магия помогает людям выжить в эти непростые времена, особенно героям и искателям приключений, постоянно встречающимся с опасностью.$B$BВсегда помни насколько важны твои способности. И не забывай о стойкости, позволяющей твоим соратникам в битве выдержать большее число ударов.$B$BНе дай никому забыть насколько сильна наша магия.','Вернитесь к жрице Жозетте в Элвиннский лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Облачение Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обычно я подвергаю всех последователей Света небольшому испытанию. Так я выясняю, достойны ли они своего первого облачения – символа того, что церковь их принимает и поддерживает.$B$BНо сейчас ситуация немного отличается. Один из жителей Златоземья видел раненого стража на берегу озера к востоку отсюда. Этого стража зовут Робертс. Найди его, исцели его раны, придай ему стойкости и вернись сюда. Если ты справишься, я сочту твое испытание завершенным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите стражника Робертса и исцелите его раны при помощи быстрого исцеления.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, $N. Вылечив стражника ты тем самым $Gпомог:помогла; городу, сделав жизнь в нем безопаснее. Рад видеть что ты уже $Gизучил:изучила; кое-какие свои способности, и даже умеешь их использовать. Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несет нашу эмблему... и любой, кто взглянет на нее, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить ее – твое дело... Это не обязательно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как ты уже $Gпонял:поняла;, наша магия помогает людям выжить в эти непростые времена, особенно героям и искателям приключений, постоянно встречающимся с опасностью.$B$BВсегда помни насколько важны твои способности. И не забывай о стойкости, позволяющей твоим соратникам в битве выдержать большее число ударов.$B$BНе дай никому забыть насколько сильна наша магия.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Жозетте в Элвиннский лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5625,'Облачение Света','Как правило, примерно в эту пору $gпослушники:послушницы; вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе. Но, честно говоря, сейчас у меня есть и более важные дела. Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф.$B$BИзлечи Дольфа и наложи на него "Слово Силы: Стойкость", и я сочту, что ты $Gпрошел:прошла; испытание. Справишься?','Найдите горного пехотинца Дольфа и исцелите его раны при помощи Малого исцеления (ранг 2). Также наложите на него "Слово силы: Стойкость", а затем вернитесь к Максану Ковальне в Каранос.','Прекрасно, $N. Вылечив стражника ты тем самым $Gпомог:помогла; городу, сделав жизнь в нем безопаснее. Рад видеть что ты уже $Gизучил:изучила; кое-какие свои способности, и даже умеешь их использовать. Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несет нашу эмблему... и любой, кто взглянет на нее, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить ее – твое дело... Это не обязательно.','Ты $Gнашел:нашла; Дольфа, $N?$B$BКак ты уже $Gпонял:поняла;, наша способность исцелять, очень полезна. Мало того, что мы в состоянии позаботиться о раненых, но мы еще жизненно необходимы для выживания героев и искателей приключений, которые пытаются построить себе имя. Стойкость, позволяет твоим соратникам в битве выдержать большее число ударов.','Вернитесь к Максану Анволу на Мерцающий хребет, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Облачение Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как правило, примерно в эту пору $gпослушники:послушницы; вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе. Но, честно говоря, сейчас у меня есть и более важные дела. Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф.$B$BИзлечи Дольфа и наложи на него "Слово Силы: Стойкость", и я сочту, что ты $Gпрошел:прошла; испытание. Справишься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите горного пехотинца Дольфа и исцелите его раны при помощи Малого исцеления (ранг 2). Также наложите на него "Слово силы: Стойкость", а затем вернитесь к Максану Ковальне в Каранос.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, $N. Вылечив стражника ты тем самым $Gпомог:помогла; городу, сделав жизнь в нем безопаснее. Рад видеть что ты уже $Gизучил:изучила; кое-какие свои способности, и даже умеешь их использовать. Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несет нашу эмблему... и любой, кто взглянет на нее, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить ее – твое дело... Это не обязательно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; Дольфа, $N?$B$BКак ты уже $Gпонял:поняла;, наша способность исцелять, очень полезна. Мало того, что мы в состоянии позаботиться о раненых, но мы еще жизненно необходимы для выживания героев и искателей приключений, которые пытаются построить себе имя. Стойкость, позволяет твоим соратникам в битве выдержать большее число ударов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Максану Анволу на Мерцающий хребет, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5626,'Во имя Света','Эй! $n! У тебя есть свободная минутка?!$B$BТы давно уже следуешь пути Света, так ведь? Как насчет того, чтобы сходить к Максану Ковальне в Каранос? Он расскажет тебе побольше о твоей судьбе, а если ты окажешься $Gдостойным:достойной;, он тебе даст твои первые одеяния $gжреца:жрицы;.$B$BТеперь ступай! Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать.','Поговорите с Максаном Ковальней в Дун Мороге.','Тебя Брансток послал? Хорошо, хорошо. Ты $Gсделал:сделала; еще один шаг навстречу Свету. Но тебе многое еще надо усилить – силу тела... и силу воли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во имя Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй! $n! У тебя есть свободная минутка?!$B$BТы давно уже следуешь пути Света, так ведь? Как насчет того, чтобы сходить к Максану Ковальне в Каранос? Он расскажет тебе побольше о твоей судьбе, а если ты окажешься $Gдостойным:достойной;, он тебе даст твои первые одеяния $gжреца:жрицы;.$B$BТеперь ступай! Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Максаном Ковальней в Дун Мороге.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя Брансток послал? Хорошо, хорошо. Ты $Gсделал:сделала; еще один шаг навстречу Свету. Но тебе многое еще надо усилить – силу тела... и силу воли.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (5627,'Звезды Элуны','Ты $Gдоказал:доказала;, $N, что ты $Gдостоин:достойна; внимание Элуны. Как будешь $Gготов:готова;, дай знать. Я с радостью обучу тебя одному из ее заклинаний, которое уникально для нашего народа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звезды Элуны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gдоказал:доказала;, $N, что ты $Gдостоин:достойна; внимание Элуны. Как будешь $Gготов:готова;, дай знать. Я с радостью обучу тебя одному из ее заклинаний, которое уникально для нашего народа.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5628,'Возвращение домой','Если не ошибаюсь, $n? Рад, что ты $Gуделил:уделила; мне минутку внимания. Забраться так далеко от дома, да в такие юные годы, – мне по душе твое рвение! Если бы мне в молодые годы хватило духу постранствовать по миру...$B$BТут недавно тебя искала жрица из вашего ордена. Сказала, что тебе спешно надо вернуться в Храм Луны в Дарнасе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением. Я бы на твоем месте не тянул.','Поговорите в Дарнасе со жрицей Алатеей.','Хорошо, что ты $Gвернулся:вернулась; домой, $N. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твое путешествие!$B$BМожет быть, ты расскажешь мне что-нибудь о том, что ты $Gвидел:видела; после того, как мы закончим с делами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение домой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если не ошибаюсь, $n? Рад, что ты $Gуделил:уделила; мне минутку внимания. Забраться так далеко от дома, да в такие юные годы, – мне по душе твое рвение! Если бы мне в молодые годы хватило духу постранствовать по миру...$B$BТут недавно тебя искала жрица из вашего ордена. Сказала, что тебе спешно надо вернуться в Храм Луны в Дарнасе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением. Я бы на твоем месте не тянул.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты $Gвернулся:вернулась; домой, $N. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твое путешествие!$B$BМожет быть, ты расскажешь мне что-нибудь о том, что ты $Gвидел:видела; после того, как мы закончим с делами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5629,'Возвращение домой','Еще раз приветствую тебя, $n. Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени. Жрица Алатея прислала за тобой. Сдается, ты $Gпривлек:привлекла; внимание наших старейшин, и они считают, что ты $Gсозрел:созрела; для более великих дел. Отправляйся в дарнасский Храм Луны и найди там Алатею. Удачи тебе, и да хранит тебя Элуна.','Поговорите в Дарнасе со жрицей Алатеей.','Хорошо, что ты $Gвернулся:вернулась;, $N. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твое путешествие!$B$BМожет быть, ты расскажешь мне что-нибудь о том, что ты $Gвидел:видела; после того, как мы закончим с делами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение домой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще раз приветствую тебя, $n. Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени. Жрица Алатея прислала за тобой. Сдается, ты $Gпривлек:привлекла; внимание наших старейшин, и они считают, что ты $Gсозрел:созрела; для более великих дел. Отправляйся в дарнасский Храм Луны и найди там Алатею. Удачи тебе, и да хранит тебя Элуна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты $Gвернулся:вернулась;, $N. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твое путешествие!$B$BМожет быть, ты расскажешь мне что-нибудь о том, что ты $Gвидел:видела; после того, как мы закончим с делами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5630,'Возвращение домой','Ну здравствуй, $nдруг:подруга. Приятно видеть, что ты так далеко $Gзабрался:забралась;! Без обид, но многие из ваших не слишком хорошо переносят местные холода. Славно, что ты $Gслеплен:слеплена; из более крутого теста.$B$BНе так давно одна из ваших жриц искала тебя – говорила, чтобы ты $Gнашел:нашла; жрицу Алатею в Храме Луны в Дарнасе. Должно быть, это важно так что возвращайся туда как можно скорее.','Поговорите в Дарнасе со жрицей Алатеей.','Хорошо, что ты $Gвернулся:вернулась; домой, $N. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твое путешествие!$B$BМожет быть, ты расскажешь мне что-нибудь о том, что ты $Gвидел:видела; после того, как мы закончим с делами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение домой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну здравствуй, $nдруг:подруга. Приятно видеть, что ты так далеко $Gзабрался:забралась;! Без обид, но многие из ваших не слишком хорошо переносят местные холода. Славно, что ты $Gслеплен:слеплена; из более крутого теста.$B$BНе так давно одна из ваших жриц искала тебя – говорила, чтобы ты $Gнашел:нашла; жрицу Алатею в Храме Луны в Дарнасе. Должно быть, это важно так что возвращайся туда как можно скорее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты $Gвернулся:вернулась; домой, $N. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твое путешествие!$B$BМожет быть, ты расскажешь мне что-нибудь о том, что ты $Gвидел:видела; после того, как мы закончим с делами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5631,'Возвращение домой','Недавно в наших чертогах побывала одна жрица, и она искала вас, $Gюный:юная:r; |3-6($r). Она сказала, что ее послали за вами и что вы должны вернуться в Храм Луны в Дарнасе как можно скорее. По прибытии найдите жрицу – она расскажет вам больше.$B$BДа пребудет с вами Свет, $n.','Поговорите в Дарнасе со жрицей Алатеей.','Хорошо, что ты $Gвернулся:вернулась; домой, $N. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твое путешествие!$B$BМожет быть, ты расскажешь мне что-нибудь о том, что ты $Gвидел:видела; после того, как мы закончим с делами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение домой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно в наших чертогах побывала одна жрица, и она искала вас, $Gюный:юная:r; |3-6($r). Она сказала, что ее послали за вами и что вы должны вернуться в Храм Луны в Дарнасе как можно скорее. По прибытии найдите жрицу – она расскажет вам больше.$B$BДа пребудет с вами Свет, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты $Gвернулся:вернулась; домой, $N. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий. Надеюсь, Элуна благословила твое путешествие!$B$BМожет быть, ты расскажешь мне что-нибудь о том, что ты $Gвидел:видела; после того, как мы закончим с делами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5632,'Возвращение домой','Да-да, конечно. Здравствуй, $n. Недавно тут побывала посланница нашего ордена. Она искала тебя. Она мельком упомянула, что в Дарнасе случилось что-то важное и что тебе следует как можно скорее вернуться в Храм Луны. Сразу поговори там со жрицей Алатеей. Наверняка это касается твоих успехов.$B$BВ общем, возвращайся в Дарнас, как только сможешь.','Поговорите в Дарнасе со жрицей Алатеей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение домой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да-да, конечно. Здравствуй, $n. Недавно тут побывала посланница нашего ордена. Она искала тебя. Она мельком упомянула, что в Дарнасе случилось что-то важное и что тебе следует как можно скорее вернуться в Храм Луны. Сразу поговори там со жрицей Алатеей. Наверняка это касается твоих успехов.$B$BВ общем, возвращайся в Дарнас, как только сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5633,'Возвращение домой','Добро пожаловать, $gдруг:подруга;. Приятно видеть тебя в наших чертогах. Да пребудет благость с тобой и твоим народом.$B$BПока ты тут $Gстранствовал:странствовала; в наших краях, тебя разыскивала здесь жрица из вашего храма. Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны. Прости, большего не скажу, но мне показалось, что дело важное. Когда доберешься до Храма, поговори со жрицей Алатеей.','Поговорите в Дарнасе со жрицей Алатеей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение домой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать, $gдруг:подруга;. Приятно видеть тебя в наших чертогах. Да пребудет благость с тобой и твоим народом.$B$BПока ты тут $Gстранствовал:странствовала; в наших краях, тебя разыскивала здесь жрица из вашего храма. Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны. Прости, большего не скажу, но мне показалось, что дело важное. Когда доберешься до Храма, поговори со жрицей Алатеей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (5634,'Молитва отчаяния','Твои услуги, оказанные силам Света, неоценимы, а твои деяния – пример блистательной храбрости для всех, кто путешествует в землях, полных опасностей. Прошу, считай этот урок наградой за все, сделанное тобой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитва отчаяния',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои услуги, оказанные силам Света, неоценимы, а твои деяния – пример блистательной храбрости для всех, кто путешествует в землях, полных опасностей. Прошу, считай этот урок наградой за все, сделанное тобой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5635,'Молитва отчаяния','$n, тобой заинтересовались наши высшие иерархи. Они желают твоего скорейшего возвращения в Собор Света Штормграда. Вероятно, они считают, что для тебя наступило время нового обучения. Когда доберешься до собора, обратись прямо к верховной жрице Лорене, она расскажет тебе об остальном. Удачи! Да хранит тебя Свет!','Поговорите с Верховной жрицей Лореной в Штормграде.','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитва отчаяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, тобой заинтересовались наши высшие иерархи. Они желают твоего скорейшего возвращения в Собор Света Штормграда. Вероятно, они считают, что для тебя наступило время нового обучения. Когда доберешься до собора, обратись прямо к верховной жрице Лорене, она расскажет тебе об остальном. Удачи! Да хранит тебя Свет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5636,'Молитва отчаяния','Да благословит тебя Элуна, |3-6($r)! Надеюсь, что Свет не покидает тебя.$B$BТебя недавно разыскивал один из наших жрецов. Он просил передать тебе, что в Соборе Света Штормграда тебя ожидает Верховная жрица Лорена. Не трать времени даром, твой народ нуждается в тебе.','Поговорите с Верховной жрицей Лореной в Штормграде.','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитва отчаяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да благословит тебя Элуна, |3-6($r)! Надеюсь, что Свет не покидает тебя.$B$BТебя недавно разыскивал один из наших жрецов. Он просил передать тебе, что в Соборе Света Штормграда тебя ожидает Верховная жрица Лорена. Не трать времени даром, твой народ нуждается в тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5637,'Молитва отчаяния','$n, тебе пора отправляться в Штормград. Верховная жрица Лорена ожидает тебя в Соборе Света, она хочет поговорить с тобой. Должно случиться что-то особенное, если тобой заинтересовалась сама Верховная жрица. Не знаю, к добру это или к худу. Думаю, что так или иначе все это окажется полезным для тебя.$B$BНе трать много времени, собирайся быстрее.','Поговорите с Верховной жрицей Лореной в Штормграде.','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитва отчаяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, тебе пора отправляться в Штормград. Верховная жрица Лорена ожидает тебя в Соборе Света, она хочет поговорить с тобой. Должно случиться что-то особенное, если тобой заинтересовалась сама Верховная жрица. Не знаю, к добру это или к худу. Думаю, что так или иначе все это окажется полезным для тебя.$B$BНе трать много времени, собирайся быстрее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5638,'Молитва отчаяния','Эй, |3-6($r)! Тебя недавно искал один из ваших жрецов! Он просил тебе передать, что тебя очень ждут в Соборе Света. Еще сказал, что это очень важно, и мне кажется, что ему стоит верить. Он был настроен весьма благодушно, так что для тебя это хорошие новости. Тебе стоит поторопиться, чтобы не упустить этот шанс.$B$BДа хранит тебя Элуна, |3-6($r).','Поговорите с Верховной жрицей Лореной в Штормграде.','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитва отчаяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, |3-6($r)! Тебя недавно искал один из ваших жрецов! Он просил тебе передать, что тебя очень ждут в Соборе Света. Еще сказал, что это очень важно, и мне кажется, что ему стоит верить. Он был настроен весьма благодушно, так что для тебя это хорошие новости. Тебе стоит поторопиться, чтобы не упустить этот шанс.$B$BДа хранит тебя Элуна, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5639,'Молитва отчаяния','$n! Тебя ждут в Штормграде! Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки. Не мешкай. Ты найдешь Лорену в Соборе Света в центре города. Передай ей от меня привет и постарайся не завалить экзамен. Да хранит тебя Свет!','Поговорите с Верховной жрицей Лореной в Штормграде.','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитва отчаяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Тебя ждут в Штормграде! Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки. Не мешкай. Ты найдешь Лорену в Соборе Света в центре города. Передай ей от меня привет и постарайся не завалить экзамен. Да хранит тебя Свет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5640,'Молитва отчаяния','Благословенна будь Элуна, чей свет хранит тебя, $n!$B$BСейчас многие члены нашего ордена решили укрепить свои познания и веру в силу Элуны. Как я знаю, и в твоем ордене происходит то же самое.$B$BКогда закончишь свои дела в Дарнасе, отправляйся к вашей Верховной жрице, дабы получить новые знания.','Поговорите с Верховной жрицей Лореной в Штормграде.','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Молитва отчаяния',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благословенна будь Элуна, чей свет хранит тебя, $n!$B$BСейчас многие члены нашего ордена решили укрепить свои познания и веру в силу Элуны. Как я знаю, и в твоем ордене происходит то же самое.$B$BКогда закончишь свои дела в Дарнасе, отправляйся к вашей Верховной жрице, дабы получить новые знания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рада твоему прибытию, $N. Есть множество вещей, которые нам нужно обсудить, но самая важная – твое будущее обучение тайному знанию Света.$B$BЕсть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (5641,'Бесстрашие','У тебя есть великие задатки жреца, $N. Продолжай в этом же направлении!$B$BТы $Gдоказал:доказала;, что $Gготов:готова; к бою. Возможно, пришло время научить тебя чему-то большему, чем немного.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесстрашие',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя есть великие задатки жреца, $N. Продолжай в этом же направлении!$B$BТы $Gдоказал:доказала;, что $Gготов:готова; к бою. Возможно, пришло время научить тебя чему-то большему, чем немного.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5642,'Страж Тьмы','В Оргриммаре происходит нечто важное, $n.$b$bОбычно посланцы, которые приезжают сюда за троллями-жрецами, держатся с ленцой. А на этот раз они, похоже, спешили! Не засиживайся в Громовом Утесе. Думаю, тебе стоит как можно скорее вернуться на Аллею Духов.','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страж Тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Оргриммаре происходит нечто важное, $n.$b$bОбычно посланцы, которые приезжают сюда за троллями-жрецами, держатся с ленцой. А на этот раз они, похоже, спешили! Не засиживайся в Громовом Утесе. Думаю, тебе стоит как можно скорее вернуться на Аллею Духов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5643,'Страж Тьмы','Как и многие из наших жрецов, члены твоего племени проходят обряды инициации. Эти обряды часто наделяют жрецов особыми способностями, которые помогают им выжить. Я чувствую, что тебе пришло время пройти такой обряд. Возвращайся на Аллею Духов в Оргриммаре и поговори с Ур\'кьо. То, чему он тебя научит, может оказаться чрезвычайно важным в будущем.','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страж Тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как и многие из наших жрецов, члены твоего племени проходят обряды инициации. Эти обряды часто наделяют жрецов особыми способностями, которые помогают им выжить. Я чувствую, что тебе пришло время пройти такой обряд. Возвращайся на Аллею Духов в Оргриммаре и поговори с Ур\'кьо. То, чему он тебя научит, может оказаться чрезвычайно важным в будущем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5644,'Всепожирающая чума','Доброго тебе дня, $n. Вижу, ты многому $gнаучился:научилась;, и пришло время вернуться к Эльталисте. Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным.$b$bЯ не скажу, что тебя ждет – пусть для тебя это будет сюрпризом. Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила... Вот это были деньки.$b$bОтправляйся в Подгород, поговори с Эльталисте, $n. Она ждет тебя в Квартале Воинов.','Поговорите с Эльталисте в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всепожирающая чума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доброго тебе дня, $n. Вижу, ты многому $gнаучился:научилась;, и пришло время вернуться к Эльталисте. Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным.$b$bЯ не скажу, что тебя ждет – пусть для тебя это будет сюрпризом. Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила... Вот это были деньки.$b$bОтправляйся в Подгород, поговори с Эльталисте, $n. Она ждет тебя в Квартале Воинов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5645,'Бесстрашие','$n, ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне. Торопитесь, $Gмогучий мой друг:могучая моя госпожа;, ибо близится срок вашего очередного испытания. Хотя я хотел бы стать свидетелем особых обрядов вашей расы, но мое место здесь. Но да пребудет с вами Свет в пути вашем. Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии.','Поговорите с верховным жрецом Роханом в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесстрашие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне. Торопитесь, $Gмогучий мой друг:могучая моя госпожа;, ибо близится срок вашего очередного испытания. Хотя я хотел бы стать свидетелем особых обрядов вашей расы, но мое место здесь. Но да пребудет с вами Свет в пути вашем. Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным жрецом Роханом в Стальгорне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5646,'Всепожирающая чума','Эльталисте оказала моему народу большое доверие, посылая ко мне учеников, а теперь я сделаю то же для ее племени.$b$bВозвращайся в Подгород, $n. Твоя госпожа ждет тебя в Квартале Воинов, чтобы рассказать еще больше о твоем народе и его обычаях. Ступай, не медли.','Поговорите с Эльталисте в Подгороде.','Ты $Gвернулся:вернулась;, это хорошо, и даже не слишком поздно – это совсем здорово, $N. У нас есть много вещей, которые надо обсудить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всепожирающая чума',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эльталисте оказала моему народу большое доверие, посылая ко мне учеников, а теперь я сделаю то же для ее племени.$b$bВозвращайся в Подгород, $n. Твоя госпожа ждет тебя в Квартале Воинов, чтобы рассказать еще больше о твоем народе и его обычаях. Ступай, не медли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gвернулся:вернулась;, это хорошо, и даже не слишком поздно – это совсем здорово, $N. У нас есть много вещей, которые надо обсудить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5647,'Бесстрашие','Твоя раса так сильна, $n. Мы гордимся союзом с вами. С каждым закатом ты и твои сородичи не только все ближе к разгадке вашего истинного происхождения, но и обретаете все большую уверенность в том, что вы на верном пути во многом. Именно эта уверенность приносит вам победу.$B$BНедавно из Стальгорна пришла весть. Тебя просят вернуться и поговорить с верховным жрецом Роханом в Палатах Магии. Не стоит заставлять его ждать. Да направит твой путь Элуна.','Поговорите с верховным жрецом Роханом в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесстрашие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя раса так сильна, $n. Мы гордимся союзом с вами. С каждым закатом ты и твои сородичи не только все ближе к разгадке вашего истинного происхождения, но и обретаете все большую уверенность в том, что вы на верном пути во многом. Именно эта уверенность приносит вам победу.$B$BНедавно из Стальгорна пришла весть. Тебя просят вернуться и поговорить с верховным жрецом Роханом в Палатах Магии. Не стоит заставлять его ждать. Да направит твой путь Элуна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным жрецом Роханом в Стальгорне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5648,'Одеяния духовности','Что ж, $n, вот ты и $gготов:готова; к своему первому испытанию. К югу от Колючего Холма, сразу за городской чертой, лежит раненная орчиха из нашего отряда. Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою. Помочь ей может только кто-то из нас. Ее зовут Корджа. Найди ее, исцели и дай ей благословение наших предков.$b$bСделай это – и я сочту, что ты $gподтвердил:подтвердила; свою готовность ступить на путь жреца.','Найдите рубаку Кор\'жу и исцелите ее раны, пользуясь Малым исцелением (уровень 2). Затем скажите ей Слово силы: Стойкость – и вернитесь к Тай\'джин в Колючий Холм.','$GМолодец:Умница;... $Gоживил:оживила; и $Gвылечил:вылечила; Кор\'жу... пусть она храбро обороняет и дальше наш город от нападений гадких людей.$B$BЯ вспоминаю дни битв, где нередко мудрый сметает того, кто полагается на грубую силу.$B$BХорошо $Gсработал:сработала;, $N. Возьми это одеяние. Может быть, оно пригодится тебе, может быть нет, но ты $Gзаслужил:заслужила; ее и я рада назвать тебя $Gбратом:сестрой;.','Многие думают, что исцеляющая магия мощна, и это логично, но мало кто подозревает, насколько она мощна... Ты можешь возвратить к жизни множество существ или даже воскресить их. Помогай воинам, магам, и остальным, по возможности.','Вернитесь к Тай\'джин в Колючий Холм, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одеяния духовности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, $n, вот ты и $gготов:готова; к своему первому испытанию. К югу от Колючего Холма, сразу за городской чертой, лежит раненная орчиха из нашего отряда. Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою. Помочь ей может только кто-то из нас. Ее зовут Корджа. Найди ее, исцели и дай ей благословение наших предков.$b$bСделай это – и я сочту, что ты $gподтвердил:подтвердила; свою готовность ступить на путь жреца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите рубаку Кор\'жу и исцелите ее раны, пользуясь Малым исцелением (уровень 2). Затем скажите ей Слово силы: Стойкость – и вернитесь к Тай\'джин в Колючий Холм.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;... $Gоживил:оживила; и $Gвылечил:вылечила; Кор\'жу... пусть она храбро обороняет и дальше наш город от нападений гадких людей.$B$BЯ вспоминаю дни битв, где нередко мудрый сметает того, кто полагается на грубую силу.$B$BХорошо $Gсработал:сработала;, $N. Возьми это одеяние. Может быть, оно пригодится тебе, может быть нет, но ты $Gзаслужил:заслужила; ее и я рада назвать тебя $Gбратом:сестрой;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Многие думают, что исцеляющая магия мощна, и это логично, но мало кто подозревает, насколько она мощна... Ты можешь возвратить к жизни множество существ или даже воскресить их. Помогай воинам, магам, и остальным, по возможности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тай\'джин в Колючий Холм, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5649,'В пользу духовности','Понимаешь, наш народ присоединился к Орде, потому что они к нам добры. Они – преданные друзья, они многому нас научили, внушили нам представление о чести... Но наши старые обычаи еще живы. Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне.$b$bТы это знаешь. Вот почему я посылаю тебя в Колючий Холм, к Тай\'джин. Она откроет тебе мудрость нашего племени. Ступай к ней, когда будешь $gготов:готова;.','Поговорите с Тай\'джин в Дуротаре.','Аа... ты Gпришел:пришла; к Тай\'джин. Это хорошо.$B$BТебе нужно знать, что мы уже не то племя, что присоединилось когда-то к Орде. Сейчас мы гораздо сильнее. Мы сильнее потому, что научились приспосабливаться, Орда многому научила нас. Мы больше не побеждаем врагов, а потом забираем у них силу. Сейчас, мы сначала собираем силы, а потом побеждаем врагов.$B$BРазница кажется незначительной, но ты узнаешь и почувствуешь ее. Племя рассчитывает, что ты обучишься таким вещам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В пользу духовности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понимаешь, наш народ присоединился к Орде, потому что они к нам добры. Они – преданные друзья, они многому нас научили, внушили нам представление о чести... Но наши старые обычаи еще живы. Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне.$b$bТы это знаешь. Вот почему я посылаю тебя в Колючий Холм, к Тай\'джин. Она откроет тебе мудрость нашего племени. Ступай к ней, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тай\'джин в Дуротаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Аа... ты Gпришел:пришла; к Тай\'джин. Это хорошо.$B$BТебе нужно знать, что мы уже не то племя, что присоединилось когда-то к Орде. Сейчас мы гораздо сильнее. Мы сильнее потому, что научились приспосабливаться, Орда многому научила нас. Мы больше не побеждаем врагов, а потом забираем у них силу. Сейчас, мы сначала собираем силы, а потом побеждаем врагов.$B$BРазница кажется незначительной, но ты узнаешь и почувствуешь ее. Племя рассчитывает, что ты обучишься таким вещам.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5650,'Одеяния Тьмы','Мы черпаем силу из тьмы и теней, $n, но ваше дело – не только дело тьмы. Вы поняли, что большая заслуга есть и в изучении искусства лечения. Это мудрый выбор. Но прежде чем познать тьму, вы должны познать и свет, а для этого нужно пройти испытание.$B$BК северу от кладбища находится раненый страж смерти по имени Кел – он защищал нас от гноллов, и ему требуется лечение. Но для того чтобы он мог и дальше исполнять свой долг, вы должны также придать ему сил. Используйте для этого свои заклинания, а потом возвращайтесь ко мне.','Найдите стража смерти Кела и вылечите его раны заклинанием "Малое Исцеление" (ранг 2). После этого прочтите над ним "Слово Силы: Стойкость", а затем вернитесь к темному священнику Берилу в Брилл.','Ты $Gпрошел:прошела; мой тест. $GМолодец:Умница;.$B$BИтак, вскоре ты сможешь погрузить на себя еще одну ношу, возложить на себя ответственность изучать темные энергии, к которым не имеет доступ жрец любой другой расы.$B$BВозьми это одеяние как символ! Носи его с гордостью.','Наши силы дают нам невероятные возможности, $N, однако скоро вы поймете, что наша способность исцелять раны и повышать наносимый врагам урон является одной из самых полезных и желанных. Не сомневайтесь в выбранном пути жреца – вы не раз убедитесь, что поступили правильно, избрав его. А вот если вы желаете применять магическую энергию для уничтожения врагов, то вам стоило бы лучше отправиться изучать тайную магию.','Вернитесь к темному священнику Берилу в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одеяния Тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы черпаем силу из тьмы и теней, $n, но ваше дело – не только дело тьмы. Вы поняли, что большая заслуга есть и в изучении искусства лечения. Это мудрый выбор. Но прежде чем познать тьму, вы должны познать и свет, а для этого нужно пройти испытание.$B$BК северу от кладбища находится раненый страж смерти по имени Кел – он защищал нас от гноллов, и ему требуется лечение. Но для того чтобы он мог и дальше исполнять свой долг, вы должны также придать ему сил. Используйте для этого свои заклинания, а потом возвращайтесь ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите стража смерти Кела и вылечите его раны заклинанием "Малое Исцеление" (ранг 2). После этого прочтите над ним "Слово Силы: Стойкость", а затем вернитесь к темному священнику Берилу в Брилл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпрошел:прошела; мой тест. $GМолодец:Умница;.$B$BИтак, вскоре ты сможешь погрузить на себя еще одну ношу, возложить на себя ответственность изучать темные энергии, к которым не имеет доступ жрец любой другой расы.$B$BВозьми это одеяние как символ! Носи его с гордостью.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наши силы дают нам невероятные возможности, $N, однако скоро вы поймете, что наша способность исцелять раны и повышать наносимый врагам урон является одной из самых полезных и желанных. Не сомневайтесь в выбранном пути жреца – вы не раз убедитесь, что поступили правильно, избрав его. А вот если вы желаете применять магическую энергию для уничтожения врагов, то вам стоило бы лучше отправиться изучать тайную магию.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному священнику Берилу в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5651,'Во славу Тьмы','Отрекшиеся извлекли много уроков из своего опыта и поняли такие вещи, о которых остальные только начинают догадываться. И несмотря на то что наш путь лежит во тьме, скоро вы поймете, что очень много вещей зависит от нее – так же как и от света. Вы научитесь использовать и то и другое... с должной осторожностью. Но никогда не забывайте того, что нас создали в тлене и бросили гнить, как какие-нибудь отбросы. Тьма – это наш дом.$B$BКогда будете готовы узнать больше, разыщите темного священника Берила в Брилле.','Поговорите с темным священником Берилом в Тирисфальских лесах.','Наконец-то ты $Gпоявился:появилась;. Одной лишь твое веры недостаточно, чтобы пройти испытания, ожидающие тебя. Нужна настойчивость, да и немного честолюбия не помешает.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во славу Тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отрекшиеся извлекли много уроков из своего опыта и поняли такие вещи, о которых остальные только начинают догадываться. И несмотря на то что наш путь лежит во тьме, скоро вы поймете, что очень много вещей зависит от нее – так же как и от света. Вы научитесь использовать и то и другое... с должной осторожностью. Но никогда не забывайте того, что нас создали в тлене и бросили гнить, как какие-нибудь отбросы. Тьма – это наш дом.$B$BКогда будете готовы узнать больше, разыщите темного священника Берила в Брилле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с темным священником Берилом в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то ты $Gпоявился:появилась;. Одной лишь твое веры недостаточно, чтобы пройти испытания, ожидающие тебя. Нужна настойчивость, да и немного честолюбия не помешает.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (5652,'Обессиливающий сглаз','На этом уроке не мешало бы взглянуть на такое заклинание, как обессиливающий сглаз. Оно поможет тебе в твоих грядущих сражениях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обессиливающий сглаз',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На этом уроке не мешало бы взглянуть на такое заклинание, как обессиливающий сглаз. Оно поможет тебе в твоих грядущих сражениях.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5653,'<NYI> Обессиливающий сглаз','Один из ваших жрецов просил нас передать тебе послание на случай твоего появления. Тебе велено вернуться в Оргриммар. Кажется, один из твоих сородичей – жрец по имени Ур\'кьо, если не ошибаюсь, – считает, что ты $gготов:готова; к дальнейшему обучению. Он говорит, что это как-то связано с вашими традиционными обрядами, и что Ур\'кьо можно найти на Аллее Духов.','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Обессиливающий сглаз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из ваших жрецов просил нас передать тебе послание на случай твоего появления. Тебе велено вернуться в Оргриммар. Кажется, один из твоих сородичей – жрец по имени Ур\'кьо, если не ошибаюсь, – считает, что ты $gготов:готова; к дальнейшему обучению. Он говорит, что это как-то связано с вашими традиционными обрядами, и что Ур\'кьо можно найти на Аллее Духов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5654,'Обессиливающий сглаз','Пора тебе встретиться с Ур\'кьо, $n. Ты найдешь его на Аллее Духов, в городе орков. Ступай туда и поговори с ним. Пора тебе познать древнюю мудрость нашего народа. Пора вступить в круг и стать настоящим жрецом нашего племени.','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обессиливающий сглаз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пора тебе встретиться с Ур\'кьо, $n. Ты найдешь его на Аллее Духов, в городе орков. Ступай туда и поговори с ним. Пора тебе познать древнюю мудрость нашего народа. Пора вступить в круг и стать настоящим жрецом нашего племени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5655,'Обессиливающий сглаз','Мне нужно было удостовериться, что ты не уйдешь слишком далеко от дома, $n. Меня послали за тобой потому, что Ур\'кьо, величайший из наших жрецов, желает поговорить с тобой. Ступай туда. Ступай на Аллею Духов в городе орков и поговори с Ур\'кьо. Он ждет тебя.','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обессиливающий сглаз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно было удостовериться, что ты не уйдешь слишком далеко от дома, $n. Меня послали за тобой потому, что Ур\'кьо, величайший из наших жрецов, желает поговорить с тобой. Ступай туда. Ступай на Аллею Духов в городе орков и поговори с Ур\'кьо. Он ждет тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5656,'Обессиливающий сглаз','Мое нестареющее сердце всегда греет мысль о том, что по миру бродит множество жрецов всех культур. Хорошо знать, что на свете есть сила, не имеющая отношения к тайной магии и вполне доступная нам. Вот почему я сочту за честь указать тебе путь, $n.$b$bУркьо, ваш великий жрец в Оргриммаре, просит тебя прибыть к нему. Ты найдешь его на Аллее Духов.','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обессиливающий сглаз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мое нестареющее сердце всегда греет мысль о том, что по миру бродит множество жрецов всех культур. Хорошо знать, что на свете есть сила, не имеющая отношения к тайной магии и вполне доступная нам. Вот почему я сочту за честь указать тебе путь, $n.$b$bУркьо, ваш великий жрец в Оргриммаре, просит тебя прибыть к нему. Ты найдешь его на Аллее Духов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5657,'Обессиливающий сглаз','Домой! Возвращайся домой, $gюный:юная:r; |3-6($r)!$b$bТвой духовный наставник Ур\'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути.$b$bСтупай на Аллею Духов в Оргриммаре, великом городе Орды! Ты найдешь его там.','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обессиливающий сглаз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Домой! Возвращайся домой, $gюный:юная:r; |3-6($r)!$b$bТвой духовный наставник Ур\'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути.$b$bСтупай на Аллею Духов в Оргриммаре, великом городе Орды! Ты найдешь его там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (5658,'Прикосновение слабости','А, $Gюный:юная; $Gжрец:жрица; снова здесь. Я хочу преподать тебе урок, который ты не скоро забудешь. $GГотов:Готова; ли ты?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикосновение слабости',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, $Gюный:юная; $Gжрец:жрица; снова здесь. Я хочу преподать тебе урок, который ты не скоро забудешь. $GГотов:Готова; ли ты?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5659,'<NYI>Внезапная слабость','Тебе здесь не место, $n. Особенно сейчас, когда тебя ждут в Квартале Воинов. Эльталисте созывает всех своих жрецов и жриц. Пришло время поведать им о том, какой мощью они обладают.$b$bОна не переносит опозданий и пустых оправданий, поэтому советую тебе тронуться в путь.','Поговорите с Эльталисте в Подгороде.','А, хорошо, еще $Gодин:одна; $Gприбыл:прибыла;. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь $Gвознагражден:вознаграждена;.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI>Внезапная слабость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе здесь не место, $n. Особенно сейчас, когда тебя ждут в Квартале Воинов. Эльталисте созывает всех своих жрецов и жриц. Пришло время поведать им о том, какой мощью они обладают.$b$bОна не переносит опозданий и пустых оправданий, поэтому советую тебе тронуться в путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, хорошо, еще $Gодин:одна; $Gприбыл:прибыла;. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь $Gвознагражден:вознаграждена;.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5660,'Прикосновение слабости','Далеко же ты $gзабрался:забралась:c;, |3-6($c). Тебя ждут в большом городе под землей. Твоя госпожа, Эльталисте, велит тебе вернуться. Как и в моем племени, есть вещи, которым тебя может научить лишь она. И не задерживайся попусту. Лучше лети в Квартал Воинов на самом быстром дирижабле.','Поговорите с Эльталисте в Подгороде.','А, хорошо, еще $Gодин:одна; $Gприбыл:прибыла;. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь $Gвознагражден:вознаграждена;.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикосновение слабости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Далеко же ты $gзабрался:забралась:c;, |3-6($c). Тебя ждут в большом городе под землей. Твоя госпожа, Эльталисте, велит тебе вернуться. Как и в моем племени, есть вещи, которым тебя может научить лишь она. И не задерживайся попусту. Лучше лети в Квартал Воинов на самом быстром дирижабле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, хорошо, еще $Gодин:одна; $Gприбыл:прибыла;. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь $Gвознагражден:вознаграждена;.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5661,'Прикосновение слабости','Ты всего лишь гость в деревне Кровавого Копыта, $n, а дом твой далеко. Меня послали сюда искать жрецов из моего племени. С ними хотят говорить вожди. Но и тебе я могу помочь.$b$bГоворят, что ваша главная жрица велит всем Отрекшимся прийти к ней – видно, ей есть что сказать.$B$BСтупай, поговори с Эльталисте в Квартале Воинов этого вашего города, как его там...','Поговорите с Эльталисте в Подгороде.','А, хорошо, еще $Gодин:одна; $Gприбыл:прибыла;. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь $Gвознагражден:вознаграждена;.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикосновение слабости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты всего лишь гость в деревне Кровавого Копыта, $n, а дом твой далеко. Меня послали сюда искать жрецов из моего племени. С ними хотят говорить вожди. Но и тебе я могу помочь.$b$bГоворят, что ваша главная жрица велит всем Отрекшимся прийти к ней – видно, ей есть что сказать.$B$BСтупай, поговори с Эльталисте в Квартале Воинов этого вашего города, как его там...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, хорошо, еще $Gодин:одна; $Gприбыл:прибыла;. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь $Gвознагражден:вознаграждена;.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5662,'Прикосновение слабости','Мое почтение тебе и твоему народу, $n. Обычно я учу лишь своих соплеменников. Тебе же передала знания Эльталисте из города, некогда звавшегося Лордероном.$b$bВозвращайся к ней, ведь только она может передать тебе способности, отличающие воинов вашей веры от других.$b$bСтупай в Квартал Воинов Подгорода и отыщи там свою госпожу.','Поговорите с Эльталисте в Подгороде.','А, хорошо, еще $Gодин:одна; $Gприбыл:прибыла;. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь $Gвознагражден:вознаграждена;.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикосновение слабости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мое почтение тебе и твоему народу, $n. Обычно я учу лишь своих соплеменников. Тебе же передала знания Эльталисте из города, некогда звавшегося Лордероном.$b$bВозвращайся к ней, ведь только она может передать тебе способности, отличающие воинов вашей веры от других.$b$bСтупай в Квартал Воинов Подгорода и отыщи там свою госпожу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, хорошо, еще $Gодин:одна; $Gприбыл:прибыла;. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь $Gвознагражден:вознаграждена;.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5663,'Прикосновение слабости','Эльталисте послала вести всем своим жрецам. Нам велено отправить молодежь в Подгород на обучение. Если ты в самом деле считаешь себя $Gодним:одной; из верных, возвращайся туда.$b$bЭльталисте живет в Квартале Воинов в глубинах Подгорода.','Поговорите с Эльталисте в Подгороде.','А, хорошо, еще $Gодин:одна; $Gприбыл:прибыла;. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь $Gвознагражден:вознаграждена;.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикосновение слабости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эльталисте послала вести всем своим жрецам. Нам велено отправить молодежь в Подгород на обучение. Если ты в самом деле считаешь себя $Gодним:одной; из верных, возвращайся туда.$b$bЭльталисте живет в Квартале Воинов в глубинах Подгорода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, хорошо, еще $Gодин:одна; $Gприбыл:прибыла;. Время для меня не имеет значения, но для других-то оно ценно. Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь $Gвознагражден:вознаграждена;.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5664,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5665,'<UNUSED>','Word was sent here from Darnassus, $n. It seems one of your priestesses wants you to return home. Speak to Priestess Alathea at the Temple of the Moon whenever you\'re able. It seems she is pleased with your progress. I am sure she takes great pride in seeing one of Elune\'s servants take such great strides in $ghis:her; faith.$B$BThe Light be with you.','Поговорите в Дарнасе со жрицей Алатеей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Word was sent here from Darnassus, $n. It seems one of your priestesses wants you to return home. Speak to Priestess Alathea at the Temple of the Moon whenever you\'re able. It seems she is pleased with your progress. I am sure she takes great pride in seeing one of Elune\'s servants take such great strides in $ghis:her; faith.$B$BThe Light be with you.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5666,'<UNUSED>','Oh, $n, I am pleased to catch you. There has been talk that you are prepared for your next test at the Temple of the Moon. Priestess Alathea herself wishes to speak to you. You should return to Darnassus as quickly as you can. Finish whatever business you have here and make haste.','Поговорите в Дарнасе со жрицей Алатеей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Oh, $n, I am pleased to catch you. There has been talk that you are prepared for your next test at the Temple of the Moon. Priestess Alathea herself wishes to speak to you. You should return to Darnassus as quickly as you can. Finish whatever business you have here and make haste.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5667,'<UNUSED>','Aye, good to see you\'re doing well in your training, young $gpriest:priestess;. One of your kind was here looking for you not too long ago. It seems you\'re wanted back in Darnassus. Something about Priestess Alathea and the Temple of the Moon. It sounded important. Perhaps you should return there soon.','Поговорите в Дарнасе со жрицей Алатеей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Aye, good to see you\'re doing well in your training, young $gpriest:priestess;. One of your kind was here looking for you not too long ago. It seems you\'re wanted back in Darnassus. Something about Priestess Alathea and the Temple of the Moon. It sounded important. Perhaps you should return there soon.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5668,'<NYI> Благословение Света') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Благословение Света',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5669,'<NYI> Благословение Света','О, $n, какое счастье, что мы встретились! Тебя разыскивают. Верховная жрица Лорена из Собора Света хочет встретиться с тобой. Наверное, хочет обсудить твое дальнейшее обучение. Многие члены моего ордена проходят такую проверку и обретают новые полезные умения.','Поговорите с Верховной жрицей Лореной в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Благословение Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, $n, какое счастье, что мы встретились! Тебя разыскивают. Верховная жрица Лорена из Собора Света хочет встретиться с тобой. Наверное, хочет обсудить твое дальнейшее обучение. Многие члены моего ордена проходят такую проверку и обретают новые полезные умения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5670,'<NYI> Благословение Света','$n! Как тебе удалось пропустить гонца из Штормграда? Вы разминулись буквально на минутку! Между прочим, хорошие новости: Верховная жрица Лорена хочет тебя видеть. Наверное, она сочла, что для тебя настало время отточить свои навыки.$B$BКогда закончишь все свои дела здесь, ступай в Штормград, в Собор Света, и поговори с ней. Она будет тебя ждать.','Поговорите с Верховной жрицей Лореной в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Благословение Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Как тебе удалось пропустить гонца из Штормграда? Вы разминулись буквально на минутку! Между прочим, хорошие новости: Верховная жрица Лорена хочет тебя видеть. Наверное, она сочла, что для тебя настало время отточить свои навыки.$B$BКогда закончишь все свои дела здесь, ступай в Штормград, в Собор Света, и поговори с ней. Она будет тебя ждать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5671,'<NYI> Благословение Света','$gЖрец:Жрица;, твоя Церковь призывает тебя вернуться в Штормград. Верховная жрица Лорена хочет поговорить с тобой. Она считает, что для тебя настало время перейти на новый, более высокий уровень мастерства.$B$BТы найдешь верховную жрицу в Соборе Света. Да осияет твой путь Элуна!','Поговорите с Верховной жрицей Лореной в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Благословение Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gЖрец:Жрица;, твоя Церковь призывает тебя вернуться в Штормград. Верховная жрица Лорена хочет поговорить с тобой. Она считает, что для тебя настало время перейти на новый, более высокий уровень мастерства.$B$BТы найдешь верховную жрицу в Соборе Света. Да осияет твой путь Элуна!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (5672,'Благодать Элуны','Посвятив себя Элуне и нашему народа, ты $Gдостиг:достигла; того состояния, которого не все из нас могут достичь') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодать Элуны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посвятив себя Элуне и нашему народа, ты $Gдостиг:достигла; того состояния, которого не все из нас могут достичь',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5673,'Благодать Элуны','Знай, что здесь ты можешь в любое время обратиться к любому наставнику, $n. Впрочем, есть знания, которые мы не можем тебе предоставить. Среди них – учение вашей богини Элуны. Верным своим приверженцам она дает особые способности, и, если я не ошибаюсь, тебе пора вернуться домой, в Храм Луны, и пройти испытание.$B$BТак что как сможешь – возвращайся и поговори со жрицей Алатеей.','Поговорите в Дарнасе со жрицей Алатеей.','Элуна благословляет тебя за столь быстрое возвращение. Важное дело ожидает тебя и важные дела ждут твоего решения. Когда отдохнешь от своего путешествия повидай меня снова. Тогда мы обсудим, как именно мы начнем... точнее продолжим, твою тренировку!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодать Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знай, что здесь ты можешь в любое время обратиться к любому наставнику, $n. Впрочем, есть знания, которые мы не можем тебе предоставить. Среди них – учение вашей богини Элуны. Верным своим приверженцам она дает особые способности, и, если я не ошибаюсь, тебе пора вернуться домой, в Храм Луны, и пройти испытание.$B$BТак что как сможешь – возвращайся и поговори со жрицей Алатеей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Элуна благословляет тебя за столь быстрое возвращение. Важное дело ожидает тебя и важные дела ждут твоего решения. Когда отдохнешь от своего путешествия повидай меня снова. Тогда мы обсудим, как именно мы начнем... точнее продолжим, твою тренировку!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5674,'Благодать Элуны','Настал славный день, $n. Ты $Gдостиг:достигла; возраста, когда наши $gжрецы:жрицы; изучают те способности, которые свойственны только ночным эльфам. Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела. Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны.','Поговорите в Дарнасе со жрицей Алатеей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодать Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настал славный день, $n. Ты $Gдостиг:достигла; возраста, когда наши $gжрецы:жрицы; изучают те способности, которые свойственны только ночным эльфам. Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела. Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5675,'Благодать Элуны','Не тяни время, $gдруг:подруга;. Пора тебе возвращаться домой в Дарнас. Жрица Алатея велит возвращаться на обучение. Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света. Так что как сможешь – иди. Алатея в своем письме говорит, что будет ждать тебя в Храме Луны. Удачи.','Поговорите в Дарнасе со жрицей Алатеей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодать Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не тяни время, $gдруг:подруга;. Пора тебе возвращаться домой в Дарнас. Жрица Алатея велит возвращаться на обучение. Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света. Так что как сможешь – иди. Алатея в своем письме говорит, что будет ждать тебя в Храме Луны. Удачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (5676,'Волшебное искажение','Чтобы защититься от тайной магии, которая является нашим основным врагом, мы должны знать некоторые заклинания.$B$BЯ научу тебя заклинаниям, которые помогут защитить себя и спутников от вредоносного воздействия тайной магии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебное искажение',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чтобы защититься от тайной магии, которая является нашим основным врагом, мы должны знать некоторые заклинания.$B$BЯ научу тебя заклинаниям, которые помогут защитить себя и спутников от вредоносного воздействия тайной магии.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5677,'Волшебное искажение','Мне бы хотелось показать тебе кое-какие из наших особых методик обучения, которые направят тебя по пути Света, но меня опередили. Тебе нужно вернуться в Штормград, $n... Прямо сейчас. Поверь мне, так будет лучше. Когда ты встретишься с Верховной жрицей Лореной из Собора Света, ты поймешь, о чем я говорю. Для вашей расы настало время подумать о будущем и выбрать свой собственный путь.','Поговорите с Верховной жрицей Лореной в Штормграде.','Ах, у вас сейчас чудесное время, $N. Я начал задаваться вопросом, все ли мои посланники были успешными. Я рад видеть, что это так, иначе я готов поспорить, что вы всё еще были бы в мире, узнавая больше обо всех угрозах, которые существуют против нашего народа.$B$BВы готовы? Я имею в виду готовы к дальнейшим тренировкам. Ваша сила растет быстрее, и я чувствую, что вы готовы больше узнать о нашей вере.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебное искажение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне бы хотелось показать тебе кое-какие из наших особых методик обучения, которые направят тебя по пути Света, но меня опередили. Тебе нужно вернуться в Штормград, $n... Прямо сейчас. Поверь мне, так будет лучше. Когда ты встретишься с Верховной жрицей Лореной из Собора Света, ты поймешь, о чем я говорю. Для вашей расы настало время подумать о будущем и выбрать свой собственный путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, у вас сейчас чудесное время, $N. Я начал задаваться вопросом, все ли мои посланники были успешными. Я рад видеть, что это так, иначе я готов поспорить, что вы всё еще были бы в мире, узнавая больше обо всех угрозах, которые существуют против нашего народа.$B$BВы готовы? Я имею в виду готовы к дальнейшим тренировкам. Ваша сила растет быстрее, и я чувствую, что вы готовы больше узнать о нашей вере.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5678,'Волшебное искажение','Тебе пора возвращаться в Штормград. Старшие иерархи призывают тебя продолжить тренировки. Жаль, что мне пришлось разыскивать тебя, но я делаю это во имя союза между нашими расами.$B$BБуду говорить откровенно, тайная магия не внушает мне никакого доверия, хоть по благословлению богов, хоть без них...$b$BТы понимаешь, о чем я говорю? Вернись в Собор Света. Верховная жрица Лорена ждет тебя.','Поговорите с Верховной жрицей Лореной в Штормграде.','Ах, у вас сейчас чудесное время, $N. Я начал задаваться вопросом, все ли мои посланники были успешными. Я рад видеть, что это так, иначе я готов поспорить, что вы всё еще были бы в мире, узнавая больше обо всех угрозах, которые существуют против нашего народа.$B$BВы готовы? Я имею в виду готовы к дальнейшим тренировкам. Ваша сила растет быстрее, и я чувствую, что вы готовы больше узнать о нашей вере.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебное искажение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе пора возвращаться в Штормград. Старшие иерархи призывают тебя продолжить тренировки. Жаль, что мне пришлось разыскивать тебя, но я делаю это во имя союза между нашими расами.$B$BБуду говорить откровенно, тайная магия не внушает мне никакого доверия, хоть по благословлению богов, хоть без них...$b$BТы понимаешь, о чем я говорю? Вернись в Собор Света. Верховная жрица Лорена ждет тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, у вас сейчас чудесное время, $N. Я начал задаваться вопросом, все ли мои посланники были успешными. Я рад видеть, что это так, иначе я готов поспорить, что вы всё еще были бы в мире, узнавая больше обо всех угрозах, которые существуют против нашего народа.$B$BВы готовы? Я имею в виду готовы к дальнейшим тренировкам. Ваша сила растет быстрее, и я чувствую, что вы готовы больше узнать о нашей вере.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (5679,'Всепожирающая чума','Я обучу тебя всепожирающей чуме, конечно, если ты уже $Gготов:готова; к этому, $N. Это заклинание поможет тебе в твоих грядущих сражениях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всепожирающая чума',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я обучу тебя всепожирающей чуме, конечно, если ты уже $Gготов:готова; к этому, $N. Это заклинание поможет тебе в твоих грядущих сражениях.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (5680,'Страж Тьмы','Твои обряды наступят очень скоро. Сейчас я обучу тебя заклинанию, которое поможет тебя в сражении против твоих врагов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страж Тьмы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои обряды наступят очень скоро. Сейчас я обучу тебя заклинанию, которое поможет тебя в сражении против твоих врагов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5681,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5682,'<UNUSED>','The time has come for you to return to Darnassus again, $n. Speak to High Priestess Alathea in the Temple of the Moon. She will tell you what you need to know.$B$BIf I am not mistaken, it will be something about new garments for your station within your order. May the Light be with you.','Speak with High Priestess Alathea in Darnassus.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','The time has come for you to return to Darnassus again, $n. Speak to High Priestess Alathea in the Temple of the Moon. She will tell you what you need to know.$B$BIf I am not mistaken, it will be something about new garments for your station within your order. May the Light be with you.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak with High Priestess Alathea in Darnassus.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5683,'<UNUSED>','Oh, $gbrother:sister;, I am so pleased for you! It is time for you to return to Darnassus and speak to High Priestess Alathea once again. Her messenger was almost certain it had to do with earning your newest garments of our order.$B$BWhen you can, return home, and give our order my very best.$B$BElune be with you.','Speak to High Priestess Alathea in Darnassus.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Oh, $gbrother:sister;, I am so pleased for you! It is time for you to return to Darnassus and speak to High Priestess Alathea once again. Her messenger was almost certain it had to do with earning your newest garments of our order.$B$BWhen you can, return home, and give our order my very best.$B$BElune be with you.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to High Priestess Alathea in Darnassus.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5684,'<UNUSED>','Hmph, good to see you\'re doin\' so well for yourself, $gpriest:priestess;. Bet you\'re wonderin\' when it\'s time for you to be called back home to Darnassus for some kind of celebration for your greatness, huh? Well, not today... well, not any kind of celebration anyway.$B$BHigh Priestess Alathea\'s sent word to me that I should direct you to her if I came across you. You can find her in the Temple of the Moon still... in case you forgot. Haha.','Speak to High Priestess Alathea in Darnassus.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Hmph, good to see you\'re doin\' so well for yourself, $gpriest:priestess;. Bet you\'re wonderin\' when it\'s time for you to be called back home to Darnassus for some kind of celebration for your greatness, huh? Well, not today... well, not any kind of celebration anyway.$B$BHigh Priestess Alathea\'s sent word to me that I should direct you to her if I came across you. You can find her in the Temple of the Moon still... in case you forgot. Haha.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to High Priestess Alathea in Darnassus.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5685,'<NYI> <TXT> Защита Света') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> Защита Света',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5686,'<NYI> Да спасет тебя Свет!','Тебе пора отправляться в Штормград, $gжрец:жрица;. Верховная жрица Лорена хочет наградить тебя за верное служение Свету. Ты найдешь ее в Соборе Света, обратись прямо к ней.$B$BС другой стороны, можешь остаться здесь и тренироваться самостоятельно, решать тебе. Чем смогу – помогу, обращайся.','Поговорите с Верховной жрицей Лореной в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Да спасет тебя Свет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе пора отправляться в Штормград, $gжрец:жрица;. Верховная жрица Лорена хочет наградить тебя за верное служение Свету. Ты найдешь ее в Соборе Света, обратись прямо к ней.$B$BС другой стороны, можешь остаться здесь и тренироваться самостоятельно, решать тебе. Чем смогу – помогу, обращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5687,'<NYI> Да спасет тебя Свет!','$n, тебе пора вернуться в Собор Света в Штормграде. Верховная жрица Лорена ожидает тебя. Тебе надлежит прийти к ней, дабы выполнить долг перед своим народом и Светом.$B$BДа хранит тебя Элуна во время путешествия!','Поговорите с Верховной жрицей Лореной в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Да спасет тебя Свет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, тебе пора вернуться в Собор Света в Штормграде. Верховная жрица Лорена ожидает тебя. Тебе надлежит прийти к ней, дабы выполнить долг перед своим народом и Светом.$B$BДа хранит тебя Элуна во время путешествия!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5688,'<NYI> <TXT> Навыки вуду') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> Навыки вуду',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5689,'<NYI> Навыки вуду','Эй, |3-6($r)! Сюда не так давно приходил посланец, тебя разыскивал. Сказал, что тебе нужно вернуться в Оргриммар и поговорить с Ур\'кьо на Аллее Духов. Он не выглядел рассерженным, но похоже, что дело важное. Может, сходишь, выяснишь?','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Навыки вуду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, |3-6($r)! Сюда не так давно приходил посланец, тебя разыскивал. Сказал, что тебе нужно вернуться в Оргриммар и поговорить с Ур\'кьо на Аллее Духов. Он не выглядел рассерженным, но похоже, что дело важное. Может, сходишь, выяснишь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5690,'<NYI> <TXT> Навыки вуду') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> Навыки вуду',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5691,'<NYI><TXT>Во тьме ее создали') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI><TXT>Во тьме ее создали',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5692,'<NYI>Порождение тьмы','Хотя я могу поведать тебе очень о многом, $n, есть вещи, которым можно обучиться только у себя на родине. Например, тому, как сшить новые одеяния... такие, по которым все смогут узнать о твоей вере.$B$BЭльталисте велит направить тебя к ней, в Подгород. Она ждет тебя в Квартале Воинов. Если ты ослушаешься, она останется недовольна нами обоими.','Поговорите с Эльталисте в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI>Порождение тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя я могу поведать тебе очень о многом, $n, есть вещи, которым можно обучиться только у себя на родине. Например, тому, как сшить новые одеяния... такие, по которым все смогут узнать о твоей вере.$B$BЭльталисте велит направить тебя к ней, в Подгород. Она ждет тебя в Квартале Воинов. Если ты ослушаешься, она останется недовольна нами обоими.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`) VALUES (5693,'Хорошо, что ты... $gжив:жива;, $n.$b$bЭльталисте просит тебя вернуться в Подгород, когда закончишь дела в Громовом Утесе. Похоже, она сочла, что тебе стоит примерять новую одежду... Скорее всего, длинное одеяние.$b$bВерховная жрица ждет тебя в Квартале Воинов.','Поговорите с Эльталисте в Подгороде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, что ты... $gжив:жива;, $n.$b$bЭльталисте просит тебя вернуться в Подгород, когда закончишь дела в Громовом Утесе. Похоже, она сочла, что тебе стоит примерять новую одежду... Скорее всего, длинное одеяние.$b$bВерховная жрица ждет тебя в Квартале Воинов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5694,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5695,'<UNUSED>','Your temple asks for your presence in Darnassus, $n. Return to the Temple of the Moon and speak to Priestess Alathea. She will be waiting for you there.$B$BThe time has come for you to earn your next robe if you feel you are ready.','Speak to Priestesss Alathea in Darnassus.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Your temple asks for your presence in Darnassus, $n. Return to the Temple of the Moon and speak to Priestess Alathea. She will be waiting for you there.$B$BThe time has come for you to earn your next robe if you feel you are ready.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to Priestesss Alathea in Darnassus.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5696,'<UNUSED>','It is always a joyous day when I can direct one of our kind back to our home because the time has come for them to earn their next set of robes.$B$BPriestess Alathea is in the Temple of the Moon and wishes to speak to you. When you can, return to Darnassus for your next test, and Elune be with you, $n.','Speak to Prietess Alathea in Darnassus.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','It is always a joyous day when I can direct one of our kind back to our home because the time has come for them to earn their next set of robes.$B$BPriestess Alathea is in the Temple of the Moon and wishes to speak to you. When you can, return to Darnassus for your next test, and Elune be with you, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak to Prietess Alathea in Darnassus.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5697,'<UNUSED>','You keep up this rate of success, an\' you\'ll be makin\' me jealous that we don\'t have more of your $gpriests:priestesses; here in Ironforge, $n. You do your people proud.$B$BPriestess Alathea would like to speak to you again if you have time. She\'s in the Temple of the Moon in Darnassus. Go there, an\' the Light be with you.','Поговорите в Дарнасе со жрицей Алатеей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','You keep up this rate of success, an\' you\'ll be makin\' me jealous that we don\'t have more of your $gpriests:priestesses; here in Ironforge, $n. You do your people proud.$B$BPriestess Alathea would like to speak to you again if you have time. She\'s in the Temple of the Moon in Darnassus. Go there, an\' the Light be with you.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Дарнасе со жрицей Алатеей.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5698,'<NYI> <TXT> Малая надежда') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> Малая надежда',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5699,'<NYI> Малая надежда','$n, тебе пора собираться в Штормград! Тебя там дожидается Верховная жрица Лорена, она хочет испытать твою силу. Отправляйся в Собор Света и не слишком задерживайся по дороге. Всем нам хватает дел, и чем быстрее ты выучишься, тем легче будет всем твоим собратьям. Ты ведь понимаешь, что наш орден предпочитает обучать тех, кто показывает неплохие способности.$B$BСвет с тобой и все такое, как всегда, ага...','Поговорите с Верховной жрицей Лореной в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Малая надежда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, тебе пора собираться в Штормград! Тебя там дожидается Верховная жрица Лорена, она хочет испытать твою силу. Отправляйся в Собор Света и не слишком задерживайся по дороге. Всем нам хватает дел, и чем быстрее ты выучишься, тем легче будет всем твоим собратьям. Ты ведь понимаешь, что наш орден предпочитает обучать тех, кто показывает неплохие способности.$B$BСвет с тобой и все такое, как всегда, ага...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5700,'<NYI> Малая надежда','$n, собратья по вере нуждаются в тебе. Особенно Верховная жрица Лорена в Штормграде. Это неудивительно, ведь в наше беспокойное время, когда повсюду идут битвы то с Ордой, то с Плетью, Собор Света нуждается в любой помощи.$B$BЗакончи все свои дела и отправляйся в собор.','Поговорите с Верховной жрицей Лореной в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Малая надежда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, собратья по вере нуждаются в тебе. Особенно Верховная жрица Лорена в Штормграде. Это неудивительно, ведь в наше беспокойное время, когда повсюду идут битвы то с Ордой, то с Плетью, Собор Света нуждается в любой помощи.$B$BЗакончи все свои дела и отправляйся в собор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Верховной жрицей Лореной в Штормграде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5701,'<NYI> <TXT> Древние обряды') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> Древние обряды',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5702,'<NYI> Древние обряды','Эй, |3-6($r)! Я научу тебя тому, что ты хочешь знать, но имей в виду: тебя ищет... как же его зовут... Ур\'кьо! Речь шла о твоем возвращении в Долину Испытаний... Нет, не туда. В Аллею Духов... в Оргриммаре... Да, точно!$b$bВ общем, Ур\'кьо из Аллеи Духов хочет с тобой поговорить.','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Древние обряды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, |3-6($r)! Я научу тебя тому, что ты хочешь знать, но имей в виду: тебя ищет... как же его зовут... Ур\'кьо! Речь шла о твоем возвращении в Долину Испытаний... Нет, не туда. В Аллею Духов... в Оргриммаре... Да, точно!$b$bВ общем, Ур\'кьо из Аллеи Духов хочет с тобой поговорить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5703,'<NYI> Древние обряды','Твой духовный наставник Ур\'кьо хочет встретиться с тобой, $n. Не заставляй его ждать!$b$bТы найдешь его на Аллее Духов в Оргриммаре. Пусть твой народ гордится тобой!','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Древние обряды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твой духовный наставник Ур\'кьо хочет встретиться с тобой, $n. Не заставляй его ждать!$b$bТы найдешь его на Аллее Духов в Оргриммаре. Пусть твой народ гордится тобой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5704,'<NYI> <TXT>Одеяние нежити-жреца') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT>Одеяние нежити-жреца',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5705,'<NYI> Больше, чем тень','Добро пожаловать на Аллею Духов, $n. Впрочем, тебе стоит знать, что тебя ждут дома, в Подгороде. Ваша верховная жрица желает поговорить с тобой.$b$BТы уже знаешь, где ее искать – в Квартале Воинов в глубинах города.$b$bСтупай и не забывай: мы в любой момент с радостью поможем тебе продолжить обучение.','Поговорите с Эльталисте в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Больше, чем тень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать на Аллею Духов, $n. Впрочем, тебе стоит знать, что тебя ждут дома, в Подгороде. Ваша верховная жрица желает поговорить с тобой.$b$BТы уже знаешь, где ее искать – в Квартале Воинов в глубинах города.$b$bСтупай и не забывай: мы в любой момент с радостью поможем тебе продолжить обучение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5706,'<NYI> Больше, чем тень.','Вот мы и свиделись вновь, $n. Но пообщаться нам не удастся – Эльталисте послала весточку, велит тебе возвращаться в Подгород. Она по-прежнему в Квартале Воинов.$B$BНе беспокойся, думаю, все хорошо. Она говорила, что довольна тобой, поэтому не пугайся.','Поговорите с Эльталисте в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Больше, чем тень.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот мы и свиделись вновь, $n. Но пообщаться нам не удастся – Эльталисте послала весточку, велит тебе возвращаться в Подгород. Она по-прежнему в Квартале Воинов.$B$BНе беспокойся, думаю, все хорошо. Она говорила, что довольна тобой, поэтому не пугайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5707,'<NYI> Игры с Тьмой') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Игры с Тьмой',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5708,'<NYI> Заигрывание с Тьмой','Говорят, что твоя вера направляет и ободряет Отрекшихся. Похоже, Эльталисте знает что-то, сокрытое от Сильваны, или ваша Темная Госпожа требует от нее быть менее разборчивой в средствах.$b$BТебе следует вернуться в Подгород и поговорить с Эльталисте. Она, как всегда, ждет тебя в Квартале Воинов.','Поговорите с Эльталисте в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Заигрывание с Тьмой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что твоя вера направляет и ободряет Отрекшихся. Похоже, Эльталисте знает что-то, сокрытое от Сильваны, или ваша Темная Госпожа требует от нее быть менее разборчивой в средствах.$b$BТебе следует вернуться в Подгород и поговорить с Эльталисте. Она, как всегда, ждет тебя в Квартале Воинов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5709,'<NYI> Заигрывание с Тьмой','И снова настало время вернуться в Подгород, $n. Эльталисте... привязалась к некоторым жрецам-Отрекшимся и во имя защиты леди Сильваны хочет, чтобы все мы как можно лучше подготовились к грядущим испытаниям.$B$BОтправляйся к Эльталисте в Квартал Воинов и будь $gготов:готова; к любому заданию.','Поговорите с Эльталисте в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Заигрывание с Тьмой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И снова настало время вернуться в Подгород, $n. Эльталисте... привязалась к некоторым жрецам-Отрекшимся и во имя защиты леди Сильваны хочет, чтобы все мы как можно лучше подготовились к грядущим испытаниям.$B$BОтправляйся к Эльталисте в Квартал Воинов и будь $gготов:готова; к любому заданию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эльталисте в Подгороде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (5710,'<NYI> <TXT> Одеяние тролля-жреца') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT> Одеяние тролля-жреца',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5711,'<NYI> Забытый путь','Я уж и не упомню, сколько ваших тут побывало. Но вот поговорить с ними по-настоящему мне ни разу не доводилось. Учить – да, советы давать – да, но вот просто поболтать со мной никому в голову не приходит.$b$bХотя, увы, сейчас разговоры разговаривать некогда: тебе следует знать, что Ур\'кьо ждет тебя в Оргриммаре, на Аллее Духов. Ему надо с тобой поговорить.','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Забытый путь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уж и не упомню, сколько ваших тут побывало. Но вот поговорить с ними по-настоящему мне ни разу не доводилось. Учить – да, советы давать – да, но вот просто поболтать со мной никому в голову не приходит.$b$bХотя, увы, сейчас разговоры разговаривать некогда: тебе следует знать, что Ур\'кьо ждет тебя в Оргриммаре, на Аллее Духов. Ему надо с тобой поговорить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5712,'<NYI> Забытый путь','Да пребудет с тобой удача, дитя мое!$b$bПару дней тому назад в Подгород прибыли гонцы-тролли. Они рассказали, что молодые жрецы возвращаются на Аллею Духов, чтобы поговорить с Ур\'кьо. Я советую тебе разузнать больше об этом: вдруг тебя это тоже касается? Надеюсь, ты помнишь дорогу обратно в Оргриммар?','Поговорите с Ур\'кьо в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> Забытый путь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да пребудет с тобой удача, дитя мое!$b$bПару дней тому назад в Подгород прибыли гонцы-тролли. Они рассказали, что молодые жрецы возвращаются на Аллею Духов, чтобы поговорить с Ур\'кьо. Я советую тебе разузнать больше об этом: вдруг тебя это тоже касается? Надеюсь, ты помнишь дорогу обратно в Оргриммар?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ур\'кьо в Оргриммаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (5713,'Каждый выстрел – в цель','Я направлялась в Лор\'данел с важным донесением, когда меня атаковал фурболг Марош и его следопыты. Его оружие оказалось отравленным, и потому я едва держусь на ногах. Конечно, мне известен рецепт противоядия, но его изготовление займет некоторое время.$B$BМожет быть, ты защитишь меня, пока я не приму противоядие? Не волнуйся, я буду помогать тебе чем смогу.$B$BЕсли мы выживем, то смогу доставить донесение в Лор\'данел. А тебе надо будет поговорить с Ойнеей на Заставе Мейстры и сообщить ей о случившемся.','Защитите жизнь часового Айнаши, а потом поговорите с Ойнеей на Заставе Мейстры в Ясеневом лесу.','Вы принесли долгожданное известие, |3-6($c). Приятно слышать, что Айнаша жива и здорова благодаря вам. Смею надеяться, вы примете эту награду за вашу доблесть. Пусть Элуна заботится о вас и освещает ваш путь.','Вы видели Сентинел Айнашу в дороге? Она уехала с важной миссией, но еще не вернулась.','Защитить Айнашу') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каждый выстрел – в цель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я направлялась в Лор\'данел с важным донесением, когда меня атаковал фурболг Марош и его следопыты. Его оружие оказалось отравленным, и потому я едва держусь на ногах. Конечно, мне известен рецепт противоядия, но его изготовление займет некоторое время.$B$BМожет быть, ты защитишь меня, пока я не приму противоядие? Не волнуйся, я буду помогать тебе чем смогу.$B$BЕсли мы выживем, то смогу доставить донесение в Лор\'данел. А тебе надо будет поговорить с Ойнеей на Заставе Мейстры и сообщить ей о случившемся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите жизнь часового Айнаши, а потом поговорите с Ойнеей на Заставе Мейстры в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы принесли долгожданное известие, |3-6($c). Приятно слышать, что Айнаша жива и здорова благодаря вам. Смею надеяться, вы примете эту награду за вашу доблесть. Пусть Элуна заботится о вас и освещает ваш путь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы видели Сентинел Айнашу в дороге? Она уехала с важной миссией, но еще не вернулась.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитить Айнашу',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5721,'Битва при Дарроушире','Теперь, $n, тебе предстоит принять участие в битве при Дарроушире и спасти Джозефа Редпата.$B$BПоложи реликвии на городскую площадь Дарроушира, и духи его жителей восстанут из могил. Начнется битва, и ты $gдолжен:должна; сделать все возможное, чтобы Дейвил выжил в битве с Хоргусом, а Редпат должен подвергнуться порче и после этого быть убитым.$B$BВ этом случае дух Редпата будет спасен. Поговори с ним и возвращайся к его дочери Памеле.','Положите сверток с реликвиями на городской площади Дарроушира.$B$BОберегайте Дейвила Яркосвета, пока не погибнет Хоргус.$B$BНе допустите смерти капитана Редпата, пока он не превратится в Редпата Оскверненного. $B$BЗатем убейте его. $B$BПоговорите с духом Джозефа Редпата, когда он вновь появится на городской площади, затем отправляйтесь к Памеле и поговорите с ней.','Битва окончена! Я слышала, что мой папа зовет меня... Он идет домой... Это так прекрасно…$B$BОн также сказал, что я могу пригласить тебя в наш дом, и приготовить тебе чай…$B$BНадеюсь, у тебя есть с собой сахар?','Там снаружи собрались злые духи. Они шепчут мне всякие ужасы...','Вернитесь к Памеле Редпат в Дарроушир, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва при Дарроушире',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, $n, тебе предстоит принять участие в битве при Дарроушире и спасти Джозефа Редпата.$B$BПоложи реликвии на городскую площадь Дарроушира, и духи его жителей восстанут из могил. Начнется битва, и ты $gдолжен:должна; сделать все возможное, чтобы Дейвил выжил в битве с Хоргусом, а Редпат должен подвергнуться порче и после этого быть убитым.$B$BВ этом случае дух Редпата будет спасен. Поговори с ним и возвращайся к его дочери Памеле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Положите сверток с реликвиями на городской площади Дарроушира.$B$BОберегайте Дейвила Яркосвета, пока не погибнет Хоргус.$B$BНе допустите смерти капитана Редпата, пока он не превратится в Редпата Оскверненного. $B$BЗатем убейте его. $B$BПоговорите с духом Джозефа Редпата, когда он вновь появится на городской площади, затем отправляйтесь к Памеле и поговорите с ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Битва окончена! Я слышала, что мой папа зовет меня... Он идет домой... Это так прекрасно…$B$BОн также сказал, что я могу пригласить тебя в наш дом, и приготовить тебе чай…$B$BНадеюсь, у тебя есть с собой сахар?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Там снаружи собрались злые духи. Они шепчут мне всякие ужасы...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Памеле Редпат в Дарроушир, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5722,'В поисках потерянного ранца','В Огненной Пропасти Магату интересуют не только трогги. До нее дошли слухи, что один из ее слуг, некий Маур Зловещий Тотем, будучи в пропасти, нашел нечто особенное, но выбраться оттуда ему не удалось. Она хочет, чтобы кто-нибудь нашел тело Маура – если оно еще цело – и выяснил, что же он такое нашел, пытаясь вести переговоры с троггами.$B$BЕсли найдешь что-нибудь интересное, принеси это Магате, и она наверняка не поскупится на награду.$B$BДа, пропасть ищи в самых темных закоулках Оргриммара.','Обыщите Огненную Пропасть в поисках тела Маура Зловещего Тотема и найдите все необычные предметы.','Тело выглядит так, будто Маура жестоко били дубинками или кулаками, но большая часть одежды и снаряжения на месте. Похоже, троггам не сильно были нужны его пожитки.\n\nВы начинаете осматривать тело в поисках любых предметов, которые могли бы заинтересовать Магату.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках потерянного ранца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Огненной Пропасти Магату интересуют не только трогги. До нее дошли слухи, что один из ее слуг, некий Маур Зловещий Тотем, будучи в пропасти, нашел нечто особенное, но выбраться оттуда ему не удалось. Она хочет, чтобы кто-нибудь нашел тело Маура – если оно еще цело – и выяснил, что же он такое нашел, пытаясь вести переговоры с троггами.$B$BЕсли найдешь что-нибудь интересное, принеси это Магате, и она наверняка не поскупится на награду.$B$BДа, пропасть ищи в самых темных закоулках Оргриммара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите Огненную Пропасть в поисках тела Маура Зловещего Тотема и найдите все необычные предметы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тело выглядит так, будто Маура жестоко били дубинками или кулаками, но большая часть одежды и снаряжения на месте. Похоже, троггам не сильно были нужны его пожитки.\n\nВы начинаете осматривать тело в поисках любых предметов, которые могли бы заинтересовать Магату.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5723,'Испытание силы врага','Назойливые твари, известные как трогги, вдруг полезли из заполненных лавой туннелей под Оргриммаром. Магата по своей доброте душевной хотела договориться с этими тварями, но они набросились на ее переговорщиков и перебили их. Но такого обращения с тауренами она допустить не может, так что теперь для нее эти твари – враги Орды.$B$BОна просит тебя разделаться с этими троггами, прежде чем они начнут угрожать Орде из-под земли. Найди Огненную Пропасть и уничтожь их всех!','Найдите в Оргриммаре Огненную Пропасть, убейте 8 троггов и 8 шаманов Огненной Пропасти и возвращайтесь к Рахауро в Громовой Утес.','Что ж, по крайней мере, ты пока цел. А сокровище нашел?','Вернитесь к Рахауро на Вершину Старейшин Громового Утеса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание силы врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Назойливые твари, известные как трогги, вдруг полезли из заполненных лавой туннелей под Оргриммаром. Магата по своей доброте душевной хотела договориться с этими тварями, но они набросились на ее переговорщиков и перебили их. Но такого обращения с тауренами она допустить не может, так что теперь для нее эти твари – враги Орды.$B$BОна просит тебя разделаться с этими троггами, прежде чем они начнут угрожать Орде из-под земли. Найди Огненную Пропасть и уничтожь их всех!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Оргриммаре Огненную Пропасть, убейте 8 троггов и 8 шаманов Огненной Пропасти и возвращайтесь к Рахауро в Громовой Утес.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ж, по крайней мере, ты пока цел. А сокровище нашел?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рахауро на Вершину Старейшин Громового Утеса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5724,'Возвращение потерянной сумки','Под телом погибшего таурена вы находите сумку. Убитый до сих пор крепко держит ее – видимо, он пытался уберечь ее во время нападения троггов.$B$BВысвободив сумку из его крепкой хватки, вы закидываете ее себе на плечо и готовитесь возвращаться наружу из туннелей, чтобы отправиться к Рахауро в Громовой Утес.','Отнесите сумку Маура Зловещего Тотема Рахауро в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение потерянной сумки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Под телом погибшего таурена вы находите сумку. Убитый до сих пор крепко держит ее – видимо, он пытался уберечь ее во время нападения троггов.$B$BВысвободив сумку из его крепкой хватки, вы закидываете ее себе на плечо и готовитесь возвращаться наружу из туннелей, чтобы отправиться к Рахауро в Громовой Утес.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сумку Маура Зловещего Тотема Рахауро в Громовой Утес.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5725,'Силы разрушения...','Тебе хорошо известно, что в Легионе принято всячески одаривать идейных последователей. Некоторым из этих даров лучше бы оказаться в руках у Темной Госпожи, чем у... простецов.$B$BНапример, в пещерах под Оргриммаром скрывается секта Совета Теней, известная как "Пламенеющий Клинок". Госпожа сообщила, что они получили две могущественные книги заклинаний – она хотела бы "позаимствовать" их. Выполни ее волю.','Принесите книги "Заклинания Тьмы" и "Заклятия Пустоты" Вариматасу в Подгород.','Молодец, |3-6($C). Ты оказал Темной Госпоже хорошую услугу. Ее подданным пригодятся твои упорство и честолюбие. Заходи ко мне в будущем. Быть может, я отправлю тебя на новые подвиги, которые помогут Темной Госпоже свергнуть Короля-лича и освободить рабов Плети.','Меня ждет сотня дел, |3-6($C). Где книги?','Вернитесь к Вариматасу на озеро Лордамер, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы разрушения...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе хорошо известно, что в Легионе принято всячески одаривать идейных последователей. Некоторым из этих даров лучше бы оказаться в руках у Темной Госпожи, чем у... простецов.$B$BНапример, в пещерах под Оргриммаром скрывается секта Совета Теней, известная как "Пламенеющий Клинок". Госпожа сообщила, что они получили две могущественные книги заклинаний – она хотела бы "позаимствовать" их. Выполни ее волю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите книги "Заклинания Тьмы" и "Заклятия Пустоты" Вариматасу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, |3-6($C). Ты оказал Темной Госпоже хорошую услугу. Ее подданным пригодятся твои упорство и честолюбие. Заходи ко мне в будущем. Быть может, я отправлю тебя на новые подвиги, которые помогут Темной Госпоже свергнуть Короля-лича и освободить рабов Плети.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Меня ждет сотня дел, |3-6($C). Где книги?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вариматасу на озеро Лордамер, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5726,'Тайные враги','Чего я не потерплю, $n, так это предательства среди своих. Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползется еще сильнее.$b$bНо ты, $gюный искатель приключений:юная искательница приключений;, можешь проникнуть туда, куда моим агентам ходу нет. Ты можешь узнать правду... можешь обнаружить настоящего главу заговора!$b$bЕсли у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников Пылающего Клинка лейтенантский знак отличия и принеси его мне.','Принесите лейтенантский знак отличия Траллу в Оргриммар.','Вернитесь к Траллу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайные враги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чего я не потерплю, $n, так это предательства среди своих. Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползется еще сильнее.$b$bНо ты, $gюный искатель приключений:юная искательница приключений;, можешь проникнуть туда, куда моим агентам ходу нет. Ты можешь узнать правду... можешь обнаружить настоящего главу заговора!$b$bЕсли у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников Пылающего Клинка лейтенантский знак отличия и принеси его мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите лейтенантский знак отличия Траллу в Оргриммар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (5727,'Тайные враги','Ну-ка, посмотрим, стоил ли принесенный тобой знак отличия таких усилий.$b$bВ городе живет чернокнижник, который уверен, будто я ему полностью доверяю. Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель Пылающего Клинка... Однако не торопись вступать с ним в бой. Он нам еще нужен, мы можем использовать его, чтобы навредить нашим врагам.$b$bОтнеси ему этот знак отличия в Расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за $Gодного:одну; из своих. А потом возвращайся ко мне.','Отнесите лейтенантский знак отличия Ниру Огненному Клинку. Убедите его в своей преданности Пылающему Клинку. Вернитесь к Траллу в Оргриммар.','Великолепно, |3-6($C)! Просто великолепно!\n\nТвое сегодняшнее деяние – всего лишь первый шаг к куда более серьезным делам. Возможно, это поможет нам уничтожить Совет Теней раз и навсегда.\n\nПерескажи мне все, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь.','Убедить Ниру в своей преданности Пылающему Клинку','Вернитесь к Траллу в Оргриммар.','Убедить Ниру в своей преданности Пылающему Клинку') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайные враги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну-ка, посмотрим, стоил ли принесенный тобой знак отличия таких усилий.$b$bВ городе живет чернокнижник, который уверен, будто я ему полностью доверяю. Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель Пылающего Клинка... Однако не торопись вступать с ним в бой. Он нам еще нужен, мы можем использовать его, чтобы навредить нашим врагам.$b$bОтнеси ему этот знак отличия в Расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за $Gодного:одну; из своих. А потом возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите лейтенантский знак отличия Ниру Огненному Клинку. Убедите его в своей преданности Пылающему Клинку. Вернитесь к Траллу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, |3-6($C)! Просто великолепно!\n\nТвое сегодняшнее деяние – всего лишь первый шаг к куда более серьезным делам. Возможно, это поможет нам уничтожить Совет Теней раз и навсегда.\n\nПерескажи мне все, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Убедить Ниру в своей преданности Пылающему Клинку',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу в Оргриммар.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Убедить Ниру в своей преданности Пылающему Клинку',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5728,'Тайные враги','Хм, предводители Пламенеющего Клинка... Это серьезно. Если Ниру ими дорожит, значит, именно их и нужно ликвидировать. Этот сатир... Баззалан, и тот, второй, которого упоминал Ниру, – он кто, чернокнижник? – их следует убить.$b$bВозвращайся в Расселину Теней и проникни в Огненную Пропасть, $n. Разыщи этих предводителей Пламенеющего Клинка и убей их. Но будь $gосторожен:осторожна;, чтобы Ниру не узнал, что это твоих рук дело. Пусть по-прежнему считает тебя $gодним из братьев:одной из сестер; по оружию.','Убейте Баззалана и Жергоша Призывателя Духов и вернитесь в Оргриммар к Траллу.','Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!','Вернитесь к Траллу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайные враги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хм, предводители Пламенеющего Клинка... Это серьезно. Если Ниру ими дорожит, значит, именно их и нужно ликвидировать. Этот сатир... Баззалан, и тот, второй, которого упоминал Ниру, – он кто, чернокнижник? – их следует убить.$b$bВозвращайся в Расселину Теней и проникни в Огненную Пропасть, $n. Разыщи этих предводителей Пламенеющего Клинка и убей их. Но будь $gосторожен:осторожна;, чтобы Ниру не узнал, что это твоих рук дело. Пусть по-прежнему считает тебя $gодним из братьев:одной из сестер; по оружию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Баззалана и Жергоша Призывателя Духов и вернитесь в Оргриммар к Траллу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5729,'Тайные враги','Думаю, теперь тебе следует попытаться войти в число приближенных Ниру. Если он действительно так взбудоражен, как мне доносят, мы убьем сразу двух зайцев. Во-первых, тебе, возможно, удастся разузнать побольше о Совете или, по крайней мере, о Пылающем Клинке, и, во-вторых, он, возможно, начнет доверять тебе настолько, что попросит ему помогать. Ему сейчас отчаянно не хватает помощников.$b$bВозвращайся в Расселину и поговори с ним, но не особо навязывайся.','Поговорите с Ниру Огненным Клинком в Оргриммаре.','Ну в чем дело?! Ах, это ты, |3-6($C)... Прошу прощения. Я зол, как бешеный кодо... Но, возможно, я сам во всем виноват. Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами. Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов. Они оба убиты. Как это невовремя! Но тут уж ничего не поделаешь.','Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайные враги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, теперь тебе следует попытаться войти в число приближенных Ниру. Если он действительно так взбудоражен, как мне доносят, мы убьем сразу двух зайцев. Во-первых, тебе, возможно, удастся разузнать побольше о Совете или, по крайней мере, о Пылающем Клинке, и, во-вторых, он, возможно, начнет доверять тебе настолько, что попросит ему помогать. Ему сейчас отчаянно не хватает помощников.$b$bВозвращайся в Расселину и поговори с ним, но не особо навязывайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ниру Огненным Клинком в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну в чем дело?! Ах, это ты, |3-6($C)... Прошу прощения. Я зол, как бешеный кодо... Но, возможно, я сам во всем виноват. Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами. Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов. Они оба убиты. Как это невовремя! Но тут уж ничего не поделаешь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (5730,'Тайные враги','Теперь ты $gодин:одна; из моих лейтенантов! Готовься, |3-6($c). Скоро я призову тебя.$B$BМожно считать, что с Пламенеющим Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать. Я сделаю все, что смогу, чтобы свести к минимуму потери здесь, в Огненной Пропасти. А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы. Возвращайся ко мне как можно скорее.','Поговорите с Траллом в Оргриммаре.','Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайные враги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты $gодин:одна; из моих лейтенантов! Готовься, |3-6($c). Скоро я призову тебя.$B$BМожно считать, что с Пламенеющим Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать. Я сделаю все, что смогу, чтобы свести к минимуму потери здесь, в Огненной Пропасти. А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы. Возвращайся ко мне как можно скорее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Траллом в Оргриммаре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5741,'Скипетр Света','Отыщите Скипетр Света и принесите его Азору Альдаморту в башню Этель-Ретор.','Неуловимый Скипетр Света!.. Добыв его, ты избавил мир от великой угрозы. Прекрасно, |3-6($C), просто прекрасно!..','Ты нашел Скипетр Света? Он у тебя?','Вернитесь к Азору Альдаморту в Этель-Ретор, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скипетр Света',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Скипетр Света и принесите его Азору Альдаморту в башню Этель-Ретор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неуловимый Скипетр Света!.. Добыв его, ты избавил мир от великой угрозы. Прекрасно, |3-6($C), просто прекрасно!..',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел Скипетр Света? Он у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Азору Альдаморту в Этель-Ретор, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (5742,'Искупление','Ты славно $gпоработал, друг мой:поработала, подруга;. Отдохни, а я пока расскажу тебе мою историю до конца.','Выслушайте Тириона Фордринга.','Освобождение Фордринга будет непростой задачей. Ты $Gготов:готова; к ней?','Прошу, друг мой, сядь и выслушай меня.','История Тириона','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искупление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты славно $gпоработал, друг мой:поработала, подруга;. Отдохни, а я пока расскажу тебе мою историю до конца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Тириона Фордринга.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Освобождение Фордринга будет непростой задачей. Ты $Gготов:готова; к ней?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прошу, друг мой, сядь и выслушай меня.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','История Тириона',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5761,'Убить тварь','Главная задача, которую поручил мне наш великий вождь, – это извести тех тварей, которые повинны в том, что в великий город нашего владыки проникают демоны. Клан Пылающего Клинка – главная, но не единственная угроза. Есть еще и Пламенеющий Клинок, клан, который обосновался в Огненной Пропасти и втайне смущает умы простых представителей Орды.$b$bЧтобы их остановить, нужно убить их предводителя, стража Скверны по имени Тарагаман Ненасытный.$b$bУбей его. Я уверен, Вождь будет рад получить его сердце...','Спуститесь в Огненную Пропасть, убейте Тарагамана Ненасытного и принесите его сердце Ниру Огненному Клинку в Оргриммаре.','Ага! Тебе это удалось! Тралл, конечно, будет в восторге.\n\nЯ позабочусь о том, чтобы это сердце попало по назначению.\n\nНу, а ты можешь отпраздновать свою победу. Я сообщу Траллу о твоем успехе.\n\nСпасибо за помощь, |3-6($C).','Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!','Вернитесь к Ниру Огненному Клинку в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить тварь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Главная задача, которую поручил мне наш великий вождь, – это извести тех тварей, которые повинны в том, что в великий город нашего владыки проникают демоны. Клан Пылающего Клинка – главная, но не единственная угроза. Есть еще и Пламенеющий Клинок, клан, который обосновался в Огненной Пропасти и втайне смущает умы простых представителей Орды.$b$bЧтобы их остановить, нужно убить их предводителя, стража Скверны по имени Тарагаман Ненасытный.$b$bУбей его. Я уверен, Вождь будет рад получить его сердце...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спуститесь в Огненную Пропасть, убейте Тарагамана Ненасытного и принесите его сердце Ниру Огненному Клинку в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага! Тебе это удалось! Тралл, конечно, будет в восторге.\n\nЯ позабочусь о том, чтобы это сердце попало по назначению.\n\nНу, а ты можешь отпраздновать свою победу. Я сообщу Траллу о твоем успехе.\n\nСпасибо за помощь, |3-6($C).',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе убить эту тварь? Наверняка он является предводителем Пламенеющего Клинка в Огненной пропасти!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ниру Огненному Клинку в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (5762,'Хеминг Эрнестуэй-младший','У меня тут посылка для нового покупателя по имени Хеминг Эрнестуэй-младший. Посылка шла очень долго, и Хеминг давно уехал, не дождавшись ее. Говорят, что теперь он где-то в Тернистой долине, охотится там на зверей вместо отца. Перед отъездом он оставил мне немного денег, чтобы я переслал ему посылку.$B$BОн очень богатый дворф, а с такими полезно водить дружбу, правда? Так что... не желаете ли доставить Хемингу эту посылку?$B$BГоворят, он разбил лагерь в Тернистой долине, к северу от Гром\'гола.','Отнесите ящик Крейвела Хемингу Эрнестуэю-младшему в Тернистую долину.','Уж не пустынная ли это пыль у вас на воротнике?\n\nХм... Если мой нос не врет, то это не пыль, а соль! Были на Мерцающей равнине, да?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хеминг Эрнестуэй-младший',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня тут посылка для нового покупателя по имени Хеминг Эрнестуэй-младший. Посылка шла очень долго, и Хеминг давно уехал, не дождавшись ее. Говорят, что теперь он где-то в Тернистой долине, охотится там на зверей вместо отца. Перед отъездом он оставил мне немного денег, чтобы я переслал ему посылку.$B$BОн очень богатый дворф, а с такими полезно водить дружбу, правда? Так что... не желаете ли доставить Хемингу эту посылку?$B$BГоворят, он разбил лагерь в Тернистой долине, к северу от Гром\'гола.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик Крейвела Хемингу Эрнестуэю-младшему в Тернистую долину.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уж не пустынная ли это пыль у вас на воротнике?\n\nХм... Если мой нос не врет, то это не пыль, а соль! Были на Мерцающей равнине, да?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (5763,'Охота в Тернистой долине','Давным-давно пришел в эти земли дворф. Звали его Хеминг, и он хотел поохотиться на крупного зверя. С ружьем он умел обращаться просто великолепно, и много дней мы охотились с ним вместе, забыв даже о вражде, разделявшей наши народы...$B$BКогда он уходил в Тернистую долину, я поклялся, что, когда бы он ни вернулся, я встречу его как дорогого гостя. Ныне он отправился охотиться в неведомые земли, но успел воспитать сына, достойного отцовской славы.$B$BОтнеси этот рог кодо в подарок Хемингу-младшему. Ты найдешь его в Тернистой долине, к северу от лагеря Гром\'гол.','Присядь и отдохни, |3-6($C). Скоро ты снова отправишься в джунгли...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота в Тернистой долине',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно пришел в эти земли дворф. Звали его Хеминг, и он хотел поохотиться на крупного зверя. С ружьем он умел обращаться просто великолепно, и много дней мы охотились с ним вместе, забыв даже о вражде, разделявшей наши народы...$B$BКогда он уходил в Тернистую долину, я поклялся, что, когда бы он ни вернулся, я встречу его как дорогого гостя. Ныне он отправился охотиться в неведомые земли, но успел воспитать сына, достойного отцовской славы.$B$BОтнеси этот рог кодо в подарок Хемингу-младшему. Ты найдешь его в Тернистой долине, к северу от лагеря Гром\'гол.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Присядь и отдохни, |3-6($C). Скоро ты снова отправишься в джунгли...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5781,'Символ ушедших дней','Чтобы помочь Телану вернуться на путь истинный, мы должны найти то, что напомнит ему о прошлом.$b$bОдин из таких предметов – игрушка, которую я подарил ему на семилетие. Он очень дорожил этим маленьким боевым молотом, уменьшенной копией моего собственного оружия.$b$bКогда меня изгнали за предательство, его мать сказала сыну, что я погиб. Его отвели к моей пустой могиле в Крипте, и там он похоронил свой молот вместе со всеми воспоминаниями обо мне.$b$bПрошу тебя, отправляйся в Крипту и принеси молот Телана.','Отправляйтесь в Крипту – в самую южную часть Восточных Чумных земель – и добудьте молот Телана. Отнесите его Тириону Фордрингу.','<Тирион еле удерживается от слез.>$B$BЭто судьба свела нас вместе, $N. Благословение тебе!','Он должен быть спасен.','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Символ ушедших дней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы помочь Телану вернуться на путь истинный, мы должны найти то, что напомнит ему о прошлом.$b$bОдин из таких предметов – игрушка, которую я подарил ему на семилетие. Он очень дорожил этим маленьким боевым молотом, уменьшенной копией моего собственного оружия.$b$bКогда меня изгнали за предательство, его мать сказала сыну, что я погиб. Его отвели к моей пустой могиле в Крипте, и там он похоронил свой молот вместе со всеми воспоминаниями обо мне.$b$bПрошу тебя, отправляйся в Крипту и принеси молот Телана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Крипту – в самую южную часть Восточных Чумных земель – и добудьте молот Телана. Отнесите его Тириону Фордрингу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тирион еле удерживается от слез.>$B$BЭто судьба свела нас вместе, $N. Благословение тебе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он должен быть спасен.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5801,'Кузня Пламенного хребта','Чтобы выковать основу ключа тебе понадобится два ториевых слитка и мощный источник тепла. Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу.$b$bНа западе, в Кратере Ун\'Горо, есть вулкан Огненного Венца – действующий. Лава из его жерла сплавит торий и кость воедино. Твои денежки потрачены не зря – эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава.$b$bВот и все, чем я могу тебе помочь. Как доделать ключ тебе подскажет Арбингтон.','Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун\'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.$b$bОтнесите недоделанную отмычку алхимику Арбингтону на Берег Промозглого Ветра в Западные Чумные земли.','Недешево обошлась тебе эта отмычка, а? И все же работа над ней не закончена; пришло время завершающего этапа – а это самое сложное. Тебе придется выступить против того самого врага, что ждал нас в Андорале... Злобной твари, которая правит бал в стенах разрушенного города.$B$BЯ говорю об Араже Призывателе – личе, одном из самых могущественных сторонников Плети.','Тебе удалось сделать заготовку отмычки? Мне жаль, что тебе пришлось покупать форму на свои деньги, но всем приходится вносить свой вклад в борьбу с Плетью. Отдай мне заготовку отмычки, и я скажу, чего не хватает для завершения работы над ней.$B$BЭто будет нелегко, но подготовка к нападению на Андорал не пропадет втуне. Вот увидишь.','Вернитесь к алхимику Арбингтону в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кузня Пламенного хребта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы выковать основу ключа тебе понадобится два ториевых слитка и мощный источник тепла. Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу.$b$bНа западе, в Кратере Ун\'Горо, есть вулкан Огненного Венца – действующий. Лава из его жерла сплавит торий и кость воедино. Твои денежки потрачены не зря – эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава.$b$bВот и все, чем я могу тебе помочь. Как доделать ключ тебе подскажет Арбингтон.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун\'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.$b$bОтнесите недоделанную отмычку алхимику Арбингтону на Берег Промозглого Ветра в Западные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Недешево обошлась тебе эта отмычка, а? И все же работа над ней не закончена; пришло время завершающего этапа – а это самое сложное. Тебе придется выступить против того самого врага, что ждал нас в Андорале... Злобной твари, которая правит бал в стенах разрушенного города.$B$BЯ говорю об Араже Призывателе – личе, одном из самых могущественных сторонников Плети.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось сделать заготовку отмычки? Мне жаль, что тебе пришлось покупать форму на свои деньги, но всем приходится вносить свой вклад в борьбу с Плетью. Отдай мне заготовку отмычки, и я скажу, чего не хватает для завершения работы над ней.$B$BЭто будет нелегко, но подготовка к нападению на Андорал не пропадет втуне. Вот увидишь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алхимику Арбингтону в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5802,'Кузня Пламенного хребта','Чтобы выковать основу ключа тебе понадобятся два ториевых слитка и мощный источник тепла. Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу.$b$bНа западе от Кратера Ун\'Горо располагается Вулкан Огненного Венца – действующий вулкан. Лава из его жерла сплавит торий и кость воедино. Твои денежки потрачены не зря – эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава.$b$bВот и все, чем я могу тебе помочь. Как доделать ключ тебе подскажет Дитерс.','Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун\'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.$b$bОтнесите недоделанную отмычку аптекарю Дитерсу в Бастион, что в Западных Чумных землях.','Недешево обошлась тебе эта отмычка, а? И все же работа над ней не закончена, пришло время завершающего этапа – а это самое сложное. Тебе придется выступить против того самого врага, что ждал нас в Андорале... Злобной твари, которая правит бал в стенах разрушенного города.$B$BЯ говорю об Араже Призывателе – личе, одном из самых могущественных сторонников Плети.','Тебе удалось сделать заготовку отмычки? Мне жаль, что тебе пришлось покупать форму на свои деньги, но всем приходится вносить свой вклад в борьбу с Плетью. Отдай мне заготовку отмычки, и я скажу, чего не хватает для завершения работы над ней.$B$BЭто будет нелегко, но подготовка к нападению на Андорал не пропадет втуне. Вот увидишь.','Вернитесь к аптекарю Дитерсу в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кузня Пламенного хребта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы выковать основу ключа тебе понадобятся два ториевых слитка и мощный источник тепла. Торий добывай самостоятельно, а где найти подходящую плавильню, я подскажу.$b$bНа западе от Кратера Ун\'Горо располагается Вулкан Огненного Венца – действующий вулкан. Лава из его жерла сплавит торий и кость воедино. Твои денежки потрачены не зря – эту форму для отливки можно просто-напросто окунуть в огненное озеро, а остальное сделает лава.$b$bВот и все, чем я могу тебе помочь. Как доделать ключ тебе подскажет Дитерс.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите форму для отливки отмычек и 2 ториевых слитка на вершину Вулкана Огненного Венца в Кратере Ун\'Горо. Окуните форму для отливки отмычки в озеро лавы. Получится недоделанная отмычка.$b$bОтнесите недоделанную отмычку аптекарю Дитерсу в Бастион, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Недешево обошлась тебе эта отмычка, а? И все же работа над ней не закончена, пришло время завершающего этапа – а это самое сложное. Тебе придется выступить против того самого врага, что ждал нас в Андорале... Злобной твари, которая правит бал в стенах разрушенного города.$B$BЯ говорю об Араже Призывателе – личе, одном из самых могущественных сторонников Плети.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось сделать заготовку отмычки? Мне жаль, что тебе пришлось покупать форму на свои деньги, но всем приходится вносить свой вклад в борьбу с Плетью. Отдай мне заготовку отмычки, и я скажу, чего не хватает для завершения работы над ней.$B$BЭто будет нелегко, но подготовка к нападению на Андорал не пропадет втуне. Вот увидишь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Дитерсу в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (5803,'Скарабей Аража','Араж Призыватель правит Андоралом из самого сердца разрушенного города. Мы знаем, что он был главой Некроситета, пока не захватил целый город. Для завершения работы над ключом нам нужен его перстень – он называется скарабеем – из него мы создадим головку ключа.$b$bПроберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую. Убив мерзавца, забери скарабея!$b$bКлюч от Некроситета ждет тебя, $n!','Убейте Аража Призывателя отнесите его скарабея алхимику Арбингтону на Берег Промозглого Ветра, что в Западных Чумных землях.','А, вот она! Я... поражен твоей отвагой и хитростью. У меня в голове не укладывается, на что ты готов пойти ради победы над силами тьмы.$B$BПозволь и мне сыграть свою небольшую роль в твоем подвиге. Я приготовил особый раствор, который позволит мне закрепить скарабея в верзней части ключа. Его сила отомкнет двери Некроситета.$B$BНу вот, остался пустячок...','Вернитесь к алхимику Арбингтону в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скарабей Аража',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Араж Призыватель правит Андоралом из самого сердца разрушенного города. Мы знаем, что он был главой Некроситета, пока не захватил целый город. Для завершения работы над ключом нам нужен его перстень – он называется скарабеем – из него мы создадим головку ключа.$b$bПроберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую. Убив мерзавца, забери скарабея!$b$bКлюч от Некроситета ждет тебя, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Аража Призывателя отнесите его скарабея алхимику Арбингтону на Берег Промозглого Ветра, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, вот она! Я... поражен твоей отвагой и хитростью. У меня в голове не укладывается, на что ты готов пойти ради победы над силами тьмы.$B$BПозволь и мне сыграть свою небольшую роль в твоем подвиге. Я приготовил особый раствор, который позволит мне закрепить скарабея в верзней части ключа. Его сила отомкнет двери Некроситета.$B$BНу вот, остался пустячок...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к алхимику Арбингтону в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5804,'Скарабей Аража','Араж Призыватель правит Андоралом из самого сердца разрушенного города. Мы знаем, что он был главой Некроситета, пока не захватил целый город. Для завершения работы над ключом нам нужен его перстень – он называется скарабеем – из него мы создадим головку ключа.$b$bПроберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую. Убив мерзавца, забери скарабея!$b$bКлюч от Некроситета ждет тебя, $n!','Убейте Аража Призывателя и отнесите его скарабея аптекарю Дитерсу в Бастион, что в Западных Чумных землях.','А, вот она! Я... поражен твоей отвагой и хитростью. У меня в голове не укладывается, на что ты $Gготов:готова; пойти ради победы над силами тьмы.$B$BПозволь и мне сыграть свою небольшую роль в твоем подвиге. Я приготовил особый раствор, который позволит мне закрепить скарабея в верхней части ключа. Его сила отомкнет двери Некроситета.$B$BНу вот, остался пустячок...','Ты $Gсумел:сумела; далеко зайти, $N – но только уничтожение физического облика Аража Призывателя даст нам возможность завершить работу над ключом. Добудь скарабея Аража – мытьем или катаньем – и принеси мне, и я сделаю из него головку ключа.','Вернитесь к аптекарю Дитерсу в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скарабей Аража',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Араж Призыватель правит Андоралом из самого сердца разрушенного города. Мы знаем, что он был главой Некроситета, пока не захватил целый город. Для завершения работы над ключом нам нужен его перстень – он называется скарабеем – из него мы создадим головку ключа.$b$bПроберись в сердце Андорала и лиши его власти над городом, теперь, когда с ним можно сражаться в открытую. Убив мерзавца, забери скарабея!$b$bКлюч от Некроситета ждет тебя, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Аража Призывателя и отнесите его скарабея аптекарю Дитерсу в Бастион, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, вот она! Я... поражен твоей отвагой и хитростью. У меня в голове не укладывается, на что ты $Gготов:готова; пойти ради победы над силами тьмы.$B$BПозволь и мне сыграть свою небольшую роль в твоем подвиге. Я приготовил особый раствор, который позволит мне закрепить скарабея в верхней части ключа. Его сила отомкнет двери Некроситета.$B$BНу вот, остался пустячок...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсумел:сумела; далеко зайти, $N – но только уничтожение физического облика Аража Призывателя даст нам возможность завершить работу над ключом. Добудь скарабея Аража – мытьем или катаньем – и принеси мне, и я сделаю из него головку ключа.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Дитерсу в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5805,'Добро пожаловать!','Добро пожаловать в "World of Warcraft"!$B$BВ знак особой благодарности за приобретение коллекционного издания "World of Warcraft" примите этот подарочный сертификат и передайте Мериссе Стилвелл в Златоземье. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.$B$BЕще раз благодарим вас и желаем приятного пребывания в "World of Warcraft"!','Передайте подарочный сертификат Златоземья Мериссе Стилвелл.','Ну, $N, теперь приветствую тебя в мире Азерота. Иди вперед, к славе, наградам и почестям!','Приветствую! Какое удовольствие встретить тебя!$B$BЯ вижу, у тебя есть специальный купон. Отдай его мне, и я предложу кое-что взамен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в "World of Warcraft"!$B$BВ знак особой благодарности за приобретение коллекционного издания "World of Warcraft" примите этот подарочный сертификат и передайте Мериссе Стилвелл в Златоземье. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.$B$BЕще раз благодарим вас и желаем приятного пребывания в "World of Warcraft"!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте подарочный сертификат Златоземья Мериссе Стилвелл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, $N, теперь приветствую тебя в мире Азерота. Иди вперед, к славе, наградам и почестям!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую! Какое удовольствие встретить тебя!$B$BЯ вижу, у тебя есть специальный купон. Отдай его мне, и я предложу кое-что взамен.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (5821,'Наемный телохранитель','Обычно мы с Риггером проводим кодо мимо поселения кентавров из племени Колкар. Боевые барабаны кентавров слышно издалека, так что, едва заслышав их, мы останавливаемся, чтобы переждать опасность. Мертвый торговец, знаешь ли, плохой торговец!$B$BВот что я тебе скажу, |3-6($c): если ты будешь охранять нас по дороге мимо деревни Колкар, мы в долгу не останемся.$B$BРасстояние-то небольшое, да и делать почти ничего не придется – только проследить за тем, чтобы караван был цел. А награду ты получишь, не сомневайся, обращайся к Смиду Заржавеню, мы с ним обделываем кое-какие делишки. Он живет чуть дальше по дороге.','Охраняйте караван Гизлтона на пути мимо деревни кентавров из племени Колкар. О награде поговорите со Смидом в Лагере Заржавня.','Ты знаешь, не больно-то мне улыбается платить такому как ты за защиту каравана Гизлтона. Эх, |3-6($C), если бы не мои годы, если бы мои руки могли держать ружье, а в зубах – граната, то я бы показал кентаврам кто их батя...','Почему я должен ожидать?$B$B<Смид выглядит просветленным>$B$BАх, да. Они же платят по счетам.','Охраняйте караван Гизлтона на пути мимо деревни кентавров из племени Колкар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наемный телохранитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обычно мы с Риггером проводим кодо мимо поселения кентавров из племени Колкар. Боевые барабаны кентавров слышно издалека, так что, едва заслышав их, мы останавливаемся, чтобы переждать опасность. Мертвый торговец, знаешь ли, плохой торговец!$B$BВот что я тебе скажу, |3-6($c): если ты будешь охранять нас по дороге мимо деревни Колкар, мы в долгу не останемся.$B$BРасстояние-то небольшое, да и делать почти ничего не придется – только проследить за тем, чтобы караван был цел. А награду ты получишь, не сомневайся, обращайся к Смиду Заржавеню, мы с ним обделываем кое-какие делишки. Он живет чуть дальше по дороге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Охраняйте караван Гизлтона на пути мимо деревни кентавров из племени Колкар. О награде поговорите со Смидом в Лагере Заржавня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты знаешь, не больно-то мне улыбается платить такому как ты за защиту каравана Гизлтона. Эх, |3-6($C), если бы не мои годы, если бы мои руки могли держать ружье, а в зубах – граната, то я бы показал кентаврам кто их батя...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Почему я должен ожидать?$B$B<Смид выглядит просветленным>$B$BАх, да. Они же платят по счетам.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Охраняйте караван Гизлтона на пути мимо деревни кентавров из племени Колкар',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5841,'Добро пожаловать!','Добро пожаловать в World of Warcraft!$b$bВ знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Йори Шлемолому в Караносе. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.$b$bЕще раз благодарим вас и желаем приятного пребывания в World of Warcraft!','Принести Йори Шлемолому подарочный сертификат Караноса.','Ну, $N, теперь приветствую тебя в мире Азерота. Иди вперед, к славе, наградам и почестям!','Приветствую! Какое удовольствие встретить тебя!$B$BЯ вижу, у тебя есть специальный сертификат. Отдай его мне, и я тебе что-нибудь предложу взамен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в World of Warcraft!$b$bВ знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Йори Шлемолому в Караносе. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.$b$bЕще раз благодарим вас и желаем приятного пребывания в World of Warcraft!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принести Йори Шлемолому подарочный сертификат Караноса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, $N, теперь приветствую тебя в мире Азерота. Иди вперед, к славе, наградам и почестям!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую! Какое удовольствие встретить тебя!$B$BЯ вижу, у тебя есть специальный сертификат. Отдай его мне, и я тебе что-нибудь предложу взамен.',`requestitemstext_loc8`);
