INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5844,'Добро пожаловать!','Добро пожаловать в World of Warcraft!$B$BВ знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Ворну Небесному Провидцу в деревне Кровавого Копыта. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.$b$bЕще раз благодарим вас и желаем приятного пребывания в World of Warcraft!','Отнесите подарочный сертификат деревни Кровавого Копыта Ворну Небесному Провидцу.','Ну, $N, теперь приветствую тебя в мире Азерота. Иди вперед, к славе, наградам и почестям!','Приветствую! Какое удовольствие встретить тебя!$B$BЯ вижу, у тебя есть специальный купон. Отдай его мне, и я предложу кое-что взамен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в World of Warcraft!$B$BВ знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Ворну Небесному Провидцу в деревне Кровавого Копыта. Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе.$b$bЕще раз благодарим вас и желаем приятного пребывания в World of Warcraft!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите подарочный сертификат деревни Кровавого Копыта Ворну Небесному Провидцу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, $N, теперь приветствую тебя в мире Азерота. Иди вперед, к славе, наградам и почестям!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую! Какое удовольствие вс