INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5845,'Символ утраченной чести','Со смертью Утера орден Серебряной Длани утратил боевой дух.$b$bМой мальчик держался до последнего. Но, отступая в разоренную деревушку Северного Дола, он принял окончательное решение.$b$bВыжил ли кто из ордена, подумал он, да и какая разница?$b$bС этой мыслью Телан бросил знамя Серебряной Длани и отрекся от всего, что прежде было ему дорого. Его честь осталась на обагренной кровью земле Северного Дола.$b$bОтправляйся в Северный Дол и принеси мне этот символ утраченной чести.','Отправляйтесь в Северный Дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу.','Он также величественен, несмотря на разорванный вид, как и в тот день, когда я впервые взглянул на него и дал клятву служения Ордену.$B$BЕго искупление настанет, возможно, и мое вместе с ним...','Моя вера поможет тебе, $N. Свет не ведает пределов.','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Символ утраченной чести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Со смертью Утера орден Серебряной Длани утратил боевой дух.$b$bМой мальчик держался до последнего. Но, отступая в разоренную деревушку Северного Дола, он принял окончательное решение.$b$bВыжил ли кто из ордена, подумал он, да и какая разница?$b$bС этой мыслью Телан бросил знамя Серебряной Длани и отрекся от всего, что прежде было ему дорого. Его честь осталась на обагренной кровью земле Северного Дола.$b$bОтправляйся в Северный Дол и принеси мне этот символ утраченной чести.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Северный Дол, что в северо-восточной части Восточных Чумных земель и найдите там символ утраченной чести. После этого вернитесь к Тириону Фордрингу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он также величественен, несмотря на разорванный вид, как и в тот день, когда я впервые взглянул на него и дал клятву служения Ордену.$B$BЕго искупление настанет, возможно, и мое вместе с ним...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Моя вера поможет тебе, $N. Свет не ведает пределов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5846,'Символ семейной любви','Когда Телан был маленьким, мы нередко ездили в Каэр Дарроу. В последний раз художница по имени Ренфри изобразила всю нашу семью на берегу. Это лучшее мое воспоминание о Телане и Карандре. Именно тогда, стоя рядом с женой и держа на руках сына, я чувствовал глубокую связь с собственной семьей, которую мне не дано было почувствовать вновь.$b$bЕсли эта картина все еще существует, найди ее.$b$bОтправляйся на разоренный остров Каэр Дарроу и выясни, уцелела ли художница или картина.','Отправляйтесь на остров Каэр Дарроу в центральной части Чумных земель и поищите там картину.','Как я мог забыть? Здесь многие духи обречены, переживать свои самые радостные мгновения жизни, прежде чем встретили свой конец.$B$BЯ тоже обречен, но не так как остальные, я помню абсолютно все…$B$BВозможно вещь, о которой ты меня спрашиваешь, причина моего блуждания на этом острове. Возможно то, что я тебе расскажу, освободит меня от моего проклятия.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Символ семейной любви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда Телан был маленьким, мы нередко ездили в Каэр Дарроу. В последний раз художница по имени Ренфри изобразила всю нашу семью на берегу. Это лучшее мое воспоминание о Телане и Карандре. Именно тогда, стоя рядом с женой и держа на руках сына, я чувствовал глубокую связь с собственной семьей, которую мне не дано было почувствовать вновь.$b$bЕсли эта картина все еще существует, найди ее.$b$bОтправляйся на разоренный остров Каэр Дарроу и выясни, уцелела ли художница или картина.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на остров Каэр Дарроу в центральной части Чумных земель и поищите там картину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как я мог забыть? Здесь многие духи обречены, переживать свои самые радостные мгновения жизни, прежде чем встретили свой конец.$B$BЯ тоже обречен, но не так как остальные, я помню абсолютно все…$B$BВозможно вещь, о которой ты меня спрашиваешь, причина моего блуждания на этом острове. Возможно то, что я тебе расскажу, освободит меня от моего проклятия.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5847,'Добро пожаловать!','Добро пожаловать в World of Warcraft!$b$bВ качестве особой благодарности за покупку коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Клэр Вилловер в Брилле. Вас ждет подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе. $b$bЕще раз благодарим вас и желаем приятного времяпрепровождения в World of Warcraft!','Отнесите подарочный сертификат Брилла Клэр Вилловер.','Ну, $N, теперь приветствую тебя в мире Азерота. Иди вперед, к славе, наградам и почестям!','Приветствую! Какое удовольствие встретить тебя!$B$BЯ вижу, у тебя есть специальный купон. Отдай его мне, и я предложу кое-что взамен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в World of Warcraft!$b$bВ качестве особой благодарности за покупку коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Клэр Вилловер в Брилле. Вас ждет подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе. $b$bЕще раз благодарим вас и желаем приятного времяпрепровождения в World of Warcraft!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите подарочный сертификат Брилла Клэр Вилловер.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, $N, теперь приветствую тебя в мире Азерота. Иди вперед, к славе, наградам и почестям!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую! Какое удовольствие встретить тебя!$B$BЯ вижу, у тебя есть специальный купон. Отдай его мне, и я предложу кое-что взамен.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5848,'Символ семейной любви','На стене моей мастерской... В казармах ордена... долгие годы висела картина.$b$bПосле суда над Тирионом я знала, что не смогу держать ее на виду. Я спрятала ее так, чтобы никто не нашел.$b$bОтправляйся в Стратхольм и проберись в место, что ныне зовется Бастионом Алого ордена. Найди там картину с двумя лунами. Сними верхний слой краски, и увидишь мой шедевр – "Символ семейной любви".$b$bДа направит Свет твою руку.','Отправляйтесь в Стратхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину "Символ семейной любви", спрятанную за другой, изображающей две луны нашего мира.$b$bОтнесите картину Тириону Фордрингу.','<Тирион бледнеет, когда видит картину>$B$B<Он начинает судорожно всхлипывать>','Картина. Где картина?','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Символ семейной любви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На стене моей мастерской... В казармах ордена... долгие годы висела картина.$b$bПосле суда над Тирионом я знала, что не смогу держать ее на виду. Я спрятала ее так, чтобы никто не нашел.$b$bОтправляйся в Стратхольм и проберись в место, что ныне зовется Бастионом Алого ордена. Найди там картину с двумя лунами. Сними верхний слой краски, и увидишь мой шедевр – "Символ семейной любви".$b$bДа направит Свет твою руку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Стратхольм в северную часть Чумных земель. Найдите в Бастионе Алого ордена картину "Символ семейной любви", спрятанную за другой, изображающей две луны нашего мира.$b$bОтнесите картину Тириону Фордрингу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Тирион бледнеет, когда видит картину>$B$B<Он начинает судорожно всхлипывать>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Картина. Где картина?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5861,'Найти Миранду','Ты $Gсделал:сделала; все, о чем я тебя просил. Остался один, последний шаг на пути к спасению.$b$bОтнеси все собранные тобой предметы Телану. К сожалению, Телан и его крестоносцы Алого ордена нападут на тебя, едва завидев.$B$bЕсть только один способ доставить мое сообщение – приняв обличье врага.$b$bНа юге отсюда находится гробница Утера. Там живет моя старая добрая подруга, Миранда. Найди ее, покажи все собранные тобой предметы, и она тебе поможет.','Отправляйтесь к гробнице Утера, которая находится в южных Чумных землях. Покажите Миранде Колдунье подарок Тириона.','Я была самой доверенной советницей Тириона, когда он носил титул лорда Марденхольдского. Я открыто отреклась от вердикта ордена Серебряной Длани и была изгнана за неповиновение.$B$BНа долю Тириона выпало много боли и разочарований. $GГотов:Готова; ли ты исправить несправедливости, обрушившиеся на Фордрингов?','Я давно дожидалась этого дня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Миранду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gсделал:сделала; все, о чем я тебя просил. Остался один, последний шаг на пути к спасению.$b$bОтнеси все собранные тобой предметы Телану. К сожалению, Телан и его крестоносцы Алого ордена нападут на тебя, едва завидев.$B$bЕсть только один способ доставить мое сообщение – приняв обличье врага.$b$bНа юге отсюда находится гробница Утера. Там живет моя старая добрая подруга, Миранда. Найди ее, покажи все собранные тобой предметы, и она тебе поможет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к гробнице Утера, которая находится в южных Чумных землях. Покажите Миранде Колдунье подарок Тириона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я была самой доверенной советницей Тириона, когда он носил титул лорда Марденхольдского. Я открыто отреклась от вердикта ордена Серебряной Длани и была изгнана за неповиновение.$B$BНа долю Тириона выпало много боли и разочарований. $GГотов:Готова; ли ты исправить несправедливости, обрушившиеся на Фордрингов?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я давно дожидалась этого дня.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5862,'Уловка против Алого Ордена','Я, как говорится, иллюзионистка. Хотя я могу создать иллюзию, благодаря которой ты проберешься в Дольный Очаг, помни – сила моя не безгранична.$b$bЕсли ты забредешь слишком далеко, иллюзия рассеется. Заклинание требует от меня значительного количества сил и сосредоточения, и я не слишком долго смогу поддерживать его.$b$bКогда будешь $gготов:готова; – обращайся.','Поговорите с Мирандой, пусть она наложит на вас Алую иллюзию. Отправляйтесь в Дольный Очаг, покуда она действует, и отнесите подарок Тириона верховному лорду Телану Фордрингу.$b$bДольный Очаг на севере, а Таэлан должен быть внутри Крепости Марденхольд.','Что это, солдат?$B$B<Таэлан открывает коробку и начинает рассматривать содержимое.>$B$BЭтого... Этого не может быть. Но все, что ты мне $Gпоказал:показала;…$B$B<Таэлан опускается на колено, сердце у него колотится. На этот город того и гляди выплеснется ярость веков.>','Ты $Gприбыл:прибыла; нам на помощь из Длани Тира?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уловка против Алого Ордена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я, как говорится, иллюзионистка. Хотя я могу создать иллюзию, благодаря которой ты проберешься в Дольный Очаг, помни – сила моя не безгранична.$b$bЕсли ты забредешь слишком далеко, иллюзия рассеется. Заклинание требует от меня значительного количества сил и сосредоточения, и я не слишком долго смогу поддерживать его.$b$bКогда будешь $gготов:готова; – обращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мирандой, пусть она наложит на вас Алую иллюзию. Отправляйтесь в Дольный Очаг, покуда она действует, и отнесите подарок Тириона верховному лорду Телану Фордрингу.$b$bДольный Очаг на севере, а Таэлан должен быть внутри Крепости Марденхольд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это, солдат?$B$B<Таэлан открывает коробку и начинает рассматривать содержимое.>$B$BЭтого... Этого не может быть. Но все, что ты мне $Gпоказал:показала;…$B$B<Таэлан опускается на колено, сердце у него колотится. На этот город того и гляди выплеснется ярость веков.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gприбыл:прибыла; нам на помощь из Длани Тира?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5863,'Поселение Песчаного Молота','Совсем недавно в Танарисе появились огры-кочевники. Они захватили большой участок пустыни к югу отсюда и построили целую крепость. Племена поменьше бродят по пустыне, захватывая руины тролльских городов.$b$bПоселение Песчаного Молота должно пасть! Не позволим же ограм превратиться в страшную силу.$b$BИх главаря зовут Гор\'марок Опустошитель. Мне кажется, что если его устранить, это станет началом конца огров.','Анди Линн из Прибамбасска просит уничтожить поселение Песчаного Молота, убив 10 громил и 10 мародеров из клана Песчаного Молота и Гор\'марока Опустошителя.','Вернитесь к Анди Линн в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поселение Песчаного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Совсем недавно в Танарисе появились огры-кочевники. Они захватили большой участок пустыни к югу отсюда и построили целую крепость. Племена поменьше бродят по пустыне, захватывая руины тролльских городов.$b$bПоселение Песчаного Молота должно пасть! Не позволим же ограм превратиться в страшную силу.$b$BИх главаря зовут Гор\'марок Опустошитель. Мне кажется, что если его устранить, это станет началом конца огров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Анди Линн из Прибамбасска просит уничтожить поселение Песчаного Молота, убив 10 громил и 10 мародеров из клана Песчаного Молота и Гор\'марока Опустошителя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анди Линн в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5881,'Смена караула','Орда не дает нам растерять силы, и это правильно! С самой Великой Войны мы здесь, в Калимдоре, живем неплохо.$B$BЯ прошу тебя оказать мне услугу: один парень по имени Гриш Выносливый Гонец охраняет Великий подъемник в Южных Степях. Передай ему это письмо: там говорится, что один из солдат запаса скоро придет ему на смену, чтобы он мог навестить свою семью. Гриш недавно просил об этом, и он будет рад услышать эти новости.','Маггран просит вас передать письмо Гришу Выносливому Гонцу у Великого подъемника в Степи.','Это хорошие новости; я слишком долго сижу здесь, охраняя этот кусок дерева. Теперь я смогу побыть со своими родными... Ура!','У тебя какие-то новости от землепряда Магграна?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смена караула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орда не дает нам растерять силы, и это правильно! С самой Великой Войны мы здесь, в Калимдоре, живем неплохо.$B$BЯ прошу тебя оказать мне услугу: один парень по имени Гриш Выносливый Гонец охраняет Великий подъемник в Южных Степях. Передай ему это письмо: там говорится, что один из солдат запаса скоро придет ему на смену, чтобы он мог навестить свою семью. Гриш недавно просил об этом, и он будет рад услышать эти новости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Маггран просит вас передать письмо Гришу Выносливому Гонцу у Великого подъемника в Степи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это хорошие новости; я слишком долго сижу здесь, охраняя этот кусок дерева. Теперь я смогу побыть со своими родными... Ура!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя какие-то новости от землепряда Магграна?',`requestitemstext_loc8`);
