INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5892,'Припасы Железного рудника','Пока не началась война, мы хранили припасы для Дун Болдара на Железном руднике. Когда у нас были войска, чтобы охранять рудник, трогги не были такой уж большой проблемой, но сейчас мы сражаемся с Ордой и не в силах его удерживать.$B$BТем не менее, припасы с Железного рудника нам очень нужны, $n. Отправляйся туда и добудь их.','Принесите 10 припасов Железного рудника интенданту Альянса в Дун Болдар.','Отлично! Уж я найду применение этому добру. Спасибо, $N!','Что, $N, удалось раздобыть припасы? Их вечно не хватает...','Вернитесь к интенданту клана Грозовой Вершины в Дун Болдар, что в Альтеракской долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы Железного рудника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока не началась война, мы хранили припасы для Дун Болдара на Железном руднике. Когда у нас были войска, чтобы охранять рудник, трогги не были такой уж большой проблемой, но сейчас мы сражаемся с Ордой и не в силах его удерживать.$B$BТем не менее, припасы с Железного рудника нам очень нужны, $n. Отправляйся туда и добудь их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 припасов Железного рудника интенданту Альянса в Дун Болдар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Уж я найду применение этому добру. Спасибо, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что, $N, удалось раздобыть припасы? Их вечно не хватает...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту клана Грозовой Вершины в Дун Болдар, что в Альтеракской долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5893,'Припасы Ледяного Зуба','Рудник Ледяного Зуба, к северу отсюда, был идеальным местом для хранения припасов. Но сейчас, когда разгорелась война с Грозовой Вершиной, у нас не хватает солдат, чтобы его постоянно патрулировать и охранять. Так что рудник постоянно переходит из рук в руки, – то к Альянсу, то к местным подземным жителям...$B$BНо припасы нам по-прежнему нужны, $n! Ступай на рудник Ледяного Зуба и добудь их. Будь $gосторожен:осторожна; – в этом месте то и дело возникают стычки.','Доставьте 10 припасов Ледяного Зуба интенданту Орды в крепость Северного Волка.','А, вот они! Превосходно, $N! Припасы немного заплесневели – сказывается влажность воздуха в руднике – но все равно сгодятся.$B$BСпасибо тебе, $N. Ты $Gпомог:помогла; нашим войскам поддержать силы.','Ты $Gвернулся:вернулась; с рудника Ледяного Зуба? А где припасы?','Вернитесь к интенданту клана Северного Волка в Крепость Северного Волка, что в Альтеракской долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы Ледяного Зуба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рудник Ледяного Зуба, к северу отсюда, был идеальным местом для хранения припасов. Но сейчас, когда разгорелась война с Грозовой Вершиной, у нас не хватает солдат, чтобы его постоянно патрулировать и охранять. Так что рудник постоянно переходит из рук в руки, – то к Альянсу, то к местным подземным жителям...$B$BНо припасы нам по-прежнему нужны, $n! Ступай на рудник Ледяного Зуба и добудь их. Будь $gосторожен:осторожна; – в этом месте то и дело возникают стычки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте 10 припасов Ледяного Зуба интенданту Орды в крепость Северного Волка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, вот они! Превосходно, $N! Припасы немного заплесневели – сказывается влажность воздуха в руднике – но все равно сгодятся.$B$BСпасибо тебе, $N. Ты $Gпомог:помогла; нашим войскам поддержать силы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась; с рудника Ледяного Зуба? А где припасы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту клана Северного Волка в Крепость Северного Волка, что в Альтеракской долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5901,'Чума на вашу лесопилку!','Ну все, теперь у меня есть партизанский план борьбы с Алым орденом! Для начала они расплатятся за свои деяния лесопилкой. Вот они у меня попрыгают! Посмотрим, будут ли они также лихо перестраивать все в городе под свои нужды, когда я перекрою им поступления стройматериалов. Поможешь мне, $n?$B$BВозьми эту банку и отправляйся в Чумной лес, что в Восточных Чумных землях. Найди термитник и набери полную банку насекомых – уж мы натравим их на Алый орден!','Возьмите пустую банку для термитов и отправляйтесь к термитникам в Восточных Чумных землях. Наберите 100 термитов Восточных Чумных земель и возвращайтесь к Микки Левину в Бастион в Тирисфальских лесах.','Прекрасно сделано, $N. Спасибо.$B$BЕсли ты $Gготов:готова;, то перейдем к следующему шагу.','Ну как, $Gнашел:нашла; термитники, $N? Не сомневаюсь, такой умный $C справится с такой простенькой задачей!$B$BНаберем термитов и устроим диверсию на лесопилке!','Вернитесь к Микки Левин в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чума на вашу лесопилку!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну все, теперь у меня есть партизанский план борьбы с Алым орденом! Для начала они расплатятся за свои деяния лесопилкой. Вот они у меня попрыгают! Посмотрим, будут ли они также лихо перестраивать все в городе под свои нужды, когда я перекрою им поступления стройматериалов. Поможешь мне, $n?$B$BВозьми эту банку и отправляйся в Чумной лес, что в Восточных Чумных землях. Найди термитник и набери полную банку насекомых – уж мы натравим их на Алый орден!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите пустую банку для термитов и отправляйтесь к термитникам в Восточных Чумных землях. Наберите 100 термитов Восточных Чумных земель и возвращайтесь к Микки Левину в Бастион в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно сделано, $N. Спасибо.$B$BЕсли ты $Gготов:готова;, то перейдем к следующему шагу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, $Gнашел:нашла; термитники, $N? Не сомневаюсь, такой умный $C справится с такой простенькой задачей!$B$BНаберем термитов и устроим диверсию на лесопилке!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Микки Левин в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5902,'Чума на вашу лесопилку!','Теперь у нас просто прорва термитов. Я надежно запрятала их вот в этот окованный железом бочонок. Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага – сразу найдешь, если свернешь на запад с дороги, ведущей отсюда в город.$B$BКак будешь на лесопилке, поставь бочонок на какое-нибудь возвышение – например, на какой-нибудь ящик.$B$BГлавное открыть, а уж дальше термиты сами разберутся. А потом возвращайся ко мне – я придумаю, чем тебя порадовать.','Найдите подходящее место на лесопилке Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов Чумных земель.','Как только бочонок оказывается открыт, водопад термитов обрушивается из-под крышки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чума на вашу лесопилку!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь у нас просто прорва термитов. Я надежно запрятала их вот в этот окованный железом бочонок. Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага – сразу найдешь, если свернешь на запад с дороги, ведущей отсюда в город.$B$BКак будешь на лесопилке, поставь бочонок на какое-нибудь возвышение – например, на какой-нибудь ящик.$B$BГлавное открыть, а уж дальше термиты сами разберутся. А потом возвращайся ко мне – я придумаю, чем тебя порадовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите подходящее место на лесопилке Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов Чумных земель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как только бочонок оказывается открыт, водопад термитов обрушивается из-под крышки.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (5903,'Чума на вашу лесопилку!','Я долгое время пытался бороться с Алым орденом в открытую, но без толку. Теперь я подумываю прибегнуть к некоторым партизанским методам – если не можешь одержать победу, хотя бы отрави врагу существование!$B$BЕсли хочешь мне помочь, слушай мой план: я собираюсь подбросить им на лесопилку самых зловредных термитов из всех существующих.$B$BЭти твари водятся в Чумном лесу недалеко от Стратхольма – их колония пережила чуму и переродилась в новый, еще более живучий вид. Найди термитник и набери полную банку насекомых – уж мы натравим их на Алый орден!','Возьмите пустую банку для термитов и отправляйтесь к термитникам в Восточных Чумных землях. Наберите 100 термитов Чумных земель и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Западные Чумные земли.','Вернитесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чума на вашу лесопилку!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я долгое время пытался бороться с Алым орденом в открытую, но без толку. Теперь я подумываю прибегнуть к некоторым партизанским методам – если не можешь одержать победу, хотя бы отрави врагу существование!$B$BЕсли хочешь мне помочь, слушай мой план: я собираюсь подбросить им на лесопилку самых зловредных термитов из всех существующих.$B$BЭти твари водятся в Чумном лесу недалеко от Стратхольма – их колония пережила чуму и переродилась в новый, еще более живучий вид. Найди термитник и набери полную банку насекомых – уж мы натравим их на Алый орден!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите пустую банку для термитов и отправляйтесь к термитникам в Восточных Чумных землях. Наберите 100 термитов Чумных земель и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Западные Чумные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5904,'Чума на вашу лесопилку!','Теперь у нас просто прорва термитов. Я надежно запрятал их вот в этот окованный железом бочонок. Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага – сразу найдешь, если свернешь на запад с дороги, ведущей отсюда в город.$B$BКак будешь на лесопилке, поставь бочонок на какое-нибудь возвышение – например, на какой-нибудь ящик.$B$BГлавное открыть, а уж дальше термиты сами разберутся. Едва ли Алый Марш сможет впредь использовать лесопилку!','Найдите подходящее место в центре лесопилки Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов Чумных земель.','Как только бочонок оказывается открыт, водопад термитов обрушивается из-под крышки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чума на вашу лесопилку!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь у нас просто прорва термитов. Я надежно запрятал их вот в этот окованный железом бочонок. Отнеси его на лесопилку Северного Кряжа, это к югу от Дольного Очага – сразу найдешь, если свернешь на запад с дороги, ведущей отсюда в город.$B$BКак будешь на лесопилке, поставь бочонок на какое-нибудь возвышение – например, на какой-нибудь ящик.$B$BГлавное открыть, а уж дальше термиты сами разберутся. Едва ли Алый Марш сможет впредь использовать лесопилку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите подходящее место в центре лесопилки Северного Кряжа в Западных Чумных землях и оставьте там бочонок термитов Чумных земель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как только бочонок оказывается открыт, водопад термитов обрушивается из-под крышки.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5921,'Лунная поляна','На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны. Теперь, когда ты $gвстал:встала; на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им, когда тебе нужно знание или уединение Лунной поляны.$B$BВот первый урок: отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд в Ночной гавани о том пути, по которому ты ныне следуешь. Удачи тебе, $Gюный друид:юная дева-друид;.','При помощи заклинания "Телепортация: Лунная поляна" перенеситесь в Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.','"Да будет так, отец Кенарий. Да будет так."$B$BДендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы.$B$B"Первое обличье, которое тебе следует освоить, - это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути - это твоя забота! И так отныне будет всегда."','Вы прибыли из Тельдрассила? Скажите, как там ловится рыба?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лунная поляна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны. Теперь, когда ты $gвстал:встала; на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им, когда тебе нужно знание или уединение Лунной поляны.$B$BВот первый урок: отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд в Ночной гавани о том пути, по которому ты ныне следуешь. Удачи тебе, $Gюный друид:юная дева-друид;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи заклинания "Телепортация: Лунная поляна" перенеситесь в Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','"Да будет так, отец Кенарий. Да будет так."$B$BДендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы.$B$B"Первое обличье, которое тебе следует освоить, - это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути - это твоя забота! И так отныне будет всегда."',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы прибыли из Тельдрассила? Скажите, как там ловится рыба?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5922,'Лунная поляна','На священной земле Лунной поляны рады всем друидам – и тауренам, и эльфам. Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погруженными в спячку друидами. Теперь, когда ты знаешь путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им всегда, когда тебе нужно знание или уединение Лунной поляны.$B$BВот первый урок – отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд в Ночной гавани о том пути, которым ты ныне следуешь. Удачи тебе, мой юный друид.','При помощи заклинания "Телепортация: Лунная поляна" перенеситесь в Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.','<Да будет так, отец Кенарий. Да будет так.>$B$BДендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы.$B$B<Первое обличье, которое тебе следует освоить, – это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути – это твоя забота! И так отныне будет всегда.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лунная поляна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На священной земле Лунной поляны рады всем друидам – и тауренам, и эльфам. Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погруженными в спячку друидами. Теперь, когда ты знаешь путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну. Пользуйся им всегда, когда тебе нужно знание или уединение Лунной поляны.$B$BВот первый урок – отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд в Ночной гавани о том пути, которым ты ныне следуешь. Удачи тебе, мой юный друид.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи заклинания "Телепортация: Лунная поляна" перенеситесь в Лунную поляну. По прибытии поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Да будет так, отец Кенарий. Да будет так.>$B$BДендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы.$B$B<Первое обличье, которое тебе следует освоить, – это обличье медведя. Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути – это твоя забота! И так отныне будет всегда.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5923,'Голос Природы','Не уделишь мне минутку внимания?..$B$BДошло до меня, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Матренгил непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила.$B$BОн живет в Анклаве Кенария в Дарнасе, на втором уровне дерева Фэндрала Оленьего Шлема.','Поговорите с Матренгилом Медвежьей Лапой в Анклаве Кенария в Дарнасе.','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный:юная; $Gдруид:дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты $Gдолжен:должна; обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не уделишь мне минутку внимания?..$B$BДошло до меня, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Матренгил непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила.$B$BОн живет в Анклаве Кенария в Дарнасе, на втором уровне дерева Фэндрала Оленьего Шлема.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Матренгилом Медвежьей Лапой в Анклаве Кенария в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный:юная; $Gдруид:дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты $Gдолжен:должна; обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5924,'Голос Природы','Не уделишь мне минутку внимания?..$b$bДо моего сведения дошло, что Матренгил Медвежья Лапа желает пообщаться с вами. Похоже, ваше обучение искусству друида переходит на новую ступень, и он лично будет учить вас. Матренгил – правая рука самого верховного друида и один из самых мудрых и благородных друидов, каких только можно встретить в Тельдрассиле.$b$bОн обитает в Анклаве Кенария в Дарнасе, на втором ярусе дерева Фэндрала Оленьего Шлема.','Поговорите с Матренгилом Медвежьей Лапой в Анклаве Кенария в Дарнасе.','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный:юная; $Gдруид:дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты $Gдолжен:должна; обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не уделишь мне минутку внимания?..$b$bДо моего сведения дошло, что Матренгил Медвежья Лапа желает пообщаться с вами. Похоже, ваше обучение искусству друида переходит на новую ступень, и он лично будет учить вас. Матренгил – правая рука самого верховного друида и один из самых мудрых и благородных друидов, каких только можно встретить в Тельдрассиле.$b$bОн обитает в Анклаве Кенария в Дарнасе, на втором ярусе дерева Фэндрала Оленьего Шлема.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Матренгилом Медвежьей Лапой в Анклаве Кенария в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный:юная; $Gдруид:дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты $Gдолжен:должна; обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5925,'Голос Природы','Не уделишь мне минутку внимания?..$B$BМне сообщили, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Матренгил – непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила.$B$BОн живет в Анклаве Кенария в Дарнасе, на третьем уровне дерева Фэндрала Оленьего Шлема.','Поговорите с Матренгилом Медвежьей Лапой в Анклаве Кенария в Дарнасе.','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный друид:юная дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения - наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не уделишь мне минутку внимания?..$B$BМне сообщили, что Матренгил Медвежья Лапа желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Матренгил – непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила.$B$BОн живет в Анклаве Кенария в Дарнасе, на третьем уровне дерева Фэндрала Оленьего Шлема.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Матренгилом Медвежьей Лапой в Анклаве Кенария в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный друид:юная дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения - наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5926,'Голос Природы','Извини, $Gдруг:девушка;...$B$BДошло до меня, что Тюрак Рунический Тотем желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Тюрак – один из помощников самого верховного друида, он друид мудрый и терпеливый. Он сумеет хорошо обучить тебя.$B$BОн живет в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.','Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин Громового Утеса.','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный:юная; $Gдруид:дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты $Gдолжен:должна; обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Извини, $Gдруг:девушка;...$B$BДошло до меня, что Тюрак Рунический Тотем желает побеседовать с тобой. Сдается, твое друидическое обучение выходит на следующую ступень, и он лично берется тебя обучать. Тюрак – один из помощников самого верховного друида, он друид мудрый и терпеливый. Он сумеет хорошо обучить тебя.$B$BОн живет в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин Громового Утеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный:юная; $Gдруид:дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты $Gдолжен:должна; обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5927,'Голос Природы','Извини, $Gдруг:подруга;...$b$bМне стало известно, что Тюрак Рунический Тотем желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься.$b$bТы найдешь его в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.','Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный:юная; $Gдруид:дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты $Gдолжен:должна; обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Извини, $Gдруг:подруга;...$b$bМне стало известно, что Тюрак Рунический Тотем желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься.$b$bТы найдешь его в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный:юная; $Gдруид:дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты $Gдолжен:должна; обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5928,'Голос Природы','Прости меня, друг мой...$B$BМне стало известно, что Тюрак Рунический Тотем желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься.$b$bТы найдешь его в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.','Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный:юная; $Gдруид:дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты $Gдолжен:должна; обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Голос Природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прости меня, друг мой...$B$BМне стало известно, что Тюрак Рунический Тотем желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида. Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида. Он известен как мудрый и терпеливый наставник. Ты у него многому научишься.$b$bТы найдешь его в Громовом Утесе, в главном шатре Круга Кенария на Вершине Старейшин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тюраком Руническим Тотемом на Вершине Старейшин в Громовом Утесе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что ты $Gнашел:нашла; сюда дорогу, $Gюный:юная; $Gдруид:дева-друид;. Пришло тебе время вступить в большой мир.$B$BВ сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота. Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага. Чтобы сделать первый шаг в этот мир, ты $Gдолжен:должна; обучиться искусству превращения в медведя. Так ты познаешь, что такое сила тела и духа.$B$BГотовься!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (5929,'Дух Великого Медведя','В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который дает начала понимания истинной природы медведя. Всем друидам в определенный момент требуется мудрость этого существа, и ты не исключение.$B$BОтправляйся же прямо сейчас к духу Великого Медведя и познай все, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты $Gусвоил:усвоила; его уроки.','Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне.','Дендрит делает еще один неприметный жест над головой при вашем приближении. Его снова окутывает аура силы, и он еле заметно улыбается.$B$B"Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи. Во взгляде твоем сила и осознанное стремление, хотя еще и не столь оформленное. Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя."','Возвращайся только тогда, когда дух Великого Медведя отпустит тебя ко мне. Без его благословения твое обучение не может продолжаться.','Найдите духа Великого Медведя на северо-западе Лунной поляны \r\nи усвойте все, что он расскажет вам о природе медведя.','Вернитесь к Дендриту Блеску Звезд в Ночную Гавань, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух Великого Медведя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя. Для всех друидов он является наставником и учителем, который дает начала понимания истинной природы медведя. Всем друидам в определенный момент требуется мудрость этого существа, и ты не исключение.$B$BОтправляйся же прямо сейчас к духу Великого Медведя и познай все, чему он захочет тебя научить. Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты $Gусвоил:усвоила; его уроки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите духа Великого Медведя на северо-западе Лунной поляны и усвойте все, что он расскажет вам о природе медведя. Когда уроки будут закончены, вернитесь к Дендриту Блеску Звезд в Ночную Гавань в Лунной поляне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дендрит делает еще один неприметный жест над головой при вашем приближении. Его снова окутывает аура силы, и он еле заметно улыбается.$B$B"Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи. Во взгляде твоем сила и осознанное стремление, хотя еще и не столь оформленное. Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя."',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Возвращайся только тогда, когда дух Великого Медведя отпустит тебя ко мне. Без его благословения твое обучение не может продолжаться.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите духа Великого Медведя на северо-западе Лунной поляны \r\nи усвойте все, что он расскажет вам о природе медведя.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дендриту Блеску Звезд в Ночную Гавань, что на Лунной поляне.',`completedtext_loc8`);
