INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (5931,'Возвращение в Дарнас','Пришла пора нашим дорогам разойтись, дитя мое, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Матренгил Медвежья Лапа живет в истинном равновесии с природой, хотя и обитает опасно близко к тому месту, где это равновесие пошатнулось. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия.$B$BСтупай же, дитя. Мы еще встретимся.','Вернитесь в Дарнас и поговорите с Матренгилом Медвежьей Лапой в Анклаве Кенария.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Дарнас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришла пора нашим дорогам разойтись, дитя мое, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Матренгил Медвежья Лапа живет в истинном равновесии с природой, хотя и обитает опасно близко к тому месту, где это равновесие пошатнулось. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия.$B$BСтупай же, дитя. Мы еще встретимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Дарнас и поговорите с Матренгилом Медвежьей Лапой в Анклаве Кенария.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5932,'Возвращение в Громовой Утес','Пришла пора нашим дорогам разойтись, дитя мое, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Хотя таурены недавно вступили на путь Кенария, Тюрак Рунический Тотем живет в равновесии с природой. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия.$B$BСтупай же, дитя. Мы еще встретимся.','Вернитесь в Громовой Утес и поговорите с Тюраком Руническим Тотемом на Вершине Старейшин.','С возвращением, $N. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет. То же было и со мной.$B$BДух Великого Медведя был частью Азерота с самого его возникновения. Мы, Таурены, внимательно прослушиваемся его мудрости и могуществу в достижении наших целей. Теперь пришла пора тебе пройти первое свое испытание на этом пути. Слушай же...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Громовой Утес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришла пора нашим дорогам разойтись, дитя мое, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне. Хотя таурены недавно вступили на путь Кенария, Тюрак Рунический Тотем живет в равновесии с природой. Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия.$B$BСтупай же, дитя. Мы еще встретимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Громовой Утес и поговорите с Тюраком Руническим Тотемом на Вершине Старейшин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С возвращением, $N. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя... немного сбивает с толку, но впечатляет. То же было и со мной.$B$BДух Великого Медведя был частью Азерота с самого его возникновения. Мы, Таурены, внимательно прослушиваемся его мудрости и могуществу в достижении наших целей. Теперь пришла пора тебе пройти первое свое испытание на этом пути. Слушай же...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5941,'Возвращение к Хроми','Ты $gсобрал:собрала; многие реликвии, сохранившиеся со времен битвы при Дарроушире. Они взывают ко мне... умоляют изменить судьбу жителей Дарроушира.$B$BДа, звучит абсурдно, но Хроми, странный гном, живущий в Андорале, убеждает меня, что это возможно. Она говорит, ты можешь спасти Дарроушир! $B$BТы $gдолжен:должна; отнести эти реликвии ей, она ждет тебя в разрушенной таверне в Андорале.','Отнесите сумку с мощами Хроми в Андорал.','Ага, вот они какие. Вместе мы создадим мощнейшее заклятие, которое ни много, ни мало, поднимет души всех кто жил в Дарроушире!$B$BНу и с помощью удачи мы даже сможем спасти Джозефа Редпата!','Я говорила с твоим другом Карлином. Он очень хорошо о тебе отзывался. Он верит, что именно ты сможешь изменить судьбу его деревни.$B$BТы $Gпринес:принесла; мне собранные тобой реликвии?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Хроми',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсобрал:собрала; многие реликвии, сохранившиеся со времен битвы при Дарроушире. Они взывают ко мне... умоляют изменить судьбу жителей Дарроушира.$B$BДа, звучит абсурдно, но Хроми, странный гном, живущий в Андорале, убеждает меня, что это возможно. Она говорит, ты можешь спасти Дарроушир! $B$BТы $gдолжен:должна; отнести эти реликвии ей, она ждет тебя в разрушенной таверне в Андорале.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сумку с мощами Хроми в Андорал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, вот они какие. Вместе мы создадим мощнейшее заклятие, которое ни много, ни мало, поднимет души всех кто жил в Дарроушире!$B$BНу и с помощью удачи мы даже сможем спасти Джозефа Редпата!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я говорила с твоим другом Карлином. Он очень хорошо о тебе отзывался. Он верит, что именно ты сможешь изменить судьбу его деревни.$B$BТы $Gпринес:принесла; мне собранные тобой реликвии?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (5942,'Спрятанные сокровища','Папа велел отдать тебе этот ключ. Он открывает сундук, который стоит во дворе за домом.$B$BА еще он просил поблагодарить тебя. Не знаю, правда, за что – может, он знает, что ты $gнашел:нашла; мою куклу?$B$BВот и ключ. Спасибо тебе, $n, ты $gхороший:хорошая;!','Откройте сундук Джозефа ключом Джозефа.','Ключ хорошо подходит к замку и сундук открывается…','Сундук стар и покрыт грязью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спрятанные сокровища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Папа велел отдать тебе этот ключ. Он открывает сундук, который стоит во дворе за домом.$B$BА еще он просил поблагодарить тебя. Не знаю, правда, за что – может, он знает, что ты $gнашел:нашла; мою куклу?$B$BВот и ключ. Спасибо тебе, $n, ты $gхороший:хорошая;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте сундук Джозефа ключом Джозефа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ключ хорошо подходит к замку и сундук открывается…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сундук стар и покрыт грязью.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (5943,'Караван Гизлтона','Вид-то у тебя надежный, |3-6($r). Подзаработать хочешь? Мы с Корком думали, что на этом караване срубим кучу денег – но оказалось, что новое предприятие сулит гораздо больше неприятностей и опасностей, чем мы полагали.$B$BТам, впереди, находится Поле Маннорок... Обычно демоны не обращают на нас внимания, но на этот раз что-то изрядно напугало кодо. Я хорошо заплачу тебе за охрану каравана. Если нам удастся миновать Поле Маннорок без проблем, ты сможешь получить награду у Смида: это наш деловой партнер в Лагере Заржавня.','Проводите караван Гизлтона через Поле Маннорок. О награде поговорите со Смидом: его можно найти в Лагере Заржавня.','Ты это... не ожидай, что мы тебе много заплатим за проводку каравана Гизлтона... Корком и Риггереле – кое как зарабатывают один золотой в неделю, так что $Gсам:сама; понимаешь...','Знаешь, если караван исчезнет, то я пропаду! Ты не несешь плохие новости?$B$B<Смид вытирает пот со лба>$B$BСпасибо богине жадности!','Проводите караван Гизлтона через Поле Маннорок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Караван Гизлтона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вид-то у тебя надежный, |3-6($r). Подзаработать хочешь? Мы с Корком думали, что на этом караване срубим кучу денег – но оказалось, что новое предприятие сулит гораздо больше неприятностей и опасностей, чем мы полагали.$B$BТам, впереди, находится Поле Маннорок... Обычно демоны не обращают на нас внимания, но на этот раз что-то изрядно напугало кодо. Я хорошо заплачу тебе за охрану каравана. Если нам удастся миновать Поле Маннорок без проблем, ты сможешь получить награду у Смида: это наш деловой партнер в Лагере Заржавня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите караван Гизлтона через Поле Маннорок. О награде поговорите со Смидом: его можно найти в Лагере Заржавня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты это... не ожидай, что мы тебе много заплатим за проводку каравана Гизлтона... Корком и Риггереле – кое как зарабатывают один золотой в неделю, так что $Gсам:сама; понимаешь...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаешь, если караван исчезнет, то я пропаду! Ты не несешь плохие новости?$B$B<Смид вытирает пот со лба>$B$BСпасибо богине жадности!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводите караван Гизлтона через Поле Маннорок.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (5944,'Во сне','Как же долго я был марионеткой верховного рыцаря. И что было проку сражаться с Алым орденом? Прошли десятки лет с мнимой смерти отца, но я жил лишь воспоминаниями о нем.$b$bМне снилось, что мы с отцом снова вместе. Он стоит рядом, с гордостью глядя, как меня принимают в орден. Мы бьемся с Плетью плечо к плечу, принося славу Альянсу и Лордерону.$b$bНе желаю больше жить во сне.$b$bОтведи меня к отцу.','Выведите Телана Фордринга из Дольного Очага.','Убийство моего сына не пройдет этим чудовищам даром. Пусть нас утешит мысль о возрождении Ордена.$B$BЯ встану во главе обновленного Ордена Серебряной Длани.$B$BВ знак своей признательности я могу отдать тебе лишь эти вещи, символы моего прошлого. Прими их, они служили мне верой и правдой долгие годы.$B$BДа встретимся мы в лучшие дни и вспомним давнее прошлое... трудные битвы... пробуждение от сна.','<Тирион восстанавливает самообладание.>','Искупление?','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во сне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как же долго я был марионеткой верховного рыцаря. И что было проку сражаться с Алым орденом? Прошли десятки лет с мнимой смерти отца, но я жил лишь воспоминаниями о нем.$b$bМне снилось, что мы с отцом снова вместе. Он стоит рядом, с гордостью глядя, как меня принимают в орден. Мы бьемся с Плетью плечо к плечу, принося славу Альянсу и Лордерону.$b$bНе желаю больше жить во сне.$b$bОтведи меня к отцу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выведите Телана Фордринга из Дольного Очага.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Убийство моего сына не пройдет этим чудовищам даром. Пусть нас утешит мысль о возрождении Ордена.$B$BЯ встану во главе обновленного Ордена Серебряной Длани.$B$BВ знак своей признательности я могу отдать тебе лишь эти вещи, символы моего прошлого. Прими их, они служили мне верой и правдой долгие годы.$B$BДа встретимся мы в лучшие дни и вспомним давнее прошлое... трудные битвы... пробуждение от сна.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Тирион восстанавливает самообладание.>',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Искупление?',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тириону Фордрингу к реке Тондрорил, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (5961,'Защитник королевы банши','Приятно видеть, что в наши ряды вступают закаленные бойцы. С каждым днем нас становится все больше. Ты $gготов:готова; испытать собственную решимость, |3-6($c)?$b$bПервый среди моих защитников – Натанос по прозвищу Гнилостень. Немногие могут превзойти его в преданности и доблести.$b$bОтыщи его в Восточных Чумных землях. Он живет в Поместье Маррисов и порой бродит по окружающим его пустошам, истребляя всякую мразь из воинств Плети и Альянса.','Поговорите с Натаносом Гнилостнем в Восточных Чумных землях. Он живет в Поместье Маррисов.','Темная Госпожа считает тебя достойным встретиться с ее защитником. Ты ведь прислан кормить моих псов, да? Иначе зачем ты меня тревожишь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитник королевы банши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приятно видеть, что в наши ряды вступают закаленные бойцы. С каждым днем нас становится все больше. Ты $gготов:готова; испытать собственную решимость, |3-6($c)?$b$bПервый среди моих защитников – Натанос по прозвищу Гнилостень. Немногие могут превзойти его в преданности и доблести.$b$bОтыщи его в Восточных Чумных землях. Он живет в Поместье Маррисов и порой бродит по окружающим его пустошам, истребляя всякую мразь из воинств Плети и Альянса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Натаносом Гнилостнем в Восточных Чумных землях. Он живет в Поместье Маррисов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Темная Госпожа считает тебя достойным встретиться с ее защитником. Ты ведь прислан кормить моих псов, да? Иначе зачем ты меня тревожишь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (5981,'Истребление великанов','Около четырех тысяч лет назад Тиранда Шелест Ветра спасла жизнь королевы ледопардов, вырвав ее из рук жестоких великанов. С тех самых пор ледопарды стали союзниками ночных эльфов. $b$bТе самые великаны, что когда-то представляли опасность для ледопардов, и поныне живут не очень далеко отсюда. Их называют кланом Ледяного Молота, и они обосновались в большой долине к югу отсюда.$b$bДокажите вашу лояльность – убейте этих великанов во имя королевы ледопардов, Ши-Ротам!','По просьбе Риверна Холодного Ветра убейте 4 великанов и 4 оберегателей ледяного молота.','Отлично, $N. Ваша решимость была должным образом отмечена.','Ты $Gдолжен:должна; продолжать проявлять себя, $N.','Вернитесь к Риверну Холодному Ветру на Уступ Ледопардов, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление великанов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Около четырех тысяч лет назад Тиранда Шелест Ветра спасла жизнь королевы ледопардов, вырвав ее из рук жестоких великанов. С тех самых пор ледопарды стали союзниками ночных эльфов. $b$bТе самые великаны, что когда-то представляли опасность для ледопардов, и поныне живут не очень далеко отсюда. Их называют кланом Ледяного Молота, и они обосновались в большой долине к югу отсюда.$b$bДокажите вашу лояльность – убейте этих великанов во имя королевы ледопардов, Ши-Ротам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Риверна Холодного Ветра убейте 4 великанов и 4 оберегателей ледяного молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N. Ваша решимость была должным образом отмечена.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдолжен:должна; продолжать проявлять себя, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риверну Холодному Ветру на Уступ Ледопардов, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6001,'Тело и дух','Прямо к востоку от Аубердина находятся пещеры лунных совухов. В той, что ближе всего к Аубердину, находится камень лунного совуха. Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, которой ты, как $gодин:одна; из друидов-медведей, должен овладеть.$B$BТы $Gзаслужил:заслужила; право пользоваться этой лунной пылью Кенария, $n... теперь покажи мне, что также $gзаслужил:заслужила; право обладать силами тела и духа, необходимыми друиду!','Посыпьте лунной пылью Кенария Камень лунного совуха в Аубердине, чтобы вызвать Лунокогтя. Победите Лунокогтя, чтобы получить силу его тела и духа.$B$BЗатем поговорите с Матренгилом Медвежьей Лапой в Дарнасе.','Пока ты не ответишь на вставший перед тобой вызов, ты не сумеешь полностью познать силу духа и тела. До тех пор я ничем не смогу тебе помочь.','Поборите Лунокогтя, чтобы заслужить его силу духа и тела','Вернитесь к Матренгилу Медвежьей Лапе в Анклав Кенария, что в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тело и дух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прямо к востоку от Аубердина находятся пещеры лунных совухов. В той, что ближе всего к Аубердину, находится камень лунного совуха. Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, которой ты, как $gодин:одна; из друидов-медведей, должен овладеть.$B$BТы $Gзаслужил:заслужила; право пользоваться этой лунной пылью Кенария, $n... теперь покажи мне, что также $gзаслужил:заслужила; право обладать силами тела и духа, необходимыми друиду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посыпьте лунной пылью Кенария Камень лунного совуха в Аубердине, чтобы вызвать Лунокогтя. Победите Лунокогтя, чтобы получить силу его тела и духа.$B$BЗатем поговорите с Матренгилом Медвежьей Лапой в Дарнасе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пока ты не ответишь на вставший перед тобой вызов, ты не сумеешь полностью познать силу духа и тела. До тех пор я ничем не смогу тебе помочь.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поборите Лунокогтя, чтобы заслужить его силу духа и тела',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матренгилу Медвежьей Лапе в Анклав Кенария, что в Дарнасе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6002,'Тело и дух','Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха. Лунные совухи – звери особые, в здешних краях они не живут. Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, который ты $Gдолжен:должна; овладеть, как $Gодин:одна; из друидов-медведей.$B$BТы $Gзаслужил:заслужила; право пользоваться этой лунной пылью Кенария, $n... теперь покажи мне, что также $Gзаслужил:заслужила; право обладать силой тела и духа, необходимыми друиду!','Посыпьте лунной пылью Кенария Камень Лунного совуха, что между Мулгором и Степями, чтобы вызвать Лунокогтя. Теперь вам надо побороть Лунокогтя, чтобы заслужить его силу духа и тела.$B$BКогда выполните это, поговорите с Тюраком Руническим Тотемом в Громовом Утесе.','Пока ты не ответишь на вставший перед тобой вызов, ты не сумеешь полностью познать силу духа и тела. До тех пор я ничем не смогу тебе помочь.','Поборите Лунокогтя, чтобы заслужить его силу духа и тела','Вернитесь к Тюраку Руническому Тотему в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тело и дух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха. Лунные совухи – звери особые, в здешних краях они не живут. Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария. Лунокоготь таит в себе силу, который ты $Gдолжен:должна; овладеть, как $Gодин:одна; из друидов-медведей.$B$BТы $Gзаслужил:заслужила; право пользоваться этой лунной пылью Кенария, $n... теперь покажи мне, что также $Gзаслужил:заслужила; право обладать силой тела и духа, необходимыми друиду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посыпьте лунной пылью Кенария Камень Лунного совуха, что между Мулгором и Степями, чтобы вызвать Лунокогтя. Теперь вам надо побороть Лунокогтя, чтобы заслужить его силу духа и тела.$B$BКогда выполните это, поговорите с Тюраком Руническим Тотемом в Громовом Утесе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пока ты не ответишь на вставший перед тобой вызов, ты не сумеешь полностью познать силу духа и тела. До тех пор я ничем не смогу тебе помочь.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поборите Лунокогтя, чтобы заслужить его силу духа и тела',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тюраку Руническому Тотему в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (6003,'<nyi> <txt>Зеленый от зависти') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<nyi> <txt>Зеленый от зависти',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6004,'Неоконченное дело','У меня была разведывательная миссия – немного сократить число противников и оценить укрепления Дольного Очага. Некоторые сторонники Альянса считают, что этот город имеет не только историческое значение. Не мое дело решать, что важнее, но выполнять задание я не в силах, пока не отдохну.$b$bЕсли хочешь, я неплохо заплачу тебе за помощь. Начни на юге, возле лагеря Алого Ордена, у небольшого бастиона. Если ты окажешься достаточно $gсилен:сильна;, я попрошу тебя помочь мне выполнить основную часть задания.','Убейте 2 медиков, 2 охотников, 2 волхвов и 2 рыцарей Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.','$GМолодец:Умница;, $N. Как тебе удалось так быстро с ними разобраться? Спасибо. Мне пока не встречался никто, кто одобрил бы Алый орден или его методы. Я верю в Свет, также как и все жители Штормграда, но эти фанатики наглядно доказали, что стремятся лишь убивать всех, кроме своих сторонников... даже ни в чем не повинных людей.','Как успехи? Враг оказался сильнее, чем ты думал? Надеюсь, что нет. Мое следующее задание потребует гораздо больше сил, чем это.','Вернитесь к Кристе Чернотени в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неоконченное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня была разведывательная миссия – немного сократить число противников и оценить укрепления Дольного Очага. Некоторые сторонники Альянса считают, что этот город имеет не только историческое значение. Не мое дело решать, что важнее, но выполнять задание я не в силах, пока не отдохну.$b$bЕсли хочешь, я неплохо заплачу тебе за помощь. Начни на юге, возле лагеря Алого Ордена, у небольшого бастиона. Если ты окажешься достаточно $gсилен:сильна;, я попрошу тебя помочь мне выполнить основную часть задания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 2 медиков, 2 охотников, 2 волхвов и 2 рыцарей Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N. Как тебе удалось так быстро с ними разобраться? Спасибо. Мне пока не встречался никто, кто одобрил бы Алый орден или его методы. Я верю в Свет, также как и все жители Штормграда, но эти фанатики наглядно доказали, что стремятся лишь убивать всех, кроме своих сторонников... даже ни в чем не повинных людей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как успехи? Враг оказался сильнее, чем ты думал? Надеюсь, что нет. Мое следующее задание потребует гораздо больше сил, чем это.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кристе Чернотени в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6021,'Зельдарр Изгой','Кто бы мог подумать, после всех наших заключений в Чумных землях нам не хватало только воров! И не просто воров, а троллей!$B$BИ не просто воров-троллей, а мертвых воров-троллей!$B$BИх главарь – огромный мертвый тролль по имени Зельдарр Изгой. Они являются по ночам, крадут тела из ямы и тащат их в свое мерзкое логово. Оно зовется Крипта, это к западу отсюда.$B$BОтправляйся туда, $n, и разберись с Зельдарром. Я сыт по горло его проделками!','Принесите голову Зельдарра Управляющему Алену в Часовню Последней Надежды.','Вернитесь к управляющему Алену в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зельдарр Изгой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто бы мог подумать, после всех наших заключений в Чумных землях нам не хватало только воров! И не просто воров, а троллей!$B$BИ не просто воров-троллей, а мертвых воров-троллей!$B$BИх главарь – огромный мертвый тролль по имени Зельдарр Изгой. Они являются по ночам, крадут тела из ямы и тащат их в свое мерзкое логово. Оно зовется Крипта, это к западу отсюда.$B$BОтправляйся туда, $n, и разберись с Зельдарром. Я сыт по горло его проделками!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Зельдарра Управляющему Алену в Часовню Последней Надежды.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к управляющему Алену в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6022,'Убийство во благо','Будь $gготов:готова; на умышленное убийство, если хочешь со мной работать.$B$BДля начала покорми моих псов.$B$BВозьми эту ступку и пестик и отправляйся в Перекресток Корина. Там у тебя будет обширный выбор тварей Плети – убей тех, какие больше приглянутся. Из их свежих туш добудь живую гниль, растолки в ступке и дай отстояться, чтобы она сгустилась. Принесешь сгущенную гниль мне.$B$BИ слушай меня, недотепа, живая гниль – продукт скоропортящийся! Поэтому работать придется быстро.','Отправляйтесь на восток в Перекресток Корина и убейте несколько населяющих его созданий Плети. Соберите 7 кусков живой гнили менее чем за 10 минут. С помощью ступки и пестика превратите живую гниль в сгущенную гниль.','Я разочарован. Я надеялся скормить моим псам тебя.$B$B<Натанос вздыхает>$B$BНу, хоть что-то им поесть достанется.','Что нюни $Gраспустил:распустила;? Если эта работенка не по тебе, отправляйся обратно к Темной Госпоже и сообщи ей, как дурно я с тобой обошелся.$B$BПроваливай!','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убийство во благо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Будь $gготов:готова; на умышленное убийство, если хочешь со мной работать.$B$BДля начала покорми моих псов.$B$BВозьми эту ступку и пестик и отправляйся в Перекресток Корина. Там у тебя будет обширный выбор тварей Плети – убей тех, какие больше приглянутся. Из их свежих туш добудь живую гниль, растолки в ступке и дай отстояться, чтобы она сгустилась. Принесешь сгущенную гниль мне.$B$BИ слушай меня, недотепа, живая гниль – продукт скоропортящийся! Поэтому работать придется быстро.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на восток в Перекресток Корина и убейте несколько населяющих его созданий Плети. Соберите 7 кусков живой гнили менее чем за 10 минут. С помощью ступки и пестика превратите живую гниль в сгущенную гниль.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я разочарован. Я надеялся скормить моим псам тебя.$B$B<Натанос вздыхает>$B$BНу, хоть что-то им поесть достанется.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что нюни $Gраспустил:распустила;? Если эта работенка не по тебе, отправляйся обратно к Темной Госпоже и сообщи ей, как дурно я с тобой обошелся.$B$BПроваливай!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6023,'Неоконченное дело','Подлинная суть моей миссии состояла в том, чтобы подорвать мощь внешних отрядов Алого ордена, а потом проникнуть внутрь Дольного Очага и оценить их основные силы. Я пока не в форме, но, может быть, могу снова попросить о помощи? Судя по собранным сведениям, за пределами города костяк сил ордена составляют двое: охотник Радли и кавалер Алого ордена Дарген. Убей их, и дело стронется с мертвой точки. Они должны быть неподалеку от прохода, рядом с городом.','Убейте охотника Радли и кавалера Алого ордена Даргена и вернитесь к Кристе Чернотени в Западные Чумные земли.','Спасибо, $N. Я и не рассчитывала на такую помощь. Кажется, самый воздух этих земель лишает меня воли. Я очень устала и чем дольше здесь нахожусь, тем мне хуже. Не представляю, как я проберусь в Дольный Очаг, чтобы выяснить размер армии Алого ордена. Но это другой разговор. Погоди, возьми это... в уплату. Спасибо еще раз.','Тебе уже удалось их найти, $N? Если мы избавимся от этих двоих, я смогу пробраться в Дольный Очаг, посмотреть, что к чему. Без твоей помощи мне не обойтись. Пожалуйста, найди мне Рэдли и Даргена.','Вернитесь к Кристе Чернотени в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неоконченное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подлинная суть моей миссии состояла в том, чтобы подорвать мощь внешних отрядов Алого ордена, а потом проникнуть внутрь Дольного Очага и оценить их основные силы. Я пока не в форме, но, может быть, могу снова попросить о помощи? Судя по собранным сведениям, за пределами города костяк сил ордена составляют двое: охотник Радли и кавалер Алого ордена Дарген. Убей их, и дело стронется с мертвой точки. Они должны быть неподалеку от прохода, рядом с городом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте охотника Радли и кавалера Алого ордена Даргена и вернитесь к Кристе Чернотени в Западные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Я и не рассчитывала на такую помощь. Кажется, самый воздух этих земель лишает меня воли. Я очень устала и чем дольше здесь нахожусь, тем мне хуже. Не представляю, как я проберусь в Дольный Очаг, чтобы выяснить размер армии Алого ордена. Но это другой разговор. Погоди, возьми это... в уплату. Спасибо еще раз.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе уже удалось их найти, $N? Если мы избавимся от этих двоих, я смогу пробраться в Дольный Очаг, посмотреть, что к чему. Без твоей помощи мне не обойтись. Пожалуйста, найди мне Рэдли и Даргена.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кристе Чернотени в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6024,'Мольба Хамейи','Убей меня. Пока не поздно!$B$BМеня зовут Хамейя. Мы с собратьями путешествовали через Зул\'Машар и, видимо, съели что-то не то. Мы заражены!$B$BЯ слышу, как лич нашептывает мне, что я должен отправиться в Зул\'Машар и постараться распространить заразу. Я не могу противиться его словам, поэтому написал это послание прежде, чем разум окончательно оставит меня.$B$BЯ закопал сундук с сокровищами рядом повозкой, оставленной за этим склепом, но его можно открыть только моим ключом. Ключ у меня.$B$BЧтобы добыть сокровище, убей меня. Пока не поздно!','Убейте секретного агента Хамейю. С помощью ключа извлеките сокровище из кучи грязи за Криптой.','Сундук Хамейя открыт!!','Сундук надежно заперт.','Вернитесь к куче грязи во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мольба Хамейи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Убей меня. Пока не поздно!$B$BМеня зовут Хамейя. Мы с собратьями путешествовали через Зул\'Машар и, видимо, съели что-то не то. Мы заражены!$B$BЯ слышу, как лич нашептывает мне, что я должен отправиться в Зул\'Машар и постараться распространить заразу. Я не могу противиться его словам, поэтому написал это послание прежде, чем разум окончательно оставит меня.$B$BЯ закопал сундук с сокровищами рядом повозкой, оставленной за этим склепом, но его можно открыть только моим ключом. Ключ у меня.$B$BЧтобы добыть сокровище, убей меня. Пока не поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте секретного агента Хамейю. С помощью ключа извлеките сокровище из кучи грязи за Криптой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сундук Хамейя открыт!!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сундук надежно заперт.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к куче грязи во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6025,'Неоконченное дело','Что? Правда? Ты $gготов:готова; меня выслушать? Но ты и так очень много для меня $gсделал:сделала;, $n. Я не могу просить тебя отправиться в Дольный Очаг.$b$bТы серьезно? Дольный Очаг гораздо опаснее прохода... Я не смогу защитить тебя или даже рассказать, что тебя может ждать там.$b$bЕсли ты в самом деле хочешь мне помочь, то проникни в город и поднимись там на какое-нибудь высокое место, чтобы осмотреть его с высоты. Оцени количество войск и доложи мне. Но будь $gосторожен:осторожна;...','Проберитесь в Дольный Очаг и найдите возвышенность, с которой открывается вид на весь город. Оцените силы Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.','$GМолодец:Умница;, $N! Спасибо!$B$BЯ вернусь к Эллингу... точнее, в Штормград как только смогу. Возьми эту скромную сумму, должна же я тебя отблагодарить. Твой народ может тобой гордиться, $N. Спасибо и удачи.','Это опасное задание, $N. Я завидую твоей храбрости.','Осмотреть Дольный Очаг с высоты','Вернитесь к Кристе Чернотени в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неоконченное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что? Правда? Ты $gготов:готова; меня выслушать? Но ты и так очень много для меня $gсделал:сделала;, $n. Я не могу просить тебя отправиться в Дольный Очаг.$b$bТы серьезно? Дольный Очаг гораздо опаснее прохода... Я не смогу защитить тебя или даже рассказать, что тебя может ждать там.$b$bЕсли ты в самом деле хочешь мне помочь, то проникни в город и поднимись там на какое-нибудь высокое место, чтобы осмотреть его с высоты. Оцени количество войск и доложи мне. Но будь $gосторожен:осторожна;...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проберитесь в Дольный Очаг и найдите возвышенность, с которой открывается вид на весь город. Оцените силы Алого ордена и вернитесь к Кристе Чернотени в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N! Спасибо!$B$BЯ вернусь к Эллингу... точнее, в Штормград как только смогу. Возьми эту скромную сумму, должна же я тебя отблагодарить. Твой народ может тобой гордиться, $N. Спасибо и удачи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это опасное задание, $N. Я завидую твоей храбрости.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Осмотреть Дольный Очаг с высоты',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кристе Чернотени в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6026,'Работу пополам','Серебряный Рассвет поручил старине Дымку кой-какую работенку. А я что, я токмо рад – денежка-то никогда не лишняя!$B$BОднако силы мои уже не те, и я бы, пожалуй, воспользовался твоей помощью, если ты тоже не прочь подзаработать. Я пойду в Чумной лес и отмечу знаком строения, которые предстоит взорвать, а ты пока добудешь взрывчатки. Договорились? Жди меня на этом самом месте, как соберешь все необходимое. Ну, что скажешь?','Принесите 2 ториевых слитка, 1 золотой жезл, 8 фугасных бомб и 8 нестабильных пусковых устройств Дымку ЛаРу.$B$BДля этого вам придется найти кузнеца и инженера.','Вернитесь к Дымку Лару в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работу пополам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Серебряный Рассвет поручил старине Дымку кой-какую работенку. А я что, я токмо рад – денежка-то никогда не лишняя!$B$BОднако силы мои уже не те, и я бы, пожалуй, воспользовался твоей помощью, если ты тоже не прочь подзаработать. Я пойду в Чумной лес и отмечу знаком строения, которые предстоит взорвать, а ты пока добудешь взрывчатки. Договорились? Жди меня на этом самом месте, как соберешь все необходимое. Ну, что скажешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 ториевых слитка, 1 золотой жезл, 8 фугасных бомб и 8 нестабильных пусковых устройств Дымку ЛаРу.$B$BДля этого вам придется найти кузнеца и инженера.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дымку Лару в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (6027,'Книга Древних','Послушай меня, $n: я вручаю тебе Самоцвет Змеи. Его нужно поместить на руку Статуи Змеи, что на острове Раназжар: это небольшой островок к северо-западу отсюда. Когда сделаешь это, явится тот, кто хранит Книгу Древних. В книге можно найти вековые тайны наг. Принеси мне эту книгу: вместе мы сумеем узнать многое о наших чешуйчатых врагах!','Отыщите Книгу Древних и принесите ее Азору Альдаморту в башню Этель-Ретор.','Утраченная Книга Древних! Я прослежу за тем, чтобы она была передана высокому совету. Сегодня ты свершил великое деяние; прими же благодарность за этот подвиг!','Вернитесь к Азору Альдаморту в Этель-Ретор, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Книга Древних',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай меня, $n: я вручаю тебе Самоцвет Змеи. Его нужно поместить на руку Статуи Змеи, что на острове Раназжар: это небольшой островок к северо-западу отсюда. Когда сделаешь это, явится тот, кто хранит Книгу Древних. В книге можно найти вековые тайны наг. Принеси мне эту книгу: вместе мы сумеем узнать многое о наших чешуйчатых врагах!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Книгу Древних и принесите ее Азору Альдаморту в башню Этель-Ретор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Утраченная Книга Древних! Я прослежу за тем, чтобы она была передана высокому совету. Сегодня ты свершил великое деяние; прими же благодарность за этот подвиг!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Азору Альдаморту в Этель-Ретор, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6028,'Донесение из Круговзора','Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему. Я здесь как представитель интересов Серебряного Рассвета по управлению Круговзором. Я должен доложить обстановку офицеру Чистосердой в Лагерь Промозглого Ветра, расположенный на южной окраине Западных Чумных земель.$B$BЕсли мне это удастся, это будет прекрасный повод представить тебя моей начальнице и, возможно, устроить тебе персональное задание!','Доставьте донесение из Круговзора офицеру Чистосердой из ордена Серебряного Рассвета в Лагерь Промозглого Ветра в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение из Круговзора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему. Я здесь как представитель интересов Серебряного Рассвета по управлению Круговзором. Я должен доложить обстановку офицеру Чистосердой в Лагерь Промозглого Ветра, расположенный на южной окраине Западных Чумных земель.$B$BЕсли мне это удастся, это будет прекрасный повод представить тебя моей начальнице и, возможно, устроить тебе персональное задание!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте донесение из Круговзора офицеру Чистосердой из ордена Серебряного Рассвета в Лагерь Промозглого Ветра в Западных Чумных землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (6028,'Greetings, $C. On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Chillwind Camp. I might also have some work for you...') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Greetings, $C. On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Chillwind Camp. I might also have some work for you...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (6029,'Донесение из Круговзора','Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему. Я здесь как представитель интересов Серебряного Рассвета в администрации Круговзора. Я должен доложить обстановку офицеру Гарушу в Бастион, расположенный на восточных окраинах Западных Чумных земель, к востоку от Тирисфальских лесов.$B$BЕсли я могу тебя об этом просить... это будет прекрасный повод представить тебя моему начальнику. И, возможно, он найдет тебе дело!','Доставьте донесение из Круговзора офицеру Гарушу из ордена Серебряного Рассвета в Бастион в Западных Чумных землях.','Грегор крайне находчив. Он некоторое время имел дело с Картелем Хитрая Шестеренка, и стал экспертом по "искусству" переговоров с гоблинами. Хотя верно, что расположение гоблинов к вам напрямую зависит от толщины вашего кошелька, они также признают и уважают роль дипломатии. Если, так или иначе, она обеспечивает им повторные заказы...$B$BВо всяком случае, Серебряный Рассвет выражает вам признательность за проделанную работу. Примите это вместе с нашей благодарностью.','Приветствую, $C. От имени Серебряного Рассвета, я предлагаю вам безопасность и убежище, пока вы находитесь на территории Бастиона. Я мог бы также предложить хорошую драку за стоящие того цели!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение из Круговзора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я ищу ответственного работника, способного помочь мне решить небольшую, но очень важную проблему. Я здесь как представитель интересов Серебряного Рассвета в администрации Круговзора. Я должен доложить обстановку офицеру Гарушу в Бастион, расположенный на восточных окраинах Западных Чумных земель, к востоку от Тирисфальских лесов.$B$BЕсли я могу тебя об этом просить... это будет прекрасный повод представить тебя моему начальнику. И, возможно, он найдет тебе дело!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте донесение из Круговзора офицеру Гарушу из ордена Серебряного Рассвета в Бастион в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Грегор крайне находчив. Он некоторое время имел дело с Картелем Хитрая Шестеренка, и стал экспертом по "искусству" переговоров с гоблинами. Хотя верно, что расположение гоблинов к вам напрямую зависит от толщины вашего кошелька, они также признают и уважают роль дипломатии. Если, так или иначе, она обеспечивает им повторные заказы...$B$BВо всяком случае, Серебряный Рассвет выражает вам признательность за проделанную работу. Примите это вместе с нашей благодарностью.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую, $C. От имени Серебряного Рассвета, я предлагаю вам безопасность и убежище, пока вы находитесь на территории Бастиона. Я мог бы также предложить хорошую драку за стоящие того цели!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6030,'Герцог Николас Зверенхофф','Отшельник-медиум по имени Умбранс, обитающий в этих краях, обеспечил Серебряный Рассвет настоящим шедевром литературы... Это самое большое собрание слухов и сплетен, которое только было когда-либо издано.$B$BОдин из наиболее уважаемых лидеров Рассвета, герцог Николас Зверенхофф, является блестящим лингвистом. Ты не $gмог:могла; бы отнести ему эту книгу – не бесплатно, разумеется! Сейчас его можно найти в Часовне Последней Надежды, в восточной части Восточных Чумных земель.','Доставьте книгу "Исследования речи духов" Герцогу Николасу Зверенхоффу в Часовню Последней Надежды в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Герцог Николас Зверенхофф',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отшельник-медиум по имени Умбранс, обитающий в этих краях, обеспечил Серебряный Рассвет настоящим шедевром литературы... Это самое большое собрание слухов и сплетен, которое только было когда-либо издано.$B$BОдин из наиболее уважаемых лидеров Рассвета, герцог Николас Зверенхофф, является блестящим лингвистом. Ты не $gмог:могла; бы отнести ему эту книгу – не бесплатно, разумеется! Сейчас его можно найти в Часовне Последней Надежды, в восточной части Восточных Чумных земель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте книгу "Исследования речи духов" Герцогу Николасу Зверенхоффу в Часовню Последней Надежды в Восточных Чумных землях.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6031,'Руническая ткань','Мы, древобрюхи, самодостаточны. Мы не любим чужаков. Для нас такая жизнь хороша, но вот для торговли – нет.$B$BНедавно к нам в Крепость Древобрюхов забрела редкая гостья – одна ночная эльфийка. У нее был плащ из рунической ткани. Рунная ткань у нас вещь редкая, но плащ был такой красивый, что мои сородичи пожелали, чтобы я нашил им побольше одежды из рунической ткани.$B$BТы принесешь мне рунической ткани? А за это я кое-что дам тебе.','Принесите 30 отрезов рунической ткани Мелиошу в Крепость Древобрюхов.','Вернитесь к Мелиошу в Зимние Ключи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руническая ткань',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы, древобрюхи, самодостаточны. Мы не любим чужаков. Для нас такая жизнь хороша, но вот для торговли – нет.$B$BНедавно к нам в Крепость Древобрюхов забрела редкая гостья – одна ночная эльфийка. У нее был плащ из рунической ткани. Рунная ткань у нас вещь редкая, но плащ был такой красивый, что мои сородичи пожелали, чтобы я нашил им побольше одежды из рунической ткани.$B$BТы принесешь мне рунической ткани? А за это я кое-что дам тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 30 отрезов рунической ткани Мелиошу в Крепость Древобрюхов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелиошу в Зимние Ключи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (6031,'А, принес. Какая же красивая ткань!$B$BСпасибо тебе, Гностикмаг. Ты настоящий друг. Пожалуйста, прими в благодарность.','Ты принес рунную ткань? Мой народ сгорает от нетерпения получить одежду из рунической ткани!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, принес. Какая же красивая ткань!$B$BСпасибо тебе, Гностикмаг. Ты настоящий друг. Пожалуйста, прими в благодарность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес рунную ткань? Мой народ сгорает от нетерпения получить одежду из рунической ткани!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6032,'Священная ткань','Хотя древобрюхам по нраву ощущение от рунической ткани, она для нас не священна. А вот луноткань – священна.$B$BПринеси мне немного этой священной ткани, и я научу тебя некоторым портняжным секретам.','Принесите 2 отреза луноткани Мелиошу в Крепость Древобрюхов.','Вернитесь к Мелиошу в Зимние Ключи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Священная ткань',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя древобрюхам по нраву ощущение от рунической ткани, она для нас не священна. А вот луноткань – священна.$B$BПринеси мне немного этой священной ткани, и я научу тебя некоторым портняжным секретам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 отреза луноткани Мелиошу в Крепость Древобрюхов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелиошу в Зимние Ключи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6041,'Дымок над водою','Пока ты $gзанимался:занималась; заготовкой припасов, мои люди отметили некоторые сооружения Плети, которые должны быть уничтожены.$B$BПлан действий таков: я дам тебе 10 брусков моего особого состава, ты отправишься в Чумной лес и оставишь их в сооружениях Плети, помеченных знаком.$B$B<Дымок щелкает пальцами.>$B$BБабах! Все очень просто!','Отправляйтесь в Чумной лес, к северо-западу от Часовни Последней Надежды. Уничтожьте 8 сооружений Плети, отмеченных знаком взрыва, поместив особый состав Дымка внутрь сооружения. Дымок отметил зиккураты и бойни.$B$BРазместив бомбу внутри сооружения, немедленно выбирайтесь наружу и любуйтесь делом рук своих с безопасного расстояния. $B$BАх да, вот еще что, особый состав Дымка – вещество весьма нестабильное.','Ты, кажется, немного чернее, чем $Gбыл:была;. Твой вид просто говорит: “меня подкоптило мощным взрывом”.$B$B<Дымок смеется.>$B$BВ любом случае! Вот твоя доля. Я подбросил тебе кое-что, теперь тебе легче будет перенести ожоги.','У меня остались припасы, чтобы сделать еще несколько палочек из специального состава. Просто дайте знать старику Смоки, если вам нужно больше.','Вернитесь к Дымку Лару в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дымок над водою',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gзанимался:занималась; заготовкой припасов, мои люди отметили некоторые сооружения Плети, которые должны быть уничтожены.$B$BПлан действий таков: я дам тебе 10 брусков моего особого состава, ты отправишься в Чумной лес и оставишь их в сооружениях Плети, помеченных знаком.$B$B<Дымок щелкает пальцами.>$B$BБабах! Все очень просто!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Чумной лес, к северо-западу от Часовни Последней Надежды. Уничтожьте 8 сооружений Плети, отмеченных знаком взрыва, поместив особый состав Дымка внутрь сооружения. Дымок отметил зиккураты и бойни.$B$BРазместив бомбу внутри сооружения, немедленно выбирайтесь наружу и любуйтесь делом рук своих с безопасного расстояния. $B$BАх да, вот еще что, особый состав Дымка – вещество весьма нестабильное.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты, кажется, немного чернее, чем $Gбыл:была;. Твой вид просто говорит: “меня подкоптило мощным взрывом”.$B$B<Дымок смеется.>$B$BВ любом случае! Вот твоя доля. Я подбросил тебе кое-что, теперь тебе легче будет перенести ожоги.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня остались припасы, чтобы сделать еще несколько палочек из специального состава. Просто дайте знать старику Смоки, если вам нужно больше.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дымку Лару в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6042,'Мелочи нежизни','С фермы и шагу нельзя ступить, чтобы не напороться на одну из этих проклятых летучих мышей! Я бы, знаешь ли, предпочел заниматься истреблением Плети, не отвлекаясь на всякую мелкую шушеру. Мое время слишком дорого, чтобы тратить его на охоту за мышами. А вот твое – нет.$B$BЧто ты там бормочешь? Обучение? Вот тебе обучение – пойди поучись ловле мышей! И не смей показываться мне на глаза, пока не перебьешь несколько десятков этих мерзких тварей.','Истребите 20 пагубных нетопырей и 10 чудовищных чумных нетопырей. После возвращайтесь к Натаносу Гнилостню.','Невероятно, сколького можно добиться, немного разозлившись.','Хватит ныть! Я мог бы заставить тебя собирать мышиный помет, но я сегодня добрый!$B$B<Натаноса явно осенила какая-то идея>$B$BЭй! А ну погоди! Куда побежал!','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мелочи нежизни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С фермы и шагу нельзя ступить, чтобы не напороться на одну из этих проклятых летучих мышей! Я бы, знаешь ли, предпочел заниматься истреблением Плети, не отвлекаясь на всякую мелкую шушеру. Мое время слишком дорого, чтобы тратить его на охоту за мышами. А вот твое – нет.$B$BЧто ты там бормочешь? Обучение? Вот тебе обучение – пойди поучись ловле мышей! И не смей показываться мне на глаза, пока не перебьешь несколько десятков этих мерзких тварей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Истребите 20 пагубных нетопырей и 10 чудовищных чумных нетопырей. После возвращайтесь к Натаносу Гнилостню.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно, сколького можно добиться, немного разозлившись.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хватит ныть! Я мог бы заставить тебя собирать мышиный помет, но я сегодня добрый!$B$B<Натаноса явно осенила какая-то идея>$B$BЭй! А ну погоди! Куда побежал!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6061,'Приручение зверя','Для нас, тауренов, важно следовать традициям предков, сражаясь с могучими зверями. Одолевая их, мы вбираем в себя их дух, делаясь все ближе Матери-Земле.$B$BПриручив же зверя и сделав его своим помощником, мы делаем еще один шаг навстречу природе. В конце концов ты сможешь выбрать зверя себе по вкусу. Но сначала всему приходится учиться, и этому тоже. Для начала возьми этот хлыст приручения; ступай, приручи равнинного долгонога.','Приручите взрослого равнинного долгонога при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в деревне Кровавого Копыта.','Я уже знаю, мать-земля сказала мне, что ты $Gсправился:справилась; со своей задачей.','Тренируйся, $N. Приручите взрослого равнинного долгонога.','Приручите взрослого равнинного долгонога','Вернитесь к Йо Колкой Гриве в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для нас, тауренов, важно следовать традициям предков, сражаясь с могучими зверями. Одолевая их, мы вбираем в себя их дух, делаясь все ближе Матери-Земле.$B$BПриручив же зверя и сделав его своим помощником, мы делаем еще один шаг навстречу природе. В конце концов ты сможешь выбрать зверя себе по вкусу. Но сначала всему приходится учиться, и этому тоже. Для начала возьми этот хлыст приручения; ступай, приручи равнинного долгонога.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приручите взрослого равнинного долгонога при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в деревне Кровавого Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уже знаю, мать-земля сказала мне, что ты $Gсправился:справилась; со своей задачей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тренируйся, $N. Приручите взрослого равнинного долгонога.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите взрослого равнинного долгонога',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йо Колкой Гриве в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6063,'Приручение зверя','Охотнику важно помнить о том, какая перед ним стоит ответственность. Природа – не та сила, которую можно подчинить своим прихотям. Ее следует почитать как нечто, без чего само твое существование было бы невозможным.$B$B$n, ты $Gдолжен:должна; доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника.$B$BПервым делом возьми этот хлыст приручения. С его помощью ты сумеешь приручить чащобного скрытня. Приручи его и поупражняйся в своем охотничьем искусстве.','С помощью хлыста приручения приручите чащобного скрытня. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.','Превосходно, $N! Ты довольно $Gспособный:способная; $Gученик:ученица;.','Ты быстро обучаешься, $N. Однажды ты станешь $Gвеликим:великой;, $C.','Приручите чащобного скрытня.','Вернитесь к Дазалару в Доланаар, что в Тельдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Охотнику важно помнить о том, какая перед ним стоит ответственность. Природа – не та сила, которую можно подчинить своим прихотям. Ее следует почитать как нечто, без чего само твое существование было бы невозможным.$B$B$n, ты $Gдолжен:должна; доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника.$B$BПервым делом возьми этот хлыст приручения. С его помощью ты сумеешь приручить чащобного скрытня. Приручи его и поупражняйся в своем охотничьем искусстве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью хлыста приручения приручите чащобного скрытня. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно, $N! Ты довольно $Gспособный:способная; $Gученик:ученица;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты быстро обучаешься, $N. Однажды ты станешь $Gвеликим:великой;, $C.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите чащобного скрытня.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дазалару в Доланаар, что в Тельдрассиле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6064,'Приручение зверя','Привет, $Gпарень:подруга;! Стало быть, хочешь узнать, как завести себе питомца?$B$BЧто же, начнем. Когда доходит до охоты, нет ничего важнее снаряжения, но о моем новом шрапнельном самостреле мы поболтаем в другой раз. А пока займемся тем, что, так интересует тебя в данный момент – питомцем!$B$BТебе лучше всего попытаться приручить нескольких существ и посмотреть, кто тебе больше по сердцу. Итак, найди большого скального вепря, а затем используй хлыст приручения, чтобы приручить его.','Приручите большого скального вепря с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.','Я знаю, знаю, ты думаешь – ну а дальше то что, а?','Тебе сначала надо попробовать приручить разных зверей – тогда ты сможешь понять, кто тебе больше по душе.','Приручите большого скального вепря.','Вернитесь к Грифу Дикому Сердцу в Каранос, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $Gпарень:подруга;! Стало быть, хочешь узнать, как завести себе питомца?$B$BЧто же, начнем. Когда доходит до охоты, нет ничего важнее снаряжения, но о моем новом шрапнельном самостреле мы поболтаем в другой раз. А пока займемся тем, что, так интересует тебя в данный момент – питомцем!$B$BТебе лучше всего попытаться приручить нескольких существ и посмотреть, кто тебе больше по сердцу. Итак, найди большого скального вепря, а затем используй хлыст приручения, чтобы приручить его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приручите большого скального вепря с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю, знаю, ты думаешь – ну а дальше то что, а?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе сначала надо попробовать приручить разных зверей – тогда ты сможешь понять, кто тебе больше по душе.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите большого скального вепря.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грифу Дикому Сердцу в Каранос, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6065,'Путь охотника','Привет тебе, $gюный охотник:юная охотница;. Ты кажешься мне достаточно $gопытным:опытной;, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Йо Колкой Гривой в деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника.','Поговорите с Йо Колкой Гривой в деревне Кровавого Копыта, что в Мулгоре.','Да, я полагаю, что ты уже $Gготов:готова;...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $gюный охотник:юная охотница;. Ты кажешься мне достаточно $gопытным:опытной;, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Йо Колкой Гривой в деревне Кровавого Копыта. Он научит тебя, как обрести собственного питомца и спутника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Йо Колкой Гривой в деревне Кровавого Копыта, что в Мулгоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я полагаю, что ты уже $Gготов:готова;...',`offerrewardtext_loc8`);
