INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6068,'Путь охотника','Привет тебе, $gюный охотник:юная охотница;! Сдается мне, что у тебя уже достаточно опыта, чтобы подчинить себе зверя и сделать его своим спутником.$b$bНайди в Колючем Холме Тотара. Он научит тебя, как обзавестись собственным питомцем.','Поговорите с Тотаром в Колючем Холме, что в Дуротаре.','Да, тебе, пожалуй, пора учиться дальше.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $gюный охотник:юная охотница;! Сдается мне, что у тебя уже достаточно опыта, чтобы подчинить себе зверя и сделать его своим спутником.$b$bНайди в Колючем Холме Тотара. Он научит тебя, как обзавестись собственным питомцем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тотаром в Колючем Холме, что в Дуротаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, тебе, пожалуй, пора учиться дальше.',`offerrewardtext_loc8`);
