INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6074,'Путь охотника','Привет тебе, $Gюный охотник:юная охотница;. Ты кажешься мне достаточно $Gопытным:опытной;, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника.','Поговорите с Грифом Диким Сердцем в Караносе, что в Дун Мороге.','Да, я думаю, что теперь ты $Gготов:готова;...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $Gюный охотник:юная охотница;. Ты кажешься мне достаточно $Gопытным:опытной;, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Грифом Диким Сердцем в Караносе, что в Дун Мороге.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я думаю, что теперь ты $Gготов:готова;...',`offerrewardtext_loc8`);
