INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6076,'Путь охотника','Привет тебе, $Gюный охотник:юная охотница;. Ты кажешься мне достаточно $Gопытным:опытной;, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника.','Поговорите с Грифом Диким Сердцем в Караносе, что в Дун Мороге.','Да, я думаю, что теперь ты $Gготов:готова;...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $Gюный охотник:юная охотница;. Ты кажешься мне достаточно $Gопытным:опытной;, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Грифом Диким Сердцем из Караноса. Он научит тебя, как обрести собственного питомца и спутника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Грифом Диким Сердцем в Караносе, что в Дун Мороге.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я думаю, что теперь ты $Gготов:готова;...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6084,'Приручение зверя','Эти скальные вепри такие здоровенные – может, тебе хочется кого поизящнее? Ладушки, у меня есть кое-кто на примете. К югу и востоку отсюда ты найдешь больших белых кошек, называемых снежными леопардами. Они чем-то напоминают элегантную винтовку – такие же красивые и такие же смертоносные. Они гораздо проворнее и быстрее укрощенного тобой вепря.$B$BНа, держи этот хлыст приручения. Посмотрим, придется ли тебе по душе снежный леопард.','Приручите снежного леопарда с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.','Когда я почувствую, что ты все $Gизучил:изучила;, я дам тебе способность $Gсамому:самой; выбирать себе любого зверя, которого ты захочешь.','Ну, как тебе снежный леопард, $N?','Приручите снежного леопарда','Вернитесь к Грифу Дикому Сердцу в Каранос, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти скальные вепри такие здоровенные – может, тебе хочется кого поизящнее? Ладушки, у меня есть кое-кто на примете. К югу и востоку отсюда ты найдешь больших белых кошек, называемых снежными леопардами. Они чем-то напоминают элегантную винтовку – такие же красивые и такие же смертоносные. Они гораздо проворнее и быстрее укрощенного тобой вепря.$B$BНа, держи этот хлыст приручения. Посмотрим, придется ли тебе по душе снежный леопард.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приручите снежного леопарда с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда я почувствую, что ты все $Gизучил:изучила;, я дам тебе способность $Gсамому:самой; выбирать себе любого зверя, которого ты захочешь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как тебе снежный леопард, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите снежного леопарда',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грифу Дикому Сердцу в Каранос, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6085,'Приручение зверя','Возможно, тебе понравится животное, обладающее чем-то большим, чем просто грубая сила. Медведи-ледолапы – замечательные спутники для охотников-новичков, вроде тебя. Их можно найти к востоку от Караноса. Вот тебе хлыст приручения, попытайся приручить это животное и посмотри, как он тебе придется!$B$BКогда ты вернешься, я научу тебя, как приручать животных. Твой питомец будет вместе с тобой разделять опасности и получать опыт. Я также научу тебя призывать и отпускать животное по своему желанию.','Приручите медведя-ледолапа с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.','Вот и ты, $N. Теперь я дам тебе навыки, позволяющие приручать, звать и прогонять любимца. Используй их на свое усмотрение.$B$BНайди себе хорошего, лояльного спутника, и наслаждайся охотой!','Ну, удалось приручить медведя-ледолапа?','Приручите медведя-ледолапа','Вернитесь к Грифу Дикому Сердцу в Каранос, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, тебе понравится животное, обладающее чем-то большим, чем просто грубая сила. Медведи-ледолапы – замечательные спутники для охотников-новичков, вроде тебя. Их можно найти к востоку от Караноса. Вот тебе хлыст приручения, попытайся приручить это животное и посмотри, как он тебе придется!$B$BКогда ты вернешься, я научу тебя, как приручать животных. Твой питомец будет вместе с тобой разделять опасности и получать опыт. Я также научу тебя призывать и отпускать животное по своему желанию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приручите медведя-ледолапа с помощью хлыста приручения. Потренируйтесь со своим новым питомцем, а затем верните хлыст приручения Грифу Дикому Сердцу в Каранос.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и ты, $N. Теперь я дам тебе навыки, позволяющие приручать, звать и прогонять любимца. Используй их на свое усмотрение.$B$BНайди себе хорошего, лояльного спутника, и наслаждайся охотой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, удалось приручить медведя-ледолапа?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите медведя-ледолапа',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грифу Дикому Сердцу в Каранос, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6086,'Обучение зверя','$n, ты умеешь приручать зверей, но ведь надо еще научиться тренировать своего питомца.$B$BИди в Палаты Войны в Стальгорне и поговори там с одним из наших лучших специалистов в обучении зверей – Белией Громовой Гранит. Она покажет тебе, как обучать питомца. Так что отправляйся в путь, $Gпарень:подруга;!$B$BБелия по характеру дружелюбна, у тебя не будет проблем в нахождении с ней общего языка. Удачи, $n.','Поговорите в с Белией Громовой Гранит в Стальгорне.','Новый рекрут? В свое время ты станешь неплохим охотником, да-да.$B$BЯ могу тебя научить тому, что ты хочешь. Животных приручать? Да все, что угодно. Но за все это придется заплатить звонкой монетой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты умеешь приручать зверей, но ведь надо еще научиться тренировать своего питомца.$B$BИди в Палаты Войны в Стальгорне и поговори там с одним из наших лучших специалистов в обучении зверей – Белией Громовой Гранит. Она покажет тебе, как обучать питомца. Так что отправляйся в путь, $Gпарень:подруга;!$B$BБелия по характеру дружелюбна, у тебя не будет проблем в нахождении с ней общего языка. Удачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в с Белией Громовой Гранит в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Новый рекрут? В свое время ты станешь неплохим охотником, да-да.$B$BЯ могу тебя научить тому, что ты хочешь. Животных приручать? Да все, что угодно. Но за все это придется заплатить звонкой монетой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6087,'Приручение зверя','Твой дух полон огня, охотник, и ты с радостью встречаешь новые испытания.$B$BСледующее задание – приручить волка, известного как охотник прерий. Он быстр и бесстрашен, и чтобы сделать его своим спутником, тебе придется воспитать в себе эти качества.$B$BВо время боя ты поймешь, как вы будете сражаться бок о бок. Ведь вы с питомцем должны действовать очень слаженно, как единый организм.$B$BВот хлыст приручения, $n. Подчини себе охотника прерий, потренируйся.','Приручите охотника прерий при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в деревне Кровавого Копыта.','Да... Мать-Земля верит, что ты $Gготов:готова; к следующему уроку.','Удалось найти охотника прерий?','Приручите охотника прерий','Вернитесь к Йо Колкой Гриве в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твой дух полон огня, охотник, и ты с радостью встречаешь новые испытания.$B$BСледующее задание – приручить волка, известного как охотник прерий. Он быстр и бесстрашен, и чтобы сделать его своим спутником, тебе придется воспитать в себе эти качества.$B$BВо время боя ты поймешь, как вы будете сражаться бок о бок. Ведь вы с питомцем должны действовать очень слаженно, как единый организм.$B$BВот хлыст приручения, $n. Подчини себе охотника прерий, потренируйся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приручите охотника прерий при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в деревне Кровавого Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... Мать-Земля верит, что ты $Gготов:готова; к следующему уроку.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти охотника прерий?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите охотника прерий',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йо Колкой Гриве в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6088,'Приручение зверя','Последним твоим заданием станет приручение жителя неба. Перепелятник – непростой противник, но зато отличный союзник – атакует он внезапно и пугает врагов.$B$BПо воле Матери-Земли, по возвращении с победой, я наделю тебя искусством приручать любого зверя и делать его своим спутником; твоему питомцу придется встретиться с теми же испытаниями, что и тебе, и вместе с тобой набираться опыта. Я покажу тебе, как подзывать и отсылать его по собственной воле.','Приручите перепелятника при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в деревне Кровавого Копыта.','Ты $Gизучил:изучила; все, чему я могу тебя научить, $N. Пусть благословения Матери-Земли направляют тебя при выборе своего любимца.$B$BВот, $N. Теперь я дам тебе силу приручать животных, а также отпускать их на волю, когда ты сочтешь нужным. Используй свои новые способности с гордостью и уважай Мать-Землю.','Скоро будешь $Gготов:готова;, $N.','Приручите перепелятника','Вернитесь к Йо Колкой Гриве в деревню Кровавого Копыта, что в Мулгоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последним твоим заданием станет приручение жителя неба. Перепелятник – непростой противник, но зато отличный союзник – атакует он внезапно и пугает врагов.$B$BПо воле Матери-Земли, по возвращении с победой, я наделю тебя искусством приручать любого зверя и делать его своим спутником; твоему питомцу придется встретиться с теми же испытаниями, что и тебе, и вместе с тобой набираться опыта. Я покажу тебе, как подзывать и отсылать его по собственной воле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приручите перепелятника при помощи хлыста приручения. Потренируйтесь и верните хлыст Йо Колкой Гриве в деревне Кровавого Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gизучил:изучила; все, чему я могу тебя научить, $N. Пусть благословения Матери-Земли направляют тебя при выборе своего любимца.$B$BВот, $N. Теперь я дам тебе силу приручать животных, а также отпускать их на волю, когда ты сочтешь нужным. Используй свои новые способности с гордостью и уважай Мать-Землю.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Скоро будешь $Gготов:готова;, $N.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите перепелятника',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Йо Колкой Гриве в деревню Кровавого Копыта, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6089,'Обучение зверя','Теперь ты знаешь, как приручать питомца, но тебе надо научиться еще и обучать его.$B$BОтправляйся в Громовой Утес. Там тебе нужно будет поговорить с одним из наших самых уважаемых охотников, Хольтом Громовым Рогом. Если он сочтет тебя достойным знаний, то объяснит тебе, как обучать твоего нового питомца. $B$BХольт одолел многих могущественных и страшных зверей Азерота и сам повелевает сильными существами. Его связь с Матерью-Землей сильна, и он многому может научить. Удачи, $n.','Поговорите с Хольтом Громовым Рогом в Громовом Утесе.','А, юный $C. Да, я могу наделить тебя знаниями, как обучать и направлять твоего питомца. Ты не только сможешь научить его новым способностям, но также сможешь кормить его и даже оживлять, если он падет в бою.$B$BСтупай, Мать-Земля еще сведет наши пути. Поговорим позже.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты знаешь, как приручать питомца, но тебе надо научиться еще и обучать его.$B$BОтправляйся в Громовой Утес. Там тебе нужно будет поговорить с одним из наших самых уважаемых охотников, Хольтом Громовым Рогом. Если он сочтет тебя достойным знаний, то объяснит тебе, как обучать твоего нового питомца. $B$BХольт одолел многих могущественных и страшных зверей Азерота и сам повелевает сильными существами. Его связь с Матерью-Землей сильна, и он многому может научить. Удачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хольтом Громовым Рогом в Громовом Утесе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, юный $C. Да, я могу наделить тебя знаниями, как обучать и направлять твоего питомца. Ты не только сможешь научить его новым способностям, но также сможешь кормить его и даже оживлять, если он падет в бою.$B$BСтупай, Мать-Земля еще сведет наши пути. Поговорим позже.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6101,'Приручение зверя','Природа изменчива, но на нее вполне можно положиться, $n. Она предсказуема в том, что никогда не остается одной и той же, она всегда меняется. $B$BПоручения, которые я тебе дам, помогут тебе увидеть и оценить различных существ, которые впоследствии смогут стать твоими спутниками.$B$BВозьми этот хлыст приручения и приручи ночного саблезуба-охотника, которого ты найдешь к югу отсюда. Поупражняйся в своем охотничьем искусстве. Таким образом ты начнешь понимать сходства и различия творений природы.','С помощью хлыста приручения приручите ночного саблезуба-охотника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.','Вижу в тебе обязательность и понимание всего, чему я научил тебя, $N.','Постоянно поддерживать равновесие с природой – таков путь жизни каждого $R.','Приручите ночного саблезуба-охотника','Вернитесь к Дазалару в Доланаар, что в Тельдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Природа изменчива, но на нее вполне можно положиться, $n. Она предсказуема в том, что никогда не остается одной и той же, она всегда меняется. $B$BПоручения, которые я тебе дам, помогут тебе увидеть и оценить различных существ, которые впоследствии смогут стать твоими спутниками.$B$BВозьми этот хлыст приручения и приручи ночного саблезуба-охотника, которого ты найдешь к югу отсюда. Поупражняйся в своем охотничьем искусстве. Таким образом ты начнешь понимать сходства и различия творений природы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью хлыста приручения приручите ночного саблезуба-охотника. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу в тебе обязательность и понимание всего, чему я научил тебя, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Постоянно поддерживать равновесие с природой – таков путь жизни каждого $R.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите ночного саблезуба-охотника',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дазалару в Доланаар, что в Тельдрассиле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6102,'Приручение зверя','Тебе удалось приручить двух детей земли, и теперь тебе предстоит подружиться с обитателем неба. При помощи этого хлыста приручи совиного крикуна, которого найдешь к западу отсюда. Испытай свое искусство, взяв в спутники эту могучую сову.$B$BКогда вернешься, я наделю тебя знаниями, которые понадобятся тебе для приручения любого животного, которого ты выберешь себе в спутники. Твой спутник встретит лицом к лицу те же опасности, что и ты, и вместе с тобой будет набираться опыта. Я также научу тебя, как призывать и отпускать по желанию твоего питомца.','С помощью хлыста приручите совиного крикуна. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.','Теперь ты знаешь все, чему я мог тебя обучить, $N. Могу ли дать тебе еще один совет? Хорошенько подумай прежде, чем выбрать первого питомца. Будет ли это существо, что ходит по земле, плавает в воде или рассекает небеса? Кем бы оно ни было, твой питомец, вне всякого сомнения, долго пробудет при тебе.$B$BЧто же, $N. Ныне я дам тебе умение приручать животное, а так же призывать и отпускать его, когда тебе будет нужно. Гордись своими новыми умениями – ты их честно заслужил.','Я горжусь твоими достижениями, $N. $Gсправился:справилась; ли ты с той задачей, что я тебе поручил?','Приручите совиного крикуна','Вернитесь к Дазалару в Доланаар, что в Тельдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось приручить двух детей земли, и теперь тебе предстоит подружиться с обитателем неба. При помощи этого хлыста приручи совиного крикуна, которого найдешь к западу отсюда. Испытай свое искусство, взяв в спутники эту могучую сову.$B$BКогда вернешься, я наделю тебя знаниями, которые понадобятся тебе для приручения любого животного, которого ты выберешь себе в спутники. Твой спутник встретит лицом к лицу те же опасности, что и ты, и вместе с тобой будет набираться опыта. Я также научу тебя, как призывать и отпускать по желанию твоего питомца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью хлыста приручите совиного крикуна. Поупражняйтесь, затем верните хлыст приручения Дазалару в Доланаар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь ты знаешь все, чему я мог тебя обучить, $N. Могу ли дать тебе еще один совет? Хорошенько подумай прежде, чем выбрать первого питомца. Будет ли это существо, что ходит по земле, плавает в воде или рассекает небеса? Кем бы оно ни было, твой питомец, вне всякого сомнения, долго пробудет при тебе.$B$BЧто же, $N. Ныне я дам тебе умение приручать животное, а так же призывать и отпускать его, когда тебе будет нужно. Гордись своими новыми умениями – ты их честно заслужил.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я горжусь твоими достижениями, $N. $Gсправился:справилась; ли ты с той задачей, что я тебе поручил?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите совиного крикуна',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дазалару в Доланаар, что в Тельдрассиле.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6103,'Обучение зверя','Теперь ты знаешь, как приручать питомца, но тебе надо научиться еще и обучать его.$B$BОтправляйся в Дарнас. Там тебе нужно будет поговорить с одной из наших самых уважаемых охотниц, Иокастой. Она объяснит тебе, как обучать твоего нового питомца, так что поторопись.$B$BХотя Иокаста и сурова, ей всегда приятно наблюдать за развитием способностей очередного охотника. Держись с ней почтительно, и она воздаст добром. Удачи, $n.','Поговорите с Иокастой в Анклаве Кенария в Дарнасе.','Новоиспеченный $C?. Что же, я могу дать тебе знания, необходимые для обучения и управления твоим питомцем. Ты сможешь обучать своего питомца не только новым способностям, но научишься его кормить и возрождать, если он погибнет в схватке.$B$BЗапомни, $N: всегда уважай равновесие и почитай природу. Теперь ступай. Попозже еще поговорим.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты знаешь, как приручать питомца, но тебе надо научиться еще и обучать его.$B$BОтправляйся в Дарнас. Там тебе нужно будет поговорить с одной из наших самых уважаемых охотниц, Иокастой. Она объяснит тебе, как обучать твоего нового питомца, так что поторопись.$B$BХотя Иокаста и сурова, ей всегда приятно наблюдать за развитием способностей очередного охотника. Держись с ней почтительно, и она воздаст добром. Удачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Иокастой в Анклаве Кенария в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Новоиспеченный $C?. Что же, я могу дать тебе знания, необходимые для обучения и управления твоим питомцем. Ты сможешь обучать своего питомца не только новым способностям, но научишься его кормить и возрождать, если он погибнет в схватке.$B$BЗапомни, $N: всегда уважай равновесие и почитай природу. Теперь ступай. Попозже еще поговорим.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6121,'Новый урок','Теперь, $n, ты $Gготов:готова; узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придется испытать на себе силу действия яда в полной мере. Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд – он ждет твоего прибытия, чтобы начать обучение.','Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.','Привет тебе друид, я вижу ты $Gготов:готова; получить знания излечения ядов.$B$BВидишь ли, мы столкнулись с определенными трудностями около Аубердина в Темных берегах, там распоясались животные, которые сеют своим ядом направо и налево, и нет на них никакой управы. Мы запросили Лунную Поляну о помощи... и надеюсь, ты, $Gтот:та;, кого мы ждали!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый урок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, $n, ты $Gготов:готова; узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придется испытать на себе силу действия яда в полной мере. Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд – он ждет твоего прибытия, чтобы начать обучение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе друид, я вижу ты $Gготов:готова; получить знания излечения ядов.$B$BВидишь ли, мы столкнулись с определенными трудностями около Аубердина в Темных берегах, там распоясались животные, которые сеют своим ядом направо и налево, и нет на них никакой управы. Мы запросили Лунную Поляну о помощи... и надеюсь, ты, $Gтот:та;, кого мы ждали!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6122,'Основной источник','Водопад Скалистый на Темных берегах – основной источник питьевой воды для всего региона, но теперь я подозреваю, что именно оттуда распространяется отрава, поражающая местную фауну – особенно оленей. Возьми эту пробирку, чтобы отобрать немного воды из устья пещеры. Осторожнее – в пещере у водопада ныне поселилась опасная нага.$B$BКак только наберешь воды, доставь ее Аландариан Песне Ночи в Аубердин. Именно она просила нашей помощи, и ты поможешь ей разобраться с этой заразой.','Используйте пустую колбу для взятия пробы воды из устья пещеры у водопада Скалистый. $B$BДоставьте наполненную колбу Аландариан Песне Ночи в Аубердин, на Темные берега.','Во имя Элуны, эта вода просто отвратительна! Не удивительно, что олени больны.$B$BЧто-то загрязняет эту воду, а она загрязняет все источники в Темных берегах! Река? Нет, не думаю…$B$BЧто-ж эта вода, что ты $Gпринес:принесла;, поможет нам сделать лекарство! И пока я работаю над ним – ты поможешь мне достать необходимые компоненты.','Это тебя прислал Круг Кенария Лунной поляны, да? Замечательно! Нам так не хватает рук для работы с бедными оленями, и мы рады любой помощи.$B$BТы $Gпринес:принесла; пробу воды, о которой говорил мне Дендрит Блеск Звезд? Он сказал, что ты принесешь ее, чтобы мы могли тотчас же приступить к трудам по исцелению...','Вернитесь к Аландариан Песне Ночи в Аубердин, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Основной источник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Водопад Скалистый на Темных берегах – основной источник питьевой воды для всего региона, но теперь я подозреваю, что именно оттуда распространяется отрава, поражающая местную фауну – особенно оленей. Возьми эту пробирку, чтобы отобрать немного воды из устья пещеры. Осторожнее – в пещере у водопада ныне поселилась опасная нага.$B$BКак только наберешь воды, доставь ее Аландариан Песне Ночи в Аубердин. Именно она просила нашей помощи, и ты поможешь ей разобраться с этой заразой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте пустую колбу для взятия пробы воды из устья пещеры у водопада Скалистый. $B$BДоставьте наполненную колбу Аландариан Песне Ночи в Аубердин, на Темные берега.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во имя Элуны, эта вода просто отвратительна! Не удивительно, что олени больны.$B$BЧто-то загрязняет эту воду, а она загрязняет все источники в Темных берегах! Река? Нет, не думаю…$B$BЧто-ж эта вода, что ты $Gпринес:принесла;, поможет нам сделать лекарство! И пока я работаю над ним – ты поможешь мне достать необходимые компоненты.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это тебя прислал Круг Кенария Лунной поляны, да? Замечательно! Нам так не хватает рук для работы с бедными оленями, и мы рады любой помощи.$B$BТы $Gпринес:принесла; пробу воды, о которой говорил мне Дендрит Блеск Звезд? Он сказал, что ты принесешь ее, чтобы мы могли тотчас же приступить к трудам по исцелению...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аландариан Песне Ночи в Аубердин, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6123,'Сбор лекарственных ингредиентов','Основой целительной мази для оленей послужит вода. Для придания ей целительных свойств мне понадобится земляной корень. Травники знают, где его искать, так что, если нам не повезло и ты не $gтравник:травница;, придется найти кого-то, кто сможет помочь.$B$BДля усиления воздействия мне нужны лунные грибы. Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно. В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будь $gосторожен:осторожна;.','Принесите 5 земляных корней и 12 лунных грибов Аландариан Песне Ночи в Аубердине, чтобы она могла сделать целительную мазь.','Отлично, $N, вы принесли так много, что должно хватить на несколько больших доз мази – по крайней мере чтобы исцеление началось.$B$BИзготовление средств против ядов иногда бывает весьма сложным, поскольку каждый из них требует конкретного антидота для нейтрализации воздействия. Здорово было бы уметь в любой момент снимать отравление, не беспокоясь о конкретных ингредиентах, которые должен содержать антидот!$B$BА теперь позвольте мне приступить к работе!','Вы собрали реагенты, необходимые для изготовления мази? Сами по себе олени не поправятся, так что нам лучше поспешить им на помощь!','Вернитесь к Аландариан Песне Ночи в Аубердин, что на Темных берегах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор лекарственных ингредиентов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Основой целительной мази для оленей послужит вода. Для придания ей целительных свойств мне понадобится земляной корень. Травники знают, где его искать, так что, если нам не повезло и ты не $gтравник:травница;, придется найти кого-то, кто сможет помочь.$B$BДля усиления воздействия мне нужны лунные грибы. Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно. В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будь $gосторожен:осторожна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 земляных корней и 12 лунных грибов Аландариан Песне Ночи в Аубердине, чтобы она могла сделать целительную мазь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N, вы принесли так много, что должно хватить на несколько больших доз мази – по крайней мере чтобы исцеление началось.$B$BИзготовление средств против ядов иногда бывает весьма сложным, поскольку каждый из них требует конкретного антидота для нейтрализации воздействия. Здорово было бы уметь в любой момент снимать отравление, не беспокоясь о конкретных ингредиентах, которые должен содержать антидот!$B$BА теперь позвольте мне приступить к работе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы собрали реагенты, необходимые для изготовления мази? Сами по себе олени не поправятся, так что нам лучше поспешить им на помощь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аландариан Песне Ночи в Аубердин, что на Темных берегах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6124,'Исцеление больных','Мази, изготовленной из реагентов, которые ты $gпринес:принесла; мне, $n, хватит на десять доз. Пока я работаю здесь, в деревне, пытаясь изготовить побольше этой мази, я хотела бы, чтобы ты $gпомог:помогла; нам начать исцеление. По всем Темным берегам встречаются больные олени. Используй мазь для исцеления их недуга.$B$BЯ уверена, что Дендрит Блеск Звезд из Лунной поляны захочет поговорить с тобой, когда работа будет закончена. Пожалуйста, передай благодарность жителей Аубердина Кругу Кенария... и позволь мне лично поблагодарить тебя за помощь!','Нанесите мазь исцеления животных на 10 больных оленей, обитающих на Темных берегах, – это должно их исцелить. По слухам, ареал обитания больных оленей – южнее реки Скалистой и севернее Аубердина, а далее – по всей области, вплоть до южных границ Темных берегов, где начинается Ясеневый лес.','Ты неплохо $Gпомог:помогла; мне, позаботившись о больных животных. Они невольные жертвы этой заразы, которая распространяется по нашим землям. В Дарнасе есть те, кто всерьез воспринимает опасность... но есть и те, кто игнорирует все знамения. Я надеюсь, ты не будешь столь же $Gслепым:слепой;, видя множество фактов прямо перед своим носом, $N.$B$BТы $Gдоказал:доказала;, что ты друг природы и Круга. Прими это как символ нашей признательности.','Вы выполнили то, о чем вас просил Аландариан Ночная Песня из Аубердина? Ваша работа не завершена, если это не так.','Вернитесь к Дендриту Блеску Звезд в Ночную Гавань, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исцеление больных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мази, изготовленной из реагентов, которые ты $gпринес:принесла; мне, $n, хватит на десять доз. Пока я работаю здесь, в деревне, пытаясь изготовить побольше этой мази, я хотела бы, чтобы ты $gпомог:помогла; нам начать исцеление. По всем Темным берегам встречаются больные олени. Используй мазь для исцеления их недуга.$B$BЯ уверена, что Дендрит Блеск Звезд из Лунной поляны захочет поговорить с тобой, когда работа будет закончена. Пожалуйста, передай благодарность жителей Аубердина Кругу Кенария... и позволь мне лично поблагодарить тебя за помощь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нанесите мазь исцеления животных на 10 больных оленей, обитающих на Темных берегах, – это должно их исцелить. По слухам, ареал обитания больных оленей – южнее реки Скалистой и севернее Аубердина, а далее – по всей области, вплоть до южных границ Темных берегов, где начинается Ясеневый лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты неплохо $Gпомог:помогла; мне, позаботившись о больных животных. Они невольные жертвы этой заразы, которая распространяется по нашим землям. В Дарнасе есть те, кто всерьез воспринимает опасность... но есть и те, кто игнорирует все знамения. Я надеюсь, ты не будешь столь же $Gслепым:слепой;, видя множество фактов прямо перед своим носом, $N.$B$BТы $Gдоказал:доказала;, что ты друг природы и Круга. Прими это как символ нашей признательности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы выполнили то, о чем вас просил Аландариан Ночная Песня из Аубердина? Ваша работа не завершена, если это не так.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дендриту Блеску Звезд в Ночную Гавань, что на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6125,'Власть над ядом','Ты $Gпознал:познала;, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами.$B$BТебе следует вернуться к Матренгилу Медвежьей Лапе в Дарнас, $n. Теперь, когда его $gученик усвоил данный ему:ученица усвоила данный ей; урок, он несомненно научит тебя новому могучему заклинанию.$B$BДо свидания, юный друид. Мы еще встретимся.','Вернитесь к Матренгилу Медвежьей Лапе в Анклав Кенария в Дарнасе.','С возвращением. Я следил за твоими успехами с тех самых пор, как ты $Gпокинул:покинула; нас, и, должен признаться, был изумлен, узнав о ситуации в Аубердине. Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие.$B$BТы благородно $Gпоступил:поступила; в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами. Используй ее во благо, $N... во благо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Власть над ядом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gпознал:познала;, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами.$B$BТебе следует вернуться к Матренгилу Медвежьей Лапе в Дарнас, $n. Теперь, когда его $gученик усвоил данный ему:ученица усвоила данный ей; урок, он несомненно научит тебя новому могучему заклинанию.$B$BДо свидания, юный друид. Мы еще встретимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Матренгилу Медвежьей Лапе в Анклав Кенария в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С возвращением. Я следил за твоими успехами с тех самых пор, как ты $Gпокинул:покинула; нас, и, должен признаться, был изумлен, узнав о ситуации в Аубердине. Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие.$B$BТы благородно $Gпоступил:поступила; в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами. Используй ее во благо, $N... во благо.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6126,'Новый урок','Теперь, $n, ты $Gготов:готова; узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты $gусвоил:усвоила; этот важный урок, посему тебе придется испытать на себе силу действия яда в полной мере. Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд – он ждет твоего прибытия, чтобы начать обучение.','Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.','Привет тебе друид, я вижу ты $Gготов:готова; получить знания излечения ядов.$B$BВидишь ли, мы столкнулись с определенными трудностями около Перекрестка в Степях, там распоясались животные, которые сеют своим ядом направо и налево, и нет на них никакой управы. Мы запросили Лунную Поляну о помощи...и надеюсь, ты, $Gтот:та;, кого мы ждали!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый урок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, $n, ты $Gготов:готова; узнать о ядах и о той власти, которой мы, друиды, над ними обладаем. Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар. Однако мы должны быть уверены, что ты $gусвоил:усвоила; этот важный урок, посему тебе придется испытать на себе силу действия яда в полной мере. Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звезд – он ждет твоего прибытия, чтобы начать обучение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Лунную поляну и поговорите с Дендритом Блеском Звезд в селении Ночная Гавань.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе друид, я вижу ты $Gготов:готова; получить знания излечения ядов.$B$BВидишь ли, мы столкнулись с определенными трудностями около Перекрестка в Степях, там распоясались животные, которые сеют своим ядом направо и налево, и нет на них никакой управы. Мы запросили Лунную Поляну о помощи...и надеюсь, ты, $Gтот:та;, кого мы ждали!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6127,'Основной источник','Вершина Багрового Тумана, что к северо-западу от Перекрестка – самый вероятный источник распространения этой отравы. На его вершине находятся озера воды, влияющие на перемены погоды. Подозреваю, что вода сейчас заражена демонопоклонниками из Пылающего Клинка.$B$BВозьми этот пробоотборник и набери воды из озера у самой вершины. Наполнив, доставь его Тонге Руническому Тотему в Перекресток. Именно он и просил нашей помощи, и ты будешь работать вместе с ним над искоренением этой заразы.','Используйте пустой пробоотборник Вершины Багрового Тумана для отбора воды из озера на вершине.$B$BДоставьте наполненный пробоотборник Вершины Багрового Тумана Тонге Руническому Тотему в Перекресток, что в Степях.','Во имя отцов-основателей, эта вода просто отвратительна! Неудивительно что газели больны.$B$BЧто-то загрязняет воду и превращает в руины экосистему северных Степей. Больные газели замечены на север по дороге отсюда. Пока мы не выявим источник заразы, у нас будет много работы здесь.$B$BА эта вода поможет нам найти причину заразы, в этом я уверен...','Это тебя прислал Круг Кенария Лунной поляны, да? Большая удача для нас! Мы выбиваемся из сил, пытаясь восстановить равновесие среди больных газелей, что блуждают в северных Степях. Мы рады любой помощи.$B$BТы $Gпринес:принесла; пробу воды, о которой говорил мне Дендрит Блеск Звезд? Он сказал, что ты принесешь воды, дабы мы могли приступить к трудам по исцелению тотчас же...','Вернитесь к Тонге Руническому Тотему в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Основной источник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вершина Багрового Тумана, что к северо-западу от Перекрестка – самый вероятный источник распространения этой отравы. На его вершине находятся озера воды, влияющие на перемены погоды. Подозреваю, что вода сейчас заражена демонопоклонниками из Пылающего Клинка.$B$BВозьми этот пробоотборник и набери воды из озера у самой вершины. Наполнив, доставь его Тонге Руническому Тотему в Перекресток. Именно он и просил нашей помощи, и ты будешь работать вместе с ним над искоренением этой заразы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте пустой пробоотборник Вершины Багрового Тумана для отбора воды из озера на вершине.$B$BДоставьте наполненный пробоотборник Вершины Багрового Тумана Тонге Руническому Тотему в Перекресток, что в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во имя отцов-основателей, эта вода просто отвратительна! Неудивительно что газели больны.$B$BЧто-то загрязняет воду и превращает в руины экосистему северных Степей. Больные газели замечены на север по дороге отсюда. Пока мы не выявим источник заразы, у нас будет много работы здесь.$B$BА эта вода поможет нам найти причину заразы, в этом я уверен...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это тебя прислал Круг Кенария Лунной поляны, да? Большая удача для нас! Мы выбиваемся из сил, пытаясь восстановить равновесие среди больных газелей, что блуждают в северных Степях. Мы рады любой помощи.$B$BТы $Gпринес:принесла; пробу воды, о которой говорил мне Дендрит Блеск Звезд? Он сказал, что ты принесешь воды, дабы мы могли приступить к трудам по исцелению тотчас же...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тонге Руническому Тотему в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6128,'Сбор лекарственных ингредиентов','Основой целебной мази для газелей послужит вода. Для придания ей целебных свойств мне понадобится земляной корень. Травники знают, где его отыскать, так что если нам не повезло, и ты – не $gтравник:травница;, придется попросить кого-то о помощи. $b$bДля силы воздействия мне нужны рога кодо – осколки и куски не подойдут. Кодо живут в северной части Степей. Убей несколько зверюг, заодно и природное равновесие восстановится. Отпили у них рога и принеси мне.','Принесите 5 земляных корней и 5 рогов кодо Тонге Руническому Тотему в Перекресток, и он сделает целебную мазь.','Отлично, $N, вы принесли так много, что должно хватить на несколько больших доз мази – по крайней мере чтобы исцеление началось.$B$BИзготовление средств против ядов иногда бывает весьма сложным, поскольку каждый из них требует конкретного антидота для нейтрализации воздействия. Здорово было бы уметь в любой момент снимать отравление, не беспокоясь о конкретных ингредиентах, которые должен содержать антидот!$B$BА теперь позвольте мне приступить к работе!','Ты $Gсобрал:собрала; реагенты, необходимые для изготовления мази? Сами по себе газели не поправятся, так что нам лучше поспешить к ним на помощь!','Вернитесь к Тонге Руническому Тотему в Степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор лекарственных ингредиентов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Основой целебной мази для газелей послужит вода. Для придания ей целебных свойств мне понадобится земляной корень. Травники знают, где его отыскать, так что если нам не повезло, и ты – не $gтравник:травница;, придется попросить кого-то о помощи. $b$bДля силы воздействия мне нужны рога кодо – осколки и куски не подойдут. Кодо живут в северной части Степей. Убей несколько зверюг, заодно и природное равновесие восстановится. Отпили у них рога и принеси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 земляных корней и 5 рогов кодо Тонге Руническому Тотему в Перекресток, и он сделает целебную мазь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N, вы принесли так много, что должно хватить на несколько больших доз мази – по крайней мере чтобы исцеление началось.$B$BИзготовление средств против ядов иногда бывает весьма сложным, поскольку каждый из них требует конкретного антидота для нейтрализации воздействия. Здорово было бы уметь в любой момент снимать отравление, не беспокоясь о конкретных ингредиентах, которые должен содержать антидот!$B$BА теперь позвольте мне приступить к работе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсобрал:собрала; реагенты, необходимые для изготовления мази? Сами по себе газели не поправятся, так что нам лучше поспешить к ним на помощь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тонге Руническому Тотему в Степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6129,'Исцеление больных','Мне удалось сделать десять доз целебной мази. Пока я работаю здесь, в деревне, пытаясь изготовить побольше, я хотела бы, чтобы ты $gпомог:помогла; нам лечить бедных зверей. По всей северной части Степей бродят больные газели. Исцели их недуг при помощи этой мази.$b$bЯ уверен, что Дендрит Блеск Звезд на Лунной поляне захочет поговорить с тобой, когда ты закончишь. Пожалуйста, передай нашу благодарность Кругу Кенария... и позволь мне поблагодарить тебя лично за неоценимую помощь!','Нанесите мазь исцеления животных на 10 больных газелей, обитающих в северной части Степей, – это должно их вылечить. По слухам, больные газели живут севернее дороги, проходящей через Перекресток с востока на запад.','Ты $Gпоступил:поступила; хорошо с больными газелями Степей, ведь они невинные жертвы заразы, что распростерлась над этим и другими континентами. Ты $Gсделал:сделала; еще один шаг по пути Кенария. Старейшины в Громовом Утесе будут рады услышать весть о тебе.$B$B$N, ты, как наш друг и друг Круга, $Gдостоин:достойна; награды. Возьми же ее.','Вы выполнили то, о чем вас просил Тонга Рунический Тотем на Перекрестке? Ваша работа не завершена, если это не так.','Вернитесь к Дендриту Блеску Звезд в Ночную Гавань, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исцеление больных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне удалось сделать десять доз целебной мази. Пока я работаю здесь, в деревне, пытаясь изготовить побольше, я хотела бы, чтобы ты $gпомог:помогла; нам лечить бедных зверей. По всей северной части Степей бродят больные газели. Исцели их недуг при помощи этой мази.$b$bЯ уверен, что Дендрит Блеск Звезд на Лунной поляне захочет поговорить с тобой, когда ты закончишь. Пожалуйста, передай нашу благодарность Кругу Кенария... и позволь мне поблагодарить тебя лично за неоценимую помощь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нанесите мазь исцеления животных на 10 больных газелей, обитающих в северной части Степей, – это должно их вылечить. По слухам, больные газели живут севернее дороги, проходящей через Перекресток с востока на запад.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпоступил:поступила; хорошо с больными газелями Степей, ведь они невинные жертвы заразы, что распростерлась над этим и другими континентами. Ты $Gсделал:сделала; еще один шаг по пути Кенария. Старейшины в Громовом Утесе будут рады услышать весть о тебе.$B$B$N, ты, как наш друг и друг Круга, $Gдостоин:достойна; награды. Возьми же ее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы выполнили то, о чем вас просил Тонга Рунический Тотем на Перекрестке? Ваша работа не завершена, если это не так.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дендриту Блеску Звезд в Ночную Гавань, что на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6130,'Власть над ядом','Ты $Gпознал:познала;, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами.$B$BТебе следует вернуться к Тюраку Руническому Тотему в Громовой Утес, $n. Теперь, когда его $gученик усвоил данный ему:ученица усвоила данный ей; урок, он несомненно научит тебя новому могучему заклинанию.$B$BДо свидания, юный друид. Мы еще встретимся.','Вернитесь к Тюраку Руническому Тотему на Вершину Старейшин в Громовой Утес.','С возвращением... я следил за твоим прогрессом... но сейчас, знаешь ли, я больше обеспокоен ситуацией вокруг Перекрестка. Эта ситуация требует твоего вмешательства.$B$BНо! Проявленное тобой усердие не останется без вознаграждения. Пока же я не могу найти лучшего пути, чем вознаградить тебя властью над ядами. Используй ее достойно, $N') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Власть над ядом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gпознал:познала;, что значит исцелять от действия яда без помощи духов. Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами.$B$BТебе следует вернуться к Тюраку Руническому Тотему в Громовой Утес, $n. Теперь, когда его $gученик усвоил данный ему:ученица усвоила данный ей; урок, он несомненно научит тебя новому могучему заклинанию.$B$BДо свидания, юный друид. Мы еще встретимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Тюраку Руническому Тотему на Вершину Старейшин в Громовой Утес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С возвращением... я следил за твоим прогрессом... но сейчас, знаешь ли, я больше обеспокоен ситуацией вокруг Перекрестка. Эта ситуация требует твоего вмешательства.$B$BНо! Проявленное тобой усердие не останется без вознаграждения. Пока же я не могу найти лучшего пути, чем вознаградить тебя властью над ядами. Используй ее достойно, $N',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (6131,'Союзник Древобрюхов','Древобрюхи – единственное фурболгское племя, не затронутое порчей. Однако нынче многие расы без разбору убивают всех фурболгов подряд. И потому фурболгов из племени Древобрюха осталось так мало.$B$BХочешь заслужить наше доверие? Изгони из Оскверненного леса пораженных порчей фурболгов Мертвого Леса, и в один прекрасный день мы признаем тебя союзником. Ты найдешь первое племя Мертвого Леса – воинов, землепроходцев и садовников – к западу от меня.','Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 5 воинов 5 землепроходцев и 5 садовников из племени Мертвого Леса.','Мы очень страдаем от событий прошлого. Спасибо за то, что ты $Gсделал:сделала;, чтобы защитить Древобрюх.','Вернитесь к Гразлу в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союзник Древобрюхов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древобрюхи – единственное фурболгское племя, не затронутое порчей. Однако нынче многие расы без разбору убивают всех фурболгов подряд. И потому фурболгов из племени Древобрюха осталось так мало.$B$BХочешь заслужить наше доверие? Изгони из Оскверненного леса пораженных порчей фурболгов Мертвого Леса, и в один прекрасный день мы признаем тебя союзником. Ты найдешь первое племя Мертвого Леса – воинов, землепроходцев и садовников – к западу от меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 5 воинов 5 землепроходцев и 5 садовников из племени Мертвого Леса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы очень страдаем от событий прошлого. Спасибо за то, что ты $Gсделал:сделала;, чтобы защитить Древобрюх.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гразлу в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6132,'Вытащи меня отсюда!','Вытащи меня отсюда!$B$BЯ отправилась к Долине Копий, чтобы поговорить с Мародинами. Мне казалось, с ними можно вести кое-какие дела... Но они не желают говорить со мной! Мне кажется, они... они хотят съесть меня!$B$BТолько вытащи меня отсюда – вот увидишь, мой брат Хорниц тебе кучу денег отвалит! А найти-то его несложно: он в нашем лагере, к востоку отсюда, там еще Кладбище кодо рядом.$B$BНам лучше поторопиться, $n: буквально пару минут назад я слышала, как два кентавра говорили, что нужно собрать дрова для готовки...','Проводите Мелиццу Жужжалит.','Моя сестра Мелисса предупредила меня о твоем приходе. Хочу тебя поблагодарить за то, что вытащил ее из очередной беды. Правда, боюсь, она уже успела вязаться во что-то новое...','Тебе не встречалась моя сестра Мелисса? Вечно она где-то гуляет... До добра это не доведет!','Проводите Мелиццу Жужжалит.','Поговорите с Хорницем Жужжалитом на кладбище кодо в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вытащи меня отсюда!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вытащи меня отсюда!$B$BЯ отправилась к Долине Копий, чтобы поговорить с Мародинами. Мне казалось, с ними можно вести кое-какие дела... Но они не желают говорить со мной! Мне кажется, они... они хотят съесть меня!$B$BТолько вытащи меня отсюда – вот увидишь, мой брат Хорниц тебе кучу денег отвалит! А найти-то его несложно: он в нашем лагере, к востоку отсюда, там еще Кладбище кодо рядом.$B$BНам лучше поторопиться, $n: буквально пару минут назад я слышала, как два кентавра говорили, что нужно собрать дрова для готовки...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите Мелиццу Жужжалит.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моя сестра Мелисса предупредила меня о твоем приходе. Хочу тебя поблагодарить за то, что вытащил ее из очередной беды. Правда, боюсь, она уже успела вязаться во что-то новое...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе не встречалась моя сестра Мелисса? Вечно она где-то гуляет... До добра это не доведет!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводите Мелиццу Жужжалит.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хорницем Жужжалитом на кладбище кодо в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6133,'Охота на cледопытов','Высшие эльфы в Сторожке Кель\'Литиен присвоили себе кое-что, что принадлежит мне, |3-6($c). Это документ, описывающий мою смертную жизнь. $B$BНет, к тебе его содержимое не имеет никакого отношения – даже не вздумай сунуть туда нос! Твое дело маленькое – принеси мне документ!$B$BИ имей в виду, тупица, я хочу, чтобы эти негодяи пожалели, что наложили свои лапы на мою частную собственность! Нанеси им как можно больший ущерб!','Отправляйтесь в северные пределы Восточных Чумных земель и заполучите реестр Кель\'Таласа. Документ находится где-то в Сторожке Кель\'Литиен.$B$BТакже убейте 8 следопытов, 8 разведчиц дорог и 8 лесников.','Я думаю, что ты не $Gчитал:читала; реестр. Никто даже ты не сделает такой глупости.','Не заставляй меня ждать, $C!','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на cледопытов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Высшие эльфы в Сторожке Кель\'Литиен присвоили себе кое-что, что принадлежит мне, |3-6($c). Это документ, описывающий мою смертную жизнь. $B$BНет, к тебе его содержимое не имеет никакого отношения – даже не вздумай сунуть туда нос! Твое дело маленькое – принеси мне документ!$B$BИ имей в виду, тупица, я хочу, чтобы эти негодяи пожалели, что наложили свои лапы на мою частную собственность! Нанеси им как можно больший ущерб!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в северные пределы Восточных Чумных земель и заполучите реестр Кель\'Таласа. Документ находится где-то в Сторожке Кель\'Литиен.$B$BТакже убейте 8 следопытов, 8 разведчиц дорог и 8 лесников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я думаю, что ты не $Gчитал:читала; реестр. Никто даже ты не сделает такой глупости.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не заставляй меня ждать, $C!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6134,'Сбор эктоплазмы','Соберите 8 единиц эктоплазмы.','Поговорите с Хорницем Жужжалитом в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор эктоплазмы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 единиц эктоплазмы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Хорницем Жужжалитом в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6135,'Проклятый Тенекрыл','Пока тебе удается с горем пополам выполнять мои поручения.$B$BПора бы заставить тебя сделать что-нибудь посложнее. Да, тупица, ты $gдозрел:дозрела; до настоящей работенки.$B$BВот что, выследи и убей Тенекрыла – это чудовищная летучая мышь-альбинос, которая хозяйничает в землях к северу отсюда. И принеси мне клок его белой шерсти – чтоб я знал, что ты не врешь!','Выследите Тенекрыла и убейте его. Принесите полоску меха Тенекрыла Натаносу Гнилостню.$B$BГоворят, Тенекрыл рыщет в землях к северу от имения Марриса.','Прекрасная работа, $Gглупец:глупая;. Я сделаю из ее меха кое-что полезное.','Не советую соваться к твари в одиночку, $C.','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятый Тенекрыл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока тебе удается с горем пополам выполнять мои поручения.$B$BПора бы заставить тебя сделать что-нибудь посложнее. Да, тупица, ты $gдозрел:дозрела; до настоящей работенки.$B$BВот что, выследи и убей Тенекрыла – это чудовищная летучая мышь-альбинос, которая хозяйничает в землях к северу отсюда. И принеси мне клок его белой шерсти – чтоб я знал, что ты не врешь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выследите Тенекрыла и убейте его. Принесите полоску меха Тенекрыла Натаносу Гнилостню.$B$BГоворят, Тенекрыл рыщет в землях к северу от имения Марриса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасная работа, $Gглупец:глупая;. Я сделаю из ее меха кое-что полезное.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не советую соваться к твари в одиночку, $C.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6136,'Огромный червь','За лагерем Серебряного Рассвета и часовней Последней Надежды, к западу от Северного Дола обитает огромный червь, Мерзкослиз.$B$BЯ потерял целые батальоны в попытках уничтожить его. Его размеры невообразимы! Чем больше он ест, тем больше растет...$B$BХотя я, в общем-то, мало волнуюсь по поводу того, сожрет ли тебя червь, должен признать, что предпочел бы, чтобы ты $gвышел победителем:вышла победительницей;. Учти, Мерзкослиз особенно охотно жрет тех, кто попытался напасть на него.','Найдите и уничтожьте Мерзкослиза в северных пустошах Восточных Чумных земель. Возвращайтесь к Натаносу Гнилостню по выполнению задания.','Как же ты меня $Gдостал:достала;!','О, да ты делаешь успехи! Такими темпами скоро получишь повышение – от полного имбецила до недоумка.','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огромный червь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За лагерем Серебряного Рассвета и часовней Последней Надежды, к западу от Северного Дола обитает огромный червь, Мерзкослиз.$B$BЯ потерял целые батальоны в попытках уничтожить его. Его размеры невообразимы! Чем больше он ест, тем больше растет...$B$BХотя я, в общем-то, мало волнуюсь по поводу того, сожрет ли тебя червь, должен признать, что предпочел бы, чтобы ты $gвышел победителем:вышла победительницей;. Учти, Мерзкослиз особенно охотно жрет тех, кто попытался напасть на него.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и уничтожьте Мерзкослиза в северных пустошах Восточных Чумных земель. Возвращайтесь к Натаносу Гнилостню по выполнению задания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как же ты меня $Gдостал:достала;!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, да ты делаешь успехи! Такими темпами скоро получишь повышение – от полного имбецила до недоумка.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6141,'Брат Антон','Антон, мой собрат по оружию, услышал вести о нашествии нежити в далеком Калимдоре, в тех землях, что называются Пустошами. Конечно же, он немедленно собрался в путь, чтобы покончить с этой угрозой!$B$BОн ищет отважных и решительных спутников – тех, у кого хватит храбрости сражаться с ним плечом к плечу. Если ты хранишь чистоту в своем сердце, разыщи брата Антона в городе, носящем имя Высоты Найджела, в Пустошах.','Найдите в Пустошах брата Антона и поговорите с ним.','Я получил вести о помощи, грядущей с востока. Не о тебе ли шла речь? Ты пришел сюда, дабы помочь Алым в нашем благородном походе?$B$BЕсли это так, то слушай...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брат Антон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Антон, мой собрат по оружию, услышал вести о нашествии нежити в далеком Калимдоре, в тех землях, что называются Пустошами. Конечно же, он немедленно собрался в путь, чтобы покончить с этой угрозой!$B$BОн ищет отважных и решительных спутников – тех, у кого хватит храбрости сражаться с ним плечом к плечу. Если ты хранишь чистоту в своем сердце, разыщи брата Антона в городе, носящем имя Высоты Найджела, в Пустошах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Пустошах брата Антона и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я получил вести о помощи, грядущей с востока. Не о тебе ли шла речь? Ты пришел сюда, дабы помочь Алым в нашем благородном походе?$B$BЕсли это так, то слушай...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6142,'Наживка из моллюска','Судя по виду, |3-6($c), ты – $Gзаядлый рыбак:заядлая рыбачка;! Обожаю ловить рыбу, всю жизнь этим занимаюсь. Можешь мне поверить, нет лучшей наживки, чем мясо мягкотелого моллюска: рыба просто не может против нее устоять, если ты понимаешь, о чем я.$B$BНа север отсюда, неподалеку от берега, есть потерпевший крушение корабль: так вот, вокруг него эти моллюски так и кишат! Принесешь мне 10 кусочков мяса моллюска – а взамен я тебе дам кое-что полезное...','Найдите 10 кусочков мяса мягкотелого моллюска и принесите Май\'Лахии в Деревню Ночных Охотников.','Это просто великолепно!.. Когда я спросила у знахаря, как лечить головную боль, он мне ответил: Май\'Лахия, детка, попробуй половить рыбку в мутной воде; увидишь – тебе сразу полегчает!\n\nОх, как подумаю – мне и правда сразу легче становится!','Поскорее бы порыбачить на наживку из мяса моллюсков!.. Ты ведь принес мне 10 наживок, как я просила?','Вернитесь к Май\'лахии в Деревню Ночных Охотников, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наживка из моллюска',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по виду, |3-6($c), ты – $Gзаядлый рыбак:заядлая рыбачка;! Обожаю ловить рыбу, всю жизнь этим занимаюсь. Можешь мне поверить, нет лучшей наживки, чем мясо мягкотелого моллюска: рыба просто не может против нее устоять, если ты понимаешь, о чем я.$B$BНа север отсюда, неподалеку от берега, есть потерпевший крушение корабль: так вот, вокруг него эти моллюски так и кишат! Принесешь мне 10 кусочков мяса моллюска – а взамен я тебе дам кое-что полезное...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 10 кусочков мяса мягкотелого моллюска и принесите Май\'Лахии в Деревню Ночных Охотников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это просто великолепно!.. Когда я спросила у знахаря, как лечить головную боль, он мне ответил: Май\'Лахия, детка, попробуй половить рыбку в мутной воде; увидишь – тебе сразу полегчает!\n\nОх, как подумаю – мне и правда сразу легче становится!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поскорее бы порыбачить на наживку из мяса моллюсков!.. Ты ведь принес мне 10 наживок, как я просила?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Май\'лахии в Деревню Ночных Охотников, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6143,'Смерть земноводным!','Может, ты $Gслышал:слышала;, может, нет... Мы с командой рыбачили неподалеку от острова Раназжар, к северу от разбитого корабля на северном побережье. Мы всегда там рыбачили, сколько я себя помню – а теперь я ни о чем другом не могу думать, кроме как о мести за своих друзей...$B$BОднажды утром на нас напали наги. Они убили всех, кроме меня!..$B$BЯ не могу вынести бремени этой вины, |3-6($c), пойми меня: ты $Gнужен:нужна; мне, чтобы расправиться с проклятыми нагами. Поверь, я хорошо вознагражу тебя. Ты ведь возьмешься за это дело?','Убейте 7 мирмидонов, 7 наг и 5 колдуний из клана Скользящего Плавника, а затем вернитесь в деревню Сумеречной Охоты и поговорите с Друлзегаром.','Ты говоришь, эти мерзкие твари мертвы? Да, месть сладка... Но в моем сердце по-прежнему пустота, которой ничто не заполнит. Я посвящу всю свою жизнь тому, чтобы извести нагов под корень – весь их род до последнего змееныша!..\n\nВот, дружище, держи свою награду, как я и обещал – хотя она ничтожно мала в сравнении с моей благодарностью...','Ты нашел Скипетр Света? Он у тебя?','Вернитесь к Друльзегару Скрюг-скраку в Деревню Ночных Охотников, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть земноводным!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может, ты $Gслышал:слышала;, может, нет... Мы с командой рыбачили неподалеку от острова Раназжар, к северу от разбитого корабля на северном побережье. Мы всегда там рыбачили, сколько я себя помню – а теперь я ни о чем другом не могу думать, кроме как о мести за своих друзей...$B$BОднажды утром на нас напали наги. Они убили всех, кроме меня!..$B$BЯ не могу вынести бремени этой вины, |3-6($c), пойми меня: ты $Gнужен:нужна; мне, чтобы расправиться с проклятыми нагами. Поверь, я хорошо вознагражу тебя. Ты ведь возьмешься за это дело?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 мирмидонов, 7 наг и 5 колдуний из клана Скользящего Плавника, а затем вернитесь в деревню Сумеречной Охоты и поговорите с Друлзегаром.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты говоришь, эти мерзкие твари мертвы? Да, месть сладка... Но в моем сердце по-прежнему пустота, которой ничто не заполнит. Я посвящу всю свою жизнь тому, чтобы извести нагов под корень – весь их род до последнего змееныша!..\n\nВот, дружище, держи свою награду, как я и обещал – хотя она ничтожно мала в сравнении с моей благодарностью...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел Скипетр Света? Он у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Друльзегару Скрюг-скраку в Деревню Ночных Охотников, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6144,'Приказ по армии','Мы получили приказ,|3-6($c). Сам Вариматас требует, чтобы я прислал ему наиболее способных солдат в Подгород для выполнения крайне сложной операции. $B$BУвы, самые достойные и способные давно погибли, а вместо них я располагаю кучкой жалких недоумков.$B$B*Натанос окидывает вас ледяным взглядом*$B$BПредстанешь перед Вариматасом в Подгороде. Смотри, не опозорь меня, |3-6($c)!','Отправляйтесь в Подгород и поговорите с Брагором Кровопалом.','Верховный рыцарь сидит в безопасности в Алом Бастионе, пока его войска наводняют наши земли страхом и убивают наших... людей.$B$BТемная Леди приказывает разобраться с этими самоявленными крестоносцами раз и навсегда. Ты будешь инструментом отмщения для Отрекшихся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ по армии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы получили приказ,|3-6($c). Сам Вариматас требует, чтобы я прислал ему наиболее способных солдат в Подгород для выполнения крайне сложной операции. $B$BУвы, самые достойные и способные давно погибли, а вместо них я располагаю кучкой жалких недоумков.$B$B*Натанос окидывает вас ледяным взглядом*$B$BПредстанешь перед Вариматасом в Подгороде. Смотри, не опозорь меня, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Подгород и поговорите с Брагором Кровопалом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Верховный рыцарь сидит в безопасности в Алом Бастионе, пока его войска наводняют наши земли страхом и убивают наших... людей.$B$BТемная Леди приказывает разобраться с этими самоявленными крестоносцами раз и навсегда. Ты будешь инструментом отмщения для Отрекшихся.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6145,'Курьер из Багрового Легиона','Возвращайтесь в Восточные Чумные земли и выследите курьера из Багрового Легиона. Убейте его и заберите приказ верховного рыцаря.$B$BЗа дальнейшими указаниями обращайтесь к Натаносу Гнилостню.','<Натанос смеется.>$B$BНаконец-то! Ура! Шанс уничтожить Алого Оракула!','Если ты справишься с этой задачей, можешь считать, что почти заслужил мое уважение, $C.','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Курьер из Багрового Легиона',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь в Восточные Чумные земли и выследите курьера из Багрового Легиона. Убейте его и заберите приказ верховного рыцаря.$B$BЗа дальнейшими указаниями обращайтесь к Натаносу Гнилостню.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Натанос смеется.>$B$BНаконец-то! Ура! Шанс уничтожить Алого Оракула!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты справишься с этой задачей, можешь считать, что почти заслужил мое уважение, $C.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6146,'Уловка Натаноса','Я тут немного подрихтовал приказ. Если наша маленькая уловка сработает, Алый Оракул на некоторое время окажется почти без защиты. Тут-то мы и нанесем удар!$B$BТеперь слушай внимательно, |3-6($c). Доставишь приказ лорду-рыцарю Валдермару.$B$BЧто значит как?! Лично в руки, тупица!$B$BДержи приказ и это гнилое яблоко – съешь его, когда войдешь в город. Оно... э-э... придаст тебе более приятный для человеческого глаза вид. Запомни, лично в руки лорду-рыцарю Валдермару!','Отправляйтесь в Длань Тира к юго-востоку от Поместья Маррисов. Прибыв в город, откусите от гнилого яблока. Под личиной рыцаря Алого ордена доставьте приказ верховного рыцаря лорду-рыцарю Валдермару.','Где ты $Gбыл:была;? Мы думали, что Плеть захватила тебя.','Не ныть, солдат! Приказы не обсуждаются!','Вернитесь к лорд-рыцарю Валделмару на Руины анклава Алого ордена, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уловка Натаноса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тут немного подрихтовал приказ. Если наша маленькая уловка сработает, Алый Оракул на некоторое время окажется почти без защиты. Тут-то мы и нанесем удар!$B$BТеперь слушай внимательно, |3-6($c). Доставишь приказ лорду-рыцарю Валдермару.$B$BЧто значит как?! Лично в руки, тупица!$B$BДержи приказ и это гнилое яблоко – съешь его, когда войдешь в город. Оно... э-э... придаст тебе более приятный для человеческого глаза вид. Запомни, лично в руки лорду-рыцарю Валдермару!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Длань Тира к юго-востоку от Поместья Маррисов. Прибыв в город, откусите от гнилого яблока. Под личиной рыцаря Алого ордена доставьте приказ верховного рыцаря лорду-рыцарю Валдермару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Где ты $Gбыл:была;? Мы думали, что Плеть захватила тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не ныть, солдат! Приказы не обсуждаются!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорд-рыцарю Валделмару на Руины анклава Алого ордена, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6147,'Назад к Натаносу','Верховный рыцарь прислал очень странный приказ... Однако приказы не обсуждаются. Возвращайся в Бастион Алого ордена и сообщи, что Оракул выдвигается немедленно.$B$BМы приложим все усилия, чтобы доставить его в Стратхольм в целости и сохранности.','Возвращайтесь к Натаносу Гнилостню и отчитайтесь о выполнении задания.','Глупцы! Мой обман остался незамеченным! Приготовься, $C. Мы должны нанести удар с холодной хитростью!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад к Натаносу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный рыцарь прислал очень странный приказ... Однако приказы не обсуждаются. Возвращайся в Бастион Алого ордена и сообщи, что Оракул выдвигается немедленно.$B$BМы приложим все усилия, чтобы доставить его в Стратхольм в целости и сохранности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к Натаносу Гнилостню и отчитайтесь о выполнении задания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Глупцы! Мой обман остался незамеченным! Приготовься, $C. Мы должны нанести удар с холодной хитростью!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6148,'Алый Оракул Деметрия','Деметрия – главный советник верховного рыцаря. Ее величают Оракулом за ее сверхъестественные способности. Она неоднократно оказывала помощь Алому ордену в боях с Плетью.$B$BПосмотрим, в самом ли деле ей открыто будущее... Уверен, она предвидела, что ее ждут неприятности. Вот ты их ей и обеспечишь!$B$BВыследи Оракула и убей ее. Полагаю, сейчас она на пути к Длани Тира. Не подведи меня, насекомое!','Алый орден сейчас в пути. Найдите Оракула Деметрию и ее свиту на дороге от Длани Тира в Стратхольм. Убейте Оракула и возвращайтесь к Натаносу Гнилостню.','Я ждал этого момента годами... $GМолодец:Умница;, $N! Ты не только $Gзаслужил:заслужила; мое уважение, но и награду!','Тебе удалось убить ее?','Return to Nathanos Blightcaller at Marris Stead in Eastern Plaguelands.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Алый Оракул Деметрия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Деметрия – главный советник верховного рыцаря. Ее величают Оракулом за ее сверхъестественные способности. Она неоднократно оказывала помощь Алому ордену в боях с Плетью.$B$BПосмотрим, в самом ли деле ей открыто будущее... Уверен, она предвидела, что ее ждут неприятности. Вот ты их ей и обеспечишь!$B$BВыследи Оракула и убей ее. Полагаю, сейчас она на пути к Длани Тира. Не подведи меня, насекомое!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Алый орден сейчас в пути. Найдите Оракула Деметрию и ее свиту на дороге от Длани Тира в Стратхольм. Убейте Оракула и возвращайтесь к Натаносу Гнилостню.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я ждал этого момента годами... $GМолодец:Умница;, $N! Ты не только $Gзаслужил:заслужила; мое уважение, но и награду!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось убить ее?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to Nathanos Blightcaller at Marris Stead in Eastern Plaguelands.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (6161,'Сокровища Ракмора','Записи Ракмора рассказывают о том, как во время плаванья к Крепости Оперенной Луны его корабль был атакован морскими тварями. Чтобы не дать врагу завладеть его сокровищем, Ракмор спрятал сундук на острове Раназжар.$B$BОткрыть сундук можно только двумя ключами, золотым и серебряным. Они были утрачены, но если разыскать и сундук, и оба ключа – кто знает, какие сокровища откроются счастливцу?','Найдите серебряный и золотой ключи Ракмора, а затем разыщите и отоприте сундук Ракмора.','Сундук открывается. Перед вами сокровище Ракмора!','Сундук надежно заперт...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровища Ракмора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Записи Ракмора рассказывают о том, как во время плаванья к Крепости Оперенной Луны его корабль был атакован морскими тварями. Чтобы не дать врагу завладеть его сокровищем, Ракмор спрятал сундук на острове Раназжар.$B$BОткрыть сундук можно только двумя ключами, золотым и серебряным. Они были утрачены, но если разыскать и сундук, и оба ключа – кто знает, какие сокровища откроются счастливцу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите серебряный и золотой ключи Ракмора, а затем разыщите и отоприте сундук Ракмора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сундук открывается. Перед вами сокровище Ракмора!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сундук надежно заперт...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6162,'Последняя битва супруга','Мой супруг ради чести нашего клана отправился в Оскверненный лес, чтобы сразиться с Советом Теней и прочими мерзостными тварями!$B$BОн несколько раз избегал смерти. Потом я получила письмо от него, в котором он говорил, что некий друид попросил у него помощи против огромного пораженного порчей фурболга по имени Рор – и с тех пор я не слышала больше ни о муже, ни о друиде.$B$BЯ хочу, чтобы ты $gпринес:принесла; мне отрубленную когтистую лапу этого Рора, $n! Я жажду мести за мое вдовство! Эта тварь, как я знаю, засела где-то на юге, возле границы Ясеневого леса.','Убейте властителя Рора и принесите его коготь Дрейка\'Сур на Заставу Отравленной Крови в Оскверненном лесу.','Ты $R чести... а также слова... Мой муж погиб в битве, но я не могла успокоиться, пока не узнала, что существо, которое погубило его, получило то же самое.$B$BСпасибо тебе, $N','Где коготь этой твари, $N? Он заплатит за свои преступления! Мне плевать, из-за порчи это или просто со злости, что он живет в таком поганом лесу! Никакому фурболгу не прощу зла, причиненного моей семье!','Вернитесь к Дрека\'сур на Заставу Отравленной Крови, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя битва супруга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой супруг ради чести нашего клана отправился в Оскверненный лес, чтобы сразиться с Советом Теней и прочими мерзостными тварями!$B$BОн несколько раз избегал смерти. Потом я получила письмо от него, в котором он говорил, что некий друид попросил у него помощи против огромного пораженного порчей фурболга по имени Рор – и с тех пор я не слышала больше ни о муже, ни о друиде.$B$BЯ хочу, чтобы ты $gпринес:принесла; мне отрубленную когтистую лапу этого Рора, $n! Я жажду мести за мое вдовство! Эта тварь, как я знаю, засела где-то на юге, возле границы Ясеневого леса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте властителя Рора и принесите его коготь Дрейка\'Сур на Заставу Отравленной Крови в Оскверненном лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $R чести... а также слова... Мой муж погиб в битве, но я не могла успокоиться, пока не узнала, что существо, которое погубило его, получило то же самое.$B$BСпасибо тебе, $N',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где коготь этой твари, $N? Он заплатит за свои преступления! Мне плевать, из-за порчи это или просто со злости, что он живет в таком поганом лесу! Никакому фурболгу не прощу зла, причиненного моей семье!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дрека\'сур на Заставу Отравленной Крови, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6163,'Рамштайн','На этом самом месте я когда-то держал оборону Лордерона... Бесчисленное воинство Плети прошло волной по моей ферме, уничтожив все живое на своем пути.$B$BГрязь. Скверна. Я стал беспомощной и безвольной игрушкой в руках Плети, оказавшись в рядах нежити. Сознанием моим управляла воля Короля-лича. $B$BА потом она освободила меня... Я ждал, я надеялся и наконец обрел свободу.$B$BТеперь я хочу отомстить чудовищу, забравшему мою жизнь. Убей его!','Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира.','Я удивляюсь... пощада? Какая пощада может быть такому...? <Натанос спеленывает.>$B$BЯ повешу голову этой уродца у себя на стене. Теперь ты $Gравен:равна; моим чемпионам','Когда Сильвана освободила меня, я гонялся за тварью, убившей меня, многие месяцы, но безрезультатно. Чудовище укрылось в Стратхольме...','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рамштайн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом самом месте я когда-то держал оборону Лордерона... Бесчисленное воинство Плети прошло волной по моей ферме, уничтожив все живое на своем пути.$B$BГрязь. Скверна. Я стал беспомощной и безвольной игрушкой в руках Плети, оказавшись в рядах нежити. Сознанием моим управляла воля Короля-лича. $B$BА потом она освободила меня... Я ждал, я надеялся и наконец обрел свободу.$B$BТеперь я хочу отомстить чудовищу, забравшему мою жизнь. Убей его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Стратхольм и убейте Рамштайна Ненасытного. Принесите его голову Натаносу в качестве сувенира.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я удивляюсь... пощада? Какая пощада может быть такому...? <Натанос спеленывает.>$B$BЯ повешу голову этой уродца у себя на стене. Теперь ты $Gравен:равна; моим чемпионам',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда Сильвана освободила меня, я гонялся за тварью, убившей меня, многие месяцы, но безрезультатно. Чудовище укрылось в Стратхольме...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаносу Гнилостню в Поместье Маррисов, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6164,'Книга рецептов Августа','Пожалуй, я готов открыть лавку...$B$BО нет! Моя книга рецептов! Мне не обойтись без нее!$B$BКажется, я оставил ее где-то в городе... Да, видимо, в таверне, в которой останавливался!$B$BПринеси мне мою книгу, умоляю, принеси мне ее! А когда открою лавку, ты увидишь, что цены у меня просто БЕЗУМНЫЕ!','Найдите книгу рецептов Августа Помешанного в таверне в Долине Ужаса.','Вот она! Какое счастье! Это безумно счастливый день, $N!','Ты $Gнашел:нашла; книгу? Лавка простаивает!','Вернитесь к Августу Помешанному в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Книга рецептов Августа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуй, я готов открыть лавку...$B$BО нет! Моя книга рецептов! Мне не обойтись без нее!$B$BКажется, я оставил ее где-то в городе... Да, видимо, в таверне, в которой останавливался!$B$BПринеси мне мою книгу, умоляю, принеси мне ее! А когда открою лавку, ты увидишь, что цены у меня просто БЕЗУМНЫЕ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите книгу рецептов Августа Помешанного в таверне в Долине Ужаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот она! Какое счастье! Это безумно счастливый день, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; книгу? Лавка простаивает!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Августу Помешанному в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (6165,'<NYI> <TXT>Останки верховного мага Тимолеана') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI> <TXT>Останки верховного мага Тимолеана',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (6181,'Срочное сообщение','Хотя мы не получаем серьезной помощи напрямую из Штормграда, у меня в городе есть знакомый, снабжающий нас доспехами. Зовут его Озрик Штранг. Его магазин, "Ограниченная неуязвимость", находится в Старом городе.$b$bНаши запасы доспехов заканчиваются, и я должен связаться с Озриком, чтобы попросить еще. Можете ли вы передать ему эту записку?$bБыстрее всего добраться до Штормграда можно с помощью Тора, нашего укротителя грифонов. Он находится прямо у подножия этого холма. Приходите к нему с моей запиской, а затем летите на грифоне в Штормград.','Отнесите записку Льюиса укротителю грифонов Тору.','Вам нужно доставить эту записку в Штормград? Это не проблема, вы можете взять одного из моих грифонов!','Такое ощущение, что вы сильно торопитесь. Что ж, если так, то вы пришли в правильное место!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Срочное сообщение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя мы не получаем серьезной помощи напрямую из Штормграда, у меня в городе есть знакомый, снабжающий нас доспехами. Зовут его Озрик Штранг. Его магазин, "Ограниченная неуязвимость", находится в Старом городе.$b$bНаши запасы доспехов заканчиваются, и я должен связаться с Озриком, чтобы попросить еще. Можете ли вы передать ему эту записку?$bБыстрее всего добраться до Штормграда можно с помощью Тора, нашего укротителя грифонов. Он находится прямо у подножия этого холма. Приходите к нему с моей запиской, а затем летите на грифоне в Штормград.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите записку Льюиса укротителю грифонов Тору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вам нужно доставить эту записку в Штормград? Это не проблема, вы можете взять одного из моих грифонов!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Такое ощущение, что вы сильно торопитесь. Что ж, если так, то вы пришли в правильное место!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6182,'Первый и последний','Натанос Маррис был первым и последним человеком-предводителем следопытов. Его наставницей была Сильвана Ветрокрылая, ныне – королева Отрекшихся.$b$bМы думали, что Натанос погиб в бою много лет назад, при защите Лордерона. Хотя его тело не было обнаружено, считалось, что он не сумел выбраться из Восточных Чумных земель.$b$bМатиас Шоу изучил обстоятельства его исчезновения и у него может быть какая-то информация. Доложитесь ему немедленно. Он обитает в Старом городе, в казармах.','Поговорите с Матиасом Шоу в Старом Городе в Штормграде. Матиас находится в казармах.','После появления сообщений о необычной активности Отрекшихся в Восточных Чумных землях туда были посланы агенты ШРУ для расследования ситуации. Результаты этого расследования оказались весьма тревожными.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первый и последний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Натанос Маррис был первым и последним человеком-предводителем следопытов. Его наставницей была Сильвана Ветрокрылая, ныне – королева Отрекшихся.$b$bМы думали, что Натанос погиб в бою много лет назад, при защите Лордерона. Хотя его тело не было обнаружено, считалось, что он не сумел выбраться из Восточных Чумных земель.$b$bМатиас Шоу изучил обстоятельства его исчезновения и у него может быть какая-то информация. Доложитесь ему немедленно. Он обитает в Старом городе, в казармах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Матиасом Шоу в Старом Городе в Штормграде. Матиас находится в казармах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','После появления сообщений о необычной активности Отрекшихся в Восточных Чумных землях туда были посланы агенты ШРУ для расследования ситуации. Результаты этого расследования оказались весьма тревожными.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6183,'Поминовение усопших','Пятеро моих лучших полевых агентов занимались делом Марриса. Вернулся только один, и тот через три дня умер во сне.$b$bТа скудная информация, которую удалось из него вытрясти, звучала несусветной чушью. Мы разобрали лишь два слова: "Натанос" и "Гниль".$b$bУ меня не хватает сотрудников, чтобы продолжить это расследование, и в "Черном Вороне" нам не помогут. Мы должны докопаться до сути, чтобы хотя бы принести какое-то утешение семьям погибших. Вы окажете нам помощь?','Еще раз поговорите с Матиасом Шоу, если хотите принять его задание.','*Матиас кивает.*$b$bЯ и не сомневался, что Ринн пришлет мне честных и благородных людей – самых преданных солдат Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поминовение усопших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пятеро моих лучших полевых агентов занимались делом Марриса. Вернулся только один, и тот через три дня умер во сне.$b$bТа скудная информация, которую удалось из него вытрясти, звучала несусветной чушью. Мы разобрали лишь два слова: "Натанос" и "Гниль".$b$bУ меня не хватает сотрудников, чтобы продолжить это расследование, и в "Черном Вороне" нам не помогут. Мы должны докопаться до сути, чтобы хотя бы принести какое-то утешение семьям погибших. Вы окажете нам помощь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Еще раз поговорите с Матиасом Шоу, если хотите принять его задание.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Матиас кивает.*$b$bЯ и не сомневался, что Ринн пришлет мне честных и благородных людей – самых преданных солдат Альянса.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6184,'Флинт Тенемор','Единственные сведения, которыми мы сейчас располагаем – это то, что Натаноса Марриса, возможно, убил этот тип по имени "Гниль". Мы допускаем, что тот же "Гниль" расправился и с моими агентами.$b$bФлинт Тенемор, еще один сотрудник ШРУ, находится в лагере на Берегу Промозглого Ветра в Западных Чумных землях. Найдите его. Он расскажет вам о текущей ситуации в Чумных землях и даст задание.$b$bУдачи вам, $n.','Отправляйтесь в Лагерь Промозглого Ветра в Западных Чумных землях и найдите Флинта Тенемора.','Ваше первое задание будет очень простым, $n. Уйти – и вернуться. Провести разведку...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Флинт Тенемор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Единственные сведения, которыми мы сейчас располагаем – это то, что Натаноса Марриса, возможно, убил этот тип по имени "Гниль". Мы допускаем, что тот же "Гниль" расправился и с моими агентами.$b$bФлинт Тенемор, еще один сотрудник ШРУ, находится в лагере на Берегу Промозглого Ветра в Западных Чумных землях. Найдите его. Он расскажет вам о текущей ситуации в Чумных землях и даст задание.$b$bУдачи вам, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Лагерь Промозглого Ветра в Западных Чумных землях и найдите Флинта Тенемора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ваше первое задание будет очень простым, $n. Уйти – и вернуться. Провести разведку...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6185,'Чума на востоке','Говорю же, первое задание – разведывательное. Ничего особенного, $n. Отправляйся в Восточные Чумные земли и поищи там сведения про Гниля.$b$bИ поглядывай, не найдешь ли ты наших пропавших оперативников. Мы вынуждены предположить, что они погибли, но коли так, должны быть... трупы.$b$b*Флинт вздыхает.*$b$bВсе агенты ШРУ носят такие знаки.$B$B*Флинт показывает вам знаки отличия ШРУ.*$b$bПринеси мне все, какие только найдешь.','Поищите в Восточных Чумных землях сведения про некоего Гниля и пропавших агентов ШРУ. Если удастся найти знаки отличия ШРУ, отнесите их Флинту Тенемору в Лагерь Промозглого Ветра.','Рутгер. Фредо. Турьен. Все... Мертвы... <Флинт сжимает в руках их регалии.> Где они были? Удалось ли тебе собрать сведения про этого мерзавца Гниля?','Ну... Как дела?','Гниль выведен на чистую воду','Вернитесь к Флинту Тенемору в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чума на востоке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорю же, первое задание – разведывательное. Ничего особенного, $n. Отправляйся в Восточные Чумные земли и поищи там сведения про Гниля.$b$bИ поглядывай, не найдешь ли ты наших пропавших оперативников. Мы вынуждены предположить, что они погибли, но коли так, должны быть... трупы.$b$b*Флинт вздыхает.*$b$bВсе агенты ШРУ носят такие знаки.$B$B*Флинт показывает вам знаки отличия ШРУ.*$b$bПринеси мне все, какие только найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите в Восточных Чумных землях сведения про некоего Гниля и пропавших агентов ШРУ. Если удастся найти знаки отличия ШРУ, отнесите их Флинту Тенемору в Лагерь Промозглого Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рутгер. Фредо. Турьен. Все... Мертвы... <Флинт сжимает в руках их регалии.> Где они были? Удалось ли тебе собрать сведения про этого мерзавца Гниля?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну... Как дела?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Гниль выведен на чистую воду',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Флинту Тенемору в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6186,'Пришествие Гнили','*Флинт бледнеет.*$b$bЭто дело рук На... Натаноса? Натанос и есть Гнилостень?$B$BНо почему? Он был... таким благородным, пользовался всеобщим уважением. Единственный человек, которого согласились обучать высшие эльфы. И теперь он безжалостный сторонник Отрекшихся?$b$bМне... жаль, что приходится просить об этом, $n, но об этих событиях должен узнать король Ринн. Я прошу тебя незамедлительно вернуться в Штормград с вестями.','Возвращайтесь в Штормград и сообщите королю Вариану Ринну о судьбе Натаноса Марриса.','Нет. Не может... НЕТ! Как? Агент Отрекшихся? ЗАЩИТНИК Королевы банши???$B$B<Верховный лорд Болвар Фордрагон бессильно опускает руки.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пришествие Гнили',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Флинт бледнеет.*$b$bЭто дело рук На... Натаноса? Натанос и есть Гнилостень?$B$BНо почему? Он был... таким благородным, пользовался всеобщим уважением. Единственный человек, которого согласились обучать высшие эльфы. И теперь он безжалостный сторонник Отрекшихся?$b$bМне... жаль, что приходится просить об этом, $n, но об этих событиях должен узнать король Ринн. Я прошу тебя незамедлительно вернуться в Штормград с вестями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь в Штормград и сообщите королю Вариану Ринну о судьбе Натаноса Марриса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет. Не может... НЕТ! Как? Агент Отрекшихся? ЗАЩИТНИК Королевы банши???$B$B<Верховный лорд Болвар Фордрагон бессильно опускает руки.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6187,'Порядок должен быть восстановлен','Знаете, сколько предводителей следопытов существует на этом свете? А сколько когда-либо существовало людей-предводителей следопытов?$b$bДостижения Натаноса необыкновенны. Он был тактическим гением, благодаря ему Альянс в течение десятилетия одерживал победы.$b$bА теперь... теперь он защитник Отрекшихся.$b$bНет. Такого быть не должно. Порядок должен быть восстановлен.$b$bСоберите армию, $n. Возвращайтесь в Проклятые земли со своими воинами и уничтожьте Гниля.$b$bЖелаю удачи, $n. В этом бою она вам точно понадобится.','Соберите войско и отправляйтесь в Восточные Чумные земли. Проведите полномасштабную атаку на Натаноса Гнилостня и любых воинов Орды, которые могут попытаться его защитить.$b$bБудьте осторожны, потому что Орда всеми силами будет защищать бывшего предводителя следопытов.','Это трагедия. Я думаю что... я считаю что весь наш род проклят, $N. Мы все прокляты! Потерять наших величайших воинов, наших самых благородных героев…$B$BМы в долгу перед тобой и я уверяю тебя, $N, где бы Натанос сейчас не был бы, он улыбается смотря на нас сверху.','<Верховный лорд Болвар Фордрагон задумался.>','Вернитесь к королю Вариану Ринну в Элвиннский лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порядок должен быть восстановлен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаете, сколько предводителей следопытов существует на этом свете? А сколько когда-либо существовало людей-предводителей следопытов?$b$bДостижения Натаноса необыкновенны. Он был тактическим гением, благодаря ему Альянс в течение десятилетия одерживал победы.$b$bА теперь... теперь он защитник Отрекшихся.$b$bНет. Такого быть не должно. Порядок должен быть восстановлен.$b$bСоберите армию, $n. Возвращайтесь в Проклятые земли со своими воинами и уничтожьте Гниля.$b$bЖелаю удачи, $n. В этом бою она вам точно понадобится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите войско и отправляйтесь в Восточные Чумные земли. Проведите полномасштабную атаку на Натаноса Гнилостня и любых воинов Орды, которые могут попытаться его защитить.$b$bБудьте осторожны, потому что Орда всеми силами будет защищать бывшего предводителя следопытов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это трагедия. Я думаю что... я считаю что весь наш род проклят, $N. Мы все прокляты! Потерять наших величайших воинов, наших самых благородных героев…$B$BМы в долгу перед тобой и я уверяю тебя, $N, где бы Натанос сейчас не был бы, он улыбается смотря на нас сверху.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Верховный лорд Болвар Фордрагон задумался.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к королю Вариану Ринну в Элвиннский лес.',`completedtext_loc8`);
