INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6221,'Северные фурболги Мертвого Леса','Прямо на юго-западе отсюда расположен лагерь фурболгов Мертвого Леса. В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги стали настоящей угрозой.$B$BПлемя Мервтого Леса злобное, но это все действие скверны, поразившей их разум. Они не враждебны от природы, но тут уж ничего не поделать. Мне невыносимо тяжело сражаться против собратьев.$B$BПрошу тебя, $n, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается.','Нафиэн просит вас убить 5 дозорного из племени Мертвого Леса, 5 мстителей и 5 шаманов из племени Мертвого Леса.','Вернитесь к Гразлу в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Северные фурболги Мертвого Леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прямо на юго-западе отсюда расположен лагерь фурболгов Мертвого Леса. В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги стали настоящей угрозой.$B$BПлемя Мервтого Леса злобное, но это все действие скверны, поразившей их разум. Они не враждебны от природы, но тут уж ничего не поделать. Мне невыносимо тяжело сражаться против собратьев.$B$BПрошу тебя, $n, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нафиэн просит вас убить 5 дозорного из племени Мертвого Леса, 5 мстителей и 5 шаманов из племени Мертвого Леса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гразлу в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (6241,'Боевые действия в деревне Зимней Спячки','Клан Древобрюхов готов постоять за себя, $n. В то время как мы позволяем свободно ходить среди нас тем, кому мы доверяем, мы стараемся по возможности избегать общения с другими племенами фурболгов. $b$bПлемя Зимней Спячки в последнее время становится все более враждебным к нам. Они, похоже, впали в состояние ярости, всецело поглощенные собственным страхом и ненавистью ко всему, чего они не понимают. $b$bЕсли бы вы могли сократить их число, это бы нам здорово помогло, $n.','Убейте 6 тотемистов, 6 дозорных и 6 землепроходцев из племени Зимней Спячки по просьбе Сальфы.','Спасибо за то, что ты $Gсделал:сделала;. Пожалуйста, продолжай помогать нам, $N. У нас очень мало союзников, к которым можно обратиться.','Вернитесь к Сальфе в Зимние Ключи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые действия в деревне Зимней Спячки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Древобрюхов готов постоять за себя, $n. В то время как мы позволяем свободно ходить среди нас тем, кому мы доверяем, мы стараемся по возможности избегать общения с другими племенами фурболгов. $b$bПлемя Зимней Спячки в последнее время становится все более враждебным к нам. Они, похоже, впали в состояние ярости, всецело поглощенные собственным страхом и ненавистью ко всему, чего они не понимают. $b$bЕсли бы вы могли сократить их число, это бы нам здорово помогло, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 тотемистов, 6 дозорных и 6 землепроходцев из племени Зимней Спячки по просьбе Сальфы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за то, что ты $Gсделал:сделала;. Пожалуйста, продолжай помогать нам, $N. У нас очень мало союзников, к которым можно обратиться.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сальфе в Зимние Ключи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (6261,'Дунгар Долгопив','$n, я сложил в этот ящик все, о чем просил Льюис. Можете отвезти ему ящик?$b$bС Тором в Западном Крае вы уже общались – значит, сможете нанять грифона, чтобы туда вернуться. Наш укротитель грифонов – Дунгар Долгопив, он находится в Торговом квартале.$b$bПоговори с Дунгаром и доставь этот ящик Льюису как можно скорее. Мы не хотим, чтобы нашим воинам в Западном Крае пришлось сражаться без новых доспехов!','Отнесите ящик Озрика к укротителю грифонов Дунгару Долгопиву.','Нужно доставить сундук в Западный Край, да? А вы там бывали прежде? Если да, то никаких проблем, друг мой. У меня есть множество грифонов, обученных этому маршруту!','Да вы вспотели, $gсударь:сударыня;! Не стоило так много бегать на своих двоих. В следующий раз возьмите грифона!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дунгар Долгопив',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я сложил в этот ящик все, о чем просил Льюис. Можете отвезти ему ящик?$b$bС Тором в Западном Крае вы уже общались – значит, сможете нанять грифона, чтобы туда вернуться. Наш укротитель грифонов – Дунгар Долгопив, он находится в Торговом квартале.$b$bПоговори с Дунгаром и доставь этот ящик Льюису как можно скорее. Мы не хотим, чтобы нашим воинам в Западном Крае пришлось сражаться без новых доспехов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ящик Озрика к укротителю грифонов Дунгару Долгопиву.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нужно доставить сундук в Западный Край, да? А вы там бывали прежде? Если да, то никаких проблем, друг мой. У меня есть множество грифонов, обученных этому маршруту!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да вы вспотели, $gсударь:сударыня;! Не стоило так много бегать на своих двоих. В следующий раз возьмите грифона!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (6281,'Продолжение пути в Штормград','За небольшую плату вы можете нанять грифона для полета в Штормград, чтобы доставить записку Льюиса Озрику. Более быстрого пути нет.$b$bЕсли для вас это приемлемо, поговорите со мной снова, когда будете готовы лететь. Я, конечно, возьму с вас немного денег, но поверьте, оно того стоит!','Оплатите укротителю грифонов Тору полет до Штормграда и принесите записку Льюиса Озрику Штрангу в магазинчик "Ограниченная неуязвимость", расположенный в районе Старого города.','Путешествовали, да? Видели что-нибудь интересненькое?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Продолжение пути в Штормград',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За небольшую плату вы можете нанять грифона для полета в Штормград, чтобы доставить записку Льюиса Озрику. Более быстрого пути нет.$b$bЕсли для вас это приемлемо, поговорите со мной снова, когда будете готовы лететь. Я, конечно, возьму с вас немного денег, но поверьте, оно того стоит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оплатите укротителю грифонов Тору полет до Штормграда и принесите записку Льюиса Озрику Штрангу в магазинчик "Ограниченная неуязвимость", расположенный в районе Старого города.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Путешествовали, да? Видели что-нибудь интересненькое?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6282,'Угроза со стороны гарпий','Таурен горд тем, что защищает эти земли. Несомненно, ты понимаешь, почему я обеспокоен тем, что здесь, в Каменном Когте, обитает множество гарпий.$B$BКлан Смертельной Ярости – вот откуда берутся все новые и новые гарпии в Калимдоре. Они посягают на жизнь всех и каждого, не давая слабым даже уйти отсюда!$B$BМне нужна твоя помощь в уничтожении гарпий, $n!','Землепряд Маггран из Приюта у Солнечного Камня просит вас убить 7 гарпий, 7 душительниц, 7 душегубок и 7 бродяжниц из стаи Кровавой Ярости.','Замечательные новости! Поведай мне вновь, как тебе удалось вселить ужас в холодные сердца злобных гарпий. Клан Смертельной Ярости понес серьезный урон!','Семена, посаженные тобою, очень сильны, они сопротивляются порче и помогут создать основу для других видов жизни. Они будут расти и расти, сначала не давая расползаться порче и исцеляя израненную землю, а затем, в один прекрасный день, вновь покроют земли Каменного Когтя густыми лесами.\n\nВсе ли семена Геи израсходованы на эти посадки?','Вернитесь к Землепряду Магграну в Приют у Солнечного Камня в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза со стороны гарпий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Таурен горд тем, что защищает эти земли. Несомненно, ты понимаешь, почему я обеспокоен тем, что здесь, в Каменном Когте, обитает множество гарпий.$B$BКлан Смертельной Ярости – вот откуда берутся все новые и новые гарпии в Калимдоре. Они посягают на жизнь всех и каждого, не давая слабым даже уйти отсюда!$B$BМне нужна твоя помощь в уничтожении гарпий, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Землепряд Маггран из Приюта у Солнечного Камня просит вас убить 7 гарпий, 7 душительниц, 7 душегубок и 7 бродяжниц из стаи Кровавой Ярости.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательные новости! Поведай мне вновь, как тебе удалось вселить ужас в холодные сердца злобных гарпий. Клан Смертельной Ярости понес серьезный урон!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Семена, посаженные тобою, очень сильны, они сопротивляются порче и помогут создать основу для других видов жизни. Они будут расти и расти, сначала не давая расползаться порче и исцеляя израненную землю, а затем, в один прекрасный день, вновь покроют земли Каменного Когтя густыми лесами.\n\nВсе ли семена Геи израсходованы на эти посадки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Землепряду Магграну в Приют у Солнечного Камня в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6283,'Предводительница стаи Кровавой Ярости','Уменьшить число гарпий из стаи Кровавой Ярости – этого недостаточно. Единственное, чем можно извести эту заразу – это убить их предводительницу, Потрошительницу!$B$BСредь этих мерзостных существ она почти королева. Убей ее, и гарпий станет меньше.$B$BВозвращайся в Обугленную долину, и ты найдешь ее у западных холмов. Ее не так-то легко уничтожить, но награда будет велика.','Маггран из Приюта у Солнечного Камня просит убить Потрошительницу из стаи Кровавой Ярости и принести ему ее останки в доказательство того, что она мертва.','Я уже чувствую, как гнев покидает меня. Что мне теперь делать? Знание о том, что зло бродило поблизости от моих земель, заставляло мои мысли течь быстро, пусть и безмолвно. Быть может, это и к лучшему... быть может, теперь я смогу обратить свои мысли в сторону добра, как и положено таурену.\n\nПрошу тебя, прими это в награду за твои труды.','Потрошительница из стаи Кровавой Ярости – ужасное существо! Ты, несомненно, найдешь ее у подножия западных холмов в Обугленной долине.\n\nБез нее гарпии будут бессильны... и мы уж точно сможем избавиться от них!','Вернитесь к Землепряду Магграну в Приют у Солнечного Камня в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предводительница стаи Кровавой Ярости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уменьшить число гарпий из стаи Кровавой Ярости – этого недостаточно. Единственное, чем можно извести эту заразу – это убить их предводительницу, Потрошительницу!$B$BСредь этих мерзостных существ она почти королева. Убей ее, и гарпий станет меньше.$B$BВозвращайся в Обугленную долину, и ты найдешь ее у западных холмов. Ее не так-то легко уничтожить, но награда будет велика.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Маггран из Приюта у Солнечного Камня просит убить Потрошительницу из стаи Кровавой Ярости и принести ему ее останки в доказательство того, что она мертва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уже чувствую, как гнев покидает меня. Что мне теперь делать? Знание о том, что зло бродило поблизости от моих земель, заставляло мои мысли течь быстро, пусть и безмолвно. Быть может, это и к лучшему... быть может, теперь я смогу обратить свои мысли в сторону добра, как и положено таурену.\n\nПрошу тебя, прими это в награду за твои труды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Потрошительница из стаи Кровавой Ярости – ужасное существо! Ты, несомненно, найдешь ее у подножия западных холмов в Обугленной долине.\n\nБез нее гарпии будут бессильны... и мы уж точно сможем избавиться от них!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Землепряду Магграну в Приют у Солнечного Камня в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6284,'Арахнофобия','Предупреждение: дорога отсюда на запад, в Сиширский каньон, опасна.$B$BБесселет и ее восьминогие отпрыски превратили этот каньон в свое логово, заплетенное паутиной.$B$BМаггран Связующий Землю из Приюта у Солнечного Камня назначил награду за Бесселет. Убей ее и принеси доказательство ее смерти Магграну – получишь награду за устранение этой восьминогой угрозы.','Убейте Бесселет и принесите клык Бесселет Магграну в Приют у Солнечного Камня.','Бесселет – безжалостный хищник... Я опасаюсь за тех, кто путешествует по Паучему Тракту ночами. Именно тогда Бесселет и ее отродья охотятся на ничего не подозревающих путников. Я сам едва не стал жертвой ее полуметровых смертоносных клыков, но, к счастью, сумел отбиться и убежать. Я отдам что угодно за то, чтобы это чудовище было уничтожено.','Вернитесь к Землепряду Магграну в Приют у Солнечного Камня в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арахнофобия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Предупреждение: дорога отсюда на запад, в Сиширский каньон, опасна.$B$BБесселет и ее восьминогие отпрыски превратили этот каньон в свое логово, заплетенное паутиной.$B$BМаггран Связующий Землю из Приюта у Солнечного Камня назначил награду за Бесселет. Убей ее и принеси доказательство ее смерти Магграну – получишь награду за устранение этой восьминогой угрозы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Бесселет и принесите клык Бесселет Магграну в Приют у Солнечного Камня.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Бесселет – безжалостный хищник... Я опасаюсь за тех, кто путешествует по Паучему Тракту ночами. Именно тогда Бесселет и ее отродья охотятся на ничего не подозревающих путников. Я сам едва не стал жертвой ее полуметровых смертоносных клыков, но, к счастью, сумел отбиться и убежать. Я отдам что угодно за то, чтобы это чудовище было уничтожено.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Землепряду Магграну в Приют у Солнечного Камня в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (6285,'Возвращение к Льюису','Укротителем грифонов в Западном Крае работает Тор. Если вы с ним уже знакомы, то можете на одном из моих грифонов к нему долететь.$b$bПолезная для вас информация: грифоны обучены так, что до столицы могут долететь всегда, а к укротителям, расположенным в других местах, полетят, только если вы там уже бывали.$b$bВы ведь уже были у Тора, так что просто поговорите со мной еще раз, когда будете готовы лететь в Западный Край. А там уже отнесете ящик Озрика интенданту Льюису.','Оплатите укротителю грифонов Дунгару Долгопиву полет до Сторожевого холма, а затем отнесите ящик Озрика Льюису.','Вы уже вернулись из Штормграда? Озрик прислал доспехи?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Льюису',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Укротителем грифонов в Западном Крае работает Тор. Если вы с ним уже знакомы, то можете на одном из моих грифонов к нему долететь.$b$bПолезная для вас информация: грифоны обучены так, что до столицы могут долететь всегда, а к укротителям, расположенным в других местах, полетят, только если вы там уже бывали.$b$bВы ведь уже были у Тора, так что просто поговорите со мной еще раз, когда будете готовы лететь в Западный Край. А там уже отнесете ящик Озрика интенданту Льюису.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оплатите укротителю грифонов Дунгару Долгопиву полет до Сторожевого холма, а затем отнесите ящик Озрика Льюису.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы уже вернулись из Штормграда? Озрик прислал доспехи?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6301,'Цикл возрождения','Жадность промышленников и постоянная война опустошили земли Каменного Пика. Только благословение Матери-Земли может исцелить такие раны.$B$B$n, я хочу отправить тебя на поиски особого семени – семени Геи. Его можно найти только здесь, в Каменном Когте, к северу от Приюта у Солнечного Камня, у Мутного Озера, у самого края воды. $B$BКак только ты принесешь мне эти семена, я напитаю их шаманской силой, дабы ускорить их рост.','Таммра Перекати-поле из Приюта у Солнечного Камня просит вас собрать 10 семян Геи.','Страшные разрушения, причиненные войной и теми, кто наживался на лесозаготовках, глубоко ранят мою душу. Чтобы начать цикл возрождения и оживить эти земли, мне нужны семена Геи. Есть ли они у тебя, |3-6($C)?','Вернитесь к Таммре Перекати-поле в Приют у Солнечного Камня в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цикл возрождения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жадность промышленников и постоянная война опустошили земли Каменного Пика. Только благословение Матери-Земли может исцелить такие раны.$B$B$n, я хочу отправить тебя на поиски особого семени – семени Геи. Его можно найти только здесь, в Каменном Когте, к северу от Приюта у Солнечного Камня, у Мутного Озера, у самого края воды. $B$BКак только ты принесешь мне эти семена, я напитаю их шаманской силой, дабы ускорить их рост.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Таммра Перекати-поле из Приюта у Солнечного Камня просит вас собрать 10 семян Геи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Страшные разрушения, причиненные войной и теми, кто наживался на лесозаготовках, глубоко ранят мою душу. Чтобы начать цикл возрождения и оживить эти земли, мне нужны семена Геи. Есть ли они у тебя, |3-6($C)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таммре Перекати-поле в Приют у Солнечного Камня в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6321,'Поставка оружия в Брилл','Палач Зуганд попросил меня заняться нашим арсеналом в Брилле. По лесу рыщут силы Плети, а то и кое-что похуже, и он хочет, чтобы у наших стражей смерти было достаточно оружия, когда оно понадобится. $b$bЯ выяснил, что в целом у нас все в порядке, но нам нужно дополнительное оружие взамен потерянного в боях. $b$bВот заявка на поставку для торговца оружием Гордона Уиндема, находящегося в Подгороде. Отнеси этот заказ нашей дрессировщице летучих мышей Анетте и поговори с ней о полете в Подгород.','Отнесите заказ Морриса Анетте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поставка оружия в Брилл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Палач Зуганд попросил меня заняться нашим арсеналом в Брилле. По лесу рыщут силы Плети, а то и кое-что похуже, и он хочет, чтобы у наших стражей смерти было достаточно оружия, когда оно понадобится. $b$bЯ выяснил, что в целом у нас все в порядке, но нам нужно дополнительное оружие взамен потерянного в боях. $b$bВот заявка на поставку для торговца оружием Гордона Уиндема, находящегося в Подгороде. Отнеси этот заказ нашей дрессировщице летучих мышей Анетте и поговори с ней о полете в Подгород.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите заказ Морриса Анетте.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (6322,'Майкл Гарретт','Я сложил припасы для Брилла в этот ящик. Если ты уже $gбывал:бывала; в Гробнице и $gзнаком:знакома; с тамошним дрессировщиком летучих мышей, то можешь туда лететь. $b$bПоговори с дрессировщиком летучих мышей здесь, в Подгороде – с Майклом Гарреттом. Он поможет тебе добраться до Брилла.','Отправляйтесь к Майклу Гарретту с ящиком Гордона.','Если вам нужно преодолеть большое расстояние, удобнее всего сделать это на летучей мыши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Майкл Гарретт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сложил припасы для Брилла в этот ящик. Если ты уже $gбывал:бывала; в Гробнице и $gзнаком:знакома; с тамошним дрессировщиком летучих мышей, то можешь туда лететь. $b$bПоговори с дрессировщиком летучих мышей здесь, в Подгороде – с Майклом Гарреттом. Он поможет тебе добраться до Брилла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Майклу Гарретту с ящиком Гордона.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если вам нужно преодолеть большое расстояние, удобнее всего сделать это на летучей мыши.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (6323,'Полет в Подгород','Обратитесь к дрессировщице летучих мышей Анетте, чтобы отправиться в Подгород, а затем отнесите заказ Морриса Гордону Уиндему.','Я держу оружие в отличном состоянии. Все почищено и готово к использованию.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полет в Подгород',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к дрессировщице летучих мышей Анетте, чтобы отправиться в Подгород, а затем отнесите заказ Морриса Гордону Уиндему.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я держу оружие в отличном состоянии. Все почищено и готово к использованию.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6324,'Обратно к Моррису','Дрессировщицу летучих мышей в Брилле зовут Анетта. Если ты уже $gзнаком:знакома; с ней, я могу предоставить тебе одну из своих летучих мышей для полета обратно.$b$bВсе наши мыши знают, как лететь в Подгород, но чтобы добраться до более отдаленных мест, пассажир должен сначала посетить эти места и познакомиться с тамошними дрессировщиками.$b$bНо раз ты уже $gбыл:была; в Брилле и $gвстречался:встречалась; с Анеттой, то ты можешь проделать этот путь. Просто скажи мне, когда будешь $gготов:готова;.','Оплатите у дрессировщика летучих мышей Майкла Гарретта полет до Брилла, а затем отдайте ящик Гордона Моррису.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обратно к Моррису',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дрессировщицу летучих мышей в Брилле зовут Анетта. Если ты уже $gзнаком:знакома; с ней, я могу предоставить тебе одну из своих летучих мышей для полета обратно.$b$bВсе наши мыши знают, как лететь в Подгород, но чтобы добраться до более отдаленных мест, пассажир должен сначала посетить эти места и познакомиться с тамошними дрессировщиками.$b$bНо раз ты уже $gбыл:была; в Брилле и $gвстречался:встречалась; с Анеттой, то ты можешь проделать этот путь. Просто скажи мне, когда будешь $gготов:готова;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оплатите у дрессировщика летучих мышей Майкла Гарретта полет до Брилла, а затем отдайте ящик Гордона Моррису.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6341,'В Дарнас','Весь Доланаар гордится сестрой Аквинной. Я уверен, она будет рада получить такой подарок от Ньомы.$B$BПросто окликни меня, когда соберешься в Дарнас, и я одолжу тебе гиппогрифа всего за несколько монет. Я даже расскажу тебе, где найти сестру Аквинну, когда ты прибудешь в столицу. Она наслаждается уединением на маленькой площади к югу от стоянки гиппогрифов в Дарнасе.','Оплатите поездку в Дарнас, после чего принесите книгу рецептов Доланаара сестре Аквинне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Дарнас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Весь Доланаар гордится сестрой Аквинной. Я уверен, она будет рада получить такой подарок от Ньомы.$B$BПросто окликни меня, когда соберешься в Дарнас, и я одолжу тебе гиппогрифа всего за несколько монет. Я даже расскажу тебе, где найти сестру Аквинну, когда ты прибудешь в столицу. Она наслаждается уединением на маленькой площади к югу от стоянки гиппогрифов в Дарнасе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оплатите поездку в Дарнас, после чего принесите книгу рецептов Доланаара сестре Аквинне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6342,'Неожиданный подарок','Какой приятный сюрприз! Я мечтала, чтобы здесь, в Храме Луны, у меня было что-то, напоминающее о доме и друзьях. Жду не дождусь, когда смогу приготовить что-нибудь по этим рецептам! Пожалуй, займусь этим прямо сегодня вечером...$B$BПослушай, не $gмог:могла; бы ты отнести эту благодарственную записку Ньоме? Наши гиппогрифы знают дорогу в Доланаар. Зайди к нашему распорядителю полетов Леоре, когда будешь $gготов:готова; вернуться обратно.','Отнесите записку сестры Аквинны Леоре, укротителю гиппогрифов в Дарнасе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неожиданный подарок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какой приятный сюрприз! Я мечтала, чтобы здесь, в Храме Луны, у меня было что-то, напоминающее о доме и друзьях. Жду не дождусь, когда смогу приготовить что-нибудь по этим рецептам! Пожалуй, займусь этим прямо сегодня вечером...$B$BПослушай, не $gмог:могла; бы ты отнести эту благодарственную записку Ньоме? Наши гиппогрифы знают дорогу в Доланаар. Зайди к нашему распорядителю полетов Леоре, когда будешь $gготов:готова; вернуться обратно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите записку сестры Аквинны Леоре, укротителю гиппогрифов в Дарнасе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6343,'Возвращение к Ньоме','Доставить тебя в Доланаар? Нет ничего проще! Ты же уже знаешь Фиделио, так что доберешься туда без проблем.$B$BЗапомни, это важно: в каждом новом городе тебе прежде всего надо познакомиться с распорядителем полетов – тогда ты сможешь путешествовать куда захочешь.$B$BОкликни меня, как будешь $gготов:готова; отправиться в путь.','Поговорите с Леорой, чтобы нанять гиппогрифа и отправиться обратно в Доланаар, после чего отнесите записку Аквинны Ньоме.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Ньоме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доставить тебя в Доланаар? Нет ничего проще! Ты же уже знаешь Фиделио, так что доберешься туда без проблем.$B$BЗапомни, это важно: в каждом новом городе тебе прежде всего надо познакомиться с распорядителем полетов – тогда ты сможешь путешествовать куда захочешь.$B$BОкликни меня, как будешь $gготов:готова; отправиться в путь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Леорой, чтобы нанять гиппогрифа и отправиться обратно в Доланаар, после чего отнесите записку Аквинны Ньоме.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6344,'Памятный дар','Моя подруга, сестра Аквинна, сейчас готовится стать жрицей луны в Дарнасе. Для этого она в прошлом году покинула Доланаар и поступила в обитель при храме. Она часто пишет мне, рассказывает, как много нового узнала во время обучения, и как она скучает по дому и старым друзьям. Мне бы хотелось как-нибудь поддержать ее, и поэтому я составила эту книгу ее любимых кулинарных рецептов Доланаара.$B$BЕсли у тебя найдется свободная минутка, пожалуйста, отнеси ее в Дарнас. Думаю, Фиделио не откажется одолжить тебе гиппогрифа, который знает туда дорогу. Его можно найти в центре города, прямо напротив постоялого двора.','Принесите Доланаарскую кулинарную книгу Фиделио.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Памятный дар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя подруга, сестра Аквинна, сейчас готовится стать жрицей луны в Дарнасе. Для этого она в прошлом году покинула Доланаар и поступила в обитель при храме. Она часто пишет мне, рассказывает, как много нового узнала во время обучения, и как она скучает по дому и старым друзьям. Мне бы хотелось как-нибудь поддержать ее, и поэтому я составила эту книгу ее любимых кулинарных рецептов Доланаара.$B$BЕсли у тебя найдется свободная минутка, пожалуйста, отнеси ее в Дарнас. Думаю, Фиделио не откажется одолжить тебе гиппогрифа, который знает туда дорогу. Его можно найти в центре города, прямо напротив постоялого двора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Доланаарскую кулинарную книгу Фиделио.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6361,'Связка шкур','Отнесите связку шкур укротителю ветрокрылов Таку в деревню Кровавого Копыта.','Тебе нужен ветрокрыл? Собираешься доставлять какие-то товары?','Принесите связку шкур укротителю ветрокрылов Девраку в Перекресток, что в Северных Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связка шкур',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите связку шкур укротителю ветрокрылов Таку в деревню Кровавого Копыта.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе нужен ветрокрыл? Собираешься доставлять какие-то товары?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Принесите связку шкур укротителю ветрокрылов Девраку в Перекресток, что в Северных Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6362,'Дорога до Громового Утеса','За небольшую плату ты можешь полететь в Громовой Утес на ветрокрыле. Быстрее не бывает!$B$BЕсли тебя устраивает цена – обращайся, когда решишь отправиться в путь.$B$BЕсли ты везешь эти шкуры Ахану, думаю, ты отыщешь его в оружейной Хевы, у основания башни ветрокрылов в Громовом Утесе. Именно там ты и приземлишься!','Оплатите перелет в Громовой Утес укротителю ветрокрылов Таку и, оказавшись на месте, отнесите связку шкур Ахану.','Заплатите укротителю ветрокрылов Девраку за полет в Громовой Утес, затем доставьте связку шкур Ахану в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога до Громового Утеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За небольшую плату ты можешь полететь в Громовой Утес на ветрокрыле. Быстрее не бывает!$B$BЕсли тебя устраивает цена – обращайся, когда решишь отправиться в путь.$B$BЕсли ты везешь эти шкуры Ахану, думаю, ты отыщешь его в оружейной Хевы, у основания башни ветрокрылов в Громовом Утесе. Именно там ты и приземлишься!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оплатите перелет в Громовой Утес укротителю ветрокрылов Таку и, оказавшись на месте, отнесите связку шкур Ахану.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Заплатите укротителю ветрокрылов Девраку за полет в Громовой Утес, затем доставьте связку шкур Ахану в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6363,'Укротитель ветрокрылов Тал','Я приготовил кое-какие кожаные изделия на продажу в деревню Кровавого Копыта. Не отнесешь ли их Варгу?$B$BЕсли ты уже $gпоговорил:поговорила; с укротителем ветрокрылов в деревне Кровавого Копыта, можешь полететь туда на виверне.$B$BОтнеси мои товары здешнему укротителю ветрокрылов Талу и поговори с ним насчет дороги до деревни Кровавого Копыта.','Отнесите кожаные вещи Ахану Талу из Громового Утеса.','Отнесите кожаные вещи Ахану Талу в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротитель ветрокрылов Тал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я приготовил кое-какие кожаные изделия на продажу в деревню Кровавого Копыта. Не отнесешь ли их Варгу?$B$BЕсли ты уже $gпоговорил:поговорила; с укротителем ветрокрылов в деревне Кровавого Копыта, можешь полететь туда на виверне.$B$BОтнеси мои товары здешнему укротителю ветрокрылов Талу и поговори с ним насчет дороги до деревни Кровавого Копыта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кожаные вещи Ахану Талу из Громового Утеса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите кожаные вещи Ахану Талу в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6364,'Возвращение к Варгу','Чтобы полететь в какой-нибудь город, следует сначала побывать в нем и поговорить с укротителем ветрокрылов. В деревне Кровавого Копыта ты уже $gпобывал:побывала;, да и с укротителем ветрокрылов Талом ты уже $gзнаком:знакома;, поэтому за небольшую плату ветрокрыл может отнести тебя туда.$B$BОбращайся, когда решишь отправиться в путь. Оказавшись в деревне Кровавого Копыта, отнеси кожаные вещи Варгу Шепоту Ветра.','Оплатите перелет до деревни Кровавого Копыта укротителю ветрокрылов Талу, а затем отнесите кожаные вещи Варгу Шепоту Ветра.','Заплатите укротителю ветрокрылов Талу за полет в Перекресток, затем доставьте кожаные вещи Ахану Джахану Соколиному Крылу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Варгу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы полететь в какой-нибудь город, следует сначала побывать в нем и поговорить с укротителем ветрокрылов. В деревне Кровавого Копыта ты уже $gпобывал:побывала;, да и с укротителем ветрокрылов Талом ты уже $gзнаком:знакома;, поэтому за небольшую плату ветрокрыл может отнести тебя туда.$B$BОбращайся, когда решишь отправиться в путь. Оказавшись в деревне Кровавого Копыта, отнеси кожаные вещи Варгу Шепоту Ветра.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оплатите перелет до деревни Кровавого Копыта укротителю ветрокрылов Талу, а затем отнесите кожаные вещи Варгу Шепоту Ветра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Заплатите укротителю ветрокрылов Талу за полет в Перекресток, затем доставьте кожаные вещи Ахану Джахану Соколиному Крылу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6365,'Мясные продукты в Оргриммар','Я хочу послать своей подруге несколько видов превосходных мясных продуктов. Ее зовут Гришка, она хозяйка таверны в Оргриммаре. Поможешь мне доставить мясо?$b$bДо Оргриммара проще всего добраться на ветрокрыле. Отнеси мясные продукты Буроку, укротителю ветрокрылов, и поговори с ним насчет доставки в Оргриммар.','Тебе нужно доставить мясо в Оргриммар? Нет проблем. За небольшую плату тебя отнесет туда мой ветрокрыл.','Хочешь куда-то добраться в мгновение ока? Тогда ты обратился по адресу!','Отнесите мясные продукты Заргха Буроку на Колючий Холм.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мясные продукты в Оргриммар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу послать своей подруге несколько видов превосходных мясных продуктов. Ее зовут Гришка, она хозяйка таверны в Оргриммаре. Поможешь мне доставить мясо?$b$bДо Оргриммара проще всего добраться на ветрокрыле. Отнеси мясные продукты Буроку, укротителю ветрокрылов, и поговори с ним насчет доставки в Оргриммар.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе нужно доставить мясо в Оргриммар? Нет проблем. За небольшую плату тебя отнесет туда мой ветрокрыл.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хочешь куда-то добраться в мгновение ока? Тогда ты обратился по адресу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите мясные продукты Заргха Буроку на Колючий Холм.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6381,'Новая жизнь','Вот видишь, |3-6($c), хотя эта земля глубоко изранена, круговорот жизни – великая сила. Теперь мы должны внести свой вклад и помочь этой силе. Посади эти семена в самой сердцевине разрушения, на западе, в Обугленной долине. Но берегись – там, в полумертвых землях, еще встречаются гарпии и злобные элементали огня.$B$B$n, возьми эти зачарованные семена Геи и посади их в кучки плодородной почвы. Круговорот жизни должен продолжаться!','Посадите 10 семян Геи в земляные курганы Геи, а затем верните оставшиеся зачарованные семена Геи Таммре в Приют у Солнечного Камня.','Семена, посаженные тобою, очень сильны, они сопротивляются порче и помогут создать основу для других видов жизни. Они будут расти и расти, сначала не давая расползаться порче и исцеляя израненную землю, а затем, в один прекрасный день, вновь покроют земли Каменного Когтя густыми лесами.\n\nВсе ли семена Геи израсходованы на эти посадки?','Вернитесь к Таммре Перекати-поле в Приют у Солнечного Камня в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая жизнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот видишь, |3-6($c), хотя эта земля глубоко изранена, круговорот жизни – великая сила. Теперь мы должны внести свой вклад и помочь этой силе. Посади эти семена в самой сердцевине разрушения, на западе, в Обугленной долине. Но берегись – там, в полумертвых землях, еще встречаются гарпии и злобные элементали огня.$B$B$n, возьми эти зачарованные семена Геи и посади их в кучки плодородной почвы. Круговорот жизни должен продолжаться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите 10 семян Геи в земляные курганы Геи, а затем верните оставшиеся зачарованные семена Геи Таммре в Приют у Солнечного Камня.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Семена, посаженные тобою, очень сильны, они сопротивляются порче и помогут создать основу для других видов жизни. Они будут расти и расти, сначала не давая расползаться порче и исцеляя израненную землю, а затем, в один прекрасный день, вновь покроют земли Каменного Когтя густыми лесами.\n\nВсе ли семена Геи израсходованы на эти посадки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таммре Перекати-поле в Приют у Солнечного Камня в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6382,'Большая охота','Твоя сила производит впечатление, |3-6($c), а интерес к охоте дает надежды, что вскоре тебе можно будет поручить дичь покрупнее... И посерьезнее.$B$BОрда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса. Если ты $gготов:готова; проявить себя в непознанных еще землях, обратись к Сенани Громосерд на Заставе Расщепленного Дерева. Она находится к северу от тропы из Степей.','Поговорите с Сенани Громосерд на Заставе Расщепленного Дерева в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая охота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя сила производит впечатление, |3-6($c), а интерес к охоте дает надежды, что вскоре тебе можно будет поручить дичь покрупнее... И посерьезнее.$B$BОрда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса. Если ты $gготов:готова; проявить себя в непознанных еще землях, обратись к Сенани Громосерд на Заставе Расщепленного Дерева. Она находится к северу от тропы из Степей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сенани Громосерд на Заставе Расщепленного Дерева в Ясеневом лесу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (6383,'Большая охота','Великая охота в Ясеневом лесу заключается в убийстве трех легендарных тварей. Ты можешь выследить их и испытать свои умения против их хитрости и силы. И в этом испытании ты, надеюсь, поймешь что-то и о себе. Вот эти чудища – медведь Топтыжень, ночной саблезуб Тенумбра и гиппогриф Острокоготь.$B$BЭти твари могучи, и, возможно, тебе понадобится помощь. Ели тебе удастся их одолеть, принеси мне доказательства своих подвигов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая охота',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великая охота в Ясеневом лесу заключается в убийстве трех легендарных тварей. Ты можешь выследить их и испытать свои умения против их хитрости и силы. И в этом испытании ты, надеюсь, поймешь что-то и о себе. Вот эти чудища – медведь Топтыжень, ночной саблезуб Тенумбра и гиппогриф Острокоготь.$B$BЭти твари могучи, и, возможно, тебе понадобится помощь. Ели тебе удастся их одолеть, принеси мне доказательства своих подвигов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6384,'Дорога до Оргриммара','Оплатите полет в Оргриммар укротителю ветрокрылов Буроку и, оказавшись в Оргриммаре, отнесите мясные продукты Гримтака Гришке.','Какой вкусный запах! Ты часом не сырое мясо несешь?','Оплатите полет в Оргриммар укротителю ветрокрылов Буроку и, оказавшись в Оргриммаре, отнесите мясные продукты Заргха Гришке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога до Оргриммара',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оплатите полет в Оргриммар укротителю ветрокрылов Буроку и, оказавшись в Оргриммаре, отнесите мясные продукты Гримтака Гришке.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какой вкусный запах! Ты часом не сырое мясо несешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Оплатите полет в Оргриммар укротителю ветрокрылов Буроку и, оказавшись в Оргриммаре, отнесите мясные продукты Заргха Гришке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6385,'Укротитель ветрокрылов Дорас','Отнесите письмо Гришки Дорасу из Оргриммара.','Тебе нужен ветрокрыл?','Отнесите письмо Гришки Дорасу из Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротитель ветрокрылов Дорас',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо Гришки Дорасу из Оргриммара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе нужен ветрокрыл?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Отнесите письмо Гришки Дорасу из Оргриммара.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6386,'Оплатите перелет в Колючий Холм укротителю ветрокрылов Доресу и, оказавшись на месте, передайте письмо Гришки Гримтаку из Колючего Холма.','Ты вернулся из Оргриммара? Гришак понравилось мясо?','Оплатите перелет в Перекресток укротителю ветрокрылов Доресу и, оказавшись на месте, передайте письмо Гришки Заргху из Перекрестка.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оплатите перелет в Колючий Холм укротителю ветрокрылов Доресу и, оказавшись на месте, передайте письмо Гришки Гримтаку из Колючего Холма.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся из Оргриммара? Гришак понравилось мясо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Оплатите перелет в Перекресток укротителю ветрокрылов Доресу и, оказавшись на месте, передайте письмо Гришки Заргху из Перекрестка.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (6389,'Чума на вашу лесопилку!','Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели.$B$BПримериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу.','Выпустите термитов Чумных земель на лесопилке Северного Кряжа и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Западные Чумные земли.','Ха-ха, превосходно! Ты справился! Дух моего отца наконец сможет покоиться с миром, а уж я-то как доволен!$B$BСпасибо тебе! Проси что хочешь, чем смогу – помогу!','Вернитесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чума на вашу лесопилку!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели.$B$BПримериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпустите термитов Чумных земель на лесопилке Северного Кряжа и возвращайтесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра в Западные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха, превосходно! Ты справился! Дух моего отца наконец сможет покоиться с миром, а уж я-то как доволен!$B$BСпасибо тебе! Проси что хочешь, чем смогу – помогу!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Натаниэлю Дамаху в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6390,'Чума на вашу лесопилку!','Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели.$B$BПримериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу.','Выпустите термитов Чумных земель на лесопилке Северного Кряжа и возвращайтесь к Микки Левину в Бастион в Тирисфальских лесах.','Благодарю тебя от всей души, $N. Вот, возьми эти деньги от меня. И извини, что не могу дать больше...','Тебе удалось, $N? $GВыпустил:Выпустила; термитов?$B$BМои близкие лишились работы, а кое-кто и жизни, и я не желаю, чтобы вдобавок место, где прошло мое детство, досталось этим мнимым святошам!','Вернитесь к Микки Левин в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чума на вашу лесопилку!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы оглядываетесь в поисках чего-нибудь подходящего, чтобы открыть бочонок, и обнаруживаете ломик, вполне подходящий для этой цели.$B$BПримериваясь, как бы снести крышку одним ударом, вы возносите молитвы, чтобы успеть унести ноги, когда насекомые вырвутся на свободу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпустите термитов Чумных земель на лесопилке Северного Кряжа и возвращайтесь к Микки Левину в Бастион в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя от всей души, $N. Вот, возьми эти деньги от меня. И извини, что не могу дать больше...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось, $N? $GВыпустил:Выпустила; термитов?$B$BМои близкие лишились работы, а кое-кто и жизни, и я не желаю, чтобы вдобавок место, где прошло мое детство, досталось этим мнимым святошам!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Микки Левин в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6393,'Война элементалей','Совет Приливов послал меня объявить войну элементалям огня здесь, в Каменном Когте. Нептулон Хозяин Приливов, повелитель всех элементалей воды, лично заинтересован в том, чтобы узреть погибель всех наших огненных сородичей.$B$B$n, ты можешь помочь мне высоко подняться во мнении Совета путем уничтожения элементалей огня в Обугленной долине. После смерти от этих элементалей остаются огненные кристаллы. Отдай их мне, и ты получишь награду.','Принесите 10 Огненных кристаллов Цунаману в приют Солнечного Камня.','Совет Приливов проявляет нетерпение. Они желают положить конец войне, которая вот уже не одну эпоху идет во всех измерениях. Мои собратья жаждут услышать новости о грандиозной победе над ненавистными элементалями огня. Где же огненные кристаллы, что так нужны мне?','Вернитесь к Цунаману в Приют у Солнечного Камня в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война элементалей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Совет Приливов послал меня объявить войну элементалям огня здесь, в Каменном Когте. Нептулон Хозяин Приливов, повелитель всех элементалей воды, лично заинтересован в том, чтобы узреть погибель всех наших огненных сородичей.$B$B$n, ты можешь помочь мне высоко подняться во мнении Совета путем уничтожения элементалей огня в Обугленной долине. После смерти от этих элементалей остаются огненные кристаллы. Отдай их мне, и ты получишь награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 Огненных кристаллов Цунаману в приют Солнечного Камня.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Совет Приливов проявляет нетерпение. Они желают положить конец войне, которая вот уже не одну эпоху идет во всех измерениях. Мои собратья жаждут услышать новости о грандиозной победе над ненавистными элементалями огня. Где же огненные кристаллы, что так нужны мне?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Цунаману в Приют у Солнечного Камня в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6394,'Кирка Тазз\'рила','$n, ты $Gдобросовестный:добросовестная:r; |3-6($r). Можно доверить тебе еще одно дело?$b$bНе так давно я ходил искать минералы в грот к северу отсюда и забыл там свою любимую кирку. А когда я вернулся за ней, то обнаружил, что там уже полно кровожадных зверей! Не можешь ли ты сходить в Грот Пылающего Клинка и раздобыть мою кирку?$b$bЯ ее оставил в зале с водопадами. Кирка моя заговоренная – она светится в темноте, так что найти ее будет нетрудно... только, боюсь, ее уже стерегут!','Принесите штейгеру Тазз\'рилу его кирку.','Вернитесь к штейгеру Тазз\'рилу в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кирка Тазз\'рила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты $Gдобросовестный:добросовестная:r; |3-6($r). Можно доверить тебе еще одно дело?$b$bНе так давно я ходил искать минералы в грот к северу отсюда и забыл там свою любимую кирку. А когда я вернулся за ней, то обнаружил, что там уже полно кровожадных зверей! Не можешь ли ты сходить в Грот Пылающего Клинка и раздобыть мою кирку?$b$bЯ ее оставил в зале с водопадами. Кирка моя заговоренная – она светится в темноте, так что найти ее будет нетрудно... только, боюсь, ее уже стерегут!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите штейгеру Тазз\'рилу его кирку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Тазз\'рилу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6395,'Они просто идиоты... копающие себе могилы.','Вернитесь к новобранцу Элрет в Похоронный Звон, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Они просто идиоты... копающие себе могилы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к новобранцу Элрет в Похоронный Звон, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6401,'Кайя жива!','Передай Таммре Перекати-поле, тетушке Кайи, живущей в Приюте у Солнечного Камня, добрые новости – Кайя жива! Мы думали, что она погибла во время того жестокого нападения на нашу деревню. Иди по дороге на запад, и придешь в Приют у Солнечного Камня.','Передайте хорошие новости Таммре Перекати-поле, живущей в Приюте у Солнечного Камня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кайя жива!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Передай Таммре Перекати-поле, тетушке Кайи, живущей в Приюте у Солнечного Камня, добрые новости – Кайя жива! Мы думали, что она погибла во время того жестокого нападения на нашу деревню. Иди по дороге на запад, и придешь в Приют у Солнечного Камня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте хорошие новости Таммре Перекати-поле, живущей в Приюте у Солнечного Камня.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6402,'Встреча в Штормграде','Вы с Виндзором должны встретиться у ворот Штормграда.$b$bВиндзор расскажет такое, что все королевство содрогнется!$b$bИ не ходи туда $gодин:одна;, $n. Собери целую армию! Позови своих земляков. К оружию!','Отправьтесь в Штормград и подойдите к городским воротам. Поговорите с оруженосцем Роу, чтобы он сообщил маршалу Виндзору о вашем прибытии.','Прежде чем мы начнем, я прошу тебя собрать армию. Ведь нам придется столкнуться с драконом!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча в Штормграде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы с Виндзором должны встретиться у ворот Штормграда.$b$bВиндзор расскажет такое, что все королевство содрогнется!$b$bИ не ходи туда $gодин:одна;, $n. Собери целую армию! Позови своих земляков. К оружию!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь в Штормград и подойдите к городским воротам. Поговорите с оруженосцем Роу, чтобы он сообщил маршалу Виндзору о вашем прибытии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прежде чем мы начнем, я прошу тебя собрать армию. Ведь нам придется столкнуться с драконом!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (6403,'Великий Маскарад','Вот это было приключение, друг мой. Я перед вами в огромном, неоплатном долгу. Может быть, когда все будет кончено...$b$bКак уже доподлинно установлено вами, Леди Престор – это Ониксия, отродье Смертокрыла, сестра-близнец владыки Черной горы Нефариана.$b$bСлишком долго держала она наше королевство под контролем. Даже сам Верховный лорд – марионетка в ее руках... Это колдовство будет разрушено.$b$bНе надо бойтесь, вместе мы победим!$b$bВы готовы?','Сопроводите Реджинальда Виндзора через весь Штормград. Защитите его!','<Болвар вытаскивает пошарканный медальон.>$B$BМагия, которая здесь содержится, должна заработать снова. Нужен всего лишь драконий глаз.$B$BСамопожертвование Виндзора освободило наше королевство, но угроза со стороны Ониксии и ее выродков все еще существует.$B$BЭтот медальон будет держать мои мысли и мое тело в порядке. Он даст мне доступ к мыслям... самой Ониксии! И я узнаю ее секреты. Видения зыбки и туманны, но кое-что я все-таки узнаю!','Я... мне... я был бессилен.','Сопроводите Реджинальда Виндзора.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий Маскарад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот это было приключение, друг мой. Я перед вами в огромном, неоплатном долгу. Может быть, когда все будет кончено...$b$bКак уже доподлинно установлено вами, Леди Престор – это Ониксия, отродье Смертокрыла, сестра-близнец владыки Черной горы Нефариана.$b$bСлишком долго держала она наше королевство под контролем. Даже сам Верховный лорд – марионетка в ее руках... Это колдовство будет разрушено.$b$bНе надо бойтесь, вместе мы победим!$b$bВы готовы?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите Реджинальда Виндзора через весь Штормград. Защитите его!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Болвар вытаскивает пошарканный медальон.>$B$BМагия, которая здесь содержится, должна заработать снова. Нужен всего лишь драконий глаз.$B$BСамопожертвование Виндзора освободило наше королевство, но угроза со стороны Ониксии и ее выродков все еще существует.$B$BЭтот медальон будет держать мои мысли и мое тело в порядке. Он даст мне доступ к мыслям... самой Ониксии! И я узнаю ее секреты. Видения зыбки и туманны, но кое-что я все-таки узнаю!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я... мне... я был бессилен.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сопроводите Реджинальда Виндзора.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6421,'Ущелье Камнепадов','Что-то не так здесь, в Каменном Когте. Чувствуешь ли ты непокой, витающий в воздухе, $n?$B$BК юго-востоку отсюда, в ущелье Камнепадов, есть пещера. Там кобольды отчаянно ищут редкие кристаллы резонита. Я прошу тебя принести оттуда образцы руды, чтобы я мог понять, что происходит в этой пещере. Помимо того, неплохо бы тебе обследовать глубины этой пещеры.$B$BИди же, $gюный:юная:c; |3-6($c), мне очень важно знать, что за зло таится под этими горами.','Обследуйте глубины пещеры в ущелье Камнепадов и принесите 10 кристаллов резонита для исследования Мор\'рогалу в Приют у Солнечного Камня.','О да! Это оно – кристалл резонита несет следы земной магии. Должно быть, кобольды, докопавшись до глубин, обнаружили там земельника.\n\nЛегенда утверждает, что земельники – это существа, созданные титанами. Именно с их помощью создана земная твердь, по которой мы ступаем. Угроза велика, нельзя не обращать на нее внимания.\n\nМор\'рогал качает головой.\n\nБыть может, я сумею наложить заклинание на эти куски руды, чтобы нарушить затею кобольдов.','Какие новости из Ущелья Камнепадов? Я вспомнил, что существует легенда, в которой говорится о резоните... Но не за что ухватиться. Быть может, узнав, что таится на дне пещеры, мы сможем пролить свет на их зловещие намерения.','Обследуйте пещеру в ущелье Камнепадов','Вернитесь к Мор\'рогалу в Приют у Солнечного Камня в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ущелье Камнепадов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то не так здесь, в Каменном Когте. Чувствуешь ли ты непокой, витающий в воздухе, $n?$B$BК юго-востоку отсюда, в ущелье Камнепадов, есть пещера. Там кобольды отчаянно ищут редкие кристаллы резонита. Я прошу тебя принести оттуда образцы руды, чтобы я мог понять, что происходит в этой пещере. Помимо того, неплохо бы тебе обследовать глубины этой пещеры.$B$BИди же, $gюный:юная:c; |3-6($c), мне очень важно знать, что за зло таится под этими горами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обследуйте глубины пещеры в ущелье Камнепадов и принесите 10 кристаллов резонита для исследования Мор\'рогалу в Приют у Солнечного Камня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да! Это оно – кристалл резонита несет следы земной магии. Должно быть, кобольды, докопавшись до глубин, обнаружили там земельника.\n\nЛегенда утверждает, что земельники – это существа, созданные титанами. Именно с их помощью создана земная твердь, по которой мы ступаем. Угроза велика, нельзя не обращать на нее внимания.\n\nМор\'рогал качает головой.\n\nБыть может, я сумею наложить заклинание на эти куски руды, чтобы нарушить затею кобольдов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие новости из Ущелья Камнепадов? Я вспомнил, что существует легенда, в которой говорится о резоните... Но не за что ухватиться. Быть может, узнав, что таится на дне пещеры, мы сможем пролить свет на их зловещие намерения.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Обследуйте пещеру в ущелье Камнепадов',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мор\'рогалу в Приют у Солнечного Камня в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (6441,'Рога сатира','Вернитесь к Пиксель на Заставу Расщепленного Дерева.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рога сатира',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пиксель на Заставу Расщепленного Дерева.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6442,'Наги на Зорамском взморье','Зло рыщет по побережью, |3-6($r).$B$BЗдесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощенный морем. Разрушенный и почти забытый.$B$BТеперь в него непонятно почему вернулись наги. Но причина не так важна – мы должны защитить край, за который так упорно боролись.$B$BПринеси мне 20 их голов! Загони наг назад, в глубины моря!','Принесите 20 голов наг из клана Зловещего Хвоста Марукайе на Зорамское взморье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наги на Зорамском взморье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зло рыщет по побережью, |3-6($r).$B$BЗдесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощенный морем. Разрушенный и почти забытый.$B$BТеперь в него непонятно почему вернулись наги. Но причина не так важна – мы должны защитить край, за который так упорно боролись.$B$BПринеси мне 20 их голов! Загони наг назад, в глубины моря!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 голов наг из клана Зловещего Хвоста Марукайе на Зорамское взморье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6461,'Кровопийцы','Мы, тролли, тут, в Малака\'джине, живем с земли, да и живем хорошо. В Каменном Когте есть на что поохотиться. $B$BТолько вот повадились к нам в последнее время незваные гости... по ночам пауки на наши стоянки нападают, хотят украсть нашу добычу. $B$BЕсли поможешь нам поубивать этих злобных тварей, мы, тролли Малака\'джина, будем перед тобой в долгу. Тут, в Каменном Когте, пауки повсюду – ступай на север, и увидишь, о чем я толкую.','Ксен\'Зилла из Малака\'джина просит вас убить 10 моховых ползунов и 7 моховых ядоплюев.','Взгляни на наших маленьких друзей-эльфов! Заперты в клетках и не могут побродить по лесу!\n\nТебе удалось раздобыть для меня немного слизи? А как насчет усиков сумеречного бегуна? А разве у тебя еще нет чешуйки волшебного дракончика?\n\nА глаза? Мне нужно так много глаз! Невозможно составить доброе магическое лесное варево без хорошей порции глаз!','Вернитесь к Ксен\'зилле в Малака\'джин, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровопийцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы, тролли, тут, в Малака\'джине, живем с земли, да и живем хорошо. В Каменном Когте есть на что поохотиться. $B$BТолько вот повадились к нам в последнее время незваные гости... по ночам пауки на наши стоянки нападают, хотят украсть нашу добычу. $B$BЕсли поможешь нам поубивать этих злобных тварей, мы, тролли Малака\'джина, будем перед тобой в долгу. Тут, в Каменном Когте, пауки повсюду – ступай на север, и увидишь, о чем я толкую.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ксен\'Зилла из Малака\'джина просит вас убить 10 моховых ползунов и 7 моховых ядоплюев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Взгляни на наших маленьких друзей-эльфов! Заперты в клетках и не могут побродить по лесу!\n\nТебе удалось раздобыть для меня немного слизи? А как насчет усиков сумеречного бегуна? А разве у тебя еще нет чешуйки волшебного дракончика?\n\nА глаза? Мне нужно так много глаз! Невозможно составить доброе магическое лесное варево без хорошей порции глаз!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ксен\'зилле в Малака\'джин, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (6481,'Пробуждение земельника','Благодаря тебе, |3-6($c), мы узнали, что этой земле грозит великая опасность. Резонитовая емкость, найденная тобою в пещере, служит вместилищем для спящего земельника по имени Гоггерок. $B$BЯ изменил своей шаманской силой принесенные тобой кристаллы. Возьми кристалл резинита и разбей резонитовую емкость, где спит земельник.$B$BСразу после пробуждения Гоггерок будет ослаблен... Убей его, $n!','Откройте резонитовую емкость при помощи зачарованного кристалла резонита и затем убейте Гоггерока. Вернитесь к Мор\'рогалу с новостями и зачарованным кристаллом резонита.','Это хорошие новости, |3-6($C)! Я опасался того, что земельник может сделать с Калимдором.\n\nУничтожение Гоггерока было задачей, достойной истинного героя. Но тебе удалось справиться с этим, и теперь и Каменный Коготь, и Калимдор перед тобой в долгу, благородный |3-6($C).\n\nПрими это как заслуженную и достойную награду.','Вернитесь к Мор\'рогалу в Приют у Солнечного Камня в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение земельника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря тебе, |3-6($c), мы узнали, что этой земле грозит великая опасность. Резонитовая емкость, найденная тобою в пещере, служит вместилищем для спящего земельника по имени Гоггерок. $B$BЯ изменил своей шаманской силой принесенные тобой кристаллы. Возьми кристалл резинита и разбей резонитовую емкость, где спит земельник.$B$BСразу после пробуждения Гоггерок будет ослаблен... Убей его, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте резонитовую емкость при помощи зачарованного кристалла резонита и затем убейте Гоггерока. Вернитесь к Мор\'рогалу с новостями и зачарованным кристаллом резонита.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это хорошие новости, |3-6($C)! Я опасался того, что земельник может сделать с Калимдором.\n\nУничтожение Гоггерока было задачей, достойной истинного героя. Но тебе удалось справиться с этим, и теперь и Каменный Коготь, и Калимдор перед тобой в долгу, благородный |3-6($C).\n\nПрими это как заслуженную и достойную награду.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мор\'рогалу в Приют у Солнечного Камня в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`endtext_loc8`) VALUES (6482,'Свободу Руулу!','Выведите Руула за пределы владений Колючего Меха') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свободу Руулу!',`title_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Выведите Руула за пределы владений Колючего Меха',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (6501,'Око дракона','Фрагмент расколотого амулета – это все, что я могу вам предложить.$b$bВам придется найти еще одного дракона, который согласится помочь вам в изготовлении нового ключа. Как только вы добудете этот ключ, вам нужно будет отправиться в Драконьи топи в Пылевых топях. Там вы и найдете ее логово, $n.$b$bГде найти других драконов, готовых помочь? К сожалению, я не знаю... Говорят, что такие существуют. Некоторые из них могут даже жить среди нас в обличии людей, гномов или эльфов, например. Желаю вам удачи в поиске.','Найдите существ, способных вернуть силу фрагменту амулета "Око дракона". Все, что об этих существах известно – это то, что они есть.','Я знаю – кусочек от черной драконихи... матери выводка, Ониксия. Как противно...','Я чувствую, что ты излучаешь недобрую ауру, $R. Что у тебя может быть с собой такого, что обладало бы такой аурой?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Фрагмент расколотого амулета – это все, что я могу вам предложить.$b$bВам придется найти еще одного дракона, который согласится помочь вам в изготовлении нового ключа. Как только вы добудете этот ключ, вам нужно будет отправиться в Драконьи топи в Пылевых топях. Там вы и найдете ее логово, $n.$b$bГде найти других драконов, готовых помочь? К сожалению, я не знаю... Говорят, что такие существуют. Некоторые из них могут даже жить среди нас в обличии людей, гномов или эльфов, например. Желаю вам удачи в поиске.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите существ, способных вернуть силу фрагменту амулета "Око дракона". Все, что об этих существах известно – это то, что они есть.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю – кусочек от черной драконихи... матери выводка, Ониксия. Как противно...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую, что ты излучаешь недобрую ауру, $R. Что у тебя может быть с собой такого, что обладало бы такой аурой?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6502,'Амулет Пламени дракона','Это – заколдованная драконья чешуя. Целая чешуйка открывает проход в драконье логово, а в сломанном виде она бесполезна.$B$BЕе можно починить, но для этого требуется кровь могучего черного дракона. Есть один такой... Его зовут генерал Драккисат, он возглавляет армию драконоидов Нефариана. Тебе доводилось о нем слышать?$B$BВозвращайся с его кровью, |3-6($r), и я наложу чары на этот осколок. Тогда ты сможешь проникнуть в Логово Ониксии.','Добудьте кровь могучего черного дракона генерала Драккисата, которого можно найти сидящим на троне в залах Вознесения в Пике Черной горы.','Этот амулет и даст тебе путь к тому, что ты ищешь. Логово Ониксии находится в Пылевых топях. Пока у тебя есть амулет, ее защитные чары не остановят тебя у входа.$B$BСиние драконы желают тебе удачи, $N.','Река времени никогда не прекращает и не замедляет свой бег, $R. Моя жизнь бесконечна, но твоя – нет. Не теряй даром времени...','Вернитесь к Хале на Руины Кел\'Терила, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амулет Пламени дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это – заколдованная драконья чешуя. Целая чешуйка открывает проход в драконье логово, а в сломанном виде она бесполезна.$B$BЕе можно починить, но для этого требуется кровь могучего черного дракона. Есть один такой... Его зовут генерал Драккисат, он возглавляет армию драконоидов Нефариана. Тебе доводилось о нем слышать?$B$BВозвращайся с его кровью, |3-6($r), и я наложу чары на этот осколок. Тогда ты сможешь проникнуть в Логово Ониксии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте кровь могучего черного дракона генерала Драккисата, которого можно найти сидящим на троне в залах Вознесения в Пике Черной горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот амулет и даст тебе путь к тому, что ты ищешь. Логово Ониксии находится в Пылевых топях. Пока у тебя есть амулет, ее защитные чары не остановят тебя у входа.$B$BСиние драконы желают тебе удачи, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Река времени никогда не прекращает и не замедляет свой бег, $R. Моя жизнь бесконечна, но твоя – нет. Не теряй даром времени...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хале на Руины Кел\'Терила, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6503,'Вестницы Ясеневого леса','Проклятые эльфы! Знали, куда ударить больнее...$b$bА все эти их гонцы... Сколько раз я предупреждал, что они за нами шпионят, никто не прислушался. И вот результат – попались, как крысы под метлу.$b$bНо отомстить никогда не поздно! Отлови этих мерзавцев и заставь их заплатить за все!','Убейте 9 вестниц Ясеневого леса.','Жду отчета о деле с лазутчицами, $N.','Поговорите с Курай\'бин на Заставе Расщепленного Дерева.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вестницы Ясеневого леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проклятые эльфы! Знали, куда ударить больнее...$b$bА все эти их гонцы... Сколько раз я предупреждал, что они за нами шпионят, никто не прислушался. И вот результат – попались, как крысы под метлу.$b$bНо отомстить никогда не поздно! Отлови этих мерзавцев и заставь их заплатить за все!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 9 вестниц Ясеневого леса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Жду отчета о деле с лазутчицами, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Курай\'бин на Заставе Расщепленного Дерева.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6504,'Утраченные страницы','Этот крошшер я только что получила из Кабестана и как раз возвращалась на лесозаготовки Песни Войны, на свое рабочее место. Мне дали инструкцию к крошшеру, но по дороге назад у меня ее вырвало из рук порывом ветра. Все страницы разлетелись, и осталась у меня одна обложка.$B$BГде теперь эти страницы носит, одним предкам ведомо... Но как я резаком-то без них пользоваться буду? Не найдешь ли их для меня?','Найдите 12 пропавших страниц руководства по использованию крошшера и соберите их по порядку глав 1, 2 и 3. Верните страницы Гурде Печати Гнева близ Заставы Расщепленного Дерева.','Вернитесь к Гурде Печати Гнева на Заставу Расщепленного Дерева, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утраченные страницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот крошшер я только что получила из Кабестана и как раз возвращалась на лесозаготовки Песни Войны, на свое рабочее место. Мне дали инструкцию к крошшеру, но по дороге назад у меня ее вырвало из рук порывом ветра. Все страницы разлетелись, и осталась у меня одна обложка.$B$BГде теперь эти страницы носит, одним предкам ведомо... Но как я резаком-то без них пользоваться буду? Не найдешь ли их для меня?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 12 пропавших страниц руководства по использованию крошшера и соберите их по порядку глав 1, 2 и 3. Верните страницы Гурде Печати Гнева близ Заставы Расщепленного Дерева.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гурде Печати Гнева на Заставу Расщепленного Дерева, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (6521,'Нечестивый союз','Повелеваю тебе убить посланника Малкина – я не позволю ему выполнить волю Короля-лича. Он пишет, что ждет встречи где-то поблизости от Курганов Иглошкурых.$B$BЕго присутствие там многое объясняет. Сила тамошних иглогривов многократно увеличилась, и среди них отмечаются признаки чумы. Очевидно, они заключили с Малкином какое-то соглашение.$B$BНайди и убей Малкина, $n. Возвращайся ко мне, когда исполнишь мое повеление.','Принесите голову посла Малкина Брагору Кровопалу в Подгород.','Прекрасно. Ты хорошо поработал, |3-6($C). \n\nТеперь, после смерти Малкина, мы по крайней мере можем быть уверенными, что продвижение Плети будет остановлено. Темная Госпожа благодарит тебя за преданность и изволит одарить тебя. \n\nПока нам неизвестно, насколько прочные позиции заняла Плеть в Лабиринтах Иглошкурых, однако не сомневаюсь, что скоро нам удастся разузнать их замыслы.','Вернитесь к Брагору Кровопалу в Королевский квартал, что в Подгороде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нечестивый союз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Повелеваю тебе убить посланника Малкина – я не позволю ему выполнить волю Короля-лича. Он пишет, что ждет встречи где-то поблизости от Курганов Иглошкурых.$B$BЕго присутствие там многое объясняет. Сила тамошних иглогривов многократно увеличилась, и среди них отмечаются признаки чумы. Очевидно, они заключили с Малкином какое-то соглашение.$B$BНайди и убей Малкина, $n. Возвращайся ко мне, когда исполнишь мое повеление.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову посла Малкина Брагору Кровопалу в Подгород.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно. Ты хорошо поработал, |3-6($C). \n\nТеперь, после смерти Малкина, мы по крайней мере можем быть уверенными, что продвижение Плети будет остановлено. Темная Госпожа благодарит тебя за преданность и изволит одарить тебя. \n\nПока нам неизвестно, насколько прочные позиции заняла Плеть в Лабиринтах Иглошкурых, однако не сомневаюсь, что скоро нам удастся разузнать их замыслы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брагору Кровопалу в Королевский квартал, что в Подгороде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6522,'Нечестивый союз','Госпожа моя!$B$BНаше предложение вам прекрасно известно. Для вас это отличная возможность получить безграничную власть над Степями и окрестными землями. От вас нам требуется лишь небольшое содействие – дайте нам свободу действий в этих землях.$B$BМы убедительно просим вас рассмотреть это предложение. Мы обладаем великой силой и охотно поделимся ею с тем, кто достаточно мудр, чтобы примкнуть к нам. Я буду ждать вас у Курганов Иглошкурых.$B$BС наилучшими пожеланиями,$BПосланник Малкин.','Отнесите маленький свиток Брагору Кровопалу в Королевский квартал Подгорода.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нечестивый союз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Госпожа моя!$B$BНаше предложение вам прекрасно известно. Для вас это отличная возможность получить безграничную власть над Степями и окрестными землями. От вас нам требуется лишь небольшое содействие – дайте нам свободу действий в этих землях.$B$BМы убедительно просим вас рассмотреть это предложение. Мы обладаем великой силой и охотно поделимся ею с тем, кто достаточно мудр, чтобы примкнуть к нам. Я буду ждать вас у Курганов Иглошкурых.$B$BС наилучшими пожеланиями,$BПосланник Малкин.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите маленький свиток Брагору Кровопалу в Королевский квартал Подгорода.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6523,'Защита Кайи','Спасибо большое за спасение! Мы должны уходить побыстрее, прежде чем они обнаружат, что я на свободе. Я прошу сопроводить меня до Лагеря Апарахе. Оттуда я уже знаю, куда идти.$b$bМой отец, Макаба Плоское Копыто, наверное, уже отчаялся узнать, где я.','Проводите Кайю Плоское Копыто до Лагеря Апарахе, затем вернитесь к Макабе Плоскому Копыту, находящемуся поблизости от юго-восточного края Каменного Когтя.','Кайю проводили до Лагеря Апарахе.','Вернитесь к Макабе Плоскому Копыту в Долину Высокого леса, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Кайи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо большое за спасение! Мы должны уходить побыстрее, прежде чем они обнаружат, что я на свободе. Я прошу сопроводить меня до Лагеря Апарахе. Оттуда я уже знаю, куда идти.$b$bМой отец, Макаба Плоское Копыто, наверное, уже отчаялся узнать, где я.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите Кайю Плоское Копыто до Лагеря Апарахе, затем вернитесь к Макабе Плоскому Копыту, находящемуся поблизости от юго-восточного края Каменного Когтя.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Кайю проводили до Лагеря Апарахе.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Макабе Плоскому Копыту в Долину Высокого леса, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (6541,'Донесение Кадраку','Ты когда-нибудь $Gбывал:бывала; в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ.$B$BЕсли тебе это по сердцу, найди Кадрака в Северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение.','Доложите о своем прибытии Кадраку в сторожевой башне в Северных Степях.','Ясеневый лес – разделенный войной край, но наши недавние усилия увенчались успехом. Мы основали заставу не только на Зорамском взморье, но еще прямо к северу отсюда построили заставу Расщепленного Дерева.','Я очень занята, |3-6($C). Если ты пришел не по важному делу, иди своей дорогой...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение Кадраку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты когда-нибудь $Gбывал:бывала; в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ.$B$BЕсли тебе это по сердцу, найди Кадрака в Северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложите о своем прибытии Кадраку в сторожевой башне в Северных Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ясеневый лес – разделенный войной край, но наши недавние усилия увенчались успехом. Мы основали заставу не только на Зорамском взморье, но еще прямо к северу отсюда построили заставу Расщепленного Дерева.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я очень занята, |3-6($C). Если ты пришел не по важному делу, иди своей дорогой...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6542,'Донесение Кадраку','Ты когда-нибудь $Gбывал:бывала; в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ.$B$BЕсли тебе это по сердцу, найди Кадрака в Северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение.','Доложитесь Кадраку в сторожевой башне в Северных Степях.','Ясеневый лес – разделенный войной край, но наши недавние усилия увенчались успехом. Мы основали не только заставу на Зорамском взморье, но и еще прямо к северу отсюда построили заставу Расщепленного Дерева.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение Кадраку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты когда-нибудь $Gбывал:бывала; в Ясеневом лесу, на севере? Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ.$B$BЕсли тебе это по сердцу, найди Кадрака в Северных Степях, в сторожевой башне. Он руководит кампанией в Ясеневом лесу и может дать тебе поручение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь Кадраку в сторожевой башне в Северных Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ясеневый лес – разделенный войной край, но наши недавние усилия увенчались успехом. Мы основали не только заставу на Зорамском взморье, но и еще прямо к северу отсюда построили заставу Расщепленного Дерева.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (6543,'Отчет Песни Войны','Недавно я отправил в Ясеневый лес нескольких разведчиков. Мне нужен гонец, чтобы доставить им приказы и вернуться с отчетом об их наблюдениях.$B$BПервый твой пункт – застава Зорам\'гар, что на западном побережье на Зорамском взморье. Там ты найдешь первого гонца. Так же тебе придется заглянуть на Заставу Расщепленного Дерева, что на севере и к востоку по дороге близ Азшары. Там найдешь разведчика и сопровождающего.$B$BПередай каждому указания и забери у них новые донесения.','Распакуйте связку донесений. Доставьте отчеты Песни Войны разведчику, гонцу и всаднику клана Песни Войны. Возьмите у них новые донесения для Кадрака и доставьте ему в северную сторожевую башню в Степях.','Вижу, на тебя можно положиться. Эти новые сведения чрезвычайно важны для осуществления планов по расширению нашего присутствия в Ясеневом лесу. Теперь мы можем разработать следующий шаг.','Вернитесь к Кадраку на Заставу Мор\'шан, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчет Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно я отправил в Ясеневый лес нескольких разведчиков. Мне нужен гонец, чтобы доставить им приказы и вернуться с отчетом об их наблюдениях.$B$BПервый твой пункт – застава Зорам\'гар, что на западном побережье на Зорамском взморье. Там ты найдешь первого гонца. Так же тебе придется заглянуть на Заставу Расщепленного Дерева, что на севере и к востоку по дороге близ Азшары. Там найдешь разведчика и сопровождающего.$B$BПередай каждому указания и забери у них новые донесения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Распакуйте связку донесений. Доставьте отчеты Песни Войны разведчику, гонцу и всаднику клана Песни Войны. Возьмите у них новые донесения для Кадрака и доставьте ему в северную сторожевую башню в Степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, на тебя можно положиться. Эти новые сведения чрезвычайно важны для осуществления планов по расширению нашего присутствия в Ясеневом лесу. Теперь мы можем разработать следующий шаг.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кадраку на Заставу Мор\'шан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6544,'Налет Торека','Надеюсь, ты с грузом? У меня будут большие неприятности, если я не доставлю все как можно скорее!','Займите Аванпост Среброкрылых.','Вернитесь к Эртогу Лютоклыку к реке Фалфаррен, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Налет Торека',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты с грузом? У меня будут большие неприятности, если я не доставлю все как можно скорее!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Займите Аванпост Среброкрылых.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эртогу Лютоклыку к реке Фалфаррен, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6545,'Сведения гонца клана Песни Войны','Мои сведения должны многое объяснить Кадраку. Ты $Gдолжен:должна; как можно скорее вернуться к нему.','Так у тебя есть для меня приказ? Всегда приятно увидеть новобранца с горячей душой и твердой волей.$B$BТебе нужна хорошая соображалка, если хочешь задержаться здесь. Наги все сильнее угрожают нам, $N. Я сам видел. А с тех пор как я сюда прибыл, мне несколько раз приходилось отбивать их нападения на этой самой заставе.$B$BНо если тебе охота поучаствовать в этом, поговори с кем-нибудь еще на заставе.','Вернитесь к гонцу клана Песни Войны в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сведения гонца клана Песни Войны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои сведения должны многое объяснить Кадраку. Ты $Gдолжен:должна; как можно скорее вернуться к нему.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так у тебя есть для меня приказ? Всегда приятно увидеть новобранца с горячей душой и твердой волей.$B$BТебе нужна хорошая соображалка, если хочешь задержаться здесь. Наги все сильнее угрожают нам, $N. Я сам видел. А с тех пор как я сюда прибыл, мне несколько раз приходилось отбивать их нападения на этой самой заставе.$B$BНо если тебе охота поучаствовать в этом, поговори с кем-нибудь еще на заставе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к гонцу клана Песни Войны в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6546,'Сведения всадника из клана Песни Войны','Отнеси мои сведения Кадраку. Быстрее, $N.','Большая опасность лежит на твоем пути, $N. Ты $Gделал:делала; все возможно чтобы помочь этим землям. Но угроза Альянса совсем близка.$B$BМы столкнусь на всех наших фронтах с врагами. Сатиры – распространенная угроза в восточном Ясеневом лесе. Кроме того, я обнаружил, что наги наводнили большую часть Азшары.$B$BПриятно видеть, что мы до сих пор укрепляем наши ряды. Всегда будь $Bготов:готова; к сражениям, $N.','Вернитесь к всаднику из клана Песни Войны в Азшару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сведения всадника из клана Песни Войны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отнеси мои сведения Кадраку. Быстрее, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Большая опасность лежит на твоем пути, $N. Ты $Gделал:делала; все возможно чтобы помочь этим землям. Но угроза Альянса совсем близка.$B$BМы столкнусь на всех наших фронтах с врагами. Сатиры – распространенная угроза в восточном Ясеневом лесе. Кроме того, я обнаружил, что наги наводнили большую часть Азшары.$B$BПриятно видеть, что мы до сих пор укрепляем наши ряды. Всегда будь $Bготов:готова; к сражениям, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к всаднику из клана Песни Войны в Азшару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6547,'Сведения разведчика клана Песни Войны','Пусть Кадрак узнает, что мы добились успеха, задержав ночных эльфов. Все идет по плану.','Держи ухо востро, $R. В тенях часто скрываются эльфы...$B$BМы должны быть начеку постоянно. Нам слишком тяжело достались эти земли, и эльфы всегда ищут случая отнять их у нас.$B$BКак я понимаю, у тебя есть очередное поручение для меня от Кадрака?','Вернитесь к разведчику клана Песни Войны в Ясеневый лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сведения разведчика клана Песни Войны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть Кадрак узнает, что мы добились успеха, задержав ночных эльфов. Все идет по плану.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Держи ухо востро, $R. В тенях часто скрываются эльфы...$B$BМы должны быть начеку постоянно. Нам слишком тяжело достались эти земли, и эльфы всегда ищут случая отнять их у нас.$B$BКак я понимаю, у тебя есть очередное поручение для меня от Кадрака?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику клана Песни Войны в Ясеневый лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6548,'Отомсти за мою деревню','Клан Зловещего Тотема напал на мою деревню и убил почти всех жителей. Я сразил столько нападавших, сколько мог, но едва спас собственную жизнь.$b$b$n, все, чего я желаю – это чтобы как можно больше этих негодяев умерло. Ты найдешь их к западу отсюда.','Убейте 8 бузотеров и 6 наемников из племени Зловещего Тотема, затем вернитесь к Макабе Плоскому Копыту, ожидающему вас на юго-восточной границе Когтистых гор.','Тебе удалось их убить?','Вернитесь к Макабу Плоскому Копыту на границу между Степями и Когтистыми горами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отомсти за мою деревню',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Зловещего Тотема напал на мою деревню и убил почти всех жителей. Я сразил столько нападавших, сколько мог, но едва спас собственную жизнь.$b$b$n, все, чего я желаю – это чтобы как можно больше этих негодяев умерло. Ты найдешь их к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 бузотеров и 6 наемников из племени Зловещего Тотема, затем вернитесь к Макабе Плоскому Копыту, ожидающему вас на юго-восточной границе Когтистых гор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось их убить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Макабу Плоскому Копыту на границу между Степями и Когтистыми горами.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (6561,'Вернитесь к Башане Руническому Тотему в Золотые равнины, что в Мулгоре.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Башане Руническому Тотему в Золотые равнины, что в Мулгоре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6562,'Угроза из Глубин','Дже\'неу Санкри нужна помощь. Он ждет в Непроглядной Пучине, что в Ясеневом лесу. Этот лес ночных эльфов находится к северу от Когтистых гор. Ты можешь добраться до него через Утес Ветрорезов или идя на север через Степи. Зорамское взморье лежит далеко на западе от леса. Будь $Gосторожен:осторожна;, $n. Там обитают такие силы, от которых теплого приема не жди.','Поговорите с Дже\'неу Санкри в Ясеневом лесу.','Тебя послал Цунаман? Великолепно. Тогда нам есть что обсудить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза из Глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дже\'неу Санкри нужна помощь. Он ждет в Непроглядной Пучине, что в Ясеневом лесу. Этот лес ночных эльфов находится к северу от Когтистых гор. Ты можешь добраться до него через Утес Ветрорезов или идя на север через Степи. Зорамское взморье лежит далеко на западе от леса. Будь $Gосторожен:осторожна;, $n. Там обитают такие силы, от которых теплого приема не жди.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дже\'неу Санкри в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя послал Цунаман? Великолепно. Тогда нам есть что обсудить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`completedtext_loc8`) VALUES (6563,'В начале туннелей Непроглядной Пучины по стенам пещер можно найти большие сапфировые друзы. Недавно было замечено, что эти кристаллы собирают наги. Пока не станет ясно, зачем им это, сдается мне, что надо наг этой возможности лишить. В кристаллах этих содержится великая сила стихий, и если их применить не как должно, то они могут стать мощным чародейским ингредиентом.$B$BТы мне не поможешь, $n? Непроглядная Пучина находится на Зорамском взморье к северу от нашей заставы.','Вернитесь к Дже\'неу Санкри на заставу Зорам\'гар, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В начале туннелей Непроглядной Пучины по стенам пещер можно найти большие сапфировые друзы. Недавно было замечено, что эти кристаллы собирают наги. Пока не станет ясно, зачем им это, сдается мне, что надо наг этой возможности лишить. В кристаллах этих содержится великая сила стихий, и если их применить не как должно, то они могут стать мощным чародейским ингредиентом.$B$BТы мне не поможешь, $n? Непроглядная Пучина находится на Зорамском взморье к северу от нашей заставы.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дже\'неу Санкри на заставу Зорам\'гар, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6564,'Верность древним богам','Принесите отсыревшую записку Дже\'неу Санкри в Ясеневый лес.','Это и правда интересно. Я рад, что ты принес мне эту записку.\n\nТеперь мы знаем, как зовут причину наших бед... Лоргус Джетт!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верность древним богам',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите отсыревшую записку Дже\'неу Санкри в Ясеневый лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это и правда интересно. Я рад, что ты принес мне эту записку.\n\nТеперь мы знаем, как зовут причину наших бед... Лоргус Джетт!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6565,'Верность древним богам','Мы не можем допустить, чтобы этот последователь Сумеречного Молота осуществил свое намерение. Клан Сумеречного Молота не понимает духов Природы. Они верят в древних богов – богов хаоса и разрушения, побежденных давным-давно. Нельзя дать этому Лоргусу добиться своего! Ты $Gдолжен:должна; остановить его, $n. Мне самому этого не сделать – я слишком слаб.$B$BСтупай в Непроглядную Пучину, найди и убей его! А потом возвращайся сюда.','Убейте Лоргуса Джетта.','Удалось ли тебе отыскать глубинный сердечник? Без него нам не понять, что именно затевает там Сумеречный Молот.','Вернитесь к Дже\'неу Санкри.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верность древним богам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не можем допустить, чтобы этот последователь Сумеречного Молота осуществил свое намерение. Клан Сумеречного Молота не понимает духов Природы. Они верят в древних богов – богов хаоса и разрушения, побежденных давным-давно. Нельзя дать этому Лоргусу добиться своего! Ты $Gдолжен:должна; остановить его, $n. Мне самому этого не сделать – я слишком слаб.$B$BСтупай в Непроглядную Пучину, найди и убей его! А потом возвращайся сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Лоргуса Джетта.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе отыскать глубинный сердечник? Без него нам не понять, что именно затевает там Сумеречный Молот.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дже\'неу Санкри.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6566,'Что принес ветер','Рад видеть тебя снова, $n. Ветер принес вести из Восточного королевства.$b$bСадись и слушай.','Выслушайте Тралла.','$GГотов:Готова; ли ты взять на себя эту задачу?','Терпение, $N.','Выслушайте Тралла.','Вернитесь к Траллу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что принес ветер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рад видеть тебя снова, $n. Ветер принес вести из Восточного королевства.$b$bСадись и слушай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте Тралла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GГотов:Готова; ли ты взять на себя эту задачу?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Терпение, $N.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Выслушайте Тралла.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Траллу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6567,'Защитник Орды','Рексар, один из самых преданных моих защитников, нашел путь в логово дракона. Однако он покинул Азерот, чтобы присоединиться к экспедиции в Запределье.$b$bОн оставил в Деревне Ночных Охотников своего товарища Рокаро, который тоже знает этот путь. Отыщи его.','Найдите Рокаро в Деревне Ночных Охотников в Пустошах.','Существует только один способ проникнуть в логово дракона, $N.$B$BВидишь ли, только сильнейшим из черных драконов разрешается входить в логово праматери! Они должны пройти немало испытаний, прежде чем получат доступ к ключу, который должен быть зачарован самим генералом Драккисатом.$B$BПоскольку ты не из рода черных драконов, тебе придется столкнуться с определенными трудностями, чтобы проникнуть туда.$B$B<Рокаро усмехается.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитник Орды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рексар, один из самых преданных моих защитников, нашел путь в логово дракона. Однако он покинул Азерот, чтобы присоединиться к экспедиции в Запределье.$b$bОн оставил в Деревне Ночных Охотников своего товарища Рокаро, который тоже знает этот путь. Отыщи его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Рокаро в Деревне Ночных Охотников в Пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Существует только один способ проникнуть в логово дракона, $N.$B$BВидишь ли, только сильнейшим из черных драконов разрешается входить в логово праматери! Они должны пройти немало испытаний, прежде чем получат доступ к ключу, который должен быть зачарован самим генералом Драккисатом.$B$BПоскольку ты не из рода черных драконов, тебе придется столкнуться с определенными трудностями, чтобы проникнуть туда.$B$B<Рокаро усмехается.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (6568,'Мастерица обмана','Иллюзия и маскировка: вот два способа, которые помогут тебе обмануть черных драконов и добыть то, что ты ищешь.$B$BКонечно, я тоже мог бы преподать тебе некоторые уроки в искусстве обмана, но здесь тебе понадобится помощь мастера.$B$BЯ знаю, кто смог бы тебе помочь. Тебе нужно отправиться в Западные Чумные земли и разыскать там Миранду Колдунью: когда-то она была мастером иллюзий Лордерона. В прошлом Миранда не раз помогала нам; она поможет и тебе, если сочтет твои цели достойными.$B$BВот, отнеси ей это послание.','Доставьте письмо Рокаро Миранде Колдунье в Западные Чумные земли.','<Миранда читает письмо, затем улыбается.>$B$BНу и как он? Рокаро, я имею в виду. Письмо между прочим пустое. Так что на словах тебе придется передать... Да ладно тебе, а если бы тебя захватили в плен? И письмо бы прочли?$B$BЛадно, забудь! Миранда поможет тебе, $R.$B$B<Миранда улыбается.>','Не так часто увидишь Ордынца в этих частях Лордерона. И что у тебя есть для Миранды?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастерица обмана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иллюзия и маскировка: вот два способа, которые помогут тебе обмануть черных драконов и добыть то, что ты ищешь.$B$BКонечно, я тоже мог бы преподать тебе некоторые уроки в искусстве обмана, но здесь тебе понадобится помощь мастера.$B$BЯ знаю, кто смог бы тебе помочь. Тебе нужно отправиться в Западные Чумные земли и разыскать там Миранду Колдунью: когда-то она была мастером иллюзий Лордерона. В прошлом Миранда не раз помогала нам; она поможет и тебе, если сочтет твои цели достойными.$B$BВот, отнеси ей это послание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте письмо Рокаро Миранде Колдунье в Западные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Миранда читает письмо, затем улыбается.>$B$BНу и как он? Рокаро, я имею в виду. Письмо между прочим пустое. Так что на словах тебе придется передать... Да ладно тебе, а если бы тебя захватили в плен? И письмо бы прочли?$B$BЛадно, забудь! Миранда поможет тебе, $R.$B$B<Миранда улыбается.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не так часто увидишь Ордынца в этих частях Лордерона. И что у тебя есть для Миранды?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6569,'Иллюзии ока','Значит, |3-6($r) $gвозжелал:возжелала; войти в Черное Племя?$b$bСоздать необходимую тебе иллюзию – пара пустяков. Куда труднее собрать компоненты, необходимые для наложения этих чар. Раз Вождь поручил тебе такую миссию, Миранде остается повиноваться.$b$bОтправляйся в верхнюю часть крепости на Пике Черной горы и убей столько черных драконоидов, чтобы набить заплечные мешки их глазами.$b$bКогда наберешь достаточно, возвращайся к Миранде.','Отправляйтесь на Пик Черной горы и добудьте 20 глаз черных драконоидов. По выполнении задания вернитесь к Миранде Колдунье.','Позволь Миранде взглянуть, $R.$B$BА да, это сработает хорошо.$B$BС этими реагентами, Миранда сделает тебе медальон, создающий иллюзию, которая обманет драконьего стража ворот.','Глаза тех, кого мы хотим изобразить, являются основной частью любой иллюзии, $N.$B$B<Миранда показывает на сумку, доверху наполненную глазными яблоками с пометкой "Алый Орден".>$B$B<Миранда смеется.>','Вернитесь к Миранде Колдунье на Холм Печали, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Иллюзии ока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, |3-6($r) $gвозжелал:возжелала; войти в Черное Племя?$b$bСоздать необходимую тебе иллюзию – пара пустяков. Куда труднее собрать компоненты, необходимые для наложения этих чар. Раз Вождь поручил тебе такую миссию, Миранде остается повиноваться.$b$bОтправляйся в верхнюю часть крепости на Пике Черной горы и убей столько черных драконоидов, чтобы набить заплечные мешки их глазами.$b$bКогда наберешь достаточно, возвращайся к Миранде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Пик Черной горы и добудьте 20 глаз черных драконоидов. По выполнении задания вернитесь к Миранде Колдунье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Позволь Миранде взглянуть, $R.$B$BА да, это сработает хорошо.$B$BС этими реагентами, Миранда сделает тебе медальон, создающий иллюзию, которая обманет драконьего стража ворот.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Глаза тех, кого мы хотим изобразить, являются основной частью любой иллюзии, $N.$B$B<Миранда показывает на сумку, доверху наполненную глазными яблоками с пометкой "Алый Орден".>$B$B<Миранда смеется.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миранде Колдунье на Холм Печали, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6570,'Огнебор','Благодаря этому медальону в пределах логова Огнебора ты будешь сохранять нужный облик.$b$BОгнебор – старый дракон, древний привратник Нефариана. На него возложена обязанность испытывать тех драконоидов, которые должны войти в элитную стражу Ониксии.$b$bОтправляйся в Драконьи топи в Пылевых топях и войди в его логово. Оказавшись внутри, надень амулет, и следуй за своей судьбой!','Отправляйтесь в Драконьи топи в Пылевых топях и найдите Логово Огнебора. Оказавшись внутри, наденьте амулет Обмана драконов и поговорите с Огнебором.','Нефариан посылает мне дракончиков? Ты никогда не пройдешь моих испытаний.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огнебор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря этому медальону в пределах логова Огнебора ты будешь сохранять нужный облик.$b$BОгнебор – старый дракон, древний привратник Нефариана. На него возложена обязанность испытывать тех драконоидов, которые должны войти в элитную стражу Ониксии.$b$bОтправляйся в Драконьи топи в Пылевых топях и войди в его логово. Оказавшись внутри, надень амулет, и следуй за своей судьбой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Драконьи топи в Пылевых топях и найдите Логово Огнебора. Оказавшись внутри, наденьте амулет Обмана драконов и поговорите с Огнебором.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нефариан посылает мне дракончиков? Ты никогда не пройдешь моих испытаний.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (6571,'Поставка для Песни Войны','Нам на лесозаготовках Песни Войны страшно не хватает кое-чего!$B$BУ Пиксель на Заставе Расщепленного Дерева наш груз лезвий для пил. За ящиком топоров от управляющего пристанью Подгребая придется сгонять в Пиратскую Бухту. $B$BА получить груз масла и веревок будет еще труднее. Веревку стянули фурболги Колючего Меха и Гиблой Чащи, а сатиры перехватили партию масла, и теперь изводят его на свои гадкие ритуалы на Ночной поляне, Сатирнааре и Ксавиане!$B$BТы мне поможешь?','Соберите полностью поставку Песни Войны: лезвия для пил, веревку для бревен, масло и партию топоров Песни Войны для Локе Окарра на Заставе Расщепленного Дерева.','Надеюсь, ты с грузом? У меня будут большие неприятности, если я не доставлю все как можно скорее!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поставка для Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам на лесозаготовках Песни Войны страшно не хватает кое-чего!$B$BУ Пиксель на Заставе Расщепленного Дерева наш груз лезвий для пил. За ящиком топоров от управляющего пристанью Подгребая придется сгонять в Пиратскую Бухту. $B$BА получить груз масла и веревок будет еще труднее. Веревку стянули фурболги Колючего Меха и Гиблой Чащи, а сатиры перехватили партию масла, и теперь изводят его на свои гадкие ритуалы на Ночной поляне, Сатирнааре и Ксавиане!$B$BТы мне поможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите полностью поставку Песни Войны: лезвия для пил, веревку для бревен, масло и партию топоров Песни Войны для Локе Окарра на Заставе Расщепленного Дерева.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты с грузом? У меня будут большие неприятности, если я не доставлю все как можно скорее!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (6581,'Лезвие пилы Песни Войны','Само совершенство – то, что надо! Ладно, вот груз.','Прямо из Кабестана, свежие лезвия для пил Песни Войны! Да, они у меня с собой.$B$BНо чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!$B$BЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защитить себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.$B$BИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лезвие пилы Песни Войны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Само совершенство – то, что надо! Ладно, вот груз.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прямо из Кабестана, свежие лезвия для пил Песни Войны! Да, они у меня с собой.$B$BНо чем вы мне заплатите? Вы же не можете забрать их просто так! Мое время дорого стоит!$B$BЧестно говоря, мне нужно доброе ружье для моих поездок. Девушке ведь надо уметь защитить себя, вы ведь понимаете? Есть одно ружье, которое мне по нраву, и я уверена, что инженер без проблем такое сделает.$B$BИ если вы принесете мне хороший мушкетон, я отдам вам партию лезвий. Идет?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6582,'Черепа: Провидец','Найдите в Зимних Ключах избранного бойца синих дракона по имени Провидец и убейте его. С его черепом вернитесь к Огнебору.','Один из нессскольких пал...','<Огнебор шипит.>','Вернитесь к Огнебору в Пылевые топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черепа: Провидец',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Зимних Ключах избранного бойца синих дракона по имени Провидец и убейте его. С его черепом вернитесь к Огнебору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Один из нессскольких пал...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Огнебор шипит.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Огнебору в Пылевые топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6583,'Черепа: Сомнус','Наш отец сокрушил самих Аспектов, а наш долг – сеять хаос и страх среди их детей.$b$bТы $Gдолжен:должна; показать свою боевую мощь бессонно грезящим. Я говорю о зеленых драконах.$b$bОтправляйся на Болото Печали и порази Сомнуса, избранного бойца зеленых драконов. Не сдерживай своей ненависти, раздави его, как червяка, и вернись ко мне с его черепом.','Убейте избранного бойца зеленых драконов Сомнуса и вернитесь с его черепом к Огнебору.','Еще один пал...','Не возвращайся сюда, пока не искупаешь в крови наших врагов и не впитаешь их страдания.','Вернитесь к Огнебору в Логово Огнебора, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черепа: Сомнус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш отец сокрушил самих Аспектов, а наш долг – сеять хаос и страх среди их детей.$b$bТы $Gдолжен:должна; показать свою боевую мощь бессонно грезящим. Я говорю о зеленых драконах.$b$bОтправляйся на Болото Печали и порази Сомнуса, избранного бойца зеленых драконов. Не сдерживай своей ненависти, раздави его, как червяка, и вернись ко мне с его черепом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте избранного бойца зеленых драконов Сомнуса и вернитесь с его черепом к Огнебору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще один пал...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не возвращайся сюда, пока не искупаешь в крови наших врагов и не впитаешь их страдания.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Огнебору в Логово Огнебора, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6584,'Черепа: Хроналис','Дозорные Времени, дети Ноздорму – Повелителя Вечноссссти...$b$bТрое из них охраняют Пещеры Времени, но только один из этих троих представляет интерес для черных драконов: Изменяющий время Хроналис, любимый отпрыск Нодзорму. Расправьсссся с ним так, чтобы даже песок в его часах рыдал от ужаса, и вернись ко мне с его черепом.','Убейте Хроналиса, охраняющего Пещеры Времени в Пустыне Танарис и вернитесь с его черепом к Огнебору.','Остались самые ненависсстные...','По иронии судьбы, время имеет решающее значение.','Вернитесь к Огнебору в Логово Огнебора, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черепа: Хроналис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дозорные Времени, дети Ноздорму – Повелителя Вечноссссти...$b$bТрое из них охраняют Пещеры Времени, но только один из этих троих представляет интерес для черных драконов: Изменяющий время Хроналис, любимый отпрыск Нодзорму. Расправьсссся с ним так, чтобы даже песок в его часах рыдал от ужаса, и вернись ко мне с его черепом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Хроналиса, охраняющего Пещеры Времени в Пустыне Танарис и вернитесь с его черепом к Огнебору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Остались самые ненависсстные...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','По иронии судьбы, время имеет решающее значение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Огнебору в Логово Огнебора, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6585,'Черепа: Акстроз','Над горами Грим Батола отец наш бился против объединенных сил Аспектов. Но коварное предательство Алекстразы дало им возможность избежать его гнева.$b$bПосссзорное пятно на иссстории нашшшего рода.$b$bТеперь Грим Батол стерегут красные драконы. Их военачальник Акстроз должен быть убит, а его череп доставлен мне. Вперед, птенчик! За нашего Отца!','Отправьтесь в Грим Батол и убейте Акстроза, избранного бойца красных драконов. Принесите его череп Огнебору.','Я сомневался в твоей самоотверженности, но ты $Gстоял:стояла; на своем, поражая наших врагов и принося славу нашему роду.$B$BТеперь я приготовлю черепа.','Перемены... Я чувствую их в тебе... Пройди этот тест и останется только церемония.','Вернитесь к Огнебору в Логово Огнебора, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Черепа: Акстроз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Над горами Грим Батола отец наш бился против объединенных сил Аспектов. Но коварное предательство Алекстразы дало им возможность избежать его гнева.$b$bПосссзорное пятно на иссстории нашшшего рода.$b$bТеперь Грим Батол стерегут красные драконы. Их военачальник Акстроз должен быть убит, а его череп доставлен мне. Вперед, птенчик! За нашего Отца!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь в Грим Батол и убейте Акстроза, избранного бойца красных драконов. Принесите его череп Огнебору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я сомневался в твоей самоотверженности, но ты $Gстоял:стояла; на своем, поражая наших врагов и принося славу нашему роду.$B$BТеперь я приготовлю черепа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Перемены... Я чувствую их в тебе... Пройди этот тест и останется только церемония.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Огнебору в Логово Огнебора, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (6601,'Вознесение','Из черепов наших врагов сделан медальон. Ты его ссснаешшь, не правда ли? Ты несомненно $Gвидел:видела; его на ваших старейшинах.$b$bВозьми его, птенчик, отнеси на Пик и отдай генералу Драккисату. Генерал наложит на него последнее заклятье, чтобы настроить амулет на тебя.$b$bТы будешь носить его как знак доблести, обозначающий твою принадлежность к одному из самых привилегированных слоев нашего общества, Защитникам Царицы Драконов.$b$bИди же!','Казалось бы, загадка разгадана. Вы знаете, что амулет Обмана Драконов, который сделала для вас Миранда Колдунья, не будет работать на Пике Черной горы. Найдите Рокаро и расскажите о ваших затруднениях. Покажите ему амулет Угасающего Пламени Дракона. Будем надеяться, он знает что делать.','Этот драконий разговор, $N – не более чем сотрясение воздуха. Высокопарное угрожающее поведение – это то, что от них следует ожидать.','Не паникуй, $N!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вознесение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из черепов наших врагов сделан медальон. Ты его ссснаешшь, не правда ли? Ты несомненно $Gвидел:видела; его на ваших старейшинах.$b$bВозьми его, птенчик, отнеси на Пик и отдай генералу Драккисату. Генерал наложит на него последнее заклятье, чтобы настроить амулет на тебя.$b$bТы будешь носить его как знак доблести, обозначающий твою принадлежность к одному из самых привилегированных слоев нашего общества, Защитникам Царицы Драконов.$b$bИди же!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Казалось бы, загадка разгадана. Вы знаете, что амулет Обмана Драконов, который сделала для вас Миранда Колдунья, не будет работать на Пике Черной горы. Найдите Рокаро и расскажите о ваших затруднениях. Покажите ему амулет Угасающего Пламени Дракона. Будем надеяться, он знает что делать.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот драконий разговор, $N – не более чем сотрясение воздуха. Высокопарное угрожающее поведение – это то, что от них следует ожидать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не паникуй, $N!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6602,'Кровь могучего черного дракона','Как насчет того, чтобы нанести визит генералу? На этот раз – никаких иллюзий и прикрытий.$B$BЦеремония?.. Весьма изящное определение для той кровавой бойни, которой так любят услаждать себя черные драконы.$B$BВсе, чего недостает этому амулету – кровь генерала Драккисата. Весьма примитивная защита. Я расскажу тебе, как разрешить эту маленькую проблему.$B$BОтправляйся к Пику Черной горы и прикончи Драккисата. Принеси мне его кровь, и я активирую ключ от Логова Ониксии.','Отправляйтесь к Пику Черной горы и убейте генерала Драккисата. Соберите его кровь и вернитесь к Рокаро.','Победа, которая запомнится на много лет, $N. Амулет Пламени дракона откроет путь к Логову Ониксии. Собери своих союзников и принеси победу Орде!','Я думаю, что не стоит тебе говорить, что Драккисата не следует недооценивать.$B$BПо его рукам стекает кровь тысячи мертвых.','Вернитесь к Рокаро в Деревню Ночных Охотников, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь могучего черного дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как насчет того, чтобы нанести визит генералу? На этот раз – никаких иллюзий и прикрытий.$B$BЦеремония?.. Весьма изящное определение для той кровавой бойни, которой так любят услаждать себя черные драконы.$B$BВсе, чего недостает этому амулету – кровь генерала Драккисата. Весьма примитивная защита. Я расскажу тебе, как разрешить эту маленькую проблему.$B$BОтправляйся к Пику Черной горы и прикончи Драккисата. Принеси мне его кровь, и я активирую ключ от Логова Ониксии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Пику Черной горы и убейте генерала Драккисата. Соберите его кровь и вернитесь к Рокаро.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Победа, которая запомнится на много лет, $N. Амулет Пламени дракона откроет путь к Логову Ониксии. Собери своих союзников и принеси победу Орде!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я думаю, что не стоит тебе говорить, что Драккисата не следует недооценивать.$B$BПо его рукам стекает кровь тысячи мертвых.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рокаро в Деревню Ночных Охотников, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6603,'Сложности в Зимних ключах!','В Зимних ключах какая-то заваруха!$B$BЯ некоторое время жила в тех диких местах и в этих вещах разбираюсь... Я всегда с гордостью это говорю. По мне, так время, что я прожила в холмах, прямо-таки золотое времечко. Помогает развивать быстроту рефлексов, сохранять холодную голову и держать ухо востро...$B$BЧтобы так разбираться в ситуации в диких краях, как я, надо быть зрелым и иметь хорошие мозги.$B$BЛадно, о чем, бишь, я?$B$BА, да, заваруха. Найди Донову Снегонору у горячих источников, и она расскажет тебе побольше.','Найдите Донову Снегонору у горячего источника в Зимних ключах.','О, привет! Значит, Мегги рассказала тебе о моих трудностях?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сложности в Зимних ключах!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Зимних ключах какая-то заваруха!$B$BЯ некоторое время жила в тех диких местах и в этих вещах разбираюсь... Я всегда с гордостью это говорю. По мне, так время, что я прожила в холмах, прямо-таки золотое времечко. Помогает развивать быстроту рефлексов, сохранять холодную голову и держать ухо востро...$B$BЧтобы так разбираться в ситуации в диких краях, как я, надо быть зрелым и иметь хорошие мозги.$B$BЛадно, о чем, бишь, я?$B$BА, да, заваруха. Найди Донову Снегонору у горячих источников, и она расскажет тебе побольше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Донову Снегонору у горячего источника в Зимних ключах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, привет! Значит, Мегги рассказала тебе о моих трудностях?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6604,'Разъяренные дикие совухи','$gЗаметил:Заметила; заброшенный лагерь на юге? Такое впечатление, что дикие совухи сошли с ума и уничтожили все, до чего смогли дотянуться! $b$bЯ слыхал, что один из выживших после этой атаки сейчас приходит в себя в деревне Звездопада, к западу отсюда. Мне очень любопытно, что же там произошло... а тебе?','Поговорите с Джероном Гранильщиком в деревне Звездопада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разъяренные дикие совухи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gЗаметил:Заметила; заброшенный лагерь на юге? Такое впечатление, что дикие совухи сошли с ума и уничтожили все, до чего смогли дотянуться! $b$bЯ слыхал, что один из выживших после этой атаки сейчас приходит в себя в деревне Звездопада, к западу отсюда. Мне очень любопытно, что же там произошло... а тебе?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джероном Гранильщиком в деревне Звездопада.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (6605,'О, $C. Вижу, еще есть надежда. Ты здесь, чтобы мне помочь?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, $C. Вижу, еще есть надежда. Ты здесь, чтобы мне помочь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6606,'Немного удачи','Немного удачи никому не помешает, так ведь? Иногда даже крошечного преимущества достаточно, чтобы обратить все в свою пользу...$B$BНедавно мне довелось познакомиться с одной довольно эксцентричной особой. Она сделала мне особый талисман на удачу... не бесплатно, разумеется. Но, поверь уж мне, он того стоит!$B$BМожет, тебе тоже такой нужен? Найди знахарку Мау\'ари в Кругозоре. Свой я тебе не отдам!','Поговорите со знахаркой Мау\'ари в Кругозоре.','Тебя Харло прислал? Как я догадываюсь, тебе нужна моя помощь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Немного удачи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Немного удачи никому не помешает, так ведь? Иногда даже крошечного преимущества достаточно, чтобы обратить все в свою пользу...$B$BНедавно мне довелось познакомиться с одной довольно эксцентричной особой. Она сделала мне особый талисман на удачу... не бесплатно, разумеется. Но, поверь уж мне, он того стоит!$B$BМожет, тебе тоже такой нужен? Найди знахарку Мау\'ари в Кругозоре. Свой я тебе не отдам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со знахаркой Мау\'ари в Кругозоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя Харло прислал? Как я догадываюсь, тебе нужна моя помощь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6607,'Нат Пэгл, великий рыболов','Не скажу, что мне так уж нравится рыбачить. Последний раз мне этим приходилось заниматься 20, а то и 30 лет назад. $B$BЛюди занимаются своим делом по разным причинам.$b$bЯ не говорю, что ты $gдолжен:должна; убить на рыбалку 30 лет, или выловить всю рыбу в этом море, чтобы стать хорошим рыбаком. Я думаю, тебе просто надо собраться и решиться несколько часов просиживать зад на берегу, ничего не делая.$b$bВот что я тебе скажу, поймай мне несколько редких рыб из этого списка, и я взамен научу тебя кой-чему.','Поймайте для Ната Пэгла следующих рыб:$bМахи-махи с берега Туманных Тростников на Болоте Печали. $bУдарник Сартериса с побережья Сар\'Терис из Пустошей.$bФераласского тунца из реки Вердантис из Фераласа.$bСиний плавник Гибельного берега из Тернистой долины.$bПо выполнении вернитесь к Нату Пэглу.','Вот это, я понимаю, улов!$B$BПоди сюда, дай-ка я тебе покажу пару трюков.','Ну как, сегодня клев был?','Вернитесь к Нату Пэглу в Лагерь Ната, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нат Пэгл, великий рыболов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не скажу, что мне так уж нравится рыбачить. Последний раз мне этим приходилось заниматься 20, а то и 30 лет назад. $B$BЛюди занимаются своим делом по разным причинам.$b$bЯ не говорю, что ты $gдолжен:должна; убить на рыбалку 30 лет, или выловить всю рыбу в этом море, чтобы стать хорошим рыбаком. Я думаю, тебе просто надо собраться и решиться несколько часов просиживать зад на берегу, ничего не делая.$b$bВот что я тебе скажу, поймай мне несколько редких рыб из этого списка, и я взамен научу тебя кой-чему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте для Ната Пэгла следующих рыб:$bМахи-махи с берега Туманных Тростников на Болоте Печали. $bУдарник Сартериса с побережья Сар\'Терис из Пустошей.$bФераласского тунца из реки Вердантис из Фераласа.$bСиний плавник Гибельного берега из Тернистой долины.$bПо выполнении вернитесь к Нату Пэглу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это, я понимаю, улов!$B$BПоди сюда, дай-ка я тебе покажу пару трюков.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, сегодня клев был?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нату Пэглу в Лагерь Ната, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6608,'Больше учить нечему','Лумак больше не может тебя учить, $n. Нечему больше учить тебя. Найди друга Лумака, Ната Пэгла. Он человек, не еда! Нат друг Лумака! Он тебя научит ловить рыбу лучше.$b$bНата можно найти в Пылевых топях, к югу от Тераморо... как его там. Он, наверное, удит рыбу. Иди!','Похоже, Лумак хочет сказать, что ему больше нечему вас учить. Возможно, стоит найти его друга Ната Пэгла – человека, который удит рыбу на островах к югу от Терамора. Кажется, Лумак имеет в виду именно это.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше учить нечему',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лумак больше не может тебя учить, $n. Нечему больше учить тебя. Найди друга Лумака, Ната Пэгла. Он человек, не еда! Нат друг Лумака! Он тебя научит ловить рыбу лучше.$b$bНата можно найти в Пылевых топях, к югу от Тераморо... как его там. Он, наверное, удит рыбу. Иди!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Похоже, Лумак хочет сказать, что ему больше нечему вас учить. Возможно, стоит найти его друга Ната Пэгла – человека, который удит рыбу на островах к югу от Терамора. Кажется, Лумак имеет в виду именно это.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6609,'С меня больше нечего взять!','Я же дворф, $Gпарень:подруга;, это ж без очков видать! Не мое дело рыбу ловить! Ты только глянь на меня! Я ж, считай, каменный!$B$BС меня больше нечего взять – все тебе отдал! Я тебя научил всему, что умел, балда!$B$BЕще не $Gпонял:поняла;? А, да ладно. Есть у меня старый дружок в Калимдоре, который сможет тебе помочь. Его зовут Нат Пэгл, он хороший парень. Ищи его на островах к югу от Терамора. Ну, топай!','Отправляйтесь в Калимдор, в приморский город Терамор. Там к югу от города найдите остров. Нат Пэгл уже ждет.','У меня на островке всегда найдется место для гостей... Насколько помню...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С меня больше нечего взять!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я же дворф, $Gпарень:подруга;, это ж без очков видать! Не мое дело рыбу ловить! Ты только глянь на меня! Я ж, считай, каменный!$B$BС меня больше нечего взять – все тебе отдал! Я тебя научил всему, что умел, балда!$B$BЕще не $Gпонял:поняла;? А, да ладно. Есть у меня старый дружок в Калимдоре, который сможет тебе помочь. Его зовут Нат Пэгл, он хороший парень. Ищи его на островах к югу от Терамора. Ну, топай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Калимдор, в приморский город Терамор. Там к югу от города найдите остров. Нат Пэгл уже ждет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У меня на островке всегда найдется место для гостей... Насколько помню...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6610,'Мидии с сюрпризом','Тебе случалось слышать о мидиях с сюрпризом? Конечно же нет! Это мой последний кулинарный шедевр. Ах, от одной мысли слюнки текут.$b$bК сожалению, у меня кончились все припасы, и я не могу его сделать! Хочешь сделку? Принеси мне нужные продукты, а я поучу тебя готовить, и даже дам парочку омлетов с мидиями! $gСогласен:Согласна;?$b$BВот что мне нужно:','Могиль Быстроруб поручил принести ему следующее:$b$b10 гигантских яиц. Их можно отыскать у рухов Танариса или других крупных птиц.$b$b10 кусков острого мяса моллюсков. Разумеется, его добывают из раковин моллюсков!$b$b20 кусков старого чеддера. Из сыроварни!$b$BСобрав все составляющие, возвращайтесь к Могилю.','Вернитесь к Могилю Быстрорубу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мидии с сюрпризом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе случалось слышать о мидиях с сюрпризом? Конечно же нет! Это мой последний кулинарный шедевр. Ах, от одной мысли слюнки текут.$b$bК сожалению, у меня кончились все припасы, и я не могу его сделать! Хочешь сделку? Принеси мне нужные продукты, а я поучу тебя готовить, и даже дам парочку омлетов с мидиями! $gСогласен:Согласна;?$b$BВот что мне нужно:',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Могиль Быстроруб поручил принести ему следующее:$b$b10 гигантских яиц. Их можно отыскать у рухов Танариса или других крупных птиц.$b$b10 кусков острого мяса моллюсков. Разумеется, его добывают из раковин моллюсков!$b$b20 кусков старого чеддера. Из сыроварни!$b$BСобрав все составляющие, возвращайтесь к Могилю.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Могилю Быстрорубу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6611,'Ступай в Прибамбасск!','Как может Замджа научить тебя всему на свете? Ты знаешь все кулинарные заговоры Замджи и требуешь новых!$b$bЗамджа ничем помочь не может. Пусть $gтолстый:толстая:r; |3-6($r) пойдет в Прибамбасск. Найдешь там мелкого гоблина по имени Могиль – вот он тебе и поможет, обжора.$b$bКогда станешь великим поваром – вернешься, научишь Замджу всему, что знаешь, а? Ну, ступай, ступай.','Отправляйтесь в Прибамбасск в пустыне Танарис и поговорите с Могилем Быстрорубом.','*Могиль выплевывает ошметки кожаной сандалии.*\n\nОх! Фу! Тьфу!*Могиль долго откашливается.*\n\nВ чем дело? Ты разве не знаешь, что в коже очень много белка и чрезвычайно мало углеводов? Ничего, узнаешь еще!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ступай в Прибамбасск!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как может Замджа научить тебя всему на свете? Ты знаешь все кулинарные заговоры Замджи и требуешь новых!$b$bЗамджа ничем помочь не может. Пусть $gтолстый:толстая:r; |3-6($r) пойдет в Прибамбасск. Найдешь там мелкого гоблина по имени Могиль – вот он тебе и поможет, обжора.$b$bКогда станешь великим поваром – вернешься, научишь Замджу всему, что знаешь, а? Ну, ступай, ступай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Прибамбасск в пустыне Танарис и поговорите с Могилем Быстрорубом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Могиль выплевывает ошметки кожаной сандалии.*\n\nОх! Фу! Тьфу!*Могиль долго откашливается.*\n\nВ чем дело? Ты разве не знаешь, что в коже очень много белка и чрезвычайно мало углеводов? Ничего, узнаешь еще!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (6612,'Я знаю одного парня...','Судя по твоему половнику, ты знаешь, чего хочешь. Да вот научить мне тебя нечему.$B$BНо тебе свезло, я знаю одного парня. Он гоблин, и считается первым поваром Калимдора.$B$BДа, $Gприятель:подруга;, придется тебе податься до Калимдора. Иди-ка в Прибамбасск и сыщи Могиля Быстроруба. Он тебя прямиком и направит.','Могиль выплевывает кожу. $B$BТьфу...$B$B Могиль громко кашляет. $B$BНу? Известно ли тебе, что в коже чрезвычайно много белка и мало углеводов, |3-6($r)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я знаю одного парня...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по твоему половнику, ты знаешь, чего хочешь. Да вот научить мне тебя нечему.$B$BНо тебе свезло, я знаю одного парня. Он гоблин, и считается первым поваром Калимдора.$B$BДа, $Gприятель:подруга;, придется тебе податься до Калимдора. Иди-ка в Прибамбасск и сыщи Могиля Быстроруба. Он тебя прямиком и направит.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Могиль выплевывает кожу. $B$BТьфу...$B$B Могиль громко кашляет. $B$BНу? Известно ли тебе, что в коже чрезвычайно много белка и мало углеводов, |3-6($r)?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6621,'Король Гиблой Чащи','Мои исследования увенчались успехом.$b$bПолагаю, мы сможем урезонить фурболгов, продемонстрировав им нашу силу.$B$BВозьми это знамя и отнеси его на их тотемный курган на северо-востоке. Они попытаются уничтожить его, но ты держись, пока не появится их вождь, Мургут. Он захочет отстоять честь племени. Принеси мне его тотем.$B$BСобирай друзей, $n. С этим делом |3-6($c)-одиночка не справится.','Водрузите знамя Сенани на тотемном кургане Гиблой Чащи. Не дайте фурболгам уничтожить знамя. Одолейте вождя Мургута и принесите тотем Мургута Сенани в приют Серебряного Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Король Гиблой Чащи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои исследования увенчались успехом.$b$bПолагаю, мы сможем урезонить фурболгов, продемонстрировав им нашу силу.$B$BВозьми это знамя и отнеси его на их тотемный курган на северо-востоке. Они попытаются уничтожить его, но ты держись, пока не появится их вождь, Мургут. Он захочет отстоять честь племени. Принеси мне его тотем.$B$BСобирай друзей, $n. С этим делом |3-6($c)-одиночка не справится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Водрузите знамя Сенани на тотемном кургане Гиблой Чащи. Не дайте фурболгам уничтожить знамя. Одолейте вождя Мургута и принесите тотем Мургута Сенани в приют Серебряного Ветра.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (6622,'Очередь на медобслуживание','Добрый день, доктор. Вы должны будете пройти тест на оказание срочной медицинской помощи. Если тест будет пройден успешно, вы вольетесь в ряды наших лучших травматологов.$B$BА теперь внимание! Смертельно раненые должны получить помощь первыми. Потом следует перевязать тяжелораненых. А затем можно заняться и обычными ранеными. Для прохождения теста вам нужно спасти 15 пациентов. Если 6 пациентов умрут, так и не дождавшись перевязки, испытание будет провалено.$B$BДля этого теста вам будут предоставлены специальные бинты.$B$BУдачи, доктор.','Окажите помощь пациентам, используя для перевязки их ран очередные перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран.$B$BПомните о порядке оказания помощи! Смертельно раненые солдаты умирают быстрее, чем тяжелораненые. Обычные раненые живут дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых.','Доктор $N, добро пожаловать в ряды травматологов Орды.','Чудотворная работа, доктор. Просто чудесно.','15 пациентов спасено!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очередь на медобслуживание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добрый день, доктор. Вы должны будете пройти тест на оказание срочной медицинской помощи. Если тест будет пройден успешно, вы вольетесь в ряды наших лучших травматологов.$B$BА теперь внимание! Смертельно раненые должны получить помощь первыми. Потом следует перевязать тяжелораненых. А затем можно заняться и обычными ранеными. Для прохождения теста вам нужно спасти 15 пациентов. Если 6 пациентов умрут, так и не дождавшись перевязки, испытание будет провалено.$B$BДля этого теста вам будут предоставлены специальные бинты.$B$BУдачи, доктор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Окажите помощь пациентам, используя для перевязки их ран очередные перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран.$B$BПомните о порядке оказания помощи! Смертельно раненые солдаты умирают быстрее, чем тяжелораненые. Обычные раненые живут дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Доктор $N, добро пожаловать в ряды травматологов Орды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чудотворная работа, доктор. Просто чудесно.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','15 пациентов спасено!',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (6623,'Травматология Орды','Доктор $n, я так понимаю? Рад новой встрече.$b$bУ меня для тебя замечательные новости. Доктор Грегори Виктор, главный травматолог Орды, предлагает тебе поработать у него в Павшем Молоте. Такой шанс выпадает раз в жизни! Лично я отдал бы все на свете за возможность поработать под руководством великого Грегори Виктора! Не упусти свою удачу!','Отлично. Надевайте халат, работа не ждет!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Травматология Орды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доктор $n, я так понимаю? Рад новой встрече.$b$bУ меня для тебя замечательные новости. Доктор Грегори Виктор, главный травматолог Орды, предлагает тебе поработать у него в Павшем Молоте. Такой шанс выпадает раз в жизни! Лично я отдал бы все на свете за возможность поработать под руководством великого Грегори Виктора! Не упусти свою удачу!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Надевайте халат, работа не ждет!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6624,'Очередь на медобслуживание','Здравствуйте, доктор. Вам сегодня предстоит пройти испытание на очередность оказания помощи раненым. Если вы успешно пройдете этот экзамен, вы будете приняты в ряды престижного сообщества травматологов Альянса.$B$BА теперь слушайте внимательно! Сначала необходимо оказать помощь смертельно раненым. После – тем, у кого тяжелые ранения. Последними идут обычные раненые. Вы должны оказать помощь 15 пациентам, чтобы пройти этот экзамен. Если 6 ваших пациентов после оказания им помощи скончаются, экзамен будет считаться проваленным.$B$BУдачи, доктор.','Окажите помощь пациентам, используя для перевязки их ран перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран.$B$BПомните о порядке оказания помощи! Смертельно раненые солдаты умрут быстрее, чем тяжелораненые. Обычные раненые могут прожить дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых.','Чудотворная работа, доктор. Просто чудесно.','15 пациентов спасено!','Вернитесь к доктору Густаву ван Склиффу на Остров Терамор, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очередь на медобслуживание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуйте, доктор. Вам сегодня предстоит пройти испытание на очередность оказания помощи раненым. Если вы успешно пройдете этот экзамен, вы будете приняты в ряды престижного сообщества травматологов Альянса.$B$BА теперь слушайте внимательно! Сначала необходимо оказать помощь смертельно раненым. После – тем, у кого тяжелые ранения. Последними идут обычные раненые. Вы должны оказать помощь 15 пациентам, чтобы пройти этот экзамен. Если 6 ваших пациентов после оказания им помощи скончаются, экзамен будет считаться проваленным.$B$BУдачи, доктор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Окажите помощь пациентам, используя для перевязки их ран перевязочные бинты. Вы должны оказать помощь 15 пациентам прежде, чем 6 из них успеют умереть от ран.$B$BПомните о порядке оказания помощи! Смертельно раненые солдаты умрут быстрее, чем тяжелораненые. Обычные раненые могут прожить дольше всех, потому им надо оказывать помощь ПОСЛЕ того, как перевяжете тех, кто при смерти, и тяжелораненых.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чудотворная работа, доктор. Просто чудесно.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','15 пациентов спасено!',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к доктору Густаву ван Склиффу на Остров Терамор, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6625,'Травматологи Альянса','Полагаю, вы доктор $n. Приятно познакомиться.$B$BУ меня есть для вас замечательная новость! Густаф ван Склифф, главный врач-травматолог Альянса, делает вам личное предложение приехать к нему в Терамор. Такая возможность выпадает раз в жизни! Я бы все отдала за возможность учиться у великого доктора Густафа ван Склиффа! Не упустите возможности, доктор!','Отправляйтесь в Терамор в Пылевых топях и поговорите с доктором Густавом ван Склиффом насчет зачисления в травматологи Альянса.','Чудесно. Мойте руки, и сразу начнем!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Травматологи Альянса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полагаю, вы доктор $n. Приятно познакомиться.$B$BУ меня есть для вас замечательная новость! Густаф ван Склифф, главный врач-травматолог Альянса, делает вам личное предложение приехать к нему в Терамор. Такая возможность выпадает раз в жизни! Я бы все отдала за возможность учиться у великого доктора Густафа ван Склиффа! Не упустите возможности, доктор!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Терамор в Пылевых топях и поговорите с доктором Густавом ван Склиффом насчет зачисления в травматологи Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чудесно. Мойте руки, и сразу начнем!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6626,'Воинство зла','Отрекшиеся не стремятся превратить смертных в себе подобных... насколько мне известно. Однако этот посланник, видимо, охотно превращает в нежить всех желающих. Я начинаю думать, что на самом деле он работает на Плеть.$B$BОднако сейчас меня больше беспокоит не он, а его последователи, число которых все возрастает. Я вижу,что каждые день из тьмы выползают все новые и новые его приспешники, пресмыкающиеся перед ним в жажде власти.$B$BЯ слишком слаба, чтобы справиться с ними, $n. Помоги мне.','Убейте 8 боевых стражей и 8 терноплетов из племени Иглошкурых, а также 8 сектанток из племени Мертвой Головы и возвращайтесь к Мириам Лунной Певице в Курганы Иглошкурых.','Как охота, $N? Глядя на то, что творит это посланник в наших землях, я перестаю сомневаться, что Плеть представляет самую страшную угрозу нашему миру с самого его сотворения.','Вернитесь к Мириам Лунной Певице в Тысячу Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воинство зла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отрекшиеся не стремятся превратить смертных в себе подобных... насколько мне известно. Однако этот посланник, видимо, охотно превращает в нежить всех желающих. Я начинаю думать, что на самом деле он работает на Плеть.$B$BОднако сейчас меня больше беспокоит не он, а его последователи, число которых все возрастает. Я вижу,что каждые день из тьмы выползают все новые и новые его приспешники, пресмыкающиеся перед ним в жажде власти.$B$BЯ слишком слаба, чтобы справиться с ними, $n. Помоги мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 боевых стражей и 8 терноплетов из племени Иглошкурых, а также 8 сектанток из племени Мертвой Головы и возвращайтесь к Мириам Лунной Певице в Курганы Иглошкурых.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как охота, $N? Глядя на то, что творит это посланник в наших землях, я перестаю сомневаться, что Плеть представляет самую страшную угрозу нашему миру с самого его сотворения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мириам Лунной Певице в Тысячу Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6627,'Испытание знаний','Ты $gпринес:принесла; мне книгу, и я должен задать тебе вопрос. Ты $gготов:готова;?$B$BСпешить нам некуда, так что не торопись. Можешь ответить мне в любое время.','Дайте верный ответ на вопрос Брауга Тусклого Духа и поговорите с ним еще раз. Брауга можно в любое время найти в Когтистых горах.','Отличная работа, |3-6($C). Ты изучил книгу как следует и прошел еще одно наше испытание.','Дайте верный ответ на вопрос Брауга Тусклого Духа.','Вернитесь к Браугу Тусклому Духу в Когтистые горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание знаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпринес:принесла; мне книгу, и я должен задать тебе вопрос. Ты $gготов:готова;?$B$BСпешить нам некуда, так что не торопись. Можешь ответить мне в любое время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дайте верный ответ на вопрос Брауга Тусклого Духа и поговорите с ним еще раз. Брауга можно в любое время найти в Когтистых горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, |3-6($C). Ты изучил книгу как следует и прошел еще одно наше испытание.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Дайте верный ответ на вопрос Брауга Тусклого Духа.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Браугу Тусклому Духу в Когтистые горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6628,'Испытание знаний','Вот мы и встретились снова. Ты $gпроявил:проявила; недюжинные способности при прохождении моих испытаний, и теперь мне осталось только задать тебе последний вопрос.$B$BКогда будешь $gготов:готова;, подойди и поговори со мной, но перед этим как следует подготовься. Спешить нам некуда.','Дайте верный ответ на вопрос Парквела Финталласа и поговорите с ним еще раз. Парквелла можно в любое время найти в Подгороде.','Надеюсь, ты доставил Алому ордену достаточно неприятностей перед тем, как украсть книгу.\n\nМое отношение к ним отнюдь не беспочвенно. Возможно, когда-то его участники и почитали Свет, но теперь они стремятся лишь уничтожить всех, кто не принадлежит к их религии. Они считают, что вся нежить – Отрекшиеся и все остальные – должна быть уничтожена, а тех, кто путешествует в земли нежити, они считают либо безумцами, либо рабами сильной магии. Идиоты. Идиоты и глупцы, все до единого.','Правильно ответьте на вопрос Парквелла Финталласа','Вернитесь к Парквелу Финталласу в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание знаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот мы и встретились снова. Ты $gпроявил:проявила; недюжинные способности при прохождении моих испытаний, и теперь мне осталось только задать тебе последний вопрос.$B$BКогда будешь $gготов:готова;, подойди и поговори со мной, но перед этим как следует подготовься. Спешить нам некуда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дайте верный ответ на вопрос Парквела Финталласа и поговорите с ним еще раз. Парквелла можно в любое время найти в Подгороде.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты доставил Алому ордену достаточно неприятностей перед тем, как украсть книгу.\n\nМое отношение к ним отнюдь не беспочвенно. Возможно, когда-то его участники и почитали Свет, но теперь они стремятся лишь уничтожить всех, кто не принадлежит к их религии. Они считают, что вся нежить – Отрекшиеся и все остальные – должна быть уничтожена, а тех, кто путешествует в земли нежити, они считают либо безумцами, либо рабами сильной магии. Идиоты. Идиоты и глупцы, все до единого.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Правильно ответьте на вопрос Парквелла Финталласа',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Парквелу Финталласу в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6629,'Убить Грундига Темное Облако','Что ж, $n, с негодяями из клана Зловещего Тотема тебе удалось расправиться отлично. Но Грундиг Темное Облако и его личная банда громил куда хуже. Именно он возглавлял то жестокое нападение на мою деревню.$b$bЕсли осмелишься, то найдешь его на Заставе Зловещего Тотема чуть дальше по дороге на запад. Убей его, и я буду вечно тебе признателен.','Убейте Грундига Темное Облако и 6 громил из племени Зловещего Тотема и вернитесь к Макабе Плоскому Копыту, который ждет вблизи юго-восточного края Каменного Когтя.','Вы убили Грундига Темное Облако и его личную группу громил?','Вернитесь к Макабу Плоскому Копыту на границу между Степями и Когтистыми горами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить Грундига Темное Облако',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, $n, с негодяями из клана Зловещего Тотема тебе удалось расправиться отлично. Но Грундиг Темное Облако и его личная банда громил куда хуже. Именно он возглавлял то жестокое нападение на мою деревню.$b$bЕсли осмелишься, то найдешь его на Заставе Зловещего Тотема чуть дальше по дороге на запад. Убей его, и я буду вечно тебе признателен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Грундига Темное Облако и 6 громил из племени Зловещего Тотема и вернитесь к Макабе Плоскому Копыту, который ждет вблизи юго-восточного края Каменного Когтя.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы убили Грундига Темное Облако и его личную группу громил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Макабу Плоскому Копыту на границу между Степями и Когтистыми горами.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6641,'Ворша Хлестунья','Ворша Хлестунья... это омерзительная гидра, что рыщет в морях...$B$BОна нападает на нашу заставу почем зря, уничтожая все на своем пути.$B$BНо я готов драться, $n. Я готов уничтожить гидру и положить конец ее нападениям на Зорам\'гар.$B$BНаги почитают эту гадкую тварь и поддерживают в ее честь пламя на жаровне, что находится на острове у побережья. Думаю, если мы ее загасим, то разъяренная Ворша вылезет из моря.$B$BНам понадобится помощь, так что приведи крепких друзей.','Победите Воршу Хлестунью.','Победите Воршу Хлестунью.','Поговорите с гонцом клана Песни Войны на заставе Зорам\'гар') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ворша Хлестунья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ворша Хлестунья... это омерзительная гидра, что рыщет в морях...$B$BОна нападает на нашу заставу почем зря, уничтожая все на своем пути.$B$BНо я готов драться, $n. Я готов уничтожить гидру и положить конец ее нападениям на Зорам\'гар.$B$BНаги почитают эту гадкую тварь и поддерживают в ее честь пламя на жаровне, что находится на острове у побережья. Думаю, если мы ее загасим, то разъяренная Ворша вылезет из моря.$B$BНам понадобится помощь, так что приведи крепких друзей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Воршу Хлестунью.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победите Воршу Хлестунью.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с гонцом клана Песни Войны на заставе Зорам\'гар',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6642,'Покровительство братства, черное железо','Хотя черное железо в изобилии водится в Глубинах, оно высоко ценится в братстве. Священное оружие Рагнароса куется именно из него.$B$BЗа каждые 10 кусков руды черного железа, которые ты пожертвуешь братству, наградой тебе будет наше доброе отношение.','Вернитесь к Локтосу Зловещему Торговцу в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покровительство братства, черное железо',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хотя черное железо в изобилии водится в Глубинах, оно высоко ценится в братстве. Священное оружие Рагнароса куется именно из него.$B$BЗа каждые 10 кусков руды черного железа, которые ты пожертвуешь братству, наградой тебе будет наше доброе отношение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Локтосу Зловещему Торговцу в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6643,'Покровительство братства, огненное ядро','Горе тем, кто искушает судьбу и безоглядно бросается в Огненные Недра. Кара за дерзость – мгновенная смерть, каковая не ведает жалости.$B$BМногие братья расстались с жизнью, отправившись на поиски огненных ядер.$B$BПожертвуй братству огненное ядро, и можешь рассчитывать на наше доброе отношение.','Вернитесь к Локтосу Зловещему Торговцу в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покровительство братства, огненное ядро',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Горе тем, кто искушает судьбу и безоглядно бросается в Огненные Недра. Кара за дерзость – мгновенная смерть, каковая не ведает жалости.$B$BМногие братья расстались с жизнью, отправившись на поиски огненных ядер.$B$BПожертвуй братству огненное ядро, и можешь рассчитывать на наше доброе отношение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Локтосу Зловещему Торговцу в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6644,'Покровительство братства, ядро лавы','Братство Тория помогает только тем, кто заслужил нашу дружбу и уважение, $R. Собственно поэтому Локтоса и уполномочили заключить с тобой договор.$B$BПожертвуй братству ядро лавы, и можешь рассчитывать на нашу помощь.','Вернитесь к Локтосу Зловещему Торговцу в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покровительство братства, ядро лавы',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Братство Тория помогает только тем, кто заслужил нашу дружбу и уважение, $R. Собственно поэтому Локтоса и уполномочили заключить с тобой договор.$B$BПожертвуй братству ядро лавы, и можешь рассчитывать на нашу помощь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Локтосу Зловещему Торговцу в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6645,'Покровительство братства, кожа Недр','Во многих священных рецептурах упоминаются шкуры питомцев Рагнароса.$B$BПожертвуй братству два куска кожи Недр, снятой с гончих из Огненных Недр, – и заслужишь добрую славу.','Вернитесь к Локтосу Зловещему Торговцу в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покровительство братства, кожа Недр',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Во многих священных рецептурах упоминаются шкуры питомцев Рагнароса.$B$BПожертвуй братству два куска кожи Недр, снятой с гончих из Огненных Недр, – и заслужишь добрую славу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Локтосу Зловещему Торговцу в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6646,'Покровительство братства, кровь горы','Твой дар приняли и оценили. Ты $Gзаслужил:заслужила; добрую славу. Если братство удостоверится в твоей преданности, тебе дадут доступ к тайнам древних ремесел.','Слезы Повелителя огня – поистине великая редкость.$B$BПожертвуй братству кровь горы, и можешь рассчитывать на наше доброе отношение.','Вернитесь к Локтосу Зловещему Торговцу в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покровительство братства, кровь горы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твой дар приняли и оценили. Ты $Gзаслужил:заслужила; добрую славу. Если братство удостоверится в твоей преданности, тебе дадут доступ к тайнам древних ремесел.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Слезы Повелителя огня – поистине великая редкость.$B$BПожертвуй братству кровь горы, и можешь рассчитывать на наше доброе отношение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Локтосу Зловещему Торговцу в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6661,'Охота на крыс','Поймайте 5 подземных крыс, используя Флейту крысолова, и принесите их Монти.','Ха, хорошо сделанная работенка, молодец! Моему братцу они нужны свеженькими, чтобы приготовить из них котлеты.','Аррр... Мы еще долго будем ждать?','Вернитесь к Монти в подземный поезд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на крыс',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 5 подземных крыс, используя Флейту крысолова, и принесите их Монти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха, хорошо сделанная работенка, молодец! Моему братцу они нужны свеженькими, чтобы приготовить из них котлеты.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Аррр... Мы еще долго будем ждать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Монти в подземный поезд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (6662,'Братишка Нипси','Отвезите Нипси в подземное депо Штормграда коробку загадочного мяса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братишка Нипси',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отвезите Нипси в подземное депо Штормграда коробку загадочного мяса.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6681,'Поместье, Черный Ворон','$n,$B$BЧерный Ворон очень заинтересовался тобой, $gюный вор:юная воришка;. Мы наблюдали. Тебе не хватает ловкости, но это преходяще.$b$bЕсли ты хочешь стать $gучеником:ученицей; мастера Черного Ворона и членом Лиги убийц, стоит только принести печать Черного Ворона (приложенную к этому письму) в поместье Черный Ворон.$b$bПервым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость.$b$bС уважением,$b$bФарад.','Отнесите печать Черного Ворона Фараду в поместье Черный Ворон, сокрытое среди холмов Хилсбрада.$b$bНе теряйте бдительности. Поиски поместья – проверка на ловкость.','Прекрасно сделано, $Gюный:юная; $Gвор:воришка;.$B$BТебя, знаешь ли, ждет длинное путешествие. Длинное и выгодное. $GГотов:Готова; ли ты принять свою судьбу из рук мастеров Черного Ворона?$B$BПоговори со стражниками снаружи. Они подскажут тебе что делать.','Ты знаешь Милтона?$B$B<Фахрад смеется.>','Вернитесь к Фараду в Поместье Черного Ворона, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поместье, Черный Ворон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n,$B$BЧерный Ворон очень заинтересовался тобой, $gюный вор:юная воришка;. Мы наблюдали. Тебе не хватает ловкости, но это преходяще.$b$bЕсли ты хочешь стать $gучеником:ученицей; мастера Черного Ворона и членом Лиги убийц, стоит только принести печать Черного Ворона (приложенную к этому письму) в поместье Черный Ворон.$b$bПервым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость.$b$bС уважением,$b$bФарад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите печать Черного Ворона Фараду в поместье Черный Ворон, сокрытое среди холмов Хилсбрада.$b$bНе теряйте бдительности. Поиски поместья – проверка на ловкость.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно сделано, $Gюный:юная; $Gвор:воришка;.$B$BТебя, знаешь ли, ждет длинное путешествие. Длинное и выгодное. $GГотов:Готова; ли ты принять свою судьбу из рук мастеров Черного Ворона?$B$BПоговори со стражниками снаружи. Они подскажут тебе что делать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты знаешь Милтона?$B$B<Фахрад смеется.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фараду в Поместье Черного Ворона, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6701,'Эмблемы Синдиката','Эй, хорошая работа! Продолжайте в том же духе, и другие мошенники могут перестать плевать на вас.','Мы были в битве с Синдикатом в течение многих лет. То, что им не хватает навыков, они восполняют в цифрах. Невозможно убить их достаточно быстро, чтобы оказать какое-либо заметное влияние на их население!$B$BМы обнаружили, что лучший способ справиться с их размером - украсть их эмблемы. Как только эмблема украдена, с позорным участником «разбираются» внутри.$B$BОбчисти их карманы и отдай эмблемы мне или одному из других охранников.$B$BНачните в крепости Дарнхольд, к югу отсюда.','Разыщите стражника поместья в Поместье Черного Ворона, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эмблемы Синдиката',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эй, хорошая работа! Продолжайте в том же духе, и другие мошенники могут перестать плевать на вас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы были в битве с Синдикатом в течение многих лет. То, что им не хватает навыков, они восполняют в цифрах. Невозможно убить их достаточно быстро, чтобы оказать какое-либо заметное влияние на их население!$B$BМы обнаружили, что лучший способ справиться с их размером - украсть их эмблемы. Как только эмблема украдена, с позорным участником «разбираются» внутри.$B$BОбчисти их карманы и отдай эмблемы мне или одному из других охранников.$B$BНачните в крепости Дарнхольд, к югу отсюда.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите стражника поместья в Поместье Черного Ворона, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
