INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6721,'Путь охотника','Привет тебе, $Gюный охотник:юная охотница;. Ты кажешься мне достаточно $Gопытным:опытной;, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.','Поговорите с Дазаларом в Доланааре, что в Тельдрассиле.','Да, пора, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $Gюный охотник:юная охотница;. Ты кажешься мне достаточно $Gопытным:опытной;, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дазаларом в Доланааре, что в Тельдрассиле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, пора, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6722,'Путь охотника','Привет тебе, $Gюный охотник:юная охотница;. Ты кажешься мне достаточно $Gопытным:опытной;, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.','Поговорите с Дазаларом в Доланааре, что в Тельдрассиле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, $Gюный охотник:юная охотница;. Ты кажешься мне достаточно $Gопытным:опытной;, чтобы научиться обращаться с животным и обрести верного друга.$B$BТебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дазаларом в Доланааре, что в Тельдрассиле.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6741,'Больше добычи!','Мне нужно больше обломков брони, $N! У тебя есть еще?','Вернитесь к кузнецу Регзару в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше добычи!',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно больше обломков брони, $N! У тебя есть еще?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кузнецу Регзару в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6761,'Новое пограничье','Я поручил своему заместителю, Матренгилу Медвежьей Лапе, разобраться с призывом о помощи из Лунной поляны. Так что по этому поводу говори с ним – НЕ со мной!$B$BИ позволь мне дать тебе один дружеский совет. Это я вывел нас всех из тьмы – я, а вовсе не Круг Кенария Лунной поляны, – когда наша раса потеряла все. Тельдрассил дает нам новую жизнь! Они наверняка попытаются внушить тебе совсем другое, но только глупец поверит их пропаганде!$B$BТы же, вроде, не из таких. Или я ошибаюсь?','Поговорите с Матренгилом Медвежьей Лапой в Анклаве Кенария в Дарнасе.','Да, |3-6($C), спасибо, что пришел. Прошу прощения за это недоразумение... но взаимное недоверие между здешним верховным друидом и хранителем Ремулом из Лунной поляны прямо-таки дрожит в воздухе. Каждый подозревает другого в кляузничестве, а ведь проблема странной порчи Тельдрассила все еще не решена. Но взаимное недоверие от этого не стихает.$B$BКак бы то ни было, у нас есть долг перед Кругом Кенария... даже если его предводители не ладят друг с другом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое пограничье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я поручил своему заместителю, Матренгилу Медвежьей Лапе, разобраться с призывом о помощи из Лунной поляны. Так что по этому поводу говори с ним – НЕ со мной!$B$BИ позволь мне дать тебе один дружеский совет. Это я вывел нас всех из тьмы – я, а вовсе не Круг Кенария Лунной поляны, – когда наша раса потеряла все. Тельдрассил дает нам новую жизнь! Они наверняка попытаются внушить тебе совсем другое, но только глупец поверит их пропаганде!$B$BТы же, вроде, не из таких. Или я ошибаюсь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Матренгилом Медвежьей Лапой в Анклаве Кенария в Дарнасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, |3-6($C), спасибо, что пришел. Прошу прощения за это недоразумение... но взаимное недоверие между здешним верховным друидом и хранителем Ремулом из Лунной поляны прямо-таки дрожит в воздухе. Каждый подозревает другого в кляузничестве, а ведь проблема странной порчи Тельдрассила все еще не решена. Но взаимное недоверие от этого не стихает.$B$BКак бы то ни было, у нас есть долг перед Кругом Кенария... даже если его предводители не ладят друг с другом.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6762,'Рабин Сатурна','Мажордом хранителя Лунной поляны Ремула – Рабин Сатурна – ищет помощи. Нужно обследовать обширные пустоши к западу от Танариса... и еще дальше, к западу от Ун\'Горо. Найди его в Ночной гавани, главном поселении Лунной поляны.$B$BПоскольку твои труды будут на благо всем нам, советую тебе вести себя осторожно. Между Дарнасом и Лунной поляной трения... и как бы они не переросли со временем в нечто большее.','Поговорите с Рабином Сатурной в селении Ночная гавань в Лунной поляне. Лунная поляна находится между Оскверненным лесом и Зимними Ключами, туда можно добраться по дороге, идущей от Крепости Древобрюхов.','Я Рабин Сатурна. От лица хранителя Ремула и всех обитателей сего священного места приветствую тебя.\n\nЯ ценю твою заинтересованность и горячую готовность помочь Кругу Кенария. Также мне ведомо о недовольстве, с которым верховный друид Дарнасса отозвался о твоей помощи нам. Будь уверен, что все, что делается, – делается во благо, и что тебя не коснутся необдуманные выпады, целью коих ты можешь стать.\n\nЗдесь ты среди друзей, $n.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рабин Сатурна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мажордом хранителя Лунной поляны Ремула – Рабин Сатурна – ищет помощи. Нужно обследовать обширные пустоши к западу от Танариса... и еще дальше, к западу от Ун\'Горо. Найди его в Ночной гавани, главном поселении Лунной поляны.$B$BПоскольку твои труды будут на благо всем нам, советую тебе вести себя осторожно. Между Дарнасом и Лунной поляной трения... и как бы они не переросли со временем в нечто большее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рабином Сатурной в селении Ночная гавань в Лунной поляне. Лунная поляна находится между Оскверненным лесом и Зимними Ключами, туда можно добраться по дороге, идущей от Крепости Древобрюхов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я Рабин Сатурна. От лица хранителя Ремула и всех обитателей сего священного места приветствую тебя.\n\nЯ ценю твою заинтересованность и горячую готовность помочь Кругу Кенария. Также мне ведомо о недовольстве, с которым верховный друид Дарнасса отозвался о твоей помощи нам. Будь уверен, что все, что делается, – делается во благо, и что тебя не коснутся необдуманные выпады, целью коих ты можешь стать.\n\nЗдесь ты среди друзей, $n.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6781,'Больше обломков брони','Это неплохие образчики, $N. Я могу перековать их на новую экипировку для наших воинов.$B$BЕсли припасов у меня окажется достаточно, может, наши опытные воины смогут выйти на поле боя!','$N, нам нужно больше обломков брони для поставки в наши войска!','Вернитесь к Мурготу Подземной Кузне в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше обломков брони',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это неплохие образчики, $N. Я могу перековать их на новую экипировку для наших воинов.$B$BЕсли припасов у меня окажется достаточно, может, наши опытные воины смогут выйти на поле боя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, нам нужно больше обломков брони для поставки в наши войска!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мурготу Подземной Кузне в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6801,'Локолар Владыка Льда','Мы пролили достаточно вражеской крови. Я смешаю эту кровь с остальной... И как только жертва будет принесена, Владыка Льда покажет этим псам Грозовой Вершины всю силу ярости Северных Волков!','Я из Громового Утеса, $R. Кэрн лично велел мне помочь клану Северных Волков в эти суровые времена.$B$BНо не будем тратить время! Убивайте наших врагов и несите мне их кровь. Как только наберется достаточно крови, можно будет начать ритуал призыва.$B$BКогда могучий элементаль обрушится на армию Грозовой Вершины, победа будет наша!','Вернитесь к шаманке стихий Турлога в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Локолар Владыка Льда',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы пролили достаточно вражеской крови. Я смешаю эту кровь с остальной... И как только жертва будет принесена, Владыка Льда покажет этим псам Грозовой Вершины всю силу ярости Северных Волков!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я из Громового Утеса, $R. Кэрн лично велел мне помочь клану Северных Волков в эти суровые времена.$B$BНо не будем тратить время! Убивайте наших врагов и несите мне их кровь. Как только наберется достаточно крови, можно будет начать ритуал призыва.$B$BКогда могучий элементаль обрушится на армию Грозовой Вершины, победа будет наша!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шаманке стихий Турлога в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6804,'Отравленная вода','Мы отправили отряд элементалей воды на разведку в восточные пределы Лордерона, пораженные чумой нежити. Теперь наши разведчики поражены скверной. Повелители Вод не могут допустить, чтобы проклятая чума угрожала нашему народу!$B$BВозьми этот фиал. В нем заключен один из аспектов Нептулона. Он исцелит пораженных скверной элементалей, уничтожив проникшую в их тела заразу. Однако этот процесс столь болезнен, что некоторые из них могут стать нестабильными.$B$BТебе придется убить колыхающихся волноплесков. Принеси мне их браслеты.','Исцелите отравленных элементалей в Восточных Чумных землях с помощью аспекта Нептулона. Принесите 12 браслетов колыхающихся волноплесков и аспект Нептулона герцогу Гидраксису в Азшару.','Хорошо сработано, $C. Эти больные элементами которых ты $Gочистил:очистила;, были оскорблением всем силам воды. Наша сила в нашей чистоте и если мы хотим выиграть нашу войну, то должны оставаться сильными.','$Gпринес:принесла; браслеты?','Вернитесь к герцогу Гидраксису на Залив Бурь, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отравленная вода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы отправили отряд элементалей воды на разведку в восточные пределы Лордерона, пораженные чумой нежити. Теперь наши разведчики поражены скверной. Повелители Вод не могут допустить, чтобы проклятая чума угрожала нашему народу!$B$BВозьми этот фиал. В нем заключен один из аспектов Нептулона. Он исцелит пораженных скверной элементалей, уничтожив проникшую в их тела заразу. Однако этот процесс столь болезнен, что некоторые из них могут стать нестабильными.$B$BТебе придется убить колыхающихся волноплесков. Принеси мне их браслеты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исцелите отравленных элементалей в Восточных Чумных землях с помощью аспекта Нептулона. Принесите 12 браслетов колыхающихся волноплесков и аспект Нептулона герцогу Гидраксису в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо сработано, $C. Эти больные элементами которых ты $Gочистил:очистила;, были оскорблением всем силам воды. Наша сила в нашей чистоте и если мы хотим выиграть нашу войну, то должны оставаться сильными.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$Gпринес:принесла; браслеты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к герцогу Гидраксису на Залив Бурь, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6805,'Буря в пустыне','Мы, элементали воды, противостоим существам низших стихий. Если и в самом деле хочешь быть $gнашим союзником:нашей союзницей;, докажи это!$B$BДалеко на юге, в пустынных землях Силитуса, в скалистом уголке, именуемом долиной Кристаллов, кишат слуги воздуха и земли. Они защищают сокрытые там предметы силы от примитивных существ, смертных. Мне нет никакого дела до того, что они там стерегут, я хочу, чтобы ты $gперебил:перебила; их.$B$BОтправляйся в Долину Кристаллов в Силитус и уничтожь наших врагов.','Убейте 15 вихрей пыли и 15 пустынных грохотунов и возвращайтесь к герцогу Гидраксису в Азшару.','Твоя храбрость доказана. Возможно, у меня будут еще задания для тебя.','Трусость – это то, чему нет прощения, $C. Отправляйся в Силитус и докажи свою доблесть.','Вернитесь к герцогу Гидраксису на Залив Бурь, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Буря в пустыне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы, элементали воды, противостоим существам низших стихий. Если и в самом деле хочешь быть $gнашим союзником:нашей союзницей;, докажи это!$B$BДалеко на юге, в пустынных землях Силитуса, в скалистом уголке, именуемом долиной Кристаллов, кишат слуги воздуха и земли. Они защищают сокрытые там предметы силы от примитивных существ, смертных. Мне нет никакого дела до того, что они там стерегут, я хочу, чтобы ты $gперебил:перебила; их.$B$BОтправляйся в Долину Кристаллов в Силитус и уничтожь наших врагов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 вихрей пыли и 15 пустынных грохотунов и возвращайтесь к герцогу Гидраксису в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя храбрость доказана. Возможно, у меня будут еще задания для тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Трусость – это то, чему нет прощения, $C. Отправляйся в Силитус и докажи свою доблесть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к герцогу Гидраксису на Залив Бурь, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6821,'Око Углевзора','Ты $gдоказал:доказала; мне, что $gспособен:способна; доблестно противостоять врагам и верно служить Повелителям Вод. Однако пока тебе приходилось выходить на бой с довольно слабыми противниками. Сможешь ди ты сразить более могущественного врага.$B$BСлушай мое повеление.$B$BНа вершине Пика Черной горы орки изловили слугу огня, Пиростража Углевзора. Найди место, где они его держат, и перебей и стражу и пленника. Принеси мне его глаз – докажи свою преданность.','Принесите око Углевзора герцогу Гидраксису в Азшару.','Да, у тебя есть сила. И ты хорошо $Gпоработал:поработала; на Пике Черной горы. Ты действительно становишься ценным союзником для нас, $N...','Ты $Gпринес:принесла; мне око, $C? Или у тебя не хватило духу и близко подойти к Пику Черной горы.','Вернитесь к герцогу Гидраксису на Залив Бурь, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око Углевзора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдоказал:доказала; мне, что $gспособен:способна; доблестно противостоять врагам и верно служить Повелителям Вод. Однако пока тебе приходилось выходить на бой с довольно слабыми противниками. Сможешь ди ты сразить более могущественного врага.$B$BСлушай мое повеление.$B$BНа вершине Пика Черной горы орки изловили слугу огня, Пиростража Углевзора. Найди место, где они его держат, и перебей и стражу и пленника. Принеси мне его глаз – докажи свою преданность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите око Углевзора герцогу Гидраксису в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, у тебя есть сила. И ты хорошо $Gпоработал:поработала; на Пике Черной горы. Ты действительно становишься ценным союзником для нас, $N...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне око, $C? Или у тебя не хватило духу и близко подойти к Пику Черной горы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к герцогу Гидраксису на Залив Бурь, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6822,'Огненные Недра','Пришло время испытать твои силы всерьез, $n. Ты $gготов:готова;?$B$BНа самом дне Глубин Черной горы скрывается путь к Огненным Недрам. Это оплот нашего врага, охраняемый самыми мощными служителями огня в нашем мире.$B$BОтправляйся в Огненные Недра, $n. Докажи мне, что у тебя хватит сил справиться с тем, что скрывается там.$B$BЕсли у тебя есть союзники, бери их с собой. Не стоит отправляться в Огненные Недра в одиночку.','Убейте 1 Повелителя огня, 1 лавового великана, 1 древнюю гончую Недр и 1 лавового волноплеска и возвращайтесь к герцогу Гидраксису в Азшару.','Тебе под силу подвиги, которые большинству кажутся невозможными. Ты вступил в схватку с тварями Огненных Недр и вышел из нее победителем. \n\nТы силен для столь маленького создания. \n\nВозможно, однажды Повелители Вод заключат союз с твоим племенем.','Тебя ждет успех в Огненных Недрах, $N.','Вернитесь к герцогу Гидраксису на Залив Бурь, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огненные Недра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время испытать твои силы всерьез, $n. Ты $gготов:готова;?$B$BНа самом дне Глубин Черной горы скрывается путь к Огненным Недрам. Это оплот нашего врага, охраняемый самыми мощными служителями огня в нашем мире.$B$BОтправляйся в Огненные Недра, $n. Докажи мне, что у тебя хватит сил справиться с тем, что скрывается там.$B$BЕсли у тебя есть союзники, бери их с собой. Не стоит отправляться в Огненные Недра в одиночку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 1 Повелителя огня, 1 лавового великана, 1 древнюю гончую Недр и 1 лавового волноплеска и возвращайтесь к герцогу Гидраксису в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе под силу подвиги, которые большинству кажутся невозможными. Ты вступил в схватку с тварями Огненных Недр и вышел из нее победителем. \n\nТы силен для столь маленького создания. \n\nВозможно, однажды Повелители Вод заключат союз с твоим племенем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебя ждет успех в Огненных Недрах, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к герцогу Гидраксису на Залив Бурь, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6823,'Агент Гидраксиса','Если в самом деле хочешь быть $gнашим союзником:нашей союзницей;, докажи серьезность своих намерений в боях против наших врагов – слуг воздуха, земли и огня. Каждое нанесенное им поражение подорвет их позиции в этих землях и послужит доказательством твоей приверженности благу нашего народа.','Добейтесь уважительного отношеия к себе со стороны Гидраксианских Повелителей Вод, затем отправляйтесь к герцогу Гидраксису в Азшару.','Молва о твоих необыкновенных успехах в борьбе против наших врагов облетела всех Повелителей Вод. Некоторые из нас считали, что твое тело слишком маленькое и хрупкое, чтобы ты $Gмог:могла; биться в наших рядах, однако теперь никто не сомневается в твоей силе. Ты $Gзавоевал:завоевала; наше уважение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Агент Гидраксиса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если в самом деле хочешь быть $gнашим союзником:нашей союзницей;, докажи серьезность своих намерений в боях против наших врагов – слуг воздуха, земли и огня. Каждое нанесенное им поражение подорвет их позиции в этих землях и послужит доказательством твоей приверженности благу нашего народа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добейтесь уважительного отношеия к себе со стороны Гидраксианских Повелителей Вод, затем отправляйтесь к герцогу Гидраксису в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молва о твоих необыкновенных успехах в борьбе против наших врагов облетела всех Повелителей Вод. Некоторые из нас считали, что твое тело слишком маленькое и хрупкое, чтобы ты $Gмог:могла; биться в наших рядах, однако теперь никто не сомневается в твоей силе. Ты $Gзавоевал:завоевала; наше уважение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6824,'Руки врага','$n, твоя помощь для нас неоценима, и мы с неохотой отправляем тебя на последнее задание – мы не хотим терять столь полезного союзника, однако работа есть работа.$B$BИмей в виду, если ты успешно выполнишь поставленную перед тобой задачу, это весьма существенно приблизит час нашей победы.$B$BМы хотим, чтобы ты $gуничтожил:уничтожила; нескольких капитанов в Огненных Недрах: Люцифрона, Сульфурона, Гееннаса и Шаззраха. Убей их и принеси их отрубленные руки.$B$BЭто потребует от тебя всех сил, но если ты преуспеешь, Повелителям Огня будет нанесен ужасный удар.','Принесите руки Люцифрона, Сульфурона, Гееннаса и Шаззраха герцогу Гидраксису в Азшару.','Ты $Gпринес:принесла; руки! Значит ты $Gпобедил:победила; огненных капитанов!$B$B$N, слово о твоих подвигах полетит по волнам и достигнет Повелителей Вод. Твое имя станет легендой для нас.$B$BПоговори со мной еще раз, $N. У меня есть для тебя еще одна задача...','Тебе удалось разбить капитанов Недр, $N? Ты $Gпринес:принесла; мне их руки.','Вернитесь к герцогу Гидраксису на Залив Бурь, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руки врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, твоя помощь для нас неоценима, и мы с неохотой отправляем тебя на последнее задание – мы не хотим терять столь полезного союзника, однако работа есть работа.$B$BИмей в виду, если ты успешно выполнишь поставленную перед тобой задачу, это весьма существенно приблизит час нашей победы.$B$BМы хотим, чтобы ты $gуничтожил:уничтожила; нескольких капитанов в Огненных Недрах: Люцифрона, Сульфурона, Гееннаса и Шаззраха. Убей их и принеси их отрубленные руки.$B$BЭто потребует от тебя всех сил, но если ты преуспеешь, Повелителям Огня будет нанесен ужасный удар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите руки Люцифрона, Сульфурона, Гееннаса и Шаззраха герцогу Гидраксису в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпринес:принесла; руки! Значит ты $Gпобедил:победила; огненных капитанов!$B$B$N, слово о твоих подвигах полетит по волнам и достигнет Повелителей Вод. Твое имя станет легендой для нас.$B$BПоговори со мной еще раз, $N. У меня есть для тебя еще одна задача...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось разбить капитанов Недр, $N? Ты $Gпринес:принесла; мне их руки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к герцогу Гидраксису на Залив Бурь, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6825,'Небо зовет – флот Смуггла','Флот питается плотью своих врагов.$B$BСкоро мы двинемся в бой!','Нужно подготовить новый флот боевых виверн, $R! Чтобы мои виверны могли нанести в битве решающий удар, они должны быть сытыми.$B$BИм нужна плоть солдат Грозовой Вершины! Сотни фунтов мяса! Уверен, ты справишься с этим заданием. $GПонял:Поняла;? Ступай!','Вернитесь к командиру звена Смуггл в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небо зовет – флот Смуггла',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Флот питается плотью своих врагов.$B$BСкоро мы двинемся в бой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нужно подготовить новый флот боевых виверн, $R! Чтобы мои виверны могли нанести в битве решающий удар, они должны быть сытыми.$B$BИм нужна плоть солдат Грозовой Вершины! Сотни фунтов мяса! Уверен, ты справишься с этим заданием. $GПонял:Поняла;? Ступай!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру звена Смуггл в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6826,'Небо зовет – флот Мааши','Больше! Больше! Принеси больше!','Ты отлично $Gпоработал:поработала;, $N, но это только начало.$B$BМои боевые виверны должны наесться вдоволь. Тогда мы сможет сокрушить врага с неумолимой точностью!$B$BМой флот – второй по силе в воздушных войсках. А значит, они должны сражаться с самыми грозными противниками! Моим боевым вивернам нужно мясо лейтенантов Грозовой Вершины.$B$BИ поторопись, солдат!','Вернитесь к командиру звена Мааше в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небо зовет – флот Мааши',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Больше! Больше! Принеси больше!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты отлично $Gпоработал:поработала;, $N, но это только начало.$B$BМои боевые виверны должны наесться вдоволь. Тогда мы сможет сокрушить врага с неумолимой точностью!$B$BМой флот – второй по силе в воздушных войсках. А значит, они должны сражаться с самыми грозными противниками! Моим боевым вивернам нужно мясо лейтенантов Грозовой Вершины.$B$BИ поторопись, солдат!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру звена Мааше в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6827,'Небо зовет – флот Маэстра','Не достаточно! Давай солдат, принеси нам больше плоти!','Я провел в этой проклятой дворфийской дыре долгие дни. Можешь поверить, я жажду мести!$B$BМы должны все четко спланировать.$B$BМоим боевым вивернам нужна особая цель! Я собираюсь накормить их мясом командиров Грозовой Вершины. К сожалению, эти трусы глубоко окопались в своих укреплениях. Ничего – я уверен, ты справишься с этой задачей!','Вернитесь к командиру звена Маэстру в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небо зовет – флот Маэстра',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не достаточно! Давай солдат, принеси нам больше плоти!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я провел в этой проклятой дворфийской дыре долгие дни. Можешь поверить, я жажду мести!$B$BМы должны все четко спланировать.$B$BМоим боевым вивернам нужна особая цель! Я собираюсь накормить их мясом командиров Грозовой Вершины. К сожалению, эти трусы глубоко окопались в своих укреплениях. Ничего – я уверен, ты справишься с этой задачей!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру звена Маэстру в Альтеракскую долину.',`completedtext_loc8`);
