INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (6843,'Штуковина') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Штуковина',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (6844,'Умбер, архивариус','Здесь полно работы, но мне кажется, главное – отнести это в Круг, на анализ. Поверь мне, дела здесь не переводятся. Если внутри этого хитина находится дневник, то Круг сможет заглянуть в прошлое!$b$BОтнеси этот дневник архивариусу Круга в Ночную Гавань. Его зовут Умбер, он настоящий гений! Да, тронутый, не без того, но все равно гений! Умбер находил манускрипты в куда более плохом состоянии. Если эти записи можно восстановить, он это сделает.','Отнесите покрытый коркой щит силитида Умберу – архивариусу Круга Кенария – в деревню Ночная Гавань, что в Лунной поляне.','Ага, что тут у нас? Книга, слегка поштопанная…$B$BЛайо послал тебя ко мне из Силитуса? Я слышал про этих жуков только несколько слушков, довольно ужасных, как я тебе замечу... Так что я с удовольствием изучу сию книгу, чтобы узнать из нее, как нам избавиться от этой напасти.','Эй, привет! Хмм...$B$BНе скрою, друг мой... Пахнешь ты неважно. Можно сказать, воняешь. Нет-нет, ничего личного. Всего лишь маленький совет... В будущем, вернувшись из боя, освежись немного. Первое впечатление – это очень важно!$B$BВпрочем... Чем могу служить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Умбер, архивариус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь полно работы, но мне кажется, главное – отнести это в Круг, на анализ. Поверь мне, дела здесь не переводятся. Если внутри этого хитина находится дневник, то Круг сможет заглянуть в прошлое!$b$BОтнеси этот дневник архивариусу Круга в Ночную Гавань. Его зовут Умбер, он настоящий гений! Да, тронутый, не без того, но все равно гений! Умбер находил манускрипты в куда более плохом состоянии. Если эти записи можно восстановить, он это сделает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите покрытый коркой щит силитида Умберу – архивариусу Круга Кенария – в деревню Ночная Гавань, что в Лунной поляне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, что тут у нас? Книга, слегка поштопанная…$B$BЛайо послал тебя ко мне из Силитуса? Я слышал про этих жуков только несколько слушков, довольно ужасных, как я тебе замечу... Так что я с удовольствием изучу сию книгу, чтобы узнать из нее, как нам избавиться от этой напасти.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эй, привет! Хмм...$B$BНе скрою, друг мой... Пахнешь ты неважно. Можно сказать, воняешь. Нет-нет, ничего личного. Всего лишь маленький совет... В будущем, вернувшись из боя, освежись немного. Первое впечатление – это очень важно!$B$BВпрочем... Чем могу служить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6845,'Раскрытие древних секретов','Короче, свяжись со мной как можно скорее... если, конечно, хочешь знать, что там внутри. Как только я это узнаю, с удовольствием поделюсь с тобой информацией – разумеется, если там действительно окажется книга.$B$BА пока я свяжусь с самой-большой-медведицей этого медвежьего угла, то есть Рабином. Он, несомненно, пожелает узнать, что за кашу ты тут $Gзаварил:заварила;. Никогда не заставляй мать-медведицу ждать, $n... ну, если только тебе неймется искупаться в меду.$B$BТакое бывает, уж поверь мне.','Поговорите с Рабином Сатурной в деревне Ночная Гавань в Лунной поляне.','А, $N. Как мило, что ты $Gсогласился:согласилась; меня навестить. Рад видеть тебя в добром здравии.$B$BЯ желаю через тебя выразить глубокую благодарность Кругу Кенария за их помощь, оказанную нам. Тут много секретов ожидают пытливых умов исследователей и тайны ждут, чтобы их раскрыли. Возьми это, как аванс за твои будущие достижения.$B$BБлагодярю тебя, $Gблагородный:благородная; $C.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раскрытие древних секретов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Короче, свяжись со мной как можно скорее... если, конечно, хочешь знать, что там внутри. Как только я это узнаю, с удовольствием поделюсь с тобой информацией – разумеется, если там действительно окажется книга.$B$BА пока я свяжусь с самой-большой-медведицей этого медвежьего угла, то есть Рабином. Он, несомненно, пожелает узнать, что за кашу ты тут $Gзаварил:заварила;. Никогда не заставляй мать-медведицу ждать, $n... ну, если только тебе неймется искупаться в меду.$B$BТакое бывает, уж поверь мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рабином Сатурной в деревне Ночная Гавань в Лунной поляне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, $N. Как мило, что ты $Gсогласился:согласилась; меня навестить. Рад видеть тебя в добром здравии.$B$BЯ желаю через тебя выразить глубокую благодарность Кругу Кенария за их помощь, оказанную нам. Тут много секретов ожидают пытливых умов исследователей и тайны ждут, чтобы их раскрыли. Возьми это, как аванс за твои будущие достижения.$B$BБлагодярю тебя, $Gблагородный:благородная; $C.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6846,'В атаку!','Ах, приказы! Они говорят, чтобы я начинал штурм по желанию и моя воля говорит... сейчас!','Мои войска снабжены и готовы к атаке. Нам просто нужны приказы Норега Грозовой Вершины, и я отправлю их в бой!','Вернитесь к фельдмаршалу Теравейну в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В атаку!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, приказы! Они говорят, чтобы я начинал штурм по желанию и моя воля говорит... сейчас!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мои войска снабжены и готовы к атаке. Нам просто нужны приказы Норега Грозовой Вершины, и я отправлю их в бой!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фельдмаршалу Теравейну в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6847,'Всевидящее око мастера Рисона','Для Синдиката ничего не значат войны, которые ведутся в этой долине, |3-6($c). Мы будем делать то, что делали всегда: подождем, пока из пепла не появится истинный вождь, свободный от всеобщего безумия, и не нанесет решающий удар.$B$BПравда, сейчас мы здесь не поэтому. Тролли из племени Ледяной Секиры похитили наше сокровище – Всевидящее око.$B$BСпаси Око, и мы всегда будем к твоим услугам, что бы ни случилось.$B$BВозвращайся, когда добудешь Око, я тебя проверю.$B$B*Мастер Рисон оскаливает зубы в усмешке.*','Заберите Всевидящее око мастера Рисона из пещер Ледяной Секиры и возвращайтесь к мастеру Рисону.$B$BБудьте осторожны: говорят, что на Всевидящее око мастера Рисона наложено ужасное проклятие!','Всевидящее око мастера Рисона спасено','Вернитесь к мастеру Синдиката Рисону в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всевидящее око мастера Рисона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для Синдиката ничего не значат войны, которые ведутся в этой долине, |3-6($c). Мы будем делать то, что делали всегда: подождем, пока из пепла не появится истинный вождь, свободный от всеобщего безумия, и не нанесет решающий удар.$B$BПравда, сейчас мы здесь не поэтому. Тролли из племени Ледяной Секиры похитили наше сокровище – Всевидящее око.$B$BСпаси Око, и мы всегда будем к твоим услугам, что бы ни случилось.$B$BВозвращайся, когда добудешь Око, я тебя проверю.$B$B*Мастер Рисон оскаливает зубы в усмешке.*',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите Всевидящее око мастера Рисона из пещер Ледяной Секиры и возвращайтесь к мастеру Рисону.$B$BБудьте осторожны: говорят, что на Всевидящее око мастера Рисона наложено ужасное проклятие!',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Всевидящее око мастера Рисона спасено',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Синдиката Рисону в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (6848,'Всевидящее око мастера Рисона','Заберите Всевидящее око мастера Рисона из пещер Ледяной Секиры и возвращайтесь к мастеру Рисону.$B$BБудьте осторожны: говорят, что на Всевидящее око мастера Рисона наложено ужасное проклятие!','Всевидящее око мастера Рисона спасено','Вернитесь к мастеру Синдиката Рисону в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всевидящее око мастера Рисона',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите Всевидящее око мастера Рисона из пещер Ледяной Секиры и возвращайтесь к мастеру Рисону.$B$BБудьте осторожны: говорят, что на Всевидящее око мастера Рисона наложено ужасное проклятие!',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Всевидящее око мастера Рисона спасено',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Синдиката Рисону в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6861,'Портативный крошшер Зинфиззлекса','Я хочу опробовать свой портативный крошшер не меньше тебя, |3-6($r), но для того, чтобы его сделать, мне нужны материалы – много материалов!$B$BСказать точнее, целая гора тория, мифрила и железа. Кроме того, по паровой пиле на каждый крошшер. Их можно достать на лесопилке.$B$BДо того, как меня поймали, я здесь все разнюхал и обнаружил, что куча паровых пил есть на лесозаготовках Грозовой Вершины.','Принесите мастеру-инженеру Спустипару$B$B30 ториевых слитков$B$B50 мифриловых слитков$B$B75 железных слитков$B$B1 паровую пилу.','Вернитесь к мастеру-инженеру Спустипару в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Портативный крошшер Зинфиззлекса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу опробовать свой портативный крошшер не меньше тебя, |3-6($r), но для того, чтобы его сделать, мне нужны материалы – много материалов!$B$BСказать точнее, целая гора тория, мифрила и железа. Кроме того, по паровой пиле на каждый крошшер. Их можно достать на лесопилке.$B$BДо того, как меня поймали, я здесь все разнюхал и обнаружил, что куча паровых пил есть на лесозаготовках Грозовой Вершины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мастеру-инженеру Спустипару$B$B30 ториевых слитков$B$B50 мифриловых слитков$B$B75 железных слитков$B$B1 паровую пилу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру-инженеру Спустипару в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (6862,'Портативный крошшер Зинфиззлекса','Я хочу опробовать свой портативный крошшер не меньше тебя, |3-6($r), но для того, чтобы его сделать, мне нужны материалы – много материалов!$B$BСказать точнее, целая гора тория, мифрила и железа. Кроме того, по паровой пиле на каждый резак. Их можно достать на лесопилке.$B$BДо того, как меня поймали, я здесь все разнюхал и обнаружил, что куча паровых пил есть на лесозаготовках Грозовой Вершины.','Принесите мастеру-инженеру Спустипару$B$B30 ториевых слитков$B$B50 мифриловых слитков$B$B75 железных слитков$B$B1 паровую пилу.','Вернитесь к мастеру-инженеру Спустипару в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Портативный крошшер Зинфиззлекса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я хочу опробовать свой портативный крошшер не меньше тебя, |3-6($r), но для того, чтобы его сделать, мне нужны материалы – много материалов!$B$BСказать точнее, целая гора тория, мифрила и железа. Кроме того, по паровой пиле на каждый резак. Их можно достать на лесопилке.$B$BДо того, как меня поймали, я здесь все разнюхал и обнаружил, что куча паровых пил есть на лесозаготовках Грозовой Вершины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мастеру-инженеру Спустипару$B$B30 ториевых слитков$B$B50 мифриловых слитков$B$B75 железных слитков$B$B1 паровую пилу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру-инженеру Спустипару в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6881,'Ивус Лесной Властелин','Клан Северного Волка защищает энергия стихий. Если мы ослабим бдительность, их шаманы могут нас уничтожить.$B$BУщерб становится все больше и больше, Круг скоро не сможет его контролировать! Нам нужно звать на помощь.$B$BСолдаты Северного Волка носят талисманы стихий, которые называются кристаллами бури. Мы можем использовать их, чтобы связаться с Айвусом. Ступай и добудь эти кристаллы, $N!','Вернитесь к верховному друиду Дикой Лани в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ивус Лесной Властелин',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Клан Северного Волка защищает энергия стихий. Если мы ослабим бдительность, их шаманы могут нас уничтожить.$B$BУщерб становится все больше и больше, Круг скоро не сможет его контролировать! Нам нужно звать на помощь.$B$BСолдаты Северного Волка носят талисманы стихий, которые называются кристаллами бури. Мы можем использовать их, чтобы связаться с Айвусом. Ступай и добудь эти кристаллы, $N!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному друиду Дикой Лани в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (6901,'В атаку!','Речь идет о времени! Теперь мы покажем этому Альянсу свою силу!','Вернитесь к воеводе Гаррику в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В атаку!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Речь идет о времени! Теперь мы покажем этому Альянсу свою силу!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воеводе Гаррику в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6921,'Среди руин','Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины. Их присутствие приведет лишь к тому, что Стихии озлобятся на нас. Если это так и оставить, то они захватят эти места навсегда.$B$B$n, ступай в Непроглядную Пучину и найди в руинах глубинный камень. Он должен быть где-то поблизости в воде. В нем находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий. Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!','Принесите глубинный сердечник Дже\'неу Санкри на заставу Зорам\'гар в Ясеневый лес.','Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемая кладезь информации, которую мы сможем оттуда извлечь. Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить.\n\nТы сегодня хорошо потрудился, и Служители Земли весьма благодарны тебе за помощь. Ты и всей Орде помог, и имеешь право гордиться собой.','Удалось ли тебе отыскать глубинный сердечник? Без него нам не понять, что именно затевает там Сумеречный Молот.','Вернитесь к Дже\'неу Санкри на заставу Зорам\'гар, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Среди руин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины. Их присутствие приведет лишь к тому, что Стихии озлобятся на нас. Если это так и оставить, то они захватят эти места навсегда.$B$B$n, ступай в Непроглядную Пучину и найди в руинах глубинный камень. Он должен быть где-то поблизости в воде. В нем находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий. Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите глубинный сердечник Дже\'неу Санкри на заставу Зорам\'гар в Ясеневый лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемая кладезь информации, которую мы сможем оттуда извлечь. Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить.\n\nТы сегодня хорошо потрудился, и Служители Земли весьма благодарны тебе за помощь. Ты и всей Орде помог, и имеешь право гордиться собой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе отыскать глубинный сердечник? Без него нам не понять, что именно затевает там Сумеречный Молот.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дже\'неу Санкри на заставу Зорам\'гар, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (6922,'Барон Акванис','Сраженный элементаль воды оставил после себя странную водяную сферу. Вы предполагаете, что этот предмет каким-то образом подпитывал тварь энергией. Внутри сферы плещется грязная на вид жидкость. Сама сфера вроде бы не поддается никаким физическим воздействиям.$B$BЕсли кто и сможет понять, что это за штука, то это Дже\'неу Санкри из Служителей Земли.','Принесите странную водяную сферу Дже\'неу Санкри в Непроглядную Пучину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Барон Акванис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сраженный элементаль воды оставил после себя странную водяную сферу. Вы предполагаете, что этот предмет каким-то образом подпитывал тварь энергией. Внутри сферы плещется грязная на вид жидкость. Сама сфера вроде бы не поддается никаким физическим воздействиям.$B$BЕсли кто и сможет понять, что это за штука, то это Дже\'неу Санкри из Служителей Земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите странную водяную сферу Дже\'неу Санкри в Непроглядную Пучину.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6941,'Скоро флот будет готов подняться в воздух! А пока – продолжай!','Мы должны что-то сделать с элитными войсками Северного Волка, которые охраняют границы, солдат! Возвращайся ко мне с медалями их лейтенантов и легионеров. Когда я пойму, что этому сброду хорошо досталось, то добью их с воздуха.','Вернитесь к командиру звена Сквороцу в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Скоро флот будет готов подняться в воздух! А пока – продолжай!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы должны что-то сделать с элитными войсками Северного Волка, которые охраняют границы, солдат! Возвращайся ко мне с медалями их лейтенантов и легионеров. Когда я пойму, что этому сброду хорошо досталось, то добью их с воздуха.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру звена Сквороцу в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6942,'Продолжай свое дело, солдат! Грифоны Заоблачного пика готовы к вылету с минуты на минуту!','Мои грифоны должны отправиться вглубь территории противника, чтобы нанести удар, но линия фронта слишком хорошо охраняется.$B$BВоины клана Северного Волка, которые охраняют линию фронта, носят на груди медали за верную службу. Сорви эти медали с их трупов и принеси мне.$B$BКак только линия фронта будет ослаблена, мы нанесем удар с воздуха!','Вернитесь к командиру звена Макарчу в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Продолжай свое дело, солдат! Грифоны Заоблачного пика готовы к вылету с минуты на минуту!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мои грифоны должны отправиться вглубь территории противника, чтобы нанести удар, но линия фронта слишком хорошо охраняется.$B$BВоины клана Северного Волка, которые охраняют линию фронта, носят на груди медали за верную службу. Сорви эти медали с их трупов и принеси мне.$B$BКак только линия фронта будет ослаблена, мы нанесем удар с воздуха!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру звена Макарчу в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6943,'Небо зовет – флот Ромеона','Видишь? Посмотри на них, солдат! Вот они, кружат в воздухе! Скоро флот Ромеона нанесет удар в самое сердце долины! Грозовая Вершина будет править в небесах!','Их дух сломлен, солдат. После нашего неудачного налета на Орду они отказываются подниматься в воздух! Но ты можешь поднять их боевой дух.$B$BВозвращайся на поле битвы и лиши клан Северного Волка командования. Сокруши всех стражей и командиров! Все они носят медали. Собери с трупов столько их медалей, сколько сможешь унести, и возвращайся ко мне. Как только мои грифоны увидят награду и почуют запах поверженного врага, они снова сумеют подняться в воздух. А теперь ступай!','Вернитесь к командиру звена Ромеону в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небо зовет – флот Ромеона',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Видишь? Посмотри на них, солдат! Вот они, кружат в воздухе! Скоро флот Ромеона нанесет удар в самое сердце долины! Грозовая Вершина будет править в небесах!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Их дух сломлен, солдат. После нашего неудачного налета на Орду они отказываются подниматься в воздух! Но ты можешь поднять их боевой дух.$B$BВозвращайся на поле битвы и лиши клан Северного Волка командования. Сокруши всех стражей и командиров! Все они носят медали. Собери с трупов столько их медалей, сколько сможешь унести, и возвращайся ко мне. Как только мои грифоны увидят награду и почуют запах поверженного врага, они снова сумеют подняться в воздух. А теперь ступай!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру звена Ромеону в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (6961,'Здравствуй, Дедушка Зима!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Здравствуй, Дедушка Зима!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6963,'Пропавшее угощение Зимнего Покрова','Слушай... Не хотелось бы разрушать праздничное волшебство, однако Пастбищам Дымного Леса нужна помощь $gискателя приключений:искательницы приключений; вроде тебя.$b$bУ нас пропал груз сладостей, которые мы закупили к зиме, а теперь куда-то подевался еще и наш агент, которого мы отправили разыскивать товар! В последний раз груз видели в Альтеракских горах, что в Предгорьях Хилсбрада, туда за ним и отправился наш агент.$b$bПозаботься о том, чтобы и товар, и наш работник вернулись сюда в целости и сохранности!','Отыщите агента Пастбищ Дымного Леса, который затерялся в снегах Предгорий Хилсбрада.','Т-т-ты м-м-меня с-слышишь! Слава б-б-богам!$B$BН-нет, я не с-с-снеговик. М-меня зовут Сакс, я раб-ботаю в Оргриммарском отделении Пастбищ Дымного Леса. М-м-м-меня отп-правили искать пропавший товар, и тут на меня нап-пала тварь, какой я никогда не видывал!$B$BБр-р, ну и холодрыга!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшее угощение Зимнего Покрова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай... Не хотелось бы разрушать праздничное волшебство, однако Пастбищам Дымного Леса нужна помощь $gискателя приключений:искательницы приключений; вроде тебя.$b$bУ нас пропал груз сладостей, которые мы закупили к зиме, а теперь куда-то подевался еще и наш агент, которого мы отправили разыскивать товар! В последний раз груз видели в Альтеракских горах, что в Предгорьях Хилсбрада, туда за ним и отправился наш агент.$b$bПозаботься о том, чтобы и товар, и наш работник вернулись сюда в целости и сохранности!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите агента Пастбищ Дымного Леса, который затерялся в снегах Предгорий Хилсбрада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Т-т-ты м-м-меня с-слышишь! Слава б-б-богам!$B$BН-нет, я не с-с-снеговик. М-меня зовут Сакс, я раб-ботаю в Оргриммарском отделении Пастбищ Дымного Леса. М-м-м-меня отп-правили искать пропавший товар, и тут на меня нап-пала тварь, какой я никогда не видывал!$B$BБр-р, ну и холодрыга!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6964,'Повод для праздника','Подарки, гости, угощение... чушь собачья!$B$BЭти гоблины искажают саму суть праздника Зимнего Покрова. Это время возрождения – земля спит под покровом снега, которым ее укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!$B$BЕжели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте Сагорна Гривастого Странника. Уверен, он будет очень удивлен, что хоть кому-то история интереснее подарков.','Поговорите с Сагорном Гривастым Странником на Аллее Мудрости Оргриммара о празднике Зимнего Покрова.','Праздник Зимнего Покрова, говоришь? Увы, в прежние времена для нас, тауренов, он был куда важнее. А теперь, похоже, другие используют древние легенды, чтобы продать побольше сладостей и подарков.$B$BНеудивительно, что Фарманда это так огорчает. Он и остальные таурены держатся за наше прошлое, как за боевое знамя. Я лично считаю, что немного веселья никогда не помешает, но о происхождении праздника забывать нельзя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повод для праздника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подарки, гости, угощение... чушь собачья!$B$BЭти гоблины искажают саму суть праздника Зимнего Покрова. Это время возрождения – земля спит под покровом снега, которым ее укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!$B$BЕжели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте Сагорна Гривастого Странника. Уверен, он будет очень удивлен, что хоть кому-то история интереснее подарков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сагорном Гривастым Странником на Аллее Мудрости Оргриммара о празднике Зимнего Покрова.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Праздник Зимнего Покрова, говоришь? Увы, в прежние времена для нас, тауренов, он был куда важнее. А теперь, похоже, другие используют древние легенды, чтобы продать побольше сладостей и подарков.$B$BНеудивительно, что Фарманда это так огорчает. Он и остальные таурены держатся за наше прошлое, как за боевое знамя. Я лично считаю, что немного веселья никогда не помешает, но о происхождении праздника забывать нельзя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (6981,'Светящийся осколок','Блестящий осколок ярко-зеленый, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство.$B$BПожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке.','Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке.$B$BЗатем отнесите осколок туда, куда вас направят.','О... мне никогда не приходилось видеть ничего подобного...','Приветствую тебя, |3-6($R). Я могу тебе чем-то помочь?','Поговорите с кем-нибудь в Кабестане о светящемся осколке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Светящийся осколок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Блестящий осколок ярко-зеленый, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма. Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство.$B$BПожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Кабестан и найдите там кого-нибудь, кто сможет вам рассказать об этом светящемся осколке.$B$BЗатем отнесите осколок туда, куда вас направят.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О... мне никогда не приходилось видеть ничего подобного...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя, |3-6($R). Я могу тебе чем-то помочь?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поговорите с кем-нибудь в Кабестане о светящемся осколке.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6982,'Припасы Ледяного Зуба','Рудник Ледяного Зуба – это хранилище Орды. Мой желудок не переваривает жратву, которой они кормят своих солдат, а их доспехи и оружие выглядят ужасно! Но... во времена, когда припасы столь важны, нам выбирать не приходится. $b$bОтправляйся в рудник Ледяного Зуба и принеси мне часть их припасов. Это поможет Альянсу поддержать свою боевую форму, а заодно лишить воинов Орды самого необходимого.$b$bРудник находится далеко на юге, в глубоком тылу Орды.','Принесите 10 ящиков с припасами Ледяного Зуба интенданту Альянса в Дун Болдар.','А, вот они! Превосходно, $N! Припасы немного заплесневели – сказывается влажность воздуха в руднике – но все равно сгодятся.$B$BСпасибо тебе, $N. Ты $Gпомог:помогла; нашим войскам поддержать силы.','Ты $Gвернулся:вернулась; с рудника Ледяного Зуба? А где припасы?','Вернитесь к интенданту клана Грозовой Вершины в Дун Болдар, что в Альтеракской долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы Ледяного Зуба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рудник Ледяного Зуба – это хранилище Орды. Мой желудок не переваривает жратву, которой они кормят своих солдат, а их доспехи и оружие выглядят ужасно! Но... во времена, когда припасы столь важны, нам выбирать не приходится. $b$bОтправляйся в рудник Ледяного Зуба и принеси мне часть их припасов. Это поможет Альянсу поддержать свою боевую форму, а заодно лишить воинов Орды самого необходимого.$b$bРудник находится далеко на юге, в глубоком тылу Орды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 ящиков с припасами Ледяного Зуба интенданту Альянса в Дун Болдар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, вот они! Превосходно, $N! Припасы немного заплесневели – сказывается влажность воздуха в руднике – но все равно сгодятся.$B$BСпасибо тебе, $N. Ты $Gпомог:помогла; нашим войскам поддержать силы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась; с рудника Ледяного Зуба? А где припасы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту клана Грозовой Вершины в Дун Болдар, что в Альтеракской долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (6984,'Благодарность от "Пастбищ Дымного Леса"!','Спасибо тебе от "Пастбищ Дымного Леса" за возвращение похищенных сладостей, $n! Мы хотим тебе за это предложить особый подарок... От самого Дедушки Зимы!$B$BПоговори с Дедушкой Зимой, и он преподнесет тебе подарок к Зимнему Покрову от нашего имени! От нашего стола вашему столу – вкусная и здоровая пища от "Пастбищ Дымного Леса"...благодаря тебе, конечно же!','Поговорите с Дедушкой Зимой в Оргриммаре.','Хо-хо-хо! Добро пожаловать!$B$BГоблины мне сказали, что тебе нынче полагается специальный приз, и я рад отдать его. Вот он – и веселого тебе праздника Зимнего Покрова каждый год!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодарность от "Пастбищ Дымного Леса"!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо тебе от "Пастбищ Дымного Леса" за возвращение похищенных сладостей, $n! Мы хотим тебе за это предложить особый подарок... От самого Дедушки Зимы!$B$BПоговори с Дедушкой Зимой, и он преподнесет тебе подарок к Зимнему Покрову от нашего имени! От нашего стола вашему столу – вкусная и здоровая пища от "Пастбищ Дымного Леса"...благодаря тебе, конечно же!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дедушкой Зимой в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хо-хо-хо! Добро пожаловать!$B$BГоблины мне сказали, что тебе нынче полагается специальный приз, и я рад отдать его. Вот он – и веселого тебе праздника Зимнего Покрова каждый год!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (6985,'Припасы Железного рудника','Дворфы Грозовой Вершины используют Железный рудник для хранения припасов. Сбегай на этот рудник и позаимствуй у дворфов их богатства. Это малость подрежет крылья Грозовой Вершине, а мы получим необходимые материалы.$B$BДействуй осторожно, $n. Железный рудник лежит в глубине территории Альянса, и за него постоянно идут бои.','Доставьте 10 ящиков припасов Железного рудника интенданту Орды в крепость Северного Волка.','Ты $Gдостал:достала; их! Прекрасно, $N! Я надеюсь, что ты $Gвидел:видела; пару дворфов во время своего похода и $Gпролил:пролила; их кровь во славу Северного Волка!','Ты $Gвошел:вошла; в шахту Железной глубины, $N? Вы совершали набег на его припасы?','Вернитесь к интенданту клана Северного Волка в Крепость Северного Волка, что в Альтеракской долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы Железного рудника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дворфы Грозовой Вершины используют Железный рудник для хранения припасов. Сбегай на этот рудник и позаимствуй у дворфов их богатства. Это малость подрежет крылья Грозовой Вершине, а мы получим необходимые материалы.$B$BДействуй осторожно, $n. Железный рудник лежит в глубине территории Альянса, и за него постоянно идут бои.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте 10 ящиков припасов Железного рудника интенданту Орды в крепость Северного Волка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gдостал:достала; их! Прекрасно, $N! Я надеюсь, что ты $Gвидел:видела; пару дворфов во время своего похода и $Gпролил:пролила; их кровь во славу Северного Волка!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвошел:вошла; в шахту Железной глубины, $N? Вы совершали набег на его припасы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту клана Северного Волка в Крепость Северного Волка, что в Альтеракской долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (7001,'Пустые стойла','Набат войны зовет наших солдат к оружию! Мы должны восстановить боеспособность армии!$B$BЕсли в стойлах заведется зверье, то всадники на волках смогут снова отправиться в бой.$B$BВозьми этот намордник и найди следы северных волков, обитающих в ближайшем лесу. Когда отыщешь волка, используй намордник, чтобы его приручить. Прирученных зверей приводи ко мне, я поставлю их в стойла.$B$BКогда стойла будут полны, наши всадники снова смогут отправиться на фронт.','Найдите северного волка в Альтеракской долине. Подойдите к нему на достаточное расстояние, чтобы его "приручить", и используйте намордник Северного Волка. После приручения северный волк проследует за вами к смотрителю стойл из клана Северного Волка. Поговорите со смотрителем, чтобы получить награду за пойманных волков.','Без твоей помощи у Всадников на волках из клана Северного Волка не было бы верховых животных, чтобы отправиться в бой. Ты оказываешь нам отличную услугу!','Приручите северного волка и приведите его к конюшенному.','Вернитесь к смотрителю стойл из клана Северного Волка в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пустые стойла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Набат войны зовет наших солдат к оружию! Мы должны восстановить боеспособность армии!$B$BЕсли в стойлах заведется зверье, то всадники на волках смогут снова отправиться в бой.$B$BВозьми этот намордник и найди следы северных волков, обитающих в ближайшем лесу. Когда отыщешь волка, используй намордник, чтобы его приручить. Прирученных зверей приводи ко мне, я поставлю их в стойла.$B$BКогда стойла будут полны, наши всадники снова смогут отправиться на фронт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите северного волка в Альтеракской долине. Подойдите к нему на достаточное расстояние, чтобы его "приручить", и используйте намордник Северного Волка. После приручения северный волк проследует за вами к смотрителю стойл из клана Северного Волка. Поговорите со смотрителем, чтобы получить награду за пойманных волков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Без твоей помощи у Всадников на волках из клана Северного Волка не было бы верховых животных, чтобы отправиться в бой. Ты оказываешь нам отличную услугу!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите северного волка и приведите его к конюшенному.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к смотрителю стойл из клана Северного Волка в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7002,'Упряжь из бараньей кожи','Отлично, солдат. Я скажу тебе, когда будет достаточно.$B$BА пока продолжай работать!','Одни наши солдаты занимаются поимкой волков для стойл, другие должны раздобыть необходимую упряжь.$B$BТебе придется поохотиться на местных баранов. Тех самых, на которых ездит кавалерия Грозовой Вершины!$B$BУбей этих баранов и принеси мне их шкуры. Из них мы соорудим упряжь для волков. Наездники снова сядут в седла!','Вернитесь к командиру всадников на волках клана Северного Волка в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упряжь из бараньей кожи',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, солдат. Я скажу тебе, когда будет достаточно.$B$BА пока продолжай работать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Одни наши солдаты занимаются поимкой волков для стойл, другие должны раздобыть необходимую упряжь.$B$BТебе придется поохотиться на местных баранов. Тех самых, на которых ездит кавалерия Грозовой Вершины!$B$BУбей этих баранов и принеси мне их шкуры. Из них мы соорудим упряжь для волков. Наездники снова сядут в седла!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру всадников на волках клана Северного Волка в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7003,'Уменьшение великанов','Нет, если я собираюсь здесь остаться, мне решительно необходимо что-то сделать с великанами! Они губят весь бизнес.$b$bЯ взял за основу разновидность гномского уменьшающего луча, но внес в конструкцию гоблинские усовершенствования! Дабы самому избежать различных неудобств – например, смерти, – я поручаю его испытание вам. Испробуйте его на любых великанах, каких найдете в Фераласе. После уменьшения вы обнаружите на месте великанов остаточное вещество – принесите его мне!','Используйте ультрасжиматель Зорбина, чтобы уменьшить великанов любого вида, каких вы найдете в Фераласе. Принесите 15 порций остаточного вещества великанов Зорбину Дребезгуну в порт Забытого берега в Фераласе.','Превосхитительнейше! Я не только благодарен тебе за великанов, но и очень рад видеть, что ты вроде как в целости и добром здравии. Хотя мой Ультрасжиматель всегда был абсолютно безопасен, так ведь?$B$BСпасибо за твои старания, $N. Теперь все гоблины будут относиться к тебе, как к другу. Вот, прими это в знак моей признательности!','Остатки миниатюризации – ценнейшая штука для инженера, скажу я вам! Ну, например, они помогают гарантировать, что уменьшитель не сделает чего-нибудь не того: например, не взорвется в руках при работе с ним.$B$BНет-нет, тот, что у вас, конечно же, не взорвется! Он абсолютно надежен!','Вернитесь к Зорбину Дребезгуну на Забытый берег, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшение великанов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет, если я собираюсь здесь остаться, мне решительно необходимо что-то сделать с великанами! Они губят весь бизнес.$b$bЯ взял за основу разновидность гномского уменьшающего луча, но внес в конструкцию гоблинские усовершенствования! Дабы самому избежать различных неудобств – например, смерти, – я поручаю его испытание вам. Испробуйте его на любых великанах, каких найдете в Фераласе. После уменьшения вы обнаружите на месте великанов остаточное вещество – принесите его мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте ультрасжиматель Зорбина, чтобы уменьшить великанов любого вида, каких вы найдете в Фераласе. Принесите 15 порций остаточного вещества великанов Зорбину Дребезгуну в порт Забытого берега в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосхитительнейше! Я не только благодарен тебе за великанов, но и очень рад видеть, что ты вроде как в целости и добром здравии. Хотя мой Ультрасжиматель всегда был абсолютно безопасен, так ведь?$B$BСпасибо за твои старания, $N. Теперь все гоблины будут относиться к тебе, как к другу. Вот, прими это в знак моей признательности!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Остатки миниатюризации – ценнейшая штука для инженера, скажу я вам! Ну, например, они помогают гарантировать, что уменьшитель не сделает чего-нибудь не того: например, не взорвется в руках при работе с ним.$B$BНет-нет, тот, что у вас, конечно же, не взорвется! Он абсолютно надежен!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зорбину Дребезгуну на Забытый берег, что в Фераласе.',`completedtext_loc8`);
