INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (7024,'Здравствуй, Дедушка Зима!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Здравствуй, Дедушка Зима!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7025,'Угощение для Дедушки Зимы','Эй, не окажешь ли услугу Дедушке Зиме, хм, $Gмальчуган:девчушка;?$B$BНет смысла говорить о себе в третьем лице, но Дедушка Зима весь день был на ногах и хотел бы и сам полакомиться угощением. Немного пряников и ледяного молока, чтобы запить, – и будет довольно. Ты ведь любишь дедушку и принесешь мне угощение?','Принесите 5 кусочков имбирного печенья и ледяное молоко Дедушке Зиме в Стальгорн.','Вернитесь к Дедушке Зиме в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угощение для Дедушки Зимы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, не окажешь ли услугу Дедушке Зиме, хм, $Gмальчуган:девчушка;?$B$BНет смысла говорить о себе в третьем лице, но Дедушка Зима весь день был на ногах и хотел бы и сам полакомиться угощением. Немного пряников и ледяного молока, чтобы запить, – и будет довольно. Ты ведь любишь дедушку и принесешь мне угощение?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 кусочков имбирного печенья и ледяное молоко Дедушке Зиме в Стальгорн.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дедушке Зиме в Стальгорн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7026,'Упряжь ездовых баранов','Отлично, солдат. Я скажу тебе, когда будет достаточно.$B$BА пока продолжай работать!','Бригада Грозовой Вершины не может отправиться в бой, не имея седел! Мы же не дикари, нам нужна упряжь для наших баранов.$B$BМы бы, конечно, могли снять шкуры с баранов, которые пасутся рядом с базой, но это было бы исключительной глупостью. А ездить мы на чем будем?$B$BТы должен напасть на базу наших врагов, клана Северного Волка и снять шкуры с волков, которых они используют как верховых животных. Когда добудешь шкуры, возвращайся, из них получится отличная упряжь. Ступай!','Вернитесь к командиру наездников на баранах клана Грозовой Вершины в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упряжь ездовых баранов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, солдат. Я скажу тебе, когда будет достаточно.$B$BА пока продолжай работать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Бригада Грозовой Вершины не может отправиться в бой, не имея седел! Мы же не дикари, нам нужна упряжь для наших баранов.$B$BМы бы, конечно, могли снять шкуры с баранов, которые пасутся рядом с базой, но это было бы исключительной глупостью. А ездить мы на чем будем?$B$BТы должен напасть на базу наших врагов, клана Северного Волка и снять шкуры с волков, которых они используют как верховых животных. Когда добудешь шкуры, возвращайся, из них получится отличная упряжь. Ступай!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру наездников на баранах клана Грозовой Вершины в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (7027,'Пустые стойла','Посмотри на эти стойла, $n! Они совершенно пустые! У бригады Грозовой Вершины нет скаковых баранов, а значит, нет и кавалерии.$B$BТы $gдолжен:должна; помочь нам, солдат! Возьми учебный ошейник и отправляйся в самую глушь этой долины. Найди альтеракских баранов, которые там бродят, и поймай их при помощи ошейника. Как поймаешь барана, возвращайся ко мне, я поставлю его в стойла.$B$BКогда баранов будет достаточно, я извещу командира всадников. В твоих силах возродить нашу кавалерию!','Найдите в Альтеракской долине альтеракского барана. Чтобы приручить барана, используйте учебный ошейник Грозовой Вершины. Для этого надо подойти в барану поближе. Пойманный баран проследует за вами к смотрителю стойл. Поговорите со смотрителем стойл, чтобы получить вознаграждение за пойманных баранов.','Стойла будут полны! Хорошая работа, солдат!','Без твоей помощи бараньи наездники на баранах из клана Грозовой Вершины останутся без верховых животных. Ты можешь оказать нам неоценимую услугу!','Баран пойман и возвращен','Вернитесь к смотрителю стойл из клана Грозовой Вершины в Дун Болдар, что в Альтеракской долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пустые стойла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посмотри на эти стойла, $n! Они совершенно пустые! У бригады Грозовой Вершины нет скаковых баранов, а значит, нет и кавалерии.$B$BТы $gдолжен:должна; помочь нам, солдат! Возьми учебный ошейник и отправляйся в самую глушь этой долины. Найди альтеракских баранов, которые там бродят, и поймай их при помощи ошейника. Как поймаешь барана, возвращайся ко мне, я поставлю его в стойла.$B$BКогда баранов будет достаточно, я извещу командира всадников. В твоих силах возродить нашу кавалерию!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Альтеракской долине альтеракского барана. Чтобы приручить барана, используйте учебный ошейник Грозовой Вершины. Для этого надо подойти в барану поближе. Пойманный баран проследует за вами к смотрителю стойл. Поговорите со смотрителем стойл, чтобы получить вознаграждение за пойманных баранов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стойла будут полны! Хорошая работа, солдат!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Без твоей помощи бараньи наездники на баранах из клана Грозовой Вершины останутся без верховых животных. Ты можешь оказать нам неоценимую услугу!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Баран пойман и возвращен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к смотрителю стойл из клана Грозовой Вершины в Дун Болдар, что в Альтеракской долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7028,'Хрустальные орнаменты','На западе, в глубинах Мародона, раскинулись хрустальные пещеры Террамока... Это очень древнее место, |3-6($c). А я хочу наложить лапу на часть тамошних древностей. За огромными дверями скрыты реликвии древних богов.$b$bЕсли ты отважишься бросить вызов злу, таящемуся в Мародоне, я щедро тебе заплачу. Собери там терадрические хрустальные орнаменты и принеси их мне.$b$bКак только я доберусь до этих орнаментов, я смогу их... изучить. Слишком долго дремали скрытые силы...','Соберите 15 терадрических хрустальных орнаментов для Ивы из Пустошей.','Ха-ха-ха! Я так и знала, что ты вернешься.$B$BИва бормочет себе под нос.$B$B... Как легко убедить.$B$B… пойдет на что угодно за сходную цену. Хе-хе-хе...','Не задавай лишних вопросов!$B$BЗаказ есть заказ.','Вернитесь к Иве в Пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хрустальные орнаменты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На западе, в глубинах Мародона, раскинулись хрустальные пещеры Террамока... Это очень древнее место, |3-6($c). А я хочу наложить лапу на часть тамошних древностей. За огромными дверями скрыты реликвии древних богов.$b$bЕсли ты отважишься бросить вызов злу, таящемуся в Мародоне, я щедро тебе заплачу. Собери там терадрические хрустальные орнаменты и принеси их мне.$b$bКак только я доберусь до этих орнаментов, я смогу их... изучить. Слишком долго дремали скрытые силы...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 терадрических хрустальных орнаментов для Ивы из Пустошей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха-ха! Я так и знала, что ты вернешься.$B$BИва бормочет себе под нос.$B$B... Как легко убедить.$B$B… пойдет на что угодно за сходную цену. Хе-хе-хе...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не задавай лишних вопросов!$B$BЗаказ есть заказ.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иве в Пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7029,'Скверна Злоязыкого','В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет все, до чего может дотянуться. Из-за него умирают растения.$B$bВозьми этот фиал, $n, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство.$b$bОтыщи в оранжевых пещерах гнусь-лозу и полей ее целебной жидкостью. Растение очистится от скверны, но все равно останется в воле Злоязыкого. Он может обратить его против тебя.','Наполните лазурный фиал с внутренним покрытием в оранжевом пруду Мародона.$B$BПолейте гнусь-лозу из наполненного фиала, чтобы изгнать ядовитую лозу.$B$BИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников.','Спасибо, что $Gпринес:принесла; мне фиал. Я исследую остатки жидкости.$B$BХотя впереди много работы, зло, совершенное Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности.','Если ты сумеешь исцелить растение, оно снова оживет. Мы должны делать все, что в наших силах, $N...','Вернитесь к Варку Боевому Шраму в деревню Гелкис, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скверна Злоязыкого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет все, до чего может дотянуться. Из-за него умирают растения.$B$bВозьми этот фиал, $n, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство.$b$bОтыщи в оранжевых пещерах гнусь-лозу и полей ее целебной жидкостью. Растение очистится от скверны, но все равно останется в воле Злоязыкого. Он может обратить его против тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните лазурный фиал с внутренним покрытием в оранжевом пруду Мародона.$B$BПолейте гнусь-лозу из наполненного фиала, чтобы изгнать ядовитую лозу.$B$BИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Варку Боевому Шраму в Деревню Ночных Охотников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что $Gпринес:принесла; мне фиал. Я исследую остатки жидкости.$B$BХотя впереди много работы, зло, совершенное Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты сумеешь исцелить растение, оно снова оживет. Мы должны делать все, что в наших силах, $N...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варку Боевому Шраму в деревню Гелкис, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (7041,'Скверна Злоязыкого','В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет все кругом. Из-за него там больше не растут цветы.$B$bВозьми этот фиал, $n, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство.$b$bОтыщи в оранжевых пещерах гнусь-лозу и полей ее целебной жидкостью. Растение очистится от скверны, но все равно останется в воле Злоязыкого. Он может обратить его против тебя.','Наполните лазурный фиал с внутренним покрытием в оранжевом пруду Мародона.$B$BПолейте гнусь-лозу из наполненного фиала, чтобы изгнать ядовитую лозу.$B$BИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела.','Спасибо, что принес мне фиал. Я исследую остатки жидкости.$B$BХотя впереди много работы, зло, совершенное Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности.','Вернитесь к Талендрии в Обугленную долину, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скверна Злоязыкого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В пещерах Мародона поселился сатир по имени Злоязыкий и оскверняет все кругом. Из-за него там больше не растут цветы.$B$bВозьми этот фиал, $n, и наполни его из оранжевого пруда рядом с пещерами. Внутри фиала есть особое покрытие, которое превратит яд в лекарство.$b$bОтыщи в оранжевых пещерах гнусь-лозу и полей ее целебной жидкостью. Растение очистится от скверны, но все равно останется в воле Злоязыкого. Он может обратить его против тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните лазурный фиал с внутренним покрытием в оранжевом пруду Мародона.$B$BПолейте гнусь-лозу из наполненного фиала, чтобы изгнать ядовитую лозу.$B$BИсцелите 8 растений, убивая ядовитые лозы, и вернитесь к Талендрии из Высоты Найджела.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что принес мне фиал. Я исследую остатки жидкости.$B$BХотя впереди много работы, зло, совершенное Злоязыким в Мародоне, хотя бы отчасти исправлено. Прими это в знак моей благодарности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талендрии в Обугленную долину, что в Когтистых горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7042,'Пропавшее угощение Зимнего Покрова','Слушай... Не хотелось бы разрушать праздничное волшебство, однако Пастбищам Дымного Леса нужна помощь $gискателя приключений:искательницы приключений; вроде тебя.$b$bУ нас пропал груз сладостей, которые мы закупили к зиме, а теперь куда-то подевался еще и наш агент, которого мы отправили разыскивать товар! В последний раз груз видели в Альтеракских горах, что в Предгорьях Хилсбрада, туда за ним и отправился наш агент.$b$bПозаботься о том, чтобы и товар, и наш работник вернулись сюда в целости и сохранности!','Отыщите агента Пастбищ Дымного Леса, который затерялся в снегах Предгорий Хилсбрада.','В-в-вы м-м-меня с-с-слыш-шит-т-е! П-по г-г-гроб ж-жиз-зни б-б-б-лагодарен!\n\nЯ н-н-не с-с-нег-говик, я М-м-еш-ш-окс, я р-р-абот-т-аю на с-с-с-т-ттальгорнское от-т-деление П-п-астбищ Д-д-дымного Л-леса... М-меня п-п-ослали на-найти п-пропавший груз, к-кок-гда на м-м-меня н-напала т-т-варь, каких я п-п-прежде и н-н-е в-видывал!\n\nКак же я з-з-з-ам-м-мерз-з-з...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшее угощение Зимнего Покрова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай... Не хотелось бы разрушать праздничное волшебство, однако Пастбищам Дымного Леса нужна помощь $gискателя приключений:искательницы приключений; вроде тебя.$b$bУ нас пропал груз сладостей, которые мы закупили к зиме, а теперь куда-то подевался еще и наш агент, которого мы отправили разыскивать товар! В последний раз груз видели в Альтеракских горах, что в Предгорьях Хилсбрада, туда за ним и отправился наш агент.$b$bПозаботься о том, чтобы и товар, и наш работник вернулись сюда в целости и сохранности!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите агента Пастбищ Дымного Леса, который затерялся в снегах Предгорий Хилсбрада.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В-в-вы м-м-меня с-с-слыш-шит-т-е! П-по г-г-гроб ж-жиз-зни б-б-б-лагодарен!\n\nЯ н-н-не с-с-нег-говик, я М-м-еш-ш-окс, я р-р-абот-т-аю на с-с-с-т-ттальгорнское от-т-деление П-п-астбищ Д-д-дымного Л-леса... М-меня п-п-ослали на-найти п-пропавший груз, к-кок-гда на м-м-меня н-напала т-т-варь, каких я п-п-прежде и н-н-е в-видывал!\n\nКак же я з-з-з-ам-м-мерз-з-з...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7044,'Легенды Мародона','Повелитель сатиров, лорд Злоязыкий, сеет ужас по всем ходам-переходам этой пещеры, отравляя разум и чувства всех несчастных, оказавшихся внутри. Он живет за лиловыми кристаллами.$b$BКроме того, Злоязыкий создал живой символ собственного падения, Ноксиона, который живет за оранжевыми кристаллами. Эти двое похитили скипетр моего брата. Келебрас, мой брат... бессмысленно бродит по пещерам, снедаемый скверной.$b$bПомоги ему! Найди обломки скипетра и попробуй поговорить с моим братом.','Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса.$b$bНайдите способ поговорить с Келебрасом.','Теперь, когда мой жезл собран воедино, надеюсь, вскоре мы сумеем избавить Мародон от скверны.','Я очнулся от нескончамого кошмара...','Вернитесь к Келебрасу Освобожденному в Мародон.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легенды Мародона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Повелитель сатиров, лорд Злоязыкий, сеет ужас по всем ходам-переходам этой пещеры, отравляя разум и чувства всех несчастных, оказавшихся внутри. Он живет за лиловыми кристаллами.$b$BКроме того, Злоязыкий создал живой символ собственного падения, Ноксиона, который живет за оранжевыми кристаллами. Эти двое похитили скипетр моего брата. Келебрас, мой брат... бессмысленно бродит по пещерам, снедаемый скверной.$b$bПомоги ему! Найди обломки скипетра и попробуй поговорить с моим братом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте две части скипетра Келебраса – жезл Келебраса и бриллиант Келебраса.$b$bНайдите способ поговорить с Келебрасом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда мой жезл собран воедино, надеюсь, вскоре мы сумеем избавить Мародон от скверны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я очнулся от нескончамого кошмара...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келебрасу Освобожденному в Мародон.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (7045,'Благодарность от "Пастбищ Дымного Леса"!','Спасибо тебе от "Пастбищ Дымного Леса" за возвращение похищенных сладостей, $n! Мы хотим тебе за это предложить особый подарок... От самого Дедушки Зимы!$B$BПоговори с Дедушкой Зимой, и он преподнесет тебе подарок к Зимнему Покрову от нашего имени! От нашего стола вашему столу – вкусная и здоровая пища от "Пастбищ Дымного Леса"...благодаря тебе, конечно же!','Поговорите с Дедушкой Зимой в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодарность от "Пастбищ Дымного Леса"!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо тебе от "Пастбищ Дымного Леса" за возвращение похищенных сладостей, $n! Мы хотим тебе за это предложить особый подарок... От самого Дедушки Зимы!$B$BПоговори с Дедушкой Зимой, и он преподнесет тебе подарок к Зимнему Покрову от нашего имени! От нашего стола вашему столу – вкусная и здоровая пища от "Пастбищ Дымного Леса"...благодаря тебе, конечно же!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дедушкой Зимой в Стальгорне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (7046,'Скипетр Келебраса','Некогда скипетр был моей опорой и надежей. Он наделял меня властью над этими пещерами. Я надеялся умиротворить дух моего дяди... Теперь я передам это бремя тебе.$b$bДля того же, чтобы слить воедино обе половины скипетра, мне понадобится твоя помощь. Иди за мной и пока я буду призывать энергию, чтобы воссоединить жезл с бриллиантом, выполняй мои указания.$b$bВоссоздадим же совместными усилиями скипетр Келебраса!','Помогите Келебрасу Освобожденному воссоздать скипетр Келебраса.$b$bПо завершении ритуала снова обратитесь к нему.','Прошу тебя, возьми этот скипетр и знай, что заключенная в нем сила должна служить лишь добру. Не останавливайся на достигнутом, иди дальше, вглубь пещер. Надеюсь, ты сумеешь отыскать останки моего дяди. Тебя подстерегает множество опасностей, $n.$B$BЕсли понадобится, можешь смело обращаться ко мне.','Если ты хочешь начать ритуал заново, останови его и снова обратись ко мне.','Создать скипетр Келебраса','Вернитесь к Келебрасу Освобожденному в Мародон.','Создать скипетр Келебраса') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скипетр Келебраса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некогда скипетр был моей опорой и надежей. Он наделял меня властью над этими пещерами. Я надеялся умиротворить дух моего дяди... Теперь я передам это бремя тебе.$b$bДля того же, чтобы слить воедино обе половины скипетра, мне понадобится твоя помощь. Иди за мной и пока я буду призывать энергию, чтобы воссоединить жезл с бриллиантом, выполняй мои указания.$b$bВоссоздадим же совместными усилиями скипетр Келебраса!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Келебрасу Освобожденному воссоздать скипетр Келебраса.$b$bПо завершении ритуала снова обратитесь к нему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прошу тебя, возьми этот скипетр и знай, что заключенная в нем сила должна служить лишь добру. Не останавливайся на достигнутом, иди дальше, вглубь пещер. Надеюсь, ты сумеешь отыскать останки моего дяди. Тебя подстерегает множество опасностей, $n.$B$BЕсли понадобится, можешь смело обращаться ко мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты хочешь начать ритуал заново, останови его и снова обратись ко мне.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Создать скипетр Келебраса',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келебрасу Освобожденному в Мародон.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Создать скипетр Келебраса',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (7061,'Праздник Зимнего Покрова','Вот, если тебе интересно узнать о празднике Зимнего Покрова побольше, прочти эту книгу. Я полагаю, что наше толкование легенды достаточно верное, и все же, как ученый, предпочитаю, чтобы вся информация была проверена.$b$bКогда дочитаешь, отнеси эту книгу в Громовой Утес Бейну Кровавому Копыту. Ему наверняка приятно будет узнать, что кто-то еще интересуется преданиями нашего народа.','Добро пожаловать в Мулгор и нашу скромную общину Громового Утеса, $Gдруг:подруга; $Gмой:моя;. Мне всегда были по нраву те, кому интересно наше королевство, его народ и его предания. Ты ведь поэтому здесь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Праздник Зимнего Покрова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, если тебе интересно узнать о празднике Зимнего Покрова побольше, прочти эту книгу. Я полагаю, что наше толкование легенды достаточно верное, и все же, как ученый, предпочитаю, чтобы вся информация была проверена.$b$bКогда дочитаешь, отнеси эту книгу в Громовой Утес Бейну Кровавому Копыту. Ему наверняка приятно будет узнать, что кто-то еще интересуется преданиями нашего народа.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать в Мулгор и нашу скромную общину Громового Утеса, $Gдруг:подруга; $Gмой:моя;. Мне всегда были по нраву те, кому интересно наше королевство, его народ и его предания. Ты ведь поэтому здесь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (7062,'Повод для праздника','Подарки, гости, угощение... чушь собачья!$B$BЭти гоблины искажают самую суть праздника Зимнего Покрова. Это время возрождения – земля спит под покровом снега, которым ее укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!$B$BЕсли тебе интересно узнать, что такое на самом деле этот праздник, поспрашивай историка Карника из лиги исследователей. Уверен, он будет очень удивлен, что кому-то история интереснее подарков.','Поговорите с историком Карником из Лиги исследователей в Стальгорне о празднике Зимнего Покрова.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повод для праздника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подарки, гости, угощение... чушь собачья!$B$BЭти гоблины искажают самую суть праздника Зимнего Покрова. Это время возрождения – земля спит под покровом снега, которым ее укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!$B$BЕсли тебе интересно узнать, что такое на самом деле этот праздник, поспрашивай историка Карника из лиги исследователей. Уверен, он будет очень удивлен, что кому-то история интереснее подарков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с историком Карником из Лиги исследователей в Стальгорне о празднике Зимнего Покрова.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (7063,'Праздник Зимнего Покрова','Если вам интересно побольше узнать о празднике Зимнего Покрова, прочтите эту книгу. Хотя я и думаю, что наше толкование легенды вполне верное, я все же ученый и буду рад, если мне удастся свести всю информацию воедино.$B$BКогда закончите, отнесите эту книгу королю Мурадину Бронзобороду. Я точно знаю: ему приятно будет услышать, что кто-то еще интересуется старинными легендами.','Прочтите книгу "Праздник Зимнего Покрова", узнайте побольше о происхождении праздника. Закончив читать книгу, отнесите ее королю Мурадину Бронзобороду в Стальгорн.','Добро пожаловать в королевство Стальгорн. Мне всегда по сердцу те, кто интересуется нашим королевством, его народом и его преданиями. Вы ведь ради этого явились ко мне?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Праздник Зимнего Покрова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если вам интересно побольше узнать о празднике Зимнего Покрова, прочтите эту книгу. Хотя я и думаю, что наше толкование легенды вполне верное, я все же ученый и буду рад, если мне удастся свести всю информацию воедино.$B$BКогда закончите, отнесите эту книгу королю Мурадину Бронзобороду. Я точно знаю: ему приятно будет услышать, что кто-то еще интересуется старинными легендами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите книгу "Праздник Зимнего Покрова", узнайте побольше о происхождении праздника. Закончив читать книгу, отнесите ее королю Мурадину Бронзобороду в Стальгорн.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать в королевство Стальгорн. Мне всегда по сердцу те, кто интересуется нашим королевством, его народом и его преданиями. Вы ведь ради этого явились ко мне?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7064,'Яблочко от яблоньки...','В глубинах Мародона живет злобное создание Хаоса, элементаль земли, принцесса Терадрас, находящаяся в родстве с древними богами. Когда-то, давным-давно, ее отыскал Зейтар, первый сын Кенария. Их... потомство зовется кентаврами. Благодарные потомки убили Зейтара, а его останки оказались во власти Терадрас. Я ищу того, кому хватит сил одолеть Терадрас и вернуть останки Зейтара в Каменный Коготь.','Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах.','Прекрасные новости, $N! Спасибо тебе!$B$BЯ поговорю с Марандисом и попрошу его о том, чтобы он осмотрел останки Зейтара. Но самую трудную часть ты $Gвыполнил:выполнила;!$B$BКогда мы отправились в путь, мне были вручены три вещи, чтобы вознаградить тех, кто будет помогать нам. Ты можешь выбрать одну из них.','Я бы предпочел сражаться в этой битве самостоятельно, но у нас нет других вариантов - нам нужны более могущественные, и расы Азерота, без сомнения, доказали, что они могут преодолеть такие вещи, работая вместе.','Вернитесь к Селендре на Побережье Сар\'Терис, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яблочко от яблоньки...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В глубинах Мародона живет злобное создание Хаоса, элементаль земли, принцесса Терадрас, находящаяся в родстве с древними богами. Когда-то, давным-давно, ее отыскал Зейтар, первый сын Кенария. Их... потомство зовется кентаврами. Благодарные потомки убили Зейтара, а его останки оказались во власти Терадрас. Я ищу того, кому хватит сил одолеть Терадрас и вернуть останки Зейтара в Каменный Коготь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте принцессу Терадрас и вернитесь к Селендре неподалеку от Деревни Ночных Охотников в Пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасные новости, $N! Спасибо тебе!$B$BЯ поговорю с Марандисом и попрошу его о том, чтобы он осмотрел останки Зейтара. Но самую трудную часть ты $Gвыполнил:выполнила;!$B$BКогда мы отправились в путь, мне были вручены три вещи, чтобы вознаградить тех, кто будет помогать нам. Ты можешь выбрать одну из них.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я бы предпочел сражаться в этой битве самостоятельно, но у нас нет других вариантов - нам нужны более могущественные, и расы Азерота, без сомнения, доказали, что они могут преодолеть такие вещи, работая вместе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Селендре на Побережье Сар\'Терис, что в Пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7065,'Яблочко от яблоньки...','В глубинах Мародона живет злобное создание Хаоса, элементаль земли, принцесса Терадрас, находящаяся в родстве с древними богами. Когда-то, давным-давно, ее отыскал Зейтар, первый сын Кенария. Их... потомство зовется кентаврами. Благодарные потомки убили Зейтара, а его останки оказались во власти Терадрас. Я ищу того, кому хватит сил одолеть Терадрас и вернуть останки Зейтара в Каменный Коготь.','Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши.','Отличные новости, $n! Спасибо!$B$BХотя мне жаль, что ты не смог принести останки Зейтара, кто я, чтобы оспаривать волю первенца Кенария? Может быть, кентавры сумеют преодолеть собственную кровожадность – будем надеяться на лучшее.$B$BМне было предписано предложить эти предметы в награду тому, кто сумеет помочь нам. Выбери любой из них.','Я чувствую тяжесть призывов к смертным расам, но у нас нет других вариантов. Расы Азерота без сомнения доказали, что могут преодолевать такие вещи, работая вместе, поэтому я прошу о помощи именно к ним.','Вернитесь к хранителю Марандису в Пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яблочко от яблоньки...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В глубинах Мародона живет злобное создание Хаоса, элементаль земли, принцесса Терадрас, находящаяся в родстве с древними богами. Когда-то, давным-давно, ее отыскал Зейтар, первый сын Кенария. Их... потомство зовется кентаврами. Благодарные потомки убили Зейтара, а его останки оказались во власти Терадрас. Я ищу того, кому хватит сил одолеть Терадрас и вернуть останки Зейтара в Каменный Коготь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте принцессу Терадрас и вернитесь к хранителю Марандису на Высоту Найджела в Пустоши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные новости, $n! Спасибо!$B$BХотя мне жаль, что ты не смог принести останки Зейтара, кто я, чтобы оспаривать волю первенца Кенария? Может быть, кентавры сумеют преодолеть собственную кровожадность – будем надеяться на лучшее.$B$BМне было предписано предложить эти предметы в награду тому, кто сумеет помочь нам. Выбери любой из них.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую тяжесть призывов к смертным расам, но у нас нет других вариантов. Расы Азерота без сомнения доказали, что могут преодолевать такие вещи, работая вместе, поэтому я прошу о помощи именно к ним.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Марандису в Пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (7066,'Семя Жизни','Несчастные кентавры – мои дети – пропадут без отца.$b$bОглянись – это место исполнено надежды и того, чему учил мой отец, Кенарий. И все это произошло от меня! Я не могу лишить их своей поддержки... хоть они и обратились против меня.$b$bУ меня есть к тебе просьба – я хочу успокоить своего брата. Возьми это... первое семя жизни, родившейся из моих останков. Скажи ему, что я не погиб, а мой дух ныне пребывает здесь. Уверен, он меня поймет.','Найдите в Лунной поляне Ремула и отдайте ему Семя Жизни.','От тебя несет скверной, как от большинства искателей приключений наших дней. Но ты отличаешься от остальных. О чем ты хочешь со мной поговорить? Я чую что-то знакомое, но не могу понять, что именно.$B$BПрошу тебя, скажи, почему ты хотел поговорить со мной?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семя Жизни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несчастные кентавры – мои дети – пропадут без отца.$b$bОглянись – это место исполнено надежды и того, чему учил мой отец, Кенарий. И все это произошло от меня! Я не могу лишить их своей поддержки... хоть они и обратились против меня.$b$bУ меня есть к тебе просьба – я хочу успокоить своего брата. Возьми это... первое семя жизни, родившейся из моих останков. Скажи ему, что я не погиб, а мой дух ныне пребывает здесь. Уверен, он меня поймет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Лунной поляне Ремула и отдайте ему Семя Жизни.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','От тебя несет скверной, как от большинства искателей приключений наших дней. Но ты отличаешься от остальных. О чем ты хочешь со мной поговорить? Я чую что-то знакомое, но не могу понять, что именно.$B$BПрошу тебя, скажи, почему ты хотел поговорить со мной?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (7067,'Инструкции кентавра-парии','Хотя меня изгнали из племени как еретика, меня поддерживает вера. Только ей я и живу. Впрочем, мне не исполнить предначертанное без посторонней помощи... Причем помощи чужака, а не кентавра.$b$bКто-то должен войти в священные залы Мародона – гробницы, которую защищает мой народ, допуская внутрь лишь избранных.$b$bЕсли ты $gсогласен:согласна; помочь мне, стоит только кивнуть. Я отдам тебе свиток с инструкциями. Прочти его и обдумай мои слова.','Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей.','Вот он, вот амулет! Теперь мне предстоит долгое дело объединения племен. Спасибо.$B$BВот, возьми это за услуги. Надеюсь, мы еще встретимся в совсем другой обстановке.','Вернитесь к кентавру-парии к Двум Колоссам, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Инструкции кентавра-парии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя меня изгнали из племени как еретика, меня поддерживает вера. Только ей я и живу. Впрочем, мне не исполнить предначертанное без посторонней помощи... Причем помощи чужака, а не кентавра.$b$bКто-то должен войти в священные залы Мародона – гробницы, которую защищает мой народ, допуская внутрь лишь избранных.$b$bЕсли ты $gсогласен:согласна; помочь мне, стоит только кивнуть. Я отдам тебе свиток с инструкциями. Прочти его и обдумай мои слова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите инструкции кентавра-парии, добудьте из Мародона амулет Соединения и верните его кентавру-парии из южной части Пустошей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот он, вот амулет! Теперь мне предстоит долгое дело объединения племен. Спасибо.$B$BВот, возьми это за услуги. Надеюсь, мы еще встретимся в совсем другой обстановке.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кентавру-парии к Двум Колоссам, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7068,'Фрагменты осколка сумрака','Сильна магия в святом месте для кентавров, священном Мародоне. Племена кентавров Пустошей готовы биться за эти места до последней капли крови, но куда им! Мы свое возьмем!$b$bСтупай в Мародон и найди там каменных тварей из осколков сумрака. Ты дашь Утель\'наю лиловые кристаллы, а уж он тебя не обидит!$b$bМеста там опасные, так что бери с собой друзей.','Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель\'наю в Оргриммар.','Ага, вот они. Вот, возьми один из этих предметов и ступай своей дорогой... у меня еще много дел.','Ну как, $Gнашел:нашла; кристаллы? Ритуалы силы, могущественные заклятья... Одним словом, эти осколки очень и очень нужны всем знатокам тайных искусств.','Вернитесь к Утель\'наю в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фрагменты осколка сумрака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сильна магия в святом месте для кентавров, священном Мародоне. Племена кентавров Пустошей готовы биться за эти места до последней капли крови, но куда им! Мы свое возьмем!$b$bСтупай в Мародон и найди там каменных тварей из осколков сумрака. Ты дашь Утель\'наю лиловые кристаллы, а уж он тебя не обидит!$b$bМеста там опасные, так что бери с собой друзей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их Утель\'наю в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, вот они. Вот, возьми один из этих предметов и ступай своей дорогой... у меня еще много дел.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, $Gнашел:нашла; кристаллы? Ритуалы силы, могущественные заклятья... Одним словом, эти осколки очень и очень нужны всем знатокам тайных искусств.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Утель\'наю в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (7069,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7070,'Фрагменты осколка сумрака','Я недавно начал испытания различных кристаллов и их магических свойств. Леди Праудмур позволила мне обратиться к путешественникам в Пустошах с просьбой отыскать там некое место, называющееся Мародон. В руинах храма поселились огромные каменные элементали, состоящие из лиловых кристаллов, которые я нарек осколками сумрака.$b$bЕсли ты решишь направиться в ту сторону и захватишь по пути несколько кристаллов, я буду очень признателен. Более того, я могу сделать тебе из них украшение.','Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей.','Ты уже побывал в Мараудоне? Понимаю, дело это опасное, но если ты достигнешь успеха, награда с лихвой окупит затраченные усилия.','Вернитесь к верховному магу Тервошу в Пылевые топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фрагменты осколка сумрака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я недавно начал испытания различных кристаллов и их магических свойств. Леди Праудмур позволила мне обратиться к путешественникам в Пустошах с просьбой отыскать там некое место, называющееся Мародон. В руинах храма поселились огромные каменные элементали, состоящие из лиловых кристаллов, которые я нарек осколками сумрака.$b$bЕсли ты решишь направиться в ту сторону и захватишь по пути несколько кристаллов, я буду очень признателен. Более того, я могу сделать тебе из них украшение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите в Мародоне 10 фрагментов осколков сумрака и отнесите их верховному магу Тервошу в Терамор на побережье Пылевых топей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже побывал в Мараудоне? Понимаю, дело это опасное, но если ты достигнешь успеха, награда с лихвой окупит затраченные усилия.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Тервошу в Пылевые топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7081,'Кладбища Альтеракской долины','Кладбища в Альтеракской долине представляют собой очень большую ценность. И Орда, и Альянс свирепо дерутся за право обладать этими сакральными местами. $GГотов:Готова; ли ты вступить в эту схватку, $n?$B$BЯ хочу, чтобы ты $gзахватил:захватила; кладбище неприятеля. Найди кладбище с вымпелом Орды и вытащи из земли этот вымпел! Вот и все, задание выполнено.$B$BЕсли не сложно, можешь покараулить захваченное кладбище несколько минут, до прибытия наших войск.','Захватите кладбище, затем возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.','Неплохо! Кладбища – необходимые точки, которые мы должны контролировать в Альтеракской долине. Так, возвращайся в битву и если увидишь кладбище под контролем Орды... ты знаешь что делать!','$N, ты еще не захватил кладбище. Возвращайся, когда задание будет выполнено!','Вернитесь к сержанту Даргену Грозовой Вершине на Возвышенность Гэвина в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кладбища Альтеракской долины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кладбища в Альтеракской долине представляют собой очень большую ценность. И Орда, и Альянс свирепо дерутся за право обладать этими сакральными местами. $GГотов:Готова; ли ты вступить в эту схватку, $n?$B$BЯ хочу, чтобы ты $gзахватил:захватила; кладбище неприятеля. Найди кладбище с вымпелом Орды и вытащи из земли этот вымпел! Вот и все, задание выполнено.$B$BЕсли не сложно, можешь покараулить захваченное кладбище несколько минут, до прибытия наших войск.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Захватите кладбище, затем возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо! Кладбища – необходимые точки, которые мы должны контролировать в Альтеракской долине. Так, возвращайся в битву и если увидишь кладбище под контролем Орды... ты знаешь что делать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты еще не захватил кладбище. Возвращайся, когда задание будет выполнено!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Даргену Грозовой Вершине на Возвышенность Гэвина в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7082,'Кладбища Альтеракской долины','Линия фронта в Альтеракской долине постоянно изменяется. Мы отступаем и снова отвоевываем территории в смертельной схватке с врагом. Особо яростные сражения идут за кладбища, $n.$B$BЯ приказываю тебе атаковать кладбище Альянса! Найди кладбище со знаменем Альянса в центре и вырви древко из земли!$B$BНа этом задание будет выполнено. Но тебе нужно будет подождать некоторое время, пока не придут наши войска.','Хорошо сделано, $N! Теперь духам наших врагов придется поблуждать... ха-ха-ха.','Атакуйте кладбище, принадлежащее Альянсу!','Вернитесь к капралу Тике Кровавому Рыку в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кладбища Альтеракской долины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Линия фронта в Альтеракской долине постоянно изменяется. Мы отступаем и снова отвоевываем территории в смертельной схватке с врагом. Особо яростные сражения идут за кладбища, $n.$B$BЯ приказываю тебе атаковать кладбище Альянса! Найди кладбище со знаменем Альянса в центре и вырви древко из земли!$B$BНа этом задание будет выполнено. Но тебе нужно будет подождать некоторое время, пока не придут наши войска.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо сделано, $N! Теперь духам наших врагов придется поблуждать... ха-ха-ха.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Атакуйте кладбище, принадлежащее Альянсу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капралу Тике Кровавому Рыку в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7101,'Башни и бункеры','Башни и бункеры – основные защитные сооружения, так что все они должны быть нашими! Твое следующее задание – захват вражеского бункера.$B$BЗайди в бункер Альянса – над ним развевается их флаг. Внутри ты увидишь знамя. Сними его, и на его месте появится белое знамя Орды. Дело сделано!$B$BБольше ничего не нужно, но если ты немного подождешь и не дашь Альянсу отбить бункер обратно, то он самоуничтожится!','Я слышала, задание успешно выполнено! Это хорошо...$B$BТеперь наши войска смогут безнаказанно продвинуться вперед и показать Альянсу, что ему не место в Альтеракской долине!','Ты еще не $Gатаковал:атаковала; бункер, $N! Ты ждешь, что другие заявят о твоей славе?','Вернитесь к капралу Тике Кровавому Рыку в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башни и бункеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Башни и бункеры – основные защитные сооружения, так что все они должны быть нашими! Твое следующее задание – захват вражеского бункера.$B$BЗайди в бункер Альянса – над ним развевается их флаг. Внутри ты увидишь знамя. Сними его, и на его месте появится белое знамя Орды. Дело сделано!$B$BБольше ничего не нужно, но если ты немного подождешь и не дашь Альянсу отбить бункер обратно, то он самоуничтожится!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я слышала, задание успешно выполнено! Это хорошо...$B$BТеперь наши войска смогут безнаказанно продвинуться вперед и показать Альянсу, что ему не место в Альтеракской долине!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты еще не $Gатаковал:атаковала; бункер, $N! Ты ждешь, что другие заявят о твоей славе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капралу Тике Кровавому Рыку в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7102,'Башни и бункеры','Башни и бункеры – основные защитные сооружения, так что у нас их должно быть как можно больше! Я приказываю тебе атаковать вражескую башню или бункер в Альтеракской долине.$B$BЗайди в бункер Орды – над ним развевается их флаг. Внутри ты увидишь вымпел. Сними его, и на его месте появится белое знамя Альянса. Дело сделано!$B$BНо на этом задание еще не закончено. Если ты продержишься рядом с башней некоторое время, чтобы ее не захватила Орда, то она разрушится!','Уничтожьте вымпел на вражеской башне или бункере и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.','Я получил отчет о том, что ты обезвредил вражеский вымпел. Отлично, $N! Теперь мы перенесем линию фронта на вражескую территорию.','Ты еще не $Gатаковал:атаковала; башню, $N! Чего же ты ждешь?','Вернитесь к сержанту Даргену Грозовой Вершине на Возвышенность Гэвина в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Башни и бункеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Башни и бункеры – основные защитные сооружения, так что у нас их должно быть как можно больше! Я приказываю тебе атаковать вражескую башню или бункер в Альтеракской долине.$B$BЗайди в бункер Орды – над ним развевается их флаг. Внутри ты увидишь вымпел. Сними его, и на его месте появится белое знамя Альянса. Дело сделано!$B$BНо на этом задание еще не закончено. Если ты продержишься рядом с башней некоторое время, чтобы ее не захватила Орда, то она разрушится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте вымпел на вражеской башне или бункере и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я получил отчет о том, что ты обезвредил вражеский вымпел. Отлично, $N! Теперь мы перенесем линию фронта на вражескую территорию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты еще не $Gатаковал:атаковала; башню, $N! Чего же ты ждешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Даргену Грозовой Вершине на Возвышенность Гэвина в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7121,'Интендант','$n, интендант велел отправлять новых рекрутов к нему. Нам нужны припасы, которые хранятся в тайниках на рудниках Альтерака, так что, скорее всего, он отправит тебя за ними.$B$BСтупай по этой дороге на запад, там найдешь интенданта.','Поговорите с интендантом клана Грозовой Вершины.','Приятно видеть новых солдат, $n, но если повезет, ты скоро отправишься на задание и перестанешь быть новичком.$B$BПодойди ко мне через минутку, я дам тебе задание...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Интендант',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, интендант велел отправлять новых рекрутов к нему. Нам нужны припасы, которые хранятся в тайниках на рудниках Альтерака, так что, скорее всего, он отправит тебя за ними.$B$BСтупай по этой дороге на запад, там найдешь интенданта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с интендантом клана Грозовой Вершины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно видеть новых солдат, $n, но если повезет, ты скоро отправишься на задание и перестанешь быть новичком.$B$BПодойди ко мне через минутку, я дам тебе задание...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7122,'Захват рудника','Рудники в Альтеракской долине – нечто большее, чем обычные сырьевые ресурсы. И Грозовая Вершина, и клан Северного Волка хранят на рудниках свои припасы. Одни – на Железном руднике, другие – на руднике Ледяного Зуба. Неплохо было бы захватить чужие припасы!$B$BЗахвати рудник и возвращайся ко мне. Найди рудник, который никому не принадлежит, и убей того, кто там главный. После этого рудник перейдет к нам, и мы вышлем войска для его охраны.','Захватите рудник, который не принадлежит Грозовой Вершине, и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.','Отличная работа, $N!Теперь, когда мы контролируем рудник, нам будет намного проще добывать и вывозить ресурсы.','Ты еще не $Gзахватил:захватила; шахту, $N!$B$BПосле того, как мы возьмем под контроль шахту, будет намного легче добывать минералы и припасы из нее.','Вернитесь к сержанту Даргену Грозовой Вершине на Возвышенность Гэвина в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват рудника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рудники в Альтеракской долине – нечто большее, чем обычные сырьевые ресурсы. И Грозовая Вершина, и клан Северного Волка хранят на рудниках свои припасы. Одни – на Железном руднике, другие – на руднике Ледяного Зуба. Неплохо было бы захватить чужие припасы!$B$BЗахвати рудник и возвращайся ко мне. Найди рудник, который никому не принадлежит, и убей того, кто там главный. После этого рудник перейдет к нам, и мы вышлем войска для его охраны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Захватите рудник, который не принадлежит Грозовой Вершине, и возвращайтесь к сержанту Даргену Грозовой Вершине в Альтеракские горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N!Теперь, когда мы контролируем рудник, нам будет намного проще добывать и вывозить ресурсы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты еще не $Gзахватил:захватила; шахту, $N!$B$BПосле того, как мы возьмем под контроль шахту, будет намного легче добывать минералы и припасы из нее.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Даргену Грозовой Вершине на Возвышенность Гэвина в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7123,'Разговор с интендантом','$n, интендант клана Северного Волка набирает рекрутов для задания на рудниках Альтеракской долины. Поговори с ним, он расскажет тебе все подробно.$B$BСтупай в бункер по западной дороге, зайди в западный вход, там ты и найдешь интенданта.','Поговорите с интендантом клана Северного Волка.','Привет, $N! Приятно видеть $Gтакого:такую;, как ты, $C. $GКоторый:Которая; рвется помочь родной Орде! Поговори со мной снова, я дам тебе задачу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с интендантом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, интендант клана Северного Волка набирает рекрутов для задания на рудниках Альтеракской долины. Поговори с ним, он расскажет тебе все подробно.$B$BСтупай в бункер по западной дороге, зайди в западный вход, там ты и найдешь интенданта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с интендантом клана Северного Волка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет, $N! Приятно видеть $Gтакого:такую;, как ты, $C. $GКоторый:Которая; рвется помочь родной Орде! Поговори со мной снова, я дам тебе задачу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7124,'Захват рудника','Битва, разгоревшаяся на землях Альтеракской долины, идет и за рудники – Железный и Ледяного Зуба. Они богаты сырьем, и к тому же их можно использовать для хранения припасов.$B$BПомоги нам, $n! Захвати один из этих рудников, во имя Орды! Отправляйся на рудник, который принадлежит нашим врагам, и убей того, кто там главный. Как только ты захватишь рудник, мы вышлем войска, чтобы взять его под охрану.','Ты $Gзахватил:захватила; рудник! Мы вышлем туда охрану и сможем добывать сырье и хранить припасы.$B$BОтлично, $N. Ты $Gоказал:оказала; Орде неоценимую помощь в ведении боевых действий!','Ты еще не $Gзахватил:захватила; мину, $N! Найдите того, кого мы не контролируем, и победите его лидера!','Вернитесь к капралу Тике Кровавому Рыку в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват рудника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Битва, разгоревшаяся на землях Альтеракской долины, идет и за рудники – Железный и Ледяного Зуба. Они богаты сырьем, и к тому же их можно использовать для хранения припасов.$B$BПомоги нам, $n! Захвати один из этих рудников, во имя Орды! Отправляйся на рудник, который принадлежит нашим врагам, и убей того, кто там главный. Как только ты захватишь рудник, мы вышлем войска, чтобы взять его под охрану.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gзахватил:захватила; рудник! Мы вышлем туда охрану и сможем добывать сырье и хранить припасы.$B$BОтлично, $N. Ты $Gоказал:оказала; Орде неоценимую помощь в ведении боевых действий!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты еще не $Gзахватил:захватила; мину, $N! Найдите того, кого мы не контролируем, и победите его лидера!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капралу Тике Кровавому Рыку в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (7141,'Битва за Альтерак','Лига исследователей уверена, что в Альтеракской долине есть артефакты, но клан Северного Волка не позволяет нам проводить здесь исследования. Не дадим Орде задушить наши благородные научные начинания! Уничтожь генерала Северного Волка, Дрек\'Тара. Без него орки ничего сделать не смогут.$B$BДрек\'Тара можно найти в крепости Северного Волка, на юге Альтеракской долины. Убей его и возвращайся.','Отправляйтесь в Альтеракскую долину, сразитесь с генералом Орды Дрек\'Таром и возвращайтесь к геологу Камнетерке в Альтеракские горы.','Великолепно, $N! Орда не скоро оправится от смерти генерала, так что мы можем начинать наши исследования!','Ступай, $N. Отправляйтесь в Альтеракскую долину и победите генерала орков!','Нанесите поражение Дрек\'Тару','Вернитесь к геологу Камнетерке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Альтерак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лига исследователей уверена, что в Альтеракской долине есть артефакты, но клан Северного Волка не позволяет нам проводить здесь исследования. Не дадим Орде задушить наши благородные научные начинания! Уничтожь генерала Северного Волка, Дрек\'Тара. Без него орки ничего сделать не смогут.$B$BДрек\'Тара можно найти в крепости Северного Волка, на юге Альтеракской долины. Убей его и возвращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Альтеракскую долину, сразитесь с генералом Орды Дрек\'Таром и возвращайтесь к геологу Камнетерке в Альтеракские горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, $N! Орда не скоро оправится от смерти генерала, так что мы можем начинать наши исследования!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ступай, $N. Отправляйтесь в Альтеракскую долину и победите генерала орков!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Нанесите поражение Дрек\'Тару',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Камнетерке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (7142,'Битва за Альтерак','Дворфы Грозовой Вершины вместе со своими союзниками вторглись в Альтеракскую долину, и мы должны выкинуть их отсюда! Если мы хотим выиграть битву за Альтерак наверняка, то нам нужно уничтожить их генерала, Вандара Грозовую Вершину!$B$BЕго можно найти в Дун Болдаре, на севере Альтеракской долины.$B$BУбей его, $n, и возвращайся обратно ко мне.','Отправляйтесь в Альтеракскую долину и убейте генерала дворфов, Вандара Грозовую Вершину. После этого возвращайтесь к Вогге Смертобою в Альтеракские горы.','Убейте генерала Вандара Грозовую Вершину','Вернитесь к Вогге Смертобою в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Альтерак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дворфы Грозовой Вершины вместе со своими союзниками вторглись в Альтеракскую долину, и мы должны выкинуть их отсюда! Если мы хотим выиграть битву за Альтерак наверняка, то нам нужно уничтожить их генерала, Вандара Грозовую Вершину!$B$BЕго можно найти в Дун Болдаре, на севере Альтеракской долины.$B$BУбей его, $n, и возвращайся обратно ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Альтеракскую долину и убейте генерала дворфов, Вандара Грозовую Вершину. После этого возвращайтесь к Вогге Смертобою в Альтеракские горы.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Убейте генерала Вандара Грозовую Вершину',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вогге Смертобою в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7161,'Арена испытаний','Приветствую, |3-6($c). Много времени прошло с тех пор, когда мы в последний раз внимали зову битвы. Трудно пробудить давно забытые чувства, но если они проснулись, обязательно прольется кровь. Ярость боя зовет нас...$B$BВ Альтеракской долине все новички должны пройти боевое крещение.$B$BГлубоко в пещерах гноллов из стаи Дикой Лапы хранится знамя клана Северного Волка. Отправляйся туда и добудь его. Возвращайся ко мне со знаменем, и получишь знак отличия новобранца.','Отправляйтесь в пещеру Дикой Лапы, расположенную на юго-востоке от основной базы в Альтеракской долине, и добудьте знамя Северного Волка. Отнесите знамя Северного Волка воеводе Лаггронду.','Вернитесь к воеводе Лаггронду в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арена испытаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, |3-6($c). Много времени прошло с тех пор, когда мы в последний раз внимали зову битвы. Трудно пробудить давно забытые чувства, но если они проснулись, обязательно прольется кровь. Ярость боя зовет нас...$B$BВ Альтеракской долине все новички должны пройти боевое крещение.$B$BГлубоко в пещерах гноллов из стаи Дикой Лапы хранится знамя клана Северного Волка. Отправляйся туда и добудь его. Возвращайся ко мне со знаменем, и получишь знак отличия новобранца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в пещеру Дикой Лапы, расположенную на юго-востоке от основной базы в Альтеракской долине, и добудьте знамя Северного Волка. Отнесите знамя Северного Волка воеводе Лаггронду.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воеводе Лаггронду в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7162,'Арена испытаний','Ты $gприбыл:прибыла; вовремя, |3-6($c). Эти дикари из клана Северного Волка ни в какую не желают сдаваться! Ничего, мы им покажем, на что способна Грозовая Вершина. Они склонятся перед нашей мощью!$B$BПеред тем, как отправиться в бой, ты $gдолжен:должна; вступить в ряды Грозовой Вершины.$B$BК юго-западу от Дун Болдара находится пещера Ледяного Крыла. В ее недрах хранится знамя Грозовой Вершины. Отправляйся туда и добудь его. Принеси знамя мне, и получишь отличительный знак новобранца.','Отправляйтесь в пещеру Ледяного Крыла, которая расположена в Альтеракской долине, на юго-западе от Дун Болдара, и добудьте знамя Грозовой Вершины. Отдайте знамя лейтенанту Хаггердину в Альтеракских горах.','Прими этот знак и носи его с честью, $N. Это символ твоего положения в Грозовой Вершине. Когда ты приобретешь уважение Грозовой Вершины, я выдам тебе другой знак.$B$BВозможно, в один прекрасный день ты станешь легендарным воителем и получишь Око Командования.','В этих землях следует опасаться гарпий, $C. Они не задумываясь вырвут тебе глотку.','Вернитесь к лейтенанту Хаггердину на холм Дарроу, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арена испытаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gприбыл:прибыла; вовремя, |3-6($c). Эти дикари из клана Северного Волка ни в какую не желают сдаваться! Ничего, мы им покажем, на что способна Грозовая Вершина. Они склонятся перед нашей мощью!$B$BПеред тем, как отправиться в бой, ты $gдолжен:должна; вступить в ряды Грозовой Вершины.$B$BК юго-западу от Дун Болдара находится пещера Ледяного Крыла. В ее недрах хранится знамя Грозовой Вершины. Отправляйся туда и добудь его. Принеси знамя мне, и получишь отличительный знак новобранца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в пещеру Ледяного Крыла, которая расположена в Альтеракской долине, на юго-западе от Дун Болдара, и добудьте знамя Грозовой Вершины. Отдайте знамя лейтенанту Хаггердину в Альтеракских горах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прими этот знак и носи его с честью, $N. Это символ твоего положения в Грозовой Вершине. Когда ты приобретешь уважение Грозовой Вершины, я выдам тебе другой знак.$B$BВозможно, в один прекрасный день ты станешь легендарным воителем и получишь Око Командования.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В этих землях следует опасаться гарпий, $C. Они не задумываясь вырвут тебе глотку.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Хаггердину на холм Дарроу, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7163,'Награда найдет героя','<Воевода Лаггронд отдает вам салют.>$B$BПришло твое время, $N. Ты столько сделал для клана Северного Волка, что можешь считаться не просто солдатом, а настоящим другом.$B$BОтлично! Давай свой знак новобранца.','Вернитесь к воеводе Лаггронду в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда найдет героя',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Воевода Лаггронд отдает вам салют.>$B$BПришло твое время, $N. Ты столько сделал для клана Северного Волка, что можешь считаться не просто солдатом, а настоящим другом.$B$BОтлично! Давай свой знак новобранца.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воеводе Лаггронду в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7164,'Уважение клана','Рад снова тебя видеть, $N. Не ожидал, что ты вернешься. Но вот, ты $Gзарекомендовал:зарекомендовала; себя как отважный и доблестный воитель клана Северного Волка.$B$BПришло время получить новое звание, $N. А с ним и новый знак отличия.$B$BДай мне свой знак.','Вернитесь к воеводе Лаггронду в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уважение клана',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рад снова тебя видеть, $N. Не ожидал, что ты вернешься. Но вот, ты $Gзарекомендовал:зарекомендовала; себя как отважный и доблестный воитель клана Северного Волка.$B$BПришло время получить новое звание, $N. А с ним и новый знак отличия.$B$BДай мне свой знак.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воеводе Лаггронду в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7165,'Заслуженное почтение','Ты $Gубил:убила; так много врагов, что реки покраснели от крови. Твоя стойкость в бою достойна всяческих похвал. Я верю, ты приведешь нашу армию к великим победам. Ты $Gзаслужил:заслужила; новое звание.$B$BПредъяви свой знак отличия.','Вернитесь к воеводе Лаггронду в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заслуженное почтение',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gубил:убила; так много врагов, что реки покраснели от крови. Твоя стойкость в бою достойна всяческих похвал. Я верю, ты приведешь нашу армию к великим победам. Ты $Gзаслужил:заслужила; новое звание.$B$BПредъяви свой знак отличия.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воеводе Лаггронду в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7166,'Легендарные герои','Скоро ты окинешь бдительным оком все поля сражений! Ты примешь командование Альтеракской долиной и всеми ее войсками!','Я чувствую исходящие от тебя мощь и силу, $C. Клан Северного Волка восхищен твоим героизмом. Мы знаем, что враги трепещут при одном упоминании твоего имени.$B$BВстань, $Gвеликий:великая; $Gвоитель:воительница; Северного Волка. Встань и прими хвалу!$B$BДай мне свой знак отличия.','Вернитесь к воеводе Лаггронду в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легендарные герои',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Скоро ты окинешь бдительным оком все поля сражений! Ты примешь командование Альтеракской долиной и всеми ее войсками!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую исходящие от тебя мощь и силу, $C. Клан Северного Волка восхищен твоим героизмом. Мы знаем, что враги трепещут при одном упоминании твоего имени.$B$BВстань, $Gвеликий:великая; $Gвоитель:воительница; Северного Волка. Встань и прими хвалу!$B$BДай мне свой знак отличия.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воеводе Лаггронду в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7167,'Око Командования','Направь силу своего знака, и пусть враги услышат твой голос. Мощь Орды несокрушима!','Дрек\'Тар наслышан о твоих подвигах. В Калимдоре только и говорят, что о твоем героизме. Сам Вождь гордится тем, что ты $Gсделал:сделала; для нашего клана.$B$BТы $Gзаслужил:заслужила; Око Командования.$B$BПредъяви свой знак отличия, командир $N.$B$B<Воевода Лаггронд отдает честь.>','Вернитесь к воеводе Лаггронду в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око Командования',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Направь силу своего знака, и пусть враги услышат твой голос. Мощь Орды несокрушима!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дрек\'Тар наслышан о твоих подвигах. В Калимдоре только и говорят, что о твоем героизме. Сам Вождь гордится тем, что ты $Gсделал:сделала; для нашего клана.$B$BТы $Gзаслужил:заслужила; Око Командования.$B$BПредъяви свой знак отличия, командир $N.$B$B<Воевода Лаггронд отдает честь.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воеводе Лаггронду в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7168,'Награда найдет героя','Пусть наши враги видят, солдат какого ранга нанес им удар! Сражайся во славу Грозовой Вершины!','Жизнь многих заканчивается раньше, чем они получают то, чего заслуживают. Ты $Gпоказал:показала; себя образцовым солдатом, $C. Время пришло.$B$BДай мне свой отличительный знак.','Вернитесь к лейтенанту Хаггердину в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда найдет героя',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть наши враги видят, солдат какого ранга нанес им удар! Сражайся во славу Грозовой Вершины!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Жизнь многих заканчивается раньше, чем они получают то, чего заслуживают. Ты $Gпоказал:показала; себя образцовым солдатом, $C. Время пришло.$B$BДай мне свой отличительный знак.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Хаггердину в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7169,'Уважение Стражи','Сам король наслышан о твоих подвигах на поле брани, $C. Продолжай с честью нести стражу Грозовой Вершины!','Крепость полна слухами о твоих подвигах на Поле брани. Ты $Gнанес:нанесла; нашим врагам могучий удар, от которого они не скоро оправятся. Ты $Gзаслужил:заслужила; уважение Грозовой Вершины.','Вернитесь к лейтенанту Хаггердину в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уважение Стражи',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сам король наслышан о твоих подвигах на поле брани, $C. Продолжай с честью нести стражу Грозовой Вершины!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Крепость полна слухами о твоих подвигах на Поле брани. Ты $Gнанес:нанесла; нашим врагам могучий удар, от которого они не скоро оправятся. Ты $Gзаслужил:заслужила; уважение Грозовой Вершины.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Хаггердину в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7170,'Заслуженное почтение','Когда мы в первый раз встретились, я и не мог подумать, что ты будущий герой. Так держать!','Ответь мне, $N. Видишь ли ты страх в глазах своих врагов? Они разбегаются в панике при виде тебя? Должно быть, понимают, что у них нет ни шанса.$B$BТы $Gзаслужил:заслужила; почтительное отношение Стражи. Дай мне свой знак отличия.','Вернитесь к лейтенанту Хаггердину в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заслуженное почтение',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда мы в первый раз встретились, я и не мог подумать, что ты будущий герой. Так держать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ответь мне, $N. Видишь ли ты страх в глазах своих врагов? Они разбегаются в панике при виде тебя? Должно быть, понимают, что у них нет ни шанса.$B$BТы $Gзаслужил:заслужила; почтительное отношение Стражи. Дай мне свой знак отличия.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Хаггердину в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7171,'Легендарные герои','Вскоре, все поле битвы будет под твоим присмотром. Командование долины и ее воска будут твоими!','Предо мной стоит $Gвеликий:великая; $Gвоитель:воительница; Альянса!$B$B<Лейтенант Мурп отдает салют.>$B$BНемногие в Грозовой Вершине удостоены такого ранга. Я видел, как ты сокрушаешь врагов. Один твой взгляд повергает их в трепет. Когда ты вступаешь в бой, в сердцах наших солдат загорается надежда.$B$BДай мне свой знак отличия.','Вернитесь к лейтенанту Хаггердину в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легендарные герои',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вскоре, все поле битвы будет под твоим присмотром. Командование долины и ее воска будут твоими!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Предо мной стоит $Gвеликий:великая; $Gвоитель:воительница; Альянса!$B$B<Лейтенант Мурп отдает салют.>$B$BНемногие в Грозовой Вершине удостоены такого ранга. Я видел, как ты сокрушаешь врагов. Один твой взгляд повергает их в трепет. Когда ты вступаешь в бой, в сердцах наших солдат загорается надежда.$B$BДай мне свой знак отличия.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Хаггердину в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7172,'Око Командования','Это вы, кто должен привести войска к победе, командир! Солдаты под вашим командованием. Они будут следовать вашим приказам.!','Пусть они услышат тебя, командир $N! Пусть познают, что такое страх. Покажи им силу Грозовой Вершины!$B$BПредъяви свой знак отличия.','Вернитесь к лейтенанту Хаггердину в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око Командования',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это вы, кто должен привести войска к победе, командир! Солдаты под вашим командованием. Они будут следовать вашим приказам.!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пусть они услышат тебя, командир $N! Пусть познают, что такое страх. Покажи им силу Грозовой Вершины!$B$BПредъяви свой знак отличия.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Хаггердину в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7181,'Легенда о Корраке','Вторжение Грозовой Вершины – это не единственная угроза в этих землях, солдат. Война в долине ведется на два фронта. Тролли-канибалы из племени Ледяной Секиры тоже представляют собой силу, с которой надо считаться.$B$BИх предводитель – Коррак Кровопуск – жестокая и коварная тварь.$B$BУбийство Коррака нанесло бы непоправимый удар племени Ледяной Секиры. Убей его и получи награду!','Согласно легенде, вождь могущественного племени троллей Ледяной Секиры периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины.$B$BЕсли Коррак появится, убейте его и возвращайтесь к воеводе Лаггронду.','Вернитесь к воеводе Лаггронду в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легенда о Корраке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вторжение Грозовой Вершины – это не единственная угроза в этих землях, солдат. Война в долине ведется на два фронта. Тролли-канибалы из племени Ледяной Секиры тоже представляют собой силу, с которой надо считаться.$B$BИх предводитель – Коррак Кровопуск – жестокая и коварная тварь.$B$BУбийство Коррака нанесло бы непоправимый удар племени Ледяной Секиры. Убей его и получи награду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Согласно легенде, вождь могущественного племени троллей Ледяной Секиры периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины.$B$BЕсли Коррак появится, убейте его и возвращайтесь к воеводе Лаггронду.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воеводе Лаггронду в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7201,'Последний элемент','У меня есть работа для тех, кто не боится заглянуть в глубины, $n. $B$BКлан Черного Железа научился создавать чрезвычайно мощных големов. $B$BИсходя из отчетов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу. $B$BПодумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют... Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без нее можешь не возвращаться! Награда будет сопоставима с затраченными усилиями.','Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лягроб также бормотала что-то про элементалей.','Прекрасно! Я пошлю их с курьером в Подгород, сейчас же! Тебе же – даю твою оплату. А теперь, убирайся!','Покажи мне их!','Вернитесь к темному магу Вивиане Лягроб в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний элемент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть работа для тех, кто не боится заглянуть в глубины, $n. $B$BКлан Черного Железа научился создавать чрезвычайно мощных големов. $B$BИсходя из отчетов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу. $B$BПодумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют... Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без нее можешь не возвращаться! Награда будет сопоставима с затраченными усилиями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Глубины Черной горы и добудьте 10 мер сущности Стихий. Стоит начать поиски с големов и их создателей. Вивиан Лягроб также бормотала что-то про элементалей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Я пошлю их с курьером в Подгород, сейчас же! Тебе же – даю твою оплату. А теперь, убирайся!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Покажи мне их!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному магу Вивиане Лягроб в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7202,'Коррак Кровопуск','Племя Ледяной Секиры, местные аборигены, имеют скверную привычку украшать свой стол блюдами из мяса наших солдат.$B$BНичего, мы им покажем, как с нами связываться!$B$BНам удалось добыть книгу, в которой записаны имена не только их знати, но и самого вождя, которое они тщательно скрывают! Его зовут Коррак Кровопуск.$B$BСмерть Коррака – это смерть всего племени Ледяной Секиры! Убей его и возвращайся.','Согласно легенде, вождь могущественного племени троллей Ледяной Секиры периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины.$B$BЕсли вам удастся найти Коррака, убейте его и возвращайтесь к лейтенанту Хаггердину в Альтеракские горы.','Вернитесь к лейтенанту Хаггердину на холм Дарроу, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коррак Кровопуск',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Ледяной Секиры, местные аборигены, имеют скверную привычку украшать свой стол блюдами из мяса наших солдат.$B$BНичего, мы им покажем, как с нами связываться!$B$BНам удалось добыть книгу, в которой записаны имена не только их знати, но и самого вождя, которое они тщательно скрывают! Его зовут Коррак Кровопуск.$B$BСмерть Коррака – это смерть всего племени Ледяной Секиры! Убей его и возвращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Согласно легенде, вождь могущественного племени троллей Ледяной Секиры периодически появляется на поле боя, внося хаос и опустошение в жизнь обитателей Альтеракской долины.$B$BЕсли вам удастся найти Коррака, убейте его и возвращайтесь к лейтенанту Хаггердину в Альтеракские горы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Хаггердину на холм Дарроу, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (7221,'Разговор с геологом Камнетеркой','А, $n, с докладом, да? Отлично, Грозовая Вершина должна использовать всех, кто годится хоть на что-нибудь.$B$BПоговори с геологом Камнетеркой в Дун Болдаре. Она как раз набирает добровольцев для очень важного задания на вражеской территории. Ты найдешь ее в гарнизоне Дун Болдара, внизу.$B$BСмотри внимательно, когда будешь пробираться через Дун Болдар. Для |3-1($c), $gкоторый:которая:c; не чурается работы, здесь найдется много дел.','Поговорите с геологом Камнетеркой в гарнизоне Дун Болдара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с геологом Камнетеркой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $n, с докладом, да? Отлично, Грозовая Вершина должна использовать всех, кто годится хоть на что-нибудь.$B$BПоговори с геологом Камнетеркой в Дун Болдаре. Она как раз набирает добровольцев для очень важного задания на вражеской территории. Ты найдешь ее в гарнизоне Дун Болдара, внизу.$B$BСмотри внимательно, когда будешь пробираться через Дун Болдар. Для |3-1($c), $gкоторый:которая:c; не чурается работы, здесь найдется много дел.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с геологом Камнетеркой в гарнизоне Дун Болдара.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (7222,'Разговор с Воггой Смертобоем','$C? Отлично! Рады видеть тебя в Альтераке, $n. Дворфы и их союзники вторглись в нашу долину, так что Орда приветствует каждого, кто решил вступить в праведный бой!$B$BПоговори с Воггой Смертобоем. Он как раз набирает агентов для важного задания в крепости Альянса в Альтеракской долине!$B$BВоггу можно найти в крепости Северного Волка.','Поговорите с Воггой в крепости Северного Волка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Воггой Смертобоем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C? Отлично! Рады видеть тебя в Альтераке, $n. Дворфы и их союзники вторглись в нашу долину, так что Орда приветствует каждого, кто решил вступить в праведный бой!$B$BПоговори с Воггой Смертобоем. Он как раз набирает агентов для важного задания в крепости Альянса в Альтеракской долине!$B$BВоггу можно найти в крепости Северного Волка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Воггой в крепости Северного Волка.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7223,'Обломки брони','В Альтеракской долине часто гремят сражения, и поставок из Стальгорна для нужд наших войск недостаточно.$B$BЕсли ты найдешь на поле боя обломки брони, приноси их мне, они нам пригодятся.','Принесите 20 обломков брони Мурготу Подземной Кузне в Дун Болдар.','Это неплохие образчики, $N. Я могу перековать их на новую экипировку для наших воинов.$B$BЕсли припасов у меня окажется достаточно, может, наши опытные воины смогут выйти на поле боя!','Мне нужно больше обломков брони, $N! У тебя есть еще?','Вернитесь к Мурготу Подземной Кузне в Дун Болдар, что в Альтеракской долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обломки брони',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Альтеракской долине часто гремят сражения, и поставок из Стальгорна для нужд наших войск недостаточно.$B$BЕсли ты найдешь на поле боя обломки брони, приноси их мне, они нам пригодятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 обломков брони Мурготу Подземной Кузне в Дун Болдар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это неплохие образчики, $N. Я могу перековать их на новую экипировку для наших воинов.$B$BЕсли припасов у меня окажется достаточно, может, наши опытные воины смогут выйти на поле боя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно больше обломков брони, $N! У тебя есть еще?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мурготу Подземной Кузне в Дун Болдар, что в Альтеракской долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7224,'Вражеский трофей','Если найдешь на поле боя обломки вражеских доспехов, неси их мне. Из них выйдет отличная броня для наших собственных войск!','Принесите 20 обломков брони кузнецу Регзару в деревню Северного Волка.','Вернитесь к кузнецу Регзару в Деревню Северного Волка, что в Альтеракской долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вражеский трофей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если найдешь на поле боя обломки вражеских доспехов, неси их мне. Из них выйдет отличная броня для наших собственных войск!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 обломков брони кузнецу Регзару в деревню Северного Волка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кузнецу Регзару в Деревню Северного Волка, что в Альтеракской долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7241,'Защита клана Северного Волка','Издалека доносится рокот барабанов войны, |3-6($c). Клан твоего вождя подвергается атакам презренных дворфов клана Грозовой Вершины из Стальгорна. $b$bСудя по твоему виду, можно решить, что ты $Gзакален в битвах и готов:закалена в битвах и готова; постоять за дело клана Северного Волка. $b$bА сейчас тебе предстоит сделать новый шаг к усовершенствованию твоего воинского мастерства. К северу от Мельницы Таррен, в Альтеракских горах, есть вход в Альтеракскую долину. Там тебе нужно отыскать воеводу Лаггронда.','Отправляйтесь в Альтеракскую долину, расположенную в Альтеракских горах. Найдите воеводу Лаггронда у входа в тоннель и поговорите с ним, чтобы начать свою военную карьеру в клане Северного Волка. Альтеракская долина находится к северу от деревни Мельница Таррен у подножия Альтеракских гор.','Чтобы стать солдатом клана Северного Волка, тебе нужно пройти проверку...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита клана Северного Волка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Издалека доносится рокот барабанов войны, |3-6($c). Клан твоего вождя подвергается атакам презренных дворфов клана Грозовой Вершины из Стальгорна. $b$bСудя по твоему виду, можно решить, что ты $Gзакален в битвах и готов:закалена в битвах и готова; постоять за дело клана Северного Волка. $b$bА сейчас тебе предстоит сделать новый шаг к усовершенствованию твоего воинского мастерства. К северу от Мельницы Таррен, в Альтеракских горах, есть вход в Альтеракскую долину. Там тебе нужно отыскать воеводу Лаггронда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Альтеракскую долину, расположенную в Альтеракских горах. Найдите воеводу Лаггронда у входа в тоннель и поговорите с ним, чтобы начать свою военную карьеру в клане Северного Волка. Альтеракская долина находится к северу от деревни Мельница Таррен у подножия Альтеракских гор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чтобы стать солдатом клана Северного Волка, тебе нужно пройти проверку...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7261,'Королевское право','Здесь, в Альтеракской долине, идут тяжелые бои. С одной стороны на нас наступают тролли-каннибалы из племени Ледяной Секиры, с другой – дикари из клана Северного Волка. Во имя короля Магни Бронзоборода, все они должны быть уничтожены! Владение этими землями – неотъемлемое суверенное право королевства Стальгорн!$B$BК сожалению, солдаты не растут на деревьях. Доложись лейтенанту Хаггердину рядом с Альтеракской долиной и с честью приступай к несению службы в Грозовой Вершине!','Отправляйтесь в Альтеракскую долину, к предгорьям Хилсбрада. Найдите лейтенанта Хаггердина рядом со входом в туннель и поговорите с ним.$B$BВо славу Бронзоборода!','За работу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Королевское право',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, в Альтеракской долине, идут тяжелые бои. С одной стороны на нас наступают тролли-каннибалы из племени Ледяной Секиры, с другой – дикари из клана Северного Волка. Во имя короля Магни Бронзоборода, все они должны быть уничтожены! Владение этими землями – неотъемлемое суверенное право королевства Стальгорн!$B$BК сожалению, солдаты не растут на деревьях. Доложись лейтенанту Хаггердину рядом с Альтеракской долиной и с честью приступай к несению службы в Грозовой Вершине!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Альтеракскую долину, к предгорьям Хилсбрада. Найдите лейтенанта Хаггердина рядом со входом в туннель и поговорите с ним.$B$BВо славу Бронзоборода!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','За работу!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7281,'Братская любовь','Отправляйтесь на территорию Грозовой Вершины и убейте командира Карла Филипса. После выполнения задания возвращайтесь к командиру Луи Филипсу.','Твой героизм непревзойден, $N.$B$BЯ должен рассказать об этом Сильване и побыстрее!','Как, должно быть, больно ему оставаться одним из живых, пока его возлюбленный брат достиг совершенства.','Вернитесь к командиру Луи Филипсу в Смотровую башню, что в Альтеракской долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братская любовь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на территорию Грозовой Вершины и убейте командира Карла Филипса. После выполнения задания возвращайтесь к командиру Луи Филипсу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твой героизм непревзойден, $N.$B$BЯ должен рассказать об этом Сильване и побыстрее!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как, должно быть, больно ему оставаться одним из живых, пока его возлюбленный брат достиг совершенства.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Луи Филипсу в Смотровую башню, что в Альтеракской долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7282,'Братская любовь','Отправляйтесь на территорию клана Северного Волка и убейте командира Луи Филипса. После выполнения задания возвращайтесь к командиру Карлу Филипсу.','Ты же не $Gзабыл:забыла; сжечь труп?','С тяжелым сердцем отдаю такой приказ, солдат.','Вернитесь к командиру Карлу Филипсу в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братская любовь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на территорию клана Северного Волка и убейте командира Луи Филипса. После выполнения задания возвращайтесь к командиру Карлу Филипсу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты же не $Gзабыл:забыла; сжечь труп?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С тяжелым сердцем отдаю такой приказ, солдат.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Карлу Филипсу в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7301,'Свергнутые властители небес','Мы взяли их в плен, |3-6($r). Мы захватили командиров звена. В небе разразилась яростная битва, но в итоге они все же уступили! К сожалению, во время контратаки против крепости Северного Волка были сбиты наши лучшие пилоты. Нужно выяснить, что с ними случилось. $b$bОбыщи западную Смотровую башню и крепость Северного Волка. Там они были замечены в последний раз. Как можно тщательней осмотри эти районы.','Отправляйтесь в крепость Северного Волка и поищите командиров звена Макарча, Сквороца и Ромеона. Вернитесь с отчетом к командиру Даффи.','Невероятно! Ты $Gосвободил:освободила; их, верно? Верно? Ну ладно, по крайней мере, мы знаем, хотя бы где их держат.','Что-нибудь, что я хотел бы услышать?','Вернитесь к командиру Даффи в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свергнутые властители небес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы взяли их в плен, |3-6($r). Мы захватили командиров звена. В небе разразилась яростная битва, но в итоге они все же уступили! К сожалению, во время контратаки против крепости Северного Волка были сбиты наши лучшие пилоты. Нужно выяснить, что с ними случилось. $b$bОбыщи западную Смотровую башню и крепость Северного Волка. Там они были замечены в последний раз. Как можно тщательней осмотри эти районы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в крепость Северного Волка и поищите командиров звена Макарча, Сквороца и Ромеона. Вернитесь с отчетом к командиру Даффи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно! Ты $Gосвободил:освободила; их, верно? Верно? Ну ладно, по крайней мере, мы знаем, хотя бы где их держат.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что-нибудь, что я хотел бы услышать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Даффи в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7302,'Свергнутые властители небес','Выясните, что стало с командирами звена Смугглом, Маашей и Маэстром. Вернитесь с отчетом к командиру Мулфорту.','Неплохо. Информация, которую ты $Gдостал:достала;, нам очень пригодится.','Статус охоты, солдат?','Вернитесь к командиру Мулфорту в Деревню Северного Волка, что в Альтеракской долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свергнутые властители небес',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните, что стало с командирами звена Смугглом, Маашей и Маэстром. Вернитесь с отчетом к командиру Мулфорту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо. Информация, которую ты $Gдостал:достала;, нам очень пригодится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Статус охоты, солдат?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мулфорту в Деревню Северного Волка, что в Альтеракской долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7321,'Нежный черепаховый суп','Кто сказал, что нежить не понимает в кулинарии? Взять, к примеру, мой заветный рецепт нежного черепашьего супа. Да я знаю народ, что из мертвых бы восстал, только бы скушать тарелочку! Хе-хе...$B$BКстати, в последнее время мне ни тарелочки приготовить не удалось. Обычно я сам ходил на озеро Лордамер ловить хрустогрызов – у, грязные тварюги – но не могу сейчас бросить работу.$B$BЕсли ты добудешь мне немного черепашьего мяса, я научу тебя варить такой суп!','Принесите 10 кусков черепашьего мяса Кристофу Френчу на Мельницу Таррен.','Мой нежный черепаший супчик согреет тебя холодной ночью... Если, конечно, ты еще помнишь, что такое холод.','Повезло добыть ингредиенты? Надо сказать, нынче эти места просто кишат подонками из Альянса... По мне, они уже зашли слишком далеко...','Вернитесь к Кристофу Френчу на Мельницу Таррен, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нежный черепаховый суп',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто сказал, что нежить не понимает в кулинарии? Взять, к примеру, мой заветный рецепт нежного черепашьего супа. Да я знаю народ, что из мертвых бы восстал, только бы скушать тарелочку! Хе-хе...$B$BКстати, в последнее время мне ни тарелочки приготовить не удалось. Обычно я сам ходил на озеро Лордамер ловить хрустогрызов – у, грязные тварюги – но не могу сейчас бросить работу.$B$BЕсли ты добудешь мне немного черепашьего мяса, я научу тебя варить такой суп!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 кусков черепашьего мяса Кристофу Френчу на Мельницу Таррен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой нежный черепаший супчик согреет тебя холодной ночью... Если, конечно, ты еще помнишь, что такое холод.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Повезло добыть ингредиенты? Надо сказать, нынче эти места просто кишат подонками из Альянса... По мне, они уже зашли слишком далеко...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кристофу Френчу на Мельницу Таррен, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (7341,'Честная сделка','Вернитесь к Коларку Наемнику в Азшару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Честная сделка',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коларку Наемнику в Азшару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7342,'Стрелы – для неженок!','Дело сделано! Вот твои стрелы.','Нет, ты представляешь?! Последнюю партию снарядов из Караноса запороли! И остается стрелять этими хлипкими, ни на что не годными стрелами! Что мне делать с половиной миллиона стрел с ториевыми наконечниками?$B$BВот что, $Gпарень:девочка;... Если принесешь мне ториевых патронов, я отдам за них эти стрелы с ториевыми наконечниками, прямо сразу и отдам! Идет?','Вернитесь к артиллеристу Шелдонору в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стрелы – для неженок!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дело сделано! Вот твои стрелы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нет, ты представляешь?! Последнюю партию снарядов из Караноса запороли! И остается стрелять этими хлипкими, ни на что не годными стрелами! Что мне делать с половиной миллиона стрел с ториевыми наконечниками?$B$BВот что, $Gпарень:девочка;... Если принесешь мне ториевых патронов, я отдам за них эти стрелы с ториевыми наконечниками, прямо сразу и отдам! Идет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к артиллеристу Шелдонору в Болотину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7367,'Обезвредить угрозу','Клан Северного Волка позволил заманить себя в совершенно идиотскую ловушку, |3-6($c). Надо быть более осмотрительным, действуя на территории врага.$B$BЕсли хочешь нанести им ощутимый удар, нужно уничтожить того, кто отвечает их за минные поля, – я говорю об эксперте по взрывчатым веществам. Пока он жив, минные поля существуют. Но если он будет мертв, поддерживать их станет некому.$B$BНе исключаю, что эксперта можно найти в башне рядом с гарнизоном Стылой Крови. Удачи тебе!','Найдите эксперта по взрывчатым веществам из клана Северного Волка и убейте его. После завершения задания возвращайтесь к эксперту по взрывчатым веществам из клана Грозовой Вершины.','Вернитесь к эксперту по взрывчатым веществам клана Грозовой Вершины в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезвредить угрозу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Северного Волка позволил заманить себя в совершенно идиотскую ловушку, |3-6($c). Надо быть более осмотрительным, действуя на территории врага.$B$BЕсли хочешь нанести им ощутимый удар, нужно уничтожить того, кто отвечает их за минные поля, – я говорю об эксперте по взрывчатым веществам. Пока он жив, минные поля существуют. Но если он будет мертв, поддерживать их станет некому.$B$BНе исключаю, что эксперта можно найти в башне рядом с гарнизоном Стылой Крови. Удачи тебе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите эксперта по взрывчатым веществам из клана Северного Волка и убейте его. После завершения задания возвращайтесь к эксперту по взрывчатым веществам из клана Грозовой Вершины.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к эксперту по взрывчатым веществам клана Грозовой Вершины в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7368,'Обезвредить угрозу','Про противопехотные мины я знаю все. Именно я, а не кто-нибудь, отвечаю за мины на всей линии фронта.$B$BЕсли ты хочешь обезвредить все минные поля Грозовой Вершины, сначала надо убить их эксперта по взрывчатым веществам. Этот трусливый дворф скорее всего прячется в первой башне Поля брани. Убей его, и минные поля будут обезврежены раз и навсегда.$B$BКак убьешь его, возвращайся ко мне. Добрые дела не должны оставаться без награды.','Найдите эксперта по взрывчатым веществам из клана Грозовой Вершины и убейте его. После завершения задания возвращайтесь к эксперту по взрывчатым веществам из клана Северного Волка.','Вернитесь к эксперту по взрывчатым веществам из клана Северного Волка в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезвредить угрозу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Про противопехотные мины я знаю все. Именно я, а не кто-нибудь, отвечаю за мины на всей линии фронта.$B$BЕсли ты хочешь обезвредить все минные поля Грозовой Вершины, сначала надо убить их эксперта по взрывчатым веществам. Этот трусливый дворф скорее всего прячется в первой башне Поля брани. Убей его, и минные поля будут обезврежены раз и навсегда.$B$BКак убьешь его, возвращайся ко мне. Добрые дела не должны оставаться без награды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите эксперта по взрывчатым веществам из клана Грозовой Вершины и убейте его. После завершения задания возвращайтесь к эксперту по взрывчатым веществам из клана Северного Волка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к эксперту по взрывчатым веществам из клана Северного Волка в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7381,'Возвращение Коррака','В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте.$B$BПринесите череп Коррака воеводе Лаггронду в предгорья Хилсбрада.','Вернитесь к воеводе Лаггронду в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение Коррака',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте.$B$BПринесите череп Коррака воеводе Лаггронду в предгорья Хилсбрада.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воеводе Лаггронду в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7382,'Коррак Бессмертный','Что-то здесь не так... Кто-нибудь догадался сжечь тело Коррака? Эти синекожие язычники ни перед чем не остановятся, чтобы возродить своего вождя.$B$BСмотри в оба, $n. Не удивляйся, если снова увидишь Коррака в живых. Убей его снова, но на этот раз обязательно сожги тело.$B$BЧтобы уж все проделать наверняка, отрежь ему голову и принеси череп мне, а все остальное пусть горит синим пламенем.','В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте.$B$BПринесите череп Коррака лейтенанту Хаггердину в предгорья Хилсбрада.','Вернитесь к лейтенанту Хаггердину на холм Дарроу, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коррак Бессмертный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то здесь не так... Кто-нибудь догадался сжечь тело Коррака? Эти синекожие язычники ни перед чем не остановятся, чтобы возродить своего вождя.$B$BСмотри в оба, $n. Не удивляйся, если снова увидишь Коррака в живых. Убей его снова, но на этот раз обязательно сожги тело.$B$BЧтобы уж все проделать наверняка, отрежь ему голову и принеси череп мне, а все остальное пусть горит синим пламенем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','В случае, если Коррак Кровопуск возвратится на Поле брани, найдите его и уничтожьте.$B$BПринесите череп Коррака лейтенанту Хаггердину в предгорья Хилсбрада.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Хаггердину на холм Дарроу, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7383,'Тельдрассил: ноша калдорай','Теперь ты $gдолжен:должна; посетить лунный колодец под ветвями Древа-оракула, далеко на северо-западе. Это первый и самый могучий из наших колодцев, в его водах содержится сама суть силы Элуны.$b$bНаполни фиал его водой и вернись ко мне. Я буду ждать тебя на перекрестке перед Дарнасом.','Наполните аметистовый фиал.','Встретьтес с Коритрасом Лунным Гневом на перекрестке перед Дарнасом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тельдрассил: ноша калдорай',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты $gдолжен:должна; посетить лунный колодец под ветвями Древа-оракула, далеко на северо-западе. Это первый и самый могучий из наших колодцев, в его водах содержится сама суть силы Элуны.$b$bНаполни фиал его водой и вернись ко мне. Я буду ждать тебя на перекрестке перед Дарнасом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните аметистовый фиал.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Встретьтес с Коритрасом Лунным Гневом на перекрестке перед Дарнасом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7384,'Ремесленники по чешуе','Принеси мне немного чешуи','Соберите немного чешуи для Караны из Убежища на Болоте Печали.','Вернитесь к Каране в Убежище, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ремесленники по чешуе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принеси мне немного чешуи',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите немного чешуи для Караны из Убежища на Болоте Печали.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каране в Убежище, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7385,'Галлон крови','Знаешь, $N – давай-ка ты мне будешь носить кровь галлонами. Зачем мелочиться?','Вернитесь к шаманке стихий Турлога в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Галлон крови',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаешь, $N – давай-ка ты мне будешь носить кровь галлонами. Зачем мелочиться?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шаманке стихий Турлога в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7386,'Друза','Отлично, $N. Сила этих чар пригодится для усиления уже имеющейся магии. Когда энергии наберется достаточно, я смогу ее сфокусировать и воззвать к Лесному Властелину о помощи.','Наверняка ты попадешь в битвы, которые будут длиться долгие дни. В такие времена не забывай собирать кристаллы Бури клана Северного Волка.$B$BКруг Кенариуса будет рад подобным дарам, $N.','Вернитесь к верховному друиду Дикой Лани в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друза',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N. Сила этих чар пригодится для усиления уже имеющейся магии. Когда энергии наберется достаточно, я смогу ее сфокусировать и воззвать к Лесному Властелину о помощи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наверняка ты попадешь в битвы, которые будут длиться долгие дни. В такие времена не забывай собирать кристаллы Бури клана Северного Волка.$B$BКруг Кенариуса будет рад подобным дарам, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному друиду Дикой Лани в Альтеракскую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7429,'Освободите Нотта!','Вы для меня – номер один во всем мире! Все остальные – после вас! Ох, большое вам спасибо, что освободили меня!$b$bЯ знал, я знал, что меня ждет более достойная участь, чем пойти на обед какому-нибудь огру!','Эта вещь называется "ключ от оков Гордока" – по крайней мере, так называют его эти "остроумцы". Думаю, такой ключ может быть у любого из огров, но у кого именно – сказать не возьмусь. Есть вероятность, что такие ключи имеются у стражников…$b$bНо о чем я говорю? Он у вас есть, да? Он при вас?!','Вернитесь к Уззлу Наперстяку в Забытый Город.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освободите Нотта!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы для меня – номер один во всем мире! Все остальные – после вас! Ох, большое вам спасибо, что освободили меня!$b$bЯ знал, я знал, что меня ждет более достойная участь, чем пойти на обед какому-нибудь огру!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эта вещь называется "ключ от оков Гордока" – по крайней мере, так называют его эти "остроумцы". Думаю, такой ключ может быть у любого из огров, но у кого именно – сказать не возьмусь. Есть вероятность, что такие ключи имеются у стражников…$b$bНо о чем я говорю? Он у вас есть, да? Он при вас?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уззлу Наперстяку в Забытый Город.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7441,'Пузиллин и старейшина Азж\'Тордин','Представь себе, $gчужестранец:чужестранка;: стоило мне зазеваться всего на секунду!.. я был очень занят: спасался от принца-отступника... – и меня тут же обворовали! Гнуснейший демон, бес Пузиллин, стащил мою книгу заклинаний, и ключ от некогда прекрасных чертогов Эльдре\'Таласа!$b$bКлюч мне теперь ни к чему: я обменял свое бессмертие на свободу, – но книга мне нужна позарез!$b$bОтыщи мне этого беса Пузиллина, и добудь у него книгу!$b$bИщи его в Квартале Криводревов Забытого Города.','Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж\'Тордина.$b$bЕсли добудете книгу, вернитесь к Азж\'Тордину в павильон Лорисс в Фераласе.','Ты $Gнашёл:нашла; его! Проклятый бес. Увы, мои сбережения скудны. Но ты можешь выбрать что-то из того, что у меня есть.','Я ни о чем не жалею, $Gчужестранец:чужестранка;. Королевы давно уже нет в живых. Труды Шен\'дралар осквернены безумием принца Тортелдрина. Я жажду лишь свободы... Освобождения...','Вернитесь к Аж\'Тордину в Фералас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пузиллин и старейшина Азж\'Тордин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Представь себе, $gчужестранец:чужестранка;: стоило мне зазеваться всего на секунду!.. я был очень занят: спасался от принца-отступника... – и меня тут же обворовали! Гнуснейший демон, бес Пузиллин, стащил мою книгу заклинаний, и ключ от некогда прекрасных чертогов Эльдре\'Таласа!$b$bКлюч мне теперь ни к чему: я обменял свое бессмертие на свободу, – но книга мне нужна позарез!$b$bОтыщи мне этого беса Пузиллина, и добудь у него книгу!$b$bИщи его в Квартале Криводревов Забытого Города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Забытый Город и отыщите беса Пузиллина. Любыми доступными средствами убедите Пузиллина отдать вам книгу заклинаний Аж\'Тордина.$b$bЕсли добудете книгу, вернитесь к Азж\'Тордину в павильон Лорисс в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gнашёл:нашла; его! Проклятый бес. Увы, мои сбережения скудны. Но ты можешь выбрать что-то из того, что у меня есть.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я ни о чем не жалею, $Gчужестранец:чужестранка;. Королевы давно уже нет в живых. Труды Шен\'дралар осквернены безумием принца Тортелдрина. Я жажду лишь свободы... Освобождения...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аж\'Тордину в Фералас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7461,'Древнее безумие','Ну что, довольно ли ты $gслышал:слышала;? Надеюсь, ты не устрашишься вступить в бой?$b$bЭтому безумию необходимо положить конец! Время бессмертных давным-давно миновало. Уничтожь стражей, охраняющих столпы, и ликвидируй силовое поле. А потом убей Бессмер\'тера. Это лишит принца большей части его силы, и тогда ты сможешь убить и его тоже. Помоги духам этого города упокоиться в мире!','Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер\'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер\'тера, рассеется.$b$bВойдите в Тюрьму Бессмер\'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.$b$bЕсли задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен\'дралар.','Благодарим тебя, $Gгерой:героиня;.','Будь осторожнее! Принц умеет заговаривать зубы...','Вернитесь к прародительнице Шен\'дралар в Забытый Город.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древнее безумие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что, довольно ли ты $gслышал:слышала;? Надеюсь, ты не устрашишься вступить в бой?$b$bЭтому безумию необходимо положить конец! Время бессмертных давным-давно миновало. Уничтожь стражей, охраняющих столпы, и ликвидируй силовое поле. А потом убей Бессмер\'тера. Это лишит принца большей части его силы, и тогда ты сможешь убить и его тоже. Помоги духам этого города упокоиться в мире!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Перебейте стражей, которые охраняют 5 столпов, снабжающих энергией Тюрьму Бессмер\'тера. После того как столпы угаснут, силовое поле, удерживающее Бессмер\'тера, рассеется.$b$bВойдите в Тюрьму Бессмер\'тера и уничтожьте злого демона, который находится внутри. И, наконец, сразитесь с принцем Тортелдрином в Читальне.$b$bЕсли задание будет выполнено успешно, вернитесь во двор, к прародительнице Шен\'дралар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарим тебя, $Gгерой:героиня;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будь осторожнее! Принц умеет заговаривать зубы...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к прародительнице Шен\'дралар в Забытый Город.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7462,'Сокровище Шен\'дралар','В библиотеке, Читальне, ты найдешь древний сундук, спрятанный под лестницей. Можешь взять оттуда, что тебе понравится.','Вернитесь в Читальню и найдите сокровище Шен\'дралар. Получите свою награду!','Вы открываете сундук и находите…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровище Шен\'дралар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В библиотеке, Читальне, ты найдешь древний сундук, спрятанный под лестницей. Можешь взять оттуда, что тебе понравится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Читальню и найдите сокровище Шен\'дралар. Получите свою награду!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы открываете сундук и находите…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7463,'Магический напиток','А-а, |3-6($r), $gпосвятивший:посвятившая:r;себя магии! Удивительно. Я не видывал подобных тебе уже... сколько? Которое у нас тысячелетье на дворе? Да уже лет пятьсот!$b$bУ меня есть кое-что, что поможет утолить твою жажду, но сначала тебе придется выполнить одно мое поручение.$b$b*Лидрос хихикает.*$b$bВ Эльдре\'Таласе завелась аномалия. В восточном крыле поселился элементаль воды. Надо его... того... занести в каталог.$b$bСтупай в Квартал Криводревов, и добудь мне частицу стихийной сущности Гидротвари. Принеси ее мне, а я тебя научу одной полезной штучке!','Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.','Превосходно! Но кто ты? О, это не имеет значения. Что я должен был дать тебе? Хм... ну, $C, может это окажется для тебя полезным.','Да? Мы где-то встречались?','Вернитесь к Сказителю Лидросу в Забытый Город.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магический напиток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А-а, |3-6($r), $gпосвятивший:посвятившая:r;себя магии! Удивительно. Я не видывал подобных тебе уже... сколько? Которое у нас тысячелетье на дворе? Да уже лет пятьсот!$b$bУ меня есть кое-что, что поможет утолить твою жажду, но сначала тебе придется выполнить одно мое поручение.$b$b*Лидрос хихикает.*$b$bВ Эльдре\'Таласе завелась аномалия. В восточном крыле поселился элементаль воды. Надо его... того... занести в каталог.$b$bСтупай в Квартал Криводревов, и добудь мне частицу стихийной сущности Гидротвари. Принеси ее мне, а я тебя научу одной полезной штучке!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ступайте в Квартал Криводревов Забытого Города и убейте элементаля воды Гидротварь. Вернитесь в Читальню к сказителю Лидросу и принесите ему сущность Гидротвари.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Но кто ты? О, это не имеет значения. Что я должен был дать тебе? Хм... ну, $C, может это окажется для тебя полезным.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Мы где-то встречались?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сказителю Лидросу в Забытый Город.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (7481,'Эльфийские легенды','Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.$B$BOur search for this lost master led us from the ruins of Quel\'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.$B$BWe suspect that the elf sought sanctuary in the halls of Eldre\'Thalas (what is now known as Dire Maul).$B$BYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!','Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в Лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать.','О стыд... о ужас... Предметы потеряны? И никакого следа?','Моя помощница, ученый ночных эльфов, Рунеторн, вербует своих союзников для выполнения этой задачи.','Обнаруженный мастер Кариэль Винтхалус','Вернитесь к ведуну Королуску в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эльфийские легенды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.$B$BOur search for this lost master led us from the ruins of Quel\'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.$B$BWe suspect that the elf sought sanctuary in the halls of Eldre\'Thalas (what is now known as Dire Maul).$B$BYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в Лагерь Мохаче к ведуну Королуску и сообщите ему все, что вам удалось узнать.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О стыд... о ужас... Предметы потеряны? И никакого следа?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Моя помощница, ученый ночных эльфов, Рунеторн, вербует своих союзников для выполнения этой задачи.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Обнаруженный мастер Кариэль Винтхалус',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведуну Королуску в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (7482,'Эльфийские легенды','Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.$B$BOur search for this lost master led us from the ruins of Quel\'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.$B$BWe suspect that the elf sought sanctuary in the halls of Eldre\'Thalas (what is now known as Dire Maul).$B$BYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!','Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в крепость Оперенной Луны к книжнице Рунический Шип и сообщите ей все, что вам удалось узнать.','О стыд... о ужас... Предметы потеряны? И никакого следа?','Моя помощница, ученый ночных эльфов, Рунеторн, вербует своих союзников для выполнения этой задачи.','Обнаруженный мастер Кариэль Винтхалус','Вернитесь к книжнице Рунический Шип в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эльфийские легенды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Several years ago, a lone elven master named Kariel Winthalus fled the devastation of his homeland with several ancient elven artifacts in tow.$B$BOur search for this lost master led us from the ruins of Quel\'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.$B$BWe suspect that the elf sought sanctuary in the halls of Eldre\'Thalas (what is now known as Dire Maul).$B$BYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попытайтесь найти в Забытом Городе Кариэля Винтхалуса. Вернитесь в крепость Оперенной Луны к книжнице Рунический Шип и сообщите ей все, что вам удалось узнать.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О стыд... о ужас... Предметы потеряны? И никакого следа?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Моя помощница, ученый ночных эльфов, Рунеторн, вербует своих союзников для выполнения этой задачи.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Обнаруженный мастер Кариэль Винтхалус',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к книжнице Рунический Шип в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7483,'Манускрипт скорости','Мастер Винтхалус потерял "Манускрипт Скорости" в восточном крыле. Этот манускрипт позволит тебе наложить на все свое снаряжение небольшое ускоряющее заклятие. Детские игрушки, на самом деле...$b$bТем не менее, если тебя это все же интересует, принеси мне манускрипт, и кое-какие необходимые реагенты.$b$bХм... Насколько я помню, там требуется кровь героев, безупречный черный алмаз и большие сверкающие осколки. Впрочем, я могу и ошибиться!$b$b*Лидрос пожимает плечами.*','Принесите сказителю Лидросу в Забытом Городе "Манускрипт Скорости", 1 безупречный черный алмаз, 2 больших сверкающих осколка и 2 образца крови героев, чтобы получить магический знак стремительности.','<Лидрос хмыкает.>$B$BКак и было обещано, магический знак стремительности. Обращайся с ним аккуратно.$B$B<Лидрос смеется.>','Чего тебе? Я с каталогом работаю!','Вернитесь к Сказителю Лидросу в Даларанский кратер, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Манускрипт скорости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мастер Винтхалус потерял "Манускрипт Скорости" в восточном крыле. Этот манускрипт позволит тебе наложить на все свое снаряжение небольшое ускоряющее заклятие. Детские игрушки, на самом деле...$b$bТем не менее, если тебя это все же интересует, принеси мне манускрипт, и кое-какие необходимые реагенты.$b$bХм... Насколько я помню, там требуется кровь героев, безупречный черный алмаз и большие сверкающие осколки. Впрочем, я могу и ошибиться!$b$b*Лидрос пожимает плечами.*',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сказителю Лидросу в Забытом Городе "Манускрипт Скорости", 1 безупречный черный алмаз, 2 больших сверкающих осколка и 2 образца крови героев, чтобы получить магический знак стремительности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Лидрос хмыкает.>$B$BКак и было обещано, магический знак стремительности. Обращайся с ним аккуратно.$B$B<Лидрос смеется.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего тебе? Я с каталогом работаю!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сказителю Лидросу в Даларанский кратер, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7484,'Манускрипт средоточия','Этот манускрипт едва не вызвал интерес у одного из юных фамилиаров хранителя мудрости! Бедняжка, ему было всего несколько недель от роду!$b$bТем из вас, кто интересуется магией, этот манускрипт может пригодиться!$b$bОн пропал где-то в этом крыле. Могу только предположить, что его прибрал к рукам один из духов высокорожденных.$b$bПринесите мне "Манускрипт Средоточия", несколько больших сверкающих осколков, шкуру тени и безупречный черный алмаз, и я создам для вас магический знак.','Принесите сказителю Лидросу в Забытом Городе "Манускрипт Средоточия", 1 безупречный черный алмаз, 4 больших сверкающих осколка и 2 образца шкуры тени, чтобы получить магический знак сосредоточения.','Смотри, |3-6($R, не покалечься, когда будешь пускать его в ход!','Снова ты? Ну, а теперь-то тебе чего надо?','Вернитесь к Сказителю Лидросу в Даларанский кратер, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Манускрипт средоточия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот манускрипт едва не вызвал интерес у одного из юных фамилиаров хранителя мудрости! Бедняжка, ему было всего несколько недель от роду!$b$bТем из вас, кто интересуется магией, этот манускрипт может пригодиться!$b$bОн пропал где-то в этом крыле. Могу только предположить, что его прибрал к рукам один из духов высокорожденных.$b$bПринесите мне "Манускрипт Средоточия", несколько больших сверкающих осколков, шкуру тени и безупречный черный алмаз, и я создам для вас магический знак.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сказителю Лидросу в Забытом Городе "Манускрипт Средоточия", 1 безупречный черный алмаз, 4 больших сверкающих осколка и 2 образца шкуры тени, чтобы получить магический знак сосредоточения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смотри, |3-6($R, не покалечься, когда будешь пускать его в ход!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Снова ты? Ну, а теперь-то тебе чего надо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сказителю Лидросу в Даларанский кратер, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7485,'Манускрипт защиты','Потеряв этот манускрипт, он рыдал, как ребенок! Не пойми меня неправильно – мне и самому случалось плакать из-за книг, ведь нет большей утраты, чем утраченные знания, – но рыдать из-за этих почти бесполезных обрывков заклинаний? Абсурд! Мне даже подумалось, что принц, пожалуй, оказал ему услугу, отделив его плоть от костей.$b$bПринеси мне этот манускрипт вместе с безупречным черным алмазом, большими сверкающими осколками и истлевшей шовной нитью поганища, и я воссоздам этот магический знак!$b$bАх, да: в общем, ищи в северном крыле.','Принесите сказителю Лидросу в Забытом Городе "Манускрипт Защиты", 1 безупречный черный алмаз, 2 больших сверкающих осколка и 1 истлевшую шовную нить поганища, чтобы получить магический знак защиты.','Да-да! Успокойся. Вот твой магический знак, как я и обещал.','Радуйся, что я такой терпеливый, а то бы я тебе...','Вернитесь к Сказителю Лидросу в Даларанский кратер, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Манускрипт защиты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Потеряв этот манускрипт, он рыдал, как ребенок! Не пойми меня неправильно – мне и самому случалось плакать из-за книг, ведь нет большей утраты, чем утраченные знания, – но рыдать из-за этих почти бесполезных обрывков заклинаний? Абсурд! Мне даже подумалось, что принц, пожалуй, оказал ему услугу, отделив его плоть от костей.$b$bПринеси мне этот манускрипт вместе с безупречным черным алмазом, большими сверкающими осколками и истлевшей шовной нитью поганища, и я воссоздам этот магический знак!$b$bАх, да: в общем, ищи в северном крыле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сказителю Лидросу в Забытом Городе "Манускрипт Защиты", 1 безупречный черный алмаз, 2 больших сверкающих осколка и 1 истлевшую шовную нить поганища, чтобы получить магический знак защиты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да! Успокойся. Вот твой магический знак, как я и обещал.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Радуйся, что я такой терпеливый, а то бы я тебе...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сказителю Лидросу в Даларанский кратер, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7486,'Награда для героя','$n, твои заслуги перед Повелителями Вод превосходят самые смелые ожидания. Мы не могли предположить, что обитатель этого мира может обладать подобной силой!$B$BНе знаю, как у твоего народа принято выражать благодарность, однако могу пообещать тебе щедрую награду.$B$BОтправляйся в южную часть острова и найди сундук, сокрытый в волнах. В том сундуке твоя награда.$B$BИди, $n. Забери свою награду.','Заберите свою награду из сундука Гидраксиса.','Голос Гидраксиса доносится от поверхности воды…$B$B"Выбери себе то, что лучше всего подходит тебе, $N. Пусть оно защищает тебя от врагов Повелителей Вод."') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда для героя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, твои заслуги перед Повелителями Вод превосходят самые смелые ожидания. Мы не могли предположить, что обитатель этого мира может обладать подобной силой!$B$BНе знаю, как у твоего народа принято выражать благодарность, однако могу пообещать тебе щедрую награду.$B$BОтправляйся в южную часть острова и найди сундук, сокрытый в волнах. В том сундуке твоя награда.$B$BИди, $n. Забери свою награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите свою награду из сундука Гидраксиса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Голос Гидраксиса доносится от поверхности воды…$B$B"Выбери себе то, что лучше всего подходит тебе, $N. Пусть оно защищает тебя от врагов Повелителей Вод."',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7487,'Сродство с недрами','Земля испещрена трещинами и разломами – прямо у нас под ногами, |3-6($r). В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра в Черной горы, в самую вотчину Повелителя Огня.$B$B$gУдивлен:Удивлена;? Прискорбно... Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб...$B$BУверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться.$B$BСмотрю, у тебя глаза заблестели. Послушай, приобрести сродство с недрами не так сложно. Отправляйся в Глубины Черной горы и принеси мне осколок из Огненных Недр. Я сделаю так, что ты сможешь видеть портал.','Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте осколок из Огненных Недр. Принесите его Лотосу Хранителю Портала в Черной горе.','Теперь я могу доставить тебя в Огненные Недра. Скажи и будет сделано.','Перед предоставлением доступа вы должны настроить свою душу на Огненные Недра.','Вернитесь к Лотосу Хранителю Портала на Черную гору, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сродство с недрами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Земля испещрена трещинами и разломами – прямо у нас под ногами, |3-6($r). В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра в Черной горы, в самую вотчину Повелителя Огня.$B$B$gУдивлен:Удивлена;? Прискорбно... Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб...$B$BУверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться.$B$BСмотрю, у тебя глаза заблестели. Послушай, приобрести сродство с недрами не так сложно. Отправляйся в Глубины Черной горы и принеси мне осколок из Огненных Недр. Я сделаю так, что ты сможешь видеть портал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте осколок из Огненных Недр. Принесите его Лотосу Хранителю Портала в Черной горе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь я могу доставить тебя в Огненные Недра. Скажи и будет сделано.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Перед предоставлением доступа вы должны настроить свою душу на Огненные Недра.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лотосу Хранителю Портала на Черную гору, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7488,'Сеть Лефтендрис','Маг Лефтендрис, злокозненная эльфийка крови, чья жестокость уступает лишь ее извращенной приверженности к магии, бежала в Забытый Город! Она создала магическое устройство: сеть, улавливающую энергию этого места, – и мы опасаемся, что, если Летендрис не остановить, она нанесет непоправимый урон нашему миру!$b$bОстанови ее, $n. Отыщи ее и отними у нее эту сеть. Она, скорее всего, где-то неподалеку от сатиров в Квартале Криводревов Забытого Города. Принеси эту сеть мне, чтобы мы могли осторожно выпустить захваченную ею энергию на свободу...','Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе.','Вернитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сеть Лефтендрис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Маг Лефтендрис, злокозненная эльфийка крови, чья жестокость уступает лишь ее извращенной приверженности к магии, бежала в Забытый Город! Она создала магическое устройство: сеть, улавливающую энергию этого места, – и мы опасаемся, что, если Летендрис не остановить, она нанесет непоправимый урон нашему миру!$b$bОстанови ее, $n. Отыщи ее и отними у нее эту сеть. Она, скорее всего, где-то неподалеку от сатиров в Квартале Криводревов Забытого Города. Принеси эту сеть мне, чтобы мы могли осторожно выпустить захваченную ею энергию на свободу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сеть Лефтендрис Латроникусу Лунному Копью в Крепость Оперенной Луны в Фераласе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Латроникусу Лунному Копью в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7489,'Сеть Лефтендрис','Эльфийка крови Лефтендрис перешла все мыслимые границы! Она так жаждала все новой магической энергии, что бросила вызов своим собратьям и создала хитроумное устройство, сеть, предназначенную для того, чтобы всасывать отравленную магию Забытого Города. Она и теперь собирает эту энергию, намереваясь использовать ее против своих врагов!$b$bЛефтендрис необходимо остановить. Отыщи ее в Квартале Криводревов в Забытом Городе, повергни ее и принеси ее сеть мне, чтобы мы могли передать ее для изучения более здравомыслящим эльфам крови.','Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе.','Хорошо, $N. Эта сеть содержит большие запасы магии из Забытого Города и я боюсь думать о повреждениях, нанесенных этой магией всем существам. За все это ответственна Лефтендрис лично. Я сожалею, что она умерла, но она ни за что не рассталась бы со своей сетью пока была жива.$B$BСпасибо тебе, $N. Я пошлю сеть к тем исследователям магии, кто более ответственен чем Лефтендрис.','Ну что, $N, сеть Лефтендрис у тебя?','Вернитесь к Тало Терновому Копыту в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сеть Лефтендрис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эльфийка крови Лефтендрис перешла все мыслимые границы! Она так жаждала все новой магической энергии, что бросила вызов своим собратьям и создала хитроумное устройство, сеть, предназначенную для того, чтобы всасывать отравленную магию Забытого Города. Она и теперь собирает эту энергию, намереваясь использовать ее против своих врагов!$b$bЛефтендрис необходимо остановить. Отыщи ее в Квартале Криводревов в Забытом Городе, повергни ее и принеси ее сеть мне, чтобы мы могли передать ее для изучения более здравомыслящим эльфам крови.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сеть Лефтендрис Тало Терновому Копыту в Лагере Мохаче в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, $N. Эта сеть содержит большие запасы магии из Забытого Города и я боюсь думать о повреждениях, нанесенных этой магией всем существам. За все это ответственна Лефтендрис лично. Я сожалею, что она умерла, но она ни за что не рассталась бы со своей сетью пока была жива.$B$BСпасибо тебе, $N. Я пошлю сеть к тем исследователям магии, кто более ответственен чем Лефтендрис.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $N, сеть Лефтендрис у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тало Терновому Копыту в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (7490,'Победа Орды','Когда Тралл видит громадную голову Ониксии, его всегдашнее самообладание на миг ему изменяет. Тралл уже готов схватиться за свой легендарный Молот Рока!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа Орды',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда Тралл видит громадную голову Ониксии, его всегдашнее самообладание на миг ему изменяет. Тралл уже готов схватиться за свой легендарный Молот Рока!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7491,'На виду у всех','Выбери себе награду, и мы достойно отпразднуем твою победу!','Когда Тралл видит громадную голову Ониксии, его всегдашнее самообладание на миг ему изменяет. Тралл уже готов схватиться за свой легендарный Молот Рока!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На виду у всех',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выбери себе награду, и мы достойно отпразднуем твою победу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда Тралл видит громадную голову Ониксии, его всегдашнее самообладание на миг ему изменяет. Тралл уже готов схватиться за свой легендарный Молот Рока!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7492,'Лагерь Мохаче','Тало Терновое Копыто, тауренский старейшина, живущий в Фераласе, прислал просьбу о помощи. Подробностей он не сообщает, но говорит, что ему требуются агенты для тонкой... и опасной работы!$b$bПослужи Орде, $n. Отправляйся в Лагерь Мохаче в Фераласе и поговори с Тало.','Поговорите с Тало Терновым Копытом в Лагере Мохаче в Фераласе.','А, рад видеть тебя $C. Мне нужна твоя поддержка, $N, и боюсь, что должен направить тебя навстречу опасности…$B$BА именно в Забытый Город.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь Мохаче',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тало Терновое Копыто, тауренский старейшина, живущий в Фераласе, прислал просьбу о помощи. Подробностей он не сообщает, но говорит, что ему требуются агенты для тонкой... и опасной работы!$b$bПослужи Орде, $n. Отправляйся в Лагерь Мохаче в Фераласе и поговори с Тало.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тало Терновым Копытом в Лагере Мохаче в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, рад видеть тебя $C. Мне нужна твоя поддержка, $N, и боюсь, что должен направить тебя навстречу опасности…$B$BА именно в Забытый Город.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (7493,'Все еще только начинается!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все еще только начинается!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7494,'Крепость Оперенной Луны','$n! Твоя помощь нужна в Фераласе!$b$bЛефтендрис, маг, объявленный вне закона, бежала в развалины древнего эльфийского города Эльдре\'Таласа, ныне именуемого Забытым Городом. Есть основания предполагать, что у нее с собой мощный магический артефакт, который необходимо вернуть.$b$bЛатроникус Лунное Копье ищет агентов, которые согласились бы отправиться в Забытый Город и отнять у Лефтендрис этот артефакт.$b$bПослужи Альянсу! Отправляйся к Латроникусу. Он находится в Крепости Оперенной Луны в Фераласе.','Поговорите с Латроникусом Лунным Копьем в Крепости Оперенной Луны в Фераласе.','Привет тебе, $n. Рад тебя видеть, но предпочел бы встретиться с тобой в более приятных обстоятельствах.\n\nСлушай внимательно, у меня для тебя жизненно важное задание...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крепость Оперенной Луны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Твоя помощь нужна в Фераласе!$b$bЛефтендрис, маг, объявленный вне закона, бежала в развалины древнего эльфийского города Эльдре\'Таласа, ныне именуемого Забытым Городом. Есть основания предполагать, что у нее с собой мощный магический артефакт, который необходимо вернуть.$b$bЛатроникус Лунное Копье ищет агентов, которые согласились бы отправиться в Забытый Город и отнять у Лефтендрис этот артефакт.$b$bПослужи Альянсу! Отправляйся к Латроникусу. Он находится в Крепости Оперенной Луны в Фераласе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Латроникусом Лунным Копьем в Крепости Оперенной Луны в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, $n. Рад тебя видеть, но предпочел бы встретиться с тобой в более приятных обстоятельствах.\n\nСлушай внимательно, у меня для тебя жизненно важное задание...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7495,'Славная победа Альянса','Наконец-то, после стольких лет ожидания... Честь Штормграда восстановлена! Правосудие свершилось! Победа! Настоящая победа!','Ох ты, клянусь бородой Утера!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Славная победа Альянса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то, после стольких лет ожидания... Честь Штормграда восстановлена! Правосудие свершилось! Победа! Настоящая победа!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ох ты, клянусь бородой Утера!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7496,'Праздник добрых времен','$n, найди майора Маттингли на Аллее Героев. Он будет тебя ждать...','Найдите майора Маттингли на Аллее Героев.','$N, немногие были удостоены подобной церемонии. Прошу, выбери свою награду, и мы начнем праздник!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Праздник добрых времен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, найди майора Маттингли на Аллее Героев. Он будет тебя ждать...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите майора Маттингли на Аллее Героев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, немногие были удостоены подобной церемонии. Прошу, выбери свою награду, и мы начнем праздник!',`offerrewardtext_loc8`);
