INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7507,'Справочник Форора','Вы обнаружили нечто очень важное. Эта книга не похожа ни на одну из тех, которые вам доводилось видеть раньше.$b$bТакое впечатление, как будто кому-то удалось испортить печать Читальни. Текст искажен и читается с трудом.','Верните "Справочник Форора по убийству драконов" в Читальню.','За эту книгу на черном рынке ты можешь получить весьма не мало золота, $N. К тому же, была сломана защитная печать и теперь каждый может узнать секреты этой книги.$B$B<Лидрос усмехается.>','О, одна из наших лучших компиляций! Я ее уже лет триста не мог отыскать...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Справочник Форора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы обнаружили нечто очень важное. Эта книга не похожа ни на одну из тех, которые вам доводилось видеть раньше.$b$bТакое впечатление, как будто кому-то удалось испортить печать Читальни. Текст искажен и читается с трудом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните "Справочник Форора по убийству драконов" в Читальню.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','За эту книгу на черном рынке ты можешь получить весьма не мало золота, $N. К тому же, была сломана защитная печать и теперь каждый может узнать секреты этой книги.$B$B<Лидрос усмехается.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, одна из наших лучших компиляций! Я ее уже лет триста не мог отыскать...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7508,'Ковка Кель\'Серрара','Если хотите взять на себя эту задачу, отнесите тусклый клинок Лидросу.','Отдайте тусклый и плоский эльфийский клинок сказителю Лидросу.','Если ты хочешь войти в логово дракона, встретиться с ним лицом к лицу и надеешься выжить после этого, то тебе нужен меч, закаленный в их крови. Я могу тебе организовать такой.','Отлично! Ну-с, начнем...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ковка Кель\'Серрара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хотите взять на себя эту задачу, отнесите тусклый клинок Лидросу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте тусклый и плоский эльфийский клинок сказителю Лидросу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если ты хочешь войти в логово дракона, встретиться с ним лицом к лицу и надеешься выжить после этого, то тебе нужен меч, закаленный в их крови. Я могу тебе организовать такой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Отлично! Ну-с, начнем...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7509,'Ковка Кель\'Серрара','Отнеси потускневший древний клинок в логово Ониксии и вызови дракона на бой.$b$bВозможно, тебе придется прибегнуть к кое-каким уловкам, чтобы заставить ее раскалить меч. Разумеется, в бою она будет пытаться испепелить тебя своим огненным дыханием. Положи потускневший древний клинок где-нибудь поблизости и постарайся, чтобы огненное дыхание попало на клинок. А после этого – если, конечно, выживешь, – схвати раскаленный клинок и прикончи Ониксию.$b$bВонзи горячий древний клинок в ее тело, чтобы получить закаленный древний клинок.','Заставьте Ониксию дохнуть своим огненным дыханием на потускневший древний клинок. После этого схватите раскаленный древний клинок. Имейте в виду, что раскаленным он останется ненадолго, так что медлить не следует!$b$bПоследнее, что нужно сделать – это убить дракона и вонзить раскаленный древний клинок в его труп.$b$bСделайте это – и Кель\'Серрар навеки станет вашим!','<Лидрос бормачет что-то невнятное.>$B$BКак и было обещано, $C, меч Кель’Серрар.','Быть может, в один прекрасный день радужным клинком будет владеть другой...','Вернитесь к Сказителю Лидросу в Забытый Город.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ковка Кель\'Серрара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнеси потускневший древний клинок в логово Ониксии и вызови дракона на бой.$b$bВозможно, тебе придется прибегнуть к кое-каким уловкам, чтобы заставить ее раскалить меч. Разумеется, в бою она будет пытаться испепелить тебя своим огненным дыханием. Положи потускневший древний клинок где-нибудь поблизости и постарайся, чтобы огненное дыхание попало на клинок. А после этого – если, конечно, выживешь, – схвати раскаленный клинок и прикончи Ониксию.$b$bВонзи горячий древний клинок в ее тело, чтобы получить закаленный древний клинок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заставьте Ониксию дохнуть своим огненным дыханием на потускневший древний клинок. После этого схватите раскаленный древний клинок. Имейте в виду, что раскаленным он останется ненадолго, так что медлить не следует!$b$bПоследнее, что нужно сделать – это убить дракона и вонзить раскаленный древний клинок в его труп.$b$bСделайте это – и Кель\'Серрар навеки станет вашим!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Лидрос бормачет что-то невнятное.>$B$BКак и было обещано, $C, меч Кель’Серрар.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Быть может, в один прекрасный день радужным клинком будет владеть другой...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сказителю Лидросу в Забытый Город.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7521,'Громораан Искатель Ветра','Я рассказал тебе все, что знаю, $n. Именно тебе предстоит отыскать элементий и уничтожить воплощение Повелителя Огня.$b$bЕсли ты справишься, с тобой пребудет благословение Громораана.','Чтобы освободить Громораана Искателя Ветра из тюрьмы, отнесите правый и левый наручник Искателя Ветра, 10 слитков элементия и сущность Повелителя Огня верховному лорду Демитриану.','Вернитесь к верховному лорду Демитриану в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громораан Искатель Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рассказал тебе все, что знаю, $n. Именно тебе предстоит отыскать элементий и уничтожить воплощение Повелителя Огня.$b$bЕсли ты справишься, с тобой пребудет благословение Громораана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Чтобы освободить Громораана Искателя Ветра из тюрьмы, отнесите правый и левый наручник Искателя Ветра, 10 слитков элементия и сущность Повелителя Огня верховному лорду Демитриану.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Демитриану в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (7522,'Сосуд Возрождения','Изучи Сосуд Возрождения, смертный. Из него возродится Искатель Ветра!','Изучите Сосуд Возрождения и вернитесь к верховному лорду Демитриану.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сосуд Возрождения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изучи Сосуд Возрождения, смертный. Из него возродится Искатель Ветра!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите Сосуд Возрождения и вернитесь к верховному лорду Демитриану.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (7541,'Служба Орде','Это займет немного времени, чтобы изучить принесенный тобой кулон. За твою службу Орде, я бы хотел предложить тебе не большую награду.$B$BСпасибо, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Служба Орде',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это займет немного времени, чтобы изучить принесенный тобой кулон. За твою службу Орде, я бы хотел предложить тебе не большую награду.$B$BСпасибо, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7562,'Мор\'зул Вестник Крови','Ты хорошо $gизучил:изучила; темные искусства и $gобрел:обрела; такую власть над существам из других миров, что... быть может, пришло время подчинить себе одного из знаменитых коней погибели.$b$bВызвать его в наш мир нелегко, для этого потребуется великая сила и большие затраты, но если ты хочешь владеть таким скакуном, поговори с Мор\'зулом Вестником Крови. Он разбил лагерь рядом с Алтарем Бурь в Пылающих степях.$b$bСтупай, $n. Задание рискованное, но такие чернокнижники как ты не страшатся опасностей.','Поговорите с Мор\'зулом Вестником Крови у Алтаря Бурь в Пылающих степях.','Привет тебе, $N, и добро пожаловать. Ты здесь, чтобы учиться около Алтаря Бурь... Или.. ты $Gпришел:пришла; поговорить со мной? Ага, я понял, что тебе надо... Ты хочешь быть мастером коня погибели? Неслабая задача, она тебе будет стоить немалого количества крови и пота... и не в последнюю очередь золота. Но конь погибели, это приз за который стоит побороться...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мор\'зул Вестник Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты хорошо $gизучил:изучила; темные искусства и $gобрел:обрела; такую власть над существам из других миров, что... быть может, пришло время подчинить себе одного из знаменитых коней погибели.$b$bВызвать его в наш мир нелегко, для этого потребуется великая сила и большие затраты, но если ты хочешь владеть таким скакуном, поговори с Мор\'зулом Вестником Крови. Он разбил лагерь рядом с Алтарем Бурь в Пылающих степях.$b$bСтупай, $n. Задание рискованное, но такие чернокнижники как ты не страшатся опасностей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мор\'зулом Вестником Крови у Алтаря Бурь в Пылающих степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет тебе, $N, и добро пожаловать. Ты здесь, чтобы учиться около Алтаря Бурь... Или.. ты $Gпришел:пришла; поговорить со мной? Ага, я понял, что тебе надо... Ты хочешь быть мастером коня погибели? Неслабая задача, она тебе будет стоить немалого количества крови и пота... и не в последнюю очередь золота. Но конь погибели, это приз за который стоит побороться...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7563,'Ярость крови','Кони погибели живут в другом мире, на огненных равнинах Зорота, и чтобы подчинить себе одного из них, необходимы могущественные руны. Я могу начертать эти руны на пергаменте, но для этого нужны особые чернила.$b$bВ далеких Зимних Ключах живут зверосовы. Некогда они были чистыми существами, но демоническое влияние Теснины Зловещего Шепота лишило их разума, и они бродят по снегам в полном безумии.$b$bИз их крови я и сделаю чернила. Остается ее добыть.','Принесите 30 бутылок крови яростных зверей Мор\'зулу Вестнику Крови в Пылающие степи.','Очень хорошо. Эта кровь будет отдистиллирована и использована, как чернила на пергаменте... И я еще оставлю немного для себя, я слышал она хороша на вкус...','Ты уже $Gвидел:видела; бешеных отродий, $N? Эти твари исполнены магии, и почти вся она сосредоточена у них в крови.','Вернитесь к Мор\'зулу Вестнику Крови на Алтарь Бурь, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярость крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кони погибели живут в другом мире, на огненных равнинах Зорота, и чтобы подчинить себе одного из них, необходимы могущественные руны. Я могу начертать эти руны на пергаменте, но для этого нужны особые чернила.$b$bВ далеких Зимних Ключах живут зверосовы. Некогда они были чистыми существами, но демоническое влияние Теснины Зловещего Шепота лишило их разума, и они бродят по снегам в полном безумии.$b$bИз их крови я и сделаю чернила. Остается ее добыть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 30 бутылок крови яростных зверей Мор\'зулу Вестнику Крови в Пылающие степи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Эта кровь будет отдистиллирована и использована, как чернила на пергаменте... И я еще оставлю немного для себя, я слышал она хороша на вкус...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gвидел:видела; бешеных отродий, $N? Эти твари исполнены магии, и почти вся она сосредоточена у них в крови.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мор\'зулу Вестнику Крови на Алтарь Бурь, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7564,'Дикоглаз','Мой слуга, Горзиеки, довольно опытный алхимик. Он сможет приготовить чернила, о которых шла речь. Я уже подготовил принесенную тобой кровь; отнеси ее Горзиеки, пусть приступает к работе.','Принесите ларец Крови Горзиеки Дикоглазу в Алтарь Бурь, что в Пылающих степях.','А, эта кровь. Должно быть от мастера Мор’зула. Он любит это вещество и часто проливает его, хе-хе. Я, однако, предпочитаю его в венах маленького грызуна. Тогда она остается теплой... столько, столько понадобится.$B$BМощная кровь. Мастер Мор’зул небось делает еще один пергамент, где написано как вызвать коня погибели! Здорово!$B$BЕсли это так, то ты сможешь выполнить ритуал, друг мой, но тебе понадобится нечто большее чем просто кровь.','Ты что-то $Gпринес:принесла;? Уж не большого ли и сочного паука? Или таракана? Хоть бы живого... Мне так нравится, когда они еще шевелятся во рту...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикоглаз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой слуга, Горзиеки, довольно опытный алхимик. Он сможет приготовить чернила, о которых шла речь. Я уже подготовил принесенную тобой кровь; отнеси ее Горзиеки, пусть приступает к работе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ларец Крови Горзиеки Дикоглазу в Алтарь Бурь, что в Пылающих степях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, эта кровь. Должно быть от мастера Мор’зула. Он любит это вещество и часто проливает его, хе-хе. Я, однако, предпочитаю его в венах маленького грызуна. Тогда она остается теплой... столько, столько понадобится.$B$BМощная кровь. Мастер Мор’зул небось делает еще один пергамент, где написано как вызвать коня погибели! Здорово!$B$BЕсли это так, то ты сможешь выполнить ритуал, друг мой, но тебе понадобится нечто большее чем просто кровь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты что-то $Gпринес:принесла;? Уж не большого ли и сочного паука? Или таракана? Хоть бы живого... Мне так нравится, когда они еще шевелятся во рту...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7581,'Тюремные кандалы','Отправляйтесь в Забытый Город, что в Фераласе и добудьте 15 порций крови сатиров из племени Исчадий Природы, что живут в Квартале Криводревов. Вернитесь к Дайо из Гниющего Шрама по выполнении поручения.','Ах, самая подходящая кровь. Она подавит защитную магическую силу стража ужаса.','Подойдет только кровь сатиров из племени Исчадий Природы.','Вернитесь к Дайо Дряхлому в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тюремные кандалы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Забытый Город, что в Фераласе и добудьте 15 порций крови сатиров из племени Исчадий Природы, что живут в Квартале Криводревов. Вернитесь к Дайо из Гниющего Шрама по выполнении поручения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, самая подходящая кровь. Она подавит защитную магическую силу стража ужаса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Подойдет только кровь сатиров из племени Исчадий Природы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дайо Дряхлому в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7582,'Тюремная камера','Отправляйтесь к Теснине Зловещего Шепота в Зимних ключах и добудьте 5 слез Хедерины у демонов Хедерины, что населяют эту теснину. Вернитесь к Дайо из Гниющего Шрама по выполнении поручения.','Мне надо совместить кровь сатиров с этими кристаллами и темница будет готова!','Хедерин не отдаст свои драгоценные камни без боя, $N.','Вернитесь к Дайо Дряхлому в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тюремная камера',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Теснине Зловещего Шепота в Зимних ключах и добудьте 5 слез Хедерины у демонов Хедерины, что населяют эту теснину. Вернитесь к Дайо из Гниющего Шрама по выполнении поручения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне надо совместить кровь сатиров с этими кристаллами и темница будет готова!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хедерин не отдаст свои драгоценные камни без боя, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дайо Дряхлому в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7583,'Заточение','Ты $Gсделал:сделала; все так, как я и просил. Теперь ты $Gготов:готова; получить знания для призыва и контроля зверя.','Ну? Как?','Вернитесь к Дайо Дряхлому в Выжженные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заточение',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсделал:сделала; все так, как я и просил. Теперь ты $Gготов:готова; получить знания для призыва и контроля зверя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну? Как?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дайо Дряхлому в Выжженные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7601,'Что хочет Ниби','Если хочешь научиться у меня призывать инфернала-слугу, ты $Gдолжен:должна; убить Крошиуса и добыть из его пылающих останков огненное ядро. Но это не так просто, как кажется. Крошиус чуть не дотла сгорел. Тебе придется снова воспламенить его тело и поднять его из праха. Но для этого тебе придется добыть другие ингредиенты из других демонических сущностей.$B$BМой бес по имени Бесенок покажет тебе дорогу.','Поговорите с Бесенком в Оскверненном лесу.','Ох, опять двадцать пять...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что хочет Ниби',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хочешь научиться у меня призывать инфернала-слугу, ты $Gдолжен:должна; убить Крошиуса и добыть из его пылающих останков огненное ядро. Но это не так просто, как кажется. Крошиус чуть не дотла сгорел. Тебе придется снова воспламенить его тело и поднять его из праха. Но для этого тебе придется добыть другие ингредиенты из других демонических сущностей.$B$BМой бес по имени Бесенок покажет тебе дорогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бесенком в Оскверненном лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, опять двадцать пять...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7602,'Безупречная субстанция Скверны','Если ты намереваешлся воскресить Крошиуса, тебе понадобится пламя Скверны. Я могу зажечь его, но для этого потребуются кое-какие ингредиенты.$B$BТебе придется принести мне безупречной субстанции Скверны из трех краев нашего мира.$B$BПервый тип субстанции ты найдешь у сатиров из племени Легаши, что в Азшаре. Второй тип – у джеденарских легионеров, а третий можно добыть у стражей Скверны в Выжженных землях.$B$BПринеси мне по порции каждой субстанции, и я зажгу пламя скверны, что позволит тебе оживить Крошиуса.','Бесенок из Оскверненного леса просит вас принести ему три порции безупречной субстанции скверны из трех различных мест.$B$BБезупречной субстанцией в Азшаре владеют сатиры из племени Легаши. В Джеденаре она есть у джеженарских легионеров. Стражи Скверны в Выжженных землях владеют этой субстанцией в своих краях.$B$BДобудьте три типа безупречной субстанции Скверны и возвращайтесь к Бесенку в Оскверненный лес.','Минуту, и я смешаю эти эссенции в пламя Скверны.','Ты только никому не говори, что Ниби дурак.','Вернитесь к Бесенку в Долину Рваных Ран, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречная субстанция Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты намереваешлся воскресить Крошиуса, тебе понадобится пламя Скверны. Я могу зажечь его, но для этого потребуются кое-какие ингредиенты.$B$BТебе придется принести мне безупречной субстанции Скверны из трех краев нашего мира.$B$BПервый тип субстанции ты найдешь у сатиров из племени Легаши, что в Азшаре. Второй тип – у джеденарских легионеров, а третий можно добыть у стражей Скверны в Выжженных землях.$B$BПринеси мне по порции каждой субстанции, и я зажгу пламя скверны, что позволит тебе оживить Крошиуса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бесенок из Оскверненного леса просит вас принести ему три порции безупречной субстанции скверны из трех различных мест.$B$BБезупречной субстанцией в Азшаре владеют сатиры из племени Легаши. В Джеденаре она есть у джеженарских легионеров. Стражи Скверны в Выжженных землях владеют этой субстанцией в своих краях.$B$BДобудьте три типа безупречной субстанции Скверны и возвращайтесь к Бесенку в Оскверненный лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Минуту, и я смешаю эти эссенции в пламя Скверны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты только никому не говори, что Ниби дурак.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бесенку в Долину Рваных Ран, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7603,'Огненное ядро Крошиуса','Крошиус лежит грудой праха на северо-востоке отсюда, в долине Рваных Ран. Возьми этот пламень Скверны и воспламени его останки. Пламя оживит павшего инфернала.$B$BПосле этого он наверняка пришибет и тебя, и твоего приспешника.$B$BЕсли каким-то чудом тебе удастся уложить Крошиуса, возьми его огненное ядро и принеси Ниби.','Обыщите долину Рваных Ран в Оскверненном лесу и найдите останки Крошиуса. Когда вы их найдете, поднесите к ним пламень Скверны и подождите, пока Крошиус не восстанет из праха. Когда инфернал очнется, убейте его и возьмите из его тела огненное ядро Крошиуса.$B$BПринесите огненное ядро Крошиуса Ниби Всемогущему в Оскверненный лес.','Сделка есть сделка! Быстро, бери это и пиши. У меня нет времени! Я колдую!','Ты $Gзаблудился:заблудилась;, что ли?','Вернитесь к Ниби Всемогущему в Долину Рваных Ран, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огненное ядро Крошиуса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крошиус лежит грудой праха на северо-востоке отсюда, в долине Рваных Ран. Возьми этот пламень Скверны и воспламени его останки. Пламя оживит павшего инфернала.$B$BПосле этого он наверняка пришибет и тебя, и твоего приспешника.$B$BЕсли каким-то чудом тебе удастся уложить Крошиуса, возьми его огненное ядро и принеси Ниби.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите долину Рваных Ран в Оскверненном лесу и найдите останки Крошиуса. Когда вы их найдете, поднесите к ним пламень Скверны и подождите, пока Крошиус не восстанет из праха. Когда инфернал очнется, убейте его и возьмите из его тела огненное ядро Крошиуса.$B$BПринесите огненное ядро Крошиуса Ниби Всемогущему в Оскверненный лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сделка есть сделка! Быстро, бери это и пиши. У меня нет времени! Я колдую!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gзаблудился:заблудилась;, что ли?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ниби Всемогущему в Долину Рваных Ран, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7604,'Заключение договора','$gНижеподписавшийся:Нижеподписавшаяся; со всей ответственностью подтверждает, что сульфуронский слиток, переданный $gим:ею; братству Тория (ООО "БТ"), является подлинником. $gНижеподписавшийся:Нижеподписавшаяся; также подтверждает, что ООО "БТ" не несет никакой ответственности за любой вред, могущий последовать в результате неосторожного обращения с Сульфурасом, как то: использование Сульфураса в качестве материала для ковки; самостоятельные разработки; попытки воспроизведения; продажа и употребление в пищу.$B$BПодпись под договором автоматически означает согласие $gподписавшегося:подписавшейся; со всеми условиями, перечисленными в документе.$B$B_______________$B$BПодпись','Подпишите договор с представителем братства Тория Локтосом Недобрым Торговцем, если вам нужен чертеж сульфуронского молота.','С тобой приятно иметь дело,$N!$B$BОт имени ООО "БТ" я желаю тебе удачи в поиске Сульфураса!','Стало быть ты $Gсогласен:согласна; со всеми условиями?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заключение договора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gНижеподписавшийся:Нижеподписавшаяся; со всей ответственностью подтверждает, что сульфуронский слиток, переданный $gим:ею; братству Тория (ООО "БТ"), является подлинником. $gНижеподписавшийся:Нижеподписавшаяся; также подтверждает, что ООО "БТ" не несет никакой ответственности за любой вред, могущий последовать в результате неосторожного обращения с Сульфурасом, как то: использование Сульфураса в качестве материала для ковки; самостоятельные разработки; попытки воспроизведения; продажа и употребление в пищу.$B$BПодпись под договором автоматически означает согласие $gподписавшегося:подписавшейся; со всеми условиями, перечисленными в документе.$B$B_______________$B$BПодпись',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подпишите договор с представителем братства Тория Локтосом Недобрым Торговцем, если вам нужен чертеж сульфуронского молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С тобой приятно иметь дело,$N!$B$BОт имени ООО "БТ" я желаю тебе удачи в поиске Сульфураса!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Стало быть ты $Gсогласен:согласна; со всеми условиями?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (7621,'Предупреждение','$C, необходимо пройти ряд испытаний, которые проверят твои способности.$B$BПредлагаю выслушать историю, которую я должен тебе рассказать.$B$BНо будь $Gвнимателен:внимательна;, испытание, которое тебе необходимо пройти, нужно выполнять в одиночку. Рекомендуется, чтобы все твоих союзники оставались на расстоянии. Вмешательство повлечет за собой наиболее суровое наказание.$B$BСудьба привела тебя сюда и теперь ты здесь. Сражайся с честью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупреждение',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$C, необходимо пройти ряд испытаний, которые проверят твои способности.$B$BПредлагаю выслушать историю, которую я должен тебе рассказать.$B$BНо будь $Gвнимателен:внимательна;, испытание, которое тебе необходимо пройти, нужно выполнять в одиночку. Рекомендуется, чтобы все твоих союзники оставались на расстоянии. Вмешательство повлечет за собой наиболее суровое наказание.$B$BСудьба привела тебя сюда и теперь ты здесь. Сражайся с честью.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (7622,'Баланс Света и Тени','Тебе предстоит сделать то, что оказалось не под силу мне – спасти крестьян, погибших во время бегства из Стратхольма.$B$BОни выйдут на свет, и ты $gдолжен:должна; защитить их. Если ты не сможешь спасти слишком многих, мы продолжим влачить наше проклятое существование.$B$BЭто настоящее испытание для всех твоих способностей. Да поможет тебе Свет, $n.','Спасите жизни 50 крестьян прежде, чем 15 из них будут убиты. Поговорите с Эрис Тайнопламень по выполнении задания.$B$BЧисло погибших крестьян можно узнать, посмотрев на Колья Смерти.','Твои стойкость и мужество поразительны, $C. Ты по праву заслуживаешь владеть щепкой Нордрассила. Осталась лишь одна задача: Око Тени должно быть восстановлено. Очисти этот мир.','Баланс Света и Тени','Вернитесь к Эрис Тайнопламени в Восточные Чумные земли.','Баланс Света и Тени') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Баланс Света и Тени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе предстоит сделать то, что оказалось не под силу мне – спасти крестьян, погибших во время бегства из Стратхольма.$B$BОни выйдут на свет, и ты $gдолжен:должна; защитить их. Если ты не сможешь спасти слишком многих, мы продолжим влачить наше проклятое существование.$B$BЭто настоящее испытание для всех твоих способностей. Да поможет тебе Свет, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите жизни 50 крестьян прежде, чем 15 из них будут убиты. Поговорите с Эрис Тайнопламень по выполнении задания.$B$BЧисло погибших крестьян можно узнать, посмотрев на Колья Смерти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои стойкость и мужество поразительны, $C. Ты по праву заслуживаешь владеть щепкой Нордрассила. Осталась лишь одна задача: Око Тени должно быть восстановлено. Очисти этот мир.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Баланс Света и Тени',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эрис Тайнопламени в Восточные Чумные земли.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Баланс Света и Тени',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7623,'Лорд Гиблопуст','Морзул говорит, что ты хочешь открыть портал в Зорот. Раз так, тебе не обойтись без зоротианской звездной пыли. А ее нелегко найти в Азероте!$b$bОна может быть лишь у одного существа – лорда Гиблопуста из Джеденара, сердца Совета Теней! Поговори с ним, вдруг он поделится звездной пылью.$b$bВпрочем, отправляясь в Джеденар, тебе необходимо принять злое обличье, чтобы добраться до Совета Теней. Значит, тебе нужны мои зелья Теней, а они недешевы...','Купите зелья Теней у Горзиеки в Алтаре Бурь, что в Пылающих степях.$b$bПриняв зелья, пройдите через Джеденар в Оскверненном лесу и поговорите с лордом Гиблопустом, который находится в Оплоте Теней.','Твоя смелость и упорства не имеют себе равных, $C. Ты $Gобрел:обрела; право владеть расщепителем Нордрассила. Тебе осталось исполнить лишь одно: найти Око Тени. Найди его, даже если тебе придется обыскать весь мир.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорд Гиблопуст',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Морзул говорит, что ты хочешь открыть портал в Зорот. Раз так, тебе не обойтись без зоротианской звездной пыли. А ее нелегко найти в Азероте!$b$bОна может быть лишь у одного существа – лорда Гиблопуста из Джеденара, сердца Совета Теней! Поговори с ним, вдруг он поделится звездной пылью.$b$bВпрочем, отправляясь в Джеденар, тебе необходимо принять злое обличье, чтобы добраться до Совета Теней. Значит, тебе нужны мои зелья Теней, а они недешевы...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите зелья Теней у Горзиеки в Алтаре Бурь, что в Пылающих степях.$b$bПриняв зелья, пройдите через Джеденар в Оскверненном лесу и поговорите с лордом Гиблопустом, который находится в Оплоте Теней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя смелость и упорства не имеют себе равных, $C. Ты $Gобрел:обрела; право владеть расщепителем Нордрассила. Тебе осталось исполнить лишь одно: найти Око Тени. Найди его, даже если тебе придется обыскать весь мир.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7624,'Улатек Предатель','Хочешь заслужить мою милость? Что ж, тогда убей, кого я укажу.$b$bМой слуга, Улатек, пресмыкается передо мной, а тем временем умышляет против меня вместе с лордом Хел\'нуратом из Зорота. Хел\'нурат хочет низвергнуть меня и захватить власть, а Улатек – его шпион...$b$bДокажи, что служишь мне, а не моим противникам. Вступи в бой с Улатеком в его собственном доме, Оплоте Теней на западе. Передай ему, что мне известна его тайна. Вот увидишь, он затрясется от страха. Принеси мне сердце предателя!','Сразитесь с Улатеком и принесите сердце предателя лорду Гиблопусту в Джеденар.','Ах, как здорово. Надо дать ему погнить неделю для лучшего вкуса. И, пожалуй, я пошлю за головой Улатека и помещу ее перед собой, когда я буду есть…$B$BХорошая работа, $C. Впечатлен. Молодец.','Я уже чувствую вкус сердца Улатека на губах. Как сладка плоть предателя...','Вернитесь к лорду Гиблопусту в Оплот Теней, что в Оскверненном лесу, в Джеденаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Улатек Предатель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь заслужить мою милость? Что ж, тогда убей, кого я укажу.$b$bМой слуга, Улатек, пресмыкается передо мной, а тем временем умышляет против меня вместе с лордом Хел\'нуратом из Зорота. Хел\'нурат хочет низвергнуть меня и захватить власть, а Улатек – его шпион...$b$bДокажи, что служишь мне, а не моим противникам. Вступи в бой с Улатеком в его собственном доме, Оплоте Теней на западе. Передай ему, что мне известна его тайна. Вот увидишь, он затрясется от страха. Принеси мне сердце предателя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сразитесь с Улатеком и принесите сердце предателя лорду Гиблопусту в Джеденар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, как здорово. Надо дать ему погнить неделю для лучшего вкуса. И, пожалуй, я пошлю за головой Улатека и помещу ее перед собой, когда я буду есть…$B$BХорошая работа, $C. Впечатлен. Молодец.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я уже чувствую вкус сердца Улатека на губах. Как сладка плоть предателя...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Гиблопусту в Оплот Теней, что в Оскверненном лесу, в Джеденаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7625,'Зоротианская звездная пыль','Так ты $gявился:явилась; в поисках зоротианской звездной пыли? Ты хочешь открыть портал в Зорот, владения моего соперника Хелнурата? Уж не одного ли из его драгоценных коней погибели ты хочешь украсть?$b$bОтлично. У моего слуги, Ур\'Дана, есть большой запас зоротианской звездной пыли. Обращайся к нему... если денег хватит.','Купите зоротианскую звездную пыль у Ур\'Дана из Оплота Теней в Джеденаре, что в Оскверненном лесу. Отнесите ее Горзиеки Дикоглазу в Пылающие степи.','Да я поверить не могу! Ты $Gразобрался:разобралась; с этим Повелителем Ужаса или $Gзаплатил:заплатила; ему денег, или и то и другое! Мор\'зул получит вскоре эти чернила, и мы сможем создать свиток, и ты откроешь портал к Зороту и вытащишь через него одного из знаменитый коней погибели!','Ты уже $Gпобывал:побывала; в Джеденаре? Удалось получить звездную пыль у лорда Гиблопуста?','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зоротианская звездная пыль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так ты $gявился:явилась; в поисках зоротианской звездной пыли? Ты хочешь открыть портал в Зорот, владения моего соперника Хелнурата? Уж не одного ли из его драгоценных коней погибели ты хочешь украсть?$b$bОтлично. У моего слуги, Ур\'Дана, есть большой запас зоротианской звездной пыли. Обращайся к нему... если денег хватит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите зоротианскую звездную пыль у Ур\'Дана из Оплота Теней в Джеденаре, что в Оскверненном лесу. Отнесите ее Горзиеки Дикоглазу в Пылающие степи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да я поверить не могу! Ты $Gразобрался:разобралась; с этим Повелителем Ужаса или $Gзаплатил:заплатила; ему денег, или и то и другое! Мор\'зул получит вскоре эти чернила, и мы сможем создать свиток, и ты откроешь портал к Зороту и вытащишь через него одного из знаменитый коней погибели!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gпобывал:побывала; в Джеденаре? Удалось получить звездную пыль у лорда Гиблопуста?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7626,'Колокол Детмуры','Колокол Детмуры назвали в честь Детмуры Темноглазой. Это один из трех предметов, необходимых для создания круга Великого призыва. Сопряженный с Колесом и Свечой, он предоставит в твое распоряжение огромный запас магической энергии.$b$bМой слуга Горзиеки может создать такой колокол, но ему понадобится много эликсиров энергии Тьмы. Добудь их у алхимика и отнеси Горзиеки.','Отнесите 2 эликсира энергии Тьмы Горзиеки Дикоглазу в Пылающие степи.','Очень хорошо! Я надеюсь, что эти эликсиры было не очень сложно достать? Некоторые алхимики здорово заламывают за свои изделия.$B$BСделаю я тебе колокол и сохраню его, пока ты не будешь $Gготов:готова; к ритуалу.','У тебя есть эти эликсиры, $N? Мор\'зул сказал мне, что тебе нужен Колокол Детмуры, и для его изготовления требуется много теневой силы!','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Колокол Детмуры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Колокол Детмуры назвали в честь Детмуры Темноглазой. Это один из трех предметов, необходимых для создания круга Великого призыва. Сопряженный с Колесом и Свечой, он предоставит в твое распоряжение огромный запас магической энергии.$b$bМой слуга Горзиеки может создать такой колокол, но ему понадобится много эликсиров энергии Тьмы. Добудь их у алхимика и отнеси Горзиеки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 2 эликсира энергии Тьмы Горзиеки Дикоглазу в Пылающие степи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо! Я надеюсь, что эти эликсиры было не очень сложно достать? Некоторые алхимики здорово заламывают за свои изделия.$B$BСделаю я тебе колокол и сохраню его, пока ты не будешь $Gготов:готова; к ритуалу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть эти эликсиры, $N? Мор\'зул сказал мне, что тебе нужен Колокол Детмуры, и для его изготовления требуется много теневой силы!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7627,'Колесо Черного Похода','Колесо Черного Похода содержит в себе и направляет черную силу, необходимую для создания круга Великого призыва. Горзиеки может создать это колесо, но ему понадобятся большие сверкающие осколки, которые получают зачаровыватели, и руда черного железа, которую может добыть опытный горняк.$b$bПринеси моему слуге все необходимое.','Отнесите 6 больших сверкающих осколков и 25 кусков руды черного железа Дикоглазу в Пылающие степи.','Ага! Вот и они. Я слышал, что руда черного железа находится только в глубинах Черной Горы, и думаю там тебе пришлось нелегко, кха-кха…$B$BЛадно, к делу. Я создам колесо и придержу его, пока ты не будешь $Gготов:готова; к ритуалу.','Колесо Черного Похода трудно сделать, и для него нужно много составляющих. Ты уже их $Gсобрал:собрала;?','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Колесо Черного Похода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Колесо Черного Похода содержит в себе и направляет черную силу, необходимую для создания круга Великого призыва. Горзиеки может создать это колесо, но ему понадобятся большие сверкающие осколки, которые получают зачаровыватели, и руда черного железа, которую может добыть опытный горняк.$b$bПринеси моему слуге все необходимое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 6 больших сверкающих осколков и 25 кусков руды черного железа Дикоглазу в Пылающие степи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага! Вот и они. Я слышал, что руда черного железа находится только в глубинах Черной Горы, и думаю там тебе пришлось нелегко, кха-кха…$B$BЛадно, к делу. Я создам колесо и придержу его, пока ты не будешь $Gготов:готова; к ритуалу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Колесо Черного Похода трудно сделать, и для него нужно много составляющих. Ты уже их $Gсобрал:собрала;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7628,'Свеча Судного дня','Свеча Судного дня хранит в себе огонь, который опаляет всех, желающих прервать твой ритуал. Зажигая свечу при создании круга Великого призыва, ты сожжешь всех упрямых демонов!$b$bВпрочем, сдержать этот огонь довольно трудно, и для этого нужна чешуя черного дракона. Купи ее у мастера снятия шкур и принеси Горзиеки Дикоглазу.','Принесите 3 чешуи черного дракона Горзиеки Дикоглазу в Пылающие степи.','А, очень хорошо. Мне было это необходимо. Теперь я сделаю свечу и выдержу ее до тех пор, пока ты не будешь $Gготов:готова; начать свой ритуал круга большого призыва.','Ты несешь мне чешую дракона, $N? Я и браться не буду за изготовление свечи, пока не получу ее... а то весь лагерь может взлететь на воздух!','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свеча Судного дня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Свеча Судного дня хранит в себе огонь, который опаляет всех, желающих прервать твой ритуал. Зажигая свечу при создании круга Великого призыва, ты сожжешь всех упрямых демонов!$b$bВпрочем, сдержать этот огонь довольно трудно, и для этого нужна чешуя черного дракона. Купи ее у мастера снятия шкур и принеси Горзиеки Дикоглазу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 чешуи черного дракона Горзиеки Дикоглазу в Пылающие степи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, очень хорошо. Мне было это необходимо. Теперь я сделаю свечу и выдержу ее до тех пор, пока ты не будешь $Gготов:готова; начать свой ритуал круга большого призыва.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты несешь мне чешую дракона, $N? Я и браться не буду за изготовление свечи, пока не получу ее... а то весь лагерь может взлететь на воздух!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7629,'Доставка беса','Для подготовки пергамента Морзула осталось сделать только одно – напитать бумагу зоротианской звездной пылью. И... боюсь, здесь этого не сделать. Мне не хватит оборудования!$b$bВпрочем, я знаю об одной лаборатории, где есть все необходимое. Она находится в Некроситете, на острове Каэр Дарроу, в Чумных землях.$b$bЯ туда отправиться не смогу, но у меня есть идея. Возьми эту бутылку. В ней сидит довольно умный бес. Выпусти его в алхимической лаборатории, и он напитает пергамент звездной пылью.','Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзиеки Дикоглазу.','Славно. Д\'жииви создал пергамент. И как там в Некроситете? Прекрасно, не правда ли? А жучки там... Я слышал, они вкусные!$B$BХорошо сделано, $N, и спасибо за то, что $Gвернул:вернула; кувшин. Он у меня уже давно и не продается!','Ты был в Некроситете, $N? Неужели бес уже окутал пергамент звездной пылью?','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка беса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для подготовки пергамента Морзула осталось сделать только одно – напитать бумагу зоротианской звездной пылью. И... боюсь, здесь этого не сделать. Мне не хватит оборудования!$b$bВпрочем, я знаю об одной лаборатории, где есть все необходимое. Она находится в Некроситете, на острове Каэр Дарроу, в Чумных землях.$b$bЯ туда отправиться не смогу, но у меня есть идея. Возьми эту бутылку. В ней сидит довольно умный бес. Выпусти его в алхимической лаборатории, и он напитает пергамент звездной пылью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите беса в бутылке в алхимическую лабораторию Некроситета. После создания пергамента верните бутылку Горзиеки Дикоглазу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Славно. Д\'жииви создал пергамент. И как там в Некроситете? Прекрасно, не правда ли? А жучки там... Я слышал, они вкусные!$B$BХорошо сделано, $N, и спасибо за то, что $Gвернул:вернула; кувшин. Он у меня уже давно и не продается!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты был в Некроситете, $N? Неужели бес уже окутал пергамент звездной пылью?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7630,'Арканит','Итак, Колокол, Колесо и Свеча готовы. Осталось создать черный магнит. Он понадобится во время ритуала, поддерживать прочие объекты, на случай, если они подведут.$b$bДля создания магнита мне понадобится арканит. У тебя его нет? Коли так, поищи его у алхимика.$b$bПринеси мне арканит, и я создам черный магнит.','Принесите 1 арканитовый слиток Горзиеки в Пылающие степи.','Ага, $Gнашел:нашла; все-таки. Я всегда говорил – надо лишь по-настоящему захотеть! Теперь я могу создать магнит. Тебе он понадобится, чтобы быть $Gуверенным:уверенной; в том, что ритуал создания круга большого призыва пройдет успешно.','У тебя есть арканит, $N? Как только он у меня будет, я могу сделать из тебя черный магнит.','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Арканит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, Колокол, Колесо и Свеча готовы. Осталось создать черный магнит. Он понадобится во время ритуала, поддерживать прочие объекты, на случай, если они подведут.$b$bДля создания магнита мне понадобится арканит. У тебя его нет? Коли так, поищи его у алхимика.$b$bПринеси мне арканит, и я создам черный магнит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 арканитовый слиток Горзиеки в Пылающие степи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, $Gнашел:нашла; все-таки. Я всегда говорил – надо лишь по-настоящему захотеть! Теперь я могу создать магнит. Тебе он понадобится, чтобы быть $Gуверенным:уверенной; в том, что ритуал создания круга большого призыва пройдет успешно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть арканит, $N? Как только он у меня будет, я могу сделать из тебя черный магнит.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Горзиеки Дикоглазу на Алтарь Бурь, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7631,'Зоротианский конь погибели','Все готово. Пришло время провести ритуал создания круга Великого призыва и воспользоваться пергаментом с рунами, начертанными зоротианской звездной пылью... И отрыть портал в Зорот.$b$bВсе инструкции по проведению ритуала я записал в тот свиток. Изучи его внимательно, потому что следует делать все в точности так, как написано, или успеха не добиться.$b$bУдачи, $n. И да попадут души твоих врагов в твой мешочек осколков.','Прочтите инструкции Мор\'зула. Призовите зоротианского коня погибели, одолейте его и подчините его дух.','Дух Зоротианского коня погибели побежден. И теперь, несмотря на то, что он еще бьет огненным копытом, вы понимаете, что душа этого зверя принадлежит вам…$B$BПризрачные голоса нашептывают вам в уши и внезапно вы осознаете как надо вызывать коня погибели.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зоротианский конь погибели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все готово. Пришло время провести ритуал создания круга Великого призыва и воспользоваться пергаментом с рунами, начертанными зоротианской звездной пылью... И отрыть портал в Зорот.$b$bВсе инструкции по проведению ритуала я записал в тот свиток. Изучи его внимательно, потому что следует делать все в точности так, как написано, или успеха не добиться.$b$bУдачи, $n. И да попадут души твоих врагов в твой мешочек осколков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите инструкции Мор\'зула. Призовите зоротианского коня погибели, одолейте его и подчините его дух.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дух Зоротианского коня погибели побежден. И теперь, несмотря на то, что он еще бьет огненным копытом, вы понимаете, что душа этого зверя принадлежит вам…$B$BПризрачные голоса нашептывают вам в уши и внезапно вы осознаете как надо вызывать коня погибели.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7632,'Древний лист','Кожица листа светится ярко-зеленым. Его поверхность очень морщиниста, на ней видны многочисленные прожилки и бороздки.$B$BЕсли задуматься, то этот лист – наверняка нечто очень древнее и могущественное.$B$BМожет, поискать, кому он принадлежит?','Еще бы мне не узнать собственный лист! Смотри-ка! В великолепном состоянии.$B$BОчень мило с твоей стороны вернуть его, $C.$B$BВозможно, ты сможешь сослужить нам службу, а мы – тебе.','<Вартус кряхтит.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древний лист',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кожица листа светится ярко-зеленым. Его поверхность очень морщиниста, на ней видны многочисленные прожилки и бороздки.$B$BЕсли задуматься, то этот лист – наверняка нечто очень древнее и могущественное.$B$BМожет, поискать, кому он принадлежит?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще бы мне не узнать собственный лист! Смотри-ка! В великолепном состоянии.$B$BОчень мило с твоей стороны вернуть его, $C.$B$BВозможно, ты сможешь сослужить нам службу, а мы – тебе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Вартус кряхтит.>',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (7633,'Посвящение','Твои труды и честность уже были отмечены, $C.$B$BМы, Древние Защитники этого некогда великого леса. Наши физические формы были уничтожены 10,000 лет назад, когда Архимонд и Пылающий Легион пошли на Хиджал. Но дух наш остался нетронутым.$B$BУ нас есть задачи, которые мы можем предложить тебе, задачи, которые откроют тебе секрет Древних.$B$BЗнай, что для выполнения задания тебе нужно просто вернуться на эту гору и мы ответим тебе на твой призыв.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посвящение',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои труды и честность уже были отмечены, $C.$B$BМы, Древние Защитники этого некогда великого леса. Наши физические формы были уничтожены 10,000 лет назад, когда Архимонд и Пылающий Легион пошли на Хиджал. Но дух наш остался нетронутым.$B$BУ нас есть задачи, которые мы можем предложить тебе, задачи, которые откроют тебе секрет Древних.$B$BЗнай, что для выполнения задания тебе нужно просто вернуться на эту гору и мы ответим тебе на твой призыв.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7634,'Перетянутый жилами лист древня','Приветствую тебя, |3-6($c). Я Хастат, древо мудрости. Я храню память тысячелетий.$B$BЕсли один из моих листьев свернуть надлежащим образом, он будет служить колчаном, подобных которым не было уже 10 000 лет. Если к этому колчану в пару получить еще и лук Древ, то силе их равных не будет.$B$BПринеси мне жил взрослого синего дракона, и получишь колчан.','Хастат Древний просит вас принести ему жилу взрослого синего дракона. По выполнении задания возвращайтесь к Хастату в Оскверненный лес.','Да защитят мои листья твои стрелы! Да не ведают они промаха! Да сгинут враги нашего мира!','С возвращением, юный $C.','Вернитесь к Хастату Древнему в Железнолесье, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перетянутый жилами лист древня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($c). Я Хастат, древо мудрости. Я храню память тысячелетий.$B$BЕсли один из моих листьев свернуть надлежащим образом, он будет служить колчаном, подобных которым не было уже 10 000 лет. Если к этому колчану в пару получить еще и лук Древ, то силе их равных не будет.$B$BПринеси мне жил взрослого синего дракона, и получишь колчан.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Хастат Древний просит вас принести ему жилу взрослого синего дракона. По выполнении задания возвращайтесь к Хастату в Оскверненный лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да защитят мои листья твои стрелы! Да не ведают они промаха! Да сгинут враги нашего мира!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С возвращением, юный $C.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хастату Древнему в Железнолесье, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7635,'Подходящая тетива','Вартус, конечно, предложил тебе посох для лука Дерев, но наложить чары на тетиву, без которой лук – не лук, могу только я.$B$BЭто простое дело, совсем плевое. Убей взрослого черного дракона и добудь из него жилу. Принеси мне эту жилу, и я зачарую ее так, что тетива для лука из нее будет, считай, вечной.','Стома Древний просит вас принести ему жилу взрослого черного дракона. Добыв жилу, возвращайтесь к Стоме в Оскверненный лес.','Это был самый мерзостный из драконов. Жила просто смердит злом. Подожди немного – я очищу ее и наложу соотвествующие чары.','Я уверен, что ты без труда найдешь и убьешь черного дракона, $N. Не отнимай у меня времени пустой болтовней.','Вернитесь к Стоме Древнему в Железнолесье, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подходящая тетива',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вартус, конечно, предложил тебе посох для лука Дерев, но наложить чары на тетиву, без которой лук – не лук, могу только я.$B$BЭто простое дело, совсем плевое. Убей взрослого черного дракона и добудь из него жилу. Принеси мне эту жилу, и я зачарую ее так, что тетива для лука из нее будет, считай, вечной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Стома Древний просит вас принести ему жилу взрослого черного дракона. Добыв жилу, возвращайтесь к Стоме в Оскверненный лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это был самый мерзостный из драконов. Жила просто смердит злом. Подожди немного – я очищу ее и наложу соотвествующие чары.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я уверен, что ты без труда найдешь и убьешь черного дракона, $N. Не отнимай у меня времени пустой болтовней.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стоме Древнему в Железнолесье, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7636,'Ветвь ходячего Древа','Тайные слуги Пылающего Легиона все еще строят козни в нашем мире, |3-6($c). Они оскверняют все, к чему прикасаются. Природа чахнет и стенает от их присутствия.$B$BТы $gдолжен:должна; выследить этих демонических разносчиков порчи, $n. Помни – ты $gдолжен:должна; лично разобраться с ними – иначе сбегут. Пока ты $gодин:одна;, они будут пытаться уничтожить тебя. Ты $gдолжен:должна; сразить их, обратить их надменность в ничтожество!$B$BЯ дам тебе кусок моей коры. Письмена на ней приведут тебя к нашим врагам. Принеси мне их головы.','Вы должны найти и уничтожить следующих четверых демонических разносчиков порчи:$B$BСимон Совратительницу.$B$BКлинфрана Безумного.$B$BСоленора Убийцу.$B$BАрториуса Судьбоносного.$B$BУничтожьте этих тварей и возвращайтесь к Вартусу Древнему в Оскверненный лес с их головами.$B$BВ поисках местонахождения этих демонов сверяйтесь с окаменевшей корой.$B$BВы ОБЯЗАНЫ выполнить это задание в одиночку.','Ты хорошо $Gсослужил:сослужила; нам, $N! Возьми этот посох и объедини его с тетивой, которую умеет создавать Стома. Вместе они образуют грозное оружие.','Пусть вас не обманывают их маскировки!','Вернитесь к Вартусу Древнему в Железнолесье, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ветвь ходячего Древа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тайные слуги Пылающего Легиона все еще строят козни в нашем мире, |3-6($c). Они оскверняют все, к чему прикасаются. Природа чахнет и стенает от их присутствия.$B$BТы $gдолжен:должна; выследить этих демонических разносчиков порчи, $n. Помни – ты $gдолжен:должна; лично разобраться с ними – иначе сбегут. Пока ты $gодин:одна;, они будут пытаться уничтожить тебя. Ты $gдолжен:должна; сразить их, обратить их надменность в ничтожество!$B$BЯ дам тебе кусок моей коры. Письмена на ней приведут тебя к нашим врагам. Принеси мне их головы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вы должны найти и уничтожить следующих четверых демонических разносчиков порчи:$B$BСимон Совратительницу.$B$BКлинфрана Безумного.$B$BСоленора Убийцу.$B$BАрториуса Судьбоносного.$B$BУничтожьте этих тварей и возвращайтесь к Вартусу Древнему в Оскверненный лес с их головами.$B$BВ поисках местонахождения этих демонов сверяйтесь с окаменевшей корой.$B$BВы ОБЯЗАНЫ выполнить это задание в одиночку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хорошо $Gсослужил:сослужила; нам, $N! Возьми этот посох и объедини его с тетивой, которую умеет создавать Стома. Вместе они образуют грозное оружие.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пусть вас не обманывают их маскировки!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вартусу Древнему в Железнолесье, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7637,'Жертва необходима','Чтобы подготовиться к этому заданию, ты $Gдолжен:должна; сначала показать умение жертвовать и умение судить... в первую очередь – жертвовать.$b$bДля выполнения задания ты $Gдолжен:должна; получить курильницу экзорцизма у Верховного жреца Рохана. Несмотря на то, что ее использование будет продиктовано благими намерениями и существенными причинами, за нее должна быть предложена соответственная компенсация.$b$bОтправляйся в Стальгорн и поговори с Верховным жрецом. Если возьмешь с собой достаточно звонкой монеты, чтобы компенсировать ему потерю курильницы, ты проявишь должную готовность к жертвам.$b$bА теперь иди, $n, время терять нельзя.','Доберитесь до Стальгорна и получите курильницу экзорцизма у Верховного жреца Рохана. За курильницу нужно будет внести плату в размере 150 золотых монет.','Да пребудут на тебе все благословения, друг мой ! Твой дар далеко превосходит наши нужды. Твоя жертва не только поможет восстановить утраченное, но также позволит нам помочь самым бедным жителям Стальгорна.\n\nА теперь дай-ка я удостоверюсь, что как следует подготовил эту курильницу для твоих будущих свершений.','Приветствую тебя, благородный ! Я наполнил свою верную курильницу свежайшими благовониями и трижды благословил ее специально для тебя. Твое пожертвование поможет нам здесь, в Стальгорне, не только изготовить новую курильницу, но также пополнить оскудевающие запасы пищи для наших нужд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жертва необходима',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы подготовиться к этому заданию, ты $Gдолжен:должна; сначала показать умение жертвовать и умение судить... в первую очередь – жертвовать.$b$bДля выполнения задания ты $Gдолжен:должна; получить курильницу экзорцизма у Верховного жреца Рохана. Несмотря на то, что ее использование будет продиктовано благими намерениями и существенными причинами, за нее должна быть предложена соответственная компенсация.$b$bОтправляйся в Стальгорн и поговори с Верховным жрецом. Если возьмешь с собой достаточно звонкой монеты, чтобы компенсировать ему потерю курильницы, ты проявишь должную готовность к жертвам.$b$bА теперь иди, $n, время терять нельзя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до Стальгорна и получите курильницу экзорцизма у Верховного жреца Рохана. За курильницу нужно будет внести плату в размере 150 золотых монет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да пребудут на тебе все благословения, друг мой ! Твой дар далеко превосходит наши нужды. Твоя жертва не только поможет восстановить утраченное, но также позволит нам помочь самым бедным жителям Стальгорна.\n\nА теперь дай-ка я удостоверюсь, что как следует подготовил эту курильницу для твоих будущих свершений.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя, благородный ! Я наполнил свою верную курильницу свежайшими благовониями и трижды благословил ее специально для тебя. Твое пожертвование поможет нам здесь, в Стальгорне, не только изготовить новую курильницу, но также пополнить оскудевающие запасы пищи для наших нужд.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7638,'Лорд Грейсон Тенелом','Пришло твое время, $n, узнать о том, как найти то, что ты, без сомнения, хочешь заполучить уже в течение некоторого времени... твоего рыцарского коня.$b$bПоговори с лордом Грейсоном Тенеломом здесь, в Соборном квартале Штормграда. Именно он не только раскроет тебе все секреты самого верного паладинского скакуна, но и поможет разобраться в задачах, которые встанут перед тобой, прежде чем ты сможешь раздобыть своего собственного коня.$b$bЯ желаю тебе всего наилучшего в этом испытании. Во имя Света, $gмой благородный брат:моя благородная сестра;!','Поговорите с лордом Грейсоном Тенеломом в Соборном квартале Штормграда.','Рад тебя видеть, $N. Я знаю как ты ждешь своего коня и настало время тебе получить его.$B$BСледуй пути добра, борись со злом и твой конь будет верно служить тебе.$B$BТвое время пришло!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорд Грейсон Тенелом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло твое время, $n, узнать о том, как найти то, что ты, без сомнения, хочешь заполучить уже в течение некоторого времени... твоего рыцарского коня.$b$bПоговори с лордом Грейсоном Тенеломом здесь, в Соборном квартале Штормграда. Именно он не только раскроет тебе все секреты самого верного паладинского скакуна, но и поможет разобраться в задачах, которые встанут перед тобой, прежде чем ты сможешь раздобыть своего собственного коня.$b$bЯ желаю тебе всего наилучшего в этом испытании. Во имя Света, $gмой благородный брат:моя благородная сестра;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с лордом Грейсоном Тенеломом в Соборном квартале Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад тебя видеть, $N. Я знаю как ты ждешь своего коня и настало время тебе получить его.$B$BСледуй пути добра, борись со злом и твой конь будет верно служить тебе.$B$BТвое время пришло!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (7639,'Демонстрация истинного правосудия','Прими эту курильницу и будь $Gблагословен:благословенна;. Я сам применял ее в нескольких обрядах экзорцизма, и она хорошо послужит тебе в грядущих тяжких испытаниях.$B$BНыне возвращайся к лорду Грейсону Тенелому в Штормград, $n. Он даст тебе поручение.','Принесите курильницу экзорцизма лорду Грейсону Тенелому в Соборный квартал Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонстрация истинного правосудия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прими эту курильницу и будь $Gблагословен:благословенна;. Я сам применял ее в нескольких обрядах экзорцизма, и она хорошо послужит тебе в грядущих тяжких испытаниях.$B$BНыне возвращайся к лорду Грейсону Тенелому в Штормград, $n. Он даст тебе поручение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите курильницу экзорцизма лорду Грейсону Тенелому в Соборный квартал Штормграда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7640,'Изгнание призраков из Долины Ужаса','Я добавил в курильницу щепотку зараженной земли Долины Ужаса, что в Восточных Чумных землях. Ты $Gдолжен:должна; будешь использовать курильницу для поиска мест, которые несут на себе признаки беспокойного поведения потусторонних сил. Ищи зеленое свечение, исходящее из-под земли – так физический мир проявляет себя, мучимый миром потусторонним, и используй курильницу для вызова из-под земли злых духов.$b$bКогда свершишь суд над призраками, я поставлю перед тобой новую задачу.','Используйте курильницу экзорцизма для вызова из-под земли призраков, мучающих Долину Ужаса. Когда убьете 25 духов долины Ужаса, вернитесь к лорду Грейсону Тенелому в Соборный квартал Штормграда.','Вернитесь к лорду Грейсону Тенелому в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изгнание призраков из Долины Ужаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я добавил в курильницу щепотку зараженной земли Долины Ужаса, что в Восточных Чумных землях. Ты $Gдолжен:должна; будешь использовать курильницу для поиска мест, которые несут на себе признаки беспокойного поведения потусторонних сил. Ищи зеленое свечение, исходящее из-под земли – так физический мир проявляет себя, мучимый миром потусторонним, и используй курильницу для вызова из-под земли злых духов.$b$bКогда свершишь суд над призраками, я поставлю перед тобой новую задачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте курильницу экзорцизма для вызова из-под земли призраков, мучающих Долину Ужаса. Когда убьете 25 духов долины Ужаса, вернитесь к лорду Грейсону Тенелому в Соборный квартал Штормграда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Грейсону Тенелому в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7641,'Работа Гриманда Элмора','Без особого чепрака рыцарский конь паладина ничем не отличается от обычного скакуна. Чепрак для твоего скакуна не только должен быть изготовлен из наилучших материалов, но в силу сопутствующих обстоятельств нужно, чтобы он еще был в достаточной мере настроен на призрачный мир.$b$bНо все по порядку, $n – сначала нужно изготовить чепрак. В Квартале Дворфов Штормграда проживает один из самых лучших современных мастеров – Гриманд Элмор. Он берет за свою работу недешево, но качество его работы – как раз то, что нам нужно. Поговори с ним.','Поговорите с Гримандом Элмором в Квартале Дворфов Штормграда.','Привет-привет, паренек – лорд Победитель Тени известил меня заранее о том, что ты придешь со мной повидаться. Я с удовольствием сделаю чепрак, какой тебе нужен, но это будет нелегко, да и обойдется недешево. Я об этом говорю открыто и в первую очередь.\n\nНо, скажу я тебе – и Грейсон поддержит меня в этом утверждении – лучшего чепрака, чем изготовленный мной, ты во всем Азероте не найдешь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работа Гриманда Элмора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Без особого чепрака рыцарский конь паладина ничем не отличается от обычного скакуна. Чепрак для твоего скакуна не только должен быть изготовлен из наилучших материалов, но в силу сопутствующих обстоятельств нужно, чтобы он еще был в достаточной мере настроен на призрачный мир.$b$bНо все по порядку, $n – сначала нужно изготовить чепрак. В Квартале Дворфов Штормграда проживает один из самых лучших современных мастеров – Гриманд Элмор. Он берет за свою работу недешево, но качество его работы – как раз то, что нам нужно. Поговори с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гримандом Элмором в Квартале Дворфов Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет-привет, паренек – лорд Победитель Тени известил меня заранее о том, что ты придешь со мной повидаться. Я с удовольствием сделаю чепрак, какой тебе нужен, но это будет нелегко, да и обойдется недешево. Я об этом говорю открыто и в первую очередь.\n\nНо, скажу я тебе – и Грейсон поддержит меня в этом утверждении – лучшего чепрака, чем изготовленный мной, ты во всем Азероте не найдешь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (7642,'Сбор необходимого','Для чепрака тебе понадобятся четыре вещи: руническая ткань для подкладки, арканитовые слитки для покрытия, цветки слезы Артаса для настройки на призрачный мир и святая вода Стратхольма для духовного укрепления. На самом деле, вещей понадобится пять... если считать золото для меня. Эта плата – за весь мой труд, а также седло и стремена ручной работы.$b$bКогда наберешь все это, я смогу изготовить твой чепрак. А пока ты ищешь необходимое, я приступлю к работе.','Принесите Гриманду Элмору в Квартал Дворфов Штормграда 40 отрезов рунической ткани, 6 арканитовых слитков, 10 цветков слезы Артаса, 5 сосудов со святой водой Стратхольма и 150 золотых монет.','Это... да, это именно то, что нужно. А ты весьма находчивый , не так ли?\n\nЛадненько, давай-ка закончим с твоим чепраком!','Вернитесь к Гриманду Эльмору в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор необходимого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для чепрака тебе понадобятся четыре вещи: руническая ткань для подкладки, арканитовые слитки для покрытия, цветки слезы Артаса для настройки на призрачный мир и святая вода Стратхольма для духовного укрепления. На самом деле, вещей понадобится пять... если считать золото для меня. Эта плата – за весь мой труд, а также седло и стремена ручной работы.$b$bКогда наберешь все это, я смогу изготовить твой чепрак. А пока ты ищешь необходимое, я приступлю к работе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Гриманду Элмору в Квартал Дворфов Штормграда 40 отрезов рунической ткани, 6 арканитовых слитков, 10 цветков слезы Артаса, 5 сосудов со святой водой Стратхольма и 150 золотых монет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это... да, это именно то, что нужно. А ты весьма находчивый , не так ли?\n\nЛадненько, давай-ка закончим с твоим чепраком!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гриманду Эльмору в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7643,'Дух древнего коня','Твоему чепраку нужно особое благословение, а его можно получить только у подходящего духа. Такой дух обитает, например, в башне Забытого Города – это Дух древнего коня. Сейчас его удерживает в плену Тендрис Криводрев. Убей эту тварь, чтобы освободить духа, $n.$B$BТолько имей в виду, что просто освободить – недостаточно. Тебе нужно сначала умилостивить духа, чтобы получить его благословение. Для этого понадобится особый лошадиный корм. Ты найдешь его в Южнобережье, если поговоришь с Меридет Карлсон.','Купите лошадиный корм для Духа древнего коня у Меридет Карлсон в Южнобережье.$B$BУбейте Тендриса Криводрева в башне Забытого Города в Фераласе и освободите духа. Накормите духа кормом и получите благословление для арканитового чепрака.','Дух древнего коня обнюхал корм и чинно захрустел им. Насытившись, дух благосклонно позволил вам накинуть чепрак ему на спину.','Дух древнего коня внимательно взирает на вас – так, словно ждет чего-то.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух древнего коня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоему чепраку нужно особое благословение, а его можно получить только у подходящего духа. Такой дух обитает, например, в башне Забытого Города – это Дух древнего коня. Сейчас его удерживает в плену Тендрис Криводрев. Убей эту тварь, чтобы освободить духа, $n.$B$BТолько имей в виду, что просто освободить – недостаточно. Тебе нужно сначала умилостивить духа, чтобы получить его благословение. Для этого понадобится особый лошадиный корм. Ты найдешь его в Южнобережье, если поговоришь с Меридет Карлсон.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите лошадиный корм для Духа древнего коня у Меридет Карлсон в Южнобережье.$B$BУбейте Тендриса Криводрева в башне Забытого Города в Фераласе и освободите духа. Накормите духа кормом и получите благословление для арканитового чепрака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дух древнего коня обнюхал корм и чинно захрустел им. Насытившись, дух благосклонно позволил вам накинуть чепрак ему на спину.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дух древнего коня внимательно взирает на вас – так, словно ждет чего-то.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7644,'Благословенный арканитовый чепрак','После того как чепрак наброшен на спину духу древнего коня, он начинает чуть заметно светиться. На миг кажется, будто все вокруг звенит от напряжения и магической мощи... а потом чепрак исчезает со спины коня. Теперь он в вашем заплечном мешке.$b$bОчевидно, чепрак получил благословение. Теперь, согласно наставлениям лорда Победителя Тени, вам следует вернуться с этим чепраком к нему в Штормград.','Вернитесь вместе с благословенным арканитовым чепраком к лорду Грейсону Тенелому в Соборный квартал Штормграда.','Тебе пришлось немало постранствовать, друг мой! И вот наконец твой чепрак готов к последнему шагу, который тебе придется предпринять.\n\nЭтот чепрак пригодится тебе, чтобы седлать своего скакуна, когда труд искупления будет завершен. Однако до этого тебе снова придется вступить в тяжкую борьбу. Твой час близок!\n\nПеред этим нам нужно изготовить еще один, последний предмет. Надеюсь, твой пыл еще не иссяк?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословенный арканитовый чепрак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как чепрак наброшен на спину духу древнего коня, он начинает чуть заметно светиться. На миг кажется, будто все вокруг звенит от напряжения и магической мощи... а потом чепрак исчезает со спины коня. Теперь он в вашем заплечном мешке.$b$bОчевидно, чепрак получил благословение. Теперь, согласно наставлениям лорда Победителя Тени, вам следует вернуться с этим чепраком к нему в Штормград.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь вместе с благословенным арканитовым чепраком к лорду Грейсону Тенелому в Соборный квартал Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе пришлось немало постранствовать, друг мой! И вот наконец твой чепрак готов к последнему шагу, который тебе придется предпринять.\n\nЭтот чепрак пригодится тебе, чтобы седлать своего скакуна, когда труд искупления будет завершен. Однако до этого тебе снова придется вступить в тяжкую борьбу. Твой час близок!\n\nПеред этим нам нужно изготовить еще один, последний предмет. Надеюсь, твой пыл еще не иссяк?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7645,'Сытный манный лошадиный корм','Серебряная Длань посчитала меня ЧОКНУТОЙ, когда я сказала, что могу сделать особый конский корм, который насытит призрачных лошадей. ВСЕ считали меня чокнутой! Пришло время отыграться!$b$bЯ сделаю, что тебе надо, ПАЛАДИН... ЗАЩИТНИК, тоже мне... Но обойдется это недешево. Мне понадобится сытное манное печенье, которое продают только в Серебряном Рассвете. Кроме того я требую – да, ТРЕБУЮ, золото в качестве компенсации за перенесенные страдания!$b$bПосмотрим, многим ли ты можешь пожертвовать, ПАЛАДИН.','Принесите 20 cытных манных печений – ключевых составляющих сытного манного лошадиного корма – Меридет Карлсон в Южнобережье в предгорьях Хилсбрада. Продается печенье только в Серебряном Рассвете.$b$bКроме того, понадобится дать ей 50 золотых, чтобы успокоить ее ущемленное самолюбие.','Да, я доказала, что ты неправ? Все они ошибались! Я БЫЛА ПРАВА ВСЕ ЭТО ВРЕМЯ!!!','Вернитесь к Меридет Карлсон в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сытный манный лошадиный корм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Серебряная Длань посчитала меня ЧОКНУТОЙ, когда я сказала, что могу сделать особый конский корм, который насытит призрачных лошадей. ВСЕ считали меня чокнутой! Пришло время отыграться!$b$bЯ сделаю, что тебе надо, ПАЛАДИН... ЗАЩИТНИК, тоже мне... Но обойдется это недешево. Мне понадобится сытное манное печенье, которое продают только в Серебряном Рассвете. Кроме того я требую – да, ТРЕБУЮ, золото в качестве компенсации за перенесенные страдания!$b$bПосмотрим, многим ли ты можешь пожертвовать, ПАЛАДИН.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 cытных манных печений – ключевых составляющих сытного манного лошадиного корма – Меридет Карлсон в Южнобережье в предгорьях Хилсбрада. Продается печенье только в Серебряном Рассвете.$b$bКроме того, понадобится дать ей 50 золотых, чтобы успокоить ее ущемленное самолюбие.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, я доказала, что ты неправ? Все они ошибались! Я БЫЛА ПРАВА ВСЕ ЭТО ВРЕМЯ!!!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Меридет Карлсон в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7646,'Магический кристалл','Теперь мы должны сконструировать магический кристалл – так начнется твой подвиг и освобождение плененного духа зловещего рыцарского коня. Собственно, кристалл уже почти готов. Катализатором для него послужила курильница, которую ты $Gиспользовал:использовала;, изгоняя духов из Долины Ужаса; осталось только сделать подходящую подставку для нашего прибора.$b$bДа, и еще нужны последние два компонента – азеротский алмаз и безупречный черный алмаз. Эти два камня станут маяком, пронзающим тьму!','Принесите азеротский алмаз и безупречный черный алмаз лорду Грейсону Тенелому в Соборный квартал Штормграда.','Вернитесь к лорду Грейсону Тенелому в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магический кристалл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь мы должны сконструировать магический кристалл – так начнется твой подвиг и освобождение плененного духа зловещего рыцарского коня. Собственно, кристалл уже почти готов. Катализатором для него послужила курильница, которую ты $Gиспользовал:использовала;, изгоняя духов из Долины Ужаса; осталось только сделать подходящую подставку для нашего прибора.$b$bДа, и еще нужны последние два компонента – азеротский алмаз и безупречный черный алмаз. Эти два камня станут маяком, пронзающим тьму!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите азеротский алмаз и безупречный черный алмаз лорду Грейсону Тенелому в Соборный квартал Штормграда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Грейсону Тенелому в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7647,'Суд и расплата','Возьми эту суму – в ней собраны предметы, которые понадобятся тебе для выполнения задания.$b$bИспользуй магический кристалл в самом сердце подвала Главного склепа для вызова проклятых духов, над которыми нужно свершить суд. Во время испытания рассчитывай силы – духи могут оказаться сильнее, чем ты думаешь. После гибели духов появится сам рыцарь смерти. Срази его и верни потерянную душу рыцарского коня. Только тогда, $n, ты сможешь принести ей избавление и возложить чепрак на твоего нового скакуна.$b$bЖелаю удачи!','Используйте магический кристалл в центре подвала Главного склепа в Некроситете. Победите вызванных духов, а затем – рыцаря смерти Темного Терзателя, который появится после поражения духов.$b$bВерните падшему скакуну Темного Терзателя его спасенную душу и покройте его благословенным зачарованным чепраком.','Искорка жизни, давно покинувшей бедного зверя, сверкает в его глазах, когда ваша рука возвращает ему его спасенную душу. Вы покрываете спину скакуна чепраком и чувствуете всплеск святой силы – правосудие свершилось! Конь тыкается носом в вашу руку, как будто благодаря за избавление от груза ужасного прошлого. Вы чувствуете, что теперь у вас появился верный друг.','Дух зловещего рыцарского коня смотрит на вас тоскливым взором. В его мертвых глазах уже давно погас огонь надежды.','Вернитесь к падшему скакуну Темного Терзателя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Суд и расплата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми эту суму – в ней собраны предметы, которые понадобятся тебе для выполнения задания.$b$bИспользуй магический кристалл в самом сердце подвала Главного склепа для вызова проклятых духов, над которыми нужно свершить суд. Во время испытания рассчитывай силы – духи могут оказаться сильнее, чем ты думаешь. После гибели духов появится сам рыцарь смерти. Срази его и верни потерянную душу рыцарского коня. Только тогда, $n, ты сможешь принести ей избавление и возложить чепрак на твоего нового скакуна.$b$bЖелаю удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте магический кристалл в центре подвала Главного склепа в Некроситете. Победите вызванных духов, а затем – рыцаря смерти Темного Терзателя, который появится после поражения духов.$b$bВерните падшему скакуну Темного Терзателя его спасенную душу и покройте его благословенным зачарованным чепраком.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Искорка жизни, давно покинувшей бедного зверя, сверкает в его глазах, когда ваша рука возвращает ему его спасенную душу. Вы покрываете спину скакуна чепраком и чувствуете всплеск святой силы – правосудие свершилось! Конь тыкается носом в вашу руку, как будто благодаря за избавление от груза ужасного прошлого. Вы чувствуете, что теперь у вас появился верный друг.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дух зловещего рыцарского коня смотрит на вас тоскливым взором. В его мертвых глазах уже давно погас огонь надежды.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к падшему скакуну Темного Терзателя.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7648,'Шедевр Гриманда','<Гриманд утирает пот со лба, сияя от гордости.>$b$bГотово, $Gдруг мой:моя леди;. Это одно из моих лучших изделий – не хуже, чем тот чепрак, что я собственноручно смастерил для лорда Победителя Тени, когда он отправлялся за своим конем. Благодарю тебя за доверие.$b$bНесомненно, и сам Грейсон захочет полюбоваться на мою работу. Покажи ему чепрак и передай мою искреннюю благодарность за его достойные дела.','Покажите арканитовый чепрак лорду Грейсону Тенелому в Соборном квартале Штормграда.','Молодец! С возрастом мастерство Гриманда растет. А его изделия были одними из лучших еще в те времена, когда он делал чепрак для моего коня!\n\nЭтот чепрак слишком хорош для обычного скакуна, но нам предстоит иметь дело с необычным животным. Тебе предстоит оседлать  коня, и поэтому для чепрака нужно получить особое благословение. Ступай.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шедевр Гриманда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Гриманд утирает пот со лба, сияя от гордости.>$b$bГотово, $Gдруг мой:моя леди;. Это одно из моих лучших изделий – не хуже, чем тот чепрак, что я собственноручно смастерил для лорда Победителя Тени, когда он отправлялся за своим конем. Благодарю тебя за доверие.$b$bНесомненно, и сам Грейсон захочет полюбоваться на мою работу. Покажи ему чепрак и передай мою искреннюю благодарность за его достойные дела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите арканитовый чепрак лорду Грейсону Тенелому в Соборном квартале Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец! С возрастом мастерство Гриманда растет. А его изделия были одними из лучших еще в те времена, когда он делал чепрак для моего коня!\n\nЭтот чепрак слишком хорош для обычного скакуна, но нам предстоит иметь дело с необычным животным. Тебе предстоит оседлать  коня, и поэтому для чепрака нужно получить особое благословение. Ступай.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7649,'"Зачарованная ториевая броня", том I','Том помечен печатью Читальни.','Верните книгу законным владельцам.','$GМолодец:Умница;, $Gмой:моя; $Gмальчик:девочка;!$B$B<Сказитель Лидрос выдирает из книги одну страницу.>$B$BВот, этот чертеж тебе наверняка пригодится!','Вы ее нашли!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Зачарованная ториевая броня", том I',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Том помечен печатью Читальни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните книгу законным владельцам.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $Gмой:моя; $Gмальчик:девочка;!$B$B<Сказитель Лидрос выдирает из книги одну страницу.>$B$BВот, этот чертеж тебе наверняка пригодится!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы ее нашли!',`requestitemstext_loc8`);
