INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7660,'Обмен волками – полярный волк','Если ты принесешь мне своего старого быстрого волка, я обменяю его тебе на одного нового. Новый волк, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе волка.','Вернитесь к Огунаро Волкопасу в Азшару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обмен волками – полярный волк',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты принесешь мне своего старого быстрого волка, я обменяю его тебе на одного нового. Новый волк, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе волка.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Огунаро Волкопасу в Азшару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7661,'Обмен волками – рыжий волк','Если ты принесешь мне своего старого быстрого волка, я обменяю его тебе на одного нового. Новый волк, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе волка.','Вернитесь к Огунаро Волкопасу в Азшару.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обмен волками – рыжий волк',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты принесешь мне своего старого быстрого волка, я обменяю его тебе на одного нового. Новый волк, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе волка.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Огунаро Волкопасу в Азшару.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7662,'Новый кодо – бирюзовый','Если ты принесешь мне своего старого кодо, я обменяю тебе его на одного нового. Новый кодо, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе кодо.','Вернитесь к Харбу Точеному Копыту в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый кодо – бирюзовый',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты принесешь мне своего старого кодо, я обменяю тебе его на одного нового. Новый кодо, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе кодо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Харбу Точеному Копыту в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7663,'Новый кодо – зеленый','Если ты принесешь мне своего старого кодо, я обменяю тебе его на одного нового. Новый кодо, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе кодо.','Вернитесь к Харбу Точеному Копыту в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый кодо – зеленый',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты принесешь мне своего старого кодо, я обменяю тебе его на одного нового. Новый кодо, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе кодо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Харбу Точеному Копыту в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7664,'Новый палевый ящер','Если ты принесешь мне своего старого ящера, я обменяю тебе его на одного нового. Новый ящер, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе ящера.','Вернитесь к Зьольниру в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый палевый ящер',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты принесешь мне своего старого ящера, я обменяю тебе его на одного нового. Новый ящер, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе ящера.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зьольниру в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7665,'Новый красный ящер','Если ты принесешь мне своего старого ящера, я обменяю тебе его на одного нового. Новый ящер, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе ящера.','Вернитесь к Зьольниру в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый красный ящер',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты принесешь мне своего старого ящера, я обменяю тебе его на одного нового. Новый ящер, будет так же быстр, как и твой старый, но иметь другой вид. Ты можешь посмотреть здесь на их вид и выбрать подходящего тебе ящера.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зьольниру в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (7666,'Возвращение в Главный склеп','Ты $Gвернулся:вернулась; из Некроситета, $N? Ты уже $Gзаплатил:заплатила; большую цену за использование гадального кристалла. Может, тебе нужен еще один?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Главный склеп',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gвернулся:вернулась; из Некроситета, $N? Ты уже $Gзаплатил:заплатила; большую цену за использование гадального кристалла. Может, тебе нужен еще один?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7667,'Существенная помощь','$n, у меня есть срочное дело, и надеюсь, ты сумеешь мне помочь. Разреши, я объясню.$b$bВ глубине Некроситета в Лордероне есть здание, которое называется Главный склеп. Мне нужно изготовить устройство, которое позволит развеять зловещие тени этого жуткого места. Но чтобы его завершить, мне нужны два алмаза, азеротский и безупречный черный. Найти их не так-то просто, я знаю, но самому мне их раздобыть не под силу.$b$bНе согласишься ли ты добыть для меня эти камни?','Принесите Сагорну Гребнестраннику на Аллею Мудрости в Оргриммаре азеротский алмаз и безупречный черный алмаз.','Ага, молодец, $N. Благодарю тебя.$B$BТеперь я могу закончить гадальный кристалл. Не хочешь ли ты поучаствовать в его применении? Уверяю тебя, это для очень важного дела...','Мне так неудобно тебя просить – но для кристального предсказателя, того устройства, которое я надеюсь изготовить, требуются оба эти камня. Но, конечно, если у тебя ничего не получится, я тебя пойму...','Вернитесь к Сагорну Гривастому Страннику в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Существенная помощь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, у меня есть срочное дело, и надеюсь, ты сумеешь мне помочь. Разреши, я объясню.$b$bВ глубине Некроситета в Лордероне есть здание, которое называется Главный склеп. Мне нужно изготовить устройство, которое позволит развеять зловещие тени этого жуткого места. Но чтобы его завершить, мне нужны два алмаза, азеротский и безупречный черный. Найти их не так-то просто, я знаю, но самому мне их раздобыть не под силу.$b$bНе согласишься ли ты добыть для меня эти камни?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Сагорну Гребнестраннику на Аллею Мудрости в Оргриммаре азеротский алмаз и безупречный черный алмаз.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, молодец, $N. Благодарю тебя.$B$BТеперь я могу закончить гадальный кристалл. Не хочешь ли ты поучаствовать в его применении? Уверяю тебя, это для очень важного дела...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне так неудобно тебя просить – но для кристального предсказателя, того устройства, которое я надеюсь изготовить, требуются оба эти камня. Но, конечно, если у тебя ничего не получится, я тебя пойму...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сагорну Гривастому Страннику в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7668,'Угроза Темного Губителя','Рыцарь смерти Темный Терзатель, владычествует над Главным cклепом в Некроситете. Он собирается подчинить себе весь мир духов! Его необходимо остановить! Тут-то тебе и понадобится кристальный предсказатель.$b$bПриведи его в действие в Главном склепе, чтобы вызвать духов-приспешников Темного Терзателя. Когда ты одолеешь этих духов, явится сам рыцарь смерти. Принеси мне его голову, $n! Только его гибель способна исправить урон, нанесенный миру духов!','Используйте кристальный предсказатель в Главном склепе в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.$b$bПринесите голову Темного Терзателя Сагорну Гривастому Страннику на Аллею Мудрости Оргриммара.','Вернитесь к Сагорну Гривастому Страннику в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза Темного Губителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыцарь смерти Темный Терзатель, владычествует над Главным cклепом в Некроситете. Он собирается подчинить себе весь мир духов! Его необходимо остановить! Тут-то тебе и понадобится кристальный предсказатель.$b$bПриведи его в действие в Главном склепе, чтобы вызвать духов-приспешников Темного Терзателя. Когда ты одолеешь этих духов, явится сам рыцарь смерти. Принеси мне его голову, $n! Только его гибель способна исправить урон, нанесенный миру духов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте кристальный предсказатель в Главном склепе в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.$b$bПринесите голову Темного Терзателя Сагорну Гривастому Страннику на Аллею Мудрости Оргриммара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сагорну Гривастому Страннику в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (7669,'Возвращение в Главный склеп') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Главный склеп',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7670,'Лорд Грейсон Тенелом','$n, пришла пора узнать, что потребуется от тебя, дабы получить предмет твоих давних мечтаний, а именно... боевого скакуна.$B$BПоговори с лордом Грейсоном Тенеломом в Соборном квартале Штормграда. Он не только наставит тебя в обращении с самым верным товарищем паладина, но и даст тебе задачу, прежде чем ты получишь своего скакуна.$B$BЖелаю тебе успешно пройти это испытание. Во имя Света, $Gблагородный брат:благородная сестра;!','Поговорите с лордом Грейсоном Тенеломом в Соборном квартале Штормграда.','Рад видеть тебя, $n. Я знаю, что ты ждал от меня наставлений, как добыть себе скакуна, и теперь час настал.\n\nТебе, несомненно, придется подвергаться разным испытаниям, но самое важное – испытание твоей готовности идти вперед вопреки любым препятствиям, что станут у тебя на пути. Это не учебные упражнения – твоя стать уже не для простых учебных испытаний. Тебе придется спасти твоего будущего товарища из лап зла, с которым тебе предстоит сражаться всю жизнь.\n\nВнемли же, твой час пришел!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорд Грейсон Тенелом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, пришла пора узнать, что потребуется от тебя, дабы получить предмет твоих давних мечтаний, а именно... боевого скакуна.$B$BПоговори с лордом Грейсоном Тенеломом в Соборном квартале Штормграда. Он не только наставит тебя в обращении с самым верным товарищем паладина, но и даст тебе задачу, прежде чем ты получишь своего скакуна.$B$BЖелаю тебе успешно пройти это испытание. Во имя Света, $Gблагородный брат:благородная сестра;!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с лордом Грейсоном Тенеломом в Соборном квартале Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад видеть тебя, $n. Я знаю, что ты ждал от меня наставлений, как добыть себе скакуна, и теперь час настал.\n\nТебе, несомненно, придется подвергаться разным испытаниям, но самое важное – испытание твоей готовности идти вперед вопреки любым препятствиям, что станут у тебя на пути. Это не учебные упражнения – твоя стать уже не для простых учебных испытаний. Тебе придется спасти твоего будущего товарища из лап зла, с которым тебе предстоит сражаться всю жизнь.\n\nВнемли же, твой час пришел!',`offerrewardtext_loc8`);
