INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7701,'РАЗЫСКИВАЕТСЯ: надзиратель Мальторий','Именем его светлости надзирателя Скользорука должно убить агента Братства Тория надзирателя Мальтория, командира подразделения Шлаковой Ямы войск Черного Железа в Котловане. Его голову должно принести в качестве доказательства. $B$BЗа наградой обращаться к дозорному капитану Лоло Долгобою.','Дворф Черного Железа, вероломный надзиратель Мальторий, скрывается в глубине Шлаковой Ямы в Котловане, что в Тлеющем ущелье. $B$BУбейте надзирателя Мальтория и принесите его голову дозорному капитану Лоло Долгобою.','Я никогда не думал, что посмотрю на эту рожу еще раз!$B$BОна выглядит лучше без остальной части к которой прикреплена.$B$BВот твоя награда *ик*, $R.','Ты не видишь, что я занят? Что <ик> ты от меня хочешь? <ик>','Вернитесь к капитану дозорных Лоло Долгобою в Лагерь Братства Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РАЗЫСКИВАЕТСЯ: надзиратель Мальторий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Именем его светлости надзирателя Скользорука должно убить агента Братства Тория надзирателя Мальтория, командира подразделения Шлаковой Ямы войск Черного Железа в Котловане. Его голову должно принести в качестве доказательства. $B$BЗа наградой обращаться к дозорному капитану Лоло Долгобою.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дворф Черного Железа, вероломный надзиратель Мальторий, скрывается в глубине Шлаковой Ямы в Котловане, что в Тлеющем ущелье. $B$BУбейте надзирателя Мальтория и принесите его голову дозорному капитану Лоло Долгобою.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я никогда не думал, что посмотрю на эту рожу еще раз!$B$BОна выглядит лучше без остальной части к которой прикреплена.$B$BВот твоя награда *ик*, $R.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты не видишь, что я занят? Что <ик> ты от меня хочешь? <ик>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану дозорных Лоло Долгобою в Лагерь Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7702,'Казнь через лишение сна','Чтобы подорвать силы Черного Железа в Шлаковой Яме, необходимо нанести удар по самому уязвимому месту. $B$BОткрою тебе секрет: дворфы, а особенно дворфы Черного Железа, крайне нуждаются в регулярном отдыхе. Хорошем отдыхе! $B$BТак вот скажи мне, как они смогут спать, если у них не будет подушек? Правильно! Никак. Поэтому надо прокрасться в Шлаковую Яму и стянуть все их подушки!','Найдите спальные кварталы дворфов Черного Железа в глубине Шлаковой Ямы, что в Котловане. $B$BУкрадите 20 подушек дворфов Черного Железа. По выполнении задания вернитесь к Эвонис Сажекурке.','По крайней мере, на сей раз – что-то интересное. Оно излучает странную силу...','Это ты опять? Не хватало мне очередной порции жалости Тор\'гана.$B$BЧто ты $Gпринес:принесла; на этот раз? Может, цветную ниточку? Или, может, веревку, чтобы я мог покончить со своим жалким существованием?..','Вернитесь к Эвонис Сажекурке в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Казнь через лишение сна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы подорвать силы Черного Железа в Шлаковой Яме, необходимо нанести удар по самому уязвимому месту. $B$BОткрою тебе секрет: дворфы, а особенно дворфы Черного Железа, крайне нуждаются в регулярном отдыхе. Хорошем отдыхе! $B$BТак вот скажи мне, как они смогут спать, если у них не будет подушек? Правильно! Никак. Поэтому надо прокрасться в Шлаковую Яму и стянуть все их подушки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите спальные кварталы дворфов Черного Железа в глубине Шлаковой Ямы, что в Котловане. $B$BУкрадите 20 подушек дворфов Черного Железа. По выполнении задания вернитесь к Эвонис Сажекурке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','По крайней мере, на сей раз – что-то интересное. Оно излучает странную силу...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это ты опять? Не хватало мне очередной порции жалости Тор\'гана.$B$BЧто ты $Gпринес:принесла; на этот раз? Может, цветную ниточку? Или, может, веревку, чтобы я мог покончить со своим жалким существованием?..',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эвонис Сажекурке в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7703,'Неоконченное дело Гордоков','Ну, раз ты теперь король, может, попробуешь добыть сокровище Гордоков у того паскудного эльфа, который называет себя принцем, а? Тот король, что был до тебя, это дело профукал – так же, как и все прочие короли до него, с тех самых пор, как Тортелдрин, тот паскудный эльф, спер его у одного из королей!$b$bА вещица-то была ценная: латная рукавица Мощи Гордока! И в старых байках говорится, что воротить ее сможет только настоящий король Гордок. А еще говорится, что паскудный эльф до сих пор шляется где-то тут. Отыщи его, и будет тебе крутая рукавица, которую ты будешь носить по гроб жизни!','Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.$b$bПо словам Давигрома, в "старых байках" говорится, что Тортелдрин – "страшный эльф", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков.','Да ты ВПРАВДУ $Gкороль:королева;! Я никогда не видел такой рукавицы еще!$B$BГлянь, та марка на рукавице, это же старая магическая марка, которая старше чем весь Гордок. Как капитан Гордока я тебе говорю, что мы знаем как вернуть мощь в эту рукавицу!$B$BЯ делаю это для тебя, $Gкороль:королева;! Бери эту рукавицу и правь НАВСЕГДА!','А, начальник! Ну че, $Gнашел:нашла; рукавицу? Может, старые байки-то врут? Че-то как-то не верится, что паскудный эльф мог что-то спереть у короля Гордока!','Вернитесь к капитану Давигрому на Остров Фенриса, что в Серебряном бору.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неоконченное дело Гордоков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, раз ты теперь король, может, попробуешь добыть сокровище Гордоков у того паскудного эльфа, который называет себя принцем, а? Тот король, что был до тебя, это дело профукал – так же, как и все прочие короли до него, с тех самых пор, как Тортелдрин, тот паскудный эльф, спер его у одного из королей!$b$bА вещица-то была ценная: латная рукавица Мощи Гордока! И в старых байках говорится, что воротить ее сможет только настоящий король Гордок. А еще говорится, что паскудный эльф до сих пор шляется где-то тут. Отыщи его, и будет тебе крутая рукавица, которую ты будешь носить по гроб жизни!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте латную рукавицу Мощи Гордока и вернитесь с ней к капитану Давигрому в Забытом Городе.$b$bПо словам Давигрома, в "старых байках" говорится, что Тортелдрин – "страшный эльф", называющий себя принцем, – похитил эту рукавицу у одного из королей Гордоков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да ты ВПРАВДУ $Gкороль:королева;! Я никогда не видел такой рукавицы еще!$B$BГлянь, та марка на рукавице, это же старая магическая марка, которая старше чем весь Гордок. Как капитан Гордока я тебе говорю, что мы знаем как вернуть мощь в эту рукавицу!$B$BЯ делаю это для тебя, $Gкороль:королева;! Бери эту рукавицу и правь НАВСЕГДА!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, начальник! Ну че, $Gнашел:нашла; рукавицу? Может, старые байки-то врут? Че-то как-то не верится, что паскудный эльф мог что-то спереть у короля Гордока!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Давигрому на Остров Фенриса, что в Серебряном бору.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (7704,'Размер имеет значение','Ну и ну... Вот так сюрприз! У горничной была огромная вышитая подушка, и вот теперь она в ваших руках. Эвонис Сажекурке непременно захочет заполучить ее. Посмотрим, что она сможет предложить взамен...','Отнесите подушку горничной Крепкие Тиски Эвонис Сажекурке в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Размер имеет значение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну и ну... Вот так сюрприз! У горничной была огромная вышитая подушка, и вот теперь она в ваших руках. Эвонис Сажекурке непременно захочет заполучить ее. Посмотрим, что она сможет предложить взамен...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите подушку горничной Крепкие Тиски Эвонис Сажекурке в Тлеющее ущелье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7721,'Энергия для уменьшения','Если я поступлю вопреки доводам разума, и все же буду по-прежнему содержать инженерную мастерскую на Забытом берегу, мне нужно будет как-то разобраться с этими зловредными элементалями. Чтоб им провалиться, этим необузданным стихиям!$b$bНо как повезло мне – а теперь и вам, $Gмой уважаемый помощник:моя уважаемая помощница;! Ведь эти элементали представляют собой идеальный источник энергии для моего ультрасжимателя! Так что ликвидируйте их, не стесняясь, только, смотрите, не выбрасывайте ядра элементалей воды!','Соберите 10 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта.','Отличнобалденнейше! Уж я с этими ядрами теперь поработаю! Да и элементалей на берегу теперь стало поменьше, так что больше не придется засыпать в слезах от мысли, что я устроил свою лавку в наихудшем месте, какое только можно себе представить!$B$BСпасибо, $N, спасибо за все твои старания! Хоть я сейчас и не в самом лучшем финансовом положении, но все же прими от меня понятную и полезную для тебя благодарность: ценности!','Я не стану докучать вам техническими подробностями и объяснениями, для чего мне эти ядра. Я лучше намекну, что, выполнив эту важную задачу, вы получите кругленькую сумму, и еще кое-что полезное в придачу. Ну что, где мои ядра?','Вернитесь к Зорбину Дребезгуну на Забытый берег, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Энергия для уменьшения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если я поступлю вопреки доводам разума, и все же буду по-прежнему содержать инженерную мастерскую на Забытом берегу, мне нужно будет как-то разобраться с этими зловредными элементалями. Чтоб им провалиться, этим необузданным стихиям!$b$bНо как повезло мне – а теперь и вам, $Gмой уважаемый помощник:моя уважаемая помощница;! Ведь эти элементали представляют собой идеальный источник энергии для моего ультрасжимателя! Так что ликвидируйте их, не стесняясь, только, смотрите, не выбрасывайте ядра элементалей воды!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличнобалденнейше! Уж я с этими ядрами теперь поработаю! Да и элементалей на берегу теперь стало поменьше, так что больше не придется засыпать в слезах от мысли, что я устроил свою лавку в наихудшем месте, какое только можно себе представить!$B$BСпасибо, $N, спасибо за все твои старания! Хоть я сейчас и не в самом лучшем финансовом положении, но все же прими от меня понятную и полезную для тебя благодарность: ценности!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не стану докучать вам техническими подробностями и объяснениями, для чего мне эти ядра. Я лучше намекну, что, выполнив эту важную задачу, вы получите кругленькую сумму, и еще кое-что полезное в придачу. Ну что, где мои ядра?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зорбину Дребезгуну на Забытый берег, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7722,'Какой еще плавень?','Когда этот негодяй Мальторий покинул клан, он унес с собой кое-что поважнее безупречнейшего чародейского кристалла. Он украл рецепт огненного плавня! Полагаю, это была его возможность выслужиться у дворфов Черного Железа. $B$BВерни нам эти секретные документы, $n. Мальторий наверняка держит их при себе, там, в Шлаковой Яме.','Верните секретные документы по изготовлению огненного плавня, украденные надзирателем Мальторием. Инспектор скорее всего находится в Шлаковой Яме в Котловане. Документы верните мастеру-кузнецу Закалону в Тлеющем ущелье.','Я надеюсь, что ты $Gвыбил:выбила; ему зубы, $N. Рагнарос знает, он это заслужил.$B$BТеперь мы можем приступить к делу.','Ты $Gнашел:нашла; планы?','Вернитесь к мастеру-кузнецу Закалону в Лагерь Братства Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Какой еще плавень?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда этот негодяй Мальторий покинул клан, он унес с собой кое-что поважнее безупречнейшего чародейского кристалла. Он украл рецепт огненного плавня! Полагаю, это была его возможность выслужиться у дворфов Черного Железа. $B$BВерни нам эти секретные документы, $n. Мальторий наверняка держит их при себе, там, в Шлаковой Яме.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните секретные документы по изготовлению огненного плавня, украденные надзирателем Мальторием. Инспектор скорее всего находится в Шлаковой Яме в Котловане. Документы верните мастеру-кузнецу Закалону в Тлеющем ущелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я надеюсь, что ты $Gвыбил:выбила; ему зубы, $N. Рагнарос знает, он это заслужил.$B$BТеперь мы можем приступить к делу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; планы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру-кузнецу Закалону в Лагерь Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7723,'Будь прокляты эти толстые пальцы','К несчастью, я уже не способен на столь меткие удары, как раньше, из-за проблем с пальцами. Виноват климат и низкое атмосферное давление – пальцы здесь отекают и становятся похожими на телcамарские кровяные колбаски... $B$BТак что придется тебе поработать за меня: вышиби дух из боевых големов, которых найдешь в ущелье.','А ты $Gхороший:хорошая; $Gпарень:девушка;. У меня для тебя есть небольшой подарок.','Ты $Gразмазал:размазала; их.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Будь прокляты эти толстые пальцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К несчастью, я уже не способен на столь меткие удары, как раньше, из-за проблем с пальцами. Виноват климат и низкое атмосферное давление – пальцы здесь отекают и становятся похожими на телcамарские кровяные колбаски... $B$BТак что придется тебе поработать за меня: вышиби дух из боевых големов, которых найдешь в ущелье.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А ты $Gхороший:хорошая; $Gпарень:девушка;. У меня для тебя есть небольшой подарок.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gразмазал:размазала; их.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7724,'Огненная угроза','Как только старый Хансел собирается отдохнуть, нелегкая подбрасывает ему еще работенки... $B$BВот, пожалуйста, теперь большие лавовые пауки добавили проблем! Скользорук говорит, его храбрецы чуть ли не из пушек от них отстреливались... $B$BКороче, чтобы зря не пугать детишек и наших доблестных вояк, надо бы найти на пауков управу. Уверен, ты справишься.','<Хансел чихает.>$B$BКажется я замерз. Проклятый холодный климат!','Был ли он прав? А нет ли их огузок?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огненная угроза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только старый Хансел собирается отдохнуть, нелегкая подбрасывает ему еще работенки... $B$BВот, пожалуйста, теперь большие лавовые пауки добавили проблем! Скользорук говорит, его храбрецы чуть ли не из пушек от них отстреливались... $B$BКороче, чтобы зря не пугать детишек и наших доблестных вояк, надо бы найти на пауков управу. Уверен, ты справишься.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Хансел чихает.>$B$BКажется я замерз. Проклятый холодный климат!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Был ли он прав? А нет ли их огузок?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7725,'Еще раз ослабим великанов','Я знаю, ты уже $gсобирал:собирала; для меня остатки миниатюризации... но, если тебе захочется снова поразвлечься, имей в виду: мне всегда нужны новые остатки!$b$bРазумеется, такого большого вознаграждения, как раньше, я больше предложить не смогу, но зато я всегда буду рад замолвить за тебя словечко перед своими друзьями-гоблинами.$b$bПоверь мне, $gпутник:путешественница;: гоблины к подобным отзывам прислушиваются чрезвычайно внимательно!','Используйте ультрасжиматель Зорбина, чтобы уменьшить великанов любого вида, каких вы найдете в Фераласе. Принесите 10 порций остаточного вещества Зорбину Дребезгуну в порт Забытого берега в Фераласе.','Практически немыслимо, $N! Ты снова $Gсделал:сделала; это и я снова благодарю тебя! Спасибо! Может быть, ты найдешь эту оплату менее большой, но знай, что ты $Gполучил:получила; большее, чем деньги – а именно уважение Картеля Хитрой Шестеренки. Если чего надо – обращайся ко мне, поможем.','Ах, вот они, плоды исследований и разумной утилизации: мои сладенькие остаточки! Нет-нет, вы только не подумайте, будто я пробую их на вкус!$B$BЯ такого почти никогда не делаю.','Вернитесь к Зорбину Дребезгуну на Забытый берег, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще раз ослабим великанов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, ты уже $gсобирал:собирала; для меня остатки миниатюризации... но, если тебе захочется снова поразвлечься, имей в виду: мне всегда нужны новые остатки!$b$bРазумеется, такого большого вознаграждения, как раньше, я больше предложить не смогу, но зато я всегда буду рад замолвить за тебя словечко перед своими друзьями-гоблинами.$b$bПоверь мне, $gпутник:путешественница;: гоблины к подобным отзывам прислушиваются чрезвычайно внимательно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте ультрасжиматель Зорбина, чтобы уменьшить великанов любого вида, каких вы найдете в Фераласе. Принесите 10 порций остаточного вещества Зорбину Дребезгуну в порт Забытого берега в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Практически немыслимо, $N! Ты снова $Gсделал:сделала; это и я снова благодарю тебя! Спасибо! Может быть, ты найдешь эту оплату менее большой, но знай, что ты $Gполучил:получила; большее, чем деньги – а именно уважение Картеля Хитрой Шестеренки. Если чего надо – обращайся ко мне, поможем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ах, вот они, плоды исследований и разумной утилизации: мои сладенькие остаточки! Нет-нет, вы только не подумайте, будто я пробую их на вкус!$B$BЯ такого почти никогда не делаю.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зорбину Дребезгуну на Забытый берег, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7726,'Новая энергия для уменьшения','О, вы не прочь снова поработать? Так героическое собирание кусков слизи, выпавших из тел элементалей, не утолило вашей жажды приключений? Ну, тогда вы, наверное, не огорчитесь, если я снова дам вам то же самое поручение?$b$bЛадно, шутки в сторону: мне нужны новые ядра элементалей воды. Но имейте в виду: сейчас почти все мои средства уходят на обустройство мастерской, так что награда, возможно, будет не столь велика... Зато обещаю вам, что расскажу всем своим ближним и дальним знакомым о том, как вы мне помогли! А у меня масса знакомых в картеле!','Соберите 6 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта.','Высший пилотаж, $N! Вот награда... Что значит мало? А репутация в нашем картеле? Поверь, она дорогого стоит!$B$BЕсли понадобится работенка, заглядывай! Мне всегда пригодятся ядро элементаля и прочее.','Ну что, удалось вам добыть то, о чем я просил?','Вернитесь к Зорбину Дребезгуну на Забытый берег, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая энергия для уменьшения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, вы не прочь снова поработать? Так героическое собирание кусков слизи, выпавших из тел элементалей, не утолило вашей жажды приключений? Ну, тогда вы, наверное, не огорчитесь, если я снова дам вам то же самое поручение?$b$bЛадно, шутки в сторону: мне нужны новые ядра элементалей воды. Но имейте в виду: сейчас почти все мои средства уходят на обустройство мастерской, так что награда, возможно, будет не столь велика... Зато обещаю вам, что расскажу всем своим ближним и дальним знакомым о том, как вы мне помогли! А у меня масса знакомых в картеле!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 ядер элементалей воды, убивая морских элементалей и морских валов на Забытом берегу в Фераласе, и принесите их Зорбину Дребезгуну, который находится неподалеку от порта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Высший пилотаж, $N! Вот награда... Что значит мало? А репутация в нашем картеле? Поверь, она дорогого стоит!$B$BЕсли понадобится работенка, заглядывай! Мне всегда пригодятся ядро элементаля и прочее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось вам добыть то, о чем я просил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зорбину Дребезгуну на Забытый берег, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7727,'Пламезавры? Ну и название...','Бедные мои ножки... У меня бурсит, $gмолодой человек:милочка;. Да, большие шишки всегда наживают себе шишки. Ну и как мне заниматься истреблением всяких тварей, если пальцы моих ног в таком плачевном состоянии? В общем, тут-то ты мне и поможешь! $B$BСкрендж и Закалон хотят, чтобы я поубивал этих проклятых ящеров, чтобы расчистить путь для их исследовательских отрядов. Они, вишь ты, желают изучать озера лавы в Шлаковой Яме. А всякие пламезавры и прочие завры им, вишь ты, мешают. В общем, придется тебе направиться в Шлаковую Яму и слегка ускорить вымирание этих монстров.','Ох, мои ноги…$B$BЯ понимаю, что у тебя еще не было Люфы...','<Гензель деловито растирает косточки.>$B$BНе стойте просто так, возьмите немного масла и люффу и начните чистить эти бурситы.$B$BУ тебя нет люффы? Ну тогда! Может, пора послать тебя на поиски луффы?$B$BЭй, ты куда?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пламезавры? Ну и название...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бедные мои ножки... У меня бурсит, $gмолодой человек:милочка;. Да, большие шишки всегда наживают себе шишки. Ну и как мне заниматься истреблением всяких тварей, если пальцы моих ног в таком плачевном состоянии? В общем, тут-то ты мне и поможешь! $B$BСкрендж и Закалон хотят, чтобы я поубивал этих проклятых ящеров, чтобы расчистить путь для их исследовательских отрядов. Они, вишь ты, желают изучать озера лавы в Шлаковой Яме. А всякие пламезавры и прочие завры им, вишь ты, мешают. В общем, придется тебе направиться в Шлаковую Яму и слегка ускорить вымирание этих монстров.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, мои ноги…$B$BЯ понимаю, что у тебя еще не было Люфы...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Гензель деловито растирает косточки.>$B$BНе стойте просто так, возьмите немного масла и люффу и начните чистить эти бурситы.$B$BУ тебя нет люффы? Ну тогда! Может, пора послать тебя на поиски луффы?$B$BЭй, ты куда?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7728,'УКРАДЕНО: фурма и подзорная труба наблюдателя','Внимание, украдены следующие предметы: $B$B*Фурма Черного Железа – одна штука. $B$B*Подзорная труба наблюдателя – одна штука. $B$BПросьба вернуть за вознаграждение. $B$BБратство Тория точно знает, что эти предметы были украдены беспринципными и завистливыми дворфами Черного Железа из Тлеющего ущелья. $B$BПодзорная труба была великолепным прибором для наблюдения, а фурма – просто незаменимый инструмент. $B$BНашедшему просьба вернуть указанные вещи Скренджу.','Найдите и верните фурму и подзорную трубу наблюдателя надсмотрщику Скренджу в Тлеющем ущелье. Единственная известная информация: вещи были украдены дворфами Черного Железа. Подзорная труба является бесценным прибором для наблюдения, а фурма – незаменимым кузнечным инструментом.','Фантастическая работа! Вот твоя награда.','Если ты $Gпришел:пришла; за наградой, то где украденные предметы?','Вернитесь к надсмотрщику Скренджу в Лагерь Братства Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','УКРАДЕНО: фурма и подзорная труба наблюдателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимание, украдены следующие предметы: $B$B*Фурма Черного Железа – одна штука. $B$B*Подзорная труба наблюдателя – одна штука. $B$BПросьба вернуть за вознаграждение. $B$BБратство Тория точно знает, что эти предметы были украдены беспринципными и завистливыми дворфами Черного Железа из Тлеющего ущелья. $B$BПодзорная труба была великолепным прибором для наблюдения, а фурма – просто незаменимый инструмент. $B$BНашедшему просьба вернуть указанные вещи Скренджу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и верните фурму и подзорную трубу наблюдателя надсмотрщику Скренджу в Тлеющем ущелье. Единственная известная информация: вещи были украдены дворфами Черного Железа. Подзорная труба является бесценным прибором для наблюдения, а фурма – незаменимым кузнечным инструментом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фантастическая работа! Вот твоя награда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты $Gпришел:пришла; за наградой, то где украденные предметы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надсмотрщику Скренджу в Лагерь Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7729,'ВАКАНСИЯ: устранитель конкурентов','Надсмотрщику Скренджу требуется опытный кандидат на должность устранителя конкурентов в Тлеющем ущелье. Пол неважен. $B$BЕсли вы считаете, что ваша квалификация достаточна для этой должности, отправляйтесь в Тлеющее ущелье и уничтожьте всех встреченных вами надсмотрщиков Черного Железа и работорговцев Черного Железа. $B$BВозвращайтесь к надсмотрщику Скренджу, когда ваша одежда пропитается кровью. $B$BСами поймете, когда настанет момент, так что вопросов не задавать.','Убейте 15 надсмотрщиков и 15 поработителей из клана Черного Железа. По выполнении задания вернитесь к десятнику Скренджу в Тлеющее ущелье.','15.9 фунтов! Это новый рекорд для веса крови и кишек на одежде! Поздравляю, $C!','Нам нужно взвесить тебя с одеждой и без неё, что бы быть уверенными.','Вернитесь к надсмотрщику Скренджу в Лагерь Братства Тория, что в Тлеющем ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ВАКАНСИЯ: устранитель конкурентов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надсмотрщику Скренджу требуется опытный кандидат на должность устранителя конкурентов в Тлеющем ущелье. Пол неважен. $B$BЕсли вы считаете, что ваша квалификация достаточна для этой должности, отправляйтесь в Тлеющее ущелье и уничтожьте всех встреченных вами надсмотрщиков Черного Железа и работорговцев Черного Железа. $B$BВозвращайтесь к надсмотрщику Скренджу, когда ваша одежда пропитается кровью. $B$BСами поймете, когда настанет момент, так что вопросов не задавать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 надсмотрщиков и 15 поработителей из клана Черного Железа. По выполнении задания вернитесь к десятнику Скренджу в Тлеющее ущелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','15.9 фунтов! Это новый рекорд для веса крови и кишек на одежде! Поздравляю, $C!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам нужно взвесить тебя с одеждой и без неё, что бы быть уверенными.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надсмотрщику Скренджу в Лагерь Братства Тория, что в Тлеющем ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7730,'Нападение на улей Зукк\'аш','Судя по сведениям, полученным с помощью разведки, враги, теснящие гноллов с юга, – это раса насекомоподобных существ. Неизвестно, разумны ли они – но, откровенно говоря, это и неважно. Если гноллы их так боятся, что предпочитают переть на нас, значит, эти твари так же опасны, как гноллы, а может, и еще опаснее.$b$bПроникни в те места, где обитают эти насекомые, Зукк\'аш. Это место называется "Гудящая Бездна". Постарайся уменьшить их численность, и доложи мне о том, что увидишь. В доказательство своих свершений принеси мне их панцири!','Принесите 20 панцирей Зукк\'аш Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе.','Молодец, $C! Конечно, отпугнуть этих насекомых тебе не удалось – их не проймешь ничем, кроме полномасштабной военной кампании. Однако с твоей помощью мы сумеем выиграть время, чтобы разработать должную стратегию.$B$BЯ велю изучить эти панцири – нам нужно узнать об этих тварях как можно больше, прежде чем бороться с тем, что оказалось куда более сложной задачей, нежели мы предполагали.','Ну что, $N, как охота? Ты здесь, чтобы доложить о своих успехах?','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нападение на улей Зукк\'аш',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по сведениям, полученным с помощью разведки, враги, теснящие гноллов с юга, – это раса насекомоподобных существ. Неизвестно, разумны ли они – но, откровенно говоря, это и неважно. Если гноллы их так боятся, что предпочитают переть на нас, значит, эти твари так же опасны, как гноллы, а может, и еще опаснее.$b$bПроникни в те места, где обитают эти насекомые, Зукк\'аш. Это место называется "Гудящая Бездна". Постарайся уменьшить их численность, и доложи мне о том, что увидишь. В доказательство своих свершений принеси мне их панцири!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 панцирей Зукк\'аш Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $C! Конечно, отпугнуть этих насекомых тебе не удалось – их не проймешь ничем, кроме полномасштабной военной кампании. Однако с твоей помощью мы сумеем выиграть время, чтобы разработать должную стратегию.$B$BЯ велю изучить эти панцири – нам нужно узнать об этих тварях как можно больше, прежде чем бороться с тем, что оказалось куда более сложной задачей, нежели мы предполагали.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $N, как охота? Ты здесь, чтобы доложить о своих успехах?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7731,'Жалохвост','Один из разведчиков, исследовавших Гудящую Бездну, доложил о виденном им гигантском насекомом – куда более крупном, чем все остальные замеченные им насекомые. Помимо необычных размеров, оно, по-видимому, окружено какой-то особой аурой, которой у прочих насекомых нет. Мы назвали его жалохвостом. $b$bНам хотелось бы изучить внутренности этой твари, чтобы понять, как лучше бороться с этой новой угрозой. Добудь ядовитые железы жалохвоста и принеси их мне!','Убейте жалохвоста в Гудящей Бездне и принести железы ядохлеста Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе.','Поразительно, $C… просто поразительно! Если Жалохвост и впрямь один из сильнейших представителей своего вида, изучение этой твари окажется более чем важным и своевременным. Теперь моя задача – сделать так, чтобы мы продержались достаточно долго и смогли воспользоваться нашими новыми знаниями.$B$BПрими это денежное вознаграждение в знак признательности всего населения лагеря, $N.','Ну что, удалось тебе одолеть жалохвоста?','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жалохвост',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из разведчиков, исследовавших Гудящую Бездну, доложил о виденном им гигантском насекомом – куда более крупном, чем все остальные замеченные им насекомые. Помимо необычных размеров, оно, по-видимому, окружено какой-то особой аурой, которой у прочих насекомых нет. Мы назвали его жалохвостом. $b$bНам хотелось бы изучить внутренности этой твари, чтобы понять, как лучше бороться с этой новой угрозой. Добудь ядовитые железы жалохвоста и принеси их мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте жалохвоста в Гудящей Бездне и принести железы ядохлеста Хадокену Быстрому Страннику в Лагерь Мохаче в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поразительно, $C… просто поразительно! Если Жалохвост и впрямь один из сильнейших представителей своего вида, изучение этой твари окажется более чем важным и своевременным. Теперь моя задача – сделать так, чтобы мы продержались достаточно долго и смогли воспользоваться нашими новыми знаниями.$B$BПрими это денежное вознаграждение в знак признательности всего населения лагеря, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе одолеть жалохвоста?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хадокену Быстрому Страннику в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7732,'Донесение об улье Зукк\'аш','Ты поступаешь весьма разумно, направляя свои усилия на борьбу с этими насекомыми, грозящими Лагерю Мохаче. Опасность далеко еще не миновала, и мне хотелось бы попросить тебя оказать Орде еще одну услугу. Вот в этих бумагах изложены все сведения об улье Зукк\'аш, которые нам удалось раздобыть. Прошу тебя доставить их Зилзибину Барабанному Бою на Волок в Оргриммаре. Он специалист по подобным созданиям; надеюсь, добытые нами знания ему пригодятся.','Доставьте отчет о нашествии насекомых-Зукк\'аш на Лагерь Мохаче Зилзибину Барабанному Бою, который проживает на Волоке в Оргриммаре.','А... Я этого ожидал. Эти создания, с которыми вы столкнулись, это древняя угроза, которую Орда продолжает игнорировать с упорством достойным лучшего применения. Хадокен мудро поступил, принеся это и приведя тебя – ко мне.$B$BЭти Зукк\'аш ни кто иные как силитиды. Некоторые думают, что они безмозглые твари, но поверь мне, это угроза куда хуже чем угроза со стороны Альянса.$B$BЕсли ты достаточно $Gсилен:сильна;, то мы используем тебя чтобы пролить свет на эту угрозу.','Приветствую! У тебя такой вид, словно ты торопишься по срочному делу. Я могу чем-нибудь помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение об улье Зукк\'аш',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты поступаешь весьма разумно, направляя свои усилия на борьбу с этими насекомыми, грозящими Лагерю Мохаче. Опасность далеко еще не миновала, и мне хотелось бы попросить тебя оказать Орде еще одну услугу. Вот в этих бумагах изложены все сведения об улье Зукк\'аш, которые нам удалось раздобыть. Прошу тебя доставить их Зилзибину Барабанному Бою на Волок в Оргриммаре. Он специалист по подобным созданиям; надеюсь, добытые нами знания ему пригодятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте отчет о нашествии насекомых-Зукк\'аш на Лагерь Мохаче Зилзибину Барабанному Бою, который проживает на Волоке в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А... Я этого ожидал. Эти создания, с которыми вы столкнулись, это древняя угроза, которую Орда продолжает игнорировать с упорством достойным лучшего применения. Хадокен мудро поступил, принеся это и приведя тебя – ко мне.$B$BЭти Зукк\'аш ни кто иные как силитиды. Некоторые думают, что они безмозглые твари, но поверь мне, это угроза куда хуже чем угроза со стороны Альянса.$B$BЕсли ты достаточно $Gсилен:сильна;, то мы используем тебя чтобы пролить свет на эту угрозу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую! У тебя такой вид, словно ты торопишься по срочному делу. Я могу чем-нибудь помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7733,'Борьба за качество','Я знаю, где можно добыть шкуры еще лучше этих – хотя в это и трудно поверить! На севере Фераласа, в глубине Пещеры Бешеного оврага, обитает другая стая йети. Они куда агрессивнее тех, с которыми тебе доводилось иметь дело прежде, так что если ты ищешь новых подвигов, тебя это наверняка заинтересует!$b$bА я хорошо вознагражу тебя за десяток шкур таких йети. Принеси их мне, и мы договоримся.','Принесите 10 шкур йети из пещеры Бешеного оврага Пратту Макгруббену в Крепость Оперенной Луны в Фераласе.','Отлично, отлично! Эти прекрасно подходят – я уже вижу, что если обработать их как следует, они станут еще прочнее.$B$BЕще раз спасибо тебе за помощь, $N. Вот, прошу: возьми одно из моих изделий.','Если эти шкуры не уступают шкурам йети Дикого Утеса, они, должно быть, по прочности ничем не хуже тория!$B$BТы только представь себе!','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба за качество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, где можно добыть шкуры еще лучше этих – хотя в это и трудно поверить! На севере Фераласа, в глубине Пещеры Бешеного оврага, обитает другая стая йети. Они куда агрессивнее тех, с которыми тебе доводилось иметь дело прежде, так что если ты ищешь новых подвигов, тебя это наверняка заинтересует!$b$bА я хорошо вознагражу тебя за десяток шкур таких йети. Принеси их мне, и мы договоримся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 шкур йети из пещеры Бешеного оврага Пратту Макгруббену в Крепость Оперенной Луны в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, отлично! Эти прекрасно подходят – я уже вижу, что если обработать их как следует, они станут еще прочнее.$B$BЕще раз спасибо тебе за помощь, $N. Вот, прошу: возьми одно из моих изделий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если эти шкуры не уступают шкурам йети Дикого Утеса, они, должно быть, по прочности ничем не хуже тория!$B$BТы только представь себе!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пратту Макгруббену в Крепость Оперенной Луны, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7734,'Борьба за качество','Я знаю, где можно добыть шкуры еще лучше этих – хотя в это и трудно поверить! На севере Фераласа – в глубине Пещеры Бешеного оврага, обитает другая стая йети. Они куда агрессивнее тех, с которыми тебе доводилось иметь дело прежде, так что если ты ищешь новых подвигов, тебя это наверняка заинтересует!$b$bА я хорошо вознагражу тебя за десяток шкур таких йети. Принеси их мне, и мы договоримся.','Принесите 10 шкур йети из пещеры Бешеного оврага Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе.','Замечательно! Эти шкуры отлично подойдут: я уже вижу, что стоит их как следует обработать, и они станут куда прочнее.$B$BИ снова спасибо за помощь, $N. Вот, пожалуйста, – выбирай из моих последних шедевров.','Если эти шкуры не уступают шкурам йети Дикого Утеса, они, должно быть, по прочности ничем не хуже тория!$B$BТы только представь себе!','Вернитесь к Джангору Быстрому Страннику в лагерь Мохаче, что в Фераласе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба за качество',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, где можно добыть шкуры еще лучше этих – хотя в это и трудно поверить! На севере Фераласа – в глубине Пещеры Бешеного оврага, обитает другая стая йети. Они куда агрессивнее тех, с которыми тебе доводилось иметь дело прежде, так что если ты ищешь новых подвигов, тебя это наверняка заинтересует!$b$bА я хорошо вознагражу тебя за десяток шкур таких йети. Принеси их мне, и мы договоримся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 шкур йети из пещеры Бешеного оврага Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Эти шкуры отлично подойдут: я уже вижу, что стоит их как следует обработать, и они станут куда прочнее.$B$BИ снова спасибо за помощь, $N. Вот, пожалуйста, – выбирай из моих последних шедевров.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если эти шкуры не уступают шкурам йети Дикого Утеса, они, должно быть, по прочности ничем не хуже тория!$B$BТы только представь себе!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джангору Быстрому Страннику в лагерь Мохаче, что в Фераласе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7735,'Безупречная шкура йети','Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети с Дикого утеса.$b$bВам известно, что Пратту Макгруббену из Крепости Оперенной Луны всегда нужны шкуры йети, а уж эта его тем более заинтересует!','Отнесите безупречную шкуру йети Пратту Макгруббену в Крепость Оперенной Луны в Фераласе.','Невероятно! Да это же самый настоящий праотец всех шкур йети!$B$BНе поверишь, сколько я тебе за нее дам. Обычно я не плачу так много за одну шкуру, но я уверен, что из этой у меня выйдет кое-что необыкновенное! Спасибо, что не забываешь меня, $N!','Что это, $N? У тебя есть для меня нечто особенное?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречная шкура йети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети с Дикого утеса.$b$bВам известно, что Пратту Макгруббену из Крепости Оперенной Луны всегда нужны шкуры йети, а уж эта его тем более заинтересует!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите безупречную шкуру йети Пратту Макгруббену в Крепость Оперенной Луны в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно! Да это же самый настоящий праотец всех шкур йети!$B$BНе поверишь, сколько я тебе за нее дам. Обычно я не плачу так много за одну шкуру, но я уверен, что из этой у меня выйдет кое-что необыкновенное! Спасибо, что не забываешь меня, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это, $N? У тебя есть для меня нечто особенное?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7736,'Пополнение запасов огненного плавня – королевская кровь','Нам нужно пополнять запасы огненного плавня. Я скажу тебе, когда хватит.','Нам нужно пополнять запасы огненного плавня. Я скажу тебе, когда хватит.','Вернитесь к мастеру-кузнецу Закалону в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пополнение запасов огненного плавня – королевская кровь',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нам нужно пополнять запасы огненного плавня. Я скажу тебе, когда хватит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам нужно пополнять запасы огненного плавня. Я скажу тебе, когда хватит.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру-кузнецу Закалону в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7737,'Завоевать еще большую благосклонность','Так, давай сюда окалину!','Ты быстро продвигаешься по служебной лестнице в Братстве, $R. Ты начинаешь в самом деле завоевывать нашу благосклонность.$B$BЕсли хочешь заслужить еще большее уважение, слушай внимательно.$B$BМы хотим повысить качество нашего огненного плавня путем добавления в него окалины черного железа. Окалину можно добыть в Глубинах Черной горы.$B$BПринеси мне как можно больше!','Вернитесь к мастеру-кузнецу Закалону в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завоевать еще большую благосклонность',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так, давай сюда окалину!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты быстро продвигаешься по служебной лестнице в Братстве, $R. Ты начинаешь в самом деле завоевывать нашу благосклонность.$B$BЕсли хочешь заслужить еще большее уважение, слушай внимательно.$B$BМы хотим повысить качество нашего огненного плавня путем добавления в него окалины черного железа. Окалину можно добыть в Глубинах Черной горы.$B$BПринеси мне как можно больше!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру-кузнецу Закалону в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7738,'Безупречная шкура йети','Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети из Пещеры Бешеного оврага.$b$bВам известно, что Джангору Быстрому Страннику из Лагеря Мохаче всегда нужны шкуры йети, а уж эта его тем более заинтересует!','Отнесите безупречную шкуру йети Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе.','Невероятно! Это, пожалуй, лучший образчик шкуры йети, какой я когда-либо видел!$B$BДа уж, конечно, за такую шкуру следует заплатить по достоинству! Обычно одна-единственная шкура стоит недорого, но из этой шкуры я наверняка сумею изготовить нечто особенное. Спасибо, что принес ее мне, $N!','Что это, $N? У тебя есть для меня нечто особенное?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречная шкура йети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы добыли безупречную шкуру йети, особенно толстую и прочную – даже прочнее шкур йети из Пещеры Бешеного оврага.$b$bВам известно, что Джангору Быстрому Страннику из Лагеря Мохаче всегда нужны шкуры йети, а уж эта его тем более заинтересует!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите безупречную шкуру йети Джангору Быстрому Страннику в Лагерь Мохаче в Фераласе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно! Это, пожалуй, лучший образчик шкуры йети, какой я когда-либо видел!$B$BДа уж, конечно, за такую шкуру следует заплатить по достоинству! Обычно одна-единственная шкура стоит недорого, но из этой шкуры я наверняка сумею изготовить нечто особенное. Спасибо, что принес ее мне, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это, $N? У тебя есть для меня нечто особенное?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (7741,'Похвала Изумрудного Круга <NYI> <TXT>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похвала Изумрудного Круга <NYI> <TXT>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (7761,'Распоряжения Ренда Чернорука','Недоумок, как-то мне очень сомнительно, что ты сумеешь сдержать чужаков и не дать им проникнуть в убежище повелителя. В случае твоей смерти – а подобный исход более чем вероятен – у этой сферы есть свой собственный механизм защиты, который не даст чужакам перенестись напрямую в Крыло Тьмы.$B$BСферой сможет воспользоваться только тот, кто отмечен меткой Драккисата. К счастью, Драккисат, в отличие от некоторых "интендантов", далеко не дурак и хорошо разбирается в своем деле. Он самолично охраняет клеймо!$B$B-Вождь Ренд Чернорук$B$BP.S. Уничтожь это письмо, идиот!','Вот уж действительно идиот... Похоже, вам нужно найти это клеймо и выжечь на руке метку Драккисата, чтобы получить доступ к сфере Приказа.$B$BВ письме ясно сказано, что генерал Драккисат охраняет клеймо. Наверное, стоит проверить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распоряжения Ренда Чернорука',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недоумок, как-то мне очень сомнительно, что ты сумеешь сдержать чужаков и не дать им проникнуть в убежище повелителя. В случае твоей смерти – а подобный исход более чем вероятен – у этой сферы есть свой собственный механизм защиты, который не даст чужакам перенестись напрямую в Крыло Тьмы.$B$BСферой сможет воспользоваться только тот, кто отмечен меткой Драккисата. К счастью, Драккисат, в отличие от некоторых "интендантов", далеко не дурак и хорошо разбирается в своем деле. Он самолично охраняет клеймо!$B$B-Вождь Ренд Чернорук$B$BP.S. Уничтожь это письмо, идиот!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вот уж действительно идиот... Похоже, вам нужно найти это клеймо и выжечь на руке метку Драккисата, чтобы получить доступ к сфере Приказа.$B$BВ письме ясно сказано, что генерал Драккисат охраняет клеймо. Наверное, стоит проверить.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7781,'Владыка Черной горы','Вы понимаете значение этой победы, $N? Ваш подвиг войдет в историю Штормграда! Подобного успеха Альянс не знал многие годы!','Невероятно!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Владыка Черной горы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы понимаете значение этой победы, $N? Ваш подвиг войдет в историю Штормграда! Подобного успеха Альянс не знал многие годы!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Невероятно!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (7782,'Владыка Черной горы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Владыка Черной горы',`title_loc8`);
