INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (7784,'Владыка Черной горы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Владыка Черной горы',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7785,'Сосуд Возрождения','Изучи Сосуд Возрождения, смертный. Из него возродится Искатель Ветра!','Изучите Сосуд Возрождения и вернитесь к верховному лорду Демитриану.','Пусть поход твой увенчается успехом. Да благословит тебя мой повелитель.','Освободишь ли ты его из астральной тюрьмы?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сосуд Возрождения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изучи Сосуд Возрождения, смертный. Из него возродится Искатель Ветра!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите Сосуд Возрождения и вернитесь к верховному лорду Демитриану.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть поход твой увенчается успехом. Да благословит тебя мой повелитель.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Освободишь ли ты его из астральной тюрьмы?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7786,'Громораан Искатель Ветра','Я рассказал тебе все, что знаю, $n. Именно тебе предстоит отыскать элементий и уничтожить воплощение Повелителя Огня.$b$bЕсли ты справишься, с тобой пребудет благословение Громораана.','Чтобы освободить Громораана Искателя Ветра из тюрьмы, отнесите правую и левую половины наручников Искателя Ветра, 10 слитков зачарованного элементия и сущность повелителя огня верховному лорду Демитриану в Силитус.','Пусть мир падет на колени, если нужно!','Вернитесь к верховному лорду Демитриану в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громораан Искатель Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рассказал тебе все, что знаю, $n. Именно тебе предстоит отыскать элементий и уничтожить воплощение Повелителя Огня.$b$bЕсли ты справишься, с тобой пребудет благословение Громораана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Чтобы освободить Громораана Искателя Ветра из тюрьмы, отнесите правую и левую половины наручников Искателя Ветра, 10 слитков зачарованного элементия и сущность повелителя огня верховному лорду Демитриану в Силитус.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пусть мир падет на колени, если нужно!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному лорду Демитриану в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7787,'Громовая Ярость','Ты $gодолел:одолела; Искателя Ветра. Отнеси этой лживой предательской скотине, Демитриану, дремлющий клинок и заставь его воспользоваться предоставленными ему материалами и пробудить Громовую Ярость.','Отдайте Дремлющий клинок Игривого Ветра верховному лорду Демитриану.','Прошу, не трогай меня! Возьми, что тебе нужно! Возьми клинок! Позволь Демитриану собирать осколки своей никчемной жизни.','<Демитриан дрожит от страха.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громовая Ярость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gодолел:одолела; Искателя Ветра. Отнеси этой лживой предательской скотине, Демитриану, дремлющий клинок и заставь его воспользоваться предоставленными ему материалами и пробудить Громовую Ярость.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте Дремлющий клинок Игривого Ветра верховному лорду Демитриану.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прошу, не трогай меня! Возьми, что тебе нужно! Возьми клинок! Позволь Демитриану собирать осколки своей никчемной жизни.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Демитриан дрожит от страха.>',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7788,'Долой захватчиков!','$gЮный:Юная:c; |3-6($c)! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$b$bОтправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!$b$bНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $n, и получишь награду!','Войдите в Ущелье Песни Войны, одержите победу над Ордой, получите почетный знак Ущелья Песни Войны и вернитесь с ним к часовому Дальной Песне в рощу Среброкрылых.','Вернитесь к часовому Дальней Песне в Зеркало Небес, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долой захватчиков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gЮный:Юная:c; |3-6($c)! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$b$bОтправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!$b$bНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $n, и получишь награду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в Ущелье Песни Войны, одержите победу над Ордой, получите почетный знак Ущелья Песни Войны и вернитесь с ним к часовому Дальной Песне в рощу Среброкрылых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Дальней Песне в Зеркало Небес, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7789,'Громи захватчиков-Среброкрылых!','Чащобы Ясеневого леса падут пред мощью Орды, |3-6($r)! Что бы ни делали Среброкрылые Часовые, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше?$b$bПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми Среброкрылых Часовых и заслужи почетный лощины Песни Войны. Вернись ко мне с этим знаком, $n – и получишь награду!','Войдите в Ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.','<Капитан Лободроб одобрительно порыкивает.>$B$BИ сколько еще они смогут так продержаться? Сколько еще солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать? Время покажет, $R, время покажет...','Кровь наших врагов - знак чести. У тебя есть такая отметка?','Вернитесь к капитану Лободробу в лагерь Мор\'шан, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громи захватчиков-Среброкрылых!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чащобы Ясеневого леса падут пред мощью Орды, |3-6($r)! Что бы ни делали Среброкрылые Часовые, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше?$b$bПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми Среброкрылых Часовых и заслужи почетный лощины Песни Войны. Вернись ко мне с этим знаком, $n – и получишь награду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в Ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан Лободроб одобрительно порыкивает.>$B$BИ сколько еще они смогут так продержаться? Сколько еще солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать? Время покажет, $R, время покажет...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кровь наших врагов - знак чести. У тебя есть такая отметка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Лободробу в лагерь Мор\'шан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (7790,'Написанное слово','Вот нечто неожиданное для тебя...$b$b$b','Поговорите с Джонатаном Лекрафтом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Написанное слово',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот нечто неожиданное для тебя...$b$b$b',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джонатаном Лекрафтом.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7791,'Пожертвование – шерсть','Мы всегда готовы принять шерсть в качестве пожертвования. Шестьдесят отрезов – дар, который жители Штормграда запомнят надолго. Ты ведь знаешь пословицу: "С миру по нитке – голому рубашка". А нам очень нужна шерсть!$B$BЕсли у тебя есть 60 отрезов шерстяной ткани и ты хочешь сделать пожертвование, то я могу принять дар прямо сейчас.','Вернитесь к Клавию Кнавингему в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шерсть',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы всегда готовы принять шерсть в качестве пожертвования. Шестьдесят отрезов – дар, который жители Штормграда запомнят надолго. Ты ведь знаешь пословицу: "С миру по нитке – голому рубашка". А нам очень нужна шерсть!$B$BЕсли у тебя есть 60 отрезов шерстяной ткани и ты хочешь сделать пожертвование, то я могу принять дар прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Клавию Кнавингему в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7792,'Пожертвование – шерсть','Мы занимаемся сбором шерстяной ткани. Если вы пожертвуете на благие цели 60 отрезов, то заслужите признательность всего народа.$b$bЕсли у вас есть 60 отрезов, можете пожертвовать их прямо сейчас.','Вернитесь к Дугиру в Экзодар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шерсть',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы занимаемся сбором шерстяной ткани. Если вы пожертвуете на благие цели 60 отрезов, то заслужите признательность всего народа.$b$bЕсли у вас есть 60 отрезов, можете пожертвовать их прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дугиру в Экзодар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7793,'Пожертвование – шелк','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Могу ли я добавить, что такой благотворительный подарок, как шелк, несомненно, повысит ваше положение в обществе! Если у вас есть 60 отрезов шелковой ткани и вы готовы пожертвовать их, я могу забрать их у вас прямо сейчас.','Вернитесь к Клавию Кнавингему в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шелк',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Могу ли я добавить, что такой благотворительный подарок, как шелк, несомненно, повысит ваше положение в обществе! Если у вас есть 60 отрезов шелковой ткани и вы готовы пожертвовать их, я могу забрать их у вас прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Клавию Кнавингему в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7794,'Пожертвование – магическая ткань','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Если у тебя есть 60 отрезов магической ткани, я могу принять их у тебя в качестве пожертвования.','Вернитесь к Клавию Кнавингему в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – магическая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя есть 60 отрезов магической ткани, я могу принять их у тебя в качестве пожертвования.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Клавию Кнавингему в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7795,'Пожертвование – руническая ткань','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.','Вернитесь к Клавию Кнавингему в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – руническая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Клавию Кнавингему в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7796,'Больше рунической ткани','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.','Вернитесь к Клавию Кнавингему в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше рунической ткани',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Клавию Кнавингему в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (7797,'Пространственный проходчик – Круговзор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пространственный проходчик – Круговзор',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7798,'Пожертвование – шелк','Мы занимаемся сбором шелка. Если вы пожертвуете на благие цели 60 отрезов, то заслужите признательность всего народа.\n\nЕсли у вас есть 60 отрезов, можете пожертвовать их прямо сейчас.','Вернитесь к Дугиру в Экзодар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шелк',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы занимаемся сбором шелка. Если вы пожертвуете на благие цели 60 отрезов, то заслужите признательность всего народа.\n\nЕсли у вас есть 60 отрезов, можете пожертвовать их прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дугиру в Экзодар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7799,'Пожертвование – магическая ткань','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Если у тебя есть 60 отрезов магической ткани, я могу принять их у тебя в качестве пожертвования.','Вернитесь к Райдону Сумеречному Воителю в Тельдрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – магическая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя есть 60 отрезов магической ткани, я могу принять их у тебя в качестве пожертвования.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Райдону Сумеречному Воителю в Тельдрассил.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7800,'Пожертвование – руническая ткань','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.','Вернитесь к Райдону Сумеречному Воителю в Тельдрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – руническая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Райдону Сумеречному Воителю в Тельдрассил.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7801,'Больше рунической ткани','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.','Вернитесь к Райдону Сумеречному Воителю в Тельдрассил.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше рунической ткани',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Райдону Сумеречному Воителю в Тельдрассил.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7802,'Пожертвование – шерсть','Мы сейчас собираем пожертвования в виде шерстяной ткани. За щедрый дар вы получите признательность Стальгорна. Наши запасы таковы, что нам нужно от вас всего лишь шестьдесят отрезов. Мы могли бы купить их и на стороне, чтобы продолжить работу.$B$BНо если вы имеете шестьдесят отрезов шерстяной ткани и готовы пожертвовать их в дар, я с готовностью приму их у вас прямо сейчас.','Вернитесь к Мистине Сталещит в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шерсть',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы сейчас собираем пожертвования в виде шерстяной ткани. За щедрый дар вы получите признательность Стальгорна. Наши запасы таковы, что нам нужно от вас всего лишь шестьдесят отрезов. Мы могли бы купить их и на стороне, чтобы продолжить работу.$B$BНо если вы имеете шестьдесят отрезов шерстяной ткани и готовы пожертвовать их в дар, я с готовностью приму их у вас прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мистине Сталещит в Болотину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7803,'Пожертвование – шелк','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.$B$BЕсли ты можешь пожертвовать 60 отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!','Вернитесь к Мистине Сталещит в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шелк',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.$B$BЕсли ты можешь пожертвовать 60 отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мистине Сталещит в Болотину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7804,'Пожертвование – магическая ткань','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Магическая ткань кончается, и чтобы пополнить запасы, мы хотели бы воспользоваться вашей помощью! Нам понадобится всего лишь 60 отрезов на нужды сообщества. Твоя щедрость не останется незамеченной в Стальгорне, уверяю тебя!$B$BЕсли у тебя есть шестьдесят отрезов магической ткани и ты $Gготов:готова; их пожертвовать, я могу принять их у тебя сейчас же.','Вернитесь к Мистине Сталещит в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – магическая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Магическая ткань кончается, и чтобы пополнить запасы, мы хотели бы воспользоваться вашей помощью! Нам понадобится всего лишь 60 отрезов на нужды сообщества. Твоя щедрость не останется незамеченной в Стальгорне, уверяю тебя!$B$BЕсли у тебя есть шестьдесят отрезов магической ткани и ты $Gготов:готова; их пожертвовать, я могу принять их у тебя сейчас же.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мистине Сталещит в Болотину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7805,'Пожертвование – руническая ткань','Невероятно! Уверяю тебя, эти отрезки пойдут на правое дело. Еще раз спасибо тебе за помощь! Мы бы без тебя не справились.$B$BЕсли ты решишь пожертвовать еще рунической ткани, то я с радостью приму ее от тебя. Только не забудь переговорить со мной, я лично проконтролирую, чтобы твои добрые дела не остались незамеченными!','$N, ты очень $Gпомог:помогла; нам в кампании по сбору ткани. Мы стараемся пополнить наши запасы, но одного вида ткани нам все равно катастрофически не хватает, а именно рунной ткани. Мы чрезвычайно в ней нуждаемся и надеемся, что ты поможешь нам, как и в прошлый раз!$B$BЕсли ты $Gсогласен:согласна;, пожалуйста, пожертвуй нам ткани – сколько сможешь. Обычно мы принимаем начальное пожертвование от одного лица в размере шестидесяти отрезов, с этого и начнем.','Вернитесь к Мистине Сталещит в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – руническая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно! Уверяю тебя, эти отрезки пойдут на правое дело. Еще раз спасибо тебе за помощь! Мы бы без тебя не справились.$B$BЕсли ты решишь пожертвовать еще рунической ткани, то я с радостью приму ее от тебя. Только не забудь переговорить со мной, я лично проконтролирую, чтобы твои добрые дела не остались незамеченными!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты очень $Gпомог:помогла; нам в кампании по сбору ткани. Мы стараемся пополнить наши запасы, но одного вида ткани нам все равно катастрофически не хватает, а именно рунной ткани. Мы чрезвычайно в ней нуждаемся и надеемся, что ты поможешь нам, как и в прошлый раз!$B$BЕсли ты $Gсогласен:согласна;, пожалуйста, пожертвуй нам ткани – сколько сможешь. Обычно мы принимаем начальное пожертвование от одного лица в размере шестидесяти отрезов, с этого и начнем.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мистине Сталещит в Болотину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7806,'Больше рунической ткани','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.','Вернитесь к Мистине Сталещит в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше рунической ткани',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мистине Сталещит в Болотину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7807,'Пожертвование – шерсть','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Мы сейчас собираем пожертвования в виде шерстяной ткани. За щедрый дар вы получите признательность Стальгорна. Наши запасы таковы, что нам нужно от вас всего лишь шестьдесят отрезов. Мы могли бы купить их и на стороне, чтобы продолжить работу.$B$BНо если вы имеете шестьдесят отрезов шерстяной ткани и готовы пожертвовать их в дар, я с готовностью приму их у вас прямо сейчас.','Вернитесь к Бубуло Грубберу в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шерсть',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы сейчас собираем пожертвования в виде шерстяной ткани. За щедрый дар вы получите признательность Стальгорна. Наши запасы таковы, что нам нужно от вас всего лишь шестьдесят отрезов. Мы могли бы купить их и на стороне, чтобы продолжить работу.$B$BНо если вы имеете шестьдесят отрезов шерстяной ткани и готовы пожертвовать их в дар, я с готовностью приму их у вас прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бубуло Грубберу в Болотину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7808,'Пожертвование – шелк','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.$B$BЕсли ты можешь пожертвовать 60 отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!','Вернитесь к Бубуло Грубберу в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шелк',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.$B$BЕсли ты можешь пожертвовать 60 отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бубуло Грубберу в Болотину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7809,'Пожертвование – магическая ткань','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Если у тебя есть 60 отрезов магической ткани, я могу принять их у тебя в качестве пожертвования.','Вернитесь к Бубуло Грубберу в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – магическая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя есть 60 отрезов магической ткани, я могу принять их у тебя в качестве пожертвования.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бубуло Грубберу в Болотину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7810,'Повелитель арены','Поговорите с Коротышкой Джоном Мифрилом на арене Тернистой долины.','Поговорите с Коротышкой Джоном Мифрилом на Арене Гурубаши, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелитель арены',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Коротышкой Джоном Мифрилом на арене Тернистой долины.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Коротышкой Джоном Мифрилом на Арене Гурубаши, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7811,'Пожертвование – руническая ткань','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.','Вернитесь к Бубуло Грубберу в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – руническая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бубуло Грубберу в Болотину.',`completedtext_loc8`);
