INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7813,'Пожертвование – шерсть','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Если у тебя при себе имеется 60 отрезов шерсти и ты $Gготов:готова; ее пожертвовать, я могу принять шерсть прямо сейчас.','Вернитесь к Ралстону Фэрнсли в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шерсть',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя при себе имеется 60 отрезов шерсти и ты $Gготов:готова; ее пожертвовать, я могу принять шерсть прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ралстону Фэрнсли в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7814,'Пожертвование – шелк','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Могу ли я добавить, что такой благотворительный подарок, как шелк, несомненно, повысит ваше положение в обществе! Если у вас есть 60 отрезов шелковой ткани и вы готовы пожертвовать их, я могу забрать их у вас прямо сейчас.','Вернитесь к Ралстону Фэрнсли в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шелк',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Могу ли я добавить, что такой благотворительный подарок, как шелк, несомненно, повысит ваше положение в обществе! Если у вас есть 60 отрезов шелковой ткани и вы готовы пожертвовать их, я могу забрать их у вас прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ралстону Фэрнсли в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7815,'Хрустогрызы, чувак!','Ты не смотри, что у них такие большие красивые глазки! Страшней морского хрустогрыза зверя нет! Только я удочку закину, как приплывают эти черепахи-переростки, жрут мне всю наживку и удилище пополам ломают!$B$BСделай мне и всей нашей деревеньке одолжение – поубивай их всех.$B$BВ смысле, хрустогрызов.','Убейте 10 морских хрустогрызов по поручению Катума Удильщика из деревни Сломанного Клыка во Внутренних землях.','Ох, друг! Я не могу тебя отблагодарить! Надеюсь, этой удочки хватит за работу.','Как идет охота?','Вернитесь к Катуму Удильщику в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хрустогрызы, чувак!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не смотри, что у них такие большие красивые глазки! Страшней морского хрустогрыза зверя нет! Только я удочку закину, как приплывают эти черепахи-переростки, жрут мне всю наживку и удилище пополам ломают!$B$BСделай мне и всей нашей деревеньке одолжение – поубивай их всех.$B$BВ смысле, хрустогрызов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 морских хрустогрызов по поручению Катума Удильщика из деревни Сломанного Клыка во Внутренних землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, друг! Я не могу тебя отблагодарить! Надеюсь, этой удочки хватит за работу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идет охота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катуму Удильщику в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7816,'Гаммерита!','Йоу! Тут живет всем черепахам черепаха – звать Гаммерита – предводительница всех морских хрустогрызов и просто наглая прожорливая рептилия, чтоб ей.$B$BОна сожрала мою лучшую блесну! Взяла и откусила прямо с удочки! С тех пор рыба совсем клевать перестала.$B$BНайди Гаммериту и вытащи у нее из брюха мою блесну!','Убейте Гаммериту и верните Катуму Удильщику из деревни Сломанного Клыка его лучшую блесну.$B$BКатум сказал, что Гаммерита ползает по берегу среди остальных черепах.','$GДРУЖИЩЕ:ПОДРУГА;!!! Ну и дела! Блесна есть, хрустогрызов нет, да я сейчас всю рыбу в море переловлю!','$GНашел:Нашла; ее?','Вернитесь к Катуму Удильщику в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гаммерита!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Йоу! Тут живет всем черепахам черепаха – звать Гаммерита – предводительница всех морских хрустогрызов и просто наглая прожорливая рептилия, чтоб ей.$B$BОна сожрала мою лучшую блесну! Взяла и откусила прямо с удочки! С тех пор рыба совсем клевать перестала.$B$BНайди Гаммериту и вытащи у нее из брюха мою блесну!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гаммериту и верните Катуму Удильщику из деревни Сломанного Клыка его лучшую блесну.$B$BКатум сказал, что Гаммерита ползает по берегу среди остальных черепах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GДРУЖИЩЕ:ПОДРУГА;!!! Ну и дела! Блесна есть, хрустогрызов нет, да я сейчас всю рыбу в море переловлю!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GНашел:Нашла; ее?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Катуму Удильщику в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7817,'Пожертвование – магическая ткань','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Если у тебя есть 60 отрезов магической ткани, я могу принять их у тебя в качестве пожертвования.','Вернитесь к Ралстону Фэрнсли в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – магическая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя есть 60 отрезов магической ткани, я могу принять их у тебя в качестве пожертвования.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ралстону Фэрнсли в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7818,'Пожертвование – руническая ткань','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.','Вернитесь к Ралстону Фэрнсли в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – руническая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ралстону Фэрнсли в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7819,'Больше рунической ткани','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!','И вновь приветствую тебя, $N! Наша потребность в рунической ткани не утихает и мы всегда рады новым пожертвованиям. За дополнительные 20 отрезков рунической ткани, я лично проконтролирую, чтобы ты за свои неустанные усилия получил признание Подгорода.','Вернитесь к Ралстону Фэрнсли в Западные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше рунической ткани',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И вновь приветствую тебя, $N! Наша потребность в рунической ткани не утихает и мы всегда рады новым пожертвованиям. За дополнительные 20 отрезков рунической ткани, я лично проконтролирую, чтобы ты за свои неустанные усилия получил признание Подгорода.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ралстону Фэрнсли в Западные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7820,'Пожертвование – шерсть','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Мы сейчас собираем пожертвования в виде шерстяной ткани. За щедрый дар вы получите признательность Громового Утеса. Наши запасы таковы, что нам нужно от вас всего лишь шестьдесят отрезов. Мы могли бы купить их и на стороне, чтобы продолжить работу.$B$BНо если вы имеете шестьдесят отрезов шерстяной ткани и готовы пожертвовать их в дар, я с готовностью приму их у вас прямо сейчас.','Вернитесь к Румстагу Гордому Страннику в Пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шерсть',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы сейчас собираем пожертвования в виде шерстяной ткани. За щедрый дар вы получите признательность Громового Утеса. Наши запасы таковы, что нам нужно от вас всего лишь шестьдесят отрезов. Мы могли бы купить их и на стороне, чтобы продолжить работу.$B$BНо если вы имеете шестьдесят отрезов шерстяной ткани и готовы пожертвовать их в дар, я с готовностью приму их у вас прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Румстагу Гордому Страннику в Пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7821,'Пожертвование – шелк','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.$B$BЕсли ты можешь пожертвовать 60 отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!','Вернитесь к Румстагу Гордому Страннику в Пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шелк',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.$B$BЕсли ты можешь пожертвовать 60 отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Румстагу Гордому Страннику в Пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7822,'Пожертвование – магическая ткань','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Магическая ткань кончается, и чтобы пополнить запасы, мы хотели бы воспользоваться твоей помощью! Нам понадобится всего лишь 60 отрезов магической ткани на нужды сообщества. Твоя щедрость не останется незамеченной в Громовом Утесе, будь уверен!$B$BЕсли у тебя есть шестьдесят отрезов магической ткани и ты $Gготов:готова; их пожертвовать, я могу принять их у тебя сейчас же.','Вернитесь к Румстагу Гордому Страннику в Пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – магическая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Магическая ткань кончается, и чтобы пополнить запасы, мы хотели бы воспользоваться твоей помощью! Нам понадобится всего лишь 60 отрезов магической ткани на нужды сообщества. Твоя щедрость не останется незамеченной в Громовом Утесе, будь уверен!$B$BЕсли у тебя есть шестьдесят отрезов магической ткани и ты $Gготов:готова; их пожертвовать, я могу принять их у тебя сейчас же.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Румстагу Гордому Страннику в Пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7823,'Пожертвование – руническая ткань','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.','Вернитесь к Румстагу Гордому Страннику в Пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – руническая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Румстагу Гордому Страннику в Пустоши.',`completedtext_loc8`);
