INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7825,'Больше рунической ткани','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.','Вернитесь к Румстагу Гордому Страннику в Пустоши.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше рунической ткани',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Румстагу Гордому Страннику в Пустоши.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7826,'Пожертвование – шерсть','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Если у тебя при себе имеется 60 отрезов шерсти и ты $Gготов:готова; ее пожертвовать, я могу принять шерсть прямо сейчас.','Вернитесь к Рашоне Лихой Плети в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шерсть',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя при себе имеется 60 отрезов шерсти и ты $Gготов:готова; ее пожертвовать, я могу принять шерсть прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рашоне Лихой Плети в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7827,'Пожертвование – шелк','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.$B$BЕсли ты можешь пожертвовать 60 отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!','Вернитесь к Рашоне Лихой Плети в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шелк',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.$B$BЕсли ты можешь пожертвовать 60 отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рашоне Лихой Плети в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7828,'Охота на бродяг','В диких лесах Внутренних земель погибло много храбрых троллей, |3-6($r). Одни из самых опасных животных там – среброгривые волки. Они прячутся в высокой траве и всегда нападают неожиданно.$B$BНельзя закрывать глаза на такую опасность!$B$BУменьшите поголовье среброгривов!','Убейте 5 среброгривых бродяг и 5 среброгривых ревунов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях.$B$BМархор сказал, что волки обитают в лесах Внутренних земель.','Великолепно, $R. Благодарю тебя от имени племени Сломанного Клыка.','Покажи им мощь!','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на бродяг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В диких лесах Внутренних земель погибло много храбрых троллей, |3-6($r). Одни из самых опасных животных там – среброгривые волки. Они прячутся в высокой траве и всегда нападают неожиданно.$B$BНельзя закрывать глаза на такую опасность!$B$BУменьшите поголовье среброгривов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 среброгривых бродяг и 5 среброгривых ревунов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях.$B$BМархор сказал, что волки обитают в лесах Внутренних земель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно, $R. Благодарю тебя от имени племени Сломанного Клыка.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Покажи им мощь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7829,'Охота на дикарей','Одни из самых мерзких существ во Внутренних землях – дикие совухи. Сколько храбрых воинов Сломанного Клыка они уже разорвали своими когтями и клювами...$B$BУбейте всех диких совухов, которых встретите, |3-6($r). Ваша помощь будет взвешена, измерена и по достоинству оценена.','Убейте 10 диких совухов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях.$B$BМархор сказал, что совухи обитают в лесах Внутренних земель.','Вы доказали, что вы – преданный союзник племени Сломанного Клыка, $N. Молодец.','Очисти свою голову от нечистых мыслей, $R. Станьте единым целым с дебрями!','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на дикарей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одни из самых мерзких существ во Внутренних землях – дикие совухи. Сколько храбрых воинов Сломанного Клыка они уже разорвали своими когтями и клювами...$B$BУбейте всех диких совухов, которых встретите, |3-6($r). Ваша помощь будет взвешена, измерена и по достоинству оценена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 диких совухов по поручению охотника Мархора из деревни Сломанного Клыка во Внутренних землях.$B$BМархор сказал, что совухи обитают в лесах Внутренних земель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы доказали, что вы – преданный союзник племени Сломанного Клыка, $N. Молодец.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Очисти свою голову от нечистых мыслей, $R. Станьте единым целым с дебрями!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7830,'Отмщение за погибших','Мерзавцы из клана Громового Молота учат своих грифонов убивать троллей. Ужасно, конечно, но не беспокойся, мы этого так не оставим.$B$BПока что я хочу, чтобы ты $gзанялся:занялась; уничтожением самых главных грифонов этих мест. Этих остроклювов зовут еще повелителями небес. $B$BУбей одного из них и принеси мне его перо.','Убейте остроклюва-повелителя небес и принесите его перо охотнику Мархору в деревню Сломанного Клыка.$B$BМархор говорил, что остроклювы водятся в диких местах Внутренних земель.','<Мархор изучает перо.>$B$BИнтересно, сколько наших охотников сожрало это чудовище, прежде чем вы воздали ему по заслугам?','Остроклюв-повелитель небес – очень редкая порода грифонов, от которых происходит невероятно агрессивное потомство.','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отмщение за погибших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мерзавцы из клана Громового Молота учат своих грифонов убивать троллей. Ужасно, конечно, но не беспокойся, мы этого так не оставим.$B$BПока что я хочу, чтобы ты $gзанялся:занялась; уничтожением самых главных грифонов этих мест. Этих остроклювов зовут еще повелителями небес. $B$BУбей одного из них и принеси мне его перо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте остроклюва-повелителя небес и принесите его перо охотнику Мархору в деревню Сломанного Клыка.$B$BМархор говорил, что остроклювы водятся в диких местах Внутренних земель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мархор изучает перо.>$B$BИнтересно, сколько наших охотников сожрало это чудовище, прежде чем вы воздали ему по заслугам?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Остроклюв-повелитель небес – очень редкая порода грифонов, от которых происходит невероятно агрессивное потомство.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7831,'Пожертвование – магическая ткань','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','У нас заканчивается магическая ткань и твоя щедрость была бы очень кстати! Нам всего-то 60 отрезов на все сообщество и нужно. Уверяю тебя, Оргриммар не забудет твоей доброты!$B$BЕсли у тебя при себе имеется 60 отрезов магической ткани и ты $Gготов:готова; ее пожертвовать, я могу ее принять прямо сейчас.','Вернитесь к Рашоне Лихой Плети в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – магическая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У нас заканчивается магическая ткань и твоя щедрость была бы очень кстати! Нам всего-то 60 отрезов на все сообщество и нужно. Уверяю тебя, Оргриммар не забудет твоей доброты!$B$BЕсли у тебя при себе имеется 60 отрезов магической ткани и ты $Gготов:готова; ее пожертвовать, я могу ее принять прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рашоне Лихой Плети в Оргриммар.',`completedtext_loc8`);
