INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7834,'Пожертвование – шелк','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.$B$BЕсли ты можешь пожертвовать 60 отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!','Вернитесь к Вехене в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шелк',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наши запасы тканей подходят к концу, и особенно нам не хватает шелка. Остается надеяться только на щедрость горожан и заезжих героев.$B$BЕсли ты можешь пожертвовать 60 отрезов шелка, я с благодарностью приму твой дар прямо сейчас. И помни: добрые дела приносят добрую славу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вехене в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7835,'Пожертвование – магическая ткань','Прекрасно! $N, благодарим тебя за щедрое пожертвование!','У нас заканчивается магическая ткань, и твоя щедрость была бы очень кстати! Нам всего-то 60 отрезов на все сообщество и нужно. Уверяю тебя, тролли Черного Копья не забудут твоей доброты!$B$BЕсли у тебя при себе имеется 60 отрезов магической ткани и ты $Gготов:готова; ее пожертвовать, я могу ее принять прямо сейчас.','Вернитесь к Вехене в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – магическая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! $N, благодарим тебя за щедрое пожертвование!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У нас заканчивается магическая ткань, и твоя щедрость была бы очень кстати! Нам всего-то 60 отрезов на все сообщество и нужно. Уверяю тебя, тролли Черного Копья не забудут твоей доброты!$B$BЕсли у тебя при себе имеется 60 отрезов магической ткани и ты $Gготов:готова; ее пожертвовать, я могу ее принять прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вехене в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7836,'Пожертвование – руническая ткань','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.','Вернитесь к Вехене в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – руническая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Ткань сразу пойдет в дело, уж не сомневайся. Благодарю тебя за помощь! Без тебя мы бы точно пропали.$B$BХотя мы и так получили от тебя много ткани, если ты вдруг соблаговолишь в будущем пожертвовать еще, я найду ей применение. Просто свяжись со мной, и я лично позабочусь, чтобы твои добрые дела не остались незамеченными!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вехене в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7837,'Больше рунической ткани','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.','Вернитесь к Вехене в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше рунической ткани',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N! Что бы мы делали без героев, щедростью сравнимых с тобой?! Спасибо за то, что не забываешь о нас!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вехене в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (7838,'Великий повелитель арены','Много крови пролито тобою на песок ринга, и я с радостью нарекаю тебя Великим Повелителем Арены!','Вернитесь к Коротышке Джону Мифрилу на Арену Гурубаши, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий повелитель арены',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Много крови пролито тобою на песок ринга, и я с радостью нарекаю тебя Великим Повелителем Арены!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коротышке Джону Мифрилу на Арену Гурубаши, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7839,'Хулиганы Порочной Ветви','Эти негодяи из племени Порочной Ветви напали на нашу деревню и украли мои инструменты! У меня, конечно, есть запасные, но тот набор, что они уволокли, был мне дорог как память. Когда я был еще мальчишкой, мне спас жизнь один гном, а потом он подарил мне тот набор.$B$BЯ очень хочу вернуть их, $n, я без них как без рук!$B$BМархор сказал, что мои инструменты видели в храмах Агол\'вата и Шаол\'вата, они оба на северо-востоке Внутренних земель.$B$BПожалуйста, верните мне инструменты!','Найдите потерянные инструменты кузнеца Углежога из деревни Сломанного Клыка во Внутренних землях.$B$BУглежог сказал, что инструменты могут быть в одном из храмов троллей Порочной Ветви в северо-восточной части Внутренних земель. Также следует проверить на Осклизлой скале.','Мои инструменты! О, великий день! Спасибо тебе, $N.','Берегитесь троллей из клана Порочной Ветви, $N. Они очень жестоки и агрессивны.','Вернитесь к кузнецу Углежогу в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хулиганы Порочной Ветви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти негодяи из племени Порочной Ветви напали на нашу деревню и украли мои инструменты! У меня, конечно, есть запасные, но тот набор, что они уволокли, был мне дорог как память. Когда я был еще мальчишкой, мне спас жизнь один гном, а потом он подарил мне тот набор.$B$BЯ очень хочу вернуть их, $n, я без них как без рук!$B$BМархор сказал, что мои инструменты видели в храмах Агол\'вата и Шаол\'вата, они оба на северо-востоке Внутренних земель.$B$BПожалуйста, верните мне инструменты!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите потерянные инструменты кузнеца Углежога из деревни Сломанного Клыка во Внутренних землях.$B$BУглежог сказал, что инструменты могут быть в одном из храмов троллей Порочной Ветви в северо-восточной части Внутренних земель. Также следует проверить на Осклизлой скале.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои инструменты! О, великий день! Спасибо тебе, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Берегитесь троллей из клана Порочной Ветви, $N. Они очень жестоки и агрессивны.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кузнецу Углежогу в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7840,'Лярд потерял свой обед','Лярд хотел устроить пикник в секретном месте, а потом пришли злые тролли племени Порочной Ветви и побили Лярда большими палками. Лярд убежал в деревню, но потерял свой обед. Лярд голодный... Может, сходишь в секретное место и найдешь там мой обед? Лярд боится. Это на севере! Остров на севере, там секретное место!','Найдите обед Лярда из деревни Сломанного Клыка во Внутренних землях.$B$BЛярд сказал, что потерял свой обед на острове к северу, где могут встретиться тролли из племени Порочной Ветви.','<Лярд берёт у вас огромный кусок мяса и начинает жадно его грызть.>$B$BВот, как хорошо! Спасибо, $Gмелкий:мелкая;.$B$BЛярд даст тебе в подарок эту специальную корзинку для пикника.','<Лярд потирает огромный живот>$B$BЛярд хочет кушать...','Вернитесь к Лярду в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лярд потерял свой обед',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лярд хотел устроить пикник в секретном месте, а потом пришли злые тролли племени Порочной Ветви и побили Лярда большими палками. Лярд убежал в деревню, но потерял свой обед. Лярд голодный... Может, сходишь в секретное место и найдешь там мой обед? Лярд боится. Это на севере! Остров на севере, там секретное место!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите обед Лярда из деревни Сломанного Клыка во Внутренних землях.$B$BЛярд сказал, что потерял свой обед на острове к северу, где могут встретиться тролли из племени Порочной Ветви.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Лярд берёт у вас огромный кусок мяса и начинает жадно его грызть.>$B$BВот, как хорошо! Спасибо, $Gмелкий:мелкая;.$B$BЛярд даст тебе в подарок эту специальную корзинку для пикника.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Лярд потирает огромный живот>$B$BЛярд хочет кушать...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лярду в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7841,'Послание клану Громового Молота','Клан Громового Молота якшается с нашими врагами и заключает с ними союзы. В этот раз они спутались с высшими эльфами. Убейте любого высшего эльфа из Высокодолья, которого только встретите – пусть их тела послужат предупреждением.$B$BС троллями шутки плохи!','Убейте 8 гонцов, 5 разведчиков, 5 стрелков и 2 следопытов Высокодолья по поручению Отхо Можи\'ко из деревни Сломанного Клыка.$B$BВысших эльфов из Высокодолья можно найти в Сторожке Кель\'Данил в северо-западной части Внутренних земель.','Похоже, Сломанный Клык тоже делает успехи в дипломатии, вступив в альянс... с тобой, $Gдруг:подруга;! Хорошо сработано!','Ты слишком $Gчист:чиста;, $Gдружище:подруга;. Вы должны перемешать это - спуститься и испачкаться с врагом.','Вернитесь к Отхо Можи\'ко в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание клану Громового Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Громового Молота якшается с нашими врагами и заключает с ними союзы. В этот раз они спутались с высшими эльфами. Убейте любого высшего эльфа из Высокодолья, которого только встретите – пусть их тела послужат предупреждением.$B$BС троллями шутки плохи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 гонцов, 5 разведчиков, 5 стрелков и 2 следопытов Высокодолья по поручению Отхо Можи\'ко из деревни Сломанного Клыка.$B$BВысших эльфов из Высокодолья можно найти в Сторожке Кель\'Данил в северо-западной части Внутренних земель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, Сломанный Клык тоже делает успехи в дипломатии, вступив в альянс... с тобой, $Gдруг:подруга;! Хорошо сработано!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты слишком $Gчист:чиста;, $Gдружище:подруга;. Вы должны перемешать это - спуститься и испачкаться с врагом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Отхо Можи\'ко в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7842,'Еще одно послание клану Громового Молота','Говорят, что дворфы Громового Молота и их грифоны – друзья не разлей вода. Хоть это и не очень красиво, но нужно воспользоваться этим преимуществом. Сделаем им еще одно предупреждение.$B$BУбей всех грифонов, каких только встретишь во Внутренних землях, и принеси мне длинное элегантное перо – это должно подействовать.','Принесите длинное элегантное перо Отхо Можи\'ко из деревни Сломанного Клыка во Внутренних землях. Перо нужно собрать с местных грифонов, которых можно найти практически в любом месте Внутренних земель.','О, неплохо. Ещё один шаг, и Громовой Молот полетит у нас отсюда вверх тормашками!','Наше последнее предупреждение непременно отпугнет их. Или очень сильно разозлит.','Вернитесь к Отхо Можи\'ко в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще одно послание клану Громового Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что дворфы Громового Молота и их грифоны – друзья не разлей вода. Хоть это и не очень красиво, но нужно воспользоваться этим преимуществом. Сделаем им еще одно предупреждение.$B$BУбей всех грифонов, каких только встретишь во Внутренних землях, и принеси мне длинное элегантное перо – это должно подействовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите длинное элегантное перо Отхо Можи\'ко из деревни Сломанного Клыка во Внутренних землях. Перо нужно собрать с местных грифонов, которых можно найти практически в любом месте Внутренних земель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, неплохо. Ещё один шаг, и Громовой Молот полетит у нас отсюда вверх тормашками!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наше последнее предупреждение непременно отпугнет их. Или очень сильно разозлит.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Отхо Можи\'ко в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (7843,'Последнее послание клану Громового Молота','*Отхо вручает вам длинное окровавленное копье, обернутое перьями грифона*$B$BВот, берите. Отнесите это на Заоблачный пик, в самый центр тамошнего поселения. Воткните копье у колодца, пусть эти дворфы знают, что с нами шутки плохи! А потом возвращайтесь ко мне. Надеюсь еще увидеть вас $gживым:живой;.','Заберитесь на Заоблачный пик в западной части Внутренних Земель и оставьте возле колодца в центре города последнее послание клану Громового Молота. После выполнения задания возвращайтесь к Отхо Можи\'ко в деревню Сломанного Клыка.$B$BБерегитесь дворфов Громового Молота и других сторонников Альянса.','Ох, и хотел бы я посмотреть на их хари в этот момент? Надеюсь, они теперь упаковывают свои пожитки, чтобы оставить город!$B$BХорошая работа, $N. Отхо наградит тебя.','Что за задержка, $Gдружище:подруга;?','Послание клану Громового Молота доставлено','Вернитесь к Отхо Можи\'ко в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последнее послание клану Громового Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Отхо вручает вам длинное окровавленное копье, обернутое перьями грифона*$B$BВот, берите. Отнесите это на Заоблачный пик, в самый центр тамошнего поселения. Воткните копье у колодца, пусть эти дворфы знают, что с нами шутки плохи! А потом возвращайтесь ко мне. Надеюсь еще увидеть вас $gживым:живой;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберитесь на Заоблачный пик в западной части Внутренних Земель и оставьте возле колодца в центре города последнее послание клану Громового Молота. После выполнения задания возвращайтесь к Отхо Можи\'ко в деревню Сломанного Клыка.$B$BБерегитесь дворфов Громового Молота и других сторонников Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, и хотел бы я посмотреть на их хари в этот момент? Надеюсь, они теперь упаковывают свои пожитки, чтобы оставить город!$B$BХорошая работа, $N. Отхо наградит тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что за задержка, $Gдружище:подруга;?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Послание клану Громового Молота доставлено',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Отхо Можи\'ко в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7844,'Собратья-каннибалы','Во Внутренних землях живет три племени троллей, $n. На этом, собственно, сходство и заканчивается – мы все тролли и мы все живем здесь.$B$BПлемя Порочной Ветви, как следует из названия, самое отвратительное – тамошние каннибалы едят и троллей, и вообще всех, кто подвернется.$B$BЕсли бы Зул\'джин был здесь, он бы уничтожил все это отродье одним движением руки! Но Зул\'джина с нами нет, поэтому приходится справляться самим.$B$BВот вам задание – пойти и убить троллей из племени Порочной Ветви.','Убейте 6 охотников за скальпами и 2 ворожеев из племени Порочной Ветви по поручению Яо\'джин из деревни Сломанного Клыка.$B$BЯо\'джин сказала, что эти тролли живут близ храмов Шаол\'вата и Агол\'вата в северо-восточной части Внутренних земель.','Прекрасно сделано, $C. Сам Зул\'джин не смог бы сделать работу лучше!!','Ворожеи и охотники за скальпами из племени Порочной Ветви живут на северо-востоке Внутренних земель.','Вернитесь к мистику Яо\'джин в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собратья-каннибалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во Внутренних землях живет три племени троллей, $n. На этом, собственно, сходство и заканчивается – мы все тролли и мы все живем здесь.$B$BПлемя Порочной Ветви, как следует из названия, самое отвратительное – тамошние каннибалы едят и троллей, и вообще всех, кто подвернется.$B$BЕсли бы Зул\'джин был здесь, он бы уничтожил все это отродье одним движением руки! Но Зул\'джина с нами нет, поэтому приходится справляться самим.$B$BВот вам задание – пойти и убить троллей из племени Порочной Ветви.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 охотников за скальпами и 2 ворожеев из племени Порочной Ветви по поручению Яо\'джин из деревни Сломанного Клыка.$B$BЯо\'джин сказала, что эти тролли живут близ храмов Шаол\'вата и Агол\'вата в северо-восточной части Внутренних земель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно сделано, $C. Сам Зул\'джин не смог бы сделать работу лучше!!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ворожеи и охотники за скальпами из племени Порочной Ветви живут на северо-востоке Внутренних земель.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мистику Яо\'джин в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7845,'Похищен старейшина Сломанный Клык!','Однажды ночью племя Порочной Ветви совершило набег на нашу деревню и похитило моего мужа. Наши разведчики узнали, что он еще жив и находится в плену на самом верху Джинта\'Алора. Они сказали, что коварная жрица Ведьмиса хочет принести его в жертву их безлицему кровавому богу Хаккару.$B$BПрошу вас, $n, спасите его! Наша деревня не переживет такой тяжелой потери.','Спасите старейшину Сломанного Клыка из Джинта\'Алора по поручению его жены из деревни Сломанного Клыка.$B$BСтарейшину держат в плену на самом верху Джинта\'Алор – главного поселения троллей племени Порочной Ветви, расположенного на юге Внутренних земель.','Ты $Gдолжен:должна; действовать быстро, $N. Они явно уже узнали о твоем присутствии здесь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищен старейшина Сломанный Клык!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Однажды ночью племя Порочной Ветви совершило набег на нашу деревню и похитило моего мужа. Наши разведчики узнали, что он еще жив и находится в плену на самом верху Джинта\'Алора. Они сказали, что коварная жрица Ведьмиса хочет принести его в жертву их безлицему кровавому богу Хаккару.$B$BПрошу вас, $n, спасите его! Наша деревня не переживет такой тяжелой потери.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите старейшину Сломанного Клыка из Джинта\'Алора по поручению его жены из деревни Сломанного Клыка.$B$BСтарейшину держат в плену на самом верху Джинта\'Алор – главного поселения троллей племени Порочной Ветви, расположенного на юге Внутренних земель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gдолжен:должна; действовать быстро, $N. Они явно уже узнали о твоем присутствии здесь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7846,'Отыскать ключ!','Ключ от моих кандалов у Хита\'йи Хранительницы, она в пещере поблизости. Но будь $gосторожен:осторожна;, там полно охраны!$B$BУбей Хранительницу и возьми у нее ключ, иначе мне отсюда не выйти.','Убейте хранительницу Хита\'йю и заберите у нее ключ от кандалов, после чего возвращайтесь к старейшине Сломанному Клыку и освободите его.','Наконец-то свобода! Благодарю тебя, $N. Сломанный Клык узнает о твоих заслугах!','Поспешите!','Вернитесь к старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отыскать ключ!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ключ от моих кандалов у Хита\'йи Хранительницы, она в пещере поблизости. Но будь $gосторожен:осторожна;, там полно охраны!$B$BУбей Хранительницу и возьми у нее ключ, иначе мне отсюда не выйти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте хранительницу Хита\'йю и заберите у нее ключ от кандалов, после чего возвращайтесь к старейшине Сломанному Клыку и освободите его.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то свобода! Благодарю тебя, $N. Сломанный Клык узнает о твоих заслугах!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поспешите!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Сломанному Клыку в Джинта\'Алор, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (7847,'Возвращение к старейшине племени Сломанного Клыка','Вернитесь к моей жене, старейшей Зазубренный Клык! Скажите ей, что со мной все хорошо, и что скоро я буду дома. Она непременно наградит вас за это известие.','Возвращайтесь к старейшине Сломанному Клыку и сообщите ей, что ее муж спасен.','Вы оказали клану Сломанного Клыка неоценимую услугу, $N! Мы навечно в долгу перед вами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к старейшине племени Сломанного Клыка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вернитесь к моей жене, старейшей Зазубренный Клык! Скажите ей, что со мной все хорошо, и что скоро я буду дома. Она непременно наградит вас за это известие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к старейшине Сломанному Клыку и сообщите ей, что ее муж спасен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы оказали клану Сломанного Клыка неоценимую услугу, $N! Мы навечно в долгу перед вами.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (7848,'Сродство с недрами','Земля испещрена трещинами и разломами – прямо у нас под ногами, |3-6($r). В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра в Черной горы, в самую вотчину Повелителя огня.$B$B$gУдивлен:Удивлена;? Прискорбно... Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб...$B$BУверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться.$B$BСмотрю, у тебя глаза заблестели. Послушай, приобрести сродство с недрами не так сложно. Отправляйся в Глубины Черной горы и принеси мне осколок из Огненных Недр. Я сделаю так, что ты сможешь видеть портал.','Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте осколок из Огненных Недр. Принесите его Лотосу Хранителю Портала в Черной горе.','Теперь я могу открыть тебе дорогу в Огненные Недра. Ищи и обрящешь...','Вернитесь к Лотосу Хранителю Портала на Черную гору, что в Пылающих степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сродство с недрами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Земля испещрена трещинами и разломами – прямо у нас под ногами, |3-6($r). В двух шагах от того места, где ты сейчас стоишь, есть разлом, ведущий в недра в Черной горы, в самую вотчину Повелителя огня.$B$B$gУдивлен:Удивлена;? Прискорбно... Смертные не в силах понять то, что они не могут увидеть, пощупать, попробовать на зуб...$B$BУверяю тебя, ты стоишь прямо рядом с порталом и вполне можешь им воспользоваться.$B$BСмотрю, у тебя глаза заблестели. Послушай, приобрести сродство с недрами не так сложно. Отправляйся в Глубины Черной горы и принеси мне осколок из Огненных Недр. Я сделаю так, что ты сможешь видеть портал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь через портал, ведущий к Огненным Недрам в Глубинах Черной горы и добудьте осколок из Огненных Недр. Принесите его Лотосу Хранителю Портала в Черной горе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь я могу открыть тебе дорогу в Огненные Недра. Ищи и обрящешь...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лотосу Хранителю Портала на Черную гору, что в Пылающих степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7849,'Боль разлуки','Как и многие жители нашей деревни, мой близкий человек погиб в лесу. Это был мой брат-близнец Мальхор – он погиб в бою с троллями Порочной Ветви, тогда же, когда пропал муж старейшей племени Зазубренный Клык.$B$BМоего брата очень быстро казнили, а его останки бросили на съедение слизнюкам и волкам.$B$BЖизнь его мы не уберегли, но душу спасти еще можно. Пожалуйста, принесите мне его останки, $n.','Принесите охотнику Мархору из деревни Сломанного Клыка во Внутренних землях кости и череп его брата-близнеца.$B$BМархор сказал, что останки его брата бросили на съедение слизнюкам и волкам Порочной Ветви – все эти твари водятся неподалеку от вершины Джинта\'Алор: слизнюки в компостной яме, а волки – в логове.','$GМой:Моя; $Gдрагоценнейший:драгоценнейшая; $Gбрат:сестра;, как мне будет тебя не хватать…$B$BБлагодарю тебя за твою помощь, $N. Ты значительно $Gвырос:выросла; в моих глазах!','Когда все его останки будут у меня, я отнесу из Яйо\'джину и подготовлю их к надлежащему погребению.','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боль разлуки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как и многие жители нашей деревни, мой близкий человек погиб в лесу. Это был мой брат-близнец Мальхор – он погиб в бою с троллями Порочной Ветви, тогда же, когда пропал муж старейшей племени Зазубренный Клык.$B$BМоего брата очень быстро казнили, а его останки бросили на съедение слизнюкам и волкам.$B$BЖизнь его мы не уберегли, но душу спасти еще можно. Пожалуйста, принесите мне его останки, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите охотнику Мархору из деревни Сломанного Клыка во Внутренних землях кости и череп его брата-близнеца.$B$BМархор сказал, что останки его брата бросили на съедение слизнюкам и волкам Порочной Ветви – все эти твари водятся неподалеку от вершины Джинта\'Алор: слизнюки в компостной яме, а волки – в логове.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМой:Моя; $Gдрагоценнейший:драгоценнейшая; $Gбрат:сестра;, как мне будет тебя не хватать…$B$BБлагодарю тебя за твою помощь, $N. Ты значительно $Gвырос:выросла; в моих глазах!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда все его останки будут у меня, я отнесу из Яйо\'джину и подготовлю их к надлежащему погребению.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику Мархору в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7850,'Темные сосуды','Тролли племени Порочной Ветви проявляют в бою необычайную свирепость! Это все потому, что их околдовала недобрая коварная жрица Ведьмиса.$B$BВ поселении Джинта\'Алор можно найти очень много сосудов с порченой кровью, которые излучают темную магию безлицего кровавого бога и наделяют троллей сверхъестественными силами, сводя их с ума.$B$BУкрадите эти сосуды и принесите их мне, чтобы я сняла порчу и ослабила хватку кровавого бога.','Принесите 5 сосудов с порченой кровью старейшине племени Сломанного Клыка во Внутренние земли. Сосуды с кровью находятся в поселении Джинта\'Алор.','Темная энергия, что собирало племя Порочной Ветви, теперь ушла. Мы должны оставаться настороже, так как наша битва против зла еще не закончена. Даже если жрица Ведьмиса будет уничтожена, другая вскоре займет ее место.','Будьте осторожны в бою с троллями Порочной Ветви, $N. Их разум затуманен, и драться они будут до смерти.','Вернитесь к старейшине племени Сломанного Клыка в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные сосуды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тролли племени Порочной Ветви проявляют в бою необычайную свирепость! Это все потому, что их околдовала недобрая коварная жрица Ведьмиса.$B$BВ поселении Джинта\'Алор можно найти очень много сосудов с порченой кровью, которые излучают темную магию безлицего кровавого бога и наделяют троллей сверхъестественными силами, сводя их с ума.$B$BУкрадите эти сосуды и принесите их мне, чтобы я сняла порчу и ослабила хватку кровавого бога.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 сосудов с порченой кровью старейшине племени Сломанного Клыка во Внутренние земли. Сосуды с кровью находятся в поселении Джинта\'Алор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Темная энергия, что собирало племя Порочной Ветви, теперь ушла. Мы должны оставаться настороже, так как наша битва против зла еще не закончена. Даже если жрица Ведьмиса будет уничтожена, другая вскоре займет ее место.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будьте осторожны в бою с троллями Порочной Ветви, $N. Их разум затуманен, и драться они будут до смерти.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине племени Сломанного Клыка в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7861,'Разыскивается: коварная жрица Ведьмиса и ее прислужники','По приказу старейшины племени Сломанного Клыка разыскивается коварная жрица Ведьмиса и ее приспешники.$B$BТот, кто убьет Ведьмису и ее стражей Аман\'заси, получит отличную награду!','Убейте коварную жрицу Ведьмису и 5 стражей Аман\'заси из племени Порочной Ветви, после чего доложите старейшине племени Сломанного Клыка во Внутренних землях.$B$BКоварную жрицу Ведьмису и стражей Аман\'заси можно найти в верхней части Джинта\'Алора во Внутренних землях.','Хороший удар по Порочной Ветви, в самом деле. Тебе причитается, $N, и мы не поскупимся.','Вы приносите новости из Джинта\'алора?','Вернитесь к старейшине племени Сломанного Клыка в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разыскивается: коварная жрица Ведьмиса и ее прислужники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По приказу старейшины племени Сломанного Клыка разыскивается коварная жрица Ведьмиса и ее приспешники.$B$BТот, кто убьет Ведьмису и ее стражей Аман\'заси, получит отличную награду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте коварную жрицу Ведьмису и 5 стражей Аман\'заси из племени Порочной Ветви, после чего доложите старейшине племени Сломанного Клыка во Внутренних землях.$B$BКоварную жрицу Ведьмису и стражей Аман\'заси можно найти в верхней части Джинта\'Алора во Внутренних землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хороший удар по Порочной Ветви, в самом деле. Тебе причитается, $N, и мы не поскупимся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы приносите новости из Джинта\'алора?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине племени Сломанного Клыка в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7862,'Требуется: капитан стражи в деревню Сломанного Клыка','Капитан стражи Мальхор погиб, и теперь эта должность свободна. Если вы хотите стать капитаном стражи в деревне Сломанного Клыка, выполните эти задания и подайте заявление старейшине племени Сломанного Клыка.$B$BУничтожьте берсерков из племени Порочной Ветви.$B$BУничтожьте темных охотников из племени Порочной Ветви.$B$BУничтожьте кровопийц из племени Порочной Ветви.$B$BУничтожьте пожирателей душ из племени Порочной Ветви.','Убейте 5 берсерков, 3 темных охотника, 3 кровопийц и 2 пожирателей душ из племени Порочной Ветви.$B$BПосле выполнения задания вернитесь к старейшине Сломанному Клыку в деревню Сломанного Клыка.','Вы и правда отлично подходите для такой работы, $N. Примите это в знак признательности и благодарности за ваши старания. Через год я еще раз пересмотрю все кандидатуры.','Вы здесь по поводу вакансии?','Вернитесь к старейшине племени Сломанного Клыка в Деревню Сломанного Клыка, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требуется: капитан стражи в деревню Сломанного Клыка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Капитан стражи Мальхор погиб, и теперь эта должность свободна. Если вы хотите стать капитаном стражи в деревне Сломанного Клыка, выполните эти задания и подайте заявление старейшине племени Сломанного Клыка.$B$BУничтожьте берсерков из племени Порочной Ветви.$B$BУничтожьте темных охотников из племени Порочной Ветви.$B$BУничтожьте кровопийц из племени Порочной Ветви.$B$BУничтожьте пожирателей душ из племени Порочной Ветви.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 берсерков, 3 темных охотника, 3 кровопийц и 2 пожирателей душ из племени Порочной Ветви.$B$BПосле выполнения задания вернитесь к старейшине Сломанному Клыку в деревню Сломанного Клыка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы и правда отлично подходите для такой работы, $N. Примите это в знак признательности и благодарности за ваши старания. Через год я еще раз пересмотрю все кандидатуры.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы здесь по поводу вакансии?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине племени Сломанного Клыка в Деревню Сломанного Клыка, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (7863,'Полевой комплект часового','Ты хорошо $Gзарекомендовал:зарекомендовала; себя, $N, тут сомнений нет! В награду возьми этот пакет! В нем паек и бинты, которые найдешь только в Ущелье Песни Войны.$B$BКогда в Ущелье тебя еще больше зауважают, тебе их тут даже продадут. Паек мы выдаем, если относимся к кому-то дружественно, а бинты – когда уважаем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полевой комплект часового',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хорошо $Gзарекомендовал:зарекомендовала; себя, $N, тут сомнений нет! В награду возьми этот пакет! В нем паек и бинты, которые найдешь только в Ущелье Песни Войны.$B$BКогда в Ущелье тебя еще больше зауважают, тебе их тут даже продадут. Паек мы выдаем, если относимся к кому-то дружественно, а бинты – когда уважаем.',`offerrewardtext_loc8`);
