INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7871,'Долой захватчиков!','$gЮный:Юная:c; |3-6($c)! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$b$bОтправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!$b$bНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $n, и получишь награду!','Войдите в Ущелье Песни Войны, одержите победу над Ордой, получите почетный знак ущелья Песни Войны и вернитесь с ним к часовому Дальней Песне в рощу Среброкрылых.','Вернитесь к часовому Дальней Песне в Зеркало Небес, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долой захватчиков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gЮный:Юная:c; |3-6($c)! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$b$bОтправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!$b$bНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $n, и получишь награду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в Ущелье Песни Войны, одержите победу над Ордой, получите почетный знак ущелья Песни Войны и вернитесь с ним к часовому Дальней Песне в рощу Среброкрылых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Дальней Песне в Зеркало Небес, что в Ясеневом лесу.',`completedtext_loc8`);
