INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (7908,'Повелитель арены','Должно быть, стать повелителем арены не так просто! Быть может, пират-распорядитель на Арене Гурубаши, знает, в чем тут штука!','Поговорите с Коротышкой Джоном Мифрилом на арене Тернистой долины.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелитель арены',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, стать повелителем арены не так просто! Быть может, пират-распорядитель на Арене Гурубаши, знает, в чем тут штука!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Коротышкой Джоном Мифрилом на арене Тернистой долины.',`objectives_loc8`);
