INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7937,'Ты найдешь свою удачу...','"Ты найдешь свою удачу в Восточной долине".$B$BЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите Лесопилку Восточной долины в Элвиннском лесу. Возле стойл стоит копна сена... На этом видение обрывается.','Отыщите свою удачу на Лесопилке Восточной долины в Элвиннском лесу.','После быстрого обыска стога ты находишь защищенный сейф внутри него! Казалось бы, что ты $Gнашел:нашла; свою удачу!','Этот стог выглядит как тот стог из твоего видения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ты найдешь свою удачу...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Ты найдешь свою удачу в Восточной долине".$B$BЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите Лесопилку Восточной долины в Элвиннском лесу. Возле стойл стоит копна сена... На этом видение обрывается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите свою удачу на Лесопилке Восточной долины в Элвиннском лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','После быстрого обыска стога ты находишь защищенный сейф внутри него! Казалось бы, что ты $Gнашел:нашла; свою удачу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Этот стог выглядит как тот стог из твоего видения.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7938,'Ты найдешь свою удачу...','"Ты найдешь свою удачу в Мертвых копях".$B$BЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите Мертвые копи возле разрушенной деревни Луноречье в Западном Крае. Запутанные ходы приводят вас к порталу, который ведет в самое сердце шахт. Вдруг перед порталом возникает странный сундук... На этом видение обрывается.','Отыскать свою удачу в Мертвых копях в Западном Крае.','Быстрый осмотр сундука обнаруживает внутри него сейф! Удача вам благоволит!','Этот сундук очень похож на тот, что явился вам в видении.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ты найдешь свою удачу...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Ты найдешь свою удачу в Мертвых копях".$B$BЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите Мертвые копи возле разрушенной деревни Луноречье в Западном Крае. Запутанные ходы приводят вас к порталу, который ведет в самое сердце шахт. Вдруг перед порталом возникает странный сундук... На этом видение обрывается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыскать свою удачу в Мертвых копях в Западном Крае.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Быстрый осмотр сундука обнаруживает внутри него сейф! Удача вам благоволит!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Этот сундук очень похож на тот, что явился вам в видении.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7939,'Обмен: увесистые точильные камни','Спасибо большое, $N. Вот твои купоны.','$N, спасибо за всю помощь, которую ты мне $Gоказал:оказала;. Я действительно не могу тебя отблагодарить!$B$BХотя моя потребность больше не велика ... если ты принесешь мне более плотные шлифовальные камни, у меня все равно будет для тебя больше билетов на ярмарку Новолуния.','Вернитесь к Керри Хикс.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обмен: увесистые точильные камни',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо большое, $N. Вот твои купоны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, спасибо за всю помощь, которую ты мне $Gоказал:оказала;. Я действительно не могу тебя отблагодарить!$B$BХотя моя потребность больше не велика ... если ты принесешь мне более плотные шлифовальные камни, у меня все равно будет для тебя больше билетов на ярмарку Новолуния.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Керри Хикс.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7940,'1200 билетов – сфера Новолуния','Не зевай, забирай! Приз, достойный короля! Поздравляю с приобретением!$B$BЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!','Налетай, торопись, выбирай себе приз! У кого есть купоны ярмарки Новолуния – подходите и обменяйте их на диковины волшебного свойства и исключительного качества! Ни орк, ни дворф не уйдет без призов!','Вернитесь к Гелвасу Углешлюзу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','1200 билетов – сфера Новолуния',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не зевай, забирай! Приз, достойный короля! Поздравляю с приобретением!$B$BЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Налетай, торопись, выбирай себе приз! У кого есть купоны ярмарки Новолуния – подходите и обменяйте их на диковины волшебного свойства и исключительного качества! Ни орк, ни дворф не уйдет без призов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гелвасу Углешлюзу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7941,'Еще накладки на доспехи','А вот и ты, $N. Отличная торговля. Наслаждайся.','$N, я так тебе благодарен! Теперь твоими стараниями у меня припасов больше, чем нужно! Но если у тебя еще завалялись комплекты грубой брони – приноси, а я уж найду им применение. За комплекты брони я расплачусь купонами ярмарки Новолуния.','Вернитесь к Хроносу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще накладки на доспехи',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А вот и ты, $N. Отличная торговля. Наслаждайся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, я так тебе благодарен! Теперь твоими стараниями у меня припасов больше, чем нужно! Но если у тебя еще завалялись комплекты грубой брони – приноси, а я уж найду им применение. За комплекты брони я расплачусь купонами ярмарки Новолуния.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроносу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7942,'Обмен: ториевые устройства','Вот ты где, $N. Вот билеты на ярмарку Новолуния для твоего удовольствия. Не стоит, как говорится, все в одном месте тратить!','$N, ты столько для меня $Gсделал:сделала;! Я бесконечно тебе благодарен.$B$BТориевых устройств мне теперь хватит надолго, но если у тебя завалялась еще парочка-другая – приноси. Я дам тебе за них купоны ярмарки.','Вернитесь к Ринлингу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обмен: ториевые устройства',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот ты где, $N. Вот билеты на ярмарку Новолуния для твоего удовольствия. Не стоит, как говорится, все в одном месте тратить!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты столько для меня $Gсделал:сделала;! Я бесконечно тебе благодарен.$B$BТориевых устройств мне теперь хватит надолго, но если у тебя завалялась еще парочка-другая – приноси. Я дам тебе за них купоны ярмарки.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ринлингу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7943,'Обмен: глаза летучих мышей','Еще раз спасибо, $N. Вот ваши купоны!','$N, мой новый аттракцион будет пострашнее гномреганской катастрофы! И я не забуду о твоем вкладе в этот проект! Спасибо тебе еще раз!$B$BЭтих запасов мне хватит надолго, но если ты раздобудешь глаза злобных летучих мышей из Восточных Чумных земель, я с удовольствием обменяю их на купоны ярмарки Новолуния!','Вернитесь к Эббу Ниблгиру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обмен: глаза летучих мышей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще раз спасибо, $N. Вот ваши купоны!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, мой новый аттракцион будет пострашнее гномреганской катастрофы! И я не забуду о твоем вкладе в этот проект! Спасибо тебе еще раз!$B$BЭтих запасов мне хватит надолго, но если ты раздобудешь глаза злобных летучих мышей из Восточных Чумных земель, я с удовольствием обменяю их на купоны ярмарки Новолуния!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эббу Ниблгиру.',`completedtext_loc8`);
