INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (7945,'Ты найдешь свою удачу...','"Ты найдешь свою удачу возле утеса Бледногривов".$B$BЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите утес Бледногривов в Мулгоре. Возле входа в пещеру стоит пень... На этом видение обрывается.','Отыскать свою удачу возле утеса Бледногривов в Мулгоре.','Из дупла в пне вы извлекли небольшой сейф. Видимо, в нем-то и скрывается ваша удача.','Судя по видению, вам нужен именно этот пень...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ты найдешь свою удачу...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','"Ты найдешь свою удачу возле утеса Бледногривов".$B$BЗаписка, которую вам дал Воржей, излучает тепло. Вы сжимаете ее в руках и видите утес Бледногривов в Мулгоре. Возле входа в пещеру стоит пень... На этом видение обрывается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыскать свою удачу возле утеса Бледногривов в Мулгоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Из дупла в пне вы извлекли небольшой сейф. Видимо, в нем-то и скрывается ваша удача.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Судя по видению, вам нужен именно этот пень...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (7946,'Потомство Жабжаб','Вернитесь к Морье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потомство Жабжаб',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7961,'Всюду кролики!','Кролики плодятся с бешеной скоростью! Надо что-то делать!$b$bПомоги нам, $n, ты наша единственная надежда!','Соберите 10 несчастливых лапок кролика и вернитесь к Джону Лекрафту к кузнице на острове Дизайнера.','Вернитесь к Джонатану Лекрафту на Остров Дизайнера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всюду кролики!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кролики плодятся с бешеной скоростью! Надо что-то делать!$b$bПомоги нам, $n, ты наша единственная надежда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 несчастливых лапок кролика и вернитесь к Джону Лекрафту к кузнице на острове Дизайнера.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джонатану Лекрафту на Остров Дизайнера.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (7962,'Кроличьи шкурки','Мне нужны шкурки кроликов Лекрафта. Добудь мне несколько штук.$b$bЭто важно!','Принесите 3 шкурки кроликов Лекрафта Джону Лекрафту.','Вернитесь к Джонатану Лекрафту на Остров Дизайнера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кроличьи шкурки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужны шкурки кроликов Лекрафта. Добудь мне несколько штук.$b$bЭто важно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 шкурки кроликов Лекрафта Джону Лекрафту.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джонатану Лекрафту на Остров Дизайнера.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (7981,'1200 билетов – амулет Новолуния','Не зевай, забирай! Приз, достойный короля! Поздравляю с приобретением!$B$BЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!','Налетай, торопись, выбирай себе приз! У кого есть купоны ярмарки Новолуния – подходите и обменяйте их на диковины волшебного свойства и исключительного качества! Ни орк, ни дворф не уйдет без призов!','Вернитесь к Гелвасу Углешлюзу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','1200 билетов – амулет Новолуния',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не зевай, забирай! Приз, достойный короля! Поздравляю с приобретением!$B$BЕсли у тебя еще появятся купоны – приходи, призов у меня целый воз и маленькая тележка!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Налетай, торопись, выбирай себе приз! У кого есть купоны ярмарки Новолуния – подходите и обменяйте их на диковины волшебного свойства и исключительного качества! Ни орк, ни дворф не уйдет без призов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гелвасу Углешлюзу.',`completedtext_loc8`);
