INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8041,'Сила горы Мугамба','Привет, $C.Я Джин\'рок Разрушитель, тролль Мугамбы. Мы, представители племени Зандалар, признаем твои достижения. Мы приветствуем твое упорство и силу воли.$B$BНоси этот талисман на шее, $C. Позволь силе горы Мугамба течь через твое нутро. Обрети силу, сокрушая наших врагов!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила горы Мугамба',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет, $C.Я Джин\'рок Разрушитель, тролль Мугамбы. Мы, представители племени Зандалар, признаем твои достижения. Мы приветствуем твое упорство и силу воли.$B$BНоси этот талисман на шее, $C. Позволь силе горы Мугамба течь через твое нутро. Обрети силу, сокрушая наших врагов!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8042,'Сила горы Мугамба','Наши пути снова пересекутся, $C.','Приятно видеть тебя в добром здравии, $N. Каждый из нас наслышан про битвы, в которых тебе удалось одержать победу. Хаккар не должен покинуть пределы Зул\'Гуруба, иначе он поглотит весь мир!$B$BДай мне свой талисман, я наполню его силой. Используй Силу Мугамбы, чтобы покарать наших врагов!','Вернитесь к Джин\'року Разрушителю в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила горы Мугамба',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наши пути снова пересекутся, $C.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приятно видеть тебя в добром здравии, $N. Каждый из нас наслышан про битвы, в которых тебе удалось одержать победу. Хаккар не должен покинуть пределы Зул\'Гуруба, иначе он поглотит весь мир!$B$BДай мне свой талисман, я наполню его силой. Используй Силу Мугамбы, чтобы покарать наших врагов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8043,'Сила горы Мугамба','Используйте свои новообретенные силы, чтобы уничтожить Гурубаши!','$GГосподин/Госпожа; $N, ты $Gвернулся:вернулась;! Молтор рассказал о твоих подвигах самому королю. Твоя слава достигла Южных морей. В один прекрасный день ты станешь $Gлегендарным:легендарной; $Gвоителем:воительницей; и войдешь в историю на века.$B$BДай мне свой талисман, я еще немного увеличу его силу.','Вернитесь к Джин\'року Разрушителю в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила горы Мугамба',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Используйте свои новообретенные силы, чтобы уничтожить Гурубаши!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GГосподин/Госпожа; $N, ты $Gвернулся:вернулась;! Молтор рассказал о твоих подвигах самому королю. Твоя слава достигла Южных морей. В один прекрасный день ты станешь $Gлегендарным:легендарной; $Gвоителем:воительницей; и войдешь в историю на века.$B$BДай мне свой талисман, я еще немного увеличу его силу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8044,'Ярость Мугамбы','Зул\'джин позавидовал бы, $C. Идите вперед и побеждайте!','Король Растахан посылает тебе слова благодарности, $Gгосподин:госпожа; $N. Подобная честь до сих пор не оказывалось ни одному чужаку.$B$B<Джинрок кланяется.>$B$BДай мне свой талисман, и я усилю его. Теперь Ярость Мугамбы неразрывно связана с твоей душой.','Вернитесь к Джин\'року Разрушителю в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярость Мугамбы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Зул\'джин позавидовал бы, $C. Идите вперед и побеждайте!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Король Растахан посылает тебе слова благодарности, $Gгосподин:госпожа; $N. Подобная честь до сих пор не оказывалось ни одному чужаку.$B$B<Джинрок кланяется.>$B$BДай мне свой талисман, и я усилю его. Теперь Ярость Мугамбы неразрывно связана с твоей душой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8045,'Клеймо язычника','Знай, язычник: катастрофа свела нас вместе. Зандалар не понимает и не ценит твои языческие обычаи, но мы справедливые создания. Носи эту печать на шее. Он послужит предупреждением для наших врагов и символом дружбы с Зандаларом.$B$BПродолжайте служить нашему народу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клеймо язычника',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знай, язычник: катастрофа свела нас вместе. Зандалар не понимает и не ценит твои языческие обычаи, но мы справедливые создания. Носи эту печать на шее. Он послужит предупреждением для наших врагов и символом дружбы с Зандаларом.$B$BПродолжайте служить нашему народу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8046,'Клеймо Язычника','Сделай все возможное, чтобы победить наших врагов, $C. Даже если для этого потребуется направить Свет.$B$B<Джин\'рох вздрагивает.>','Похоже, я слишком поторопился в своих суждениях, $C. Твоя слепая вера в этот Свет чего-то стоит.$B$BДай мне свое клеймо, я увеличу его силу.','Вернитесь к Джин\'року Разрушителю в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клеймо Язычника',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сделай все возможное, чтобы победить наших врагов, $C. Даже если для этого потребуется направить Свет.$B$B<Джин\'рох вздрагивает.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, я слишком поторопился в своих суждениях, $C. Твоя слепая вера в этот Свет чего-то стоит.$B$BДай мне свое клеймо, я увеличу его силу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8047,'Клеймо Язычника','Наши убеждения различны, но наше дело правое. Срази наших врагов, $C.','Должен признаться, я не думал, что у тебя хватит решимости довести это дело до конца, $C. Ты $Gстал:стала; для Зандалара бесценным союзником. В самом деле, я восхищен.$B$BДай мне свое клеймо, я увеличу его силу.','Вернитесь к Джин\'року Разрушителю в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клеймо Язычника',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наши убеждения различны, но наше дело правое. Срази наших врагов, $C.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Должен признаться, я не думал, что у тебя хватит решимости довести это дело до конца, $C. Ты $Gстал:стала; для Зандалара бесценным союзником. В самом деле, я восхищен.$B$BДай мне свое клеймо, я увеличу его силу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8048,'Печать героя','Бдительность, честь, верность, храбрость... Вы воплощаете все эти качества.','Король признал твое существование, $C. Вы первый в своем роде, которого Растахан принял как верного союзника Зандалара.$B$BВы будете очень вознаграждены за свои усилия. Представьте свой бренд, и я применю финальное усиление.','Вернитесь к Джин\'року Разрушителю в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печать героя',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бдительность, честь, верность, храбрость... Вы воплощаете все эти качества.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Король признал твое существование, $C. Вы первый в своем роде, которого Растахан принял как верного союзника Зандалара.$B$BВы будете очень вознаграждены за свои усилия. Представьте свой бренд, и я применю финальное усиление.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8049,'Око Зулдазара','Примите этот талисман в знак нашей признательности, $C.$B$BГлаз Зулдазара будет набирать силу по мере того, как укрепляется ваша связь с троллями Зандалара. Периодически возвращайтесь ко мне, и я наполню этот драгоценный камень.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око Зулдазара',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Примите этот талисман в знак нашей признательности, $C.$B$BГлаз Зулдазара будет набирать силу по мере того, как укрепляется ваша связь с троллями Зандалара. Периодически возвращайтесь ко мне, и я наполню этот драгоценный камень.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8050,'Око Зулдазара','Будьте решительны в своих действиях, $N. Убийца Душ будет пытаться подавить вашу волю к жизни.','Добро пожаловать, $C. Око Зулдазара пульсирует энергией. Вы готовы сделать следующий шаг. Дай мне талисман, и я выполню наполнение.','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око Зулдазара',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будьте решительны в своих действиях, $N. Убийца Душ будет пытаться подавить вашу волю к жизни.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать, $C. Око Зулдазара пульсирует энергией. Вы готовы сделать следующий шаг. Дай мне талисман, и я выполню наполнение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8051,'Око Зулдазара','Продолжай сражаться с Убийцей Душ и его приспешниками, $N. Ему нельзя позволить покинуть пределы Зул\'Гуруб.','Сказки о твоих битвах с Гурубаши разносятся ветром, $C. Даже члены королевской семьи начинают говорить о ваших поступках. Ходят слухи, что король Растахан даже упомянул вас по имени.$B$BПришло время наполнить Око. Дай мне талисман, и я выполню службу.','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Око Зулдазара',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Продолжай сражаться с Убийцей Душ и его приспешниками, $N. Ему нельзя позволить покинуть пределы Зул\'Гуруб.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сказки о твоих битвах с Гурубаши разносятся ветром, $C. Даже члены королевской семьи начинают говорить о ваших поступках. Ходят слухи, что король Растахан даже упомянул вас по имени.$B$BПришло время наполнить Око. Дай мне талисман, и я выполню службу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8052,'Всевидящее Око Зулдазара','Разбейте их всех и позвольте Хаккару разобраться с ними','Если бы у нас было еще десять тысяч таких, как ты, $N. Армии Хаккара будут развеяны по ветру в мгновение ока.$B$BУвы, Око готов полностью реализовать свой потенциал. Дай это мне.','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всевидящее Око Зулдазара',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разбейте их всех и позвольте Хаккару разобраться с ними',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если бы у нас было еще десять тысяч таких, как ты, $N. Армии Хаккара будут развеяны по ветру в мгновение ока.$B$BУвы, Око готов полностью реализовать свой потенциал. Дай это мне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8053,'Знаки Силы: боевые наручи вольнодумца','Ты – $gязычник:язычница;, но мы не преследуем язычников в нашем племени. Мы уважаем тех, кто не боится гонений и без колебаний готов принять смерть за свою веру. Мы знаем, что ты $gготов:готова; умереть за свои убеждения, наши вольнодумцы тоже были такими.$B$BНам нужны Знаки Силы. Ступай в Зул\'Гуруб и уничтожь прислужников Хаккара. Возвращайся, когда найдешь то, что мне нужно. В обмен я отдам тебе одну из деталей брони зандаларских вольнодумцев.','Принесите Джин\'року Разрушителю изначальные поручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.','Вы делаете многое, чтобы нас почтить. С твоих рук капает кровь приспешников Хаккара. Вы друг племени.$B$BНосите эти наручи. Это наручи вольнодумца. Вот что я имею в виду под реальной властью.','Ты $Gвернулся:вернулась;? Знаки Силы с тобой? Или ты просто отнимаешь у меня время?$B$BЯ надеюсь, что нет, язычник.','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: боевые наручи вольнодумца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты – $gязычник:язычница;, но мы не преследуем язычников в нашем племени. Мы уважаем тех, кто не боится гонений и без колебаний готов принять смерть за свою веру. Мы знаем, что ты $gготов:готова; умереть за свои убеждения, наши вольнодумцы тоже были такими.$B$BНам нужны Знаки Силы. Ступай в Зул\'Гуруб и уничтожь прислужников Хаккара. Возвращайся, когда найдешь то, что мне нужно. В обмен я отдам тебе одну из деталей брони зандаларских вольнодумцев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Джин\'року Разрушителю изначальные поручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы делаете многое, чтобы нас почтить. С твоих рук капает кровь приспешников Хаккара. Вы друг племени.$B$BНосите эти наручи. Это наручи вольнодумца. Вот что я имею в виду под реальной властью.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;? Знаки Силы с тобой? Или ты просто отнимаешь у меня время?$B$BЯ надеюсь, что нет, язычник.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8054,'Знаки силы: пояс вольнодумца','Твои верования для нас чужды, $gязычник:язычница;. Но племя Зандалара в свое время тоже называли еретиками. Это было еще во времена расцвета Гурубаши. Тогда язычники осмелились бросить вызов жрецам Хаккара. Их нещадно преследовали и уничтожали, словно диких зверей, но они до самого конца не отступили в своей борьбе против Кровавого бога. Мы понимаем, какую цену им пришлось заплатить, и чтим их мужество. Они были настоящими вольнодумцами. $B$BУничтожь приспешников Хаккара в Зул\'Гурубе и принеси мне Знаки Силы. В случае успеха тебя ждет награда.$B$BСтупай.','Принесите Джин\'року Разрушителю изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.','Ваше почтение гарантирована в племени. Враги падают перед вашей мощью.$B$BЭто пояс вольнодумца. Это символ чести. Это мощный моджо. Это теперь твое.','Знаки у тебя? Обагрила ли кровь врагов твои доспехи?','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки силы: пояс вольнодумца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои верования для нас чужды, $gязычник:язычница;. Но племя Зандалара в свое время тоже называли еретиками. Это было еще во времена расцвета Гурубаши. Тогда язычники осмелились бросить вызов жрецам Хаккара. Их нещадно преследовали и уничтожали, словно диких зверей, но они до самого конца не отступили в своей борьбе против Кровавого бога. Мы понимаем, какую цену им пришлось заплатить, и чтим их мужество. Они были настоящими вольнодумцами. $B$BУничтожь приспешников Хаккара в Зул\'Гурубе и принеси мне Знаки Силы. В случае успеха тебя ждет награда.$B$BСтупай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Джин\'року Разрушителю изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ваше почтение гарантирована в племени. Враги падают перед вашей мощью.$B$BЭто пояс вольнодумца. Это символ чести. Это мощный моджо. Это теперь твое.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаки у тебя? Обагрила ли кровь врагов твои доспехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8055,'Знаки Силы: кираса вольнодумца','Боевое снаряжение – это символ могущества. Вольнодумцы же особенно гордятся своими доспехами. Они усиливают кирасы могущественными заклятиями, и даже если во время боя их вера пошатнется, то кирасы выдержат все что угодно.$B$BЕсли ты заслужишь уважение нашего племени, то получишь такую кирасу. Ступай в Зул\'Гуруб и принеси мне Знаки Силы. Вырви их у врага безо всякой пощады. Докажи, что ты заслуживаешь звания вольнодумца.','Принесите Джин\'року Разрушителю Изначальную гербовую накидку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.','Вы сделали то, что могли немногие. Вы поставили приспешников Хаккара на колени. Вы показали им, на что способен вольнодумец. Вы показали нам, как в племени могут почитать еретика. У вас больше, чем реальная власть. Ты настоящая сила.$B$BВозьми нагрудник, вольнодумец. Сокрушайте тех, кто противостоит нам.','Знаки Силы у тебя? Нам необходимы могучие заклятия, заключенные в них. Если ты добудешь эти знаки, то здорово поможешь племени.','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: кираса вольнодумца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боевое снаряжение – это символ могущества. Вольнодумцы же особенно гордятся своими доспехами. Они усиливают кирасы могущественными заклятиями, и даже если во время боя их вера пошатнется, то кирасы выдержат все что угодно.$B$BЕсли ты заслужишь уважение нашего племени, то получишь такую кирасу. Ступай в Зул\'Гуруб и принеси мне Знаки Силы. Вырви их у врага безо всякой пощады. Докажи, что ты заслуживаешь звания вольнодумца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Джин\'року Разрушителю Изначальную гербовую накидку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы сделали то, что могли немногие. Вы поставили приспешников Хаккара на колени. Вы показали им, на что способен вольнодумец. Вы показали нам, как в племени могут почитать еретика. У вас больше, чем реальная власть. Ты настоящая сила.$B$BВозьми нагрудник, вольнодумец. Сокрушайте тех, кто противостоит нам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаки Силы у тебя? Нам необходимы могучие заклятия, заключенные в них. Если ты добудешь эти знаки, то здорово поможешь племени.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8056,'Знаки Силы: наручи авгура','Авгуры нашего племени очень гордятся своим даром предвидения. Это тебе не знахари, которые только и знают, что проклинать направо и налево! Нет, наши авгуры предсказывают будущее по костям и листьям. Тебе, как $Gшаману:шаманке;, должно быть известно, на что способны авгуры. В Зандаларе их откровения очень ценятся.$B$BПокажи нам, чего ты стоишь, и принеси Знаки Силы из Зул\'Гуруба. Если тебе это удастся, я отдам тебе наручи, которыми наши авгуры очень дорожат.','Принесите Мейвики Зулдазарской Изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BМейвики Зулдазарская живет на острове Йоджамба, в Тернистой долине.','Кажется, в тебе есть немного зандаларского авгура. Мы знаем о деяниях, которые ты $Gсовершал:совершала; в Зул\'Гуруб от нашего имени, друг. Эти Знаки силы будут иметь большое значение, чтобы помочь племени Зандалар - племени,которое теперь считает тебя другом. Возьми эти наручи, $N ты их $Gзаработал:заработала;!','$Gполучил:получила; нужные мне Знаки силы из Зул\'Гуруба? Эти наручи стоят любых усилий, которые вам понадобятся!','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: наручи авгура',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Авгуры нашего племени очень гордятся своим даром предвидения. Это тебе не знахари, которые только и знают, что проклинать направо и налево! Нет, наши авгуры предсказывают будущее по костям и листьям. Тебе, как $Gшаману:шаманке;, должно быть известно, на что способны авгуры. В Зандаларе их откровения очень ценятся.$B$BПокажи нам, чего ты стоишь, и принеси Знаки Силы из Зул\'Гуруба. Если тебе это удастся, я отдам тебе наручи, которыми наши авгуры очень дорожат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мейвики Зулдазарской Изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BМейвики Зулдазарская живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кажется, в тебе есть немного зандаларского авгура. Мы знаем о деяниях, которые ты $Gсовершал:совершала; в Зул\'Гуруб от нашего имени, друг. Эти Знаки силы будут иметь большое значение, чтобы помочь племени Зандалар - племени,которое теперь считает тебя другом. Возьми эти наручи, $N ты их $Gзаработал:заработала;!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$Gполучил:получила; нужные мне Знаки силы из Зул\'Гуруба? Эти наручи стоят любых усилий, которые вам понадобятся!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8057,'Знаки Силы: наручи гаруспика','Гаруспики играют не последнюю роль в нашем племени; если ты достаточно $Gмудр:мудра;, то обязательно прислушаешься к их предсказаниям. Они читают судьбу по внутренностям животных и приносят их в жертву духам, чтобы узнать божественную волю. Именно мудрость гаруспиков дала нам преимущество в войне с разрозненными племенами империи Гурубаши.$B$BДокажи нашему племени, чего ты стоишь. Принеси из Зул\'Гуруба Знаки Силы, и я отдам тебе наручи, от которых не отказался бы никто из гаруспиков Зандалара.','Принесите Мейвики Зулдазарской изначальный браслет Хаккари. Кроме того, вам необходимо заслужить как минимум дружественное отношение племени Зандалар.$B$BМейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.','Ах, я чувствую силу, исходящую от этих Знаков силы, $N. Ты оказался тем, кого мы в племени можем назвать «другом». Сделка есть сделка, $N... Вот наручи зандаларского гаруспика!','Ты $Gдобыл:добыла; Знаки Силы в Зул\'Гурубе? Эти наручи того стоят, Квилладру, можешь мне поверить!','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: наручи гаруспика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гаруспики играют не последнюю роль в нашем племени; если ты достаточно $Gмудр:мудра;, то обязательно прислушаешься к их предсказаниям. Они читают судьбу по внутренностям животных и приносят их в жертву духам, чтобы узнать божественную волю. Именно мудрость гаруспиков дала нам преимущество в войне с разрозненными племенами империи Гурубаши.$B$BДокажи нашему племени, чего ты стоишь. Принеси из Зул\'Гуруба Знаки Силы, и я отдам тебе наручи, от которых не отказался бы никто из гаруспиков Зандалара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мейвики Зулдазарской изначальный браслет Хаккари. Кроме того, вам необходимо заслужить как минимум дружественное отношение племени Зандалар.$B$BМейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, я чувствую силу, исходящую от этих Знаков силы, $N. Ты оказался тем, кого мы в племени можем назвать «другом». Сделка есть сделка, $N... Вот наручи зандаларского гаруспика!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдобыл:добыла; Знаки Силы в Зул\'Гурубе? Эти наручи того стоят, Квилладру, можешь мне поверить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8058,'Знаки Силы: боевые наручи воздаятеля','Месть – это сила. Именно она движет блюстителями Зандалара. У племени много врагов, и блюстители несут им воздаяние. Ни одно преступление против нас не останется безнаказанным! Враги должны бояться нашей мести! Так было раньше и так будет всегда.$B$BСтань одним из наших блюстителей! Найди Знаки Силы в Зул\'Гурубе. Соверши возмездие от имени нашего племени и уничтожь прислужников Хаккара. Ты будешь $Gнагражден:награждена;.','Принесите Джин\'року Разрушителю изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.','Сегодня вы отомстили. Вы приняли облик мстителя. Вы поставили слуг Кровавого Бога на колени.$B$BЭто будет подпитывать вашу месть в будущем. Теперь ты друг Зандалара.','Тебе удалось достать Знаки Силы? Свершилось ли возмездие во имя Зандалара?','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: боевые наручи воздаятеля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Месть – это сила. Именно она движет блюстителями Зандалара. У племени много врагов, и блюстители несут им воздаяние. Ни одно преступление против нас не останется безнаказанным! Враги должны бояться нашей мести! Так было раньше и так будет всегда.$B$BСтань одним из наших блюстителей! Найди Знаки Силы в Зул\'Гурубе. Соверши возмездие от имени нашего племени и уничтожь прислужников Хаккара. Ты будешь $Gнагражден:награждена;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Джин\'року Разрушителю изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодня вы отомстили. Вы приняли облик мстителя. Вы поставили слуг Кровавого Бога на колени.$B$BЭто будет подпитывать вашу месть в будущем. Теперь ты друг Зандалара.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось достать Знаки Силы? Свершилось ли возмездие во имя Зандалара?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8059,'Знаки Силы: напульсники бесноватого','Чернокнижники ступают на опасную почву, заключая сделки с демонами, но наши бесноватые зашли еще дальше. С помощью древнего ритуала они позволяют демону захватить свое тело, а потом пытаются подчинить его своей воле и использовать его силу. Совершить такой подвиг удается не многим.$B$BЕсли хочешь приобщиться к знанию бесноватых, принеси мне Знаки Силы из Зул\'Гуруба.','Принесите Ал\'табиму Всевидящему изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.','Хорошо...без сомнения, их заставили заплатить мучительными способами, прежде чем они отказались от Знаков силы. Возьми это - дьявольские напульсники. Сделанный из мощного заклинания, используемого при вызове добычи демона, он является мощным инструментом в твоем обретении силы.','Тебе удалось добыть Знаки Силы? Сражаясь со злобными приспешниками Хаккара, ты не только доказываешь готовность постичь пути бесноватых, но подтверждаешь для нас свою важность.','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: напульсники бесноватого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чернокнижники ступают на опасную почву, заключая сделки с демонами, но наши бесноватые зашли еще дальше. С помощью древнего ритуала они позволяют демону захватить свое тело, а потом пытаются подчинить его своей воле и использовать его силу. Совершить такой подвиг удается не многим.$B$BЕсли хочешь приобщиться к знанию бесноватых, принеси мне Знаки Силы из Зул\'Гуруба.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ал\'табиму Всевидящему изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо...без сомнения, их заставили заплатить мучительными способами, прежде чем они отказались от Знаков силы. Возьми это - дьявольские напульсники. Сделанный из мощного заклинания, используемого при вызове добычи демона, он является мощным инструментом в твоем обретении силы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть Знаки Силы? Сражаясь со злобными приспешниками Хаккара, ты не только доказываешь готовность постичь пути бесноватых, но подтверждаешь для нас свою важность.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8060,'Знаки Силы: напульсники мастера иллюзий','Маги нашего племени – это творцы иллюзий. В свои чары они вплетают заклинания, одурманивающие врагов и сбивающие их с толку.$B$B*Альтабим злорадно хихикает.*$B$BНаблюдать за работой настоящего мастера иллюзий – истинное удовольствие. Ты можешь видеть, как враг уничтожает себя сам, все больше и больше погружаясь в безумие.$B$BЕсли хочешь узнать о мастерах иллюзий побольше, ступай в Зул\'Гуруб и принеси мне Знаки Силы. Взамен я отдам тебе напульсники, которые использовали наши мастера иллюзий, творя свои заклинания.','Принесите Ал\'табиму Всевидящему изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.','Впечатляюще... Вы чувствовали, как сквозь них течет моджо? Знаки силы использовались как своего рода валюта, когда Империя Гурубаши правила этими землями. Теперь мы, Зандалар, будем использовать скрытый моджо внутри них, чтобы сражаться со вторым восстанием Кровавого Бога Хаккара!$B$BСегодня ты хорошо $Gпоработал:поработала; - считай, что ты друг Зандалар. Вот и обещанные мною напульсники иллюзиониста!','О, $N ты уже $Gвернулся:вернулась? Тебе удалось достать Знаки Силы?','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: напульсники мастера иллюзий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Маги нашего племени – это творцы иллюзий. В свои чары они вплетают заклинания, одурманивающие врагов и сбивающие их с толку.$B$B*Альтабим злорадно хихикает.*$B$BНаблюдать за работой настоящего мастера иллюзий – истинное удовольствие. Ты можешь видеть, как враг уничтожает себя сам, все больше и больше погружаясь в безумие.$B$BЕсли хочешь узнать о мастерах иллюзий побольше, ступай в Зул\'Гуруб и принеси мне Знаки Силы. Взамен я отдам тебе напульсники, которые использовали наши мастера иллюзий, творя свои заклинания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ал\'табиму Всевидящему изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляюще... Вы чувствовали, как сквозь них течет моджо? Знаки силы использовались как своего рода валюта, когда Империя Гурубаши правила этими землями. Теперь мы, Зандалар, будем использовать скрытый моджо внутри них, чтобы сражаться со вторым восстанием Кровавого Бога Хаккара!$B$BСегодня ты хорошо $Gпоработал:поработала; - считай, что ты друг Зандалар. Вот и обещанные мною напульсники иллюзиониста!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, $N ты уже $Gвернулся:вернулась? Тебе удалось достать Знаки Силы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8061,'Знаки Силы: напульсники исповедника','В Зандаларе принято одаривать силой тех, кто общается с богами и власть имущими. Наши жрецы не просто целители – они исповедники нашего племени. Зло приходит как снаружи – из Зул\'Гуруба, так и изнутри. Наши исповедники – наши судьи, которые оберегают нас от того зла, что поглотило Гурубаши.$B$BСтупай в Зул\'Гуруб и принеси Знаки Силы. Узнай, что значит быть исповедником, и охрани нас от зла.','Принесите Ал\'табиму Всевидящему изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.','Отлично, $N! Это было немалым подвигом - принести это мне. Несомненно, ты выступил сегодня как исповедник нашего племени, защитив нам от угрозы Хаккара. Эти напульсники подходят такому другу племени!','Ты $Gвернулся:вернулась из Зул\'Гуруба? Удалось ли тебе получить Знаки силы у приспешников Хаккара?','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: напульсники исповедника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Зандаларе принято одаривать силой тех, кто общается с богами и власть имущими. Наши жрецы не просто целители – они исповедники нашего племени. Зло приходит как снаружи – из Зул\'Гуруба, так и изнутри. Наши исповедники – наши судьи, которые оберегают нас от того зла, что поглотило Гурубаши.$B$BСтупай в Зул\'Гуруб и принеси Знаки Силы. Узнай, что значит быть исповедником, и охрани нас от зла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ал\'табиму Всевидящему изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! Это было немалым подвигом - принести это мне. Несомненно, ты выступил сегодня как исповедник нашего племени, защитив нам от угрозы Хаккара. Эти напульсники подходят такому другу племени!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась из Зул\'Гуруба? Удалось ли тебе получить Знаки силы у приспешников Хаккара?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8062,'Знаки Силы: наручи хищника','В темные времена, наставшие после падения империи Гурубаши, зандаларские хищники использовали все свое мастерство, чтобы наше племя сумело выжить. И теперь они воплощают в себе самую сущность охоты. Отправляйся в Зул\'Гуруб и докажи, что ты $gдостоин:достойна; занять место среди хищников Зандалара. Принеси мне Знаки Силы из Зул\'Гуруба. Тогда ты сможешь еще на один шаг приблизиться к тому, чтобы стать $gодним:одной; из немногих хищников нашего племени.','Принесите Фальтиру Слепому из Зул\'Гуруба изначальные наручники Хаккари. Кроме того, вам необходимо заслужить как минимум дружественное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.','Да... Мне не нужно зрение, чтобы почувствовать присутствие Знаков Силы. Ваш успех в Зул\'Гурубе впечатлил многих в племени. Мы не только считаем вас другом Зандалара, но и считаем вас достаточно достойными, чтобы обладать наручниками хищника - могущественными предметами и символом того, что значит быть хищником. $GМолодец:Умница;, $N.','Ступай в Зул\'Гуруб и охоться на тех, кто владеет Знаками Силы, $N. Пусть они будут твоей добычей.','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: наручи хищника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В темные времена, наставшие после падения империи Гурубаши, зандаларские хищники использовали все свое мастерство, чтобы наше племя сумело выжить. И теперь они воплощают в себе самую сущность охоты. Отправляйся в Зул\'Гуруб и докажи, что ты $gдостоин:достойна; занять место среди хищников Зандалара. Принеси мне Знаки Силы из Зул\'Гуруба. Тогда ты сможешь еще на один шаг приблизиться к тому, чтобы стать $gодним:одной; из немногих хищников нашего племени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Фальтиру Слепому из Зул\'Гуруба изначальные наручники Хаккари. Кроме того, вам необходимо заслужить как минимум дружественное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... Мне не нужно зрение, чтобы почувствовать присутствие Знаков Силы. Ваш успех в Зул\'Гурубе впечатлил многих в племени. Мы не только считаем вас другом Зандалара, но и считаем вас достаточно достойными, чтобы обладать наручниками хищника - могущественными предметами и символом того, что значит быть хищником. $GМолодец:Умница;, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ступай в Зул\'Гуруб и охоться на тех, кто владеет Знаками Силы, $N. Пусть они будут твоей добычей.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8063,'Знаки Силы: наручи безумца','Безумцы Зандалара чем-то сродни разбойникам, но самое главное – они несут с собой Хаос и разрушение. В те жестокие времена, когда наши племена были раздроблены, боевое безумие помогло нам выстоять против врага. Если бы не оно, мы бы не уцелели.$B$BПринеси мне Знаки Силы из Зул\'Гуруба, и одна из деталей брони безумцев станет твоей. Впусти боевое безумие в свою душу!','Принесите Фальтиру Слепому изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.','$GМолодец:Умница;, $N... благодаря своим достижениям в Зул\'Гуруб ты $Gполучил:получила; право называть племя Зандалар своим другом. За твои старания прими эту награду!','Отыщи безумие в Зул\'Гурубе и затми его своим собственным, $N! Это означает успех, а успех - награду! Пусть Бог Крови снова не правит безраздельно!','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: наручи безумца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Безумцы Зандалара чем-то сродни разбойникам, но самое главное – они несут с собой Хаос и разрушение. В те жестокие времена, когда наши племена были раздроблены, боевое безумие помогло нам выстоять против врага. Если бы не оно, мы бы не уцелели.$B$BПринеси мне Знаки Силы из Зул\'Гуруба, и одна из деталей брони безумцев станет твоей. Впусти боевое безумие в свою душу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Фальтиру Слепому изначальные обручья Хаккари. Кроме того, вам необходимо заслужить как минимум дружелюбное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N... благодаря своим достижениям в Зул\'Гуруб ты $Gполучил:получила; право называть племя Зандалар своим другом. За твои старания прими эту награду!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Отыщи безумие в Зул\'Гурубе и затми его своим собственным, $N! Это означает успех, а успех - награду! Пусть Бог Крови снова не правит безраздельно!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8064,'Знаки Силы: пояс гаруспика','Мы в Зандаларе не следуем путями друидов: мы не подстраиваемся под природу, но меняем ее согласно нашим желаниям. Тем не менее и среди нас есть те, кто близок к природе. Наши гаруспики всегда умели слушать и понимать ее. Чтобы понять дух животного, надо знать, что значит быть одним из них. В этом и заключается истинная сила природы.$B$BПринеси мне Знаки Силы из Зул\'Гуруба, докажи племени, что тебе можно доверять. Если ты сделаешь это, я отдам тебе могущественный пояс – из тех, что некогда принадлежали гаруспикам Зандалара.$B$BВ нем сокрыто могучее колдовство!','Принесите Мейвики Зулдазарской изначальный кушак Хаккари. Мейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.','Благодарю тебя - скрытая сила этих предметов будет сокровищем сама по себе. Ты не только $Gсделал:сделала; то, что я просил, но и $Gдоказал:доказала;, что $Gоказал:оказала; нам честь здесь, в племени. Как и обещал, вот ваша награда!','$Gполучил:получила нужные мне Знаки силы из Зул\'Гуруба? Пояс гаруспика будет твоим, если он у тебя есть.','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: пояс гаруспика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы в Зандаларе не следуем путями друидов: мы не подстраиваемся под природу, но меняем ее согласно нашим желаниям. Тем не менее и среди нас есть те, кто близок к природе. Наши гаруспики всегда умели слушать и понимать ее. Чтобы понять дух животного, надо знать, что значит быть одним из них. В этом и заключается истинная сила природы.$B$BПринеси мне Знаки Силы из Зул\'Гуруба, докажи племени, что тебе можно доверять. Если ты сделаешь это, я отдам тебе могущественный пояс – из тех, что некогда принадлежали гаруспикам Зандалара.$B$BВ нем сокрыто могучее колдовство!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мейвики Зулдазарской изначальный кушак Хаккари. Мейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя - скрытая сила этих предметов будет сокровищем сама по себе. Ты не только $Gсделал:сделала; то, что я просил, но и $Gдоказал:доказала;, что $Gоказал:оказала; нам честь здесь, в племени. Как и обещал, вот ваша награда!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$Gполучил:получила нужные мне Знаки силы из Зул\'Гуруба? Пояс гаруспика будет твоим, если он у тебя есть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8065,'Знаки Силы: мундир гаруспика','Одежда гаруспиков, $n, – это символ их могущества. Например, мундир – это символ связи между гаруспиком и постигаемой им божественной мудростью. В мундир зашивают части тел животных, принесенных в жертву. Это напоминает гаруспику о связи с его дарами.$B$BДокажи племени, чего ты стоишь, и принеси Знаки Силы из Зул\'Гуруба. Сделай это, и мундир гаруспиков, хранящий их силу, станет твоим.','Принесите Мейвики Зулдазарской Изначальную гербовую накидку Хаккари. Мейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.','Впечатляет... ты успешно $Gсобрал:собрала; необходимые Знаки Силы, $N. В Зул\'Гурубе ходят легенды о твоих достижениях. Отныне ты будешь $Gпочитаем:почитаемой; в племени. Вот твой мундир, могучий $C!','$Gполучил:получила необходимые Знаки силы из Зул\'Гуруба? Туника гаруспика стоит любых усилий, которые тебе придется приложить.','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: мундир гаруспика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одежда гаруспиков, $n, – это символ их могущества. Например, мундир – это символ связи между гаруспиком и постигаемой им божественной мудростью. В мундир зашивают части тел животных, принесенных в жертву. Это напоминает гаруспику о связи с его дарами.$B$BДокажи племени, чего ты стоишь, и принеси Знаки Силы из Зул\'Гуруба. Сделай это, и мундир гаруспиков, хранящий их силу, станет твоим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мейвики Зулдазарской Изначальную гербовую накидку Хаккари. Мейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляет... ты успешно $Gсобрал:собрала; необходимые Знаки Силы, $N. В Зул\'Гурубе ходят легенды о твоих достижениях. Отныне ты будешь $Gпочитаем:почитаемой; в племени. Вот твой мундир, могучий $C!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$Gполучил:получила необходимые Знаки силы из Зул\'Гуруба? Туника гаруспика стоит любых усилий, которые тебе придется приложить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8066,'Знаки Силы: пояс хищника','Любой хищник знает, как подкрадываться к добыче, но самый ловкий умеет выбирать лучший момент для удара. Ты $gдолжен:должна; уметь и подкрадываться, и нападать, чтобы вернуться с добычей из Зул\'Гуруба.$B$BПринеси мне Знаки Силы. Я обрету могущество, заключенное в них, а ты получишь пояс зандаларского хищника – вещь, ради которой стоит потрудиться.','Принесите Фальтиру Слепому из Зул\'Гуруба изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.','Я почувствовал твое прибытие за несколько минут до этого, $N. Мне открылись Образцы Силы, которые ты $Gпринес:принесла;. Я чувствую силу: их скрытый моджо - грубая магия,которая будет подпитывать наши силы к победе над дьявольскими замыслами Кровавого бога Хаккара.$B$BТы заслуживаешь похвалы и награды за твой успех. Тебя почитают в племени и ты $Gдостоин:достойна; носить пояс хищника.','Ударьте безумных миньонов Хаккара в Зул\'Гурубе - это те, в чьих руках находятся Знаки силы, $N. Докажите им - и всему племени - свой успех в качестве претендента на хищник.','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: пояс хищника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Любой хищник знает, как подкрадываться к добыче, но самый ловкий умеет выбирать лучший момент для удара. Ты $gдолжен:должна; уметь и подкрадываться, и нападать, чтобы вернуться с добычей из Зул\'Гуруба.$B$BПринеси мне Знаки Силы. Я обрету могущество, заключенное в них, а ты получишь пояс зандаларского хищника – вещь, ради которой стоит потрудиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Фальтиру Слепому из Зул\'Гуруба изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я почувствовал твое прибытие за несколько минут до этого, $N. Мне открылись Образцы Силы, которые ты $Gпринес:принесла;. Я чувствую силу: их скрытый моджо - грубая магия,которая будет подпитывать наши силы к победе над дьявольскими замыслами Кровавого бога Хаккара.$B$BТы заслуживаешь похвалы и награды за твой успех. Тебя почитают в племени и ты $Gдостоин:достойна; носить пояс хищника.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ударьте безумных миньонов Хаккара в Зул\'Гурубе - это те, в чьих руках находятся Знаки силы, $N. Докажите им - и всему племени - свой успех в качестве претендента на хищник.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8067,'Знаки Силы: оплечье хищника','В Зандаларе одежда рассказывает о подвигах того, кто ее носит. При этом символы наших свершений не обязательно должны быть видимы глазом – излучаемая ими сила говорит сама за себя. Одежда хищников Зандалара обладает именно такими свойствами; более же всего они ценят свои оплечья. Они скрывают своего владельца от чужих взглядов, когда он желает остаться невидимым.$B$BВ Зул\'Гурубе тебя ждут Знаки Силы. Принеси их мне, и это оплечье станет твоим.','Принесите Фальтиру Слепому из Зул\'Гуруба изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.','Успех... Ты $Gпочитаем:почитаема; в племени, $N. Обрести Знаки Силы, необходимые для мантии, было непросто, но ты $Gсправился:справилась; с этим. Ты $Gзаслужил:заслужила; свое место среди нас и, безусловно, $Gзаслужил:заслужила; право носить эту мантию.','Ваши удары по Зул\'Гурубу увенчались успехом, $N? Только когда ты принесешь мне то, что я ищу - и полностью проявишь себя в племени, - ты заработаешь непревзойденную мантию среди Зандаларов.','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: оплечье хищника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Зандаларе одежда рассказывает о подвигах того, кто ее носит. При этом символы наших свершений не обязательно должны быть видимы глазом – излучаемая ими сила говорит сама за себя. Одежда хищников Зандалара обладает именно такими свойствами; более же всего они ценят свои оплечья. Они скрывают своего владельца от чужих взглядов, когда он желает остаться невидимым.$B$BВ Зул\'Гурубе тебя ждут Знаки Силы. Принеси их мне, и это оплечье станет твоим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Фальтиру Слепому из Зул\'Гуруба изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Успех... Ты $Gпочитаем:почитаема; в племени, $N. Обрести Знаки Силы, необходимые для мантии, было непросто, но ты $Gсправился:справилась; с этим. Ты $Gзаслужил:заслужила; свое место среди нас и, безусловно, $Gзаслужил:заслужила; право носить эту мантию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ваши удары по Зул\'Гурубу увенчались успехом, $N? Только когда ты принесешь мне то, что я ищу - и полностью проявишь себя в племени, - ты заработаешь непревзойденную мантию среди Зандаларов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8068,'Знаки Силы: оплечье мастера иллюзий','Магия – это бесформенная изначальная сила. Могучие маги управляют ее энергией в своих целях. Мы прибегаем к ней в своих заклятиях, но, чтобы создавать иллюзии, нужно особое могущество. Как можно победить врага, который существует только в твоем воображении? В Зандаларе знают цену подобной магии, и мастера иллюзий пользуются большим уважением в племени.$B$BПринеси из Зул\'Гуруба Знаки Силы, и ты заслужишь уважение племени, а также оплечье мастера иллюзий.','Принесите Ал\'табиму Всевидящему изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BАльтабим Всевидящий живет на острове Йоджамба, в Тернистой долине.','Успех! С этого момента ты будешь иметь почтение в племени! Зул\'Гуруб определенно испытал на себе мощь Зандалара сегодня, благодаря тебе, $N.$B$BС благословения племени прими мантию зандаларского иллюзиониста. Пусть она тебе хорошо послужит.','Как прошел твой набег на Зул\'Гуруб? Ты $Gдовел:довела врагов до безумия, используя мастерство иллюзий? Впрочем, от чего бы они ни умерли, добытые Знаки Силы помогут нам предотвратить воцарение Хаккара.','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: оплечье мастера иллюзий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Магия – это бесформенная изначальная сила. Могучие маги управляют ее энергией в своих целях. Мы прибегаем к ней в своих заклятиях, но, чтобы создавать иллюзии, нужно особое могущество. Как можно победить врага, который существует только в твоем воображении? В Зандаларе знают цену подобной магии, и мастера иллюзий пользуются большим уважением в племени.$B$BПринеси из Зул\'Гуруба Знаки Силы, и ты заслужишь уважение племени, а также оплечье мастера иллюзий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ал\'табиму Всевидящему изначальную лацерну Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BАльтабим Всевидящий живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Успех! С этого момента ты будешь иметь почтение в племени! Зул\'Гуруб определенно испытал на себе мощь Зандалара сегодня, благодаря тебе, $N.$B$BС благословения племени прими мантию зандаларского иллюзиониста. Пусть она тебе хорошо послужит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как прошел твой набег на Зул\'Гуруб? Ты $Gдовел:довела врагов до безумия, используя мастерство иллюзий? Впрочем, от чего бы они ни умерли, добытые Знаки Силы помогут нам предотвратить воцарение Хаккара.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8069,'Знаки Силы: одеяние мастера иллюзий','В нашем племени одежда – это символ могущества и власти. Она сшита из лучших материалов и усилена заклинаниями, которые дают нам мощь. Одежды мастеров иллюзий отражают самую сущность творимых ими заклятий. Легенды гласят, что одежды мастера иллюзий постоянно меняет свой вид.$B$BЯ могу дать тебе такое одежды, $n... но сначала покажи племени, на что ты $gспособен:способна;. Принеси мне из Зул\'Гуруба Знаки Силы!','Принесите Ал\'табиму Всевидящему изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.','Наконец-то кто-то достойный надет мантию иллюзиониста! Твой успех в Зул\'Гурубе обеспечил тебе уважение среди племени на долгие годы. Носите её с гордостью, $N!','Удалось ли тебе достать Знаки Силы? Я знаю, это сделать непросто... Но у меня было видение, что именно чужеземец возглавит нас и поведет на борьбу с Хаккаром. Может быть, это именно ты?','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: одеяние мастера иллюзий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В нашем племени одежда – это символ могущества и власти. Она сшита из лучших материалов и усилена заклинаниями, которые дают нам мощь. Одежды мастеров иллюзий отражают самую сущность творимых ими заклятий. Легенды гласят, что одежды мастера иллюзий постоянно меняет свой вид.$B$BЯ могу дать тебе такое одежды, $n... но сначала покажи племени, на что ты $gспособен:способна;. Принеси мне из Зул\'Гуруба Знаки Силы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ал\'табиму Всевидящему изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то кто-то достойный надет мантию иллюзиониста! Твой успех в Зул\'Гурубе обеспечил тебе уважение среди племени на долгие годы. Носите её с гордостью, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе достать Знаки Силы? Я знаю, это сделать непросто... Но у меня было видение, что именно чужеземец возглавит нас и поведет на борьбу с Хаккаром. Может быть, это именно ты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8070,'Знаки Силы: пояс исповедника','После падения имеперии Гурубаши ужасное зло, разъедавшее племя изнутри, охватило и Зандалар. Нас спасли исповедники, которые защищали нас от нас же самих, не давая истреблять себе подобных. До сих пор исповедники охраняют наш дух и стоят на страже наших жизней.$B$BСтупай в Зул\'Гуруб и узри глубину падения Хаккара и Гурубаши. Вырви из их грязных лап Знаки Силы. В случае успеха тебя ожидает награда.','Принесите Ал\'табиму Всевидящему изначальный кушак Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.','Успех! Это будет иметь большое значение для наращивания нашей силы против Хаккара. С твоей помощью мы сделали важный шаг в обеспечении того, чтобы Бог крови не уничтожил всех нас.$B$BСегодня ты $Gзаслужил:заслужила; уважение своего племени, $N. Прими это - наручники духовника - в знак нашей благодарности.','Образцы могущества... они у вас есть? Только когда они у нас появятся, мы сможем использовать скрытую энергию, хранящуюся в них. Было бы хорошо перевернуть столы на приспешников Кровавого Бога...','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: пояс исповедника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После падения имеперии Гурубаши ужасное зло, разъедавшее племя изнутри, охватило и Зандалар. Нас спасли исповедники, которые защищали нас от нас же самих, не давая истреблять себе подобных. До сих пор исповедники охраняют наш дух и стоят на страже наших жизней.$B$BСтупай в Зул\'Гуруб и узри глубину падения Хаккара и Гурубаши. Вырви из их грязных лап Знаки Силы. В случае успеха тебя ожидает награда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ал\'табиму Всевидящему изначальный кушак Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Успех! Это будет иметь большое значение для наращивания нашей силы против Хаккара. С твоей помощью мы сделали важный шаг в обеспечении того, чтобы Бог крови не уничтожил всех нас.$B$BСегодня ты $Gзаслужил:заслужила; уважение своего племени, $N. Прими это - наручники духовника - в знак нашей благодарности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Образцы могущества... они у вас есть? Только когда они у нас появятся, мы сможем использовать скрытую энергию, хранящуюся в них. Было бы хорошо перевернуть столы на приспешников Кровавого Бога...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8071,'Знаки Силы: оплечье исповедника','Исповедники Зандалара носят особые оплечья, по которым каждый из нас узнает пастырей племени. Эти оплечья усилены могучими заклятиями, которые помогают почувствовать угрозу, исходящую от врагов племени. Тебе, как $Gжрецу:жрице;, они очень бы пригодились.$B$BЕсли ты отправишься в Зул\'Гуруб, сразишься с приспешниками Хаккара и принесешь мне нужные Знаки Силы, я отдам тебе оплечье, достойное лучших исповедников.','Принесите Ал\'табиму Всевидящему изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.','$GМолодец:Умница;, $N - Хаккара наверняка ощутили возмездие Зандалара сегодня благодаря тебе. Твои деяния принесли тебе постоянное почитание в племени. С нашего благословения прими, пожалуйста, эту исповедническую мантию как свою!','У тебя есть Знаки силы из Зул\'Гуруба?','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: оплечье исповедника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Исповедники Зандалара носят особые оплечья, по которым каждый из нас узнает пастырей племени. Эти оплечья усилены могучими заклятиями, которые помогают почувствовать угрозу, исходящую от врагов племени. Тебе, как $Gжрецу:жрице;, они очень бы пригодились.$B$BЕсли ты отправишься в Зул\'Гуруб, сразишься с приспешниками Хаккара и принесешь мне нужные Знаки Силы, я отдам тебе оплечье, достойное лучших исповедников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ал\'табиму Всевидящему изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N - Хаккара наверняка ощутили возмездие Зандалара сегодня благодаря тебе. Твои деяния принесли тебе постоянное почитание в племени. С нашего благословения прими, пожалуйста, эту исповедническую мантию как свою!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть Знаки силы из Зул\'Гуруба?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8072,'Знаки Силы: оплечье безумца','Одним из легендарных безумцев Зандалара был Карвахал Безумный. Легенды гласят, что в боях с врагами племени он применял заклинание "волна безумия", наложенное на его оплечья. Врагов поражал ужас, и они видели только мелькание его двойных кинжалов. До сих пор оплечья безумцев – предмет их особой гордости.$B$BПринеси мне Знаки Силы из Зул-Гуруба, и они достанутся тебе, чтобы вселять безумие и трепет в твоих врагов.','Принесите Фальтиру Слепому изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.','Сегодня победа за нами, благодаря тому безумию, которое ты $Gпосеял:посеяла; на наших общих врагов! Тебя должны почитать Зандалары, и нет лучшего способа выразить свою благодарность за твои дела, чем предложить тебе мантию сумасшедшего!','О, ты $Gвернулся:вернулась – с тобой ли Знаки Силы? Легенды о Карвахале Безумном говорят нам, что, как бы ни был силен враг, его можно одолеть. Хаос способен поставить на колени любого, и это одна из немногих закономерностей, присущих ему.','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: оплечье безумца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одним из легендарных безумцев Зандалара был Карвахал Безумный. Легенды гласят, что в боях с врагами племени он применял заклинание "волна безумия", наложенное на его оплечья. Врагов поражал ужас, и они видели только мелькание его двойных кинжалов. До сих пор оплечья безумцев – предмет их особой гордости.$B$BПринеси мне Знаки Силы из Зул-Гуруба, и они достанутся тебе, чтобы вселять безумие и трепет в твоих врагов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Фальтиру Слепому изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодня победа за нами, благодаря тому безумию, которое ты $Gпосеял:посеяла; на наших общих врагов! Тебя должны почитать Зандалары, и нет лучшего способа выразить свою благодарность за твои дела, чем предложить тебе мантию сумасшедшего!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, ты $Gвернулся:вернулась – с тобой ли Знаки Силы? Легенды о Карвахале Безумном говорят нам, что, как бы ни был силен враг, его можно одолеть. Хаос способен поставить на колени любого, и это одна из немногих закономерностей, присущих ему.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8073,'Знаки Силы: мундир безумца','Мои глаза уже давно ничего не видят, но я от этого не страдаю. В нашем племени одежда – символ твоего статуса и могущества, поэтому самые могущественные предметы излучают невидимую глазами силу. Этот мундир зандаларского безумца – не исключение, он пронизан изначальной магией хаоса и безумия, присущих его владельцу.$B$BМне нужны Знаки Силы, которые находятся в Зул\'Гурубе. Принеси мне их, и я отдам тебе этот легендарный мундир, который... придется под стать любому сеятелю безумия.','Принесите Фальтиру Слепому из Зул-Гуруба изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.','Впечатляет... сегодня ты $Gсделал:сделала; то, что немногие считали возможным. Твое благоговение перед племенем гарантировано на всю жизнь, $N. Ты $Gзаслужил:заслужила; право надеть мундир зандаларского безумца - делайте это с нашего благословения.','С возвращением на остров, $N... ты победно $Gвернулся:вернулась с Знаками силы на буксире?','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: мундир безумца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои глаза уже давно ничего не видят, но я от этого не страдаю. В нашем племени одежда – символ твоего статуса и могущества, поэтому самые могущественные предметы излучают невидимую глазами силу. Этот мундир зандаларского безумца – не исключение, он пронизан изначальной магией хаоса и безумия, присущих его владельцу.$B$BМне нужны Знаки Силы, которые находятся в Зул\'Гурубе. Принеси мне их, и я отдам тебе этот легендарный мундир, который... придется под стать любому сеятелю безумия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Фальтиру Слепому из Зул-Гуруба изначальную эгиду Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BФальтир Слепой живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляет... сегодня ты $Gсделал:сделала; то, что немногие считали возможным. Твое благоговение перед племенем гарантировано на всю жизнь, $N. Ты $Gзаслужил:заслужила; право надеть мундир зандаларского безумца - делайте это с нашего благословения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С возвращением на остров, $N... ты победно $Gвернулся:вернулась с Знаками силы на буксире?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8074,'Знаки Силы: пояс авгура','Авгуры многое знают о стихиях, дружище, и используют свои знания во славу нашего племени. В темные времена, наступившие после падения империи Гурубаши, именно авгуры привели нас в тихую гавань Южных морей. Они же вернули нас обратно в Долину, в самое сердце зла, свившее себе гнездо в Зул\'Гурубе.$B$BПринеси Знаки Силы из Зул\'Гуруба и докажи племени, чего ты стоишь. Взамен я дам тебе пояс, который служил нашим авгурам. Это не простой пояс, на нем лежит могучее заклинание.','Принесите Мейвики Зулдазарской изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BМейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.','Я чувствую запах побежденного зла в тебе, $N. Это сладкий запах, $Gдружище:подруга;... думаю, ты хорошо знаешь его.$B$BЯ знаю, что принести мне Знаки Силы, необходимые для пояса, - непростое дело. Твои дела не только прославили племя, но и себя среди моего племени. Вот и я - возьми пояс авгура и надень его как свой собственный!','Знаки силы - это то, что мне нужно, мы извлечем силу прямо из них в нашей борьбе со злом из Зул\'Гуруба. У тебя есть они для меня?','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: пояс авгура',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Авгуры многое знают о стихиях, дружище, и используют свои знания во славу нашего племени. В темные времена, наступившие после падения империи Гурубаши, именно авгуры привели нас в тихую гавань Южных морей. Они же вернули нас обратно в Долину, в самое сердце зла, свившее себе гнездо в Зул\'Гурубе.$B$BПринеси Знаки Силы из Зул\'Гуруба и докажи племени, чего ты стоишь. Взамен я дам тебе пояс, который служил нашим авгурам. Это не простой пояс, на нем лежит могучее заклинание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мейвики Зулдазарской изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BМейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я чувствую запах побежденного зла в тебе, $N. Это сладкий запах, $Gдружище:подруга;... думаю, ты хорошо знаешь его.$B$BЯ знаю, что принести мне Знаки Силы, необходимые для пояса, - непростое дело. Твои дела не только прославили племя, но и себя среди моего племени. Вот и я - возьми пояс авгура и надень его как свой собственный!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаки силы - это то, что мне нужно, мы извлечем силу прямо из них в нашей борьбе со злом из Зул\'Гуруба. У тебя есть они для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8075,'Знаки Силы: хауберк авгура','Все авгуры Зандалара носят хауберки. Они сшиты из лучшего шелка и укреплены прочными кольчужными звеньями. Хауберк – не только символ причастности авгуров к божественному, но и знак их власти. Никто не смеет переходить дорогу тем, кто общается с духами.$B$BДокажи свою преданность племени и принеси мне Знаки Силы из Зул\'Гуруба. Если тебе удастся сделать это, я отдам тебе лучший из хауберков, который когда-либо носили наши авгуры!','Принесите Мейвики Зулдазарской изначальную гербовую накидку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BМейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.','Я знаю, через что тебе пришлось пройти, чтобы принести мне Знаки силы, $N. Это было нелегко, $Gдружище:подруга; - победить зло, которое истекает из Зул\'Гуруба, как грязная жижа - но теперь, когда все сказано и сделано, я могу легко сказать, что ты будешь почитаем среди Зандаларов на долгие годы!$B$BВот - возьмите кольчугу авгура и с гордостью носи ее!','Знаки силы - ключевой источник магической силы - той же силы, которая используется для создания кольчужной одежды авгура. Принеси мне то, что мне нужно, и я смогу поделиться лучшими облачениями, которые любой зандаларский авгур пожелает.','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: хауберк авгура',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все авгуры Зандалара носят хауберки. Они сшиты из лучшего шелка и укреплены прочными кольчужными звеньями. Хауберк – не только символ причастности авгуров к божественному, но и знак их власти. Никто не смеет переходить дорогу тем, кто общается с духами.$B$BДокажи свою преданность племени и принеси мне Знаки Силы из Зул\'Гуруба. Если тебе удастся сделать это, я отдам тебе лучший из хауберков, который когда-либо носили наши авгуры!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мейвики Зулдазарской изначальную гербовую накидку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BМейвики Зулдазарская находится на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю, через что тебе пришлось пройти, чтобы принести мне Знаки силы, $N. Это было нелегко, $Gдружище:подруга; - победить зло, которое истекает из Зул\'Гуруба, как грязная жижа - но теперь, когда все сказано и сделано, я могу легко сказать, что ты будешь почитаем среди Зандаларов на долгие годы!$B$BВот - возьмите кольчугу авгура и с гордостью носи ее!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаки силы - ключевой источник магической силы - той же силы, которая используется для создания кольчужной одежды авгура. Принеси мне то, что мне нужно, и я смогу поделиться лучшими облачениями, которые любой зандаларский авгур пожелает.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8076,'Знаки Силы: оплечье бесноватого','Бесноватые стремятся полностью слиться с силой, а не просто использовать ее. Многие из бесноватых проиграли бой со своим демоном. Но когда враги наступали со всех сторон – особенно в Зул\'Гурубе, – победа стоила всех принесенных жертв. От того, сумеем ли мы сокрушить наших врагов, зависит наше существование, – этому нас научило падение империи Гурубаши.$B$BСтупай в Зул\'Гуруб и добудь необходимые нам Знаки Силы. Наградой тебе будет оплечье бесноватого.','Принесите Ал\'табиму Всевидящему изначальный кушак Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.','$GМолодец:Умница;, $N. Знаки Силы из Зул\'Гуруба служат нам напоминанием о могуществе, которое было растрачено впустую. Империя Гурубаши была сильна, но пожрала сама себя изнутри. Игра, в которую играют бесноватые, очень похожа на то, что случилось с империей... Но добытая ими сила необходима для выживания племени.$B$BПрими это оплечье, наш славный союзник... оно сослужит тебе добрую службу.','Удалось добыть Знаки Силы в Зул\'Гурубе? Чтобы победить Хаккара, нам нужна колдовская мощь, заключенная в них. Помоги нам, и ты не останешься без награды.','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: оплечье бесноватого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бесноватые стремятся полностью слиться с силой, а не просто использовать ее. Многие из бесноватых проиграли бой со своим демоном. Но когда враги наступали со всех сторон – особенно в Зул\'Гурубе, – победа стоила всех принесенных жертв. От того, сумеем ли мы сокрушить наших врагов, зависит наше существование, – этому нас научило падение империи Гурубаши.$B$BСтупай в Зул\'Гуруб и добудь необходимые нам Знаки Силы. Наградой тебе будет оплечье бесноватого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ал\'табиму Всевидящему изначальный кушак Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N. Знаки Силы из Зул\'Гуруба служат нам напоминанием о могуществе, которое было растрачено впустую. Империя Гурубаши была сильна, но пожрала сама себя изнутри. Игра, в которую играют бесноватые, очень похожа на то, что случилось с империей... Но добытая ими сила необходима для выживания племени.$B$BПрими это оплечье, наш славный союзник... оно сослужит тебе добрую службу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось добыть Знаки Силы в Зул\'Гурубе? Чтобы победить Хаккара, нам нужна колдовская мощь, заключенная в них. Помоги нам, и ты не останешься без награды.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8077,'Знаки Силы: одеяние бесноватого','Одеяния, в которые мы облачаемся перед битвой, говорят о нашей силе. Одеяние бесноватого создано из рунической ткани, на которую наложено могучее заклятие. Один его вид вселяет страх в сердца врагов... Особенно его боятся демоны, зная, что рано или поздно бесноватый их одолеет и подчинит своей воле.$B$BПринеси мне Знаки Силы из Зул\'Гуруба. Это непросто сделать... но в случае успеха одеяние бесноватого станет твоим.','Принесите Ал\'табиму Всевидящему изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.','Впечатляет - ваша победа в Зул\'Гуруб заверила нас, что Хаккар не победит. Может наступить время, когда вы встретитесь лицом к лицу с Богом Крови напрямую... и если это произойдет, знайте, что ваше почтение гарантировано племенем Зандалар.$B$BО, и это одеяние, я думаю,должно в этом помочь.$B$B<Альтабим понимающе подмигивает вам.>','Знаки силы... ты $Gвернулся:вернулась; с ними? Только когда они у нас появятся, мы поделимся с тобой высшим символом демонической силы, $N.','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: одеяние бесноватого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одеяния, в которые мы облачаемся перед битвой, говорят о нашей силе. Одеяние бесноватого создано из рунической ткани, на которую наложено могучее заклятие. Один его вид вселяет страх в сердца врагов... Особенно его боятся демоны, зная, что рано или поздно бесноватый их одолеет и подчинит своей воле.$B$BПринеси мне Знаки Силы из Зул\'Гуруба. Это непросто сделать... но в случае успеха одеяние бесноватого станет твоим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Ал\'табиму Всевидящему изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BАл\'табим Всевидящий живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Впечатляет - ваша победа в Зул\'Гуруб заверила нас, что Хаккар не победит. Может наступить время, когда вы встретитесь лицом к лицу с Богом Крови напрямую... и если это произойдет, знайте, что ваше почтение гарантировано племенем Зандалар.$B$BО, и это одеяние, я думаю,должно в этом помочь.$B$B<Альтабим понимающе подмигивает вам.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаки силы... ты $Gвернулся:вернулась; с ними? Только когда они у нас появятся, мы поделимся с тобой высшим символом демонической силы, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8078,'Знаки Силы: пояс воздаятеля','Зул\'Гуруб жаждет мести, но Хаккар не должен воцариться! Он подточил империю Гурубаши и разрушил ее, и этому преступлению не может быть оправдания. Из-за Хаккара тролли теперь – лишь тень былой славы.$B$BСтань нашим блюстителем, уничтожь служителей зла. Зул\'Гуруб должен отведать мести Зандалара. Как доказательство совершенной мести, принеси мне Знаки Силы. Взамен ты получишь пояс воздаятеля. С ним ты обретешь настоящую мощь.$B$BСтупай.','Принесите Джин\'року Разрушителю изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.','Теперь ты знаешь путь, которым надлежит следовать блюстителю. Твои деяния принесли племени славу, а нашим врагам – смерть.$B$BПрими этот пояс блюстителя, и вместе с ним – нашу благодарность.','Ты $Gпринес:принесла; Знаки Силы? Ты $Gпобедил:победила; врагов племени? Хаккар должен знать гнев мстителя!','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: пояс воздаятеля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Зул\'Гуруб жаждет мести, но Хаккар не должен воцариться! Он подточил империю Гурубаши и разрушил ее, и этому преступлению не может быть оправдания. Из-за Хаккара тролли теперь – лишь тень былой славы.$B$BСтань нашим блюстителем, уничтожь служителей зла. Зул\'Гуруб должен отведать мести Зандалара. Как доказательство совершенной мести, принеси мне Знаки Силы. Взамен ты получишь пояс воздаятеля. С ним ты обретешь настоящую мощь.$B$BСтупай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Джин\'року Разрушителю изначальный ремень Хаккари. Кроме того, вам необходимо заслужить как минимум уважительное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь ты знаешь путь, которым надлежит следовать блюстителю. Твои деяния принесли племени славу, а нашим врагам – смерть.$B$BПрими этот пояс блюстителя, и вместе с ним – нашу благодарность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; Знаки Силы? Ты $Gпобедил:победила; врагов племени? Хаккар должен знать гнев мстителя!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8079,'Знаки Силы: кираса воздаятеля','Символ мощи воздаятеля – его кираса. Ее выковывают, используя могучие заклятия. Подобный доспех носят только те, кто заслужил почет и уважение племени. Кираса воздаятеля – символ отмщения Зандалара.$B$BСтать блюстителем – значит нести отмщение. Добудь в Зул\'Гурубе Знаки Силы и принеси их нам. Мы должны вернуть заклинания, которые были у нас украдены. Пусть приспешники Хаккара заплатят за свои преступления кровью! Твоей наградой будет кираса воздаятеля.$B$BСтупай. Отомсти за нас.','Принесите Джин\'року Разрушителю изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.','То, что ты $Gсовершил:совершила;, внушает трепет. Племя не забывает своих героев, ведь благодаря тебе Зул\'Гуруб испытал всю силу отмщения Зандалара!$B$BТвои деяния станут примером для остальных, и они будут чтить тебя как само воплощение мести.','Ты $Gвернулся:вернулась; с победой? Знаки Силы с тобой? Расскажи мне о совершенной мести!','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Силы: кираса воздаятеля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Символ мощи воздаятеля – его кираса. Ее выковывают, используя могучие заклятия. Подобный доспех носят только те, кто заслужил почет и уважение племени. Кираса воздаятеля – символ отмщения Зандалара.$B$BСтать блюстителем – значит нести отмщение. Добудь в Зул\'Гурубе Знаки Силы и принеси их нам. Мы должны вернуть заклинания, которые были у нас украдены. Пусть приспешники Хаккара заплатят за свои преступления кровью! Твоей наградой будет кираса воздаятеля.$B$BСтупай. Отомсти за нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Джин\'року Разрушителю изначальную рубашку Хаккари. Кроме того, вам необходимо заслужить как минимум почтительное отношение племени Зандалар.$B$BДжин\'рок Разрушитель живет на острове Йоджамба, в Тернистой долине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что ты $Gсовершил:совершила;, внушает трепет. Племя не забывает своих героев, ведь благодаря тебе Зул\'Гуруб испытал всю силу отмщения Зандалара!$B$BТвои деяния станут примером для остальных, и они будут чтить тебя как само воплощение мести.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась; с победой? Знаки Силы с тобой? Расскажи мне о совершенной мести!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джин\'року Разрушителю на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8080,'Ресурсы Низины Арати','Войну выигрывают солдаты – любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо и все это можно добыть там.$B$BИ вот чего я хочу от вас, $n. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.','Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Макчисту в Опорный пункт.','У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам.$B$BСпасибо, $N. Действительно, успешное выполнение миссий, подобных той, которую ты $Gвыполнил:выполнила;, - вот как действительно выигрывают войны.','У тебя есть ящик с ресурсами, $N? Без них Лига Аратора не сможет вести достойную битву...','Вернитесь к сержанту Макчист на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ресурсы Низины Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войну выигрывают солдаты – любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо и все это можно добыть там.$B$BИ вот чего я хочу от вас, $n. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Макчисту в Опорный пункт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам.$B$BСпасибо, $N. Действительно, успешное выполнение миссий, подобных той, которую ты $Gвыполнил:выполнила;, - вот как действительно выигрывают войны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть ящик с ресурсами, $N? Без них Лига Аратора не сможет вести достойную битву...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Макчист на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8081,'Новые ящики с ресурсами','Очень хорошо. Я немедленно передам их нашим интендантам.$B$BЕще раз спасибо, $N. Твой вклад в нашу борьбу заметят как целитель, так и фельдмаршал.','$N, у Лиги Аратора есть постоянная миссия: вернуться в низину Арати, добыть еще ящики с ресурсами и принести их мне.','Вернитесь к сержанту Макчист на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые ящики с ресурсами',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Я немедленно передам их нашим интендантам.$B$BЕще раз спасибо, $N. Твой вклад в нашу борьбу заметят как целитель, так и фельдмаршал.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, у Лиги Аратора есть постоянная миссия: вернуться в низину Арати, добыть еще ящики с ресурсами и принести их мне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Макчист на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8101,'Камешек Каджаро','Знаешь ли ты, что это, $R? Это – камешек с горы Каджаро в Южных морях. Там, где находится эта гора, постоянно происходят извержения вулканов, сама земля течет и меняется.$B$BСила камня будет расти по мере того, как будет крепнуть твоя связь с троллями Зандалара. Используй его силу, чтобы стереть наших врагов с лица земли. В битве будь подобен вулкану: пусть никто не спасется от смертоносной мощи твоего гнева...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камешек Каджаро',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знаешь ли ты, что это, $R? Это – камешек с горы Каджаро в Южных морях. Там, где находится эта гора, постоянно происходят извержения вулканов, сама земля течет и меняется.$B$BСила камня будет расти по мере того, как будет крепнуть твоя связь с троллями Зандалара. Используй его силу, чтобы стереть наших врагов с лица земли. В битве будь подобен вулкану: пусть никто не спасется от смертоносной мощи твоего гнева...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8102,'Камешек Каджаро','Будь как огненная лава Каджаро, которую ничто не может остановить.','Снова здравствуй, $C. Я вижу, камешек пригодился. Благодаря его сверхъестественной силе тебе удалось одолеть множество врагов, и они умерли в ужасных мучениях. Пришло время увеличить силу камня. Дай его мне.','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камешек Каджаро',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будь как огненная лава Каджаро, которую ничто не может остановить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Снова здравствуй, $C. Я вижу, камешек пригодился. Благодаря его сверхъестественной силе тебе удалось одолеть множество врагов, и они умерли в ужасных мучениях. Пришло время увеличить силу камня. Дай его мне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8103,'Камешек Каджаро','Продолжай истреблять троллей Зул\'Гуруба. Пусть Хаккар знает, что мир не склонится перед его жестокостью.','Хаккари боятся тебя, $N. Они боятся тебя едва ли не больше, чем своего собственного безликого Кровавого бога. Ты $Gуничтожил:уничтожила; множество приспешников Хаккара с помощью силы Каджаро.','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камешек Каджаро',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Продолжай истреблять троллей Зул\'Гуруба. Пусть Хаккар знает, что мир не склонится перед его жестокостью.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хаккари боятся тебя, $N. Они боятся тебя едва ли не больше, чем своего собственного безликого Кровавого бога. Ты $Gуничтожил:уничтожила; множество приспешников Хаккара с помощью силы Каджаро.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8104,'Самоцвет Каджаро','<Альтабим с невидимой мощью разбивает камешек.>$B$BТы видишь? Галька - это то, что мы называем жеодой. Внутри гальки находятся мощные кристаллы, впитавшие скрытую энергию нашего мира. Разрезав камешек пополам, я, наконец, позволил полностью реализовать его потенциал. Используйте его, чтобы опустошить наших врагов.','Дай мне талисман, $N. Я должен тебе кое-что показать.','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самоцвет Каджаро',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Альтабим с невидимой мощью разбивает камешек.>$B$BТы видишь? Галька - это то, что мы называем жеодой. Внутри гальки находятся мощные кристаллы, впитавшие скрытую энергию нашего мира. Разрезав камешек пополам, я, наконец, позволил полностью реализовать его потенциал. Используйте его, чтобы опустошить наших врагов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дай мне талисман, $N. Я должен тебе кое-что показать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8105,'Битва за Низину Арати','$n, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать с целью обеспечить наши силы поставками сырья и различных припасов. Я отдаю тебе приказ атаковать самые удаленные от нашей базы точки. $b$bНапади на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найди вражеский флаг и сорви его с флагштока! $b$bКогда сумеешь сделать это в четырех указанных точках, возвращайся ко мне.','Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.','Я получил отчеты о твоих подвигах в Низине Арати, $N. Отлично сработано! Я верю, что однажды мы вернем себе наши родные земли,такими как героями ,как ты.','Вернитесь к фельдмаршалу Освету на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Низину Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать с целью обеспечить наши силы поставками сырья и различных припасов. Я отдаю тебе приказ атаковать самые удаленные от нашей базы точки. $b$bНапади на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найди вражеский флаг и сорви его с флагштока! $b$bКогда сумеешь сделать это в четырех указанных точках, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я получил отчеты о твоих подвигах в Низине Арати, $N. Отлично сработано! Я верю, что однажды мы вернем себе наши родные земли,такими как героями ,как ты.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фельдмаршалу Освету на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8106,'Ожерелье Кезанского порока','Прими этот талисман, $N. Используй его силу, чтобы уничтожить наших общих врагов.$B$BЗнай, что он – частичка нашей истории. В свое время Кезан был частью огромной Зандаларской империи. К сожалению, гоблины выжили оттуда моих братьев и сестер...$B$BТеперь в Кезане находится столица гоблинов Нижняя шахта, а ведь в давние времена он славился своим величием! До сих пор Кезан считается нашей священной землей') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье Кезанского порока',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прими этот талисман, $N. Используй его силу, чтобы уничтожить наших общих врагов.$B$BЗнай, что он – частичка нашей истории. В свое время Кезан был частью огромной Зандаларской империи. К сожалению, гоблины выжили оттуда моих братьев и сестер...$B$BТеперь в Кезане находится столица гоблинов Нижняя шахта, а ведь в давние времена он славился своим величием! До сих пор Кезан считается нашей священной землей',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8107,'Ожерелье Кезанского порока','Слейся с тьмой, $C. Проникни в мир теней. Позволь Кезанскому пороку напитать темные стороны твоего "я".','В Зандаларе уважение следует заслужить, $N. Тролли предлагают свою дружбу и заключают союзы только с теми, кого они уважают.$B$BДай мне свой талисман, я наполню его силой.','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье Кезанского порока',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слейся с тьмой, $C. Проникни в мир теней. Позволь Кезанскому пороку напитать темные стороны твоего "я".',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В Зандаларе уважение следует заслужить, $N. Тролли предлагают свою дружбу и заключают союзы только с теми, кого они уважают.$B$BДай мне свой талисман, я наполню его силой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8108,'Ожерелье Кезанского порока','Только совместными усилиями мы сможем остановить Свежевателя.','Я готов , $C. Еще раз улучшу твой талисман. Я только прошу тебя продолжать уничтожение Хаккара и его приспешников.$B$BДай мне талисман.','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье Кезанского порока',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Только совместными усилиями мы сможем остановить Свежевателя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я готов , $C. Еще раз улучшу твой талисман. Я только прошу тебя продолжать уничтожение Хаккара и его приспешников.$B$BДай мне талисман.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8109,'Ожерелье Вечного Кезанского Позора','Убей их и освежуй трупы. Пусть тени поглотят приспешников Хаккара! Страх твоих врагов придаст тебе силы, а ожерелье Кезанской порчи стократно умножит ее.','Призови своих демонов, $C. Пусть энергия Кезанского порока напитает их. Придет время, и ты сможешь использовать их на поле боя, чтобы уничтожить своих врагов.$B$BДа... Пришло время окончательно улучшить ожерелье Кезанского порока. Дай мне свой талисман.','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье Вечного Кезанского Позора',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Убей их и освежуй трупы. Пусть тени поглотят приспешников Хаккара! Страх твоих врагов придаст тебе силы, а ожерелье Кезанской порчи стократно умножит ее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Призови своих демонов, $C. Пусть энергия Кезанского порока напитает их. Придет время, и ты сможешь использовать их на поле боя, чтобы уничтожить своих врагов.$B$BДа... Пришло время окончательно улучшить ожерелье Кезанского порока. Дай мне свой талисман.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ал\'табиму Всевидящему в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8110,'Зачарованные водоросли Южных морей','Видишь эти водоросли, золотце? Они из Южных морей. Мы всего лишь добавили немного заклинаний и немного магии, чтобы они лучше служили своему владельцу.$B$BТы ведь $C, так что для тебя это будет совсем просто. Оберни их вокруг шеи и подумай о птичках, белочках – в общем, о чем-нибудь для тебя приятном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачарованные водоросли Южных морей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Видишь эти водоросли, золотце? Они из Южных морей. Мы всего лишь добавили немного заклинаний и немного магии, чтобы они лучше служили своему владельцу.$B$BТы ведь $C, так что для тебя это будет совсем просто. Оберни их вокруг шеи и подумай о птичках, белочках – в общем, о чем-нибудь для тебя приятном.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8111,'Зачарованные водоросли Южных морей','Смотри, не скури его нечаянно! Ожерелье поможет тебе сражаться со злом.','Привет, непоседа! Приятно тебя видеть снова. В племени только и разговоров, что о твоих победах в Зул-Гурубе. Молтор обмолвился, что неплохо бы добавить силы твоему талисману. Дай-ка его Майвики, посмотрим, сможет ли она его улучшить.','Вернитесь к Мейвики Зулдазарской в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачарованные водоросли Южных морей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смотри, не скури его нечаянно! Ожерелье поможет тебе сражаться со злом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, непоседа! Приятно тебя видеть снова. В племени только и разговоров, что о твоих победах в Зул-Гурубе. Молтор обмолвился, что неплохо бы добавить силы твоему талисману. Дай-ка его Майвики, посмотрим, сможет ли она его улучшить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8112,'Зачарованные водоросли Южных морей','Тебе удалось показать троллям Зул\'Гуруба, что значит истинная сила!','Как себя чувствует твой талисман, $N? Похоже, пришло время добавить немного магии и колдовства в его листья... А то что-то они поникли. Дай-ка мне его, Майвики сейчас все исправит.','Вернитесь к Мейвики Зулдазарской в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачарованные водоросли Южных морей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось показать троллям Зул\'Гуруба, что значит истинная сила!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как себя чувствует твой талисман, $N? Похоже, пришло время добавить немного магии и колдовства в его листья... А то что-то они поникли. Дай-ка мне его, Майвики сейчас все исправит.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8113,'Безупречные зачарованные водоросли Южных морей','Славен твой путь, $N. Продолжай преследовать и безжалостно истреблять приспешников Хаккара.','Давно не виделись, $N! Известно ли тебе, что сам король Растахан приказал добавить последний магический штрих к твоему талисману? Да-да, именно так! Я бы не поверила, если бы не слышала собственными ушами. Давай талисман сюда.','Вернитесь к Мейвики Зулдазарской в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безупречные зачарованные водоросли Южных морей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Славен твой путь, $N. Продолжай преследовать и безжалостно истреблять приспешников Хаккара.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Давно не виделись, $N! Известно ли тебе, что сам король Растахан приказал добавить последний магический штрих к твоему талисману? Да-да, именно так! Я бы не поверила, если бы не слышала собственными ушами. Давай талисман сюда.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (8114,'Контроль над четырьмя базами','$n, ты бесстрашно $gворвался:ворвалась; в самое пекло сражения в Низине Арати и $gзаслужил:заслужила; на этом поле боя великие почести. Ты $gпоказал:показала; нам, чего стоит |3-6($c) вроде тебя, и $gпоказал:показала; нашим врагам, что мы не сдадимся перед их подлостью!$B$BПоскольку ты уже $gдоказал:доказала; нам свою ценность, у меня есть для тебя очень трудное задание. Я хочу, чтобы ты $gзанял и удержал:заняла и удержала; как минимум четыре базы в Низине Арати. Если тебе удастся это сделать, мы не только сумеем собрать стратегически важные ресурсы – мы сможем показать Орде наше превосходство!$B$BИди, $n, и да сопутствует тебе удача.','Отправляйтесь в Низину Арати, захватите и удержите контроль над четырьмя базами одновременно, затем возвращайтесь к фельдмаршалу Освету в Опорный пункт.','Отличная работа, $N! Ко мне пришел взволнованный разведчик с отчетом о твоих подвигах. Мы в Лиге Аратора очень довольны!$B$BТЫ стремительно становишься местным героем среди солдат Лиги, и сегодняшний поступок еще раз доказывает твою безупречную репутацию.','Захватите и удержите контроль над четырьмя базами') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контроль над четырьмя базами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты бесстрашно $gворвался:ворвалась; в самое пекло сражения в Низине Арати и $gзаслужил:заслужила; на этом поле боя великие почести. Ты $gпоказал:показала; нам, чего стоит |3-6($c) вроде тебя, и $gпоказал:показала; нашим врагам, что мы не сдадимся перед их подлостью!$B$BПоскольку ты уже $gдоказал:доказала; нам свою ценность, у меня есть для тебя очень трудное задание. Я хочу, чтобы ты $gзанял и удержал:заняла и удержала; как минимум четыре базы в Низине Арати. Если тебе удастся это сделать, мы не только сумеем собрать стратегически важные ресурсы – мы сможем показать Орде наше превосходство!$B$BИди, $n, и да сопутствует тебе удача.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Низину Арати, захватите и удержите контроль над четырьмя базами одновременно, затем возвращайтесь к фельдмаршалу Освету в Опорный пункт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N! Ко мне пришел взволнованный разведчик с отчетом о твоих подвигах. Мы в Лиге Аратора очень довольны!$B$BТЫ стремительно становишься местным героем среди солдат Лиги, и сегодняшний поступок еще раз доказывает твою безупречную репутацию.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Захватите и удержите контроль над четырьмя базами',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (8115,'Контроль над пятью базами','$n, битва за Низину Арати – кровавое предприятие. Ваша помощь очень нужна Лиге Аратора и принимается с большой благодарностью.$B$BУ нас есть для вас еще одно задание.$B$BЛига хочет нанести решительный, сильный удар по оккупирующим Низину Арати Осквернителям. Мы хотим выбить их со всех стратегических точек поля боя!$B$BЭто будет нелегко, но если кто и в состоянии это сделать, так это именно вы.','Возьмите под контроль одновременно все 5 баз в Низине Арати, а затем возвращайтесь к фельдмаршалу Освету в Опорный пункт.','Ты $Gсделал:сделала; это! Ты $Gзабрал:забрала; все базы! $GМолодец:Умница;, $N!$B$BБыли и те, кто сомневался в твоих шансах, но я знал, что ты справишься. Спасибо и знай, что Лига Аратора очень уважает тебя.Осквернители Отрекшихся должны бояться упоминания вашего имени!','Возьмите под контроль одновременно все пять баз') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Контроль над пятью базами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, битва за Низину Арати – кровавое предприятие. Ваша помощь очень нужна Лиге Аратора и принимается с большой благодарностью.$B$BУ нас есть для вас еще одно задание.$B$BЛига хочет нанести решительный, сильный удар по оккупирующим Низину Арати Осквернителям. Мы хотим выбить их со всех стратегических точек поля боя!$B$BЭто будет нелегко, но если кто и в состоянии это сделать, так это именно вы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите под контроль одновременно все 5 баз в Низине Арати, а затем возвращайтесь к фельдмаршалу Освету в Опорный пункт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсделал:сделала; это! Ты $Gзабрал:забрала; все базы! $GМолодец:Умница;, $N!$B$BБыли и те, кто сомневался в твоих шансах, но я знал, что ты справишься. Спасибо и знай, что Лига Аратора очень уважает тебя.Осквернители Отрекшихся должны бояться упоминания вашего имени!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Возьмите под контроль одновременно все пять баз',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8116,'Ожерелье видений Вудресса','У тебя есть много общего со старой Майвики, золотце. Мы обе – $C! Правда, Майвики больше занимается мистикой, а ты в основном выполняешь за других грязную работу. Зато мы обе знаем, что могут даровать великие духи.$B$BЯ дам тебе этот шар, носи его на шее. Загляни в него, и увидишь деревню Вудресс в Южных морях. Пусть это укрепит твой дух!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье видений Вудресса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя есть много общего со старой Майвики, золотце. Мы обе – $C! Правда, Майвики больше занимается мистикой, а ты в основном выполняешь за других грязную работу. Зато мы обе знаем, что могут даровать великие духи.$B$BЯ дам тебе этот шар, носи его на шее. Загляни в него, и увидишь деревню Вудресс в Южных морях. Пусть это укрепит твой дух!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8117,'Ожерелье видений Вудресса','Остерегайся злых духов Хаккари, дружище. Честно говоря, они жуткие.','Хорошие новости, $N. Молтор в последнее время будет петь тебе дифирамбы. Он сказал, как ты превращаешься в настоящего героя Зандалара.$B$BОн также сказал, чтобы Мэйвики отполировала ваш шар еще немного! Дай это, чтобы Мэйвики могла сделать видение ярче.','Вернитесь к Мейвики Зулдазарской в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье видений Вудресса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Остерегайся злых духов Хаккари, дружище. Честно говоря, они жуткие.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хорошие новости, $N. Молтор в последнее время будет петь тебе дифирамбы. Он сказал, как ты превращаешься в настоящего героя Зандалара.$B$BОн также сказал, чтобы Мэйвики отполировала ваш шар еще немного! Дай это, чтобы Мэйвики могла сделать видение ярче.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8118,'Ожерелье видений Вудресса','Взгляни на это сейчас, $N. Вудресс стала еще четче, да? Позволь первичной силе течь через тебя, дружище.','Ша-мон! Мэйвики пошутят!$B$B<Мэйвики смеется.>$B$BИтак, ты $Gиспользовал:использовала; духов и элементы против наших врагов в Зул\'Гуруб, а? Хвала духам!$B$BМэйвики украсит ваш ожерелье. Дай сюда, $N.','Вернитесь к Мейвики Зулдазарской в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье видений Вудресса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Взгляни на это сейчас, $N. Вудресс стала еще четче, да? Позволь первичной силе течь через тебя, дружище.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ша-мон! Мэйвики пошутят!$B$B<Мэйвики смеется.>$B$BИтак, ты $Gиспользовал:использовала; духов и элементы против наших врагов в Зул\'Гуруб, а? Хвала духам!$B$BМэйвики украсит ваш ожерелье. Дай сюда, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8119,'Незамутненное ожерелье видений Вудресса','Когда-нибудь, $N, ты сможешь использовать эту сферу, чтобы общаться со мной напрямую. Как только эта битва с Хаккаром закончится, Мэйвики отправится домой. Позволь нам позвать духов и попросить их, чтобы этот день наступил поскорее.','<Мэйвики указывает на ваш талисман.>$B$BПосмотри, $N! Он ожил. Духи танцуют вокруг талисмана.$B$BОтдай его Мэйвики, чтобы она внесла последнее улучшение.','Вернитесь к Мейвики Зулдазарской в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Незамутненное ожерелье видений Вудресса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда-нибудь, $N, ты сможешь использовать эту сферу, чтобы общаться со мной напрямую. Как только эта битва с Хаккаром закончится, Мэйвики отправится домой. Позволь нам позвать духов и попросить их, чтобы этот день наступил поскорее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Мэйвики указывает на ваш талисман.>$B$BПосмотри, $N! Он ожил. Духи танцуют вокруг талисмана.$B$BОтдай его Мэйвики, чтобы она внесла последнее улучшение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мейвики Зулдазарской в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8120,'Битва за Низину Арати','Как ты, конечно, $Gслышал:слышала;, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей!$B$BОтправляйся в Низину Арати и напади на рудник, лесопилку, кузницу и стойла. Сорви с флагштоков вражеские знамена, заявив о правах Орды на эти территории.$B$BИди, $n. Доложи мне, когда выполнишь задание.','Нападите на рудник, лесопилку, кузницу и стойла в Низине Арати и возвращайтесь к повелительнице смерти Двайр в Павший Молот.','Разведчик Осквернителя пришел ко мне с отчетом о твоем успехе, $N. $GМолодец:Умница;.$B$BКак ты знаешь, чтобы выиграть битву за Низину Арати, мы должны быть всегда бдительны и пресекать любые попытки расширения Альянса. Сделаем это и наша победа здесь обеспечена.','Вернитесь к повелительнице смерти Двайр к Восточному кругу Обуздания, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Низину Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты, конечно, $Gслышал:слышала;, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей!$B$BОтправляйся в Низину Арати и напади на рудник, лесопилку, кузницу и стойла. Сорви с флагштоков вражеские знамена, заявив о правах Орды на эти территории.$B$BИди, $n. Доложи мне, когда выполнишь задание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нападите на рудник, лесопилку, кузницу и стойла в Низине Арати и возвращайтесь к повелительнице смерти Двайр в Павший Молот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разведчик Осквернителя пришел ко мне с отчетом о твоем успехе, $N. $GМолодец:Умница;.$B$BКак ты знаешь, чтобы выиграть битву за Низину Арати, мы должны быть всегда бдительны и пресекать любые попытки расширения Альянса. Сделаем это и наша победа здесь обеспечена.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелительнице смерти Двайр к Восточному кругу Обуздания, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (8121,'Захват четырех баз','$n, в то время как гремят бои за Низину Арати, новости о ваших деяниях достигли моих ушей. Среди нас вы пользуетесь большим уважением, и это дает мне уверенность в том, что вы выполните миссию, которую я собираюсь на вас возложить.$B$BПришло время послать весточку Лиге Аратора. Мы должны дать им понять, что их позиции в Низине Арати слабы, и потерять их очень легко. Мы должны показать им это, удерживая одновременно четыре стратегических точки в низине.$B$BДобейтесь успеха в этом, $n, и заслужите еще большее уважение среди Осквернителей.','Удерживайте одновременно четыре базы в Низине Арати, а затем возвращайтесь к повелительнице смерти Двайр в Павший Молот.','Хорошая работа, $N! Твои последние сражения в Низине Арати были довольно трудными, и поэтому их успехи достойны похвалы. Лига Аратора, должно быть, пошатнулась от последних стычек в бассейне, зализывает свои раны, и надеюсь, они передумали здесь сражаться.','Удерживайте одновременно четыре базы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват четырех баз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, в то время как гремят бои за Низину Арати, новости о ваших деяниях достигли моих ушей. Среди нас вы пользуетесь большим уважением, и это дает мне уверенность в том, что вы выполните миссию, которую я собираюсь на вас возложить.$B$BПришло время послать весточку Лиге Аратора. Мы должны дать им понять, что их позиции в Низине Арати слабы, и потерять их очень легко. Мы должны показать им это, удерживая одновременно четыре стратегических точки в низине.$B$BДобейтесь успеха в этом, $n, и заслужите еще большее уважение среди Осквернителей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Удерживайте одновременно четыре базы в Низине Арати, а затем возвращайтесь к повелительнице смерти Двайр в Павший Молот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $N! Твои последние сражения в Низине Арати были довольно трудными, и поэтому их успехи достойны похвалы. Лига Аратора, должно быть, пошатнулась от последних стычек в бассейне, зализывает свои раны, и надеюсь, они передумали здесь сражаться.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Удерживайте одновременно четыре базы',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (8122,'Занять пять баз','Непросто увидеть, когда мы так уже глубоко увязли в конфликте, но наши разведчики сообщают об ослаблении Лиги Аратора. Мы должны использовать это окно и нанести Лиге жестокий удар! Возвращайтесь в Низину Арати и бросайтесь в бой против наших врагов. Проклинайте их, убивайте их и захватите все пять стратегических баз! Пусть их солдаты с воплями бегут с передовой и пусть рассказы о вашей жестокости срываются с их дрожащих губ.$B$BСделайте это и одержите великую победу для Осквернителей.','Захватите и удерживайте все пять баз в Низине Арати, затем возвращайтесь к повелительнице смерти Двайр в Павший Молот.','Крики Альянса можно было услышать даже отсюда, когда вы их атаковали, $N. Мне даже стало их жаль.$B$BТвоя значимость для Осквернителей не вызывает сомнений. Твои деяния в Низине Арати были самыми впечатляющими образами, и они отозвались эхом в покоях Вариматраса...','Захватите и удерживайте все пять баз') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Занять пять баз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Непросто увидеть, когда мы так уже глубоко увязли в конфликте, но наши разведчики сообщают об ослаблении Лиги Аратора. Мы должны использовать это окно и нанести Лиге жестокий удар! Возвращайтесь в Низину Арати и бросайтесь в бой против наших врагов. Проклинайте их, убивайте их и захватите все пять стратегических баз! Пусть их солдаты с воплями бегут с передовой и пусть рассказы о вашей жестокости срываются с их дрожащих губ.$B$BСделайте это и одержите великую победу для Осквернителей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Захватите и удерживайте все пять баз в Низине Арати, затем возвращайтесь к повелительнице смерти Двайр в Павший Молот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Крики Альянса можно было услышать даже отсюда, когда вы их атаковали, $N. Мне даже стало их жаль.$B$BТвоя значимость для Осквернителей не вызывает сомнений. Твои деяния в Низине Арати были самыми впечатляющими образами, и они отозвались эхом в покоях Вариматраса...',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Захватите и удерживайте все пять баз',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (8123,'Перекрыть линии поставок Аратора','Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдаленную область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы.$B$BВы, $n, можете нам помочь. Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перекрыть линии поставок Аратора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдаленную область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы.$B$BВы, $n, можете нам помочь. Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8124,'Новые ящики с ресурсами','Очень хорошо. Я немедленно передам их нашим интендантам.$B$BЕще раз спасибо, $N. Твой вклад в нашу борьбу заметят как ворчун, так и верховный полководец.','$N, у Осквернителей есть постоянная миссия: вернуться в низину Арати, добыть еще ящики с ресурсами и принести их мне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые ящики с ресурсами',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Я немедленно передам их нашим интендантам.$B$BЕще раз спасибо, $N. Твой вклад в нашу борьбу заметят как ворчун, так и верховный полководец.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, у Осквернителей есть постоянная миссия: вернуться в низину Арати, добыть еще ящики с ресурсами и принести их мне.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8141,'Зандаларский талисман Тьмы','Ты быстро растешь, юный $C. Пришло время принять тебя в Шера Алик. На нашем языке это название означает "Рука смерти". Тысячи лет мы были наемными убийцами Зандаларской империи. Слишком долго мы сидели сложа руки и смотрели, как Хаккар набирает силу. Настала пора сразиться с ним, но теперь за нами нет объединенных сил троллей. Только ты и подобные тебе могут помочь нам в борьбе с Кровавым богом и его приспешниками.$B$BНоси этот талисман, и пусть он поможет тебе в твоих странствиях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандаларский талисман Тьмы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты быстро растешь, юный $C. Пришло время принять тебя в Шера Алик. На нашем языке это название означает "Рука смерти". Тысячи лет мы были наемными убийцами Зандаларской империи. Слишком долго мы сидели сложа руки и смотрели, как Хаккар набирает силу. Настала пора сразиться с ним, но теперь за нами нет объединенных сил троллей. Только ты и подобные тебе могут помочь нам в борьбе с Кровавым богом и его приспешниками.$B$BНоси этот талисман, и пусть он поможет тебе в твоих странствиях.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8142,'Зандаларский талисман Тьмы','Осталось только одно улучшение, которое можно наложить на талисман, $C. Когда придет время, я применю это улучшение.','Впечатляет, $N. У тебя есть талант к убийству, которого я не ощущал ни у кого уже много лет. Даже Молтор знает о той работе, которую ты $Gпроделал:проделала; для Зандалара. Пора еще больше усилить талисман. Дай мне.','Вернитесь к Фальтиру Слепому в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандаларский талисман Тьмы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Осталось только одно улучшение, которое можно наложить на талисман, $C. Когда придет время, я применю это улучшение.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Впечатляет, $N. У тебя есть талант к убийству, которого я не ощущал ни у кого уже много лет. Даже Молтор знает о той работе, которую ты $Gпроделал:проделала; для Зандалара. Пора еще больше усилить талисман. Дай мне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8143,'Зандаларский талисман Тьмы','Ваши враги должны научиться уважению! Вы получите это, когда враг увидит блеск Руки Смерти - но будет слишком поздно...','Я чувствую, что ты $Gубил:убила; хаккари, $N, бесчисленное количество раз. Ты несешь вонь их моджо.$B$BПолагаю, талисман Тени помог? Отдай его мне и позволь мне усилить его силу.','Вернитесь к Фальтиру Слепому в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандаларский талисман Тьмы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ваши враги должны научиться уважению! Вы получите это, когда враг увидит блеск Руки Смерти - но будет слишком поздно...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую, что ты $Gубил:убила; хаккари, $N, бесчисленное количество раз. Ты несешь вонь их моджо.$B$BПолагаю, талисман Тени помог? Отдай его мне и позволь мне усилить его силу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8144,'Зандаларский талисман власти над Тьмой','Это последний раз, когда мы будем выступать под эгидой Шеры Али\'х. Вы знаете все, что должны. Возьмите талисман и продолжайте убивать. Нельзя позволить Хаккару покинуть Зул\'Гуруб.','Он стремится к росту, $N. В талисман впиталось все, что ты $Gсделал:сделала;. Тысячи трупов троллей, усеивающих Зул\'Гуруб, подпитывают его силу. Дай его мне, и я сделаю последнее улучшение.','Вернитесь к Фальтиру Слепому в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зандаларский талисман власти над Тьмой',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это последний раз, когда мы будем выступать под эгидой Шеры Али\'х. Вы знаете все, что должны. Возьмите талисман и продолжайте убивать. Нельзя позволить Хаккару покинуть Зул\'Гуруб.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он стремится к росту, $N. В талисман впиталось все, что ты $Gсделал:сделала;. Тысячи трупов троллей, усеивающих Зул\'Гуруб, подпитывают его силу. Дай его мне, и я сделаю последнее улучшение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8145,'Нить Водоворота','В Зандаларе профессия охотника весьма уважаема, $C. Наши лучшие охотники уплывают к самому краю Водоворота, чтобы доказать свою отвагу.$B$BТам, в сердце моря, они добывают водоросль, известную как "нить Водоворота". Из нее плетут талисманы, увеличивающие силу и меткость.$B$BЯ дам тебе одну нить Водоворота. По мере того как будет расти твоя связь с Зандаларом, я буду вплетать новые нити в твой талисман.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нить Водоворота',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В Зандаларе профессия охотника весьма уважаема, $C. Наши лучшие охотники уплывают к самому краю Водоворота, чтобы доказать свою отвагу.$B$BТам, в сердце моря, они добывают водоросль, известную как "нить Водоворота". Из нее плетут талисманы, увеличивающие силу и меткость.$B$BЯ дам тебе одну нить Водоворота. По мере того как будет расти твоя связь с Зандаларом, я буду вплетать новые нити в твой талисман.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8146,'Нить Водоворота','Пусть ищут искупления в ваших боеприпасах.','Даже отсюда я слышу звук твоих залпов, опустошающих наших врагов. Их крики разносятся эхом агонии.$B$BТы $Gпрославился:прославилась; среди троллей Зандалара, $N. Мы благодарны тебе за все, что ты $Gсделал:сделала;.$B$BДай мне свой талисман, чтобы я мог добавить еще одно плетение.','Вернитесь к Фальтиру Слепому в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нить Водоворота',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть ищут искупления в ваших боеприпасах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Даже отсюда я слышу звук твоих залпов, опустошающих наших врагов. Их крики разносятся эхом агонии.$B$BТы $Gпрославился:прославилась; среди троллей Зандалара, $N. Мы благодарны тебе за все, что ты $Gсделал:сделала;.$B$BДай мне свой талисман, чтобы я мог добавить еще одно плетение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8147,'Нить Водоворота','Осталось только одно улучшение, которое я смогу добавить к твоему талисману, $N.','Ах, $N, приятно снова тебя понюхать.$B$B<Фалтир усмехается.>$B$BИзвини за мое чувство юмора. Иногда это может быть очень грязно.$B$BЯ чувствую, что Ты $Gпричинил:причинила; огромную боль нашим врагам. Силы Хаккара в гневе выкрикивают твое имя. Это превосходно.$B$BТы $Gзаработал:заработала; еще одно плетение на своем талисмане. Передай это мне','Вернитесь к Фальтиру Слепому в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нить Водоворота',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Осталось только одно улучшение, которое я смогу добавить к твоему талисману, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ах, $N, приятно снова тебя понюхать.$B$B<Фалтир усмехается.>$B$BИзвини за мое чувство юмора. Иногда это может быть очень грязно.$B$BЯ чувствую, что Ты $Gпричинил:причинила; огромную боль нашим врагам. Силы Хаккара в гневе выкрикивают твое имя. Это превосходно.$B$BТы $Gзаработал:заработала; еще одно плетение на своем талисмане. Передай это мне',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8148,'Ярость Водоворота','Твой путь только начался, $C. Возможно, однажды вы посетите Водоворот и загляните в самое сердце мира.$B$BЖелаю силы и стойкости!','Молтор передает сообщение от короля Растахана, $N. Королевский двор очень впечатлен твоим уничтожением сил Хаккари. Я должен наградить тебя последним переплетением твоего талисмана. Передай мне.','Вернитесь к Фальтиру Слепому в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ярость Водоворота',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твой путь только начался, $C. Возможно, однажды вы посетите Водоворот и загляните в самое сердце мира.$B$BЖелаю силы и стойкости!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Молтор передает сообщение от короля Растахана, $N. Королевский двор очень впечатлен твоим уничтожением сил Хаккари. Я должен наградить тебя последним переплетением твоего талисмана. Передай мне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фальтиру Слепому в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (8149,'Почести герою','Во время Недели урожая в Азероте мы возносим хвалу героям, которые готовы жизнь отдать – а порой и отдают – за нас. Альянс славит множество героев, но нет повести печальнее на свете, чем повесть об Утере Светоносном.$B$BПомоги же нам воздать почести Утеру и отнеси эти подношения к его гробнице в Западных Чумных землях. Положи их к подножию его статуи и возвращайся ко мне. Я пробуду тут только до конца праздника, так что не трать времени и отнеси Утеру эти приношения.','Пойдите к гробнице Утера в Западных Чумных землях, положите подношения у подножия его статуи и вернутсья к Вагнеру Молотобойцу в Стальгорн до конца Недели урожая.','Он был героем из героев, этот Утер. Даже представить не могу, какую боль он испытал, когда Артас – его лучший ученик, которого Утер любил как сына, – предал человечество. И все же он попытался остановить Артаса, за что мы всегда будем его помнить как истинного паладина. Он дрался до конца, думая лишь о тех, кого надеялся спасти.$B$BСпасибо тебе, $N. Ты $Gоказал:оказала; почести великому герою, помянув его и принеся радость Неделе урожая.','Ты $Gсовершил;совершила; путешествие к Могиле Утера и $Gпоместил:поместила; там дань?$B$BЭто может быть опасное путешествие для менее опытных искателей приключений; условно говоря, более безопасный способ передвижения - путешествие на север от реки, протекающей через Хилсбрад, до Чумных земель. Это течет из озера, которое смежно с Холмом Скорби; отправляйтесь на запад через холмы, избегая прилегающей гробницы... той, которая кишит Плетью.','Положите подношение у гробницы Утера','Вернитесь к Вагнеру Молотобойцу ко Вратам Стальгорна, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почести герою',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время Недели урожая в Азероте мы возносим хвалу героям, которые готовы жизнь отдать – а порой и отдают – за нас. Альянс славит множество героев, но нет повести печальнее на свете, чем повесть об Утере Светоносном.$B$BПомоги же нам воздать почести Утеру и отнеси эти подношения к его гробнице в Западных Чумных землях. Положи их к подножию его статуи и возвращайся ко мне. Я пробуду тут только до конца праздника, так что не трать времени и отнеси Утеру эти приношения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пойдите к гробнице Утера в Западных Чумных землях, положите подношения у подножия его статуи и вернутсья к Вагнеру Молотобойцу в Стальгорн до конца Недели урожая.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он был героем из героев, этот Утер. Даже представить не могу, какую боль он испытал, когда Артас – его лучший ученик, которого Утер любил как сына, – предал человечество. И все же он попытался остановить Артаса, за что мы всегда будем его помнить как истинного паладина. Он дрался до конца, думая лишь о тех, кого надеялся спасти.$B$BСпасибо тебе, $N. Ты $Gоказал:оказала; почести великому герою, помянув его и принеся радость Неделе урожая.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсовершил;совершила; путешествие к Могиле Утера и $Gпоместил:поместила; там дань?$B$BЭто может быть опасное путешествие для менее опытных искателей приключений; условно говоря, более безопасный способ передвижения - путешествие на север от реки, протекающей через Хилсбрад, до Чумных земель. Это течет из озера, которое смежно с Холмом Скорби; отправляйтесь на запад через холмы, избегая прилегающей гробницы... той, которая кишит Плетью.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Положите подношение у гробницы Утера',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вагнеру Молотобойцу ко Вратам Стальгорна, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (8150,'Почести герою','Во время Недели урожая мы воздаем почести героям, которые готовы отдать, – а порой и отдают, – за нас жизнь. В Орде множество храбрецов и героев, но нет более яркого примера мужества и самопожертвования, чем Гром Адский Крик.$B$BПомоги же нам воздать почести Грому. Отнеси эти подношения к его памятнику в Каньоне Гибели Демона в Ясеневом лесу. Положи их к ногам статуи и возвращайся ко мне. Я пробуду тут только до конца праздника, так что не теряй времени!','Отправляйтесь к памятнику Грому Адскому Крику в Каньон Гибели Демона в Ясеневом лесу и положите подношения у подножия памятника. Вернитесь к Явниру Нашаку в Оргриммар до конца Недели урожая.','Полное имя Грома – "Громмаш", означает "Сердце великана". Воистину, ему потребовалось сердце великана, чтобы в одиночку выстоять против Маннорота! Верно сказал вождь, что проклятие орков началось с Грома, и Гром же с ним покончил! И воистину, самопожертвование – и, возможно, искупление – Грома было не напрасным.$B$BСпасибо тебе, $N. Ты $Gпочтил:почтила; память великого героя, порадовав его дух и дух Недели урожая.','Ты $Gсовершил:совершила; путешествие к Памятнику Грома и $Gпоместил:поместила; его дань там?$B$BМесто, где стоит памятник, до сих пор тронуто заразой Пылающего Легиона. Если вы менее опытны в приключениях, будьте осторожны при приближении к памятнику.','Положите подношение у памятника Грому','Вернитесь к Явниру Нашаку в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почести герою',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время Недели урожая мы воздаем почести героям, которые готовы отдать, – а порой и отдают, – за нас жизнь. В Орде множество храбрецов и героев, но нет более яркого примера мужества и самопожертвования, чем Гром Адский Крик.$B$BПомоги же нам воздать почести Грому. Отнеси эти подношения к его памятнику в Каньоне Гибели Демона в Ясеневом лесу. Положи их к ногам статуи и возвращайся ко мне. Я пробуду тут только до конца праздника, так что не теряй времени!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к памятнику Грому Адскому Крику в Каньон Гибели Демона в Ясеневом лесу и положите подношения у подножия памятника. Вернитесь к Явниру Нашаку в Оргриммар до конца Недели урожая.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Полное имя Грома – "Громмаш", означает "Сердце великана". Воистину, ему потребовалось сердце великана, чтобы в одиночку выстоять против Маннорота! Верно сказал вождь, что проклятие орков началось с Грома, и Гром же с ним покончил! И воистину, самопожертвование – и, возможно, искупление – Грома было не напрасным.$B$BСпасибо тебе, $N. Ты $Gпочтил:почтила; память великого героя, порадовав его дух и дух Недели урожая.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсовершил:совершила; путешествие к Памятнику Грома и $Gпоместил:поместила; его дань там?$B$BМесто, где стоит памятник, до сих пор тронуто заразой Пылающего Легиона. Если вы менее опытны в приключениях, будьте осторожны при приближении к памятнику.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Положите подношение у памятника Грому',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Явниру Нашаку в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8151,'Талисман охотника','Огтинк из Азшары ищет опытных охотников вроде тебя. Огтинк – фурболг-охотник, отрекшийся от своего племени ради помощи Кругу Кенария. Он стремится наставлять собратьев по оружию и учить их соблюдению природного равновесия. Тебе не помешает поговорить с ним.$b$bОгтинг живет на скалах Азшары, на северо-востоке от руин Эльдарата.','Поговорите с Огтинком из Азшары.','Я более не охочусь, а учу других. Такая судьба.$B$BСоздай с моей помощью талисман охотника, состоящий из частиц убитой дичи. Талисман будет напоминать тебе о прошлых испытаниях и победах. Я оставлю его себе, а тебе дам кое-что другое.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Талисман охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огтинк из Азшары ищет опытных охотников вроде тебя. Огтинк – фурболг-охотник, отрекшийся от своего племени ради помощи Кругу Кенария. Он стремится наставлять собратьев по оружию и учить их соблюдению природного равновесия. Тебе не помешает поговорить с ним.$b$bОгтинг живет на скалах Азшары, на северо-востоке от руин Эльдарата.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Огтинком из Азшары.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я более не охочусь, а учу других. Такая судьба.$B$BСоздай с моей помощью талисман охотника, состоящий из частиц убитой дичи. Талисман будет напоминать тебе о прошлых испытаниях и победах. Я оставлю его себе, а тебе дам кое-что другое.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8152,'REUSE','$n, когда будете готовы, сходите к умудренному фурболгу-охотнику по имени Огтинк, что живет в Азшаре. Он может обучить вас еще лучше и стать вашим наставником.$b$bОгтинк живет на вершинах утесов к северо-востоку от руин Эльдарата, что в Азшаре.','Поговорите в Азшаре с Огтинком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REUSE',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, когда будете готовы, сходите к умудренному фурболгу-охотнику по имени Огтинк, что живет в Азшаре. Он может обучить вас еще лучше и стать вашим наставником.$b$bОгтинк живет на вершинах утесов к северо-востоку от руин Эльдарата, что в Азшаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Азшаре с Огтинком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8153,'Рога и копыта','Беговые олени являются обладателями самых мощных рогов из всех известных нам животных. Олень использует рога для обороны, атаки и нередко убийства. Совершенной формы рога являются свидетельством силы духа животного. $B$BДобывший такие рога и сам обретает небывалую силу духа. $B$BПоохоться на мохноногих оленей и принеси мне лучшую пару их рогов.','Принесите пару великолепных рогов мохоногого оленя Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.','У тебя явно хорошее терпение и зоркий глаз, иначе тебе не удалось бы справиться с задачей. Я доволен.','$Gпринес:принесла; рога?','Вернитесь к Огтинку на Разоренное побережье, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рога и копыта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Беговые олени являются обладателями самых мощных рогов из всех известных нам животных. Олень использует рога для обороны, атаки и нередко убийства. Совершенной формы рога являются свидетельством силы духа животного. $B$BДобывший такие рога и сам обретает небывалую силу духа. $B$BПоохоться на мохноногих оленей и принеси мне лучшую пару их рогов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите пару великолепных рогов мохоногого оленя Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя явно хорошее терпение и зоркий глаз, иначе тебе не удалось бы справиться с задачей. Я доволен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$Gпринес:принесла; рога?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Огтинку на Разоренное побережье, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8154,'Ресурсы Низины Арати','Войну выигрывают солдаты – любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо и все это можно добыть там.$B$BИ вот чего я хочу от вас, $n. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.','Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Макчисту в Опорный пункт.','У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам.$B$BСпасибо, $N. Действительно, успешное выполнение миссий, подобных той, которую ты $Gвыполнил:выполнила;, - вот как действительно выигрывают войны.','У тебя есть ящик с ресурсами, $N? Без них Лига Аратора не сможет вести достойную битву...','Вернитесь к сержанту Макчист на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ресурсы Низины Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войну выигрывают солдаты – любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо и все это можно добыть там.$B$BИ вот чего я хочу от вас, $n. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Макчисту в Опорный пункт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам.$B$BСпасибо, $N. Действительно, успешное выполнение миссий, подобных той, которую ты $Gвыполнил:выполнила;, - вот как действительно выигрывают войны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть ящик с ресурсами, $N? Без них Лига Аратора не сможет вести достойную битву...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Макчист на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
