INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8157,'Новые ящики с ресурсами','Очень хорошо. Я немедленно передам их нашим интендантам.$B$BЕще раз спасибо, $N. Твой вклад в нашу борьбу заметят как целитель, так и фельдмаршал.','$N, у Лиги Аратора есть постоянная миссия: вернуться в низину Арати, добыть еще ящики с ресурсами и принести их мне.','Вернитесь к сержанту Макчист на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые ящики с ресурсами',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Я немедленно передам их нашим интендантам.$B$BЕще раз спасибо, $N. Твой вклад в нашу борьбу заметят как целитель, так и фельдмаршал.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, у Лиги Аратора есть постоянная миссия: вернуться в низину Арати, добыть еще ящики с ресурсами и принести их мне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Макчист на Нагорье Арати.',`completedtext_loc8`);
