INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8166,'Битва за Низину Арати','$n, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать с целью обеспечить наши силы поставками сырья и различных припасов. Я отдаю тебе приказ атаковать самые удаленные от нашей базы точки. $b$bНапади на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найди вражеский флаг и сорви его с флагштока! $b$bКогда сумеешь сделать это в четырех указанных точках, возвращайся ко мне.','Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.','Я получил сообщения о ваших подвигах в Низине Арати, $N. Отлично сработано! С теми, кто, как вы, присоединяется к борьбе здесь, я верю,что однажды мы вернем наши родные земли.','Вернитесь к фельдмаршалу Освету на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Низину Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать с целью обеспечить наши силы поставками сырья и различных припасов. Я отдаю тебе приказ атаковать самые удаленные от нашей базы точки. $b$bНапади на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найди вражеский флаг и сорви его с флагштока! $b$bКогда сумеешь сделать это в четырех указанных точках, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я получил сообщения о ваших подвигах в Низине Арати, $N. Отлично сработано! С теми, кто, как вы, присоединяется к борьбе здесь, я верю,что однажды мы вернем наши родные земли.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фельдмаршалу Освету на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8167,'Битва за Низину Арати','$n, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать с целью обеспечить наши силы поставками сырья и различных припасов. Я отдаю тебе приказ атаковать самые удаленные от нашей базы точки. $b$bНапади на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найди вражеский флаг и сорви его с флагштока! $b$bКогда сумеешь сделать это в четырех указанных точках, возвращайся ко мне.','Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.','Я получил сообщения о ваших подвигах в Низине Арати, $N. Отлично сработано! С теми, кто, как вы, присоединяется к борьбе здесь, я верю,что однажды мы вернем наши родные земли.','Вернитесь к фельдмаршалу Освету на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Низину Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, битва за Низину Арати – это битва за ресурсы и за территорию. Ключевые точки на этой местности нужно удерживать с целью обеспечить наши силы поставками сырья и различных припасов. Я отдаю тебе приказ атаковать самые удаленные от нашей базы точки. $b$bНапади на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага. Найди вражеский флаг и сорви его с флагштока! $b$bКогда сумеешь сделать это в четырех указанных точках, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я получил сообщения о ваших подвигах в Низине Арати, $N. Отлично сработано! С теми, кто, как вы, присоединяется к борьбе здесь, я верю,что однажды мы вернем наши родные земли.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фельдмаршалу Освету на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
