INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8171,'Битва за Низину Арати','Как ты, конечно, $Gслышал:слышала;, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей!$B$BОтправляйся в Низину Арати и напади на рудник, лесопилку, кузницу и стойла. Сорви с флагштоков вражеские знамена, заявив о правах Орды на эти территории.$B$BИди, $n. Доложи мне, когда выполнишь задание.','Захватите в Низине Арати рудник, лесопилку, кузницу и стойла и возвращайтесь к повелительнице смерти Двайр в Павший Молот.','Вернитесь к повелительнице смерти Двайр к Восточному кругу Обуздания, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Низину Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты, конечно, $Gслышал:слышала;, Лига Аратора посылает огромное количество войск в Низину Арати. Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов. Мы должны показать им, что Арати никогда больше не будет домом для людей!$B$BОтправляйся в Низину Арати и напади на рудник, лесопилку, кузницу и стойла. Сорви с флагштоков вражеские знамена, заявив о правах Орды на эти территории.$B$BИди, $n. Доложи мне, когда выполнишь задание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Захватите в Низине Арати рудник, лесопилку, кузницу и стойла и возвращайтесь к повелительнице смерти Двайр в Павший Молот.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелительнице смерти Двайр к Восточному кругу Обуздания, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8181,'Сопротивление Йекинье','Дурные вести, $n. Если верить табличкам Мошару, то подлинная сущность Хаккара, то есть само божество, может родиться из того самого яйца, в которое тебе удалось его заключить. Йе\'кинья обманул тебя, он хотел привести в мир Хаккара!$B$BСтупай к этому негодяю и потребуй, чтобы он вернул тебе яйцо. Остается молиться, чтобы можно было предотвратить возрождение Хаккара!','Поговорите с Йе\'киньей.','Значит, ты $Gпоговорил:поговорила; с этим старым дворфом Железным Башмаком и $Gотыскал:отыскала; утраченные таблички Мошару? Ох, уж этот проспектор, сующий нос не в свое дело…$B$BНеважно. Мир уже не спасти. Хаккар возродился, и сила его растет с каждым часом... далеко-далеко, в глубинах древнего королевства Зул\'Гуруба! Он вернулся! И теперь затопит мир кровью и ужасом!$B$BСпасибо, $N. Ты $Gпомог:помогла; ускорить возвращение Свежевателя Душ!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сопротивление Йекинье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дурные вести, $n. Если верить табличкам Мошару, то подлинная сущность Хаккара, то есть само божество, может родиться из того самого яйца, в которое тебе удалось его заключить. Йе\'кинья обманул тебя, он хотел привести в мир Хаккара!$B$BСтупай к этому негодяю и потребуй, чтобы он вернул тебе яйцо. Остается молиться, чтобы можно было предотвратить возрождение Хаккара!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Йе\'киньей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, ты $Gпоговорил:поговорила; с этим старым дворфом Железным Башмаком и $Gотыскал:отыскала; утраченные таблички Мошару? Ох, уж этот проспектор, сующий нос не в свое дело…$B$BНеважно. Мир уже не спасти. Хаккар возродился, и сила его растет с каждым часом... далеко-далеко, в глубинах древнего королевства Зул\'Гуруба! Он вернулся! И теперь затопит мир кровью и ужасом!$B$BСпасибо, $N. Ты $Gпомог:помогла; ускорить возвращение Свежевателя Душ!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8182,'Длань Растахана','Все наши самые жуткие страхи сбываются. В легендах говорилось о Свежевателе Душ, правившим миром древних троллей злом и жестокостью. Сила его была беспредельна. Если его не остановить, он снова воцарится в Азероте!$b$bТролли Зандалара могут остановить наступление тьмы. Они живут на острове Йоджамба, недалеко от побережья Тернистой долины, к западу от Руин Зул\'Кунды. Поговори с их вождем, Молтором. Будем надеяться, что он знает, как одолеть Хаккара.','Поговорите с Молтором из Тернистой долины.','Тебя прислал геолог, Железный Башмак? Он мудр, как и его сородичи, и в мудрости своей прислал тебя ко мне. Мы, зандаларские тролли, знаем, как одолеть Свежевателя Душ.$B$BПоговори с другими троллями, живущими на острове, прислушайся к их словам и готовься, $N, ибо твой дальнейший путь пропитан кровью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Длань Растахана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все наши самые жуткие страхи сбываются. В легендах говорилось о Свежевателе Душ, правившим миром древних троллей злом и жестокостью. Сила его была беспредельна. Если его не остановить, он снова воцарится в Азероте!$b$bТролли Зандалара могут остановить наступление тьмы. Они живут на острове Йоджамба, недалеко от побережья Тернистой долины, к западу от Руин Зул\'Кунды. Поговори с их вождем, Молтором. Будем надеяться, что он знает, как одолеть Хаккара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Молтором из Тернистой долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал геолог, Железный Башмак? Он мудр, как и его сородичи, и в мудрости своей прислал тебя ко мне. Мы, зандаларские тролли, знаем, как одолеть Свежевателя Душ.$B$BПоговори с другими троллями, живущими на острове, прислушайся к их словам и готовься, $N, ибо твой дальнейший путь пропитан кровью.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8183,'Сердце Хаккара','Сердце Хаккара пылает изнутри. Свежеватель Душ повержен, но ключ к его силе – все еще в его сердце.','Принесите сердце Хаккара Молтору на остров Йоджамба.','Сердце Хаккара!.. Со Свежевателем Душ покончено! Наш мир спасен!$B$BНевозможно переоценить то, что ты $Gсделал:сделала; для нас, $N. Ты – живая легенда нашего мира.','$N, ты $Gокружен:окружена темной аурой. Неужели и тебя настигло проклятие Свежевателя Душ?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце Хаккара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сердце Хаккара пылает изнутри. Свежеватель Душ повержен, но ключ к его силе – все еще в его сердце.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сердце Хаккара Молтору на остров Йоджамба.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сердце Хаккара!.. Со Свежевателем Душ покончено! Наш мир спасен!$B$BНевозможно переоценить то, что ты $Gсделал:сделала; для нас, $N. Ты – живая легенда нашего мира.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты $Gокружен:окружена темной аурой. Неужели и тебя настигло проклятие Свежевателя Душ?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8184,'Явление Силы','Используй подарок с умом, |3-6($C). Не давай спуску приспешникам Хаккара!','Принеси мне все компоненты и я сделаю для тебя могущественный амулет!','Вернитесь к Занзе Неупокоенному.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Явление Силы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Используй подарок с умом, |3-6($C). Не давай спуску приспешникам Хаккара!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принеси мне все компоненты и я сделаю для тебя могущественный амулет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Занзе Неупокоенному.',`completedtext_loc8`);
