INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8193,'Главный приз','Спешите и сдайте их, если хотите быть объявленным Мастером Рыболова! Я стою здесь ЧАСЫ без еды! Отдай этих рыб!','Сегодня между 14:00 и 16:00 у нас будет проходить соревнование, чтобы определить, кто из них самый лучший рыболов! Просто будьте ПЕРВЫМ, кто принесёт мне 40 Крапчатых вкуснорыб, выловленных из Пиратской Бухты, найденных вдоль побережья Тернистой долины, и вы будете объявлены Морским дьяволом!$B$BЕсли вы не $Gпервый:первая;, кто принес мне 40 рыб, мой ученик все равно вознаградит вас деньгами за каждые 5 рыб, которые вы ей принесете.$B$BО, и не откладывайте, они быстро портятся!','Вернитесь к Ригглу Мормышу в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главный приз',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спешите и сдайте их, если хотите быть объявленным Мастером Рыболова! Я стою здесь ЧАСЫ без еды! Отдай этих рыб!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сегодня между 14:00 и 16:00 у нас будет проходить соревнование, чтобы определить, кто из них самый лучший рыболов! Просто будьте ПЕРВЫМ, кто принесёт мне 40 Крапчатых вкуснорыб, выловленных из Пиратской Бухты, найденных вдоль побережья Тернистой долины, и вы будете объявлены Морским дьяволом!$B$BЕсли вы не $Gпервый:первая;, кто принес мне 40 рыб, мой ученик все равно вознаградит вас деньгами за каждые 5 рыб, которые вы ей принесете.$B$BО, и не откладывайте, они быстро портятся!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ригглу Мормышу в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8194,'Начинающий рыболов','Несмотря на то, что у нас уже есть победитель конкурса, я все равно куплю у тебя Крапчатую рыбу по разумной цене. Что ты скажешь?!','Вернитесь к Джанг в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Начинающий рыболов',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Несмотря на то, что у нас уже есть победитель конкурса, я все равно куплю у тебя Крапчатую рыбу по разумной цене. Что ты скажешь?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джанг в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8195,'Монеты племен: Зулиан, Раззаши и Хаккари','Отлично – эти монеты прекрасно дополнят в мою коллекцию... Они нужны племени, чтобы помешать возрождению Кровавого бога. Этот почетный знак – твой по праву, $N, прими его вместе с нашей благодарностью!','Я ищу Знаки Силы, известные как Монеты Племен. Это валюта, используемая различными обитателями Зул\'Гуруба, и каждый из них наделен тонким, но могущественным моджо.$B$BМожно найти девять различных видов. Если у тебя есть лишние, я обменяю один из наших жетонов чести на набор из трех. Вы можете использовать Жетоны с Торговцем Рин\'вошо; он предлагает нашим героям специальные предметы за них.','Вернитесь к Винчаксе в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Монеты племен: Зулиан, Раззаши и Хаккари',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично – эти монеты прекрасно дополнят в мою коллекцию... Они нужны племени, чтобы помешать возрождению Кровавого бога. Этот почетный знак – твой по праву, $N, прими его вместе с нашей благодарностью!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я ищу Знаки Силы, известные как Монеты Племен. Это валюта, используемая различными обитателями Зул\'Гуруба, и каждый из них наделен тонким, но могущественным моджо.$B$BМожно найти девять различных видов. Если у тебя есть лишние, я обменяю один из наших жетонов чести на набор из трех. Вы можете использовать Жетоны с Торговцем Рин\'вошо; он предлагает нашим героям специальные предметы за них.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Винчаксе в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8196,'Экстракт манго','Честная сделка, мой друг - пожалуйста, насладитесь сочными фруктами Южных морей с благословения племени.','$N, из которых можно изготовить могучий экстракт, растут на островах Южных морей. Одно-единственное манго придает и физические и душевные силы тому, кто его съест. Тебе когда-нибудь приходилось пробовать манго? Если нет, то ты много потерял!$B$BУ нас есть запасы манго, и мы охотно обменяем плоды на Почетный знак Зандалара. Если ты не знаешь, где достать знаки, поговори с Винчаксой. Приступим к обмену?','Вернитесь к Рин\'вошо Торговцу в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экстракт манго',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Честная сделка, мой друг - пожалуйста, насладитесь сочными фруктами Южных морей с благословения племени.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, из которых можно изготовить могучий экстракт, растут на островах Южных морей. Одно-единственное манго придает и физические и душевные силы тому, кто его съест. Тебе когда-нибудь приходилось пробовать манго? Если нет, то ты много потерял!$B$BУ нас есть запасы манго, и мы охотно обменяем плоды на Почетный знак Зандалара. Если ты не знаешь, где достать знаки, поговори с Винчаксой. Приступим к обмену?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рин\'вошо Торговцу в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8201,'Коллекция голов','Это правда. Хаккар теперь обитает в Зул\'Гурубе, питаясь силой наших богов. Порабощенные им жрецы направляют энергию самых священных божеств Свежевателю Душ, и скоро сильнее его в Азероте не будет существа. Его надо остановить!$B$BВозьми этот священный шнур. Нанижи на него головы верховных жрецов, по вине которых сила наших богов утекает к Хаккару.$B$BСделав это, возвращайся ко мне.','Соберите ожерелье из голов пятерых жрецов и вернитесь с ним к Экзалу на остров Йоджамба.','Вот это ожерелье! Тебе удалось остановить хищение силы наших богов и ослабить Хаккара!$B$BТы $Gсовершил:совершила; настоящий подвиг, $N. Пусть головы этих презренных троллей продолжают умолять тебя о пощаде – даже после того, как в них остынет кровь.','Ты уже $Gоткрутил:открутила; жрецам головы, $N? Мы должны остановить Хаккара, пока он не набрался сил!','Вернитесь к Экзалу на Гибельный берег, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коллекция голов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это правда. Хаккар теперь обитает в Зул\'Гурубе, питаясь силой наших богов. Порабощенные им жрецы направляют энергию самых священных божеств Свежевателю Душ, и скоро сильнее его в Азероте не будет существа. Его надо остановить!$B$BВозьми этот священный шнур. Нанижи на него головы верховных жрецов, по вине которых сила наших богов утекает к Хаккару.$B$BСделав это, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите ожерелье из голов пятерых жрецов и вернитесь с ним к Экзалу на остров Йоджамба.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это ожерелье! Тебе удалось остановить хищение силы наших богов и ослабить Хаккара!$B$BТы $Gсовершил:совершила; настоящий подвиг, $N. Пусть головы этих презренных троллей продолжают умолять тебя о пощаде – даже после того, как в них остынет кровь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gоткрутил:открутила; жрецам головы, $N? Мы должны остановить Хаккара, пока он не набрался сил!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Экзалу на Гибельный берег, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8221,'*Жжж*$B$BОпознание рыбы-ангела Кифэра завершено.$B$BВы можете получить награду.$B$B*Щелк-щелк**Бзззз*','<ЖЖЖ><Щелк>$B$BЯ разыскиваю редкие сорта рыбы по поручению рыбака Синежаброго. Если вы принесете мне рыбу-ангела Кифэра, то получите награду.$B$B<Щелк><Жжж>','Вернитесь к Рыбоботу 5000 в Тернистую долину.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Жжж*$B$BОпознание рыбы-ангела Кифэра завершено.$B$BВы можете получить награду.$B$B*Щелк-щелк**Бзззз*',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<ЖЖЖ><Щелк>$B$BЯ разыскиваю редкие сорта рыбы по поручению рыбака Синежаброго. Если вы принесете мне рыбу-ангела Кифэра, то получите награду.$B$B<Щелк><Жжж>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рыбоботу 5000 в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8222,'Светящаяся кровь скорпида','Отличная работа, $N! Большое спасибо! Я сделаю краску из этой крови и превращу дешёвое барахло в настоящее сокровище!$B$BВот твои купоны!','За все время, что я работаю на ярмарке, я усвоил множество истин. Поделюсь полезным знанием: публика обожает блестящие безделушки! Это может быть что угодно – возьми, скажем, ножку от стула и покрась ее золотой краской. За эту штуковину будет драться детвора со всей округи!$B$BИтак, $N, мне нужна светящаяся кровь скорпида. Скорпидов можно найти в Силитусе, Выжженных землях или Пылающих степях.','Вернитесь к Эббу Ниблгиру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Светящаяся кровь скорпида',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N! Большое спасибо! Я сделаю краску из этой крови и превращу дешёвое барахло в настоящее сокровище!$B$BВот твои купоны!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','За все время, что я работаю на ярмарке, я усвоил множество истин. Поделюсь полезным знанием: публика обожает блестящие безделушки! Это может быть что угодно – возьми, скажем, ножку от стула и покрась ее золотой краской. За эту штуковину будет драться детвора со всей округи!$B$BИтак, $N, мне нужна светящаяся кровь скорпида. Скорпидов можно найти в Силитусе, Выжженных землях или Пылающих степях.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эббу Ниблгиру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8223,'Обмен: светящаяся кровь скорпида','Еще раз спасибо, $N. Вот ваши купоны!','А знаешь, $N, кровь скорпидов – отличное средство! Удивительно, как с помощью блесток можно любой мусор превратить в изысканную поделку. Клиентам полюбились безделушки, а любовь правит миром, так ведь?$B$BТвоя помощь неоценима, $N. Если вдруг ты раздобудешь еще светящейся крови скорпида, принеси ее мне, и я дам тебе ярмарочные купоны!','Вернитесь к Эббу Ниблгиру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обмен: светящаяся кровь скорпида',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще раз спасибо, $N. Вот ваши купоны!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А знаешь, $N, кровь скорпидов – отличное средство! Удивительно, как с помощью блесток можно любой мусор превратить в изысканную поделку. Клиентам полюбились безделушки, а любовь правит миром, так ведь?$B$BТвоя помощь неоценима, $N. Если вдруг ты раздобудешь еще светящейся крови скорпида, принеси ее мне, и я дам тебе ярмарочные купоны!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эббу Ниблгиру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8224,'Редкая рыба – дезийская ставрида','*Жжж*$B$BОпознание дезийской ставриды завершено.$B$BВы можете получить награду.$B$B*Щелк-щелк**Бзззз*','<ЖЖЖ><Щелк>$B$BЯ разыскиваю редкие сорта рыбы по поручению рыбака Синежаброго. Если вы принесете мне дезийскую ставриду, то получите награду.$B$B<Щелк><Жжж>','Вернитесь к Рыбоботу 5000 в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Редкая рыба – дезийская ставрида',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Жжж*$B$BОпознание дезийской ставриды завершено.$B$BВы можете получить награду.$B$B*Щелк-щелк**Бзззз*',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<ЖЖЖ><Щелк>$B$BЯ разыскиваю редкие сорта рыбы по поручению рыбака Синежаброго. Если вы принесете мне дезийскую ставриду, то получите награду.$B$B<Щелк><Жжж>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рыбоботу 5000 в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8225,'Редкая рыба – синий полосатик Браунелла','*Жжж*$B$BОпознание синего полосатика Браунелла завершено.$B$BВы можете получить награду.$B$B*Щелк-щелк**Бзззз*','<ЖЖЖ><Щелк>$B$BЯ разыскиваю редкие сорта рыбы по поручению рыбака Синежаброго. Если вы принесете мне синего полосатика Браунелла, то получите награду..$B$B<Щелк><Жжж>','Вернитесь к Рыбоботу 5000 в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Редкая рыба – синий полосатик Браунелла',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Жжж*$B$BОпознание синего полосатика Браунелла завершено.$B$BВы можете получить награду.$B$B*Щелк-щелк**Бзззз*',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<ЖЖЖ><Щелк>$B$BЯ разыскиваю редкие сорта рыбы по поручению рыбака Синежаброго. Если вы принесете мне синего полосатика Браунелла, то получите награду..$B$B<Щелк><Жжж>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рыбоботу 5000 в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8226,'Редкая рыба – бледная упырыба','Вернитесь к Рыбоботу 5000 в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Редкая рыба – бледная упырыба',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рыбоботу 5000 в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8227,'Измерительная лента Ната','Среди разбросанных рыболовных инструментов лежит свернутая шелковая измерительная лента. К ней прицеплена бирка с надписью:$B$B"Нат Пэгл, Пылевые топи".','Верните измерительную ленту Нату Пэглу. Найти Пэгла можно в Пылевых топях.','О, тебе удалось отыскать мою измерительную ленту? Она мне очень дорога! Именно ею я измерял самых больших рыб, которых мне удавалось поймать...$B$BНо ведь я потерял свою ленту в Зул\'Гурубе... Ты там был? Может быть, ты видел этого самого Газ\'ранку, о котором рассказывают басни?$B$BЧто ж... может быть, ты хочешь его поймать?','Привет, $Gдорогой:дорогая;. Ты здесь чтобы порыбачить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Измерительная лента Ната',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среди разбросанных рыболовных инструментов лежит свернутая шелковая измерительная лента. К ней прицеплена бирка с надписью:$B$B"Нат Пэгл, Пылевые топи".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните измерительную ленту Нату Пэглу. Найти Пэгла можно в Пылевых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, тебе удалось отыскать мою измерительную ленту? Она мне очень дорога! Именно ею я измерял самых больших рыб, которых мне удавалось поймать...$B$BНо ведь я потерял свою ленту в Зул\'Гурубе... Ты там был? Может быть, ты видел этого самого Газ\'ранку, о котором рассказывают басни?$B$BЧто ж... может быть, ты хочешь его поймать?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $Gдорогой:дорогая;. Ты здесь чтобы порыбачить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8228,'Приглашение на рыбалку','В воскресенье в Пиратской Бухте будет рыбный конкурс! Вот правила!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приглашение на рыбалку',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В воскресенье в Пиратской Бухте будет рыбный конкурс! Вот правила!',`offerrewardtext_loc8`);
