INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8230,'Пробное задание Коллина') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробное задание Коллина',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8231,'Охота на волношлепа','Волношлеп – земноводное, встречающееся только в Азшаре. Эти твари сильны и очень живучи. $b$bВ их твердой блестящей чешуе, как в зеркале, отражается мастерство охотника. $b$bВыследи и убей нескольких на побережье Азшары и принеси мне их чешую.','Принесите 6 чешуй волношлепа Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.','Волношлепы – не самые слабые противники, особенно если пытаться биться с ними в воде – их естественной среде обитания. Ты $Gдоказал:доказала; что можешь справиться с очень опасной добычей.','Добились ли вы успеха?','Вернитесь к Огтинку на Разоренное побережье, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на волношлепа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волношлеп – земноводное, встречающееся только в Азшаре. Эти твари сильны и очень живучи. $b$bВ их твердой блестящей чешуе, как в зеркале, отражается мастерство охотника. $b$bВыследи и убей нескольких на побережье Азшары и принеси мне их чешую.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 чешуй волношлепа Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Волношлепы – не самые слабые противники, особенно если пытаться биться с ними в воде – их естественной среде обитания. Ты $Gдоказал:доказала; что можешь справиться с очень опасной добычей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добились ли вы успеха?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Огтинку на Разоренное побережье, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8232,'Зеленый дракон','Ты отправляешься на опасную охоту, |3-6($r). Убей зеленого дракона Морфаза и принеси мне его зуб. Морфаз обитает в Храме Атал\'Хаккара. Вход в него ты найдешь на Болоте Печали. $b$bНо помни, $gодному:одной; тебе его не осилить. У дракона много врагов – найди соратников и уничтожь его! $b$bМногие, очень многие не прочь добыть зуб этой твари. Принеси его мне, и я достойно награжу тебя.','Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.','Ты $Gпоказал:показала; себя $Gвеликим:великой; $Gвоителем:воительницей;, $N. Прими этот дар, я храню его с давних лет, когда сам был охотником.','Я вижу на твоем челе печать невзгод, $N. Тебе удалось убить дракона?','Вернитесь к Огтинку на Разоренное побережье, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зеленый дракон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отправляешься на опасную охоту, |3-6($r). Убей зеленого дракона Морфаза и принеси мне его зуб. Морфаз обитает в Храме Атал\'Хаккара. Вход в него ты найдешь на Болоте Печали. $b$bНо помни, $gодному:одной; тебе его не осилить. У дракона много врагов – найди соратников и уничтожь его! $b$bМногие, очень многие не прочь добыть зуб этой твари. Принеси его мне, и я достойно награжу тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите зуб Морфаза Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпоказал:показала; себя $Gвеликим:великой; $Gвоителем:воительницей;, $N. Прими этот дар, я храню его с давних лет, когда сам был охотником.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я вижу на твоем челе печать невзгод, $N. Тебе удалось убить дракона?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Огтинку на Разоренное побережье, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8233,'Приглашение','Лорд Джорах Черный Ворон настоятельно приглашает вас к себе. Приглашение тайное, поэтому никаких подробностей.$b$bПоместье Черный Ворон находится в предгорьях Хилсбрада – горная тропа начинается на северо-западе от крепости Дарнхольд.','Поговорите с лордом Джорахом Черным Вороном в его поместье.','Добро пожаловать! Прошу вас, $N, присаживайтесь. Я хочу обсудить с вами одно простое дельце.$B$BВидите ли, недавно я лишился кое-чего очень ценного, и, прямо говоря, хочу вернуть его любой ценой. Это дело и для вас выгодное, да, очень выгодное.$B$BЧто скажете, $N? Вы же любите приключения?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приглашение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лорд Джорах Черный Ворон настоятельно приглашает вас к себе. Приглашение тайное, поэтому никаких подробностей.$b$bПоместье Черный Ворон находится в предгорьях Хилсбрада – горная тропа начинается на северо-западе от крепости Дарнхольд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с лордом Джорахом Черным Вороном в его поместье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать! Прошу вас, $N, присаживайтесь. Я хочу обсудить с вами одно простое дельце.$B$BВидите ли, недавно я лишился кое-чего очень ценного, и, прямо говоря, хочу вернуть его любой ценой. Это дело и для вас выгодное, да, очень выгодное.$B$BЧто скажете, $N? Вы же любите приключения?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8234,'Запечатанная лазурная сумка','Начнем сначала. Я потерял небольшую сумку голубого цвета. В ней были мои личные вещи. $b$bНет нужды искать воров – они уже мертвы. Мне известно лишь, что эти дураки не сумели открыть сумку и продали ее какому-то шаману из племени Древобрюхов в Азшаре, выдав ее за священную реликвию. Очень умно. $b$bЯ хочу, чтобы ты $gотправился:отправилась; в Азшару и $gзаполучил:заполучила; у шамана мою сумку – хитростью или силой. Полагаю, что лучше все же хитростью. Сумку отнеси верховному магу Ксилему.','Добудьте запечатанную лазурную сумку у шамана из племени Древобрюхов в Азшаре. Затем отнесите сумку верховному магу Ксилему в Азшаре.','Вижу, у тебя сумка лорда Черного Ворона. Что ж ты сразу не $Gсказал:сказала;, $Gсынок:дочка;?','Мы знакомы?','Вернитесь к верховному магу Ксилему в Медвежий угол, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запечатанная лазурная сумка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Начнем сначала. Я потерял небольшую сумку голубого цвета. В ней были мои личные вещи. $b$bНет нужды искать воров – они уже мертвы. Мне известно лишь, что эти дураки не сумели открыть сумку и продали ее какому-то шаману из племени Древобрюхов в Азшаре, выдав ее за священную реликвию. Очень умно. $b$bЯ хочу, чтобы ты $gотправился:отправилась; в Азшару и $gзаполучил:заполучила; у шамана мою сумку – хитростью или силой. Полагаю, что лучше все же хитростью. Сумку отнеси верховному магу Ксилему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте запечатанную лазурную сумку у шамана из племени Древобрюхов в Азшаре. Затем отнесите сумку верховному магу Ксилему в Азшаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, у тебя сумка лорда Черного Ворона. Что ж ты сразу не $Gсказал:сказала;, $Gсынок:дочка;?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы знакомы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Ксилему в Медвежий угол, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8235,'Зашифрованные фрагменты','Лорд Черный Ворон просил нас с тобой об услуге. Он желает снять заклятие с этой сумки. $B$BК сожалению, мои книги по снятию чар были захвачены и уничтожены дикарями. Каждый клочок, оставшийся от них, невероятно ценен для меня. $B$BЕсли ты сможешь принести мне зашифрованные фрагменты, я попробую восстановить хотя бы часть моих книг. Чтобы найти фрагменты, поохоться на обитающих в Азшаре зверей – они обычно подбирают все, что плохо лежит.','Принесите 10 зашифрованных фрагментов верховному магу Ксилему в Азшару.','Похоже, тебе удалось найти весьма ценные фрагменты. Не так уж ты и $Gбесполезен:бесполезена;, в конце концов.','Ты $Gпринес:принесла; мне фрагменты? Я должен как можно скорее приступить к работе.','Вернитесь к верховному магу Ксилему в Медвежий угол, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зашифрованные фрагменты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лорд Черный Ворон просил нас с тобой об услуге. Он желает снять заклятие с этой сумки. $B$BК сожалению, мои книги по снятию чар были захвачены и уничтожены дикарями. Каждый клочок, оставшийся от них, невероятно ценен для меня. $B$BЕсли ты сможешь принести мне зашифрованные фрагменты, я попробую восстановить хотя бы часть моих книг. Чтобы найти фрагменты, поохоться на обитающих в Азшаре зверей – они обычно подбирают все, что плохо лежит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 зашифрованных фрагментов верховному магу Ксилему в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, тебе удалось найти весьма ценные фрагменты. Не так уж ты и $Gбесполезен:бесполезена;, в конце концов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне фрагменты? Я должен как можно скорее приступить к работе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Ксилему в Медвежий угол, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8236,'Лазурный ключ','Мне потребуется время, чтобы расшифровать фрагменты и снять заклятие. Когда я закончу, то самолично доставлю сумку лорду Черному Ворону. $b$bОднако нам все еще нужен ключ. Говорят, что ключ присвоил зеленый дракон по имени Морфаз. Его логово находится в глубинах Храма Атал\'Хаккара – вход в него ты найдешь на Болоте Печали. $b$bСобери своих сподвижников и отправляйся к логову дракона. Лорд Черный Ворон ждет, когда ты принесешь ему ключ.','Принесите лазурный ключ лорду Черному Ворону.','Ключ! Я уже думал, что он потерян навеки! Прошу тебя, возьми что-то из зачарованной одежды из моих запасов. Она предназначена для особо искусных разбойников. Пусть все знают, что с тобой шутки плохи!$B$B*Джорах раскрывает сумку, и из нее вырывается золотое сияние. Джорах с изумлением смотрит внутрь...*','Верховный маг Ксилем уже прислал мне сумку. Ты $Gпринес:принесла; ключ?','Вернитесь к лорду Джораху Черному Ворону в Поместье Черного Ворона, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лазурный ключ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне потребуется время, чтобы расшифровать фрагменты и снять заклятие. Когда я закончу, то самолично доставлю сумку лорду Черному Ворону. $b$bОднако нам все еще нужен ключ. Говорят, что ключ присвоил зеленый дракон по имени Морфаз. Его логово находится в глубинах Храма Атал\'Хаккара – вход в него ты найдешь на Болоте Печали. $b$bСобери своих сподвижников и отправляйся к логову дракона. Лорд Черный Ворон ждет, когда ты принесешь ему ключ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите лазурный ключ лорду Черному Ворону.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ключ! Я уже думал, что он потерян навеки! Прошу тебя, возьми что-то из зачарованной одежды из моих запасов. Она предназначена для особо искусных разбойников. Пусть все знают, что с тобой шутки плохи!$B$B*Джорах раскрывает сумку, и из нее вырывается золотое сияние. Джорах с изумлением смотрит внутрь...*',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Верховный маг Ксилем уже прислал мне сумку. Ты $Gпринес:принесла; ключ?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Джораху Черному Ворону в Поместье Черного Ворона, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8237,'REUSE') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REUSE',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8238,'Монеты племен: Гурубаши, Порочная Ветвь и Сухокожие','Отлично – эти монеты прекрасно дополнят в мою коллекцию... Они нужны племени, чтобы помешать возрождению Кровавого бога. Этот почетный знак – твой по праву, $N, прими его вместе с нашей благодарностью!','Я ищу Знаки Силы, известные как Монеты Племен. Это валюта, используемая различными обитателями Зул\'Гуруба, и каждый из них наделен тонким, но могущественным моджо.$B$BМожно найти девять различных видов. Если у тебя есть лишние, я обменяю один из наших жетонов чести на набор из трех. Вы можете использовать Жетоны с Торговцем Рин\'вошо; он предлагает нашим героям специальные предметы за них.','Вернитесь к Винчаксе в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Монеты племен: Гурубаши, Порочная Ветвь и Сухокожие',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично – эти монеты прекрасно дополнят в мою коллекцию... Они нужны племени, чтобы помешать возрождению Кровавого бога. Этот почетный знак – твой по праву, $N, прими его вместе с нашей благодарностью!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я ищу Знаки Силы, известные как Монеты Племен. Это валюта, используемая различными обитателями Зул\'Гуруба, и каждый из них наделен тонким, но могущественным моджо.$B$BМожно найти девять различных видов. Если у тебя есть лишние, я обменяю один из наших жетонов чести на набор из трех. Вы можете использовать Жетоны с Торговцем Рин\'вошо; он предлагает нашим героям специальные предметы за них.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Винчаксе в Тернистую долину.',`completedtext_loc8`);
