INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8240,'Драгоценности для Занзы','Драгоценности Хаккари необходимо уничтожить. Это наше внутреннее дело, но оно настолько важное, что мы просим о помощи и чужеземцев.$B$BОтыщи в Зул\'Гурубе все драгоценности, которые сможешь, принеси на Алтарь Занзы и уничтожь их. Если ты справишься с этим заданием, я дам тебе почетный знак нашего племени. Знай, что у нас этими знаками не разбрасываются!$B$BСтупай, и да пребудет с тобой благословение Занзы!','Найдите в Зул\'Гурубе драгоценности Хаккари и уничтожьте их на Алтаре Занзы на острове Йоджамба. Поговорите с Винчаксой.','Отлично... Каждая драгоценность, которую удалось отнять у прислужников Кровавого бога – еще один шаг к тому, чтобы покончить с ними навечно. Ты $Gоказал:оказала; племени неоценимую услугу, и племя этого не забудет.$B$BПомни, что найденные драгоценности нужно уничтожить на Алтаре Занзы. За уничтожение каждой драгоценности ты получишь почетный знак племени! Для хранения почетных знаков тебе потребуется свободное место в сумках.','Уничтожь драгоценности на Алтаре Занзы! Сделай это, и Занза благословит тебя дважды!','Вернитесь к Винчаксе на остров Йоджамба, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Драгоценности для Занзы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Драгоценности Хаккари необходимо уничтожить. Это наше внутреннее дело, но оно настолько важное, что мы просим о помощи и чужеземцев.$B$BОтыщи в Зул\'Гурубе все драгоценности, которые сможешь, принеси на Алтарь Занзы и уничтожь их. Если ты справишься с этим заданием, я дам тебе почетный знак нашего племени. Знай, что у нас этими знаками не разбрасываются!$B$BСтупай, и да пребудет с тобой благословение Занзы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Зул\'Гурубе драгоценности Хаккари и уничтожьте их на Алтаре Занзы на острове Йоджамба. Поговорите с Винчаксой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично... Каждая драгоценность, которую удалось отнять у прислужников Кровавого бога – еще один шаг к тому, чтобы покончить с ними навечно. Ты $Gоказал:оказала; племени неоценимую услугу, и племя этого не забудет.$B$BПомни, что найденные драгоценности нужно уничтожить на Алтаре Занзы. За уничтожение каждой драгоценности ты получишь почетный знак племени! Для хранения почетных знаков тебе потребуется свободное место в сумках.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уничтожь драгоценности на Алтаре Занзы! Сделай это, и Занза благословит тебя дважды!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Винчаксе на остров Йоджамба, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8241,'Пополнение запасов огненного плавня – железо','Плавень в кузне лишним не бывает, поверь моему слову... Неси сколько можешь, пока не скажу – хватит.','Не будем тратить драгоценное время на ерунду, $N. Пора пополнить запасы огненного плавня – они уже совсем на исходе.$B$BВот что мне от тебя нужно:$BЧешуя пламезавра$BЖелезные слитки$BУголь.$B$BМне нужно все, что ты сможешь предложить! И поторопись, если хочешь угодить Братству.','Вернитесь к мастеру-кузнецу Закалону в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пополнение запасов огненного плавня – железо',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Плавень в кузне лишним не бывает, поверь моему слову... Неси сколько можешь, пока не скажу – хватит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не будем тратить драгоценное время на ерунду, $N. Пора пополнить запасы огненного плавня – они уже совсем на исходе.$B$BВот что мне от тебя нужно:$BЧешуя пламезавра$BЖелезные слитки$BУголь.$B$BМне нужно все, что ты сможешь предложить! И поторопись, если хочешь угодить Братству.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру-кузнецу Закалону в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8242,'Пополнение запасов огненного плавня – толстая кожа','Плавень в кузне лишним не бывает, поверь моему слову... Неси сколько можешь, пока не скажу – хватит.','Не будем тратить драгоценное время на ерунду, $R. Пора пополнить запасы огненного плавня – они уже совсем на исходе.$B$BВот что мне от тебя нужно:$BЧешуя пламезавра$BТяжелая кожа$BУголь.$B$BМне нужно все, что ты сможешь предложить! И поторопись, если хочешь угодить Братству.','Вернитесь к мастеру-кузнецу Закалону в Тлеющее ущелье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пополнение запасов огненного плавня – толстая кожа',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Плавень в кузне лишним не бывает, поверь моему слову... Неси сколько можешь, пока не скажу – хватит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не будем тратить драгоценное время на ерунду, $R. Пора пополнить запасы огненного плавня – они уже совсем на исходе.$B$BВот что мне от тебя нужно:$BЧешуя пламезавра$BТяжелая кожа$BУголь.$B$BМне нужно все, что ты сможешь предложить! И поторопись, если хочешь угодить Братству.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру-кузнецу Закалону в Тлеющее ущелье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8243,'Напиток могущества Занзы','Дай мне знать, когда будешь $Gготов:готова; к обмену.','С вашим повышением статуса среди племени вы получите доступ к некоторым из наших наиболее полезных напитков. Вот... эти отвары сильны в моджо - благословлены Занзой и подходят для искателей приключений из всех слоев общества!$B$BЯ позволю вам выбрать одно из трех, которые я предлагаю; взамен мне нужен один жетон чести зандалара. Обратите внимание, что в любой момент времени в вашем духе могут действовать только эффекты одного из них.$B$BДайте мне знать, когда будете готовы к обмену!','Вернитесь к Рин\'вошо Торговцу в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Напиток могущества Занзы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дай мне знать, когда будешь $Gготов:готова; к обмену.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С вашим повышением статуса среди племени вы получите доступ к некоторым из наших наиболее полезных напитков. Вот... эти отвары сильны в моджо - благословлены Занзой и подходят для искателей приключений из всех слоев общества!$B$BЯ позволю вам выбрать одно из трех, которые я предлагаю; взамен мне нужен один жетон чести зандалара. Обратите внимание, что в любой момент времени в вашем духе могут действовать только эффекты одного из них.$B$BДайте мне знать, когда будете готовы к обмену!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рин\'вошо Торговцу в Тернистую долину.',`completedtext_loc8`);
