INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8246,'Перстни Зандалара','Честная сделка, мой друг - пожалуйста, прими эту печатку с благословения племени.','Для друзей нашего племени, $N, у меня есть особый подарок прямо из нашего дома в Южных морях... Перстни Зандалара! Они усиливают любые наплечники и влияют на силу нападения или заклинаний.$B$BВ обмен на каждое кольцо мне нужно 15 почетных знаков Зандалара.','Вернитесь к Рин\'вошо Торговцу в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перстни Зандалара',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Честная сделка, мой друг - пожалуйста, прими эту печатку с благословения племени.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Для друзей нашего племени, $N, у меня есть особый подарок прямо из нашего дома в Южных морях... Перстни Зандалара! Они усиливают любые наплечники и влияют на силу нападения или заклинаний.$B$BВ обмен на каждое кольцо мне нужно 15 почетных знаков Зандалара.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рин\'вошо Торговцу в Тернистую долину.',`completedtext_loc8`);
