INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8248,'<UNUSED>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8249,'Принести ларцы','Да найдется место для твоих клинков в чьем-нибудь сердце.$B$BВ прямом смысле.','Моим разбойникам необходимо потренироваться во взломе замков, и мне нужны соответствующие замки. Зан делает такие, что они только зеленым новичкам годятся.$B$BВот что, принеси-ка мне 5 тяжелых ларцов, а я замолвлю за тебя словечко кому надо.$B$BТы можешь отпереть ларцы и порыться в них, но оставь там хотя бы несколько монеток... даже разбойнику-ученику нужна мотивация.','Вернитесь к Фараду в Альтеракские горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Принести ларцы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да найдется место для твоих клинков в чьем-нибудь сердце.$B$BВ прямом смысле.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Моим разбойникам необходимо потренироваться во взломе замков, и мне нужны соответствующие замки. Зан делает такие, что они только зеленым новичкам годятся.$B$BВот что, принеси-ка мне 5 тяжелых ларцов, а я замолвлю за тебя словечко кому надо.$B$BТы можешь отпереть ларцы и порыться в них, но оставь там хотя бы несколько монеток... даже разбойнику-ученику нужна мотивация.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фараду в Альтеракские горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8250,'Магическое искусство','Верховный маг Ксилем ищет кого-то... Не менее опытного, чем ты.$b$bЕсли хочешь, поговори с ним. Он живет в Азшаре, в башне на вершине утеса. Добраться туда можно лишь при помощи заклинания, которое известно его заносчивому слуге, Санату Лим-Йо.$b$bСанат живет в лагере ниже башни своего хозяина. Найти его можно так: там, где главная дорога Азшары разветвляется у входа в руины Эльдарата, поворачивай строго на север и иди, пока не упрешься в скалы.','Найдите Саната Лим-Йо и добейтесь, чтобы он доставил вас к верховному магу Ксилему.','*Санат смотрит на вас с презрением.*$B$BВерховный маг Ксилем ждет тебя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магическое искусство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный маг Ксилем ищет кого-то... Не менее опытного, чем ты.$b$bЕсли хочешь, поговори с ним. Он живет в Азшаре, в башне на вершине утеса. Добраться туда можно лишь при помощи заклинания, которое известно его заносчивому слуге, Санату Лим-Йо.$b$bСанат живет в лагере ниже башни своего хозяина. Найти его можно так: там, где главная дорога Азшары разветвляется у входа в руины Эльдарата, поворачивай строго на север и иди, пока не упрешься в скалы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Саната Лим-Йо и добейтесь, чтобы он доставил вас к верховному магу Ксилему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Санат смотрит на вас с презрением.*$B$BВерховный маг Ксилем ждет тебя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8251,'Волшебная пыль','Эльфы крови в Азшаре изобрели свой способ распылять магические предметы. Получаемая в результате сияющая пыль отличается от элементов, получаемых в результате обычного распыления.$b$bЯ отправил ученика купить этой пыли, но эльфы безжалостно убили его. Они должны заплатить за это! $b$bВремя мирных переговоров прошло, $n. Найди эльфов крови в скалах Азшары и примени к ним более... убедительные методы. Мне нужна эта пыль.','Принесите 10 горстей сияющей пыли верховному магу Ксилему.','Молодец, $N! Меня не перестает удивлять, насколько убедительным может быть залп магических снарядов.','У тебя есть пыль?','Вернитесь к верховному магу Ксилему в Теснину Зловещего Шепота, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебная пыль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эльфы крови в Азшаре изобрели свой способ распылять магические предметы. Получаемая в результате сияющая пыль отличается от элементов, получаемых в результате обычного распыления.$b$bЯ отправил ученика купить этой пыли, но эльфы безжалостно убили его. Они должны заплатить за это! $b$bВремя мирных переговоров прошло, $n. Найди эльфов крови в скалах Азшары и примени к ним более... убедительные методы. Мне нужна эта пыль.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 горстей сияющей пыли верховному магу Ксилему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $N! Меня не перестает удивлять, насколько убедительным может быть залп магических снарядов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть пыль?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Ксилему в Теснину Зловещего Шепота, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8252,'Кораллы сирен','Оглянись вокруг. Развалины и все побережье кишат тварями Бича Злобы. Проклятые создания научились искать редкие вещества и предметы, встречающиеся в Азшаре. $b$bНапример, эти твари почему-то очень интересуются заколдованными кораллами – по совершенно не ясным мне причинам. Теперь этих кораллов в бухте почти не осталось, а они так нужны мне для исследований! Прошу тебя, отбери несколько кораллов у сирен из клана Бича Злобы и принеси их мне.','Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему.','Это великолепный образец коралла, $N. Ваши навыки, несомненно, точны и смертоносны.$B$BНе думайте, что ваши усилия остались незамеченными. Возможно, вы достойны настоящей проверки своего мастерства...','Сирены из плевелашей - удивительно искусные маги. Надеюсь, не так искусен, как ты?','Вернитесь к верховному магу Ксилему в Теснину Зловещего Шепота, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кораллы сирен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оглянись вокруг. Развалины и все побережье кишат тварями Бича Злобы. Проклятые создания научились искать редкие вещества и предметы, встречающиеся в Азшаре. $b$bНапример, эти твари почему-то очень интересуются заколдованными кораллами – по совершенно не ясным мне причинам. Теперь этих кораллов в бухте почти не осталось, а они так нужны мне для исследований! Прошу тебя, отбери несколько кораллов у сирен из клана Бича Злобы и принеси их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 заколдованных кораллов и принесите их верховному магу Ксилему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это великолепный образец коралла, $N. Ваши навыки, несомненно, точны и смертоносны.$B$BНе думайте, что ваши усилия остались незамеченными. Возможно, вы достойны настоящей проверки своего мастерства...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сирены из плевелашей - удивительно искусные маги. Надеюсь, не так искусен, как ты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Ксилему в Теснину Зловещего Шепота, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8253,'Уничтожить Морфаза','В глубинах Храма Атал\'Хаккара скрывается зеленой дракон по имени Морфаз. $b$bМного лет назад он напал на меня из засады и проглотил целиком сопровождавшего меня ученика. Мне не впервой терять учеников, однако именно этот, проглоченный, нес кристалл тайной магии небывалой мощи. $b$bВыбери достаточно сильных соратников и отправляйся в Затонувший храм. Уничтожь Морфаза и принеси мне мой кристалл.','Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.','Невероятно. Осколок вырос, поглощая энергию дракона за долгие годы.$B$BЯ больше не могу вас просить. С этим осколком вернулась моя способность сотворять. Мое первое творение твое, $N, и тебе остается только выбирать...','Ты $Gубил:убила; моего старого врага?','Вернитесь к верховному магу Ксилему в Медвежий угол, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить Морфаза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В глубинах Храма Атал\'Хаккара скрывается зеленой дракон по имени Морфаз. $b$bМного лет назад он напал на меня из засады и проглотил целиком сопровождавшего меня ученика. Мне не впервой терять учеников, однако именно этот, проглоченный, нес кристалл тайной магии небывалой мощи. $b$bВыбери достаточно сильных соратников и отправляйся в Затонувший храм. Уничтожь Морфаза и принеси мне мой кристалл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте кристалл тайной магии из брюха Морфаза и принесите его верховному магу Ксилему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно. Осколок вырос, поглощая энергию дракона за долгие годы.$B$BЯ больше не могу вас просить. С этим осколком вернулась моя способность сотворять. Мое первое творение твое, $N, и тебе остается только выбирать...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gубил:убила; моего старого врага?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Ксилему в Медвежий угол, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8254,'Помощь Кенарию','Служителям богов пристало помогать попавшим в беду. Как именно – неважно, главное – во имя чего.$b$bКругу Кенария необходима помощь. Если ты хочешь протянуть им руку помощи, поговори с Огтинком. Он живет на вершинах скал на северо-востоке от руин Эльдарата в Азшаре.','Отыщи Огтинка в Азшаре.','Я очень рад твоему приходу. У меня словно камень с души свалился. Нам предстоит очень много дел.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Кенарию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Служителям богов пристало помогать попавшим в беду. Как именно – неважно, главное – во имя чего.$b$bКругу Кенария необходима помощь. Если ты хочешь протянуть им руку помощи, поговори с Огтинком. Он живет на вершинах скал на северо-востоке от руин Эльдарата в Азшаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщи Огтинка в Азшаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я очень рад твоему приходу. У меня словно камень с души свалился. Нам предстоит очень много дел.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8255,'Охота на беговых оленей','Мохноногие олени, обитающие в Азшаре, – самые великолепные создания, когда-либо населявшие Оскверненный лес. Они наделены естественной невосприимчивостью ко всем болезням и ядам, поэтому порча не коснулась их. Мудрые животные предпочли покинуть зараженные земли. $b$bК прискорбию своему я должен просить тебя поохотиться на этих прекрасных созданий, поскольку их железы необходимы для изготовления целительного снадобья. Снадобья, которое вернет Оскверненному лесу его прежний облик.','Добудьте 4 железы здорового мохоногого оленя и принесите их Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.','Сама судьба привела тебя сюда, $N. Вера твоя не противоречит тому, что должно исполнить для создания снадобья.$B$BВидишь ли, Круг Кенария считает этих беговых оленей священными животными, убийство которых невозможно ни при каких обстоятельствах. Если бы им пришлось это сделать, это сильно подорвало бы их дух.','Ты $Gвернулся:вернулась;. Надеюсь, удача улыбнулась тебе?','Вернитесь к Огтинку на Разоренное побережье, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на беговых оленей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мохноногие олени, обитающие в Азшаре, – самые великолепные создания, когда-либо населявшие Оскверненный лес. Они наделены естественной невосприимчивостью ко всем болезням и ядам, поэтому порча не коснулась их. Мудрые животные предпочли покинуть зараженные земли. $b$bК прискорбию своему я должен просить тебя поохотиться на этих прекрасных созданий, поскольку их железы необходимы для изготовления целительного снадобья. Снадобья, которое вернет Оскверненному лесу его прежний облик.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 4 железы здорового мохоногого оленя и принесите их Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сама судьба привела тебя сюда, $N. Вера твоя не противоречит тому, что должно исполнить для создания снадобья.$B$BВидишь ли, Круг Кенария считает этих беговых оленей священными животными, убийство которых невозможно ни при каких обстоятельствах. Если бы им пришлось это сделать, это сильно подорвало бы их дух.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;. Надеюсь, удача улыбнулась тебе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Огтинку на Разоренное побережье, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8256,'Лимфа нежити','Чтобы получить целительное снадобье, воспользуемся простым рецептом: смешаем одну часть яда с двумя благотворными субстанциями. Один целительный компонент у нас уже есть, теперь надо добыть яд. $B$BСамые могущественные твари нежити, такие как неупокоенные высокорожденные, скитающиеся по руинам Эльдарата, часто настолько сильно поражены порчей, что она принимает вполне осязаемую форму зеленой слизи. Среди живых эта субстанция известна как лимфа нежити. $b$bЭто очень мощный яд, поэтому потребуется лишь одна мера.','Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.','Да, не самое приятное зрелище... Но, как это не печально, эта мерзкая субстанция необходима для создания целебной мази. Спасибо, $N.','Нам нужна лимфа как можно скорее! Тебе удалось добыть ее?','Вернитесь к Огтинку на Разоренное побережье, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лимфа нежити',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы получить целительное снадобье, воспользуемся простым рецептом: смешаем одну часть яда с двумя благотворными субстанциями. Один целительный компонент у нас уже есть, теперь надо добыть яд. $B$BСамые могущественные твари нежити, такие как неупокоенные высокорожденные, скитающиеся по руинам Эльдарата, часто настолько сильно поражены порчей, что она принимает вполне осязаемую форму зеленой слизи. Среди живых эта субстанция известна как лимфа нежити. $b$bЭто очень мощный яд, поэтому потребуется лишь одна мера.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите лимфу нежити Огтинку в Азшару. Огтинк обитает среди скал в северо-востоку от руин Эльдарата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, не самое приятное зрелище... Но, как это не печально, эта мерзкая субстанция необходима для создания целебной мази. Спасибо, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам нужна лимфа как можно скорее! Тебе удалось добыть ее?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Огтинку на Разоренное побережье, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8257,'Кровь Морфаза','Теперь нам нужен последний целительный компонент. $b$bИзвестно, что зеленый дракон Морфаз наделен невосприимчивостью ко всем болезням и ядам. Это знание досталось дорогой ценой – не один друид погиб, пытаясь справиться с драконом. Уверен, его кровь послужит отличным компонентом для нашего снадобья.$b$bПосланник Круга Кенария заберет уже собранные тобой компоненты, пока ты будешь добывать последний. Собери соратников и отправляйся в логово зеленого дракона в затонувший Храм Атал\'Хаккара. Принеси его кровь Грете Замшелому Копыту в Оскверненный лес.','Убейте Морфаза в затонувшем Храме Атал\'Хаккара и принесите его кровь Грете Замшелому Копыту в Оскверненный лес. Вход в храм сокрыт на Болоте Печали.','Не могу поверить... тебе действительно удалось справиться с драконом и добыть его кровь! Мы немедленно приготовим снадобье и начнем исцеление растений и животных Оскверненного леса. Это займет очень много времени, но теперь мы можем это сделать – и все благодаря тебе!','Ты $Gдобыл:добыла; кровь Морфаза?','Вернитесь к Грете Замшелому Копыту в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь Морфаза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь нам нужен последний целительный компонент. $b$bИзвестно, что зеленый дракон Морфаз наделен невосприимчивостью ко всем болезням и ядам. Это знание досталось дорогой ценой – не один друид погиб, пытаясь справиться с драконом. Уверен, его кровь послужит отличным компонентом для нашего снадобья.$b$bПосланник Круга Кенария заберет уже собранные тобой компоненты, пока ты будешь добывать последний. Собери соратников и отправляйся в логово зеленого дракона в затонувший Храм Атал\'Хаккара. Принеси его кровь Грете Замшелому Копыту в Оскверненный лес.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Морфаза в затонувшем Храме Атал\'Хаккара и принесите его кровь Грете Замшелому Копыту в Оскверненный лес. Вход в храм сокрыт на Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не могу поверить... тебе действительно удалось справиться с драконом и добыть его кровь! Мы немедленно приготовим снадобье и начнем исцеление растений и животных Оскверненного леса. Это займет очень много времени, но теперь мы можем это сделать – и все благодаря тебе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдобыл:добыла; кровь Морфаза?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грете Замшелому Копыту в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8258,'Угроза Темного Губителя','Темный Терзатель, рыцарь смерти, владычествует над Главным cклепом в Некроситете. Он собирается подчинить себе весь мир духов! Его необходимо остановить! Тут-то тебе и понадобится кристальный предсказатель.$b$bПриведи его в действие в Главном склепе, чтобы вызвать духов-приспешников Темного Терзателя. Когда ты одолеешь этих духов, явится сам рыцарь смерти. Принеси мне его голову, $n! Только его гибель способна исправить урон, нанесенный миру духов!','Используйте кристальный предсказатель в Главном склепе в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.$b$bПринесите голову Темного Терзателя Сагорну Гривастому Страннику на Аллею Мудрости Оргриммара.','Это радостная победа, $N! Гибель Темного Похитителя должна восстановить хрупкие оковы, скрепляющие царство духов.$B$BТы $Gпревзошел:превзошла; результаты, о чем вас просили, даже когда вы не имели представления о награде.Прими этот простой подарок моей благодарности.','Время критично, $N - удалось ли тебе остановить угрозу Рыцаря смерти Темного Терзателя?','Вернитесь к Сагорну Гривастому Страннику в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза Темного Губителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Темный Терзатель, рыцарь смерти, владычествует над Главным cклепом в Некроситете. Он собирается подчинить себе весь мир духов! Его необходимо остановить! Тут-то тебе и понадобится кристальный предсказатель.$b$bПриведи его в действие в Главном склепе, чтобы вызвать духов-приспешников Темного Терзателя. Когда ты одолеешь этих духов, явится сам рыцарь смерти. Принеси мне его голову, $n! Только его гибель способна исправить урон, нанесенный миру духов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте кристальный предсказатель в Главном склепе в Некроситете. Сразитесь с духами. Когда появится Темный Терзатель, убейте его.$b$bПринесите голову Темного Терзателя Сагорну Гривастому Страннику на Аллею Мудрости Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это радостная победа, $N! Гибель Темного Похитителя должна восстановить хрупкие оковы, скрепляющие царство духов.$B$BТы $Gпревзошел:превзошла; результаты, о чем вас просили, даже когда вы не имели представления о награде.Прими этот простой подарок моей благодарности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Время критично, $N - удалось ли тебе остановить угрозу Рыцаря смерти Темного Терзателя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сагорну Гривастому Страннику в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8259,'Более достойная награда') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Более достойная награда',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8260,'Полевой комплект Лиги Аратора','Ты определенно $Gначал:начала; показывать нам себя, $N. В награду возьмите эту амуницию! Внутри вы найдете пайки и бинты, которые можно использовать только в Низине Арати.По мере того, как вы продолжаете проявлять себя в Низине, вы обнаружите, что эти предметы станут доступны вам для покупки. Пайки становятся доступными, когда вы дружите с нами, и бинты, когда вас уважают.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полевой комплект Лиги Аратора',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты определенно $Gначал:начала; показывать нам себя, $N. В награду возьмите эту амуницию! Внутри вы найдете пайки и бинты, которые можно использовать только в Низине Арати.По мере того, как вы продолжаете проявлять себя в Низине, вы обнаружите, что эти предметы станут доступны вам для покупки. Пайки становятся доступными, когда вы дружите с нами, и бинты, когда вас уважают.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8261,'Стандартный полевой комплект Лиги Аратора','Ты определенно $Gначал:начала; показывать нам себя, $N. В награду возьмите эту амуницию! Внутри вы найдете пайки и бинты, которые можно использовать только в Низине Арати.По мере того, как вы продолжаете проявлять себя в Низине, вы обнаружите, что эти предметы станут доступны вам для покупки. Пайки становятся доступными, когда вы дружите с нами, и бинты, когда вас уважают.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стандартный полевой комплект Лиги Аратора',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты определенно $Gначал:начала; показывать нам себя, $N. В награду возьмите эту амуницию! Внутри вы найдете пайки и бинты, которые можно использовать только в Низине Арати.По мере того, как вы продолжаете проявлять себя в Низине, вы обнаружите, что эти предметы станут доступны вам для покупки. Пайки становятся доступными, когда вы дружите с нами, и бинты, когда вас уважают.',`offerrewardtext_loc8`);
