INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8263,'Полевой комплект Осквернителей','В награду возьми это! Внутри ты найдешь пайки и бинты, которые можно использовать только в Низине Арати.$B$BПо мере того, как ты продолжишь проявлять себя в Низине, ты обнаружишь, что эти предметы станут доступны тебе к покупке. Пайки станут доступными, когда ты заслужишь уважение, и бинты, когда заслужишь почтение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полевой комплект Осквернителей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В награду возьми это! Внутри ты найдешь пайки и бинты, которые можно использовать только в Низине Арати.$B$BПо мере того, как ты продолжишь проявлять себя в Низине, ты обнаружишь, что эти предметы станут доступны тебе к покупке. Пайки станут доступными, когда ты заслужишь уважение, и бинты, когда заслужишь почтение.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8264,'Стандартный полевой комплект Осквернителей','В награду возьми это! Внутри ты найдешь пайки и бинты, которые можно использовать только в Низине Арати.$B$BПо мере того, как ты продолжишь проявлять себя в Низине, ты обнаружишь, что эти предметы станут доступны тебе к покупке. Пайки станут доступными, когда ты заслужишь уважение, и бинты, когда заслужишь почтение.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стандартный полевой комплект Осквернителей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В награду возьми это! Внутри ты найдешь пайки и бинты, которые можно использовать только в Низине Арати.$B$BПо мере того, как ты продолжишь проявлять себя в Низине, ты обнаружишь, что эти предметы станут доступны тебе к покупке. Пайки станут доступными, когда ты заслужишь уважение, и бинты, когда заслужишь почтение.',`offerrewardtext_loc8`);
