INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8266,'Ленты жертвоприношения','Что ж, ты не $Gсбежал:сбежала; перед лицом поражения. Ты $Gстоял:стояла; на своем, $N, и именно это делает тебя настоящим героем. Без сомнения, в следующий раз ты выиграешь ... но тем не менее мы благодарим тебя за твои старания.','Вернитесь к часовому Дальней Песне в Ясеневый лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ленты жертвоприношения',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, ты не $Gсбежал:сбежала; перед лицом поражения. Ты $Gстоял:стояла; на своем, $N, и именно это делает тебя настоящим героем. Без сомнения, в следующий раз ты выиграешь ... но тем не менее мы благодарим тебя за твои старания.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Дальней Песне в Ясеневый лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8267,'Ленты жертвоприношения','Что ж, ты не $Gсбежал:сбежала; перед лицом поражения. Ты $Gстоял:стояла; на своем, $N, и именно это делает тебя настоящим героем. Без сомнения, в следующий раз ты выиграешь ... но тем не менее мы благодарим тебя за твои старания.','Вернитесь к часовому Дальней Песне в Ясеневый лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ленты жертвоприношения',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, ты не $Gсбежал:сбежала; перед лицом поражения. Ты $Gстоял:стояла; на своем, $N, и именно это делает тебя настоящим героем. Без сомнения, в следующий раз ты выиграешь ... но тем не менее мы благодарим тебя за твои старания.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Дальней Песне в Ясеневый лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8268,'Ленты жертвоприношения','Что ж, ты не $Gсбежал:сбежала; перед лицом поражения. Ты $Gстоял:стояла; на своем, $N, и именно это делает тебя настоящим героем. Без сомнения, в следующий раз ты выиграешь ... но тем не менее мы благодарим тебя за твои старания.','Вернитесь к капитану Лободробу в Лагерь Мор\'шан, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ленты жертвоприношения',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, ты не $Gсбежал:сбежала; перед лицом поражения. Ты $Gстоял:стояла; на своем, $N, и именно это делает тебя настоящим героем. Без сомнения, в следующий раз ты выиграешь ... но тем не менее мы благодарим тебя за твои старания.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Лободробу в Лагерь Мор\'шан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8269,'Ленты жертвоприношения','Что ж, ты не $Gсбежал:сбежала; перед лицом поражения. Ты $Gстоял:стояла; на своем, $N, и именно это делает тебя настоящим героем. Без сомнения, в следующий раз ты выиграешь ... но тем не менее мы благодарим тебя за твои старания.','Вернитесь к капитану Лободробу в Лагерь Мор\'шан, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ленты жертвоприношения',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, ты не $Gсбежал:сбежала; перед лицом поражения. Ты $Gстоял:стояла; на своем, $N, и именно это делает тебя настоящим героем. Без сомнения, в следующий раз ты выиграешь ... но тем не менее мы благодарим тебя за твои старания.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Лободробу в Лагерь Мор\'шан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8270,'test copy quest') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','test copy quest',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8271,'Герой Грозовой Вершины','Как герой Грозовой Вершины, вы можете выбрать один предмет из недавно обнаруженных сокровищ.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Герой Грозовой Вершины',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как герой Грозовой Вершины, вы можете выбрать один предмет из недавно обнаруженных сокровищ.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (8272,'Каково это, $N? Каково это - сокрушать врагов и смотреть, как их линии расходятся? Приятно, правда?$B$BТы $Gдолжен:должна; быть $Gвознагражден:вознаграждена; за этот подвиг, солдат.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Каково это, $N? Каково это - сокрушать врагов и смотреть, как их линии расходятся? Приятно, правда?$B$BТы $Gдолжен:должна; быть $Gвознагражден:вознаграждена; за этот подвиг, солдат.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8273,'Благодарность Оран','Разве это не интересно? Вы сказали, что нашли эту табличку на маленьком безлюдном острове в Оверлук-Клиффс во Внутренних землях, $C? Действительно, очень интересно. <Оран осторожно убирает планшет и трет руки.>$B$BБлагодарю вас за ваши старания в этом вопросе. Наша Темная Госпожа будет очень довольна этим открытием. Позвольте мне вознаградить вас соразмерно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благодарность Оран',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разве это не интересно? Вы сказали, что нашли эту табличку на маленьком безлюдном острове в Оверлук-Клиффс во Внутренних землях, $C? Действительно, очень интересно. <Оран осторожно убирает планшет и трет руки.>$B$BБлагодарю вас за ваши старания в этом вопросе. Наша Темная Госпожа будет очень довольна этим открытием. Позвольте мне вознаградить вас соразмерно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8274,'Убийственное поручение','У тебя есть свободное времечко? Убей мне мурлоков, и я тебе блестяшечку дам!','Убейте 5 мурлоков и вернитесь к испытательному персонажу.','Return to [PH] Luis Test NPC in Designer Island.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убийственное поручение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя есть свободное времечко? Убей мне мурлоков, и я тебе блестяшечку дам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 мурлоков и вернитесь к испытательному персонажу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Return to [PH] Luis Test NPC in Designer Island.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8275,'Отвоевание Силитуса','Внемлите, герои Альянса! Мы слишком долго не обращали внимания на опасность, источник которой – силитиды. Им никто не противостоял, и мерзкие насекомые подготовились к масштабному вторжению.$b$bСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!$b$bВсе на защиту Азерота! Все способные держать оружие должны пройти инструктаж у призывательницы ветров Гордого Рога в Крепости Кенария!','Поговорите с призывательницей ветров Гордый Рог в Крепости Кенария.','Отлично, еще один доброволец готов выступить против силитидов. Добро пожаловать в Крепость Кенария, $C). Я рад, что слова наших посланников привлекают героев вроде тебя. У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвоевание Силитуса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внемлите, герои Альянса! Мы слишком долго не обращали внимания на опасность, источник которой – силитиды. Им никто не противостоял, и мерзкие насекомые подготовились к масштабному вторжению.$b$bСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!$b$bВсе на защиту Азерота! Все способные держать оружие должны пройти инструктаж у призывательницы ветров Гордого Рога в Крепости Кенария!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с призывательницей ветров Гордый Рог в Крепости Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, еще один доброволец готов выступить против силитидов. Добро пожаловать в Крепость Кенария, $C). Я рад, что слова наших посланников привлекают героев вроде тебя. У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8276,'Отвоевание Силитуса','Внемлите, герои Орды! Мы слишком долго не обращали внимания на серьезную угрозу. Дрожание земли рядом с ульями силитидов говорит о серьезном возрастании их числа в связи с готовящимся нападением.$b$bСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!$b$bВсе, способные держать оружие, должны обратиться к призывательнице ветров Гордыму Рогу в Крепости Кенария! Да сгинут силитиды!','Поговорите с призывательницей ветров Гордый Рог в Крепости Кенария.','Отлично, еще один доброволец готов выступить против силитидов. Добро пожаловать в Крепость Кенария, $C. Я рад, что слова наших посланников привлекают героев вроде тебя. У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвоевание Силитуса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внемлите, герои Орды! Мы слишком долго не обращали внимания на серьезную угрозу. Дрожание земли рядом с ульями силитидов говорит о серьезном возрастании их числа в связи с готовящимся нападением.$b$bСилы Круга Кенария собираются в Силитусе, чтобы дать отпор силитидам, пока не поздно! Мы не позволим им и дальше осквернять нашу землю!$b$bВсе, способные держать оружие, должны обратиться к призывательнице ветров Гордыму Рогу в Крепости Кенария! Да сгинут силитиды!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с призывательницей ветров Гордый Рог в Крепости Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, еще один доброволец готов выступить против силитидов. Добро пожаловать в Крепость Кенария, $C. Я рад, что слова наших посланников привлекают героев вроде тебя. У тебя будет предостаточно возможностей помочь нам, и, думается мне, ты быстро станешь одним из сильнейших наших сторонников.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8277,'Смертельный яд','Битисса Шаткобрус к твоим услугам! Мой кузен Ноггл зарабатывает на жизнь, продавая алхимикам из Крепости Кенария редкие травы. Точнее, зарабатывал. Из последней вылазки он вернулся отравленный страшным ядом.$b$BЯ сумела замедлить действие яда, но чтобы полностью нейтрализовать его, мне понадобятся образцы яда тех тварей, что ужалили его.$b$bНоггл вернулся с севера, поэтому я готова поспорить, что он пострадал от камнехвостых скорпидов или песчаных пауков-быстролапов. Принеси мне несколько жал и клыков, и я сделаю противоядие.','Принесите Битиссе Шаткобрус из Крепости Кенария 8 жал камнехвостых скорпидов и 8 клыков песчаных пауков-быстролапов.','Вернитесь к Битиссе Шаткобрус в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смертельный яд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Битисса Шаткобрус к твоим услугам! Мой кузен Ноггл зарабатывает на жизнь, продавая алхимикам из Крепости Кенария редкие травы. Точнее, зарабатывал. Из последней вылазки он вернулся отравленный страшным ядом.$b$BЯ сумела замедлить действие яда, но чтобы полностью нейтрализовать его, мне понадобятся образцы яда тех тварей, что ужалили его.$b$bНоггл вернулся с севера, поэтому я готова поспорить, что он пострадал от камнехвостых скорпидов или песчаных пауков-быстролапов. Принеси мне несколько жал и клыков, и я сделаю противоядие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Битиссе Шаткобрус из Крепости Кенария 8 жал камнехвостых скорпидов и 8 клыков песчаных пауков-быстролапов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Битиссе Шаткобрус в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8278,'Последняя надежда Ноггла','Проклятье! Противоядие не сработало. Наверное, Ноггла укусила одна из тварей на далеком юге, они гораздо страшнее остальных.$b$bПридется попросить тебя отправиться за образцами, $n. В утешение могу сказать, что поскольку яд у них сильный, мне потребуется не так много образцов, как в прошлый раз. С другой стороны, на юге больше ядовитых тварей, поэтому придется убить по несколько существ разных видов.','Принесите Битиссе Шаткобрус из Крепости Кенария 3 жала камнехвостых клешневиков, 3 жала камнехвостых живодеров и 3 клыка скальных пауков-скакунов.','Да! Похоже, сработало, Ноггл приходит в себя. Мы у тебя в долгу!','Это последний шанс спасти Ноггла! Спеши!','Вернитесь к Битиссе Шаткобрус в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя надежда Ноггла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проклятье! Противоядие не сработало. Наверное, Ноггла укусила одна из тварей на далеком юге, они гораздо страшнее остальных.$b$bПридется попросить тебя отправиться за образцами, $n. В утешение могу сказать, что поскольку яд у них сильный, мне потребуется не так много образцов, как в прошлый раз. С другой стороны, на юге больше ядовитых тварей, поэтому придется убить по несколько существ разных видов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Битиссе Шаткобрус из Крепости Кенария 3 жала камнехвостых клешневиков, 3 жала камнехвостых живодеров и 3 клыка скальных пауков-скакунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да! Похоже, сработало, Ноггл приходит в себя. Мы у тебя в долгу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это последний шанс спасти Ноггла! Спеши!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Битиссе Шаткобрус в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8279,'Сумеречный словарь','Сумеречный Молот не прощает тех, кто покидает его ряды. Они охотятся за мной, словно за диким зверем! Излишне говорить, что их враги – мои друзья!$b$bЧтобы расшифровать эту табличку, мне понадобится книга, которой пользуются их писцы при закодировании тайных посланий, Сумеречный словарь. Эта книга настолько важна, что три ее главы держат в разных местах! Главы находятся у особых офицеров, именуемых сумеречными хранителями. Ищи их в лагерях Сумеречного Молота.','Принесите три главы Сумеречного словаря отшельнику Ортеллу из Силитуса.','Вернитесь к отшельнику Ортеллу в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречный словарь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сумеречный Молот не прощает тех, кто покидает его ряды. Они охотятся за мной, словно за диким зверем! Излишне говорить, что их враги – мои друзья!$b$bЧтобы расшифровать эту табличку, мне понадобится книга, которой пользуются их писцы при закодировании тайных посланий, Сумеречный словарь. Эта книга настолько важна, что три ее главы держат в разных местах! Главы находятся у особых офицеров, именуемых сумеречными хранителями. Ищи их в лагерях Сумеречного Молота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три главы Сумеречного словаря отшельнику Ортеллу из Силитуса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к отшельнику Ортеллу в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8280,'Надежные поставки','Крепость Кенария имеет важнейшее стратегическое значение. Не сомневаюсь, что пока мы удерживаем ее, силитидам нас не одолеть. Разумеется, если припасы будут поступать регулярно.$b$bПесчаные черви оказались даже большей помехой для наших караванов, чем сами силитиды. Например, сегодня утром землечерпы разграбили большой караван с рассветницей. Необходимо сократить число этих тварей, чтобы обеспечить бесперебойные поставки.','Убейте 15 землечерпов по поручению призывательницы ветров Гордый Рог.','Ударные земснаряды представляют собой серьезную угрозу, и с ними нужно быстро бороться!','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надежные поставки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крепость Кенария имеет важнейшее стратегическое значение. Не сомневаюсь, что пока мы удерживаем ее, силитидам нас не одолеть. Разумеется, если припасы будут поступать регулярно.$b$bПесчаные черви оказались даже большей помехой для наших караванов, чем сами силитиды. Например, сегодня утром землечерпы разграбили большой караван с рассветницей. Необходимо сократить число этих тварей, чтобы обеспечить бесперебойные поставки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 землечерпов по поручению призывательницы ветров Гордый Рог.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ударные земснаряды представляют собой серьезную угрозу, и с ними нужно быстро бороться!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8281,'Обеспечение безопасности','Ты великолепно себя $gзарекомендовал:зарекомендовала;, $n. К сожалению, нашему снабжению по-прежнему грозит опасность. Землечерпов теперь нет, но их место несомненно займут их более крупные южные родственники – земляные сокрушители.$b$bЧтобы приструнить этих червяков, придется убить их побольше. Но мы не можем подвергать опасности наше снабжение.','Убейте 20 земляных сокрушителей по поручению призывательницы ветров Гордого Рога.','Земснаряд-дробилки представляют собой серьезную угрозу, и с ней нужно бороться немедленно!','Вернитесь к призывательнице ветров Гордый Рог в Улей Аши, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обеспечение безопасности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты великолепно себя $gзарекомендовал:зарекомендовала;, $n. К сожалению, нашему снабжению по-прежнему грозит опасность. Землечерпов теперь нет, но их место несомненно займут их более крупные южные родственники – земляные сокрушители.$b$bЧтобы приструнить этих червяков, придется убить их побольше. Но мы не можем подвергать опасности наше снабжение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 земляных сокрушителей по поручению призывательницы ветров Гордого Рога.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Земснаряд-дробилки представляют собой серьезную угрозу, и с ней нужно бороться немедленно!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывательнице ветров Гордый Рог в Улей Аши, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8282,'Потерянная сумка Ноггла','Где я? Где моя сумка? *вздыхает* Наверное, я потерял ее, убегая от Смертехвата, огромного скорпида. Я мчался, не разбирая дороги, и забрел прямо в гнездо камнехвостых живодеров.$b$bВ моей сумке были ценнейшие реагенты. Без них мы с Битикс не сможем делать зелья для Крепости Кенария. Я пока не в силах встать, но если ты сможешь вернуть мне реагенты, я тебе отплачу сторицей.$b$bНа Смертехвата я наткнулся в южных горах, за лагерем Бронзоборода.','Принесите сумку Ноггла из гор в южной части Силитуса и верните ее хозяину в Крепости Кенария.','Вернитесь к Ногглу Шаткобрусу в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянная сумка Ноггла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Где я? Где моя сумка? *вздыхает* Наверное, я потерял ее, убегая от Смертехвата, огромного скорпида. Я мчался, не разбирая дороги, и забрел прямо в гнездо камнехвостых живодеров.$b$bВ моей сумке были ценнейшие реагенты. Без них мы с Битикс не сможем делать зелья для Крепости Кенария. Я пока не в силах встать, но если ты сможешь вернуть мне реагенты, я тебе отплачу сторицей.$b$bНа Смертехвата я наткнулся в южных горах, за лагерем Бронзоборода.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите сумку Ноггла из гор в южной части Силитуса и верните ее хозяину в Крепости Кенария.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ногглу Шаткобрусу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8283,'РОЗЫСК: Смертехват, гроза пустыни','Принесите хелицеры Смертехвата Вишу Коцусу, капитану стражи.','Замечательно! Смертехвата нет, и мы сможем спокойно подобраться к ульям силитидов по южным горам. Мы высоко ценим твою работу.','Доказательством гибели твари послужат ее хелицеры. Нет хелицер, нет и награды.','Вернитесь к Вишу Коцусу в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РОЗЫСК: Смертехват, гроза пустыни',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите хелицеры Смертехвата Вишу Коцусу, капитану стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Смертехвата нет, и мы сможем спокойно подобраться к ульям силитидов по южным горам. Мы высоко ценим твою работу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Доказательством гибели твари послужат ее хелицеры. Нет хелицер, нет и награды.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вишу Коцусу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8284,'Сумеречная тайна','На северо-западе отсюда некогда благоденствовал лагерь служителей культа Сумеречного Молота. Теперь на месте лагеря остались лишь обломки древесины и ткани, среди которых бродят элементали.$b$bМне удалось добыть там несколько кусочков глиняной таблички, но их слишком мало, чтобы узнать что-нибудь ценное. Не сможешь ли ты добыть остальные фрагменты? Быть может, они прольют свет на деятельность Сумеречного Молота в Силитусе.','Геолог Ехидная из Крепости Кенария просит вас собрать 8 фрагментов Сумеречной таблички.','Так я и думала. Я могу перевести отдельные слова, но они лишены смысла. Сумеречный Молот часто пользуется особыми шифрами, чтобы скрыть значение своих текстов от чужих; нужно найти кого-нибудь, кто разбирается в таких вещах.','Разграбленный лагерь находится на северо-западе. Возвращайся, когда соберешь все фрагменты.','Вернитесь к геологу Ехидной в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречная тайна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На северо-западе отсюда некогда благоденствовал лагерь служителей культа Сумеречного Молота. Теперь на месте лагеря остались лишь обломки древесины и ткани, среди которых бродят элементали.$b$bМне удалось добыть там несколько кусочков глиняной таблички, но их слишком мало, чтобы узнать что-нибудь ценное. Не сможешь ли ты добыть остальные фрагменты? Быть может, они прольют свет на деятельность Сумеречного Молота в Силитусе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Геолог Ехидная из Крепости Кенария просит вас собрать 8 фрагментов Сумеречной таблички.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так я и думала. Я могу перевести отдельные слова, но они лишены смысла. Сумеречный Молот часто пользуется особыми шифрами, чтобы скрыть значение своих текстов от чужих; нужно найти кого-нибудь, кто разбирается в таких вещах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разграбленный лагерь находится на северо-западе. Возвращайся, когда соберешь все фрагменты.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Ехидной в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8285,'Дезертир','Ходят слухи, что некто по имени Ортелл вышел из рядов Сумеречного Молота. Говорят, он прячется в горах на юге от деревни Южного Ветра и живет в полном уединении. Может быть, имеет смысл прибегнуть к его помощи в расшифровании таблички.$b$bВозьми восстановленную табличку и отнеси ее Ортеллу.','Отнесите восстановленную табличку отшельнику Ортеллу в Силитус.','Вижу, ты не понаслышке знаешь о моей бывшей организации. Должно быть, ты из Крепости Кенария.$B$BТебе нужна информация для борьбы с Сумеречным Молотом? Подойди ближе, может быть, мы сможем помочь друг другу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дезертир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, что некто по имени Ортелл вышел из рядов Сумеречного Молота. Говорят, он прячется в горах на юге от деревни Южного Ветра и живет в полном уединении. Может быть, имеет смысл прибегнуть к его помощи в расшифровании таблички.$b$bВозьми восстановленную табличку и отнеси ее Ортеллу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите восстановленную табличку отшельнику Ортеллу в Силитус.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вижу, ты не понаслышке знаешь о моей бывшей организации. Должно быть, ты из Крепости Кенария.$B$BТебе нужна информация для борьбы с Сумеречным Молотом? Подойди ближе, может быть, мы сможем помочь друг другу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (8286,'Что день грядущий нам готовит','Я уже почти очутился в объятьях смерти, и тут вмешался он. Лишь раз дохнул он на мое искалеченное тело, а затем оставалось лишь дождаться, пока пески времени исцелят мои раны.$B$B"Навеки останешься ты, коли так нужно," – сказал он, и с этими словами сделал меня Стражем.$b$bТолько взгляни на пустыню. Вторая война неминуема. Найди тайное укрытие бронзовых драконов. Отправляйся в Пещеры Времени и узнай, не вернулся ли повелитель. Я должен знать наверняка, иначе не смогу действовать.','Отправляйтесь в Пещеры Времени в Танарисе и найдите Анахроноса, из рода Ноздорму.','Так и должно быть - поднялся великий. Мои часы заканчиваются…','Анахронос вернулся?','Найдите драконов из рода Ноздорму.','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что день грядущий нам готовит',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже почти очутился в объятьях смерти, и тут вмешался он. Лишь раз дохнул он на мое искалеченное тело, а затем оставалось лишь дождаться, пока пески времени исцелят мои раны.$B$B"Навеки останешься ты, коли так нужно," – сказал он, и с этими словами сделал меня Стражем.$b$bТолько взгляни на пустыню. Вторая война неминуема. Найди тайное укрытие бронзовых драконов. Отправляйся в Пещеры Времени и узнай, не вернулся ли повелитель. Я должен знать наверняка, иначе не смогу действовать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Пещеры Времени в Танарисе и найдите Анахроноса, из рода Ноздорму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так и должно быть - поднялся великий. Мои часы заканчиваются…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Анахронос вернулся?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Найдите драконов из рода Ноздорму.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8287,'Ужасная цель','Ну вот... Ценная информация, скажу я тебе! Я видел, как силы Круга Кенария прибыли в Силитус. Они планируют выбить из наших краев Сумеречный Молот, верно? Это поспособствует воплощению их планов.$b$bОтнеси этот пергамент их главе, командиру Мар\'алиту. Скоро Сумеречный Молоты изгонят из этих земель и их жадные ручки до меня не дотянутся!','Отнесите переписанный с таблички расшифрованный текст командиру Мар\'алиту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ужасная цель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот... Ценная информация, скажу я тебе! Я видел, как силы Круга Кенария прибыли в Силитус. Они планируют выбить из наших краев Сумеречный Молот, верно? Это поспособствует воплощению их планов.$b$bОтнеси этот пергамент их главе, командиру Мар\'алиту. Скоро Сумеречный Молоты изгонят из этих земель и их жадные ручки до меня не дотянутся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите переписанный с таблички расшифрованный текст командиру Мар\'алиту.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8288,'Кто будет избран?','Время у нас на исходе! Нам необходим герой! Выполнить мое задание под силу лишь целой армии, но только одному из целой толпы будущих героев суждено принять на себя тяжкую ношу ответственности – стать союзником Племени.$b$bВ логове владыки Черной горы живет жестокий зверь, предводитель драконов Разящий Бич. Он охраняет Залы Раздора, перекрывая путь в покои Нефариана. Убей гнусную тварь и принеси мне ее голову. Это будет первым шагом на твоем пути.','Принесите голову предводителя драконов Разящего Бича Баристольфу из Зыбучих Песков в Крепость Кенария в Силитусе.','Неужели ты станешь первым союзником бронзовых драконов за тысячу лет?','Твоя цель – завоевать благосклонность рода Ноздорму.','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто будет избран?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время у нас на исходе! Нам необходим герой! Выполнить мое задание под силу лишь целой армии, но только одному из целой толпы будущих героев суждено принять на себя тяжкую ношу ответственности – стать союзником Племени.$b$bВ логове владыки Черной горы живет жестокий зверь, предводитель драконов Разящий Бич. Он охраняет Залы Раздора, перекрывая путь в покои Нефариана. Убей гнусную тварь и принеси мне ее голову. Это будет первым шагом на твоем пути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову предводителя драконов Разящего Бича Баристольфу из Зыбучих Песков в Крепость Кенария в Силитусе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неужели ты станешь первым союзником бронзовых драконов за тысячу лет?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твоя цель – завоевать благосклонность рода Ноздорму.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8289,'Талисманы заслуг','Вернитесь к часовому Дальней Песне в Ясеневый лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Талисманы заслуг',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Дальней Песне в Ясеневый лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8290,'Долой захватчиков!','$gЮный:Юная:c; |3-6($c)! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$b$bОтправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!$b$bНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $n, и получишь награду!','Войдите в Ущелье Песни Войны, одержите победу над Ордой, получите почетный знак Ущелья Песни Войны и вернитесь с ним к часовому Дальней Песня в рощу Среброкрылых.','Вернитесь к часовому Дальней Песне в Зеркало Небес, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долой захватчиков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gЮный:Юная:c; |3-6($c)! Миновав этот проход, ты увидишь поле яростных сражений. Орда продолжает вырубать наши священные леса, уничтожая вечнозеленые кроны, чтобы питать свою военную машину!$b$bОтправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!$b$bНаградой тебе будет талисман заслуг. Принеси мне такой талисман, $n, и получишь награду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в Ущелье Песни Войны, одержите победу над Ордой, получите почетный знак Ущелья Песни Войны и вернитесь с ним к часовому Дальней Песня в рощу Среброкрылых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Дальней Песне в Зеркало Небес, что в Ясеневом лесу.',`completedtext_loc8`);
