INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8292,'Талисманы заслуг','Спасибо, $N. Твои подвиги в Ущелье Песни Войны прозвучат по всему Ясеневому лесу.','Вернитесь к часовому Дальней Песне в Ясеневый лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Талисманы заслуг',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Твои подвиги в Ущелье Песни Войны прозвучат по всему Ясеневому лесу.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Дальней Песне в Ясеневый лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8293,'Почетный знак','Ночные эльфы и их союзники должны дрожать даже при шепоте твоего имени! За Орду!','Вернитесь к капитану Лободробу в Лагерь Мор\'шан, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почетный знак',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ночные эльфы и их союзники должны дрожать даже при шепоте твоего имени! За Орду!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Лободробу в Лагерь Мор\'шан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8294,'Громи захватчиков-Среброкрылых!','Чащобы Ясеневого леса падут пред мощью Орды, |3-6($r)! Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше?$b$bПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из клана Среброкрылых и заслужи почетный знак Ущелья Песни Войны. Вернись ко мне с этим знаком, $n – и получишь награду!','Войдите в Ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак Ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.','<Капитан Лободроб одобрительно порыкивает.>$B$BИ сколько еще они смогут так продержаться? Сколько еще солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать? Время покажет, $R, время покажет...','Кровь наших врагов - знак чести. У тебя есть такая отметка?','Вернитесь к капитану Лободробу в лагерь Мор\'шан, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Громи захватчиков-Среброкрылых!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чащобы Ясеневого леса падут пред мощью Орды, |3-6($r)! Что бы ни делали часовые из клана Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше?$b$bПусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду! Разгроми часовых из клана Среброкрылых и заслужи почетный знак Ущелья Песни Войны. Вернись ко мне с этим знаком, $n – и получишь награду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в Ущелье Песни Войны, одержите победу над Альянсом, получите почетный знак Ущелья Песни Войны и вернитесь с ним к капитану Лободробу в лагерь Мор\'шан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан Лободроб одобрительно порыкивает.>$B$BИ сколько еще они смогут так продержаться? Сколько еще солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать? Время покажет, $R, время покажет...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кровь наших врагов - знак чести. У тебя есть такая отметка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Лободробу в лагерь Мор\'шан, что в Степях.',`completedtext_loc8`);
