INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8296,'Почетный знак','Вернитесь к капитану Лободробу в Лагерь Мор\'шан, что в Степях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почетный знак',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Лободробу в Лагерь Мор\'шан, что в Степях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8297,'Ресурсы Низины Арати','Войну выигрывают солдаты, любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна, еще не начавшись!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо, и все можно добыть там.$B$BИ вот чего я хочу от вас, $n. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.','Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Макчисту в Опорный пункт.','У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам.$B$BСпасибо, $N. Действительно, успешное выполнение миссий, подобных той, которую ты $Gвыполнил:выполнила;, - вот как действительно выигрывают войны.','У тебя есть ящик с ресурсами, $N? Без них Лига Аратора не сможет вести достойную битву...','Вернитесь к сержанту Макчист на Опорный пункт, что на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ресурсы Низины Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войну выигрывают солдаты, любой солдат вам это скажет. Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна, еще не начавшись!$B$BВот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы. Металл, оружие, пища, древесина – все это необходимо, и все можно добыть там.$B$BИ вот чего я хочу от вас, $n. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выиграйте битву за Низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Макчисту в Опорный пункт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам.$B$BСпасибо, $N. Действительно, успешное выполнение миссий, подобных той, которую ты $Gвыполнил:выполнила;, - вот как действительно выигрывают войны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть ящик с ресурсами, $N? Без них Лига Аратора не сможет вести достойную битву...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Макчист на Опорный пункт, что на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8298,'Новые ящики с ресурсами','Очень хорошо. Я немедленно передам их нашим интендантам.$B$BЕще раз спасибо, $N. Твой вклад в нашу борьбу заметят как целитель, так и фельдмаршал.','$N, у Лиги Аратора есть постоянная миссия: вернуться в низину Арати, добыть еще ящики с ресурсами и принести их мне.','Вернитесь к сержанту Макчист на Нагорье Арати.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые ящики с ресурсами',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Я немедленно передам их нашим интендантам.$B$BЕще раз спасибо, $N. Твой вклад в нашу борьбу заметят как целитель, так и фельдмаршал.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, у Лиги Аратора есть постоянная миссия: вернуться в низину Арати, добыть еще ящики с ресурсами и принести их мне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Макчист на Нагорье Арати.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (8299,'Перекрыть линии поставок Аратора','Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдаленную область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы.$B$BВы, $n, можете нам помочь. Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перекрыть линии поставок Аратора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати. Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдаленную область, намереваясь распространить свои владения за пределы Опорного пункта. Мы должны остановить их, а наилучшее средство для этого – захватить их припасы.$B$BВы, $n, можете нам помочь. Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками. Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8300,'Новые ящики с ресурсами','Очень хорошо. Я немедленно передам их нашим интендантам.$B$BЕще раз спасибо, $N. Твой вклад в нашу борьбу заметят как ворчун, так и верховный полководец.','$N, у Осквернителей есть постоянная миссия: вернуться в низину Арати, добыть еще ящики с ресурсами и принести их мне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые ящики с ресурсами',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Я немедленно передам их нашим интендантам.$B$BЕще раз спасибо, $N. Твой вклад в нашу борьбу заметят как ворчун, так и верховный полководец.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, у Осквернителей есть постоянная миссия: вернуться в низину Арати, добыть еще ящики с ресурсами и принести их мне.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8301,'Путь праведника','Род Ноздорму инстинктивно не верит низшим расам. Хоть ты и $gсмог:смогла; доказать мне, что у тебя задатки настоящего героя, пришло время доказать это моему повелителю.$b$bУлей Аши, улей Зора и улей Регал кишат силитидами, которые грозят нашему существованию. Убей как можно больше проклятых тварей и принеси мне фрагменты их панцирей. Когда у тебя закончится место в заплечных мешках, возвращайся и я укреплю твою решимость.','Принесите Баристолфу 200 фрагментов силитидских панцирей.','Не думай, что ты $Gодин:одна;. Я дарую тебе способность привлекать других к себе на помощь. Подлинному защитнику своего народа не обойтись без помощи собратьев.','Недоверие к смертным расам коренится в далеком прошлом; но пусть тебе об этом расскажут сами драконы, когда придет время.','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь праведника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Род Ноздорму инстинктивно не верит низшим расам. Хоть ты и $gсмог:смогла; доказать мне, что у тебя задатки настоящего героя, пришло время доказать это моему повелителю.$b$bУлей Аши, улей Зора и улей Регал кишат силитидами, которые грозят нашему существованию. Убей как можно больше проклятых тварей и принеси мне фрагменты их панцирей. Когда у тебя закончится место в заплечных мешках, возвращайся и я укреплю твою решимость.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Баристолфу 200 фрагментов силитидских панцирей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не думай, что ты $Gодин:одна;. Я дарую тебе способность привлекать других к себе на помощь. Подлинному защитнику своего народа не обойтись без помощи собратьев.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Недоверие к смертным расам коренится в далеком прошлом; но пусть тебе об этом расскажут сами драконы, когда придет время.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8302,'Рука праведника','Старательно выбирай своих представителей, $gсмертный:смертная;. Всякий раз, выполнив задание, ты сможешь выбрать себе нового представителя.$b$bА теперь, не теряя времени, скажу: мне по-прежнему нужны обломки силитидских панцирей. Что стоишь? Иди!','Принесите Баристолфу 200 фрагментов силитидских панцирей.','Молодец, герой. Тебе будет дарована возможность назначить еще одного агента Ноздорму.','Быть может, когда-нибудь ты возглавишь гарнизон крепости Кенария.','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рука праведника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старательно выбирай своих представителей, $gсмертный:смертная;. Всякий раз, выполнив задание, ты сможешь выбрать себе нового представителя.$b$bА теперь, не теряя времени, скажу: мне по-прежнему нужны обломки силитидских панцирей. Что стоишь? Иди!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Баристолфу 200 фрагментов силитидских панцирей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, герой. Тебе будет дарована возможность назначить еще одного агента Ноздорму.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Быть может, когда-нибудь ты возглавишь гарнизон крепости Кенария.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Баристолфу из Зыбучих Песков в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8303,'Анахронос','Время пришло, $n.$b$bЯ должен извиниться за то, что так долго держал все в тайне. Но кругом враги, они могут оказаться у нас прямо под носом. Прошу тебя, прими этот фолиант, читай его и учись. Я с радостью делюсь с тобой знаниями. Теперь же отыщи нашего повелителя.','Отыщите Анахроноса в Пещерах Времени в Танарисе.','Весь Калимдор надеется на тебя, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Анахронос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время пришло, $n.$b$bЯ должен извиниться за то, что так долго держал все в тайне. Но кругом враги, они могут оказаться у нас прямо под носом. Прошу тебя, прими этот фолиант, читай его и учись. Я с радостью делюсь с тобой знаниями. Теперь же отыщи нашего повелителя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Анахроноса в Пещерах Времени в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Весь Калимдор надеется на тебя, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questturntextwindow_loc8`,`questturntargetname_loc8`) VALUES (8304,'Дражайшая Наталия','Моя милая Наталия пропала.$b$bЧестно говоря, в последние недели перед исчезновением она довольно странно вела себя. Я несколько раз видел, как она говорила сама с собой. При этом Наталия уверяла, что все в порядке и ей необходимо продолжать исследования.$b$bВ последний раз я видел ее, когда она направилась в лагерь Бронзоборода, на юг.$b$bУ меня слишком мало солдат, $n. Сходи в лагерь Бронзоборода и допроси дворфов.','Допросите Франкала и Рутгара в лагере Бронзоборода о местонахождении Наталии Мар\'алит.','< Командир Мар\'алит задумчиво опускает голову.>$B$BЖива она или мертва, я должен поступать правильно. Ее нужно найти. Увы, я связан долгом с этим форпостом. Ты поможешь мне еще раз, $N?','Не теряй времени, $N!','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.','Жуткие новости…','Командир Мар\'алит') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дражайшая Наталия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя милая Наталия пропала.$b$bЧестно говоря, в последние недели перед исчезновением она довольно странно вела себя. Я несколько раз видел, как она говорила сама с собой. При этом Наталия уверяла, что все в порядке и ей необходимо продолжать исследования.$b$bВ последний раз я видел ее, когда она направилась в лагерь Бронзоборода, на юг.$b$bУ меня слишком мало солдат, $n. Сходи в лагерь Бронзоборода и допроси дворфов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Допросите Франкала и Рутгара в лагере Бронзоборода о местонахождении Наталии Мар\'алит.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','< Командир Мар\'алит задумчиво опускает голову.>$B$BЖива она или мертва, я должен поступать правильно. Ее нужно найти. Увы, я связан долгом с этим форпостом. Ты поможешь мне еще раз, $N?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не теряй времени, $N!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`), `questturntextwindow_loc8`=IF(`questturntextwindow_loc8` IS NULL OR `questturntextwindow_loc8`='','Жуткие новости…',`questturntextwindow_loc8`), `questturntargetname_loc8`=IF(`questturntargetname_loc8` IS NULL OR `questturntargetname_loc8`='','Командир Мар\'алит',`questturntargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8305,'Давно забытые воспоминания','В пустыне неподалеку от Силитуса, рядом со священной стеной, есть хрустальная слеза. Эта слеза – символ великих потерь, понесенных во время войны Зыбучих песков. Отыщи эту слезу и загляни в ее глубины, дабы достичь просветления.','Отыщите в Силитусе хрустальную слезу и загляните в ее глубины.','Ты можешь чувствовать, что большое горе вращается вокруг этого кристалла. Сила настолько мощна, что ты чувствуешь, как будто ты можешь  разрушиться и умереть от печали.$B') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Давно забытые воспоминания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В пустыне неподалеку от Силитуса, рядом со священной стеной, есть хрустальная слеза. Эта слеза – символ великих потерь, понесенных во время войны Зыбучих песков. Отыщи эту слезу и загляни в ее глубины, дабы достичь просветления.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите в Силитусе хрустальную слезу и загляните в ее глубины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты можешь чувствовать, что большое горе вращается вокруг этого кристалла. Сила настолько мощна, что ты чувствуешь, как будто ты можешь  разрушиться и умереть от печали.$B',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (8306,'В бездне безумия','Прошу тебя, $n, отправляйся в Улей Регал и узнай, что сталось с моей дорогой Наталией. Это будет очень непросто. Прежде чем нырять в бездну безумия, вернись и поговори с дворфами. Быть может, они подскажут тебе, как разобраться с силитидами из улья.$b$bИ последнее, $n. Если она в самом деле безумна, как говорят... сделай, что должно.','Найдите любимую командира Мар\'алита из Крепости Кенария в Силитусе. По имеющимся сведениям, госпожу Наталию Мар\'алит можно найти в Улье Регал.$b$bПрежде чем отправляться в улей, не забудьте поговорить с дворфами из лагеря Бронзоборода. Они могут дать пару советов и подкинуть дополнительную работу.$b$BСледует помнить слова командира: "Сделай, что должно..."','<Командир Мар\'алит хватается за сердце.>$B$BК\'Тун? ЧТО все это значит? Что еще за К\'Тун? Как мог этот демон превратить мою милую Наталию в описанного тобой монстра?','Наталия?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.','Все еще хуже, чем я думал…','Командир Мар\'алит') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В бездне безумия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу тебя, $n, отправляйся в Улей Регал и узнай, что сталось с моей дорогой Наталией. Это будет очень непросто. Прежде чем нырять в бездну безумия, вернись и поговори с дворфами. Быть может, они подскажут тебе, как разобраться с силитидами из улья.$b$bИ последнее, $n. Если она в самом деле безумна, как говорят... сделай, что должно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите любимую командира Мар\'алита из Крепости Кенария в Силитусе. По имеющимся сведениям, госпожу Наталию Мар\'алит можно найти в Улье Регал.$b$bПрежде чем отправляться в улей, не забудьте поговорить с дворфами из лагеря Бронзоборода. Они могут дать пару советов и подкинуть дополнительную работу.$b$BСледует помнить слова командира: "Сделай, что должно..."',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Командир Мар\'алит хватается за сердце.>$B$BК\'Тун? ЧТО все это значит? Что еще за К\'Тун? Как мог этот демон превратить мою милую Наталию в описанного тобой монстра?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наталия?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Все еще хуже, чем я думал…',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Командир Мар\'алит',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8307,'Блюдо из червей','Приспособиться к жизни в пустыне, мягко говоря, нелегко. Мне не хватает не только птиц и деревьев Аубердина, но и нормальной еды! Я делаю все, что моих силах, но выбор продуктов у нас невелик. Я изучаю местные травы, но их так мало...$b$bЗато я видела, как в лагерях Сумеречного Молота, что к западу отсюда, охотятся на песчаных червей. Но их мясо очень горькое, и я не представляю, как сделать его съедобным. Если ты окажешься в их лагере, смотри в оба. Как узнаешь что-нибудь – сообщи мне.','Поищите в лагере Сумеречного Молота на западе от Крепости Кенария сведения о приготовлении мяса песчаных червей.','В книге содержится несколько обычных рецептов и пара очень оригинальных. Полистав ее, вы находите рецепт, в котором упоминается мясо песчаных червей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Блюдо из червей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приспособиться к жизни в пустыне, мягко говоря, нелегко. Мне не хватает не только птиц и деревьев Аубердина, но и нормальной еды! Я делаю все, что моих силах, но выбор продуктов у нас невелик. Я изучаю местные травы, но их так мало...$b$bЗато я видела, как в лагерях Сумеречного Молота, что к западу отсюда, охотятся на песчаных червей. Но их мясо очень горькое, и я не представляю, как сделать его съедобным. Если ты окажешься в их лагере, смотри в оба. Как узнаешь что-нибудь – сообщи мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите в лагере Сумеречного Молота на западе от Крепости Кенария сведения о приготовлении мяса песчаных червей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В книге содержится несколько обычных рецептов и пара очень оригинальных. Полистав ее, вы находите рецепт, в котором упоминается мясо песчаных червей.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8308,'Потерянное письмо Бранна Бронзоборода','Всем заинтересованным лицам:$b$BЕсли вы читаете это письмо, значит, я мертв или скоро умру. Трудно сказать. Большая часть команды уже мертва.$b$bНашел сведения про титана. Страшная битва между ним и древним богом. Самый настоящий древний бог. Нашел древний туннель в Ан\'Кираж. Иду по нему.$b$bОтнесите это письмо в мой старый лагерь. Покормите, напоите и приласкайте моих обезьянок.$b$B- Бранн Бронзобород, оперативный исследователь$b$bP.S. Остерегайся безумного ночного эльфа, поклоняющегося древнему богу.','Отнесите письмо Бранна Бронзоборода в лагерь Бронзоборода в южной части Силитуса.','Что ж, многое прояснилось. Если ты доберешься до Ан\'Киража, посматривай, нет ли там старины Бранна. Боюсь, без своих обезьян он бессилен.','Мамочки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянное письмо Бранна Бронзоборода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всем заинтересованным лицам:$b$BЕсли вы читаете это письмо, значит, я мертв или скоро умру. Трудно сказать. Большая часть команды уже мертва.$b$bНашел сведения про титана. Страшная битва между ним и древним богом. Самый настоящий древний бог. Нашел древний туннель в Ан\'Кираж. Иду по нему.$b$bОтнесите это письмо в мой старый лагерь. Покормите, напоите и приласкайте моих обезьянок.$b$B- Бранн Бронзобород, оперативный исследователь$b$bP.S. Остерегайся безумного ночного эльфа, поклоняющегося древнему богу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо Бранна Бронзоборода в лагерь Бронзоборода в южной части Силитуса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, многое прояснилось. Если ты доберешься до Ан\'Киража, посматривай, нет ли там старины Бранна. Боюсь, без своих обезьян он бессилен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мамочки.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8309,'Поиски рун','После нашего первого рейда в ульи и последовавшего за этим безумия госпожи Мар\'алит из этих трех ульев так и хлынули проклятые жуки! Мне кажется, их повышенная активность как-то связана с письменами, покрывающими эти странные кристаллы.$b$bЕсли бы мне удалось получить оттиски с кристаллов из всех трех ульев, то можно было бы попытаться объяснить причины этого безумия.$b$bВозьми копирующее устройство геолога, $n, и отправляйся в Улей Регал, что к востоку отсюда. Мне нужен последний оттиск!','При помощи копирующего устройства геолога получите оттиск покрытого письменами кристалла из Улья Регал.','Ничего я не понимаю в этих письменах. Первый раз такие вижу! Надеюсь, исследования Франкала помогут пролить на них свет.','Если в одном из ульев тебе попадется ненормальная ночная эльфийка, дай ей хорошего пинка от нашего имени.','Вернитесь к Рутгару Знакописцу в Лагерь Бронзоборода, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски рун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После нашего первого рейда в ульи и последовавшего за этим безумия госпожи Мар\'алит из этих трех ульев так и хлынули проклятые жуки! Мне кажется, их повышенная активность как-то связана с письменами, покрывающими эти странные кристаллы.$b$bЕсли бы мне удалось получить оттиски с кристаллов из всех трех ульев, то можно было бы попытаться объяснить причины этого безумия.$b$bВозьми копирующее устройство геолога, $n, и отправляйся в Улей Регал, что к востоку отсюда. Мне нужен последний оттиск!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи копирующего устройства геолога получите оттиск покрытого письменами кристалла из Улья Регал.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ничего я не понимаю в этих письменах. Первый раз такие вижу! Надеюсь, исследования Франкала помогут пролить на них свет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если в одном из ульев тебе попадется ненормальная ночная эльфийка, дай ей хорошего пинка от нашего имени.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рутгару Знакописцу в Лагерь Бронзоборода, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8311,'Тыквовинские вкусности для Джеспера!','Мне за конфетами нельзя. После нападения Смертокрыла попечительница сирот Найтингейл не разрешает мне далеко отходить от приюта.$b$bМожет быть, сходишь вместо меня? А я потом поменяюсь с тобой: отдам те конфеты, которые у меня уже есть, взамен новых, которые ты принесешь!$b$bУ всех хозяев таверн в больших городах непременно есть конфеты на Тыквовин, надо только поговорить с ними и сделать то, что они попросят! А еще гном по имени Талваш из Стальгорна тоже раздает конфеты. Когда соберешь все конфеты, принеси их мне, ладно?','Поговорите с хозяевами таверн в Штормграде, Стальгорне и Дарнасе, а также с Талвашем дель Кисселем в Стальгорне. Выполните то, что они потребуют за предлагамые ими сладости.$b$bВернитесь к Джесперу в сиротский приют Штормграда и принесите ему марципан Дарнаса, леденец Гномрегана, нугу из Штормграда и мятную конфету Стальгорна.','Ты уже набрал для меня сладостей? Жаль, что я сам не могу пойти, но я рад, что ты мне помогаешь! Мне даже становится легче.','Вернитесь к Джесперу к вратам Штормграда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тыквовинские вкусности для Джеспера!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне за конфетами нельзя. После нападения Смертокрыла попечительница сирот Найтингейл не разрешает мне далеко отходить от приюта.$b$bМожет быть, сходишь вместо меня? А я потом поменяюсь с тобой: отдам те конфеты, которые у меня уже есть, взамен новых, которые ты принесешь!$b$bУ всех хозяев таверн в больших городах непременно есть конфеты на Тыквовин, надо только поговорить с ними и сделать то, что они попросят! А еще гном по имени Талваш из Стальгорна тоже раздает конфеты. Когда соберешь все конфеты, принеси их мне, ладно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хозяевами таверн в Штормграде, Стальгорне и Дарнасе, а также с Талвашем дель Кисселем в Стальгорне. Выполните то, что они потребуют за предлагамые ими сладости.$b$bВернитесь к Джесперу в сиротский приют Штормграда и принесите ему марципан Дарнаса, леденец Гномрегана, нугу из Штормграда и мятную конфету Стальгорна.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже набрал для меня сладостей? Жаль, что я сам не могу пойти, но я рад, что ты мне помогаешь! Мне даже становится легче.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джесперу к вратам Штормграда.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8312,'Тыквовинские вкусности для Крохи!','Я бы так хотела отправиться за конфетами! Но не могу, потому что попечительница сирот мне не разрешает. Сходи вместо меня, а? А я с тобой потом поменяюсь: отдам те конфеты, что у меня уже есть, взамен тех, которые дадут тебе! Вот эта конфетка тебе наверняка понравится: она позволяет превращаться в разных существ, забавных и страшных!$b$bУ всех хозяев таверн в больших городах непременно есть конфеты, которые они дарят на Тыквовин – надо только поговорить с ними и сделать то, что они попросят. И троллиха по имени Кали Ремик из Оргриммара тоже раздает конфеты. Когда соберешь все конфеты, принеси их мне, ладно?','Поговорите с хозяевами таверн в Оргриммаре, Подгороде и Громовом Утесе, а также с Кали Ремик в Аллее Духов Оргриммара. Выполните то, что они потребуют, за предлагамые ими сладости.$b$bВернитесь к Крохе в сиротский приют Оргриммара и принесите ей марципан Громового Утеса, леденец троллей Черного Копья, нугу из Оргриммара и мятную конфету Подгорода.','Что, много конфет тебе дали? Попечительница сказала, что мы можем выбрать только в одно место, и тут, по крайней мере, происходит много всего интересного.','Вернитесь к Крохе в Руины Лордерона.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тыквовинские вкусности для Крохи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бы так хотела отправиться за конфетами! Но не могу, потому что попечительница сирот мне не разрешает. Сходи вместо меня, а? А я с тобой потом поменяюсь: отдам те конфеты, что у меня уже есть, взамен тех, которые дадут тебе! Вот эта конфетка тебе наверняка понравится: она позволяет превращаться в разных существ, забавных и страшных!$b$bУ всех хозяев таверн в больших городах непременно есть конфеты, которые они дарят на Тыквовин – надо только поговорить с ними и сделать то, что они попросят. И троллиха по имени Кали Ремик из Оргриммара тоже раздает конфеты. Когда соберешь все конфеты, принеси их мне, ладно?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хозяевами таверн в Оргриммаре, Подгороде и Громовом Утесе, а также с Кали Ремик в Аллее Духов Оргриммара. Выполните то, что они потребуют, за предлагамые ими сладости.$b$bВернитесь к Крохе в сиротский приют Оргриммара и принесите ей марципан Громового Утеса, леденец троллей Черного Копья, нугу из Оргриммара и мятную конфету Подгорода.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что, много конфет тебе дали? Попечительница сказала, что мы можем выбрать только в одно место, и тут, по крайней мере, происходит много всего интересного.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крохе в Руины Лордерона.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8313,'Наделение знаниями','Хотя вам вполне понятен рецепт по приготовлению мяса песчаного червя, в нем упоминаются незнакомые травы и специи. Быть может, Каландрата хорошо разбирается в растениях пустыни и сможет помочь вам.','Принесите вырванную страницу с рецептом Каландрате в таверну Крепости Кенария.','Дай-ка взглянуть…$B$BКажется, все просто. У них есть свои названия для некоторых видов растений, но догадаться совсем просто. Дай, я покажу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наделение знаниями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя вам вполне понятен рецепт по приготовлению мяса песчаного червя, в нем упоминаются незнакомые травы и специи. Быть может, Каландрата хорошо разбирается в растениях пустыни и сможет помочь вам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите вырванную страницу с рецептом Каландрате в таверну Крепости Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дай-ка взглянуть…$B$BКажется, все просто. У них есть свои названия для некоторых видов растений, но догадаться совсем просто. Дай, я покажу!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8314,'Разгадка тайны','Мы на грани крупного прорыва, $n! Принесенные тобой оттиски позволили нам воссоздать письмена на хрустальной призме. Очевидно, что для киражи и прочих непонятных сущностей они имеют большое значение и позволяют передавать силитидам сообщения.$b$bК несчастью, это все, что нам удалось понять. Необходимо прочитать послания, сокрытые в кристаллах.$b$bОтнеси покрытую письменами хрустальную призму геологу Ехидной в Крепость Кенария. Может, она сумеет тебе помочь.','Принесите покрытую письменами хрустальную призму геологу Ехидной в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разгадка тайны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы на грани крупного прорыва, $n! Принесенные тобой оттиски позволили нам воссоздать письмена на хрустальной призме. Очевидно, что для киражи и прочих непонятных сущностей они имеют большое значение и позволяют передавать силитидам сообщения.$b$bК несчастью, это все, что нам удалось понять. Необходимо прочитать послания, сокрытые в кристаллах.$b$bОтнеси покрытую письменами хрустальную призму геологу Ехидной в Крепость Кенария. Может, она сумеет тебе помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите покрытую письменами хрустальную призму геологу Ехидной в Крепость Кенария, что в Силитусе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8315,'Зов','Здесь изображена встреча посланника киражи с тремя силитидами у костей большого дракона. Над рисунком я вижу надпись, судя по всему, какой-то шифр. Не исключено, что это ключевой момент призыва посланника.$b$bЯ создам копию, попробуй воспользоваться ей в пустыне у Костей Граккаронда. Если я права, вожди решат, что им посылают какие-то данные и явятся на зов. Убей их и сразись с посланником. Ключ к кристаллам у него...','Геолог Ехидная из Крепости Кенария просит добыть открыватель Кристаллов у киражского посланника.$b$bВам следует отнести письмена вызова к Костям Граккаронда, на юг от Крепости Кенария, и нарисовать их на песке. Если появится киражский посланник, убейте его и заберите открыватель Кристаллов. При успехе вернитесь к геологу Ехидной.$b$bДля выполнения задания понадобится целая армия!','20.000 лет истории у меня в руках!','Мы должны воспользоваться подходящей возможностью и нанести удар!','Вернитесь к геологу Ехидной в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь изображена встреча посланника киражи с тремя силитидами у костей большого дракона. Над рисунком я вижу надпись, судя по всему, какой-то шифр. Не исключено, что это ключевой момент призыва посланника.$b$bЯ создам копию, попробуй воспользоваться ей в пустыне у Костей Граккаронда. Если я права, вожди решат, что им посылают какие-то данные и явятся на зов. Убей их и сразись с посланником. Ключ к кристаллам у него...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Геолог Ехидная из Крепости Кенария просит добыть открыватель Кристаллов у киражского посланника.$b$bВам следует отнести письмена вызова к Костям Граккаронда, на юг от Крепости Кенария, и нарисовать их на песке. Если появится киражский посланник, убейте его и заберите открыватель Кристаллов. При успехе вернитесь к геологу Ехидной.$b$bДля выполнения задания понадобится целая армия!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','20.000 лет истории у меня в руках!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы должны воспользоваться подходящей возможностью и нанести удар!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Ехидной в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8316,'Оружие войны','Приходит война, $N, а с ней приходят невыразимые ужасы. Вы сделали все, что от вас требовали, и за это вы должны быть вознаграждены.$B$BЕсли это... это пророчество когда-нибудь сбудется...$B$B<Геолог Ларксбейн бледнеет.>$B$Bбудет конец нашему будущему.$B$BЭто вооружение окажется бесценным для вашей кампании в этой пустыне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие войны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приходит война, $N, а с ней приходят невыразимые ужасы. Вы сделали все, что от вас требовали, и за это вы должны быть вознаграждены.$B$BЕсли это... это пророчество когда-нибудь сбудется...$B$B<Геолог Ларксбейн бледнеет.>$B$Bбудет конец нашему будущему.$B$BЭто вооружение окажется бесценным для вашей кампании в этой пустыне.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8317,'Помощь по кухне','Рецепт мне несомненно пригодится. Пора приниматься за работу, чтобы приготовить копченые пустынные клецки уже сегодня. Мне не помешала бы помощь, а уж я бы тебе отплатила сторицей.','Каландрате из Крепости Кенария необходимы 10 копченых пустынных клецок.','Отлично! Ты мой спаситель. Не думала, что сторонники Сумеречного Молота могут придумать такой хороший рецепт.','Как идут дела с клецками?','Вернитесь к Каландрате в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь по кухне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рецепт мне несомненно пригодится. Пора приниматься за работу, чтобы приготовить копченые пустынные клецки уже сегодня. Мне не помешала бы помощь, а уж я бы тебе отплатила сторицей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Каландрате из Крепости Кенария необходимы 10 копченых пустынных клецок.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Ты мой спаситель. Не думала, что сторонники Сумеречного Молота могут придумать такой хороший рецепт.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идут дела с клецками?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каландрате в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8318,'Тайные послания','Некоторые из служителей культа Сумеречного Молота носят с собой листы бумаги, на которых нацарапана какая-то неразборчивая писанина. Принеси мне целую пачку таких писулек.$b$bЯ не могу понять, что означает эта ерунда, но дело не в том! При помощи этих бумажек происходят тайные переговоры их группировок. Чем больше текстов мы у них отнимем, тем сложнее им будет обмениваться сообщениями!','Великолепно! Уберу-ка я их подальше, они мне потом пригодятся.','Вернитесь к Бору Буйногривому в Улей Аши, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайные послания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некоторые из служителей культа Сумеречного Молота носят с собой листы бумаги, на которых нацарапана какая-то неразборчивая писанина. Принеси мне целую пачку таких писулек.$b$bЯ не могу понять, что означает эта ерунда, но дело не в том! При помощи этих бумажек происходят тайные переговоры их группировок. Чем больше текстов мы у них отнимем, тем сложнее им будет обмениваться сообщениями!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Уберу-ка я их подальше, они мне потом пригодятся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бору Буйногривому в Улей Аши, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8319,'Зашифрованные Сумеречные тексты','Превосходно! Я замолвлю за тебя доброе слово.','Можешь и дальше приносить мне тексты. Скоро мы выгоним Сумеречный Молот из Силитуса.','Вернитесь к Бору Буйногривому в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зашифрованные Сумеречные тексты',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Я замолвлю за тебя доброе слово.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Можешь и дальше приносить мне тексты. Скоро мы выгоним Сумеречный Молот из Силитуса.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бору Буйногривому в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8320,'Геолорды из культа Сумеречного Молота','Сумеречный Молот, безумная секта, поклоняющаяся богам смерти и разрушения, разбила лагеря по всему Силитусу и день и ночь проводит свои ритуалы. Планы ее стронников нам неизвестны, но они как-то связаны с пульсирующими красными кристаллами, разбросанными по всей пустыне.$b$bХотя, быть может, однажды нам удастся разгадать эту тайну, но сейчас главное – избавиться от угрозы. Ступай в их лагеря, что к западу отсюда, и найди там геолордов из культа Сумеречного Молота. Они командуют этими змеюками, поэтому нанести удар необходимо именно по ним!','Войдите в пустыню и найдите сумеречных геолордов, $N. Вернись ко мне после того, как они будут убиты.','Вернитесь к Хууму Буйногривому в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Геолорды из культа Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сумеречный Молот, безумная секта, поклоняющаяся богам смерти и разрушения, разбила лагеря по всему Силитусу и день и ночь проводит свои ритуалы. Планы ее стронников нам неизвестны, но они как-то связаны с пульсирующими красными кристаллами, разбросанными по всей пустыне.$b$bХотя, быть может, однажды нам удастся разгадать эту тайну, но сейчас главное – избавиться от угрозы. Ступай в их лагеря, что к западу отсюда, и найди там геолордов из культа Сумеречного Молота. Они командуют этими змеюками, поэтому нанести удар необходимо именно по ним!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Войдите в пустыню и найдите сумеречных геолордов, $N. Вернись ко мне после того, как они будут убиты.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хууму Буйногривому в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`,`questgivertargetname_loc8`) VALUES (8321,'Вайрал Подлый','Мы обнаружили еще одну базу Сумеречного Молота. Она зовется Сумеречная пещера и находится в северо-восточной части Силитуса. Их главарь, Вайрал Подлый, живет именно в этой пещере, и его-то тебе и предстоит победить. Одолев злодея, принеси мне его перстень-печатку.$b$bГоворят, что в Сумеречной пещере можно насмотреться таких ужасов, что век не забудешь.','Убейте Вайрала Подлого и заберите его перстень-печатку.','Получилось! Вайрал мертв! Что ж, нападение Сумеречного Молота на Силитус обречено на провал. Их здесь еще немало осталось, но они нескоро оправятся от сегодняшнего удара.','Тебе удалось победить Вайрала Подлого? Где его перстень-печатка?','Вернитесь к Хууму Буйногривому в Крепость Кенария, что в Силитусе.','Нечестивый предводитель сектантов, скрывающихся в Сумеречной пещере.','Вайрал Подлый') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вайрал Подлый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы обнаружили еще одну базу Сумеречного Молота. Она зовется Сумеречная пещера и находится в северо-восточной части Силитуса. Их главарь, Вайрал Подлый, живет именно в этой пещере, и его-то тебе и предстоит победить. Одолев злодея, принеси мне его перстень-печатку.$b$bГоворят, что в Сумеречной пещере можно насмотреться таких ужасов, что век не забудешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Вайрала Подлого и заберите его перстень-печатку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Получилось! Вайрал мертв! Что ж, нападение Сумеречного Молота на Силитус обречено на провал. Их здесь еще немало осталось, но они нескоро оправятся от сегодняшнего удара.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось победить Вайрала Подлого? Где его перстень-печатка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хууму Буйногривому в Крепость Кенария, что в Силитусе.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Нечестивый предводитель сектантов, скрывающихся в Сумеречной пещере.',`questgivertextwindow_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Вайрал Подлый',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8322,'Тухлые яйца','Люди Южнобережья любят эль, особенно тот, что подают в местной таверне. Думаю, тыквовинского хаоса им маловато – надо бы подпортить им недельный, а то и месячный запас выпивки!$B$BВозьмите вот эти тухлые яйца и подбросьте в главную бочку с пивом в таверне Южнобережья. Однако вашего присутствия там не потерпят, поэтому приготовьтесь защищаться!$B$BКак только угостите все Южнобережье этим незабываемым элем, возвращайтесь на наш фестиваль!','Бросьте тухлые яйца в главную бочку с пивом в таверне Южнобережья.','Пробившись в таверну, вы опускаете тухлые яйца в бочку. В воздухе разливается отвратительная вонь…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тухлые яйца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Люди Южнобережья любят эль, особенно тот, что подают в местной таверне. Думаю, тыквовинского хаоса им маловато – надо бы подпортить им недельный, а то и месячный запас выпивки!$B$BВозьмите вот эти тухлые яйца и подбросьте в главную бочку с пивом в таверне Южнобережья. Однако вашего присутствия там не потерпят, поэтому приготовьтесь защищаться!$B$BКак только угостите все Южнобережье этим незабываемым элем, возвращайтесь на наш фестиваль!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Бросьте тухлые яйца в главную бочку с пивом в таверне Южнобережья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пробившись в таверну, вы опускаете тухлые яйца в бочку. В воздухе разливается отвратительная вонь…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8323,'Истинно верующие','Теперь, когда у меня есть Сумеречный словарь, мне остается попросить тебя о небольшой услуге.$b$bВ моей бывшей организации ежемесячно издаются тщательно закодированные сводки новостей.$b$bЕсли они получат новые сведения обо мне или решат перестать меня искать, об этом сообщат в "Истинно верующем".$b$bХотя меня, безусловно, интересует подобная информация, в этих сводках могут быть и другие полезные сведения. Принеси мне как можно больше зашифрованных текстов, добытых у сторонников Сумеречного Молота.','Принесите 10 зашифрованных Сумеречных текстов отшельнику Ортеллу.','Великолепно! Я как можно скорее займусь расшифровкой. Если мне попадется интересная информация, я найду способ связаться с тобой.','Тебе удалось найти зашифрованные тексты? Мне было бы интересно заглянуть в свеженький номер "Истинно верующего".','Вернитесь к отшельнику Ортеллу в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истинно верующие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у меня есть Сумеречный словарь, мне остается попросить тебя о небольшой услуге.$b$bВ моей бывшей организации ежемесячно издаются тщательно закодированные сводки новостей.$b$bЕсли они получат новые сведения обо мне или решат перестать меня искать, об этом сообщат в "Истинно верующем".$b$bХотя меня, безусловно, интересует подобная информация, в этих сводках могут быть и другие полезные сведения. Принеси мне как можно больше зашифрованных текстов, добытых у сторонников Сумеречного Молота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 зашифрованных Сумеречных текстов отшельнику Ортеллу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Я как можно скорее займусь расшифровкой. Если мне попадется интересная информация, я найду способ связаться с тобой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти зашифрованные тексты? Мне было бы интересно заглянуть в свеженький номер "Истинно верующего".',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к отшельнику Ортеллу в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8324,'Не теряя веры','Великолепно! Если тебе снова попадутся зашифрованные тексты, сразу неси мне.','Ты $нашел:нашла; новые зашифрованные тексты? Принеси мне целую кипу, на расшифровку уходит немало времени.','Вернитесь к отшельнику Ортеллу в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не теряя веры',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Если тебе снова попадутся зашифрованные тексты, сразу неси мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $нашел:нашла; новые зашифрованные тексты? Принеси мне целую кипу, на расшифровку уходит немало времени.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к отшельнику Ортеллу в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8325,'Убейте 6 маназмеев – они находятся у пламенеющих кристаллов, недалеко от башни и беседки.','Наша работа по восстановлению нашего общества начинается здесь, $N. Как только мы будем в состоянии обезопасить наш дом, мы сможем больше осмотреть и Запределье.','Вернитесь к магистру Эроне на Остров Солнечного Скитальца, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 маназмеев – они находятся у пламенеющих кристаллов, недалеко от башни и беседки.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наша работа по восстановлению нашего общества начинается здесь, $N. Как только мы будем в состоянии обезопасить наш дом, мы сможем больше осмотреть и Запределье.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Эроне на Остров Солнечного Скитальца, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8326,'Вынужденные меры','Вернитесь к магистру Эроне на Остров Солнечного Скитальца, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вынужденные меры',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Эроне на Остров Солнечного Скитальца, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8326,'Теперь башня и ее окрестности станут относительно безопасными, пусть и ненадолго. Ты хорошо потрудился, но если мы хотим здесь прочно обосноваться, необходимо взять под контроль весь остров. А для этого придется сталкиваться с куда более грозными противниками, чем обезумевшие маназмеи и рыси.$B$BВозьми мой подарок, Адраан, он тебе, несомненно, пригодится в дальнейшем.','Мне не доставляет никакого удовольствия просить тебя убивать этих животных. В прошлом мы жили в относительной гармонии с лесными тварями, но настали другие времена. Главная задача син\'дорай – выжить. Помни об этом.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь башня и ее окрестности станут относительно безопасными, пусть и ненадолго. Ты хорошо потрудился, но если мы хотим здесь прочно обосноваться, необходимо взять под контроль весь остров. А для этого придется сталкиваться с куда более грозными противниками, чем обезумевшие маназмеи и рыси.$B$BВозьми мой подарок, Адраан, он тебе, несомненно, пригодится в дальнейшем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне не доставляет никакого удовольствия просить тебя убивать этих животных. В прошлом мы жили в относительной гармонии с лесными тварями, но настали другие времена. Главная задача син\'дорай – выжить. Помни об этом.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8327,'Визит к Лантану Перилону') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Визит к Лантану Перилону',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (8327,'Адраан, магистр Эрона говорила мне, что ты скоро прибудешь. Видишь на западе высокое здание с резными шпилями, парящее в воздухе? Это Академия Фалтриена. Тебе предстоит отбить ее у одного из Презренных – эльфов крови, поддавшихся своим самым низменным страстям.$B$BНадеюсь, ты готов к битве. Это станет для тебя не просто уроком доблести, но и примером того, что с тобой случится, если ты забудешь о том, кто ты есть.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Адраан, магистр Эрона говорила мне, что ты скоро прибудешь. Видишь на западе высокое здание с резными шпилями, парящее в воздухе? Это Академия Фалтриена. Тебе предстоит отбить ее у одного из Презренных – эльфов крови, поддавшихся своим самым низменным страстям.$B$BНадеюсь, ты готов к битве. Это станет для тебя не просто уроком доблести, но и примером того, что с тобой случится, если ты забудешь о том, кто ты есть.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8330,'Отлично! Я знал, что ты прекрасно справишься. Как только мы почувствуем себя в безопасности на этом острове, я сумею найти этим вещам хорошее применение.$B$BКак я и обещал, сумка теперь твоя. Также прими этот доспех – он тебе пригодится. Думаю, это справедливая награда!','Тебе удалось найти мои вещи? Как только мы укрепим нашу власть на Острове Солнечного Скитальца, они понадобятся мне для работы. А пока я должен следить за Колодцем... точнее за тем, что от него осталось.','Вернитесь к хранителю Колодца Соланиану в Солнечный Шпиль, что на Острове Солнечного Скитальца.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Я знал, что ты прекрасно справишься. Как только мы почувствуем себя в безопасности на этом острове, я сумею найти этим вещам хорошее применение.$B$BКак я и обещал, сумка теперь твоя. Также прими этот доспех – он тебе пригодится. Думаю, это справедливая награда!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти мои вещи? Как только мы укрепим нашу власть на Острове Солнечного Скитальца, они понадобятся мне для работы. А пока я должен следить за Колодцем... точнее за тем, что от него осталось.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Колодца Соланиану в Солнечный Шпиль, что на Острове Солнечного Скитальца.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8331,'Аурель Золотой Лист','Мы надеялись, что Сумеречный Молот свернет свои операции в Силитусе... Увы, мы ошиблись. Благодаря постоянным нападением на лагеря сектантов нам удалось выяснить, что Молот контролирует еще более страшная сила, Совет Бездны. Для связи со служителями культа этот совет пользуется ветровыми камнями, рассеянными по лагерям Молота. Пришло время выступить против Совета Бездны.$b$bПоговори с ремесленницей Аурель Золотой Лист, в восточной части Крепости Кенария. Мы задумали одну хитрость, для которой необходимо ее искусство.','Поговорите с Аурель Золотой Лист в Крепости Кенария.','Добрый день, $N. Говорят, ты собираешься выступить против Совета Бездны? Коли так, слушай внимательно...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аурель Золотой Лист',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы надеялись, что Сумеречный Молот свернет свои операции в Силитусе... Увы, мы ошиблись. Благодаря постоянным нападением на лагеря сектантов нам удалось выяснить, что Молот контролирует еще более страшная сила, Совет Бездны. Для связи со служителями культа этот совет пользуется ветровыми камнями, рассеянными по лагерям Молота. Пришло время выступить против Совета Бездны.$b$bПоговори с ремесленницей Аурель Золотой Лист, в восточной части Крепости Кенария. Мы задумали одну хитрость, для которой необходимо ее искусство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аурель Золотой Лист в Крепости Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добрый день, $N. Говорят, ты собираешься выступить против Совета Бездны? Коли так, слушай внимательно...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8332,'Герцоги Совета','Мы думаем, что при помощи ветрового камня можно устроить засаду на герцога Совета Бездны. Для этого придется связаться с Советом через этот камень и убедить всех, что ты – $gодин:одна; из командующих среднего ранга Сумеречного Молота.$b$bЧтобы эта хитрость удалась, необходим статусный медальон. Я могу создать его, но мне понадобится большой сверкающий осколок и талисманы храмовников Бездны.$b$BПринеси их мне, а остальное я сделаю сама.','Принесите Аурель Золотой Лист в Крепость Кенария 1 большой сверкающий осколок и 3 талисмана Бездны.','Ах, очень хорошо. Я работал над медальоном - теперь с этими последними ингредиентами, я буду готов через несколько минут...$B$BВот и мы. Вот медальон, $N.$B$BВам нужно будет надеть это, когда вы активируете один из ветряных камней Сумеречного Молота. Наденьте это вместе с остальными сумеречными атрибутами, и Совет Бездны увидит в вас одного из своих сектантов.','У тебя есть осколок и герб, $N? Они мне понадобятся, чтобы сделать медальон сумеречного культиста.','Вернитесь к Аурели Золотому Листу в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Герцоги Совета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы думаем, что при помощи ветрового камня можно устроить засаду на герцога Совета Бездны. Для этого придется связаться с Советом через этот камень и убедить всех, что ты – $gодин:одна; из командующих среднего ранга Сумеречного Молота.$b$bЧтобы эта хитрость удалась, необходим статусный медальон. Я могу создать его, но мне понадобится большой сверкающий осколок и талисманы храмовников Бездны.$b$BПринеси их мне, а остальное я сделаю сама.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Аурель Золотой Лист в Крепость Кенария 1 большой сверкающий осколок и 3 талисмана Бездны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, очень хорошо. Я работал над медальоном - теперь с этими последними ингредиентами, я буду готов через несколько минут...$B$BВот и мы. Вот медальон, $N.$B$BВам нужно будет надеть это, когда вы активируете один из ветряных камней Сумеречного Молота. Наденьте это вместе с остальными сумеречными атрибутами, и Совет Бездны увидит в вас одного из своих сектантов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть осколок и герб, $N? Они мне понадобятся, чтобы сделать медальон сумеречного культиста.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аурели Золотому Листу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8333,'Статусный медальон','Вот ты где, $N. Еще один сумеречный медальон. Используй его как следует, и я желаю тебе удачи против Совета Бездны!','Если тебе понадобится еще один станционный медальон служителя Сумрака, я с радостью помогу тебе. Но мне понадобится еще один осколок и несколько талисманов Бездны…','Вернитесь к Аурели Золотому Листу в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Статусный медальон',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот ты где, $N. Еще один сумеречный медальон. Используй его как следует, и я желаю тебе удачи против Совета Бездны!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если тебе понадобится еще один станционный медальон служителя Сумрака, я с радостью помогу тебе. Но мне понадобится еще один осколок и несколько талисманов Бездны…',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аурели Золотому Листу в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8334,'Агрессия','Лучше будет если ты узнаешь о выживании, и цене на выживание сейчас, чем позже. Как эльфу крови, тебе нужно привыкнуть к тому, что в чем-то придется делать нелегкий выбор.$B$BКогда Плеть разрывала наш дом надвое, здесь некому было помочь нам. И нам пришлось самим себя вытягивать из этой петли.','Вернитесь к Лантану Перилону на Остров Солнечного Скитальца, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Агрессия',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лучше будет если ты узнаешь о выживании, и цене на выживание сейчас, чем позже. Как эльфу крови, тебе нужно привыкнуть к тому, что в чем-то придется делать нелегкий выбор.$B$BКогда Плеть разрывала наш дом надвое, здесь некому было помочь нам. И нам пришлось самим себя вытягивать из этой петли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лантану Перилону на Остров Солнечного Скитальца, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8335,'Фелендрен Изгой','Вернитесь к Лантану Перилону на Остров Солнечного Скитальца, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фелендрен Изгой',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лантану Перилону на Остров Солнечного Скитальца, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (8335,'Помни: Фелендрен Изгой – всего лишь вестник куда большей беды. Его уничтожение решит лишь наши сегодняшние проблемы, но всем эльфам крови грозит та же участь, если мы не научимся обуздывать свою тягу к магии.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Помни: Фелендрен Изгой – всего лишь вестник куда большей беды. Его уничтожение решит лишь наши сегодняшние проблемы, но всем эльфам крови грозит та же участь, если мы не научимся обуздывать свою тягу к магии.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8336,'Очень жаль, что мы утратили контроль над многими существами этого острова. Некогда это был оплот спокойствия, трудов и исследований. Теперь мы только и делаем, что отбиваемся от нападений собственных созданий!$B$BВыполни для меня небольшое поручение и получишь волшебный дар. Принеси мне горсть магических осколков. Ты можешь найти их у существ, обладающих магическими способностями. В награду за это я наложу на тебя заклятие, которое поможет тебе в твоих приключениях.','Соберите 6 магических осколков, убивая любых существ, обладающих магическими способностями, а затем вернитесь к чародею Итанасу.','Замечательно! Как раз то, что нужно. Я много размышлял о проклятии, поразившем Остров Солнечного Скитальца. Одно из возможных решений проблемы – собирать магические осколки и проводить эксперименты над ними. Не лучший путь, но другого я пока не вижу.$B$BКак бы то ни было, я продолжу свои исследования. Сейчас я наложу на тебя заклятие. Уверен, оно тебе поможет!','Некогда при помощи магии мы подчинили себе многие существа этого острова. Но когда Плеть уничтожила Солнечный Колодец, наша власть над здешними животными ослабла. Магические осколки – все, что осталось от наших заклинаний, и мы надеемся создать из них новое устройство, чтобы вновь подчинить себе местную фауну.$B$BВозможно, осколки также помогут нам понять, что за проклятие поразило наш остров...','Вернитесь к чародею Итанасу на Остров Солнечного Скитальца, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Очень жаль, что мы утратили контроль над многими существами этого острова. Некогда это был оплот спокойствия, трудов и исследований. Теперь мы только и делаем, что отбиваемся от нападений собственных созданий!$B$BВыполни для меня небольшое поручение и получишь волшебный дар. Принеси мне горсть магических осколков. Ты можешь найти их у существ, обладающих магическими способностями. В награду за это я наложу на тебя заклятие, которое поможет тебе в твоих приключениях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 магических осколков, убивая любых существ, обладающих магическими способностями, а затем вернитесь к чародею Итанасу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Как раз то, что нужно. Я много размышлял о проклятии, поразившем Остров Солнечного Скитальца. Одно из возможных решений проблемы – собирать магические осколки и проводить эксперименты над ними. Не лучший путь, но другого я пока не вижу.$B$BКак бы то ни было, я продолжу свои исследования. Сейчас я наложу на тебя заклятие. Уверен, оно тебе поможет!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Некогда при помощи магии мы подчинили себе многие существа этого острова. Но когда Плеть уничтожила Солнечный Колодец, наша власть над здешними животными ослабла. Магические осколки – все, что осталось от наших заклинаний, и мы надеемся создать из них новое устройство, чтобы вновь подчинить себе местную фауну.$B$BВозможно, осколки также помогут нам понять, что за проклятие поразило наш остров...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Итанасу на Остров Солнечного Скитальца, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8337,'<UNUSED>','Вернитесь к чародею Итанасу в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Итанасу в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8338,'Оскверненный магический осколок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный магический осколок',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8338,'Как интересно... Когда я говорю "интересно", это значит, что я крайне взволнован.$B$BВосстановление контроля над островом после разрушения Солнечного Колодца – задача чрезвычайно тяжелая. Подозреваю, что за всеми нашими бедами стоит одна и та же злая сила, и этот осколок поможет мне понять, что же на самом деле происходит.$B$BТы мудро поступил, принеся его мне, Адраан. Вот, возьми это в награду за предусмотрительность. Благодарю тебя.','Судя по всему, у тебя какое-то срочное дело. Чем я могу помочь?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как интересно... Когда я говорю "интересно", это значит, что я крайне взволнован.$B$BВосстановление контроля над островом после разрушения Солнечного Колодца – задача чрезвычайно тяжелая. Подозреваю, что за всеми нашими бедами стоит одна и та же злая сила, и этот осколок поможет мне понять, что же на самом деле происходит.$B$BТы мудро поступил, принеся его мне, Адраан. Вот, возьми это в награду за предусмотрительность. Благодарю тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Судя по всему, у тебя какое-то срочное дело. Чем я могу помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8339,'Обмануть Совет<NYI> <TXT> UNUSED','Чтобы сделать перстень-печатку сумеречного сектанта, мне понадобится куча предметов.','Принесите предметы Аурель Золотой Лист в Крепость Кенария.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обмануть Совет<NYI> <TXT> UNUSED',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы сделать перстень-печатку сумеречного сектанта, мне понадобится куча предметов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите предметы Аурель Золотой Лист в Крепость Кенария.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8340,'Сумеречный перстень-печатка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречный перстень-печатка',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8341,'Лорды Совета','Чтобы вызвать лордов Совета Бездны, необходим больший ветровой камень. К тому же они согласны беседовать лишь с самыми высокопоставленными представителями Сумеречного Молота. Но... Я придумала, как поработать над твоей маскировкой и обмануть лордов Бездны!$b$bДля этого понадобится кольцо Власти, которое носят лишь вожди сектантов. Я готова создать такое кольцо, если ты принесешь мне большие сверкающие осколки и перстни Бездны.','Принесите Аурель Золотой Лист в Крепость Кенария 5 больших сверкающих осколков и 3 перстня Бездны.','Спасибо. Минуточку, и я приготовлю тебе кольцо...$B$BВот оно. Теперь ты $Gготов:готова;.$B$BОбязательно надень это кольцо вместе с медальоном и остальной сумеречной атрибутикой, когда активируешь большой камень ветра. Сделай это, и Совет Бездны сочтет тебя своим слугой. Тогда, возможно, тебе удастся заманить их в засаду!','У тебя есть осколки и печатки, $N? Они мне понадобятся, чтобы создать кольцо светлости.','Вернитесь к Аурели Золотому Листу в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лорды Совета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы вызвать лордов Совета Бездны, необходим больший ветровой камень. К тому же они согласны беседовать лишь с самыми высокопоставленными представителями Сумеречного Молота. Но... Я придумала, как поработать над твоей маскировкой и обмануть лордов Бездны!$b$bДля этого понадобится кольцо Власти, которое носят лишь вожди сектантов. Я готова создать такое кольцо, если ты принесешь мне большие сверкающие осколки и перстни Бездны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Аурель Золотой Лист в Крепость Кенария 5 больших сверкающих осколков и 3 перстня Бездны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо. Минуточку, и я приготовлю тебе кольцо...$B$BВот оно. Теперь ты $Gготов:готова;.$B$BОбязательно надень это кольцо вместе с медальоном и остальной сумеречной атрибутикой, когда активируешь большой камень ветра. Сделай это, и Совет Бездны сочтет тебя своим слугой. Тогда, возможно, тебе удастся заманить их в засаду!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть осколки и печатки, $N? Они мне понадобятся, чтобы создать кольцо светлости.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аурели Золотому Листу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8342,'Кольцо Власти служителя культа Сумеречного Молота','Ах, я вижу, у вас сильные убеждения. Не многие столкнутся с этим советом демонов!$B$BВот твое кольцо, $N. Да сохранятся твоя воля и твоя удача.','$N, если ты собираешься вновь выступить против Высшего Совета Бездны, тебе понадобится еще одно кольцо Власти служителя Сумрака. Принеси мне еще несколько осколков и перстней, и я сделаю такое кольцо.','Вернитесь к Аурели Золотому Листу в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо Власти служителя культа Сумеречного Молота',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, я вижу, у вас сильные убеждения. Не многие столкнутся с этим советом демонов!$B$BВот твое кольцо, $N. Да сохранятся твоя воля и твоя удача.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, если ты собираешься вновь выступить против Высшего Совета Бездны, тебе понадобится еще одно кольцо Власти служителя Сумрака. Принеси мне еще несколько осколков и перстней, и я сделаю такое кольцо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аурели Золотому Листу в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8343,'Открытие Золотого Листа','$n, Аурель придумала, как вызвать и одолеть правящую верхушку Совета Бездны! Это опасно, но ты $gзаслужил:заслужила; уважение всего Круга Кенария. Мы знаем, что ты – $gединственный:единственная;, кому по плечу такое задание.$B$BЖелаю удачи, $n. Когда решишь приняться за это задание, поговори с Аурель.','Поговорите с Аурель Золотой Лист в Крепости Кенария.','Хуум говорит правду. Думаю, я знаю, как вызвать лорда Совета Бездны. Слушай внимательно...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Открытие Золотого Листа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, Аурель придумала, как вызвать и одолеть правящую верхушку Совета Бездны! Это опасно, но ты $gзаслужил:заслужила; уважение всего Круга Кенария. Мы знаем, что ты – $gединственный:единственная;, кому по плечу такое задание.$B$BЖелаю удачи, $n. Когда решишь приняться за это задание, поговори с Аурель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аурель Золотой Лист в Крепости Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хуум говорит правду. Думаю, я знаю, как вызвать лорда Совета Бездны. Слушай внимательно...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8344,'Постижение основ','Принесите 4 призрачные сущности и 1 оскверненную призрачную сущность призывателю Тель\'Лариену в Солнечный Шпиль на Остров Солнечного Скитальца.','Отлично сработано! Да, этого должно быть достаточно, чтобы приступить к моему исследованию. У меня есть сильное предчувствие, что эта испорченная сущность будет просто вещью... , как я уже упоминал.$B$BМолодым $C очень рекомендуется следовать указаниям своих мастеров. Как я и обещал, вот награда за соблюдение инструкций и их компетентное выполнение - знание, позволяющее призывать и связывать своего собственного беса.$B$BИспользуйте это правильно, $N.','Сущности призраков послужат мне хорошим источником экспериментов. Как и твоя жизнь в качестве $C, важно учиться тому, что мы находим в мире... прежде, чем подчинять это своей воле. Поскольку демоны являются самым богатым источником силы, будет большим благом, если такая зараза действительно присутствует на острове.$B$BЧто ж... это благо для нас, чернокнижников.','Вернитесь к призывателю Тель’лариену в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Постижение основ',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 призрачные сущности и 1 оскверненную призрачную сущность призывателю Тель\'Лариену в Солнечный Шпиль на Остров Солнечного Скитальца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано! Да, этого должно быть достаточно, чтобы приступить к моему исследованию. У меня есть сильное предчувствие, что эта испорченная сущность будет просто вещью... , как я уже упоминал.$B$BМолодым $C очень рекомендуется следовать указаниям своих мастеров. Как я и обещал, вот награда за соблюдение инструкций и их компетентное выполнение - знание, позволяющее призывать и связывать своего собственного беса.$B$BИспользуйте это правильно, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сущности призраков послужат мне хорошим источником экспериментов. Как и твоя жизнь в качестве $C, важно учиться тому, что мы находим в мире... прежде, чем подчинять это своей воле. Поскольку демоны являются самым богатым источником силы, будет большим благом, если такая зараза действительно присутствует на острове.$B$BЧто ж... это благо для нас, чернокнижников.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывателю Тель’лариену в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8345,'Ах, $n, благодарю тебя за то, что ты $gпосетил:посетила; святилище Дат\'Ремара. Прежде всего следует похвалить тебя за чувство долга и почтительность - они послужат тебе не только здесь, но и повсюду в Азероте.$B$BЧто до странных ощущений - несомненно, это от порчи, поразившей Остров Солнечного Скитальца. Мы обратим на это внимание; спасибо за предупреждение!','$GПрочел:Прочла; ли ты надпись на святилище, $C?','Вернитесь к хранителю Колодца Соланиану на Остров Солнечного Скитальца, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, $n, благодарю тебя за то, что ты $gпосетил:посетила; святилище Дат\'Ремара. Прежде всего следует похвалить тебя за чувство долга и почтительность - они послужат тебе не только здесь, но и повсюду в Азероте.$B$BЧто до странных ощущений - несомненно, это от порчи, поразившей Остров Солнечного Скитальца. Мы обратим на это внимание; спасибо за предупреждение!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GПрочел:Прочла; ли ты надпись на святилище, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Колодца Соланиану на Остров Солнечного Скитальца, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8346,'А, $N. Ты $Gвыполнил:выполнила; свою задачу?','Вернитесь к чародею Хелиону на Остров Солнечного Скитальца, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, $N. Ты $Gвыполнил:выполнила; свою задачу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Хелиону на Остров Солнечного Скитальца, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8348,'Перстень герцогов','Хуум говорит, что ты $gпридумал:придумала;, как вызвать герцогов Бездны! Это большое достижение.$b$bЗнаешь, что бы еще хорошо сделать? Убить одного из них. Это произвело бы неизгладимое впечатление на их прихвостней, если ты понимаешь, о чем я. В доказательство собственного подвига принеси перстень герцога.','Принесите перстень Бездны Бору Буйногривому из Крепости Кенария.','Стоило тебе войти в крепость Кенария, и я сразу понял, что передо мной могучий $C. Так держать!','Как дела с герцогом Бездны? Трудно пришлось?','Вернитесь к Бору Буйногривому в Улей Аши, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перстень герцогов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хуум говорит, что ты $gпридумал:придумала;, как вызвать герцогов Бездны! Это большое достижение.$b$bЗнаешь, что бы еще хорошо сделать? Убить одного из них. Это произвело бы неизгладимое впечатление на их прихвостней, если ты понимаешь, о чем я. В доказательство собственного подвига принеси перстень герцога.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите перстень Бездны Бору Буйногривому из Крепости Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Стоило тебе войти в крепость Кенария, и я сразу понял, что передо мной могучий $C. Так держать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как дела с герцогом Бездны? Трудно пришлось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бору Буйногривому в Улей Аши, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8349,'Бор Буйногривый','Теперь у тебя есть медальон, и ты можешь вызвать герцога Бездны. Поговори с Бором Буйногривым. Он даст тебе задание.$b$bУдачи, $n. Если тебе снова понадобятся медальоны, возвращайся ко мне.','Поговорите с Бором Буйногривым из Крепости Кенария.','Рад видеть тебя, $C! Значит, теперь у тебя есть медальон? Хорошо – он понадобится тебе для следующего задания...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бор Буйногривый',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь у тебя есть медальон, и ты можешь вызвать герцога Бездны. Поговори с Бором Буйногривым. Он даст тебе задание.$b$bУдачи, $n. Если тебе снова понадобятся медальоны, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бором Буйногривым из Крепости Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад видеть тебя, $C! Значит, теперь у тебя есть медальон? Хорошо – он понадобится тебе для следующего задания...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8351,'Разговор с Бором','Теперь ты можешь замаскироваться под высокопоставленного представителя Сумрачного Совета, и с тобой хочет поговорить Бор Буйногривый. Ступай, поговори с ним и готовься к трудному заданию...','Поговорите с Бором Буйногривым из Крепости Кенария.','Да, правильно, $N. У меня впереди очень сложная задача...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Бором',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь ты можешь замаскироваться под высокопоставленного представителя Сумрачного Совета, и с тобой хочет поговорить Бор Буйногривый. Ступай, поговори с ним и готовься к трудному заданию...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бором Буйногривым из Крепости Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, правильно, $N. У меня впереди очень сложная задача...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8352,'Скипетр Совета','Мы с Хуумом только что обсуждали тебя. Он говорит, что ты $gготов:готова; испытать себя и сразиться с лордом Бездны!$b$bДолжен предупредить, что это очень опасно. Возьми с собой подкрепление. И не пару друзей, а хороший боевой отряд. Если твои друзья стоят тебя, кто знает, может быть, удастся одолеть этого лорда!$b$bЕсли ты вдруг справишься – мне как всегда потребуются доказательства – то тебя ждет великая награда.','Принесите скипетр Бездны Бору Буйногривому из Крепости Кенария.','Ну как все прошло?','Вернитесь к Бору Буйногривому в Улей Аши, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скипетр Совета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с Хуумом только что обсуждали тебя. Он говорит, что ты $gготов:готова; испытать себя и сразиться с лордом Бездны!$b$bДолжен предупредить, что это очень опасно. Возьми с собой подкрепление. И не пару друзей, а хороший боевой отряд. Если твои друзья стоят тебя, кто знает, может быть, удастся одолеть этого лорда!$b$bЕсли ты вдруг справишься – мне как всегда потребуются доказательства – то тебя ждет великая награда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите скипетр Бездны Бору Буйногривому из Крепости Кенария.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как все прошло?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бору Буйногривому в Улей Аши, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8353,'Курочка с мятой','А, тыквовинничаем для больных деток? Я сказал бы, ты малость $Gстароват:старовата; конфетки выпрашивать...$B$BЧто же, за мое лакомство – мятную конфету Стальгорна – ты... поквохчешь как курица! Да, курочки любят мятные конфетки... впрочем, может и не любят... главное, что конфетку ты не получишь, пока не поквохчешь!$B$BНу что, |3-6($c), будешь квохтать или нет?! Пора отрабатывать лакомство!','Изобразите курицу для хозяина таверны Огневара.','Ой, забавно! Просто здорово, $n! Вот твое угощение.$B$BВеселого Тыквовина!','Вернитесь к хозяину таверны Огневару в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Курочка с мятой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, тыквовинничаем для больных деток? Я сказал бы, ты малость $Gстароват:старовата; конфетки выпрашивать...$B$BЧто же, за мое лакомство – мятную конфету Стальгорна – ты... поквохчешь как курица! Да, курочки любят мятные конфетки... впрочем, может и не любят... главное, что конфетку ты не получишь, пока не поквохчешь!$B$BНу что, |3-6($c), будешь квохтать или нет?! Пора отрабатывать лакомство!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изобразите курицу для хозяина таверны Огневара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, забавно! Просто здорово, $n! Вот твое угощение.$B$BВеселого Тыквовина!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хозяину таверны Огневару в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8354,'Курочка с мятой','А, ты у нас сегодня вместо детишек, да? Я сказал бы, ты малость $Gстароват:старовата; конфетки выпрашивать...$B$BЧто же, за мое лакомство – мятную конфету Подгорода – ты... поквохчешь как курица! Да, курочки любят мятные конфетки... впрочем, им не обязательно их ЛЮБИТЬ... главное, что конфетку ты не получишь, пока не поквохчешь!$B$BНу что, |3-6($c), будешь квохтать или нет?! Пора отрабатывать лакомство!','Изобразите курицу для хозяина таверны Нормана и получите за это конфету Подгорода!','Вернитесь к хозяину таверны Норману в Тирисфальские леса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Курочка с мятой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, ты у нас сегодня вместо детишек, да? Я сказал бы, ты малость $Gстароват:старовата; конфетки выпрашивать...$B$BЧто же, за мое лакомство – мятную конфету Подгорода – ты... поквохчешь как курица! Да, курочки любят мятные конфетки... впрочем, им не обязательно их ЛЮБИТЬ... главное, что конфетку ты не получишь, пока не поквохчешь!$B$BНу что, |3-6($c), будешь квохтать или нет?! Пора отрабатывать лакомство!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изобразите курицу для хозяина таверны Нормана и получите за это конфету Подгорода!',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хозяину таверны Норману в Тирисфальские леса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8355,'Плата за леденцы','А, тебе нужны сладости! Ха-ха!$B$BНу, хотя ты и доброе дело делаешь, собирая сладости для детишек, так просто я тебя не отпущу. Есть у меня вкусные леденцы Гномрегана, и я отдам их детишкам... если ты изобразишь мне паровоз! Ха, вот это будет штука! За паровоз – целый леденец!$B$BТу-ту, |3-6($c)!','Изобразите паровозик для Талваша дель Кисселя.','У-у-у! Великолепно, $n! Вот твои сладости.$B$BСчастливого Тыквовина!','Ну, а теперь продолжайте...','Вернитесь к Талвашу дель Кисселю в Стальгорн.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плата за леденцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, тебе нужны сладости! Ха-ха!$B$BНу, хотя ты и доброе дело делаешь, собирая сладости для детишек, так просто я тебя не отпущу. Есть у меня вкусные леденцы Гномрегана, и я отдам их детишкам... если ты изобразишь мне паровоз! Ха, вот это будет штука! За паровоз – целый леденец!$B$BТу-ту, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изобразите паровозик для Талваша дель Кисселя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У-у-у! Великолепно, $n! Вот твои сладости.$B$BСчастливого Тыквовина!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, а теперь продолжайте...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талвашу дель Кисселю в Стальгорн.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8356,'Поиграй мускулами!','Какой у тебя... интересный костюмчик. Несмотря на то, что ты по доброте своей помогаешь ребенку получить сладости, мне все же придется попросить тебя сделать что-нибудь!$b$bНу-ка, ну-ка... ты выглядишь $gтаким сильным и мускулистым:такой сильной и мускулистой; в этом... наряде... посмотрим-ка на твои бицепсы! Да, давай, поиграй-ка мускулами, $gсилач:силачка;!$b$bПоиграешь мускулами – дам тебе вкуснейшей нуги. Это отличное тыквовинское угощение!','Поиграйте мускулами перед хозяйкой таверны Аллисон и получите от нее за это нугу из Штормграда.','Вернитесь к хозяйке таверны Аллисон в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиграй мускулами!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какой у тебя... интересный костюмчик. Несмотря на то, что ты по доброте своей помогаешь ребенку получить сладости, мне все же придется попросить тебя сделать что-нибудь!$b$bНу-ка, ну-ка... ты выглядишь $gтаким сильным и мускулистым:такой сильной и мускулистой; в этом... наряде... посмотрим-ка на твои бицепсы! Да, давай, поиграй-ка мускулами, $gсилач:силачка;!$b$bПоиграешь мускулами – дам тебе вкуснейшей нуги. Это отличное тыквовинское угощение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поиграйте мускулами перед хозяйкой таверны Аллисон и получите от нее за это нугу из Штормграда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хозяйке таверны Аллисон в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8357,'Танец за марципан','Хоть это и не твоя прямая обязанность, лакомство тебе придется отработать! От традиции, пожалуй, отходить не будем...$B$BДумаю, я отдам тебе марципан за... ТАНЕЦ! Да-да, покажи, как ты пляшешь! Попляши для меня, и я дам тебе вкусный марципанчик!','Потанцуйте для хозяйки таверны Салиенны, и за это вы получите марципан Дарнаса!','Да тебе стоило бы в балет податься, $n!$B$BВот твоя награда за чудесное развлечение. Веселого тебе тыквовина, и передай привет больным детишкам! Пусть быстрее поправляются.','Ты же знаешь, как танцевать? Попробуй поставить вот эту ногу сюда... а вот эту сюда... теперь вот так...','Вернитесь к хозяйке таверны Салиенне в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танец за марципан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хоть это и не твоя прямая обязанность, лакомство тебе придется отработать! От традиции, пожалуй, отходить не будем...$B$BДумаю, я отдам тебе марципан за... ТАНЕЦ! Да-да, покажи, как ты пляшешь! Попляши для меня, и я дам тебе вкусный марципанчик!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потанцуйте для хозяйки таверны Салиенны, и за это вы получите марципан Дарнаса!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да тебе стоило бы в балет податься, $n!$B$BВот твоя награда за чудесное развлечение. Веселого тебе тыквовина, и передай привет больным детишкам! Пусть быстрее поправляются.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты же знаешь, как танцевать? Попробуй поставить вот эту ногу сюда... а вот эту сюда... теперь вот так...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хозяйке таверны Салиенне в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8358,'Плата за леденцы','А, тебе нужны сладости? Ну-ну!$b$bЗаруби себе на носу: ты, конечно, занимаешься благородным делом, собираешь сласти для ребенка, но без платы ты ничего не получишь! У меня как раз имеется сладкий-пресладкий леденец троллей Черного Копья, девочка ему будет очень рада... но сначала изобрази-ка ты мне паровозик! То-то я посмеюсь! Посмотри, какой замечательный леденец – а всего-то и надо изобразить паровозик!$b$bНу-ка, |3-6($c)! Чух-чух-чух-чух!','Изобразите паровозик перед Кали Ремик и получите в награду леденец троллей Черного Копья!','Ну, а теперь продолжайте...','Вернитесь к Кали Ремик на Аллею Духов, что в Оргриммаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плата за леденцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, тебе нужны сладости? Ну-ну!$b$bЗаруби себе на носу: ты, конечно, занимаешься благородным делом, собираешь сласти для ребенка, но без платы ты ничего не получишь! У меня как раз имеется сладкий-пресладкий леденец троллей Черного Копья, девочка ему будет очень рада... но сначала изобрази-ка ты мне паровозик! То-то я посмеюсь! Посмотри, какой замечательный леденец – а всего-то и надо изобразить паровозик!$b$bНу-ка, |3-6($c)! Чух-чух-чух-чух!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изобразите паровозик перед Кали Ремик и получите в награду леденец троллей Черного Копья!',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, а теперь продолжайте...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кали Ремик на Аллею Духов, что в Оргриммаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8359,'Поиграй мускулами!','Ой, какой интересненький костюмчик! Нет, ты, конечно, $gхороший мальчик:хорошая девочка;, раз помогаешь ребенку собрать сладости, но, боюсь, тебе все же придется выполнить для меня какое-нибудь задание, прежде чем ты получишь конфету.$b$bДай-ка подумать... У тебя такой накачанный вид в этом... костюмчике! Поиграй-ка мускулами!$b$bА я тебе за это дам вкусной оргриммарской нуги. Дети ее очень любят!','Поиграйте мускулами перед хозяйкой таверны Гришкой и получите от нее за это нугу из Оргриммара.','Никаких конфет, пока не поиграешь мускулами для меня, $N...','Вернитесь к трактирщице Гришке в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиграй мускулами!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ой, какой интересненький костюмчик! Нет, ты, конечно, $gхороший мальчик:хорошая девочка;, раз помогаешь ребенку собрать сладости, но, боюсь, тебе все же придется выполнить для меня какое-нибудь задание, прежде чем ты получишь конфету.$b$bДай-ка подумать... У тебя такой накачанный вид в этом... костюмчике! Поиграй-ка мускулами!$b$bА я тебе за это дам вкусной оргриммарской нуги. Дети ее очень любят!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поиграйте мускулами перед хозяйкой таверны Гришкой и получите от нее за это нугу из Оргриммара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Никаких конфет, пока не поиграешь мускулами для меня, $N...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к трактирщице Гришке в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8360,'Танец за марципан','Хоть это и не твоя прямая обязанность, лакомство тебе придется отработать! От традиции, пожалуй, отходить не будем...$B$BДумаю, я отдам тебе марципан за... ТАНЕЦ! Да-да, покажи, как ты пляшешь! Попляши для меня, и я дам тебе вкусный марципанчик!','Потанцуйте для хозяйки таверны Палы, и за это вы получите марципан Громового Утеса!','Ты же знаешь, как танцевать? Попробуй поставить вот эту ногу сюда... а вот эту сюда... теперь вот так...','Вернитесь к хозяйке таверны Пале в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танец за марципан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хоть это и не твоя прямая обязанность, лакомство тебе придется отработать! От традиции, пожалуй, отходить не будем...$B$BДумаю, я отдам тебе марципан за... ТАНЕЦ! Да-да, покажи, как ты пляшешь! Попляши для меня, и я дам тебе вкусный марципанчик!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потанцуйте для хозяйки таверны Палы, и за это вы получите марципан Громового Утеса!',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты же знаешь, как танцевать? Попробуй поставить вот эту ногу сюда... а вот эту сюда... теперь вот так...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хозяйке таверны Пале в Громовой Утес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8361,'Связь с Бездной','Мы видели, как сектанты проводят ритуалы и вызывают могущественных повелителей стихий. Мы не знаем, поклоняются ли им служители культа или используют как посредников при общении с еще более страшными силами. Ясно одно – они получают приказы от этих элементалей.$b$bОтыщи храмовника Бездны и задай ему хорошую трепку! Стоит лишить войска командира, и в их рядах начинается разброд и шатания. Принеси доказательство своего подвига.','Убейте храмовника Бездны по поручению Бора Буйногривого из Крепости Кенария, что в Силитусе, и принесите в доказательство талисман Бездны.','Ха! У тебя получилось! Скоро мы одолеем Сумеречный Молот!','Работа закончена?','Вернитесь к Бору Буйногривому в Улей Аши, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Связь с Бездной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы видели, как сектанты проводят ритуалы и вызывают могущественных повелителей стихий. Мы не знаем, поклоняются ли им служители культа или используют как посредников при общении с еще более страшными силами. Ясно одно – они получают приказы от этих элементалей.$b$bОтыщи храмовника Бездны и задай ему хорошую трепку! Стоит лишить войска командира, и в их рядах начинается разброд и шатания. Принеси доказательство своего подвига.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте храмовника Бездны по поручению Бора Буйногривого из Крепости Кенария, что в Силитусе, и принесите в доказательство талисман Бездны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! У тебя получилось! Скоро мы одолеем Сумеречный Молот!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Работа закончена?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бору Буйногривому в Улей Аши, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8362,'Талисманы Бездны','Ты $Gмолодец:умница;! Мне больше не надо беспокоиться о тамплиерах.$B$BВот так, $N. Надеюсь, там есть что-то полезное для тебя.','Ты уже $Gдоказал:доказала;, что умеешь сражаться, $N. Нельзя ослаблять натиск на Сумеречный Молот. Ступай, сразись с новыми храмовниками Бездны, и получишь в награду вещи, которые мы с Хуумом добыли в бою.','Вернитесь к Бору Буйногривому в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Талисманы Бездны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gмолодец:умница;! Мне больше не надо беспокоиться о тамплиерах.$B$BВот так, $N. Надеюсь, там есть что-то полезное для тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gдоказал:доказала;, что умеешь сражаться, $N. Нельзя ослаблять натиск на Сумеречный Молот. Ступай, сразись с новыми храмовниками Бездны, и получишь в награду вещи, которые мы с Хуумом добыли в бою.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бору Буйногривому в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8363,'Перстни Бездны','Отлично, $N! Победа над этими герцогами заставит Сумеречный Молот на некоторое время пошатнуться. Как и обещал, вот ваша награда. Это одни из лучших вещей, которые мы с Хуумом нашли.','Ты $Gдоказал:доказала;, что можешь вызвать на бой герцогов Бездны, $N. А я всегда готов поощрять хорошие тенденции. Принеси мне еще перстней, и я награжу тебя.','Вернитесь к Бору Буйногривому в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перстни Бездны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! Победа над этими герцогами заставит Сумеречный Молот на некоторое время пошатнуться. Как и обещал, вот ваша награда. Это одни из лучших вещей, которые мы с Хуумом нашли.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдоказал:доказала;, что можешь вызвать на бой герцогов Бездны, $N. А я всегда готов поощрять хорошие тенденции. Принеси мне еще перстней, и я награжу тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бору Буйногривому в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8364,'Скипетры Бездны','Я знал, что ты справишься, $N! Вот твоя награда.','Тебе удалось превзойти все мои ожидания, $N. Ты можешь справиться с противниками, которых мы с Хуумом не решились бы вызвать на бой.$B$BМне остается лишь поощрять тебя за борьбу с Сумеречным Молотом и его главарями.$B$BПринеси мне еще сумеречных скипетров, и я постараюсь достойно тебя наградить.','Вернитесь к Бору Буйногривому в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скипетры Бездны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знал, что ты справишься, $N! Вот твоя награда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось превзойти все мои ожидания, $N. Ты можешь справиться с противниками, которых мы с Хуумом не решились бы вызвать на бой.$B$BМне остается лишь поощрять тебя за борьбу с Сумеречным Молотом и его главарями.$B$BПринеси мне еще сумеречных скипетров, и я постараюсь достойно тебя наградить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бору Буйногривому в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8365,'Пиратские шляпы','Так это тебя Картель послал к нам на помощь? Пожалуй, ты сойдешь. Слушай внимательно, |3-6($c). Ты ведь знаешь, что я законодатель мод Азерота? Короли и королевы, вожди и... как там Орда называет своих королев? Одним словом, все носят, что я укажу. И платят за это бешеные деньги, что особенно приятно.$b$bВ общем, поступим так. Отправляйся в Бухту Сорванных Парусов и раздобудь побольше пиратских шляп. Справишься?','Добудьте 20 шляп пиратов Южных Морей и отнесите их Отти Кутюри в Порт Хитрой Шестеренки в Танарисе.','Вернитесь к Отти Кутюри в Порт Хитрой Шестеренки, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пиратские шляпы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так это тебя Картель послал к нам на помощь? Пожалуй, ты сойдешь. Слушай внимательно, |3-6($c). Ты ведь знаешь, что я законодатель мод Азерота? Короли и королевы, вожди и... как там Орда называет своих королев? Одним словом, все носят, что я укажу. И платят за это бешеные деньги, что особенно приятно.$b$bВ общем, поступим так. Отправляйся в Бухту Сорванных Парусов и раздобудь побольше пиратских шляп. Справишься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 20 шляп пиратов Южных Морей и отнесите их Отти Кутюри в Порт Хитрой Шестеренки в Танарисе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Отти Кутюри в Порт Хитрой Шестеренки, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8366,'Покажи этим пиратам','Они требуют от меня невозможного!$b$bКартель Хитрой Шестеренки хочет, чтобы я преподал пиратам Южных Морей урок. Мне что, разорваться?! Я должен поддерживать здесь порядок.$b$bВ последнее время пираты забыли, что картель платит им за защиту. Нужно показать им, что к чему.$b$bПираты поселились в Бухте Сорванных Парусов, неподалеку отсюда, на юге. Спасибо, $n. Я твой должник!','Начальник отдела безопасности Чепухастер из Порта Хитрой Шестеренки в Танарисе просит убить 10 пиратов, 10 флибустьеров, 10 рабочих и 10 сорвиголов Южных морей.','Вернитесь к начальнику отдела безопасности Чепухастеру в Порт Хитрой Шестеренки, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покажи этим пиратам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они требуют от меня невозможного!$b$bКартель Хитрой Шестеренки хочет, чтобы я преподал пиратам Южных Морей урок. Мне что, разорваться?! Я должен поддерживать здесь порядок.$b$bВ последнее время пираты забыли, что картель платит им за защиту. Нужно показать им, что к чему.$b$bПираты поселились в Бухте Сорванных Парусов, неподалеку отсюда, на юге. Спасибо, $n. Я твой должник!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Начальник отдела безопасности Чепухастер из Порта Хитрой Шестеренки в Танарисе просит убить 10 пиратов, 10 флибустьеров, 10 рабочих и 10 сорвиголов Южных морей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к начальнику отдела безопасности Чепухастеру в Порт Хитрой Шестеренки, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (8366,'$n! You are the man!!!$B$BI\'m sure that the Cartel will ease up on me now that you\'ve dealt with those Southsea scum. Let\'s see, what can I give you as a reward? How about a little coin and you choose from one of these for your trouble?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$n! You are the man!!!$B$BI\'m sure that the Cartel will ease up on me now that you\'ve dealt with those Southsea scum. Let\'s see, what can I give you as a reward? How about a little coin and you choose from one of these for your trouble?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8367,'Великая честь','Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс.$b$bСтупай же и сокруши противника на всех фронтах. За честь! За Орду!','Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды или в Шаттрат.','На твою долю выпали непростые испытание, но ты не лишился мужества и сила тебя не покинула. Знаки победы – пустое. Не по ним судят о твоей доблести. Выше голову, $N. Сегодня тебе подобает смотреть на других свысока, ведь ты настоящий герой!','Травы Арати мокры от крови и слышны лязга стали и воинственные крики воинов которые сражаются за Альтерак. Не трать моего времени, разве что ты $Gпринес:принесла; новости с фронта!','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая честь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет выше чести, чем биться с Альянсом во имя Орды! Лучшие же наши воины – те немногие, которым довелось сразиться на ВСЕХ полях битвы. Отдельные стычки не помогут нам одолеть врага. Лишь тщательно спланировав наступление, мы сломим проклятый Альянс.$b$bСтупай же и сокруши противника на всех фронтах. За честь! За Орду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите почетные знаки каждого поля боя ордынскому вестнику войны в любую столицу Орды или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На твою долю выпали непростые испытание, но ты не лишился мужества и сила тебя не покинула. Знаки победы – пустое. Не по ним судят о твоей доблести. Выше голову, $N. Сегодня тебе подобает смотреть на других свысока, ведь ты настоящий герой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Травы Арати мокры от крови и слышны лязга стали и воинственные крики воинов которые сражаются за Альтерак. Не трать моего времени, разве что ты $Gпринес:принесла; новости с фронта!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8368,'Битва за Ущелье Песни Войны','Битва со Среброкрылыми Часовыми за Ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.$b$bНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!','Принесите 3 почетных знака Ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.','Великолепно! Ты $Gпоказал:показала;, чего стоишь, выступив против врага в Ущелье Песни Войны! Да разнесутся вести о твоих подвигах по всем нашим землям.','Сражение в Ущелье Песни Войны против Стражей Среброкрылых имеет огромное значение. Под предлогом защиты леса, который им не принадлежит, Альянс пытается лишить Орду одного из наших крупнейших источников древесины.$B$BНе позволь этому случиться, $N! Возвращайся ко мне с доказательством того, что ты достойно служишь Орде!','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Ущелье Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Битва со Среброкрылыми Часовыми за Ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.$b$bНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 почетных знака Ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Ты $Gпоказал:показала;, чего стоишь, выступив против врага в Ущелье Песни Войны! Да разнесутся вести о твоих подвигах по всем нашим землям.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сражение в Ущелье Песни Войны против Стражей Среброкрылых имеет огромное значение. Под предлогом защиты леса, который им не принадлежит, Альянс пытается лишить Орду одного из наших крупнейших источников древесины.$B$BНе позволь этому случиться, $N! Возвращайся ко мне с доказательством того, что ты достойно служишь Орде!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8369,'Вторжение в Альтеракскую долину','Слушай, $n. Что бы ни болтали про битву в Альтеракской долине, правда состоит в следующем: экспедиция Грозовой Вершины вторглась в земли клана Северного Волка. В тот день, когда мы позволим Альянсу безнаказанно нарушать наши границы, я повешу секиру на стену и примусь посыпать голову пеплом. Отправляйся и сотри в порошок наглых захватчиков!','Принесите 3 почетных знака Альтеракской долины ордынскому вестнику войны рядом со входом на поле боя.','Ты $Gвстал:встала; на защиту наших земель с невиданной храбостью! Я непременно расскажу командующим о твоих подвигах.','Что слышно из земель Северного Волка? Как идет битва в Альтеракской долине?','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение в Альтеракскую долину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $n. Что бы ни болтали про битву в Альтеракской долине, правда состоит в следующем: экспедиция Грозовой Вершины вторглась в земли клана Северного Волка. В тот день, когда мы позволим Альянсу безнаказанно нарушать наши границы, я повешу секиру на стену и примусь посыпать голову пеплом. Отправляйся и сотри в порошок наглых захватчиков!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 почетных знака Альтеракской долины ордынскому вестнику войны рядом со входом на поле боя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gвстал:встала; на защиту наших земель с невиданной храбостью! Я непременно расскажу командующим о твоих подвигах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что слышно из земель Северного Волка? Как идет битва в Альтеракской долине?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8370,'Завоевание Низины Арати','Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.$b$bВ Низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, $n!','Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завоевание Низины Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.$b$bВ Низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8371,'В едином порыве','В войне против Орды решающей может оказаться любая битва, $gсынок:дочка;.$B$BПобеда на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой.$b$bАльянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закаленных в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.','Принесите почетные знаки каждого поля боя бригадному генералу Альянса в любую столицу Альянса или в Шаттрат.','Ты не $Gразочаровал:разочаровала; меня, $N! И ты $Gполучил:получила; большее, чем просто медали и отличия. Ты $Gполучил:получила; бесценный опыт и $Gзакалил:закалила; свой дух.$B$BХорошо сделано, |3-6($C). Ты настоящий герой Альянса!','Как $Gтвои:ваши; путешествия, $Gпарень:девушка;?','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В едином порыве',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В войне против Орды решающей может оказаться любая битва, $gсынок:дочка;.$B$BПобеда на одном фронте позволит захватить ресурсы, которые помогут победить и на другом. И с точностью до наоборот – любая проигранная битва может дать нашим врагам преимущество в другой.$b$bАльянсу не хватает бойцов, которые бы хорошенько поняли это... бойцов, закаленных в битвах! Отправляйся сражаться с Ордой, а когда побываешь на всех полях битвы, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите почетные знаки каждого поля боя бригадному генералу Альянса в любую столицу Альянса или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не $Gразочаровал:разочаровала; меня, $N! И ты $Gполучил:получила; большее, чем просто медали и отличия. Ты $Gполучил:получила; бесценный опыт и $Gзакалил:закалила; свой дух.$B$BХорошо сделано, |3-6($C). Ты настоящий герой Альянса!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как $Gтвои:ваши; путешествия, $Gпарень:девушка;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8372,'Битва за Ущелье Песни Войны','Среброкрылые Часовые вступили в бой со всадниками из клана Песни Войны, стараясь защитить от них лес. Впрочем, желание сохранить этот лес объсняется не только их любовью к природе.$b$bЭтот лес представляет собой естественную преграду для наступления сил Орды. Без него Астранаар не продержался бы и дня, и в наши земли давно вторглась бы огромная армия Орды.$b$bВнеси свой вклад в борьбу со всадниками из клана Песни Войны, $n! За Альянс!','Принесите 3 почетных знака Ущелья Песни Войны бригадному генералу Альянса рядом со входом на поля боя.','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Ущелье Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среброкрылые Часовые вступили в бой со всадниками из клана Песни Войны, стараясь защитить от них лес. Впрочем, желание сохранить этот лес объсняется не только их любовью к природе.$b$bЭтот лес представляет собой естественную преграду для наступления сил Орды. Без него Астранаар не продержался бы и дня, и в наши земли давно вторглась бы огромная армия Орды.$b$bВнеси свой вклад в борьбу со всадниками из клана Песни Войны, $n! За Альянс!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 почетных знака Ущелья Песни Войны бригадному генералу Альянса рядом со входом на поля боя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (8373,'Сила сосен','Самое гнусное в Тыквовине – это бомбы-вонючки, которые Отрекшиеся бросают на Южнобережье. Кто бы мог подумать, что праздновение свободы требует такой вони?$b$bКогда наступит Тыквовин, убери при помощи этого очистителя любую из мерзких бомб, которые Орда может подкинуть к нам в деревню. Очиститель действует благодаря силе сосен.$b$bПрими участие в поддержании чистоты Южнобережья, и я дам тебе кое-какие тыквовинские вкусности, которым ты несомненно порадуешься. Договорились?','Уберите любую бомбу-вонючку Отрекшихся, брошенную в Южнобережье, при помощи очистителя бомб-вонючек. По выполнении задания возвращайтесь к сержанту Дыгалу.','О, здесь уже почти не воняет. Почти. Благодаря тебе, $N, Южнобережье может пережить еще один Тыквовин. Вот ваши угощения и моя благодарность. Если у вас закончатся конфеты, я думаю, что в Стальгорне есть гном по имени Катрина Мерцанна, которая может продать вам больше, но она будет там только во время Тыквовина.','Убрать бомбу-вонючку, брошенную в Южнобережье!','Вернитесь к сержанту Дыгалу в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила сосен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Самое гнусное в Тыквовине – это бомбы-вонючки, которые Отрекшиеся бросают на Южнобережье. Кто бы мог подумать, что праздновение свободы требует такой вони?$b$bКогда наступит Тыквовин, убери при помощи этого очистителя любую из мерзких бомб, которые Орда может подкинуть к нам в деревню. Очиститель действует благодаря силе сосен.$b$bПрими участие в поддержании чистоты Южнобережья, и я дам тебе кое-какие тыквовинские вкусности, которым ты несомненно порадуешься. Договорились?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уберите любую бомбу-вонючку Отрекшихся, брошенную в Южнобережье, при помощи очистителя бомб-вонючек. По выполнении задания возвращайтесь к сержанту Дыгалу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, здесь уже почти не воняет. Почти. Благодаря тебе, $N, Южнобережье может пережить еще один Тыквовин. Вот ваши угощения и моя благодарность. Если у вас закончатся конфеты, я думаю, что в Стальгорне есть гном по имени Катрина Мерцанна, которая может продать вам больше, но она будет там только во время Тыквовина.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Убрать бомбу-вонючку, брошенную в Южнобережье!',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Дыгалу в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8374,'Завоевание Низины Арати','Чтобы выиграть войну, мало быть быть умнее и хитрее противника. Зачастую победа достается тем, в чьих руках сосредоточены все ресурсы.$b$bРесурсов в Низине Арати – хоть отбавляй. Главное – захватить их первыми.$b$bЕсли победа будет за Альянсом, нашим солдатам достанется больше мечей и копий. Если Орде – те же мечи и копья обратятся против нас! Твой долг помочь Альянсу захватить Низину Арати!','Принесите 3 почетных знака Низины Арати бригадному генералу Альянса рядом со входом на поля боя.','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завоевание Низины Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы выиграть войну, мало быть быть умнее и хитрее противника. Зачастую победа достается тем, в чьих руках сосредоточены все ресурсы.$b$bРесурсов в Низине Арати – хоть отбавляй. Главное – захватить их первыми.$b$bЕсли победа будет за Альянсом, нашим солдатам достанется больше мечей и копий. Если Орде – те же мечи и копья обратятся против нас! Твой долг помочь Альянсу захватить Низину Арати!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 почетных знака Низины Арати бригадному генералу Альянса рядом со входом на поля боя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8375,'Помни Альтеракскую долину!','Не пойми меня превратно, $n. Орда совершенно справедливо считает Альтеракскую долину территорией клана Северного Волка.$b$bВидишь ли, экспедиция Грозовой Вершины прибыла в эти края как мирные исследователи. Они искали руду и древние реликвии, но нашли лишь смерть. Альянс не ожидал такой бессмысленной жестокости даже от клана Северного Волка.$b$bВечная память отважным дворфам, павшим от рук вероломных орков. Ступай, |3-6($c), внеси свой вклад в битву за Альтеракскую долину. За Альянс!','Принесите 3 почетных знака Альтеракской долины бригадному генералу Альянса рядом со входом на поле боя.','Ты $Gвстал:встала; на защиту наших земель с невиданной храбостью! Я непременно расскажу командующим о твоих подвигах.','Какие вести с фронта, $N?','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помни Альтеракскую долину!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не пойми меня превратно, $n. Орда совершенно справедливо считает Альтеракскую долину территорией клана Северного Волка.$b$bВидишь ли, экспедиция Грозовой Вершины прибыла в эти края как мирные исследователи. Они искали руду и древние реликвии, но нашли лишь смерть. Альянс не ожидал такой бессмысленной жестокости даже от клана Северного Волка.$b$bВечная память отважным дворфам, павшим от рук вероломных орков. Ступай, |3-6($c), внеси свой вклад в битву за Альтеракскую долину. За Альянс!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 почетных знака Альтеракской долины бригадному генералу Альянса рядом со входом на поле боя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gвстал:встала; на защиту наших земель с невиданной храбостью! Я непременно расскажу командующим о твоих подвигах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие вести с фронта, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8376,'Оружие войны','Грядет война, а вместе с ней невиданные ужасы. Ты $Gсделал:сделала; все, что $Gмог:могла;, и $Gдолжен:должна; получить награду.$B$BЕсли это... пророчество сбудется…$B$B<Геолог Ехидная бледнеет.>$B$BМожно считать, что у нас нет будущего.$B$BЭто оружие понадобится тебе на войне в пустыне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие войны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Грядет война, а вместе с ней невиданные ужасы. Ты $Gсделал:сделала; все, что $Gмог:могла;, и $Gдолжен:должна; получить награду.$B$BЕсли это... пророчество сбудется…$B$B<Геолог Ехидная бледнеет.>$B$BМожно считать, что у нас нет будущего.$B$BЭто оружие понадобится тебе на войне в пустыне.',`offerrewardtext_loc8`);
