INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8409,'Поломанные бочки','Тухлые яйца успешно подброшены в бочку, и весь эль Южнобережья теперь безнадежно испорчен.$B$BОтправляйтесь назад, к зовущей Тьму Янке, на фестиваль Плетеного человека в Тирисфальских лесах, и доложите о своем успехе.','Вернитесь к зовущей Тьму Янке на фестиваль Плетеного человека в Тирисфальских лесах.','Ха-ха! Вот теперь-то вы продемонстрировали настоящий дух Тыквовина, вернее, дух ОТРЕКШИХСЯ!!!$B$B*Янка Зовущая Тьму смеется и потирает руки.*$B$BЗамечательно, что в Южнобережье теперь будут пить испорченный эль, а то и вовсе никакого. А вы – вот, угощайтесь. Надеюсь, вам все понравится!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поломанные бочки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тухлые яйца успешно подброшены в бочку, и весь эль Южнобережья теперь безнадежно испорчен.$B$BОтправляйтесь назад, к зовущей Тьму Янке, на фестиваль Плетеного человека в Тирисфальских лесах, и доложите о своем успехе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к зовущей Тьму Янке на фестиваль Плетеного человека в Тирисфальских лесах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха! Вот теперь-то вы продемонстрировали настоящий дух Тыквовина, вернее, дух ОТРЕКШИХСЯ!!!$B$B*Янка Зовущая Тьму смеется и потирает руки.*$B$BЗамечательно, что в Южнобережье теперь будут пить испорченный эль, а то и вовсе никакого. А вы – вот, угощайтесь. Надеюсь, вам все понравится!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8410,'Покорение стихий','Бат\'ра Страж Ветра ищет шамана вроде тебя. Принеси ему по образцу каждой из стихий, чтобы доказать свое мастерство.$b$bБат\'ру можно отыскать на востоке от Мельницы Таррен. Иди вдоль реки на север до руин. Там-то Бат\'ра и разбил лагерь.','Соберите образцы воздуха, огня, земли и воды по поручению Бат\'ры Стража Ветра.','Отлично, $N. Теперь мы говорим','Что ты мне $Gпринес:принесла;, $C?','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покорение стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бат\'ра Страж Ветра ищет шамана вроде тебя. Принеси ему по образцу каждой из стихий, чтобы доказать свое мастерство.$b$bБат\'ру можно отыскать на востоке от Мельницы Таррен. Иди вдоль реки на север до руин. Там-то Бат\'ра и разбил лагерь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите образцы воздуха, огня, земли и воды по поручению Бат\'ры Стража Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N. Теперь мы говорим',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ты мне $Gпринес:принесла;, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8411,'Покорение Стихий','Добро пожаловать, |3-6($c). Расклад такой: ты несешь мне стихии и только потом я с тобой говорю.$b$bМне нужны от тебя Огонь, Воздух, Вода и Земля. Только потом я тебе буду доверять, дружище. Надо удостовериться, что ты не совсем дундук.','Принесите стихии Земли, Воздуха, Огня и Воды Бат\'ре Стражу Ветра.','Где элементы, $Gдружище:подруга;?','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покорение Стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать, |3-6($c). Расклад такой: ты несешь мне стихии и только потом я с тобой говорю.$b$bМне нужны от тебя Огонь, Воздух, Вода и Земля. Только потом я тебе буду доверять, дружище. Надо удостовериться, что ты не совсем дундук.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите стихии Земли, Воздуха, Огня и Воды Бат\'ре Стражу Ветра.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где элементы, $Gдружище:подруга;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8412,'Тотем духов','Духи стихий здешних мест меня невзлюбили.$b$bТы знаешь о тотемах больше других, а мне без защитного тотема духов не обойтись. Стихии у нас уже есть, теперь нужно что-то более близкое к природе, первобытное.$b$bВ Западных Чумных землях можно добыть когти медведей и глаза пауков. Падальщики едят и тех, и других, поэтому у них в желудках может быть и то, и другое.','Принесите части тотема Духа Бат\'ре Стражу Ветра.','Отлично, $N! Давай попробуем...','Духи знают, что делают, а они пытаются убить меня! Надеюсь, ты несешь мне нужные части.','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тотем духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духи стихий здешних мест меня невзлюбили.$b$bТы знаешь о тотемах больше других, а мне без защитного тотема духов не обойтись. Стихии у нас уже есть, теперь нужно что-то более близкое к природе, первобытное.$b$bВ Западных Чумных землях можно добыть когти медведей и глаза пауков. Падальщики едят и тех, и других, поэтому у них в желудках может быть и то, и другое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите части тотема Духа Бат\'ре Стражу Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! Давай попробуем...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Духи знают, что делают, а они пытаются убить меня! Надеюсь, ты несешь мне нужные части.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8413,'Вуду','Силы этого тотема духов не достаточно. Нам нужна магия вуду, чтобы сделать верную защиту.$b$bТролли из затонувшего храма делают перья, насыщенные магией вуду. Ступай туда и убей Гашера, Миджана, Золо, Хукку, Зул\'Лора и Лоро. Тогда нам хватит магии на настоящий тотем духов.','Принесите вудуистские перья Бат\'ре Стражу Ветра.','Пора этому троллю хорошенько вздремнуть! За мной присмотрит тотем духов.$B$BТебе понадобилось много времени, чтобы собрать все части. Ты хочешь что-нибудь за труды?','Где перья, дружище?','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вуду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Силы этого тотема духов не достаточно. Нам нужна магия вуду, чтобы сделать верную защиту.$b$bТролли из затонувшего храма делают перья, насыщенные магией вуду. Ступай туда и убей Гашера, Миджана, Золо, Хукку, Зул\'Лора и Лоро. Тогда нам хватит магии на настоящий тотем духов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите вудуистские перья Бат\'ре Стражу Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пора этому троллю хорошенько вздремнуть! За мной присмотрит тотем духов.$B$BТебе понадобилось много времени, чтобы собрать все части. Ты хочешь что-нибудь за труды?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где перья, дружище?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бат\'ре Стражу Ветра на Берег Промозглого Ветра, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8414,'Борьба со злом','Привет тебе, |3-6($c). Отрадно видеть рыцаря вроде тебя в сих безотрадных землях.$b$bМы рассчитваем на твою помощь в борьбе с беконечными полчищами нежити. Собери побольше камней Плети и отнеси их верховному жрецу Тель\'данису. Он охраняет гробницу Утера неподалеку отсюда.$b$bКамни Плети находят лишь те, кто получил Жетон Серебряного Рассвета. Если у тебя нет амулета, поговори с офицером Чистосердой.','Принесите 20 камней приспешников Плети верховному жрецу Тель\'данису в Западные Чумные земли.','Какое зло ты принес мне?','Вернитесь к верховному жрецу Тель\'данису в Гробницу Утера, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борьба со злом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, |3-6($c). Отрадно видеть рыцаря вроде тебя в сих безотрадных землях.$b$bМы рассчитваем на твою помощь в борьбе с беконечными полчищами нежити. Собери побольше камней Плети и отнеси их верховному жрецу Тель\'данису. Он охраняет гробницу Утера неподалеку отсюда.$b$bКамни Плети находят лишь те, кто получил Жетон Серебряного Рассвета. Если у тебя нет амулета, поговори с офицером Чистосердой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 камней приспешников Плети верховному жрецу Тель\'данису в Западные Чумные земли.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какое зло ты принес мне?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному жрецу Тель\'данису в Гробницу Утера, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8415,'Лагерь Промозглого Ветра','Командиру Ашламу Неутомимому нужен паладин, не уступающий тебе честью и доблестью, $n. Командир живет в Лагере Промозглого Ветра в южной части Западных Чумных земель. Найди его и помоги делу Света!','Обратитесь к командиру Ашламу Неутомимому в Лагере Промозглого Ветра.','Отлично, |3-6($C)! Посмотрим, из какого теста ты сделан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь Промозглого Ветра',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Командиру Ашламу Неутомимому нужен паладин, не уступающий тебе честью и доблестью, $n. Командир живет в Лагере Промозглого Ветра в южной части Западных Чумных земель. Найди его и помоги делу Света!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к командиру Ашламу Неутомимому в Лагере Промозглого Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, |3-6($C)! Посмотрим, из какого теста ты сделан.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (8416,'Бездействующие камни Плети','Камни очищены от зла, $n.$b$bЯ в курсе планов командира Аслама, и ему понадобится всего лишь один бездействующий камень. Отнеси его, и да сгорит Плеть в праведном огне.','Отнесите бездействующий камень командиру Ашламу Неутомимому на Берег Промозглого Ветра.','Удалось ли Тельданису очистить камни Плети?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бездействующие камни Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Камни очищены от зла, $n.$b$bЯ в курсе планов командира Аслама, и ему понадобится всего лишь один бездействующий камень. Отнеси его, и да сгорит Плеть в праведном огне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите бездействующий камень командиру Ашламу Неутомимому на Берег Промозглого Ветра.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли Тельданису очистить камни Плети?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8417,'Неупокоенный дух','По Выжженным землям бродит неупокоенный дух одного из величайших героев Орды. Честь воина прочнее смертного тела, так что тебе не помешает поговорить с ним.','Поговорите с павшим героем Орды у входа в Выжженные земли.','Итак, ты хочешь избавить меня от боли. Жаль, что меня нельзя просто-напросто зарубить, но к сожалению, не все так просто…','Столи откашлялся от моей выпивки?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неупокоенный дух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По Выжженным землям бродит неупокоенный дух одного из величайших героев Орды. Честь воина прочнее смертного тела, так что тебе не помешает поговорить с ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с павшим героем Орды у входа в Выжженные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, ты хочешь избавить меня от боли. Жаль, что меня нельзя просто-напросто зарубить, но к сожалению, не все так просто…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Столи откашлялся от моей выпивки?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8418,'Создание камня силы','Теперь мы сможем создать оружие против нежити из бездействующих камней Плети. Задание непростое. Магией, способной вынудить зло обратиться против самого себя, владеют лишь тролли из затонувшего храма.$b$bВ храме есть тролли по имени Ранокол, Миджан, Золо, Хукку, Зул\'Лор и Лоро. Не стоит их жалеть... они давно пали и их души запятнаны злом.','Добудьте янтарные, синие и зеленые вудуистские перья у троллей из Затонувшего храма.','Великолепно. Я сказал бы, что удивлен, но я ни на минуту не сомневался, что ты не подведешь нас.$B$BМне выпала честь вручить тебе один из священных камней силы. Пользуйся им во благо.','Тебе удалось убить проклятых троллей?','Вернитесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Создание камня силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь мы сможем создать оружие против нежити из бездействующих камней Плети. Задание непростое. Магией, способной вынудить зло обратиться против самого себя, владеют лишь тролли из затонувшего храма.$b$bВ храме есть тролли по имени Ранокол, Миджан, Золо, Хукку, Зул\'Лор и Лоро. Не стоит их жалеть... они давно пали и их души запятнаны злом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте янтарные, синие и зеленые вудуистские перья у троллей из Затонувшего храма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Я сказал бы, что удивлен, но я ни на минуту не сомневался, что ты не подведешь нас.$B$BМне выпала честь вручить тебе один из священных камней силы. Пользуйся им во благо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось убить проклятых троллей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8419,'Просьба беса','С тобой хочет встретиться один бес из Оскверненного леса по имени Бесенок. Это довольно странно, поскольку он попросил тебя принести отрез ткани Скверны в залог доброй воли. Ты весьма $gмогущественный чернокнижник:могущественная чернокнижница; и наверняка знаешь, что ткань Скверны таскают с собой сатиры Оскверненного леса.$b$bБесенок живет на севере от водопада Ядовитой Крови. Говорят, в это время года там очень красиво.','Отнесите Бесенку из Оскверненного леса отрез ткани Скверны.','Ой, спасибо, добренький $C!$B$B*Бесенок подносит ткань к лицу.*$B$BКак мне нравится ее касаться! Она так славно обжигает кожу и внушает злобные мысли...','Ты $Gпринес:принесла; мне ткань Скверны?','Вернитесь к Бесенку в Долину Рваных Ран, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба беса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тобой хочет встретиться один бес из Оскверненного леса по имени Бесенок. Это довольно странно, поскольку он попросил тебя принести отрез ткани Скверны в залог доброй воли. Ты весьма $gмогущественный чернокнижник:могущественная чернокнижница; и наверняка знаешь, что ткань Скверны таскают с собой сатиры Оскверненного леса.$b$bБесенок живет на севере от водопада Ядовитой Крови. Говорят, в это время года там очень красиво.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Бесенку из Оскверненного леса отрез ткани Скверны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, спасибо, добренький $C!$B$B*Бесенок подносит ткань к лицу.*$B$BКак мне нравится ее касаться! Она так славно обжигает кожу и внушает злобные мысли...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне ткань Скверны?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бесенку в Долину Рваных Ран, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8420,'Пробирает!','Может, ты и не $Gожидал:ожидала; услышать это от беса, но мне хочется завести питомца. Правда-правда. Это же нечестно – у Ниби есть я, а у меня нет никого!$b$bМне даже не надо живого питомца. Мне нужно что-нибудь, из чего я бы мог его себе сделать – например, ткань Скверны. У сатиров тут, в Оскверненном лесу, ткань Скверны-то имеется, так что просто убивай их, пока не найдешь ткань. Звучит не так уж и ужасно, правда?','Принесите отрез ткани Скверны Бесенку в Оскверненный лес.','Вот это да! Ты слишком $Gдобрый:добрая;, $N!$B$B<Импси прижимает к лицу ткань скверны.>$B$BО, как мне нравится это ощущение, то, как она обжигает твою кожу и плетет злые мысли в уме…','Ты $Gпринес:принесла; мне ткань Скверны?','Вернитесь к Бесенку в Долину Рваных Ран, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробирает!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может, ты и не $Gожидал:ожидала; услышать это от беса, но мне хочется завести питомца. Правда-правда. Это же нечестно – у Ниби есть я, а у меня нет никого!$b$bМне даже не надо живого питомца. Мне нужно что-нибудь, из чего я бы мог его себе сделать – например, ткань Скверны. У сатиров тут, в Оскверненном лесу, ткань Скверны-то имеется, так что просто убивай их, пока не найдешь ткань. Звучит не так уж и ужасно, правда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите отрез ткани Скверны Бесенку в Оскверненный лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это да! Ты слишком $Gдобрый:добрая;, $N!$B$B<Импси прижимает к лицу ткань скверны.>$B$BО, как мне нравится это ощущение, то, как она обжигает твою кожу и плетет злые мысли в уме…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне ткань Скверны?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бесенку в Долину Рваных Ран, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8421,'Бросовый материал','Теперь, когда у меня есть ткань Скверны, я могу начать изготовление собственного питомца.$b$bНо ему нужны глазки! Может, сумеешь оторвать кусочек гнилой древесины от железного дерева, и я вырежу из нее прелестные глазки? Деревья эти можно найти в Железнолесье.$b$bА еще мне понадобится немного экстракта ядовитой крови, чтобы мой питомец приобрел демонический запах. Этот экстракт можно добыть из нечистых слизнюков, а они ошиваются прямо по соседству со мной и Ниби.','Принесите 10 кусков гнилой древесины и 4 порции экстракта ядовитой крови Бесенку в Оскверненный лес.','Это будет очень хорошо работать.','Ну, все принес?','Вернитесь к Бесенку в Долину Рваных Ран, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бросовый материал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у меня есть ткань Скверны, я могу начать изготовление собственного питомца.$b$bНо ему нужны глазки! Может, сумеешь оторвать кусочек гнилой древесины от железного дерева, и я вырежу из нее прелестные глазки? Деревья эти можно найти в Железнолесье.$b$bА еще мне понадобится немного экстракта ядовитой крови, чтобы мой питомец приобрел демонический запах. Этот экстракт можно добыть из нечистых слизнюков, а они ошиваются прямо по соседству со мной и Ниби.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 кусков гнилой древесины и 4 порции экстракта ядовитой крови Бесенку в Оскверненный лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это будет очень хорошо работать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, все принес?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бесенку в Долину Рваных Ран, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8422,'Тролли Пера','Мой питомец почти готов. Осталось набить его.$b$bТолько вудуистские перья с троллей затонувшего храма помогут делу. Их зовут Ранокол, Миджан, Золо, Хукку, Зул\'Лор и Лоро. Убей их. Перебей их всех! $b$bЭто непростое дело, $n, потому я заплачу тебе за услугу, дав тебе кое-что из барахла Ниби – ему это все равно, наверное, не нужно.','Принесите 6 вудуистских перьев троллей из затонувшего храма.','Отлично, теперь мой питомец закончен!$B$B*Бесенок быстро набивает куколку и с демонической горячностью обнимает ее.*$B$BОго, какой побочный эффект у этих вудуистских перьев...','Где перья? Эта кукла нуждается в них!','Вернитесь к Бесенку в Долину Рваных Ран, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролли Пера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой питомец почти готов. Осталось набить его.$b$bТолько вудуистские перья с троллей затонувшего храма помогут делу. Их зовут Ранокол, Миджан, Золо, Хукку, Зул\'Лор и Лоро. Убей их. Перебей их всех! $b$bЭто непростое дело, $n, потому я заплачу тебе за услугу, дав тебе кое-что из барахла Ниби – ему это все равно, наверное, не нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 вудуистских перьев троллей из затонувшего храма.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, теперь мой питомец закончен!$B$B*Бесенок быстро набивает куколку и с демонической горячностью обнимает ее.*$B$BОго, какой побочный эффект у этих вудуистских перьев...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где перья? Эта кукла нуждается в них!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бесенку в Долину Рваных Ран, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8423,'Воинское испытание','*Герой окидывает тебя взглядом.*$b$bНет сомнений, ты |3-6($c). У меня для тебя есть почетная задача, но сначала необходимо испытать твою силу.$b$bГоворят, что Рексар проверял остроту своих клинков, убивая зловепря одним быстрым ударом. Теперь же я проверю твою силу, отправив тебя на охоту за зловепрями.','Убейте 7 Зловепрей в Выжженных землях и вернитесь к павшему герою Орды.','Мне не нужны доказательства твоих подвигов, $C. Достаточно того, что я вижу решимость в чертах твоего лица.','Горящие шипы кабана оставляют ужасные шрамы. Не бойся боли и обезображивания, $C, они ничто по сравнению с тюрьмой, к которой я привязан.','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воинское испытание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Герой окидывает тебя взглядом.*$b$bНет сомнений, ты |3-6($c). У меня для тебя есть почетная задача, но сначала необходимо испытать твою силу.$b$bГоворят, что Рексар проверял остроту своих клинков, убивая зловепря одним быстрым ударом. Теперь же я проверю твою силу, отправив тебя на охоту за зловепрями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 7 Зловепрей в Выжженных землях и вернитесь к павшему герою Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне не нужны доказательства твоих подвигов, $C. Достаточно того, что я вижу решимость в чертах твоего лица.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Горящие шипы кабана оставляют ужасные шрамы. Не бойся боли и обезображивания, $C, они ничто по сравнению с тюрьмой, к которой я привязан.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8424,'Война против Приверженцев Тени','Постоянное присутствие Приверженцев Тени в Выжженных землях причиняет мне сильную боль. Их темные ритуалы и заклинания вызывают мучения, каких я не ведал при жизни.$b$bЧерез тебя я могу передать мое собственное послание боли. Иди и неси мой гнев.','Убейте Приверженцев Тени в Выжженных землях и вернитесь к павшему герою Орды.','Тебе уже удалось умерить мою боль и тем самым почтить меня. Благодарю тебя, $C.','Приверженцев тени нелегко победить, не так ли? Но ты $C, и ты победишь или погибнешь, пытаясь.','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война против Приверженцев Тени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Постоянное присутствие Приверженцев Тени в Выжженных землях причиняет мне сильную боль. Их темные ритуалы и заклинания вызывают мучения, каких я не ведал при жизни.$b$bЧерез тебя я могу передать мое собственное послание боли. Иди и неси мой гнев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Приверженцев Тени в Выжженных землях и вернитесь к павшему герою Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе уже удалось умерить мою боль и тем самым почтить меня. Благодарю тебя, $C.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приверженцев тени нелегко победить, не так ли? Но ты $C, и ты победишь или погибнешь, пытаясь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8425,'Вудуистские перья','Благодаря твоей чести я обрел частицу покоя. Неправильно было бы ничего не предложить взамен.$b$bПри жизни мое оружие и доспехи были великолепны, но теперь они для меня бесполезны. Быть может, тебе они послужат лучше.$b$bОтправляйся к затонувшему храму и уничтожь троллей-охранников Ранокола, Миджана, Золо, Хукку, Зул\'Лора и Лоро. У них хранятся магические перья, которые могут восстановить мое материальное тело на достаточно долгое время, чтобы я мог вручить тебе награду.','Принесите вудуистские перья павшему герою Орды, забрав их у троллей в Затонувшем Храме.','Наконец-то я вновь могу почувствовать холодное прикосновение стали, пусть даже на несколько мгновений.','Ты уже назад – так быстро? Для тебя и меня время течет по-разному, быть может, для тебя это и вправду было долгое путешествие...','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вудуистские перья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря твоей чести я обрел частицу покоя. Неправильно было бы ничего не предложить взамен.$b$bПри жизни мое оружие и доспехи были великолепны, но теперь они для меня бесполезны. Быть может, тебе они послужат лучше.$b$bОтправляйся к затонувшему храму и уничтожь троллей-охранников Ранокола, Миджана, Золо, Хукку, Зул\'Лора и Лоро. У них хранятся магические перья, которые могут восстановить мое материальное тело на достаточно долгое время, чтобы я мог вручить тебе награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите вудуистские перья павшему герою Орды, забрав их у троллей в Затонувшем Храме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то я вновь могу почувствовать холодное прикосновение стали, пусть даже на несколько мгновений.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже назад – так быстро? Для тебя и меня время течет по-разному, быть может, для тебя это и вправду было долгое путешествие...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8426,'Битва за Ущелье Песни Войны','Битва со Среброкрылыми Часовыми за Ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.$b$bНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!','Принесите 3 почетных знака Ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.','Великолепно! Ты $Gпоказал:показала;, чего стоишь, выступив против врага в Ущелье Песни Войны! Да разнесутся вести о твоих подвигах по всем нашим землям.','Сражение в Ущелье Песни Войны против Стражей Среброкрылых имеет огромное значение. Под предлогом защиты леса, который им не принадлежит, Альянс пытается лишить Орду одного из наших крупнейших источников древесины.$B$BНе позволь этому случиться, $N! Возвращайся ко мне с доказательством того, что ты достойно служишь Орде!','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва за Ущелье Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Битва со Среброкрылыми Часовыми за Ущелье Песни Войны имеет огромное значение. Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины.$b$bНе бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 почетных знака Ущелья Песни Войны ордынскому вестнику войны рядом со входом на поля боя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Ты $Gпоказал:показала;, чего стоишь, выступив против врага в Ущелье Песни Войны! Да разнесутся вести о твоих подвигах по всем нашим землям.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сражение в Ущелье Песни Войны против Стражей Среброкрылых имеет огромное значение. Под предлогом защиты леса, который им не принадлежит, Альянс пытается лишить Орду одного из наших крупнейших источников древесины.$B$BНе позволь этому случиться, $N! Возвращайся ко мне с доказательством того, что ты достойно служишь Орде!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
