INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8436,'Завоевание Низины Арати','Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.$b$bВ Низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, $n!','Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.','Вернитесь к ордынскому вестнику войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завоевание Низины Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш конфликт с Альянсом дошел до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой.$b$bВ Низине Арати идет простая и открытая борьба за ресурсы. Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска! Помоги нам захватить источник ресурсов, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 почетных знака Низины Арати ордынскому вестнику войны рядом со входом на поля боя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ордынскому вестнику войны.',`completedtext_loc8`);
