INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8446,'Под покровом кошмара','Эта вещь так и сочится скверной.$b$bМожет быть, существует связь между ней и драконами, вылетающими из Сна. Кто-то должен разобраться, что делать с этой штукой. Может, тебе обратиться к друидам Лунной поляны или Крепости Кенария?','Найдите того, кто сможет осознать значение поглощенного кошмарами предмета.$b$bМожет быть, вам сможет помочь могущественный друид.','Я должен снять порчу с этого предмета. Этот предмет может пролить свет на мою не удачу проникнуть в Сон. Отдай его мне.','Да, $R?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под покровом кошмара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта вещь так и сочится скверной.$b$bМожет быть, существует связь между ней и драконами, вылетающими из Сна. Кто-то должен разобраться, что делать с этой штукой. Может, тебе обратиться к друидам Лунной поляны или Крепости Кенария?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите того, кто сможет осознать значение поглощенного кошмарами предмета.$b$bМожет быть, вам сможет помочь могущественный друид.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я должен снять порчу с этого предмета. Этот предмет может пролить свет на мою не удачу проникнуть в Сон. Отдай его мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $R?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (8447,'Пробуждение легенд','Воды озера Элуне\'ара смоют кошмары, поглотившие этот предмет. Это займет совсем немного времени. Подожди, $n.','Дождитесь, пока хранитель Ремул из Лунной поляны очистит поглощенный кошмарами предмет.','Возьми это кольцо, $N. Оно сыграло свою роль для Малфуриона. А теперь, послужит нам...','Пробуждение легенд.','Вернитесь к хранителю Ремулу на Озеро Элуне\'ара, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение легенд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воды озера Элуне\'ара смоют кошмары, поглотившие этот предмет. Это займет совсем немного времени. Подожди, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока хранитель Ремул из Лунной поляны очистит поглощенный кошмарами предмет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возьми это кольцо, $N. Оно сыграло свою роль для Малфуриона. А теперь, послужит нам...',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Пробуждение легенд.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Ремулу на Озеро Элуне\'ара, что на Лунной поляне.',`completedtext_loc8`);
