INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8458,'<UNUSED>','Пожалуй, я сумею отыскать этого повелителя демонов, если найду нужные реагенты.$b$bОднако если он действительно так могущественен, мне понадобятся предметы, собранные со смертельно опасных тварей...$b$bПрежде всего мне придется снять заклятия, которые защищают его от соглядатаев. Для этого нужен скальп сатира, но не первого попавшегося, а тенелова из племени Ярой Ненависти.$b$bИщи их в древних развалинах на северо-востоке Пустошей.','Принесите скальп тенелова Маурину Костолому в Пустоши.','Вернитесь к Маурину Костолому на Заставу Скитающихся Духов, что в Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуй, я сумею отыскать этого повелителя демонов, если найду нужные реагенты.$b$bОднако если он действительно так могущественен, мне понадобятся предметы, собранные со смертельно опасных тварей...$b$bПрежде всего мне придется снять заклятия, которые защищают его от соглядатаев. Для этого нужен скальп сатира, но не первого попавшегося, а тенелова из племени Ярой Ненависти.$b$bИщи их в древних развалинах на северо-востоке Пустошей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите скальп тенелова Маурину Костолому в Пустоши.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маурину Костолому на Заставу Скитающихся Духов, что в Пустошах.',`completedtext_loc8`);
