INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8460,'Союзник Древобрюхов','Фурболги Древобрюхов – единственное фурболгское племя, не затронутое порчей. Однако нынче многие расы без разбору убивают всех фурболгов подряд. И потому фурболгов Древобрюхов осталось так мало.$B$BХочешь заслужить доверие? Изгони из Оскверненного леса пораженных порчей фурболгов Мертвого Леса, и в один прекрасный день мы признаем тебя $gсоюзником:союзницей;. Ты найдешь первое племя Мертвого Леса – воинов, землепроходцев и садовников – к западу от меня.','Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 6 воинов, 6 землепроходцев и 6 садовников из племени Мертвого Леса. Выполнив поручение, возвращайтесь в южную часть Оскверненного леса к Изумрудному святилищу.','Мы сильно страдаем от того, что случилось в прошлом. Спасибо за все, что ты сделал для защиты Древобрюхов. И в знак начала нашей дружбы, прими этот скромный подарок.','Вернитесь к Гразлу в Изумрудное святилище, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союзник Древобрюхов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Фурболги Древобрюхов – единственное фурболгское племя, не затронутое порчей. Однако нынче многие расы без разбору убивают всех фурболгов подряд. И потому фурболгов Древобрюхов осталось так мало.$B$BХочешь заслужить доверие? Изгони из Оскверненного леса пораженных порчей фурболгов Мертвого Леса, и в один прекрасный день мы признаем тебя $gсоюзником:союзницей;. Ты найдешь первое племя Мертвого Леса – воинов, землепроходцев и садовников – к западу от меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 6 воинов, 6 землепроходцев и 6 садовников из племени Мертвого Леса. Выполнив поручение, возвращайтесь в южную часть Оскверненного леса к Изумрудному святилищу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы сильно страдаем от того, что случилось в прошлом. Спасибо за все, что ты сделал для защиты Древобрюхов. И в знак начала нашей дружбы, прими этот скромный подарок.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гразлу в Изумрудное святилище, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8461,'Северные фурболги Мертвого Леса','Прямо на юго-западе отсюда расположен лагерь фурболгов Мертвого Леса. В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги стали настоящей угрозой.$B$BПлемя Мертвого Леса злобное, но это все действие скверны, поразившей их разум. Они враждебны не от природы, но тут уж ничего не поделать. Мне невыносимо тяжело сражаться против собратьев.$B$BПрошу тебя, $n, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается.','Нафиен просит вас убить 6 дозорных, 6 мстителей и 6 шаманов из племени Мертвого Леса. По выполнении возвращайтесь на север Оскверненного леса ко входу в Крепость Древобрюхов.','Вернитесь к Нафиену, который находится рядом с Деревней Сквернолапов, что в Оскверненном лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Северные фурболги Мертвого Леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прямо на юго-западе отсюда расположен лагерь фурболгов Мертвого Леса. В лагере царствует порча, и я хочу положить этому конец прежде, чем эти фурболги стали настоящей угрозой.$B$BПлемя Мертвого Леса злобное, но это все действие скверны, поразившей их разум. Они враждебны не от природы, но тут уж ничего не поделать. Мне невыносимо тяжело сражаться против собратьев.$B$BПрошу тебя, $n, делай, что должно, но не рассказывай мне подробностей – у меня и без того сердце разрывается.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нафиен просит вас убить 6 дозорных, 6 мстителей и 6 шаманов из племени Мертвого Леса. По выполнении возвращайтесь на север Оскверненного леса ко входу в Крепость Древобрюхов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нафиену, который находится рядом с Деревней Сквернолапов, что в Оскверненном лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8462,'Беседа с Нафиэном','Кто знает, может ты справишься с еще более страшной угрозой, что нынче нависла над нами, кланом Древобрюхов. Ты уже $gсумел:сумела; показать здесь свою доблесть...$B$BЕще один мой сородич стоит на страже у входа в Крепость Древобрюхов, по этой дороге дальше к северу. Его зовут Нафиен. Он может показаться тебе злобной грязной тварью, но ты его не бойся. Он всего лишь ищет помощи против злых сил, что угрожают нашему дому.','Отправляйтесь на север по главной дороге в Оскверненном лесу и поговорите с фурболгом по имени Нафиен. Он стоит на страже у входа в Крепость Древобрюхов.','Ага... ветер принес мне весть о чужаке не из нашего племени, который ищет союза с фурболгами Крепости Древобрюхов. Добро пожаловать – но знай, мое племя не доверяет чужакам.\n\nВремена сейчас смутные, и мы можем доверять только тем, кто вместе с нами сражается с осквернителями наших краев... тем, кто доказал нам свою верность. А те, кому мы не доверяем, встретят откровенную враждебность, как только войдут в крепость.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беседа с Нафиэном',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кто знает, может ты справишься с еще более страшной угрозой, что нынче нависла над нами, кланом Древобрюхов. Ты уже $gсумел:сумела; показать здесь свою доблесть...$B$BЕще один мой сородич стоит на страже у входа в Крепость Древобрюхов, по этой дороге дальше к северу. Его зовут Нафиен. Он может показаться тебе злобной грязной тварью, но ты его не бойся. Он всего лишь ищет помощи против злых сил, что угрожают нашему дому.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на север по главной дороге в Оскверненном лесу и поговорите с фурболгом по имени Нафиен. Он стоит на страже у входа в Крепость Древобрюхов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага... ветер принес мне весть о чужаке не из нашего племени, который ищет союза с фурболгами Крепости Древобрюхов. Добро пожаловать – но знай, мое племя не доверяет чужакам.\n\nВремена сейчас смутные, и мы можем доверять только тем, кто вместе с нами сражается с осквернителями наших краев... тем, кто доказал нам свою верность. А те, кому мы не доверяем, встретят откровенную враждебность, как только войдут в крепость.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8463,'Нестабильные кристаллы маны','Вернитесь к Аэльдону Озаренному Солнцем на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нестабильные кристаллы маны',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аэльдону Озаренному Солнцем на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8464,'Боевые действия в деревне Зимней Спячки','Клан Древобрюхов готов постоять за себя, $n. В то время как мы позволяем свободно ходить среди нас тем, кому мы доверяем, мы стараемся по возможности избегать общения с другими племенами фурболгов. $b$bПлемя Зимней Спячки в последнее время становится все более враждебным к нам. Они, похоже, впали в состояние ярости, всецело поглощенные собственным страхом и ненавистью ко всему, чего они не понимают. $b$bЯ вынужден просить вас пробить брешь в их рядах для уменьшения угрозы для нас. Ищите их в деревне Зимней Спячки далеко на восток отсюда.','Убейте 8 шаманов, 8 дозорных и 8 ведмедей из племени Зимней Спячки по просьбе Сальфы. Он ждет у входа в Крепость Древобрюхов в Зимних Ключах.','Вернитесь к Сальфе в Зимние Ключи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые действия в деревне Зимней Спячки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Древобрюхов готов постоять за себя, $n. В то время как мы позволяем свободно ходить среди нас тем, кому мы доверяем, мы стараемся по возможности избегать общения с другими племенами фурболгов. $b$bПлемя Зимней Спячки в последнее время становится все более враждебным к нам. Они, похоже, впали в состояние ярости, всецело поглощенные собственным страхом и ненавистью ко всему, чего они не понимают. $b$bЯ вынужден просить вас пробить брешь в их рядах для уменьшения угрозы для нас. Ищите их в деревне Зимней Спячки далеко на восток отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 шаманов, 8 дозорных и 8 ведмедей из племени Зимней Спячки по просьбе Сальфы. Он ждет у входа в Крепость Древобрюхов в Зимних Ключах.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сальфе в Зимние Ключи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8465,'Разговор с Сальфой','Порча расползается не только от фурболгов Мертвого Леса с юга, но и с востока, от фурболгов из племени Зимней Спячки, что в Зимних Ключах. Если хочешь еще нам помочь, поговори с Сальфой по другую сторону берлоги, у входа в Зимние Ключи. Иди туда по левой тропке.$B$BОсторожнее – если мои тамошние сородичи сочтут, что ты – недобрый гость или ненавистный враг, они на тебя нападут. Иди так быстро, как можешь, чтобы избежать стычки. Убьешь кого из древобрюхов, пусть даже защищаясь – вызовешь еще большую враждебность.','Пройдите через Крепость Древобрюхов и выйдите к Зимним Ключам. Поговорите с Сальфой, который стоит на страже у входа в Крепость Древобрюхов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Сальфой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Порча расползается не только от фурболгов Мертвого Леса с юга, но и с востока, от фурболгов из племени Зимней Спячки, что в Зимних Ключах. Если хочешь еще нам помочь, поговори с Сальфой по другую сторону берлоги, у входа в Зимние Ключи. Иди туда по левой тропке.$B$BОсторожнее – если мои тамошние сородичи сочтут, что ты – недобрый гость или ненавистный враг, они на тебя нападут. Иди так быстро, как можешь, чтобы избежать стычки. Убьешь кого из древобрюхов, пусть даже защищаясь – вызовешь еще большую враждебность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите через Крепость Древобрюхов и выйдите к Зимним Ключам. Поговорите с Сальфой, который стоит на страже у входа в Крепость Древобрюхов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8466,'Перья для Гразла','Вернитесь к Гразлу в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перья для Гразла',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гразлу в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8467,'Перья для Нафиэна','Вернитесь к Нафиэну в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перья для Нафиэна',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нафиэну в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (8468,'Вернитесь к сержанту Ка\'рену на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Ка\'рену на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8469,'Бусы для Сальфы','Вернитесь к Сальфе в Оскверненный лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бусы для Сальфы',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сальфе в Оскверненный лес.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8470,'Ритуальный тотем Мертвого Леса','Вы нашли один из ритуальных тотемов фурболгов клана Мертвого Леса. Сам тотем совершенно неописуемой конструкции, и от него исходит ощутимое чувство отчаяния. Если есть предмет, который мог бы стать олицетворением порчи, снедающей фурболгов Мертвого Леса – то вот он.$B$BОдин из фурболгов в Крепости Древобрюхов мог бы найти применение этому предмету... конечно, если вы уже добились достаточного доверия от них, чтобы они снизошли до разговора с вами.','Отнесите ритуальный тотем Мертвого Леса в Крепость Древобрюхов и посмотрите, не пригодится ли этот предмет кому из тамошних фурболгов. Фурболги Крепости Древобрюхов не станут говорить с вами – разве что их отношение к вам нейтральное или лучше.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ритуальный тотем Мертвого Леса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы нашли один из ритуальных тотемов фурболгов клана Мертвого Леса. Сам тотем совершенно неописуемой конструкции, и от него исходит ощутимое чувство отчаяния. Если есть предмет, который мог бы стать олицетворением порчи, снедающей фурболгов Мертвого Леса – то вот он.$B$BОдин из фурболгов в Крепости Древобрюхов мог бы найти применение этому предмету... конечно, если вы уже добились достаточного доверия от них, чтобы они снизошли до разговора с вами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ритуальный тотем Мертвого Леса в Крепость Древобрюхов и посмотрите, не пригодится ли этот предмет кому из тамошних фурболгов. Фурболги Крепости Древобрюхов не станут говорить с вами – разве что их отношение к вам нейтральное или лучше.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8471,'Ритуальный тотем Зимней Спячки','Вы нашли один из ритуальных тотемов Зимней Спячки. Сам тотем представляет собой неописуемую конструкцию, которая испускает почти осязаемые волны страха и отчаяния. Если такую вещь носят все фурболги, то понятно, что довело их до такого состояния.$B$BКто-нибудь из фурболгов логова Древобрюхов наверняка разберется с этой вещью... однако фурболги будут говорить только с теми, кому достаточно доверяют.','Отнесите ритуальный тотем Зимней Спячки в берлогу Древобрюхов и отдайте его фурболгу, который им заинтересуется. Никто из племени Древобрюхов не заговорит с вами, пока вы не завоюете себе среди них достойную репутацию.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ритуальный тотем Зимней Спячки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы нашли один из ритуальных тотемов Зимней Спячки. Сам тотем представляет собой неописуемую конструкцию, которая испускает почти осязаемые волны страха и отчаяния. Если такую вещь носят все фурболги, то понятно, что довело их до такого состояния.$B$BКто-нибудь из фурболгов логова Древобрюхов наверняка разберется с этой вещью... однако фурболги будут говорить только с теми, кому достаточно доверяют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ритуальный тотем Зимней Спячки в берлогу Древобрюхов и отдайте его фурболгу, который им заинтересуется. Никто из племени Древобрюхов не заговорит с вами, пока вы не завоюете себе среди них достойную репутацию.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8471,'This thing... it is in the shape of a Winterfall Ritual Totem, but it has been twisted by forces I cannot begin to comprehend. Whatever taint that has set the Winterfall against us is surely present in this object.$B$BDivine wisdom has brought both this and you to us, $n. We will study this object intently; perhaps one day, the Winterfall will rage against us no longer.$B$BThank you, friend - please accept these offerings in exchange for your benevolence.','$C - you approach us in a peaceful manner, but I sense that you are here on matters that are grave and severe... for both furbolg and $R alike. What have you come to tell us?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','This thing... it is in the shape of a Winterfall Ritual Totem, but it has been twisted by forces I cannot begin to comprehend. Whatever taint that has set the Winterfall against us is surely present in this object.$B$BDivine wisdom has brought both this and you to us, $n. We will study this object intently; perhaps one day, the Winterfall will rage against us no longer.$B$BThank you, friend - please accept these offerings in exchange for your benevolence.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$C - you approach us in a peaceful manner, but I sense that you are here on matters that are grave and severe... for both furbolg and $R alike. What have you come to tell us?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`completedtext_loc8`) VALUES (8472,'Волшебные часовые, которых наши предки изготовили, чтобы охранять город, в последнее время пришли в полную негодность. Они уже не признают в нас своих хозяев и нападают, как только увидят!$b$bОни созданы много лет назад, но волшебные сердечники, на которых они работают, все еще вполне пригодны. Собери эти сердечники и принеси мне, чтобы я мог пустить их в дело. Часовые бродят по разрушенным кварталам Луносвета, на северо-западе.','Вернитесь к магистру Джаронису на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волшебные часовые, которых наши предки изготовили, чтобы охранять город, в последнее время пришли в полную негодность. Они уже не признают в нас своих хозяев и нападают, как только увидят!$b$bОни созданы много лет назад, но волшебные сердечники, на которых они работают, все еще вполне пригодны. Собери эти сердечники и принеси мне, чтобы я мог пустить их в дело. Часовые бродят по разрушенным кварталам Луносвета, на северо-западе.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Джаронису на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8473,'Печальное задание','Вернитесь к Ларианне Речному Ветру на Тропу Золотой Ветви, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Печальное задание',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ларианне Речному Ветру на Тропу Золотой Ветви, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (8474,'Подвеска Старого Белоствола','На подвеске выгравированы инициалы: ЛРВ. Возможно, они помогут вам найти создателя подвески...','Отыщите того, кто мог изготовить подвеску Старого Белоствола. Возможно, он подскажет, что это за предмет?','Ты хочешь мне что-то показать?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подвеска Старого Белоствола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На подвеске выгравированы инициалы: ЛРВ. Возможно, они помогут вам найти создателя подвески...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите того, кто мог изготовить подвеску Старого Белоствола. Возможно, он подскажет, что это за предмет?',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь мне что-то показать?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8475,'Тропа Мертвых','Разумеется, Плеть еще нескоро отступится от нас, но все же оборонять тропу Мертвых необходимо, и мы ценим любую помощь!','Ты $Gвернулся:вернулась;, $N. Разве тебе не нужно сражаться с нежитью у Тропы Мертвых?','Вернитесь к следопыту Джаеле на Тропу Мертвых, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тропа Мертвых',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Разумеется, Плеть еще нескоро отступится от нас, но все же оборонять тропу Мертвых необходимо, и мы ценим любую помощь!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;, $N. Разве тебе не нужно сражаться с нежитью у Тропы Мертвых?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к следопыту Джаеле на Тропу Мертвых, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8476,'$GМолодец:Умница;, $N! Чем больше у нас будет таких как ты, тем быстрее мы вернем нашим землям прежнее великолепие.','Ты найдешь Тор\'Вату и Зеб\'Вату к юго-востоку отсюда. Возвращайся, когда убьешь троллей.','Вернитесь к Лейтенанту Вестнице Зари в Обитель Странников, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N! Чем больше у нас будет таких как ты, тем быстрее мы вернем нашим землям прежнее великолепие.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты найдешь Тор\'Вату и Зеб\'Вату к юго-востоку отсюда. Возвращайся, когда убьешь троллей.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лейтенанту Вестнице Зари в Обитель Странников, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (8477,'Вернитесь к Аратели Кузне Солнца в Обитель Странников, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аратели Кузне Солнца в Обитель Странников, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8478,'Выбор оружия') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выбор оружия',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8479,'Зул\'Марош','Принесите Вень\'яши, пленному троллю в Тор\'Вате, голову вождя Зул\'Мароша. Вождя можно найти в Зеб\'Вате, за озером Элрендар.','Вернитесь к Вень\'яши в Тор\'Вату, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зул\'Марош',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Вень\'яши, пленному троллю в Тор\'Вате, голову вождя Зул\'Мароша. Вождя можно найти в Зеб\'Вате, за озером Элрендар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вень\'яши в Тор\'Вату, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8480,'Потерянное оружие','Отлично, $N! Теперь мы зададим жару этим Презренным!','Ты еще не $Gсобрал:собрала; утраченное оружие?','Вернитесь к Велендрису Белому Рассвету в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянное оружие',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! Теперь мы зададим жару этим Презренным!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты еще не $Gсобрал:собрала; утраченное оружие?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Велендрису Белому Рассвету в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8481,'Корень всех зол','$n, спасибо тебе за то, что $Gнашел:нашла; способ вырвать корень зла из душ племени Зимней Спячки – уничтожить демона, овладевшего ими!$B$BОтнеси этот факел к входу в пещеру Гролнара и поставь его там. Это заставит демона появиться. Вот тогда ты со своими союзниками нападешь на него! Только сущность погибшего демона поможет начать долгий процесс исцеления племени Зимней Спячки... и спасения Крепости Древобрюхов.','Установите факел призыва демона у входа в пещеру Гролнара в деревне фурболгов Зимней Спячки. Сразите демона и добудьте сущность Зандивиуса для Горна Одноглаза из Крепости Древобрюхов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корень всех зол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, спасибо тебе за то, что $Gнашел:нашла; способ вырвать корень зла из душ племени Зимней Спячки – уничтожить демона, овладевшего ими!$B$BОтнеси этот факел к входу в пещеру Гролнара и поставь его там. Это заставит демона появиться. Вот тогда ты со своими союзниками нападешь на него! Только сущность погибшего демона поможет начать долгий процесс исцеления племени Зимней Спячки... и спасения Крепости Древобрюхов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите факел призыва демона у входа в пещеру Гролнара в деревне фурболгов Зимней Спячки. Сразите демона и добудьте сущность Зандивиуса для Горна Одноглаза из Крепости Древобрюхов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (8482,'Все это было у ночного эльфа? Точно? Язык-то явно дворфийский…$B$BНасколько я понимаю из письма, тот, кто его написал, не сам устроил аварию, но был прислан сюда, чтобы понаблюдать за ее результатами. Тут сказано, что наши усилия опасны и безрассудны... но вот кто это был?$B$BНу разумеется! Тот посланец из Стальгорна! Не глупо ли было доверяться тому, кто принадлежит к Альянсу?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все это было у ночного эльфа? Точно? Язык-то явно дворфийский…$B$BНасколько я понимаю из письма, тот, кто его написал, не сам устроил аварию, но был прислан сюда, чтобы понаблюдать за ее результатами. Тут сказано, что наши усилия опасны и безрассудны... но вот кто это был?$B$BНу разумеется! Тот посланец из Стальгорна! Не глупо ли было доверяться тому, кто принадлежит к Альянсу?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (8483,'Дворфийский шпион','Слушай, $n. Ситуация очень деликатная. Мы вычислили шпиона, но убить его открыто не можем. Не можем мы и попытаться его схватить – слишком велик риск, что уйдет.$b$bПрошу тебя: пойди в Северное святилище, найди там геолога Стража Наковальни и убей его. Только тихо: мы не хотим, чтобы пошли разговоры, что мы допустили в свой город шпиона.$b$bПринеси мне в доказательство его голову. Пусть стальгорнцы знают, что к син\'дорай соваться опасно.','Вернитесь к Аэльдону Озаренному Солнцем на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дворфийский шпион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $n. Ситуация очень деликатная. Мы вычислили шпиона, но убить его открыто не можем. Не можем мы и попытаться его схватить – слишком велик риск, что уйдет.$b$bПрошу тебя: пойди в Северное святилище, найди там геолога Стража Наковальни и убей его. Только тихо: мы не хотим, чтобы пошли разговоры, что мы допустили в свой город шпиона.$b$bПринеси мне в доказательство его голову. Пусть стальгорнцы знают, что к син\'дорай соваться опасно.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аэльдону Озаренному Солнцем на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8484,'Знак мира','Твои подвиги выше любых похвал, $n. И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир.$B$BПрошу – отнеси этот дар королю дворфов, что живет в железной горе – вроде бы вы зовете этот город Стальгорном. В былые времена он пытался заключить с нами союз от имени Альянса. Так что теперь достойно будет, чтобы ты $Gзавершил:завершила; труды Альянса по установлению мира с нами.','Отнесите мирное приношение Древобрюхов королю Магни Бронзобороду в Стальгорн.','Действительно, это самый удачный поворот событий. Если бы с этими существами был заключен прочный мир, это, безусловно, дало бы нам преимущество в Калимдора... Я немедленно сообщу об этом другим лидерам Альянса!$B$BЧто до тебя, $N... ты $Gпроявил:проявила; храбрость как в дипломатии, так и в действии. Я благодарю тебя, как и весь Альянс.','$C, добро пожаловать в мои владения. Стальгорн всегда следует считать домом для такого героя, как вы. Какое у тебя дело со мной?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак мира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои подвиги выше любых похвал, $n. И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир.$B$BПрошу – отнеси этот дар королю дворфов, что живет в железной горе – вроде бы вы зовете этот город Стальгорном. В былые времена он пытался заключить с нами союз от имени Альянса. Так что теперь достойно будет, чтобы ты $Gзавершил:завершила; труды Альянса по установлению мира с нами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите мирное приношение Древобрюхов королю Магни Бронзобороду в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Действительно, это самый удачный поворот событий. Если бы с этими существами был заключен прочный мир, это, безусловно, дало бы нам преимущество в Калимдора... Я немедленно сообщу об этом другим лидерам Альянса!$B$BЧто до тебя, $N... ты $Gпроявил:проявила; храбрость как в дипломатии, так и в действии. Я благодарю тебя, как и весь Альянс.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$C, добро пожаловать в мои владения. Стальгорн всегда следует считать домом для такого героя, как вы. Какое у тебя дело со мной?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8485,'Знак мира','Твои подвиги выше любых похвал, $n. И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир.$B$BПрошу – отнеси этот дар вождю орков, что живет в Дуротаре. Кажется, вы называете его город Оргриммаром. В былые времена он пытался заключить с нами союз от имени Орды. Так что теперь достойно будет, чтобы ты $Gзавершил:завершила; труды Орды по установлению мира с нами.','Отнесите мирное приношение Древобрюхов Шоку Нарнсу в Оргриммар.','Действительно, это самый удачный поворот событий. Если бы с этими существами был заключен прочный мир, это, безусловно, дало бы нам преимущество в защите Калимдора от внешних угроз. Я немедленно сообщу об этом другим лидерам Орды, и будут отправлены новые дипломаты!$B$BA за вас, $N... вы проявили храбрость как в дипломатии, так и в действии. Благодарю вас, как и вся Орда.','Вождь тебя приветствует, $C. Твои дела укрепляют Орду в эти смутные времена. Какое у тебя дело ко мной?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак мира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои подвиги выше любых похвал, $n. И раз ты представляешь свой народ, то мы теперь должны заключить с ним мир.$B$BПрошу – отнеси этот дар вождю орков, что живет в Дуротаре. Кажется, вы называете его город Оргриммаром. В былые времена он пытался заключить с нами союз от имени Орды. Так что теперь достойно будет, чтобы ты $Gзавершил:завершила; труды Орды по установлению мира с нами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите мирное приношение Древобрюхов Шоку Нарнсу в Оргриммар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Действительно, это самый удачный поворот событий. Если бы с этими существами был заключен прочный мир, это, безусловно, дало бы нам преимущество в защите Калимдора от внешних угроз. Я немедленно сообщу об этом другим лидерам Орды, и будут отправлены новые дипломаты!$B$BA за вас, $N... вы проявили храбрость как в дипломатии, так и в действии. Благодарю вас, как и вся Орда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вождь тебя приветствует, $C. Твои дела укрепляют Орду в эти смутные времена. Какое у тебя дело ко мной?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8486,'Магическая нестабильность','Ты уже $Gизбавился:избавилась; от волшебных призраков?','Вернитесь к хранительнице энергии Велании в Западное святилище, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магическая нестабильность',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gизбавился:избавилась; от волшебных призраков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранительнице энергии Велании в Западное святилище, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8487,'Пока Артас и его армия Плети не проложили здесь свой гибельный путь к Луносвету, это было действующее волшебное святилище.$b$bА теперь от него не больше проку, чем от любой другой части Тропы Мертвых. Почва заражена, это место кишит нежитью, энергия силовых линий полностью искажена.$b$bИ теперь я хочу знать, $n, обратимо ли это искажение или нет. Собери образцы почвы, чтобы я могла изучить их. Возможно, со временем мы сумеем все исправить?','Отлично. Я попробую более точно проанализировать заразу на почве при помощи заклинаний.','Ты собрал образцы, которые я просила, $N?','Вернитесь к ученице Мирведе в Восточное святилище, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока Артас и его армия Плети не проложили здесь свой гибельный путь к Луносвету, это было действующее волшебное святилище.$b$bА теперь от него не больше проку, чем от любой другой части Тропы Мертвых. Почва заражена, это место кишит нежитью, энергия силовых линий полностью искажена.$b$bИ теперь я хочу знать, $n, обратимо ли это искажение или нет. Собери образцы почвы, чтобы я могла изучить их. Возможно, со временем мы сумеем все исправить?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Я попробую более точно проанализировать заразу на почве при помощи заклинаний.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты собрал образцы, которые я просила, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученице Мирведе в Восточное святилище, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (8488,'Неожиданный результат','Что-то не так, $n. Я чувствую присутствие Плети! Готовься сражаться!','Мои усилия безнадежны, $N. Была изменена сама природа почвы... зараза необратима. Спасибо за помощь. Мне нужно будет попросить тебя об еще одном последнем задании.','Защитите ученицу Мирведу') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неожиданный результат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то не так, $n. Я чувствую присутствие Плети! Готовься сражаться!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои усилия безнадежны, $N. Была изменена сама природа почвы... зараза необратима. Спасибо за помощь. Мне нужно будет попросить тебя об еще одном последнем задании.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите ученицу Мирведу',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8489,'Невредимый преобразователь','Кажется, перед вами один из чародейских преобразователей, о которых говорила хранительница энергии Велания. Огонь его не коснулся, так что он может ей пригодиться.','Принесите хранительнице энергии Велании невредимый чародейский преобразователь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невредимый преобразователь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, перед вами один из чародейских преобразователей, о которых говорила хранительница энергии Велания. Огонь его не коснулся, так что он может ей пригодиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите хранительнице энергии Велании невредимый чародейский преобразователь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8490,'Усиление обороны','Вернитесь к хранителю рун Дериану к Руническому камню Фалитасу, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Усиление обороны',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю рун Дериану к Руническому камню Фалитасу, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8491,'Добывание шкур','Отлично, $N! Вот, возьми в награду эти доспехи. Кстати, ты $Gпринес:принесла; столько шкур, что их хватит на что-нибудь еще.','О, ты уже здесь! А где шкуры?','Вернитесь к Велану Светлому Тополю в деревню Легкий Ветерок, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добывание шкур',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! Вот, возьми в награду эти доспехи. Кстати, ты $Gпринес:принесла; столько шкур, что их хватит на что-нибудь еще.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, ты уже здесь! А где шкуры?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Велану Светлому Тополю в деревню Легкий Ветерок, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8492,'Альянсу не хватает медных слитков!','Здорово, |3-6($c)! На вид ты вполне $gпригоден:пригодна; к тому, чтобы принять участие в подготовке к войне! Нам пригодится любая помощь, так что наступил твой звездный час.$B$BЯ собираю медные слитки стопками по двадцать штук. Дело благое, да? Ты как, хочешь оказать помощь Альянсу?','Принесите 20 медных слитков сержанту Каменлобу в Палаты Войны Стальгорна.','Похвально, солдат! Сейчас мы уложим эти слитки в штабель и используем их по назначению. Альянс будет гордиться тобой. $B$BЕсли раздобудешь еще стопку медных слитков, не раздумывай, неси мне.','Ну что, солдат, удалось собрать 20 медных слитков?','Вернитесь к сержанту Камнелобу в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает медных слитков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здорово, |3-6($c)! На вид ты вполне $gпригоден:пригодна; к тому, чтобы принять участие в подготовке к войне! Нам пригодится любая помощь, так что наступил твой звездный час.$B$BЯ собираю медные слитки стопками по двадцать штук. Дело благое, да? Ты как, хочешь оказать помощь Альянсу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 медных слитков сержанту Каменлобу в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похвально, солдат! Сейчас мы уложим эти слитки в штабель и используем их по назначению. Альянс будет гордиться тобой. $B$BЕсли раздобудешь еще стопку медных слитков, не раздумывай, неси мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, солдат, удалось собрать 20 медных слитков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Камнелобу в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8493,'Альянсу все еще не хватает медных слитков!','Ты $gвернулся:вернулась;, |3-6($c)? Превосходно! Для подготовки к войне в Ан\'Кираже все еще нужны медные слитки. Ты поможешь нам собрать их?','Принесите 20 медных слитков сержанту Каменлобу в Военный двор Стальгорна.','Прекрасная работа! Добыча и выплавка всей этой меди, должно быть, была тем еще развлечением. Если, конечно, ты не $gкупил:купила; слитки на аукционе. В любом случае, главное – результат. Приложенные тобой усилия не останутся незамеченными, |3-6($c). Если раздобудешь еще слитки, без малейшего колебания неси их мне.','Ты уже $gвернулся:вернулась;, |3-6($c)? Превосходно! Слитки, которые тебе удалось достать, сослужат нам добрую службу. Я могу сказать со всей ответственностью, что медь пойдет на изготовление паровых танков, а так же вертолетов и прочей военной техники.$B$BИ пусть эти штабеля меди не смущают твой взгляд, к сожалению, их пока недостаточно, чтобы подготовится к войне в Ан\'Кираже как следует. Но ведь мы еще можем рассчитывать на твою помощь?','Вернитесь к сержанту Камнелобу в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу все еще не хватает медных слитков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвернулся:вернулась;, |3-6($c)? Превосходно! Для подготовки к войне в Ан\'Кираже все еще нужны медные слитки. Ты поможешь нам собрать их?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 медных слитков сержанту Каменлобу в Военный двор Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасная работа! Добыча и выплавка всей этой меди, должно быть, была тем еще развлечением. Если, конечно, ты не $gкупил:купила; слитки на аукционе. В любом случае, главное – результат. Приложенные тобой усилия не останутся незамеченными, |3-6($c). Если раздобудешь еще слитки, без малейшего колебания неси их мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $gвернулся:вернулась;, |3-6($c)? Превосходно! Слитки, которые тебе удалось достать, сослужат нам добрую службу. Я могу сказать со всей ответственностью, что медь пойдет на изготовление паровых танков, а так же вертолетов и прочей военной техники.$B$BИ пусть эти штабеля меди не смущают твой взгляд, к сожалению, их пока недостаточно, чтобы подготовится к войне в Ан\'Кираже как следует. Но ведь мы еще можем рассчитывать на твою помощь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Камнелобу в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8494,'Альянсу не хватает железных слитков!','Эгей, $gмистер:мисс.; Красивые Штанишки, ты прямо отрада для моих измученных глаз. Пока ты $gшатался:шаталась; по городам и весям в поисках приключений, у нас тут произошла прорва всего. К примеру, Альянс вот готовится к войне в Ан\'Кираже, и всем резко понадобились железные слитки... чертова прорва железных слитков. Можешь таскать их мне стопками по двадцать. Ну как, могу я на тебя рассчитывать, |3-6($c)?','Принесите 20 железных слитков капралу Карнсу в Палаты Войны Стальгорна.','Ну хорошо, $N, на этот раз тебе удалось вывернуться. Пожалуй, на будущее за тобой стоит приглядывать. Как ни тяжело это говорить, но спасибо тебе за помощь. Альянс тебя не забудет, и я тоже. А теперь дуй-ка отсюда и лучше помоги еще кому-нибудь в заготовках.','Принесите 20 железных слитков капралу Карнсу в Палаты Войны Стальгорна.','Вернитесь к капралу Карнсу в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает железных слитков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эгей, $gмистер:мисс.; Красивые Штанишки, ты прямо отрада для моих измученных глаз. Пока ты $gшатался:шаталась; по городам и весям в поисках приключений, у нас тут произошла прорва всего. К примеру, Альянс вот готовится к войне в Ан\'Кираже, и всем резко понадобились железные слитки... чертова прорва железных слитков. Можешь таскать их мне стопками по двадцать. Ну как, могу я на тебя рассчитывать, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 железных слитков капралу Карнсу в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну хорошо, $N, на этот раз тебе удалось вывернуться. Пожалуй, на будущее за тобой стоит приглядывать. Как ни тяжело это говорить, но спасибо тебе за помощь. Альянс тебя не забудет, и я тоже. А теперь дуй-ка отсюда и лучше помоги еще кому-нибудь в заготовках.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Принесите 20 железных слитков капралу Карнсу в Палаты Войны Стальгорна.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капралу Карнсу в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8495,'Альянсу по-прежнему не хватает железных слитков!','Ты опять здесь? Не заставляй меня слишком хорошо о тебе думать, |3-6($c), а то я прямо таять начинаю. Как видишь, мы еще не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и все остальное-прочее, что нужно изготовить для большой драчки. Я думаю, ты сможешь принести еще слитков двадцать в перерыве между своими шатаниями в Зул\'Гуруб, или где там у вас, у молодежи, сейчас модно тусоваться.','Принесите 20 железных слитков капралу Карнсу на аэродром в Дун Морог.','Должно быть, в Пылающих Степях выпал снег. Вы только посмотрите, это же $N, да не просто так, а с подарком. Двадцать железных слитков! Именно то, что мне нужно.$B$BХочу сказать тебе со всей серьезностью, $N, Альянс перед тобой в долгу. А теперь давай, шлепай отсюда и помоги еще кому-нибудь в заготовках.','Ты опять здесь? Не заставляй меня слишком хорошо о тебе думать, $C, а то я буквально таю изнутри. Как видишь, мы еще не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и все остальное-прочее, что нужно изготовить для большой драчки. Я думаю, ты сможешь принести еще слитков двадцать в перерыве между своими шатаниями в Зул\'Гуруб, или где там у вас, у молодежи, сейчас модно тусоваться.','Вернитесь к капралу Карнсу в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает железных слитков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты опять здесь? Не заставляй меня слишком хорошо о тебе думать, |3-6($c), а то я прямо таять начинаю. Как видишь, мы еще не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и все остальное-прочее, что нужно изготовить для большой драчки. Я думаю, ты сможешь принести еще слитков двадцать в перерыве между своими шатаниями в Зул\'Гуруб, или где там у вас, у молодежи, сейчас модно тусоваться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 железных слитков капралу Карнсу на аэродром в Дун Морог.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Должно быть, в Пылающих Степях выпал снег. Вы только посмотрите, это же $N, да не просто так, а с подарком. Двадцать железных слитков! Именно то, что мне нужно.$B$BХочу сказать тебе со всей серьезностью, $N, Альянс перед тобой в долгу. А теперь давай, шлепай отсюда и помоги еще кому-нибудь в заготовках.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты опять здесь? Не заставляй меня слишком хорошо о тебе думать, $C, а то я буквально таю изнутри. Как видишь, мы еще не собрали достаточно железных слитков, чтобы хватило на оружие, броню, паровые танки и все остальное-прочее, что нужно изготовить для большой драчки. Я думаю, ты сможешь принести еще слитков двадцать в перерыве между своими шатаниями в Зул\'Гуруб, или где там у вас, у молодежи, сейчас модно тусоваться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капралу Карнсу в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8496,'Запас бинтов','В последнее время мы понесли серьезные потери, и запас бинтов стремительно иссякает. Добудь нам первоклассные перевязочные материалы и отнеси их призывательнице ветров Гордому Рогу в Крепость Кенария.','Принесите 30 плотных бинтов из рунической ткани, 30 плотных шелковых бинтов и 30 бинтов из магической ткани призывательнице ветров Гордый Рог в Крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу X.','Ты как раз вовремя. Принесенные тобой перевязочные материалы спасут немало жизней. Мы благодарны тебе за труды. Вот твое следующее задание.','У тебя есть что-то для меня, $N?','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запас бинтов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В последнее время мы понесли серьезные потери, и запас бинтов стремительно иссякает. Добудь нам первоклассные перевязочные материалы и отнеси их призывательнице ветров Гордому Рогу в Крепость Кенария.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 30 плотных бинтов из рунической ткани, 30 плотных шелковых бинтов и 30 бинтов из магической ткани призывательнице ветров Гордый Рог в Крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу X.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты как раз вовремя. Принесенные тобой перевязочные материалы спасут немало жизней. Мы благодарны тебе за труды. Вот твое следующее задание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8497,'Неприкосновенный запас','В Крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих наборов для выживания отправляющихся в пустыню и отнеси их Каландрате в Крепость Кенария.','Принесите 4 сферы воды, 4 мощных противоядия и 4 копченые пустынные клецки Каландрате в таверну в Крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу I.','Отлично! Нам очень нужны эти материалы. Спасибо.','У тебя есть что-то для меня, $N?','Вернитесь к Каландрате в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприкосновенный запас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих наборов для выживания отправляющихся в пустыню и отнеси их Каландрате в Крепость Кенария.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 сферы воды, 4 мощных противоядия и 4 копченые пустынные клецки Каландрате в таверну в Крепости Кенария в Силитусе. Кроме того, сдайте тыловую задачу I.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Нам очень нужны эти материалы. Спасибо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каландрате в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8498,'Боевые приказы Сумеречного Молота','Разведчики донесли, что от вождей Сумеречного Молота поступили новые приказы. Их распространяют пророки под охраной солдат. Перехвати эти приказы и принеси их командиру Мар\'алиту.','Добудьте боевые приказы Сумеречного Молота и отнесите их командиру Мар\'алиту в Крепость Кенария в Силитусе. Для завершения задания понадобится тактическая задача X.','Великолепно. Главное – опережать противника на ход. Благодаря полученным сведениям, нам известны намерения Сумеречного Молота.','Что ты мне $Gпринес:принесла;, $N?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые приказы Сумеречного Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики донесли, что от вождей Сумеречного Молота поступили новые приказы. Их распространяют пророки под охраной солдат. Перехвати эти приказы и принеси их командиру Мар\'алиту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте боевые приказы Сумеречного Молота и отнесите их командиру Мар\'алиту в Крепость Кенария в Силитусе. Для завершения задания понадобится тактическая задача X.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Главное – опережать противника на ход. Благодаря полученным сведениям, нам известны намерения Сумеречного Молота.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ты мне $Gпринес:принесла;, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8499,'Альянсу не хватает ториевых слитков!','Крайне любезно с твоей стороны, что ты так беспокоишься о нуждах Альянса. Приготовления к войне идут полным ходом, и, помимо всего прочего, нам нужно очень много ториевых слитков. Именно за их сбор я и отвечаю. Торий необходим для изготовления различных военных машин, в основном паровых танков, которые планируется доставлять по воздуху в Силитус сразу же после сборки. За помощь в добыче ториевых слитков я была бы очень признательна, |3-6($c).','Принесите 20 ториевых слитков госпоже Двукоссе в Палаты Войны Стальгорна.','О, спасибо тебе, $C! Огромное спасибо! Прибавилось еще двадцать, осталось собрать еще несчетное количество. Альянс пред тобой в долгу. Если раздобудешь еще двадцать слитков, обращайся ко мне.','О, посылка от моего брата? Великолепно! Сегодня мне по-настоящему светит удача!','Вернитесь к госпоже Двукоссе в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает ториевых слитков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крайне любезно с твоей стороны, что ты так беспокоишься о нуждах Альянса. Приготовления к войне идут полным ходом, и, помимо всего прочего, нам нужно очень много ториевых слитков. Именно за их сбор я и отвечаю. Торий необходим для изготовления различных военных машин, в основном паровых танков, которые планируется доставлять по воздуху в Силитус сразу же после сборки. За помощь в добыче ториевых слитков я была бы очень признательна, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 ториевых слитков госпоже Двукоссе в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, спасибо тебе, $C! Огромное спасибо! Прибавилось еще двадцать, осталось собрать еще несчетное количество. Альянс пред тобой в долгу. Если раздобудешь еще двадцать слитков, обращайся ко мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, посылка от моего брата? Великолепно! Сегодня мне по-настоящему светит удача!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к госпоже Двукоссе в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8500,'Альянсу по-прежнему не хватает ториевых слитков!','Добро пожаловать снова, $n. Надеюсь, у тебя все в порядке? Это правда, нам все еще нужны ториевые слитки. Если сможешь достать их, я буду очень признательна.','Принесите 20 ториевых слитков госпоже Двукоссе на аэродром в Дун Морог.','Отличная работа, $C! Я прослежу, чтобы ториевые слитки были хорошо упакованы и доставлены кузнецам и инженерам, которые изготавливают для нашей армии военную технику. Спасибо тебе еще раз. Если сможешь достать еще двадцать слитков, я приму их у тебя с благодарностью.','Добро пожаловать снова, $N. Надеюсь, у тебя все в порядке? Это правда, нам все еще нужны ториевые слитки. Если сможешь достать их, я буду очень признательна.','Вернитесь к госпоже Двукоссе в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает ториевых слитков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать снова, $n. Надеюсь, у тебя все в порядке? Это правда, нам все еще нужны ториевые слитки. Если сможешь достать их, я буду очень признательна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 ториевых слитков госпоже Двукоссе на аэродром в Дун Морог.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $C! Я прослежу, чтобы ториевые слитки были хорошо упакованы и доставлены кузнецам и инженерам, которые изготавливают для нашей армии военную технику. Спасибо тебе еще раз. Если сможешь достать еще двадцать слитков, я приму их у тебя с благодарностью.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать снова, $N. Надеюсь, у тебя все в порядке? Это правда, нам все еще нужны ториевые слитки. Если сможешь достать их, я буду очень признательна.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к госпоже Двукоссе в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8501,'Цель: острожалы из улья Аши','По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Аши. Твоей основной целью будут летающие острожалы из этого улья.$b$BВыполнив задание, отчитайся командиру Мар\'алиту.','Убейте 30 острожалов из улья Аши и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу XII.','Отличная работа, $N. Твои подвиги в сражении при Улье Аши не прошли незамеченными.','Ты хочешь что-то сказать, $N?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: острожалы из улья Аши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По мере нарастания конфликта, силитиды представляют все большую опасность для наших операций. Тебя избрали для участия в нападении на улей Аши. Твоей основной целью будут летающие острожалы из этого улья.$b$BВыполнив задание, отчитайся командиру Мар\'алиту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 острожалов из улья Аши и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу XII.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Твои подвиги в сражении при Улье Аши не прошли незамеченными.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь что-то сказать, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8502,'Цель: рабочие из улья Аши','Убейте 30 рабочих из улья Аши и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу III.','Отличная работа, $N. Без рабочих силитидам придется нелегко. Кто будет восстанавливать их ульи?','Ты хочешь что-то сказать, $C?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: рабочие из улья Аши',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 рабочих из улья Аши и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу III.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Без рабочих силитидам придется нелегко. Кто будет восстанавливать их ульи?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь что-то сказать, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8503,'Альянсу не хватает удавника!','Знаешь ли ты, |3-6($c), насколько широко и разнообразно применение удавника? Как, я тебе уже об этом рассказывал? Правда?.. Ну ладно. В любом случае, нам нужно много этой травы, и когда я говорю так, я имею в виду действительно МНОГО! Не следует ли тебе помочь нам, как ты считаешь? Я понимаю, это означает, что тебе придется остаться без всех этих чудесных штучек, которые можно приготовить из удавника... но ведь это ради благого дела!','Принесите 20 стеблей удавника рядовому Драксельмеру в Палаты Войны Стальгорна.','Урра! Еще двадцатью меньше собирать. Отлично справляешься с работой! Пойду уберу травы, пока они не засохли. Времени так мало, а удавника так много!$B$BСпасибо еще раз, |3-6($c)!','Это грязный поклеп! Я не брал отсюда ни одной травинки! Хотя соблазн очень велик... ведь это ж практически настоящая панацея от утилитарной бесполезности.  кашляет  Да, кстати, как там насчет удавника, который ты $gдолжен был:должна была; принести мне?','Вернитесь к рядовому Драксельмеру в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает удавника!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь ли ты, |3-6($c), насколько широко и разнообразно применение удавника? Как, я тебе уже об этом рассказывал? Правда?.. Ну ладно. В любом случае, нам нужно много этой травы, и когда я говорю так, я имею в виду действительно МНОГО! Не следует ли тебе помочь нам, как ты считаешь? Я понимаю, это означает, что тебе придется остаться без всех этих чудесных штучек, которые можно приготовить из удавника... но ведь это ради благого дела!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 стеблей удавника рядовому Драксельмеру в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Урра! Еще двадцатью меньше собирать. Отлично справляешься с работой! Пойду уберу травы, пока они не засохли. Времени так мало, а удавника так много!$B$BСпасибо еще раз, |3-6($c)!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это грязный поклеп! Я не брал отсюда ни одной травинки! Хотя соблазн очень велик... ведь это ж практически настоящая панацея от утилитарной бесполезности.  кашляет  Да, кстати, как там насчет удавника, который ты $gдолжен был:должна была; принести мне?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рядовому Драксельмеру в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8504,'Альянсу по-прежнему не хватает удавника!','Эй, ты там... Ой... Что это было? Ах, да, $n! $GЗашел:Зашла; поинтересоваться, не нужно ли мне еще удавника? О, тебе крупно повезло, потому что ответ на этот жизненно важный вопрос – конечно, ДА! Ну как, соберешь еще двадцать штук?','Принесите 20 стеблей удавника рядовому Драксельмеру на аэродром в Дун Морог.','Вернитесь к рядовому Драксельмеру в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает удавника!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты там... Ой... Что это было? Ах, да, $n! $GЗашел:Зашла; поинтересоваться, не нужно ли мне еще удавника? О, тебе крупно повезло, потому что ответ на этот жизненно важный вопрос – конечно, ДА! Ну как, соберешь еще двадцать штук?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 стеблей удавника рядовому Драксельмеру на аэродром в Дун Морог.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рядовому Драксельмеру в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8505,'Альянсу не хватает лилового лотоса!','$C, цветы лилового лотоса где только не применяют. От имени Альянса я отвечаю за заготовку лотоса в количестве, достаточном для удовлетворения всех военных нужд.$B$BНо чтобы собирать цветы, мне нужны добровольцы. Справишься с этим заданием?','Принесите 20 цветков лилового лотоса мастеру Ночной Песне в Палаты Войны Стальгорна.','Твой вклад очень ценен для всех нас, $C. Только объединив наши усилия, мы сможем отбросить армию безжалостных силитидов и одержать победу. Даже Орда занимается сбором лилового лотоса. Если снова наберешь этих цветов, возвращайся ко мне.','Тебе удалось собрать цветы лилового лотоса?','Вернитесь к мастеру Песне Ночи в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает лилового лотоса!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, цветы лилового лотоса где только не применяют. От имени Альянса я отвечаю за заготовку лотоса в количестве, достаточном для удовлетворения всех военных нужд.$B$BНо чтобы собирать цветы, мне нужны добровольцы. Справишься с этим заданием?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 цветков лилового лотоса мастеру Ночной Песне в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твой вклад очень ценен для всех нас, $C. Только объединив наши усилия, мы сможем отбросить армию безжалостных силитидов и одержать победу. Даже Орда занимается сбором лилового лотоса. Если снова наберешь этих цветов, возвращайся ко мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать цветы лилового лотоса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Песне Ночи в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8506,'Альянсу по-прежнему не хватает лилового лотоса!','Добро пожаловать обратно, |3-6($c). Наши запасы лилового лотоса растут, но нам все равно нужно еще. Займись сбором цветов, если можешь, я тебя очень прошу.','Принесите 20 цветков лилового лотоса мастеру Ночной Песне на аэродром в Дун Морог.','Вернитесь к мастеру Песне Ночи в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает лилового лотоса!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать обратно, |3-6($c). Наши запасы лилового лотоса растут, но нам все равно нужно еще. Займись сбором цветов, если можешь, я тебя очень прошу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 цветков лилового лотоса мастеру Ночной Песне на аэродром в Дун Морог.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к мастеру Песне Ночи в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8507,'Рутинное задание','Приветствую тебя, $n. Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные.$b$bДружина Стальгорна под предводительством капитана Черной Наковальни расквартирована рядом с Ульем Зора.$b$bПоговори с капитаном и его лейтенантом, Джанелой Твердомолот, а потом возвращайся. Тем временем я подготовлю для тебя новое задание.$b$bАх да, сделай одолжение, держись подальше от легиона Оргриммара. Нам нелегко удерживать эти два войска от грызни, очень уж они друг друга не любят.','Поступите в распоряжение дружины Стальгорна возле Улья Зора. Подготовьте неподписанные бумаги о полевых обязанностях и получите подписанные бумаги о полевых обязанностях от капитана Черной Наковальни, вернитесь к призывателю ветров Калдону в Крепость Кенария в Силитусе.$b$bВнимание: исцеление или наложение благоприятных заклинаний на бойцов дружины Стальгорна переводит в режим PvP.','Отлично, $N. Я подготовила целую серию заданий, которые наилучшим образом распорядятся твоими навыками.$B$BЕсли ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!$B$BЕсли тебе понадобится новое задание, возвращайся к капитану Черной Наковальне.','Дружина капитана Черной Наковальни расквартирована рядом с Ульем Зора. Если ты не найдешь его, поговори с Джанелой Твердомолот.','Вернитесь к призывателю ветров Калдону в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рутинное задание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $n. Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные.$b$bДружина Стальгорна под предводительством капитана Черной Наковальни расквартирована рядом с Ульем Зора.$b$bПоговори с капитаном и его лейтенантом, Джанелой Твердомолот, а потом возвращайся. Тем временем я подготовлю для тебя новое задание.$b$bАх да, сделай одолжение, держись подальше от легиона Оргриммара. Нам нелегко удерживать эти два войска от грызни, очень уж они друг друга не любят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поступите в распоряжение дружины Стальгорна возле Улья Зора. Подготовьте неподписанные бумаги о полевых обязанностях и получите подписанные бумаги о полевых обязанностях от капитана Черной Наковальни, вернитесь к призывателю ветров Калдону в Крепость Кенария в Силитусе.$b$bВнимание: исцеление или наложение благоприятных заклинаний на бойцов дружины Стальгорна переводит в режим PvP.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N. Я подготовила целую серию заданий, которые наилучшим образом распорядятся твоими навыками.$B$BЕсли ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!$B$BЕсли тебе понадобится новое задание, возвращайся к капитану Черной Наковальне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дружина капитана Черной Наковальни расквартирована рядом с Ульем Зора. Если ты не найдешь его, поговори с Джанелой Твердомолот.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывателю ветров Калдону в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8508,'Бумаги о полевых обязанностях','Да, я полагаю, что эта небольшая стычка перейдет в боевое дежурство. Отнеси их обратно в Крепость Кенария, я уверен, у них для тебя найдется работа.','Я так понимаю, ты хочешь подписать эти бумаги?','Вернитесь к капитану Черной Наковальне в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бумаги о полевых обязанностях',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я полагаю, что эта небольшая стычка перейдет в боевое дежурство. Отнеси их обратно в Крепость Кенария, я уверен, у них для тебя найдется работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я так понимаю, ты хочешь подписать эти бумаги?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Черной Наковальне в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8509,'Альянсу не хватает слез Артаса!','Я предпочитаю говорить быстро и по существу, |3-6($c). Альянсу нужно много слез Артаса для войны в Ан\'Кираже. Не спрашивай меня, зачем, я всего лишь выполняю приказ. Собери столько этих цветов, сколько унесешь, и сдай мне. Ну что, возьмешься за это задание?','Принесите 20 слез Артаса старшему сержанту Гермайн в Палаты Войны Стальгорна.','Неплохо сработано, $C. Должна сказать, я приятно удивлена. Ты никогда бы не $Gповерил:поверила;, сколько людей приходят, обещают помочь и не возвращаются. Одну секунду, сейчас я упакую травы в ящик и прикреплю к нему бирку с твоим именем, а потом сможем поговорить на тему того, нужны ли мне еще эти растения.','Что? Докладывай быстро и четко, $C! Тебе удалось собрать необходимое количество слез Артаса?','Вернитесь к старшему сержанту Гермайн в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает слез Артаса!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я предпочитаю говорить быстро и по существу, |3-6($c). Альянсу нужно много слез Артаса для войны в Ан\'Кираже. Не спрашивай меня, зачем, я всего лишь выполняю приказ. Собери столько этих цветов, сколько унесешь, и сдай мне. Ну что, возьмешься за это задание?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 слез Артаса старшему сержанту Гермайн в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо сработано, $C. Должна сказать, я приятно удивлена. Ты никогда бы не $Gповерил:поверила;, сколько людей приходят, обещают помочь и не возвращаются. Одну секунду, сейчас я упакую травы в ящик и прикреплю к нему бирку с твоим именем, а потом сможем поговорить на тему того, нужны ли мне еще эти растения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что? Докладывай быстро и четко, $C! Тебе удалось собрать необходимое количество слез Артаса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему сержанту Гермайн в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8510,'Альянсу снова нужны слезы Артаса','Так, похоже, слезы Артаса мне все еще нужны. Я предполагаю, что они растут там же, где и раньше. Чем быстрее мы закончим подготовку, тем быстрее начнем наступление на Ан\'Кираж.$B$BЯ могу вновь рассчитывать на твою помощь, |3-6($c)?','Принесите 20 цветков слезы Артаса старшему сержанту Гермайн на аэродром в Дун Морог.','Вернитесь к старшему сержанту Гермайн в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу снова нужны слезы Артаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так, похоже, слезы Артаса мне все еще нужны. Я предполагаю, что они растут там же, где и раньше. Чем быстрее мы закончим подготовку, тем быстрее начнем наступление на Ан\'Кираж.$B$BЯ могу вновь рассчитывать на твою помощь, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 цветков слезы Артаса старшему сержанту Гермайн на аэродром в Дун Морог.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему сержанту Гермайн в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8511,'Альянсу не хватает легкой кожи!','Наш клан Обдирщиков Камня испокон века знал толк в снятии шкур, |3-6($c). Как говорится, и с камня снимем шкуру. Потому-то Альянс и попросил нас взяться за заготовку тонкой кожи для войны в Ан\'Кираже. Я слежу, чтобы кожа была хорошо выдублена, уж не знаю, для чего она там понадобится. Но без помощи мне никак не обойтись.$B$BПока я здесь за всем надзираю, тебе придется прогуляться малость и добыть кож, а потом принести их мне. Ну что, $gпаренек:девушка;, возьмешься за дело?','Принесите 10 легких кож Бонни Шлифовальщице в Палаты Войны Стальгорна.','Я прямо скажу, Альянску крупно повезло, что у него есть такие искушенные специалисты по свежеванию, как ты,|3-6($c). Уж я прослежу, чтобы ни одну кожу ненароком не попортили. Спасибо тебе – и не забудь, когда я пересчитаю кожу, справиться у меня, не требуется ли нам еще.','Ну, $c, где обещанная кожа?','Вернитесь к Бонни Шлифовальщице в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает легкой кожи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш клан Обдирщиков Камня испокон века знал толк в снятии шкур, |3-6($c). Как говорится, и с камня снимем шкуру. Потому-то Альянс и попросил нас взяться за заготовку тонкой кожи для войны в Ан\'Кираже. Я слежу, чтобы кожа была хорошо выдублена, уж не знаю, для чего она там понадобится. Но без помощи мне никак не обойтись.$B$BПока я здесь за всем надзираю, тебе придется прогуляться малость и добыть кож, а потом принести их мне. Ну что, $gпаренек:девушка;, возьмешься за дело?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 легких кож Бонни Шлифовальщице в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я прямо скажу, Альянску крупно повезло, что у него есть такие искушенные специалисты по свежеванию, как ты,|3-6($c). Уж я прослежу, чтобы ни одну кожу ненароком не попортили. Спасибо тебе – и не забудь, когда я пересчитаю кожу, справиться у меня, не требуется ли нам еще.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, $c, где обещанная кожа?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бонни Шлифовальщице в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8512,'Альянсу по-прежнему не хватает легкой кожи!','Рада снова тебя видеть, $n. Похоже, что мы еще не собрали достаточно кожи для наших воинских нужд. Если принесешь мне штук десять кож, это будет просто отлично.','Принесите 10 кусков легкой кожи Бонни Шлифовальщице на аэродром в Дун Морог.','Вернитесь к Бонни Шлифовальщице в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает легкой кожи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рада снова тебя видеть, $n. Похоже, что мы еще не собрали достаточно кожи для наших воинских нужд. Если принесешь мне штук десять кож, это будет просто отлично.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 кусков легкой кожи Бонни Шлифовальщице на аэродром в Дун Морог.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бонни Шлифовальщице в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8513,'Альянсу не хватает средней кожи!','Так точно, $gсэр:мэм;, я отвечаю за сбор всей средней кожи, необходимой для подготовки к войне с Ан\'Киражем. Если вы можете раздобыть среднюю кожу, неважно где, сдайте ее мне, пожалуйста. Я буду благодарен за любую помощь, если у вас найдется на нее время.','Принесите 10 средних кож рядовому Портеру в Палаты Войны Стальгорна.','Вау! Похоже, вы и правда решили помочь. Большое спасибо за ваш вклад в общее дело. Пойду-ка я упакую и пересчитаю кожи. Нет, вы действительно знаете, чем скрасить день простого служаки.','Так точно, $gсэр:мэм;, я помню вас. Вы принесли среднюю кожу?','Вернитесь к рядовому Портеру в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает средней кожи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так точно, $gсэр:мэм;, я отвечаю за сбор всей средней кожи, необходимой для подготовки к войне с Ан\'Киражем. Если вы можете раздобыть среднюю кожу, неважно где, сдайте ее мне, пожалуйста. Я буду благодарен за любую помощь, если у вас найдется на нее время.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 средних кож рядовому Портеру в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вау! Похоже, вы и правда решили помочь. Большое спасибо за ваш вклад в общее дело. Пойду-ка я упакую и пересчитаю кожи. Нет, вы действительно знаете, чем скрасить день простого служаки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так точно, $gсэр:мэм;, я помню вас. Вы принесли среднюю кожу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рядовому Портеру в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8514,'Альянсу по-прежнему не хватает средней кожи!','Так точно, $gсэр:мэм;, к настоящему времени нам удалось собрать $2063w кусков средней кожи. Я знаю, что прошу слишком многого, но не могли бы вы снова оказать помощь? Если желаете, конечно. Мне необходимо выполнить установленную норму.','Принесите 10 средних кож рядовому Портеру на аэродром в Дун Морог.','Так точно, $gсэр:мэм;, мы собрали много средней кожи, но все равно недостаточно. Заверяю вас, мы найдем этой коже самое наилучшее применение, ни один клочок не пропадет зря. Я знаю, что требую слишком многого, но если у вас еще сохранилось желание, помогите мне набрать установленную норму.','Вернитесь к рядовому Портеру в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает средней кожи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так точно, $gсэр:мэм;, к настоящему времени нам удалось собрать $2063w кусков средней кожи. Я знаю, что прошу слишком многого, но не могли бы вы снова оказать помощь? Если желаете, конечно. Мне необходимо выполнить установленную норму.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 средних кож рядовому Портеру на аэродром в Дун Морог.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так точно, $gсэр:мэм;, мы собрали много средней кожи, но все равно недостаточно. Заверяю вас, мы найдем этой коже самое наилучшее применение, ни один клочок не пропадет зря. Я знаю, что требую слишком многого, но если у вас еще сохранилось желание, помогите мне набрать установленную норму.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рядовому Портеру в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8515,'Альянсу не хватает плотной кожи!','О, будет так здорово! $C, приготовления к ан\'киражской войне идут вовсю, и так получилось, что я отвечаю за заготовку плотной кожи. Из нее мы сможем наделать тысячи разных вещей, но сначала надо ее достать – тоже тысячами. В буквальном смысле. И тут на сцену выходишь ты.$B$BТы ведь принесешь мне отличную увесистую кипу плотной кожи? Правда-правда?','Принесите 10 плотных кож Марте Остроигл в Палаты Войны Стальгорна.','О, я знала, что ты справишься, $C, конечно же, я это знала! Я отправлю эту кожу по нужному адресу, как только смогу. Ага, а теперь давай-ка посмотрим. Похоже, в итоге все получается очень, очень миленько. Загляни ко мне еще разочек, я сейчас проверю, не нужно ли нам еще кожи. Если понадобится, то было бы так здорово, если бы ты $Gсмог:смогла; достать для нас еще!','Это же обещанной кожей у тебя сумки набиты, $C? Не могу дождаться, когда же ты отдашь ее мне! Тогда все-все останутся нами довольны, правда?','Вернитесь к Марте Остроигл в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает плотной кожи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, будет так здорово! $C, приготовления к ан\'киражской войне идут вовсю, и так получилось, что я отвечаю за заготовку плотной кожи. Из нее мы сможем наделать тысячи разных вещей, но сначала надо ее достать – тоже тысячами. В буквальном смысле. И тут на сцену выходишь ты.$B$BТы ведь принесешь мне отличную увесистую кипу плотной кожи? Правда-правда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 плотных кож Марте Остроигл в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, я знала, что ты справишься, $C, конечно же, я это знала! Я отправлю эту кожу по нужному адресу, как только смогу. Ага, а теперь давай-ка посмотрим. Похоже, в итоге все получается очень, очень миленько. Загляни ко мне еще разочек, я сейчас проверю, не нужно ли нам еще кожи. Если понадобится, то было бы так здорово, если бы ты $Gсмог:смогла; достать для нас еще!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это же обещанной кожей у тебя сумки набиты, $C? Не могу дождаться, когда же ты отдашь ее мне! Тогда все-все останутся нами довольны, правда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марте Остроигл в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8516,'Альянсу по-прежнему не хватает плотной кожи!','Да-да, стопки все еще не очень высокие. $n, мы не выполняем норму – не хватает целых $2071w кусков плотной кожи. Только подумай, сколько всего полезного из нее можно сделать! Броню и оружие на любой вкус! Она годится как на отделку паровых танков, так и на оптические винтовки. Держу пари, все закончится тем, что мы соберем столько кожи, что остаток придется отдать Орде на дирижабли.$B$BТы ведь принесешь мне еще плотной кожи?','Принесите 10 плотных кож Марте Остроигл на аэродром Стальгорна.','У тебя снова все получилось! Просто невероятно, как ты умудряешься выбраться отсюда, собрать все, что нужно, а потом еще вернуться и сдать все мне. Когда люди узнают, сколько ты для нас $Gсделал:сделала;, они встанут в очередь за твоими автографами!$B$BБольшое-пребольшое спасибо за столь благородное и щедрое пожертвование плотной кожи, $N.','Да-да, стопки еще не очень высокие. $N, мы не выполняем норму – не хватает целых 80000 плотной кожи. Только подумай, сколько всего полезного из нее можно сделать! Броню и оружие на любой вкус! Она годится как на отделку паровых танков, так и на оптические винтовки. Держу пари, все закончится тем, что мы соберем столько кожи, что остаток придется отдать Орде на дирижабли.$B$BТы ведь принесешь мне еще плотной кожи?','Вернитесь к Марте Остроигл в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает плотной кожи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да-да, стопки все еще не очень высокие. $n, мы не выполняем норму – не хватает целых $2071w кусков плотной кожи. Только подумай, сколько всего полезного из нее можно сделать! Броню и оружие на любой вкус! Она годится как на отделку паровых танков, так и на оптические винтовки. Держу пари, все закончится тем, что мы соберем столько кожи, что остаток придется отдать Орде на дирижабли.$B$BТы ведь принесешь мне еще плотной кожи?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 плотных кож Марте Остроигл на аэродром Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя снова все получилось! Просто невероятно, как ты умудряешься выбраться отсюда, собрать все, что нужно, а потом еще вернуться и сдать все мне. Когда люди узнают, сколько ты для нас $Gсделал:сделала;, они встанут в очередь за твоими автографами!$B$BБольшое-пребольшое спасибо за столь благородное и щедрое пожертвование плотной кожи, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да-да, стопки еще не очень высокие. $N, мы не выполняем норму – не хватает целых 80000 плотной кожи. Только подумай, сколько всего полезного из нее можно сделать! Броню и оружие на любой вкус! Она годится как на отделку паровых танков, так и на оптические винтовки. Держу пари, все закончится тем, что мы соберем столько кожи, что остаток придется отдать Орде на дирижабли.$B$BТы ведь принесешь мне еще плотной кожи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Марте Остроигл в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8517,'Альянсу не хватает льняных бинтов!','Война в Ан\'Кираже будет долгой и кровавой. Прибегнуть к помощи людей, подобных тебе, было для Альянса мудрым решением. Перед тем как сломя голову ринуться в военный конфликт, надо собрать достаточно припасов.$B$BМне поручили запасать льняные бинты, и я надеюсь, что ты мне поможешь. Это не так-то легко, но по крайней мере льняные бинты проще всего изготовить. Что скажешь, |3-6($c)?','Принесите 20 льняных бинтов часовому Серебринке Небес в Палаты Войны Стальгорна.','Многим солдатам ты, считай, $gсослужил:сослужила; добрую службу, |3-6($c). Я лично прослежу, чтобы твои усилия не остались незамеченными. Одну минуту, сейчас я упакую эти бинты, куда надо, и внесу их в реестр, а потом посмотрим, сколько нужно ли мне еще. $B$BДа осенит тебя своим светом Элуна, $r!','Двадцать льняных бинтов у тебя, |3-6($c)?','Вернитесь к часовому Серебринке Небес в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает льняных бинтов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Война в Ан\'Кираже будет долгой и кровавой. Прибегнуть к помощи людей, подобных тебе, было для Альянса мудрым решением. Перед тем как сломя голову ринуться в военный конфликт, надо собрать достаточно припасов.$B$BМне поручили запасать льняные бинты, и я надеюсь, что ты мне поможешь. Это не так-то легко, но по крайней мере льняные бинты проще всего изготовить. Что скажешь, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 льняных бинтов часовому Серебринке Небес в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Многим солдатам ты, считай, $gсослужил:сослужила; добрую службу, |3-6($c). Я лично прослежу, чтобы твои усилия не остались незамеченными. Одну минуту, сейчас я упакую эти бинты, куда надо, и внесу их в реестр, а потом посмотрим, сколько нужно ли мне еще. $B$BДа осенит тебя своим светом Элуна, $r!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Двадцать льняных бинтов у тебя, |3-6($c)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Серебринке Небес в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8518,'Альянсу по-прежнему не хватает льняных бинтов!','Меня всегда изумляет самоотверженность – ведь столь многие обычно гораздо более склонны к эгоизму. $C, я все никак не могу выполнить свою норму по сбору льняных бинтов. Не поможешь ли мне еще раз?','Принесите 20 льняных бинтов часовому Серебринке Небес на аэродром в Дун Морог.','Меня всегда изумляет самоотверженность, ведь многие обычно более склонны к эгоизму. $C, я все никак не могу выполнить свою норму по сбору льняных бинтов. Не поможешь ли мне еще раз?','Вернитесь к часовому Серебринке Небес в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает льняных бинтов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня всегда изумляет самоотверженность – ведь столь многие обычно гораздо более склонны к эгоизму. $C, я все никак не могу выполнить свою норму по сбору льняных бинтов. Не поможешь ли мне еще раз?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 льняных бинтов часовому Серебринке Небес на аэродром в Дун Морог.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Меня всегда изумляет самоотверженность, ведь многие обычно более склонны к эгоизму. $C, я все никак не могу выполнить свою норму по сбору льняных бинтов. Не поможешь ли мне еще раз?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к часовому Серебринке Небес в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (8519,'Пешка на Доске Вечности','Успокоившись и сосредоточив взгляд на кристалле, вы замечаете, что внутри что-то шевелится. Посмотрев поближе, вы осознаете, что перед вами предстало прошлое... давно забытое.','Узнайте о прошлом все, что можно. Потом поговорите с Анахроносом в Пещерах Времени в Танарисе.','После предательства Оленьего Шлема я собрал осколки скипетра Зыбучих песков и вернулся сюда. Я желал охранить скипетр от посягательств тех, кто был готов воспользоваться им во зло – так были созданы драконы.$B$BМне казалось, что если разделить части скипетра между четырьмя могущественными Аспектами, то взыскующие Хаос не смогут восстановить его. Я был глупцом. Проклятые драконы охотятся на меня по сей день.','Война Зыбучих песков','Вернитесь к Анахроносу в Пещеры Времени, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пешка на Доске Вечности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Успокоившись и сосредоточив взгляд на кристалле, вы замечаете, что внутри что-то шевелится. Посмотрев поближе, вы осознаете, что перед вами предстало прошлое... давно забытое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Узнайте о прошлом все, что можно. Потом поговорите с Анахроносом в Пещерах Времени в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','После предательства Оленьего Шлема я собрал осколки скипетра Зыбучих песков и вернулся сюда. Я желал охранить скипетр от посягательств тех, кто был готов воспользоваться им во зло – так были созданы драконы.$B$BМне казалось, что если разделить части скипетра между четырьмя могущественными Аспектами, то взыскующие Хаос не смогут восстановить его. Я был глупцом. Проклятые драконы охотятся на меня по сей день.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Война Зыбучих песков',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахроносу в Пещеры Времени, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8520,'Альянсу не хватает шелковых бинтов!','На горизонте маячит война в Ан\'Кираже, так что мы должны приложить все усилия, чтобы на поле боя солдаты ни в чем не нуждались. Именно этим мы и занимаемся. Я вот, например, отвечаю за заготовку шелковых бинтов.$B$BНе хочешь ли мне помочь малость?','Принесите 20 шелковых бинтов медсестре Стоунфилд в Палаты Войны Стальгорна.','$C$c, ты молодчина! Спасибо за бинты. Благодаря тебе мы еще на шаг приблизились к нашей общей цели. Сейчас пойду уберу бинты, а потом можем еще поболтать.','Приветик, $C, ну что, удалось раздобыть двадцать шелковых бинтов?','Вернитесь к медсестре Стоунфилд в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает шелковых бинтов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На горизонте маячит война в Ан\'Кираже, так что мы должны приложить все усилия, чтобы на поле боя солдаты ни в чем не нуждались. Именно этим мы и занимаемся. Я вот, например, отвечаю за заготовку шелковых бинтов.$B$BНе хочешь ли мне помочь малость?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 шелковых бинтов медсестре Стоунфилд в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$C$c, ты молодчина! Спасибо за бинты. Благодаря тебе мы еще на шаг приблизились к нашей общей цели. Сейчас пойду уберу бинты, а потом можем еще поболтать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветик, $C, ну что, удалось раздобыть двадцать шелковых бинтов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к медсестре Стоунфилд в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8521,'Альянсу по-прежнему не хватает шелковых бинтов!','Очень мило с твой стороны снова предложить мне помощь, |3-6($c). Мы пока собрали всего лишь $2082w шелковых бинтов, так что еще работать и работать.','Принесите 20 шелковых бинтов медсестре Стоунфилд на аэродром в Дун Морог.','Приятно иметь дело с бескорыстными ребятами вроде тебя, $N. Мы не забудем твой вклад в подготовку к войне. Именно от таких, как ты, и зависит, победим мы или проиграем. Я надеюсь, что наших усилий хватит для победы.$B$BЕще раз большое спасибо!','Очень мило с твоей стороны снова предложить мне помощь, $C. Мы уже собрали очень много шелковых бинтов, но это, к сожалению, далеко не конец. $N, можешь принести еще штук двадцать? Я была бы благодарна тебе от имени всего Альянса.','Вернитесь к медсестре Стоунфилд в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает шелковых бинтов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Очень мило с твой стороны снова предложить мне помощь, |3-6($c). Мы пока собрали всего лишь $2082w шелковых бинтов, так что еще работать и работать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 шелковых бинтов медсестре Стоунфилд на аэродром в Дун Морог.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно иметь дело с бескорыстными ребятами вроде тебя, $N. Мы не забудем твой вклад в подготовку к войне. Именно от таких, как ты, и зависит, победим мы или проиграем. Я надеюсь, что наших усилий хватит для победы.$B$BЕще раз большое спасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Очень мило с твоей стороны снова предложить мне помощь, $C. Мы уже собрали очень много шелковых бинтов, но это, к сожалению, далеко не конец. $N, можешь принести еще штук двадцать? Я была бы благодарна тебе от имени всего Альянса.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к медсестре Стоунфилд в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8522,'Альянсу не хватает бинтов из рунической ткани!','Считай ведение войны сколь угодно сомнительным занятием, |3-6($c), но военная машина уже завертелась. Оглянись на свою семью и друзей и спроси, чем ты можешь помочь им, – ведь все мы попадем в горнило битвы, и надо будет как-то выживать.$B$BИменно поэтому я запасаюсь бинтами из рунической ткани, кто бы их ни принес. Не хочешь ли внести посильный вклад в это дело?','Твоя настойчивость в выполнении этого задания выше всяких похвал, $C. Сейчас я уберу бинты на склад и вернусь. Я бы хотел побеседовать с тобой относительно возможности добыть еще бинтов из рунической ткани.','Проходит день за днем, а мы все продолжаем и продолжаем готовиться. $C, тебе удалось достать бинты из рунической ткани?','Вернитесь к хранителю Лунному Сумраку в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает бинтов из рунической ткани!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Считай ведение войны сколь угодно сомнительным занятием, |3-6($c), но военная машина уже завертелась. Оглянись на свою семью и друзей и спроси, чем ты можешь помочь им, – ведь все мы попадем в горнило битвы, и надо будет как-то выживать.$B$BИменно поэтому я запасаюсь бинтами из рунической ткани, кто бы их ни принес. Не хочешь ли внести посильный вклад в это дело?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя настойчивость в выполнении этого задания выше всяких похвал, $C. Сейчас я уберу бинты на склад и вернусь. Я бы хотел побеседовать с тобой относительно возможности добыть еще бинтов из рунической ткани.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Проходит день за днем, а мы все продолжаем и продолжаем готовиться. $C, тебе удалось достать бинты из рунической ткани?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Лунному Сумраку в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8523,'Альянсу по-прежнему не хватает бинтов из рунической ткани!','Итак, мы снова вынуждены говорить о делах, не терпящих отлагательств, |3-6($c). Хочу еще раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно. Но работы еще непочатый край.$B$B$n, можешь принести мне еще бинтов из рунической ткани?','Принесите 20 бинтов из рунической ткани Хранителю Лунному Сумраку на аэродром в Дун Морог.','Я рад что этот путь мы проделали вместе, $N. Работать с тобой – одно удовольствие. Хочу еще раз поблагодарить за бескорыстную помощь Альянсу тебя и всех, подобных тебе. Возращайся скорей, побеседуем еще.','Итак, мы снова вынуждены говорить о делах, не терпящих отлагательств, $C. Хочу еще раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно. Но работы еще непочатый край.$B$B$N, можешь принести мне еще бинтов из рунной ткани?','Вернитесь к хранителю Лунному Сумраку в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает бинтов из рунической ткани!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, мы снова вынуждены говорить о делах, не терпящих отлагательств, |3-6($c). Хочу еще раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно. Но работы еще непочатый край.$B$B$n, можешь принести мне еще бинтов из рунической ткани?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 бинтов из рунической ткани Хранителю Лунному Сумраку на аэродром в Дун Морог.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад что этот путь мы проделали вместе, $N. Работать с тобой – одно удовольствие. Хочу еще раз поблагодарить за бескорыстную помощь Альянсу тебя и всех, подобных тебе. Возращайся скорей, побеседуем еще.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Итак, мы снова вынуждены говорить о делах, не терпящих отлагательств, $C. Хочу еще раз поблагодарить тебя за вложенные усилия, мало кто трудится столь самоотверженно. Но работы еще непочатый край.$B$B$N, можешь принести мне еще бинтов из рунной ткани?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Лунному Сумраку в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8524,'Альянсу не хватает радужного тунца!','Эй, дружище! Если бы я спросил тебя: "Нужно ли солдатам на войне хорошо кушать?" – ты бы, без сомнения, $gответил:ответила;: "Да, конечно!". И я абсолютно с тобой согласен! Рад, что мы сошлись во мнениях. Теперь, я думаю, ты не будешь спорить, что тебе осталось только отправиться на рыбалку, наловить радужного тунца, приготовить всю порцию и принести мне. М-м-м, я уже в предвкушении.','Принесите 20 тушек радужного тунца Гладню Гастрогному в Палаты Войны Стальгорна.','Два для Альянса, один мне, два для Альянса, один мне... Эгей, отличная работа, $gрыбак:рыбачка;! Похоже, ты отличное приобретение для нашего клуба. А мне кажется, надо б раздобыть еще тунца. Почему бы тебе не прогуляться и не принести еще рыбки? У меня уже в животе урчит...','Готов поспорить, что ты вернешься с нужным количеством радужного тунца, |3-6($c)!','Вернитесь к Гладеню Гастрогному в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает радужного тунца!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, дружище! Если бы я спросил тебя: "Нужно ли солдатам на войне хорошо кушать?" – ты бы, без сомнения, $gответил:ответила;: "Да, конечно!". И я абсолютно с тобой согласен! Рад, что мы сошлись во мнениях. Теперь, я думаю, ты не будешь спорить, что тебе осталось только отправиться на рыбалку, наловить радужного тунца, приготовить всю порцию и принести мне. М-м-м, я уже в предвкушении.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 тушек радужного тунца Гладню Гастрогному в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Два для Альянса, один мне, два для Альянса, один мне... Эгей, отличная работа, $gрыбак:рыбачка;! Похоже, ты отличное приобретение для нашего клуба. А мне кажется, надо б раздобыть еще тунца. Почему бы тебе не прогуляться и не принести еще рыбки? У меня уже в животе урчит...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Готов поспорить, что ты вернешься с нужным количеством радужного тунца, |3-6($c)!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гладеню Гастрогному в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8525,'Альянсу по-прежнему не хватает радужного тунца!','Что? Снова ты? Ну и дела, не будь я гном! Гладень Гастрогном, чтобы быть точным. Выходит, ты $gпришел:пришла;, чтобы снова помочь мне? Не могу сказать, чтобы я был этим недоволен. А может, тебе просто понравилось, как пахнет жареный тунец? *облизывается*$B$BЛадно, хватит болтать. Ступай-ка и принеси мне побольше радужного тунца!','Принесите 20 тушек радужного тунца Гладню Гастрогному на аэродром в Дун Морог.','Я сразу понял, что в тебе что-то такое есть, $gмалыш:детка;. Ты выглядишь, как человек, который знает, чего хочет. Да-да, с Глади Гастрогномом есть верное правило, – сделай мне приятно, и ты об этом не пожалеешь. $B$BХа-ха-ха! Ладно, сейчас пойду сложу рыбку и вернусь. Если хочешь, можешь пока приготовить еще двадцать штук.','Что? Снова ты? Ну и дела, не будь я гном! Гладень Гастрогном, чтобы быть точным. Выходит, ты $gпришел:пришла;, чтобы снова помочь мне? Не могу сказать, чтобы я был этим недоволен. А может, тебе просто понравилось, как пахнет жареный тунец?  облизывается $B$BЛадно, хватит болтать. Ступай-ка и принеси мне побольше радужного тунца!','Вернитесь к Гладеню Гастрогному в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает радужного тунца!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что? Снова ты? Ну и дела, не будь я гном! Гладень Гастрогном, чтобы быть точным. Выходит, ты $gпришел:пришла;, чтобы снова помочь мне? Не могу сказать, чтобы я был этим недоволен. А может, тебе просто понравилось, как пахнет жареный тунец? *облизывается*$B$BЛадно, хватит болтать. Ступай-ка и принеси мне побольше радужного тунца!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 тушек радужного тунца Гладню Гастрогному на аэродром в Дун Морог.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я сразу понял, что в тебе что-то такое есть, $gмалыш:детка;. Ты выглядишь, как человек, который знает, чего хочет. Да-да, с Глади Гастрогномом есть верное правило, – сделай мне приятно, и ты об этом не пожалеешь. $B$BХа-ха-ха! Ладно, сейчас пойду сложу рыбку и вернусь. Если хочешь, можешь пока приготовить еще двадцать штук.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что? Снова ты? Ну и дела, не будь я гном! Гладень Гастрогном, чтобы быть точным. Выходит, ты $gпришел:пришла;, чтобы снова помочь мне? Не могу сказать, чтобы я был этим недоволен. А может, тебе просто понравилось, как пахнет жареный тунец?  облизывается $B$BЛадно, хватит болтать. Ступай-ка и принеси мне побольше радужного тунца!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гладеню Гастрогному в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8526,'Альянсу не хватает жареного мяса ящера!','Как делишки, |3-6($c)? Я вижу, ты просто рвешься принять участие в заготовке провизии для ан\'киражской войны. Мой папочка решил, что ответственность за сбор чего-то там чему-то там меня научит. Как бы не так. Я мясо на дух не выношу.$B$BЛадно, если вдруг захочешь помочь, принеси побольше жареных ящеров. Несомненно, именно об этом мясе и будут мечтать все наши отважные солдаты.','Принесите 20 жареных ящеров Саре Грустносвист в Палаты Войны Стальгорна.','Вот это да. Спасибо, что притащил сюда всю эту жженую плоть, $C. Минуточку, сейчас я его покидаю в кучу, – надеюсь, кто-нибудь о нем да позаботится. Если время найдется, может быть, еще принесешь?','Ну что, где там наши жареные ящеры?','Вернитесь к Саре Грустносвист в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает жареного мяса ящера!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как делишки, |3-6($c)? Я вижу, ты просто рвешься принять участие в заготовке провизии для ан\'киражской войны. Мой папочка решил, что ответственность за сбор чего-то там чему-то там меня научит. Как бы не так. Я мясо на дух не выношу.$B$BЛадно, если вдруг захочешь помочь, принеси побольше жареных ящеров. Несомненно, именно об этом мясе и будут мечтать все наши отважные солдаты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 жареных ящеров Саре Грустносвист в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот это да. Спасибо, что притащил сюда всю эту жженую плоть, $C. Минуточку, сейчас я его покидаю в кучу, – надеюсь, кто-нибудь о нем да позаботится. Если время найдется, может быть, еще принесешь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где там наши жареные ящеры?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Саре Грустносвист в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8527,'Альянсу по-прежнему не хватает жареного мяса ящера!','О, снова здорово, |3-6($c). Я вижу, ты в восторге от всей этой беготни. Наверное, ты хочешь принести мне еще двадцать жареных ящеров? Отлично. Тогда пойди и принеси. Увидимся.','Принесите 20 жареных ящеров Саре Грустносвист на аэродром в Дун Морог.','Вернитесь к Саре Грустносвист в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает жареного мяса ящера!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, снова здорово, |3-6($c). Я вижу, ты в восторге от всей этой беготни. Наверное, ты хочешь принести мне еще двадцать жареных ящеров? Отлично. Тогда пойди и принеси. Увидимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 жареных ящеров Саре Грустносвист на аэродром в Дун Морог.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Саре Грустносвист в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8528,'Альянсу не хватает пятнистого желтохвоста!','Возможно, заготовка вареной рыбы выглядит не особенно героически, но не стоит преуменьшать значение нашей работы, |3-6($c).Солдаты – такие же люди, как и все, и они хотят есть. Именно поэтому мы должны обеспечить их провиантом, пока не началась война в Ан\'Кираже.$B$BЯ получила приказ заготавливать пятнистый желтохвост. Это отличный пищевой ресурс, он хорошо хранится, идет на изготовление различных блюд и совсем не пахнет, в отличие от другой морской рыбы. Ну что, поможешь мне в его заготовке?','Принесите 20 пятнистых желтохвостов охотнице Быстрой Реке в Палаты Войны Стальгорна.','Спасибо за быструю и своевременную помощь, $C. Теперь наши солдаты не будут испытывать недостатка в провианте. Подожди немного, я позабочусь о размещении рыбы на складе, и мы обсудим доставку еще одной порции, если ты не против.','Я уверена, что ты $Gвернулся:вернулась; так быстро, потому что $Gпринес:принесла; необходимое количество желтохвоста.','Вернитесь к охотнице Быстрой Реке в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает пятнистого желтохвоста!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, заготовка вареной рыбы выглядит не особенно героически, но не стоит преуменьшать значение нашей работы, |3-6($c).Солдаты – такие же люди, как и все, и они хотят есть. Именно поэтому мы должны обеспечить их провиантом, пока не началась война в Ан\'Кираже.$B$BЯ получила приказ заготавливать пятнистый желтохвост. Это отличный пищевой ресурс, он хорошо хранится, идет на изготовление различных блюд и совсем не пахнет, в отличие от другой морской рыбы. Ну что, поможешь мне в его заготовке?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 пятнистых желтохвостов охотнице Быстрой Реке в Палаты Войны Стальгорна.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за быструю и своевременную помощь, $C. Теперь наши солдаты не будут испытывать недостатка в провианте. Подожди немного, я позабочусь о размещении рыбы на складе, и мы обсудим доставку еще одной порции, если ты не против.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я уверена, что ты $Gвернулся:вернулась; так быстро, потому что $Gпринес:принесла; необходимое количество желтохвоста.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнице Быстрой Реке в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8529,'Альянсу по-прежнему не хватает пятнистого желтохвоста!','Если у тебя еще не пропало желание помогать нам, то нам все еще нужен желтохвост, $n. Я думаю, в прошлый раз ты $gприобрел:приобрела; достаточно опыта, так что сейчас дело пойдет веселее. Ну что, по рукам?','Принесите 20 пятнистых желтохвостов охотнице Быстрой Реке на аэродром в Дун Морог.','Сразу видно, что ты заботишься о нуждах Альянса, как о своих собственных, $N. Твои старания не останутся незамеченными, и награда обязательно найдет своего героя. Спасибо за отлично приготовленную рыбу. Теперь ее можно хранить долго и без особых проблем. Пойду-ка я запишу, сколько ты $Gпринес:принесла;. Когда близится война, на счету должна быть каждая рыбина!','Если у тебя еще не пропало желание помогать нам, то нам опять нужен желтохвост, $N. Я думаю, в прошлый раз ты $Gприобрел:приобрела достаточно опыта, так что сейчас дело пойдет веселее. Ну что, по рукам?','Вернитесь к охотнице Быстрой Реке в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает пятнистого желтохвоста!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если у тебя еще не пропало желание помогать нам, то нам все еще нужен желтохвост, $n. Я думаю, в прошлый раз ты $gприобрел:приобрела; достаточно опыта, так что сейчас дело пойдет веселее. Ну что, по рукам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 пятнистых желтохвостов охотнице Быстрой Реке на аэродром в Дун Морог.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сразу видно, что ты заботишься о нуждах Альянса, как о своих собственных, $N. Твои старания не останутся незамеченными, и награда обязательно найдет своего героя. Спасибо за отлично приготовленную рыбу. Теперь ее можно хранить долго и без особых проблем. Пойду-ка я запишу, сколько ты $Gпринес:принесла;. Когда близится война, на счету должна быть каждая рыбина!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя еще не пропало желание помогать нам, то нам опять нужен желтохвост, $N. Я думаю, в прошлый раз ты $Gприобрел:приобрела достаточно опыта, так что сейчас дело пойдет веселее. Ну что, по рукам?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнице Быстрой Реке в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8530,'Альянсу не хватает опаленных вулканических камней!','$C, мне нужна твоя помощь. Есть камни, которые можно достать в Огненных Недрах, – я имею в виду опаленные вулканические камни. Они нужны нам для подготовки к войне в Ан\'Кираже. Наши кузнецы и инженеры знают, как их использовать, так что мы получили на них заказ. Проберись в Огненные Недра и собери столько, сколько сможешь. Не сомневаюсь, что тебе удастся уговорить пойти с тобой штук тридцать девять близких приятелей.','Принесите 50 оплавленных вулканических камней командиру Мощному Молоту на аэродром в Дун Мороге.','Вернитесь к командиру Мощному Молоту к реке Строптивой, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу не хватает опаленных вулканических камней!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, мне нужна твоя помощь. Есть камни, которые можно достать в Огненных Недрах, – я имею в виду опаленные вулканические камни. Они нужны нам для подготовки к войне в Ан\'Кираже. Наши кузнецы и инженеры знают, как их использовать, так что мы получили на них заказ. Проберись в Огненные Недра и собери столько, сколько сможешь. Не сомневаюсь, что тебе удастся уговорить пойти с тобой штук тридцать девять близких приятелей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 50 оплавленных вулканических камней командиру Мощному Молоту на аэродром в Дун Мороге.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мощному Молоту к реке Строптивой, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8531,'Альянсу по-прежнему не хватает опаленных вулканических камней!','Спасибо, что $gпришел:пришла; снова, $n. Если твои друзья все еще с тобой, вернитесь в Огненные Недра и наберите еще оплавленных вулканических камней. Ну как, по рукам?','Принесите 50 оплавленных вулканических камней командиру Мощному Молоту на аэродром в Дун Морог.','Вернитесь к командиру Мощному Молоту в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альянсу по-прежнему не хватает опаленных вулканических камней!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо, что $gпришел:пришла; снова, $n. Если твои друзья все еще с тобой, вернитесь в Огненные Недра и наберите еще оплавленных вулканических камней. Ну как, по рукам?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 50 оплавленных вулканических камней командиру Мощному Молоту на аэродром в Дун Морог.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мощному Молоту в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8532,'Орде не хватает медных слитков!','Я так рад, что ты $gрешил:решила; помочь нам. Не всякий бы согласился, так что я лучше еще раз уточню, правильно ли ты меня $gпонял:поняла;. Мне нужны медные слитки, а не просто медь. У нас недостаточно ни времени, ни людей, чтобы самим ее выплавлять, так что твои усилия не останутся незамеченными. Ну как, |3-6($c), справишься?','Принесите 20 медных слитков шахтеру Кромвелю на Аллею Духов Оргриммара.','Вот они, слитки, хорошо, что ты не $Gстал:стала; полировать их. В блеске нет никакого смысла, они все равно пойдут на военные нужды. Пойду уложу их в штабели, и нужно позаботиться, чтобы они были пущены в дело. Если добудешь еще двадцать, обращайся прямо ко мне.','Я надеюсь, 20 медных слитков у тебя с собой, $C?','Вернитесь к шахтеру Кромвелю в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает медных слитков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я так рад, что ты $gрешил:решила; помочь нам. Не всякий бы согласился, так что я лучше еще раз уточню, правильно ли ты меня $gпонял:поняла;. Мне нужны медные слитки, а не просто медь. У нас недостаточно ни времени, ни людей, чтобы самим ее выплавлять, так что твои усилия не останутся незамеченными. Ну как, |3-6($c), справишься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 медных слитков шахтеру Кромвелю на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот они, слитки, хорошо, что ты не $Gстал:стала; полировать их. В блеске нет никакого смысла, они все равно пойдут на военные нужды. Пойду уложу их в штабели, и нужно позаботиться, чтобы они были пущены в дело. Если добудешь еще двадцать, обращайся прямо ко мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я надеюсь, 20 медных слитков у тебя с собой, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шахтеру Кромвелю в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8533,'Орде по-прежнему не хватает медных слитков!','Уже $gвернулся:вернулась;? Из тебя быстро бы получился отличный рудокоп, |3-6($c). Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь ее в слитки и возвращайся ко мне. Я знаю, что ты кое-что можешь, вопрос – хочешь ли?','Принесите 20 медных слитков шахтеру Кромвелю в Дуротар.','Ты опять $Gдоказал:доказала;, что ты многого стоишь, $C. Я чувствую, эта медь хорошо нам послужит, когда придет время. А теперь мне надо сложить ее в штабеля и подсчитать. Если у тебя не пропало желание, ты, вероятно, сможешь помочь нам, если принесешь еще медных слитков.','Уже $Gвернулся:вернулась;? Из тебя быстро получился бы отличный рудокоп, $C. Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь ее в слитки и возвращайся ко мне. Я знаю, что кое-что ты можешь, но вот вопрос – хочешь ли.','Вернитесь к шахтеру Кромвелю в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде по-прежнему не хватает медных слитков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Уже $gвернулся:вернулась;? Из тебя быстро бы получился отличный рудокоп, |3-6($c). Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь ее в слитки и возвращайся ко мне. Я знаю, что ты кое-что можешь, вопрос – хочешь ли?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 медных слитков шахтеру Кромвелю в Дуротар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты опять $Gдоказал:доказала;, что ты многого стоишь, $C. Я чувствую, эта медь хорошо нам послужит, когда придет время. А теперь мне надо сложить ее в штабеля и подсчитать. Если у тебя не пропало желание, ты, вероятно, сможешь помочь нам, если принесешь еще медных слитков.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уже $Gвернулся:вернулась;? Из тебя быстро получился бы отличный рудокоп, $C. Ну, ты уже знаешь, как управляться с киркой, так что ступай, добудь побольше медной руды, переплавь ее в слитки и возвращайся ко мне. Я знаю, что кое-что ты можешь, но вот вопрос – хочешь ли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шахтеру Кромвелю в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8534,'Донесение разведчика из улья Зора','Мы отправили наших лучших разведчиков к ульям силитидов. Азенель уже несколько дней наблюдает за передвижениями этих насекомых. Найди ее и забери у нее письменный отчет. Нам необходимо как можно скорее получить от нее сведения.','Свяжитесь с кенарийской разведчицей Азенель в Улье Зора и отнесите ее донесение призывательнице ветров Гордый Рог в Крепость Кенария. Кроме того, принесите тактическую задачу VI.','Мы очень ценим твои усилия, $N. Я немедленно займусь этим донесением, а ты можешь переходить к следующему заданию.','Ты найдешь разведчика Азенель внутри Улья Зора. Торопись, $N! Время имеет существенное значение.','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение разведчика из улья Зора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы отправили наших лучших разведчиков к ульям силитидов. Азенель уже несколько дней наблюдает за передвижениями этих насекомых. Найди ее и забери у нее письменный отчет. Нам необходимо как можно скорее получить от нее сведения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Свяжитесь с кенарийской разведчицей Азенель в Улье Зора и отнесите ее донесение призывательнице ветров Гордый Рог в Крепость Кенария. Кроме того, принесите тактическую задачу VI.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы очень ценим твои усилия, $N. Я немедленно займусь этим донесением, а ты можешь переходить к следующему заданию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты найдешь разведчика Азенель внутри Улья Зора. Торопись, $N! Время имеет существенное значение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8535,'Седой храмовник','Сумеречный Молот и повелители стихий, которым поклоняются служители культа, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан\'Кираже, мы не должны терять бдительность и давать волю внешним врагам.$b$bОтыщи способ вызвать и уничтожить седого храмовника и доложи о выполнении задания Бору Буйногривому.','Призовите и убейте седого храмовника и доложите о выполнении задания Бору Буйногривому из Крепости Кенария. Для завершения задания принесите тактическую задачу IV.','Отличная работа, $N. Вот следующее задание.','Твоя задача уже выполнена, $N?','Вернитесь к Бору Буйногривому в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Седой храмовник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сумеречный Молот и повелители стихий, которым поклоняются служители культа, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан\'Кираже, мы не должны терять бдительность и давать волю внешним врагам.$b$bОтыщи способ вызвать и уничтожить седого храмовника и доложи о выполнении задания Бору Буйногривому.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите и убейте седого храмовника и доложите о выполнении задания Бору Буйногривому из Крепости Кенария. Для завершения задания принесите тактическую задачу IV.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Вот следующее задание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твоя задача уже выполнена, $N?',`requestitemstext_loc8`), `completed