INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8538,'Четыре герцога','Связь между Сумеречным Молотом и Советом Бездны оказалась куда важнее, чем нам казалось вначале.$b$bМы не сомневаемся, что повелители Стихий, именуемые герцогами Бездны, управляют служителями культа Сумеречного Молота. Найди способ выманить в наш мир четырех герцогов Бездны и убей их!$b$bМы избрали тебя за прежние заслуги и не сомневаемся, что ты справишься.','Отыщите способ вызвать и убить герцога Огарцога, герцога Глубин, герцога Ветров и герцога Осколков и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария. Для завершения задания принесите тактическую задачу V.','Сегодня ты добился большого успеха, $N. Ты $Gпобедил:победила; некоторых из наших самых могущественных врагов. За это я тебе очень благодарен.','Твоя задача уже выполнена, $N?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Четыре герцога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Связь между Сумеречным Молотом и Советом Бездны оказалась куда важнее, чем нам казалось вначале.$b$bМы не сомневаемся, что повелители Стихий, именуемые герцогами Бездны, управляют служителями культа Сумеречного Молота. Найди способ выманить в наш мир четырех герцогов Бездны и убей их!$b$bМы избрали тебя за прежние заслуги и не сомневаемся, что ты справишься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите способ вызвать и убить герцога Огарцога, герцога Глубин, герцога Ветров и герцога Осколков и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария. Для завершения задания принесите тактическую задачу V.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодня ты добился большого успеха, $N. Ты $Gпобедил:победила; некоторых из наших самых могущественных врагов. За это я тебе очень благодарен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твоя задача уже выполнена, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8539,'Цель: сестры-убийцы из Улья Зора','Мы вызвали подкрепление для сражения у Улья Зора. Твоя задача – убить как можно больше сестер-убийц. Выполнив задание, отчитайся командиру Мар\'алиту.','Убейте 30 сестер-убийц из Улья Зора и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу V.','Отличная работа, $N. Ты очень ценный союзник.','Ты хочешь что-то сказать, $C?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: сестры-убийцы из Улья Зора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы вызвали подкрепление для сражения у Улья Зора. Твоя задача – убить как можно больше сестер-убийц. Выполнив задание, отчитайся командиру Мар\'алиту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 сестер-убийц из Улья Зора и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу V.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Ты очень ценный союзник.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь что-то сказать, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8540,'Сапоги для стражей','Верховому подразделению Крепости Кенария не хватает изысканных мифриловых сапог. Принеси нам очередную партию и передай их капитану Вишу Коцусу из Крепости Кенария.','Принесите 3 пары изысканных мифриловых сапог Вишу Коцусу, капитану стражи в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу II.','Отлично! Как раз то, что нужно. Спасибо.','У тебя есть что-то для меня, $N?','Вернитесь к Вишу Коцусу в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сапоги для стражей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховому подразделению Крепости Кенария не хватает изысканных мифриловых сапог. Принеси нам очередную партию и передай их капитану Вишу Коцусу из Крепости Кенария.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 пары изысканных мифриловых сапог Вишу Коцусу, капитану стражи в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу II.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Как раз то, что нужно. Спасибо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вишу Коцусу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8541,'Шлифовальные камни','У стражи Крепости Кенария на исходе шлифовальные камни. Добудь их и отнеси капитану Вишу Коцусу в Крепость Кенария.','Принесите 10 увесистых точильных каменей, 10 твердых шлифовальных камней и 10 тяжелых шлифовальных каменей Вишу Коцусу, капитану стражи в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу III.','Отлично! Как раз то, что нужно. Спасибо.','У тебя есть что-то для меня, $N?','Вернитесь к Вишу Коцусу в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шлифовальные камни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У стражи Крепости Кенария на исходе шлифовальные камни. Добудь их и отнеси капитану Вишу Коцусу в Крепость Кенария.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 увесистых точильных каменей, 10 твердых шлифовальных камней и 10 тяжелых шлифовальных каменей Вишу Коцусу, капитану стражи в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу III.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Как раз то, что нужно. Спасибо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вишу Коцусу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8542,'Орде не хватает оловянных слитков!','Лок\'тар, |3-6($r), я уверен, ты в курсе, что мы собираемся воевать с тараканами Ан\'Киража. Вождь сказал, что сначала надо как следует подготовиться. Я б охотней точил мечи или подгонял броню, но мне доверили сбор оловянных слитков. Для меня это большая честь, да! Но без помощи мне не справиться.$B$BНадо, чтобы кто-то добывал эти самые слитки и приносил сюда. Нам нужно так много, что, боюсь, я и считать-то до стольких не умею.','Принесите 20 оловянных слитков рубаке Маугу на Аллею Духов Оргриммара.','Хм... Выглядит так, будто слитков столько, сколько нужно... Только не пытайся обмануть меня, $C! От этого счета у меня башка раскалывается. Пойду сложу слитки в штабель, а ты пока отправляйся и принеси еще столько же.','Ударные земснаряды представляют собой серьезную угрозу, и с ними нужно быстро бороться!','Вернитесь к рубаке Маугу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает оловянных слитков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лок\'тар, |3-6($r), я уверен, ты в курсе, что мы собираемся воевать с тараканами Ан\'Киража. Вождь сказал, что сначала надо как следует подготовиться. Я б охотней точил мечи или подгонял броню, но мне доверили сбор оловянных слитков. Для меня это большая честь, да! Но без помощи мне не справиться.$B$BНадо, чтобы кто-то добывал эти самые слитки и приносил сюда. Нам нужно так много, что, боюсь, я и считать-то до стольких не умею.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 оловянных слитков рубаке Маугу на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... Выглядит так, будто слитков столько, сколько нужно... Только не пытайся обмануть меня, $C! От этого счета у меня башка раскалывается. Пойду сложу слитки в штабель, а ты пока отправляйся и принеси еще столько же.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ударные земснаряды представляют собой серьезную угрозу, и с ними нужно быстро бороться!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рубаке Маугу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8543,'Орде все еще нужны оловянные слитки!','Отлично, я понял, к войне ты относишься серьезно. Видишь ли, в ее предвкушении я так нервничаю, что потихоньку начинаю выходить из себя. А твоя медлительность меня просто бесит!!! Не можешь притаскивать товар быстрее, что ли? Может, мне малость с тобой поразмяться, чтобы снять стресс...$B$BХар!!! Нет, не буду, пожалуй, а то кто тогда будет носить мне слитки?','Принесите 20 оловянных слитков рубаке Маугу в Дуротар.','Тром\'ка, $N! Своими делами ты оказываешь и мне, и Орде большую честь. Сейчас я позабочусь об этих слитках. А когда мы сделаем все, что нужно, то отправимся на войну и покажем этому ничтожному Альянсу, как надо давить тараканов!$B$BТак что ступай и принеси еще слитков!','Отлично, я понял, к войне ты относишься серьезно. Видишь ли, в ее предвкушении я немного нервничаю, думаю, ты меня понимаешь, как солдат солдата, $C. Это будет победоносная война, когда начнется. Воины Орды преодолеют пески и с оружием в руках кинутся на киражских тараканов. В этот день все мы обретем великую славу!$B$BХар! Но сначала нужно собрать достаточное количество этих несчастных оловянных слитков. Забавно, что мы не можем начать грандиозную войну без этих маленьких штуковин, правда?','Вернитесь к рубаке Маугу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще нужны оловянные слитки!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично, я понял, к войне ты относишься серьезно. Видишь ли, в ее предвкушении я так нервничаю, что потихоньку начинаю выходить из себя. А твоя медлительность меня просто бесит!!! Не можешь притаскивать товар быстрее, что ли? Может, мне малость с тобой поразмяться, чтобы снять стресс...$B$BХар!!! Нет, не буду, пожалуй, а то кто тогда будет носить мне слитки?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 оловянных слитков рубаке Маугу в Дуротар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тром\'ка, $N! Своими делами ты оказываешь и мне, и Орде большую честь. Сейчас я позабочусь об этих слитках. А когда мы сделаем все, что нужно, то отправимся на войну и покажем этому ничтожному Альянсу, как надо давить тараканов!$B$BТак что ступай и принеси еще слитков!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Отлично, я понял, к войне ты относишься серьезно. Видишь ли, в ее предвкушении я немного нервничаю, думаю, ты меня понимаешь, как солдат солдата, $C. Это будет победоносная война, когда начнется. Воины Орды преодолеют пески и с оружием в руках кинутся на киражских тараканов. В этот день все мы обретем великую славу!$B$BХар! Но сначала нужно собрать достаточное количество этих несчастных оловянных слитков. Забавно, что мы не можем начать грандиозную войну без этих маленьких штуковин, правда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рубаке Маугу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8544,'Наплеч Завоевателя','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!','Тебе удалось собрать все, что мне нужно?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наплеч Завоевателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать все, что мне нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8545,'Орде не хватает мифриловых слитков!','Война надвигается неотвратимо, и все, что нам остается, |3-6($c), – это как следует подготовиться к ней. В такие времена мы должны сплотиться и помогать друг другу. Как видишь, меня поставили ответственным за сбор мифриловых слитков, которые потом пойдут на нужды армии. Я стараюсь как могу, но этого пока недостаточно.$B$BСумеешь добыть мифрил на рудниках и переплавить его в слитки? Это бы нам очень пригодилось.','Принесите 20 мифриловых слитков старшему сержанту Ткелаху. Ткелах находится на Аллее Духов Оргриммара.','Ну вот, очень неплохой зачин в нашей работе, $C. Теперь на складе лежит еще 20 новеньких слиточков, сейчас я внесу их в список. Когда на пороге война, на счету каждая крупинка мифрила!$B$BТы заглядывай, похоже, нам скоро еще понадобятся слитки.','Хорошо бы поскорее собрать все слитки и закончить подготовку к войне в Ан\'Кираже. Ты уже $Gдостал:достала; все, что мне нужно, $Gдружище:подруга;?','Вернитесь к главному сержанту Т\'келах в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает мифриловых слитков!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Война надвигается неотвратимо, и все, что нам остается, |3-6($c), – это как следует подготовиться к ней. В такие времена мы должны сплотиться и помогать друг другу. Как видишь, меня поставили ответственным за сбор мифриловых слитков, которые потом пойдут на нужды армии. Я стараюсь как могу, но этого пока недостаточно.$B$BСумеешь добыть мифрил на рудниках и переплавить его в слитки? Это бы нам очень пригодилось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 мифриловых слитков старшему сержанту Ткелаху. Ткелах находится на Аллее Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну вот, очень неплохой зачин в нашей работе, $C. Теперь на складе лежит еще 20 новеньких слиточков, сейчас я внесу их в список. Когда на пороге война, на счету каждая крупинка мифрила!$B$BТы заглядывай, похоже, нам скоро еще понадобятся слитки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хорошо бы поскорее собрать все слитки и закончить подготовку к войне в Ан\'Кираже. Ты уже $Gдостал:достала; все, что мне нужно, $Gдружище:подруга;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному сержанту Т\'келах в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8546,'Орде все еще не хватает мифриловых слитков!','Отлично сработано, $N! Мы ближе к цели на целых двадцать слитков. Сейчас я прослежу, чтобы их отгрузили. Если раздобудешь еще двадцать, дружище, сразу же тащи их мне.','Ага, приятно снова тебя видеть, дружище. Я помню, ты уже помог мне разок, а теперь снова нужна твоя помощь. Мы продолжаем собирать для войны мифриловые слитки. Из них получится отличное оружие, которым мы легко передавим всех этих киражских тараканов.$B$BТак что, если ты и правда нам друг, принеси еще мифриловых слитков. Пока мы не выполнили нашу квоту, я очень на тебя рассчитываю.','Вернитесь к главному сержанту Т\'келах в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает мифриловых слитков!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично сработано, $N! Мы ближе к цели на целых двадцать слитков. Сейчас я прослежу, чтобы их отгрузили. Если раздобудешь еще двадцать, дружище, сразу же тащи их мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ага, приятно снова тебя видеть, дружище. Я помню, ты уже помог мне разок, а теперь снова нужна твоя помощь. Мы продолжаем собирать для войны мифриловые слитки. Из них получится отличное оружие, которым мы легко передавим всех этих киражских тараканов.$B$BТак что, если ты и правда нам друг, принеси еще мифриловых слитков. Пока мы не выполнили нашу квоту, я очень на тебя рассчитываю.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному сержанту Т\'келах в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8547,'Добро пожаловать!','Добро пожаловать в мир World of Warcraft!$B$BВ знак особой благодарности за приобретение коллекционного издания вы получаете подарок! Передайте этот подарочный сертификат Марсилле Утренней Звезде на площади Соколиных Крыльев. Взамен вы получите маленького спутника, который будет сопровождать вас на пути к славе.$B$BЕще раз благодарим вас и желаем приятного времяпровождения в мире World of Warcraft!','Принесите подарочный сертификат площади Соколиных Крыльев Марсилле Утренней Звезде.','Ты действительно уникальный герой, $N. Мы приветствуем тебя в мире Азерота и предлагаем тебе один из этих уникальных подарков!','Привет! Приятно познакомиться!$B$BЯ вижу, что у вас есть специальный ваучер. Отдай его мне, и я предложу тебе что-нибудь взамен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в мир World of Warcraft!$B$BВ знак особой благодарности за приобретение коллекционного издания вы получаете подарок! Передайте этот подарочный сертификат Марсилле Утренней Звезде на площади Соколиных Крыльев. Взамен вы получите маленького спутника, который будет сопровождать вас на пути к славе.$B$BЕще раз благодарим вас и желаем приятного времяпровождения в мире World of Warcraft!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите подарочный сертификат площади Соколиных Крыльев Марсилле Утренней Звезде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты действительно уникальный герой, $N. Мы приветствуем тебя в мире Азерота и предлагаем тебе один из этих уникальных подарков!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет! Приятно познакомиться!$B$BЯ вижу, что у вас есть специальный ваучер. Отдай его мне, и я предложу тебе что-нибудь взамен.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8548,'Броня добровольца','Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в Крепости Кенария, нужны не для красоты, $n.$b$bНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.','Принесите 5 боевых, 3 тыловых и 7 тактических знаков Кенария Варгусу из Крепости Кенария в Силитусе. Кроме того, для выполнения этого задания вам необходимо заслужить дружелюбное отношение Круга Кенария.','Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в Крепости Кенария, нужны не для красоты, $N.$B$BНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.','В наших интересах держать наших самых верных союзников в хорошей форме, $N.','Вернитесь к Варгусу в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Броня добровольца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в Крепости Кенария, нужны не для красоты, $n.$b$bНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 боевых, 3 тыловых и 7 тактических знаков Кенария Варгусу из Крепости Кенария в Силитусе. Кроме того, для выполнения этого задания вам необходимо заслужить дружелюбное отношение Круга Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в Крепости Кенария, нужны не для красоты, $N.$B$BНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В наших интересах держать наших самых верных союзников в хорошей форме, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варгусу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8549,'Орде не хватает мироцвета!','Говорят, каждое поколение должно пройти испытание огнем. Боюсь, что ан\'киражская война станет для нас тем самым горном для закалки. Ничего, подготовимся как следует и покажем всем, из какого мы слеплены теста.$B$BНам нужен мироцвет, который пойдет на создание лекарственных снадобий, и я вызвалась быть ответственной за его сбор. Надеюсь, ты $gпришел:пришла; предложить мне свою помощь. Собери побольше мироцвета и принеси его мне.','Принесите 20 цветков мироцвета травнице Гордый Плюмаж на Аллею Духов Оргриммара.','Подготовка близится к концу, и скоро грянет война. Спасибо за помощь, $N. Мироцвет очень нужен нам, и твой вклад в общее дело не останется незамеченным. Если сможешь, возвращайся и помоги мне собрать еще мироцвета. А пока ступай, и пусть Мать-Земля хранит тебя.','Уже $Gсобрал:собрала; мироцвет и $Gвернулся:вернулась;, $C?','Вернитесь к травнице Красивому Перу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает мироцвета!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, каждое поколение должно пройти испытание огнем. Боюсь, что ан\'киражская война станет для нас тем самым горном для закалки. Ничего, подготовимся как следует и покажем всем, из какого мы слеплены теста.$B$BНам нужен мироцвет, который пойдет на создание лекарственных снадобий, и я вызвалась быть ответственной за его сбор. Надеюсь, ты $gпришел:пришла; предложить мне свою помощь. Собери побольше мироцвета и принеси его мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 цветков мироцвета травнице Гордый Плюмаж на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Подготовка близится к концу, и скоро грянет война. Спасибо за помощь, $N. Мироцвет очень нужен нам, и твой вклад в общее дело не останется незамеченным. Если сможешь, возвращайся и помоги мне собрать еще мироцвета. А пока ступай, и пусть Мать-Земля хранит тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уже $Gсобрал:собрала; мироцвет и $Gвернулся:вернулась;, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к травнице Красивому Перу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8550,'Орде все еще не хватает мироцвета!','Спасибо, что продолжаешь помогать нам, $N. Твоя самоотдача делает честь тебе и твоим предкам. Пойду упакую травы, чтобы они не потеряли своей свежести к тому времени, когда они понадобятся. Продолжай трудиться на благо нашей победы, во имя Орды!','Вернитесь к травнице Красивому Перу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает мироцвета!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что продолжаешь помогать нам, $N. Твоя самоотдача делает честь тебе и твоим предкам. Пойду упакую травы, чтобы они не потеряли своей свежести к тому времени, когда они понадобятся. Продолжай трудиться на благо нашей победы, во имя Орды!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к травнице Красивому Перу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8551,'Сундук капитана','Когда-то у меня был корабль, на котором я плавал до самого Кабестана в Калимдоре, и репутация у меня была безупречная.$B$BПока...$B$BПока не появились проклятые морские великаны! Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую Бухту. А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая. Наглец!$B$BГоворят, Горлаш бродит по берегу к востоку отсюда. Найди его и верни мой сундук! Благодарность моя не будет знать предела.','Верните Гекельберри Смоттсу из Пиратской Бухты его сундук.','Ты его $Gнашел:нашла;! Славный день для меня. Спасибо тебе, $N! Теперь, когда мой сундук ко мне вернулся, я немного успокоился','Эгей, $N! $GНашел:Нашела; Горлаша? Это был мой любимый сундук, к тому же в тайном отделении там лежат все мои сокровища!','Вернитесь к капитану Гекельбери Смоттсу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сундук капитана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда-то у меня был корабль, на котором я плавал до самого Кабестана в Калимдоре, и репутация у меня была безупречная.$B$BПока...$B$BПока не появились проклятые морские великаны! Они разбили мой корабль, поубивали всю команду, а меня отправили на шлюпке в Пиратскую Бухту. А один из гигантов, Горлаш, украл мой капитанский сундук, мол табакерка из него выйдет неплохая. Наглец!$B$BГоворят, Горлаш бродит по берегу к востоку отсюда. Найди его и верни мой сундук! Благодарность моя не будет знать предела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Гекельберри Смоттсу из Пиратской Бухты его сундук.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты его $Gнашел:нашла;! Славный день для меня. Спасибо тебе, $N! Теперь, когда мой сундук ко мне вернулся, я немного успокоился',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эгей, $N! $GНашел:Нашела; Горлаша? Это был мой любимый сундук, к тому же в тайном отделении там лежат все мои сокровища!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гекельбери Смоттсу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8552,'Кушак с монограммой','Вдоль каймы кушака вышита монограмма "ГС".','Верните кушак с монограммой владельцу.','Тебе удалось вернуть мой кушак? Тогда... ты, должно быть, убил морского великана! Урааа!$B$BКак я рад, что этот негодяй мертв – Мок\'раш был одним из трех великанов, которые уничтожили мои корабли и поубивали всю команду.$B$BИ так три раза подряд!$B$BТы достойный $C, $N.','Привет.У тебя ко мне дело?','Разыщите владельца кушака с монограммой в Пиратской Бухте, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кушак с монограммой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вдоль каймы кушака вышита монограмма "ГС".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните кушак с монограммой владельцу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось вернуть мой кушак? Тогда... ты, должно быть, убил морского великана! Урааа!$B$BКак я рад, что этот негодяй мертв – Мок\'раш был одним из трех великанов, которые уничтожили мои корабли и поубивали всю команду.$B$BИ так три раза подряд!$B$BТы достойный $C, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет.У тебя ко мне дело?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите владельца кушака с монограммой в Пиратской Бухте, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8553,'Капитанская сабля','После того как эти проклятые великаны уничтожили мой корабль, я купил еще один. Назвал его "Месть Смоттса", запасся продовольствием, нанял команду и отправился в поисках этих злодеев. Найти-то я их нашел, но... они снова надавали мне по шее. "Месть Смоттса" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку.$B$BУ другого великана, Неголаша, моя сабля.$B$BСразись с Неголашем и принеси мне мою саблю!$B$BМожешь поговорить со Салагой, поваром с "Мести Смоттса", который выжил в последней битве. Он поможет тебе найти великана.','Поговорите с Салагой.','Привет, привет, $N. Капитан сказал мне, что ты будешь бороться с Неголашем, да?','Поговорите с Салагой в Пиратской Бухте, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Капитанская сабля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как эти проклятые великаны уничтожили мой корабль, я купил еще один. Назвал его "Месть Смоттса", запасся продовольствием, нанял команду и отправился в поисках этих злодеев. Найти-то я их нашел, но... они снова надавали мне по шее. "Месть Смоттса" разбили на части, поубивали вторую команду, а меня снова посадили на шлюпку.$B$BУ другого великана, Неголаша, моя сабля.$B$BСразись с Неголашем и принеси мне мою саблю!$B$BМожешь поговорить со Салагой, поваром с "Мести Смоттса", который выжил в последней битве. Он поможет тебе найти великана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Салагой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет, привет, $N. Капитан сказал мне, что ты будешь бороться с Неголашем, да?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Салагой в Пиратской Бухте, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8554,'Бой с Неголашем','Неголаш – великан-обжора.$B$BКогда они уничтожили мой корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это мое коронное блюдо, рецепт я привез из самих Бесплодных земель!$B$BЕсли ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!','Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Смоттса.$B$BУбейте Неголаша и отнесите абордажную саблю Смоттса хозяину в Тернистую долину.','Ты $Gзабрал:забрала; саблю у Неголаша! Я не верил, что мне повезет, $N! Встретив тебя, моя удача вернулась, без сомнения!$B$BСпасибо! И если я когда-нибудь заполучу новый корабль, и ты захочешь прокатиться, то ты будешь не нем почетным гостем.','Ты $Gзаполучил:заполучила; мою саблю, $N?','Вернитесь к капитану Гекельбери Смоттсу в Пиратскую Бухту, что в Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бой с Неголашем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неголаш – великан-обжора.$B$BКогда они уничтожили мой корабль, Неголаш бросился прямиком на кухню. В отличие от его товарищей, команда его не очень интересовала. Ему хотелось вина... и жареных крылышек канюка. Это мое коронное блюдо, рецепт я привез из самих Бесплодных земель!$B$BЕсли ты хочешь приманить великана, добудь вина и кучу крылышек канюка. Сложи их в нашу старую шлюпку, которая причалена на юго-востоке отсюда. Когда Неголаш почует запах еды, он непременно явится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 10 жареных крылышек канюка и 5 бутылок экзотического вина в спасательную шлюпку капитана Смоттса.$B$BУбейте Неголаша и отнесите абордажную саблю Смоттса хозяину в Тернистую долину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gзабрал:забрала; саблю у Неголаша! Я не верил, что мне повезет, $N! Встретив тебя, моя удача вернулась, без сомнения!$B$BСпасибо! И если я когда-нибудь заполучу новый корабль, и ты захочешь прокатиться, то ты будешь не нем почетным гостем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gзаполучил:заполучила; мою саблю, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гекельбери Смоттсу в Пиратскую Бухту, что в Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8555,'Создание драконов','Эраникус, Ваэластраз и Азурегос... Несомненно, ты знаешь об этих драконах, смертный. Поэтому не случайно, что они играли такие влиятельные роли в качестве наблюдателей за нашим миром.$B$BК сожалению (и частично виновата моя собственная наивность), будь то агенты Древних богов или предательство со стороны тех, кто называл их друзьями, каждый страж трагически погиб. Это подогревало мое недоверие к твоему виду.$B$BИ $R, приготовьcя к худшему.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Создание драконов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эраникус, Ваэластраз и Азурегос... Несомненно, ты знаешь об этих драконах, смертный. Поэтому не случайно, что они играли такие влиятельные роли в качестве наблюдателей за нашим миром.$B$BК сожалению (и частично виновата моя собственная наивность), будь то агенты Древних богов или предательство со стороны тех, кто называл их друзьями, каждый страж трагически погиб. Это подогревало мое недоверие к твоему виду.$B$BИ $R, приготовьcя к худшему.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8556,'Перстень неумолимой силы','Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности. Однако считается, что если заменить пораженные скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастет еще больше.$B$BКамни, украшающие киражских идолов, вполне подойдут – они отменного качества.$B$BПринеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, |3-6($c).','Принесите киражское кольцо власти, 2 лучистых идола, 5 бронзовых скарабеев и 5 скарабеев из бивневой кости Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария.','Ты $Gпринес:принесла; мне кольцо и материалы, $N?','Ты $Gпринес:принесла; мне кольцо и материалы, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перстень неумолимой силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности. Однако считается, что если заменить пораженные скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастет еще больше.$B$BКамни, украшающие киражских идолов, вполне подойдут – они отменного качества.$B$BПринеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите киражское кольцо власти, 2 лучистых идола, 5 бронзовых скарабеев и 5 скарабеев из бивневой кости Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпринес:принесла; мне кольцо и материалы, $N?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне кольцо и материалы, $N?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8557,'Пелерина неумолимой силы','Я рад слышать, что ты помогаешь нам в нападении на Ан\'Кираж, $n. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.$B$BМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.$B$BУвидишь, эта вещь тебя не разочарует.','Принесите киражскую воинскую пелерину, 2 ониксовых идола, 5 серебряных и 5 костяных скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.','Воспользуйся этим плащом, $N. Пусть он защитит тебя от нечестивой магии Киражи.','Ты $Gпринес:принесла; мне материалы для плаща, $N?','Вернитесь к Кейлу Стремительному Когтю в Улей Аши, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пелерина неумолимой силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рад слышать, что ты помогаешь нам в нападении на Ан\'Кираж, $n. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.$B$BМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.$B$BУвидишь, эта вещь тебя не разочарует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите киражскую воинскую пелерину, 2 ониксовых идола, 5 серебряных и 5 костяных скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воспользуйся этим плащом, $N. Пусть он защитит тебя от нечестивой магии Киражи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне материалы для плаща, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кейлу Стремительному Когтю в Улей Аши, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8558,'Серп неумолимой силы','Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов...$B$BПри одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них свое собственное искусство. Докажи Кругу Кенариуса свою преданность, $n, и я создам для тебя могучее оружие из лучших киражских материалов.','Принесите киражскую шипастую рукоять, 2 алебастровых идола, 5 хрустальных и 5 каменных скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария.','Ты отлично поработал, |3-6($C). Это шедевр с рукоятью... баланс просто совершенен.$B$BВозьми это оружие, $N. Пусть оно поможет тебе победить наших врагов.','Ты $Gпринес:принесла; то, что мне нужно, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серп неумолимой силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Киражи и их прислужники владеют вещами, которые созданы из редчайших и благороднейших материалов – костей гигантских древних созданий, драгоценностей из самых глубин земли, чистейших и прочных металлов...$B$BПри одном взгляде на киражские артефакты мне хочется разбить их, чтобы переплавить обломки и испробовать на них свое собственное искусство. Докажи Кругу Кенариуса свою преданность, $n, и я создам для тебя могучее оружие из лучших киражских материалов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите киражскую шипастую рукоять, 2 алебастровых идола, 5 хрустальных и 5 каменных скарабеев Надзирателю Харо в Силитус. Кроме того, вас должны превозносить в Круге Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты отлично поработал, |3-6($C). Это шедевр с рукоятью... баланс просто совершенен.$B$BВозьми это оружие, $N. Пусть оно поможет тебе победить наших врагов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; то, что мне нужно, $N?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8559,'Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.','Принесите киражские наручники властности, 2 идола Войны, 5 золотых скарабеев и 5 скарабеев из бивневой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.','Отличная работа, $N. Ты $Gдоказал:доказала; что ты не $Gпростой:простая; $Gсмертный:смертная;.$B$BВозьми это, они помогут тебя в сражении против этих мерзких Киражей.','Тебе удалось добыть то, о чем я просил, $N?','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите киражские наручники властности, 2 идола Войны, 5 золотых скарабеев и 5 скарабеев из бивневой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Ты $Gдоказал:доказала; что ты не $Gпростой:простая; $Gсмертный:смертная;.$B$BВозьми это, они помогут тебя в сражении против этих мерзких Киражей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть то, о чем я просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8560,'Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.','Принесите целую шкуру Оуро, 2 идола Смерти, 5 бронзовых скарабеев и 5 скарабеев из бивневой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.','Да... использовав шкуру червя на вещи, можно не плохо усилить ее. Возьми эти набедренники. Пусть они помогут тебе в сражении против Киражи!','Ты $Gпринес:принесла; не обходимые мне компоненты, $N?','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите целую шкуру Оуро, 2 идола Смерти, 5 бронзовых скарабеев и 5 скарабеев из бивневой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... использовав шкуру червя на вещи, можно не плохо усилить ее. Возьми эти набедренники. Пусть они помогут тебе в сражении против Киражи!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; не обходимые мне компоненты, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8561,'Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан\'Кираж будут служить нам.$B$BПринеси то, что мне нужно, $n. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.','Тебе удалось одержать победу! Императоры-близнецы прекратили шептаться в моей голове.$B$BПрими же от меня награду. Один вид этой вещи вселит ужас в сердца киражи... Она напомнит им, что самые могучие их предводители погибли от рук смертных.','Ты $Gпринес:принесла; мне то, о чем я просила, $N?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан\'Кираж будут служить нам.$B$BПринеси то, что мне нужно, $n. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось одержать победу! Императоры-близнецы прекратили шептаться в моей голове.$B$BПрими же от меня награду. Один вид этой вещи вселит ужас в сердца киражи... Она напомнит им, что самые могучие их предводители погибли от рук смертных.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне то, о чем я просила, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8562,'Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.','Я не ожидала, что ты сумеешь вернуться $Gживым:живой; $N.$B$BТебе удалось исполнить то, что не под силу многим бессмертным.$B$BУбив К\'Туна, ты не только $Gспас:спасла; Азерот, ты $Gпоколоебал:поколебала; чаши космических весов, на которых лежат события, далеко превосходящие твое понимание.$B$BПрими эти одежды как символ великой славы и знак великого груза, который ты $Gвзвалил:взвалила; на себя своим поступком.$B$BБыть может, они помогут преодолеть тяготы пути, который отныне лежит перед тобой, богоубийца.','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.','Вернитесь к Ветсере в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не ожидала, что ты сумеешь вернуться $Gживым:живой; $N.$B$BТебе удалось исполнить то, что не под силу многим бессмертным.$B$BУбив К\'Туна, ты не только $Gспас:спасла; Азерот, ты $Gпоколоебал:поколебала; чаши космических весов, на которых лежат события, далеко превосходящие твое понимание.$B$BПрими эти одежды как символ великой славы и знак великого груза, который ты $Gвзвалил:взвалила; на себя своим поступком.$B$BБыть может, они помогут преодолеть тяготы пути, который отныне лежит перед тобой, богоубийца.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ветсере в Ан\'Кираж.',`completedtext_loc8`);
