INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8571,'<UNUSED>Комплекты грубой брони','Вернитесь к Хроносу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>Комплекты грубой брони',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хроносу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8572,'Броня ветерана','Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в Крепости Кенария, нужны не для красоты, $n.$b$bНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.','Принесите 7 боевых, 4 тыловых и 4 тактических знаков Кенария Варгусу из Крепости Кенария в Силитусе. Кроме того, для выполнения этого задания вам необходимо заслужить уважительное отношение Круга Кенария.','Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в Крепости Кенария, нужны не для красоты, $N.$B$BНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.','В наших интересах держать наших самых верных союзников в хорошей форме, $N.','Вернитесь к Варгусу в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Броня ветерана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в Крепости Кенария, нужны не для красоты, $n.$b$bНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 7 боевых, 4 тыловых и 4 тактических знаков Кенария Варгусу из Крепости Кенария в Силитусе. Кроме того, для выполнения этого задания вам необходимо заслужить уважительное отношение Круга Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в Крепости Кенария, нужны не для красоты, $N.$B$BНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В наших интересах держать наших самых верных союзников в хорошей форме, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варгусу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
