ectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Те знаки, которые достались тебе во время выполнения боевых, тыловых и тактических заданий в Крепости Кенария, нужны не для красоты, $N.$B$BНе теряй их. Когда ты докажешь свою верность нашей организации, я смогу предложить тебе кое-какое снаряжение, которое мы храним для ближайших сподвижников, в обмен на эти знаки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В наших интересах держать наших самых верных союзников в хорошей форме, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варгусу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8575,'Магическая книга Азурегоса','Из надписи на книге вы ни слова не понимаете. Вы даже не знаете, на каком языке сделана эта надпись!','Принесите магическую книгу Азурегоса Нарайну Причуденю в Танарис.','<Нарайн рассматривает письмо>$B$BВыдающийся, $R! Что это? Я не могу читать это.','Оооо! Пульсирующая магией штуковина! Для меня?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магическая книга Азурегоса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из надписи на книге вы ни слова не понимаете. Вы даже не знаете, на каком языке сделана эта надпись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите магическую книгу Азурегоса Нарайну Причуденю в Танарис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Нарайн рассматривает письмо>$B$BВыдающийся, $R! Что это? Я не могу читать это.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Оооо! Пульсирующая магией штуковина! Для меня?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8576,'Перевод книги','Перво-наперво, $N! Мы должны выяснить, что написал Азурегос в этой книге.$B$BГоворишь, что он сказал тебе сделать арканитовый буй и это есть схема? Странно, что он использовал драконий язык, зная, что я не могу читать это.$B$BНу что же, тогда мне понадобятся мои гадальные очки, 500-фунтовая курица и второй том книги "Драконий язык для чайников". Не обязательно в таком порядке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перевод книги',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Перво-наперво, $N! Мы должны выяснить, что написал Азурегос в этой книге.$B$BГоворишь, что он сказал тебе сделать арканитовый буй и это есть схема? Странно, что он использовал драконий язык, зная, что я не могу читать это.$B$BНу что же, тогда мне понадобятся мои гадальные очки, 500-фунтовая курица и второй том книги "Драконий язык для чайников". Не обязательно в таком порядке.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8577,'Тушеный Лис, БЛД','Если я хочу хоть что-то перевести, мне нужны мои гадальные очки. Увы, их давным-давно спер мой бывший лучший друг Тушеный Лис. Он разбил мое сердце на пять частей и оставил меня в горести.$B$BПри помощи моего верного хрустального шара я выяснил, где он находится – либо у Стены Седогрива в Серебряном бору или в каком-то мире за порталом Запределья, нынче разоренном Пылающим Легионом. Вы должны найти его след и отнять у него мои очки, $n!','Нарайн Причудень хочет, чтобы вы нашли его бывшего лучшего друга (БЛД) Тушеного Лиса, и отняли у него гадальные очки, которые БЛД украл у Причуденя.','Я не могу поверить, что он нашел меня. Я был уверен, что потерял его, когда был в Запределье. Я не собираюсь возвращаться туда, $R! Никогда!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тушеный Лис, БЛД',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если я хочу хоть что-то перевести, мне нужны мои гадальные очки. Увы, их давным-давно спер мой бывший лучший друг Тушеный Лис. Он разбил мое сердце на пять частей и оставил меня в горести.$B$BПри помощи моего верного хрустального шара я выяснил, где он находится – либо у Стены Седогрива в Серебряном бору или в каком-то мире за порталом Запределья, нынче разоренном Пылающим Легионом. Вы должны найти его след и отнять у него мои очки, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нарайн Причудень хочет, чтобы вы нашли его бывшего лучшего друга (БЛД) Тушеного Лиса, и отняли у него гадальные очки, которые БЛД украл у Причуденя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не могу поверить, что он нашел меня. Я был уверен, что потерял его, когда был в Запределье. Я не собираюсь возвращаться туда, $R! Никогда!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8578,'Гадальные очки? Без проблем!','* Из ящика доносится вздох облегчения.*$B$BТак вам нужны только его очки? Отлично! Никаких проблем... Подождите минуточку, и... Эй! Где... Епрст!$B$BВ общем, есть новость плохая и еще хуже. Плохая – я потерял очки. Еще хуже – я потерял их, когда в прошлом месяце разнюхивал обстановку в Огненных Недрах. Да, в Огненных Недрах... Думаю, что на этом наш разговор закончен! Пока!','Найдите гадальные очки Нарайна и отнесите их Нарайну Причуденю в Танарис.','Замечательно! А куда же я дел 500-фунтовую курицу и второй том "Драконий язык для чайников"? Да, вот кое-что тебе, за твою тяжелую работу.','Огненные Недра? Надеюсь что мои очки все еще целы!','Вернитесь к Нарайну Причуденю в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гадальные очки? Без проблем!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','* Из ящика доносится вздох облегчения.*$B$BТак вам нужны только его очки? Отлично! Никаких проблем... Подождите минуточку, и... Эй! Где... Епрст!$B$BВ общем, есть новость плохая и еще хуже. Плохая – я потерял очки. Еще хуже – я потерял их, когда в прошлом месяце разнюхивал обстановку в Огненных Недрах. Да, в Огненных Недрах... Думаю, что на этом наш разговор закончен! Пока!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите гадальные очки Нарайна и отнесите их Нарайну Причуденю в Танарис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! А куда же я дел 500-фунтовую курицу и второй том "Драконий язык для чайников"? Да, вот кое-что тебе, за твою тяжелую работу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Огненные Недра? Надеюсь что мои очки все еще целы!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нарайну Причуденю в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8579,'Поборники правого дела из числа смертных','Я вижу, ты не обычная смертная, Риктикитики. Твои шансы победить древнего бога исчезающе малы, но они все равно больше, чем наши. В конце концов, если он ожидает у своих дверей драконов, то вряд ли готовится встретить кого-нибудь вроде тебя. $B$BТысячу лет назад Анахронос и Олений Шлем создали союз смертных и драконов, и смогли победить киражи. Можем заключить договор и мы. Если ты завоюешь доверие крыла Бронзовых драконов, мы тоже будем тебе доверять, и ты сможешь стать настоящим защитником правого дела.','Вернитесь к Кандостразу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поборники правого дела из числа смертных',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я вижу, ты не обычная смертная, Риктикитики. Твои шансы победить древнего бога исчезающе малы, но они все равно больше, чем наши. В конце концов, если он ожидает у своих дверей драконов, то вряд ли готовится встретить кого-нибудь вроде тебя. $B$BТысячу лет назад Анахронос и Олений Шлем создали союз смертных и драконов, и смогли победить киражи. Можем заключить договор и мы. Если ты завоюешь доверие крыла Бронзовых драконов, мы тоже будем тебе доверять, и ты сможешь стать настоящим защитником правого дела.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8580,'Орде не хватает огнецвета!','Даров, |3-6($c). Как делишки, дружище? Орде тут для войны в Ан\'Кираже понадобилась прорва этого несчастного огнецвета. Даж интересно, они собираются запихнуть его во всякие взрывающиеся штуки или отдать Альянсу на топливо для танков? Спроси что-нибудь полегче, тут Пелекейки не в курсе, ага.$B$BНо кое-что Пелекейки знает... например, что ты сейчас пойдешь и принесешь ему этого несчастного огнецвета, ага, дружище?','Принесите 20 огнецветов нетопыриному наезднику Пелекейки на Аллею Духов Оргриммара.','$C! Пеле\'кейки просто счастлив. Сейчас он заберет эти цветочки и сложит их в коробку, чтоб не попортились. Уж Пеле\'кейки присмотрит, чтоб их употребили на всякие военные штуки, а не на какую-нибудь дребедень. А если добудешь еще цветочков, сразу же тащи Пеле\'кейки, ему это всяко понадобится.','Ты ведь не хочешь рассердить Пелекейки, ага, $Gдружище:подруга;? Ты хочешь, чтобы Пелекейки был счастлив. Поэтому сейчас пойдешь и принесешь ему целую охапку огнецвета, причем очень-очень быстро!','Вернитесь к объездчику нетопырей Пеле\'кейки в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает огнецвета!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даров, |3-6($c). Как делишки, дружище? Орде тут для войны в Ан\'Кираже понадобилась прорва этого несчастного огнецвета. Даж интересно, они собираются запихнуть его во всякие взрывающиеся штуки или отдать Альянсу на топливо для танков? Спроси что-нибудь полегче, тут Пелекейки не в курсе, ага.$B$BНо кое-что Пелекейки знает... например, что ты сейчас пойдешь и принесешь ему этого несчастного огнецвета, ага, дружище?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 огнецветов нетопыриному наезднику Пелекейки на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$C! Пеле\'кейки просто счастлив. Сейчас он заберет эти цветочки и сложит их в коробку, чтоб не попортились. Уж Пеле\'кейки присмотрит, чтоб их употребили на всякие военные штуки, а не на какую-нибудь дребедень. А если добудешь еще цветочков, сразу же тащи Пеле\'кейки, ему это всяко понадобится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты ведь не хочешь рассердить Пелекейки, ага, $Gдружище:подруга;? Ты хочешь, чтобы Пелекейки был счастлив. Поэтому сейчас пойдешь и принесешь ему целую охапку огнецвета, причем очень-очень быстро!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к объездчику нетопырей Пеле\'кейки в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8581,'Орде все еще не хватает огнецвета!','Это не шутка, $C? Ты так быстро $Gпринес:принесла; огнецвета Пеле\'кейке? Пеле\'кейки пересчитает их прямо сейчас, дружище! Ты делаешь Пеле\'кейки таким счастливым, он всем рассказывал, $N лучший коллекционер огнецвета! Пеле\'кейки не может дождаться начала войны.','Вернитесь к объездчику нетопырей Пеле\'кейки в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает огнецвета!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это не шутка, $C? Ты так быстро $Gпринес:принесла; огнецвета Пеле\'кейке? Пеле\'кейки пересчитает их прямо сейчас, дружище! Ты делаешь Пеле\'кейки таким счастливым, он всем рассказывал, $N лучший коллекционер огнецвета! Пеле\'кейки не может дождаться начала войны.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к объездчику нетопырей Пеле\'кейки в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8582,'Орде не хватает лилового лотоса!','Лилового лотос, |3-6($c), является основной составляющей множества зелий, эликсиров и масел, которые необходимы для войны в Ан\'Кираже. Мы создадим бесчисленное количество самых разных снадобий. Я думаю, придется даже поэкспериментировать, чтобы исследовать все возможные способы его применения. Но для экспериментов необходимо иметь достаточно цветов в запасе.$B$BА вот это уже работа для тебя. Ступай и собери как можно больше цветков лилового лотоса. Возьмешься ради нас за это задание?','Принесите 20 цветков лилового лотоса аптекарю Жезели на Аллею Духов Оргриммара.','Твоя работа заслуживает одобрения, $C. Я должна рассортировать образцы и не забыть отметить, что это был твой вклад. Пока у меня не дойдут руки до этих цветов, нужно их правильно хранить. Как ты $Gмог:могла; отметить, лотоса нужно гораздо больше, чем мы сейчас имеем. Далеко не уходи.','Ты так скоро $Gвозвратился:возвратилась; $C? А где лиловый лотос? Поторопись, а то все мои труды пойдут насмарку.','Вернитесь к аптекарю Жезели в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает лилового лотоса!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лилового лотос, |3-6($c), является основной составляющей множества зелий, эликсиров и масел, которые необходимы для войны в Ан\'Кираже. Мы создадим бесчисленное количество самых разных снадобий. Я думаю, придется даже поэкспериментировать, чтобы исследовать все возможные способы его применения. Но для экспериментов необходимо иметь достаточно цветов в запасе.$B$BА вот это уже работа для тебя. Ступай и собери как можно больше цветков лилового лотоса. Возьмешься ради нас за это задание?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 цветков лилового лотоса аптекарю Жезели на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя работа заслуживает одобрения, $C. Я должна рассортировать образцы и не забыть отметить, что это был твой вклад. Пока у меня не дойдут руки до этих цветов, нужно их правильно хранить. Как ты $Gмог:могла; отметить, лотоса нужно гораздо больше, чем мы сейчас имеем. Далеко не уходи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты так скоро $Gвозвратился:возвратилась; $C? А где лиловый лотос? Поторопись, а то все мои труды пойдут насмарку.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Жезели в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8583,'Орде все еще не хватает лилового лотоса!','Безукоризненно точная работа, $N. Не могу не похвалить твое прилежание, а так же быстроту. Я лично присмотрю, чтобы ни один из этих цветков не пропал понапрасну.$B$BБольшое тебе спасибо. Если соберешь еще лилового лотоса, бегом неси ко мне.','Вынуждена констатировать тот факт, что мы все еще нуждаемся в цветах лилового лотоса, |3-6($C). Мои исследования направлены на изучение новых способов применения этого реагента, и очень много уходит на то, чтобы выработать методологию.$B$BМне нужно, чтобы ты собрал как минимум еще двадцать образцов. Возвращайся, когда выполнишь это задание.','Вернитесь к аптекарю Жезели в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает лилового лотоса!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Безукоризненно точная работа, $N. Не могу не похвалить твое прилежание, а так же быстроту. Я лично присмотрю, чтобы ни один из этих цветков не пропал понапрасну.$B$BБольшое тебе спасибо. Если соберешь еще лилового лотоса, бегом неси ко мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вынуждена констатировать тот факт, что мы все еще нуждаемся в цветах лилового лотоса, |3-6($C). Мои исследования направлены на изучение новых способов применения этого реагента, и очень много уходит на то, чтобы выработать методологию.$B$BМне нужно, чтобы ты собрал как минимум еще двадцать образцов. Возвращайся, когда выполнишь это задание.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Жезели в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8584,'Никогда не расспрашивай меня о моем бизнесе!','Обо мне вам следует знать только одно – НИКОГДА не расспрашивайте меня о моем бизнесе! Я работаю с такими материями, в которых вы просто ничего не понимаете! Например: знаете ли вы, что такое психотронный мордарий? Конечно, не знаете! Именно поэтому я – мозговой центр, а вы – добывающий придаток.$B$BКак я уже сказал, если мы хотим, чтобы у нас все получилось, нам понадобится 500-фунтовая курица.$B$BСтупайте в Прибамбасск и поговорите с Могилем Быстрорубом – он скажет, где вам искать подходящий экземпляр.','Нарайн Причудень из Танариса хочет, чтобы вы поговорили с Могилем Быстрорубом из Прибамбасска.','<Могиль чешет в затылке.>$B$B500-фунтовая курица? Таких не бывает! То есть, уже не бывает. Знавал я такую птицу... Черного бройлера-убийцу...$B$B<У Могиля дрожит голос.>$B$BНо его давно уже никто не видел, и эта птица теперь существует только в сказках. Однако у меня есть идейка, от которой будет выгода нам обоим.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Никогда не расспрашивай меня о моем бизнесе!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обо мне вам следует знать только одно – НИКОГДА не расспрашивайте меня о моем бизнесе! Я работаю с такими материями, в которых вы просто ничего не понимаете! Например: знаете ли вы, что такое психотронный мордарий? Конечно, не знаете! Именно поэтому я – мозговой центр, а вы – добывающий придаток.$B$BКак я уже сказал, если мы хотим, чтобы у нас все получилось, нам понадобится 500-фунтовая курица.$B$BСтупайте в Прибамбасск и поговорите с Могилем Быстрорубом – он скажет, где вам искать подходящий экземпляр.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нарайн Причудень из Танариса хочет, чтобы вы поговорили с Могилем Быстрорубом из Прибамбасска.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Могиль чешет в затылке.>$B$B500-фунтовая курица? Таких не бывает! То есть, уже не бывает. Знавал я такую птицу... Черного бройлера-убийцу...$B$B<У Могиля дрожит голос.>$B$BНо его давно уже никто не видел, и эта птица теперь существует только в сказках. Однако у меня есть идейка, от которой будет выгода нам обоим.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8585,'Остров Ужаса!','Легенды гласят, что у химер Острова Ужаса, что в Фераласе, самое сочное и нежное на свете мясо! У этих химер есть главный химер, который, если его приготовить как надо, сойдет за 500-фунтовую курицу. Или не сойдет.$B$BСтупай на остров Ужаса и убей лорда Лакмерана. Принеси мне его тушу. Гном будет доволен. А вот чтобы я был доволен, достань мне немного вырезки химеры.$B$BСделай это – и будет тебе твоя 500-фунтовая курица и кое-что сверх того.','Принесите тушу Лакмерана и 20 кусков вырезки химер Могилю Быстрорубу в Танарис.','Посмотри на это филе! Это просто фантастика!$B$BТеперь о курице... Хм, дай посмотреть. Мне нужно несколько минут, чтобы разобраться в рецепте.','Мммм... Химеры...','Вернитесь к Могилю Быстрорубу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остров Ужаса!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Легенды гласят, что у химер Острова Ужаса, что в Фераласе, самое сочное и нежное на свете мясо! У этих химер есть главный химер, который, если его приготовить как надо, сойдет за 500-фунтовую курицу. Или не сойдет.$B$BСтупай на остров Ужаса и убей лорда Лакмерана. Принеси мне его тушу. Гном будет доволен. А вот чтобы я был доволен, достань мне немного вырезки химеры.$B$BСделай это – и будет тебе твоя 500-фунтовая курица и кое-что сверх того.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите тушу Лакмерана и 20 кусков вырезки химер Могилю Быстрорубу в Танарис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотри на это филе! Это просто фантастика!$B$BТеперь о курице... Хм, дай посмотреть. Мне нужно несколько минут, чтобы разобраться в рецепте.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мммм... Химеры...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Могилю Быстрорубу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8586,'Рецепт готов! Теперь мне нужно от тебя немного ракетного топлива и глубокоскальной соли. Я займусь специями, а за счет мяса, что ты $Gдобыл:добыла; покроем остальные расходы.$B$BКак принесешь мне то, что я просил, курица будет готова, и можешь нести ее Нарайну.','Могиль Быстроруб Прибамбасска просит, чтобы вы принесли ему 20 порций гоблинского ракетного топлива и 20 порций глубокоскальной соли.','Все готово! Я представляю тебе свое величайшее творение: зажигательные отбивные Могиля из химерока!','Поторопись! Мы же не хотим, чтобы это мясо пропало.','Вернитесь к Могилю Быстрорубу в Танарис.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рецепт готов! Теперь мне нужно от тебя немного ракетного топлива и глубокоскальной соли. Я займусь специями, а за счет мяса, что ты $Gдобыл:добыла; покроем остальные расходы.$B$BКак принесешь мне то, что я просил, курица будет готова, и можешь нести ее Нарайну.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Могиль Быстроруб Прибамбасска просит, чтобы вы принесли ему 20 порций гоблинского ракетного топлива и 20 порций глубокоскальной соли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все готово! Я представляю тебе свое величайшее творение: зажигательные отбивные Могиля из химерока!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поторопись! Мы же не хотим, чтобы это мясо пропало.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Могилю Быстрорубу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8587,'Возвращение к Нарайну','Я гоблин слова, $Gпарень:подруга;. Вот твой 500 фунтовый цыпленок.$B$BНа кой гному 500-фунтовый цыпленок – понятия не имею...$B$B*Могиль ворчит себе под нос что-то неразборчивое.*$B$BМожет, он спать в нем будет... Грязные гномы...','Доставьте 500-фунтового цыпленка Нарайну Причуденю в Танарис.','<Нарайн помещает обе руки на цыпленка и запихивает в него свое лицо.>$B$BМммм... Это невероятно! Лучший цыпленок, которого я когда-то видел!','Что это за чудный запах?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Нарайну',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я гоблин слова, $Gпарень:подруга;. Вот твой 500 фунтовый цыпленок.$B$BНа кой гному 500-фунтовый цыпленок – понятия не имею...$B$B*Могиль ворчит себе под нос что-то неразборчивое.*$B$BМожет, он спать в нем будет... Грязные гномы...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте 500-фунтового цыпленка Нарайну Причуденю в Танарис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Нарайн помещает обе руки на цыпленка и запихивает в него свое лицо.>$B$BМммм... Это невероятно! Лучший цыпленок, которого я когда-то видел!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это за чудный запах?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8588,'Орде не хватает толстой кожи!','Если уж мы собрались воевать, сначала надо подготовиться как следует, правда, дружище? Толстая кожа на войне – продукт первой необходимости. Она идет на все – начиная с заплаток на доспехи и заканчивая старыми добрыми ловушками.$B$BИменно поэтому ее надо собрать как можно больше. А вот это уже твоя работа, |3-6($c). Наточи поострее нож и добудь кож этак штук десять. Вот принесешь их, тогда и поговорим.','Принесите 10 кусков толстой кожи специалисту по снятию шкур Джамани на Аллею Духов Оргриммара.','О, тебе удалось достать толстую кожу. У тебя острый нож, $C, кожи отлично выделаны! Пойду уберу их на склад. Нужно убедиться, что твой вклад не пропадет и послужит на благо Орде. Если удастся раздобыть еще, неси сюда.','Я тут не в игрушки играю, так что времени трепаться с тобой у меня нет, $C. Слишком много толстой кожи, с которой надо возиться. Возвращайся обратно, когда соберешь хотя бы десять кусков.','Вернитесь к специалисту по снятию шкур Джамани в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает толстой кожи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если уж мы собрались воевать, сначала надо подготовиться как следует, правда, дружище? Толстая кожа на войне – продукт первой необходимости. Она идет на все – начиная с заплаток на доспехи и заканчивая старыми добрыми ловушками.$B$BИменно поэтому ее надо собрать как можно больше. А вот это уже твоя работа, |3-6($c). Наточи поострее нож и добудь кож этак штук десять. Вот принесешь их, тогда и поговорим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 кусков толстой кожи специалисту по снятию шкур Джамани на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, тебе удалось достать толстую кожу. У тебя острый нож, $C, кожи отлично выделаны! Пойду уберу их на склад. Нужно убедиться, что твой вклад не пропадет и послужит на благо Орде. Если удастся раздобыть еще, неси сюда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я тут не в игрушки играю, так что времени трепаться с тобой у меня нет, $C. Слишком много толстой кожи, с которой надо возиться. Возвращайся обратно, когда соберешь хотя бы десять кусков.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к специалисту по снятию шкур Джамани в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8589,'Орде все еще не хватает толстой кожи!','Ну ты даешь, дружище! Огромное тебе спасибо за эти кожи. Каждая из них хоть немного, но приближает нас к завершению военной подготовки. Пойду сдам кожи на склад, чтобы кожевники могли приступить к работе.$B$BБольшое тебе спасибо еще раз. Если раздобудешь следующую порцию кож, то ты знаешь, где меня найти.','Так точно, |3-6($C), мне все еще нужна толстая кожа. Запросы от генералов и интендантских служб кажутся бесконечными. Но это еще ничто по сравнению с тем, что требуют от нас хозяева дирижаблей!$B$BМне придется, пожалуй, двойную норму сдать. $N, пожалуйста, принеси побольше толстой кожи, и как можно скорее!','Вернитесь к специалисту по снятию шкур Джамани в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает толстой кожи!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну ты даешь, дружище! Огромное тебе спасибо за эти кожи. Каждая из них хоть немного, но приближает нас к завершению военной подготовки. Пойду сдам кожи на склад, чтобы кожевники могли приступить к работе.$B$BБольшое тебе спасибо еще раз. Если раздобудешь следующую порцию кож, то ты знаешь, где меня найти.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так точно, |3-6($C), мне все еще нужна толстая кожа. Запросы от генералов и интендантских служб кажутся бесконечными. Но это еще ничто по сравнению с тем, что требуют от нас хозяева дирижаблей!$B$BМне придется, пожалуй, двойную норму сдать. $N, пожалуйста, принеси побольше толстой кожи, и как можно скорее!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к специалисту по снятию шкур Джамани в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8590,'Орде не хватает плотной кожи!','Я рада, что ты $gрешил:решила; поговорить со мной, |3-6($c). Подготовка к войне в Ан\'Кираже идет полным ходом, так что нам с тобой нельзя сбавлять темп работы.$B$BЯ отвечаю за сбор плотной кожи, и ее нужно действительно много, поэтому без твоей помощи никак не справиться. Если ты мне поможешь, в моем лице тебе будет благодарна вся Орда.','Принесите 10 плотных кож сержанту Умале на Аллею Духов Оргриммара.','Ты хорошо постарался, $C. Эта кожа не будет истрачена зря – она пойдет на усиление наших дирижаблей и изготовление оружия и брони. Благодарю тебя от лица всей Орды. Если тебе в своих путешествиях удастся добыть еще плотной кожи, неси ее мне. И удачи тебе.','Что, $C, уже удалось достать плотную кожу?','Вернитесь к сержанту Умале в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает плотной кожи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рада, что ты $gрешил:решила; поговорить со мной, |3-6($c). Подготовка к войне в Ан\'Кираже идет полным ходом, так что нам с тобой нельзя сбавлять темп работы.$B$BЯ отвечаю за сбор плотной кожи, и ее нужно действительно много, поэтому без твоей помощи никак не справиться. Если ты мне поможешь, в моем лице тебе будет благодарна вся Орда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 плотных кож сержанту Умале на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты хорошо постарался, $C. Эта кожа не будет истрачена зря – она пойдет на усиление наших дирижаблей и изготовление оружия и брони. Благодарю тебя от лица всей Орды. Если тебе в своих путешествиях удастся добыть еще плотной кожи, неси ее мне. И удачи тебе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что, $C, уже удалось достать плотную кожу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Умале в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8591,'Орде все еще не хватает плотной кожи!','Ты справился, я знала, что у тебя все выйдет! От имени всей Орды я снова благодарю тебя. Твой вклад не останется незамеченным. Если достанешь еще плотной кожи, приноси ее мне.$B$BЛок\'тар огар, $C!','Как видишь, |3-6($C), я все еще продолжаю собирать плотную кожу. И я снова хочу просить тебя о помощи. Обещаю, Орда не забудет приложенных тобой усилий.$B$BПостарайся достать кожу как можно скорее, для нас очень важно поскорее закончить приготовления к войне!','Вернитесь к сержанту Умале в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает плотной кожи!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты справился, я знала, что у тебя все выйдет! От имени всей Орды я снова благодарю тебя. Твой вклад не останется незамеченным. Если достанешь еще плотной кожи, приноси ее мне.$B$BЛок\'тар огар, $C!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как видишь, |3-6($C), я все еще продолжаю собирать плотную кожу. И я снова хочу просить тебя о помощи. Обещаю, Орда не забудет приложенных тобой усилий.$B$BПостарайся достать кожу как можно скорее, для нас очень важно поскорее закончить приготовления к войне!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Умале в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (8592,'Тиара Оракула','Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан\'Кираж будут служить нам.$B$BПринеси то, что мне нужно, $n. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тиара Оракула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан\'Кираж будут служить нам.$B$BПринеси то, что мне нужно, $n. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8593,'Брюки Оракула','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.','Принесите целую шкуру Оуро, 2 идола Жизни, 5 золотых и 5 глиняных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.','Да... Эту шкуру невозможно пробить почти ничем. Если добавить самые прочные куски панцирей киражи, убитых нами по дороге сюда, из нее получится великолепный доспех. Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан\'Киража.','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брюки Оракула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите целую шкуру Оуро, 2 идола Жизни, 5 золотых и 5 глиняных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружественное отношение рода Ноздорму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... Эту шкуру невозможно пробить почти ничем. Если добавить самые прочные куски панцирей киражи, убитых нами по дороге сюда, из нее получится великолепный доспех. Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан\'Киража.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8594,'Оплечье Оракула','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!','Тебе удалось собрать все, что мне нужно?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оплечье Оракула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать все, что мне нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8595,'Поборники правого дела из числа смертных','Удивительно, что смертному существу вроде тебя, $N, удалось одолеть киражского владыку. Но их армия по-прежнему сильна и многочисленна. Если хочешь доказать, что ты действительно $Gпоборник:поборница; нашего дела, продолжай истреблять киражи.','Вернитесь к Кандостразу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поборники правого дела из числа смертных',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удивительно, что смертному существу вроде тебя, $N, удалось одолеть киражского владыку. Но их армия по-прежнему сильна и многочисленна. Если хочешь доказать, что ты действительно $Gпоборник:поборница; нашего дела, продолжай истреблять киражи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8596,'Обмотки Оракула','Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.','Принесите киражские наручники властности, 2 идола Смерти, 5 бронзовых и 5 золотых скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обмотки Оракула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите киражские наручники властности, 2 идола Смерти, 5 бронзовых и 5 золотых скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8597,'"Драконий язык для чайников"','Я так и знал, что однажды эта книга мне пригодится! И я в своей мудрости и предусмотрительности приготовил для нее укромное хранилище.$B$BНе беспокойтесь, это место никто и никогда не найдет! Только для того, чтобы туда добраться, мне понадобился гирокоптер. Увы, я потерпел крушение на берегу по дороге домой. Но именно в результате этого несчастного случая я обрел сверхгномские способности!$B$BНайдите мой разбитый гирокоптер на Последнем берегу и плывите оттуда к югу! Нужное место узнаете с первого взгляда!','Найдите книгу Нарайна Причуденя на острове в Южных морях.','Книга пропала! Но здесь лежит записка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Драконий язык для чайников"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я так и знал, что однажды эта книга мне пригодится! И я в своей мудрости и предусмотрительности приготовил для нее укромное хранилище.$B$BНе беспокойтесь, это место никто и никогда не найдет! Только для того, чтобы туда добраться, мне понадобился гирокоптер. Увы, я потерпел крушение на берегу по дороге домой. Но именно в результате этого несчастного случая я обрел сверхгномские способности!$B$BНайдите мой разбитый гирокоптер на Последнем берегу и плывите оттуда к югу! Нужное место узнаете с первого взгляда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите книгу Нарайна Причуденя на острове в Южных морях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Книга пропала! Но здесь лежит записка.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8598,'вЫкУП','*Текст записки оттиснут на пергаменте различными шрифтами.*$B$BТвоя драгоценная книга у нас, гном. Ежели хочешь снова ее увидеть, делай как сказано.$B$B*Дальше идет список инструкций на три страницы.*$B$BНеси деньги и приходи один!','Отнесите письмо с требованием выкупа Нарайну Причуденю в Танарис.','<Лицо Нарайна окрашивается в красный цвет.>$B$BНу хорошо... я покажу им, что значит связаться с гномом!','В чем дело?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','вЫкУП',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Текст записки оттиснут на пергаменте различными шрифтами.*$B$BТвоя драгоценная книга у нас, гном. Ежели хочешь снова ее увидеть, делай как сказано.$B$B*Дальше идет список инструкций на три страницы.*$B$BНеси деньги и приходи один!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо с требованием выкупа Нарайну Причуденю в Танарис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Лицо Нарайна окрашивается в красный цвет.>$B$BНу хорошо... я покажу им, что значит связаться с гномом!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В чем дело?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8599,'Любовная песнь для Нарайна','Нечасто у меня бывают гости. Говоря по чести, последний раз это было тогда, когда я спасла этого миленького, сладенького гномика из-под обломков разбитого ветролета.$B$B*Меридит смотрит вдаль, погрузившись в воспоминания.*$B$BТы его знаешь? Нарайн? Нарайн Причудень? О, как бы я была благодарна, если бы кто-нибудь доставил ему письмо от меня. Я просто должна рассказать ему о своих чувствах! Я знаю, это любовь! Я точно знаю!$B$BНе можешь ли ты доставить это письмецо Нарайну? Я век буду благодарна тебе!','Отнесите любовное послание Меридит Нарайну Причуденю в Танарис.','Что!?$B$B*Нарайн начинает суетиться.*$B$BНу, хммм... От меня-то вы чего хотите??? Она же рыба! РЫБА, говорю вам! А я гном. У нас все равно ничего бы не вышло.','От вас рыбой несет!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любовная песнь для Нарайна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нечасто у меня бывают гости. Говоря по чести, последний раз это было тогда, когда я спасла этого миленького, сладенького гномика из-под обломков разбитого ветролета.$B$B*Меридит смотрит вдаль, погрузившись в воспоминания.*$B$BТы его знаешь? Нарайн? Нарайн Причудень? О, как бы я была благодарна, если бы кто-нибудь доставил ему письмо от меня. Я просто должна рассказать ему о своих чувствах! Я знаю, это любовь! Я точно знаю!$B$BНе можешь ли ты доставить это письмецо Нарайну? Я век буду благодарна тебе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите любовное послание Меридит Нарайну Причуденю в Танарис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что!?$B$B*Нарайн начинает суетиться.*$B$BНу, хммм... От меня-то вы чего хотите??? Она же рыба! РЫБА, говорю вам! А я гном. У нас все равно ничего бы не вышло.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','От вас рыбой несет!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8600,'Орде нужна грубая кожа!','Я понял, что подгонка ножа по руке важна даже больше, чем острота лезвия. И самый тупой клинок способен порезать, если приложить нужное усилие. Правильно, |3-6($c)? Думаю, у нас не будет таких проблем, ведь наши ножи всегда хорошо заточены.$B$BНу, это не важно. У меня для тебя есть дело. Достань мне побольше грубой кожи. Она нужна, чтобы Орда как следует подготовилась к войне в Ан\'Кираже. Я не сомневаюсь, что ты отлично справишься, ага?','Принесите 10 кусков грубой кожи Доктору Серратусу, который находится на Аллее Духов в Оргриммаре.','Прекрасно, прекрасно, ты $Gпроделал:проделала; неплохую работенку, хотя некоторые из этих кож по краям обрезаны не слишком ровно. Но, без сомнений, задание выполнено, и ты получишь обещанную награду. Если вдруг раздобудешь еще прочной кожи, то тащи ее мне поскорее.','Не может же быть, чтобы срезка десяти прочных кож отняла столько времени! Может, тебе стоит наточить охотничий нож? Или я ошибся, и кожи у тебя с собой?','Вернитесь к доктору Серратусу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде нужна грубая кожа!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я понял, что подгонка ножа по руке важна даже больше, чем острота лезвия. И самый тупой клинок способен порезать, если приложить нужное усилие. Правильно, |3-6($c)? Думаю, у нас не будет таких проблем, ведь наши ножи всегда хорошо заточены.$B$BНу, это не важно. У меня для тебя есть дело. Достань мне побольше грубой кожи. Она нужна, чтобы Орда как следует подготовилась к войне в Ан\'Кираже. Я не сомневаюсь, что ты отлично справишься, ага?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 кусков грубой кожи Доктору Серратусу, который находится на Аллее Духов в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, прекрасно, ты $Gпроделал:проделала; неплохую работенку, хотя некоторые из этих кож по краям обрезаны не слишком ровно. Но, без сомнений, задание выполнено, и ты получишь обещанную награду. Если вдруг раздобудешь еще прочной кожи, то тащи ее мне поскорее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не может же быть, чтобы срезка десяти прочных кож отняла столько времени! Может, тебе стоит наточить охотничий нож? Или я ошибся, и кожи у тебя с собой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к доктору Серратусу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8601,'Орде все еще не хватает грубой кожи!','Тренировка, тренировка и еще раз тренировка. Хорошо заточенный нож и умение им пользоваться еще не раз сослужат тебе добрую службу, $N. Похоже, края этих кож стали ровнее, чем было вначале. Ты $Gкупил:купила; себе новый нож?$B$BВ любом случае, большое спасибо за потраченные силы. Твой вклад не останется незамеченным, уж будь $Gуверен:уверена;. Если вдруг сыщещь еще прочной кожи, приходи узнать, не нужна ли она мне.','Вернитесь к доктору Серратусу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает грубой кожи!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тренировка, тренировка и еще раз тренировка. Хорошо заточенный нож и умение им пользоваться еще не раз сослужат тебе добрую службу, $N. Похоже, края этих кож стали ровнее, чем было вначале. Ты $Gкупил:купила; себе новый нож?$B$BВ любом случае, большое спасибо за потраченные силы. Твой вклад не останется незамеченным, уж будь $Gуверен:уверена;. Если вдруг сыщещь еще прочной кожи, приходи узнать, не нужна ли она мне.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к доктору Серратусу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8602,'Наплечье Зовущего бурю','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!','Я изготовил это наплечье, $Gсмертный:смертная;, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.','Тебе удалось собрать все, что мне нужно?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наплечье Зовущего бурю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я изготовил это наплечье, $Gсмертный:смертная;, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать все, что мне нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8603,'Одежды оракула','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.','Вернитесь к Ветсере в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одежды оракула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ветсере в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8604,'Орде не хватает шерстяных бинтов!','Приветствую, |3-6($c). Мне поручено собирать шерстяные бинты для подготовки к войне в Ан\'Кираже. К сожалению, на поле боя солдаты не могут рассчитывать, что лекари успеют добраться сразу до всех. Поэтому мы должны уделить как можно больше внимания оказанию первой помощи.$B$BЕсли у тебя есть время, помоги мне собрать шерстяные бинты. Принеси их сюда, а я позабочусь, чтобы тебе выдали положенное вознаграждение.','Принесите 20 шерстяных бинтов целителю клана Долгий Бег на Аллею Духов Оргриммара.','Хм... Выглядит так, будто слитков столько, сколько нужно... Только не пытайся обмануть меня, $C! От этого счета у меня башка раскалывается. Пойду сложу слитки в штабель, а ты пока отправляйся и принеси еще столько же.','Ударные земснаряды представляют собой серьезную угрозу, и с ними нужно быстро бороться!','Вернитесь к целителю Выносливому Гонцу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает шерстяных бинтов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, |3-6($c). Мне поручено собирать шерстяные бинты для подготовки к войне в Ан\'Кираже. К сожалению, на поле боя солдаты не могут рассчитывать, что лекари успеют добраться сразу до всех. Поэтому мы должны уделить как можно больше внимания оказанию первой помощи.$B$BЕсли у тебя есть время, помоги мне собрать шерстяные бинты. Принеси их сюда, а я позабочусь, чтобы тебе выдали положенное вознаграждение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 шерстяных бинтов целителю клана Долгий Бег на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... Выглядит так, будто слитков столько, сколько нужно... Только не пытайся обмануть меня, $C! От этого счета у меня башка раскалывается. Пойду сложу слитки в штабель, а ты пока отправляйся и принеси еще столько же.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ударные земснаряды представляют собой серьезную угрозу, и с ними нужно быстро бороться!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к целителю Выносливому Гонцу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8605,'Орде все еще не хватает шерстяных бинтов!','Ты знаешь, что такое настоящее благородство, $N! Я прослежу, чтобы эти бинты попали в нужные руки. Прими мою благодарность и благодарность Орды.$B$BСтупай с миром и обязательно возвращайся, если у тебя будут лишние шерстяные бинты. Нам понадобится вся помощь, которая только возможна.','Вернитесь к целителю Выносливому Гонцу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает шерстяных бинтов!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты знаешь, что такое настоящее благородство, $N! Я прослежу, чтобы эти бинты попали в нужные руки. Прими мою благодарность и благодарность Орды.$B$BСтупай с миром и обязательно возвращайся, если у тебя будут лишние шерстяные бинты. Нам понадобится вся помощь, которая только возможна.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к целителю Выносливому Гонцу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8606,'Утка!','Меня посетила гениальная мысль! Вот что мы сделаем. Я насыплю в мешок камней, а вы осуществите сброс. Да, знаю, я должен доставить выкуп лично – я и доставлю, типа того.$B$B<Нарайн меряет вас взглядом.>$B$BСойдете. Берите этот тюрбан, одежду и мешок с камнями и направляйтесь к условленной точке сброса в Зимних ключах.$B$BВ этом специальном наборе все, что вам нужно. Когда они высунут нос, чтобы забрать выкуп, задайте им перцу! Будут знать, как наезжать на Нарайна!','Нарайн Причудень из Танариса хочет, чтобы вы отправились в Зимние ключи и сбросили мешок с золотом в условленной точке, указанной книгокрадами.','Возможно мы их недооценили.','Вернитесь к Нарайну Причуденю в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Утка!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня посетила гениальная мысль! Вот что мы сделаем. Я насыплю в мешок камней, а вы осуществите сброс. Да, знаю, я должен доставить выкуп лично – я и доставлю, типа того.$B$B<Нарайн меряет вас взглядом.>$B$BСойдете. Берите этот тюрбан, одежду и мешок с камнями и направляйтесь к условленной точке сброса в Зимних ключах.$B$BВ этом специальном наборе все, что вам нужно. Когда они высунут нос, чтобы забрать выкуп, задайте им перцу! Будут знать, как наезжать на Нарайна!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нарайн Причудень из Танариса хочет, чтобы вы отправились в Зимние ключи и сбросили мешок с золотом в условленной точке, указанной книгокрадами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Возможно мы их недооценили.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нарайну Причуденю в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8607,'Орде не хватает бинтов из магической ткани!','Ты действительно хочешь помочь мне в сборе материалов, за которые я отвечаю? Отлично! Бинты из магической ткани нужны мне любой ценой, я имею в виду, в буквальном смысле "любой ценой". Хорошо бы свежие, но это совершенно не обязательно. Когда добудешь их, |3-6($c), возвращайся ко мне, я прослежу, чтобы тебя соответственным образом наградили.','Принесите 20 бинтов из магической ткани госпоже Кэллоу на Аллею Духов Оргриммара.','Удивительно, но все в порядке. Возможно, я недооценила твои способности, $C. Все возможно. К тому же, задание было несложное, а награда гораздо больше, чем следует. Впрочем, не бери в голову. Если хочешь в самом деле доказать, чего стоишь, ступай и принеси еще бинтов из магической ткани.','Пожалуйста, не подведи, это поставит меня в крайне неудобное положение. Возвращайся с бинтами из магической ткани как только сможешь.','Вернитесь к госпоже Кэллоу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает бинтов из магической ткани!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты действительно хочешь помочь мне в сборе материалов, за которые я отвечаю? Отлично! Бинты из магической ткани нужны мне любой ценой, я имею в виду, в буквальном смысле "любой ценой". Хорошо бы свежие, но это совершенно не обязательно. Когда добудешь их, |3-6($c), возвращайся ко мне, я прослежу, чтобы тебя соответственным образом наградили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 бинтов из магической ткани госпоже Кэллоу на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Удивительно, но все в порядке. Возможно, я недооценила твои способности, $C. Все возможно. К тому же, задание было несложное, а награда гораздо больше, чем следует. Впрочем, не бери в голову. Если хочешь в самом деле доказать, чего стоишь, ступай и принеси еще бинтов из магической ткани.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пожалуйста, не подведи, это поставит меня в крайне неудобное положение. Возвращайся с бинтами из магической ткани как только сможешь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к госпоже Кэллоу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8608,'Орде опять не хватает бинтов из магической ткани!','Просто поразительно, $C, тебе опять все удалось! Ну, говорят, что у меня нюх на помощников. Хорошо, твой вклад не останется незамеченным и ты несоменно получишь социальные льготы соразмерно своим заслугам. А пока, я полагаю, тебе следует вернуться к сбору бинтов из магической ткани, если ты действительно хочешь доказать, чего стоишь.','Вернитесь к госпоже Кэллоу в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде опять не хватает бинтов из магической ткани!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Просто поразительно, $C, тебе опять все удалось! Ну, говорят, что у меня нюх на помощников. Хорошо, твой вклад не останется незамеченным и ты несоменно получишь социальные льготы соразмерно своим заслугам. А пока, я полагаю, тебе следует вернуться к сбору бинтов из магической ткани, если ты действительно хочешь доказать, чего стоишь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к госпоже Кэллоу в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8609,'Орде не хватает бинтов из рунической ткани!','Альянс и Орда готовятся к войне в Ан\'Кираже, идя встречными курсами. Просто удивительно, что они собираются воевать не друг с другом, а с силитидами, какая бы сила ни стояла за ними. Не менее удивительно, что обе стороны вносят свой вклад в заготовку военных ресурсов в достаточном количестве.$B$BЯ отвечаю за сбор бинтов из рунической ткани, для оказания первой помощи. Но одна я точно не справлюсь. Помоги мне, |3-6($c), я буду очень признательна.','Принесите 20 бинтов из рунической ткани каменному стражу Илистому Копыту на Аллею Духов Оргриммара.','Орда в долгу перед тобой, $C. Спасибо тебе за то, что ты для нас $сделал:сделала;, мы сохраним твои поступки в своем сердце. Я должна складировать эти бинты и посчитать, насколько мы приблизились к выполнению цели. Если получится, добудь еще бинтов из рунной ткани и возвращайся ко мне.','Достали яд?','Вернитесь к каменному стражу Илистому Копыту в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает бинтов из рунической ткани!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянс и Орда готовятся к войне в Ан\'Кираже, идя встречными курсами. Просто удивительно, что они собираются воевать не друг с другом, а с силитидами, какая бы сила ни стояла за ними. Не менее удивительно, что обе стороны вносят свой вклад в заготовку военных ресурсов в достаточном количестве.$B$BЯ отвечаю за сбор бинтов из рунической ткани, для оказания первой помощи. Но одна я точно не справлюсь. Помоги мне, |3-6($c), я буду очень признательна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 бинтов из рунической ткани каменному стражу Илистому Копыту на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Орда в долгу перед тобой, $C. Спасибо тебе за то, что ты для нас $сделал:сделала;, мы сохраним твои поступки в своем сердце. Я должна складировать эти бинты и посчитать, насколько мы приблизились к выполнению цели. Если получится, добудь еще бинтов из рунной ткани и возвращайся ко мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Достали яд?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Илистому Копыту в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8610,'Орде все еще не хватает бинтов из рунической ткани!','С твоей стороны это очень бескорыстный поступок, $N. Может быть, именно он спасет жизнь многим бойцам нашей армии в Ан\'Кираже. Орда в долгу перед тобой. Если сумеешь достать еще бинтов из рунной ткани, пожалуйста, неси их мне.','Вернитесь к каменному стражу Илистому Копыту в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает бинтов из рунической ткани!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С твоей стороны это очень бескорыстный поступок, $N. Может быть, именно он спасет жизнь многим бойцам нашей армии в Ан\'Кираже. Орда в долгу перед тобой. Если сумеешь достать еще бинтов из рунной ткани, пожалуйста, неси их мне.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к каменному стражу Илистому Копыту в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8611,'Орде не хватает постных стейков из волчатины!','Я здесь не просто так загораю, |3-6($c). Подготовка к войне – дело нешуточное! Если мы хотим передавить тараканов Ан\'Киража, надо приложить массу усилий, в том числе к заготовке провианта.$B$BМеня назначили ответственным за засолку постных стейков из волчатины. Однако не могу же я разорваться на части – бегать за волками по лесам и обеспечивать хранение и учет мяса одновременно. Так что это тебе придется добыть волчатины и приготовить ее, как надо, а потом ты принесешь ее мне. Все понятно?','О, это мясо неплохо выглядит. Сейчас я его засолю и уберу на хранение. Надеюсь, до войны оно доживет свежим.$B$BСпасибо за вклад в наше общее дело, |3-6($C). А пока – как насчет того, чтобы принести мне еще порцию стейков?','Летучие хамелеоны могут быть очень опасны, когда на них нападают. Так что смотри в оба, |3-6($R)! Тем более, опасаться приходится не только дракончиков, но и тамошних ночных эльфов.$B$BКогда наберешь нужное количество крыльев, дай мне знать, уж я в долгу не останусь!','Вернитесь к кровостражу Сыросмолле в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает постных стейков из волчатины!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я здесь не просто так загораю, |3-6($c). Подготовка к войне – дело нешуточное! Если мы хотим передавить тараканов Ан\'Киража, надо приложить массу усилий, в том числе к заготовке провианта.$B$BМеня назначили ответственным за засолку постных стейков из волчатины. Однако не могу же я разорваться на части – бегать за волками по лесам и обеспечивать хранение и учет мяса одновременно. Так что это тебе придется добыть волчатины и приготовить ее, как надо, а потом ты принесешь ее мне. Все понятно?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, это мясо неплохо выглядит. Сейчас я его засолю и уберу на хранение. Надеюсь, до войны оно доживет свежим.$B$BСпасибо за вклад в наше общее дело, |3-6($C). А пока – как насчет того, чтобы принести мне еще порцию стейков?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Летучие хамелеоны могут быть очень опасны, когда на них нападают. Так что смотри в оба, |3-6($R)! Тем более, опасаться приходится не только дракончиков, но и тамошних ночных эльфов.$B$BКогда наберешь нужное количество крыльев, дай мне знать, уж я в долгу не останусь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровостражу Сыросмолле в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8612,'Орде все еще не хватает постных стейков из волчатины!','Вернитесь к кровостражу Сыросмолле в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает постных стейков из волчатины!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кровостражу Сыросмолле в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8613,'Орде не хватает пятнистого желтохвоста!','Отличный денек для рыбалки, ага, дружище? Эта ты правильно думаешь, мне б рыбка ого как пригодилась. Орде нужна чертова куча пятнистого желтохвоста. Говорят, мы будем его хавать, когда отправимся в Ан\'Кираж рубиться. Так я ответил, что всегда готов служить, ага. Тока мне, конечно, помощь понадобится. Ты как насчет помочь, |3-6($c)?','Принесите 20 пятнистых желтохвостов Линдо Рыболову на Аллею Духов Оргриммара.','О, это мясо неплохо выглядит. Сейчас я его засолю и уберу на хранение. Надеюсь, до войны оно доживет свежим.$B$BСпасибо за вклад в наше общее дело, |3-6($C). А пока – как насчет того, чтобы принести мне еще порцию стейков?','Летучие хамелеоны могут быть очень опасны, когда на них нападают. Так что смотри в оба, |3-6($R)! Тем более, опасаться приходится не только дракончиков, но и тамошних ночных эльфов.$B$BКогда наберешь нужное количество крыльев, дай мне знать, уж я в долгу не останусь!','Вернитесь к рыболову Лин\'до в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает пятнистого желтохвоста!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отличный денек для рыбалки, ага, дружище? Эта ты правильно думаешь, мне б рыбка ого как пригодилась. Орде нужна чертова куча пятнистого желтохвоста. Говорят, мы будем его хавать, когда отправимся в Ан\'Кираж рубиться. Так я ответил, что всегда готов служить, ага. Тока мне, конечно, помощь понадобится. Ты как насчет помочь, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 пятнистых желтохвостов Линдо Рыболову на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, это мясо неплохо выглядит. Сейчас я его засолю и уберу на хранение. Надеюсь, до войны оно доживет свежим.$B$BСпасибо за вклад в наше общее дело, |3-6($C). А пока – как насчет того, чтобы принести мне еще порцию стейков?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Летучие хамелеоны могут быть очень опасны, когда на них нападают. Так что смотри в оба, |3-6($R)! Тем более, опасаться приходится не только дракончиков, но и тамошних ночных эльфов.$B$BКогда наберешь нужное количество крыльев, дай мне знать, уж я в долгу не останусь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыболову Лин\'до в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8614,'Орде все еще не хватает пятнистого желтохвоста!','Лучший улов сезона, $N! Отличная работенка. Вот это я понимаю, никаких костей в рыбе. За такого желтохвоста всякий боец спасибо скажет. Наловишь еще, тащи сюда обзательно.','Вернитесь к рыболову Лин\'до в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает пятнистого желтохвоста!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лучший улов сезона, $N! Отличная работенка. Вот это я понимаю, никаких костей в рыбе. За такого желтохвоста всякий боец спасибо скажет. Наловишь еще, тащи сюда обзательно.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рыболову Лин\'до в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8615,'Орде не хватает печеного лосося!','Подготовка к войне в Ан\'Кираже – дело нешуточное, |3-6($c). Чтобы изготовить оружие, нужно железо, а чтобы крепко держать его в руках – провиант. Если ты не поешь пару дней, хватит ли у тебя сил поднять боевой топор, когда придет время для битвы?$B$BИменно поэтому сбор провизии не менее важен, чем все остальное. Я занимаюсь заготовками печеного лосося. Он хорошо хранится и обладает отличными питательными свойствами. Ну что, поможешь мне, |3-6($c)?','Принесите 20 печеных лососей повару Острой Шпоре на Аллею Духов Оргриммара.','О, это мясо неплохо выглядит. Сейчас я его засолю и уберу на хранение. Надеюсь, до войны оно доживет свежим.$B$BСпасибо за вклад в наше общее дело, |3-6($C). А пока – как насчет того, чтобы принести мне еще порцию стейков?','Летучие хамелеоны могут быть очень опасны, когда на них нападают. Так что смотри в оба, |3-6($R)! Тем более, опасаться приходится не только дракончиков, но и тамошних ночных эльфов.$B$BКогда наберешь нужное количество крыльев, дай мне знать, уж я в долгу не останусь!','Вернитесь к вождю Острому Когтю в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает печеного лосося!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подготовка к войне в Ан\'Кираже – дело нешуточное, |3-6($c). Чтобы изготовить оружие, нужно железо, а чтобы крепко держать его в руках – провиант. Если ты не поешь пару дней, хватит ли у тебя сил поднять боевой топор, когда придет время для битвы?$B$BИменно поэтому сбор провизии не менее важен, чем все остальное. Я занимаюсь заготовками печеного лосося. Он хорошо хранится и обладает отличными питательными свойствами. Ну что, поможешь мне, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 20 печеных лососей повару Острой Шпоре на Аллею Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, это мясо неплохо выглядит. Сейчас я его засолю и уберу на хранение. Надеюсь, до войны оно доживет свежим.$B$BСпасибо за вклад в наше общее дело, |3-6($C). А пока – как насчет того, чтобы принести мне еще порцию стейков?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Летучие хамелеоны могут быть очень опасны, когда на них нападают. Так что смотри в оба, |3-6($R)! Тем более, опасаться приходится не только дракончиков, но и тамошних ночных эльфов.$B$BКогда наберешь нужное количество крыльев, дай мне знать, уж я в долгу не останусь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Острому Когтю в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8616,'Орде все еще не хватает печеного лосося!','Вернитесь к вождю Острому Когтю в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает печеного лосося!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Острому Когтю в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8617,'Орде не хватает опаленного вулканического камня!','Пришло время и тебе поучаствовать в нашей подготовке войны в Ан\'Кираже, |3-6($c). Прошли деньки, когда можно было беззаботно валяться на солнышке. Нынче каждый должен встать под знамена Орды и Вождя! А я, в отличие от нашего вождя, добросердечием не страдаю, уж будь $gспокоен:спокойна;.$B$BТы $gдолжен:должна; собрать военные силы своей гильдии (если состоишь в таковой) и проникнуть в Огненные Недра. Мне нужны оплавленные вулканические камни, которые можно обнаружить у тамошних обитателей. Собери столько камней, сколько сможешь, и возвращайся обратно.','Принесите 50 оплавленных вулканических камней генералу Зогу в Дуротар.','Вернитесь к генералу Зогу в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде не хватает опаленного вулканического камня!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время и тебе поучаствовать в нашей подготовке войны в Ан\'Кираже, |3-6($c). Прошли деньки, когда можно было беззаботно валяться на солнышке. Нынче каждый должен встать под знамена Орды и Вождя! А я, в отличие от нашего вождя, добросердечием не страдаю, уж будь $gспокоен:спокойна;.$B$BТы $gдолжен:должна; собрать военные силы своей гильдии (если состоишь в таковой) и проникнуть в Огненные Недра. Мне нужны оплавленные вулканические камни, которые можно обнаружить у тамошних обитателей. Собери столько камней, сколько сможешь, и возвращайся обратно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 50 оплавленных вулканических камней генералу Зогу в Дуротар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Зогу в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8618,'Орде все еще не хватает опаленных вулканических камней!','Вернитесь к генералу Зогу в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орде все еще не хватает опаленных вулканических камней!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Зогу в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8619,'Предок Утренний Туман','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предок Утренний Туман',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8620,'"Драконий язык для чайников"','Надо было раньше сообразить! Мой архивраг, Доктор Жло, взялся за старое! А теперь, благодаря вашему провалу в Зимних ключах, Доктор Жло уничтожил мою книгу! И как теперь вы будете спасать мир, герой?$B$BИз полученной мной записки я узнал, что "Драконий язык для чайников: том II" разорван на 8 частей и разбросан по ветру! Если вы как-нибудь умудритесь найти пропавшие главы, при помощи этого магического переплета сшейте их снова и возвращайтесь ко мне.','Найдите 8 утраченных глав из книги "Драконий язык для чайников" и соберите их при помощи магического книжного переплета. Принесите полную книгу "Драконий язык для чайников: том II" Нарайну Причуденю в Танарис.','Фантастика! Поверить не могу что вы прошли через барьер! Вы часом не машина? Будь я на вашем месте – да горел бы этот мир синим огнем!$B$BСнимаю перед вами тюрбан $Gсэр:мисс;. И тоже доброе дело не должно остаться без награды.','Я вот как положил одну ногу на другую... эй, где все 8 частей книги?','Вернитесь к Нарайну Причуденю в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Драконий язык для чайников"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо было раньше сообразить! Мой архивраг, Доктор Жло, взялся за старое! А теперь, благодаря вашему провалу в Зимних ключах, Доктор Жло уничтожил мою книгу! И как теперь вы будете спасать мир, герой?$B$BИз полученной мной записки я узнал, что "Драконий язык для чайников: том II" разорван на 8 частей и разбросан по ветру! Если вы как-нибудь умудритесь найти пропавшие главы, при помощи этого магического переплета сшейте их снова и возвращайтесь ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 8 утраченных глав из книги "Драконий язык для чайников" и соберите их при помощи магического книжного переплета. Принесите полную книгу "Драконий язык для чайников: том II" Нарайну Причуденю в Танарис.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фантастика! Поверить не могу что вы прошли через барьер! Вы часом не машина? Будь я на вашем месте – да горел бы этот мир синим огнем!$B$BСнимаю перед вами тюрбан $Gсэр:мисс;. И тоже доброе дело не должно остаться без награды.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я вот как положил одну ногу на другую... эй, где все 8 частей книги?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нарайну Причуденю в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8621,'Прочные ботинки Зовущего бурю','Тебе удалось добыть то, о чем я просил, $N?','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прочные ботинки Зовущего бурю',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть то, о чем я просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8622,'Хауберк Зовущего бурю','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.','Принесите панцирь древнего бога, 2 идола мудреца, 5 серебряных и 5 костяных скарабеев Ветсере в Ан\'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.','Тебе удалось добыть то, о чем я просил, $N?','Вернитесь к Ветсере в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хауберк Зовущего бурю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите панцирь древнего бога, 2 идола мудреца, 5 серебряных и 5 костяных скарабеев Ветсере в Ан\'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть то, о чем я просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ветсере в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8623,'Диадема Зовущего бурю','Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан\'Кираж будут служить нам.$B$BПринеси то, что мне нужно, $n. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.','Тебе удалось добыть то, о чем я просил, $N?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Диадема Зовущего бурю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан\'Кираж будут служить нам.$B$BПринеси то, что мне нужно, $n. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть то, о чем я просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8624,'Поножи Зовущего бурю','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.','Принесите шкуру гигантского песчаного червя, 2 идола Борьбы, 5 бронзовых скарабеев и 5 скарабеев из бивневой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.','Тебе удалось добыть то, о чем я просил, $N?','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поножи Зовущего бурю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите шкуру гигантского песчаного червя, 2 идола Борьбы, 5 бронзовых скарабеев и 5 скарабеев из бивневой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть то, о чем я просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8625,'Наплечные пластины таинства','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!','Я изготовила это наплечье, $Gсмертный:смертная;, из принесенных тобой вещей и панцирей поверженных киражи. Тебя они защитят, а сердца врагов их вид наполнит ужасом.','Тебе удалось собрать все, что мне нужно?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наплечные пластины таинства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я изготовила это наплечье, $Gсмертный:смертная;, из принесенных тобой вещей и панцирей поверженных киражи. Тебя они защитят, а сердца врагов их вид наполнит ужасом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать все, что мне нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8626,'Прочные ботинки бойца','Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.','Принесите киражские наручники властности, 2 идола Жизни, 5 каменных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прочные ботинки бойца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите киражские наручники властности, 2 идола Жизни, 5 каменных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8627,'Кираса Мстителя','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.','Вернитесь к Ветсере в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кираса Мстителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ветсере в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (8628,'Корона Мстителя','Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан\'Кираж будут служить нам.$B$BПринеси то, что мне нужно, $n. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корона Мстителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Императоры-близнецы... Их непрестанный шепот в моих ушах потихоньку сводит меня с ума. Они смеются надо мной, зная, что я не сумею вступить в их владения, чтобы спасти моего брата Аригоса.$B$BЯ вижу их безобразные головы, увенчанные могущественными коронами. Но я отомщу им... эти символы власти Ан\'Кираж будут служить нам.$B$BПринеси то, что мне нужно, $n. Взамен я отдам тебе головной убор, не имеющий себе равных по силе.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8629,'Набедренники Мстителя','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.','Принесите шкуру гигантского песчаного червя, два идола Борьбы, пять бронзовых скарабеев и пять скарабеев из бивневой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.','Да... Эту шкуру невозможно пробить почти ничем. Если добавить самые прочные куски панцирей киражи, убитых нами по дороге сюда, из нее получится великолепный доспех. Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан\'Киража.','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Набедренники Мстителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите шкуру гигантского песчаного червя, два идола Борьбы, пять бронзовых скарабеев и пять скарабеев из бивневой кости Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... Эту шкуру невозможно пробить почти ничем. Если добавить самые прочные куски панцирей киражи, убитых нами по дороге сюда, из нее получится великолепный доспех. Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан\'Киража.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8630,'Наплечье Мстителя','Тебе удалось собрать все, что мне нужно?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наплечье Мстителя',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать все, что мне нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8631,'Поножи таинства','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.','Принесите целую шкуру Оуро, 2 идола Мудреца, 5 серебряных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.','Тебе удалось добыть то, о чем я просил, $N?','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поножи таинства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите целую шкуру Оуро, 2 идола Мудреца, 5 серебряных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть то, о чем я просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8632,'Венец таинства','Тебе удалось одержать победу! Императоры-близнецы прекратили шептаться в моей голове.$B$BПрими же от меня награду. Один вид этой вещи вселит ужас в сердца киражи... Она напомнит им, что самые могучие их предводители погибли от рук смертных.','Ты $Gпринес:принесла; мне то, о чем я просила, $N?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Венец таинства',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось одержать победу! Императоры-близнецы прекратили шептаться в моей голове.$B$BПрими же от меня награду. Один вид этой вещи вселит ужас в сердца киражи... Она напомнит им, что самые могучие их предводители погибли от рук смертных.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне то, о чем я просила, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8633,'Одеяния таинства','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.','Принесите чешую древнего бога, 2 идола Солнца, 5 золотых и 5 глиняных скарабеев Ветсере в Ан\'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.','Я не ожидала, что ты сумеешь вернуться $Gживым:живой;, $N.$B$BТебе удалось исполнить то, что не под силу многим бессмертным.$B$BУбив К\'Туна, ты не только $Gспас:спасла; Азерот, ты $Gпоколоебал:поколебала; чаши космических весов, на которых лежат события, далеко превосходящие твое понимание.$B$BПрими эти одежды как символ великой славы и знак великого груза, который ты $Gвзвалил:взвалила; на себя своим поступком.$B$BБыть может, они помогут преодолеть тяготы пути, который отныне лежит перед тобой, богоубийца.','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.','Вернитесь к Ветсере в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одеяния таинства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите чешую древнего бога, 2 идола Солнца, 5 золотых и 5 глиняных скарабеев Ветсере в Ан\'Кираж. Кроме того, необходимо заслужить как минимум уважительное отношение рода Ноздорму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не ожидала, что ты сумеешь вернуться $Gживым:живой;, $N.$B$BТебе удалось исполнить то, что не под силу многим бессмертным.$B$BУбив К\'Туна, ты не только $Gспас:спасла; Азерот, ты $Gпоколоебал:поколебала; чаши космических весов, на которых лежат события, далеко превосходящие твое понимание.$B$BПрими эти одежды как символ великой славы и знак великого груза, который ты $Gвзвалил:взвалила; на себя своим поступком.$B$BБыть может, они помогут преодолеть тяготы пути, который отныне лежит перед тобой, богоубийца.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ветсере в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8634,'Сапоги таинства','Отличная работа, $N. Ты $Gдоказал:доказала; что ты не $Gпростой:простая; $Gсмертный:смертная;.$B$BВозьми это, они помогут тебя в сражении против этих мерзких Киражей.','Тебе удалось добыть то, о чем я просил, $N?','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сапоги таинства',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Ты $Gдоказал:доказала; что ты не $Gпростой:простая; $Gсмертный:смертная;.$B$BВозьми это, они помогут тебя в сражении против этих мерзких Киражей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть то, о чем я просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8635,'Предок Камнещеп','Легенды растут из семени давних битв. Ты живешь в эпоху героев, $gюноша:девушка;. Да укоренится твоя легенда и да принесет она обильный плод.$B$BВсего тебе наилучшего, $n. Прими от меня этот знак...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предок Камнещеп',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Легенды растут из семени давних битв. Ты живешь в эпоху героев, $gюноша:девушка;. Да укоренится твоя легенда и да принесет она обильный плод.$B$BВсего тебе наилучшего, $n. Прими от меня этот знак...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8636,'Предок Скалогром','Плоть, материя жизни, смертна и рано или поздно обратится в прах. Дух же вечен. Всего наилучшего тебе, $n. Прими этот знак...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предок Скалогром',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Плоть, материя жизни, смертна и рано или поздно обратится в прах. Дух же вечен. Всего наилучшего тебе, $n. Прими этот знак...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8637,'Сапоги торговца смертью','Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.','Принесите киражские наручники властности, 2 идола Борьбы, 5 хрустальных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.','Отличная работа, $N. Ты $Gдоказал:доказала; что ты не $Gпростой:простая; $Gсмертный:смертная;.$B$BВозьми это, они помогут тебя в сражении против этих мерзких Киражей.','Тебе удалось добыть то, о чем я просил, $N?','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сапоги торговца смертью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древняя киражская магия исполнена небывалой силы. Cамые могущественные киражи владели предметами такой мощи, что они были способны остановить даже дракона.$B$BПринеси мне киражские наручники властности и еще несколько компонентов, и я создам для тебя потрясающие сапоги.$B$BУвидишь, насколько они окажутся полезны в схватке с врагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите киражские наручники властности, 2 идола Борьбы, 5 хрустальных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум равнодушное отношение рода Ноздорму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Ты $Gдоказал:доказала; что ты не $Gпростой:простая; $Gсмертный:смертная;.$B$BВозьми это, они помогут тебя в сражении против этих мерзких Киражей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть то, о чем я просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8638,'Жилет торговца смертью','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.','Я не ожидала, что ты сумеешь вернуться $Gживым:живой; $N.$B$BТебе удалось исполнить то, что не под силу многим бессмертным.$B$BУбив К\'Туна, ты не только $Gспас:спасла; Азерот, ты $Gпоколоебал:поколебала; чаши космических весов, на которых лежат события, далеко превосходящие твое понимание.$B$BПрими эти одежды как символ великой славы и знак великого груза, который ты $Gвзвалил:взвалила; на себя своим поступком.$B$BБыть может, они помогут преодолеть тяготы пути, который отныне лежит перед тобой, богоубийца.','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.','Вернитесь к Ветсере в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жилет торговца смертью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не ожидала, что ты сумеешь вернуться $Gживым:живой; $N.$B$BТебе удалось исполнить то, что не под силу многим бессмертным.$B$BУбив К\'Туна, ты не только $Gспас:спасла; Азерот, ты $Gпоколоебал:поколебала; чаши космических весов, на которых лежат события, далеко превосходящие твое понимание.$B$BПрими эти одежды как символ великой славы и знак великого груза, который ты $Gвзвалил:взвалила; на себя своим поступком.$B$BБыть может, они помогут преодолеть тяготы пути, который отныне лежит перед тобой, богоубийца.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ветсере в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8639,'Шлем торговца смертью','Тебе удалось одержать победу! Императоры-близнецы прекратили шептаться в моей голове.$B$BПрими же от меня награду. Один вид этой вещи вселит ужас в сердца киражи... Она напомнит им, что самые могучие их предводители погибли от рук смертных.','Ты $Gпринес:принесла; мне то, о чем я просила, $N?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шлем торговца смертью',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось одержать победу! Императоры-близнецы прекратили шептаться в моей голове.$B$BПрими же от меня награду. Один вид этой вещи вселит ужас в сердца киражи... Она напомнит им, что самые могучие их предводители погибли от рук смертных.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне то, о чем я просила, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8640,'Поножи торговца смертью','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.','Принесите целую шкуру Оуро, 2 идола Ночи, 5 каменных и 5 хрустальных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.','Тебе удалось добыть то, о чем я просил, $N?','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поножи торговца смертью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите целую шкуру Оуро, 2 идола Ночи, 5 каменных и 5 хрустальных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть то, о чем я просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8641,'Наплеч торговца смертью','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!','Я изготовил это наплечье, $Gсмертный:смертная;, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.','Тебе удалось собрать все, что мне нужно?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наплеч торговца смертью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я изготовил это наплечье, $Gсмертный:смертная;, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать все, что мне нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
