INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8655,'Наголенники Мстителя','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наголенники Мстителя',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8656,'Хауберк бойца','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.','Вернитесь к Ветсере в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хауберк бойца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ветсере в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8657,'Диадема бойца','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Диадема бойца',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8658,'Поножи бойца','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.','Принесите шкуру гигантского песчаного червя, 2 идола Солнца, 5 серебряных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.','Да... Эту шкуру невозможно пробить почти ничем. Если добавить самые прочные куски панцирей киражи, убитых нами по дороге сюда, из нее получится великолепный доспех. Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан\'Киража.','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поножи бойца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите шкуру гигантского песчаного червя, 2 идола Солнца, 5 серебряных и 5 костяных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... Эту шкуру невозможно пробить почти ничем. Если добавить самые прочные куски панцирей киражи, убитых нами по дороге сюда, из нее получится великолепный доспех. Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан\'Киража.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8659,'Наплечье бойца','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!','Тебе удалось собрать все, что мне нужно?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наплечье бойца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать все, что мне нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
