INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8663,'Брюки Призывателя Рока','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.','Принесите шкуру гигантского песчаного червя, 2 идола Возрождения, 5 золотых и 5 глиняных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.','Да... Эту шкуру невозможно пробить почти ничем. Если добавить самые прочные куски панцирей киражи, убитых нами по дороге сюда, из нее получится великолепный доспех. Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан\'Киража.','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брюки Призывателя Рока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите шкуру гигантского песчаного червя, 2 идола Возрождения, 5 золотых и 5 глиняных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... Эту шкуру невозможно пробить почти ничем. Если добавить самые прочные куски панцирей киражи, убитых нами по дороге сюда, из нее получится великолепный доспех. Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан\'Киража.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8664,'Оплечье Призывателя Рока','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!','Тебе удалось собрать все, что мне нужно?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оплечье Призывателя Рока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать все, что мне нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8665,'Сапоги сотворения','Отличная работа, $N. Ты $Gдоказал:доказала; что ты не $Gпростой:простая; $Gсмертный:смертная;.$B$BВозьми это, они помогут тебя в сражении против этих мерзких Киражей.','Тебе удалось добыть то, о чем я просил, $N?','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сапоги сотворения',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Ты $Gдоказал:доказала; что ты не $Gпростой:простая; $Gсмертный:смертная;.$B$BВозьми это, они помогут тебя в сражении против этих мерзких Киражей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть то, о чем я просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8666,'Жилет сотворения','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.','Я не ожидала, что ты сумеешь вернуться $Gживым:живой; $N.$B$BТебе удалось исполнить то, что не под силу многим бессмертным.$B$BУбив К\'Туна, ты не только $Gспас:спасла; Азерот, ты $Gпоколоебал:поколебала; чаши космических весов, на которых лежат события, далеко превосходящие твое понимание.$B$BПрими эти одежды как символ великой славы и знак великого груза, который ты $Gвзвалил:взвалила; на себя своим поступком.$B$BБыть может, они помогут преодолеть тяготы пути, который отныне лежит перед тобой, богоубийца.','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.','Вернитесь к Ветсере в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жилет сотворения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Древний бог, о котором лучше вслух не упоминать, медленно пробуждается от своего сна в Ан\'Кираже. Ужасная судьба, которая ждет Азерот в случае его пробуждения, – вопрос лишь нескольких дней... или нескольких лет. Для существа, обладающего подобной мощью, время не имеет значения.$B$BВстанут звезды подходящим образом – и ярость его обрушится на живущих, подобно плети. Тебе следует найти его и положить конец его существованию, пока он не пробудился.$B$BКогда ты сделаешь это, принеси мне кусок его панциря. Взамен я дам тебе броню, подобной которой не владел еще никто из смертных. Броню, достойную убийцы бога.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не ожидала, что ты сумеешь вернуться $Gживым:живой; $N.$B$BТебе удалось исполнить то, что не под силу многим бессмертным.$B$BУбив К\'Туна, ты не только $Gспас:спасла; Азерот, ты $Gпоколоебал:поколебала; чаши космических весов, на которых лежат события, далеко превосходящие твое понимание.$B$BПрими эти одежды как символ великой славы и знак великого груза, который ты $Gвзвалил:взвалила; на себя своим поступком.$B$BБыть может, они помогут преодолеть тяготы пути, который отныне лежит перед тобой, богоубийца.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','К\'Тун, внушающий ужас всему живому, дремлет в глубинах Ан\'Киража в ожидании пробуждения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ветсере в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8667,'Шлем сотворения','Тебе удалось одержать победу! Императоры-близнецы прекратили шептаться в моей голове.$B$BПрими же от меня награду. Один вид этой вещи вселит ужас в сердца киражи... Она напомнит им, что самые могучие их предводители погибли от рук смертных.','Ты $Gпринес:принесла; мне то, о чем я просила, $N?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шлем сотворения',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось одержать победу! Императоры-близнецы прекратили шептаться в моей голове.$B$BПрими же от меня награду. Один вид этой вещи вселит ужас в сердца киражи... Она напомнит им, что самые могучие их предводители погибли от рук смертных.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне то, о чем я просила, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8668,'Брюки сотворения','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.','Принесите шкуру гигантского песчаного червя, 2 идола Войны, 5 каменных и 5 хрустальных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.','Да... Эту шкуру невозможно пробить почти ничем. Если добавить самые прочные куски панцирей киражи, убитых нами по дороге сюда, из нее получится великолепный доспех. Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан\'Киража.','Ты $Gпринес:принесла; не обходимые мне компоненты, $N?','Вернитесь к Кандостразу в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Брюки сотворения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь доказать нам, что тебе можно доверять, $gсмертный:смертная;? Ну хорошо. Возможно, и тебе удастся извлечь из этого пользу.$B$BСлушай. Есть существо, обладающее легендарной силой. Это древний песчаный червь Оуро. Говорят, его создал сам древний бог, в насмешку над всеми остальными формами жизни.$B$BШкура у этого червя просто невероятная. Она такая толстая, что ее невозможно пробить, но при этом такая гибкая, что позволяет червю перемещаться с непостижимой скоростью и изяществом.$B$BПринеси мне шкуру Оуро и еще ряд компонентов, и я создам для тебя поножи, обладающие огромной силой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите шкуру гигантского песчаного червя, 2 идола Войны, 5 каменных и 5 хрустальных скарабеев Кандострасу в Ан\'Кираж. Кроме того, необходимо заслужить как минимум дружеское отношение рода Ноздорму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... Эту шкуру невозможно пробить почти ничем. Если добавить самые прочные куски панцирей киражи, убитых нами по дороге сюда, из нее получится великолепный доспех. Пусть он защитит тебя при встрече с невообразимыми ужасами, что ожидают внутри Ан\'Киража.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; не обходимые мне компоненты, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кандостразу в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8669,'Наплечные пластины сотворения','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!','Я изготовил это наплечье, $Gсмертный:смертная;, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.','Тебе удалось собрать все, что мне нужно?','Вернитесь к Андоргос в Ан\'Кираж.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наплечные пластины сотворения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас говорят, что вычурные наплечные доспехи, которые носят смертные, были изначально созданы в подражание крыльям драконов.$B$BПринеси мне наручники, принадлежащие киражским правителям, и я сделаю из них наплечье еще более устрашающее, чем крылья самого Нефариана!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я изготовил это наплечье, $Gсмертный:смертная;, из принесенных тобой вещей и панцирей поверженных киражей. Тебя они защитят, а сердца врагов их вид наполнит ужасом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать все, что мне нужно?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андоргос в Ан\'Кираж.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8670,'Предок Рунический Тотем','Жизнь так и кипит в тебе, $gюный:юная; |3-6($c). Я принимаю твою дань уважения. Возьми взамен этот знак...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предок Рунический Тотем',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жизнь так и кипит в тебе, $gюный:юная; |3-6($c). Я принимаю твою дань уважения. Возьми взамен этот знак...',`offerrewardtext_loc8`);
