INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8687,'Цель: копатели из Улья Зора','Мы вызвали подкрепление для сражения у Улья Зора. Твоя задача – убить как можно больше копателей. Выполнив задание, отчитайся командиру Мар\'алиту.','Убейте 30 копателей из Улья Зора и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу VII.','Отличная работа, $N. Без копаталей силитидам придется нелегко. Кто будет восстанавливать строение улья? Думаю, ты хочешь получить новое задание.','Ты хочешь что-то сказать, $C?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: копатели из Улья Зора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы вызвали подкрепление для сражения у Улья Зора. Твоя задача – убить как можно больше копателей. Выполнив задание, отчитайся командиру Мар\'алиту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 копателей из Улья Зора и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу VII.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Без копаталей силитидам придется нелегко. Кто будет восстанавливать строение улья? Думаю, ты хочешь получить новое задание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь что-то сказать, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8688,'Предок Вестник Ветров','В небесах, в бессчетных созвездиях, записана разгадка всех наших земных тайн. Смогут ли мудрые – и удачливые – обратить взор к небесной тверди и узнать правду?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предок Вестник Ветров',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В небесах, в бессчетных созвездиях, записана разгадка всех наших земных тайн. Смогут ли мудрые – и удачливые – обратить взор к небесной тверди и узнать правду?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8689,'Накидка бесконечной мудрости','Я рад слышать, что ты помогаешь нам в нападении на Ан\'Кираж, $n. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.$B$BМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.$B$BУвидишь, эта вещь тебя не разочарует.','Принесите киражскую воинскую пелерину, 2 яшмовых идола, 5 золотых и 5 глиняных скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.','О да... Эта пелерина безукоризненна.$B$BВозьми ее, $N. Пусть она защитит тебя от нечистой магии кираи.','Ты $Gпринес:принесла; мне материалы для плаща, $N?','Вернитесь к Кейлу Стремительному Когтю в Улей Аши, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Накидка бесконечной мудрости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рад слышать, что ты помогаешь нам в нападении на Ан\'Кираж, $n. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.$B$BМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.$B$BУвидишь, эта вещь тебя не разочарует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите киражскую воинскую пелерину, 2 яшмовых идола, 5 золотых и 5 глиняных скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да... Эта пелерина безукоризненна.$B$BВозьми ее, $N. Пусть она защитит тебя от нечистой магии кираи.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне материалы для плаща, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кейлу Стремительному Когтю в Улей Аши, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8690,'Плащ надвигающейся бури','Я рад слышать, что ты помогаешь нам в нападении на Ан\'Кираж, $n. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.$B$BМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.$B$BУвидишь, эта вещь тебя не разочарует.','Принесите киражскую царскую пелерину, 2 обсидиановых идола, 5 глиняных и 5 золотых скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.','Вернитесь к Кейлу Стремительному Когтю в Улей Аши, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плащ надвигающейся бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рад слышать, что ты помогаешь нам в нападении на Ан\'Кираж, $n. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.$B$BМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.$B$BУвидишь, эта вещь тебя не разочарует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите киражскую царскую пелерину, 2 обсидиановых идола, 5 глиняных и 5 золотых скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кейлу Стремительному Когтю в Улей Аши, что в Силитусе.',`completedtext_loc8`);
