INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8696,'Плащ незримого пути','Я рад слышать, что ты помогаешь нам в нападении на Ан\'Кираж, $n. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.$B$BМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.$B$BУвидишь, эта вещь тебя не разочарует.','Принесите киражскую царскую пелерину, 2 лучистых идола, 5 каменных и 5 хрустальных скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.','О да... Эта пелерина безукоризненна.$B$BВозьми ее, $N. Пусть она защитит тебя от нечистой магии кираи.','Ты $Gпринес:принесла; мне материалы для плаща, $N?','Вернитесь к Кейлу Стремительному Когтю в Улей Аши, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плащ незримого пути',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рад слышать, что ты помогаешь нам в нападении на Ан\'Кираж, $n. В благодарность я бы хотел сделать для тебя одну вещь, которая защитит тебя от врагов.$B$BМне понадобится киражская накидка – я смогу подогнать ее под твой размер. Для застежек мне понадобятся идолы и скарабеи.$B$BУвидишь, эта вещь тебя не разочарует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите киражскую царскую пелерину, 2 лучистых идола, 5 каменных и 5 хрустальных скарабеев Кейлу Стремительному Когтю в Силитус. Кроме того, необходимо заслужить как минимум почтительное отношение Круга Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да... Эта пелерина безукоризненна.$B$BВозьми ее, $N. Пусть она защитит тебя от нечистой магии кираи.',`offerrewardtext_loc8`), `requestitems