INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8697,'Кольцо бесконечной мудрости','Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности. Однако считается, что если заменить пораженные скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастет еще больше.$B$BКамни, украшающие киражских идолов, вполне подойдут – они отменного качества.$B$BПринеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, |3-6($c).','Принесите киражское церемониальное кольцо, 2 обсидиановых идола, 5 серебряных и 5 костяных скарабеев Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария.','Я заменю камень в этом кольце. Увидишь, это сделает его эффективность куда более... приемлемой.','Ты $Gпринес:принесла; мне кольцо и материалы, $N?','Вернитесь к призывательнице ветров Йессендре в Ан\'Кираж, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо бесконечной мудрости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышала, что кольца, которые носят киражские лейтенанты, дают им невероятные способности. Однако считается, что если заменить пораженные скверной драгоценные камни, вставленные в оправу, на более чистые, мощь колец возрастет еще больше.$B$BКамни, украшающие киражских идолов, вполне подойдут – они отменного качества.$B$BПринеси мне этих идолов и кольцо одного из лейтенантов, и я создам для тебя могущественный талисман, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите киражское церемониальное кольцо, 2 обсидиановых идола, 5 серебряных и 5 костяных скарабеев Зовущей Йессендре в Силитус. Кроме того, необходимо заслужить как минимум уважительное отношение Круга Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я заменю камень в этом кольце. Увидишь, это сделает его эффективность куда более... приемлемой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне кольцо и материалы, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывательнице ветров Йессендре в Ан\'Кираж, что в Силитусе.',`completedtext_loc8`);
