INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8713,'Предок Песнь Звезд','В небесах, в бессчетных созвездиях, скрыта разгадка всех наших земных тайн. Смогут ли мудрые и удачливые обратить взор к небесной тверди и узнать правду?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предок Песнь Звезд',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В небесах, в бессчетных созвездиях, скрыта разгадка всех наших земных тайн. Смогут ли мудрые и удачливые обратить взор к небесной тверди и узнать правду?',`offerrewardtext_loc8`);
