INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8728,'Хорошая новость и плохая новость','Что же, это оказалось дольше, чем я думал. Давай-ка посмотрим, что написано в этой книге.$B$B*Нарайн молча читает книгу, периодически что-то бормоча себе под нос.*$B$BХорошая новость – я на 99% уверен, что смогу сделать арканитовый буек, который будет работать согласно вашим требованиям. А вот это полностью зависит от плохих новостей.$B$BА плохие новости заключаются в том, что мне понадобится куча арканита, элементиевой руды и редких самоцветов.$B$BПринесите мне все, что надо, и я сделаю буек.','Нарайн Причудень и Танариса хочет, чтобы вы принесли ему 20 арканитовых слитков, 10 кусков элементиевой руды, 10 азеротских бриллиантов и 10 синих сапфиров.','Сделка есть сделка. Я очень надеюсь, что ты знаешь, во что ввязываешься, $N. Чтобы порыбачить, придется пройти через очень много проблем.','Арканитовые буйки сами собой не делаются, $N. НЕТ, денег взаймы не дам.','Вернитесь к Нарайну Причудню в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хорошая новость и плохая новость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что же, это оказалось дольше, чем я думал. Давай-ка посмотрим, что написано в этой книге.$B$B*Нарайн молча читает книгу, периодически что-то бормоча себе под нос.*$B$BХорошая новость – я на 99% уверен, что смогу сделать арканитовый буек, который будет работать согласно вашим требованиям. А вот это полностью зависит от плохих новостей.$B$BА плохие новости заключаются в том, что мне понадобится куча арканита, элементиевой руды и редких самоцветов.$B$BПринесите мне все, что надо, и я сделаю буек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нарайн Причудень и Танариса хочет, чтобы вы принесли ему 20 арканитовых слитков, 10 кусков элементиевой руды, 10 азеротских бриллиантов и 10 синих сапфиров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сделка есть сделка. Я очень надеюсь, что ты знаешь, во что ввязываешься, $N. Чтобы порыбачить, придется пройти через очень много проблем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Арканитовые буйки сами собой не делаются, $N. НЕТ, денег взаймы не дам.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нарайну Причудню в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8729,'Гнев Нептулона','Я еще не говорил о плохой новости, нет??? Ее зовут Каракула – 30 метров смерти и разрушения. Наверное, я забыл об этой мелочи.$B$BМое сверхпсихопсионическое ясновидение говорит мне, что лучше всего будет закинуть буек с берега Азшары, в Залив Бурь.$B$BВысматривайте водоворот, в котором скорее всего будет до кучи обломков кораблей.$B$BКстати, надеюсь, не в одиночку пойдете?$B$BЕсли вам каким-то чудесным образом повезет, отнесите обломок скипетра Анахроносу.','Забросье арканитовый буй в Водоворот в Заливе Бурь Азшары.','Молодец, $N. Я скоро смогу переделать Скипетр Зыбучих Песков.','Время на исходе!','Вернитесь к Анахроносу в Пещеры Времени, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнев Нептулона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я еще не говорил о плохой новости, нет??? Ее зовут Каракула – 30 метров смерти и разрушения. Наверное, я забыл об этой мелочи.$B$BМое сверхпсихопсионическое ясновидение говорит мне, что лучше всего будет закинуть буек с берега Азшары, в Залив Бурь.$B$BВысматривайте водоворот, в котором скорее всего будет до кучи обломков кораблей.$B$BКстати, надеюсь, не в одиночку пойдете?$B$BЕсли вам каким-то чудесным образом повезет, отнесите обломок скипетра Анахроносу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Забросье арканитовый буй в Водоворот в Заливе Бурь Азшары.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $N. Я скоро смогу переделать Скипетр Зыбучих Песков.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Время на исходе!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахроносу в Пещеры Времени, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8730,'Поражение Нефария','Надо же, герой! Тысячу лет назад мне поручили хранить осколок, и вот в черный час он был отнят у меня... Но какая же трагедия без жестокости?$B$B<Веластрас слабо кашляет.>$B$BОс... осколок скипетра ныне у Нефария.$B$BВремя дорого, ибо Нефарий намерен уничтожить осколок. Поторопись!','Убейте Нефариана и добудьте осколок красного скипетра. Верните осколок красного скипетра Анахроносу в Пещеры Времени в Танарис. На выполнение задания у вас есть 5 часов.','Душа Ваэластраза успокойна, $Gчемпион:чемпионка;. Все Аспекты с большим интересом следят за твоими успехами. Знай, что у тебя есть сильные союзники.$B$BМне было велено дать тебе кое-что, чтобы помочь тебе в этой борьбе. Используй это правильно...','Другой наш герой проиграл порождению Смертокрыла. Мы будем навеки прокляты этим страданием...','Вернитесь к Анахроносу в Пещеры Времени, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поражение Нефария',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надо же, герой! Тысячу лет назад мне поручили хранить осколок, и вот в черный час он был отнят у меня... Но какая же трагедия без жестокости?$B$B<Веластрас слабо кашляет.>$B$BОс... осколок скипетра ныне у Нефария.$B$BВремя дорого, ибо Нефарий намерен уничтожить осколок. Поторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Нефариана и добудьте осколок красного скипетра. Верните осколок красного скипетра Анахроносу в Пещеры Времени в Танарис. На выполнение задания у вас есть 5 часов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Душа Ваэластраза успокойна, $Gчемпион:чемпионка;. Все Аспекты с большим интересом следят за твоими успехами. Знай, что у тебя есть сильные союзники.$B$BМне было велено дать тебе кое-что, чтобы помочь тебе в этой борьбе. Используй это правильно...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Другой наш герой проиграл порождению Смертокрыла. Мы будем навеки прокляты этим страданием...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахроносу в Пещеры Времени, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8731,'Рутинное задание','Приветствую тебя, $n. Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные.$b$bЛегион Оргриммара под предводительством капитана Крушителя Черепов расквартирован рядом с Ульем Регал.$b$bПоговори с капитаном и принеси мне доказательство выполнения его указаний. Тем временем я подготовлю для тебя новое задание.$b$bАх да, сделай одолжение, держись подальше от дружины Стальгорна. Добровольцы Орды и Альянса постоянно грызутся друг с другом.','Сразу видно, что Круг немного внимания уделяет писанине. Он подписал эти бумаги кровью силитидов!$B$BХорошо, Илиторий. Я подготовил для тебя задания, которые наилучшим образом используют твои способности, $C.$B$BЕсли ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!','Капитана Расщепленного Черепа можно найти за пределами Улья Регал.','Вернитесь к призывателю ветров Калдону в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рутинное задание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $n. Прежде чем дать тебе ответственные задания, я должен поручить тебе более простые и рутинные.$b$bЛегион Оргриммара под предводительством капитана Крушителя Черепов расквартирован рядом с Ульем Регал.$b$bПоговори с капитаном и принеси мне доказательство выполнения его указаний. Тем временем я подготовлю для тебя новое задание.$b$bАх да, сделай одолжение, держись подальше от дружины Стальгорна. Добровольцы Орды и Альянса постоянно грызутся друг с другом.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сразу видно, что Круг немного внимания уделяет писанине. Он подписал эти бумаги кровью силитидов!$B$BХорошо, Илиторий. Я подготовил для тебя задания, которые наилучшим образом используют твои способности, $C.$B$BЕсли ты и такие как ты будут биться, не покладая рук, скоро мы изгоним врагов!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Капитана Расщепленного Черепа можно найти за пределами Улья Регал.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывателю ветров Калдону в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8732,'Бумаги о полевых обязанностях','Да, я полагаю, что эта небольшая стычка перейдет в боевое дежурство. Отнеси их обратно в Крепость Кенария, я уверен, у них для тебя найдется работа.','Я так понимаю, ты хочешь подписать эти бумаги?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бумаги о полевых обязанностях',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я полагаю, что эта небольшая стычка перейдет в боевое дежурство. Отнеси их обратно в Крепость Кенария, я уверен, у них для тебя найдется работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я так понимаю, ты хочешь подписать эти бумаги?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8733,'Эраникус, Тиран Сна','Это будет расплата. Если я сегодня погибну, то паду я за правое дело. Верни осколок зеленого жезла. Освободи Эраникуса от порчи, которой поразили его древние боги.$B$BОтправляйся в Дарнас. Прямо у стен города ты встретишь одного из моих агентов. Он даст ход нашим делам и оповестит Тиранду о наших планах так, чтобы не прознал Олений Шлем.$B$B*Малфурион вздыхает.*$B$BУтратить милость тысячелетий...','Отправляйтесь на континент Тельдрассил и найдите агента Малфуриона у стен Дарнаса.','Огонек молчит, только иногда тихо жужжит. Странно, но он способен ощаться с вами мысленно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эраникус, Тиран Сна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это будет расплата. Если я сегодня погибну, то паду я за правое дело. Верни осколок зеленого жезла. Освободи Эраникуса от порчи, которой поразили его древние боги.$B$BОтправляйся в Дарнас. Прямо у стен города ты встретишь одного из моих агентов. Он даст ход нашим делам и оповестит Тиранду о наших планах так, чтобы не прознал Олений Шлем.$B$B*Малфурион вздыхает.*$B$BУтратить милость тысячелетий...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на континент Тельдрассил и найдите агента Малфуриона у стен Дарнаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Огонек молчит, только иногда тихо жужжит. Странно, но он способен ощаться с вами мысленно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8734,'Тиранда и Ремул','Тиранда будет извещена, $gсмертный:смертная;. Шан\'до Ярость Бури подготовил меня к неожиданностям.$B$BТеперь тебе надлежит отправится в Лунную поляну и поговорить с хранителем Ремулом. Он даст тебе дальнейшие инструкции по поводу того, как вызвать Эраникуса.$B$BМы все желаем тебе великой удачи.','Отправляйтесь в Лунную поляну и поговорите с хранителем Ремулом.','Невозможно будет выманить Эраникуса из Сна, если он того не пожелает. Однако, его намерения заставят его прийти в наш мир. Он жаждет уничтожить живое проявление Малфуриона. Если мы добьемся успеха, это может погубить одного из самых могучих союзников Сна. Кошмар полностью поглотит все, что еще сохранилось, если Малфурион падет...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тиранда и Ремул',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тиранда будет извещена, $gсмертный:смертная;. Шан\'до Ярость Бури подготовил меня к неожиданностям.$B$BТеперь тебе надлежит отправится в Лунную поляну и поговорить с хранителем Ремулом. Он даст тебе дальнейшие инструкции по поводу того, как вызвать Эраникуса.$B$BМы все желаем тебе великой удачи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Лунную поляну и поговорите с хранителем Ремулом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невозможно будет выманить Эраникуса из Сна, если он того не пожелает. Однако, его намерения заставят его прийти в наш мир. Он жаждет уничтожить живое проявление Малфуриона. Если мы добьемся успеха, это может погубить одного из самых могучих союзников Сна. Кошмар полностью поглотит все, что еще сохранилось, если Малфурион падет...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8735,'Проклятие Кошмара','Тебе нужно оправиться к четырем порталам сна Азерота. Из каждого ты добудешь фрагмент проклятия Кошмара. Дракониды, населяющие те места, не будут их отдавать. Возвращайся, когда добудешь все фрагменты.','Отправьтесь к четырем порталам Изумрудного Сна в Азероте и добудьте фрагменты проклятия Кошмара из каждого из них. Вернитесь к хранителю Ремулу в Лунную поляну по завершении задания.','$GГотов:Готова; ли ты? Готов ли мир встретить то, что мы собираемся призвать? Я не знаю... У меня есть долг перед Малфурионом. Я связан долгом и честью...','<Ремулос находится в глубокой задумчивости.>','Вернитесь к хранителю Ремулу на Озеро Элуне\'ара, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятие Кошмара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе нужно оправиться к четырем порталам сна Азерота. Из каждого ты добудешь фрагмент проклятия Кошмара. Дракониды, населяющие те места, не будут их отдавать. Возвращайся, когда добудешь все фрагменты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь к четырем порталам Изумрудного Сна в Азероте и добудьте фрагменты проклятия Кошмара из каждого из них. Вернитесь к хранителю Ремулу в Лунную поляну по завершении задания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GГотов:Готова; ли ты? Готов ли мир встретить то, что мы собираемся призвать? Я не знаю... У меня есть долг перед Малфурионом. Я связан долгом и честью...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Ремулос находится в глубокой задумчивости.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Ремулу на Озеро Элуне\'ара, что на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (8736,'Явление Кошмара','Мы должны усмирить Эраникуса. Мы не можем позволить ему уничтожить себя!$B$BТиранда уже идет нам на помощь. Мы должны отбить удары дракона и спасти Ночную гавань от неминуемого уничтожения.$B$BСтой на страже! Ты и твои союзники – наша единственная надежда.','Защитите Ночную гавань от Эраникуса. Не дайте погибнуть хранителю Ремулу. Не убивайте Эраникуса. Защищайте себя. Дождитесь Тиранды.','Он пришел в себя, $N. Ныне он возвращаяется в Сон, дабы исправить тот вред, что причинил. Эраникус станет могучим союзником Малфуриону и моему отцу.$B$BПрими эти доспехи, $N, они подарены мне самой Изерой. Они пригодятся тебе в сражении с киражами.','Избавление Эраникуса','Вернитесь к хранителю Ремулу в Святилище Ремула, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Явление Кошмара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны усмирить Эраникуса. Мы не можем позволить ему уничтожить себя!$B$BТиранда уже идет нам на помощь. Мы должны отбить удары дракона и спасти Ночную гавань от неминуемого уничтожения.$B$BСтой на страже! Ты и твои союзники – наша единственная надежда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитите Ночную гавань от Эраникуса. Не дайте погибнуть хранителю Ремулу. Не убивайте Эраникуса. Защищайте себя. Дождитесь Тиранды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он пришел в себя, $N. Ныне он возвращаяется в Сон, дабы исправить тот вред, что причинил. Эраникус станет могучим союзником Малфуриону и моему отцу.$B$BПрими эти доспехи, $N, они подарены мне самой Изерой. Они пригодятся тебе в сражении с киражами.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Избавление Эраникуса',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Ремулу в Святилище Ремула, что на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8737,'Лазурный храмовник','Сумеречный Молот и повелители стихий, которым поклоняются служители культа, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан\'Кираже, мы не должны терять бдительность и давать волю внешним врагам.$b$bОтыщи способ вызвать и уничтожить лазурного храмовника и доложи о выполнении задания Бору Буйногривому.','Призовите и убейте лазурного храмовника и доложите о выполнении задания Бору Буйногривому из Крепости Кенария. Для завершения задания принесите тактическую задачу I.','Отличная работа, $N. Вот следующее задание.','Твоя задача уже выполнена, $N?','Вернитесь к Бору Буйногривому в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лазурный храмовник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сумеречный Молот и повелители стихий, которым поклоняются служители культа, представляют серьезную опасность для деятельности Круга в Силитусе. Учитывая, что у нас появились новые враги – в Ан\'Кираже, мы не должны терять бдительность и давать волю внешним врагам.$b$bОтыщи способ вызвать и уничтожить лазурного храмовника и доложи о выполнении задания Бору Буйногривому.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите и убейте лазурного храмовника и доложите о выполнении задания Бору Буйногривому из Крепости Кенария. Для завершения задания принесите тактическую задачу I.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Вот следующее задание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твоя задача уже выполнена, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бору Буйногривому в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8738,'Донесение разведчика из улья Регал','Мы отправили наших лучших разведчиков к ульям силитидов. Разведчик Ландион уже несколько дней наблюдает за передвижениями этих насекомых. Найди его и забери у него письменный отчет. Нам необходимо как можно скорее получить собранные сведения.','Свяжитесь с кенарийским разведчиком Ландионом в Улье Регал и отнесите донесение разведчика из Улья Регал призывательнице ветров Гордый Рог в Крепость Кенария. Кроме того, принесите тактическую задачу VII.','Мы очень ценим твои усилия, $N. Я немедленно займусь этими донесениями, а ты можешь переходить к следующему заданию.','Ты найдешь разведчика Лэндиона внутри Улья\'регала. Торопись, $N! Время имеет существенное значение.','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение разведчика из улья Регал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы отправили наших лучших разведчиков к ульям силитидов. Разведчик Ландион уже несколько дней наблюдает за передвижениями этих насекомых. Найди его и забери у него письменный отчет. Нам необходимо как можно скорее получить собранные сведения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Свяжитесь с кенарийским разведчиком Ландионом в Улье Регал и отнесите донесение разведчика из Улья Регал призывательнице ветров Гордый Рог в Крепость Кенария. Кроме того, принесите тактическую задачу VII.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы очень ценим твои усилия, $N. Я немедленно займусь этими донесениями, а ты можешь переходить к следующему заданию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты найдешь разведчика Лэндиона внутри Улья\'регала. Торопись, $N! Время имеет существенное значение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8739,'Донесение разведчика из улья Аши','Мы отправили наших лучших разведчиков к ульям силитидов. Разведчик Джалия уже несколько дней наблюдает за передвижениями этих насекомых. Найди ее и забери у нее письменный отчет. Нам необходимо как можно скорее получить собранные сведения.','Свяжитесь с кенарийской разведчицей Джалией в Улье Аши и отнесите ее донесение призывательнице ветров Гордый Рог в Крепость Кенария. Кроме того, принесите тактическую задачу VIII.','Мы очень ценим твои усилия, $N. Я немедленно займусь этими донесениями, а ты можешь переходить к следующему заданию.','Ты найдешь разведчика Джалию внутри Улья Аши. Торопись, $N! Время имеет существенное значение.','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение разведчика из улья Аши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы отправили наших лучших разведчиков к ульям силитидов. Разведчик Джалия уже несколько дней наблюдает за передвижениями этих насекомых. Найди ее и забери у нее письменный отчет. Нам необходимо как можно скорее получить собранные сведения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Свяжитесь с кенарийской разведчицей Джалией в Улье Аши и отнесите ее донесение призывательнице ветров Гордый Рог в Крепость Кенария. Кроме того, принесите тактическую задачу VIII.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы очень ценим твои усилия, $N. Я немедленно займусь этими донесениями, а ты можешь переходить к следующему заданию.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты найдешь разведчика Джалию внутри Улья Аши. Торопись, $N! Время имеет существенное значение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8740,'Сумеречные мародеры','В последнее время появились верховые отряды сторонников Сумеречного Молота. Они не суются в земли, охраняемые Крепостью Кенария, а грабят небольшие караваны и отряды.$b$bНайди и убей сумеречных мародеров, а заодно и их лидера, воительницу по имени Морна. О выполнении задания доложи Зовущей из клана Гордый Рог.','Убейте сумеречного мародера Морну и двух сумеречных мародеров. Доложите о выполнении задания призывательнице ветров Гордый Рог. Кроме того, сдайте тактическую задачу IX.','Молодец, $N. Сумеречные мародеры причинили нам множество неприятностей. Мириться с ними было нельзя. Вот тебе следующее задание.','Твоя задача уже выполнена, $N?','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумеречные мародеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В последнее время появились верховые отряды сторонников Сумеречного Молота. Они не суются в земли, охраняемые Крепостью Кенария, а грабят небольшие караваны и отряды.$b$bНайди и убей сумеречных мародеров, а заодно и их лидера, воительницу по имени Морна. О выполнении задания доложи Зовущей из клана Гордый Рог.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте сумеречного мародера Морну и двух сумеречных мародеров. Доложите о выполнении задания призывательнице ветров Гордый Рог. Кроме того, сдайте тактическую задачу IX.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $N. Сумеречные мародеры причинили нам множество неприятностей. Мириться с ними было нельзя. Вот тебе следующее задание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твоя задача уже выполнена, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8741,'Возвращение победителя','Хранитель ждет твоего возвращения, $n. Отнеси этот осколок зеленого скипетра Анахроносу в Пещеры Времени.','Отнесите осколок зеленого скипетра Анахроносу в Пещеры Времени в Танарисе.','О твоих подвигах будет знать каждый, чемпион. Они будут петь тебе дифирамбы от Оргриммара до дальних уголков Южных морей. Все будут знать о чемпионе Бронзового полета, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение победителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хранитель ждет твоего возвращения, $n. Отнеси этот осколок зеленого скипетра Анахроносу в Пещеры Времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите осколок зеленого скипетра Анахроносу в Пещеры Времени в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О твоих подвигах будет знать каждый, чемпион. Они будут петь тебе дифирамбы от Оргриммара до дальних уголков Южных морей. Все будут знать о чемпионе Бронзового полета, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8742,'Армия Калимдора','Прошла тысяча лет, и, как и было суждено, теперь ты передо мной. Тот, кто приведет свой народ к новой эре.$B$BСтарый Бог трепещет, $N. О да, он боится твоей веры. Разрушь пророчество К\'Туна.$B$BОн знает, что ты $Gпришел:пришла;, чемпион - и вместе с тобой приходит мощь Калимдора. Ты $Gдолжен:должна; только сообщить мне, когда будешь $Gготов:готова;, и я дам тебе Скипетр Зыбучих песков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Армия Калимдора',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прошла тысяча лет, и, как и было суждено, теперь ты передо мной. Тот, кто приведет свой народ к новой эре.$B$BСтарый Бог трепещет, $N. О да, он боится твоей веры. Разрушь пророчество К\'Туна.$B$BОн знает, что ты $Gпришел:пришла;, чемпион - и вместе с тобой приходит мощь Калимдора. Ты $Gдолжен:должна; только сообщить мне, когда будешь $Gготов:готова;, и я дам тебе Скипетр Зыбучих песков.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8743,'Бей в гонг!','Из земли возле гонга вырывается особый кристалл.','Гонг Скарабея зловеще нависает над тобой. Крепись духом, $N – как только гонг Скарабея загудит, врата Ан\'Киража откроются.$B$BДряхлая пасть этого зверя может извергнуть только хаос и разрушение. Защити свой народ!','Вернитесь к гонгу Скарабея в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бей в гонг!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Из земли возле гонга вырывается особый кристалл.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гонг Скарабея зловеще нависает над тобой. Крепись духом, $N – как только гонг Скарабея загудит, врата Ан\'Киража откроются.$B$BДряхлая пасть этого зверя может извергнуть только хаос и разрушение. Защити свой народ!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к гонгу Скарабея в Силитус.',`completedtext_loc8`);
