INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8745,'Сокровище Вневременного') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровище Вневременного',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8747,'Путь защитника','Недурно, $Gмалыш:малышка;. Тебе пришлось немало попотеть, чтобы заслужить благосклонность Бронзовых драконов. Мы не забудем твоих усилий.$B$BПерстень-печатка победителя придаст мощи твоим ударам.$B$BЕще раз подумай хорошенько. Избрав путь, ты не сможешь сойти с него.','Впечатляет, $Gмалыш:малышка;. Вы пережили много неприятностей, чтобы получить благосклонность Бронзового Полета. Ваша преданность отмечена.$B$BПерстень с печаткой завоевателя значительно усилит ваши физические атаки.$B$BИмейте в виду, что после того, как вы выбрали свой путь, у вас не будет возможности обратиться за помощью, если вы передумаете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь защитника',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Недурно, $Gмалыш:малышка;. Тебе пришлось немало попотеть, чтобы заслужить благосклонность Бронзовых драконов. Мы не забудем твоих усилий.$B$BПерстень-печатка победителя придаст мощи твоим ударам.$B$BЕще раз подумай хорошенько. Избрав путь, ты не сможешь сойти с него.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Впечатляет, $Gмалыш:малышка;. Вы пережили много неприятностей, чтобы получить благосклонность Бронзового Полета. Ваша преданность отмечена.$B$BПерстень с печаткой завоевателя значительно усилит ваши физические атаки.$B$BИмейте в виду, что после того, как вы выбрали свой путь, у вас не будет возможности обратиться за помощью, если вы передумаете.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8748,'Путь защитника','Твое восхождение в ранг стаи впечатляет, $N. Да не сворачивай ты с пути защитника!','Мы не забудем, как ты $Gзащищал:защищала; детей Калимдора. Дай мне свой перстень-печатку, и я наложу на него более сложные чары.','Вернитесь к Анахроносу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь защитника',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твое восхождение в ранг стаи впечатляет, $N. Да не сворачивай ты с пути защитника!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы не забудем, как ты $Gзащищал:защищала; детей Калимдора. Дай мне свой перстень-печатку, и я наложу на него более сложные чары.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахроносу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8749,'Путь защитника','Твое восхождение в ранг стаи впечатляет, $N. Да не сворачивай ты с пути защитника!','Ты чтишь мой род, $N. Убей врагов Калимдора! Покажите им, что значит уничтожить землю вечного звездного света.$B$BВы заработали еще одно улучшение. Дай мне свое перстень, чтобы я мог усилить его силу.','Вернитесь к Анахроносу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь защитника',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твое восхождение в ранг стаи впечатляет, $N. Да не сворачивай ты с пути защитника!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты чтишь мой род, $N. Убей врагов Калимдора! Покажите им, что значит уничтожить землю вечного звездного света.$B$BВы заработали еще одно улучшение. Дай мне свое перстень, чтобы я мог усилить его силу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахроносу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8750,'Путь защитника','Твое восхождение в ранг стаи впечатляет, $N. Да не сворачивай ты с пути защитника!','Посвящение такого масштаба является редкостью. Ты $Gпоказал:показала;, что твоя воля не изменилась, $N. Вы будете очень вознаграждены за ваши стойкие часы над нашим миром.$B$BДай мне свое перстень с печаткой, чтобы я мог усилить его чары.','Вернитесь к Анахроносу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь защитника',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твое восхождение в ранг стаи впечатляет, $N. Да не сворачивай ты с пути защитника!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Посвящение такого масштаба является редкостью. Ты $Gпоказал:показала;, что твоя воля не изменилась, $N. Вы будете очень вознаграждены за ваши стойкие часы над нашим миром.$B$BДай мне свое перстень с печаткой, чтобы я мог усилить его чары.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахроносу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8751,'Защитник Калимдора','Хвала тебе, $GЗащитник:Защитница; Калимдора! Великая тебе хвала!','Никогда прежде мне не случалось видеть такой стойкости! Бронзовые драконы даруют тебе свои последние чары. Этого потребовал сам Вневременный!$B$BДай мне свой перстень, и я наложу на него еще одно заклятье.','Вернитесь к Анахроносу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитник Калимдора',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала тебе, $GЗащитник:Защитница; Калимдора! Великая тебе хвала!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Никогда прежде мне не случалось видеть такой стойкости! Бронзовые драконы даруют тебе свои последние чары. Этого потребовал сам Вневременный!$B$BДай мне свой перстень, и я наложу на него еще одно заклятье.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахроносу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8752,'Путь победителя','Недурно, $Gмалыш:малышка;. Тебе пришлось немало попотеть, чтобы заслужить благосклонность Бронзовых драконов. Мы не забудем твоих усилий.$B$BПерстень-печатка победителя придаст мощи твоим ударам.$B$BЕще раз подумай хорошенько. Избрав путь, ты не сможешь сойти с него.','Впечатляет, $Gмалыш:малышка;. Вы пережили много неприятностей, чтобы получить благосклонность Бронзового Полета. Ваша преданность отмечена.$B$BПерстень с печаткой завоевателя значительно усилит ваши физические атаки.$B$BИмейте в виду, что после того, как вы выбрали свой путь, у вас не будет возможности обратиться за помощью, если вы передумаете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь победителя',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Недурно, $Gмалыш:малышка;. Тебе пришлось немало попотеть, чтобы заслужить благосклонность Бронзовых драконов. Мы не забудем твоих усилий.$B$BПерстень-печатка победителя придаст мощи твоим ударам.$B$BЕще раз подумай хорошенько. Избрав путь, ты не сможешь сойти с него.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Впечатляет, $Gмалыш:малышка;. Вы пережили много неприятностей, чтобы получить благосклонность Бронзового Полета. Ваша преданность отмечена.$B$BПерстень с печаткой завоевателя значительно усилит ваши физические атаки.$B$BИмейте в виду, что после того, как вы выбрали свой путь, у вас не будет возможности обратиться за помощью, если вы передумаете.',`requestitemstext_loc8`);
