INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8761,'Великий заклинатель','Хвала тебе, $GВеликий:Великая; $Gзаклинатель:заклинательница;! Великая тебе хвала!','Никогда прежде мне не случалось видеть такой стойкости! Бронзовые драконы даруют тебе свои последние чары. Этого потребовал сам Вневременный!$B$BДай мне свой перстень, и я наложу на него еще одно заклятье.','Вернитесь к Анахроносу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий заклинатель',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала тебе, $GВеликий:Великая; $Gзаклинатель:заклинательница;! Великая тебе хвала!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Никогда прежде мне не случалось видеть такой стойкости! Бронзовые драконы даруют тебе свои последние чары. Этого потребовал сам Вневременный!$B$BДай мне свой перстень, и я наложу на него еще одно заклятье.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахроносу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8763,'Герой дня','Слушай... Я вообще-то не должен тебе этого говорить, но раз уж ты у нас сегодня герой; и все такое...$B$BВ эту пору везде полно остролиста, но он быстро вянет. Мы получили машину для заготовки остролиста – и он не портится! Мы его используем, чтобы придать вкус празднику... и ради прибыли – летом!$B$BЯ позволю тебе попользоваться этой машинкой, но только если ты мастер-кулинар. От тебя потребуется некоторое количество глубокоскальной соли и два-три, ну, скажем, пять золотых. И получишь славную партию остролиста, которую можно хранить сколько угодно.','Принесите 1 порцию глубокоскальной соли и 5 золотых монет к любой сушилке для остролиста, чтобы получить 5 сушеных остролистов.','Машина при начале работы тихонько гудит и выпускает облачко пара. Вскоре она останавливается, и из нее выходит еще одна струйка пара. Дверца открывается, а за ней – партия сушеного остролиста!','На первый взгляд, сушилка для остролиста напоминает нечто вроде перегонного куба, но, если вглядеться повнимательнее, становится видно, что в основную конструкцию внесены типично гоблинские изменения. Тем не менее вы – достаточно опытный кулинар, чтобы разобраться, как работает эта машина.\n\nСвежий остролист в машину уже загружен – нужно только добавить глубокоскальной соли и пять золотых монет, и машинка заработает.','Вернитесь к сушилке для остролиста.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Герой дня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай... Я вообще-то не должен тебе этого говорить, но раз уж ты у нас сегодня герой; и все такое...$B$BВ эту пору везде полно остролиста, но он быстро вянет. Мы получили машину для заготовки остролиста – и он не портится! Мы его используем, чтобы придать вкус празднику... и ради прибыли – летом!$B$BЯ позволю тебе попользоваться этой машинкой, но только если ты мастер-кулинар. От тебя потребуется некоторое количество глубокоскальной соли и два-три, ну, скажем, пять золотых. И получишь славную партию остролиста, которую можно хранить сколько угодно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 порцию глубокоскальной соли и 5 золотых монет к любой сушилке для остролиста, чтобы получить 5 сушеных остролистов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Машина при начале работы тихонько гудит и выпускает облачко пара. Вскоре она останавливается, и из нее выходит еще одна струйка пара. Дверца открывается, а за ней – партия сушеного остролиста!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На первый взгляд, сушилка для остролиста напоминает нечто вроде перегонного куба, но, если вглядеться повнимательнее, становится видно, что в основную конструкцию внесены типично гоблинские изменения. Тем не менее вы – достаточно опытный кулинар, чтобы разобраться, как работает эта машина.\n\nСвежий остролист в машину уже загружен – нужно только добавить глубокоскальной соли и пять золотых монет, и машинка заработает.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сушилке для остролиста.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8764,'Изменение пути – уже не защитник','Будь $Gздоров:здорова;, $N. Если вы передумаете, я буду здесь, чтобы помочь вам.','Чемпион, Если ты решишь пойти другим путем, Подари мне свой перстень с печаткой и гору скарабеев от наших врагов в Ан\'Кираж.','Вернитесь к Анахроносу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изменение пути – уже не защитник',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будь $Gздоров:здорова;, $N. Если вы передумаете, я буду здесь, чтобы помочь вам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чемпион, Если ты решишь пойти другим путем, Подари мне свой перстень с печаткой и гору скарабеев от наших врагов в Ан\'Кираж.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахроносу в Танарис.',`completedtext_loc8`);
