INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8770,'Цель: защитники из Улья Аши','Убейте 30 защитников из Улья Аши и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу I.','Отличная работа, $N. Мы не забудем твоих усилий.','Ты хочешь что-то сказать, $C?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: защитники из Улья Аши',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 защитников из Улья Аши и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу I.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Мы не забудем твоих усилий.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь что-то сказать, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8771,'Цель: пескоходы из Улья Аши','Убейте 30 пескоходов из Улья Аши и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу II.','Отличная работа, $N. Твои подвиги в сражении при Улье Аши не прошли незамеченными.','Ты хочешь что-то сказать, $C?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: пескоходы из Улья Аши',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 пескоходов из Улья Аши и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу II.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Твои подвиги в сражении при Улье Аши не прошли незамеченными.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь что-то сказать, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8772,'Отличная работа, $N. Твои подвиги в сражении при Улье Зора не прошли незамеченными.','Ты хочешь что-то сказать, $C?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Твои подвиги в сражении при Улье Зора не прошли незамеченными.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь что-то сказать, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8773,'Цель: разрушители из Улья Зора','Мы вызвали подкрепление для сражения у Улья Зора. Твоя задача – убить как можно больше разрушителей. Выполнив задание, отчитайся командиру Мар\'алиту.','Убейте 30 разрушителей из Улья Зора и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи IV.','Я слышал немало добрых слов о твоем участии в нападении на Улей Зора. Продолжай в том же духе, и победа будет за нами.','Ты хочешь что-то сказать, $C?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: разрушители из Улья Зора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы вызвали подкрепление для сражения у Улья Зора. Твоя задача – убить как можно больше разрушителей. Выполнив задание, отчитайся командиру Мар\'алиту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 разрушителей из Улья Зора и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи IV.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я слышал немало добрых слов о твоем участии в нападении на Улей Зора. Продолжай в том же духе, и победа будет за нами.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь что-то сказать, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8774,'Цель: стерегущие из Улья Регал','Убейте 30 стерегущих из Улья Регал и доложите об этом командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи VIII.','Отличная работа, $N. Твои подвиги в сражении при Улье Регал не прошли незамеченными.','Ты хочешь что-то сказать, $N?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: стерегущие из Улья Регал',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 стерегущих из Улья Регал и доложите об этом командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите изложение боевой задачи VIII.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Твои подвиги в сражении при Улье Регал не прошли незамеченными.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь что-то сказать, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
