INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8777,'Цель: землерои из Улья Регал','Убейте 30 землероев из Улья Регал и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу XI.','Отличная работа, $N. Твои подвиги в сражении при Улье Регал не прошли незамеченными.','Ты хочешь что-то сказать, $N?','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цель: землерои из Улья Регал',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 землероев из Улья Регал и доложите о выполнении задания командиру Мар\'алиту в Крепости Кенария в Силитусе. Для завершения задания принесите боевую задачу XI.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Твои подвиги в сражении при Улье Регал не прошли незамеченными.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь что-то сказать, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Мар\'алиту в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8778,'Взрывчатка для дружины Стальгорна','Дружина Стальгорна прислала необычный запрос – на весьма... э-э-э... неустойчивые вещества. Собери их и принеси господину Пружине Форсунки из дружины Стальгорна.','Принесите 6 бутылок воспламеняющей смеси, 5 бочонков гоблинского ракетного топлива и 10 порций концентрированного взрывчатого вещества чародею Пружине Форсунки возле Улья Зора в Силитусе. Кроме того, принесите тыловое задание IV.','Ах, да! Они очень пригодятся! Большое спасибо, $N!','У тебя есть что-то для меня, $N?','Вернитесь к чародею Форсунчику, что стоит у Улья Зора в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взрывчатка для дружины Стальгорна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дружина Стальгорна прислала необычный запрос – на весьма... э-э-э... неустойчивые вещества. Собери их и принеси господину Пружине Форсунки из дружины Стальгорна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 бутылок воспламеняющей смеси, 5 бочонков гоблинского ракетного топлива и 10 порций концентрированного взрывчатого вещества чародею Пружине Форсунки возле Улья Зора в Силитусе. Кроме того, принесите тыловое задание IV.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, да! Они очень пригодятся! Большое спасибо, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Форсунчику, что стоит у Улья Зора в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8779,'Материалы для гадания','Исследования геолога Злая Шутка имели огромное значение для нашей деятельности в Силитусе. Недавно она запросила материалы для гадания.$b$bПожалуйста, собери все необходимое и отнеси ей. Пусть она продолжает исследования.','Принесите 1 большой сверкающий осколок, 1 большой светозарный осколок и 1 огромный изумруд геологу Злой Шутке в Крепости Кенария в Силитусе. Также принесите тыловое задание V.','О да... Ты мне очень $Gпомог:помогла;! Достать эти материалы в пустыне невероятно сложно. Спасибо, $N.','У тебя есть что-то для меня, $N?','Вернитесь к геологу Ехидной в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Материалы для гадания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Исследования геолога Злая Шутка имели огромное значение для нашей деятельности в Силитусе. Недавно она запросила материалы для гадания.$b$bПожалуйста, собери все необходимое и отнеси ей. Пусть она продолжает исследования.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 большой сверкающий осколок, 1 большой светозарный осколок и 1 огромный изумруд геологу Злой Шутке в Крепости Кенария в Силитусе. Также принесите тыловое задание V.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да... Ты мне очень $Gпомог:помогла;! Достать эти материалы в пустыне невероятно сложно. Спасибо, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Ехидной в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8780,'Комплекты брони','У дружины Стальгорна на исходе запасы накладок на доспехи. Добудь партию таких комплектов и отнеси их Джанеле Твердомолот на заставу дружины Стальгорна, что рядом с Ульем Зора.','Принесите 8 комплектов накладок из грубой кожи и 8 комплектов накладок из толстой кожи Джанеле Твердомолот на заставу дружины Стальгорна возле Улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VII.','Спасибо, я передам их нашим ребятам.','У тебя есть что-то для меня, $N?','Вернитесь к Джанеле Твердомолот, что стоит у Улья Зора в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Комплекты брони',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У дружины Стальгорна на исходе запасы накладок на доспехи. Добудь партию таких комплектов и отнеси их Джанеле Твердомолот на заставу дружины Стальгорна, что рядом с Ульем Зора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 комплектов накладок из грубой кожи и 8 комплектов накладок из толстой кожи Джанеле Твердомолот на заставу дружины Стальгорна возле Улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VII.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, я передам их нашим ребятам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джанеле Твердомолот, что стоит у Улья Зора в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8781,'Нехватка оружия','Дружина Стальгорна оказалась чрезвычайно полезным союзником в наших битвах в Силитусе. К сожалению, по пути они растеряли много припасов и оборудования. Добудь партию оружия и доставь ее Джанеле Твердомолот к Улью Зора.','Принесите 2 палаша лунной стали Джанеле Твердомолот на заставу дружины Стальгорна возле Улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VI.','Отлично! Мне больше не придется слышать жалобы на тупые лезвия. Спасибо, $N.','У тебя есть что-то для меня, $N?','Вернитесь к Джанеле Твердомолот, что стоит у Улья Зора в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нехватка оружия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дружина Стальгорна оказалась чрезвычайно полезным союзником в наших битвах в Силитусе. К сожалению, по пути они растеряли много припасов и оборудования. Добудь партию оружия и доставь ее Джанеле Твердомолот к Улью Зора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 палаша лунной стали Джанеле Твердомолот на заставу дружины Стальгорна возле Улья Зора в Силитусе. Кроме того, сдайте тыловую задачу VI.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Мне больше не придется слышать жалобы на тупые лезвия. Спасибо, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джанеле Твердомолот, что стоит у Улья Зора в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8782,'Поставки формы','У нас такой приток добровольцев, что не хватает формы. Принеси материалы для пошива формы и отдай их Зовущей из клана Гордый Рог.','Принесите 1 кусок луноткани, 2 рулона рунической ткани и 1 железношелковую паутину призывательнице ветров Гордый Рог в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу VIII.','А, да, нам их очень не хватало. Спасибо за добрую службу, $N.','У тебя есть что-то для меня, $N?','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поставки формы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас такой приток добровольцев, что не хватает формы. Принеси материалы для пошива формы и отдай их Зовущей из клана Гордый Рог.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 кусок луноткани, 2 рулона рунической ткани и 1 железношелковую паутину призывательнице ветров Гордый Рог в Крепости Кенария в Силитусе. Кроме того сдайте тыловую задачу VIII.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, да, нам их очень не хватало. Спасибо за добрую службу, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывательнице ветров Гордый Рог в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8783,'Необычные материалы','Варгус, кузнец Крепости Кенария, запросил партию зачарованных материалов для создания мощного оружия для наших солдат. Добудь все необходимое и отнеси их Варгусу в Крепость Кенария, чтобы он снабдил войска всем необходимым.','Принесите Варгусу из Крепости Кенария в Силитусе 2 зачарованных ториевых слитка и 2 куска зачарованной кожи. Кроме того, принесите тыловое задание IX.','Да-да. Превосходные материалы. Спасибо, $N.','У тебя есть что-то для меня, $N?','Вернитесь к Варгусу в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычные материалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Варгус, кузнец Крепости Кенария, запросил партию зачарованных материалов для создания мощного оружия для наших солдат. Добудь все необходимое и отнеси их Варгусу в Крепость Кенария, чтобы он снабдил войска всем необходимым.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Варгусу из Крепости Кенария в Силитусе 2 зачарованных ториевых слитка и 2 куска зачарованной кожи. Кроме того, принесите тыловое задание IX.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да-да. Превосходные материалы. Спасибо, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варгусу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8784,'Секреты киражи','Вам удалось обнаружить древний киражский артефакт! Возможно, один из драконов, стоящих в храме недалеко от входа, сможет найти применение этой реликвии.','Принесите древний киражский артефакт драконам, которые укрылись в храме, недалеко от входа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секреты киражи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вам удалось обнаружить древний киражский артефакт! Возможно, один из драконов, стоящих в храме недалеко от входа, сможет найти применение этой реликвии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите древний киражский артефакт драконам, которые укрылись в храме, недалеко от входа.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8785,'Амулеты для легиона Оргриммара','Легион Оргриммара послал запрос на несколько необычные вещества. Учитывая, как хорошо они проявили себя в Силитусе, мы бы хотели как можно скорее выполнить их просьбу. Собери материалы и отнеси их троллихе по имени Шаи.','Принесите 6 мощных амулетов, 6 бутылей большого колдунства и 8 бутылок воспламеняющей смеси темной жрице Шаи к Улью Регал в Силитус. Кроме того, принесите тыловое задание IV.','Ах, да. То что нужно! Из этих веществ я сделаю особое зелье. Оно оч-чень не понравится силитидам!','Ты $Gпринес:принесла; мне все материалы?','Вернитесь к жрице Тени Шаи в Улей Регал, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Амулеты для легиона Оргриммара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Легион Оргриммара послал запрос на несколько необычные вещества. Учитывая, как хорошо они проявили себя в Силитусе, мы бы хотели как можно скорее выполнить их просьбу. Собери материалы и отнеси их троллихе по имени Шаи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 мощных амулетов, 6 бутылей большого колдунства и 8 бутылок воспламеняющей смеси темной жрице Шаи к Улью Регал в Силитус. Кроме того, принесите тыловое задание IV.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, да. То что нужно! Из этих веществ я сделаю особое зелье. Оно оч-чень не понравится силитидам!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне все материалы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Тени Шаи в Улей Регал, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8786,'Нехватка оружия','Легион Оргриммара послал запрос на поставку оружия, а его нет на складе! Добудь необходимое снаряжение и отнеси его Мероку Дальнему Пути к Улью Регал.','Принесите 3 массивных железных топора Мероку Дальнему Пути в лагерь легиона Оргриммара рядом с Ульем Регал. Кроме того, сдайте тыловую задачу VI.','Превосходная работа. Нам их не хватало, $N.','У тебя есть что-то для меня, $N?','Вернитесь к Мероку Дальнему Пути в Улей Регал, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нехватка оружия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Легион Оргриммара послал запрос на поставку оружия, а его нет на складе! Добудь необходимое снаряжение и отнеси его Мероку Дальнему Пути к Улью Регал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 массивных железных топора Мероку Дальнему Пути в лагерь легиона Оргриммара рядом с Ульем Регал. Кроме того, сдайте тыловую задачу VI.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходная работа. Нам их не хватало, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мероку Дальнему Пути в Улей Регал, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8787,'Комплекты брони','В Силитус, к нам на подмогу, прибыли отважные добровольцы из легиона Оргриммара. По пути они растеряли свои запасы накладок на доспехи. Добудь партию таких комплектов и отнеси их Мероку Дальнему Пути, в лагерь легиона Оргриммара.','Принесите 8 комплектов накладок из грубой кожи и 8 комплектов накладок из толстой кожи Мероку Дальнему Пути к Улью Регал. Кроме того, сдайте тыловую задачу VII.','Отлично... Я раздам все комплекты солдатам. Легион Оргриммара благодарит тебя, $N!','У тебя есть что-то для меня, $N?','Вернитесь к Мероку Дальнему Пути в Улей Регал, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Комплекты брони',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Силитус, к нам на подмогу, прибыли отважные добровольцы из легиона Оргриммара. По пути они растеряли свои запасы накладок на доспехи. Добудь партию таких комплектов и отнеси их Мероку Дальнему Пути, в лагерь легиона Оргриммара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 комплектов накладок из грубой кожи и 8 комплектов накладок из толстой кожи Мероку Дальнему Пути к Улью Регал. Кроме того, сдайте тыловую задачу VII.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично... Я раздам все комплекты солдатам. Легион Оргриммара благодарит тебя, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мероку Дальнему Пути в Улей Регал, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8788,'Слегка помятый подарок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слегка помятый подарок',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8789,'Киражское императорское оружие','Мы не то чтобы просто сидели здесь на протяжении тысячелетий, $n.$B$BМы наблюдали за торжеством этих тварей, пока они пировали и истощали свои ресурсы. Мы слушали, как они строят схемы и планы по уничтожению нашего мира. Мы узнали о предателях в их рядах.$B$BУ них есть слабости, и теперь мы знаем, как их использовать.$B$BНайди и принеси мне их церемониальное оружие. В сочетании с предметами, созданными непостоянством их собственного бога, оно станет силой, с которой придется считаться любому.','Аригос в Храме Ан\'Киража создаст для вас усиленное элементием оружие, если вы принесете ему киражское имперское оружие и 3 куска элементиевой руды.','Это оружие, усиленное элементием, одинаково легко пронзит как обычного киражи, так и их бога.','Вернитесь к Аригосу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Киражское императорское оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не то чтобы просто сидели здесь на протяжении тысячелетий, $n.$B$BМы наблюдали за торжеством этих тварей, пока они пировали и истощали свои ресурсы. Мы слушали, как они строят схемы и планы по уничтожению нашего мира. Мы узнали о предателях в их рядах.$B$BУ них есть слабости, и теперь мы знаем, как их использовать.$B$BНайди и принеси мне их церемониальное оружие. В сочетании с предметами, созданными непостоянством их собственного бога, оно станет силой, с которой придется считаться любому.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аригос в Храме Ан\'Киража создаст для вас усиленное элементием оружие, если вы принесете ему киражское имперское оружие и 3 куска элементиевой руды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это оружие, усиленное элементием, одинаково легко пронзит как обычного киражи, так и их бога.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аригосу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8790,'Киражские императорские регалии','Аригос предполагает, что элемент, рожденный в результате столкновения между древними богами и их прислужниками, в надлежащих условиях станет для них смертельным. Я имею в виду элементий, $gсмертный:смертная;.$B$BПринеси мне киражские императорские регалии и это вещество-яд, я и смогу создать оружие, обладающее великой силой.','Меритра из Сна в Храме Ан\'Киража может создать для вас усиленное элементием оружие, если вы принесете ей киражские имперские регалии и 3 куска элементиевой руды.','Ты сокрушишь их и освободишь нас от этих оков.','Вернитесь к Меритре из Сна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Киражские императорские регалии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Аригос предполагает, что элемент, рожденный в результате столкновения между древними богами и их прислужниками, в надлежащих условиях станет для них смертельным. Я имею в виду элементий, $gсмертный:смертная;.$B$BПринеси мне киражские императорские регалии и это вещество-яд, я и смогу создать оружие, обладающее великой силой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Меритра из Сна в Храме Ан\'Киража может создать для вас усиленное элементием оружие, если вы принесете ей киражские имперские регалии и 3 куска элементиевой руды.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты сокрушишь их и освободишь нас от этих оков.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Меритре из Сна.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8791,'Повергнутый Оссириан','Смертельная угроза больше не нависает над нами. Безжалостный Оссириан повержен!$B$BОб этой победе должны узнать все жители Калимдора. Отнесите голову Оссириана командиру Мар\'алиту в Крепость Кенария.','Принесите голову Оссириана Неуязвимого командиру Мар\'алиту в Крепость Кенария.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повергнутый Оссириан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Смертельная угроза больше не нависает над нами. Безжалостный Оссириан повержен!$B$BОб этой победе должны узнать все жители Калимдора. Отнесите голову Оссириана командиру Мар\'алиту в Крепость Кенария.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Оссириана Неуязвимого командиру Мар\'алиту в Крепость Кенария.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8792,'Приветствую! Хорошо, что ты $gрешил:решила; поговорить со мной. Если мы хотим достойно подготовиться к ан\'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не след оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, $n!$B$BПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, |3-6($c)? Примешь участие в этом жизненно важном деле?','Поговорите с вождем Горчуком на Аллее Духов Оргриммара.','Тромька, $C! Приятно видеть, что так много представителей Орды,как ты,$N, выступают, чтобы оказать свою поддержку в предстоящей Ан\'киражской войне. Наши старания гарантируют, что мы победим силитидов и их злых хозяев, скрытых внутри Ан\'Киража.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую! Хорошо, что ты $gрешил:решила; поговорить со мной. Если мы хотим достойно подготовиться к ан\'киражской войне, то Орде должны помогать все, кто может. Вот и тебе не след оставаться в стороне. Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться, $n!$B$BПоговори с тем, кто отвечает за заготовки, – с вождем Горчуком. Ну как, что скажешь, |3-6($c)? Примешь участие в этом жизненно важном деле?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вождем Горчуком на Аллее Духов Оргриммара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тромька, $C! Приятно видеть, что так много представителей Орды,как ты,$N, выступают, чтобы оказать свою поддержку в предстоящей Ан\'киражской войне. Наши старания гарантируют, что мы победим силитидов и их злых хозяев, скрытых внутри Ан\'Киража.',`offerrewardtext_loc8`);
