INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8829,'Последняя хитрость','Сумеречный Молот действует путем обмана и тайных наветов. Хотя они действуют в нашем мире, их идеи рождаются за его пределами, куда мы прежде не могли добраться.$b$bМы пришли к заключению, что камни, которыми главари Сумеречного Молота пользуются для призывания своих повелителей, работают в обе стороны. Чтобы попытаться воспользоваться ими подобным образом, мы должны изготовить точнейшую копию одеяния посланника культа Сумеречного Молота.$b$bСобери все необходимые материалы и отнеси их Аурэль Золотой Лист, $n.','Принесите шкуру тени, 3 истлевшие шовные нити поганища и 1 одеяние сумеречного сектанта Аурэль Золотой Лист в Крепость Кенария в Силитусе. Кроме того, сдайте тыловую задачу XI.','Да, думаю, собранных тобой материалов хватит. Я окрашу это одеяние в цвета, которые носят посланники Сумеречного Молота. Да поможет Элуна вновь обмануть наших врагов.$B$BНо не беспокойся, когда ты выполнишь свою роль в этой игре, то получишь достойную награду. Ты $Gверный:верная; и $Gдостойный:достойная; $Gсоюзник:союзница;, $N.','У тебя есть что-то для меня, $N?','Вернитесь к Аурели Золотому Листу в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последняя хитрость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сумеречный Молот действует путем обмана и тайных наветов. Хотя они действуют в нашем мире, их идеи рождаются за его пределами, куда мы прежде не могли добраться.$b$bМы пришли к заключению, что камни, которыми главари Сумеречного Молота пользуются для призывания своих повелителей, работают в обе стороны. Чтобы попытаться воспользоваться ими подобным образом, мы должны изготовить точнейшую копию одеяния посланника культа Сумеречного Молота.$b$bСобери все необходимые материалы и отнеси их Аурэль Золотой Лист, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите шкуру тени, 3 истлевшие шовные нити поганища и 1 одеяние сумеречного сектанта Аурэль Золотой Лист в Крепость Кенария в Силитусе. Кроме того, сдайте тыловую задачу XI.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, думаю, собранных тобой материалов хватит. Я окрашу это одеяние в цвета, которые носят посланники Сумеречного Молота. Да поможет Элуна вновь обмануть наших врагов.$B$BНо не беспокойся, когда ты выполнишь свою роль в этой игре, то получишь достойную награду. Ты $Gверный:верная; и $Gдостойный:достойная; $Gсоюзник:союзница;, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аурели Золотому Листу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8830,'Один рекомендательный жетон','Отлично – твои подвиги записаны, и тебе воздастся по заслугам. Продолжай в том же духе, $C!$B$BЕсли ты хочешь сдать еще несколько жетонов, я с радостью их приму.','Один рекомендательный жетон позволяет немного улучшить отношение жителей Штормграда к сдавшему его искателю приключений.$B$BИмей в виду, что лучше сдавать разом десять жетонов, это гораздо выгоднее. У тех же, кто заработал не так много жетонов, мы принимаем их по одному.$B$BНу вот, я тебя предупредил, а теперь готов помочь, если ты все же хочешь сдать мне один жетон.','Вернитесь к офицеру Лунному Свету в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Один рекомендательный жетон',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично – твои подвиги записаны, и тебе воздастся по заслугам. Продолжай в том же духе, $C!$B$BЕсли ты хочешь сдать еще несколько жетонов, я с радостью их приму.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Один рекомендательный жетон позволяет немного улучшить отношение жителей Штормграда к сдавшему его искателю приключений.$B$BИмей в виду, что лучше сдавать разом десять жетонов, это гораздо выгоднее. У тех же, кто заработал не так много жетонов, мы принимаем их по одному.$B$BНу вот, я тебя предупредил, а теперь готов помочь, если ты все же хочешь сдать мне один жетон.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к офицеру Лунному Свету в Дарнас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8831,'Десять рекомендательных жетонов','Отлично! Чтобы получить такое количество жетонов, тебе пришлось многим пожертвовать, но и награда будет велика. Благодаря таким искателям приключений, как ты, мир меняется к лучшему.$B$BСообщи, если у тебя появятся новые жетоны - я с радостью приму любое количество.','Я принимаю от искателей приключений рекомендательные жетоны, полученные за выполнение долга. За каждые десять отношение жителей Штормграда к тебе существенно улучшится. Я также принимаю такие жетоны по одному, но по более низкой ставке. Мы больше ценим великие подвиги, чем малые, хотя ни один не остается без внимания.$B$BИтак, я готов с радостью принять от тебя комплект жетонов.','Вернитесь к офицеру Лунному Свету в Дарнас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Десять рекомендательных жетонов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Чтобы получить такое количество жетонов, тебе пришлось многим пожертвовать, но и награда будет велика. Благодаря таким искателям приключений, как ты, мир меняется к лучшему.$B$BСообщи, если у тебя появятся новые жетоны - я с радостью приму любое количество.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я принимаю от искателей приключений рекомендательные жетоны, полученные за выполнение долга. За каждые десять отношение жителей Штормграда к тебе существенно улучшится. Я также принимаю такие жетоны по одному, но по более низкой ставке. Мы больше ценим великие подвиги, чем малые, хотя ни один не остается без внимания.$B$BИтак, я готов с радостью принять от тебя комплект жетонов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к офицеру Лунному Свету в Дарнас.',`completedtext_loc8`);
