INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8837,'Десять рекомендательных жетонов','Отлично! Чтобы получить такое количество жетонов, тебе пришлось многим пожертвовать, но и награда будет велика. Благодаря таким искателям приключений, как ты, мир меняется к лучшему.$B$BСообщи, если у тебя появятся новые жетоны - я с радостью приму любое количество.','Я принимаю от искателей приключений рекомендательные жетоны, полученные за выполнение долга. За каждые десять отношение жителей Дарнасса к тебе существенно улучшится. Я также принимаю такие жетоны по одному, но по более низкой ставке. Мы больше ценим великие подвиги, чем малые, хотя ни один не остается без внимания.$B$BИтак, я готов с радостью принять от тебя комплект жетонов.','Вернитесь к офицеру Малуфу в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Десять рекомендательных жетонов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Чтобы получить такое количество жетонов, тебе пришлось многим пожертвовать, но и награда будет велика. Благодаря таким искателям приключений, как ты, мир меняется к лучшему.$B$BСообщи, если у тебя появятся новые жетоны - я с радостью приму любое количество.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я принимаю от искателей приключений рекомендательные жетоны, полученные за выполнение долга. За каждые десять отношение жителей Дарнасса к тебе существенно улучшится. Я также принимаю такие жетоны по одному, но по более низкой ставке. Мы больше ценим великие подвиги, чем малые, хотя ни один не остается без внимания.$B$BИтак, я готов с радостью принять от тебя комплект жетонов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к офицеру Малуфу в Штормград.',`completedtext_