INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8838,'Один рекомендательный жетон','Отлично – твои подвиги записаны, и тебе воздастся по заслугам. Продолжай в том же духе, $C!$B$BЕсли ты хочешь сдать еще несколько жетонов, я с радостью их приму.','Один рекомендательный жетон позволяет немного улучшить отношение жителей Гномрегана к сдавшему его искателю приключений.$B$BИмей в виду, что лучше сдавать разом десять жетонов, это гораздо выгоднее. У тех же, кто заработал не так много жетонов, мы принимаем их по одному.$B$BНу вот, я тебя предупредил, а теперь готов помочь, если ты все же хочешь сдать мне один жетон.','Вернитесь к офицеру Бифштеккеру в Болотину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Один рекомендательный жетон',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично – твои подвиги записаны, и тебе воздастся по заслугам. Продолжай в том же духе, $C!$B$BЕсли ты хочешь сдать еще несколько жетонов, я с радостью их приму.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Один рекомендательный жетон позволяет немного улучшить отношение жителей Гномрегана к сдавшему его искателю приключений.$B$BИмей в виду, что лучше сдавать разом десять жетонов, это гораздо выгоднее. У тех же, кто заработал не так много жетонов, мы принимаем их по одному.$B$BНу вот, я тебя предупредил, а теперь готов помочь, если ты все же хочешь сдать мне один жетон.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к офицеру Бифштеккеру в Болотину.',`completedtext_loc8`);
