INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8856,'Неприкосновенный запас','В Крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих наборов для выживания в пустыне и отнеси их Каландрате в Крепость Кенария.','Принесите 4 сферы воды, 4 мощных противоядия и 4 печеных лосося Каландрате в таверну в Крепости Кенария в Силитусе.','Вернитесь к Каландрате в Улей Аши, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприкосновенный запас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Крепость Кенария прибыли новые добровольцы, и мы должны позаботиться, чтобы они выжили в пустыне. Новичкам грозит обезвоживание и множество ядовитых тварей. Собери как можно больше составляющих наборов для выживания в пустыне и отнеси их Каландрате в Крепость Кенария.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 сферы воды, 4 мощных противоядия и 4 печеных лосося Каландрате в таверну в Крепости Кенария в Силитусе.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каландрате в Улей Аши, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8857,'Тайны колосса – Аши','Мне нужны закаленные в бою искатели приключений, которые согласятся принести свежие образцы панциря павшего колосса Аши Карлсу в Пиратскую Бухту. Нет-нет, я не прошу подходить к телу этой твари. Возьми один из образцов у меня и поспеши. Тухлятина ему не годится!','Отнесите фрагмент панциря колосса Аши Карлсу Пропеллерзу в Пиратскую Бухту.','Ох, сколько же я наделаю цыплят из этого отличного панциря! Молодец, $Gмой:моя; $Gмальчик:девочка;!','Да? Что это у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны колосса – Аши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужны закаленные в бою искатели приключений, которые согласятся принести свежие образцы панциря павшего колосса Аши Карлсу в Пиратскую Бухту. Нет-нет, я не прошу подходить к телу этой твари. Возьми один из образцов у меня и поспеши. Тухлятина ему не годится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите фрагмент панциря колосса Аши Карлсу Пропеллерзу в Пиратскую Бухту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, сколько же я наделаю цыплят из этого отличного панциря! Молодец, $Gмой:моя; $Gмальчик:девочка;!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Что это у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8858,'Тайны колосса – Регал','Я бы с радостью сунул этот панцирь прямо в наглую рожу Скользкорука... Только вот мне не выбраться, я собираю образцы этого тараканища. И судя по его размерам, провожусь еще лет сто.$b$bОтнеси этот образец Скользкоруку, и побыстрее. Он платит МНОГО!$b$bА вот его адресок: Лагерь Братства Тория – он в Тлеющем ущелье.','Отнесите фрагмент панциря колосса Регала надзирателю Скользоруку в Тлеющем ущелье.','Великолепно. Из этого хитина можно сделать необыкновенно мощный доспех. Вот обещанные богатства.','Хммм…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны колосса – Регал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бы с радостью сунул этот панцирь прямо в наглую рожу Скользкорука... Только вот мне не выбраться, я собираю образцы этого тараканища. И судя по его размерам, провожусь еще лет сто.$b$bОтнеси этот образец Скользкоруку, и побыстрее. Он платит МНОГО!$b$bА вот его адресок: Лагерь Братства Тория – он в Тлеющем ущелье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите фрагмент панциря колосса Регала надзирателю Скользоруку в Тлеющем ущелье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно. Из этого хитина можно сделать необыкновенно мощный доспех. Вот обещанные богатства.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хммм…',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8859,'Тайны колосса – Зора','Моих слуг едва не убили при попытке добыть эти образцы. Не медли ни минуты! Лорд Максвелл Тиросс с нетерпением ждет свежих образцов панцирей. Он надеется, что тайны Колосса помогут нам в войне с Плетью!$b$bТы еще тут?! Вперед, в часовню Последней Надежды! Да, ты получишь неплохую награду за труды...','Отнесите фрагмент панциря колосса Зоры лорду Максвеллу Тироссу в Часовню Последней Надежды в Восточных Чумных землях.','Отлично, и как раз вовремя! $GМолодец:Умница;.','Что-то ты тяжело ступаешь, дружище.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны колосса – Зора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моих слуг едва не убили при попытке добыть эти образцы. Не медли ни минуты! Лорд Максвелл Тиросс с нетерпением ждет свежих образцов панцирей. Он надеется, что тайны Колосса помогут нам в войне с Плетью!$b$bТы еще тут?! Вперед, в часовню Последней Надежды! Да, ты получишь неплохую награду за труды...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите фрагмент панциря колосса Зоры лорду Максвеллу Тироссу в Часовню Последней Надежды в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, и как раз вовремя! $GМолодец:Умница;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что-то ты тяжело ступаешь, дружище.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (8860,'Отмечаем Новый Год!','Отнесите припасы Пастбищ Дымного Леса хозяйке таверны Аллисон в Штормград.','Приветствую! Хочешь покутить? Или, может быть, сначала предпочтешь отдохнуть?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отмечаем Новый Год!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите припасы Пастбищ Дымного Леса хозяйке таверны Аллисон в Штормград.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую! Хочешь покутить? Или, может быть, сначала предпочтешь отдохнуть?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (8861,'Отмечаем Новый Год!','Отнесите припасы Пастбищ Дымного Леса хозяйке таверны Пале в Громовой Утес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отмечаем Новый Год!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите припасы Пастбищ Дымного Леса хозяйке таверны Пале в Громовой Утес.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8862,'Свеча Элуны','Что ж, я принимаю эти монеты предков. Пожалуйста, возьми свечу Элуны с моего благословения. Также, пожалуйста, насладитесь этим бесплатным фейерверком.$B$BПусть твой Лунный праздник будет радостным и наполненным весельем, $N.$B$BИ если вы решите сразиться с Оменом и его приспешниками, свеча Элуны вам пригодится...','Свеча Элуны - артефакт, вызывающий большое почтение учеников Лунного фестиваля. В свече хранится настоящий лунный свет!$B$BЭтот свет безвреден для большинства существ, но ты обнаружишь, что Омен и его приспешники обожжены и ослеплены им.','Вернитесь к Валадару Звездной Песне на Лунную поляну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свеча Элуны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, я принимаю эти монеты предков. Пожалуйста, возьми свечу Элуны с моего благословения. Также, пожалуйста, насладитесь этим бесплатным фейерверком.$B$BПусть твой Лунный праздник будет радостным и наполненным весельем, $N.$B$BИ если вы решите сразиться с Оменом и его приспешниками, свеча Элуны вам пригодится...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Свеча Элуны - артефакт, вызывающий большое почтение учеников Лунного фестиваля. В свече хранится настоящий лунный свет!$B$BЭтот свет безвреден для большинства существ, но ты обнаружишь, что Омен и его приспешники обожжены и ослеплены им.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валадару Звездной Песне на Лунную поляну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8863,'Праздничные клецки','Замечательно! Наслаждайся клецками и прими мои поздравления. Хотя это всего лишь крохи благодарности по сравнению с той славой, которой ты покрыл себя, свершая великие деяния, мне кажется, что они тебе все равно понравятся.$B$BА если бы у тебя были еще монетки наследия, то у меня нашлось бы для тебя много интересных вещей.','Вернитесь к Валадару Звездной Песне на Лунную поляну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Праздничные клецки',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Наслаждайся клецками и прими мои поздравления. Хотя это всего лишь крохи благодарности по сравнению с той славой, которой ты покрыл себя, свершая великие деяния, мне кажется, что они тебе все равно понравятся.$B$BА если бы у тебя были еще монетки наследия, то у меня нашлось бы для тебя много интересных вещей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валадару Звездной Песне на Лунную поляну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8864,'Платья Лунного фестиваля','Отлично – беру эти монеты наследия. Бери платье и мое благословение. И полюбуйся, пожалуйста, праздничным фейерверком.$B$BТочно так же, как ты $Gпринес:принесла; честь и славу своим старшим, ты $Gоказал:оказала; честь и мне, посетив меня. Спасибо тебе, и радостного Лунного фестиваля!','У меня есть выбор одеяний, которые могли бы заинтересовать тебя. Такие одежды носили в прежние времена во время Лунного фестиваля, и те, что есть у меня, может, лучшие из тех что мне приходилось видеть. Каждое одеяние – ручной работы, сделано только из лучших и тончайших материалов.$B$BЗа несколько монет наследия я дам тебе выбрать любое из трех модных одеяний, что держу для себя. Идет?','Вернитесь к Валадару Звездной Песне на Лунную поляну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Платья Лунного фестиваля',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично – беру эти монеты наследия. Бери платье и мое благословение. И полюбуйся, пожалуйста, праздничным фейерверком.$B$BТочно так же, как ты $Gпринес:принесла; честь и славу своим старшим, ты $Gоказал:оказала; честь и мне, посетив меня. Спасибо тебе, и радостного Лунного фестиваля!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня есть выбор одеяний, которые могли бы заинтересовать тебя. Такие одежды носили в прежние времена во время Лунного фестиваля, и те, что есть у меня, может, лучшие из тех что мне приходилось видеть. Каждое одеяние – ручной работы, сделано только из лучших и тончайших материалов.$B$BЗа несколько монет наследия я дам тебе выбрать любое из трех модных одеяний, что держу для себя. Идет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валадару Звездной Песне на Лунную поляну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8865,'Костюмы Лунного фестиваля','Идет – я беру эти монеты наследия. Бери этот брючный костюм и мое благословение. И полюбуся, пожалуйста, праздничным фейерверком!$B$BЕсли у тебя найдется еще несколько монет наследия, обращайся ко мне. Я буду продавать разные вещи в течение всего Лунного фестиваля.','Мне приятно поведать тебе, что у меня есть прекрасный выбор праздничных брючных костюмов, которые ты можешь купить для себя... но только за монеты наследия. Если для тебя имеет значение мода, то это как раз то, что ты ищешь! Заверяю тебя – таких брючных костюмов больше нигде не сыщешь!$B$BЗа несколько монет наследия я позволю тебе выбрать из трех костюмов, которые держу для себя. Идет?','Вернитесь к Валадару Звездной Песне на Лунную поляну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Костюмы Лунного фестиваля',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Идет – я беру эти монеты наследия. Бери этот брючный костюм и мое благословение. И полюбуся, пожалуйста, праздничным фейерверком!$B$BЕсли у тебя найдется еще несколько монет наследия, обращайся ко мне. Я буду продавать разные вещи в течение всего Лунного фестиваля.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне приятно поведать тебе, что у меня есть прекрасный выбор праздничных брючных костюмов, которые ты можешь купить для себя... но только за монеты наследия. Если для тебя имеет значение мода, то это как раз то, что ты ищешь! Заверяю тебя – таких брючных костюмов больше нигде не сыщешь!$B$BЗа несколько монет наследия я позволю тебе выбрать из трех костюмов, которые держу для себя. Идет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валадару Звездной Песне на Лунную поляну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8866,'Предок Бронзобород','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предок Бронзобород',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно знать, что народ этих земель все еще отдает дань уважения древним расам. Всего хорошего, $n. Прими этот знак...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (8867,'Лунный фейерверк','Каждый год друиды Лунной поляны празднуют торжество своего города над древним злом.$b$bМы вспоминаем о мудрости старейшин, наслаждаемся пирами и, разумеется, пускаем фейерверки!$b$bЗа небольшое пожертвование ты можешь приобрести разноцветные ракеты у наших торговцев и запустить их с помощью пусковых установок.','Вернитесь к предвестнице Лунного фестиваля.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лунный фейерверк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каждый год друиды Лунной поляны празднуют торжество своего города над древним злом.$b$bМы вспоминаем о мудрости старейшин, наслаждаемся пирами и, разумеется, пускаем фейерверки!$b$bЗа небольшое пожертвование ты можешь приобрести разноцветные ракеты у наших торговцев и запустить их с помощью пусковых установок.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнице Лунного фестиваля.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (8868,'Благословение Элуны','Этот проклятый демон, Омен, был некогда героем нашего мира. Волк великой силы, баловень удачи, Омен сражался плечом к плечу с героями Войны древних, пока не попал под власть демонический магии. Обратившись против своих союзников, он в ярости рыскал по Азероту, сея вокруг себя смерть и ужас.$B$BНаконец, побежденный здесь, в Лунной поляне, Омен ныне спит под илом озера Элуне\'ара. Но каждый год во время праздника он пробуждается... $B$BСобирай соратников, $n, вызови на бой и порази исчадие тьмы, Омена. Заслужи благословение Элуны!','Призовите Омена, одержите над ним победу и получите благословение Элуны. Вернитесь к Валадару Звездной Песне в Ночную Гавань.','Получите благословение Элуны','Вернитесь к Валадару Звездной Песне в Ночную Гавань, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение Элуны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот проклятый демон, Омен, был некогда героем нашего мира. Волк великой силы, баловень удачи, Омен сражался плечом к плечу с героями Войны древних, пока не попал под власть демонический магии. Обратившись против своих союзников, он в ярости рыскал по Азероту, сея вокруг себя смерть и ужас.$B$BНаконец, побежденный здесь, в Лунной поляне, Омен ныне спит под илом озера Элуне\'ара. Но каждый год во время праздника он пробуждается... $B$BСобирай соратников, $n, вызови на бой и порази исчадие тьмы, Омена. Заслужи благословение Элуны!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите Омена, одержите над ним победу и получите благословение Элуны. Вернитесь к Валадару Звездной Песне в Ночную Гавань.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Получите благословение Элуны',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Валадару Звездной Песне в Ночную Гавань, что на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (8869,'Секрет безмятежности','В казематах Бастиона Алого ордена таится секрет безмятежности. Молотобоец из Багрового Легиона стережет его как зеницу ока. Срази его и принеси мне его фартук. За это я открою тебе секреты школы Молота.$B$BНо запомни. Если ты выберешь это умение, Школы Меча и Топора будут для тебя закрыты.','Отправляйтесь в Стратхольм и убейте молотобойца из Багрового Легиона. Возьмите его фартук и возвращайтесь к Лилит.','Вернитесь к Лилит Гибкой в Круговзор, что в Зимних Ключах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Секрет безмятежности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В казематах Бастиона Алого ордена таится секрет безмятежности. Молотобоец из Багрового Легиона стережет его как зеницу ока. Срази его и принеси мне его фартук. За это я открою тебе секреты школы Молота.$B$BНо запомни. Если ты выберешь это умение, Школы Меча и Топора будут для тебя закрыты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Стратхольм и убейте молотобойца из Багрового Легиона. Возьмите его фартук и возвращайтесь к Лилит.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лилит Гибкой в Круговзор, что в Зимних Ключах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8870,'Лунный фестиваль','Время веселиться, $n! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.','Поговорите с предвестницей Лунного фестиваля в Палатах Магии Стальгорна. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.','Добро пожаловать, $N. Ты $Gпришел:пришла;, чтобы праздновать вместе с нами?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лунный фестиваль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время веселиться, $n! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предвестницей Лунного фестиваля в Палатах Магии Стальгорна. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать, $N. Ты $Gпришел:пришла;, чтобы праздновать вместе с нами?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (8871,'Лунный фестиваль','Время веселиться, $n! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.','Поговорите с предвестницей Лунного фестиваля в Штормграде.','Приветствую и добро пожаловать, мадам! Не желаете ли отведать наших знаменитых вин?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лунный фестиваль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время веселиться, $n! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предвестницей Лунного фестиваля в Штормграде.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую и добро пожаловать, мадам! Не желаете ли отведать наших знаменитых вин?',`requestitemstext_loc8`);
