INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8875,'Лунный фестиваль','Время веселиться, $n! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.','Поговорите с предвестницей Лунного фестиваля на вершине Старейшин Громового Утеса. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.','Добро пожаловать, $N. Ты $Gпришел:пришла;, чтобы праздновать вместе с нами?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лунный фестиваль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Время веселиться, $n! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале. В городе ты найдешь предвестницу Лунного фестиваля – ее расположение отмечено кругом благословенного лунного света. Она расскажет тебе больше об этом празднике.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предвестницей Лунного фестиваля на вершине Старейшин Громового Утеса. Вы можете также поговорить с предвестницами Лунного фестиваля в других столичных городах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать, $N. Ты $Gпришел:пришла;, чтобы праздновать вместе с нами?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8876,'Маленькие ракеты','О, великолепно. Вот тебе инструкция, $N, и да благословит тебя Элуна.','Вернитесь к Фариэли Песне Звезд на Лунную поляну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маленькие ракеты',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, великолепно. Вот тебе инструкция, $N, и да благословит тебя Элуна.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фариэли Песне Звезд на Лунную поляну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8877,'Пусковая установка для фейерверков','Вот, $N. Это чертеж пусковой установки для фейерверков. Ставишь ее там, где хочешь повеселиться, и приглашай друзей на праздник!','Вернитесь к Фариэли Песне Звезд на Лунную поляну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусковая установка для фейерверков',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, $N. Это чертеж пусковой установки для фейерверков. Ставишь ее там, где хочешь повеселиться, и приглашай друзей на праздник!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фариэли Песне Звезд на Лунную поляну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8878,'Праздничные выкройки','Вот твои выкройки, $N. Изделия, которые ты сошьешь благодаря им, будут вне всякого сомнения прекрасны.','Вернитесь к Фариэли Песне Звезд на Лунную поляну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Праздничные выкройки',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот твои выкройки, $N. Изделия, которые ты сошьешь благодаря им, будут вне всякого сомнения прекрасны.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фариэли Песне Звезд на Лунную поляну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8879,'Большие ракеты','Отлично, беру. Вот твои инструкции, $N. Воспользуйся ими к вящей славе Элуны!','Вернитесь к Фариэли Песне Звезд на Лунную поляну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большие ракеты',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, беру. Вот твои инструкции, $N. Воспользуйся ими к вящей славе Элуны!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фариэли Песне Звезд на Лунную поляну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (8880,'Сигнальные ракеты','Вот, $N. Бери эти чертежи и изучай их секреты. Желаю тебе удачи и надеюсь в будущем увидеть твои прекрасные творения.','Вернитесь к Фариэли Песне Звезд на Лунную поляну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сигнальные ракеты',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, $N. Бери эти чертежи и изучай их секреты. Желаю тебе удачи и надеюсь в будущем увидеть твои прекрасные творения.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фариэли Песне Звезд на Лунную поляну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8881,'Большие связки фейерверков','Спасибо, $N. Вот рецепт большой связки фейерверков. Пусть ваши товары принесут радость и удачу всем, кто на них смотрит.','Для больших сигнальных ракет требуется много ресурсов и изрядное мастерство, но их блеск и красота стоят усилий! За несколько монет наследия я поделюсь с тобой умением их создавать.','Вернитесь к Фариэли Песне Звезд на Лунную поляну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большие связки фейерверков',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Вот рецепт большой связки фейерверков. Пусть ваши товары принесут радость и удачу всем, кто на них смотрит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Для больших сигнальных ракет требуется много ресурсов и изрядное мастерство, но их блеск и красота стоят усилий! За несколько монет наследия я поделюсь с тобой умением их создавать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фариэли Песне Звезд на Лунную поляну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8882,'Пусковая установка для связок фейерверков','Вот ваша схема. Изучите её внимательно…$B$BУдачи, $N. Пусть ваши торжества будут соперничать с самим Лунным фестивалем!','Чтобы устроить самый лучший фейерверк, надо использовать многозарядные ракеты, а выпускать их надо из пусковых установок для многозарядных ракет! Разве не логично тебе будет узнать секреты сооружения пусковых установок для многозарядных ракет? Принеси мне монеты наследия, и я дам тебе это знание!','Вернитесь к Фариэли Песне Звезд на Лунную поляну.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусковая установка для связок фейерверков',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот ваша схема. Изучите её внимательно…$B$BУдачи, $N. Пусть ваши торжества будут соперничать с самим Лунным фестивалем!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чтобы устроить самый лучший фейерверк, надо использовать многозарядные ракеты, а выпускать их надо из пусковых установок для многозарядных ракет! Разве не логично тебе будет узнать секреты сооружения пусковых установок для многозарядных ракет? Принеси мне монеты наследия, и я дам тебе это знание!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фариэли Песне Звезд на Лунную поляну.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (8883,'Валадар Звездная Песня') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Валадар Звездная Песня',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8884,'Рыбьи головы, рыбьи головы...','Приветствую тебя, |3-6($c). Посмотри-ка вон туда, в сторону моря. Что ты видишь? Правильно, наш пляж... Наш Безмятежный берег. Но теперь на нем кишат гнусные твари, именуемые мурлоками!$b$bЭто оскорбление для всех нас!$b$bУ меня есть для тебя задание – если ты сочтешь, что оно тебе по плечу. Мне нужны их головы! Посмотрим; возможно, если нам удастся значительно сократить их численность, эти твари испугаются и вернутся обратно в свои темные глубины, откуда выползли!','Молодец, |3-6($C), ты неплохо потрудилась! Судя по запаху, тебе удалось добыть все, что я просил – а может, и более того. Эти головы нам еще пригодятся. На уху или еще куда-нибудь...\n\nУвы, но, боюсь, твои усилия результата не дали. Мурлоки и не думают отступать! Нам надо действовать более решительно!','Мы, следопыты из Обители Странников, делаем все, чтобы исправить урон, нанесенный нашим прекрасным землям. И ради этого мы готовы на все!\n\nНу что, где головы мурлоков?','Вернитесь к Гатвелиону Солнечному Взору в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рыбьи головы, рыбьи головы...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($c). Посмотри-ка вон туда, в сторону моря. Что ты видишь? Правильно, наш пляж... Наш Безмятежный берег. Но теперь на нем кишат гнусные твари, именуемые мурлоками!$b$bЭто оскорбление для всех нас!$b$bУ меня есть для тебя задание – если ты сочтешь, что оно тебе по плечу. Мне нужны их головы! Посмотрим; возможно, если нам удастся значительно сократить их численность, эти твари испугаются и вернутся обратно в свои темные глубины, откуда выползли!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, |3-6($C), ты неплохо потрудилась! Судя по запаху, тебе удалось добыть все, что я просил – а может, и более того. Эти головы нам еще пригодятся. На уху или еще куда-нибудь...\n\nУвы, но, боюсь, твои усилия результата не дали. Мурлоки и не думают отступать! Нам надо действовать более решительно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы, следопыты из Обители Странников, делаем все, чтобы исправить урон, нанесенный нашим прекрасным землям. И ради этого мы готовы на все!\n\nНу что, где головы мурлоков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гатвелиону Солнечному Взору в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8885,'Кольцо Мррргла','Мурлоки из племени Темной Чешуи не испугались тебя! Но я, кажется, знаю, как им отомстить – и заодно заставить их собирать вещички!$b$bУ этих мурлоков есть главарь, который зовет себя Мррргл. Он бродит по Золотистому взморью, к югу от устья реки. Эта тварь некогда убила моего земляка и теперь нагло носит его кольцо!$b$bУбей Мррргла и принеси мне кольцо моего товарища. Уж тогда-то мы сумеем запугать этих чудищ!','Наконец-то! Правда, мурлоки так и не ушли, но все же приятно было видеть, как они забегали в панике, когда ты сразила их так называемого "вождя". Я благодарю тебя, а вместе со мной – и все син\'дорай Луносвета!\n\nПожалуйста, выбери одну из этих вещей в награду за оказанную тобой услугу!','Ты, |3-6($C), – оружие моей мести и победы! Ну что, кольцо у тебя с собой?','Вернитесь к Гатвелиону Солнечному Взору в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо Мррргла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мурлоки из племени Темной Чешуи не испугались тебя! Но я, кажется, знаю, как им отомстить – и заодно заставить их собирать вещички!$b$bУ этих мурлоков есть главарь, который зовет себя Мррргл. Он бродит по Золотистому взморью, к югу от устья реки. Эта тварь некогда убила моего земляка и теперь нагло носит его кольцо!$b$bУбей Мррргла и принеси мне кольцо моего товарища. Уж тогда-то мы сумеем запугать этих чудищ!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то! Правда, мурлоки так и не ушли, но все же приятно было видеть, как они забегали в панике, когда ты сразила их так называемого "вождя". Я благодарю тебя, а вместе со мной – и все син\'дорай Луносвета!\n\nПожалуйста, выбери одну из этих вещей в награду за оказанную тобой услугу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты, |3-6($C), – оружие моей мести и победы! Ну что, кольцо у тебя с собой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гатвелиону Солнечному Взору в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8886,'На помощь! Пираты!','Прекрасно! Ты $Gспас:спасла; меня от разорения и $Gотомстил:отомстила; этим мерзким тварям!$B$BТеперь, если мне только удастся уговорить наших славных следопытов помочь мне с грузом, я наконец-то выберусь отсюда! Надо было вернуться сразу, как только Велендрис сумел отбить верфь.$B$BВот, возьми. Большего я себе позволить не могу, но должна же я хоть как-то вознаградить тебя за труды!','Спасибо тебе за помощь, $N! Я даже могу улыбаться, впервые за много дней. Но как подумаю, что эти чудища сделали с моим кораблем и что происходит с Кель\'Таласом...$B$BНу что, тебе удалось найти хотя бы часть груза?','Вернитесь к капитану Келисендре в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На помощь! Пираты!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Ты $Gспас:спасла; меня от разорения и $Gотомстил:отомстила; этим мерзким тварям!$B$BТеперь, если мне только удастся уговорить наших славных следопытов помочь мне с грузом, я наконец-то выберусь отсюда! Надо было вернуться сразу, как только Велендрис сумел отбить верфь.$B$BВот, возьми. Большего я себе позволить не могу, но должна же я хоть как-то вознаградить тебя за труды!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Спасибо тебе за помощь, $N! Я даже могу улыбаться, впервые за много дней. Но как подумаю, что эти чудища сделали с моим кораблем и что происходит с Кель\'Таласом...$B$BНу что, тебе удалось найти хотя бы часть груза?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Келисендре в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (8888,'Ученица магистра','Ах, магистр обо мне тревожится? Как это мило. Лучше бы он обо мне побеспокоился раньше, когда мы были еще в замке!\n\nНу, неважно. Пожалуйста, |3-6($C), выслушай меня внимательно. Мне придется попросить тебя об услуге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ученица магистра',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, магистр обо мне тревожится? Как это мило. Лучше бы он обо мне побеспокоился раньше, когда мы были еще в замке!\n\nНу, неважно. Пожалуйста, |3-6($C), выслушай меня внимательно. Мне придется попросить тебя об услуге.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8889,'Отключить замок','Удалось ли тебе отключить источники энергии? Мне отсюда плохо видно...','Вернитесь к ученице Лоралталис в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отключить замок',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе отключить источники энергии? Мне отсюда плохо видно...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученице Лоралталис в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8890,'Весточка из замка','О нет! Значит, я опоздал... Это все моя вина.\n\nМои исследования альтернативных источников магии зашли слишком далеко, прежде чем я догадался положить этому конец. Если бы только я отправился туда сам... или если бы они вняли моим предупреждениям!\n\nИх судьба на моей совести, |3-6($C). Но все равно, я благодарю тебя за то, что ты помогла истерзанным душам моих бывших учеников обрести покой. Меня отчасти утешает то, что они недолго пребывали в этом состоянии, которое для эльфа хуже смерти.','Что это? Какая знакомая тетрадка... О нет! Этот журнал... мои исследования... с них-то все и началось!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Весточка из замка',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О нет! Значит, я опоздал... Это все моя вина.\n\nМои исследования альтернативных источников магии зашли слишком далеко, прежде чем я догадался положить этому конец. Если бы только я отправился туда сам... или если бы они вняли моим предупреждениям!\n\nИх судьба на моей совести, |3-6($C). Но все равно, я благодарю тебя за то, что ты помогла истерзанным душам моих бывших учеников обрести покой. Меня отчасти утешает то, что они недолго пребывали в этом состоянии, которое для эльфа хуже смерти.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это? Какая знакомая тетрадка... О нет! Этот журнал... мои исследования... с них-то все и началось!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (8891,'Неоконченное исследование','Что это? Какая знакомая тетрадка... О нет! Этот журнал... мои исследования... с них-то все и началось!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неоконченное исследование',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это? Какая знакомая тетрадка... О нет! Этот журнал... мои исследования... с них-то все и началось!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8892,'Причал Солнечного Паруса захватили Презренные. Как только мы сумеем подвести туда подкрепление, мы покажем этим уродам, почем фунт лиха!$b$bА пока что ты, $n, можешь нам помочь: поучи их слегка уму-разуму. Сходи туда и покажи им, что с нами шутить опасно. Причал Солнечного Паруса находится к западу от деревни Легкий Ветерок.','Пусть знают, что с нами лучше не связываться! Спасибо, $N.','Ты уже $Gпреподал:преподала; урок этим Презренным?','Вернитесь к следопыту Деголайну в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Причал Солнечного Паруса захватили Презренные. Как только мы сумеем подвести туда подкрепление, мы покажем этим уродам, почем фунт лиха!$b$bА пока что ты, $n, можешь нам помочь: поучи их слегка уму-разуму. Сходи туда и покажи им, что с нами шутить опасно. Причал Солнечного Паруса находится к западу от деревни Легкий Ветерок.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть знают, что с нами лучше не связываться! Спасибо, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gпреподал:преподала; урок этим Презренным?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к следопыту Деголайну в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8893,'Супер Яйц-О-Матик','Вернитесь к Яйц-О-Матику в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Супер Яйц-О-Матик',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Яйц-О-Матику в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8894,'Зачистка территории','Ужас, просто ужас! В замке творится неизвестно что, магистр и все его ученики разбежались, и не успели мы глазом моргнуть, как оказалось, что повсюду кишат эти магические твари! А Виллитену кто-нибудь что-нибудь сказал? Ни словечка!$b$bПослушай, |3-6($c), твой долг – помочь мне разогнать этих мерзких существ! Я не могу поддерживать порядок, пока вокруг бесчинствуют эти "аномальные явления"!','Ну, думаю, этого должно быть достаточно, не правда ли? Спасибо за помощь, |3-6($C). Могу только надеяться, что этот беспорядок окончательно ликвидируют к тому времени, как в Замок Блеклых Сумерек вернется магистр.\n\nНа вот, возьми эту мелочь. Это немного, но больше у меня при себе сейчас нет. Можешь перед уходом ликвидировать еще нескольких тварей, если тебя не затруднит.','Ну что, удалось тебе разобраться с ними? Много ли этих порождений магии тебе удалось уложить? Что же я буду делать, если магистр Блеклых Сумерек вернется, а тут повсюду эти твари?','Вернитесь к Виллитену Хранителю Земель в Земли Блеклых Сумерек, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка территории',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ужас, просто ужас! В замке творится неизвестно что, магистр и все его ученики разбежались, и не успели мы глазом моргнуть, как оказалось, что повсюду кишат эти магические твари! А Виллитену кто-нибудь что-нибудь сказал? Ни словечка!$b$bПослушай, |3-6($c), твой долг – помочь мне разогнать этих мерзких существ! Я не могу поддерживать порядок, пока вокруг бесчинствуют эти "аномальные явления"!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, думаю, этого должно быть достаточно, не правда ли? Спасибо за помощь, |3-6($C). Могу только надеяться, что этот беспорядок окончательно ликвидируют к тому времени, как в Замок Блеклых Сумерек вернется магистр.\n\nНа вот, возьми эту мелочь. Это немного, но больше у меня при себе сейчас нет. Можешь перед уходом ликвидировать еще нескольких тварей, если тебя не затруднит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе разобраться с ними? Много ли этих порождений магии тебе удалось уложить? Что же я буду делать, если магистр Блеклых Сумерек вернется, а тут повсюду эти твари?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виллитену Хранителю Земель в Земли Блеклых Сумерек, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (8895,'Послание в Северное святилище','Да, $C?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание в Северное святилище',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (8896,'Дворфийский шпион','Так ты говоришь, что эти бумаги были у ночного эльфа? Язык-то, по большей части, дворфийский...$b$bГеолог Страж Наковальни! Его прислали сюда из Стальгорна с дипломатической миссией! Мне следовало заподозрить, что он не случайно интересуется нашими волшебными святилищами! $n, отыщи этого дворфа в Северном святилище и разберись с ним. Да, и сделай это тихо!','Найдите и убейте геолога Стража Наковальни в Северном святилище, затем доложите о выполнении задания Аэльдону Озаренному Солнцем из Лесов Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дворфийский шпион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так ты говоришь, что эти бумаги были у ночного эльфа? Язык-то, по большей части, дворфийский...$b$bГеолог Страж Наковальни! Его прислали сюда из Стальгорна с дипломатической миссией! Мне следовало заподозрить, что он не случайно интересуется нашими волшебными святилищами! $n, отыщи этого дворфа в Северном святилище и разберись с ним. Да, и сделай это тихо!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и убейте геолога Стража Наковальни в Северном святилище, затем доложите о выполнении задания Аэльдону Озаренному Солнцем из Лесов Вечной Песни.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8897,'Дорогая моя Колара!','Я должен нести стражу здесь, у ворот, но я не могу выбросить из головы мысли о моей милой Коларе. В лучшем случае я могу видеться с нею лишь по несколько часов... Да и что я собой представляю? Я получаю жалованье младшего офицера и со дня на день меня могут отправить на фронт.$b$bНе забудет ли она обо мне сразу же после расставания? В городе полно мужчин, и многие из них богаты.$b$bНо, как бы то ни было, я написал тут несколько слов... в общем, ничего особенного, но я буду признателен, если ты доставишь ей эту записку от меня.','Отнесите написанную со старанием записку лейтенанта Хельдрика Коларе Дин, живущей недалеко от банка в Штормграде.','Как это мило! Он впервые догадался мне написать. Ты думаешь, он это серьезно?$B$BКолара Нельдрик? По-моему, звучит неплохо. О, но я забегаю вперед. Спасибо тебе.','Привет, $Gкрасавчик:красотка;. Я могу тебе чем-нибудь помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорогая моя Колара!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я должен нести стражу здесь, у ворот, но я не могу выбросить из головы мысли о моей милой Коларе. В лучшем случае я могу видеться с нею лишь по несколько часов... Да и что я собой представляю? Я получаю жалованье младшего офицера и со дня на день меня могут отправить на фронт.$b$bНе забудет ли она обо мне сразу же после расставания? В городе полно мужчин, и многие из них богаты.$b$bНо, как бы то ни было, я написал тут несколько слов... в общем, ничего особенного, но я буду признателен, если ты доставишь ей эту записку от меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите написанную со старанием записку лейтенанта Хельдрика Коларе Дин, живущей недалеко от банка в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как это мило! Он впервые догадался мне написать. Ты думаешь, он это серьезно?$B$BКолара Нельдрик? По-моему, звучит неплохо. О, но я забегаю вперед. Спасибо тебе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $Gкрасавчик:красотка;. Я могу тебе чем-нибудь помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8898,'Дорогая моя Колара!','В последний раз, когда я был в Штормграде по делам банка, я встретил там девушку. Она похитила мое сердце. Я не могу не думать о ней! Я хотел бы послать ей это письмо – я переписывал его двенадцать раз.$b$bПочта сейчас так загружена, а я хотел бы точно знать, что письмо попадет к ней.$b$bЕсли ты направляешься туда, то не окажешь ли мне услугу?','Отнесите смятое письмо Коларе Дин, обитающей поблизости от банка в Штормграде.','Тормек? О да, я помню его. У него была такая красивая борода, и он все время в нее улыбался.$B$BАх, поверить не могу, что он меня не забыл!','Привет, $Gкрасавчик:красотка;. Я могу тебе чем-нибудь помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорогая моя Колара!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В последний раз, когда я был в Штормграде по делам банка, я встретил там девушку. Она похитила мое сердце. Я не могу не думать о ней! Я хотел бы послать ей это письмо – я переписывал его двенадцать раз.$b$bПочта сейчас так загружена, а я хотел бы точно знать, что письмо попадет к ней.$b$bЕсли ты направляешься туда, то не окажешь ли мне услугу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите смятое письмо Коларе Дин, обитающей поблизости от банка в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тормек? О да, я помню его. У него была такая красивая борода, и он все время в нее улыбался.$B$BАх, поверить не могу, что он меня не забыл!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $Gкрасавчик:красотка;. Я могу тебе чем-нибудь помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8899,'Дорогая моя Колара!','Как описать ее красоту? Тысячи лет я учился выражать свои мысли словами, но ныне я нем. $b$bЭти смертные вводят в смущение разум и превращают нас в лепечущих чушь идиотов.$b$bЯ слишком долго смотрел на эти слова. Я больше не могу выжать из них ни капли смысла и убедительности. Нет, она должна получить это послание немедленно, или кто-нибудь другой привлечет ее внимание.','Отнесите безукоризненное письмо Коларе Дин, обитающей поблизости от банка в Штормграде.','Ничего подобного я прежде не получала. Как трогательно!','Привет, $Gкрасавчик:красотка;. Я могу тебе чем-нибудь помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорогая моя Колара!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как описать ее красоту? Тысячи лет я учился выражать свои мысли словами, но ныне я нем. $b$bЭти смертные вводят в смущение разум и превращают нас в лепечущих чушь идиотов.$b$bЯ слишком долго смотрел на эти слова. Я больше не могу выжать из них ни капли смысла и убедительности. Нет, она должна получить это послание немедленно, или кто-нибудь другой привлечет ее внимание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите безукоризненное письмо Коларе Дин, обитающей поблизости от банка в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ничего подобного я прежде не получала. Как трогательно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $Gкрасавчик:красотка;. Я могу тебе чем-нибудь помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8900,'Дорогая моя Эления!','Она была такой грустной. Я понял это, едва взглянув на выражение ее лица. Я имею в виду, она казалась грустной – понимаешь? $b$bА после того, как я поговорил с ней, возникла взаимосвязь. Я не думал, что кто-то может понять меня, но она смогла.$b$bКогда я сказал остальным, они смеялись надо мной, и потому я больше никогда с ней не заговаривал. Но я скучаю по ней. Ты не можешь отнести ей от меня письмо? Я хочу быть уверен, что оно попадет к ней в руки.','Отнесите слегка помятую записку Элении Хайдон, обитающей поблизости от банка в Подгороде.','Вот не ожидала, что орк окажется таким красноречивым. Конечно же, до нынешних времен у нас не было возможности как следует их узнать. Спасибо за доставку письма!','О, и чему я обязана такой радостью?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорогая моя Эления!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Она была такой грустной. Я понял это, едва взглянув на выражение ее лица. Я имею в виду, она казалась грустной – понимаешь? $b$bА после того, как я поговорил с ней, возникла взаимосвязь. Я не думал, что кто-то может понять меня, но она смогла.$b$bКогда я сказал остальным, они смеялись надо мной, и потому я больше никогда с ней не заговаривал. Но я скучаю по ней. Ты не можешь отнести ей от меня письмо? Я хочу быть уверен, что оно попадет к ней в руки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите слегка помятую записку Элении Хайдон, обитающей поблизости от банка в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот не ожидала, что орк окажется таким красноречивым. Конечно же, до нынешних времен у нас не было возможности как следует их узнать. Спасибо за доставку письма!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, и чему я обязана такой радостью?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8901,'Дорогая моя Эления!','Известно ли тебе, что такое любовь, $gюноша:девушка;? До недавнего времени, пока я не повстречал создание по имени Эления из Подгорода, это чувство было мне не знакомо. Таурены вообще редко обращают внимание на представителей других рас, тем более, если это кто-то из Отрекшихся. Но сейчас я днями и ночами думаю только о ней.$b$bТы не $gмог:могла; бы отнести ей это письмо? Я хочу, чтобы она приехала в Мулгор. Надеюсь, она согласится.','Отнесите написанное со старанием письмо Элении Хайдон, обитающей поблизости от банка в Подгороде.','Какие милые слова написал мне Темма! Но, хотя его слова меня тронули, я не могу всерьез рассматривать любовь таурена. Мы слишком разные по крови, разуму и духу.$B$BКак хорошо, что он не сделал мне это предложение лично. Мне было бы невыносимо разбивать ему сердце.','О, и чему я обязана такой радостью?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорогая моя Эления!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Известно ли тебе, что такое любовь, $gюноша:девушка;? До недавнего времени, пока я не повстречал создание по имени Эления из Подгорода, это чувство было мне не знакомо. Таурены вообще редко обращают внимание на представителей других рас, тем более, если это кто-то из Отрекшихся. Но сейчас я днями и ночами думаю только о ней.$b$bТы не $gмог:могла; бы отнести ей это письмо? Я хочу, чтобы она приехала в Мулгор. Надеюсь, она согласится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите написанное со старанием письмо Элении Хайдон, обитающей поблизости от банка в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какие милые слова написал мне Темма! Но, хотя его слова меня тронули, я не могу всерьез рассматривать любовь таурена. Мы слишком разные по крови, разуму и духу.$B$BКак хорошо, что он не сделал мне это предложение лично. Мне было бы невыносимо разбивать ему сердце.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, и чему я обязана такой радостью?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8902,'Дорогая моя Эления!','Целую жизнь назад я был помолвлен с девушкой по имени Эления, подругой моего детства. Прошли годы с тех пор, как я в последний раз думал о ней, но в последнее время она постоянно занимает мои мысли. $b$bБыть может даже тогда, когда все ушло, в нашей жизни все-таки остается место для любви.$b$bЯ уверен, что она тоже изменилась. Ты не передашь ей от меня письмо? Я слишком волнуюсь, чтобы передать его лично.','Отнесите проникнутое любовью письмо Элении Хайдон, обитающей поблизости от банка в Подгороде.','Это возвращает воспоминания о прошлой жизни, $N. Эления Тор.Знаешь, это должно было быть моим именем. У нас была бы красивая церемония на берегу озера.$B$BЗначит, простые мечты.$B$BНо если бы он увидел меня сейчас, я сомневаюсь, что он вообще увидел бы во мне Элению. Только холодная плоть и мертвое сердце...','О, и чему я обязана такой радостью?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорогая моя Эления!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Целую жизнь назад я был помолвлен с девушкой по имени Эления, подругой моего детства. Прошли годы с тех пор, как я в последний раз думал о ней, но в последнее время она постоянно занимает мои мысли. $b$bБыть может даже тогда, когда все ушло, в нашей жизни все-таки остается место для любви.$b$bЯ уверен, что она тоже изменилась. Ты не передашь ей от меня письмо? Я слишком волнуюсь, чтобы передать его лично.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите проникнутое любовью письмо Элении Хайдон, обитающей поблизости от банка в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это возвращает воспоминания о прошлой жизни, $N. Эления Тор.Знаешь, это должно было быть моим именем. У нас была бы красивая церемония на берегу озера.$B$BЗначит, простые мечты.$B$BНо если бы он увидел меня сейчас, я сомневаюсь, что он вообще увидел бы во мне Элению. Только холодная плоть и мертвое сердце...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, и чему я обязана такой радостью?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8903,'Опасная любовь','И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.$b$bДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.$b$bОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.','Раздобудьте открытку штормградского стражника и отдайте ее Аристану Моттару в Штормграде.','Так это правда! Просто не могу поверить. Как это могло случиться? Дай мне немного поразмыслить. За этим должны крыться какие-то причины.','Прав ли я был, когда беспокоился? Поражены ли стражи этой любовной лихорадкой?','Вернитесь к Аристану Моттару в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасная любовь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.$b$bДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.$b$bОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте открытку штормградского стражника и отдайте ее Аристану Моттару в Штормграде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так это правда! Просто не могу поверить. Как это могло случиться? Дай мне немного поразмыслить. За этим должны крыться какие-то причины.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прав ли я был, когда беспокоился? Поражены ли стражи этой любовной лихорадкой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аристану Моттару в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8904,'Опасная любовь','И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.$b$bДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.$b$bОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.','Раздобудьте заплесневелую открытку стража и отнесите ее Фенстаду Аргайлу в Подгороде.','Так это правда! Просто не могу поверить. Как это могло случиться? Дай мне немного поразмыслить. За этим должны крыться какие-то причины.','Был ли я прав, когда волновался? Наши идиоты-стражи поддались этой заразе?','Вернитесь к Фенстаду Аргайлу в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасная любовь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.$b$bДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.$b$bОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте заплесневелую открытку стража и отнесите ее Фенстаду Аргайлу в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так это правда! Просто не могу поверить. Как это могло случиться? Дай мне немного поразмыслить. За этим должны крыться какие-то причины.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Был ли я прав, когда волновался? Наши идиоты-стражи поддались этой заразе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фенстаду Аргайлу в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8905,'Серьезное предложение','Рада встрече, |3-6($c). У меня найдется кое-что интересное для тебя.$B$BЕсть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества. Я бы сменяла наручи из этого комплекта на наручи попроще за одну маленькую услугу.$B$BКровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны. Принеси мне некоторое количество этой крови, наручи и немного золота. Увидишь – твои старания окупятся.','Добудьте 15 порций крови животных Зимних Ключей и 20 золотых монет и отдайте их вместе с наручами Буйного Сердца Делиане в Стальгорне.','Великолепно! Так совершим обмен! Жалко расставаться с такими великолепными доспехами, но, боюсь, в ближайшее время они мне не понадобятся.$B$BЕсли ты согласишься выполнить для меня еще кое-какие поручения, то, может, я отдам и остальную часть комплекта.','Ты $Gпринес:принесла; мне то, о чем я просил, $N?','Вернитесь к Делиане к Высокому трону, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное предложение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рада встрече, |3-6($c). У меня найдется кое-что интересное для тебя.$B$BЕсть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества. Я бы сменяла наручи из этого комплекта на наручи попроще за одну маленькую услугу.$B$BКровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны. Принеси мне некоторое количество этой крови, наручи и немного золота. Увидишь – твои старания окупятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 15 порций крови животных Зимних Ключей и 20 золотых монет и отдайте их вместе с наручами Буйного Сердца Делиане в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Так совершим обмен! Жалко расставаться с такими великолепными доспехами, но, боюсь, в ближайшее время они мне не понадобятся.$B$BЕсли ты согласишься выполнить для меня еще кое-какие поручения, то, может, я отдам и остальную часть комплекта.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне то, о чем я просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8906,'Серьезное предложение','Рада встрече, |3-6($c). У меня найдется кое-что интересное для тебя.$B$BЕсть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества. Я бы сменяла наручи из этого комплекта на простые за одну маленькую услугу.$B$BКровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны. Принеси мне некоторое количество этой крови, наручи и немного золота. Увидишь – твои старания окупятся.','Добудьте 15 порций крови животных Зимних ключей и 20 золотых и отдайте их вместе с наручниками загонщика Делиане в Стальгорне.','Великолепно! Так совершим обмен! Жалко расставаться с такими великолепными доспехами, но, боюсь, в ближайшее время они мне не понадобятся.$B$BЕсли ты согласишься выполнить для меня еще кое-какие поручения, то, может, я отдам и остальную часть комплекта.','Ты $Gпринес:принесла; мне то, о чем я просил, $N?','Вернитесь к Делиане к Высокому трону, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Серьезное предложение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рада встрече, |3-6($c). У меня найдется кое-что интересное для тебя.$B$BЕсть у меня комплект доспехов – вроде тех, что носят такие как ты, но гораздо лучшего качества. Я бы сменяла наручи из этого комплекта на простые за одну маленькую услугу.$B$BКровь ледопардов и медведей, что водятся в Зимних Ключах, обладает важными свойствами, которые мне сейчас позарез нужны. Принеси мне некоторое количество этой крови, наручи и немного золота. Увидишь – твои старания окупятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 15 порций крови животных Зимних ключей и 20 золотых и отдайте их вместе с наручниками загон