questitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gполучил:получила; нужные мне предметы, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моквару в Оргриммар.',`completedtext_loc8`);
