INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8921,'Эктоплазматический дистиллятор','А, тебе нужен мой последний проект... спектральный сканер иных измерений! К сожалению, мне не хватает средств и сотрудников.$b$BХочешь помочь? Великолепно! Первым делом нам придется добыть самую сущность смерти! Эктоплазматический дистиллятор будет нелегко построить, $n.$b$bМне понадобится арканитовый преобразователь, несколько великих вечных субстанций и масло каменного угря. Пригодится и вулканический пепел из озер лавы в Пылающих степях – из него я сделаю фильтр.','Принести Муксу Маноскребу из Прибамбасска 1 сверхточный арканитовый преобразователь, 4 великих вечных субстанции, 10 порций масла каменного угря, 25 горстей вулканического пепла и 40 золотых.','Да, именно этих предметов мне и не хватало. Довольно таки быстро, $N!$B$BЗа считанные минуты, твой дистиллятор будет готов к работе!','Я понимаю, что очень сложно достать такие материалы... но это все необходимо нам!','Вернитесь к Муксу Маноскребу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эктоплазматический дистиллятор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, тебе нужен мой последний проект... спектральный сканер иных измерений! К сожалению, мне не хватает средств и сотрудников.$b$BХочешь помочь? Великолепно! Первым делом нам придется добыть самую сущность смерти! Эктоплазматический дистиллятор будет нелегко построить, $n.$b$bМне понадобится арканитовый преобразователь, несколько великих вечных субстанций и масло каменного угря. Пригодится и вулканический пепел из озер лавы в Пылающих степях – из него я сделаю фильтр.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принести Муксу Маноскребу из Прибамбасска 1 сверхточный арканитовый преобразователь, 4 великих вечных субстанции, 10 порций масла каменного угря, 25 горстей вулканического пепла и 40 золотых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, именно этих предметов мне и не хватало. Довольно таки быстро, $N!$B$BЗа считанные минуты, твой дистиллятор будет готов к работе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я понимаю, что очень сложно достать такие материалы... но это все необходимо нам!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муксу Маноскребу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8922,'Сверхъестественное устройство','Я должна найти способ связаться с Антионом Хармоном... точнее, с его духом!$B$BЯ знаю одного инженера, который чрезвычайно интересуется сверхъестественным. Он говорит, будто бы может соорудить машину, которая позволит ему разговаривать с духами!$B$BТа кровь, что ты $Gсобрал:собрала;, предназначается как раз ему. Поезжай в Прибамбасск и отдай ее ему в оплату услуг!','Отнесите запечатанный контейнер с кровью Муксу Маноскребу в Прибамбасск в Танарисе.','О, радость! У меня как раз запасы оскудели!$B$BГоворите, вас Делиана послала?','Вы что-то мне принесли?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сверхъестественное устройство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я должна найти способ связаться с Антионом Хармоном... точнее, с его духом!$B$BЯ знаю одного инженера, который чрезвычайно интересуется сверхъестественным. Он говорит, будто бы может соорудить машину, которая позволит ему разговаривать с духами!$B$BТа кровь, что ты $Gсобрал:собрала;, предназначается как раз ему. Поезжай в Прибамбасск и отдай ее ему в оплату услуг!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанный контейнер с кровью Муксу Маноскребу в Прибамбасск в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, радость! У меня как раз запасы оскудели!$B$BГоворите, вас Делиана послала?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы что-то мне принесли?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8923,'Сверхъестественное устройство','Ты все еще здесь? Да, храбрости тебе не занимать! Наверное, тебя заинтересовали те наручи, что я тебе дал. Да, у меня есть и другие детали такого доспеха, и ты их получишь, если будешь по-прежнему помогать мне.$b$bТот яд, что я собирал, предназначен для моего знакомого, Мукса Маноскреба. Это инженер, который увлекается всем сверхъестественным. Сейчас он пытается построить прибор, с помощью которого можно общаться с мертвыми! Я надеюсь с помощью этого прибора связаться с Антионом и получить от него совет.','Отнесите запечатанный ларчик с ядом Муксу Маноскребу в Прибамбасск.','Говоришь Моквар прислал тебя?','Хочешь поговорить со мной?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сверхъестественное устройство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты все еще здесь? Да, храбрости тебе не занимать! Наверное, тебя заинтересовали те наручи, что я тебе дал. Да, у меня есть и другие детали такого доспеха, и ты их получишь, если будешь по-прежнему помогать мне.$b$bТот яд, что я собирал, предназначен для моего знакомого, Мукса Маноскреба. Это инженер, который увлекается всем сверхъестественным. Сейчас он пытается построить прибор, с помощью которого можно общаться с мертвыми! Я надеюсь с помощью этого прибора связаться с Антионом и получить от него совет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанный ларчик с ядом Муксу Маноскребу в Прибамбасск.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говоришь Моквар прислал тебя?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Хочешь поговорить со мной?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8924,'В поисках эктоплазмы','Отличная конструкция, вот что я скажу! Впрочем, тебе придется попутешествовать, чтобы отыскать бестелесную нежить, без которой не обойтись.$b$bВидишь ли, разный климат оказывает разного рода воздействие на спектральную ткань мертвецов. Там понадобится эктоплазма от страдающих ночных эльфов Силитуса, духов высокорожденных из Зимних Ключей и призраков и банши из Восточных Чумных земель. Не забудь установить дистиллятор, прежде чем приступать к делу!','Воспользуйтесь эктоплазматическим дистиллятором рядом с бестелесной нежитью и соберите 12 образцов опаленной эктоплазмы в Силитусе, 12 образцов замороженной эктоплазмы в Зимних Ключах и 12 образцов стабильной эктоплазмы в Восточных Чумных землях. Принесите их вместе с эктоплазматическим дистиллятором Муксу Маноскребу в Прибамбасск.','Здорово!$B$BИспользуя потустороннюю энергию, которая хранится в этой эктоплазме, мы можем достучаться до тех, чьи души еще не совсем покинули этот мир!','$GСобрал:Собрала; эктоплазму?','Вернитесь к Муксу Маноскребу в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках эктоплазмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отличная конструкция, вот что я скажу! Впрочем, тебе придется попутешествовать, чтобы отыскать бестелесную нежить, без которой не обойтись.$b$bВидишь ли, разный климат оказывает разного рода воздействие на спектральную ткань мертвецов. Там понадобится эктоплазма от страдающих ночных эльфов Силитуса, духов высокорожденных из Зимних Ключей и призраков и банши из Восточных Чумных земель. Не забудь установить дистиллятор, прежде чем приступать к делу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь эктоплазматическим дистиллятором рядом с бестелесной нежитью и соберите 12 образцов опаленной эктоплазмы в Силитусе, 12 образцов замороженной эктоплазмы в Зимних Ключах и 12 образцов стабильной эктоплазмы в Восточных Чумных землях. Принесите их вместе с эктоплазматическим дистиллятором Муксу Маноскребу в Прибамбасск.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здорово!$B$BИспользуя потустороннюю энергию, которая хранится в этой эктоплазме, мы можем достучаться до тех, чьи души еще не совсем покинули этот мир!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GСобрал:Собрала; эктоплазму?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муксу Маноскребу в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8925,'Портативный источник энергии','Теперь нам понадобится стабильный и портативный источник энергии, который сможет поддерживать эктоплазму в активной форме. До меня дошли слухи о могущественном элементале по имени Повелитель магмы Бокк. Его сердце состоит из магмы, и это бесконечный источник тепла!$b$bГоворят, что его можно отыскать в Пылающих степях, на юге от Черной горы. Принеси мне магмовое ядро и мы обеспечим энергией спектральный сканер иных измерений!','Отыщите в Пылающих степях Повелителя магмы Бокка, добудьте его магмовое ядро и отнесите его Муксу Маноскребу в Прибамбасск.','Ты $Gсделал:сделала; это! Безусловно, магмовое ядро сможет поддерживать эктоплазму в активной форме!','Ты $Gнашел:нашла; Повелителя магмы, $N?','Вернитесь к Муксу Маноскребу в Прибамбасск, что в Танарисе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Портативный источник энергии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь нам понадобится стабильный и портативный источник энергии, который сможет поддерживать эктоплазму в активной форме. До меня дошли слухи о могущественном элементале по имени Повелитель магмы Бокк. Его сердце состоит из магмы, и это бесконечный источник тепла!$b$bГоворят, что его можно отыскать в Пылающих степях, на юге от Черной горы. Принеси мне магмовое ядро и мы обеспечим энергией спектральный сканер иных измерений!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите в Пылающих степях Повелителя магмы Бокка, добудьте его магмовое ядро и отнесите его Муксу Маноскребу в Прибамбасск.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсделал:сделала; это! Безусловно, магмовое ядро сможет поддерживать эктоплазму в активной форме!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gнашел:нашла; Повелителя магмы, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муксу Маноскребу в Прибамбасск, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8926,'Справедливое вознаграждение','Ты $Gсдержал:сдержала; слово и $Gпринес:принесла; устройство Мукса. И уж если я хочу, чтобы ты и дальше $Gзащищал:защищала; мою шкуру, то награда должна быть соответствующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.','Принесите пояс дикого cердца и пару перчаток дикого cердца в Стальгорн Делиане.','Ты свою часть сделки $Gвыполнил:выполнила;, я выполню свою.$B$BНо помни: лучшее я придержу до завершения работы. Сладкое – на закуску.','Ну, $Gготов:готова; к обмену?','Вернитесь к Делиане к Высокому трону, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Справедливое вознаграждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gсдержал:сдержала; слово и $Gпринес:принесла; устройство Мукса. И уж если я хочу, чтобы ты и дальше $Gзащищал:защищала; мою шкуру, то награда должна быть соответствующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите пояс дикого cердца и пару перчаток дикого cердца в Стальгорн Делиане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты свою часть сделки $Gвыполнил:выполнила;, я выполню свою.$B$BНо помни: лучшее я придержу до завершения работы. Сладкое – на закуску.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, $Gготов:готова; к обмену?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8927,'Справедливое вознаграждение','Ты $gоказался:оказалась; чрезвычайно надежным $gпомощником:помощницей;, $n! Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!$b$bОбменяю-ка я твой пояс и перчатки на кое-что получше. А если мы оба доживем до успешного завершения нашего предприятия, я отдам тебе и остальное.','Принесите Моквару в Оргриммар пояс дикого cердца и перчатки дикого cердца.','Наше соглашение остается в силе. Просто помните, это лишь вкус того, что вас ждет. Освободи меня от этой проклятой судьбы, и я награду тебя предметами поистине великой силы.','Вы готовы произвести обмен?','Вернитесь к Моквару в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Справедливое вознаграждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gоказался:оказалась; чрезвычайно надежным $gпомощником:помощницей;, $n! Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!$b$bОбменяю-ка я твой пояс и перчатки на кое-что получше. А если мы оба доживем до успешного завершения нашего предприятия, я отдам тебе и остальное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Моквару в Оргриммар пояс дикого cердца и перчатки дикого cердца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наше соглашение остается в силе. Просто помните, это лишь вкус того, что вас ждет. Освободи меня от этой проклятой судьбы, и я награду тебя предметами поистине великой силы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы готовы произвести обмен?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моквару в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8928,'Сомнительный торговец','Сердечник снабдит наше устройство энергией, остается найти жезл, который будет должным образом направлять ее и при этом не расплавится.$b$bЗнавал я одного беса из Зимних Ключей, который продавал самые разные товары. У него был жезл Стихий, который бы идеально подошел. Так и пнул бы себя – что стоило купить?$b$bОн живет в пещере у входа в Теснину Зловещего Шепота. Прокрадись туда и отыщи его.$b$BИ не давай ему больше сорока золотых – такую цену он назвал мне!','Отыщите беса в пещере у входа в Теснину Зловещего Шепота в южной части Зимних Ключей, купите жезл Скверны Стихий и отнесите его Муксу Маноскребу в Прибамбасск.','Ты $Gсделал:сделала; это! Этот жезл просто идеален. Теперь, его нужно поставить вот сюда...','$GБыл:Была; ли ты у беса?','Вернитесь к Муксу Маноскребу в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сомнительный торговец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сердечник снабдит наше устройство энергией, остается найти жезл, который будет должным образом направлять ее и при этом не расплавится.$b$bЗнавал я одного беса из Зимних Ключей, который продавал самые разные товары. У него был жезл Стихий, который бы идеально подошел. Так и пнул бы себя – что стоило купить?$b$bОн живет в пещере у входа в Теснину Зловещего Шепота. Прокрадись туда и отыщи его.$b$BИ не давай ему больше сорока золотых – такую цену он назвал мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите беса в пещере у входа в Теснину Зловещего Шепота в южной части Зимних Ключей, купите жезл Скверны Стихий и отнесите его Муксу Маноскребу в Прибамбасск.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсделал:сделала; это! Этот жезл просто идеален. Теперь, его нужно поставить вот сюда...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GБыл:Была; ли ты у беса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Муксу Маноскребу в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8929,'В поисках Антиона','Ну что ж, нам ничего не остается, как только опробовать гоблинское изобретение. Говорят, Антион пал под натиском легионов Стратхольма, когда пытался войти в его ворота. $B$BПопробуй воспользоваться этим изобретением там, возможно, тебе удастся узнать то, что знал Антион.','Используйте спектральный сканер иных измерений на входе в Стратхольм и поговорите с духом Антиона Хармона.','Тебя прислала Делиана? Я сделаю все, что ты просишь, но сначала окажи мне любезность.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Антиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ж, нам ничего не остается, как только опробовать гоблинское изобретение. Говорят, Антион пал под натиском легионов Стратхольма, когда пытался войти в его ворота. $B$BПопробуй воспользоваться этим изобретением там, возможно, тебе удастся узнать то, что знал Антион.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте спектральный сканер иных измерений на входе в Стратхольм и поговорите с духом Антиона Хармона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислала Делиана? Я сделаю все, что ты просишь, но сначала окажи мне любезность.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8930,'В поисках Антиона','Ну что ж, нам ничего не остается, как только опробовать гоблинское изобретение. Говорят, Антион пал под натиском легионов Стратхольма, когда пытался войти в его ворота. $B$BПопробуй воспользоваться этим изобретением там, возможно, с его помощью и в самом деле можно говорить с мертвыми.','Используйте спектральный сканер иных измерений на входе в Стратхольм и поговорите с духом Антиона Хармона.','Тебя прислал Моквар? Я сделаю все, что ты просишь, но сначала окажи мне любезность.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Антиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну что ж, нам ничего не остается, как только опробовать гоблинское изобретение. Говорят, Антион пал под натиском легионов Стратхольма, когда пытался войти в его ворота. $B$BПопробуй воспользоваться этим изобретением там, возможно, с его помощью и в самом деле можно говорить с мертвыми.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте спектральный сканер иных измерений на входе в Стратхольм и поговорите с духом Антиона Хармона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислал Моквар? Я сделаю все, что ты просишь, но сначала окажи мне любезность.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8931,'Справедливое вознаграждение','Ты $Gсдержал:сдержала; слово и $Gпринес:принесла; устройство Мукса. И уж если я хочу, чтобы ты и дальше $Gзащищал:защищала; мою шкуру, то награда должна быть соответствующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.','Принесите пояс загонщика и пару перчаток загонщика в Стальгорн Делиане.','Ты свою часть сделки $Gвыполнил:выполнила;, я выполню свою.$B$BНо помни: лучшее я придержу до завершения работы. Сладкое – на закуску.','Ну, $Gготов:готова; к обмену?','Вернитесь к Делиане к Высокому трону, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Справедливое вознаграждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gсдержал:сдержала; слово и $Gпринес:принесла; устройство Мукса. И уж если я хочу, чтобы ты и дальше $Gзащищал:защищала; мою шкуру, то награда должна быть соответствующей. Принеси мне тот пояс и перчатки, которые хочешь улучшить. Обещаю, что те, которые ты получишь взамен, будут намного лучше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите пояс загонщика и пару перчаток загонщика в Стальгорн Делиане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты свою часть сделки $Gвыполнил:выполнила;, я выполню свою.$B$BНо помни: лучшее я придержу до завершения работы. Сладкое – на закуску.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, $Gготов:готова; к обмену?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',`completedtext_loc8`);
