INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8938,'Справедливое вознаграждение','Ты $gоказался:оказалась; чрезвычайно надежным $gпомощником:помощницей;, $n! Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!$b$bОбменяю-ка я твой пояс и перчатки на кое-что получше. А если мы оба доживем до успешного завершения нашего предприятия, я отдам тебе и остальное.','Принесите Моквару в Оргриммар пояс загонщика и перчатки загонщика.','Наше соглашение остается в силе. Просто помните, это лишь вкус того, что вас ждет. Освободи меня от этой проклятой судьбы, и я награду тебя предметами поистине великой силы.','Вы готовы произвести обмен?','Вернитесь к Моквару в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Справедливое вознаграждение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gоказался:оказалась; чрезвычайно надежным $gпомощником:помощницей;, $n! Раз уж я рассчитываю, что ты поможешь мне выпутаться из неприятностей, будет только разумно вознаградить тебя по заслугам!$b$bОбменяю-ка я твой пояс и перчатки на кое-что получше. А если мы оба доживем до успешного завершения нашего предприятия, я отдам тебе и остальное.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Моквару в Оргриммар пояс загонщика и перчатки загонщика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наше соглашение остается в силе. Просто помните, это лишь вкус того, что вас ждет. Освободи меня от этой проклятой судьбы, и я награду тебя предметами поистине великой силы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы готовы произвести обмен?',`requestitemstext_loc8`), `