INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8945,'Просьба мертвеца','Я отвечу на все твои вопросы, $n. Но прежде исполни мою просьбу.$B$BЛюбимая жена моя была схвачена проклятым воинством Ривендера.$B$BКак же я не хотел, чтобы она следовала за дураками из Серебряного Рассвета, но теперь это все уже не важно. Прошу тебя, сделай то, что не удалось мне, – спаси Исиду из лап барона!','Отправляйтесь в Стратхольм и спасите Исиду Хармон от Барона Ривендера.','Благодарю, за спасение! Не думал я, что мне удастся выжить. Прошу тебя, прими это в качестве миллионной доли моей благодарности.$B$BАнтион... о нет... не может быть!','Скажите, Исида жива?','Вернитесь к Исиде Хармон в Стратхольм.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба мертвеца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я отвечу на все твои вопросы, $n. Но прежде исполни мою просьбу.$B$BЛюбимая жена моя была схвачена проклятым воинством Ривендера.$B$BКак же я не хотел, чтобы она следовала за дураками из Серебряного Рассвета, но теперь это все уже не важно. Прошу тебя, сделай то, что не удалось мне, – спаси Исиду из лап барона!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Стратхольм и спасите Исиду Хармон от Барона Ривендера.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю, за спасение! Не думал я, что мне удастся выжить. Прошу тебя, прими это в качестве миллионной доли моей благодарности.$B$BАнтион... о нет... не может быть!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Скажите, Исида жива?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исиде Хармон в Стратхольм.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8946,'Доказательство жизни','Нет судьбы горше, чем видеть, как твои близкие гибнут, пытаясь спасти тебя. Ты утверждаешь, что можешь говорить с мертвыми.$B$BОтнеси Антиону этот медальон как доказательство того, что я жива и здорова. Скажи ему, что ему не стоит цепляться за этот мир, обрекая себя на скитания в обличье бесплотного духа – мое бедное сердце этого не вынесет.$B$BПрощай, $n, я всегда буду у тебя в долгу.','Отнесите медальон Исиды Антиону Хармону в Восточные Чумные земли.','Этот медальон... ты $Gнашел:нашла; её! Теперь я могу покоиться с миром.$B$BТеперь, я должен ответить на твои вопросы, $N. Но поспеши, я не могу находиться в этом мире слишком долго.','Исида жива?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доказательство жизни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет судьбы горше, чем видеть, как твои близкие гибнут, пытаясь спасти тебя. Ты утверждаешь, что можешь говорить с мертвыми.$B$BОтнеси Антиону этот медальон как доказательство того, что я жива и здорова. Скажи ему, что ему не стоит цепляться за этот мир, обрекая себя на скитания в обличье бесплотного духа – мое бедное сердце этого не вынесет.$B$BПрощай, $n, я всегда буду у тебя в долгу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите медальон Исиды Антиону Хармону в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот медальон... ты $Gнашел:нашла; её! Теперь я могу покоиться с миром.$B$BТеперь, я должен ответить на твои вопросы, $N. Но поспеши, я не могу находиться в этом мире слишком долго.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Исида жива?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8947,'Странная просьба Антиона','Мы не сразу поняли важность медальона Вальтхалака, поэтому он был поделен наряду с остальными трофеями. Первый фрагмент получил дворф по имени Тельдрен. Я сам пытался отобрать у него этот фрагмент, но дворф избил меня до полусмерти. Тебе придется забрать фрагмент силой.$B$BГоворят, Тельдрен стал гладиатором у дворфов Черного Железа. Имей в виду, это очень сильный противник.$B$BИ сначала собери для меня некоторые материалы – они тебе понадобятся.','Принесите три слитка черного железа, 20 кусков зачарованной кожи, 3 куска луноткани и 4 обработанные грубые шкуры Антиону Хармону в Восточные Чумные земли.','Отлично. Я превращу их во что-то более необходимое нам.','Ты $Gдостал:достала; материалы, $N?','Вернитесь к Антиону Хармону в Стратхольм, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странная просьба Антиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не сразу поняли важность медальона Вальтхалака, поэтому он был поделен наряду с остальными трофеями. Первый фрагмент получил дворф по имени Тельдрен. Я сам пытался отобрать у него этот фрагмент, но дворф избил меня до полусмерти. Тебе придется забрать фрагмент силой.$B$BГоворят, Тельдрен стал гладиатором у дворфов Черного Железа. Имей в виду, это очень сильный противник.$B$BИ сначала собери для меня некоторые материалы – они тебе понадобятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите три слитка черного железа, 20 кусков зачарованной кожи, 3 куска луноткани и 4 обработанные грубые шкуры Антиону Хармону в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично. Я превращу их во что-то более необходимое нам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдостал:достала; материалы, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Антиону Хармону в Стратхольм, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8948,'Старый приятель Антиона','Тельдрен – не из тех, кто охотно вступает в честный поединок. Но я изготовил знамя его родовых цветов.$b$bЕсли еще наложить на него соответствующее заклятие, перед этим он не устоит.$b$bМой старый приятель по имени Фарлин знает такое заклятие. Умеет он... подзуживать. Ты найдешь его в библиотеке Забытого Города.','Отнесите незаконченное Знамя Вызова Фалрину Садовнику в библиотеку Забытого Города.','Говоришь Антион прислал тебя? Я думал, он мертв. Ну ладно, в своей жизни я слышал и куда страннее вещи.$B$BНу, хорошо. Так что ты говоришь, что мне нужно сделать с этим знаменем?','Ну, говори, $Gчужестранец:чужестранка;, не видишь что ли, я занят!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старый приятель Антиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тельдрен – не из тех, кто охотно вступает в честный поединок. Но я изготовил знамя его родовых цветов.$b$bЕсли еще наложить на него соответствующее заклятие, перед этим он не устоит.$b$bМой старый приятель по имени Фарлин знает такое заклятие. Умеет он... подзуживать. Ты найдешь его в библиотеке Забытого Города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите незаконченное Знамя Вызова Фалрину Садовнику в библиотеку Забытого Города.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говоришь Антион прислал тебя? Я думал, он мертв. Ну ладно, в своей жизни я слышал и куда страннее вещи.$B$BНу, хорошо. Так что ты говоришь, что мне нужно сделать с этим знаменем?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, говори, $Gчужестранец:чужестранка;, не видишь что ли, я занят!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8949,'Кровная месть Фарлина','Да, |3-6($c), мне действительно знакомы те чары, которые ты ищешь. Но я не из тех, что оказывают услуги даром, даже тем, кого прислал сюда мой старый приятель.$b$bЯ испытываю глубокую ненависть и презрение к нашим грубым соседям-ограм. И не только к ним: последователей Омокка я ненавижу не меньше, чем сторонников короля Гордока.$b$bУбивай их! И чем больше, тем лучше! Принеси мне в доказательство своего успеха ожерелья, которые огры носят на шее. Сделай это, тогда и поговорим о твоей просьбе.','Соберите 25 боевых ожерелий огров с огров Забытого Города или Пика Черной горы и вернитесь в Читальню Забытого Города к Фалрину Садовнику.','Хмм... странно, но я не чувствую себя лучше, после смерти моего брата, от рук этих зверюг.$B$BНо, уговор, есть уговор. Давай посмотрим, что я могу сделать для тебя.','Ты $Gоказал:оказала; услугу, о которой я просил тебя, $N?','Вернитесь к Фалрину Садовнику в Забытый Город.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровная месть Фарлина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, |3-6($c), мне действительно знакомы те чары, которые ты ищешь. Но я не из тех, что оказывают услуги даром, даже тем, кого прислал сюда мой старый приятель.$b$bЯ испытываю глубокую ненависть и презрение к нашим грубым соседям-ограм. И не только к ним: последователей Омокка я ненавижу не меньше, чем сторонников короля Гордока.$b$bУбивай их! И чем больше, тем лучше! Принеси мне в доказательство своего успеха ожерелья, которые огры носят на шее. Сделай это, тогда и поговорим о твоей просьбе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 25 боевых ожерелий огров с огров Забытого Города или Пика Черной горы и вернитесь в Читальню Забытого Города к Фалрину Садовнику.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм... странно, но я не чувствую себя лучше, после смерти моего брата, от рук этих зверюг.$B$BНо, уговор, есть уговор. Давай посмотрим, что я могу сделать для тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gоказал:оказала; услугу, о которой я просил тебя, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фалрину Садовнику в Забытый Город.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8950,'Чары подстрекателя','Я без труда могу наложить на знамя чары, которые тебе нужны, $n. Но к несчастью, у меня нет необходимых материалов: такие заклинания очень мало кто спрашивает.$b$bМне потребуется сущность одного из призраков Элдрета, обитающих в этих залах, горсть черных рун из Некроситета и несколько больших сверкающих осколков. Принеси мне эти реагенты, и я создам для тебя нужные чары.','Принесите 1 сущность язвительного призрака, 4 черных руны и 8 больших сверкающих осколков Фалрину Садовнику в Забытом Городе.','Эти материалы прекрасно подойдут для наложения чар.','Ты $Gсобрал:собрала; необходимые мне материалы, $N?','Вернитесь к Фалрину Садовнику в Забытый Город.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чары подстрекателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я без труда могу наложить на знамя чары, которые тебе нужны, $n. Но к несчастью, у меня нет необходимых материалов: такие заклинания очень мало кто спрашивает.$b$bМне потребуется сущность одного из призраков Элдрета, обитающих в этих залах, горсть черных рун из Некроситета и несколько больших сверкающих осколков. Принеси мне эти реагенты, и я создам для тебя нужные чары.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 сущность язвительного призрака, 4 черных руны и 8 больших сверкающих осколков Фалрину Садовнику в Забытом Городе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти материалы прекрасно подойдут для наложения чар.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсобрал:собрала; необходимые мне материалы, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фалрину Садовнику в Забытый Город.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8951,'Прощальные слова Антиона','В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю удачи – она тебе понадобится!','Вернитесь в Стальгорн к Делиане с сапогами дикого cердца, килтом дикого cердца и наплечем дикого сердца.','Поверить не могу, что наша жизнь висит на волоске из-за какого-то дурацкого медальона! А ты $Gуверен:уверен;, что Антион упомянул Бодли?$B$BЛадно, ты свое дело $Gсделал:сделала;, так что давай закончим и с твоей наградой.','Ты $Gвернулся:вернулась;, $N. Ты $Gдолжен:должна; рассказать мне все о том, что $Gузнал:узнала;. Но сначала давай договоримся о твоей награде.','Вернитесь к Делиане к Высокому трону, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощальные слова Антиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю удачи – она тебе понадобится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Стальгорн к Делиане с сапогами дикого cердца, килтом дикого cердца и наплечем дикого сердца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поверить не могу, что наша жизнь висит на волоске из-за какого-то дурацкого медальона! А ты $Gуверен:уверен;, что Антион упомянул Бодли?$B$BЛадно, ты свое дело $Gсделал:сделала;, так что давай закончим и с твоей наградой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;, $N. Ты $Gдолжен:должна; рассказать мне все о том, что $Gузнал:узнала;. Но сначала давай договоримся о твоей награде.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8952,'Прощальные слова Антиона','В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю тебе удачи – она тебе очень понадобится!','Принесите в Стальгорн Делиане сапоги загонщика, штаны загонщика и оплечье загонщика.','Поверить не могу, что наша жизнь висит на волоске из-за какого-то дурацкого медальона! А ты $Gуверен:уверен;, что Антион упомянул Бодли?$B$BЛадно, ты свое дело $Gсделал:сделала;, так что давай закончим и с твоей наградой.','Ты $Gвернулся:вернулась;, $N. Ты $Gдолжен:должна; рассказать мне все о том, что $Gузнал:узнала;. Но сначала давай договоримся о твоей награде.','Вернитесь к Делиане к Высокому трону, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощальные слова Антиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю тебе удачи – она тебе очень понадобится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите в Стальгорн Делиане сапоги загонщика, штаны загонщика и оплечье загонщика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `of