mstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;, $N. Ты $Gдолжен:должна; рассказать мне все о том, что $Gузнал:узнала;. Но сначала давай договоримся о твоей награде.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8959,'Прощальные слова Антиона','В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю тебе удачи – она тебе очень понадобится!','Принесите в Стальгорн Делиане сапоги Доблести, ножные латы Доблести и наплеч Доблести.','Поверить не могу, что наша жизнь висит на волоске из-за какого-то дурацкого медальона! А ты $Gуверен:уверен;, что Антион упомянул Бодли?$B$BЛадно, ты свое дело $Gсделал:сделала;, так что давай закончим и с твоей наградой.','Ты $Gвернулся:вернулась;, $N. Ты $Gдолжен:должна; рассказать мне все о том, что $Gузнал:узнала;. Но сначала давай договоримся о твоей награде.','Вернитесь к Делиане к Высокому трону, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощальные слова Антиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом медальоне заключена душа Вальтхалака. В жадности своей мы, безумцы, разделили его на три части, не ведая о поджидавшем нас проклятии.$B$BЕдинственный способ уничтожить заклятье Вальтхалака – вновь собрать медальон. Вернись к Делиане и скажи ей, что Бодли – ее единственная надежда найти остальные части. Поговори с ней об условленной награде.$B$BЯ же ныне спокойно умру. Желаю тебе удачи – она тебе очень понадобится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите в Стальгорн Делиане сапоги Доблести, ножные латы Доблести и наплеч Доблести.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поверить не могу, что наша жизнь висит на волоске из-за какого-то дурацкого медальона! А ты $Gуверен:уверен;, что Антион упомянул Бодли?$B$BЛадно, ты свое дело $Gсделал:сделала;, так что давай закончим и с твоей наградой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;, $N. Ты $Gдолжен:должна; рассказать мне все о том, что $Gузнал:узнала;. Но сначала давай договоримся о твоей награде.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8960,'Злосчастная доля Бодли','Значит, нам нужно найти недостающие части и собрать медальон? Но разыскать Бодли будет непросто. Он отправился к Черной горе, хотел еще раз проникнуть в Пик Черной горы. И до сих пор не вернулся.$B$BБоюсь, как бы с ним не случилось беды. На всякий случай возьми с собой спектральный сканер иных измерений. Лучше заранее приготовиться к самому худшему...','Отыщите Бодли у Пика Черной горы с помощью спектрального сканера иных измерений.','Ты себе даже не представляешь, как я рад, что меня видят и слышатI Наконец я дождался кого-то, с кем можно поговорить!$B$BТы нам поможешь, $N? Мы сами не ведали, что творили, и совершили великое зло, а теперь должны все исправить. Если ты $Gсказал:сказала; правду и у тебя действительно есть верхняя часть амулета Лорда Вальтхалака, я могу подсказать, где найти две оставшиеся части. Тогда амулет вновь обретет свою целостность, и весь этот ужас закончится.$B$BДа, кстати, меня зовут Бодли. Будем знакомы!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злосчастная доля Бодли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, нам нужно найти недостающие части и собрать медальон? Но разыскать Бодли будет непросто. Он отправился к Черной горе, хотел еще раз проникнуть в Пик Черной горы. И до сих пор не вернулся.$B$BБоюсь, как бы с ним не случилось беды. На всякий случай возьми с собой спектральный сканер иных измерений. Лучше заранее приготовиться к самому худшему...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Бодли у Пика Черной горы с помощью спектрального сканера иных измерений.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты себе даже не представляешь, как я рад, что меня видят и слышатI Наконец я дождался кого-то, с кем можно поговорить!$B$BТы нам поможешь, $N? Мы сами не ведали, что творили, и совершили великое зло, а теперь должны все исправить. Если ты $Gсказал:сказала; правду и у тебя действительно есть верхняя часть амулета Лорда Вальтхалака, я могу подсказать, где найти две оставшиеся части. Тогда амулет вновь обретет свою целостность, и весь этот ужас закончится.$B$BДа, кстати, меня зовут Бодли. Будем знакомы!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8961,'Три властелина огня','Для того чтобы вызвать Лорда Вальтхалака, первым делом нам нужно собрать амулет воедино. Одна часть у нас есть, еще двух не хватает. Для того чтобы собрать эти части, нам нужно добыть жаровню и особые угли, чтобы зажечь в ней огонь.$B$BТы, может быть, $Gслышал:слышала; о трех властелинах огня. Это Лорд Опалитель из Глубин Черной горы, Пиростраж Углевзор с Пика Черной горы и герцог Огарцог из Силитуса. Убей их, возьми от каждого по одному углю и принеси их сюда вместе с жаровней Благословения, которую можно купить у приспешников Серебряного Рассвета, если ты пользуешься среди них уважением.','Добыть огневит Опалителя, уголь Углевзора и уголь Огарцога и принести их Бодли в Черную гору вместе с жаровней Благословения.','Я впечатлен, $C, но у нас нет времени на рассказы. Я дам тебе следующее задание.$B$BПоговори со мной еще раз, когда почувствуешь, что $Gготов:готова; бросить вызов тому, что ждет тебя впереди.','То, что мы взялись за последнюю работу, было нашей глупостью... нашей гибелью. Если бы только мы случайно не украли дух лорда Вальтхалака, который содержался в амулете; Если бы только в нашей группе наемников не было таких жадных, которые разделили ее между собой. Я был бы сегодня жив, может, подбросил бы пиво или подбросил одного из своих детей в воздух.$B$B$N не позволяй жадности неблагородных людей из нашей старой наемной компании стать твоей гибелью.','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Три властелина огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для того чтобы вызвать Лорда Вальтхалака, первым делом нам нужно собрать амулет воедино. Одна часть у нас есть, еще двух не хватает. Для того чтобы собрать эти части, нам нужно добыть жаровню и особые угли, чтобы зажечь в ней огонь.$B$BТы, может быть, $Gслышал:слышала; о трех властелинах огня. Это Лорд Опалитель из Глубин Черной горы, Пиростраж Углевзор с Пика Черной горы и герцог Огарцог из Силитуса. Убей их, возьми от каждого по одному углю и принеси их сюда вместе с жаровней Благословения, которую можно купить у приспешников Серебряного Рассвета, если ты пользуешься среди них уважением.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добыть огневит Опалителя, уголь Углевзора и уголь Огарцога и принести их Бодли в Черную гору вместе с жаровней Благословения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я впечатлен, $C, но у нас нет времени на рассказы. Я дам тебе следующее задание.$B$BПоговори со мной еще раз, когда почувствуешь, что $Gготов:готова; бросить вызов тому, что ждет тебя впереди.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','То, что мы взялись за последнюю работу, было нашей глупостью... нашей гибелью. Если бы только мы случайно не украли дух лорда Вальтхалака, который содержался в амулете; Если бы только в нашей группе наемников не было таких жадных, которые разделили ее между собой. Я был бы сегодня жив, может, подбросил бы пиво или подбросил одного из своих детей в воздух.$B$B$N не позволяй жадности неблагородных людей из нашей старой наемной компании стать твоей гибелью.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8962,'Важная составляющая заклинания','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего соратника.$B$BУ Мора Серого Копыта, нашего выдающегося друида, было немало хороших друзей в Круге Кенария, и некоторые из них пали жертвой атаки силитидов. Мне нужно, чтобы ты $gзабрал:забрала; останки погибших друидов у силитидов из Улья Регал, что на юго-востоке Силитуса.','Найдите останки друидов и принести их Бодли в Черную гору.','Отличная работа, $N. Я наполню жаровню сущностью останков.$B$BТеперь все, что осталось, - это отправиться в нижнюю часть Пика Черной горы, в комнату, где находится Военный Мастер Вун в Тазз\'Алаоре, и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Он не может успокоиться, пока у него не отберут амулет.','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важная составляющая заклинания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего соратника.$B$BУ Мора Серого Копыта, нашего выдающегося друида, было немало хороших друзей в Круге Кенария, и некоторые из них пали жертвой атаки силитидов. Мне нужно, чтобы ты $gзабрал:забрала; останки погибших друидов у силитидов из Улья Регал, что на юго-востоке Силитуса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите останки друидов и принести их Бодли в Черную гору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Я наполню жаровню сущностью останков.$B$BТеперь все, что осталось, - это отправиться в нижнюю часть Пика Черной горы, в комнату, где находится Военный Мастер Вун в Тазз\'Алаоре, и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Он не может успокоиться, пока у него не отберут амулет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8963,'Важная составляющая заклинания','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моей павшей соратницы.$B$BИзалиен, наша жрица, выросла в Зимних Ключах в Деревне Звездного Ветра. Забери реликвию Деревни Звездного Ветра у великанов ледяного молота в теснине Ледяного Шепота в южной части Зимних Ключей.','Найдите реликвию Деревни Звездного Ветра и принести ее Бодли в Черную гору.','Отличная работа, $N. Я наполню жаровню сущностью останков.$B$BТеперь все, что осталось, - это отправиться в Святилище Эльдретарра в восточном крыле Забытого Города и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Ее дух был испорчен из-за того, что она обладала частью амулета Валтхалака и частью его души внутри него.','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важная составляющая заклинания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моей павшей соратницы.$B$BИзалиен, наша жрица, выросла в Зимних Ключах в Деревне Звездного Ветра. Забери реликвию Деревни Звездного Ветра у великанов ледяного молота в теснине Ледяного Шепота в южной части Зимних Ключей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите реликвию Деревни Звездного Ветра и принести ее Бодли в Черную гору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Я наполню жаровню сущностью останков.$B$BТеперь все, что осталось, - это отправиться в Святилище Эльдретарра в восточном крыле Забытого Города и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Ее дух был испорчен из-за того, что она обладала частью амулета Валтхалака и частью его души внутри него.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8964,'Важная составляющая заклинания','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь. Но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет духов моих бывших соратников.$B$BДжариен и Сотос оставили нас и решили присоединиться к Алому ордену, свято уверовав в его путь. Они так стремились вступить в эту подлую организацию... но не прошли испытания на посвящении. Отправляйся в Длань Тира в Восточных Чумных землях и забери сверкающий меч Фанатизма у тамошних преторов.','Добыть сверкающий меч Фанатизма и принести его Бодли в Черную гору.','Отличная работа, $N. Я наполню жаровню сущностью останков.$B$BТеперь все, что осталось, - это попасть в Багровый трон внутри Алого бастиона в Стратхольме и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Он не может успокоиться, пока у него не отберут амулет.','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важная составляющая заклинания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь. Но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет духов моих бывших соратников.$B$BДжариен и Сотос оставили нас и решили присоединиться к Алому ордену, свято уверовав в его путь. Они так стремились вступить в эту подлую организацию... но не прошли испытания на посвящении. Отправляйся в Длань Тира в Восточных Чумных землях и забери сверкающий меч Фанатизма у тамошних преторов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добыть сверкающий меч Фанатизма и принести его Бодли в Черную гору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Я наполню жаровню сущностью останков.$B$BТеперь все, что осталось, - это попасть в Багровый трон внутри Алого бастиона в Стратхольме и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Он не может успокоиться, пока у него не отберут амулет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8965,'Важная составляющая заклинания','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего товарища.$B$BКормок, огр-некромант, путешествовавший вместе с нами, обосновался впоследствии на южном побережье предгорий Хилсбрада и вызвал души изгнанных мертвецов, обитателей острова Очищения. Иди туда и добудь пепел душ Изгнанников.','Добыть пепел душ Изгнанников и принести его Бодли в Черную гору.','Отличная работа, $N. Я наполню жаровню сущностью останков.$B$BТеперь все, что осталось, - это попасть в Некроситет, в комнату Раса Ледяного Шепота и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Он не может успокоиться, пока у него не отберут амулет.','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Важная составляющая заклинания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего товарища.$B$BКормок, огр-некромант, путешествовавший вместе с нами, обосновался впоследствии на южном побережье предгорий Хилсбрада и вызвал души изгнанных мертвецов, обитателей острова Очищения. Иди туда и добудь пепел душ Изгнанников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добыть пепел душ Изгнанников и принести его Бодли в Черную гору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Я наполню жаровню сущностью останков.$B$BТеперь все, что осталось, - это попасть в Некроситет, в комнату Раса Ледяного Шепота и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Он не может успокоиться, пока у него не отберут амулет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8966,'Левая часть амулета Лорда Вальтхалака','Мой друг Мор Серое Копыто был первым, кто завладел частью разбитого амулета Лорда Вальтхалака и пал жертвой разрушительных чар осколка души владыки, заключенного внутри. Выкрав книгу заклинаний Вальтхалака и амулет, мы бежали сломя голову с Пика Черной горы. По пути вниз Мор сорвался и упал.$B$BПотом мы узнали, что он не разбился, но его захватил и подверг страшным пыткам воевода Вун. Призрачные убийцы пробрались к нему и убили его на глазах у Вуна.','Вызвать дух Мора Серого Копыта с помощью жаровни Призыва, прикончить его и забрать недостающую часть амулета Лорда Вальтхалака. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Вальтхалака и жаровню Призыва.','Ты $Gсделал:сделала; большое дело, $N. Один дух покоиться в мире, но нам еще предстоит много сделать.$B$BУ меня для тебя есть ещё задания.','Тебе удалось извлечь левую часть амулета Лорда Вальтахалака и положить конец мучениям моего товарища, Мора Серого Копыта?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Левая часть амулета Лорда Вальтхалака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой друг Мор Серое Копыто был первым, кто завладел частью разбитого амулета Лорда Вальтхалака и пал жертвой разрушительных чар осколка души владыки, заключенного внутри. Выкрав книгу заклинаний Вальтхалака и амулет, мы бежали сломя голову с Пика Черной горы. По пути вниз Мор сорвался и упал.$B$BПотом мы узнали, что он не разбился, но его захватил и подверг страшным пыткам воевода Вун. Призрачные убийцы пробрались к нему и убили его на глазах у Вуна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызвать дух Мора Серого Копыта с помощью жаровни Призыва, прикончить его и забрать недостающую часть амулета Лорда Вальтхалака. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Вальтхалака и жаровню Призыва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсделал:сделала; большое дело, $N. Один дух покоиться в мире, но нам еще предстоит много сделать.$B$BУ меня для тебя есть ещё задания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось извлечь левую часть амулета Лорда Вальтахалака и положить конец мучениям моего товарища, Мора Серого Копыта?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8967,'Левая часть амулета Лорда Вальтхалака','Недавно нам стало известно, что наша бывшая соратница Изалиен, жрица ночных эльфов, отправилась в древнее поселение своего народа, известное теперь под названием Забытый Город. Насколько нам удалось узнать, она отправилась в Забытый Город как по личным причинам, так и за тем, чтобы вызнать секреты той части амулета Лорда Вальтхалака, которую она забрала с собой.$B$BНо ее замыслам не суждено было сбыться. До нас дошли слухи, что у святилища Элдретарра Изалиен попала в засаду, которую устроил Алззин Перевертень.','С помощью жаровни Призыва вызвать дух Изалиен и убить ее. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.','Спасибо $N, теперь дух Изалиен отправился к остальным. Впереди нас ещё ожидает много работы.$B$BУ меня для тебя есть ещё задания.','Ты уже $Gзавершил:завершила; своё задание по спасению души Изалиен и извлечение левой части амулета Лорда Вальтхалака, $N?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Левая часть амулета Лорда Вальтхалака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно нам стало известно, что наша бывшая соратница Изалиен, жрица ночных эльфов, отправилась в древнее поселение своего народа, известное теперь под названием Забытый Город. Насколько нам удалось узнать, она отправилась в Забытый Город как по личным причинам, так и за тем, чтобы вызнать секреты той части амулета Лорда Вальтхалака, которую она забрала с собой.$B$BНо ее замыслам не суждено было сбыться. До нас дошли слухи, что у святилища Элдретарра Изалиен попала в засаду, которую устроил Алззин Перевертень.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью жаровни Призыва вызвать дух Изалиен и убить ее. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо $N, теперь дух Изалиен отправился к остальным. Впереди нас ещё ожидает много работы.$B$BУ меня для тебя есть ещё задания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gзавершил:завершила; своё задание по спасению души Изалиен и извлечение левой части амулета Лорда Вальтхалака, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8968,'Левая часть амулета Лорда Вальтхалака','Наши бывшие соратники, брат с сестрой Сотос и Джариен, решили присоединиться к Алому ордену. Они ушли и забрали с собой левую часть амулета Лорда Вальтхалака. Я всегда говорил: оно даже и к лучшему, что мы избавились от этой проклятой вещицы, но сейчас ее надо вернуть.$B$BНасколько мы знаем, Джариен и Сотос не прошли испытание на ритуале посвящения в чертоге Датрохана в Бастионе Алого ордена, и Верховный рыцарь собственноручно прикончил обоих.$B$BКак бы там ни было, нам нужна эта часть амулета, и мы... то есть ты $gдолжен:должна; будешь ее забрать.','Вызвать духов Джариен и Сотоса с помощью жаровни Призыва и убить их обоих. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.','Я полагаю, что это лучшее что мы могли предложить, двум проклятым душам. В любом случае у нас есть то, что нам нужно. Но, к сожалению, у нас ещё много работы.$B$BУ меня для тебя есть ещё задания.','Означает ли твое появление здесь, $C, что тебе удалось положить конец блужданию этих двух душ и извлечь левую часть амулета Лорда Вальтхалака?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Левая часть амулета Лорда Вальтхалака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши бывшие соратники, брат с сестрой Сотос и Джариен, решили присоединиться к Алому ордену. Они ушли и забрали с собой левую часть амулета Лорда Вальтхалака. Я всегда говорил: оно даже и к лучшему, что мы избавились от этой проклятой вещицы, но сейчас ее надо вернуть.$B$BНасколько мы знаем, Джариен и Сотос не прошли испытание на ритуале посвящения в чертоге Датрохана в Бастионе Алого ордена, и Верховный рыцарь собственноручно прикончил обоих.$B$BКак бы там ни было, нам нужна эта часть амулета, и мы... то есть ты $gдолжен:должна; будешь ее забрать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызвать духов Джариен и Сотоса с помощью жаровни Призыва и убить их обоих. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я полагаю, что это лучшее что мы могли предложить, двум проклятым душам. В любом случае у нас есть то, что нам нужно. Но, к сожалению, у нас ещё много работы.$B$BУ меня для тебя есть ещё задания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Означает ли твое появление здесь, $C, что тебе удалось положить конец блужданию этих двух душ и извлечь левую часть амулета Лорда Вальтхалака?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8969,'Левая часть амулета Лорда Вальтхалака','Теперь, когда у нас есть все, что нужно для ритуала призыва, осталось решить, кого именно вызвать.$B$BКормок был неплохим парнем, пока не занялся некромантией. Вот тогда нам всем стало по-настоящему жутко – и это при том, что отряд набирали уж явно не из боязливых юнцов и кисейных барышень. Никто не удивился, когда он забрал свою часть амулета и вернулся в свой новый дом в Некроситете.$B$BНо даже там он не укрылся от призрачных убийц. Они прикончили его на глазах у Раса Ледяного Шепота, его хозяина.','С помощью жаровни Призыва вызвать дух Кормока и убить его. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.','Отличная работа, $N! Кормок был уж и не таким плохим огром, по крайней мере, когда был жив. Но у нас впереди ещё много работы.$B$BУ меня для тебя есть ещё задания.','Если ты $Gвернулся:вернулась; с амулетом, это очень хорошо. Но если без, поспеши, у нас мало времени.','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Левая часть амулета Лорда Вальтхалака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у нас есть все, что нужно для ритуала призыва, осталось решить, кого именно вызвать.$B$BКормок был неплохим парнем, пока не занялся некромантией. Вот тогда нам всем стало по-настоящему жутко – и это при том, что отряд набирали уж явно не из боязливых юнцов и кисейных барышень. Никто не удивился, когда он забрал свою часть амулета и вернулся в свой новый дом в Некроситете.$B$BНо даже там он не укрылся от призрачных убийц. Они прикончили его на глазах у Раса Ледяного Шепота, его хозяина.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью жаровни Призыва вызвать дух Кормока и убить его. Вернуться к Бодли в Черную гору, отдать ему левую часть амулета Лорда Вальтхалака и жаровню Призыва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N! Кормок был уж и не таким плохим огром, по крайней мере, когда был жив. Но у нас впереди ещё много работы.$B$BУ меня для тебя есть ещё задания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты $Gвернулся:вернулась; с амулетом, это очень хорошо. Но если без, поспеши, у нас мало времени.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8970,'Я вижу в твоем будущем остров Алькац...','Как я уже говорил, |3-6($c), при жизни я изучал ворожбу и гадание и даже подумывал о том, чтобы пойти в прорицатели или провидцы. Но это не самое прибыльное занятие. Во-первых, неблагодарное и опасное. А во-вторых, реагенты редки и недешевы. Однако я кое-чему научился, и моих знаний хватит, чтобы найти последнюю часть амулета, а вместе с нею – и дух моего павшего соратника.$B$BНо мне понадобится твоя помощь, $n. Отправляйся на остров Алькац у побережья Пылевых топей и собери кровавую ламинарию у наг из клана Страшаз, которые там обитают.','Соберите 20 порций кровавой ламинарии у наг из клана Страшаз и принесите их Бодли на Черную гору.','Если честно, $N, то я очень удивлен что ты $Gвернулся:вернулась;.$B$BНу хорошо, дай мне пару минут... гадание, это не просто щелкнуть двумя пальцами и ждать ответа.','Кровавая ламинария, $N, мне нужно много кровавой ламинарии чтобы привести в действие гадальные заклинания. Вероятно, тебе лучше взять с собой несколько своих друзей, так как остров Алькац очень опасен.','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я вижу в твоем будущем остров Алькац...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как я уже говорил, |3-6($c), при жизни я изучал ворожбу и гадание и даже подумывал о том, чтобы пойти в прорицатели или провидцы. Но это не самое прибыльное занятие. Во-первых, неблагодарное и опасное. А во-вторых, реагенты редки и недешевы. Однако я кое-чему научился, и моих знаний хватит, чтобы найти последнюю часть амулета, а вместе с нею – и дух моего павшего соратника.$B$BНо мне понадобится твоя помощь, $n. Отправляйся на остров Алькац у побережья Пылевых топей и собери кровавую ламинарию у наг из клана Страшаз, которые там обитают.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 20 порций кровавой ламинарии у наг из клана Страшаз и принесите их Бодли на Черную гору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если честно, $N, то я очень удивлен что ты $Gвернулся:вернулась;.$B$BНу хорошо, дай мне пару минут... гадание, это не просто щелкнуть двумя пальцами и ждать ответа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кровавая ламинария, $N, мне нужно много кровавой ламинарии чтобы привести в действие гадальные заклинания. Вероятно, тебе лучше взять с собой несколько своих друзей, так как остров Алькац очень опасен.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
