INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8977,'Возвращение к Делиане','С тобой здорово сотрудничать, $n. Вот готовое изделие.$B$BНадеюсь, оно поможет тебе в твоих дальнейших подвигах. Да, и если ты не против, рассказывай всем обо мне. Мне лишние клиенты не помешают!','Принесите спектральный сканер иных измерений Делиане в Стальгорн.','Блестяще! Ты на славу $Gпостарался:постаралась;, $N. Хотя я гоблинским изделиям и не доверяю, но выбора у меня нет.','Уже $Gвернулся:вернулась;?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Делиане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тобой здорово сотрудничать, $n. Вот готовое изделие.$B$BНадеюсь, оно поможет тебе в твоих дальнейших подвигах. Да, и если ты не против, рассказывай всем обо мне. Мне лишние клиенты не помешают!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите спектральный сканер иных измерений Делиане в Стальгорн.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Блестяще! Ты на славу $Gпостарался:постаралась;, $N. Хотя я гоблинским изделиям и не доверяю, но выбора у меня нет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уже $Gвернулся:вернулась;?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (8978,'Возвращение к Моквару','Приятно было поработать с тобой, $n! Вот, твой заказ готов.$b$bНадеюсь, мои изделия тебе пригодятся. И кстати, если ты не против, расскажи обо мне другим. Лишние заказчики мне совсем не помешают!','Принесите Моквару в Оргриммар спектральный сканер иных измерений.','Ты уже $Gвернулся:вернулась; с устройством? Я впечатлён, $N. Отличная работа.','Ты $Gвернулся:вернулась; с устройством?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Моквару',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приятно было поработать с тобой, $n! Вот, твой заказ готов.$b$bНадеюсь, мои изделия тебе пригодятся. И кстати, если ты не против, расскажи обо мне другим. Лишние заказчики мне совсем не помешают!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Моквару в Оргриммар спектральный сканер иных измерений.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты уже $Gвернулся:вернулась; с устройством? Я впечатлён, $N. Отличная работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась; с устройством?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8979,'Подозрения Фенстада','Кажется, я понял причину странностей, происходящих в последнее время. Ты чувствуешь новый запах в воздухе, перебивающий даже вонь от каналов? Запах новых одеколонов и духов, только что вошедших в моду?$B$BНаш разум затуманен какой-то гнусной алхимией.$b$bЕсть только один способ убедиться – отнести флакон одеколона и духов аптекарю Зинг. Королевское фармацевтическое общество отыщет истину.$B$BЯ возмещу тебе цену покупки, когда ты вернешься.','Понятно, еще одна навязчивая идея Фенстада. Он что думает, Королевскому фармацевтическому обществу нечем больше заняться, только проводить для него всякие мелкие расследования?$B$BНу что ж, еще раз я потешу его душу','Чем могу служить?','Вернитесь к аптекарю Зинг в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подозрения Фенстада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, я понял причину странностей, происходящих в последнее время. Ты чувствуешь новый запах в воздухе, перебивающий даже вонь от каналов? Запах новых одеколонов и духов, только что вошедших в моду?$B$BНаш разум затуманен какой-то гнусной алхимией.$b$bЕсть только один способ убедиться – отнести флакон одеколона и духов аптекарю Зинг. Королевское фармацевтическое общество отыщет истину.$B$BЯ возмещу тебе цену покупки, когда ты вернешься.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Понятно, еще одна навязчивая идея Фенстада. Он что думает, Королевскому фармацевтическому обществу нечем больше заняться, только проводить для него всякие мелкие расследования?$B$BНу что ж, еще раз я потешу его душу',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем могу служить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Зинг в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8980,'Мнение Зинг','Это неожиданно. Похоже, Фенстад в конце концов все-таки что-то нарыл. Я нашла следы веществ, используемых в зельях контроля над разумом.$b$bИзвестно, что такие вещества используются в некоторых духах, но некоторые из обнаруженных мною ингредиентов... Это серьезная алхимия, даже для того, кто наделен способностями участника Королевского фармацевтического общества.','Вернитесь к Фенстаду Аргайлу, ожидающему около банка в Подгороде.','Итак, я был прав. Мы не должны терять время зря. Мы должны определить источник этих испорченных ароматов.$B$BЭто, чтобы отплатить вам за покупку одеколона и духов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мнение Зинг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это неожиданно. Похоже, Фенстад в конце концов все-таки что-то нарыл. Я нашла следы веществ, используемых в зельях контроля над разумом.$b$bИзвестно, что такие вещества используются в некоторых духах, но некоторые из обнаруженных мною ингредиентов... Это серьезная алхимия, даже для того, кто наделен способностями участника Королевского фармацевтического общества.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Фенстаду Аргайлу, ожидающему около банка в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, я был прав. Мы не должны терять время зря. Мы должны определить источник этих испорченных ароматов.$B$BЭто, чтобы отплатить вам за покупку одеколона и духов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (8981,'Подношение даров','Вернитесь к Кви К. Мелкошустру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подношение даров',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кви К. Мелкошустру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8982,'Поиск источника','Мы должны узнать, кто поставщик. Я заметил у аптекаря Катрины в сумке флакон духов. Она сказала, что приобрела его у Нормана, хозяина таверны.','Поговорите с хозяином таверны Норманом в Подгороде.','О да, я лишь недавно получил партию духов и одеколона. Я не знаю, надолго ли они задержатся на полках – похоже, всем эти запахи нравятся.$B$BНо если хочешь спросить мое мнение, то я не знаю, что в этом такого.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиск источника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны узнать, кто поставщик. Я заметил у аптекаря Катрины в сумке флакон духов. Она сказала, что приобрела его у Нормана, хозяина таверны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хозяином таверны Норманом в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О да, я лишь недавно получил партию духов и одеколона. Я не знаю, надолго ли они задержатся на полках – похоже, всем эти запахи нравятся.$B$BНо если хочешь спросить мое мнение, то я не знаю, что в этом такого.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8983,'Поиск источника','Что-то не так с тем, чем я торгую? Ну, я никогда не видел, чтобы так много народа столь отчаянно чего-нибудь жаждало.$b$bЯ покупаю припасы у торговки по имени Мара Ренник. Она в городе недавно.$b$bОна упоминала, что хочет доставить кое-какие товары торговцу одеждой в Квартал Магов.','Поговорите с Марой Ренник в портновской лавке в Квартале Магов Подгорода.','Боюсь, я продала всю партию духов и одеколона Норману, хозяину таверны. Если они тебе нужны, поговори с ним – может быть, у него что-то еще осталось.$B$BНо не трать времени. Полагаю, ты сочтешь запах одеколона просто неотразимым.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиск источника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то не так с тем, чем я торгую? Ну, я никогда не видел, чтобы так много народа столь отчаянно чего-нибудь жаждало.$b$bЯ покупаю припасы у торговки по имени Мара Ренник. Она в городе недавно.$b$bОна упоминала, что хочет доставить кое-какие товары торговцу одеждой в Квартал Магов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Марой Ренник в портновской лавке в Квартале Магов Подгорода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Боюсь, я продала всю партию духов и одеколона Норману, хозяину таверны. Если они тебе нужны, поговори с ним – может быть, у него что-то еще осталось.$B$BНо не трать времени. Полагаю, ты сочтешь запах одеколона просто неотразимым.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8984,'Источник обнаружен','Видишь ли, действия какого-то негодяя-аптекаря – не моя забота. Если он вредит нашему делу, то я буду первой, кто укажет тебе нужное направление поисков.$b$bЕсли он невиновен, то ему нечего скрывать, верно?$b$bЯ приобрела товары у аптекаря Стаффрона Лерента. Он работает в укромном уголке за поместьем Черный Ворон в предгорях Хилсбрада. Честно говоря, он показался мне несколько странным.','Найдите аптекаря Стаффрона Лерента в предгорьях Хилсбрада за поместьем Черный Ворон.','Да, я сделал эти благовония. Чудный запах, не так ли? Неотразимый.$B$BКогда воины Альянса и Орды равно будут сражены этой любовью, они не смогут остановить воздвижение Совета Тени.$B$BОни окажется ослабленными и неподготовленными. Беспокоясь за тех, кого любят, они потеряют бдительность.$B$BРешение было таким простым. Почему понадобилось столько времени, чтобы найти его? Слабое место любого – его сердце. И тебе уже не остановить неизбежное.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник обнаружен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь ли, действия какого-то негодяя-аптекаря – не моя забота. Если он вредит нашему делу, то я буду первой, кто укажет тебе нужное направление поисков.$b$bЕсли он невиновен, то ему нечего скрывать, верно?$b$bЯ приобрела товары у аптекаря Стаффрона Лерента. Он работает в укромном уголке за поместьем Черный Ворон в предгорях Хилсбрада. Честно говоря, он показался мне несколько странным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите аптекаря Стаффрона Лерента в предгорьях Хилсбрада за поместьем Черный Ворон.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я сделал эти благовония. Чудный запах, не так ли? Неотразимый.$B$BКогда воины Альянса и Орды равно будут сражены этой любовью, они не смогут остановить воздвижение Совета Тени.$B$BОни окажется ослабленными и неподготовленными. Беспокоясь за тех, кого любят, они потеряют бдительность.$B$BРешение было таким простым. Почему понадобилось столько времени, чтобы найти его? Слабое место любого – его сердце. И тебе уже не остановить неизбежное.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8985,'Еще одна важная составляющая заклинания','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моей павшей соратницы.$B$BИзалиен, наша жрица, выросла в Зимних Ключах в Деревне Звездного Ветра. Забери реликвию Деревни Звездного Ветра у великанов ледяного молота в теснине Ледяного Шепота в южной части Зимних Ключей.','Найдите реликвию Деревни Звездного Ветра и принести ее Бодли в Черную гору.','Отличная работа, $N. Я наполню жаровню сущностью реликвии.$B$BТеперь все, что осталось, - это пойти в Святилище Эльдретарра в восточном крыле Забытого Города и использовать жаровню, чтобы призвать дух моей бывшей когорты. Ее дух был испорчен из-за того, что она завладела частью амулета Валтхалака и частью его души внутри него.$B$BOх, кстати, у меня были остатки кровавой водоросли от вашей поездки на остров Алькас, поэтому я превратил ее в несколько зелий для тебя. Выбирай!','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще одна важная составляющая заклинания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моей павшей соратницы.$B$BИзалиен, наша жрица, выросла в Зимних Ключах в Деревне Звездного Ветра. Забери реликвию Деревни Звездного Ветра у великанов ледяного молота в теснине Ледяного Шепота в южной части Зимних Ключей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите реликвию Деревни Звездного Ветра и принести ее Бодли в Черную гору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Я наполню жаровню сущностью реликвии.$B$BТеперь все, что осталось, - это пойти в Святилище Эльдретарра в восточном крыле Забытого Города и использовать жаровню, чтобы призвать дух моей бывшей когорты. Ее дух был испорчен из-за того, что она завладела частью амулета Валтхалака и частью его души внутри него.$B$BOх, кстати, у меня были остатки кровавой водоросли от вашей поездки на остров Алькас, поэтому я превратил ее в несколько зелий для тебя. Выбирай!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8986,'Еще одна важная составляющая заклинания','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего соратника.$B$BУ Мора Серого Копыта, нашего выдающегося друида, было немало хороших друзей в Круге Кенария, и некоторые из них пали жертвой атаки силитидов. Мне нужно, чтобы ты $gзабрал:забрала; останки погибших друидов у силитидов из Улья Регал, что на юго-востоке Силитуса.','Найдите останки друидов и принести их Бодли в Черную гору.','Отличная работа, $N. Я наполню жаровню сущностью реликвии.$B$BТеперь все, что осталось, - это отправиться в нижнюю часть Пика Черной горы, в комнату, где находится Военный Мастер Вун в Тазз\'Алаоре, и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Он не может успокоиться, пока у него не отберут амулет.$B$BОх, кстати, у меня были остатки кровавой капусты после вашей поездки на остров Алькас, поэтому я приготовил для тебя зелья. Выбирай!','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще одна важная составляющая заклинания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего соратника.$B$BУ Мора Серого Копыта, нашего выдающегося друида, было немало хороших друзей в Круге Кенария, и некоторые из них пали жертвой атаки силитидов. Мне нужно, чтобы ты $gзабрал:забрала; останки погибших друидов у силитидов из Улья Регал, что на юго-востоке Силитуса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите останки друидов и принести их Бодли в Черную гору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Я наполню жаровню сущностью реликвии.$B$BТеперь все, что осталось, - это отправиться в нижнюю часть Пика Черной горы, в комнату, где находится Военный Мастер Вун в Тазз\'Алаоре, и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Он не может успокоиться, пока у него не отберут амулет.$B$BОх, кстати, у меня были остатки кровавой капусты после вашей поездки на остров Алькас, поэтому я приготовил для тебя зелья. Выбирай!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8987,'Еще одна важная составляющая заклинания','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь. Но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет духов моих бывших соратников.$B$BДжариен и Сотос оставили нас и решили присоединиться к Алому ордену, свято уверовав в его путь. Они так стремились вступить в эту подлую организацию... но не прошли испытания на посвящении. Отправляйся в Длань Тира в Восточные Чумные земли и забери сверкающий меч Фанатизма у тамошних преторов.','Добыть сверкающий меч Фанатизма и принести его Бодли в Черную гору.','Отличная работа, $N. Я наполню жаровню сущностью меча.$B$BТеперь все, что осталось, - это попасть в Багровый трон внутри Алого бастиона в Стратхольме и использовать жаровню, чтобы призвать останки моих бывших когорт, Джариена и Сотос. Их души были искажены еще больше из-за того, что они владели амулетом Валтхалака c его духом внутри.$B$BЯ приготовил для тебя зелья. Выбирай!','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще одна важная составляющая заклинания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь. Но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет духов моих бывших соратников.$B$BДжариен и Сотос оставили нас и решили присоединиться к Алому ордену, свято уверовав в его путь. Они так стремились вступить в эту подлую организацию... но не прошли испытания на посвящении. Отправляйся в Длань Тира в Восточные Чумные земли и забери сверкающий меч Фанатизма у тамошних преторов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добыть сверкающий меч Фанатизма и принести его Бодли в Черную гору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Я наполню жаровню сущностью меча.$B$BТеперь все, что осталось, - это попасть в Багровый трон внутри Алого бастиона в Стратхольме и использовать жаровню, чтобы призвать останки моих бывших когорт, Джариена и Сотос. Их души были искажены еще больше из-за того, что они владели амулетом Валтхалака c его духом внутри.$B$BЯ приготовил для тебя зелья. Выбирай!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8988,'Еще одна важная составляющая заклинания','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего товарища.$B$BКормок, огр-некромант, путешествовавший вместе с нами, обосновался впоследствии на южном побережье предгорий Хилсбрада и вызвал души изгнанных мертвецов, обитателей острова Очищения. Иди туда и добудь пепел душ Изгнанников.','Добыть пепел душ Изгнанников и принести его Бодли в Черную гору.','Отличная работа, $N. Я наполню жаровню сущностью останков.$B$BТеперь все, что осталось, - это попасть в Некроситет, в комнату Раса Ледяного Шепота и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Он не может успокоиться, пока у него не отберут амулет.$B$BЯ приготовил для тебя зелья. Выбирай!','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще одна важная составляющая заклинания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, слушай внимательно. Теперь у нас есть жаровня и все, что нужно, чтобы зажечь в ней огонь, но нам не хватает одной важной вещи, чтобы все получилось, как должно. Нам нужно что-то, что сосредоточит великую силу и привлечет дух моего павшего товарища.$B$BКормок, огр-некромант, путешествовавший вместе с нами, обосновался впоследствии на южном побережье предгорий Хилсбрада и вызвал души изгнанных мертвецов, обитателей острова Очищения. Иди туда и добудь пепел душ Изгнанников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добыть пепел душ Изгнанников и принести его Бодли в Черную гору.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Я наполню жаровню сущностью останков.$B$BТеперь все, что осталось, - это попасть в Некроситет, в комнату Раса Ледяного Шепота и использовать жаровню для призыва испорченный дух моей бывшей когорты Мор Серое Копыто. Он не может успокоиться, пока у него не отберут амулет.$B$BЯ приготовил для тебя зелья. Выбирай!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже вернулся, $C, с тем, за чем я тебя посылал собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8989,'Правая часть амулета Лорда Вальтхалака','Мой товарищ Мор Серое Копыто был первым, кто завладел частью разбитого амулета Лорда Вальтхалака и пал жертвой разрушительных чар осколка духа Лорда, заключенного внутри. После того как мы выкрали книгу заклинаний Вальтхалака и амулет, мы попытались укрыться в верхних пределах Пика Черной горы. Но когда мы туда поднимались, Мор сорвался и упал.$B$BПотом мы узнали, что он не разбился, но его захватил и подверг страшным пыткам воевода Вун. Призрачные убийцы пробрались к нему и убили его на глазах у Вуна.','Вызвать дух Мора Серого Копыта с помощью жаровни Призыва, прикончить его и забрать недостающую часть амулета Лорда Вальтхалака. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.','Спасибо за помощь, $N. Другой дух покоиться с миром и теперь у нас собранный амулет! Но впереди нас ещё ждет самое сложное испытание.$B$BДля того чтобы жаровня была готова к призыву Лорда Вальтхалака, нам нужно ещё несколько вещей.','Ты возвращаешь правую часть амулета, и мы восстанавливаем его. По моему звучит легко.','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правая часть амулета Лорда Вальтхалака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой товарищ Мор Серое Копыто был первым, кто завладел частью разбитого амулета Лорда Вальтхалака и пал жертвой разрушительных чар осколка духа Лорда, заключенного внутри. После того как мы выкрали книгу заклинаний Вальтхалака и амулет, мы попытались укрыться в верхних пределах Пика Черной горы. Но когда мы туда поднимались, Мор сорвался и упал.$B$BПотом мы узнали, что он не разбился, но его захватил и подверг страшным пыткам воевода Вун. Призрачные убийцы пробрались к нему и убили его на глазах у Вуна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызвать дух Мора Серого Копыта с помощью жаровни Призыва, прикончить его и забрать недостающую часть амулета Лорда Вальтхалака. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь, $N. Другой дух покоиться с миром и теперь у нас собранный амулет! Но впереди нас ещё ждет самое сложное испытание.$B$BДля того чтобы жаровня была готова к призыву Лорда Вальтхалака, нам нужно ещё несколько вещей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты возвращаешь правую часть амулета, и мы восстанавливаем его. По моему звучит легко.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8990,'Правая часть амулета Лорда Вальтхалака','Недавно нам стало известно, что наша бывшая соратница Изалиен, жрица ночных эльфов, отправилась в древнее поселение своего народа, известное теперь под названием Забытый Город. Насколько нам удалось узнать, она отправилась в Забытый Город как по личным причинам, так и за тем, чтобы вызнать секреты той части амулета Лорда Вальтхалака, которую она забрала с собой.$B$BНо ее замыслам не суждено было сбыться. До нас дошли слухи, что у святилища Элдретарра Изалиен попала в засаду, которую устроил Алззин Перевертень.','С помощью жаровни Призыва вызвать дух Изалиен и убить ее. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.','Спасибо за помощь, $N. Другой дух покоиться с миром и теперь у нас собранный амулет! Но впереди нас ещё ждет самое сложное испытание.$B$BДля того чтобы жаровня была готова к призыву Лорда Вальтхалака, нам нужно ещё несколько вещей.','И конечно же, ты уже $Gспас:спасла; дух Изалиен и $Gизвлек:извлекла; правую часть амулета, $N?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правая часть амулета Лорда Вальтхалака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно нам стало известно, что наша бывшая соратница Изалиен, жрица ночных эльфов, отправилась в древнее поселение своего народа, известное теперь под названием Забытый Город. Насколько нам удалось узнать, она отправилась в Забытый Город как по личным причинам, так и за тем, чтобы вызнать секреты той части амулета Лорда Вальтхалака, которую она забрала с собой.$B$BНо ее замыслам не суждено было сбыться. До нас дошли слухи, что у святилища Элдретарра Изалиен попала в засаду, которую устроил Алззин Перевертень.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью жаровни Призыва вызвать дух Изалиен и убить ее. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь, $N. Другой дух покоиться с миром и теперь у нас собранный амулет! Но впереди нас ещё ждет самое сложное испытание.$B$BДля того чтобы жаровня была готова к призыву Лорда Вальтхалака, нам нужно ещё несколько вещей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И конечно же, ты уже $Gспас:спасла; дух Изалиен и $Gизвлек:извлекла; правую часть амулета, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8991,'Правая часть амулета Лорда Вальтхалака','Наши бывшие соратники Сотос и Джариен некогда решили вступить в ряды Алого ордена. Уходя, они забрали с собой правую часть амулета Лорда Вальтхалака. Я всегда говорил: оно даже и к лучшему, что мы избавились от этой проклятой вещицы, но сейчас ее надо вернуть.$B$BНасколько мы знаем, Джариен и Сотос не прошли испытание на ритуале посвящения в чертоге Датрохана в Бастионе Алого ордена, и Верховный рыцарь собственноручно прикончил обоих.$B$BКак бы там ни было, нам нужна эта часть амулета, и мы... то есть ты... $gдолжен:должна; будешь ее забрать.','Вызвать духов Джариен и Сотоса с помощью жаровни Призыва и убить их обоих. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.','Спасибо за помощь, $N. Другой дух покоиться с миром и теперь у нас собранный амулет! Но впереди нас ещё ждет самое сложное испытание.$B$BДля того чтобы жаровня была готова к призыву Лорда Вальтхалака, нам нужно ещё несколько вещей.','Означает ли твоё возвращение, что тебе удалось упокоить этих двух глупцов и собрать амулет?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правая часть амулета Лорда Вальтхалака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши бывшие соратники Сотос и Джариен некогда решили вступить в ряды Алого ордена. Уходя, они забрали с собой правую часть амулета Лорда Вальтхалака. Я всегда говорил: оно даже и к лучшему, что мы избавились от этой проклятой вещицы, но сейчас ее надо вернуть.$B$BНасколько мы знаем, Джариен и Сотос не прошли испытание на ритуале посвящения в чертоге Датрохана в Бастионе Алого ордена, и Верховный рыцарь собственноручно прикончил обоих.$B$BКак бы там ни было, нам нужна эта часть амулета, и мы... то есть ты... $gдолжен:должна; будешь ее забрать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызвать духов Джариен и Сотоса с помощью жаровни Призыва и убить их обоих. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь, $N. Другой дух покоиться с миром и теперь у нас собранный амулет! Но впереди нас ещё ждет самое сложное испытание.$B$BДля того чтобы жаровня была готова к призыву Лорда Вальтхалака, нам нужно ещё несколько вещей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Означает ли твоё возвращение, что тебе удалось упокоить этих двух глупцов и собрать амулет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8992,'Правая часть амулета Лорда Вальтхалака','Теперь, когда у нас есть все, что нужно для ритуала призыва, осталось решить, кого именно вызвать.$B$BКормок был неплохим парнем, пока не занялся некромантией. Вот тогда нам всем стало по-настоящему жутко – и это при том, что отряд набирали уж явно не из боязливых юнцов и кисейных барышень. Никто не удивился, когда он забрал свою часть амулета и вернулся в свой новый дом в Некроситете.$B$BНо даже там он не укрылся от призрачных убийц. Они прикончили его на глазах у Раса Ледяного Шепота, его хозяина.','С помощью жаровни Призыва вызвать дух Кормока и убить его. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.','Спасибо за помощь, $N. Другой дух покоиться с миром и теперь у нас собранный амулет! Но впереди нас ещё ждет самое сложное испытание.$B$BДля того чтобы жаровня была готова к призыву Лорда Вальтхалака, нам нужно ещё несколько вещей.','Ты $Gвернулся:вернулась; с амулетом?','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правая часть амулета Лорда Вальтхалака',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у нас есть все, что нужно для ритуала призыва, осталось решить, кого именно вызвать.$B$BКормок был неплохим парнем, пока не занялся некромантией. Вот тогда нам всем стало по-настоящему жутко – и это при том, что отряд набирали уж явно не из боязливых юнцов и кисейных барышень. Никто не удивился, когда он забрал свою часть амулета и вернулся в свой новый дом в Некроситете.$B$BНо даже там он не укрылся от призрачных убийц. Они прикончили его на глазах у Раса Ледяного Шепота, его хозяина.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью жаровни Призыва вызвать дух Кормока и убить его. Вернуться к Бодли в Черную гору, отдать ему восстановленный амулет и жаровню Призыва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь, $N. Другой дух покоиться с миром и теперь у нас собранный амулет! Но впереди нас ещё ждет самое сложное испытание.$B$BДля того чтобы жаровня была готова к призыву Лорда Вальтхалака, нам нужно ещё несколько вещей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась; с амулетом?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8993,'Подношение даров','Вы пришли подарить любимому лидеру подарок любви и обожания?','Вернитесь к Кви К. Мелкошустру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подношение даров',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы пришли подарить любимому лидеру подарок любви и обожания?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кви К. Мелкошустру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8994,'Последние приготовления','У нас почти все готово, |3-6($c). Осталось найти еще несколько компонентов, и тогда я смогу должным образом настроить жаровню и вызвать дух Лорда Вальтхалака.$B$BДля начала я попрошу тебя отправиться в Пик Черной горы и перебить тамошних орков. Они носят наручи из особого сплава металлов, один из которых как раз мне и нужен. Постарайся собрать их как можно больше, чтобы я смог извлечь необходимое количество металла. И еще мне понадобится настой великой силы. Без нее я не смогу завершить заклинание.$B$BИди, $n, и да пребудет с тобой удача!','Соберите 40 наручей Черной горы и разыщите склянку великой силы. Отнесите все это Бодли в Черную Скалу.','Вот и всё. Я извлёк металл из браслетов и наполнил им жаровню. Скоро она будет готова для вызова Лорда Вальтхалака.$B$BМы уже очень далеко зашли, $N, и нет обратного пути!','Мы прошли долгий путь, $N, и я хотел быть сказать, что независим оттого, что произойдет, спасибо! Ты $Gподверг:подвергла; себя смертельной опасности, чтобы помочь нам.','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последние приготовления',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас почти все готово, |3-6($c). Осталось найти еще несколько компонентов, и тогда я смогу должным образом настроить жаровню и вызвать дух Лорда Вальтхалака.$B$BДля начала я попрошу тебя отправиться в Пик Черной горы и перебить тамошних орков. Они носят наручи из особого сплава металлов, один из которых как раз мне и нужен. Постарайся собрать их как можно больше, чтобы я смог извлечь необходимое количество металла. И еще мне понадобится настой великой силы. Без нее я не смогу завершить заклинание.$B$BИди, $n, и да пребудет с тобой удача!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 40 наручей Черной горы и разыщите склянку великой силы. Отнесите все это Бодли в Черную Скалу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот и всё. Я извлёк металл из браслетов и наполнил им жаровню. Скоро она будет готова для вызова Лорда Вальтхалака.$B$BМы уже очень далеко зашли, $N, и нет обратного пути!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы прошли долгий путь, $N, и я хотел быть сказать, что независим оттого, что произойдет, спасибо! Ты $Gподверг:подвергла; себя смертельной опасности, чтобы помочь нам.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8995,'Mea Culpa, Лорд Вальтхалак','Теперь все готово, $n.$B$BПри жизни Лорд Вальтхалак жил в чертоге, который теперь называется чертогом Зверя. Отправляйся туда, зажги огонь в жаровне Призыва и вызови дух владыки. При этом Вальтхалак вновь обретет тело, и тебе придется убить его еще раз. Но сначала тебе нужно сразиться со Зверем владыки, так что лучше иди не $gодин:одна;, а возьми себе в помощь верных друзей, ибо немногие возвращались из верхних пределов Пика Черной горы живыми.$B$BКогда убьешь Вальтхалака, используй амулет. Как только дух Лорда обретет целостность, он потребует вернуть ему амулет. И это его право!$B$BУдачи!','Вызвать Лорда Вальтхалака с помощью жаровни Призыва. Убить его и использовать амулет. Потом вернуть амулет духу Вальтхалака.','Какое счастье для тебя, что ты не член той группы, которая украла у меня это.$B$BЯ забираю то, что по праву принадлежит мне, $Gсмертный:смертная;! Отдай мне амулет!','$C, как ты посмел нарушить мой покой?','Вернитесь к духу Лорда Вальтхалака на Вершину Черной горы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Mea Culpa, Лорд Вальтхалак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь все готово, $n.$B$BПри жизни Лорд Вальтхалак жил в чертоге, который теперь называется чертогом Зверя. Отправляйся туда, зажги огонь в жаровне Призыва и вызови дух владыки. При этом Вальтхалак вновь обретет тело, и тебе придется убить его еще раз. Но сначала тебе нужно сразиться со Зверем владыки, так что лучше иди не $gодин:одна;, а возьми себе в помощь верных друзей, ибо немногие возвращались из верхних пределов Пика Черной горы живыми.$B$BКогда убьешь Вальтхалака, используй амулет. Как только дух Лорда обретет целостность, он потребует вернуть ему амулет. И это его право!$B$BУдачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вызвать Лорда Вальтхалака с помощью жаровни Призыва. Убить его и использовать амулет. Потом вернуть амулет духу Вальтхалака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какое счастье для тебя, что ты не член той группы, которая украла у меня это.$B$BЯ забираю то, что по праву принадлежит мне, $Gсмертный:смертная;! Отдай мне амулет!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$C, как ты посмел нарушить мой покой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу Лорда Вальтхалака на Вершину Черной горы.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8996,'Возвращение к Бодли','На сей раз я прощаю тебе твою дерзость, |3-6($c), потому что сегодня ты $gсовершил:совершила; благородный поступок: $gвернул:вернула; мне недостающие части моей украденной души. Быть может, тебе не хватает телесной мощи, |3-6($r), но ты $gкрепок духом, смел и отважен:крепка духом, смела и отважна;, в отличие от тех, кто украл мою душу!$B$BВозвращайся к ним, пока я не передумал и не прикончил тебя на месте. Иди к ним и скажи, что им ничего не грозит... до поры до времени.','Вернитесь к Бодли в Черную гору и отдайте ему жаровню Призыва.','Что, правда?! Он так и сказал? Ушам не верю! Он действительно собирается отозвать призрачных убийц?! Хотя, как я понимаю, он намекнул, что в будущем намеревается разобраться с моими товарищами – с теми, кто ещё жив.$B$BСегодня – великий день, $N! Ты $Gсумел:сумела; сделать то, что удавалось лишь считанным единицам, и хоть и отчасти, но все-таки $Gосвободил:освободила; нас от прошлых грехов.$B$BСпасибо! Прими это в знак благодарности. Эту вещь можно использовать для призыва тех духов, с которыми ты уже $Gимел:имела; дело и некоторых других...','$N, ты $Gвернулся:вернулась; и все ещё $Gжив:жива;! Хоть $Gодин:одна; из нас.','Вернитесь к Бодли в Пылающие степи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Бодли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На сей раз я прощаю тебе твою дерзость, |3-6($c), потому что сегодня ты $gсовершил:совершила; благородный поступок: $gвернул:вернула; мне недостающие части моей украденной души. Быть может, тебе не хватает телесной мощи, |3-6($r), но ты $gкрепок духом, смел и отважен:крепка духом, смела и отважна;, в отличие от тех, кто украл мою душу!$B$BВозвращайся к ним, пока я не передумал и не прикончил тебя на месте. Иди к ним и скажи, что им ничего не грозит... до поры до времени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Бодли в Черную гору и отдайте ему жаровню Призыва.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, правда?! Он так и сказал? Ушам не верю! Он действительно собирается отозвать призрачных убийц?! Хотя, как я понимаю, он намекнул, что в будущем намеревается разобраться с моими товарищами – с теми, кто ещё жив.$B$BСегодня – великий день, $N! Ты $Gсумел:сумела; сделать то, что удавалось лишь считанным единицам, и хоть и отчасти, но все-таки $Gосвободил:освободила; нас от прошлых грехов.$B$BСпасибо! Прими это в знак благодарности. Эту вещь можно использовать для призыва тех духов, с которыми ты уже $Gимел:имела; дело и некоторых других...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты $Gвернулся:вернулась; и все ещё $Gжив:жива;! Хоть $Gодин:одна; из нас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бодли в Пылающие степи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8997,'Круг замкнулся','Как это ни грустно, $gдружище:моя госпожа;, пришло время прощаться. Но если ты вдруг соберешься меня навестить, я всегда буду рад встрече с $gдругом:доброй подругой;. Приходи, когда хочешь. Может быть, даже в самое ближайшее время, пока ты еще не $gотправился:отправилась; в Пик Черной горы.$B$BЛадно, долгие проводы – лишние слезы. Иди, пока я действительно не прослезился. Возвращайся к Делиане в Стальгорн и расскажи ей обо всем, что случилось.','Поговорите с Делианой в Высоком троне в Стальгорне.','Рада видеть тебя, $N.$B$BНу, расскажи мне, что выяснилось.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Круг замкнулся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как это ни грустно, $gдружище:моя госпожа;, пришло время прощаться. Но если ты вдруг соберешься меня навестить, я всегда буду рад встрече с $gдругом:доброй подругой;. Приходи, когда хочешь. Может быть, даже в самое ближайшее время, пока ты еще не $gотправился:отправилась; в Пик Черной горы.$B$BЛадно, долгие проводы – лишние слезы. Иди, пока я действительно не прослезился. Возвращайся к Делиане в Стальгорн и расскажи ей обо всем, что случилось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Делианой в Высоком троне в Стальгорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рада видеть тебя, $N.$B$BНу, расскажи мне, что выяснилось.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (8998,'Круг замкнулся','Как это ни грустно, $gдружище:моя госпожа;, пришло время прощаться. Но если ты вдруг соберешься меня навестить, я всегда буду рад встрече с $gдругом:доброй подругой;. Приходи когда хочешь. Может быть, даже в самое ближайшее время, пока ты еще не $gотправился:отправилась; на Пик Черной горы.$B$BЛадно, долгие проводы – лишние слезы. Иди, пока я действительно не прослезился. Возвращайся к Моквару в Оргриммар и расскажи ему обо всем, что случилось.','Поговорите с Мокваром в крепости Громмаш на Аллее Мудрости в Оргриммаре.','Я рад видеть, что ты $Gжив:жива;, $N.$B$BРасскажи, что удалось узнать?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Круг замкнулся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как это ни грустно, $gдружище:моя госпожа;, пришло время прощаться. Но если ты вдруг соберешься меня навестить, я всегда буду рад встрече с $gдругом:доброй подругой;. Приходи когда хочешь. Может быть, даже в самое ближайшее время, пока ты еще не $gотправился:отправилась; на Пик Черной горы.$B$BЛадно, долгие проводы – лишние слезы. Иди, пока я действительно не прослезился. Возвращайся к Моквару в Оргриммар и расскажи ему обо всем, что случилось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мокваром в крепости Громмаш на Аллее Мудрости в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад видеть, что ты $Gжив:жива;, $N.$B$BРасскажи, что удалось узнать?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (8999,'Сладкое – на закуску','Замечательная история, $n! Спасибо тебе и сердечная благодарность всем, кто принимал участие. Может, сегодня ночью я хоть нормально посплю.$B$BВ награду хочу предложить несколько вещичек, что тебя, наверное, порадуют.','Отдайте Делиане клобук и жилет дикого сердца.','Я буду скучать по тебе, $N. Я в долгу перед тобой,думаю, я никогда не смогу расплатиться за это.$B$BНадеюсь, что тебе понравятся твои новые доспехи, и что они будут защищать тебя.','В соответствии с нашей сделкой, готовы ли вы отдать свои части Дикого Сердца в обмен на новый Клобук и Жилет Буйного Сердца?','Вернитесь к Делиане к Высокому трону, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сладкое – на закуску',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Замечательная история, $n! Спасибо тебе и сердечная благодарность всем, кто принимал участие. Может, сегодня ночью я хоть нормально посплю.$B$BВ награду хочу предложить несколько вещичек, что тебя, наверное, порадуют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте Делиане клобук и жилет дикого сердца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я буду скучать по тебе, $N. Я в долгу перед тобой,думаю, я никогда не смогу расплатиться за это.$B$BНадеюсь, что тебе понравятся твои новые доспехи, и что они будут защищать тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В соответствии с нашей сделкой, готовы ли вы отдать свои части Дикого Сердца в обмен на новый Клобук и Жилет Буйного Сердца?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9000,'Сладкое – на закуску','Замечательная история, $n! Спасибо тебе и сердечная благодарность всем, кто принимал участие. Может, сегодня ночью я хоть нормально посплю.$B$BВ награду хочу предложить несколько вещичек, что тебя, наверное, порадуют.','Отдайте Делиане шапку и мундир загонщика.','Я буду скучать по тебе, $N. Я в долгу перед тобой,думаю, я никогда не смогу расплатиться за это.$B$BНадеюсь, что тебе понравятся твои новые доспехи, и что они будут защищать тебя.','В соответствии с нашей сделкой, готовы ли вы отдать свои части загонщика в обмен на новую Шапку и Мундир Повелителя Зверей?','Вернитесь к Делиане к Высокому трону, что в Стальгорне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сладкое – на закуску',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Замечательная история, $n! Спасибо тебе и сердечная благодарность всем, кто принимал участие. Может, сегодня ночью я хоть нормально посплю.$B$BВ награду хочу предложить несколько вещичек, что тебя, наверное, порадуют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте Делиане шапку и мундир загонщика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я буду скучать по тебе, $N. Я в долгу перед тобой,думаю, я никогда не смогу расплатиться за это.$B$BНадеюсь, что тебе понравятся твои новые доспехи, и что они будут защищать тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В соответствии с нашей сделкой, готовы ли вы отдать свои части загонщика в обмен на новую Шапку и Мундир Повелителя Зверей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Делиане к Высокому трону, что в Стальгорне.',`completedtext_loc8`);
