INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9007,'Сладкое – на закуску','Воистину удивительная история, $n! Я тебе признателен от всей души – и не только я, но и все, кто замешан в этой истории. Благодаря твоим трудам мы избавились от ошибок нашего прошлого.$b$bПоговорим теперь о твоей награде. У меня есть кое-что, что наверняка придется тебе по нраву!','Отдайте Моквару клобук дикого сердца и жилет дикого сердца.','Я буду скучать по тебе, $N. Я в долгу перед тобой,думаю, я никогда не смогу расплатиться за это.$B$BНадеюсь, что тебе понравятся твои новые доспехи и они помогут добиться ещё большей чести!','В соответствии с нашей сделкой, готовы ли вы отдать свои части Дикого Сердца в обмен на новый Клобук и Жилет Буйного Сердца?','Вернитесь к Моквару в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сладкое – на закуску',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воистину удивительная история, $n! Я тебе признателен от всей души – и не только я, но и все, кто замешан в этой истории. Благодаря твоим трудам мы избавились от ошибок нашего прошлого.$b$bПоговорим теперь о твоей награде. У меня есть кое-что, что наверняка придется тебе по нраву!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте Моквару клобук дикого сердца и жилет дикого сердца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я буду скучать по тебе, $N. Я в долгу перед тобой,думаю, я никогда не смогу расплатиться за это.$B$BНадеюсь, что тебе понравятся твои новые доспехи и они помогут добиться ещё большей чести!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В соответствии с нашей сделкой, готовы ли вы отдать свои части Дикого Сердца в обмен на