INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9014,'Сладкое – на закуску','Воистину удивительная история, $n! Я тебе признателен от всей души – и не только я, но и все, кто замешан в этой истории. Благодаря твоим трудам мы избавились от ошибок нашего прошлого.$b$bПоговорим теперь о твоей награде. У меня есть кое-что, что наверняка придется тебе по нраву!','Отдайте Моквару корону Магистра и одеяние Магистра.','Я буду скучать по тебе, $N. Я в долгу перед тобой,думаю, я никогда не смогу расплатиться за это.$B$BНадеюсь, что тебе понравятся твои новые доспехи и они помогут добиться ещё большей чести!','В соответствии с нашей сделкой, готовы ли вы отдать свои части магистра в обмен на новую Корону и Одеяния волшебника?','Вернитесь к Моквару в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сладкое – на закуску',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воистину удивительная история, $n! Я тебе признателен от всей души – и не только я, но и все, кто замешан в этой истории. Благодаря твоим трудам мы избавились от ошибок нашего прошлого.$b$bПоговорим теперь о твоей награде. У меня есть кое-что, что наверняка придется тебе по нраву!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте Моквару корону Магистра и одеяние Магистра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я буду скучать по тебе, $N. Я в долгу перед тобой,думаю, я никогда не смогу расплатиться за это.$B$BНадеюсь, что тебе понравятся твои новые доспехи и они помогут добиться ещё большей чести!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В соответствии с нашей сделкой, готовы ли вы отдать свои части магистра в обмен на новую Корону и Одеяния волшебника?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моквару в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9015,'Вызов','Слушай внимательно, $n. Тебе нужно будет войти в Зал Правосудия в Глубинах Черной горы. Когда верховный судья Мрачнокамень вынесет тебе приговор, вонзи знамя в землю в знак открытого неповиновения.$B$BТелдрен не сможет сдержаться и примет вызов на бой, горя желанием драться. Убей его и забери то, что должно забрать, после чего передай эту вещь Антиону.','Войдите в Зал Правосудия в Глубинах Черной горы, выслушайте приговор верховного судьи Мрачнокамня и вонзите знамя Вызова в центр круга. Убейте Телдрена и его гладиаторов, после чего вернитесь к Антиону Хармону в Восточные Чумные земли с первой частью амулета Лорда Вальтхалака.','Ты $Gвосстановил:восстановила; часть медальона, $N.','Ты $Gвернулся:вернулась;, $N!','Вернитесь к Антиону Хармону в Стратхольм, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай внимательно, $n. Тебе нужно будет войти в Зал Правосудия в Глубинах Черной горы. Когда верховный судья Мрачнокамень вынесет тебе приговор, вонзи знамя в землю в знак открытого неповиновения.$B$BТелдрен не сможет сдержаться и примет вызов на бой, горя желанием драться. Убей его и забери то, что должно забрать, после чего передай эту вещь Антиону.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в Зал Правосудия в Глубинах Черной горы, выслушайте приговор верховного судьи Мрачнокамня и вонзите знамя Вызова в центр круга. Убейте Телдрена и его гладиаторов, после чего вернитесь к Антиону Хармону в Восточные Чумные земли с первой частью амулета Лорда Вальтхалака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gвосстановил:восстановила; часть медальона, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;, $N!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Антиону Хармону в Стратхольм, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9016,'Прощальные слова Антиона','В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$b$bЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части. Расскажи ему про обещанные награды.$b$bНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!','Отдайте Моквару в Оргриммаре сапоги дикого Сердца, килт дикого сердца и наплеч буйного сердца.','Это проклятие было наложено на нас за простой медальон. Лорд Валтхалак определенно знает, как затаить обиду.$B$BМы постараемся найти оставшиеся части - надеюсь, прежде чем я встречу безвременную кончину. Но перед этим давай посмотрим на твою награду.','Ты $Gвернулся:вернулась;, и по твоим глазам я вижу, что тебе есть что сказать мне, $N. Позвольте нам в первую очередь позаботиться о вашей награде.','Вернитесь к Моквару в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощальные слова Антиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$b$bЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части. Расскажи ему про обещанные награды.$b$bНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте Моквару в Оргриммаре сапоги дикого Сердца, килт дикого сердца и наплеч буйного сердца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это проклятие было наложено на нас за простой медальон. Лорд Валтхалак определенно знает, как затаить обиду.$B$BМы постараемся найти оставшиеся части - надеюсь, прежде чем я встречу безвременную кончину. Но перед этим давай посмотрим на твою награду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;, и по твоим глазам я вижу, что тебе есть что сказать мне, $N. Позвольте нам в первую очередь позаботиться о вашей награде.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моквару в Оргриммар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9017,'Прощальные слова Антиона','В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$b$bЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части. Расскажи ему про обещанные награды.$b$bНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!','Принесите Моквару в Оргриммаре сапоги загонщика, штаны загонщика и оплечье загонщика.','Это проклятие было наложено на нас за простой медальон. Лорд Валтхалак определенно знает, как затаить обиду.$B$BМы постараемся найти оставшиеся части - надеюсь, прежде чем я встречу безвременную кончину. Но перед этим давай посмотрим на твою награду.','Ты $Gвернулся:вернулась;, и по твоим глазам я вижу, что тебе есть что сказать мне, $N. Позвольте нам в первую очередь позаботиться о вашей награде.','Вернитесь к Моквару в Оргриммар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощальные слова Антиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$b$bЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Моквару и скажи ему, что Бодли – его единственная надежда найти оставшиеся части. Расскажи ему про обещанные награды.$b$bНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Моквару в Оргриммаре сапоги загонщика, штаны загонщика и оплечье загонщика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerreward