INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9023,'Идеальный яд','Мы с братом занимаемся составлением ядов для поместья Черный Ворон.$b$bЛорд Черный Ворон поручил мне исследование нового и очень эффективного яда, который производится из ядовитых желез обителей Зул\'Гуруба и руин Ан\'Киража.$b$bВ этих проклятых руинах живут две опасных твари, которые годятся для наших целей. Принеси мне ядовитые железы Куриннакс и Веноксиса, и заслужишь мою вечную признательность.','Дирк Громодрев из Крепости Кенария попросил принести ему ядовитую железу Веноксиса и ядовитую железу Куриннакса.','Ворон благодарит тебя, герой! Выбирайте!','Дельце не простое, $N. Без помощников тебе не обойтись.','Вернитесь к Дирку Громодреву в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальный яд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с братом занимаемся составлением ядов для поместья Черный Ворон.$b$bЛорд Черный Ворон поручил мне исследование нового и очень эффективного яда, который производится из ядовитых желез обителей Зул\'Гуруба и руин Ан\'Киража.$b$bВ этих проклятых руинах живут две опасных твари, которые годятся для наших целей. Принеси мне ядовитые железы Куриннакс и Веноксиса, и заслужишь мою вечную признательность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дирк Громодрев из Крепости Кенария попросил принести ему ядовитую железу Веноксиса и ядовитую железу Куриннакса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ворон благодарит тебя, герой! Выбирайте!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дельце не простое, $N. Без помощников тебе не обойтись.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дирку Громодреву в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9024,'Подозрения Аристана','Я понял! Ты чувствуешь новый запах в воздухе? Запах новых одеколонов и духов, только что вошедших в моду? Наши стражи не стали бы так просто пренебрегать своими обязанностями.$b$bИменно так – разве что их разум затуманен какой-то гнусной алхимией.$b$bЕсть только один способ убедиться – отнеси флакон одеколона и духов Моргану Песту и расскажи ему о моих подозрениях. Я возмещу тебе затраты, когда ты вернешься.','Отнесите 1 флакон одеколона и 1 флакон духов Моргану Песту в Торговый квартал Штормграда.','Я понимаю тревогу Аристана, но мне кажется, он перестарался. Пусть молодые мужчины и женщины делают то, что им нравится. Я думаю, Аристан просто забыл, что такое быть молодым и влюбленным. $B$BНо лучше ему этого не говорить. У него странное чувство юмора.','Я чем-нибудь могу тебе помочь?','Вернитесь к Моргану Песту в Штормград.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подозрения Аристана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я понял! Ты чувствуешь новый запах в воздухе? Запах новых одеколонов и духов, только что вошедших в моду? Наши стражи не стали бы так просто пренебрегать своими обязанностями.$b$bИменно так – разве что их разум затуманен какой-то гнусной алхимией.$b$bЕсть только один способ убедиться – отнеси флакон одеколона и духов Моргану Песту и расскажи ему о моих подозрениях. Я возмещу тебе затраты, когда ты вернешься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите 1 флакон одеколона и 1 флакон духов Моргану Песту в Торговый квартал Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я понимаю тревогу Аристана, но мне кажется, он перестарался. Пусть молодые мужчины и женщины делают то, что им нравится. Я думаю, Аристан просто забыл, что такое быть молодым и влюбленным. $B$BНо лучше ему этого не говорить. У него странное чувство юмора.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чем-нибудь могу тебе помочь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Моргану Песту в Штормград.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9025,'Открытие Моргана','Ну-с, что я скажу... Похоже, Аристан в конце концов все-таки напал на какой-то след. Я нашел остатки веществ, используемых в любовных зельях и хитрых средствах контроля разума.$b$bИзвестно, что такие вещества используются в некоторых духах, но некоторые из обнаруженных мною ингредиентов... Пахнет занятно.','Вернитесь к Аристану Моттару, ожидающему около банка в Торговом квартале Штормграда.','Как я и думал, мои подозрения подтвердились, что ещё больше тревожит. Мы должны тщательно обдумать наш следующий шаг. $B$BЭто, чтобы отплатить тебе за покупку одеколона и духов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Открытие Моргана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну-с, что я скажу... Похоже, Аристан в конце концов все-таки напал на какой-то след. Я нашел остатки веществ, используемых в любовных зельях и хитрых средствах контроля разума.$b$bИзвестно, что такие вещества используются в некоторых духах, но некоторые из обнаруженных мною ингредиентов... Пахнет занятно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Аристану Моттару, ожидающему около банка в Торговом квартале Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как я и думал, мои подозрения подтвердились, что ещё больше тревожит. Мы должны тщательно обдумать наш следующий шаг. $B$BЭто, чтобы отплатить тебе за покупку одеколона и духов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9026,'Поиск источника','Мы должны найти источник. Я видел гораздо больше народа, чем обычно, – в том числе и стражей – входящими в "Позолоченную розу" и выходящими оттуда. Поговори с Эллисон. Если она продает эти духи, она должна знать, откуда они взялись.','Поговорите с хозяйкой таверны "Позолоченная роза" Аллисон в Торговом квартале Штормграда.','Ах да, недавно у меня на складе появились духи и одеколон. Они так хорошо продаются, я не знаю, как долго он будет на полках. $B$BВсе пахнут одинаково? Пахнет здорово, но все же.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиск источника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны найти источник. Я видел гораздо больше народа, чем обычно, – в том числе и стражей – входящими в "Позолоченную розу" и выходящими оттуда. Поговори с Эллисон. Если она продает эти духи, она должна знать, откуда они взялись.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с хозяйкой таверны "Позолоченная роза" Аллисон в Торговом квартале Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах да, недавно у меня на складе появились духи и одеколон. Они так хорошо продаются, я не знаю, как долго он будет на полках. $B$BВсе пахнут одинаково? Пахнет здорово, но все же.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9027,'Поиск источника','В этом одеколоне есть что-то интересное? Возможно. Никогда не видела, чтобы столько народа так страстно желали приобрести один и тот же товар.$b$bПослушай, если с этим что-то не так, я тоже хочу знать. Я купила всю партию у торговца по имени Эверт Соризам. Он в городе недавно.$b$bОн упоминал, что собирается доставить кое-какие товары в "Тончайшую пряжу".','Поговорите с Эвертом Соризамом в "Тончайшей пряже" у каналов Штормграда.','Да, конечно. Эти благовония в нынешнем сезоне расходятся моментом. Только за последний час у меня уже пять или шесть раз спрашивали о них. $B$BБоюсь, я продал всю партию этого товара. Если он тебе нужен, поговори с хозяйкой таверны Эллисон в "Позолоченной Розе". $B$BНо не трать времени. Полагаю, ты сочтешь запах одеколона просто неотразимым.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиск источника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом одеколоне есть что-то интересное? Возможно. Никогда не видела, чтобы столько народа так страстно желали приобрести один и тот же товар.$b$bПослушай, если с этим что-то не так, я тоже хочу знать. Я купила всю партию у торговца по имени Эверт Соризам. Он в городе недавно.$b$bОн упоминал, что собирается доставить кое-какие товары в "Тончайшую пряжу".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эвертом Соризамом в "Тончайшей пряже" у каналов Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, конечно. Эти благовония в нынешнем сезоне расходятся моментом. Только за последний час у меня уже пять или шесть раз спрашивали о них. $B$BБоюсь, я продал всю партию этого товара. Если он тебе нужен, поговори с хозяйкой таверны Эллисон в "Позолоченной Розе". $B$BНо не трать времени. Полагаю, ты сочтешь запах одеколона просто неотразимым.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9028,'Источник обнаружен','Что? Предательство? Нет, нет, заверяю тебя, мои намерения были совершенно безобидными.$b$bЧто плохого в том, чтобы слегка помочь тем, кто желает облегчить мучительный ритуал ухаживания? Пойми, это не преступление.$b$bИ чтобы доказать, что я ничего плохого не желал, я даже назову источник этих благовоний. $b$bИх поставлял мне Стаффрон Лерент, какой-то аптекарь. Я никогда не говорил с ним.$b$bГоблин-посредник сказал, что этот аптекарь работает где-то в предгорьях Хилсбрада, за тем загадочным поместьем Черный Ворон. Желаю тебе удачи в поисках.','Найдите аптекаря Стаффрона Лерента в предгорьях Хилсбрада за поместьем Черный Ворон.','Да, я сделал эти благовония. Чудный запах, не так ли? Неотразимый.$B$BКогда воины Альянса и Орды равно будут сражены этой любовью, они не смогут остановить воздвижение Совета Тени.$B$BОни окажется ослабленными и неподготовленными. Беспокоясь за тех, кого любят, они потеряют бдительность.$B$BРешение было таким простым. Почему понадобилось столько времени, чтобы найти его? Слабое место любого – его сердце. И тебе уже не остановить неизбежное.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник обнаружен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что? Предательство? Нет, нет, заверяю тебя, мои намерения были совершенно безобидными.$b$bЧто плохого в том, чтобы слегка помочь тем, кто желает облегчить мучительный ритуал ухаживания? Пойми, это не преступление.$b$bИ чтобы доказать, что я ничего плохого не желал, я даже назову источник этих благовоний. $b$bИх поставлял мне Стаффрон Лерент, какой-то аптекарь. Я никогда не говорил с ним.$b$bГоблин-посредник сказал, что этот аптекарь работает где-то в предгорьях Хилсбрада, за тем загадочным поместьем Черный Ворон. Желаю тебе удачи в поисках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите аптекаря Стаффрона Лерента в предгорьях Хилсбрада за поместьем Черный Ворон.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я сделал эти благовония. Чудный запах, не так ли? Неотразимый.$B$BКогда воины Альянса и Орды равно будут сражены этой любовью, они не смогут остановить воздвижение Совета Тени.$B$BОни окажется ослабленными и неподготовленными. Беспокоясь за тех, кого любят, они потеряют бдительность.$B$BРешение было таким простым. Почему понадобилось столько времени, чтобы найти его? Слабое место любого – его сердце. И тебе уже не остановить неизбежное.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9029,'Бурлящий котел','Из котла доносится приятный запах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бурлящий котел',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Из котла доносится приятный запах.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9030,'Прощальные слова Антиона','В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$b$bЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Делиане и скажи ей, что Бодли – ее единственная надежда найти оставшиеся части. $b$bНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!','Поговорите с Делианой из Стальгорна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прощальные слова Антиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$b$bЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Делиане и скажи ей, что Бодли – ее единственная надежда найти оставшиеся части. $b$bНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Делианой из Стальгорна.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9031,'<TXT>Прощальные слова Антиона','В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$b$bЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Делиане и скажи ей, что Бодли – ее единственная надежда найти оставшиеся части. $b$bНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!','Поговорите с Мокваром из Оргриммара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<TXT>Прощальные слова Антиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом амулете хранилась душа Вальтхалака. Мы, по глупости и по жадности, раскололи его на три части, не ведая о проклятии, которое нас ожидало.$b$bЕдинственный способ остановить заклятие Вальтхалака – это снова собрать амулет воедино. Возвращайся к Делиане и скажи ей, что Бодли – ее единственная надежда найти оставшиеся части. $b$bНу, а я упокоюсь в мире. Желаю удачи. Она тебе понадобится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мокваром из Оргриммара.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9032,'Злосчастная доля Бодли','В медальоне заключена душа Вальтхалака? Неудивительно, что его охраняет столь мощное проклятие.$B$BНо разыскать Бодли будет непросто. Насколько я знаю, он собирался вернуться в Пик Черной горы, и с тех пор о нем больше никто не слышал.$B$BПопробуй найти его в Черной горе, хотя весьма вероятно, что Бодли уже нет в живых. Так что я бы тебе посоветовал взять с собой спектральный сканер иных измерений. Как ни горько мне говорить об этом, но лучше заранее приготовиться к самому худшему...','Отыщите Бодли у Пика Черной горы с помощью спектрального сканера иных измерений.','Ты себе даже не представляешь, как я рад, что меня видят и слышатI Наконец я дождался кого-то, с кем можно поговорить!$B$BТы нам поможешь, $N? Мы сами не ведали, что творили, и совершили великое зло, а теперь должны все исправить. Если ты $Gсказал:сказала; правду и у тебя действительно есть верхняя часть амулета Лорда Вальтхалака, я могу подсказать, где найти две оставшиеся части. Тогда амулет вновь обретет свою целостность, и весь этот ужас закончится.$B$BДа, кстати, меня зовут Бодли. Будем знакомы!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Злосчастная доля Бодли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В медальоне заключена душа Вальтхалака? Неудивительно, что его охраняет столь мощное проклятие.$B$BНо разыскать Бодли будет непросто. Насколько я знаю, он собирался вернуться в Пик Черной горы, и с тех пор о нем больше никто не слышал.$B$BПопробуй найти его в Черной горе, хотя весьма вероятно, что Бодли уже нет в живых. Так что я бы тебе посоветовал взять с собой спектральный сканер иных измерений. Как ни горько мне говорить об этом, но лучше заранее приготовиться к самому худшему...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Бодли у Пика Черной горы с помощью спектрального сканера иных измерений.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты себе даже не представляешь, как я рад, что меня видят и слышатI Наконец я дождался кого-то, с кем можно поговорить!$B$BТы нам поможешь, $N? Мы сами не ведали, что творили, и совершили великое зло, а теперь должны все исправить. Если ты $Gсказал:сказала; правду и у тебя действительно есть верхняя часть амулета Лорда Вальтхалака, я могу подсказать, где найти две оставшиеся части. Тогда амулет вновь обретет свою целостность, и весь этот ужас закончится.$B$BДа, кстати, меня зовут Бодли. Будем знакомы!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9033,'Отголоски войны','С последней войны прошло пять лет...$b$bПогибли десятки тысяч, и все ради чего? Нам так и не удалось избавиться от угрозы.$b$bТеперь же Король-лич вновь поднимает голову. Его правая рука, Кел\'Тузад, готовится напасть на наши земли.$b$bОн не пройдет! Докажи свою преданность нашему делу. Рискни своей жизнью ради победы над Плетью, а Серебряный Рассвет и Алый Марш прикроют тебя со спины.$b$bСтупай в Наксрамас и уничтожь воинство Плети...','Командир Элигор Вестник Рассвета из Часовни Последней Надежды, что в Восточных Чумных землях просит убить 5 ходячих ужасов, 5 каменных горгулий, 8 капитанов рыцарей Смерти и 3 ядовитых пауков-скакунов.','Отличая работа!','Долг, честь, преданность... Что для тебя значат эти слова?','Вернитесь к командиру Элигору Вестнику Рассвета в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отголоски войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С последней войны прошло пять лет...$b$bПогибли десятки тысяч, и все ради чего? Нам так и не удалось избавиться от угрозы.$b$bТеперь же Король-лич вновь поднимает голову. Его правая рука, Кел\'Тузад, готовится напасть на наши земли.$b$bОн не пройдет! Докажи свою преданность нашему делу. Рискни своей жизнью ради победы над Плетью, а Серебряный Рассвет и Алый Марш прикроют тебя со спины.$b$bСтупай в Наксрамас и уничтожь воинство Плети...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Командир Элигор Вестник Рассвета из Часовни Последней Надежды, что в Восточных Чумных землях просит убить 5 ходячих ужасов, 5 каменных горгулий, 8 капитанов рыцарей Смерти и 3 ядовитых пауков-скакунов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличая работа!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Долг, честь, преданность... Что для тебя значат эти слова?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Элигору Вестнику Рассвета в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9034,'Кираса неустрашимости','Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.','Корфакс из Часовни Последней Надежды, что в Восточных Чумных землях, готов сделать кирасу неустрашимости, если вы принесете ему следующее: 1 испоганенную кирасу, 25 обломков доспехов, 4 слитка арканита и 2 кристалла-источника.','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя кирасу неустрашимости.','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кираса неустрашимости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Корфакс из Часовни Последней Надежды, что в Восточных Чумных землях, готов сделать кирасу неустрашимости, если вы принесете ему следующее: 1 испоганенную кирасу, 25 обломков доспехов, 4 слитка арканита и 2 кристалла-источника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя кирасу неустрашимости.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (9035,'Засада на дороге','Эй! Помоги, пожалуйста!$b$bНа нас с товарищем напали Презренные! Они так алчут магии, что забрали буквально все, что нашли: и кристаллы маны, и жезлы, и книги заклинаний... ну, то есть все!$b$bМеледор погнался за ними, а мне пришлось остаться, чтобы приглядывать за тем, что они не сумели отнять. Догони его, посмотри, вдруг ты сумеешь ему помочь...','Все, сбежали. Видно, не понравился им мой огненный шар! Но вот вещи наши они побросали в реку...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засада на дороге',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй! Помоги, пожалуйста!$b$bНа нас с товарищем напали Презренные! Они так алчут магии, что забрали буквально все, что нашли: и кристаллы маны, и жезлы, и книги заклинаний... ну, то есть все!$b$bМеледор погнался за ними, а мне пришлось остаться, чтобы приглядывать за тем, что они не сумели отнять. Догони его, посмотри, вдруг ты сумеешь ему помочь...',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все, сбежали. Видно, не понравился им мой огненный шар! Но вот вещи наши они побросали в реку...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9036,'Ножные латы неустрашимости','Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.','Корфакс из Часовни Последней Надежды, что в Восточных Чумных землях, готов сделать ножные латы неустрашимости, если вы принесете ему следующее: 1 испоганенные ножные латы, 20 обломков доспехов, 4 слитка арканита и 3 обработанных грубых шкуры.','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя латы неустрашимости.','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ножные латы неустрашимости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты ведь отправляешься на войну с Плетью в Наксрамас? Если тебе попадутся испоганенные доспехи и обломки доспехов, принеси их мне, я сделаю тебе броню, достойную величайших героев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Корфакс из Часовни Последней Надежды, что в Восточных Чумных землях, готов сделать ножные латы неустрашимости, если вы принесете ему следующее: 1 испоганенные ножные латы, 20 обломков доспехов, 4 слитка арканита и 3 обработанных грубых шкуры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя латы неустрашимости.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.',`completedtext_loc8`);
