INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9051,'Испытание яда','Яд, который ты $gпомог:помогла; мне создать, нужен мне для особых целей. Огромные дьявозавры, обитающие в кратере, мешают мне охотиться и даже угрожают моей жизни. Даже если бы у меня хватило сил, чтобы убить дьявозавра, это было бы бесполезно – на место убитого немедленно придет другой. $b$bВозьми эту отравленную колючку и загони ее глубоко в шкуру дьявозавра. Яд усмирит зверя, хоть я и не знаю, насколько быстро...','Уколите дьявозавра колючкой дьявозавра. По выполнении задания вернитесь к Землепроходцу Торве.','Спасибо, $N. Ты $Gхрабрый:хитрая; и $Gмудрый:мудрая;. $B$BСкажи мне, как отреагировал дьявозавр на введенный тобой токсин?','Удалось ли вам усмирить великого зверя?','Дьявозавр уколот колючкой.','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание яда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Яд, который ты $gпомог:помогла; мне создать, нужен мне для особых целей. Огромные дьявозавры, обитающие в кратере, мешают мне охотиться и даже угрожают моей жизни. Даже если бы у меня хватило сил, чтобы убить дьявозавра, это было бы бесполезно – на место убитого немедленно придет другой. $b$bВозьми эту отравленную колючку и загони ее глубоко в шкуру дьявозавра. Яд усмирит зверя, хоть я и не знаю, насколько быстро...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уколите дьявозавра колючкой дьявозавра. По выполнении задания вернитесь к Землепроходцу Торве.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N. Ты $Gхрабрый:хитрая; и $Gмудрый:мудрая;. $B$BСкажи мне, как отреагировал дьявозавр на введенный тобой токсин?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли вам усмирить великого зверя?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Дьявозавр уколот колючкой.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9052,'Яд кровоцвета','Мне нужна твоя помощь в создании яда, с помощью которого я собираюсь усмирять огромных чудовищ, обитающих в кратере. Не бойся, яд не смертелен. Кроме того, острые глаза |3-1($c) будут большим подспорьем при сборе ингредиентов. $b$bГрибы-кровошляпочники растут под ростками кровоцвета – их в кратере полным полно. Жала Гориши можно собрать с насекомых, которые водятся в районе Скользкого оврага в южной части кратера.','Соберите 8 кровошляпочников и 8 жал Гориши и вернитесь к Землепроходцу Торве в Кратер Ун\'Горо.','Ингредиенты, наконец-то!$B$BТеперь будет не сложно создать яд...','Добились ли вы успеха?','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яд кровоцвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужна твоя помощь в создании яда, с помощью которого я собираюсь усмирять огромных чудовищ, обитающих в кратере. Не бойся, яд не смертелен. Кроме того, острые глаза |3-1($c) будут большим подспорьем при сборе ингредиентов. $b$bГрибы-кровошляпочники растут под ростками кровоцвета – их в кратере полным полно. Жала Гориши можно собрать с насекомых, которые водятся в районе Скользкого оврага в южной части кратера.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 кровошляпочников и 8 жал Гориши и вернитесь к Землепроходцу Торве в Кратер Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ингредиенты, наконец-то!$B$BТеперь будет не сложно создать яд...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добились ли вы успеха?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9053,'Лучший ингредиент','Как я и опасался – яд слишком слаб для такого большого зверя. $b$bЧтобы создать более мощный яд, мне потребуются лучшие ингредиенты. Отправляйся на дно Храма Атал\'Хаккара, раскрой секреты алтаря и заполучи от тамошнего стража гнилую лозу. Храм опасен, поэтому не ходи $gодин:одна;. $b$bВозвращайся ко мне, когда закончишь задание.','Возьмите гнилую лозу у стража на дне затонувшего храма и вернитесь к Землепроходцу Торве.','Наконец-то, теперь яд может быть полностью создан. $B$BПрими мою благодарность и уважение. Желаю тебе удачи в твоих путешествиях, $N.','Вы восстановили виноградную лозу?','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучший ингредиент',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как я и опасался – яд слишком слаб для такого большого зверя. $b$bЧтобы создать более мощный яд, мне потребуются лучшие ингредиенты. Отправляйся на дно Храма Атал\'Хаккара, раскрой секреты алтаря и заполучи от тамошнего стража гнилую лозу. Храм опасен, поэтому не ходи $gодин:одна;. $b$bВозвращайся ко мне, когда закончишь задание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите гнилую лозу у стража на дне затонувшего храма и вернитесь к Землепроходцу Торве.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то, теперь яд может быть полностью создан. $B$BПрими мою благодарность и уважение. Желаю тебе удачи в твоих путешествиях, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы восстановили виноградную лозу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепроходцу Торве в Топи, что в Кратере Ун\'Горо.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9054,'Мундир расхитителя гробниц','Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.$b$bПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!','Охотник Леопольд из Часовни Последней Надежды в Восточных Чумных землях готов создать мундир расхитителя гробниц, если вы принесете ему следующее: 1 испоганенный мундир, 25 обрывков кольчуги, 4 слитка арканита и 3 обработанных грубых шкур.','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя мундир Расхитителя гробниц.','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!','Вернитесь к охотнику Леопольду в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мундир расхитителя гробниц',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я придумал, как лучше использовать панцири некрорахнидов. Если укрепить с их помощью испоганенные магические доспехи, которых хватает в Наксрамасе, выйдет броня невиданной прочности.$b$bПринеси мне все необходимое, и я создам для тебя лучшие на свете доспехи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Охотник Леопольд из Часовни Последней Надежды в Восточных Чумных землях готов создать мундир расхитителя гробниц, если вы принесете ему следующее: 1 испоганенный мундир, 25 обрывков кольчуги, 4 слитка арканита и 3 обработанных грубых шкур.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя мундир Расхитителя гробниц.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику Леопольду в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
