,`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику Леопольду в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
