INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9062,'Промокшие страницы','Ой, она вся промокла! Что же делать? Инструктор Антеол этого не одобрит!$B$BСлушай, вот тебе деньги! И у меня есть идея...','Вернитесь к ученику Меледору в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Промокшие страницы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, она вся промокла! Что же делать? Инструктор Антеол этого не одобрит!$B$BСлушай, вот тебе деньги! И у меня есть идея...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Меледору в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9063,'Землепроходец Торва','Охотнику по имени Землепроходец Торва понадобилась помощь друида. Он сказал, что лишь у нас есть нужные навыки и должное уважение к природе.$b$bОт Кратера Ун\'Горо к пустыне Танарис ведет дорога. Торва стоит у самого входа в кратер.','Поговорите с Землепроходцем Торвой в Кратере Ун\'Горо.','Тебе пришлось долгое путешествие, чтобы встретиться со мной, $C.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Землепроходец Торва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Охотнику по имени Землепроходец Торва понадобилась помощь друида. Он сказал, что лишь у нас есть нужные навыки и должное уважение к природе.$b$bОт Кратера Ун\'Горо к пустыне Танарис ведет дорога. Торва стоит у самого входа в кратер.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Землепроходцем Торвой в Кратере Ун\'Горо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе пришлось долгое путешествие, чтобы встретиться со мной, $C.',`offerrewardtext_loc8`);
