INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9067,'Бесконечный праздник','А ты довольно таки $Gэнергичный:энергичная; и $Gмолодой:молодая;, не так ли?$B$BДа, это именно те припасы, что мне нужны. За то, что $Gсобрал:собрала; все это для меня, ты безусловно заслуживаешь компенсации, и я думаю, кое что дополнительно. $B$BО, я чуть не забыл, вот приглашение на вечеринку. И, $C, в следующий раз, когда попадешь на праздник, убедись что ты $Gодет:одета; немного более... празднично.','Разве я не послал тебя за припасами для праздника? Или это $Gбыл:была; не ты? Ну, в конце концов, не могу же я помнить всех в лицо! У меня ведь столько интересных знакомых...$B$BТак чего тебе надо?','Вернитесь к лорду Салтерилу на виллу Салтерила, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесконечный праздник',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А ты довольно таки $Gэнергичный:энергичная; и $Gмолодой:молодая;, не так ли?$B$BДа, это именно те припасы, что мне нужны. За то, что $Gсобрал:собрала; все это для меня, ты безусловно заслуживаешь компенсации, и я думаю, кое что дополнительно. $B$BО, я чуть не забыл, вот приглашение на вечеринку. И, $C, в следующий раз, когда попадешь на праздник, убедись что ты $Gодет:одета; немного более... празднично.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разве я не послал тебя за припасами для праздника? Или это $Gбыл:была; не ты? Ну, в конце концов, не могу же я помнить всех в лицо! У меня ведь столько интересных знакомых...$B$BТак чего тебе надо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Салтерилу на виллу Салтерила, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9068,'Мундир Землекрушителя','Прошу тебя, окажи мне честь и верни броню тех, кто пал, защищая эти земли.$b$bЗлые силы несомненно испоганили эти доспехи и используют их для собственных гнусных целей, однако их можно укрепить при помощи обрывков кольчуг и вновь пойти в них на войну.$b$bПринеси мне остатки брони павших и материалы для их очищения, и получишь взамен доспехи Землекрушителя.$b$bСтупай, поищи в Наксрамасе.','Римблат Землекрушитель из Часовни Последней Надежды в Восточных Чумных землях готов создать мундир Землекрушителя, если вы принесете ему следующее: 1 испоганенный мундир, 25 обрывков кольчуги, 4 слитка арканита и 3 обработанных грубых шкуры.','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя мундир Землекрушителя.','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!','Вернитесь к Римблату Землекрушитю в Восточную башню, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мундир Землекрушителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошу тебя, окажи мне честь и верни броню тех, кто пал, защищая эти земли.$b$bЗлые силы несомненно испоганили эти доспехи и используют их для собственных гнусных целей, однако их можно укрепить при помощи обрывков кольчуг и вновь пойти в них на войну.$b$bПринеси мне остатки брони павших и материалы для их очищения, и получишь взамен доспехи Землекрушителя.$b$bСтупай, поищи в Наксрамасе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Римблат Землекрушитель из Часовни Последней Надежды в Восточных Чумных землях готов создать мундир Землекрушителя, если вы принесете ему следующее: 1 испоганенный мундир, 25 обрывков кольчуги, 4 слитка арканита и 3 обработанных грубых шкуры.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя мундир Землекрушителя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Римблату Землекрушитю в Восточную башню, что в Восточных Чумных землях.',`completedtext_loc8`);
