INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9076,'Главарь Презренных','Ага, тебе все-таки удалось его одолеть! Ну, конечно, вряд ли бы ты его $Gпоймал:поймала;, если бы мои воины его не загнали…$B$BДа шучу я, шучу! Спасибо, |3-6($C). Ты еще завоюешь себе славу.','Ну что, тебе удалось добыть его голову или нет? У меня нет лишнего времени, $N!','Вернитесь к Велендрису Белому Рассвету в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главарь Презренных',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ага, тебе все-таки удалось его одолеть! Ну, конечно, вряд ли бы ты его $Gпоймал:поймала;, если бы мои воины его не загнали…$B$BДа шучу я, шучу! Спасибо, |3-6($C). Ты еще завоюешь себе славу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, тебе удалось добыть его голову или нет? У меня нет лишнего времени, $N!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Велендрису Белому Рассвету в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9077,'Кираса костяной косы','Если ты хочешь броню костяной косы, принеси мне все материалы.$b$bСтупай в Наксрамас, огромный парящий город смерти, и набери там испоганенных доспехов и обрывков кольчуг. Принеси их мне вместе с остальными материалами, и, считай, Костяная коса – твоя. Ах да, не забудь и мне отстегнуть за работу... Кости я тебе обеспечу.','Рохан Убийца из Часовни Последней Надежды в Восточных Чумных землях готов создать кирасу костяной косы, если вы принесете ему следующее: 1 испоганенную кирасу, 25 обрывков кожи, 2 слитка арканита и 6 обработанных грубых шкур.','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя кирасу костяной косы.','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!','Вернитесь к Рохану Убийце в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кираса костяной косы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты хочешь броню костяной косы, принеси мне все материалы.$b$bСтупай в Наксрамас, огромный парящий город смерти, и набери там испоганенных доспехов и обрывков кольчуг. Принеси их мне вместе с остальными материалами, и, считай, Костяная коса – твоя. Ах да, не забудь и мне отстегнуть за работу... Кости я тебе обеспечу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Рохан Убийца из Часовни Последней Надежды в Восточных Чумных землях готов создать кирасу костяной косы, если вы принесете ему следующее: 1 испоганенную кирасу, 25 обрывков кожи, 2 слитка арканита и 6 обработанных грубых шкур.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя кирасу костяной косы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рохану Убийце в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
