INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9085,'Тени Рока','После разрушения защиты кругов призыва Плети, которые появляются в тех местах, где происходит нападение, тебе придется сразиться с послушниками, которые охраняют эти круги.$b$bЧестно говоря, это не живые существа, а тени, одни из самых устрашающих созданий Короля-лича. Их можно обнаружить с помощью некротических рун, которые они носят при себе, а затем уничтожить посредством магии или силой оружия.','Ну, как, тебе улыбнулась удача, $N?','Удача на твоей стороне, $N?','Вернитесь к командиру Томасу Элерану в Восточную башню, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тени Рока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После разрушения защиты кругов призыва Плети, которые появляются в тех местах, где происходит нападение, тебе придется сразиться с послушниками, которые охраняют эти круги.$b$bЧестно говоря, это не живые существа, а тени, одни из самых устрашающих созданий Короля-лича. Их можно обнаружить с помощью некротических рун, которые они носят при себе, а затем уничтожить посредством магии или силой оружия.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, как, тебе улыбнулась удача, $N?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удача на твоей стороне, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Томасу Элерану в Восточную башню, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9086,'Мундир сновидца','В последней войне пало немало героев, да и сегодня все больше славных бойцов погибает под натиском Плети. С тел погибших срывают доспехи, уносят в Наксрамас и используют для неведомых, но несомненно гнусных, целей.$b$bВерни испоганенные доспехи и их обрывки, принеси все остальные материалы, и я сделаю для тебя броню сновидца.','Райн из Часовни Последней Надежды в Восточных Чумных землях готова создать мундир сновидца, если вы принесете ей следующее: 1 испоганенный мундир, 25 обрывков кожи, 6 обработанных грубых шкур и 2 кристалла-источника.','Твой мундир сновидца готов, $N.','Стоимость материала высока, но вскоре о ней забывают.','Вернитесь к Райн в Восточную башню, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мундир сновидца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В последней войне пало немало героев, да и сегодня все больше славных бойцов погибает под натиском Плети. С тел погибших срывают доспехи, уносят в Наксрамас и используют для неведомых, но несомненно гнусных, целей.$b$bВерни испоганенные доспехи и их обрывки, принеси все остальные материалы, и я сделаю для тебя броню сновидца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Райн из Часовни Последней Надежды в Восточных Чумных землях готова создать мундир сновидца, если вы принесете ей следующее: 1 испоганенный мундир, 25 обрывков кожи, 6 обработанных грубых шкур и 2 кристалла-источника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твой мундир сновидца готов, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Стоимость материала высока, но вскоре о ней 