INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9095,'Одеяние ледяного огня','У меня был доступ ко многим личным вещам Медива. Меня больше всего интересовали манускрипты. Хотя в основном книги были, прямо скажем, полной чепухой, но и в этой мусорной кучи были свои изумруды. В одном из манускриптов описывалось создание брони, достойной верховного мага, брони ледяного огня.$b$b<Анжела указывает на собственную голову.>$b$bВсе знания теперь хранятся там, и я с радостью поделюсь ими с тобой, если ты снабдишь меня необходимыми материалами.','Верховный маг Анжела Досантос из Часовни Последней Надежды в Восточных Чумных землях готова создать одеяние ледяного огня, если вы принесете ей следующее: 1 испоганенное одеяние, 25 обрывков ткани, 4 куска луноткани и 2 кристалла-источника.','Отлично $N! У тебя всё то, что мне нужно и теперь я сделаю для тебя одеяние ледяного огня.','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!','Вернитесь к верховному магу Анжеле Досантос в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одеяние ледяного огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня был доступ ко многим личным вещам Медива. Меня больше всего интересовали манускрипты. Хотя в основном книги были, прямо скажем, полной чепухой, но и в этой мусорной кучи были свои изумруды. В одном из манускриптов описывалось создание брони, достойной верховного мага, брони ледяного огня.$b$b<Анжела указывает на собственную голову.>$b$bВсе знания теперь хранятся там, и я с радостью поделюсь ими с тобой, если ты снабдишь меня необходимыми материалами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный маг Анжела Досантос из Часовни Последней Надежды в Восточных Чумных землях готова