INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9103,'Одеяние Проклятого Сердца','Не буду тебе лгать, $gслизняк:тля;. Тьма облачения Проклятого Сердца может поглотить нас обоих, потому я и назначил такую высокую цену. Если уж умирать, то по крайней мере, на груде золота.$b$bМне наплевать, как сдохнешь ты, главное делай, как я скажу. Принесешь все, что велено – оба нагреем руки. Ну, или умрем; впрочем, я начинаю повторяться...','Матеус Обрушивающий Гнев из Часовни Последней Надежды готов создать одеяние Проклятого Сердца, если вы принесете ему следующее: 1 испоганенное одеяние, 25 обрывков ткани, 4 куска луноткани и 2 кристалла-источника.','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя одеяние Проклятого Сердца.','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!','Вернитесь к Матеусу Обрушивающему Гнев в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одеяние Проклятого Сердца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не буду тебе лгать, $gслизняк:тля;. Тьма облачения Проклятого Сердца может поглотить нас обоих, потому я и назначил такую высокую цену. Если уж умирать, то по крайней мере, на груде золота.$b$bМне наплевать, как сдохнешь ты, главное делай, как я скажу. Принесешь все, что велено – оба нагреем руки. Ну, или умрем; впрочем, я начинаю повторяться...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Матеус Обрушивающий Гнев из Часовни Последней Надежды готов создать одеяние Проклятого Сердца, если вы принесете ему следующее: 1 испоганенное одеяние, 25 обрывков ткани, 4 куска луноткани и 2 кристалла-источника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! У т