INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9111,'Одеяние веры','*Отец Монтой делает какие-то странные пассы.*$b$bБлагослови тебя Свет, дитя мое, удалось ли тебе отыскать одежды павших? Бедные воины, лишившиеся жизни на поле битвы – у них отняли все, даже достоинство.$b$bПринеси мне оскверненные доспехи павших и все реагенты для их очищения, и ты познаешь, что такое истинная вера.','Отец Иниго Монтой из Часовни Последней Надежды готов создать одеяние Веры, если вы принесете ему следующее: 1 испоганенное одеяние, 25 обрывков ткани, поврежденных в бою, 4 куска луноткани и 2 кристалла-источника.','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя одеяние Веры.','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!','Вернитесь к отцу Иниго Монтою в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одеяние веры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Отец Монтой делает какие-то странные пассы.*$b$bБлагослови тебя Свет, дитя мое, удалось ли тебе отыскать одежды павших? Бедные воины, лишившиеся жизни на поле битвы – у них отняли все, даже достоинство.$b$bПринеси мне оскверненные доспехи павших и все реагенты для их очищения, и ты познаешь, что такое истинная вера.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отец Иниго Монтой из Часовни Последней Надежды готов создать одеяние Веры, если вы принесете ему следующее: 1 испоганенное одеяние, 25 обрывков ткани, поврежденных в бою, 4 куска луноткани и 2 кристалла-источника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя одеяние Веры.',`offerrewardtext_loc8`), `requestitems