t_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к отцу Иниго Монтою в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9118,'Наручники веры','*Отец Монтой делает какие-то странные пассы.*$b$bБлагослови тебя Свет, дитя мое, удалось ли тебе отыскать одежды павших? Бедные воины, лишившиеся жизни на поле битвы – у них отняли все, даже достоинство.$b$bПринеси мне оскверненные доспехи павших и все реагенты для их очищения, и ты познаешь, что такое истинная вера.','Отец Иниго Монтой из Часовни Последней Надежды готов создать наручники Веры, если вы принесете ему следующее: 1 испоганенные наручники, 6 обрывков ткани, поврежденных в бою, 1 кристалл-источник и 1 чародейский кристалл.','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя наручи Веры.','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!','Вернитесь к отцу Иниго Монтою в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наручники веры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Отец Монтой делает какие-то странные пассы.*$b$bБлагослови тебя Свет, дитя мое, удалось ли тебе отыскать одежды павших? Бедные воины, лишившиеся жизни на поле битвы – у них отняли все, даже достоинство.$b$bПринеси мне оскверненные доспехи павших и все реагенты для их очищения, и ты познаешь, что такое истинная вера.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отец Иниго Монтой из Часовни Последней Надежды готов создать наручники Веры, если вы принесете ему следующее: 1 испоганенные наручники, 6 обрывков ткани, поврежденных в бою, 1 кристалл-источник и 1 чародейский кристалл.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N! У тебя все то, что мне нужно и теперь я сделаю для тебя наручи Веры.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас есть недостающие детали для задания, пожалуйста, идите и получите их все!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к отцу Иниго Монтою в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9119,'Авария в Западном святилище','Оглядись вокруг. Нельзя сказать, что все в порядке!$B$BВ Западном святилище произошла серьезная авария. Нужно сделать все, чтобы ситуация не ухудшилась!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Авария в Западном святилище',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Оглядись вокруг. Нельзя сказать, что все в порядке!$B$BВ Западном святилище произошла серьезная авария. Нужно сделать все, чтобы ситуация не ухудшилась!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9120,'Падение Кел\'Тузада','От повелителя Наксрамаса остался лишь этот талисман. Голос рассудка подсказывает, что следует уничтожить его, дабы Король Мертвых не смог более возродиться. К счастью, вы не привыкли слушаться внутреннего голоса.$b$bКое-кто из часовни Последней Надежды обещал недурно заплатить за этот талисман. Кому есть дело до возрождения Кел\'Тузада?','Отнесите талисман Кел\'Тузада в Часовню Последней Надежды в Восточных Чумных землях.','За все дни моей жизни никогда не ожидал увидеть это... $B$B<Похоже, у отца Монтой течет слюна.>$B$BАх да, ты будешь $Gвознагражден:вознаграждена;. Дай сюда. Сейчас же!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Кел\'Тузада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От повелителя Наксрамаса остался лишь этот талисман. Голос рассудка подсказывает, что следует уничтожить его, дабы Король Мертвых не смог более возродиться. К счастью, вы не привыкли слушаться внутреннего голоса.$b$bКое-кто из часовни Последней Надежды обещал недурно заплатить за этот талисман. Кому есть дело до возрождения Кел\'Тузада?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите талисман Кел\'Тузада в Часовню Последней Надежды в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','За все дни моей жизни никогда не ожидал увидеть это... $B$B<Похоже, у отца Монтой течет слюна.>$B$BАх да, ты будешь $Gвознагражден:вознаграждена;. Дай сюда. Сейчас же!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9121,'Цитадель ужаса – Наксрамас','В чаще Чумного леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.$b$bМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку тебе не хватает преданности делу Серебряного Рассвета, за чары придется немало заплатить. Ты можешь отказаться от задания и вернуться ко мне, как только тебя начнут почитать или превозносить. Тогда я сделаю тебе скидку.','Верховный маг Анжела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова наложить на вас заклинание чародейского покрова за 5 чародейских кристаллов, 2 кристалла-источника, 1 сферу Праведности и 60 золотых. Вы должны заслужить уважительное отношение Серебряного Рассвета.','Ты почувствуешь легкое покалывание, $N. Это ощущение означает, что все сработало. После окончания, ты сможешь зайти в Наксрамас, ступив на руны портала в чаще Чумного леса.','Ещё никому не удалось выйти живым из Наксрамаса, чтобы рассказать эту историю.','Вернитесь к верховному магу Анжеле Досантос в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цитадель ужаса – Наксрамас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В чаще Чумного леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.$b$bМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку тебе не хватает преданности делу Серебряного Рассвета, за чары придется немало заплатить. Ты можешь отказаться от задания и вернуться ко мне, как только тебя начнут почитать или превозносить. Тогда я сделаю тебе скидку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный маг Анжела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова наложить на вас заклинание чародейского покрова за 5 чародейских кристаллов, 2 кристалла-источника, 1 сферу Праведности и 60 золотых. Вы должны заслужить уважительное отношение Серебряного Рассвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты почувствуешь легкое покалывание, $N. Это ощущение означает, что все сработало. После окончания, ты сможешь зайти в Наксрамас, ступив на руны портала в чаще Чумного леса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ещё никому не удалось выйти живым из Наксрамаса, чтобы рассказать эту историю.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Анжеле Досантос в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9122,'Цитадель ужаса – Наксрамас','В чаще Чумного леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.$b$bМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку ты весьма $gпредан:предана; делу Серебряного Рассвета, часть издержек мы возьмем на себя.','Верховный маг Анжела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова наложить на вас заклинание чародейского покрова за 2 чародейских кристалла, 1 кристалл-источник и 30 золотых. Вы должны заслужить почтительное отношение Серебряного Рассвета.','Ты почувствуешь легкое покалывание, $N. Это ощущение означает, что все сработало. После окончания, ты сможешь зайти в Наксрамас, ступив на руны портала в чаще Чумного леса.','Ещё никому не удалось выйти живым из Наксрамаса, чтобы рассказать эту историю.','Вернитесь к верховному магу Анжеле Досантос в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цитадель ужаса – Наксрамас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В чаще Чумного леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.$b$bМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку ты весьма $gпредан:предана; делу Серебряного Рассвета, часть издержек мы возьмем на себя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный маг Анжела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова наложить на вас заклинание чародейского покрова за 2 чародейских кристалла, 1 кристалл-источник и 30 золотых. Вы должны заслужить почтительное отношение Серебряного Рассвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты почувствуешь легкое покалывание, $N. Это ощущение означает, что все сработало. После окончания, ты сможешь зайти в Наксрамас, ступив на руны портала в чаще Чумного леса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ещё никому не удалось выйти живым из Наксрамаса, чтобы рассказать эту историю.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Анжеле Досантос в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9123,'Цитадель ужаса – Наксрамас','В чаще Чумного леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.$b$bМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку твоя преданность делу Серебряного Рассвета не подлежит сомнению, мы возьмем на себя все издержки.','Верховный маг Анжела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова бесплатно наложить на вас заклинание чародейского покрова. Сначала добейтесь того, чтобы вас превозносили в Серебряном Рассвете.','Ты почувствуешь легкое покалывание, $N. Это ощущение означает, что все сработало. После окончания, ты сможешь зайти в Наксрамас, ступив на руны портала в чаще Чумного леса.','Ещё никому не удалось выйти живым из Наксрамаса, чтобы рассказать эту историю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цитадель ужаса – Наксрамас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В чаще Чумного леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.$b$bМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку твоя преданность делу Серебряного Рассвета не подлежит сомнению, мы возьмем на себя все издержки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный маг Анжела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова бесплатно наложить на вас заклинание чародейского покрова. Сначала добейтесь того, чтобы вас превозносили в Серебряном Рассвете.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты почувствуешь легкое покалывание, $N. Это ощущение означает, что все сработало. После окончания, ты сможешь зайти в Наксрамас, ступив на руны портала в чаще Чумного леса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ещё никому не удалось выйти живым из Наксрамаса, чтобы рассказать эту историю.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9124,'Доспехи расхитителя гробниц на дороге не валяются...','Хочешь получить такую побрякушку?$B$B*Леопольд помахивает значком Алого ордена.*$B$BМне пригодилась бы твоя помощь в одном деле, $n. Я создаю броню расхитителей гробниц для глупцов, желающих сунуть нос в Наксрамас. У меня нет недостатка в материалах, за исключением конечностей и панцирей некрорахнидов. Принеси мне их, и получишь значок. Имей в виду, интенданты готовы отдать за эти побрякушки много интересного.','Принесите 30 конечностей и панцирей некрорахнидов Охотнику Леопольду в Часовню Последней Надежды в Восточные Чумные земли.','Как охота?','Вернитесь к охотнику Леопольду в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доспехи расхитителя гробниц на дороге не валяются...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь получить такую побрякушку?$B$B*Леопольд помахивает значком Алого ордена.*$B$BМне пригодилась бы твоя помощь в одном деле, $n. Я создаю броню расхитителей гробниц для глупцов, желающих сунуть нос в Наксрамас. У меня нет недостатка в материалах, за исключением конечностей и панцирей некрорахнидов. Принеси мне их, и получишь значок. Имей в виду, интенданты готовы отдать за эти побрякушки много интересного.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 30 конечностей и панцирей некрорахнидов Охотнику Леопольду в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как охота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику Леопольду в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9125,'Конечности и панцири некрорахнидов','Вернитесь к охотнику Леопольду в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конечности и панцири некрорахнидов',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнику Леопольду в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9126,'Копи костяной косы','Для изготовления доспехов костяной косы, изобретенных доном Хулио, требуются обломки костей – чем больше, тем лучше. Хотя безумцы, регулярно отправляющиеся в Наксрамас, приносят мне довольно много, обломки костей Плети для меня никогда не лишние.$B$BНе желаешь ли помочь мне? Так ты изничтожишь подлых тварей плети и снабдишь меня материалом для доспехов.','Принесите 30 обломков костей Рохану Убийце в Часовню Последней Надежды в Восточные Чумные земли.','Я могу указать тебе путь к зараженным местам, $C).','Вернитесь к Рохану Убийце в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Копи костяной косы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для изготовления доспехов костяной косы, изобретенных доном Хулио, требуются обломки костей – чем больше, тем лучше. Хотя безумцы, регулярно отправляющиеся в Наксрамас, приносят мне довольно много, обломки костей Плети для меня никогда не лишние.$B$BНе желаешь ли помочь мне? Так ты изничтожишь подлых тварей плети и снабдишь меня материалом для доспехов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 30 обломков костей Рохану Убийце в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я могу указать тебе путь к зараженным местам, $C).',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рохану Убийце в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9127,'Обломки костей','Вернитесь к Рохану Убийце в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обломки костей',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рохану Убийце в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9128,'Уравнение стихий','Приветствую тебя, $gстранник:странница;! Не ищешь ли ты работу? Плачу знаками отличия – их можно обменять на разные магические предметы у интендантов.$B$BСлушай, что мне нужно: принеси мне как можно больше средоточий стихий – сколько сможешь унести. Чем больше, тем лучше!$B$BСредоточия стихий можно найти у элементалей всех форм и размеров.','Принесите 30 средоточий стихий верховному магу Анжеле Досантос в Часовню Последней Надежды в Восточные Чумные земли.','Вернитесь к верховному магу Анжеле Досантос в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уравнение стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $gстранник:странница;! Не ищешь ли ты работу? Плачу знаками отличия – их можно обменять на разные магические предметы у интендантов.$B$BСлушай, что мне нужно: принеси мне как можно больше средоточий стихий – сколько сможешь унести. Чем больше, тем лучше!$B$BСредоточия стихий можно найти у элементалей всех форм и размеров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 30 средоточий стихий верховному магу Анжеле Досантос в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Анжеле Досантос в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9129,'Средоточие стихий','Вернитесь к верховному магу Анжеле Досантос в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Средоточие стихий',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Анжеле Досантос в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9130,'Товары из Луносвета','Привет новобранцам! У нас тут плохо со снабжением, но в Луносвете нам обещали материальную помощь. Это и будет твоим первым заданием.$B$BБери этот список и неси повелителю небес Ясному Рассвету. Он снабдит тебя дальнейшими инструкциями, как добраться до Луносвета.','Доставьте список Сатиэль повелителю небес Ясному Рассвету в деревню Легкий Ветерок.','Да, что тут у тебя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Товары из Луносвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет новобранцам! У нас тут плохо со снабжением, но в Луносвете нам обещали материальную помощь. Это и будет твоим первым заданием.$B$BБери этот список и неси повелителю небес Ясному Рассвету. Он снабдит тебя дальнейшими инструкциями, как добраться до Луносвета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте список Сатиэль повелителю небес Ясному Рассвету в деревню Легкий Ветерок.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, что тут у тебя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9131,'Броня неустрашимости','Ты когда-нибудь $gвидел:видела; доспехи неустрашимости, |3-6($c)? Конечно нет, ты же еще совсем салага. Так вот, послушай знатока – он великолепен!$B$BТы, наверное, недоумеваешь, какое это к тебе может иметь отношение? Вот что, недотепа, мне нужны пластины черного железа – как можно больше.$B$BС их помощью я скрепляю части доспехов неустрашимости для наших славных воинов. Так что я хорошо заплачу.','Принесите 30 пластин черного железа Корфаксу в Часовню Последней Надежды в Восточных Чумных землях.','Маловато, но пока сойдет. Найдешь еще – приноси.','Корфакс злобно смотрит на вас\n\nНу что тебе еще надо? Указать дорогу?','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Броня неустрашимости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты когда-нибудь $gвидел:видела; доспехи неустрашимости, |3-6($c)? Конечно нет, ты же еще совсем салага. Так вот, послушай знатока – он великолепен!$B$BТы, наверное, недоумеваешь, какое это к тебе может иметь отношение? Вот что, недотепа, мне нужны пластины черного железа – как можно больше.$B$BС их помощью я скрепляю части доспехов неустрашимости для наших славных воинов. Так что я хорошо заплачу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 30 пластин черного железа Корфаксу в Часовню Последней Надежды в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Маловато, но пока сойдет. Найдешь еще – приноси.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Корфакс злобно смотрит на вас\n\nНу что тебе еще надо? Указать дорогу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9132,'Лом черного железа','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лом черного железа',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9133,'Полет в Луносвет') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полет в Луносвет',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (9134,'Повелительница небес Полудымка','О, с виду – увесистый ящик! Ты хочешь погрузить его на одну из моих крылатых красоток?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелительница небес Полудымка',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, с виду – увесистый ящик! Ты хочешь погрузить его на одну из моих крылатых красоток?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (9135,'Возвращение к Сатиэль','$C, ты так скоро вернулась? Это те товары, за которыми я тебя посылала? Не похоже, чтобы тут было все, что я запрашивала!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Сатиэль',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$C, ты так скоро вернулась? Это те товары, за которыми я тебя посылала? Не похоже, чтобы тут было все, что я запрашивала!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9136,'Дикая флора','Я изготавливаю особые доспехи для наших бравых солдат, входящих в Наксрамас – они называются доспехами сновидца. Обычно у меня нет недостатка в материалах, за исключением диких ростков.$B$BВозможно, ты подумаешь, что эта работа не серьезна, однако без диких ростков создание таких доспехов невозможно.$B$BИ я готова платить за эту работу знаками Рассвета или Марша!','Принесите 30 диких ростков Райн в Часовню Последней Надежды в Восточные Чумные земли.','Я прекрасно разбираюсь в флоре нашего мира. Тебе нужен совет?','Вернитесь к Райн в Восточную башню, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикая флора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я изготавливаю особые доспехи для наших бравых солдат, входящих в Наксрамас – они называются доспехами сновидца. Обычно у меня нет недостатка в материалах, за исключением диких ростков.$B$BВозможно, ты подумаешь, что эта работа не серьезна, однако без диких ростков создание таких доспехов невозможно.$B$BИ я готова платить за эту работу знаками Рассвета или Марша!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 30 диких ростков Райн в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я прекрасно разбираюсь в флоре нашего мира. Тебе нужен совет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Райн в Восточную башню, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9137,'Дикие ростки','Вернитесь к Райн в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикие ростки',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Райн в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9138,'Деревня Солнечной Короны','С твоей помощью мы справимся с проблемой Плети, $C. С Дар\'Кханом разберутся!$B$BТы уже $Gсправился:справилась; с нерубской проблемой в Деревне Солнечной Короны?','Вернитесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Солнечной Короны',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С твоей помощью мы справимся с проблемой Плети, $C. С Дар\'Кханом разберутся!$B$BТы уже $Gсправился:справилась; с нерубской проблемой в Деревне Солнечной Короны?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9139,'Деревня Золотистой Дымки','Как только верну себе остаток припасов, смогу заняться делом. Войскам не уйти далеко, если они не смогут покупать то, что им нужно.\n\nЗона боевых действий – место прибыльное, не так ли, |3-6($C)? Ну да ладно, удалось ли тебе пробиться к моей повозке через полчища этих вурдалаков?','Вернитесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Золотистой Дымки',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как только верну себе остаток припасов, смогу заняться делом. Войскам не уйти далеко, если они не смогут покупать то, что им нужно.\n\nЗона боевых действий – место прибыльное, не так ли, |3-6($C)? Ну да ладно, удалось ли тебе пробиться к моей повозке через полчища этих вурдалаков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9140,'Деревня Ветрокрылых','$n, тебе пришло время вступить в главную битву за поселения Призрачных земель. Деревня Ветрокрылых к юго-западу отсюда захвачена крупным и сильным ударным отрядом – тенями и горгульями. Ты выступишь на острие нашей атаки и ослабишь противника насколько возможно!$B$BМагистры соседнего святилища Солнца на сей раз сделали специальный запрос: они хотят, чтобы останки этих тварей Плети были доставлены им для изучения, дабы найти метод борьбы с ними.$B$BДоброй охоты!','Ну, что, |3-6($C), деревня Ветрокрылых освобождена? Проклятые магистры из святилища Солнца уже просто плешь мне проели – не терпится им ручонками своими пощупать останки тех тварей Плети, что я просил тебя собрать.\n\nНо ты не переживай. Соберись и продолжай выполнять задание. А с магистрами я сам разберусь.','Вернитесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деревня Ветрокрылых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, тебе пришло время вступить в главную битву за поселения Призрачных земель. Деревня Ветрокрылых к юго-западу отсюда захвачена крупным и сильным ударным отрядом – тенями и горгульями. Ты выступишь на острие нашей атаки и ослабишь противника насколько возможно!$B$BМагистры соседнего святилища Солнца на сей раз сделали специальный запрос: они хотят, чтобы останки этих тварей Плети были доставлены им для изучения, дабы найти метод борьбы с ними.$B$BДоброй охоты!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что, |3-6($C), деревня Ветрокрылых освобождена? Проклятые магистры из святилища Солнца уже просто плешь мне проели – не терпится им ручонками своими пощупать останки тех тварей Плети, что я просил тебя собрать.\n\nНо ты не переживай. Соберись и продолжай выполнять задание. А с магистрами я сам разберусь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9141,'Не все так просто','Хочешь получить задание? Не все так просто. Неужели ты думаешь, что я буду раздавать задания всякому явившемуся пред мои очи оборванцу, когда меня осаждают толпы желающих работать на фронте!$B$BХочешь получить задание – докажи, что ты его $gдостоин:достойна;! Принеси мне знак доблести, тогда и поговорим.$B$BИмей в виду, единственный способ поступить к нам на работу – обагрить руки кровью!','Принесите знак доблести Серебряного Рассвета командиру Метцу в Часовню Последней Надежды в Восточные Чумные земли.','Хорошо, слушай порядок действий: за каждый предъявленный знак доблести будешь получать задание. Выполнять строго по инструкции и отчитываться караванщику Камнетесу. Вопросы есть? Прекрасно, теперь марш отсюда.','Командир-посланник Метц жует сигару\n\nВ чем дело? У меня нет времени!','Вернитесь к командиру Метцу в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не все так просто',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь получить задание? Не все так просто. Неужели ты думаешь, что я буду раздавать задания всякому явившемуся пред мои очи оборванцу, когда меня осаждают толпы желающих работать на фронте!$B$BХочешь получить задание – докажи, что ты его $gдостоин:достойна;! Принеси мне знак доблести, тогда и поговорим.$B$BИмей в виду, единственный способ поступить к нам на работу – обагрить руки кровью!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите знак доблести Серебряного Рассвета командиру Метцу в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, слушай порядок действий: за каждый предъявленный знак доблести будешь получать задание. Выполнять строго по инструкции и отчитываться караванщику Камнетесу. Вопросы есть? Прекрасно, теперь марш отсюда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Командир-посланник Метц жует сигару\n\nВ чем дело? У меня нет времени!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Метцу в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9142,'Задание мастера','Вернитесь к командиру Метцу в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание мастера',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Метцу в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9143,'Неприятности в Зеб\'Соре','Вернитесь к следопыту Валанне в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприятности в Зеб\'Соре',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к следопыту Валанне в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (9144,'Пропавший в Призрачных землях','Идите по дороге, ведущей из деревни Легкий Ветерок на юг, и найдите курьера Рассветного Странника.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший в Призрачных землях',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите по дороге, ведущей из деревни Легкий Ветерок на юг, и найдите курьера Рассветного Странника.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`) VALUES (9145,'Найдите следопыта Валанну и лейтенанта Томатрена на берегу озера Эрлендар в Призрачных землях близ деревни Солнечной Короны.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите следопыта Валанну и лейтенанта Томатрена на берегу озера Эрлендар в Призрачных землях близ деревни Солнечной Короны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (9146,'Донесение капитану Гелиосу','Ты уже совершила нападение на Зеб\'Нову?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение капитану Гелиосу',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже совершила нападение на Зеб\'Нову?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9147,'Умирающий курьер','Ну? Ты принесла то, что я просила? Поспеши, иначе этот прекрасный юный эльф умрет!','Вернитесь к аптекарю Тедре в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Умирающий курьер',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну? Ты принесла то, что я просила? Поспеши, иначе этот прекрасный юный эльф умрет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Тедре в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (9148,'Письмо при тебе?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Письмо при тебе?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9149,'Чумной берег','Чтобы найти лекарство от этой болезни, нам нужно понять, как она влияет на различные существа – от самых сложных форм жизни до простейших. $B$BЯ прибыл сюда для исследования мурлоков, поскольку они, как и мы, сохраняют свободу воли даже после смерти. Что делает этих ничтожных ублюдков такими особенными? Мне надо это выяснить, $n!$B$BОтправляйся на северо-запад и принеси мне их хребты, чтобы я мог изучить накопление заразы в их костном мозге. Кто знает, что за секрет хранят их жалкие кости?','Принесите 6 хребтов чумных мурлоков аптекарю Рензитену в Транквиллион, что в Призрачных землях.','Блестяще! Эти хребты как нельзя лучше годятся для моих исследований! Когда я найду лекарство от чумы и слух обо мне пойдет по городам и весям, тогда уж я не позабуду упомянуть о тебе!\n\nА пока вот тебе награда. Они могут тебе понадобиться, если решишь вернуться на побережье.','Вернитесь к аптекарю Рензитену в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чумной берег',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы найти лекарство от этой болезни, нам нужно понять, как она влияет на различные существа – от самых сложных форм жизни до простейших. $B$BЯ прибыл сюда для исследования мурлоков, поскольку они, как и мы, сохраняют свободу воли даже после смерти. Что делает этих ничтожных ублюдков такими особенными? Мне надо это выяснить, $n!$B$BОтправляйся на северо-запад и принеси мне их хребты, чтобы я мог изучить накопление заразы в их костном мозге. Кто знает, что за секрет хранят их жалкие кости?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 хребтов чумных мурлоков аптекарю Рензитену в Транквиллион, что в Призрачных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Блестяще! Эти хребты как нельзя лучше годятся для моих исследований! Когда я найду лекарство от чумы и слух обо мне пойдет по городам и весям, тогда уж я не позабуду упомянуть о тебе!\n\nА пока вот тебе награда. Они могут тебе понадобиться, если решишь вернуться на побережье.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Рензитену в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9150,'Спасение прошлого','Прямо не верится! На юго-востоке от нас существует и действует настоящее магическое святилище – святилище Солнца! Все самые знаменитые магистры собрались туда ради этого!$B$BИ, конечно, все позабыли о святилище Луны. От него мало что осталось, и его сила породила странных тварей. $B$BНо я не дам добру пропасть. Отправляйся в святилище Луны и посмотри, нельзя ли собрать с тамошних тварей немного кристаллизованной субстанции?','Магистр Даренис хочет, чтобы вы отправились в святилище Луны к западу от Транквиллиона и добыли 8 кристализованных субстанций маны с волшебных пожирателей и маначервей, что населяют это место.','Это очень мощная субстанция. Я весьма доволен твоей работой.','Вернитесь к магистру Даренису в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прямо не верится! На юго-востоке от нас существует и действует настоящее магическое святилище – святилище Солнца! Все самые знаменитые магистры собрались туда ради этого!$B$BИ, конечно, все позабыли о святилище Луны. От него мало что осталось, и его сила породила странных тварей. $B$BНо я не дам добру пропасть. Отправляйся в святилище Луны и посмотри, нельзя ли собрать с тамошних тварей немного кристаллизованной субстанции?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Магистр Даренис хочет, чтобы вы отправились в святилище Луны к западу от Транквиллиона и добыли 8 кристализованных субстанций маны с волшебных пожирателей и маначервей, что населяют это место.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это очень мощная субстанция. Я весьма доволен твоей работой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Даренису в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9151,'Святилище Солнца','Ты $Gдоказал:доказала; свою верность Транквиллиону, оказав содействие в борьбе против сил Плети. Из Луносвета прибыли несколько наших самых могучих магистров, чтобы перенести битву прямо на вражеский порог.$B$BОни восстановили чародейское святилище на юге и оттеснили Плеть из окрестностей. Они намерены нанести удар по Смертхольму, оплоту Дар\'Кхана. Тебе следует присоединиться к ним, $n. Уверен, $Gтакой закаленный:такая закаленная:c; |3-6($c), как ты, очень им пригодится.','Поговорите с магистром Идонисом в святилище Солнца в Призрачных землях.','Так ты от Дарэниса? Очень хорошо, думаю, твоя помощь в сражении с силами Дар\'Кхана нам пригодится.','Чем могу помочь, |3-6($C)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святилище Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gдоказал:доказала; свою верность Транквиллиону, оказав содействие в борьбе против сил Плети. Из Луносвета прибыли несколько наших самых могучих магистров, чтобы перенести битву прямо на вражеский порог.$B$BОни восстановили чародейское святилище на юге и оттеснили Плеть из окрестностей. Они намерены нанести удар по Смертхольму, оплоту Дар\'Кхана. Тебе следует присоединиться к ним, $n. Уверен, $Gтакой закаленный:такая закаленная:c; |3-6($c), как ты, очень им пригодится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с магистром Идонисом в святилище Солнца в Призрачных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ты от Дарэниса? Очень хорошо, думаю, твоя помощь в сражении с силами Дар\'Кхана нам пригодится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем могу помочь, |3-6($C)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9152,'Припасы могильщика','И как прикажете мне обеспечивать военные поставки, когда я даже своих собственных получить не могу? Мне обещали конвой – а он так и не прибыл. Кроме того, одну повозку пришлось бросить на западе, когда на меня напала шайка вурдалаков!$B$BС твоей помощью я мог бы заново открыть дело. Отправляйся из города по западной дороге мимо кладбища. По другую сторону Тропы Мертвых дорога раздваивается. Холм, за которым должна быть моя повозка, как раз за развилкой.','Вернитесь к Ратису Могильщику в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы могильщика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И как прикажете мне обеспечивать военные поставки, когда я даже своих собственных получить не могу? Мне обещали конвой – а он так и не прибыл. Кроме того, одну повозку пришлось бросить на западе, когда на меня напала шайка вурдалаков!$B$BС твоей помощью я мог бы заново открыть дело. Отправляйся из города по западной дороге мимо кладбища. По другую сторону Тропы Мертвых дорога раздваивается. Холм, за которым должна быть моя повозка, как раз за развилкой.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ратису Могильщику в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9153,'Под тенью','Парящие некрополи Плети не щадят ни Орду, ни Альянс. Тень летающих крепостей пала на Танарис, Выжженные земли, Зимние Ключи и Пылающие степи.$b$bТолько объединив усилия, мы сможем противостоять этой беде.$b$bНекрополи поддерживаются энергией магических кругов, которые размещены в различных точках захваченных регионов. Все магические круги охраняются полчищами нежити. Мы определили, что если уничтожить эти толпы нежити, то защита кругов будет снята.','Отлично, $N. Постепенно занимая новые позиции, мы сможем избавиться от угрозы со стороны возрожденной Плети. $B$BОтдохни и восстанови силы, но после этого тебе снова придется отправиться на фронт, иначе мы потеряем те земли, которые отбили сегодня. $B$BДабы помочь тебе в грядущих битвах, мы готовы отдать тебе некоторые из наших особых предметов в обмен на определенное количество некротических рун.','Потребуется какое-то время, чтобы избавиться от нависшей над нами угрозы. Как далеко тебе удалось продвинуться, $N?','Вернитесь к командиру Томасу Элерану в Восточную башню, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Под тенью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Парящие некрополи Плети не щадят ни Орду, ни Альянс. Тень летающих крепостей пала на Танарис, Выжженные земли, Зимние Ключи и Пылающие степи.$b$bТолько объединив усилия, мы сможем противостоять этой беде.$b$bНекрополи поддерживаются энергией магических кругов, которые размещены в различных точках захваченных регионов. Все магические круги охраняются полчищами нежити. Мы определили, что если уничтожить эти толпы нежити, то защита кругов будет снята.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N. Постепенно занимая новые позиции, мы сможем избавиться от угрозы со стороны возрожденной Плети. $B$BОтдохни и восстанови силы, но после этого тебе снова придется отправиться на фронт, иначе мы потеряем те земли, которые отбили сегодня. $B$BДабы помочь тебе в грядущих битвах, мы готовы отдать тебе некоторые из наших особых предметов в обмен на определенное количество некротических рун.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Потребуется какое-то время, чтобы избавиться от нависшей над нами угрозы. Как далеко тебе удалось продвинуться, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Томасу Элерану в Восточную башню, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9154,'Часовня Последней Надежды') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Часовня Последней Надежды',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9155,'По Тропе Мертвых','Раз уж ты $Gзабрел:забрела; в такую даль, то $gдолжен:должна; знать о Тропе Мертвых. Даже теперь твари Плети бездумно следуют по выжженной полосе, что оставил за собой Артас по пути в Луносвет.$B$BПокажи, на что ты $gспособен:способна;, прореди ряды Плети на Тропе. Если отработаешь свой хлеб, я замолвлю за тебя доброе слово.','Убейте 10 восставших ненасытников и 10 уродливых каннибалов на Тропе Мертвых. Возвращайтесь к ловчему смерти Ратиэлю в Транквиллион за наградой.','Тебе удалось добыть кристаллы?','Вернитесь к ловчему смерти Ратиэлю в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По Тропе Мертвых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раз уж ты $Gзабрел:забрела; в такую даль, то $gдолжен:должна; знать о Тропе Мертвых. Даже теперь твари Плети бездумно следуют по выжженной полосе, что оставил за собой Артас по пути в Луносвет.$B$BПокажи, на что ты $gспособен:способна;, прореди ряды Плети на Тропе. Если отработаешь свой хлеб, я замолвлю за тебя доброе слово.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 восставших ненасытников и 10 уродливых каннибалов на Тропе Мертвых. Возвращайтесь к ловчему смерти Ратиэлю в Транквиллион за наградой.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть кристаллы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему смерти Ратиэлю в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9156,'Сим назначается щедрая награда за мерзостных поганищ, известных как Гнилоступ и Лузран! Эти отвратительные создания Дар\'Кхана чрезвычайно опасны. Их видели близ Воющего и Кровоточащего зиккуратов. Тот, кто желает получить награду, должен предоставить головы этих поганищ ловчему смерти Ратиэлю в доказательство своей победы!','Найдите в Призрачных землях Гнилоступа и Лузрана. Принесите их головы ловчему смерти Ратиэлю в Транквиллион и получите награду.','Вернитесь к ловчему смерти Ратиэлю в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сим назначается щедрая награда за мерзостных поганищ, известных как Гнилоступ и Лузран! Эти отвратительные создания Дар\'Кхана чрезвычайно опасны. Их видели близ Воющего и Кровоточащего зиккуратов. Тот, кто желает получить награду, должен предоставить головы этих поганищ ловчему смерти Ратиэлю в доказательство своей победы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Призрачных землях Гнилоступа и Лузрана. Принесите их головы ловчему смерти Ратиэлю в Транквиллион и получите награду.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему смерти Ратиэлю в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9157,'Забытые обряды','Каждый год мы, обитатели деревни Солнечной короны, принимали участие в обряде, который был предназначен для того, чтобы держать под контролем различные аспекты природы. Власть над стихией Воды символизировалась призыванием и покорением элементаля по имени Аквантион. Но наши чары были подлым образом искажены, в результате этот поганец разорвал узы и сам поработил нас!$B$BВо время обряда мы носили медальоны в виде волны. Найди их на дне этого озера, они нужны нам, чтобы освободить души наших сородичей!','Принесите 8 медальонов Волны Геранису Белому Рассвету в Призрачные земли.','Теперь, когда у нас снова есть эти медальоны, мы призовем Аквантиона. Этот мятежный элементаль заплатит за нашу смерть. Мы будем отомщены!','Вернитесь к Геранису Белому Рассвету в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Забытые обряды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Каждый год мы, обитатели деревни Солнечной короны, принимали участие в обряде, который был предназначен для того, чтобы держать под контролем различные аспекты природы. Власть над стихией Воды символизировалась призыванием и покорением элементаля по имени Аквантион. Но наши чары были подлым образом искажены, в результате этот поганец разорвал узы и сам поработил нас!$B$BВо время обряда мы носили медальоны в виде волны. Найди их на дне этого озера, они нужны нам, чтобы освободить души наших сородичей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 медальонов Волны Геранису Белому Рассвету в Призрачные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда у нас снова есть эти медальоны, мы призовем Аквантиона. Этот мятежный элементаль заплатит за нашу смерть. Мы будем отомщены!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Геранису Белому Рассвету в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9158,'Разносчики заразы','Ты $Gпроявил:проявила; мужество, отправившись сюда, в Призрачные земли, $n. Здесь у нас много работы и мало храбрецов, готовых за нее взяться.$B$BЕсли ты действительно $gготов:готова; нам помочь, я осмелюсь предложить тебе одно неблагодарное задание. Вся дикая природа здесь поражена заразой, и мы должны остановить ее распространение. Ступай охотиться на светлопалых рысей к востоку и югу отсюда и возвращайся, когда перебьешь достаточное их число.','Ты $Gвыполнил:выполнила; задание, о котором я тебя просила, $N?','Вернитесь к страннице Седайне в Анклав Странников, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разносчики заразы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gпроявил:проявила; мужество, отправившись сюда, в Призрачные земли, $n. Здесь у нас много работы и мало храбрецов, готовых за нее взяться.$B$BЕсли ты действительно $gготов:готова; нам помочь, я осмелюсь предложить тебе одно неблагодарное задание. Вся дикая природа здесь поражена заразой, и мы должны остановить ее распространение. Ступай охотиться на светлопалых рысей к востоку и югу отсюда и возвращайся, когда перебьешь достаточное их число.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвыполнил:выполнила; задание, о котором я тебя просила, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к страннице Седайне в Анклав Странников, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9159,'Обуздание заразы','Ты $Gпоказал:показала; себя достойным союзником, $n. Я прошу тебя продолжить труды и выследить еще некоторое количество зараженных животных. На сей раз придется иметь дело с более опасными тварями. А именно – с воронковыми пауками-прядильщиками к западу от Тропы Мертвых и мрачницами-вампирами к югу отсюда. Покончишь с делом – возвращайся ко мне.','Итак, дело сделано, |3-6($C)? Ты отключила лунный кристалл ночных эльфов в Ан\'овине?','Вернитесь к страннице Седайне в Анклав Странников, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обуздание заразы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $Gпоказал:показала; себя достойным союзником, $n. Я прошу тебя продолжить труды и выследить еще некоторое количество зараженных животных. На сей раз придется иметь дело с более опасными тварями. А именно – с воронковыми пауками-прядильщиками к западу от Тропы Мертвых и мрачницами-вампирами к югу отсюда. Покончишь с делом – возвращайся ко мне.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Итак, дело сделано, |3-6($C)? Ты отключила лунный кристалл ночных эльфов в Ан\'овине?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к страннице Седайне в Анклав Странников, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9160,'Обследование Ан\'дарота','$C, у нас проблемы с группой ночных эльфов, недавно захвативших находящийся поблизости островок. Они устроили небольшой лагерь в Ан\'дароте, древнем узле линии магической силы, облюбованном еще высшими эльфами. Это к северо-западу отсюда. Туда ведет грунтовая дорога, что начинается сразу за Тропой Мертвых.$B$BПомоги нам – отправляйся туда, узнай, что они затевают, и перебей сколько сможешь этих надменных ночных эльфов.','Обследуйте район Ан\'дарота','Вернитесь к госпоже Златилен в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обследование Ан\'дарота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, у нас проблемы с группой ночных эльфов, недавно захвативших находящийся поблизости островок. Они устроили небольшой лагерь в Ан\'дароте, древнем узле линии магической силы, облюбованном еще высшими эльфами. Это к северо-западу отсюда. Туда ведет грунтовая дорога, что начинается сразу за Тропой Мертвых.$B$BПомоги нам – отправляйся туда, узнай, что они затевают, и перебей сколько сможешь этих надменных ночных эльфов.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Обследуйте район Ан\'дарота',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к госпоже Златилен в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9161,'Тень предателя','Говорят, что Дар\'Кхан Дратир восстал из мертвых, чтобы возглавить полчища Плети здесь, в Призрачных землях. Дар\'Кхан давно уже связался с Плетью... но некогда, при жизни, он был эльфом... Большую часть своего времени он проводил в Башне Утренней Звезды, к северо-востоку отсюда. Он скрывался там долгими ночами, строя козни против собственного народа. $B$BОбыщи башню, $n, может, найдешь еще какую информацию. Возможно, он вел дневник или делал записи. Поищи, информация лишней не бывает.','Отправляйтесь к Башне Утренней Звезды в Призрачных землях и найдите любую информацию о прошлом Дар\'Кхана.','Перевернув несколько страниц этой древней книжицы, вы приходите к выводу, что некогда она принадлежала эльфу по имени Дар\'Кхан Дратир.','Чем так воняет?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тень предателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что Дар\'Кхан Дратир восстал из мертвых, чтобы возглавить полчища Плети здесь, в Призрачных землях. Дар\'Кхан давно уже связался с Плетью... но некогда, при жизни, он был эльфом... Большую часть своего времени он проводил в Башне Утренней Звезды, к северо-востоку отсюда. Он скрывался там долгими ночами, строя козни против собственного народа. $B$BОбыщи башню, $n, может, найдешь еще какую информацию. Возможно, он вел дневник или делал записи. Поищи, информация лишней не бывает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Башне Утренней Звезды в Призрачных землях и найдите любую информацию о прошлом Дар\'Кхана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Перевернув несколько страниц этой древней книжицы, вы приходите к выводу, что некогда она принадлежала эльфу по имени Дар\'Кхан Дратир.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем так воняет?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9162,'Отблески былого','Просматривая страницы дневника, вы вдруг испытываете острое ощущение того, что за вами наблюдают.$B$BСодержание дневника пугает. Душа Дар\'Кхана полна ненависти и презрения к собственному народу. Все его махинации и интриги изложены здесь в мельчайших подробностях.$B$BВозможно, Винне может пригодиться эта информация.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отблески былого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Просматривая страницы дневника, вы вдруг испытываете острое ощущение того, что за вами наблюдают.$B$BСодержание дневника пугает. Душа Дар\'Кхана полна ненависти и презрения к собственному народу. Все его махинации и интриги изложены здесь в мельчайших подробностях.$B$BВозможно, Винне может пригодиться эта информация.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9163,'Вылазка на оккупированную территорию','Наиболее простой способ выведать планы ночных эльфов – отправить тебя на их остров с целью добыть любую доступную информацию.$B$BЯ хочу, чтобы ты $Gнаправился:направилась; на запад по дороге из города на остров Шаландис, что прямо рядом с побережьем. Ступай туда и принеси мне все планы, которые найдешь на острове либо на корабле.','Вернитесь к госпоже Златилен в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вылазка на оккупированную территорию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наиболее простой способ выведать планы ночных эльфов – отправить тебя на их остров с целью добыть любую доступную информацию.$B$BЯ хочу, чтобы ты $Gнаправился:направилась; на запад по дороге из города на остров Шаландис, что прямо рядом с побережьем. Ступай туда и принеси мне все планы, которые найдешь на острове либо на корабле.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к госпоже Златилен в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9164,'Пленники Смертхольма','Что с пленниками Смертхольма? Ты туда еще не ходила?','Вернитесь к чародейке Джанеде в Святилище Солнца, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пленники Смертхольма',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что с пленниками Смертхольма? Ты туда еще не ходила?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародейке Джанеде в Святилище Солнца, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9165,'Подорожная','Если бы не помощь странников вроде тебя, наш караван никогда не добрался бы до пункта назначения! Твари Плети лезут из всех щелей!$B$B*Страж Дидье утирает лоб*$B$BТеперь надо дождаться здесь фельдмаршала Чамберса, чтобы он подписал тебе подорожную. Предъявишь ее командиру Метцу в Часовню Последней Надежды в Восточные Проклятые земли.$B$BИ вот что, $n, имей в виду, Метц из тех парней, которые любят орать, мол, прихлопну как муху да кишки по деревьям развешу... Только в отличие от большинства подобных крикунов, именно так он и сделает.','Доставьте подписанную подорожную командиру Метцу в Часовню Последней Надежды в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подорожная',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если бы не помощь странников вроде тебя, наш караван никогда не добрался бы до пункта назначения! Твари Плети лезут из всех щелей!$B$B*Страж Дидье утирает лоб*$B$BТеперь надо дождаться здесь фельдмаршала Чамберса, чтобы он подписал тебе подорожную. Предъявишь ее командиру Метцу в Часовню Последней Надежды в Восточные Проклятые земли.$B$BИ вот что, $n, имей в виду, Метц из тех парней, которые любят орать, мол, прихлопну как муху да кишки по деревьям развешу... Только в отличие от большинства подобных крикунов, именно так он и сделает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте подписанную подорожную командиру Метцу в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9166,'Донесение в Ан\'телас','Отправляйся на восток. На южном склоне пика Солнечного Пастбища, к северо-востоку от святилища Солнца, находится Ан\'телас. Именно туда следует доставить обнаруженные нами планы ночных эльфов.$B$BМагистр Силастор постоянно проводит там исследования узлов линий силы для потенциального их использования в битве с Плетью. Пусть глянет на эти планы и прольет свет на замыслы ночных эльфов.','Передайте планы ночных эльфов магистру Силастору из Ан\'теласа в Призрачных землях.','О, хвала Солнцу!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение в Ан\'телас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отправляйся на восток. На южном склоне пика Солнечного Пастбища, к северо-востоку от святилища Солнца, находится Ан\'телас. Именно туда следует доставить обнаруженные нами планы ночных эльфов.$B$BМагистр Силастор постоянно проводит там исследования узлов линий силы для потенциального их использования в битве с Плетью. Пусть глянет на эти планы и прольет свет на замыслы ночных эльфов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте планы ночных эльфов магистру Силастору из Ан\'теласа в Призрачных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О, хвала Солнцу!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9167,'Гибель предателя','Все, что мы сделали в Призрачных землях, призвано вернуть принадлежащее нам по праву. Плеть слишком долго держала в своих когтях эти земли.$B$BПришло время расплаты, $n. Благодаря тебе и нашим новым союзникам, Отрекшимся, час отмщения близок.$B$BТот, кто хочет похитить мощь Солнечного Колодца, должен сгинуть! Ступай в Смертхольм, оплот Плети к югу от Тропы Мертвых. Принеси мне голову Дар\'Кхана, и твои деяния не будут забыты!','Ну, дело сделано? Дар\'Кхан убит?','Вернитесь к магистру Каендрису в Святилище Солнца, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гибель предателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все, что мы сделали в Призрачных землях, призвано вернуть принадлежащее нам по праву. Плеть слишком долго держала в своих когтях эти земли.$B$BПришло время расплаты, $n. Благодаря тебе и нашим новым союзникам, Отрекшимся, час отмщения близок.$B$BТот, кто хочет похитить мощь Солнечного Колодца, должен сгинуть! Ступай в Смертхольм, оплот Плети к югу от Тропы Мертвых. Принеси мне голову Дар\'Кхана, и твои деяния не будут забыты!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, дело сделано? Дар\'Кхан убит?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Каендрису в Святилище Солнца, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9168,'Сердце Смертхольма','Глубоко в недрах Смертхольма наши враги пытаются создать более сильных и смертоносных призрачных солдат. Эти гнусные твари – совершенные инструменты, созданные самим Дар\'Кханом и закаленные черной магией Смертхольма.$B$BОтправляйся в башню Проклятых Смертхольма и уничтожь их, $n. Мы не можем позволить армии нашего врага усиливаться в то время, как мы с трудом удерживаем плацдарм в Призрачных землях.','Уничтожьте 8 очей Дар\'Кхана и доложите об этом магистру Идонису из святилища Солнца в Призрачных землях.','Вернитесь к магистру Идонису в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце Смертхольма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Глубоко в недрах Смертхольма наши враги пытаются создать более сильных и смертоносных призрачных солдат. Эти гнусные твари – совершенные инструменты, созданные самим Дар\'Кханом и закаленные черной магией Смертхольма.$B$BОтправляйся в башню Проклятых Смертхольма и уничтожь их, $n. Мы не можем позволить армии нашего врага усиливаться в то время, как мы с трудом удерживаем плацдарм в Призрачных землях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 очей Дар\'Кхана и доложите об этом магистру Идонису из святилища Солнца в Призрачных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Идонису в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9169,'Ан\'овин: отключение','Эти лунные кристаллы – наблюдательные устройства, и следят они за нами! Я понимаю, что из Ан\'дарота до кристаллов дотянуться не смогут, чего не могу сказать про Ан\'овин, что лежит прямо к югу отсюда.$B$BИз схем, которые теперь есть в моем распоряжении, я узнал основные принципы действия лунных кристаллов; достаточно просто отключить их. Отправляйся в Ан\'овин, добудь сферу управления у одного из ночных эльфов и с ее помощью отключи лунный кристалл, чтобы не дать осуществиться их планам!$B$BТоропись, |3-6($c)!','Добудьте сферу управления кристаллом и с ее помощью отключите лунный кристалл ночных эльфов в Ан\'овине. Затем возвращайтесь к магистру Силастору в Ан\'телас в Призрачных землях.','Что с пленниками Смертхольма? Ты туда еще не ходила?','Вернитесь к магистру Силастору в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ан\'овин: отключение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти лунные кристаллы – наблюдательные устройства, и следят они за нами! Я понимаю, что из Ан\'дарота до кристаллов дотянуться не смогут, чего не могу сказать про Ан\'овин, что лежит прямо к югу отсюда.$B$BИз схем, которые теперь есть в моем распоряжении, я узнал основные принципы действия лунных кристаллов; достаточно просто отключить их. Отправляйся в Ан\'овин, добудь сферу управления у одного из ночных эльфов и с ее помощью отключи лунный кристалл, чтобы не дать осуществиться их планам!$B$BТоропись, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сферу управления кристаллом и с ее помощью отключите лунный кристалл ночных эльфов в Ан\'овине. Затем возвращайтесь к магистру Силастору в Ан\'телас в Призрачных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что с пленниками Смертхольма? Ты туда еще не ходила?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Силастору в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9170,'Приспешники Дар\'Кхана','Этот подлый предатель, Дар\'Кхан, обрел великую власть, встав на сторону Плети. Его приспешники командуют огромной армией нежити, что противостоит нашим тающим силам.$B$BМасофет Черный, Джурион Обманщик, Боргот Кровопускатель и Мирдоран Мерзостный. Запомни эти имена крепко, ибо в Призрачных землях эти полководцы Плети уступают только самому Дар\'Кхану. Срази их, и их безмозглое воинство будет повергнуто в хаос.','Магистр Идонис хочет, чтобы вы отправились в Смертхольм и сразили Масофета Черного, Джуриона Обманщика, Боргота Кровопускателя и Мирдорана Мерзостного. Выполнив поручение, отчитайтесь перед магистром Идонисом в святилище Солнца Призрачных земель.','Армии Дар\'Кхана скоро будут разгромлены. Плеть не выстоит против объединенной мощи син\'дорай и Отрекшихся.','Что с пленниками Смертхольма? Ты туда еще не ходила?','Вернитесь к магистру Идонису в Святилище Солнца, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приспешники Дар\'Кхана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот подлый предатель, Дар\'Кхан, обрел великую власть, встав на сторону Плети. Его приспешники командуют огромной армией нежити, что противостоит нашим тающим силам.$B$BМасофет Черный, Джурион Обманщик, Боргот Кровопускатель и Мирдоран Мерзостный. Запомни эти имена крепко, ибо в Призрачных землях эти полководцы Плети уступают только самому Дар\'Кхану. Срази их, и их безмозглое воинство будет повергнуто в хаос.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Магистр Идонис хочет, чтобы вы отправились в Смертхольм и сразили Масофета Черного, Джуриона Обманщика, Боргота Кровопускателя и Мирдорана Мерзостного. Выполнив поручение, отчитайтесь перед магистром Идонисом в святилище Солнца Призрачных земель.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Армии Дар\'Кхана скоро будут разгромлены. Плеть не выстоит против объединенной мощи син\'дорай и Отрекшихся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что с пленниками Смертхольма? Ты туда еще не ходила?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Идонису в Святилище Солнца, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9171,'Хрустящий деликатес','Это невыносимо! Мне тут совершенно не из чего готовить! Госпожа пригласила меня из Луносвета – ей нужны утонченные блюда, соответствующие ее положению. А что, нет? И вот я здесь, но тут нечего есть! Ты $Gдолжен:должна; пойти и принести свежей дичи, чтобы я хоть что-нибудь смог приготовить.$B$BГоспожа Златилен любит покушать что-нибудь хрустящее. К юго-западу отсюда, по ту сторону Тропы Мертвых, полно воронковых пауков-прядильщиков. Да, они противные, я знаю, но именно они нам и нужны.','Вернитесь к главному шеф-повару Плеснеру в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хрустящий деликатес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это невыносимо! Мне тут совершенно не из чего готовить! Госпожа пригласила меня из Луносвета – ей нужны утонченные блюда, соответствующие ее положению. А что, нет? И вот я здесь, но тут нечего есть! Ты $Gдолжен:должна; пойти и принести свежей дичи, чтобы я хоть что-нибудь смог приготовить.$B$BГоспожа Златилен любит покушать что-нибудь хрустящее. К юго-западу отсюда, по ту сторону Тропы Мертвых, полно воронковых пауков-прядильщиков. Да, они противные, я знаю, но именно они нам и нужны.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному шеф-повару Плеснеру в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (9172,'Ты хотела говорить со мной?') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хотела говорить со мной?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9173,'Захват Шпилей Ветрокрылых','$C, я желаю, чтобы ты $gзахватил:захватила; Шпили Ветрокрылых!$B$BЭто высокая честь. Шпили Ветрокрылых – родина Сильваны Ветрокрылой, повелительницы Отрекшихся и бывшего главнокомандующего следопытов эльфов. Однако ныне башня захвачена безмозглыми полчищами Плети.$B$BЧтобы добраться туда, ступай по южной дороге до развилки. Возьми направо и, пересекши Тропу Мертвых, иди на юго-запад. Ты обязательно увидишь ее.','Тебе удалось добыть кристаллы?','Вернитесь к верховному палачу Маврену в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват Шпилей Ветрокрылых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, я желаю, чтобы ты $gзахватил:захватила; Шпили Ветрокрылых!$B$BЭто высокая честь. Шпили Ветрокрылых – родина Сильваны Ветрокрылой, повелительницы Отрекшихся и бывшего главнокомандующего следопытов эльфов. Однако ныне башня захвачена безмозглыми полчищами Плети.$B$BЧтобы добраться туда, ступай по южной дороге до развилки. Возьми направо и, пересекши Тропу Мертвых, иди на юго-запад. Ты обязательно увидишь ее.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть кристаллы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Маврену в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9174,'Победа над Аквантионом','Этот злобный элементаль сгубил много жизней в тот роковой день, когда восстал против нас. Чтобы нарушить наш обряд, он призвал подлых мурлоков. Более того, ему удалось исказить наши чары и обратить их против нас.$B$BПокажи ему всю силу нашей неутоленной мести! Возьми эти медальоны и возложи их на алтарь Укрощения Приливов на дне озера. Аквантион тут же ответит на твой вызов!$B$BНо берегись, |3-6($r)! Поскольку наша магия более не властна над ним, гнев его будет неукротим! Срази Аквантиона, дабы мы обрели покой!','Геранис Белый Рассвет хочет, чтобы вы нырнули на дно озера к востоку от деревни Солнечной Короны и возложили связку медальонов на алтарь Укрощения Приливов. Призовите и сразите элементаля по имени Аквантион, затем возвращайтесь к Геранису.','Аквантион убит?','Вернитесь к Геранису Белому Рассвету в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Победа над Аквантионом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот злобный элементаль сгубил много жизней в тот роковой день, когда восстал против нас. Чтобы нарушить наш обряд, он призвал подлых мурлоков. Более того, ему удалось исказить наши чары и обратить их против нас.$B$BПокажи ему всю силу нашей неутоленной мести! Возьми эти медальоны и возложи их на алтарь Укрощения Приливов на дне озера. Аквантион тут же ответит на твой вызов!$B$BНо берегись, |3-6($r)! Поскольку наша магия более не властна над ним, гнев его будет неукротим! Срази Аквантиона, дабы мы обрели покой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Геранис Белый Рассвет хочет, чтобы вы нырнули на дно озера к востоку от деревни Солнечной Короны и возложили связку медальонов на алтарь Укрощения Приливов. Призовите и сразите элементаля по имени Аквантион, затем возвращайтесь к Геранису.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Аквантион убит?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Геранису Белому Рассвету в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (9175,'Ожерелье Госпожи','Ожерелье мерцает, это настоящий шедевр ювелирного искусства, который светится даже во мраке, окутывающем Призрачные земли. Судя по надписи и месту, где вы его нашли, это наверняка принадлежит самой леди Сильване Ветрокрылой!$B$BНаверное, лучше всего будет отнести эту вещь верховному палачу Маврену в Транквиллион. Похоже, он самый высокопоставленный Отрекшийся в здешних местах и наверняка знает, что с этой вещью делать.','Говоришь, ты нашла это на одной из тварей Плети в Шпилях Ветрокрылых и что на ней есть надпись? Дай-ка посмотреть!\n\nВот, возьми монету за хорошую работу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье Госпожи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ожерелье мерцает, это настоящий шедевр ювелирного искусства, который светится даже во мраке, окутывающем Призрачные земли. Судя по надписи и месту, где вы его нашли, это наверняка принадлежит самой леди Сильване Ветрокрылой!$B$BНаверное, лучше всего будет отнести эту вещь верховному палачу Маврену в Транквиллион. Похоже, он самый высокопоставленный Отрекшийся в здешних местах и наверняка знает, что с этой вещью делать.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говоришь, ты нашла это на одной из тварей Плети в Шпилях Ветрокрылых и что на ней есть надпись? Дай-ка посмотреть!\n\nВот, возьми монету за хорошую работу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9176,'Зиккураты-близнецы','Судя по этому дневнику, Дар\'Кхан пообещал Плети два могучих эльфийских артефакта: камень Света и камень Пламени. Они наполнены магический силой Солнечного Колодца и настроены так, чтобы Плеть не могла овладеть ими.$B$BЭти кристаллы предполагалось перенести туда, где ныне стоят Воющий и Кровоточащий зиккураты, прямо в центр Тропы Мертвых. Если они и доныне там, нам нужно вернуть их. Их сила очень понадобится нам в борьбе с врагом.','Тебе удалось добыть кристаллы?','Вернитесь к магистру Каендрису в Святилище Солнца, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зиккураты-близнецы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по этому дневнику, Дар\'Кхан пообещал Плети два могучих эльфийских артефакта: камень Света и камень Пламени. Они наполнены магический силой Солнечного Колодца и настроены так, чтобы Плеть не могла овладеть ими.$B$BЭти кристаллы предполагалось перенести туда, где ныне стоят Воющий и Кровоточащий зиккураты, прямо в центр Тропы Мертвых. Если они и доныне там, нам нужно вернуть их. Их сила очень понадобится нам в борьбе с врагом.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть кристаллы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Каендрису в Святилище Солнца, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (9177,'Путь в Подгород','Отнесите Сильване Ветрокрылой ожерелье Госпожи в Королевский квартал Подгорода.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь в Подгород',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите Сильване Ветрокрылой ожерелье Госпожи в Королевский квартал Подгорода.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9178,'Задание мастера: массивное грузило','Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд BS-091:$B$B120 массивных грузил.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет','Доставьте 120 массивных грузил и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание мастера: массивное грузило',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд BS-091:$B$B120 массивных грузил.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте 120 массивных грузил и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`);
