INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9189,'Посылка в Гробницу','Тебе удалось тронуть женское сердце, хоть оно и не бьется.$B$BОднако мне нужно доставить кое-какие бумаги в Гробницу, расположенную в Серебряном бору. Наш представитель там – советник Соррелон.$B$BЕсли ты не собираешься лететь на летучей мыши, кратчайший путь – это выйти из Подгорода и двинуться по дороге на юг. Смотри на указатели, отыскать нужное место будет несложно. Соберись с духом. Гробница представляет собой полуразрушенный склеп.$B$BСтранные существа эти Отрекшиеся.','Отнесите запечатанные приказы син\'дорай советнику Соррелону в Гробницу в Серебряном бору.','Приветствую тебя, сестра. Какие вести ты принесла?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посылка в Гробницу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось тронуть женское сердце, хоть оно и не бьется.$B$BОднако мне нужно доставить кое-какие бумаги в Гробницу, расположенную в Серебряном бору. Наш представитель там – советник Соррелон.$B$BЕсли ты не собираешься лететь на летучей мыши, кратчайший путь – это выйти из Подгорода и двинуться по дороге на юг. Смотри на указатели, отыскать нужное место будет несложно. Соберись с духом. Гробница представляет собой полуразрушенный склеп.$B$BСтранные существа эти Отрекшиеся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанные приказы син\'дорай советнику Соррелону в Гробницу в Серебряном бору.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую тебя, сестра. Какие вести ты принесла?',`requestitemstext_loc8`);
