INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9192,'Беда в Беспросветных рудниках','Беспросветные рудники к юго-западу отсюда захвачены гноллами, зовущими себя кланом Черной Лапы. Мне не надо напоминать тебе, сколь стратегически важны эти рудники для нашей кампании в Призрачных землях!$B$BСтупай по южной дороге из города и на развилке возьми вправо. Прямо за зиккуратом справа будет короткая грунтовая тропа на запад. Иди по ней.$B$BКак увидишь кучи руды, знай – ты $gпришел:пришла;.','Надеюсь, ты принесла мне известие о том, что Шпили Ветрокрылых очищены от нечестивой Плети?','Вернитесь к ловчему смерти Малтендису в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беда в Беспросветных рудниках',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Беспросветные рудники к юго-западу отсюда захвачены гноллами, зовущими себя кланом Черной Лапы. Мне не надо напоминать тебе, сколь стратегически важны эти рудники для нашей кампании в Призрачных землях!$B$BСтупай по южной дороге из города и на развилке возьми вправо. Прямо за зиккуратом справа будет короткая грунтовая тропа на запад. Иди по ней.$B$BКак увидишь кучи руды, знай – ты $gпришел:пришла;.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты принесла мне известие о том, что Шпили Ветрокрылых очищены от нечестивой Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему смерти Малтендису в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
