INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9199,'Джуджу троллей','Погребенные в катакомбах Амани тролли начали восставать из мертвых! Я хочу, чтобы ты $Gотправился:оправилась; туда и $Gвернулся:вернулась; с доказательствами их окончательной и бесповоротной смерти! На некоторых из этих тролльских мумий и их вполне живых двойниках есть джуджу – святящиеся предметы, в которых заключен неведомый источник силы. Возможно, от этого они и оживают!$B$BКатакомбы лежат под пиком Солнечного Пастбища, прямо на востоке. Мне говорили, что проще всего туда добраться через вход в северном склоне горы. Найди же его, |3-6($c)!','Думаю, мне незачем напоминать тебе, что мы не можем позволить себе, чтобы эти тролли поднимались из покойников прямо у нас под носом! Нам хватает забот со Смертхольмом на юге!','Вернитесь к ловчему смерти Малтендису в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джуджу троллей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Погребенные в катакомбах Амани тролли начали восставать из мертвых! Я хочу, чтобы ты $Gотправился:оправилась; туда и $Gвернулся:вернулась; с доказательствами их окончательной и бесповоротной смерти! На некоторых из этих тролльских мумий и их вполне живых двойниках есть джуджу – святящиеся предметы, в которых заключен неведомый источник силы. Возможно, от этого они и оживают!$B$BКатакомбы лежат под пиком Солнечного Пастбища, прямо на востоке. Мне говорили, что проще всего туда добраться через вход в северном склоне горы. Найди же его, |3-6($c)!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Думаю, мне незачем напоминать тебе, что мы не можем позволить себе, чтобы эти тролли поднимались из покойников прямо у нас под носом! Нам хватает забот со Смертхольмом на юге!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему смерти Малтендису в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9200,'Задание мастера: огромный флакон с зельем маны','Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд AL-473:$B$B10 огромных флаконов с зельем маны.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет','Доставьте 10 огромных флаконов с зельем маны и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание мастера: огромный флакон с зельем маны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд AL-473:$B$B10 огромных флаконов с зельем маны.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте 10 огромных флаконов с зельем маны и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`);
