INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9206,'Задание мастера: молниевый угорь','Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд FS-9:$B$B30 молниевых угрей.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет','Доставьте 30 молниевых угрей и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание мастера: молниевый угорь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Податель сего имеет право на получение награды в форме значков отличия по своему выбору в случае выполнения задания, указанного в контракте.$B$BЗаказ-наряд FS-9:$B$B30 молниевых угрей.$B$BВыполненные заказы доставлять караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.$B$BКонтракт признается недействительным в случае, если бумага была подделана или тем или иным образом испорчена.$B$BПодпись: Командир Метц, Серебряный Рассвет',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте 30 молниевых угрей и соответствующее задание мастера караванщику Камнетесу в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9207,'Образцы руды из Беспросветных рудников','Меня прислали сюда из святилища Солнца за образцами руды, но рудники захватили гноллы! Если я вскорости не доставлю эти образцы магистру, он мне голову оторвет. Ты не $gмог:могла; бы мне помочь, |3-6($c)?$B$BРуду можно добыть из медных и оловянных жил, да и гноллы таскают ее там повсюду. Набрав достаточно руды, отнеси ее магистру Квалестису в святилище Солнца, что прямо на востоке отсюда. Когда пересечешь Тропу Мертвых, святилище будет прямо к югу от пика Солнечного Пастбища.','Принесите 6 образцов руды из Беспросветных рудников и доставьте их магистру Квалестису в святилище Солнца в Призрачных землях.','Вернитесь к магистру Квалестису в Святилище Солнца, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Образцы руды из Беспросветных рудников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня прислали сюда из святилища Солнца за образцами руды, но рудники захватили гноллы! Если я вскорости не доставлю эти образцы магистру, он мне голову оторвет. Ты не $gмог:могла; бы мне помочь, |3-6($c)?$B$BРуду можно добыть из медных и оловянных жил, да и гноллы таскают ее там повсюду. Набрав достаточно руды, отнеси ее магистру Квалестису в святилище Солнца, что прямо на востоке отсюда. Когда пересечешь Тропу Мертвых, святилище будет прямо к югу от пика Солнечного Пастбища.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 образцов руды из Беспросветных рудников и доставьте их магистру Квалестису в святилище Солнца в Призрачных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Квалестису в Святилище Солнца, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9208,'Защита Джунглей – Магический знак защиты','Занза владеет искусством древних троллей и может сделать множество полезных вещей. Тебе когда-нибудь приходилось слышать о Защите Джунглей? Ну конечно нет. Твой разум сбит с толку жалкой эльфийской магией.$B$BПринеси мне магический знак эльфийской работы. Тогда я дам тебе Защиту, и ты увидишь, что такое настоящая магия!','Занзе Неупокоенному в Зул\'Гурубе нужен магический знак защиты.','Беспокойная магия этих чар, усиливает мой гнев. Гнев, дает мне силы.$B$BПриноси мне больше таких знаков и я выдам тебе еще один такой знак защиты.','У тебя есть аркан?','Вернитесь к Занзе Неупокоенному в Зул\'Гуруб.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Джунглей – Магический знак защиты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Занза владеет искусством древних троллей и может сделать множество полезных вещей. Тебе когда-нибудь приходилось слышать о Защите Джунглей? Ну конечно нет. Твой разум сбит с толку жалкой эльфийской магией.$B$BПринеси мне магический знак эльфийской работы. Тогда я дам тебе Защиту, и ты увидишь, что такое настоящая магия!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Занзе Неупокоенному в Зул\'Гурубе нужен магический знак защиты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Беспокойная магия этих чар, усиливает мой гнев. Гнев, дает мне силы.$B$BПриноси мне больше таких знаков и я выдам тебе еще один такой знак защиты.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть аркан?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Занзе Неупокоенному в Зул\'Гуруб.',`completedtext_loc8`);
