pletedtext_loc8`='','Вернитесь к Занзе Неупокоенному в Зул\'Гуруб.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9211,'Ледяная защита','Ледяная защита – это тончайшая пленка защитных чар, наносимая на отдельные элементы экипировки. Она позволяет усиливать защиту в бою с ледяными созданиями.$B$BОднако все, что делает Обрушивающий Гнев, имеет свою цену – и немалую! Клянчить скидку бесполезно. Ну что, $gготов:готова; раскошелиться?','Заплатите 10 значков Алого ордена и 30 золотых Матеусу Обрушивающему Гнев из Часовни Последней Надежды в Восточных Чумных землях.','<Матеус подставляет карман для золота.>$B$B$R, Наксрамас – не доброе место, пусть тебя оберегает эта ледяная защита.','Если бы не Серебряный Рассвет, вряд ли бы тут сейчас мозолил мне глаза!','Вернитесь к Матеусу Обрушивающему Гнев в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ледяная защита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ледяная защита – это тончайшая пленка защитных чар, наносимая на отдельные элементы экипировки. Она позволяет усиливать защиту в бою с ледяными созданиями.$B$BОднако все, что делает Обрушивающий Гнев, имеет свою цену – и немалую! Клянчить скидку бесполезно. Ну что, $gготов:готова; раскошелиться?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заплатите 10 значков Алого ордена и 30 золотых Матеусу Обрушивающему Гнев из Часовни Последней Надежды в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Матеус подставляет карман для золота.>$B$B$R, Наксрамас – не доброе место, пусть тебя оберегает эта ледяная защита.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если бы не Серебряный Рассвет, вряд ли бы тут сейчас мозолил мне глаза!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матеусу Обрушивающему Гнев в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9212,'Бегство из Катакомб','Ты настоящая героиня, |3-6($C), раз сумела привести ее сюда в целости и сохранности! Полагаю, придется устроить рейд и зачистить еще и эти катакомбы. Можно подумать, нам не хватает проблем с живыми троллями!\n\nСегодня ты совершила великий подвиг, и я должен наградить тебя. Выбирай любой из этих предметов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бегство из Катакомб',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты настоящая героиня, |3-6($C), раз сумела привести ее сюда в целости и сохранности! Полагаю, придется устроить рейд и зачистить еще и эти катакомбы. Можно подумать, нам не хватает проблем с живыми троллями!\n\nСегодня ты совершила великий подвиг, и я должен наградить тебя. Выбирай любой из этих предметов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9213,'Теневая защита','Это гениальное изобретение! Также как и Ледяная защита, Теневая защита основана на использовании тонкой пленки защитной магии на элементах экипировки. Есть еще кое-что, что роднит ее с Ледяной защитой – ЦЕНА!$B$BНу что, $gготов:готова; выложить кругленькую сумму?','Заплатите 10 значков Алого ордена и 30 золотых Матеусу Обрушивающему Гнев из Часовни Последней Надежды в Восточных Чумных землях.','<Матеус подставляет свой карман для золота.>$B$BЧего стоишь, $R? Наша сделка уже завершена, я больше тебе ничего не дам.','<Матеус зевает>$B$BЕсли у тебя в карманах ветер, исчезни, насекомое.','Вернитесь к Матеусу Обрушивающему Гнев в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теневая защита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это гениальное изобретение! Также как и Ледяная защита, Теневая защита основана на использовании тонкой пленки защитной магии на элементах экипировки. Есть еще кое-что, что роднит ее с Ледяной защитой – ЦЕНА!$B$BНу что, $gготов:готова; выложить кругленькую сумму?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заплатите 10 значков Алого ордена и 30 золотых Матеусу Обрушивающему Гнев из Часовни Последней Надежды в Восточных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Матеус подставляет свой карман для золота.>$B$BЧего стоишь, $R? Наша сделка уже завершена, я больше тебе ничего не дам.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Матеус зевает>$B$BЕсли у тебя в карманах ветер, исчезни, насекомое.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Матеусу Обрушивающему Гнев в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9214,'Оружие Призрачной Сосны','$C, я хочу, чтобы ты $Gперебил:перебила; как можно больше троллей Призрачной Сосны. Нам нужно как следует сократить их численность, прежде чем заняться Смертхольмом. И раз уж ты за это $Gвзялся:взялась;, то давай-ка убьем двух зайцев одним выстрелом. Принеси мне их оружие – чего добру пропадать? А нам в борьбе против Плети оно может очень даже пригодиться.$B$BПрогуляйся вволю по их лагерям на востоке в Зеб\'Теле и на юге в Зеб\'Нове.','Вернитесь к капитану Гелиосу в Анклав Странников, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие Призрачной Сосны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, я хочу, чтобы ты $Gперебил:перебила; как можно больше троллей Призрачной Сосны. Нам нужно как следует сократить их численность, прежде чем заняться Смертхольмом. И раз уж ты за это $Gвзялся:взялась;, то давай-ка убьем двух зайцев одним выстрелом. Принеси мне их оружие – чего добру пропадать? А нам в борьбе против Плети оно может очень даже пригодиться.$B$BПрогуляйся вволю по их лагерям на востоке в Зеб\'Теле и на юге в Зеб\'Нове.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гелиосу в Анклав Странников, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9215,'Награда за голову Келгаша!','РАЗЫСКИВАЕТСЯ: Капитану Гелиосу нужна голова Кел\'гаша Коварного, предводителя троллей племени Призрачной Сосны. Никаких полумер. Известно, что Кел\'гаш скрывается где-то на юге, в Зеб\'Нове.$B$B$B$BНАГРАДА: Будет, но никаких авансов!','Чем так воняет?','Вернитесь к капитану Гелиосу в Анклав Странников, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда за голову Келгаша!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','РАЗЫСКИВАЕТСЯ: Капитану Гелиосу нужна голова Кел\'гаша Коварного, предводителя троллей племени Призрачной Сосны. Никаких полумер. Известно, что Кел\'гаш скрывается где-то на юге, в Зеб\'Нове.$B$B$B$BНАГРАДА: Будет, но никаких авансов!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем так воняет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гелиосу в Анклав Странников, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9216,'Гниющие сердца','Я слыхала, будто тролли Амани пожирают сердца врагов, чтобы обрести их силу. Что-то в этом должно быть, $n. При должной обработке сердца нежити могут давать мощные эликсиры.$B$BПоохоться на зомби, что бродят по Тропе Мертвых, и принеси мне их сердца. А я покажу тебе, как мы сможем улучшить твои физические способности для борьбы с нежитью.','Принесите 10 гниющих сердец магистру Аминель в Транквиллион.','Вернитесь к магистру Аминель в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гниющие сердца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слыхала, будто тролли Амани пожирают сердца врагов, чтобы обрести их силу. Что-то в этом должно быть, $n. При должной обработке сердца нежити могут давать мощные эликсиры.$B$BПоохоться на зомби, что бродят по Тропе Мертвых, и принеси мне их сердца. А я покажу тебе, как мы сможем улучшить твои физические способности для борьбы с нежитью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 гниющих сердец магистру Аминель в Транквиллион.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Аминель в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9217,'Больше гниющих сердец','Это даст вам большую силу против Бича. $B$BПринеси больше сердец, если найдешь их, $N.','Ты $Gпринес:принесла; еще сердца упырей? Я могу использовать столько, сколько ты сможешь собрать, $N.','Вернитесь к магистру Аминель в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше гниющих сердец',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это даст вам большую силу против Бича. $B$BПринеси больше сердец, если найдешь их, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; еще сердца упырей? Я могу использовать столько, сколько ты сможешь собрать, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Аминель в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9218,'Позвоночный порошок','Темная энергия, которая струится в телах восставших мертвецов, накапливается в первую очередь в их позвоночниках. Я разработала метод перегонки этой энергии в зелье, которое резко увеличивает наши магические способности при борьбе с нежитью.$B$BПринеси мне позвоночного порошка, и я с радостью дам тебе этого зелья. Скелетов ты найдешь в избытке на Тропе Мертвых к западу отсюда.','Принесите 10 порций позвоночного порошка магистру Аминель в Транквиллион.','Вернитесь к магистру Аминель в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Позвоночный порошок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Темная энергия, которая струится в телах восставших мертвецов, накапливается в первую очередь в их позвоночниках. Я разработала метод перегонки этой энергии в зелье, которое резко увеличивает наши магические способности при борьбе с нежитью.$B$BПринеси мне позвоночного порошка, и я с радостью дам тебе этого зелья. Скелетов ты найдешь в избытке на Тропе Мертвых к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 порций позвоночного порошка магистру Аминель в Транквиллион.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Аминель в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9219,'Больше позвоночного порошка','Эта пыль так же сильна, как и всегда, $N. Продолжайте приносить ее мне, если вам нужно усилить свои магические силы против Плети.','Вы раздобыли еще спинальной пыли? Я могу использовать столько, сколько ты мне принесешь.','Вернитесь к магистру Аминель в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше позвоночного порошка',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эта пыль так же сильна, как и всегда, $N. Продолжайте приносить ее мне, если вам нужно усилить свои магические силы против Плети.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы раздобыли еще спинальной пыли? Я могу использовать столько, сколько ты мне принесешь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Аминель в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9220,'Война со Смертхольмом','Если хочешь помочь нам, то лучше это сделать здесь и сейчас.$B$BВосстановив святилище Солнца, мы подняли стяг сопротивления перед оплотом нашего врага – Смертхольмом. $B$BСтупай же и одолей орды нежити, что кишат в мерзостной крепости Плети.','Убейте 5 очей Дар\'Кхана, 6 нерубов-центурионов и 6 плакальщиц в Смертхольме. Возвращайтесь к магистру Идонису в святилище Солнца в Призрачных землях.','Ну, дело сделано? Дар\'Кхан убит?','Вернитесь к магистру Идонису в Святилище Солнца, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война со Смертхольмом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хочешь помочь нам, то лучше это сделать здесь и сейчас.$B$BВосстановив святилище Солнца, мы подняли стяг сопротивления перед оплотом нашего врага – Смертхольмом. $B$BСтупай же и одолей орды нежити, что кишат в мерзостной крепости Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 очей Дар\'Кхана, 6 нерубов-центурионов и 6 плакальщиц в Смертхольме. Возвращайтесь к магистру Идонису в святилище Солнца в Призрачных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, дело сделано? Дар\'Кхан убит?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Идонису в Святилище Солнца, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9221,'Превосходное боевое снаряжениее – Друг Рассвета','Приветствую тебя, $gбрат:сестра;. Желаешь ли обменять значки Серебряного Рассвета или значки Алого ордена на боевое снаряжение?$B$BСразу предупреждаю, легендарное снаряжение очень дорого даже для друзей Рассвета. Рекомендую для начала заработать полное доверие Серебряного Рассвета!','За 30 знаков Рассвета и 30 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.','Добрый день, $N. Было очень приятно иметь дело с тобой.','Выбирай внимательно. Без возврата.','Вернитесь к интенданту Миранде Бричлок в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Превосходное боевое снаряжениее – Друг Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $gбрат:сестра;. Желаешь ли обменять значки Серебряного Рассвета или значки Алого ордена на боевое снаряжение?$B$BСразу предупреждаю, легендарное снаряжение очень дорого даже для друзей Рассвета. Рекомендую для начала заработать полное доверие Серебряного Рассвета!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','За 30 знаков Рассвета и 30 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добрый день, $N. Было очень приятно иметь дело с тобой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выбирай внимательно. Без возврата.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Миранде Бричлок в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9222,'Легендарное боевое снаряжение – Друг Рассвета','Приветствую тебя, $gбрат:сестра;. Желаешь ли обменять значки Серебряного Рассвета или значки Алого ордена на боевое снаряжение?$B$BСразу предупреждаю, легендарное снаряжение очень дорого даже для друзей Рассвета. Рекомендую для начала заработать полное доверие Серебряного Рассвета!','За 110 знаков Рассвета и 110 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.','Добрый день, $N. Было очень приятно иметь дело с тобой.','Выбирай внимательно. Без возврата.','Вернитесь к интенданту Миранде Бричлок в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легендарное боевое снаряжение – Друг Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $gбрат:сестра;. Желаешь ли обменять значки Серебряного Рассвета или значки Алого ордена на боевое снаряжение?$B$BСразу предупреждаю, легендарное снаряжение очень дорого даже для друзей Рассвета. Рекомендую для начала заработать полное доверие Серебряного Рассвета!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','За 110 знаков Рассвета и 110 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добрый день, $N. Было очень приятно иметь дело с тобой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выбирай внимательно. Без возврата.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Миранде Бричлок в Часовню Последней Надежды