INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9228,'Легендарное боевое снаряжение – Восторг Рассвета','Приветствую тебя, $gбрат:сестра;. Желаешь ли обменять значки Серебряного Рассвета или значки Алого ордена на боевое снаряжение?$B$BВсякий, кого превозносят в Серебряном Рассвете, получает невероятные скидки на приобретение товаров! Скорее же воспользуйся своим преимуществом!','За 27 знаков Рассвета и 27 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.','Добрый день, $N. Было очень приятно иметь дело с тобой.','Выбирай внимательно. Без возврата.','Вернитесь к интенданту Миранде Бричлок в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Легендарное боевое снаряжение – Восторг Рассвета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $gбрат:сестра;. Желаешь ли обменять значки Серебряного Рассвета или значки Алого ордена на боевое снаряжение?$B$BВсякий, кого превозносят в Серебряном Рассвете, получает невероятные скидки на приобретение товаров! Скорее же воспользуйся своим преимуществом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','За 27 знаков Рассвета и 27 значков Алого ордена вы можете выбрать себе предмет из сокровищницы Серебряного Рассвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добрый день, $N. Было очень приятно иметь дело с тобой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Выбирай внимательно. Без возврата.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Миранде Бричлок в Часовню Последней Надежды, что в Вост