INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9229,'Кольцо Судьбы Рамаладни','Рамаладни был воином Братства и учеником верховного лорда Могрейна еще до возникновения Рассвета. Когда до него дошла весть о гибели Могрейна, гнев и ярость овладели его сердцем.$B$BПойми, $n, тот, кто позволяет гневу и жажде мести овладеть собой, теряет душу и разум. Именно это и произошло с Рамаладни, духом мести, вошедшим в Наксрамас, чтобы осуществить возмездие, и более не вернувшимся.$B$BОтправляйся в Наксрамас и найди то, что было некогда Рамаладни.','Идите в Наксрамас и найдите кольцо Судьбы Рамаладни.','Это его кольцо! Но оно разрушается. Никаких других доказательств о Рамаладне не было найдено?$B$BЭто не сулит ничем хорошим для Рамаладни. Однако, кольцо... может быть спасено.','Есть новости о Рамаладни?','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо Судьбы Рамаладни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рамаладни был воином Братства и учеником верховного лорда Могрейна еще до возникновения Рассвета. Когда до него дошла весть о гибели Могрейна, гнев и ярость овладели его сердцем.$B$BПойми, $n, тот, кто позволяет гневу и жажде мести овладеть собой, теряет душу и разум. Именно это и произошло с Рамаладни, духом мести, вошедшим в Наксрамас, чтобы осуществить возмездие, и более не вернувшимся.$B$BОтправляйся в Наксрамас и найди то, что было некогда Рамаладни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в Наксрамас и найдите кольцо Судьбы Рамаладни.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это его кольцо! Но оно разрушается. Никаких других доказательств о Рамаладне не было найдено?$B$BЭто не сулит ничем хорошим для Рамаладни. Однако, кольцо... может быть спасено.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть новости о Рамаладни?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9230,'Ледяная хватка Рамаладни','Починить кольцо будет нелегко, $n. Видишь ли, оно было сделано из рун, которые можно найти только в сооружениях Плети – таких как Наксрамас. Мне также потребуются дополнительные материалы, однако основное затруднение представляют именно морозные руны. Принеси мне материалы, и я восстановлю кольцо в первозданном виде.','Принесите 1 морозную руну, 1 синий сапфир и 1 арканитовый слиток Корфаксу в Часовню Последней Надежды в Восточные Чумные земли.','Как и было обещано, вот твое кольцо.','Морозные руны можно найти в Наксрамасе.','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ледяная хватка Рамаладни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Починить кольцо будет нелегко, $n. Видишь ли, оно было сделано из рун, которые можно найти только в сооружениях Плети – таких как Наксрамас. Мне также потребуются дополнительные материалы, однако основное затруднение представляют именно морозные руны. Принеси мне материалы, и я восстановлю кольцо в первозданном виде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 морозную руну, 1 синий сапфир и 1 арканитовый слиток Корфаксу в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как и было обещано, вот твое кольцо.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Морозные руны можно найти в Наксрамасе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корфаксу, Воителю Света, в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9231,'reuse') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','reuse',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9232,'Не разгуляешься...','Ты, похоже, спишь и видишь себя героем Рассвета? Я видел, как летели головы лучших солдат под натиском шайки сброда Кел\'Тузада. Не понимаю, как такую бестолочь, как ты, можно вообще допускать в Наксрамас?$B$B*Вильгельм вздыхает*$B$BУвы, выбора у меня нет... попытаюсь хотя бы помочь.$B$BОмарион оставил мне всего один рецепт. Не разгуляешься... Я могу сделать несколько вариантов штанов – только принеси мне материалы.','Принесите 2 морозных руны, 2 субстанции Воды, 2 синих сапфира и 30 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли.','<Вильгельм вытирает пот со лба.>$B$BЭто была тяжелая работа! Наслаждайся этими поножами, $C. Теперь, ты умрешь в чистых поножах.','Ты ведь не $Gвстретил:встретила; Омариона?','Вернитесь к ремесленнику Вильгельму в Восточную башню, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не разгуляешься...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты, похоже, спишь и видишь себя героем Рассвета? Я видел, как летели головы лучших солдат под натиском шайки сброда Кел\'Тузада. Не понимаю, как такую бестолочь, как ты, можно вообще допускать в Наксрамас?$B$B*Вильгельм вздыхает*$B$BУвы, выбора у меня нет... попытаюсь хотя бы помочь.$B$BОмарион оставил мне всего один рецепт. Не разгуляешься... Я могу сделать несколько вариантов штанов – только принеси мне материалы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 2 морозных руны, 2 субстанции Воды, 2 синих сапфира и 30 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вильгельм вытирает пот со лба.>$B$BЭто была тяжелая работа! Наслаждайся этими поножами, $C. Теперь, ты умрешь в чистых поножах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты ведь не $Gвстретил:встретила; Омариона?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ремесленнику Вильгельму в Восточную башню, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9233,'Руководство Омариона','Вильгельм!$B$BЕсли ты читаешь эти строки, то мечта твоя сбылась: я окочурился. Знай, что и на смертном одре я думал только о том, сколь негодный ремесленник из тебя вышел. К сожалению, податель сего вполне может отобрать у тебя звание худшего мастера.$B$BЧто касается настоящего руководства, в нем собраны все мои рецепты. Сделай для подателя сего все, что он попросит. Не сомневаюсь впрочем, что сдерешь ты втридорога, ибо канальей ты был, канальей и остался.$B$BС искренним презрением,$B$BОмарион.','Отнесите руководство Омариона ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли.','Омарион и я – были, как не разлей вода. $B$BВо всяком случае, это безусловно открывает новые возможности, $N. Теперь я в состоянии изготовить больше деталей – за не большую плату и расходных материалов конечно.','Это и в самом деле то, что я думаю?$B$B<У Вильгельма явно дрожат руки>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руководство Омариона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вильгельм!$B$BЕсли ты читаешь эти строки, то мечта твоя сбылась: я окочурился. Знай, что и на смертном одре я думал только о том, сколь негодный ремесленник из тебя вышел. К сожалению, податель сего вполне может отобрать у тебя звание худшего мастера.$B$BЧто касается настоящего руководства, в нем собраны все мои рецепты. Сделай для подателя сего все, что он попросит. Не сомневаюсь впрочем, что сдерешь ты втридорога, ибо канальей ты был, канальей и остался.$B$BС искренним презрением,$B$BОмарион.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите руководство Омариона ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Омарион и я – были, как не разлей вода. $B$BВо всяком случае, это безусловно открывает новые возможности, $N. Теперь я в состоянии изготовить больше деталей – за не большую плату и расходных материалов конечно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это и в самом деле то, что я думаю?$B$B<У Вильгельма явно дрожат руки>',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9234,'Рукавицы ледяной погибели','Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать рукавицы ледяной погибели. От тебя требуются лишь материалы и скромная плата за работу.','Принесите 5 морозных рун, 12 ториевых слитков, 2 арканитовых слитка, 2 субстанции Воды и 200 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли.','Вот твой заказ, $N. Как и было обещано!','Ты $Gпринес:принесла; мне материалы?','Вернитесь к ремесленнику Вильгельму в Восточную башню, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рукавицы ледяной погибели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать рукавицы ледяной погибели. От тебя требуются лишь материалы и скромная плата за работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 морозных рун, 12 ториевых слитков, 2 арканитовых слитка, 2 субстанции Воды и 200 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот твой заказ, $N. Как и было обещано!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне материалы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ремесленнику Вильгельму в Восточную башню, что в Восточных Чумных землях.',`completedtext_loc8`);
