INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9236,'Кираса ледяной погибели','Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать кирасу ледяной погибели. От тебя требуются лишь материалы и скромная плата за работу.','Принесите 8 морозных рун, 16 ториевых слитков, 2 арканитовых слитка, 4 субстанции Воды и 300 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли. Для выполнения задания вам также необходимо пользоваться полным доверием в Серебряном Рассвете.','Вот твой заказ, $N. Как и было обещано!','Ты $Gпринес:принесла; мне материалы?','Вернитесь к ремесленнику Вильгельму в Восточную башню, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кираса ледяной погибели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря тебе и Омариону – да будет земля ему пухом – я могу создать кирасу ледяной погибели. От тебя требуются лишь материалы и скромная плата за работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 морозных рун, 16 ториевых слитков, 2 арканитовых слитка, 4 субстанции Воды и 300 золотых ремесленнику Вильгельму в Часовню Последней Надежды в Восточные Чумные земли. Для выполнения задания вам также необходимо пользоваться полным доверием в Серебряном Рассвете.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот твой заказ, $N. Как и было обещано!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; мне материалы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ремесленнику Вильгельму в Восточную башню, что в Восточных Чумных землях.',`compl