INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9247,'Зов Хранителя','Ответив на зов, мы будем у тебя в долгу, $N. Серебряный Рассвет уверен, что благодаря твоему яркому примеру другие получат прекрасное представление о том, как отбросить вторжение Плети!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Хранителя',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ответив на зов, мы будем у тебя в долгу, $N. Серебряный Рассвет уверен, что благодаря твоему яркому примеру другие получат прекрасное представление о том, как отбросить вторжение Плети!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9248,'Скромный подарок','Ишну-ала, |3-6($r). Покажи мне доказательство кончины лорда Совета Бездны и получишь в награду предмет, который поможет тебе справиться с киражи.','Принесите 1 скипетр Бездны Аурели Золотой Лист из Крепости Кенария в Силитусе. Кроме того, вы должны добиться уважительного отношения Круга Кенария.','Андэ’торас-эсил. На моем родном языке, это означает: "Да исчезнут ваши неприятности". $B$BГордо носи это кольцо, $N.','Фанду-дат-белор? Ой, простите меня, $N. Не узнал. У тебя есть скипетр?','Вернитесь к Аурели Золотому Листу в Крепость Кенария, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скромный подарок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ишну-ала, |3-6($r). Покажи мне доказательство кончины лорда Совета Бездны и получишь в награду предмет, который поможет тебе справиться с киражи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 1 скипетр Бездны Аурели Золотой Лист из Крепости Кенария в Силитусе. Кроме того, вы должны добиться уважительного отношения Круга Кенария.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Андэ’торас-эсил. На моем родном языке, это означает: "Да исчезнут ваши неприятности". $B$BГордо носи это кольцо, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Фанду-дат-белор? Ой, простите меня, $N. Не узнал. У тебя есть скипетр?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аурели Золотому Листу в Крепость Кенария, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9249,'40 купонов – пульт управления паровым танком','Да найдется место для твоих клинков в чьем-нибудь сердце. $B$BВ прямом смысле.','Налетай, торопись, выбирай себе приз! У кого есть купоны ярмарки Новолуния – подходите и обменяйте их на диковины волшебного свойства и исключительного качества! Ни орк, ни дворф не уйдет без призов!','Вернитесь к Гелвасу Углешлюзу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','40 купонов – пульт управления паровым танком',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да найдется место для твоих клинков в чьем-нибудь сердце. $B$BВ прямом смысле.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Налетай, торопись, выбирай себе приз! У кого есть купоны ярмарки Новолуния – подходите и обменяйте их на диковины волшебного свойства и исключительного качества! Ни орк, ни дворф не уйдет без призов!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гелвасу Углешлюзу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9250,'Основа Атиеша','Основа готова, и Атиеш собран почти полностью. Не хватает лишь набалдашника и основания. Да, и осталась небольшая проблемка – посох по-прежнему служит проводником зла Сарагаса в мир.$b$bНайди того, кто поможет тебе отыскать недостающие части, а заодно изгнать из посоха злого духа.','Найдите того, кто поможет отыскать недостающие части посоха и изгнать из него злого духа.','Архимаги погибли. $B$BНе стоит их оплакивать, $N. Этому суждено было случиться. Так же, как и то, что ты сейчас держишь посох Стража...','Настало время, $Gсмертный:смертная;.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Основа Атиеша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Основа готова, и Атиеш собран почти полностью. Не хватает лишь набалдашника и основания. Да, и осталась небольшая проблемка – посох по-прежнему служит проводником зла Сарагаса в мир.$b$bНайди того, кто поможет тебе отыскать недостающие части, а заодно изгнать из посоха злого духа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите того, кто поможет отыскать недостающие части посоха и изгнать из него злого духа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Архимаги погибли. $B$BНе стоит их оплакивать, $N. Этому суждено было случиться. Так же, как и то, что ты сейчас держишь посох Стража...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Настало время, $Gсмертный:смертная;.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9251,'Ты удивляешься, почему до сих пор $gжив:жива;? Ведь в твоих руках предмет, являющий собой средоточие зла. Ответ неочевиден, $n. Я делаю лишь то, что должно.$b$bКел\'Тузад сидит на троне Наксрамаса и вынашивает коварные планы... Он ищет то, что у тебя в руках, а у него в руках то, что ищешь ты.$b$bЧто же до острия посоха, то когда дворф Бранн Бронзобород отправился в Ан\'Кираж, оно было у него. Этого дворфа более нет в Ан\'Кираже, но основание Атиеша все еще там.$b$bЕсли тебе удастся отыскать оставшиеся части посоха, принеси их мне.','Это существо... не от мира сего.','В своем нынешнем виде, посох очень опасен в руках смертного.','Вернитесь к Анахроносу в Пещеры Времени, что в Танарисе.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты удивляешься, почему до сих пор $gжив:жива;? Ведь в твоих руках предмет, являющий собой средоточие зла. Ответ неочевиден, $n. Я делаю лишь то, что должно.$b$bКел\'Тузад сидит на троне Наксрамаса и вынашивает коварные планы... Он ищет то, что у тебя в руках, а у него в руках то, что ищешь ты.$b$bЧто же до острия посоха, то когда дворф Бранн Бронзобород отправился в Ан\'Кираж, оно было у него. Этого дворфа более нет в Ан\'Кираже, но основание Атиеша все еще там.$b$bЕсли тебе удастся отыскать оставшиеся части посоха, принеси их мне.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это существо... не от мира сего.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','В своем нынешнем виде, посох очень опасен в руках смертного.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахроносу в Пещеры Времени, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9252,'Оборона деревни Легкий Ветерок','Спасибо тебе большое, $N. Работа у нас неблагодарная, но твоими стараниями она стала чуть-чуть полегче.','Мы победим, $N.','Вернитесь к следопыту Сарийне в деревню Легкий Ветерок, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона деревни Легкий Ветерок',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе большое, $N. Работа у нас неблагодарная, но твоими стараниями она стала чуть-чуть полегче.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы победим, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к следопыту Сарийне в деревню Легкий Ветерок, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9253,'Хранитель рун Дериан') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранитель рун Дериан',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9254,'Упрямая ученица','Очень приятно, что моя бывшая наставница обо мне не забывает. Как жаль, что она давно утратила веру в мой успех!$B$BНе пытайся уговорить меня вернуться к ней, не трать времени зря. Лучше помоги мне в исследованиях либо уходи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упрямая ученица',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень приятно, что моя бывшая наставница обо мне не забывает. Как жаль, что она давно утратила веру в мой успех!$B$BНе пытайся уговорить меня вернуться к ней, не трать времени зря. Лучше помоги мне в исследованиях либо уходи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (9255,'Исследовательские записи','Конечно, итоги моих исследований удручающи, но все же отрицательный результат – тоже результат. Прошу тебя, отнеси эти записи магистру Ландре Рассветной Страннице в деревню Легкий Ветерок, к западу отсюда.','Эти записи... шокируют. Если все это правда, то урон, нанесенный земле Тропы Мертвых, необратим!$B$BЯ немедленно сообщу об этом великому магистру! Тем больше причин нашему народу оставить этот мир и искать свою истинную судьбу в Запределье!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследовательские записи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Конечно, итоги моих исследований удручающи, но все же отрицательный результат – тоже результат. Прошу тебя, отнеси эти записи магистру Ландре Рассветной Страннице в деревню Легкий Ветерок, к западу отсюда.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти записи... шокируют. Если все это правда, то урон, нанесенный земле Тропы Мертвых, необратим!$B$BЯ немедленно сообщу об этом великому магистру! Тем больше причин нашему народу оставить этот мир и искать свою истинную судьбу в Запределье!',`offerrewardtext_loc8`);
