INSERT INTO `locales_quest` (`id`,`details_loc8`,`completedtext_loc8`) VALUES (9257,'Последнее задание будет самым трудным. Ты уже $gодолел:одолела; прихвостня древнего бога и Короля-лича, теперь же придется бросить вызов правой руке Саргераса.$b$bОтнеси посох в Стратхольм, к освященной земле, где пали величайшие рыцари Лордерона. Помести оскверененный посох на священную землю и готовься к схватке с неодолимой силой... Одержи верх над демоном, в чьей власти находится посох, и возвращайся ко мне.','Вернитесь к Анахроносу в Пещеры Времени, что в Танарисе.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последнее задание будет самым трудным. Ты уже $gодолел:одолела; прихвостня древнего бога и Короля-лича, теперь же придется бросить вызов правой руке Саргераса.$b$bОтнеси посох в Стратхольм, к освященной земле, где пали величайшие рыцари Лордерона. Помести оскверененный посох на священную землю и готовься к схватке с неодолимой силой... Одержи верх над демоном, в чьей власти находится посох, и возвращайся ко мне.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анахроносу в Пещеры Времени, что в Танарисе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9258,'Выжженная роща') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выжженная роща',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9259,'Предатель Кровавого Паруса','Давай почтим минутой молчания наших павших товарищей, $N. $B$B<Предатель Кровавого Паруса ухмыляется тебе и подмигивает.>$B$BБыть предателем - это одно, убивать собственные деньги... это было бы просто отвратительно, глаз!','Этот паршивый пес, Ревилгаз, предложил помиловать любого бывшего кровопийцу, готового наброситься на своего капитана! Этот трюмный молокосос попросил меня уйти от моих старых товарищей и принести их банданы в качестве доказательства.$B$BУ меня нет желания это делать, и я не стану просить вас об этом. Принеси мне немного шелковой ткани и красной краски, и я сделаю подходящие копии. Я скажу барону, что ты $Gпошел:пошла; перебежчиком, но будь $Gосторожен:осторожна;... кровавым парусам это не понравится!','Вернитесь к предателю шайки Кровавого Паруса в Тернистую долину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предатель Кровавого Паруса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Давай почтим минутой молчания наших павших товарищей, $N. $B$B<Предатель Кровавого Паруса ухмыляется тебе и подмигивает.>$B$BБыть предателем - это одно, убивать собственные деньги... это было бы просто отвратительно, глаз!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Этот паршивый пес, Ревилгаз, предложил помиловать любого бывшего кровопийцу, готового наброситься на своего капитана! Этот трюмный молокосос попросил меня уйти от моих старых товарищей и принести их банданы в качестве доказательства.$B$BУ меня нет желания это делать, и я не стану просить вас об этом. Принеси мне немного шелковой ткани и красной краски, и я сделаю подходящие копии. Я скажу барону, что ты $Gпошел:пошла; перебежчиком, но будь $Gосторожен:осторожна;... кровавым парусам это не понравится!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предателю шайки Кровавого Паруса в Тернистую долину.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9260,'Что делает Плеть в Штормграде?','Войска Короля-лича стали лагерем у самых наших дверей. Мы не можем оставаться в бездействии! Выступишь ли ты на защиту Штормграда против этих проклятых захватчиков?$B$BТам, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху. Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно. Пока ты занимаешься этим, уменьши количество этих искажений природы, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!','Соберите три тусклых Некротических камня Плети, которые носит при себе нежить собравшаяся у Штормграда, и исследуйте светящиеся рунические круги вблизи лагеря Плети.','Хмм. Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то. Я содрогаюсь при мысли о том, с каким извращенным разумом осуществляется связь посредством подобной магии. Тем не менее тебе удалось остаться в живых и в здравом рассудке. Серебряный Рассвет ценит твою службу.','Расследование уже завершено? Нет? Тогда за дело!','Исследуйте круг','Вернитесь к лейтенанту Оррину на Аллею Героев, что в Штормграде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что делает Плеть в Штормграде?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войска Короля-лича стали лагерем у самых наших дверей. Мы не можем оставаться в бездействии! Выступишь ли ты на защиту Штормграда против этих проклятых захватчиков?$B$BТам, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху. Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно. Пока ты занимаешься этим, уменьши количество этих искажений природы, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите три тусклых Некротических камня Плети, которые носит при себе нежить собравшаяся у Штормграда, и исследуйте светящиеся рунические круги вблизи лагеря Плети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм. Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то. Я содрогаюсь при мысли о том, с каким извращенным разумом осуществляется связь посредством подобной магии. Тем не менее тебе удалось остаться в живых и в здравом рассудке. Серебряный Рассвет ценит твою службу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Расследование уже завершено? Нет? Тогда за дело!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Исследуйте круг',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Оррину на Аллею Героев, что в Штормграде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9261,'Что делает Плеть в Стальгорне?','Войска Короля-лича стали лагерем у самых наших дверей. Мы не можем оставаться в бездействии! Выступишь ли ты на защиту Стальгорна против этих проклятых захватчиков?$B$BТам, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху. Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно. Пока ты занимаешься этим, уменьши количество этих искажений природы, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!','Соберите три тусклых Некротических камня Плети, которые носит при себе нежить, откружившая Стальгорн, и исследуйте светящиеся рунические круги вблизи лагеря Плети.','Исследуйте круги.','Вернитесь к лейтенанту Невиллу ко Вратам Стальгорна, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что делает Плеть в Стальгорне?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войска Короля-лича стали лагерем у самых наших дверей. Мы не можем оставаться в бездействии! Выступишь ли ты на защиту Стальгорна против этих проклятых захватчиков?$B$BТам, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху. Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно. Пока ты занимаешься этим, уменьши количество этих искажений природы, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите три тусклых Некротических камня Плети, которые носит при себе нежить, откружившая Стальгорн, и исследуйте светящиеся рунические круги вблизи лагеря Плети.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Исследуйте круги.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Невиллу ко Вратам Стальгорна, что в Дун Мороге.',`completedtext_loc8`);
