INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9283,'Помощь выжившим','Мы снова зарядили исцеляющие кристаллы, но есть и другие способы помочь раненым. Все дренеи наделены даром наару – возможностью лечить. Воспользуйся этой способностью и исцели одного из уцелевших в катастрофе.$b$bБольшая часть раненых находится на западе и на северо-западе отсюда, хотя в результате крушения нас разбросало по всей долине.$b$bВсе выжившие дренеи подверглись воздействию радиоактивных кристаллов, поэтому их легко узнать по красному свечению.$b$bСпаси их, $n.','Мы выживем... С твоей помощью.','Вернитесь к Зальдууну на Место Крушения, что в долине Аммен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь выжившим',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы снова зарядили исцеляющие кристаллы, но есть и другие способы помочь раненым. Все дренеи наделены даром наару – возможностью лечить. Воспользуйся этой способностью и исцели одного из уцелевших в катастрофе.$b$bБольшая часть раненых находится на западе и на северо-западе отсюда, хотя в результате крушения нас разбросало по всей долине.$b$bВсе выжившие дренеи подверглись воздействию радиоактивных кристаллов, поэтому их легко узнать по красному свечению.$b$bСпаси их, $n.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы выживем... С твоей помощью.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зальдууну на Место Крушения, что в долине Аммен.',`completedtext_loc8`);
