INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9287,'Наставник паладинов','Я рад, что ты $gпожелал:пожелала; обратиться ко мне. В прошлом я занимался обучением молодых паладинов, только что вступивших в наш орден. Я снова принял на себя эту почетную обязанность. Говорят, ты стремишься к Свету. Это честь для меня – помочь тебе сделать первые шаги на этом пути.$b$bВот мой первый урок...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наставник паладинов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что ты $gпожелал:пожелала; обратиться ко мне. В прошлом я занимался обучением молодых паладинов, только что вступивших в наш орден. Я снова принял на себя эту почетную обязанность. Говорят, ты стремишься к Свету. Это честь для меня – помочь тебе сделать первые шаги на этом пути.$b$bВот мой первый урок...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9288,'Наставник охотников','Я рад, что вы пришли ко мне. В течение достаточно долгого времени я отвечал за обучение наших юных охотников, и я намерен продолжать этот новый мир. Я присматривал за тобой какое-то время, и для меня было бы честью помочь тебе научиться путям |1-3($C). $B$BНачнем?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наставник охотников',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что вы пришли ко мне. В течение достаточно долгого времени я отвечал за обучение наших юных охотников, и я намерен продолжать этот новый мир. Я присматривал за тобой какое-то время, и для меня было бы честью помочь тебе научиться путям |1-3($C). $B$BНачнем?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9289,'Наставник воинов','Хорошо, что ты ищешь моего наставника. На протяжении веков я учил молодых воинов |3-6($R), поэтому я могу знать кое-что о том, с чего тебе следует начинать. Я вижу в тебе задатки отличного воина, но только если ты внимательно будешь слушать то, чему я должен учить. $B$BТы $Gготов:готова; учиться, молодой |3-6($C)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наставник воинов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты ищешь моего наставника. На протяжении веков я учил молодых воинов |3-6($R), поэтому я могу знать кое-что о том, с чего тебе следует начинать. Я вижу в тебе задатки отличного воина, но только если ты внимательно будешь слушать то, чему я должен учить. $B$BТы $Gготов:готова; учиться, молодой |3-6($C)?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9290,'Наставник магов','Я рад, что ты $Gпришел:пришла; в поисках моих знаний. Нам нужно многое сделать, чтобы отточить твои магические способности. $B$BНа протяжении более ста лет я учил тайной, ледяной и огненной магии, и я могу чувствовать их так же сильно в этом мире. Хочешь, я поделюсь с тобой кое-чем из того, что знаю?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наставник магов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад, что ты $Gпришел:пришла; в поисках моих знаний. Нам нужно многое сделать, чтобы отточить твои магические способности. $B$BНа протяжении более ста лет я учил тайной, ледяной и огненной магии, и я могу чувствовать их так же сильно в этом мире. Хочешь, я поделюсь с тобой кое-чем из того, что знаю?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9291,'Наставник жрецов','То, что ты $Gпришел:пришла; ко мне в поисках мудрости, вселяет надежду в наше будущее. Хоть у меня и полно забот с нашими пострадавшими, все же я могу найти минутку для того, что бы помочь тебе в твоих первых шагах как $C. Путь света, является самым высоким из призваний, и я уверен, что ты более чем $Gготов:готова; взять его на себя. $B$BКогда почувствуешь, что $Gготов:готова; начать обучение, обратись ко мне еще раз.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наставник жрецов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что ты $Gпришел:пришла; ко мне в поисках мудрости, вселяет надежду в наше будущее. Хоть у меня и полно забот с нашими пострадавшими, все же я могу найти минутку для того, что бы помочь тебе в твоих первых шагах как $C. Путь света, является самым высоким из призваний, и я уверен, что ты более чем $Gготов:готова; взять его на себя. $B$BКогда почувствуешь, что $Gготов:готова; начать обучение, обратись ко мне еще раз.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9292,'Треснувший некротический кристалл','На трупе павшего поганища вы обнаруживаете треснутый кристалл, медленно пульсирующий некротической энергией.','Отнесите треснувший некротический кристалл лейтенанту Оррину, находящемуся за воротами Штормграда.','Хм, так это было на трупе одного из этих мерзостных поганищ?$B$BМы слышали о лагерях-некрополях, призванных Плетью. Я подозреваю, что они хотят создать такой лагерь в Штормграде. Хорошо что им это не удалось.','Тебе что-нибудь нужно?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Треснувший некротический кристалл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На трупе павшего поганища вы обнаруживаете треснутый кристалл, медленно пульсирующий некротической энергией.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите треснувший некротический кристалл лейтенанту Оррину, находящемуся за воротами Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм, так это было на трупе одного из этих мерзостных поганищ?$B$BМы слышали о лагерях-некрополях, призванных Плетью. Я подозреваю, что они хотят создать такой лагерь в Штормграде. Хорошо что им это не удалось.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе что-нибудь нужно?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9293,'То, что должно быть сделано...','Один из обломков кристаллов корабля упал в озеро неподалеку отсюда и заразил его радиацией. В результате многие растения и животные долины Аммен подверглись различным мутациям.$b$bУ меня есть идея, как излечить озеро, но сначала я должна заполучить образцы корнехлестов-мутантов и проанализировать их. Их можно найти на западе от полей Аммен.$b$bПоможешь мне, |3-6($c)?','Соберите 10 образцов корней корнехлестов и отнесите их ботанику Таэрикс на место крушения в долине Аммен.','Вернитесь к ботанику Таэрикс на Место Крушения, что в долине Аммен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','То, что должно быть сделано...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из обломков кристаллов корабля упал в озеро неподалеку отсюда и заразил его радиацией. В результате многие растения и животные долины Аммен подверглись различным мутациям.$b$bУ меня есть идея, как излечить озеро, но сначала я должна заполучить образцы корнехлестов-мутантов и проанализировать их. Их можно найти на западе от полей Аммен.$b$bПоможешь мне, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 образцов корней корнехлестов и отнесите их ботанику Таэрикс на место крушения в долине Аммен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ботанику Таэрикс на Место Крушения, что в долине Аммен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9294,'Исцеление озера','Если будет на то воля Света, этот состав сработает! Я хочу, чтобы ты $gобработал:обработала; им Серебристое озеро на юге. Надеюсь, нам удастся очистить воду от радиоактивного заражения.$b$bПодплыви поближе к кристаллу и вылей туда нейтрализующее вещество. Не беспокойся, ты не успеешь заразиться.','Чем скорее ты растворишь нейтрализующее вещество в озере, чем меньше местных зверей, приходящих на водопой, мутируют. Да и мы сами тоже!$b$BЖаль, что я не в силах помочь бедным тварям, уже пораженным радиацией. Ах, если бы уцелело оборудование из моей лаборатории!','Вернитесь к ботанику Таэрикс на Место Крушения, что в долине Аммен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исцеление озера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если будет на то воля Света, этот состав сработает! Я хочу, чтобы ты $gобработал:обработала; им Серебристое озеро на юге. Надеюсь, нам удастся очистить воду от радиоактивного заражения.$b$bПодплыви поближе к кристаллу и вылей туда нейтрализующее вещество. Не беспокойся, ты не успеешь заразиться.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем скорее ты растворишь нейтрализующее вещество в озере, чем меньше местных зверей, приходящих на водопой, мутируют. Да и мы сами тоже!$b$BЖаль, что я не в силах помочь бедным тварям, уже пораженным радиацией. Ах, если бы уцелело оборудование из моей лаборатории!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ботанику Таэрикс на Место Крушения, что в долине Аммен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9295,'Письмо с фронта','Какая трагедия. Спасибо, что $Gпринес:принесла; мне это. Я постараюсь найти адресата письма по его содержанию. С твоей помощью мы сможем наконец дать кому-то душевное спокойствие.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Письмо с фронта',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая трагедия. Спасибо, что $Gпринес:принесла; мне это. Я постараюсь найти адресата письма по его содержанию. С твоей помощью мы сможем наконец дать кому-то душевное спокойствие.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9296,'reuse','Камень испускает какую-то темную энергию. Надо отдать его КОМУ-НИБУДЬ.','Отдайте тусклый некротический камень КОМУ-НИБУДЬ.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','reuse',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Камень испускает какую-то темную энергию. Надо отдать его КОМУ-НИБУДЬ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте тусклый некротический камень КОМУ-НИБУДЬ.',`objectives_loc8`);
