INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9299,'Записка с фронта','Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.','Да? Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Записка с фронта',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Что у тебя там?',`requestitemstext_loc8`);
