INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9301,'Конверт с фронта','Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.','Да? Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конверт с фронта',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Что у тебя там?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9302,'Послание с фронта','Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.','Да? Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание с фронта',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Что у тебя там?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9303,'Прививка','Жаная должна починить излучатель, и ей нужны запчасти. Без нашей помощи ей не обойтись. Таэрикс приготовила особую прививку для совунов Совиных холмов, населяющих территорию, на которой особенно много обломков корабля.$b$bПостарайся подобраться поближе к незараженным совунам и воспользуйся кристаллом. К сожалению, остальных придется убить. Совуны живут в Совиной чаще и Совиных холмах на юго-востоке.','Сделайте прививку шести совунам Совиных холмов при помощи особого кристалла. Затем вернитесь к воздаятелю Алдару на место крушения в долине Аммен.','Чем быстрее мы очистим Совиные холмы, тем быстрее Жаная сможет взяться за работу.','Вернитесь к воздаятелю Алдару на Место Крушения, что в долине Аммен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прививка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жаная должна починить излучатель, и ей нужны запчасти. Без нашей помощи ей не обойтись. Таэрикс приготовила особую прививку для совунов Совиных холмов, населяющих территорию, на которой особенно много обломков корабля.$b$bПостарайся подобраться поближе к незараженным совунам и воспользуйся кристаллом. К сожалению, остальных придется убить. Совуны живут в Совиной чаще и Совиных холмах на юго-востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сделайте прививку шести совунам Совиных холмов при помощи особого кристалла. Затем вернитесь к воздаятелю Алдару на место крушения в долине Аммен.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем быстрее мы очистим Совиные холмы, тем быстрее Жаная сможет взяться за работу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Алдару на Место Крушения, что в долине Аммен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9304,'Документ с фронта','Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.','Да? Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Документ с фронта',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как трагично! Эти слова явно предназначены для той, кого любил этот солдат, но она так их и не прочла. Описанные события произошли много лет назад, я даже не знаю, жива ли та, кому адресовано письмо.\n\nИ все же надежда еще не потеряна. По именам и сведениям, указанным в письме, я могу узнать местонахождение семьи! Это потребует некоторых исследований, но библиотекарь в Штормграде должен мне услугу...\n\nСпасибо за доставку этого письма ко мне. Быть может, это поможет кому-нибудь обрести хоть немного душевного покоя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Что у тебя там?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9305,'Запасные части','Мы обнаружили среди обломков корабля поврежденный голографический передатчик. Если его починить, можно попытаться связаться с выжившими дренеями за пределами долины Аммен.$b$bДля ремонта нужны запчасти, которые можно вытащить из других обломков, валяющихся в округе, но их уже утащили местные совуны.$b$bОтправляйся на юг, в Совиную чащу и Совиные холмы, и найди запасные части.','Соберите 4 запчасти для передатчика и отнесите их технику Жанае на место крушения в долине Аммен.','Если мы соберем все детали, я смогу починить передатчик. Если повезет, нам даже найдется, с кем поговорить по нему.','Вернитесь к технику Жанае на Место Крушения, что в долине Аммен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запасные части',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы обнаружили среди обломков корабля поврежденный голографический передатчик. Если его починить, можно попытаться связаться с выжившими дренеями за пределами долины Аммен.$b$bДля ремонта нужны запчасти, которые можно вытащить из других обломков, валяющихся в округе, но их уже утащили местные совуны.$b$bОтправляйся на юг, в Совиную чащу и Совиные холмы, и найди запасные части.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 запчасти для передатчика и отнесите их технику Жанае на место крушения в долине Аммен.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если мы соберем все детали, я смогу починить передатчик. Если повезет, нам даже найдется, с кем поговорить по нему.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к технику Жанае на Место Крушения, что в долине Аммен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9306,'<DEPRECATED>Воздаятель Алдар','$n, воздаятелю Алдару нужна помощь. Необходимо разобраться с совунами, которые превратились в мутантов в результате крушения нашего корабля.$B$BАлдар стоит на южной стороне места крушения. Пожалуйста, поговори с ним как можно скорее.','Поговорите с воздаятелем Алдаром на месте крушения в долине Аммен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<DEPRECATED>Воздаятель Алдар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, воздаятелю Алдару нужна помощь. Необходимо разобраться с совунами, которые превратились в мутантов в результате крушения нашего корабля.$B$BАлдар стоит на южной стороне места крушения. Пожалуйста, поговори с ним как можно скорее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с воздаятелем Алдаром на месте крушения в долине Аммен.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9307,'<DEPRECATED>Сострадание','В Серебристое озеро рухнул обломок корабля и отравил его воды. В результате все кто, пьет из него воду, мутировали и сделались злобными и жестокими. Хуже всего мутировавшие совуны.$b$bСтупай в Совиную чащу и убей как можно больше этих жалких существ. Мы всего лишь хотим избавить бедняг от страданий, поэтому даже убивая, помни о милосердии.','Убейте 14 мутировавших совунов и вернитесь к поборнику Алдару на место крушения в долине Аммен.','Вернитесь к воздаятелю Алдару в Священную рощу, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<DEPRECATED>Сострадание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Серебристое озеро рухнул обломок корабля и отравил его воды. В результате все кто, пьет из него воду, мутировали и сделались злобными и жестокими. Хуже всего мутировавшие совуны.$b$bСтупай в Совиную чащу и убей как можно больше этих жалких существ. Мы всего лишь хотим избавить бедняг от страданий, поэтому даже убивая, помни о милосердии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 14 мутировавших совунов и вернитесь к поборнику Алдару на место крушения в долине Аммен.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Алдару в Священную рощу, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9308,'<DEPRECATED>Останки эльфов крови?','Вам кажется, что перед вами останки син\'дорай – эльфа крови. Судя по всему, он пал жертвой когтей нескольких мутировавших совунов.$b$bОбыскав тело, вы находите на шее медальон на цепочке. Может быть, он заинтересует воздаятеля Алдара?','Отнесите амулет эльфа крови воздаятелю Алдару на место крушения в долине Аммен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<DEPRECATED>Останки эльфов крови?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вам кажется, что перед вами останки син\'дорай – эльфа крови. Судя по всему, он пал жертвой когтей нескольких мутировавших совунов.$b$bОбыскав тело, вы находите на шее медальон на цепочке. Может быть, он заинтересует воздаятеля Алдара?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите амулет эльфа крови воздаятелю Алдару на место крушения в долине Аммен.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (9309,'Пропавший разведчик','У нас есть несколько сообщений о том, что на Хребте Теней творится что-то неладное.$b$bНичего хорошего в этом нет: мы ведь думали, что разведчики тщательно обследовали окрестности. Впрочем, один из них еще не вернулся.$b$bОтправляйся на юго-запад, на другую сторону Серебристого озера и найди Толаана. Узнай, что его задержало.','Помоги... Эльфы крови! Я... попал в засаду. Мне... недолго осталось.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший разведчик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас есть несколько сообщений о том, что на Хребте Теней творится что-то неладное.$b$bНичего хорошего в этом нет: мы ведь думали, что разведчики тщательно обследовали окрестности. Впрочем, один из них еще не вернулся.$b$bОтправляйся на юго-запад, на другую сторону Серебристого озера и найди Толаана. Узнай, что его задержало.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Помоги... Эльфы крови! Я... попал в засаду. Мне... недолго осталось.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9310,'Тусклый некротический кристалл','На трупе павшей твари вы находите кристалл, излучающий тусклую некротическую энергию.','Отнесите тусклый некротический кристалл лейтенанту Рукагу во внутренний двор Подгорода.','Это было у одной из тварей, напавших на город?\n\nМы слышали о лагерях-некрополях, призванных Плетью. Я подозреваю, что они хотят создать такой лагерь в Подгороде. Впредь мы должны быть бдительными..','Я могу чем-нибудь помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тусклый некротический кристалл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На трупе павшей твари вы находите кристалл, излучающий тусклую некротическую энергию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите тусклый некротический кристалл лейтенанту Рукагу во внутренний двор Подгорода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это было у одной из тварей, напавших на город?\n\nМы слышали о лагерях-некрополях, призванных Плетью. Я подозреваю, что они хотят создать такой лагерь в Подгороде. Впредь мы должны быть бдительными..',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я могу чем-нибудь помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9311,'Шпион эльфов крови','У меня есть план. Мы должны убить их главаря. Тогда, может быть, им придется отступить. В конце концов, наша задача – выиграть время на ремонт остатков корабля.$b$bУбей геодезиста, а потом расскажи обо всем воздаятелю Алдару – он должен быть в курсе.','Убейте геодезиста Кандресс и расскажите о случившемся воздаятелю Алдару на месте крушения в долине Аммен.','Значит, это правда... В долину Аммен пробрался отряд эльфов крови! Как они сумели нас найти?$b$bЯ немедленно пошлю кого-нибудь за Толааном.','Вернитесь к воздаятелю Алдару на Место Крушения, что в долине Аммен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шпион эльфов крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть план. Мы должны убить их главаря. Тогда, может быть, им придется отступить. В конце концов, наша задача – выиграть время на ремонт остатков корабля.$b$bУбей геодезиста, а потом расскажи обо всем воздаятелю Алдару – он должен быть в курсе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте геодезиста Кандресс и расскажите о случившемся воздаятелю Алдару на месте крушения в долине Аммен.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Значит, это правда... В долину Аммен пробрался отряд эльфов крови! Как они сумели нас найти?$b$bЯ немедленно пошлю кого-нибудь за Толааном.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Алдару на Место Крушения, что в долине Аммен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9312,'Излучатель','Пока ты $gбродил:бродила; по Хребту Теней, Жаная занималась голографическим излучателем. Тебе стоит поговорить с ней.','Поговорите с техником Жанаей на месте крушения в долине Аммен.','Получилось! Получилось! Кажется, я починила излучатель! Сейчас я активирую последний кристалл, и дело в шляпе.$b$bСмотри на излучатель, $n. Похоже, он заработал... Кто-то появляется!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Излучатель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gбродил:бродила; по Хребту Теней, Жаная занималась голографическим излучателем. Тебе стоит поговорить с ней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с техником Жанаей на месте крушения в долине Аммен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Получилось! Получилось! Кажется, я починила излучатель! Сейчас я активирую последний кристалл, и дело в шляпе.$b$bСмотри на излучатель, $n. Похоже, он заработал... Кто-то появляется!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9313,'На Лазурную заставу','Ради всего святого, $n, отправляйся на Лазурную заставу и поговори с Дувууном!$b$bС нашего островка есть узкая тропа на запад. Иди по ней, перейди через Хрустальную реку, и окажешься в другой части острова. Если идти дальше, не сходя с дороги, она приведет тебя на Лазурную заставу.$b$bМожет быть, они помогут нам и снабдят нас припасами? Остальные последуют за тобой, когда смогут.$b$bСпасибо, без тебя бы нам не справиться!','Поговорите с техником Дивуун на Лазурной заставе на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На Лазурную заставу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ради всего святого, $n, отправляйся на Лазурную заставу и поговори с Дувууном!$b$bС нашего островка есть узкая тропа на запад. Иди по ней, перейди через Хрустальную реку, и окажешься в другой части острова. Если идти дальше, не сходя с дороги, она приведет тебя на Лазурную заставу.$b$bМожет быть, они помогут нам и снабдят нас припасами? Остальные последуют за тобой, когда смогут.$b$bСпасибо, без тебя бы нам не справиться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с техником Дивуун на Лазурной заставе на острове Лазурной Дымки.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9314,'Вести с Лазурной заставы','$C! На меня напала пара зверей-мутантов и ранила меня в ногу.$b$bПосле того как нам удалось связаться с Жанаей, меня отправили из Лазурной заставы на разведку. Пожалуйста, поговори вместо меня c корчмарем Челланой. Ей нужно знать, скольких беженцев ждать в нашем поселении. Перейди Хрустальную реку и иди по дороге до самой Лазурной заставы.$b$bОбязательно скажи ей, что тебе нужно где-то остановиться.','Поговорите с корчмарем Челланой на Лазурной заставе на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вести с Лазурной заставы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C! На меня напала пара зверей-мутантов и ранила меня в ногу.$b$bПосле того как нам удалось связаться с Жанаей, меня отправили из Лазурной заставы на разведку. Пожалуйста, поговори вместо меня c корчмарем Челланой. Ей нужно знать, скольких беженцев ждать в нашем поселении. Перейди Хрустальную реку и иди по дороге до самой Лазурной заставы.$b$bОбязательно скажи ей, что тебе нужно где-то остановиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с корчмарем Челланой на Лазурной заставе на острове Лазурной Дымки.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9315,'Анок\'сутен','Убейте Анок\'сутен и возвращайтесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.','За время моего пребывания тут я много узнал о способах борьбы с Плетью. Их можно победить, но к победе придется продвигаться малыми шагами. Если принять во внимание то, что они пополняют свои ряды нашими погибшими соратниками, мы не имеем права на ошибку.\n\nНу, как твоя битва в Деревне Золотистой Дымки?','Вернитесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Анок\'сутен',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Анок\'сутен и возвращайтесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','За время моего пребывания тут я много узнал о способах борьбы с Плетью. Их можно победить, но к победе придется продвигаться малыми шагами. Если принять во внимание то, что они пополняют свои ряды нашими погибшими соратниками, мы не имеем права на ошибку.\n\nНу, как твоя битва в Деревне Золотистой Дымки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Вандрилу в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9316,'[TXT] Гоблины-варвары','*Брианна испытующе смотрит на вас.*$B$BЗначит, вы желаете поохотиться на гоблинов? Что же, если вы решили, то можете начать с варваров, что живут по соседству. А в знак доказательства вашей победы принесите мне их зубы.','Брианна Шнайдер с острова Дизайнера хочет 10 гоблинских зубов.','Вернитесь к Bri\'s Test Character на Остров Дизайнера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[TXT] Гоблины-варвары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Брианна испытующе смотрит на вас.*$B$BЗначит, вы желаете поохотиться на гоблинов? Что же, если вы решили, то можете начать с варваров, что живут по соседству. А в знак доказательства вашей победы принесите мне их зубы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Брианна Шнайдер с острова Дизайнера хочет 10 гоблинских зубов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Bri\'s Test Character на Остров Дизайнера.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9317,'Освященное точило','Вернитесь к интенданту из ордена Серебряного Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освященное точило',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту из ордена Серебряного Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9318,'Благословенное волшебное масло','Вернитесь к интенданту из ордена Серебряного Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословенное волшебное масло',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту из ордена Серебряного Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9319,'Свет в темных местах','Ты $Gдоказал:доказала;, что ты не совсем $Gбесполезный:бесполезная; $Gсмертный:смертная;.','Вы нашли свой путь через темноту?','Вернитесь к старейшине Служителей Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свет в темных местах',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gдоказал:доказала;, что ты не совсем $Gбесполезный:бесполезная; $Gсмертный:смертная;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы нашли свой путь через темноту?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Служителей Земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9320,'Гигантский флакон с зельем маны','Вернитесь к экипировщику из ордена Серебряного Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гигантский флакон с зельем маны',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к экипировщику из ордена Серебряного Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9321,'Гигантский флакон с лечебным зельем','Вернитесь к интенданту из ордена Серебряного Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гигантский флакон с лечебным зельем',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту из ордена Серебряного Рассвета.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9322,'Костры Калимдора','Твой дух излучает тепло костров Калимдора. Разве оно не бодрит? Возможно, когда сила покинет тебя, ты ощутишь это чувство.','Костры Калимдора горели ярко?','Вернитесь к хранителю праздничного пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Костры Калимдора',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твой дух излучает тепло костров Калимдора. Разве оно не бодрит? Возможно, когда сила покинет тебя, ты ощутишь это чувство.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Костры Калимдора горели ярко?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю праздничного пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9323,'Костры Восточных королевств','Огненный праздник распространился по всем землям, |3-6($c). Нет ни единого уголка, куда не проник бы жар этого празднества, а самые сильные огни пылают ярко-синим цветом. Найди их.$b$bОдин из них можно обнаружить к северу от Пика Черной горы. Другие размещаются в глубине территории Восточных Чумных земель возле полуразрушенного города, вдоль дороги, ведущей на утесы гористых Внутренних Земель, и на пути к Темный портал в Выжженных землях.$b$bВозвращайся, когда завершишь свое путешествие.','Посетите лагеря Праздника Огня, размещенные в Выжженных землях, Восточных Чумных землях, во Внутренних землях и Тлеющем ущелье, затем поговорите с хранителем праздничного пламени.','А вот и ты. Немного $Gуставший:уставшая;, $Gпыльный:пыльная;, но $Gпросветленный:просветленная;! Тепло эти костров объединяет нас всех, делая нас мудрее и сильнее.','Потребуется какое-то время, чтобы избавиться от нависшей над нами угрозы. Как далеко тебе удалось продвинуться, $N?','Вернитесь к хранителю праздничного пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Костры Восточных королевств',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огненный праздник распространился по всем землям, |3-6($c). Нет ни единого уголка, куда не проник бы жар этого празднества, а самые сильные огни пылают ярко-синим цветом. Найди их.$b$bОдин из них можно обнаружить к северу от Пика Черной горы. Другие размещаются в глубине территории Восточных Чумных земель возле полуразрушенного города, вдоль дороги, ведущей на утесы гористых Внутренних Земель, и на пути к Темный портал в Выжженных землях.$b$bВозвращайся, когда завершишь свое путешествие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посетите лагеря Праздника Огня, размещенные в Выжженных землях, Восточных Чумных землях, во Внутренних землях и Тлеющем ущелье, затем поговорите с хранителем праздничного пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А вот и ты. Немного $Gуставший:уставшая;, $Gпыльный:пыльная;, но $Gпросветленный:просветленная;! Тепло эти костров объединяет нас всех, делая нас мудрее и сильнее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Потребуется какое-то время, чтобы избавиться от нависшей над нами угрозы. Как далеко тебе удалось продвинуться, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю праздничного пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9324,'Похищение пламени Оргриммара','Это пламя, похищенное из сердца Оргриммара, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...','Верните Пламя Оргриммара хранителю мудрости Праздника.','Что это? Если я не ошибаюсь, это пламя добыто из самого сердца Оргриммара! Свирепая сила, наполняющая души орков и троллей, чувствуется в неистовом жаре этого огня. Какое чудесное добавление к коллекции! И сколь велика твоя отвага, позволившая тебе пробраться в самое логово врага, дабы заполучить священное пламя!$B$BИнтересно, какая сила таится в других городах?. .','Ты поистине светишься, |3-6($R). Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищение пламени Оргриммара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это пламя, похищенное из сердца Оргриммара, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Пламя Оргриммара хранителю мудрости Праздника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Если я не ошибаюсь, это пламя добыто из самого сердца Оргриммара! Свирепая сила, наполняющая души орков и троллей, чувствуется в неистовом жаре этого огня. Какое чудесное добавление к коллекции! И сколь велика твоя отвага, позволившая тебе пробраться в самое логово врага, дабы заполучить священное пламя!$B$BИнтересно, какая сила таится в других городах?. .',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты поистине светишься, |3-6($R). Что у тебя там?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9325,'Похищение пламени Громового Утеса','Это пламя, похищенное у шамана Громового Утеса, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...','Верните Пламя Громового Утеса хранителю мудрости Праздника.','Если я не ошибаюсь, это пламя добыто на уступах Громового Утеса! Как оно поет, исполненное силы духа! Твою ловкость можно назвать непревзойденной, $N. Прими это как малую плату за свое мастерство. Если бы у нас было пламя из всех трех городов...','Ты поистине светишься, |3-6($R). Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищение пламени Громового Утеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это пламя, похищенное у шамана Громового Утеса, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Пламя Громового Утеса хранителю мудрости Праздника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если я не ошибаюсь, это пламя добыто на уступах Громового Утеса! Как оно поет, исполненное силы духа! Твою ловкость можно назвать непревзойденной, $N. Прими это как малую плату за свое мастерство. Если бы у нас было пламя из всех трех городов...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты поистине светишься, |3-6($R). Что у тебя там?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9326,'Похищение пламени Подгорода','Это пламя, похищенное из руин над Подгородом, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...','Верните Пламя Подгорода хранителю мудрости Праздника.','Хм... Какой странный огонь! Он слаб, почти угасает, но его жар силен. Ты говоришь, он из Подгорода? Поразительно. Кто знает, чего мы можем достичь, заполучив пламя из всех трех городов?','Ты поистине светишься, |3-6($R). Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищение пламени Подгорода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это пламя, похищенное из руин над Подгородом, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Хранитель мудрости может знать больше...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Пламя Подгорода хранителю мудрости Праздника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... Какой странный огонь! Он слаб, почти угасает, но его жар силен. Ты говоришь, он из Подгорода? Поразительно. Кто знает, чего мы можем достичь, заполучив пламя из всех трех городов?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты поистине светишься, |3-6($R). Что у тебя там?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (9327,'Отрекшиеся','Понимаю, что это звучит странно, но Отрекшиеся готовы помогать нам. Поговори с их предводителем, верховным палачом Мавреном. Он в башне на западной окраине города.$B$BИ, |3-6($c), после разговора с ним возвращайся ко мне – у меня есть одно неприятное дело, которое требует немедленного решения!','Письмо при тебе?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отрекшиеся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понимаю, что это звучит странно, но Отрекшиеся готовы помогать нам. Поговори с их предводителем, верховным палачом Мавреном. Он в башне на западной окраине города.$B$BИ, |3-6($c), после разговора с ним возвращайся ко мне – у меня есть одно неприятное дело, которое требует немедленного решения!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Письмо при тебе?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9328,'Герой син\'дорай','Принесите голову Дар\'Кхана Лор\'темару Терону в Луносвет.','Ты хочешь поговорить со мной, |3-6($C)? Не припомню, чтобы назначал тебе встречу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Герой син\'дорай',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Дар\'Кхана Лор\'темару Терону в Луносвет.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь поговорить со мной, |3-6($C)? Не припомню, чтобы назначал тебе встречу.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9329,'Отрекшиеся','Понимаю, что это звучит странно, но Отрекшиеся готовы помогать нам. Поговори с их предводителем, верховным палачом Мавреном. Он в башне на западной окраине города.$B$BИ, |3-6($c), после разговора с ним возвращайся ко мне – у меня есть одно неприятное дело, которое требует немедленного решения!','Мы, Отрекшиеся, потому здесь, что у нас с вами общий враг – Дар\'Кхан! Он вернулся и ныне командует Плетью, чьи полчища вторглись в эти края из его логова, Смертхольма, что на юге.\n\nНаша предводительница, Сильвана Ветрокрылая, родом из этих мест, при жизни она была эльфом! У Дар\'Кхана перед ней должок, и она жаждет его смерти не меньше, чем вы.\n\nВместе мы разобьем его, $C!','Знаю, это кажется странным, но Отрекшиеся здесь, чтобы помочь. Тебе следует поговорить с их лидером, верховным палачом Мавреном. Он в башне в западной части города.$B$BИ, $C, когда закончишь с ним поговорить, возвращайся ко мне; У меня есть что-то ужасное, с чем нужно немедленно разобраться!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отрекшиеся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Понимаю, что это звучит странно, но Отрекшиеся готовы помогать нам. Поговори с их предводителем, верховным палачом Мавреном. Он в башне на западной окраине города.$B$BИ, |3-6($c), после разговора с ним возвращайся ко мне – у меня есть одно неприятное дело, которое требует немедленного решения!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы, Отрекшиеся, потому здесь, что у нас с вами общий враг – Дар\'Кхан! Он вернулся и ныне командует Плетью, чьи полчища вторглись в эти края из его логова, Смертхольма, что на юге.\n\nНаша предводительница, Сильвана Ветрокрылая, родом из этих мест, при жизни она была эльфом! У Дар\'Кхана перед ней должок, и она жаждет его смерти не меньше, чем вы.\n\nВместе мы разобьем его, $C!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаю, это кажется странным, но Отрекшиеся здесь, чтобы помочь. Тебе следует поговорить с их лидером, верховным палачом Мавреном. Он в башне в западной части города.$B$BИ, $C, когда закончишь с ним поговорить, возвращайся ко мне; У меня есть что-то ужасное, с чем нужно немедленно разобраться!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9330,'Похищение пламени Штормграда','Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...','Верните Пламя Штормграда Праздничному Сказителю.','И это ярко горящее пламя... ты говоришь, оно из Штормграда? Замечательно! Должно быть, это было славное приключение! Конечно же, я заплачу тебе за это. Если ты найдешь еще что-нибудь подобное, обязательно приходи поговорить со мной.','Ты поистине светишься, |3-6($R). Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищение пламени Штормграда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Пламя Штормграда Праздничному Сказителю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И это ярко горящее пламя... ты говоришь, оно из Штормграда? Замечательно! Должно быть, это было славное приключение! Конечно же, я заплачу тебе за это. Если ты найдешь еще что-нибудь подобное, обязательно приходи поговорить со мной.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты поистине светишься, |3-6($R). Что у тебя там?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9331,'Похищение пламени Стальгорна','Это пламя, похищенное из сердца Стальгорна, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...','Верните Пламя Стальгорна Праздничному Сказителю.','Это сильное пламя, должно быть, явилось из залов Стальгорна; оно столь же неукротимо, как сами дворфы. Отличная добыча, $N. Если бы у меня был огонь из других городов... а, неважно. Вот твоя плата.','Ты поистине светишься, |3-6($R). Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищение пламени Стальгорна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это пламя, похищенное из сердца Стальгорна, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Пламя Стальгорна Праздничному Сказителю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это сильное пламя, должно быть, явилось из залов Стальгорна; оно столь же неукротимо, как сами дворфы. Отличная добыча, $N. Если бы у меня был огонь из других городов... а, неважно. Вот твоя плата.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты поистине светишься, |3-6($R). Что у тебя там?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9332,'Похищение пламени Дарнаса','Это пламя, похищенное с берегов Тельдрассила, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...','Верните Пламя Дарнаса Праздничному Сказителю.','Этот огонь полон древней скорби, $N. Ты говоришь, он добыт от корней Тельдрассила? Невероятно! Вот награда за твое мастерство. Возвращайся ко мне, если найдешь еще что-либо подобное; возможно, у меня найдется применение этому.','Ты поистине светишься, |3-6($R). Что у тебя там?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищение пламени Дарнаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это пламя, похищенное с берегов Тельдрассила, наполняет тебя теплом. Эта сырая энергия чужда тебе, но Сказитель может знать больше...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Пламя Дарнаса Праздничному Сказителю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот огонь полон древней скорби, $N. Ты говоришь, он добыт от корней Тельдрассила? Невероятно! Вот награда за твое мастерство. Возвращайся ко мне, если найдешь еще что-либо подобное; возможно, у меня найдется применение этому.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты поистине светишься, |3-6($R). Что у тебя там?',`requestitemstext_loc8`);
