INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9338,'Верность Кругу Кенария','С твоей помощью, $N, мы преодолеем все препятствия.','Даже если тебе не нужны предлагаемые нами материальные вознаграждения, эти значки по-прежнему свидетельствуют о нашем взаимном доверии и дружбе.$B$BПринеси их мне. Я должным образом отмечу твою службу, если твоя работа выходит за рамки служебного долга.','Вернитесь к призывателю ветров Калдону в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верность Кругу Кенария',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С твоей помощью, $N, мы преодолеем все препятствия.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Даже если тебе не нужны предлагаемые нами материальные вознаграждения, эти значки по-прежнему свидетельствуют о нашем взаимном доверии и дружбе.$B$BПринеси их мне. Я должным образом отмечу твою службу, если твоя работа выходит за рамки служебного долга.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывателю ветров Калдону в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9339,'Награда вора','Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...','Верните Пламя Штормграда (NAME)','Сегодняшние твои деяния свидетельствуют сами за себя, $N. $B$BЯ мало что могу дать тебе помимо этого, но у меня есть вот этот венец – дар, что соответствует ловкости и дерзости. Пусть он озарит твой путь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда вора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Пламя Штормграда (NAME)',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодняшние твои деяния свидетельствуют сами за себя, $N. $B$BЯ мало что могу дать тебе помимо этого, но у меня есть вот этот венец – дар, что соответствует ловкости и дерзости. Пусть он озарит твой путь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9340,'Глубокий Разлом','Ступайте на восток от Соколиного Дозора, к Глубокому Разлому, и убейте 8 детенышей камнеруба и 3 камнерубов-вожаков по приказу капитана следопытов Венн\'рена.','Ты $Gвернулся:вернулась;. Это значит, что задание выполнено?','Вернитесь к капитану следопытов Венн\'рену в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубокий Разлом',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ступайте на восток от Соколиного Дозора, к Глубокому Разлому, и убейте 8 детенышей камнеруба и 3 камнерубов-вожаков по приказу капитана следопытов Венн\'рена.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;. Это значит, что задание выполнено?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану следопытов Венн\'рену в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
