INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9345,'Изготовление мази','Я не добрался даже до Зет\'Гора, как патруль Легиона меня засек. Я побежал, надеясь укрыться в башне неподалеку, но одна из гончих Скверны вцепилась мне под колено.$B$BСбежать-то я сбежал, но с ногой творится что-то ужасное. Каменный страж Амбелан нашел меня и перетащил сюда.$B$BМне надо хоть немного подлечиться. В Долине Костей, к северу отсюда, растет трава шиполист. Я смогу сделать из нее обезболивающую мазь, которая позволит мне ходить.','Соберите 12 листьев пламенного шиполиста и возвращайтесь к Грелагу на Заставу Хребтолома.','Ты принес листья?','Вернитесь к Грелагу на Заставу Хребтолома, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изготовление мази',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не добрался даже до Зет\'Гора, как патруль Легиона меня засек. Я побежал, надеясь укрыться в башне неподалеку, но одна из гончих Скверны вцепилась мне под колено.$B$BСбежать-то я сбежал, но с ногой творится что-то ужасное. Каменный страж Амбелан нашел меня и перетащил сюда.$B$BМне надо хоть немного подлечиться. В Долине Костей, к северу отсюда, растет трава шиполист. Я смогу сделать из нее обезболивающую мазь, которая позволит мне ходить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 12 листьев пламенного шиполиста и возвращайтесь к Грелагу на Заставу Хребтолома.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес листья?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грелагу на Заставу Хребтолома, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9349,'Сбор яиц опустошителей','Чтобы блюдо было отменным, его надо готовить из отменных продуктов! Эти яйца прекрасны.$B$BСейчас я дочищу свою сковородку, и можешь присоединяться к трапезе!','Ну, где яйца?$B$B*Живот Легасси издает голодное бурчание.*','Вернитесь к Легасси на место крушения дирижабля, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор яиц опустошителей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чтобы блюдо было отменным, его надо готовить из отменных продуктов! Эти яйца прекрасны.$B$BСейчас я дочищу свою сковородку, и можешь присоединяться к трапезе!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, где яйца?$B$B*Живот Легасси издает голодное бурчание.*',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Легасси на место крушения дирижабля, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9350,'Работай, солнце еще высоко','Постоянные атаки Легиона истощили нашу оборону. Если падут крепостные стены, то падет и Траллмар. Я отправил батраков на строительные работы, но у нас недостаточно материалов.$B$BГрелаг, один из учеников провозвестницы, предложил вернуться к образу жизни наших предков. В давние времена мы добывали мясо, шкуры и кость, охотясь на копытней. Копытни пасутся на юго-востоке. Отправляйся на охоту, чтобы почтить предков и добыть необходимые материалы.','Отправляйтесь на охоту на свирепых копытней и добудьте 8 шкур копытня и 8 комплектов костей копытня. Собрав материалы, возвращайтесь к командиру стражи Кранку в Траллмар.','Вернитесь к командиру стражи Кранку в Каньон Каменной Стены, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работай, солнце еще высоко',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Постоянные атаки Легиона истощили нашу оборону. Если падут крепостные стены, то падет и Траллмар. Я отправил батраков на строительные работы, но у нас недостаточно материалов.$B$BГрелаг, один из учеников провозвестницы, предложил вернуться к образу жизни наших предков. В давние времена мы добывали мясо, шкуры и кость, охотясь на копытней. Копытни пасутся на юго-востоке. Отправляйся на охоту, чтобы почтить предков и добыть необходимые материалы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на охоту на свирепых копытней и добудьте 8 шкур копытня и 8 комплектов костей копытня. Собрав материалы, возвращайтесь к командиру стражи Кранку в Траллмар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру стражи Кранку в Каньон Каменной Стены, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9351,'Дикие демоны Бездны','Даже если я восстановлю оболочку дирижабля, все равно мне нечем заправить двигатель. Топливо закончилось, и я ума не приложу, где его можно достать.$B$BРазве что, к югу отсюда находится место под названием Искривленные поля. Там полно всякой нечисти и бесконтрольных демонов Бездны, но ведь это, можно сказать, ходячие батарейки!$B$BПринеси мне сущности демонов Бездны, я запущу двигатель и мы наконец уберемся отсюда. Ставлю пять золотых, что выжму из этого демона настоящую демоническую скорость!','Принесите 10 конденсированных сущностей демона Бездны "Крикуну" Скриду Многослову на место крушения дирижабля.','Отлично! Вот это мощь! Мне придется усовершенствовать двигатель, чтобы воспользоваться всеми преимуществами этой штуки. Если... в смысле, когда мы отсюда выберемся, в Зоне 52 ахнут, увидев, что я придумал!','Удалось добыть сущности?','Вернитесь к Крикуну Скриду Многослову на место крушения дирижабля, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикие демоны Бездны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже если я восстановлю оболочку дирижабля, все равно мне нечем заправить двигатель. Топливо закончилось, и я ума не приложу, где его можно достать.$B$BРазве что, к югу отсюда находится место под названием Искривленные поля. Там полно всякой нечисти и бесконтрольных демонов Бездны, но ведь это, можно сказать, ходячие батарейки!$B$BПринеси мне сущности демонов Бездны, я запущу двигатель и мы наконец уберемся отсюда. Ставлю пять золотых, что выжму из этого демона настоящую демоническую скорость!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 конденсированных сущностей демона Бездны "Крикуну" Скриду Многослову на место крушения дирижабля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Вот это мощь! Мне придется усовершенствовать двигатель, чтобы воспользоваться всеми преимуществами этой штуки. Если... в смысле, когда мы отсюда выберемся, в Зоне 52 ахнут, увидев, что я придумал!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось добыть сущности?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крикуну Скриду Многослову на место крушения дирижабля, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9352,'Вторжение из Дарнаса','Ночные эльфы? Здесь? Вот крысы!$B$BКак ты думаешь, имеют ли они отношение к аварии в моем святилище? Если у тебя есть какие-то сведения, лучше незамедлительно передать их капитану Печати Солнца!','Тебе удалось что-нибудь выяснить? За этим стоят ночные эльфы?','Вернитесь к хранительнице энергии Велании в Западное святилище, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение из Дарнаса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ночные эльфы? Здесь? Вот крысы!$B$BКак ты думаешь, имеют ли они отношение к аварии в моем святилище? Если у тебя есть какие-то сведения, лучше незамедлительно передать их капитану Печати Солнца!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось что-нибудь выяснить? За этим стоят ночные эльфы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранительнице энергии Велании в Западное святилище, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9353,'Отоваривание подарочного купона iCoke','Вернитесь к ней номер два.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отоваривание подарочного купона iCoke',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ней номер два.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9354,'Поиск новых материалов','*Дворф отрывается от своей работы и выжидающе на вас смотрит*. Если тебе надо что-нибудь починить, |3-6($c), вставай в очередь. Я по уши занят подгонкой обмундирования Сынов Лотара и подготовкой к новым сражениям.$B$BРудники наводнили землеточцы, и наши запасы металла изрядно поистощились. Я покрутил так и сяк разный материал, и решил пустить в дело шкуры свирепых копытней, обитающих к северо-востоку от Оплота. Пока нет железа, будем работать с тем, что есть.','Добудьте 8 шкур и 8 сухожилий свирепого копытня и принесите Шалтую в Оплот Чести.','Вернитесь к Шалтую на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиск новых материалов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Дворф отрывается от своей работы и выжидающе на вас смотрит*. Если тебе надо что-нибудь починить, |3-6($c), вставай в очередь. Я по уши занят подгонкой обмундирования Сынов Лотара и подготовкой к новым сражениям.$B$BРудники наводнили землеточцы, и наши запасы металла изрядно поистощились. Я покрутил так и сяк разный материал, и решил пустить в дело шкуры свирепых копытней, обитающих к северо-востоку от Оплота. Пока нет железа, будем работать с тем, что есть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 шкур и 8 сухожилий свирепого копытня и принесите Шалтую в Оплот Чести.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шалтую на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9355,'Работа для сообразительных','Привет, |3-6($c). Наконец-то прибыло подкрепление, так что мы можем себе позволить хоть какое-то подобие нормальной жизни.$B$BОдна из первых задач – восстановить поток путников и торговых караванов по юго-западной дороге, но для этого надо очистить эту область от землероев.$B$BСыны будут тебе благодарны, если ты поможешь нам разобраться с этой напастью. Место обитания землероев очень легко опознать. Видишь вздыбленную землю – значит, внутри они и сидят.','Убейте 15 хищных землероев и возвращайтесь к Штейгеру Большие Десны в Оплот Чести.','Ну что, $gочистил:очистила; дорогу от червей?','Вернитесь к штейгеру Большие Десны в Копи Оплота Чести, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работа для сообразительных',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, |3-6($c). Наконец-то прибыло подкрепление, так что мы можем себе позволить хоть какое-то подобие нормальной жизни.$B$BОдна из первых задач – восстановить поток путников и торговых караванов по юго-западной дороге, но для этого надо очистить эту область от землероев.$B$BСыны будут тебе благодарны, если ты поможешь нам разобраться с этой напастью. Место обитания землероев очень легко опознать. Видишь вздыбленную землю – значит, внутри они и сидят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 хищных землероев и возвращайтесь к Штейгеру Большие Десны в Оплот Чести.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $gочистил:очистила; дорогу от червей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Большие Десны в Копи Оплота Чести, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9356,'Летать как птица','Принесите 12 мясистых крыльев канюка Легасси на место крушения дирижабля.','Предвкушаю, какое у него будет лицо, когда он это увидит. С самого момента аварии он постоянно ворчит, что я думаю только о еде. Но кто-то же должен всех кормить, пока остальные чинят дирижабль!','Вернитесь к Легасси на место крушения дирижабля, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Летать как птица',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 мясистых крыльев канюка Легасси на место крушения дирижабля.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Предвкушаю, какое у него будет лицо, когда он это увидит. С самого момента аварии он постоянно ворчит, что я думаю только о еде. Но кто-то же должен всех кормить, пока остальные чинят дирижабль!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Легасси на место крушения дирижабля, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9357,'Задание Аэльдона Озаренного Солнцем','Если ты ищешь работу, обратись к капитану Печати Солнца за Внутренними эльфийскими воротами, что у меня за спиной.$b$bА теперь оставь меня в покое, мне нужно допросить этого негодяя.','Поговорите с Аэльдоном Озаренным Солнцем у Внутренних эльфийских ворот в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание Аэльдона Озаренного Солнцем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты ищешь работу, обратись к капитану Печати Солнца за Внутренними эльфийскими воротами, что у меня за спиной.$b$bА теперь оставь меня в покое, мне нужно допросить этого негодяя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аэльдоном Озаренным Солнцем у Внутренних эльфийских ворот в Лесах Вечной Песни.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (9358,'Ты здесь, чтобы нам помогать? Так что же ты молчишь? Помощь нам всегда требуется!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты здесь, чтобы нам помогать? Так что же ты молчишь? Помощь нам всегда требуется!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9359,'Обитель Странников') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обитель Странников',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (9360,'Тролли отвлекали нас своими атаками, планируя нападение на деревню Легкий Ветерок? Мы этого совершенно не ожидали!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тролли отвлекали нас своими атаками, планируя нападение на деревню Легкий Ветерок? Мы этого совершенно не ожидали!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9361,'Зловепрь – тоже мясо','Легасси требует принести ему 8 кусков мяса зловепря на место крушения дирижабля. Убейте зловепря, добудьте порченое мясо зловепря, а затем очистите его с помощью микстуры очищения.','Хм...$B$BВыглядит съедобным, если проперчить хорошенько. Лучше не будем говорить Скриду, откуда взялся его завтрак, ладно?','Что там с очищенным мясом зловепря? Удалось приготовить?','Вернитесь к Легасси на место крушения дирижабля, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зловепрь – тоже мясо',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Легасси требует принести ему 8 кусков мяса зловепря на место крушения дирижабля. Убейте зловепря, добудьте порченое мясо зловепря, а затем очистите его с помощью микстуры очищения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм...$B$BВыглядит съедобным, если проперчить хорошенько. Лучше не будем говорить Скриду, откуда взялся его завтрак, ладно?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там с очищенным мясом зловепря? Удалось приготовить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Легасси на место крушения дирижабля, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9362,'Полководец Креллиан','У меня мало времени, $n! С помощью чар магического зрения я обнаружил мощный источник магии. Я не могу покинуть башню, поэтому прошу тебя убить мерзкое создание, завладевшее мощным артефактом. $b$bЖалкий недоумок, известный как полководец Креллиан, прячется за широкими спинами своих стражей в храме Зин-Малор. Испепели это ничтожество и принеси мне радужную раковину, которую он прячет.','Принесите радужную раковину верховному магу Ксилему в башню в утесах Азшары.','Я должен сказать, что эта раковина имеет странную ауру.','Не теряй зря время! Ты $Gдостал:достала; раковину?','Вернитесь к верховному магу Ксилему в Медвежий угол, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полководец Креллиан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня мало времени, $n! С помощью чар магического зрения я обнаружил мощный источник магии. Я не могу покинуть башню, поэтому прошу тебя убить мерзкое создание, завладевшее мощным артефактом. $b$bЖалкий недоумок, известный как полководец Креллиан, прячется за широкими спинами своих стражей в храме Зин-Малор. Испепели это ничтожество и принеси мне радужную раковину, которую он прячет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите радужную раковину верховному магу Ксилему в башню в утесах Азшары.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я должен сказать, что эта раковина имеет странную ауру.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не теряй зря время! Ты $Gдостал:достала; раковину?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Ксилему в Медвежий угол, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9363,'Предупреждение деревне Легкий Ветерок') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупреждение деревне Легкий Ветерок',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9364,'Частицы магии','В ходе исследований я выявил потрясающее свойство радужной раковины. $b$bВозьми раковину и наложи заклинание превращения на тварей Бича Злобы в Азшаре. Через несколько мгновений хаотическая аура раковины создаст нескольких маленьких клонов. Клонов надо убить – как можно скорее! – и тогда раковина вберет в себя их сущность. $b$bВозвращайся ко мне, когда раковина будет полна.','Наложите заклинание превращения на тварей Бича Злобы в Азшаре и убейте клонов, которые появятся несколько мгновений спустя. Убейте 50 клонов и возвращайтесь к верховному магу Ксилему в Азшару.','Великолепно! Великолепно!$B$BТеперь мы можем реформировать эту магию в новое заклинание!','Ты $Gвыполнил:выполнила; мое поручение?','Вернитесь к верховному магу Ксилему в Медвежий угол, что в Азшаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Частицы магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В ходе исследований я выявил потрясающее свойство радужной раковины. $b$bВозьми раковину и наложи заклинание превращения на тварей Бича Злобы в Азшаре. Через несколько мгновений хаотическая аура раковины создаст нескольких маленьких клонов. Клонов надо убить – как можно скорее! – и тогда раковина вберет в себя их сущность. $b$bВозвращайся ко мне, когда раковина будет полна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наложите заклинание превращения на тварей Бича Злобы в Азшаре и убейте клонов, которые появятся несколько мгновений спустя. Убейте 50 клонов и возвращайтесь к верховному магу Ксилему в Азшару.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Великолепно!$B$BТеперь мы можем реформировать эту магию в новое заклинание!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвыполнил:выполнила; мое поручение?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Ксилему в Медвежий угол, что в Азшаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9365,'Награда вора','Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...','Верните Пламя Штормграда (NAME)','Сегодняшние твои деяния свидетельствуют сами за себя, $N. $B$BЯ мало что могу дать тебе помимо этого, но у меня есть вот этот венец – дар, что соответствует ловкости и дерзости. Пусть он озарит твой путь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Награда вора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это пламя, похищенное из сердца Штормграда, наполняет тебя теплом. Эта сырая энергия чужда тебе, но (NAME) может знать больше...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Пламя Штормграда (NAME)',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодняшние твои деяния свидетельствуют сами за себя, $N. $B$BЯ мало что могу дать тебе помимо этого, но у меня есть вот этот венец – дар, что соответствует ловкости и дерзости. Пусть он озарит твой путь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9366,'Оскверненная кровь','К северо-востоку отсюда лежат Пруды Аггонара. Когда-то там было священное место дренеев, но потом кровь демона осквернила воды этих прудов.$B$BС тех пор минуло много лет, но кровь, даже разбавленная, все еще таит в себе огромную силу. Рядом с прудами разгуливают исчадия ужаса, насыщаясь энергией, разлитой в воде. Уничтожь их и принеси мне их оскверненную кровь. Выполни это задание, и получишь награду.','Вернитесь к Риатену Мрачному в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненная кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К северо-востоку отсюда лежат Пруды Аггонара. Когда-то там было священное место дренеев, но потом кровь демона осквернила воды этих прудов.$B$BС тех пор минуло много лет, но кровь, даже разбавленная, все еще таит в себе огромную силу. Рядом с прудами разгуливают исчадия ужаса, насыщаясь энергией, разлитой в воде. Уничтожь их и принеси мне их оскверненную кровь. Выполни это задание, и получишь награду.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риатену Мрачному в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9367,'Праздник Огня','Вновь наступает праздник Огненного солнцеворота!$b$bКаждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажженными в наших столичных городах. По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Середине Лета.$b$bНа самом деле, если ты не против, у меня для тебя есть задание. Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах. Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!','Прикоснитесь к пламени праздничных костров в Штормграде, Стальгорне и Дарнасе, затем поговорите с хранителем мудрости Праздника в столичных городах.','Отлично! Кажется, мы назначили послушных Хранителей пламени в этом году, если костры так же хорошо хранятся, как вы утверждаете. Спасибо, что осмотрели их для меня. Вот, возьмите это как небольшой знак моего уважения.','Костры горят?','Вернитесь к хранителю мудрости Праздника.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Праздник Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вновь наступает праздник Огненного солнцеворота!$b$bКаждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажженными в наших столичных городах. По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Середине Лета.$b$bНа самом деле, если ты не против, у меня для тебя есть задание. Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах. Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикоснитесь к пламени праздничных костров в Штормграде, Стальгорне и Дарнасе, затем поговорите с хранителем мудрости Праздника в столичных городах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Кажется, мы назначили послушных Хранителей пламени в этом году, если костры так же хорошо хранятся, как вы утверждаете. Спасибо, что осмотрели их для меня. Вот, возьмите это как небольшой знак моего уважения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Костры горят?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю мудрости Праздника.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9368,'Праздник Огня','Вновь наступает праздник Огненного солнцеворота!$b$bКаждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажженными в наших столичных городах. По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Огненному солнцевороту.$b$bНа самом деле, если ты не против, у меня для тебя есть задание. Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах. Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!','Прикоснитесь к пламени праздничных костров в Оргриммаре, Громовом Утесе и Подгороде, затем поговорите с Праздничным сказителем в столичных городах.','Отличная работа, $N. С тьмой покончено, остался только вопрос времени, когда Король Лич вспомнит о своих некрополях и решит оставить нас в покое.','Удача на твоей стороне, $N?','Вернитесь к праздничному сказителю.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Праздник Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вновь наступает праздник Огненного солнцеворота!$b$bКаждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажженными в наших столичных городах. По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Огненному солнцевороту.$b$bНа самом деле, если ты не против, у меня для тебя есть задание. Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах. Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прикоснитесь к пламени праздничных костров в Оргриммаре, Громовом Утесе и Подгороде, затем поговорите с Праздничным сказителем в столичных городах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. С тьмой покончено, остался только вопрос времени, когда Король Лич вспомнит о своих некрополях и решит оставить нас в покое.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удача на твоей стороне, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к праздничному сказителю.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9369,'Исцеляющие кристаллы','Мы дренеи. Наш корабль разбился, и поскольку раненых очень много, первым делом надо зарядить исцеляющие кристаллы. И побыстрее!$b$bК сожалению, в настоящий момент для этого придется добывать кровь долинных мотыльков, она отлично подойдет.$b$bМотыльки водятся во всей долине, особенно в северо-западной ее части.','Добудьте 6 фиалов с кровью мотылька из ближайших долинных мотыльков и принесите их Проэнтиусу на место крушения в долине Аммен.','Жаль, что приходится обменивать жизни этих существ на наши – подобная жестокость противна духу дренеев. Зато собранная кровь наполнит исцеляющие кристаллы, так что мотыльки погибли не зря.','Тебе удалось набрать достаточно крови мотыльков для создания исцеляющих кристаллов? Время не ждет, раненых очень много!','Вернитесь к Проэнтиусу на Место Крушения, что в долине Аммен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исцеляющие кристаллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы дренеи. Наш корабль разбился, и поскольку раненых очень много, первым делом надо зарядить исцеляющие кристаллы. И побыстрее!$b$bК сожалению, в настоящий момент для этого придется добывать кровь долинных мотыльков, она отлично подойдет.$b$bМотыльки водятся во всей долине, особенно в северо-западной ее части.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 6 фиалов с кровью мотылька из ближайших долинных мотыльков и принесите их Проэнтиусу на место крушения в долине Аммен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Жаль, что приходится обменивать жизни этих существ на наши – подобная жестокость противна духу дренеев. Зато собранная кровь наполнит исцеляющие кристаллы, так что мотыльки погибли не зря.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось набрать достаточно крови мотыльков для создания исцеляющих кристаллов? Время не ждет, раненых очень много!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Проэнтиусу на Место Крушения, что в долине Аммен.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9370,'Остановить очищение','Наши разведчики захватили у прудов Аггонара какого-то дренейского паладина. Он подготавливал ритуал по очистке прудов. Мы должны остановить дренеев, а не то потеряем бесценный источник оскверненной крови!$B$BВот этим сигнальным самоцветом он должен был пометить место, где их жрец – "анахорет", как они себя называют, – мог бы спокойно провести ритуал. Поставь камень на Алтарь Аггонара и убей всех дренеев, которые появятся.$B$BДумаю, тебе стоит прихватить парочку друзей на помощь.','Пусть эти святые фанатики не лезут не в свое дело.','Вернитесь к Риатену Мрачному в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановить очищение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши разведчики захватили у прудов Аггонара какого-то дренейского паладина. Он подготавливал ритуал по очистке прудов. Мы должны остановить дренеев, а не то потеряем бесценный источник оскверненной крови!$B$BВот этим сигнальным самоцветом он должен был пометить место, где их жрец – "анахорет", как они себя называют, – мог бы спокойно провести ритуал. Поставь камень на Алтарь Аггонара и убей всех дренеев, которые появятся.$B$BДумаю, тебе стоит прихватить парочку друзей на помощь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пусть эти святые фанатики не лезут не в свое дело.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Риатену Мрачному в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9371,'Ботаник Таэрикс','$n, ботанику Таэрикс нужна твоя помощь. Она вместе с учениками расположилась на западе отсюда, рядом с кораблем.','Поговорите с ботаником Таэрикс на месте крушения в долине Аммен.','О, слава Небу, что ты здесь. У нас очень много работы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ботаник Таэрикс',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ботанику Таэрикс нужна твоя помощь. Она вместе с учениками расположилась на западе отсюда, рядом с кораблем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с ботаником Таэрикс на месте крушения в долине Аммен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, слава Небу, что ты здесь. У нас очень много работы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9372,'Распространение демонической скверны','Добро пожаловать на Кенарийскую заставу, |3-6($c). Я благодарна, что ты $gзашел:зашла; сюда, нас нечасто балуют визитами. Я исходила эти земли вдоль и поперек, исследуя существ, которые их населяют.$B$BИзучая по поручению Кенарийской экспедиции наиболее опасных тварей, я сделала поразительное открытие. Многие из здешних существ уже подверглись кардинальным изменениям, но все равно продолжают мутировать. Чтобы следить за этими изменениями, мне нужны образцы крови, так что я буду рада любой помощи.','Тебе удалось выполнить мою просьбу?','Вернитесь к Тиа Рыжей Гриве на Кенарийскую заставу, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распространение демонической скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать на Кенарийскую заставу, |3-6($c). Я благодарна, что ты $gзашел:зашла; сюда, нас нечасто балуют визитами. Я исходила эти земли вдоль и поперек, исследуя существ, которые их населяют.$B$BИзучая по поручению Кенарийской экспедиции наиболее опасных тварей, я сделала поразительное открытие. Многие из здешних существ уже подверглись кардинальным изменениям, но все равно продолжают мутировать. Чтобы следить за этими изменениями, мне нужны образцы крови, так что я буду рада любой помощи.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось выполнить мою просьбу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тиа Рыжей Гриве на Кенарийскую заставу, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9373,'Потерянное послание','Взглянув на кожу чехла повнимательней, вы понимаете, что его разъели желудочные соки червя. Кажется, на чехле был какой-то узор, но детали украшений разобрать невозможно.$B$BЕдинственное, что можно опознать, так это полустертый знак Круга Кенария. О содержимом чехла ничего не известно, и вы решаете, что лучше всего отнести его кому-нибудь из Круга.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянное послание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взглянув на кожу чехла повнимательней, вы понимаете, что его разъели желудочные соки червя. Кажется, на чехле был какой-то узор, но детали украшений разобрать невозможно.$B$BЕдинственное, что можно опознать, так это полустертый знак Круга Кенария. О содержимом чехла ничего не известно, и вы решаете, что лучше всего отнести его кому-нибудь из Круга.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9374,'Записи Арелиона','Мой муж Арелион заинтересовался Прудами Аггонара, едва мы прибыли в Запределье. Больше всего времени он проводил, изучая свойства местного ила.$B$BНесколько дней назад Аэриона не стало. Мне сказали, что он мертв, а с этим ничего уже не поделаешь.$B$BНо я бы не хотела, чтобы исследования моего мужа бесследно сгинули после его смерти. Ступай на северо-восток, к прудам, и поищи его дневник. Аэрион носил его в коричневом ранце.','Вернитесь к магистру Каринде в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Записи Арелиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой муж Арелион заинтересовался Прудами Аггонара, едва мы прибыли в Запределье. Больше всего времени он проводил, изучая свойства местного ила.$B$BНесколько дней назад Аэриона не стало. Мне сказали, что он мертв, а с этим ничего уже не поделаешь.$B$BНо я бы не хотела, чтобы исследования моего мужа бесследно сгинули после его смерти. Ступай на северо-восток, к прудам, и поищи его дневник. Аэрион носил его в коричневом ранце.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Каринде в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9376,'Скарб пилигрима','Наша раненая путница все продолжает кричать о какой-то сумке.$B$BТы не $gзаметил:заметила; ничего похожего на том месте, где ее $gнашел:нашла;? Хм...$B$BДолжно быть, она потеряла сумку, когда бежала от преследователей. Перозубые опустошители из вон той лощины на юге часто нападают на одиноких путников.$B$BЕсли она не успокоится, я не смогу наложить повязку на рану. Как она не понимает, что упрямство может стоить ей жизни!$B$BСтупай в Лощину Пыльного Пера, и попробуй разыскать место ее стоянки. Держу пари, она оставила свои сумки где-то там.','Перозубые опустошители напали на израненную эльфийку крови – пилигрима, когда она остановилась в Лощине Пыльного Пера. Разыщите ее стоянку и потерянные вещи.','Не нравится мне все это. Вряд ли она бы кинула сумку на дороге. Ты можешь разыскать ее вещи?','Вернитесь к Талерису Созерцателю Рассвета в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скарб пилигрима',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша раненая путница все продолжает кричать о какой-то сумке.$B$BТы не $gзаметил:заметила; ничего похожего на том месте, где ее $gнашел:нашла;? Хм...$B$BДолжно быть, она потеряла сумку, когда бежала от преследователей. Перозубые опустошители из вон той лощины на юге часто нападают на одиноких путников.$B$BЕсли она не успокоится, я не смогу наложить повязку на рану. Как она не понимает, что упрямство может стоить ей жизни!$B$BСтупай в Лощину Пыльного Пера, и попробуй разыскать место ее стоянки. Держу пари, она оставила свои сумки где-то там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Перозубые опустошители напали на израненную эльфийку крови – пилигрима, когда она остановилась в Лощине Пыльного Пера. Разыщите ее стоянку и потерянные вещи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не нравится мне все это. Вряд ли она бы кинула сумку на дороге. Ты можешь разыскать ее вещи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талерису Созерцателю Рассвета в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9377,'Жажда магической силы','Соколиный Дозор служит пристанищем для тех, кто странствует по Запределью. Мы находимся в самом начале пути, но многие приходят к нам, уже истомленные магической жаждой.$B$BВ этом мире необходимо уметь контролировать свою зависимость от магии. Помогают еда и питье, но полезнее всего иметь запасы магической энергии. Ее могучими источниками являются демоны Бездны, но в последнее время они встречаются все реже и реже. Сейчас их можно отыскать только на Искривленных полях к юго-западу отсюда.','Извлеките сущность могущественного демона Бездны из мстительных демонов Бездны и возвращайтесь к Талерису Созерцателю Рассвета в Соколиный Дозор.','Вернитесь к Талерису Созерцателю Рассвета в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жажда магической силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Соколиный Дозор служит пристанищем для тех, кто странствует по Запределью. Мы находимся в самом начале пути, но многие приходят к нам, уже истомленные магической жаждой.$B$BВ этом мире необходимо уметь контролировать свою зависимость от магии. Помогают еда и питье, но полезнее всего иметь запасы магической энергии. Ее могучими источниками являются демоны Бездны, но в последнее время они встречаются все реже и реже. Сейчас их можно отыскать только на Искривленных полях к юго-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Извлеките сущность могущественного демона Бездны из мстительных демонов Бездны и возвращайтесь к Талерису Созерцателю Рассвета в Соколиный Дозор.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талерису Созерцателю Рассвета в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9378,'DND FLAG Цитадель ужаса – Наксрамас','В чаще Чумного леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.$b$bМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку твоя преданность делу Серебряного Рассвета не подлежит сомнению, мы возьмем на себя все издержки.','Верховный маг Анжела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова бесплатно наложить на вас заклинание чародейского покрова. Вы должны заслужить полное доверие Серебряного Рассвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DND FLAG Цитадель ужаса – Наксрамас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В чаще Чумного леса находится вход в цитадель ужаса, Наксрамас. Все попытки войти туда разбивались о могущественные чары, наложенные на портал. До сегодняшнего дня.$b$bМы придумали, как проникнуть внутрь при помощи чародейского покрова. Это старый трюк магов Кирин-Тора, над которым я хорошенько поработала. Поскольку твоя преданность делу Серебряного Рассвета не подлежит сомнению, мы возьмем на себя все издержки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный маг Анжела Досантос из Часовни Последней Надежды, что в Восточных Чумных землях, готова бесплатно наложить на вас заклинание чародейского покрова. Вы должны заслужить полное доверие Серебряного Рассвета.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9379,'Укрепить охотника Скверны','Приветствую, |3-6($c). Скажи Джир\'си здрасьте. Не бойся, он не кусается... пока я не разрешу.$B$B<Анжела успокаивающе свистит охотнику Скверны.>$B$BПо сравнению с астральными гончими, которые обитают в Запределье, он совсем крошка. Но скоро мы это исправим, правда, Джир\'си, моя лапочка?$B$BЯ думаю, мы найдем способ. Мне нужна кровь астральных гончих, именно поэтому я обратилась к тебе. Пока ты будешь охотиться за ними на юго-востоке, я подготовлю все для экпери... эээ... я хотела сказать, лечения.','Соберите 6 образцов крови астральной гончей и принесите их Анжеле "Коготь" Кестрел в Траллмар.','Вернитесь к Анжеле "Когтю" Кестрел на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укрепить охотника Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, |3-6($c). Скажи Джир\'си здрасьте. Не бойся, он не кусается... пока я не разрешу.$B$B<Анжела успокаивающе свистит охотнику Скверны.>$B$BПо сравнению с астральными гончими, которые обитают в Запределье, он совсем крошка. Но скоро мы это исправим, правда, Джир\'си, моя лапочка?$B$BЯ думаю, мы найдем способ. Мне нужна кровь астральных гончих, именно поэтому я обратилась к тебе. Пока ты будешь охотиться за ними на юго-востоке, я подготовлю все для экпери... эээ... я хотела сказать, лечения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 образцов крови астральной гончей и принесите их Анжеле "Коготь" Кестрел в Траллмар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анжеле "Когтю" Кестрел на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9380,'В погоне за большим','Клянусь, что если получу еще хоть одно письмо из Стальгорна...$B$BТы когда-нибудь $gпытался:пыталась; что-нибудь объяснить тому, кто тебя в упор слышать не хочет, а, |3-6($c)? Я послал этим парням из Стальгорна астральную гончую, которую они заказывали, но им, видите ли, нужна целая "упаковка" подобных созданий! Подумать только, – упаковка!$B$BЯ попытался им объяснить, что астральные гончие – одиночки, но они отказались меня слушать. Я уже понял, что вразумить их невозможно. Можешь собрать штук шесть самых лучших гончих, они встречаются к востоку от крепости, и принести сюда?','Соберите 6 неповрежденных трупов астральных гончих и доставьте в Оплот Чести геологу Мурантусу.','Вернитесь к геологу Мурантусу на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В погоне за большим',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клянусь, что если получу еще хоть одно письмо из Стальгорна...$B$BТы когда-нибудь $gпытался:пыталась; что-нибудь объяснить тому, кто тебя в упор слышать не хочет, а, |3-6($c)? Я послал этим парням из Стальгорна астральную гончую, которую они заказывали, но им, видите ли, нужна целая "упаковка" подобных созданий! Подумать только, – упаковка!$B$BЯ попытался им объяснить, что астральные гончие – одиночки, но они отказались меня слушать. Я уже понял, что вразумить их невозможно. Можешь собрать штук шесть самых лучших гончих, они встречаются к востоку от крепости, и принести сюда?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 неповрежденных трупов астральных гончих и доставьте в Оплот Чести геологу Мурантусу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Мурантусу на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9381,'Стрелы, бьющие без промаха','Вернитесь к сокольничему Дренне Речному Ветру в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стрелы, бьющие без промаха',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сокольничему Дренне Речному Ветру в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9383,'Честолюбивый план','Используйте Освященный кристалл против раненого неконтролируемого демона Бездны, затем возвращайтесь к Элшаане в Храм Телхамата.','Сработала ли магия кристалла против демона Бездны?','Вернитесь к Элшаане в Храм Телхамата, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Честолюбивый план',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте Освященный кристалл против раненого неконтролируемого демона Бездны, затем возвращайтесь к Элшаане в Храм Телхамата.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сработала ли магия кристалла против демона Бездны?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элшаане в Храм Телхамата, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9384,'<NYI>Пролить свет','Наконец-то пришло время уничтожить этого демона. Советую тебе соблюдать осторожность, $n, ты пока еще слишком мало знаешь о демонах Бездны.$B$BОтнеси этот сосуд Рамату, пусть он займется уничтожением. А ты внимательно наблюдай за процессом. После завершения расскажешь, как все прошло.','Отнесите сияющий освященный кристалл Рамату в Храм Шанаара, чтобы он вознес моление Свету и уничтожил демона.','Вернитесь к Элшаане на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI>Пролить свет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то пришло время уничтожить этого демона. Советую тебе соблюдать осторожность, $n, ты пока еще слишком мало знаешь о демонах Бездны.$B$BОтнеси этот сосуд Рамату, пусть он займется уничтожением. А ты внимательно наблюдай за процессом. После завершения расскажешь, как все прошло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сияющий освященный кристалл Рамату в Храм Шанаара, чтобы он вознес моление Свету и уничтожил демона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Элшаане на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9385,'Разъяренные Опустошители','Оплот Чести послал нас разобраться с араккоа, и мы разбили здесь лагерь, думая, что никто нас не потревожит. Как выяснилось, мы встали слишком близко к перозубым опустошителям.$B$BЭти безжалостные твари сводят на нет всю нашу работу. Мы заплатим тебе, если ты с ними разделаешься. Ну что, по рукам?','Как продвигается охота на опустошителей?','Вернитесь к Гремни Длиннобороду на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разъяренные Опустошители',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оплот Чести послал нас разобраться с араккоа, и мы разбили здесь лагерь, думая, что никто нас не потревожит. Как выяснилось, мы встали слишком близко к перозубым опустошителям.$B$BЭти безжалостные твари сводят на нет всю нашу работу. Мы заплатим тебе, если ты с ними разделаешься. Ну что, по рукам?',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигается охота на опустошителей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гремни Длиннобороду на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9386,'Свет в темных местах','Неужели тебе этого так хочется? Ну что ж, если снова желаешь спуститься в глубины, я с радостью тебя вознагражу. $b$bОтыщи костры, горящие в Стратхольме, Некроситете, Забытом Городе и в залах самого Пика Черной горы. Я буду ждать твоего возвращения, $n.','Найдите костры, размещенные в Пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени.','Ты $Gдоказал:доказала;, что ты не совсем $Gбесполезный:бесполезная; $Gсмертный:смертная;.','Вернитесь к хранителю праздничного пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Свет в темных местах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неужели тебе этого так хочется? Ну что ж, если снова желаешь спуститься в глубины, я с радостью тебя вознагражу. $b$bОтыщи костры, горящие в Стратхольме, Некроситете, Забытом Городе и в залах самого Пика Черной горы. Я буду ждать твоего возвращения, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите костры, размещенные в Пике Черной горы, Забытом Городе, Некроситете и Стратхольме и коснитесь их; затем поговорите с хранителем праздничного пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gдоказал:доказала;, что ты не совсем $Gбесполезный:бесполезная; $Gсмертный:смертная;.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю праздничного пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9387,'Источник осквернения','Все дренеи, не попавшие под влияние Скверны, – истинные паладины Света, и наш невезучий приятель не исключение. Но мне интересно, как Скверна смогла низвести эту великую расу до Сломленных и Заблудших.$B$BЯ слышал о теории, что мутацию вызывает энергия Скверны. Я хочу ее проверить.$B$BК северо-западу отсюда лежат Руины Ша\'наара. Туда иллидарские надсмотрщики согнали Сломленных. Принеси мне несколько демонических сущностей, которые можно добыть из надсмотрщиков, и я проверю их на этом дренее.','Ты добыла образцы?','Вернитесь к Аптекарю Азетену в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник осквернения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все дренеи, не попавшие под влияние Скверны, – истинные паладины Света, и наш невезучий приятель не исключение. Но мне интересно, как Скверна смогла низвести эту великую расу до Сломленных и Заблудших.$B$BЯ слышал о теории, что мутацию вызывает энергия Скверны. Я хочу ее проверить.$B$BК северо-западу отсюда лежат Руины Ша\'наара. Туда иллидарские надсмотрщики согнали Сломленных. Принеси мне несколько демонических сущностей, которые можно добыть из надсмотрщиков, и я проверю их на этом дренее.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты добыла образцы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аптекарю Азетену в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9388,'Мерцающие огни Калимдора','Сегодня по всему миру горит множество огней, $n. Сложнее всего присматривать за теми кострами, которые пылают зеленым; без присмотра они не будут гореть долго. Убедись, что изумрудные огни все еще горят в Калимдоре – пусть наш Хранитель костров успокоится.$b$bТы найдешь эти костры вблизи Кабестана в Степях, неподалеку от Меча Властителя на Темных берегах, в Ясеневом лесу у моста около Аванпоста Среброкрылых, и поблизости от дороги на Утес Ветрорезов вдоль главного тракта в Когтистых горах.','Посетите праздничные костры в Ясеневом лесу, Степях, на Темных берегах и в Когтистых горах, затем поговорите с хранителем праздничного пламени.','Ах, так значит, они все еще горят. Отлично, ты $Gпроделал:проделала; превосходную работу, $N. Вот, возьми это и будь $Gблагословен:благословенна;.','Пока идет праздник, огни не должны погаснуть!','Вернитесь к хранителю праздничного пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мерцающие огни Калимдора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня по всему миру горит множество огней, $n. Сложнее всего присматривать за теми кострами, которые пылают зеленым; без присмотра они не будут гореть долго. Убедись, что изумрудные огни все еще горят в Калимдоре – пусть наш Хранитель костров успокоится.$b$bТы найдешь эти костры вблизи Кабестана в Степях, неподалеку от Меча Властителя на Темных берегах, в Ясеневом лесу у моста около Аванпоста Среброкрылых, и поблизости от дороги на Утес Ветрорезов вдоль главного тракта в Когтистых горах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посетите праздничные костры в Ясеневом лесу, Степях, на Темных берегах и в Когтистых горах, затем поговорите с хранителем праздничного пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, так значит, они все еще горят. Отлично, ты $Gпроделал:проделала; превосходную работу, $N. Вот, возьми это и будь $Gблагословен:благословенна;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пока идет праздник, огни не должны погаснуть!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю праздничного пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9389,'Мерцающие огни Восточных королевств','Итак, ты $Gвернулся:вернулась; и $Gвидел:видела; эти изумрудные огни. Что ты о них думаешь, а? Редкое и удивительное зрелище, не так ли?. Что ж, ты $Gпровел:провела; превосходную работу... пожалуйста, возьми это в знак моей благодарности.','Тебе уже удалось проверить огни?','Вернитесь к хранителю праздничного пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мерцающие огни Восточных королевств',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, ты $Gвернулся:вернулась; и $Gвидел:видела; эти изумрудные огни. Что ты о них думаешь, а? Редкое и удивительное зрелище, не так ли?. Что ж, ты $Gпровел:провела; превосходную работу... пожалуйста, возьми это в знак моей благодарности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе уже удалось проверить огни?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю праздничного пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (9390,'Найти Седаи','Выслушай меня, |3-6($c). Мой брат Седаи отправился на встречу с орками Заставы маг\'харов. Этот несчастный идеалист считал, что время излечило взаимные обиды, и мы сможем договориться о мире.$B$BУже несколько дней о нем ничего не слышно, и я опасаюсь самого худшего.$B$BМожешь отправиться на его поиски и дать отдых моей измученной душе? Седаи должен быть где-то на востоке.','Вы находите тело юного дренейского паладина. Он убит стрелой в спину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Седаи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Выслушай меня, |3-6($c). Мой брат Седаи отправился на встречу с орками Заставы маг\'харов. Этот несчастный идеалист считал, что время излечило взаимные обиды, и мы сможем договориться о мире.$B$BУже несколько дней о нем ничего не слышно, и я опасаюсь самого худшего.$B$BМожешь отправиться на его поиски и дать отдых моей измученной душе? Седаи должен быть где-то на востоке.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы находите тело юного дренейского паладина. Он убит стрелой в спину.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9391,'Осветить путь','Теперь, когда численность камнедеров уменьшилась, надо указать пилигримам безопасную дорогу. Возьми этот факел и возвращайся к Глубокому Разлому. Разыщи там три маяка, которые стоят вдоль дороги на восток.$B$BЗажги их, и после этого возвращайся ко мне. Будь $gосторожен:осторожна; – огонь маяков наверняка привлечет камнедеров.','Глубокий Разлом все еще опасен, но, по крайней мере, там можно пройти.\n\nЕсли бы Альянс не караулил все известные нам дороги, вряд ли бы мы решили на такое дело.','Вернитесь к капитану следопытов Венн\'рену в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осветить путь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда численность камнедеров уменьшилась, надо указать пилигримам безопасную дорогу. Возьми этот факел и возвращайся к Глубокому Разлому. Разыщи там три маяка, которые стоят вдоль дороги на восток.$B$BЗажги их, и после этого возвращайся ко мне. Будь $gосторожен:осторожна; – огонь маяков наверняка привлечет камнедеров.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Глубокий Разлом все еще опасен, но, по крайней мере, там можно пройти.\n\nЕсли бы Альянс не караулил все известные нам дороги, вряд ли бы мы решили на такое дело.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану следопытов Венн\'рену в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`requestitemstext_loc8`) VALUES (9394,'Удалось ли тебе отключить источники энергии? Мне отсюда плохо видно...') ON DUPLICATE KEY UPDATE `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе отключить источники энергии? Мне отсюда плохо видно...',`requestitemstext_loc8`);
