INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9396,'Магия араккоа','Вернитесь к чародею Калестрису Утренней Звезде в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магия араккоа',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Калестрису Утренней Звезде в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9397,'Пух и перья','Ты вернулась. принесла самку калири?','Вернитесь к сокольничему Дренне Речному Ветру в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пух и перья',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулась. принесла самку калири?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сокольничему Дренне Речному Ветру в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9398,'Смертельно опасные хищники','В Запределье Сломленные не испытывали ничего, кроме насилия и жестокости. Не удивительно, как только открылся Темный портал, они кинулись к нему, стремясь выбраться из этого мира.$B$BК несчастью для наших ошеломленных братьев и сестер, пришедших с юга, они стали легкой добычей для камнедеров Глубокого Разлома. Если хочешь помочь выжить моему племени, отправляйся к Разлому и уничтожь хищников.','Вернитесь к разведчице Вануре в Храм Телхамата на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смертельно опасные хищники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Запределье Сломленные не испытывали ничего, кроме насилия и жестокости. Не удивительно, как только открылся Темный портал, они кинулись к нему, стремясь выбраться из этого мира.$B$BК несчастью для наших ошеломленных братьев и сестер, пришедших с юга, они стали легкой добычей для камнедеров Глубокого Разлома. Если хочешь помочь выжить моему племени, отправляйся к Разлому и уничтожь хищников.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчице Вануре в Храм Телхамата на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9399,'Безжалостные десятники','Ты думаешь, все Сломленные несут в себе семена зла? На самом деле, очень многое зависит от обстоятельств. Пока я не встретил Оменай, меня тоже можно было считать потерянным.$B$BНаш разум сильно пострадал от воздействия демонической магии орков. В таком состоянии очень легко сбиться с пути и лишиться воли.$B$BДемоны, заключившие союз с Иллиданом, день за днем обыскивали Адское Пламя, находили нас и делали своими рабами. Оменай принесли нам надежду. Если хочешь, чтобы мои родичи обрели свободу, отправляйся к Руинам Ша\'наара, что на юго-западе отсюда, и убей иллидарских надсмотрщиков.','Ты $gвернулся:вернулась;! Тебе удалось освободить моих братьев?','Вернитесь к Икану в Храм Телхамата на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безжалостные десятники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты думаешь, все Сломленные несут в себе семена зла? На самом деле, очень многое зависит от обстоятельств. Пока я не встретил Оменай, меня тоже можно было считать потерянным.$B$BНаш разум сильно пострадал от воздействия демонической магии орков. В таком состоянии очень легко сбиться с пути и лишиться воли.$B$BДемоны, заключившие союз с Иллиданом, день за днем обыскивали Адское Пламя, находили нас и делали своими рабами. Оменай принесли нам надежду. Если хочешь, чтобы мои родичи обрели свободу, отправляйся к Руинам Ша\'наара, что на юго-западе отсюда, и убей иллидарских надсмотрщиков.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gвернулся:вернулась;! Тебе удалось освободить моих братьев?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Икану в Храм Телхамата на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9400,'Убийца','Тело соответствует описанию Круна Хребтолома, убийцы из Цитадели Адского Пламени. Перевернув тело, вы замечаете, что из его спины торчит каменный топор.','Разыщите убийцу по имени Крун Хребтолом','Обследуйте труп орка Скверны на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убийца',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тело соответствует описанию Круна Хребтолома, убийцы из Цитадели Адского Пламени. Перевернув тело, вы замечаете, что из его спины торчит каменный топор.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Разыщите убийцу по имени Крун Хребтолом',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Обследуйте труп орка Скверны на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (9401,'Странное оружие','Вы вытаскиваете каменный топор из тела, чтобы рассмотреть его повнимательней. В этом оружии есть что-то необычное.$B$BВроде бы сделано орками, но вы раньше никогда не видели, чтобы орки работали с таким материалом. Возможно, топор следует показать Назгрелу.','Скажи, убийца мертв?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странное оружие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы вытаскиваете каменный топор из тела, чтобы рассмотреть его повнимательней. В этом оружии есть что-то необычное.$B$BВроде бы сделано орками, но вы раньше никогда не видели, чтобы орки работали с таким материалом. Возможно, топор следует показать Назгрелу.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Скажи, убийца мертв?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9402,'Апорт!','Ты кто? $n? Можешь не зазнаваться от того, что я знаю тебя по имени: $gодна из моих студенток:один из моих студентов; только о тебе и твердит.$b$bХм... если уж ты хочешь произвести на $gнее:него; впечатление, отчего бы тебе не оказать мне услугу? На дне пруда, что позади меня, лежит лазурный фиал. Нырни, добудь его и принеси сюда.','Нырните на дно пруда Тихого Шелеста и добудьте лазурный фиал для инструктора Антеола.','Что ж, $Gмолодец:умница;, $Gмолодец:умница;... Стоило мне попросить тебя прыгнуть в пруд, и ты это $Gсделал:сделала;! Интересно, чего бы ты не $Gсделал:сделала;, если бы тебя попросил об этом один из лучших друзей!$B$BЕсли ты ждешь награды за труд, вот тебе в награду совет: никогда не берись за дело, не узнав сначала, что ты с этого будешь иметь. Главное оружие мага – это его ум. Запомни это и постарайся впредь первым делом пускать в ход мозги.','Ну, как водичка?','Вернитесь к инструктору Антеолу на Пруд Тихого Шелеста, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Апорт!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты кто? $n? Можешь не зазнаваться от того, что я знаю тебя по имени: $gодна из моих студенток:один из моих студентов; только о тебе и твердит.$b$bХм... если уж ты хочешь произвести на $gнее:него; впечатление, отчего бы тебе не оказать мне услугу? На дне пруда, что позади меня, лежит лазурный фиал. Нырни, добудь его и принеси сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нырните на дно пруда Тихого Шелеста и добудьте лазурный фиал для инструктора Антеола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, $Gмолодец:умница;, $Gмолодец:умница;... Стоило мне попросить тебя прыгнуть в пруд, и ты это $Gсделал:сделала;! Интересно, чего бы ты не $Gсделал:сделала;, если бы тебя попросил об этом один из лучших друзей!$B$BЕсли ты ждешь награды за труд, вот тебе в награду совет: никогда не берись за дело, не узнав сначала, что ты с этого будешь иметь. Главное оружие мага – это его ум. Запомни это и постарайся впредь первым делом пускать в ход мозги.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как водичка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Антеолу на Пруд Тихого Шелеста, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9403,'Чистейшая вода','Ну а теперь, когда ты кое-чему $gнаучился:научилась;, я тебе предложу кое-что более существенное. Речь идет о твоей способности защищаться в ближнем бою. Разумеется, лучше вообще не вступать в бой без крайней необходимости, но нужно быть $gготовым:готовой; ко всему.$b$bЯ могу помочь тебе изготовить посох, подобающий магу. Для начала возьми флакон, добытый тобою со дна, и наполни его водой у подножия водопада Элрендар. Ступай вдоль реки на юго-восток, и увидишь водопад.','Наполните лазурный флакон водой из водопада Элрендар для Антеола.','Ну-с, посмотрим, что там у тебя…$B$B<Антеол рассматривает флакон на просвет.>$B$BДа, это подойдет. $GМолодец:Умница;, $N.','Только вода из водопада Элрендар достаточно чиста, чтобы использовать ее в магии! Есть ли у тебя такая вода?','Вернитесь к инструктору Антеолу на Пруд Тихого Шелеста, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чистейшая вода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну а теперь, когда ты кое-чему $gнаучился:научилась;, я тебе предложу кое-что более существенное. Речь идет о твоей способности защищаться в ближнем бою. Разумеется, лучше вообще не вступать в бой без крайней необходимости, но нужно быть $gготовым:готовой; ко всему.$b$bЯ могу помочь тебе изготовить посох, подобающий магу. Для начала возьми флакон, добытый тобою со дна, и наполни его водой у подножия водопада Элрендар. Ступай вдоль реки на юго-восток, и увидишь водопад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните лазурный флакон водой из водопада Элрендар для Антеола.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну-с, посмотрим, что там у тебя…$B$B<Антеол рассматривает флакон на просвет.>$B$BДа, это подойдет. $GМолодец:Умница;, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Только вода из водопада Элрендар достаточно чиста, чтобы использовать ее в магии! Есть ли у тебя такая вода?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Антеолу на Пруд Тихого Шелеста, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9404,'Живая ветка','Тебе, наверное, случалось видеть ходячие деревья вблизи водопада Элрендар? Эти хранители природы пронизаны первородной магией, которую мы можем использовать в собственных целях с помощью чистой воды, которую ты уже $gпринес:принесла; мне.$b$bК несчастью, наши хранители леса такие древние и ветхие, что тебе, возможно, придется перебить нескольких из них, прежде чем удастся найти хоть одну живую ветку.','Ты $Gвыполнил:выполнила; мою просьбу, $N, и можешь получить заслуженную награду.','Ну что, где ветка? Неси ее скорее!','Вернитесь к инструктору Антеолу на Пруд Тихого Шелеста, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Живая ветка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе, наверное, случалось видеть ходячие деревья вблизи водопада Элрендар? Эти хранители природы пронизаны первородной магией, которую мы можем использовать в собственных целях с помощью чистой воды, которую ты уже $gпринес:принесла; мне.$b$bК несчастью, наши хранители леса такие древние и ветхие, что тебе, возможно, придется перебить нескольких из них, прежде чем удастся найти хоть одну живую ветку.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gвыполнил:выполнила; мою просьбу, $N, и можешь получить заслуженную награду.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где ветка? Неси ее скорее!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инструктору Антеолу на Пруд Тихого Шелеста, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9405,'Поручение Вождя','Как известно, вождь затеял экспедицию только с одной целью. Это мир, из которого мы пришли. Там наши корни.$B$BВ этом путешествии у орков и эльфов крови разные цели. В отличие от нас, они ищут землю обетованную.$B$BКто бы не создал этот топор, он знаком с прежними днями и мы должны найти его. Дело слишком важное, чтобы использовать обычный способ поиска. Покажи топор провозвестнице Регулкут, она скажет, что делать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поручение Вождя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как известно, вождь затеял экспедицию только с одной целью. Это мир, из которого мы пришли. Там наши корни.$B$BВ этом путешествии у орков и эльфов крови разные цели. В отличие от нас, они ищут землю обетованную.$B$BКто бы не создал этот топор, он знаком с прежними днями и мы должны найти его. Дело слишком важное, чтобы использовать обычный способ поиска. Покажи топор провозвестнице Регулкут, она скажет, что делать.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9406,'Маг\'хары','Новости, которые ты $gпринес:принесла; о другой земле за Темным порталом... Я должен поверить, что вся земля там принадлежит сыну Дуротана... и свободна от демонической скверны? Но как его народ смог вернуться в этот мир?$B$BНадеюсь, для твоего же блага, что это не шутка, |3-6($c). Новость, которую ты $gпринес:принесла; слишком много для нас значит. Я немедленно отправлю донесение в Награнд! Адский Крик должен узнать об этом!$B$BОтнеси письмо обратно в Траллмар, своему командиру. Скажи, что маг\'харские орки шлют ему привет!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маг\'хары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Новости, которые ты $gпринес:принесла; о другой земле за Темным порталом... Я должен поверить, что вся земля там принадлежит сыну Дуротана... и свободна от демонической скверны? Но как его народ смог вернуться в этот мир?$B$BНадеюсь, для твоего же блага, что это не шутка, |3-6($c). Новость, которую ты $gпринес:принесла; слишком много для нас значит. Я немедленно отправлю донесение в Награнд! Адский Крик должен узнать об этом!$B$BОтнеси письмо обратно в Траллмар, своему командиру. Скажи, что маг\'харские орки шлют ему привет!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9407,'Много лет Темный портал оставался безмолвным... забытым. Но теперь он проснулся.$B$BПосле того как наши войска отразили нападение демонов, они пробились через портал и встретились с врагом на его территории!$B$BНыне мы втянуты в безжалостную войну, и кое-кто думает, что мы не сможем победить. Наш долг, наша мрачная радость – сразиться с демонами в Запределье, обеспечив нашу победу. $B$BЕсли ты хочешь помочь нам, $n, то немедленно сообщи об этом генерал-лейтенанту Ориону. Он ждет тебя в Запределье...','Пройдите через Темный портал и найдите генерал-лейтенанта Ориона. Он ждет вашего прибытия на другой стороне, в Запределье.','Наша экспедиция благополучно прошла через портал и основала новую базу, именуемую Траллмар. Но, как ты видишь, Пылающий Легион своим вторжением отрезал нас от наших собратьев. Любому понятно, что демоны надеются отбить Темный портал и не позволить нам получить подкрепление с Азерота.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много лет Темный портал оставался безмолвным... забытым. Но теперь он проснулся.$B$BПосле того как наши войска отразили нападение демонов, они пробились через портал и встретились с врагом на его территории!$B$BНыне мы втянуты в безжалостную войну, и кое-кто думает, что мы не сможем победить. Наш долг, наша мрачная радость – сразиться с демонами в Запределье, обеспечив нашу победу. $B$BЕсли ты хочешь помочь нам, $n, то немедленно сообщи об этом генерал-лейтенанту Ориону. Он ждет тебя в Запределье...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите через Темный портал и найдите генерал-лейтенанта Ориона. Он ждет вашего прибытия на другой стороне, в Запределье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наша экспедиция благополучно прошла через портал и основала новую базу, именуемую Траллмар. Но, как ты видишь, Пылающий Легион своим вторжением отрезал нас от наших собратьев. Любому понятно, что демоны надеются отбить Темный портал и не позволить нам получить подкрепление с Азерота.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9408,'Забытые герои','Мы потеряли уже столько солдат в битве за этот портал, но по-прежнему продолжаем держать оборону.$B$BТрудно поверить, но эта крепость, – живое свидетельство стойкости солдат Альянса.$B$BЗдесь находится один из великих героев – Данат Троллебой! Разыщи его, |3-6($c). Он поговорил с каждым солдатом, и, несомненно, захочет видеть и тебя.','Поговорите с командиром армии Данатом Троллебоем в Оплоте Чести.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Забытые герои',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы потеряли уже столько солдат в битве за этот портал, но по-прежнему продолжаем держать оборону.$B$BТрудно поверить, но эта крепость, – живое свидетельство стойкости солдат Альянса.$B$BЗдесь находится один из великих героев – Данат Троллебой! Разыщи его, |3-6($c). Он поговорил с каждым солдатом, и, несомненно, захочет видеть и тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром армии Данатом Троллебоем в Оплоте Чести.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9409,'Срочная доставка','Благодаря тебе мы собрали все необходимое, чтобы зарядить исцеляющие кристаллы. Отнеси эти фиалы Зальдууну, нашему жрецу. Он ухаживает за ранеными в центральной части корабля.','Отнесите сверток с фиалами Зальдууну на место крушения в долине Аммен.','Отличная работа! Эта кровь прекрасно подойдет для наших исцеляющих кристаллов.$b$bРаз уж ты здесь, у меня найдется для тебя поручение. Ты не против?','Привет тебе, |3-6($c). Что ты несешь? Это мне?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Срочная доставка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря тебе мы собрали все необходимое, чтобы зарядить исцеляющие кристаллы. Отнеси эти фиалы Зальдууну, нашему жрецу. Он ухаживает за ранеными в центральной части корабля.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сверток с фиалами Зальдууну на место крушения в долине Аммен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа! Эта кровь прекрасно подойдет для наших исцеляющих кристаллов.$b$bРаз уж ты здесь, у меня найдется для тебя поручение. Ты не против?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет тебе, |3-6($c). Что ты несешь? Это мне?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9410,'Хранитель душ','Их возможности превосходят нюх наших самых лучших волков, $n. У духов есть свой способ отыскать кого-то. Ты призовешь существо, которое чует не запах, но сущность.$B$BА теперь ступай, |3-6($c). Возьми с собой этот тотем и установи его там, где $gнашел:нашла; каменный топор.','Установите тотем духа волка на том месте, где вы нашли тело Круна Хребтолома. Когда появится дух древнего волка, следуйте за ним.','Тебе повезло остаться в живых.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранитель душ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Их возможности превосходят нюх наших самых лучших волков, $n. У духов есть свой способ отыскать кого-то. Ты призовешь существо, которое чует не запах, но сущность.$B$BА теперь ступай, |3-6($c). Возьми с собой этот тотем и установи его там, где $gнашел:нашла; каменный топор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите тотем духа волка на том месте, где вы нашли тело Круна Хребтолома. Когда появится дух древнего волка, следуйте за ним.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе повезло остаться в живых.',`requestitemstext_loc8`);
