INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9415,'Маршал Синяя Синестен','Ты новобранец маршала Синестена? Ну, конечно.$b$bЧего ты ждешь? Наши солдаты умирают там, в пустыне. Правда, тебе не терпится к ним присоединиться?$b$bИди, и смотри, не присохни к песку по пути.','Поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маршал Синяя Синестен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты новобранец маршала Синестена? Ну, конечно.$b$bЧего ты ждешь? Наши солдаты умирают там, в пустыне. Правда, тебе не терпится к ним присоединиться?$b$bИди, и смотри, не присохни к песку по пути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9416,'Генерал Кирика','Должно быть, ты $gодин:одна; из новобранцев генерала Кирики. Пора тебе браться за дело. В пустыне тела очень быстро портятся.$b$bДворфы ежедневно получают подкрепление, а мы не должны им уступать. Полезные ископаемые Силитуса наши!$b$bГенерал тебя проинструктирует. Не мое дело – учить тебя. Мне приказали только найти тебя.','Поговорите с генералом Кирикой в лагере Орды рядом с Ульем Регал.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Генерал Кирика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Должно быть, ты $gодин:одна; из новобранцев генерала Кирики. Пора тебе браться за дело. В пустыне тела очень быстро портятся.$b$bДворфы ежедневно получают подкрепление, а мы не должны им уступать. Полезные ископаемые Силитуса наши!$b$bГенерал тебя проинструктирует. Не мое дело – учить тебя. Мне приказали только найти тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с генералом Кирикой в лагере Орды рядом с Ульем Регал.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9417,'Угроза Араккоа','Ты $gвернулся:вернулась;! Как дела?','Вернитесь к Гремни Длиннобороду на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза Араккоа',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gвернулся:вернулась;! Как дела?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гремни Длиннобороду на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (9418,'Сфера Авруу','Наконец-то я на свободе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сфера Авруу',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наконец-то я на свободе!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9419,'Истощение пустыни','Совсем недавно мы выяснили, что Орда добывает в Силитусе полезные ископаемые. Мы думали, что в таком климате не стоит держать много войск.$b$bК сожалению, выяснилось, насколько важны эти полезные ископаемые, и теперь мы тщетно пытаемся догнать Орду по масштабам добычи.$b$bЕсли ты хочешь мне помочь, ступай в пустыню и принеси оттуда силитист.','Найдите и принесите силитист к экстрактору силитистов и поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора.','Соблюдай осторожность, но не медли. Время на исходе.','Вернитесь к маршалу Синестену в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истощение пустыни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Совсем недавно мы выяснили, что Орда добывает в Силитусе полезные ископаемые. Мы думали, что в таком климате не стоит держать много войск.$b$bК сожалению, выяснилось, насколько важны эти полезные ископаемые, и теперь мы тщетно пытаемся догнать Орду по масштабам добычи.$b$bЕсли ты хочешь мне помочь, ступай в пустыню и принеси оттуда силитист.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и принесите силитист к экстрактору силитистов и поговорите с маршалом Синестеном в лагере Альянса возле Улья Зора.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Соблюдай осторожность, но не медли. Время на исходе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к маршалу Синестену в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9420,'Прекрасное оперение','Вернитесь к Миррену Длиннобороду на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прекрасное оперение',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миррену Длиннобороду на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9421,'Обучение шамана','Я Фирманваар и ты $Gпоступил:поступила; правильно, отыскав меня. Мое призвание - давать наставления $C, особенно тем, кто только начинает свой путь. $B$BШаманизм сейчас изучают только среди $R, $N. Я буду здесь как только ты поймешь, что $Gготов:готова; к дальнейшему обучению.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение шамана',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я Фирманваар и ты $Gпоступил:поступила; правильно, отыскав меня. Мое призвание - давать наставления $C, особенно тем, кто только начинает свой путь. $B$BШаманизм сейчас изучают только среди $R, $N. Я буду здесь как только ты поймешь, что $Gготов:готова; к дальнейшему обучению.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9422,'Истощение пустыни','Мы давно начали добычу кристаллов пустыни Силитуса. Поначалу мы сталкивались лишь с опасностями, исходящими от местных жителей, песка, пыли и жары.$b$bТеперь же Альянс пронюхал, чем мы тут занимаемся, и началась гонка за добычей полезных ископаемых.$b$bУ меня каждая пара рук на счету, надеюсь, ты мне тоже поможешь.','Найдите и принесите силитист к экстрактору силитистов и поговорите с генералом Кирикой в лагере Орды возле Улья Регал.','Будь $Gосторожен:осторожна; в пустыне, $N. Альянс скрывается в дюнах, любой шаг, может стать твоим последним.','Вернитесь к генералу Кирике в Улей Регал, что в Силитусе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истощение пустыни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы давно начали добычу кристаллов пустыни Силитуса. Поначалу мы сталкивались лишь с опасностями, исходящими от местных жителей, песка, пыли и жары.$b$bТеперь же Альянс пронюхал, чем мы тут занимаемся, и началась гонка за добычей полезных ископаемых.$b$bУ меня каждая пара рук на счету, надеюсь, ты мне тоже поможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и принесите силитист к экстрактору силитистов и поговорите с генералом Кирикой в лагере Орды возле Улья Регал.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будь $Gосторожен:осторожна; в пустыне, $N. Альянс скрывается в дюнах, любой шаг, может стать твоим последним.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к генералу Кирике в Улей Регал, что в Силитусе.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9423,'Возвращение к Обадию','Вы получили подтверждение смерти Седаи, так что придется вернуться к Обадию с мрачными новостями.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Обадию',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы получили подтверждение смерти Седаи, так что придется вернуться к Обадию с мрачными новостями.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9424,'Месть Макуру','Седаи был Макуру как брат. Мы все обязаны ему жизнью. Оменай называют Макуру безумным, но если они не станут мстить за Седаи, то они сами лишились ума!$B$BВ этом мире немногое принадлежит Макуру, но он отдаст тебе все, чем обладает, если ты отомстишь за Седаи.$B$BЯ видел маг\'харских рубак в холмах к северо-востоку. Они нас ненавидят! Они не заслуживают нашей пощады! Ступай, отомсти за Седаи! В качестве доказательства смерти принеси их ожерелья предков.','Вернитесь к Макуру в Храм Телхамата на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Макуру',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Седаи был Макуру как брат. Мы все обязаны ему жизнью. Оменай называют Макуру безумным, но если они не станут мстить за Седаи, то они сами лишились ума!$B$BВ этом мире немногое принадлежит Макуру, но он отдаст тебе все, чем обладает, если ты отомстишь за Седаи.$B$BЯ видел маг\'харских рубак в холмах к северо-востоку. Они нас ненавидят! Они не заслуживают нашей пощады! Ступай, отомсти за Седаи! В качестве доказательства смерти принеси их ожерелья предков.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Макуру в Храм Телхамата на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9425,'Возвращение в Мельницу Таррен','Рад видеть тебя, |3-6($c)! У меня есть задание как раз для тебя.$B$BМы лишь недавно вступили в Орду и должны убедить всех, что готовы их поддерживать и помогать в трудную минуту. Тогда и они с большей готовностью придут нам на помощь.$B$BСтупай в город Отрекшихся – Мельницу Таррен. Он расположен в предгорьях Хилсбрада, на юго-востоке. По прибытии поговори с советницей Вечерней Зарей.','Отправляйтесь в Мельницу Таррен в предгорьях Хилсбрада и поговорите с советницей Вечерней Зарей.','Ну и ну! Еще одна из моих сестер. Отлично! Нам предстоит многое сделать для наших новых друзей-Отрекшихся. Пройдись по городу и выясни, кому из жителей нужна помощь.\n\nНе сомневаюсь, ты найдешь время, чтобы помочь всем!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Мельницу Таррен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рад видеть тебя, |3-6($c)! У меня есть задание как раз для тебя.$B$BМы лишь недавно вступили в Орду и должны убедить всех, что готовы их поддерживать и помогать в трудную минуту. Тогда и они с большей готовностью придут нам на помощь.$B$BСтупай в город Отрекшихся – Мельницу Таррен. Он расположен в предгорьях Хилсбрада, на юго-востоке. По прибытии поговори с советницей Вечерней Зарей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Мельницу Таррен в предгорьях Хилсбрада и поговорите с советницей Вечерней Зарей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну и ну! Еще одна из моих сестер. Отлично! Нам предстоит многое сделать для наших новых друзей-Отрекшихся. Пройдись по городу и выясни, кому из жителей нужна помощь.\n\nНе сомневаюсь, ты найдешь время, чтобы помочь всем!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9426,'Пруды Аггонара','Много времени прошло с тех пор, как мы назвали эту землю Дренором. Демоническая печать безвозвратно ее изменила.$B$BЯ помню одно место, сейчас его называют Пруды Аггонара. Когда-то там били благословенные источники, теперь же кровь демона Аггонара запятнала их самую суть. Оскверненная кровь породила гнусных тварей, от которых надо избавиться, если мы хотим очистить эти пруды. Ступай к востоку, к прудам, и уничтожь исчадья ужаса и прочую нечисть, которая там развелась.','Вернитесь к Амаану Мудрейшему в Храм Телхамата на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пруды Аггонара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Много времени прошло с тех пор, как мы назвали эту землю Дренором. Демоническая печать безвозвратно ее изменила.$B$BЯ помню одно место, сейчас его называют Пруды Аггонара. Когда-то там били благословенные источники, теперь же кровь демона Аггонара запятнала их самую суть. Оскверненная кровь породила гнусных тварей, от которых надо избавиться, если мы хотим очистить эти пруды. Ступай к востоку, к прудам, и уничтожь исчадья ужаса и прочую нечисть, которая там развелась.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амаану Мудрейшему в Храм Телхамата на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9427,'Очищение вод','Я прошу тебя закончить дело, которое мы начали. Теперь, когда демоническое влияние ослабело, ты $gдолжен:должна; взять фиал Очищения и вылить его содержимое на сам источник скверны – тело Аггонара.$B$BКости демона лежат в самой северной части прудов. Будь $gосторожен:осторожна;, я думаю, что сущность Аггонара не полностью оставила этот мир.','Отправляйтесь к прудам Аггонара и используйте Фиал Очищения над телом Аггонара по просьбе Амаана Мудрейшего. После того как вода будет очищена от сущности Аггонара, возвращайтесь обратно к Амаану.','Вернитесь к Амаану Мудрейшему в Храм Телхамата на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение вод',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прошу тебя закончить дело, которое мы начали. Теперь, когда демоническое влияние ослабело, ты $gдолжен:должна; взять фиал Очищения и вылить его содержимое на сам источник скверны – тело Аггонара.$B$BКости демона лежат в самой северной части прудов. Будь $gосторожен:осторожна;, я думаю, что сущность Аггонара не полностью оставила этот мир.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к прудам Аггонара и используйте Фиал Очищения над телом Аггонара по просьбе Амаана Мудрейшего. После того как вода будет очищена от сущности Аггонара, возвращайтесь обратно к Амаану.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амаану Мудрейшему в Храм Телхамата на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9428,'Явиться на Заставу Расщепленного Дерева','<Посланница наклоняется поближе и переходит на шепот.>$b$bТвоя слава обгоняет тебя, $n! Я прошу тебя отправиться на Заставу Расщепленного Дерева в Ясеневом лесу. Пешком туда проще всего добраться, если идти на запад через Дуротар и Степи, а потом на развилке повернуть на север.$b$bКогда прибудешь туда, поговори с советником Верным Солнцу. Только осторожнее, Ясеневый лес – место опасное!','Поговорите с советником Верным Солнцу на Заставе Расщепленного Дерева в Ясеневом лесу.','Посол заранее сообщил, поэтому я вас ждал. $B$BПосол просто хочет, чтобы вы сделали все возможное, чтобы помочь. Она сказала что-то о том, чтобы укрепить наши отношения с остальной частью Орды. $B$BСпросите у всех - на Посту есть и другие, нуждающиеся в помощи. И я слышал, что на побережье к западу есть еще один форпост Орды, который называется Зорам\'гар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Явиться на Заставу Расщепленного Дерева',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Посланница наклоняется поближе и переходит на шепот.>$b$bТвоя слава обгоняет тебя, $n! Я прошу тебя отправиться на Заставу Расщепленного Дерева в Ясеневом лесу. Пешком туда проще всего добраться, если идти на запад через Дуротар и Степи, а потом на развилке повернуть на север.$b$bКогда прибудешь туда, поговори с советником Верным Солнцу. Только осторожнее, Ясеневый лес – место опасное!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с советником Верным Солнцу на Заставе Расщепленного Дерева в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посол заранее сообщил, поэтому я вас ждал. $B$BПосол просто хочет, чтобы вы сделали все возможное, чтобы помочь. Она сказала что-то о том, чтобы укрепить наши отношения с остальной частью Орды. $B$BСпросите у всех - на Посту есть и другие, нуждающиеся в помощи. И я слышал, что на побережье к западу есть еще один форпост Орды, который называется Зорам\'гар.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9429,'Путешествие в Темнолесье','Слышал я, что у королевства Штормграда есть настоящая заноза в боку – Сумеречный лес. Местность эта наполнена страхом и зловонием нежити.$b$bПоскольку мы пытаемся помочь им по мере сил, я хотел бы, чтобы ты $Gотправился:отправилась; на юго-восток, в главное тамошнее поселение людей – городок под названием Темнолесье. Анахорет Делан будет ждать вас.','Поговорите с анахоретом Деланом в городе Темнолесье в Сумеречном лесу.','Приветствую вас, $C. Хотелось бы верить, что путешествие ваше обошлось без неожиданностей?$B$BЭти несчастные со всех сторон окружены исчадиями ночи. Мы хотим, чтобы вы оказали им посильную помощь и разогнали тьму.$B$BПобродите по городу, познакомьтесь с его жителями. Пожалуйста, $n, помогите им, чем сможете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие в Темнолесье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слышал я, что у королевства Штормграда есть настоящая заноза в боку – Сумеречный лес. Местность эта наполнена страхом и зловонием нежити.$b$bПоскольку мы пытаемся помочь им по мере сил, я хотел бы, чтобы ты $Gотправился:отправилась; на юго-восток, в главное тамошнее поселение людей – городок под названием Темнолесье. Анахорет Делан будет ждать вас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с анахоретом Деланом в городе Темнолесье в Сумеречном лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую вас, $C. Хотелось бы верить, что путешествие ваше обошлось без неожиданностей?$B$BЭти несчастные со всех сторон окружены исчадиями ночи. Мы хотим, чтобы вы оказали им посильную помощь и разогнали тьму.$B$BПобродите по городу, познакомьтесь с его жителями. Пожалуйста, $n, помогите им, чем сможете.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9430,'Реликвии Ша\'наара','Чтобы видеть недоступное всем остальным, мне не нужны глаза. Я не стану осуждать тебя за то, что ты $gвыполнил:выполнила; просьбу Макуру. Я хочу, чтобы ты $gнаучился:научилась; не просто смотреть, но видеть.$B$BСтупай к юго-западу, к Руинам Ша\'наара и собери все реликвии, которые там найдешь. Если судьба будет благосклонна, нам попадется то, что нужно.$B$BВозможно, тебе покажется неясным смысл моей просьбы, $n, но отбрось всякие сомнения. Чтобы понять, нужно иметь терпение.','Тебе сопутствовала удача. Как я и надеялся, мы нашли то, что искали.','Вернитесь к Амаану Мудрейшему в Храм Телхамата на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвии Ша\'наара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы видеть недоступное всем остальным, мне не нужны глаза. Я не стану осуждать тебя за то, что ты $gвыполнил:выполнила; просьбу Макуру. Я хочу, чтобы ты $gнаучился:научилась; не просто смотреть, но видеть.$B$BСтупай к юго-западу, к Руинам Ша\'наара и собери все реликвии, которые там найдешь. Если судьба будет благосклонна, нам попадется то, что нужно.$B$BВозможно, тебе покажется неясным смысл моей просьбы, $n, но отбрось всякие сомнения. Чтобы понять, нужно иметь терпение.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе сопутствовала удача. Как я и надеялся, мы нашли то, что искали.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амаану Мудрейшему в Храм Телхамата на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9431,'Другой подход','Что син\'дорай делает здесь, на этой выветренной вершине в Тысяче Игл, так далеко от роскошных дворцов Луносвета?$B$BВсе очень просто. Мои собратья изгнали меня и сожгли все мои записи о натуральных лекарствах от магической зависимости.$B$BЗдесь я могу продолжать исследования, вот только реагентов у меня нет. Поэтому я буду бесконечно признательна, если ты соберешь немного очищающей земли с грохочущих булыжней, а потом отнесешь ее моему помощнику на заставу Белого Плеса. Булыжни обитают у западных игл.','Соберите 2 горсти очищающей земли с грохочущих булыжней и отнесите Визло Фингалету на заставу Белого Плеса.','Что? Она не сказала про лунный колодец? Так ведь у нее именно это и было на уме. Признаться, все это выглядит немного странно, но не буду же я в здравом уме лишаться клиента! Тем более – единственного.\n\nКонечно, я бы не сказал, что это очень благоразумно – лезть в поселок ночных эльфов и воровать воду из их колодца, но раз она за это платит, то стоит попробовать.','Письмо магистра Элозай немного запутанно, но я, кажется, понял, что она хочет от меня. Если у вас есть земля, про которую она упоминала, то я могу положить ее в сосуд для воды из лунного колодца.','Вернитесь к Визло Фингалету на Заставу Белого Плеса, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Другой подход',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что син\'дорай делает здесь, на этой выветренной вершине в Тысяче Игл, так далеко от роскошных дворцов Луносвета?$B$BВсе очень просто. Мои собратья изгнали меня и сожгли все мои записи о натуральных лекарствах от магической зависимости.$B$BЗдесь я могу продолжать исследования, вот только реагентов у меня нет. Поэтому я буду бесконечно признательна, если ты соберешь немного очищающей земли с грохочущих булыжней, а потом отнесешь ее моему помощнику на заставу Белого Плеса. Булыжни обитают у западных игл.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 2 горсти очищающей земли с грохочущих булыжней и отнесите Визло Фингалету на заставу Белого Плеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Она не сказала про лунный колодец? Так ведь у нее именно это и было на уме. Признаться, все это выглядит немного странно, но не буду же я в здравом уме лишаться клиента! Тем более – единственного.\n\nКонечно, я бы не сказал, что это очень благоразумно – лезть в поселок ночных эльфов и воровать воду из их колодца, но раз она за это платит, то стоит попробовать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Письмо магистра Элозай немного запутанно, но я, кажется, понял, что она хочет от меня. Если у вас есть земля, про которую она упоминала, то я могу положить ее в сосуд для воды из лунного колодца.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Визло Фингалету на Заставу Белого Плеса, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9432,'Дорога в Астранаар','Я рад, что ты $gпришел:пришла; на помощь. Тут тебе и правда найдется дело.$B$BМне хотелось бы, чтобы ты $gотправился:отправилась; в городок ночных эльфов Астранаар. Он расположен в Ясеневом лесу, огромном лесу к югу от Темных берегов в Калимдоре.$B$BПожалуйста, поговори с воздаятельницей Паланаарой, когда прибудешь туда, и посмотри, чем сможешь помочь местным жителям.','Отправляйтесь в Астранаар в Ясеневом лесу и поговорите с воздаятельницей Паланаарой.','Всегда приятно увидеть почти знакомое лицо. Наверное, ты $n. Эмиссар Валастраа сообщила мне, что ты скоро будешь.$B$BНароду Ясеневого леса нужна наша поддержка, $C. Поговори с жителями Астранаара и узнай, какая помощь им нужна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога в Астранаар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рад, что ты $gпришел:пришла; на помощь. Тут тебе и правда найдется дело.$B$BМне хотелось бы, чтобы ты $gотправился:отправилась; в городок ночных эльфов Астранаар. Он расположен в Ясеневом лесу, огромном лесу к югу от Темных берегов в Калимдоре.$B$BПожалуйста, поговори с воздаятельницей Паланаарой, когда прибудешь туда, и посмотри, чем сможешь помочь местным жителям.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Астранаар в Ясеневом лесу и поговорите с воздаятельницей Паланаарой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Всегда приятно увидеть почти знакомое лицо. Наверное, ты $n. Эмиссар Валастраа сообщила мне, что ты скоро будешь.$B$BНароду Ясеневого леса нужна наша поддержка, $C. Поговори с жителями Астранаара и узнай, какая помощь им нужна.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9433,'Проба из Лунного колодца','Да не смотри ты на меня так! Я ж не говорил, что пошлю тебя черпать воду из колодца фляжкой!$B$BЯ вот тут как раз... гм... настраивал одно изобретение для моего клиента. Эта штука, Роботрон, двигается с помощью портативной панели управления, которую я запрятал в кустах на границе с Таланааром. Вот, возьми это устройство, найди ту панель и включи робота – а он сам наберет воды.$B$BЕсли бы мой клиент прознал, что мы тут вытворяем с его заказом, он бы меня за уши подвесил!','На каменной игле, ближайшей к границе с Таланааром, в кустах спрятано устройство управления Роботроном 3000. Найдите ее и включите робота при помощи устройства, которое вам дал Визло. Подведите робота к западному краю Тысячи Игл, где находится застава Альянса под названием Таланаар, и прикажите ему набрать немного воды из Лунного колодца, после чего вернитесь к Визло Фингалету на заставу Белого Плеса.','Все вышло даже лучше, чем я хотел! Запиши за гоблинами еще одно гениальное изобретение!\n\nЕдинственная проблема в том, что оно безнадежно покрыто пылью. У меня вся жизнь уйдет на то, чтобы его отчистить и вернуть на место.\n\nХотя чего-чего, а времени у меня хватает.','Ну и как, сработало?','Вернитесь к Визло Фингалету на Заставу Белого Плеса, что в Тысяче Игл.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проба из Лунного колодца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да не смотри ты на меня так! Я ж не говорил, что пошлю тебя черпать воду из колодца фляжкой!$B$BЯ вот тут как раз... гм... настраивал одно изобретение для моего клиента. Эта штука, Роботрон, двигается с помощью портативной панели управления, которую я запрятал в кустах на границе с Таланааром. Вот, возьми это устройство, найди ту панель и включи робота – а он сам наберет воды.$B$BЕсли бы мой клиент прознал, что мы тут вытворяем с его заказом, он бы меня за уши подвесил!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','На каменной игле, ближайшей к границе с Таланааром, в кустах спрятано устройство управления Роботроном 3000. Найдите ее и включите робота при помощи устройства, которое вам дал Визло. Подведите робота к западному краю Тысячи Игл, где находится застава Альянса под названием Таланаар, и прикажите ему набрать немного воды из Лунного колодца, после чего вернитесь к Визло Фингалету на заставу Белого Плеса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все вышло даже лучше, чем я хотел! Запиши за гоблинами еще одно гениальное изобретение!\n\nЕдинственная проблема в том, что оно безнадежно покрыто пылью. У меня вся жизнь уйдет на то, чтобы его отчистить и вернуть на место.\n\nХотя чего-чего, а времени у меня хватает.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну и как, сработало?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Визло Фингалету на Заставу Белого Плеса, что в Тысяче Игл.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9434,'Испытание тоника','*Визло берет пробу воды из робота и кладет ее в ящик, где уже лежит земля, добытая с булыжней, и несколько других вещей*$B$BНу вот, заказ магистра Элозай готов. Передай ей, что мне очень понравилось с ней работать и что я желаю ей всяческих успехов в ее исследованиях.','Доставьте ящик с реагентами магистра Элозай на Заставу Вольного Ветра.','Вам с Визло удалось собрать реагенты?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание тоника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Визло берет пробу воды из робота и кладет ее в ящик, где уже лежит земля, добытая с булыжней, и несколько других вещей*$B$BНу вот, заказ магистра Элозай готов. Передай ей, что мне очень понравилось с ней работать и что я желаю ей всяческих успехов в ее исследованиях.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте ящик с реагентами магистра Элозай на Заставу Вольного Ветра.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вам с Визло удалось собрать реагенты?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9435,'Пропавшие кристаллы','Если что и можно с уверенностью сказать про Хилсбрад, так это то, что эти края обречены вечно жить в тени войны. Нападают даже на обозы с камнем.$b$bВ обычной ситуации нас не очень расстраивает утрата строительных материалов, но в последней поставке из Лазуритового рудника был ящик с редкими кристаллами, которые мне не терпится изучить. Отрекшиеся-налетчики перехватили обоз и угнали его на северо-восток, к разрушенной башне. Нам непременно нужны эти кристаллы, |3-6($c)!','Отберите у нежити посылку с редкими кристаллами и верните ее Ураану из Южнобережья.','Слава Свету! Судя по тону писем бригадира, казалось, что этот ящик с кристаллами содержал единственные известные образцы из шахты. Если бы мы потеряли их, $N, возможно, мы никогда не увидели бы больше таких. $B$BЯ не могу не отблагодарить вас за вашу помощь.','Удалось ли вам забрать кристаллы у Отрекшихся?','Вернитесь к Ураану в Южнобережье, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие кристаллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если что и можно с уверенностью сказать про Хилсбрад, так это то, что эти края обречены вечно жить в тени войны. Нападают даже на обозы с камнем.$b$bВ обычной ситуации нас не очень расстраивает утрата строительных материалов, но в последней поставке из Лазуритового рудника был ящик с редкими кристаллами, которые мне не терпится изучить. Отрекшиеся-налетчики перехватили обоз и угнали его на северо-восток, к разрушенной башне. Нам непременно нужны эти кристаллы, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отберите у нежити посылку с редкими кристаллами и верните ее Ураану из Южнобережья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава Свету! Судя по тону писем бригадира, казалось, что этот ящик с кристаллами содержал единственные известные образцы из шахты. Если бы мы потеряли их, $N, возможно, мы никогда не увидели бы больше таких. $B$BЯ не могу не отблагодарить вас за вашу помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли вам забрать кристаллы у Отрекшихся?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ураану в Южнобережье, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9436,'Изучение Кровавого Скальпа','Рад знакомству, |3-6($c). В последнее время я стал изучать боевые приемы различных племен троллей, и заметил одну особенность. Тролли племени Кровавого Скальпа, живущие в руинах Ткаши и Бал\'лал, пользуются той же тактикой, что и Амани северных лесов.$B$BУ них очень необычная магия, и благодаря ей они стали самым могучим племенем в здешних краях. Благодаря этому можно создать сильное оружие против Амани, но нужно докопаться до сути.','Немет Остроглаз из лагеря Гром\'гол попросил вас принести ему тотем Кровавого Скальпа, добыв его у шамана из племени Кровавого Скальпа.','Вернитесь к Немету Остроглазу в лагерь Гром\'гол, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение Кровавого Скальпа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рад знакомству, |3-6($c). В последнее время я стал изучать боевые приемы различных племен троллей, и заметил одну особенность. Тролли племени Кровавого Скальпа, живущие в руинах Ткаши и Бал\'лал, пользуются той же тактикой, что и Амани северных лесов.$B$BУ них очень необычная магия, и благодаря ей они стали самым могучим племенем в здешних краях. Благодаря этому можно создать сильное оружие против Амани, но нужно докопаться до сути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Немет Остроглаз из лагеря Гром\'гол попросил вас принести ему тотем Кровавого Скальпа, добыв его у шамана из племени Кровавого Скальпа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Немету Остроглазу в лагерь Гром\'гол, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9437,'Сумерки "Гонца Рассвета"','От тутошних огров не жди ничего, кроме тупых шуток, дурного эля да мигрени.$b$bКогда мой корабль "Гонец Рассвета" пристал к здешним берегам, эти негодяи из Терамора смылись с моим грузом и последним членом экипажа. Я добрался сюда в поисках помощи, но эти самые ни на что не годные огры просто тупо смотрели на меня, пока я рассказывал им свою историю. $B$BМогу ли я надеяться на помощь $gотзывчивого:отзывчивой:r; |3-1($r), в выяснении того, что случилось с моим грузом и в освобождении Итании из северной башни, к северо-востоку отсюда, куда они ее посадили?','Вернитесь к Балиндару Ясной Звезде в деревню Гиблотопь, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сумерки "Гонца Рассвета"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От тутошних огров не жди ничего, кроме тупых шуток, дурного эля да мигрени.$b$bКогда мой корабль "Гонец Рассвета" пристал к здешним берегам, эти негодяи из Терамора смылись с моим грузом и последним членом экипажа. Я добрался сюда в поисках помощи, но эти самые ни на что не годные огры просто тупо смотрели на меня, пока я рассказывал им свою историю. $B$BМогу ли я надеяться на помощь $gотзывчивого:отзывчивой:r; |3-1($r), в выяснении того, что случилось с моим грузом и в освобождении Итании из северной башни, к северо-востоку отсюда, куда они ее посадили?',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Балиндару Ясной Звезде в деревню Гиблотопь, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9438,'Вы видите, что напряжение уходит с лица Тралла по мере того, как он читает донесение Назгрела  \n\nМой народ... Мы должны отправиться к ним. Мы должны отпавиться в Награнд как можно скорее!','Ты принесла вести из Запределья? Докладывай немедленно!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы видите, что напряжение уходит с лица Тралла по мере того, как он читает донесение Назгрела  \n\nМой народ... Мы должны отправиться к ним. Мы должны отпавиться в Награнд как можно скорее!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принесла вести из Запределья? Докладывай немедленно!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9439,'Потерянный багаж','Это что же, Каргат? Матушки... Я ожидал что это какое-то поселение, оазис цивилизации в пустыне... $B$BДолжно быть, тут какая-то ошибка. Не может же быть эта клоака, кишащая немытыми, неотесанными дикарями, штаб-квартирой экспедиционных войск! Эти грубые варвары начали ржать во всю глотку, когда я сообщил, что меня ограбили дворфы Черного Железа и скрылись в направлении крепости Ангор. Могу ли я рассчитывать, что ты поможешь мне вернуть мое имущество?','Верните советнику Сарофасу в Каргат вещи советника и рапиру советника из крепости Ангор.','Ты чудотворец, $N! Говорю тебе, я никогда в жизни так не ждал смены одежды. $B$BИ моя рапира! Я чувствовал себя беззащитным без моего клинка. $B$BТы $Gдолжен:должна; быть $Gвознаграждён:вознаграждена; за свои усилия. Никогда не говори, что Сарофас не признаёт маленьких людей, которые помогли ему на длинном пути!','Ради Солнца, не смотри на меня! Это ужасно, что я вынужден торчать здесь, в грязной одежде! Тебе удалось достать мои вещи из той дыры в земле, которую дворфы Чёрного Железа называют крепостью?','Вернитесь к советнику Сарофасу в Каргат, что в Бесплодных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянный багаж',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это что же, Каргат? Матушки... Я ожидал что это какое-то поселение, оазис цивилизации в пустыне... $B$BДолжно быть, тут какая-то ошибка. Не может же быть эта клоака, кишащая немытыми, неотесанными дикарями, штаб-квартирой экспедиционных войск! Эти грубые варвары начали ржать во всю глотку, когда я сообщил, что меня ограбили дворфы Черного Железа и скрылись в направлении крепости Ангор. Могу ли я рассчитывать, что ты поможешь мне вернуть мое имущество?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните советнику Сарофасу в Каргат вещи советника и рапиру советника из крепости Ангор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты чудотворец, $N! Говорю тебе, я никогда в жизни так не ждал смены одежды. $B$BИ моя рапира! Я чувствовал себя беззащитным без моего клинка. $B$BТы $Gдолжен:должна; быть $Gвознаграждён:вознаграждена; за свои усилия. Никогда не говори, что Сарофас не признаёт маленьких людей, которые помогли ему на длинном пути!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ради Солнца, не смотри на меня! Это ужасно, что я вынужден торчать здесь, в грязной одежде! Тебе удалось достать мои вещи из той дыры в земле, которую дворфы Чёрного Железа называют крепостью?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к советнику Сарофасу в Каргат, что в Бесплодных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9440,'Маленькие кусочки','Я совершенствую антидренейское оружие, и ты мне в этом поможешь.$B$BЗаблудшие – родня дренеям, хотя и отстают в своем развитии, поэтому экспериментирую я на них. От тебя требуется скормить несколько зараженных Скверной кусочков еды их домашнему скоту. Они в свою очередь убьют и съедят эту скотину и попадут под власть проклятия. Я покажу этому анахорету Авууну из Убежища!$B$BСтупай и поторопись! Ты найдешь Заблудших и их загоны для скота к северо-востоку от Болотного пристанища.','Накормите испорченными кусочками мяса домашний скот Заблудших. Потом верните остатки Серсее Певице Заката в Каменор на Болото Печали.','Прекрасно! Жду не дождусь, когда смогу оценить эффект от последней партии!\n\nТы все сделал замечательно, прелесть моя. Я бы дала тебе и больше за то развлечение, которое ты мне устроил, но ты же знаешь, здесь на болотах денег днем с огнем не найти.\n\nНо я уверена, что забава того стоит!','Ты скормил скоту все оскверненные кусочки? Погоди! А тому глупому человечишке, что сидит у них в клетке? Ему – нет, я надеюсь?\n\nУф! Было бы очень жаль!','Вернитесь к Серсее Певице Заката на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маленькие кусочки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я совершенствую антидренейское оружие, и ты мне в этом поможешь.$B$BЗаблудшие – родня дренеям, хотя и отстают в своем развитии, поэтому экспериментирую я на них. От тебя требуется скормить несколько зараженных Скверной кусочков еды их домашнему скоту. Они в свою очередь убьют и съедят эту скотину и попадут под власть проклятия. Я покажу этому анахорету Авууну из Убежища!$B$BСтупай и поторопись! Ты найдешь Заблудших и их загоны для скота к северо-востоку от Болотного пристанища.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Накормите испорченными кусочками мяса домашний скот Заблудших. Потом верните остатки Серсее Певице Заката в Каменор на Болото Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Жду не дождусь, когда смогу оценить эффект от последней партии!\n\nТы все сделал замечательно, прелесть моя. Я бы дала тебе и больше за то развлечение, которое ты мне устроил, но ты же знаешь, здесь на болотах денег днем с огнем не найти.\n\nНо я уверена, что забава того стоит!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты скормил скоту все оскверненные кусочки? Погоди! А тому глупому человечишке, что сидит у них в клетке? Ему – нет, я надеюсь?\n\nУф! Было бы очень жаль!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Серсее Певице Заката на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (9441,'Это очень важно, что вы помогли в нужное время. Нам нелегко будет забыть вас и того, кто послал вас сюда. $B$BМы благодарим вас.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это очень важно, что вы помогли в нужное время. Нам нелегко будет забыть вас и того, кто послал вас сюда. $B$BМы благодарим вас.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9442,'Изнуряющая слабость','Горкан говорил хорошие вещи о тебе. Они оказались верны. $B$BСпасибо за помощь.','Ты $Gдобыл:добыла; гриб, который мне нужен, $N?','Вернитесь к заклинательнице земли Риге на Заставу маг\'харов, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изнуряющая слабость',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Горкан говорил хорошие вещи о тебе. Они оказались верны. $B$BСпасибо за помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдобыл:добыла; гриб, который мне нужен, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинательнице земли Риге на Заставу маг\'харов, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9443,'Так называемый знак Светоносного','Некогда я был учеником Утера Светоносного, основателя ордена рыцарей Серебряной Длани. Я сам видел, как неправильно он воспитал принца Артаса. Это привело к гибели моей родины, Кель\'Таласа, и я виню Утера в трагедии моего народа! А теперь он покоится в величественной гробнице – скажите, как мило.$b$bМои шпионы доносят, что эти алые идиоты держат на одной из сторожевых башен рядом с воротами Дольного Очага "святую" реликвию, связанную с Утером.$b$bОтправляйся в Западные Чумные земли и принеси ее.','Добудьте знак Светоносного и принесите его Мелару Клинку Рассвета в Бастион, что в Западных Чумных землях.','Первый шаг завершен. Передай мне реликвию Утер Светоносного, и я превращу её во что-нибудь более подходящее. $B$BТеперь моя месть начнется всерьез, $C!','Когда вам удастся получить его "метку", мы немного ее изменим, сделав его лучше.','Вернитесь к Мелару Клинку Рассвета в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Так называемый знак Светоносного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некогда я был учеником Утера Светоносного, основателя ордена рыцарей Серебряной Длани. Я сам видел, как неправильно он воспитал принца Артаса. Это привело к гибели моей родины, Кель\'Таласа, и я виню Утера в трагедии моего народа! А теперь он покоится в величественной гробнице – скажите, как мило.$b$bМои шпионы доносят, что эти алые идиоты держат на одной из сторожевых башен рядом с воротами Дольного Очага "святую" реликвию, связанную с Утером.$b$bОтправляйся в Западные Чумные земли и принеси ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте знак Светоносного и принесите его Мелару Клинку Рассвета в Бастион, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Первый шаг завершен. Передай мне реликвию Утер Светоносного, и я превращу её во что-нибудь более подходящее. $B$BТеперь моя месть начнется всерьез, $C!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда вам удастся получить его "метку", мы немного ее изменим, сделав его лучше.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелару Клинку Рассвета в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9444,'Осквернение гробницы Утера','Вот так-то лучше. Я наложил на этот знак магию скверны.$b$bА теперь отнеси его в место его упокоения в Западные Чумные земли. Воспользуйся оскверненным священным символом перед статуей Утера и оскверни тем самым его гробницу! Для этого придется подобраться поближе.$b$bГробница находится на юго-востоке от руин Андорала. Как выполнишь мое поручение, возвращайся ко мне.$b$bИ поторапливайся, |3-6($c)!','Оскверните гробницу Утера и возвращайтесь к Мелару Клинку Рассвета в Бастион, что в Западных Чумных землях.','Прощает меня? ОН ПРОЩАЕТ МЕНЯ?!!!$B$BМне все равно, что сказал этот старый призрак - это была его вина! Все, что случилось в КельТаласе - это результат его некомпетентности!$B$BПонятно, что осквернение не сработало. Уходи, исчезни с моих глаз! Я должен все обдумать.','Значит, сделано? Могила Утера осквернена?','Вернитесь к Мелару Клинку Рассвета в Бастион, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернение гробницы Утера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот так-то лучше. Я наложил на этот знак магию скверны.$b$bА теперь отнеси его в место его упокоения в Западные Чумные земли. Воспользуйся оскверненным священным символом перед статуей Утера и оскверни тем самым его гробницу! Для этого придется подобраться поближе.$b$bГробница находится на юго-востоке от руин Андорала. Как выполнишь мое поручение, возвращайся ко мне.$b$bИ поторапливайся, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оскверните гробницу Утера и возвращайтесь к Мелару Клинку Рассвета в Бастион, что в Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прощает меня? ОН ПРОЩАЕТ МЕНЯ?!!!$B$BМне все равно, что сказал этот старый призрак - это была его вина! Все, что случилось в КельТаласе - это результат его некомпетентности!$B$BПонятно, что осквернение не сработало. Уходи, исчезни с моих глаз! Я должен все обдумать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Значит, сделано? Могила Утера осквернена?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мелару Клинку Рассвета в Бастион, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9445,'<NYI><TXT>Placeholder: A Worthy Offering','Получите благословение Утера с вершины сторожевой башни у входа в Дольный Очаг и отнесите его <NPC> на Берег Промозглого Ветра.','Вернитесь к ...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI><TXT>Placeholder: A Worthy Offering',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите благословение Утера с вершины сторожевой башни у входа в Дольный Очаг и отнесите его <NPC> на Берег Промозглого Ветра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ...',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`,`questgivertextwindow_loc8`) VALUES (9446,'Гробница Светоносного','Тебе удалось добыть знак Светоносного, остается отнести его к гробнице Утера.$b$bСходишь со мной? Это недалеко, а я буду рад твоему обществу. Потом можешь вернуться и рассказать о нашем путешествии верховной жрице Макдонелл.$b$bЧто скажешь, $n?','Проводите анахорета Трууна к гробнице Утера в Западные Чумные земли. После поговорите с верховной жрицей Макдонелл из Лагеря Промозглого Ветра.','Тебе явился Светоносный? Поразительно! Это результат твоей самоотверженной помощи анахорету.$B$BДаже если половина историй про Утера – правда, он был великим человеком. А ты, как и он, настоящий герой для всех существ доброй воли на Азероте!','Разве ты не должен идти к гробнице Утера с анахоретом Трууэном?','Проводить анахорета Трууна к гробнице Утера','Вернитесь к верховной жрице Макдонелл в Лагерь Промозглого Ветра, что в Западных Чумных землях.','Проводить анахорета Трууна к гробнице Утера') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гробница Светоносного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось добыть знак Светоносного, остается отнести его к гробнице Утера.$b$bСходишь со мной? Это недалеко, а я буду рад твоему обществу. Потом можешь вернуться и рассказать о нашем путешествии верховной жрице Макдонелл.$b$bЧто скажешь, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите анахорета Трууна к гробнице Утера в Западные Чумные земли. После поговорите с верховной жрицей Макдонелл из Лагеря Промозглого Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе явился Светоносный? Поразительно! Это результат твоей самоотверженной помощи анахорету.$B$BДаже если половина историй про Утера – правда, он был великим человеком. А ты, как и он, настоящий герой для всех существ доброй воли на Азероте!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Разве ты не должен идти к гробнице Утера с анахоретом Трууэном?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводить анахорета Трууна к гробнице Утера',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховной жрице Макдонелл в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`), `questgivertextwindow_loc8`=IF(`questgivertextwindow_loc8` IS NULL OR `questgivertextwindow_loc8`='','Проводить анахорета Трууна к гробнице Утера',`questgivertextwindow_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9447,'Применение целебной мази','Из того, что ты мне $gпринес:принесла;, я приготовила мазь, которая восстановит силу наших рубак. Вот, возьми. Нанеси ее на всех изнуренных рубак, которых увидишь, и возвращайся ко мне.','Нанесите целебную мазь на 10 изнуренных маг\'харских рубак рядом с Заставой маг\'харов на Полуострове Адского Пламени по просьбе заклинательницы земли Риги.','Духи благословят тебя, $N. Маг\'хары перед тобой в долгу.','Твоя задача выполнена?','Вернитесь к заклинательнице земли Риге на Заставу маг\'харов, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Применение целебной мази',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из того, что ты мне $gпринес:принесла;, я приготовила мазь, которая восстановит силу наших рубак. Вот, возьми. Нанеси ее на всех изнуренных рубак, которых увидишь, и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нанесите целебную мазь на 10 изнуренных маг\'харских рубак рядом с Заставой маг\'харов на Полуострове Адского Пламени по просьбе заклинательницы земли Риги.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Духи благословят тебя, $N. Маг\'хары перед тобой в долгу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твоя задача выполнена?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к заклинательнице земли Риге на Заставу маг\'харов, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9448,'Милость к проклятым','Эта ведьма из эльфов крови – Серсея Певица Заката – заражает порчей Заблудших, я знаю это, и все тут! Я не знаю, зачем и как она это делает, но результаты ужасают. Некоторые из Заблудших еще сильнее подпали под влияние порчи, под воздействие еще более мощных энергий Скверны!$B$B$C, не проникаешься ли ты жалостью к этим несчастным существам? Они не должны прожить остаток дней своих под действием проклятья.$B$BТы найдешь бедняг в Болотном пристанище, к востоку отсюда.','Убейте 3 проклятых из племени Заблудших, потом вернитесь к анахорету Авууну в Убежище на Болото Печали.','Значит, дело сделано. Благодарю вас за проявленное сострадание. После того, как они были заражены Серсеей, уже ничего нельзя было сделать. $B$BТеперь они в лучшем мире, и я надеюсь, что мои исследования принесут плоды, чтобы они могли быть реабилитированы.','Ты поступаешь правильно, $C. Заблудшие уже так сильно пострадали. Они не должны страдать от этого унижения.','Вернитесь к анахорету Авууну на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Милость к проклятым',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта ведьма из эльфов крови – Серсея Певица Заката – заражает порчей Заблудших, я знаю это, и все тут! Я не знаю, зачем и как она это делает, но результаты ужасают. Некоторые из Заблудших еще сильнее подпали под влияние порчи, под воздействие еще более мощных энергий Скверны!$B$B$C, не проникаешься ли ты жалостью к этим несчастным существам? Они не должны прожить остаток дней своих под действием проклятья.$B$BТы найдешь бедняг в Болотном пристанище, к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 3 проклятых из племени Заблудших, потом вернитесь к анахорету Авууну в Убежище на Болото Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, дело сделано. Благодарю вас за проявленное сострадание. После того, как они были заражены Серсеей, уже ничего нельзя было сделать. $B$BТеперь они в лучшем мире, и я надеюсь, что мои исследования принесут плоды, чтобы они могли быть реабилитированы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты поступаешь правильно, $C. Заблудшие уже так сильно пострадали. Они не должны страдать от этого унижения.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Авууну на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9449,'Зов Земли','Выслушай меня, $n. Пришло время тебе поговорить с духами стихий напрямую.$b$bВпрочем, соблюдай осторожность. Мы оказались в этом мире случайно и невольно принесли ему зло, разъярили духов земли и нарушили природное равновесие.$b$bЕсли ты хочешь создать тотем Земли, поговори прежде с духом долины. Он находится в Священной роще, в холмах на северо-западе отсюда.','Поговорите с духом долины в Священной роще долины Аммен.','Ты $Gпосмел:посмела; искать моей мудрости после того, что твой народ сделал с этими островами, $Gнезнакомец:незнакомка;! Тем не менее, есть что сказать о вашей храбрости, так что я поделюсь с вами некоторыми знаниями. $B$BЗемля под вашими ногами составляет основу всего. Небо, вода, даже великий огонь - все покоится на его плечах. В то время как другие часто образуют хаотические бури, земля остается. Он придает силу и стойкость сердцевине вашего существа. $B$BСейчас ты проявишь себя, $C') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Выслушай меня, $n. Пришло время тебе поговорить с духами стихий напрямую.$b$bВпрочем, соблюдай осторожность. Мы оказались в этом мире случайно и невольно принесли ему зло, разъярили духов земли и нарушили природное равновесие.$b$bЕсли ты хочешь создать тотем Земли, поговори прежде с духом долины. Он находится в Священной роще, в холмах на северо-западе отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с духом долины в Священной роще долины Аммен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпосмел:посмела; искать моей мудрости после того, что твой народ сделал с этими островами, $Gнезнакомец:незнакомка;! Тем не менее, есть что сказать о вашей храбрости, так что я поделюсь с вами некоторыми знаниями. $B$BЗемля под вашими ногами составляет основу всего. Небо, вода, даже великий огонь - все покоится на его плечах. В то время как другие часто образуют хаотические бури, земля остается. Он придает силу и стойкость сердцевине вашего существа. $B$BСейчас ты проявишь себя, $C',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9450,'Зов Земли','Крушение корабля дренеев привело к нарушению природного равновесия в этой долине. Духи Земли в ярости обратились против других стихий, пытающихся утихомирить их. Вскоре ты поймешь, как важна гармония стихий для их познания.$b$bИтак, я поручаю тебе восстановить исконное равновесие. За моей спиной располагается роща, в которой духи Земли воюют с тремя другими стихиями. Наведи там порядок.','Убейте 4 неупокоенных духов земли и возвращайтесь к духу долины в Священную рощу долины Аммен.','Неплохо $Gсправился:справилась;. Уничтожив неупокоенных духов, ты $Gпомог:помогла; вылечить дисбаланс между стихиями, который непреднамеренно вызвал наш народ. $B$BНа протяжении всего твоего путешествия в качестве $C ты $Gдолжен:должна; помнить об этом, обращаясь к нашей силе. Баланс должен быть сохранен.','Стихии так и не пришли в равновесие, $N.','Вернитесь к духу долины в Священную рощу, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крушение корабля дренеев привело к нарушению природного равновесия в этой долине. Духи Земли в ярости обратились против других стихий, пытающихся утихомирить их. Вскоре ты поймешь, как важна гармония стихий для их познания.$b$bИтак, я поручаю тебе восстановить исконное равновесие. За моей спиной располагается роща, в которой духи Земли воюют с тремя другими стихиями. Наведи там порядок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 неупокоенных духов земли и возвращайтесь к духу долины в Священную рощу долины Аммен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо $Gсправился:справилась;. Уничтожив неупокоенных духов, ты $Gпомог:помогла; вылечить дисбаланс между стихиями, который непреднамеренно вызвал наш народ. $B$BНа протяжении всего твоего путешествия в качестве $C ты $Gдолжен:должна; помнить об этом, обращаясь к нашей силе. Баланс должен быть сохранен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Стихии так и не пришли в равновесие, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к духу долины в Священную рощу, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9451,'Зов Земли','Я передам тебе частицу моего физического облика, и ты положишь ее в основу своего тотема Земли. Отнеси эту частицу тому, кто послал тебя сюда.$b$bМы с тобой будем связаны навеки. До самой смерти силы Земли будут верно служить тебе, а отплатишь ты нам в тот миг, когда самая плоть твоя станет землей.$b$bПостарайся распорядиться своей силой мудро.','Отнесите кристалл Земли Фирманваару на место крушения в долине Аммен.','Ты молодец, $N. Помогая восстановить баланс стихий в роще, ты также восстанавливаешь баланс между земными элементами этого мира, $R. Может быть это даст понимание, тем кто не одобряет наш путь. $B$BЯ создам для тебя тотем, с помощью которого ты сможешь призывать силу земли на служение тебе. И со временем тебе будет раскрываться все больше загадок этой стихии. $B$BА теперь возьми свой тотем, $C.','Вместе Сломленные и дренеи обретут более глубокое понимание тайн, скрываемых стихиями.$B$BТы $Gвернулся:вернулась; с тем, что необходимо для создания твоего земного тотема?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я передам тебе частицу моего физического облика, и ты положишь ее в основу своего тотема Земли. Отнеси эту частицу тому, кто послал тебя сюда.$b$bМы с тобой будем связаны навеки. До самой смерти силы Земли будут верно служить тебе, а отплатишь ты нам в тот миг, когда самая плоть твоя станет землей.$b$bПостарайся распорядиться своей силой мудро.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите кристалл Земли Фирманваару на место крушения в долине Аммен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты молодец, $N. Помогая восстановить баланс стихий в роще, ты также восстанавливаешь баланс между земными элементами этого мира, $R. Может быть это даст понимание, тем кто не одобряет наш путь. $B$BЯ создам для тебя тотем, с помощью которого ты сможешь призывать силу земли на служение тебе. И со временем тебе будет раскрываться все больше загадок этой стихии. $B$BА теперь возьми свой тотем, $C.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вместе Сломленные и дренеи обретут более глубокое понимание тайн, скрываемых стихиями.$B$BТы $Gвернулся:вернулась; с тем, что необходимо для создания твоего земного тотема?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9452,'Деликатесный красный луциан','Я обнаружила, что в этих водах много красного луциана – а это очень вкусная рыба! Сетью я могла бы наловить столько, что хватило бы на дюжину дренеев! К сожалению, недавно во время рыбалки на меня напала тварь, которую называют мурлоком. Из-за ран я не могу ловить рыбу. Помоги мне!$B$BПоставь эту сеть в водах Хрустальной реки на востоке, и у тебя будет огромный улов.$B$BЧто скажешь? Не забудь потом вернуть сеть.','Поймайте 10 красных луцианов рыболовной сетью дренеев. Отдайте рыбу и сеть Диктинне на острове Лазурной Дымки.','Остерегайся мурлоков: это странные и крайне надоедливые существа.','Вернитесь к Диктинне на переправу Аммен, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деликатесный красный луциан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я обнаружила, что в этих водах много красного луциана – а это очень вкусная рыба! Сетью я могла бы наловить столько, что хватило бы на дюжину дренеев! К сожалению, недавно во время рыбалки на меня напала тварь, которую называют мурлоком. Из-за ран я не могу ловить рыбу. Помоги мне!$B$BПоставь эту сеть в водах Хрустальной реки на востоке, и у тебя будет огромный улов.$B$BЧто скажешь? Не забудь потом вернуть сеть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 10 красных луцианов рыболовной сетью дренеев. Отдайте рыбу и сеть Диктинне на острове Лазурной Дымки.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Остерегайся мурлоков: это странные и крайне надоедливые существа.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Диктинне на переправу Аммен, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9453,'Поиски Актеона','Прекрасно, $n! Наш народ будет признателен тебе за рыбу. Кстати, не отнесешь ли наловленного красного луциана Актеону на Лазурную заставу?$B$BЕго будет несложно отыскать – он ждет этот улов.','Отнести ящик красного луциана Актеону на Лазурную заставу.','Тебе нравятся мои доспехи? Я сделал их сам! Они отличаются от привычных нам, но зато очень удобные.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Актеона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прекрасно, $n! Наш народ будет признателен тебе за рыбу. Кстати, не отнесешь ли наловленного красного луциана Актеону на Лазурную заставу?$B$BЕго будет несложно отыскать – он ждет этот улов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнести ящик красного луциана Актеону на Лазурную заставу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе нравятся мои доспехи? Я сделал их сам! Они отличаются от привычных нам, но зато очень удобные.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9454,'Великая охота на лунных оленей','Принесите 6 кусков вырезки лунного оленя Актеону на Лазурную заставу.','Молодец, $n, молодец!$B$BПока ты $Gохотился:охотилась;, я приготовил тебе немного вырезки. Может, ты и от рецепта не откажешься?','Шкура у оленей тонкая, зато мясо нежное, сочное.','Вернитесь к Актеону на Лазурную заставу, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великая охота на лунных оленей',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 кусков вырезки лунного оленя Актеону на Лазурную заставу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $n, молодец!$B$BПока ты $Gохотился:охотилась;, я приготовил тебе немного вырезки. Может, ты и от рецепта не откажешься?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Шкура у оленей тонкая, зато мясо нежное, сочное.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Актеону на Лазурную заставу, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9455,'Странные находки','Похоже, найденный тобой в теле ночного ловца-недоростка кристалл – часть Экзодара. Это объясняет необычную внешность и поведение некоторых животных этих земель.$B$BОтнеси кристалл на Лазурную заставу. Экзарху следует узнать о твоей находке.','Отнесите слабо мерцающий кристалл экзарху Менелаусу на Лазурную заставу.','Как такая вещь могла оказаться в желудке ночного ловца? Не заражены ли и другие звери осколками от разбившегося корабля?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странные находки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, найденный тобой в теле ночного ловца-недоростка кристалл – часть Экзодара. Это объясняет необычную внешность и поведение некоторых животных этих земель.$B$BОтнеси кристалл на Лазурную заставу. Экзарху следует узнать о твоей находке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите слабо мерцающий кристалл экзарху Менелаусу на Лазурную заставу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как такая вещь могла оказаться в желудке ночного ловца? Не заражены ли и другие звери осколками от разбившегося корабля?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9456,'Истребление ночных ловцов, остров 2...','Не буду скрывать от тебя горестного значения твоей находки. Здесь, несомненно, наша вина. До нас доходили сообщения об осколках кристаллов в реке на востоке, но мы не обращали на них внимания. Теперь же остается либо сидеть и сокрушаться о случившейся трагедии, либо постараться ограничить распространение заразы.$B$BЕсли тебе такое дело по плечу, отправляйся в лес и постарайся уничтожить как можно больше зараженных ночных ловцов.','Уничтожьте 8 зараженных ночных ловцов-недоростков и вернитесь на Лазурную заставу.','Надеюсь, еще не поздно...','Необходимо остановить распространение инфекции. Судя по сведениям из Кровавой заставы, дело плохо. Мы должны немедленно принять меры!','Вернитесь к экзарху Менелаусу на Лазурную заставу, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истребление ночных ловцов, остров 2...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не буду скрывать от тебя горестного значения твоей находки. Здесь, несомненно, наша вина. До нас доходили сообщения об осколках кристаллов в реке на востоке, но мы не обращали на них внимания. Теперь же остается либо сидеть и сокрушаться о случившейся трагедии, либо постараться ограничить распространение заразы.$B$BЕсли тебе такое дело по плечу, отправляйся в лес и постарайся уничтожить как можно больше зараженных ночных ловцов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 зараженных ночных ловцов-недоростков и вернитесь на Лазурную заставу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, еще не поздно...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Необходимо остановить распространение инфекции. Судя по сведениям из Кровавой заставы, дело плохо. Мы должны немедленно принять меры!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к экзарху Менелаусу на Лазурную заставу, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9457,'Необычный посетитель','Так значит, за племенем Кровавого Скальпа и их необычной магией стоит Найас? Признаться, не думал, что расследование пойдет таким путем, но неважно, полученные сведения нам пригодятся.$B$BНедалеко от северо-западной части побережья находится остров, населенный младшими элементалями Воды. Там есть грубая каменная плита, которая, должно быть, служила троллям алтарем для поклонения. Отнеси найденный тобой тотем на этот алтарь. Посмотрим, не удастся ли выманить этого Найаса и перелить его силу в более подходящую форму.','Воспользуйтесь Даром Найаса неподалеку от алтаря Найаса и призовите этого элементаля воды. Одолейте его и принесите сердце Найаса Немету Остроглазу в лагерь Гром\'гол.','Какие вести о Найасе ты несешь?','Вернитесь к Немету Остроглазу в лагерь Гром\'гол, что в Северной Тернистой долине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычный посетитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так значит, за племенем Кровавого Скальпа и их необычной магией стоит Найас? Признаться, не думал, что расследование пойдет таким путем, но неважно, полученные сведения нам пригодятся.$B$BНедалеко от северо-западной части побережья находится остров, населенный младшими элементалями Воды. Там есть грубая каменная плита, которая, должно быть, служила троллям алтарем для поклонения. Отнеси найденный тобой тотем на этот алтарь. Посмотрим, не удастся ли выманить этого Найаса и перелить его силу в более подходящую форму.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь Даром Найаса неподалеку от алтаря Найаса и призовите этого элементаля воды. Одолейте его и принесите сердце Найаса Немету Остроглазу в лагерь Гром\'гол.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие вести о Найасе ты несешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Немету Остроглазу в лагерь Гром\'гол, что в Северной Тернистой долине.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9458,'<UNUSED>Зелье обострения чувств','Вернитесь к старшему снабженцу экспедиции Анклсу в Силитус.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>Зелье обострения чувств',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшему снабженцу экспедиции Анклсу в Силитус.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9459,'<UNUSED>Зелье защиты от критических попаданий','Вернитесь к эмиссару Гормоку в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>Зелье защиты от критических попаданий',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к эмиссару Гормоку в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9460,'Объединенными усилиями','Келтус Темный Лист для доклада явился!$b$bДа, а ты, собственно, кто $gтакой:такая;? Если хочешь получить мои донесения, сначала помоги мне.$b$bЯ тут собираюсь напасть на часовых-шпионов, но сначала хочу выслать вперед мою верную Шептунью. Однако ей нужен запах, чтобы знать, на кого нападать.$b$bУж конечно, тебе не составит труда подкрасться и стянуть какую-нибудь вещицу у их предводительницы?','Украдите у предводительницы часовых кружевной носовой платок и принесите его Келтусу Темному Листу.','Превосходно! Такой личный предмет несет в себе сильный запах злоумышленника - достаточно, чтобы направить Шептунью в их ряды...','Ты что-то $Gпонял:поняла;?','Вернитесь к Келтусу Темному Листу в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Объединенными усилиями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Келтус Темный Лист для доклада явился!$b$bДа, а ты, собственно, кто $gтакой:такая;? Если хочешь получить мои донесения, сначала помоги мне.$b$bЯ тут собираюсь напасть на часовых-шпионов, но сначала хочу выслать вперед мою верную Шептунью. Однако ей нужен запах, чтобы знать, на кого нападать.$b$bУж конечно, тебе не составит труда подкрасться и стянуть какую-нибудь вещицу у их предводительницы?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите у предводительницы часовых кружевной носовой платок и принесите его Келтусу Темному Листу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Такой личный предмет несет в себе сильный запах злоумышленника - достаточно, чтобы направить Шептунью в их ряды...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты что-то $Gпонял:поняла;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Келтусу Темному Листу в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9461,'Зов Огня','Пророк заинтересовался тобой, услышав об успешном прохождении испытания. Прежде чем создать Тотем огня, тебе следует поговорить с ним.$B$BМало кому выпадает эта честь, спеши в Экзодар на встречу с Пророком!','Найдите Пророка Велена в Чертоге Света Экзодара.','Здравствуйте, $N, я Вас ждала. Надеюсь, у Вас был хороший день ?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пророк заинтересовался тобой, услышав об успешном прохождении испытания. Прежде чем создать Тотем огня, тебе следует поговорить с ним.$B$BМало кому выпадает эта честь, спеши в Экзодар на встречу с Пророком!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Пророка Велена в Чертоге Света Экзодара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здравствуйте, $N, я Вас ждала. Надеюсь, у Вас был хороший день ?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9462,'Зов Огня','$n! Пришло время двинуться дальше по пути духов. Отыщи Тулууна, шамана Лазурной заставы. Он начнет обучать тебя пониманию и усмирению силы пламени.','Поговорите с Тулууном на Лазурной заставе на острове Лазурной Дымки.','Как раз вовремя, $N. Надеюсь, вы готовы продолжить обучение. Следующая задача будет сложной.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Пришло время двинуться дальше по пути духов. Отыщи Тулууна, шамана Лазурной заставы. Он начнет обучать тебя пониманию и усмирению силы пламени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Тулууном на Лазурной заставе на острове Лазурной Дымки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как раз вовремя, $N. Надеюсь, вы готовы продолжить обучение. Следующая задача будет сложной.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9463,'Ради науки','Выяснилось, что побеги хлестунов, которые растут на острове, имеют целебные свойства. При правильной обработке из них получается сильнодействующая лечебная мазь. К сожалению, на Лазурной заставе так много раненых дренеев, что никаких запасов не хватает.$B$BНашу хрупкую гостью нашли вчера возле Хрустального ручья. Если ты принесешь мне побеги – кто знает, может быть, удастся ее спасти.$B$BКорнехватов можно отыскать на юге и на востоке от Лазурной заставы.','Принесите 8 побегов корнехватов анахорету Фатиме на Лазурную заставу.','Будем надеяться, что мазь укрепит ее дух и поможет больной встать на ноги!','Боюсь, что состояние нашей больной стремительно ухудшается.','Вернитесь к анахорету Фатиме на Лазурную заставу, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ради науки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Выяснилось, что побеги хлестунов, которые растут на острове, имеют целебные свойства. При правильной обработке из них получается сильнодействующая лечебная мазь. К сожалению, на Лазурной заставе так много раненых дренеев, что никаких запасов не хватает.$B$BНашу хрупкую гостью нашли вчера возле Хрустального ручья. Если ты принесешь мне побеги – кто знает, может быть, удастся ее спасти.$B$BКорнехватов можно отыскать на юге и на востоке от Лазурной заставы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 побегов корнехватов анахорету Фатиме на Лазурную заставу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Будем надеяться, что мазь укрепит ее дух и поможет больной встать на ноги!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Боюсь, что состояние нашей больной стремительно ухудшается.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Фатиме на Лазурную заставу, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9464,'Зов Огня','И снова тебя ожидает испытание. На сей раз ты $gдолжен:должна; понять хаотическую составляющую огня, если собираешься создать тотем, обуздывающий его силу.$B$BНа северо-востоке находится священное место огня, именуемое Тлеющая поляна. Среди ее опаленных деревьев стоит Пламенрав, могущественный элементаль огня, и с ним-то тебе и предстоит поговорить.$B$BСтупай к нему, и да хранят тебя все стихии Азерота.','Поговорите с Пламенравом на Тлеющей поляне на острове Лазурной Дымки.','Я верю, что огонь в твоих глазах, вызвано желанием расти и понимать? Хорошо!$B$BТулуун отправил тебя сюда, потому что он видит твой потенциал как ученика, так и помощника в решении проблем, вызванных крахом вашего Экзодара. $B$BУвидимся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И снова тебя ожидает испытание. На сей раз ты $gдолжен:должна; понять хаотическую составляющую огня, если собираешься создать тотем, обуздывающий его силу.$B$BНа северо-востоке находится священное место огня, именуемое Тлеющая поляна. Среди ее опаленных деревьев стоит Пламенрав, могущественный элементаль огня, и с ним-то тебе и предстоит поговорить.$B$BСтупай к нему, и да хранят тебя все стихии Азерота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Пламенравом на Тлеющей поляне на острове Лазурной Дымки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я верю, что огонь в твоих глазах, вызвано желанием расти и понимать? Хорошо!$B$BТулуун отправил тебя сюда, потому что он видит твой потенциал как ученика, так и помощника в решении проблем, вызванных крахом вашего Экзодара. $B$BУвидимся.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9465,'Зов Огня','Верните ритуальный факел Пламенраву в Тлеющую поляну на острове Лазурной Дымки.','Видишь, его огонь не гаснет? Это работа Спесивеца. Это символ его высокомерия. Пламя предназначено для того, чтобы поглотить то, что оно сжигает, а затем само умереть, чтобы возродиться заново в другой раз. $B$BЯ помогу тебе , чтобы мы могли справиться с Спесивецем. Дадим ему погореть еще немного.','У тебя есть факел?','Вернитесь к Пламенраву на Тлеющую поляну, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните ритуальный факел Пламенраву в Тлеющую поляну на острове Лазурной Дымки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Видишь, его огонь не гаснет? Это работа Спесивеца. Это символ его высокомерия. Пламя предназначено для того, чтобы поглотить то, что оно сжигает, а затем само умереть, чтобы возродиться заново в другой раз. $B$BЯ помогу тебе , чтобы мы могли справиться с Спесивецем. Дадим ему погореть еще немного.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть факел?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пламенраву на Тлеющую поляну, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9467,'Зов Огня','Добудьте пепел Спесивца и принесите его и ритуальный факел Пламенраву на Тлеющую поляну на острове Лазурной Дымки. Можно воспользоваться Сферой возвращения, чтобы телепортироваться к Пламенраву.','Это ценный урок, который ты $Gусвоил:усвоила; сегодня здесь. Это история окончаний и новых начинаний. $B$BКогда мы впервые разговаривали, я сказал тебе, что огонь - это не только разрушение, но и обновляющая сила стихий. Своими действиями ты $Gуничтожил:уничтожила; и $Gспас:спасла; Спесивеца, ибо он возродится из пепла.','Не говори со мной , пока не соберешь прах Отера.','Вернитесь к Пламенраву на Тлеющую поляну, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте пепел Спесивца и принесите его и ритуальный факел Пламенраву на Тлеющую поляну на острове Лазурной Дымки. Можно воспользоваться Сферой возвращения, чтобы телепортироваться к Пламенраву.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это ценный урок, который ты $Gусвоил:усвоила; сегодня здесь. Это история окончаний и новых начинаний. $B$BКогда мы впервые разговаривали, я сказал тебе, что огонь - это не только разрушение, но и обновляющая сила стихий. Своими действиями ты $Gуничтожил:уничтожила; и $Gспас:спасла; Спесивеца, ибо он возродится из пепла.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не говори со мной , пока не соберешь прах Отера.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пламенраву на Тлеющую поляну, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9468,'Зов Огня','Сегодня тебе удалось далеко продвинуться по пути постижения сути огня. Относись к нему с уважением, или пламя пожрет тебя!$B$BЯ оставил тебе немного пепла Спесивца. Используй его для создания тотема огня и помни все, чему ты $Gнаучился:научилась;.$B$BА теперь возвращайся к Тулууну.','Отнесите пепел Спесивца Тулууну на Лазурную заставу на острове Лазурной Дымки.','Ты $Gпрошел:прошла; через очищающий огонь разрушения и $Gобновился:обновилась;, $N. Это мало чем отличается от скорби, которую в настоящее время испытывает народ $R. И, спасая Хаунтера от самого себя, ты обеспечила себе связь с стихией огня этого мира.','Вы выглядите немного подписанным по краям. Каково твое общение с пламенем, $C?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня тебе удалось далеко продвинуться по пути постижения сути огня. Относись к нему с уважением, или пламя пожрет тебя!$B$BЯ оставил тебе немного пепла Спесивца. Используй его для создания тотема огня и помни все, чему ты $Gнаучился:научилась;.$B$BА теперь возвращайся к Тулууну.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите пепел Спесивца Тулууну на Лазурную заставу на острове Лазурной Дымки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпрошел:прошла; через очищающий огонь разрушения и $Gобновился:обновилась;, $N. Это мало чем отличается от скорби, которую в настоящее время испытывает народ $R. И, спасая Хаунтера от самого себя, ты обеспечила себе связь с стихией огня этого мира.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы выглядите немного подписанным по краям. Каково твое общение с пламенем, $C?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9469,'Встреча с Перобородом','Когда меня, наконец, удостоят аудиенции с Фалстадом Громовым Молотом, я хочу, чтобы вместе со мной пошел один из наших лучших представителей среди дворфов.$B$BБольшим уважением среди них пользуется Перобород – во-первых, за его потрясающее мастерство дрессировки грифонов, а во-вторых, за его мудрость. Если кто и сможет убедить Фалстада Громового Молота, то только он.$B$BЯ бы сходил к Перобороду сам, но мне нельзя покидать Заоблачный пик, потому что аудиенцию могут назначить в любой момент. Пожалуйста, сходите к нему и спросите, не согласится ли он поговорить со мной. Перобород живет на юге.','Навестите дворфа Пероборода в его домике. Если там его нет, то поищите, где он может быть.','В дневнике Пероборода очень много записей. Вы пролистываете его до конца и ищете в тексте информацию о том, где может быть хозяин.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с Перобородом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда меня, наконец, удостоят аудиенции с Фалстадом Громовым Молотом, я хочу, чтобы вместе со мной пошел один из наших лучших представителей среди дворфов.$B$BБольшим уважением среди них пользуется Перобород – во-первых, за его потрясающее мастерство дрессировки грифонов, а во-вторых, за его мудрость. Если кто и сможет убедить Фалстада Громового Молота, то только он.$B$BЯ бы сходил к Перобороду сам, но мне нельзя покидать Заоблачный пик, потому что аудиенцию могут назначить в любой момент. Пожалуйста, сходите к нему и спросите, не согласится ли он поговорить со мной. Перобород живет на юге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Навестите дворфа Пероборода в его домике. Если там его нет, то поищите, где он может быть.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В дневнике Пероборода очень много записей. Вы пролистываете его до конца и ищете в тексте информацию о том, где может быть хозяин.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9470,'Жест доброй воли','Кроме дворфов и их грифонов во Внутренних землях живут еще и лесные тролли.$B$BЭти тролли считают, что дворфы оскверняют их священные земли, и никогда не упускают возможности напасть на грифонов. Отличный шанс снискать уважение Громового Молота – убить главу племени Сухокожих, знахаря Май\'джина. Это поумерит наглость троллей. Май\'джин живет в Гроте Богена, это к западу от Шадра\'Алор.','Убейте знахаря Май\'джина и его питомца-паука Чаказа по поручению посла Руалета с Заоблачного пика.','Большое спасибо, $n. Дворфы Громового Молота будут рады узнать, что противостоят троллям племени Сухокожих не в одиночку. Пусть тролли знают, что на нашей стороне грифоны – глядишь, наглость свою и поумерят.','Ты $Gвернулся:вернулась; с новостями о смерти знахаря Май\'джина?','Вернитесь к послу Руалету на Заоблачный пик, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жест доброй воли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кроме дворфов и их грифонов во Внутренних землях живут еще и лесные тролли.$B$BЭти тролли считают, что дворфы оскверняют их священные земли, и никогда не упускают возможности напасть на грифонов. Отличный шанс снискать уважение Громового Молота – убить главу племени Сухокожих, знахаря Май\'джина. Это поумерит наглость троллей. Май\'джин живет в Гроте Богена, это к западу от Шадра\'Алор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте знахаря Май\'джина и его питомца-паука Чаказа по поручению посла Руалета с Заоблачного пика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большое спасибо, $n. Дворфы Громового Молота будут рады узнать, что противостоят троллям племени Сухокожих не в одиночку. Пусть тролли знают, что на нашей стороне грифоны – глядишь, наглость свою и поумерят.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась; с новостями о смерти знахаря Май\'джина?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к послу Руалету на Заоблачный пик, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9471,'Охота на хищников','Дворфы из клана Громового Молота – верные товарищи и отличные дрессировщики для грифонов, у которых полно врагов, в особенности среди лесных троллей.$B$BОднако помимо троллей у них есть и естественные враги, например, волки. Один волк грифону не страшен, но они часто нападают стаей, потому что другой добычи здесь мало. Если уменьшить поголовье волков, то местные леса станут чуть безопаснее для грифонов, а дворфы будут нам благодарны.','Убейте 10 облезлых среброгривов и 5 среброгривых волков по поручению посла Руалета с Заоблачного пика.','Посол Руалет кивает и берет у вас отчет $B$BВы отлично справились. Клан Громового Молота обязательно узнает о том, что поголовье среброгривов уменьшилось. Когда я встречусь с их предводителями, я непременно прослежу за тем, чтобы ваши старания не прошли незамеченными перед Альянсом. Пожалуйста, примите это в знак моей благодарности, $n.','Ты $Gуничтожил:уничтожила; популяцию серебристой гривы?','Вернитесь к послу Руалету на Заоблачный пик, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на хищников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дворфы из клана Громового Молота – верные товарищи и отличные дрессировщики для грифонов, у которых полно врагов, в особенности среди лесных троллей.$B$BОднако помимо троллей у них есть и естественные враги, например, волки. Один волк грифону не страшен, но они часто нападают стаей, потому что другой добычи здесь мало. Если уменьшить поголовье волков, то местные леса станут чуть безопаснее для грифонов, а дворфы будут нам благодарны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 облезлых среброгривов и 5 среброгривых волков по поручению посла Руалета с Заоблачного пика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посол Руалет кивает и берет у вас отчет $B$BВы отлично справились. Клан Громового Молота обязательно узнает о том, что поголовье среброгривов уменьшилось. Когда я встречусь с их предводителями, я непременно прослежу за тем, чтобы ваши старания не прошли незамеченными перед Альянсом. Пожалуйста, примите это в знак моей благодарности, $n.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gуничтожил:уничтожила; популяцию серебристой гривы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к послу Руалету на Заоблачный пик, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9472,'Любовница Арелиона','У Арелиона было столько важных дел, а он тратил свое время на какую-то любовницу!$B$BТеперь-то мне все ясно. Виера Шепот Солнца, эта маленькая потаскушка... Я покажу ей, как переходить дорогу магистру!$B$BВозьми свиток. Разыщи Виеру и вымани ее из города. Когда это удастся, прочитай над ней заклинание.$B$BАрелион упоминал, что эта маленькая дрянь обожает вино, которое делают друиды. Я думаю, его можно найти в Кенарийском оплоте, как раз в Зангартопи, к западу отсюда.','Выманите Виеру Шепот Солнца из поселения и примените к ней Свиток Воздаяния Каринды по приказу магистра Каринды из Соколиного Дозора.','Так, $N. Готово?','Вернитесь к магистру Каринде в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любовница Арелиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Арелиона было столько важных дел, а он тратил свое время на какую-то любовницу!$B$BТеперь-то мне все ясно. Виера Шепот Солнца, эта маленькая потаскушка... Я покажу ей, как переходить дорогу магистру!$B$BВозьми свиток. Разыщи Виеру и вымани ее из города. Когда это удастся, прочитай над ней заклинание.$B$BАрелион упоминал, что эта маленькая дрянь обожает вино, которое делают друиды. Я думаю, его можно найти в Кенарийском оплоте, как раз в Зангартопи, к западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выманите Виеру Шепот Солнца из поселения и примените к ней Свиток Воздаяния Каринды по приказу магистра Каринды из Соколиного Дозора.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так, $N. Готово?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Каринде в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9473,'Другое решение','Принесите 5 луковиц лазурного львиного зева Дедалу на Лазурную заставу.','Смотри, как растение исцеляет больную.','Время на исходе! Торопись!','Вернитесь к Дедалу на Лазурную заставу, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Другое решение',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 луковиц лазурного львиного зева Дедалу на Лазурную заставу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смотри, как растение исцеляет больную.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Время на исходе! Торопись!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дедалу на Лазурную заставу, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9474,'Знак Светоносного','То недолгое время, что я пробыл в Азероте, я посвятил изучению великих героев. Славнейший из них Утер Светоносный, преданный самым лучшим своим учеником, Артасом.$b$bЯ бы хотел почтить его память и отнести одну из утраченных им вещей к его гробнице. Говорят, что сторонники Алого ордена держат на одной из сторожевых башен рядом с воротами Дольного Очага реликвию Утера.$b$bПрошу тебя, |3-6($c), ступай и принеси ее.','Добудьте знак Светоносного и принесите его анахорету Трууну в Лагерь Промозглого Ветра, что Западных Чумных землях.','Спасибо, |3-6($C)! Возвращение реликвии – большая радость для всех, кто чтит память Утера Светоносного.','Знак Светоносного – могущественный символ веры Утера в Свет.','Вернитесь к анахорету Трууну в Лагерь Промозглого Ветра, что в Западных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак Светоносного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То недолгое время, что я пробыл в Азероте, я посвятил изучению великих героев. Славнейший из них Утер Светоносный, преданный самым лучшим своим учеником, Артасом.$b$bЯ бы хотел почтить его память и отнести одну из утраченных им вещей к его гробнице. Говорят, что сторонники Алого ордена держат на одной из сторожевых башен рядом с воротами Дольного Очага реликвию Утера.$b$bПрошу тебя, |3-6($c), ступай и принеси ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте знак Светоносного и принесите его анахорету Трууну в Лагерь Промозглого Ветра, что Западных Чумных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, |3-6($C)! Возвращение реликвии – большая радость для всех, кто чтит память Утера Светоносного.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знак Светоносного – могущественный символ веры Утера в Свет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Трууну в Лагерь Промозглого Ветра, что в Западных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9475,'Похищенные яйца','Осмотрев скелет, вы понимаете, что это все, что осталось от бедного Пероборода. В одной руке скелет сжимает истлевший кусок бумаги, который вы осторожно вынимаете и разворачиваете. На бумаге от руки нарисована карта и нацарапаны какие-то заметки.$B$BСудя по всему, это схема Шадра\'Алор, и три местных храма тут отмечены крестиками – должно быть, именно там находятся украденные яйца. Вы прячете карту в сумку, чтобы потом, в безопасном месте, рассмотреть ее поподробнее.','Соберите 5 яиц грифона и принесите их послу Руалету на Заоблачный пик.','Вы отдаете послу яйца и рассказываете о том, что обнаружили в лачуге Пероборода и в Шадра\'Алор $B$BТролли Сухокожих убили Пероборода?$B$B Риалет приходит в ужас, услышав об ужасной смерти дворфа и о ее последствиях $B$BЯ понимаю, почему он пошел искать яйца сам, но лучше бы он привел с собой подмогу. Вне всяких сомнений, его смерть приведет Фалстада Громового Молота в ярость, и моя аудиенция будет вновь отложена на неопределенный срок.','Судя по вашему виду, вы принесли мне дурные вести. Что вам удалось узнать?','Вернитесь к послу Руалету на Заоблачный пик, что во Внутренних землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищенные яйца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Осмотрев скелет, вы понимаете, что это все, что осталось от бедного Пероборода. В одной руке скелет сжимает истлевший кусок бумаги, который вы осторожно вынимаете и разворачиваете. На бумаге от руки нарисована карта и нацарапаны какие-то заметки.$B$BСудя по всему, это схема Шадра\'Алор, и три местных храма тут отмечены крестиками – должно быть, именно там находятся украденные яйца. Вы прячете карту в сумку, чтобы потом, в безопасном месте, рассмотреть ее поподробнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 яиц грифона и принесите их послу Руалету на Заоблачный пик.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы отдаете послу яйца и рассказываете о том, что обнаружили в лачуге Пероборода и в Шадра\'Алор $B$BТролли Сухокожих убили Пероборода?$B$B Риалет приходит в ужас, услышав об ужасной смерти дворфа и о ее последствиях $B$BЯ понимаю, почему он пошел искать яйца сам, но лучше бы он привел с собой подмогу. Вне всяких сомнений, его смерть приведет Фалстада Громового Молота в ярость, и моя аудиенция будет вновь отложена на неопределенный срок.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Судя по вашему виду, вы принесли мне дурные вести. Что вам удалось узнать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к послу Руалету на Заоблачный пик, что во Внутренних землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9476,'В поисках Пероборода','В последних записях дневника Перобород выражает свое беспокойство участившимися нападениями троллей племени Сухокожих на грифонов Громового Молота и постоянными кражами грифоньих яиц. Разведка в маленьком поселении племени Сухокожих не дала никаких результатов.$B$BВ последней записи Перобород пишет о своих подозрениях насчет того, что за этими набегами может стоять знахарь Майд\'жин, а в самом последнем, поспешно накарябанном предложении говорится о том, что дворф собирался пойти в Шадра\'Алор и поискать яйца там.','Отправляйтесь в Шадра\'Алор и поищите следы Пероборода.','На алтаре лежит куча костей, с виду принадлежавших дворфу. Никаких особых примет не видно, но вы решаете осмотреть тело и убедиться в том, что это и впрямь останки Пероборода.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Пероборода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В последних записях дневника Перобород выражает свое беспокойство участившимися нападениями троллей племени Сухокожих на грифонов Громового Молота и постоянными кражами грифоньих яиц. Разведка в маленьком поселении племени Сухокожих не дала никаких результатов.$B$BВ последней записи Перобород пишет о своих подозрениях насчет того, что за этими набегами может стоять знахарь Майд\'жин, а в самом последнем, поспешно накарябанном предложении говорится о том, что дворф собирался пойти в Шадра\'Алор и поискать яйца там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Шадра\'Алор и поищите следы Пероборода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На алтаре лежит куча костей, с виду принадлежавших дворфу. Никаких особых примет не видно, но вы решаете осмотреть тело и убедиться в том, что это и впрямь останки Пероборода.',`offerrewardtext_loc8`);
