INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9482,'<UNUSED>Зелье сопротивления силам природы','Вернитесь к эмиссару Гормоку в Восточные Чумные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>Зелье сопротивления силам природы',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к эмиссару Гормоку в Восточные Чумные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9483,'Изысканные удовольствия жизни','Думаю, мы можем подружиться. Давай со мной, мы ведь не хотим ни с кем делиться, правда?','Вернитесь к Виере Шепот Солнца в Соколиный Дозор, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изысканные удовольствия жизни',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Думаю, мы можем подружиться. Давай со мной, мы ведь не хотим ни с кем делиться, правда?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Виере Шепот Солнца в Соколиный Дозор, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9484,'Приручение зверя','Несомненно, тебе неоднократно доводилось охотиться на зверей и убивать их как ради пропитания, так и ради самозащиты. Но теперь тебе уже по силам подружиться с ними и использовать их способности в своих целях. Я научу тебя, как это сделать.$b$bВот, возьми этот магический хлыст приручения. Он позволяет временно подчинить себе дикого зверя и заставить его сражаться на твоей стороне. Начни с безумного дракондора, сравнительно мирной птицы. Они водятся поблизости от Обители Странников. Когда управишься, возвращайся ко мне.','Приручите безумного дракондора с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.','Выдержать многочисленные удары и укусы дракондора - признак твоего упорства. Есть ли у тебя силы узнать больше?','Ты $Gосвоил:освоила; дракондора?','Приручите безумного дракондора','Вернитесь к Лейтенанту Вестнице Зари в Обитель Странников, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несомненно, тебе неоднократно доводилось охотиться на зверей и убивать их как ради пропитания, так и ради самозащиты. Но теперь тебе уже по силам подружиться с ними и использовать их способности в своих целях. Я научу тебя, как это сделать.$b$bВот, возьми этот магический хлыст приручения. Он позволяет временно подчинить себе дикого зверя и заставить его сражаться на твоей стороне. Начни с безумного дракондора, сравнительно мирной птицы. Они водятся поблизости от Обители Странников. Когда управишься, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приручите безумного дракондора с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Выдержать многочисленные удары и укусы дракондора - признак твоего упорства. Есть ли у тебя силы узнать больше?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gосвоил:освоила; дракондора?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите безумного дракондора',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лейтенанту Вестнице Зари в Обитель Странников, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9485,'Приручение зверя','Молодец, $n! Ты быстро обучаешься понимать природу.$b$bМрачница – хитроумный охотник, она сочетает стремительность дракондора с яростью прыголапа. Мрачницы водятся к югу от реки Элрендар и нападают на злосчастных путников, которые забредают в Призрачные земли.$b$bИспользуй этот последний хлыст приручения, чтобы подружиться с мрачницей, а когда управишься, возвращайся ко мне.','Приручите мрачницу с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.','Итак, как видишь, $N, мне уже нечему тебя учить. Ты уже понимаешь, что значит дружить с теми, на кого когда-то $Gохотился:охотилась;. Тебе нужно только выбрать одного из союзников природы с чертами, соответствующим твоим собственным.','Ты $Gприручил:приручила; Мрачницу?','Мрачница приручена','Вернитесь к Лейтенанту Вестнице Зари в Обитель Странников, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Молодец, $n! Ты быстро обучаешься понимать природу.$b$bМрачница – хитроумный охотник, она сочетает стремительность дракондора с яростью прыголапа. Мрачницы водятся к югу от реки Элрендар и нападают на злосчастных путников, которые забредают в Призрачные земли.$b$bИспользуй этот последний хлыст приручения, чтобы подружиться с мрачницей, а когда управишься, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приручите мрачницу с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, как видишь, $N, мне уже нечему тебя учить. Ты уже понимаешь, что значит дружить с теми, на кого когда-то $Gохотился:охотилась;. Тебе нужно только выбрать одного из союзников природы с чертами, соответствующим твоим собственным.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gприручил:приручила; Мрачницу?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Мрачница приручена',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лейтенанту Вестнице Зари в Обитель Странников, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9486,'Приручение зверя','Взрослый прыголап – ловкий охотник. Сдружиться с ним непросто – ведь поначалу он считает тебя добычей. Но ты не отчаивайся.$b$bИспользуй хлыст приручения, подчини себе эту крупную кошку и попробуй поохотиться вместе с ней. Прыголапы водятся в Лесах Вечной Песни повсюду, и порой подходят совсем близко к жилью. Когда управишься, возвращайся ко мне.','Приручите взрослого прыголапа с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.','Ты $Gпроявил:проявил; силу и упорство. Остается последнее испытание, пока ты не сможешь приручать без использования магии.','Вы охотились вместе с прыгуном?','Приручите взрослого прыголапа','Вернитесь к Лейтенанту Вестнице Зари в Обитель Странников, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взрослый прыголап – ловкий охотник. Сдружиться с ним непросто – ведь поначалу он считает тебя добычей. Но ты не отчаивайся.$b$bИспользуй хлыст приручения, подчини себе эту крупную кошку и попробуй поохотиться вместе с ней. Прыголапы водятся в Лесах Вечной Песни повсюду, и порой подходят совсем близко к жилью. Когда управишься, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Приручите взрослого прыголапа с помощью хлыста приручения, потом вернитесь к лейтенанту Вестнице Зари.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпроявил:проявил; силу и упорство. Остается последнее испытание, пока ты не сможешь приручать без использования магии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы охотились вместе с прыгуном?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручите взрослого прыголапа',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лейтенанту Вестнице Зари в Обитель Странников, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9487,'Волшебные разорители','Волшебные разорители – создания, наделенные неземной силой. Они защищены крепкой броней, их удары сокрушительны. Однако ты можешь обойти их защиту и избежать их атак. Твое заклинательское искусство дает тебе неоспоримые преимущества, $n.$b$bОтправляйся в Башню Утренней Звезды и разнеси в клочья этих магических стражей. Из останков собери осколки кристаллизованной магический энергии, а потом возвращайся ко мне. Башня Утренней Звезды находится на востоке, за озером.','Чародей Вандрил хочет, чтобы вы принесли ему 10 осколков тайной магии.','Как же непродуктивно тратить магию на создание тварей, обладающих только физической силой! В конце концов, разве не ради грубой силы мы заключили союз с низшими расами?$B$BХорошо, что ты $Gуничтожил:уничтожила; их, теперь мы используем эти осколки для более подходящих целей.','Надеюсь, тебе удалось подобраться к этим тварям?','Вернитесь к чародею Вандрилу в Ан\'дарот, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волшебные разорители',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волшебные разорители – создания, наделенные неземной силой. Они защищены крепкой броней, их удары сокрушительны. Однако ты можешь обойти их защиту и избежать их атак. Твое заклинательское искусство дает тебе неоспоримые преимущества, $n.$b$bОтправляйся в Башню Утренней Звезды и разнеси в клочья этих магических стражей. Из останков собери осколки кристаллизованной магический энергии, а потом возвращайся ко мне. Башня Утренней Звезды находится на востоке, за озером.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Чародей Вандрил хочет, чтобы вы принесли ему 10 осколков тайной магии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как же непродуктивно тратить магию на создание тварей, обладающих только физической силой! В конце концов, разве не ради грубой силы мы заключили союз с низшими расами?$B$BХорошо, что ты $Gуничтожил:уничтожила; их, теперь мы используем эти осколки для более подходящих целей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, тебе удалось подобраться к этим тварям?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Вандрилу в Ан\'дарот, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9488,'Простое одеяние','Те осколки тайной магии, что ты $Gдобыл:добыла;, пригодятся как нельзя лучше.$b$bСпрашиваешь, для чего? Да для изготовления замечательного одеяния для $Gтакого:такой:c; |3-6($c), как ты!$b$bНам нужно всего-то немного льняной ткани и паутинная железа. Железу можно добыть у любого паука-прядильщика, лучше у предварительно убитого.','Чародей Вандрил хочет, чтобы вы принесли ему 15 кусков льняной ткани и паутинную железу паука-прядильщика.','Тебе незачем знать все тонкости создания магического одеяния, $N, просто запоминай, что мне от тебя нужно, и приноси. $B$BБуду с тобой честным – того, что ты уже $Gпринес:принесла;, хватит на несколько одеяний. Выручка с их продажи с лихвой покроет все мои издержки на изготовление твоего одеяния, и даже останется на что-нибудь приятненькое. Похоже, это я тебя благодарить должен!','Это одеяние нельзя закончить без некоторых необходимых материалов. Но ведь ты и $Gсам:сама; это знаешь, не так ли?','Вернитесь к чародею Вандрилу в Ан\'дарот, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Простое одеяние',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Те осколки тайной магии, что ты $Gдобыл:добыла;, пригодятся как нельзя лучше.$b$bСпрашиваешь, для чего? Да для изготовления замечательного одеяния для $Gтакого:такой:c; |3-6($c), как ты!$b$bНам нужно всего-то немного льняной ткани и паутинная железа. Железу можно добыть у любого паука-прядильщика, лучше у предварительно убитого.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Чародей Вандрил хочет, чтобы вы принесли ему 15 кусков льняной ткани и паутинную железу паука-прядильщика.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе незачем знать все тонкости создания магического одеяния, $N, просто запоминай, что мне от тебя нужно, и приноси. $B$BБуду с тобой честным – того, что ты уже $Gпринес:принесла;, хватит на несколько одеяний. Выручка с их продажи с лихвой покроет все мои издержки на изготовление твоего одеяния, и даже останется на что-нибудь приятненькое. Похоже, это я тебя благодарить должен!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это одеяние нельзя закончить без некоторых необходимых материалов. Но ведь ты и $Gсам:сама; это знаешь, не так ли?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Вандрилу в Ан\'дарот, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9489,'Поднять боевой дух','А, $n! Хорошо, что ты здесь. Яростные атаки Плети вселяют отчаяние в души наших городских стражей...$b$bСтупай скорее на Тропу Мертвых к югу от города. Там стоят в дозоре Джаэла и ее следопыты. Благослови их, наполни их силой Света!','Наложите Слово Силы: Стойкость на 6 следопытов Лесов Вечной Песни на Тропе Мертвых.','Хорошо, что ты ищешь моего руководства. Веками я обучал молодых $R воинов, так что я могу кое-что знать о том, с чего вам следует начать. Я вижу в тебе задатки великого $C, но только если ты внимательно прислушиваешься к тому, чему я должен учить. $B$BТы готов учиться, юный $C?','Вы дали надежду там, где она угасла?','Вернитесь к Понарису на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поднять боевой дух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, $n! Хорошо, что ты здесь. Яростные атаки Плети вселяют отчаяние в души наших городских стражей...$b$bСтупай скорее на Тропу Мертвых к югу от города. Там стоят в дозоре Джаэла и ее следопыты. Благослови их, наполни их силой Света!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наложите Слово Силы: Стойкость на 6 следопытов Лесов Вечной Песни на Тропе Мертвых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты ищешь моего руководства. Веками я обучал молодых $R воинов, так что я могу кое-что знать о том, с чего вам следует начать. Я вижу в тебе задатки великого $C, но только если ты внимательно прислушиваешься к тому, чему я должен учить. $B$BТы готов учиться, юный $C?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы дали надежду там, где она угасла?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Понарису на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9491,'Жадность','Вчера сюда заявился до неприличия богатый торговец. Говорил о каком-то кольце "чрезвычайной археологический важности", которое вроде бы заперто в одном из бесчисленных погребальных сундуков в катакомбах Амани. Потом он еще долго рассказывал, сколько готов за это самое кольцо отвалить.$b$bДавай так: я добуду воровской инструмент, и если тебе удастся принести колечко, то отсыплю тебе столько, что на десяток колечек хватит!','Эраланна из Транквиллиона хочет, чтобы вы добыли исцарапанное золотое кольцо из катакомб Амани.','Это кольцо? Не на что смотреть, но вы знаете, что говорят про мусор одного эльфа…$B$BИ не забудем про твою оплату. Не стесняйся тратить его прямо здесь, $Gбрат:сестра;!','Пожалуйста, скажи мне, что ты $Gнашел:нашла; кольцо.','Вернитесь к Эраланне в Транквиллион, что в Призрачных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жадность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вчера сюда заявился до неприличия богатый торговец. Говорил о каком-то кольце "чрезвычайной археологический важности", которое вроде бы заперто в одном из бесчисленных погребальных сундуков в катакомбах Амани. Потом он еще долго рассказывал, сколько готов за это самое кольцо отвалить.$b$bДавай так: я добуду воровской инструмент, и если тебе удастся принести колечко, то отсыплю тебе столько, что на десяток колечек хватит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Эраланна из Транквиллиона хочет, чтобы вы добыли исцарапанное золотое кольцо из катакомб Амани.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это кольцо? Не на что смотреть, но вы знаете, что говорят про мусор одного эльфа…$B$BИ не забудем про твою оплату. Не стесняйся тратить его прямо здесь, $Gбрат:сестра;!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пожалуйста, скажи мне, что ты $Gнашел:нашла; кольцо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Эраланне в Транквиллион, что в Призрачных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9492,'Новый поворот событий','Запределье живет в постоянном ожидании нападения орков, такова печальная истина. Было время, когда Сыны Лотара думали, что смогут оплатить безопасность Оплота Чести ценой собственной крови, но и это не принесло мира.$B$BТеперь Сыны не потерпят на своих землях никаких орков – ни зеленых, ни кориченевых, ни красных! Мы победим их или умрем, сражаясь. У нас есть шансы на победу, если мы сразимся с ними в Цитадели Адского Пламени. Принеси мне оружие их самозваного вождя Каргата Острорука, и я щедро награжу тебя.','Принесите кулак вождя Каргата командиру армии Данату Троллебою в Оплот Чести.','$GМолодец:Умница;, $N. Благодаря вашей победе в Цитадели Адского Пламени мы нанесли серьезный удар по оркам.$B$BЯ должен поговорить с полевым командиром Ромусом о последующих действиях и обеспечении того, чтобы орки продолжали обороняться. Теперь, когда мы получили подкрепление, мы можем сделать гораздо больше, чем просто защитить Оплот Чести.','Вы вернулись с доказательствами кончины вождя Каргата Острорука?','Вернитесь к командиру армии Данату Троллебою в Оплот Чести, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый поворот событий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Запределье живет в постоянном ожидании нападения орков, такова печальная истина. Было время, когда Сыны Лотара думали, что смогут оплатить безопасность Оплота Чести ценой собственной крови, но и это не принесло мира.$B$BТеперь Сыны не потерпят на своих землях никаких орков – ни зеленых, ни кориченевых, ни красных! Мы победим их или умрем, сражаясь. У нас есть шансы на победу, если мы сразимся с ними в Цитадели Адского Пламени. Принеси мне оружие их самозваного вождя Каргата Острорука, и я щедро награжу тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите кулак вождя Каргата командиру армии Данату Троллебою в Оплот Чести.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N. Благодаря вашей победе в Цитадели Адского Пламени мы нанесли серьезный удар по оркам.$B$BЯ должен поговорить с полевым командиром Ромусом о последующих действиях и обеспечении того, чтобы орки продолжали обороняться. Теперь, когда мы получили подкрепление, мы можем сделать гораздо больше, чем просто защитить Оплот Чести.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы вернулись с доказательствами кончины вождя Каргата Острорука?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру армии Данату Троллебою в Оплот Чести, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9493,'Элита Орды Скверны','Мы мало что знаем об Орде Скверны, хотя за информацию заплачено многими жизнями.$B$BКаргат Острорук командует безжалостными, закаленными в боях воинами, чьи возможности к тому же усилены магией скверны. У этого войска есть своя элита – легионеры, воители и центурионы клана Изувеченной Длани. Они внушают страх обычным солдатам и исполняют роль офицерского состава.$B$BЕсли мы хотим добиться хоть каких-то успехов в сражении с Ордой Скверны, сначала надо лишить ее командования.','Убейте 8 легионеров клана Изувеченной Длани, 4 центуриона клана Изувеченной Длани и 4 воителей клана Изувеченной Длани по приказу боевого командира Ромуса из Оплота Чести.','Это действительно отличная новость, $N. Учитывая прогресс в сообщении из Цитадели Адского Пламени, возможно, мы сможем позволить себе обратить внимание на присутствие Орды Скверны в других частях полуострова и Запределья в целом.','Я не настолько наивен, чтобы думать, что поражение легионеров Изувеченной Длани знаменует нашу победу над Ордой Скверны, но это хороший первый шаг.','Вернитесь к боевому командиру Ромусу на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Элита Орды Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы мало что знаем об Орде Скверны, хотя за информацию заплачено многими жизнями.$B$BКаргат Острорук командует безжалостными, закаленными в боях воинами, чьи возможности к тому же усилены магией скверны. У этого войска есть своя элита – легионеры, воители и центурионы клана Изувеченной Длани. Они внушают страх обычным солдатам и исполняют роль офицерского состава.$B$BЕсли мы хотим добиться хоть каких-то успехов в сражении с Ордой Скверны, сначала надо лишить ее командования.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 легионеров клана Изувеченной Длани, 4 центуриона клана Изувеченной Длани и 4 воителей клана Изувеченной Длани по приказу боевого командира Ромуса из Оплота Чести.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это действительно отличная новость, $N. Учитывая прогресс в сообщении из Цитадели Адского Пламени, возможно, мы сможем позволить себе обратить внимание на присутствие Орды Скверны в других частях полуострова и Запределья в целом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не настолько наивен, чтобы думать, что поражение легионеров Изувеченной Длани знаменует нашу победу над Ордой Скверны, но это хороший первый шаг.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому командиру Ромусу на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9494,'Угли Скверны','Наши твердолобые азеротские академики слишком засиделись в своих башнях. Пришло время показать им, что такое настоящие исследования! Дескать, они боятся играть с огнем. Ничего, как только у меня окажется огонь, я вдоволь с ним поиграю!$B$BВ Разрушенных залах Цитадели Адского Пламени главный чернокнижник Пустоклят достиг невероятного магического мастерства, используя силу двух странных жаровен. $n, возьми сосуд, в котором он хранит угли Скверны, достань один уголь и принеси мне.','Принесите уголь Скверны волхву Забраксис из Оплота Чести.','Отлично, отлично! В мои планы не входит повторять подвиги чернокнижника Пустоклята, но надо быть полным дураком, чтобы не замечать силы угля Скверны.$B$BПравда, исследования вроде моего хотят запретить, так что всё нужно держать в секрете. $N, ты ведь никому не расскажешь?','Ты $Gпринёс:принесла;, эээ, уголь?','Вернитесь к волхву Забраксис на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угли Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши твердолобые азеротские академики слишком засиделись в своих башнях. Пришло время показать им, что такое настоящие исследования! Дескать, они боятся играть с огнем. Ничего, как только у меня окажется огонь, я вдоволь с ним поиграю!$B$BВ Разрушенных залах Цитадели Адского Пламени главный чернокнижник Пустоклят достиг невероятного магического мастерства, используя силу двух странных жаровен. $n, возьми сосуд, в котором он хранит угли Скверны, достань один уголь и принеси мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите уголь Скверны волхву Забраксис из Оплота Чести.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, отлично! В мои планы не входит повторять подвиги чернокнижника Пустоклята, но надо быть полным дураком, чтобы не замечать силы угля Скверны.$B$BПравда, исследования вроде моего хотят запретить, так что всё нужно держать в секрете. $N, ты ведь никому не расскажешь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринёс:принесла;, эээ, уголь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волхву Забраксис на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9495,'Мы должны запомнить Каргата таким, каким он был раньше, и извлечь для себя уроки из его падения. $B$BЗа службу Орде, $N, ты можешь выбрать одно из числа этого оружия.','У тебя есть доказательства поражения Каргата Острорука?','Вернитесь к Назгрелу в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы должны запомнить Каргата таким, каким он был раньше, и извлечь для себя уроки из его падения. $B$BЗа службу Орде, $N, ты можешь выбрать одно из числа этого оружия.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть доказательства поражения Каргата Острорука?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Назгрелу в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9496,'Отличная работа, $N. Когда легионеры разбиты, будет легче противостоять Орде Скверны на поле битвы, хотя они остаются грозными противниками.','Как только легионеры клана Изувеченной Длани будут разбиты, мы сможем начать нашу кампанию против Орды Скверны. Ты $Gвыполнил:выполнила; задание, $N?','Вернитесь к темному охотнику Туджину в Каньон Каменной Стены, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Когда легионеры разбиты, будет легче противостоять Орде Скверны на поле битвы, хотя они остаются грозными противниками.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как только легионеры клана Изувеченной Длани будут разбиты, мы сможем начать нашу кампанию против Орды Скверны. Ты $Gвыполнил:выполнила; задание, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному охотнику Туджину в Каньон Каменной Стены, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9497,'Знамя Орды Скверны','Когда весть о так называемой Орде Скверны достигла Вождя, он испытал не только сильную ярость, но и глубокую скорбь. Ничего, не долго осталось торжествовать этой фальшивой орде, мы расправимся с ней так же, как и с задаваками Ренда. А ее трофейное знамя украсит крепость Громмаш, во славу истинного Вождя.$B$BЭту волю Вождя выпало исполнить тебе, $n. Задание непростое, знамя Орды Скверны охраняет один из ее лучших воинов, О\'мрогг Завоеватель, и он не отступит без яростного боя.','Убейте О\'мрогга Завоевателя и захватите ордынское знамя Скверны. После этого возвращайтесь к властителю Хану Изуверу в Траллмар.','Вернитесь к властителю Хану Изуверу в Гибель Сквернобота, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знамя Орды Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда весть о так называемой Орде Скверны достигла Вождя, он испытал не только сильную ярость, но и глубокую скорбь. Ничего, не долго осталось торжествовать этой фальшивой орде, мы расправимся с ней так же, как и с задаваками Ренда. А ее трофейное знамя украсит крепость Громмаш, во славу истинного Вождя.$B$BЭту волю Вождя выпало исполнить тебе, $n. Задание непростое, знамя Орды Скверны охраняет один из ее лучших воинов, О\'мрогг Завоеватель, и он не отступит без яростного боя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте О\'мрогга Завоевателя и захватите ордынское знамя Скверны. После этого возвращайтесь к властителю Хану Изуверу в Траллмар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Хану Изуверу в Гибель Сквернобота, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9498,'Соколиный Дозор') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Соколиный Дозор',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9499,'Соколиный Дозор','Добро пожаловать в Соколиный Дозор, $Gбрат:сестра;. Не всем эльфам крови посчастливилось так далеко забраться. $B$BЧто ж, очень жаль. Впрочем, наша работа в Запределье только начинается.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Соколиный Дозор',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Соколиный Дозор, $Gбрат:сестра;. Не всем эльфам крови посчастливилось так далеко забраться. $B$BЧто ж, очень жаль. Впрочем, наша работа в Запределье только начинается.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9500,'Зов Воды','Я чувствую, много времени прошло с тех пор, когда тебе довелось пройти последнее испытание... О тебе спрашивал предсказатель Нобундо. Должно быть, твоя мудрость возросла – ибо ныне тебя призывают, дабы открыть тебе тайны стихии Воды.$B$BПолагаю, тебе не нужно напоминать, где в Кристальном зале Экзодара ты сможешь найти предсказателя. Я права?','Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним.','Мы встретились снова. Я издали наблюдал за твоими успехами, $C, и я доволен.$B$BПришло время тебе пообщаться с водной стихией, узнать ее тайны и отдаться воде, чтобы ты, в свою очередь, $Gнаучился:научилась; управлять ею.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я чувствую, много времени прошло с тех пор, когда тебе довелось пройти последнее испытание... О тебе спрашивал предсказатель Нобундо. Должно быть, твоя мудрость возросла – ибо ныне тебя призывают, дабы открыть тебе тайны стихии Воды.$B$BПолагаю, тебе не нужно напоминать, где в Кристальном зале Экзодара ты сможешь найти предсказателя. Я права?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы встретились снова. Я издали наблюдал за твоими успехами, $C, и я доволен.$B$BПришло время тебе пообщаться с водной стихией, узнать ее тайны и отдаться воде, чтобы ты, в свою очередь, $Gнаучился:научилась; управлять ею.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9501,'Зов Воды','Водяница, могущественный элементаль воды, пожелала встретиться с вами. Судя по всему, со стихией воды на острове Кровавой Дымки происходит что-то неладное. Ничего удивительного, впрочем – если принимать во внимание, насколько странно эльфы крови относятся ко всему, что их окружает.$B$BУ северного берега острова Кровавой Дымки есть Подводный риф, вы найдете Водяницу там.$B$BВозьмите это зелье – когда вы войдете в воду возле рифа, оно поможет вам попасть к Водянице.','Найдите Водяницу у Подводного рифа возле острова Кровавой Дымки и поговорите с ней.','Не бойся, $N. Пока вы здесь, мы будем говорить мысленно. $B$BЯ благодарен Провидцу Нобундо за то, что он прислал тебя ко мне. Воды на острове Кровавой Дымки и вокруг него загрязняют большие волнения. Даже слепой не сможет не заметить этот эффект, который оказывает на всех существ и окружающую среду. $B$BТы и я будем работать вместе, чтобы остановить это разложение, прежде чем оно распространится дальше.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Водяница, могущественный элементаль воды, пожелала встретиться с вами. Судя по всему, со стихией воды на острове Кровавой Дымки происходит что-то неладное. Ничего удивительного, впрочем – если принимать во внимание, насколько странно эльфы крови относятся ко всему, что их окружает.$B$BУ северного берега острова Кровавой Дымки есть Подводный риф, вы найдете Водяницу там.$B$BВозьмите это зелье – когда вы войдете в воду возле рифа, оно поможет вам попасть к Водянице.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Водяницу у Подводного рифа возле острова Кровавой Дымки и поговорите с ней.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не бойся, $N. Пока вы здесь, мы будем говорить мысленно. $B$BЯ благодарен Провидцу Нобундо за то, что он прислал тебя ко мне. Воды на острове Кровавой Дымки и вокруг него загрязняют большие волнения. Даже слепой не сможет не заметить этот эффект, который оказывает на всех существ и окружающую среду. $B$BТы и я будем работать вместе, чтобы остановить это разложение, прежде чем оно распространится дальше.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9502,'Зов Воды','Я чувствую, много времени прошло с тех пор, как тебе довелось пройти последнее испытание... О тебе спрашивал предсказатель Нобундо. Должно быть, твоя мудрость возросла – ибо ныне тебя призывают, дабы открыть тебе тайны стихии Воды.$B$BПолагаю, тебе не нужно напоминать, где в Кристальном зале Экзодара ты сможешь найти предсказателя. Я права?','Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним.','Мы встретились снова. Я издали наблюдал за твоими успехами, $C, и я доволен.$B$BПришло время тебе пообщаться с водной стихией, узнать ее тайны и отдаться воде, чтобы ты, в свою очередь, $Gнаучился:научилась; управлять ею.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я чувствую, много времени прошло с тех пор, как тебе довелось пройти последнее испытание... О тебе спрашивал предсказатель Нобундо. Должно быть, твоя мудрость возросла – ибо ныне тебя призывают, дабы открыть тебе тайны стихии Воды.$B$BПолагаю, тебе не нужно напоминать, где в Кристальном зале Экзодара ты сможешь найти предсказателя. Я права?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы встретились снова. Я издали наблюдал за твоими успехами, $C, и я доволен.$B$BПришло время тебе пообщаться с водной стихией, узнать ее тайны и отдаться воде, чтобы ты, в свою очередь, $Gнаучился:научилась; управлять ею.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9503,'Зов Воды','Вода – источник жизни и залог существования всего сущего, благословение, заставляющее расцветать бесплодную землю и гасящее всепожирающий огонь... Однако отравленная вода способна нести погибель.$B$BМы должны понять, насколько велик ущерб, нанесенный источникам воды. К юго-западу отсюда находится Смрадный пруд. Тебе нужно отправиться туда и добыть смрадную эссенцию водяных духов, обитающих в пруду.','Принесите 6 бутылочек смрадной эссенции на остров Кровавой Дымки в храм Подводного рифаа и отдайте Водянице.','Спасибо, $C. Этого должно быть достаточно, чтобы я мог изучить это искажение. Тогда у нас будет лучшее представление о том, как действовать дальше.','Ты так быстро $Gсобрал:собрала; смрадную эссенцию моих несчастных сестер, $N?','Вернитесь к Водянице на Подводный риф, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вода – источник жизни и залог существования всего сущего, благословение, заставляющее расцветать бесплодную землю и гасящее всепожирающий огонь... Однако отравленная вода способна нести погибель.$B$BМы должны понять, насколько велик ущерб, нанесенный источникам воды. К юго-западу отсюда находится Смрадный пруд. Тебе нужно отправиться туда и добыть смрадную эссенцию водяных духов, обитающих в пруду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 бутылочек смрадной эссенции на остров Кровавой Дымки в храм Подводного рифаа и отдайте Водянице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $C. Этого должно быть достаточно, чтобы я мог изучить это искажение. Тогда у нас будет лучшее представление о том, как действовать дальше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты так быстро $Gсобрал:собрала; смрадную эссенцию моих несчастных сестер, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Водянице на Подводный риф, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9504,'Зов Воды','Дела обстоят хуже, чем я думала. Скверна может распространиться до самого океана и по всему Азероту вместе с океанскими течениями...$B$BЧтобы не дать этому случиться, нам нужен образец самой чистой воды, какую только можно достать. К юго-востоку отсюда, на нетронутой скверной части острова, находятся руины. Отправляйся туда и найди фонтан, который охраняют наги из племени Зловещей Чешуи.$B$BНаполни этот бурдюк водой из фонтана. Прошу тебя, $n, не медли!','Наполните пустой бурдюк, а затем вернитесь на остров Кровавой Дымки в храм Подводного рифа и отдайте бурдюк Водянице.','Вода в мелких объемах слаба, но соединив их вместе, это создаст непреодолимую силу. Она смывает землю и гасит огонь и легко выталкивает воздух. $B$BМы - та неудержимая сила, $N, а не те, что отравили остров Кровавой Дымки!','У тебя есть чистая вода из руин?','Вернитесь к Водянице на Подводный риф, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дела обстоят хуже, чем я думала. Скверна может распространиться до самого океана и по всему Азероту вместе с океанскими течениями...$B$BЧтобы не дать этому случиться, нам нужен образец самой чистой воды, какую только можно достать. К юго-востоку отсюда, на нетронутой скверной части острова, находятся руины. Отправляйся туда и найди фонтан, который охраняют наги из племени Зловещей Чешуи.$B$BНаполни этот бурдюк водой из фонтана. Прошу тебя, $n, не медли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните пустой бурдюк, а затем вернитесь на остров Кровавой Дымки в храм Подводного рифа и отдайте бурдюк Водянице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вода в мелких объемах слаба, но соединив их вместе, это создаст непреодолимую силу. Она смывает землю и гасит огонь и легко выталкивает воздух. $B$BМы - та неудержимая сила, $N, а не те, что отравили остров Кровавой Дымки!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть чистая вода из руин?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Водянице на Подводный риф, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9505,'Пророчество Велена','Пророк предвидел наступление этого дня. Он говорил, что на острове в новом мире мы найдем союзников.$B$B"Нам предстоит испытание. Они попросят нас искупить грехи наших отцов..."$B$BТогда мы не поняли значения его слов, но, видя это существо и его реакцию на наше появление, мы все яснее видим, о чем было пророчество. Даже здесь почувствовали падение дренеев.$B$BСтупай на юг. Именно там мы нашли это существо. Найди ее родичей и поведай им о нашем народе.','Отправляйтесь на юг и отыщите народ, о котором говорило раненое существо.','Ты говоришь, что найдена одна из наших? И что она ранена? Я немедленно пошлю в вашу деревню одного из своих воинов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пророчество Велена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пророк предвидел наступление этого дня. Он говорил, что на острове в новом мире мы найдем союзников.$B$B"Нам предстоит испытание. Они попросят нас искупить грехи наших отцов..."$B$BТогда мы не поняли значения его слов, но, видя это существо и его реакцию на наше появление, мы все яснее видим, о чем было пророчество. Даже здесь почувствовали падение дренеев.$B$BСтупай на юг. Именно там мы нашли это существо. Найди ее родичей и поведай им о нашем народе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на юг и отыщите народ, о котором говорило раненое существо.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты говоришь, что найдена одна из наших? И что она ранена? Я немедленно пошлю в вашу деревню одного из своих воинов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9506,'Начало положено','Я – адмирал Одиссий из командования ВМС Альянса. Наш корабль был вынужден причалить к острову из-за своего рода нашествия. Мне даже неловко говорить об этом, но в трюмах обоих кораблей ухитрились спрятаться гоблины.$B$BПрошлой ночью, когда большая часть команды спала, они нанесли удар!$B$BЕще удивительнее то, что они украли наши навигационные приборы и спрыгнули с корабля!$B$BВоры скрылись в чаще к востоку отсюда. Не поищешь ли ты наше оборудование? Ты $gоказал:оказала; бы нам большую услугу.','Вернитесь к адмиралу Одиссию в Лагерь Одиссия, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Начало положено',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я – адмирал Одиссий из командования ВМС Альянса. Наш корабль был вынужден причалить к острову из-за своего рода нашествия. Мне даже неловко говорить об этом, но в трюмах обоих кораблей ухитрились спрятаться гоблины.$B$BПрошлой ночью, когда большая часть команды спала, они нанесли удар!$B$BЕще удивительнее то, что они украли наши навигационные приборы и спрыгнули с корабля!$B$BВоры скрылись в чаще к востоку отсюда. Не поищешь ли ты наше оборудование? Ты $gоказал:оказала; бы нам большую услугу.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Одиссию в Лагерь Одиссия, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9507,'<DEPRECATED>Со стола Могула Раздунка','Согласно этим планам, гоблины явились сюда за обломками кристаллов Экзодара. Похоже, гоблины должны добыть на острове все обломки кристаллов и похитить два корабля Альянса, бросивших якоря неподалеку от берега.$B$BВозможно, стоит отнести эти планы адмиралу Одиссию.','Отнесите совершенно секретные планы Торговой Компании адмиралу Одиссию в Лагерь Одиссия.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<DEPRECATED>Со стола Могула Раздунка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Согласно этим планам, гоблины явились сюда за обломками кристаллов Экзодара. Похоже, гоблины должны добыть на острове все обломки кристаллов и похитить два корабля Альянса, бросивших якоря неподалеку от берега.$B$BВозможно, стоит отнести эти планы адмиралу Одиссию.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите совершенно секретные планы Торговой Компании адмиралу Одиссию в Лагерь Одиссия.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9508,'Зов Воды','Мне удалось определить, что является источником порчи. Это побочный продукт неких безумных опытов, которым нужно положить конец. И займешься этим ты!$B$BК юго-западу от Смрадного пруда находится небольшой лагерь. Там проводит свои "исследования" Телатион Нечистый – и именно оттуда распространяется мерзость, отравляющая воды острова.$B$BИспользуй чистую воду из Ясеневого леса, чтобы уничтожить бочки в его тайном хранилище. Не сомневаюсь, это выманит Телатиона из его логова.$B$BМы положим конец этой мерзости!','Принесите голову Телатиона на остров Кровавой Дымки в храм Подводного рифа и отдайте Водянице.','Готово! Кризис предотвращен, и ты $Gприступил:приступила; к восстановлению воды на острове Кровавой Дымки. Со временем вода вместе с другими элементами исцелит сама себя. $B$BОчень жаль, что эльфы крови не видят, что, загрязняя свое окружение, они убивают себя!','У тебя получилось?','Вернитесь к Водянице на Подводный риф, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне удалось определить, что является источником порчи. Это побочный продукт неких безумных опытов, которым нужно положить конец. И займешься этим ты!$B$BК юго-западу от Смрадного пруда находится небольшой лагерь. Там проводит свои "исследования" Телатион Нечистый – и именно оттуда распространяется мерзость, отравляющая воды острова.$B$BИспользуй чистую воду из Ясеневого леса, чтобы уничтожить бочки в его тайном хранилище. Не сомневаюсь, это выманит Телатиона из его логова.$B$BМы положим конец этой мерзости!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Телатиона на остров Кровавой Дымки в храм Подводного рифа и отдайте Водянице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Готово! Кризис предотвращен, и ты $Gприступил:приступила; к восстановлению воды на острове Кровавой Дымки. Со временем вода вместе с другими элементами исцелит сама себя. $B$BОчень жаль, что эльфы крови не видят, что, загрязняя свое окружение, они убивают себя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя получилось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Водянице на Подводный риф, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9509,'Зов Воды','Я сохранила немного воды из Ясеневого леса; не потому, что не верила, что ты справишься с ситуацией, нет, я даже скорее была уверена в успехе... Мне просто показалось – будет неплохо, если ты сможешь принести Нобундо что-нибудь особенное.$B$BВот, держи, $n, полный флакон чистейшей воды. В обмен на него ты получишь могущественный водяной тотем.$B$BПредсказатель Нобундо ждет твоего возвращения в Экзодаре.','Отнесите флакон чистейшей воды предсказателю Нобундо. Его можно найти на острове Лазурной Дымки в Экзодаре.','Ты $Gпоступил:поступила; не по годам мудро, $N. Я чувствую, что водная стихия довольна твоими действиями. Для меня будет большой честью взять чистую воду, которую ты несешь, и объединить ее сущность в твой новый водный тотем. $B$BКогда ты пойдешь дальше, хорошо запомни уроки воды, и ты обретешь еще большее понимание этой стихии.','Мне рассказали о великих делах, которые ты $Gсовершил:совершила;. Давай поговорим.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сохранила немного воды из Ясеневого леса; не потому, что не верила, что ты справишься с ситуацией, нет, я даже скорее была уверена в успехе... Мне просто показалось – будет неплохо, если ты сможешь принести Нобундо что-нибудь особенное.$B$BВот, держи, $n, полный флакон чистейшей воды. В обмен на него ты получишь могущественный водяной тотем.$B$BПредсказатель Нобундо ждет твоего возвращения в Экзодаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите флакон чистейшей воды предсказателю Нобундо. Его можно найти на острове Лазурной Дымки в Экзодаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпоступил:поступила; не по годам мудро, $N. Я чувствую, что водная стихия довольна твоими действиями. Для меня будет большой честью взять чистую воду, которую ты несешь, и объединить ее сущность в твой новый водный тотем. $B$BКогда ты пойдешь дальше, хорошо запомни уроки воды, и ты обретешь еще большее понимание этой стихии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне рассказали о великих делах, которые ты $Gсовершил:совершила;. Давай поговорим.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9511,'Боевые планы Каргата','<TXT>В документах, обнаруженных на теле Каргата, подробно излагается план вторжения в Оплот Чести.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боевые планы Каргата',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<TXT>В документах, обнаруженных на теле Каргата, подробно излагается план вторжения в Оплот Чести.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9512,'Крабовый супчик поваренка','Адмирал прав, в тебе и впрямь кладезь талантов. Не поможешь Поваренку?$B$BЕсли я снова подам на обед курицу, команда меня утопит.$B$BЯ смотрю, вдоль берега бродят крабы – и сколько! Притащи мне крабьего мяска, и можешь считать – я твой должник.$B$BВыручишь бывшего пирата?','Принесите 6 кусков мяса шустрых крабов "Поваренку" Максоусу в Лагерь Одиссия.','Вернитесь к "Поваренку" Максоусу в Лагерь Одиссия, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крабовый супчик поваренка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Адмирал прав, в тебе и впрямь кладезь талантов. Не поможешь Поваренку?$B$BЕсли я снова подам на обед курицу, команда меня утопит.$B$BЯ смотрю, вдоль берега бродят крабы – и сколько! Притащи мне крабьего мяска, и можешь считать – я твой должник.$B$BВыручишь бывшего пирата?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 кусков мяса шустрых крабов "Поваренку" Максоусу в Лагерь Одиссия.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к "Поваренку" Максоусу в Лагерь Одиссия, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9513,'Возвращение руин','Хотя многие считают наше затруднительное положение следствием несчастливой случайности, я чувствую, что мы недаром оказались здесь. Невидимая рука судьбы подтолкнула нас к этой земле. Для чего – со временем станет ясно.$B$BК западу отсюда находится древний эльфийский город, лежащий в руинах и заселенный нагами. Мне не хотелось бы сидеть сложа руки, пока наги оскверняют земли предков.$B$BТы $gнаделен:наделена; неплохими способностями, |3-6($c). Почти мой народ и очисти руины от нежеланных обитателей.','Хвала Элуне! Неприкаянные души теперь могут обрести покой.','Вернитесь к жрице Кайлин Ил\'динар в Лагерь Одиссия, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение руин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя многие считают наше затруднительное положение следствием несчастливой случайности, я чувствую, что мы недаром оказались здесь. Невидимая рука судьбы подтолкнула нас к этой земле. Для чего – со временем станет ясно.$B$BК западу отсюда находится древний эльфийский город, лежащий в руинах и заселенный нагами. Мне не хотелось бы сидеть сложа руки, пока наги оскверняют земли предков.$B$BТы $gнаделен:наделена; неплохими способностями, |3-6($c). Почти мой народ и очисти руины от нежеланных обитателей.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала Элуне! Неприкаянные души теперь могут обрести покой.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Кайлин Ил\'динар в Лагерь Одиссия, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (9514,'Покрытая рунами табличка','Вы не можете разобрать ни одного из символов на табличке. Быть может, прочесть таинственные руны сумела бы жрица?','Нет, я не могу прочесть эти руны, но я знаю, кто может...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покрытая рунами табличка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы не можете разобрать ни одного из символов на табличке. Быть может, прочесть таинственные руны сумела бы жрица?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет, я не могу прочесть эти руны, но я знаю, кто может...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9515,'Полководец Шрисс\'тиз','Вторжение наг может плохо для нас закончиться, $n. Мне приходилось видеть, на что они способны, и такого я ни одному живому существу не пожелала бы. Подозреваю, что их полководец Шрисс\'тиз прячется в пещере – скорее всего в западной части побережья.$B$BОтыщи полководца Шрисс\'тиза и положи конец его правлению.','Жрица Кайлин Ил\'динар из лагеря Одиссия попросила вас убить полководца Шрисс\'тиза.','Полководец Шрисс\'тиз мертв, и наги не скоро оправятся от этого удара. Теперь мы в безопасности... на время.$B$BДолжна признать, что я напрасно относилась к тебе с подозрением. Ты не имеешь ничего общего с мерзавцем Архимондом. Прими этот дар от ночных эльфов.','Не теряй бдительности!','Вернитесь к жрице Кайлин Ил\'динар в Лагерь Одиссия, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полководец Шрисс\'тиз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вторжение наг может плохо для нас закончиться, $n. Мне приходилось видеть, на что они способны, и такого я ни одному живому существу не пожелала бы. Подозреваю, что их полководец Шрисс\'тиз прячется в пещере – скорее всего в западной части побережья.$B$BОтыщи полководца Шрисс\'тиза и положи конец его правлению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Жрица Кайлин Ил\'динар из лагеря Одиссия попросила вас убить полководца Шрисс\'тиза.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Полководец Шрисс\'тиз мертв, и наги не скоро оправятся от этого удара. Теперь мы в безопасности... на время.$B$BДолжна признать, что я напрасно относилась к тебе с подозрением. Ты не имеешь ничего общего с мерзавцем Архимондом. Прими этот дар от ночных эльфов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не теряй бдительности!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к жрице Кайлин Ил\'динар в Лагерь Одиссия, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9516,'Уничтожить Легион!','Я не потерплю их присутствия в нашем мире! Пылающий Легион чуть не уничтожил нашу расу, и мы бежали сюда, чтобы построить себе новый дом в новом мире. Теперь они снова пришли. И мы снова отступили, и снова, и снова!$B$BДовольно! $B$BОстатки Легиона затаились к югу и к западу от холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона. Это все, что осталось от полчищ, что некогда вторглись в этот мир.$B$BСтупай же и перебей сколько сможешь, пока еще не поздно!','Убейте 15 демонов на холме Демонического Огня, в каньоне Гибели Демона и гряде Гибели Демона.','Примите мое почтение и благодарность, $C. Может быть, нам все же удастся построить здесь новый дом, не страшась больше Пылающего Легиона.','Демоны еще стоят?','[Deprecated] Return to Vindicator Vedaar at the Warsong Lumber Camp in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить Легион!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не потерплю их присутствия в нашем мире! Пылающий Легион чуть не уничтожил нашу расу, и мы бежали сюда, чтобы построить себе новый дом в новом мире. Теперь они снова пришли. И мы снова отступили, и снова, и снова!$B$BДовольно! $B$BОстатки Легиона затаились к югу и к западу от холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона. Это все, что осталось от полчищ, что некогда вторглись в этот мир.$B$BСтупай же и перебей сколько сможешь, пока еще не поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 демонов на холме Демонического Огня, в каньоне Гибели Демона и гряде Гибели Демона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Примите мое почтение и благодарность, $C. Может быть, нам все же удастся построить здесь новый дом, не страшась больше Пылающего Легиона.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Демоны еще стоят?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Vindicator Vedaar at the Warsong Lumber Camp in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9517,'Напрасные усилия','Добро пожаловать в Лесную Песнь, |3-6($c). Там, где ныне стоят палатки, однажды вырастут дома, но для этого необходимы постоянные поставки строительных материалов. Я не посмею просить никого из наших рабочих рубить древние деревья этой рощи, но наши соседи на западе не столь трепетно относятся к лесу.$B$BМы заберем немного оскверненного дерева из цитадели сатиров на западе. Доставь древесину Кривокрону на Лесозаготовки Песни Войны. Он один из Древних, и может очистить ее от порчи.','Добудьте 5 связок оскверненной древесины Сатирнаара.','Дерево, поваленное орочьими грубыми клинками, изуродовано так, словно его ураганом повалило. Из него ничего путного не построишь, но я очищу его от порчи и верну архитектору Немосу и его работникам. Хоть какое-то добро выйдет из этого лиха, в конце концов.','Древний со скрипом поворачивается к вам. $B$BАрхитектор Немос сказал, что ты можешь доставить древесину, спасенную из лагеря лесогубов и мерзостного Сатирнаара?','[Deprecated] Speak with Gnarl at the Warsong Lumber Camp in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Напрасные усилия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в Лесную Песнь, |3-6($c). Там, где ныне стоят палатки, однажды вырастут дома, но для этого необходимы постоянные поставки строительных материалов. Я не посмею просить никого из наших рабочих рубить древние деревья этой рощи, но наши соседи на западе не столь трепетно относятся к лесу.$B$BМы заберем немного оскверненного дерева из цитадели сатиров на западе. Доставь древесину Кривокрону на Лесозаготовки Песни Войны. Он один из Древних, и может очистить ее от порчи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 связок оскверненной древесины Сатирнаара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дерево, поваленное орочьими грубыми клинками, изуродовано так, словно его ураганом повалило. Из него ничего путного не построишь, но я очищу его от порчи и верну архитектору Немосу и его работникам. Хоть какое-то добро выйдет из этого лиха, в конце концов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Древний со скрипом поворачивается к вам. $B$BАрхитектор Немос сказал, что ты можешь доставить древесину, спасенную из лагеря лесогубов и мерзостного Сатирнаара?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Speak with Gnarl at the Warsong Lumber Camp in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9518,'Пособники разрушения','Лесозаготовки Песни Войны – нарыв на теле нашей истерзанной земли. Каждый раз, как нам удается пресечь их работу, надзиратель Гортак приказывает своим лесорубам удвоить усилия!$B$BТеперь орки валят столько леса, что даже использовать весь не могут, рубят живые стволы, когда у них бревна гниют за ненадобностью! Это плевок нам в душу, $n, и мы покажем им, что не потерпим дальнейшего разорения наших земель!$B$BСтупай и не ведай покоя, пока этот надзиратель Гортак и его пособники не будут мертвы!','Убейте надзирателя Гортака и 12 других сторонников Орды на лесозаготовках Песни Войны.','Наконец-то мы преподали оркам урок, который они не осмелятся проигнорировать. Любой мастер или старшина, который сунется на лесозаготовки и заменит Гортака, на собственной шкуре испытает мой гнев!$B$BМы должны развить успех, $n, и не останавливаться, пока от лесозаготовок Песни Войны не останутся лишь смутные воспоминания, а на их месте не поднимется роща.','Пока жив Смотритель Гортак, я буду противостоять ему. Какие новости из лагеря пиломатериалов?','[Deprecated] Return to Sentinel Luciel Starwhisper at the Warsong Lumber Camp in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пособники разрушения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лесозаготовки Песни Войны – нарыв на теле нашей истерзанной земли. Каждый раз, как нам удается пресечь их работу, надзиратель Гортак приказывает своим лесорубам удвоить усилия!$B$BТеперь орки валят столько леса, что даже использовать весь не могут, рубят живые стволы, когда у них бревна гниют за ненадобностью! Это плевок нам в душу, $n, и мы покажем им, что не потерпим дальнейшего разорения наших земель!$B$BСтупай и не ведай покоя, пока этот надзиратель Гортак и его пособники не будут мертвы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте надзирателя Гортака и 12 других сторонников Орды на лесозаготовках Песни Войны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то мы преподали оркам урок, который они не осмелятся проигнорировать. Любой мастер или старшина, который сунется на лесозаготовки и заменит Гортака, на собственной шкуре испытает мой гнев!$B$BМы должны развить успех, $n, и не останавливаться, пока от лесозаготовок Песни Войны не останутся лишь смутные воспоминания, а на их месте не поднимется роща.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пока жив Смотритель Гортак, я буду противостоять ему. Какие новости из лагеря пиломатериалов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Sentinel Luciel Starwhisper at the Warsong Lumber Camp in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9519,'Потерянная чаша','В области к западу отсюда, что нынче зовется Сатирнаар, некогда было прославленное святилище, которое возвел мой народ. В нем хранилась бесценная реликвия, чаша Элуны, доверенная хранителям святилища жрецами Элуны. Некогда к святилищу стекались паломники, дабы испытать целительную силу чаши, которой она, как говорят, обладала.$B$BМожет, это просто байки, но если в них есть доля правды, то эта святыня может стать ключом к возрождению нашего истерзанного леса. Мне надо точно это выяснить, $n.','Добудьте чашу Элуны.','Вернитесь к Кайнету Штилю в Лесную Песнь, что в Ясеневом лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянная чаша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В области к западу отсюда, что нынче зовется Сатирнаар, некогда было прославленное святилище, которое возвел мой народ. В нем хранилась бесценная реликвия, чаша Элуны, доверенная хранителям святилища жрецами Элуны. Некогда к святилищу стекались паломники, дабы испытать целительную силу чаши, которой она, как говорят, обладала.$B$BМожет, это просто байки, но если в них есть доля правды, то эта святыня может стать ключом к возрождению нашего истерзанного леса. Мне надо точно это выяснить, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте чашу Элуны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайнету Штилю в Лесную Песнь, что в Ясеневом лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9520,'Демонические планы','Этот пергамент выронил демон, но что странно – он написан на Всеобщем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя Ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.$B$BВ плане подробно описывается подготовка нападения демонов на Лесную Песнь на севере отсюда – место, где основали свое поселение дренеи.$B$BВозможно, это заинтересует воздаятеля Ведаара с лесозаготовок Песни Войны?','Доставьте демонические планы воздаятелю Ведаару на лесозаготовки Песни Войны в Ясеневый лес.','Клянусь Семью Кристаллами Ата\'мала, этого не может быть! Они хотят напасть на нас здесь, в Лесной Песне?!$B$BНе будет этого, доколе я жив!$B$B<Воздаятель Ведаар сминает в кулаке пергамент с демоническими планами.>$B$BНет. Мы этого не допустим!','Что тут у вас, сударь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонические планы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот пергамент выронил демон, но что странно – он написан на Всеобщем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя Ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.$B$BВ плане подробно описывается подготовка нападения демонов на Лесную Песнь на севере отсюда – место, где основали свое поселение дренеи.$B$BВозможно, это заинтересует воздаятеля Ведаара с лесозаготовок Песни Войны?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте демонические планы воздаятелю Ведаару на лесозаготовки Песни Войны в Ясеневый лес.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клянусь Семью Кристаллами Ата\'мала, этого не может быть! Они хотят напасть на нас здесь, в Лесной Песне?!$B$BНе будет этого, доколе я жив!$B$B<Воздаятель Ведаар сминает в кулаке пергамент с демоническими планами.>$B$BНет. Мы этого не допустим!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тут у вас, сударь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9521,'Донесение с северного фронта','Борьбу с Ордой ведет не только Башня в Ночных лесах, $n. К юго-востоку, на границе со Степями, в роще Среброкрылых, находятся Часовые Среброкрылых. Часовой Дальняя Песня из этой рощи направляет наши действия против тех, кто готов разорить наши земли.$B$BЯ немного припозднилась с отправлением моего последнего донесения часовому Дальней Песне, но боюсь оставить башню без охраны.$B$BМне крайне необходима твоя помощь в доставке этого отчета!','Доставьте донесение часового Мелирии часовому Дальней Песне в рощу Среброкрылых, что в Ясеневом лесу.','Благодарю за доставку этого донесения, $C. Из того, что пишет часовой Люсьель, видно, что оправдываются наши худшие опасения. С каждым нашим очередным успехом Орда все решительнее пытается нанести нам как можно больше урона.$B$BМы не можем позволить себе отступить. Судьба земель наших предков стоит на кону. Но если на границе будет больше таких, как ты, мы точно победим. Будешь ли ты биться вместе с нами?','Что у тебя такое, $C?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение с северного фронта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Борьбу с Ордой ведет не только Башня в Ночных лесах, $n. К юго-востоку, на границе со Степями, в роще Среброкрылых, находятся Часовые Среброкрылых. Часовой Дальняя Песня из этой рощи направляет наши действия против тех, кто готов разорить наши земли.$B$BЯ немного припозднилась с отправлением моего последнего донесения часовому Дальней Песне, но боюсь оставить башню без охраны.$B$BМне крайне необходима твоя помощь в доставке этого отчета!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте донесение часового Мелирии часовому Дальней Песне в рощу Среброкрылых, что в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю за доставку этого донесения, $C. Из того, что пишет часовой Люсьель, видно, что оправдываются наши худшие опасения. С каждым нашим очередным успехом Орда все решительнее пытается нанести нам как можно больше урона.$B$BМы не можем позволить себе отступить. Судьба земель наших предков стоит на кону. Но если на границе будет больше таких, как ты, мы точно победим. Будешь ли ты биться вместе с нами?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что у тебя такое, $C?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9522,'Больше никогда!','$n, на твои плечи ложится обязанность сорвать нападение Пылающего Легиона! Ты $Gдолжен:должна; уничтожить их предводителей. Остальные демоны, по большей части – безмозглые твари. $B$BГорганнона ты найдешь в Каньоне Гибели демона к югу за Холмом Демонического Огня, близ сломанного, парящего копья Маннорота.$B$BДиатор Ищейка засел где-то в логове в холме над Грядой Гибели Демона. Чтобы найти эту гряду, отыщи уступ, по которому можно подняться из Каньона Гибели демона близ памятника Грому Адскому Крику.$B$BПринеси мне их оружие.','Добудьте пламенеющее лезвие Горганнона и желчное копье Ищейки.','Никогда более Пылающий Легион не потревожит нас в этих местах! Вы избавили нас от битвы, которую мы наверняка проиграли бы, $C.$B$BЯ приношу вам благодарность и глубочайшее уважение от лица Длани Аргуса. Для меня большая честь, что вы сражаетесь на нашей стороне.','Наши разведчики ночных эльфов сообщают, что подготовка к атаке, возможно, еще продолжается. Эти повелители ужаса должны умереть, $N!','[Deprecated] Return to Vindicator Vedaar at the Warsong Lumber Camp in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше никогда!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, на твои плечи ложится обязанность сорвать нападение Пылающего Легиона! Ты $Gдолжен:должна; уничтожить их предводителей. Остальные демоны, по большей части – безмозглые твари. $B$BГорганнона ты найдешь в Каньоне Гибели демона к югу за Холмом Демонического Огня, близ сломанного, парящего копья Маннорота.$B$BДиатор Ищейка засел где-то в логове в холме над Грядой Гибели Демона. Чтобы найти эту гряду, отыщи уступ, по которому можно подняться из Каньона Гибели демона близ памятника Грому Адскому Крику.$B$BПринеси мне их оружие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте пламенеющее лезвие Горганнона и желчное копье Ищейки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Никогда более Пылающий Легион не потревожит нас в этих местах! Вы избавили нас от битвы, которую мы наверняка проиграли бы, $C.$B$BЯ приношу вам благодарность и глубочайшее уважение от лица Длани Аргуса. Для меня большая честь, что вы сражаетесь на нашей стороне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Наши разведчики ночных эльфов сообщают, что подготовка к атаке, возможно, еще продолжается. Эти повелители ужаса должны умереть, $N!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Vindicator Vedaar at the Warsong Lumber Camp in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9523,'Хрупкие предметы. Не кантовать!','Жрица говорит, что руины на западе отсюда – это разрушенный город ночных эльфов. Я сразу вспомнил, что говорил мой папаша про такого рода развалины: "Сынок, если тебе попадутся эльфийские развалины, знай, что там полно эльфийских реликвий."$B$BЧто я за дворф, если не найму первого встречного, чтобы добыть эльфийские реликвии? Вперед!','Без реликвий можешь даже не возвращаться.','Вернитесь к археологу Адаманту Железному Сердцу в Лагерь Одиссия, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хрупкие предметы. Не кантовать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жрица говорит, что руины на западе отсюда – это разрушенный город ночных эльфов. Я сразу вспомнил, что говорил мой папаша про такого рода развалины: "Сынок, если тебе попадутся эльфийские развалины, знай, что там полно эльфийских реликвий."$B$BЧто я за дворф, если не найму первого встречного, чтобы добыть эльфийские реликвии? Вперед!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Без реликвий можешь даже не возвращаться.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к археологу Адаманту Железному Сердцу в Лагерь Одиссия, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9524,'Узник Цитадели','Альянс, здесь? Тогда слушай внимательно, |3-6($c).$B$BКаргату удалось захватить несколько наших солдат. Среди них капитан Алина, один из самых важных офицеров. Надо успеть спасти ее, пока ее не казнили.$B$BОбо мне не беспокойся, я смоюсь отсюда, как только переведу дыхание.','Спасите капитана Алину в Цитадели Адского Пламени до того, как ее казнят.$B$BЭто задание выполняется в режиме героической сложности.','Благодарю тебя, $N. Должен признаться, я не ожидал, что в пути будет спасательная группа. $B$BЯ соберу оставшихся заключенных и отведу их обратно в Оплот Чести','Вернитесь к капитану Алине на Возвышенность Гэвина, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Узник Цитадели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альянс, здесь? Тогда слушай внимательно, |3-6($c).$B$BКаргату удалось захватить несколько наших солдат. Среди них капитан Алина, один из самых важных офицеров. Надо успеть спасти ее, пока ее не казнили.$B$BОбо мне не беспокойся, я смоюсь отсюда, как только переведу дыхание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите капитана Алину в Цитадели Адского Пламени до того, как ее казнят.$B$BЭто задание выполняется в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, $N. Должен признаться, я не ожидал, что в пути будет спасательная группа. $B$BЯ соберу оставшихся заключенных и отведу их обратно в Оплот Чести',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Алине на Возвышенность Гэвина, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9525,'Узник Цитадели','Мне удалось сбежать из тюрьмы Каргата, $n. Сегодня должны казнить нескольких заключенных, и среди них одного очень важного офицера.$B$BЕсли мы потеряем капитана Костолома, это будет ощутимый удар для всей нашей армии. Ты $gдолжен:должна; сделать все, что в твоих силах, чтобы его спасти. Я бы отправился с тобой, но, к сожалению, я слишком слаб...','Спасите капитана Костолома в Цитадели Адского Пламени до того, как его казнят.$B$BЭто задание выполняется в режиме героической сложности.','Ты скрасил мне день, $C. Когда я умру, я позабочусь о том, чтобы он был на поле битвы... залит кровью моих противников и уничтожал их вместе со мной.','Вернитесь к капитану Костолому на Возвышенность Гэвина, что в Альтеракских горах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Узник Цитадели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне удалось сбежать из тюрьмы Каргата, $n. Сегодня должны казнить нескольких заключенных, и среди них одного очень важного офицера.$B$BЕсли мы потеряем капитана Костолома, это будет ощутимый удар для всей нашей армии. Ты $gдолжен:должна; сделать все, что в твоих силах, чтобы его спасти. Я бы отправился с тобой, но, к сожалению, я слишком слаб...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите капитана Костолома в Цитадели Адского Пламени до того, как его казнят.$B$BЭто задание выполняется в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты скрасил мне день, $C. Когда я умру, я позабочусь о том, чтобы он был на поле битвы... залит кровью моих противников и уничтожал их вместе со мной.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Костолому на Возвышенность Гэвина, что в Альтеракских горах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9526,'Возрождение Холма Демонического Огня','$GМалыш:Малышка;, к юго-западу отсюда находится место, что зовется лесами Ночной Песни. С недавнего времени его называют Холмом Демонического Огня. Прискорбно видеть, как по этой земле бродят демоны и разносят везде свою порчу.$B$BНе поможешь ли ты возродить эту землю?$B$BУ меня есть несколько саженцев, которые я приберег на этот случай. Отнеси их на Холм Демонического Огня и посади их в кучи плодородной земли.','Посадите 8 древесных саженцев в кучи плодородной земли.','Добро. Хотя много твоих годов утечет прежде, чем эти саженцы превратятся в Древних, но со временем они помогут нам в борьбе против демонов на Холме Демонического Огня.$B$BСтупай же с миром, младший брат.','Неужели ты еще не все мои семена $Gпосадил:посадила;?','[Deprecated] Return to Gnarl at the Warsong Lumber Camp in Ashenvale.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возрождение Холма Демонического Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GМалыш:Малышка;, к юго-западу отсюда находится место, что зовется лесами Ночной Песни. С недавнего времени его называют Холмом Демонического Огня. Прискорбно видеть, как по этой земле бродят демоны и разносят везде свою порчу.$B$BНе поможешь ли ты возродить эту землю?$B$BУ меня есть несколько саженцев, которые я приберег на этот случай. Отнеси их на Холм Демонического Огня и посади их в кучи плодородной земли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посадите 8 древесных саженцев в кучи плодородной земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро. Хотя много твоих годов утечет прежде, чем эти саженцы превратятся в Древних, но со временем они помогут нам в борьбе против демонов на Холме Демонического Огня.$B$BСтупай же с миром, младший брат.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели ты еще не все мои семена $Gпосадил:посадила;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Gnarl at the Warsong Lumber Camp in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9527,'Останки семьи','Долгие годы мы мирно жили на острове по соседству с совухами. Представь себе мое удивление, когда они наводнили наш берег и напали на нас!$B$BЯ сражался изо всех сил, но меня легко скрутили. Теряя сознание от жестоких ударов, я надеялся лишь на то, что моя семья не пострадает.$B$BКогда я пришел в себя, вокруг было тихо, но песок покраснел от крови. Их крови. Мою жену и дочь сожрали заживо.$B$BЯ не жажду мести, $n. Мне бы только похоронить как должно то, что от них осталось.','Верните Коулену останки его семьи.','Мою жену звали Талриса, а дочь – Магвин.','Вернитесь к Коулену на остров Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Останки семьи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Долгие годы мы мирно жили на острове по соседству с совухами. Представь себе мое удивление, когда они наводнили наш берег и напали на нас!$B$BЯ сражался изо всех сил, но меня легко скрутили. Теряя сознание от жестоких ударов, я надеялся лишь на то, что моя семья не пострадает.$B$BКогда я пришел в себя, вокруг было тихо, но песок покраснел от крови. Их крови. Мою жену и дочь сожрали заживо.$B$BЯ не жажду мести, $n. Мне бы только похоронить как должно то, что от них осталось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Коулену останки его семьи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мою жену звали Талриса, а дочь – Магвин.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Коулену на остров Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9529,'Камень','Я уверена, что твой бес оказался полезным и даже забавным слугой, однако пора тебе подчинить себе более могущественное существо – демона Бездны.$b$bСтупай по Тропе Мертвых до переправы через реку Элрендар. Перейдя через реку, отыщи на южном берегу светящийся голубой камень и возьми его. Тогда ты поймешь, что тебе делать дальше.','Добудьте камень Бездны с Тропы Мертвых.','Когда ты смотришь на камень, то что ты видишь начинает кружиться...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уверена, что твой бес оказался полезным и даже забавным слугой, однако пора тебе подчинить себе более могущественное существо – демона Бездны.$b$bСтупай по Тропе Мертвых до переправы через реку Элрендар. Перейдя через реку, отыщи на южном берегу светящийся голубой камень и возьми его. Тогда ты поймешь, что тебе делать дальше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте камень Бездны с Тропы Мертвых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда ты смотришь на камень, то что ты видишь начинает кружиться...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9530,'Созревший план','Я давно подозревал нечто подобное, но теперь исчезли последние сомнения.$B$BСреди нас есть предатель.$B$BГоблинские планы прямо указывают на существование заговора. Поскольку я не могу представить, кто из моих людей нас предал, мне понадобится твоя помощь. Теперь никому из команды нельзя доверять.$B$BДля осуществления плана мне понадобится выдолбленный ствол и листья. Их можно поискать неподалеку от стоянки лесорубов к северу от нас. Охапки листьев ты и $Gсам:сама; наберешь в лесу.','Обожаю, когда план начинает выполняться...','Вернитесь к адмиралу Одиссию в Лагерь Одиссия, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Созревший план',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я давно подозревал нечто подобное, но теперь исчезли последние сомнения.$B$BСреди нас есть предатель.$B$BГоблинские планы прямо указывают на существование заговора. Поскольку я не могу представить, кто из моих людей нас предал, мне понадобится твоя помощь. Теперь никому из команды нельзя доверять.$B$BДля осуществления плана мне понадобится выдолбленный ствол и листья. Их можно поискать неподалеку от стоянки лесорубов к северу от нас. Охапки листьев ты и $Gсам:сама; наберешь в лесу.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обожаю, когда план начинает выполняться...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Одиссию в Лагерь Одиссия, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9531,'У деревьев есть уши','Если верить планам, предатель должен встретиться с предводителем гоблинов Гизлом в бухте на западном острове. Проследи за ними, $n.$B$BПомнишь, я просил тебя набрать листьев и принести выдолбленный ствол? Их-то ты и наденешь! Прекрасная маскировка.$B$BОтправляйся в бухту и посмотри, выставлен ли нагский флаг. Если да, то встреча должна вот-вот состояться. Замаскируйся и жди. В конце концов предатель заявится на встречу. Дождись окончания встречи и сообщи мне, кто этот негодяй.','Проследите за встречей Гизла с предателем.$B$BВернитесь с докладом к адмиралу Одиссию.','Ушам своим не верю! Во всем виноват гном... и как я не догадался!','Предатель еще пожалеет, что связался с ВМС Альянса!','Вернитесь к адмиралу Одиссию в Лагерь Одиссия, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У деревьев есть уши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если верить планам, предатель должен встретиться с предводителем гоблинов Гизлом в бухте на западном острове. Проследи за ними, $n.$B$BПомнишь, я просил тебя набрать листьев и принести выдолбленный ствол? Их-то ты и наденешь! Прекрасная маскировка.$B$BОтправляйся в бухту и посмотри, выставлен ли нагский флаг. Если да, то встреча должна вот-вот состояться. Замаскируйся и жди. В конце концов предатель заявится на встречу. Дождись окончания встречи и сообщи мне, кто этот негодяй.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проследите за встречей Гизла с предателем.$B$BВернитесь с докладом к адмиралу Одиссию.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ушам своим не верю! Во всем виноват гном... и как я не догадался!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Предатель еще пожалеет, что связался с ВМС Альянса!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Одиссию в Лагерь Одиссия, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9532,'Найти Келтуса Темного Листа','$n, один из наших разведчиков чересчур увлекся своими обязанностями! Он неусыпно следит за нашими врагами, но при этом забывает присылать донесения о том, что ему удалось выяснить!$b$bНайди этого шпиона, Келтуса Темного Листа, убеди его сообщить, наконец, о том, что он узнал, и как можно быстрее возвращайся ко мне. Он далеко отсюда, на юго-западе, там, где река Элрендар расходится на два рукава и огибает Деревню Золотистой Дымки. Келтус выслеживает ночных эльфов из Ан\'дарота, так что, должно быть, он где-то там.','Найдите Келтуса Темного Листа.','Надеюсь, вы видите, что я под прикрытием... по крайней мере, был.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Келтуса Темного Листа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, один из наших разведчиков чересчур увлекся своими обязанностями! Он неусыпно следит за нашими врагами, но при этом забывает присылать донесения о том, что ему удалось выяснить!$b$bНайди этого шпиона, Келтуса Темного Листа, убеди его сообщить, наконец, о том, что он узнал, и как можно быстрее возвращайся ко мне. Он далеко отсюда, на юго-западе, там, где река Элрендар расходится на два рукава и огибает Деревню Золотистой Дымки. Келтус выслеживает ночных эльфов из Ан\'дарота, так что, должно быть, он где-то там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Келтуса Темного Листа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, вы видите, что я под прикрытием... по крайней мере, был.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9533,'Рука помощи','Мой народ принялся за важное дело в восточной части Ясеневого леса при поддержке и помощи калдорай.$B$BПод руководством архитектора Немоса и воздаятеля Ведаара они восстанавливают древний форт ночных эльфов. Это непростая задача, $n, ибо кругом много врагов. Я знаю, что архитектор Немос и его сторонники в Лесной Песни будут благодарны любой помощи, и он просил меня присылать к нему всякого, кого это заинтересует.$B$BЕсли хочешь отправиться туда, окликни меня еще раз, и я организую тебе транспорт.','Отправляйтесь в Лесную Песнь и поговорите с архитектором Немосом.$B$BОбратитесь к воздаятельнице Паланааре, если вам требуется транспорт.','Радостно видеть нового гостя в Лесной Песни.$B$BПоборница Паланаар присылает на помощь столько народу, сколько может, и мы рады каждой паре рук.$B$BПосмотрите вокруг, $C. Может, сейчас вид не слишком впечатляет, но пройдет время, и при помощи наших союзников ночных эльфов мы построим здесь поселение, которое будет достойно называться домом. Сделать предстоит очень много, и любую помощь мы примем с радостью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рука помощи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой народ принялся за важное дело в восточной части Ясеневого леса при поддержке и помощи калдорай.$B$BПод руководством архитектора Немоса и воздаятеля Ведаара они восстанавливают древний форт ночных эльфов. Это непростая задача, $n, ибо кругом много врагов. Я знаю, что архитектор Немос и его сторонники в Лесной Песни будут благодарны любой помощи, и он просил меня присылать к нему всякого, кого это заинтересует.$B$BЕсли хочешь отправиться туда, окликни меня еще раз, и я организую тебе транспорт.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Лесную Песнь и поговорите с архитектором Немосом.$B$BОбратитесь к воздаятельнице Паланааре, если вам требуется транспорт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Радостно видеть нового гостя в Лесной Песни.$B$BПоборница Паланаар присылает на помощь столько народу, сколько может, и мы рады каждой паре рук.$B$BПосмотрите вокруг, $C. Может, сейчас вид не слишком впечатляет, но пройдет время, и при помощи наших союзников ночных эльфов мы построим здесь поселение, которое будет достойно называться домом. Сделать предстоит очень много, и любую помощь мы примем с радостью.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9534,'Уничтожить Легион!','Остатки демонического Пылающего Легиона слишком долго надоедали нам.$B$BХватит!$B$BЭти демоны лезут от Холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона на востоке.$B$BСтупай и уничтожь их сколько сумеешь – и покроешь славой и себя, и Орду!','Уничтожьте 15 любых демонов на холме Демонического Огня, в Каньоне Гибели Демона и Гряде Гибели Демона, а затем вернитесь к Валуше на Заставу Расщепленного Дерева в Ясеневом лесу.','Это куда лучше! Нет ничего достойнее, чем очищать наш мир от демонов. Да и противники они стоящие, не то что эти дохляки из Альянса.','Да, могучий |3-6($C), я почувствовала твое приближение. Уверена, тебе есть что еще рассказать мне о твоей охоте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить Легион!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остатки демонического Пылающего Легиона слишком долго надоедали нам.$B$BХватит!$B$BЭти демоны лезут от Холма Демонического Огня, Каньона Гибели Демона и Гряды Гибели Демона на востоке.$B$BСтупай и уничтожь их сколько сумеешь – и покроешь славой и себя, и Орду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 любых демонов на холме Демонического Огня, в Каньоне Гибели Демона и Гряде Гибели Демона, а затем вернитесь к Валуше на Заставу Расщепленного Дерева в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это куда лучше! Нет ничего достойнее, чем очищать наш мир от демонов. Да и противники они стоящие, не то что эти дохляки из Альянса.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, могучий |3-6($C), я почувствовала твое приближение. Уверена, тебе есть что еще рассказать мне о твоей охоте.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9535,'Демонические планы','Этот пергамент выронил демон, но что странно – он написан на орочьем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя Ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.$B$BВ плане подробно описывается подготовка нападения демонов на Заставу Расщепленного Дерева на северо-западе отсюда.$B$BВы уверены, что это очень заинтересует Валушу на Заставе Расщепленного Дерева.','Передайте демонические планы Валуше на Заставу Расщепленного Дерева в Ясеневом лесу.','Повелители Ужаса! Они хотят напасть на нашу заставу Расщепленного Дерева?!\n\nПока жива – не допущу!\n\n<Валуша сминает в кулаке пергамент с планами демонов.>\n\nНет. Они не пройдут! Они – погибель для нашего мира!','Что тут у тебя, Разведчик?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонические планы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот пергамент выронил демон, но что странно – он написан на орочьем! В нем упоминаются два имени – Диатор и Горганнон. Эти два повелителя Ужаса, пользующиеся дурной репутацией даже среди себе подобных, управляют демонами в здешних местах.$B$BВ плане подробно описывается подготовка нападения демонов на Заставу Расщепленного Дерева на северо-западе отсюда.$B$BВы уверены, что это очень заинтересует Валушу на Заставе Расщепленного Дерева.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте демонические планы Валуше на Заставу Расщепленного Дерева в Ясеневом лесу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Повелители Ужаса! Они хотят напасть на нашу заставу Расщепленного Дерева?!\n\nПока жива – не допущу!\n\n<Валуша сминает в кулаке пергамент с планами демонов.>\n\nНет. Они не пройдут! Они – погибель для нашего мира!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тут у тебя, Разведчик?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9536,'Никогда больше Пылающему Легиону не поработить ни орков, ни какую другую расу Орды!\n\nТы отважный боец, |3-6($C)! В груди твоей бьется сердце истинного сына Орды! Мы гордимся тобой!','Да, могучий |3-6($C), я почувствовала твое приближение. Уверена, тебе есть что еще рассказать мне о твоей охоте.','[Deprecated] Return to Velusha at Splintertree Post in Ashenvale.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Никогда больше Пылающему Легиону не поработить ни орков, ни какую другую расу Орды!\n\nТы отважный боец, |3-6($C)! В груди твоей бьется сердце истинного сына Орды! Мы гордимся тобой!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, могучий |3-6($C), я почувствовала твое приближение. Уверена, тебе есть что еще рассказать мне о твоей охоте.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','[Deprecated] Return to Velusha at Splintertree Post in Ashenvale.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9537,'Не ведая пощады','Перемолоттер должен быть привлечен к ответственности!$B$BСтупай на берег, отыщи там вероломного гнома и вытряси из него все возможные сведения!$B$BЕсли высокопоставленные представители Альянса способны на предательство, чего остается ждать от других?!$B$BИ последнее, $n: не колеблясь, применяй силу...','Добудьте для адмирала Одиссия переписку предателя у инженера "Искра" Перемолоттера','Удалось ли тебе отловить лживого шакала?','Вернитесь к адмиралу Одиссию в Лагерь Одиссия, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не ведая пощады',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Перемолоттер должен быть привлечен к ответственности!$B$BСтупай на берег, отыщи там вероломного гнома и вытряси из него все возможные сведения!$B$BЕсли высокопоставленные представители Альянса способны на предательство, чего остается ждать от других?!$B$BИ последнее, $n: не колеблясь, применяй силу...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте для адмирала Одиссия переписку предателя у инженера "Искра" Перемолоттера',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе отловить лживого шакала?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к адмиралу Одиссию в Лагерь Одиссия, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9538,'Изучение языка','Кажется, я докопался до сути, $n!$B$B<Ауррен указывает на тотем.>$B$BВсе, что нам нужно знать о языке фурболгов Тихвой, написано на их тотемах. Имея общее представление о том, как работают эти символы, мы можем изучить тотемы и научиться разговаривать с фурболгами.$B$BЗначения из таблицы символов я выписал на этот пергамент. Изучи его хорошенько, а потом займись тотемом. Он укажет тебе путь к следующему тотему языкознания.$B$BКогда изучишь язык, поговори с Аругу!','Изучите пергамент "Язык фурболгов Тихвой для начинающих", полученный от Ауррена, а потом займитесь тотемом Акиды на Лазурной заставе.','На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: "А-К-И-Д-А".','От тотема исходит негромкое гудение.','Чтение учебника языка фурболгов Тихвой.','Вернитесь к тотему Акиды на остров Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение языка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, я докопался до сути, $n!$B$B<Ауррен указывает на тотем.>$B$BВсе, что нам нужно знать о языке фурболгов Тихвой, написано на их тотемах. Имея общее представление о том, как работают эти символы, мы можем изучить тотемы и научиться разговаривать с фурболгами.$B$BЗначения из таблицы символов я выписал на этот пергамент. Изучи его хорошенько, а потом займись тотемом. Он укажет тебе путь к следующему тотему языкознания.$B$BКогда изучишь язык, поговори с Аругу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите пергамент "Язык фурболгов Тихвой для начинающих", полученный от Ауррена, а потом займитесь тотемом Акиды на Лазурной заставе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: "А-К-И-Д-А".',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','От тотема исходит негромкое гудение.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Чтение учебника языка фурболгов Тихвой.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тотему Акиды на остров Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9539,'Тотем Ку','Вы начинаете читать надпись на тотеме, едва произнося непонятные слова и фразы. Постепенно смысл написанного становится ясен. Кажется, тотем велит отправиться на ближайший холм на северо-востоке.','Найдите тотем Ку с помощью проводника.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тотем Ку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы начинаете читать надпись на тотеме, едва произнося непонятные слова и фразы. Постепенно смысл написанного становится ясен. Кажется, тотем велит отправиться на ближайший холм на северо-востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите тотем Ку с помощью проводника.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9540,'Тотем Тикти','Вы начинаете читать надпись на тотеме, с большей легкостью произнося непонятные слова и фразы. Постепенно смысл написанного делается вам ясен. Кажется, тотем велит переправиться через Хрустальную реку на востоке. Быть может, Предназначение ждет вас по ту сторону реки.','Найдите тотем Тикти с помощью проводника.','На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: "Т-И-К-Т-И".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тотем Тикти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы начинаете читать надпись на тотеме, с большей легкостью произнося непонятные слова и фразы. Постепенно смысл написанного делается вам ясен. Кажется, тотем велит переправиться через Хрустальную реку на востоке. Быть может, Предназначение ждет вас по ту сторону реки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите тотем Тикти с помощью проводника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: "Т-И-К-Т-И".',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9541,'Тотем Йора','Символы этого тотема переводятся куда быстрее. Узоры и картинки превращаются в знакомые слова. Вы почти уверены, что тотем призывает вас двинуться на юг, вниз по реке. Что-то ожидает вас на дне реки.','Найдите тотем Йора с помощью проводника.','На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: "Й-О-Р".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тотем Йора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Символы этого тотема переводятся куда быстрее. Узоры и картинки превращаются в знакомые слова. Вы почти уверены, что тотем призывает вас двинуться на юг, вниз по реке. Что-то ожидает вас на дне реки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите тотем Йора с помощью проводника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На тотеме вырезано множество примитивных рисунков: совы, медведи, волки и олени.$B$BВам бросается в глаза странный набор символов, и губы сами собой произносят: "Й-О-Р".',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9542,'Тотем Варк','Теперь все символы языка фурболгов вам хорошо знакомы. Надписи на тотеме Йора вы читаете свободно, как на родном языке.$B$BСудя по всему, на западе отсюда располагается еще одно селение фурболгов. Совершенное знание языка позволяет вам понять, что ваша цель – Деревня Косолапов. Йор поведет вас, но если вы собьетесь с пути, то знайте: через лес, точно к месту вашего назначения, ведет древняя эльфийская дорога.','Найдите тотем Варк с помощью проводника.','Вы читаете надпись на тотеме, и губы сами собой произносят: "В-А-Р-К".') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тотем Варк',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь все символы языка фурболгов вам хорошо знакомы. Надписи на тотеме Йора вы читаете свободно, как на родном языке.$B$BСудя по всему, на западе отсюда располагается еще одно селение фурболгов. Совершенное знание языка позволяет вам понять, что ваша цель – Деревня Косолапов. Йор поведет вас, но если вы собьетесь с пути, то знайте: через лес, точно к месту вашего назначения, ведет древняя эльфийская дорога.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите тотем Варк с помощью проводника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы читаете надпись на тотеме, и губы сами собой произносят: "В-А-Р-К".',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9543,'Искупление','Сколько длится наша история, столько мы и воюем с орками, $n. Однажды, одержимые жаждой крови, они чуть не истребили нас поголовно, и с тех пор мы предпочитаем держаться от них подальше, пусть даже им и удалось избавиться от власти демонов.$B$BА теперь... эта новая связь... Не скажу, чтобы она нас обрадовала. Поговори с нашим старейшиной, Амааном Мудрейшим, он поможет пролить свет на эти события.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искупление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сколько длится наша история, столько мы и воюем с орками, $n. Однажды, одержимые жаждой крови, они чуть не истребили нас поголовно, и с тех пор мы предпочитаем держаться от них подальше, пусть даже им и удалось избавиться от власти демонов.$B$BА теперь... эта новая связь... Не скажу, чтобы она нас обрадовала. Поговори с нашим старейшиной, Амааном Мудрейшим, он поможет пролить свет на эти события.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9544,'Пророчество Акиды','На тотеме изображена война между племенами Тихвой и Косолапов. Судя по всему, фурболги племени Косолапов вытворяли немыслимые вещи с собратьями из племени Тихвой.$B$BИ вот среди хаоса начало сбываться пророчество: придет герой иной крови и спасет племя Тихвой.$B$BУбейте фурболгов из деревни Косолапов и отберите у них ключи. Отоприте клетки с пленниками из племени Тихвой. Освободив всех, возвращайтесь к Аругу из племени Тихвой.','Освободите 8 пленников из племени Тихвой из клеток в деревне Косолапов. Вернитесь к Аругу из племени Тихвой на Лазурную заставу.','Итак, пророчество Акиды истинно... Герой пришел к нам.','Вернитесь к Аругу из племени Тихвой на Лазурную заставу, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пророчество Акиды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На тотеме изображена война между племенами Тихвой и Косолапов. Судя по всему, фурболги племени Косолапов вытворяли немыслимые вещи с собратьями из племени Тихвой.$B$BИ вот среди хаоса начало сбываться пророчество: придет герой иной крови и спасет племя Тихвой.$B$BУбейте фурболгов из деревни Косолапов и отберите у них ключи. Отоприте клетки с пленниками из племени Тихвой. Освободив всех, возвращайтесь к Аругу из племени Тихвой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 8 пленников из племени Тихвой из клеток в деревне Косолапов. Вернитесь к Аругу из племени Тихвой на Лазурную заставу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Итак, пророчество Акиды истинно... Герой пришел к нам.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аругу из племени Тихвой на Лазурную заставу, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9545,'Реликвия ясновидца','Упрямцы ограничивают свой разум, утверждая, что истина может быть только одна. Но мудрые распахивают свой ум навстречу множеству вероятностей, которые коренятся в настоящем и прорастают в будущее.$B$BОтнеси эту реликвию туда, где ты $gнашел:нашла; Седаи. Смотри глазами, но видь разумом, $n,','Вернитесь к Амаану Мудрейшему в Храм Телхамата на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвия ясновидца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Упрямцы ограничивают свой разум, утверждая, что истина может быть только одна. Но мудрые распахивают свой ум навстречу множеству вероятностей, которые коренятся в настоящем и прорастают в будущее.$B$BОтнеси эту реликвию туда, где ты $gнашел:нашла; Седаи. Смотри глазами, но видь разумом, $n,',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Амаану Мудрейшему в Храм Телхамата на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9546,'Исполнение пророчества','Пророчество гласило, что явится Избранный, который избавит нас от смертельной хватки Косолапов, и сами духи возвестят прибытие этого героя.$B$BИ вот ты здесь.$B$BПреклоняюсь перед тобой, о $gВеликий:Великая;. Умоляю, спаси наших малышей. Их захватили воины племени Косолапов, застав нас врасплох. Их держат в клетках в Деревне Косолапов на юго-западе. Ключи от клеток – у фурболгов-косолапов. Убей их и забери ключи. Освободи мой народ.','Освободить 8 пленников из племени Тихвой из клеток в Деревне Косолапов по просьбе Аругу из племени Тихвой.','Вернитесь к Аругу из племени Тихвой на остров Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исполнение пророчества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пророчество гласило, что явится Избранный, который избавит нас от смертельной хватки Косолапов, и сами духи возвестят прибытие этого героя.$B$BИ вот ты здесь.$B$BПреклоняюсь перед тобой, о $gВеликий:Великая;. Умоляю, спаси наших малышей. Их захватили воины племени Косолапов, застав нас врасплох. Их держат в клетках в Деревне Косолапов на юго-западе. Ключи от клеток – у фурболгов-косолапов. Убей их и забери ключи. Освободи мой народ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободить 8 пленников из племени Тихвой из клеток в Деревне Косолапов по просьбе Аругу из племени Тихвой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аругу из племени Тихвой на остров Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9547,'Зов Воздуха','$n, Предсказатель Нобундо спрашивал о тебе. Должно быть, настало время познать тайны воздуха, последней из стихий!$B$BЯ хочу сказать, что очень горжусь твоими достижениями. Впереди тебя ждут великие свершения.','Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.','И, наконец, мы подошли к последнему из четырех великих элементов: воздуху. Ты считаешь себя достаточно $Gмудрым:мудрой;, чтобы продолжить, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, Предсказатель Нобундо спрашивал о тебе. Должно быть, настало время познать тайны воздуха, последней из стихий!$B$BЯ хочу сказать, что очень горжусь твоими достижениями. Впереди тебя ждут великие свершения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И, наконец, мы подошли к последнему из четырех великих элементов: воздуху. Ты считаешь себя достаточно $Gмудрым:мудрой;, чтобы продолжить, $N?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9548,'Украденное снаряжение','Тсс! Говори тише, не привлекай ко мне внимания.$B$BЕсли мурлоки меня обнаружат, весь эксперимент пойдет прахом! Я и так весьма близок к тому, чтобы утратить все полученные данные...$B$BВчера, пока я пополнял запасы, один из мурлоков, надо думать, подошел слишком близко и обнаружил мой лагерь. Я возвращаюсь – и что же вижу? Эти пучеглазые куда-то волокут ящик с моим снаряжением! Уверен, они его припрятали в одном из поселений. Только мне высовываться не резон, не будет от этого добра. Может, ты мне поможешь? А?','Верните Клопперу Бацбаху его оборудование. Клоппера можно найти в старом черепашьем панцире на берегу.','Ну как, ты $Gнашел:нашла; мое оборудование?','Вернитесь к Клопперу Бацбаху на Остров Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Украденное снаряжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тсс! Говори тише, не привлекай ко мне внимания.$B$BЕсли мурлоки меня обнаружат, весь эксперимент пойдет прахом! Я и так весьма близок к тому, чтобы утратить все полученные данные...$B$BВчера, пока я пополнял запасы, один из мурлоков, надо думать, подошел слишком близко и обнаружил мой лагерь. Я возвращаюсь – и что же вижу? Эти пучеглазые куда-то волокут ящик с моим снаряжением! Уверен, они его припрятали в одном из поселений. Только мне высовываться не резон, не будет от этого добра. Может, ты мне поможешь? А?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните Клопперу Бацбаху его оборудование. Клоппера можно найти в старом черепашьем панцире на берегу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, ты $Gнашел:нашла; мое оборудование?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Клопперу Бацбаху на Остров Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9549,'Артефакты клана Черного Ила','Мои наблюдения и заметки о мурлоках из племени Черного Ила, несомненно, станут большим вкладом в науку, можешь мне поверить, $n. Однако все это – лишь начало. Я намереваюсь вернуться в Стальгорн и продемонстрировать там примитивные творения этого клана.$B$BОднако есть одно маленькое "но", мешающее осуществлению моих планов. Дело в том, что мурлоки постоянно носят нужные мне предметы при себе, а я не вынесу бремени убийства... Но если ты поможешь мне заполучить идолов, которые носят с собой провидцы племени Черного Ила, а также несколько ножей – из тех, которыми вооружены их воины, я не стану допытываться, как эти вещи попали к тебе.','Принесите 3 варварских идола и 6 варварских ножа мурлоков Клопперу Бацбаху, который прячется в старом черепашьем панцире на берегу.','Ну что? Ну как? Получилось у тебя, э-э, достать артефакты, которые я мог бы отправить в Стальгорн?','Вернитесь к Клопперу Бацбаху на Остров Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Артефакты клана Черного Ила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои наблюдения и заметки о мурлоках из племени Черного Ила, несомненно, станут большим вкладом в науку, можешь мне поверить, $n. Однако все это – лишь начало. Я намереваюсь вернуться в Стальгорн и продемонстрировать там примитивные творения этого клана.$B$BОднако есть одно маленькое "но", мешающее осуществлению моих планов. Дело в том, что мурлоки постоянно носят нужные мне предметы при себе, а я не вынесу бремени убийства... Но если ты поможешь мне заполучить идолов, которые носят с собой провидцы племени Черного Ила, а также несколько ножей – из тех, которыми вооружены их воины, я не стану допытываться, как эти вещи попали к тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 варварских идола и 6 варварских ножа мурлоков Клопперу Бацбаху, который прячется в старом черепашьем панцире на берегу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что? Ну как? Получилось у тебя, э-э, достать артефакты, которые я мог бы отправить в Стальгорн?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Клопперу Бацбаху на Остров Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9550,'Загадочная карта','Небрежно нарисованная карта не может рассказать ничего о том, кто сделал ее – кроме того, что у картографа была нетвердая рука. Здесь изображен небольшой павильон с полуразрушенной колоннадой – похоже, он находится к западу от частично затопленной башни.$B$BЕсли верить карте, эти руины находятся на восточном побережье острова. Неизвестно, что там находится, но неведомый картограф, видимо, считал это достаточно важным.','Найдите павильон, изображенный на карте, и выясните, что в нем необычного.','При внимательном рассмотрении выясняется, что найденная книга представляет собой дневник. Записи в нем сделаны изящным почерком, сильно отличающимся от почерка картографа. Впрочем, картограф отметился и здесь: на многих страницах нельзя разобрать первоначальный текст – поверх него сделаны какие-то наброски и записи.$B$BВозможно, изначально рукопись действительно содержала ценные сведения, но сейчас прочесть удается только рассказ картографа о каком-то пьяном загуле в порту.','Возможно, эта старая рукопись и есть то важное, ради чего была нарисована карта...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадочная карта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Небрежно нарисованная карта не может рассказать ничего о том, кто сделал ее – кроме того, что у картографа была нетвердая рука. Здесь изображен небольшой павильон с полуразрушенной колоннадой – похоже, он находится к западу от частично затопленной башни.$B$BЕсли верить карте, эти руины находятся на восточном побережье острова. Неизвестно, что там находится, но неведомый картограф, видимо, считал это достаточно важным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите павильон, изображенный на карте, и выясните, что в нем необычного.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','При внимательном рассмотрении выясняется, что найденная книга представляет собой дневник. Записи в нем сделаны изящным почерком, сильно отличающимся от почерка картографа. Впрочем, картограф отметился и здесь: на многих страницах нельзя разобрать первоначальный текст – поверх него сделаны какие-то наброски и записи.$B$BВозможно, изначально рукопись действительно содержала ценные сведения, но сейчас прочесть удается только рассказ картографа о каком-то пьяном загуле в порту.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Возможно, эта старая рукопись и есть то важное, ради чего была нарисована карта...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9551,'Зов Воздуха','$n,предсказатель Нобундо спрашивал о тебе. Должно быть, настало время познать тайны воздуха, последней из стихий!$B$BЯ хочу сказать, что очень горжусь твоими достижениями. Впереди тебя ждут великие свершения.','Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.','И, наконец, мы подошли к последнему из четырех великих элементов: воздуху. Ты считаешь себя достаточно $Gмудрым:мудрой;, чтобы продолжить, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n,предсказатель Нобундо спрашивал о тебе. Должно быть, настало время познать тайны воздуха, последней из стихий!$B$BЯ хочу сказать, что очень горжусь твоими достижениями. Впереди тебя ждут великие свершения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И, наконец, мы подошли к последнему из четырех великих элементов: воздуху. Ты считаешь себя достаточно $Gмудрым:мудрой;, чтобы продолжить, $N?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9552,'Зов Воздуха','Тебя призывает великий дух воздуха, и пришло время ответить на зов.$B$BПоднимись по Штормовому пути на северном склоне горы, в которую врезался Экзодар. На вершине ты найдешь пещеру. В ней живет одна из моих самых лучших учениц, Велаада.$B$BВыслушай ее мудрые слова и повинуйся ей. Так ты обретешь глубокое понимание стихии Воздуха.','Поговорите с Велаадой на Штормовом Пике острова Лазурной Дымки.','Мне по ветру шептали, что ты придешь, $C. $B$BПровидец Нобундо очень высокого мнения о тебе, и, судя по тому, что я слышал о твоих путешествиях, я тоже.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя призывает великий дух воздуха, и пришло время ответить на зов.$B$BПоднимись по Штормовому пути на северном склоне горы, в которую врезался Экзодар. На вершине ты найдешь пещеру. В ней живет одна из моих самых лучших учениц, Велаада.$B$BВыслушай ее мудрые слова и повинуйся ей. Так ты обретешь глубокое понимание стихии Воздуха.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Велаадой на Штормовом Пике острова Лазурной Дымки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне по ветру шептали, что ты придешь, $C. $B$BПровидец Нобундо очень высокого мнения о тебе, и, судя по тому, что я слышал о твоих путешествиях, я тоже.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9553,'Зов Воздуха','Хотя воздух неосязаем, это – могучая сила, окутывающая все вокруг и проникающая повсюду.$B$BЕго не видит око, но даже камень этой горы состоит по большей части из воздуха, воздух растворен и в морской воде, а огонь не смог бы пылать без него. Только не говори об этом другим стихиям!$B$BТот, кто может научить тебя этой мудрости, находится совсем рядом. На северном крае этого пика тебя ждет Шептатель. Благодаря ему ты познаешь суть стихии Воздуха.','Поговорите с Шептателем на Штормовом Пике острова Лазурной Дымки.','Я ждал твоего приезда, $C. Я чувствую что, ты $Gпришел:пришла; искать мудрости и чего-то еще. $B$BХорошо, приступим.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя воздух неосязаем, это – могучая сила, окутывающая все вокруг и проникающая повсюду.$B$BЕго не видит око, но даже камень этой горы состоит по большей части из воздуха, воздух растворен и в морской воде, а огонь не смог бы пылать без него. Только не говори об этом другим стихиям!$B$BТот, кто может научить тебя этой мудрости, находится совсем рядом. На северном крае этого пика тебя ждет Шептатель. Благодаря ему ты познаешь суть стихии Воздуха.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Шептателем на Штормовом Пике острова Лазурной Дымки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я ждал твоего приезда, $C. Я чувствую что, ты $Gпришел:пришла; искать мудрости и чего-то еще. $B$BХорошо, приступим.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9554,'Зов Воздуха','Хотя мои братья и сестры других стихий просили тебя выполнить различные задания, я ничего не хочу от тебя. Мне кажется, ты и так $gсовершил:совершила; немало, расплатившись за корабль, рухнувший в эти земли с моих небес. Я вижу, у тебя довольно мудрости, чтобы разумно распорядиться стихией воздуха.$B$BОтнеси эту часть моей сущности предсказателю Нобундо, и он поможет тебе создать тотем. Я готов отнести тебя в Экзодар по воздуху.','Отдайте Завихрение воздуха предсказателю Нобундо в Экзодаре.','Я горжусь тобой, $N. Ты стойко $Gвыстоял:выстояла; там, где другие колеблются, и в процессе ты $Gполучил:получила; лучшее понимание стихий и себя. Помни их уроки на своем жизненном пути, и ты станешь мудрее. $B$BА теперь дай мне завиток Сусурруса, чтобы я мог наполнить им твой тотем воздуха. Как и другие тотемы, он будет служить тебе, так и будет напоминанием о связи, которую ты $Gустановил:установила; со стихиями.','Так скоро $Gвернулся:вернулась;? Твои волосы выглядят взъерошенными.$B$B<Нобундо понимающе усмехается.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя мои братья и сестры других стихий просили тебя выполнить различные задания, я ничего не хочу от тебя. Мне кажется, ты и так $gсовершил:совершила; немало, расплатившись за корабль, рухнувший в эти земли с моих небес. Я вижу, у тебя довольно мудрости, чтобы разумно распорядиться стихией воздуха.$B$BОтнеси эту часть моей сущности предсказателю Нобундо, и он поможет тебе создать тотем. Я готов отнести тебя в Экзодар по воздуху.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте Завихрение воздуха предсказателю Нобундо в Экзодаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я горжусь тобой, $N. Ты стойко $Gвыстоял:выстояла; там, где другие колеблются, и в процессе ты $Gполучил:получила; лучшее понимание стихий и себя. Помни их уроки на своем жизненном пути, и ты станешь мудрее. $B$BА теперь дай мне завиток Сусурруса, чтобы я мог наполнить им твой тотем воздуха. Как и другие тотемы, он будет служить тебе, так и будет напоминанием о связи, которую ты $Gустановил:установила; со стихиями.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так скоро $Gвернулся:вернулась;? Твои волосы выглядят взъерошенными.$B$B<Нобундо понимающе усмехается.>',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9555,'Зов Огня','Я рад, что ты $Gизбрал:избрала; нелегкий путь шамана. Немногие решаются на это, но я провижу, что нам не обойтись без шаманизма, который мы переняли от Сломленных.$B$BДа, теперь их называют именно так, но они некогда были дренеями. Их изменила магия Скверны, и поэтому они не могут призывать на помощь силу Света. Многие относятся к ним, а заодно и к шаманизму, с подозрением, но они не несут зла.$B$BЯ хочу, чтобы ты $gпобеседовал:побеседовала; с предсказателем Нобундо. Он – мудрейший из известных мне шаманов, и под его руководством ты многому научишься.','Поговорите с предсказателем Нобундо в Кристальном зале Экзодара.','Приветствую. Всегда приятно встретить $R, открытого на путь шаманизма. Их так мало. $B$BВы научились не судить пламя по его внешнему виду, как и мое. $B$BВы здесь, потому что готовы создать свой тотем огня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов Огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рад, что ты $Gизбрал:избрала; нелегкий путь шамана. Немногие решаются на это, но я провижу, что нам не обойтись без шаманизма, который мы переняли от Сломленных.$B$BДа, теперь их называют именно так, но они некогда были дренеями. Их изменила магия Скверны, и поэтому они не могут призывать на помощь силу Света. Многие относятся к ним, а заодно и к шаманизму, с подозрением, но они не несут зла.$B$BЯ хочу, чтобы ты $gпобеседовал:побеседовала; с предсказателем Нобундо. Он – мудрейший из известных мне шаманов, и под его руководством ты многому научишься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предсказателем Нобундо в Кристальном зале Экзодара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую. Всегда приятно встретить $R, открытого на путь шаманизма. Их так мало. $B$BВы научились не судить пламя по его внешнему виду, как и мое. $B$BВы здесь, потому что готовы создать свой тотем огня.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9556,'Вода для мага','Ты без сомнения прекрасно $gпроявил:проявила; себя в борьбе за башни, |3-6($r), и непременно получишь свою награду за доблесть. Но сначала ты $gдолжен:должна; доказать, что понимаешь всю глубину разыгравшейся здесь трагедии.$B$BОтправляйся на улицы Стратхольма и найди сосуд со святой водой. Отнеси его в Квартал Магов в Штормград или Подгород... Если твои сородичи одержали верх в тех землях, тебе удастся добраться до кого-то из моих коллег.','Найдите бутылку святой воды Стратхольма на улицах Стратхольма и доставьте ее Лордеронскому магу в Квартал Магов в Штормграде или Подгороде, если вашей стороне удалось одержать верх в Восточных Чумных землях.','Вернитесь к Лордеронскому магу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вода для мага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты без сомнения прекрасно $gпроявил:проявила; себя в борьбе за башни, |3-6($r), и непременно получишь свою награду за доблесть. Но сначала ты $gдолжен:должна; доказать, что понимаешь всю глубину разыгравшейся здесь трагедии.$B$BОтправляйся на улицы Стратхольма и найди сосуд со святой водой. Отнеси его в Квартал Магов в Штормград или Подгород... Если твои сородичи одержали верх в тех землях, тебе удастся добраться до кого-то из моих коллег.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите бутылку святой воды Стратхольма на улицах Стратхольма и доставьте ее Лордеронскому магу в Квартал Магов в Штормграде или Подгороде, если вашей стороне удалось одержать верх в Восточных Чумных землях.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лордеронскому магу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9557,'Расшифровка книги','Прочесть записи невозможно – изначальный текст нельзя отделить от скорописи картографа. Но, может быть, кто-нибудь все-таки сумеет это сделать?..$B$BАнахорет Пайтеус собрал множество артефактов различных культур: возможно, его опыт поможет расшифровать и эти записи?','Отнесите древние записи на Кровавую заставу и покажите анахорету Пайтеусу.','Хмм... Непростая задача. Да, вероятно, я сумею выяснить, что же написал на этих страницах первый автор.$B$BСначала мне нужно взять все необходимое для расшифровки. Это не займет много времени...','Да озарит благословенный Свет все твои начинания, |3-6($c). Ну, показывай, с чем $Gпришел:пришла;...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расшифровка книги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прочесть записи невозможно – изначальный текст нельзя отделить от скорописи картографа. Но, может быть, кто-нибудь все-таки сумеет это сделать?..$B$BАнахорет Пайтеус собрал множество артефактов различных культур: возможно, его опыт поможет расшифровать и эти записи?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите древние записи на Кровавую заставу и покажите анахорету Пайтеусу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм... Непростая задача. Да, вероятно, я сумею выяснить, что же написал на этих страницах первый автор.$B$BСначала мне нужно взять все необходимое для расшифровки. Это не займет много времени...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да озарит благословенный Свет все твои начинания, |3-6($c). Ну, показывай, с чем $Gпришел:пришла;...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9558,'Длиннобородые') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Длиннобородые',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9559,'Логово клана Тихвой','$GИзбранный:Избранная;, отправляйся на север, к дому моего народа – в логово клана Тихвой. Именно там тебя ждет самое сложное испытание.$B$BСтупай, верховный вождь клана Тихвой ждет твоего прибытия.','Поговорите с верховным вождем клана Тихвой в Логове клана.','Много сотен лет мы жили в относительном мире с прочими обитателями этих земель. Несколько месяцев назад Курц увидел грозные предзнаменования. Долгий мир подошел к концу. Но мы и не представляли, насколько серьезны будут последствия катастрофы!$B$BКажется, будто сами боги принесли раздор в наши края: против нас выступили и враги, и друзья. Но пророчество говорит и о другом... Среди всеобщего хаоса нам явится герой – герой не нашей крови. Избранный спасет нас от гибели.$B$BЭтот герой – ты.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Логово клана Тихвой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GИзбранный:Избранная;, отправляйся на север, к дому моего народа – в логово клана Тихвой. Именно там тебя ждет самое сложное испытание.$B$BСтупай, верховный вождь клана Тихвой ждет твоего прибытия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным вождем клана Тихвой в Логове клана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Много сотен лет мы жили в относительном мире с прочими обитателями этих земель. Несколько месяцев назад Курц увидел грозные предзнаменования. Долгий мир подошел к концу. Но мы и не представляли, насколько серьезны будут последствия катастрофы!$B$BКажется, будто сами боги принесли раздор в наши края: против нас выступили и враги, и друзья. Но пророчество говорит и о другом... Среди всеобщего хаоса нам явится герой – герой не нашей крови. Избранный спасет нас от гибели.$B$BЭтот герой – ты.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9560,'Звери Судного дня!','Принесите 8 шкур опустошителей Мурдо в логово клана Тихвой.','Какие гнусные твари! Даже Слепой Наблюдатель их видит... а ведь он слеп.','Вернитесь к Мурдо в логово клана Тихвой, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Звери Судного дня!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 шкур опустошителей Мурдо в логово клана Тихвой.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие гнусные твари! Даже Слепой Наблюдатель их видит... а ведь он слеп.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мурдо в логово клана Тихвой, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9561,'Записи Нолкаи','Ну вот, $n, перевод готов.$B$B<Анахорет Пайтеус указывает на последний переведенный фрагмент.>$B$B"Враги уже близко. Мы собрали всех, кто выжил, и отошли на восток, к храму. Храм – наш последний оплот на этом острове. Многие думают, что именно здесь нам суждено принять последний бой. Я спрятал то немногое, что у меня было, у подножия храма – надеюсь, кто-нибудь найдет мой тайник и узнает, что здесь произошло..."','Найдите место, описанное в дневнике Нолкаи, и отыщите его тайник.','Земляной холмик, явно искусственного происхождения, зарос травами и кустарником.$B$BЧерез несколько минут из-под слоя земли появляется старый ящик. Вероятно, это именно то, о чем говорилось в записях Нолкаи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Записи Нолкаи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот, $n, перевод готов.$B$B<Анахорет Пайтеус указывает на последний переведенный фрагмент.>$B$B"Враги уже близко. Мы собрали всех, кто выжил, и отошли на восток, к храму. Храм – наш последний оплот на этом острове. Многие думают, что именно здесь нам суждено принять последний бой. Я спрятал то немногое, что у меня было, у подножия храма – надеюсь, кто-нибудь найдет мой тайник и узнает, что здесь произошло..."',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите место, описанное в дневнике Нолкаи, и отыщите его тайник.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Земляной холмик, явно искусственного происхождения, зарос травами и кустарником.$B$BЧерез несколько минут из-под слоя земли появляется старый ящик. Вероятно, это именно то, о чем говорилось в записях Нолкаи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9562,'Мурлоки... За что нам эта напасть?','Темные настали дни, $GИзбранный:Избранная;. Даже мурлоки наступают нам на пятки – в прямом смысле слова. К сожалению, недавно они посягнули не только на мое самолюбие.$B$BУ нас всегда были напряженные отношения с племенем Илистых Плавников, но я и помыслить не мог, что они осмелятся напасть на нас и похитить запасы продовольствия! Отправляйся на запад, к Илистому берегу, и верни наши припасы!$B$BИ если тебе попадется темнокожий мурлок с клоком белой шерсти, застрявшим между пальцами...','Верните 5 мешков зерна клана Тихвой.','М... Вкусное зерно... Паркат будет в восторге!','Мурлок дал мне пинка и плюнул на меня... среди бела дня!','Вернитесь к Гурфу в логово клана Тихвой, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мурлоки... За что нам эта напасть?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Темные настали дни, $GИзбранный:Избранная;. Даже мурлоки наступают нам на пятки – в прямом смысле слова. К сожалению, недавно они посягнули не только на мое самолюбие.$B$BУ нас всегда были напряженные отношения с племенем Илистых Плавников, но я и помыслить не мог, что они осмелятся напасть на нас и похитить запасы продовольствия! Отправляйся на запад, к Илистому берегу, и верни наши припасы!$B$BИ если тебе попадется темнокожий мурлок с клоком белой шерсти, застрявшим между пальцами...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните 5 мешков зерна клана Тихвой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','М... Вкусное зерно... Паркат будет в восторге!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мурлок дал мне пинка и плюнул на меня... среди бела дня!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гурфу в логово клана Тихвой, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9563,'Доверие Миррена','Принесите Миррену Длиннобороду 1 кружку горькой настойки Стражей Пустоты. Для выполнения этого задания необходимо иметь дружелюбное отношение Оплота Чести.','У тебя проблемы с настойкой? Старый добрый Берни из Крепости Стражей Пустоты обычно запасает ее бочками.$B$BЕсли, конечно, он не смылся оттуда куда подальше... Вот это была бы беда так беда!','Вернитесь к Миррену Длиннобороду на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доверие Миррена',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Миррену Длиннобороду 1 кружку горькой настойки Стражей Пустоты. Для выполнения этого задания необходимо иметь дружелюбное отношение Оплота Чести.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя проблемы с настойкой? Старый добрый Берни из Крепости Стражей Пустоты обычно запасает ее бочками.$B$BЕсли, конечно, он не смылся оттуда куда подальше... Вот это была бы беда так беда!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Миррену Длиннобороду на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (9564,'Клок шерсти Гурфа','Вы нашли клок шерсти, потерянный Гурфом в борьбе с мурлоками. Отнесите его Гурфу и сообщите, что ужасный Мургургул убит.','Неужели это он?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клок шерсти Гурфа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы нашли клок шерсти, потерянный Гурфом в борьбе с мурлоками. Отнесите его Гурфу и сообщите, что ужасный Мургургул убит.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели это он?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9565,'Поиски в логове клана Тихвой','Я верховный вождь, и поэтому более всего меня волнует причина предательства союзников.$B$BПочему дикие совухи – наши бывшие друзья – решили на нас напасть? Почему они поселились в Логове клана Тихвой?$B$BМожет быть, ответ на мой вопроc таится внутри. Попытайся докопаться до правды.','Найдите в логове клана Тихвой причины предательства совухов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски в логове клана Тихвой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я верховный вождь, и поэтому более всего меня волнует причина предательства союзников.$B$BПочему дикие совухи – наши бывшие друзья – решили на нас напасть? Почему они поселились в Логове клана Тихвой?$B$BМожет быть, ответ на мой вопроc таится внутри. Попытайся докопаться до правды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в логове клана Тихвой причины предательства совухов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9566,'Кровавые кристаллы','На первый взгляд этот кристалл кажется частью Экзодара. На самом деле с ним что-то не так – он кроваво-красный и быстро растворяется в пещерной воде.$B$BВозможно, именно этим объясняется необычно агрессивное поведение существ острова Лазурной Дымки. Сообщите об этом верховному вождю племени Тихвой.','Поговорите с верховным вождем племени в логове клана Тихвой.','Мои разведчики видели много таких же кристаллов на севере.$B$BБлагодарю за помощь, но теперь мне нужно посоветоваться со старейшинами. По окончании совещания я пошлю за тобой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровавые кристаллы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На первый взгляд этот кристалл кажется частью Экзодара. На самом деле с ним что-то не так – он кроваво-красный и быстро растворяется в пещерной воде.$B$BВозможно, именно этим объясняется необычно агрессивное поведение существ острова Лазурной Дымки. Сообщите об этом верховному вождю племени Тихвой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным вождем племени в логове клана Тихвой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мои разведчики видели много таких же кристаллов на севере.$B$BБлагодарю за помощь, но теперь мне нужно посоветоваться со старейшинами. По окончании совещания я пошлю за тобой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9567,'Лицо врага','Приветствую, |3-6($c). Приятно видеть у нас, на Кровавой заставе, еще $gодного искателя:одну искательницу; приключений. Конечно, эльфы крови сейчас представляют наиболее явную угрозу; однако на острове Кровавой Дымки есть и другие твари, от которых нельзя ждать ничего хорошего.$B$BСатиры из племени Наззивус – источник постоянной тревоги для нас. Это ужасные существа – демонические создания, использующие черную магию; скверна, порожденная падением "Экзодара", питает их и придает им сил.$B$BМы должны научиться контролировать сатиров – но для этого нам нужно знать о них как можно больше. Отправляйся на юго-запад к Наззивиану, отыщи их нелепый монумент и попробуй что-нибудь разузнать.','Найдите в Наззивиане монумент Наззивуса, возьмите один из иероглифов с монумента и вернитесь к воздаятельнице Алезии на Кровавую заставу.','Удалось ли тебе узнать хоть что-то новое о сатирах из племени Наззивус?','Вернитесь к воздаятельнице Алезии на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лицо врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, |3-6($c). Приятно видеть у нас, на Кровавой заставе, еще $gодного искателя:одну искательницу; приключений. Конечно, эльфы крови сейчас представляют наиболее явную угрозу; однако на острове Кровавой Дымки есть и другие твари, от которых нельзя ждать ничего хорошего.$B$BСатиры из племени Наззивус – источник постоянной тревоги для нас. Это ужасные существа – демонические создания, использующие черную магию; скверна, порожденная падением "Экзодара", питает их и придает им сил.$B$BМы должны научиться контролировать сатиров – но для этого нам нужно знать о них как можно больше. Отправляйся на юго-запад к Наззивиану, отыщи их нелепый монумент и попробуй что-нибудь разузнать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Наззивиане монумент Наззивуса, возьмите один из иероглифов с монумента и вернитесь к воздаятельнице Алезии на Кровавую заставу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе узнать хоть что-то новое о сатирах из племени Наззивус?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятельнице Алезии на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9568,'Лучшая защита','Дела обстоят хуже, чем я думала, $n. Нам, дренеям, хорошо известно, что происходит с теми, кто решается продать душу Легиону в обмен на обещание бессмертия и могущества...$B$BПлемя сатиров этого острова – Наззивус – это потомки злосчастных существ, вступивших в союз с Легионом. Боюсь, они найдут способ использовать оскверненные кристаллы как оружие и обратят их силу против нас.$B$BТы $Gвидел:видела;, во что кристаллы превратили эту землю – так представь себе, на что окажутся способны сатиры, если к ним попадет такое оружие!.. Отправляйся на юго-запад, в Наззивиан, и помни: иногда нападение – лучшая защита!','Воздаятельница Алезия с Кровавой заставы просит убить 10 сатиров, 5 разбойников и 5 скверноподанных из племени Наззивус.','Вернитесь к воздаятельнице Алезии на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучшая защита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дела обстоят хуже, чем я думала, $n. Нам, дренеям, хорошо известно, что происходит с теми, кто решается продать душу Легиону в обмен на обещание бессмертия и могущества...$B$BПлемя сатиров этого острова – Наззивус – это потомки злосчастных существ, вступивших в союз с Легионом. Боюсь, они найдут способ использовать оскверненные кристаллы как оружие и обратят их силу против нас.$B$BТы $Gвидел:видела;, во что кристаллы превратили эту землю – так представь себе, на что окажутся способны сатиры, если к ним попадет такое оружие!.. Отправляйся на юго-запад, в Наззивиан, и помни: иногда нападение – лучшая защита!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воздаятельница Алезия с Кровавой заставы просит убить 10 сатиров, 5 разбойников и 5 скверноподанных из племени Наззивус.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятельнице Алезии на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9569,'Противостояние','Теперь, когда мы дали сатирам понять, что не уйдем с этой земли, пора показать, что терпеть здесь отродий Пылающего Легиона мы также не намерены.$B$BСлишком долго дренеи стремились избежать столкновения с Легионом и его приспешниками, $n; слишком долго – и это не принесло нам ничего, кроме горестей. Когда псы Легиона находили нас, они не щадили никого.$B$BСатиры не должны воспользоваться оскверненными кристаллами, оставшимися после гибели "Экзодара"; тем более они не должны использовать эти кристаллы в качестве оружия. Отправляйся на север, в Аксариен, разыщи предводителя сатиров, убей его и верни нам те кристаллы, которые он уже успел собрать.','Убейте Зевракса, 5 аксариенских тенеловов и 5 аксариенских призывателей огня, соберите 5 оскверненных кристаллов и отнесите их на Кровавую заставу воздаятельнице Алезии.','Лишившись своего предводителя, а заодно и уже собранных оскверненных кристаллов, сатиры стали значительно менее опасными для нас. Но лишь Предвечному Свету ведомо, сколько здесь еще этих злосчастных тварей...$B$BМы – я и вестник Миколаас – благодарны тебе за помощь: если бы не это, сатиры стали бы для нас слишком серьезной угрозой. Решимость и отвага – вот ключ к победе над Легионом и его приспешниками!','Вернитесь к воздаятельнице Алезии на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Противостояние',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы дали сатирам понять, что не уйдем с этой земли, пора показать, что терпеть здесь отродий Пылающего Легиона мы также не намерены.$B$BСлишком долго дренеи стремились избежать столкновения с Легионом и его приспешниками, $n; слишком долго – и это не принесло нам ничего, кроме горестей. Когда псы Легиона находили нас, они не щадили никого.$B$BСатиры не должны воспользоваться оскверненными кристаллами, оставшимися после гибели "Экзодара"; тем более они не должны использовать эти кристаллы в качестве оружия. Отправляйся на север, в Аксариен, разыщи предводителя сатиров, убей его и верни нам те кристаллы, которые он уже успел собрать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зевракса, 5 аксариенских тенеловов и 5 аксариенских призывателей огня, соберите 5 оскверненных кристаллов и отнесите их на Кровавую заставу воздаятельнице Алезии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Лишившись своего предводителя, а заодно и уже собранных оскверненных кристаллов, сатиры стали значительно менее опасными для нас. Но лишь Предвечному Свету ведомо, сколько здесь еще этих злосчастных тварей...$B$BМы – я и вестник Миколаас – благодарны тебе за помощь: если бы не это, сатиры стали бы для нас слишком серьезной угрозой. Решимость и отвага – вот ключ к победе над Легионом и его приспешниками!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятельнице Алезии на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9570,'Куркен-жмуркен','Когда кристальная буря улеглась, в нашу деревню явилось чудище из древних легенд. Оказалось, что этого зверя, Куркена, привели сюда дикие совухи. Он погубил многих моих соплеменников, пытавшихся отстоять родную деревню, и с тех пор многие, бросившие ему вызов, погибли.$B$BМне было видение, что победа над тварью близка. Я не сомневаюсь, что именно тебе суждено совершить этот подвиг, $n. Ты – наша последняя надежда. Ступай в логово клана Тихвой, убей Куркена и в доказательство принеси мне его шкуру.','Убейте Куркена и принесите его шкуру Курцу Прорицателю в логово клана Тихвой на острове Лазурной Дымки.','Вернитесь к Курцу Прорицателю в логово клана Тихвой, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Куркен-жмуркен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда кристальная буря улеглась, в нашу деревню явилось чудище из древних легенд. Оказалось, что этого зверя, Куркена, привели сюда дикие совухи. Он погубил многих моих соплеменников, пытавшихся отстоять родную деревню, и с тех пор многие, бросившие ему вызов, погибли.$B$BМне было видение, что победа над тварью близка. Я не сомневаюсь, что именно тебе суждено совершить этот подвиг, $n. Ты – наша последняя надежда. Ступай в логово клана Тихвой, убей Куркена и в доказательство принеси мне его шкуру.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Куркена и принесите его шкуру Курцу Прорицателю в логово клана Тихвой на острове Лазурной Дымки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Курцу Прорицателю в логово клана Тихвой, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9571,'Шкура Куркена','Отнесите шкуру Куркена Мурдо на другою сторону деревни. Он сделает из нее все, что вы захотите.','Отнесите шкуру Куркена Мурдо в логово клана Тихвой.','Привет $Gгерою:героине;!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шкура Куркена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отнесите шкуру Куркена Мурдо на другою сторону деревни. Он сделает из нее все, что вы захотите.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите шкуру Куркена Мурдо в логово клана Тихвой.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет $Gгерою:героине;!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9572,'Ослабить оборону валов','Нужно торопиться, у нас мало очень времени. На карту поставлено само существование Траллмара!$B$BМы зажаты между Цитаделью Адского Пламени на западе и Пылающим Легионом на востоке. Если внимание Легиона окажется привлечено к Темному порталу, то мы сумеем нанести удар оркам Цитадели Адского Пламени. Но для этого нужно атаковать бастионы цитадели!$B$BОтправляйся туда, убей тех, кто командует орками Скверны, а доказательства их смерти принеси Каса\'ресу.','Убейте начальника стражи Гарголмара, Омора Неодолимого и дракона Назана. Принесите руку Гарголмара, копыто Омора и голову Назана Каса\'ресу в Траллмар на Полуострове Адского Пламени.','После смерти военачальников в их рядах должно наступить смятение. $B$BНо убить нескольких стражей – это еще не все, $C.','$N, правильно? Сток\'тон сказал, чтобы я ожидал твоего доклада.$B$BНадеюсь, что ты $Gпринёс:принесла; хорошие новости?','Вернитесь к Каса\'ресу в Каньон Каменной Стены, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ослабить оборону валов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно торопиться, у нас мало очень времени. На карту поставлено само существование Траллмара!$B$BМы зажаты между Цитаделью Адского Пламени на западе и Пылающим Легионом на востоке. Если внимание Легиона окажется привлечено к Темному порталу, то мы сумеем нанести удар оркам Цитадели Адского Пламени. Но для этого нужно атаковать бастионы цитадели!$B$BОтправляйся туда, убей тех, кто командует орками Скверны, а доказательства их смерти принеси Каса\'ресу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте начальника стражи Гарголмара, Омора Неодолимого и дракона Назана. Принесите руку Гарголмара, копыто Омора и голову Назана Каса\'ресу в Траллмар на Полуострове Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','После смерти военачальников в их рядах должно наступить смятение. $B$BНо убить нескольких стражей – это еще не все, $C.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, правильно? Сток\'тон сказал, чтобы я ожидал твоего доклада.$B$BНадеюсь, что ты $Gпринёс:принесла; хорошие новости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каса\'ресу в Каньон Каменной Стены, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9573,'Вождь Умуру','Я – Тихвой Младший, наследник рода. Как видишь, мои защитники выстроили ловушку для буйных диких совухов, нападающих на нас изнутри логова. Пока что нам удается удерживать их, но ни один из воинов не смог проникнуть внутрь. Если ты сумеешь пробраться туда и убить их главаря, у нас появится шанс нанести им решающий удар!$B$BОтыщи вождя Умуру и уничтожь его. Прикончи всех безумных диких совухов, которые тебе встретятся.','Убейте вождя Умуру и 9 безумных диких совухов.','Задание выполнено?','Вернитесь к Тихвою Младшему в логово клана Тихвой, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь Умуру',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я – Тихвой Младший, наследник рода. Как видишь, мои защитники выстроили ловушку для буйных диких совухов, нападающих на нас изнутри логова. Пока что нам удается удерживать их, но ни один из воинов не смог проникнуть внутрь. Если ты сумеешь пробраться туда и убить их главаря, у нас появится шанс нанести им решающий удар!$B$BОтыщи вождя Умуру и уничтожь его. Прикончи всех безумных диких совухов, которые тебе встретятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте вождя Умуру и 9 безумных диких совухов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Задание выполнено?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тихвою Младшему в логово клана Тихвой, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9574,'Отравленные скверной','С нашим прибытием жизнь на острове Кровавой Дымки изменилась навсегда. Обломки от падения "Экзодара" разбросаны по всему острову – боюсь, это оказывает скверное влияние на здешнюю природу.$B$BОднако прежде чем делать окончательные выводы, мне хотелось бы получить некоторые данные. Похоже, в первую очередь действие кристаллов сказалось на деревьях; вероятно, у древней должны проявляться ярко выраженные симптомы заражения... Думаю, я смогу начать углубленные исследования, если ты принесешь мне образцы коры оскверненных древней.','Принесите на Кровавую заставу 6 кусков коры, покрытой кристаллами, и отдайте Морэ.','Ну как, удалось тебе найти нужные образцы?','Вернитесь к Морэ на Кровавую заставу, что на острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отравленные скверной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С нашим прибытием жизнь на острове Кровавой Дымки изменилась навсегда. Обломки от падения "Экзодара" разбросаны по всему острову – боюсь, это оказывает скверное влияние на здешнюю природу.$B$BОднако прежде чем делать окончательные выводы, мне хотелось бы получить некоторые данные. Похоже, в первую очередь действие кристаллов сказалось на деревьях; вероятно, у древней должны проявляться ярко выраженные симптомы заражения... Думаю, я смогу начать углубленные исследования, если ты принесешь мне образцы коры оскверненных древней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите на Кровавую заставу 6 кусков коры, покрытой кристаллами, и отдайте Морэ.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось тебе найти нужные образцы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морэ на Кровавую заставу, что на острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9575,'Ослабить оборону валов','Нужно торопиться, у нас очень мало времени. На карту поставлено само существование Оплота Чести!$B$BМы зажаты между Цитаделью Адского Пламени на западе и Пылающим Легионом на востоке. Если внимание Легиона будет привлечено к Темному порталу, то мы сумеем нанести удар оркам Цитадели Адского Пламени. Но для этого нужно атаковать бастионы цитадели!$B$BОтправляйся туда, убей тех, кто командует орками Скверны, а доказательства их смерти принеси Пушкаренку.','Убейте начальника стражи Гарголмара, Омора Неодолимого и дракона Назана. Принесите руку Гарголмара, копыто Омора и голову Назана Пушкаренку в Оплот Чести на Полуострове Адского Пламени.','Знаешь, что я ненавижу больше, чем ошибаться? Проигрывать деньги. Я поспорил, что ты не справишься с заданием, дорогуша.$b$bНеплохое начало. Смерть командиров внесет панику в их ряды. Обезвредив их артиллерию, мы получим достаточно времени, чтобы подобраться к самой цитадели.$B$BНо орков по-прежнему больше, чем может охватить глаз, так что жди нового задания.$B$BНо пока я тобой доволен. Можешь выбрать в оружейной, что захочешь.','Вернитесь к Пушкаренку на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ослабить оборону валов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно торопиться, у нас очень мало времени. На карту поставлено само существование Оплота Чести!$B$BМы зажаты между Цитаделью Адского Пламени на западе и Пылающим Легионом на востоке. Если внимание Легиона будет привлечено к Темному порталу, то мы сумеем нанести удар оркам Цитадели Адского Пламени. Но для этого нужно атаковать бастионы цитадели!$B$BОтправляйся туда, убей тех, кто командует орками Скверны, а доказательства их смерти принеси Пушкаренку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте начальника стражи Гарголмара, Омора Неодолимого и дракона Назана. Принесите руку Гарголмара, копыто Омора и голову Назана Пушкаренку в Оплот Чести на Полуострове Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Знаешь, что я ненавижу больше, чем ошибаться? Проигрывать деньги. Я поспорил, что ты не справишься с заданием, дорогуша.$b$bНеплохое начало. Смерть командиров внесет панику в их ряды. Обезвредив их артиллерию, мы получим достаточно времени, чтобы подобраться к самой цитадели.$B$BНо орков по-прежнему больше, чем может охватить глаз, так что жди нового задания.$B$BНо пока я тобой доволен. Можешь выбрать в оружейной, что захочешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пушкаренку на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9576,'Ожерелье Жестокого Плавника','Грубо сработанная подвеска украшена слабо светящимся кристаллом. Хотя его пульсирующий свет еле виден, от кристалла исходит отчетливое ощущение угрозы.$B$BЧто могло заставить Жестого Плавника создать эту подвеску?.. Как бы то ни было, эта вещь кажется слишком важной, чтобы не придавать ей значения. Необходимо показать ее кому-нибудь на Кровавой заставе.','Покажите подвеску Красного Кристалла Морэ на Кровавой заставе.','Что это у тебя?..') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожерелье Жестокого Плавника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грубо сработанная подвеска украшена слабо светящимся кристаллом. Хотя его пульсирующий свет еле виден, от кристалла исходит отчетливое ощущение угрозы.$B$BЧто могло заставить Жестого Плавника создать эту подвеску?.. Как бы то ни было, эта вещь кажется слишком важной, чтобы не придавать ей значения. Необходимо показать ее кому-нибудь на Кровавой заставе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите подвеску Красного Кристалла Морэ на Кровавой заставе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?..',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9577,'DAILY TEST QUEST (PVP)','<NYI>Ищите <QUESTGIVER> в <LOCATION>. Она/он желает, чтобы вы помогли им в трудном деле.','Поговорите с <QUESTGIVER> в <AREA>.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DAILY TEST QUEST (PVP)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<NYI>Ищите <QUESTGIVER> в <LOCATION>. Она/он желает, чтобы вы помогли им в трудном деле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с <QUESTGIVER> в <AREA>.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9578,'В поисках Галена','Скажи, $n, часто ли ты вспоминаешь свою семью?.. На "Экзодаре" было много семей, но я почти не слышала о таких, которым удалось воссоединиться.$B$BСама я пытаюсь найти хоть какие-то следы моего мужа, Галена, который работал техником в криогенном блоке. Обломки криогенного блока находятся к западу отсюда, и там тьма тьмущая эльфов крови!$B$BНо я обязана выяснить, что случилось с Галеном! Даже весть о его смерти будет лучше этой страшной неизвестности! Вот смотри: видишь эту подвеску? У моего мужа точно такая же – их нам подарила моя сестра.','Найдите Галена, мужа Морэ.','На трупе одежда экзодарских техников, но подвески, о которой говорила Морэ, нет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Галена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скажи, $n, часто ли ты вспоминаешь свою семью?.. На "Экзодаре" было много семей, но я почти не слышала о таких, которым удалось воссоединиться.$B$BСама я пытаюсь найти хоть какие-то следы моего мужа, Галена, который работал техником в криогенном блоке. Обломки криогенного блока находятся к западу отсюда, и там тьма тьмущая эльфов крови!$B$BНо я обязана выяснить, что случилось с Галеном! Даже весть о его смерти будет лучше этой страшной неизвестности! Вот смотри: видишь эту подвеску? У моего мужа точно такая же – их нам подарила моя сестра.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Галена, мужа Морэ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На трупе одежда экзодарских техников, но подвески, о которой говорила Морэ, нет.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9579,'Судьба Галена','По рассказу Морэ невозможно опознать тело; однако заметно, что его одежду разорвали, когда обыскивали труп в поисках ценностей.$B$BЭльфы крови, живущие в этих местах, несомненно, забрали бы все мало-мальски ценное, тем более драгоценный амулет Галена.$B$BКонечно, то, что Гален погиб при крушении, станет для Морэ тяжелым ударом. Но возможно, ей будет немного легче, если удастся отобрать у эльфов крови амулет ее супруга...','Принесите на Кровавую заставу амулет Галена и отдайте его Морэ.','Вернитесь к Морэ на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Галена',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','По рассказу Морэ невозможно опознать тело; однако заметно, что его одежду разорвали, когда обыскивали труп в поисках ценностей.$B$BЭльфы крови, живущие в этих местах, несомненно, забрали бы все мало-мальски ценное, тем более драгоценный амулет Галена.$B$BКонечно, то, что Гален погиб при крушении, станет для Морэ тяжелым ударом. Но возможно, ей будет немного легче, если удастся отобрать у эльфов крови амулет ее супруга...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите на Кровавую заставу амулет Галена и отдайте его Морэ.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морэ на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9580,'Вскормленные медвежатиной','Полагаю, за время, проведенное на острове Кровавой Дымки, ты $Gуспел:успела; понять, что после нашего прибытия все здесь переменилось. Однако мой опыт свидетельствует о том, что натуральные продукты можно использовать всегда – даже если их источником является природа, подобная здешней.$B$BРесурсов у нас мало, так что приходится полагаться исключительно на собственные умения. Я вот поставляю в лавки медвежье мясо – знаешь ведь, на острове медведей немало; а если мясо готовить, соблюдая некоторые предосторожности, оно вполне съедобно. Так вот, я тут подумал: ты все равно бродишь по всему острову – может, если тебе по дороге попадется пара медведей, поможешь нам с припасами?','Принесите зверолову Лисеону на Кровавую заставу 8 кусков мяса с боков старых бурых медведей.','Вернитесь к зверолову Лисеону на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вскормленные медвежатиной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полагаю, за время, проведенное на острове Кровавой Дымки, ты $Gуспел:успела; понять, что после нашего прибытия все здесь переменилось. Однако мой опыт свидетельствует о том, что натуральные продукты можно использовать всегда – даже если их источником является природа, подобная здешней.$B$BРесурсов у нас мало, так что приходится полагаться исключительно на собственные умения. Я вот поставляю в лавки медвежье мясо – знаешь ведь, на острове медведей немало; а если мясо готовить, соблюдая некоторые предосторожности, оно вполне съедобно. Так вот, я тут подумал: ты все равно бродишь по всему острову – может, если тебе по дороге попадется пара медведей, поможешь нам с припасами?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите зверолову Лисеону на Кровавую заставу 8 кусков мяса с боков старых бурых медведей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к зверолову Лисеону на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9581,'Изучение кристаллов','Добро пожаловать на Кровавую заставу, |3-6($c). Конечно, основная моя задача – защита заставы, но наши вожди в Экзодаре возложили на меня и другие обязанности.$B$BПроблема в том, что на острове слишком опасно – а мы не можем рисковать нашими исследователями, посылая их на смерть. Но при этом мне нужно добыть образцы кристаллов из разных районов острова. Понимаешь, к чему я веду?$B$BПервый образец – из тех, что мне нужны, – можно найти в обломках корабля к югу отсюда. Он недалеко, только мост перейти... правда, как я слышал, в тех местах водится множество опустошителей...','Добудьте образец кристалла с места крушения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте предвестнику Миколаасу.','Этот осколок кристалла даст нашим исследователям базу для сравнения – он принесен из той части острова, которую не так сильно затронула скверна.$B$BОднако же пока не имеет смысла посылать образец в Экзодар – сначала нам нужно собрать полный набор кристаллов. Начало, безусловно, положено. Поверь, если ты поможешь мне и в остальном, я сам прослежу за тем, чтобы твои усилия были вознаграждены.','Ну как, удалось тебе раздобыть первый образец кристалла?','Вернитесь к предвестнику Миколаасу на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Изучение кристаллов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать на Кровавую заставу, |3-6($c). Конечно, основная моя задача – защита заставы, но наши вожди в Экзодаре возложили на меня и другие обязанности.$B$BПроблема в том, что на острове слишком опасно – а мы не можем рисковать нашими исследователями, посылая их на смерть. Но при этом мне нужно добыть образцы кристаллов из разных районов острова. Понимаешь, к чему я веду?$B$BПервый образец – из тех, что мне нужны, – можно найти в обломках корабля к югу отсюда. Он недалеко, только мост перейти... правда, как я слышал, в тех местах водится множество опустошителей...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте образец кристалла с места крушения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте предвестнику Миколаасу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот осколок кристалла даст нашим исследователям базу для сравнения – он принесен из той части острова, которую не так сильно затронула скверна.$B$BОднако же пока не имеет смысла посылать образец в Экзодар – сначала нам нужно собрать полный набор кристаллов. Начало, безусловно, положено. Поверь, если ты поможешь мне и в остальном, я сам прослежу за тем, чтобы твои усилия были вознаграждены.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось тебе раздобыть первый образец кристалла?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Миколаасу на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9582,'Силой единой','Когда наш корабль разбился, весь зверинец разметало по северо-восточному побережью. Мне дали ключ от клетки одного из наиболее страшных зверей, смертоносного опустошителя. Панцирь у этой твари не очень прочный, зато на нее почти не действуют заклинания. Ее нужно убить простым клинком.$B$BВозьми этот ключ и избавь опустошителя от плена и страданий. Не допусти, чтобы он сбежал и причинил еще больший вред окружающей среде.','Откройте клетку смертоносного опустошителя, убейте его и вернитесь к Руаде на Лазурную заставу на острове Лазурной Дымки.','<Руада торжественно кивает.>$B$BТогда это сделано. $B$BТы $Gготов:готова; к следующему уроку, $N, но я не буду тем, кто научит тебя этому.','Ты $Gопустил:отпустила; зверя?','Вернитесь к Руаде на Лазурную заставу, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силой единой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда наш корабль разбился, весь зверинец разметало по северо-восточному побережью. Мне дали ключ от клетки одного из наиболее страшных зверей, смертоносного опустошителя. Панцирь у этой твари не очень прочный, зато на нее почти не действуют заклинания. Ее нужно убить простым клинком.$B$BВозьми этот ключ и избавь опустошителя от плена и страданий. Не допусти, чтобы он сбежал и причинил еще больший вред окружающей среде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Откройте клетку смертоносного опустошителя, убейте его и вернитесь к Руаде на Лазурную заставу на острове Лазурной Дымки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Руада торжественно кивает.>$B$BТогда это сделано. $B$BТы $Gготов:готова; к следующему уроку, $N, но я не буду тем, кто научит тебя этому.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gопустил:отпустила; зверя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руаде на Лазурную заставу, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9583,'Благородная душа жертвует мне ткань.','Принесите Омару ткани.','Вернитесь к тестовому дракону на Остров Программиста.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благородная душа жертвует мне ткань.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Омару ткани.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тестовому дракону на Остров Программиста.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9584,'Второй образец','Теперь, когда у нас есть первый кристалл, нам понадобятся другие образцы, которые я мог бы отправить в Экзодар. Увы, там, где можно раздобыть эти кристаллы, тебя поджидает еще большая опасность, чем прежде...$B$BВторой образец ты сможешь найти в лесу Клинков, к северо-западу от Кровавой заставы. Правда, в этом лесу обосновались эльфы крови... Попытайся найти кристалл, который они еще не успели прибрать к рукам и использовать в своих целях, и отколи от него образец.','Добудьте образец кристалла с места столкновения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте его предвестнику Миколаасу.','Ты $Gсумел:сумела; добыть второй образец кристалла? Он у тебя с собой?','Вернитесь к предвестнику Миколаасу на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второй образец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у нас есть первый кристалл, нам понадобятся другие образцы, которые я мог бы отправить в Экзодар. Увы, там, где можно раздобыть эти кристаллы, тебя поджидает еще большая опасность, чем прежде...$B$BВторой образец ты сможешь найти в лесу Клинков, к северо-западу от Кровавой заставы. Правда, в этом лесу обосновались эльфы крови... Попытайся найти кристалл, который они еще не успели прибрать к рукам и использовать в своих целях, и отколи от него образец.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте образец кристалла с места столкновения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте его предвестнику Миколаасу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсумел:сумела; добыть второй образец кристалла? Он у тебя с собой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Миколаасу на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9585,'Последний образчик','Остался всего один образец, и я смогу отправить эти кристаллы в Экзодар. Послушай, $n: последний кристалл нужно добыть в Аксариене, оплоте сатиров – а он находится к северо-западу отсюда.$B$BНе знаю, чего можно ждать от этого кристалла, но уверен, что обнаружу в нем следы скверны. Помнишь кристаллы, от которых были отколоты предыдущие образцы? Тебе нужно найти такие же, иначе наши исследователи не смогут провести сравнительный анализ.','Добудьте образец кристалла с места столкновения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте предвестнику Миколаасу.','Ну, где последний образец для моего драгоценного набора?','Вернитесь к предвестнику Миколаасу на Остров Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последний образчик',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Остался всего один образец, и я смогу отправить эти кристаллы в Экзодар. Послушай, $n: последний кристалл нужно добыть в Аксариене, оплоте сатиров – а он находится к северо-западу отсюда.$B$BНе знаю, чего можно ждать от этого кристалла, но уверен, что обнаружу в нем следы скверны. Помнишь кристаллы, от которых были отколоты предыдущие образцы? Тебе нужно найти такие же, иначе наши исследователи не смогут провести сравнительный анализ.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте образец кристалла с места столкновения, отколов фрагмент кайлом для добычи кристаллов. Принесите образец на Кровавую заставу и отдайте предвестнику Миколаасу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, где последний образец для моего драгоценного набора?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Миколаасу на Остров Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9586,'Помощь Таваре','Тавара, одна из наших травниц, решила пополнить свои запасы и ушла в лес. Ее давно не видно – боюсь, бедняга нуждается в помощи. Я сам не могу пойти на поиски.$B$BПрошу тебя, |3-6($c), найди ее и исцели, если нужно. Она вышла из Лазурной заставы и направилась на восток, в сторону горячих источников.','Найдите Тавару и исцелите ее раны.','Спасибо тебе за помощь Таваре. Многие из нас не знакомы с этими землями, поэтому неприятности могут поджидать нас там, где меньше всего этого ожидаешь. $B$BДля меня было бы честью, если бы ты $Gносил:носила; эти одеяния. Они отметят тебя как $Gодного:одну; из $Gзащитников:защитниц; Лазурной заставы и $Gпреданного:преданной; $Gпоследователя:последовательницы; Света.','Ну, где последний образец для моего драгоценного набора?','Вернитесь к Гувану на Лазурную заставу, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Таваре',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тавара, одна из наших травниц, решила пополнить свои запасы и ушла в лес. Ее давно не видно – боюсь, бедняга нуждается в помощи. Я сам не могу пойти на поиски.$B$BПрошу тебя, |3-6($c), найди ее и исцели, если нужно. Она вышла из Лазурной заставы и направилась на восток, в сторону горячих источников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Тавару и исцелите ее раны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе за помощь Таваре. Многие из нас не знакомы с этими землями, поэтому неприятности могут поджидать нас там, где меньше всего этого ожидаешь. $B$BДля меня было бы честью, если бы ты $Gносил:носила; эти одеяния. Они отметят тебя как $Gодного:одну; из $Gзащитников:защитниц; Лазурной заставы и $Gпреданного:преданной; $Gпоследователя:последовательницы; Света.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, где последний образец для моего драгоценного набора?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гувану на Лазурную заставу, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9587,'Темные вести','Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква "И". Взломав печать, вы с волнением заглядываете в письмо.$B$BПоложительно, его должен прочесть Данат Троллебой!','Доставьте угрожающее письмо командиру армии Данату Троллебою в Оплот Чести на Полуострове Адского Пламени.','Ну, что у нас тут, $gпарень:мэм;?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква "И". Взломав печать, вы с волнением заглядываете в письмо.$B$BПоложительно, его должен прочесть Данат Троллебой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте угрожающее письмо командиру армии Данату Троллебою в Оплот Чести на Полуострове Адского Пламени.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что у нас тут, $gпарень:мэм;?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9588,'Темные вести','Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква "И". Взломав печать, вы с волнением заглядываете в письмо.$B$BПоложительно, его надо доставить Назгрелу в Траллмар!','Доставьте угрожающее письмо Назгрелу в Траллмар на Полуострове Адского Пламени.','Ты говоришь, это подписано Иллиданом ?! Дай мне это. $B$B<Назгрел читает письмо, а затем снова во второй раз, подумав, прежде чем продолжить.>$B$BЭта новость, которую ты $Gпринес:принесла;, действительно зловещая. Зная это, мы должны ускорить наши планы против Цитадели Адского Пламени и этой Кузни Крови. Поскольку ты $Gпоказал:показала;, что можешь выполнить работу, я хочу, чтобы ты $Gвозглавил:возглавила; эти планы!$B$BЦентурион Казарес даст тебе следующую миссию, хотя я подозреваю, что она будет гораздо опаснее, чем первая. $B$BЛок\'тар огар, $N!','Что это за письмо, $C?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темные вести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быстро осмотрев безжизненного Вазрудена Глашатая, вы обнаруживаете свернутое письмо с уцелевшей печатью. На печати красной тушью оттиснута причудливо нарисованная буква "И". Взломав печать, вы с волнением заглядываете в письмо.$B$BПоложительно, его надо доставить Назгрелу в Траллмар!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте угрожающее письмо Назгрелу в Траллмар на Полуострове Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты говоришь, это подписано Иллиданом ?! Дай мне это. $B$B<Назгрел читает письмо, а затем снова во второй раз, подумав, прежде чем продолжить.>$B$BЭта новость, которую ты $Gпринес:принесла;, действительно зловещая. Зная это, мы должны ускорить наши планы против Цитадели Адского Пламени и этой Кузни Крови. Поскольку ты $Gпоказал:показала;, что можешь выполнить работу, я хочу, чтобы ты $Gвозглавил:возглавила; эти планы!$B$BЦентурион Казарес даст тебе следующую миссию, хотя я подозреваю, что она будет гораздо опаснее, чем первая. $B$BЛок\'тар огар, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это за письмо, $C?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9589,'Кровь есть жизнь','Это письмо всех поставит на уши. Если бы мы знали, как были созданы орки Скверны, то наверняка бы придумали, как с ними справиться. Будто бы нам было недостаточно Пылающего Легиона на востоке.$B$BТак что нам крупно повезло, моя радость! Тебе придется прогуляться к так называемой Кузне Крови, в Цитадель Адского Пламени. Так сказать, в самое пекло.$B$BСтупай, поубивай орков Скверны и добудь образцы их крови.$B$BНадеюсь, ты справишься.','Принесите 10 фиалов крови орков Скверны Пушкаренку в Оплот Чести на Полуострове Адского Пламени.','Не хрена себе, сказал я себе! На данный момент ты $gмой самый любимый:моя самая любимая; штатская штафирка из всех жалких штафирок этого жалкого мира.$B$BКлянусь, яйцеголовые выпрыгнут из штанов от радости, когда я выложу перед ними образцы крови. Кто знает, может, мы обнаружим новый способ борьбы с проклятыми скверноорками?','Где кровь, дорогуша? Если тебе приказали ее добыть, то это должно быть очень важно, как ты думаешь?','Вернитесь к Пушкаренку на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь есть жизнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это письмо всех поставит на уши. Если бы мы знали, как были созданы орки Скверны, то наверняка бы придумали, как с ними справиться. Будто бы нам было недостаточно Пылающего Легиона на востоке.$B$BТак что нам крупно повезло, моя радость! Тебе придется прогуляться к так называемой Кузне Крови, в Цитадель Адского Пламени. Так сказать, в самое пекло.$B$BСтупай, поубивай орков Скверны и добудь образцы их крови.$B$BНадеюсь, ты справишься.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 фиалов крови орков Скверны Пушкаренку в Оплот Чести на Полуострове Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не хрена себе, сказал я себе! На данный момент ты $gмой самый любимый:моя самая любимая; штатская штафирка из всех жалких штафирок этого жалкого мира.$B$BКлянусь, яйцеголовые выпрыгнут из штанов от радости, когда я выложу перед ними образцы крови. Кто знает, может, мы обнаружим новый способ борьбы с проклятыми скверноорками?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где кровь, дорогуша? Если тебе приказали ее добыть, то это должно быть очень важно, как ты думаешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пушкаренку на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9590,'Кровь есть жизнь','Это письмо меня беспокоит, но вовсе не потому, что его написал Предатель. Если мы будем знать, как были созданы орки Скверны, то сумеем победить их! Мало нам атак Легиона с запада, так теперь еще с востока эти проклятые орки!$B$BТы $gдолжен:должна; пробраться в Кузню Крови в Цитадели Адского Пламени. Убей орков Скверны, которые тебе попадутся, и принеси мне образцы их крови.','Принесите 10 фиалов крови орков Скверны центуриону Каса\'ресу в Траллмар на Полуострове Адского Пламени.','Я впечатлен твоими способностями, $N. Не один раз, а дважды ты $Gпроникал:проникала; в Цитадель Адского Пламени и $Gвыполнял:выполняла; то, о чем тебя просили. $B$BЯ прослежу, чтобы эта кровь была доставлена ​​тем, кто сможет раскрыть ее тайны. Кто знает, возможно, мы сможем повернуть вспять этот процесс?','Неужели вы так быстро собрали всю кровь?','Вернитесь к Каcа\'ресу в Каньон Каменной Стены, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь есть жизнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это письмо меня беспокоит, но вовсе не потому, что его написал Предатель. Если мы будем знать, как были созданы орки Скверны, то сумеем победить их! Мало нам атак Легиона с запада, так теперь еще с востока эти проклятые орки!$B$BТы $gдолжен:должна; пробраться в Кузню Крови в Цитадели Адского Пламени. Убей орков Скверны, которые тебе попадутся, и принеси мне образцы их крови.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 фиалов крови орков Скверны центуриону Каса\'ресу в Траллмар на Полуострове Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я впечатлен твоими способностями, $N. Не один раз, а дважды ты $Gпроникал:проникала; в Цитадель Адского Пламени и $Gвыполнял:выполняла; то, о чем тебя просили. $B$BЯ прослежу, чтобы эта кровь была доставлена ​​тем, кто сможет раскрыть ее тайны. Кто знает, возможно, мы сможем повернуть вспять этот процесс?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели вы так быстро собрали всю кровь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каcа\'ресу в Каньон Каменной Стены, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9591,'Приручение зверя','Когда |3-6($c) избирает свой путь, $gего:ее; учат лишь убивать. Мне кажется, тебе пора сделать следующий шаг.$B$BФурболги племени Тихвой придумали, как можно приручить зверя, не тратя на это долгие месяцы. Они вырезают тотем в форме определенного животного, и он позволяет установить временную связь с существами этого вида.$B$BНачнем первый урок. Возьми этот тотем и приручи при его помощи одного из колючих крабов на западном побережье острова.','Используйте тотем приручения и приручите колючего краба. Вернитесь к охотнице Келле Тетиве Ночи.','Я уверен, что первое, что ты $Gузнал:узнала;, было то, насколько неприятным был процесс связывания.','Удалось тебе использовать магию тотема, чтобы подружиться с колючим крабом? Эти существа очень злые!','Приручение колючего краба','Вернитесь к охотнице Келле Тетиве Ночи на остров Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда |3-6($c) избирает свой путь, $gего:ее; учат лишь убивать. Мне кажется, тебе пора сделать следующий шаг.$B$BФурболги племени Тихвой придумали, как можно приручить зверя, не тратя на это долгие месяцы. Они вырезают тотем в форме определенного животного, и он позволяет установить временную связь с существами этого вида.$B$BНачнем первый урок. Возьми этот тотем и приручи при его помощи одного из колючих крабов на западном побережье острова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте тотем приручения и приручите колючего краба. Вернитесь к охотнице Келле Тетиве Ночи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уверен, что первое, что ты $Gузнал:узнала;, было то, насколько неприятным был процесс связывания.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось тебе использовать магию тотема, чтобы подружиться с колючим крабом? Эти существа очень злые!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручение колючего краба',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнице Келле Тетиве Ночи на остров Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9592,'Приручение зверя','Крабы, конечно, злобные твари, но лесоног – гораздо более сложное испытание. Чем сильнее будущий союзник, тем больше стойкости требуется от охотника во время приручения.$B$BВозьми этот тотем приручения и приручи большого лесонога. Их можно найти на севере острова Лазурной Дымки.','Используйте тотем приручения и приручите большого лесонога, после чего вернитесь к охотнице Келле Тетиве Ночи.','Похоже, лесовоз не выклевывал вам глаза. $B$B<Келла на мгновение отводит взгляд.>$B$BНе то чтобы я, конечно, думал, что это произойдет!','Лесонога - могущественная птица, хищники часто ее недооценивают, что приводит к ужасным результатам.','Приручение большого лесонога.','Вернитесь к охотнице Келле Тетиве Ночи на остров Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Крабы, конечно, злобные твари, но лесоног – гораздо более сложное испытание. Чем сильнее будущий союзник, тем больше стойкости требуется от охотника во время приручения.$B$BВозьми этот тотем приручения и приручи большого лесонога. Их можно найти на севере острова Лазурной Дымки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте тотем приручения и приручите большого лесонога, после чего вернитесь к охотнице Келле Тетиве Ночи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, лесовоз не выклевывал вам глаза. $B$B<Келла на мгновение отводит взгляд.>$B$BНе то чтобы я, конечно, думал, что это произойдет!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лесонога - могущественная птица, хищники часто ее недооценивают, что приводит к ужасным результатам.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручение большого лесонога.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнице Келле Тетиве Ночи на остров Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9593,'Приручение зверя','Во время приручения большого лесонога ты, должно быть, $gзаметил:заметила; огромных кошек, зовущихся ночными ловцами. Эти хищники смертельно опасны... но и союзники из них превосходные.$b$bПриручи ночного ловца при помощи тотема приручения, отправляйся с ним на охоту и береги его. Как закончишь – возвращайся ко мне.','Используйте тотем приручения и приручите ночного ловца. Вернитесь к охотнице Келле Тетиве Ночи.','Должен сказать, $N, вы познали это гораздо быстрее, чем я предполагал. Похоже, нам не понадобится этот последний тотем приручения. И, честно говоря, я даже не уверен, что это такое. Похоже, это какая-то чудовищная ящерица с крыльями и длинным хвостом. Ну ладно, может в другой раз!$B$BУ вас достаточно опыта, чтобы попробовать это самостоятельно, без помощи тотема приручения. Удачи!','Ночной ловец - большой котенок с острыми, как бритва когтями и огромной жаждой мяса...','Приручение ночного ловца','Вернитесь к охотнице Келле Тетиве Ночи на остров Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приручение зверя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время приручения большого лесонога ты, должно быть, $gзаметил:заметила; огромных кошек, зовущихся ночными ловцами. Эти хищники смертельно опасны... но и союзники из них превосходные.$b$bПриручи ночного ловца при помощи тотема приручения, отправляйся с ним на охоту и береги его. Как закончишь – возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте тотем приручения и приручите ночного ловца. Вернитесь к охотнице Келле Тетиве Ночи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Должен сказать, $N, вы познали это гораздо быстрее, чем я предполагал. Похоже, нам не понадобится этот последний тотем приручения. И, честно говоря, я даже не уверен, что это такое. Похоже, это какая-то чудовищная ящерица с крыльями и длинным хвостом. Ну ладно, может в другой раз!$B$BУ вас достаточно опыта, чтобы попробовать это самостоятельно, без помощи тотема приручения. Удачи!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ночной ловец - большой котенок с острыми, как бритва когтями и огромной жаждой мяса...',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Приручение ночного ловца',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнице Келле Тетиве Ночи на остров Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9594,'Знаки Легиона','Убейте 8 сатиров из племени Наззивус и 8 скверноподданных из племени Наззивус, а затем отнесите латный доспех Тзерака воздаятельнице Алезии на Кровавую заставу.','Хорошо, что ты $Gпринес:принесла; мне эту броню, $N. Вне всякого сомнения, это часть доспехов солдата Пылающего Легиона. $B$BКак я и опасалась, сатиры племени Наззивус снова наладили связь с Легионом. Если их не остановить, сатиры и их союзники-демоны уничтожат нас. Я должна немедленно сообщить обо всем предвестнику Миколаасу!','Да, |3-6($C)? Что это у тебя?','Вернитесь к воздаятельнице Алезии на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Легиона',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 сатиров из племени Наззивус и 8 скверноподданных из племени Наззивус, а затем отнесите латный доспех Тзерака воздаятельнице Алезии на Кровавую заставу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты $Gпринес:принесла; мне эту броню, $N. Вне всякого сомнения, это часть доспехов солдата Пылающего Легиона. $B$BКак я и опасалась, сатиры племени Наззивус снова наладили связь с Легионом. Если их не остановить, сатиры и их союзники-демоны уничтожат нас. Я должна немедленно сообщить обо всем предвестнику Миколаасу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, |3-6($C)? Что это у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятельнице Алезии на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9595,'Самоконтроль','Каждым заклинанием ты $Gдолжен:должна; закалять себя против такой соблазнительной приманки магии, используя ее только по мере необходимости для целей добра. Надеюсь, духи дали представление о том, во что ты можешь превратиться, если станешь $Gнеосторожным:неосторожной;... $Gбезмозглым:безмозглой; $Gрабом:рабыней; магии.','Ты $Gстолкнулся:столкнулась; со своими кошмары?','Вернитесь к Бати в Чертог Света, что в Экзодаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самоконтроль',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Каждым заклинанием ты $Gдолжен:должна; закалять себя против такой соблазнительной приманки магии, используя ее только по мере необходимости для целей добра. Надеюсь, духи дали представление о том, во что ты можешь превратиться, если станешь $Gнеосторожным:неосторожной;... $Gбезмозглым:безмозглой; $Gрабом:рабыней; магии.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gстолкнулся:столкнулась; со своими кошмары?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бати в Чертог Света, что в Экзодаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9596,'<DEPRECATED>Контроль','<NYI>Сделай что-нибудь, |3-6($c)!','<NYI>Запись в дневнике.','Вернитесь к Джонатану Лекрафту на Остров Дизайнера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<DEPRECATED>Контроль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<NYI>Сделай что-нибудь, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','<NYI>Запись в дневнике.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джонатану Лекрафту на Остров Дизайнера.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9597,'<UNUSED>','<NYI>Hey little man, do something worthy and talk to Jonathan LeCraft.','<NYI>Запись в дневнике.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<NYI>Hey little man, do something worthy and talk to Jonathan LeCraft.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','<NYI>Запись в дневнике.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9598,'Искупление','Я – наставница паладинов. Я та, кто ведет их стезей добродетели к Истинному Свету, дабы они защищали наш народ от любой угрозы.$B$BИ для тебя пришло время сделать первый шаг на пути праведности. Если ты решишься принять этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, чего от тебя ожидают. Постигнув мудрость, заключенную в этой книге, ты откроешь в себе новые, удивительные способности.','Прочтите Фолиант Божественности и поговорите с Джоль.','Надеюсь, ты все это время $Gизучал:изучала; фолиант?$B$BВ таком случае ты $Gдолжен:должна; быть $Gготов:готова; к испытанию. После крушения "Экзодара" в этих новых землях много дел для таких, как мы: всегда есть те, кто нуждается в помощи, сострадании и понимании; всегда есть враждебные твари, которых необходимо уничтожать...$B$BДоказав, что ты обладаешь достаточным терпением, чтобы помогать ближним, ты тем самым покажешь, что твои помыслы чисты и что ты воистину служишь Свету.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искупление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я – наставница паладинов. Я та, кто ведет их стезей добродетели к Истинному Свету, дабы они защищали наш народ от любой угрозы.$B$BИ для тебя пришло время сделать первый шаг на пути праведности. Если ты решишься принять этот путь, я дам тебе Фолиант Божественности. Изучая его, ты узнаешь кое-что о Свете и о том, чего от тебя ожидают. Постигнув мудрость, заключенную в этой книге, ты откроешь в себе новые, удивительные способности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прочтите Фолиант Божественности и поговорите с Джоль.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, ты все это время $Gизучал:изучала; фолиант?$B$BВ таком случае ты $Gдолжен:должна; быть $Gготов:готова; к испытанию. После крушения "Экзодара" в этих новых землях много дел для таких, как мы: всегда есть те, кто нуждается в помощи, сострадании и понимании; всегда есть враждебные твари, которых необходимо уничтожать...$B$BДоказав, что ты обладаешь достаточным терпением, чтобы помогать ближним, ты тем самым покажешь, что твои помыслы чисты и что ты воистину служишь Свету.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9599,'<UNUSED>','In all things, paladins must reflect the Light, which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.$B$BAlthough called upon to smite evil in these harsh times, you must always remember that it\'s aiding others that will truly set you apart from the other citizens. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.$B$BKnow this well, and never forget it.','Speak with Jol in the Exodar.','Спасибо, $N! Я рад, что молодой фурболг-шаман в порядке. $B$BВы действительно благословлены Светом! Поэтому вы должны использовать его, чтобы вернуть свет во всех!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<UNUSED>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','In all things, paladins must reflect the Light, which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.$B$BAlthough called upon to smite evil in these harsh times, you must always remember that it\'s aiding others that will truly set you apart from the other citizens. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.$B$BKnow this well, and never forget it.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Speak with Jol in the Exodar.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, $N! Я рад, что молодой фурболг-шаман в порядке. $B$BВы действительно благословлены Светом! Поэтому вы должны использовать его, чтобы вернуть свет во всех!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9600,'Искупление','Итак, $n, твоя задача – помочь нашим новым союзникам, фурболгам из племени Тихвой.$B$BНесколько молодых шаманов племени Тихвой наткнулись на лагерь Косолапов и погибли, все до единого. Возьми этот знак Жизни и воскреси одного из шаманов.$B$BАнклав Косолапов находится к востоку от дороги, сразу за мостом, соединяющим острова Лазурной и Кровавой Дымки. Когда выполнишь задание, возвращайся ко мне.','Воскресите молодого фурболга-шамана из племени Тихвой при помощи знака Жизни, а затем вернитесь к Джоль.','Не стоит смущать души тех, кому тебе довелось помочь. Видишь ли, те, кто волею судьбы был возвращен в мир живущих, некоторое время обычно пребывают в растерянности. Думаю, потрясение от встречи с чужаком, да еще и непривычного вида, может оказаться слишком большим испытанием...$B$BБлагодаря тебе юный шаман сумел пережить это жестокое испытание; полагаю, ты вполне $Gдостоин:достойна; того, чтобы использовать силу священного Символа.','Любая жизнь священна, любой из живущих достоин спасения – конечно, если он на нашей стороне. А наши враги... Что ж, они заслужили вечный покой.','Вернитесь к Джоли в Чертог Света, что в Экзодаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искупление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, $n, твоя задача – помочь нашим новым союзникам, фурболгам из племени Тихвой.$B$BНесколько молодых шаманов племени Тихвой наткнулись на лагерь Косолапов и погибли, все до единого. Возьми этот знак Жизни и воскреси одного из шаманов.$B$BАнклав Косолапов находится к востоку от дороги, сразу за мостом, соединяющим острова Лазурной и Кровавой Дымки. Когда выполнишь задание, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воскресите молодого фурболга-шамана из племени Тихвой при помощи знака Жизни, а затем вернитесь к Джоль.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не стоит смущать души тех, кому тебе довелось помочь. Видишь ли, те, кто волею судьбы был возвращен в мир живущих, некоторое время обычно пребывают в растерянности. Думаю, потрясение от встречи с чужаком, да еще и непривычного вида, может оказаться слишком большим испытанием...$B$BБлагодаря тебе юный шаман сумел пережить это жестокое испытание; полагаю, ты вполне $Gдостоин:достойна; того, чтобы использовать силу священного Символа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Любая жизнь священна, любой из живущих достоин спасения – конечно, если он на нашей стороне. А наши враги... Что ж, они заслужили вечный покой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джоли в Чертог Света, что в Экзодаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9601,'В Бастион','С тобой желает поговорить рыцарь крови Мелар Клинок Рассвета. Мелара можно найти в Бастионе, он охраняет проход между Тирисфальскими лесами и Западными Чумными землями.$b$bТерпение – не его сильная сторона. Не советую заставлять его ждать.','Поговорите с Меларом Клинком Рассвета из Бастиона.','Ааа... похоже пора. $B$B<Мелар понимающе кивает.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Бастион',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С тобой желает поговорить рыцарь крови Мелар Клинок Рассвета. Мелара можно найти в Бастионе, он охраняет проход между Тирисфальскими лесами и Западными Чумными землями.$b$bТерпение – не его сильная сторона. Не советую заставлять его ждать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Меларом Клинком Рассвета из Бастиона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ааа... похоже пора. $B$B<Мелар понимающе кивает.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9602,'Избавь их от лукавого...','Сообщи об этом своему народу, $n. Хотя твои подвиги нарушили планы Кель\'таса и его темного властителя, негодяи не оставят попыток напасть на нас.$B$BОтнеси переписку предателя вождям своего народа. Они должны взглянуть на это своими глазами. Быть может, они лучше поймут, о чем здесь идет речь.','Отнесите переписку предателя экзарху Менелаусу на Лазурную заставу.','Ты $gвернулся:вернулась;!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Избавь их от лукавого...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сообщи об этом своему народу, $n. Хотя твои подвиги нарушили планы Кель\'таса и его темного властителя, негодяи не оставят попыток напасть на нас.$B$BОтнеси переписку предателя вождям своего народа. Они должны взглянуть на это своими глазами. Быть может, они лучше поймут, о чем здесь идет речь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите переписку предателя экзарху Менелаусу на Лазурную заставу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gвернулся:вернулась;!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9603,'Лежанки, лекарства и прочая ерунда','Добро пожаловать на Лазурную заставу, |3-6($c). Не обращай внимания на беспорядок. Все почему-то считают, что, как только напишешь на вывеске "Таверна", так внутри сразу сами собой образуются и мебель, и припасы, и все такое. А если таверна строится с нуля?..$B$BНам удалось приспособить под таверну одну из спасательных капсул; но пока тут нет мебели и запаса лекарств, это всего лишь шикарная палатка. Нургуни из Экзодара предложила собрать для меня кое-какие припасы – хотя бы то, что необходимо на первый случай, – но мне нужно, чтобы кто-нибудь отвез ей список...','Отвезите список Челланы на Лазурную заставу укротителю гиппогрифов Залдаану.','Итак, тебе нужно отправиться в Экзодар?$B$BПуть неблизкий – но ты не беспокойся, я знаю, как быстро доставить тебя туда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лежанки, лекарства и прочая ерунда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать на Лазурную заставу, |3-6($c). Не обращай внимания на беспорядок. Все почему-то считают, что, как только напишешь на вывеске "Таверна", так внутри сразу сами собой образуются и мебель, и припасы, и все такое. А если таверна строится с нуля?..$B$BНам удалось приспособить под таверну одну из спасательных капсул; но пока тут нет мебели и запаса лекарств, это всего лишь шикарная палатка. Нургуни из Экзодара предложила собрать для меня кое-какие припасы – хотя бы то, что необходимо на первый случай, – но мне нужно, чтобы кто-нибудь отвез ей список...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отвезите список Челланы на Лазурную заставу укротителю гиппогрифов Залдаану.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, тебе нужно отправиться в Экзодар?$B$BПуть неблизкий – но ты не беспокойся, я знаю, как быстро доставить тебя туда.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9604,'На крыльях гиппогрифа','За небольшую плату ты можешь взять одного из моих гиппогрифов, чтобы долететь до Экзодара.$B$BНет ничего быстрее и безопаснее гиппогрифа – в особенности для тех, кому необходимо доставить важное послание. Захочешь прокатиться – подходи, и мы обо всем договоримся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На крыльях гиппогрифа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За небольшую плату ты можешь взять одного из моих гиппогрифов, чтобы долететь до Экзодара.$B$BНет ничего быстрее и безопаснее гиппогрифа – в особенности для тех, кому необходимо доставить важное послание. Захочешь прокатиться – подходи, и мы обо всем договоримся.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9605,'Укротитель гиппогрифов Стефанос','А вот и ящичек, $n, держи. Думаю, тут есть все, что нужно Челлане, чтобы дела в таверне пошли на лад. Передай ей, что она без стеснения может заказывать все необходимое. Лазурной заставе срочно требуется помещение, где можно было бы ухаживать за ранеными, а также место, где путешественники смогут восстановить свои силы.$B$BКогда будешь $Gготов:готова; вернуться на Лазурную заставу, найди сначала Стефаноса – он обычно бывает у трона наару, что в Экзодаре.','Найдите Стефаноса у трона наару, что в Экзодаре, и наймите гиппогрифа для возвращения на Лазурную заставу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укротитель гиппогрифов Стефанос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А вот и ящичек, $n, держи. Думаю, тут есть все, что нужно Челлане, чтобы дела в таверне пошли на лад. Передай ей, что она без стеснения может заказывать все необходимое. Лазурной заставе срочно требуется помещение, где можно было бы ухаживать за ранеными, а также место, где путешественники смогут восстановить свои силы.$B$BКогда будешь $Gготов:готова; вернуться на Лазурную заставу, найди сначала Стефаноса – он обычно бывает у трона наару, что в Экзодаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Стефаноса у трона наару, что в Экзодаре, и наймите гиппогрифа для возвращения на Лазурную заставу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9606,'Возвращение к корчмарю Челлане','Если мне память не изменяет, укрощением гиппогрифов на Лазурной заставе занимается Залдаан. Если тебе уже приходилось с ним встречаться, значит, ты можешь отправиться к нему на одном из моих гиппогрифов.$B$BС гиппогрифами есть одна тонкость, о которой надо помнить: их обучают возвращаться в родной город, но к другому укротителю гиппогрифов они отнесут тебя только в том случае, если тебе уже доводилось у него бывать.$B$BПоскольку ты $Gприбыл:прибыла; сюда на одном из гиппогрифов Залдаана, тебе не составит труда вернуться на Лазурную заставу и отвезти туда припасы.','Договоритесь со Стефаносом и наймите у него гиппогрифа для путешествия на Лазурную заставу. На заставе доставьте припасы Нургуни корчмарю Тоферу Челлане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к корчмарю Челлане',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мне память не изменяет, укрощением гиппогрифов на Лазурной заставе занимается Залдаан. Если тебе уже приходилось с ним встречаться, значит, ты можешь отправиться к нему на одном из моих гиппогрифов.$B$BС гиппогрифами есть одна тонкость, о которой надо помнить: их обучают возвращаться в родной город, но к другому укротителю гиппогрифов они отнесут тебя только в том случае, если тебе уже доводилось у него бывать.$B$BПоскольку ты $Gприбыл:прибыла; сюда на одном из гиппогрифов Залдаана, тебе не составит труда вернуться на Лазурную заставу и отвезти туда припасы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Договоритесь со Стефаносом и наймите у него гиппогрифа для путешествия на Лазурную заставу. На заставе доставьте припасы Нургуни корчмарю Тоферу Челлане.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9607,'В сердце ярости','$C, немедленно собирай силы и отправляйся на разведку к Кузне Крови в Цитадели Адского Пламени! Да-да, вот прямо сегодня, моя радость!$B$BНаши маги сумели засечь, что там происходит что-то из ряда выходящее. Но дальнейшее наблюдение оказалось заблокировано очень мощной защитной магией. Это вам не баран чихнул!$B$BТебе придется столкнуться с жестоким сопротивлением – ни одна группа из тех, что мы отправили на задание, не вернулась.$B$BРазведай все детали, вернись и доложи о результатах командиру армии.','Детально изучите Кузню Крови и доложите об увиденном командиру армии Данату Троллебою из Оплота Чести на Полуострове Адского Пламени.','У НИХ ЕСТЬ ВЛАСТИТЕЛЬ ПРЕИСПОДНЕЙ?!$B$BБоевой командир оглядывается на остальных и понижает голос.*$B$BЭто все объясняет. Должно быть, они использовали кровь этого властителя преисподней, чтобы создать орков Скверны. Значит, они тоже связаны с Пылающим Легионом. Если они смогли это сделать с коричневыми орками, значит, рано или поздно доберутся и до зеленых. Если из Темного портала выйдут орки новой Орды, нам придется несладко.$B$BМы должны нанести превентивный удар, и как можно скорее!','$GШтатский:Штатская;, докладывайте! Каковы результаты разведки Кузни Крови?','Детально изучите Кузню Крови','Вернитесь к командиру армии Данату Троллебою в Оплот Чести, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В сердце ярости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, немедленно собирай силы и отправляйся на разведку к Кузне Крови в Цитадели Адского Пламени! Да-да, вот прямо сегодня, моя радость!$B$BНаши маги сумели засечь, что там происходит что-то из ряда выходящее. Но дальнейшее наблюдение оказалось заблокировано очень мощной защитной магией. Это вам не баран чихнул!$B$BТебе придется столкнуться с жестоким сопротивлением – ни одна группа из тех, что мы отправили на задание, не вернулась.$B$BРазведай все детали, вернись и доложи о результатах командиру армии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Детально изучите Кузню Крови и доложите об увиденном командиру армии Данату Троллебою из Оплота Чести на Полуострове Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У НИХ ЕСТЬ ВЛАСТИТЕЛЬ ПРЕИСПОДНЕЙ?!$B$BБоевой командир оглядывается на остальных и понижает голос.*$B$BЭто все объясняет. Должно быть, они использовали кровь этого властителя преисподней, чтобы создать орков Скверны. Значит, они тоже связаны с Пылающим Легионом. Если они смогли это сделать с коричневыми орками, значит, рано или поздно доберутся и до зеленых. Если из Темного портала выйдут орки новой Орды, нам придется несладко.$B$BМы должны нанести превентивный удар, и как можно скорее!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GШтатский:Штатская;, докладывайте! Каковы результаты разведки Кузни Крови?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Детально изучите Кузню Крови',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру армии Данату Троллебою в Оплот Чести, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9608,'В сердце ярости','$C, ты $gдолжен:должна; собрать отряд и немедленно отправиться в Кузню Крови, в Цитадель Адского Пламени! Магические кристаллы показывают, что там происходит что-то странное. Но понять, что именно, не удается, потому что видение заблокировано мощной защитной магией. Ясно только одно, – там творится что-то очень важное.$B$BРассчитывай, что встретишься с жестоким сопротивлением. Ни одна из групп, которые мы отправили на это задание, не вернулась.$B$BРазведай детально, что там происходит, и доложи Назгреллу, советнику Тралла.','Детально изучите Кузню Крови и доложите об увиденном Назгрелу из Траллмара на Полуострове Адского Пламени.','У НИХ ЕСТЬ ПИТ ЛОРД?$B$B<Назгрел замечает взгляды других собравшихся и понижает голос.>$B$BОни используют его кровь для создания новых орков Скверны, которые никак не связаны с Пылающим Легионом. Если они творят подобные вещи с маг\'харскими коричневыми орками, то могут добраться и до нас!$B$BМы должны нанести удар в сердце их военной мощи, и скоро!','Ты уже $Gобследовал:обследовала; всю Кузню Крови? Что ты мне скажешь?','Детально изучите Кузню Крови','Вернитесь к Назгрелу в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В сердце ярости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, ты $gдолжен:должна; собрать отряд и немедленно отправиться в Кузню Крови, в Цитадель Адского Пламени! Магические кристаллы показывают, что там происходит что-то странное. Но понять, что именно, не удается, потому что видение заблокировано мощной защитной магией. Ясно только одно, – там творится что-то очень важное.$B$BРассчитывай, что встретишься с жестоким сопротивлением. Ни одна из групп, которые мы отправили на это задание, не вернулась.$B$BРазведай детально, что там происходит, и доложи Назгреллу, советнику Тралла.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Детально изучите Кузню Крови и доложите об увиденном Назгрелу из Траллмара на Полуострове Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У НИХ ЕСТЬ ПИТ ЛОРД?$B$B<Назгрел замечает взгляды других собравшихся и понижает голос.>$B$BОни используют его кровь для создания новых орков Скверны, которые никак не связаны с Пылающим Легионом. Если они творят подобные вещи с маг\'харскими коричневыми орками, то могут добраться и до нас!$B$BМы должны нанести удар в сердце их военной мощи, и скоро!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gобследовал:обследовала; всю Кузню Крови? Что ты мне скажешь?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Детально изучите Кузню Крови',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Назгрелу в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9609,'Помощь дозорному Биггсу','Магтур сообщил мне, что дозорному, который находится неподалеку, нужна помощь. Очевидно, караван, который он сопровождал из Темнолесья, был атакован Заблудшими. Сдается мне, он единственный, кто выжил после этого нападения.$B$BОн сейчас где-то к югу отсюда. Прошу тебя, |3-6($c), помоги ему.','Найдите дозорного Биггса на Болоте Печали.','Какие? Дренеи послали вас сюда из Убежища? Как странно. $B$BНу, я не из тех, кто отказывается от помощи. Спасибо, что пришли, $C!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь дозорному Биггсу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Магтур сообщил мне, что дозорному, который находится неподалеку, нужна помощь. Очевидно, караван, который он сопровождал из Темнолесья, был атакован Заблудшими. Сдается мне, он единственный, кто выжил после этого нападения.$B$BОн сейчас где-то к югу отсюда. Прошу тебя, |3-6($c), помоги ему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите дозорного Биггса на Болоте Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какие? Дренеи послали вас сюда из Убежища? Как странно. $B$BНу, я не из тех, кто отказывается от помощи. Спасибо, что пришли, $C!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9610,'Озеро Слез','Я интересуюсь прошлым Азерота. Не хочешь ли мне помочь?$B$BЗдесь в трясинах по соседству находится весьма интересная в историческом отношении местность, в которое я и попросил бы тебя отправиться. К юго-востоку отсюда расположено озеро Слез. Говорят, что на его берегах и в глубинах спрятаны артефакты цивилизации троллей Атал\'ай.$B$BНо берегись, озеро охраняет Сомнус, древний зеленый дракон и его сородичи, а само оно просто кишит плотоядной рыбой.','Добудьте 5 артефактов Атал\'ай и вернитесь с ними к Холаару в Убежище на Болото Печали.','Благодарю тебя, $C. Изучение этих артефактов должно занять какое-то время. Как еще мы и дренеи, сможем вписаться в него, если не придем к пониманию истории вашего мира?','Я с нетерпением жду, когда ты соберешь достаточно артефактов Атал\'ай, чтобы я мог приступить к их изучению. Я очень хочу узнать, что случилось с их некогда великой цивилизацией.','Вернитесь к Холаару на Болото Печали.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Озеро Слез',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я интересуюсь прошлым Азерота. Не хочешь ли мне помочь?$B$BЗдесь в трясинах по соседству находится весьма интересная в историческом отношении местность, в которое я и попросил бы тебя отправиться. К юго-востоку отсюда расположено озеро Слез. Говорят, что на его берегах и в глубинах спрятаны артефакты цивилизации троллей Атал\'ай.$B$BНо берегись, озеро охраняет Сомнус, древний зеленый дракон и его сородичи, а само оно просто кишит плотоядной рыбой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 артефактов Атал\'ай и вернитесь с ними к Холаару в Убежище на Болото Печали.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, $C. Изучение этих артефактов должно занять какое-то время. Как еще мы и дренеи, сможем вписаться в него, если не придем к пониманию истории вашего мира?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я с нетерпением жду, когда ты соберешь достаточно артефактов Атал\'ай, чтобы я мог приступить к их изучению. Я очень хочу узнать, что случилось с их некогда великой цивилизацией.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Холаару на Болото Печали.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9611,'Azuremyst: aa - A - Quest Flag 000') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Azuremyst: aa - A - Quest Flag 000',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9612,'Большое спасибо!','Ты $gспас:спасла; мне жизнь, $n! Спасибо огромное! Если бы не ты, эта тварь разорвала бы меня на части.$B$BЕсли будешь на Лазурной заставе, расскажи о своем подвиге экзарху. Не сомневаюсь, он очень обрадуется!','Поговорите с экзархом Менелаусом на Лазурной заставе.','Отлично, $N. Молодцы действительно! Вы становитесь особой |3-4($R) - на голову выше других в вашем возрасте. Возьми это как награду!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большое спасибо!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gспас:спасла; мне жизнь, $n! Спасибо огромное! Если бы не ты, эта тварь разорвала бы меня на части.$B$BЕсли будешь на Лазурной заставе, расскажи о своем подвиге экзарху. Не сомневаюсь, он очень обрадуется!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с экзархом Менелаусом на Лазурной заставе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N. Молодцы действительно! Вы становитесь особой |3-4($R) - на голову выше других в вашем возрасте. Возьми это как награду!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9613,'Deprecated: завещание Кинны','*Как только вы дотронулись до меча, в ваших ушах зазвучал женский голос.* $B$BАй! Не делай этого! Не видишь, что я и так уже вся развалилась на кусочки? Это больно!$B$BЯ вижу, ты не $gпопался:попалась; в ловушки Каражана. Тогда, конечно, ты знаешь о Кадгаре и Аметистовом Оке.$B$BТебе надо найти кого-нибудь, кто сможет собрать меня из обломков. Корен... он был одним из нас. Надеюсь, ты тоже на нашей стороне. Тогда он может помочь.','Раздробленный клинок, который вы отыскали в Каражане, просит вас найти Корена, чтобы тот мог восстановить его. Для завершения этого задания необходимо иметь как минимум уважительное отношение Аметистового Ока.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Deprecated: завещание Кинны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Как только вы дотронулись до меча, в ваших ушах зазвучал женский голос.* $B$BАй! Не делай этого! Не видишь, что я и так уже вся развалилась на кусочки? Это больно!$B$BЯ вижу, ты не $gпопался:попалась; в ловушки Каражана. Тогда, конечно, ты знаешь о Кадгаре и Аметистовом Оке.$B$BТебе надо найти кого-нибудь, кто сможет собрать меня из обломков. Корен... он был одним из нас. Надеюсь, ты тоже на нашей стороне. Тогда он может помочь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздробленный клинок, который вы отыскали в Каражане, просит вас найти Корена, чтобы тот мог восстановить его. Для завершения этого задания необходимо иметь как минимум уважительное отношение Аметистового Ока.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9614,'Deprecated: Перековать короткий меч','Этот клинок был разбит на такое множество осколков... Переплавить их в единое целое будет совсем не просто.$B$BМне потребуется корий. Много кория. Кроме того, кристалл Бездны и некоторое количество изначального огня.','Принесите 40 кориевых слитков, 1 кристалл Бездны и 8 сгустков изначального огня Корену в Каражан.','Вернитесь к Корен в Каражан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Deprecated: Перековать короткий меч',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот клинок был разбит на такое множество осколков... Переплавить их в единое целое будет совсем не просто.$B$BМне потребуется корий. Много кория. Кроме того, кристалл Бездны и некоторое количество изначального огня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 40 кориевых слитков, 1 кристалл Бездны и 8 сгустков изначального огня Корену в Каражан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корен в Каражан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9615,'Deprecated: Перековать длинный меч','Этот клинок был разбит на такое множество осколков... Переплавить их в единое целое будет совсем не просто.$B$BМне потребуется корий. Много кория. Кроме того, кристалл Бездны и некоторое количество изначального огня.','Принесите 40 кориевых слитков, 1 кристалл Бездны и 8 сгустков изначального огня Корену в Каражан.','Вернитесь к Корен в Каражан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Deprecated: Перековать длинный меч',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот клинок был разбит на такое множество осколков... Переплавить их в единое целое будет совсем не просто.$B$BМне потребуется корий. Много кория. Кроме того, кристалл Бездны и некоторое количество изначального огня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 40 кориевых слитков, 1 кристалл Бездны и 8 сгустков изначального огня Корену в Каражан.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корен в Каражан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9616,'Бандиты!','Похоже, это объявление о награде. Язык эльфов крови вам непонятен, но на картинке изображен мертвый дреней, улыбающийся эльф крови, попирающий его труп, и символ, вероятно, означающий денежные единицы.$B$BОказывается, они хотят истребить дренеев! Следует сообщить об этом экзарху.','Отнесите сообщение эльфов крови экзарху Менелаусу на Лазурную заставу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бандиты!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, это объявление о награде. Язык эльфов крови вам непонятен, но на картинке изображен мертвый дреней, улыбающийся эльф крови, попирающий его труп, и символ, вероятно, означающий денежные единицы.$B$BОказывается, они хотят истребить дренеев! Следует сообщить об этом экзарху.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сообщение эльфов крови экзарху Менелаусу на Лазурную заставу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9617,'На поиски Странников','Лейтенант Вестница Зари в Обители Странников созывает к себе всех, кто посвятил себя ремеслу охотника. Тебе стоит повидаться с ней, $n. Она подлинный светоч мудрости для всех нас.$b$bОбитель Странников находится к югу от Луносвета.','Поговорите с лейтенантом Вестницей Зари в Обители Странников.','$N, хорошо, что вы пришли. Список наших союзников становится все меньше, и даже тем, кто разделяет наше дело, не полностью доверяют. Именно поэтому мы обращаемся за помощью к природе.$B$BВ союзниках леса мы находим глубокую связь, не знающую обмана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На поиски Странников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Лейтенант Вестница Зари в Обители Странников созывает к себе всех, кто посвятил себя ремеслу охотника. Тебе стоит повидаться с ней, $n. Она подлинный светоч мудрости для всех нас.$b$bОбитель Странников находится к югу от Луносвета.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с лейтенантом Вестницей Зари в Обители Странников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, хорошо, что вы пришли. Список наших союзников становится все меньше, и даже тем, кто разделяет наше дело, не полностью доверяют. Именно поэтому мы обращаемся за помощью к природе.$B$BВ союзниках леса мы находим глубокую связь, не знающую обмана.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9618,'Возвращение с донесениями','Да, ловкости рук тебе не занимать! Несомненно, тебе эти донесения доверить можно.','Отнесите донесения Келтуса Темного Листа Зеланису в Луносвет.','Все эти отчеты из Келтуса? Он был очень занят, это точно. $B$BКелтус - $C среди негодяев - он редко выполняет приказы в точности и часто берет дело в свои руки! Однако не поймите это неправильно, так как он один из моих самых надежных шпионов, и без него мы бы потерялись. $B$BВы сегодня проделали образцовую работу. Пожалуйста, прими этот клинок и направь его в спину нашему врагу.','Удалось ли тебе найти Келтуса?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение с донесениями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, ловкости рук тебе не занимать! Несомненно, тебе эти донесения доверить можно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите донесения Келтуса Темного Листа Зеланису в Луносвет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все эти отчеты из Келтуса? Он был очень занят, это точно. $B$BКелтус - $C среди негодяев - он редко выполняет приказы в точности и часто берет дело в свои руки! Однако не поймите это неправильно, так как он один из моих самых надежных шпионов, и без него мы бы потерялись. $B$BВы сегодня проделали образцовую работу. Пожалуйста, прими этот клинок и направь его в спину нашему врагу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе найти Келтуса?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9619,'Руна призыва','В камне Бездны проступает многоярусное здание, по которому бродят призрачные фигуры. По мере того как изображение становится отчетливее, появляются все новые здания. Судя по всему, это Деревня Золотистой Дымки.$b$bВнезапно крыши и кроны деревьев проносятся мимо, и открывается путь в Деревню Золотистой Дымки, ведущий вдоль реки Элрендар на запад.$b$bСтупайте туда; оказавшись там, используйте камень пустоты близ руны Призыва на вершине центрального здания и повергните вызванного демона Бездны. Только после этого вы можете вернуться к своей наставнице.','Используйте камень Бездны, чтобы призвать демона Бездны в Деревню Золотистой Дымки, одолейте демона и вернуться к Талионии в Луносвет.','Я впечатлен, что ты здесь стоишь, $N. Многие ученики погибли из-за странника Бездны или даже из-за камня пустоты. $B$BСтранник Бездны теперь в твоем распоряжении. Хорошо используй своего нового слугу.','Ты $Gследовал:следовала; по пути, открытому камнем пустоты?','Вернитесь к Талионии в Святилище, что в Луносвете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руна призыва',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В камне Бездны проступает многоярусное здание, по которому бродят призрачные фигуры. По мере того как изображение становится отчетливее, появляются все новые здания. Судя по всему, это Деревня Золотистой Дымки.$b$bВнезапно крыши и кроны деревьев проносятся мимо, и открывается путь в Деревню Золотистой Дымки, ведущий вдоль реки Элрендар на запад.$b$bСтупайте туда; оказавшись там, используйте камень пустоты близ руны Призыва на вершине центрального здания и повергните вызванного демона Бездны. Только после этого вы можете вернуться к своей наставнице.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте камень Бездны, чтобы призвать демона Бездны в Деревню Золотистой Дымки, одолейте демона и вернуться к Талионии в Луносвет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я впечатлен, что ты здесь стоишь, $N. Многие ученики погибли из-за странника Бездны или даже из-за камня пустоты. $B$BСтранник Бездны теперь в твоем распоряжении. Хорошо используй своего нового слугу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gследовал:следовала; по пути, открытому камнем пустоты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талионии в Святилище, что в Луносвете.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9620,'Пропавшие картографы','После того как мы обосновались здесь, на Кровавой заставе, я посылал разведовательные группы, чтобы составить более точные карты острова. Обычно разведчики возвращались целыми и невредимыми и исправно снабжали меня необходимыми сведениями; но группа, которую я отправил на восток, к развалинам, так и не вернулась.$B$BБоюсь, с ними что-то случилось... но нас не так много, чтобы снаряжать поисковую экспедицию. Прошу тебя, $n, разыщи их! Помоги им, если они нуждаются в помощи. Надеюсь, они вернутся – и не с пустыми руками...','Предвестник Миколаас просит разыскать группу разведчиков, которую он послал к развалинам Лорет\'Арана, и помочь группе чем только возможно.','Живых не осталось. Разведчики-дренеи погибли, сраженные оружием наг. Их вещи разбросаны по земле, и только кристаллы с исследовательскими данными исчезли бесследно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие картографы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После того как мы обосновались здесь, на Кровавой заставе, я посылал разведовательные группы, чтобы составить более точные карты острова. Обычно разведчики возвращались целыми и невредимыми и исправно снабжали меня необходимыми сведениями; но группа, которую я отправил на восток, к развалинам, так и не вернулась.$B$BБоюсь, с ними что-то случилось... но нас не так много, чтобы снаряжать поисковую экспедицию. Прошу тебя, $n, разыщи их! Помоги им, если они нуждаются в помощи. Надеюсь, они вернутся – и не с пустыми руками...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предвестник Миколаас просит разыскать группу разведчиков, которую он послал к развалинам Лорет\'Арана, и помочь группе чем только возможно.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Живых не осталось. Разведчики-дренеи погибли, сраженные оружием наг. Их вещи разбросаны по земле, и только кристаллы с исследовательскими данными исчезли бесследно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9621,'Посол к Орде','Наши потенциальные союзники сомневались в наших способностях. Какая им от нас польза, если мы собственные проблемы решить не можем?$B$BТеперь все изменилось. В нашей силе никто не усомнится. Мы сможем вступить в Орду как равные.$B$BОтнеси это письмо Сильване, правительнице Отрекшихся. Она и так на нашей стороне, но весть о смерти Дар\'Кхана будет воистину музыкой для ее ушей. Готовься к долгому пути, $n. Если все сложится благополучно, Сильвана пошлет тебя в Оргриммар.','Отнесите письмо от Лор\'темара Терона Сильване Ветрокрылой в Подгород, столицу Отрекшихся в Тирисфальских лесах.','А, гость из Кель\'Таласа! Какие вести ты принесла?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посол к Орде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши потенциальные союзники сомневались в наших способностях. Какая им от нас польза, если мы собственные проблемы решить не можем?$B$BТеперь все изменилось. В нашей силе никто не усомнится. Мы сможем вступить в Орду как равные.$B$BОтнеси это письмо Сильване, правительнице Отрекшихся. Она и так на нашей стороне, но весть о смерти Дар\'Кхана будет воистину музыкой для ее ушей. Готовься к долгому пути, $n. Если все сложится благополучно, Сильвана пошлет тебя в Оргриммар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите письмо от Лор\'темара Терона Сильване Ветрокрылой в Подгород, столицу Отрекшихся в Тирисфальских лесах.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, гость из Кель\'Таласа! Какие вести ты принесла?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9622,'Предупреди свой народ','Форт спасен. Скоро мой народ вернется в дом предков. Пророчество исполнилось, и для Тихвой наступает век процветания.$B$BУвы, твой народ ожидает темный путь. Пророчество говорило не обо всем, многие вопросы остались без ответа.$B$BВозвращайся к своим правителям и расскажи им обо всем, что $gвидел:видела; здесь.$B$BИ помни, $gИзбранный:Избранная;: стоит только попросить, и племя Тихвой придет тебе на помощь.','Поговорите с экзархом Менелаусом на Лазурной заставе.','Видения, говоришь? Интересно... Так пророчество сбылось?$B$BЗначит, они видели энергетическое ядро Экзодара? И О\'рос тоже являлся им в видении? Что бы это значило?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупреди свой народ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Форт спасен. Скоро мой народ вернется в дом предков. Пророчество исполнилось, и для Тихвой наступает век процветания.$B$BУвы, твой народ ожидает темный путь. Пророчество говорило не обо всем, многие вопросы остались без ответа.$B$BВозвращайся к своим правителям и расскажи им обо всем, что $gвидел:видела; здесь.$B$BИ помни, $gИзбранный:Избранная;: стоит только попросить, и племя Тихвой придет тебе на помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с экзархом Менелаусом на Лазурной заставе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Видения, говоришь? Интересно... Так пророчество сбылось?$B$BЗначит, они видели энергетическое ядро Экзодара? И О\'рос тоже являлся им в видении? Что бы это значило?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9623,'Время пришло','Ты $gпокорил:покорила; дикие леса нашей новой родины и $gпроявил:проявила; себя с лучшей стороны. Я думаю, ты $gготов:готова; отправиться на остров Кровавой Дымки и вступить в бой с нашими врагами. Такие как ты нужны Длани Аргуса. $B$BПоговори с Тораллиусом Пастухом. Он присматривает за элекками неподалеку от Экзодара. Передай ему мои распоряжения, чтобы он немедленно ознакомил тебя с новыми обязанностями на острове Кровавой Дымки.','Передайте распоряжения экзарха Тораллиусу Пастуху. Он находится у Экзодара, недалеко от входа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время пришло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпокорил:покорила; дикие леса нашей новой родины и $gпроявил:проявила; себя с лучшей стороны. Я думаю, ты $gготов:готова; отправиться на остров Кровавой Дымки и вступить в бой с нашими врагами. Такие как ты нужны Длани Аргуса. $B$BПоговори с Тораллиусом Пастухом. Он присматривает за элекками неподалеку от Экзодара. Передай ему мои распоряжения, чтобы он немедленно ознакомил тебя с новыми обязанностями на острове Кровавой Дымки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте распоряжения экзарха Тораллиусу Пастуху. Он находится у Экзодара, недалеко от входа.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9624,'Любимое блюдо','Послушай, |3-6($c), Я сделал замечательное, грандиозное открытие! В той части острова, которая не была затронута скверной, растет восхитительный фрукт, именуемый песчаной грушей. Их находят у корней деревьев.$B$BЯ готовил с ними грушевые пироги, но выяснилось, что элекки – большие охотники до песчаных груш, так что они частенько подъедали мои запасы. Тогда я решил делать запас побольше, чтобы хватало и мне, и элеккам, – но, увы, все мои запасы пропали, а пирогов-то хочется... Я вот и подумал: может, ты мне поможешь запастись песчаными грушами? А я с тобой непременно поделюсь, когда напеку пирогов, обещаю!','Принесите 10 песчаных груш Аонару на Перекресток Кессела.','Найти песчаные груши все труднее – а это значит, что я могу печь все меньше пирогов, а уж элеккам и вовсе почти ничего не останется... Но, может, ты принесешь мне хоть немного груш?','Вернитесь к Аонару на Берилловое побережье, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любимое блюдо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, |3-6($c), Я сделал замечательное, грандиозное открытие! В той части острова, которая не была затронута скверной, растет восхитительный фрукт, именуемый песчаной грушей. Их находят у корней деревьев.$B$BЯ готовил с ними грушевые пироги, но выяснилось, что элекки – большие охотники до песчаных груш, так что они частенько подъедали мои запасы. Тогда я решил делать запас побольше, чтобы хватало и мне, и элеккам, – но, увы, все мои запасы пропали, а пирогов-то хочется... Я вот и подумал: может, ты мне поможешь запастись песчаными грушами? А я с тобой непременно поделюсь, когда напеку пирогов, обещаю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 песчаных груш Аонару на Перекресток Кессела.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Найти песчаные груши все труднее – а это значит, что я могу печь все меньше пирогов, а уж элеккам и вовсе почти ничего не останется... Но, может, ты принесешь мне хоть немного груш?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аонару на Берилловое побережье, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (9625,'Элекки – это серьезно','Поговорите с Ворканом Пастухом Элекков на острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Элекки – это серьезно',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ворканом Пастухом Элекков на острове Кровавой Дымки.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (9627,'Верность Орде','Возвращайтесь в Луносвет и поговорите с Лор\'темаром Тероном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верность Орде',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь в Луносвет и поговорите с Лор\'темаром Тероном.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9628,'Цена знания – жизнь','Похоже, картографам уже не понадобится никакая помощь. Однако они, скорее всего, успели собрать информацию, которая так нужна предвестнику Миколаасу. Кристалла с результатами наблюдений среди вещей убитых не обнаружилось – следовательно, он попал в руки наг из клана Зловещей Чешуи.$B$BПредвестник Миколаас, конечно, будет весьма огорчен, узнав о гибели своих картографов, но еще больше его огорчит, если все их труды пропадут впустую.','Неподалеку от того места, где были убиты картографы, обитают наги клана Зловещей Чешуи. Отберите у них кристалл с результатами наблюдений и доставьте его на Кровавую заставу предвестнику Миколаасу.','Тебе удалось выяснить, что помешало исследовательской группе вернуться?','Вернитесь к предвестнику Миколаасу на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Цена знания – жизнь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, картографам уже не понадобится никакая помощь. Однако они, скорее всего, успели собрать информацию, которая так нужна предвестнику Миколаасу. Кристалла с результатами наблюдений среди вещей убитых не обнаружилось – следовательно, он попал в руки наг из клана Зловещей Чешуи.$B$BПредвестник Миколаас, конечно, будет весьма огорчен, узнав о гибели своих картографов, но еще больше его огорчит, если все их труды пропадут впустую.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Неподалеку от того места, где были убиты картографы, обитают наги клана Зловещей Чешуи. Отберите у них кристалл с результатами наблюдений и доставьте его на Кровавую заставу предвестнику Миколаасу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось выяснить, что помешало исследовательской группе вернуться?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Миколаасу на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9629,'Поймать и отпустить','Живущие на юго-западном побережье мурлоки из клана Черного Ила – весьма любопытные создания. В некоторых случаях они поступают почти как неразумные звери, в других же проявляют завидную организованность.$B$BУ меня на этот счет есть несколько теорий, но до сего момента я не имела возможности их проверить. Я разработала одно устройство, позволяющее следить за интересующими меня особями мурлоков, не нанося им существенного вреда и не влияя на их естественное поведение. Если ты поможешь мне с метками, можешь быть $Gуверен:уверена;: я хорошо тебе заплачу.','Ну как, сработал мой маркировщик? Тебе удалось поставить мурлокам метки? Это помогло бы мне существенно продвинуться в исследованиях...','Вернитесь к Морэ на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поймать и отпустить',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Живущие на юго-западном побережье мурлоки из клана Черного Ила – весьма любопытные создания. В некоторых случаях они поступают почти как неразумные звери, в других же проявляют завидную организованность.$B$BУ меня на этот счет есть несколько теорий, но до сего момента я не имела возможности их проверить. Я разработала одно устройство, позволяющее следить за интересующими меня особями мурлоков, не нанося им существенного вреда и не влияя на их естественное поведение. Если ты поможешь мне с метками, можешь быть $Gуверен:уверена;: я хорошо тебе заплачу.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, сработал мой маркировщик? Тебе удалось поставить мурлокам метки? Это помогло бы мне существенно продвинуться в исследованиях...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морэ на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9630,'Дневник Медива','Я слышал о тебе, $n. Ты заходишь в Каражан и выходишь обратно так свободно, как никто из смертных.$B$BЯ хочу попросить тебя об особой услуге. Аметистовое Око пыталось выяснить местонахождение собственноручных дневников Медива – это было одним из предметов наших поисков.$B$BК сожалению, никто из посланных агентов назад не вернулся. Вравьен был одним из последних, отправленных нами. Разыщи его, если сможешь, и узнай что-нибудь о записях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дневник Медива',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал о тебе, $n. Ты заходишь в Каражан и выходишь обратно так свободно, как никто из смертных.$B$BЯ хочу попросить тебя об особой услуге. Аметистовое Око пыталось выяснить местонахождение собственноручных дневников Медива – это было одним из предметов наших поисков.$B$BК сожалению, никто из посланных агентов назад не вернулся. Вравьен был одним из последних, отправленных нами. Разыщи его, если сможешь, и узнай что-нибудь о записях.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9631,'Взаимовыручка','Есть одна небольшая деталь, про которую я совершенно забыл. Остаток сущности Медива, заключенный в этом фрагменте кости, абсолютно лишен жизни – так же, как и Арканагос.$B$BНо, тем не менее, есть способ все исправить. И я знаю человека, который может помочь нам.$B$BСтупай в Зону 52 в Пустоверти и покажи эту кость Калинне Латред. Она сообразит, что можно сделать.','Доставьте фрагмент обугленной кости Калинне Латред в Зону 52 в Пустоверти.','Альтурус хочет, чтобы я подняла из мертвых целого дракона? М-да, такое дело трудно даже представить. $B$BНо, думаю, я сумею вам помочь, $N. Если вы, в свою очередь, поможете мне.','Вас прислал Альтурус. Звезды предупредили меня о вашем прибытии.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взаимовыручка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть одна небольшая деталь, про которую я совершенно забыл. Остаток сущности Медива, заключенный в этом фрагменте кости, абсолютно лишен жизни – так же, как и Арканагос.$B$BНо, тем не менее, есть способ все исправить. И я знаю человека, который может помочь нам.$B$BСтупай в Зону 52 в Пустоверти и покажи эту кость Калинне Латред. Она сообразит, что можно сделать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте фрагмент обугленной кости Калинне Латред в Зону 52 в Пустоверти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Альтурус хочет, чтобы я подняла из мертвых целого дракона? М-да, такое дело трудно даже представить. $B$BНо, думаю, я сумею вам помочь, $N. Если вы, в свою очередь, поможете мне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вас прислал Альтурус. Звезды предупредили меня о вашем прибытии.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9632,'Новые союзники','Думаю, тебе уже известно, |3-6($c), сколько усилий приложил предвестник Миколаас, чтобы обеспечить надежную защиту Кровавой заставе. Но несмотря на это, нам по-прежнему не хватает ресурсов, зато врагов явный избыток.$B$BВрагам хорошо известна эта наша слабость, однако они не принимают в расчет то, что мы можем заручиться поддержкой Альянса. Я подготовил рекомендательное письмо: его нужно доставить в Аубердин, ближайший к нам оплот Альянса. Надеюсь, они прислушаются к нашему предложению, и вместе мы разгромим врагов. Отнеси это письмо охотнице Келле Тетиве Ночи на пристань к западу от Экзодара.','Доставьте рекомендательное письмо охотнице Келле Тетиве Ночи на остров Лазурной Дымки.','Конечно, я помогу тебе попасть в Аубердин. По счастью, тут по морю совсем недалеко.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые союзники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, тебе уже известно, |3-6($c), сколько усилий приложил предвестник Миколаас, чтобы обеспечить надежную защиту Кровавой заставе. Но несмотря на это, нам по-прежнему не хватает ресурсов, зато врагов явный избыток.$B$BВрагам хорошо известна эта наша слабость, однако они не принимают в расчет то, что мы можем заручиться поддержкой Альянса. Я подготовил рекомендательное письмо: его нужно доставить в Аубердин, ближайший к нам оплот Альянса. Надеюсь, они прислушаются к нашему предложению, и вместе мы разгромим врагов. Отнеси это письмо охотнице Келле Тетиве Ночи на пристань к западу от Экзодара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте рекомендательное письмо охотнице Келле Тетиве Ночи на остров Лазурной Дымки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конечно, я помогу тебе попасть в Аубердин. По счастью, тут по морю совсем недалеко.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9633,'Дорога к Аубердину','Подожди на пристани. Скоро из порта Аубердин, что на Темных берегах, прибудет корабль. Когда пассажиры сойдут на берег, ты сможешь подняться на борт.$B$BПутешествие будет недолгим – конечно, если ты не страдаешь морской болезнью. Сойдешь на берег в Аубердине, а там уже доставишь письмо по назначению.$B$BДумаю, лучше всего обратиться к моему старому другу и весьма уважаемому жителю Аубердина; его зовут Тандрис Ветропряд.','Сядьте на корабль, идущий в Аубердин. Пристань находится неподалеку от дома охотницы Келлы Тетивы Ночи. В Аубердине отдайте рекомендательное письмо Тандрису Ветропряду.','Тандрис берет рекомендательное письмо, пробегает его глазами и кивает. $B$BВ давние времена мой народ жил на островах, которые дренеи называют островами Лазурной и Кровавой Дымки. Анахорет Пайтеус и его братия, по всей видимости, столкнулись с древними врагами ночных эльфов...$B$BУверен, Аубердин окажет своим новым союзникам всю возможную поддержку. Я пошлю весточку Пайтеусу, как только поговорю с жителями города и часовыми.','Добро пожаловать в Аубердин, $Gдобрый друг:добрая госпожа;. Что привело тебя на Темный Берег?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога к Аубердину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Подожди на пристани. Скоро из порта Аубердин, что на Темных берегах, прибудет корабль. Когда пассажиры сойдут на берег, ты сможешь подняться на борт.$B$BПутешествие будет недолгим – конечно, если ты не страдаешь морской болезнью. Сойдешь на берег в Аубердине, а там уже доставишь письмо по назначению.$B$BДумаю, лучше всего обратиться к моему старому другу и весьма уважаемому жителю Аубердина; его зовут Тандрис Ветропряд.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сядьте на корабль, идущий в Аубердин. Пристань находится неподалеку от дома охотницы Келлы Тетивы Ночи. В Аубердине отдайте рекомендательное письмо Тандрису Ветропряду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тандрис берет рекомендательное письмо, пробегает его глазами и кивает. $B$BВ давние времена мой народ жил на островах, которые дренеи называют островами Лазурной и Кровавой Дымки. Анахорет Пайтеус и его братия, по всей видимости, столкнулись с древними врагами ночных эльфов...$B$BУверен, Аубердин окажет своим новым союзникам всю возможную поддержку. Я пошлю весточку Пайтеусу, как только поговорю с жителями города и часовыми.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать в Аубердин, $Gдобрый друг:добрая госпожа;. Что привело тебя на Темный Берег?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9634,'Чужие-хищники','В наших странствиях мы хорошо усвоили один урок: нужно быть крайне осторожным, перенося животных и растения из одного мира в другой. На "Экзодаре" при крушении были образчики многих видов нездешних существ, в том числе насекомовидный хищник, который зовется опустошителем.$B$BНекоторые экземпляры погибли; другие не только выжили, но и приспособились к новым условиям. Если мы не озаботимся этим вопросом, они могут нарушить экологический баланс на островах.$B$BТы найдешь опустошителей неподалеку от Перекрестка Кессела, к западу отсюда. Насколько мне известно, они поселились неподалеку от берега.','Мы должны действовать быстро, иначе опустошители вытеснят всех естественных хищников на острове. Необходимо сократить их популяцию!','Вернитесь к Воркану Пастуху Элекков на Берилловое побережье, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чужие-хищники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В наших странствиях мы хорошо усвоили один урок: нужно быть крайне осторожным, перенося животных и растения из одного мира в другой. На "Экзодаре" при крушении были образчики многих видов нездешних существ, в том числе насекомовидный хищник, который зовется опустошителем.$B$BНекоторые экземпляры погибли; другие не только выжили, но и приспособились к новым условиям. Если мы не озаботимся этим вопросом, они могут нарушить экологический баланс на островах.$B$BТы найдешь опустошителей неподалеку от Перекрестка Кессела, к западу отсюда. Насколько мне известно, они поселились неподалеку от берега.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы должны действовать быстро, иначе опустошители вытеснят всех естественных хищников на острове. Необходимо сократить их популяцию!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Воркану Пастуху Элекков на Берилловое побережье, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9635,'Удаленный конденсатор выхлопов!','Болотный газ – потрясающая вещь! Он может быть весьма ценным! Но сначала его нужно собрать – а вот для этого-то нам и потребуется удаленный конденсатор выхлопов!$b$bЯ могу тебе дать чертежи такого конденсатора, но сначала хочу получить что-нибудь взамен. Например, мне нужны кое-какие запчасти. Я знаю, что еще не так давно куча полезных деталей валялась вокруг сломанного парового насоса в Мертвой трясине, к северо-востоку отсюда.$b$bЯ слышал, что это иссохшие великаны растащили детали по всему дну пересохшего озера.','Отлично! Теперь, если добыть скользящую петлю, пергаментное крепление, хлебательную трубку и липкую ленту, получится то, что надо!$B$BНу ладно, ладно! Ты $Gзаслужил:аслужила; награду, я же и не спорю! Счастливо, $N.','Ну что, где запчасти? Мой водолазный костюм нуждается в ремонте...','Вернитесь к Маку Ныряльщику в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удаленный конденсатор выхлопов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Болотный газ – потрясающая вещь! Он может быть весьма ценным! Но сначала его нужно собрать – а вот для этого-то нам и потребуется удаленный конденсатор выхлопов!$b$bЯ могу тебе дать чертежи такого конденсатора, но сначала хочу получить что-нибудь взамен. Например, мне нужны кое-какие запчасти. Я знаю, что еще не так давно куча полезных деталей валялась вокруг сломанного парового насоса в Мертвой трясине, к северо-востоку отсюда.$b$bЯ слышал, что это иссохшие великаны растащили детали по всему дну пересохшего озера.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Теперь, если добыть скользящую петлю, пергаментное крепление, хлебательную трубку и липкую ленту, получится то, что надо!$B$BНу ладно, ладно! Ты $Gзаслужил:аслужила; награду, я же и не спорю! Счастливо, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где запчасти? Мой водолазный костюм нуждается в ремонте...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Маку Ныряльщику в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9636,'Удаленный конденсатор выхлопов!','Доводилось ли вам видеть болотный газ? Блестящая штука, не правда ли?$b$bНо для того, чтобы извлечь из него все полезное, нужен удаленный конденсатор выхлопов! Я могу вам дать чертежи такого конденсатора, но мне нужны запчасти для ремонта техники.$b$bЯ знаю, что еще не так давно куча деталей валялась вокруг парового насоса в Мертвой трясине, к северо-востоку отсюда. Думаю, это иссохшие великаны разрушили насос.$b$bНу что, поможем друг другу?','Принесите 15 деталей парового насоса К. Ли Мелюзге в Телредор в Зангартопи.','Ну что, где запчасти? Мне нужно починить кольцедав, пока анахорет Ахуурн не настучал мне по голове!','Вернитесь к К. Ли Мелюзге в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удаленный конденсатор выхлопов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доводилось ли вам видеть болотный газ? Блестящая штука, не правда ли?$b$bНо для того, чтобы извлечь из него все полезное, нужен удаленный конденсатор выхлопов! Я могу вам дать чертежи такого конденсатора, но мне нужны запчасти для ремонта техники.$b$bЯ знаю, что еще не так давно куча деталей валялась вокруг парового насоса в Мертвой трясине, к северо-востоку отсюда. Думаю, это иссохшие великаны разрушили насос.$b$bНу что, поможем друг другу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 15 деталей парового насоса К. Ли Мелюзге в Телредор в Зангартопи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, где запчасти? Мне нужно починить кольцедав, пока анахорет Ахуурн не настучал мне по голове!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к К. Ли Мелюзге в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9637,'Требование Калинны','Мне пришлось покинуть Кирин-Тор в поисках знаний, которые орден считал запретными. Есть некая ирония в том, что теперь орден просит моей помощи именно по этому вопросу.$B$BМожет быть, я помогу тебе. Но сначала хочу, чтобы ты кое-что для меня $gсделал:сделала;. Мне нужны две книги, я уже давно пытаюсь их раздобыть $B$BПервая называется Фолиант Сумерек. Им владеет орочий чернокнижник Пустоклят. Вторая, Книга Забытых Имен, находится у араккоа, известного как Темнопряд Сит.','Калинна Латред требует отыскать и принести ей Фолиант Сумерек и Книгу Забытых Имен. Первой владеет главный чернокнижник Пустоклят, его можно найти в Разрушенных залах Цитадели Адского Пламени. Вторая принадлежит Темнопряду Ситу, который находится в Сетеккских залах в Аукиндоне.$B$BЭто задание должно быть выполнено в героическом режиме.','Вернитесь к Калинне Латред в Пустоверть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Требование Калинны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне пришлось покинуть Кирин-Тор в поисках знаний, которые орден считал запретными. Есть некая ирония в том, что теперь орден просит моей помощи именно по этому вопросу.$B$BМожет быть, я помогу тебе. Но сначала хочу, чтобы ты кое-что для меня $gсделал:сделала;. Мне нужны две книги, я уже давно пытаюсь их раздобыть $B$BПервая называется Фолиант Сумерек. Им владеет орочий чернокнижник Пустоклят. Вторая, Книга Забытых Имен, находится у араккоа, известного как Темнопряд Сит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Калинна Латред требует отыскать и принести ей Фолиант Сумерек и Книгу Забытых Имен. Первой владеет главный чернокнижник Пустоклят, его можно найти в Разрушенных залах Цитадели Адского Пламени. Вторая принадлежит Темнопряду Ситу, который находится в Сетеккских залах в Аукиндоне.$B$BЭто задание должно быть выполнено в героическом режиме.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калинне Латред в Пустоверть.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (9638,'В хороших руках','Мне надо было искать эти записи? Быть того не может. Не помню ничего подобного.$B$BНу конечно! Ты имеешь в виду Градава. Это он искал какую-то книгу, когда я тут торчал. Мне кажется, вряд ли он до сих пор сумел ее отыскать. А почему бы тебе не поговорить с ним лично?$B$BЯ б тебе помог, но... эти книги такие... захватывающие!','Не видишь, что ли, что я очень занят? Чего тебе нужно?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В хороших руках',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне надо было искать эти записи? Быть того не может. Не помню ничего подобного.$B$BНу конечно! Ты имеешь в виду Градава. Это он искал какую-то книгу, когда я тут торчал. Мне кажется, вряд ли он до сих пор сумел ее отыскать. А почему бы тебе не поговорить с ним лично?$B$BЯ б тебе помог, но... эти книги такие... захватывающие!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не видишь, что ли, что я очень занят? Чего тебе нужно?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9639,'Камсис','Дневник, какой дневник? Конечно, ты имеешь в виду Камсис.$B$BСтупай и спроси ее об этом. Если я сейчас оторвусь от работы, то все пойдет насмарку!','Поговорите с Камсис в Библиотеке Стража в Каражане.','Эти записи, о которых ты говоришь... Меня послали найти их, да?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Камсис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дневник, какой дневник? Конечно, ты имеешь в виду Камсис.$B$BСтупай и спроси ее об этом. Если я сейчас оторвусь от работы, то все пойдет насмарку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Камсис в Библиотеке Стража в Каражане.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти записи, о которых ты говоришь... Меня послали найти их, да?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9640,'Тень Арана','Дай мне подумать секунду. Аметистовое Око... Журнал Медива... Да, теперь я что-то припоминаю.$B$BМне кажется, у меня был этот журнал, пока я не начала читать эти манускрипты...$B$BАран... Да, Аран тоже спрашивал меня об этой книге. Правда, какое милое совпадение? Так и есть, должно быть, я отдала книгу ему. В конце концов, он же отец Медива.','Вернитесь к Камсис в Каражан.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тень Арана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дай мне подумать секунду. Аметистовое Око... Журнал Медива... Да, теперь я что-то припоминаю.$B$BМне кажется, у меня был этот журнал, пока я не начала читать эти манускрипты...$B$BАран... Да, Аран тоже спрашивал меня об этой книге. Правда, какое милое совпадение? Так и есть, должно быть, я отдала книгу ему. В конце концов, он же отец Медива.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Камсис в Каражан.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9641,'Осколки облученного кристалла','В результате крушения "Экзодара" фрагменты оскверненных кристаллов оказались разбросанными по всему острову Кровавой Дымки; их скверна отравила воды и землю.$B$BМы обнаруживали осколки кристаллов даже в плоти животных, добытых на охоте. Однако я нашел способ очищать кристаллы от скверны и использовать их по назначению. Если ты принесешь мне достаточное количество осколков, взамен я отдам тебе один из целых кристаллов. Думаю, тебе нужно знать, что осколки обнаруживались в телах медведей, опустошителей, бражников и древней, обитающих в оскверненной части острова.','Принесите 10 осколков облученного кристалла воздаятелю Боросу на Кровавую заставу.','Неплохо. Теперь у меня есть исходные материалы для воссоздания кристаллов.$B$BТы можешь выбрать один из трех видов кристаллов, которые я могу создать. Каждый вид хорош для охоты на определенную добычу...','Ну как, удалось тебе собрать осколки кристаллов? Я говорил, их можно найти в телах животных и на стволах деревьев...','Вернитесь к воздаятелю Боросу на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осколки облученного кристалла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В результате крушения "Экзодара" фрагменты оскверненных кристаллов оказались разбросанными по всему острову Кровавой Дымки; их скверна отравила воды и землю.$B$BМы обнаруживали осколки кристаллов даже в плоти животных, добытых на охоте. Однако я нашел способ очищать кристаллы от скверны и использовать их по назначению. Если ты принесешь мне достаточное количество осколков, взамен я отдам тебе один из целых кристаллов. Думаю, тебе нужно знать, что осколки обнаруживались в телах медведей, опустошителей, бражников и древней, обитающих в оскверненной части острова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 осколков облученного кристалла воздаятелю Боросу на Кровавую заставу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо. Теперь у меня есть исходные материалы для воссоздания кристаллов.$B$BТы можешь выбрать один из трех видов кристаллов, которые я могу создать. Каждый вид хорош для охоты на определенную добычу...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось тебе собрать осколки кристаллов? Я говорил, их можно найти в телах животных и на стволах деревьев...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Боросу на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9642,'И снова облученные кристаллы','Если у тебя есть еще облученные осколки, я с радостью обменяю их на свои кристаллы.','Вернитесь к воздаятелю Боросу на Остров Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И снова облученные кристаллы',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя есть еще облученные осколки, я с радостью обменяю их на свои кристаллы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Боросу на Остров Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9643,'Удушающая лоза','У хорошего лесника все идет в дело, |3-6($c). Даже самые странные существа зачастую обладают весьма полезными для нас особенностями.$B$BСолнечные Ястребы постоянно нападают на Кровавую заставу; тут уж все средства защиты хороши, не исключая и ловушки. Мне тут на ум пришла одна ловушка, для которой прекрасно подойдет колючая лоза. Острые шипы и смертельный яд – прекрасная комбинация, которая надолго отобъет охоту у любого соваться на заставу. Принеси мне несколько побегов мутировавшей удушающей лозы, и я немедленно примусь за работу.','Принесите зверолову Лисеону 6 побегов колючей удушающей лозы.','Что, удалось тебе добыть побеги?','Вернитесь к зверолову Лисеону на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удушающая лоза',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У хорошего лесника все идет в дело, |3-6($c). Даже самые странные существа зачастую обладают весьма полезными для нас особенностями.$B$BСолнечные Ястребы постоянно нападают на Кровавую заставу; тут уж все средства защиты хороши, не исключая и ловушки. Мне тут на ум пришла одна ловушка, для которой прекрасно подойдет колючая лоза. Острые шипы и смертельный яд – прекрасная комбинация, которая надолго отобъет охоту у любого соваться на заставу. Принеси мне несколько побегов мутировавшей удушающей лозы, и я немедленно примусь за работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите зверолову Лисеону 6 побегов колючей удушающей лозы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что, удалось тебе добыть побеги?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к зверолову Лисеону на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9644,'Ночная Погибель','Невероятно! Вам удалось добыть не только записи Медива, но даже часть его собственной сущности. $B$BХотя эта сущность невероятно слаба, она все равно сумеет дать нам жизненно важные сведения о Медиве. Мы не забудем того, что вы для нас сделали.','Что за новости ты $Gпринес:принесла;, $N?','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ночная Погибель',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно! Вам удалось добыть не только записи Медива, но даже часть его собственной сущности. $B$BХотя эта сущность невероятно слаба, она все равно сумеет дать нам жизненно важные сведения о Медиве. Мы не забудем того, что вы для нас сделали.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что за новости ты $Gпринес:принесла;, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`endtext_loc8`) VALUES (9645,'Просто позор, что наши люди поддались магии Каражана. Ну, по крайней мере, тебе удалось добыть то, за чем их послали.','Запись прочитана') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Просто позор, что наши люди поддались магии Каражана. Ну, по крайней мере, тебе удалось добыть то, за чем их послали.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Запись прочитана',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9646,'РАЗЫСКИВАЕТСЯ: Коготь Смерти','Принесите лапу Когтя Смерти предвестнику Миколаасу на Кровавую заставу.','Чем могу служить, |3-6($c)?','Вернитесь к предвестнику Миколаасу на Остров Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РАЗЫСКИВАЕТСЯ: Коготь Смерти',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите лапу Когтя Смерти предвестнику Миколаасу на Кровавую заставу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем могу служить, |3-6($c)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Миколаасу на Остров Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9647,'Ловля бражников','Когда мы впервые столкнулись с бражниками, мы не заметили у них никаких отклонений. Однако скверна расползалась по острову, и вскоре у всех живых существ начали проявляться признаки заражения.$B$BДошло до того, что бражники, прежде не доставлявшие нам особого беспокойства, начали разрушать все, с чем соприкасаются. Как будто мало вреда было от кристаллов, усеявших все вокруг после крушения "Экзодара"!.. У нас просто не оставалось иного выбора: приходится отлавливать их, чтобы хоть немного исправить ситуацию в землях к северу от Кровавой заставы.','Зверолов Лисеон просит убить 10 царственных синих бражников.','Как дела с ловлей бабочек?','Вернитесь к зверолову Лисеону на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловля бражников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда мы впервые столкнулись с бражниками, мы не заметили у них никаких отклонений. Однако скверна расползалась по острову, и вскоре у всех живых существ начали проявляться признаки заражения.$B$BДошло до того, что бражники, прежде не доставлявшие нам особого беспокойства, начали разрушать все, с чем соприкасаются. Как будто мало вреда было от кристаллов, усеявших все вокруг после крушения "Экзодара"!.. У нас просто не оставалось иного выбора: приходится отлавливать их, чтобы хоть немного исправить ситуацию в землях к северу от Кровавой заставы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зверолов Лисеон просит убить 10 царственных синих бражников.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как дела с ловлей бабочек?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к зверолову Лисеону на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`completedtext_loc8`) VALUES (9648,'А известно ли тебе, что грибная охота намного опаснее, чем поглощение грибов? Грибники подвергают себя множеству неведомых опасностей – ведь в лесу видимо-невидимо разных тварей!$B$BС другой стороны, что такое жизнь без риска? К тому же мне нужны грибы. Для коллекции. В здешних неисследованных землях можно найти четыре весьма любопытных типа грибов: водянистый смрадорог, кровавый гриб, губительную полиспору и поганку конусовидную. В каждом регионе острова Кровавой Дымки растет только один из видов этих грибов. Принеси их мне.','Вернитесь к Джессере из Мак\'Ари на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А известно ли тебе, что грибная охота намного опаснее, чем поглощение грибов? Грибники подвергают себя множеству неведомых опасностей – ведь в лесу видимо-невидимо разных тварей!$B$BС другой стороны, что такое жизнь без риска? К тому же мне нужны грибы. Для коллекции. В здешних неисследованных землях можно найти четыре весьма любопытных типа грибов: водянистый смрадорог, кровавый гриб, губительную полиспору и поганку конусовидную. В каждом регионе острова Кровавой Дымки растет только один из видов этих грибов. Принеси их мне.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джессере из Мак\'Ари на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9649,'Слеза Изеры','Рад снова тебя видеть, $n! Тебе просто блестяще удалось выполнить мое предыдущее задание. Так вот, я тут подумал: может, тебя не затруднит выполнить еще одну небольшую просьбу?$B$BК северо-востоку отсюда находится остров Драконьей Скорби, где можно отыскать редчайшую разновидность грибов, именуемую "Слезой Изеры" – это в честь зеленых дракончиков, обитающих на острове. Нет, сами грибы не зеленые. А какая тут связь?.. Хм, позволь мне не вдаваться в подробности. Мне нужен только малюсенький образец этих грибов... Да, совсем забыл: обитатели острова не слишком гостеприимны, так что будь поосторожнее...','Что, ты уже $Gвернулся:вернулась;?.. Так быстро?','Вернитесь к Джессере из Мак\'Ари на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слеза Изеры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рад снова тебя видеть, $n! Тебе просто блестяще удалось выполнить мое предыдущее задание. Так вот, я тут подумал: может, тебя не затруднит выполнить еще одну небольшую просьбу?$B$BК северо-востоку отсюда находится остров Драконьей Скорби, где можно отыскать редчайшую разновидность грибов, именуемую "Слезой Изеры" – это в честь зеленых дракончиков, обитающих на острове. Нет, сами грибы не зеленые. А какая тут связь?.. Хм, позволь мне не вдаваться в подробности. Мне нужен только малюсенький образец этих грибов... Да, совсем забыл: обитатели острова не слишком гостеприимны, так что будь поосторожнее...',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что, ты уже $Gвернулся:вернулась;?.. Так быстро?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джессере из Мак\'Ари на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9650,'Deprecated: Приращение магии','*TXT*Ну хорошо, давай усилим мои магические способности. В этом есть определенный смысл – в конце концов, при жизни я была волшебницей.$B$BИ то, что я превратилась в оружие, никак не отразилось на моей способности соображать!$B$BНам понадобится собрать кое-какие ингредиенты.','<TXT>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Deprecated: Приращение магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*TXT*Ну хорошо, давай усилим мои магические способности. В этом есть определенный смысл – в конце концов, при жизни я была волшебницей.$B$BИ то, что я превратилась в оружие, никак не отразилось на моей способности соображать!$B$BНам понадобится собрать кое-какие ингредиенты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','<TXT>',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9651,'Deprecated: Приращение магии','*TXT*Ну хорошо, давай усилим мои магические способности. Это имеет смысл. В конце концов, при жизни я была волшебницей.$B$BИ то, что я была вынуждена превратиться в оружие, никак не отразилось на моей способности соображать $B$BНам понадобится собрать кое-какие ингредиенты.','<TXT>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Deprecated: Приращение магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*TXT*Ну хорошо, давай усилим мои магические способности. Это имеет смысл. В конце концов, при жизни я была волшебницей.$B$BИ то, что я была вынуждена превратиться в оружие, никак не отразилось на моей способности соображать $B$BНам понадобится собрать кое-какие ингредиенты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','<TXT>',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (9652,'Deprecated: Физическое усиление','О, я бы не отказалась. Мы должны выжать все, что возможно, из сложившейся ситуации... В моем случае, из того, что я оказалась оружием. Значит, я должна стать самым лучшим оружием, каким смогу.$B$BДавай, попробуем. Заострить лезвие, укрепить рукоять... мне нравится, как это звучит.$B$BПравда, для этого понадобятся кое-какие материалы.','Вернитесь к Грани Кинны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Deprecated: Физическое усиление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, я бы не отказалась. Мы должны выжать все, что возможно, из сложившейся ситуации... В моем случае, из того, что я оказалась оружием. Значит, я должна стать самым лучшим оружием, каким смогу.$B$BДавай, попробуем. Заострить лезвие, укрепить рукоять... мне нравится, как это звучит.$B$BПравда, для этого понадобятся кое-какие материалы.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грани Кинны.',`completedtext_loc8`);
