INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9654,'Deprecated: хорошо поставленная круговая оборона','Боевая магия всегда была моим коньком... Насколько я помню. Я сделаю все, что смогу, чтобы передать тебе свою силу.$B$BНо для этого понадобится больше магической энергии, чем у меня есть. В качестве нее можно использовать магические аномалии, которые гуляют по верхним уровням Библиотеки Стража. Собери осадки их чар, они нам понадобятся в большом количестве.','Грань Кинны, находящаяся внутри Завещания Кинны, просит вас собрать 20 осадков чар магических аномалий Каражана.','Вернитесь к Грани Кинны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Deprecated: хорошо поставленная круговая оборона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боевая магия всегда была моим коньком... Насколько я помню. Я сделаю все, что смогу, чтобы передать тебе свою силу.$B$BНо для этого понадобится больше магической энергии, чем у меня есть. В качестве нее можно использовать магические аномалии, которые гуляют по верхним уровням Библиотеки Стража. Собери осадки их чар, они нам понадобятся в большом количестве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Грань Кинны, находящаяся внутри Завещания Кинны, просит вас собрать 20 осадков чар магических аномалий Каражана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грани Кинны.',`completedtext_loc8`);
