INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9661,'Deprecated: Хорошая круговая оборона','Боевая магия всегда была моим коньком... Насколько я помню. Я сделаю все, что смогу, чтобы передать тебе свою силу.$B$BНо для этого понадобится больше магической энергии, чем у меня есть. В качестве нее можно использовать магические аномалии, которые гуляют по верхним уровням Библиотеки Стража. Собери осадки их чар, они нам понадобятся в большом количестве.','Грань Кинны, находящаяся внутри Завещания Кинны, просит вас собрать 20 осадков чар магических аномалий Каражана.','Вернитесь к Грани Кинны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Deprecated: Хорошая круговая оборона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боевая магия всегда была моим коньком... Насколько я помню. Я сделаю все, что смогу, чтобы передать тебе свою силу.$B$BНо для этого понадобится больше магической энергии, чем у меня есть. В качестве нее можно использовать магические аномалии, которые гуляют по верхним уровням Библиотеки Стража. Собери осадки их чар, они нам понадобятся в большом количестве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Грань Кинны, находящаяся внутри Завещания Кинны, просит вас собрать 20 осадков чар магических аномалий Каражана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грани Кинны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9662,'Deprecated: Кинна обретает свободу','Моя память... Я все помню!!! Такое ощущение, будто все кусочки воспоминаний сложились в единое целое.$B$BЯ была одной из первых, кого послали исследовать изменившийся Каражан. Меня обнаружил демон по имени Малчезар.$B$BСразу стало понятно, что мне с ним не тягаться. Мою душу затягивало в ловушку его магии.$B$BНо в последний момент мне удалось скрыть маленький кусочек самой себя... своей памяти... внутри единственного предмета, о котором я успела подумать: в своем мече. Моя душа в плену у Малчезара. Ты $gдолжен:должна; помочь мне вернуть ее!','Уничтожьте Малчезара по просьбе Завещания Кинны. Грань Кинны должна уцелеть. Не забудьте взять завещание с собой.','Вернитесь к Грани Кинны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Deprecated: Кинна обретает свободу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя память... Я все помню!!! Такое ощущение, будто все кусочки воспоминаний сложились в единое целое.$B$BЯ была одной из первых, кого послали исследовать изменившийся Каражан. Меня обнаружил демон по имени Малчезар.$B$BСразу стало понятно, что мне с ним не тягаться. Мою душу затягивало в ловушку его магии.$B$BНо в последний момент мне удалось скрыть маленький кусочек самой себя... своей памяти... внутри единственного предмета, о котором я успела подумать: в своем мече. Моя душа в плену у Малчезара. Ты $gдолжен:должна; помочь мне вернуть ее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Малчезара по просьбе Завещания Кинны. Грань Кинны должна уцелеть. Не забудьте взять завещание с собой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Грани Кинны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9663,'Путь Кессела','Сообщите верховному вождю клана Тихвой, экзарху Менелаусу и адмиралу Одиссию о готовящемся вторжении эльфов крови, а затем возвратитесь к Кесселу. На все отводится 15 минут. Элекка следует держать подальше от воды.','Спеши! Времени мало!','Вернитесь к Кесселу на Остров Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Кессела',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сообщите верховному вождю клана Тихвой, экзарху Менелаусу и адмиралу Одиссию о готовящемся вторжении эльфов крови, а затем возвратитесь к Кесселу. На все отводится 15 минут. Элекка следует держать подальше от воды.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Спеши! Времени мало!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кесселу на Остров Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9664,'Новые форпосты','Добро пожаловать в Чумные земли, $n. Как тебе известно, Отрекшиеся и их приспешники удерживают земли к западу отсюда, несмотря на все наши усилия. Командующие Альянса приняли решение укрепить наши прифронтовые позиции, завоевав новые укрепления.$B$BБашни, давно заброшенные и позабытые еще в дни Лордерона, необходимо захватить и восстановить. Это очень опасные земли, и нам потребуется твоя помощь.','Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и Башню Чумного леса в Восточных Чумных землях и вернитесь к посланнику Белобороду в Часовню Последней Надежды.','Превосходно, $n. Теперь необходимо удерживать эти башни до прибытия подкрепления – для этого нам потребуется твоя помощь.','Вернитесь к эмиссару Белобороду в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые форпосты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в Чумные земли, $n. Как тебе известно, Отрекшиеся и их приспешники удерживают земли к западу отсюда, несмотря на все наши усилия. Командующие Альянса приняли решение укрепить наши прифронтовые позиции, завоевав новые укрепления.$B$BБашни, давно заброшенные и позабытые еще в дни Лордерона, необходимо захватить и восстановить. Это очень опасные земли, и нам потребуется твоя помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и Башню Чумного леса в Восточных Чумных землях и вернитесь к посланнику Белобороду в Часовню Последней Надежды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно, $n. Теперь необходимо удерживать эти башни до прибытия подкрепления – для этого нам потребуется твоя помощь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к эмиссару Белобороду в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9665,'Укрепим оборону','Разведчики Отрекшихся раскрыли планы Альянса создать новые форпосты в Восточных Чумных землях на базе заброшенных башен.$B$BНельзя позволить им закрепиться на наших восточных границах, поэтому необходимо помешать планам Альянса. Мы должны выманить их войска из тех башен, которые они уже успели захватить, и занять те, которые еще не были захвачены.','Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и Башню Чумного леса в Восточных Чумных землях и возвращайтесь к посланнику Гормоку в Часовню Последней Надежды.','Это хорошие новости, $N. Здесь, в Чумных землях, будет постоянная борьба, пока мы полностью не отбросим силы Альянса. $B$BДо этого дня я надеюсь, что мы будем получать от тебя постоянную помощь.','Они, должно быть, глупцы,если полагают, что мы позволим им создавать базы так близко к одной из наших столиц.$B$BМы будем сокращать их численность, пока они не свернут и не отступят на юг.','Вернитесь к эмиссару Гормоку в Часовню Последней Надежды, что в Восточных Чумных землях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Укрепим оборону',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разведчики Отрекшихся раскрыли планы Альянса создать новые форпосты в Восточных Чумных землях на базе заброшенных башен.$B$BНельзя позволить им закрепиться на наших восточных границах, поэтому необходимо помешать планам Альянса. Мы должны выманить их войска из тех башен, которые они уже успели захватить, и занять те, которые еще не были захвачены.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Захватите башню Королевской Стражи, Восточную башню, Башню Северного перевала и Башню Чумного леса в Восточных Чумных землях и возвращайтесь к посланнику Гормоку в Часовню Последней Надежды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это хорошие новости, $N. Здесь, в Чумных землях, будет постоянная борьба, пока мы полностью не отбросим силы Альянса. $B$BДо этого дня я надеюсь, что мы будем получать от тебя постоянную помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Они, должно быть, глупцы,если полагают, что мы позволим им создавать базы так близко к одной из наших столиц.$B$BМы будем сокращать их численность, пока они не свернут и не отступят на юг.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к эмиссару Гормоку в Часовню Последней Надежды, что в Восточных Чумных землях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9666,'Демонстрация силы','Тебе уже доводилось видеть змеелюдей? Тех самых, которые называют себя нагами?$B$B<Кессел с отвращением сплевывает.>$B$BТри ночи прошло с тех пор, как они осмелились напасть на этот лагерь. Примитивные твари! Какова наглость, а?$B$BПослушай, $n, я хочу, чтобы ты кое-что $Gсделал:сделала; для меня. На северо-востоке отсюда находится логово Зловещей Чешуи, где обитает Лорд Ксиз. Найди его, убей и пронзи его тело древком этого знамени!$B$BПусть скользкие твари трепещут при виде нашего штандарта!','Дело сделано?','Демонстрация силы','Вернитесь к Кесселу на Перекресток Кессела, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонстрация силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе уже доводилось видеть змеелюдей? Тех самых, которые называют себя нагами?$B$B<Кессел с отвращением сплевывает.>$B$BТри ночи прошло с тех пор, как они осмелились напасть на этот лагерь. Примитивные твари! Какова наглость, а?$B$BПослушай, $n, я хочу, чтобы ты кое-что $Gсделал:сделала; для меня. На северо-востоке отсюда находится логово Зловещей Чешуи, где обитает Лорд Ксиз. Найди его, убей и пронзи его тело древком этого знамени!$B$BПусть скользкие твари трепещут при виде нашего штандарта!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дело сделано?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Демонстрация силы',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кесселу на Перекресток Кессела, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9667,'Спасение принцессы Тихвои','Умоляю тебя, $n, помоги мне! Меня взяли в плен фурболги из племени Косолапов. Они хотят принести меня в жертву их нечистым богам!$B$BКлюч от клетки – у вождя клана. Но он так просто здесь не объявится. Чтобы вынудить вождя сделать это, тебе придется убить обитающих здесь фурболгов – уничтожить два лагеря племени Косолапов к западу отсюда. Не сомневайся: вождь непременно придет, чтобы отомстить за смерть соплеменников – а когда это произойдет, ты убьешь его и заберешь ключ.$B$BЕсли ты спасешь меня, мой отец не поскупится на награду!','Выпустите принцессу Тихвою из клетки, а затем найдите на Кровавой заставе посла племени Тихвой Фрасабу и поговорите с ним.$B$BЧтобы раздобыть ключ от клетки, убейте верховного вождя племени Косолапов.','И вот еще одно доказательство тому, что пророчества говорили именно о тебе. Прими же мою вечную благодарность, $n, а в придачу – одну из этих реликвий племени Тихвой…','У меня мало времени, $N. Они скоро меня убьют...','Вернитесь к послу племени Тихвой Фрасабу на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение принцессы Тихвои',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Умоляю тебя, $n, помоги мне! Меня взяли в плен фурболги из племени Косолапов. Они хотят принести меня в жертву их нечистым богам!$B$BКлюч от клетки – у вождя клана. Но он так просто здесь не объявится. Чтобы вынудить вождя сделать это, тебе придется убить обитающих здесь фурболгов – уничтожить два лагеря племени Косолапов к западу отсюда. Не сомневайся: вождь непременно придет, чтобы отомстить за смерть соплеменников – а когда это произойдет, ты убьешь его и заберешь ключ.$B$BЕсли ты спасешь меня, мой отец не поскупится на награду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выпустите принцессу Тихвою из клетки, а затем найдите на Кровавой заставе посла племени Тихвой Фрасабу и поговорите с ним.$B$BЧтобы раздобыть ключ от клетки, убейте верховного вождя племени Косолапов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И вот еще одно доказательство тому, что пророчества говорили именно о тебе. Прими же мою вечную благодарность, $n, а в придачу – одну из этих реликвий племени Тихвой…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У меня мало времени, $N. Они скоро меня убьют...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к послу племени Тихвой Фрасабу на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9668,'Доклад экзарху Адметиусу','Солдат Длани Аргуса должен обладать многими качествами: быть покорным, отважным, разумным – но прежде всего благородным. Надеюсь, у тебя еще будет возможность проявить хотя бы часть этих качеств, |3-6($c).$B$BЕсли ты все еще хочешь присоединиться к братству Длани, отправляйся на Кровавую заставу к экзарху Адметиусу. Он и его подчиненные обучат тебя и превратят в настоящего солдата дренеев. Насколько это возможно.$B$BИ вот еще что запомни, $n: не всегда благородные существа ведут себя честно и благородно. Иногда они просто не могут позволить себе этого.$B$BНу, довольно болтовни, отправляйся на Кровавую заставу – это прямо по дороге на север.','Разыщите на Кровавой заставе экзарха Адметиуса и поговорите с ним.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доклад экзарху Адметиусу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Солдат Длани Аргуса должен обладать многими качествами: быть покорным, отважным, разумным – но прежде всего благородным. Надеюсь, у тебя еще будет возможность проявить хотя бы часть этих качеств, |3-6($c).$B$BЕсли ты все еще хочешь присоединиться к братству Длани, отправляйся на Кровавую заставу к экзарху Адметиусу. Он и его подчиненные обучат тебя и превратят в настоящего солдата дренеев. Насколько это возможно.$B$BИ вот еще что запомни, $n: не всегда благородные существа ведут себя честно и благородно. Иногда они просто не могут позволить себе этого.$B$BНу, довольно болтовни, отправляйся на Кровавую заставу – это прямо по дороге на север.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите на Кровавой заставе экзарха Адметиуса и поговорите с ним.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9669,'Пропавшая экспедиция','Около недели назад мы проводили разведку западных пустошей острова Кровавой Дымки, когда на нас напали кровожадные пауки. Насколько я могу судить, их размеры и чрезвычайная агрессивность обусловлены действием кристаллов.$B$BМне удалось спастись, но моим спутникам повезло меньше. Нельзя допустить, чтобы и других постигла та же печальная участь. Отправляйся на запад к перевалу Янтарной паутины: нужно уничтожить пауков и их матриарха Зарак.','Убейте 8 пауков-ткачих, 8 паучих-кровопийц и матриарха пауков – Зарак. По завершении задания вернитесь на Кровавую заставу к Акелусу.','Это было ужасно...','Вернитесь к Акелусу на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшая экспедиция',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Около недели назад мы проводили разведку западных пустошей острова Кровавой Дымки, когда на нас напали кровожадные пауки. Насколько я могу судить, их размеры и чрезвычайная агрессивность обусловлены действием кристаллов.$B$BМне удалось спастись, но моим спутникам повезло меньше. Нельзя допустить, чтобы и других постигла та же печальная участь. Отправляйся на запад к перевалу Янтарной паутины: нужно уничтожить пауков и их матриарха Зарак.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 пауков-ткачих, 8 паучих-кровопийц и матриарха пауков – Зарак. По завершении задания вернитесь на Кровавую заставу к Акелусу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это было ужасно...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Акелусу на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9670,'Они живы! Может быть...','Ты представить себе не можешь, $n, что мне пришлось пережить! Ужас! Кошмарный сон!.. На нас набросились пауки, будь они прокляты, да к тому же их прародительница, чтоб у нее все лапы поотсыхали, как с неба свалилась и тут же запеленала нас всех в коконы!$B$BНо это было еще полбеды, эта членистоногая зараза пристроилась рядом с нами и начала откладывать яйца! Представляешь? Она решила, что мы – отличный корм для ее молодняка. КОРМ! Вообрази только!$B$BМне-то кое-как удалось выбраться, а мои товарищи так и валяются там, спеленутые, как младенцы. В одиночку мне их не спасти, я даже близко не могу подойти к тому проклятому месту. Ты ведь поможешь мне, верно?$B$BРаспутай коконы! Может, хоть кто-то еще из наших остался в живых!','Освободите 5 ученых экспедиции по просьбе ученого Корнелиуса.','Ну, как дела?','Вернитесь к ученому Корнелиусу на Перевал Янтарной Паутины, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они живы! Может быть...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты представить себе не можешь, $n, что мне пришлось пережить! Ужас! Кошмарный сон!.. На нас набросились пауки, будь они прокляты, да к тому же их прародительница, чтоб у нее все лапы поотсыхали, как с неба свалилась и тут же запеленала нас всех в коконы!$B$BНо это было еще полбеды, эта членистоногая зараза пристроилась рядом с нами и начала откладывать яйца! Представляешь? Она решила, что мы – отличный корм для ее молодняка. КОРМ! Вообрази только!$B$BМне-то кое-как удалось выбраться, а мои товарищи так и валяются там, спеленутые, как младенцы. В одиночку мне их не спасти, я даже близко не могу подойти к тому проклятому месту. Ты ведь поможешь мне, верно?$B$BРаспутай коконы! Может, хоть кто-то еще из наших остался в живых!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 5 ученых экспедиции по просьбе ученого Корнелиуса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как дела?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученому Корнелиусу на Перевал Янтарной Паутины, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9671,'Срочная доставка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Срочная доставка',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9672,'Наследие проклятых','Дорогой друг!$B$BПеро дрожит в моих руках, когда я пишу эти строки. Надеюсь, ты получишь письмо вовремя.$B$BПрошлой ночью в моем шатре появился Эдвард Хейнс, капитан "Утерянной Надежды". Да-да, тот самый Эдвард Хейнс, который умер от цинги двадцать лет назад.$B$BПризрак поведал мне историю, от которой кровь застыла у меня в жилах. Тебе непременно нужно услышать эту историю – и выполнить одно задание. Прошу тебя, разыщи Эдварда на острове Драконьей Скорби; ты сможешь найти его к северо-востоку от своего лагеря.$B$BС наилучшими пожеланиями,$B$BАдмирал Одиссий.','Адмирал Одиссий просит разыскать капитана Эдварда Хейнса и поговорить с ним.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие проклятых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дорогой друг!$B$BПеро дрожит в моих руках, когда я пишу эти строки. Надеюсь, ты получишь письмо вовремя.$B$BПрошлой ночью в моем шатре появился Эдвард Хейнс, капитан "Утерянной Надежды". Да-да, тот самый Эдвард Хейнс, который умер от цинги двадцать лет назад.$B$BПризрак поведал мне историю, от которой кровь застыла у меня в жилах. Тебе непременно нужно услышать эту историю – и выполнить одно задание. Прошу тебя, разыщи Эдварда на острове Драконьей Скорби; ты сможешь найти его к северо-востоку от своего лагеря.$B$BС наилучшими пожеланиями,$B$BАдмирал Одиссий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Адмирал Одиссий просит разыскать капитана Эдварда Хейнса и поговорить с ним.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9673,'Дрессировка','Тебе удалось приручить питомца, но теперь нужно его выдрессировать. Обратись к Хальтенису, лучшему дрессировщику Луносвета.$b$bХальтенис всегда рад моим ученикам. Прояви уважение – и он обязательно поможет тебе. Удачи!','Поговорите с Хальтенисом в Луносвете.','Итак, вы узнали немного, не так ли?$B$B<Халтенис внимательно смотрит на вас.>$B$BВы будете служить городу и нашему великому делу, хорошо используя свои недавно приобретенные навыки. Позвольте мне показать вам, как приучить вашего питомца к некоторым интересным трюкам, таким как выпотрошить врага, и вы сможете отправиться в путь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дрессировка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось приручить питомца, но теперь нужно его выдрессировать. Обратись к Хальтенису, лучшему дрессировщику Луносвета.$b$bХальтенис всегда рад моим ученикам. Прояви уважение – и он обязательно поможет тебе. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Хальтенисом в Луносвете.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, вы узнали немного, не так ли?$B$B<Халтенис внимательно смотрит на вас.>$B$BВы будете служить городу и нашему великому делу, хорошо используя свои недавно приобретенные навыки. Позвольте мне показать вам, как приучить вашего питомца к некоторым интересным трюкам, таким как выпотрошить врага, и вы сможете отправиться в путь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9674,'Проклятые наги','Говорят, когда мир раскололся, эти земли возопили... Именно здесь канули в бездну забвения тысячи ночных эльфов, а вместо них в мир вступили чудовищные твари, порождение ночных кошмаров – наги.$B$BНаги повиновались лишь своей королеве Азшаре; они уничтожали любого, кто решался плыть по их морям. Так было тысячи лет... но теперь, возможно, все переменится.$B$BПервым делом нужно будет истребить проклятых наг на этом рифе.','Капитан Эдвард Хейнс с острова Драконьей Скорби просит убить 10 проклятых наг.','Отличное начало – но только начало...','Невероятно мерзкие твари эти наги...','Вернитесь к капитану Эдварду Хейнсу на Остров Драконьей Скорби, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятые наги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, когда мир раскололся, эти земли возопили... Именно здесь канули в бездну забвения тысячи ночных эльфов, а вместо них в мир вступили чудовищные твари, порождение ночных кошмаров – наги.$B$BНаги повиновались лишь своей королеве Азшаре; они уничтожали любого, кто решался плыть по их морям. Так было тысячи лет... но теперь, возможно, все переменится.$B$BПервым делом нужно будет истребить проклятых наг на этом рифе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Эдвард Хейнс с острова Драконьей Скорби просит убить 10 проклятых наг.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличное начало – но только начало...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Невероятно мерзкие твари эти наги...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эдварду Хейнсу на Остров Драконьей Скорби, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9675,'Дрессировка','Да, и еще одно! Тебе не помешает поговорить с Ганааром из Экзодара. Он научит тебя заботиться о твоем питомце и дрессировать его.$B$BГанаара можно отыскать в юго-западном углу Торгового ряда.','Поговорите с Ганааром в Торговом ряду Экзодара.','Умение кормить и оживлять своего питомца от смерти - это не просто дать дополнительный лакомый кусочек и оживлять его, как мягко выразился ваш последний учитель. Более того, дрессировка позволяет вашему питомцу совершенствоваться так, как он не мог бы добиться самостоятельно. $B$BЯ уже многому научился у фурболгов, поэтому будьте внимательнее и я передам вам эти знания.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дрессировка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, и еще одно! Тебе не помешает поговорить с Ганааром из Экзодара. Он научит тебя заботиться о твоем питомце и дрессировать его.$B$BГанаара можно отыскать в юго-западном углу Торгового ряда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ганааром в Торговом ряду Экзодара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Умение кормить и оживлять своего питомца от смерти - это не просто дать дополнительный лакомый кусочек и оживлять его, как мягко выразился ваш последний учитель. Более того, дрессировка позволяет вашему питомцу совершенствоваться так, как он не мог бы добиться самостоятельно. $B$BЯ уже многому научился у фурболгов, поэтому будьте внимательнее и я передам вам эти знания.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9677,'Призыв предводителя рыцарей Доблестной Крови','$n, ты $gпреуспел:преуспела; в начале своего обучения и $gсумел:сумела; отличиться среди тех, кто жаждет стать рыцарями крови. Ты $gготов:готова; к следующему этапу обучения. Сам предводитель рыцарей Доблестная Кровь желает поговорить с тобой.$b$bНе сомневаюсь, предводитель устроит тебе испытание, чтобы проверить твои способности и уровень обучения. Ты найдешь его в штабе рыцарей крови на площади Странников в Луносвете. Желаю удачи, $n!','Поговорите с предводителем рыцарей Доблестной Кровью на площади Странников в Луносвете.','Приветствую, $Gпослушник:послушница;. То, что ты $Gответил:ответила; на мой призыв так быстро, служит хорошим предзнаменованием для тебя. $B$BНо давай обойдемся без шуток, так как они лучше всего подходят для придворных и иже с ними. $B$BТвой быстрый рост привлек мое внимание, $N. И мы хотим увидеть, насколько глубоко ты $Gусвоил:усвоила; уроки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв предводителя рыцарей Доблестной Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты $gпреуспел:преуспела; в начале своего обучения и $gсумел:сумела; отличиться среди тех, кто жаждет стать рыцарями крови. Ты $gготов:готова; к следующему этапу обучения. Сам предводитель рыцарей Доблестная Кровь желает поговорить с тобой.$b$bНе сомневаюсь, предводитель устроит тебе испытание, чтобы проверить твои способности и уровень обучения. Ты найдешь его в штабе рыцарей крови на площади Странников в Луносвете. Желаю удачи, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предводителем рыцарей Доблестной Кровью на площади Странников в Луносвете.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приветствую, $Gпослушник:послушница;. То, что ты $Gответил:ответила; на мой призыв так быстро, служит хорошим предзнаменованием для тебя. $B$BНо давай обойдемся без шуток, так как они лучше всего подходят для придворных и иже с ними. $B$BТвой быстрый рост привлек мое внимание, $N. И мы хотим увидеть, насколько глубоко ты $Gусвоил:усвоила; уроки.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9678,'Первое испытание','Ты прекрасно $gосвоил:освоила; искусство сражения, но этого недостаточно.$B$BСосредоточенность и несгибаемая сила воли – вот что отличает настоящего рыцаря Крови от обычного головореза.$B$BХочешь закалить характер? Тогда отправляйся на Остров Напастей, к северо-востоку от Призрачных земель. Там, в одной из пещер, найди жаровню и встань перед ней на колени. Затем разожги в жаровне пламя и не своди глаз с того, что представится твоему взору.','Отправляйтесь на остров, описанный предводителем рыцарей Доблестной Кровью, найдите пещеру и разожгите огонь в жаровне. Пройдя первое испытание, возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.','Я знаю, что, должно быть, происходит у тебя в голове. $B$BЯ послал убийцу к тебе. $B$BНе обижайся, $N; это было необходимое испытание. Рыцари крови - это братство, но мы должны постоянно следить за тем, чтобы наши братья были начеку и были готовы. $B$BДа и это такая же часть твоего обучения, как и любое упражнение на мечах.','Пусть Свет подчиняется вашей воле во всех начинаниях.','Вернитесь к предводителю рыцарей Доблестной Крови в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первое испытание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты прекрасно $gосвоил:освоила; искусство сражения, но этого недостаточно.$B$BСосредоточенность и несгибаемая сила воли – вот что отличает настоящего рыцаря Крови от обычного головореза.$B$BХочешь закалить характер? Тогда отправляйся на Остров Напастей, к северо-востоку от Призрачных земель. Там, в одной из пещер, найди жаровню и встань перед ней на колени. Затем разожги в жаровне пламя и не своди глаз с того, что представится твоему взору.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на остров, описанный предводителем рыцарей Доблестной Кровью, найдите пещеру и разожгите огонь в жаровне. Пройдя первое испытание, возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю, что, должно быть, происходит у тебя в голове. $B$BЯ послал убийцу к тебе. $B$BНе обижайся, $N; это было необходимое испытание. Рыцари крови - это братство, но мы должны постоянно следить за тем, чтобы наши братья были начеку и были готовы. $B$BДа и это такая же часть твоего обучения, как и любое упражнение на мечах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пусть Свет подчиняется вашей воле во всех начинаниях.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предводителю рыцарей Доблестной Крови в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9679,'<NYI>Возвращение к предводителю рыцарей Доблестной Крови','Враг повержен; ты $gпобедил:победила;. Но, похоже, все это не простое совпадение. Возможно, это часть испытания, посланного тебе предводителем рыцарей Доблестной Кровью.$B$BЧто ж, испытание пройдено, а значит, самое время вернуться в Луносвет и потолковать с Доблестной Кровью.','Найдите в Луносвете предводителя рыцарей Доблестную Кровь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI>Возвращение к предводителю рыцарей Доблестной Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Враг повержен; ты $gпобедил:победила;. Но, похоже, все это не простое совпадение. Возможно, это часть испытания, посланного тебе предводителем рыцарей Доблестной Кровью.$B$BЧто ж, испытание пройдено, а значит, самое время вернуться в Луносвет и потолковать с Доблестной Кровью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Луносвете предводителя рыцарей Доблестную Кровь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9680,'Тайны прошлого','Великолепно! Этот маленький костяной обломок буквально лучится энергией, я чувствую это!','Ну как, удалось отыскать нужный фрагмент кости, $N?','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны прошлого',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великолепно! Этот маленький костяной обломок буквально лучится энергией, я чувствую это!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось отыскать нужный фрагмент кости, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9681,'Источник силы','Жестоко? Ну что ты, $n. Безмолвный клинок прекрасно знал, на что идет, и выполнил свой долг с честью и достоинством. Его самоотверженность должна послужить примером для всех нас.$B$BНо это далеко не последний подвиг Безмолвного Клинка, $n. Ему предстоят еще многие свершения. Да-да, ты не $gослышался:ослышалась; – нам нужно воскресить его. И займешься этим именно ты!$B$BДоселе ты $gограничивался:ограничивалась; простыми заклинаниями, но теперь, когда нас предал Кель\'тас, когда мы утеряли источник энергии, тебе придется научиться нести Свет по-новому. Отправляйся к магистру Асталору Кровавой Клятве.','Поговорите с магистром Асталором Кровавой Клятвой в тайной зале, расположенной под штабом рыцарей Крови.','Добро пожаловать, молодой $C. $B$BСила Рыцарей Крови взята у существа огромной силы. $B$B<Магистр указывает на большое пленное существо в центре комнаты.>$B$BРазве это не великолепно? Это подарок от нашего любимого принца Кель\'таса, и это основа мастерства Рыцарей крови Света. Это существо завидует нам своей мощью, поэтому мы разработали способ получить ее на своих условиях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Источник силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жестоко? Ну что ты, $n. Безмолвный клинок прекрасно знал, на что идет, и выполнил свой долг с честью и достоинством. Его самоотверженность должна послужить примером для всех нас.$B$BНо это далеко не последний подвиг Безмолвного Клинка, $n. Ему предстоят еще многие свершения. Да-да, ты не $gослышался:ослышалась; – нам нужно воскресить его. И займешься этим именно ты!$B$BДоселе ты $gограничивался:ограничивалась; простыми заклинаниями, но теперь, когда нас предал Кель\'тас, когда мы утеряли источник энергии, тебе придется научиться нести Свет по-новому. Отправляйся к магистру Асталору Кровавой Клятве.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с магистром Асталором Кровавой Клятвой в тайной зале, расположенной под штабом рыцарей Крови.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать, молодой $C. $B$BСила Рыцарей Крови взята у существа огромной силы. $B$B<Магистр указывает на большое пленное существо в центре комнаты.>$B$BРазве это не великолепно? Это подарок от нашего любимого принца Кель\'таса, и это основа мастерства Рыцарей крови Света. Это существо завидует нам своей мощью, поэтому мы разработали способ получить ее на своих условиях.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9682,'Отчаявшиеся','На краю рифа, глубже, чем обитают проклятые наги, находится обитель отчаявшихся – там обитают проклятые путешественники, неупокоенные призраки тех, кого унесло проклятие...$B$BМне горько, что приходится просить тебя об этом, но... Их должно уничтожить.$B$BОтлученные души должны обрести покой. Вернись ко мне, когда исполнишь все, как нужно, – я дам тебе еще одно, последнее задание.','Капитан Эдвард Хейнс с острова Драконьей Скорби просит освободить 4 отлученных души.','Вернитесь к капитану Эдварду Хейнсу на Остров Драконьей Скорби, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчаявшиеся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На краю рифа, глубже, чем обитают проклятые наги, находится обитель отчаявшихся – там обитают проклятые путешественники, неупокоенные призраки тех, кого унесло проклятие...$B$BМне горько, что приходится просить тебя об этом, но... Их должно уничтожить.$B$BОтлученные души должны обрести покой. Вернись ко мне, когда исполнишь все, как нужно, – я дам тебе еще одно, последнее задание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Эдвард Хейнс с острова Драконьей Скорби просит освободить 4 отлученных души.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эдварду Хейнсу на Остров Драконьей Скорби, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9683,'Избавление от проклятья','К югу отсюда находится остров Проклятой Крови. В центре острова расположено святилище, посвященное возлюбленной королеве наг – Азшаре. Разрушь статую! Уничтожь это чучело! Не сомневаюсь: это разъярит предводителя Проклятых наг, Атофа.$B$BУбей Атофа, а потом возвращайся ко мне.','Капитан Эдвард Хейнс с острова Драконьей Скорби просит уничтожить статую королевы Азшары и убить Атофа Проклятого.','Подумать только! Тебе это удалось!.. Благодарение сотен и сотен душ пребудет с тобой.$B$BПозволь кое-что предложить тебе...','Нужно выманить Атофа из его логова!','Вернитесь к капитану Эдварду Хейнсу на Остров Драконьей Скорби, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Избавление от проклятья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К югу отсюда находится остров Проклятой Крови. В центре острова расположено святилище, посвященное возлюбленной королеве наг – Азшаре. Разрушь статую! Уничтожь это чучело! Не сомневаюсь: это разъярит предводителя Проклятых наг, Атофа.$B$BУбей Атофа, а потом возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Эдвард Хейнс с острова Драконьей Скорби просит уничтожить статую королевы Азшары и убить Атофа Проклятого.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Подумать только! Тебе это удалось!.. Благодарение сотен и сотен душ пребудет с тобой.$B$BПозволь кое-что предложить тебе...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нужно выманить Атофа из его логова!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эдварду Хейнсу на Остров Драконьей Скорби, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9684,'Получение силы Света','Прими этот зачарованный сосуд, $n, и наполни его магической силой, окружающей магистров, до краев. Когда-то эти магистры охраняли плененного наару, и часть его энергии еще находится в них. Этого сосуда хватит, чтобы вернуть к жизни падшего рыцаря.$B$BНе беспокойся о магистрах, за ними присмотрят. Лорд Соланар сообщил мне, что Леди Лиадрин занимается поиском нового источника магической силы.','Используйте мерцающий сосуд на эльфах крови-магистрах, чтобы наполнить его магической силой, и возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.','Неплохо, $N. Силы, дарованные светом, никогда не будут "естественными"для Рыцарей Крови. У немногих хватит смелости или способностей владеть ими, но я знаю, что вы не разочаруете нас.','Ты $Gговорил:говорила; с Магистром Асталором Кровавым клятвой?','Вернитесь к предводителю рыцарей Доблестной Крови в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Получение силы Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прими этот зачарованный сосуд, $n, и наполни его магической силой, окружающей магистров, до краев. Когда-то эти магистры охраняли плененного наару, и часть его энергии еще находится в них. Этого сосуда хватит, чтобы вернуть к жизни падшего рыцаря.$B$BНе беспокойся о магистрах, за ними присмотрят. Лорд Соланар сообщил мне, что Леди Лиадрин занимается поиском нового источника магической силы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте мерцающий сосуд на эльфах крови-магистрах, чтобы наполнить его магической силой, и возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо, $N. Силы, дарованные светом, никогда не будут "естественными"для Рыцарей Крови. У немногих хватит смелости или способностей владеть ими, но я знаю, что вы не разочаруете нас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gговорил:говорила; с Магистром Асталором Кровавым клятвой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предводителю рыцарей Доблестной Крови в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9685,'Воскрешение','Пока ты $gнаполнял:наполняла; сосуд, отряд посвященных принес тело Сангриаса Безмолвного Клинка. Отправляйся на верхний этаж таверны Луносвета и воскреси Сангриаса с помощью магической силы, заключенной в сосуде.$B$BПоторопись, $n. Если не успеешь вовремя, даже все могущество Света не сможет вернуть его к жизни. Возвращайся ко мне, когда закончишь.','Отправляйтесь в таверну Луносвета и воскресите Сангриаса Безмолвного Клинка с помощью силы, заключенной в наполненном мерцающем сосуде.','С возвращением, $N. Теперь, когда вы знаете правду об источнике нашей силы и продемонстрировали свое умение владеть им, я дам вам возможность воскрешать павших в поле. $B$BОставайтесь верными порядку и преуспевайте в своих тренировках, и ваша сила будет только расти.','Вернитесь к предводителю рыцарей Доблестной Крови в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воскрешение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты $gнаполнял:наполняла; сосуд, отряд посвященных принес тело Сангриаса Безмолвного Клинка. Отправляйся на верхний этаж таверны Луносвета и воскреси Сангриаса с помощью магической силы, заключенной в сосуде.$B$BПоторопись, $n. Если не успеешь вовремя, даже все могущество Света не сможет вернуть его к жизни. Возвращайся ко мне, когда закончишь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в таверну Луносвета и воскресите Сангриаса Безмолвного Клинка с помощью силы, заключенной в наполненном мерцающем сосуде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С возвращением, $N. Теперь, когда вы знаете правду об источнике нашей силы и продемонстрировали свое умение владеть им, я дам вам возможность воскрешать павших в поле. $B$BОставайтесь верными порядку и преуспевайте в своих тренировках, и ваша сила будет только расти.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предводителю рыцарей Доблестной Крови в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9686,'Второе испытание','От титула адепта тебя отделяет лишь одно испытание, $n.$B$BОно совсем не похоже на предыдущее – в этот раз все четко и понятно: брось вызов четырем лучшим рыцарям Крови и победи их в честном бою.$B$BКогда будешь $gготов:готова; начать, прикоснись к кристаллу, что появится посередине павильона. После этого просто дождись начала испытания.$B$BНачнем?','Пройдите второе испытание, победив воителя Ярокрова, воителя Светореза, воительницу Быстромеч и воителя Солнцесвета в павильоне у наставника Келерана Алого Взмаха.','Хорошо, $N! Ты $Gдоказал:доказала;, что $Gдостойн:достойна; полноправного членства в рыцарях крови и получаешь повышение до статуса адепта. Однако есть еще несколько задач, которые остаются до того, как ты сможешь приступить к службе.','Рыцарь крови скорее умрет, чем подчинится врагу. Помни это, $N.','Пройдите второе испытание.','Вернитесь к наставнику Келерану Алому Взмаху на Руины Луносвета, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второе испытание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От титула адепта тебя отделяет лишь одно испытание, $n.$B$BОно совсем не похоже на предыдущее – в этот раз все четко и понятно: брось вызов четырем лучшим рыцарям Крови и победи их в честном бою.$B$BКогда будешь $gготов:готова; начать, прикоснись к кристаллу, что появится посередине павильона. После этого просто дождись начала испытания.$B$BНачнем?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите второе испытание, победив воителя Ярокрова, воителя Светореза, воительницу Быстромеч и воителя Солнцесвета в павильоне у наставника Келерана Алого Взмаха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, $N! Ты $Gдоказал:доказала;, что $Gдостойн:достойна; полноправного членства в рыцарях крови и получаешь повышение до статуса адепта. Однако есть еще несколько задач, которые остаются до того, как ты сможешь приступить к службе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рыцарь крови скорее умрет, чем подчинится врагу. Помни это, $N.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Пройдите второе испытание.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наставнику Келерану Алому Взмаху на Руины Луносвета, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9687,'Святотатство','Не так давно на берегах этого острова стали появляться совухи. Они приходили поодиночке и с единственной целью: похитить кости павших драконов. Не знаю, что произошло с этими существами – прежде совухам никогда не приходило в голову тревожить прах ушедших; но ныне души драконов лишились покоя, не в силах вынести святотатства.$B$BЕсли ты отправишься на запад и минуешь Кровавый берег, то доберешься до гряды Яростного Пера. Там, в поселениях совухов, можно отыскать похищенные кости драконов...','Принц Торет с острова Драконьей Скорби просит отыскать 8 костей драконов.','Давно минули времена войн драконов. Все, что осталось, – древние кости и немногие живые из выводка Изеры...','Вернитесь к принцу Торету на Остров Драконьей Скорби, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Святотатство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не так давно на берегах этого острова стали появляться совухи. Они приходили поодиночке и с единственной целью: похитить кости павших драконов. Не знаю, что произошло с этими существами – прежде совухам никогда не приходило в голову тревожить прах ушедших; но ныне души драконов лишились покоя, не в силах вынести святотатства.$B$BЕсли ты отправишься на запад и минуешь Кровавый берег, то доберешься до гряды Яростного Пера. Там, в поселениях совухов, можно отыскать похищенные кости драконов...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принц Торет с острова Драконьей Скорби просит отыскать 8 костей драконов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Давно минули времена войн драконов. Все, что осталось, – древние кости и немногие живые из выводка Изеры...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Торету на Остров Драконьей Скорби, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9688,'Дорога в Сон','То, что ты видишь, – это беспокойные духи зеленых драконов. Подобно мне, они привязаны к этой земле и не могут достичь места своего упокоения в Изумрудном Сне.$B$BТо, что тебе удалось вернуть кости погибших, немного успокоило их, однако еще рано останавливаться на достигнутом...$B$BНеобходимо уничтожить астральные тела этих заблудших драконов и освободить их души. Пока это не будет совершено, я не сумею покинуть остров!','Принц Торет с острова Драконьей Скорби просит убить 5 темно-зеленых дракончиков и 5 детенышей зеленого дракона.','Каким бы отвратительным ни было это деяние, его нужно было совершить. И теперь тебе предстоит взглянуть в лицо истинному злу.','Мне больно даже смотреть на это... Прошу тебя, давай больше не будем об этом говорить.','Вернитесь к принцу Торету на Остров Драконьей Скорби, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дорога в Сон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, что ты видишь, – это беспокойные духи зеленых драконов. Подобно мне, они привязаны к этой земле и не могут достичь места своего упокоения в Изумрудном Сне.$B$BТо, что тебе удалось вернуть кости погибших, немного успокоило их, однако еще рано останавливаться на достигнутом...$B$BНеобходимо уничтожить астральные тела этих заблудших драконов и освободить их души. Пока это не будет совершено, я не сумею покинуть остров!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принц Торет с острова Драконьей Скорби просит убить 5 темно-зеленых дракончиков и 5 детенышей зеленого дракона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Каким бы отвратительным ни было это деяние, его нужно было совершить. И теперь тебе предстоит взглянуть в лицо истинному злу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне больно даже смотреть на это... Прошу тебя, давай больше не будем об этом говорить.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к принцу Торету на Остров Драконьей Скорби, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9690,'Второе испытание','Что ж, $gюный:юная; $n. Ты $gузнал:узнала; истинную природу нашего могущества и $gприложил:приложила; немало усилий, чтобы овладеть им и стать настоящим рыцарем крови.$B$BПришло время второго испытания. Выдержишь его – и я наделю тебя титулом адепта. Отправляйся к наставнику Келерану Алому Взмаху. Чтобы найти его, держи свой путь на север, через руины Луносвета, а затем сверни на восток прямо перед мостом к Острову Солнечного Скитальца.','Поговорите с наставником Келераном Алым Взмахом.','Когда вы будете готовы, я расскажу вам больше о том испытании, которое вам предстоит пройти. Приготовьтесь и поговорите со мной еще раз, когда захотите начать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второе испытание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, $gюный:юная; $n. Ты $gузнал:узнала; истинную природу нашего могущества и $gприложил:приложила; немало усилий, чтобы овладеть им и стать настоящим рыцарем крови.$B$BПришло время второго испытания. Выдержишь его – и я наделю тебя титулом адепта. Отправляйся к наставнику Келерану Алому Взмаху. Чтобы найти его, держи свой путь на север, через руины Луносвета, а затем сверни на восток прямо перед мостом к Острову Солнечного Скитальца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с наставником Келераном Алым Взмахом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда вы будете готовы, я расскажу вам больше о том испытании, которое вам предстоит пройти. Приготовьтесь и поговорите со мной еще раз, когда захотите начать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9691,'Возвращение в Луносвет','Возвращайся в Луносвет и встреться с предводителем рыцарей Доблестной Кровью. Не беспокойся: твой визит будет лучшим доказательством того, что испытание успешно пройдено.$B$BПредводитель сам расскажет тебе, что осталось совершить для получения титула адепта. Тебе есть чем гордиться, $n. Поверь, немногим удается пройти это испытание и остаться в живых.','Возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.','Я знал, что ты пройдешь испытание, $N. Твои оставшиеся испытания в основном формальные, но они не менее опасны, чем смотреть на одного из наших чемпионов с обнаженным оружием. Слушай внимательно, и я скажу тебе, что еще ты $Gдолжен:должна; сделать, чтобы получить новое звание.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Луносвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возвращайся в Луносвет и встреться с предводителем рыцарей Доблестной Кровью. Не беспокойся: твой визит будет лучшим доказательством того, что испытание успешно пройдено.$B$BПредводитель сам расскажет тебе, что осталось совершить для получения титула адепта. Тебе есть чем гордиться, $n. Поверь, немногим удается пройти это испытание и остаться в живых.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к предводителю рыцарей Доблестной Крови в Луносвет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знал, что ты пройдешь испытание, $N. Твои оставшиеся испытания в основном формальные, но они не менее опасны, чем смотреть на одного из наших чемпионов с обнаженным оружием. Слушай внимательно, и я скажу тебе, что еще ты $Gдолжен:должна; сделать, чтобы получить новое звание.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9692,'Путь адепта','Прежде вступить в орден, каждый кандидат должен собрать все необходимые компоненты для ковки особого оружия рыцарей Крови – закаленного кровью протазана.$B$BКроме того, каждый рыцарь должен носить особый знак отличия. Выковать знак нельзя – его можно только получить от ветерана ордена. Знак, который будешь носить ты, принадлежал бесстрашному рыцарю, павшему при осаде Смертхольма. Но сначала тебе нужно найти его.$B$BЯ подготовил несколько записок, которые помогут тебе в поисках.','Принесите оскверненный самоцвет Кора, ящик со слитками, закаленными в крови, нужное количество крови разгневанных и знак отличия рыцаря крови предводителю рыцарей Доблестной Крови в Луносвет.','Отлично, $N. Все здесь. Остается только выковать оружие.','Ты $Gвыполнил:выполнила; задание, порученное мной, $N?','Вернитесь к предводителю рыцарей Доблестной Крови в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь адепта',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде вступить в орден, каждый кандидат должен собрать все необходимые компоненты для ковки особого оружия рыцарей Крови – закаленного кровью протазана.$B$BКроме того, каждый рыцарь должен носить особый знак отличия. Выковать знак нельзя – его можно только получить от ветерана ордена. Знак, который будешь носить ты, принадлежал бесстрашному рыцарю, павшему при осаде Смертхольма. Но сначала тебе нужно найти его.$B$BЯ подготовил несколько записок, которые помогут тебе в поисках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите оскверненный самоцвет Кора, ящик со слитками, закаленными в крови, нужное количество крови разгневанных и знак отличия рыцаря крови предводителю рыцарей Доблестной Крови в Луносвет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, $N. Все здесь. Остается только выковать оружие.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвыполнил:выполнила; задание, порученное мной, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предводителю рыцарей Доблестной Крови в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9693,'Что для тебя Аргус?..','Экзарх Адметиус с Кровавой заставы просит поговорить с воздаятелем Боросом.','Ах, $n... Да, я слышал о тебе. Говорят, тебе удалось весь Кессельский путь за 15 минут проскочить? Хотя мне как-то не очень верится.$B$BТы $Gготов:готова; жить и умереть во имя Света? Во имя Велена? Во имя Аргуса?..$B$B Борос смеется. $B$BЛадно, ладно, что-то я увлекся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что для тебя Аргус?..',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Экзарх Адметиус с Кровавой заставы просит поговорить с воздаятелем Боросом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, $n... Да, я слышал о тебе. Говорят, тебе удалось весь Кессельский путь за 15 минут проскочить? Хотя мне как-то не очень верится.$B$BТы $Gготов:готова; жить и умереть во имя Света? Во имя Велена? Во имя Аргуса?..$B$B Борос смеется. $B$BЛадно, ладно, что-то я увлекся.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9694,'Кровавая застава','Убейте 10 шпионов клана Солнечного Ястреба и сообщите об этом на Кровавую заставу воздаятелю Боросу.','Их так много... Такое ощущение, что откуда-то все время берутся новые!','Вернитесь к воздаятелю Боросу на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровавая застава',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 шпионов клана Солнечного Ястреба и сообщите об этом на Кровавую заставу воздаятелю Боросу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Их так много... Такое ощущение, что откуда-то все время берутся новые!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Боросу на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9695,'Повеление Солнечного короля','Похоже, это важный документ. Жаль только, что он написан на талассийском – ведь ты не знаешь этого языка, верно?$B$BБудем надеяться, воздаятель Борос подскажет, что делать с этим письмом.','Доставьте повеление Солнечного короля воздаятелю Боросу на Кровавую заставу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повеление Солнечного короля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, это важный документ. Жаль только, что он написан на талассийском – ведь ты не знаешь этого языка, верно?$B$BБудем надеяться, воздаятель Борос подскажет, что делать с этим письмом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте повеление Солнечного короля воздаятелю Боросу на Кровавую заставу.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9696,'Переводы...','Элизия читает документ. $B$BЕсли то, что здесь написано, – правда, значит, эльфы крови открыли портал в Запределье. Да, это объясняет, почему их становится все больше и больше...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переводы...',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Элизия читает документ. $B$BЕсли то, что здесь написано, – правда, значит, эльфы крови открыли портал в Запределье. Да, это объясняет, почему их становится все больше и больше...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9697,'Наблюдательница Лиса\'о','Экология местных существ, в особенности спорлингов и болотников, требует серьезного исследования. Казалось бы, что в этом такого? Но, занявшись полевыми исследованиями, ты обнаружишь, что дело это опасное и требует мужества и находчивости.$b$bОтыщи наблюдательницу Лиса\'о у кенарийского караульного поста на юго-западе болот. Ступай по дороге на запад, и рано или поздно придешь туда. Она, правда, чересчур погружена в свои научные исследования, но не обращай на это внимания.$b$bДа, и еще: осторожнее с ее кошкой!','Поговорите с наблюдательницей Лиса\'о у кенарийского караульного поста в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наблюдательница Лиса\'о',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Экология местных существ, в особенности спорлингов и болотников, требует серьезного исследования. Казалось бы, что в этом такого? Но, занявшись полевыми исследованиями, ты обнаружишь, что дело это опасное и требует мужества и находчивости.$b$bОтыщи наблюдательницу Лиса\'о у кенарийского караульного поста на юго-западе болот. Ступай по дороге на запад, и рано или поздно придешь туда. Она, правда, чересчур погружена в свои научные исследования, но не обращай на это внимания.$b$bДа, и еще: осторожнее с ее кошкой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с наблюдательницей Лиса\'о у кенарийского караульного поста в Зангартопи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9698,'Аудиенция у Пророка','Доставьте переведенное послание Солнечных Ястребов Пророку Велену в Экзодар.','Велен читает документ. $B$BЛюбопытно... Это действительно многое объясняет…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аудиенция у Пророка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте переведенное послание Солнечных Ястребов Пророку Велену в Экзодар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Велен читает документ. $B$BЛюбопытно... Это действительно многое объясняет…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9699,'Правда или вымысел','Благодарю, $n, ты $Gуспел:успела; как раз вовремя. Похоже, ты – один из лучших агентов Длани Аргуса.$B$BЕсли бы мы еще знали, с кем на острове Кровавой Дымки они поддерживают связь и где находится Солнечный портал... Где бы ни был этот портал, похоже, его надежно охраняют.$B$BНе хочешь ли заняться его поисками?$B$BЕсли ты не против, доставь эти распоряжения воздаятелю Боросу. Он расскажет тебе, что делать.','Доставьте распоряжения Велена воздаятелю Боросу на Кровавую заставу.','План неплох – но и опасен. Но, я уверен, ты справишься.','Ну, что там?..') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Правда или вымысел',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодарю, $n, ты $Gуспел:успела; как раз вовремя. Похоже, ты – один из лучших агентов Длани Аргуса.$B$BЕсли бы мы еще знали, с кем на острове Кровавой Дымки они поддерживают связь и где находится Солнечный портал... Где бы ни был этот портал, похоже, его надежно охраняют.$B$BНе хочешь ли заняться его поисками?$B$BЕсли ты не против, доставь эти распоряжения воздаятелю Боросу. Он расскажет тебе, что делать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте распоряжения Велена воздаятелю Боросу на Кровавую заставу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','План неплох – но и опасен. Но, я уверен, ты справишься.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что там?..',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9700,'Магия против Тьмы','Велен говорит, что если эльфы крови попытались создать переход между этими островами и Запредельем, то в местах открытия порталов непременно объявятся аномалии: это неизбежный побочный эффект. Тебе нужно обыскать остров и обнаружить места скопления подобных аномалий.$B$BПомни, $n: некоторые из этих существ – выходцы из Бездны. Если они встретятся тебе, убивай их без колебаний! Если тебе удастся выяснить что-то новое, сообщи об этом мне. Поиски лучше начать с севера, от Сверхускорителя.','Воздаятель Борос с Кровавой заставы просит найти Солнечный портал и убить 5 аномалий Бездны.','Мне не раз докладывали о том, что в этих землях появились странные существа. Тебе предстоит выяснить, являются ли они местными зверями-мутантами или аномалиями – то есть существами из Бездны.','Местонахождение Солнечного портала установлено','Вернитесь к воздаятелю Боросу на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Магия против Тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Велен говорит, что если эльфы крови попытались создать переход между этими островами и Запредельем, то в местах открытия порталов непременно объявятся аномалии: это неизбежный побочный эффект. Тебе нужно обыскать остров и обнаружить места скопления подобных аномалий.$B$BПомни, $n: некоторые из этих существ – выходцы из Бездны. Если они встретятся тебе, убивай их без колебаний! Если тебе удастся выяснить что-то новое, сообщи об этом мне. Поиски лучше начать с севера, от Сверхускорителя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воздаятель Борос с Кровавой заставы просит найти Солнечный портал и убить 5 аномалий Бездны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне не раз докладывали о том, что в этих землях появились странные существа. Тебе предстоит выяснить, являются ли они местными зверями-мутантами или аномалиями – то есть существами из Бездны.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Местонахождение Солнечного портала установлено',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Боросу на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9701,'Наблюдение за спорлингами','Нам следует как можно больше узнать о спорлингах Спореггара и их взаимоотношениях с окружающим миром. Один из способов это сделать – это незаметно наблюдать за спорлингами, как делаю это я.$b$bА тебя я попрошу сходить на Грибную поляну к западу отсюда. Исследуй весь тот район, вернись и расскажи мне, что тебе удалось узнать.','Исследуйте Грибную поляну в Зангартопи, затем вернитесь к наблюдательнице Лиса\'о к кенарийскому караульному посту в Зангартопи и расскажите об увиденном.','Что?! Болотники с гряды Квагг пожирают отпрысков спорлингов?! Это ужасно!','Уже $gвернулся:вернулась;? Твои наблюдения за спорлингами Спореггара очень важны для моих исследований! Надеюсь, ты не из торопыг? Мне нужны сведения обо всей Грибной поляне!','Исследуйте Грибную поляну','Вернитесь к наблюдательнице Лиса\'о на Кенарийский караульный пост, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наблюдение за спорлингами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам следует как можно больше узнать о спорлингах Спореггара и их взаимоотношениях с окружающим миром. Один из способов это сделать – это незаметно наблюдать за спорлингами, как делаю это я.$b$bА тебя я попрошу сходить на Грибную поляну к западу отсюда. Исследуй весь тот район, вернись и расскажи мне, что тебе удалось узнать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте Грибную поляну в Зангартопи, затем вернитесь к наблюдательнице Лиса\'о к кенарийскому караульному посту в Зангартопи и расскажите об увиденном.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что?! Болотники с гряды Квагг пожирают отпрысков спорлингов?! Это ужасно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уже $gвернулся:вернулась;? Твои наблюдения за спорлингами Спореггара очень важны для моих исследований! Надеюсь, ты не из торопыг? Мне нужны сведения обо всей Грибной поляне!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Исследуйте Грибную поляну',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наблюдательнице Лиса\'о на Кенарийский караульный пост, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9702,'Вопросы питания','Я все не могу понять, зачем болотники переходят через дорогу на Грибную поляну. Должно быть, они голодают? В любом случае, так дело не пойдет!$b$bЯ имею в виду, что в обычных условиях не стала бы вмешиваться, но если они и дальше будут пожирать отпрысков спорлингов, спорлинги окажутся истреблены!$b$bВот как мы поступим: я останусь здесь, а ты отправляйся к гряде Квагг на востоке и попытайся выяснить, почему болотники вторгаются на территорию спорлингов.','Соберите 10 образцов выброшенного корма и вернитесь к наблюдательнице Лиса\'о на кенарийский караульный пост в Зангартопи.','Вернитесь к наблюдательнице Лиса\'о на Кенарийский караульный пост, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вопросы питания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я все не могу понять, зачем болотники переходят через дорогу на Грибную поляну. Должно быть, они голодают? В любом случае, так дело не пойдет!$b$bЯ имею в виду, что в обычных условиях не стала бы вмешиваться, но если они и дальше будут пожирать отпрысков спорлингов, спорлинги окажутся истреблены!$b$bВот как мы поступим: я останусь здесь, а ты отправляйся к гряде Квагг на востоке и попытайся выяснить, почему болотники вторгаются на территорию спорлингов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 образцов выброшенного корма и вернитесь к наблюдательнице Лиса\'о на кенарийский караульный пост в Зангартопи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наблюдательнице Лиса\'о на Кенарийский караульный пост, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9703,'Криогенный блок','У нас есть кому заняться поиском порталов, $n. Для тебя есть другая, не менее важная задача.$B$BБоросу недавно доложили об обнаружении нового места падения обломков Экзодара. Кроме того, нам удалось выяснить, что этот обломок фактически является криогенным блоком Экзодара. Там находятся капсулы – точно такие же, как те, из которых некогда вышли дренеи в долине Аммен.$B$BКроме того, там находятся лечебные средства. Отправляйся на запад от Кровавой заставы – именно там находится криогенный блок. Постарайся найти лечебные средства – и выживших, если, конечно, они там есть.','Воздаятель Курос хочет, чтобы вы доставили на Кровавую заставу 12 ящичков с лечебными средствами.','Ну что, сведения были точны?','Вернитесь к воздаятелю Куросу на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Криогенный блок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас есть кому заняться поиском порталов, $n. Для тебя есть другая, не менее важная задача.$B$BБоросу недавно доложили об обнаружении нового места падения обломков Экзодара. Кроме того, нам удалось выяснить, что этот обломок фактически является криогенным блоком Экзодара. Там находятся капсулы – точно такие же, как те, из которых некогда вышли дренеи в долине Аммен.$B$BКроме того, там находятся лечебные средства. Отправляйся на запад от Кровавой заставы – именно там находится криогенный блок. Постарайся найти лечебные средства – и выживших, если, конечно, они там есть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воздаятель Курос хочет, чтобы вы доставили на Кровавую заставу 12 ящичков с лечебными средствами.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, сведения были точны?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Куросу на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9704,'Отправляйтесь на юг, в руины Луносвета, и отыщите убитого курьера на Рассветной улице.','С тела курьера похищено все, кроме одного свертка. Судя по описанию Аларион, это и есть сверток Эроны.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на юг, в руины Луносвета, и отыщите убитого курьера на Рассветной улице.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С тела курьера похищено все, кроме одного свертка. Судя по описанию Аларион, это и есть сверток Эроны.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9707,'Ковка оружия','Что ж, ты $gдоказал:доказала;, что $gдостоин:достойна; стать рыцарем нашего ордена. Для меня большая честь даровать тебе титул адепта, $n. Сам принц Кель\'тас гордился бы тобой.$B$BТы будешь опорой для тех, кто сражается рядом с тобой, и примером для тех, кто стремится присоединиться к нам. Не щади врагов и не показывай свою слабость, защищай свой народ и стань истинным владыкой Света.$B$BА теперь пришло время выковать оружие, положенное тебе с новым титулом.','Принесите ящик с материалами Бемаррину в Луносвет.','Похоже, у тебя есть все, что мне нужно. Давайте начнем!','Поздравляю, $N. Поверьте, достижение звания адепта - нелегкий подвиг. Я видел, сколько людей входит в это здание, и как немногие из них продержались достаточно долго, чтобы навестить меня с этими материалами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ковка оружия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ж, ты $gдоказал:доказала;, что $gдостоин:достойна; стать рыцарем нашего ордена. Для меня большая честь даровать тебе титул адепта, $n. Сам принц Кель\'тас гордился бы тобой.$B$BТы будешь опорой для тех, кто сражается рядом с тобой, и примером для тех, кто стремится присоединиться к нам. Не щади врагов и не показывай свою слабость, защищай свой народ и стань истинным владыкой Света.$B$BА теперь пришло время выковать оружие, положенное тебе с новым титулом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ящик с материалами Бемаррину в Луносвет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, у тебя есть все, что мне нужно. Давайте начнем!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поздравляю, $N. Поверьте, достижение звания адепта - нелегкий подвиг. Я видел, сколько людей входит в это здание, и как немногие из них продержались достаточно долго, чтобы навестить меня с этими материалами.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9708,'Знакомые грибы','Да-да, я же знала, что уже встречала этот тип грибов в другом районе болот!$b$bУ меня есть гипотеза... К северу отсюда есть место, которое называют Болотными вырубками. Мне лично это название кажется странным, но, с другой стороны, я же там не бывала... Так вот, мне нужны образцы тамошних грибов, чтобы проверить мои соображения.$b$bТолько смотри, |3-6($c), будь $gосторожен:осторожна:c;! Я слышала, что в тех краях появились огры. Возможно, тебе придется отбирать образцы у них. Может быть, это из-за огров болотники больше не решаются добывать там пищу?','Соберите 15 образцов грибов и принесите их наблюдательнице Лиса\'о на караульный пост Кенария в Зангартопи.','Ну что, образцы у тебя?','Вернитесь к наблюдательнице Лиса\'о на Кенарийский караульный пост, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знакомые грибы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да-да, я же знала, что уже встречала этот тип грибов в другом районе болот!$b$bУ меня есть гипотеза... К северу отсюда есть место, которое называют Болотными вырубками. Мне лично это название кажется странным, но, с другой стороны, я же там не бывала... Так вот, мне нужны образцы тамошних грибов, чтобы проверить мои соображения.$b$bТолько смотри, |3-6($c), будь $gосторожен:осторожна:c;! Я слышала, что в тех краях появились огры. Возможно, тебе придется отбирать образцы у них. Может быть, это из-за огров болотники больше не решаются добывать там пищу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 образцов грибов и принесите их наблюдательнице Лиса\'о на караульный пост Кенария в Зангартопи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, образцы у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наблюдательнице Лиса\'о на Кенарийский караульный пост, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9709,'Ворованные грибы','$C, у меня есть идея! Возвращайся на север и проберись на территорию огров.$b$bК северо-западу от Болотных вырубок есть место, которое называется крепость Анго\'рош. Крепость находится на парящем острове, куда ведет мост из большого гриба.$b$bДолжно быть, огры хранят собранные грибы именно там. Могу поручиться, они там есть повсюду, и уж тем более у самих огров!$b$bПринеси мне побольше этих грибов, и я попытаюсь предложить болотникам новый источник пищи.','Соберите 10 ящиков грибов и вернитесь с ними к наблюдательнице Лиса\'о на караульный пост Кенария в Зангартопи.','Ну что, достаточно ли у нас грибов, чтобы устроить новый сад для болотников?','Вернитесь к наблюдательнице Лиса\'о на Кенарийский караульный пост, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ворованные грибы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, у меня есть идея! Возвращайся на север и проберись на территорию огров.$b$bК северо-западу от Болотных вырубок есть место, которое называется крепость Анго\'рош. Крепость находится на парящем острове, куда ведет мост из большого гриба.$b$bДолжно быть, огры хранят собранные грибы именно там. Могу поручиться, они там есть повсюду, и уж тем более у самих огров!$b$bПринеси мне побольше этих грибов, и я попытаюсь предложить болотникам новый источник пищи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 ящиков грибов и вернитесь с ними к наблюдательнице Лиса\'о на караульный пост Кенария в Зангартопи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, достаточно ли у нас грибов, чтобы устроить новый сад для болотников?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к наблюдательнице Лиса\'о на Кенарийский караульный пост, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9710,'Закаленный кровью протазан','Все готово, $n. Скоро ты получишь свое новое оружие.','Дождитесь, пока Бемаррин смастерит оружие.','Вот оно, $N. Используйте его на службе Луносвета и своего ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Закаленный кровью протазан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все готово, $n. Скоро ты получишь свое новое оружие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дождитесь, пока Бемаррин смастерит оружие.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот оно, $N. Используйте его на службе Луносвета и своего ордена.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9712,'Талассийский боевой конь','Тебе удалось добиться поистине впечатляющих успехов, $n. Магистр Асталор и его поверенные позволили тебе прикоснуться к силе Света – и ты $gсумел:сумела; обратить ее себе во благо. Пришло время получить новые знания.$B$BСила Света дарует способность вызывать талассийского тяжеловоза, который станет твоим верным скакуном.$B$BПродолжай служить ордену, $n. Тебя ждут еще большие свершения.','Поговорите с предводителем рыцарей Доблестной Кровью, чтобы научиться вызывать талассийского боевого коня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Талассийский боевой конь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось добиться поистине впечатляющих успехов, $n. Магистр Асталор и его поверенные позволили тебе прикоснуться к силе Света – и ты $gсумел:сумела; обратить ее себе во благо. Пришло время получить новые знания.$B$BСила Света дарует способность вызывать талассийского тяжеловоза, который станет твоим верным скакуном.$B$BПродолжай служить ордену, $n. Тебя ждут еще большие свершения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с предводителем рыцарей Доблестной Кровью, чтобы научиться вызывать талассийского боевого коня.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9713,'Включение возможности сбора огнешляпки') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Включение возможности сбора огнешляпки',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9714,'Принеси мне еще одну клумбу!','Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты ещё раз заглянешь в Нижетопь?','Кровавый гибискус, который можно найти у шаркунов, болотоходов и подболотных скатов в Нижетопи, в резервуаре Кривого Клыка, нам всегда пригодится. Приноси его мне связками по пять штук, я буду очень тебе благодарен!','Вернитесь к Гзхун\'тту в Спореггар, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Принеси мне еще одну клумбу!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти цветки отлично подойдут. Но кровавый гибискус нам нужен постоянно. Может быть, как-нибудь ты ещё раз заглянешь в Нижетопь?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кровавый гибискус, который можно найти у шаркунов, болотоходов и подболотных скатов в Нижетопи, в резервуаре Кривого Клыка, нам всегда пригодится. Приноси его мне связками по пять штук, я буду очень тебе благодарен!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гзхун\'тту в Спореггар, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9715,'Принеси мне клумбу!','Нам необходимо пополнить наши запасы кровавого гибискуса. Мы его используем в самых разнообразных целях. Раньше этого гибискуса было много повсюду, но теперь, когда болота пересыхают, он водится только в Нижетопи в Резервуаре Кривого Клыка, что под Змеиным озером.$b$bГоворят, что для тамошних шаркунов, болотоходов и болотных скатов он – лучшее лакомство. Так что, если хочешь нам помочь, добудь у них эти цветы.','Добудьте 5 растений кровавого гибискуса и отнесите их Гзхун\'тту в Спореггар в Зангартопи.','Отличный гибискус! Но лишний гибискус нам никогда не помешает. Будешь в Нижетопи, имей это в виду!','Ну что, удалось тебе добыть гибискус, как я просил?','Вернитесь к Гзхун\'тту в Спореггар, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Принеси мне клумбу!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам необходимо пополнить наши запасы кровавого гибискуса. Мы его используем в самых разнообразных целях. Раньше этого гибискуса было много повсюду, но теперь, когда болота пересыхают, он водится только в Нижетопи в Резервуаре Кривого Клыка, что под Змеиным озером.$b$bГоворят, что для тамошних шаркунов, болотоходов и болотных скатов он – лучшее лакомство. Так что, если хочешь нам помочь, добудь у них эти цветы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 растений кровавого гибискуса и отнесите их Гзхун\'тту в Спореггар в Зангартопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличный гибискус! Но лишний гибискус нам никогда не помешает. Будешь в Нижетопи, имей это в виду!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе добыть гибискус, как я просил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гзхун\'тту в Спореггар, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9716,'Неприятности на Озере Тенетопь','Мы явились в Запределье, рассчитывая найти здесь крохотные островки сохранившейся жизни. Но в Зангартопи мы обнаружили обширную, процветающую экосистему!$b$bОднако наши первые радужные впечатления оказались обманчивыми. Уровень воды в озерах и болотах непрерывно понижается все то время, что мы делаем замеры!$b$bДля местных животных и растений это может обернуться катастрофой. Отправляйся на Озеро Тенетопь к юго-западу отсюда и попробуй отыскать причину убывания воды.','Выясните причину убывания воды в Озере Тенетопь. Затем вернитесь к Исиэли Песни Ветра в Кенарийский оплот в Зангартопи.','Ну что, $n, удалось что-нибудь выяснить?','Исследуйте Озеро Тенетопь.','Вернитесь к Исиэли Песне Ветра в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприятности на Озере Тенетопь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы явились в Запределье, рассчитывая найти здесь крохотные островки сохранившейся жизни. Но в Зангартопи мы обнаружили обширную, процветающую экосистему!$b$bОднако наши первые радужные впечатления оказались обманчивыми. Уровень воды в озерах и болотах непрерывно понижается все то время, что мы делаем замеры!$b$bДля местных животных и растений это может обернуться катастрофой. Отправляйся на Озеро Тенетопь к юго-западу отсюда и попробуй отыскать причину убывания воды.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните причину убывания воды в Озере Тенетопь. Затем вернитесь к Исиэли Песни Ветра в Кенарийский оплот в Зангартопи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $n, удалось что-нибудь выяснить?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Исследуйте Озеро Тенетопь.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исиэли Песне Ветра в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9717,'Удачный ход','Мы – народ мирный, но вести войну со споровыми великанами мы просто вынуждены, нравится нам это, или нет. А у нас есть поговорка, что, когда речь идет о грибах и о войне, все средства хороши!$b$bОдин из предводителей споровых великанов, Болотоглад, уже в течение нескольких тысяч лет бережно взращивает особое растение, известное как подспорник. Если с этим растением что-то случится, дух Болотоглада, несомненно, будет сломлен!$b$bОтправляйся в Нижетопь Резервуара Кривого Клыка, и укради у него это растение! Поверь мне, на это он внимание обратит непременно!','Добудьте ветку подспорника и вернитесь с ней к Тшу в Спореггар в Зангартопи.','Спорлинг издает звук, отдаленно напоминающий хмыканье.\n\nВеликолепно! Несомненно, боевой дух споровых великанов упадет ниже дна болота, как только они поймут, что тебе удалось совершить.\n\nПравда, возможно, они так разгневаются, что нападут на нас снова...\n\nТшу делает такое движение, как будто пожимает плечами.','Нижетопь – очень опасное место! Я, конечно, не сочту тебя $gтрусом:трусливой;, если ты не рискнешь отправиться туда. Но коли уж возьмешься за это дело, стыдно тебе будет вернуться с пустыми руками.','Вернитесь к Тшу в Спореггар, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удачный ход',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы – народ мирный, но вести войну со споровыми великанами мы просто вынуждены, нравится нам это, или нет. А у нас есть поговорка, что, когда речь идет о грибах и о войне, все средства хороши!$b$bОдин из предводителей споровых великанов, Болотоглад, уже в течение нескольких тысяч лет бережно взращивает особое растение, известное как подспорник. Если с этим растением что-то случится, дух Болотоглада, несомненно, будет сломлен!$b$bОтправляйся в Нижетопь Резервуара Кривого Клыка, и укради у него это растение! Поверь мне, на это он внимание обратит непременно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ветку подспорника и вернитесь с ней к Тшу в Спореггар в Зангартопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спорлинг издает звук, отдаленно напоминающий хмыканье.\n\nВеликолепно! Несомненно, боевой дух споровых великанов упадет ниже дна болота, как только они поймут, что тебе удалось совершить.\n\nПравда, возможно, они так разгневаются, что нападут на нас снова...\n\nТшу делает такое движение, как будто пожимает плечами.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нижетопь – очень опасное место! Я, конечно, не сочту тебя $gтрусом:трусливой;, если ты не рискнешь отправиться туда. Но коли уж возьмешься за это дело, стыдно тебе будет вернуться с пустыми руками.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тшу в Спореггар, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9718,'С высоты птичьего полета','Нужно определить, сколько озер затронула деятельность наг, и затем уже действовать.$b$bРазумеется, обследовать каждый водоем в Зангартопи – дело долгое. С помощью магии я могу изменить твой облик, приспособив его для этой разведки.$b$bКогда будешь $Gготов:готова;, подойди ко мне и используй этот амулет. А когда дело будет окончено, я помогу тебе благополучно вернуться обратно.','Используйте амулет буревестника, чтобы исследовать основные озера Зангартопи по просьбе Исиэли Песни Ветра.','Исследуйте основные озера Зангартопи.','Вернитесь к Исиэли Песне Ветра в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С высоты птичьего полета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно определить, сколько озер затронула деятельность наг, и затем уже действовать.$b$bРазумеется, обследовать каждый водоем в Зангартопи – дело долгое. С помощью магии я могу изменить твой облик, приспособив его для этой разведки.$b$bКогда будешь $Gготов:готова;, подойди ко мне и используй этот амулет. А когда дело будет окончено, я помогу тебе благополучно вернуться обратно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте амулет буревестника, чтобы исследовать основные озера Зангартопи по просьбе Исиэли Песни Ветра.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Исследуйте основные озера Зангартопи.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исиэли Песне Ветра в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9719,'Охота на охотницу','Испокон веков наибольшую угрозу для моего народа представляли болотоходы. Теперь, когда нам угрожают еще и споровые великаны, мы не можем допустить, чтобы на нас нападали наши старинные враги!$b$b$C, отваги тебе не занимать, ты $gдоказал:доказала; это. Как ты думаешь, сумеешь ли ты пробраться в Нижетопь Резервуара Кривого Клыка и уничтожить великую мать болотоходов, Черную Охотницу?$b$bА в доказательство принеси мне ее мозг!','Принесите мозг Черной Охотницы Кнн\'иксу в Спореггар в Зангартопи.','Черная Охотница мертва! Нехорошо радоваться убийству, но эта великая мать и все ее племя на протяжении веков причиняли моему народу неисчислимые страдания.\n\nУвы, теперь одна из ее потомков преобразуется и займет ее место, однако это все же займет какое-то время, и мы сможет перевести дух. В течение некоторого времени болотоходы перестанут нас тревожить...','Ты $gвернулся:вернулась;! Значит ли это, что Черной Охотницы больше нет в живых?','Вернитесь к Кнн\'иксу в Спореггар, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на охотницу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Испокон веков наибольшую угрозу для моего народа представляли болотоходы. Теперь, когда нам угрожают еще и споровые великаны, мы не можем допустить, чтобы на нас нападали наши старинные враги!$b$b$C, отваги тебе не занимать, ты $gдоказал:доказала; это. Как ты думаешь, сумеешь ли ты пробраться в Нижетопь Резервуара Кривого Клыка и уничтожить великую мать болотоходов, Черную Охотницу?$b$bА в доказательство принеси мне ее мозг!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мозг Черной Охотницы Кнн\'иксу в Спореггар в Зангартопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Черная Охотница мертва! Нехорошо радоваться убийству, но эта великая мать и все ее племя на протяжении веков причиняли моему народу неисчислимые страдания.\n\nУвы, теперь одна из ее потомков преобразуется и займет ее место, однако это все же займет какое-то время, и мы сможет перевести дух. В течение некоторого времени болотоходы перестанут нас тревожить...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gвернулся:вернулась;! Значит ли это, что Черной Охотницы больше нет в живых?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кнн\'иксу в Спореггар, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9720,'Необходимо поддерживать равновесие!','Я представления не имею, для чего нагам понадобилось осушать свои собственные озера. Но знаю одно: их необходимо остановить!$b$bЭти семена несут в себе гнев самой земли. Отнеси их к паровым насосам, установленным нагами, и осыпь ими все эти рычаги и приводы.$b$bИз семян прорастут лозы толщиной в руку и прочные, как сталь. Ступай, $n. Восстанови природное равновесие, нарушенное нагами!','Осыпьте семенами железной лозы пульты управления паровым насосом в Змеином озере, Озере Тенетопь, озере Болотных Огоньков и в Лагуне. Затем вернитесь к Исиэли Песни Ветра в Кенарийский оплот в Зангартопи и отдайте ей оставшиеся семена.','Ну что, |3-6($c), готово?','Вернитесь к Исиэли Песни Ветра в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необходимо поддерживать равновесие!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я представления не имею, для чего нагам понадобилось осушать свои собственные озера. Но знаю одно: их необходимо остановить!$b$bЭти семена несут в себе гнев самой земли. Отнеси их к паровым насосам, установленным нагами, и осыпь ими все эти рычаги и приводы.$b$bИз семян прорастут лозы толщиной в руку и прочные, как сталь. Ступай, $n. Восстанови природное равновесие, нарушенное нагами!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Осыпьте семенами железной лозы пульты управления паровым насосом в Змеином озере, Озере Тенетопь, озере Болотных Огоньков и в Лагуне. Затем вернитесь к Исиэли Песни Ветра в Кенарийский оплот в Зангартопи и отдайте ей оставшиеся семена.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, |3-6($c), готово?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исиэли Песни Ветра в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9721,'Призыв леди Лиадрин','Твоя преданность ордену не осталась незамеченной: Лорд Соланар Кровогнев, правая рука самой Леди Лиадрин, пожелал встретиться с тобой.$B$BТакой чести удостаиваются немногие, $n. Обычно новыми кандидатами занимаюсь я, но Лорд Соланар считает, что ты – $gособенный:особенная;. Не упусти свой шанс, $n!','Поговорите с Лордом Соланаром в Луносвете.','В ближайшее время мы обсудим цель вашего визита. Во-первых, позвольте мне сказать, что я действительно впечатлен вашим служением и вашим умениям владеть Светом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв леди Лиадрин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя преданность ордену не осталась незамеченной: Лорд Соланар Кровогнев, правая рука самой Леди Лиадрин, пожелал встретиться с тобой.$B$BТакой чести удостаиваются немногие, $n. Обычно новыми кандидатами занимаюсь я, но Лорд Соланар считает, что ты – $gособенный:особенная;. Не упусти свой шанс, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лордом Соланаром в Луносвете.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В ближайшее время мы обсудим цель вашего визита. Во-первых, позвольте мне сказать, что я действительно впечатлен вашим служением и вашим умениям владеть Светом.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9722,'Путь мастера','В нашем ордене есть круг посвященных, в который входят только самые преданные, опытные и умелые рыцари. Отличить их можно по особой породе скакунов – талассийским скакунам.$B$BКаждый кандидат на титул мастера должен доказать свою верность идеалам ордена и заручиться поддержкой одного из посвященных.$B$BЕсли ты действительно желаешь стать мастером – я лично буду твоим покровителем.','Поговорите с Лордом Соланаром еще раз и примите предложение о покровительстве.','То, что вы решили принять мое предложение, говорит многое о вас, $N. Я желаю вам удачи в задачах, которые я вам поставлю, но я уверен, что вы проявите себя более чем способным. $B$BЯ представлю задачи в порядке от самого простого к самому сложному, и мы можем начать, когда вы будете готовы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь мастера',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В нашем ордене есть круг посвященных, в который входят только самые преданные, опытные и умелые рыцари. Отличить их можно по особой породе скакунов – талассийским скакунам.$B$BКаждый кандидат на титул мастера должен доказать свою верность идеалам ордена и заручиться поддержкой одного из посвященных.$B$BЕсли ты действительно желаешь стать мастером – я лично буду твоим покровителем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лордом Соланаром еще раз и примите предложение о покровительстве.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что вы решили принять мое предложение, говорит многое о вас, $N. Я желаю вам удачи в задачах, которые я вам поставлю, но я уверен, что вы проявите себя более чем способным. $B$BЯ представлю задачи в порядке от самого простого к самому сложному, и мы можем начать, когда вы будете готовы.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9723,'Жест преданности','Истинная преданность ордену доказывается не мечом, $n. Настоящий рыцарь должен быть готов выполнить любые поручения – какими бы мелкими и незначительными они не казались.$B$BИ сейчас тебе предстоит выполнить одно из таких поручений. Я дам тебе список предметов, которые необходимы поверенным магистра Асталора Кровавой Клятвы для поддержания энергии Света. Найди их и вернись ко мне.','Принесите Лорду Соланару в Луносвет 40 отрезов рунической ткани, 6 арканитовых слитков, 10 солнечников, 5 темных рун и 150 золотых.','Превосходно. Похоже, все здесь. $B$BНе волнуйтесь. Ваше следующее задание будет включать в себя множество возможностей снова овладеть вашим оружием, я обещаю. $B$BЯ попрошу посвященного отнести все Магистру Асталору. Нет необходимости отправлять вас по такому тривиальному поручению, когда есть более важные дела.','Вы вернулись с материалами, которые требуются Магистру Асталору?','Вернитесь к лорду Соланару Кровогневу в Луносвет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жест преданности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Истинная преданность ордену доказывается не мечом, $n. Настоящий рыцарь должен быть готов выполнить любые поручения – какими бы мелкими и незначительными они не казались.$B$BИ сейчас тебе предстоит выполнить одно из таких поручений. Я дам тебе список предметов, которые необходимы поверенным магистра Асталора Кровавой Клятвы для поддержания энергии Света. Найди их и вернись ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Лорду Соланару в Луносвет 40 отрезов рунической ткани, 6 арканитовых слитков, 10 солнечников, 5 темных рун и 150 золотых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно. Похоже, все здесь. $B$BНе волнуйтесь. Ваше следующее задание будет включать в себя множество возможностей снова овладеть вашим оружием, я обещаю. $B$BЯ попрошу посвященного отнести все Магистру Асталору. Нет необходимости отправлять вас по такому тривиальному поручению, когда есть более важные дела.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы вернулись с материалами, которые требуются Магистру Асталору?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Соланару Кровогневу в Луносвет.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9724,'Предупреждение Кругу Кенария','Принесенные тобой новости о деятельности наг в Зангартопи воистину ужасны! Исиэль поступила разумно, что сообщила об этом нам. Она не забывает, что экспедиции не выжить без поддержки Круга...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупреждение Кругу Кенария',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Принесенные тобой новости о деятельности наг в Зангартопи воистину ужасны! Исиэль поступила разумно, что сообщила об этом нам. Она не забывает, что экспедиции не выжить без поддержки Круга...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9725,'Доказательство лояльности','Защита земель Кель\'Таласа – священный долг рыцарей Крови, $n. Только благодаря нам и нашим союзникам жители Луносвета могут спать спокойно. Пришло время тебе разделить с нами эту обязанность.$B$BМне сообщили, что на юго-восточной границе, на окраине Восточных Чумных земель замечены воины Плети. Инженеры готовят свои машины к нападению на Призрачные земли. Их надо остановить!','Лорд Соланар Кровогнев из Луносвета просит уничтожить 3 мясных фургона и убить 15 инженеров Плети.','Вы хорошо проявили себя, продемонстрировав свою верность своей Родине и преданность нуждам ордена, $N. У меня есть последнее задание, прежде чем вы сможете претендовать на звание мастера.','С возвращением, $N. Ты $Gпобедил:победила; инженеров Плети и их мясные фургоны?','Вернитесь к лорду Соланару Кровогневу в Луносвет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доказательство лояльности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Защита земель Кель\'Таласа – священный долг рыцарей Крови, $n. Только благодаря нам и нашим союзникам жители Луносвета могут спать спокойно. Пришло время тебе разделить с нами эту обязанность.$B$BМне сообщили, что на юго-восточной границе, на окраине Восточных Чумных земель замечены воины Плети. Инженеры готовят свои машины к нападению на Призрачные земли. Их надо остановить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Лорд Соланар Кровогнев из Луносвета просит уничтожить 3 мясных фургона и убить 15 инженеров Плети.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы хорошо проявили себя, продемонстрировав свою верность своей Родине и преданность нуждам ордена, $N. У меня есть последнее задание, прежде чем вы сможете претендовать на звание мастера.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С возвращением, $N. Ты $Gпобедил:победила; инженеров Плети и их мясные фургоны?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Соланару Кровогневу в Луносвет.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9726,'Теперь, когда мы друзья...','Наги из анклава Кровавой Чешуи, что к северо-востоку отсюда, начали истреблять наш народ! $C, их необходимо остановить!$b$bНаучи их уму-разуму в доказательство нашей дружбы...','Убейте 12 надсмотрщиков за рабами из клана Кровавой Чешуи, 6 чародеек из клана Кровавой Чешуи и возвращайтесь к Гзхун\'тту в Спореггар в Зангартопи.','Ты еще не $Gпобывал:побывала; в гостях у наг?','Вернитесь к Гзхун\'тту в Спореггар, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теперь, когда мы друзья...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наги из анклава Кровавой Чешуи, что к северо-востоку отсюда, начали истреблять наш народ! $C, их необходимо остановить!$b$bНаучи их уму-разуму в доказательство нашей дружбы...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 надсмотрщиков за рабами из клана Кровавой Чешуи, 6 чародеек из клана Кровавой Чешуи и возвращайтесь к Гзхун\'тту в Спореггар в Зангартопи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты еще не $Gпобывал:побывала; в гостях у наг?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гзхун\'тту в Спореггар, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9727,'Раз уж мы по-прежнему друзья...','Поступили сведения, что наги из анклава Кровавой Чешуи на северо-востоке продолжают истреблять наш народ! А мы было решили, что тебе, |3-6($c), удалось с ними покончить!$b$bБыть может, ты поучишь их уму-разуму, в доказательство того, что наша дружба по-прежнему прочна?','Убейте 12 надсмотрщиков за рабами из клана Кровавой Чешуи, 6 чародеек из клана Кровавой Чешуи и возвращайтесь к Гзхун\'тту в Спореггар в Зангартопи.','Ты еще не $Gпобывал:побывала; в гостях у наг?','Вернитесь к Гзхун\'тту в Спореггар, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Раз уж мы по-прежнему друзья...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поступили сведения, что наги из анклава Кровавой Чешуи на северо-востоке продолжают истреблять наш народ! А мы было решили, что тебе, |3-6($c), удалось с ними покончить!$b$bБыть может, ты поучишь их уму-разуму, в доказательство того, что наша дружба по-прежнему прочна?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 надсмотрщиков за рабами из клана Кровавой Чешуи, 6 чародеек из клана Кровавой Чешуи и возвращайтесь к Гзхун\'тту в Спореггар в Зангартопи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты еще не $Gпобывал:побывала; в гостях у наг?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гзхун\'тту в Спореггар, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9728,'Теплый прием','Друиды из экспедиции занимаются тем, что изучают растения и исследуют озера, ну, а мое дело – разбираться с враждебными существами.$b$bС тех самых пор, как мы появились в Зангартопи, наги то и дело нападают на нас без вызова и предупреждения. Мы делаем все, что можем, чтобы противостоять им, но наши возможности ограничены.$b$bЯ бы попросил тебя побывать в нескольких крепостях наг в Зангартопи и показать этим тварям, что с нами лучше не связываться. А в доказательство твоих подвигов принеси мне их когти!','Принесите стражу-смотрителю Хамууту из Кенарийского оплота 30 когтей наг.','Вернитесь к стражу-смотрителю Хамууту в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Теплый прием',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Друиды из экспедиции занимаются тем, что изучают растения и исследуют озера, ну, а мое дело – разбираться с враждебными существами.$b$bС тех самых пор, как мы появились в Зангартопи, наги то и дело нападают на нас без вызова и предупреждения. Мы делаем все, что можем, чтобы противостоять им, но наши возможности ограничены.$b$bЯ бы попросил тебя побывать в нескольких крепостях наг в Зангартопи и показать этим тварям, что с нами лучше не связываться. А в доказательство твоих подвигов принеси мне их когти!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите стражу-смотрителю Хамууту из Кенарийского оплота 30 когтей наг.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу-смотрителю Хамууту в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9731,'Схема стоков','На добытой вами схеме изображена система подземных труб и насосов, ведущих от крупных озер на болотах Зангара к Змеиному озеру.$b$bЕсли верить этой схеме, в центре Змеиного озера находится огромная труба, куда и уходит вода. Проверьте эту информацию и передайте ее в Кенарийский оплот.','Найдите в Змеином озере признаки утечки воды. Вернитесь к Исиэли Песни Ветра в Кенарийский оплот и сообщите о своем открытии.','Утечка обнаружена','Вернитесь к Исиэли Песне Ветра в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Схема стоков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На добытой вами схеме изображена система подземных труб и насосов, ведущих от крупных озер на болотах Зангара к Змеиному озеру.$b$bЕсли верить этой схеме, в центре Змеиного озера находится огромная труба, куда и уходит вода. Проверьте эту информацию и передайте ее в Кенарийский оплот.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите в Змеином озере признаки утечки воды. Вернитесь к Исиэли Песни Ветра в Кенарийский оплот и сообщите о своем открытии.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Утечка обнаружена',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исиэли Песне Ветра в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9732,'Возвращение на болота','Возвращайся к Исиэли и дай ей знать, что помощь будет прислана при первой же возможности.$b$bНаших соратников удерживали дела на Лунной поляне и в Силитусе, однако мы сделаем все, что в наших силах, чтобы отправить подкрепление в Кенарийский оплот!','Вернитесь к Исиэли Песни Ветра в Кенарийском оплоте в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение на болота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возвращайся к Исиэли и дай ей знать, что помощь будет прислана при первой же возможности.$b$bНаших соратников удерживали дела на Лунной поляне и в Силитусе, однако мы сделаем все, что в наших силах, чтобы отправить подкрепление в Кенарийский оплот!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Исиэли Песни Ветра в Кенарийском оплоте в Зангартопи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9733,'Предупреждение Кругу Кенария','Кенарийская экспедиция теперь сделалась крупной, практически самостоятельной организацией. Но об этих событиях необходимо предупредить Круг Кенария.$b$bНе тревожься, тебе не придется возвращаться обратно в Лунную поляну. Посланцы Круга Кенария есть неподалеку отсюда, на Полуострове Адского Пламени.','Поговорите с Махурамом Крепким Копытом в Траллмаре на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предупреждение Кругу Кенария',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кенарийская экспедиция теперь сделалась крупной, практически самостоятельной организацией. Но об этих событиях необходимо предупредить Круг Кенария.$b$bНе тревожься, тебе не придется возвращаться обратно в Лунную поляну. Посланцы Круга Кенария есть неподалеку отсюда, на Полуострове Адского Пламени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Махурамом Крепким Копытом в Траллмаре на Полуострове Адского Пламени.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9734,'Возвращение на болота','Возвращайся к Исиэли и дай ей знать, что помощь будет прислана при первой же возможности.$b$bНаших соратников удерживали дела на Лунной поляне и в Силитусе, однако мы сделаем все, что в наших силах, чтобы отправить подкрепление в Кенарийский оплот!','Вернитесь к Исиэли Песни Ветра в Кенарийском оплоте в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение на болота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возвращайся к Исиэли и дай ей знать, что помощь будет прислана при первой же возможности.$b$bНаших соратников удерживали дела на Лунной поляне и в Силитусе, однако мы сделаем все, что в наших силах, чтобы отправить подкрепление в Кенарийский оплот!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Исиэли Песни Ветра в Кенарийском оплоте в Зангартопи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9735,'Истинные владыки Света','Рыцари Крови – настоящие владыки Света. Но те, кто называет себя "паладинами", отказываются верить в наше превосходство и желают подчинить Свет себе.$B$BПора показать им, что с нами шутки плохи. И я придумал, как это сделать! Сначала проберись в библиотечное крыло аббатства Длани Тира и выкради один фиал святой воды...','Принесите фиал святой воды Длани Тира Лорду Соланару Кровогневу в Луносвет.','Хм... это довольно небольшая сумма. но если мы будем осторожны. этого должно быть достаточно. Ты видишь. Алый орден считает себя посвященным Свету. $B$BИх ошибочное рвение испортило даже благословение, произнесенное над этой водой.','Удалось достать воду?','Вернитесь к лорду Соланару Кровогневу в Луносвет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истинные владыки Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рыцари Крови – настоящие владыки Света. Но те, кто называет себя "паладинами", отказываются верить в наше превосходство и желают подчинить Свет себе.$B$BПора показать им, что с нами шутки плохи. И я придумал, как это сделать! Сначала проберись в библиотечное крыло аббатства Длани Тира и выкради один фиал святой воды...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите фиал святой воды Длани Тира Лорду Соланару Кровогневу в Луносвет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... это довольно небольшая сумма. но если мы будем осторожны. этого должно быть достаточно. Ты видишь. Алый орден считает себя посвященным Свету. $B$BИх ошибочное рвение испортило даже благословение, произнесенное над этой водой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось достать воду?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Соланару Кровогневу в Луносвет.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9736,'Истинные владыки Света','Теперь, когда у нас есть святая вода, пора приняться за поиски недостающих реагентов. Я подскажу тебе, где отыскать два из них, $n.$B$BОтправляйся на площадь, что возле Тропы Мертвых, и найди в одной из лавок торговку по имени Залле. У нее сможешь купить чародейский катализатор. А за вторым реагентом, сумеречным порошком, тебе прямая дорога к Дарлии, торговке ядами. Найти ее можно неподалеку от наставников разбойников в Закоулке Душегубов.$B$BОставшиеся реагенты – азеротский бриллиант и безупречный черный алмаз – тебе придется искать $gсамому:самой;.','Принесите Лорду Соланару Кровогневу в Луносвет 1 чародейский катализатор, 1 меру сумеречного порошка, 1 азеротский алмаз и 1 безупречный черный алмаз.','Теперь, когда у нас есть все реагенты, я могу приготовить смесь. $B$B<Медленная улыбка расплывается по лицу леди Лиадрин.>$B$BВсе отлично складывается, $N. Когда это будет закончено, я подробно расскажу, что еще предстоит сделать.','Ты $Gсобрал:собрала; необходимые мне реагенты?','Вернитесь к лорду Соланару Кровогневу в Луносвет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истинные владыки Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у нас есть святая вода, пора приняться за поиски недостающих реагентов. Я подскажу тебе, где отыскать два из них, $n.$B$BОтправляйся на площадь, что возле Тропы Мертвых, и найди в одной из лавок торговку по имени Залле. У нее сможешь купить чародейский катализатор. А за вторым реагентом, сумеречным порошком, тебе прямая дорога к Дарлии, торговке ядами. Найти ее можно неподалеку от наставников разбойников в Закоулке Душегубов.$B$BОставшиеся реагенты – азеротский бриллиант и безупречный черный алмаз – тебе придется искать $gсамому:самой;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Лорду Соланару Кровогневу в Луносвет 1 чародейский катализатор, 1 меру сумеречного порошка, 1 азеротский алмаз и 1 безупречный черный алмаз.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда у нас есть все реагенты, я могу приготовить смесь. $B$B<Медленная улыбка расплывается по лицу леди Лиадрин.>$B$BВсе отлично складывается, $N. Когда это будет закончено, я подробно расскажу, что еще предстоит сделать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсобрал:собрала; необходимые мне реагенты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Соланару Кровогневу в Луносвет.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9737,'Истинные владыки Света','Только мы можем повелевать силой Света, $n. Пришло время раз и навсегда объяснить это глупцам, называющим себя "паладинами".$B$BЧасовня Алонсия, оплот рыцарей ордена Серебряной Длани, оказалась нетронутой даже после разрушения Стратхольма. Неугасимое пламя, что горит внутри часовни, – вот что защищает ее. Потуши пламя с помощью огнетушительной смеси, и пусть весь мир узнает, кто настоящие владыки Света!','Потушите неугасимое пламя часовни Алонсия с помощью огнетушительной смеси и уничтожьте всех, кто попробует защитить часовню.','$GМолодец:Умница;, $N. Всем, кто будет противостоять нам, следует прислушаться к вашему предупреждению. Наши враги должны знать, что они в опасности, от самого низшего пехотинца до самого могущественного героя. $B$BВы заслужили свое место в рядах мастеров. Ваша самоотверженность и доблесть служат примером для всех рыцарей крови. В знак вашего нового статуса я даю вам возможность призывать талассийского скакуна и управлять им.','Ты $Gсделал:сделала;, как я просила и $Gдоставил:доставила; мое сообщение? Лжепаладины мира наверняка знают, что их время подошло к концу.','Вернитесь к лорду Соланару Кровогневу в Луносвет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истинные владыки Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только мы можем повелевать силой Света, $n. Пришло время раз и навсегда объяснить это глупцам, называющим себя "паладинами".$B$BЧасовня Алонсия, оплот рыцарей ордена Серебряной Длани, оказалась нетронутой даже после разрушения Стратхольма. Неугасимое пламя, что горит внутри часовни, – вот что защищает ее. Потуши пламя с помощью огнетушительной смеси, и пусть весь мир узнает, кто настоящие владыки Света!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Потушите неугасимое пламя часовни Алонсия с помощью огнетушительной смеси и уничтожьте всех, кто попробует защитить часовню.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N. Всем, кто будет противостоять нам, следует прислушаться к вашему предупреждению. Наши враги должны знать, что они в опасности, от самого низшего пехотинца до самого могущественного героя. $B$BВы заслужили свое место в рядах мастеров. Ваша самоотверженность и доблесть служат примером для всех рыцарей крови. В знак вашего нового статуса я даю вам возможность призывать талассийского скакуна и управлять им.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсделал:сделала;, как я просила и $Gдоставил:доставила; мое сообщение? Лжепаладины мира наверняка знают, что их время подошло к концу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Соланару Кровогневу в Луносвет.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9738,'Погибли при исполнении','Умоляю, помоги мне! Нас прислала сюда Исиэль, чтобы мы разгадали загадку этих паровых насосов и выяснили, зачем они откачивают воду из болота. Однако мои друзья поступили опрометчиво – они разделились и отправились в разные стороны в одиночку.$B$BЭти четверо бывают такими недоумками, и все же я очень люблю их.$B$BПожалуйста, выясни что с ними сталось – я очень беспокоюсь. Поищи их в Узилище и в Нижетопи.$B$BБлагодарю тебя, |3-6($c).','Выясните, что стало с землепрядом Гневвсом, натуралистом Кусом, культиватором Зеленопалом и призывателем ветров Когтем. Затем возвращайтесь к дозорному Джанг в Резервуар Кривого Клыка в Зангартопь.','Ты $gвыяснил:выяснила;, что стало с моими друзьями?','Вернитесь к дозорному Джанг на Змеиное озеро, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Погибли при исполнении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Умоляю, помоги мне! Нас прислала сюда Исиэль, чтобы мы разгадали загадку этих паровых насосов и выяснили, зачем они откачивают воду из болота. Однако мои друзья поступили опрометчиво – они разделились и отправились в разные стороны в одиночку.$B$BЭти четверо бывают такими недоумками, и все же я очень люблю их.$B$BПожалуйста, выясни что с ними сталось – я очень беспокоюсь. Поищи их в Узилище и в Нижетопи.$B$BБлагодарю тебя, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выясните, что стало с землепрядом Гневвсом, натуралистом Кусом, культиватором Зеленопалом и призывателем ветров Когтем. Затем возвращайтесь к дозорному Джанг в Резервуар Кривого Клыка в Зангартопь.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gвыяснил:выяснила;, что стало с моими друзьями?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Джанг на Змеиное озеро, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9739,'Проблемы спорлингов','Эй, ты! Ты $gобязан:обязана; нам помочь!$b$bГрибные великаны пожирают все наши мешочки со спорами! Сделай что-нибудь, иначе мы останемся без потомства!$b$bМешочки со спорами поначалу большие, а потом уменьшаются, по мере того, как выходит наполняющий их воздух. Отыщи побольше маленьких зрелых мешочков со спорами и спаси их – столько, сколько сможешь!','Соберите 10 мешочков зрелых спор по просьбе Фассна из Грибной поляны.','Мешочки со спорами! Они у тебя?','Вернитесь к Фассну на Грибную поляну, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проблемы спорлингов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты! Ты $gобязан:обязана; нам помочь!$b$bГрибные великаны пожирают все наши мешочки со спорами! Сделай что-нибудь, иначе мы останемся без потомства!$b$bМешочки со спорами поначалу большие, а потом уменьшаются, по мере того, как выходит наполняющий их воздух. Отыщи побольше маленьких зрелых мешочков со спорами и спаси их – столько, сколько сможешь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 мешочков зрелых спор по просьбе Фассна из Грибной поляны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мешочки со спорами! Они у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фассну на Грибную поляну, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9740,'Солнечные Ворота','Благодаря тебе и тому, что ты $Gсделал:сделала;, мои разведчики сумели отыскать Солнечные Ворота. Эльфы постарались сделать так, чтобы Ворота можно было переместить в любой момент – именно потому на том месте, которое ты $Gисследовал:исследовала;, ничего не оказалось.$B$BОднако преимущество такой системы также является и ее величайшей слабостью. Солнечные Ворота стабилизируются при помощи пультов управления. Если мы сможем их уничтожить, то нам удастся уничтожить и сам портал. В настоящее время Солнечные Ворота находятся к западу отсюда, к югу от Энергоблока. Найди и уничтожь их!','Воздаятель Эсом из Кровавой заставы хочет, чтобы Солнечные Ворота были уничтожены.','Роскошно! Теперь врагам не получить подкреплений! Осталось только прикончить их...','Ты $Gдолжен:должна; уничтожить пульты управления, а после – и сами Солнечные Ворота!','Вернитесь к воздаятелю Эсому на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Солнечные Ворота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодаря тебе и тому, что ты $Gсделал:сделала;, мои разведчики сумели отыскать Солнечные Ворота. Эльфы постарались сделать так, чтобы Ворота можно было переместить в любой момент – именно потому на том месте, которое ты $Gисследовал:исследовала;, ничего не оказалось.$B$BОднако преимущество такой системы также является и ее величайшей слабостью. Солнечные Ворота стабилизируются при помощи пультов управления. Если мы сможем их уничтожить, то нам удастся уничтожить и сам портал. В настоящее время Солнечные Ворота находятся к западу отсюда, к югу от Энергоблока. Найди и уничтожь их!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воздаятель Эсом из Кровавой заставы хочет, чтобы Солнечные Ворота были уничтожены.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Роскошно! Теперь врагам не получить подкреплений! Осталось только прикончить их...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдолжен:должна; уничтожить пульты управления, а после – и сами Солнечные Ворота!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Эсому на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9741,'Твари из Бездны','Убейте 12 тварей Бездны и сообщите об этом на Кровавую заставу воздаятелю Эсому.','Вырастая, твари Бездны становятся аномалиями. Сказать по чести, мы толком не знаем, что это за существа... Можно сказать даже, что им придумали такое имя, просто чтобы как-то их называть.','Вернитесь к воздаятелю Эсому на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Твари из Бездны',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 тварей Бездны и сообщите об этом на Кровавую заставу воздаятелю Эсому.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вырастая, твари Бездны становятся аномалиями. Сказать по чести, мы толком не знаем, что это за существа... Можно сказать даже, что им придумали такое имя, просто чтобы как-то их называть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Эсому на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9742,'Новые мешочки со спорами','Да! Благодаря тебе спасено еще несколько мешочков со спорами!$B$BТы не такой, как другие пришельцы. Я поведаю моему народу о твоих деяниях!$B$B*Это задание можно выполнять повторно до тех пор, пока не добьешься дружелюбного отношения.*','Что, |3-6($r), тебе удалось спасти еще несколько мешочков со спорами?','Вернитесь к Фассну на Грибную поляну, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые мешочки со спорами',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да! Благодаря тебе спасено еще несколько мешочков со спорами!$B$BТы не такой, как другие пришельцы. Я поведаю моему народу о твоих деяниях!$B$B*Это задание можно выполнять повторно до тех пор, пока не добьешься дружелюбного отношения.*',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что, |3-6($r), тебе удалось спасти еще несколько мешочков со спорами?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фассну на Грибную поляну, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9743,'Природные враги','Мы, спорлинги, и болотники никогда особо не ладили. Однако в прошлом нам удавалось обороняться от них копьями и камнями. А в последнее время они сделались более агрессивными... или же более отчаянными. Они не боятся ни нас, ни нашего оружия.$b$bНо ты – ты куда страшнее, и оружие у тебя лучше нашего. Если ты согласишься сразиться за нас против болотников, мы будем твоими вечными должниками! Принеси мне их усики, чтобы знать, сколько их тебе удалось перебить.','Принесите Фассну из Грибной поляны в Зангартопи 6 усиков болотника.','Ну, как идет истребление болотников? Объясни этим тварям, что в земли спорлингов соваться не следует!','Вернитесь к Фассну на Грибную поляну, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Природные враги',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы, спорлинги, и болотники никогда особо не ладили. Однако в прошлом нам удавалось обороняться от них копьями и камнями. А в последнее время они сделались более агрессивными... или же более отчаянными. Они не боятся ни нас, ни нашего оружия.$b$bНо ты – ты куда страшнее, и оружие у тебя лучше нашего. Если ты согласишься сразиться за нас против болотников, мы будем твоими вечными должниками! Принеси мне их усики, чтобы знать, сколько их тебе удалось перебить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Фассну из Грибной поляны в Зангартопи 6 усиков болотника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как идет истребление болотников? Объясни этим тварям, что в земли спорлингов соваться не следует!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фассну на Грибную поляну, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9744,'Еще усиков!','Невероятно! Нужны сотни спорлингов, чтобы перебить столько же великанов, сколько ты! Я позабочусь о том, чтобы о твоих деяниях стало известно всем.$B$B*Это задание можно выполнять повторно до тех пор, пока не добьешься дружелюбного отношения.*','Тебе удалось перебить немало великанов, но немало их по-прежнему бродит по болотам. И они по-прежнему охотятся на наши мешочки со спорами!','Вернитесь к Фассну на Грибную поляну, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще усиков!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно! Нужны сотни спорлингов, чтобы перебить столько же великанов, сколько ты! Я позабочусь о том, чтобы о твоих деяниях стало известно всем.$B$B*Это задание можно выполнять повторно до тех пор, пока не добьешься дружелюбного отношения.*',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось перебить немало великанов, но немало их по-прежнему бродит по болотам. И они по-прежнему охотятся на наши мешочки со спорами!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фассну на Грибную поляну, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9745,'<DEPRECATED>Подавление пламени') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<DEPRECATED>Подавление пламени',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9746,'Границы возможного','Выше голову, $n! Победа близка! Теперь, когда Солнечные Ворота обнаружены, мы скоро прекратим эти эльфийские поставки. Думаю, заодно пришло время и сократить количество самих эльфов крови...$B$BК западу отсюда разбито множество лагерей Солнечных Ястребов – шагу нельзя ступить, чтобы не столкнуться с их защитником или пиромантом. Найди и убей их, а потом возвращайся ко мне.','Убейте 10 пиромантов и 10 защитников клана Солнечного Ястреба и сообщите об этом на Кровавую заставу воздаятелю Эсому.','Это, несомненно, ослабит их оборону. Теперь эльфы Крови не раз подумают, прежде чем попытаться напасть на нас!','Не может же их предводительница вечно скрываться от нас! Мы будем планомерно уничтожать один их лагерь за другим, пока не отыщем Сиронас.','Вернитесь к воздаятелю Эсому на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Границы возможного',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Выше голову, $n! Победа близка! Теперь, когда Солнечные Ворота обнаружены, мы скоро прекратим эти эльфийские поставки. Думаю, заодно пришло время и сократить количество самих эльфов крови...$B$BК западу отсюда разбито множество лагерей Солнечных Ястребов – шагу нельзя ступить, чтобы не столкнуться с их защитником или пиромантом. Найди и убей их, а потом возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 пиромантов и 10 защитников клана Солнечного Ястреба и сообщите об этом на Кровавую заставу воздаятелю Эсому.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это, несомненно, ослабит их оборону. Теперь эльфы Крови не раз подумают, прежде чем попытаться напасть на нас!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не может же их предводительница вечно скрываться от нас! Мы будем планомерно уничтожать один их лагерь за другим, пока не отыщем Сиронас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Эсому на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9747,'Племя Тенетопи','Да, наги ужасны. Но еще ужаснее племена предателей, Сломленных и Заблудших, которые им помогали!$b$bИ хуже всех – Заблудшие из племени Тенетопи. Они используют черную магию, чтобы захватывать и порабощать других! К беглым рабам они особенно жестоки. Если я покину убежище хоть на день, меня поймают и перережут мне горло!$b$bОтправляйся в деревню Тенетопь к югу отсюда, и перебей их и их предводителя, Катару. Пока они живы, я не перестаю опасаться за свою жизнь!','Отправляйтесь в деревню Тенетопь и убейте Катару, 8 провидцев Тенетопи, 6 знахарей Тенетопи и 6 оракулов Тенетопи по просьбе Икейена из Кенарийского оплота.','Ты $gвернулся:вернулась;? Что, Катару и рабовладельцы из племени Тенетопи уже мертвы?','Вернитесь к Икейену в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Племя Тенетопи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, наги ужасны. Но еще ужаснее племена предателей, Сломленных и Заблудших, которые им помогали!$b$bИ хуже всех – Заблудшие из племени Тенетопи. Они используют черную магию, чтобы захватывать и порабощать других! К беглым рабам они особенно жестоки. Если я покину убежище хоть на день, меня поймают и перережут мне горло!$b$bОтправляйся в деревню Тенетопь к югу отсюда, и перебей их и их предводителя, Катару. Пока они живы, я не перестаю опасаться за свою жизнь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в деревню Тенетопь и убейте Катару, 8 провидцев Тенетопи, 6 знахарей Тенетопи и 6 оракулов Тенетопи по просьбе Икейена из Кенарийского оплота.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gвернулся:вернулась;? Что, Катару и рабовладельцы из племени Тенетопи уже мертвы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Икейену в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9748,'Не пей эту воду!','Воздаятель Эсом на Кровавой заставе попросил вас принести пробу воды с острова Кровавой Дымки во флаконе, который он предоставил.','Как я и думал, вода покраснела от примесей, просочившихся из силового ядра.$B$BНадеюсь, тебе не пришло в голову искупаться в этой водичке?','Вернитесь к воздаятелю Эсому на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не пей эту воду!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воздаятель Эсом на Кровавой заставе попросил вас принести пробу воды с острова Кровавой Дымки во флаконе, который он предоставил.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как я и думал, вода покраснела от примесей, просочившихся из силового ядра.$B$BНадеюсь, тебе не пришло в голову искупаться в этой водичке?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Эсому на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9749,'Они живы! Может быть...','Ты представить себе не можешь, $n, что мне пришлось пережить! Ужас! Кошмарный сон!.. На нас набросились пауки, будь они прокляты, да к тому же их прародительница, чтоб у нее все лапы поотсыхали, как с неба свалилась и тут же запеленала нас всех в коконы!$B$BНо это еще полбеды: эта членистоногая зараза пристроилась рядом с нами и начала откладывать яйца! Представляешь? Она решила, что мы – отличный корм для ее молодняка. КОРМ! Вообрази только!$B$BМне-то кое-как удалось выбраться, а мои товарищи так и валяются там, спеленутые, как младенцы. В одиночку мне их не спасти: я даже близко не могу подойти к тому проклятому месту. Ты ведь поможешь мне, верно?$B$BРаспутай коконы! Может, кто-то из наших еще остался в живых!','Освободите 5 ученых экспедиции по просьбе ученого Корнелиуса.','Вернитесь к ученому Корнелиусу на Перевал Янтарной Паутины, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они живы! Может быть...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты представить себе не можешь, $n, что мне пришлось пережить! Ужас! Кошмарный сон!.. На нас набросились пауки, будь они прокляты, да к тому же их прародительница, чтоб у нее все лапы поотсыхали, как с неба свалилась и тут же запеленала нас всех в коконы!$B$BНо это еще полбеды: эта членистоногая зараза пристроилась рядом с нами и начала откладывать яйца! Представляешь? Она решила, что мы – отличный корм для ее молодняка. КОРМ! Вообрази только!$B$BМне-то кое-как удалось выбраться, а мои товарищи так и валяются там, спеленутые, как младенцы. В одиночку мне их не спасти: я даже близко не могу подойти к тому проклятому месту. Ты ведь поможешь мне, верно?$B$BРаспутай коконы! Может, кто-то из наших еще остался в живых!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 5 ученых экспедиции по просьбе ученого Корнелиуса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученому Корнелиусу на Перевал Янтарной Паутины, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9750,'UNUSED Срочная доставка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','UNUSED Срочная доставка',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9751,'Наследие Проклятых','Прошлой ночью в моем шатре объявился Эдвард Хейнс, капитан "Утерянной Надежды". Да-да, тот самый Эдвард Хейнс, который умер от цинги двадцать лет назад.$B$BПризрак поведал мне историю, от которой кровь застыла у меня в жилах. Тебе непременно нужно услышать эту историю – и выполнить одно задание. Прошу тебя, разыщи Эдварда на острове Драконьей Скорби; ты сможешь найти его к северо-востоку от Кровавой заставы.','Адмирал Одиссий просит разыскать капитана Эдварда Хейнса и поговорить с ним.','Скажи, ты, сухопутная мартышка, тебе приходилось слышать о проклятии? Ну да, конечно, разумеется, ничего! А между тем именно проклятье и потопило все эти корабли; вернее сказать, это сделал Заговоренный Риф – мерзейшее место в мире. Я и сам здесь торчу уже двадцать лет, если ты этого не знаешь. $B$BЯкорь мне в глотку!. . Вот тут-то я и помер, стал падалью, которой даже драконы брезгуют... Впрочем, это совсем другая история. Я сейчас не о том. Мы должны помочь тем злосчастным душам, которые попали в ловушку на этом рифе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Проклятых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прошлой ночью в моем шатре объявился Эдвард Хейнс, капитан "Утерянной Надежды". Да-да, тот самый Эдвард Хейнс, который умер от цинги двадцать лет назад.$B$BПризрак поведал мне историю, от которой кровь застыла у меня в жилах. Тебе непременно нужно услышать эту историю – и выполнить одно задание. Прошу тебя, разыщи Эдварда на острове Драконьей Скорби; ты сможешь найти его к северо-востоку от Кровавой заставы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Адмирал Одиссий просит разыскать капитана Эдварда Хейнса и поговорить с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Скажи, ты, сухопутная мартышка, тебе приходилось слышать о проклятии? Ну да, конечно, разумеется, ничего! А между тем именно проклятье и потопило все эти корабли; вернее сказать, это сделал Заговоренный Риф – мерзейшее место в мире. Я и сам здесь торчу уже двадцать лет, если ты этого не знаешь. $B$BЯкорь мне в глотку!. . Вот тут-то я и помер, стал падалью, которой даже драконы брезгуют... Впрочем, это совсем другая история. Я сейчас не о том. Мы должны помочь тем злосчастным душам, которые попали в ловушку на этом рифе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9752,'Спасение с озера Тенетопь','Пожалуйста, помоги мне выбраться отсюда!$b$bЯ собирала травы неподалеку от этого места, когда меня похитила толпа этих маленьких дикарей! Я пыталась сопротивляться, но их было слишком много.$b$bПомоги мне вырваться от этих жестоких тварей с их гнусной магией и вернуться в Кенарийский оплот!','Проводите Кайру Длинную Гриву в Кенарийский оплот в Зангартопи. Выполнив эту задачу, явитесь к Исиэли Песни Ветра.','Проводите Кайру Длинную Гриву в безопасное место','Вернитесь к Исиэли Песне Ветра в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение с озера Тенетопь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пожалуйста, помоги мне выбраться отсюда!$b$bЯ собирала травы неподалеку от этого места, когда меня похитила толпа этих маленьких дикарей! Я пыталась сопротивляться, но их было слишком много.$b$bПомоги мне вырваться от этих жестоких тварей с их гнусной магией и вернуться в Кенарийский оплот!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите Кайру Длинную Гриву в Кенарийский оплот в Зангартопи. Выполнив эту задачу, явитесь к Исиэли Песни Ветра.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводите Кайру Длинную Гриву в безопасное место',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исиэли Песне Ветра в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9757,'Охотница Келла Тетива Ночи','Охотница Келла Тетива Ночи ищет способных охотников. Она научит тебя приручать диких зверей – это очень важное умение для охотника.$b$bКелла живет рядом с причалом Валаара, небольшом порту на западе от Экзодара.','Поговорите с охотницей Келлой Тетивой Ночи рядом с причалом Валаара.','Сразу приступим к уроку!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охотница Келла Тетива Ночи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Охотница Келла Тетива Ночи ищет способных охотников. Она научит тебя приручать диких зверей – это очень важное умение для охотника.$b$bКелла живет рядом с причалом Валаара, небольшом порту на западе от Экзодара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с охотницей Келлой Тетивой Ночи рядом с причалом Валаара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сразу приступим к уроку!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9758,'Возвращение к чародею Вандрилу','А, ты здесь, как хорошо! И как раз вовремя! Здесь много что предстоит сделать!','Как только верну себе остаток припасов, смогу заняться делом. Войскам не уйти далеко, если они не смогут покупать то, что им нужно.\n\nЗона боевых действий – место прибыльное, не так ли, |3-6($C)? Ну да ладно, удалось ли тебе пробиться к моей повозке через полчища этих вурдалаков?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к чародею Вандрилу',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, ты здесь, как хорошо! И как раз вовремя! Здесь много что предстоит сделать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как только верну себе остаток припасов, смогу заняться делом. Войскам не уйти далеко, если они не смогут покупать то, что им нужно.\n\nЗона боевых действий – место прибыльное, не так ли, |3-6($C)? Ну да ладно, удалось ли тебе пробиться к моей повозке через полчища этих вурдалаков?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9762,'Неписаное пророчество','Эти острова станут домом для тысяч и тысяч; многие останутся здесь на всю жизнь. Если таково твое желание, можешь присоединиться к ним – но ты ведь вовсе не этого хочешь, $n?$B$B Велен кивает. $B$BДа, ты многое свершишь, прежде чем покинешь этот мир. Не страшись своей судьбы, шагни ей навстречу!$B$BНа прощание прими от меня два дара: плащ и перстень. Такие плащи носят только достойнейшие из братства Длани Аргуса, а права носить эти перстни-печатки удостаиваются лишь величайшие мудрецы. Ты $Gдостоин:достойна; этих даров – носи их с гордостью.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неписаное пророчество',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти острова станут домом для тысяч и тысяч; многие останутся здесь на всю жизнь. Если таково твое желание, можешь присоединиться к ним – но ты ведь вовсе не этого хочешь, $n?$B$B Велен кивает. $B$BДа, ты многое свершишь, прежде чем покинешь этот мир. Не страшись своей судьбы, шагни ей навстречу!$B$BНа прощание прими от меня два дара: плащ и перстень. Такие плащи носят только достойнейшие из братства Длани Аргуса, а права носить эти перстни-печатки удостаиваются лишь величайшие мудрецы. Ты $Gдостоин:достойна; этих даров – носи их с гордостью.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9763,'Убежище врага','Врага иногда можно уничтожить, тайком подобравшись к самому его логову.$B$BНесколько часов назад я видела, как отряд наг прошел через каменную арку во второй туннель слева. Я почти не понимаю их языка, однако одно слово сумела разобрать: Калитреш.$B$BДолжно быть, это вход в паровые подземелья, откуда полководец Калитреш осуществляет командование войсками. Найди и убей его! Я слишком слаба, чтобы помочь тебе.','Дозорный Джанг хочет, чтобы вы нашли и убили полководца Калитреша в Резервуаре Кривого Клыка.','Наш самый большой враг в регионе, наконец, мертв. Ты $Gоказал:оказала; экспедиции большую услугу, $N. $B$BМы всегда будем у тебя в долгу.','Что насчет Калитреша? Он мертв, $N?','Вернитесь к дозорному Джанг на Змеиное озеро, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убежище врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Врага иногда можно уничтожить, тайком подобравшись к самому его логову.$B$BНесколько часов назад я видела, как отряд наг прошел через каменную арку во второй туннель слева. Я почти не понимаю их языка, однако одно слово сумела разобрать: Калитреш.$B$BДолжно быть, это вход в паровые подземелья, откуда полководец Калитреш осуществляет командование войсками. Найди и убей его! Я слишком слаба, чтобы помочь тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дозорный Джанг хочет, чтобы вы нашли и убили полководца Калитреша в Резервуаре Кривого Клыка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наш самый большой враг в регионе, наконец, мертв. Ты $Gоказал:оказала; экспедиции большую услугу, $N. $B$BМы всегда будем у тебя в долгу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что насчет Калитреша? Он мертв, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Джанг на Змеиное озеро, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9764,'Приказы Леди Вайш','Письмо содержит подробные указания нагам Кривого Клыка, работающим в паровых подземельях. В письме сообщается о прибытии кенарийских друидов в регион и содержится приказ уничтожать их на месте. Количество воды, перенаправляемой в Резервуар Кривого Клыка из окрестных озер, велено удвоить. Приказ скреплен печатью Леди Вайш.$B$BПисьмо явно будет интересно друидам из Кенарийской экспедиции. Отнесите его их главе, Исиэли Песни Ветра.','Отнесите приказы Леди Вайш Исиэли Песни Ветра в Кенарийский оплот в Зангартопи.','Вайш!$B$BЭто намного больше, на что мы рассчитывали. Наши маленькие победы тут и там над нагами ничего не значат. $B$BЕсли в этом замешана леди Вайш, то действуют силы гораздо более могущественные, чем мы думали. $B$BТы хорошо $Gпоработал:поработала;, доставив это нам, $N. Теперь мы должны готовиться к войне.','Что у тебя там, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказы Леди Вайш',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Письмо содержит подробные указания нагам Кривого Клыка, работающим в паровых подземельях. В письме сообщается о прибытии кенарийских друидов в регион и содержится приказ уничтожать их на месте. Количество воды, перенаправляемой в Резервуар Кривого Клыка из окрестных озер, велено удвоить. Приказ скреплен печатью Леди Вайш.$B$BПисьмо явно будет интересно друидам из Кенарийской экспедиции. Отнесите его их главе, Исиэли Песни Ветра.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите приказы Леди Вайш Исиэли Песни Ветра в Кенарийский оплот в Зангартопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вайш!$B$BЭто намного больше, на что мы рассчитывали. Наши маленькие победы тут и там над нагами ничего не значат. $B$BЕсли в этом замешана леди Вайш, то действуют силы гораздо более могущественные, чем мы думали. $B$BТы хорошо $Gпоработал:поработала;, доставив это нам, $N. Теперь мы должны готовиться к войне.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что у тебя там, $N?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9765,'Готовься к войне','Кенарийская экспедиция вначале была вполне мирным предприятием. Однако теперь мы, очевидно, стоим на пороге войны с нагами.$B$BМногие из нас не против вступить в бой с врагом, но мы слишком плохо вооружены. Принеси мне оружие наг, и мы перекуем его на глефы и наконечники стрел.$B$BИмей в виду, нам подойдет только самое лучшее оружие, $n. Ищи наг в Резервуаре Кривого Клыка.','Добудьте оружие Змеиного Зуба у наг в Резервуаре Кривого Клыка и принесите его Исиэли Песни Ветра в Кенарийский оплот в Зангартопи.','Они отлично подойдут, $N. Принесите еще какое-нибудь оружие, которое найдете. Наша потребность велика, а ресурсы ограничены.','Вы получили оружие, которое я ищу, $N?','Вернитесь к Исиэли Песни Ветра в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Готовься к войне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кенарийская экспедиция вначале была вполне мирным предприятием. Однако теперь мы, очевидно, стоим на пороге войны с нагами.$B$BМногие из нас не против вступить в бой с врагом, но мы слишком плохо вооружены. Принеси мне оружие наг, и мы перекуем его на глефы и наконечники стрел.$B$BИмей в виду, нам подойдет только самое лучшее оружие, $n. Ищи наг в Резервуаре Кривого Клыка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте оружие Змеиного Зуба у наг в Резервуаре Кривого Клыка и принесите его Исиэли Песни Ветра в Кенарийский оплот в Зангартопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они отлично подойдут, $N. Принесите еще какое-нибудь оружие, которое найдете. Наша потребность велика, а ресурсы ограничены.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы получили оружие, которое я ищу, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исиэли Песни Ветра в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9766,'Оружие Кривого Клыка','Отличная работа, $N. Наги научатся не недооценивать нас.','Мы превратим собственную сталь наг в оружие, чтобы использовать против них. Принеси мне все вооружение, которое удалось спасти из резервуара Кривого Клыка.','Вернитесь к Исиэли Песни Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие Кривого Клыка',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Наги научатся не недооценивать нас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы превратим собственную сталь наг в оружие, чтобы использовать против них. Принеси мне все вооружение, которое удалось спасти из резервуара Кривого Клыка.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Исиэли Песни Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9767,'Врага нужно знать в лицо','Для того чтобы разбить врага, не всегда достаточно превосходить его силой или численностью. Часто победа основана на знании слабых мест противника, предугадывании их стратегии или тактики.$B$BМы знаем о нагах много, и все же их магия остается для нас загадкой.$B$BЯ хочу изучить магию наг Резервуара Кривого Клыка. Принеси мне одну из их книг заклинаний!','Добудьте книгу заклинаний Кривого Клыка у наг Резервуара Кривого Клыка и принесите ее Ашьену в Кенарийский оплот в Зангартопи.','Вернитесь к Ашьену в Зангартопь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Врага нужно знать в лицо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для того чтобы разбить врага, не всегда достаточно превосходить его силой или численностью. Часто победа основана на знании слабых мест противника, предугадывании их стратегии или тактики.$B$BМы знаем о нагах много, и все же их магия остается для нас загадкой.$B$BЯ хочу изучить магию наг Резервуара Кривого Клыка. Принеси мне одну из их книг заклинаний!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте книгу заклинаний Кривого Клыка у наг Резервуара Кривого Клыка и принесите ее Ашьену в Кенарийский оплот в Зангартопи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ашьену в Зангартопь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9768,'Книги заклинаний Кривого Клыка','Вернитесь к Ашьену в Зангартопь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Книги заклинаний Кривого Клыка',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ашьену в Зангартопь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9769,'Мода непредсказуема!','Принесите 8 прозрачных крыльев любых видов светлячков, обитающих в Зангартопи, Магаше с заставы Болотной Крысы.','Вернитесь к Магаше на Заставу Болотной Крысы, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мода непредсказуема!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 прозрачных крыльев любых видов светлячков, обитающих в Зангартопи, Магаше с заставы Болотной Крысы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Магаше на Заставу Болотной Крысы, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9770,'Опасные болотные клыки','Иногда я жалею, что Дэнжай не отправил с нами шамана, или не дал нам с собой хотя бы тотема, который мог бы отпугивать болотных потрошителей.$b$bЭта местность буквально кишит ими! Просто кошмар какой-то. Такое впечатление, что у них вообще нет естественных врагов.$b$bМы все по очереди занимаемся тем, что истребляем этих тварей. Ты $gпришел:пришла; как раз вовремя, $n. Поздравляю! Теперь засучи рукава и перебей побольше этих тварей!','Убейте 10 болотных потрошителей по просьбе Реавижа с заставы Болотной Крысы.','Кругом все еще полно болотных клыков! В чем дело, $N? Мне кажется, что ты еще не $Gуправился:управилась; со своим делом.','Вернитесь к Реавижу на Заставу Болотной Крысы, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасные болотные клыки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иногда я жалею, что Дэнжай не отправил с нами шамана, или не дал нам с собой хотя бы тотема, который мог бы отпугивать болотных потрошителей.$b$bЭта местность буквально кишит ими! Просто кошмар какой-то. Такое впечатление, что у них вообще нет естественных врагов.$b$bМы все по очереди занимаемся тем, что истребляем этих тварей. Ты $gпришел:пришла; как раз вовремя, $n. Поздравляю! Теперь засучи рукава и перебей побольше этих тварей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 болотных потрошителей по просьбе Реавижа с заставы Болотной Крысы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кругом все еще полно болотных клыков! В чем дело, $N? Мне кажется, что ты еще не $Gуправился:управилась; со своим делом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реавижу на Заставу Болотной Крысы, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9771,'Поиски разведчика Джиобы','Теперь, когда здешние места тебе более или менее знакомы, я хотел бы попросить твоей помощи в еще одном деле. Мертвая трясина – так мы зовем топи к северо-западу отсюда, – место гиблое. Никто никогда не видел там ни единой живой души – но, с другой стороны, никто там подолгу и не задерживался.$b$bИ вот наш разведчик, Джиоба, вызвался исследовать эту местность и доложить о том, что ему удалось обнаружить. Он ушел с заставы три дня тому назад и до сих пор не вернулся. А между тем Джиоба не из тех, кто уходит надолго и не подает о себе вестей. Попытайся его найти, $n!','Найдите разведчика Джиобу в Мертвой трясине, что в Зангартопи.','Да, труп действительно полностью соответствует описанию. Существо, убившее Джиобу, очевидно, застигло его врасплох, потому что оружие разведчика осталось в ножнах, а по земле разлито содержимое маленькой походной чернильницы...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски разведчика Джиобы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда здешние места тебе более или менее знакомы, я хотел бы попросить твоей помощи в еще одном деле. Мертвая трясина – так мы зовем топи к северо-западу отсюда, – место гиблое. Никто никогда не видел там ни единой живой души – но, с другой стороны, никто там подолгу и не задерживался.$b$bИ вот наш разведчик, Джиоба, вызвался исследовать эту местность и доложить о том, что ему удалось обнаружить. Он ушел с заставы три дня тому назад и до сих пор не вернулся. А между тем Джиоба не из тех, кто уходит надолго и не подает о себе вестей. Попытайся его найти, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите разведчика Джиобу в Мертвой трясине, что в Зангартопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, труп действительно полностью соответствует описанию. Существо, убившее Джиобу, очевидно, застигло его врасплох, потому что оружие разведчика осталось в ножнах, а по земле разлито содержимое маленькой походной чернильницы...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9772,'Донесение разведчика Джиобы','Тело разведчика Джиобы усеяно кусочками засохших грибов. Кто бы его ни убил, он явно принадлежал к той же породе гигантских вянущих грибов Мертвой трясины. Возможно, один из этих высохших великанов застал разведчика врасплох, когда тот писал свое донесение...$b$bНо не имея текста донесения, невозможно узнать, что же сумел обнаружить разведчик. Если донесение удастся найти, его необходимо доставить Зураю.','Добудьте донесение разведчика Джиобы у высохших великанов и вернитесь с ним к Зураю на заставу Болотной Крысы.','Вернитесь к Зураю на Заставу Болотной Крысы, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение разведчика Джиобы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тело разведчика Джиобы усеяно кусочками засохших грибов. Кто бы его ни убил, он явно принадлежал к той же породе гигантских вянущих грибов Мертвой трясины. Возможно, один из этих высохших великанов застал разведчика врасплох, когда тот писал свое донесение...$b$bНо не имея текста донесения, невозможно узнать, что же сумел обнаружить разведчик. Если донесение удастся найти, его необходимо доставить Зураю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте донесение разведчика Джиобы у высохших великанов и вернитесь с ним к Зураю на заставу Болотной Крысы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зураю на Заставу Болотной Крысы, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9773,'Довольно грибов!','Грибной суп, жаркое из грибов, грибной соус...$b$bГрибы, грибы, грибы! Кроме грибов, есть тут вообще нечего! Если ты говоришь, что хочешь есть, повар вручает тебе топор и велит нарубить себе грибов на ужин!$b$bТак вот, меня это достало. Я знаю: тут, в озерах, водится рыба! Конечно, она мерзкая на вид, но все лучше, чем эти грибы!$b$bСколько ты потребуешь с меня за то, чтобы я впервые за несколько недель могла нормально поесть?','Добудьте 8 филе угря с угрей из озера Тенетопь и принесите их Магаше на заставу Болотной Крысы.','Вернитесь к Магаше на Заставу Болотной Крысы, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Довольно грибов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грибной суп, жаркое из грибов, грибной соус...$b$bГрибы, грибы, грибы! Кроме грибов, есть тут вообще нечего! Если ты говоришь, что хочешь есть, повар вручает тебе топор и велит нарубить себе грибов на ужин!$b$bТак вот, меня это достало. Я знаю: тут, в озерах, водится рыба! Конечно, она мерзкая на вид, но все лучше, чем эти грибы!$b$bСколько ты потребуешь с меня за то, чтобы я впервые за несколько недель могла нормально поесть?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 8 филе угря с угрей из озера Тенетопь и принесите их Магаше на заставу Болотной Крысы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Магаше на Заставу Болотной Крысы, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9774,'Толстая чешуя гидры','Реавиж правильно сделал, что привез сюда кожаные доспехи. Мой доспех от здешней сырости ржавеет на глазах. Я мало-помалу заменяю проржавевшие чешуйки. У местных гидр – отличная, прочная чешуя, и болотная сырость им нипочем.$b$bНо отыскать подходящие чешуйки не так-то просто! Самые лучшие иногда оказываются обломанными или слишком истертыми. Так что принеси мне побольше хорошей чешуи, какую сумеешь добыть у гидр, водящихся в больших озерах.','Принесите Зураю на заставу Болотной Крысы 12 толстых чешуек гидры.','Чего ухмыляешься? Да, я знаю, мой доспех будет выглядеть странновато до тех пор, пока я не заменю все металлические чешуйки на новые, но лучше уж такой доспех, чем вовсе никакого!','Вернитесь к Зураю на Заставу Болотной Крысы, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Толстая чешуя гидры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Реавиж правильно сделал, что привез сюда кожаные доспехи. Мой доспех от здешней сырости ржавеет на глазах. Я мало-помалу заменяю проржавевшие чешуйки. У местных гидр – отличная, прочная чешуя, и болотная сырость им нипочем.$b$bНо отыскать подходящие чешуйки не так-то просто! Самые лучшие иногда оказываются обломанными или слишком истертыми. Так что принеси мне побольше хорошей чешуи, какую сумеешь добыть у гидр, водящихся в больших озерах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Зураю на заставу Болотной Крысы 12 толстых чешуек гидры.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чего ухмыляешься? Да, я знаю, мой доспех будет выглядеть странновато до тех пор, пока я не заменю все металлические чешуйки на новые, но лучше уж такой доспех, чем вовсе никакого!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зураю на Заставу Болотной Крысы, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9775,'Донесение темному охотнику Дэнжаю','Темный охотник Дэнжай, несомненно, рассчитывает получить донесение о моих успехах в обустройстве нашего форта. Я приготовил краткий отчет о том, что уже сделано здесь, но теперь, после гибели разведчика Джиобы, мне некого послать гонцом на базу Дэнжая, в Забра\'джин на западе.$b$bЕсли тебе все равно нужно в ту сторону, может быть, занесешь ему мой доклад? Поначалу Дэнжай может показаться жутковатым, но, когда к нему привыкнешь, он, в сущности, неплохой малый.','Отнесите донесение Зурая темному охотнику Дэнжаю в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение темному охотнику Дэнжаю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Темный охотник Дэнжай, несомненно, рассчитывает получить донесение о моих успехах в обустройстве нашего форта. Я приготовил краткий отчет о том, что уже сделано здесь, но теперь, после гибели разведчика Джиобы, мне некого послать гонцом на базу Дэнжая, в Забра\'джин на западе.$b$bЕсли тебе все равно нужно в ту сторону, может быть, занесешь ему мой доклад? Поначалу Дэнжай может показаться жутковатым, но, когда к нему привыкнешь, он, в сущности, неплохой малый.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите донесение Зурая темному охотнику Дэнжаю в Забра\'джин, что в Зангартопи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9776,'Прибежище Оребор','Как тебе известно, среди обитателей Телредора немало беженцев той войны, в результате которой число дренеев уменьшилось вдесятеро. И моя цель – сделать Телредор безопасной гаванью для всех наших союзников в этой борьбе. Есть и такие, кто хотел бы присоединиться к нам, но пока не готов к этому.$b$bМы должны помогать им, чем можем, $n! Группа Сломленных под предводительством Икути укрылась в развалинах старого храма к северо-западу от Змеиного озера. Отыщи их и протяни им руку помощи!','Поговорите с Икути в Прибежище Оребор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прибежище Оребор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как тебе известно, среди обитателей Телредора немало беженцев той войны, в результате которой число дренеев уменьшилось вдесятеро. И моя цель – сделать Телредор безопасной гаванью для всех наших союзников в этой борьбе. Есть и такие, кто хотел бы присоединиться к нам, но пока не готов к этому.$b$bМы должны помогать им, чем можем, $n! Группа Сломленных под предводительством Икути укрылась в развалинах старого храма к северо-западу от Змеиного озера. Отыщи их и протяни им руку помощи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Икути в Прибежище Оребор, что в Зангартопи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9777,'Споры гриба-блескуна','Видишь ли, |3-6($r), у нас на болотах гореть особо нечему, поэтому приходится искать другие способы освещения. Многие из болотных животных и растений испускают слабое свечение.$b$bДержать в клетках светящихся животных сложно, да и жестоко, поэтому мы используем для освещения грибы.$b$bМы собираем и выращиваем грибы-блескуны прямо здесь, однако периодически все же приходится пополнять запасы. Эти маленькие зеленые грибочки часто растут у подножия больших грибов в окрестностях Телредора.','Принесите 6 спор гриба-блескуна Руаму в Телредоре.','Судя по всему, скоро нам понадобятся новые грибы-блескуны...','Вернитесь к Руаму в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Споры гриба-блескуна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь ли, |3-6($r), у нас на болотах гореть особо нечему, поэтому приходится искать другие способы освещения. Многие из болотных животных и растений испускают слабое свечение.$b$bДержать в клетках светящихся животных сложно, да и жестоко, поэтому мы используем для освещения грибы.$b$bМы собираем и выращиваем грибы-блескуны прямо здесь, однако периодически все же приходится пополнять запасы. Эти маленькие зеленые грибочки часто растут у подножия больших грибов в окрестностях Телредора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 спор гриба-блескуна Руаму в Телредоре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Судя по всему, скоро нам понадобятся новые грибы-блескуны...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Руаму в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9778,'Страж-смотритель Хамуут','Прежде чем покинуть Кенарийский оплот, поговори-ка со стражем-смотрителем Хамуутом. Он отвечает за безопасность экспедиции.$b$bЕсли я не отправлю к нему $Gтакого опытного искателя приключений:такую опытную искательницу приключений;, как ты, он мне этого никогда не простит!','Явитесь к стражу-смотрителю Хамууту в Кенарийский оплот в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страж-смотритель Хамуут',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем покинуть Кенарийский оплот, поговори-ка со стражем-смотрителем Хамуутом. Он отвечает за безопасность экспедиции.$b$bЕсли я не отправлю к нему $Gтакого опытного искателя приключений:такую опытную искательницу приключений;, как ты, он мне этого никогда не простит!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к стражу-смотрителю Хамууту в Кенарийский оплот в Зангартопи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9779,'Перехват сообщения','Рад видеть тебя снова, $n. У меня тут возникла проблема – и, возможно, ты поможешь мне решить ее.$B$BНаши лазутчики в тылу врага доложили, что видели у Солнечных Ястребов какой-то странный документ.$B$BК сожалению, нам не удалось снять копию этого документа. А потому нужно, чтобы ты $Gотправился:отправилась; к этим Ястребам и $Gпопытался:попыталась; его раздобыть. Уверен: применив соответствующие методы, ты добьешься успеха. Как понимаешь, в средствах я тебя не ограничиваю...','Найдите послание Солнечных Ястребов. Возможно, для этого придется убить нескольких из них. Послание должно быть доставлено на Кровавую заставу воздаятелю Боросу.','Вернитесь к воздаятелю Боросу на Кровавую заставу, что на Острове Кровавой Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перехват сообщения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рад видеть тебя снова, $n. У меня тут возникла проблема – и, возможно, ты поможешь мне решить ее.$B$BНаши лазутчики в тылу врага доложили, что видели у Солнечных Ястребов какой-то странный документ.$B$BК сожалению, нам не удалось снять копию этого документа. А потому нужно, чтобы ты $Gотправился:отправилась; к этим Ястребам и $Gпопытался:попыталась; его раздобыть. Уверен: применив соответствующие методы, ты добьешься успеха. Как понимаешь, в средствах я тебя не ограничиваю...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите послание Солнечных Ястребов. Возможно, для этого придется убить нескольких из них. Послание должно быть доставлено на Кровавую заставу воздаятелю Боросу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Боросу на Кровавую заставу, что на Острове Кровавой Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9780,'Филе угрей из озера Тенетопь','Приятно видеть здесь новое лицо! Когда мы с Хаалруном впервые прибыли в Телредор, мы здесь были единственными чужаками, но с тех пор много воды утекло...$b$bТем не менее мы стараемся радушно принимать новоприбывших и заботимся о том, чтобы в городе не было недостатка в еде и припасах. Перед анахоретами Телредора мы в неоплатном долгу, однако мы стремимся не уступать им в великодушии и принимаем новичков так, как когда-то приняли нас.$b$bЕсли ты не против нам помочь, то в соседних озерах водится рыба, которая называется угорь из озера Тенетопь. Ею мы в основном и питаемся.','Принесите Нораани из Телредора 8 филе угря.','Спасибо за помощь, $n! Твоя щедрость не будет забыта.','Ну что, пополнишь ли ты наши запасы рыбы?','Вернитесь к Нораани в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Филе угрей из озера Тенетопь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приятно видеть здесь новое лицо! Когда мы с Хаалруном впервые прибыли в Телредор, мы здесь были единственными чужаками, но с тех пор много воды утекло...$b$bТем не менее мы стараемся радушно принимать новоприбывших и заботимся о том, чтобы в городе не было недостатка в еде и припасах. Перед анахоретами Телредора мы в неоплатном долгу, однако мы стремимся не уступать им в великодушии и принимаем новичков так, как когда-то приняли нас.$b$bЕсли ты не против нам помочь, то в соседних озерах водится рыба, которая называется угорь из озера Тенетопь. Ею мы в основном и питаемся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Нораани из Телредора 8 филе угря.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь, $n! Твоя щедрость не будет забыта.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, пополнишь ли ты наши запасы рыбы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нораани в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9781,'Слишком много ртов!','Когда я в последний раз ходил на охоту, мне попалась на глаза новая застава, которую строит группа троллей. Они тоже наверняка собираются охотиться в здешних местах!$b$bЕсли они вздумали поселиться здесь навсегда, конкуренция за добычу будет жестокая. На троллей мы напасть не можем – это приведет к войне. Но мы можем хотя бы убавить количество хищников, которые тоже конкурируют с нами.$b$bКаждая убитая тобой болотная гидра – это на три голодных рта меньше!','Убейте 10 болотных гидр и вернитесь к Хаалруну в Телредор.','Молодец! На ближайшее будущее этого должно быть достаточно, чтобы уменьшить конкуренцию. Но, конечно, со временем придется искать новые источники пищи. На одной рыбе и грибах прожить можно, но разнообразие не помешает...','Ну, как охота?','Вернитесь к Хаалруну в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слишком много ртов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я в последний раз ходил на охоту, мне попалась на глаза новая застава, которую строит группа троллей. Они тоже наверняка собираются охотиться в здешних местах!$b$bЕсли они вздумали поселиться здесь навсегда, конкуренция за добычу будет жестокая. На троллей мы напасть не можем – это приведет к войне. Но мы можем хотя бы убавить количество хищников, которые тоже конкурируют с нами.$b$bКаждая убитая тобой болотная гидра – это на три голодных рта меньше!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 болотных гидр и вернитесь к Хаалруну в Телредор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец! На ближайшее будущее этого должно быть достаточно, чтобы уменьшить конкуренцию. Но, конечно, со временем придется искать новые источники пищи. На одной рыбе и грибах прожить можно, но разнообразие не помешает...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как охота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хаалруну в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9782,'Мертвая трясина','Я довольно долго прожил среди анахоретов Телредора, и за это время неплохо изучил болота. В последнее время я начал замечать, что земли на северо-востоке меняются, и не в лучшую сторону.$b$bПрактически вся местная флора и фауна начала вянуть, чахнуть и гибнуть, причем без всяких видимых причин. У меня есть несколько идей относительно того, что там происходит, но все это не выходит за рамки гипотезы. Если бы тебе удалось принести мне оттуда образец почвы, я бы, возможно, сумел постичь эту тайну...','Принесите пробу почвы Мертвой трясины воздаятелю Идаару в Телредоре.','Почва, похоже, истощена. Но это еще ничего не объясняет. В чем же дело? Отчего же все внезапно принялось вымирать?','Ну что, удалось тебе добыть образец почвы Мертвой трясины?','Вернитесь к воздаятелю Идаару в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мертвая трясина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я довольно долго прожил среди анахоретов Телредора, и за это время неплохо изучил болота. В последнее время я начал замечать, что земли на северо-востоке меняются, и не в лучшую сторону.$b$bПрактически вся местная флора и фауна начала вянуть, чахнуть и гибнуть, причем без всяких видимых причин. У меня есть несколько идей относительно того, что там происходит, но все это не выходит за рамки гипотезы. Если бы тебе удалось принести мне оттуда образец почвы, я бы, возможно, сумел постичь эту тайну...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите пробу почвы Мертвой трясины воздаятелю Идаару в Телредоре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Почва, похоже, истощена. Но это еще ничего не объясняет. В чем же дело? Отчего же все внезапно принялось вымирать?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе добыть образец почвы Мертвой трясины?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Идаару в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9783,'Неестественная засуха','$n, принесенный тобой образец почвы практически лишен влаги! Если уж сама земля теряет влагу, значит, существа, обитающие в Мертвой трясине, жестоко страдают от засухи!$b$bЯ видел, что бывает, когда грибные великаны начинают вянуть и умирать от засухи. Они впадают в бешенство от мучений и нападают на всех, кого встретят на своем пути!$b$bЭти существа не понимают, что происходит. Спасти их мы не в силах – лучшее, что мы можем сделать, это прекратить их мучения.','Убейте 12 иссохших великанов по просьбе воздаятеля Идаара из Телредора.','Мне жаль убивать обитателей Мертвой трясины, но их все равно уже не спасти. Остается только попытаться восстановить эти земли и вырастить новое поколение великанов...','Вернитесь к воздаятелю Идаару в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неестественная засуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, принесенный тобой образец почвы практически лишен влаги! Если уж сама земля теряет влагу, значит, существа, обитающие в Мертвой трясине, жестоко страдают от засухи!$b$bЯ видел, что бывает, когда грибные великаны начинают вянуть и умирать от засухи. Они впадают в бешенство от мучений и нападают на всех, кого встретят на своем пути!$b$bЭти существа не понимают, что происходит. Спасти их мы не в силах – лучшее, что мы можем сделать, это прекратить их мучения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 иссохших великанов по просьбе воздаятеля Идаара из Телредора.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне жаль убивать обитателей Мертвой трясины, но их все равно уже не спасти. Остается только попытаться восстановить эти земли и вырастить новое поколение великанов...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Идаару в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9784,'Определение растений','Новые части растений мне всегда пригодятся! Сейчас, когда уровень воды в озерах постоянно снижается, у меня возникает чувство, что на болотах растет число пришлых растений. Однако чтобы подтвердить эту теорию, мне нужны точные цифры!','Вернитесь к Лауранне Тар\'вел в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Определение растений',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Новые части растений мне всегда пригодятся! Сейчас, когда уровень воды в озерах постоянно снижается, у меня возникает чувство, что на болотах растет число пришлых растений. Однако чтобы подтвердить эту теорию, мне нужны точные цифры!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лауранне Тар\'вел в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9785,'Благословение Древ','$n, тебе удалось заслужить доверие Кенарийской экспедиции! Пора тебе побеседовать с Древами, Ашьеном и Келетом, и попросить их благословения.$b$bЗнак Древ даст тебе великую силу. И по мере того, как наше уважение к тебе будет расти, его действие будет только усиливаться.$b$bСтупай, $n, попроси благословения у Древ!','Призывательница ветров Черное Копыто просит вас поговорить с Древами Ашьеном и Келетом в Кенарийском оплоте и получить их благословение.','$n, ты уже $gпоговорил:поговорила; с Древами?','Вернитесь к призывательнице ветров Черное Копыто в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение Древ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, тебе удалось заслужить доверие Кенарийской экспедиции! Пора тебе побеседовать с Древами, Ашьеном и Келетом, и попросить их благословения.$b$bЗнак Древ даст тебе великую силу. И по мере того, как наше уважение к тебе будет расти, его действие будет только усиливаться.$b$bСтупай, $n, попроси благословения у Древ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призывательница ветров Черное Копыто просит вас поговорить с Древами Ашьеном и Келетом в Кенарийском оплоте и получить их благословение.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$n, ты уже $gпоговорил:поговорила; с Древами?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к призывательнице ветров Черное Копыто в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9786,'Руины Боха\'му','До того как орки истребили большую часть моего народа, Телредор служил убежищем дренейским анахоретам и спиритуалистам. Небольшой орден спиритуалистов и поборников имел множество святилищ в здешних краях.$b$bВо время войны мы потеряли связь с анахоретами из святилищ, в особенности из храма Бохаму на юго-западе. До меня доходили сведения, что в тех местах обосновалась группа Заблудших, и они, возможно, даже используют развалины храма. Побывай в руинах Бохаму и расскажи мне о том, что там найдешь.','Исследуйте руины Бохаму по просьбе анахорета Ахуурна из Телредора.','Ну что, $n, $gпобывал:побывала; ли ты в руинах Бохаму? Можешь ли ты себе представить, как они выглядели в расцвете своего величия?','Руины Боха\'му исследованы','Вернитесь к анахорету Ахуурну в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины Боха\'му',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До того как орки истребили большую часть моего народа, Телредор служил убежищем дренейским анахоретам и спиритуалистам. Небольшой орден спиритуалистов и поборников имел множество святилищ в здешних краях.$b$bВо время войны мы потеряли связь с анахоретами из святилищ, в особенности из храма Бохаму на юго-западе. До меня доходили сведения, что в тех местах обосновалась группа Заблудших, и они, возможно, даже используют развалины храма. Побывай в руинах Бохаму и расскажи мне о том, что там найдешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте руины Бохаму по просьбе анахорета Ахуурна из Телредора.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $n, $gпобывал:побывала; ли ты в руинах Бохаму? Можешь ли ты себе представить, как они выглядели в расцвете своего величия?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Руины Боха\'му исследованы',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Ахуурну в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9787,'Идолы Дикотопи','Судя по твоим рассказам о том, что происходит в руинах Бохаму, это племя Заблудших поклоняется духам животных. Но прежде, чем познакомиться с ними поближе, нам следует больше узнать об их верованиях!$b$bВозвращайся в деревню Дикотопь и добудь втайне несколько их идолов, чтобы я мог их изучить. Только постарайся не рассердить самих Заблудших – это может помешать нам установить с ними контакт...','Соберите 6 идолов Дикотопи и вернитесь с ними к анахорету Ахуурну в Телредор.','Ну что, идолы у тебя?','Вернитесь к анахорету Ахуурну в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идолы Дикотопи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по твоим рассказам о том, что происходит в руинах Бохаму, это племя Заблудших поклоняется духам животных. Но прежде, чем познакомиться с ними поближе, нам следует больше узнать об их верованиях!$b$bВозвращайся в деревню Дикотопь и добудь втайне несколько их идолов, чтобы я мог их изучить. Только постарайся не рассердить самих Заблудших – это может помешать нам установить с ними контакт...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 идолов Дикотопи и вернитесь с ними к анахорету Ахуурну в Телредор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, идолы у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Ахуурну в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9788,'Темное, сырое место','Вскоре после того, как мне удалось бежать от племени Тенетопи, я укрылся в пещере к югу от их деревни. Я ведь не знал, что за эту пещеру сражаются между собой болотные твари и гриболюди!$b$bМне пришлось в спешке бежать оттуда, и я оставил там сундучок со всем, что у меня было.$b$bКакая насмешка судьбы: спасти свое имущество из деревни Тенетопь, чтобы почти сразу его потерять! Если ты согласишься принести мне мой сундучок, я подарю тебе какую-нибудь ценную вещь. Что скажешь, $n?','Отыщите вещи Икейена в пещере к югу от Тенетопи. Верните их Икейену в Кенарийском оплоте в Зангартопи.','Вернитесь к Икейену в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темное, сырое место',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вскоре после того, как мне удалось бежать от племени Тенетопи, я укрылся в пещере к югу от их деревни. Я ведь не знал, что за эту пещеру сражаются между собой болотные твари и гриболюди!$b$bМне пришлось в спешке бежать оттуда, и я оставил там сундучок со всем, что у меня было.$b$bКакая насмешка судьбы: спасти свое имущество из деревни Тенетопь, чтобы почти сразу его потерять! Если ты согласишься принести мне мой сундучок, я подарю тебе какую-нибудь ценную вещь. Что скажешь, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите вещи Икейена в пещере к югу от Тенетопи. Верните их Икейену в Кенарийском оплоте в Зангартопи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Икейену в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9789,'Охота на копытней','Хочешь стать $Gохотником:охотницей;? Сначала докажи, что ты этого $gдостоин:достойна;.$B$BМеня не волнует, сколько у тебя трофеев и как они были добыты. Если ты ни разу не $gбыл:была; с нами на охоте – считай, ты вообще ничего в этом не смыслишь. Начни с копытней, если $gты настоящий мужчина:тебе хватит смелости;.$B$BКак раз недавно я видел поблизости стадо копытней. Еще они водятся на юге.','Убейте 12 копытней и вернитесь к Хемингу Эрнестуэю в его охотничий лагерь в Награнде.','Вернитесь к Хемингу Эрнестуэю в охотничий лагерь Эрнестуэя, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на копытней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь стать $Gохотником:охотницей;? Сначала докажи, что ты этого $gдостоин:достойна;.$B$BМеня не волнует, сколько у тебя трофеев и как они были добыты. Если ты ни разу не $gбыл:была; с нами на охоте – считай, ты вообще ничего в этом не смыслишь. Начни с копытней, если $gты настоящий мужчина:тебе хватит смелости;.$B$BКак раз недавно я видел поблизости стадо копытней. Еще они водятся на юге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 копытней и вернитесь к Хемингу Эрнестуэю в его охотничий лагерь в Награнде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хемингу Эрнестуэю в охотничий лагерь Эрнестуэя, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9790,'Прозрачные крылья','Принесите Хаалруну из Телредора 8 прозрачных крыльев любых видов светляков, обитающих в Зангартопи.','Спасибо тебе, $n!$b$b*Хаалрун сочувственно улыбается.*$b$bНу, порадуйся хотя бы тому, что тебе не придется их отчищать! Это самая противная часть работы. Однако если их как следует отскоблить, ни за что не скажешь, что это крылья гигантского насекомого.','Ну что, удалось тебе раздобыть прозрачные крылья?','Вернитесь к Хаалруну в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прозрачные крылья',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Хаалруну из Телредора 8 прозрачных крыльев любых видов светляков, обитающих в Зангартопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе, $n!$b$b*Хаалрун сочувственно улыбается.*$b$bНу, порадуйся хотя бы тому, что тебе не придется их отчищать! Это самая противная часть работы. Однако если их как следует отскоблить, ни за что не скажешь, что это крылья гигантского насекомого.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе раздобыть прозрачные крылья?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хаалруну в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9791,'Опасные болотные клыки','Пока орки вели войну против моего народа, собиратели редко выбирались за пределы Телредора, поскольку боялись нападения или плена. Теперь мы чаще выходим за стены, но болота не стали менее опасными!$b$bТакое впечатление, что за последние несколько месяцев скаты Пустоты совершенно обнаглели. Не знаю, в чем дело, может быть, им сделалось труднее охотиться на их обычную добычу, но сейчас они то и дело нападают на наших собирателей. Если бы нам удалось уменьшить их численность в окрестностях Телредора, возможно, они оставили бы нас в покое...','Убейте 10 болотных потрошителей и вернитесь к Нораани в Телредор.','Удачна ли была твоя охота на болотных клыков?','Вернитесь к Нораани в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасные болотные клыки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока орки вели войну против моего народа, собиратели редко выбирались за пределы Телредора, поскольку боялись нападения или плена. Теперь мы чаще выходим за стены, но болота не стали менее опасными!$b$bТакое впечатление, что за последние несколько месяцев скаты Пустоты совершенно обнаглели. Не знаю, в чем дело, может быть, им сделалось труднее охотиться на их обычную добычу, но сейчас они то и дело нападают на наших собирателей. Если бы нам удалось уменьшить их численность в окрестностях Телредора, возможно, они оставили бы нас в покое...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 болотных потрошителей и вернитесь к Нораани в Телредор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удачна ли была твоя охота на болотных клыков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нораани в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9793,'Судьба Туурема','Хм... Да, я помню, как наши разведчики упоминали о руинах дренейского поселения в северной части леса. Самому мне об этих развалинах мало что известно, но ты, если хочешь, можешь поговорить с разведчиками.','Чем могу служить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Туурема',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хм... Да, я помню, как наши разведчики упоминали о руинах дренейского поселения в северной части леса. Самому мне об этих развалинах мало что известно, но ты, если хочешь, можешь поговорить с разведчиками.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем могу служить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9794,'Не время для любопытства','$n, я вынужден просить тебя об услуге. В другое время я сделал бы это сам, но у меня и без того дел невпроворот.$b$bУ меня есть соратник, по имени Киалон. Он живет в Сильванааре, что в Острогорье к северу отсюда. Он ждет от меня письма, хотя, подозреваю, ему не понравится то, что он прочтет.$b$bЕсли ты доставишь ему мой ответ, я буду тебе очень признателен. Только смотри, не вздумай читать это письмо! Оно предназначено только Киалону, и никому другому.','Доставьте письмо Тимоти Киалону в Сильванаар в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не время для любопытства',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я вынужден просить тебя об услуге. В другое время я сделал бы это сам, но у меня и без того дел невпроворот.$b$bУ меня есть соратник, по имени Киалон. Он живет в Сильванааре, что в Острогорье к северу отсюда. Он ждет от меня письма, хотя, подозреваю, ему не понравится то, что он прочтет.$b$bЕсли ты доставишь ему мой ответ, я буду тебе очень признателен. Только смотри, не вздумай читать это письмо! Оно предназначено только Киалону, и никому другому.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте письмо Тимоти Киалону в Сильванаар в Острогорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9795,'Угроза со стороны огров','На болотах становится все больше огров. Как будто мало нам было наг и их союзников! Огры уже захватили большую территорию на северо-западе, и слишком близко подобрались к нашим землям.$b$bНа место каждого убитого нами огра тотчас встают несколько новых. Даже не знаю, долго ли мы продержимся, если им взбредет в голову напасть на Забра\'джин! Ступай на север, в горы, в орочий Оплот Громоборцев, и сообщи Некхтару о нашем положении. Мы были бы рады любой помощи!','Отправляйтесь в Оплот Громоборцев в Острогорье и поговорите с Некхтаром.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза со стороны огров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На болотах становится все больше огров. Как будто мало нам было наг и их союзников! Огры уже захватили большую территорию на северо-западе, и слишком близко подобрались к нашим землям.$b$bНа место каждого убитого нами огра тотчас встают несколько новых. Даже не знаю, долго ли мы продержимся, если им взбредет в голову напасть на Забра\'джин! Ступай на север, в горы, в орочий Оплот Громоборцев, и сообщи Некхтару о нашем положении. Мы были бы рады любой помощи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Оплот Громоборцев в Острогорье и поговорите с Некхтаром.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9796,'Новости из Зангартопи','Да уж, давно пора ему достроить эту заставу! Слишком много наших гонцов погибло от рук разбойников из Альянса...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новости из Зангартопи',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да уж, давно пора ему достроить эту заставу! Слишком много наших гонцов погибло от рук разбойников из Альянса...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (9797,'Подкрепление для Гарадара','Поговорите с капитаном Крогханом в Гарадаре в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подкрепление для Гарадара',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Крогханом в Гарадаре в Награнде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9798,'Планы эльфов крови','Кажется, дренеи должны узнать об этих планах. Отнесите их воздаятелю Алдару на место крушения.','Отнесите планы эльфов крови воздаятелю Алдару на место крушения в долине Аммен.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Планы эльфов крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, дренеи должны узнать об этих планах. Отнесите их воздаятелю Алдару на место крушения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите планы эльфов крови воздаятелю Алдару на место крушения в долине Аммен.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9799,'Сбор трав','На полях Аммен, что на западе отсюда, обитают здешние корнехлесты. Воды ближайшего к ним озера очень загрязнены, и ботаник Таэрикс беспокоится, что после их очистки популяция корнехлестов не восстановится.$b$bСходи на поля Аммен, сорви несколько оскверненных цветов. Я взгляну на них и подумаю, что можно сделать. Их легко отличить от других по необычным красным лепесткам.','Сорвите 3 оскверненных цветка и вернитесь к ученице Вишаэль на месте крушения в долине Аммен.','Неплохие образцы. Спасибо за помощь. Как только я найду время и проведу анализ этих растений, можно будет примерно понять, сколько усилий потребуется для восстановления полей.','Вернитесь к Проэнтиусу на Место Крушения, что в Долине Ам') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор трав',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На полях Аммен, что на западе отсюда, обитают здешние корнехлесты. Воды ближайшего к ним озера очень загрязнены, и ботаник Таэрикс беспокоится, что после их очистки популяция корнехлестов не восстановится.$b$bСходи на поля Аммен, сорви несколько оскверненных цветов. Я взгляну на них и подумаю, что можно сделать. Их легко отличить от других по необычным красным лепесткам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сорвите 3 оскверненных цветка и вернитесь к ученице Вишаэль на месте крушения в долине Аммен.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохие образцы. Спасибо за помощь. Как только я найду время и проведу анализ этих растений, можно будет примерно понять, сколько усилий потребуется для восстановления полей.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Проэнтиусу на Место Крушения, что в Долине Ам',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9800,'Редкий деликатес','Ты еще не $Gготов:готова; встретиться с беспокойными стихиями Награнда. Прежде чем браться за задания Служителей Земли, тебе нужно сначала помочь $gсамому:самой; себе.$B$BНа западе ты найдешь кучки помета, оставленные местными четвероногими. Надо просеять помет и выбрать оттуда семена награндской караколлы. Из них я смогу приготовить пилюлю, которая поможет тебе в бою с беспокойными силами природы.$B$BВозвращайся, когда наберешь две горсти семян. Горсти отмеряй по меркам огров.','Принесите Повелителю стихий Ло\'апу к Трону Стихий в Награнде 8 семян караколлы.','Вернитесь к повелителю стихий Ло\'апу к Трону Стихий, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Редкий деликатес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты еще не $Gготов:готова; встретиться с беспокойными стихиями Награнда. Прежде чем браться за задания Служителей Земли, тебе нужно сначала помочь $gсамому:самой; себе.$B$BНа западе ты найдешь кучки помета, оставленные местными четвероногими. Надо просеять помет и выбрать оттуда семена награндской караколлы. Из них я смогу приготовить пилюлю, которая поможет тебе в бою с беспокойными силами природы.$B$BВозвращайся, когда наберешь две горсти семян. Горсти отмеряй по меркам огров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Повелителю стихий Ло\'апу к Трону Стихий в Награнде 8 семян караколлы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелителю стихий Ло\'апу к Трону Стихий, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9801,'Сбор реагентов','У меня такое ощущение, что эти Заблудшие не будут рады видеть дренея, а вот араккоа примут с распростертыми объятиями. Я могу создать зелье, которое позволит тебе ненадолго принять облик араккоа. Однако для этого требуется пара реагентов, которые нельзя хранить подолгу и необходимо использовать в течение нескольких часов после того, как они были добыты.$b$bТебе придется принести мне горсть глаз спороската и несколько щупалец болотного долгонога. Оба вида обитают поблизости от Телредора.','Принесите анахорету Ахууму в Телредоре 4 глаза спороската и 4 щупальца болотного долгонога.','Да, это отлично подойдет! Минутку, я сейчас приготовлю зелье...','Ну что, реагенты при тебе?','Вернитесь к анахорету Ахуурну в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор реагентов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня такое ощущение, что эти Заблудшие не будут рады видеть дренея, а вот араккоа примут с распростертыми объятиями. Я могу создать зелье, которое позволит тебе ненадолго принять облик араккоа. Однако для этого требуется пара реагентов, которые нельзя хранить подолгу и необходимо использовать в течение нескольких часов после того, как они были добыты.$b$bТебе придется принести мне горсть глаз спороската и несколько щупалец болотного долгонога. Оба вида обитают поблизости от Телредора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите анахорету Ахууму в Телредоре 4 глаза спороската и 4 щупальца болотного долгонога.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это отлично подойдет! Минутку, я сейчас приготовлю зелье...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, реагенты при тебе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Ахуурну в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9802,'Растения Зангартопи','Озера Зангартопи мало-помалу пересыхают. Почему – мы точно не знаем, но известно, что многие виды растений уже находятся на грани вымирания.$b$bПоскольку я – каталогизатор экспедиции, в мои обязанности входит отслеживать и идентифицировать вымирающие растения, чтобы мы могли понять, что с ними происходит.$b$bЕсли вы хотели бы нам помочь, приносите мне неопознанные части растений. Их можно собирать самостоятельно, если вы $gтравник:травница;, а еще их иногда имеют при себе обитатели болот.','Принесите 10 неопознанных частей растений Лауранне Тар\'вел в Кенарийском оплоте в Зангартопи.','Вернитесь к Лауранне Тар\'вел в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растения Зангартопи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Озера Зангартопи мало-помалу пересыхают. Почему – мы точно не знаем, но известно, что многие виды растений уже находятся на грани вымирания.$b$bПоскольку я – каталогизатор экспедиции, в мои обязанности входит отслеживать и идентифицировать вымирающие растения, чтобы мы могли понять, что с ними происходит.$b$bЕсли вы хотели бы нам помочь, приносите мне неопознанные части растений. Их можно собирать самостоятельно, если вы $gтравник:травница;, а еще их иногда имеют при себе обитатели болот.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 неопознанных частей растений Лауранне Тар\'вел в Кенарийском оплоте в Зангартопи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лауранне Тар\'вел в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9803,'Посланец в Дикотопь','Пришло время встретиться с племенем из Дикотопи и внушить им, что Свет не отрекся от них. Возьми с собой приготовленное мною зелье и отправляйся в руины Бохаму.$b$bПридя в руины, выпей зелье. Оно придаст тебе облик одного из их птичьих духов. Поговори со старейшиной Курути и дай ему знать, что дренеи готовы принять его народ, как своих давно потерянных братьев.','Придите в руины Бохаму и выпейте эликсир Ахуума. Приняв обличье араккоа, поговорите со старейшиной Курути.','Вернитесь к анахорету Ахуурну в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посланец в Дикотопь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время встретиться с племенем из Дикотопи и внушить им, что Свет не отрекся от них. Возьми с собой приготовленное мною зелье и отправляйся в руины Бохаму.$b$bПридя в руины, выпей зелье. Оно придаст тебе облик одного из их птичьих духов. Поговори со старейшиной Курути и дай ему знать, что дренеи готовы принять его народ, как своих давно потерянных братьев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Придите в руины Бохаму и выпейте эликсир Ахуума. Приняв обличье араккоа, поговорите со старейшиной Курути.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Ахуурну в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9804,'Беспокойные духи озера Небесной Песни','Нарушение цикла приливов и отливов награндских вод взбудоражило водных духов озера Небесной Песни. И они, в свою очередь, тоже стали нести разрушение по водным путям.$B$BВатуусан Водный явился нам в видении и дал разрешение устранить эту проблему – при условии, что мы разберемся и с изначальным источником беспокойства...$B$BНо всему свое время. Сначала нам следует устранить опасность, непосредственно угрожающую Трону. Уничтожь взбешенных озерных духов и возвращайся ко мне.','Уничтожьте 8 озерных духов по просьбе Повелителя cтихий Ло\'апа, обитающего у Трона Стихий.','Вернитесь к повелителю стихий Ло\'апу к Трону Стихий, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беспокойные духи озера Небесной Песни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нарушение цикла приливов и отливов награндских вод взбудоражило водных духов озера Небесной Песни. И они, в свою очередь, тоже стали нести разрушение по водным путям.$B$BВатуусан Водный явился нам в видении и дал разрешение устранить эту проблему – при условии, что мы разберемся и с изначальным источником беспокойства...$B$BНо всему свое время. Сначала нам следует устранить опасность, непосредственно угрожающую Трону. Уничтожь взбешенных озерных духов и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 8 озерных духов по просьбе Повелителя cтихий Ло\'апа, обитающего у Трона Стихий.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелителю стихий Ло\'апу к Трону Стихий, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9805,'Благословение Возжигателя','Презренные Заблудшие до сих пор не высовывались из Зангартопи, но теперь они собираются разнести свою скверну по всему нашему миру.$B$BЯ попросил совета у сил природы и получил их благословение. Чтобы остановить нашествие, мы должны натравить на Заблудших стихии!$B$BЯ одолжу тебе живой огонь, взятый от пылающей сущности самого Возжигателя. Отправляйся на юго-восток, в деревню Трепещущего Тростника, и запусти им живой огонь под крыши! Пусть мерзавцы познают ярость стихий!','Спалите самый большой дом и три лачуги на западной, восточной и южной окраинах деревни Трепещущего Тростника.$B$BКогда выполните поручение, верните живой огонь Повелителю стихий Ло\'апу.','Твои усилия приостановили распространение скверны, но теперь возникли иные трудности.','Вернитесь к повелителю стихий Ло\'апу к Трону Стихий, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благословение Возжигателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Презренные Заблудшие до сих пор не высовывались из Зангартопи, но теперь они собираются разнести свою скверну по всему нашему миру.$B$BЯ попросил совета у сил природы и получил их благословение. Чтобы остановить нашествие, мы должны натравить на Заблудших стихии!$B$BЯ одолжу тебе живой огонь, взятый от пылающей сущности самого Возжигателя. Отправляйся на юго-восток, в деревню Трепещущего Тростника, и запусти им живой огонь под крыши! Пусть мерзавцы познают ярость стихий!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спалите самый большой дом и три лачуги на западной, восточной и южной окраинах деревни Трепещущего Тростника.$B$BКогда выполните поручение, верните живой огонь Повелителю стихий Ло\'апу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твои усилия приостановили распространение скверны, но теперь возникли иные трудности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелителю стихий Ло\'апу к Трону Стихий, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9806,'Прорастающие споры','Спороскаты и болотоброды бродят среди высоких грибочков и собирают прорастающие споры своими конечностями.$b$bМы, как видишь, народец низкорослый, и сами добывать эти споры можем с большим трудом. Ищи спороскатов и болотобродов, и собирай прорастающие споры. Весь Спореггар будет тебе крайне признателен.','Соберите 6 прорастающих спор с различных спороскатов и болотобродов в Зангартопи. Выполнив задачу, вернитесь к Гшаффу в Спореггар.','Вернитесь к Гшаффу в Спореггар, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорастающие споры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спороскаты и болотоброды бродят среди высоких грибочков и собирают прорастающие споры своими конечностями.$b$bМы, как видишь, народец низкорослый, и сами добывать эти споры можем с большим трудом. Ищи спороскатов и болотобродов, и собирай прорастающие споры. Весь Спореггар будет тебе крайне признателен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 6 прорастающих спор с различных спороскатов и болотобродов в Зангартопи. Выполнив задачу, вернитесь к Гшаффу в Спореггар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гшаффу в Спореггар, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9807,'Новые прорастающие споры','Мы ценим твою помощь, $n. Ждем новых спор!','Лишние прорастающие споры нам всегда пригодятся, |3-6($r)! Хвастливые грибочки чрезвычайно полезны. Если мы сможем их выращивать, это значительно расширит наши возможности.','Вернитесь к Гшаффу в Спореггар, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новые прорастающие споры',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы ценим твою помощь, $n. Ждем новых спор!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лишние прорастающие споры нам всегда пригодятся, |3-6($r)! Хвастливые грибочки чрезвычайно полезны. Если мы сможем их выращивать, это значительно расширит наши возможности.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гшаффу в Спореггар, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9808,'Грибы-огнешляпки','Я видел, как твои сородичи обменивают нужные им вещи на блестящие металлические кругляшки. Мы от вас не так сильно отличаемся. У нас тоже есть свои деньги: блестящие кругленькие грибочки.$b$bГрибы-огнешляпки растут на болотах повсюду, нужно только уметь добыть их из земли, не повредив. Я тебя этому научу, если только обещаешь принести несколько штук нам, в нашу казну. Ну что, идет?','Принесите 10 огнешляпок Мссхи\'фну в Спореггар в Зангартопи.','Вернитесь к Мссхи\'фну в Спореггар, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грибы-огнешляпки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я видел, как твои сородичи обменивают нужные им вещи на блестящие металлические кругляшки. Мы от вас не так сильно отличаемся. У нас тоже есть свои деньги: блестящие кругленькие грибочки.$b$bГрибы-огнешляпки растут на болотах повсюду, нужно только уметь добыть их из земли, не повредив. Я тебя этому научу, если только обещаешь принести несколько штук нам, в нашу казну. Ну что, идет?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 огнешляпок Мссхи\'фну в Спореггар в Зангартопи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мссхи\'фну в Спореггар, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9809,'Нужно больше грибов!','Если у тебя есть еще огнешляпки, я бы взял. Нашей деревне они всегда пригодятся.','Вернитесь к Мссхи\'фну в Спореггар, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нужно больше грибов!',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя есть еще огнешляпки, я бы взял. Нашей деревне они всегда пригодятся.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мссхи\'фну в Спореггар, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9810,'Оскверненный дух','Ватуусану удалось остановить распространение скверны, но при этом он нечаянно создал искаженного духа. И этот дух вобрал в себя всю скверну и порчу!$B$BТебе нужно найти этого искаженного духа болот. Он укрылся в глубинах озера Солнечного Источника к юго-западу отсюда.$B$BРазыщи и уничтожь искаженного духа Ватуусана, а также все его порождения, также тронутые скверной.','Уничтожьте загрязненную сущность Ватуусана и 8 озерных волноплесков по просьбе Повелителя cтихий Ло\'апа.','Вернитесь к повелителю стихий Ло\'апу к Трону Стихий, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненный дух',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ватуусану удалось остановить распространение скверны, но при этом он нечаянно создал искаженного духа. И этот дух вобрал в себя всю скверну и порчу!$B$BТебе нужно найти этого искаженного духа болот. Он укрылся в глубинах озера Солнечного Источника к юго-западу отсюда.$B$BРазыщи и уничтожь искаженного духа Ватуусана, а также все его порождения, также тронутые скверной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте загрязненную сущность Ватуусана и 8 озерных волноплесков по просьбе Повелителя cтихий Ло\'апа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелителю стихий Ло\'апу к Трону Стихий, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9811,'Друг син\'дорай','Принесите голову Дар\'Кхана Лор\'темару Терону в Луносвет.','Так значит, ты $Gубил:убила; Дар\'Кхана, |3-6($R)? Прекрасно, прекрасно. Думаю, это станет началом крепкой дружбы между нашими народами.','Ты хочешь поговорить со мной, |3-6($C)? Не припомню, чтобы назначал тебе встречу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друг син\'дорай',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову Дар\'Кхана Лор\'темару Терону в Луносвет.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так значит, ты $Gубил:убила; Дар\'Кхана, |3-6($R)? Прекрасно, прекрасно. Думаю, это станет началом крепкой дружбы между нашими народами.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь поговорить со мной, |3-6($C)? Не припомню, чтобы назначал тебе встречу.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (9812,'Посол к Орде','Наши потенциальные союзники сомневались в наших способностях. Какая им от нас польза, если мы собственные проблемы решить не можем?$B$BТеперь все изменилось. В нашей силе никто не усомнится. Мы сможем вступить в Орду как равные.$B$BОтнеси это письмо Сильване, правительнице Отрекшихся. Она и так на нашей стороне, но весть о смерти Дар\'Кхана будет воистину музыкой для ее ушей. Готовься к долгому пути, $n. Если все сложится благополучно, Сильвана пошлет тебя в Оргриммар.','А, гость из Кель\'Таласа! Какие вести ты $Gпринес:принесла;?','А, гость из Кель\'Таласа! Какие вести ты $Gпринес:принесла;?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посол к Орде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши потенциальные союзники сомневались в наших способностях. Какая им от нас польза, если мы собственные проблемы решить не можем?$B$BТеперь все изменилось. В нашей силе никто не усомнится. Мы сможем вступить в Орду как равные.$B$BОтнеси это письмо Сильване, правительнице Отрекшихся. Она и так на нашей стороне, но весть о смерти Дар\'Кхана будет воистину музыкой для ее ушей. Готовься к долгому пути, $n. Если все сложится благополучно, Сильвана пошлет тебя в Оргриммар.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, гость из Кель\'Таласа! Какие вести ты $Gпринес:принесла;?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, гость из Кель\'Таласа! Какие вести ты $Gпринес:принесла;?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (9813,'<Саурфанг начинает читать письмо.>$B$BЗначит, эльфы крови наконец разобрались со своей неприятностью. Меня не удивляет, что для этого потребовалась твоя помощь и целый отряд Отрекшихся. $B$B<Саурфанг смеется.>$B$BНу, с этим уж ничего не поделаешь. В конце концов, они нам нужны не меньше, чем мы им.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Саурфанг начинает читать письмо.>$B$BЗначит, эльфы крови наконец разобрались со своей неприятностью. Меня не удивляет, что для этого потребовалась твоя помощь и целый отряд Отрекшихся. $B$B<Саурфанг смеется.>$B$BНу, с этим уж ничего не поделаешь. В конце концов, они нам нужны не меньше, чем мы им.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9814,'Грибы-пороховики, слышь?','Любишь грибочки, а? Тут, в Зангартопи, у самого Забра\'джина, растут крутые грибочки!$b$bТолько смотри, держи ухо востро! Их не зря зовут пороховиками. Если подойдешь слишком близко, и не остережешься, они взрываются прямо тебе в лицо. Бабах – и ты с головы до ног в ядовитых спорах!$b$bЯ их использовал, чтобы толковать предсказания, но мои запасы почти закончились...','Принесите знахарю Тор\'геш 6 грибов-пороховиков.','Во, отлично!$B$BСлышь, че я тебе скажу? За эти грибочки я тебе устрою потеху!','Ну че, где мои грибочки?','Вернитесь к знахарю Тор\'гешу в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грибы-пороховики, слышь?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Любишь грибочки, а? Тут, в Зангартопи, у самого Забра\'джина, растут крутые грибочки!$b$bТолько смотри, держи ухо востро! Их не зря зовут пороховиками. Если подойдешь слишком близко, и не остережешься, они взрываются прямо тебе в лицо. Бабах – и ты с головы до ног в ядовитых спорах!$b$bЯ их использовал, чтобы толковать предсказания, но мои запасы почти закончились...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите знахарю Тор\'геш 6 грибов-пороховиков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Во, отлично!$B$BСлышь, че я тебе скажу? За эти грибочки я тебе устрою потеху!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну че, где мои грибочки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Тор\'гешу в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9815,'Грязные делишки','Духи воды, подвергшиеся наиболее пагубному воздействию, обитают в котловине Халаани к юго-западу отсюда, у заброшенного города Халаа. И хотя некоторые зараженные духи могут быть уничтожены без вреда для окружающей среды, останки порождений грязи тоже должны быть устранены.$B$BИначе эти ядра, остающиеся после уничтожения порождений, могут снова загрязнить окружающую среду.$B$BУничтожь порождения грязи и принеси мне их ядра.','Принесите Повелителю стихий Ло\'апу к Трону Стихий в Награнде 5 ядер порождений грязи.','Смотри, чтобы там не осталось ни единой крупинки грязи!','Вернитесь к повелителю стихий Ло\'апу к Трону Стихий, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязные делишки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духи воды, подвергшиеся наиболее пагубному воздействию, обитают в котловине Халаани к юго-западу отсюда, у заброшенного города Халаа. И хотя некоторые зараженные духи могут быть уничтожены без вреда для окружающей среды, останки порождений грязи тоже должны быть устранены.$B$BИначе эти ядра, остающиеся после уничтожения порождений, могут снова загрязнить окружающую среду.$B$BУничтожь порождения грязи и принеси мне их ядра.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Повелителю стихий Ло\'апу к Трону Стихий в Награнде 5 ядер порождений грязи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Смотри, чтобы там не осталось ни единой крупинки грязи!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелителю стихий Ло\'апу к Трону Стихий, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9816,'Видали вы такое?','Все в этом болоте есть, одного не хватает: мурлоков!$b$bНо ты не дрейфь: я придумал, как это уладить. Вон, видишь Булька с Гурглом, какие они прикольные? Так вот, я собираюсь подарить Заблудшим таких же забавных мурлоков!$b$bВот, бери эту клетку, тащи ее к деревне Остротопь и выпусти этих малявок среди северо-восточного скопления хижин. Нет, Булька с Гурглом я с тобой не отпущу. Но эти разноцветные мелкие мурлоки ничем не хуже! Поставь клетку на большой плоский камень, который там увидишь, и открой дверцу!','Отнесите клетку с мурлоками в деревню Остротопь и оставьте ее на плоском камне.','Ай, молодца! Надеюсь, им там теперь не скучно!','<Знахарь Тор\'гаш усмехается.>$B$BПонравился ли подарок маленьким мурлокам?','Вернитесь к знахарю Тор\'гешу в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Видали вы такое?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все в этом болоте есть, одного не хватает: мурлоков!$b$bНо ты не дрейфь: я придумал, как это уладить. Вон, видишь Булька с Гурглом, какие они прикольные? Так вот, я собираюсь подарить Заблудшим таких же забавных мурлоков!$b$bВот, бери эту клетку, тащи ее к деревне Остротопь и выпусти этих малявок среди северо-восточного скопления хижин. Нет, Булька с Гурглом я с тобой не отпущу. Но эти разноцветные мелкие мурлоки ничем не хуже! Поставь клетку на большой плоский камень, который там увидишь, и открой дверцу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите клетку с мурлоками в деревню Остротопь и оставьте ее на плоском камне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ай, молодца! Надеюсь, им там теперь не скучно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Знахарь Тор\'гаш усмехается.>$B$BПонравился ли подарок маленьким мурлокам?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к знахарю Тор\'гешу в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9818,'Из глубин','Что-то происходит там, под землей. Почва дрожит, будто ее истязают. $B$B*Унтраг бьет себя кулаком в грудь.*$B$BЭтот звук повторяется сто тысяч раз. Без конца. Земля содрогается. Она взывает к нам.$B$BГордауг говорил со мной. Он сказал, что нечто вытесняет стихии наружу. Нечто из глубин.$B$BИди и поговори с Гордаугом. Нет, не говори ничего, просто слушай Гордауга. Слушай Гордауга и услышь...','Поговорите с Гордаугом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Из глубин',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то происходит там, под землей. Почва дрожит, будто ее истязают. $B$B*Унтраг бьет себя кулаком в грудь.*$B$BЭтот звук повторяется сто тысяч раз. Без конца. Земля содрогается. Она взывает к нам.$B$BГордауг говорил со мной. Он сказал, что нечто вытесняет стихии наружу. Нечто из глубин.$B$BИди и поговори с Гордаугом. Нет, не говори ничего, просто слушай Гордауга. Слушай Гордауга и услышь...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гордаугом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9819,'Истерзанные духи земли','Уничтожьте 10 истерзанных духов земли по просьбе Гордага из Трона Стихий Награнда.','<Гордауг одобрительно кивает.>$B$BХорошо. Духи уснули.','Вернитесь к Гордаугу к Трону Стихий, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истерзанные духи земли',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 истерзанных духов земли по просьбе Гордага из Трона Стихий Награнда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гордауг одобрительно кивает.>$B$BХорошо. Духи уснули.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гордаугу к Трону Стихий, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9820,'РАЗЫСКИВАЕТСЯ: Главарь Грог\'ак','Разыскивается живым или мертвым Главарь Грог\'ак из Анго\'роша, ответственный за операцию по сбору грибов.$b$bЭтот мерзавец и его прихвостни повинны в вырубке грибов к северу от поселения! Если их не остановить, эта банда прорубит тропу к самым стенами Забра\'джина!$b$bТот, кто доставит голову Грог\'ака темному охотнику Дэнжаю, получит щедрое вознаграждение!','Принесите голову главаря Грог\'ака темному охотнику Дэнжаю в Забра\'джин.','Вернитесь к темному охотнику Дэнжаю в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','РАЗЫСКИВАЕТСЯ: Главарь Грог\'ак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разыскивается живым или мертвым Главарь Грог\'ак из Анго\'роша, ответственный за операцию по сбору грибов.$b$bЭтот мерзавец и его прихвостни повинны в вырубке грибов к северу от поселения! Если их не остановить, эта банда прорубит тропу к самым стенами Забра\'джина!$b$bТот, кто доставит голову Грог\'ака темному охотнику Дэнжаю, получит щедрое вознаграждение!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите голову главаря Грог\'ака темному охотнику Дэнжаю в Забра\'джин.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному охотнику Дэнжаю в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9821,'Попробовать зло на зуб','<Гордауг берет кусок породы и пробует его на зуб.>$B$BГордауг пробует. Гордауг знает, откуда эта земля.$B$B<Гордауг поднимает тяжеленную ногу и с силой впечатывает ступню в землю.>$B$BСмотри. Это Награнд.$B$B<Гордауг указывает на отпечаток ступни. Он оказывается подробной геологической картой Награнда, где обозначено местоположение элементалей, которых Гордауг хочет уничтожить.>$B$BРАЗДАВИ ИХ! Принеси Гордаугу осколки, я их съем.$B$BВозьми карту.','Принесите Гордаугу к Трону Стихий 10 средоточий разъяренных сокрушителей.','Гордауг есть камни. Гордауг найти захватчика. Неси камни!','Вернитесь к Гордаугу к Трону Стихий, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Попробовать зло на зуб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Гордауг берет кусок породы и пробует его на зуб.>$B$BГордауг пробует. Гордауг знает, откуда эта земля.$B$B<Гордауг поднимает тяжеленную ногу и с силой впечатывает ступню в землю.>$B$BСмотри. Это Награнд.$B$B<Гордауг указывает на отпечаток ступни. Он оказывается подробной геологической картой Награнда, где обозначено местоположение элементалей, которых Гордауг хочет уничтожить.>$B$BРАЗДАВИ ИХ! Принеси Гордаугу осколки, я их съем.$B$BВозьми карту.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Гордаугу к Трону Стихий 10 средоточий разъяренных сокрушителей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Гордауг есть камни. Гордауг найти захватчика. Неси камни!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гордаугу к Трону Стихий, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9822,'Угроза нападения','Сдается мне, что огры не случайно затеяли вырубать грибы именно в этом направлении. Я подозреваю, что они готовят нападение на Забра\'джин!$b$b$n, мне нужно знать это наверняка! У огров есть еще один форпост на северо-западе, Земли Анго\'рош. И если они готовятся напасть, там непременно должны быть признаки этого. Ступай в Земли Анго\'рош, $n, и постарайся выяснить это. Если обнаружишь что-нибудь подозрительное, возвращайся ко мне.','Принесите планы нападения клана Анго\'рош темному охотнику Дэнжаю в Забра\'джин.','Ну что, удалось ли тебе обнаружить доказательства намерений огров?','Вернитесь к темному охотнику Дэнжаю в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза нападения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сдается мне, что огры не случайно затеяли вырубать грибы именно в этом направлении. Я подозреваю, что они готовят нападение на Забра\'джин!$b$b$n, мне нужно знать это наверняка! У огров есть еще один форпост на северо-западе, Земли Анго\'рош. И если они готовятся напасть, там непременно должны быть признаки этого. Ступай в Земли Анго\'рош, $n, и постарайся выяснить это. Если обнаружишь что-нибудь подозрительное, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите планы нападения клана Анго\'рош темному охотнику Дэнжаю в Забра\'джин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось ли тебе обнаружить доказательства намерений огров?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному охотнику Дэнжаю в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9823,'Мы и они','Чтобы покончить с угрозой Анго\'роша, нужно убить их вождя, властителя Кровавого Кулака. Однако мы не просто убьем его – судьба властителя и его приверженцев станет примером для всего клана!$b$bСтупай в крепость Анго\'рош и покончи с нашими врагами. Крепость находится на маленьком острове к северо-западу от Забра\'джина. Пройди лагерь Анго\'рош, и увидишь мост из поваленного гриба.$b$bНе давай им пощады, $n! Они нас щадить не будут.','Убейте властителя Кровавого Кулака, 10 извергов из клана Анго\'рош и 10 пожирателей душ из клана Анго\'рош и вернитесь к темному охотнику Дэнжаю в Забра\'джин.','Угроза анго\'рошов нависает над нами. Ты $Gустранил:устранила; их лидера?','Вернитесь к темному охотнику Дэнжаю в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы и они',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы покончить с угрозой Анго\'роша, нужно убить их вождя, властителя Кровавого Кулака. Однако мы не просто убьем его – судьба властителя и его приверженцев станет примером для всего клана!$b$bСтупай в крепость Анго\'рош и покончи с нашими врагами. Крепость находится на маленьком острове к северо-западу от Забра\'джина. Пройди лагерь Анго\'рош, и увидишь мост из поваленного гриба.$b$bНе давай им пощады, $n! Они нас щадить не будут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте властителя Кровавого Кулака, 10 извергов из клана Анго\'рош и 10 пожирателей душ из клана Анго\'рош и вернитесь к темному охотнику Дэнжаю в Забра\'джин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Угроза анго\'рошов нависает над нами. Ты $Gустранил:устранила; их лидера?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному охотнику Дэнжаю в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9824,'Колебания тайной магии','Я пытаюсь получить отпечаток энергии Каражана... Разумеется, для своего собственного исследования. К сожалению, здесь мне не удается ничего уловить. Если бы я мог добраться до источника подземных вод, мой кристалл принимал бы сигналы без помех.$B$BЯ слышал, что в подземельях под нами есть источник и целое подземное озеро. Правда, это место кишит призраками, а я уже не в том возрасте, чтобы с ними сражаться. Что скажете насчет того, чтобы помочь старику – спуститься в подземелье и задействовать гадальный кристалл $gсамому:самой;?','Активируйте кристалл ясновидения Аметистового Ока рядом с подземными источниками вод в Хозяйском погребе и вернитесь к верховному магу Альтуру, находящемуся у входа в Каражан.','Результаты ни о чем хорошем не говорят, $N. Каражан должен излучать потоки тайной магии... Вместо этого мы наблюдаем полную тишину. Никаких сигналов. Вообще ничего. За исключением очень слабого демонического эха. $B$BЭто плохие новости, $N.','Как там замеры энергии, $N? Вам удалось их провести?','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Колебания тайной магии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пытаюсь получить отпечаток энергии Каражана... Разумеется, для своего собственного исследования. К сожалению, здесь мне не удается ничего уловить. Если бы я мог добраться до источника подземных вод, мой кристалл принимал бы сигналы без помех.$B$BЯ слышал, что в подземельях под нами есть источник и целое подземное озеро. Правда, это место кишит призраками, а я уже не в том возрасте, чтобы с ними сражаться. Что скажете насчет того, чтобы помочь старику – спуститься в подземелье и задействовать гадальный кристалл $gсамому:самой;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Активируйте кристалл ясновидения Аметистового Ока рядом с подземными источниками вод в Хозяйском погребе и вернитесь к верховному магу Альтуру, находящемуся у входа в Каражан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Результаты ни о чем хорошем не говорят, $N. Каражан должен излучать потоки тайной магии... Вместо этого мы наблюдаем полную тишину. Никаких сигналов. Вообще ничего. За исключением очень слабого демонического эха. $B$BЭто плохие новости, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там замеры энергии, $N? Вам удалось их провести?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9825,'Неустанный труд','Как вы могли заметить, снаружи стен Каражана блуждают призраки. Почему и как они там возникли, неизвестно, и это очень меня беспокоит!$B$BДоставьте мне одну из призрачных сущностей, чтобы я мог изучить ее. В Каражане много секретов, $n, и я полон решимости раскрыть их все.','Принесите 10 призрачных сущностей верховному магу Альтуру, находящемуся у входа в Каражан.','Поразительно. Теперь я смогу изучить эти сущности, $N. Спасибо вам за помощь.','Удалось собрать сущности призраков, |3-6($C)?','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неустанный труд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как вы могли заметить, снаружи стен Каражана блуждают призраки. Почему и как они там возникли, неизвестно, и это очень меня беспокоит!$B$BДоставьте мне одну из призрачных сущностей, чтобы я мог изучить ее. В Каражане много секретов, $n, и я полон решимости раскрыть их все.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 призрачных сущностей верховному магу Альтуру, находящемуся у входа в Каражан.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поразительно. Теперь я смогу изучить эти сущности, $N. Спасибо вам за помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось собрать сущности призраков, |3-6($C)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9826,'Вести из Даларана','Все это не сулит нам ничего хорошего, $n. Я никогда не понимал необходимости в особой секретности, поэтому расскажу тебе немного о нас, то есть об Аметистовом Оке $B$BМы все – агенты Кирин-Тора, Совета магов Даларана. Нам было поручено следить за Каражаном и Медивом – на случай, если что-нибудь пойдет наперекосяк.$B$BЧто и случилось... причем очень скоро, после того, как Медив исчез.$B$BВ этом письме изложены все подробности моего личного расследования. Доставь его верховному магу Седрику, он тоже из Аметистового Ока. Его можно отыскать на склонах даларанского кратера.','Доставьте письмо Альтуруса верховному магу Седрику на окраину кратера Даларана.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вести из Даларана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все это не сулит нам ничего хорошего, $n. Я никогда не понимал необходимости в особой секретности, поэтому расскажу тебе немного о нас, то есть об Аметистовом Оке $B$BМы все – агенты Кирин-Тора, Совета магов Даларана. Нам было поручено следить за Каражаном и Медивом – на случай, если что-нибудь пойдет наперекосяк.$B$BЧто и случилось... причем очень скоро, после того, как Медив исчез.$B$BВ этом письме изложены все подробности моего личного расследования. Доставь его верховному магу Седрику, он тоже из Аметистового Ока. Его можно отыскать на склонах даларанского кратера.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте письмо Альтуруса верховному магу Седрику на окраину кратера Даларана.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9827,'Высохшая базидия','Пристально разглядев базидию, вы обнаруживаете выемки, в которых раньше, по-видимому, что-то находилось. Ком грибной ткани представляет собой загадку. Ясно, что она поражена каким-то заболеванием, но вы не понимаете, что это такое и что с ним не так.$b$bБыть может, кто-то из тех, кто лучше вашего разбирается в обитателях Зангартопи, сумеет объяснить вам, в чем дело...','Отнесите высохшую базидию Руаму в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Высохшая базидия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пристально разглядев базидию, вы обнаруживаете выемки, в которых раньше, по-видимому, что-то находилось. Ком грибной ткани представляет собой загадку. Ясно, что она поражена каким-то заболеванием, но вы не понимаете, что это такое и что с ним не так.$b$bБыть может, кто-то из тех, кто лучше вашего разбирается в обитателях Зангартопи, сумеет объяснить вам, в чем дело...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите высохшую базидию Руаму в Телредор, что в Зангартопи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9828,'Высохшая базидия','Пристально разглядев базидию, вы обнаруживаете выемки, в которых раньше, по-видимому, что-то находилось. Ком грибной ткани представляет собой загадку. Ясно, что она поражена каким-то заболеванием, но вы не понимаете, что это такое и что с ним не так.$b$bБыть может, кто-то из тех, кто лучше вашего разбирается в обитателях Зангартопи, сумеет объяснить вам, в чем дело...','Отнесите высохшую базидию Реавижу на заставу Болотной Крысы, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Высохшая базидия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пристально разглядев базидию, вы обнаруживаете выемки, в которых раньше, по-видимому, что-то находилось. Ком грибной ткани представляет собой загадку. Ясно, что она поражена каким-то заболеванием, но вы не понимаете, что это такое и что с ним не так.$b$bБыть может, кто-то из тех, кто лучше вашего разбирается в обитателях Зангартопи, сумеет объяснить вам, в чем дело...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите высохшую базидию Реавижу на заставу Болотной Крысы, что в Зангартопи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9829,'Кадгар','Альтурус прислал тревожные вести. Когда Каражан закрылся от всего мира, нам это не понравилось. Там работали наши агенты, а связь с ними прервалась. А теперь этот... демонический выброс. Нужно расследовать его!$B$BЕдинственные, кто мог открыть Каражан – Кадгар и Медив, – признаны умершими.$B$BМы надеемся, что Медив исчез навсегда, но вот его ученик, Кадгар, еще жив и находится в Шаттрате. Найдите его и отдайте ему письмо Альтура.','Доставьте письмо Альтуруса Кадгару в Шаттрат – город в лесу Тероккар.','Аметистовое Око? Подумать только!$B$BПокажите-ка мне это письмо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кадгар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Альтурус прислал тревожные вести. Когда Каражан закрылся от всего мира, нам это не понравилось. Там работали наши агенты, а связь с ними прервалась. А теперь этот... демонический выброс. Нужно расследовать его!$B$BЕдинственные, кто мог открыть Каражан – Кадгар и Медив, – признаны умершими.$B$BМы надеемся, что Медив исчез навсегда, но вот его ученик, Кадгар, еще жив и находится в Шаттрате. Найдите его и отдайте ему письмо Альтура.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте письмо Альтуруса Кадгару в Шаттрат – город в лесу Тероккар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Аметистовое Око? Подумать только!$B$BПокажите-ка мне это письмо.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9830,'Яд паразита','Когда я говорю с дренеями, у меня всегда создается впечатление, что они не ощущают связи с родной природой. Вот моих собратьев, Сломленных, многие жалеют, говорят, что они как будто что-то потеряли.$b$bНу, может быть, мы и впрямь лишились стремления к Свету, но зато пережитое сделало нас ближе к земле.$b$bМой народ способен найти применение многому, что дренеи считают за мусор. Вот взять, к примеру, яд болотных паразитов, что водятся к юго-западу отсюда. Его ведь можно использовать и на охоте, и в медицине...','Принесите 6 порций яда болотного паразита Пулуу в Прибежище Оребор.','Я надеюсь показать анахорету Ахуурну и другим жителям Телредора, как можно использовать яд болотного паразита. Но для этого мне потребуется удвоить свои запасы.','Вернитесь к Пулуу в прибежище Оребор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яд паразита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я говорю с дренеями, у меня всегда создается впечатление, что они не ощущают связи с родной природой. Вот моих собратьев, Сломленных, многие жалеют, говорят, что они как будто что-то потеряли.$b$bНу, может быть, мы и впрямь лишились стремления к Свету, но зато пережитое сделало нас ближе к земле.$b$bМой народ способен найти применение многому, что дренеи считают за мусор. Вот взять, к примеру, яд болотных паразитов, что водятся к юго-западу отсюда. Его ведь можно использовать и на охоте, и в медицине...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 порций яда болотного паразита Пулуу в Прибежище Оребор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я надеюсь показать анахорету Ахуурну и другим жителям Телредора, как можно использовать яд болотного паразита. Но для этого мне потребуется удвоить свои запасы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пулуу в прибежище Оребор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9831,'Вход в Каражан','Меня очень взволновали эти известия, $n, однако пробраться в Каражан будет не так-то просто.$B$BВидишь ли, когда стало ясно, что мне придется тут задержаться, я разломил ключ на три фрагмента.$B$BКаждый фрагмент я поместил в зачарованный контейнер и поместил их в места, которые на тот момент были самыми безопасными.$B$BОднако теперь нам нужно вернуть их. Первый фрагмент находится в части Аукиндона, которой завладел Совет Теней. Принеси мне этот фрагмент.','Пройдите в Темный лабиринт в Аукиндоне, найдите там волшебный контейнер и возьмите из него первый фрагмент ключа, после чего вернитесь к Кадгару.','Вернитесь к Кадгару в Нижний Город, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вход в Каражан',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня очень взволновали эти известия, $n, однако пробраться в Каражан будет не так-то просто.$B$BВидишь ли, когда стало ясно, что мне придется тут задержаться, я разломил ключ на три фрагмента.$B$BКаждый фрагмент я поместил в зачарованный контейнер и поместил их в места, которые на тот момент были самыми безопасными.$B$BОднако теперь нам нужно вернуть их. Первый фрагмент находится в части Аукиндона, которой завладел Совет Теней. Принеси мне этот фрагмент.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пройдите в Темный лабиринт в Аукиндоне, найдите там волшебный контейнер и возьмите из него первый фрагмент ключа, после чего вернитесь к Кадгару.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кадгару в Нижний Город, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9832,'Второй и третий фрагменты','Второй фрагмент я спрятал в Змеином озере, еще задолго до того, как оно получило это название. После того как озеро захватили наги и установили там гигантский сток, контейнер, скорее всего, оказался в глубине Резервуара Кривого Клыка.$B$BДостать третий фрагмент будет сложнее всего, так как его я оставил в Крепости Бурь – она тогда еще принадлежала наару. Теперь крепость захватил Кель\'тас, а зал, где я оставил фрагмент, превратили в тюрьму.$B$BПринеси мне недостающие фрагменты, $n. От успеха твоего похода зависит очень многое.','Добудьте второй фрагмент ключа из волшебного контейнера в Резервуаре Кривого Клыка, а третий фрагмент ключа – из волшебного контейнера в Крепости Бурь, после чего вернитесь к Кадгару в Шаттрат.','Ты $Gдобыл:добыла; фрагменты. Что ж, это впечатляет, $N. Несомненно, вам можно доверить ключ от Каражана. $B$BОднако есть еще одна небольшая проблема.','Как продвигаются поиски фрагментов ключа?','Вернитесь к Кадгару в Нижний Город, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Второй и третий фрагменты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Второй фрагмент я спрятал в Змеином озере, еще задолго до того, как оно получило это название. После того как озеро захватили наги и установили там гигантский сток, контейнер, скорее всего, оказался в глубине Резервуара Кривого Клыка.$B$BДостать третий фрагмент будет сложнее всего, так как его я оставил в Крепости Бурь – она тогда еще принадлежала наару. Теперь крепость захватил Кель\'тас, а зал, где я оставил фрагмент, превратили в тюрьму.$B$BПринеси мне недостающие фрагменты, $n. От успеха твоего похода зависит очень многое.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте второй фрагмент ключа из волшебного контейнера в Резервуаре Кривого Клыка, а третий фрагмент ключа – из волшебного контейнера в Крепости Бурь, после чего вернитесь к Кадгару в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gдобыл:добыла; фрагменты. Что ж, это впечатляет, $N. Несомненно, вам можно доверить ключ от Каражана. $B$BОднако есть еще одна небольшая проблема.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигаются поиски фрагментов ключа?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кадгару в Нижний Город, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9833,'Линии связи','Одна из причин, по которой Икути привел нас в Зангартопь – это необходимость поддерживать связь между дренеями и Телааром в Награнде, родиной Куренай. А для этого дороги должны быть безопасны.$b$bПо пути сюда на нас то и дело нападали болотные терзатели. Мы-то отражали их нападения, но для одинокого путника они чрезвычайно опасны! Если бы тебе удалось уменьшить их численность, нашим гонцам было бы куда спокойнее.','Убейте 12 болотных терзателей по просьбе Пулуу из Прибежища Оребор.','Отличные новости! Конечно, до полной безопасности здешним дорогам пока далеко, однако же наши посланцы умны и находчивы...','Ну как, удалось ли тебе сделать дороги безопаснее?','Вернитесь к Пулуу в прибежище Оребор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Линии связи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна из причин, по которой Икути привел нас в Зангартопь – это необходимость поддерживать связь между дренеями и Телааром в Награнде, родиной Куренай. А для этого дороги должны быть безопасны.$b$bПо пути сюда на нас то и дело нападали болотные терзатели. Мы-то отражали их нападения, но для одинокого путника они чрезвычайно опасны! Если бы тебе удалось уменьшить их численность, нашим гонцам было бы куда спокойнее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 болотных терзателей по просьбе Пулуу из Прибежища Оребор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные новости! Конечно, до полной безопасности здешним дорогам пока далеко, однако же наши посланцы умны и находчивы...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, удалось ли тебе сделать дороги безопаснее?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пулуу в прибежище Оребор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9834,'Природная броня','Дренеев в их блестящих доспехах Макту видит за милю, даже сквозь болотный туман!$b$bМакту хочет над ними смеяться, но потом вспоминает, что они были добры к куренай, и Макту хочет показать им, как куренай делают доспехи.$b$bИз темных чешуйчатых шкур болотных твердозубов получаются самые лучшие доспехи, какие когда-нибудь носил Макту. Если $n принесет Макту несколько шкур болотных твердозубов, плавающих в глубинах Змеиного озера, Макту охотно поделится своими доспехами!','Принесите 8 шкур болотных твердозубов Макту в Прибежище Оребор.','Вернитесь к Макту в прибежище Оребор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Природная броня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дренеев в их блестящих доспехах Макту видит за милю, даже сквозь болотный туман!$b$bМакту хочет над ними смеяться, но потом вспоминает, что они были добры к куренай, и Макту хочет показать им, как куренай делают доспехи.$b$bИз темных чешуйчатых шкур болотных твердозубов получаются самые лучшие доспехи, какие когда-нибудь носил Макту. Если $n принесет Макту несколько шкур болотных твердозубов, плавающих в глубинах Змеиного озера, Макту охотно поделится своими доспехами!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 шкур болотных твердозубов Макту в Прибежище Оребор.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Макту в прибежище Оребор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9835,'Вторжение Анго\'рош','Небольшой отряд Сломленных, который ты видишь, – посланцы из большого поселения в Награнде. Куренай, как мы себя называем – это Сломленные, которые стремятся воссоединиться со своими собратьями-дренеями.$b$bМы прибыли сюда, чтобы укрепить связи Куренай с дренеями Телредора.$b$bЕсли огры клана Анго\'рош возьмут верх, этот храм долго не продержится. Они вырубили все крупные грибы на Болотных вырубках, и подбираются все ближе к нашему убежищу. Если ты хочешь считаться нашим другом, помоги нам бороться с этими врагами!','Убейте 10 огров из клана Анго\'рош и 5 шаманов клана Анго\'рош и вернитесь к Икути в Прибежище Оребор.','Теперь огры на время притихнут, но я уверен: так быстро они не сдадутся! С тех пор, как я перестал быть дренеем, я многое забыл, но как упорны огры – это не забывается!','Как идет борьба с Анго\'рош?','Вернитесь к Икути в прибежище Оребор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение Анго\'рош',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Небольшой отряд Сломленных, который ты видишь, – посланцы из большого поселения в Награнде. Куренай, как мы себя называем – это Сломленные, которые стремятся воссоединиться со своими собратьями-дренеями.$b$bМы прибыли сюда, чтобы укрепить связи Куренай с дренеями Телредора.$b$bЕсли огры клана Анго\'рош возьмут верх, этот храм долго не продержится. Они вырубили все крупные грибы на Болотных вырубках, и подбираются все ближе к нашему убежищу. Если ты хочешь считаться нашим другом, помоги нам бороться с этими врагами!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 огров из клана Анго\'рош и 5 шаманов клана Анго\'рош и вернитесь к Икути в Прибежище Оребор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь огры на время притихнут, но я уверен: так быстро они не сдадутся! С тех пор, как я перестал быть дренеем, я многое забыл, но как упорны огры – это не забывается!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идет борьба с Анго\'рош?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Икути в прибежище Оребор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (9836,'Разрешение учителя','Я сумел воссоздать ключ, которым пользовался, будучи учеником. С виду он вполне рабочий – в общем-то, ключ как ключ. Но когда я пытаюсь открыть Каражан, ключ не действует. С тем же успехом я мог бы взять и обычную железку.$B$BСобственно, это и есть никчемная железка. Ключ не будет работать без согласия Медива. Да, я знаю, что Медив мертв. Но это не значит, что с ним невозможно связаться.$B$BВ Азероте есть место, которое называют Пещерами Времени. Их охраняют бронзовые драконы. Проберись в пещеры, вернись в прошлое и уговори Медива дать разрешение на пользование ключом.','Отправляйтесь в Пещеры Времени и уговорите Медива дать разрешение на использование Восстановленного ключа.','Этот ключ. Я узнаю его. Ключ Кадгара... Разумеется, я еще не давал ему никакого ключа.','Кто ты и что тебе нужно?','Разрешение учителя') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрешение учителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сумел воссоздать ключ, которым пользовался, будучи учеником. С виду он вполне рабочий – в общем-то, ключ как ключ. Но когда я пытаюсь открыть Каражан, ключ не действует. С тем же успехом я мог бы взять и обычную железку.$B$BСобственно, это и есть никчемная железка. Ключ не будет работать без согласия Медива. Да, я знаю, что Медив мертв. Но это не значит, что с ним невозможно связаться.$B$BВ Азероте есть место, которое называют Пещерами Времени. Их охраняют бронзовые драконы. Проберись в пещеры, вернись в прошлое и уговори Медива дать разрешение на пользование ключом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Пещеры Времени и уговорите Медива дать разрешение на использование Восстановленного ключа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот ключ. Я узнаю его. Ключ Кадгара... Разумеется, я еще не давал ему никакого ключа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кто ты и что тебе нужно?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Разрешение учителя',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9837,'Возвращение к Кадгару','Похоже, я помню кое-что о грядущих событиях, связанных с тобой и этим ключом.$B$B*Медив смотрит на вас так, будто увидел привидение.*$B$BТебя ждут нелегкие времена, $n. Будем надеяться, у тебя хватит сил вынести все испытания.$B$BЧто касается ключа, то я должен отдать его Кадгару, когда он придет ко мне. О таком ученике можно только мечтать.$B$BЯ так понимаю, тебе понадобится твой собственный ключ.$B$B*Медив роется в карманах своего одеяния и вручает вам ключ.* $B$BВот он. Желаю тебе удачи, |3-6($c).','Вернитесь в Шаттрат к Кадгару и покажите ему хозяйский ключ.','Его собственный ключ? Невероятно!$B$BЯ не чувствую никаких возмущений в нашей временной линии, так что, думаю, это действительно произошло. Дороги назад нет, $N. Этот ключ твой и только твой.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Кадгару',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, я помню кое-что о грядущих событиях, связанных с тобой и этим ключом.$B$B*Медив смотрит на вас так, будто увидел привидение.*$B$BТебя ждут нелегкие времена, $n. Будем надеяться, у тебя хватит сил вынести все испытания.$B$BЧто касается ключа, то я должен отдать его Кадгару, когда он придет ко мне. О таком ученике можно только мечтать.$B$BЯ так понимаю, тебе понадобится твой собственный ключ.$B$B*Медив роется в карманах своего одеяния и вручает вам ключ.* $B$BВот он. Желаю тебе удачи, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Шаттрат к Кадгару и покажите ему хозяйский ключ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Его собственный ключ? Невероятно!$B$BЯ не чувствую никаких возмущений в нашей временной линии, так что, думаю, это действительно произошло. Дороги назад нет, $N. Этот ключ твой и только твой.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9838,'Аметистовое Око','На тебя была возложена великая ответственность, $n. Если знаки, которые удалось разглядеть Аметистовому Оку, истинны, то ты $gдолжен:должна; помочь им.$B$BНесмотря на все мои расхождения с Седриком, я признаю, что люди вроде Альтуруса ведут очень важную работу. Но будь $gосторожен:осторожна; – они могут тебя использовать. Всегда помни о том, что ключ принадлежит тебе, а не им. Но если в Каражане и правда таится опасность, то именно они лучше всего научат, как ее одолеть. Возвращайся к Альтурусу и помогай ему, чем сможешь.','Поговорите с верховным магом Альтуром, который находится снаружи Каражана.','Я послал тебя, чтобы доставить письмо, а ты $Gвернулся:вернулась; с ключом от этого места? Похоже, в тебе скрыто нечто большее, чем кажется на первый взгляд, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аметистовое Око',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На тебя была возложена великая ответственность, $n. Если знаки, которые удалось разглядеть Аметистовому Оку, истинны, то ты $gдолжен:должна; помочь им.$B$BНесмотря на все мои расхождения с Седриком, я признаю, что люди вроде Альтуруса ведут очень важную работу. Но будь $gосторожен:осторожна; – они могут тебя использовать. Всегда помни о том, что ключ принадлежит тебе, а не им. Но если в Каражане и правда таится опасность, то именно они лучше всего научат, как ее одолеть. Возвращайся к Альтурусу и помогай ему, чем сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным магом Альтуром, который находится снаружи Каражана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я послал тебя, чтобы доставить письмо, а ты $Gвернулся:вернулась; с ключом от этого места? Похоже, в тебе скрыто нечто большее, чем кажется на первый взгляд, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9839,'Властитель Кровавый Кулак','Основа любого огрского племени – это его вождь. Лишившись вождя, клан Анго\'рош распадется, и огры примутся драться между собой, выясняя, кто теперь будет главным.$b$bХотя здесь немало разных огров, их основные силы сосредоточены в крепости Анго\'рош на северо-западе. Крепость представляет собой пещеру на небольшом островке, на который с болота можно попасть по стволу поваленного гриба.$b$bСтупай туда и одолей властителя Кровавого Кулака! Это обеспечит нам давно заслуженную передышку.','Убейте властителя Кровавого Кулака и 10 извергов из клана Анго\'рош по просьбе Икути. Выполнив задачу, вернитесь в Прибежище Оребор.','Наконец-то! Мы благодарим тебя за помощь – благодаря тебе наше положение упрочилось. Я пошлю весть о твоих деяниях в куренайский город Телаар в Награнде. У наших народов еще не раз будет случай сражаться плечом к плечу!','Ну что, дело сделано? Удалось ли тебе покончить с властителем Кровавым Кулаком?','Вернитесь к Икути в прибежище Оребор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Властитель Кровавый Кулак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Основа любого огрского племени – это его вождь. Лишившись вождя, клан Анго\'рош распадется, и огры примутся драться между собой, выясняя, кто теперь будет главным.$b$bХотя здесь немало разных огров, их основные силы сосредоточены в крепости Анго\'рош на северо-западе. Крепость представляет собой пещеру на небольшом островке, на который с болота можно попасть по стволу поваленного гриба.$b$bСтупай туда и одолей властителя Кровавого Кулака! Это обеспечит нам давно заслуженную передышку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте властителя Кровавого Кулака и 10 извергов из клана Анго\'рош по просьбе Икути. Выполнив задачу, вернитесь в Прибежище Оребор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то! Мы благодарим тебя за помощь – благодаря тебе наше положение упрочилось. Я пошлю весть о твоих деяниях в куренайский город Телаар в Награнде. У наших народов еще не раз будет случай сражаться плечом к плечу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, дело сделано? Удалось ли тебе покончить с властителем Кровавым Кулаком?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Икути в прибежище Оребор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9840,'Оценка ситуации','Теперь, когда мы – вернее, ты -$gнашел:нашла; путь обратно в Башню Медива, нам надо в первую очередь попытаться узнать, что же происходит внутри.$B$BОдна из наших агентов, которой удалось проникнуть в Каражан, вела закодированную запись событий. К несчастью, сразу после того, как Каражан закрылся, мы узнали о ее смерти. На нас работал Корен, кузнец из Каражана. Хотя он не член Аметистового Ока, думаю, он поможет нам отыскать записи Кинны. Ты найдешь его внутри.','Найдите Корена в Каражане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оценка ситуации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы – вернее, ты -$gнашел:нашла; путь обратно в Башню Медива, нам надо в первую очередь попытаться узнать, что же происходит внутри.$B$BОдна из наших агентов, которой удалось проникнуть в Каражан, вела закодированную запись событий. К несчастью, сразу после того, как Каражан закрылся, мы узнали о ее смерти. На нас работал Корен, кузнец из Каражана. Хотя он не член Аметистового Ока, думаю, он поможет нам отыскать записи Кинны. Ты найдешь его внутри.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Корена в Каражане.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9841,'Поделом гнусным тварям!','Что за адское жужжание! Просто работать невозможно! Слышишь?$b$bЯ от него буквально с ума схожу. И, главное, я ведь знаю, кто это жужжит! Это все проклятые болотные паразиты! И шум всегда доносится с юго-западной стороны от деревни.$b$bЭти твари такие здоровенные, что их не прихлопнешь, не раздавишь, и отмахнуться от них тоже не получится. С ними надо воевать всерьез! В общем, меня не волнует, как ты это сделаешь, $n, главное – заставь их заткнуться!','Убейте 8 болотных паразитов и вернитесь к Гамбаринко в Забра\'джин.','Так я и думал. Разница сразу заметна. Наконец-то я снова смогу взяться за работу! Спасибо тебе большое! Если тебе снова понадобятся мои товары, не забудь про Гамбаринко!','Звук как будто ушел вдаль. Это желаемое за действительное или ты действительно что-то $Gсделал:сделала; для решения проблемы?','Вернитесь к Гамбаринко в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поделом гнусным тварям!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что за адское жужжание! Просто работать невозможно! Слышишь?$b$bЯ от него буквально с ума схожу. И, главное, я ведь знаю, кто это жужжит! Это все проклятые болотные паразиты! И шум всегда доносится с юго-западной стороны от деревни.$b$bЭти твари такие здоровенные, что их не прихлопнешь, не раздавишь, и отмахнуться от них тоже не получится. С ними надо воевать всерьез! В общем, меня не волнует, как ты это сделаешь, $n, главное – заставь их заткнуться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 болотных паразитов и вернитесь к Гамбаринко в Забра\'джин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так я и думал. Разница сразу заметна. Наконец-то я снова смогу взяться за работу! Спасибо тебе большое! Если тебе снова понадобятся мои товары, не забудь про Гамбаринко!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Звук как будто ушел вдаль. Это желаемое за действительное или ты действительно что-то $Gсделал:сделала; для решения проблемы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гамбаринко в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9842,'Острейшие резцы','Болотная сырость не пошла на пользу моим железным инструментам. Я уже зарекся их точить. Работа по дереву не идет совершенно.$b$bОднако обнаружилось, что зубы болотных терзателей, обитающих к югу и к западу от города, куда острее любых стальных резцов, какими я когда-либо владел! Кроме того, они не тупятся и не боятся ржавчины. Правда, вделывать их в рукоятку не так-то просто, но я, кажется, решил и эту проблему. Так что приноси мне их зубы, я буду очень признателен.','Принесите 10 зубов болотного терзателя Гамбаринко в Забра\'джине.','О, ну, этого мне хватит надолго! Мне кажется, кое-кто догадывается, в чем дело. У меня уже несколько раз спрашивали, не продам ли я свои резцы. Может быть, продавать их на сторону окажется даже выгоднее, чем мастерить что-то самому...','Ну что, удалось тебе раздобыть резцы для меня?','Вернитесь к Гамбаринко в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Острейшие резцы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Болотная сырость не пошла на пользу моим железным инструментам. Я уже зарекся их точить. Работа по дереву не идет совершенно.$b$bОднако обнаружилось, что зубы болотных терзателей, обитающих к югу и к западу от города, куда острее любых стальных резцов, какими я когда-либо владел! Кроме того, они не тупятся и не боятся ржавчины. Правда, вделывать их в рукоятку не так-то просто, но я, кажется, решил и эту проблему. Так что приноси мне их зубы, я буду очень признателен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 зубов болотного терзателя Гамбаринко в Забра\'джине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, ну, этого мне хватит надолго! Мне кажется, кое-кто догадывается, в чем дело. У меня уже несколько раз спрашивали, не продам ли я свои резцы. Может быть, продавать их на сторону окажется даже выгоднее, чем мастерить что-то самому...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе раздобыть резцы для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гамбаринко в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9843,'Записи Кинны','Кого ты там $gискал:искала;, повтори-ка еще разок? Кинну?$B$BКогда-то я встречал кого-то с похожим именем. Она останавливалась наверху, в Гостевых комнатах. Я не должен был болтать об этом, да?$B$BКак ты $gговорил:говорила;, ты из Аметистового Ока? Никогда о таком не слыхал.$B$BА теперь я бы вернулся к своей работе, если не возражаешь.$B$B<Похоже, Корен уже забыл о вас.>','Найдите Гостевые комнаты в Каражане, а в них – записи Кинны, и доставьте их верховному магу Альтуру.','Тебе удалось найти записи. Я уверен, они содержат информацию, которая даст ответ на наши вопросы, $N.','Записи Кинны... Тебе удалось их найти?','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Записи Кинны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кого ты там $gискал:искала;, повтори-ка еще разок? Кинну?$B$BКогда-то я встречал кого-то с похожим именем. Она останавливалась наверху, в Гостевых комнатах. Я не должен был болтать об этом, да?$B$BКак ты $gговорил:говорила;, ты из Аметистового Ока? Никогда о таком не слыхал.$B$BА теперь я бы вернулся к своей работе, если не возражаешь.$B$B<Похоже, Корен уже забыл о вас.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Гостевые комнаты в Каражане, а в них – записи Кинны, и доставьте их верховному магу Альтуру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе удалось найти записи. Я уверен, они содержат информацию, которая даст ответ на наши вопросы, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Записи Кинны... Тебе удалось их найти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9844,'Присутствие демонов','Последние несколько записей Кинны подтверждают наши предположения, что в Каражан пробрались демоны.$B$BЕй удалось засечь прибытие агента Пылающего Легиона. По ее словам, он обосновался на самом верху башни.$B$BНа этом ее записи обрываются.$B$BКаражан – это очень важное для нас место, |3-6($c). Это портал в бездну, маяк, сияющий для других миров. Я не хочу даже думать о том, что может случиться, если он попадет не в те руки. Необходимо остановить демонов. А ключ от Каражана, $n, есть только у вас.','Верховный маг Альтур просит вас уничтожить демона на вершине башни Каражана.','Вам удалось это сделать! Наши данные снова пришли в норму!$B$BНеобходимо сообщить новости Седрику. Он будет просто поражен.','Боюсь спросить, $N. Что стало внутри Каражана?','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Присутствие демонов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Последние несколько записей Кинны подтверждают наши предположения, что в Каражан пробрались демоны.$B$BЕй удалось засечь прибытие агента Пылающего Легиона. По ее словам, он обосновался на самом верху башни.$B$BНа этом ее записи обрываются.$B$BКаражан – это очень важное для нас место, |3-6($c). Это портал в бездну, маяк, сияющий для других миров. Я не хочу даже думать о том, что может случиться, если он попадет не в те руки. Необходимо остановить демонов. А ключ от Каражана, $n, есть только у вас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный маг Альтур просит вас уничтожить демона на вершине башни Каражана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вам удалось это сделать! Наши данные снова пришли в норму!$B$BНеобходимо сообщить новости Седрику. Он будет просто поражен.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Боюсь спросить, $N. Что стало внутри Каражана?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Альтуру на Перевал Мертвого Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9845,'Не распугивайте рыбу!','Убейте 10 болотных твердозубов и вернитесь к Зурджайе в Забра\'джин.','Мне не терпится поскорее вернуться к рыбалке! Наконец-то я принесу в город полное ведро рыбы! А то Гамбаринко меня уже засмеял.','Безопасно ли мне снова ловить рыбу?','Вернитесь к Зурджайе в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не распугивайте рыбу!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 болотных твердозубов и вернитесь к Зурджайе в Забра\'джин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне не терпится поскорее вернуться к рыбалке! Наконец-то я принесу в город полное ведро рыбы! А то Гамбаринко меня уже засмеял.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Безопасно ли мне снова ловить рыбу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зурджайе в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9846,'Духи Дикотопи','Говорят, что самое могущественное племя Заблудших на болотах, племя Дикотопи, владеет могучей магией. Может быть, это и вранье, но я не могу пренебрегать ничем, что поможет мне управлять духами этого мира.$b$b$n, отыщи мистиков, охотников и друидов Дикотопи, и захвати их тотемы. Все, что мне надо знать, станет понятно по их резьбе.','Принесите 10 тотемов-хранителей Дикотопи ясновидящей Джаниди в Забра\'джин.','И где тотемы?','Вернитесь к ясновидящей Джаниди в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи Дикотопи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, что самое могущественное племя Заблудших на болотах, племя Дикотопи, владеет могучей магией. Может быть, это и вранье, но я не могу пренебрегать ничем, что поможет мне управлять духами этого мира.$b$b$n, отыщи мистиков, охотников и друидов Дикотопи, и захвати их тотемы. Все, что мне надо знать, станет понятно по их резьбе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 тотемов-хранителей Дикотопи ясновидящей Джаниди в Забра\'джин.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','И где тотемы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ясновидящей Джаниди в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9847,'Дух-союзник?','Нужно выяснить, велико ли могущество змеиного духа Дикотопи, и можно ли его подчинить нашей воле. Только представь, что можно было бы совершить, повелевая могуществом духа Запределья!$b$bВозьми с собой этот тотем и проберись к подножию лестницы, ведущей в руины Боха\'му. Установи тотем на землю, остальное он сделает сам. Дух не сможет явиться, пока кто-нибудь не воспользовался тотемом.','Отнесите тотем Дикотопи к подножию лестницы руин Боха\'му и установите его на землю. Расскажите о том, что вы видели, ясновидящей Джаниди в Забра\'джине.','Удалось ли тебе призвать духа Дикотопи?','Вернитесь к ясновидящей Джаниди в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух-союзник?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно выяснить, велико ли могущество змеиного духа Дикотопи, и можно ли его подчинить нашей воле. Только представь, что можно было бы совершить, повелевая могуществом духа Запределья!$b$bВозьми с собой этот тотем и проберись к подножию лестницы, ведущей в руины Боха\'му. Установи тотем на землю, остальное он сделает сам. Дух не сможет явиться, пока кто-нибудь не воспользовался тотемом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите тотем Дикотопи к подножию лестницы руин Боха\'му и установите его на землю. Расскажите о том, что вы видели, ясновидящей Джаниди в Забра\'джине.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе призвать духа Дикотопи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ясновидящей Джаниди в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9848,'Тайны Остротопи','Насекомые, насекомые! Болота кишат насекомыми, и мои товарищи, похоже, помешались на них.$b$bНу, а с меня довольно! Меня интересует куда более важный вопрос. К западу отсюда есть деревня Заблудших, которые называют себя кланом Остротопь.$b$bВсе они – высокопрофессиональные убийцы. Я обнаружил, что они изготовляют и применяют особенно действенный сорт яда. И мне до смерти хочется узнать побольше об этом яде. Однако для этого нужно раздобыть рецепт и фиал с образчиком...','Принесите справочник по ядам Остротопи и фиал яда Остротопи Тимоти Даниэльсу в Прибежище Оребор.','Надеюсь, твои поиски в деревне Остротопь не были безрезультатными? Мне не терпится разрешить эту загадку!','Вернитесь к Тимоти Даниэльсу в прибежище Оребор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны Остротопи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насекомые, насекомые! Болота кишат насекомыми, и мои товарищи, похоже, помешались на них.$b$bНу, а с меня довольно! Меня интересует куда более важный вопрос. К западу отсюда есть деревня Заблудших, которые называют себя кланом Остротопь.$b$bВсе они – высокопрофессиональные убийцы. Я обнаружил, что они изготовляют и применяют особенно действенный сорт яда. И мне до смерти хочется узнать побольше об этом яде. Однако для этого нужно раздобыть рецепт и фиал с образчиком...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите справочник по ядам Остротопи и фиал яда Остротопи Тимоти Даниэльсу в Прибежище Оребор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, твои поиски в деревне Остротопь не были безрезультатными? Мне не терпится разрешить эту загадку!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тимоти Даниэльсу в прибежище Оребор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9849,'Сорвать личину','Убейте 30 прислужников Гурока.','ГУРОК! Гурок предал стихии!','Вернитесь к Гордаугу к Трону Стихий, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сорвать личину',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 30 прислужников Гурока.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','ГУРОК! Гурок предал стихии!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гордаугу к Трону Стихий, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9850,'Охота на копытней','Я уже убедился, что ты $gспособен:способна; разыскать и завалить обыкновенного копытня, но их самцы гораздо опаснее!$B$BУбей двенадцать самцов копытня, и тогда уже поговорим о твоем охотничьем мастерстве.$B$BЭти звери обитают в центральных районах Награнда, к западу и югу отсюда.','Убейте 12 самцов копытня и вернитесь к Хемингу Эрнестуэю в его охотничий лагерь в Награнде.','Вернитесь к Хемингу Эрнестуэю в охотничий лагерь Эрнестуэя, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на копытней',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже убедился, что ты $gспособен:способна; разыскать и завалить обыкновенного копытня, но их самцы гораздо опаснее!$B$BУбей двенадцать самцов копытня, и тогда уже поговорим о твоем охотничьем мастерстве.$B$BЭти звери обитают в центральных районах Награнда, к западу и югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 самцов копытня и вернитесь к Хемингу Эрнестуэю в его охотничий лагерь в Награнде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хемингу Эрнестуэю в охотничий лагерь Эрнестуэя, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9854,'Охота на ветрухов','Ты тоже живешь лишь охотой, |3-6($c)? Тоже ищешь покоя, что нисходит на душу охотника, когда он выслеживает добычу? Знаешь ли ты, что такое трепет перед последними ударами сердца сраженного зверя? Я помогу тебе узнать все тонкости нашего ремесла!$B$BНагранд – край, исполненный жизни. Нетронутый островок жизни посреди этого опустошенного мира. Принеси мне убитых тобою ветрухов, и тогда мы продолжим разговор.$B$BВетрухов найти легко – они бродят повсюду вокруг нашего лагеря.','Убейте 12 ветрухов и вернитесь к Фитцу в охотничий лагерь Эрнестуэя в Награнде.','Каждый прожитый день – это великий дар. И этим даром надо воспользоваться в полной мере. И, может быть, уже завтра наши шаги по земле станут еще стремительнее и легче. А наши руки протянутся немного дальше в извечном стремлении схватить ускользающую мечту.','Вернитесь к страннику Шадо "Фитцу" в охотничий лагерь Эрнестуэя, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на ветрухов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты тоже живешь лишь охотой, |3-6($c)? Тоже ищешь покоя, что нисходит на душу охотника, когда он выслеживает добычу? Знаешь ли ты, что такое трепет перед последними ударами сердца сраженного зверя? Я помогу тебе узнать все тонкости нашего ремесла!$B$BНагранд – край, исполненный жизни. Нетронутый островок жизни посреди этого опустошенного мира. Принеси мне убитых тобою ветрухов, и тогда мы продолжим разговор.$B$BВетрухов найти легко – они бродят повсюду вокруг нашего лагеря.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 ветрухов и вернитесь к Фитцу в охотничий лагерь Эрнестуэя в Награнде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Каждый прожитый день – это великий дар. И этим даром надо воспользоваться в полной мере. И, может быть, уже завтра наши шаги по земле станут еще стремительнее и легче. А наши руки протянутся немного дальше в извечном стремлении схватить ускользающую мечту.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к страннику Шадо "Фитцу" в охотничий лагерь Эрнестуэя, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9855,'Охота на ветрухов','Только $gдостойнейший:достойнейшая; из достойнейших сможет приблизиться к великой добыче! Пока ты еще не $gготов:готова;, я буду тебя направлять.$B$BСуществует еще один вид ветрухов – свирепее и опаснее прочих. Разыщи прожорливых ветрухов и испытай свою храбрость. Ты найдешь их в самом сердце Награнда, к западу и юго-западу отсюда.','Добудьте 12 прожорливых ветрухов и вернитесь к Фитцу в лагерь Эрнестуэя в Награнде.','Вернитесь к страннику Шадо "Фитцу" в охотничий лагерь Эрнестуэя, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на ветрухов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только $gдостойнейший:достойнейшая; из достойнейших сможет приблизиться к великой добыче! Пока ты еще не $gготов:готова;, я буду тебя направлять.$B$BСуществует еще один вид ветрухов – свирепее и опаснее прочих. Разыщи прожорливых ветрухов и испытай свою храбрость. Ты найдешь их в самом сердце Награнда, к западу и юго-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 12 прожорливых ветрухов и вернитесь к Фитцу в лагерь Эрнестуэя в Награнде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к страннику Шадо "Фитцу" в охотничий лагерь Эрнестуэя, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9857,'Охота на талбуков','Сегодня я вряд ли пойду на охоту. Не желаешь меня заменить?$B$BЯ сказал Хемингу, что постараюсь добыть побольше талбуков, которые здесь встречаются на каждом шагу. Лучше всего охотиться на самцов. Кстати, я видел, как они собирались в ближайшей роще.$B$BНу что? Поохотишься за меня?','Убейте 12 талбуков-самцов и возвращайтесь к Гарольду Лейну в лагерь Эрнестуэя в Награнде.','Вернитесь к Гарольду Лейну в охотничий лагерь Эрнестуэя, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на талбуков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня я вряд ли пойду на охоту. Не желаешь меня заменить?$B$BЯ сказал Хемингу, что постараюсь добыть побольше талбуков, которые здесь встречаются на каждом шагу. Лучше всего охотиться на самцов. Кстати, я видел, как они собирались в ближайшей роще.$B$BНу что? Поохотишься за меня?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 талбуков-самцов и возвращайтесь к Гарольду Лейну в лагерь Эрнестуэя в Награнде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарольду Лейну в охотничий лагерь Эрнестуэя, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9858,'Охота на талбуков','Убейте 12 талбуков-шипоедов и возвращайтесь к Гарольду Лейну в лагерь Эрнестуэя в Награнде.','Вернитесь к Гарольду Лейну в охотничий лагерь Эрнестуэя, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на талбуков',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 талбуков-шипоедов и возвращайтесь к Гарольду Лейну в лагерь Эрнестуэя в Награнде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарольду Лейну в охотничий лагерь Эрнестуэя, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9860,'Новое направление','Немедленно возвращайтесь к Седрику, $n. Ваша помощь Аметистовому Оку будет вознаграждена. $B$BМожете думать о нас и о нашей организации что хотите, |3-6($c), но об обретении благосклонности верховных магов Даларана вы не пожалеете.','Поговорите с верховным магом Седриком на окраине кратера Даларана.','Альтурус рассказал мне, что случилось, $N, но это еще не все. Если Каражан так и останется запечатанным от пришельцев извне, захватить нас врасплох станет для Легиона делом времени. $B$BЕсли только вы не примете на себя ответственности, наложенной на вас самой судьбой. $B$B<Седрик протягивает вам раскрытую ладонь, на которой лежит знак с символом Аметистового Ока.>$B$BЧто скажете, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое направление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Немедленно возвращайтесь к Седрику, $n. Ваша помощь Аметистовому Оку будет вознаграждена. $B$BМожете думать о нас и о нашей организации что хотите, |3-6($c), но об обретении благосклонности верховных магов Даларана вы не пожалеете.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным магом Седриком на окраине кратера Даларана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Альтурус рассказал мне, что случилось, $N, но это еще не все. Если Каражан так и останется запечатанным от пришельцев извне, захватить нас врасплох станет для Легиона делом времени. $B$BЕсли только вы не примете на себя ответственности, наложенной на вас самой судьбой. $B$B<Седрик протягивает вам раскрытую ладонь, на которой лежит знак с символом Аметистового Ока.>$B$BЧто скажете, $N?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9861,'Вой-Ветер','Эта аморфная масса воздушной стихии говорит с вами на языке, которого вы не понимаете. Скорее всего, это язык стихий – калимаг. Может быть, у Трона Стихий найдется кто-то, кто подскажет вам, что это за странная находка.','Разыщите у Трона Стихий кого-нибудь, кто знает язык калимаг, и покажите ему или ей Вой-Ветра.','Дай это мне! Быстро!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вой-Ветер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта аморфная масса воздушной стихии говорит с вами на языке, которого вы не понимаете. Скорее всего, это язык стихий – калимаг. Может быть, у Трона Стихий найдется кто-то, кто подскажет вам, что это за странная находка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите у Трона Стихий кого-нибудь, кто знает язык калимаг, и покажите ему или ей Вой-Ветра.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дай это мне! Быстро!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9862,'Разлагатели Темной Крови','Убейте 5 разлагателей из племени Темной Крови по просьбе повелителя стихий Морха, находящегося у Трона Стихий.','Дух воздуха утверждает, что разлагатели Темной Крови ловят его собратьев и отправляют сеять хаос среди других элементалей в Солнечном Источнике...','Вернитесь к повелителю стихий Морху к Трону Стихий, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разлагатели Темной Крови',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 разлагателей из племени Темной Крови по просьбе повелителя стихий Морха, находящегося у Трона Стихий.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дух воздуха утверждает, что разлагатели Темной Крови ловят его собратьев и отправляют сеять хаос среди других элементалей в Солнечном Источнике...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелителю стихий Морху к Трону Стихий, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9863,'Вражеские святыни','Принесите 10 идолов Темной Крови предсказателю Куркашу в Гарадар.','Нам не хватит сил для набега, поэтому мы попросили тебя о помощи.','Вернитесь к предсказателю Куркашу в Гарадар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вражеские святыни',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 идолов Темной Крови предсказателю Куркашу в Гарадар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам не хватит сил для набега, поэтому мы попросили тебя о помощи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предсказателю Куркашу в Гарадар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9864,'Пропавший отряд','После набега Темной Крови группа наших юнцов решила им отомстить. Мы пытались их остановить, но ярость оказалась сильнее. Прошла уже неделя, а от наших детей нет ни единой весточки.$B$BПрошу тебя, |3-6($r), отыщи их. Они еще очень юные – куда им тягаться со свирепыми дикарями?!$B$BОни направились по западной дороге. Поезжай по ней и попытайся обнаружить следы наших юных отпрысков.$B$BИ еще одно, $n, если ты дорожишь своей жизнью, обходи Халаа стороной. Там идет война.','Отыщите пропавший гарадарский отряд.','Я знаю предания своего народа. В них говорится, что когда-то мы были великими воинами…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший отряд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После набега Темной Крови группа наших юнцов решила им отомстить. Мы пытались их остановить, но ярость оказалась сильнее. Прошла уже неделя, а от наших детей нет ни единой весточки.$B$BПрошу тебя, |3-6($r), отыщи их. Они еще очень юные – куда им тягаться со свирепыми дикарями?!$B$BОни направились по западной дороге. Поезжай по ней и попытайся обнаружить следы наших юных отпрысков.$B$BИ еще одно, $n, если ты дорожишь своей жизнью, обходи Халаа стороной. Там идет война.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите пропавший гарадарский отряд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю предания своего народа. В них говорится, что когда-то мы были великими воинами…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9865,'Да, были воины в наше время...','Я не знаю, кто ты, $gстранник:прекрасная госпожа;, но молю о помощи. Мне горько говорить об этом, но я – последний из орков, оставшихся здесь.$B$BЯ ощутил что-то такое, чего не чувствовал прежде... Я... я жажду мести. Кровь за кровь. Ты когда-нибудь $gчувствовал:ощущала; что-либо подобное? Меня охватывает непреодолимое желание схватить топор и сокрушить им моих врагов. Я готов сражаться до тех пор, пока рука не опустится в изнеможении.$B$BЗастава Солнечного Источника лежит к югу отсюда. Там ты найдешь наших врагов... Убей их... Убей их всех...','Убейте 20 падальщиков из племени Темной Крови и 10 налетчиков из племени Темной Крови.','За каждого убитого ими члена моей семьи должно умереть по десять человек!','Вернитесь к Саурфангу Младшему к Похоронной процессии маг\'харов, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Да, были воины в наше время...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не знаю, кто ты, $gстранник:прекрасная госпожа;, но молю о помощи. Мне горько говорить об этом, но я – последний из орков, оставшихся здесь.$B$BЯ ощутил что-то такое, чего не чувствовал прежде... Я... я жажду мести. Кровь за кровь. Ты когда-нибудь $gчувствовал:ощущала; что-либо подобное? Меня охватывает непреодолимое желание схватить топор и сокрушить им моих врагов. Я готов сражаться до тех пор, пока рука не опустится в изнеможении.$B$BЗастава Солнечного Источника лежит к югу отсюда. Там ты найдешь наших врагов... Убей их... Убей их всех...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 падальщиков из племени Темной Крови и 10 налетчиков из племени Темной Крови.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','За каждого убитого ими члена моей семьи должно умереть по десять человек!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Саурфангу Младшему к Похоронной процессии маг\'харов, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9866,'Он будет странствовать по земле...','Окажи мне последнюю услугу, $n. Я не хочу возвращаться в Гарадар. Я убежден, что судьба уготовила мне иной путь, на котором меня ждут великие свершения.$B$BПожалуйста, найди предсказателя Корхука и скажи ему, что я не вернусь. Я не могу повернуть назад. Я должен странствовать по земле... Он поймет.','Доставьте известие предсказателю Корхуку в Гарадар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Он будет странствовать по земле...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Окажи мне последнюю услугу, $n. Я не хочу возвращаться в Гарадар. Я убежден, что судьба уготовила мне иной путь, на котором меня ждут великие свершения.$B$BПожалуйста, найди предсказателя Корхука и скажи ему, что я не вернусь. Я не могу повернуть назад. Я должен странствовать по земле... Он поймет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте известие предсказателю Корхуку в Гарадар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9867,'Главари Темной Крови','Принесите предсказателю Маргадешу в Гарадар голову Ортора Темной Крови.','Значит, я смотрю в лицо нашего врага? Я прикажу насадить эту голову на кол и выставить над городскими воротами Гарадара. Если они соберутся напасть на нас снова, пусть видят, к чему приводят столь необдуманные шаги…','Вернитесь к предсказателю Маргадешу в Гарадар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главари Темной Крови',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите предсказателю Маргадешу в Гарадар голову Ортора Темной Крови.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, я смотрю в лицо нашего врага? Я прикажу насадить эту голову на кол и выставить над городскими воротами Гарадара. Если они соберутся напасть на нас снова, пусть видят, к чему приводят столь необдуманные шаги…',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предсказателю Маргадешу в Гарадар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9869,'Трон Стихий','Приветствую тебя, |3-6($r). Я – Локи, повелитель стихий из Служителей Земли. Я пришел в Телаар, чтобы рассказать куренай о состоянии стихий.$B$BМогу я тебя попросить об одной небольшой услуге? Ты не $gмог:могла; бы сходить к Трону Стихий – это в северных холмах Награнда, за озером Небесной Песни, – и сообщить повелительнице стихий Шарвак, что я благополучно добрался до Телаара? Без вознаграждения ты не останешься. Я уверен, что Шарвак предложит тебе компенсацию за беспокойство.','Поговорите с повелительницей стихий Шарвак у Трона Стихий.','Большое спасибо за новости. Не желаешь ли ты оказать содействие Служителям Земли? Стихии находятся в движении. Сейчас мы не откажемся от любой помощи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трон Стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($r). Я – Локи, повелитель стихий из Служителей Земли. Я пришел в Телаар, чтобы рассказать куренай о состоянии стихий.$B$BМогу я тебя попросить об одной небольшой услуге? Ты не $gмог:могла; бы сходить к Трону Стихий – это в северных холмах Награнда, за озером Небесной Песни, – и сообщить повелительнице стихий Шарвак, что я благополучно добрался до Телаара? Без вознаграждения ты не останешься. Я уверен, что Шарвак предложит тебе компенсацию за беспокойство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с повелительницей стихий Шарвак у Трона Стихий.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большое спасибо за новости. Не желаешь ли ты оказать содействие Служителям Земли? Стихии находятся в движении. Сейчас мы не откажемся от любой помощи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9870,'Трон Стихий','Приветствую тебя, |3-6($r). Я – повелитель стихий Ялхан из Служителей Земли. Я пришел в Гарадар, чтобы проинформировать маг\'харов о состоянии стихий.$B$BМогу я попросить тебя об одной небольшой услуге? Ты не $gмог:могла; бы сходить к Трону Стихий – это в северных холмах Награнда, за озером Небесной Песни – и сообщить повелительнице стихий Шарвак, что я благополучно добрался до Гарадара? Без вознаграждения ты не останешься. Я уверен, что Шарвак предложит тебе компенсацию за беспокойство.','Поговорите с повелительницей стихий Шарвак у Трона Стихий.','Большое спасибо за новости. Не желаешь ли ты оказать содействие Служителям Земли? Стихии находятся в движении. Сейчас мы не откажемся от любой помощи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трон Стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($r). Я – повелитель стихий Ялхан из Служителей Земли. Я пришел в Гарадар, чтобы проинформировать маг\'харов о состоянии стихий.$B$BМогу я попросить тебя об одной небольшой услуге? Ты не $gмог:могла; бы сходить к Трону Стихий – это в северных холмах Награнда, за озером Небесной Песни – и сообщить повелительнице стихий Шарвак, что я благополучно добрался до Гарадара? Без вознаграждения ты не останешься. Я уверен, что Шарвак предложит тебе компенсацию за беспокойство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с повелительницей стихий Шарвак у Трона Стихий.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Большое спасибо за новости. Не желаешь ли ты оказать содействие Служителям Земли? Стихии находятся в движении. Сейчас мы не откажемся от любой помощи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9871,'Захватчики из племени Темной Крови','На пергаменте нарисована грубая и схематичная карта Награнда. Телаар обозначен большим красным "X". Похоже, Падшие Темной Крови готовят вторжение в город. Передайте планы вторжения Темной Крови Арехрону в Телааре.','Передайте планы вторжения Темной Крови Арехрону в Телаар, что в Награнде.','Что это?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захватчики из племени Темной Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На пергаменте нарисована грубая и схематичная карта Награнда. Телаар обозначен большим красным "X". Похоже, Падшие Темной Крови готовят вторжение в город. Передайте планы вторжения Темной Крови Арехрону в Телааре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте планы вторжения Темной Крови Арехрону в Телаар, что в Награнде.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9872,'Захватчики из племени Темной Крови','На пергаменте нарисована грубая и схематичная карта Награнда. Гарадар обозначен большим красным "X". Похоже, Падшие Темной Крови готовят вторжение в город. Передайте планы вторжения Темной Крови Гаррошу в Гарадаре.','Передайте планы вторжения Темной Крови Гаррошу.','Что это?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захватчики из племени Темной Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На пергаменте нарисована грубая и схематичная карта Награнда. Гарадар обозначен большим красным "X". Похоже, Падшие Темной Крови готовят вторжение в город. Передайте планы вторжения Темной Крови Гаррошу в Гарадаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте планы вторжения Темной Крови Гаррошу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9873,'Ортор, мой старый друг...','Эти планы вторжения составлял мой давний знакомый. Ортор Темная Кровь, некогда знатный Сломленный, посвященный в науку стихий, теперь сделался лизоблюдом Мусел\'ека, этого царя пиявок.$B$BИз плана следует, что они захватили Заставу Солнечного Источника, деревушку орков к северо-западу отсюда.$B$BОтправляйся на Заставу Солнечного Источника и избавь мир от Ортора. Так будет лучше для всех...','Арехрон из Телаара в Награнде поручил вам убить Ортора Темную Кровь.','Вернитесь к Арехрону в Телаар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ортор, мой старый друг...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти планы вторжения составлял мой давний знакомый. Ортор Темная Кровь, некогда знатный Сломленный, посвященный в науку стихий, теперь сделался лизоблюдом Мусел\'ека, этого царя пиявок.$B$BИз плана следует, что они захватили Заставу Солнечного Источника, деревушку орков к северо-западу отсюда.$B$BОтправляйся на Заставу Солнечного Источника и избавь мир от Ортора. Так будет лучше для всех...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Арехрон из Телаара в Награнде поручил вам убить Ортора Темную Кровь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Арехрону в Телаар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9874,'Остановить заразу','Мне только что стало известно о катастрофе поистине устрашающего масштаба, $n. Эти мерзавцы Темной Крови захватили орочью Заставу Солнечного Источника... это к северо-западу отсюда... перебили всех тамошних жителей, а тела принялись сбрасывать в озеро Солнечного Источника. Если все эти тела начнут разлагаться в озере, наш главный источник пресной воды в этой области будет отравлен.$B$BЯ понимаю, что это работа не из приятных, но ее надо сделать. Возьми этот зачарованный факел, иди на заставу и сожги все трупы орков...','Сожгите 10 трупов селян Солнечного Источника с помощью факела жидкого огня. Когда исполните поручение, верните факел Отонбу Ведуну.','Вернитесь к Отонбу Ведуну в Телаар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановить заразу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне только что стало известно о катастрофе поистине устрашающего масштаба, $n. Эти мерзавцы Темной Крови захватили орочью Заставу Солнечного Источника... это к северо-западу отсюда... перебили всех тамошних жителей, а тела принялись сбрасывать в озеро Солнечного Источника. Если все эти тела начнут разлагаться в озере, наш главный источник пресной воды в этой области будет отравлен.$B$BЯ понимаю, что это работа не из приятных, но ее надо сделать. Возьми этот зачарованный факел, иди на заставу и сожги все трупы орков...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите 10 трупов селян Солнечного Источника с помощью факела жидкого огня. Когда исполните поручение, верните факел Отонбу Ведуну.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Отонбу Ведуну в Телаар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (9875,'Неизвестный науке вид','А вот это растение Лауранна, очевидно, упустила из виду. Ты $gуверен:уверена;, что $gобнаружил:обнаружила; вид, еще не описанный Лауранной. Стоит показать это растение Лауранне и посмотреть, что она скажет...','Принесите неизвестный науке вид Лауранне Тар\'вел в Кенарийский оплот в Зангартопи.','Ты хочешь мне что-то показать?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неизвестный науке вид',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А вот это растение Лауранна, очевидно, упустила из виду. Ты $gуверен:уверена;, что $gобнаружил:обнаружила; вид, еще не описанный Лауранной. Стоит показать это растение Лауранне и посмотреть, что она скажет...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите неизвестный науке вид Лауранне Тар\'вел в Кенарийский оплот в Зангартопи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь мне что-то показать?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9876,'Провалившийся рейд','Я отправила небольшой отряд наших друидов, чтобы исследовать обнаруженную тобой трубу в Змеином озере. Я рассчитывала на их скорое возвращение. Нужно ли говорить, что они не вернулись до сих пор?$b$bТы – $gодин:одна; из самых способных наших союзников. Пожалуйста, отыщи их и выясни, что с ними стало.','По просьбе Исиэли Песни Ветра отыщите следы друидов из Кенарийской экспедиции у входа в Резервуар Кривого Клыка, что в Зангартопи.','Слава Кенарию, что ты здесь! Я не могла выбраться наружу из-за ран...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Провалившийся рейд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я отправила небольшой отряд наших друидов, чтобы исследовать обнаруженную тобой трубу в Змеином озере. Я рассчитывала на их скорое возвращение. Нужно ли говорить, что они не вернулись до сих пор?$b$bТы – $gодин:одна; из самых способных наших союзников. Пожалуйста, отыщи их и выясни, что с ними стало.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Исиэли Песни Ветра отыщите следы друидов из Кенарийской экспедиции у входа в Резервуар Кривого Клыка, что в Зангартопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава Кенарию, что ты здесь! Я не могла выбраться наружу из-за ран...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9877,'Приводящее в сознание зелье','В битве с Плетью не избежать потерь. Каждый день многие погибают, но еще большему числу выпадает куда более страшный удел.$B$BПлеть захватывает пленников. И лучше им умереть, чем испытать то, что ждет их в Смертхольме. Их допрашивают и пытают, используя ужасный, ломающий волю яд. $B$BАптекарь Рензитен из Транквиллиона разработал противоядие – ступай к нему и принеси его приводящее в сознание зелье.','Поговорите с аптекарем Рензитеном в Транквиллионе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приводящее в сознание зелье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В битве с Плетью не избежать потерь. Каждый день многие погибают, но еще большему числу выпадает куда более страшный удел.$B$BПлеть захватывает пленников. И лучше им умереть, чем испытать то, что ждет их в Смертхольме. Их допрашивают и пытают, используя ужасный, ломающий волю яд. $B$BАптекарь Рензитен из Транквиллиона разработал противоядие – ступай к нему и принеси его приводящее в сознание зелье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с аптекарем Рензитеном в Транквиллионе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9878,'Устранение проблемы','Убейте 10 падальщиков и 5 налетчиков из племени Темной Крови.','Тёмная кровь - гнусное племя Сломленных, $N. Они могут выглядеть как Куренай, но, несомненно, они дикие звери-убийцы.','Вернитесь к Полилуклуку Мудрейшему в Телаар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Устранение проблемы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 падальщиков и 5 налетчиков из племени Темной Крови.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тёмная кровь - гнусное племя Сломленных, $N. Они могут выглядеть как Куренай, но, несомненно, они дикие звери-убийцы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Полилуклуку Мудрейшему в Телаар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9880,'Hellfire Penninsula: -pn – A – ToWoW – Hellfire Turnin Cap','Вернитесь к прапорщику Трейси Праудвелл на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Hellfire Penninsula: -pn – A – ToWoW – Hellfire Turnin Cap',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к прапорщику Трейси Праудвелл на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9881,'Hellfire Penninsula: -pn – H – ToWoW – Hellfire Turnin Cap','Вернитесь к Черноглазке Зов Войны на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Hellfire Penninsula: -pn – H – ToWoW – Hellfire Turnin Cap',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Черноглазке Зов Войны на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9882,'Украсть у вора','Принц Харамад пока не разрешает нам работать внутри Ошу\'гуна, поскольку это может разозлить некоторых влиятельных наару. Так что время идет, а работа стоит.$B$BНо я, кажется, нашел лазейку.$B$BПонимаешь, мы не единственные, кого тянет к этому гигантскому алмазу. Вор по имени Гава\'кси возглавил банду головорезов, которые проникли в Ошу\'гун и принялись откалывать от камня крупные куски.$B$BТвоя задача, |3-6($r), найти их и забрать то, что принадлежит нам по праву.','Раздобудьте 10 осколков кристалла Ошу\'гуна и отдайте их Гезхе в Небесном лагере в Награнде.','Прекрасный цвет. И качество в основном отличное.$B$BЯ сообщу нашим людям, как ты нам помогаешь.','Вернитесь к Гезхе в Небесный лагерь, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Украсть у вора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принц Харамад пока не разрешает нам работать внутри Ошу\'гуна, поскольку это может разозлить некоторых влиятельных наару. Так что время идет, а работа стоит.$B$BНо я, кажется, нашел лазейку.$B$BПонимаешь, мы не единственные, кого тянет к этому гигантскому алмазу. Вор по имени Гава\'кси возглавил банду головорезов, которые проникли в Ошу\'гун и принялись откалывать от камня крупные куски.$B$BТвоя задача, |3-6($r), найти их и забрать то, что принадлежит нам по праву.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте 10 осколков кристалла Ошу\'гуна и отдайте их Гезхе в Небесном лагере в Награнде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасный цвет. И качество в основном отличное.$B$BЯ сообщу нашим людям, как ты нам помогаешь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гезхе в Небесный лагерь, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9883,'Снова осколки кристалла','Принеси нам ещё осколков, $N. Все, которые сумеешь собрать. Нельзя позволять этим ворам расхищать нашу собственность.$B$BПусть даже она ещё не совсем наша. Хотя, разумеется, уже почти наша. Во всяком случае, на бумаге.','У тебя есть ещё осколки кристаллов? Убедись, что ты не берешь ничего, что прикреплено к горе. Мы бы не хотели создавать проблемы с наару.','Вернитесь к Гезхе в Награнд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снова осколки кристалла',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Принеси нам ещё осколков, $N. Все, которые сумеешь собрать. Нельзя позволять этим ворам расхищать нашу собственность.$B$BПусть даже она ещё не совсем наша. Хотя, разумеется, уже почти наша. Во всяком случае, на бумаге.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть ещё осколки кристаллов? Убедись, что ты не берешь ничего, что прикреплено к горе. Мы бы не хотели создавать проблемы с наару.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гезхе в Награнд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (9884,'Выгодное сотрудничество','Консорциум хорошо известен тем, что хорошо заботится о своих друзьях. В начале каждого месяца я буду иметь несколько драгоценных камней, готовых для тебя в качестве оплаты за ваши услуги.$B$BКачество драгоценных камней, которые ты получишь, будет зависеть от того, насколько ты $Gбыл:была; $Gлоялен:лояльна; к нам. Будем надеяться, что ты поступишь разумно и останешься с нами.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Выгодное сотрудничество',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Консорциум хорошо известен тем, что хорошо заботится о своих друзьях. В начале каждого месяца я буду иметь несколько драгоценных камней, готовых для тебя в качестве оплаты за ваши услуги.$B$BКачество драгоценных камней, которые ты получишь, будет зависеть от того, насколько ты $Gбыл:была; $Gлоялен:лояльна; к нам. Будем надеяться, что ты поступишь разумно и останешься с нами.',`offerrewardtext_loc8`);
