INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (9888,'Слабосильный владыка','Джорин Мертвый Глаз просит вас найти Килрата и поговорить с ним.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слабосильный владыка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Джорин Мертвый Глаз просит вас найти Килрата и поговорить с ним.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9889,'Толстяка не убивать','Я уже несколько дней слежу за этими тварями. Толстяк говорит, что чего-то ждет. Чего конкретно – неизвестно.$B$BУ меня есть план, но тут придется применить насилие. Нужно убить нескольких его подчиненных, а потом избить его до полусмерти. После этого, я уверен, он выложит все, что нам надо узнать.','Убейте 10 захватчиков из клана Тяжелого Кулака, затем избейте и допросите Анкора Безжалостного.','Не убивай меня, я все расскажу!','Я подчиняюсь! Я подчиняюсь!','Анкор сдается','Вернитесь к Анкору Безжалостному на руины Кровавой Глазницы, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Толстяка не убивать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже несколько дней слежу за этими тварями. Толстяк говорит, что чего-то ждет. Чего конкретно – неизвестно.$B$BУ меня есть план, но тут придется применить насилие. Нужно убить нескольких его подчиненных, а потом избить его до полусмерти. После этого, я уверен, он выложит все, что нам надо узнать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 захватчиков из клана Тяжелого Кулака, затем избейте и допросите Анкора Безжалостного.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не убивай меня, я все расскажу!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я подчиняюсь! Я подчиняюсь!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Анкор сдается',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анкору Безжалостному на руины Кровавой Глазницы, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9890,'Успех!','Долгие годы клан Тяжелого Кулака правил над всеми ограми в Запределье. При Кроле огры объединились и жили дружно. Они довольствовались теми землями, которые им были даны. Однако в последние месяцы многие огры погибли от рук их же сородичей из Боевого Молота. Этот клан захватил почти все наши земли в Награнде и перебил многих наших собратьев.$B$BМы должны были взять этот город. У нас просто не было выбора. Нас истребляют...$B$BКрол пропал без вести, клан Тяжелого Кулака в полной растерянности. Лантрезор Клинок правит в его отсуствие.','Передайте все сведения, которые вы выбили из Анкора, Килрату в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Успех!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Долгие годы клан Тяжелого Кулака правил над всеми ограми в Запределье. При Кроле огры объединились и жили дружно. Они довольствовались теми землями, которые им были даны. Однако в последние месяцы многие огры погибли от рук их же сородичей из Боевого Молота. Этот клан захватил почти все наши земли в Награнде и перебил многих наших собратьев.$B$BМы должны были взять этот город. У нас просто не было выбора. Нас истребляют...$B$BКрол пропал без вести, клан Тяжелого Кулака в полной растерянности. Лантрезор Клинок правит в его отсуствие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте все сведения, которые вы выбили из Анкора, Килрату в лес Тероккар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9891,'Потому что Килрат – трус','Расскажи обо всем Джорину в Гарадаре. Уверяю тебя, его не обрадует известие об уничтожении деревни и почти поголовном истреблении ее жителей из-за претензий огров на территорию.$B$BДа хранят тебя предки... Если я тебе снова понадоблюсь, я буду прятаться здесь в кустах. В общем, ты знаешь, где меня найти.','Передайте информацию, которую вы выбили из Анкора, Джорину Мертвому Глазу в Гарадаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потому что Килрат – трус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Расскажи обо всем Джорину в Гарадаре. Уверяю тебя, его не обрадует известие об уничтожении деревни и почти поголовном истреблении ее жителей из-за претензий огров на территорию.$B$BДа хранят тебя предки... Если я тебе снова понадоблюсь, я буду прятаться здесь в кустах. В общем, ты знаешь, где меня найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте информацию, которую вы выбили из Анкора, Джорину Мертвому Глазу в Гарадаре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9892,'Поиски обсидиановых боевых ожерелий','Вернитесь к Гезхе в Награнд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски обсидиановых боевых ожерелий',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гезхе в Награнд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9893,'Обсидиановое боевое ожерелье','Гора Ошу\'гун еще не готова к раскопкам, и мы теряем немалую прибыль, $n.$B$BК счастью, я обнаружил дополнительный источник дохода. Огры Награнда носят боевые ожерелья из обсидиана – минерала, который во многих мирах ценится весьма высоко.$B$BЗерид уже разобрался с парочкой этих громил – в интересах безопасности, разумеется. В данном случае ожерелья можно рассматривать как дополнительные премиальные... А еще лучше вообще никак их не рассматривать, а просто собрать и принести мне сюда.','Принесите 10 обсидиановых боевых ожерелий Гезхе в Небесный лагерь в Награнде.','Вернитесь к Гезхе в Небесный лагерь, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обсидиановое боевое ожерелье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гора Ошу\'гун еще не готова к раскопкам, и мы теряем немалую прибыль, $n.$B$BК счастью, я обнаружил дополнительный источник дохода. Огры Награнда носят боевые ожерелья из обсидиана – минерала, который во многих мирах ценится весьма высоко.$B$BЗерид уже разобрался с парочкой этих громил – в интересах безопасности, разумеется. В данном случае ожерелья можно рассматривать как дополнительные премиальные... А еще лучше вообще никак их не рассматривать, а просто собрать и принести мне сюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 обсидиановых боевых ожерелий Гезхе в Небесный лагерь в Награнде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гезхе в Небесный лагерь, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9896,'Проклятие черной бракониды','Жарковато здесь, клянусь огненным чревом Каз\'горота! Вполне понимаю первую экспедицию, которая отсюда сбежала. Впрочем, все знают, что сбежали они не из-за жары. Их выжила черная браконида, хотя, конечно, они в этом ни за что не признаются!$b$bОни встали лагерем на юг от светящихся дренейских башен, что к западу отсюда, чуть на север от деревни Дикотопь. И тут, откуда ни возьмись, появляется гигантская оса и нападает на них! Жду не дождусь увидеть, какие у них будут лица, когда я привезу в Стальгорн жало этой самой осы!','Принесите жало черной бракониды геологу Коналлу в Телредор.','У меня просто слов нет, чтобы выразить, как я тебе благодарен! Ох, и потеха будет...','Ну что, удалось тебе добыть жало? Имей в виду, оно мне нужно целым и невредимым!','Вернитесь к геологу Коналлу в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятие черной бракониды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жарковато здесь, клянусь огненным чревом Каз\'горота! Вполне понимаю первую экспедицию, которая отсюда сбежала. Впрочем, все знают, что сбежали они не из-за жары. Их выжила черная браконида, хотя, конечно, они в этом ни за что не признаются!$b$bОни встали лагерем на юг от светящихся дренейских башен, что к западу отсюда, чуть на север от деревни Дикотопь. И тут, откуда ни возьмись, появляется гигантская оса и нападает на них! Жду не дождусь увидеть, какие у них будут лица, когда я привезу в Стальгорн жало этой самой осы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите жало черной бракониды геологу Коналлу в Телредор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У меня просто слов нет, чтобы выразить, как я тебе благодарен! Ох, и потеха будет...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе добыть жало? Имей в виду, оно мне нужно целым и невредимым!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Коналлу в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9897,'Я спасена!','Я не жадная. Могу поделиться. Главное, я спаслась от этого паршивца Ганкли! С Зангартопи я притащила целую тонну шкур, так что с меня не убудет!','Отнесите сверток шкур Гарольду Лейну в лагерь Эрнестуэя в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я спасена!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не жадная. Могу поделиться. Главное, я спаслась от этого паршивца Ганкли! С Зангартопи я притащила целую тонну шкур, так что с меня не убудет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сверток шкур Гарольду Лейну в лагерь Эрнестуэя в Награнде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9898,'Принесите жало черной бракониды Реавижу на заставу Болотной Крысы.','Скоро мне повезет, нутром чую!','Вернитесь к Реавижу на Заставу Болотной Крысы, что в Зангартопи.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите жало черной бракониды Реавижу на заставу Болотной Крысы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Скоро мне повезет, нутром чую!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Реавижу на Заставу Болотной Крысы, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9899,'Несделанное дело','Хотелось бы, чтобы кто-нибудь нашел способ вразумить этого Реавижа! Он совершенно забыл про свои обязанности, а вместо этого посвящает все свое время и силы тому, чтобы добиться моего расположения. Я пыталась не обращать на него внимания, я умоляла его перестать, – ничто не помогает!$b$bА до тех пор, пока он не придет в себя, мне приходится разгребать за ним несделанную работу! Например, он должен был разобраться со Спорокрылом, но могу поручиться, что это чудовище до сих пор летает на свободе! Послушай, если у тебя есть время, не сходишь ли ты в западную часть Мертвой трясины, чтобы убить этого ската? А я пока что разберусь с Реавижем...','Убейте Спорокрыла по просьбе Магаши с заставы Болотной Крысы.','Он уперся, как баран! Наверно, придется мне попросить темного охотника Дэнжая, чтобы перевел меня обратно в Забра\'джин...','Вернитесь к Магаше на Заставу Болотной Крысы, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Несделанное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотелось бы, чтобы кто-нибудь нашел способ вразумить этого Реавижа! Он совершенно забыл про свои обязанности, а вместо этого посвящает все свое время и силы тому, чтобы добиться моего расположения. Я пыталась не обращать на него внимания, я умоляла его перестать, – ничто не помогает!$b$bА до тех пор, пока он не придет в себя, мне приходится разгребать за ним несделанную работу! Например, он должен был разобраться со Спорокрылом, но могу поручиться, что это чудовище до сих пор летает на свободе! Послушай, если у тебя есть время, не сходишь ли ты в западную часть Мертвой трясины, чтобы убить этого ската? А я пока что разберусь с Реавижем...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Спорокрыла по просьбе Магаши с заставы Болотной Крысы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он уперся, как баран! Наверно, придется мне попросить темного охотника Дэнжая, чтобы перевел меня обратно в Забра\'джин...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Магаше на Заставу Болотной Крысы, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9900,'Гава\'кси','Присутствие эфириалов-мошенников в этих краях, может быть, и забавляет Гезхе, который во всем ищет выгоду... однако это серьезная угроза безопасности нашей операции.$B$BИх вождь Гава\'кси – опасный преступник, и сейчас моя главная задача – нейтрализовать его как можно скорее.$B$BЕсли хочешь быть нам $gполезным:полезной;, убей мерзавца Гава\'кси. Я лично прослежу за тем, чтобы ты $gполучил:получила; достойное вознаграждение.','Убейте Гава\'кси, который скрывается близ Ошу\'гуна, и возвращайтесь к Зериду в Небесный лагерь в Награнде.','Вернитесь к Зериду в Небесный лагерь, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гава\'кси',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Присутствие эфириалов-мошенников в этих краях, может быть, и забавляет Гезхе, который во всем ищет выгоду... однако это серьезная угроза безопасности нашей операции.$B$BИх вождь Гава\'кси – опасный преступник, и сейчас моя главная задача – нейтрализовать его как можно скорее.$B$BЕсли хочешь быть нам $gполезным:полезной;, убей мерзавца Гава\'кси. Я лично прослежу за тем, чтобы ты $gполучил:получила; достойное вознаграждение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гава\'кси, который скрывается близ Ошу\'гуна, и возвращайтесь к Зериду в Небесный лагерь в Награнде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зериду в Небесный лагерь, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9901,'Неоконченное дело','Первая экспедиция, которую отправила сюда Лига, сообщала о встрече с гигантским зангарским скатом, которого они прозвали Спорокрылом. Экспедиции пришлось срочно уходить, поэтому они не успели убить этого ската, как собирались. Я же решил заняться этим.$b$bВ обрывках их отчета говорится, что это существо обитает в юго-западной части Мертвой трясины. Кажется, воздаятель Идаар упоминал, что это к северо-востоку от Телредора.','Убейте Спорокрыла по просьбе геолога Коналла из Телредора.','Ну что, удалось тебе выследить Спорокрыла?','Вернитесь к геологу Коналлу в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неоконченное дело',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Первая экспедиция, которую отправила сюда Лига, сообщала о встрече с гигантским зангарским скатом, которого они прозвали Спорокрылом. Экспедиции пришлось срочно уходить, поэтому они не успели убить этого ската, как собирались. Я же решил заняться этим.$b$bВ обрывках их отчета говорится, что это существо обитает в юго-западной части Мертвой трясины. Кажется, воздаятель Идаар упоминал, что это к северо-востоку от Телредора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Спорокрыла по просьбе геолога Коналла из Телредора.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе выследить Спорокрыла?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Коналлу в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9902,'Ужас озера Болотных Огоньков','Путешествуя по землям, захваченными нагами, я увидел, как обходятся там с моими собратьями, которым повезло меньше моего. На юго-западе озера Болотных Огоньков я наблюдал, как один особенно жестокий десятник играет в жуткую игру. Он отправляет своих рабов на острова, когда знает, что Жутеклешень, гигантский крабстер, вышел на охоту.$b$bЯ не стану описывать, чем заканчиваются эти игры. Нас слишком мало, чтобы напасть на наг, но мы, по крайней мере, можем лишить их любимой забавы, убив их страшного питомца!','Убейте Жутеклешня и вернитесь к Пулуу в Прибежище Оребор.','Увы, больше я не могу ничем помочь своим угнетенным братьям – но, по крайней мере, мы предотвратили немало бессмысленных смертей!','Вернитесь к Пулуу в прибежище Оребор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ужас озера Болотных Огоньков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Путешествуя по землям, захваченными нагами, я увидел, как обходятся там с моими собратьями, которым повезло меньше моего. На юго-западе озера Болотных Огоньков я наблюдал, как один особенно жестокий десятник играет в жуткую игру. Он отправляет своих рабов на острова, когда знает, что Жутеклешень, гигантский крабстер, вышел на охоту.$b$bЯ не стану описывать, чем заканчиваются эти игры. Нас слишком мало, чтобы напасть на наг, но мы, по крайней мере, можем лишить их любимой забавы, убив их страшного питомца!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Жутеклешня и вернитесь к Пулуу в Прибежище Оребор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Увы, больше я не могу ничем помочь своим угнетенным братьям – но, по крайней мере, мы предотвратили немало бессмысленных смертей!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пулуу в прибежище Оребор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9903,'Самый здоровенный','Тебе удалось уничтожить большинство мелких гидр, но Мрагеш – дело другое! Это свирепая, коварная тварь, и в свое время он изводил многих рыбаков.$b$bНо я буду последней, кому он досаждает! Он прячется где-то в глубине Змеиного озера, на северо-востоке. Он уже покойник, хотя сам этого еще не знает!','Убейте Мрагеша и вернитесь к Зурджайе в Забра\'джин.','Я уверена, старина понимал, что ему скоро конец. Теперь все так переменилось, что старым обитателям болот осталось жить недолго. Оно и к лучшему, что старик теперь покоится в мире.','Старый Мрагеш "на пенсии"?','Вернитесь к Зурджайе в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самый здоровенный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось уничтожить большинство мелких гидр, но Мрагеш – дело другое! Это свирепая, коварная тварь, и в свое время он изводил многих рыбаков.$b$bНо я буду последней, кому он досаждает! Он прячется где-то в глубине Змеиного озера, на северо-востоке. Он уже покойник, хотя сам этого еще не знает!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Мрагеша и вернитесь к Зурджайе в Забра\'джин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уверена, старина понимал, что ему скоро конец. Теперь все так переменилось, что старым обитателям болот осталось жить недолго. Оно и к лучшему, что старик теперь покоится в мире.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Старый Мрагеш "на пенсии"?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зурджайе в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9904,'Охота на Жутеклешня','Мне случалось ловить всякую рыбу, какая водится в озерах, но есть одна, которую мне поймать никак не удается. Конечно, я ловила и угрей, и илистых бешенок. Но в последний раз, как я удила на одном из островов на озере Болотных Огоньков, у меня клюнул огромный крабстер. Эта тварь перекусила мне леску и уплыла прочь.$b$bЕго зовут Жутеклешень, и я не успокоюсь, пока он не сдохнет! Он такой здоровый, что его ни одному рыбаку не поймать. Наверное, придется его просто укокошить по старинке.','Убейте Жутеклешня и вернитесь к Зурджайе в Забра\'джин.','Ну, наконец-то! Говорят, у всякого великого рыболова непременно есть история о здоровенной твари, которая перекусила леску и уплыла, но лично я еще ни разу не встречала такой рыбы, которую бы я не сумела одолеть, так или иначе.','Я так понимаю, Жутеклешень уже мертв, $N?','Вернитесь к Зурджайе в Забра\'джин, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на Жутеклешня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне случалось ловить всякую рыбу, какая водится в озерах, но есть одна, которую мне поймать никак не удается. Конечно, я ловила и угрей, и илистых бешенок. Но в последний раз, как я удила на одном из островов на озере Болотных Огоньков, у меня клюнул огромный крабстер. Эта тварь перекусила мне леску и уплыла прочь.$b$bЕго зовут Жутеклешень, и я не успокоюсь, пока он не сдохнет! Он такой здоровый, что его ни одному рыбаку не поймать. Наверное, придется его просто укокошить по старинке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Жутеклешня и вернитесь к Зурджайе в Забра\'джин.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, наконец-то! Говорят, у всякого великого рыболова непременно есть история о здоровенной твари, которая перекусила леску и уплыла, но лично я еще ни разу не встречала такой рыбы, которую бы я не сумела одолеть, так или иначе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я так понимаю, Жутеклешень уже мертв, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зурджайе в Забра\'джин, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9905,'Месть Макту','В прошлый раз, когда Макту охотился на гидр на Змеином озере, на него напала самая здоровенная гидра, какую он видел в своей жизни. Макту потянулся было за копьем, но было слишком поздно. Гидра чудом не сожрала его.$b$bИ кто знает? Вдруг в следующий раз Макту повезет меньше? Макту хочет, чтобы следующего раза не случилось. Поможешь ли ты Макту отомстить этой гидре, Мрагешу?','Найдите и убейте Мрагеша, и вернитесь к Макту в Прибежище Оребор.','Много лет назад Макту взял бы шкуру Мрагеша и изготовил себе прочные доспехи. Но теперь Мрагеш слишком стар. Шкура слишком мягкая для доброго доспеха.','Вернитесь к Макту в прибежище Оребор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть Макту',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В прошлый раз, когда Макту охотился на гидр на Змеином озере, на него напала самая здоровенная гидра, какую он видел в своей жизни. Макту потянулся было за копьем, но было слишком поздно. Гидра чудом не сожрала его.$b$bИ кто знает? Вдруг в следующий раз Макту повезет меньше? Макту хочет, чтобы следующего раза не случилось. Поможешь ли ты Макту отомстить этой гидре, Мрагешу?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и убейте Мрагеша, и вернитесь к Макту в Прибежище Оребор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Много лет назад Макту взял бы шкуру Мрагеша и изготовил себе прочные доспехи. Но теперь Мрагеш слишком стар. Шкура слишком мягкая для доброго доспеха.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Макту в прибежище Оребор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9906,'Клинок вместо слов','Огры уважают лишь силу. Даже так: Силу с большой буквы. Если мы покажем им свою слабость, они тут же этим воспользуются и сметут нас с лица земли.$B$BВозможно, Гаррош готов сдаться на милость огрским псам, но только не я! Я буду драться до последней капли крови! И сейчас я посылаю тебя, $n, с посланием клану Тяжелого Кулака. Эти животные понимают только язык силы.$B$BОтправляйся в руины Пылающего Клинка, к юго-востоку отсюда, и покажи этим ограм, на что способны маг\'хары.','Джорин Мертвый Глаз из Гарадара в Награнде просит вас убить 8 сокрушителей и 8 мистиков из клана Тяжелого Кулака.','Это только начало. Есть и другие, кому мы должны преподать урок!','Это только начало. Есть и другие, кому мы должны преподать урок!','Вернитесь к Джорину Мертвому Глазу в Гарадар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинок вместо слов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огры уважают лишь силу. Даже так: Силу с большой буквы. Если мы покажем им свою слабость, они тут же этим воспользуются и сметут нас с лица земли.$B$BВозможно, Гаррош готов сдаться на милость огрским псам, но только не я! Я буду драться до последней капли крови! И сейчас я посылаю тебя, $n, с посланием клану Тяжелого Кулака. Эти животные понимают только язык силы.$B$BОтправляйся в руины Пылающего Клинка, к юго-востоку отсюда, и покажи этим ограм, на что способны маг\'хары.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Джорин Мертвый Глаз из Гарадара в Награнде просит вас убить 8 сокрушителей и 8 мистиков из клана Тяжелого Кулака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это только начало. Есть и другие, кому мы должны преподать урок!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это только начало. Есть и другие, кому мы должны преподать урок!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джорину Мертвому Глазу в Гарадар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9907,'Дерзкий набег','Прямо на западе отсюда лежит котловина Халаани. В котловине есть отроги-близнецы: расщелина Северного Ветра и расщелина Южного Ветра. В них огры Тяжелого Кулака спрятали свои поселения.$B$BЯ хочу, чтобы ты $gвыследил и уничтожил:выследила и уничтожила; всех огров в этих расщелинах. Во имя маг\'харов!','Джорин Мертвый Глаз из Гарадара в Награнде просит вас убить 10 воинов и 10 магов из клана Тяжелого Кулака.','Им следует напомнить, что мы - сила, с которой нужно считаться в этом регионе.','Вернитесь к Джорину Мертвому Глазу в Гарадар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дерзкий набег',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прямо на западе отсюда лежит котловина Халаани. В котловине есть отроги-близнецы: расщелина Северного Ветра и расщелина Южного Ветра. В них огры Тяжелого Кулака спрятали свои поселения.$B$BЯ хочу, чтобы ты $gвыследил и уничтожил:выследила и уничтожила; всех огров в этих расщелинах. Во имя маг\'харов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Джорин Мертвый Глаз из Гарадара в Награнде просит вас убить 10 воинов и 10 магов из клана Тяжелого Кулака.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Им следует напомнить, что мы - сила, с которой нужно считаться в этом регионе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джорину Мертвому Глазу в Гарадар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9908,'Hellfire Penninsula: -pn – A – ToWoW – Hellfire Turnin','Вернитесь к прапорщику Трейси Праудвелл на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Hellfire Penninsula: -pn – A – ToWoW – Hellfire Turnin',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к прапорщику Трейси Праудвелл на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (9909,'Hellfire Penninsula: -pn – A – ToWoW – Hellfire Turnin','Вернитесь к Черноглазке Зов Войны на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Hellfire Penninsula: -pn – A – ToWoW – Hellfire Turnin',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Черноглазке Зов Войны на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9910,'Страх и уважение','Если ты собираешься в руины Пылающего Клинка, у меня есть для тебя поручение. Возьми эти боевые штандарты маг\'харов и водрузи их на видном месте на территории огров. Лучше всего – где-нибудь на возвышении. Ищи гигантские погребальные костры на верхних уровнях. Помести по одному знамени возле первого, второго и третьего погребальных костров Пылающего Клинка.$B$BЭти знамена надолго запомнятся всем ограм, которые уклонились от битвы.','Установите по одному боевому штандарту маг\'харов возле первого, второго и третьего погребальных костров клана Пылающего Клинка. Когда выполните поручение, верните Илкай\'гану Мистику оставшиеся штандарты.','Может, возьмешься еще за одну работенку? На этот раз, скажем так, более деликатного свойства?','Вернитесь к Илкай\'гану Мистику в Гарадар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страх и уважение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты собираешься в руины Пылающего Клинка, у меня есть для тебя поручение. Возьми эти боевые штандарты маг\'харов и водрузи их на видном месте на территории огров. Лучше всего – где-нибудь на возвышении. Ищи гигантские погребальные костры на верхних уровнях. Помести по одному знамени возле первого, второго и третьего погребальных костров Пылающего Клинка.$B$BЭти знамена надолго запомнятся всем ограм, которые уклонились от битвы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите по одному боевому штандарту маг\'харов возле первого, второго и третьего погребальных костров клана Пылающего Клинка. Когда выполните поручение, верните Илкай\'гану Мистику оставшиеся штандарты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Может, возьмешься еще за одну работенку? На этот раз, скажем так, более деликатного свойства?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Илкай\'гану Мистику в Гарадар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9911,'Владыка болот','Эта окровавленная челюсть принадлежит гигантскому существу! Скат Пустоты, которому она принадлежала, должен быть самым огромным, какого когда-либо встречали в Зангартопи! Судя по состоянию челюсти, это существо – уже не падальщик, а хищник...$b$bКенарийская экспедиция наверняка заинтересуется подобным экземпляром. Обратитесь к наблюдательнице Лиса\'о, которая живет в небольшом лагере к западу от гряды Квагг.','Принесите челюсть "Графа" Унгула наблюдательнице Лиса\'о на Кенарийский караульный пост, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Владыка болот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эта окровавленная челюсть принадлежит гигантскому существу! Скат Пустоты, которому она принадлежала, должен быть самым огромным, какого когда-либо встречали в Зангартопи! Судя по состоянию челюсти, это существо – уже не падальщик, а хищник...$b$bКенарийская экспедиция наверняка заинтересуется подобным экземпляром. Обратитесь к наблюдательнице Лиса\'о, которая живет в небольшом лагере к западу от гряды Квагг.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите челюсть "Графа" Унгула наблюдательнице Лиса\'о на Кенарийский караульный пост, что в Зангартопи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9912,'Кенарийская экспедиция','Главные представители Круга Кенария в Запределье – это Кенарийская экспедиция. Изначально она возникла как небольшой отряд, напрямую контролируемый Кругом Кенария. Но со временем экспедиция сделалась мощной, практически независимой организацией.$b$bГлава экспедиции, Исиэль Песнь Ветра, просила нас направлять добровольцев на ее базу. Она находится в Кенарийском оплоте на востоке Зангартопи. Ступай по главной дороге, ведущей на запад, и она выведет тебя, куда нужно.','Поговорите с Исиэлью Песнью Ветра в Кенарийском оплоте в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кенарийская экспедиция',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Главные представители Круга Кенария в Запределье – это Кенарийская экспедиция. Изначально она возникла как небольшой отряд, напрямую контролируемый Кругом Кенария. Но со временем экспедиция сделалась мощной, практически независимой организацией.$b$bГлава экспедиции, Исиэль Песнь Ветра, просила нас направлять добровольцев на ее базу. Она находится в Кенарийском оплоте на востоке Зангартопи. Ступай по главной дороге, ведущей на запад, и она выведет тебя, куда нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Исиэлью Песнью Ветра в Кенарийском оплоте в Зангартопи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9913,'Консорциум ждет вас','Консорциум заинтересован в предприимчивых сотрудниках вроде вас. Трудно найти более честных, работящих и милых в общении компаньонов, чем мы.$B$BВсе, что мы требуем, – это преданность, верность делу и достаточная моральная гибкость. Если вы заинтересовались, обращайтесь к Гезхе, руководителю операционного отдела. Его можно найти в Небесном лагере, к северу от Ошу\'гуна.','Обратитесь к Гезхе. Его можно найти в Небесном лагере в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Консорциум ждет вас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Консорциум заинтересован в предприимчивых сотрудниках вроде вас. Трудно найти более честных, работящих и милых в общении компаньонов, чем мы.$B$BВсе, что мы требуем, – это преданность, верность делу и достаточная моральная гибкость. Если вы заинтересовались, обращайтесь к Гезхе, руководителю операционного отдела. Его можно найти в Небесном лагере, к северу от Ошу\'гуна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обратитесь к Гезхе. Его можно найти в Небесном лагере в Награнде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9914,'Кость на вес золота','Кость элекка – материал весьма ценный. Мои постоянные клиенты из дальних краев уже встали в очередь и предлагают за материал хорошую цену.$B$BЯ готов поделиться с тобой долей прибыли, если ты будешь мне помогать.$B$BМне нужна кость высшего качества, а именно – бивни диких элекков, обитающих в Награнде. Кость самцов элекка не дотягивает до стандарта.$B$BИ не волнуйся, это не браконьерство. У меня есть твердая договоренность и с орками, и с дренеями.$B$BНу что, мы с тобой договорились?','Добудьте 3 пары бивней элекков и принесите их Шадреку в Небесный лагерь в Награнде.','Вернитесь к Шадреку в Небесный лагерь, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кость на вес золота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кость элекка – материал весьма ценный. Мои постоянные клиенты из дальних краев уже встали в очередь и предлагают за материал хорошую цену.$B$BЯ готов поделиться с тобой долей прибыли, если ты будешь мне помогать.$B$BМне нужна кость высшего качества, а именно – бивни диких элекков, обитающих в Награнде. Кость самцов элекка не дотягивает до стандарта.$B$BИ не волнуйся, это не браконьерство. У меня есть твердая договоренность и с орками, и с дренеями.$B$BНу что, мы с тобой договорились?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 пары бивней элекков и принесите их Шадреку в Небесный лагерь в Награнде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шадреку в Небесный лагерь, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9915,'Кость на вес воздуха','Отличные, более тонкие образцы бивней, хотя некоторые выглядят немного тусклыми.$B$BУ тебя огромная благодарность Консорциума, $N.','Мне всё ещё нужно больше пар клыков из слоновой кости диких элекков, бродящих по этой земле. К сожалению, мой бюджет больше не будет покрывать твою долю прибыли.','Вернитесь к Шадреку в Награнд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кость на вес воздуха',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные, более тонкие образцы бивней, хотя некоторые выглядят немного тусклыми.$B$BУ тебя огромная благодарность Консорциума, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне всё ещё нужно больше пар клыков из слоновой кости диких элекков, бродящих по этой земле. К сожалению, мой бюджет больше не будет покрывать твою долю прибыли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шадреку в Награнд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (9916,'Припасы Кровавой Глазницы','Огры Тяжелого Кулака спрятали украденные у нас припасы в расселинах Награнда, к западу отсюда, в котловине Халаани.$B$BРаз уж ты все равно туда отправляешься, поищи сундуки с припасами. Если удастся их вернуть, это сильно облегчит жизнь нашим матронам в Гарадаре.','Найдите 10 ящиков с припасами клана Кровавой Глазницы и принесите их Илкай\'гану Мистику.','Почти все наши пожитки либо погибли, либо были украдены при нападениях. Я мало что могу тебе предложить, но кое-что интересное у меня есть... Оно тебе наверняка пригодится...','Вернитесь к Илкай\'гану Мистику в Гарадар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Припасы Кровавой Глазницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огры Тяжелого Кулака спрятали украденные у нас припасы в расселинах Награнда, к западу отсюда, в котловине Халаани.$B$BРаз уж ты все равно туда отправляешься, поищи сундуки с припасами. Если удастся их вернуть, это сильно облегчит жизнь нашим матронам в Гарадаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 10 ящиков с припасами клана Кровавой Глазницы и принесите их Илкай\'гану Мистику.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Почти все наши пожитки либо погибли, либо были украдены при нападениях. Я мало что могу тебе предложить, но кое-что интересное у меня есть... Оно тебе наверняка пригодится...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Илкай\'гану Мистику в Гарадар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9917,'Не верь глазам своим','То ли зрение меня подводит, то ли там вдалеке и вправду огры? Как это они забрались так далеко от своего холма? Мне это очень не нравится, $gстранник:странница;. Сначала Темная Кровь, теперь огры. Нам просто не справиться со всеми напастями.$B$BПопробуй разузнать, почему огры забрались на восток. Их передовой лагерь где-то в 200 шагах восточнее отсюда. Увидишь охотников клана Тяжелого Кулака – значит, $gдобрался:добралась; до места. Перебей всех и забери их планы вторжения.','Добудьте планы Тяжелого Кулака для охотницы Бинтук из Телаара.','<Бинтук просматривает планы.>$B$BВо имя Света! Почерк отвратительный. Не могу понять, то ли они собираются "съесть синекожих и захватить их деревню", то ли испечь пирог с голубикой. И так и так можно прочесть. Надо с этим разобраться!','Есть какие-то новости?','Вернитесь к охотнице Бинтук в Телаар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не верь глазам своим',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То ли зрение меня подводит, то ли там вдалеке и вправду огры? Как это они забрались так далеко от своего холма? Мне это очень не нравится, $gстранник:странница;. Сначала Темная Кровь, теперь огры. Нам просто не справиться со всеми напастями.$B$BПопробуй разузнать, почему огры забрались на восток. Их передовой лагерь где-то в 200 шагах восточнее отсюда. Увидишь охотников клана Тяжелого Кулака – значит, $gдобрался:добралась; до места. Перебей всех и забери их планы вторжения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте планы Тяжелого Кулака для охотницы Бинтук из Телаара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Бинтук просматривает планы.>$B$BВо имя Света! Почерк отвратительный. Не могу понять, то ли они собираются "съесть синекожих и захватить их деревню", то ли испечь пирог с голубикой. И так и так можно прочесть. Надо с этим разобраться!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть какие-то новости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнице Бинтук в Телаар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9918,'Только не в мою смену!','Поговорите с Глыбом. Когда получите необходимые сведения, возвращайтесь к охотнице Бинтук.','Вероятно, он будет спать на гребне.','Вернитесь к охотнице Бинтук в Телаар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только не в мою смену!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Глыбом. Когда получите необходимые сведения, возвращайтесь к охотнице Бинтук.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вероятно, он будет спать на гребне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнице Бинтук в Телаар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9919,'Спореггар','Ты $gдобрый:добрая:r; |3-6($r), $n. Не как другие, с которыми я встречался.$b$bТебе стоит встретиться с моими сородичами – они будут очень благодарны тебе за помощь. Отнеси эти мешочки со спорами к нашему предводителю, Мссхи\'фну. Ты найдешь его в Спореггаре, к северу отсюда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спореггар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gдобрый:добрая:r; |3-6($r), $n. Не как другие, с которыми я встречался.$b$bТебе стоит встретиться с моими сородичами – они будут очень благодарны тебе за помощь. Отнеси эти мешочки со спорами к нашему предводителю, Мссхи\'фну. Ты найдешь его в Спореггаре, к северу отсюда.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (9920,'Мо\'мор Разрушитель','Охотница Бинтук из Телаара хочет, чтобы вы поговорили с Мо\'мором Разрушителем.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мо\'мор Разрушитель',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Охотница Бинтук из Телаара хочет, чтобы вы поговорили с Мо\'мором Разрушителем.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9921,'Руины Пылающего Клинка','Эти вылазки огров – явные предвестники большого вторжения. Мы должны нанести им удар до того, как они соберут армию для атаки на город.$B$BЕсли ты не боишься испачкать руки, у меня есть для тебя поручение, |3-6($r).$B$BСамый крупный отряд Тяжелого Кулака расположился сейчас в руинах Пылающего Клинка, почти прямо к востоку от Телаара, на границе леса Тероккар. Иди туда и покажи этим мерзавцам, что Телаар никогда не подчинится их воле!','Мо\'мор Разрушитель из Телаара желает, чтобы вы убили 8 мистиков и 8 сокрушителей из клана Тяжелого Кулака.','Мы только недавно вернули Телаар. Мы не потеряем его снова!','Вернитесь к Мо\'мору Разрушителю в Телаар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руины Пылающего Клинка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти вылазки огров – явные предвестники большого вторжения. Мы должны нанести им удар до того, как они соберут армию для атаки на город.$B$BЕсли ты не боишься испачкать руки, у меня есть для тебя поручение, |3-6($r).$B$BСамый крупный отряд Тяжелого Кулака расположился сейчас в руинах Пылающего Клинка, почти прямо к востоку от Телаара, на границе леса Тероккар. Иди туда и покажи этим мерзавцам, что Телаар никогда не подчинится их воле!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мо\'мор Разрушитель из Телаара желает, чтобы вы убили 8 мистиков и 8 сокрушителей из клана Тяжелого Кулака.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы только недавно вернули Телаар. Мы не потеряем его снова!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мо\'мору Разрушителю в Телаар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9922,'Расселины Награнда','Твоя сила изумляет, $n! Ты $gготов:готова; к новым подвигам?$B$BМне донесли, что большой отряд огров из клана Тяжелого Кулака скрывается в расселинах Награнда, в котловине Халаани к северо-западу отсюда.$B$BСпустись в расселины и разберись с ограми.','Мо\'мор Разрушитель из Телаара желает, чтобы вы убили 10 воинов и 10 магов клана Тяжелого Кулака.','Остерегайся элементалей в бассейне, $N.','Вернитесь к Мо\'мору Разрушителю в Телаар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Расселины Награнда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя сила изумляет, $n! Ты $gготов:готова; к новым подвигам?$B$BМне донесли, что большой отряд огров из клана Тяжелого Кулака скрывается в расселинах Награнда, в котловине Халаани к северо-западу отсюда.$B$BСпустись в расселины и разберись с ограми.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мо\'мор Разрушитель из Телаара желает, чтобы вы убили 10 воинов и 10 магов клана Тяжелого Кулака.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Остерегайся элементалей в бассейне, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мо\'мору Разрушителю в Телаар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9923,'НА ПОМОЩЬ!','НА ПОМОЩЬ! Они сожрут меня заживо! Точно-точно сожрут, я знаю!$B$BНайди ключ. Он у кого-то из этих огров.$B$BЕсли поможешь мне выбраться отсюда, мой отец щедро тебя наградит! Я – сын Арехрона, владыки Телаара.','Найдите ключ клана Тяжелого Кулака и освободите Корки. После этого отправляйтесь к Арехрону в Телаар за наградой.','Разыщите Арехрона в Телааре, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','НА ПОМОЩЬ!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','НА ПОМОЩЬ! Они сожрут меня заживо! Точно-точно сожрут, я знаю!$B$BНайди ключ. Он у кого-то из этих огров.$B$BЕсли поможешь мне выбраться отсюда, мой отец щедро тебя наградит! Я – сын Арехрона, владыки Телаара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ключ клана Тяжелого Кулака и освободите Корки. После этого отправляйтесь к Арехрону в Телаар за наградой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите Арехрона в Телааре, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9924,'Корки снова пропал!','Найдите и освободите Корки.','Вернитесь к Арехрону в Телаар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Корки снова пропал!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите и освободите Корки.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Арехрону в Телаар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9925,'Вопросы безопасности','Гезхе разместил нас как можно ближе к Ошу\'гуну, совсем не заботясь о безопасности команды. Почему? Да просто он посчитал, что тут он сможет заработать на десять процентов больше, чем если бы мы расположились в горах к югу отсюда.$B$BНаплевать на бешеных отроков Бездны, которые шастают буквально в десяти шагах от нас. Это же проблема службы безопасности, а не Гезхе.$B$BВот что. Перебьешь отроков Бездны – получишь десятую долю денег, выделенных на охрану. И не слишком радуйся: денег там ворг наплакал.','Убейте 8 отроков Бездны поблизости от Ошу\'гуна по просьбе Зерида из Небесного лагеря.','Вернитесь к Зериду в Небесный лагерь, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вопросы безопасности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гезхе разместил нас как можно ближе к Ошу\'гуну, совсем не заботясь о безопасности команды. Почему? Да просто он посчитал, что тут он сможет заработать на десять процентов больше, чем если бы мы расположились в горах к югу отсюда.$B$BНаплевать на бешеных отроков Бездны, которые шастают буквально в десяти шагах от нас. Это же проблема службы безопасности, а не Гезхе.$B$BВот что. Перебьешь отроков Бездны – получишь десятую долю денег, выделенных на охрану. И не слишком радуйся: денег там ворг наплакал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 8 отроков Бездны поблизости от Ошу\'гуна по просьбе Зерида из Небесного лагеря.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зериду в Небесный лагерь, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9926,'FLAG Совет Теней/Цепочка заданий Боевой Молот') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG Совет Теней/Цепочка заданий Боевой Молот',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9927,'Безжалостное коварство','По поручению Лантрезора Клинка из Руин Пылающего Клинка в Награнде вонзите 10 знамен клана Боевого Молота в тела защитников бастиона Вечной Скорби.$B$BВерните Лантрезору Клинку оставшиеся знамена.','Вернитесь к Лантрезору Клинку на Руины Пылающего Клинка, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Безжалостное коварство',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Лантрезора Клинка из Руин Пылающего Клинка в Награнде вонзите 10 знамен клана Боевого Молота в тела защитников бастиона Вечной Скорби.$B$BВерните Лантрезору Клинку оставшиеся знамена.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лантрезору Клинку на Руины Пылающего Клинка, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9928,'Военная хитрость','Чтобы мой план сработал, мне нужно, чтобы ты $Gвыкрал:выкрала; оружие из бастиона Вечной Скорби.$B$BОбыщи крепость. Ищи сундуки с оружием Вечной Скорби. Все, что найдешь, неси мне.$B$BБастион расположен прямо на юге и чуть к западу от руин Пылающего Клинка.','Принесите Лантрезору Клинку в руины Пылающего Клинка 10 ящиков с оружием бастиона Вечной Скорби.','Вернитесь к Лантрезору Клинку на Руины Пылающего Клинка, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Военная хитрость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы мой план сработал, мне нужно, чтобы ты $Gвыкрал:выкрала; оружие из бастиона Вечной Скорби.$B$BОбыщи крепость. Ищи сундуки с оружием Вечной Скорби. Все, что найдешь, неси мне.$B$BБастион расположен прямо на юге и чуть к западу от руин Пылающего Клинка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Лантрезору Клинку в руины Пылающего Клинка 10 ящиков с оружием бастиона Вечной Скорби.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лантрезору Клинку на Руины Пылающего Клинка, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9931,'Взаимная вежливость','По поручению Лантрезора Клинка из Руин Пылающего Клинка в Награнде воткните 10 знамен Вечной Скорби в трупы огров клана Боевого Молота, обитающих в руинах Веселого Черепа.$B$BОставшиеся знамена верните Лантрезору.','Сможешь предугадать, что будет дальше?','Вернитесь к Лантрезору Клинку на Руины Пылающего Клинка, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взаимная вежливость',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Лантрезора Клинка из Руин Пылающего Клинка в Награнде воткните 10 знамен Вечной Скорби в трупы огров клана Боевого Молота, обитающих в руинах Веселого Черепа.$B$BОставшиеся знамена верните Лантрезору.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сможешь предугадать, что будет дальше?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лантрезору Клинку на Руины Пылающего Клинка, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9932,'Вещественное доказательство','Твоя вылазка в бастион Вечной Скорби открыла нам новые возможности. Теперь у нас есть целая куча мертвых тел, с помощью которых можно инсценировать великую битву.$B$BОтправляйся на внутренний двор руин Веселого Черепа. Там горит костер. Убедись, что поблизости никого нет, и воспользуйся этим одеялом, чтобы подать дымовые сигналы. Когда мои огры увидят дым, они проникнут туда и живописно разложат повсюду трупы убитых защитников бастиона.$B$BЭто добьет наших врагов!','По поручению Лантрезора Клинка из Руин Пылающего Клинка в Награнде найдите костер Боевого Молота во внутреннем дворе руин Веселого Черепа. С помощью мокрого шерстяного одеяла подайте дымовой сигнал ограм.','Теперь ты понимаешь, почему меня невозможно победить?','Вернитесь к Лантрезору Клинку на Руины Пылающего Клинка, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вещественное доказательство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя вылазка в бастион Вечной Скорби открыла нам новые возможности. Теперь у нас есть целая куча мертвых тел, с помощью которых можно инсценировать великую битву.$B$BОтправляйся на внутренний двор руин Веселого Черепа. Там горит костер. Убедись, что поблизости никого нет, и воспользуйся этим одеялом, чтобы подать дымовые сигналы. Когда мои огры увидят дым, они проникнут туда и живописно разложат повсюду трупы убитых защитников бастиона.$B$BЭто добьет наших врагов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Лантрезора Клинка из Руин Пылающего Клинка в Награнде найдите костер Боевого Молота во внутреннем дворе руин Веселого Черепа. С помощью мокрого шерстяного одеяла подайте дымовой сигнал ограм.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Теперь ты понимаешь, почему меня невозможно победить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лантрезору Клинку на Руины Пылающего Клинка, что в Награнде.',`completedtext_loc8`);
