INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9935,'Разыскиваются:$B$BГизельда Колдунья из бастиона Вечной Скорби и ее приспешники по обвинению в убийствах, ритуальных жертвоприношениях, пособничестве Легиону, похищении мирных граждан и многочисленных кражах со взломом.$B$BВ настоящее время скрывается в бастионе Вечной Скорби в юго-восточном Награнде, на окраине леса Тероккар.$B$BТот, кто сумеет поймать преступницу и предать ее в руки правосудия, получит награду от стража-смотрителя Быккрока в Гарадаре.','Убейте Гизельду Колдунью и 10 любых служителей бастиона Вечной Скорби. Получите награду у стража-смотрителя Быккрока в Гарадаре.','Ты здесь, чтобы получить награду?','Вернитесь к стражу-смотрителю Быккроку в Гарадар, что в Награнде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разыскиваются:$B$BГизельда Колдунья из бастиона Вечной Скорби и ее приспешники по обвинению в убийствах, ритуальных жертвоприношениях, пособничестве Легиону, похищении мирных граждан и многочисленных кражах со взломом.$B$BВ настоящее время скрывается в бастионе Вечной Скорби в юго-восточном Награнде, на окраине леса Тероккар.$B$BТот, кто сумеет поймать преступницу и предать ее в руки правосудия, получит награду от стража-смотрителя Быккрока в Гарадаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гизельду Колдунью и 10 любых служителей бастиона Вечной Скорби. Получите награду у стража-смотрителя Быккрока в Гарадаре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты здесь, чтобы получить награду?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу-смотрителю Быккроку в Гарадар, что в Награнде.',`completedtext_loc8`);
