INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9939,'Разыскивается живым или мертвым!$B$BЗорбо Советчик разыскивается за организацию ряда спланированных нападений на Гарадар. При содействии разрушителей и шаманов преступник убил бессчетное количество орков. Зорбо вооружен, беспощаден и очень опасен.$B$BСейчас он скрывается в руинах Веселого Черепа в северных горах Награнда.$B$BУбивший или поймавший Зорбо Советчика может обратиться за наградой к стражу-смотрителю Быккроку в Гарадаре.','Убейте Зорбо Советчика, 5 шаманов и 5 разорителей из клана Боевого Молота. Получите награду у стража-смотрителя Быккрока.','Ты здесь, чтобы получить награду?','Вернитесь к стражу-смотрителю Быккроку в Гарадар, что в Награнде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разыскивается живым или мертвым!$B$BЗорбо Советчик разыскивается за организацию ряда спланированных нападений на Гарадар. При содействии разрушителей и шаманов преступник убил бессчетное количество орков. Зорбо вооружен, беспощаден и очень опасен.$B$BСейчас он скрывается в руинах Веселого Черепа в северных горах Награнда.$B$BУбивший или поймавший Зорбо Советчика может обратиться за наградой к стражу-смотрителю Быккроку в Гарадаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зорбо Советчика, 5 шаманов и 5 разорителей из клана Боевого Молота. Получите награду у стража-смотрителя Быккрока.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты здесь, чтобы получить награду?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу-смотрителю Быккроку в Гарадар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9940,'Разыскивается живым или мертвым!$B$BЗорбо Советчик разыскивается за организацию ряда спланированных нападений на Телаар. При содействии разрушителей и шаманов преступник убил бессчетное количество Сломленных. Зорбо вооружен, беспощаден и очень опасен.$B$BСейчас он скрывается в руинах Веселого Черепа в северных горах Награнда.$B$BУбивший или поймавший Зорбо Советчика может обратиться за наградой к стражу-смотрителю Мой\'прну Джиллу в Телаар.','Убейте Зорбо Советчика, 5 шаманов и 5 разорителей из клана Боевого Молота. Получите награду у стража-смотрителя Мой\'прна Джилла.','Ты здесь, чтобы получить награду?','Вернитесь к стражу-смотрителю Мой\'прну Джиллу в Телаар, что в Награнде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Разыскивается живым или мертвым!$B$BЗорбо Советчик разыскивается за организацию ряда спланированных нападений на Телаар. При содействии разрушителей и шаманов преступник убил бессчетное количество Сломленных. Зорбо вооружен, беспощаден и очень опасен.$B$BСейчас он скрывается в руинах Веселого Черепа в северных горах Награнда.$B$BУбивший или поймавший Зорбо Советчика может обратиться за наградой к стражу-смотрителю Мой\'прну Джиллу в Телаар.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зорбо Советчика, 5 шаманов и 5 разорителей из клана Боевого Молота. Получите награду у стража-смотрителя Мой\'прна Джилла.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты здесь, чтобы получить награду?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу-смотрителю Мой\'прну Джиллу в Телаар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (9944,'Пропавший маг\'харский караван','Найдите пропавший маг\'харский караван.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший маг\'харский караван',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите пропавший маг\'харский караван.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9945,'Войной на Боевой Молот','Мы направлялись в Земли Предков, когда нас окружили огры Боевого Молота. Они напали одновременно со всех сторон, убили нескольких воинов из похоронной процессии и многих других. Более того, они осквернили останки старейшины, покоившиеся в катафалке.$B$BСпрашивается, зачем? Чтобы унизить нас и продемонстрировать свою силу? Даже огры Тяжелого Кулака до такого бы не опустились.$B$BЯ – благочестивый и праведный орк, $n, но у всякого терпения есть пределы. Ты найдешь этих негодяев к северо-западу отсюда, у холма Боевого Молота. Уничтожь их всех!','Старейшина Йорли из Маг\'харского Каравана в Награнде попросил вас убить 8 громил и 8 чернокнижников клана Боевого Молота.','Для начала неплохо, но надо еще разобраться с их вожаком, чтобы закрепить результат.','Это всего лишь один шаг в долгом процессе. Ограм, как и собакам, нужно показать разницу между добром и злом. Рассказывать им бесполезно.','Вернитесь к старейшине Йорли к Похоронной процессии маг\'харов, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Войной на Боевой Молот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы направлялись в Земли Предков, когда нас окружили огры Боевого Молота. Они напали одновременно со всех сторон, убили нескольких воинов из похоронной процессии и многих других. Более того, они осквернили останки старейшины, покоившиеся в катафалке.$B$BСпрашивается, зачем? Чтобы унизить нас и продемонстрировать свою силу? Даже огры Тяжелого Кулака до такого бы не опустились.$B$BЯ – благочестивый и праведный орк, $n, но у всякого терпения есть пределы. Ты найдешь этих негодяев к северо-западу отсюда, у холма Боевого Молота. Уничтожь их всех!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Старейшина Йорли из Маг\'харского Каравана в Награнде попросил вас убить 8 громил и 8 чернокнижников клана Боевого Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Для начала неплохо, но надо еще разобраться с их вожаком, чтобы закрепить результат.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это всего лишь один шаг в долгом процессе. Ограм, как и собакам, нужно показать разницу между добром и злом. Рассказывать им бесполезно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Йорли к Похоронной процессии маг\'харов, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9948,'Спасательная экспедиция','Огры обожают свежатинку, уж я-то знаю. А это значит, что маг\'харов, которых они захватили, скорее всего, держат живыми, пока не придет время подать их к столу. Мерзко звучит, но нет худа без добра.$B$BПроберись к холму Боевого Молота и отыщи там пленных маг\'харов. Ключи от их клеток, скорее всего, хранятся у огров из клана Боевого Молота, шатающихся где-то поблизости.$B$BУбей этих огров, забери ключи и освободи пленников.','Освободите 5 пленных маг\'харов по просьбе старейшины Унгриза из маг\'харского каравана в Награнде.','<Унгриз вздыхает.>$B$BЯ знаю, что прошу о многом, $N; но верни их живыми...','Вернитесь к старейшине Унгризу к Похоронной процессии маг\'харов, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасательная экспедиция',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огры обожают свежатинку, уж я-то знаю. А это значит, что маг\'харов, которых они захватили, скорее всего, держат живыми, пока не придет время подать их к столу. Мерзко звучит, но нет худа без добра.$B$BПроберись к холму Боевого Молота и отыщи там пленных маг\'харов. Ключи от их клеток, скорее всего, хранятся у огров из клана Боевого Молота, шатающихся где-то поблизости.$B$BУбей этих огров, забери ключи и освободи пленников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите 5 пленных маг\'харов по просьбе старейшины Унгриза из маг\'харского каравана в Награнде.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Унгриз вздыхает.>$B$BЯ знаю, что прошу о многом, $N; но верни их живыми...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Унгризу к Похоронной процессии маг\'харов, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9951,'Он следит за тобой!','Скорее, прячьтесь! Нафталар следит за вами... за всеми нами следит!$B$BЯ не смею взбираться на башню и говорить с ним, но вы... вы, похоже, знаете нужные слова. Только будьте осторожны – он не любит шуток и быстр на расправу с дураками.$B$BЕсли сможете, уговорите его спуститься и попить чайку... Но в любом случае, сделайте что-нибудь, чтобы он перестал на меня смотреть!','Не надо нам было приглашать его на ужин, это точно!$B$BИли, по крайней мере, надо было настоять хотя бы на паре блюд перед десертом, который они принесли!','Вернитесь к хранителю Древлосу в Перелесок Кенария, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Он следит за тобой!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скорее, прячьтесь! Нафталар следит за вами... за всеми нами следит!$B$BЯ не смею взбираться на башню и говорить с ним, но вы... вы, похоже, знаете нужные слова. Только будьте осторожны – он не любит шуток и быстр на расправу с дураками.$B$BЕсли сможете, уговорите его спуститься и попить чайку... Но в любом случае, сделайте что-нибудь, чтобы он перестал на меня смотреть!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не надо нам было приглашать его на ужин, это точно!$B$BИли, по крайней мере, надо было настоять хотя бы на паре блюд перед десертом, который они принесли!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Древлосу в Перелесок Кенария, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9956,'Разграбленный караван','Я сопровождала караван, направлявшийся в Прибежище Оребор в Зангартопи. На подходе к болотам на нас напали огры Боевого Молота. Они забрали груз, перебили всех наших, а меня взяли в плен.$B$BК счастью, они не озаботились тем, чтобы укрепить замок моей клетки. Когда они все заснули, мне удалось выбраться и сбежать.$B$BМоих мертвых товарищей уже не спасти, но мы можем хотя бы забрать груз из разграбленного каравана. Огры спрятали краденое на холме Боевого Молота в горах на северо-западе Награнда.','Помогите охотнице Киме вернуть 10 телаарских ящиков с припасами.','Вот незадача... Корки, сын Арехрона, спросил меня, что случилось. Выслушав новости, он снова пропал!','Вернитесь к охотнице Киме в Телаар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разграбленный караван',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сопровождала караван, направлявшийся в Прибежище Оребор в Зангартопи. На подходе к болотам на нас напали огры Боевого Молота. Они забрали груз, перебили всех наших, а меня взяли в плен.$B$BК счастью, они не озаботились тем, чтобы укрепить замок моей клетки. Когда они все заснули, мне удалось выбраться и сбежать.$B$BМоих мертвых товарищей уже не спасти, но мы можем хотя бы забрать груз из разграбленного каравана. Огры спрятали краденое на холме Боевого Молота в горах на северо-западе Награнда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите охотнице Киме вернуть 10 телаарских ящиков с припасами.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вот незадача... Корки, сын Арехрона, спросил меня, что случилось. Выслушав новости, он снова пропал!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к охотнице Киме в Телаар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (9957,'Что случилось в Перелеске Кенария?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что случилось в Перелеске Кенария?',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9960,'Что случилось в Перелеске Кенария?','Здравствуйте, |3-6($c). От друидов из Перелеска Кенария уже давно нет никаких вестей.$B$BЯ хочу, чтобы вы отправились туда и узнали, что с ними случилось. Это место к северо-западу отсюда, если ехать через лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что случилось в Перелеске Кенария?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуйте, |3-6($c). От друидов из Перелеска Кенария уже давно нет никаких вестей.$B$BЯ хочу, чтобы вы отправились туда и узнали, что с ними случилось. Это место к северо-западу отсюда, если ехать через лес.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (9961,'Что случилось в Перелеске Кенария?','$c, у меня к вам важное дело. От друидов в Перелеске Кенария уже давно нет никаких вестей, и это тревожит меня, потому что раньше они связывались с нами довольно часто.$B$BНе могли бы вы съездить туда и проверить, все ли с ними в порядке? Перелесок находится к северо-западу отсюда, если ехать через лес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что случилось в Перелеске Кенария?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$c, у меня к вам важное дело. От друидов в Перелеске Кенария уже давно нет никаких вестей, и это тревожит меня, потому что раньше они связывались с нами довольно часто.$B$BНе могли бы вы съездить туда и проверить, все ли с ними в порядке? Перелесок находится к северо-западу отсюда, если ехать через лес.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9962,'Кольцо Крови: Хромоног','Ты $gготов:готова; к своей первой битве? Дай мне знать, и я объявлю о начале боя. Тебе останется только ждать в Кольце Крови, когда появится твой противник.$B$BТы будешь сражаться против Хромонога, свирепого копытня.$B$BУдачи! Надеюсь, ты $gпривел:привела; с собой верных друзей.$B$BИ помни, поединок закончится только тогда, когда кто-то из вас – либо ты, либо соперник – упадет на арену и больше не встанет.','Одержите победу над Хромоногом. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.','Поединок закончится только тогда, когда один из вас упадёт замертво.','Одержана победа над Хромоногом','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо Крови: Хромоног',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gготов:готова; к своей первой битве? Дай мне знать, и я объявлю о начале боя. Тебе останется только ждать в Кольце Крови, когда появится твой противник.$B$BТы будешь сражаться против Хромонога, свирепого копытня.$B$BУдачи! Надеюсь, ты $gпривел:привела; с собой верных друзей.$B$BИ помни, поединок закончится только тогда, когда кто-то из вас – либо ты, либо соперник – упадет на арену и больше не встанет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Хромоногом. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поединок закончится только тогда, когда один из вас упадёт замертво.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Одержана победа над Хромоногом',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9967,'Кольцо Крови: братья Блю','В следующей схватке тебе придется сразиться сразу с двумя противниками – а точнее, с братьями-близнецами. Они называют себя "Братья Блю."$B$BЕще не поздно отказаться от боя, $n. Если откажешься, я пойму.$B$BНо если ты $gготов:готова; драться, тогда войди в Кольцо Крови и жди выхода близнецов из племени Темной Крови.$B$BКто упал и не поднялся, тот проиграл. Кто устоял, тот победитель!','Одержите победу над близнецами из племени Темной Крови, которые называют себя "Братья Блю". После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.','Поединок закончится только тогда, когда один из вас упадёт замертво.','"Братья Блю" побеждены','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо Крови: братья Блю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В следующей схватке тебе придется сразиться сразу с двумя противниками – а точнее, с братьями-близнецами. Они называют себя "Братья Блю."$B$BЕще не поздно отказаться от боя, $n. Если откажешься, я пойму.$B$BНо если ты $gготов:готова; драться, тогда войди в Кольцо Крови и жди выхода близнецов из племени Темной Крови.$B$BКто упал и не поднялся, тот проиграл. Кто устоял, тот победитель!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над близнецами из племени Темной Крови, которые называют себя "Братья Блю". После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поединок закончится только тогда, когда один из вас упадёт замертво.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','"Братья Блю" побеждены',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9968,'Странная энергия','Живущие в чащобе пухоспинки почему-то изменились.$B$BРаньше там бурлила жизнь, но теперь остались только эти бабочки, и если раньше они были очень мирными, то теперь нападают на всякого, кто приблизится к ним.$B$BМне нужно сравнить агрессивных пухоспинок с нормальными, а для этого мне понадобятся образцы и тех, и других. Обычных можно найти и к югу, и к северу отсюда.$B$BУверен, это как-то связано с гибелью всех друидов.','Странно. Образцы агрессивных пухоспинок словно бы пропитаны чистейшей маной...$B$BПохоже то, что убило друидов, оставило после себя сильное энергетическое поле. Но пухоспинки почему-то не погибли от него, а только стали очень агрессивными.$B$BНо в одном я теперь уверен – эта странная энергия является побочным продуктом того, что убило всех друидов в чащобе.','Вы принесли образцы?','Вернитесь к землепряду Тавгрену сразу за Перелеском Кенария, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странная энергия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Живущие в чащобе пухоспинки почему-то изменились.$B$BРаньше там бурлила жизнь, но теперь остались только эти бабочки, и если раньше они были очень мирными, то теперь нападают на всякого, кто приблизится к ним.$B$BМне нужно сравнить агрессивных пухоспинок с нормальными, а для этого мне понадобятся образцы и тех, и других. Обычных можно найти и к югу, и к северу отсюда.$B$BУверен, это как-то связано с гибелью всех друидов.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Странно. Образцы агрессивных пухоспинок словно бы пропитаны чистейшей маной...$B$BПохоже то, что убило друидов, оставило после себя сильное энергетическое поле. Но пухоспинки почему-то не погибли от него, а только стали очень агрессивными.$B$BНо в одном я теперь уверен – эта странная энергия является побочным продуктом того, что убило всех друидов в чащобе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы принесли образцы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепряду Тавгрену сразу за Перелеском Кенария, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9970,'Кольцо Крови: Камнедар Выщербленный Повелитель','Это будет нелегкий бой, $n. Надеюсь, у тебя есть отважные друзья, которые смогут тебе помочь? Огры нашли великана в Острогорье. Его зовут Камнедар! Поверь мне на слово, $gодин:одна; ты не справишься. Этот Камнедар непобедим! Он тверд, как скала, в прямом смысле слова!$B$BЕсли хочешь сразиться с ним, войди в Кольцо Крови, и он примет вызов.','Победите Камнедара Выщербленного Повелителя. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.','Поединок закончится только тогда, когда один из вас упадёт замертво.','Победа над Камнедаром Выщербленным Повелителем одержана','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо Крови: Камнедар Выщербленный Повелитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это будет нелегкий бой, $n. Надеюсь, у тебя есть отважные друзья, которые смогут тебе помочь? Огры нашли великана в Острогорье. Его зовут Камнедар! Поверь мне на слово, $gодин:одна; ты не справишься. Этот Камнедар непобедим! Он тверд, как скала, в прямом смысле слова!$B$BЕсли хочешь сразиться с ним, войди в Кольцо Крови, и он примет вызов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите Камнедара Выщербленного Повелителя. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поединок закончится только тогда, когда один из вас упадёт замертво.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа над Камнедаром Выщербленным Повелителем одержана',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (9971,'Ответы в чащобе','Ума не приложу, что же убило всех местных друидов? Меня самого тут пару дней не было – я изучал Костяные пустоши на юге.$B$BПожалуйста, помогите мне выяснить, что за трагедия здесь произошла! Нужно сходить в чащобу и поискать там какие-то улики, подсказки, которые смогут навести нас на след. Когда я был там – правда, очень не долго – то видел труп некоего Сломленного и странный предмет около него.$B$BА насчет Древлоса не волнуйтесь – он, возможно, и сошел с ума от того, что там произошло, но вообще он безобиден.','Удалось что-нибудь найти?','Вернитесь к землепряду Тавгрену сразу за Перелеском Кенария, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ответы в чащобе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ума не приложу, что же убило всех местных друидов? Меня самого тут пару дней не было – я изучал Костяные пустоши на юге.$B$BПожалуйста, помогите мне выяснить, что за трагедия здесь произошла! Нужно сходить в чащобу и поискать там какие-то улики, подсказки, которые смогут навести нас на след. Когда я был там – правда, очень не долго – то видел труп некоего Сломленного и странный предмет около него.$B$BА насчет Древлоса не волнуйтесь – он, возможно, и сошел с ума от того, что там произошло, но вообще он безобиден.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось что-нибудь найти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к землепряду Тавгрену сразу за Перелеском Кенария, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9972,'Кольцо Крови: Скрагат','Ты сметаешь их всех, $gмалыш:красавица;! Валишь просто пачками! На следующий поединок они выставляют действительно сильного бойца. Говорят, он повелитель Бездны или как там его... В общем, они в нем уверены. Ты $gслышал:слышала;, как этот слабак Могор тявкал на тебя, словно грязная шавка? Ставки взлетели до небес!$B$BНо я в тебя верю. Сейчас ты войдешь в этот круг и по-быстрому прикончишь их хваленого бойца!','Одержите победу над Скрагатом. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.','Поединок закончится только тогда, когда один из вас упадёт замертво.','Победа над Скрагатом одержана','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо Крови: Скрагат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты сметаешь их всех, $gмалыш:красавица;! Валишь просто пачками! На следующий поединок они выставляют действительно сильного бойца. Говорят, он повелитель Бездны или как там его... В общем, они в нем уверены. Ты $gслышал:слышала;, как этот слабак Могор тявкал на тебя, словно грязная шавка? Ставки взлетели до небес!$B$BНо я в тебя верю. Сейчас ты войдешь в этот круг и по-быстрому прикончишь их хваленого бойца!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Скрагатом. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поединок закончится только тогда, когда один из вас упадёт замертво.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа над Скрагатом одержана',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9973,'Кольцо Крови: чемпион клана Боевого Молота','Им пришлось привезти этого бойца из гладиаторских ям Острогорья. Его тренировали на горных великанах – он выходил в одиночку против троих...$B$BЕсли ты выиграешь этот бой, то станешь новым чемпионом. Как ты думаешь, каковы твои шансы, $gмалыш:красавица;? Ну что, попробуешь? Скажи только слово, и я поставлю на тебя целое состояние.$B$BА теперь иди и побеждай!','Одержите победу над чемпионом клана Боевого Молота. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.','О, боги. Герой Боевого Молота Могор желает воспользоваться своим правом выйти на бой. Тебе придется сразиться с ним!$B$BИ знаешь, молотобойцы ведь не зря так зовутся.','Поединок закончится только тогда, когда один из вас упадёт замертво.','Победа над чемпионом клана Боевого Молота одержана','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо Крови: чемпион клана Боевого Молота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Им пришлось привезти этого бойца из гладиаторских ям Острогорья. Его тренировали на горных великанах – он выходил в одиночку против троих...$B$BЕсли ты выиграешь этот бой, то станешь новым чемпионом. Как ты думаешь, каковы твои шансы, $gмалыш:красавица;? Ну что, попробуешь? Скажи только слово, и я поставлю на тебя целое состояние.$B$BА теперь иди и побеждай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над чемпионом клана Боевого Молота. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О, боги. Герой Боевого Молота Могор желает воспользоваться своим правом выйти на бой. Тебе придется сразиться с ним!$B$BИ знаешь, молотобойцы ведь не зря так зовутся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поединок закончится только тогда, когда один из вас упадёт замертво.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа над чемпионом клана Боевого Молота одержана',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (9977,'Кольцо Крови: последнее испытание','Одержите победу над Могором, героем клана Боевого Молота. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.','Гаргток обещал, что ты получишь достойную награду. И он свое слово сдержит!','Поединок закончится только тогда, когда один из вас упадёт замертво.','Победа над Могором, героем Боевого Молота, одержана','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кольцо Крови: последнее испытание',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одержите победу над Могором, героем клана Боевого Молота. После битвы обратитесь к троллю-прислужнику Водину и получите свою награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гаргток обещал, что ты получишь достойную награду. И он свое слово сдержит!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поединок закончится только тогда, когда один из вас упадёт замертво.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа над Могором, героем Боевого Молота, одержана',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к троллю-прислужнику Водину на Руины Веселого Черепа, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9978,'Любыми средствами','Не знаю, что все это значит, но знаю, где нам найти еще подсказок.$B$BЕсть такой торговец – Эмпур – у него можно купить любой товар и любую информацию. Если вы сумеете его разговорить, то он наверняка скажет много интересного.$B$BОн путешествует по дороге между Тууремом и Шаттратом. Но будьте осторожны – у Эмпура есть телохранитель.','Найдите Эмпура на дороге между и Тууремом и Шаттратом в лесу Тероккар. Убедите его рассказать вам все, что ему известно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Любыми средствами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не знаю, что все это значит, но знаю, где нам найти еще подсказок.$B$BЕсть такой торговец – Эмпур – у него можно купить любой товар и любую информацию. Если вы сумеете его разговорить, то он наверняка скажет много интересного.$B$BОн путешествует по дороге между Тууремом и Шаттратом. Но будьте осторожны – у Эмпура есть телохранитель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Эмпура на дороге между и Тууремом и Шаттратом в лесу Тероккар. Убедите его рассказать вам все, что ему известно.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (9979,'Латрай Торговец Ветром','Меня попросили забрать у некоего духа Астрала несколько коробок с товарами и доставить их по назначению.$B$BПоследний раз я видел его возле таверны "На краю земли" в Нижнем Городе. Звать его Латрай Торговец Ветром, и это все, что я знаю!$B$BОб остальном расспрашивай у него!','Поговорите с Латраем Торговцем Ветром возле таверны "На краю земли" в Нижнем Городе Шаттрата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Латрай Торговец Ветром',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня попросили забрать у некоего духа Астрала несколько коробок с товарами и доставить их по назначению.$B$BПоследний раз я видел его возле таверны "На краю земли" в Нижнем Городе. Звать его Латрай Торговец Ветром, и это все, что я знаю!$B$BОб остальном расспрашивай у него!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Латраем Торговцем Ветром возле таверны "На краю земли" в Нижнем Городе Шаттрата.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9980,'Спасите Дейрома!','Как можно быстрее отправляйтесь в завесу Шалас, $n! Время не терпит. Когда араккоа прознают, что вы сделали с их защитой, они попытаются перевезти Дейрома в другое место или даже убить его!$B$BЕсли можете, возьмите с собой друга, или даже двоих – вам там придется нелегко. Эти птицелюди очень дорожат пленником, и просто так с ним не расстанутся. Когда найдете Дейрома и расправитесь с его похитителями, возвращайтесь в Бастион Аллерии и поговорите с Тандером.','Проберитесь в гнездовье Шалас, убейте Луангу и освободите Дейрома, после чего доложитесь Леди Дене Кеннеди в Бастионе Аллерии.','Вернитесь к леди Дене Кеннеди в Бастион Аллерии, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасите Дейрома!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как можно быстрее отправляйтесь в завесу Шалас, $n! Время не терпит. Когда араккоа прознают, что вы сделали с их защитой, они попытаются перевезти Дейрома в другое место или даже убить его!$B$BЕсли можете, возьмите с собой друга, или даже двоих – вам там придется нелегко. Эти птицелюди очень дорожат пленником, и просто так с ним не расстанутся. Когда найдете Дейрома и расправитесь с его похитителями, возвращайтесь в Бастион Аллерии и поговорите с Тандером.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проберитесь в гнездовье Шалас, убейте Луангу и освободите Дейрома, после чего доложитесь Леди Дене Кеннеди в Бастионе Аллерии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Дене Кеннеди в Бастион Аллерии, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (9981,'Спасите Дугара!','Как можно быстрее отправляйтесь в завесу Шалас, $n! Время не терпит. Когда араккоа прознают, что вы сделали с их защитой, они попытаются перевезти Дугара в другое место или даже убить его!$B$BЕсли можете, возьмите с собой друга, или даже двоих – вам там придется нелегко. Эти птицелюди очень дорожат пленником, и просто так с ним не расстанутся. Когда найдете Дугара и расправитесь с его похитителями, возвращайтесь в Форт Камнеломов и поговорите с Рокагом.','Проберитесь в завесу Шалас, убейте Луангу и освободите Дейрома, после чего доложитесь Рокагу в Форте Камнеломов.','Вернитесь к Рокагу в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасите Дугара!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как можно быстрее отправляйтесь в завесу Шалас, $n! Время не терпит. Когда араккоа прознают, что вы сделали с их защитой, они попытаются перевезти Дугара в другое место или даже убить его!$B$BЕсли можете, возьмите с собой друга, или даже двоих – вам там придется нелегко. Эти птицелюди очень дорожат пленником, и просто так с ним не расстанутся. Когда найдете Дугара и расправитесь с его похитителями, возвращайтесь в Форт Камнеломов и поговорите с Рокагом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проберитесь в завесу Шалас, убейте Луангу и освободите Дейрома, после чего доложитесь Рокагу в Форте Камнеломов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рокагу в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (9984,'Хозяин Сокрытого Города','Вы не можете прочитать текст свитка, но узорная печать внизу явно принадлежит некоему высокопоставленному араккоа. Даже если Луанга и руководил похищением и допросом Дейрома, приказы он принимал от кого-то еще.$B$BТандер упоминал, что Андарл изучает араккоа – возможно, он сумеет расшифровать содержимое свитка.','Отнесите приказы Луанги Андарлу в Бастион Аллерии, что в лесу Тероккар.','Я могу прочитать большую часть этого, достаточно, чтобы составить общее представление. Тот, кто написал это, хвалит "прогресс", достигнутый Луангой, и призывает продолжать допрашивать своих "гостей". $B$BМежду тем, в нем говорится, что "приготовления в Скеттисе идут по плану" и что они "скоро будут готовы вернуть свои исконные земли". $B$BЯ не знаком с этим "Скеттисом", упомянутым автором, но где бы он ни находился, похоже, что араккоа собирают там армию! Об этом нужно немедленно сообщить Тандеру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хозяин Сокрытого Города',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы не можете прочитать текст свитка, но узорная печать внизу явно принадлежит некоему высокопоставленному араккоа. Даже если Луанга и руководил похищением и допросом Дейрома, приказы он принимал от кого-то еще.$B$BТандер упоминал, что Андарл изучает араккоа – возможно, он сумеет расшифровать содержимое свитка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите приказы Луанги Андарлу в Бастион Аллерии, что в лесу Тероккар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я могу прочитать большую часть этого, достаточно, чтобы составить общее представление. Тот, кто написал это, хвалит "прогресс", достигнутый Луангой, и призывает продолжать допрашивать своих "гостей". $B$BМежду тем, в нем говорится, что "приготовления в Скеттисе идут по плану" и что они "скоро будут готовы вернуть свои исконные земли". $B$BЯ не знаком с этим "Скеттисом", упомянутым автором, но где бы он ни находился, похоже, что араккоа собирают там армию! Об этом нужно немедленно сообщить Тандеру.',`offerrewardtext_loc8`);
