INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10360,'Пожертвование – шелк','Замечательно! Благодарим Вас за щедрое пожертвование, $N!','Могу ли я добавить, что такой благотворительный подарок, как шелк, несомненно, повысит ваше положение в обществе! Если у вас есть 60 отрезов шелковой ткани и вы готовы пожертвовать их, я могу забрать их у вас прямо сейчас.','Вернитесь к Сориму Песне Света в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – шелк',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Благодарим Вас за щедрое пожертвование, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Могу ли я добавить, что такой благотворительный подарок, как шелк, несомненно, повысит ваше положение в обществе! Если у вас есть 60 отрезов шелковой ткани и вы готовы пожертвовать их, я могу забрать их у вас прямо сейчас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сориму Песне Света в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10361,'Пожертвование – магическая ткань','Замечательно! Благодарим Вас за щедрое пожертвование, $N!','Если у тебя есть 60 отрезов магической ткани, я могу принять их у тебя в качестве пожертвования.','Вернитесь к Сориму Песне Света в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – магическая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно! Благодарим Вас за щедрое пожертвование, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя есть 60 отрезов магической ткани, я могу принять их у тебя в качестве пожертвования.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сориму Песне Света в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10362,'Пожертвование – руническая ткань','Потрясающе - уверяю вас, они пригодятся. Еще раз спасибо за вашу помощь! Без Вас мы бы точно пропали.$B$BС учетом всех ваших пожертвований я обязательно обработаю любые дополнительные пожертвования из рунической ткани, которые вы захотите сделать в будущем. Только не забудьте связаться со мной, и я лично позабочусь о том, чтобы ваши добрые дела не остались незамеченными!','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.','Вернитесь к Сориму Песне Света в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пожертвование – руническая ткань',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе - уверяю вас, они пригодятся. Еще раз спасибо за вашу помощь! Без Вас мы бы точно пропали.$B$BС учетом всех ваших пожертвований я обязательно обработаю любые дополнительные пожертвования из рунической ткани, которые вы захотите сделать в будущем. Только не забудьте связаться со мной, и я лично позабочусь о том, чтобы ваши добрые дела не остались незамеченными!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты исправно снабжаешь нас тканями. На сей раз у нас случилась новая беда: запасы рунной ткани подошли к концу. Это просто ужасно, мы не знаем, что делать – не осталось ни кусочка, ни ниточки! Мы помним, что раньше могли рассчитывать на тебя, и опять просим о помощи.$B$BЕсли у тебя есть рунная ткань – пожалуйста, пожертвуй ее нам. Нужно всего-то 60 отрезов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сориму Песне Света в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10363,'Больше рунической ткани','$N, если бы такие герои, как вы, не помогали , мы бы погибли! Благодарю вас за непрестанные труды!','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.','Вернитесь к Сориму Песне Света в Леса Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше рунической ткани',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, если бы такие герои, как вы, не помогали , мы бы погибли! Благодарю вас за непрестанные труды!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Всякий раз, когда ты будешь приносить мне руническую ткань, я приму её.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сориму Песне Света в Леса Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10364,'Кадмос','Тебе удалось многого добиться за короткое время, $n. Гораздо больше, чем можно было надеяться. Пришло время продолжить обучение под руководством Кадмоса.$B$BОн уже получил вести о тебе и дожидается твоего прибытия в Экзодаре. Его можно найти в Ските анахоретов неподалеку от входа в Чертог Света.','Поговорите с Кадмосом в Чертоге Света Экзодара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кадмос',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось многого добиться за короткое время, $n. Гораздо больше, чем можно было надеяться. Пришло время продолжить обучение под руководством Кадмоса.$B$BОн уже получил вести о тебе и дожидается твоего прибытия в Экзодаре. Его можно найти в Ските анахоретов неподалеку от входа в Чертог Света.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кадмосом в Чертоге Света Экзодара.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10365,'Тебе удалось справиться лучше, чем ожидал кто-либо из нас. Манагорн Ара – последний работающий манагорн, оставшийся в распоряжении Келя. Он находится к северо-западу отсюда, хотя для того, чтобы попасть сюда тебе, наверное, лучше пойти кружным путем. Тебе необходимо выключить его.$B$BПоследний кристалл доступа находится в распоряжении у надзиратель Азарада. Насколько нам известно, это последний источник энергии Келя, так что сопротивление будет яростным. На твоем месте я взял бы с собой нескольких друзей.$B$BХмм... Азарад. Странное имя для син\'дорай.','Кель в сговоре с Пылающим Легионом? Ха! Ворен\'таль по потолку будет бегать от таких сведений.$B$BТы думаешь, тысячи паломников, собравшихся со всего Азерота, захотят союзничать с Пылающим Легионом? Я думаю, нет!','Удалось ли тебе выполнить задачу, о которой я говорил тебе, $N?','Вернитесь к патрону шпионов Талодиену в Зону 52, что в Пустоверти.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебе удалось справиться лучше, чем ожидал кто-либо из нас. Манагорн Ара – последний работающий манагорн, оставшийся в распоряжении Келя. Он находится к северо-западу отсюда, хотя для того, чтобы попасть сюда тебе, наверное, лучше пойти кружным путем. Тебе необходимо выключить его.$B$BПоследний кристалл доступа находится в распоряжении у надзиратель Азарада. Насколько нам известно, это последний источник энергии Келя, так что сопротивление будет яростным. На твоем месте я взял бы с собой нескольких друзей.$B$BХмм... Азарад. Странное имя для син\'дорай.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кель в сговоре с Пылающим Легионом? Ха! Ворен\'таль по потолку будет бегать от таких сведений.$B$BТы думаешь, тысячи паломников, собравшихся со всего Азерота, захотят союзничать с Пылающим Легионом? Я думаю, нет!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе выполнить задачу, о которой я говорил тебе, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к патрону шпионов Талодиену в Зону 52, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10366,'Джоль','Следовать путем света и чистоты нелегко. Даже мне порой случается оступиться.$b$bПоговори с моей наставницей Джоль в Экзодаре. Она помогла мне сделать первые шаги на этом пути, и я не сомневаюсь, что ты станешь ее $gлучшим учеником:лучшей ученицей;.$b$bДжоль можно отыскать в Чертоге Света Экзодара. Найди Святилище поборников – это комната, окруженная сиянием.','Поговорите с Джоль в Святилище поборников в Экзодаре.','Я давно тебя поджидаю, $n.$b$bТуллас превозносит тебя до небес, и я с радостью продолжу учить тебя пути Света. Я помогу тебе лучше разобраться в своих способностях и скрытом могуществе, когда ты будешь $gготов:готова;.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джоль',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Следовать путем света и чистоты нелегко. Даже мне порой случается оступиться.$b$bПоговори с моей наставницей Джоль в Экзодаре. Она помогла мне сделать первые шаги на этом пути, и я не сомневаюсь, что ты станешь ее $gлучшим учеником:лучшей ученицей;.$b$bДжоль можно отыскать в Чертоге Света Экзодара. Найди Святилище поборников – это комната, окруженная сиянием.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джоль в Святилище поборников в Экзодаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я давно тебя поджидаю, $n.$b$bТуллас превозносит тебя до небес, и я с радостью продолжу учить тебя пути Света. Я помогу тебе лучше разобраться в своих способностях и скрытом могуществе, когда ты будешь $gготов:готова;.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10367,'Предатель среди нас','Везде, где есть пленные Сломленные, найдется и предатель. Ничтожное создание, продавшее своих собратьев в обмен на обещание власти.$B$BСреди руин, на ступенях, примостилась его жалкая лачуга.$B$BПредателя сейчас там нет, так что ты сможешь подкрасться незаметно, если будешь $gосторожен:осторожна;. Внутри стоит сундук, в котором лежит ключ. Это ключ от цепей пленных старейшин Отребья. Принеси его мне.$B$BБудь $gосторожен:осторожна;, где-то неподалеку бродит Арзет Безжалостный.','Добудьте ключ Ша\'наара, спрятанный в лачуге в Руинах Ша\'наара неподалеку от Наладу.','Вернитесь к Наладу на Руины Ша\'наара, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предатель среди нас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Везде, где есть пленные Сломленные, найдется и предатель. Ничтожное создание, продавшее своих собратьев в обмен на обещание власти.$B$BСреди руин, на ступенях, примостилась его жалкая лачуга.$B$BПредателя сейчас там нет, так что ты сможешь подкрасться незаметно, если будешь $gосторожен:осторожна;. Внутри стоит сундук, в котором лежит ключ. Это ключ от цепей пленных старейшин Отребья. Принеси его мне.$B$BБудь $gосторожен:осторожна;, где-то неподалеку бродит Арзет Безжалостный.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте ключ Ша\'наара, спрятанный в лачуге в Руинах Ша\'наара неподалеку от Наладу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Наладу на Руины Ша\'наара, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10368,'Старейшины Отребья','Дух племени Отребья сломлен, потому что наши старейшины томятся в плену. Возьми этот ключ и ступай вниз, чтобы освободить их.$B$BИх зовут Мород Ветродув, Акору Призыватель Огня и Айлаан Пробуждающий Воду. Если они станут свободны, духи вернутся к Отребью.','Освободите Морода Ветродува, Акору Призывателя Огня и Айлаана Пробуждающего Воду. После выполнения задания возвращайтесь к Наладу.','Вернитесь к Наладу на Руины Ша\'наара, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старейшины Отребья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дух племени Отребья сломлен, потому что наши старейшины томятся в плену. Возьми этот ключ и ступай вниз, чтобы освободить их.$B$BИх зовут Мород Ветродув, Акору Призыватель Огня и Айлаан Пробуждающий Воду. Если они станут свободны, духи вернутся к Отребью.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите Морода Ветродува, Акору Призывателя Огня и Айлаана Пробуждающего Воду. После выполнения задания возвращайтесь к Наладу.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Наладу на Руины Ша\'наара, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10369,'Наследие Арзета','Да, стихии снова вернулись к нам! Это не та сила, что была когда-то, но и немного магии в умелых руках может сделать многое.$B$BАрзет обладает великой мощью, дарованной ему исчадиями преисподней. Возьми этот посох. Когда-то он был великим символом нашего племени. Если его использовать против Арзета, посох на время лишит его силы. Уничтожь Арзета и освободи мой народ!','Используйте посох старейшин племени Отребья против Арзета Безжалостного. После того как Арзет потеряет силу, убейте его. После выполнения задания возвращайтесь к Наладу в Руины Ша\'наара.','Вернитесь к Наладу на Руины Ша\'наара, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие Арзета',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, стихии снова вернулись к нам! Это не та сила, что была когда-то, но и немного магии в умелых руках может сделать многое.$B$BАрзет обладает великой мощью, дарованной ему исчадиями преисподней. Возьми этот посох. Когда-то он был великим символом нашего племени. Если его использовать против Арзета, посох на время лишит его силы. Уничтожь Арзета и освободи мой народ!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте посох старейшин племени Отребья против Арзета Безжалостного. После того как Арзет потеряет силу, убейте его. После выполнения задания возвращайтесь к Наладу в Руины Ша\'наара.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Наладу на Руины Ша\'наара, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (10370,'Приказ Назгрела <TXT>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приказ Назгрела <TXT>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10371,'Йорус Ячменовар','Воин-дворф по имени Йорус Ячменовар бросил вызов всем воинам Альянса.$B$bОн ждет в таверне Приозерья, что в Красногорье в Восточных королевствах. Путь предстоит долгий, но возможность испытать свои силы стоит того.','Поговорите с Йорусом Ячменоваром в таверне Приозерья, что в Красногорье.','Ха! Итак, ты $Gслышал:слышала; о моем вызове, не так ли?$B$BНу сядь и слушай. Выпей и насладись этим... потому что это может быть последним, что ты сделаешь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Йорус Ячменовар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воин-дворф по имени Йорус Ячменовар бросил вызов всем воинам Альянса.$B$bОн ждет в таверне Приозерья, что в Красногорье в Восточных королевствах. Путь предстоит долгий, но возможность испытать свои силы стоит того.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Йорусом Ячменоваром в таверне Приозерья, что в Красногорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Итак, ты $Gслышал:слышала; о моем вызове, не так ли?$B$BНу сядь и слушай. Выпей и насладись этим... потому что это может быть последним, что ты сделаешь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10372,'Деликатная просьба','Эраланна, моя поверенная из Транквиллиона, попросила помощи в выполнении какого-то срочного задания.$B$BНе знаю, что там у нее случилось, но думаю, что ты в любом случае справишься. Отправляйся в Транквиллион, что в Призрачных землях, и поговори с Эраланной. $B$BСлов она не выбирает, но можешь верить ей без опаски.','Поговорите с Эраланной в Транквиллионе.','Я начал задаваться вопросом, получило ли Зеланис это письмо.$B$BХороший. Давай приступим к работе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Деликатная просьба',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эраланна, моя поверенная из Транквиллиона, попросила помощи в выполнении какого-то срочного задания.$B$BНе знаю, что там у нее случилось, но думаю, что ты в любом случае справишься. Отправляйся в Транквиллион, что в Призрачных землях, и поговори с Эраланной. $B$BСлов она не выбирает, но можешь верить ей без опаски.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Эраланной в Транквиллионе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я начал задаваться вопросом, получило ли Зеланис это письмо.$B$BХороший. Давай приступим к работе.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10373,'Призыв к оружию: Чумные земли!','Слушайте все! Все герои – слушайте!$B$BКоролевство Штормграда призывает всех к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Новая опасность надвигается из руин Чумных земель!$B$BГерои королевства – собирайтесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра к северу от Альтеракских гор!','Разыщите командира Ашлама Неутомимого в Лагере Промозглого Ветра к северу от Альтеракских гор.','Добро пожаловать в Чумные земли, герой. Это одна из самых опасных границ в Азероте, особенно учитывая надвигающуюся угрозу Плети на севере и северо-востоке. Я рад слышать, что громкий призыв к долгу и служение общему благу не остался незамеченным!$B$BЕсли вы готовы запачкать руки, значит, вам есть чем заняться на краю Чумных земель.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Чумные земли!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушайте все! Все герои – слушайте!$B$BКоролевство Штормграда призывает всех к оружию! Все, кто способен держать в руках оружие, должны подняться на борьбу с проклятой Плетью! Спешите на северные границы Восточных королевств! Новая опасность надвигается из руин Чумных земель!$B$BГерои королевства – собирайтесь к командиру Ашламу Неутомимому в Лагерь Промозглого Ветра к северу от Альтеракских гор!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите командира Ашлама Неутомимого в Лагере Промозглого Ветра к северу от Альтеракских гор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Чумные земли, герой. Это одна из самых опасных границ в Азероте, особенно учитывая надвигающуюся угрозу Плети на севере и северо-востоке. Я рад слышать, что громкий призыв к долгу и служение общему благу не остался незамеченным!$B$BЕсли вы готовы запачкать руки, значит, вам есть чем заняться на краю Чумных земель.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10374,'Призыв к оружию: Чумные земли!','Внимайте моим словам, о герои! Орда призывает к решительным действиям!$b$bВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.$b$bХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лесов!','Найдите верховного палача Деррингтона. Его лагерь находится возле Бастиона, к востоку от Тирисфальских лесов и Подгорода.','Добро пожаловать в Чумные земли, герой. Это одна из самых опасных границ в Азероте, особенно учитывая надвигающуюся угрозу Плети на востоке, а оттуда еще дальше на восток. Я рад слышать, что громкий призыв к долгу и служение общему благу не остался незамеченным!$B$BЕсли вы готовы запачкать руки, значит, вам есть чем заняться на краю Чумных земель.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Чумные земли!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимайте моим словам, о герои! Орда призывает к решительным действиям!$b$bВсе, кто способен носить оружие, должны выступить в поход против Плети! Из руин Восточных королевств поднимается новая угроза! Ваш путь лежит на восток от Подгорода, в северные пределы земель, ныне известных как Чумные земли.$b$bХрабрецы, обращайтесь к верховному палачу Деррингтону. Он ждет вас в лагере у Бастиона, к востоку от Тирисфальских лесов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите верховного палача Деррингтона. Его лагерь находится возле Бастиона, к востоку от Тирисфальских лесов и Подгорода.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать в Чумные земли, герой. Это одна из самых опасных границ в Азероте, особенно учитывая надвигающуюся угрозу Плети на востоке, а оттуда еще дальше на восток. Я рад слышать, что громкий призыв к долгу и служение общему благу не остался незамеченным!$B$BЕсли вы готовы запачкать руки, значит, вам есть чем заняться на краю Чумных земель.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (10375,'Обсидиановое боевое ожерелье','Ты много $gсделал:сделала; для нашего народа и всегда $gбыл:была; для нас $gверным другом:доброй подругой;, $n. $gГотов:Готова; ли ты еще раз доказать свою преданность и выступить с нами против сильнейшего из врагов?$B$BОгры Запределья','Вернитесь к ...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обсидиановое боевое ожерелье',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты много $gсделал:сделала; для нашего народа и всегда $gбыл:была; для нас $gверным другом:доброй подругой;, $n. $gГотов:Готова; ли ты еще раз доказать свою преданность и выступить с нами против сильнейшего из врагов?$B$BОгры Запределья',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ...',`completedtext_loc8`);
