INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (10379,'Прикосновение слабости') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прикосновение слабости',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10380,'Темный пакт','Мы были столь слепы, $n, что союз между двумя нашими наиболее опасными врагами остался незамеченным. $B$BНе удивлюсь, если Провидцы имеют какое-то отношение к сокрытию от нас этих сведений, однако теперь мы должны посмотреть в лицо реальности. Пылающий Легион и армия Ярости Солнца Кель\'таса ныне выступают под одним знаменем. $B$BПрисутствие этих демонов – единственная причина, по которой Кель\'тас вообще сумел использовать эту технологию в Крепости Бурь. По приказу Орелиса я должен откомандировать тебя уничтожить их.','Кайлаан, находящийся в Лагере Тулумана в Пустоверти хочет, чтобы вы убили 6 ган\'аргов-астральных ремонтников, 3 Дочерей Судьбы и 3 мо\'аргов-мастеров искажения.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.','Значит, дело сделано. Мы приходим сюда, выслеживаем их и убиваем по приказу нашего начальства. Не давать пощады и не ждать ее.$B$BИногда это заставляет задумываться.','Вы справились со своей задачей, $N?','Вернитесь к Кайлаану в Лагерь Тулумана, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темный пакт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы были столь слепы, $n, что союз между двумя нашими наиболее опасными врагами остался незамеченным. $B$BНе удивлюсь, если Провидцы имеют какое-то отношение к сокрытию от нас этих сведений, однако теперь мы должны посмотреть в лицо реальности. Пылающий Легион и армия Ярости Солнца Кель\'таса ныне выступают под одним знаменем. $B$BПрисутствие этих демонов – единственная причина, по которой Кель\'тас вообще сумел использовать эту технологию в Крепости Бурь. По приказу Орелиса я должен откомандировать тебя уничтожить их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Кайлаан, находящийся в Лагере Тулумана в Пустоверти хочет, чтобы вы убили 6 ган\'аргов-астральных ремонтников, 3 Дочерей Судьбы и 3 мо\'аргов-мастеров искажения.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, дело сделано. Мы приходим сюда, выслеживаем их и убиваем по приказу нашего начальства. Не давать пощады и не ждать ее.$B$BИногда это заставляет задумываться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы справились со своей задачей, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайлаану в Лагерь Тулумана, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10381,'Нет больше Алдора','Моя миссия здесь завершена. Я сделал то, что приказал мне Орелис, и ни в чем его не подвел.$B$BДовольно. Я предвижу кровавую резню – они называют это не то походом, не то маршем, – которая последует за известием о союзе между Кель\'тасом и Пылающим Легионом.$B$BСначала они отдают наш священный город нашим врагам, а затем просят нас умирать в сражении против их врагов. Возвращайся к Орелису; скажи ему, что наару отныне могут сами сражаться в собственных битвах.','Вернитесь с сообщением к Экзарху Орелису в Зону 52.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.','Дурные новости, принесенные тобою, наполняют мое сердце скорбью. Два наших злейших врага объединились, а один из самых любимых сынов Шаттрата утратил свой путь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нет больше Алдора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя миссия здесь завершена. Я сделал то, что приказал мне Орелис, и ни в чем его не подвел.$B$BДовольно. Я предвижу кровавую резню – они называют это не то походом, не то маршем, – которая последует за известием о союзе между Кель\'тасом и Пылающим Легионом.$B$BСначала они отдают наш священный город нашим врагам, а затем просят нас умирать в сражении против их врагов. Возвращайся к Орелису; скажи ему, что наару отныне могут сами сражаться в собственных битвах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь с сообщением к Экзарху Орелису в Зону 52.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дурные новости, принесенные тобою, наполняют мое сердце скорбью. Два наших злейших врага объединились, а один из самых любимых сынов Шаттрата утратил свой путь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10382,'Отправка на фронт','Хорошо, $n, надеюсь, ты $gготов:готова; сделать следующий шаг. Легион не ведает отдыха, – значит, и нам нельзя расслабляться. Возьми грифона и отправляйся в Пик Чести, – это небольшой форт, расположенный рядом с Передовой Легиона. $B$BПо прибытии доложись фельдмаршалу Броку, он тебя проинструктирует, что делать дальше. Да, и передавай привет этому бледномордому щитогрызу.','Долетите до Пика Чести на грифоне и поговорите с фельдмаршалом Броком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отправка на фронт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, $n, надеюсь, ты $gготов:готова; сделать следующий шаг. Легион не ведает отдыха, – значит, и нам нельзя расслабляться. Возьми грифона и отправляйся в Пик Чести, – это небольшой форт, расположенный рядом с Передовой Легиона. $B$BПо прибытии доложись фельдмаршалу Броку, он тебя проинструктирует, что делать дальше. Да, и передавай привет этому бледномордому щитогрызу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Долетите до Пика Чести на грифоне и поговорите с фельдмаршалом Броком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10383,'Хлебные крошки!','Привет. Разберись-ка с этими кроликами.','Поговорите с Джонатаном Лекрафтом насчет кроликов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хлебные крошки!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет. Разберись-ка с этими кроликами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Джонатаном Лекрафтом насчет кроликов.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10384,'Данные Братства Эфириум','Оглянись вокруг, создание из плоти и крови. Поблизости от этого передатчика должна находиться информационная ячейка Братства Эфириум. Найди эту ячейку, открой ее и забери содержимое.$B$BЗатем немедленно возвращайся обратно к передатчику!','Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас забрать данные из информационной ячейки Эфириума.','<Ты держишь информационную ячейку так, чтобы Амир мог прочесть планы.>$B$BНичего нет... Проклятье! Они хитры, но не хитрее Амира!$B$BТо, о чем я хочу тебя попросить, очень опасно. Я пойму, если ты решишь отказаться, создание из плоти и крови...','Удалось ли тебе найти информационную ячейку?','Поговорите с проекцией командира Амира, воспользовавшись передатчиком братства Эфириум Зета на испытательном полигоне Эфириума, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Данные Братства Эфириум',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оглянись вокруг, создание из плоти и крови. Поблизости от этого передатчика должна находиться информационная ячейка Братства Эфириум. Найди эту ячейку, открой ее и забери содержимое.$B$BЗатем немедленно возвращайся обратно к передатчику!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас забрать данные из информационной ячейки Эфириума.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ты держишь информационную ячейку так, чтобы Амир мог прочесть планы.>$B$BНичего нет... Проклятье! Они хитры, но не хитрее Амира!$B$BТо, о чем я хочу тебя попросить, очень опасно. Я пойму, если ты решишь отказаться, создание из плоти и крови...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе найти информационную ячейку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с проекцией командира Амира, воспользовавшись передатчиком братства Эфириум Зета на испытательном полигоне Эфириума, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10385,'Риск поражения мозга – высокий','Они используют передающие кристаллы, чтобы обмениваться данными между полигонами.$B$BДля тебя есть только один способ увидеть эти кристаллы и извлечь хранящуюся в них информацию. К несчастью, это может привести к необратимым повреждениям мозга.$B$BЕсли ты не откажешься рискнуть, тебе нужно убить представителей Эфириума здесь, на полигоне, и забрать их сущности. Когда сущность окажется у тебя в руках, выпей ее. Это на какое-то время позволит тебе видеть ретрансляторы Эфириума – у тебя будет достаточно времени, чтобы уничтожить ретранслятор и извлечь из него данные.','Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас забрать 15 передач данных из ретранслятора Эфириума.','Теперь мы окончательно осознали причины создания Протектората.$B$BБратство Эфириума находится здесь не для того, чтобы охотиться на Пространствуса! Они намереваются стать пустотой!$B$BВ этом Манагорне они манипулируют энергией Бездны для того, чтобы соединить собственную силу в создании, известном как ловчий нексуса.$B$BОни, несомненно, используют первичный ускоритель для завершения этой трансформации.','Удалось ли тебе забрать данные из кристаллов?','Поговорите с проекцией командира Амира, воспользовавшись передатчиком братства Эфириум Зета на испытательном полигоне Эфириума, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Риск поражения мозга – высокий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они используют передающие кристаллы, чтобы обмениваться данными между полигонами.$B$BДля тебя есть только один способ увидеть эти кристаллы и извлечь хранящуюся в них информацию. К несчастью, это может привести к необратимым повреждениям мозга.$B$BЕсли ты не откажешься рискнуть, тебе нужно убить представителей Эфириума здесь, на полигоне, и забрать их сущности. Когда сущность окажется у тебя в руках, выпей ее. Это на какое-то время позволит тебе видеть ретрансляторы Эфириума – у тебя будет достаточно времени, чтобы уничтожить ретранслятор и извлечь из него данные.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас забрать 15 передач данных из ретранслятора Эфириума.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь мы окончательно осознали причины создания Протектората.$B$BБратство Эфириума находится здесь не для того, чтобы охотиться на Пространствуса! Они намереваются стать пустотой!$B$BВ этом Манагорне они манипулируют энергией Бездны для того, чтобы соединить собственную силу в создании, известном как ловчий нексуса.$B$BОни, несомненно, используют первичный ускоритель для завершения этой трансформации.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе забрать данные из кристаллов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с проекцией командира Амира, воспользовавшись передатчиком братства Эфириум Зета на испытательном полигоне Эфириума, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10386,'Гроза скверноботов','Властитель Хан Изувер славится своими безумными атаками на Легион, и ему всегда нужны добровольцы. Опредленно, ты ему подходишь.$B$BЕсли считаешь, что у тебя хватит выдержки и безрассудства, пойди и поговори с ним. Он пьет с друзьями вон там, рядом с разбитым скверноботом. Они завалили его всего несколько часов назад. Скажу честно, если бы не Хан, мы все бы здесь полегли.','Поговорите с властителем Ханом Изуверским Кулаком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гроза скверноботов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Властитель Хан Изувер славится своими безумными атаками на Легион, и ему всегда нужны добровольцы. Опредленно, ты ему подходишь.$B$BЕсли считаешь, что у тебя хватит выдержки и безрассудства, пойди и поговори с ним. Он пьет с друзьями вон там, рядом с разбитым скверноботом. Они завалили его всего несколько часов назад. Скажу честно, если бы не Хан, мы все бы здесь полегли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с властителем Ханом Изуверским Кулаком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10387,'Гроза скверноботов','Властитель Хан Изувер славится своими безумными атаками на Легион, и ему всегда нужны добровольцы. Опредленно, ты ему подходишь.$B$BЕсли считаешь, что у тебя хватит выдержки и безрассудства, пойди и поговори с ним. Он пьет с друзьями вон там, рядом с разбитым скверноботом. Они завалили его всего несколько часов назад. Скажу честно, если бы не Хан, мы все бы здесь полегли.','Поговорите с властителем Ханом Изуверским Кулаком.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гроза скверноботов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Властитель Хан Изувер славится своими безумными атаками на Легион, и ему всегда нужны добровольцы. Опредленно, ты ему подходишь.$B$BЕсли считаешь, что у тебя хватит выдержки и безрассудства, пойди и поговори с ним. Он пьет с друзьями вон там, рядом с разбитым скверноботом. Они завалили его всего несколько часов назад. Скажу честно, если бы не Хан, мы все бы здесь полегли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с властителем Ханом Изуверским Кулаком.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10388,'Назад в Траллмар','Надеюсь, полет тебе понравился, $gприятель:подруга;. Пока тебя не было, прибыл посланник – кажется, Назгрел нашел для тебя новую работу. Лучше тебе вернуться обратно в Траллмар и доложиться ему лично. Есть у меня подозрение, что Легион снова что-то затевает.','Возвращайтесь в Траллмар и поговорите с Назгрелом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад в Траллмар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надеюсь, полет тебе понравился, $gприятель:подруга;. Пока тебя не было, прибыл посланник – кажется, Назгрел нашел для тебя новую работу. Лучше тебе вернуться обратно в Траллмар и доложиться ему лично. Есть у меня подозрение, что Легион снова что-то затевает.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь в Траллмар и поговорите с Назгрелом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10389,'Тьма и агония','Приветствую, $n. Мне удалось перехватить шифрованное послание Легиона. В нем говорилось, что Легион собирает отряды исчадий Ужаса на западе, рядом с Прудами Аггонара. Нам нельзя оставаться в бездействии, зная, что враг стягивает силы. Ты $gдолжен:должна; отправиться туда и уничтожить их.','Убейте 10 исчадий Ужаса у прудов Аггонара по приказу магистра Кровавого Ястреба.','Ну, $C, как там поживают исчадия Ужаса?','Вернитесь к магистру Кровавому Ястребу в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тьма и агония',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, $n. Мне удалось перехватить шифрованное послание Легиона. В нем говорилось, что Легион собирает отряды исчадий Ужаса на западе, рядом с Прудами Аггонара. Нам нельзя оставаться в бездействии, зная, что враг стягивает силы. Ты $gдолжен:должна; отправиться туда и уничтожить их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 исчадий Ужаса у прудов Аггонара по приказу магистра Кровавого Ястреба.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, $C, как там поживают исчадия Ужаса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Кровавому Ястребу в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (10390,'Лагерь Легиона: Магеддон','Вернитесь к Назгрелу в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь Легиона: Магеддон',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Назгрелу в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10391,'Пушки Ярости','Легион может начать обстрел нас в любой момент, $N! Тебе нужно уничтожить эти пушки!','Вернитесь к Назгрелу в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пушки Ярости',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Легион может начать обстрел нас в любой момент, $N! Тебе нужно уничтожить эти пушки!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Назгрелу в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10392,'Дверь в Бездну','Для нас честь знать тебя, $n. Мы должны нанести новый удар, пока Легион не оправился от предыдущего! К северу от Траллмара лежит Точка вторжения: Аннигилятор. Там находится искажающий портал, по которому Легион получает подкрепление.$B$BТебе нужно перегрузить этот портал так, чтобы он отправился обратно в бездну, которая его породила. Ключ активации портала находится у Завоевателя Арикс\'Амала. Уничтожь его. Забери ключ. Открой им портал и сделай, что должно. Да пребудет с тобой благословение Вождя!','Убейте Арикс\'Амала и заберите ключ врат Пылающего Легиона. Используйте ключ на Руне Злобы и возвращайтесь к Назгрелу в Траллмар.','Вернитесь к Назгрелу в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дверь в Бездну',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для нас честь знать тебя, $n. Мы должны нанести новый удар, пока Легион не оправился от предыдущего! К северу от Траллмара лежит Точка вторжения: Аннигилятор. Там находится искажающий портал, по которому Легион получает подкрепление.$B$BТебе нужно перегрузить этот портал так, чтобы он отправился обратно в бездну, которая его породила. Ключ активации портала находится у Завоевателя Арикс\'Амала. Уничтожь его. Забери ключ. Открой им портал и сделай, что должно. Да пребудет с тобой благословение Вождя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Арикс\'Амала и заберите ключ врат Пылающего Легиона. Используйте ключ на Руне Злобы и возвращайтесь к Назгрелу в Траллмар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Назгрелу в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10393,'Коварные планы','Текст, судя по всему, написан на каком-то странном языке, неразборчивым и спутанным почерком. Чем больше вы на него смотрите, тем труднее что-нибудь разобрать, и в конце концов буквы начинают прыгать перед глазами. Похоже, понять этот странный почерк сможет одно существо в Траллмаре – эльф крови магистр Кровавый Ястреб.','Доставьте послание Пылающего Легиона магистру Кровавому Ястребу в Траллмар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коварные планы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Текст, судя по всему, написан на каком-то странном языке, неразборчивым и спутанным почерком. Чем больше вы на него смотрите, тем труднее что-нибудь разобрать, и в конце концов буквы начинают прыгать перед глазами. Похоже, понять этот странный почерк сможет одно существо в Траллмаре – эльф крови магистр Кровавый Ястреб.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте послание Пылающего Легиона магистру Кровавому Ястребу в Траллмар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10394,'Убейте 10 ган\'аргов-прислужников и Остропила. После выполнения задания возвращайтесь к передовому командиру Броку на Пик Чести.','Только не говори мне, что ты трусишь, |3-6($c). Если они закончат строительство Лагеря Легиона, то придется бояться еще и скверноботов. Ступай и выполняй приказ!','Вернитесь к фельдмаршалу Броку на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 ган\'аргов-прислужников и Остропила. После выполнения задания возвращайтесь к передовому командиру Броку на Пик Чести.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Только не говори мне, что ты трусишь, |3-6($c). Если они закончат строительство Лагеря Легиона, то придется бояться еще и скверноботов. Ступай и выполняй приказ!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фельдмаршалу Броку на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (10395,'Темное послание','Текст, судя по всему, написан на каком-то странном языке, неразборчивым и спутанным почерком. Чем больше вы на него смотрите, тем труднее что-нибудь разобрать, и в конце концов буквы начинают прыгать перед глазами. Похоже, понять этот странный почерк сможет одно существо в Оплоте Чести – дренайский провидец бед Крив.','Доставьте послание Пылающего Легиона провидцу бед Криву в главную крепость Оплота Чести.','Что случилось, |3-6($c)? Я чувствую, ты $gпринес:принесла; послание надвигающегося рока.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Темное послание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Текст, судя по всему, написан на каком-то странном языке, неразборчивым и спутанным почерком. Чем больше вы на него смотрите, тем труднее что-нибудь разобрать, и в конце концов буквы начинают прыгать перед глазами. Похоже, понять этот странный почерк сможет одно существо в Оплоте Чести – дренайский провидец бед Крив.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте послание Пылающего Легиона провидцу бед Криву в главную крепость Оплота Чести.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что случилось, |3-6($c)? Я чувствую, ты $gпринес:принесла; послание надвигающегося рока.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (10396,'Враг моего врага...','Вернитесь к фельдмаршалу Броку на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враг моего врага...',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фельдмаршалу Броку на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10397,'Точка вторжения: Аннигилятор','Уничтожьте Арикс\'Амала. Заберите ключ врат пылающего Легиона. Примените ключ на Руне Злобы.','Вернитесь к фельдмаршалу Броку на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Точка вторжения: Аннигилятор',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Арикс\'Амала. Заберите ключ врат пылающего Легиона. Примените ключ на Руне Злобы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фельдмаршалу Броку на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10399,'Сердце тьмы','Убейте 10 исчадий ужаса у прудов Аггонара и возвращайтесь к провидцу бед Криву в главную крепость Оплота Чести.','Я чувствую, в твоем сердце поселилась тьма, |3-6($c). Ты $gвстретил:встретила; свой страх лицом к лицу? Или он все еще ожидает тебя у прудов Аггонара?','Вернитесь к провидцу бед Криву в Оплот Чести, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце тьмы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 исчадий ужаса у прудов Аггонара и возвращайтесь к провидцу бед Криву в главную крепость Оплота Чести.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую, в твоем сердце поселилась тьма, |3-6($c). Ты $gвстретил:встретила; свой страх лицом к лицу? Или он все еще ожидает тебя у прудов Аггонара?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провидцу бед Криву в Оплот Чести, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (10402,'<TXT>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<TXT>',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10403,'Наладу','Возможно, не вся надежда еще потеряна для Отребья. Я один из четырех старейшин, которые возглавляли племя, пока нас не поработили Иллидари. Я думал, что все остальные мертвы, но мне удалось узнать, что живы по крайней мере двое из них. Они находятся в плену и лишены сил, так же, как и я сам.$B$BНо я не могу найти Наладу и опасаюсь самого худшего. Наверху, в руинах, много лачуг. Может быть, в одной из них ты разыщешь его. Если бы все четверо старейшин оказались живы, это было бы великим благом для нашего племени.','Отыщите Наладу в Руинах Ша\'наара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наладу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, не вся надежда еще потеряна для Отребья. Я один из четырех старейшин, которые возглавляли племя, пока нас не поработили Иллидари. Я думал, что все остальные мертвы, но мне удалось узнать, что живы по крайней мере двое из них. Они находятся в плену и лишены сил, так же, как и я сам.$B$BНо я не могу найти Наладу и опасаюсь самого худшего. Наверху, в руинах, много лачуг. Может быть, в одной из них ты разыщешь его. Если бы все четверо старейшин оказались живы, это было бы великим благом для нашего племени.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Наладу в Руинах Ша\'наара.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10404,'Против Легиона','Мы установили, что Пылающий Легион снабжал Кель\'таса помощью в области технологии, во много раз усилив опасность, представляемую его армией.$B$BСогласно количеству представителей Легиона в округе, самый большой удар, который мы можем нанести по нашим врагам – это прямая атака на кузнечные базы на севере.$B$BОтправляйся к кузнечной базе "Забвение" и кузнечной базе "Геенна" и уничтожь наших врагов. Пусть Свет ведет твой клинок, $n.','Экзарх Орелис, находящийся в Зоне 52, просит вас отправиться к кузнечной базе "Забвение" и кузнечной базе "Геенна" и убить 12 ган\'аргов-работников кузни, 6 мо\'аргов-начальников кузни и 6 вестников зла. $B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.','Вы нанесли могучий удар по врагам Света, $N. Вам моя благодарность, а также благодарность Алдоров.','Вернитесь к экзарху Орелису.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Против Легиона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы установили, что Пылающий Легион снабжал Кель\'таса помощью в области технологии, во много раз усилив опасность, представляемую его армией.$B$BСогласно количеству представителей Легиона в округе, самый большой удар, который мы можем нанести по нашим врагам – это прямая атака на кузнечные базы на севере.$B$BОтправляйся к кузнечной базе "Забвение" и кузнечной базе "Геенна" и уничтожь наших врагов. Пусть Свет ведет твой клинок, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Экзарх Орелис, находящийся в Зоне 52, просит вас отправиться к кузнечной базе "Забвение" и кузнечной базе "Геенна" и убить 12 ган\'аргов-работников кузни, 6 мо\'аргов-начальников кузни и 6 вестников зла. $B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы нанесли могучий удар по врагам Света, $N. Вам моя благодарность, а также благодарность Алдоров.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к экзарху Орелису.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10405,'С-А-Б-О-Т-А-Ж','Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас добыть 1 комплект готовых обмоток Эфириума.','Превосходно! Теперь можно откалибровать устройство.','Удалось ли тебе раздобыть обмотки?','Поговорите с проекцией командира Амира, воспользовавшись передатчиком братства Эфириум Зета на испытательном полигоне Эфириума, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С-А-Б-О-Т-А-Ж',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас добыть 1 комплект готовых обмоток Эфириума.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Теперь можно откалибровать устройство.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе раздобыть обмотки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с проекцией командира Амира, воспользовавшись передатчиком братства Эфириум Зета на испытательном полигоне Эфириума, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10406,'Передать послание','Я высылаю одного из своих уничтожителей, чтобы он разместил разрушающее устройство. Необходимо, чтобы никто не причинил ему вреда, пока он устанавливает агрегат.$B$BВозьми его под защиту! Если на него нападут, он не сможет сражаться, поскольку он – всего лишь голографическая проекция, но эту проекцию можно уничтожить!$B$BВозвращайся ко мне, как только работа будет выполнена.','Благодаря тебе их планы рухнули! Теперь осталось только одно... Салхадаар.','Он должен достичь цели!','Диверсия на трубопроводе прошла успешно','Поговорите с проекцией командира Амира, воспользовавшись передатчиком братства Эфириум Зета на испытательном полигоне Эфириума, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Передать послание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я высылаю одного из своих уничтожителей, чтобы он разместил разрушающее устройство. Необходимо, чтобы никто не причинил ему вреда, пока он устанавливает агрегат.$B$BВозьми его под защиту! Если на него нападут, он не сможет сражаться, поскольку он – всего лишь голографическая проекция, но эту проекцию можно уничтожить!$B$BВозвращайся ко мне, как только работа будет выполнена.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодаря тебе их планы рухнули! Теперь осталось только одно... Салхадаар.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он должен достичь цели!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Диверсия на трубопроводе прошла успешно',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с проекцией командира Амира, воспользовавшись передатчиком братства Эфириум Зета на испытательном полигоне Эфириума, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10407,'Тень Сокретара','Известный своими злобными деяниями эредар Сокретар возглавляет Пылающий Легион в Пустоверти. Одного упоминания его имени достаточно, чтобы заставить многих дренеев вздрогнуть. Он отдает приказы, сидя на острове к северо-западу отсюда. Только самые его доверенные лейтенанты могут попасть на этот остров.$B$BЧтобы добраться дотуда, мы должны заполучить камень телепортации, а это само по себе нелегкая задача. Первая половина камня находится у начальника кузни Моруга на кузнечной базе "Забвение". Вторую половину хранит демон Силрот на кузнечной базе "Геенна".','Твоя преданность нашему делу просто невероятна, $N. Теперь, когда у нас есть камень телепортации Сокретара, осталось сделать еще только одно.','Удалось ли тебе добыть камень телепортации Сокретара, $N?','Вернитесь к анахорету Карже в Зону 52, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тень Сокретара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Известный своими злобными деяниями эредар Сокретар возглавляет Пылающий Легион в Пустоверти. Одного упоминания его имени достаточно, чтобы заставить многих дренеев вздрогнуть. Он отдает приказы, сидя на острове к северо-западу отсюда. Только самые его доверенные лейтенанты могут попасть на этот остров.$B$BЧтобы добраться дотуда, мы должны заполучить камень телепортации, а это само по себе нелегкая задача. Первая половина камня находится у начальника кузни Моруга на кузнечной базе "Забвение". Вторую половину хранит демон Силрот на кузнечной базе "Геенна".',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя преданность нашему делу просто невероятна, $N. Теперь, когда у нас есть камень телепортации Сокретара, осталось сделать еще только одно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе добыть камень телепортации Сокретара, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Карже в Зону 52, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10408,'Соправитель Салхадаар','У меня есть еще один дезинтегратор, способный уничтожить три контура, окружающие Салхадаара. Когда контуры будут уничтожены, защитное поле Салхадаара отключится. Однако за это он обрушит на тебя столь яростный удар, которого даже тебе, $n, прежде не приходилось испытывать.$B$BНо если ты желаешь избавить мир от Салхадаара, я отдам тебе дезинтегратор.','Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас использовать дезинтегратор Протектората, чтобы отключить защитное поле Салхадаара, а затем уничтожить Соправителя Салхадаара.','Он... он действительно мертв? Уничтожен?','Поговорите с проекцией командира Амира, воспользовавшись передатчиком братства Эфириум Зета на испытательном полигоне Эфириума, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Соправитель Салхадаар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть еще один дезинтегратор, способный уничтожить три контура, окружающие Салхадаара. Когда контуры будут уничтожены, защитное поле Салхадаара отключится. Однако за это он обрушит на тебя столь яростный удар, которого даже тебе, $n, прежде не приходилось испытывать.$B$BНо если ты желаешь избавить мир от Салхадаара, я отдам тебе дезинтегратор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проекция командира Амира на полигоне Эфириума – передатчик Эфириума Зета – просит вас использовать дезинтегратор Протектората, чтобы отключить защитное поле Салхадаара, а затем уничтожить Соправителя Салхадаара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он... он действительно мертв? Уничтожен?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с проекцией командира Амира, воспользовавшись передатчиком братства Эфириум Зета на испытательном полигоне Эфириума, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10409,'Удар по Легиону','При столкновении с эредаром, наделенным великой мощью, большие армии чаще всего оказываются бесполезны. Влияние скверны на смертные души так велико, что только самые сильные волей существа могут противостоять ему. $B$BОтнеси этот камень на Точку вторжения "Властитель" между кузнечными базами "Забвение" и "Геенна"; возьми с собой самых близких и надежных друзей. Орелис и Каржа встретят тебя у Трона Сокретара. Я пошлю с ними Адуина.$B$BДа победит сегодня Свет, $n. Да встретит Сокретар свою смерть!','Верховная жрица Ишана просит вас отправиться к телепорту Легиона в северо-западной части Пустоверти и использовать его, чтобы переместиться к Трону Сокретара.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.','Дело сделано, $N. Сокретар уничтожен.$B$BМои раны и раны всех остальных исцелятся, $N. Однако злобная магия Сокретара оказалась слишком сильна для юного Кайлаана. Даже самые отчаянные мои молитвы не смогут воскресить его.$B$BКак невыносимо жаль, что таким юным приходится умирать в бою. Однако в конце концов его воля оказалась достаточно сильна, чтобы очиститься от скверны Легиона. Быть может, мы сумеем найти в этом утешение.','Свет с тобой, $C.','Удар по Легиону','Поговорите с Ишаной на ярусе Алдоров, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар по Легиону',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При столкновении с эредаром, наделенным великой мощью, большие армии чаще всего оказываются бесполезны. Влияние скверны на смертные души так велико, что только самые сильные волей существа могут противостоять ему. $B$BОтнеси этот камень на Точку вторжения "Властитель" между кузнечными базами "Забвение" и "Геенна"; возьми с собой самых близких и надежных друзей. Орелис и Каржа встретят тебя у Трона Сокретара. Я пошлю с ними Адуина.$B$BДа победит сегодня Свет, $n. Да встретит Сокретар свою смерть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховная жрица Ишана просит вас отправиться к телепорту Легиона в северо-западной части Пустоверти и использовать его, чтобы переместиться к Трону Сокретара.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дело сделано, $N. Сокретар уничтожен.$B$BМои раны и раны всех остальных исцелятся, $N. Однако злобная магия Сокретара оказалась слишком сильна для юного Кайлаана. Даже самые отчаянные мои молитвы не смогут воскресить его.$B$BКак невыносимо жаль, что таким юным приходится умирать в бою. Однако в конце концов его воля оказалась достаточно сильна, чтобы очиститься от скверны Легиона. Быть может, мы сумеем найти в этом утешение.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Свет с тобой, $C.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Удар по Легиону',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Ишаной на ярусе Алдоров, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (10410,'Помощь Ишаны','Пришло время для прямого столкновения с Сокретаром, $n. Однако к противостоянию предводителю эредаров мы относимся всерьез. Если мы не подготовимся как следует, одна ошибка будет стоить нам жизни. $B$BОтнеси камень телепортации Сокретара верховной жрице Ишане в Святилище Вечного Света в городе Шаттрат.Она определит, как нам лучше действовать в этой ситуации.','Отнесите камень телепортации Сокретара верховной жрице Ишане в Святилище Вечного Света на Возвышенности Алдоров в городе Шаттрат. $B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.','Сокретар... я помню это имя. Когда-то он был достойным воином Света, и единственным его изъяном была гордость.','Что тревожит тебя, дитя?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Ишаны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время для прямого столкновения с Сокретаром, $n. Однако к противостоянию предводителю эредаров мы относимся всерьез. Если мы не подготовимся как следует, одна ошибка будет стоить нам жизни. $B$BОтнеси камень телепортации Сокретара верховной жрице Ишане в Святилище Вечного Света в городе Шаттрат.Она определит, как нам лучше действовать в этой ситуации.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите камень телепортации Сокретара верховной жрице Ишане в Святилище Вечного Света на Возвышенности Алдоров в городе Шаттрат. $B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сокретар... я помню это имя. Когда-то он был достойным воином Света, и единственным его изъяном была гордость.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тревожит тебя, дитя?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10411,'Слава электрошоку!','Вокруг разрушенного манагорна ты увидишь последствия действий Пространствуса. Сочащиеся слякочи наполняют пруды, окружающие Ультрис. Прямо под этими прудами, где сейчас размещается полигон Эфириума, ты найдешь еще больше утечек – то есть отбросы Бездны.$B$BЛучший способ избавиться от этого – использовать электрошок, чтобы разбить слизнюков на капли. Используй этот эликсир, чтобы снабдить свои атаки электричеством. Получившийся в результате разряд переведет слизнюков в более примитивную форму каплей. Уничтожь эти капли!','Ученый Навууд, находящийся на заставе стражей Протектората в Пустоверти просит вас уничтожить 30 каплей отброса Бездны и 30 сочащихся каплей слякоча.','Вернитесь к ученому Навууду на Заставу Стражей Протектората, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слава электрошоку!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вокруг разрушенного манагорна ты увидишь последствия действий Пространствуса. Сочащиеся слякочи наполняют пруды, окружающие Ультрис. Прямо под этими прудами, где сейчас размещается полигон Эфириума, ты найдешь еще больше утечек – то есть отбросы Бездны.$B$BЛучший способ избавиться от этого – использовать электрошок, чтобы разбить слизнюков на капли. Используй этот эликсир, чтобы снабдить свои атаки электричеством. Получившийся в результате разряд переведет слизнюков в более примитивную форму каплей. Уничтожь эти капли!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ученый Навууд, находящийся на заставе стражей Протектората в Пустоверти просит вас уничтожить 30 каплей отброса Бездны и 30 сочащихся каплей слякоча.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученому Навууду на Заставу Стражей Протектората, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10412,'Перстни Огнекрылов','Не секрет, что Кель\'тас Солнечный Скиталец видит в нас большую угрозу. И вообще-то он прав: мало кто из син\'дорай, только что прибывших из Луносвета, готов присоединиться к тем, с кем принц водит компанию.$B$BТакже не секрет и то, что война эта ведется не только на словах. Провидцы и армии Кель\'таса бросаются в атаку, едва завидев друг друга. Если вы действительно решили принять нашу сторону, $n, докажите это – примите участие в войне.$B$BНизшие офицеры Кель\'таса носят перстни Огнекрылов – принесите их мне.','Принесите магистру Файленн 10 перстней Огнекрылов.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.','Хорошая работа, $N. Возможно, вы и впрямь сможете оказаться нам $Gполезным:полезной;.','Ну же, $N. Говорите.','Вернитесь к магистру Файленн в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перстни Огнекрылов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не секрет, что Кель\'тас Солнечный Скиталец видит в нас большую угрозу. И вообще-то он прав: мало кто из син\'дорай, только что прибывших из Луносвета, готов присоединиться к тем, с кем принц водит компанию.$B$BТакже не секрет и то, что война эта ведется не только на словах. Провидцы и армии Кель\'таса бросаются в атаку, едва завидев друг друга. Если вы действительно решили принять нашу сторону, $n, докажите это – примите участие в войне.$B$BНизшие офицеры Кель\'таса носят перстни Огнекрылов – принесите их мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите магистру Файленн 10 перстней Огнекрылов.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $N. Возможно, вы и впрямь сможете оказаться нам $Gполезным:полезной;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну же, $N. Говорите.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Файленн в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10413,'Ужасы загрязнения','Ты осторожно наполняешь фиал ужасной слизью павшего ужаса Бездны.$B$BИсследователь Навууд на заставе стражей Протектората будет весьма заинтересован в такой находке! Немедленно доставь это к нему!','Отнесите фиал со слизью ужаса Бездны к ученому Навууду на заставу стражей Протектората в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ужасы загрязнения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты осторожно наполняешь фиал ужасной слизью павшего ужаса Бездны.$B$BИсследователь Навууд на заставе стражей Протектората будет весьма заинтересован в такой находке! Немедленно доставь это к нему!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите фиал со слизью ужаса Бездны к ученому Навууду на заставу стражей Протектората в Пустоверти.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10414,'Перстень Огнекрылов','Даже самая маленькая помощь нашему делу не останется незамеченной, $N. Армия врага велика, но победа будет за нами!','Вернитесь к магистру Файленн в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перстень Огнекрылов',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Даже самая маленькая помощь нашему делу не останется незамеченной, $N. Армия врага велика, но победа будет за нами!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Файленн в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10415,'Больше перстней Огнекрылов','Прекрасно! Пусть все наши враги исчезнут!$B$B<Это задание можно повторять до тех пор, пока вы не заслужите уважительное отношение.>','Что вы сделали для нас в последнее время, $N? Война против Кель\'таса не продолжится сама по себе!','Вернитесь к магистру Файленн в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше перстней Огнекрылов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Пусть все наши враги исчезнут!$B$B<Это задание можно повторять до тех пор, пока вы не заслужите уважительное отношение.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что вы сделали для нас в последнее время, $N? Война против Кель\'таса не продолжится сама по себе!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Файленн в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10416,'Преобразование силы','Чародейские фолианты – это вам не просто книжки про магию. В них содержится большая сила, и я научился сосредотачивать ее в одной-единственной чародейской руне.$B$BЕсли вам попадется чародейский фолиант, то я с радостью обменяю его на такую руну, но фолианты бывают только у очень могущественных существ. В Запределье ими обычно владеют эльфы крови, последователи Келя, но вообще эти книги могут попасться где угодно.','Принесите чародейский фолиант Ворен\'талю Провидцу в Шаттрат.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.','Вот, $N, как и обещал: вся сила книги, заключенная в одну руну.','А, $N! Как идут поиски чародейского фолианта?','Вернитесь к Ворен\'талю Провидцу в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Преобразование силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чародейские фолианты – это вам не просто книжки про магию. В них содержится большая сила, и я научился сосредотачивать ее в одной-единственной чародейской руне.$B$BЕсли вам попадется чародейский фолиант, то я с радостью обменяю его на такую руну, но фолианты бывают только у очень могущественных существ. В Запределье ими обычно владеют эльфы крови, последователи Келя, но вообще эти книги могут попасться где угодно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите чародейский фолиант Ворен\'талю Провидцу в Шаттрат.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот, $N, как и обещал: вся сила книги, заключенная в одну руну.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, $N! Как идут поиски чародейского фолианта?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ворен\'талю Провидцу в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10417,'Провести диагностику','Где бы Консорциум ни заявил о своем присутствии, мы приходим туда со своей технологией экосфер. Защитное поле позволяет нам работать в тщательно контролируемой благоприятной атмосфере, поскольку окружающая среда часто бывает враждебной. $B$BСуровые условия Пустоверти и обитающие здесь существа причиняют вред оборудованию, генерирующему наши сферы; в особенности пострадал генератор, находящийся к востоку отсюда. Я запустил там диагностику, надеясь понять, что можно сделать, дабы уменьшить ущерб. Не можешь ли ты снять показатели диагностики и доставить их мне?','Заберите результаты диагностики и доставьте их Мердаду на Заставу срединных земель.','Удалось ли тебе снять результаты диагностики?','Вернитесь к Мердаду в Заповедник "Срединные земли", что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Провести диагностику',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Где бы Консорциум ни заявил о своем присутствии, мы приходим туда со своей технологией экосфер. Защитное поле позволяет нам работать в тщательно контролируемой благоприятной атмосфере, поскольку окружающая среда часто бывает враждебной. $B$BСуровые условия Пустоверти и обитающие здесь существа причиняют вред оборудованию, генерирующему наши сферы; в особенности пострадал генератор, находящийся к востоку отсюда. Я запустил там диагностику, надеясь понять, что можно сделать, дабы уменьшить ущерб. Не можешь ли ты снять показатели диагностики и доставить их мне?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите результаты диагностики и доставьте их Мердаду на Заставу срединных земель.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе снять результаты диагностики?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мердаду в Заповедник "Срединные земли", что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10418,'Покончить с вредителями','Обыскивая район в поисках того, что причинило такой ущерб нашему оборудованию, я заметил детали генератора защитного поля на дне маленького озера к северу отсюда. Не знаю, почему кроколисков так заинтересовало оборудование, но мы должны устранить эту проблему.$B$BМнение Консорциума по этому вопросу ясно. Если дело доходит до выбора между оборудованием и кроколисками, животным придется уступить. Думаю, ты не откажешься взяться за это дело.','Мердад, находящийся на Заставе срединных земель, просит вас убить 8 шипастых кроколисков.','Этот район уже выглядит более чисто. Эти сферы довольно полезны, но у них есть недостатки – они ускоряют рост некоторых местных видов животных и растений.','Вы избавили этих существ от страданий? Не поймите меня неправильно, я действительно любитель животных, но не тогда, когда животные кусают руку, которая их кормит и укрывает.','Вернитесь к Мердаду в Заповедник "Срединные земли", что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покончить с вредителями',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обыскивая район в поисках того, что причинило такой ущерб нашему оборудованию, я заметил детали генератора защитного поля на дне маленького озера к северу отсюда. Не знаю, почему кроколисков так заинтересовало оборудование, но мы должны устранить эту проблему.$B$BМнение Консорциума по этому вопросу ясно. Если дело доходит до выбора между оборудованием и кроколисками, животным придется уступить. Думаю, ты не откажешься взяться за это дело.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мердад, находящийся на Заставе срединных земель, просит вас убить 8 шипастых кроколисков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот район уже выглядит более чисто. Эти сферы довольно полезны, но у них есть недостатки – они ускоряют рост некоторых местных видов животных и растений.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы избавили этих существ от страданий? Не поймите меня неправильно, я действительно любитель животных, но не тогда, когда животные кусают руку, которая их кормит и укрывает.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мердаду в Заповедник "Срединные земли", что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10419,'Чародейские фолианты','Этот фолиант наделен потрясающей силой! Однако тот, чей разум ясен, сумеет без труда заключить ее в одну руну.','Вернитесь к Ворен\'талю Провидцу в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чародейские фолианты',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот фолиант наделен потрясающей силой! Однако тот, чей разум ясен, сумеет без труда заключить ее в одну руну.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ворен\'талю Провидцу в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10420,'Очищающий Свет','Этот храм – одно из самых священных мест в Запределье. Сила Света здесь настолько велика, что может очистить предметы, сильнее других пострадавшие от Скверны.$B$BЕсли тебе попадутся латные перчатки Скверны, – а это наверняка произойдет после нескольких схваток с демонами, – принеси их мне, и я продемонстрирую тебе всю очищающую силу Света.','Принесите латные перчатки Скверны Ишане в Шаттрат.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.','Смотри, как распадаются оскверненные материалы. Смотри, как металл обращается в пыль.$B$BСвет очищает все, оставляя лишь чистейший осадок.','Вернитесь к Ишане на Возвышенность Алдоров, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищающий Свет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот храм – одно из самых священных мест в Запределье. Сила Света здесь настолько велика, что может очистить предметы, сильнее других пострадавшие от Скверны.$B$BЕсли тебе попадутся латные перчатки Скверны, – а это наверняка произойдет после нескольких схваток с демонами, – принеси их мне, и я продемонстрирую тебе всю очищающую силу Света.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите латные перчатки Скверны Ишане в Шаттрат.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Смотри, как распадаются оскверненные материалы. Смотри, как металл обращается в пыль.$B$BСвет очищает все, оставляя лишь чистейший осадок.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ишане на Возвышенность Алдоров, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10421,'Латные перчатки Скверны','Скверна изгнана из этого мира, остался лишь чистый светлый осадок.','Не попадались ли вам в последнее время латные перчатки Скверны? Нельзя оставлять эти оскверненные вещи в нашем мире, $N. Нужно очистить их.','Вернитесь к Ишане.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Латные перчатки Скверны',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Скверна изгнана из этого мира, остался лишь чистый светлый осадок.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не попадались ли вам в последнее время латные перчатки Скверны? Нельзя оставлять эти оскверненные вещи в нашем мире, $N. Нужно очистить их.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ишане.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (10422,'Капитан Тиралиус','10 дней назад капитан Тиралиус повел взвод солдат на юг, к полигону Эфириума. С тех пор мы ничего не слышали ни о нем, ни о его подчиненных.$B$BВероятнее всего, они попали в засаду и были убиты, однако мои приборы выдают любопытные показания.$B$BМне кажется, это сигнал бедствия, однако эти штуки и прежде ошибались. Если Тиралиус еще жив, они держат его в одной из тюрем. Тебе нужно отыскать эту тюрьму и открыть ее ключом, который, вероятнее всего, находится у стражника.','Вернитесь к укротителю плоти Виридиусу на Заставу Стражей Протектората, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Капитан Тиралиус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','10 дней назад капитан Тиралиус повел взвод солдат на юг, к полигону Эфириума. С тех пор мы ничего не слышали ни о нем, ни о его подчиненных.$B$BВероятнее всего, они попали в засаду и были убиты, однако мои приборы выдают любопытные показания.$B$BМне кажется, это сигнал бедствия, однако эти штуки и прежде ошибались. Если Тиралиус еще жив, они держат его в одной из тюрем. Тебе нужно отыскать эту тюрьму и открыть ее ключом, который, вероятнее всего, находится у стражника.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю плоти Виридиусу на Заставу Стражей Протектората, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10423,'На Штормовую Вершину','Старший инженер Гхабар будет рад узнать результаты диагностики. Кстати, нас предупредили, что нужно присматривать за работой наших генераторов экосферы. По мере того, как поле делается все более и более нестабильным, его эффект становится труднее контролировать. Это может завершиться катастрофой для нашей экспедиции и для всех, кто обитает под сферой.$B$BТы найдешь Гхабара на Штормовой Вершине. Просто иди по дороге на север от этой экосферы, через мост. Она приведет тебя к подъемнику у подножия Вершины.','Поговорите с Гхабаром на Штормовой Вершине в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На Штормовую Вершину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старший инженер Гхабар будет рад узнать результаты диагностики. Кстати, нас предупредили, что нужно присматривать за работой наших генераторов экосферы. По мере того, как поле делается все более и более нестабильным, его эффект становится труднее контролировать. Это может завершиться катастрофой для нашей экспедиции и для всех, кто обитает под сферой.$B$BТы найдешь Гхабара на Штормовой Вершине. Просто иди по дороге на север от этой экосферы, через мост. Она приведет тебя к подъемнику у подножия Вершины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гхабаром на Штормовой Вершине в Пустоверти.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10424,'Диагноз: критический','Если результаты, полученные Мердадом верны – а у меня нет причин в этом сомневаться – то остальные экосферы в опасности.$B$BНо я думаю, что Мердад не сумел опознать истинную причину неполадок. Время от времени разные твари повреждают генераторы, но не настолько сильно. $B$BРади пущей безопасности я попросил бы тебя провести диагностику главного генератора экосферы Штормовой Вершины. Этот генератор находится в заповеднике "Сатерон" у самого восточного края сферы.','Используйте диагностическое устройство, стоя поблизости от генератора экосферы заповедника"Сатерон", и отнесите результаты диагностики Гхабару в Штормовую Вершину.','Эти результаты точно совпадают с тем, что получил Мердад. Но почему? Единственное возможное объяснение, которое приходит мне в голову – это то, что часть деталей генераторов сферы вышла из строя или пропала. Это может значительно ослабить защитное поле сферы и вызвать дисбаланс, как указывают все результаты диагностики.','Удалось ли получить результаты диагностики?','Вернитесь к Гхабару на Штормовую Вершину, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Диагноз: критический',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если результаты, полученные Мердадом верны – а у меня нет причин в этом сомневаться – то остальные экосферы в опасности.$B$BНо я думаю, что Мердад не сумел опознать истинную причину неполадок. Время от времени разные твари повреждают генераторы, но не настолько сильно. $B$BРади пущей безопасности я попросил бы тебя провести диагностику главного генератора экосферы Штормовой Вершины. Этот генератор находится в заповеднике "Сатерон" у самого восточного края сферы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте диагностическое устройство, стоя поблизости от генератора экосферы заповедника"Сатерон", и отнесите результаты диагностики Гхабару в Штормовую Вершину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти результаты точно совпадают с тем, что получил Мердад. Но почему? Единственное возможное объяснение, которое приходит мне в голову – это то, что часть деталей генераторов сферы вышла из строя или пропала. Это может значительно ослабить защитное поле сферы и вызвать дисбаланс, как указывают все результаты диагностики.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли получить результаты диагностики?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гхабару на Штормовую Вершину, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10425,'Побег с полигона','Во имя К\'ареша! Он разорвал бы меня на части.$B$BЯ солдат Протектората. Мой взвод был послан на разведывательную миссию примерно 10 дней назад. Когда мы продвигались через верхние уступы этого острова, на нас напал отряд Братства Эфириума. По крайней мере, я думаю, что они были из Братства Эфириума. У них тот же самый цвет энергии, но обмотки выглядели так, словно сделаны из пустоты.$B$BВ живых остался только Тиралис. Думаю, они бросили его в темницу.$B$BЯ должен добраться до заставы стражей Протектората! Не можешь ли ты сопроводить меня?','Сопроводите пленного передового бойца Протектората обратно на заставу стражей Протектората в Пустоверти.','<Командир Амир выглядит довольным.>$B$BХорошая работа, существо из плоти и крови! Этот солдат может дать нам ключ к разрушению всех планов Братства Эфириум.','Да?','Пленный передовой боец Протектората сопровожден','Вернитесь к командиру Амиру на Заставу Стражей Протектората, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег с полигона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во имя К\'ареша! Он разорвал бы меня на части.$B$BЯ солдат Протектората. Мой взвод был послан на разведывательную миссию примерно 10 дней назад. Когда мы продвигались через верхние уступы этого острова, на нас напал отряд Братства Эфириума. По крайней мере, я думаю, что они были из Братства Эфириума. У них тот же самый цвет энергии, но обмотки выглядели так, словно сделаны из пустоты.$B$BВ живых остался только Тиралис. Думаю, они бросили его в темницу.$B$BЯ должен добраться до заставы стражей Протектората! Не можешь ли ты сопроводить меня?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите пленного передового бойца Протектората обратно на заставу стражей Протектората в Пустоверти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Командир Амир выглядит довольным.>$B$BХорошая работа, существо из плоти и крови! Этот солдат может дать нам ключ к разрушению всех планов Братства Эфириум.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Пленный передовой боец Протектората сопровожден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Амиру на Заставу Стражей Протектората, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10426,'Растительность заповедников','Только оглянись вокруг, |3-6($c)! Разве это не удивительно? Конечно же, это невероятное возрождение жизни является побочным продуктом астральных сфер, но представь себе, что они попадут в руки нашей экспедиции. $B$BЯ готовлюсь вести переговоры с духами Астрала относительно доступа к их технологии, однако у меня есть лучшая идея касательно их воздействия на растительный мир.$B$BЯ создала прибор, способный сконцентрировать энергию сферы на хлестунах, растущих в этой зоне. Может быть, ты окажешь мне услугу – проверить действие этого прибора и поделиться со мной результатами?','Используйте модулятор энергетического поля на фаралонских плеточниках. Пронаблюдайте результаты и после того, как проведете 10 тестов, сообщите результаты Аурин Лунное Сияние, находящейся на Штормовой Вершине.','Ничего себе! Фокусирование энергии сферы, похоже, продолжает ускорять рост до той степени, на которой он порождает необычайную агрессию. Если мы действительно получим возможность использовать эту технологию, мы должны убедиться, что взяли правильные значения.','Удалось ли тебе сфокусировать энергию сферы?','Вернитесь к Аурин Лунному Сиянию на Штормовую Вершину, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Растительность заповедников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только оглянись вокруг, |3-6($c)! Разве это не удивительно? Конечно же, это невероятное возрождение жизни является побочным продуктом астральных сфер, но представь себе, что они попадут в руки нашей экспедиции. $B$BЯ готовлюсь вести переговоры с духами Астрала относительно доступа к их технологии, однако у меня есть лучшая идея касательно их воздействия на растительный мир.$B$BЯ создала прибор, способный сконцентрировать энергию сферы на хлестунах, растущих в этой зоне. Может быть, ты окажешь мне услугу – проверить действие этого прибора и поделиться со мной результатами?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте модулятор энергетического поля на фаралонских плеточниках. Пронаблюдайте результаты и после того, как проведете 10 тестов, сообщите результаты Аурин Лунное Сияние, находящейся на Штормовой Вершине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ничего себе! Фокусирование энергии сферы, похоже, продолжает ускорять рост до той степени, на которой он порождает необычайную агрессию. Если мы действительно получим возможность использовать эту технологию, мы должны убедиться, что взяли правильные значения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе сфокусировать энергию сферы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аурин Лунному Сиянию на Штормовую Вершину, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10427,'Животные заповедников','Твоя работа с хлестунами дала нам неоценимые сведения, однако мне интересно, применимы ли они и к животным тоже?$B$BБоюсь, собирать информацию о талбуках, живущих под этой сферой, будет сложнее, чем изучать хлестуны.$B$BИспользуя это метящее устройство, ты можешь погрузить в сон ослабевшего талбука и нацепить на него метку, чтобы я могла следить, как он взрослеет. Механизм установки метки не сработает, если талбук не израсходовал большую часть своих сил.','Пометьте 12 талбуков для Аурин Лунное Сияние из Штормовой Вершины. Вы можете метить как самцов, так и самок талбуков, используя метчик для талбуков.','Превосходно. Я буду присматривать за помеченными особями и проверю, взрослеют ли они так же быстро, как другие формы жизни в сфере.$B$BПри наличии должного контроля мы сможем использовать эту технологию, чтобы восстановить разрушенные участки Запределья и Азерота.','Тебе удалось пометить достаточное число талбуков?','Вернитесь к Аурин Лунному Сиянию на Штормовую Вершину, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Животные заповедников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твоя работа с хлестунами дала нам неоценимые сведения, однако мне интересно, применимы ли они и к животным тоже?$B$BБоюсь, собирать информацию о талбуках, живущих под этой сферой, будет сложнее, чем изучать хлестуны.$B$BИспользуя это метящее устройство, ты можешь погрузить в сон ослабевшего талбука и нацепить на него метку, чтобы я могла следить, как он взрослеет. Механизм установки метки не сработает, если талбук не израсходовал большую часть своих сил.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пометьте 12 талбуков для Аурин Лунное Сияние из Штормовой Вершины. Вы можете метить как самцов, так и самок талбуков, используя метчик для талбуков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно. Я буду присматривать за помеченными особями и проверю, взрослеют ли они так же быстро, как другие формы жизни в сфере.$B$BПри наличии должного контроля мы сможем использовать эту технологию, чтобы восстановить разрушенные участки Запределья и Азерота.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось пометить достаточное число талбуков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аурин Лунному Сиянию на Штормовую Вершину, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (10428,'Пропавший рыбак') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший рыбак',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10429,'Когда природа заходит слишком далеко','В технологии экосфер задействовано столько энергии! Определенно, есть границы, за которые мы не смеем выходить, $n.$B$BКогда живые существа вырастают слишком быстро или слишком большими, это так же плохо, как и полное отсутствие жизни. $B$BДо меня доходили слухи, что одно такое существо обитает в пруду на востоке отсюда. Я слышала, что торговцы из числа духов Астрала сговорились поймать эту гидру для забавы, однако у меня на нее другие виды. Принеси мне сердце этого существа, чтобы я могла его изучить.','Аурин Лунное Сияние из Штормовой Вершины просит вас принести ей сердце гигантской гидры.','Удалось ли тебе добыть образец тканей этой чудовищной гидры?','Вернитесь к Аурин Лунному Сиянию на Штормовую Вершину, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда природа заходит слишком далеко',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В технологии экосфер задействовано столько энергии! Определенно, есть границы, за которые мы не смеем выходить, $n.$B$BКогда живые существа вырастают слишком быстро или слишком большими, это так же плохо, как и полное отсутствие жизни. $B$BДо меня доходили слухи, что одно такое существо обитает в пруду на востоке отсюда. Я слышала, что торговцы из числа духов Астрала сговорились поймать эту гидру для забавы, однако у меня на нее другие виды. Принеси мне сердце этого существа, чтобы я могла его изучить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аурин Лунное Сияние из Штормовой Вершины просит вас принести ей сердце гигантской гидры.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе добыть образец тканей этой чудовищной гидры?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аурин Лунному Сиянию на Штормовую Вершину, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (10430,'Испытание прототипа','Я работал над ремонтным набором для переносных генераторов для использования в суровом климате, где осуществляет свои действия Консорциум. Конечно, он не был предназначен для Пустоверти, но с этим проблем быть не должно.$B$BЯ уже составил план испытаний с участием одного из моих лучших техников – он сейчас находится в заповеднике "Дальнее поле" за Осколками Пустоты, на северо-востоке отсюда. Отнеси этот прототип Ташару. Он знает, что с ним делать. Если это сработает, мы сможем использовать данный прибор, чтобы усилить генераторы поля в крупных экосферах.','Отнесите ремонтный аппарат Ташару в заповедник "Дальнее поле" в Пустоверти.','Похоже, это у тебя прототип. Тебя послал Гхабар?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание прототипа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я работал над ремонтным набором для переносных генераторов для использования в суровом климате, где осуществляет свои действия Консорциум. Конечно, он не был предназначен для Пустоверти, но с этим проблем быть не должно.$B$BЯ уже составил план испытаний с участием одного из моих лучших техников – он сейчас находится в заповеднике "Дальнее поле" за Осколками Пустоты, на северо-востоке отсюда. Отнеси этот прототип Ташару. Он знает, что с ним делать. Если это сработает, мы сможем использовать данный прибор, чтобы усилить генераторы поля в крупных экосферах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ремонтный аппарат Ташару в заповедник "Дальнее поле" в Пустоверти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, это у тебя прототип. Тебя послал Гхабар?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (10431,'Помощь извне','Идите в Лагерь Тулумана, на север от Зоны 52, и поговорите с Кайлааном. $B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь извне',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Идите в Лагерь Тулумана, на север от Зоны 52, и поговорите с Кайлааном. $B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10432,'Надежное свидетельство','Это важно, $N. Очень важно!$B$BВорен\'талю нужно услышать это как можно скорее.','Ну? Что хотел сказать мне Тельдорн?','Вернитесь к патрону шпионов Талодиену в Зону 52, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надежное свидетельство',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это важно, $N. Очень важно!$B$BВорен\'талю нужно услышать это как можно скорее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну? Что хотел сказать мне Тельдорн?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к патрону шпионов Талодиену в Зону 52, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10433,'Поддерживая видимость','Эфириалы умны и очень наблюдательны, так что я не случайно здесь изображаю простого скорняка. На самом деле меня послали из Зоны 52, чтобы взглянуть на технологию, которую эфириалы используют для создания своих экосфер.$B$BЯ хочу попросить тебя о помощи, |3-6($c). Нам нужно как можно чаще задействовать агентов, не принадлежащих к расе гоблинов.$B$BТак вот, притворись, что охотишься, и принеси мне несколько шкур рыси-клыкодера. Рыси встречаются вокруг заповедника "Срединные земли".','Принесите 10 шкур рыси-клыкодера Шоли Пору на Заставу срединных земель.','Вернитесь к Шоли Пору в Заповедник "Срединные земли", что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддерживая видимость',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эфириалы умны и очень наблюдательны, так что я не случайно здесь изображаю простого скорняка. На самом деле меня послали из Зоны 52, чтобы взглянуть на технологию, которую эфириалы используют для создания своих экосфер.$B$BЯ хочу попросить тебя о помощи, |3-6($c). Нам нужно как можно чаще задействовать агентов, не принадлежащих к расе гоблинов.$B$BТак вот, притворись, что охотишься, и принеси мне несколько шкур рыси-клыкодера. Рыси встречаются вокруг заповедника "Срединные земли".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 шкур рыси-клыкодера Шоли Пору на Заставу срединных земель.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шоли Пору в Заповедник "Срединные земли", что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10434,'Динамический дуэт','Прекрасно.$B$B<Шоли подмигивает тебе.>$B$BЯ думаю, они это купят. Если я пошлю тебя поговорить с моими коллегами на Штормовой Вершине, то никаких подозрений это не вызовет.$B$BПоищи там Джема Бондса и Оди Иголку. Они расскажут тебе все, что нужно. Скажи им, что тебя послал Шоли.','Поговорите с Оди Иголкой на Штормовой Вершине в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Динамический дуэт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прекрасно.$B$B<Шоли подмигивает тебе.>$B$BЯ думаю, они это купят. Если я пошлю тебя поговорить с моими коллегами на Штормовой Вершине, то никаких подозрений это не вызовет.$B$BПоищи там Джема Бондса и Оди Иголку. Они расскажут тебе все, что нужно. Скажи им, что тебя послал Шоли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Оди Иголкой на Штормовой Вершине в Пустоверти.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10435,'Сбор деталей','Оди Иголка, находящаяся на Штормовой Вершине, просит вас принести ей 10 сегментов генератора защитного купола.','Вернитесь к Оди Иголке на Штормовую Вершину, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор деталей',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оди Иголка, находящаяся на Штормовой Вершине, просит вас принести ей 10 сегментов генератора защитного купола.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Оди Иголке на Штормовую Вершину, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10436,'Все чисто!','Прежде чем мы начнем испытание, мы должны убедиться, что в районе нет никого, кто мог бы вмешаться. В нашем случае – это вон те ящерицы-переростки.$B$B<Ташар указывает в сторону cаблезубых ящеров.>$B$BНет смысла говорить, что случится, если один из них решит попробовать на вкус наш генератор, пока он заряжается. За много лет на должности техника я видел много странных вещей, в том числе и изрядное количество мерзких тварей, которые изначально были довольно милыми зверушками.','Ташар, находящийся в заповеднике "Дальнее поле", просит вас убить 12 саблезубых ящеров.','Вернитесь к Ташару в заповедник "Дальнее поле", что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все чисто!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем мы начнем испытание, мы должны убедиться, что в районе нет никого, кто мог бы вмешаться. В нашем случае – это вон те ящерицы-переростки.$B$B<Ташар указывает в сторону cаблезубых ящеров.>$B$BНет смысла говорить, что случится, если один из них решит попробовать на вкус наш генератор, пока он заряжается. За много лет на должности техника я видел много странных вещей, в том числе и изрядное количество мерзких тварей, которые изначально были довольно милыми зверушками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ташар, находящийся в заповеднике "Дальнее поле", просит вас убить 12 саблезубых ящеров.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ташару в заповедник "Дальнее поле", что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10437,'Рецепт уничтожения','Профессор Дабири, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы собрали 8 фрагментов Пространствуса.','Превосходно! При помощи этих фрагментов мы сможем настроить бомбу, которая уничтожит стержень Бездны над Ультрисом. Когда стержень Бездны будет уничтожен, связь Пространствуса с Бездной оборвется и он останется без защиты.','Удалось ли тебе собрать достаточно фрагментов?','Вернитесь к профессору Дабири на Заставу Стражей Протектората, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рецепт уничтожения',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Профессор Дабири, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы собрали 8 фрагментов Пространствуса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! При помощи этих фрагментов мы сможем настроить бомбу, которая уничтожит стержень Бездны над Ультрисом. Когда стержень Бездны будет уничтожен, связь Пространствуса с Бездной оборвется и он останется без защиты.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе собрать достаточно фрагментов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к профессору Дабири на Заставу Стражей Протектората, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10438,'На крыльях Пустоты','Вот, $n. Возьми этот фазовый дезинтегратор и забирайся в седло. Дракон Пустоты Протектората доставит тебя достаточно близко к Ультрису, чтобы сбросить дезинтегратор на стержень Бездны.$B$BСкинь как можно больше дезинтеграционных зарядов, чтобы уничтожение было полным!$B$BКогда все будет сделано, скажи дракону Пустоты и он унесет тебя ввысь.$B$BЕсли промахнешься, то прежде, чем снова идти на задание, возьми у меня еще бомбы.','Профессор Дабири, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы использовали фазовый дезинтегратор, когда окажетесь вблизи от стержня Бездны наверху Ультриса. Скиньте как можно больше зарядов фазового дезинтегратора, чтобы обеспечить полное уничтожение. Заряды фазового дезинтегратора автоматически попадут в стержень Бездны, если вы будете достаточно близко, чтобы использовать их.$B$BЕсли вы преуспеете, возвращайтесь к профессору Дабири!','Настало время нанести удар! Когда разрыв исчезнет, Пространствус будет уязвим для физических и магических атак!','Вернитесь к профессору Дабири на Заставу Стражей Протектората, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На крыльях Пустоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, $n. Возьми этот фазовый дезинтегратор и забирайся в седло. Дракон Пустоты Протектората доставит тебя достаточно близко к Ультрису, чтобы сбросить дезинтегратор на стержень Бездны.$B$BСкинь как можно больше дезинтеграционных зарядов, чтобы уничтожение было полным!$B$BКогда все будет сделано, скажи дракону Пустоты и он унесет тебя ввысь.$B$BЕсли промахнешься, то прежде, чем снова идти на задание, возьми у меня еще бомбы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Профессор Дабири, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы использовали фазовый дезинтегратор, когда окажетесь вблизи от стержня Бездны наверху Ультриса. Скиньте как можно больше зарядов фазового дезинтегратора, чтобы обеспечить полное уничтожение. Заряды фазового дезинтегратора автоматически попадут в стержень Бездны, если вы будете достаточно близко, чтобы использовать их.$B$BЕсли вы преуспеете, возвращайтесь к профессору Дабири!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Настало время нанести удар! Когда разрыв исчезнет, Пространствус будет уязвим для физических и магических атак!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к профессору Дабири на Заставу Стражей Протектората, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10439,'Пространствус Всепоглощающий','Твои отважные подвиги заставили Амира действовать! Он отрядил капитана Саида и Мстителей!$B$BТеперь все, что осталось – это уничтожить Пространствуса.$B$BКогда все будет готово, я вызову Саида. Если он сейчас не сражается в очередной битве, он будет ожидать твоих приказов – ищи его к востоку отсюда.$B$BКогда подготовишься к сражению, уведоми его, и он поведет свои войска.$B$BЖелаю тебе удачи, о существо из плоти и крови! Мы охотились за Пространствусом тысячи лет!','Профессор Дабири, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы поговорили с капитаном Саидом, а потом вместе с его армией проследовали к манагорну Ультрис и убили Пространствуса Всепоглощающего!','На протяжении тысяч лет мы не знали ничего, кроме войны. Мы защищали наш народ от нападений тварей Бездны и эфириалов в равной степени.$B$BНыне один из самых ненавистных наших врагов мертв – наконец-то.$B$BО существо из плоти и крови, знай, что тебе благодарны сотни миллионов эфириалов!','Вернитесь к профессору Дабири на Заставу Стражей Протектората, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пространствус Всепоглощающий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои отважные подвиги заставили Амира действовать! Он отрядил капитана Саида и Мстителей!$B$BТеперь все, что осталось – это уничтожить Пространствуса.$B$BКогда все будет готово, я вызову Саида. Если он сейчас не сражается в очередной битве, он будет ожидать твоих приказов – ищи его к востоку отсюда.$B$BКогда подготовишься к сражению, уведоми его, и он поведет свои войска.$B$BЖелаю тебе удачи, о существо из плоти и крови! Мы охотились за Пространствусом тысячи лет!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Профессор Дабири, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы поговорили с капитаном Саидом, а потом вместе с его армией проследовали к манагорну Ультрис и убили Пространствуса Всепоглощающего!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На протяжении тысяч лет мы не знали ничего, кроме войны. Мы защищали наш народ от нападений тварей Бездны и эфириалов в равной степени.$B$BНыне один из самых ненавистных наших врагов мертв – наконец-то.$B$BО существо из плоти и крови, знай, что тебе благодарны сотни миллионов эфириалов!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к профессору Дабири на Заставу Стражей Протектората, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10440,'Успех!','Проверка показала небывалый успех! Мы, несомненно, можем использовать этот прибор для починки сфер.$B$BСообщи о результатах проверки в Штормовую Вершину и дай Гхабару знать, что я, помимо этого, обнаружил некую схему в повреждениях генераторов поля. Из ряда мест пропали ключевые детали генераторов. Это не несчастный случай, $n, и не технологическая ошибка. Это намеренная кража.','Вернитесь в Штормовую Вершину, что в Пустоверти, и поговорите с Гхабаром.','Я немедленно пошлю своих техников на работу по починке.$B$BОднако подозрения Ташара относительно саботажа тревожат меня. Не могу вспомнить никого, кто оказался бы достаточно дерзок, чтобы взяться за похищение наших технологий. Во всяком случае, из тех, кто знает, на что мы способны. Быть может, настало время ограничить доступ в Штормовую Вершину.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Успех!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проверка показала небывалый успех! Мы, несомненно, можем использовать этот прибор для починки сфер.$B$BСообщи о результатах проверки в Штормовую Вершину и дай Гхабару знать, что я, помимо этого, обнаружил некую схему в повреждениях генераторов поля. Из ряда мест пропали ключевые детали генераторов. Это не несчастный случай, $n, и не технологическая ошибка. Это намеренная кража.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Штормовую Вершину, что в Пустоверти, и поговорите с Гхабаром.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я немедленно пошлю своих техников на работу по починке.$B$BОднако подозрения Ташара относительно саботажа тревожат меня. Не могу вспомнить никого, кто оказался бы достаточно дерзок, чтобы взяться за похищение наших технологий. Во всяком случае, из тех, кто знает, на что мы способны. Быть может, настало время ограничить доступ в Штормовую Вершину.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10441,'Торговля по мелочам','<Оди снова понижает голос.>$B$BТеперь, когда у нас есть товар, я отошлю большую часть деталей в Зону 52. Их здесь достаточно, чтобы собрать не один генератор, и это дает идеальную возможность провернуть дельце.$B$BЯ видела, как представительница Кенарийской экспедиции пытается торговаться. Вот чего я хочу: намекни ей, что мы можем обеспечить то, что она ищет, по вполне разумной цене. Зачем ей и дальше иметь дело с этими жуликами – духами Астрала?','Поговорите с Аурин Лунное Сияние у подножия Штормовой Вершины в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Торговля по мелочам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Оди снова понижает голос.>$B$BТеперь, когда у нас есть товар, я отошлю большую часть деталей в Зону 52. Их здесь достаточно, чтобы собрать не один генератор, и это дает идеальную возможность провернуть дельце.$B$BЯ видела, как представительница Кенарийской экспедиции пытается торговаться. Вот чего я хочу: намекни ей, что мы можем обеспечить то, что она ищет, по вполне разумной цене. Зачем ей и дальше иметь дело с этими жуликами – духами Астрала?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Аурин Лунное Сияние у подножия Штормовой Вершины в Пустоверти.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (10442,'Помощь Кенарийской заставе','$C, некий таурен по имени Тиа Рыжая Грива непрерывно докучает нам просьбами о помощи. Она из Кенарийской экспедиции, их застава находится к юго-западу от дороги, ведущей в Зангартопь.$B$BЭто чуть ближе Холма Колючего Клыка.$B$BМожешь пойти туда и выяснить, что ей нужно? Я не хочу беспокоить капитана следопытов Венн\'рена по таким мелочам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Кенарийской заставе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, некий таурен по имени Тиа Рыжая Грива непрерывно докучает нам просьбами о помощи. Она из Кенарийской экспедиции, их застава находится к юго-западу от дороги, ведущей в Зангартопь.$B$BЭто чуть ближе Холма Колючего Клыка.$B$BМожешь пойти туда и выяснить, что ей нужно? Я не хочу беспокоить капитана следопытов Венн\'рена по таким мелочам.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (10443,'Помощь Кенарийской заставе','Как я понимаю, Круг Кенария отправил в Запределье экспедицию, чтобы узнать, что там случилось, и при необходимости оказать помощь.$B$BОни разбили лагерь к юго-западу от дороги, ведущей в Зангартопь, не доходя до Холма Колючего Клыка.$B$BМожешь отправиться к ним на помощь? Найди там Тиу Рыжую Гриву, это она просила нас прислать подкрепление.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Кенарийской заставе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как я понимаю, Круг Кенария отправил в Запределье экспедицию, чтобы узнать, что там случилось, и при необходимости оказать помощь.$B$BОни разбили лагерь к юго-западу от дороги, ведущей в Зангартопь, не доходя до Холма Колючего Клыка.$B$BМожешь отправиться к ним на помощь? Найди там Тиу Рыжую Гриву, это она просила нас прислать подкрепление.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (10444,'Послание для Заставы Аллерии','Нужно немедленно действовать!$B$BРядом с Лагерем Огнекрылов есть кое-кто, с кем вам нужно поговорить – он лучше знает, что делать дальше.$B$BНайдите лейтенанта Меридиана на Заставе Аллерии и объясните ему ситуацию. Застава находится к северо-востоку от южного берега реки, протекающей южнее Лагеря Огнекрылов.$B$BПоспешите, $n.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание для Заставы Аллерии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно немедленно действовать!$B$BРядом с Лагерем Огнекрылов есть кое-кто, с кем вам нужно поговорить – он лучше знает, что делать дальше.$B$BНайдите лейтенанта Меридиана на Заставе Аллерии и объясните ему ситуацию. Застава находится к северо-востоку от южного берега реки, протекающей южнее Лагеря Огнекрылов.$B$BПоспешите, $n.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10445,'Сосуды Вечности','Иллидан наполнил семь сосудов из Источника Вечности. Три из них он вылил в озеро на горе Хиджал и создал второй Источник. Долгое время считалось, что остальные четыре сосуда были утрачены.$B$BНо после того как открылся Темный портал, мы узнали, что Иллидан отдал по одному сосуду своим лейтенантам Кель\'тасу и Вайши. Найди эти сосуды и принеси нам. Без них мы не можем открыть временные проходы к событиям, так или иначе связанным с горой Хиджал, – ни к недавним, ни к древним. Мы должны позаботиться о том, чтобы ничто не смогло изменить исход битвы за Хиджал.','Я просил от тебя невозможного, но я надеялся на твой успех. От этого многое зависит.','Я просил у тебя невозможного, но надеюсь, что ты добьешься успеха. От этого многое зависит.','Вернитесь к Соридорми в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сосуды Вечности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иллидан наполнил семь сосудов из Источника Вечности. Три из них он вылил в озеро на горе Хиджал и создал второй Источник. Долгое время считалось, что остальные четыре сосуда были утрачены.$B$BНо после того как открылся Темный портал, мы узнали, что Иллидан отдал по одному сосуду своим лейтенантам Кель\'тасу и Вайши. Найди эти сосуды и принеси нам. Без них мы не можем открыть временные проходы к событиям, так или иначе связанным с горой Хиджал, – ни к недавним, ни к древним. Мы должны позаботиться о том, чтобы ничто не смогло изменить исход битвы за Хиджал.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я просил от тебя невозможного, но я надеялся на твой успех. От этого многое зависит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я просил у тебя невозможного, но надеюсь, что ты добьешься успеха. От этого многое зависит.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Соридорми в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (10446,'Финальный код','Они собирают еще одну мана-бомбу во дворе! Разведка сообщила мне, что финальный код от этой бомбы находится у Шарта Волдуна, который руководит этим проектом в Лагере Огнекрылов.$B$B$n, вам нужно вернуться туда и отобрать у него этот код. Шарт живет на пике самой высокой башни.$B$BКогда добудете код, найдите эту недособранную бомбу и отключите ее.$B$BТолько тогда Бастион Аллерии будет в безопасности.','Вернитесь к Дженайе Шепот Звезд в Бастион Аллерии, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Финальный код',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они собирают еще одну мана-бомбу во дворе! Разведка сообщила мне, что финальный код от этой бомбы находится у Шарта Волдуна, который руководит этим проектом в Лагере Огнекрылов.$B$B$n, вам нужно вернуться туда и отобрать у него этот код. Шарт живет на пике самой высокой башни.$B$BКогда добудете код, найдите эту недособранную бомбу и отключите ее.$B$BТолько тогда Бастион Аллерии будет в безопасности.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дженайе Шепот Звезд в Бастион Аллерии, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (10447,'Финальный код','Они собирают еще одну мана-бомбу во дворе! Разведка сообщила мне, что финальный код от этой бомбы находится у Шарта Волдуна, который руководит этим проектом в Лагере Огнекрылов.$B$B$n, вам нужно вернуться туда и отобрать у него этот код. Шарт живет на пике самой высокой башни.$B$BКогда добудете код, найдите эту недособранную бомбу и отключите ее.$B$BТолько тогда Форт Камнеломов будет в безопасности.','Вернитесь к Тууки в Форт Камнеломов, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Финальный код',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они собирают еще одну мана-бомбу во дворе! Разведка сообщила мне, что финальный код от этой бомбы находится у Шарта Волдуна, который руководит этим проектом в Лагере Огнекрылов.$B$B$n, вам нужно вернуться туда и отобрать у него этот код. Шарт живет на пике самой высокой башни.$B$BКогда добудете код, найдите эту недособранную бомбу и отключите ее.$B$BТолько тогда Форт Камнеломов будет в безопасности.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тууки в Форт Камнеломов, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (10448,'Донесение в Лагерь Камнеломов','Нужно немедленно действовать!$B$BРядом с Лагерем Огнекрылов есть кое-кто, с кем вам нужно поговорить – он лучше знает, что делать дальше.$B$BНайдите сержанта Чани в Лагере Камнеломов и объясните ей ситуацию. Из крепости идите на север, а из центра Туурема поворачивайте на восток. Лагерь находится на берегу реки, что к юго-западу от Лагеря Огнекрылов.$B$BПоспешите, $n.','Детали бомб. Значит, я была права, хотя именно здесь я предпочла бы ошибиться.$B$BЛадно, значит, нам с вами предстоит одно очень серьезное дело.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение в Лагерь Камнеломов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно немедленно действовать!$B$BРядом с Лагерем Огнекрылов есть кое-кто, с кем вам нужно поговорить – он лучше знает, что делать дальше.$B$BНайдите сержанта Чани в Лагере Камнеломов и объясните ей ситуацию. Из крепости идите на север, а из центра Туурема поворачивайте на восток. Лагерь находится на берегу реки, что к юго-западу от Лагеря Огнекрылов.$B$BПоспешите, $n.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Детали бомб. Значит, я была права, хотя именно здесь я предпочла бы ошибиться.$B$BЛадно, значит, нам с вами предстоит одно очень серьезное дело.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (10449,'Аптекарь Зелана','Доставьте образцы крови костеглода аптекарю Зелане в Гибель Сквернобота по просьбе Вартока Топоруба из Траллмара.','Служить Орде – это большая честь для меня. Чем могу помочь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аптекарь Зелана',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте образцы крови костеглода аптекарю Зелане в Гибель Сквернобота по просьбе Вартока Топоруба из Траллмара.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Служить Орде – это большая честь для меня. Чем могу помочь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10450,'Кровь Костеглодов','Костеглоды! Чтоб они все попередохли! При виде их красной шкуры в моих жилах кровь вскипает от ярости!$B$BУ меня к тебе дело, $n. Убивай орков из клана Костеглодов и собирай их подлую кровь. Наши аптекари протестируют ее и узнают, как эти орки попали под власть демонической Скверны, той самой, от которой нам недавно удалось освободиться.$B$BКостеглоды обитают рядом с обрушенной стеной, которая тянется к югу, вдоль Пути Славы. После выполнения задания возвращайся ко мне.','Принесите 12 фиалов крови костеглода Вартоку Топорубу в Траллмар.','Вернитесь к Вартоку Топорубу в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь Костеглодов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Костеглоды! Чтоб они все попередохли! При виде их красной шкуры в моих жилах кровь вскипает от ярости!$B$BУ меня к тебе дело, $n. Убивай орков из клана Костеглодов и собирай их подлую кровь. Наши аптекари протестируют ее и узнают, как эти орки попали под власть демонической Скверны, той самой, от которой нам недавно удалось освободиться.$B$BКостеглоды обитают рядом с обрушенной стеной, которая тянется к югу, вдоль Пути Славы. После выполнения задания возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 12 фиалов крови костеглода Вартоку Топорубу в Траллмар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вартоку Топорубу в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10451,'Спастись из водохранилища Змеиных Колец','Благодарение Матери-Земле! Я отбилась от остальных несколько дней назад, хотела обнаружить источник того беспокойства, которое чувствовали духи воды. Расследование привело меня к Змеиным Кольцам, где я обнаружила наг, оскверняющих запасы воды долины Призрачной Луны. $B$BК сожалению, меня заметили, и я попала в плен. У меня нет сил даже говорить о той судьбе, которую они мне уготовили.$B$BМы должны выбраться отсюда! Помоги мне бежать, а потом найти Торлока у Алтаря Проклятия.','Выведите целительницу земли Вильду из водохранилища Змеиных Колец и затем разыщите целителя земли Торлока у Алтаря Проклятия, на западной окраине Руки Гул\'дана.','Хвала Матери-Земле. Я уверен, что теперь Вильда и сама доберется домой. Прошу, прими это от нас как знак признательности.','Целительница земли Вильда доставлена в безопасное место','Вернитесь к целителю земли Торлоку на Алтарь Проклятия, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спастись из водохранилища Змеиных Колец',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодарение Матери-Земле! Я отбилась от остальных несколько дней назад, хотела обнаружить источник того беспокойства, которое чувствовали духи воды. Расследование привело меня к Змеиным Кольцам, где я обнаружила наг, оскверняющих запасы воды долины Призрачной Луны. $B$BК сожалению, меня заметили, и я попала в плен. У меня нет сил даже говорить о той судьбе, которую они мне уготовили.$B$BМы должны выбраться отсюда! Помоги мне бежать, а потом найти Торлока у Алтаря Проклятия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выведите целительницу земли Вильду из водохранилища Змеиных Колец и затем разыщите целителя земли Торлока у Алтаря Проклятия, на западной окраине Руки Гул\'дана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хвала Матери-Земле. Я уверен, что теперь Вильда и сама доберется домой. Прошу, прими это от нас как знак признательности.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Целительница земли Вильда доставлена в безопасное место',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к целителю земли Торлоку на Алтарь Проклятия, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10452,'DON\'T USE [PH] Fel Orc 1','[PH Fel Orc 1.','[PH Fel Orc 1.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DON\'T USE [PH] Fel Orc 1',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[PH Fel Orc 1.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PH Fel Orc 1.',`objectives_loc8`);
