INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (10454,'FLAG – OFF THE RAILS') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG – OFF THE RAILS',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10455,'Угроза хищников','Мы выращивали Живую рощу ускоренными темпами, но лесные рыси каким-то образом вышли из-под нашего контроля.$B$BРаньше популяция рысей была стабильна, но теперь они начали проникать даже в Сильванаар, и недавно произошло несколько неприятных инцидентов.$B$BПодозреваю, что за этим стоят араккоа из Лашш, но прежде надо разобраться с самим рысями.$B$BЯ была бы весьма тебе благодарна, если бы нам в этом $Gпомог:помогла;.','Убейте 12 лесных рысей.','Вернитесь к Рине Лунному Роднику в Сильванаар, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угроза хищников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы выращивали Живую рощу ускоренными темпами, но лесные рыси каким-то образом вышли из-под нашего контроля.$B$BРаньше популяция рысей была стабильна, но теперь они начали проникать даже в Сильванаар, и недавно произошло несколько неприятных инцидентов.$B$BПодозреваю, что за этим стоят араккоа из Лашш, но прежде надо разобраться с самим рысями.$B$BЯ была бы весьма тебе благодарна, если бы нам в этом $Gпомог:помогла;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 лесных рысей.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рине Лунному Роднику в Сильванаар, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10456,'Волчья напасть','Эти подлые расы Орды захватили поселение на востоке. С собой они привели стаю лютых волков, на которых они ездят верхом и посылают как часовых.$B$BИ эти волки разбойничают на мосту, что разделяет нас. Они охотятся на наших волшебных драконов, необходимых для опыления Живой рощи.$B$BИди через восточный выход, чтобы пересечь мост над лощиной Кровавого Молота, который выводит к Зазубренной гряде на востоке, и принеси мне их хвосты в доказательство!','Соберите 4 хвоста лютого волка клана Громоборцев.','Мне даже трудно выразить, насколько важно уничтожить этих лютых волков Громоборцев! Само их существование угрожает стабильности Живой рощи и всей нашей работе здесь.','Вернитесь к Рине Лунному Роднику в Сильванаар, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Волчья напасть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти подлые расы Орды захватили поселение на востоке. С собой они привели стаю лютых волков, на которых они ездят верхом и посылают как часовых.$B$BИ эти волки разбойничают на мосту, что разделяет нас. Они охотятся на наших волшебных драконов, необходимых для опыления Живой рощи.$B$BИди через восточный выход, чтобы пересечь мост над лощиной Кровавого Молота, который выводит к Зазубренной гряде на востоке, и принеси мне их хвосты в доказательство!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 4 хвоста лютого волка клана Громоборцев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне даже трудно выразить, насколько важно уничтожить этих лютых волков Громоборцев! Само их существование угрожает стабильности Живой рощи и всей нашей работе здесь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рине Лунному Роднику в Сильванаар, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10457,'Защитить свой дом','Хотя ты и так много $Gпотрудился:потрудилась; ради защиты нашего нового дома в этих краях, мне все еще кажется, что Живую рощу надо обезопасить.$B$BПрошу тебя, возьми вот эту маленькую ветку, которую я наполнила силой природы. Когда ты взмахнешь ей над саженцами, что я высадила в роще, она вызовет грозу, которая ускорит рост древней.$B$BЭти древни очень нужны для защиты рощи, особенно если ты не задержишься в Сильванааре надолго.','Взмахните ветвью Рины над 5 саженцами рощи, чтобы призвать на защиту Живой рощи силы природы.','Теперь, когда защита Рощи укреплена, я чувствую себя куда спокойнее.$B$BТы $Gзаслужил:заслужила; нашу благодарность и хвалу, $N.$B$BИ, конечно, я сразу же вспомнила об ещё одном важном деле!','Как идёт укрепление защиты Рощи?$B$BПоскольку мы не знаем о намерениях араккоа из Лашш, а Орда засела прямо на другой стороне ущелья, то я боюсь, что если мы не поторопимся, то не сумеем защитить ни наш дом, ни Рощу, ни все наши труды.','Вернитесь к Рине Лунному Роднику в Сильванаар, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защитить свой дом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя ты и так много $Gпотрудился:потрудилась; ради защиты нашего нового дома в этих краях, мне все еще кажется, что Живую рощу надо обезопасить.$B$BПрошу тебя, возьми вот эту маленькую ветку, которую я наполнила силой природы. Когда ты взмахнешь ей над саженцами, что я высадила в роще, она вызовет грозу, которая ускорит рост древней.$B$BЭти древни очень нужны для защиты рощи, особенно если ты не задержишься в Сильванааре надолго.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Взмахните ветвью Рины над 5 саженцами рощи, чтобы призвать на защиту Живой рощи силы природы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, когда защита Рощи укреплена, я чувствую себя куда спокойнее.$B$BТы $Gзаслужил:заслужила; нашу благодарность и хвалу, $N.$B$BИ, конечно, я сразу же вспомнила об ещё одном важном деле!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как идёт укрепление защиты Рощи?$B$BПоскольку мы не знаем о намерениях араккоа из Лашш, а Орда засела прямо на другой стороне ущелья, то я боюсь, что если мы не поторопимся, то не сумеем защитить ни наш дом, ни Рощу, ни все наши труды.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рине Лунному Роднику в Сильванаар, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10458,'Разъяренные бесы пламени и земли','Мы должны пробовать исправить причиненный ущерб. Мы должны найти общий язык со стихиями этого края и, может быть, нам удастся что-то исправить! $B$BВот тебе тотем духов, |3-6($r). Тотем поглощает души убитых рядом с ним разъяренных элементалей. Тебе придется собрать множество бесов, чтобы зарядить тотем.$B$BНачни с бесов земли и пламени и возвращайся, когда тотем будет полностью заряжен.','Поймайте с помощью тотема духов 8 бесов земли и 8 бесов пламени для целителя земли Торлока из Алтаря Проклятия.','Когда все души элементалей обретут пристанище в этом тотеме, мы сможем пообщаться с ними и выяснить, возможно ли что-нибудь сделать для Долины Призрачной Луны.','Я боюсь, эту землю уже ничто не спасет.','Вернитесь к целителю земли Торлоку на Алтарь Проклятия, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разъяренные бесы пламени и земли',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны пробовать исправить причиненный ущерб. Мы должны найти общий язык со стихиями этого края и, может быть, нам удастся что-то исправить! $B$BВот тебе тотем духов, |3-6($r). Тотем поглощает души убитых рядом с ним разъяренных элементалей. Тебе придется собрать множество бесов, чтобы зарядить тотем.$B$BНачни с бесов земли и пламени и возвращайся, когда тотем будет полностью заряжен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте с помощью тотема духов 8 бесов земли и 8 бесов пламени для целителя земли Торлока из Алтаря Проклятия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Когда все души элементалей обретут пристанище в этом тотеме, мы сможем пообщаться с ними и выяснить, возможно ли что-нибудь сделать для Долины Призрачной Луны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я боюсь, эту землю уже ничто не спасет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к целителю земли Торлоку на Алтарь Проклятия, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10459,'Почтительное отношение Кенарийской экспедиции','Мы знаем о твоих свершениях, $n. То, что ты $gсделал:сделала; для нас, выходит за рамки того, чего мы ждем от обычных союзников.$b$bУ меня к тебе будет особая просьба – но сначала мне нужно испытать твою преданность.','Исиэль Песнь Ветра из Кенарийского оплота хочет, чтобы вы добились почтительного отношения Кенарийской экспедиции.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почтительное отношение Кенарийской экспедиции',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы знаем о твоих свершениях, $n. То, что ты $gсделал:сделала; для нас, выходит за рамки того, чего мы ждем от обычных союзников.$b$bУ меня к тебе будет особая просьба – но сначала мне нужно испытать твою преданность.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исиэль Песнь Ветра из Кенарийского оплота хочет, чтобы вы добились почтительного отношения Кенарийской экспедиции.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (10460,'Посвящение в защитники','Ты $Gверен:уверена;, что хочешь избрать этот путь, $N? Он будет нелегким, так что трижды подумай, прежде чем примешь решение.$B$BВ этом кольце заключена капля воды из Источника Вечности. Его сила возрастет, когда ты заслужишь доверие драконов Песчаной Чешуи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посвящение в защитники',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gверен:уверена;, что хочешь избрать этот путь, $N? Он будет нелегким, так что трижды подумай, прежде чем примешь решение.$B$BВ этом кольце заключена капля воды из Источника Вечности. Его сила возрастет, когда ты заслужишь доверие драконов Песчаной Чешуи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (10461,'Посвящение в целители','Ты $Gуверен:уверена;, что это тот путь, по которому ты хочешь идти, $N? Это не решение, которое вы должны принять легко.$B$BЭто кольцо пропитано капелькой из Колодца Вечности. Он будет расти по мере того, как вы будете проявлять себя в Весах Песков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посвящение в целители',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gуверен:уверена;, что это тот путь, по которому ты хочешь идти, $N? Это не решение, которое вы должны принять легко.$B$BЭто кольцо пропитано капелькой из Колодца Вечности. Он будет расти по мере того, как вы будете проявлять себя в Весах Песков.',`offerrewardtext_loc8`);
