INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (10463,'Посвящение в мудрецы','Ты $Gверен:уверена;, что хочешь избрать этот путь, $N? Он будет нелегким, так что трижды подумай, прежде чем примешь решение.$B$BВ этом кольце заключена капля воды из Источника Вечности. Его сила возрастет, когда ты заслужишь доверие драконов Песчаной Чешуи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посвящение в мудрецы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gверен:уверена;, что хочешь избрать этот путь, $N? Он будет нелегким, так что трижды подумай, прежде чем примешь решение.$B$BВ этом кольце заключена капля воды из Источника Вечности. Его сила возрастет, когда ты заслужишь доверие драконов Песчаной Чешуи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (10464,'Обет мудреца','Ты $gвыбрал:избрала; свой путь и $gдал:дала; обет. Теперь все зависит только от тебя, |3-6($c).$B$BБудешь верой и правдой служить драконам Песчаной Чешуи – получишь щедрую награду. Но помни: если ты не сумеешь исполнить свою задачу, линия времени будет разрушена, и ход истории изменится!','Ты оправдал наше доверие, |3-6($R). Во всяком случае, до сих пор у нас не было повода усомниться в тебе.$B$BУчти, что доверие супруги и помощницы Ноздорму непросто заслужить.','Ты по-прежнему служишь нам верой и правдой, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обет мудреца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвыбрал:избрала; свой путь и $gдал:дала; обет. Теперь все зависит только от тебя, |3-6($c).$B$BБудешь верой и правдой служить драконам Песчаной Чешуи – получишь щедрую награду. Но помни: если ты не сумеешь исполнить свою задачу, линия времени будет разрушена, и ход истории изменится!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты оправдал наше доверие, |3-6($R). Во всяком случае, до сих пор у нас не было повода усомниться в тебе.$B$BУчти, что доверие супруги и помощницы Ноздорму непросто заслужить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты по-прежнему служишь нам верой и правдой, $N.',`requestitemstext_loc8`);
