INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (10467,'Обет защитника','Ты $gвыбрал:избрала; свой путь и $gдал:дала; обет. Теперь все зависит только от тебя, |3-6($c).$B$BБудешь верой и правдой служить драконам Песчаной Чешуи – получишь щедрую награду. Но помни: если ты не сумеешь исполнить свою задачу, линия времени будет разрушена, и ход истории изменится!','Ты $Gоправдал:оправдала; наше доверие, |3-6($R). Во всяком случае, до сих пор у нас не было повода усомниться в тебе.$B$BУчти, что доверие супруги и помощницы Ноздорму непросто заслужить.','Ты по-прежнему служишь нам верой и правдой, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обет защитника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвыбрал:избрала; свой путь и $gдал:дала; обет. Теперь все зависит только от тебя, |3-6($c).$B$BБудешь верой и правдой служить драконам Песчаной Чешуи – получишь щедрую награду. Но помни: если ты не сумеешь исполнить свою задачу, линия времени будет разрушена, и ход истории изменится!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gоправдал:оправдала; наше доверие, |3-6($R). Во всяком случае, до сих пор у нас не было повода усомниться в тебе.$B$BУчти, что доверие супруги и помощницы Ноздорму непросто заслужить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты по-прежнему служишь нам верой и правдой, $N.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (10468,'Клятва мудреца','Ты $gсдержал:сдержала; данное нам обещание, $n. Теперь мы знаем, чего ты стоишь.$B$BПока ты будешь странствовать во времени и охранять от вмешательства прошлое горы Хиджал, я наполню силой твое кольцо. Ждать осталось недолго – уже очень скоро оно обретет свою полную силу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клятва мудреца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсдержал:сдержала; данное нам обещание, $n. Теперь мы знаем, чего ты стоишь.$B$BПока ты будешь странствовать во времени и охранять от вмешательства прошлое горы Хиджал, я наполню силой твое кольцо. Ждать осталось недолго – уже очень скоро оно обретет свою полную силу.',`details_loc8`);
