INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (10472,'Договор мудреца','То, что ты $gсделал:сделала;, превзошло все мои ожидания, $n.$B$BТы перемещаешься во времени так же легко и свободно, как любой из бронзовых драконов. Ты $gсоздан:создана; для великой силы, и я рада помочь тебе обрести ее в полной мере.$B$BПродолжай верой и правдой служить драконам Песчаной Чешуи, и я сделаю так, чтобы твой дар обрел полную силу.','Ты пребываешь в единстве со временем, $N. Ты – $Gодин:одна; из нас. В капле воды из Источника Вечности заключена величайшая сила, превосходящая воображение смертных.$B$BПрими этот дар, и пусть все знают, что ты $Gзаключил:заключила; договор с драконами Песчаной Чешуи... а это значит, что ты $Gзаключил:заключила; договор с самим временем.','Пусть время всегда работает на тебя, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Договор мудреца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, что ты $gсделал:сделала;, превзошло все мои ожидания, $n.$B$BТы перемещаешься во времени так же легко и свободно, как любой из бронзовых драконов. Ты $gсоздан:создана; для великой силы, и я рада помочь тебе обрести ее в полной мере.$B$BПродолжай верой и правдой служить драконам Песчаной Чешуи, и я сделаю так, чтобы твой дар обрел полную силу.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты пребываешь в единстве со временем, $N. Ты – $Gодин:одна; из нас. В капле воды из Источника Вечности заключена величайшая сила, превосходящая воображение смертных.$B$BПрими этот дар, и пусть все знают, что ты $Gзаключил:заключила; договор с драконами Песчаной Чешуи... а это значит, что ты $Gзаключил:заключила; договор с самим временем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пусть время всегда работает на тебя, $N.',`requestitemstext_loc8`);
