INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10701,'Низвергнуть Глыбня Пустоты','Какие? Что?! Быстрее ... Здесь так много дел.$B$BЯ хочу когда-нибудь сдвинуть эту штуку с мертвой точки, понимаешь?','Вернитесь к командующему ракетами Фьюзеляжу в Зону 52, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Низвергнуть Глыбня Пустоты',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какие? Что?! Быстрее ... Здесь так много дел.$B$BЯ хочу когда-нибудь сдвинуть эту штуку с мертвой точки, понимаешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командующему ракетами Фьюзеляжу в Зону 52, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10702,'Наряд вне очереди','Все силы Орды сейчас сплотились, дабы отражать атаки Легиона. Это значит, что у нас не хватает рук, чтобы выполнять подсобные работы.$B$BНашим караванам постоянно угрожает какая-то живность. Они пару метров не могут проехать по дороге, чтобы не наткнуться на химеру, скверносквина или скорпиона-переростка.$B$BОтправляйся туда и очисти Долину Призрачной Луны от чрезмерно агрессивной живности. Просто убей всех, кого сможешь.','Убейте 20 тварей, водящихся в Долине Призрачной Луны для Властителя Ор\'барокха.$B$BТварями считаются скверносвины, мерзкокрылые химеры и огнепанцирные клешневики. Соотношение может быть любым.','Блестяще! Когда нам снова понадобятся услуги чистильщика, я найду тебя.','Возвращайся ко мне, когда наши караваны перейдут в безопасные дебри.','Вернитесь к властителю Ор\'барокху в Деревню Призрачной Луны, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наряд вне очереди',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все силы Орды сейчас сплотились, дабы отражать атаки Легиона. Это значит, что у нас не хватает рук, чтобы выполнять подсобные работы.$B$BНашим караванам постоянно угрожает какая-то живность. Они пару метров не могут проехать по дороге, чтобы не наткнуться на химеру, скверносквина или скорпиона-переростка.$B$BОтправляйся туда и очисти Долину Призрачной Луны от чрезмерно агрессивной живности. Просто убей всех, кого сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 тварей, водящихся в Долине Призрачной Луны для Властителя Ор\'барокха.$B$BТварями считаются скверносвины, мерзкокрылые химеры и огнепанцирные клешневики. Соотношение может быть любым.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Блестяще! Когда нам снова понадобятся услуги чистильщика, я найду тебя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Возвращайся ко мне, когда наши караваны перейдут в безопасные дебри.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Ор\'барокху в Деревню Призрачной Луны, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10703,'Зачистка','Пришло время спускаться с небес на землю и слегка запачкаться. А чего ты $gждал:ждала;, а? Прежде чем начать ползать, придется сначала научиться ходить, как думаешь? Хм... разверни это!$B$BПо-любому, пришло время свистать всех наверх и разбираться с теми отбросами, которые посылает на нас Легион. А тебе придется взять на себя почетную обязанность почистить окружающее пространство от всяких диких тварей.$B$BБери меч, доспех, чего там тебе еще надо для полного счастья, отправляйся и убей всю живность, которая попадется на пути, чтобы наши караваны могли беспрепятственно продвигаться по долине.','Убейте 20 тварей, водящихся в Долине Призрачной Луны, для Тана Йорегара из Цитадели Громового Молота.$B$BТварями считаются скверносвины, мерзкокрылые химеры и огнепанцирные клешневики. Соотношение может быть любым.','Ха! Превосходно! Вот плата за твои труды, если нам потребуются еще чистильщики, мы с тобой свяжемся.','Вернитесь к Тану Йорегару в Цитадель Громового Молота, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пришло время спускаться с небес на землю и слегка запачкаться. А чего ты $gждал:ждала;, а? Прежде чем начать ползать, придется сначала научиться ходить, как думаешь? Хм... разверни это!$B$BПо-любому, пришло время свистать всех наверх и разбираться с теми отбросами, которые посылает на нас Легион. А тебе придется взять на себя почетную обязанность почистить окружающее пространство от всяких диких тварей.$B$BБери меч, доспех, чего там тебе еще надо для полного счастья, отправляйся и убей всю живность, которая попадется на пути, чтобы наши караваны могли беспрепятственно продвигаться по долине.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 тварей, водящихся в Долине Призрачной Луны, для Тана Йорегара из Цитадели Громового Молота.$B$BТварями считаются скверносвины, мерзкокрылые химеры и огнепанцирные клешневики. Соотношение может быть любым.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха! Превосходно! Вот плата за твои труды, если нам потребуются еще чистильщики, мы с тобой свяжемся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тану Йорегару в Цитадель Громового Молота, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10704,'Как проникнуть в Аркатрац','Принесите А\'далу верхний и нижний обломок ключа Аркатраца, чтобы он собрал из них целый ключ.','Я впечатлён, $N, хотя именно этого и следовало ожидать от $Gгероя:героини;, $Gкоторый:которая; $Gвернул:вернула; нам кристалл Ата\'мала.$B$BДай мне обломки, и я соединю их вместе. Тогда тебе будет открыт доступ в Аркатрац.','<В вашей голове раздаётся мелодичный голос А\'дала.>$B$BТы $Gвернулся:вернулась;. $GПринёс:Принесла; ли ты два обломка ключа от Аркатраца?','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как проникнуть в Аркатрац',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите А\'далу верхний и нижний обломок ключа Аркатраца, чтобы он собрал из них целый ключ.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я впечатлён, $N, хотя именно этого и следовало ожидать от $Gгероя:героини;, $Gкоторый:которая; $Gвернул:вернула; нам кристалл Ата\'мала.$B$BДай мне обломки, и я соединю их вместе. Тогда тебе будет открыт доступ в Аркатрац.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<В вашей голове раздаётся мелодичный голос А\'дала.>$B$BТы $Gвернулся:вернулась;. $GПринёс:Принесла; ли ты два обломка ключа от Аркатраца?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10705,'Провидец Адало','Найдите провидца Адало в Аркатраце в Крепости Бурь.','Провидец Пеплоустов давно мертв. Перевернув его тело, вы замечаете письмена, нацарапанные на полу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Провидец Адало',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите провидца Адало в Аркатраце в Крепости Бурь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Провидец Пеплоустов давно мертв. Перевернув его тело, вы замечаете письмена, нацарапанные на полу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10706,'Таинственное знамение','Прежде чем умереть, Адало написал на полу возле себя единственное слово, надпись уже почти неразличима, но тебе удается, разобрать слово "Ата\'мал".$B$BВозможно Акама разберется, что имел в виду его брат.','Вернитесь к Акаме в Клеть Стражницы в Долине Призрачной Луны.','Да... Конечно! Теперь все ясно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Таинственное знамение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем умереть, Адало написал на полу возле себя единственное слово, надпись уже почти неразличима, но тебе удается, разобрать слово "Ата\'мал".$B$BВозможно Акама разберется, что имел в виду его брат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Акаме в Клеть Стражницы в Долине Призрачной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да... Конечно! Теперь все ясно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10707,'Терраса Ата\'мала','Отправляйтесь на Террасу Ата\'мала в Долине Призрачной Луны и раздобудьте Сердце Ярости. По выполнении задания вернитесь к Акаме в Клеть Стражницы.','Теперь... Сила кристалла в моих руках!','Ты $Gвернулся:вернулась;, $N.','Вернитесь к Акаме в Клеть Стражницы, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Терраса Ата\'мала',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на Террасу Ата\'мала в Долине Призрачной Луны и раздобудьте Сердце Ярости. По выполнении задания вернитесь к Акаме в Клеть Стражницы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь... Сила кристалла в моих руках!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Акаме в Клеть Стражницы, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10708,'Обещание Акамы','<Акама вставляет кристалл в медальон, который держит в руке.>$B$BЯ уже не так силен как прежде, $n. Так тесно общаться со злом все эти годы, я не уверен, что у меня хватит сил совладать с таким могущественным артефактом.$B$BВозьми его как залог того, что когда ты встретишься лицом к лицу с Иллиданом, я буду на твоей стороне. Отнеси его тому, кому мы можем безоговорочно доверять, А\'далу в Шаттрат.','Принесите медальон Карабора А\'далу в Шаттрат.','<Когда вы отдаете медальон А\'далу, он исчезает в его существе во вспышке света.>$B$B<Вам кратко показывается мгновение... возможно, в будущем. Вы видите, как Акама и Майев выходят из клетки надзирателя, пробираясь к темному храму. Третья фигура, окутанная тенями, помогает им. При ближайшем рассмотрении вы замечаете, что фигура-это вы.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обещание Акамы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Акама вставляет кристалл в медальон, который держит в руке.>$B$BЯ уже не так силен как прежде, $n. Так тесно общаться со злом все эти годы, я не уверен, что у меня хватит сил совладать с таким могущественным артефактом.$B$BВозьми его как залог того, что когда ты встретишься лицом к лицу с Иллиданом, я буду на твоей стороне. Отнеси его тому, кому мы можем безоговорочно доверять, А\'далу в Шаттрат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите медальон Карабора А\'далу в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Когда вы отдаете медальон А\'далу, он исчезает в его существе во вспышке света.>$B$B<Вам кратко показывается мгновение... возможно, в будущем. Вы видите, как Акама и Майев выходят из клетки надзирателя, пробираясь к темному храму. Третья фигура, окутанная тенями, помогает им. При ближайшем рассмотрении вы замечаете, что фигура-это вы.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10709,'Воссоединение','Значит, ты из мира за Порталом? И ты знаешь о Рексаре. Да, я хорошо с ним знаком.$b$bВидишь ли, это мой сын.$b$bНо он сделал свой выбор давным-давно. Он не с нами, и тут ему рады не будут. Нам хватает хлопот с ограми Кровавого Молота.$b$bЗапомни – если в тебе половина крови Мок\'Натала, от этого ты не становишься одним из Мок\'Натал.','Поговорите с Рексаром в Оплоте Громоборцев в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воссоединение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, ты из мира за Порталом? И ты знаешь о Рексаре. Да, я хорошо с ним знаком.$b$bВидишь ли, это мой сын.$b$bНо он сделал свой выбор давным-давно. Он не с нами, и тут ему рады не будут. Нам хватает хлопот с ограми Кровавого Молота.$b$bЗапомни – если в тебе половина крови Мок\'Натала, от этого ты не становишься одним из Мок\'Натал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рексаром в Оплоте Громоборцев в Острогорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10710,'Испытательный полет: Звенящий гребень','Я тут малость похимичил с Конденсаторием зефира и готов осуществить еще одно испытание! Не желаете ли помочь?$B$BЭтот полет будет коротким, но зато каким быстрым!$B$BГм... ну, я уверен, что опасности нет... и все же у меня тут есть один документик, вы уж подпишите. Это всего лишь формальность, честное слово!$B$BУдачи вам, самой большой удачи! Скажите Ралли, пусть он вас запустит, а после эксперимента приходите ко мне!','Подпишите отказ от претензий к Талли, затем поговорите с Ралли Быстроцапом насчет Конденсатория зефира.','Развейте все сомнения по ветру.','Вернитесь к Талли Быстроцапу на Станцию Тошли, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытательный полет: Звенящий гребень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я тут малость похимичил с Конденсаторием зефира и готов осуществить еще одно испытание! Не желаете ли помочь?$B$BЭтот полет будет коротким, но зато каким быстрым!$B$BГм... ну, я уверен, что опасности нет... и все же у меня тут есть один документик, вы уж подпишите. Это всего лишь формальность, честное слово!$B$BУдачи вам, самой большой удачи! Скажите Ралли, пусть он вас запустит, а после эксперимента приходите ко мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подпишите отказ от претензий к Талли, затем поговорите с Ралли Быстроцапом насчет Конденсатория зефира.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Развейте все сомнения по ветру.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талли Быстроцапу на Станцию Тошли, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10711,'Испытательный полет: лагерь Разаана','$n, я повысил эффективность Конденсатория зефира на 30 процентов. А, значит, мне понадобится подопытный субъект вашего веса и более высокое аэродинамическое сопротивление! Хотите проверить мою теорию? Эксперимент потребует от вас полета в окрестности лагеря Разаана.$B$BПоговорите с Ралли... он подготовит вас к полету.','Поговорите с Ралли Быстроцапом насчет использования Конденсатория зефира.','Дотроньтесь до неба.','Вернитесь к Талли Быстроцапу на Станцию Тошли, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытательный полет: лагерь Разаана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я повысил эффективность Конденсатория зефира на 30 процентов. А, значит, мне понадобится подопытный субъект вашего веса и более высокое аэродинамическое сопротивление! Хотите проверить мою теорию? Эксперимент потребует от вас полета в окрестности лагеря Разаана.$B$BПоговорите с Ралли... он подготовит вас к полету.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ралли Быстроцапом насчет использования Конденсатория зефира.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Дотроньтесь до неба.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талли Быстроцапу на Станцию Тошли, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`completedtext_loc8`) VALUES (10712,'Поговорите с О\'малли Быстроцапом в Вечной роще, что в Острогорье.') ON DUPLICATE KEY UPDATE `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с О\'малли Быстроцапом в Вечной роще, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10713,'...и время действовать','Убейте 10 лесорубов Культа Змея.','Вы защитили деревья? Лесорубы убиты?','Вернитесь к хранителю Деревьев Чауну в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','...и время действовать',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 лесорубов Культа Змея.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы защитили деревья? Лесорубы убиты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Деревьев Чауну в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10714,'На крыльях Духа','Если огры Кровавого Молота не дают покоя Мок\'Натал, я остановлю их и их приспешников. Огры просты по натуре, и от преследования Мок\'Натал выгоды им мало.$b$bЗначит, тут другая причина. $n, возьми Духа, моего ястреба, и проследи за переговорами предводителей Кровавого Молота. Там, где нас заметят, на ястреба не обратят внимания.','Найдите занятых разговором ворожея и надсмотрщика из клана Кровавого Молота, затем при помощи свистка Рексара призовите Духа и проследите за ними.','<Дух садится на плечо Рексара, пока тот внимательно слушает.>$B$BЗначит, действия огров направляют сыны Груула! Они натравливают огров Кровавого Молота на Мок\'Натал, говоря, что так они заслужат их благосклонность!','Что тебе удалось узнать, $N?','Вернитесь к Рексару в Оплот Громоборцев, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На крыльях Духа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если огры Кровавого Молота не дают покоя Мок\'Натал, я остановлю их и их приспешников. Огры просты по натуре, и от преследования Мок\'Натал выгоды им мало.$b$bЗначит, тут другая причина. $n, возьми Духа, моего ястреба, и проследи за переговорами предводителей Кровавого Молота. Там, где нас заметят, на ястреба не обратят внимания.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите занятых разговором ворожея и надсмотрщика из клана Кровавого Молота, затем при помощи свистка Рексара призовите Духа и проследите за ними.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Дух садится на плечо Рексара, пока тот внимательно слушает.>$B$BЗначит, действия огров направляют сыны Груула! Они натравливают огров Кровавого Молота на Мок\'Натал, говоря, что так они заслужат их благосклонность!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось узнать, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рексару в Оплот Громоборцев, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10715,'Прогулка в Беспокойную лощину','Значит, Рексар хочет, чтобы я приготовил ему яду? Что же, я исполню его просьбу, но не даром. Дармовщина разрушает дружбу.$B$BСначала тебе придется немного прогуляться на юго-запад, в Беспокойную лощину.$B$BТам обретаются самые ядовитые твари Запределья – да и не только Запределья. Я имею в виду землероев. А яд можно добыть из их ядовитых желез.','Очень хорошо. Простая, прямо-таки тупая часть задачи решена. Теперь давай мне железы, и я займусь самой трудной частью.','Вернитесь к барону Черногриву в Круг Крови, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прогулка в Беспокойную лощину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, Рексар хочет, чтобы я приготовил ему яду? Что же, я исполню его просьбу, но не даром. Дармовщина разрушает дружбу.$B$BСначала тебе придется немного прогуляться на юго-запад, в Беспокойную лощину.$B$BТам обретаются самые ядовитые твари Запределья – да и не только Запределья. Я имею в виду землероев. А яд можно добыть из их ядовитых желез.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Простая, прямо-таки тупая часть задачи решена. Теперь давай мне железы, и я займусь самой трудной частью.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Черногриву в Круг Крови, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10716,'Испытательный полет: Лес Ворона <требует вознаграждения>','Конденсаторий зефира готов к самому долгому полету! Что скажете, $n? Не хотите ли еще разок полетать?$B$BЯ усовершенствовал двигательную систему, но пока я не отлажу все параметры, кондесаторию будет требоваться дополнительное топливо, чтобы получить нужный первоначальный импульс! Поговорите перед вылетом с Ралли – он знает все детали.$B$BУдачи вам, $n. Полет заведет вас в далекий Лес Ворона. Переживете полет – и унесете ноги от лесных огров и араккоа – возвращайтесь, и мы отпразднуем успех!','Поговорите с Ралли Быстроцапом насчет использования Конденсатория зефира. Вернитесь к Талли Быстроцапу на станцию Тошли.','Отправьтесь в опасный полет.','Вернитесь к Талли Быстроцапу на Станцию Тошли, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытательный полет: Лес Ворона <требует вознаграждения>',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Конденсаторий зефира готов к самому долгому полету! Что скажете, $n? Не хотите ли еще разок полетать?$B$BЯ усовершенствовал двигательную систему, но пока я не отлажу все параметры, кондесаторию будет требоваться дополнительное топливо, чтобы получить нужный первоначальный импульс! Поговорите перед вылетом с Ралли – он знает все детали.$B$BУдачи вам, $n. Полет заведет вас в далекий Лес Ворона. Переживете полет – и унесете ноги от лесных огров и араккоа – возвращайтесь, и мы отпразднуем успех!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ралли Быстроцапом насчет использования Конденсатория зефира. Вернитесь к Талли Быстроцапу на станцию Тошли.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отправьтесь в опасный полет.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Талли Быстроцапу на Станцию Тошли, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10717,'Вор у вора...','Добудьте 5 сетей Культа Змея.','Как добыча сетей? Судя по тому, что я видела, сети у этих браконьеров достаточно крепкие, чтобы сгодиться для наших целей.','Вернитесь к Самии Недомолвке в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вор у вора...',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 сетей Культа Змея.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как добыча сетей? Судя по тому, что я видела, сети у этих браконьеров достаточно крепкие, чтобы сгодиться для наших целей.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Самии Недомолвке в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10718,'У духов есть голоса','$n, теперь, когда ты меня видишь, тебе будет что сказать Рексару. Я знаю, что он ищет свой народ, и я знаю, где он живет.$B$BМок\'Натал, как их называют, построили деревню на востоке за Островерхим гребнем.$B$BИди, передай Рексару эту весть. Его народ в опасности, и я знаю, что он бросится им на помощь.','Поговорите с Рексаром в Оплоте Громоборцев в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У духов есть голоса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, теперь, когда ты меня видишь, тебе будет что сказать Рексару. Я знаю, что он ищет свой народ, и я знаю, где он живет.$B$BМок\'Натал, как их называют, построили деревню на востоке за Островерхим гребнем.$B$BИди, передай Рексару эту весть. Его народ в опасности, и я знаю, что он бросится им на помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рексаром в Оплоте Громоборцев в Острогорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (10719,'Где записка?','Эту записку доставил служитель культа. Похоже, ее надо доставить надзирателю Нуаару. Она подписана каким-то Колфисом Черной Чешуей.$B$BПохоже, это может заинтересовать хранителя деревьев Чауна.','Отдайте записку о встрече хранителю деревьев Чауну в Вечную рощу в Острогорье.','Что это у нас тут? А это не пятно ли крови на записке?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Где записка?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эту записку доставил служитель культа. Похоже, ее надо доставить надзирателю Нуаару. Она подписана каким-то Колфисом Черной Чешуей.$B$BПохоже, это может заинтересовать хранителя деревьев Чауна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте записку о встрече хранителю деревьев Чауну в Вечную рощу в Острогорье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у нас тут? А это не пятно ли крови на записке?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10720,'Самые маленькие создания','Огры существа простые, но все же они заметят, что ты рассыпаешь яд по их лагерю. Я научу тебя, как в этом случае воспользоваться помощью самых маленьких творений природы.$b$bВыбив на этом барабане простейший ритм, ты приманишь сурка, и он будет выполнять твои приказы.$b$bРядом с лагерем Кровавого Молота на севере, у каньона Кинжальной Пасти, за Кругом Крови, в норах живут сурки.$B$BПримани сурков, пусть они подсыплют яда в бочки клана Кровавого Молота.','Ударьте в барабан из шкуры кодо возле норы сурка. Держа сурка под контролем, насыпьте яду в три бочонка в лагере Кровавого Молота.','Долгие годы я пытался усовершенствовать способы общения с природой. Это только малая часть еще нераскрытых возможностей творений природы, которые могут пойти на пользу тебе.','Вернитесь к Рексару в Оплот Громоборцев, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самые маленькие создания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Огры существа простые, но все же они заметят, что ты рассыпаешь яд по их лагерю. Я научу тебя, как в этом случае воспользоваться помощью самых маленьких творений природы.$b$bВыбив на этом барабане простейший ритм, ты приманишь сурка, и он будет выполнять твои приказы.$b$bРядом с лагерем Кровавого Молота на севере, у каньона Кинжальной Пасти, за Кругом Крови, в норах живут сурки.$B$BПримани сурков, пусть они подсыплют яда в бочки клана Кровавого Молота.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ударьте в барабан из шкуры кодо возле норы сурка. Держа сурка под контролем, насыпьте яду в три бочонка в лагере Кровавого Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Долгие годы я пытался усовершенствовать способы общения с природой. Это только малая часть еще нераскрытых возможностей творений природы, которые могут пойти на пользу тебе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рексару в Оплот Громоборцев, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10721,'Подложим Груллоку свинью','$n, есть у меня питомец-вепрь по имени Хаффер. Он хочет помочь тебе обдурить одного из тутошних сынков Груула.$B$BГруллок живет в местечке под названием Окаянная лощина. Как доберешься дотуда, выпусти Хаффера. Гронн начнет его гонять по округе, а ты потихоньку стяни его мешок и отнеси его барону Черногриву.$B$BЧтобы добраться до Окаянной лощины, иди вниз по северному склону и на восток через Драконью Пагубу. Лощина на ее восточной окраине.','Добудьте мешок Груллока.','Вернитесь к барону Черногриву в Круг Крови, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подложим Груллоку свинью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, есть у меня питомец-вепрь по имени Хаффер. Он хочет помочь тебе обдурить одного из тутошних сынков Груула.$B$BГруллок живет в местечке под названием Окаянная лощина. Как доберешься дотуда, выпусти Хаффера. Гронн начнет его гонять по округе, а ты потихоньку стяни его мешок и отнеси его барону Черногриву.$B$BЧтобы добраться до Окаянной лощины, иди вниз по северному склону и на восток через Драконью Пагубу. Лощина на ее восточной окраине.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте мешок Груллока.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Черногриву в Круг Крови, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10722,'Встреча в пещере Крыла Тьмы','Это необходимо сделать! $n, ты $Gобязан:обязана; выдать себя за надзирателя Нуаара и побывать на этой встрече!$B$BСлужители Культа Змея в ковене носят стандартное облачение, так что просто собери детали их одежды, и когда у тебя будет их достаточно, надень их.$B$BВыдай себя за инспектора Нуаара и поговори с Колфисом Черной Чешуей, чтобы узнать, что он скажет, а потом возвращайся к хранителю деревьев Чауну.$B$BКовен ты найдешь за туннелем Драконьего черепа, если пойдешь по тропе мимо Леса Ворона и Гришната до конца.','Соберите костюм инспектора из деталей одежды, собранных у различных адептов Культа Змея. Отправьтесь в этом костюме на встречу с Колфисом Черной Чешуей.','Встретьтесь с Колфисом Черной Чешуей.','Вернитесь к хранителю Деревьев Чауну в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча в пещере Крыла Тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это необходимо сделать! $n, ты $Gобязан:обязана; выдать себя за надзирателя Нуаара и побывать на этой встрече!$B$BСлужители Культа Змея в ковене носят стандартное облачение, так что просто собери детали их одежды, и когда у тебя будет их достаточно, надень их.$B$BВыдай себя за инспектора Нуаара и поговори с Колфисом Черной Чешуей, чтобы узнать, что он скажет, а потом возвращайся к хранителю деревьев Чауну.$B$BКовен ты найдешь за туннелем Драконьего черепа, если пойдешь по тропе мимо Леса Ворона и Гришната до конца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите костюм инспектора из деталей одежды, собранных у различных адептов Культа Змея. Отправьтесь в этом костюме на встречу с Колфисом Черной Чешуей.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Встретьтесь с Колфисом Черной Чешуей.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Деревьев Чауну в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10723,'Горгром Драконоед','Добудьте 3 тотема гризли у огров Камен\'мока. Поставьте ловушку Черногрива на алтарь Горгрома, затем призовите и убейте Горгрома Драконоеда.$b$bКогда Горгром будет убит, поставьте 3 тотема гризли возле его туши.','Огры Кровавого Молота и их хозяин Горгром теперь не будут угрожать Мок\'Наталу.$B$BИ все же я неспокоен, когда размышляю о влиянии наших действий на других гроннов. Сдается мне, надо покончить с этой войной раз и навсегда.','Когда дело будет сделано, огры Кровавого Молота больше нас не потревожат.','Вернитесь к Рексару в Оплот Громоборцев, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горгром Драконоед',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 тотема гризли у огров Камен\'мока. Поставьте ловушку Черногрива на алтарь Горгрома, затем призовите и убейте Горгрома Драконоеда.$b$bКогда Горгром будет убит, поставьте 3 тотема гризли возле его туши.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Огры Кровавого Молота и их хозяин Горгром теперь не будут угрожать Мок\'Наталу.$B$BИ все же я неспокоен, когда размышляю о влиянии наших действий на других гроннов. Сдается мне, надо покончить с этой войной раз и навсегда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда дело будет сделано, огры Кровавого Молота больше нас не потревожат.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рексару в Оплот Громоборцев, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (10725,'Аметистовое Око в восхищении','Твои достижения на службе Аметистовому Оку превзошли все наши ожидания, $n. Ты всего лишь на шаг отстоишь от самых высоких почестей, оказываемых в Даларане чужестранцам. $B$BПродолжай служить нам верой и правдой, и я увеличу мощь твоего перстня до предела.','Теперь твой перстень сравнялся по силе с перстнем любого из верховных магов Совета. Носи его, не снимая. По нему посвященный признает, чьим союзником ты являешься. И пусть сила послужить тебе добром, так же, как ты $Gслужил:служила; нам!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аметистовое Око в восхищении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои достижения на службе Аметистовому Оку превзошли все наши ожидания, $n. Ты всего лишь на шаг отстоишь от самых высоких почестей, оказываемых в Даларане чужестранцам. $B$BПродолжай служить нам верой и правдой, и я увеличу мощь твоего перстня до предела.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь твой перстень сравнялся по силе с перстнем любого из верховных магов Совета. Носи его, не снимая. По нему посвященный признает, чьим союзником ты являешься. И пусть сила послужить тебе добром, так же, как ты $Gслужил:служила; нам!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10726,'Аметистовое Око в восхищении','Твои достижения на службе Аметистовому Оку превзошли все наши ожидания, $n. Ты всего лишь на шаг отстоишь от самых высоких почестей, оказываемых в Даларане чужестранцам. $B$BПродолжай служить нам верой и правдой, и я увеличу мощь твоего перстня до предела.','Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить полное доверие Аметистового Ока.','Теперь твой перстень сравнялся по силе с перстнем любого из верховных магов Совета. Носи его, не снимая. По нему посвященный признает, чьим союзником ты являешься. И пусть сила послужить тебе добром, так же, как ты $Gслужил:служила; нам!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аметистовое Око в восхищении',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои достижения на службе Аметистовому Оку превзошли все наши ожидания, $n. Ты всего лишь на шаг отстоишь от самых высоких почестей, оказываемых в Даларане чужестранцам. $B$BПродолжай служить нам верой и правдой, и я увеличу мощь твоего перстня до предела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить полное доверие Аметистового Ока.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь твой перстень сравнялся по силе с перстнем любого из верховных магов Совета. Носи его, не снимая. По нему посвященный признает, чьим союзником ты являешься. И пусть сила послужить тебе добром, так же, как ты $Gслужил:служила; нам!',`offerrewardtext_loc8`);
