INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (10729,'Маг из Аметистового Ока','Ты $Gуверен:уверена; в своем решении, $N? Тебе предстоит сделать очень непростой выбор.$B$BСила перстня Аметистового Ока станет возрастать по мере того, как ты будешь доказывать нам свою преданность.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маг из Аметистового Ока',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gуверен:уверена; в своем решении, $N? Тебе предстоит сделать очень непростой выбор.$B$BСила перстня Аметистового Ока станет возрастать по мере того, как ты будешь доказывать нам свою преданность.',`offerrewardtext_loc8`);
