INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (10733,'Путь Аметистового Ока','Ты $gвыбрал:выбрала; свой путь, |3-6($c). Следуй же ему, куда бы он тебя ни привел.$B$BЕсть свои преимущества в том, чтобы иметь друзей среди верховных магов Даларана. Если будешь служить нам верой и правдой, мы щедро наградим тебя.','Ты оказываешь нам честь своей службой, $N. Смотри, как я высвобождаю силу, заключенную в твоей печатке!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Аметистового Ока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gвыбрал:выбрала; свой путь, |3-6($c). Следуй же ему, куда бы он тебя ни привел.$B$BЕсть свои преимущества в том, чтобы иметь друзей среди верховных магов Даларана. Если будешь служить нам верой и правдой, мы щедро наградим тебя.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты оказываешь нам честь своей службой, $N. Смотри, как я высвобождаю силу, заключенную в твоей печатке!',`offerrewardtext_loc8`);
