INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10737,'Разрешение учителя','Я сумел воссоздать ключ, которым пользовался, будучи учеником. Выглядит он полностью рабочим – насколько это возможно для ключа. Но Каражан им отпереть не проще, чем обычным куском металлолома. $B$BБез согласия Медива любой ключ будет всего лишь никчемной железкой. Да, я знаю, что Медив мертв. Но это всего лишь усложняет ситуацию, а не делает ее неразрешимой. $B$BВ Азероте есть место, называемое Пещерами Времени. Их охраняют Бронзовые драконы. Проберись внутрь, вернись в прошлое и уговори Медива дать мне возможность пользоваться этим ключом.','Отправляйтесь в Пещеры Времени и уговорите Медива разрешить пользоваться восстановленным ключом ученика.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрешение учителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сумел воссоздать ключ, которым пользовался, будучи учеником. Выглядит он полностью рабочим – насколько это возможно для ключа. Но Каражан им отпереть не проще, чем обычным куском металлолома. $B$BБез согласия Медива любой ключ будет всего лишь никчемной железкой. Да, я знаю, что Медив мертв. Но это всего лишь усложняет ситуацию, а не делает ее неразрешимой. $B$BВ Азероте есть место, называемое Пещерами Времени. Их охраняют Бронзовые драконы. Проберись внутрь, вернись в прошлое и уговори Медива дать мне возможность пользоваться этим ключом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Пещеры Времени и уговорите Медива разрешить пользоваться восстановленным ключом ученика.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (10738,'Достойное служение','Ты не $gразочаровал:разочаровала; нас, $n. Мы продолжаем возлагать на тебя самые большие надежды. $B$BПродолжай служить Аметистовому Оку, и тебя ждет достойное вознаграждение.','Твое служение не осталось незамеченным, $N. Этот перстень внешне не изменяется, но сила его возрастает по мере того, как ты доказываешь нам свою преданность.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойное служение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты не $gразочаровал:разочаровала; нас, $n. Мы продолжаем возлагать на тебя самые большие надежды. $B$BПродолжай служить Аметистовому Оку, и тебя ждет достойное вознаграждение.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твое служение не осталось незамеченным, $N. Этот перстень внешне не изменяется, но сила его возрастает по мере того, как ты доказываешь нам свою преданность.',`offerrewardtext_loc8`);
