INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (10743,'[DEPRECATED]<txt>Герой Мок\'Натала') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]<txt>Герой Мок\'Натала',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10744,'Вести о Победе','Вы должны немедленно известить о нашем успехе Курдрана Громового Молота! Его солдаты под командой командира звена Нуаинна сражались без устали, чтобы удержать цитадель Громового Молота, и ваше возвращение, конечно, их обрадует. Теперь, когда угрозы от легиона больше не существует, Курдран может, наконец, начать разбираться с войсками Иллидана. Здесь у нас не то, чтобы совсем безопасно, но сегодня мы выиграли переломное сражение.','Вернитесь в Цитадель Громового Молота и поговорите с Курдраном.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вести о Победе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы должны немедленно известить о нашем успехе Курдрана Громового Молота! Его солдаты под командой командира звена Нуаинна сражались без устали, чтобы удержать цитадель Громового Молота, и ваше возвращение, конечно, их обрадует. Теперь, когда угрозы от легиона больше не существует, Курдран может, наконец, начать разбираться с войсками Иллидана. Здесь у нас не то, чтобы совсем безопасно, но сегодня мы выиграли переломное сражение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в Цитадель Громового Молота и поговорите с Курдраном.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10745,'Вести о Победе','Вы должны немедленно известить о нашем успехе властителя Ор\'барокха! Теперь, когда мы сокрушили Легион и стерли даже следы его присутствия в Долине Призрачной Луны, Властитель может, наконец, обратить внимание на других врагов. Хотя стража Кор\'крона никогда в этом не признается, они будут рады, что мы больше не воюем на два фронта.','Возвращайтесь в Деревню Призрачной Луны и поговорите с властителем Ор\'барокхом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вести о Победе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы должны немедленно известить о нашем успехе властителя Ор\'барокха! Теперь, когда мы сокрушили Легион и стерли даже следы его присутствия в Долине Призрачной Луны, Властитель может, наконец, обратить внимание на других врагов. Хотя стража Кор\'крона никогда в этом не признается, они будут рады, что мы больше не воюем на два фронта.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь в Деревню Призрачной Луны и поговорите с властителем Ор\'барокхом.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10746,'DEPRECATED Каражан: LAB – E – Exalted Ring – заклинатель','То, что тебе удалось сделать, превзошло все мои ожидания, $n.$B$BТы перемещаешься по времени так же легко, как любой из бронзовых драконов. Ты $gсоздан:создана; для великой силы, и я рада помочь тебе обрести ее. Продолжай служить нам, и я сделаю так, чтобы твой дар обрел полную силу.','Принесите свое кольцо Вечности Соридорми в Пещеры Времени. Однако прежде необходимо заслужить полное доверие драконов Песчаной Чешуи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','DEPRECATED Каражан: LAB – E – Exalted Ring – заклинатель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, что тебе удалось сделать, превзошло все мои ожидания, $n.$B$BТы перемещаешься по времени так же легко, как любой из бронзовых драконов. Ты $gсоздан:создана; для великой силы, и я рада помочь тебе обрести ее. Продолжай служить нам, и я сделаю так, чтобы твой дар обрел полную силу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите свое кольцо Вечности Соридорми в Пещеры Времени. Однако прежде необходимо заслужить полное доверие драконов Песчаной Чешуи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10747,'Дракончики Культа Змея','Поймайте 10 черных дракончиков Культа Змея при помощи сети.','У вас не возникло сложностей при ловле дракончиков? Надеюсь, вы не обожглись!','Вернитесь к Самии Недомолвке в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дракончики Культа Змея',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 10 черных дракончиков Культа Змея при помощи сети.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У вас не возникло сложностей при ловле дракончиков? Надеюсь, вы не обожглись!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Самии Недомолвке в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10748,'Да сгинет Макснар!','Убейте Макснара Бледную Пасть.','Вернитесь к хранителю Деревьев Чауну в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Да сгинет Макснар!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Макснара Бледную Пасть.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю Деревьев Чауну в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (10749,'Яд барона Черногрива','Вот, отнеси своему хозяину. Уверен, что Рексар употребит его по делу.$B$BО, не забудь ему напомнить, что он мне должен.$B$BОн знает, чего я хочу, и поскольку он намерен добыть это для меня, то мы с тобой встретимся быстрее, чем ты думаешь.$B$BА теперь будь $gхорошим мальчиком:хорошей девочкой; – бегом к Рексару!','Доставьте яд барона Черногиива Рексару в Оплот Громоборцев в Острогорье.','Грязное это дело – ядами травить. Но я сделаю, как он хочет.','|3-6($C), ты так быстро $Gвернулся:вернулась;? Яд при тебе?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Яд барона Черногрива',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, отнеси своему хозяину. Уверен, что Рексар употребит его по делу.$B$BО, не забудь ему напомнить, что он мне должен.$B$BОн знает, чего я хочу, и поскольку он намерен добыть это для меня, то мы с тобой встретимся быстрее, чем ты думаешь.$B$BА теперь будь $gхорошим мальчиком:хорошей девочкой; – бегом к Рексару!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте яд барона Черногиива Рексару в Оплот Громоборцев в Острогорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Грязное это дело – ядами травить. Но я сделаю, как он хочет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','|3-6($C), ты так быстро $Gвернулся:вернулась;? Яд при тебе?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10750,'Путь Завоевания','От моих всадников на ветрокрылах пришли сведения, $n. Эльфы крови лагеря Затмения затевают что-то гадкое. Они начали сосредотачивать свои силы на Пути Завоевания, далеко на юго-востоке отсюда возле Лагеря Затмения.$B$BЯ хочу, чтобы ты $gотправился туда и разобрался:отправилась туда и разобралась;, что они затевают. Когда закончишь, используй сигнальное ружье, чтобы подать сигнал всаднику. Передай ему все, что тебе удастся узнать и получи от него следующий приказ.','Путь Завоевания обнаружен','Воспользуйтесь кор\'кронским сигнальным ружьем, чтобы подать сигнал всаднику на ветрокрыле.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у властителя Ор\'барокха в деревне Призрачной Луны, что в долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Завоевания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','От моих всадников на ветрокрылах пришли сведения, $n. Эльфы крови лагеря Затмения затевают что-то гадкое. Они начали сосредотачивать свои силы на Пути Завоевания, далеко на юго-востоке отсюда возле Лагеря Затмения.$B$BЯ хочу, чтобы ты $gотправился туда и разобрался:отправилась туда и разобралась;, что они затевают. Когда закончишь, используй сигнальное ружье, чтобы подать сигнал всаднику. Передай ему все, что тебе удастся узнать и получи от него следующий приказ.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Путь Завоевания обнаружен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь кор\'кронским сигнальным ружьем, чтобы подать сигнал всаднику на ветрокрыле.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у властителя Ор\'барокха в деревне Призрачной Луны, что в долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10751,'Перерезанный путь','Нам нужно больше времени, |3-6($r). Я собираюсь лететь вперед с другими всадниками. Хотелось бы надеяться, что мы сможем раздобыть еще немного информации. Что мне нужно от тебя, это очистить нам путь и, что самое главное, удержать их стрелков подальше от нас!$B$BВызови одного из всадников на ветрокрылах с помощью кор\'кронского сигнального ружья, когда ты подсчитаешь точное их число.','Убейте 20 солдат, 10 кавалеристов и 10 чароплетов лагеря Затмения.','Воспользуйтесь кор\'кронским сигнальным ружьем, чтобы подать сигнал всаднику на ветрокрыле.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у властителя Ор\'барокха в деревне Призрачной Луны, что в долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перерезанный путь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам нужно больше времени, |3-6($r). Я собираюсь лететь вперед с другими всадниками. Хотелось бы надеяться, что мы сможем раздобыть еще немного информации. Что мне нужно от тебя, это очистить нам путь и, что самое главное, удержать их стрелков подальше от нас!$B$BВызови одного из всадников на ветрокрылах с помощью кор\'кронского сигнального ружья, когда ты подсчитаешь точное их число.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 солдат, 10 кавалеристов и 10 чароплетов лагеря Затмения.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь кор\'кронским сигнальным ружьем, чтобы подать сигнал всаднику на ветрокрыле.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у властителя Ор\'барокха в деревне Призрачной Луны, что в долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10752,'Вперед, в Ясеневый лес','Недавно Раэна Волкопас проходила из Дарнаса через Аубердин, направляясь в Ясеневый лес. Она говорила что-то о фурболгах. Мне не удалось расспросить ее поподробнее, но, возможно, ты сумеешь ее найти и предложить ей помощь, |3-6($c). Иди из Аубердина по южной дороге. Как только доберешься до границы Ясеневого леса, продолжай идти по дороге. Там ты найдешь Астранаар и Раэну Волкопаса.','Поговорите с Раэной Волкопас в Астранааре.','Значит, Тандрис Ветропряд все еще считает, что мне нужна нянька? Надо бы ему напомнить, кто кого спасал – похоже, он забыл, что это я вытащила его из беды.$B$BНо хорошо, что ты сейчас здесь, |3-6($r), возможно, я найду для тебя дело.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вперед, в Ясеневый лес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно Раэна Волкопас проходила из Дарнаса через Аубердин, направляясь в Ясеневый лес. Она говорила что-то о фурболгах. Мне не удалось расспросить ее поподробнее, но, возможно, ты сумеешь ее найти и предложить ей помощь, |3-6($c). Иди из Аубердина по южной дороге. Как только доберешься до границы Ясеневого леса, продолжай идти по дороге. Там ты найдешь Астранаар и Раэну Волкопаса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Раэной Волкопас в Астранааре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Тандрис Ветропряд все еще считает, что мне нужна нянька? Надо бы ему напомнить, кто кого спасал – похоже, он забыл, что это я вытащила его из беды.$B$BНо хорошо, что ты сейчас здесь, |3-6($r), возможно, я найду для тебя дело.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10753,'Зачистка пустоши','Неисчислимы злодеяния Пылающего Легиона. Даже сейчас, пока мы говорим, они посылают свои полчища против здешних животных. Беспомощные перед ними, они гибнут одно за другим. $n, помоги мне прекратить эти преступления против природы, которую они поражают порчей! $B$BНа востоке отсюда, за холмом, ты увидишь, как порча расползается по лощине Клинков. Убей тех, кто совершил это злодеяние, осквернителей – а заодно и Скверноподданных, сколько получится.','Убейте 4 скверноподданных чешуекрылых змеев, 4 скверноподданных из каньона Кинжальной Пасти и 2 осквернителей.','Нет во мне радости, ибо мы убиваем сотворённых Элуной, но распространение порчи надо остановить. Ты $Gсделал:сделала; благое дело, $C.','Справедливость восторжествовала?','Вернитесь к Фарадрелле в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистка пустоши',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неисчислимы злодеяния Пылающего Легиона. Даже сейчас, пока мы говорим, они посылают свои полчища против здешних животных. Беспомощные перед ними, они гибнут одно за другим. $n, помоги мне прекратить эти преступления против природы, которую они поражают порчей! $B$BНа востоке отсюда, за холмом, ты увидишь, как порча расползается по лощине Клинков. Убей тех, кто совершил это злодеяние, осквернителей – а заодно и Скверноподданных, сколько получится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 скверноподданных чешуекрылых змеев, 4 скверноподданных из каньона Кинжальной Пасти и 2 осквернителей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет во мне радости, ибо мы убиваем сотворённых Элуной, но распространение порчи надо остановить. Ты $Gсделал:сделала; благое дело, $C.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Справедливость восторжествовала?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фарадрелле в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (10754,'Вход в цитадель','Не может быть! Дай-ка мне поближе взглянуть на эту форму.','Тебе есть что мне показать, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вход в цитадель',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не может быть! Дай-ка мне поближе взглянуть на эту форму.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе есть что мне показать, $N?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (10755,'Вход в цитадель','Форма для отливки ключа? Может ли это быть тем, что даст нам доступ в Расколотые залы?','Тебе есть что мне показать, $N?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вход в цитадель',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Форма для отливки ключа? Может ли это быть тем, что даст нам доступ в Расколотые залы?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе есть что мне показать, $N?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (10756,'Великий мастер Рохок','Символ на рукояти этого ключа... Внутри формы его разглядеть трудно, но я узнаю его... Это знак клана Изувеченной Длани.$B$BЕсть шанс, что с его помощью ты сможешь проникнуть в Разрушенные залы.$B$BПоговори с Рохоком, это наш кузнец. Если кто-нибудь и сможет изготовить этот ключ, так это он.','Принесите форму для отливки ключа Рохоку в Траллмар, что на Полуострове Адского Пламени.','Назгрел хочет, чтобы я поработал над ключом? Он забыл, что мы на поле битвы? Есть лезвия и копья, которые нужно выковать!','Что это?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий мастер Рохок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Символ на рукояти этого ключа... Внутри формы его разглядеть трудно, но я узнаю его... Это знак клана Изувеченной Длани.$B$BЕсть шанс, что с его помощью ты сможешь проникнуть в Разрушенные залы.$B$BПоговори с Рохоком, это наш кузнец. Если кто-нибудь и сможет изготовить этот ключ, так это он.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите форму для отливки ключа Рохоку в Траллмар, что на Полуострове Адского Пламени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Назгрел хочет, чтобы я поработал над ключом? Он забыл, что мы на поле битвы? Есть лезвия и копья, которые нужно выковать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10757,'Просьба Рохока','Возможно, кузнецы орков Скверны не самые искусные в мире, но у них есть чему поучиться. Для этой формы подойдет только оскверненное железо, если мы хотим получить рабочий ключ. Все остальное его только испортит.$B$BПринеси мне несколько слитков оскверненного железа, немного чародейской пыли и частицу Огня. Я постараюсь сделать все, что смогу, но ничего не хочу обещать.','Превосходно. Давайте попробуем.','Ты $Gполучил:получила;, запрошенные мной материалы?','Вернитесь к Рохоку в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Рохока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, кузнецы орков Скверны не самые искусные в мире, но у них есть чему поучиться. Для этой формы подойдет только оскверненное железо, если мы хотим получить рабочий ключ. Все остальное его только испортит.$B$BПринеси мне несколько слитков оскверненного железа, немного чародейской пыли и частицу Огня. Я постараюсь сделать все, что смогу, но ничего не хочу обещать.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно. Давайте попробуем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gполучил:получила;, запрошенные мной материалы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рохоку в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10758,'Жарче, чем в пекле','Вот незадача, $n! Сколько бы я ни кидал в топку угля, жара все равно не хватает.$B$BЯ думаю, есть только одна сила, которая могла бы поддержать температуру, достаточную для выплавки этого ключа, и она находится в легионовских скверноботах.$B$BКогда-то я видел, как повергли одного сквернобота. Помню, он весь задымился, начал изрыгать пламя и окутался облаками пара. Возьми эту форму и сунь ее в нутро поверженного сквернобота. Я бы рекомендовал тебе позвать на помощь друзей, если надумаешь за ним отправиться.','Вы добились успеха! Вам остается только попробовать.','Ты $Gвыполнил:выполнила; задание, порученное мной, $N?','Вернитесь к Рохоку в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жарче, чем в пекле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот незадача, $n! Сколько бы я ни кидал в топку угля, жара все равно не хватает.$B$BЯ думаю, есть только одна сила, которая могла бы поддержать температуру, достаточную для выплавки этого ключа, и она находится в легионовских скверноботах.$B$BКогда-то я видел, как повергли одного сквернобота. Помню, он весь задымился, начал изрыгать пламя и окутался облаками пара. Возьми эту форму и сунь ее в нутро поверженного сквернобота. Я бы рекомендовал тебе позвать на помощь друзей, если надумаешь за ним отправиться.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы добились успеха! Вам остается только попробовать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвыполнил:выполнила; задание, порученное мной, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рохоку в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10759,'Найти дезертира','Я чувствую, что мы собрали все части головоломки, но порядок, в котором надо их сложить, чтобы получить хоть какой-то смысл, от меня ускользает.$B$BДумаю, нам стоит попытаться найти этого дезертира. Если он оставил своих товарищей, есть шанс убедить его помочь нам понять, что планирует темный конклав араккоа.$B$BНачни его поиски по дороге к Магмовым полям к северо-западу отсюда. Скорее всего, он попытается найти убежище именно там.','Найдите Паршаха в Магмовых полях и поговорите с ним.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти дезертира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я чувствую, что мы собрали все части головоломки, но порядок, в котором надо их сложить, чтобы получить хоть какой-то смысл, от меня ускользает.$B$BДумаю, нам стоит попытаться найти этого дезертира. Если он оставил своих товарищей, есть шанс убедить его помочь нам понять, что планирует темный конклав араккоа.$B$BНачни его поиски по дороге к Магмовым полям к северо-западу отсюда. Скорее всего, он попытается найти убежище именно там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Паршаха в Магмовых полях и поговорите с ним.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10760,'Развалины Скет\'лона','Добудьте у темного конклава араккоа и принесите сержанту Каргулу в Деревню Призрачной Луны первую, вторую и третью страницы дневника командира Скет\'лона.','<Сержант изучает страницы.>$B$BНе вижу здесь ничего такого уж полезного, однако есть пара записей, которые можно использовать. Тут написано, что до самой своей гибели араккоа готовились к какому-то сложному ритуалу, но больше про этот ритуал ничего не известно. И еще тут есть любопытная запись о каком-то дезертире...','Что тебе удалось узнать?','Вернитесь к сержанту Каргулу в Деревню Призрачной Луны, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Развалины Скет\'лона',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте у темного конклава араккоа и принесите сержанту Каргулу в Деревню Призрачной Луны первую, вторую и третью страницы дневника командира Скет\'лона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Сержант изучает страницы.>$B$BНе вижу здесь ничего такого уж полезного, однако есть пара записей, которые можно использовать. Тут написано, что до самой своей гибели араккоа готовились к какому-то сложному ритуалу, но больше про этот ритуал ничего не известно. И еще тут есть любопытная запись о каком-то дезертире...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось узнать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Каргулу в Деревню Призрачной Луны, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10761,'Найти дезертира','Вряд ли кто-нибудь нам тут объяснит, почему души этих араккоа задержались в нашем мире или зачем им нужна кровь орков.$B$BДумаю, нам стоит попытаться найти этого дезертира. Если он оставил своих товарищей, есть шанс убедить его помочь нам понять, что планирует темный конклав араккоа.$B$BНачни поиски его по дороге к Магмовым полям к юго-востоку отсюда. Скорее всего, он попытается найти убежище именно там.','Найдите Паршаха в Магмовых полях и поговорите с ним.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти дезертира',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вряд ли кто-нибудь нам тут объяснит, почему души этих араккоа задержались в нашем мире или зачем им нужна кровь орков.$B$BДумаю, нам стоит попытаться найти этого дезертира. Если он оставил своих товарищей, есть шанс убедить его помочь нам понять, что планирует темный конклав араккоа.$B$BНачни поиски его по дороге к Магмовым полям к юго-востоку отсюда. Скорее всего, он попытается найти убежище именно там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Паршаха в Магмовых полях и поговорите с ним.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (10762,'Великий Мастер Болтуй','Символ на рукояти этого ключа... Под плесенью трудно разглядеть, но я узнаю его... Это знак клана Изувеченной Длани.$B$BЕсть шанс, что с его помощью ты сможешь проникнуть в Разрушенные залы.$B$BПоговори с Болтуем. Он великий мастер своего дела. Если кто-нибудь и сможет отковать этот ключ, так это он.','Принести форму для отливки ключа Болтую в Оплот Чести.','Какой такой ключ? Данат что, забыл, – нам надо работать над осадными орудиями!','Что это?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великий Мастер Болтуй',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Символ на рукояти этого ключа... Под плесенью трудно разглядеть, но я узнаю его... Это знак клана Изувеченной Длани.$B$BЕсть шанс, что с его помощью ты сможешь проникнуть в Разрушенные залы.$B$BПоговори с Болтуем. Он великий мастер своего дела. Если кто-нибудь и сможет отковать этот ключ, так это он.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принести форму для отливки ключа Болтую в Оплот Чести.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой такой ключ? Данат что, забыл, – нам надо работать над осадными орудиями!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10763,'Просьба Болтуя','Орки Скверны – полные дикари, но их кузнечное искусство отнюдь не так примитивно, как можно подумать. Для этой формы подойдет только оскверненное железо, если мы хотим получить рабочий ключ. Все остальное только его испортит.$B$BПринеси мне несколько слитков оскверненного железа, немного чародейской пыли и частицу Огня. Я постараюсь сделать все, что смогу, но ничего не обещаю.','Ну, давай попробуем. Посмотрим, на что годится кузнечное дело орков Скверны.','Ты $Gдостал:достала;, запрошенные мной материалы?','Вернитесь к Болтую в Оплот Чести, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Болтуя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Орки Скверны – полные дикари, но их кузнечное искусство отнюдь не так примитивно, как можно подумать. Для этой формы подойдет только оскверненное железо, если мы хотим получить рабочий ключ. Все остальное только его испортит.$B$BПринеси мне несколько слитков оскверненного железа, немного чародейской пыли и частицу Огня. Я постараюсь сделать все, что смогу, но ничего не обещаю.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, давай попробуем. Посмотрим, на что годится кузнечное дело орков Скверны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдостал:достала;, запрошенные мной материалы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Болтую в Оплот Чести, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10765,'Война Миров','На южном конце Пути Завоевания, возле каравана, вставшего лагерем, мне удалось заметить великана и эльфийку крови в одеждах Советника, которые вроде бы организовали там встречу. Ты наверняка также $gзаметил:заметила; менее крупных гигантов на пути. Что-то в этом мире крупно не так, боец.$B$BЯ хочу, чтобы ты $gпроник:проникла; на такую встречу и $gиспортил:испортила; им праздник. Разузнай все, что можешь, а потом позови кого-нибудь из нас с помощью светового ружья.','Убейте канцлера Кровавую Листву и Корока Могучего и добудьте приказ Иллидана.','Так они собираются искать милости великанов? У меня есть план, как разрушить этот отвратительный союз.','Слушаю тебя, солдат.','Воспользуйтесь кор\'кронским сигнальным ружьем, чтобы подать сигнал всаднику на ветрокрыле.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у властителя Ор\'барокха в деревне Призрачной Луны, что в долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Война Миров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На южном конце Пути Завоевания, возле каравана, вставшего лагерем, мне удалось заметить великана и эльфийку крови в одеждах Советника, которые вроде бы организовали там встречу. Ты наверняка также $gзаметил:заметила; менее крупных гигантов на пути. Что-то в этом мире крупно не так, боец.$B$BЯ хочу, чтобы ты $gпроник:проникла; на такую встречу и $gиспортил:испортила; им праздник. Разузнай все, что можешь, а потом позови кого-нибудь из нас с помощью светового ружья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте канцлера Кровавую Листву и Корока Могучего и добудьте приказ Иллидана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так они собираются искать милости великанов? У меня есть план, как разрушить этот отвратительный союз.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Слушаю тебя, солдат.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь кор\'кронским сигнальным ружьем, чтобы подать сигнал всаднику на ветрокрыле.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у властителя Ор\'барокха в деревне Призрачной Луны, что в долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10766,'Точка вторжения: Катаклизм','Теперь, когда у нас есть доступ к базе Легиона в Точке вторжения: Катаклизм, нужно придумать способ положить конец их действиям. Цитадель Громового Молота не может спать спокойно, пока даже следы присутствия Легиона в этой местности не стерты с лица земли.$B$BЯ послал туда передовой отряд, чтобы помочь тебе уничтожить их припасы. Возвращайся в форт Легиона и воспользуйся телепортом, отмеченным зелеными кристаллами. Плекси встретит тебя на месте.','Доложитесь Плекси в Точке вторжения: Катаклизм.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Точка вторжения: Катаклизм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у нас есть доступ к базе Легиона в Точке вторжения: Катаклизм, нужно придумать способ положить конец их действиям. Цитадель Громового Молота не может спать спокойно, пока даже следы присутствия Легиона в этой местности не стерты с лица земли.$B$BЯ послал туда передовой отряд, чтобы помочь тебе уничтожить их припасы. Возвращайся в форт Легиона и воспользуйся телепортом, отмеченным зелеными кристаллами. Плекси встретит тебя на месте.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь Плекси в Точке вторжения: Катаклизм.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10767,'Точка вторжения: Катаклизм','Теперь, когда у нас есть доступ к базе Легиона в Точке вторжения: Катаклизм, нужно придумать способ положить конец их действиям. Деревня Призрачной Луны не может спать спокойно, пока даже следы присутствия Легиона в этой местности не стерты с лица земли.$B$BЯ послал туда передовой отряд, чтобы помочь тебе уничтожить их припасы. Возвращайся в форт Легиона и воспользуйся телепортом, отмеченным зелеными кристаллами. Наканси встретит тебя на месте.','Доложитесь Наканси в Точке вторжения: Катаклизм.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Точка вторжения: Катаклизм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у нас есть доступ к базе Легиона в Точке вторжения: Катаклизм, нужно придумать способ положить конец их действиям. Деревня Призрачной Луны не может спать спокойно, пока даже следы присутствия Легиона в этой местности не стерты с лица земли.$B$BЯ послал туда передовой отряд, чтобы помочь тебе уничтожить их припасы. Возвращайся в форт Легиона и воспользуйся телепортом, отмеченным зелеными кристаллами. Наканси встретит тебя на месте.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь Наканси в Точке вторжения: Катаклизм.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10768,'Гербовые накидки Иллидари','Всадники на ветрокрылах должны вернуться в Деревню Призрачной Луны, чтобы подготовиться к следующему этапу нашего штурма. Теперь мне от тебя нужны гербовые накидки эльфов крови.$B$BКогда ты соберешь достаточно гербовых накидок, подай сигнал всадникам на ветрокрылах, используя кор\'кронское сигнальное ружье. Пришло время попробовать себя в шпионаже, |3-6($r)!','Соберите 10 гербовых накидок Иллидари.','Агаа! Это – то, что надо!!!','Воспользуйтесь кор\'кронским сигнальным ружьем, чтобы подать сигнал всаднику на ветрокрыле.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у властителя Ор\'барокха в деревне Призрачной Луны, что в долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гербовые накидки Иллидари',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Всадники на ветрокрылах должны вернуться в Деревню Призрачной Луны, чтобы подготовиться к следующему этапу нашего штурма. Теперь мне от тебя нужны гербовые накидки эльфов крови.$B$BКогда ты соберешь достаточно гербовых накидок, подай сигнал всадникам на ветрокрылах, используя кор\'кронское сигнальное ружье. Пришло время попробовать себя в шпионаже, |3-6($r)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 гербовых накидок Иллидари.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Агаа! Это – то, что надо!!!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь кор\'кронским сигнальным ружьем, чтобы подать сигнал всаднику на ветрокрыле.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у властителя Ор\'барокха в деревне Призрачной Луны, что в долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10769,'Удар исподтишка','Ученый Тиорус был так добр, подготовить эту смесь для последней стычки. Я просто вылью ее на эту гербовую накидку, которую тебе удалось раздобыть и на ней возникнет образ негодяев Иллидари.$B$BВозьми эту зачарованную гербовую накидку и отправляйся в Поля Затмения, к юго-западу от Лагеря Затмения. Там используй гербовую накидку, чтобы превратиться в агента Иллидана. Пользуясь личиной, убей безумных колоссов, бродящих по полю. Они сочтут это нападением лагеря Затмения, и союз будет разорван.','Убейте 5 безумных колоссов в личине эльфа крови Иллидари и потом вернитесь к Властителю Ор\'барокху в Деревню Призрачной Луны в одноименной долине. Верните ему кор\'кронское сигнальное ружье.','Вернитесь к властителю Ор\'барокху в Деревню Призрачной Луны, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар исподтишка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ученый Тиорус был так добр, подготовить эту смесь для последней стычки. Я просто вылью ее на эту гербовую накидку, которую тебе удалось раздобыть и на ней возникнет образ негодяев Иллидари.$B$BВозьми эту зачарованную гербовую накидку и отправляйся в Поля Затмения, к юго-западу от Лагеря Затмения. Там используй гербовую накидку, чтобы превратиться в агента Иллидана. Пользуясь личиной, убей безумных колоссов, бродящих по полю. Они сочтут это нападением лагеря Затмения, и союз будет разорван.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 безумных колоссов в личине эльфа крови Иллидари и потом вернитесь к Властителю Ор\'барокху в Деревню Призрачной Луны в одноименной долине. Верните ему кор\'кронское сигнальное ружье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Ор\'барокху в Деревню Призрачной Луны, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10770,'Угольки','Скоро я усну глубоким сном леса. Прежде чем я закопаю свои корни глубоко и навсегда закрою эти старые глаза, я надеюсь узнать, что эти несчастные бесы страдали и погибли.','Вернитесь к Замшельнику Древнему в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Угольки',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Скоро я усну глубоким сном леса. Прежде чем я закопаю свои корни глубоко и навсегда закрою эти старые глаза, я надеюсь узнать, что эти несчастные бесы страдали и погибли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Замшельнику Древнему в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10771,'Восстать из пепла','Если ты пойдешь отсюда по дороге, что идет на восток, а потом поднимается по склону горы, а затем свернешь на север, ты найдешь мой старый утраченный дом.$b$bНекода там рос лес. Название его уже забыто. Давным-давно Пылающий Легион призвал туда огненных бесов и прочих огненных тварей. Мой дом был разрушен, и мой народ бежал. Остался я один. $B$BЯ сумел спасти немного семян железнокорня, который можно посадить в плодородную вулканическую почву. Их магия сильна. Сделай это для меня, и я поделюсь с тобой сокровищами забытых веков.','Дело сделано? Тебе удалось возродить хоть какую-то жизнь на моей древней родине?','Вернитесь к Замшельнику Древнему в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстать из пепла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты пойдешь отсюда по дороге, что идет на восток, а потом поднимается по склону горы, а затем свернешь на север, ты найдешь мой старый утраченный дом.$b$bНекода там рос лес. Название его уже забыто. Давным-давно Пылающий Легион призвал туда огненных бесов и прочих огненных тварей. Мой дом был разрушен, и мой народ бежал. Остался я один. $B$BЯ сумел спасти немного семян железнокорня, который можно посадить в плодородную вулканическую почву. Их магия сильна. Сделай это для меня, и я поделюсь с тобой сокровищами забытых веков.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дело сделано? Тебе удалось возродить хоть какую-то жизнь на моей древней родине?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Замшельнику Древнему в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10772,'Путь Завоевания','Отправляйтесь по Пути Завоевания в Долине Призрачной Луны.','Путь Завоевания обнаружен','Воспользуйтесь сигнальным ружьем Громового Молота, чтобы подать сигнал всаднику на грифоне.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у тана Йорегара в цитадели Громового Молота, что в долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь Завоевания',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь по Пути Завоевания в Долине Призрачной Луны.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Путь Завоевания обнаружен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь сигнальным ружьем Громового Молота, чтобы подать сигнал всаднику на грифоне.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у тана Йорегара в цитадели Громового Молота, что в долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10773,'Перерезанный путь','Убейте 20 солдат, 10 кавалеристов лагеря Затмения и 5 сынов Корока.','Ты не поверишь, солдат!','Воспользуйтесь сигнальным ружьем Громового Молота, чтобы подать сигнал всаднику на грифоне.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у тана Йорегара в цитадели Громового Молота, что в долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перерезанный путь',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 солдат, 10 кавалеристов лагеря Затмения и 5 сынов Корока.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты не поверишь, солдат!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь сигнальным ружьем Громового Молота, чтобы подать сигнал всаднику на грифоне.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у тана Йорегара в цитадели Громового Молота, что в долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10774,'Великан плюс эльфийка равно...','На южном конце Пути Завоевания, возле каравана, вставшего лагерем, мне пришлось наблюдать вроде как встречу великана и эльфийки крови в одеждах Советника. Что гиганты вообще здесь делают? Что-то здесь явно не так, солдат$B$BТебе придется пробиться к месту встречи и сорвать ее. Все, что ты сумеешь принести с места встречи, может нам поспособствовать. Как будешь $gготов:готова;, вызови одного из нас с помощью сигнального ружья.','Убейте канцлера Кровавую Листву и Корока Могучего и верните приказ Иллидана.','Так они собираются искать милости великанов? У меня есть план, как разрушить этот пугающий союз.','Воспользуйтесь сигнальным ружьем Громового Молота, чтобы подать сигнал всаднику на грифоне.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у тана Йорегара в цитадели Громового Молота, что в долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великан плюс эльфийка равно...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На южном конце Пути Завоевания, возле каравана, вставшего лагерем, мне пришлось наблюдать вроде как встречу великана и эльфийки крови в одеждах Советника. Что гиганты вообще здесь делают? Что-то здесь явно не так, солдат$B$BТебе придется пробиться к месту встречи и сорвать ее. Все, что ты сумеешь принести с места встречи, может нам поспособствовать. Как будешь $gготов:готова;, вызови одного из нас с помощью сигнального ружья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте канцлера Кровавую Листву и Корока Могучего и верните приказ Иллидана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так они собираются искать милости великанов? У меня есть план, как разрушить этот пугающий союз.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь сигнальным ружьем Громового Молота, чтобы подать сигнал всаднику на грифоне.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у тана Йорегара в цитадели Громового Молота, что в долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10775,'Гербовые накидки Иллидари','Соберите 10 гербовых накидок Иллидари.','Воспользуйтесь сигнальным ружьем Громового Молота, чтобы подать сигнал всаднику на грифоне.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у тана Йорегара в цитадели Громового Молота, что в долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гербовые накидки Иллидари',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 гербовых накидок Иллидари.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь сигнальным ружьем Громового Молота, чтобы подать сигнал всаднику на грифоне.$B$BЕсли вы потеряете сигнальное ружье, возьмите новое у тана Йорегара в цитадели Громового Молота, что в долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10776,'Удар исподтишка','Гномус был так добр подготовить эту смесь для последней стычки. Я просто вылью ее на эту гербовую накидку, которую тебе удалось раздобыть и на ней возникнет образ негодяев Иллидари.$B$BВозьми эту зачарованную гербовую накидку и отправляйся на Поля Затмения, к юго-западу от Лагеря Затмения. Там используй гербовую накидку, чтобы превратиться в агента Иллидана. Пользуясь личиной, убей безумных колоссов, бродящих по полю. Они сочтут это нападением лагеря Затмения, и союз будет разорван.','Убейте 5 безумных колоссов, находясь в облике посланника Иллидана, потом вернитесь к тану Йорегару в цитадель Громового Молота в Долине Призрачной Луны. Верните ему сигнальное ружье Громового Молота.','Вернитесь к Тану Йорегару в Цитадель Громового Молота, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удар исподтишка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гномус был так добр подготовить эту смесь для последней стычки. Я просто вылью ее на эту гербовую накидку, которую тебе удалось раздобыть и на ней возникнет образ негодяев Иллидари.$B$BВозьми эту зачарованную гербовую накидку и отправляйся на Поля Затмения, к юго-западу от Лагеря Затмения. Там используй гербовую накидку, чтобы превратиться в агента Иллидана. Пользуясь личиной, убей безумных колоссов, бродящих по полю. Они сочтут это нападением лагеря Затмения, и союз будет разорван.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 безумных колоссов, находясь в облике посланника Иллидана, потом вернитесь к тану Йорегару в цитадель Громового Молота в Долине Призрачной Луны. Верните ему сигнальное ружье Громового Молота.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тану Йорегару в Цитадель Громового Молота, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10777,'Тотем Азгара','То, о чем ты $Gпрочитал:прочитала; в дневнике командира – истинная правда. Пока Орда множилась под рукой Гул\'дана, мои соплеменники пытались отвести опасность, нападая на орков. Гул\'дан узнал об этом и уничтожил наши поселения, пленив души моих собратьев.$B$BИх необходимо остановить, пока они не натворили еще больше бед. На Развалинах Скет\'лона к северу отсюда найди Азгара и принеси хранящийся у него тотем. Он поможет нам спутать карты темному конклаву.','Принесите Паршаху в Магмовые поля военный тотем Скет\'лона.','Вернитесь к Паршаху на Магмовые поля, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тотем Азгара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','То, о чем ты $Gпрочитал:прочитала; в дневнике командира – истинная правда. Пока Орда множилась под рукой Гул\'дана, мои соплеменники пытались отвести опасность, нападая на орков. Гул\'дан узнал об этом и уничтожил наши поселения, пленив души моих собратьев.$B$BИх необходимо остановить, пока они не натворили еще больше бед. На Развалинах Скет\'лона к северу отсюда найди Азгара и принеси хранящийся у него тотем. Он поможет нам спутать карты темному конклаву.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Паршаху в Магмовые поля военный тотем Скет\'лона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Паршаху на Магмовые поля, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10778,'Жезл Лиантэ','Силы одного тотема не хватит, чтобы одолеть магию темного конклава.$B$BМы можем скомбинировать его силу с другими артефактами и создать посох, фокусирующий их энергию. И если мы не можем отвратить моих соплеменников от овладевшей ими порочности, то мы хотя бы можем остановить их.$B$BОдин из элементов, необходимых для посоха – жезл Лиантэ, который хранится у эльфов крови в Лагере Затмения к юго-востоку отсюда. Ты найдешь этот артефакт в павильоне на верхнем ярусе руин. Будь осторожнее, $n, его хорошо охраняют.','Заберите ключ Лиантэ у любого из эльфов крови в Лагере Затмения, откройте сейф и заберите жезл Лиантэ. Вернитесь с ветвью к Паршаху в Магмовые поля.','Отлично! Такая вещь заслуживает лучшей участи, чем пылиться в темном сундуке. Уж мы то пристроим ее к делу.','Тебе удалось раздобыть Ветвь?','Вернитесь к Паршаху на Магмовые поля, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жезл Лиантэ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Силы одного тотема не хватит, чтобы одолеть магию темного конклава.$B$BМы можем скомбинировать его силу с другими артефактами и создать посох, фокусирующий их энергию. И если мы не можем отвратить моих соплеменников от овладевшей ими порочности, то мы хотя бы можем остановить их.$B$BОдин из элементов, необходимых для посоха – жезл Лиантэ, который хранится у эльфов крови в Лагере Затмения к юго-востоку отсюда. Ты найдешь этот артефакт в павильоне на верхнем ярусе руин. Будь осторожнее, $n, его хорошо охраняют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите ключ Лиантэ у любого из эльфов крови в Лагере Затмения, откройте сейф и заберите жезл Лиантэ. Вернитесь с ветвью к Паршаху в Магмовые поля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Такая вещь заслуживает лучшей участи, чем пылиться в темном сундуке. Уж мы то пристроим ее к делу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось раздобыть Ветвь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Паршаху на Магмовые поля, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10779,'Путь охотника','Приветствую, $gюный охотник:юная охотница;. Мне кажется, ты уже $gспособен:способна; справиться со зверем и сделать его своим спутником.$B$BПоговори с охотницей Келлой Тетивой Ночи. Она расскажет тебе, как завести питомца.','Поговорите с охотницей Келлой Тетивой Ночи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь охотника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую, $gюный охотник:юная охотница;. Мне кажется, ты уже $gспособен:способна; справиться со зверем и сделать его своим спутником.$B$BПоговори с охотницей Келлой Тетивой Ночи. Она расскажет тебе, как завести питомца.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с охотницей Келлой Тетивой Ночи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10780,'Перья Скет\'лона','В посохе не хватает всего одной детали. Мы должны направить силу посоха против духов Темного Конклава.$B$BСделать это мы можем, собрав перья, разбросанные на земле в Лагере Скет\'лона и использовав их при изготовлении посоха. Лагерь находится на юге отсюда, восточнее цитадели Громового Молота.$B$BЧары Гул\'дана уничтожили моих собратьев, оставив их души скитаться, однако на этом все не кончилось, – ведь чары питались тем заклинанием, которое араккоа готовили для подчинения духов.','Соберите 8 перьев Скет\'лона и принесите их Паршаху в Магмовые поля.','<Паршах принимает пепельные перья, качая головой.>$B$BБыло бы лучше, если бы они умерли в тот день, но это было бы слишком просто. То, что чары Гул\'дана превратили их в угрозу, против которой они пытались бороться, это очень жестокая шутка...','Удалось ли тебе собрать перья для посоха?','Вернитесь к Паршаху на Магмовые поля, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перья Скет\'лона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В посохе не хватает всего одной детали. Мы должны направить силу посоха против духов Темного Конклава.$B$BСделать это мы можем, собрав перья, разбросанные на земле в Лагере Скет\'лона и использовав их при изготовлении посоха. Лагерь находится на юге отсюда, восточнее цитадели Громового Молота.$B$BЧары Гул\'дана уничтожили моих собратьев, оставив их души скитаться, однако на этом все не кончилось, – ведь чары питались тем заклинанием, которое араккоа готовили для подчинения духов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 перьев Скет\'лона и принесите их Паршаху в Магмовые поля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Паршах принимает пепельные перья, качая головой.>$B$BБыло бы лучше, если бы они умерли в тот день, но это было бы слишком просто. То, что чары Гул\'дана превратили их в угрозу, против которой они пытались бороться, это очень жестокая шутка...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе собрать перья для посоха?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Паршаху на Магмовые поля, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10781,'Битва у Кровавого Дозора','Как мы и подозревали, тебя уже ищут на Пути Завоевания. Пора уносить ноги, |3-6($r)!$B$BОставь меня... Со мной все кончено. Они.. Я слышу их шаги, они уже близко. Сейчас или никогда... Убирайся! Если ты останешься, тебе придется сражаться.$B$BЕсли ты решил принять бой, и тебе каким-то чудом удастся уцелеть, передай те сведения, которые мы раздобыли А\'далу в Шаттрат.','Сразитесь с войском Иллидари возле Кровавого Дозора и останьтесь в живых!$B$BВернитесь к А\'далу в Шаттрат, если сумеете победить.','<А\'дал приветствует вас.>','Силы Кровавой Печати уничтожены.','Вернитесь к А\'далу в Шаттрат, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва у Кровавого Дозора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как мы и подозревали, тебя уже ищут на Пути Завоевания. Пора уносить ноги, |3-6($r)!$B$BОставь меня... Со мной все кончено. Они.. Я слышу их шаги, они уже близко. Сейчас или никогда... Убирайся! Если ты останешься, тебе придется сражаться.$B$BЕсли ты решил принять бой, и тебе каким-то чудом удастся уцелеть, передай те сведения, которые мы раздобыли А\'далу в Шаттрат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сразитесь с войском Иллидари возле Кровавого Дозора и останьтесь в живых!$B$BВернитесь к А\'далу в Шаттрат, если сумеете победить.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<А\'дал приветствует вас.>',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Силы Кровавой Печати уничтожены.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к А\'далу в Шаттрат, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10782,'Зарядка набалдашника','Посох почти закончен! $B$BОсталось только наполнить набалдашник силами, оставшимися в этих местах от Гул\'дана. На восток, около Дьявольских Копей, к югу от Дьявольской Кузницы, находится Алтарь Проклятия.$B$BТам заключены воспоминания о жизни Гул\'дана. Когда ты принесешь незавершенный набалдашник к алтарю, не удивляйся, если некоторые из объектов отреагируют на него: у тебя в руках будет опасный артефакт, связанный с катаклизмом.','Отправляйтесь к Алтарю Проклятия и воспользуйтесь незавершенным набалдашником возле Гул\'дана. Когда набалдашник зарядится, возвращайтесь к Паршаху в Магмовые Поля.','Набалдашник заряжен?','Вернитесь к Паршаху на Магмовые поля, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зарядка набалдашника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посох почти закончен! $B$BОсталось только наполнить набалдашник силами, оставшимися в этих местах от Гул\'дана. На восток, около Дьявольских Копей, к югу от Дьявольской Кузницы, находится Алтарь Проклятия.$B$BТам заключены воспоминания о жизни Гул\'дана. Когда ты принесешь незавершенный набалдашник к алтарю, не удивляйся, если некоторые из объектов отреагируют на него: у тебя в руках будет опасный артефакт, связанный с катаклизмом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к Алтарю Проклятия и воспользуйтесь незавершенным набалдашником возле Гул\'дана. Когда набалдашник зарядится, возвращайтесь к Паршаху в Магмовые Поля.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Набалдашник заряжен?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Паршаху на Магмовые поля, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10783,'Барон Черногрив','Вот мой план. Мы отравим огров и уничтожим их хозяина-гронна. $b$bВо время странствий в этих горах я повстречал одного человека по имени барон Черногрив. Он виртуоз алхимии, и мы можем попробовать уговорить его помочь нам.$b$bИщи его в Круге Крови дальше по каньону к северу отсюда. Какую бы цену он ни запросил, соглашайся.','Поговорите с бароном Черногривом в Круге Крови в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Барон Черногрив',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот мой план. Мы отравим огров и уничтожим их хозяина-гронна. $b$bВо время странствий в этих горах я повстречал одного человека по имени барон Черногрив. Он виртуоз алхимии, и мы можем попробовать уговорить его помочь нам.$b$bИщи его в Круге Крови дальше по каньону к северу отсюда. Какую бы цену он ни запросил, соглашайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с бароном Черногривом в Круге Крови в Острогорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10784,'Уничтожить лагерь Кровавого Молота!','Убейте 10 извергов и 5 чернокнижников клана Кровавого Молота.','Ты уже $Gуничтожил:уничтожила; лагерь Кровавого Молота?','Вернитесь к Тор\'чанку Двукогтю в Оплот Громоборцев, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить лагерь Кровавого Молота!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 извергов и 5 чернокнижников клана Кровавого Молота.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже $Gуничтожил:уничтожила; лагерь Кровавого Молота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тор\'чанку Двукогтю в Оплот Громоборцев, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10785,'Ловушка!','Ничто в этом мире не может вызвать у меня такого гнева, как этот Груул и его сыны! Они истребили мой народ – моих детей – но теперь я отомщу.$B$BЯ создал ловушку из драконьего огня, и если тебе хватит сообразительности, то с ее помощью ты сможешь прикончить даже гронна.$B$BТоропись, отнеси эту ловушку Рексару. Я хочу утолить жажду мести!','Отнесите ловушку пламени дракона Рексару в Оплот Громоборцев в Острогорье.','Хмм, ловушка из субстанции драконьего огня? Интересно, откуда Черногрив берет такие редкие субстанции?$B$BДа ладно. Важно, что мы с помощью этой штуковины прикончим сына Груула.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловушка!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ничто в этом мире не может вызвать у меня такого гнева, как этот Груул и его сыны! Они истребили мой народ – моих детей – но теперь я отомщу.$B$BЯ создал ловушку из драконьего огня, и если тебе хватит сообразительности, то с ее помощью ты сможешь прикончить даже гронна.$B$BТоропись, отнеси эту ловушку Рексару. Я хочу утолить жажду мести!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ловушку пламени дракона Рексару в Оплот Громоборцев в Острогорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хмм, ловушка из субстанции драконьего огня? Интересно, откуда Черногрив берет такие редкие субстанции?$B$BДа ладно. Важно, что мы с помощью этой штуковины прикончим сына Груула.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10786,'Резня в Камен\'моке','Убейте 5 громил и 3 шаманов Камен\'мока, затем вернитесь к Тор\'чанку Двукогтю в Оплот Громоборцев в Острогорье.','Вернитесь к Тор\'чанку Двукогтю в Оплот Громоборцев, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Резня в Камен\'моке',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 громил и 3 шаманов Камен\'мока, затем вернитесь к Тор\'чанку Двукогтю в Оплот Громоборцев в Острогорье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тор\'чанку Двукогтю в Оплот Громоборцев, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10787,'[DEPRECATED]<txt><nyi>Драконы Драконьей Пагубы','Мы должны чем-то разозлить Гока, если хотим с ним сразиться.$B$BТеперь, когда ты $Gосвободил:освободила; &&&, думаю, я знаю, что делать!$B$BКогда соберешься, дай мне знать, и я попрошу &&& отвезти тебя к одной из драконьих туш, пригвожденных к скалам Драконьей Пагубы. $B$BЗабери тушу и принеси ее мне, чтобы мы смогли сделать что-нибудь такое, что непременно выманит Гока из его убежища!','Рексар просит вас поговорить с ним насчет полета на &&& к Драконьей Пагубе, чтобы добыть тело черного дракона. Вернитесь к нему в Оплот Громоборцев в Острогорье, когда добудете тело дракона.','Вернитесь к Рексару в земли Камнерогов, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]<txt><nyi>Драконы Драконьей Пагубы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны чем-то разозлить Гока, если хотим с ним сразиться.$B$BТеперь, когда ты $Gосвободил:освободила; &&&, думаю, я знаю, что делать!$B$BКогда соберешься, дай мне знать, и я попрошу &&& отвезти тебя к одной из драконьих туш, пригвожденных к скалам Драконьей Пагубы. $B$BЗабери тушу и принеси ее мне, чтобы мы смогли сделать что-нибудь такое, что непременно выманит Гока из его убежища!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Рексар просит вас поговорить с ним насчет полета на &&& к Драконьей Пагубе, чтобы добыть тело черного дракона. Вернитесь к нему в Оплот Громоборцев в Острогорье, когда добудете тело дракона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рексару в земли Камнерогов, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10788,'Возвращение к Талионии','Талиония из Луносвета призывает тебя к себе, $n. Наверное, тебе пришло время научиться вызывать и контролировать более могущественного демона. Отправляйся к ней – чем быстрее, тем лучше. Насколько я понимаю, Талионию можно найти в Святилище, маленьком и уютном логове зла в Закоулке Душегубов.','Поговорите с Талионией в Луносвете.','Итак, $Gпутешественник:путешественница; возвращается...$B$BЯ надеюсь, что мой сарказм очевиден, $N, потому что вы доставили мне, большие неудобства, заставив прислать повестку. Считайте, что вы - всего лишь волосы стража скверны после его выгорания, хотя у них нет волос.$B$Bобратите внимание, это не урок, которому вас будут учить дважды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Талионии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Талиония из Луносвета призывает тебя к себе, $n. Наверное, тебе пришло время научиться вызывать и контролировать более могущественного демона. Отправляйся к ней – чем быстрее, тем лучше. Насколько я понимаю, Талионию можно найти в Святилище, маленьком и уютном логове зла в Закоулке Душегубов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Талионией в Луносвете.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, $Gпутешественник:путешественница; возвращается...$B$BЯ надеюсь, что мой сарказм очевиден, $N, потому что вы доставили мне, большие неудобства, заставив прислать повестку. Считайте, что вы - всего лишь волосы стража скверны после его выгорания, хотя у них нет волос.$B$Bобратите внимание, это не урок, которому вас будут учить дважды.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10789,'Возвращение к Карендину Халгару','А, ты здесь, $n!$b$bКарендин Халгар велит тебе явиться к нему в Квартал Магов в Подгороде. Терпеливостью он не отличается, так что я бы на твоем месте не медлил.','Поговорите с Карендином Халгаром в Подгороде.','Да, я вижу это в твоих глазах. Тебе не терпится узнать больше.$B$BОчень хорошо, это тот самый урок, который нам обоим понравится.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Карендину Халгару',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, ты здесь, $n!$b$bКарендин Халгар велит тебе явиться к нему в Квартал Магов в Подгороде. Терпеливостью он не отличается, так что я бы на твоем месте не медлил.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Карендином Халгаром в Подгороде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, я вижу это в твоих глазах. Тебе не терпится узнать больше.$B$BОчень хорошо, это тот самый урок, который нам обоим понравится.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10790,'Возвращение к Ган\'рулу Кровавому Глазу','Далеко же ты от дома, |3-6($r). Быть может, пришло время вернуться к твоему учителю, Ган\'рулу Кровавому Глазу? О нем слышали все наши собратья по ремеслу, даже в этих краях.$B$BГан\'рул живет в Расселине Теней в Оргриммаре.','Найдите Ган\'рула Кровавого Глаза в Оргриммаре и поговорите с ним.','Ты жаждешь запретных знаний, да? Я могу их тебе предложить...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Ган\'рулу Кровавому Глазу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Далеко же ты от дома, |3-6($r). Быть может, пришло время вернуться к твоему учителю, Ган\'рулу Кровавому Глазу? О нем слышали все наши собратья по ремеслу, даже в этих краях.$B$BГан\'рул живет в Расселине Теней в Оргриммаре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Ган\'рула Кровавого Глаза в Оргриммаре и поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты жаждешь запретных знаний, да? Я могу их тебе предложить...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10791,'Приветствие духа Волка','Зажгите обрядовые благовония около свечей в хижине Малуказа и наблюдайте за церемонией. По завершении церемонии поговорите с Малуказом еще раз.','Восстановление связи с духом волка – это лишь начало моего пути, а никак не конец.','Вернитесь к Малуказу в Форт Камнеломов, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приветствие духа Волка',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зажгите обрядовые благовония около свечей в хижине Малуказа и наблюдайте за церемонией. По завершении церемонии поговорите с Малуказом еще раз.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Восстановление связи с духом волка – это лишь начало моего пути, а никак не конец.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Малуказу в Форт Камнеломов, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10792,'Сжечь Зет\'Гор!','Клан Кровавой Глазницы отрекся от своего гордого рода! Мы, орки, которые сражались и умирали, только бы не запятнать себя скверной Маннорота, видим в наших подлых сородичах лишь слабость и невежество... И поэтому они должны быть уничтожены!$B$BСтупай в Зет\'Гор, их оплот на востоке, и сожги его дотла. Убей батраков, забери у них факелы, зажги их в кузне и подожги все склады, стойла и казармы. Пусть все сгорит в огне! Уничтожь их и возвращайся ко мне.$B$BВо имя Орды!','Убейте батраков из клана Кровавой Глазницы, заберите у них факелы, зажгите факелы в кузне Зет\'Гора и забросьте горящие факелы в строения Зет\'Гора.','Вернитесь к капитану Мрачному Вою на Заставу Хребтолома, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сжечь Зет\'Гор!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Кровавой Глазницы отрекся от своего гордого рода! Мы, орки, которые сражались и умирали, только бы не запятнать себя скверной Маннорота, видим в наших подлых сородичах лишь слабость и невежество... И поэтому они должны быть уничтожены!$B$BСтупай в Зет\'Гор, их оплот на востоке, и сожги его дотла. Убей батраков, забери у них факелы, зажги их в кузне и подожги все склады, стойла и казармы. Пусть все сгорит в огне! Уничтожь их и возвращайся ко мне.$B$BВо имя Орды!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте батраков из клана Кровавой Глазницы, заберите у них факелы, зажгите факелы в кузне Зет\'Гора и забросьте горящие факелы в строения Зет\'Гора.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Мрачному Вою на Заставу Хребтолома, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (10793,'Записи Вал\'зарека: Предвестье Войны','В этом журнале описаны недавние действия армии Иллидана. Так же в нем объясняется, почему Вал\'зарек так демонстративно использовал Путь Завоевания. Ему был поручен захват верховного генерала Ша\'тар.$B$BЭтот генерал находился в пункте известном как Кровавый Дозор, расположенном в южном конце Пути Завоевания. Таинственная группа, называющая себя Кровавая Печать обвиняется в его похищении. Если ты решишь, разузнать больше об этом деле, захвати с собой подмогу.','Найдите Марка Аврелиона, верховного генерала Ша\'тар в Кровавом Дозоре.$B$BИщите его в кристаллической тюрьме.','<Генерал Аврелион появляется в глубине кристалла.>$B$BСлушай... А ты что тут делаешь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Записи Вал\'зарека: Предвестье Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом журнале описаны недавние действия армии Иллидана. Так же в нем объясняется, почему Вал\'зарек так демонстративно использовал Путь Завоевания. Ему был поручен захват верховного генерала Ша\'тар.$B$BЭтот генерал находился в пункте известном как Кровавый Дозор, расположенном в южном конце Пути Завоевания. Таинственная группа, называющая себя Кровавая Печать обвиняется в его похищении. Если ты решишь, разузнать больше об этом деле, захвати с собой подмогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Марка Аврелиона, верховного генерала Ша\'тар в Кровавом Дозоре.$B$BИщите его в кристаллической тюрьме.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Генерал Аврелион появляется в глубине кристалла.>$B$BСлушай... А ты что тут делаешь?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10794,'Разбойники Изувеченной Длани','Знаешь, $n, нам открыты далеко не все тайны мира. К примеру, искусством приготовления смертельных ядов мы так и не овладели. А вот орки из клана Изувеченной Длани постигли вершины этого мастерства. Отправляйся в Оргриммар и постарайся завоевать их доверие.$b$bСначала пройди в Подгород через портал в Луносвете, затем выйди за пределы города и следуй к ближайшей башне. Там ты сможешь сесть на дирижабль гоблинов и долететь до Оргриммара. Затем найди Шентула в Расселине Теней.','Поговорите с Шентулом в Оргриммаре.','Итак, вы хотите работать на Изувеченную Длань? Кажется, каждый день у нас появляется кто-то новый.$B$BСлушайте внимательно и я объясню, что вам нужно делать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разбойники Изувеченной Длани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, $n, нам открыты далеко не все тайны мира. К примеру, искусством приготовления смертельных ядов мы так и не овладели. А вот орки из клана Изувеченной Длани постигли вершины этого мастерства. Отправляйся в Оргриммар и постарайся завоевать их доверие.$b$bСначала пройди в Подгород через портал в Луносвете, затем выйди за пределы города и следуй к ближайшей башне. Там ты сможешь сесть на дирижабль гоблинов и долететь до Оргриммара. Затем найди Шентула в Расселине Теней.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Шентулом в Оргриммаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, вы хотите работать на Изувеченную Длань? Кажется, каждый день у нас появляется кто-то новый.$B$BСлушайте внимательно и я объясню, что вам нужно делать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10795,'Встреча с Доргоком','Убейте Доргока в лагере Кровавого Молота.','Раз Доргок убит, огры Кровавого Молота остались без руководства и будут в панике, пока у них не появится новый предводитель.$B$BСпасибо тебе, $C, теперь мы легче вздохнем.','Я не могу выразить достаточно чётко, насколько важно убить Доргока как можно быстрее.','Вернитесь к командиру Гефусу Камнестену в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с Доргоком',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Доргока в лагере Кровавого Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Раз Доргок убит, огры Кровавого Молота остались без руководства и будут в панике, пока у них не появится новый предводитель.$B$BСпасибо тебе, $C, теперь мы легче вздохнем.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не могу выразить достаточно чётко, насколько важно убить Доргока как можно быстрее.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Гефусу Камнестену в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10796,'Уничтожить лагерь Кровавого Молота!','Убейте 10 извергов и 5 чернокнижников клана Кровавого Молота.','<Лейтенант кивает, откровенно довольная вашими убойными способностями.>$B$BВы поражаете меня, $N. Похоже, вы не зря заслужили свою репутацию.$B$BС каждым убитым огром мы приближаемся к нашей цели – избавлению от опасности, ибо мы хотим жить в мире.','Вы уже разрушили лагерь Кровавого Молота?','Вернитесь к лейтенанту Файрвезер в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожить лагерь Кровавого Молота!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 извергов и 5 чернокнижников клана Кровавого Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Лейтенант кивает, откровенно довольная вашими убойными способностями.>$B$BВы поражаете меня, $N. Похоже, вы не зря заслужили свою репутацию.$B$BС каждым убитым огром мы приближаемся к нашей цели – избавлению от опасности, ибо мы хотим жить в мире.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы уже разрушили лагерь Кровавого Молота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Файрвезер в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (10797,'Благоволение гронна','Отнесите благоволение Горгрома командиру Гефусу Камнестену в Вечную рощу в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Благоволение гронна',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите благоволение Горгрома командиру Гефусу Камнестену в Вечную рощу в Острогорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (10798,'Визит к барону','Дурные вести. Горгром Драконоед стоит за недавней вылазкой Кровавых Молотов Сильванаара!$B$BКак ему удается манипулировать ими, причем не только натравливая на них Камнерогов – я не знаю. Но если мы хотим разделаться с гронном, нам понадобится помощь.$B$BЯ знаю одного человека, который владеет необычной магией. Барон Черногрив зовут его. Ты найдешь его в Круге Крови, если пойдешь вниз по юго-западному склону, а затем на юго-запад по каньону.$B$BПопроси его сделать для нас ловушку на гронна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Визит к барону',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дурные вести. Горгром Драконоед стоит за недавней вылазкой Кровавых Молотов Сильванаара!$B$BКак ему удается манипулировать ими, причем не только натравливая на них Камнерогов – я не знаю. Но если мы хотим разделаться с гронном, нам понадобится помощь.$B$BЯ знаю одного человека, который владеет необычной магией. Барон Черногрив зовут его. Ты найдешь его в Круге Крови, если пойдешь вниз по юго-западному склону, а затем на юго-запад по каньону.$B$BПопроси его сделать для нас ловушку на гронна.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10799,'Прогулка в Беспокойную лощину','Ладно, я сделаю эту ловушку, но сначала я кое-что потребую от тебя.$B$BИ уж так получилось, что это некая вещь, которой владеет живущий по соседству гронн, но пока тебе еще рано биться с ним.$B$BПотому мы с тобой сделаем сонный порошочек из яда живущих тут землероев.$B$BТы найдешь их в Беспокойной лощине на юго-западе. Принеси мне их железы, да побыстрее!','Соберите 7 ядовитых желез землероев.','Очень хорошо. Простая, прямо-таки тупая задача решена. Теперь давай мне железы, и я займусь самым трудным делом.','Вернитесь к барону Черногриву в Круг Крови, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прогулка в Беспокойную лощину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, я сделаю эту ловушку, но сначала я кое-что потребую от тебя.$B$BИ уж так получилось, что это некая вещь, которой владеет живущий по соседству гронн, но пока тебе еще рано биться с ним.$B$BПотому мы с тобой сделаем сонный порошочек из яда живущих тут землероев.$B$BТы найдешь их в Беспокойной лощине на юго-западе. Принеси мне их железы, да побыстрее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 ядовитых желез землероев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Простая, прямо-таки тупая задача решена. Теперь давай мне железы, и я займусь самым трудным делом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Черногриву в Круг Крови, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10800,'Спи спокойно, гронн','Я снова превзошел самого себя! Я сделал сонный порошок. Бери его и используй против Груллока, того самого гронна, который стережет ту вещь, что мне нужна.$B$BГруллок засел в Окаянной лощине, что в восточном конце Драконьей Пагубы по ту сторону Круга Крови.$B$BБудь я на твоем месте, я не стал бы тянуть, как только стянул бы его мешок. Действие порошка долго не продержится.','Украдите мешок Груллока.','Вернитесь к барону Черногриву в Круг Крови, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спи спокойно, гронн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я снова превзошел самого себя! Я сделал сонный порошок. Бери его и используй против Груллока, того самого гронна, который стережет ту вещь, что мне нужна.$B$BГруллок засел в Окаянной лощине, что в восточном конце Драконьей Пагубы по ту сторону Круга Крови.$B$BБудь я на твоем месте, я не стал бы тянуть, как только стянул бы его мешок. Действие порошка долго не продержится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите мешок Груллока.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к барону Черногриву в Круг Крови, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (10801,'Ловушка!','Никого в этом мире я не ненавижу сильнее чем этого Груула и его сыновей! Они истребили мой народ – моих детей – но теперь я отомщу.$B$BЯ создал ловушку из драконьего огня, и если тебе хватит сообразительности, то с ее помощью ты сможешь прикончить даже гронна.$B$BТоропись, отнеси эту ловушку твоему командиру Каменной Стене. Я хочу утолить жажду мести!','Отнесите ловушку пламени дракона командиру Гефусу Камнестену в Вечную рощу в Острогорье.','Барон изготовил ловушку? Она способна прикончить гронна?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловушка!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Никого в этом мире я не ненавижу сильнее чем этого Груула и его сыновей! Они истребили мой народ – моих детей – но теперь я отомщу.$B$BЯ создал ловушку из драконьего огня, и если тебе хватит сообразительности, то с ее помощью ты сможешь прикончить даже гронна.$B$BТоропись, отнеси эту ловушку твоему командиру Каменной Стене. Я хочу утолить жажду мести!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите ловушку пламени дракона командиру Гефусу Камнестену в Вечную рощу в Острогорье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Барон изготовил ловушку? Она способна прикончить гронна?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10802,'Горгром Драконоед','Добудьте 3 тотема гризли у огров Камен\'мока. Поставьте ловушку Черногрива на алтарь Горгрома, затем призовите и убейте Горгрома Драконоеда.$b$bКогда Горгром будет убит, поставьте 3 тотема гризли возле его туши.','Ну, ты $Gоставил:оставила; им послание?','Вернитесь к командиру Гефусу Камнестену в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Горгром Драконоед',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 тотема гризли у огров Камен\'мока. Поставьте ловушку Черногрива на алтарь Горгрома, затем призовите и убейте Горгрома Драконоеда.$b$bКогда Горгром будет убит, поставьте 3 тотема гризли возле его туши.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, ты $Gоставил:оставила; им послание?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Гефусу Камнестену в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10803,'Резня в Камен\'моке','Я знаю, что у нас были планы направить вас в Камен\'мок. В связи с этим у меня есть для вас одно поручение.$B$BМы должны пользоваться любой возможностью разбить огров здешних гор, иначе они просто задавят нас числом, и все, за что мы заплатили кровью, пойдет прахом!$B$BКамен\'мок находится на западе. Отправляйтесь на юго-запад через мост, затем прямо в туннель. На западной стороне Леса Ворона вы их обнаружите.$B$B$n, я желаю, чтобы вы стерли с лица земли огров Камен\'мока!','Убейте 5 громил и 3 шаманов Камен\'мока.','Вернитесь к лейтенанту Файрвезер в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Резня в Камен\'моке',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я знаю, что у нас были планы направить вас в Камен\'мок. В связи с этим у меня есть для вас одно поручение.$B$BМы должны пользоваться любой возможностью разбить огров здешних гор, иначе они просто задавят нас числом, и все, за что мы заплатили кровью, пойдет прахом!$B$BКамен\'мок находится на западе. Отправляйтесь на юго-запад через мост, затем прямо в туннель. На западной стороне Леса Ворона вы их обнаружите.$B$B$n, я желаю, чтобы вы стерли с лица земли огров Камен\'мока!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 5 громил и 3 шаманов Камен\'мока.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Файрвезер в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10804,'Доброта','Накормите 8 взрослых драконов Пустоты по просьбе Морденая на Полях Крыльев Пустоты.','Вернитесь к Морденаю на Поля Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доброта',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Накормите 8 взрослых драконов Пустоты по просьбе Морденая на Полях Крыльев Пустоты.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морденаю на Поля Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10807,'Сломленные из племени Пеплоустов','Пеплоустов боятся все Павшие, В этот клан входят самые жестокие и кровожадные представители племени, которых отбирает лично Акама. Свирепостью они не уступают ни нагам, ни демонам, ни эльфам крови из армии Иллидана, и сейчас они во множестве собрались в руинах Баа\'ри к северу отсюда. Ступай туда и прореди их число, прежде чем они соберутся напасть на нас.','Убейте для Варена Исправителя 3 укротителей, 4 воинов и 6 шаманов из племени Пеплоустов.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.','Слава Провидцам, $N! Ты $Gисполнил:исполнила; волю Провидца, сокрушив тех, кто служит Иллидану.','$GВыполнил:Выполнила; ли ты порученное тебе задание, $N?','Вернитесь к Варену Исправителю в Святилище Звезд, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сломленные из племени Пеплоустов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пеплоустов боятся все Павшие, В этот клан входят самые жестокие и кровожадные представители племени, которых отбирает лично Акама. Свирепостью они не уступают ни нагам, ни демонам, ни эльфам крови из армии Иллидана, и сейчас они во множестве собрались в руинах Баа\'ри к северу отсюда. Ступай туда и прореди их число, прежде чем они соберутся напасть на нас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте для Варена Исправителя 3 укротителей, 4 воинов и 6 шаманов из племени Пеплоустов.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава Провидцам, $N! Ты $Gисполнил:исполнила; волю Провидца, сокрушив тех, кто служит Иллидану.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GВыполнил:Выполнила; ли ты порученное тебе задание, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варену Исправителю в Святилище Звезд, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10808,'Крах темного конклава','Духи, входящие в темный конклав, намерены воззвать к темному и древнему злу через ритуал, который они проведут возле лавовых ям к югу от Лагеря Скет\'лона.$B$BМагия Гул\'дана, смешавшаяся с их собственной, призывает их вновь вернуть этого смертельно опасного чародея в наш мир. Мы не можем этого позволить, $n. Хаос и разрушения, которые он принесет с собой, будут неизмеримы.$B$BБери с собой посох, отправляйся на место проведения ритуала и останови темный конклав раз и навсегда.','Убейте ритуалистов Темного конклава и используйте посох Паршаха, чтобы прервать ритуал призыва. По выполнении задания вернитесь к Паршаху в Магмовые поля.','Я искал способ остановить темный конклав годами, а тебе это удалось так быстро! Теперь они больше не являются для нас угрозой.$B$BЯ часто чувствую свою вину за то, что бросил своих товарищей перед лицом смерти. Но теперь я знаю, что принял правильное решение. Если бы тогда моя решимость не дрогнула, я бы стал такой же безропотной тенью.','Вернитесь к Паршаху на Магмовые поля, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крах темного конклава',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духи, входящие в темный конклав, намерены воззвать к темному и древнему злу через ритуал, который они проведут возле лавовых ям к югу от Лагеря Скет\'лона.$B$BМагия Гул\'дана, смешавшаяся с их собственной, призывает их вновь вернуть этого смертельно опасного чародея в наш мир. Мы не можем этого позволить, $n. Хаос и разрушения, которые он принесет с собой, будут неизмеримы.$B$BБери с собой посох, отправляйся на место проведения ритуала и останови темный конклав раз и навсегда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте ритуалистов Темного конклава и используйте посох Паршаха, чтобы прервать ритуал призыва. По выполнении задания вернитесь к Паршаху в Магмовые поля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я искал способ остановить темный конклав годами, а тебе это удалось так быстро! Теперь они больше не являются для нас угрозой.$B$BЯ часто чувствую свою вину за то, что бросил своих товарищей перед лицом смерти. Но теперь я знаю, что принял правильное решение. Если бы тогда моя решимость не дрогнула, я бы стал такой же безропотной тенью.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Паршаху на Магмовые поля, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10809,'В объявлении написано следующее:$B$B"Повелитель воргов Крууш возглавляет наездников на воргах клана Кровавой Глазницы. Он и его наездники виновны в совершении налетов на караваны с припасами Заставы Хребтолома. За их головы назначена награда."$B$B"В последний раз разведчики видели Крууша возле Зет\'Гора. Храбрец, который принесет головы негодяев, заслужит благодарность Орды и солидное денежное вознаграждение."$B$B"Капитан Мрачный Вой"','Убейте повелителя воргов Крууша и принесите его голову капитану Мрачному Вою на Заставу Хребтолома.','Вернитесь к капитану Мрачному Вою на Заставу Хребтолома, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В объявлении написано следующее:$B$B"Повелитель воргов Крууш возглавляет наездников на воргах клана Кровавой Глазницы. Он и его наездники виновны в совершении налетов на караваны с припасами Заставы Хребтолома. За их головы назначена награда."$B$B"В последний раз разведчики видели Крууша возле Зет\'Гора. Храбрец, который принесет головы негодяев, заслужит благодарность Орды и солидное денежное вознаграждение."$B$B"Капитан Мрачный Вой"',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте повелителя воргов Крууша и принесите его голову капитану Мрачному Вою на Заставу Хребтолома.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Мрачному Вою на Заставу Хребтолома, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (10810,'Поврежденная маска') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поврежденная маска',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (10811,'Поиски Нельтараку','Найдите Нельтараку, предводителя рода Крыльев Пустоты.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Нельтараку',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Нельтараку, предводителя рода Крыльев Пустоты.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (10812,'Тайная маска','Ну, вот, теперь будет работать. Желаешь знать, что это такое? Да устройство связи – позволяет этим тупицам общаться друг с другом. И это Пылающий Легион! Я бы предложил отнести эту маску Владыке леса Антелариону. Он тут где-то снаружи прогуливается. Никогда на месте не сидит, понимаете ли.$B$BЕму такую штуку уже давно заполучить хочется.','Глазам своим не верю!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайная маска',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, вот, теперь будет работать. Желаешь знать, что это такое? Да устройство связи – позволяет этим тупицам общаться друг с другом. И это Пылающий Легион! Я бы предложил отнести эту маску Владыке леса Антелариону. Он тут где-то снаружи прогуливается. Никогда на месте не сидит, понимаете ли.$B$BЕму такую штуку уже давно заполучить хочется.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Глазам своим не верю!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10813,'Очи Гриллока','Используйте кристалл Зеззака, чтобы захватить Око Гриллока, затем приблизьтесь к котлу Зеззака, чтобы тот смог извлечь Око. После выполнения задания верните Зеззаку кристалл.','Вернитесь к Зеззаку на Заставу Хребтолома, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очи Гриллока',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте кристалл Зеззака, чтобы захватить Око Гриллока, затем приблизьтесь к котлу Зеззака, чтобы тот смог извлечь Око. После выполнения задания верните Зеззаку кристалл.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зеззаку на Заставу Хребтолома, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10814,'История Нельтараку','У меня есть информация, которая тебе пригодится. Слушай внимательно, |3-6($r).','Поговорите с Нельтараку и выслушайте его историю.','Так ты поможешь нам?','История Нельтараку','Вернитесь к Нельтараку на Поля Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','История Нельтараку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть информация, которая тебе пригодится. Слушай внимательно, |3-6($r).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Нельтараку и выслушайте его историю.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ты поможешь нам?',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','История Нельтараку',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нельтараку на Поля Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10815,'Записи Вал\'зарека: Предвестье Войны','В этом журнале описаны недавние действия армии Иллидана. Также в нем объясняется, почему Вал\'зарек так демонстративно использовал Путь Завоевания. Ему был поручен захват верховного генерала Ша\'тар.$B$BЭтот генерал находился в пункте известном как Кровавый Дозор, расположенном в южном конце Пути Завоевания. Таинственная группа, называющая себя Кровавая Печать, обвиняется в его похищении. Если ты решишь разузнать больше об этом деле, захвати с собой подмогу.','Найдите Марка Аврелиона, верховного генерала Ша\'тар, в Кровавом Дозоре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Записи Вал\'зарека: Предвестье Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом журнале описаны недавние действия армии Иллидана. Также в нем объясняется, почему Вал\'зарек так демонстративно использовал Путь Завоевания. Ему был поручен захват верховного генерала Ша\'тар.$B$BЭтот генерал находился в пункте известном как Кровавый Дозор, расположенном в южном конце Пути Завоевания. Таинственная группа, называющая себя Кровавая Печать, обвиняется в его похищении. Если ты решишь разузнать больше об этом деле, захвати с собой подмогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Марка Аврелиона, верховного генерала Ша\'тар, в Кровавом Дозоре.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10816,'Восстановление Святых земель','Убейте для воздаятеля Алуумена 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.','Прекрасно, |3-6($C). Да пребудет с тобой Свет.','Привет, $N. Какие новости?','Вернитесь к воздаятелю Алуумену к алтарю Ша\'тар, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстановление Святых земель',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте для воздаятеля Алуумена 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, |3-6($C). Да пребудет с тобой Свет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $N. Какие новости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Алуумену к алтарю Ша\'тар, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10817,'Великое воздаяние','Ты неплохо $gпоказал:показала; себя против сломленных из племени Пеплоустов, $n. Теперь у меня для тебя новое задание. $B$BНе так давно Святилище Звезд захватили иллидановы орки Скверны.$B$BНам известно, что это совершили орки из клана Призрачной Луны, которые сейчас занимают Террасу Ата\'мала.$B$BПокажи им, что с Провидцами шутить не стоит.','Убейте для Варена Исправителя 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.','Сегодня ты $Gзавоевал:завоевала; мое безмерное уважение, $N.$B$BУбить одного орка Скверны не так то просто, но уничтожить столько... Это поистине подвиг!','Привет, $N. Какие новости?','Вернитесь к Варену Исправителю в Святилище Звезд, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великое воздаяние',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты неплохо $gпоказал:показала; себя против сломленных из племени Пеплоустов, $n. Теперь у меня для тебя новое задание. $B$BНе так давно Святилище Звезд захватили иллидановы орки Скверны.$B$BНам известно, что это совершили орки из клана Призрачной Луны, которые сейчас занимают Террасу Ата\'мала.$B$BПокажи им, что с Провидцами шутить не стоит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте для Варена Исправителя 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сегодня ты $Gзавоевал:завоевала; мое безмерное уважение, $N.$B$BУбить одного орка Скверны не так то просто, но уничтожить столько... Это поистине подвиг!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $N. Какие новости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Варену Исправителю в Святилище Звезд, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10818,'Барон Черногрив желает вас лицезреть','$n, пока ты демон знает где $Gгеройствовал:геройствовала;, сюда прилетал ручной дракон барона Черногрива с посланием.$B$BТребует тебя лично. Как я понял, он хочет, чтобы ты $Gпомог:помогла; ему в его личной разборке с гронном.$B$BПонятно, что лучше тебя в Запределье ему не найти для этого дела, Но на твоем месте я оповестил бы парочку друзей и назначил бы им встречу у Круга Крови.','Поговорите с бароном Черногривом в Круге Крови в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Барон Черногрив желает вас лицезреть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, пока ты демон знает где $Gгеройствовал:геройствовала;, сюда прилетал ручной дракон барона Черногрива с посланием.$B$BТребует тебя лично. Как я понял, он хочет, чтобы ты $Gпомог:помогла; ему в его личной разборке с гронном.$B$BПонятно, что лучше тебя в Запределье ему не найти для этого дела, Но на твоем месте я оповестил бы парочку друзей и назначил бы им встречу у Круга Крови.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с бароном Черногривом в Круге Крови в Острогорье.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (10819,'Респиратор Искаженных','Это еще что такое! Кто смеет меня вызывать? Говори, или заставлю тебя умолкнуть навеки!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Респиратор Искаженных',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это еще что такое! Кто смеет меня вызывать? Говори, или заставлю тебя умолкнуть навеки!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10820,'Обмануть врага','Чем дольше ты молчишь, тем ближе ты к смерти! ГОВОРИ!$B$BЧто? В лагере бунт? Не может быть такого! Мои рабы не посмеют испытывать на прочность мою власть!$B$BНу, ужо им, все до единого они заплатят за предательство, и дорого заплатят! Заткни их, и покончим с этим! Как только выполнишь приказ, доложи мне, иначе я и с тобой разделаюсь!','Убейте 4 рабочих Кузни Рока и 4 инженеров Кузни Рока.','Мое терпение утомляет, почему ты их не $Gдоделал:доделала;?','Вернитесь к переговорному устройству Легиона в Острогорье в Лагерь Легиона: Злоба.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обмануть врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чем дольше ты молчишь, тем ближе ты к смерти! ГОВОРИ!$B$BЧто? В лагере бунт? Не может быть такого! Мои рабы не посмеют испытывать на прочность мою власть!$B$BНу, ужо им, все до единого они заплатят за предательство, и дорого заплатят! Заткни их, и покончим с этим! Как только выполнишь приказ, доложи мне, иначе я и с тобой разделаюсь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 4 рабочих Кузни Рока и 4 инженеров Кузни Рока.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мое терпение утомляет, почему ты их не $Gдоделал:доделала;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к переговорному устройству Легиона в Острогорье в Лагерь Легиона: Злоба.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10822,'Перстень Ярости Солнца','Армия Кель\'таса скоро падёт.','Даже самая маленькая помощь нашему делу не останется незамеченной, $N. Армия врага велика, но победа будет за нами!','Вернитесь к боевому магу Вияре в Долину Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перстень Ярости Солнца',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Армия Кель\'таса скоро падёт.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Даже самая маленькая помощь нашему делу не останется незамеченной, $N. Армия врага велика, но победа будет за нами!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому магу Вияре в Долину Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10823,'Больше перстней Ярости Солнца','Ты делаешь себе имя, $N. Так держать.','Что ты $Gсделал:сделала; для нас за последнее время, $N?','Вернитесь к боевому магу Вияре в Долину Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше перстней Ярости Солнца',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты делаешь себе имя, $N. Так держать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ты $Gсделал:сделала; для нас за последнее время, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому магу Вияре в Долину Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10824,'Перстни Ярости Солнца','Выживут ли Провидцы, сейчас зависит от того, сможем ли мы прекратить рост армии Кель\'таса. Каждый путник из Кель\'Таласа, встающий под знамена принца, еще на один шаг приближает его к победе. В принципе, то же самое верно и для нас.$B$BКак только приток новобранцев кончится, война сведется к тому, кто быстрее перебьет войско противника. Докажи свою верность Провидцам, принеси мне перстни Ярости Солнца, которые носят высокопоставленные эльфы крови, союзники Келя и Иллидана. Ты найдешь этих эльфов в Лагере Затмения к западу отсюда или в руинах Карабора на северо-востоке.','Принесите 10 перстней Ярости Солнца боевому магу Вияре в святилище Звезд.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.','Победить эльфов Келя, не так-то просто. Превосходно!','Продолжай, $N.','Вернитесь к боевому магу Вияре в Святилище Звезд, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перстни Ярости Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Выживут ли Провидцы, сейчас зависит от того, сможем ли мы прекратить рост армии Кель\'таса. Каждый путник из Кель\'Таласа, встающий под знамена принца, еще на один шаг приближает его к победе. В принципе, то же самое верно и для нас.$B$BКак только приток новобранцев кончится, война сведется к тому, кто быстрее перебьет войско противника. Докажи свою верность Провидцам, принеси мне перстни Ярости Солнца, которые носят высокопоставленные эльфы крови, союзники Келя и Иллидана. Ты найдешь этих эльфов в Лагере Затмения к западу отсюда или в руинах Карабора на северо-востоке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 перстней Ярости Солнца боевому магу Вияре в святилище Звезд.$B$BВыполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Победить эльфов Келя, не так-то просто. Превосходно!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Продолжай, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому магу Вияре в Святилище Звезд, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (10825,'Тайна сферы','Да, это твой шар! Как странно – похоже, его сделали араккоа. Ты что, только что из Гришната?$B$BТогда все ясно, но какой недоброй цели он служит – я не понимаю. Хотя он источает зло, у меня такое ощущение, будто он как-то связан с миром природы.$B$BДай-ка я попытаюсь активировать его. Хотя в нем таится сильное зло, в нем есть какая-то остаточная память...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна сферы',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это твой шар! Как странно – похоже, его сделали араккоа. Ты что, только что из Гришната?$B$BТогда все ясно, но какой недоброй цели он служит – я не понимаю. Хотя он источает зло, у меня такое ощущение, будто он как-то связан с миром природы.$B$BДай-ка я попытаюсь активировать его. Хотя в нем таится сильное зло, в нем есть какая-то остаточная память...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10826,'Знаки Саргераса','Теперь тебе должно быть ясно, почему мы враждуем с Легионом и его приспешниками.$B$BЕсли ты хочешь упрочить свое положение среди Алдоров, принеси мне высшие знаки отличия Легиона и их последователей из Совета Теней. Здесь в Долине Призрачной Луны сейчас находится множество воинов Легиона, в особенности в западной части долины, возле форта Легиона и Кузниц Смерти.','Принесите 10 знаков Саргераса предвестнику Саронену в Долину Призрачной Луны.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.','Ты $Gотважен:отважна;, $Gдруг:подруга; $Gмой:моя;. Пусть отныне все узнают, что ты – $Gнаш:наша; $Gистинный:истинная; $Gсоюзник:союзница;.','$GПринес:Принесла; ли ты вражеские знаки отличия, $N?','Вернитесь к предвестнику Саронену к алтарю Ша\'тар, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знаки Саргераса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь тебе должно быть ясно, почему мы враждуем с Легионом и его приспешниками.$B$BЕсли ты хочешь упрочить свое положение среди Алдоров, принеси мне высшие знаки отличия Легиона и их последователей из Совета Теней. Здесь в Долине Призрачной Луны сейчас находится множество воинов Легиона, в особенности в западной части долины, возле форта Легиона и Кузниц Смерти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 знаков Саргераса предвестнику Саронену в Долину Призрачной Луны.$B$BВыполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gотважен:отважна;, $Gдруг:подруга; $Gмой:моя;. Пусть отныне все узнают, что ты – $Gнаш:наша; $Gистинный:истинная; $Gсоюзник:союзница;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$GПринес:Принесла; ли ты вражеские знаки отличия, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Саронену к алтарю Ша\'тар, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10827,'Больше знаков Саргераса','Вы растете в наших глазах, $N. Боритесь с врагами Света повсюду, и ваши подвиги будут достойно вознаграждены.','Вы принесли еще знаков различия наших врагов, |3-6($C)? Пылающий Легион все еще угрожает нам, и мы преследуем его повсеместно.','Вернитесь к предвестнику Саронену в Долину Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше знаков Саргераса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы растете в наших глазах, $N. Боритесь с врагами Света повсюду, и ваши подвиги будут достойно вознаграждены.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы принесли еще знаков различия наших врагов, |3-6($C)? Пылающий Легион все еще угрожает нам, и мы преследуем его повсеместно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Саронену в Долину Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10828,'Знак Саргераса','Вы растете в наших глазах, $N. Боритесь с врагами Света повсюду, и ваши подвиги будут достойно вознаграждены.','Я приму любой оставшийся у тебя знак. Не волнуйся, твои усилия будут оценены должным образом.','Вернитесь к предвестнику Саронену в Долину Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знак Саргераса',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы растете в наших глазах, $N. Боритесь с врагами Света повсюду, и ваши подвиги будут достойно вознаграждены.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я приму любой оставшийся у тебя знак. Не волнуйся, твои усилия будут оценены должным образом.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Саронену в Долину Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (10829,'Древоствол должен знать!','Очень тревожно! Эти араккоа делают так, что Древа и защитники леса подпадают под власть злых духов!$B$BНо осталось еще одно древо, которое не пострадало. Его имя Древоствол, и ты $Gдолжен:должна; тотчас пойти к нему, если мы хотим спасти деревья Леса Ворона!$B$BВозвращайся в Лес Ворона. Ты найдешь его на развилке тропы сразу после Гришната.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Древоствол должен знать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Очень тревожно! Эти араккоа делают так, что Древа и защитники леса подпадают под власть злых духов!$B$BНо осталось еще одно древо, которое не пострадало. Его имя Древоствол, и ты $Gдолжен:должна; тотчас пойти к нему, если мы хотим спасти деревья Леса Ворона!$B$BВозвращайся в Лес Ворона. Ты найдешь его на развилке тропы сразу после Гришната.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10830,'Экзорцизм для деревьев','Найдите 5 сфер Гришната и 5 перьев ужасающего ворона и превратите их в перья изгнания духов. При помощи этих перьев изгоните и уничтожьте 5 духов кои-кои из листобородов Леса Ворона.','Зло, обитающее в деревьях, начинает проникать во все естественное в лесу.$B$BТы $Gдолжен:должна; действовать быстро, $N, пока все не пропало!','Вернитесь к Древостволу в Лес Ворона, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экзорцизм для деревьев',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите 5 сфер Гришната и 5 перьев ужасающего ворона и превратите их в перья изгнания духов. При помощи этих перьев изгоните и уничтожьте 5 духов кои-кои из листобородов Леса Ворона.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Зло, обитающее в деревьях, начинает проникать во все естественное в лесу.$B$BТы $Gдолжен:должна; действовать быстро, $N, пока все не пропало!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Древостволу в Лес Ворона, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10831,'Обучение шитью из луноткани','Если хотите, я могу научить вас шить из луноткани. Вы научитесь ткать изначальную луноткань, которой у вас получится в два раза больше, чем у обычного портного, и сможете выучить несколько специальных выкроек. Но сначала придется пройти небольшое испытание.$B$BВам нужно изготовить образец изначальной луноткани в колодце Кенарийского оплота. Все необходимые материалы я вам дам. Когда изготовите образец, приносите его мне, я посмотрю.','Возьмите отрез прочной ткани Пустоты, встаньте в Лунный колодец Кенарийского оплота и изготовьте изначальную луноткань. Готовую ткань отнесите Назмаре Песне Луны в Нижний Город Шаттрата.$B$B*ВНИМАНИЕ!* Вы можете специализироваться только на одном виде ткани.','<Насмара осматривает ткань и вертеть ее в руках.>$B$BЭто очень хороший образец, $N. Из вас получится отличный портной луноткани.','Вы создали образец изначальной луноткани?','Вернитесь к Назмаре Песни Луны в Шаттрат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение шитью из луноткани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хотите, я могу научить вас шить из луноткани. Вы научитесь ткать изначальную луноткань, которой у вас получится в два раза больше, чем у обычного портного, и сможете выучить несколько специальных выкроек. Но сначала придется пройти небольшое испытание.$B$BВам нужно изготовить образец изначальной луноткани в колодце Кенарийского оплота. Все необходимые материалы я вам дам. Когда изготовите образец, приносите его мне, я посмотрю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите отрез прочной ткани Пустоты, встаньте в Лунный колодец Кенарийского оплота и изготовьте изначальную луноткань. Готовую ткань отнесите Назмаре Песне Луны в Нижний Город Шаттрата.$B$B*ВНИМАНИЕ!* Вы можете специализироваться только на одном виде ткани.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Насмара осматривает ткань и вертеть ее в руках.>$B$BЭто очень хороший образец, $N. Из вас получится отличный портной луноткани.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы создали образец изначальной луноткани?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Назмаре Песни Луны в Шаттрат.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10832,'Обучение шитью из огненной чароткани','Я могу обучить вас шитью из ткани огненных чар, но помните, что это довольно опасное занятие.$B$BКогда будете изготавливать ткань в Пустоверти, вы привлечете внимание могущественных призраков. Я ищу способ избежать этого, но для исследований мне не хватает сущностей Призраков Пустоты.$B$BВот, возьмите с собой в Пустоверть этот маяк, вызовите с его помощью призрака и принесите мне его сущность – тогда я обучу вас. Те, кто умеет шить из ткани огненной чароткани, изготавливают в два раза больше этой ткани и получают эксклюзивные выкройки.','Принесите образец сущности призрака Пустоты Гидже Чароплетке в Нижний Город Шаттрата.$B$B*ВНИМАНИЕ!* Вы можете специализироваться только на одном виде шитья.','<Гиджа исследует сущность призрака Пустоты.>$B$BДаже этот небольшой образец сущности существа излучает мощь. Возможно, я неправильно поняла, что происходит. Мы не злим призраков, забирая энергию из окружающей среды. Скорее призраки и окружение - это одно и то же!$B$BНе стесняйтесь сообщить мне, если вы сделаете какие-либо дальнейшие открытия, теперь, когда вы стали портным огненной чароткани.','Вы получили сущность призрака пустоты?','Вернитесь к Гидже Чароплетке в Шаттрат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение шитью из огненной чароткани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я могу обучить вас шитью из ткани огненных чар, но помните, что это довольно опасное занятие.$B$BКогда будете изготавливать ткань в Пустоверти, вы привлечете внимание могущественных призраков. Я ищу способ избежать этого, но для исследований мне не хватает сущностей Призраков Пустоты.$B$BВот, возьмите с собой в Пустоверть этот маяк, вызовите с его помощью призрака и принесите мне его сущность – тогда я обучу вас. Те, кто умеет шить из ткани огненной чароткани, изготавливают в два раза больше этой ткани и получают эксклюзивные выкройки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите образец сущности призрака Пустоты Гидже Чароплетке в Нижний Город Шаттрата.$B$B*ВНИМАНИЕ!* Вы можете специализироваться только на одном виде шитья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Гиджа исследует сущность призрака Пустоты.>$B$BДаже этот небольшой образец сущности существа излучает мощь. Возможно, я неправильно поняла, что происходит. Мы не злим призраков, забирая энергию из окружающей среды. Скорее призраки и окружение - это одно и то же!$B$BНе стесняйтесь сообщить мне, если вы сделаете какие-либо дальнейшие открытия, теперь, когда вы стали портным огненной чароткани.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы получили сущность призрака пустоты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гидже Чароплетке в Шаттрат.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10833,'Обучение шитью из тенеткани','Если вы решили специализироваться на шитье из тенеткани, то будете изготавливать в два раза больше такой ткани по сравнению с обычными портными, а также получите несколько эксклюзивных выкроек.$B$BРазумеется, любой портной может пользоваться Алтарем Теней, но специалисты по тенеткани чувствуют его силу гораздо лучше и обладают способностями, доступными далеко не всем.$B$BВот, отнесите этот кристалл в восточную часть долины Призрачной Луны и найдите там перевал Крыльев Пустоты – он идет на юг от полей Крыльев Пустоты. Возле самого края земли стоит Алтарь Теней – задействуйте кристалл именно там.','Укрепите связь с Алтарем Теней при помощи кристалла глубоких теней, после чего вернитесь к Андриону Темнопряду в Нижний Город Шаттрата.$B$B*ВНИМАНИЕ!* Вы можете специализироваться только на одном виде шитья.','Я вижу, что ваше посещение алтаря прошло успешно. В вас есть тонкая разница, которую немногие заметят, но нет никаких сомнений в том, что она есть.','Вы использовали силу кристалла, чтобы глубже настроиться на Алтарь Теней?','Вернитесь к Андриону Темнопряду в Шаттрат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение шитью из тенеткани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если вы решили специализироваться на шитье из тенеткани, то будете изготавливать в два раза больше такой ткани по сравнению с обычными портными, а также получите несколько эксклюзивных выкроек.$B$BРазумеется, любой портной может пользоваться Алтарем Теней, но специалисты по тенеткани чувствуют его силу гораздо лучше и обладают способностями, доступными далеко не всем.$B$BВот, отнесите этот кристалл в восточную часть долины Призрачной Луны и найдите там перевал Крыльев Пустоты – он идет на юг от полей Крыльев Пустоты. Возле самого края земли стоит Алтарь Теней – задействуйте кристалл именно там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Укрепите связь с Алтарем Теней при помощи кристалла глубоких теней, после чего вернитесь к Андриону Темнопряду в Нижний Город Шаттрата.$B$B*ВНИМАНИЕ!* Вы можете специализироваться только на одном виде шитья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я вижу, что ваше посещение алтаря прошло успешно. В вас есть тонкая разница, которую немногие заметят, но нет никаких сомнений в том, что она есть.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы использовали силу кристалла, чтобы глубже настроиться на Алтарь Теней?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Андриону Темнопряду в Шаттрат.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (10835,'Аптекарь Антонивич','$n, я подготовил промежуточный отчет о своей работе с кровью орков Кровавой Глазницы. Думаю, мой траллмарский коллега аптекарь Антонивич будет счастлив получить его. Он тоже изучает феномен орков Скверны... При необходимости мы должны суметь оградить наших оркских союзников от трагедии, которая приключилась с их собратьями.$B$BДоставь Антонивичу мое донесение, а я пока продолжу исследование принесенных тобой образцов крови. Если нам повезет, мы поймем, чем вызвано появление орков Скверны.','А-а, послание Албрека! Очень хорошо. Королевское Фармацевтическое Общество работает день и ночь, чтобы определить, как же орки Скверны стали орками Скверны. Их предательству нет прощения... Мы должны гарантировать, что сумеем защитить от подобной напасти наших друзей-орков.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аптекарь Антонивич',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я подготовил промежуточный отчет о своей работе с кровью орков Кровавой Глазницы. Думаю, мой траллмарский коллега аптекарь Антонивич будет счастлив получить его. Он тоже изучает феномен орков Скверны... При необходимости мы должны суметь оградить наших оркских союзников от трагедии, которая приключилась с их собратьями.$B$BДоставь Антонивичу мое донесение, а я пока продолжу исследование принесенных тобой образцов крови. Если нам повезет, мы поймем, чем вызвано появление орков Скверны.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А-а, послание Албрека! Очень хорошо. Королевское Фармацевтическое Общество работает день и ночь, чтобы определить, как же орки Скверны стали орками Скверны. Их предательству нет прощения... Мы должны гарантировать, что сумеем защитить от подобной напасти наших друзей-орков.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10836,'Переполох в крепости Драконьей Пасти','Мне необходимо время, чтобы разработать план по спасению моих детей и супруги. И ты обеспечишь мне это время, $gсмертный:смертная;.$B$BОтправляйся в крепость Драконьей Пасти, расположенную на восточном краю полей Крыльев Пустоты, и убей всех орков, которые попадутся тебе на пути. Воцарившийся хаос сорвет все их планы.$B$BБудь $gосторожен:осторожна; – некоторые из моего народа не в себе, их разум подчинен шаманам клана. Единственный выход для них – смерть. Я надеюсь, ты поможешь им обрести ее.','Убейте 15 орков из клана Драконьей Пасти для Нельтараку.$B$BЗасчитывается орк любого ранга.','Вернитесь к Нельтараку на Поля Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переполох в крепости Драконьей Пасти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне необходимо время, чтобы разработать план по спасению моих детей и супруги. И ты обеспечишь мне это время, $gсмертный:смертная;.$B$BОтправляйся в крепость Драконьей Пасти, расположенную на восточном краю полей Крыльев Пустоты, и убей всех орков, которые попадутся тебе на пути. Воцарившийся хаос сорвет все их планы.$B$BБудь $gосторожен:осторожна; – некоторые из моего народа не в себе, их разум подчинен шаманам клана. Единственный выход для них – смерть. Я надеюсь, ты поможешь им обрести ее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 орков из клана Драконьей Пасти для Нельтараку.$B$BЗасчитывается орк любого ранга.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нельтараку на Поля Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10837,'На Кряж Крыльев Пустоты!','Соберите для Нельтараку 12 кристаллов Лозы Пустоты на Кряже Крыльев Пустоты.','Где мои кристаллы.','Вернитесь к Нельтараку на Поля Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На Кряж Крыльев Пустоты!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите для Нельтараку 12 кристаллов Лозы Пустоты на Кряже Крыльев Пустоты.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где мои кристаллы.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нельтараку на Поля Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10839,'Гнездовье Скит: Темный камень Терокка','Гнездовье Скит находится к северо-западу от каравана и к югу от Шаттрата, в чаще леса. Говорят, что там поселенцы Скеттиса воздвигли темный алтарь для поклонения своему богу. Если мы хотим, чтобы араккоа Скеттиса когда-либо узрели Свет, мы должны уничтожить этот Темный камень Терокка.$B$BВозьми этот жезл Очищения и направь его на Темный камень. Этот жезл благословлен самим А\'далом, и его чистоты должно хватить для того, чтобы изгнать всю скверну из этого алтаря. Ступай, и да озарит свет твой путь.','Тьма окружает нас. Что ты можешь рассказать о завесе Скит?','Попытайтесь очистить темный камень Терокка','Вернитесь к Киррику Пробужденному к Каравану Беженцев, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнездовье Скит: Темный камень Терокка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гнездовье Скит находится к северо-западу от каравана и к югу от Шаттрата, в чаще леса. Говорят, что там поселенцы Скеттиса воздвигли темный алтарь для поклонения своему богу. Если мы хотим, чтобы араккоа Скеттиса когда-либо узрели Свет, мы должны уничтожить этот Темный камень Терокка.$B$BВозьми этот жезл Очищения и направь его на Темный камень. Этот жезл благословлен самим А\'далом, и его чистоты должно хватить для того, чтобы изгнать всю скверну из этого алтаря. Ступай, и да озарит свет твой путь.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тьма окружает нас. Что ты можешь рассказать о завесе Скит?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Попытайтесь очистить темный камень Терокка',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киррику Пробужденному к Каравану Беженцев, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10840,'Гробница Света','На востоке, под обугленными песками, находится Гробница Света – заброшенное место для захоронения мертвых. Я собирался войти туда и изгнать злых духов, но потом на наш караван напали, и теперь мне немного не до того...$B$BЕдинственное, что мне удалось узнать – это то, что там теперь объявилось новое зло – духи Астрала. Они обыскивают мертвые тела и крадут с них украшения и амулеты.$B$BНо пока мой караван в таком состоянии, я мало что могу сделать для гробницы...','Отправляйтесь в Гробницу Света и убейте там 10 эфириалов-пустомантов и 10 эфириалов-расхитителей, после чего вернитесь к верховному жрецу Орглуму в Караван беженцев.','Сколько эфириалов ты $Gуничтожил:уничтожила;? Надеюсь, этого будет достаточно, чтобы выгнать их из Гробницы Света.','Вернитесь к верховному жрецу Орглуму к Каравану Беженцев, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гробница Света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На востоке, под обугленными песками, находится Гробница Света – заброшенное место для захоронения мертвых. Я собирался войти туда и изгнать злых духов, но потом на наш караван напали, и теперь мне немного не до того...$B$BЕдинственное, что мне удалось узнать – это то, что там теперь объявилось новое зло – духи Астрала. Они обыскивают мертвые тела и крадут с них украшения и амулеты.$B$BНо пока мой караван в таком состоянии, я мало что могу сделать для гробницы...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Гробницу Света и убейте там 10 эфириалов-пустомантов и 10 эфириалов-расхитителей, после чего вернитесь к верховному жрецу Орглуму в Караван беженцев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько эфириалов ты $Gуничтожил:уничтожила;? Надеюсь, этого будет достаточно, чтобы выгнать их из Гробницы Света.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному жрецу Орглуму к Каравану Беженцев, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10842,'Мстительные души','Гробницу Света захватил Совет Теней, и умершие дренеи превратились в проклятых духов, одержимых яростью и ненавистью ко всему живому.$B$BВойди в гробницу и отыщи этих невинных жертв. Даруй им покой, который они заслужили.','Верховный жрец Орглум велит вам отправиться в Гробницу Света и убить 5 мстительных дренеев.','Вы спасли нас всех! Как нам отблагодарить вас?','Поговорите с верховным жрецом Орглумом в Караване Беженцев, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мстительные души',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гробницу Света захватил Совет Теней, и умершие дренеи превратились в проклятых духов, одержимых яростью и ненавистью ко всему живому.$B$BВойди в гробницу и отыщи этих невинных жертв. Даруй им покой, который они заслужили.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный жрец Орглум велит вам отправиться в Гробницу Света и убить 5 мстительных дренеев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы спасли нас всех! Как нам отблагодарить вас?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с верховным жрецом Орглумом в Караване Беженцев, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10843,'С незапамятных времен...','Убейте Гноша Брогната, вождя огров на заставе Камнерогов.','Вернитесь к Леороксу в деревню Мок\'Натал, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С незапамятных времен...',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гноша Брогната, вождя огров на заставе Камнерогов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Леороксу в деревню Мок\'Натал, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (10844,'Лагерь Легиона: Злоба') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь Легиона: Злоба',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10845,'Убить мать драконов','Мои охотники только что вернулись с разведки на Звенящем гребне. Похоже, драконы Пустоты, что заразили тамошние кристаллы, сильно расплодились и того-гляди нам на голову сядут.$B$BРаз уж ты $Gпоказал:показала; себя опытным бойцом, посмотрим, хватит ли тебе выдержки для драки со взрослым драконом.$B$BИщи Звенящий гребень на юге, за Склоном Чешуекрылых. Пойди и убей их мать-дракониху, Крыло Ужаса.','Убейте Крыло Ужаса.','Ну, побывал на Заставе Камнерогов и отобрал у них тотемы?','Вернитесь к Леороксу в деревню Мок\'Натал, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить мать драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои охотники только что вернулись с разведки на Звенящем гребне. Похоже, драконы Пустоты, что заразили тамошние кристаллы, сильно расплодились и того-гляди нам на голову сядут.$B$BРаз уж ты $Gпоказал:показала; себя опытным бойцом, посмотрим, хватит ли тебе выдержки для драки со взрослым драконом.$B$BИщи Звенящий гребень на юге, за Склоном Чешуекрылых. Пойди и убей их мать-дракониху, Крыло Ужаса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Крыло Ужаса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, побывал на Заставе Камнерогов и отобрал у них тотемы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Леороксу в деревню Мок\'Натал, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10846,'Как понять Мок\'Натал','<Леорокс смотрит вам в глаза так, что у вас мороз идет по коже.>$B$BТы $Gпришел:пришла; к Мок\'Натал, но ты нас не понимаешь. Ты не понимаешь нашей борьбы за выживание.$B$BЕсли ты хочешь понять нас, тебе придется вкусить этой борьбы.$B$BНа юге живут араккоа Векх\'нира. Они поработили группу огров из пещер, известных как Участок Трогмы, и их предводитель Векх там живет.$B$BУбей его!','Убейте Векха, предводителя араккоа Векх\'нира.','У нас много врагов. Некоторые мы выбрали, а некоторые, такие как Век\'нир, нет.$B$BКак бы то ни было, мы убьем всех их вождей.','Вернитесь к Леороксу в деревню Мок\'Натал, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Как понять Мок\'Натал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Леорокс смотрит вам в глаза так, что у вас мороз идет по коже.>$B$BТы $Gпришел:пришла; к Мок\'Натал, но ты нас не понимаешь. Ты не понимаешь нашей борьбы за выживание.$B$BЕсли ты хочешь понять нас, тебе придется вкусить этой борьбы.$B$BНа юге живут араккоа Векх\'нира. Они поработили группу огров из пещер, известных как Участок Трогмы, и их предводитель Векх там живет.$B$BУбей его!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Векха, предводителя араккоа Векх\'нира.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У нас много врагов. Некоторые мы выбрали, а некоторые, такие как Век\'нир, нет.$B$BКак бы то ни было, мы убьем всех их вождей.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Леороксу в деревню Мок\'Натал, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10847,'Глаза Скеттиса','С утесов Скеттиса на нас движется неумолимый рок.$B$BМоему народу, араккоа, уготована невыразимо жестокая участь. Мы долгое время использовали темную магию в дурных целях, но благодаря А\'далу я познал свет и глубоко раскаялся.$B$BТерокк наблюдает за своими поселениями из Скеттиса через сферы, на которые наложены темные чары. Украдите эти Глаза из Гнездовья Рескк и Гнездовья Шиенор – это в северном Тероккаре. Я хочу увидеть то же, что видит Терокк, хочу посмотреть через очи Скеттиса.','Принесите Око Рескка и Око Шиенор Рилаку Освобожденному в Нижний Город Шаттрата.','Вернитесь к Рилаку Освобожденному в Нижний Город Шаттрата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаза Скеттиса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С утесов Скеттиса на нас движется неумолимый рок.$B$BМоему народу, араккоа, уготована невыразимо жестокая участь. Мы долгое время использовали темную магию в дурных целях, но благодаря А\'далу я познал свет и глубоко раскаялся.$B$BТерокк наблюдает за своими поселениями из Скеттиса через сферы, на которые наложены темные чары. Украдите эти Глаза из Гнездовья Рескк и Гнездовья Шиенор – это в северном Тероккаре. Я хочу увидеть то же, что видит Терокк, хочу посмотреть через очи Скеттиса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Око Рескка и Око Шиенор Рилаку Освобожденному в Нижний Город Шаттрата.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рилаку Освобожденному в Нижний Город Шаттрата.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10848,'Гнездовье Рейз: неживое зло','Гнездовье Рейз – это особо неприятное поселение Скеттиса.$B$BНесмотря на то, что эту деревню уничтожила Аукиндонская катастрофа, Терокк все еще держит в своей власти оставшихся там неупокоенных духов. Вам нужно отправиться в Гнездовье Рейз и истребить это гнусное отродье – их можно найти к западу от Гробницы Тени, на границе Костяных пустошей и леса Тероккар.$B$BЭто будет нашим первым ударом по Терокку и стражам Скеттиса.','Эти злобные духи заслужили смерть, ибо они сами были готовы убивать, не задумываясь.$B$BДля тех, кто находится во власти Терокка, спасения нет, но мы по крайней мере можем нанести ему сокрушающий удар во имя Света.','Вернитесь к Киррику Пробужденному к Каравану Беженцев, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнездовье Рейз: неживое зло',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гнездовье Рейз – это особо неприятное поселение Скеттиса.$B$BНесмотря на то, что эту деревню уничтожила Аукиндонская катастрофа, Терокк все еще держит в своей власти оставшихся там неупокоенных духов. Вам нужно отправиться в Гнездовье Рейз и истребить это гнусное отродье – их можно найти к западу от Гробницы Тени, на границе Костяных пустошей и леса Тероккар.$B$BЭто будет нашим первым ударом по Терокку и стражам Скеттиса.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти злобные духи заслужили смерть, ибо они сами были готовы убивать, не задумываясь.$B$BДля тех, кто находится во власти Терокка, спасения нет, но мы по крайней мере можем нанести ему сокрушающий удар во имя Света.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киррику Пробужденному к Каравану Беженцев, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10849,'Поиски Киррика','Еще один араккоа отступился от Терокка!$B$BКиррик признал его шарлатаном, а никаким не пророком. Единственное видение, которое явилось Терокку, говорило лишь о злой участи, уготованной тем, кто призовет его.$B$BКиррик храбро увел нас всех из Скеттиса, а после того, как мы прибыли в Шаттрат, он ушел в другие колонии в поисках новых последователей.$B$BВ этом послании написано о том, что увидели Глаза, и нужно непременно рассказать об этом Киррику! Ступайте из Шаттрата на юг, к Костяным пустошам, и высматривайте караван.','Отнесите послание Риллака Киррику Пробужденному в Караван беженцев на Костяных Пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Киррика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще один араккоа отступился от Терокка!$B$BКиррик признал его шарлатаном, а никаким не пророком. Единственное видение, которое явилось Терокку, говорило лишь о злой участи, уготованной тем, кто призовет его.$B$BКиррик храбро увел нас всех из Скеттиса, а после того, как мы прибыли в Шаттрат, он ушел в другие колонии в поисках новых последователей.$B$BВ этом послании написано о том, что увидели Глаза, и нужно непременно рассказать об этом Киррику! Ступайте из Шаттрата на юг, к Костяным пустошам, и высматривайте караван.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите послание Риллака Киррику Пробужденному в Караван беженцев на Костяных Пустошах.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10850,'Газ хаоса в двигателе','Сквернобот начинает трястись и чихать, по мере того как вы загружаете его неправильным топливом.','Вернитесь к бездействующему скверноботу в Пустоверть.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Газ хаоса в двигателе',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сквернобот начинает трястись и чихать, по мере того как вы загружаете его неправильным топливом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бездействующему скверноботу в Пустоверть.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10851,'Тотем врага моего','Почитать предков можно достойным образом – и недостойным.$B$BОгры клана Камнерогов носят с собой тотемы, но не почитают их. Они пытаются использовать тотемы, управлять с их помощью!$B$BМы должны украсть у них эти тотемы, потому как огры их недостойны! Мы найдем им лучшее применение.$B$BОтправляйся на заставу Камнерогов на запад, что прямо у юго-западной части Островерхого гребня. Убей их мистиков и сокрушителей и забери у них тотемы!','Добудьте 5 тотемов Камнерогов.','Вернитесь к вызывателю духов Догару в деревню Мок\'Натал, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тотем врага моего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Почитать предков можно достойным образом – и недостойным.$B$BОгры клана Камнерогов носят с собой тотемы, но не почитают их. Они пытаются использовать тотемы, управлять с их помощью!$B$BМы должны украсть у них эти тотемы, потому как огры их недостойны! Мы найдем им лучшее применение.$B$BОтправляйся на заставу Камнерогов на запад, что прямо у юго-западной части Островерхого гребня. Убей их мистиков и сокрушителей и забери у них тотемы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 тотемов Камнерогов.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вызывателю духов Догару в деревню Мок\'Натал, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10852,'Пропавшие друзья','Ночью кто-то пришел и очень страшно шумел, мы испугались и бросились врассыпную. Очень страшно было! Даже и не знаю, когда мы поедем дальше.$B$BНекоторые мои друзья до сих пор не вернулись – наверное, эти страшные птицелюди утащили их на северо-запад и заперли в клетках. Было бы здорово, если бы вы нашли их, а то я за них волнуюсь!','Мне скучно, играть не с кем. Ты $Gнашёл:нашла; моих друзей?','Вернитесь к Итану к Каравану Беженцев, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавшие друзья',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ночью кто-то пришел и очень страшно шумел, мы испугались и бросились врассыпную. Очень страшно было! Даже и не знаю, когда мы поедем дальше.$B$BНекоторые мои друзья до сих пор не вернулись – наверное, эти страшные птицелюди утащили их на северо-запад и заперли в клетках. Было бы здорово, если бы вы нашли их, а то я за них волнуюсь!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне скучно, играть не с кем. Ты $Gнашёл:нашла; моих друзей?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Итану к Каравану Беженцев, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10853,'Зов духов','Духи драконов Пустоты Звенящего гребня жаждут освобождения.$B$BЭти драконы Пустоты не всегда были драконами Пустоты. Прежде они были черными драконами.$B$BНо когда этот мир рухнул, по нему прошла всесокрушающая волна энергии Пустоты, и в качестве побочного эффекта изменила драконьи яйца.$B$BТеперь они – лишь искаженные подобия прежних себя. Мы должны помочь им обрести мир.$B$BСделай это, убив дракона близ тотема созывания духов, затем освободи из тотема его дух.','Соберите 8 духов младших драконов Пустоты при помощи тотемов вызова духов.','Ты сегодня сделал доброе дело, |3-6($C). Теперь освобожденные души драконов воистину воспоют. А та остаточная часть души, которую они оставили после себя – могучее лекарство.\n\nХочу спросить – а не собираешься ли ты на север? Там есть кое-что весьма любопытное для меня, связанное с деятельностью духов Астрала.\n\nЯ чувствую, оттуда будет много лиха.','Драконы Звенящего гребня – угроза для нас, но я думаю, что они величественные существа.\n\nИли, по крайней мере. были таковыми. Надеюсь, ты сумеешь спасти их души.\n\nИ если тебе понадобится еще тотемов. У меня найдется несколько штук.','Вернитесь к вызывателю духов Догару в деревню Мок\'Натал, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духи драконов Пустоты Звенящего гребня жаждут освобождения.$B$BЭти драконы Пустоты не всегда были драконами Пустоты. Прежде они были черными драконами.$B$BНо когда этот мир рухнул, по нему прошла всесокрушающая волна энергии Пустоты, и в качестве побочного эффекта изменила драконьи яйца.$B$BТеперь они – лишь искаженные подобия прежних себя. Мы должны помочь им обрести мир.$B$BСделай это, убив дракона близ тотема созывания духов, затем освободи из тотема его дух.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 духов младших драконов Пустоты при помощи тотемов вызова духов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты сегодня сделал доброе дело, |3-6($C). Теперь освобожденные души драконов воистину воспоют. А та остаточная часть души, которую они оставили после себя – могучее лекарство.\n\nХочу спросить – а не собираешься ли ты на север? Там есть кое-что весьма любопытное для меня, связанное с деятельностью духов Астрала.\n\nЯ чувствую, оттуда будет много лиха.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Драконы Звенящего гребня – угроза для нас, но я думаю, что они величественные существа.\n\nИли, по крайней мере. были таковыми. Надеюсь, ты сумеешь спасти их души.\n\nИ если тебе понадобится еще тотемов. У меня найдется несколько штук.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вызывателю духов Догару в деревню Мок\'Натал, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10854,'Силы Нельтараку','Забери зачарованный кристалл Лозы Пустоты и отправляйся обратно в крепость Драконьей Пасти. Найди там порабощенных драконов и активируй кристалл. Моя сила поможет драконам освободиться от удерживающих их чар. Когда ты увидишь, что дракон освободился, помоги ему справиться с надсмотрщиком, поскольку сам он, скорее всего, будет ослаблен пленом.$B$BОсвободи всех, кого сможешь, и возвращайся ко мне, $n.','Освободите для Нельтараку 5 порабощенных драконов Крыльев Пустоты.','Не теряй времени. У нас очень много дел!','Вернитесь к Нельтараку на Поля Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Силы Нельтараку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Забери зачарованный кристалл Лозы Пустоты и отправляйся обратно в крепость Драконьей Пасти. Найди там порабощенных драконов и активируй кристалл. Моя сила поможет драконам освободиться от удерживающих их чар. Когда ты увидишь, что дракон освободился, помоги ему справиться с надсмотрщиком, поскольку сам он, скорее всего, будет ослаблен пленом.$B$BОсвободи всех, кого сможешь, и возвращайся ко мне, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите для Нельтараку 5 порабощенных драконов Крыльев Пустоты.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не теряй времени. У нас очень много дел!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нельтараку на Поля Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10855,'Сквернобот – нет, спасибо!','Ах да, скверноботы! Несомненно, самые ужасные механические создания Легиона. И не меньше трех этих ходячих кошмаров нацелены на Штормовую Вершину. $B$BК счастью для нас, они еще не активны. Это дает нам возможность справиться с ними путем саботажа, а не грубой силы.$B$BВозьми у ган\'арга на кузнечной базе "Забвение" конденсированный газ Пустоты и наполни им топливный бак ближайшего сквернобота. Мне кажется, что его двигатель не очень-то хорошо с этим справится.','Заберите 5 единиц конденсированного газа Пустоты у ган\'аргов-анжинеров на кузнечной базе "Забвение", к северо-западу от Штормовой Вершины, и загрузите их в ближайший бездействующий сквернобот. После завершения задачи возвращайтесь к ловчему Пустоты Наутису.','Вернитесь к ловчему Пустоты Наутису на Штормовую Вершину, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сквернобот – нет, спасибо!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ах да, скверноботы! Несомненно, самые ужасные механические создания Легиона. И не меньше трех этих ходячих кошмаров нацелены на Штормовую Вершину. $B$BК счастью для нас, они еще не активны. Это дает нам возможность справиться с ними путем саботажа, а не грубой силы.$B$BВозьми у ган\'арга на кузнечной базе "Забвение" конденсированный газ Пустоты и наполни им топливный бак ближайшего сквернобота. Мне кажется, что его двигатель не очень-то хорошо с этим справится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите 5 единиц конденсированного газа Пустоты у ган\'аргов-анжинеров на кузнечной базе "Забвение", к северо-западу от Штормовой Вершины, и загрузите их в ближайший бездействующий сквернобот. После завершения задачи возвращайтесь к ловчему Пустоты Наутису.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Пустоты Наутису на Штормовую Вершину, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10856,'Наилучшая защита','Отважные действия по промышленному саботажу больше не дадут нам ничего, $n. Точно так же, как кузнечная база "Забвение" служит местом сборки скверноботов, кузнечная база "Геенна" является полигоном для их армии, где размещена большая часть телепортационных установок Пылающего Легиона. $B$BЯ хочу послать тебя туда, чтобы уменьшить их количество. У них сейчас, должно быть, собрался полный личный состав Носителей Ярости, и мы не можем этого допустить.','Ловчий Пустоты Наутис просит вас убить 12 вестников Зла на кузнечной базе "Геенна" к северу от Штормовой Вершины.','Вернитесь к ловчему Пустоты Наутису на Штормовую Вершину, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наилучшая защита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отважные действия по промышленному саботажу больше не дадут нам ничего, $n. Точно так же, как кузнечная база "Забвение" служит местом сборки скверноботов, кузнечная база "Геенна" является полигоном для их армии, где размещена большая часть телепортационных установок Пылающего Легиона. $B$BЯ хочу послать тебя туда, чтобы уменьшить их количество. У них сейчас, должно быть, собрался полный личный состав Носителей Ярости, и мы не можем этого допустить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ловчий Пустоты Наутис просит вас убить 12 вестников Зла на кузнечной базе "Геенна" к северу от Штормовой Вершины.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Пустоты Наутису на Штормовую Вершину, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10857,'Телепортируй это!','Может быть, убивать демонов и забавно, но толку от этого мало, пока Легион использует свои телепорты, чтобы заменять тех, кого мы убили, новыми. $B$BК несчастью, у меня под рукой нет достаточно мощной взрывчатки... но она есть у мо\'арга, который присматривает за телепортами. $B$BВозьми этот жезл... я настроил его силу так, чтобы она взаимодействовала с частотой, на которой работает мозг мо\'арга. Возвращайся на кузнечную базу "Геенна" и используй жезл на любом мо\'арге, которого встретишь. Действие будет недолгим, но ты сможешь использовать их разрушительные заряды, чтобы уничтожить ближайшие телепорты.','Ловчий Пустоты Наутис просит вас применить жезл Ментального Вмешательства против мо\'аргов, находящихся в Лагере Легиона "Геенна" и использовать их способность взорвать телепорт для того, чтобы уничтожить три телепорта в Лагере Легиона.','Вернитесь к ловчему Пустоты Наутису на Штормовую Вершину, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Телепортируй это!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может быть, убивать демонов и забавно, но толку от этого мало, пока Легион использует свои телепорты, чтобы заменять тех, кого мы убили, новыми. $B$BК несчастью, у меня под рукой нет достаточно мощной взрывчатки... но она есть у мо\'арга, который присматривает за телепортами. $B$BВозьми этот жезл... я настроил его силу так, чтобы она взаимодействовала с частотой, на которой работает мозг мо\'арга. Возвращайся на кузнечную базу "Геенна" и используй жезл на любом мо\'арге, которого встретишь. Действие будет недолгим, но ты сможешь использовать их разрушительные заряды, чтобы уничтожить ближайшие телепорты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ловчий Пустоты Наутис просит вас применить жезл Ментального Вмешательства против мо\'аргов, находящихся в Лагере Легиона "Геенна" и использовать их способность взорвать телепорт для того, чтобы уничтожить три телепорта в Лагере Легиона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Пустоты Наутису на Штормовую Вершину, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10858,'Каринаку','Мне стыдно снова просить тебя о помощи. $n, но ты сейчас – единственная надежда всего выводка. Без моей супруги нам грозит вымиранье как виду.$B$BОтправляйся в крепость Драконьей Пасти и найди Каринаку. Мы будем неподалеку, на случай если тебе понадобится помощь.','Найдите Каринаку в крепости клана Драконьей Пасти.','Это все цепи, они лишают меня сил. Единственный способ освободиться, это отобрать ключ у Зулухеда и отпереть замок.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каринаку',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне стыдно снова просить тебя о помощи. $n, но ты сейчас – единственная надежда всего выводка. Без моей супруги нам грозит вымиранье как виду.$B$BОтправляйся в крепость Драконьей Пасти и найди Каринаку. Мы будем неподалеку, на случай если тебе понадобится помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Каринаку в крепости клана Драконьей Пасти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это все цепи, они лишают меня сил. Единственный способ освободиться, это отобрать ключ у Зулухеда и отпереть замок.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10859,'Собрать шары','У духов астрала Разаани есть странные устройства, которые испускают маленькие розовые светящиеся шарики. Чем-то они напоминают мне души.$B$BНе путай их с большими желтыми шарами, которые вылетают из духов астрала, когда они гибнут, это что-то совсем другое.$B$BЯ хочу, чтобы ты $Gсходил:сходила; на север к лагерю Разаана и $Gразбросал:разбросала; там несколько тотемов, которые притянут к себе розовые светящиеся шарики.$B$BЗатем принеси их мне, чтобы я смог определить. что же это такое на самом деле.','Соберите 15 световых сфер братства Разаани при помощи тотема для собирания сфер.','Удалось собрать необходимое количество световых сфер братства Разаани?','Вернитесь к вызывателю духов Догару в деревню Мок\'Натал, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собрать шары',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У духов астрала Разаани есть странные устройства, которые испускают маленькие розовые светящиеся шарики. Чем-то они напоминают мне души.$B$BНе путай их с большими желтыми шарами, которые вылетают из духов астрала, когда они гибнут, это что-то совсем другое.$B$BЯ хочу, чтобы ты $Gсходил:сходила; на север к лагерю Разаана и $Gразбросал:разбросала; там несколько тотемов, которые притянут к себе розовые светящиеся шарики.$B$BЗатем принеси их мне, чтобы я смог определить. что же это такое на самом деле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 световых сфер братства Разаани при помощи тотема для собирания сфер.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось собрать необходимое количество световых сфер братства Разаани?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вызывателю духов Догару в деревню Мок\'Натал, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10860,'Лакомства Мок\'Натал','Добудьте 3 ребра ящера и 3 куска змеиного мяса.','Вернитесь к Сестре Варе в деревню Мок\'Натал, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лакомства Мок\'Натал',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 3 ребра ящера и 3 куска змеиного мяса.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сестре Варе в деревню Мок\'Натал, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10861,'Гнездовье Литик: превентивный удар','К юго-западу отсюда находится поселение араккоа под названием Гнездовье Литик, где прислужники Терокка накладывают злые чары на своих птенцов еще до того, как они вылупятся из яиц, чтобы сразу после рождения они бездумно повиновались Терокку.$B$BОтправляйтесь в Гнездовье Литик и разбейте птичьи яйца до того, как злые чары полностью поглотят их, а если опоздаете, то просто убейте нечестивых птенцов.$B$BИ помните, что ярче всего Свет сияет во тьме.','Разбейте проклятые яйца в Гнездовье Литик. Освободите 3 птенцов и убейте 3 злобных птенцов, после чего вернитесь к Киррику Пробужденному в Караван беженцев.','Очень неприятно вредить чужим детенышам, однако нельзя пускать такую угрозу на самотек. Вы хорошо поработали. Да пребудет в вашем сердце милость А\'дала.','Вы уничтожили яйца?','Вернитесь к Киррику Пробужденному к Каравану Беженцев, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнездовье Литик: превентивный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К юго-западу отсюда находится поселение араккоа под названием Гнездовье Литик, где прислужники Терокка накладывают злые чары на своих птенцов еще до того, как они вылупятся из яиц, чтобы сразу после рождения они бездумно повиновались Терокку.$B$BОтправляйтесь в Гнездовье Литик и разбейте птичьи яйца до того, как злые чары полностью поглотят их, а если опоздаете, то просто убейте нечестивых птенцов.$B$BИ помните, что ярче всего Свет сияет во тьме.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разбейте проклятые яйца в Гнездовье Литик. Освободите 3 птенцов и убейте 3 злобных птенцов, после чего вернитесь к Киррику Пробужденному в Караван беженцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень неприятно вредить чужим детенышам, однако нельзя пускать такую угрозу на самотек. Вы хорошо поработали. Да пребудет в вашем сердце милость А\'дала.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы уничтожили яйца?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киррику Пробужденному к Каравану Беженцев, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10862,'Сдаться Орде','Эти мерзкие араккоа нападают на нас каждый день! Они устраивают засады на наших охотников, а иногда даже проникают за стены! Мы, конечно, убиваем их при любой возможности, но они владеют очень сильной магией, которая часто помогает им спастись.$B$BМне сказали, что есть араккоа, которые считаются союзниками Орды, и якобы они живут в Шаттрате, к северо-западу отсюда. Их предводителя зовут Рилак Освобожденный, найдите его в Нижнем Городе и убедите капитулировать.','Найдите Рилака Освобожденного в Нижнем Городе Шаттрата и потребуйте, чтобы он и его народ сдались Орде, как велел вам Рокаг.','Ваши люди сердятся, но я мало что могу сделать. Некоторые из нас преклоняются перед силой наару, и благодаря ей мы изменились навеки. Однако те из нас, кто до сих пор живет на воле, остались такими же, как прежде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сдаться Орде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти мерзкие араккоа нападают на нас каждый день! Они устраивают засады на наших охотников, а иногда даже проникают за стены! Мы, конечно, убиваем их при любой возможности, но они владеют очень сильной магией, которая часто помогает им спастись.$B$BМне сказали, что есть араккоа, которые считаются союзниками Орды, и якобы они живут в Шаттрате, к северо-западу отсюда. Их предводителя зовут Рилак Освобожденный, найдите его в Нижнем Городе и убедите капитулировать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Рилака Освобожденного в Нижнем Городе Шаттрата и потребуйте, чтобы он и его народ сдались Орде, как велел вам Рокаг.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ваши люди сердятся, но я мало что могу сделать. Некоторые из нас преклоняются перед силой наару, и благодаря ей мы изменились навеки. Однако те из нас, кто до сих пор живет на воле, остались такими же, как прежде.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10863,'Тайны араккоа','Здесь, на границе, нам каждый день приходится иметь дело с араккоа – они постоянно нападают на нас, грабят караваны с провизией, убивают наших разведчиков...$B$BИ, тем не менее, нам на удивление мало известно об этих загадочных существах. Я слышала, что к северо-западу отсюда, в Шаттрате, есть араккоа, которые не проявляют никакой враждебности. Возможно, они согласятся поделиться с нами секретами своей расы.$B$BИх предводителя зовут Рилак Освобожденный, он живет в северной части Нижнего Города.','Найдите Рилака Освобожденного в Нижнем Городе Шаттрата и попытайтесь выведать у него несколько секретов араккоа по просьбе леди Дены Кеннеди.','Хорошо, что вы нашли меня. Мне многое надо вам показать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны араккоа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь, на границе, нам каждый день приходится иметь дело с араккоа – они постоянно нападают на нас, грабят караваны с провизией, убивают наших разведчиков...$B$BИ, тем не менее, нам на удивление мало известно об этих загадочных существах. Я слышала, что к северо-западу отсюда, в Шаттрате, есть араккоа, которые не проявляют никакой враждебности. Возможно, они согласятся поделиться с нами секретами своей расы.$B$BИх предводителя зовут Рилак Освобожденный, он живет в северной части Нижнего Города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Рилака Освобожденного в Нижнем Городе Шаттрата и попытайтесь выведать у него несколько секретов араккоа по просьбе леди Дены Кеннеди.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что вы нашли меня. Мне многое надо вам показать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10864,'Урожай душ','Убейте 20 орков из клана Изувеченной Длани, затем возвращайтесь к аптекарю Антонивичу в Траллмар.','Кристалл еще не успокоен, $N. Возвращайся ко мне после того, как пожнешь души орков Изувеченной Длани.','Вернитесь к аптекарю Антонивичу в Траллмар, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урожай душ',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 орков из клана Изувеченной Длани, затем возвращайтесь к аптекарю Антонивичу в Траллмар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кристалл еще не успокоен, $N. Возвращайся ко мне после того, как пожнешь души орков Изувеченной Длани.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Антонивичу в Траллмар, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (10865,'Доложить Леороксу!','Быстрее, надо скорее доложить Леороксу о том, что случилось в лагере Разаана!$B$BЭти шарики были сделаны из душ, причем некоторые – из душ Мок\'Натал!','Расскажите Леороксу о том, что затеяли духи астрала Разаани. Его можно найти в деревне Мок\'Натал в Острогорье.','Удалось собрать необходимое количество световых сфер братства Разаани?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доложить Леороксу!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Быстрее, надо скорее доложить Леороксу о том, что случилось в лагере Разаана!$B$BЭти шарики были сделаны из душ, причем некоторые – из душ Мок\'Натал!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расскажите Леороксу о том, что затеяли духи астрала Разаани. Его можно найти в деревне Мок\'Натал в Острогорье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось собрать необходимое количество световых сфер братства Разаани?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10866,'Зулухед Измученный','Убейте Зулухеда Измученного и заберите Ключ Зулухеда. Используйте его на цепях Зулухеда, чтобы освободить Каринаку.','Вернитесь к Каринаку в Крепость Драконьей Пасти, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зулухед Измученный',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зулухеда Измученного и заберите Ключ Зулухеда. Используйте его на цепях Зулухеда, чтобы освободить Каринаку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каринаку в Крепость Драконьей Пасти, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10867,'Ответ будет только один','Добудьте коллекцию душ.','Уже? Души наших предков освобождены от этих злобных духов Астрала?','Вернитесь к вызывателю духов Догару в деревню Мок\'Натал, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ответ будет только один',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте коллекцию душ.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Уже? Души наших предков освобождены от этих злобных духов Астрала?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вызывателю духов Догару в деревню Мок\'Натал, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10868,'Тропа войны араккоа','Убейте 14 шиенорских когантов и 6 шиенорских колдунов, после чего вернитесь к советнице Файле в Форт Камнеломов.','Сколько араккоа убито, $N? Они убегали от вас? Они убегали и прятались, когда вы ворвались в их лагерь?','Вернитесь к советнику Файле в Форт Камнеломов, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тропа войны араккоа',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 14 шиенорских когантов и 6 шиенорских колдунов, после чего вернитесь к советнице Файле в Форт Камнеломов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько араккоа убито, $N? Они убегали от вас? Они убегали и прятались, когда вы ворвались в их лагерь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к советнику Файле в Форт Камнеломов, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10869,'Уменьшить стаю','Араккоа снова напали на нас, на этот раз ночью, и потом скрылись с помощью своей черной магии, прежде чем мы успели собрать все наши силы. Они спасают своих воинов от верной смерти с помощью кругов призыва, но если мы нападем на их дома, им не скрыться. Гнездовье Рескк и Гнездовье Шиенор находятся к северу и северо-западу отсюда.$B$BНайдите эти гнездовья араккоа и убейте столько существ, сколько сможете.','Убейте 14 шиенорских когантов и 6 шиенорских колдунов, после чего вернитесь к лейтенанту Булыжному Молоту в Бастион Аллерии.','Вернитесь к лейтенанту Булыжному Молоту в Бастион Аллерии, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уменьшить стаю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Араккоа снова напали на нас, на этот раз ночью, и потом скрылись с помощью своей черной магии, прежде чем мы успели собрать все наши силы. Они спасают своих воинов от верной смерти с помощью кругов призыва, но если мы нападем на их дома, им не скрыться. Гнездовье Рескк и Гнездовье Шиенор находятся к северу и северо-западу отсюда.$B$BНайдите эти гнездовья араккоа и убейте столько существ, сколько сможете.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 14 шиенорских когантов и 6 шиенорских колдунов, после чего вернитесь к лейтенанту Булыжному Молоту в Бастион Аллерии.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Булыжному Молоту в Бастион Аллерии, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (10870,'Союзник Крыльев Пустоты','Позволь мне вернуть тебя к Морденаю. Я уверен, он не откажется снова тебя повидать','Позвольте Каринаку отнести вас к Морденаю на Поля Крыльев Пустоты.','Каринаку стонет.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союзник Крыльев Пустоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Позволь мне вернуть тебя к Морденаю. Я уверен, он не откажется снова тебя повидать',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Позвольте Каринаку отнести вас к Морденаю на Поля Крыльев Пустоты.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Каринаку стонет.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10871,'Союзник Крыльев Пустоты','Позволь мне вернуть тебя к Морденаю. Я уверен, он не откажется снова тебя повидать','Позвольте Каринаку отнести вас к Морденаю на Поля Крыльев Пустоты.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союзник Крыльев Пустоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Позволь мне вернуть тебя к Морденаю. Я уверен, он не откажется снова тебя повидать',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Позвольте Каринаку отнести вас к Морденаю на Поля Крыльев Пустоты.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10872,'Зулухед Измученный','Убейте Зулухеда Измученного и заберите Ключ Зулухеда. Используйте его на цепях Зулухеда, чтобы освободить Каринаку.','Вернитесь к Каринаку в Крепость Драконьей Пасти, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зулухед Измученный',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Зулухеда Измученного и заберите Ключ Зулухеда. Используйте его на цепях Зулухеда, чтобы освободить Каринаку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каринаку в Крепость Драконьей Пасти, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10873,'Захваченные в ночи','На нашу маленькую заставу постоянно нападают. Вот, например, несколько дней назад напали пауки с Гряды Пустопутов – это на юго-восточном краю Костяных пустошей. Пауки отравили много наших людей, опутали их своими тенетами и уволокли за собой. Несколько воинов похватали оружие и пустились в погоню, не подготовившись как следует...$B$BС тех пор мы их и не видели. Однако мы надеемся, что они все еще живы. Как знать, может, пауки просто держат их в плену? Но людей у нас осталось совсем мало... Быть может, вы поищете наших пропавших воинов?','Пойдите на Гряду Пустопутов и освободите там 6 опутанных воинов Ша\'тар, после чего вернитесь к разведчику Наврину на заставу Ша\'тар.','Вы спасли очень многих, я уж и не думал, что мы когда-нибудь увидим их снова! Мы премного обязаны вам, $n.','Вернитесь к разведчику Наврину в Лагерь Ша\'тар, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захваченные в ночи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На нашу маленькую заставу постоянно нападают. Вот, например, несколько дней назад напали пауки с Гряды Пустопутов – это на юго-восточном краю Костяных пустошей. Пауки отравили много наших людей, опутали их своими тенетами и уволокли за собой. Несколько воинов похватали оружие и пустились в погоню, не подготовившись как следует...$B$BС тех пор мы их и не видели. Однако мы надеемся, что они все еще живы. Как знать, может, пауки просто держат их в плену? Но людей у нас осталось совсем мало... Быть может, вы поищете наших пропавших воинов?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пойдите на Гряду Пустопутов и освободите там 6 опутанных воинов Ша\'тар, после чего вернитесь к разведчику Наврину на заставу Ша\'тар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы спасли очень многих, я уж и не думал, что мы когда-нибудь увидим их снова! Мы премного обязаны вам, $n.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Наврину в Лагерь Ша\'тар, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (10874,'Гнездовье Шалас: сигнальные огни','Обитель Терокка, Скеттис, возвышается над Костяными пустошами на востоке. У основания Скеттиса находится завеса Шалас, самое примечательное поселение Терокка. Именно из укреплений Гнездовья Шалас боевые маги Терокка идут войной против Света.$B$BЗлодеи из Гнездовья Шалас общаются со своим повелителем посредством сложной системы сигнальных огней. Вам, |3-6($r), нужно будет отправиться на восток и погасить эти огни. Как только завеса Шалас погрузится в молчание, мы сможем спланировать падение Скеттиса.$B$BНо не будем забегать вперед.','Вернитесь к Киррику Пробужденному к Каравану Беженцев, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнездовье Шалас: сигнальные огни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Обитель Терокка, Скеттис, возвышается над Костяными пустошами на востоке. У основания Скеттиса находится завеса Шалас, самое примечательное поселение Терокка. Именно из укреплений Гнездовья Шалас боевые маги Терокка идут войной против Света.$B$BЗлодеи из Гнездовья Шалас общаются со своим повелителем посредством сложной системы сигнальных огней. Вам, |3-6($r), нужно будет отправиться на восток и погасить эти огни. Как только завеса Шалас погрузится в молчание, мы сможем спланировать падение Скеттиса.$B$BНо не будем забегать вперед.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Киррику Пробужденному к Каравану Беженцев, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (10875,'Донесение Назгрелу','$n, пока ты $gсовершал:совершала; набег с демоническим кристаллом, я отправил донесение о твоих подвигах в сражениях с орками Скверны. Назгрел, наш великий вождь в Траллмаре, хочет поговорить с тобой. Надеюсь, он приготовил для тебя особое, смертоносное задание...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесение Назгрелу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, пока ты $gсовершал:совершала; набег с демоническим кристаллом, я отправил донесение о твоих подвигах в сражениях с орками Скверны. Назгрел, наш великий вождь в Траллмаре, хочет поговорить с тобой. Надеюсь, он приготовил для тебя особое, смертоносное задание...',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10877,'Реликвия Ужаса','Когда-то давно из Аукиндона вышел караван, задачей которого было забрать Реликвию Ужаса из древних гробниц под некрополем. Им не удалось этого сделать, и причиной тому была сама реликвия – она несет зло и притягивает его, стоит только ее коснуться. Их караван был уничтожен где-то к востоку отсюда.$B$BС помощью этого артефакта можно уничтожить Жутуса Проклятого – существо, летающее над Костяными пустошами. Если желаете, помогите мне, но помните, что вы подвергнете риску себя и свою душу.','Отыщите Реликвию Ужаса к востоку от Брошенного каравана, после чего вернитесь к Оакуну.','Поверить не могу, что вам это удалось. Реликвия Ужаса еще сильнее, чем я думал. Только истинный герой мог выжить в этом путешествии и вернуться назад, неся с собой эту проклятую вещь.','Вы нашли Реликвию Ужаса? Она нам необходима.','Вернитесь к Оакуну в Лагерь Ша\'тар, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Реликвия Ужаса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда-то давно из Аукиндона вышел караван, задачей которого было забрать Реликвию Ужаса из древних гробниц под некрополем. Им не удалось этого сделать, и причиной тому была сама реликвия – она несет зло и притягивает его, стоит только ее коснуться. Их караван был уничтожен где-то к востоку отсюда.$B$BС помощью этого артефакта можно уничтожить Жутуса Проклятого – существо, летающее над Костяными пустошами. Если желаете, помогите мне, но помните, что вы подвергнете риску себя и свою душу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Реликвию Ужаса к востоку от Брошенного каравана, после чего вернитесь к Оакуну.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поверить не могу, что вам это удалось. Реликвия Ужаса еще сильнее, чем я думал. Только истинный герой мог выжить в этом путешествии и вернуться назад, неся с собой эту проклятую вещь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы нашли Реликвию Ужаса? Она нам необходима.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Оакуну в Лагерь Ша\'тар, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10878,'До наступления тьмы','Когда на наш караван напали сектанты Совета Теней, разведчики помчались в Шаттрат за помощью. Стражи думают, что теперь мы в безопасности, однако они недооценивают этих безумцев.$B$BЛично мне бы не хотелось, чтобы какой-нибудь фанатик ночью перерезал мне горло. Прошу, сделайте нам одолжение – разберитесь с ними, пока они не добрались до нас.$B$BСлужители культа расположились к югу отсюда, у северного входа в Аукиндон.','Ты $Gсделал:сделала; то, о чём я тебя просил, $N? Я боюсь за нашу жизнь.','Вернитесь к Мекеде к Каравану Беженцев, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','До наступления тьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда на наш караван напали сектанты Совета Теней, разведчики помчались в Шаттрат за помощью. Стражи думают, что теперь мы в безопасности, однако они недооценивают этих безумцев.$B$BЛично мне бы не хотелось, чтобы какой-нибудь фанатик ночью перерезал мне горло. Прошу, сделайте нам одолжение – разберитесь с ними, пока они не добрались до нас.$B$BСлужители культа расположились к югу отсюда, у северного входа в Аукиндон.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсделал:сделала; то, о чём я тебя просил, $N? Я боюсь за нашу жизнь.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мекеде к Каравану Беженцев, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (10880,'Распоряжения заговорщиков','На этом письме стоит темная печать, и хотя язык кажется знакомым, слова, похоже, зашифрованы.$B$BВозможно, кто-нибудь в Караване беженцев сумеет это расшифровать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Распоряжения заговорщиков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом письме стоит темная печать, и хотя язык кажется знакомым, слова, похоже, зашифрованы.$B$BВозможно, кто-нибудь в Караване беженцев сумеет это расшифровать.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10881,'Гробница Тени','Многие считают, что именно Совет Теней произвел тот взрыв, который разорвал Аукиндон на части. Говорят, они разбудили в его глубинах какое-то древнее зло.$B$BЕсли это так, то нужно обратить это зло против них. Судя по этим бумагам, часть Совета Теней бежит из Аукиндона, а в Гробнице Тени они хранят могущественные артефакты оттуда.$B$BСреди этих артефактов находятся три священные реликвии, принадлежавшие патриархам Арунену, К\'алену и Аталору. Я прошу вас вернуть их.','Войдите в Гробницу Тени, что к западу от Каравана беженцев и найдите там пелерину Арунена, молот К\'алена и свиток Аталора, после чего вернитесь к Мекеде в Караван беженцев.','Вернитесь к Мекеде к Каравану Беженцев, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гробница Тени',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие считают, что именно Совет Теней произвел тот взрыв, который разорвал Аукиндон на части. Говорят, они разбудили в его глубинах какое-то древнее зло.$B$BЕсли это так, то нужно обратить это зло против них. Судя по этим бумагам, часть Совета Теней бежит из Аукиндона, а в Гробнице Тени они хранят могущественные артефакты оттуда.$B$BСреди этих артефактов находятся три священные реликвии, принадлежавшие патриархам Арунену, К\'алену и Аталору. Я прошу вас вернуть их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Войдите в Гробницу Тени, что к западу от Каравана беженцев и найдите там пелерину Арунена, молот К\'алена и свиток Аталора, после чего вернитесь к Мекеде в Караван беженцев.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мекеде к Каравану Беженцев, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10882,'Вестник Рока','<В голосе А’дала слышатся негармоничные ноты.>$B$BПринцу Кель\'тасу следовало тщательнее выбирать тюремщика: все, кто был заперт в Аркатраце, выбираются наружу.$B$BСреди них есть один служитель древних богов – Предвестник Скайрисс, который стремится помочь своему хозяину завоевать все миры.$B$B$n, нельзя дать ему сбежать. Вернитесь в Крепость Бурь, проберитесь в Аркатрац и убейте предвестника Скайрисса, пока не стало слишком поздно!','Отправьтесь в район Аркатрац Крепости Бурь и убейте там предвестника Скайрисса, после чего вернитесь к А\'далу на Террасу Света в Шаттрат.','<Хрустальный мелодичный голос А\'дала звучит спокойнее, чем при ваших прошлых разговорах.>$B$BВы снова проявили недюжинную смелость. Если бы предвестник Скайрисс освободился, то унес бы тысячи жизней, как и другой слуга Древних Богов - Скерам, в вашем мире Азерота.$B$BТо, что я предложу вам взамен, может показаться несравнимой малостью, но помните, что вместе с этим вы получаете вечную благодарность Ша\'тар.','<А\'дал сосредотачивает своё внимание на вас, его взгляд почти невыносим.>$B$B$N, может быть, ты не понимаешь масштабов своей миссии? Некогда терять время зря... собери группу соотечественников и войди в Аркатрац.$B$BПоложи конец Предвестнику Скайриссу.','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вестник Рока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<В голосе А’дала слышатся негармоничные ноты.>$B$BПринцу Кель\'тасу следовало тщательнее выбирать тюремщика: все, кто был заперт в Аркатраце, выбираются наружу.$B$BСреди них есть один служитель древних богов – Предвестник Скайрисс, который стремится помочь своему хозяину завоевать все миры.$B$B$n, нельзя дать ему сбежать. Вернитесь в Крепость Бурь, проберитесь в Аркатрац и убейте предвестника Скайрисса, пока не стало слишком поздно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправьтесь в район Аркатрац Крепости Бурь и убейте там предвестника Скайрисса, после чего вернитесь к А\'далу на Террасу Света в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Хрустальный мелодичный голос А\'дала звучит спокойнее, чем при ваших прошлых разговорах.>$B$BВы снова проявили недюжинную смелость. Если бы предвестник Скайрисс освободился, то унес бы тысячи жизней, как и другой слуга Древних Богов - Скерам, в вашем мире Азерота.$B$BТо, что я предложу вам взамен, может показаться несравнимой малостью, но помните, что вместе с этим вы получаете вечную благодарность Ша\'тар.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<А\'дал сосредотачивает своё внимание на вас, его взгляд почти невыносим.>$B$B$N, может быть, ты не понимаешь масштабов своей миссии? Некогда терять время зря... собери группу соотечественников и войди в Аркатрац.$B$BПоложи конец Предвестнику Скайриссу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (10883,'Ключ Урагана','Поговорите с А\'далом в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ключ Урагана',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с А\'далом в Шаттрате.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10884,'Испытание наару: милосердие','$GМолодец:Умница;, $N. Ты $Gпрошел:прошла; испытание милосердием.','<А\'дал приветствует вас.>','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание наару: милосердие',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N. Ты $Gпрошел:прошла; испытание милосердием.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<А\'дал приветствует вас.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10885,'Испытание наару: сила','Прежде чем наару признают тебя достойным, тебе предстоит пройти четыре испытания.$b$bИспытание силы делится на два этапа. Сначала уничтожь главу Парового подземелья Кривого Клыка, полководца Калитреша, и принеси мне его трезубец. Потом убей пришельца из иных миров, Бормотуна, в Темном лабиринте Аукиндона, и принеси мне его сущность.$b$bЕсли ты справишься с этим заданием, я сочту, что ты $gпрошел:прошла; испытание силой.','А\'дал из Шаттрата просит добыть трезубец Калитреша и сущность Бормотуна.$b$bЭто задание выполняется в режиме героической сложности.','$GМолодец:Умница;, $N. Ты $Gпрошел:прошла; испытание силой.','<А\'дал приветствует вас.>','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание наару: сила',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем наару признают тебя достойным, тебе предстоит пройти четыре испытания.$b$bИспытание силы делится на два этапа. Сначала уничтожь главу Парового подземелья Кривого Клыка, полководца Калитреша, и принеси мне его трезубец. Потом убей пришельца из иных миров, Бормотуна, в Темном лабиринте Аукиндона, и принеси мне его сущность.$b$bЕсли ты справишься с этим заданием, я сочту, что ты $gпрошел:прошла; испытание силой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал из Шаттрата просит добыть трезубец Калитреша и сущность Бормотуна.$b$bЭто задание выполняется в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N. Ты $Gпрошел:прошла; испытание силой.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<А\'дал приветствует вас.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10886,'Испытание наару: упорство','А\'дал из Шаттрата просит спасти Милхауса Манашторма из Аркатраца, что в Крепости Бурь.$b$bЭто задание выполняется в режиме героической сложности.','$GМолодец:Умница;, $N. Ты $Gпрошел:прошла; испытание упорством.','<А\'дал приветствует вас.>','Милхаус Манашторм спасен','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание наару: упорство',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал из Шаттрата просит спасти Милхауса Манашторма из Аркатраца, что в Крепости Бурь.$b$bЭто задание выполняется в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N. Ты $Gпрошел:прошла; испытание упорством.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<А\'дал приветствует вас.>',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Милхаус Манашторм спасен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (10887,'Побег из гробницы','Благодарю за помощь, $n. Я уж было попрощался с жизнью...$B$BДавай выбираться отсюда, пока не прибежали другие служители культа.','Помогите Акуно добраться до Каравана беженцев, после чего поговорите с Мекедой.','Вы спасли Акуно, моего доброго друга, и я бесконечно обязан вам, $n.','Да, $N?','Акуно сопровожден до места назначения') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег из гробницы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодарю за помощь, $n. Я уж было попрощался с жизнью...$B$BДавай выбираться отсюда, пока не прибежали другие служители культа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Акуно добраться до Каравана беженцев, после чего поговорите с Мекедой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы спасли Акуно, моего доброго друга, и я бесконечно обязан вам, $n.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Акуно сопровожден до места назначения',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10888,'Испытание наару: Магтеридон','А\'дал из Шаттрата просит вас убить Магтеридона.','Вы зарекомендовали себя как бойца исключительной силы. Наару предоставляют вам доступ к Крепости Бурь.','<А\'дал приветствует вас.>','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание наару: Магтеридон',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал из Шаттрата просит вас убить Магтеридона.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы зарекомендовали себя как бойца исключительной силы. Наару предоставляют вам доступ к Крепости Бурь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<А\'дал приветствует вас.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к А\'далу в Нижний Город, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10889,'Обратно в Шаттрат','Вы действовали очень храбро, но ответ разъяренного Терокка не заставит себя ждать.$B$BПоспешите в Шаттрат, расскажите обо всем Рилаку!','Доберитесь до Шаттрата и поговорите там с Рилаком Освобожденным в Нижнем Городе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обратно в Шаттрат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы действовали очень храбро, но ответ разъяренного Терокка не заставит себя ждать.$B$BПоспешите в Шаттрат, расскажите обо всем Рилаку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до Шаттрата и поговорите там с Рилаком Освобожденным в Нижнем Городе.',`objectives_loc8`);
