INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10891,'Имперские латы','Есть в Прибамбасске дворф по имени Деротайн Грязеглот, который научит тебя ковать имперские латы. И всего-то надо добраться до пустыни Танарис и найти его там. Ну, как?','Поговорите с Деротайном Грязеглотом в Прибамбасске, что в Танарисе.','Конечно, я научу тебя ковать имперские латы! И обойдется это тебе в толику золота... в форме ториевых слитков!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Имперские латы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть в Прибамбасске дворф по имени Деротайн Грязеглот, который научит тебя ковать имперские латы. И всего-то надо добраться до пустыни Танарис и найти его там. Ну, как?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Деротайном Грязеглотом в Прибамбасске, что в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конечно, я научу тебя ковать имперские латы! И обойдется это тебе в толику золота... в форме ториевых слитков!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10892,'Имперские латы','Есть в Прибамбасске дворф по имени Деротайн Грязеглот, который научит тебя ковать имперские латы. И всего-то надо добраться до пустыни Танарис и найти его там. Ну, как?','Поговорите с Деротайном Грязеглотом в Прибамбасске, что в Танарисе.','Конечно, я научу вас делать имперские латные доспехи! Это может стоить вам немного золота... в виде ториевых слитков!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Имперские латы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть в Прибамбасске дворф по имени Деротайн Грязеглот, который научит тебя ковать имперские латы. И всего-то надо добраться до пустыни Танарис и найти его там. Ну, как?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Деротайном Грязеглотом в Прибамбасске, что в Танарисе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конечно, я научу вас делать имперские латные доспехи! Это может стоить вам немного золота... в виде ториевых слитков!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10893,'За всем стоит Длиннохвостка','Когда служители культа Крыльев Тьмы заполоняют туннель, нам приходится туго. Короче, их больше.$B$BИ хотя нам удается не подпускать их слишком близко к выходу, факт остается фактом – будут сильно напирать, нас опрокинут. $B$BНужно, чтобы кто-то зашел с другого конца туннеля и прикончил их предводительницу, Драаку Длиннохвостку. Хочешь развлечься?','Устраните Драаку Длиннохвостку, предводительницу служителей культа Змея в туннеле Драконьего черепа.','Вернитесь к дозорному Лунному Сумраку в Туннель Драконьего Черепа, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За всем стоит Длиннохвостка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда служители культа Крыльев Тьмы заполоняют туннель, нам приходится туго. Короче, их больше.$B$BИ хотя нам удается не подпускать их слишком близко к выходу, факт остается фактом – будут сильно напирать, нас опрокинут. $B$BНужно, чтобы кто-то зашел с другого конца туннеля и прикончил их предводительницу, Драаку Длиннохвостку. Хочешь развлечься?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Устраните Драаку Длиннохвостку, предводительницу служителей культа Змея в туннеле Драконьего черепа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорному Лунному Сумраку в Туннель Драконьего Черепа, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (10894,'Страж Драконьего черепа','Передайте записку о встрече дозорному Лунному Сумраку у входа в туннель Драконьего черепа в Острогорье.','Чем могу помочь? У тебя новости из Вечной рощи?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страж Драконьего черепа',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Передайте записку о встрече дозорному Лунному Сумраку у входа в туннель Драконьего черепа в Острогорье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем могу помочь? У тебя новости из Вечной рощи?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10895,'Сжечь Зет\'Гор!','Установите дымовые маяки у каждой из башен Зет\'Гора и возвращайтесь к командиру звена Даби\'ри в Лагерь экспедиции.','Вернитесь к командиру звена Даби\'ри в Лагерь экспедиции, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сжечь Зет\'Гор!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите дымовые маяки у каждой из башен Зет\'Гора и возвращайтесь к командиру звена Даби\'ри в Лагерь экспедиции.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру звена Даби\'ри в Лагерь экспедиции, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10896,'Зараженные защитники','Деревья этой земли пожирает сила, вырвавшаяся из Аукиндона. Сами видите, во что превратила землю эта темная магия. Уцелевшие деревья заражены древесными клещами, которые точат их древесину под корой.$B$BБольше всего этих клещей живет в гниющих лесных гневнях и зараженных корнеходах, эти существа – настоящие рассадники паразитов. Их можно найти на краю леса к востоку отсюда: сначала убейте носителей, а потом паразитов, которые населяют их.','Убейте 25 лесных клещей и вернитесь к Лакотаю в Караван беженцев. Клещи живут в телах гниющих лесных гневней и зараженных корнеходов.','Вы уничтожили источник заражений?','Вернитесь к Лакотаю к Каравану Беженцев, что в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зараженные защитники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Деревья этой земли пожирает сила, вырвавшаяся из Аукиндона. Сами видите, во что превратила землю эта темная магия. Уцелевшие деревья заражены древесными клещами, которые точат их древесину под корой.$B$BБольше всего этих клещей живет в гниющих лесных гневнях и зараженных корнеходах, эти существа – настоящие рассадники паразитов. Их можно найти на краю леса к востоку отсюда: сначала убейте носителей, а потом паразитов, которые населяют их.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 25 лесных клещей и вернитесь к Лакотаю в Караван беженцев. Клещи живут в телах гниющих лесных гневней и зараженных корнеходов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы уничтожили источник заражений?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лакотаю к Каравану Беженцев, что в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10897,'Мастер зелий','Как ты знаешь, растения обладают свойствами, которые позволяют алхимикам возвращать другим существам силу и энергию с помощью зелий.$b$bЗнакомство с растениями Запределья позволяет мне учить алхимиков извлекать из растений все, что они могут дать. Если ты хочешь расширить свои познания в области зелий, я готова тебя этому научить, но прежде попрошу об одной услуге.$b$bХодят слухи, что старший ботаник Фрейвин из Крепости Бурь написал подробное руководство по ботанике. Принеси его мне вместе с образцами своей работы, и я поделюсь с тобой теми знаниями, которых ты так алкаешь.','Отправляйтесь в Ботанику в Крепости Бурь и добудьте у верховного ботаника Фрейвина "Полевой справочник ботаника". Принесите Лауранне Тар\'вел справочник, 5 гигантских флаконов с лечебным зельем, 5 гигантских флаконов с зельем маны и 5 больших зелий сна без сновидений.$b$b*ВНИМАНИЕ!* Вы можете избрать только одну алхимическую специальность!','Превосходно! Похоже, вы хотите учиться, так что давайте перейдем к делу. Я научу вас, как максимально использовать растения, которые вы используете в своих алхимических зельях.$B$BВы обнаружите, что травы можно использовать очень долго, если вы знаете, что делаете. Иногда вы сможете сделать два зелья из материалов, которые изначально сочли необходимыми только для одного.','Ты $Gуверен:уверена; в этом, $N? Специализация на зельях помешает тебе заниматься другими специализациями.','Вернитесь к Лауранне Тар\'вел в Кенарийский оплот, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер зелий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как ты знаешь, растения обладают свойствами, которые позволяют алхимикам возвращать другим существам силу и энергию с помощью зелий.$b$bЗнакомство с растениями Запределья позволяет мне учить алхимиков извлекать из растений все, что они могут дать. Если ты хочешь расширить свои познания в области зелий, я готова тебя этому научить, но прежде попрошу об одной услуге.$b$bХодят слухи, что старший ботаник Фрейвин из Крепости Бурь написал подробное руководство по ботанике. Принеси его мне вместе с образцами своей работы, и я поделюсь с тобой теми знаниями, которых ты так алкаешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Ботанику в Крепости Бурь и добудьте у верховного ботаника Фрейвина "Полевой справочник ботаника". Принесите Лауранне Тар\'вел справочник, 5 гигантских флаконов с лечебным зельем, 5 гигантских флаконов с зельем маны и 5 больших зелий сна без сновидений.$b$b*ВНИМАНИЕ!* Вы можете избрать только одну алхимическую специальность!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно! Похоже, вы хотите учиться, так что давайте перейдем к делу. Я научу вас, как максимально использовать растения, которые вы используете в своих алхимических зельях.$B$BВы обнаружите, что травы можно использовать очень долго, если вы знаете, что делаете. Иногда вы сможете сделать два зелья из материалов, которые изначально сочли необходимыми только для одного.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gуверен:уверена; в этом, $N? Специализация на зельях помешает тебе заниматься другими специализациями.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лауранне Тар\'вел в Кенарийский оплот, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10899,'Мастер трансмутации','Любой алхимик скажет тебе, что материя податлива, что любую субстанцию можно трансформировать в другую – но ничто на самом деле не создается и не уничтожается.$B$BИстинный мастер трансмутации может научить, как преодолевать это ограничение – и я могу рассказать тебе, как достигнуть этого мастерства!$B$BБудучи перспективным трансмутатором, ты, несомненно, знаешь об изначальной мощи – сочетании материального представления всех изначальных сил. Предъяви мне доказательство своих трансмутационных способностей, и я поделюсь с тобой моими знаниями.','Заревхи, находящийся на Штормовой Вершине в Пустоверти просит вас принести ему 4 единицы изначальной мощи.$B$B*ВНИМАНИЕ!* Вы можете выбрать только одну алхимическую специализацию.','Отличная работа, $N! Эти трансмутации идеальны во всех отношениях!$B$BТеперь я научу вас, как процесс алхимической трансмутации может вызвать материю из воздуха! Используйте свои знания с умом, мастер трансмутации.$B$BА теперь, если вы меня извините, мне нужно навестить покупателя, интересующегося первобытной мощью.','Вы уверены, что хотите стать мастером трансмутации? Если вы специализируетесь в этой области, вы не сможете специализироваться на зельях или эликсирах.','Вернитесь к Заревхи на Штормовую Вершину, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер трансмутации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Любой алхимик скажет тебе, что материя податлива, что любую субстанцию можно трансформировать в другую – но ничто на самом деле не создается и не уничтожается.$B$BИстинный мастер трансмутации может научить, как преодолевать это ограничение – и я могу рассказать тебе, как достигнуть этого мастерства!$B$BБудучи перспективным трансмутатором, ты, несомненно, знаешь об изначальной мощи – сочетании материального представления всех изначальных сил. Предъяви мне доказательство своих трансмутационных способностей, и я поделюсь с тобой моими знаниями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заревхи, находящийся на Штормовой Вершине в Пустоверти просит вас принести ему 4 единицы изначальной мощи.$B$B*ВНИМАНИЕ!* Вы можете выбрать только одну алхимическую специализацию.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N! Эти трансмутации идеальны во всех отношениях!$B$BТеперь я научу вас, как процесс алхимической трансмутации может вызвать материю из воздуха! Используйте свои знания с умом, мастер трансмутации.$B$BА теперь, если вы меня извините, мне нужно навестить покупателя, интересующегося первобытной мощью.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы уверены, что хотите стать мастером трансмутации? Если вы специализируетесь в этой области, вы не сможете специализироваться на зельях или эликсирах.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Заревхи на Штормовую Вершину, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (10900,'Сожгите, |3-6($R), сожгите все! Они ничего не заслуживают! Вы меня слышите? Ничего! Они должны заплатить за то, что сделали. За то, что они продолжают делать.$B$BЯ бы убил Вайши сам, если бы мог освободиться от этих проклятых повязок.$B$BИли, может быть, вы хотите сделать работу Нептулона? Ее смерть служит нам обоим.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сожгите, |3-6($R), сожгите все! Они ничего не заслуживают! Вы меня слышите? Ничего! Они должны заплатить за то, что сделали. За то, что они продолжают делать.$B$BЯ бы убил Вайши сам, если бы мог освободиться от этих проклятых повязок.$B$BИли, может быть, вы хотите сделать работу Нептулона? Ее смерть служит нам обоим.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10901,'Дубина Кардеша','Для создания оружия мне необходимы печатки стихий. Принеси мне их!$B$BПечатку земли ты найдешь в логове Груула Драконобоя в Острогорье.$B$BПечатка огня – это сердце существа, именуемого Ночной Погибелью. Это легендарное чудовище по слухам обитает в священных залах пророка Медива.$B$BПоторопись!','Принесите печатки земли и огня Скартису Еретику в Узилище (героический уровень сложности) в Резервуар Кривого Клыка.','В конце концов!$B$BЯ не забыл нашего соглашения, смертный. Теперь ты тоже сможешь войти в логово леди Вайш. А теперь оставь меня! У меня много планов.','С исправленной дубиной я вырвусь из своих оков и вернусь в Змеиное святилище, чтобы отомстить Вайш и ее приспешникам!','Вернитесь к Скартису Еретику в Узилище.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дубина Кардеша',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для создания оружия мне необходимы печатки стихий. Принеси мне их!$B$BПечатку земли ты найдешь в логове Груула Драконобоя в Острогорье.$B$BПечатка огня – это сердце существа, именуемого Ночной Погибелью. Это легендарное чудовище по слухам обитает в священных залах пророка Медива.$B$BПоторопись!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите печатки земли и огня Скартису Еретику в Узилище (героический уровень сложности) в Резервуар Кривого Клыка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В конце концов!$B$BЯ не забыл нашего соглашения, смертный. Теперь ты тоже сможешь войти в логово леди Вайш. А теперь оставь меня! У меня много планов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С исправленной дубиной я вырвусь из своих оков и вернусь в Змеиное святилище, чтобы отомстить Вайш и ее приспешникам!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скартису Еретику в Узилище.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10902,'Мастер эликсиров','Я посвятил всю свою жизнь совершенствованию эликсиров, но, несмотря на все мои успехи, так и не сумел приготовить эликсира вечной жизни.$B$BНо, кажется, понял, какого реагента мне не хватает. Говорят, в Азероте есть место под названием Пещеры Времени – туда проникают существа, способные создавать временные разломы.$B$BВ разломах конденсируется энергия и выпадает в форме кристаллов – так называемых "сутей Бесконечности". Принесите мне их, а также не забудьте несколько образцов ваших работ, – и я научу вас всему, что знаю сам.','Отправляйтесь в Черные Топи в Пещерах Времени и добудьте 10 кристаллов сути Бесконечности с повелителей и хранительниц временных разломов. Затем отнесите кристаллы, 5 больших эликсиров защиты, 5 эликсиров власти и 5 больших эликсиров ловкости Лорокиму в Нижний Город Шаттрата.$B$B*ВНИМАНИЕ!* Вы можете специализироваться только на одном виде алхимии.','Вы очень хорошо разбираетесь в эликсирах, если таковые имеются. Из тебя получится хороший ученик.$B$BЭти эссенции дадут мне достаточно материалов, чтобы сформировать мой рецепт. Благодаря этому открытию меня будут знать все алхимики!$B$BТеперь, если вы хотите учиться, я готов учить.','Элексиры? Они у тебя?','Вернитесь к Лорокиму в Шаттрат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер эликсиров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я посвятил всю свою жизнь совершенствованию эликсиров, но, несмотря на все мои успехи, так и не сумел приготовить эликсира вечной жизни.$B$BНо, кажется, понял, какого реагента мне не хватает. Говорят, в Азероте есть место под названием Пещеры Времени – туда проникают существа, способные создавать временные разломы.$B$BВ разломах конденсируется энергия и выпадает в форме кристаллов – так называемых "сутей Бесконечности". Принесите мне их, а также не забудьте несколько образцов ваших работ, – и я научу вас всему, что знаю сам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Черные Топи в Пещерах Времени и добудьте 10 кристаллов сути Бесконечности с повелителей и хранительниц временных разломов. Затем отнесите кристаллы, 5 больших эликсиров защиты, 5 эликсиров власти и 5 больших эликсиров ловкости Лорокиму в Нижний Город Шаттрата.$B$B*ВНИМАНИЕ!* Вы можете специализироваться только на одном виде алхимии.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы очень хорошо разбираетесь в эликсирах, если таковые имеются. Из тебя получится хороший ученик.$B$BЭти эссенции дадут мне достаточно материалов, чтобы сформировать мой рецепт. Благодаря этому открытию меня будут знать все алхимики!$B$BТеперь, если вы хотите учиться, я готов учить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Элексиры? Они у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лорокиму в Шаттрат.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10903,'Возвращение в Оплот Чести','$n, пока ты $gбыл:была; на задании в Зет\'Горе, я получил известия о моем командире, полковнике Джулсе. Во время сражения у Форта Горгаза его поразила демоническая скверна, и сейчас он находится в крайне тяжелом состоянии.$B$BВ боях с орками Скверны тебе нет равных, но силен ли твой дух так же, как твоя плоть?$B$BПожалуйста, вернись в Оплот Чести и поговори с Клату. Ты отыщешь его в таверне Оплота Чести, на верхнем этаже.','Поговорите с ассистентом Клату. Его можно найти в таверне Оплота Чести.','Да, это так. За последние несколько дней состояние полковника Джулса снова ухудшилось. Анахорет Берада день и ночь возносит за него молитвы. Будем надеяться, что полковник все-таки поправится.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Оплот Чести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, пока ты $gбыл:была; на задании в Зет\'Горе, я получил известия о моем командире, полковнике Джулсе. Во время сражения у Форта Горгаза его поразила демоническая скверна, и сейчас он находится в крайне тяжелом состоянии.$B$BВ боях с орками Скверны тебе нет равных, но силен ли твой дух так же, как твоя плоть?$B$BПожалуйста, вернись в Оплот Чести и поговори с Клату. Ты отыщешь его в таверне Оплота Чести, на верхнем этаже.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с ассистентом Клату. Его можно найти в таверне Оплота Чести.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это так. За последние несколько дней состояние полковника Джулса снова ухудшилось. Анахорет Берада день и ночь возносит за него молитвы. Будем надеяться, что полковник все-таки поправится.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10904,'Боеприпасы Скверны','Мы должны отрезать Пылающему Легиону доступ к Вратам Смерти, но сначала тебе придется разрушить два их портала!$B$BПроблема в том, что мы даже поцарапать такие штуки не можем, так что придется тебе использовать против них их собственное оружие.$B$BБойцы, стражи, старшие кузнецы и техники кузницы Смерти могут подносить снаряды для пушек Скверны.$B$BОбычно это на них не влияет, но если ты сумеешь принести мне ядер их пушек, я наполню их неукротимым гневом Природы!','Соберите 5 ядер пушек Скверны.','Воняют хуже, чем я думал!$B$BДавай их мне побыстрее, и я наполню их силой Природы так, что они окажутся смертельными для их мерзостных хозяев и их отвратительных тварей.','Ядра уже у тебя?','Воспользуйтесь сигнальным огнем друидов, чтобы призвать друида Вечной рощи к Вратам Смерти в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Боеприпасы Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны отрезать Пылающему Легиону доступ к Вратам Смерти, но сначала тебе придется разрушить два их портала!$B$BПроблема в том, что мы даже поцарапать такие штуки не можем, так что придется тебе использовать против них их собственное оружие.$B$BБойцы, стражи, старшие кузнецы и техники кузницы Смерти могут подносить снаряды для пушек Скверны.$B$BОбычно это на них не влияет, но если ты сумеешь принести мне ядер их пушек, я наполню их неукротимым гневом Природы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 ядер пушек Скверны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воняют хуже, чем я думал!$B$BДавай их мне побыстрее, и я наполню их силой Природы так, что они окажутся смертельными для их мерзостных хозяев и их отвратительных тварей.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ядра уже у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь сигнальным огнем друидов, чтобы призвать друида Вечной рощи к Вратам Смерти в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10905,'Мастер зелий','Я очень даже неплохой алхимик, но только общего профиля. Если ты хочешь сосредоточиться на одной из областей знаний, придется поискать другого учителя.$b$bЗельями занимается Лауранна Тар\'вел из Кенарийской экспедиции.$b$bОна специализируется на растениях, и научит тебя наилучшим способом использовать сырье. Ее можно найти в Зангартопи. Непременно скажи, что ты от меня.','Поговорите с Лауранной Тар\'вел в Кенарийском оплоте в Зангартопи.$b$B*ВНИМАНИЕ!*Вы можете выбрать лишь одно из направлений алхимии!','Вы хотите, чтобы я помог вам с изучением зелий? Хорошо, $N. Посмотрим, что мы можем сделать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер зелий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я очень даже неплохой алхимик, но только общего профиля. Если ты хочешь сосредоточиться на одной из областей знаний, придется поискать другого учителя.$b$bЗельями занимается Лауранна Тар\'вел из Кенарийской экспедиции.$b$bОна специализируется на растениях, и научит тебя наилучшим способом использовать сырье. Ее можно найти в Зангартопи. Непременно скажи, что ты от меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лауранной Тар\'вел в Кенарийском оплоте в Зангартопи.$b$B*ВНИМАНИЕ!*Вы можете выбрать лишь одно из направлений алхимии!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы хотите, чтобы я помог вам с изучением зелий? Хорошо, $N. Посмотрим, что мы можем сделать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10906,'Мастер эликсиров','Я очень даже неплохой алхимик, но только общего профиля. Если ты хочешь сосредоточиться на одной из областей знаний, придется поискать другого учителя.$b$bЭликсирами занимается араккоа по имени Лороким.$b$bОн превосходно разбирается в эликсирах, хотя и зарывает свой талант в землю, безуспешно пытаясь создать эликсир жизни. Найди его, он будет неплохим учителем.','Поговорите с Лорокимом из Нижнего Города Шаттрата.$b$B*ВНИМАНИЕ!*Вы можете выбрать лишь одно из направлений алхимии!','Вы хотите научиться у меня? Хммм да. Возможно, ты будешь подходящим учеником.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер эликсиров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я очень даже неплохой алхимик, но только общего профиля. Если ты хочешь сосредоточиться на одной из областей знаний, придется поискать другого учителя.$b$bЭликсирами занимается араккоа по имени Лороким.$b$bОн превосходно разбирается в эликсирах, хотя и зарывает свой талант в землю, безуспешно пытаясь создать эликсир жизни. Найди его, он будет неплохим учителем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лорокимом из Нижнего Города Шаттрата.$b$B*ВНИМАНИЕ!*Вы можете выбрать лишь одно из направлений алхимии!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы хотите научиться у меня? Хммм да. Возможно, ты будешь подходящим учеником.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10907,'Мастер трансмутации','Я очень даже неплохой алхимик, но только общего профиля. Если ты хочешь сосредоточиться на одной из областей знаний, придется поискать другого учителя.$b$bЕсли тебя интересует трансмутация, найди духа Астрала по имени Заревхи. Он живет на Штормовой Вершине в Пустоверти.$b$bЧто Заревхи не знает о трансмутации, и знать не надо! Попробуй стать его $gучеником:ученицей;, но берегись – цены духи Астрала заламывают... астрономические!','Поговорите с Заревхи из Штормовой Вершины Пустоверти.$b$B*ВНИМАНИЕ!*Вы можете выбрать лишь одно из направлений алхимии!','Вы хотите, чтобы я помог вам в изучении трансмутаций? Хорошо, $N. Посмотрим, что мы можем сделать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер трансмутации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я очень даже неплохой алхимик, но только общего профиля. Если ты хочешь сосредоточиться на одной из областей знаний, придется поискать другого учителя.$b$bЕсли тебя интересует трансмутация, найди духа Астрала по имени Заревхи. Он живет на Штормовой Вершине в Пустоверти.$b$bЧто Заревхи не знает о трансмутации, и знать не надо! Попробуй стать его $gучеником:ученицей;, но берегись – цены духи Астрала заламывают... астрономические!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Заревхи из Штормовой Вершины Пустоверти.$b$B*ВНИМАНИЕ!*Вы можете выбрать лишь одно из направлений алхимии!',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы хотите, чтобы я помог вам в изучении трансмутаций? Хорошо, $N. Посмотрим, что мы можем сделать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10908,'Поговорите с Рилаком Освобожденным','Вы так удивленно смотрите на меня... Не извиняйтесь, я привык. Мой народ, араккоа, заслуживает того, чтобы его боялись.$B$BЕсли хотите узнать больше, поговорите с Рилаком Освобожденным в Шаттрате. Его можно найти в северной части нижнего города, он живет там с другими изгнанниками из Скеттиса.$B$BИ да, $n, я не прощаюсь!','Поговорите с Рилаком Освобожденным в Нижнем Городе Шаттрата по просьбе Киррика Пробужденного.','Итак, мы встретились, $N. Простите мне мою прямоту, но времени мало, так что сразу к делу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поговорите с Рилаком Освобожденным',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы так удивленно смотрите на меня... Не извиняйтесь, я привык. Мой народ, араккоа, заслуживает того, чтобы его боялись.$B$BЕсли хотите узнать больше, поговорите с Рилаком Освобожденным в Шаттрате. Его можно найти в северной части нижнего города, он живет там с другими изгнанниками из Скеттиса.$B$BИ да, $n, я не прощаюсь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Рилаком Освобожденным в Нижнем Городе Шаттрата по просьбе Киррика Пробужденного.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, мы встретились, $N. Простите мне мою прямоту, но времени мало, так что сразу к делу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10909,'Духи Скверны','Полковник Джулс попал под проклятье в битве за Форт Горгаза, укрепление орков Скверны. Мой учитель Берада день и ночь проводит возле несчастного человека, но ему нужна помощь. Измученный дух полковника ищет покоя, и я боюсь, что единственный способ вернуть ему желанный покой, – это отомстить за него.$B$BОтнеси эту реликвию анахорета на Заставу Горгаза. Положи ее на землю рядом с орками из клана Изувеченной Длани и сразись с ними. Смерть освободит их проклятые души, и ты сможешь их уничтожить, чтобы исцелить дух полковника Джулса.','Задействуйте по просьбе Клату из Оплота Чести реликвию анахорета на Заставе Горгаза, к юго-западу от Оплота Чести, и убивайте берсерков из клана Изувеченной Длани рядом с этой реликвией. После этого уничтожьте 10 освобожденных духов Скверны, чтобы отомстить за полковника Джулса.','Души орков Изувеченной Длани нечисты, и нет надежды на их исцеление, но мое сердце скорбит о том, что мы вынуждены использовать столь кровавый путь, чтобы вернуть покой душе полковника Джулса.','Вернитесь к ассистенту Клату в Оплот Чести, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи Скверны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полковник Джулс попал под проклятье в битве за Форт Горгаза, укрепление орков Скверны. Мой учитель Берада день и ночь проводит возле несчастного человека, но ему нужна помощь. Измученный дух полковника ищет покоя, и я боюсь, что единственный способ вернуть ему желанный покой, – это отомстить за него.$B$BОтнеси эту реликвию анахорета на Заставу Горгаза. Положи ее на землю рядом с орками из клана Изувеченной Длани и сразись с ними. Смерть освободит их проклятые души, и ты сможешь их уничтожить, чтобы исцелить дух полковника Джулса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Задействуйте по просьбе Клату из Оплота Чести реликвию анахорета на Заставе Горгаза, к юго-западу от Оплота Чести, и убивайте берсерков из клана Изувеченной Длани рядом с этой реликвией. После этого уничтожьте 10 освобожденных духов Скверны, чтобы отомстить за полковника Джулса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Души орков Изувеченной Длани нечисты, и нет надежды на их исцеление, но мое сердце скорбит о том, что мы вынуждены использовать столь кровавый путь, чтобы вернуть покой душе полковника Джулса.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ассистенту Клату в Оплот Чести, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10910,'Врата Смерти','Существует еще одна опасность, даже более страшная, чем Пылающий Легион. К югу отсюда находится портал, который называют Врата Смерти. Он открывается в чудовищный мир, в котором Легион выращивает своих ужасных псов.$B$BЧтобы дотуда добраться, выйди из Вечной рощи и иди на восток вверх по склону. Потом по южной дороге, через лощину Клинков, лагерь Разаана, Островерхий гребень и Склон Чешуекрылых. Затем по склону вниз к заставе Векхаара, и попадешь к Вратам Смерти через туннель к югу от Мок\'Натал.$B$BКак только окажешься там, используй этот сигнальный огонь друидов.','Воспользуйтесь сигнальным огнем друидов возле Врат Смерти, чтобы призвать друидов Вечной рощи и поговорить с ними.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Врата Смерти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Существует еще одна опасность, даже более страшная, чем Пылающий Легион. К югу отсюда находится портал, который называют Врата Смерти. Он открывается в чудовищный мир, в котором Легион выращивает своих ужасных псов.$B$BЧтобы дотуда добраться, выйди из Вечной рощи и иди на восток вверх по склону. Потом по южной дороге, через лощину Клинков, лагерь Разаана, Островерхий гребень и Склон Чешуекрылых. Затем по склону вниз к заставе Векхаара, и попадешь к Вратам Смерти через туннель к югу от Мок\'Натал.$B$BКак только окажешься там, используй этот сигнальный огонь друидов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь сигнальным огнем друидов возле Врат Смерти, чтобы призвать друидов Вечной рощи и поговорить с ними.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10911,'Открыть огонь!','Используйте боеприпасы, наполненные силой Природы, для установления контроля над пушками Скверны Врат Смерти. Разрушьте Северный и Южный порталы при помощи пушек.','Твоя доблесть просто поразительна!$B$BПрекрасно. Раз порталы уничтожены, остается сделать только одно дело.','Воспользуйтесь сигнальным огнем друидов, чтобы призвать друида Вечной рощи к Вратам Смерти в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Открыть огонь!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте боеприпасы, наполненные силой Природы, для установления контроля над пушками Скверны Врат Смерти. Разрушьте Северный и Южный порталы при помощи пушек.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя доблесть просто поразительна!$B$BПрекрасно. Раз порталы уничтожены, остается сделать только одно дело.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Воспользуйтесь сигнальным огнем друидов, чтобы призвать друида Вечной рощи к Вратам Смерти в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (10912,'Псарь','Вернитесь к владыке леса Антелариону в Вечную рощу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Псарь',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к владыке леса Антелариону в Вечную рощу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10916,'Откопать благословенные четки','Анахорет Берада собирается проводить обряд по исцелению полковника Джулса от скверны, и для этого ему понадобится помощник. Который обязательно должен надлежащим образом подготовиться...$B$BМне стыдно признаться, но я потерял свои благословенные четки во внутреннем дворе Оплота Чести. Уверен, их утащил Шар-Ик и закопал где-нибудь, но вопрос где? Поговори с хозяйкой этой собаки, прапорщиком Трейси Праудвелл, может быть, она скажет, где Шар-Ик закапывает свои сокровища.','Разыщите дренейские четки и принесите их ассистенту Клату в Оплот Чести.','Вернитесь к ассистенту Клату в Оплот Чести, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Откопать благословенные четки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Анахорет Берада собирается проводить обряд по исцелению полковника Джулса от скверны, и для этого ему понадобится помощник. Который обязательно должен надлежащим образом подготовиться...$B$BМне стыдно признаться, но я потерял свои благословенные четки во внутреннем дворе Оплота Чести. Уверен, их утащил Шар-Ик и закопал где-нибудь, но вопрос где? Поговори с хозяйкой этой собаки, прапорщиком Трейси Праудвелл, может быть, она скажет, где Шар-Ик закапывает свои сокровища.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите дренейские четки и принесите их ассистенту Клату в Оплот Чести.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ассистенту Клату в Оплот Чести, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10917,'Затруднительное положение изгнанника','Я изгнанник, и приговорен к смерти теми, кто остался верен Скеттису. Я не выхожу из города, опасаясь за свою жизнь, но ведь я могу достать своих врагов и отсюда!$B$BУ меня тут есть небольшие сбережения, и я с радостью отдам их вам, если вы убьете тех, кто желает мне смерти. В качестве доказательства принесите мне перья араккоа из разных завес Тероккара.','Принесите 30 перьев араккоа Векаксу в Нижний Город Шаттрата.','Вернитесь к Векаксу в Нижний Город Шаттрата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Затруднительное положение изгнанника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я изгнанник, и приговорен к смерти теми, кто остался верен Скеттису. Я не выхожу из города, опасаясь за свою жизнь, но ведь я могу достать своих врагов и отсюда!$B$BУ меня тут есть небольшие сбережения, и я с радостью отдам их вам, если вы убьете тех, кто желает мне смерти. В качестве доказательства принесите мне перья араккоа из разных завес Тероккара.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 30 перьев араккоа Векаксу в Нижний Город Шаттрата.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Векаксу в Нижний Город Шаттрата.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10918,'Больше перьев','<Векакс издаёт радостный клекот, увидев доказательства смерти своих врагов>$B$BДа, теперь-то Скеттис узнает, что мы, Изгнанники, не будем молча терпеть их притеснения! А вот и обещанная награда. Если принесёте мне ещё перьев, то получите больше.','Псы Скеттиса всё ещё следят за нами, изгнанниками. Стоит нам только сунуться за пределы Шаттрата, как нас убьют на месте.$B$BПринесите мне ещё перьев в доказательство вашей победы над ними.','Вернитесь к Векаксу в Нижний Город Шаттрата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Больше перьев',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Векакс издаёт радостный клекот, увидев доказательства смерти своих врагов>$B$BДа, теперь-то Скеттис узнает, что мы, Изгнанники, не будем молча терпеть их притеснения! А вот и обещанная награда. Если принесёте мне ещё перьев, то получите больше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Псы Скеттиса всё ещё следят за нами, изгнанниками. Стоит нам только сунуться за пределы Шаттрата, как нас убьют на месте.$B$BПринесите мне ещё перьев в доказательство вашей победы над ними.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Векаксу в Нижний Город Шаттрата.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10919,'Собачья радость','<Шар-Ик счастливо гавкает и хватает лакомство. Потом оглядывается по сторонам, размышляя, где бы зарыть новое сокровище…>','Фэй Фэй выжидающе смотрит на тебя...','Вернитесь к Шар-Ику на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собачья радость',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Шар-Ик счастливо гавкает и хватает лакомство. Потом оглядывается по сторонам, размышляя, где бы зарыть новое сокровище…>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Фэй Фэй выжидающе смотрит на тебя...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Шар-Ику на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10920,'За павших','Когда на нашу заставу напали паучихи, мы услышали глас наару, призывающий нас к битве, и последовали за этими тварями во тьму. Некоторых из наших людей мы нашли мертвыми, но кто-то еще боролся с похитителями.$B$BК утру мы пришли в это место и дрались не на жизнь, а насмерть, однако все не выстояли. Паучий яд скоро убьет моих товарищей, да и мне долго не продержаться. Но до того, как я умру, я хотел бы увидеть, как этим мерзким жуткопалым черным вдовам придет конец.','Убейте 20 жуткопалых черных вдов и вернитесь к воздаятелю Хайлену на западную сторону Гряды Пустопутов.','Я чувствую, как яд течет по моим венам. Наару зовут меня, я вижу свет. Вдовы ужасных клыков побеждены?','Вернитесь к воздаятелю Хайлену на границу Гряды Пустопутов в Костяных пустошах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','За павших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда на нашу заставу напали паучихи, мы услышали глас наару, призывающий нас к битве, и последовали за этими тварями во тьму. Некоторых из наших людей мы нашли мертвыми, но кто-то еще боролся с похитителями.$B$BК утру мы пришли в это место и дрались не на жизнь, а насмерть, однако все не выстояли. Паучий яд скоро убьет моих товарищей, да и мне долго не продержаться. Но до того, как я умру, я хотел бы увидеть, как этим мерзким жуткопалым черным вдовам придет конец.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 жуткопалых черных вдов и вернитесь к воздаятелю Хайлену на западную сторону Гряды Пустопутов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую, как яд течет по моим венам. Наару зовут меня, я вижу свет. Вдовы ужасных клыков побеждены?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Хайлену на границу Гряды Пустопутов в Костяных пустошах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10924,'Кровная м... есть!','Кровь прыгуан-ловцов, обитающих в этом районе – это очень сильный и редкий реактив. Торговля им идет весьма успешно.$B$BОбычно я посылаю за ней Зеппита, моего беса. Кровь прыгуана-ловца слишком едкая, чтобы ты или я могли без опаски обращаться с ней, но Зеппита это не волнует.$B$BУ меня тут много дел в лавке, так что, если я пошлю с тобой Зеппита, ты не поможешь в сборе крови? Зеппиту трудно на чем-то сосредоточиться надолго, так что тебе нужно быть поблизости от бегуна в момент его смерти, чтобы заставить Зеппита выполнить работу.','Принесите 8 фиалов крови прыгуаны-ловца Саб\'аофу, находящемуся в Космовороте.','Удалось ли собрать нужное мне количество крови? Как вел себя Зеппит?','Вернитесь к Саб-аофу в Космоворот, что в Пустоверти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровная м... есть!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кровь прыгуан-ловцов, обитающих в этом районе – это очень сильный и редкий реактив. Торговля им идет весьма успешно.$B$BОбычно я посылаю за ней Зеппита, моего беса. Кровь прыгуана-ловца слишком едкая, чтобы ты или я могли без опаски обращаться с ней, но Зеппита это не волнует.$B$BУ меня тут много дел в лавке, так что, если я пошлю с тобой Зеппита, ты не поможешь в сборе крови? Зеппиту трудно на чем-то сосредоточиться надолго, так что тебе нужно быть поблизости от бегуна в момент его смерти, чтобы заставить Зеппита выполнить работу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 фиалов крови прыгуаны-ловца Саб\'аофу, находящемуся в Космовороте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли собрать нужное мне количество крови? Как вел себя Зеппит?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Саб-аофу в Космоворот, что в Пустоверти.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10926,'Обратно в лагерь Ша\'тар','Мы не сможем вернуться сами – паучий яд слишком силен. Вернитесь в лагерь Ша\'тар и скажите разведчику Наврину, чтобы он выслал за нами подмогу.','Вернитесь в лагерь Ша\'тар и поговорите с разведчиком Наврином в Костяных пустошах по просьбе воздаятеля Хайлена.','Я очень рад слышать, что наши воины храбро сражались с пауками. За ними сейчас же отправится группа спасателей.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обратно в лагерь Ша\'тар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не сможем вернуться сами – паучий яд слишком силен. Вернитесь в лагерь Ша\'тар и скажите разведчику Наврину, чтобы он выслал за нами подмогу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь в лагерь Ша\'тар и поговорите с разведчиком Наврином в Костяных пустошах по просьбе воздаятеля Хайлена.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я очень рад слышать, что наши воины храбро сражались с пауками. За ними сейчас же отправится группа спасателей.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10927,'Убийство пауков','Командир Тень Небес хочет, чтобы этот туннель был очищен от всякой пакости, и чтобы мы могли вести торговлю с Убежищем. Я не могу оставить пост, потому поручаю эту задачу вам. Проведите в туннеле зачистку и отчитайтесь командиру Тень Небес немедленно!','Убейте 6 пещерных пауков.','Поговорите с командиром Тенью Небес в Сильванааре, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убийство пауков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Командир Тень Небес хочет, чтобы этот туннель был очищен от всякой пакости, и чтобы мы могли вести торговлю с Убежищем. Я не могу оставить пост, потому поручаю эту задачу вам. Проведите в туннеле зачистку и отчитайтесь командиру Тень Небес немедленно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 пещерных пауков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с командиром Тенью Небес в Сильванааре, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10928,'Убийство пауков','Тор\'чанк Двукоготь хочет, чтобы этот туннель был очищен от всякой пакости, и чтобы мы могли вести торговлю с Болотной крысой. Я не могу оставить пост, потому поручаю эту задачу тебе. Проведи в туннеле зачистку и отчитайся Тор\'чанку Двукогтю немедленно!','Убейте 6 пещерных пауков.','Хорошая работа, $C. Этот туннель – наша дорога жизни до болот.','Я сказал Грунту Гракху отдавать прямые приказы. Вы ему не подчиняетесь?','Поговорите с Тор\'чанком Двукогтем в Оплоте Громоборцев, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убийство пауков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тор\'чанк Двукоготь хочет, чтобы этот туннель был очищен от всякой пакости, и чтобы мы могли вести торговлю с Болотной крысой. Я не могу оставить пост, потому поручаю эту задачу тебе. Проведи в туннеле зачистку и отчитайся Тор\'чанку Двукогтю немедленно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 6 пещерных пауков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $C. Этот туннель – наша дорога жизни до болот.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я сказал Грунту Гракху отдавать прямые приказы. Вы ему не подчиняетесь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Тор\'чанком Двукогтем в Оплоте Громоборцев, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10931,'Возвращение в Экзодар','Тебя желает видеть твой учитель из Экзодара, Кадмос. Речь пойдет о твоем обучении, но о чем именно, я не знаю.','Поговорите с Кадмосом из Экзодара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Экзодар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя желает видеть твой учитель из Экзодара, Кадмос. Речь пойдет о твоем обучении, но о чем именно, я не знаю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кадмосом из Экзодара.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10932,'Возвращение в Экзодар','Тебя желает видеть твой учитель из Экзодара, Кадмос. Речь пойдет о твоем обучении, но о чем именно, я не знаю.','Поговорите с Кадмосом из Экзодара.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Экзодар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя желает видеть твой учитель из Экзодара, Кадмос. Речь пойдет о твоем обучении, но о чем именно, я не знаю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Кадмосом из Экзодара.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10933,'Возвращение в Луносвет','Тебя желает видеть твой учитель из Луносвета, Альдрэ. Речь пойдет о твоем обучении, но о чем именно, я не знаю.','Поговорите с Альдрэ из Луносвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Луносвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя желает видеть твой учитель из Луносвета, Альдрэ. Речь пойдет о твоем обучении, но о чем именно, я не знаю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Альдрэ из Луносвета.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (10934,'Возвращение в Луносвет','Тебя желает видеть твой учитель из Луносвета, Альдрэ. Речь пойдет о твоем обучении, но о чем именно, я не знаю.','Поговорите с Альдрэ из Луносвета.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Луносвет',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя желает видеть твой учитель из Луносвета, Альдрэ. Речь пойдет о твоем обучении, но о чем именно, я не знаю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Альдрэ из Луносвета.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (10935,'Экзорцизм над полковником Джулсом','$n, нам нужно спасти полковника Джулса. Его состояние все ухудшается. Берада боится, что если его не избавить от скверны, то мы навсегда его потеряем.$B$BВозьми эти благословленные четки и скажи анахорету Бераде, чтобы он начинал ритуал. Помни, что экзорцизм нельзя прерывать ни на минуту! Это очень важно! Если ритуал пройдет благополучно, полковник Джулс будет спасен. После окончания ритуала поговори с полковником и возвращайся ко мне.','Поговорите с анахоретом Берада. Используйте благословенные четки, чтобы провести ритуал. После окончания ритуала поговорите со спасенным полковником Джулсом. Возвращайтесь к ассистенту Клату.','Вернитесь к ассистенту Клату в Оплот Чести, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Экзорцизм над полковником Джулсом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, нам нужно спасти полковника Джулса. Его состояние все ухудшается. Берада боится, что если его не избавить от скверны, то мы навсегда его потеряем.$B$BВозьми эти благословленные четки и скажи анахорету Бераде, чтобы он начинал ритуал. Помни, что экзорцизм нельзя прерывать ни на минуту! Это очень важно! Если ритуал пройдет благополучно, полковник Джулс будет спасен. После окончания ритуала поговори с полковником и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с анахоретом Берада. Используйте благословенные четки, чтобы провести ритуал. После окончания ритуала поговорите со спасенным полковником Джулсом. Возвращайтесь к ассистенту Клату.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ассистенту Клату в Оплот Чести, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (10936,'Тебя ищет Троллебой','Мы были заняты, и я попросил посланника подождать в зале. Похоже, это ему надоело, или он сбежал, увидев, как Джулс парит в воздухе.$B$BЯ к тому, что тебя ищет командир армии Данат. Рекомендую поскорее отправиться в казармы и отыскать его.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тебя ищет Троллебой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы были заняты, и я попросил посланника подождать в зале. Похоже, это ему надоело, или он сбежал, увидев, как Джулс парит в воздухе.$B$BЯ к тому, что тебя ищет командир армии Данат. Рекомендую поскорее отправиться в казармы и отыскать его.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10942,'Детская неделя','Одна маленькая девочка будет очень рада, если вы побудете ее опекуном, пусть и недолго.$B$BВот, возьмите свисток – с его помощью вы всегда сможете позвать свою воспитанницу. Свисток будет действовать только в течение Детской недели.$B$BПопробуйте позвать сиротку, $n! Она будет очень рада с вами познакомиться и выйти за пределы города.','Дуньте в эльфийскую детскую свистульку. Присматривайте за сиротой в течение всей Детской недели.','А, так это вы мой опекун? Меня зовут Саландрия, я живу здесь с самого детства. Родители у меня погибли на войне, потому меня и отдали в приют.$B$BТут вообще-то неплохо, но хочется и мир посмотреть, – я ведь даже из города никогда не выходила. Вот, я написала список мест, которые хочу увидеть, и дел, которые хочу сделать.$B$BТак что можем отправляться когда угодно!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Детская неделя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна маленькая девочка будет очень рада, если вы побудете ее опекуном, пусть и недолго.$B$BВот, возьмите свисток – с его помощью вы всегда сможете позвать свою воспитанницу. Свисток будет действовать только в течение Детской недели.$B$BПопробуйте позвать сиротку, $n! Она будет очень рада с вами познакомиться и выйти за пределы города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дуньте в эльфийскую детскую свистульку. Присматривайте за сиротой в течение всей Детской недели.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, так это вы мой опекун? Меня зовут Саландрия, я живу здесь с самого детства. Родители у меня погибли на войне, потому меня и отдали в приют.$B$BТут вообще-то неплохо, но хочется и мир посмотреть, – я ведь даже из города никогда не выходила. Вот, я написала список мест, которые хочу увидеть, и дел, которые хочу сделать.$B$BТак что можем отправляться когда угодно!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10943,'Детская неделя','Одна маленькая девочка будет очень рада, если вы побудете ее опекуном, пусть и недолго.$B$BВот, возьмите свисток – с его помощью вы всегда сможете позвать свою воспитанницу. Свисток будет действовать только в течение Детской недели.$B$BПопробуйте позвать сиротку, $n! Она будет очень рада с вами познакомиться и выйти за пределы города.','Продудите в дренейскую детскую свистульку. Присматривайте за сиротой в течение всей Детской недели.','Наверное, ты $Gтот:та;, кто будет $Gмоим:моей; $Gстаршим:старшей; $Gбратом:сестрой; на Детской неделе! Меня зовут Дорнаа, рада познакомиться.$B$B<Девочка на минуту грустнеет.>$B$BМоих маму и папу убили на войне, и я почти всю жизнь провела в приюте. Здесь неплохо, но мне всегда хотелось увидеть и другие места.$B$BЯ написала список мест, которые хочу посмотреть, это ничего? Надеюсь, тебя это не слишком затруднит...$B$BМожем отправляться в любое время.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Детская неделя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Одна маленькая девочка будет очень рада, если вы побудете ее опекуном, пусть и недолго.$B$BВот, возьмите свисток – с его помощью вы всегда сможете позвать свою воспитанницу. Свисток будет действовать только в течение Детской недели.$B$BПопробуйте позвать сиротку, $n! Она будет очень рада с вами познакомиться и выйти за пределы города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Продудите в дренейскую детскую свистульку. Присматривайте за сиротой в течение всей Детской недели.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наверное, ты $Gтот:та;, кто будет $Gмоим:моей; $Gстаршим:старшей; $Gбратом:сестрой; на Детской неделе! Меня зовут Дорнаа, рада познакомиться.$B$B<Девочка на минуту грустнеет.>$B$BМоих маму и папу убили на войне, и я почти всю жизнь провела в приюте. Здесь неплохо, но мне всегда хотелось увидеть и другие места.$B$BЯ написала список мест, которые хочу посмотреть, это ничего? Надеюсь, тебя это не слишком затруднит...$B$BМожем отправляться в любое время.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10944,'Тайна под угрозой','Благодарю тебя, $n. Мне известно твое имя. Акама посвятил тебя в свои планы, и я также поверю тебе свои.$B$BНагам стало известно о том, что я в тайне веду деятельность против Иллидана, и они попытались под пытками вытянуть из меня правду. Я не сказал ни слова – Акама научил меня превозмогать боль с помощью медитации.$B$BИллидан велел нагам привести меня к нему. Он прочел мои мысли, и я ничем не мог помешать ему.$B$BТы $gдолжен:должна; предупредить Акаму. Наши замыслы под угрозой!','Отправляйтесь в Клеть Стражницы в Долину Призрачной Луны и поговорите с Акамой.','Благодарю тебя, $N. Олум – один из самых близких моих друзей и самых преданных соратников. Он внес неоценимый вклад в осуществление наших замыслов.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайна под угрозой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Благодарю тебя, $n. Мне известно твое имя. Акама посвятил тебя в свои планы, и я также поверю тебе свои.$B$BНагам стало известно о том, что я в тайне веду деятельность против Иллидана, и они попытались под пытками вытянуть из меня правду. Я не сказал ни слова – Акама научил меня превозмогать боль с помощью медитации.$B$BИллидан велел нагам привести меня к нему. Он прочел мои мысли, и я ничем не мог помешать ему.$B$BТы $gдолжен:должна; предупредить Акаму. Наши замыслы под угрозой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Клеть Стражницы в Долину Призрачной Луны и поговорите с Акамой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, $N. Олум – один из самых близких моих друзей и самых преданных соратников. Он внес неоценимый вклад в осуществление наших замыслов.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10945,'Хч\'уу и народ грибов','У меня была подруга по имени Хч\'уу. Она сказала мне, что очутилась в приюте, потому что заблудилась, убегая от злобного грибного великана.$b$bМы с ней очень подружились, но в прошлом году приехали ее сородичи и забрали ее. Кажется, она сказала, что едет в Спореггар.$b$bЯ бы хотела увидеть ее и посмотреть на ее грибную деревню. Попечительница сирот говорит, что это где-то на западной стороне Зангартопи, между озерами Спороветра и Болотных Огоньков.$b$bМожно мы туда пойдем? Можно? Пожалуйста!','Отведите вашу подопечную Саландрию, в Спореггар в Зангартопь. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с Хч\'уу.','Спасибо, что $Gустроил:устроила; мне встречу с Саландрией. Я очень скучала по ней целый год, но мы по-прежнему друзья.$B$BМы решили, что когда вырастем, то станем отважными искателями приключений вроде тебя!','Сводить Саландрию в Спореггар.','Вернитесь к Хч\'уу в Зангартопь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хч\'уу и народ грибов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня была подруга по имени Хч\'уу. Она сказала мне, что очутилась в приюте, потому что заблудилась, убегая от злобного грибного великана.$b$bМы с ней очень подружились, но в прошлом году приехали ее сородичи и забрали ее. Кажется, она сказала, что едет в Спореггар.$b$bЯ бы хотела увидеть ее и посмотреть на ее грибную деревню. Попечительница сирот говорит, что это где-то на западной стороне Зангартопи, между озерами Спороветра и Болотных Огоньков.$b$bМожно мы туда пойдем? Можно? Пожалуйста!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите вашу подопечную Саландрию, в Спореггар в Зангартопь. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с Хч\'уу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, что $Gустроил:устроила; мне встречу с Саландрией. Я очень скучала по ней целый год, но мы по-прежнему друзья.$B$BМы решили, что когда вырастем, то станем отважными искателями приключений вроде тебя!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сводить Саландрию в Спореггар.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хч\'уу в Зангартопь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (10946,'Коварство Пеплоустов','Жертва Олума велика. Я никогда не потребовал, чтобы он расстался с жизнью ради нашего дела. Но теперь ничего не изменишь.$B$BЧтобы поддержать в душе Иллидана иллюзию безопасности, нужно какое-то время покорно исполнять все его повеления.$B$BПод моим командованием огромная армия, но доверять я могу лишь Пеплоустам.$B$BТебе придется исполнить все, что прикажет Иллидан. Возьми этот клобук. Он зачарован: чей бы взгляд не упал на тебя, всем будет казаться, что перед ними один из моих солдат. В этом обличье тебе придется убить феникса Келя, Ал\'ара.','$GМолодец:Умница;, $N. Возможно, тебе удалось на время отвлечь внимание Иллидана от нас и от...$B$B<Акама оглядывается на Майев Песнь Теней>$B$BОднако впереди еще много работы.','Ты $Gрасправился:расправилась; с фениксом, $N? Иллидан не привык ждать!','Коварство Пеплоустов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коварство Пеплоустов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Жертва Олума велика. Я никогда не потребовал, чтобы он расстался с жизнью ради нашего дела. Но теперь ничего не изменишь.$B$BЧтобы поддержать в душе Иллидана иллюзию безопасности, нужно какое-то время покорно исполнять все его повеления.$B$BПод моим командованием огромная армия, но доверять я могу лишь Пеплоустам.$B$BТебе придется исполнить все, что прикажет Иллидан. Возьми этот клобук. Он зачарован: чей бы взгляд не упал на тебя, всем будет казаться, что перед ними один из моих солдат. В этом обличье тебе придется убить феникса Келя, Ал\'ара.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N. Возможно, тебе удалось на время отвлечь внимание Иллидана от нас и от...$B$B<Акама оглядывается на Майев Песнь Теней>$B$BОднако впереди еще много работы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gрасправился:расправилась; с фениксом, $N? Иллидан не привык ждать!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Коварство Пеплоустов',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10947,'Артефакт из прошлого','Теперь внимание Иллидана сосредоточено на Кель\'тасе. Время действовать!$B$BМне было видение – артефакт, который сможет помочь нам в борьбе. Это амулет лича, именуемого Лютым Хладом. Однако амулет утратил свою силу после того, как его хозяин потерпел поражение в битве за гору Хиджал.$B$BНо я уверен, что есть способ вернуть артефакту его силу. Есть легенда о неком месте в Азероте, охраняемом бронзовыми драконами... месте, где встречается прошлое и будущее. Там ты найдешь то, что нам нужно.','Мое зрение... Я чувствую мощь чар амулета, чувствую, как мне открывается незримое... Я использую эту силу, чтобы вернуть то, что принадлежит мне по праву. Пришло время сразиться с Иллиданом!','Тебе удалось вернуть силу амулету, $N?','Вернитесь к Акаме в Клеть Стражницы, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Артефакт из прошлого',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь внимание Иллидана сосредоточено на Кель\'тасе. Время действовать!$B$BМне было видение – артефакт, который сможет помочь нам в борьбе. Это амулет лича, именуемого Лютым Хладом. Однако амулет утратил свою силу после того, как его хозяин потерпел поражение в битве за гору Хиджал.$B$BНо я уверен, что есть способ вернуть артефакту его силу. Есть легенда о неком месте в Азероте, охраняемом бронзовыми драконами... месте, где встречается прошлое и будущее. Там ты найдешь то, что нам нужно.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мое зрение... Я чувствую мощь чар амулета, чувствую, как мне открывается незримое... Я использую эту силу, чтобы вернуть то, что принадлежит мне по праву. Пришло время сразиться с Иллиданом!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось вернуть силу амулету, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Акаме в Клеть Стражницы, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10948,'Пленная душа','Тебя, вероятно, удивляет то, что я так долго скрывал свои намерения. Наверное, ты недоумеваешь, почему я не вступил в союз с наару в открытую?$B$BБеда в том, что душа моя заключена в Черном храме, и пока она там, Иллидан может уничтожить меня в любой момент. Но теперь все будет иначе! С помощью этого амулета я верну себе свою душу! $B$BВремя пришло, $n. Я поведу Майев и моих Служителей Смерти к порогу Иллидана.$B$BОтправляйся к А\'далу и расскажи ему о нашем плане. Если мы нанесем удар одновременно, мы сокрушим оборону Иллидана.','Отправляйтесь в Шаттрат и расскажите А\'далу о просьбе Акамы.','<Вас окутывает сияние, исходящее от А\'дала – наару приветствует вас. Вам кажется, он уже прочел в вашем сознании то, что вы должны были ему рассказать.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пленная душа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тебя, вероятно, удивляет то, что я так долго скрывал свои намерения. Наверное, ты недоумеваешь, почему я не вступил в союз с наару в открытую?$B$BБеда в том, что душа моя заключена в Черном храме, и пока она там, Иллидан может уничтожить меня в любой момент. Но теперь все будет иначе! С помощью этого амулета я верну себе свою душу! $B$BВремя пришло, $n. Я поведу Майев и моих Служителей Смерти к порогу Иллидана.$B$BОтправляйся к А\'далу и расскажи ему о нашем плане. Если мы нанесем удар одновременно, мы сокрушим оборону Иллидана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Шаттрат и расскажите А\'далу о просьбе Акамы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вас окутывает сияние, исходящее от А\'дала – наару приветствует вас. Вам кажется, он уже прочел в вашем сознании то, что вы должны были ему рассказать.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10949,'Вход в Черный храм','<А\'дал показывает вам наару, сражающегося вместе с дренеями-воздаятелями и магистрами эльфов крови у Черного храма. Вы понимаете, что это и есть тот самый момент, которого ждал Акама.>','Отправляйтесь ко входу в Черный храм в Долине Призрачной Луны и поговорите с Кси\'ри.','<Кажется, Кси\'ри чувствует ваше присутствие. Однако он сосредоточен на битве.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вход в Черный храм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<А\'дал показывает вам наару, сражающегося вместе с дренеями-воздаятелями и магистрами эльфов крови у Черного храма. Вы понимаете, что это и есть тот самый момент, которого ждал Акама.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь ко входу в Черный храм в Долине Призрачной Луны и поговорите с Кси\'ри.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Кажется, Кси\'ри чувствует ваше присутствие. Однако он сосредоточен на битве.>',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10950,'Аукиндон и Ритуальный Круг','Один из приходивших к нам жрецов рассказал об одном месте неподалеку отсюда. Оно называется Аукиндон, и, кажется, является очень важным для дренеев.$b$bОн сказал, что раньше туда относили тела умерших дренеев. Но некоторое время назад случилось что-то плохое, и все взорвалось.$b$bЯ бы хотела взглянуть на этот Ритуальный Круг. Попечительница сирот говорила, что он находится в центре Костяных пустошей, на юге от леса Тероккар.$b$bПожалуйста, $n, пойдем туда!','Отведите свою подопечную, сиротку Дорнаа, к камню встречи у Ритуального Круга в центра Аукиндона. Аукиндон находится в центре Костяных пустошей, что в лесу Тероккар. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом.','Ох, до чего здорово! Здесь все такое древнее... И действительно кто-то тут все взорвал. Только посмотри на это!$B$BОоо, а ты уже $Gвидел:видела; здешнее небо?','Сводить Дорнаа к Ритуальному Кругу','Подуйте в детскую свистульку и позовите свою дренейскую сироту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Аукиндон и Ритуальный Круг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из приходивших к нам жрецов рассказал об одном месте неподалеку отсюда. Оно называется Аукиндон, и, кажется, является очень важным для дренеев.$b$bОн сказал, что раньше туда относили тела умерших дренеев. Но некоторое время назад случилось что-то плохое, и все взорвалось.$b$bЯ бы хотела взглянуть на этот Ритуальный Круг. Попечительница сирот говорила, что он находится в центре Костяных пустошей, на юге от леса Тероккар.$b$bПожалуйста, $n, пойдем туда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите свою подопечную, сиротку Дорнаа, к камню встречи у Ритуального Круга в центра Аукиндона. Аукиндон находится в центре Костяных пустошей, что в лесу Тероккар. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ох, до чего здорово! Здесь все такое древнее... И действительно кто-то тут все взорвал. Только посмотри на это!$B$BОоо, а ты уже $Gвидел:видела; здешнее небо?',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сводить Дорнаа к Ритуальному Кругу',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Подуйте в детскую свистульку и позовите свою дренейскую сироту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10951,'Путешествие к Темному порталу','Это место гораздо интереснее, чем о нем рассказывают. Потрясающе!$B$BНеужели его правда создал могучий волшебник Медив?$B$BИнтересно, что на той стороне? Ты туда $Gходил:ходила;? Хм-м-м, нам обязательно надо посмотреть, что на той стороне Темного портала!','Сводить Саландрию к Темному порталу','Подуйте в детскую свистульку и позовите свою эльфийку крови – сироту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие к Темному порталу',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это место гораздо интереснее, чем о нем рассказывают. Потрясающе!$B$BНеужели его правда создал могучий волшебник Медив?$B$BИнтересно, что на той стороне? Ты туда $Gходил:ходила;? Хм-м-м, нам обязательно надо посмотреть, что на той стороне Темного портала!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сводить Саландрию к Темному порталу',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Подуйте в детскую свистульку и позовите свою эльфийку крови – сироту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10952,'Путешествие к Темному порталу','Это место гораздо интереснее, чем о нем рассказывают попечительницы сирот. Потрясающе! Нам говорили, что портал создал могучий волшебник Медив.$B$BИнтересно, что на той стороне? Ты туда $Gходил:ходила;? Хм-м-м, нам определенно надо побывать по ту сторону Темного портала!','Сводить Дорнаа к Темному порталу','Подуйте в детскую свистульку и позовите свою подопечную дренейскую сиротку.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие к Темному порталу',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это место гораздо интереснее, чем о нем рассказывают попечительницы сирот. Потрясающе! Нам говорили, что портал создал могучий волшебник Медив.$B$BИнтересно, что на той стороне? Ты туда $Gходил:ходила;? Хм-м-м, нам определенно надо побывать по ту сторону Темного портала!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сводить Дорнаа к Темному порталу',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Подуйте в детскую свистульку и позовите свою подопечную дренейскую сиротку.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10953,'Путешествие к Трону Стихий','Ты когда-нибудь $gслышал:слышала; о Троне Стихий? Кажется это такое место в Награнде, где живут все эти элементали.$b$bКогда-нибудь я стану могущественным магом или чернокнижницей. Я все узнаю про эти силы Стихий!$b$bКак ты думаешь, можно туда сходить?$b$b<Саландрия лукаво смотрит на вас.>$b$bНаверняка это будет очень познавательно. Кажется, Трон находится на севере от Гарадара, на другой стороне озера Небесной Песни.','Отведите свою подопечную, сиротку Саландрию, к Трону Стихий в Награнд. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с повелительницей стихий Шарвак.','Ты $Gпривел:привела; сюда ребенка? Безрассудный поступок. Впрочем, я обещаю, что ей не причинят вреда, во всяком случае, если она не будет соваться к Возжигателю.$B$BХм-м-м, жаль, что она эльф крови. Будь она способна на глубинные связи с миром, мы обучили бы ее исцелять его глубокие раны. Впрочем, быть может, общение с духами Стихий поможет ей лучше понять природу мирозданья.$B$BСтупай с миром. Хорошо позаботься о своей подопечной.','Сводить Саландрию к Трону Стихий','Поговорите с повелительницей стихий Шарвак в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путешествие к Трону Стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты когда-нибудь $gслышал:слышала; о Троне Стихий? Кажется это такое место в Награнде, где живут все эти элементали.$b$bКогда-нибудь я стану могущественным магом или чернокнижницей. Я все узнаю про эти силы Стихий!$b$bКак ты думаешь, можно туда сходить?$b$b<Саландрия лукаво смотрит на вас.>$b$bНаверняка это будет очень познавательно. Кажется, Трон находится на севере от Гарадара, на другой стороне озера Небесной Песни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите свою подопечную, сиротку Саландрию, к Трону Стихий в Награнд. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с повелительницей стихий Шарвак.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпривел:привела; сюда ребенка? Безрассудный поступок. Впрочем, я обещаю, что ей не причинят вреда, во всяком случае, если она не будет соваться к Возжигателю.$B$BХм-м-м, жаль, что она эльф крови. Будь она способна на глубинные связи с миром, мы обучили бы ее исцелять его глубокие раны. Впрочем, быть может, общение с духами Стихий поможет ей лучше понять природу мирозданья.$B$BСтупай с миром. Хорошо позаботься о своей подопечной.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сводить Саландрию к Трону Стихий',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с повелительницей стихий Шарвак в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10954,'Джил находится в Небесном лагере!','Я соскучилась по брату, Джилу. Он старше меня на два года, поэтому ему разрешили поступить в обучение к эфириалам в Награнде.$b$bМне бы хотелось его навестить! Он увлекается геологией и тому подобным, так что ему там нравится.$b$bПопечительница сирот говорит, что он в обучении в Небесном лагере. Кажется, этот лагерь находится прямо у дороги, далеко на западе от Телаара и на северо-западе от великой горы Ошу\'гун.','Отведите свою подопечную, сиротку Дорнаа, в Небесный лагерь в Награнде. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом. Затем поговорите с Джилом.','Я ужасно скучал по Дорнаа. Спасибо, что привели ее в гости. Тут у эфириалов мне одиноко. И они так озабочены всем этим Ошу\'гунским делом.$B$BНо когда я сдам экзамены по ювелирному делу, я смогу съездить в приют и навестить сестричку. Я чуть не сдал их на прошлой неделе, но завтра-то уж точно сдам!','Сводить Дорнаа в Небесный лагерь','Поговорите с Джилом в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Джил находится в Небесном лагере!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я соскучилась по брату, Джилу. Он старше меня на два года, поэтому ему разрешили поступить в обучение к эфириалам в Награнде.$b$bМне бы хотелось его навестить! Он увлекается геологией и тому подобным, так что ему там нравится.$b$bПопечительница сирот говорит, что он в обучении в Небесном лагере. Кажется, этот лагерь находится прямо у дороги, далеко на западе от Телаара и на северо-западе от великой горы Ошу\'гун.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите свою подопечную, сиротку Дорнаа, в Небесный лагерь в Награнде. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом. Затем поговорите с Джилом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я ужасно скучал по Дорнаа. Спасибо, что привели ее в гости. Тут у эфириалов мне одиноко. И они так озабочены всем этим Ошу\'гунским делом.$B$BНо когда я сдам экзамены по ювелирному делу, я смогу съездить в приют и навестить сестричку. Я чуть не сдал их на прошлой неделе, но завтра-то уж точно сдам!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сводить Дорнаа в Небесный лагерь',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джилом в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10955,'Мортис Шелест Крыла','До того, как все ордена друидов объединились в Круг Кенария, друиды-вороны отвечали за обучение талантливых молодых друидов искусству полета. Когда орден был распущен, бывшие его члены не оставили своего дела, но попасть к ним в ученики не так-то просто.$b$bВ настоящий момент Мортис Шелест Крыла ищет себе ученика. Немногие друиды освоили все доступные им облики, но ты, кажется, $gнаделен:наделена; теми талантами, которые нужны Мортису. Найди его в Кенарийском оплоте в Зангартопи.','Найдите Мортиса Шелеста Крыла в Кенарийском оплоте в Зангартопи.','У тебя есть все необходимое для обучения? <Мортис смотрит на вас несколько скептически.>$B$BЯ долго искал подмастерье, чтобы передать свои знания. Хотя друиды Когтя больше не являются официальными членами ордена, я останусь им до последнего вздоха.$B$BС этого момента я принимаю тебя в ученики. Со моей стороны, я научу тебя секретам облика птицы. Со своей стороны, ты должен выполнять все, что я скажу. Ты $Gпонял:поняла;?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мортис Шелест Крыла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До того, как все ордена друидов объединились в Круг Кенария, друиды-вороны отвечали за обучение талантливых молодых друидов искусству полета. Когда орден был распущен, бывшие его члены не оставили своего дела, но попасть к ним в ученики не так-то просто.$b$bВ настоящий момент Мортис Шелест Крыла ищет себе ученика. Немногие друиды освоили все доступные им облики, но ты, кажется, $gнаделен:наделена; теми талантами, которые нужны Мортису. Найди его в Кенарийском оплоте в Зангартопи.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Мортиса Шелеста Крыла в Кенарийском оплоте в Зангартопи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя есть все необходимое для обучения? <Мортис смотрит на вас несколько скептически.>$B$BЯ долго искал подмастерье, чтобы передать свои знания. Хотя друиды Когтя больше не являются официальными членами ордена, я останусь им до последнего вздоха.$B$BС этого момента я принимаю тебя в ученики. Со моей стороны, я научу тебя секретам облика птицы. Со своей стороны, ты должен выполнять все, что я скажу. Ты $Gпонял:поняла;?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (10956,'Ты знаешь что-нибудь про наару? Это же те ангелы, которые всегда помогают дренеям. Я видела их в Шаттрате.$b$bГоворят, что один из наару, О\'рос, был в Экзодаре во время полета на Азерот. Я бы так хотела сама посмотреть.$b$bОтведи меня туда, пожалуйста. Мы быстро попадем туда через портал в Храме Луны в Дарнасе! А если заблудимся, сможем посмотреть на твою карту.','<Вы скорее чувствуете, чем слышите, мелодичный голос О\'роса.>$B$BСпасибо, что $Gпривел:привела; ко мне этого ребенка, $N. Она не такая как все, и когда вырастет, дренеи будут гордиться ею. И в этом не последнюю роль сыграет твоя доброта. Ты $Gпроизвел:произвела; на нее сильное впечатление.','Поговорите с О\'росом в Экзодаре, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты знаешь что-нибудь про наару? Это же те ангелы, которые всегда помогают дренеям. Я видела их в Шаттрате.$b$bГоворят, что один из наару, О\'рос, был в Экзодаре во время полета на Азерот. Я бы так хотела сама посмотреть.$b$bОтведи меня туда, пожалуйста. Мы быстро попадем туда через портал в Храме Луны в Дарнасе! А если заблудимся, сможем посмотреть на твою карту.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы скорее чувствуете, чем слышите, мелодичный голос О\'роса.>$B$BСпасибо, что $Gпривел:привела; ко мне этого ребенка, $N. Она не такая как все, и когда вырастет, дренеи будут гордиться ею. И в этом не последнюю роль сыграет твоя доброта. Ты $Gпроизвел:произвела; на нее сильное впечатление.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с О\'росом в Экзодаре, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10957,'Искупление Пеплоустов','Возвратите Акаме власть над его душой, сразив Тень Акамы в Черном храме. Затем возвращайтесь в провидцу Канеи.','Дело сделано, $N. Пора расправиться с Иллиданом','Да, $N?','Вернитесь к провидцу Канеи в Черный храм.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искупление Пеплоустов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвратите Акаме власть над его душой, сразив Тень Акамы в Черном храме. Затем возвращайтесь в провидцу Канеи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дело сделано, $N. Пора расправиться с Иллиданом',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провидцу Канеи в Черный храм.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (10958,'Найти Пеплоустов','Найдите Служителей Смерти Акамы в Черном храме.','Мы ждали тебя, $N. Акама нуждается в твоей помощи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Пеплоустов',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Служителей Смерти Акамы в Черном храме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы ждали тебя, $N. Акама нуждается в твоей помощи.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10959,'Судьба Предателя','Когда воины Иллидана будут разбиты, Акама сможет открыть путь в святилище Предателя. Будь $gготов:готова; отправиться туда немедленно.$B$BНам все еще не известно, что сталось с Майев, но мы должны двигаться дальше без нее.$B$BНадеюсь, ты справишься. Иллидан едва ли придет в восторг при виде Акамы.','Провидец Канеи хочет, чтобы вы сразили Иллидана в Черном храме.','Все вышло так, как мы предполагали, $N! Воины Иллидана пали один за одним и наконец и сам Иллидан принял кару!$B$BЗнай, что многие годы Акама жил мыслями об этой минуте! Наконец-то Иллидан мертв, а мой народ свободен!','Да, $N?','Вернитесь к провидцу Канеи в Черный храм.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба Предателя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда воины Иллидана будут разбиты, Акама сможет открыть путь в святилище Предателя. Будь $gготов:готова; отправиться туда немедленно.$B$BНам все еще не известно, что сталось с Майев, но мы должны двигаться дальше без нее.$B$BНадеюсь, ты справишься. Иллидан едва ли придет в восторг при виде Акамы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Провидец Канеи хочет, чтобы вы сразили Иллидана в Черном храме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Все вышло так, как мы предполагали, $N! Воины Иллидана пали один за одним и наконец и сам Иллидан принял кару!$B$BЗнай, что многие годы Акама жил мыслями об этой минуте! Наконец-то Иллидан мертв, а мой народ свободен!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к провидцу Канеи в Черный храм.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (10960,'Когда я вырасту...','А когда тебе было столько же лет, сколько мне, ты уже $Gзнал:знала;, что будешь |3-4($c), когда вырастешь?$B$BА я не знаю, кем хочу быть. Может, магом или чернокнижницей? Или, может, рыцарем крови паладином? Да, рыцарем крови лучше всего!$B$BГоворят, что настоящие рыцари крови обучаются в Луносвете! И что наставников паладинов можно найти на площади Странников. Ты отвезешь меня туда?$B$BНу, пожалуйста, отвези меня туда, пожалуйста!','Так мало тех, кто достаточно одарен, чтобы передавать такую ​​силу от М\'уру. Увидеть это в ребенке поистине потрясающе!$B$BБыло мудро с твоей стороны привести ее ко мне.$B$BТы говоришь, что она сирота из Шаттрата? Я позабочусь о том, чтобы попечительнице сирот было подано прошение о том, чтобы она перешла под нашу опеку для надлежащего обучения. Ей будет лучше здесь.$B$BА до тех пор позаботься о ней.','Сводить Саландрию к наставникам паладинов в Луносвет.','Поговорите с Леди Лиадрин в Луносвете.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Когда я вырасту...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А когда тебе было столько же лет, сколько мне, ты уже $Gзнал:знала;, что будешь |3-4($c), когда вырастешь?$B$BА я не знаю, кем хочу быть. Может, магом или чернокнижницей? Или, может, рыцарем крови паладином? Да, рыцарем крови лучше всего!$B$BГоворят, что настоящие рыцари крови обучаются в Луносвете! И что наставников паладинов можно найти на площади Странников. Ты отвезешь меня туда?$B$BНу, пожалуйста, отвези меня туда, пожалуйста!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так мало тех, кто достаточно одарен, чтобы передавать такую ​​силу от М\'уру. Увидеть это в ребенке поистине потрясающе!$B$BБыло мудро с твоей стороны привести ее ко мне.$B$BТы говоришь, что она сирота из Шаттрата? Я позабочусь о том, чтобы попечительнице сирот было подано прошение о том, чтобы она перешла под нашу опеку для надлежащего обучения. Ей будет лучше здесь.$B$BА до тех пор позаботься о ней.',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сводить Саландрию к наставникам паладинов в Луносвет.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Леди Лиадрин в Луносвете.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10961,'Зелье пробуждения','Давным-давно одному древнему друиду доверили реликвии, обучавшие пути буревестника.$b$bПоскольку они нужны тебе для занятий, придется пробудить хранителя от сна.$b$bЯ приготовлю зелье, которое позволит сделать это без особого труда. Для составления зелья необходимы вполне обычные травы, а также топлянник, который растет на самых высоких грибах в болоте. Лети туда и набери его, но соблюдай осторожность, растение хрупкое и может взорваться, если неаккуратно с ним обращаться.','Принесите 10 топлянников, 10 древних лишайников и 10 цветков сияния грез Мортису Шелесту Крыла в Кенарийский оплот.','Ты $Gпринес:принесла; ингредиенты? Пожалуйста, испачкай на меня пыльцой. Я бесконтрольно чихаю от него.$B$B<Мортис фыркает от унизительного чихания.>$B$B<Мортис принимает у вас травы, осматривая их. Достав пузырек, он начинает смешивать зелье.>$B$BЭто займет всего минуту, $N. Затем ты $Gдолжен:должна; отправиться в Лунную поляну.','Ты $Gпринес:принесла; ингредиенты для разливки? Пожалуйста, постарайся не попасть на меня пыльцой. Я чихаю в его присутствии.$B$B<Мортис фыркает от унизительного чихания.>','Вернитесь к Мортису Шелесту Крыла в Зангартопь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зелье пробуждения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно одному древнему друиду доверили реликвии, обучавшие пути буревестника.$b$bПоскольку они нужны тебе для занятий, придется пробудить хранителя от сна.$b$bЯ приготовлю зелье, которое позволит сделать это без особого труда. Для составления зелья необходимы вполне обычные травы, а также топлянник, который растет на самых высоких грибах в болоте. Лети туда и набери его, но соблюдай осторожность, растение хрупкое и может взорваться, если неаккуратно с ним обращаться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 топлянников, 10 древних лишайников и 10 цветков сияния грез Мортису Шелесту Крыла в Кенарийский оплот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gпринес:принесла; ингредиенты? Пожалуйста, испачкай на меня пыльцой. Я бесконтрольно чихаю от него.$B$B<Мортис фыркает от унизительного чихания.>$B$B<Мортис принимает у вас травы, осматривая их. Достав пузырек, он начинает смешивать зелье.>$B$BЭто займет всего минуту, $N. Затем ты $Gдолжен:должна; отправиться в Лунную поляну.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; ингредиенты для разливки? Пожалуйста, постарайся не попасть на меня пыльцой. Я чихаю в его присутствии.$B$B<Мортис фыркает от унизительного чихания.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мортису Шелесту Крыла в Зангартопь.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10962,'Время посетить Пещеры','Здорово! Мой собственный дракон! Надеюсь, когда-нибудь я смогу подружиться с драконом.$B$B<Дорнаа прыгает от радости, крепко прижимая к себе новую игрушку.>$B$BКакая чудесная поездка! Надеюсь, она не скоро закончится!','Как ты думаешь, правду говорят про Пещеры Времени?','Подуйте в детскую свистульку и позовите свою дренейскую сироту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время посетить Пещеры',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здорово! Мой собственный дракон! Надеюсь, когда-нибудь я смогу подружиться с драконом.$B$B<Дорнаа прыгает от радости, крепко прижимая к себе новую игрушку.>$B$BКакая чудесная поездка! Надеюсь, она не скоро закончится!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как ты думаешь, правду говорят про Пещеры Времени?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Подуйте в детскую свистульку и позовите свою дренейскую сироту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10963,'Время посетить Пещеры','Здорово! Мой собственный дракон! Когда-нибудь у меня будет еще и настоящий.$B$B<Саландрия с лукавым видом рассматривает новую игрушку, думая о чем-то.>$B$BКакая чудесная поездка! Надеюсь, она не скоро закончится!','Если правда все, что говорят про Пещеры Времени, то это потрясающее место.','Подуйте в детскую свистульку и позовите свою эльфийку крови – сироту.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время посетить Пещеры',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Здорово! Мой собственный дракон! Когда-нибудь у меня будет еще и настоящий.$B$B<Саландрия с лукавым видом рассматривает новую игрушку, думая о чем-то.>$B$BКакая чудесная поездка! Надеюсь, она не скоро закончится!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если правда все, что говорят про Пещеры Времени, то это потрясающее место.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Подуйте в детскую свистульку и позовите свою эльфийку крови – сироту.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (10964,'Пробуждение спящего','Возьми зелье и отправляйся в Лунную поляну, в Кельи Малфуриона. В самой южной из них, той самой, которую охраняют Хранители снов, ты найдешь Клинтара Странника Снов.$b$bНапои его зельем и дождись его пробуждения. В момент соединения души с телом он будет очень уязвим и несомненно не узнает тебя. Представься, как только он придет в чувства. Ему понадобится твоя помощь для сбора реликвий для церемонии.','Разбудите Клинтара Странника Снов при помощи зелья Пробуждения. Когда он придет в себя, поговорите с ним.','<Друид выходит из сна, вялый и изможденный. Его взгляд блуждает по комнате в поисках...>$B$BМортис?$B$BНет, ты не Мортис... Кто ты, $R и почему нарушил мой покой?$B$B<Несмотря на враждебность вопроса, друид почти рад, что его разбудили.>','<Вы готовитесь дать зелье спящему $C.>') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пробуждение спящего',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми зелье и отправляйся в Лунную поляну, в Кельи Малфуриона. В самой южной из них, той самой, которую охраняют Хранители снов, ты найдешь Клинтара Странника Снов.$b$bНапои его зельем и дождись его пробуждения. В момент соединения души с телом он будет очень уязвим и несомненно не узнает тебя. Представься, как только он придет в чувства. Ему понадобится твоя помощь для сбора реликвий для церемонии.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разбудите Клинтара Странника Снов при помощи зелья Пробуждения. Когда он придет в себя, поговорите с ним.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Друид выходит из сна, вялый и изможденный. Его взгляд блуждает по комнате в поисках...>$B$BМортис?$B$BНет, ты не Мортис... Кто ты, $R и почему нарушил мой покой?$B$B<Несмотря на враждебность вопроса, друид почти рад, что его разбудили.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Вы готовитесь дать зелье спящему $C.>',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10965,'Не просто сон','*Клинтар внимательно слушает, пока вы перечисляете инструкции Мортиса, кивает, но вид у него весьма испуганный.*$b$bЯ не могу полностью отринуть Изумрудный Сон и отправиться тебе на помощь, но частица моей души поможет тебе в поисках реликвий. Обращайся с ней бережно, она очень хрупкая.$b$bИзумрудный Сон стал чуждым и опасным местом. Он крепко держит меня, и я не смогу стать сам собой, пока он не станет таким, как прежде. Вокруг тебя лишь отзвук реальности сна!','Охраняйте дух Клинтара Странника Снов, пока он будет собирать реликвии Авианы. Потом поговорите с хранителем снов Луросой.','Тебе повезло, что Клинтар был достаточно силен, чтобы так долго сохранять раскол в своей сущности, $N. Немногие друиды могут справиться с таким подвигом, находясь под атакой Изумрудного сна. Хорошо охраняй реликвию!','Быстрее, $R. Если эти существа сбегут из кургана, Клинтар Сновидец окажется не единственным, кто попадет в опасность.','Вернитесь к хранителю снов Луросе на Озеро Элуне\'ара, что на Лунной поляне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Не просто сон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Клинтар внимательно слушает, пока вы перечисляете инструкции Мортиса, кивает, но вид у него весьма испуганный.*$b$bЯ не могу полностью отринуть Изумрудный Сон и отправиться тебе на помощь, но частица моей души поможет тебе в поисках реликвий. Обращайся с ней бережно, она очень хрупкая.$b$bИзумрудный Сон стал чуждым и опасным местом. Он крепко держит меня, и я не смогу стать сам собой, пока он не станет таким, как прежде. Вокруг тебя лишь отзвук реальности сна!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Охраняйте дух Клинтара Странника Снов, пока он будет собирать реликвии Авианы. Потом поговорите с хранителем снов Луросой.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе повезло, что Клинтар был достаточно силен, чтобы так долго сохранять раскол в своей сущности, $N. Немногие друиды могут справиться с таким подвигом, находясь под атакой Изумрудного сна. Хорошо охраняй реликвию!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Быстрее, $R. Если эти существа сбегут из кургана, Клинтар Сновидец окажется не единственным, кто попадет в опасность.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к хранителю снов Луросе на Озеро Элуне\'ара, что на Лунной поляне.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (10966,'Возвращение в приют','Как жаль! Пора обратно в приют в Шаттрат.$b$bА мне было так хорошо! Ты лучше всех на свете, $n! Теперь ты $gмой старший брат:моя старшая сестра;!$B$b<У Дорнаа наворачиваются слезы на глаза.>$b$bЯ буду по тебе очень скучать! Когда я вырасту, я стану такой же, как ты!!!','Отведите свою подопечную, сиротку Дорнаа, обратно в приют Шаттрата, вернув дренейскую детскую свистульку попечительнице сирот Миле в Нижнем Городе.','Душа радуется, когда понимаешь, что есть великодушные вроде тебя, которые готовы щедро жертвовать собственное время на благое дело.$B$BЯ вижу, что общение с тобой произвело на Дорнаа большое впечатление. Детям полезно видеть мир за пределами приюта.$B$BОна говорит, что хотела бы отдать тебе одного из своих домашних зверушек. Чтобы ты $Gзаботился:заботилась; о ней, как некогда о Саландрии и не $Gзабыл:забыла; свою подопечную.$B$BТы теперь для нее как родня;.','Приятно видеть вас снова, |3-6($C). Я верю, что вы и молодой Дорнаа замечательно провели время вместе?','Вернитесь к попечительнице сирот Миле в Шаттрат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в приют',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как жаль! Пора обратно в приют в Шаттрат.$b$bА мне было так хорошо! Ты лучше всех на свете, $n! Теперь ты $gмой старший брат:моя старшая сестра;!$B$b<У Дорнаа наворачиваются слезы на глаза.>$b$bЯ буду по тебе очень скучать! Когда я вырасту, я стану такой же, как ты!!!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите свою подопечную, сиротку Дорнаа, обратно в приют Шаттрата, вернув дренейскую детскую свистульку попечительнице сирот Миле в Нижнем Городе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Душа радуется, когда понимаешь, что есть великодушные вроде тебя, которые готовы щедро жертвовать собственное время на благое дело.$B$BЯ вижу, что общение с тобой произвело на Дорнаа большое впечатление. Детям полезно видеть мир за пределами приюта.$B$BОна говорит, что хотела бы отдать тебе одного из своих домашних зверушек. Чтобы ты $Gзаботился:заботилась; о ней, как некогда о Саландрии и не $Gзабыл:забыла; свою подопечную.$B$BТы теперь для нее как родня;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приятно видеть вас снова, |3-6($C). Я верю, что вы и молодой Дорнаа замечательно провели время вместе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к попечительнице сирот Миле в Шаттрат.',`completedtext_loc8`);
