INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11010,'Бомбардировочный заход','Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес.','Ну как – еще не разделались с их пушечными ядрами?','Вернитесь к небесному сержанту Вандерлип на Заставу Стражи Небес, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бомбардировочный заход',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как – еще не разделались с их пушечными ядрами?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к небесному сержанту Вандерлип на Заставу Стражи Небес, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11011,'Вечная бдительность','Победа над Анзу, богом-вороном, настоящий подвиг. Но боюсь, он не оставит своей затеи вернуться в Запределье.$b$bПока у него остаются последователи, он может снова восстать из праха. На всякий случай держи при себе лунный камень Сущности.','Попросите у Мортиса Шелеста Крыла лунный камень Сущности.','Держи лунный камень при себе, $N. Если ты подозреваешь, что Анзу собирает силы, чтобы попытаться еще раз вернуться в этот мир, используй его, чтобы победить его еще раз.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вечная бдительность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Победа над Анзу, богом-вороном, настоящий подвиг. Но боюсь, он не оставит своей затеи вернуться в Запределье.$b$bПока у него остаются последователи, он может снова восстать из праха. На всякий случай держи при себе лунный камень Сущности.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попросите у Мортиса Шелеста Крыла лунный камень Сущности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Держи лунный камень при себе, $N. Если ты подозреваешь, что Анзу собирает силы, чтобы попытаться еще раз вернуться в этот мир, используй его, чтобы победить его еще раз.',`offerrewardtext_loc8`);
