INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11014,'Задание десятника','Поговорите с надсмотрщиком Варкулом Дыханием Дракона в лагере клана Драконьей Пасти.','Моргор рычит. Ты опоздал...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание десятника',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с надсмотрщиком Варкулом Дыханием Дракона в лагере клана Драконьей Пасти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Моргор рычит. Ты опоздал...',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11015,'Кристаллы Крыльев Пустоты','Принесите 30 кристаллов Крыльев Пустоты надсмотрщику Варкулу Дыханию Дракона в лагерь Драконьей Пасти.','На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.','Кристаллы Крыльев Пустоты, используются во многих предметах, в большинстве своем в оружии и доспехах.','Вернитесь к надсмотрщику Варкулу Дыханию дракона на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристаллы Крыльев Пустоты',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 30 кристаллов Крыльев Пустоты надсмотрщику Варкулу Дыханию Дракона в лагерь Драконьей Пасти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кристаллы Крыльев Пустоты, используются во многих предметах, в большинстве своем в оружии и доспехах.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надсмотрщику Варкулу Дыханию дракона на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11016,'Шкуры живодеров-пустокопов','Скорняк, говоришь? Ну здесь-то кожи в избытке. Вокруг месторождений кристаллов можно найти уйму живодеров. Убей их и забирай шкуры. Хотя у некоторых из них, шкуры попрочнее, чем у остальных, этих принесешь мне,','На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.','Нам нужны эти шкуры на подкладку для брони и прочие технические нужды.','Вернитесь к надсмотрщику Варкулу Дыханию дракона на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шкуры живодеров-пустокопов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скорняк, говоришь? Ну здесь-то кожи в избытке. Вокруг месторождений кристаллов можно найти уйму живодеров. Убей их и забирай шкуры. Хотя у некоторых из них, шкуры попрочнее, чем у остальных, этих принесешь мне,',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам нужны эти шкуры на подкладку для брони и прочие технические нужды.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надсмотрщику Варкулу Дыханию дракона на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11017,'Пыльца пустопраха','Цветочки собираешь? Забааавно... К сожалению, наши маги и шаман нуждаются в твоих услугах. Кусты пустопраха, что растут на этом уступе, вырабатывают особенную пыльцу, которая необходима им в их колдовстве. Принеси мне этой штуки, и я приму у тебя сегодняшнюю работу.','На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.','Вернитесь к надсмотрщику Варкулу Дыханию дракона на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пыльца пустопраха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Цветочки собираешь? Забааавно... К сожалению, наши маги и шаман нуждаются в твоих услугах. Кусты пустопраха, что растут на этом уступе, вырабатывают особенную пыльцу, которая необходима им в их колдовстве. Принеси мне этой штуки, и я приму у тебя сегодняшнюю работу.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надсмотрщику Варкулу Дыханию дракона на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11018,'Хаотитовая руда','На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.','Эти умники там, собираются использовать эту руду, чтобы укрепить наше оружие и доспехи.','Вернитесь к надсмотрщику Варкулу Дыханию дракона на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хаотитовая руда',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На сегодня достаточно, детка. Приходи завтра, если переживешь эту ночь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти умники там, собираются использовать эту руду, чтобы укрепить наше оружие и доспехи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надсмотрщику Варкулу Дыханию дракона на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11019,'Друг в тылу врага','Не думай, что тебе придется встретиться с армией орков Скверны в одиночку.$B$B<В глазах Ярзила мерцают синие искры.>$B$BТак вот мы здесь с тобой, $N. В любой услуге, которую ты сможешь оказать оркам Скверны, действуя во имя отвоевания земель Крыльев Пустоты, мы будем рядом, чтобы удостовериться, что все идет по нашему плану.$B$BТебе надо вести себя осторожно и не привлекать к себе нежелательного внимания во время твоих акций саботажа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Друг в тылу врага',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не думай, что тебе придется встретиться с армией орков Скверны в одиночку.$B$B<В глазах Ярзила мерцают синие искры.>$B$BТак вот мы здесь с тобой, $N. В любой услуге, которую ты сможешь оказать оркам Скверны, действуя во имя отвоевания земель Крыльев Пустоты, мы будем рядом, чтобы удостовериться, что все идет по нашему плану.$B$BТебе надо вести себя осторожно и не привлекать к себе нежелательного внимания во время твоих акций саботажа.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (11020,'Медленная смерть','Вернитесь к Язриллу Наемнику на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Медленная смерть',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Язриллу Наемнику на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11021,'Альманах Ишааля','Принесите альманах Ишааля небесному командиру Адарису к северу от Скеттиса.','Вы хотите мне что-то показать?','Вернитесь к небесному командиру Адарису в лагерь Черного Ветра, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альманах Ишааля',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите альманах Ишааля небесному командиру Адарису к северу от Скеттиса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы хотите мне что-то показать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к небесному командиру Адарису в лагерь Черного Ветра, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11022,'Разговор с Мог\'доргом','Поговорите с Мог\'доргом Мудрым. Он находится на вершине башни на восточной стороне Круга Крови в Острогорье.','Мой добрый |3-6($R), я рад, что вы решили еще раз поговорить со мной перед отъездом.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разговор с Мог\'доргом',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мог\'доргом Мудрым. Он находится на вершине башни на восточной стороне Круга Крови в Острогорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мой добрый |3-6($R), я рад, что вы решили еще раз поговорить со мной перед отъездом.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11023,'Еще разок задать им жару!','Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес.','Ну, как бомбардировка?','Вернитесь к небесному сержанту Вандерлип на Заставу Стражи Небес, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще разок задать им жару!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как бомбардировка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к небесному сержанту Вандерлип на Заставу Стражи Небес, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11024,'Союзник в Нижнем Городе','Принесите альманах Ишааля Рилаку Освобожденному в Нижний Город Шаттрата.','Не может быть... Это когда-то принадлежало жрецу когтя... Откуда вы это взяли?','От вас так и разит Скеттисом! Немедленно объяснитесь!','Вернитесь к Рилаку Освобожденному в Нижний Город Шаттрата.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Союзник в Нижнем Городе',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите альманах Ишааля Рилаку Освобожденному в Нижний Город Шаттрата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не может быть... Это когда-то принадлежало жрецу когтя... Откуда вы это взяли?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','От вас так и разит Скеттисом! Немедленно объяснитесь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Рилаку Освобожденному в Нижний Город Шаттрата.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11025,'Кристаллы') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристаллы',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11026,'Гони демонов!','Ты как раз вовремя, друг! Нам нужна помощь. За это ты получишь одну редкую вещь, которая под конец поможет нам обоим.$B$BМы уже не жестокие огры, но тутошние демоны грозят перерезать и нас, стражу Небес. Беда в том, что как убьешь демона, он тут же приходит назад в новом теле!$B$BНо если ты возьмешь кристалл и сделаешь портал изгнания, то если их убивать рядом с ним, их субстанции втянет в портал, и они уйдут откуда пришли!','Это послужит им уроком!','Вернитесь к Кронку в Огри\'лу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гони демонов!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты как раз вовремя, друг! Нам нужна помощь. За это ты получишь одну редкую вещь, которая под конец поможет нам обоим.$B$BМы уже не жестокие огры, но тутошние демоны грозят перерезать и нас, стражу Небес. Беда в том, что как убьешь демона, он тут же приходит назад в новом теле!$B$BНо если ты возьмешь кристалл и сделаешь портал изгнания, то если их убивать рядом с ним, их субстанции втянет в портал, и они уйдут откуда пришли!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это послужит им уроком!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кронку в Огри\'лу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11027,'Есть у тебя темная руна?','Ха-ха, хорошо! Гакху нравятся темные руны! <Вы берете закаленную в кристаллах темную руну, которую сделал Гак ранее.>$B$B$N запомни, управляй деградером, используй молот, чтобы разбить магический щит на транспортере Шартуула. Выпусти другого демона и сразись с ним, чтобы им управлять! В логове разбивай и контролируй новых демонов, пока они не перестанут существовать!$B$BТы спасешь Огри\'ла!','Демоны из этого лагеря постоянно ремонтируют транспортера.$B$BГахку нужна темная руна, чтобы сделать выкованную кристалл с темными рунами.$B$BЕсли у маленького $R нет темной руны, поговори с Кронком. Он делает одну темную руну каждый день!','Вернитесь к Гахку в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Есть у тебя темная руна?',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ха-ха, хорошо! Гакху нравятся темные руны! <Вы берете закаленную в кристаллах темную руну, которую сделал Гак ранее.>$B$B$N запомни, управляй деградером, используй молот, чтобы разбить магический щит на транспортере Шартуула. Выпусти другого демона и сразись с ним, чтобы им управлять! В логове разбивай и контролируй новых демонов, пока они не перестанут существовать!$B$BТы спасешь Огри\'ла!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Демоны из этого лагеря постоянно ремонтируют транспортера.$B$BГахку нужна темная руна, чтобы сделать выкованную кристалл с темными рунами.$B$BЕсли у маленького $R нет темной руны, поговори с Кронком. Он делает одну темную руну каждый день!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гахку в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (11028,'Оставшееся время','Расскажите небесному капитану Адарису о возвращении Терокка. Вы сможете найти его в лагере Черного Ветра в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оставшееся время',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расскажите небесному капитану Адарису о возвращении Терокка. Вы сможете найти его в лагере Черного Ветра в лесу Тероккар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11029,'Потрепанная маскировка','Открывайте, $n. Это маскировочный костюм. Выглядит не очень-то убедительно, да?$B$BЯ шью их для астральных контрабандистов, которые ищут редкие книги. В центре Скеттиса, в местечке под названием Покой Терокка, живет писатель араккоа – совсем старый и почти слепой.$B$BНаденьте этот костюм и постарайтесь выманить у него книгу "Кровная вражда". Но будьте осторожны – других араккоа этот костюм не обманет.','Оденьтесь в потрепанный маскировочный костюм араккоа, возьмите книгу "Кровная вражда" у Сахаака и вернитесь к Хаззику.','Вернитесь к Хаззику в лагерь Черного Ветра, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потрепанная маскировка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Открывайте, $n. Это маскировочный костюм. Выглядит не очень-то убедительно, да?$B$BЯ шью их для астральных контрабандистов, которые ищут редкие книги. В центре Скеттиса, в местечке под названием Покой Терокка, живет писатель араккоа – совсем старый и почти слепой.$B$BНаденьте этот костюм и постарайтесь выманить у него книгу "Кровная вражда". Но будьте осторожны – других араккоа этот костюм не обманет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Оденьтесь в потрепанный маскировочный костюм араккоа, возьмите книгу "Кровная вражда" у Сахаака и вернитесь к Хаззику.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хаззику в лагерь Черного Ветра, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11030,'Наш мальчик хочет быть следопытом Стражи Небес','$C, у нас есть одна проблема – у нас много сыновей. И поскольку рядом обосновалась Стража Небес, наши сыновья только и говорят, что хотят вступить в ее ряды.$B$BБудучи гордым отцом, мы хотим для них самого лучшего. Потому не сходишь ли ты к хрустальной кузнице Скверны в Лагерь Легиона на север или юг, чтобы добыть магический настой для наших сыновей? Иди на зеленый дым – и найдешь лагерь.$B$BМы думаем, что на настой пойдет десять осколков апексита. Мы бы их тебе дали, да у нас нету.','Добудьте нестабильный настой Зверя.','Вернитесь к Торкусу в Огри\'лу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наш мальчик хочет быть следопытом Стражи Небес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, у нас есть одна проблема – у нас много сыновей. И поскольку рядом обосновалась Стража Небес, наши сыновья только и говорят, что хотят вступить в ее ряды.$B$BБудучи гордым отцом, мы хотим для них самого лучшего. Потому не сходишь ли ты к хрустальной кузнице Скверны в Лагерь Легиона на север или юг, чтобы добыть магический настой для наших сыновей? Иди на зеленый дым – и найдешь лагерь.$B$BМы думаем, что на настой пойдет десять осколков апексита. Мы бы их тебе дали, да у нас нету.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте нестабильный настой Зверя.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торкусу в Огри\'лу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11031,'Перестать быть верховным магом из Аметистового Ока','Ты $Gрешил:решила; отказаться от своего предыдущего выбора?$B$BЯ полагаю, что могу помочь вам обратить его вспять. В конце концов, Даларан больше заботится о твоей преданности, чем о том, как ты ее проявляешь.$B$BЭто будет недешево. И конечно, мне нужно будет вернуть твое старое кольцо.','Вернитесь к верховному магу Лериде на Перевал Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перестать быть верховным магом из Аметистового Ока',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gрешил:решила; отказаться от своего предыдущего выбора?$B$BЯ полагаю, что могу помочь вам обратить его вспять. В конце концов, Даларан больше заботится о твоей преданности, чем о том, как ты ее проявляешь.$B$BЭто будет недешево. И конечно, мне нужно будет вернуть твое старое кольцо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лериде на Перевал Мертвого Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11032,'Перестать быть защитником из Аметистового Ока','Прими это следующее решение тщательно. Мы делаем все возможное, чтобы помочь нашим союзникам, но даже ресурсы Даларана имеют свои пределы.','Ты $Gрешил:решила; отказаться от своего предыдущего выбора?$B$BЯ полагаю, что могу помочь вам обратить его вспять. В конце концов, Даларан больше заботится о твоей преданности, чем о том, как ты ее проявляешь.$B$BЭто будет недешево. И конечно, мне нужно будет вернуть твое старое кольцо.','Вернитесь к верховному магу Лериде на Перевал Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перестать быть защитником из Аметистового Ока',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прими это следующее решение тщательно. Мы делаем все возможное, чтобы помочь нашим союзникам, но даже ресурсы Даларана имеют свои пределы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gрешил:решила; отказаться от своего предыдущего выбора?$B$BЯ полагаю, что могу помочь вам обратить его вспять. В конце концов, Даларан больше заботится о твоей преданности, чем о том, как ты ее проявляешь.$B$BЭто будет недешево. И конечно, мне нужно будет вернуть твое старое кольцо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лериде на Перевал Мертвого Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11033,'Перестать быть убийцей из Аметистового Ока','Прими это следующее решение тщательно. Мы делаем все возможное, чтобы помочь нашим союзникам, но даже ресурсы Даларана имеют свои пределы.','Ты $Gрешил:решила; отказаться от своего предыдущего выбора?$B$BЯ полагаю, что могу помочь вам обратить его вспять. В конце концов, Даларан больше заботится о твоей преданности, чем о том, как ты ее проявляешь.$B$BЭто будет недешево. И конечно, мне нужно будет вернуть твое старое кольцо.','Вернитесь к верховному магу Лериде на Перевал Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перестать быть убийцей из Аметистового Ока',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прими это следующее решение тщательно. Мы делаем все возможное, чтобы помочь нашим союзникам, но даже ресурсы Даларана имеют свои пределы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gрешил:решила; отказаться от своего предыдущего выбора?$B$BЯ полагаю, что могу помочь вам обратить его вспять. В конце концов, Даларан больше заботится о твоей преданности, чем о том, как ты ее проявляешь.$B$BЭто будет недешево. И конечно, мне нужно будет вернуть твое старое кольцо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лериде на Перевал Мертвого Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11034,'Перестать быть исцелителем','Прими это следующее решение тщательно. Мы делаем все возможное, чтобы помочь нашим союзникам, но даже ресурсы Даларана имеют свои пределы.','Ты $Gрешил:решила; отказаться от своего предыдущего выбора?$B$BЯ полагаю, что могу помочь вам обратить его вспять. В конце концов, Даларан больше заботится о твоей преданности, чем о том, как ты ее проявляешь.$B$BЭто будет недешево. И конечно, мне нужно будет вернуть твое старое кольцо.','Вернитесь к верховному магу Лериде на Перевал Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перестать быть исцелителем',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прими это следующее решение тщательно. Мы делаем все возможное, чтобы помочь нашим союзникам, но даже ресурсы Даларана имеют свои пределы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gрешил:решила; отказаться от своего предыдущего выбора?$B$BЯ полагаю, что могу помочь вам обратить его вспять. В конце концов, Даларан больше заботится о твоей преданности, чем о том, как ты ее проявляешь.$B$BЭто будет недешево. И конечно, мне нужно будет вернуть твое старое кольцо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Лериде на Перевал Мертвого Ветра.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (11035,'Недружелюбные небеса','На северо-восточном краю этого острова есть док, в котором пакуют и вывозят кристаллы Крыльев Пустоты и прочие реликвии. Перевозчики из клана Драконьей Пасти транспортируют товары от дока до клановой крепости, в то время как лидеры клана охраняют это место от любого, кто осмелится напасть.$B$BЕдинственный путь добраться туда и напасть на клан, – Заоблачная тропа Драконьей Пасти.$B$BЛети к расколотым островам по Небесной дороге и устрой там засаду на перевозчиков, которые пользуются этим маршрутом. Возврати наши утраченные реликвии!','Вернитесь к Язриллу Наемнику на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Недружелюбные небеса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На северо-восточном краю этого острова есть док, в котором пакуют и вывозят кристаллы Крыльев Пустоты и прочие реликвии. Перевозчики из клана Драконьей Пасти транспортируют товары от дока до клановой крепости, в то время как лидеры клана охраняют это место от любого, кто осмелится напасть.$B$BЕдинственный путь добраться туда и напасть на клан, – Заоблачная тропа Драконьей Пасти.$B$BЛети к расколотым островам по Небесной дороге и устрой там засаду на перевозчиков, которые пользуются этим маршрутом. Возврати наши утраченные реликвии!',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Язриллу Наемнику на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (11036,'Еще один пункт долой!','Это поставка от старины Орока?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще один пункт долой!',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это поставка от старины Орока?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (11037,'Странное видение','Мне было странное видение, $n. Я так и не поняла, что оно значит. Я видела стрелу, огромную стрелу с огненным оперением, устремленную в небо. Для опытного чародея сотворить что-то подобное – раз плюнуть, но я почему-то уверена, что эта стрела – не творение магов.$B$BЭто совсем не похоже на то, что умеют и могут мастера Азерота. Разыщи тех, кто создал эту стрелу, $n. И предложи им свою помощь, ибо не исключено, что без помощи со стороны все их усилия пропадут втуне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странное видение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне было странное видение, $n. Я так и не поняла, что оно значит. Я видела стрелу, огромную стрелу с огненным оперением, устремленную в небо. Для опытного чародея сотворить что-то подобное – раз плюнуть, но я почему-то уверена, что эта стрела – не творение магов.$B$BЭто совсем не похоже на то, что умеют и могут мастера Азерота. Разыщи тех, кто создал эту стрелу, $n. И предложи им свою помощь, ибо не исключено, что без помощи со стороны все их усилия пропадут втуне.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11038,'Помощь экзарху Орелису','Недавно верховная жрица Ишана отправила в Пустоверть группу отшельников под началом экзарха Орелиса. Они должны были проследить за действиями Кель\'таса и его приспешников, но пока что от них не поступило никакой информации.$B$BБоюсь, что у нас не хватит сил на это задание, поэтому ваша помощь придется экзарху очень кстати. Не желаете ли отправиться в Зону 52 и помочь ему?','Поговорите с экзархом Орелисом в Зоне 52.','Значит, вы хотите помочь нам узнать планы Кель\'таса? Это хорошо. Пустоверть так и кишит агентами эльфов крови, из-за которых эта земля скоро распадется на части.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь экзарху Орелису',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно верховная жрица Ишана отправила в Пустоверть группу отшельников под началом экзарха Орелиса. Они должны были проследить за действиями Кель\'таса и его приспешников, но пока что от них не поступило никакой информации.$B$BБоюсь, что у нас не хватит сил на это задание, поэтому ваша помощь придется экзарху очень кстати. Не желаете ли отправиться в Зону 52 и помочь ему?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с экзархом Орелисом в Зоне 52.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, вы хотите помочь нам узнать планы Кель\'таса? Это хорошо. Пустоверть так и кишит агентами эльфов крови, из-за которых эта земля скоро распадется на части.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11039,'Отчет патрону шпионов Талодиену','Не так давно Ворен\'таль отправил в Пустоверть небольшую группу слежения за действиями Кель\'таса. Наш предводитель безоговорочно доверяет патрону шпионов Талодиену и его соратникам, поэтому не отказал ему в просьбе о подкреплении.$B$BОтчет Талодиена был очень кратким, но из него было понятно, что он обнаружил что-то очень важное. Отправляйтесь к нему в Зону 52 и помогите ему всем, чем сумеете.','Доложитесь патрону шпионов Талодиену в Зоне 52.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отчет патрону шпионов Талодиену',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не так давно Ворен\'таль отправил в Пустоверть небольшую группу слежения за действиями Кель\'таса. Наш предводитель безоговорочно доверяет патрону шпионов Талодиену и его соратникам, поэтому не отказал ему в просьбе о подкреплении.$B$BОтчет Талодиена был очень кратким, но из него было понятно, что он обнаружил что-то очень важное. Отправляйтесь к нему в Зону 52 и помогите ему всем, чем сумеете.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь патрону шпионов Талодиену в Зоне 52.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11040,'Чтоб я ещё знал, на кой нужны некоторые из этих деталей... Нет, я найду им применение, но никогда не думал, что однажды придется научиться думать по-гномски!','Похоже, что это ящик гномского мастера-инженера. Стало быть, вас Босси прислала?') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чтоб я ещё знал, на кой нужны некоторые из этих деталей... Нет, я найду им применение, но никогда не думал, что однажды придется научиться думать по-гномски!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Похоже, что это ящик гномского мастера-инженера. Стало быть, вас Босси прислала?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11041,'Неоконченное дело','Убейте 10 надземных живодеров и Бараш Мать Стаи. По выполнении вернитесь к властителю Мор\'гору в лагерь Драконьей Пасти.','Как докладывает один из моих наблюдателей, ты получил приказ и взял дело в свои собственные руки? Хм... Неплохо. Тебе удалось удивить меня.','Вернитесь к властителю Мор\'гору на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неоконченное дело',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 надземных живодеров и Бараш Мать Стаи. По выполнении вернитесь к властителю Мор\'гору в лагерь Драконьей Пасти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как докладывает один из моих наблюдателей, ты получил приказ и взял дело в свои собственные руки? Хм... Неплохо. Тебе удалось удивить меня.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Мор\'гору на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (11042,'Таинственное видение','Меня преследует странное видение, $n. Я вижу столп дыма, поднимающийся в небо вслед за гигантским огнем. Это не природное явление и не исчадие зла – в этом я абсолютно уверен.$B$BЯ не знаю, что это такое. Знаю только, что его создали трудом многих существ. Да... В одиночку это было бы невозможно осуществить. $B$BОтправляйся в Пустоверть, |3-6($c). Найди тех, кто сотворил этот дым, и предложи им свою помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Таинственное видение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня преследует странное видение, $n. Я вижу столп дыма, поднимающийся в небо вслед за гигантским огнем. Это не природное явление и не исчадие зла – в этом я абсолютно уверен.$B$BЯ не знаю, что это такое. Знаю только, что его создали трудом многих существ. Да... В одиночку это было бы невозможно осуществить. $B$BОтправляйся в Пустоверть, |3-6($c). Найди тех, кто сотворил этот дым, и предложи им свою помощь.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11043,'Усовершенствованный грифон','Я слышал, что эти дворфы Громового Молота устроили грифоний насест в своей крепости внизу в южной Долине Призрачной Луны. Если ты туда идешь, поговори с ними от моего имени, ладно? У меня есть кое-какие идеи насчет того, как бы получше оснастить их грифонов!$B$BЧего останавливаться-то, если можно приделать к ним альтиметр, зеркало заднего обзора и ракету? Представляешь, как быстро можно летать, если привязать к заднице грифона вот такую малышку! Я назову ее Турбо-Грифон 8000!','Поговорите с Брюнном Жаробородом в Цитадели Громового Молота в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Усовершенствованный грифон',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышал, что эти дворфы Громового Молота устроили грифоний насест в своей крепости внизу в южной Долине Призрачной Луны. Если ты туда идешь, поговори с ними от моего имени, ладно? У меня есть кое-какие идеи насчет того, как бы получше оснастить их грифонов!$B$BЧего останавливаться-то, если можно приделать к ним альтиметр, зеркало заднего обзора и ракету? Представляешь, как быстро можно летать, если привязать к заднице грифона вот такую малышку! Я назову ее Турбо-Грифон 8000!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Брюнном Жаробородом в Цитадели Громового Молота в Долине Призрачной Луны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11044,'Страшные видения','Мой покой часто бывает нарушен видениями катастрофы: с небес на землю обрушивается зеленый огонь, поражая храбрых защитников крепости. Это видение мучает меня уже не одну неделю, но только недавно я осознал, к чему это предзнаменование.$B$BДалеко на востоке, в Долине Призрачной Луны, дворфы Громового Молота сдерживают постоянные атаки Пылающего Легиона и других многочисленных неприятелей. Они отчаянно сражаются, но без помощи союзников им не выстоять. Встань на их сторону, $n. Помоги им в их борьбе.','Поговорите с командиром звена Нуаинном в цитадели Громового Молота.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страшные видения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой покой часто бывает нарушен видениями катастрофы: с небес на землю обрушивается зеленый огонь, поражая храбрых защитников крепости. Это видение мучает меня уже не одну неделю, но только недавно я осознал, к чему это предзнаменование.$B$BДалеко на востоке, в Долине Призрачной Луны, дворфы Громового Молота сдерживают постоянные атаки Пылающего Легиона и других многочисленных неприятелей. Они отчаянно сражаются, но без помощи союзников им не выстоять. Встань на их сторону, $n. Помоги им в их борьбе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с командиром звена Нуаинном в цитадели Громового Молота.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11045,'Зорус Ревнитель','У Долины Призрачной Луны очень непростая история. Мало кто решается войти туда – из страха пробудить к жизни таящиеся в долине ужасы.$B$BОднако смельчаки все же находятся, например, Зорус Ревнитель – он исследует призраки прошлого этой долины. Занятие это очень опасное, так что, думаю, он будет рад любой помощи.$B$BЕсли вы вдруг попадете в долину, поищите там Зоруса – он чаще всего бывает в цитадели Громового Молота, это в самом центре южной части долины.','Поговорите с Зорусом Ревнителем в цитадели Громового Молота.','Фантей говорит правду: я действительно с радостью приму вашу помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зорус Ревнитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Долины Призрачной Луны очень непростая история. Мало кто решается войти туда – из страха пробудить к жизни таящиеся в долине ужасы.$B$BОднако смельчаки все же находятся, например, Зорус Ревнитель – он исследует призраки прошлого этой долины. Занятие это очень опасное, так что, думаю, он будет рад любой помощи.$B$BЕсли вы вдруг попадете в долину, поищите там Зоруса – он чаще всего бывает в цитадели Громового Молота, это в самом центре южной части долины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зорусом Ревнителем в цитадели Громового Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фантей говорит правду: я действительно с радостью приму вашу помощь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11046,'Главный аптекарь Хильдегард','У Долины Призрачной Луны очень непростая история. Мало кто решается исследовать ее – из страха пробудить к жизни таящиеся в долине кошмары.$B$BОднако смельчаки все же находятся. Главный аптекарь Хильдегард исследует призраки прошлого Долины Призрачной Луны – это очень опасное дело; уверен, она будет рада любой предложенной помощи.$B$BЕсли вы попадете в ту долину, поищите там аптекаря Хильдегард – наверняка найдете ее в Деревне Призрачной Луны в северо-западной части долины.','Поговорите с главным аптекарем Хильдегард в Деревне Призрачной Луны.','У Фантея хорошая память. Я уже несколько месяцев не покупала реагентов в Шаттрате. Однако он прав, помощь мне не помешает.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Главный аптекарь Хильдегард',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У Долины Призрачной Луны очень непростая история. Мало кто решается исследовать ее – из страха пробудить к жизни таящиеся в долине кошмары.$B$BОднако смельчаки все же находятся. Главный аптекарь Хильдегард исследует призраки прошлого Долины Призрачной Луны – это очень опасное дело; уверен, она будет рада любой предложенной помощи.$B$BЕсли вы попадете в ту долину, поищите там аптекаря Хильдегард – наверняка найдете ее в Деревне Призрачной Луны в северо-западной части долины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с главным аптекарем Хильдегард в Деревне Призрачной Луны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У Фантея хорошая память. Я уже несколько месяцев не покупала реагентов в Шаттрате. Однако он прав, помощь мне не помешает.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11047,'Просьба ученика') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба ученика',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11048,'Рапорт Крогхана','Мне было приказано задержаться в Гарадаре на непродолжительный срок, оценить обстановку, а потом доложить обо всем Кровавому стражу Галмоку в Деревню Призрачной Луны. Если судить по тому, что я видел, Гарадар только выиграет от долгосрочного сотрудничества с Ордой.$B$BЯ понимаю, что у Галмока сейчас на счету каждый воин, но я думаю, он поймет, что моя миссия здесь еще не закончена. Отправляйся в Деревню Призрачной Луны на северо-западе Долины Призрачной Луны и объясни Кровавому стражу Галмоку, в чем причина задержки.','Объясните Кровавому стражу Галмоку в Деревне Призрачной Луны, почему Крогхан не может явиться к нему.','<Узнав о решении Крогхана, Галмок недовольно ворчит.>$B$BЯ понимаю его точку зрения, но у нас на счету каждый воин! Легион денно и нощно посылает против нас инферналов. Если Крогхан не торопится возвращаться, ты займешь его место в окопах!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рапорт Крогхана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне было приказано задержаться в Гарадаре на непродолжительный срок, оценить обстановку, а потом доложить обо всем Кровавому стражу Галмоку в Деревню Призрачной Луны. Если судить по тому, что я видел, Гарадар только выиграет от долгосрочного сотрудничества с Ордой.$B$BЯ понимаю, что у Галмока сейчас на счету каждый воин, но я думаю, он поймет, что моя миссия здесь еще не закончена. Отправляйся в Деревню Призрачной Луны на северо-западе Долины Призрачной Луны и объясни Кровавому стражу Галмоку, в чем причина задержки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Объясните Кровавому стражу Галмоку в Деревне Призрачной Луны, почему Крогхан не может явиться к нему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Узнав о решении Крогхана, Галмок недовольно ворчит.>$B$BЯ понимаю его точку зрения, но у нас на счету каждый воин! Легион денно и нощно посылает против нас инферналов. Если Крогхан не торопится возвращаться, ты займешь его место в окопах!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11049,'Большая Охота','Если вдруг в твоих странствиях ты обнаружишь яйца драконов Крыльев Пустоты, не затруднит ли тебя принести их мне?$B$BПредупреждаю, это редкая вещь, не огорчайся, если тебе не удастся найти ни одного. Клан Драконьей Пасти потратил уйму времени и сил, собирая эти яйца и пряча их в разных укромных местах.$B$BИх можно обнаружить у существ, обитающих на острове, возле месторождений кристаллов, в копях, или даже в кустах пустопраха.$B$BНо соблюдай осторожность – мы же не хотим, чтобы Мор\'гор засек тебя?','Как продвигается охота?','Вернитесь к Язриллу Наемнику на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Большая Охота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если вдруг в твоих странствиях ты обнаружишь яйца драконов Крыльев Пустоты, не затруднит ли тебя принести их мне?$B$BПредупреждаю, это редкая вещь, не огорчайся, если тебе не удастся найти ни одного. Клан Драконьей Пасти потратил уйму времени и сил, собирая эти яйца и пряча их в разных укромных местах.$B$BИх можно обнаружить у существ, обитающих на острове, возле месторождений кристаллов, в копях, или даже в кустах пустопраха.$B$BНо соблюдай осторожность – мы же не хотим, чтобы Мор\'гор засек тебя?',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигается охота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Язриллу Наемнику на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (11050,'Собрать их все!','Вернитесь к Язриллу Наемнику в Долину Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собрать их все!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Язриллу Наемнику в Долину Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (11051,'Демонов – долой!','Если мы понимаем в демонах, а мы понимаем, потому что усердно их изучаем, то они быстро устраняют любой урон, нанесенный их драгоценным транспортерам.$B$BСтало быть, если ты хочешь попытать удачи с другой темной руной, возьми еще раз наш кристалл изгнания и уничтожь еще демонов. Кстати, ты ведь хочешь помочь нам справиться с ними?$B$BМы говорили – "попытать удачи", потому что результаты получаются разные. Ты можешь получить темную руну, а можешь получить и совсем не то.','Вернитесь к Кронку в Огри\'лу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Демонов – долой!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если мы понимаем в демонах, а мы понимаем, потому что усердно их изучаем, то они быстро устраняют любой урон, нанесенный их драгоценным транспортерам.$B$BСтало быть, если ты хочешь попытать удачи с другой темной руной, возьми еще раз наш кристалл изгнания и уничтожь еще демонов. Кстати, ты ведь хочешь помочь нам справиться с ними?$B$BМы говорили – "попытать удачи", потому что результаты получаются разные. Ты можешь получить темную руну, а можешь получить и совсем не то.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кронку в Огри\'лу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11052,'Обещание Акамы','<Акама вставляет кристалл в медальон, который держит в руке.>$B$BЯ уже не так силен как прежде, $n. Так тесно общаться со злом все эти годы, я не уверен, что у меня хватит сил совладать с таким могущественным артефактом.$B$BВозьми его как залог того, что когда ты встретишься лицом к лицу с Иллиданом, я буду на твоей стороне. Отнеси его тому, кому мы можем безоговорочно доверять, А\'далу в Шаттрат.','Принесите медальон Карабора А\'далу в Шаттрат.','*Ты протягиваешь медальон. А\'далу, и он исчезает в ослепительной вспышке.*$B$B*В этой вспышке тебе является видение, возможно, это видение будущего. Ты видишь, как Акама и Майев выходят из Клети Стражницы и пробиваются к Темному Храму, третья фигура, укрытая в тени, помогает им, приглядевшись, ты понимаешь, что это ты сам.*','<А\'дал замечает твое приближение, и теплый свет окутывает тебя. Кажется, он уже знает, зачем ты здесь.>','Вернитесь к А\'далу в Шаттрат, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обещание Акамы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Акама вставляет кристалл в медальон, который держит в руке.>$B$BЯ уже не так силен как прежде, $n. Так тесно общаться со злом все эти годы, я не уверен, что у меня хватит сил совладать с таким могущественным артефактом.$B$BВозьми его как залог того, что когда ты встретишься лицом к лицу с Иллиданом, я буду на твоей стороне. Отнеси его тому, кому мы можем безоговорочно доверять, А\'далу в Шаттрат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите медальон Карабора А\'далу в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Ты протягиваешь медальон. А\'далу, и он исчезает в ослепительной вспышке.*$B$B*В этой вспышке тебе является видение, возможно, это видение будущего. Ты видишь, как Акама и Майев выходят из Клети Стражницы и пробиваются к Темному Храму, третья фигура, укрытая в тени, помогает им, приглядевшись, ты понимаешь, что это ты сам.*',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<А\'дал замечает твое приближение, и теплый свет окутывает тебя. Кажется, он уже знает, зачем ты здесь.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к А\'далу в Шаттрат, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (11053,'Новое назначение','Кристаллы Крыльев Пустоты, используются во многих предметах, в большинстве своем в оружии и доспехах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новое назначение',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кристаллы Крыльев Пустоты, используются во многих предметах, в большинстве своем в оружии и доспехах.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11054,'Ты – инспектор: как делать все правильно','Так ты – новый инспектор, да? Есть одна штука, которую должен иметь каждый инспектор для поддержания дисциплины. Прежде чем ты приступишь к работе и начнешь вколачивать здравый смысл в пустые головы, тебе нужно обзавестись такой штукой. Каждый инспектор сам добывает все, что нужно для ее изготовления, и ты не будешь исключением.$B$BМне нужна узловатая кожа и прочная шкура Тирантия. Тирантия можно найти в заповеднике "Дальнее поле" в северных пределах Пустоверти.','Аррр! Теперь-то ты настоящий инспектор. Эта ящерица-переросток была грозой многих орков!$B$B*Надзиратель Грязевик начинает мастерить оружие.*','Эти пеоны палки просят! Надо как следует их проучить, $n! Чего ты ждешь?','Вернитесь к надзирателю Грязевику на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ты – инспектор: как делать все правильно',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так ты – новый инспектор, да? Есть одна штука, которую должен иметь каждый инспектор для поддержания дисциплины. Прежде чем ты приступишь к работе и начнешь вколачивать здравый смысл в пустые головы, тебе нужно обзавестись такой штукой. Каждый инспектор сам добывает все, что нужно для ее изготовления, и ты не будешь исключением.$B$BМне нужна узловатая кожа и прочная шкура Тирантия. Тирантия можно найти в заповеднике "Дальнее поле" в северных пределах Пустоверти.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Аррр! Теперь-то ты настоящий инспектор. Эта ящерица-переросток была грозой многих орков!$B$B*Надзиратель Грязевик начинает мастерить оружие.*',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти пеоны палки просят! Надо как следует их проучить, $n! Чего ты ждешь?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надзирателю Грязевику на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11055,'Вот твой ботиранг, похожих много, но этот сделан специально под тебя.$B$BБудучи инспектором, ты с его помощью будешь сеять страх в душах непокорных. Его правильное использование гарантирует тебе повиновение.$B$BОтправляйся на хрустальные поля и призови к порядку этих разгильдяев-батраков. Пускай на своей шкуре почуют мощь ботиранга!','Призовите к порядку 20 ленивых батраков в лагере Драконьей Пасти. Ботиранг нужно будет вернуть надзирателю Грязевику.','Тяжелый выдался денек! Но и плата будет хороша, верно? И не греет ли тебе душу вид того, как эти никчемные шмакодявки копошатся вокруг кристаллов. Как бы то ни было, на сегодня все. Завтра тебя ждет еще один раунд насаждения дисциплины с помощью ботиранга, так что возвращайся.','Вернитесь к надзирателю Грязевику на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот твой ботиранг, похожих много, но этот сделан специально под тебя.$B$BБудучи инспектором, ты с его помощью будешь сеять страх в душах непокорных. Его правильное использование гарантирует тебе повиновение.$B$BОтправляйся на хрустальные поля и призови к порядку этих разгильдяев-батраков. Пускай на своей шкуре почуют мощь ботиранга!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Призовите к порядку 20 ленивых батраков в лагере Драконьей Пасти. Ботиранг нужно будет вернуть надзирателю Грязевику.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тяжелый выдался денек! Но и плата будет хороша, верно? И не греет ли тебе душу вид того, как эти никчемные шмакодявки копошатся вокруг кристаллов. Как бы то ни было, на сегодня все. Завтра тебя ждет еще один раунд насаждения дисциплины с помощью ботиранга, так что возвращайся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надзирателю Грязевику на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11056,'Просьба Хаззика','Заберите сверток Хаззика из его дома в восточном Скеттисе и верните сверток хозяину.','Вернитесь к Хаззику в лагерь Черного Ветра, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба Хаззика',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заберите сверток Хаззика из его дома в восточном Скеттисе и верните сверток хозяину.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хаззику в лагерь Черного Ветра, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11057,'Огрское подполье','Поговорите с Мог\'доргом Мудрым на вершине одной из башен рядом с Кругом Крови в Острогорье.','Тебя прислали сверху? Воистину, благословенна моя миссия! Я пытаюсь спасти Кровавый Молот от уничтожения кланом Камнерогов и сыновей Груула, которые стоят за ними.$B$BЯ верю, что ты поможешь нашему тайному обществу и приведешь нас к свободе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Огрское подполье',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мог\'доргом Мудрым на вершине одной из башен рядом с Кругом Крови в Острогорье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя прислали сверху? Воистину, благословенна моя миссия! Я пытаюсь спасти Кровавый Молот от уничтожения кланом Камнерогов и сыновей Груула, которые стоят за ними.$B$BЯ верю, что ты поможешь нашему тайному обществу и приведешь нас к свободе!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (11058,'Апекситовая реликвия','Давным-давно тут обитала ныне несуществующая секта араккоа, известная как Апекс. Но оставшиеся после них предметы здесь еще попадаются. Мы зовем их апекситовыми реликвиями.$B$BМы знаем, что если ими воспользоваться как должно, то они могут принести огромное благо. Каждая реликвия выдает цветовую последовательность, соотвественно которой надо нажимать на кристаллы. Так ты проходишь через несколько уровней, каждый из которых труднее предыдущего.$B$BДля того чтобы реликвия заработала, необходим апекситовый осколок. Возвращайся, когда постигнешь суть вибраций Апекса.','Получите вибрации Апекса от апекситовой реликвии.','Вы уже научились пользоваться апекситовой реликвией? И нам, и Ша\'тарским Небесным Стражам к северу интересно, что вы о них узнали.','Постигните суть вибраций Апекса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Апекситовая реликвия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Давным-давно тут обитала ныне несуществующая секта араккоа, известная как Апекс. Но оставшиеся после них предметы здесь еще попадаются. Мы зовем их апекситовыми реликвиями.$B$BМы знаем, что если ими воспользоваться как должно, то они могут принести огромное благо. Каждая реликвия выдает цветовую последовательность, соотвественно которой надо нажимать на кристаллы. Так ты проходишь через несколько уровней, каждый из которых труднее предыдущего.$B$BДля того чтобы реликвия заработала, необходим апекситовый осколок. Возвращайся, когда постигнешь суть вибраций Апекса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Получите вибрации Апекса от апекситовой реликвии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы уже научились пользоваться апекситовой реликвией? И нам, и Ша\'тарским Небесным Стражам к северу интересно, что вы о них узнали.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Постигните суть вибраций Апекса.',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (11060,'Кристалл с темными рунами','Вернитесь к Гахку в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кристалл с темными рунами',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гахку в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11061,'Отцовский долг','Добудьте нестабильный настой волшебника.','Этот настой волшебника непременно сделает моих мальчиков еще умнее, чем они есть, и очень поможет им выполнять свои обязанности, как только их возьмут в Стражу Небес Ша\'тар.','Вернитесь к Торкусу в Огри\'лу, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отцовский долг',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте нестабильный настой волшебника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Этот настой волшебника непременно сделает моих мальчиков еще умнее, чем они есть, и очень поможет им выполнять свои обязанности, как только их возьмут в Стражу Небес Ша\'тар.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торкусу в Огри\'лу, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11062,'Застава Стражи Небес','$n, мы думали – не посетишь ли ты наших друзей на севере на заставе Стражи Небес?$B$BНебесный командир Келлер и его Стража защищают там всех нас, и он просит нас прислать кого-нибудь, кто, по нашему мнению, мог бы помочь нам.$B$BИ это будешь ты!$B$BИди туда как можно скорее и, пожалуйста, передай ему наш поклон.','Поговорите с небесным командиром Келлером на заставе Стражи Небес на вершинах Острогорья.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Застава Стражи Небес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мы думали – не посетишь ли ты наших друзей на севере на заставе Стражи Небес?$B$BНебесный командир Келлер и его Стража защищают там всех нас, и он просит нас прислать кого-нибудь, кто, по нашему мнению, мог бы помочь нам.$B$BИ это будешь ты!$B$BИди туда как можно скорее и, пожалуйста, передай ему наш поклон.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с небесным командиром Келлером на заставе Стражи Небес на вершинах Острогорья.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11063,'Заработай крылья','Так ты хочешь примкнуть к Усмирителям небес? Ты неплохо себя показал в клане Драконьей Пасти, но это ничего не значит тут, в небесах Запределья. Вопрос в том, умеешь ли ты летать?$B$BПолет – это не просто взгромоздиться на спину дракону Пустоты и отвезти в форт партию кристаллов, с этим-то любой дурак справится. Полет, это быть лучшим, первым среди орков.$B$BК западу отсюда есть шесть пилотов, победи их всех – и я пожалую тебе крылья Усмирителя небес.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заработай крылья',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так ты хочешь примкнуть к Усмирителям небес? Ты неплохо себя показал в клане Драконьей Пасти, но это ничего не значит тут, в небесах Запределья. Вопрос в том, умеешь ли ты летать?$B$BПолет – это не просто взгромоздиться на спину дракону Пустоты и отвезти в форт партию кристаллов, с этим-то любой дурак справится. Полет, это быть лучшим, первым среди орков.$B$BК западу отсюда есть шесть пилотов, победи их всех – и я пожалую тебе крылья Усмирителя небес.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11064,'Пусть моя седина не вводит тебя в заблуждение, рядовой, я все равно в десять раз искуснее тебя. И не думай, что у старика не найдется в рукаве пары козырей.$B$BВсе, что тебе остается, это гнаться за мной и постараться не слететь со своего зверя. Если тебе это удастся, – ты $gвыиграл:выиграла;.$B$BНачнем, как только ты будешь $gготов:готова;.','Тыквы?! Да-а, вот так проходит мирская слава... Я уверен, что другие наездники будут посильнее Старины.','Это наш правитель, в конце концов, выбил демонов из Запределья и закрыл их порталы. Все должны склониться перед величием Иллидана!','Победите "Старину" Марга Сквернослова.','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пусть моя седина не вводит тебя в заблуждение, рядовой, я все равно в десять раз искуснее тебя. И не думай, что у старика не найдется в рукаве пары козырей.$B$BВсе, что тебе остается, это гнаться за мной и постараться не слететь со своего зверя. Если тебе это удастся, – ты $gвыиграл:выиграла;.$B$BНачнем, как только ты будешь $gготов:готова;.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тыквы?! Да-а, вот так проходит мирская слава... Я уверен, что другие наездники будут посильнее Старины.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это наш правитель, в конце концов, выбил демонов из Запределья и закрыл их порталы. Все должны склониться перед величием Иллидана!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победите "Старину" Марга Сквернослова.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11065,'Ловим летучих скатов!','Поймайте 5 летучих скатов при помощи веревочного аркана.','Ну, удалось заарканить хоть сколько-нибудь? Похоже, с веревкой ты обращаться умеешь, так что много времени у тебя это не отнимет.','Вернитесь к стражу небес Кати на Заставу Стражи Небес, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловим летучих скатов!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 5 летучих скатов при помощи веревочного аркана.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, удалось заарканить хоть сколько-нибудь? Похоже, с веревкой ты обращаться умеешь, так что много времени у тебя это не отнимет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу небес Кати на Заставу Стражи Небес, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11066,'Нам нужно больше летучих скатов!','Поймайте 5 летучих скатов при помощи веревочного аркана.','Вернитесь к стражу небес Кати на Заставу Стражи Небес, что в Острогорье.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нам нужно больше летучих скатов!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 5 летучих скатов при помощи веревочного аркана.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к стражу небес Кати на Заставу Стражи Небес, что в Острогорье.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11067,'Гонки Драконьей Пасти: Троп Смраднорыг','В этом клане все по-честному, правда, $n? Даже такому отребью, как я, дается честный шанс. Теперь, если ты хочешь доказать усмирителям небес, что чего-то стоишь, тебе придется победить меня.$B$BЯ стряхну тебя с хвоста, как надоедливую блоху.$B$BНачнем, когда ты будешь $gготов:готова;.','Интересно... Твой следующий заезд, безусловно, будет сложнее. Корлока неуклюжим не назовешь.','Это наш правитель, в конце концов, выбил демонов из Запределья и закрыл их порталы. Все должны склониться перед величием Иллидана!','Троп Смраднорыг побежден','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гонки Драконьей Пасти: Троп Смраднорыг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В этом клане все по-честному, правда, $n? Даже такому отребью, как я, дается честный шанс. Теперь, если ты хочешь доказать усмирителям небес, что чего-то стоишь, тебе придется победить меня.$B$BЯ стряхну тебя с хвоста, как надоедливую блоху.$B$BНачнем, когда ты будешь $gготов:готова;.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интересно... Твой следующий заезд, безусловно, будет сложнее. Корлока неуклюжим не назовешь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это наш правитель, в конце концов, выбил демонов из Запределья и закрыл их порталы. Все должны склониться перед величием Иллидана!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Троп Смраднорыг побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11068,'Гонки Драконьей Пасти: Корлок Ветеринар','Ты вызываешь на бой МЕНЯ? Не смеши мои сапоги!$B$BТак ты серьезно?! Ну, тогда ладно. Все что тебе нужно – это не умереть, с этим-то ты справишься? Даже если я буду швыряться в тебя черепами и летать вокруг тебя кругами, смеясь над твоими жалкими потугами на полет?$B$BСкажи, когда будешь готов, и погнали.','Следующие два всадника – лучшие наездники среди дворфов и орков Азерота. У тебя нет против них ни единого шанса!','Это наш правитель, в конце концов, выбил демонов из Запределья и закрыл их порталы. Все должны склониться перед величием Иллидана!','Победите Корлока Ветеринара.','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гонки Драконьей Пасти: Корлок Ветеринар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты вызываешь на бой МЕНЯ? Не смеши мои сапоги!$B$BТак ты серьезно?! Ну, тогда ладно. Все что тебе нужно – это не умереть, с этим-то ты справишься? Даже если я буду швыряться в тебя черепами и летать вокруг тебя кругами, смеясь над твоими жалкими потугами на полет?$B$BСкажи, когда будешь готов, и погнали.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Следующие два всадника – лучшие наездники среди дворфов и орков Азерота. У тебя нет против них ни единого шанса!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это наш правитель, в конце концов, выбил демонов из Запределья и закрыл их порталы. Все должны склониться перед величием Иллидана!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победите Корлока Ветеринара.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11069,'Глазам своим не верю! Теперь тебе нужно обойти Маэстра, а уж тут-то у тебя нет никаких шансов.','Это наш правитель, в конце концов, выбил демонов из Запределья и закрыл их порталы. Все должны склониться перед величием Иллидана!','Командир звена Ромеон побежден','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Глазам своим не верю! Теперь тебе нужно обойти Маэстра, а уж тут-то у тебя нет никаких шансов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это наш правитель, в конце концов, выбил демонов из Запределья и закрыл их порталы. Все должны склониться перед величием Иллидана!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Командир звена Ромеон побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11070,'Три года в поту, в крови и в слезах. В основном в слезах. Количество слез, которые проливает грубый солдат, когда дело доходит до тотальной войны, просто не поддается описанию!$B$B"Они запрыгивают к нам в башню на лошадях!" "Почему их база так хорошо укреплена?" "Они захватили наш Приют Успокоения, я ухожу в самоволку!"$B$BСлабаки...$B$BЯ удрал из этой "юдоли скорби" за минуту до открытия Темного портала, теперь я один из лучших бойцов клана Драконьей Пасти. Если ты хочешь взобраться на вершину, сначала придется миновать меня.$B$BНачнем, когда скажешь.','Похоже, между тобой и победой остался только капитан, парень. Удачи! Она тебе пригодится.','Малверик - самый одаренный гонщик, которого я когда-либо видел. Единственное, что удерживает его от высшей позиции орков, - это его безрассудство.','Командир звена Маэстр побежден','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Три года в поту, в крови и в слезах. В основном в слезах. Количество слез, которые проливает грубый солдат, когда дело доходит до тотальной войны, просто не поддается описанию!$B$B"Они запрыгивают к нам в башню на лошадях!" "Почему их база так хорошо укреплена?" "Они захватили наш Приют Успокоения, я ухожу в самоволку!"$B$BСлабаки...$B$BЯ удрал из этой "юдоли скорби" за минуту до открытия Темного портала, теперь я один из лучших бойцов клана Драконьей Пасти. Если ты хочешь взобраться на вершину, сначала придется миновать меня.$B$BНачнем, когда скажешь.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, между тобой и победой остался только капитан, парень. Удачи! Она тебе пригодится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Малверик - самый одаренный гонщик, которого я когда-либо видел. Единственное, что удерживает его от высшей позиции орков, - это его безрассудство.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Командир звена Маэстр побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11071,'Ты осмеливаешься вызвать Небокрушителя? Мир вокруг тебя обрушится в бездну, и небо разлетится на куски под ударами моих метеоров.$B$BУ тебя нет шансов, солдат. Впрочем, если ты желаешь таким образом свести счеты с жизнью...$B$BЯ удовлетворю твое желание, хотя бы для того, чтобы больше ни один идиот не лез ко мне с подобными просьбами.$B$BНачнем по твоему сигналу.','Капитан Небокрушитель побежден','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты осмеливаешься вызвать Небокрушителя? Мир вокруг тебя обрушится в бездну, и небо разлетится на куски под ударами моих метеоров.$B$BУ тебя нет шансов, солдат. Впрочем, если ты желаешь таким образом свести счеты с жизнью...$B$BЯ удовлетворю твое желание, хотя бы для того, чтобы больше ни один идиот не лез ко мне с подобными просьбами.$B$BНачнем по твоему сигналу.',`details_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Капитан Небокрушитель побежден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джаю Нослаю на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11072,'Кровные враги','Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттика, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра.','Отлично! Вот, бери. Я приготовил этот сверток с предметами, символизирующими побежденных тобой врагов. Они позволят тебе вызвать Терокка.$B$BОсторожнее, $N. Он самый сильный из всех араккоа, что были и будут. Не надо его недооценивать!','Вы выполнили свою задачу, $N?','Вернитесь к Хаззику в лагерь Черного Ветра, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровные враги',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттика, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Вот, бери. Я приготовил этот сверток с предметами, символизирующими побежденных тобой врагов. Они позволят тебе вызвать Терокка.$B$BОсторожнее, $N. Он самый сильный из всех араккоа, что были и будут. Не надо его недооценивать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы выполнили свою задачу, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хаззику в лагерь Черного Ветра, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11073,'Падение Терокка','Послушайте... Я не обращал внимания на все ваши разговоры с пленником араккоа, $n, потому что ваше с ним сотрудничество может принести нам пользу.$B$BВидите ли... Если бы я помог вам с призыванием Терокка, здесь бы вспыхнул настоящий мятеж.$B$BТак что возьмите все, что вам дал Хаззик и следуйте своему плану. Мои люди прикроют вас, когда потребуется, но советую и вам привести с собой помощников. Боюсь, второго шанса вам не представится.','Возьмите приготовленное Хаззиком Подношение Затерянного во Времени и отнесите его к груде черепов в центре Скеттиса. С помощью подношения призовите Терокка и сразитесь с ним, после чего вернитесь к небесному командиру Адарису.','Вернитесь к небесному командиру Адарису в лагерь Черного Ветра, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падение Терокка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушайте... Я не обращал внимания на все ваши разговоры с пленником араккоа, $n, потому что ваше с ним сотрудничество может принести нам пользу.$B$BВидите ли... Если бы я помог вам с призыванием Терокка, здесь бы вспыхнул настоящий мятеж.$B$BТак что возьмите все, что вам дал Хаззик и следуйте своему плану. Мои люди прикроют вас, когда потребуется, но советую и вам привести с собой помощников. Боюсь, второго шанса вам не представится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите приготовленное Хаззиком Подношение Затерянного во Времени и отнесите его к груде черепов в центре Скеттиса. С помощью подношения призовите Терокка и сразитесь с ним, после чего вернитесь к небесному командиру Адарису.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к небесному командиру Адарису в лагерь Черного Ветра, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11074,'Кровные враги','Добудьте у затерянных во времени араккоа их свитки и отнесите их к груде черепов в центре круга призыва в Скеттисе. Вызовите и победите потомков врагов Терокка, после чего отнесите Хаззику коготь Аккарая, хребет Гарокка, чешую Векказа и коготь Геззарака.','Для того чтобы призвать Терокка, потребуются вещи от каждого из потомков его величайших врагов.','Вернитесь к Хаззику в лагерь Черного Ветра, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровные враги',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте у затерянных во времени араккоа их свитки и отнесите их к груде черепов в центре круга призыва в Скеттисе. Вызовите и победите потомков врагов Терокка, после чего отнесите Хаззику коготь Аккарая, хребет Гарокка, чешую Векказа и коготь Геззарака.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Для того чтобы призвать Терокка, потребуются вещи от каждого из потомков его величайших врагов.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хаззику в лагерь Черного Ветра, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11075,'Копи Крыльев Пустоты','В Копях Крыльев Пустоты требуется твоя помощь, инспектор, $n.$B$BДва дня назад нам пришлось прервать работу в одной из копей из-за одного крайне неприятного открытия. Шахтер, который работал на нижних ярусах, стукнул киркой по необычному скоплению кристаллов. К сожалению, на другом конце этого скопления оказался очень злой дракон Пустоты. Животное очнулось от спячки и первым делом истребило всех наших работников.$B$BДоложи об этом Госпоже Копей. Тебя ждут возле входа в копи к юго-западу отсюда.','Найдите Госпожу Копей на Кряже Крыльев Пустоты.','Шахтеры упорно трудятся, но ни один не осмеливается ступить в эту шахту. Они предпочитают умереть, но не спускаться в ее глубины. Теперь в твои обязанности будет входить выполнение всех тех заданий, с которыми не справились они.','Кристаллы Крыльев Пустоты, используются во многих предметах, в большинстве своем в оружии и доспехах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Копи Крыльев Пустоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Копях Крыльев Пустоты требуется твоя помощь, инспектор, $n.$B$BДва дня назад нам пришлось прервать работу в одной из копей из-за одного крайне неприятного открытия. Шахтер, который работал на нижних ярусах, стукнул киркой по необычному скоплению кристаллов. К сожалению, на другом конце этого скопления оказался очень злой дракон Пустоты. Животное очнулось от спячки и первым делом истребило всех наших работников.$B$BДоложи об этом Госпоже Копей. Тебя ждут возле входа в копи к юго-западу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Госпожу Копей на Кряже Крыльев Пустоты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Шахтеры упорно трудятся, но ни один не осмеливается ступить в эту шахту. Они предпочитают умереть, но не спускаться в ее глубины. Теперь в твои обязанности будет входить выполнение всех тех заданий, с которыми не справились они.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кристаллы Крыльев Пустоты, используются во многих предметах, в большинстве своем в оружии и доспехах.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11076,'Собрать по кусочкам...','Большая часть добытых минералов лежит сейчас в беспорядке за дверями этой шахты. Брошенные груженые тачки стоят там повсюду, а мы не можем до них добраться из-за этого вторжения.$B$BИ здесь в игру вступаешь ты, $n. Твоей задачей будет собрать груз из этих тачек, оставленных шахтерами.$B$BСобери весь груз и верни его мне или моей сестре.','Соберите для Госпожи Копей груз 15 тачек в Долине Призрачной Луны.','Вернитесь к Госпоже Копей в Копи Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собрать по кусочкам...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Большая часть добытых минералов лежит сейчас в беспорядке за дверями этой шахты. Брошенные груженые тачки стоят там повсюду, а мы не можем до них добраться из-за этого вторжения.$B$BИ здесь в игру вступаешь ты, $n. Твоей задачей будет собрать груз из этих тачек, оставленных шахтерами.$B$BСобери весь груз и верни его мне или моей сестре.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите для Госпожи Копей груз 15 тачек в Долине Призрачной Луны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Госпоже Копей в Копи Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11077,'Драконы – это не самое страшное','Этот дракон проснулся в злобе на мелких надоедливых существ, кишащих в этих копях. И для клана Драконьей Пасти они тоже – как шило в боку. Особенно живодеры-пустокопы и опустошители-пустокопы из Копей Пустоты. Помоги нам от них избавиться. Я не прошу тебя отдать этому все свое время – будет достаточно одного раза в день.$B$BОтправляйся туда и убей столько, сколько сможешь.','Убейте 15 живодеров-пустокопов и 5 опустошителей-пустокопов из Копей Пустоты для штейгера из клана Драконьей Пасти.','На сегодня достаточно, инспектор. Возвращайся завтра для нового раунда зачистки.','Как продвигается решение нашей проблемы?','Вернитесь к штейгеру из клана Драконьей Пасти в Копи Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Драконы – это не самое страшное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот дракон проснулся в злобе на мелких надоедливых существ, кишащих в этих копях. И для клана Драконьей Пасти они тоже – как шило в боку. Особенно живодеры-пустокопы и опустошители-пустокопы из Копей Пустоты. Помоги нам от них избавиться. Я не прошу тебя отдать этому все свое время – будет достаточно одного раза в день.$B$BОтправляйся туда и убей столько, сколько сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 живодеров-пустокопов и 5 опустошителей-пустокопов из Копей Пустоты для штейгера из клана Драконьей Пасти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','На сегодня достаточно, инспектор. Возвращайся завтра для нового раунда зачистки.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигается решение нашей проблемы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру из клана Драконьей Пасти в Копи Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (11080,'Излучение реликвии','Теперь, когда ты $Gпознал:познала; просветляющую вибрацию апекситовой реликвии, пора глубже изучить принципы ее действия. Мы будем с нетерпением ждать результатов твоих изысканий!$B$BЧем лучше ты настроишься на взаимодействие с реликвией, тем выше станет уровень твоих познаний. Ты поймешь это по излучению от реликвии.$B$BВернись к нам, когда почувствуешь это излучение.','Испытайте на себе излучение от апекситовой реликвии.','Мы чураемся жестокости, но по крайней мере создание, которое мы послали тебя уничтожить, не было живым.\n\nКстати – голова при тебе?','Вы почувствовали на себе апекситовое излучение') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Излучение реликвии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты $Gпознал:познала; просветляющую вибрацию апекситовой реликвии, пора глубже изучить принципы ее действия. Мы будем с нетерпением ждать результатов твоих изысканий!$B$BЧем лучше ты настроишься на взаимодействие с реликвией, тем выше станет уровень твоих познаний. Ты поймешь это по излучению от реликвии.$B$BВернись к нам, когда почувствуешь это излучение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испытайте на себе излучение от апекситовой реликвии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы чураемся жестокости, но по крайней мере создание, которое мы послали тебя уничтожить, не было живым.\n\nКстати – голова при тебе?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Вы почувствовали на себе апекситовое излучение',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11081,'Восстание в племени Темной Крови','Этот документ говорит о восстании, планируемом Сломленными из племени Темной Крови. Видимо дракона использовали, для того, чтобы отвлечь внимание от их исчезновения, но, глядя на их тела, разбросанные по шахте, придется признать, что план их провалился.$B$BВерни планы побега Госпоже Копей.','Отнесите планы побега племени Темной Крови Госпоже Копей.','Что это?','Вернитесь к Госпоже Копей в Копи Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восстание в племени Темной Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот документ говорит о восстании, планируемом Сломленными из племени Темной Крови. Видимо дракона использовали, для того, чтобы отвлечь внимание от их исчезновения, но, глядя на их тела, разбросанные по шахте, придется признать, что план их провалился.$B$BВерни планы побега Госпоже Копей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите планы побега племени Темной Крови Госпоже Копей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Госпоже Копей в Копи Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11082,'В поисках правды','Эти шахтеры слишком тупы, чтобы придумать какой бы то ни было план побега. Мы должны найти и наказать того, кто помог им. Отправляйся в шахту и найди там надзирателей из племени Темной Крови. Если они впутались в эту заварушку с побегом, то, скорее всего, они будут скрываться.$B$BКак только ты найдешь хоть одного, пытай его, пока он не выдаст тебе, кто стоял за составлением этого плана. Вернешься ко мне с именем этого предателя и рукой надзирателя.','Найдите надзирателя из племени Темной Крови и допросите его. Вернитесь к Госпоже Копей с информацией об организаторе побега и рукой надзирателя.','Нечего сказать? Возможно, когда он будет истекать кровью на полу этой шахты, он вспомнит... Вспомнит, что значит идти против сил Иллидана!','Ну? Неужели это заняло столько времени?','Соберите сведения о планах Темной Крови.','Вернитесь к Госпоже Копей в Копи Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках правды',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти шахтеры слишком тупы, чтобы придумать какой бы то ни было план побега. Мы должны найти и наказать того, кто помог им. Отправляйся в шахту и найди там надзирателей из племени Темной Крови. Если они впутались в эту заварушку с побегом, то, скорее всего, они будут скрываться.$B$BКак только ты найдешь хоть одного, пытай его, пока он не выдаст тебе, кто стоял за составлением этого плана. Вернешься ко мне с именем этого предателя и рукой надзирателя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите надзирателя из племени Темной Крови и допросите его. Вернитесь к Госпоже Копей с информацией об организаторе побега и рукой надзирателя.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нечего сказать? Возможно, когда он будет истекать кровью на полу этой шахты, он вспомнит... Вспомнит, что значит идти против сил Иллидана!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну? Неужели это заняло столько времени?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Соберите сведения о планах Темной Крови.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Госпоже Копей в Копи Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11083,'Спятившие и очень опасные...','Не волнуйся из-за дракона, $n. Мы нашли на него управу.$B$BНа нижних ярусах этой копи обитает банда психов из клана Темной Крови. После того как дракон вырвался, они оказались отрезанными от выхода. И вот спустя всего 2 дня они утратили всякие представления о приличиях, обратились к каннибализму и прочим дикостям. Нам там эти психи не нужны! Поэтому иди и убей их. Всех!','Кристаллы Крыльев Пустоты, используются во многих предметах, в большинстве своем в оружии и доспехах.','Вернитесь к Ронагу Деспоту в Копи Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спятившие и очень опасные...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не волнуйся из-за дракона, $n. Мы нашли на него управу.$B$BНа нижних ярусах этой копи обитает банда психов из клана Темной Крови. После того как дракон вырвался, они оказались отрезанными от выхода. И вот спустя всего 2 дня они утратили всякие представления о приличиях, обратились к каннибализму и прочим дикостям. Нам там эти психи не нужны! Поэтому иди и убей их. Всех!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кристаллы Крыльев Пустоты, используются во многих предметах, в большинстве своем в оружии и доспехах.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ронагу Деспоту в Копи Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (11084,'Стой прямо, капитан!','Так... Так... Так... Все еще $Gжив:жива; как я погляжу. Хорошо. Потому что Мор\'гор, хочет тебя видеть немедленно. Шевелись!','Как я уже говорил, пыльца хаотического пыльника используется нашими заклинателями.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стой прямо, капитан!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так... Так... Так... Все еще $Gжив:жива; как я погляжу. Хорошо. Потому что Мор\'гор, хочет тебя видеть немедленно. Шевелись!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как я уже говорил, пыльца хаотического пыльника используется нашими заклинателями.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11085,'Побег из Скеттиса','Здравствуй, $n. Спасибо, что $gпришел:пришла; мне на помощь.$B$BЯ был на разведке, когда эти жуткие араккоа сбили меня с моего ската.$B$BДавай выбираться отсюда, пока еще можем!','Проводите плененного Стража Небес в безопасное место, а затем доложите небесному сержанту Дорину.','Да, $N?','Плененный Страж Небес освобожден','Вернитесь к небесному сержанту Дорину в лагерь Черного Ветра, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег из Скеттиса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здравствуй, $n. Спасибо, что $gпришел:пришла; мне на помощь.$B$BЯ был на разведке, когда эти жуткие араккоа сбили меня с моего ската.$B$BДавай выбираться отсюда, пока еще можем!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите плененного Стража Небес в безопасное место, а затем доложите небесному сержанту Дорину.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Плененный Страж Небес освобожден',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к небесному сержанту Дорину в лагерь Черного Ветра, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11086,'Разрушение сумеречного портала','Это наш правитель, в конце концов, выбил демонов из Запределья и закрыл их порталы. Все должны склониться перед величием Иллидана!','Вернитесь к властителю Мор\'гору на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разрушение сумеречного портала',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это наш правитель, в конце концов, выбил демонов из Запределья и закрыл их порталы. Все должны склониться перед величием Иллидана!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Мор\'гору на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11087,'ФЛАГ ХИДЖАЛА','Иллидан наполнил семь фиалов из Источника Вечности. Три из них он вылил в озеро на вершине горы Хиджал и создал второй Источник. Долгое время считалось, что остальные четыре были утрачены. $B$BПосле того как открылся Темный портал, мы узнали, что Иллидан отдал по одному фиалу своим лейтенантам Кель\'тасу и Вайш. Найди их и верни нам эти фиалы. Мы используем их для того, чтобы сфокусироваться на событиях, связанных с горой Хиджал, и открыть портал. Мы не позволим изменить исход битвы за гору Хиджал.','Соридорми из Пещер Времени желает, чтобы вы принесли ей неполный фиал Леди Вайш из Резервуара Кривого Клыка и неполный фиал Кель\'таса из Крепости Бурь.','Вернитесь к Соридорми в Танарис.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ФЛАГ ХИДЖАЛА',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иллидан наполнил семь фиалов из Источника Вечности. Три из них он вылил в озеро на вершине горы Хиджал и создал второй Источник. Долгое время считалось, что остальные четыре были утрачены. $B$BПосле того как открылся Темный портал, мы узнали, что Иллидан отдал по одному фиалу своим лейтенантам Кель\'тасу и Вайш. Найди их и верни нам эти фиалы. Мы используем их для того, чтобы сфокусироваться на событиях, связанных с горой Хиджал, и открыть портал. Мы не позволим изменить исход битвы за гору Хиджал.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соридорми из Пещер Времени желает, чтобы вы принесли ей неполный фиал Леди Вайш из Резервуара Кривого Клыка и неполный фиал Кель\'таса из Крепости Бурь.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Соридорми в Танарис.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11088,'<DEPRECATED>Утрата знаний','Принеси мне побольше огненной чароткани, и сможешь забыть обо всем.','Принесите Джонатану Лекрафту 10 отрезов огненной чароткани.','Вернитесь к Джонатану Лекрафту на Остров Дизайнера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<DEPRECATED>Утрата знаний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принеси мне побольше огненной чароткани, и сможешь забыть обо всем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Джонатану Лекрафту 10 отрезов огненной чароткани.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джонатану Лекрафту на Остров Дизайнера.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11089,'Пушка души Рет\'хедрона','Рет\'хедрон теперь правит Сумеречной Грядой в Награнде. Эредар такой силы, пришедший в этот мир, не сулит ничего хорошего Иллидари. Увы, у нас не хватает сил, чтобы справиться с ним. Особенно сейчас, когда Ша\'тар развязали войну у Черного храма. Однако у меня есть план.$B$BТы победишь Рет\'хедрона и отправишь его обратно через сумеречный портал. Для этого необходимо использовать пушку души.$B$BВот тебе список материалов, когда раздобудешь все, возвращайся ко мне.','Принесите повелителю Иллидари Балтазу, находящемуся в лагере Драконьей Пасти, 2 слитка оскверненной стали, 1 адамантитовую рамку, 1 кориевый сердечник и 1 безупречную чародейскую сущность.','Вернитесь к повелителю Иллидари Балтазу на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пушка души Рет\'хедрона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рет\'хедрон теперь правит Сумеречной Грядой в Награнде. Эредар такой силы, пришедший в этот мир, не сулит ничего хорошего Иллидари. Увы, у нас не хватает сил, чтобы справиться с ним. Особенно сейчас, когда Ша\'тар развязали войну у Черного храма. Однако у меня есть план.$B$BТы победишь Рет\'хедрона и отправишь его обратно через сумеречный портал. Для этого необходимо использовать пушку души.$B$BВот тебе список материалов, когда раздобудешь все, возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите повелителю Иллидари Балтазу, находящемуся в лагере Драконьей Пасти, 2 слитка оскверненной стали, 1 адамантитовую рамку, 1 кориевый сердечник и 1 безупречную чародейскую сущность.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелителю Иллидари Балтазу на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11090,'Покорить Покорителя','<Батлас держит в руках странно выглядящий предмет.>$B$BЭто пушка души. Правильно настроенная, она обладает разрушительным эффектом. Эта настроена на мою кровь, такую же, как та, что течет в венах Рет\'хедрона – моего брата, которого погубит его неуместная лояльность.$B$BВозьми пушку и лети на Сумеречный Хребет, в западном Награнде, найди там Рет\'хедрона и стреляй! Оставайся на своем летающем существе, в пределах видимости, чтобы достичь необходимого эффекта. Держись и ему ничего не останется, кроме как спасаться бегством.','Он вернется, но теперь силы Легиона, посланные против владыки Иллидана, ослаблены. Иллидан непременно узнает о твоих заслугах. Капитан.','Свершилось?','Покорите Рет\'хедрона Покорителя.','Вернитесь к повелителю Иллидари Балтазу на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покорить Покорителя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Батлас держит в руках странно выглядящий предмет.>$B$BЭто пушка души. Правильно настроенная, она обладает разрушительным эффектом. Эта настроена на мою кровь, такую же, как та, что течет в венах Рет\'хедрона – моего брата, которого погубит его неуместная лояльность.$B$BВозьми пушку и лети на Сумеречный Хребет, в западном Награнде, найди там Рет\'хедрона и стреляй! Оставайся на своем летающем существе, в пределах видимости, чтобы достичь необходимого эффекта. Держись и ему ничего не останется, кроме как спасаться бегством.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он вернется, но теперь силы Легиона, посланные против владыки Иллидана, ослаблены. Иллидан непременно узнает о твоих заслугах. Капитан.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Свершилось?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Покорите Рет\'хедрона Покорителя.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к повелителю Иллидари Балтазу на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (11091,'Особая благодарность','Мы чураемся жестокости, но по крайней мере создание, которое мы послали тебя уничтожить, не было живым.\n\nКстати – голова при тебе?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Особая благодарность',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы чураемся жестокости, но по крайней мере создание, которое мы послали тебя уничтожить, не было живым.\n\nКстати – голова при тебе?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11092,'Приветствую тебя, Командир!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приветствую тебя, Командир!',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11093,'Пропитание для скатов Пустоты','При должной дрессировке скаты Пустоты становятся на удивление послушными и преданными питомцами, но, к сожалению, эта война не щадит и их. У нас бывает по нескольку десятков вылетов в день – бедные звери едва успевают перевести дух. К тому же с кормом в последнее время перебои, и если скатов не убьют эти мерзкие птицелюди, то они умрут сами, от голода!$B$BЕсли вы не против, возьмите одного ската в лес, к югу отсюда. Там он сможет покушать – они не против мяса прыгуан-ловцов, но только если оно свежее.','Возьмите клетку для скатов Пустоты в лес к югу от лагеря Черного Ветра и убейте прыгуан-ловцов долины Черного Ветра около голодного ската Пустоты. После этого вернитесь к укротителю Диисаку из Стражи Небес.','Вы вернулись! Как себя вел скат?','Вернитесь к укротителю Диисаку из Стражи Небес в лагерь Черного Ветра, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропитание для скатов Пустоты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При должной дрессировке скаты Пустоты становятся на удивление послушными и преданными питомцами, но, к сожалению, эта война не щадит и их. У нас бывает по нескольку десятков вылетов в день – бедные звери едва успевают перевести дух. К тому же с кормом в последнее время перебои, и если скатов не убьют эти мерзкие птицелюди, то они умрут сами, от голода!$B$BЕсли вы не против, возьмите одного ската в лес, к югу отсюда. Там он сможет покушать – они не против мяса прыгуан-ловцов, но только если оно свежее.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите клетку для скатов Пустоты в лес к югу от лагеря Черного Ветра и убейте прыгуан-ловцов долины Черного Ветра около голодного ската Пустоты. После этого вернитесь к укротителю Диисаку из Стражи Небес.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы вернулись! Как себя вел скат?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю Диисаку из Стражи Небес в лагерь Черного Ветра, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11094,'Всех убей, один останься!','Доставьте информацию о вашей новой миссии вместе со сигнальным ружьем чародею Тэлису в Святилище Звезд.','Хорошо, что ты пришел к нам, возможно, мы сможем использовать эту атаку в своих целях и побить клан Драконьей Пасти его же оружием.','Присаживайся, дитя.','Вернитесь к чародею Тэлису в Святилище Звезд, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всех убей, один останься!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте информацию о вашей новой миссии вместе со сигнальным ружьем чародею Тэлису в Святилище Звезд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что ты пришел к нам, возможно, мы сможем использовать эту атаку в своих целях и побить клан Драконьей Пасти его же оружием.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Присаживайся, дитя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к чародею Тэлису в Святилище Звезд, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11095,'Командир Хобб','*Хобб ухмыляется.*$B$BНеплохая получится ловушка...','<Хобб кивает.>','Вернитесь к командиру Хоббу в Святилище Звезд, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Командир Хобб',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Хобб ухмыляется.*$B$BНеплохая получится ловушка...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Хобб кивает.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Хоббу в Святилище Звезд, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11096,'Атака с воздуха','Вы хотите вступить в ряды Стражи Небес? Что ж, летать вы умеете, а вот как насчет боя?$B$BСтража Небес охраняет Шаттрат от всех опасностей – как ближних, так и дальних. Одна из таких опасностей – это огры из клана Гордунни, населяющие Пограничные холмы на севере.$B$BНаземным войскам Шаттрата тяжело подобраться к ограм, поэтому эту задачу передали нам. Может быть, вы что-нибудь сможете с ними сделать.','Убейте 20 любых огров из клана Гордунни в Защитных холмах, после чего вернитесь к Юуле в Шаттрат.','Прекрасно! Думаю, мы с вами сработаемся.','Вернитесь к Юуле в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Атака с воздуха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы хотите вступить в ряды Стражи Небес? Что ж, летать вы умеете, а вот как насчет боя?$B$BСтража Небес охраняет Шаттрат от всех опасностей – как ближних, так и дальних. Одна из таких опасностей – это огры из клана Гордунни, населяющие Пограничные холмы на севере.$B$BНаземным войскам Шаттрата тяжело подобраться к ограм, поэтому эту задачу передали нам. Может быть, вы что-нибудь сможете с ними сделать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 20 любых огров из клана Гордунни в Защитных холмах, после чего вернитесь к Юуле в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно! Думаю, мы с вами сработаемся.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Юуле в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11097,'Самая опасная ловушка','Возьми эти медали Провидцев. Мор\'гору понадобится доказательство "победы", когда все закончится. Он решит, что медали сняты с наших павших воинов. $B$BТеперь все, что тебе остается, – использовать сигнальную ракету, чтобы известить налетчиков из клана Драконьей Пасти. Мы сокрушим их, когда у тебя все будет готово, только дай нам знак.','Помогите Командиру Хоббу защитить Святилище Звезд. Когда войска Драконьей Пасти будут разгромлены, вернитесь к властителю Мор\'гору в лагерь Драконьей Пасти с медалями Провидцев.','<Мор\'гор смеется.>$B$BХа! Я знал, что ты меня не подведешь, командир! Я хочу, чтобы ты устраивал набеги на Святилище Звезд как минимум один раз в день, Они поймут, что у них нет выбора, кроме как покинуть Лунную Тень!','Вернитесь к властителю Мор\'гору на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самая опасная ловушка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми эти медали Провидцев. Мор\'гору понадобится доказательство "победы", когда все закончится. Он решит, что медали сняты с наших павших воинов. $B$BТеперь все, что тебе остается, – использовать сигнальную ракету, чтобы известить налетчиков из клана Драконьей Пасти. Мы сокрушим их, когда у тебя все будет готово, только дай нам знак.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Командиру Хоббу защитить Святилище Звезд. Когда войска Драконьей Пасти будут разгромлены, вернитесь к властителю Мор\'гору в лагерь Драконьей Пасти с медалями Провидцев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Мор\'гор смеется.>$B$BХа! Я знал, что ты меня не подведешь, командир! Я хочу, чтобы ты устраивал набеги на Святилище Звезд как минимум один раз в день, Они поймут, что у них нет выбора, кроме как покинуть Лунную Тень!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Мор\'гору на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11098,'В Скеттис!','Защитные Холмы – лишь один из пределов, которые нам приходится защищать. Куда большая опасность, хотя и не столь заметная, грозит нам со стороны гор Скетил, из города араккоа, Скеттиса.$b$bНесколько месяцев назад наши лазутчики заметили, что араккоа явно оживились. За этим последовало несколько нападений на Шаттрат. С тех-то пор город и окружают войска.$b$bОтнеси эту взрывчатку сержанту Дорину в лагерь Черного Ветра рядом со Скеттисом. Скажи ему, что ты его новобранец.','Отнесите упаковку взрывчатки сержанту Дорину в лагерь Черного Ветра рядом со Скеттисом.','Вернитесь к небесному сержанту Дорину в долину Черного Ветра, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Скеттис!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Защитные Холмы – лишь один из пределов, которые нам приходится защищать. Куда большая опасность, хотя и не столь заметная, грозит нам со стороны гор Скетил, из города араккоа, Скеттиса.$b$bНесколько месяцев назад наши лазутчики заметили, что араккоа явно оживились. За этим последовало несколько нападений на Шаттрат. С тех-то пор город и окружают войска.$b$bОтнеси эту взрывчатку сержанту Дорину в лагерь Черного Ветра рядом со Скеттисом. Скажи ему, что ты его новобранец.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите упаковку взрывчатки сержанту Дорину в лагерь Черного Ветра рядом со Скеттисом.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к небесному сержанту Дорину в долину Черного Ветра, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11099,'Всех убей, один останься!','Командир $n, смирно! Вы должны взять батальон Усмирителей небес и уничтожить заставу Алдоров, расположенную к северо-западу от Черного храма. После того как алтарь Ша\'тар будет разрушен, пути к нашим постам в Лагере Змеиных Колец снова будут открыты.$B$BОтправляйтесь! Используйте сигнальное ружье, чтобы подать усмирителям сигнал к атаке!','Доставьте информацию о вашей новой миссии вместе с сигнальным ружьем анахорету Сейле к алтарю Ша\'тар.','Присаживайся, дитя мое.','Вернитесь к анахорету Сейле к алтарю Ша\'тар, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всех убей, один останься!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Командир $n, смирно! Вы должны взять батальон Усмирителей небес и уничтожить заставу Алдоров, расположенную к северо-западу от Черного храма. После того как алтарь Ша\'тар будет разрушен, пути к нашим постам в Лагере Змеиных Колец снова будут открыты.$B$BОтправляйтесь! Используйте сигнальное ружье, чтобы подать усмирителям сигнал к атаке!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте информацию о вашей новой миссии вместе с сигнальным ружьем анахорету Сейле к алтарю Ша\'тар.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Присаживайся, дитя мое.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к анахорету Сейле к алтарю Ша\'тар, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11100,'Командир Аркус','Отдайте сигнальную ракету клана Драконьей Пасти командиру Аркусу у алтаря Ша\'тар.','Вернитесь к командиру Аркусу к алтарю Ша\'тар, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Командир Аркус',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте сигнальную ракету клана Драконьей Пасти командиру Аркусу у алтаря Ша\'тар.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к командиру Аркусу к алтарю Ша\'тар, что в Долине Призрачной Луны.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (11101,'Самая Опасная Ловушка','Возьми эти медали Алдоров. Мор\'гору понадобится доказательство "победы", когда все закончится. Он решит, что медали были сняты с трупов солдат. $B$BТеперь все, что тебе остается, – использовать сигнальную ракету, чтобы известить налетчиков из клана Драконьей Пасти. Мы сокрушим их, когда у тебя все будет готово, только дай нам знак.','Вернитесь к властителю Мор\'гору на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Самая Опасная Ловушка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми эти медали Алдоров. Мор\'гору понадобится доказательство "победы", когда все закончится. Он решит, что медали были сняты с трупов солдат. $B$BТеперь все, что тебе остается, – использовать сигнальную ракету, чтобы известить налетчиков из клана Драконьей Пасти. Мы сокрушим их, когда у тебя все будет готово, только дай нам знак.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Мор\'гору на Кряж Крыльев Пустоты, что в Долине Призрачной Луны.',`completedtext_loc8`);
