INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (11107,'Склонитесь перед верховным господином','Я недостоин даже принести вам это известие, $Gсэр:мадам;, умоляю о снисхождении. Властитель Мор\'гор хочет видеть вас у себя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Склонитесь перед верховным господином',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я недостоин даже принести вам это известие, $Gсэр:мадам;, умоляю о снисхождении. Властитель Мор\'гор хочет видеть вас у себя.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11108,'Владыка Иллидан Ярость Бури','Пойдем, сам Владыка Иллидан ждет нас!','Встретьтесь с Иллиданом Яростью Бури. Найдите Бартамуса в Нижнем Городе Шаттрата, если останетесь в живых.','У тебя было настоящее приключение, $N.','Встреча с Иллиданом Яростью Бури','Вернитесь к Бартамусу в Шаттрат, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Владыка Иллидан Ярость Бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пойдем, сам Владыка Иллидан ждет нас!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Встретьтесь с Иллиданом Яростью Бури. Найдите Бартамуса в Нижнем Городе Шаттрата, если останетесь в живых.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя было настоящее приключение, $N.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Встреча с Иллиданом Яростью Бури',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бартамусу в Шаттрат, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11109,'Кобальтовый дракон Пустоты Хорус','Познакомиться с тобой, $N, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты $Gсделал:сделала; для племени Крыльев Пустоты.$B$BЕсли Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.$B$BНо ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кобальтовый дракон Пустоты Хорус',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Познакомиться с тобой, $N, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты $Gсделал:сделала; для племени Крыльев Пустоты.$B$BЕсли Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.$B$BНо ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11110,'Лиловый дракон Пустоты Малфас','Познакомиться с тобой, $N, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты $Gсделал:сделала; для племени Крыльев Пустоты.$B$BЕсли Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.$B$BНо ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лиловый дракон Пустоты Малфас',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Познакомиться с тобой, $N, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты $Gсделал:сделала; для племени Крыльев Пустоты.$B$BЕсли Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.$B$BНо ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`) VALUES (11111,'Ониксовый дракон Пустоты Ониксиен','Ну что, ты $Gсправился:справилась; с поручением?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ониксовый дракон Пустоты Ониксиен',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, ты $Gсправился:справилась; с поручением?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11112,'Лазурный дракон Пустоты Сураку','Познакомиться с тобой, $N, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты $Gсделал:сделала; для племени Крыльев Пустоты.$B$BЕсли Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.$B$BНо ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лазурный дракон Пустоты Сураку',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Познакомиться с тобой, $N, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты $Gсделал:сделала; для племени Крыльев Пустоты.$B$BЕсли Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.$B$BНо ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11113,'Пурпурный дракон Пустоты Воранаку','Познакомиться с тобой, $N, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты $Gсделал:сделала; для племени Крыльев Пустоты.$B$BЕсли Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.$B$BНо ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пурпурный дракон Пустоты Воранаку',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Познакомиться с тобой, $N, большая честь. Мы внимательно следили за всеми твоими приключениями и крайне благодарны тебе за все, что ты $Gсделал:сделала; для племени Крыльев Пустоты.$B$BЕсли Ты выберешь меня своим спутником, я пойду за тобой на край света или еще дальше. В любом случае, я сделаю все, чтобы оправдать оказанную мне честь.$B$BНо ты можешь выбрать только одного из нас, и сделанный выбор нельзя будет изменить.',`offerrewardtext_loc8`);
