INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11116,'Испытание Наару: Магтеридон (QUEST FLAG)','Прежде чем наару признают тебя достойным, тебе предстоит пройти четыре испытания.$b$bОсталось лишь одно препятствие, $gсмертный:смертная;. Собери армию побольше и отправляйся в логово Магтеридона в глубины Цитадели Адского Пламени. Пробейся в центральный чертог и убей гнусного сеятеля скверны!$B$bНаградой тебе станет ключ Урагана.','А\'дал из Шаттрата просит вас убить Магтеридона.','Вернитесь к А\'далу на Полуостров Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытание Наару: Магтеридон (QUEST FLAG)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем наару признают тебя достойным, тебе предстоит пройти четыре испытания.$b$bОсталось лишь одно препятствие, $gсмертный:смертная;. Собери армию побольше и отправляйся в логово Магтеридона в глубины Цитадели Адского Пламени. Пробейся в центральный чертог и убей гнусного сеятеля скверны!$B$bНаградой тебе станет ключ Урагана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','А\'дал из Шаттрата просит вас убить Магтеридона.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к А\'далу на Полуостров Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11117,'Поймать дикого зайцелопа!','Ну вот. Слышишь? Страшный шум в холмах. Это зайцелопы! Коварные звери так и прут на запах Хмельного фестиваля! Я хотел бы поймать парочку, да вот беда, ушиб ногу, мне их не догнать. Ты можешь мне помочь!$b$bВозьми сеть и накинь ее на мелких гадов. Принеси мне не меньше пяти, а уж за мной не заржавеет!$b$bАх, да, еще одно – чтобы увидеть зайцелопов, тебе придется использовать cинтехмельные очки! Если нужна пара, дай мне знать.','Голдарк Меткий Охотник попросил вас поймать 5 оглушенных зайцелопов с помощью особой сети. Он упомянул, что необходимо надеть cинтехмельные очки, чтобы их увидеть.','Что? Они действительно существуют!$B$BМне нужна минутка... и выпить...$B$B<Он делает глоток из своей кружки.>$B$BДумаю, я могу позволить тебе оставить одного...','Ты $Gбыл:была; достаточно $Gпьян:пьяна;, чтобы увидеть маленьких зайцелопов?','Вернитесь к Голдарку Меткому Охотнику в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поймать дикого зайцелопа!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну вот. Слышишь? Страшный шум в холмах. Это зайцелопы! Коварные звери так и прут на запах Хмельного фестиваля! Я хотел бы поймать парочку, да вот беда, ушиб ногу, мне их не догнать. Ты можешь мне помочь!$b$bВозьми сеть и накинь ее на мелких гадов. Принеси мне не меньше пяти, а уж за мной не заржавеет!$b$bАх, да, еще одно – чтобы увидеть зайцелопов, тебе придется использовать cинтехмельные очки! Если нужна пара, дай мне знать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Голдарк Меткий Охотник попросил вас поймать 5 оглушенных зайцелопов с помощью особой сети. Он упомянул, что необходимо надеть cинтехмельные очки, чтобы их увидеть.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Они действительно существуют!$B$BМне нужна минутка... и выпить...$B$B<Он делает глоток из своей кружки.>$B$BДумаю, я могу позволить тебе оставить одного...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gбыл:была; достаточно $Gпьян:пьяна;, чтобы увидеть маленьких зайцелопов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Голдарку Меткому Охотнику в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11118,'Розовые элекки на марше','Напиваться на Хмельном фестивале – почетная традиция и практически обязанность каждого участника! Но беда в том, что со всего Азерота идут жалобы – весь праздник портят галлюцинации! Так дело не пойдет!$b$bПроклятых элекков не берет обычное оружие – проходит сквозь них – так что возьми этот образчик гномьей инженерии, обойди все пивные дворики и уничтожь этих тварей.$b$bИ не забудь, чтобы их увидеть, надо надеть cинтехмельные очки! Если тебе они нужны, одолжи у меня.','Посетите пивные дворики рядом с Штормградом, Дарнасом и Экзодаром, истребите по три элекка в каждом из мест и возвращайтесь к Голдарку Меткому Охотнику. Чтобы увидеть розовых элекков, необходимо надеть синтехмельные очки.','Хорошая работа! Розовые элекки... что за нелепая мысль!','Эти надоедливые розовые пятнышки уже ушли?','Вернитесь к Голдарку Меткому Охотнику в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Розовые элекки на марше',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Напиваться на Хмельном фестивале – почетная традиция и практически обязанность каждого участника! Но беда в том, что со всего Азерота идут жалобы – весь праздник портят галлюцинации! Так дело не пойдет!$b$bПроклятых элекков не берет обычное оружие – проходит сквозь них – так что возьми этот образчик гномьей инженерии, обойди все пивные дворики и уничтожь этих тварей.$b$bИ не забудь, чтобы их увидеть, надо надеть cинтехмельные очки! Если тебе они нужны, одолжи у меня.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Посетите пивные дворики рядом с Штормградом, Дарнасом и Экзодаром, истребите по три элекка в каждом из мест и возвращайтесь к Голдарку Меткому Охотнику. Чтобы увидеть розовых элекков, необходимо надеть синтехмельные очки.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа! Розовые элекки... что за нелепая мысль!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти надоедливые розовые пятнышки уже ушли?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Голдарку Меткому Охотнику в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11119,'Налет на Лагерь Баш\'ира!','Эй, $gприятель:подруга;! Хочешь поразвлечься, а?$B$BКаждые пару часов мы, эфир-техи, совершаем налет на Лагерь Баш\'ира, там, далеко на северо-восток от Острогорья. Говорят, что мы "изучаем" тамошнюю хрустальную кузницу, но на самом-то деле это налет, и ничто иное. Нам хрустальная кузница нужна для дозаправки, да еще остается на продажу.$B$BИди-ка на посадочную площадку и переговори с учеником эфир-теха. Он тебе скажет, когда очередной вылет.','Поговорите с учеником эфир-теха на заставе Стражи Небес в Острогорье.','Ну, как бомбардировка?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Налет на Лагерь Баш\'ира!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, $gприятель:подруга;! Хочешь поразвлечься, а?$B$BКаждые пару часов мы, эфир-техи, совершаем налет на Лагерь Баш\'ира, там, далеко на северо-восток от Острогорья. Говорят, что мы "изучаем" тамошнюю хрустальную кузницу, но на самом-то деле это налет, и ничто иное. Нам хрустальная кузница нужна для дозаправки, да еще остается на продажу.$B$BИди-ка на посадочную площадку и переговори с учеником эфир-теха. Он тебе скажет, когда очередной вылет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с учеником эфир-теха на заставе Стражи Небес в Острогорье.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как бомбардировка?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11120,'Розовые элекки на марше','Ты $Gмолодец:умница;, $Gпарень:девушка;. Вот, возьми это в качестве оплаты за работу, которую ты $Gсделал:сделала;.','Ты $Gпрояснил:прояснила; ту маленькую проблему, о которой мы говорили?','Вернитесь к Глодраку Меткому Охотнику в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Розовые элекки на марше',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gмолодец:умница;, $Gпарень:девушка;. Вот, возьми это в качестве оплаты за работу, которую ты $Gсделал:сделала;.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпрояснил:прояснила; ту маленькую проблему, о которой мы говорили?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глодраку Меткому Охотнику в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11121,'ЕЖЕДНЕВНОЕ ИСПЫТАТЕЛЬНОЕ ЗАДАНИЕ (РЕЙД)','<NYI>Ищите <QUESTGIVER> в <LOCATION>. Она/он желает, чтобы вы помогли им в трудном деле.','Поговорите с <QUESTGIVER> в <AREA>.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ЕЖЕДНЕВНОЕ ИСПЫТАТЕЛЬНОЕ ЗАДАНИЕ (РЕЙД)',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<NYI>Ищите <QUESTGIVER> в <LOCATION>. Она/он желает, чтобы вы помогли им в трудном деле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с <QUESTGIVER> в <AREA>.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11122,'Туда и обратно','Мне нужны бочки! Чего ты ждешь?!','Вернитесь к Нейлу Рамштайну в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Туда и обратно',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужны бочки! Чего ты ждешь?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нейлу Рамштайну в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11123,'[DEPRECATED]Inspecting the Ruins','Бедняга Джеймс так и не оправился после пожара в "Последнем привале" и гибели семьи. Мы с ребятами делаем все, что в наших силах, чтобы найти ублюдков, ответственных за это.$B$BЯ послал нашего лучшего следователя, инспектора Тарема, на пепелище, но одному там не справиться. Если вы поможете Тарему, мы этого не забудем. Видит Свет, мы все хотели бы помочь.$B$BДо таверны можно дойти по главной дороге, только будьте поосторожнее. В такую глухомань мои патрули не заходят.','Поговорите с инспектором Таремом в таверне "Последний привал".','Приятно видеть, что капитан Ваймс наконец поручает это расследование.$B$BЯ использовал светоотражающий порошок, чтобы вытереть пыль. Он выявляет подозрительные объекты и отметки, помогая вам сосредоточить усилия. Посмотрите на все, что освещает пыль.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Inspecting the Ruins',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Бедняга Джеймс так и не оправился после пожара в "Последнем привале" и гибели семьи. Мы с ребятами делаем все, что в наших силах, чтобы найти ублюдков, ответственных за это.$B$BЯ послал нашего лучшего следователя, инспектора Тарема, на пепелище, но одному там не справиться. Если вы поможете Тарему, мы этого не забудем. Видит Свет, мы все хотели бы помочь.$B$BДо таверны можно дойти по главной дороге, только будьте поосторожнее. В такую глухомань мои патрули не заходят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с инспектором Таремом в таверне "Последний привал".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Приятно видеть, что капитан Ваймс наконец поручает это расследование.$B$BЯ использовал светоотражающий порошок, чтобы вытереть пыль. Он выявляет подозрительные объекты и отметки, помогая вам сосредоточить усилия. Посмотрите на все, что освещает пыль.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11124,'[DEPRECATED]Inspecting the Ruins','Если ты пойдешь по дороге на юг от деревни, а затем свернешь на запад к Степям, ты найдешь пепелище таверны "Последний привал".$B$BТерамор направил туда следователя, чтобы разобраться, с чего бы это вдруг таверна сгорела. У меня есть наблюдатель в тех местах, к тому же, я не очень верю в то, что людям удастся раскрыть, что же там произошло.$B$BЧто бы ты ни $gразузнал:разузнала;, не смей рассказывать об этом следователю. Мы сами со всем разберемся.','Расследуйте дело в таверне "Последний привал", что стоит на границе Степей и Пылевых топей.','Инспектор смотрит на вас с нескрываемым недоверием.\n\nМне сказали, что ты будешь... помогать в расследовании. Что же, хорошо.\n\nЯ обработал тут все вот этим порошком, чтобы узнать, кто напал на гостиницу. Он поможет выявить улики, связанные с эти нападением. Обследуй все, что покажется подозрительным.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Inspecting the Ruins',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты пойдешь по дороге на юг от деревни, а затем свернешь на запад к Степям, ты найдешь пепелище таверны "Последний привал".$B$BТерамор направил туда следователя, чтобы разобраться, с чего бы это вдруг таверна сгорела. У меня есть наблюдатель в тех местах, к тому же, я не очень верю в то, что людям удастся раскрыть, что же там произошло.$B$BЧто бы ты ни $gразузнал:разузнала;, не смей рассказывать об этом следователю. Мы сами со всем разберемся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Расследуйте дело в таверне "Последний привал", что стоит на границе Степей и Пылевых топей.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Инспектор смотрит на вас с нескрываемым недоверием.\n\nМне сказали, что ты будешь... помогать в расследовании. Что же, хорошо.\n\nЯ обработал тут все вот этим порошком, чтобы узнать, кто напал на гостиницу. Он поможет выявить улики, связанные с эти нападением. Обследуй все, что покажется подозрительным.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11125,'[PH] Новые внутренние земли – задание') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[PH] Новые внутренние земли – задание',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11126,'Чужой среди своих','Хорошо, что я встретила тебя, |3-6($c). Я прибыла в Терамор, чтобы помочь разобраться с проблемой дезертирства. Солдаты покидают свои посты, вражеские агенты проникли в город!$B$BОни распространяют лживую пропаганду, надеясь, что и другие присоединятся к ним! $B$BАгенты буквально повсюду – у всех сторожевых постов в городе и доках. Нужно их найти, выявить и дискредитировать! Пока мы не можем сделать большего, иначе только вызовем к ним больше доверия.','Прогоните 5 дезертиров-подстрекателей и вернитесь к докам Терамора к Калии Гастингс.','Очень хорошо, $n. Думаю, нам удалось застать их врасплох. Похоже, эти агенты считали себя в безопасности за городскими стенами.$B$BСо временем подстрекатели вернутся и снова будут распространять дезинформацию. А мы пока воспользуемся тем временем, что ты для нас выиграл, чтобы отогнать их как можно дальше.','Вы изгнали дезертиров из Терамора?','Вернитесь к Калии Гастингс на Остров Терамор, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чужой среди своих',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хорошо, что я встретила тебя, |3-6($c). Я прибыла в Терамор, чтобы помочь разобраться с проблемой дезертирства. Солдаты покидают свои посты, вражеские агенты проникли в город!$B$BОни распространяют лживую пропаганду, надеясь, что и другие присоединятся к ним! $B$BАгенты буквально повсюду – у всех сторожевых постов в городе и доках. Нужно их найти, выявить и дискредитировать! Пока мы не можем сделать большего, иначе только вызовем к ним больше доверия.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Прогоните 5 дезертиров-подстрекателей и вернитесь к докам Терамора к Калии Гастингс.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо, $n. Думаю, нам удалось застать их врасплох. Похоже, эти агенты считали себя в безопасности за городскими стенами.$B$BСо временем подстрекатели вернутся и снова будут распространять дезинформацию. А мы пока воспользуемся тем временем, что ты для нас выиграл, чтобы отогнать их как можно дальше.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы изгнали дезертиров из Терамора?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калии Гастингс на Остров Терамор, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11127,'<NYI>Тайны Громопойла','Я бы ни за что не стал воровать у моих кузенов Громоваров. Они отличные ребята. Но бизнес есть бизнес, порой приходится идти на крайние меры. Поэтому черную работу за меня делают другие.$b$bМрачнобух Громовар – это один придурок из этого семейства. Он живет к югу от Луноречья, в холмах Западного Края. Ходят слухи, что Мрачнобух придумал новый рецепт эля. Я хочу заполучить его еще до выхода продукта на рынок. Ты ведь сможешь его добыть? А уж за мной не заржавеет. Ячменовары всегда платят по счетам.','Украдите тайный рецепт Мрачнобуха из лагеря Мрачнобуха в Западном Крае и отнесите его Ячменовару на территории Хмельного фестиваля.','Вернитесь к Бекану Ячменовару в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI>Тайны Громопойла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я бы ни за что не стал воровать у моих кузенов Громоваров. Они отличные ребята. Но бизнес есть бизнес, порой приходится идти на крайние меры. Поэтому черную работу за меня делают другие.$b$bМрачнобух Громовар – это один придурок из этого семейства. Он живет к югу от Луноречья, в холмах Западного Края. Ходят слухи, что Мрачнобух придумал новый рецепт эля. Я хочу заполучить его еще до выхода продукта на рынок. Ты ведь сможешь его добыть? А уж за мной не заржавеет. Ячменовары всегда платят по счетам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Украдите тайный рецепт Мрачнобуха из лагеря Мрачнобуха в Западном Крае и отнесите его Ячменовару на территории Хмельного фестиваля.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бекану Ячменовару в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11128,'Пропагандистская война','Вражеские агенты не просто заводят случайные беседы со стражниками. Мы нашли множество листовок с призывом к дезертирству, которые эти агенты умудрились провезти на корабле в доки.$B$BКорабль, что привез листовки, еще стоит в Тераморе, в дальнем доке. Если бы тебе удалось проникнуть на борт и выкрасть оставшиеся пропагандистские листовки, то их агенты утратили бы свое самое мощное оружие. Осторожнее! Команда – опытные каперы. Груз, скорее всего, держат в капитанской каюте.','Доставьте дезертирскую пропаганду Калии Гастингс к докам в Тераморе.','Агент ШРУ одобрительно кивает. $B$BБлестяще. Остается только дискредитировать вражескую агентуру так, чтобы они больше в Терамор сунуться не смели, и на этот счет у меня созрел план.','Удалось ли найти и выкрасть оставшиеся листовки?','Вернитесь к Калии Гастингс на Остров Терамор, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропагандистская война',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вражеские агенты не просто заводят случайные беседы со стражниками. Мы нашли множество листовок с призывом к дезертирству, которые эти агенты умудрились провезти на корабле в доки.$B$BКорабль, что привез листовки, еще стоит в Тераморе, в дальнем доке. Если бы тебе удалось проникнуть на борт и выкрасть оставшиеся пропагандистские листовки, то их агенты утратили бы свое самое мощное оружие. Осторожнее! Команда – опытные каперы. Груз, скорее всего, держат в капитанской каюте.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте дезертирскую пропаганду Калии Гастингс к докам в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Агент ШРУ одобрительно кивает. $B$BБлестяще. Остается только дискредитировать вражескую агентуру так, чтобы они больше в Терамор сунуться не смели, и на этот счет у меня созрел план.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли найти и выкрасть оставшиеся листовки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калии Гастингс на Остров Терамор, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11129,'Пропал Кайл!','Помоги мне, $n! Мой любимый щенок Кайл сбежал! Я знаю, он потерялся и теперь бегает вокруг деревни Кровавого Копыта, голодный и несчастный.$B$BПожалуйста, отыщи его и покорми. Он поест, утешится и вернется домой.$B$BНо сначала надо найти для него еду. Его любимое блюдо – нежное мясо долгоногов. Отправляйся на восток, там их – хоть пруд пруди. Убей одного из них и принеси его сочное мясо Кайлу. Как увидишь Кайла в городе – предложи ему мясо, и он непременно подойдет к тебе.','Анаб Пшеничная Грива из деревни Кровавого Копыта в Мулгоре попросил найти его лучшего щенка, Кайла Бесноватого.$B$BПокормите Кайла нежным мясом долгонога и возвращайтесь к Анабу Пшеничной Гриве.','Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед…\n\nТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.','Вернитесь к Анабу Пшеничной Гриве в Мулгор.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропал Кайл!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помоги мне, $n! Мой любимый щенок Кайл сбежал! Я знаю, он потерялся и теперь бегает вокруг деревни Кровавого Копыта, голодный и несчастный.$B$BПожалуйста, отыщи его и покорми. Он поест, утешится и вернется домой.$B$BНо сначала надо найти для него еду. Его любимое блюдо – нежное мясо долгоногов. Отправляйся на восток, там их – хоть пруд пруди. Убей одного из них и принеси его сочное мясо Кайлу. Как увидишь Кайла в городе – предложи ему мясо, и он непременно подойдет к тебе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Анаб Пшеничная Грива из деревни Кровавого Копыта в Мулгоре попросил найти его лучшего щенка, Кайла Бесноватого.$B$BПокормите Кайла нежным мясом долгонога и возвращайтесь к Анабу Пшеничной Гриве.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лихорадка не оставляет меня ни днем, ни ночью, уже начинается бред... И зачем я связался со зверем, которого не смог одолеть мой дед…\n\nТы несешь мне ингредиенты для лекарства? Боюсь, если не остановить распространение инфекции, я могу умереть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Анабу Пшеничной Гриве в Мулгор.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11130,'Ой, блестяшечки!','Ходи сюда, $Gпарниша:лапуля;! Дай старине Жулю посмотреть на твои блестяшечки...$b$bХммм. Да-да, неплохо, но ты можешь добыть больше. Куда больше.$b$b*Жуль наклоняется к вам и шепчет.*$b$bСлавные блестяшечки – они повсюду, $n, только надо знать, где искать! Нынче тебе свезло так свезло – я знаю парня, который поможет тебе найти столько блестяшек, что и не унесешь.$b$bЗайди к моему старому приятелю, Бадду – он болтается близ Зул\'Амана, и покажи ему вот это. Он поймет, что тебя послал старый Жуль, и он тебя посвятит в свою затею.','Жуль хочет, чтобы вы взяли его записку и отнесли ее Бадду в Призрачные земли к Зул\'Аману.','Бадд читает записку.\n\nА, друг Жуля? Добро пожаловать!\n\nКак раз вовремя. По роковому стечению обстоятельств я недавно лишился своих партнеров. Настоящая трагедия, но большой выигрыш стоит больших затрат. Но лучше не думать о плохом!\n\nТы несомненно уже знаешь о моих бесчисленных изобретениях и открытиях, но все они ничто по сравнению вот с этим! Честно говоря, мы тут в Зул\'Амане, можно сказать, творим историю и, по велению судьбы, ты вступаешь в дело с самого начала!','<Бадд подозрительно смотрит на записку.>$B$BЧто у тебя там, $C?','Вернитесь к Бадду Недреку в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ой, блестяшечки!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходи сюда, $Gпарниша:лапуля;! Дай старине Жулю посмотреть на твои блестяшечки...$b$bХммм. Да-да, неплохо, но ты можешь добыть больше. Куда больше.$b$b*Жуль наклоняется к вам и шепчет.*$b$bСлавные блестяшечки – они повсюду, $n, только надо знать, где искать! Нынче тебе свезло так свезло – я знаю парня, который поможет тебе найти столько блестяшек, что и не унесешь.$b$bЗайди к моему старому приятелю, Бадду – он болтается близ Зул\'Амана, и покажи ему вот это. Он поймет, что тебя послал старый Жуль, и он тебя посвятит в свою затею.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Жуль хочет, чтобы вы взяли его записку и отнесли ее Бадду в Призрачные земли к Зул\'Аману.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бадд читает записку.\n\nА, друг Жуля? Добро пожаловать!\n\nКак раз вовремя. По роковому стечению обстоятельств я недавно лишился своих партнеров. Настоящая трагедия, но большой выигрыш стоит больших затрат. Но лучше не думать о плохом!\n\nТы несомненно уже знаешь о моих бесчисленных изобретениях и открытиях, но все они ничто по сравнению вот с этим! Честно говоря, мы тут в Зул\'Амане, можно сказать, творим историю и, по велению судьбы, ты вступаешь в дело с самого начала!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Бадд подозрительно смотрит на записку.>$B$BЧто у тебя там, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бадду Недреку в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11131,'Гаси пожар!','Вы должны помочь нам! Всадник без головы напал на деревню! Кругом пожар! Дети в опасности!$B$BПожалуйста, $n, помогите пожарной бригаде. Берите ведро и заливайте пожар или передавайте ведра по цепочке! Погасите пожар, и мы, может, еще спасемся!','Переодетая попечительница сирот просит вас помочь потушить пожар в деревне. Когда пожар будет потушен, снова поговорите с попечительницей сирот.','$N, ты $Gобещал:обещала; спасти детей!','Пожар потушен','Вернитесь к переодетой попечительнице сирот.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гаси пожар!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы должны помочь нам! Всадник без головы напал на деревню! Кругом пожар! Дети в опасности!$B$BПожалуйста, $n, помогите пожарной бригаде. Берите ведро и заливайте пожар или передавайте ведра по цепочке! Погасите пожар, и мы, может, еще спасемся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Переодетая попечительница сирот просит вас помочь потушить пожар в деревне. Когда пожар будет потушен, снова поговорите с попечительницей сирот.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, ты $Gобещал:обещала; спасти детей!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Пожар потушен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к переодетой попечительнице сирот.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11132,'Все обещаешь и обещаешь','Мои изыскания подтверждают слухи об огромном сокровище, спрятанном в Зул\'Амане. Там для каждого найдется своя гора золота с холмиком! Но сначала ты $gдолжен:должна; заработать свою долю в этом пироге.$b$bНаша первая попытка достать эти сокровища пошла не так гладко, как я надеялся. Фактически, моя карта и те неумехи, которым я ее вручил, пропали без вести. Они отправились за троллем по имени Налоракк.$b$bЗабудь об этих неудачниках, мне нужна карта! Добейся успеха и ты войдешь в историю как тот, кто помог Бадду Недреку раскрыть тайны Зул\'Амана.','Разыщите карту Бадда Недрека на террасе верховного шамана Налоракка в Зул\'Амане и верните ее хозяину.','<Бадд выглядит немного шокированным.>$B$BОй? Ты $Gнашел:нашла; ее?$B$BГм, я имел в виду, конечно она у тебя! Молодец, $C.$B$BПосмотрим, смогу ли я найти что-то хорошее для тебя... ааа... да, сделаем это.','Аааа да, $N, не так ли?$B$BТы еще не $Gвернул:вернула; мою карту?','Вернитесь к Бадду Недреку в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все обещаешь и обещаешь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои изыскания подтверждают слухи об огромном сокровище, спрятанном в Зул\'Амане. Там для каждого найдется своя гора золота с холмиком! Но сначала ты $gдолжен:должна; заработать свою долю в этом пироге.$b$bНаша первая попытка достать эти сокровища пошла не так гладко, как я надеялся. Фактически, моя карта и те неумехи, которым я ее вручил, пропали без вести. Они отправились за троллем по имени Налоракк.$b$bЗабудь об этих неудачниках, мне нужна карта! Добейся успеха и ты войдешь в историю как тот, кто помог Бадду Недреку раскрыть тайны Зул\'Амана.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разыщите карту Бадда Недрека на террасе верховного шамана Налоракка в Зул\'Амане и верните ее хозяину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Бадд выглядит немного шокированным.>$B$BОй? Ты $Gнашел:нашла; ее?$B$BГм, я имел в виду, конечно она у тебя! Молодец, $C.$B$BПосмотрим, смогу ли я найти что-то хорошее для тебя... ааа... да, сделаем это.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Аааа да, $N, не так ли?$B$BТы еще не $Gвернул:вернула; мою карту?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бадду Недреку в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11133,'Дискредитация вражеской агентуры','Я кое-что изменила в листовках, которые вы похитили у наших заклятых друзей в доках. Теперь любой, кто их прочтет, будет совершенно по-другому смотреть на них и их цели.$B$BЕсли мы подкинем побольше этих листовок страже, врагам будет очень нелегко снова угнездиться в наших стенах.$B$B<Калия вручает вам стопку подправленных листовок.> $B$BНе займетесь ли этим, пока я обдумываю очередной шаг?','Калия Гастингс просит вас всучить подправленные листовки 6 тераморским стражникам. После этого вернитесь к Калии и доложите о выполнении задания.','<Калия смеется, когда вы описываете реакцию охранников на пропаганду.>$B$BКак я и надеялась! Я думаю, можно с уверенностью сказать, что любые агенты-дезертиры, которые попытаются проникнуть в Терамор, будут смеяться прямо за городом!','Мне показалось, что из барака доносится смех. Вы раздавали те листовки, которые я вам дал?','Вернитесь к Калии Гастингс на Остров Терамор, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дискредитация вражеской агентуры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я кое-что изменила в листовках, которые вы похитили у наших заклятых друзей в доках. Теперь любой, кто их прочтет, будет совершенно по-другому смотреть на них и их цели.$B$BЕсли мы подкинем побольше этих листовок страже, врагам будет очень нелегко снова угнездиться в наших стенах.$B$B<Калия вручает вам стопку подправленных листовок.> $B$BНе займетесь ли этим, пока я обдумываю очередной шаг?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Калия Гастингс просит вас всучить подправленные листовки 6 тераморским стражникам. После этого вернитесь к Калии и доложите о выполнении задания.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Калия смеется, когда вы описываете реакцию охранников на пропаганду.>$B$BКак я и надеялась! Я думаю, можно с уверенностью сказать, что любые агенты-дезертиры, которые попытаются проникнуть в Терамор, будут смеяться прямо за городом!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне показалось, что из барака доносится смех. Вы раздавали те листовки, которые я вам дал?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калии Гастингс на Остров Терамор, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11134,'Конец вражеской пропаганде','Теперь, когда мы выжили вражеских подстрекателей из Терамора, пора закончить операцию. Мои местные осведомители доносят, что база вражеской агентуры находится на судне, вставшем на якорь у маленького острова к юго-востоку от доков.$B$BЕсли арестовать их лидера, Гависа Серого Щита, остальные сопротивляться не станут. Найдите его на борту и убедите сдаться. Скорее всего, для виду он немного побрыкается. Но когда поймет, что ему не светит, непременно покорится.','Арестуйте Гависа Серого Щита, затем доложитесь Калии Гастингс у доков Терамора.','Просьба Гэвиса не такая уж диковинная, как может показаться. При правильном обращении леди Джайна может вернуть дезертиров в лоно, но это, конечно, ее решение.$B$BБыло приятно работать с тобой, $N. Сомневаюсь, что без вашей помощи операция прошла бы так гладко. Когда я сделаю отчет в Штормграде, он назовет вас тем $C, который устранил угрозу дезертирства.','Вы завершили штурм базы дезертиров?','Вернитесь к Калии Гастингс на Остров Терамор, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Конец вражеской пропаганде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы выжили вражеских подстрекателей из Терамора, пора закончить операцию. Мои местные осведомители доносят, что база вражеской агентуры находится на судне, вставшем на якорь у маленького острова к юго-востоку от доков.$B$BЕсли арестовать их лидера, Гависа Серого Щита, остальные сопротивляться не станут. Найдите его на борту и убедите сдаться. Скорее всего, для виду он немного побрыкается. Но когда поймет, что ему не светит, непременно покорится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Арестуйте Гависа Серого Щита, затем доложитесь Калии Гастингс у доков Терамора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Просьба Гэвиса не такая уж диковинная, как может показаться. При правильном обращении леди Джайна может вернуть дезертиров в лоно, но это, конечно, ее решение.$B$BБыло приятно работать с тобой, $N. Сомневаюсь, что без вашей помощи операция прошла бы так гладко. Когда я сделаю отчет в Штормграде, он назовет вас тем $C, который устранил угрозу дезертирства.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы завершили штурм базы дезертиров?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Калии Гастингс на Остров Терамор, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11135,'Всадник без головы','Найдите святилище тыквы Всадника без головы.','Происхождение этой святыни неизвестно, но нет сомнений, кому она отдает дань уважения...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всадник без головы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите святилище тыквы Всадника без головы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Происхождение этой святыни неизвестно, но нет сомнений, кому она отдает дань уважения...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11136,'Тревожные события','Донесения наших патрулей в последнее время приобретают тревожный характер. В них говорится о людях в красных банданах Братства Справедливости, что появились на Побережье Мрака, к северу от стен Терамора.$B$BОбломки корабля, найденные в тех местах, говорят о том, что они могли попасть сюда в результате кораблекрушения, но у нас слишком мало информации. Капитан Ваймор на Сторожевом посту – сторожевой башне к северу от города – ждет помощи в расследовании.','Отрапортуйте капитану Ваймору на Сторожевом посту.','<Капитан не пытается скрыть, что оценивает ваши способности.>$B$BТак вы слышали о недавнем кораблекрушении у берегов? Хорошо, мне нужна помощь, чтобы подтвердить мои подозрения о выживших. Добро пожаловать на борт, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тревожные события',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Донесения наших патрулей в последнее время приобретают тревожный характер. В них говорится о людях в красных банданах Братства Справедливости, что появились на Побережье Мрака, к северу от стен Терамора.$B$BОбломки корабля, найденные в тех местах, говорят о том, что они могли попасть сюда в результате кораблекрушения, но у нас слишком мало информации. Капитан Ваймор на Сторожевом посту – сторожевой башне к северу от города – ждет помощи в расследовании.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отрапортуйте капитану Ваймору на Сторожевом посту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан не пытается скрыть, что оценивает ваши способности.>$B$BТак вы слышали о недавнем кораблекрушении у берегов? Хорошо, мне нужна помощь, чтобы подтвердить мои подозрения о выживших. Добро пожаловать на борт, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11137,'[DEPRECATED]Defias in Dustwallow?','Мои разведчики донесли о кораблекрушении на северо-востоке побережья. Кораблекрушения здесь – дело обычное, но донесения говорят о том, что выжившие носят красные банданы Братства Справедливости!$B$BОни ремесленники и цеховики, но не мореходы. Что они делают на месте кораблекрушения на континенте, который не представляет для них интереса?$B$BГоворят, их предводитель живет на большом острове недалеко от побережья, к северо-востоку от города. Убей его и принеси все документы, какие удастся найти.','Добудьте приказы Братства Справедливости у Гарна Маферса и принесите его капитану Ваймору на Сторожевой пост.','<Капитан Ваймор принимает от вас приказы и перечитывает их.>$B$BЧто вообще может означать «драгоценный груз»? Братство Справедливости провело небольшое время с контрабандой обратно в земли Штормграда, но, похоже, это не для их лиги. Язык этих орденов предполагает богатого или знатного покровителя.','Удалось ли вам выследить их лидера?','Вернитесь к капитану Ваймору на Сторожевой пост, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Defias in Dustwallow?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мои разведчики донесли о кораблекрушении на северо-востоке побережья. Кораблекрушения здесь – дело обычное, но донесения говорят о том, что выжившие носят красные банданы Братства Справедливости!$B$BОни ремесленники и цеховики, но не мореходы. Что они делают на месте кораблекрушения на континенте, который не представляет для них интереса?$B$BГоворят, их предводитель живет на большом острове недалеко от побережья, к северо-востоку от города. Убей его и принеси все документы, какие удастся найти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте приказы Братства Справедливости у Гарна Маферса и принесите его капитану Ваймору на Сторожевой пост.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан Ваймор принимает от вас приказы и перечитывает их.>$B$BЧто вообще может означать «драгоценный груз»? Братство Справедливости провело небольшое время с контрабандой обратно в земли Штормграда, но, похоже, это не для их лиги. Язык этих орденов предполагает богатого или знатного покровителя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли вам выследить их лидера?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Ваймору на Сторожевой пост, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11138,'[DEPRECATED]Renn McGill','Судя по формулировке добытого тобою приказа, создается впечатление, что первой целью Братства Справедливости будет найти и обезопасить тот самый непонятный груз.$B$BНа ШРУ в Тераморе одно время работал некий ныряльщик, занимавшийся подводными поисками, по имени Ренн Макжабр. Услышав о кораблекрушении, Ренн направился на север, чтобы заняться подводным поиском у острова, где нынче засело Братство Справедливости.$B$BЕсли мы хотим опередить бандитов, нам понадобится его помощь. Ищи Ренна в воде к северо-востоку от островка, прямо к северу от того большого острова, на котором ты уже $gуспел:успела; побывать.','Доставьте приказы Братства Справедливости Ренну Макжабру к Побережью Мрака.','<Ренн просматривает заказы.>$B$BИтак, на борту был ценный груз! Мы должны найти его, прежде чем Братство Справедливости вернет его. Эти ребята не дайверы, но нам понадобится их снаряжение, если вы поможете мне найти груз.','Добро пожаловать, $C. Что привело вас сюда?','Вернитесь к Ренну Макжабру на Зловещий берег, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Renn McGill',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по формулировке добытого тобою приказа, создается впечатление, что первой целью Братства Справедливости будет найти и обезопасить тот самый непонятный груз.$B$BНа ШРУ в Тераморе одно время работал некий ныряльщик, занимавшийся подводными поисками, по имени Ренн Макжабр. Услышав о кораблекрушении, Ренн направился на север, чтобы заняться подводным поиском у острова, где нынче засело Братство Справедливости.$B$BЕсли мы хотим опередить бандитов, нам понадобится его помощь. Ищи Ренна в воде к северо-востоку от островка, прямо к северу от того большого острова, на котором ты уже $gуспел:успела; побывать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте приказы Братства Справедливости Ренну Макжабру к Побережью Мрака.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ренн просматривает заказы.>$B$BИтак, на борту был ценный груз! Мы должны найти его, прежде чем Братство Справедливости вернет его. Эти ребята не дайверы, но нам понадобится их снаряжение, если вы поможете мне найти груз.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Добро пожаловать, $C. Что привело вас сюда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ренну Макжабру на Зловещий берег, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11139,'[DEPRECATED]Secondhand Diving Gear','Дно отсюда до Алькаца усыпано обломками кораблекрушений. Братство Справедливости уже наняло ныряльщиков, которые рыщут по соседству. Мы добудем их снаряжение, оденем тебя и начнем охоту, но сначала придется кое-что "позаимствовать".$B$BПоищи на этом острове ящик со снаряжением для подводного плавания и что-нибудь для его починки. Когда все найдешь, неси мне, и я за минуту подготовлю тебе костюмчик!','Принесите набор инструментов и поврежденное снаряжение подводника Ренну Макжабру в Пылевые топи.','Вау, это не в лучшей форме, чем я думал, а эти инструменты...$B$BНу, я сказал, что верну их в рабочее состояние для вас, так что мне лучше приступить к работе.','Посмотрим, что вам удалось «позаимствовать» у Братства Справедливости.','Вернитесь к Ренну Макжабру на Зловещий берег, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Secondhand Diving Gear',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дно отсюда до Алькаца усыпано обломками кораблекрушений. Братство Справедливости уже наняло ныряльщиков, которые рыщут по соседству. Мы добудем их снаряжение, оденем тебя и начнем охоту, но сначала придется кое-что "позаимствовать".$B$BПоищи на этом острове ящик со снаряжением для подводного плавания и что-нибудь для его починки. Когда все найдешь, неси мне, и я за минуту подготовлю тебе костюмчик!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите набор инструментов и поврежденное снаряжение подводника Ренну Макжабру в Пылевые топи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вау, это не в лучшей форме, чем я думал, а эти инструменты...$B$BНу, я сказал, что верну их в рабочее состояние для вас, так что мне лучше приступить к работе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Посмотрим, что вам удалось «позаимствовать» у Братства Справедливости.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ренну Макжабру на Зловещий берег, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11140,'[DEPRECATED]Recover the Cargo!','В общем, починил я тебе это снаряжение, так что некоторое время под водой продержишься. Но особо на него не рассчитывай.$B$BОбломки корабля разбросаны по дну – от самого восточного берега этого острова до Алькаца. Покуда хватит воздуха в водолазном шлеме, можешь искать под водой обломки между этим островом и Алькацом. Возьми этот набор для спасения имущества. Не подплывай слишком близко к Алькацу. Тамошние гидры – просто жуть!','Принесите 6 поднятых со дна сундуков Ренну Макжабру в Пылевые топи.','<Ренн перебирает содержимое найденных вами сейфов.>$B$BХорошая работа. А теперь посмотрим, есть ли здесь наш «драгоценный груз»...','Ваш поиск обломков показал что-нибудь о грузе Справедливости?','Вернитесь к Ренну Макжабру на Зловещий берег, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Recover the Cargo!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В общем, починил я тебе это снаряжение, так что некоторое время под водой продержишься. Но особо на него не рассчитывай.$B$BОбломки корабля разбросаны по дну – от самого восточного берега этого острова до Алькаца. Покуда хватит воздуха в водолазном шлеме, можешь искать под водой обломки между этим островом и Алькацом. Возьми этот набор для спасения имущества. Не подплывай слишком близко к Алькацу. Тамошние гидры – просто жуть!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 поднятых со дна сундуков Ренну Макжабру в Пылевые топи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ренн перебирает содержимое найденных вами сейфов.>$B$BХорошая работа. А теперь посмотрим, есть ли здесь наш «драгоценный груз»...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ваш поиск обломков показал что-нибудь о грузе Справедливости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ренну Макжабру на Зловещий берег, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11141,'[DEPRECATED]Jaina Must Know','Вы должны безотлагательно оповестить леди Джайну о том, что нам удалось узнать! Бандиты перевозили пленника, и мы не знаем, кто это и жив ли он или она до сих пор!$B$BНо в одном нет сомнений, $n. Эти бандюги в петлю по мелочам не полезут. Наверняка их пленник – очень важная персона. Леди Джайна должна знать об этом больше, чем кто-либо другой. Найди ее на вершине башни магов в центре Терамора.','Поговорите в Тераморе с леди Джайной Праудмур.','Вы и Ренн проделали отличную работу, раскрывая эту информацию и немедленно сообщая о ней. Теперь мы должны подтвердить ваши выводы. Если мы ошибаемся, последствия будут слишком велики.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Jaina Must Know',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы должны безотлагательно оповестить леди Джайну о том, что нам удалось узнать! Бандиты перевозили пленника, и мы не знаем, кто это и жив ли он или она до сих пор!$B$BНо в одном нет сомнений, $n. Эти бандюги в петлю по мелочам не полезут. Наверняка их пленник – очень важная персона. Леди Джайна должна знать об этом больше, чем кто-либо другой. Найди ее на вершине башни магов в центре Терамора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Тераморе с леди Джайной Праудмур.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы и Ренн проделали отличную работу, раскрывая эту информацию и немедленно сообщая о ней. Теперь мы должны подтвердить ваши выводы. Если мы ошибаемся, последствия будут слишком велики.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11142,'[DEPRECATED]Survey Alcaz Island','Похоже, догадка Ренна насчет острова Алькац оказалась верной. Нам надо обследовать этот остров, но, чтобы пробиться туда, потребуется целый вооруженный отряд.$B$BОборона Терамора сейчас не может позволить себе такую роскошь, поэтому я договорилась с Коссой Багровое Крыло, ученицей тераморского укротителя грифонов, чтобы она дала тебе одно из своих животных для обследования Алькаца с воздуха.$B$BТолько на острове Алькац можно найти намек на то, что Братство Справедливости причастно к похищению.','Поговорите с Коссой Багровое Крыло и возьмите одного из ее грифонов, чтобы обследовать остров Алькац. После выполнения поручения отрапортуйте леди Джайне Праудмур в Тераморе.','<Леди Джайна внимательно слушает, как вы докладываете о результатах аэрофотосъемки.> Рунический круг$B$BA, дракон? Братство Справедливости вступило в союз с НЕЙ? Предатель?$B$B<Леди Джайна успокаивается и готовится к объяснению.>','Исследуйте остров Алькац.','Вернитесь к леди Джайне Праудмур на Остров Терамор, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Survey Alcaz Island',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, догадка Ренна насчет острова Алькац оказалась верной. Нам надо обследовать этот остров, но, чтобы пробиться туда, потребуется целый вооруженный отряд.$B$BОборона Терамора сейчас не может позволить себе такую роскошь, поэтому я договорилась с Коссой Багровое Крыло, ученицей тераморского укротителя грифонов, чтобы она дала тебе одно из своих животных для обследования Алькаца с воздуха.$B$BТолько на острове Алькац можно найти намек на то, что Братство Справедливости причастно к похищению.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Коссой Багровое Крыло и возьмите одного из ее грифонов, чтобы обследовать остров Алькац. После выполнения поручения отрапортуйте леди Джайне Праудмур в Тераморе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Леди Джайна внимательно слушает, как вы докладываете о результатах аэрофотосъемки.> Рунический круг$B$BA, дракон? Братство Справедливости вступило в союз с НЕЙ? Предатель?$B$B<Леди Джайна успокаивается и готовится к объяснению.>',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Исследуйте остров Алькац.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к леди Джайне Праудмур на Остров Терамор, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11143,'[DEPRECATED]A Grim Connection','Я говорил с инспектором Таремом по поводу информации, добытой вами в развалинах таверны "Последний привал". Похоже, он уверен, что следы копыт и найденный вами там щит указывают на тауренский клан Зловещий Тотем.$B$BС учетом донесений об их активности на болотах, это вряд ли можно считать простым совпадением. Я отправляю тебя к капитану Дариллу, он у нас что-то вроде специалиста по делам этого клана. Ступай по дороге на север из города к Северной башне. Это вторая застава на дороге.','Отрапортуйте капитану Дариллу в Северной башне.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]A Grim Connection',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я говорил с инспектором Таремом по поводу информации, добытой вами в развалинах таверны "Последний привал". Похоже, он уверен, что следы копыт и найденный вами там щит указывают на тауренский клан Зловещий Тотем.$B$BС учетом донесений об их активности на болотах, это вряд ли можно считать простым совпадением. Я отправляю тебя к капитану Дариллу, он у нас что-то вроде специалиста по делам этого клана. Ступай по дороге на север из города к Северной башне. Это вторая застава на дороге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отрапортуйте капитану Дариллу в Северной башне.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11144,'[DEPRECATED]Confirming the Suspicion','Пусть Зловещий Тотем и самое воинственное из тауренских племен, в организованности им не откажешь. Если таверну "Последний привал" подожгли действительно они, приказ об этом мог отдать лишь один из старейшин племени.$B$BНа северо-западе находится одно крупное поселение Зловещего Тотема, деревня Черного Копыта. Она служит им базой для нападений на нашу башню, но я готов поспорить, что там ты найдешь нужную информацию. Планы нападения должны были сохраниться у старейшин деревни.','Принесите боевой план племени Зловещий Тотем капитану Дариллу в Северную башню.','Вернитесь к капитану Дариллу в Северную башню, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Confirming the Suspicion',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пусть Зловещий Тотем и самое воинственное из тауренских племен, в организованности им не откажешь. Если таверну "Последний привал" подожгли действительно они, приказ об этом мог отдать лишь один из старейшин племени.$B$BНа северо-западе находится одно крупное поселение Зловещего Тотема, деревня Черного Копыта. Она служит им базой для нападений на нашу башню, но я готов поспорить, что там ты найдешь нужную информацию. Планы нападения должны были сохраниться у старейшин деревни.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите боевой план племени Зловещий Тотем капитану Дариллу в Северную башню.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Дариллу в Северную башню, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11145,'[DEPRECATED]Prisoners of the Grimtotems','Мы делаем все возможное, чтобы припереть к стенке этих налетчиков из племени Зловещего Тотема, но они продолжают нападать на город. Хуже того – они умудряются обнаруживать и захватывать в плен патрули, которые капитан посылает вести разведку и охранять дорогу.$B$BДумаю, что пленников держат в деревне Черного Копыта, что к северо-западу отсюда. Насколько мне известны повадки этих тауренов, наверняка ключи от камер пленников держат при себе охранники деревни. Мне все равно, что ты будешь делать, |3-6($c), просто спаси моих людей.','Сержант Лукас из Северной башни просит вас спасти 5 тераморских пленников.','Освобожденные пленники уже начали возвращаться из деревни Черного Копыта. Информация, которую капитан получает от пленников, даст нам преимущество в нашей следующей битве против Зловещих Тотемов.$B$BМоя благодарность вам и людям.','Удалось ли вам освободить пленников в деревне Черного Копыта?','Вернитесь к сержанту Лукасу в Северную башню, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Prisoners of the Grimtotems',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы делаем все возможное, чтобы припереть к стенке этих налетчиков из племени Зловещего Тотема, но они продолжают нападать на город. Хуже того – они умудряются обнаруживать и захватывать в плен патрули, которые капитан посылает вести разведку и охранять дорогу.$B$BДумаю, что пленников держат в деревне Черного Копыта, что к северо-западу отсюда. Насколько мне известны повадки этих тауренов, наверняка ключи от камер пленников держат при себе охранники деревни. Мне все равно, что ты будешь делать, |3-6($c), просто спаси моих людей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сержант Лукас из Северной башни просит вас спасти 5 тераморских пленников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Освобожденные пленники уже начали возвращаться из деревни Черного Копыта. Информация, которую капитан получает от пленников, даст нам преимущество в нашей следующей битве против Зловещих Тотемов.$B$BМоя благодарность вам и людям.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли вам освободить пленников в деревне Черного Копыта?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Лукасу в Северную башню, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11146,'[DEPRECATED]Raptor Captor','Полоса болот к северо-востоку отсюда – гнездо особенно мерзких ящеров. Из-за них мы потеряли уже не одного беспечного солдата, и у меня появилась мысль натравить зверей на наших соседей из клана Зловещего Тотема.$B$BВозьми эту веревку и поймай с ее помощью несколько ящеров Кровавой Топи или крикунов Кровавой Топи. Впрочем, я бы не стал пытаться ловить этих тварей, пока не удастся хотя бы немного ослабить их в бою. А бой будет нешуточный.','Сержант Лукас из Северной башни просит вас поймать 6 ящеров. Вы можете ловить как ящеров Кровавой Топи, так и крикунов Кровавой Топи.','Вы выглядите немного поцарапанным, но ничего серьезного. Ты определенно в гораздо лучшей форме, чем будут Зловещие Тотемы, когда наши новые друзья-хищники покончат с ними.','Ты поймал этих хищников?','Вернитесь к сержанту Лукасу в Северную башню, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Raptor Captor',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Полоса болот к северо-востоку отсюда – гнездо особенно мерзких ящеров. Из-за них мы потеряли уже не одного беспечного солдата, и у меня появилась мысль натравить зверей на наших соседей из клана Зловещего Тотема.$B$BВозьми эту веревку и поймай с ее помощью несколько ящеров Кровавой Топи или крикунов Кровавой Топи. Впрочем, я бы не стал пытаться ловить этих тварей, пока не удастся хотя бы немного ослабить их в бою. А бой будет нешуточный.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сержант Лукас из Северной башни просит вас поймать 6 ящеров. Вы можете ловить как ящеров Кровавой Топи, так и крикунов Кровавой Топи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы выглядите немного поцарапанным, но ничего серьезного. Ты определенно в гораздо лучшей форме, чем будут Зловещие Тотемы, когда наши новые друзья-хищники покончат с ними.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты поймал этих хищников?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Лукасу в Северную башню, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11147,'[DEPRECATED]Unleash the Raptors','Теперь, когда у нас есть ящеры, следующий наш шаг – "уговорить" их напасть на неугодное нам племя в деревне Черного Копыта к северо-западу отсюда.$B$BУ меня тут осталось немного вырезки из... неважно, из кого. Это будет твоя приманка. Положи ее на землю у ветряной мельницы посреди деревни. А об остальном позаботятся ящеры, по крайней мере, я на это надеюсь.','Сержант Лукас из Северной башни хочет, чтобы вы положили приманку на ящера близ ветряной мельницы в деревне Черного Копыта.','<Сержант не пытается скрыть ухмылку.>$B$BХорошо. Это должно предотвратить один или два рейда.','Вы выпустили хищников в деревне Черного Копыта?','Вернитесь к сержанту Лукасу в Северную башню, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Unleash the Raptors',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у нас есть ящеры, следующий наш шаг – "уговорить" их напасть на неугодное нам племя в деревне Черного Копыта к северо-западу отсюда.$B$BУ меня тут осталось немного вырезки из... неважно, из кого. Это будет твоя приманка. Положи ее на землю у ветряной мельницы посреди деревни. А об остальном позаботятся ящеры, по крайней мере, я на это надеюсь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сержант Лукас из Северной башни хочет, чтобы вы положили приманку на ящера близ ветряной мельницы в деревне Черного Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Сержант не пытается скрыть ухмылку.>$B$BХорошо. Это должно предотвратить один или два рейда.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы выпустили хищников в деревне Черного Копыта?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Лукасу в Северную башню, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11148,'[DEPRECATED]Arms of the Grimtotems','Если снаряжение, которое ты $gобнаружил:обнаружила; в развалинах таверны, принадлежало воинам Зловещего Тотема, то наверняка в их лагере к северо-западу отсюда найдется еще больше.$B$BНам не удалось собрать достаточно информации о деревне Черного Копыта, но, судя по численности нападавшего отряда, там базируются значительные силы.$B$BСделай все, чтобы заполучить их снаряжение и сравнить с найденным в развалинах таверны.','Капитан Дарилл из Северной башни хочет, чтобы вы принесли ему 7 предметов вооружения из деревни Черного Копыта.','Вернитесь к капитану Дариллу в Северную башню, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Arms of the Grimtotems',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если снаряжение, которое ты $gобнаружил:обнаружила; в развалинах таверны, принадлежало воинам Зловещего Тотема, то наверняка в их лагере к северо-западу отсюда найдется еще больше.$B$BНам не удалось собрать достаточно информации о деревне Черного Копыта, но, судя по численности нападавшего отряда, там базируются значительные силы.$B$BСделай все, чтобы заполучить их снаряжение и сравнить с найденным в развалинах таверны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Дарилл из Северной башни хочет, чтобы вы принесли ему 7 предметов вооружения из деревни Черного Копыта.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Дариллу в Северную башню, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11149,'[DEPRECATED]Tabetha\'s Assistance','Я не могу выделить никого в помощь второй заставе клана Зловещего Тотема, но, кажется, знаю, кто может помочь вам. $B$BВ самом сердце Трясины, к югу отсюда, находится маленькая усадьба, владеет которой Табета. Она может показаться просто старой отшельницей, но на самом деле она волшебница и провидица, причем небезызвестная. Идите по дороге на юг до ее усадьбы и попросите помощи в поиске тех, кто ответственен за резню в таверне "Последний привал".','Поговорите с Табетой в ее усадьбе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Tabetha\'s Assistance',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не могу выделить никого в помощь второй заставе клана Зловещего Тотема, но, кажется, знаю, кто может помочь вам. $B$BВ самом сердце Трясины, к югу отсюда, находится маленькая усадьба, владеет которой Табета. Она может показаться просто старой отшельницей, но на самом деле она волшебница и провидица, причем небезызвестная. Идите по дороге на юг до ее усадьбы и попросите помощи в поиске тех, кто ответственен за резню в таверне "Последний привал".',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Табетой в ее усадьбе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11150,'[DEPRECATED]Raze Direhorn Post!','Незачем гадать, чтобы увидеть угрозу, которая исходит от моих "соседей". И если это та самая банда, что сожгла "Последний привал", как ты говоришь, то нужно действовать немедля.$B$BБери вот этот факел и предай их лагерь огню! Ты найдешь заставу Дикого Рога к северу от моей усадьбы, возле дороги. Пропустить ее совершенно невозможно, эти варвары уже успели наставить вокруг свои драгоценные тотемы.','Сожгите северный, восточный и северо-западный шатры на заставе Дикого Рога, затем вернитесь в усадьбу Табеты.','Вернитесь к Табете на ферму, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Raze Direhorn Post!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Незачем гадать, чтобы увидеть угрозу, которая исходит от моих "соседей". И если это та самая банда, что сожгла "Последний привал", как ты говоришь, то нужно действовать немедля.$B$BБери вот этот факел и предай их лагерь огню! Ты найдешь заставу Дикого Рога к северу от моей усадьбы, возле дороги. Пропустить ее совершенно невозможно, эти варвары уже успели наставить вокруг свои драгоценные тотемы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите северный, восточный и северо-западный шатры на заставе Дикого Рога, затем вернитесь в усадьбу Табеты.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на ферму, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11151,'[DEPRECATED]Justice for the Hyals','Хотя, по мне, этот Зловещий Тотем – мухи надоедливые, не более, капитан Ваймс пожелает узнать о ваших делах. Отнесите ему известие, что вы выследили тех, кто замешан в сожжении таверны "Последний привал", и разобрались с ними.$B$BСемье Джима Хьяля это уже не поможет, но хоть в Зловещем Тотеме сто раз подумают, прежде чем лезть на тех, кого защищает Терамор.','Поговорите с капитаном Гарраном Ваймсом в Цитадели в Тераморе.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Justice for the Hyals',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя, по мне, этот Зловещий Тотем – мухи надоедливые, не более, капитан Ваймс пожелает узнать о ваших делах. Отнесите ему известие, что вы выследили тех, кто замешан в сожжении таверны "Последний привал", и разобрались с ними.$B$BСемье Джима Хьяля это уже не поможет, но хоть в Зловещем Тотеме сто раз подумают, прежде чем лезть на тех, кого защищает Терамор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Гарраном Ваймсом в Цитадели в Тераморе.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11152,'[DEPRECATED]Peace at Last','Как бы дать знать жене и сыну Джеймса Хьяля, что мы отомстили их убийцам?$B$B*Капитан Ваймс достает маленький венок.*$B$BГоворят, что души все видят, даже если мы и не можем говорить с ними. Это малость, но если бы вы возложили этот венок на могилу семейства Хьяль, я был бы вам очень благодарен. Это один из самых больших могильных памятников на кладбище к северу от ворот Терамора.','Капитан Гарран Ваймс из Цитадели хочет, чтобы вы возложили венок к памятнику семейства Хьяль.','Вернитесь к капитану Гаррану Ваймсу в Цитадель, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Peace at Last',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как бы дать знать жене и сыну Джеймса Хьяля, что мы отомстили их убийцам?$B$B*Капитан Ваймс достает маленький венок.*$B$BГоворят, что души все видят, даже если мы и не можем говорить с ними. Это малость, но если бы вы возложили этот венок на могилу семейства Хьяль, я был бы вам очень благодарен. Это один из самых больших могильных памятников на кладбище к северу от ворот Терамора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Гарран Ваймс из Цитадели хочет, чтобы вы возложили венок к памятнику семейства Хьяль.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Гаррану Ваймсу в Цитадель, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11153,'Прорвать блокаду','Все наши корабли затоплены! Нам нужна твоя помощь, чтобы прорваться сквозь пиратскую блокаду в Пролив Кораблекрушений!$B$BВозьми эти кассетные бомбы и садись на дирижабль, который "одолжил" нам Боронайзер. На нем ты пролетишь прямо над палубами этих проклятых пиратов и раздашь им наши подарочки!$B$BТы – наша последняя надежда прорвать блокаду. Надеюсь, тебе удастся разнести их корабли в мелкие щепки!','Возьмите кассетные бомбы Петрова и сбросьте их на корабли, убив 25 матросов абордажной команды и уничтожив 10 абордажных пушек. Как только задание будет выполнено, вернитесь к бомбардиру Петрову в Крепость Западной Стражи.','Именно это я и надеялся услышать! А ты знаешь, что надо делать, $N!$B$BМожет быть, ты заглянешь завтра, когда мы изготовим новую партию бомб? Я бы не стал так долго ждать, но у меня кончилось гуано летучих мышей, а мой помощник Фекнат куда-то запропастился.$B$BИнтересно, что его так задержало?','Мы снова говорим? Это должно означать, что ты это $Gсделал:сделала;! Ты кое-что $Gпоказал:показала; этим гнилым пиратам Северного моря!','Вернитесь к бомбардиру Петрову в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прорвать блокаду',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все наши корабли затоплены! Нам нужна твоя помощь, чтобы прорваться сквозь пиратскую блокаду в Пролив Кораблекрушений!$B$BВозьми эти кассетные бомбы и садись на дирижабль, который "одолжил" нам Боронайзер. На нем ты пролетишь прямо над палубами этих проклятых пиратов и раздашь им наши подарочки!$B$BТы – наша последняя надежда прорвать блокаду. Надеюсь, тебе удастся разнести их корабли в мелкие щепки!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите кассетные бомбы Петрова и сбросьте их на корабли, убив 25 матросов абордажной команды и уничтожив 10 абордажных пушек. Как только задание будет выполнено, вернитесь к бомбардиру Петрову в Крепость Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Именно это я и надеялся услышать! А ты знаешь, что надо делать, $N!$B$BМожет быть, ты заглянешь завтра, когда мы изготовим новую партию бомб? Я бы не стал так долго ждать, но у меня кончилось гуано летучих мышей, а мой помощник Фекнат куда-то запропастился.$B$BИнтересно, что его так задержало?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы снова говорим? Это должно означать, что ты это $Gсделал:сделала;! Ты кое-что $Gпоказал:показала; этим гнилым пиратам Северного моря!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бомбардиру Петрову в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11154,'Пусть обделаются от страха!','Эй, ты! Да, ты... иди сюда, мне нужна твоя помощь!$B$BПетров послал меня сюда собирать гуано летучих мышей для кассетных бомб, которые он мастерит в крепости, но я не собираюсь соваться прямо в лапы смерти!$B$BКороче, темнолапые летучие мыши водятся только на Вырубках к северу отсюда, но с этой платформы я сойду только в направлении дома!$B$BА вот ты... ты можешь совершить этот подвиг ради меня! Правда? Ну пожалуйста!!!$B$BВот, держи хлопушки. Основная мысль такова: бросаешь их рядом с летучими мышами, и они гадят от страха!','Соберите 10 кусков гуано темнолапых летучих мышей и отнесите их инженеру Фекнату к Стальным воротам.','Вернитесь к инженеру Фекнату к Стальным воротам, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть обделаются от страха!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, ты! Да, ты... иди сюда, мне нужна твоя помощь!$B$BПетров послал меня сюда собирать гуано летучих мышей для кассетных бомб, которые он мастерит в крепости, но я не собираюсь соваться прямо в лапы смерти!$B$BКороче, темнолапые летучие мыши водятся только на Вырубках к северу отсюда, но с этой платформы я сойду только в направлении дома!$B$BА вот ты... ты можешь совершить этот подвиг ради меня! Правда? Ну пожалуйста!!!$B$BВот, держи хлопушки. Основная мысль такова: бросаешь их рядом с летучими мышами, и они гадят от страха!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 кусков гуано темнолапых летучих мышей и отнесите их инженеру Фекнату к Стальным воротам.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к инженеру Фекнату к Стальным воротам, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11155,'Снова суп из черпорога?','После всех этих таинственных исчезновений домашнего скота нам не мешало бы озаботиться припасами. Иначе хищные звери станут нашей последней заботой!$B$BПоскольку я тут несколько занята приготовлением пищи, тебе придется отправиться на восток и поохотиться на черпорогов. Именно их нежное мясо я хочу сегодня приготовить. $B$BСмотри, не попадись им на рога!','Шеф-повар Дымкотел поручила вам добыть 6 кусков мяса черпорогов и принести их ей в Крепость Западной Стражи.','Нет ничего вкуснее нежного мяса черпорога, срезанного с боков!','Вернитесь к шеф-повару Дымкотелу в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Снова суп из черпорога?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','После всех этих таинственных исчезновений домашнего скота нам не мешало бы озаботиться припасами. Иначе хищные звери станут нашей последней заботой!$B$BПоскольку я тут несколько занята приготовлением пищи, тебе придется отправиться на восток и поохотиться на черпорогов. Именно их нежное мясо я хочу сегодня приготовить. $B$BСмотри, не попадись им на рога!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Шеф-повар Дымкотел поручила вам добыть 6 кусков мяса черпорогов и принести их ей в Крепость Западной Стражи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нет ничего вкуснее нежного мяса черпорога, срезанного с боков!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к шеф-повару Дымкотелу в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11156,'[DEPRECATED]Direhorn Raiders','Клан Зловещего Тотема там, на заставе Дикого Рога, наглеет день ото дня. По ночам часто слышно, как они горланят песни о своих деяниях против тех, кто пытается тут осесть.$B$BОни твердо намерены выгнать нас из усадьбы Табеты, хотя она тут воспитала целое поколение учеников. Мы защищали усадьбу как могли, но ученик Гарион во время последнего налета был ранен.$B$BСтупай на заставу Дикого Рога и убей всех Зловещих Тотемов, каких встретишь! Нападения надо остановить.','Убейте 12 тауренов из клана Зловещего Тотема с заставы Дикого Рога и вернитесь к ученику Морланну в усадьбу Табеты.','Ученик Морланн кивает.\n\nХорошо. Не думаю, что я буду о них скучать. В конце концов в центре болота можно ожидать некоторого уединения?','Удалось ли вам остановить атаки Зловещего Тотема?','Вернитесь к ученику Морланну на ферму, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Direhorn Raiders',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клан Зловещего Тотема там, на заставе Дикого Рога, наглеет день ото дня. По ночам часто слышно, как они горланят песни о своих деяниях против тех, кто пытается тут осесть.$B$BОни твердо намерены выгнать нас из усадьбы Табеты, хотя она тут воспитала целое поколение учеников. Мы защищали усадьбу как могли, но ученик Гарион во время последнего налета был ранен.$B$BСтупай на заставу Дикого Рога и убей всех Зловещих Тотемов, каких встретишь! Нападения надо остановить.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 12 тауренов из клана Зловещего Тотема с заставы Дикого Рога и вернитесь к ученику Морланну в усадьбу Табеты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ученик Морланн кивает.\n\nХорошо. Не думаю, что я буду о них скучать. В конце концов в центре болота можно ожидать некоторого уединения?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли вам остановить атаки Зловещего Тотема?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Морланну на ферму, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11157,'В тисках зла','$n, такое поручение я могу доверить только тебе. Нужно уничтожить яйца протодраконов и детенышей протодраконов в горящем лесу на юго-востоке! $B$BС тех пор, как мы прибыли сюда, в Пылающем Гнездовье не стихают пожары. Должно быть, это результат действия какой-то ужасной магии. В последнее время ситуация ухудшилась, и мои люди опасаются, что в ближайшие несколько недель мы все окажемся в огненной ловушке!$B$BОтправляйся туда и устрани угрозу, уничтожив яйца и детенышей протодраконов.','Уничтожьте 15 яиц протодраконов и 15 детенышей протодраконов, после чего вернитесь к капитану Адамсу в Крепость Западной Стражи.','Ну надо же! Если нам повезет, эти чудовища испугаются за своих детенышей и отступят, остановив распространение магического огня.$B$BПогоди... что это за звук? Похоже на хлопанье крыльев.','Как продвигаются ваши усилия?','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В тисках зла',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, такое поручение я могу доверить только тебе. Нужно уничтожить яйца протодраконов и детенышей протодраконов в горящем лесу на юго-востоке! $B$BС тех пор, как мы прибыли сюда, в Пылающем Гнездовье не стихают пожары. Должно быть, это результат действия какой-то ужасной магии. В последнее время ситуация ухудшилась, и мои люди опасаются, что в ближайшие несколько недель мы все окажемся в огненной ловушке!$B$BОтправляйся туда и устрани угрозу, уничтожив яйца и детенышей протодраконов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 яиц протодраконов и 15 детенышей протодраконов, после чего вернитесь к капитану Адамсу в Крепость Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну надо же! Если нам повезет, эти чудовища испугаются за своих детенышей и отступят, остановив распространение магического огня.$B$BПогоди... что это за звук? Похоже на хлопанье крыльев.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как продвигаются ваши усилия?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11158,'[DEPRECATED]Bloodfen Feathers','Что, боишься Брогга, малютка |3-6($r)? Не бойся. Гоблины Шестермути друзья Броггу, да и ты можешь с ним подружиться.$B$BБрогг ушел из Деревни Гиблотопь, когда новый вождь не стал мстить черным драконам, которые разрушили дом Брогга и убили много его старых друзей. Брогг пришел сюда, чтобы упокоить души убитых друзей и отомстить за них, но ему нужна помощь. Для обряда Броггу нужны магические перья – как те, что носят ящеры логова Кровавой Топи, что к западу от города.','Принесите 5 перьев Кровавой Топи Броггу в Шестермуть.','Брогг принимает перья.\n\nБрогг рад этим перьям. Очень сильная магия. Брогг не знает, что делают ящеры для придания силы перьям, но для обряда лучше не сыскать.','Брогг с надеждой смотрит на вас.\n\nТы принес Броггу перья?','Вернитесь к Броггу в Шестермуть, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Bloodfen Feathers',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что, боишься Брогга, малютка |3-6($r)? Не бойся. Гоблины Шестермути друзья Броггу, да и ты можешь с ним подружиться.$B$BБрогг ушел из Деревни Гиблотопь, когда новый вождь не стал мстить черным драконам, которые разрушили дом Брогга и убили много его старых друзей. Брогг пришел сюда, чтобы упокоить души убитых друзей и отомстить за них, но ему нужна помощь. Для обряда Броггу нужны магические перья – как те, что носят ящеры логова Кровавой Топи, что к западу от города.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 перьев Кровавой Топи Броггу в Шестермуть.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Брогг принимает перья.\n\nБрогг рад этим перьям. Очень сильная магия. Брогг не знает, что делают ящеры для придания силы перьям, но для обряда лучше не сыскать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Брогг с надеждой смотрит на вас.\n\nТы принес Броггу перья?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Броггу в Шестермуть, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11159,'[DEPRECATED]Spirits of Stonemaul Hold','Брогг закончил тотем, который принесет покой душам его друзей. Когда пришли дракониды, они убили всех в клане Каменных Молотов, кто не успел убежать. Броггу и властителю Мок\'Морокку удалось скрыться. Вместе с другими выжившими они планировали напасть на драконидов.$B$BОднако этого так и не произошло, и теперь духи мертвых клана Каменного Молота не дают покоя Броггу и остальным. Отнеси этот тотем на север, к руинам Деревни Каменного Молота, и поставь рядом со скелетами огров, чтобы привлечь к себе духов. Победи духов, чтобы дать им успокоение.','Брогг из Шестермути просит вас дать покой 10 духам клана Каменного Молота.','Брогг говорит тебе спасибо за помощь, хотя он знает, что властитель Мок\'Морокк тебе спасибо не скажет. Но теперь оставшиеся огры Каменного Молота смогут заняться делами живых и оставить мертвых в покое. Броггу осталось сделать только одно дело.','Броггу надо знать, дал ли ты покой жестоким духам Каменного Молота?','Вернитесь к Броггу в Шестермуть, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Spirits of Stonemaul Hold',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Брогг закончил тотем, который принесет покой душам его друзей. Когда пришли дракониды, они убили всех в клане Каменных Молотов, кто не успел убежать. Броггу и властителю Мок\'Морокку удалось скрыться. Вместе с другими выжившими они планировали напасть на драконидов.$B$BОднако этого так и не произошло, и теперь духи мертвых клана Каменного Молота не дают покоя Броггу и остальным. Отнеси этот тотем на север, к руинам Деревни Каменного Молота, и поставь рядом со скелетами огров, чтобы привлечь к себе духов. Победи духов, чтобы дать им успокоение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Брогг из Шестермути просит вас дать покой 10 духам клана Каменного Молота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Брогг говорит тебе спасибо за помощь, хотя он знает, что властитель Мок\'Морокк тебе спасибо не скажет. Но теперь оставшиеся огры Каменного Молота смогут заняться делами живых и оставить мертвых в покое. Броггу осталось сделать только одно дело.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Броггу надо знать, дал ли ты покой жестоким духам Каменного Молота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Броггу в Шестермуть, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11160,'[DEPRECATED]Banner of the Stonemaul','Когда пришли драконы и отняли старый дом Брогга, огры Каменного Молота бежали и все бросили, даже знамя клана.$B$BБрогг знает, что знамя хранится глубоко в могильном кургане огров Каменного Молота, но теперь он зовется Огненное логово. Брогг должен получить клановое знамя, чтобы отомстить драконам, которые убили его друзей.$B$BДревний курган клана Брогга, Огненное логово, кишащее драконидами, находится на северо-западе от Шестермути. Знамя глубоко в пещере. Будь осторожнее, $n.','Добудьте знамя Каменного Молота и принесите его Броггу в Шестермуть.','Ты принес знамя Каменного Молота?','Вернитесь к Броггу в Шестермуть, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Banner of the Stonemaul',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда пришли драконы и отняли старый дом Брогга, огры Каменного Молота бежали и все бросили, даже знамя клана.$B$BБрогг знает, что знамя хранится глубоко в могильном кургане огров Каменного Молота, но теперь он зовется Огненное логово. Брогг должен получить клановое знамя, чтобы отомстить драконам, которые убили его друзей.$B$BДревний курган клана Брогга, Огненное логово, кишащее драконидами, находится на северо-западе от Шестермути. Знамя глубоко в пещере. Будь осторожнее, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте знамя Каменного Молота и принесите его Броггу в Шестермуть.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес знамя Каменного Молота?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Броггу в Шестермуть, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11161,'[DEPRECATED]The Essence of Enmity','Чтобы сделать тотем для обряда, Броггу надо получить сущность тех тварей, что убили его друзей. Ненависть и злоба врагов Брогга будет питать пламя его мести.$B$BВыследи Огнегривых пеплохвостов, разведчиков или губителей, и прикоснись тотемом Брогга к их трупам. Только умирая, драконид испускает свою сущность.$B$BТвари, которых ты будешь искать, кишат в Огненном логове, к северо-западу отсюда, и в руинах Деревни Каменного Молота на севере.','Принесите 10 сущностей черного дракона Броггу в Шестермуть.','Ты добыл сущность? Броггу она нужна, чтобы отомстить врагам!','Вернитесь к Броггу в Шестермуть, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Essence of Enmity',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы сделать тотем для обряда, Броггу надо получить сущность тех тварей, что убили его друзей. Ненависть и злоба врагов Брогга будет питать пламя его мести.$B$BВыследи Огнегривых пеплохвостов, разведчиков или губителей, и прикоснись тотемом Брогга к их трупам. Только умирая, драконид испускает свою сущность.$B$BТвари, которых ты будешь искать, кишат в Огненном логове, к северо-западу отсюда, и в руинах Деревни Каменного Молота на севере.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 сущностей черного дракона Броггу в Шестермуть.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты добыл сущность? Броггу она нужна, чтобы отомстить врагам!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Броггу в Шестермуть, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11162,'[DEPRECATED]Challenge to the Black Flight','Брогг лелеет мысль отомстить черным драконам болот. $n, ты очень $Gпомог:помогла; в подготовке к этому мероприятию. Хочешь помочь еще?$B$BБери клановое знамя Брогга и поезжай на восток, пока не найдешь пещеру, похожую на драконью пасть. Водрузи знамя Каменного Молота у входа в пещеру и брось Ониксии вызов Брогга!$B$BБрогг и Каменные Молоты вернут себе свою землю!','Установите знамя Каменного Молота у входа в Логово Ониксии, затем вернитесь к Броггу в Шестермуть.','Брогг отомстит!','Вернитесь к Броггу в Шестермуть, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Challenge to the Black Flight',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Брогг лелеет мысль отомстить черным драконам болот. $n, ты очень $Gпомог:помогла; в подготовке к этому мероприятию. Хочешь помочь еще?$B$BБери клановое знамя Брогга и поезжай на восток, пока не найдешь пещеру, похожую на драконью пасть. Водрузи знамя Каменного Молота у входа в пещеру и брось Ониксии вызов Брогга!$B$BБрогг и Каменные Молоты вернут себе свою землю!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Установите знамя Каменного Молота у входа в Логово Ониксии, затем вернитесь к Броггу в Шестермуть.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Брогг отомстит!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Броггу в Шестермуть, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11163,'Тайная Сестрица','*Донна подозрительно оглядывается по сторонам и шепчет тебе.*$B$BТо, что я тебе сейчас скажу, должно остаться между нами, смекаешь?$B$BМеня прислали сюда мирохранители Шаттрата, чтобы я проникла в банду Бадда. С самого твоего появления, ты привлек мое пристальное внимание. Но твои действия полностью очистили тебя от всех подозрений. А за то, что ты убил Зул\'джина, мне поручено вручить тебе награду.','Доберитесь до Донны Браско, чтобы получить причитающуюся вам награду. Найти Донну можно на Призрачных Землях, сразу за окраиной Зул\'Амана.','<Донна оглядывается и затем шепчет вам.>$B$B$N, то, что я собираюсь сказать вам, должно оставаться конфиденциальным, понятно?$B$BМеня послали миротворцы Шаттрата, чтобы проникнуть сюда в банду Бадда. По правде говоря, с тех пор, как вы впервые приехали, вы были ключевой фигурой в моем расследовании.$B$BНо с некоторых пор ваши дела сняли с вас какие-либо подозрения. Фактически, за то, что вы убили безумного военачальника Зул\'Джина, я вынуждена вознаградить вас за ваши усилия.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайная Сестрица',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','*Донна подозрительно оглядывается по сторонам и шепчет тебе.*$B$BТо, что я тебе сейчас скажу, должно остаться между нами, смекаешь?$B$BМеня прислали сюда мирохранители Шаттрата, чтобы я проникла в банду Бадда. С самого твоего появления, ты привлек мое пристальное внимание. Но твои действия полностью очистили тебя от всех подозрений. А за то, что ты убил Зул\'джина, мне поручено вручить тебе награду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доберитесь до Донны Браско, чтобы получить причитающуюся вам награду. Найти Донну можно на Призрачных Землях, сразу за окраиной Зул\'Амана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Донна оглядывается и затем шепчет вам.>$B$B$N, то, что я собираюсь сказать вам, должно оставаться конфиденциальным, понятно?$B$BМеня послали миротворцы Шаттрата, чтобы проникнуть сюда в банду Бадда. По правде говоря, с тех пор, как вы впервые приехали, вы были ключевой фигурой в моем расследовании.$B$BНо с некоторых пор ваши дела сняли с вас какие-либо подозрения. Фактически, за то, что вы убили безумного военачальника Зул\'Джина, я вынуждена вознаградить вас за ваши усилия.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11164,'Клыкастые всадники','Привет, $gчувак:чувиха;, ты тут типа $gновенький:новенькая;? Сделаешь для меня одну штуку?$B$BБадд затеял обновить свои личины лесных троллей. Говорит, что уже почти закончил, не хватает одной небольшой детали... Клыков.$B$BМое умение снимать шкуры тут абсолютно бесполезно...$B$BПринесешь мне десяток их клыков, а, $gдруг:подруга;?','Соберите для Пригмона 10 клыков лесных троллей в Зул\'Амане и принесите их ему в лагерь Бадда в Призрачных Землях.','Ах да, это именно то, что мне нужно!$B$BВот и платёж, который я тебе обещал, $C.','Поторопись, $Gдружище:подружка;!$B$BМожет, пошлют меня в Зул\'Аман одного, если я в ближайшее время не отдам ему эти бивни!','Вернитесь к Пригмону в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клыкастые всадники',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $gчувак:чувиха;, ты тут типа $gновенький:новенькая;? Сделаешь для меня одну штуку?$B$BБадд затеял обновить свои личины лесных троллей. Говорит, что уже почти закончил, не хватает одной небольшой детали... Клыков.$B$BМое умение снимать шкуры тут абсолютно бесполезно...$B$BПринесешь мне десяток их клыков, а, $gдруг:подруга;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите для Пригмона 10 клыков лесных троллей в Зул\'Амане и принесите их ему в лагерь Бадда в Призрачных Землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах да, это именно то, что мне нужно!$B$BВот и платёж, который я тебе обещал, $C.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поторопись, $Gдружище:подружка;!$B$BМожет, пошлют меня в Зул\'Аман одного, если я в ближайшее время не отдам ему эти бивни!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пригмону в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11165,'Тролль в стане троллей','Послушай, $gпарень:подруга;, старине Пригмону нужно, чтобы ты $gсделал:сделала; еще кое-что.$b$bМой никчемный кузен Зунгам не может выбраться из Зул\'Амана. Но тем не менее он жив – прошлой ночью я видел в небе его сигнальную ракету!$b$bСтоило бы конечно, бросить его там, чтобы не втягивал меня в свои дела, но он мне должен нехилую сумму денег.$b$bТак что сделай, что можешь, спаси его шкуру и принеси мне должок!','Найдите Зунгама и помогите ему выбраться из Зул\'Амана.','Я свободен!$B$BДэй взял почти все, когда схватил меня, но осталось еще кое-что - возьмите мою последнюю монету за ваши усилия.$B$B...и меньшее, что я могу сделать, это предложить свои услуги....') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тролль в стане троллей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Послушай, $gпарень:подруга;, старине Пригмону нужно, чтобы ты $gсделал:сделала; еще кое-что.$b$bМой никчемный кузен Зунгам не может выбраться из Зул\'Амана. Но тем не менее он жив – прошлой ночью я видел в небе его сигнальную ракету!$b$bСтоило бы конечно, бросить его там, чтобы не втягивал меня в свои дела, но он мне должен нехилую сумму денег.$b$bТак что сделай, что можешь, спаси его шкуру и принеси мне должок!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Зунгама и помогите ему выбраться из Зул\'Амана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я свободен!$B$BДэй взял почти все, когда схватил меня, но осталось еще кое-что - возьмите мою последнюю монету за ваши усилия.$B$B...и меньшее, что я могу сделать, это предложить свои услуги....',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11166,'Крестом на карте обозначена... твоя смерть!','Нет, ну как они могли провалиться? Идиоты! Говорил я им, будьте осторожнее, и даже выдал им маскировку, чтобы было проще. Ладно, туда им и дорога. Теперь этим делом займешься ты.$B$BЕсли ты добьешься успеха, то я сочту тебя достойным вступить в ряды моей команды, молва о которой скоро прогремит по всему миру. И на меньшее я не согласен.$B$BНам осталось заполнить еще несколько участков на моей карте, и тогда мы сможем начать раскопки.','Отправляйтесь в Зул\'Аман и посетите чертог Халаззи, платформу Джан\'алая и платформу Акил\'зона. Заметьте все подробности и по возвращении доложите о них Бадду в его лагере в Призрачных землях.','<Бадд изо всех сил пытается сохранить самообладание.>$B$BИтак, $N, тебе пора вернуться. Да, фактически, Ты задерживаешь всю операцию.$B$BТеперь приступим к заполнению этой карты...','Я верю, что мои созданные вручную маскировки обеспечили вам адекватную защиту в Зул\'Амане.$B$BВы обследовали эти места для меня? Или мне начать искать замену?','Вернитесь к Бадду Недреку в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Крестом на карте обозначена... твоя смерть!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нет, ну как они могли провалиться? Идиоты! Говорил я им, будьте осторожнее, и даже выдал им маскировку, чтобы было проще. Ладно, туда им и дорога. Теперь этим делом займешься ты.$B$BЕсли ты добьешься успеха, то я сочту тебя достойным вступить в ряды моей команды, молва о которой скоро прогремит по всему миру. И на меньшее я не согласен.$B$BНам осталось заполнить еще несколько участков на моей карте, и тогда мы сможем начать раскопки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Зул\'Аман и посетите чертог Халаззи, платформу Джан\'алая и платформу Акил\'зона. Заметьте все подробности и по возвращении доложите о них Бадду в его лагере в Призрачных землях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Бадд изо всех сил пытается сохранить самообладание.>$B$BИтак, $N, тебе пора вернуться. Да, фактически, Ты задерживаешь всю операцию.$B$BТеперь приступим к заполнению этой карты...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я верю, что мои созданные вручную маскировки обеспечили вам адекватную защиту в Зул\'Амане.$B$BВы обследовали эти места для меня? Или мне начать искать замену?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бадду Недреку в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11167,'Новая чума','Аптекарь Лисандер из Лагеря Возмездия просит вас собрать 10 неповрежденных флаконов с чумой с места кораблекрушения на юго-востоке.','Я рад видеть тебя живым и невредимым. Видишь ли, переноска этих контейнеров не абсолютно безопасна – можно было и заразиться. Наверное, мне стоило предупредить тебя об этом.','Вернитесь к аптекарю Лисандеру в Лагерь Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новая чума',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аптекарь Лисандер из Лагеря Возмездия просит вас собрать 10 неповрежденных флаконов с чумой с места кораблекрушения на юго-востоке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я рад видеть тебя живым и невредимым. Видишь ли, переноска этих контейнеров не абсолютно безопасна – можно было и заразиться. Наверное, мне стоило предупредить тебя об этом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лисандеру в Лагерь Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11168,'Добавить крепости','Похоже, долгое путешествие через море негативно сказывается на эффективности чумы. Нам надо добавить мощный токсин, чтобы усилить воздействие штамма.$B$BМне кажется, что вот эти береговые членистоногие могут быть дальними родственниками мелких темнопанцирных прибрежных крабов. Последние водятся в тропических районах и выделяют столь мощный паралитический яд, что одного укуса хватит на целого огра.$B$BНо мы же знаем – чем больше особь, тем лучше! Возможно, эти гигантские прибрежные крабы будут нам полезны. Принеси-ка мне несколько ядовитых желез!','Принесите 3 гигантские ядовитые железы гигантских прибрежных крабов аптекарю Лисандеру, который будет ждать вас в Лагере Возмездия в Ревущем фьорде.','Вернитесь к аптекарю Лисандеру в Лагерь Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добавить крепости',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, долгое путешествие через море негативно сказывается на эффективности чумы. Нам надо добавить мощный токсин, чтобы усилить воздействие штамма.$B$BМне кажется, что вот эти береговые членистоногие могут быть дальними родственниками мелких темнопанцирных прибрежных крабов. Последние водятся в тропических районах и выделяют столь мощный паралитический яд, что одного укуса хватит на целого огра.$B$BНо мы же знаем – чем больше особь, тем лучше! Возможно, эти гигантские прибрежные крабы будут нам полезны. Принеси-ка мне несколько ядовитых желез!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 3 гигантские ядовитые железы гигантских прибрежных крабов аптекарю Лисандеру, который будет ждать вас в Лагере Возмездия в Ревущем фьорде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лисандеру в Лагерь Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11169,'[DEPRECATED]The Grimtotem Weapon','Во время последнего нападения клана Зловещего Тотема я был ранен, но прежде мне удалось захватить странный тотем, из тех, что наши враги используют против нас.$B$BМне казалось, что во время сражения он выплескивал заряды необузданной энергии, но сколько я ни бился, я так и не сумел понять, как он действует. Я дам тебе этот тотем на время, если ты мне поможешь испытать его.$B$BТопкая местность вокруг усадьбы – гнездилище мерзких кроколисков-грязекупов и грязекупов-острозубов. Мимо не пройдешь, слово даю. Попробуй сражаться с кроколисками вблизи тотема.','Ученик Гарион из усадьбы Табеты хочет, чтобы вы испытали захваченный тотем на 10 крапчатых кроколисках-грязекупах или грязекупах-острозубах.','<Ученик выслушивает ваш рассказ об испытании.>\n\nДымка и электрические разряды? И только? Нет, должно быть что-то еще! Таурены из Зловещего Тотема вряд ли потащат с собой на поле битвы бесполезную вещь.','Как успехи с испытанием тотема?','Вернитесь к ученику Гариону на ферму, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Grimtotem Weapon',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время последнего нападения клана Зловещего Тотема я был ранен, но прежде мне удалось захватить странный тотем, из тех, что наши враги используют против нас.$B$BМне казалось, что во время сражения он выплескивал заряды необузданной энергии, но сколько я ни бился, я так и не сумел понять, как он действует. Я дам тебе этот тотем на время, если ты мне поможешь испытать его.$B$BТопкая местность вокруг усадьбы – гнездилище мерзких кроколисков-грязекупов и грязекупов-острозубов. Мимо не пройдешь, слово даю. Попробуй сражаться с кроколисками вблизи тотема.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ученик Гарион из усадьбы Табеты хочет, чтобы вы испытали захваченный тотем на 10 крапчатых кроколисках-грязекупах или грязекупах-острозубах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ученик выслушивает ваш рассказ об испытании.>\n\nДымка и электрические разряды? И только? Нет, должно быть что-то еще! Таурены из Зловещего Тотема вряд ли потащат с собой на поле битвы бесполезную вещь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как успехи с испытанием тотема?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Гариону на ферму, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11170,'Испытания на море','Мы только что узнали, что войска Альянса выслали подкрепление. Как раз вовремя! $B$BНам не хватает подопытных особей, а эти резервисты Северного флота как раз подойдут для испытаний!$B$BВозьми эти склянки с чумой и поговори с Камиллой, дрессировщицей нетопырей. Скажи ей, что тебе нужна летучая мышь для специального задания.$B$BКак только окажешься над морем, сбрось склянки на флот Альянса. Интересно будет посмотреть на результат!','Поговорите с дрессировщицей нетопырей Камиллой, возьмите ездового нетопыря и летите наперерез войскам Альянса. Когда вы будете пролетать над флотом, сбросьте склянки с чумой и заразите 16 резервистов Северного флота.','Хммм...результаты не очень впечатляющие...','А, вот и ты!','Вернитесь к аптекарю Лисандеру в Лагерь Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытания на море',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы только что узнали, что войска Альянса выслали подкрепление. Как раз вовремя! $B$BНам не хватает подопытных особей, а эти резервисты Северного флота как раз подойдут для испытаний!$B$BВозьми эти склянки с чумой и поговори с Камиллой, дрессировщицей нетопырей. Скажи ей, что тебе нужна летучая мышь для специального задания.$B$BКак только окажешься над морем, сбрось склянки на флот Альянса. Интересно будет посмотреть на результат!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с дрессировщицей нетопырей Камиллой, возьмите ездового нетопыря и летите наперерез войскам Альянса. Когда вы будете пролетать над флотом, сбросьте склянки с чумой и заразите 16 резервистов Северного флота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хммм...результаты не очень впечатляющие...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, вот и ты!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лисандеру в Лагерь Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11171,'Повелитель Проклятий? Пффф!','Отлично! Скоро мы триумфально войдем в Зул\'Аман.$B$BТы выложился по полной для общего дела, $n, и я говорил со своими ребятами – они не возражают против тебя. Так что ты заслужил свое место в команде. Осталась одна небольшая заминка. Ты должен убить, этого, как его... повелителя проклятий. Ничего страшного, тебе стоит посмотреть ему в глаза, и он бросится наутек. Старые, бессильные тролли часто прибавляют к своему имени громкие титулы, чтобы скрыть свою беспомощность...','Убейте в Зул\'Амане повелителя проклятий Малакрасса и вернитесь к Бадду Недреку на Холмы Томагавков.','Наконец-то! Теперь, когда работа завершена, я могу, наконец, оставить след в истории. Но во-первых, есть одно небольшое дело к тебе....$B$BБоюсь, $N, что пришло время отпустить тебя. Я чувствую, что ваш потенциал здесь достигнут, если не намного превышен.$B$Bне плохо. Ведь требуется исключительный тип личности, чтобы участвовать в таких неординарных событиях и не терять рассудка. И посмотри сюда, у меня есть кое-что, что поможет тебе меня запомнишь.','Я надеюсь, вы оценили масштабы возможность, что я дал вам, $N.$B$BВы уже позаботились о Малакрассе?','Вернитесь к Бадду Недреку в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелитель Проклятий? Пффф!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично! Скоро мы триумфально войдем в Зул\'Аман.$B$BТы выложился по полной для общего дела, $n, и я говорил со своими ребятами – они не возражают против тебя. Так что ты заслужил свое место в команде. Осталась одна небольшая заминка. Ты должен убить, этого, как его... повелителя проклятий. Ничего страшного, тебе стоит посмотреть ему в глаза, и он бросится наутек. Старые, бессильные тролли часто прибавляют к своему имени громкие титулы, чтобы скрыть свою беспомощность...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте в Зул\'Амане повелителя проклятий Малакрасса и вернитесь к Бадду Недреку на Холмы Томагавков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то! Теперь, когда работа завершена, я могу, наконец, оставить след в истории. Но во-первых, есть одно небольшое дело к тебе....$B$BБоюсь, $N, что пришло время отпустить тебя. Я чувствую, что ваш потенциал здесь достигнут, если не намного превышен.$B$Bне плохо. Ведь требуется исключительный тип личности, чтобы участвовать в таких неординарных событиях и не терять рассудка. И посмотри сюда, у меня есть кое-что, что поможет тебе меня запомнишь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я надеюсь, вы оценили масштабы возможность, что я дал вам, $N.$B$BВы уже позаботились о Малакрассе?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бадду Недреку в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11172,'[DEPRECATED]The Zeppelin Crash','Не так давно к востоку отсюда разбился гоблинский дирижабль.Несколько дней назад в ту сторону проезжала представительница картеля Хитрой Шестеренки.$B$BОна искала информацию о судьбе груза с дирижабля и его пилота, Бизила, но никто из нас на месте крушения не был. Сомневаюсь, что она самостоятельно подчистит обломки. Еще менее вероятно, что она получит груз, который переправлял дирижабль.$B$BЕсли есть время, сходи к ней на место крушения дирижабля Бизила, прямо на востоке отсюда, возле гор.','Поговорите с Мокси Сталегриль на месте крушения дирижабля Бизила.','Так тебя послали эти маги-отшельники? И с чего я тебе должна доверять?\n\nВпрочем, помощь мне не помешала бы. Да и нет тут ничего интересного для мага.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Zeppelin Crash',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не так давно к востоку отсюда разбился гоблинский дирижабль.Несколько дней назад в ту сторону проезжала представительница картеля Хитрой Шестеренки.$B$BОна искала информацию о судьбе груза с дирижабля и его пилота, Бизила, но никто из нас на месте крушения не был. Сомневаюсь, что она самостоятельно подчистит обломки. Еще менее вероятно, что она получит груз, который переправлял дирижабль.$B$BЕсли есть время, сходи к ней на место крушения дирижабля Бизила, прямо на востоке отсюда, возле гор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мокси Сталегриль на месте крушения дирижабля Бизила.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так тебя послали эти маги-отшельники? И с чего я тебе должна доверять?\n\nВпрочем, помощь мне не помешала бы. Да и нет тут ничего интересного для мага.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11173,'[DEPRECATED]The Reagent Thief','Что ученик Морланн действительно умеет делать, так это ныть насчет нехватки реагентов.$B$BОбычно я его нытье мимо ушей пропускаю, но это не всегда помогает! На сей раз я попытаюсь заткнуть его другим способом. $B$BМожет, если я подброшу недостающий реактив, прежде чем он заметит, он отвяжется от меня. Самый распространенный реактив, который мы оба используем, – это болотный яд, который получают из темноклыких ползунов и пагубных живорезов, что водятся в болотах к северу от усадьбы. Принесешь яда, и я подолью его, прежде чем Морланн заметит.','Принесите 6 флаконов болотного яда ученику Гариону в усадьбу Табеты.','Ученик Гарион рассматривает яд.\n\nПревосходно! Он и не заметит, что это новый.','Ты добыл яд? Морланн того и гляди заметит, что колбы куда-то делись.','Вернитесь к ученику Гариону на ферму, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Reagent Thief',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что ученик Морланн действительно умеет делать, так это ныть насчет нехватки реагентов.$B$BОбычно я его нытье мимо ушей пропускаю, но это не всегда помогает! На сей раз я попытаюсь заткнуть его другим способом. $B$BМожет, если я подброшу недостающий реактив, прежде чем он заметит, он отвяжется от меня. Самый распространенный реактив, который мы оба используем, – это болотный яд, который получают из темноклыких ползунов и пагубных живорезов, что водятся в болотах к северу от усадьбы. Принесешь яда, и я подолью его, прежде чем Морланн заметит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 флаконов болотного яда ученику Гариону в усадьбу Табеты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ученик Гарион рассматривает яд.\n\nПревосходно! Он и не заметит, что это новый.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты добыл яд? Морланн того и гляди заметит, что колбы куда-то делись.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ученику Гариону на ферму, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11174,'[DEPRECATED]Corrosion Prevention','Ты только посмотри! Слизнюки так и кишат. Если мне не удастся как-то разобраться с ними, они сожрут и обломки, и груз с дирижабля!$B$BЯ не могу вернуться ни с чем, |3-6($c)! Помоги мне разогнать этих слизнюков, прежде чем они тут все понадкусывают!$B$BЕсли включить это устройство, оно направит энергию на слизнюков, и они начнут взрываться. Разбитый энергетический сердечник дирижабля сможет подпитывать устройство. Тот кусок, что рядом с местом крушения, работает стабильно, остальные – не очень.','Мокси Сталегриль хочет, чтобы вы уничтожили 10 слизнюков и доложили ей о выполнении задания на месте крушения дирижабля Бизила.','Ну, вроде почище стало...\n\nПора вернуться к делу и заняться спасением груза.','Как твоя маленькая война против слизнюков?','Вернитесь к Мокси Сталегриль на место крушения дирижабля Бизила, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Corrosion Prevention',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты только посмотри! Слизнюки так и кишат. Если мне не удастся как-то разобраться с ними, они сожрут и обломки, и груз с дирижабля!$B$BЯ не могу вернуться ни с чем, |3-6($c)! Помоги мне разогнать этих слизнюков, прежде чем они тут все понадкусывают!$B$BЕсли включить это устройство, оно направит энергию на слизнюков, и они начнут взрываться. Разбитый энергетический сердечник дирижабля сможет подпитывать устройство. Тот кусок, что рядом с местом крушения, работает стабильно, остальные – не очень.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мокси Сталегриль хочет, чтобы вы уничтожили 10 слизнюков и доложили ей о выполнении задания на месте крушения дирижабля Бизила.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну, вроде почище стало...\n\nПора вернуться к делу и заняться спасением груза.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как твоя маленькая война против слизнюков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мокси Сталегриль на место крушения дирижабля Бизила, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11175,'Дочка моя','Скажи, это правда, что все исследователи, отправившиеся в Шепчущую теснину, сошли с ума?$B$BМоя дочка работает надзирательницей в Лиге исследователей, и ее группа отправилась куда-то на север, к месту, которое называется Стальные ворота. Честно говоря, после всех ужасных событий, обрушившихся на нас, я опасаюсь за ее безопасность. $B$BПрошу тебя, |3-6($c), найди Ирену и убедись, что с ней все в порядке. Я уже стар, и мне не по силам совершить такое путешествие.','Старик Каменная Мантия попросил вас найти его дочку, надзирательницу Ирену Каменная Мантия в Стальных воротах.','Грр! Так я и знала! Трясется надо мной, как курица над цыпленком. Стыдно-то как!$B$BНет, ты только не подумай, что я тебе не рада... наоборот! Мы все рады тебя видеть. Нам так нужна твоя помощь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дочка моя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скажи, это правда, что все исследователи, отправившиеся в Шепчущую теснину, сошли с ума?$B$BМоя дочка работает надзирательницей в Лиге исследователей, и ее группа отправилась куда-то на север, к месту, которое называется Стальные ворота. Честно говоря, после всех ужасных событий, обрушившихся на нас, я опасаюсь за ее безопасность. $B$BПрошу тебя, |3-6($c), найди Ирену и убедись, что с ней все в порядке. Я уже стар, и мне не по силам совершить такое путешествие.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Старик Каменная Мантия попросил вас найти его дочку, надзирательницу Ирену Каменная Мантия в Стальных воротах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Грр! Так я и знала! Трясется надо мной, как курица над цыпленком. Стыдно-то как!$B$BНет, ты только не подумай, что я тебе не рада... наоборот! Мы все рады тебя видеть. Нам так нужна твоя помощь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11176,'Присматривая за работой','Наша работа здесь только начинается, но с прибытием летающих машин из Крепости Западной Стражи дела пойдут веселее.$B$BПроблема в том, что нам не хватает опытных пилотов. Хуже того, на Вырубках к северу отсюда начались какие-то проблемы, так что мне бы хотелось побыстрее закончить дела и отправиться домой. $B$BЕсли хочешь помочь нам, поговори с одним из главных археологов. Они сейчас осматривают ветролеты к северу и югу от раскопок.','Надзиратель Ирена Каменная Мантия попросила вас поговорить с главным археологом Стальных ворот.','Тебя Ирена прислала, да? Отлично! У нас найдется для тебя работа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Присматривая за работой',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наша работа здесь только начинается, но с прибытием летающих машин из Крепости Западной Стражи дела пойдут веселее.$B$BПроблема в том, что нам не хватает опытных пилотов. Хуже того, на Вырубках к северу отсюда начались какие-то проблемы, так что мне бы хотелось побыстрее закончить дела и отправиться домой. $B$BЕсли хочешь помочь нам, поговори с одним из главных археологов. Они сейчас осматривают ветролеты к северу и югу от раскопок.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Надзиратель Ирена Каменная Мантия попросила вас поговорить с главным археологом Стальных ворот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебя Ирена прислала, да? Отлично! У нас найдется для тебя работа.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11177,'[DEPRECATED]The Hermit of Swamplight Manor','Есть тут один парень, которого местные зовут Ярл "Болотный Глаз", он живет в одиночестве на болотах. Некоторое время назад он "приобрел" сторожку "Болотный огонек", после того как прежние владельцы таинственным образом исчезли.$B$BЯ время от времени посылаю кого-нибудь проверить, как он там. Понимаешь, он мне малость дедулю моего напоминает. Говорят, что он на голову немного больной.$B$BЕсли ты пойдешь на северо-запад по дороге из Терамора, то найдешь сторожку "Болотный огонек" возле Ведьмина холма, прямо перед поворотом дороги на запад.','Поговорите с Ярлом "Болотным Глазом" в сторожке "Болотный огонек".','Слезь с моей лужайки... если, конечно, ты не хочешь помочь старому "Болотному оку" с кулинарией. Что скажешь?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Hermit of Swamplight Manor',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть тут один парень, которого местные зовут Ярл "Болотный Глаз", он живет в одиночестве на болотах. Некоторое время назад он "приобрел" сторожку "Болотный огонек", после того как прежние владельцы таинственным образом исчезли.$B$BЯ время от времени посылаю кого-нибудь проверить, как он там. Понимаешь, он мне малость дедулю моего напоминает. Говорят, что он на голову немного больной.$B$BЕсли ты пойдешь на северо-запад по дороге из Терамора, то найдешь сторожку "Болотный огонек" возле Ведьмина холма, прямо перед поворотом дороги на запад.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ярлом "Болотным Глазом" в сторожке "Болотный огонек".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слезь с моей лужайки... если, конечно, ты не хочешь помочь старому "Болотному оку" с кулинарией. Что скажешь?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11178,'Кровь Вождя','Пока ты изучаешь пульсирующий фиал, твои мысли обращаются к маленькому, вздорному человечку за стенами Зул\'Амана.$B$BПодумать только, какое лицо будет у Бадда, когда он это увидит.','Принесите кровь Зул\'джина Бадду в его лагерь в Призрачных Землях. За пределами Зул\'Амана.','Ты говоришь - Кровь самого Зул\'джина?$B$B<Собираясь, Бадд продолжает>$B$BЧто ж, я ценю этот жест, $C, но я мог бы легко убить его. Нет никакого способа, чтобы он был так напуган, как говорят легенды. Эти вещи могут быть полностью преувеличены, как вы со временем узнаете. Скорее всего, этот жалкий старый кретин заболел артритом!$B$BВ любом случае, я полагаю, это было меньшее, что вы могли сделать в качестве платы за доброту, которую я вам здесь оказал.$B$BТеперь прочь - я должен избавиться от этого мерзкого пузырька!','<Бадд пытается скрыть свое недовольство вашим присутствием.>$B$BСнова ты....$B$BНе знаю, как еще это сказать - я просто слишком занят своими приготовлениями, чтобы держать тебя за ручку.$B$BПоверь, $N, все к лучшему. Возможно, каким-то чудом ты в конечном итоге сможешь создать себе имя.$B$BЕсли да, то ты можешь говорить, что $Gначинал:начинала; с несравненного Бадда Недрека!','Вернитесь к Бадду Недреку в Призрачные земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь Вождя',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты изучаешь пульсирующий фиал, твои мысли обращаются к маленькому, вздорному человечку за стенами Зул\'Амана.$B$BПодумать только, какое лицо будет у Бадда, когда он это увидит.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите кровь Зул\'джина Бадду в его лагерь в Призрачных Землях. За пределами Зул\'Амана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты говоришь - Кровь самого Зул\'джина?$B$B<Собираясь, Бадд продолжает>$B$BЧто ж, я ценю этот жест, $C, но я мог бы легко убить его. Нет никакого способа, чтобы он был так напуган, как говорят легенды. Эти вещи могут быть полностью преувеличены, как вы со временем узнаете. Скорее всего, этот жалкий старый кретин заболел артритом!$B$BВ любом случае, я полагаю, это было меньшее, что вы могли сделать в качестве платы за доброту, которую я вам здесь оказал.$B$BТеперь прочь - я должен избавиться от этого мерзкого пузырька!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Бадд пытается скрыть свое недовольство вашим присутствием.>$B$BСнова ты....$B$BНе знаю, как еще это сказать - я просто слишком занят своими приготовлениями, чтобы держать тебя за ручку.$B$BПоверь, $N, все к лучшему. Возможно, каким-то чудом ты в конечном итоге сможешь создать себе имя.$B$BЕсли да, то ты можешь говорить, что $Gначинал:начинала; с несравненного Бадда Недрека!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бадду Недреку в Призрачные земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11179,'У Финлея кишка тонка','У нас так много лучников! И кто же должен следить за состоянием их оружия? Я, Финлей Флетчер!$B$BКомандир приказал мне и моим помощникам подготовить Крепость Диккор к походу, а у меня не было времени выбраться наружу и добыть кишечные струны, из которых изготавливается тетива. $B$B$C, $gмиленький:миленькая;, принеси мне несколько кишечных струн! Их можно добыть с туманных саблезубов, которые бродят возле фьорда. Только не тащи какие попало – мне подойдут только самые лучшие! Рваные кишки никуда не годятся.','Соберите 7 безупречных кишечных струн туманных саблезубов для Финлея Флетчера из Крепости Западной Стражи.','Вернитесь к Финлею Флетчеру в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У Финлея кишка тонка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У нас так много лучников! И кто же должен следить за состоянием их оружия? Я, Финлей Флетчер!$B$BКомандир приказал мне и моим помощникам подготовить Крепость Диккор к походу, а у меня не было времени выбраться наружу и добыть кишечные струны, из которых изготавливается тетива. $B$B$C, $gмиленький:миленькая;, принеси мне несколько кишечных струн! Их можно добыть с туманных саблезубов, которые бродят возле фьорда. Только не тащи какие попало – мне подойдут только самые лучшие! Рваные кишки никуда не годятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 безупречных кишечных струн туманных саблезубов для Финлея Флетчера из Крепости Западной Стражи.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Финлею Флетчеру в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11180,'Что таится на Ведьмином холме?','Я приехал сюда навестить Ярла в его новом доме и с тех пор живу в непрекращающемся кошмаре! С этим местом что-то не так, не я один это замечаю...$B$BТы $Gвидел:видела; призраков и неупокоенных мертвецов вокруг Ведьмина холма? Чую я – если кто и знает, что тут творится, так это они. Разыщи в окрестностях этих восставших мертвецов и духов, уложи их в бою на вечный покой – и посмотрим, что нам удастся узнать прежде, чем зло окончательно сожрет Ярла!','Моргант Мрачник из сторожки "Болотный огонек" хочет, чтобы вы добыли информацию у 10 восставших мертвецов или духов.','Что ты $Gузнал:узнала; от духов, обитающих в этом месте?','Вернитесь к Морганту Мрачнику в сторожку "Болотный огонек", что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что таится на Ведьмином холме?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я приехал сюда навестить Ярла в его новом доме и с тех пор живу в непрекращающемся кошмаре! С этим местом что-то не так, не я один это замечаю...$B$BТы $Gвидел:видела; призраков и неупокоенных мертвецов вокруг Ведьмина холма? Чую я – если кто и знает, что тут творится, так это они. Разыщи в окрестностях этих восставших мертвецов и духов, уложи их в бою на вечный покой – и посмотрим, что нам удастся узнать прежде, чем зло окончательно сожрет Ярла!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Моргант Мрачник из сторожки "Болотный огонек" хочет, чтобы вы добыли информацию у 10 восставших мертвецов или духов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что ты $Gузнал:узнала; от духов, обитающих в этом месте?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морганту Мрачнику в сторожку "Болотный огонек", что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11181,'Ведьмина погибель','За долгие годы работы травником я часто видел, как природа сама незаметно решает самые неприятные проблемы. Я читал, что тайные маги и знахари часто изгоняют зло дымом травки, называемой ведьмина погибель.$B$BЕсли это так, то ведьмина погибель должна расти неподалеку, на мелководье близ Ведьмина холма. Ты узнаешь ее по широким листьям и красноватому стеблю. Принеси мне травы, сколько найдешь, $n. Может, это наша единственная надежда.','Принесите 9 ростков ведьминой погибели Морганту Мрачнику в сторожку "Болотный огонек".','Моргант берет у вас пучок травы.\n\nТочно подходит под описание! Пока тебя не было, я приготовил факел. Остается только сунуть в него траву.','Удалось травки набрать? Действовать надо быстро – прежде чем зло, которое стоит за этим нашествием, укоренится в этих местах.','Вернитесь к Морганту Мрачнику в сторожку "Болотный огонек", что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ведьмина погибель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За долгие годы работы травником я часто видел, как природа сама незаметно решает самые неприятные проблемы. Я читал, что тайные маги и знахари часто изгоняют зло дымом травки, называемой ведьмина погибель.$B$BЕсли это так, то ведьмина погибель должна расти неподалеку, на мелководье близ Ведьмина холма. Ты узнаешь ее по широким листьям и красноватому стеблю. Принеси мне травы, сколько найдешь, $n. Может, это наша единственная надежда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 9 ростков ведьминой погибели Морганту Мрачнику в сторожку "Болотный огонек".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Моргант берет у вас пучок травы.\n\nТочно подходит под описание! Пока тебя не было, я приготовил факел. Остается только сунуть в него траву.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось травки набрать? Действовать надо быстро – прежде чем зло, которое стоит за этим нашествием, укоренится в этих местах.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морганту Мрачнику в сторожку "Болотный огонек", что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11182,'В поисках первопричины','Все в мире стремится к равновесию, и помешать этому могут лишь те, кому неведома великая гармония природы. $B$BТы зря тратишь свое время, убивая драконов и их детенышей. Истинная причина распространения магического пожара – недавно пробудившиеся врайкулы во главе с их повелителем, Скелдом Сыном Дракона.$B$BЕсли ты жаждешь обагрить свои руки кровью, начни с них. Ты найдешь логово врайкулов на южной стороне Пылающего Гнездовья.','Убить 5 укротителей из клана Укротителей драконов и Скелда Сына Дракона. Если вам удастся выполнить это задание, вернитесь к древу Пылающего Гнездовья.','Как твои дела, малыш? Удалось ли тебе справиться с этими назойливыми тварями?','Вернитесь к Древу Пылающего гнездовья в Пылающее Гнездовье, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках первопричины',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все в мире стремится к равновесию, и помешать этому могут лишь те, кому неведома великая гармония природы. $B$BТы зря тратишь свое время, убивая драконов и их детенышей. Истинная причина распространения магического пожара – недавно пробудившиеся врайкулы во главе с их повелителем, Скелдом Сыном Дракона.$B$BЕсли ты жаждешь обагрить свои руки кровью, начни с них. Ты найдешь логово врайкулов на южной стороне Пылающего Гнездовья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убить 5 укротителей из клана Укротителей драконов и Скелда Сына Дракона. Если вам удастся выполнить это задание, вернитесь к древу Пылающего Гнездовья.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как твои дела, малыш? Удалось ли тебе справиться с этими назойливыми тварями?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Древу Пылающего гнездовья в Пылающее Гнездовье, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11183,'Очищение Ведьмина холма','Факел готов. Установи его в конце пристани и приготовься к бою.$B$BЯ понятия не имею, кого может привлечь факельный дым... если вообще хоть кто-то появится. Должен сказать, не верю я в народную магию, учиться настоящей у нас времени нет. Желаю вам с Ярлом удачи!','Моргант Мрачник из сторожки "Болотный огонек" хочет, чтобы вы установили факел в конце дока и сразились с тем, что выйдет на свет.','Дело сделано?','Вернитесь к Морганту Мрачнику в сторожку "Болотный огонек", что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение Ведьмина холма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Факел готов. Установи его в конце пристани и приготовься к бою.$B$BЯ понятия не имею, кого может привлечь факельный дым... если вообще хоть кто-то появится. Должен сказать, не верю я в народную магию, учиться настоящей у нас времени нет. Желаю вам с Ярлом удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Моргант Мрачник из сторожки "Болотный огонек" хочет, чтобы вы установили факел в конце дока и сразились с тем, что выйдет на свет.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дело сделано?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Морганту Мрачнику в сторожку "Болотный огонек", что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11184,'[DEPRECATED]WANTED: Goreclaw the Ravenous','Путешественникам и полевому составу Хитрой Шестеренки рекомендуется избегать логова Кровавой Топи, что к западу от города.$B$BЭтот район разорен ящерами, предводитель у них – жестокий и коварный Кровокоготь Ненасытный, который убил уже как минимум двоих инженеров Хитрой Шестеренки.$B$BДраззит Кранотек назначает щедрую награду тому, кто избавит Шестермуть от этой напасти.','Убейте Кровокогтя Ненасытного и явитесь с сообщением к Драззиту Кранотеку в Шестермуть.','Ну наконец-то нашелся храбрец! Я уж подумывал было утроить награду, чтобы кто-нибудь да прикончил наконец этого проклятого ящера, только бюджет не позволял!','Ты очень $Gдоволен:довольна; собой. $GПришел:Пришла; требовать награду за этого чудовищного хищника?','Вернитесь к Драззиту Кранотеку в Шестермуть, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]WANTED: Goreclaw the Ravenous',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Путешественникам и полевому составу Хитрой Шестеренки рекомендуется избегать логова Кровавой Топи, что к западу от города.$B$BЭтот район разорен ящерами, предводитель у них – жестокий и коварный Кровокоготь Ненасытный, который убил уже как минимум двоих инженеров Хитрой Шестеренки.$B$BДраззит Кранотек назначает щедрую награду тому, кто избавит Шестермуть от этой напасти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Кровокогтя Ненасытного и явитесь с сообщением к Драззиту Кранотеку в Шестермуть.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну наконец-то нашелся храбрец! Я уж подумывал было утроить награду, чтобы кто-нибудь да прикончил наконец этого проклятого ящера, только бюджет не позволял!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты очень $Gдоволен:довольна; собой. $GПришел:Пришла; требовать награду за этого чудовищного хищника?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драззиту Кранотеку в Шестермуть, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11185,'[DEPRECATED]The Apothecary\'s Letter','Это письмо, найденное при аптекаре Отрекшихся, говорит о тесном союзе племени Зловещего Тотема и новых хозяев Лордерона.$B$B"В качестве демонстрации доброй воли и в знак новообретенного доверия мы посылаем вам в помощь аптекаря Силлу. Она посодействует в битве против нашего общего врага в Калимдоре. Никто не устоит перед нашей объединенной мощью и решимостью."$B$BПисьмо надо доставить агенту ШРУ Анделло, привратнику в усадьбе Табеты.','Отнесите запечатанное письмо привратнику Анделло в усадьбу Табеты.','Анделло читает письмо, потрясенный его содержанием. $B$BМы давно подозревали, что Орда и Отрекшиеся в союзе, и это письмо подтверждает наши подозрения. При помощи магии и оружия Отрекшихся Зловещий Тотем станет еще более страшным врагом. Баланс сил в Калимдоре может сильно измениться.','Что там у тебя, $C?','Вернитесь к привратнику Анделло на Трясину, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Apothecary\'s Letter',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это письмо, найденное при аптекаре Отрекшихся, говорит о тесном союзе племени Зловещего Тотема и новых хозяев Лордерона.$B$B"В качестве демонстрации доброй воли и в знак новообретенного доверия мы посылаем вам в помощь аптекаря Силлу. Она посодействует в битве против нашего общего врага в Калимдоре. Никто не устоит перед нашей объединенной мощью и решимостью."$B$BПисьмо надо доставить агенту ШРУ Анделло, привратнику в усадьбе Табеты.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите запечатанное письмо привратнику Анделло в усадьбу Табеты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Анделло читает письмо, потрясенный его содержанием. $B$BМы давно подозревали, что Орда и Отрекшиеся в союзе, и это письмо подтверждает наши подозрения. При помощи магии и оружия Отрекшихся Зловещий Тотем станет еще более страшным врагом. Баланс сил в Калимдоре может сильно измениться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там у тебя, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к привратнику Анделло на Трясину, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11186,'[DEPRECATED]Signs of Treachery?','Это письмо, найденное при аптекаре Отрекшихся, говорит о тайной связи племени Зловещего Тотема и Подгорода.$B$B"В качестве демонстрации доброй воли и в знак новообретенного доверия мы посылаем вам в помощь аптекаря Силлу. Она посодействует в битве против нашего общего врага в Калимдоре. Никто не устоит перед нашей объединенной мощью и решимостью."$B$BВозможно, Назир Кровавое Копье из Деревни Гиблотопь знает, как распорядиться этой информацией.','Доставьте запечатанное письмо Назиру Кровавому Копью в Деревню Гиблотопь.','Если все и вправду так, то Отрекшимся придется объясниться!\n\nТаурены из Зловещего Тотема своими выходками давно испытывает терпение вождя. Мы обычно оставляли такие дела улаживать самим тауренам, но это письмо может все изменить.\n\nЭти подозрения еще надо проверить, так что никому не рассказывай о том, что видел сегодня.','Что там у тебя, $C?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Signs of Treachery?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это письмо, найденное при аптекаре Отрекшихся, говорит о тайной связи племени Зловещего Тотема и Подгорода.$B$B"В качестве демонстрации доброй воли и в знак новообретенного доверия мы посылаем вам в помощь аптекаря Силлу. Она посодействует в битве против нашего общего врага в Калимдоре. Никто не устоит перед нашей объединенной мощью и решимостью."$B$BВозможно, Назир Кровавое Копье из Деревни Гиблотопь знает, как распорядиться этой информацией.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте запечатанное письмо Назиру Кровавому Копью в Деревню Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если все и вправду так, то Отрекшимся придется объясниться!\n\nТаурены из Зловещего Тотема своими выходками давно испытывает терпение вождя. Мы обычно оставляли такие дела улаживать самим тауренам, но это письмо может все изменить.\n\nЭти подозрения еще надо проверить, так что никому не рассказывай о том, что видел сегодня.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что там у тебя, $C?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11187,'Маг-лейтенант Малистер','КАКОЙ УЖАС! Протодраконы напали на крепость!$B$BОбычно таких зверей легко отпугнуть, расправившись с их кладкой и детенышами.$B$BНо мы ведь все это уже испробовали, верно?$B$B$n, придется нам действовать более решительно. Поговори с моим советником, магом-лейтенаном Малистером. Он расскажет тебе, как разделаться с этими тварями.','Капитан Адамс попросил вас поговорить с его советником, магом-лейтенаном Малистером. Его можно найти в Крепости Западной Стражи.','<Малистер подзывает вас к себе и приглушенно шепчет.>$B$BЭтого-то я и боялся. Я пытался отговорить капитана, но он предпочитает сначала действовать, а потом думать.$B$BЛадно, давай посмотрим, что нам остается делать.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Маг-лейтенант Малистер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','КАКОЙ УЖАС! Протодраконы напали на крепость!$B$BОбычно таких зверей легко отпугнуть, расправившись с их кладкой и детенышами.$B$BНо мы ведь все это уже испробовали, верно?$B$B$n, придется нам действовать более решительно. Поговори с моим советником, магом-лейтенаном Малистером. Он расскажет тебе, как разделаться с этими тварями.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Адамс попросил вас поговорить с его советником, магом-лейтенаном Малистером. Его можно найти в Крепости Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Малистер подзывает вас к себе и приглушенно шепчет.>$B$BЭтого-то я и боялся. Я пытался отговорить капитана, но он предпочитает сначала действовать, а потом думать.$B$BЛадно, давай посмотрим, что нам остается делать.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11188,'Минус на минус','Теперь, когда мы разворошили гнездо протодраконов в Пылающем Гнездовье, они будут постоянно нападать на крепость. Этого мы не можем допустить.$B$BЯ, конечно, не люблю вышибать клин клином, но в данном случае нам остается только уничтожить этих созданий. Мне жаль, но другого пути нет. $B$BВозьми мою волшебную палочку. Вообще-то я пытался увеличить радиус ее действия, но ничего путного не вышло. Однако теперь она отлично привлекает внимание протодраконов.','Маг-лейтенант Малистер из Крепости Западной Стражи поручил вам уничтожить 3 протодраконов.','<Маг-лейтенант тяжело вздыхает.>$B$BДа, нелегкая тебе выпала доля. Ну, ладно – что сделано, то сделано. Надеюсь, новое поколение протодраконов из Пылающего Гнездовья не запомнит то, что мы с ними совершили.$B$BА если нам повезет, границы магического леса не будут расширяться.$B$BВот, $N, возьми этот скромный сувенир из нашей сокровищницы. Это самое малое, что мы можем для тебя сделать.','К сожалению, капитану пришлось заставить тебя разозлить протодраконов. Хотя им, кажется, не хватает интеллекта, они все же кажутся благородными существами. Не говоря уже о ситуации, в которую мы попадаем.$B$BОсмелюсь спросить, я...','Вернитесь к магу-лейтенанту Малистеру в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Минус на минус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы разворошили гнездо протодраконов в Пылающем Гнездовье, они будут постоянно нападать на крепость. Этого мы не можем допустить.$B$BЯ, конечно, не люблю вышибать клин клином, но в данном случае нам остается только уничтожить этих созданий. Мне жаль, но другого пути нет. $B$BВозьми мою волшебную палочку. Вообще-то я пытался увеличить радиус ее действия, но ничего путного не вышло. Однако теперь она отлично привлекает внимание протодраконов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Маг-лейтенант Малистер из Крепости Западной Стражи поручил вам уничтожить 3 протодраконов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Маг-лейтенант тяжело вздыхает.>$B$BДа, нелегкая тебе выпала доля. Ну, ладно – что сделано, то сделано. Надеюсь, новое поколение протодраконов из Пылающего Гнездовья не запомнит то, что мы с ними совершили.$B$BА если нам повезет, границы магического леса не будут расширяться.$B$BВот, $N, возьми этот скромный сувенир из нашей сокровищницы. Это самое малое, что мы можем для тебя сделать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','К сожалению, капитану пришлось заставить тебя разозлить протодраконов. Хотя им, кажется, не хватает интеллекта, они все же кажутся благородными существами. Не говоря уже о ситуации, в которую мы попадаем.$B$BОсмелюсь спросить, я...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магу-лейтенанту Малистеру в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11189,'В последний раз','Привет. Я что, умер? Судя по тому, что я болтаюсь над собственным телом, это действительно так.$B$BМ-да, какая жалость. Только я собрался сделать предложение Ирене, как на нас напали солдаты Плети. $B$BНо я знаю, что она все еще жива... я чувствую это. $B$B$C, не $gмог:могла; бы ты проводить меня к ней? Плеть все еще может видеть мою душу, и мне страшно даже подумать, что они могут со мной сделать. $B$BА мне бы так хотелось в последний раз взглянуть на ее прекрасное лицо. Прошу тебя, передай ей, что я ее люблю.','Сопроводите привидение исследователя Джарена к надзирательнице Ирене Каменная Мантия в Стальные ворота Ревущего фьорда.','Сопроводить призрак исследователя Джарена к Ирене Каменная Мантия','Вернитесь к надзирателю Ирене Каменной Мантии в Шепчущую теснину, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В последний раз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет. Я что, умер? Судя по тому, что я болтаюсь над собственным телом, это действительно так.$B$BМ-да, какая жалость. Только я собрался сделать предложение Ирене, как на нас напали солдаты Плети. $B$BНо я знаю, что она все еще жива... я чувствую это. $B$B$C, не $gмог:могла; бы ты проводить меня к ней? Плеть все еще может видеть мою душу, и мне страшно даже подумать, что они могут со мной сделать. $B$BА мне бы так хотелось в последний раз взглянуть на ее прекрасное лицо. Прошу тебя, передай ей, что я ее люблю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сопроводите привидение исследователя Джарена к надзирательнице Ирене Каменная Мантия в Стальные ворота Ревущего фьорда.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сопроводить призрак исследователя Джарена к Ирене Каменная Мантия',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к надзирателю Ирене Каменной Мантии в Шепчущую теснину, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11190,'К каждой пушке затычка','Вот скажи мне, $Gдружище:подруга;, какому умнику пришла в голову светлая мысль сделать наши пушки нестандартного размера? Теперь нам приходится изготавливать особые ядра каждый раз, когда кому-нибудь приспичит выстрелить из этой поганой штуковины! $B$BСлушай, я был бы тебе очень благодарен, если бы ты $gпоходил:походила; вокруг и $gсобрал:собрала; уже использованные снаряды. Судя по тому, как стреляют наши пушки, земли к югу и востоку отсюда должны быть просто усеяны боеприпасами. $B$B<Канонир разводит ладони, показывая, какого размера должны быть ядра.>$B$BЕй-богу, проще собрать их, чем отливать новые!','Канонир Эли поручил вам собрать 10 пушечных ядер и отнести их в Крепость Западной Стражи.','Слава тебе, $N, вечная слава!$B$BСложи их прямо там, где стоишь. Я поручу нашим ребятам загрузить их в пушки, и скоро нам можно будет не волноваться о количестве ядер – хватит всему Скорну!','Этак у нас скоро совсем не останется ядер, |3-6($C). А враги наши не спят, особенно в Скорне!$B$BНу теперь-то нам есть, чем стрелять, правда?','Вернитесь к канониру Эли в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','К каждой пушке затычка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот скажи мне, $Gдружище:подруга;, какому умнику пришла в голову светлая мысль сделать наши пушки нестандартного размера? Теперь нам приходится изготавливать особые ядра каждый раз, когда кому-нибудь приспичит выстрелить из этой поганой штуковины! $B$BСлушай, я был бы тебе очень благодарен, если бы ты $gпоходил:походила; вокруг и $gсобрал:собрала; уже использованные снаряды. Судя по тому, как стреляют наши пушки, земли к югу и востоку отсюда должны быть просто усеяны боеприпасами. $B$B<Канонир разводит ладони, показывая, какого размера должны быть ядра.>$B$BЕй-богу, проще собрать их, чем отливать новые!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Канонир Эли поручил вам собрать 10 пушечных ядер и отнести их в Крепость Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава тебе, $N, вечная слава!$B$BСложи их прямо там, где стоишь. Я поручу нашим ребятам загрузить их в пушки, и скоро нам можно будет не волноваться о количестве ядер – хватит всему Скорну!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Этак у нас скоро совсем не останется ядер, |3-6($C). А враги наши не спят, особенно в Скорне!$B$BНу теперь-то нам есть, чем стрелять, правда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к канониру Эли в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11191,'[DEPRECATED]This Old Lighthouse','Старый маяк к востоку отсюда уже давно не работает, но Бабс Шипокрутка до сих пор спит и видит, будто он снова светит.$B$BНе знаю, как она собирается это сделать, но, по идее, тогда кораблям будет легче заходить в порт и доставлять грузы, так что я не против. Лучше грузчиком в порту, чем солдатом на передовой, понимаешь ли.','Поговорите с Бабс Шипокруткой на маяке, что на островке к востоку от Терамора.','Хорошо. Я могу использовать любую помощь, которую вы можете предложить. Моя первая задача - снова зажечь эту лампу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]This Old Lighthouse',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Старый маяк к востоку отсюда уже давно не работает, но Бабс Шипокрутка до сих пор спит и видит, будто он снова светит.$B$BНе знаю, как она собирается это сделать, но, по идее, тогда кораблям будет легче заходить в порт и доставлять грузы, так что я не против. Лучше грузчиком в порту, чем солдатом на передовой, понимаешь ли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бабс Шипокруткой на маяке, что на островке к востоку от Терамора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо. Я могу использовать любую помощь, которую вы можете предложить. Моя первая задача - снова зажечь эту лампу.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11192,'[DEPRECATED]Thresher Oil','Из старого журнала маяка понятно, что фонарь заправляли жиром крепкозубов, что обитают на здешнем побережье.$B$B<Бабс морщит нос при одной мысли о столь отсталой технологии.>$B$BНадеюсь, это будет практичное, пусть и неизящное, решение проблемы. В журнале говорится, что лучший жир добывают из самых молодых черных крепкозубов, а они водятся прямо под доками Терамора.$B$BНе поможешь ли добыть топливо для фонаря, если, конечно, тебя не смущает такая работа?','Принесите 4 контейнера жира крепкозуба Бабс Шипокрутке на маяк близ Терамора.','Что ж, у меня есть сомнения, но на данный момент это единственное доступное решение. Я уверен, что как только он будет запущен и заработает, у нас будет время подумать о других способах заправки лампы.','Тебе удалось достать масло для молотилки?','Вернитесь к Бабс Шипокрутке на Остров Терамор, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Thresher Oil',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из старого журнала маяка понятно, что фонарь заправляли жиром крепкозубов, что обитают на здешнем побережье.$B$B<Бабс морщит нос при одной мысли о столь отсталой технологии.>$B$BНадеюсь, это будет практичное, пусть и неизящное, решение проблемы. В журнале говорится, что лучший жир добывают из самых молодых черных крепкозубов, а они водятся прямо под доками Терамора.$B$BНе поможешь ли добыть топливо для фонаря, если, конечно, тебя не смущает такая работа?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 4 контейнера жира крепкозуба Бабс Шипокрутке на маяк близ Терамора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, у меня есть сомнения, но на данный момент это единственное доступное решение. Я уверен, что как только он будет запущен и заработает, у нас будет время подумать о других способах заправки лампы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось достать масло для молотилки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бабс Шипокрутке на Остров Терамор, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11193,'[DEPRECATED]Dastardly Denizens of the Deep','Чего только не найдешь на старом маяке, знаешь ли. Когда я зажгла фонарь, то увидела вот эту книгу.$B$B<Бабс берет книгу и с выражением читает название.>$B$B"Подлые обитатели глубин!"$B$BНу, такое во сне увидишь – дубиной не отмахаешься! Наверное, стоит ее просмотреть по диагонали, но у меня сейчас совсем нет времени на чтение.$B$BТы, наверное, догадываешься, кому она может понравиться... да, тому рыбнику, "Весельчаку" Ленни Полечуду. Он собирает старые книги.','Отнесите книгу "Подлые обитатели глубин" "Весельчаку" Ленни Полечуду в доки Терамора.','Что ж, Бэбс подумал, что прислал это. Не знаю, пролистывали вы ее или нет, но в сказках этой книги много правды. Знаете, моряки не просто все это выдумали.','Что будет сегодня? Снук неплохой.','Поговорите с "Весельчаком" Ленни Полечудом на Острове Терамор, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Dastardly Denizens of the Deep',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чего только не найдешь на старом маяке, знаешь ли. Когда я зажгла фонарь, то увидела вот эту книгу.$B$B<Бабс берет книгу и с выражением читает название.>$B$B"Подлые обитатели глубин!"$B$BНу, такое во сне увидишь – дубиной не отмахаешься! Наверное, стоит ее просмотреть по диагонали, но у меня сейчас совсем нет времени на чтение.$B$BТы, наверное, догадываешься, кому она может понравиться... да, тому рыбнику, "Весельчаку" Ленни Полечуду. Он собирает старые книги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите книгу "Подлые обитатели глубин" "Весельчаку" Ленни Полечуду в доки Терамора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что ж, Бэбс подумал, что прислал это. Не знаю, пролистывали вы ее или нет, но в сказках этой книги много правды. Знаете, моряки не просто все это выдумали.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что будет сегодня? Снук неплохой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с "Весельчаком" Ленни Полечудом на Острове Терамор, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11194,'[DEPRECATED]Is it Real?','Да, вы с Бабс наверняка вволю посмеялись над нелепыми описаниями да картинками в этой книжонке. Однако я бы на вашем месте задумался: вдруг в этих легендах есть доля правды?$B$BКое-где до сих пор можно услышать рассказы моряков о Тетуре, морской твари, которая, судя по книжке, водится где-то здесь! Конечно, если хочешь знать наверняка, спроси старину Ната Пэгла.$B$BОн устроил себе небольшой лагерь на островке в Заливе Яростных Волн, что к юго-западу, за Пылевой бухтой.','Поговорите с Натом Пэглом в лагере Ната, что в Пылевых топях.','Итак, вы хотите знать о морских чудовищах? Хм... ну, я заключу с тобой сделку, но это будет связано с большим количеством алкоголя и некоторым смущением с твоей стороны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Is it Real?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, вы с Бабс наверняка вволю посмеялись над нелепыми описаниями да картинками в этой книжонке. Однако я бы на вашем месте задумался: вдруг в этих легендах есть доля правды?$B$BКое-где до сих пор можно услышать рассказы моряков о Тетуре, морской твари, которая, судя по книжке, водится где-то здесь! Конечно, если хочешь знать наверняка, спроси старину Ната Пэгла.$B$BОн устроил себе небольшой лагерь на островке в Заливе Яростных Волн, что к юго-западу, за Пылевой бухтой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Натом Пэглом в лагере Ната, что в Пылевых топях.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, вы хотите знать о морских чудовищах? Хм... ну, я заключу с тобой сделку, но это будет связано с большим количеством алкоголя и некоторым смущением с твоей стороны.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11195,'Игра в куклы','Я, наверное, сошел с ума, $n, вот в чем штука-то. Не помню, когда кто-то последний раз кто-то помогал Зунгаму за просто так.$B$BЯ стянул это у одного из дикарей, которые меня тут приковывали. На вид, штуковина неказистая, но тот, кто согласиться ее принять, будет мне хорошим другом!$B$BУж если мне свезет выбраться отсюда живым и непотресканным, я, пожалуй, стаскал бы эту штуку в Шаттрат и показал бы ему.','Отнесите потрепанную куклу вуду Жулю в Шаттрат.','Эй, где ты это $Gвзял:взяла;?$B$BНет, нет, не говори мне - это исходит от самого Хекс-Лорда! Теперь все ясно. Сильный моджо! Носитель этой реликвии, сколько бы позоров он ни претерпел, всегда будет почитаем его сверстниками. Невероятно!$B$B<Когда Грифтах держит куклу в воздухе, с ее шеи падает маленький ржавый амулет. Тролль начинает сбрасывать его, но затем поворачивается к вам с блеском в глазах.>$B$BУ меня сейчас нет монет, дружище, но добро пожаловать сюда...','Привет, $N! Я слышал, ты $Gработал:работала; в команде Бадда. Ты не доживешь до того момента,когда пожалеешь об этом шаге, друг, я могу тебе это обещать.$B$BЧто там у тебя, $Gдружище:подружка;?','Вернитесь к Жулю в Шаттрат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игра в куклы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я, наверное, сошел с ума, $n, вот в чем штука-то. Не помню, когда кто-то последний раз кто-то помогал Зунгаму за просто так.$B$BЯ стянул это у одного из дикарей, которые меня тут приковывали. На вид, штуковина неказистая, но тот, кто согласиться ее принять, будет мне хорошим другом!$B$BУж если мне свезет выбраться отсюда живым и непотресканным, я, пожалуй, стаскал бы эту штуку в Шаттрат и показал бы ему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8