INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`,`questgivertargetname_loc8`) VALUES (11196,'Вождь Амани','Племя Амани собирает силы, и теперь у них новый вождь, $n. Его зовут Даакара Непобедимый. Но мы еще посмотрим, поможет ли ему выжить его имя.$b$bСначала разберись с его лейтенантами, чтобы никто тебе не мешал. А затем переходи к Даакаре. Уничтожь его и положи конец всем притязаниям племен Зандалар и Амани!','Победите нового вождя племени Амани, Даакару.','Вернитесь к Вол\'джину в Зул\'Аман.','Даакара, вождь племени Амани.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вождь Амани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Племя Амани собирает силы, и теперь у них новый вождь, $n. Его зовут Даакара Непобедимый. Но мы еще посмотрим, поможет ли ему выжить его имя.$b$bСначала разберись с его лейтенантами, чтобы никто тебе не мешал. А затем переходи к Даакаре. Уничтожь его и положи конец всем притязаниям племен Зандалар и Амани!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите нового вождя племени Амани, Даакару.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вол\'джину в Зул\'Аман.',`completedtext_loc8`), `questgivertargetname_loc8`=IF(`questgivertargetname_loc8` IS NULL OR `questgivertargetname_loc8`='','Даакара, вождь племени Амани.',`questgivertargetname_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11197,'ZZOLD Upper Deck Promo – Верховой призрачный волк OLD') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ZZOLD Upper Deck Promo – Верховой призрачный волк OLD',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11198,'[DEPRECATED]Take Down Tethyr!','Чудовище это или нет, мы не станем рисковать безопасностью наших морских перевозок. Я приказал нашим лучшим стрелкам приготовиться к бою с Тетуром. Артиллеристы усилили оборону доков тремя мортирами.$B$BЯ намерен приказать зажечь маяк. Если Тетур пойдет в атаку, твоя задача будет стрелять из мортир и прикончить тварь прежде, чем он убьет всех наших стрелков. При этом я не стал бы долго стоять на одном месте. Стрельба из мортир обязательно привлечет его внимание.','Майор Миллз из доков Терамора хочет, чтобы вы покончили с Тетуром.','$GМолодец:Умница;, $N! Признаюсь, когда я впервые увидел этого зверя, я усомнился в нашей способности защищать доки, но вы блестяще cправились!','Сделайте свой отчет.','Защитите тераморские доки от Тетура.','Вернитесь к Майору Миллзу на Остров Терамор, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Take Down Tethyr!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чудовище это или нет, мы не станем рисковать безопасностью наших морских перевозок. Я приказал нашим лучшим стрелкам приготовиться к бою с Тетуром. Артиллеристы усилили оборону доков тремя мортирами.$B$BЯ намерен приказать зажечь маяк. Если Тетур пойдет в атаку, твоя задача будет стрелять из мортир и прикончить тварь прежде, чем он убьет всех наших стрелков. При этом я не стал бы долго стоять на одном месте. Стрельба из мортир обязательно привлечет его внимание.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Майор Миллз из доков Терамора хочет, чтобы вы покончили с Тетуром.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N! Признаюсь, когда я впервые увидел этого зверя, я усомнился в нашей способности защищать доки, но вы блестяще cправились!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сделайте свой отчет.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитите тераморские доки от Тетура.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Майору Миллзу на Остров Терамор, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11199,'Доклад разведчика Ноулса','Теперь, $n, когда мы разобрались с этими проклятыми прототварями, я хочу поручить тебе другое задание. $B$BОдин из моих разведчиков доложил о некоей подозрительной деятельности Отрекшихся на юге. Похоже, что они обосновались в врайкульской деревне Халгринд и строят некие зловещие планы.$B$BЯ надеюсь, что ты лично займешься расследованием этого дела. Поговори с разведчиком Ноулсом, выясни, что ему удалось узнать, и начинай действовать.$B$BПоследний раз он докладывал свое местоположение у Тлеющей башни, к западу от Халгринда.','Капитан Адамс попросил вас разыскать разведчика Ноулса у Тлеющей башни.','Наконец-то, помощь прибыла!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доклад разведчика Ноулса',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, $n, когда мы разобрались с этими проклятыми прототварями, я хочу поручить тебе другое задание. $B$BОдин из моих разведчиков доложил о некоей подозрительной деятельности Отрекшихся на юге. Похоже, что они обосновались в врайкульской деревне Халгринд и строят некие зловещие планы.$B$BЯ надеюсь, что ты лично займешься расследованием этого дела. Поговори с разведчиком Ноулсом, выясни, что ему удалось узнать, и начинай действовать.$B$BПоследний раз он докладывал свое местоположение у Тлеющей башни, к западу от Халгринда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Адамс попросил вас разыскать разведчика Ноулса у Тлеющей башни.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то, помощь прибыла!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11200,'[DEPRECATED]More than Coincidence','Мы выяснили на пепелище таверны все, что могли. Боюсь представить, куда нас заведет это расследование, но мы должны узнать правду.$B$BСледы копыт и щит с клеймом Мозарна дают повод полагать, что в это дело может быть замешан Зловещий Тотем. Они недавно построили на болотах, к северо-востоку отсюда, поселение, деревню Черного Копыта. Отправляйся туда и поищи еще какое-нибудь оружие работы Мозарна.','Крог из Деревни Гиблотопь хочет, чтобы вы принесли ему 7 предметов оружия Черного Копыта.','Крог рассматривает оружие, принесенное вами из деревни Черного Копыта.\n\nЯвно работа Мозарна. Дальнейшее расследование привлечет слишком много внимания, но теперь у нас развязаны руки для борьбы со Зловещим Тотемом.','Что показали твои поиски в Деревне Черного Копыта?','Вернитесь к Крогу в деревню Гиблотопь, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]More than Coincidence',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы выяснили на пепелище таверны все, что могли. Боюсь представить, куда нас заведет это расследование, но мы должны узнать правду.$B$BСледы копыт и щит с клеймом Мозарна дают повод полагать, что в это дело может быть замешан Зловещий Тотем. Они недавно построили на болотах, к северо-востоку отсюда, поселение, деревню Черного Копыта. Отправляйся туда и поищи еще какое-нибудь оружие работы Мозарна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Крог из Деревни Гиблотопь хочет, чтобы вы принесли ему 7 предметов оружия Черного Копыта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Крог рассматривает оружие, принесенное вами из деревни Черного Копыта.\n\nЯвно работа Мозарна. Дальнейшее расследование привлечет слишком много внимания, но теперь у нас развязаны руки для борьбы со Зловещим Тотемом.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что показали твои поиски в Деревне Черного Копыта?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крогу в деревню Гиблотопь, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11201,'[DEPRECATED]The Grimtotem Plot','Теперь, когда дела племени Зловещего Тотема в Тысяче Игл стали известны всем, многие таурены начали косо смотреть на них. Мы знаем, что вожди племени замешаны в убийстве и похищениях ради достижения своих целей, и я опасаюсь, что следующей их целью станем именно мы.$B$BДеревня Черного Копыта, что на северо-востоке, рядом с Синей топью – новое крупное поселение племени Зловещий Тотем. Их старейшины получают приказы из Громового Утеса. Посмотри, не сумеешь ли ты перехватить приказы и выяснить, что задумывают эти таурены.','Принесите боевые планы клана Зловещего Тотема Крогу в Деревню Гиблотопь.','Крог читает боевые планы.\n\nВ том, что Зловещий Тотем двинется на людей, сомнений нет. Но что он замышляет против нас? Действия этого клана давно вызывают беспокойство в рядах Орды, но вождю до сих пор удавалось рассеивать его.','Удалось ли найти какие-либо следы?','Вернитесь к Крогу в Пылевые топи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]The Grimtotem Plot',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда дела племени Зловещего Тотема в Тысяче Игл стали известны всем, многие таурены начали косо смотреть на них. Мы знаем, что вожди племени замешаны в убийстве и похищениях ради достижения своих целей, и я опасаюсь, что следующей их целью станем именно мы.$B$BДеревня Черного Копыта, что на северо-востоке, рядом с Синей топью – новое крупное поселение племени Зловещий Тотем. Их старейшины получают приказы из Громового Утеса. Посмотри, не сумеешь ли ты перехватить приказы и выяснить, что задумывают эти таурены.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите боевые планы клана Зловещего Тотема Крогу в Деревню Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Крог читает боевые планы.\n\nВ том, что Зловещий Тотем двинется на людей, сомнений нет. Но что он замышляет против нас? Действия этого клана давно вызывают беспокойство в рядах Орды, но вождю до сих пор удавалось рассеивать его.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли найти какие-либо следы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Крогу в Пылевые топи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11202,'Задание: вечный огонь','Насколько мне известно, Отрекшиеся задумали нечто недоброе, и эти контейнеры с чумой имеют прямое отношение к их зловещим планам. $B$BОсмелюсь предположить, $n, что нам следует уничтожить эти ящики прежде, чем Отрекшиеся смогут ими воспользоваться. Я взял на себя смелость принести несколько факелов из Пылающего Гнездовья. Эти штуки горят уже несколько дней!$B$BВот, возьми – у тебя лучше получится поджечь эти контейнеры.','Разведчик Ноулс посоветовал вам воспользоваться неугасимыми факелами, чтобы уничтожить четыре контейнера с чумой, окружающих Халгринд.','С самого начала было трудно сказать, что именно там происходит. Тебе удалось поджечь эти чумные танки?','Вернитесь к разведчику Ноулсу в Тлеющую башню, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание: вечный огонь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько мне известно, Отрекшиеся задумали нечто недоброе, и эти контейнеры с чумой имеют прямое отношение к их зловещим планам. $B$BОсмелюсь предположить, $n, что нам следует уничтожить эти ящики прежде, чем Отрекшиеся смогут ими воспользоваться. Я взял на себя смелость принести несколько факелов из Пылающего Гнездовья. Эти штуки горят уже несколько дней!$B$BВот, возьми – у тебя лучше получится поджечь эти контейнеры.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разведчик Ноулс посоветовал вам воспользоваться неугасимыми факелами, чтобы уничтожить четыре контейнера с чумой, окружающих Халгринд.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С самого начала было трудно сказать, что именно там происходит. Тебе удалось поджечь эти чумные танки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Ноулсу в Тлеющую башню, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11203,'[DEPRECATED]Seek Out Tabetha','Оружие, которое ты $Gзахватил:захватила; в деревне Черного Копыта, никогда не видело других сражений, кроме тренировочного боя, что говорит о том, что Зловещих Тотемов, разрушивших "Последний привал", еще много.$B$BНа юге, в самом сердце Трясины, живет ведьма Табета. Хотя она и человек, но ведет себя с нами по чести и воспитывала некоторых наших магов.$B$BПопроси у нее помощи в поисках Зловещего Тотема, который сжег гостиницу. Альянс не должен считать, что мы замешаны в этом нападении.','Поговорите с Табетой в ее усадьбе на Трясине.','Табета еле заметно улыбается.\n\nКрог хочет, чтобы я погадала ему насчет Зловещего Тотема? Ну, тут мне магия не нужна.\n\nПохоже, у нас общий враг. Зловещий Тотем устроил заставу по соседству, и теперь житья от него нет ни мне, ни моим ученикам.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Seek Out Tabetha',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Оружие, которое ты $Gзахватил:захватила; в деревне Черного Копыта, никогда не видело других сражений, кроме тренировочного боя, что говорит о том, что Зловещих Тотемов, разрушивших "Последний привал", еще много.$B$BНа юге, в самом сердце Трясины, живет ведьма Табета. Хотя она и человек, но ведет себя с нами по чести и воспитывала некоторых наших магов.$B$BПопроси у нее помощи в поисках Зловещего Тотема, который сжег гостиницу. Альянс не должен считать, что мы замешаны в этом нападении.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Табетой в ее усадьбе на Трясине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Табета еле заметно улыбается.\n\nКрог хочет, чтобы я погадала ему насчет Зловещего Тотема? Ну, тут мне магия не нужна.\n\nПохоже, у нас общий враг. Зловещий Тотем устроил заставу по соседству, и теперь житья от него нет ни мне, ни моим ученикам.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11204,'[DEPRECATED]Return to Krog','Надеюсь, я тебе помог. Увы, больше у меня нет никаких сведений. Мы с учениками сделали столько оружия и доспехов, что всего и не упомнишь.$B$BМы ведь снаряжаем не только отважных бойцов, защищающих земли тауренов, – мои изделия также ценятся среди членов клана Зловещего Тотема. Опытный воин узнает хорошую работу с первого взгляда.','Поговорите с Крогом в Деревне Гиблотопь.','Он действительно сказал, что Зловещий Тотем – самый крупный его заказчик? Мозарн помог нам куда больше, чем думает. Против Зловещего Тотема столько улик, что мы спокойно можем огласить их первыми подозреваемыми.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Return to Krog',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Надеюсь, я тебе помог. Увы, больше у меня нет никаких сведений. Мы с учениками сделали столько оружия и доспехов, что всего и не упомнишь.$B$BМы ведь снаряжаем не только отважных бойцов, защищающих земли тауренов, – мои изделия также ценятся среди членов клана Зловещего Тотема. Опытный воин узнает хорошую работу с первого взгляда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Крогом в Деревне Гиблотопь.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Он действительно сказал, что Зловещий Тотем – самый крупный его заказчик? Мозарн помог нам куда больше, чем думает. Против Зловещего Тотема столько улик, что мы спокойно можем огласить их первыми подозреваемыми.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11205,'[DEPRECATED]Raze Direhorn Post!','Незачем гадать, чтобы увидеть угрозу, которая исходит от моих "соседей". И если это та самая банда, что сожгла "Последний привал", как ты говоришь, то нужно действовать немедля.$B$BБери вот этот факел и предай их лагерь огню! Ты найдешь заставу Дикого Рога к северу от моей усадьбы, возле дороги. Пропустить ее совершенно невозможно, эти варвары уже успели наставить вокруг свои драгоценные тотемы.','Сожгите северный, восточный и северо-западный шатры на заставе Дикого Рога, затем вернитесь в усадьбу Табеты.','Надеюсь, в Зловещем Тотеме без труда уразумеют, что им хотели сказать.\n\nА что касается тебя, то твой осведомитель в Деревне Гиблотопь захочет узнать, каковы твои успехи. Я понимаю, что разрушение таверны "Последний привал" может вызвать напряжение между Ордой и Альянсом. Если я встречу следователей из Терамора, то с радостью сообщу, что Зловещий Тотем действовал по собственной инициативе.','Вы применили этот фонарик с пользой?','Вернитесь к Табете на ферму, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Raze Direhorn Post!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Незачем гадать, чтобы увидеть угрозу, которая исходит от моих "соседей". И если это та самая банда, что сожгла "Последний привал", как ты говоришь, то нужно действовать немедля.$B$BБери вот этот факел и предай их лагерь огню! Ты найдешь заставу Дикого Рога к северу от моей усадьбы, возле дороги. Пропустить ее совершенно невозможно, эти варвары уже успели наставить вокруг свои драгоценные тотемы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сожгите северный, восточный и северо-западный шатры на заставе Дикого Рога, затем вернитесь в усадьбу Табеты.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, в Зловещем Тотеме без труда уразумеют, что им хотели сказать.\n\nА что касается тебя, то твой осведомитель в Деревне Гиблотопь захочет узнать, каковы твои успехи. Я понимаю, что разрушение таверны "Последний привал" может вызвать напряжение между Ордой и Альянсом. Если я встречу следователей из Терамора, то с радостью сообщу, что Зловещий Тотем действовал по собственной инициативе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы применили этот фонарик с пользой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Табете на ферму, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11206,'[DEPRECATED]Justice Dispensed','Сомневаюсь, чтобы Зловещий Тотем оставил свои планы выжить людей с болот. Хотя ты, я смотрю, $gбыл:была; бы не против. Но по крайней мере, мы разобрались с ответственными за поджог "Последнего привала".$B$Bиди и поведай своему предводителю, что правосудие свершилось.','Вернитесь к Крогу в Деревню Гиблотопь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Justice Dispensed',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сомневаюсь, чтобы Зловещий Тотем оставил свои планы выжить людей с болот. Хотя ты, я смотрю, $gбыл:была; бы не против. Но по крайней мере, мы разобрались с ответственными за поджог "Последнего привала".$B$Bиди и поведай своему предводителю, что правосудие свершилось.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Крогу в Деревню Гиблотопь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11207,'[DEPRECATED]Secure the Cargo!','Этот дирижабль вез шестимесячный запас припасов для Шестермути! Конечно, кое-что они смогут выменять, но долго они не продержатся.$B$BМеня послали сюда спасти хотя бы часть груза, но обломки рассыпаны по всем окрестным болотам! Понятно, что изрядная часть груза при крушении была уничтожена, тем не менее, может, ты поможешь мне спасти то, что осталось?','Мокси Сталегриль на месте крушения дирижабля Бизила просит вас собрать 8 ящиков с грузом из дирижабля.','Ого! Ты нашел намного больше, чем я ожидала! Не знаю уж, на какую часть груза рассчитывал Драззит, отправляя нас сюда, но он будет просто вне себя от восторга.','*Дерзи просто вне себя от волнения.*\n\nГруз уцелел? Тебе удалось хоть что-то найти?','Вернитесь к Мокси Сталегриль на место крушения дирижабля Бизила, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Secure the Cargo!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот дирижабль вез шестимесячный запас припасов для Шестермути! Конечно, кое-что они смогут выменять, но долго они не продержатся.$B$BМеня послали сюда спасти хотя бы часть груза, но обломки рассыпаны по всем окрестным болотам! Понятно, что изрядная часть груза при крушении была уничтожена, тем не менее, может, ты поможешь мне спасти то, что осталось?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мокси Сталегриль на месте крушения дирижабля Бизила просит вас собрать 8 ящиков с грузом из дирижабля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ого! Ты нашел намного больше, чем я ожидала! Не знаю уж, на какую часть груза рассчитывал Драззит, отправляя нас сюда, но он будет просто вне себя от восторга.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','*Дерзи просто вне себя от волнения.*\n\nГруз уцелел? Тебе удалось хоть что-то найти?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мокси Сталегриль на место крушения дирижабля Бизила, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11208,'Поставка для Драззита','Драззит ожидает вскорости получить от меня вести, но место мне кажется довольно опасным, чтобы ехать туда самой. Если у тебя найдется время, не свезешь ли ты часть спасенного груза ему в Шестермуть?$B$BЭто небольшое поселение к юго-западу отсюда, за руинами Деревни Каменного Молота, если тебе еще не доводилось там бывать. Также туда можно дойти по дороге от усадьбы Табеты. Когда доберешься до Шестермути, ищи парня по имени Драззит Кранотек.','Доставьте груз с дирижабля Драззиту Кранотеку в Шестермуть.','Да?','Вернитесь к Драззиту Кранотеку в Шестермуть, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поставка для Драззита',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Драззит ожидает вскорости получить от меня вести, но место мне кажется довольно опасным, чтобы ехать туда самой. Если у тебя найдется время, не свезешь ли ты часть спасенного груза ему в Шестермуть?$B$BЭто небольшое поселение к юго-западу отсюда, за руинами Деревни Каменного Молота, если тебе еще не доводилось там бывать. Также туда можно дойти по дороге от усадьбы Табеты. Когда доберешься до Шестермути, ищи парня по имени Драззит Кранотек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте груз с дирижабля Драззиту Кранотеку в Шестермуть.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Драззиту Кранотеку в Шестермуть, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11209,'[DEPRECATED]Nat\'s Bargain','Значит, ты $Gнашел:нашла; экземпляр "Подлых обитателей глубин"? Что же, скажу по собственному опыту: все, что там написано, – правда. Кое-кого я собственными глазами видел.$B$BНо ты спрашиваешь про Тетура. Давай договоримся. Вот что мне от тебя надо: я тут разрабатываю новую линию наживок, но вот эту я еще не испытывал.$B$BВозьми эту пасту – да, запашок у нее не из приятных – намажься ею и плыви к тому разбитому кораблю на юго-запад. Выживешь – расскажешь, как все прошло!','Нат Пэгл из лагеря Ната хочет, чтобы вы испытали его новую наживку для рыбы.','Совсем неплохо, но знаешь, я бы принял ванну как можно скорее, на твоем месте.','Помни, главное - «не возвращайся, пока что-то тебя не укусит».','Вернитесь к Нату Пэглу в Лагерь Ната, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Nat\'s Bargain',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, ты $Gнашел:нашла; экземпляр "Подлых обитателей глубин"? Что же, скажу по собственному опыту: все, что там написано, – правда. Кое-кого я собственными глазами видел.$B$BНо ты спрашиваешь про Тетура. Давай договоримся. Вот что мне от тебя надо: я тут разрабатываю новую линию наживок, но вот эту я еще не испытывал.$B$BВозьми эту пасту – да, запашок у нее не из приятных – намажься ею и плыви к тому разбитому кораблю на юго-запад. Выживешь – расскажешь, как все прошло!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Нат Пэгл из лагеря Ната хочет, чтобы вы испытали его новую наживку для рыбы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Совсем неплохо, но знаешь, я бы принял ванну как можно скорее, на твоем месте.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Помни, главное - «не возвращайся, пока что-то тебя не укусит».',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нату Пэглу в Лагерь Ната, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11210,'[DEPRECATED]Oh, It\'s Real','Да, Тетур вполне настоящий, и живет он в тераморских водах.$B$BПриходит на яркий огонь. Именно поэтому маяк там и не зажигают...$B$BСтоит его зажечь, как чудище вернется. Но в здравом уме никто на это не пойдет.$B$BСоответственно, это работка для тебя. Приятно было с тобой выпить, но не обижайся на Ната, если Тетур на самом деле примет тебя за наживку. Если ты намереваешься с ним повидаться, поговори сначала с майором Миллзом из доков Терамора.','Поговорите с майором Миллзом в доках Терамора.','<Вы рассказываете о своем опыте с Нэтом Пэглом, осторожно опуская часть о «приманке».>$B$BНу, похоже, у нас есть работа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Oh, It\'s Real',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, Тетур вполне настоящий, и живет он в тераморских водах.$B$BПриходит на яркий огонь. Именно поэтому маяк там и не зажигают...$B$BСтоит его зажечь, как чудище вернется. Но в здравом уме никто на это не пойдет.$B$BСоответственно, это работка для тебя. Приятно было с тобой выпить, но не обижайся на Ната, если Тетур на самом деле примет тебя за наживку. Если ты намереваешься с ним повидаться, поговори сначала с майором Миллзом из доков Терамора.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с майором Миллзом в доках Терамора.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вы рассказываете о своем опыте с Нэтом Пэглом, осторожно опуская часть о «приманке».>$B$BНу, похоже, у нас есть работа.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11211,'Помощь деревне Шестермуть','Когда та гоблинша... как бишь ее там... Токси, Рокси... Мокси, вот! Короче, когда она проезжала здесь к месту крушения дирижабля, то говорила, что в деревне Шестермуть какие-то проблемы.$B$BЭтот разбившийся дирижабль вез им свежие припасы. Если поедешь отсюда по южной дороге мимо руин Деревни Каменного Молота, в конце концов упрешься в Шестермуть.$B$BПочему бы тебе там не встретиться с Драззитом Кранотеком и не спросить, какая помощь нужна?','Поговорите в Шестермути с Драззитом Кранотеком.','Хорошо, что Табета прислала тебя. Неплохо было бы, если б она передала каких-то припасов, пока сюда не доставят груз с разбившегося дирижабля, но, как мне известно, сейчас ей просто нечем поделиться. Если у тебя есть вкус к приключениям, то я назначил награду за одного особенно противного ящера.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь деревне Шестермуть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда та гоблинша... как бишь ее там... Токси, Рокси... Мокси, вот! Короче, когда она проезжала здесь к месту крушения дирижабля, то говорила, что в деревне Шестермуть какие-то проблемы.$B$BЭтот разбившийся дирижабль вез им свежие припасы. Если поедешь отсюда по южной дороге мимо руин Деревни Каменного Молота, в конце концов упрешься в Шестермуть.$B$BПочему бы тебе там не встретиться с Драззитом Кранотеком и не спросить, какая помощь нужна?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Шестермути с Драззитом Кранотеком.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что Табета прислала тебя. Неплохо было бы, если б она передала каких-то припасов, пока сюда не доставят груз с разбившегося дирижабля, но, как мне известно, сейчас ей просто нечем поделиться. Если у тебя есть вкус к приключениям, то я назначил награду за одного особенно противного ящера.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11212,'Ферма Табеты','Среди болот живет старая женщина по имени Табета. Мы немного знаем о ней – пожалуй, только то, что она куда старше, чем кажется. Она время от времени помогает нам, пока что ей удается поддерживать здесь мир между нашими силами и Ордой.$B$BОбычно она держала с нами постоянную связь, но недавно эта связь прервалась.$B$BЕсли у тебя выдастся минутка, может, проведаешь ее? Иди по дороге мимо Северной башни, там она сворачивает на юг к Трясине. Усадьбу Табеты видно с дороги.','Поговорите с Табетой в ее усадьбе на Трясине.','Хорошо, что Терамор прислал сюда хоть кого-то. Опасения вашего приятеля-стража небезосновательны. У нас появились новые соседи, и добрыми их никак не назовешь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ферма Табеты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среди болот живет старая женщина по имени Табета. Мы немного знаем о ней – пожалуй, только то, что она куда старше, чем кажется. Она время от времени помогает нам, пока что ей удается поддерживать здесь мир между нашими силами и Ордой.$B$BОбычно она держала с нами постоянную связь, но недавно эта связь прервалась.$B$BЕсли у тебя выдастся минутка, может, проведаешь ее? Иди по дороге мимо Северной башни, там она сворачивает на юг к Трясине. Усадьбу Табеты видно с дороги.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Табетой в ее усадьбе на Трясине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо, что Терамор прислал сюда хоть кого-то. Опасения вашего приятеля-стража небезосновательны. У нас появились новые соседи, и добрыми их никак не назовешь.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11213,'Навестить Табету','Среди болот в маленькой усадьбе живет человеческая женщина по имени Табета. Обычно я дел с людьми не веду, но она не раз нам помогала.$B$BОднако в последнее время я не могу с ней связаться, так что ищу кого-нибудь, кто пошел бы в ее усадьбу да проверил, все ли там ладно.$B$BЕсли пойдешь по дороге на юг из деревни, а затем свернешь на болота, то найдешь ее усадьбу в самом сердце Трясины.','Поговорите с Табетой в ее усадьбе на Трясине.','Назир очень кстати решил послать кого-нибудь сюда. У нас появились новые соседи, и с тех пор жить стало просто невыносимо.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Навестить Табету',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среди болот в маленькой усадьбе живет человеческая женщина по имени Табета. Обычно я дел с людьми не веду, но она не раз нам помогала.$B$BОднако в последнее время я не могу с ней связаться, так что ищу кого-нибудь, кто пошел бы в ее усадьбу да проверил, все ли там ладно.$B$BЕсли пойдешь по дороге на юг из деревни, а затем свернешь на болота, то найдешь ее усадьбу в самом сердце Трясины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Табетой в ее усадьбе на Трясине.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Назир очень кстати решил послать кого-нибудь сюда. У нас появились новые соседи, и с тех пор жить стало просто невыносимо.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11214,'[DEPRECATED]Mission to Mudsprocket','Недавно картель Хитрой Шестеренки основал новый форпост в южной части Пылевых топей. Насколько помню, зовется он Шестермуть и расположен на главной дороге, что ведет к югу от усадьбы Табеты и руин Деревни Каменного Молота.$B$BЭто дает замечательную возможность установить новые торговые связи, и леди Джайна хочет, чтобы я послал туда представителя. Не согласишься ли ты выполнить эту миссию?','Поговорите с Драззитом Кранотеком в Шестермути.','Значит, Терамор заинтересован в ведении бизнеса? Ну, это не то предложение, от которого я бы отказался. Здесь сейчас довольно мало припасов, поэтому нам нужны все возможные деловые контакты!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Mission to Mudsprocket',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно картель Хитрой Шестеренки основал новый форпост в южной части Пылевых топей. Насколько помню, зовется он Шестермуть и расположен на главной дороге, что ведет к югу от усадьбы Табеты и руин Деревни Каменного Молота.$B$BЭто дает замечательную возможность установить новые торговые связи, и леди Джайна хочет, чтобы я послал туда представителя. Не согласишься ли ты выполнить эту миссию?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Драззитом Кранотеком в Шестермути.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Терамор заинтересован в ведении бизнеса? Ну, это не то предложение, от которого я бы отказался. Здесь сейчас довольно мало припасов, поэтому нам нужны все возможные деловые контакты!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11215,'Помощь Шестермути','На новом форпосте картеля Хитрой Шестеренки в южной части Трясин дела не так уж и хороши. Дирижабль с припасами для Шестермути разбился, и они остались без жизненно необходимых инструментов, провизии и медикаментов.$B$BИди по дороге на юг, прямо в глубь болот. Ты пройдешь усадьбу Табеты и руины Деревни Каменного Молота, прежде чем дорога приведет тебя в Шестермуть. Помоги городскому управлению, чем сможешь.','Поговорите с Драззитом Кранотеком в Шестермути.','Я не откажусь от любой помощи! Мы тут как раз обживаемся, поэтому используем все доступные средства на полную катушку, пока дирижабль не доставил груз.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помощь Шестермути',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На новом форпосте картеля Хитрой Шестеренки в южной части Трясин дела не так уж и хороши. Дирижабль с припасами для Шестермути разбился, и они остались без жизненно необходимых инструментов, провизии и медикаментов.$B$BИди по дороге на юг, прямо в глубь болот. Ты пройдешь усадьбу Табеты и руины Деревни Каменного Молота, прежде чем дорога приведет тебя в Шестермуть. Помоги городскому управлению, чем сможешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Драззитом Кранотеком в Шестермути.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не откажусь от любой помощи! Мы тут как раз обживаемся, поэтому используем все доступные средства на полную катушку, пока дирижабль не доставил груз.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (11216,'Верховный маг Альтур','Поговорите с верховным магом Альтуром близ Каражана на перевале Мертвого Ветра.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верховный маг Альтур',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с верховным магом Альтуром близ Каражана на перевале Мертвого Ветра.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11217,'[DEPRECATED]Catch a Dragon by the Tail','Поскольку дирижабль разбился, поставка задерживается, и мы остались без медикаментов и бинтов.$B$BМы используем все, что можем, но среди всех этих насекомых, отбиваясь от врагов и неся потери, мы вряд ли продержимся долго! Я нашел тут одну травку, которая, сдается, помогает при лечении любых ран и притупляет боль, но и ее мало.$B$BОна называется змейкин хвост, ее целые заросли в Земле Драконов и Драконьих топях к востоку от города. Сами растения представляют собой свившиеся кольцами стебли. Когда смотришь на них, кажется, будто они пульсируют.','Гиззикс Грязебульк из Шестермути просит принести ему 8 стеблей змейкиного хвоста.','Спасибо тебе! Теперь наши парни продержатся в поле, пока Дерзи не доставит груз, оставшийся после крушения дирижабля.','Ты нашел, где растет змеехвостка?','Вернитесь к Гиззиксу Грязебульку в Шестермуть, что в Пылевых топях.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Catch a Dragon by the Tail',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поскольку дирижабль разбился, поставка задерживается, и мы остались без медикаментов и бинтов.$B$BМы используем все, что можем, но среди всех этих насекомых, отбиваясь от врагов и неся потери, мы вряд ли продержимся долго! Я нашел тут одну травку, которая, сдается, помогает при лечении любых ран и притупляет боль, но и ее мало.$B$BОна называется змейкин хвост, ее целые заросли в Земле Драконов и Драконьих топях к востоку от города. Сами растения представляют собой свившиеся кольцами стебли. Когда смотришь на них, кажется, будто они пульсируют.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гиззикс Грязебульк из Шестермути просит принести ему 8 стеблей змейкиного хвоста.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо тебе! Теперь наши парни продержатся в поле, пока Дерзи не доставит груз, оставшийся после крушения дирижабля.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел, где растет змеехвостка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гиззиксу Грязебульку в Шестермуть, что в Пылевых топях.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11218,'Осторожно! Взрывчатка!','$n, капитан поручил мне задание, с которым мне не справиться без твоей помощи.$B$BМои товарищи из Лиги исследователей отправились на север, вести раскопки в Шепчущей теснине, и что-то в этом месте свело их с ума. Теперь они нападают на всех, кто осмеливается к ним приблизиться. $B$BА капитана заботит только руда для крепости! К счастью, я знаю, как решить эту проблему.$B$BОтправляйся туда, взорви месторождение и принеси сюда осколки руды вместе с драгоценными камнями. Эта раскопки недешево нам обходятся, знаешь ли.$B$BПравда, должен тебя предупредить – это очень странная руда!','Воспользуйтесь динамитом Стальной Чеки, чтобы собрать 6 кусков руды из Шепчущей теснины и 18 драгоценных камней из Шепчущей теснины. Затем принесите руду и камни саперу Стальной Чеке в Крепость Западной Стражи.','Говоришь, тебе было неприятно прикасаться к этой руде? Может быть, нам не стоит больше ее использовать.$B$B<Стальная Чека бросает быстрый взгляд на вашу добычу и быстро меняет тему разговора.>$B$BКакие симпатичные камешки! Интересно, сколько удастся за них выручить? Ну конечно, эти деньги пойдут на ремонт и новые инструменты...$B$BЗнаешь, с тобой довольно выгодно сотрудничать! Вот, возьми... это самое малое, что я могу для тебя сделать.','Кажется, мы никогда не закончим возводить эту крепость. Надеюсь, ты несешь нам припасы, необходимые для продолжения строительства.','Вернитесь к саперу Стальной Чеке в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осторожно! Взрывчатка!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, капитан поручил мне задание, с которым мне не справиться без твоей помощи.$B$BМои товарищи из Лиги исследователей отправились на север, вести раскопки в Шепчущей теснине, и что-то в этом месте свело их с ума. Теперь они нападают на всех, кто осмеливается к ним приблизиться. $B$BА капитана заботит только руда для крепости! К счастью, я знаю, как решить эту проблему.$B$BОтправляйся туда, взорви месторождение и принеси сюда осколки руды вместе с драгоценными камнями. Эта раскопки недешево нам обходятся, знаешь ли.$B$BПравда, должен тебя предупредить – это очень странная руда!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь динамитом Стальной Чеки, чтобы собрать 6 кусков руды из Шепчущей теснины и 18 драгоценных камней из Шепчущей теснины. Затем принесите руду и камни саперу Стальной Чеке в Крепость Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Говоришь, тебе было неприятно прикасаться к этой руде? Может быть, нам не стоит больше ее использовать.$B$B<Стальная Чека бросает быстрый взгляд на вашу добычу и быстро меняет тему разговора.>$B$BКакие симпатичные камешки! Интересно, сколько удастся за них выручить? Ну конечно, эти деньги пойдут на ремонт и новые инструменты...$B$BЗнаешь, с тобой довольно выгодно сотрудничать! Вот, возьми... это самое малое, что я могу для тебя сделать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Кажется, мы никогда не закончим возводить эту крепость. Надеюсь, ты несешь нам припасы, необходимые для продолжения строительства.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к саперу Стальной Чеке в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11219,'Гаси пожар!','Спасите детей Орды, $n! Всадник без головы, который некогда был человеком-паладином, а теперь стал безумным демоном, поджег нашу деревню! Вы должны потушить пожар!$B$BХватайте ведро и тушите огонь или передавайте ведра по цепочке! Потушите пожар и прогоните всадника без головы!','Попечительница сирот в маске просит вас помочь потушить пожар в деревне. Когда пожар потухнет, снова поговорите с попечительницей сирот в городе.','$N, вы обещали спасти детей!','Пожар потушен','Вернитесь к попечительнице сирот в маске.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гаси пожар!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасите детей Орды, $n! Всадник без головы, который некогда был человеком-паладином, а теперь стал безумным демоном, поджег нашу деревню! Вы должны потушить пожар!$B$BХватайте ведро и тушите огонь или передавайте ведра по цепочке! Потушите пожар и прогоните всадника без головы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Попечительница сирот в маске просит вас помочь потушить пожар в деревне. Когда пожар потухнет, снова поговорите с попечительницей сирот в городе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, вы обещали спасти детей!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Пожар потушен',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к попечительнице сирот в маске.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11220,'Всадник без головы','Найдите святилище тыквы Всадника без головы.','Происхождение этой святыни неизвестно, но нет сомнений, кому она отдает дань уважения...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Всадник без головы',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите святилище тыквы Всадника без головы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Происхождение этой святыни неизвестно, но нет сомнений, кому она отдает дань уважения...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11221,'Донесения с полей','Мы пришли в Нордскол, чтобы одержать победу над Артасом. Альянс – это незначительная помеха нашим планам, которую мы вскоре устраним.$B$BМы уже уничтожили их флот на востоке, но выжившие моряки укрылись на Обнажившемся дне, к югу отсюда.$B$BМы рассчитывали легко разрушить их самодельные укрепления, но недооценили их волю к жизни. Найди моих полевых офицеров, темного следопыта Лиану и ловчего смерти Разаэля. Мне нужен их отчет о текущей ситуации.','Поговорите с темным следопытом Лианой и ловчим смерти Разаэлем на поле боя в Кровоточащей долине к югу от Лагеря Возмездия, после чего вернитесь к Верховному палачу Ансельму.','Пушки заставили нас отступить? Я им покажу, как стрелять по нашим войскам!','Вернитесь к верховному палачу Ансельму в Лагерь Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Донесения с полей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы пришли в Нордскол, чтобы одержать победу над Артасом. Альянс – это незначительная помеха нашим планам, которую мы вскоре устраним.$B$BМы уже уничтожили их флот на востоке, но выжившие моряки укрылись на Обнажившемся дне, к югу отсюда.$B$BМы рассчитывали легко разрушить их самодельные укрепления, но недооценили их волю к жизни. Найди моих полевых офицеров, темного следопыта Лиану и ловчего смерти Разаэля. Мне нужен их отчет о текущей ситуации.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с темным следопытом Лианой и ловчим смерти Разаэлем на поле боя в Кровоточащей долине к югу от Лагеря Возмездия, после чего вернитесь к Верховному палачу Ансельму.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Пушки заставили нас отступить? Я им покажу, как стрелять по нашим войскам!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Ансельму в Лагерь Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11222,'[DEPRECATED]Proof of Treachery','Хотя мы получили ответы отнюдь не на все вопросы, необходимо, чтобы вы оповестили о результатах наших изысканий короля Вариана Ринна немедленно!$B$BОн должен знать, что Братство Справедливости в Штормграде обзавелось влиятельным покровителем и связано с его похищением! Сомневаюсь, что после этого он пощадит причастных к этому преступлению людей.$B$BЯ могу воспользоваться магией для ускорения вашей поездки в Штормград. Просто скажите мне, когда будете готовы, $n.','Поговорите с королем Варианом Ринном в крепости Штормграда.','<Верховный лорд Болвар слушает, пока вы доставляете сообщение Джайны.>$B$BВы уверены? Это очень серьезное обвинение...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Proof of Treachery',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя мы получили ответы отнюдь не на все вопросы, необходимо, чтобы вы оповестили о результатах наших изысканий короля Вариана Ринна немедленно!$B$BОн должен знать, что Братство Справедливости в Штормграде обзавелось влиятельным покровителем и связано с его похищением! Сомневаюсь, что после этого он пощадит причастных к этому преступлению людей.$B$BЯ могу воспользоваться магией для ускорения вашей поездки в Штормград. Просто скажите мне, когда будете готовы, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королем Варианом Ринном в крепости Штормграда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Верховный лорд Болвар слушает, пока вы доставляете сообщение Джайны.>$B$BВы уверены? Это очень серьезное обвинение...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11223,'[DEPRECATED]Return to Jaina','Мы должны составить план, как уничтожить остатки Братства Справедливости. Пожалуйста, передай мою благодарность леди Джайне в Терамор. Она всегда была мне добрым другом и надежным союзником. $B$BСтупай в Квартал Магов в западной части города и поговори с верховным магом Малином у тамошней башни. Он поможет тебе поскорее вернуться в Терамор.','Поговорите в Тераморе с леди Джайной Праудмур.','Это отличные новости, $N! Я волновалась, что верховный лорд может усомниться в правдивости нашей информации, но теперь я вижу, что мое беспокойство было неуместным.$B$BВы должны быть хорошо вознаграждены за ваши усилия от имени Терамора и Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[DEPRECATED]Return to Jaina',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны составить план, как уничтожить остатки Братства Справедливости. Пожалуйста, передай мою благодарность леди Джайне в Терамор. Она всегда была мне добрым другом и надежным союзником. $B$BСтупай в Квартал Магов в западной части города и поговори с верховным магом Малином у тамошней башни. Он поможет тебе поскорее вернуться в Терамор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите в Тераморе с леди Джайной Праудмур.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это отличные новости, $N! Я волновалась, что верховный лорд может усомниться в правдивости нашей информации, но теперь я вижу, что мое беспокойство было неуместным.$B$BВы должны быть хорошо вознаграждены за ваши усилия от имени Терамора и Альянса.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11224,'Пришли мулов сюда','Я слышала о том, что случилось в Шепчущей теснине на севере. Туда спустились многие члены Лиги исследователей, и, говорят, сошли с ума от того, что они там обнаружили.$B$BЭто, впрочем, не меняет того факта, что они забрали с собой почти всех наших мулов и оборудование. Мулов мне особенно жалко!$B$BЕсли ты вдруг окажешься в тех краях и наткнешься на бедных животных, просто подойди к ним и пригрози рукой. Они испугаются и побегут домой.','Исследовательница Эбигейл просит вас пригрозить рукой (команда /рука) 10 брошенным груженым мулам, после чего вернуться к ней в Крепость Западной Стражи.','Это серьезный удар по нам. Я даже не хочу знать, что они там обнаружили.$B$BЭтого достаточно, чтобы я не могла уснуть по ночам, просто пытаясь представить, что это могло быть.','Вернитесь к исследовательнице Эбигейл в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пришли мулов сюда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышала о том, что случилось в Шепчущей теснине на севере. Туда спустились многие члены Лиги исследователей, и, говорят, сошли с ума от того, что они там обнаружили.$B$BЭто, впрочем, не меняет того факта, что они забрали с собой почти всех наших мулов и оборудование. Мулов мне особенно жалко!$B$BЕсли ты вдруг окажешься в тех краях и наткнешься на бедных животных, просто подойди к ним и пригрози рукой. Они испугаются и побегут домой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследовательница Эбигейл просит вас пригрозить рукой (команда /рука) 10 брошенным груженым мулам, после чего вернуться к ней в Крепость Западной Стражи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это серьезный удар по нам. Я даже не хочу знать, что они там обнаружили.$B$BЭтого достаточно, чтобы я не могла уснуть по ночам, просто пытаясь представить, что это могло быть.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к исследовательнице Эбигейл в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11225,'Отшельник с Ведьмина холма','Эти болота странно влияют на людей. Некоторые сходят с ума от одной жизни здесь.$B$BУ любого, кто когда-либо селился в сторожке "Болотный огонек", просто-напросто ехала крыша. Последний хозяин, Ярл "Болотный Глаз", уже начинает дуреть.$B$BЯ до конца не понимаю, что тут творится, так что буду благодарен, если ты разузнаешь, что к чему.$B$BСторожка стоит на восточном краю болота. Иди через Синюю топь, мимо Северной башни. Твой пункт назначения – жутковатое место под названием Ведьмин холм.','Поговорите с Ярлом "Болотным Глазом" в сторожке "Болотный огонек".','Вы пришли сюда шпионить за мной? Нет?$B$BМожет быть, вы цените прекрасную кухню? Хорошо, ты можешь помочь!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отшельник с Ведьмина холма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти болота странно влияют на людей. Некоторые сходят с ума от одной жизни здесь.$B$BУ любого, кто когда-либо селился в сторожке "Болотный огонек", просто-напросто ехала крыша. Последний хозяин, Ярл "Болотный Глаз", уже начинает дуреть.$B$BЯ до конца не понимаю, что тут творится, так что буду благодарен, если ты разузнаешь, что к чему.$B$BСторожка стоит на восточном краю болота. Иди через Синюю топь, мимо Северной башни. Твой пункт назначения – жутковатое место под названием Ведьмин холм.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Ярлом "Болотным Глазом" в сторожке "Болотный огонек".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы пришли сюда шпионить за мной? Нет?$B$BМожет быть, вы цените прекрасную кухню? Хорошо, ты можешь помочь!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11226,'Upper Deck Promo – Призрачный верховой тигр') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Upper Deck Promo – Призрачный верховой тигр',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11227,'Пусть едят вволю!','Верховный палач требует, чтобы мои собаки отправились вынюхивать следы шпионов противника, но я-то знаю, что чумные псы и с места не сдвинутся, пока их не накормят нормальной едой. $B$BЭти тупоголовые вояки не понимают, что мои звери не будут есть всякие отбросы. Как можно требовать каких-то успехов от голодных собак?$B$BСлушай, у тебя не найдется свободной минутки? Пожалуйста, возьми одного из псов поохотиться на ворон к западу отсюда. Их мясо не очень-то вкусное, но мои песики его обожают!','Понтий, псарь из Лагеря Возмездия, просит вас забрать голодного чумного пса из клетки и накормить его мясом ворон фьорда, которые кружат к западу от Лагеря Возмездия.','Вернитесь к Понтему в Лагерь Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть едят вволю!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Верховный палач требует, чтобы мои собаки отправились вынюхивать следы шпионов противника, но я-то знаю, что чумные псы и с места не сдвинутся, пока их не накормят нормальной едой. $B$BЭти тупоголовые вояки не понимают, что мои звери не будут есть всякие отбросы. Как можно требовать каких-то успехов от голодных собак?$B$BСлушай, у тебя не найдется свободной минутки? Пожалуйста, возьми одного из псов поохотиться на ворон к западу отсюда. Их мясо не очень-то вкусное, но мои песики его обожают!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Понтий, псарь из Лагеря Возмездия, просит вас забрать голодного чумного пса из клетки и накормить его мясом ворон фьорда, которые кружат к западу от Лагеря Возмездия.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Понтему в Лагерь Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11228,'Во власти ледяного кошмара...','Фордрагон совсем с ума сошел, если он и впрямь думает, что этот отряд зеленоротых юнцов, которых он послал на защиту Валгарда, продержится хотя бы сутки.$B$B<Макалрой с удивлением рассматривает ваше обмундирование.>$B$BА вот ты, пожалуй, справишься гораздо лучше.$B$BЯ не могу даже описать, насколько велика ценность этого порта. А после того, как на нас напали эти летающие твари, ситуация резко ухудшилась.$B$BНайди вице-адмирала Келлера на северо-западе и сообщи ему, что ты уже $gвырос:выросла; из коротких штанишек.','Поговорите с вице-адмиралом Келлером в Валгардском порту.','Этот дворф знает, что говорит. Мы действительно не можем допустить, чтобы порт был захвачен. Это одна из двух безопасных гаваней Альянса в этом ледяном кошмаре – вторая находится на сотню миль к западу, на побережье Борейской тундры.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Во власти ледяного кошмара...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Фордрагон совсем с ума сошел, если он и впрямь думает, что этот отряд зеленоротых юнцов, которых он послал на защиту Валгарда, продержится хотя бы сутки.$B$B<Макалрой с удивлением рассматривает ваше обмундирование.>$B$BА вот ты, пожалуй, справишься гораздо лучше.$B$BЯ не могу даже описать, насколько велика ценность этого порта. А после того, как на нас напали эти летающие твари, ситуация резко ухудшилась.$B$BНайди вице-адмирала Келлера на северо-западе и сообщи ему, что ты уже $gвырос:выросла; из коротких штанишек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с вице-адмиралом Келлером в Валгардском порту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этот дворф знает, что говорит. Мы действительно не можем допустить, чтобы порт был захвачен. Это одна из двух безопасных гаваней Альянса в этом ледяном кошмаре – вторая находится на сотню миль к западу, на побережье Борейской тундры.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11229,'Флагман "Ветрокрылая"','Три наших фрегата – "Ветрокрылая", "Месть королевы" и "Забвение" стоят на якоре к востоку от Обнажившегося дна. Передай капитану флота Харкеру, что ему приказано уничтожить пушки Альянса.$B$BПоговори с нашей дрессировщицей нетопырей Камиллой и попроси ее довезти тебя до места дислокации флота. Поторопись, $n, ибо каждую минуту, которую мы тратим на стычки с Альянсом, мы могли бы посвятить войне с Артасом.','Поговорите с дрессировщицей нетопырей Камиллой в Лагере Возмездия и летите к флагману "Ветрокрылая". Доложите о своем прибытии капитану Харкеру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Флагман "Ветрокрылая"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Три наших фрегата – "Ветрокрылая", "Месть королевы" и "Забвение" стоят на якоре к востоку от Обнажившегося дна. Передай капитану флота Харкеру, что ему приказано уничтожить пушки Альянса.$B$BПоговори с нашей дрессировщицей нетопырей Камиллой и попроси ее довезти тебя до места дислокации флота. Поторопись, $n, ибо каждую минуту, которую мы тратим на стычки с Альянсом, мы могли бы посвятить войне с Артасом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с дрессировщицей нетопырей Камиллой в Лагере Возмездия и летите к флагману "Ветрокрылая". Доложите о своем прибытии капитану Харкеру.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11230,'Засада!','Мы думали, что это будет легкой прогулкой. Их войска плохо экипированы, солдаты изранены и страдают от голода. Однако каким-то образом мы угодили в их ловушку.$B$BМы хотели использовать южные рифы как укрытие, но на подходе были взяты на абордаж этими вонючими псами Альянса.$B$BМне очень жаль, но если ты рассчитываешь на нашу огневую поддержку, тебе придется сначала вернуть наши корабли.','Капитан Харкер на борту "Ветрокрылой" просит вас убить 15 стражей бухты Северного флота.','Молодец, поставил этих поганцев на место. С оставшимися разберутся мои люди.','Ну, и чего ты ждешь? Убей этих мерзавцев!','Вернитесь к капитану Харкер на "Ветрокрылую", что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засада!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы думали, что это будет легкой прогулкой. Их войска плохо экипированы, солдаты изранены и страдают от голода. Однако каким-то образом мы угодили в их ловушку.$B$BМы хотели использовать южные рифы как укрытие, но на подходе были взяты на абордаж этими вонючими псами Альянса.$B$BМне очень жаль, но если ты рассчитываешь на нашу огневую поддержку, тебе придется сначала вернуть наши корабли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Харкер на борту "Ветрокрылой" просит вас убить 15 стражей бухты Северного флота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, поставил этих поганцев на место. С оставшимися разберутся мои люди.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, и чего ты ждешь? Убей этих мерзавцев!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Харкер на "Ветрокрылую", что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11231,'О ключах и клетках','Возможно, капитану это безразлично, но мы-то знаем, что врайкулы совершают какие-то омерзительные ритуалы "пробуждения" к северу от Гьялерброна.$B$BВ ходе этих обрядов проливается кровь невинных жертв!$B$B$C, ты $gдолжен:должна; остановить это! Неважно, кого они держат в своих клетках для жертвоприношений – их надо освободить. Могу поспорить, врайкулы носят ключи при себе.$B$BВидит Свет, нам не нужны эти мерзкие врайкулы поблизости, и еще меньше нам хочется разбираться с тем злом, которое они пытаются пробудить!','Слава тебе, дитя мое, ибо ты несешь Свет даже в самые темные уголки этого мира!$B$BПожалуйста, прими это скромное вознаграждение твоим благим делам. Я лично прослежу за судьбой освобожденных тобой пленников, и пусть будет даровано спасение тем, кто служит Свету и Альянсу.','После освобождения заключенных в Гьялерброне врайкулы не смогут продолжать свои нечестивые обряды.$B$BТы наша единственная надежда остановить их.','Вернитесь к отцу Левариолу в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','О ключах и клетках',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, капитану это безразлично, но мы-то знаем, что врайкулы совершают какие-то омерзительные ритуалы "пробуждения" к северу от Гьялерброна.$B$BВ ходе этих обрядов проливается кровь невинных жертв!$B$B$C, ты $gдолжен:должна; остановить это! Неважно, кого они держат в своих клетках для жертвоприношений – их надо освободить. Могу поспорить, врайкулы носят ключи при себе.$B$BВидит Свет, нам не нужны эти мерзкие врайкулы поблизости, и еще меньше нам хочется разбираться с тем злом, которое они пытаются пробудить!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава тебе, дитя мое, ибо ты несешь Свет даже в самые темные уголки этого мира!$B$BПожалуйста, прими это скромное вознаграждение твоим благим делам. Я лично прослежу за судьбой освобожденных тобой пленников, и пусть будет даровано спасение тем, кто служит Свету и Альянсу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','После освобождения заключенных в Гьялерброне врайкулы не смогут продолжать свои нечестивые обряды.$B$BТы наша единственная надежда остановить их.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к отцу Левариолу в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11232,'Дайте нам знак','Скорее всего, мы сможем пробиться назад, к пушкам. К несчастью, нам лучше не привлекать к себе внимания, поэтому тебе придется пометить цели с земли.$B$BВозьми с собой эти дымовые сигнальные ракеты и обозначь местонахождение пушек вдоль северной стены на контролируемой Альянсом территории к западу отсюда. Как только путь для наших наземных отрядов будет расчищен, дай знак Лиане. Об остальном мы позаботимся сами.','С помощью дымовых сигнальных ракет обозначьте местонахождение пушек Альянса вдоль северной стены Обнажившегося дна. Доложите о выполнении задания темному следопыту Лиане из Кровоточащей долины.','Превосходно. Я дам знать нашим наземным отрядам, что они могут выступать.','Ну, и чего ты ждешь? Убей этих мерзавцев!','Вернитесь к темному следопыту Лиане в Кровоточащую долину, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дайте нам знак',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скорее всего, мы сможем пробиться назад, к пушкам. К несчастью, нам лучше не привлекать к себе внимания, поэтому тебе придется пометить цели с земли.$B$BВозьми с собой эти дымовые сигнальные ракеты и обозначь местонахождение пушек вдоль северной стены на контролируемой Альянсом территории к западу отсюда. Как только путь для наших наземных отрядов будет расчищен, дай знак Лиане. Об остальном мы позаботимся сами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','С помощью дымовых сигнальных ракет обозначьте местонахождение пушек Альянса вдоль северной стены Обнажившегося дна. Доложите о выполнении задания темному следопыту Лиане из Кровоточащей долины.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно. Я дам знать нашим наземным отрядам, что они могут выступать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, и чего ты ждешь? Убей этих мерзавцев!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному следопыту Лиане в Кровоточащую долину, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11233,'Решающий удар','Ты отлично $gпроявил:проявила; себя на поле боя, $n. Возможно, именно ты $gизменил:изменила; ход битвы в нашу пользу.$B$BТеперь я хочу поручить тебе очень ответственную миссию. Не знаю, сколько еще времени понадобится противнику, чтобы прийти в себя, но времени для действий осталось не так уж много.$B$BВоспользуйся замешательством неприятеля, вызванным нашим нападением, проберись за линию фронта и уничтожь их предводителей. Вот их имена и звания: капитан Ольстер, лейтенант Селейна и сержант Лоррик. Удачи, |3-6($c).','Темный следопыт Лиана из Лагеря Возмездия послала вас убить капитана Ольстера, сержанта Лоррика и лейтенанта Селейну, обосновавшихся на Обнажившемся дне.','Скоро наши войска одержат великую победу. Ансельм будет рад услышать эти вести.','Вернитесь к темному следопыту Лиане в Кровоточащую долину, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Решающий удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты отлично $gпроявил:проявила; себя на поле боя, $n. Возможно, именно ты $gизменил:изменила; ход битвы в нашу пользу.$B$BТеперь я хочу поручить тебе очень ответственную миссию. Не знаю, сколько еще времени понадобится противнику, чтобы прийти в себя, но времени для действий осталось не так уж много.$B$BВоспользуйся замешательством неприятеля, вызванным нашим нападением, проберись за линию фронта и уничтожь их предводителей. Вот их имена и звания: капитан Ольстер, лейтенант Селейна и сержант Лоррик. Удачи, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Темный следопыт Лиана из Лагеря Возмездия послала вас убить капитана Ольстера, сержанта Лоррика и лейтенанта Селейну, обосновавшихся на Обнажившемся дне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Скоро наши войска одержат великую победу. Ансельм будет рад услышать эти вести.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к темному следопыту Лиане в Кровоточащую долину, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (11234,'Доложите Ансельму','Вернитесь к верховному палачу Ансельму в Лагерь Возмездия в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доложите Ансельму',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к верховному палачу Ансельму в Лагерь Возмездия в Ревущем фьорде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11235,'Очистить Гьялерброн','Увы, теперь перед нами стоит другая проблема. Выжившие разведчики сообщили, что врайкулы замышляют нечто недоброе в своей главной крепости к северу отсюда. $B$BОни называют это место Гьялерброн, хотя вообще-то первая буква этого слова произносится как "Ш". Странные существа. $B$BНо все это не важно; важно то, что тебе надо пробраться туда и убить как можно больше этих мерзких существ, чтобы сорвать их зловещие планы. $B$BЯ знаю, что могу на тебя рассчитывать, $n.','Капитан Адамс поручил вам убить 15 гьялербронских воинов, 8 гьялербронских руночаров и 8 гьялербронских сноходцев. После чего вам надлежит вернуться к нему в Крепость Западной Стражи.','Ты $Gмолодец:умница;, $N. Хорошо, что мы от них избавились.$B$BНо это место все еще меня беспокоит, и я боюсь, что наша война еще не окончена.','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очистить Гьялерброн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Увы, теперь перед нами стоит другая проблема. Выжившие разведчики сообщили, что врайкулы замышляют нечто недоброе в своей главной крепости к северу отсюда. $B$BОни называют это место Гьялерброн, хотя вообще-то первая буква этого слова произносится как "Ш". Странные существа. $B$BНо все это не важно; важно то, что тебе надо пробраться туда и убить как можно больше этих мерзких существ, чтобы сорвать их зловещие планы. $B$BЯ знаю, что могу на тебя рассчитывать, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Адамс поручил вам убить 15 гьялербронских воинов, 8 гьялербронских руночаров и 8 гьялербронских сноходцев. После чего вам надлежит вернуться к нему в Крепость Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gмолодец:умница;, $N. Хорошо, что мы от них избавились.$B$BНо это место все еще меня беспокоит, и я боюсь, что наша война еще не окончена.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11236,'Некровладыка Мезхен','Армия Плети уже пришла в Гьялерброн, и в их рядах есть несколько некромантов! Должно быть, они пытаются провести врайкулов в крепость Артаса.$B$BПредводитель этих некролордов должен умереть!$B$B$n, на твои плечи ложится огромная ответственность – ты $gдолжен:должна; сорвать планы некровладыки Мезхена и уничтожить его самого.$B$BЯ не допущу, чтобы эти врайкулы заключили союз с Плетью! $B$BМезхена можно найти на платформе в дальнем правом квартале Гьялерброна.','Убейте некровладыку Мезхена. Затем вернитесь к капитану Адамсу в Крепость Западной Стражи.','<Капитан облегченно вздыхает.>$B$BНу, теперь мы можем слегка расслабиться.$B$B$N, ты снова $Gподтвердил:подтвердила; свою значимость для Крепости Западной Стражи и всего Альянса. Пожалуйста, выбери себе что-нибудь из нашей сокровищницы. Это самое меньшее, что мы можем для тебя сделать!','Ты $Gуверен:уверена;, что $Gубил:убила; Межена и его некролордов, $C?','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Некровладыка Мезхен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Армия Плети уже пришла в Гьялерброн, и в их рядах есть несколько некромантов! Должно быть, они пытаются провести врайкулов в крепость Артаса.$B$BПредводитель этих некролордов должен умереть!$B$B$n, на твои плечи ложится огромная ответственность – ты $gдолжен:должна; сорвать планы некровладыки Мезхена и уничтожить его самого.$B$BЯ не допущу, чтобы эти врайкулы заключили союз с Плетью! $B$BМезхена можно найти на платформе в дальнем правом квартале Гьялерброна.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте некровладыку Мезхена. Затем вернитесь к капитану Адамсу в Крепость Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Капитан облегченно вздыхает.>$B$BНу, теперь мы можем слегка расслабиться.$B$B$N, ты снова $Gподтвердил:подтвердила; свою значимость для Крепости Западной Стражи и всего Альянса. Пожалуйста, выбери себе что-нибудь из нашей сокровищницы. Это самое меньшее, что мы можем для тебя сделать!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gуверен:уверена;, что $Gубил:убила; Межена и его некролордов, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11237,'Гьялербронский план нападения','Вы держите в руках планы нападения на Крепость Западной Стражи. Похоже, что врайкулы собираются использовать для атаки ледяного змея, Ледиона, который кружит у вас над головой.$B$BНаверняка, маг-лейтенант Малистер сможет что-нибудь предпринять, если вы доставите эти планы к нему в южную крепость.','$N, мы не можем допустить, чтобы эти планы осуществились!','Что это?! Планы нападения на крепость?$B$BОНИ ПОСЫЛАЮТ ЛЕДЯНОГО ЗМЕЯ?!','Вернитесь к магу-лейтенанту Малистеру в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гьялербронский план нападения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы держите в руках планы нападения на Крепость Западной Стражи. Похоже, что врайкулы собираются использовать для атаки ледяного змея, Ледиона, который кружит у вас над головой.$B$BНаверняка, маг-лейтенант Малистер сможет что-нибудь предпринять, если вы доставите эти планы к нему в южную крепость.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$N, мы не можем допустить, чтобы эти планы осуществились!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это?! Планы нападения на крепость?$B$BОНИ ПОСЫЛАЮТ ЛЕДЯНОГО ЗМЕЯ?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магу-лейтенанту Малистеру в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11239,'На службе Света','Убейте 10 бессмертных дозорных, 4 чудовищных ужаса и 2 тлетворных существа по просьбе отца Левариола из Крепости Западной Стражи.','<Священник тихо шепчет слова молитвы.>$B$BДитя мое, $N, ты $Gбыл:была; $Gпослан:послана; в ответ на мои молитвы. Гордо стой в лучах Света, ибо подвиг твой священен!$B$BКстати, в сокровищнице храма наверняка найдется что-то, что тебе пригодится.','Святой Свет пронизывает ваши действия и все.$B$BНи одно существо, ни одно место, каким бы злым оно ни было, не может избежать его гнева!','Вернитесь к отцу Левариолу в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На службе Света',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 бессмертных дозорных, 4 чудовищных ужаса и 2 тлетворных существа по просьбе отца Левариола из Крепости Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Священник тихо шепчет слова молитвы.>$B$BДитя мое, $N, ты $Gбыл:была; $Gпослан:послана; в ответ на мои молитвы. Гордо стой в лучах Света, ибо подвиг твой священен!$B$BКстати, в сокровищнице храма наверняка найдется что-то, что тебе пригодится.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Святой Свет пронизывает ваши действия и все.$B$BНи одно существо, ни одно место, каким бы злым оно ни было, не может избежать его гнева!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к отцу Левариолу в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11240,'Предводитель Спятивших','Знаешь, дружище, мне тоже все это не нравится, но, пока тебя не было, капитан пересмотрел свое мнение об этом месте.$B$BПохоже, он хочет убить моего бывшего начальника Лиги исследователей. Могу предположить, что за этим последует нападение на их лагерь.$B$BМожет быть, ты окажешь мне услугу? Отправляйся назад, в Шепчущую теснину, и убей Сквига Идолохотника. Насколько я помню, он прячется в пещере на северо-западе.','Убейте Сквига Идолохотника и сообщите об этом саперу Стальная Чека, который находится в Крепости Западной Стражи.','<Сапер недовольно морщится, как будто не рассчитывал на успех вашей миссии.>$B$BКапитан будет рад слышать, что его задание выполнено.$B$BСпасибо тебе за помощь в Шепчущей теснине. Выбери себе что-нибудь из этого в награду.','Вернитесь к саперу Стальной Чеке в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предводитель Спятивших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, дружище, мне тоже все это не нравится, но, пока тебя не было, капитан пересмотрел свое мнение об этом месте.$B$BПохоже, он хочет убить моего бывшего начальника Лиги исследователей. Могу предположить, что за этим последует нападение на их лагерь.$B$BМожет быть, ты окажешь мне услугу? Отправляйся назад, в Шепчущую теснину, и убей Сквига Идолохотника. Насколько я помню, он прячется в пещере на северо-западе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Сквига Идолохотника и сообщите об этом саперу Стальная Чека, который находится в Крепости Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Сапер недовольно морщится, как будто не рассчитывал на успех вашей миссии.>$B$BКапитан будет рад слышать, что его задание выполнено.$B$BСпасибо тебе за помощь в Шепчущей теснине. Выбери себе что-нибудь из этого в награду.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к саперу Стальной Чеке в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11241,'Путь огня','Спасибо, что $gвытащил:вытащила; меня из этой передряги, $n. Не хотелось бы узнать, что за судьбу готовили мне эти мерзавцы из Альянса.$B$BДавай попробуем выбраться отсюда. Надеюсь, нам еще удастся с ними рассчитаться. Есть ли здесь наш лагерь поблизости?','Выведите аптекаря Хейнса из Обнажившегося дна после чего сообщите о произошедшем аптекарю Лисандеру из Лагеря Возмездия в Ревущем фьорде.','Спасти аптекаря Хейнса','Вернитесь к аптекарю Лисандеру в Лагерь Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь огня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо, что $gвытащил:вытащила; меня из этой передряги, $n. Не хотелось бы узнать, что за судьбу готовили мне эти мерзавцы из Альянса.$B$BДавай попробуем выбраться отсюда. Надеюсь, нам еще удастся с ними рассчитаться. Есть ли здесь наш лагерь поблизости?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выведите аптекаря Хейнса из Обнажившегося дна после чего сообщите о произошедшем аптекарю Лисандеру из Лагеря Возмездия в Ревущем фьорде.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Спасти аптекаря Хейнса',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Лисандеру в Лагерь Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11242,'Наконец, свободен!','Гнев был моей темницей, $n, а ты $Gосвободил:освободила; меня. Хотя я считал себя правым, душа моя ныне кровоточит от всех тех ужасов и смертей, которые обрушил я на жителей Азерота.$B$BБлагодарю тебя, что ты $gпривел:привела; меня к Свету. Да не сверну я с этого пути!$B$BОтнеси этот потрепанный молитвенник попечительнице сирот, чтобы дети узнали, что больше я их не потревожу.','Возьмите книгу Томаса Томсона и отнесите ее переодетой попечительнице сирот в Златоземье, Каранос или на Лазурную заставу.','Что это такое? Книга Томаса Томсона? Но так звали всадника до того, как он был проклят! Значит ли это, что он наконец-то свободен? Значит ли это, что он больше не будет мучить добрых людей Азерота?$B$BКакой радостный день! $N, ваш подвиг будет долго жить с нами. Дети и дети их жетей будут воспевать ваше имя!','У тебя есть что-то хорошее для меня, $N?','Вернитесь к переодетой попечительнице сирот.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наконец, свободен!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гнев был моей темницей, $n, а ты $Gосвободил:освободила; меня. Хотя я считал себя правым, душа моя ныне кровоточит от всех тех ужасов и смертей, которые обрушил я на жителей Азерота.$B$BБлагодарю тебя, что ты $gпривел:привела; меня к Свету. Да не сверну я с этого пути!$B$BОтнеси этот потрепанный молитвенник попечительнице сирот, чтобы дети узнали, что больше я их не потревожу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите книгу Томаса Томсона и отнесите ее переодетой попечительнице сирот в Златоземье, Каранос или на Лазурную заставу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это такое? Книга Томаса Томсона? Но так звали всадника до того, как он был проклят! Значит ли это, что он наконец-то свободен? Значит ли это, что он больше не будет мучить добрых людей Азерота?$B$BКакой радостный день! $N, ваш подвиг будет долго жить с нами. Дети и дети их жетей будут воспевать ваше имя!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя есть что-то хорошее для меня, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к переодетой попечительнице сирот.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11243,'Если Валгард падет...','Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас убить 12 захватчиков из клана Укротителей драконов или воргов из клана Укротителей драконов.','Судьба мира вполне может быть с нами.','Вернитесь к вице-адмиралу Келлеру в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Если Валгард падет...',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас убить 12 захватчиков из клана Укротителей драконов или воргов из клана Укротителей драконов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Судьба мира вполне может быть с нами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вице-адмиралу Келлеру в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11244,'На помощь спасателям','Эти жуткие великаны появились буквально из воздуха через месяц после того, как мы прибыли сюда. Мы были плохо подготовлены к нападению и дорого поплатились за свою беспечность. Мы потеряли всю археологическую бригаду и нескольких жителей, которых похитили и утащили в руины. С тех пор мы находимся на осадном положении.$B$BХуже того, наших разведчиков, которых мы послали на помощь похищенным, поймали врайкулы, насадили на гарпуны и оставили умирать в лесу к северу от Валгарда. Пожалуйста, найди их и освободи!','Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас спасти 8 валгардских разведчиков, которых проткнули гарпунами и оставили умирать.','Какая дикость! Не могу поверить, что врайкулы так поступили с нашими разведчиками. Они хотели запугать нас, ослабить нашу решимость... заставить спасаться бегством.$B$BНо их замысел не удался.$B$BМы покажем этим мерзавцам, что будет с теми, кто осмелится развязать войну с Альянсом!','Найди этих разведчиков!','Вернитесь к вице-адмиралу Келлеру в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На помощь спасателям',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти жуткие великаны появились буквально из воздуха через месяц после того, как мы прибыли сюда. Мы были плохо подготовлены к нападению и дорого поплатились за свою беспечность. Мы потеряли всю археологическую бригаду и нескольких жителей, которых похитили и утащили в руины. С тех пор мы находимся на осадном положении.$B$BХуже того, наших разведчиков, которых мы послали на помощь похищенным, поймали врайкулы, насадили на гарпуны и оставили умирать в лесу к северу от Валгарда. Пожалуйста, найди их и освободи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас спасти 8 валгардских разведчиков, которых проткнули гарпунами и оставили умирать.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая дикость! Не могу поверить, что врайкулы так поступили с нашими разведчиками. Они хотели запугать нас, ослабить нашу решимость... заставить спасаться бегством.$B$BНо их замысел не удался.$B$BМы покажем этим мерзавцам, что будет с теми, кто осмелится развязать войну с Альянсом!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Найди этих разведчиков!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вице-адмиралу Келлеру в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11245,'Смертельно опасные башни','$n, мы не можем двигаться дальше, не уничтожив сторожевые башни.$B$BНо на вершине каждой вышки несет стражу множество волшебников. Стоит тебе только приблизиться к башне – и мы обречены!$B$BКонечно, мы можем призвать бомбардиров из Крепости Западной Стражи, но они должны видеть цель, которую им предстоит разбомбить. Для этого тебе придется подкрасться к башням и забросить на вершину каждой дымовую сигнальную ракету.$B$BГлавное – не подходи слишком близко.','Сержант из крепости Западной Стражи сообщил вам, что сторожевые башни Скорна разумнее всего разрушить с воздуха.','$GКакой:Какая; ты $Gметкий:меткая;, $N! Надо будет проставиться бомбардирам, когда мы вернемся обратно в крепость.','Подобраться слишком близко к этим башням - верная смерть, пока эти заклинатели там.','Поговорите с сержантом из крепости Западной Стражи, который вас сопровождает. Чтобы позвать сержанта, воспользуйтесь знаком отличия командира Западной Стражи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смертельно опасные башни',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, мы не можем двигаться дальше, не уничтожив сторожевые башни.$B$BНо на вершине каждой вышки несет стражу множество волшебников. Стоит тебе только приблизиться к башне – и мы обречены!$B$BКонечно, мы можем призвать бомбардиров из Крепости Западной Стражи, но они должны видеть цель, которую им предстоит разбомбить. Для этого тебе придется подкрасться к башням и забросить на вершину каждой дымовую сигнальную ракету.$B$BГлавное – не подходи слишком близко.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сержант из крепости Западной Стражи сообщил вам, что сторожевые башни Скорна разумнее всего разрушить с воздуха.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GКакой:Какая; ты $Gметкий:меткая;, $N! Надо будет проставиться бомбардирам, когда мы вернемся обратно в крепость.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Подобраться слишком близко к этим башням - верная смерть, пока эти заклинатели там.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с сержантом из крепости Западной Стражи, который вас сопровождает. Чтобы позвать сержанта, воспользуйтесь знаком отличия командира Западной Стражи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11246,'Тяжело, но необходимо','Нам докладывали, что врайкулы могут восставать из мертвых. Нет, они не похожи на оживших мертвецов Плети, но их понятие жизни после смерти несет нам не меньшие беды.$B$BМы не можем так рисковать!$B$BВот, возьмите мой мачете. Пока мы будем продвигаться вперед, кромсайте им все трупы врайкулов, которые встретятся вам по пути. Я бы и сам это сделал, но у меня слабые нервы.$B$B<Сержант глупо ухмыляется.>$B$BЯ потратил все утро на заточку клинка, так что теперь он разрубит даже самые толстые кости.','Сержант из крепости Западной Стражи попросил вас разрубить на куски 20 снежескорнских врайкулов в Скорне.','Ух ты, сэр,а вы знаете, как обращаться с этой штуковиной.$B$B<Сержант бросает на вас настороженный взгляд.>$B$BЗнаете что, давайте-ка я заберу у вас мачете. А то вдруг вы поскользнетесь, споткнетесь, да зарубите меня ненароком!','Одно я знаю наверняка, это то, что я не хочу, чтобы кто-нибудь из этих врайкулов восстал после того, как мы их разрубили!','Поговорите с сержантом из крепости Западной Стражи, который вас сопровождает. Чтобы позвать сержанта, воспользуйтесь знаком отличия командира Западной Стражи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжело, но необходимо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам докладывали, что врайкулы могут восставать из мертвых. Нет, они не похожи на оживших мертвецов Плети, но их понятие жизни после смерти несет нам не меньшие беды.$B$BМы не можем так рисковать!$B$BВот, возьмите мой мачете. Пока мы будем продвигаться вперед, кромсайте им все трупы врайкулов, которые встретятся вам по пути. Я бы и сам это сделал, но у меня слабые нервы.$B$B<Сержант глупо ухмыляется.>$B$BЯ потратил все утро на заточку клинка, так что теперь он разрубит даже самые толстые кости.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сержант из крепости Западной Стражи попросил вас разрубить на куски 20 снежескорнских врайкулов в Скорне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты, сэр,а вы знаете, как обращаться с этой штуковиной.$B$B<Сержант бросает на вас настороженный взгляд.>$B$BЗнаете что, давайте-ка я заберу у вас мачете. А то вдруг вы поскользнетесь, споткнетесь, да зарубите меня ненароком!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Одно я знаю наверняка, это то, что я не хочу, чтобы кто-нибудь из этих врайкулов восстал после того, как мы их разрубили!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с сержантом из крепости Западной Стражи, который вас сопровождает. Чтобы позвать сержанта, воспользуйтесь знаком отличия командира Западной Стражи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11247,'Гори, Скорн, гори!','Капитан Адамс приказал мне разрушить множество зданий в Скорне.$B$BНо теперь я могу смело доверить это ответственное задание своему командиру – то есть, вам, $n.$B$BПредлагаю сжечь два больших дома и казармы в нижнем квартале Скорна. Нам надо просто прокрасться в каждый дом и поджечь его факелом изнутри.','Сержант из крепости Западной Стражи поручил вам поджечь два больших дома и казармы в Скорне.','Могу посоветовать, когда поджигаешь здания, не задерживайся в них слишком долго.','Поговорите с сержантом из крепости Западной Стражи, который вас сопровождает. Чтобы позвать сержанта, воспользуйтесь знаком отличия командира Западной Стражи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гори, Скорн, гори!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Капитан Адамс приказал мне разрушить множество зданий в Скорне.$B$BНо теперь я могу смело доверить это ответственное задание своему командиру – то есть, вам, $n.$B$BПредлагаю сжечь два больших дома и казармы в нижнем квартале Скорна. Нам надо просто прокрасться в каждый дом и поджечь его факелом изнутри.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сержант из крепости Западной Стражи поручил вам поджечь два больших дома и казармы в Скорне.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Могу посоветовать, когда поджигаешь здания, не задерживайся в них слишком долго.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с сержантом из крепости Западной Стражи, который вас сопровождает. Чтобы позвать сержанта, воспользуйтесь знаком отличия командира Западной Стражи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11248,'Операция: Атака на Скорн','$n! Только тебе я могу доверить столь рискованное и смертельно опасное поручение.$B$BНа восточной границе нашего форта находится крепость врайкулов, Скорн. Мои разведчики доложили, что эти "великаны" планируют нападение, которое мы вряд ли сможем отразить.$B$BГрубой силой мы ничего не добьемся, поэтому я хочу пустить в дело хитрость. Я выслал вперед сержанта и снабдил его всеми необходимыми инструкциями. Отправляйся в Скорн и покажи ему этот знак отличия командира.','Капитан Адамс попросил вас воспользоваться знаком отличия командира Западной Стражи в Скорне и поговорить с сержантом из крепости Западной Стражи.','Рад познакомиться с тобой, $N!Это честь для меня – работать с тобой в одной команде.$B$BКстати говоря, у нас много дел!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Операция: Атака на Скорн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Только тебе я могу доверить столь рискованное и смертельно опасное поручение.$B$BНа восточной границе нашего форта находится крепость врайкулов, Скорн. Мои разведчики доложили, что эти "великаны" планируют нападение, которое мы вряд ли сможем отразить.$B$BГрубой силой мы ничего не добьемся, поэтому я хочу пустить в дело хитрость. Я выслал вперед сержанта и снабдил его всеми необходимыми инструкциями. Отправляйся в Скорн и покажи ему этот знак отличия командира.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Адамс попросил вас воспользоваться знаком отличия командира Западной Стражи в Скорне и поговорить с сержантом из крепости Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Рад познакомиться с тобой, $N!Это честь для меня – работать с тобой в одной команде.$B$BКстати говоря, у нас много дел!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11249,'Остановить вознесение!','Этот огромный сверток сделан из драконьей кожи. Развернув его на всю длину, вы видите таинственные знаки на чешуйчатой поверхности, изображающие ход врайкульского ритуала. $B$BТам нарисован тан врайкульского клана, поднимающийся в небо в окружении ангелоподобных существ. Позади него во мраке изображена темная, загадочная фигура.$B$BЧто-то подсказывает вам, что тан скорнского клана собирается пройти через этот ритуал. Вы должны его остановить! Напротив дома тана уже вздымается в небо огромный погребальный костер.','Разверните врайкульский свиток вознесения рядом с погребальным костром тана, призовите и убейте его. Исходя из магической природы ритуала, вы можете предположить, что отцу Левариолу из Крепости Западной Стражи будет очень интересно взглянуть на этот свиток.','Чем я могу помочь тебе, дитя мое?','Вернитесь к отцу Левариолу в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановить вознесение!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот огромный сверток сделан из драконьей кожи. Развернув его на всю длину, вы видите таинственные знаки на чешуйчатой поверхности, изображающие ход врайкульского ритуала. $B$BТам нарисован тан врайкульского клана, поднимающийся в небо в окружении ангелоподобных существ. Позади него во мраке изображена темная, загадочная фигура.$B$BЧто-то подсказывает вам, что тан скорнского клана собирается пройти через этот ритуал. Вы должны его остановить! Напротив дома тана уже вздымается в небо огромный погребальный костер.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разверните врайкульский свиток вознесения рядом с погребальным костром тана, призовите и убейте его. Исходя из магической природы ритуала, вы можете предположить, что отцу Левариолу из Крепости Западной Стражи будет очень интересно взглянуть на этот свиток.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Чем я могу помочь тебе, дитя мое?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к отцу Левариолу в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11250,'Слава покорителю Скорна!','Мы – точнее, ты – $gсделал:сделала; все, за чем нас сюда посылали. Я горжусь тем, что мне довелось служить под началом $gтакого юного, но мудрого:такой юной, но мудрой:r; |3-1($r). $B$BНе сомневаюсь, капитан будет рад слышать о твоих достижениях, но если ты по какой-то причине решишь остаться тут на некоторое время, то я всегда в твоем распоряжении.','Отнесите знак отличия командира Западной Стражи капитану Адамсу в Крепость Западной Стражи.','Какие прекрасные новости! Я знал, что ты сможешь осадить их, $N!$B$BНу, хоть на кого-то здесь можно положиться.$B$BПолагаю, ты $Gзаслужил:заслужила; награду. Давай, выбирай – для тебя ничего не жалко.','Полагаю, раз ты $Gвернулся:вернулась; то Скорн больше нам не угрожает?','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слава покорителю Скорна!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы – точнее, ты – $gсделал:сделала; все, за чем нас сюда посылали. Я горжусь тем, что мне довелось служить под началом $gтакого юного, но мудрого:такой юной, но мудрой:r; |3-1($r). $B$BНе сомневаюсь, капитан будет рад слышать о твоих достижениях, но если ты по какой-то причине решишь остаться тут на некоторое время, то я всегда в твоем распоряжении.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите знак отличия командира Западной Стражи капитану Адамсу в Крепость Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какие прекрасные новости! Я знал, что ты сможешь осадить их, $N!$B$BНу, хоть на кого-то здесь можно положиться.$B$BПолагаю, ты $Gзаслужил:заслужила; награду. Давай, выбирай – для тебя ничего не жалко.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Полагаю, раз ты $Gвернулся:вернулась; то Скорн больше нам не угрожает?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11251,'С новыми силами','Мы заплатили высокую цену, но все-таки закончили разведку местности.$b$bК сожалению, сведения не очень обнадеживают. Практически всех жителей захватили в плен или убили. Пропавшими без вести числятся лишь несколько опытных стражей.$b$bРазведчики сделали все, что могли – теперь настала твоя очередь действовать.$b$bИз-за холма на северо-востоке доносятся звуки сражения. Узнай, что там происходит, |3-6($c). Будем надеяться, мы найдем выживших, и они дадут нам информацию, которую можно будет использовать против наших врагов.','Разведчица Валори просит вас узнать, что за звуки битвы доносятся из-за холма на северо-востоке Деревни Драконьего Черепа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','С новыми силами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы заплатили высокую цену, но все-таки закончили разведку местности.$b$bК сожалению, сведения не очень обнадеживают. Практически всех жителей захватили в плен или убили. Пропавшими без вести числятся лишь несколько опытных стражей.$b$bРазведчики сделали все, что могли – теперь настала твоя очередь действовать.$b$bИз-за холма на северо-востоке доносятся звуки сражения. Узнай, что там происходит, |3-6($c). Будем надеяться, мы найдем выживших, и они дадут нам информацию, которую можно будет использовать против наших врагов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разведчица Валори просит вас узнать, что за звуки битвы доносятся из-за холма на северо-востоке Деревни Драконьего Черепа.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11252,'На Утгард!','Слушай, $gюнец:девчонка;,. Я уже убил столько этих тварей, сколько тебе за всю жизнь не положить. Сечешь?...$b$bВрайкулы не знают страха в битве. Иногда кажется, что они равнодушны к смерти. Учитывая их свирепость и их численность – мы обречены. Вот так-то.$b$bЕсть, правда, среди них один врайкул, которого они уважают. Зовут его Ингвар. Не знаю уж, почему они так перед ним пресмыкаются, но твоя победа над ним повергнет их в ужас.$b$bТогда, возможно, у нас появится шанс...','Защитник Мордун поручил вам казнить Ингвара Грабителя, который обитает в Утгарде, и принести его голову вице-адмиралу Келлеру.','Замечательно!$B$BЭто может быть удача, на которую все мы надеялись.$B$B$GМолодец:Умница;, $N!','Рад видеть, что ты $Gздоров:здорова;, $N.$B$BУ нас было столько жертв и мы выдержали.','Вернитесь к вице-адмиралу Келлеру в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На Утгард!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай, $gюнец:девчонка;,. Я уже убил столько этих тварей, сколько тебе за всю жизнь не положить. Сечешь?...$b$bВрайкулы не знают страха в битве. Иногда кажется, что они равнодушны к смерти. Учитывая их свирепость и их численность – мы обречены. Вот так-то.$b$bЕсть, правда, среди них один врайкул, которого они уважают. Зовут его Ингвар. Не знаю уж, почему они так перед ним пресмыкаются, но твоя победа над ним повергнет их в ужас.$b$bТогда, возможно, у нас появится шанс...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Защитник Мордун поручил вам казнить Ингвара Грабителя, который обитает в Утгарде, и принести его голову вице-адмиралу Келлеру.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно!$B$BЭто может быть удача, на которую все мы надеялись.$B$B$GМолодец:Умница;, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Рад видеть, что ты $Gздоров:здорова;, $N.$B$BУ нас было столько жертв и мы выдержали.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вице-адмиралу Келлеру в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11253,'По следу врага','Теперь, когда этот подлец набил свое брюхо, возможно, он захочет немного потрудиться. Вот его поводок – иди и забери его из клетки.$B$BНе знаю, что там хочет от тебя Ансельм, но этот пес точно приведет тебя к цели.','Воспользуйтесь ошейником чумного пса и заберите из клетки в Лагере Возмездия чумного пса-ищейку. Идите с ним по следу, куда бы он вас не привел.','А, вот и ты!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','По следу врага',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда этот подлец набил свое брюхо, возможно, он захочет немного потрудиться. Вот его поводок – иди и забери его из клетки.$B$BНе знаю, что там хочет от тебя Ансельм, но этот пес точно приведет тебя к цели.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь ошейником чумного пса и заберите из клетки в Лагере Возмездия чумного пса-ищейку. Идите с ним по следу, куда бы он вас не привел.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, вот и ты!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11254,'Карта на шкуре дракона','Внимательно изучив свиток, вы понимаете, что это подробная карта фьорда. Местонахождения различных деревень отмечены символами, напоминающими племенные знаки. $B$BЛагерь Возмездия помечен огромным рисунком, изображающим череп.$B$BЭта карта, несомненно, представляет огромный интерес для верховного палача Ансельма.','Принесите карту на шкуре дракона верховному палачу Ансельму в Лагерь Возмездия.','<Верховный палач внимательно рассматривает карту, изучая символы вокруг Фьорда.>\n\nТак, это восточное побережье. Значит, деревни Потрошителей Драконов и Снежескорнов находятся здесь и здесь... а это, должно быть, мы, приговоренные к смерти.','Ты хочешь мне что-то показать, |3-6($C)?','Вернитесь к верховному палачу Ансельму в Лагерь Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Карта на шкуре дракона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Внимательно изучив свиток, вы понимаете, что это подробная карта фьорда. Местонахождения различных деревень отмечены символами, напоминающими племенные знаки. $B$BЛагерь Возмездия помечен огромным рисунком, изображающим череп.$B$BЭта карта, несомненно, представляет огромный интерес для верховного палача Ансельма.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите карту на шкуре дракона верховному палачу Ансельму в Лагерь Возмездия.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Верховный палач внимательно рассматривает карту, изучая символы вокруг Фьорда.>\n\nТак, это восточное побережье. Значит, деревни Потрошителей Драконов и Снежескорнов находятся здесь и здесь... а это, должно быть, мы, приговоренные к смерти.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты хочешь мне что-то показать, |3-6($C)?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Ансельму в Лагерь Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11255,'Пленники в Деревне Драконьего Черепа','Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас спасти 3 пленных валгардских узников.','Спасенные тобой солдаты предоставили нам крайне важную информацию. Эти твари называют себя "врайкулами". Их племя, обосновавшееся в Деревне Драконьего Черепа, возглавляет мистик по имени Янис, который провозглашает себя служителем другого врайкула, Ингвара Расхитителя.','Вложи в него опору, $N! На карту поставлены жизни людей!','Вернитесь к вице-адмиралу Келлеру в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пленники в Деревне Драконьего Черепа',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас спасти 3 пленных валгардских узников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасенные тобой солдаты предоставили нам крайне важную информацию. Эти твари называют себя "врайкулами". Их племя, обосновавшееся в Деревне Драконьего Черепа, возглавляет мистик по имени Янис, который провозглашает себя служителем другого врайкула, Ингвара Расхитителя.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вложи в него опору, $N! На карту поставлены жизни людей!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вице-адмиралу Келлеру в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11256,'Скорн должен пасть!','$n! Врайкульская крепость – Скорн – находится на юге. Недавно в ней пробудились некие странные великаны, которые теперь повсеместно атакуют наши войска.$B$BМои разведчики сообщают, что они планируют напасть на наш лагерь, и мы не сможем им противостоять. Единственный выход для моего народа – покинуть эти земли и уйти на север, в более безопасное место.$B$BЯ прошу тебя, приложи все свои умения и выиграй для нас немного времени. Я выслал вперед храбреца из нашего племени. Покажи ему эту эмблему, и он расскажет тебе, что надо сделать.','Интересно будет познакомиться с твоим народом, |3-6($C). Скоро мы будем сражаться бок о бок! \n\nНу, что, за работу?','Ты испытал руну?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скорн должен пасть!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Врайкульская крепость – Скорн – находится на юге. Недавно в ней пробудились некие странные великаны, которые теперь повсеместно атакуют наши войска.$B$BМои разведчики сообщают, что они планируют напасть на наш лагерь, и мы не сможем им противостоять. Единственный выход для моего народа – покинуть эти земли и уйти на север, в более безопасное место.$B$BЯ прошу тебя, приложи все свои умения и выиграй для нас немного времени. Я выслал вперед храбреца из нашего племени. Покажи ему эту эмблему, и он расскажет тебе, что надо сделать.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Интересно будет познакомиться с твоим народом, |3-6($C). Скоро мы будем сражаться бок о бок! \n\nНу, что, за работу?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты испытал руну?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11257,'Тяжело, но необходимо','Наши старейшины говорят, что врайкулы могут восставать из мертвых. Нет, они не похожи на оживших мертвецов Плети, но их понятие жизни после смерти несет нам не меньшие беды.$B$BМы не можем так рисковать!$B$BВот, возьми мое мачете. Пока мы будем продвигаться вперед, кромсай им все трупы врайкулов, которые встретятся тебе по пути.$B$BЯ потратил все утро на заточку клинка, так что теперь он разрубит даже самые толстые кости.','Тебе уже приходилось держать в руках мачете? Кажется, ты с ним вполне неплохо управляешься.\n\n<Храбрец с опаской смотрит на вас.>\n\nДавай-ка я заберу его у тебя, |3-6($C). На всякий случай.','Знаешь, когда здания загорятся, нам лучше отбежать подальше. Дух огня не знает жалости в своем стремлении разрушать.','Поговорите с храбрецом из лагеря Заиндевевшего Копыта. Чтобы позвать его, воспользуйтесь эмблемой Заиндевевшего Копыта.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тяжело, но необходимо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши старейшины говорят, что врайкулы могут восставать из мертвых. Нет, они не похожи на оживших мертвецов Плети, но их понятие жизни после смерти несет нам не меньшие беды.$B$BМы не можем так рисковать!$B$BВот, возьми мое мачете. Пока мы будем продвигаться вперед, кромсай им все трупы врайкулов, которые встретятся тебе по пути.$B$BЯ потратил все утро на заточку клинка, так что теперь он разрубит даже самые толстые кости.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тебе уже приходилось держать в руках мачете? Кажется, ты с ним вполне неплохо управляешься.\n\n<Храбрец с опаской смотрит на вас.>\n\nДавай-ка я заберу его у тебя, |3-6($C). На всякий случай.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаешь, когда здания загорятся, нам лучше отбежать подальше. Дух огня не знает жалости в своем стремлении разрушать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с храбрецом из лагеря Заиндевевшего Копыта. Чтобы позвать его, воспользуйтесь эмблемой Заиндевевшего Копыта.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11258,'Гори, Скорн, гори!','Вождь Прахтотем приказал мне разрушить множество зданий в Скорне.$B$BНо теперь я могу смело доверить это ответственное задание своему командиру – то есть тебе, $n.$B$BПредлагаю сжечь два больших дома и казармы в нижнем квартале Скорна. Нам надо просто прокрасться в каждый дом и поджечь его факелом изнутри.','Знаешь, когда здания загорятся, нам лучше отбежать подальше. Дух огня не знает жалости в своем стремлении разрушать.','Поговорите с храбрецом из лагеря Заиндевевшего Копыта. Чтобы позвать его, воспользуйтесь эмблемой Заиндевевшего Копыта.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гори, Скорн, гори!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вождь Прахтотем приказал мне разрушить множество зданий в Скорне.$B$BНо теперь я могу смело доверить это ответственное задание своему командиру – то есть тебе, $n.$B$BПредлагаю сжечь два больших дома и казармы в нижнем квартале Скорна. Нам надо просто прокрасться в каждый дом и поджечь его факелом изнутри.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаешь, когда здания загорятся, нам лучше отбежать подальше. Дух огня не знает жалости в своем стремлении разрушать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с храбрецом из лагеря Заиндевевшего Копыта. Чтобы позвать его, воспользуйтесь эмблемой Заиндевевшего Копыта.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11259,'Смертельно опасные башни','Знаешь, когда здания загорятся, нам лучше отбежать подальше. Дух огня не знает жалости в своем стремлении разрушать.','Поговорите с храбрецом из лагеря Заиндевевшего Копыта. Чтобы позвать его, воспользуйтесь эмблемой Заиндевевшего Копыта.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смертельно опасные башни',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Знаешь, когда здания загорятся, нам лучше отбежать подальше. Дух огня не знает жалости в своем стремлении разрушать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с храбрецом из лагеря Заиндевевшего Копыта. Чтобы позвать его, воспользуйтесь эмблемой Заиндевевшего Копыта.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11260,'Остановить вознесение!','Этот огромный сверток сделан из драконьей кожи. Развернув его на всю длину, вы видите таинственные знаки на чешуйчатой поверхности, изображающие ход врайкульского ритуала. $B$BТам нарисован тан врайкульского клана, поднимающийся в небо в окружении ангелоподобных существ. Позади него во мраке изображена темная, загадочная фигура.$B$BЧто-то подсказывает вам, что глава скорнского клана собирается пройти через этот ритуал. Вы должны его остановить! Напротив дома тана уже вздымается в небо огромный погребальный костер.','Да? Чем я могу помочь тебе, дитя мое?','Вернитесь к Великой Матери Анкхе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановить вознесение!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот огромный сверток сделан из драконьей кожи. Развернув его на всю длину, вы видите таинственные знаки на чешуйчатой поверхности, изображающие ход врайкульского ритуала. $B$BТам нарисован тан врайкульского клана, поднимающийся в небо в окружении ангелоподобных существ. Позади него во мраке изображена темная, загадочная фигура.$B$BЧто-то подсказывает вам, что глава скорнского клана собирается пройти через этот ритуал. Вы должны его остановить! Напротив дома тана уже вздымается в небо огромный погребальный костер.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да? Чем я могу помочь тебе, дитя мое?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Великой Матери Анкхе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11261,'Покоритель Скорна!','Ты $gсделал:сделала; все, ради чего нас сюда послали, |3-6($c). Должен признать, ты храбро $gсражался:сражалась;. Твой народ не такой уж и странный, как мне показалось сначала.$B$BВождь Прахтотем будет рад услышать о твоей победе, но если ты по какой-то причине решишь задержаться здесь – обращайся ко мне. Я всегда к твоим услугам.','Отличные новости! Теперь мы можем спокойно подготовиться к отступлению.\n\nПрошу, возьми это в знак нашей благодарности.','Вернитесь к вождю Прахтотему в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покоритель Скорна!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсделал:сделала; все, ради чего нас сюда послали, |3-6($c). Должен признать, ты храбро $gсражался:сражалась;. Твой народ не такой уж и странный, как мне показалось сначала.$B$BВождь Прахтотем будет рад услышать о твоей победе, но если ты по какой-то причине решишь задержаться здесь – обращайся ко мне. Я всегда к твоим услугам.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличные новости! Теперь мы можем спокойно подготовиться к отступлению.\n\nПрошу, возьми это в знак нашей благодарности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Прахтотему в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11263,'Очистить Гьялерброн','Выжившие гонцы сообщили, что врайкулы замышляют нечто недоброе в своей главной крепости к западу отсюда. $B$BЭто запретное место зовется Гьялерброн. Мои выносливые гонцы доложили, что врайкулы проводят там некие странные ритуалы. $B$BЭтого мы не можем допустить.$B$BХочешь помочь нам? Тогда убей врайкулов в Гьялерброне прежде, чем они закончат свои приготовления и нападут на нас!','Ледяной змей и его хозяин мертвы?\n\nНо где же рог?','Вернитесь к вождю Прахтотему в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очистить Гьялерброн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Выжившие гонцы сообщили, что врайкулы замышляют нечто недоброе в своей главной крепости к западу отсюда. $B$BЭто запретное место зовется Гьялерброн. Мои выносливые гонцы доложили, что врайкулы проводят там некие странные ритуалы. $B$BЭтого мы не можем допустить.$B$BХочешь помочь нам? Тогда убей врайкулов в Гьялерброне прежде, чем они закончат свои приготовления и нападут на нас!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ледяной змей и его хозяин мертвы?\n\nНо где же рог?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Прахтотему в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11264,'Некровладыка Мезхен','Мертвецы уже пришли в Гьялерброн, и они привели с собой некромантов?$B$BПредводитель этих некролордов должен умереть!$B$B$n, на твои плечи ложится огромная ответственность – ты $gдолжен:должна; сорвать планы некровладыки Мезхена и уничтожить его самого.$B$BЯ не допущу, чтобы эти врайкулы заключили союз с мертвецами! $B$BМезхена можно найти на платформе в дальнем правом квартале Гьялерброна.','Ледяной змей и его хозяин мертвы?\n\nНо где же рог?','Вернитесь к вождю Прахтотему в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Некровладыка Мезхен',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мертвецы уже пришли в Гьялерброн, и они привели с собой некромантов?$B$BПредводитель этих некролордов должен умереть!$B$B$n, на твои плечи ложится огромная ответственность – ты $gдолжен:должна; сорвать планы некровладыки Мезхена и уничтожить его самого.$B$BЯ не допущу, чтобы эти врайкулы заключили союз с мертвецами! $B$BМезхена можно найти на платформе в дальнем правом квартале Гьялерброна.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ледяной змей и его хозяин мертвы?\n\nНо где же рог?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Прахтотему в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11265,'О ключах и клетках','Насколько нам известно, врайкулы совершают какие-то омерзительные ритуалы "пробуждения" к северу от Гьялерброна.$B$BВ ходе этих обрядов проливается кровь невинных жертв!$B$B$n, ты $gдолжен:должна; остановить это! Неважно, кого они держат в своих клетках для жертвоприношений – их надо освободить. Могу поспорить, врайкулы носят ключи при себе.$B$BНам не нужны эти мерзкие врайкулы поблизости, и еще меньше нам хочется разбираться с тем злом, которое они пытаются пробудить!','Ты уверен, что Мезхен и прочие некровладыки мертвы?','Вернитесь к Великой Матери Анкхе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','О ключах и клетках',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Насколько нам известно, врайкулы совершают какие-то омерзительные ритуалы "пробуждения" к северу от Гьялерброна.$B$BВ ходе этих обрядов проливается кровь невинных жертв!$B$B$n, ты $gдолжен:должна; остановить это! Неважно, кого они держат в своих клетках для жертвоприношений – их надо освободить. Могу поспорить, врайкулы носят ключи при себе.$B$BНам не нужны эти мерзкие врайкулы поблизости, и еще меньше нам хочется разбираться с тем злом, которое они пытаются пробудить!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уверен, что Мезхен и прочие некровладыки мертвы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Великой Матери Анкхе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11266,'Гьялербронский план нападения','Что это?! Планы нападения на лагерь?\n\nОНИ ПОСЫЛАЮТ К НАМ ЛЕТУЧЕГО ЗМЕЯ?!','Вернитесь к Целее Ледогрив в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гьялербронский план нападения',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это?! Планы нападения на лагерь?\n\nОНИ ПОСЫЛАЮТ К НАМ ЛЕТУЧЕГО ЗМЕЯ?!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Целее Ледогрив в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11268,'Ходячие мертвецы','Ты уже $gсделал:сделала; для нас больше, чем мы рассчитывали, $n, но меня по-прежнему беспокоит одна проблема: Плеть.$B$BДухи земли и воздуха, огня и воды не переносят присутствия этих тварей, но ничего не могут им противопоставить. Это значит, что за дело должны взяться мы! $B$BВозможно, я прошу слишком многого, но ты $gдолжен:должна; вернуться на запад, в Гьялерброн, и уничтожить логово этой омерзительной Плети! Не забудь проверить, не остались ли эти презренные твари в чертогах Пробуждения, что под Гьялерброном.','Ледяной змей и его хозяин мертвы?\n\nНо где же рог?','Вернитесь к Великой Матери Анкхе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ходячие мертвецы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты уже $gсделал:сделала; для нас больше, чем мы рассчитывали, $n, но меня по-прежнему беспокоит одна проблема: Плеть.$B$BДухи земли и воздуха, огня и воды не переносят присутствия этих тварей, но ничего не могут им противопоставить. Это значит, что за дело должны взяться мы! $B$BВозможно, я прошу слишком многого, но ты $gдолжен:должна; вернуться на запад, в Гьялерброн, и уничтожить логово этой омерзительной Плети! Не забудь проверить, не остались ли эти презренные твари в чертогах Пробуждения, что под Гьялерброном.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ледяной змей и его хозяин мертвы?\n\nНо где же рог?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Великой Матери Анкхе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11269,'Работаем до упора','Со дня на день прибудет авангард войск Альянса. Всех этих солдат надо переодеть в зимнюю униформу, а я еще не закончил шить плащи. $B$BЯ подбиваю наши плащи пухом пятнистых гиппогрифов, но мои запасы не бесконечны!$B$BПомоги мне, $n. Капитан Адамс с меня шкуру сдерет, если плащи не будут готовы к сроку! Принеси мне весь пух, который сможешь найти. В чаще вокруг форта всегда полно линяющих гиппогрифов. Их пух валяется повсюду.','Гил Гризерт просит вас принести ему 10 клочков пуха пятнистых гиппогрифов.','Слава богам! Этого хватит, чтобы закончить пошив плащей к сроку. Ночами спать не буду, но закончу работу до прибытия войск. Все лучше, чем попасться под горячую руку капитану Адамсу.$B$BНаслышан я про этого вояку!','Вернитесь к Гилу Гризерту в Крепость Вилдервар, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Работаем до упора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Со дня на день прибудет авангард войск Альянса. Всех этих солдат надо переодеть в зимнюю униформу, а я еще не закончил шить плащи. $B$BЯ подбиваю наши плащи пухом пятнистых гиппогрифов, но мои запасы не бесконечны!$B$BПомоги мне, $n. Капитан Адамс с меня шкуру сдерет, если плащи не будут готовы к сроку! Принеси мне весь пух, который сможешь найти. В чаще вокруг форта всегда полно линяющих гиппогрифов. Их пух валяется повсюду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гил Гризерт просит вас принести ему 10 клочков пуха пятнистых гиппогрифов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава богам! Этого хватит, чтобы закончить пошив плащей к сроку. Ночами спать не буду, но закончу работу до прибытия войск. Все лучше, чем попасться под горячую руку капитану Адамсу.$B$BНаслышан я про этого вояку!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гилу Гризерту в Крепость Вилдервар, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11270,'Ужасы войны','Мы постепенно заканчиваем зачистку северного флота Штормграда, высадившегося на побережье. Схватка была ожесточенной, чему свидетельствует множество мертвых тел на западе.$B$BНет, эти трупы не оскорбляют мое чувство прекрасного, но они могут стать угрозой всем нам.$B$BВидишь ли, в землях Короля-лича мертвецов очень легко превратить в оружие. Возьми этот факел и сделай все возможное, чтобы этого не произошло.','Верховный палач Ансельм из Лагеря Возмездия просит вас взять горящий факел и сжечь десять трупов, лежащих к западу от города.','Мне все равно, сколько гигантов, драконов или кобольдов тебе довелось убить. Не возвращайся, пока не выполнишь мое поручение.','Вернитесь к верховному палачу Ансельму в Лагерь Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ужасы войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы постепенно заканчиваем зачистку северного флота Штормграда, высадившегося на побережье. Схватка была ожесточенной, чему свидетельствует множество мертвых тел на западе.$B$BНет, эти трупы не оскорбляют мое чувство прекрасного, но они могут стать угрозой всем нам.$B$BВидишь ли, в землях Короля-лича мертвецов очень легко превратить в оружие. Возьми этот факел и сделай все возможное, чтобы этого не произошло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верховный палач Ансельм из Лагеря Возмездия просит вас взять горящий факел и сжечь десять трупов, лежащих к западу от города.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне все равно, сколько гигантов, драконов или кобольдов тебе довелось убить. Не возвращайся, пока не выполнишь мое поручение.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному палачу Ансельму в Лагерь Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11271,'Спешные приготовления','Пух пятнистых гиппогрифов очень ценится среди моего народа и используется в самых разнообразных целях – от оперения стрел до пошива церемониальной одежды. Поскольку мы готовимся покинуть аванпост, это наша последняя возможность набрать пух в сезон линьки.$B$BС твоей помощью я сделаю достаточный запас пуха, которого хватит на все путешествие. А дорога обещает быть нелегкой!$B$BИщи клочья пуха повсюду на земле вокруг аванпоста.','С твоей помощью мы сможем хорошо подготовиться к этому нелегкому путешествию. Мне почти нечем тебя отблагодарить, но все же возьми одну из этих вещей, лежащих у меня без дела.','Ты нашел пух гиппогрифов?','Вернитесь к Ахоте Белому Инею в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спешные приготовления',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пух пятнистых гиппогрифов очень ценится среди моего народа и используется в самых разнообразных целях – от оперения стрел до пошива церемониальной одежды. Поскольку мы готовимся покинуть аванпост, это наша последняя возможность набрать пух в сезон линьки.$B$BС твоей помощью я сделаю достаточный запас пуха, которого хватит на все путешествие. А дорога обещает быть нелегкой!$B$BИщи клочья пуха повсюду на земле вокруг аванпоста.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','С твоей помощью мы сможем хорошо подготовиться к этому нелегкому путешествию. Мне почти нечем тебя отблагодарить, но все же возьми одну из этих вещей, лежащих у меня без дела.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел пух гиппогрифов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ахоте Белому Инею в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11273,'Объединение людей','Мы были на грани величайшего археологического открытия, когда эти чудовища напали на наш лагерь! Увы, вернуться в Валгард удалось только мне одному. Я даже не знаю, что стало с моими людьми, и куда пропали артефакты, которые мы достали из раскопа! Как бы то ни было, их надо вернуть!$B$BРаз уж ты все равно направляешься в Деревню Драконьего Черепа, поищи, пожалуйста, моих сослуживцев! Если есть хоть какая-то надежда сохранить полученную информацию, мы должны ей воспользоваться!$B$BПрежде всего постарайся найти Пулроя. Когда я бежал из лагеря, он был еще жив.','Найдите Пулроя в Деревне Драконьего Черепа.','Вы нашли Пулроя – увы, слишком поздно.$B$BОбыскав тело археолога, вы видите журнал, крепко зажатый в руке Пулроя. Похоже, это предсмертные записи несчастного дворфа.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Объединение людей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы были на грани величайшего археологического открытия, когда эти чудовища напали на наш лагерь! Увы, вернуться в Валгард удалось только мне одному. Я даже не знаю, что стало с моими людьми, и куда пропали артефакты, которые мы достали из раскопа! Как бы то ни было, их надо вернуть!$B$BРаз уж ты все равно направляешься в Деревню Драконьего Черепа, поищи, пожалуйста, моих сослуживцев! Если есть хоть какая-то надежда сохранить полученную информацию, мы должны ей воспользоваться!$B$BПрежде всего постарайся найти Пулроя. Когда я бежал из лагеря, он был еще жив.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Пулроя в Деревне Драконьего Черепа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы нашли Пулроя – увы, слишком поздно.$B$BОбыскав тело археолога, вы видите журнал, крепко зажатый в руке Пулроя. Похоже, это предсмертные записи несчастного дворфа.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11274,'Зедд мертв, детка?','Тому, кто найдет этот журнал:$B$BЭти кровожадные мерзавцы захватили руины Драконьего Черепа. Я не знаю, зачем они сюда пришли и чего добиваются. Честно говоря, мне все равно – я беспокоюсь только за сохранность артефактов.$B$BПрячась в этом месте, мы с Зеддом натолкнулись на потрясающее открытие: мы обнаружили шифр к табличкам! К несчастью, прошлой ночью Зедд отстал. Шифр все еще у него. Таблички унесли Глоренфелд и Дегарн. Где они – неизвестно...$B$BНайди Зедда.$B$B-Пулрой','Найдите Зедда в Деревне Драконьего Черепа.','Вы нашли Зедда. Увы, не надо быть доктором, чтобы понять, что для бедняги все кончено.$B$BПохоже, его собирались скормить воргам. Бедняга...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зедд мертв, детка?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тому, кто найдет этот журнал:$B$BЭти кровожадные мерзавцы захватили руины Драконьего Черепа. Я не знаю, зачем они сюда пришли и чего добиваются. Честно говоря, мне все равно – я беспокоюсь только за сохранность артефактов.$B$BПрячась в этом месте, мы с Зеддом натолкнулись на потрясающее открытие: мы обнаружили шифр к табличкам! К несчастью, прошлой ночью Зедд отстал. Шифр все еще у него. Таблички унесли Глоренфелд и Дегарн. Где они – неизвестно...$B$BНайди Зедда.$B$B-Пулрой',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Зедда в Деревне Драконьего Черепа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы нашли Зедда. Увы, не надо быть доктором, чтобы понять, что для бедняги все кончено.$B$BПохоже, его собирались скормить воргам. Бедняга...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11275,'Охотничий рог','Многие поколения мои соплеменники охотились на гигантских йети, обитающих в этих холмах. В этом году наконец-то настал мой черед присоединиться к охоте. Надеюсь, мы успеем загнать немало йети перед тем, как навсегда покинем эти края.$B$BЧтобы подготовиться к охоте, мне надо вырезать охотничий рог из рогов жутких баранов, которые бродят вокруг нашего лагеря. Старейшины сказали, что звук охотничьего рога напоминает брачный зов самки йети, но мне в это верится с трудом.$B$BВпрочем, неважно – главное, сделать рог. Давай ты принесешь мне самые лучшие рога барана, а я выберу себе один для отделки.','Ты нашел какие-нибудь подходящие рога?','Вернитесь к Нокоме Заклинателю Снегов в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охотничий рог',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие поколения мои соплеменники охотились на гигантских йети, обитающих в этих холмах. В этом году наконец-то настал мой черед присоединиться к охоте. Надеюсь, мы успеем загнать немало йети перед тем, как навсегда покинем эти края.$B$BЧтобы подготовиться к охоте, мне надо вырезать охотничий рог из рогов жутких баранов, которые бродят вокруг нашего лагеря. Старейшины сказали, что звук охотничьего рога напоминает брачный зов самки йети, но мне в это верится с трудом.$B$BВпрочем, неважно – главное, сделать рог. Давай ты принесешь мне самые лучшие рога барана, а я выберу себе один для отделки.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел какие-нибудь подходящие рога?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нокоме Заклинателю Снегов в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11276,'И их осталось двое...','Похоже, у Зедда не было с собой шифра. Тщательно осмотрев местность, вы находите в грязи надпись, которая гласит:$B$B"Глор и Дег в катакомбах. Шифр и таблички у них."$B$BПохоже, вам придется отправиться в катакомбы, которые находятся к северу от этого места, и найти Глоренфелда и Дегарна. За мостом, перекинутым через яму с воргами, виднеется туннель, который ведет прямо в катакомбы.','Обыщите Катакомбы Утгард в поисках Глоренфелда.','Ну наконец-то! Пулрой и Зедд мертвы.$B$BА Дегарн...$B$B<Глоренфелд качает головой.>$B$BВождь Укротителей драконов утащил его в глубину катакомб. Я услышал краем уха, как этот гамадрил-переросток говорил что-то о "пожертвовании Королю ужаса"$B$BШифр у него, спрятан в бороде.$B$BЧего-о? Дворфы всегда прячут самые ценные вещи в бороде!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И их осталось двое...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, у Зедда не было с собой шифра. Тщательно осмотрев местность, вы находите в грязи надпись, которая гласит:$B$B"Глор и Дег в катакомбах. Шифр и таблички у них."$B$BПохоже, вам придется отправиться в катакомбы, которые находятся к северу от этого места, и найти Глоренфелда и Дегарна. За мостом, перекинутым через яму с воргами, виднеется туннель, который ведет прямо в катакомбы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обыщите Катакомбы Утгард в поисках Глоренфелда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ну наконец-то! Пулрой и Зедд мертвы.$B$BА Дегарн...$B$B<Глоренфелд качает головой.>$B$BВождь Укротителей драконов утащил его в глубину катакомб. Я услышал краем уха, как этот гамадрил-переросток говорил что-то о "пожертвовании Королю ужаса"$B$BШифр у него, спрятан в бороде.$B$BЧего-о? Дворфы всегда прячут самые ценные вещи в бороде!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11277,'Глубины порока','Они держат Дегарна в запертой клетке на огромной арене для гладиаторских боев. Насколько я понял, Укротители драконов выпускают своих пленников на эту арену, чтобы те сражались с самыми безжалостными врайкульскими бойцами. Неудачников они скидывают вниз, в подвалы, где Плеть превращает их в зомби! Ужасно, не правда ли?$B$BНо сначала мы должны решить первоочередные проблемы. Главное – собрать таблички, которые разбросаны по всему подземелью! Найди их – а потом можешь играть в героя-освободителя!','Глоренфелд из Катакомб Утгард просит вас собрать 10 табличек Драконьего Черепа.','Проверь каждый уголок!','Вернитесь к Глоренфелду в Катакомбы Утгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глубины порока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они держат Дегарна в запертой клетке на огромной арене для гладиаторских боев. Насколько я понял, Укротители драконов выпускают своих пленников на эту арену, чтобы те сражались с самыми безжалостными врайкульскими бойцами. Неудачников они скидывают вниз, в подвалы, где Плеть превращает их в зомби! Ужасно, не правда ли?$B$BНо сначала мы должны решить первоочередные проблемы. Главное – собрать таблички, которые разбросаны по всему подземелью! Найди их – а потом можешь играть в героя-освободителя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Глоренфелд из Катакомб Утгард просит вас собрать 10 табличек Драконьего Черепа.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Проверь каждый уголок!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глоренфелду в Катакомбы Утгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11278,'Возвращение в Валгард','Мне горько думать о том, что мы потеряли двух наших лучших дворфов в поисках этих святынь. Они пожертвовали своими жизнями, чтобы сохранить и донести до нас эту информацию.$B$B<Глоренфелд заворачивает шифр и таблички в потрепанный платок.>$B$BОтнеси это назад, в Валгард. Максорф знает, что надо делать.$B$BЯ? Со мной все будет в порядке. Видишь – я пока что цел и невредим.','Отнесите сверток Глоренфелда Белтранду Максорфу в Валгардский порт.','Мне понадобится время, чтобы рассортировать эти таблички. Но я уверен, что мои исследования прольют свет на тайну происхождения людей. Я уверен, что когда-то здесь жили наши предки, но все они были уничтожены врайкулами. Как только я расшифрую надписи на этих святынях, мы узнаем правду.','Вернитесь к Белтранду Максорфу в Ревущий фьорд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение в Валгард',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне горько думать о том, что мы потеряли двух наших лучших дворфов в поисках этих святынь. Они пожертвовали своими жизнями, чтобы сохранить и донести до нас эту информацию.$B$B<Глоренфелд заворачивает шифр и таблички в потрепанный платок.>$B$BОтнеси это назад, в Валгард. Максорф знает, что надо делать.$B$BЯ? Со мной все будет в порядке. Видишь – я пока что цел и невредим.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сверток Глоренфелда Белтранду Максорфу в Валгардский порт.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мне понадобится время, чтобы рассортировать эти таблички. Но я уверен, что мои исследования прольют свет на тайну происхождения людей. Я уверен, что когда-то здесь жили наши предки, но все они были уничтожены врайкулами. Как только я расшифрую надписи на этих святынях, мы узнаем правду.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Белтранду Максорфу в Ревущий фьорд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11279,'Зеленые и светящиеся','Мы разработали превосходную чуму, и мне не терпится расширить поле экспериментов. $B$BМожет быть, нам испытать ее на детенышах протодраконов?!$B$BТы только подумай о том, какие возможности открываются перед нами! Мы станем первооткрывателями штамма, способного поражать всех живых существ!$B$BВот, я отложил на всякий случай запасную канистру с чумой. Полагаю, я могу доверить ее тебе.$B$BОбрызгай яйца протодраконов в Пылающем Гнездовье на северо-западе, после чего возьми образцы зачумленных детенышей протодраконов, которые вылупятся из зараженной кладки.','Распространитель чумы Тилингаст попросил вас собрать 10 образцов плоти зачумленных детенышей протодраконов и отнести их к нему в Новый Агамонд.','Без этих образцов я не смогу доказать нашему научному сообществу, что мой штамм способен поражать все живые организмы!','Вернитесь к распространителю чумы Тилингасту в Новый Агамонд, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зеленые и светящиеся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы разработали превосходную чуму, и мне не терпится расширить поле экспериментов. $B$BМожет быть, нам испытать ее на детенышах протодраконов?!$B$BТы только подумай о том, какие возможности открываются перед нами! Мы станем первооткрывателями штамма, способного поражать всех живых существ!$B$BВот, я отложил на всякий случай запасную канистру с чумой. Полагаю, я могу доверить ее тебе.$B$BОбрызгай яйца протодраконов в Пылающем Гнездовье на северо-западе, после чего возьми образцы зачумленных детенышей протодраконов, которые вылупятся из зараженной кладки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Распространитель чумы Тилингаст попросил вас собрать 10 образцов плоти зачумленных детенышей протодраконов и отнести их к нему в Новый Агамонд.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Без этих образцов я не смогу доказать нашему научному сообществу, что мой штамм способен поражать все живые организмы!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к распространителю чумы Тилингасту в Новый Агамонд, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11280,'Драконис гастритис','У меня появилась мысль. Что если чума не убила дракончиков потому, что мы распыляли отраву снаружи?$B$B$n, мы должны как-то заразить их изнутри!$B$BПридумал! Вот, держи кусок зачумленного мяса. Отнеси его в Пылающее Гнездовье и скорми дракончикам!$B$BХотя нет, мы должны мыслить шире. Лучше примани с его помощью большого протодракона – пусть он спустится с неба и сожрет наше угощение.$B$BЯ гений!$B$BКстати, не отходи далеко от нашего подопытного и наблюдай, что произойдет. Он, конечно, может напасть на тебя... но такова цена прогресса!','Распространитель чумы Тилингаст просит вас приманить протодракона с помощью куска зачумленного мяса Тилингаста и понаблюдать за его реакцией на угощение.','Клыкаррам нужна твоя помощь!','Вернитесь к распространителю чумы Тилингасту в Новый Агамонд, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Драконис гастритис',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня появилась мысль. Что если чума не убила дракончиков потому, что мы распыляли отраву снаружи?$B$B$n, мы должны как-то заразить их изнутри!$B$BПридумал! Вот, держи кусок зачумленного мяса. Отнеси его в Пылающее Гнездовье и скорми дракончикам!$B$BХотя нет, мы должны мыслить шире. Лучше примани с его помощью большого протодракона – пусть он спустится с неба и сожрет наше угощение.$B$BЯ гений!$B$BКстати, не отходи далеко от нашего подопытного и наблюдай, что произойдет. Он, конечно, может напасть на тебя... но такова цена прогресса!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Распространитель чумы Тилингаст просит вас приманить протодракона с помощью куска зачумленного мяса Тилингаста и понаблюдать за его реакцией на угощение.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Клыкаррам нужна твоя помощь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к распространителю чумы Тилингасту в Новый Агамонд, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11281,'Подражая зову природы','Я обточила рог, но прежде чем наносить на него традиционную резьбу, надо убедиться, что он работает. Ахота говорил, что он испытывает свои охотничьи рога у подножия замерзшего водопада на северо-востоке лагеря. Он утверждает, что наши охотники уже много поколений используют акустику льда для этой цели.$B$BТы поможешь мне испытать рог? Если я правильно его вырезала, то на его зов может откликнуться сам великий йети! Только не забудь вернуть мне рог после проверки.','Ты нашел пух гиппогрифов?','Вернитесь к Нокоме Заклинателю Снегов в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подражая зову природы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я обточила рог, но прежде чем наносить на него традиционную резьбу, надо убедиться, что он работает. Ахота говорил, что он испытывает свои охотничьи рога у подножия замерзшего водопада на северо-востоке лагеря. Он утверждает, что наши охотники уже много поколений используют акустику льда для этой цели.$B$BТы поможешь мне испытать рог? Если я правильно его вырезала, то на его зов может откликнуться сам великий йети! Только не забудь вернуть мне рог после проверки.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел пух гиппогрифов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нокоме Заклинателю Снегов в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11282,'Урок страха','Когда ты побываешь в стольких же переделках, как и Горт, ты поймешь, что врага можно победить лишь тогда, когда он боится тебя до смерти! $B$BНо эти врайкулы нас не боятся. Убьешь одного – на его место приходит другой... только вопит еще громче, и секира у него больше в два раза.$B$BТолько смерть самого большого и страшного врайкула может напугать все это племя.$B$BИди же и сражайся со Снежескорнами, пока не появятся их чемпионы. Убей их всех и проткни трупы древком флага Отрекшихся. Пусть они узнают, что такое страх!','По приказу Горта вам надо победить Улфа Кровопускателя, Орика Зловещего и Гуннара Торвардссона, после чего проткнуть их тела древком знамени Отрекшихся. Убивайте врайкулов вдоль баррикады, возведенной Отрекшимися, пока не появятся чемпионы.','Молодец, ты хорошо потрудился. Я видел, как пали врайкулы, пронзенные древком флага Сильваны. Да, сегодня победа на нашей стороне!','Ты убил всех врайкулов? Да, они крепкие твари!','Вернитесь к сержанту Горту к подъемнику лагеря Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Урок страха',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда ты побываешь в стольких же переделках, как и Горт, ты поймешь, что врага можно победить лишь тогда, когда он боится тебя до смерти! $B$BНо эти врайкулы нас не боятся. Убьешь одного – на его место приходит другой... только вопит еще громче, и секира у него больше в два раза.$B$BТолько смерть самого большого и страшного врайкула может напугать все это племя.$B$BИди же и сражайся со Снежескорнами, пока не появятся их чемпионы. Убей их всех и проткни трупы древком флага Отрекшихся. Пусть они узнают, что такое страх!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По приказу Горта вам надо победить Улфа Кровопускателя, Орика Зловещего и Гуннара Торвардссона, после чего проткнуть их тела древком знамени Отрекшихся. Убивайте врайкулов вдоль баррикады, возведенной Отрекшимися, пока не появятся чемпионы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, ты хорошо потрудился. Я видел, как пали врайкулы, пронзенные древком флага Сильваны. Да, сегодня победа на нашей стороне!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты убил всех врайкулов? Да, они крепкие твари!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Горту к подъемнику лагеря Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11283,'Кровавая бойня в Гибльхейме','Эти врайкулы так и прут из западного поселения! Можно подумать, они там почкованием размножаются – так их много.$B$BНо у Горта есть идея. Ты $gсам:сама; пойдешь в этот город и перебьешь всех Снежескорнов. Тогда они перестанут лезть к нам!','Сержант Горт просит вас убить 16 снежескорнских врайкулов в Гибльхейме.','Я гляжу, тебе не впервой убивать! Справляешься с этим делом не хуже Горта!','Все сжег? Проверь еще раз – вдруг что-нибудь осталось.','Вернитесь к сержанту Горту к подъемнику лагеря Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровавая бойня в Гибльхейме',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти врайкулы так и прут из западного поселения! Можно подумать, они там почкованием размножаются – так их много.$B$BНо у Горта есть идея. Ты $gсам:сама; пойдешь в этот город и перебьешь всех Снежескорнов. Тогда они перестанут лезть к нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сержант Горт просит вас убить 16 снежескорнских врайкулов в Гибльхейме.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я гляжу, тебе не впервой убивать! Справляешься с этим делом не хуже Горта!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все сжег? Проверь еще раз – вдруг что-нибудь осталось.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Горту к подъемнику лагеря Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11284,'Соседство с йети','Если охранники не желают помогать мне – может быть, ты меня поддержишь? Я – старшина шахты, которая находится за мостом. Мои люди добывают руду, которая пойдет на выплавку оружия для разведывательных отрядов. Без наших поставок они не смогут расчистить путь к Седым холмам.$B$BНо недавно шахту захватил гигантский йети, преградив путь к тоннелю, который нам необходимо расширить! Мы пытались напугать его криками и даже пробовали выкурить его оттуда, но ничего не получилось.$B$BМожет быть, ты сможешь разбудить его запахом свежей баранины? Вокруг города по снегу бродят множество ледорогих баранов. Пожалуйста, помоги нам! Мы в отчаянии!','Старшина Колби из крепости Вилдервар просит вас убить Сколорога.','Тебе удалось как-нибудь убрать этого глупого йети с моей шахты?','Вернитесь к старшине Колби в Крепость Вилдервар, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Соседство с йети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если охранники не желают помогать мне – может быть, ты меня поддержишь? Я – старшина шахты, которая находится за мостом. Мои люди добывают руду, которая пойдет на выплавку оружия для разведывательных отрядов. Без наших поставок они не смогут расчистить путь к Седым холмам.$B$BНо недавно шахту захватил гигантский йети, преградив путь к тоннелю, который нам необходимо расширить! Мы пытались напугать его криками и даже пробовали выкурить его оттуда, но ничего не получилось.$B$BМожет быть, ты сможешь разбудить его запахом свежей баранины? Вокруг города по снегу бродят множество ледорогих баранов. Пожалуйста, помоги нам! Мы в отчаянии!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Старшина Колби из крепости Вилдервар просит вас убить Сколорога.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось как-нибудь убрать этого глупого йети с моей шахты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старшине Колби в Крепость Вилдервар, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11285,'Гори, Гибльхейм!','Недостаточно просто убить Снежескорнов – мы должны сжечь их дома! Э... и мосты тоже. Давай спалим весь город – на всякий случай!$B$BВот, возьми факел. Иди в Гибльхейм, на запад, и сожги его ДОТЛА! Это научит их бояться.','Сержант Горт послал вас в Гибльхейм с факелом Горта, чтобы вы сожгли 1 снежескорнское здание, 1 снежескорнскую сторожевую башню, 1 снежескорнский мост и 1 снежескорнские казармы.','Похоже, ты сжег почти все постройки. Осталось несколько зданий... но Горт доволен тем, что видит.','Все сжег? Проверь еще раз – вдруг что-нибудь осталось.','Вернитесь к сержанту Горту к подъемнику лагеря Возмездия, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гори, Гибльхейм!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недостаточно просто убить Снежескорнов – мы должны сжечь их дома! Э... и мосты тоже. Давай спалим весь город – на всякий случай!$B$BВот, возьми факел. Иди в Гибльхейм, на запад, и сожги его ДОТЛА! Это научит их бояться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Сержант Горт послал вас в Гибльхейм с факелом Горта, чтобы вы сожгли 1 снежескорнское здание, 1 снежескорнскую сторожевую башню, 1 снежескорнский мост и 1 снежескорнские казармы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Похоже, ты сжег почти все постройки. Осталось несколько зданий... но Горт доволен тем, что видит.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все сжег? Проверь еще раз – вдруг что-нибудь осталось.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Горту к подъемнику лагеря Возмездия, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11286,'Артефакты Стальных ворот','Я пришел сюда по другой причине – мой старый друг явился ко мне во сне и просил о помощи. Но когда я увидел эти штуковины, роющие огромную яму в земле, меня охватила ярость.$B$BНасколько я понимаю, эти так называемые дворфы выкапывают древние артефакты, которые могут пролить свет на наше прошлое.$B$BПожалуйста, спустись туда и принеси их мне. Надеюсь, ни один из дворфов не станет у тебя на пути.','Ведун Странник Туманов попросил вас принести 10 артефактов Стальных ворот. Когда вы соберете их все, вернитесь к ведуну в Стальные ворота.','Сколько артефактов ты нашел в Стальных Воротах?','Вернитесь к ведуну Страннику Туманов к Стальным воротам, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Артефакты Стальных ворот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пришел сюда по другой причине – мой старый друг явился ко мне во сне и просил о помощи. Но когда я увидел эти штуковины, роющие огромную яму в земле, меня охватила ярость.$B$BНасколько я понимаю, эти так называемые дворфы выкапывают древние артефакты, которые могут пролить свет на наше прошлое.$B$BПожалуйста, спустись туда и принеси их мне. Надеюсь, ни один из дворфов не станет у тебя на пути.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ведун Странник Туманов попросил вас принести 10 артефактов Стальных ворот. Когда вы соберете их все, вернитесь к ведуну в Стальные ворота.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько артефактов ты нашел в Стальных Воротах?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведуну Страннику Туманов к Стальным воротам, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (11287,'Найти ведуна Странника Туманов','$C, я беспокоюсь за своего сына, ведуна Странника Туманов. Земли эти жестоки и беспощадны, а от него давно не было никаких вестей.$B$BОн сказал, что видит сны про какого-то волка, после чего собрал маленькую группу выносливых гонцов и отправился на запад. Мне кажется, он упоминал некое место под названием Стальные ворота.$B$BНе $gмог:могла; бы ты отправиться на его поиски? Я должна убедиться, что с ним все в порядке.','Когда гьялербронские узники будут освобождены, врайкулы не смогут больше проводить свои мерзкие ритуалы.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти ведуна Странника Туманов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$C, я беспокоюсь за своего сына, ведуна Странника Туманов. Земли эти жестоки и беспощадны, а от него давно не было никаких вестей.$B$BОн сказал, что видит сны про какого-то волка, после чего собрал маленькую группу выносливых гонцов и отправился на запад. Мне кажется, он упоминал некое место под названием Стальные ворота.$B$BНе $gмог:могла; бы ты отправиться на его поиски? Я должна убедиться, что с ним все в порядке.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда гьялербронские узники будут освобождены, врайкулы не смогут больше проводить свои мерзкие ритуалы.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11288,'Сияние света','<Арес тяжело дышит, пытаясь обратиться к вам.>$B$BЯ – посланник Серебряного Авангарда, исполняющий свой священный долг.$B$BНаши силы были уничтожены в Чумных землях. Сиянием рассвета артефакт был очищен и избавлен от скверны. Многие из нас сгинули ради возвращения этой святыни.$B$BНо надежда все еще жива... еще есть время.$B$BАртефакт был унесен в логово Павших, что вырыто глубоко под нами. Его охраняют безжалостные мертвецы.$B$B<Тело Ареса начинает светиться непереносимо ярким светом.>$B$BСвет... защитит... тебя...','Арес Поклявшийся, лежащий при смерти в Катакомбах Утгард, попросил вас вернуть священный артефакт.$B$BЭто задание ограничено по времени.','Вам кажется, что будет правильно положить священный клинок рядом с телом Ареса.$B$BКак только вы кладете меч, вас снова ослепляет яркий свет.','<Арес без сознания.>','Вернитесь к Аресу Поклявшемуся в Катакомбы Утгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сияние света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Арес тяжело дышит, пытаясь обратиться к вам.>$B$BЯ – посланник Серебряного Авангарда, исполняющий свой священный долг.$B$BНаши силы были уничтожены в Чумных землях. Сиянием рассвета артефакт был очищен и избавлен от скверны. Многие из нас сгинули ради возвращения этой святыни.$B$BНо надежда все еще жива... еще есть время.$B$BАртефакт был унесен в логово Павших, что вырыто глубоко под нами. Его охраняют безжалостные мертвецы.$B$B<Тело Ареса начинает светиться непереносимо ярким светом.>$B$BСвет... защитит... тебя...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Арес Поклявшийся, лежащий при смерти в Катакомбах Утгард, попросил вас вернуть священный артефакт.$B$BЭто задание ограничено по времени.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вам кажется, что будет правильно положить священный клинок рядом с телом Ареса.$B$BКак только вы кладете меч, вас снова ослепляет яркий свет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Арес без сознания.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Аресу Поклявшемуся в Катакомбы Утгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11289,'Ведомый честью','<Арес улыбается.>$B$BСлава Свету. Ты $gуспел:успела;! $B$B<Арес кашляет.>$B$BВозьми этот артефакт и отнеси его в Валгард. Лорд Ирулон Верный Клинок ожидает его возвращения.$B$BСражайся с честью, друг мой. Всегда. Честь превыше всего.$B$B<Арес умирает.>','Верните священный артефакт лорду Ирулону Верный Клинок в Валгард.','Во имя Света!','Вернитесь к лорду Ирулону Верному Клинку в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ведомый честью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Арес улыбается.>$B$BСлава Свету. Ты $gуспел:успела;! $B$B<Арес кашляет.>$B$BВозьми этот артефакт и отнеси его в Валгард. Лорд Ирулон Верный Клинок ожидает его возвращения.$B$BСражайся с честью, друг мой. Всегда. Честь превыше всего.$B$B<Арес умирает.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните священный артефакт лорду Ирулону Верный Клинок в Валгард.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Во имя Света!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Ирулону Верному Клинку в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11290,'Военные планы клана Укротителей драконов','Хотя мы мало что знаем о местонахождении Ингвара, нам точно известно, что Янис обитает в пещере рядом с воргской ямой в Деревне Драконьего Черепа.$B$BРазведданные, полученные от спасенных солдат, подтверждают, что Янис охраняет военные планы клана Укротителей драконов.$B$BТы $gдолжен:должна; вернуться в Деревню Драконьего Черепа и забрать эти планы. Убивай всех врайкулов, которые встретятся тебе на пути, включая Яниса!','Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде поручил вам достать военные планы клана Укротителей драконов.','<Вице-адмирал Келлер бегло проглядывает планы.>$B$BНевероятно! Судя по всему, в фьорде есть несколько поселений врайкулов. Еще одно племя планирует нападение на Крепость Западной Стражи. О боги, возможно, мы уже опоздали! Я уже несколько дней не получал известий из крепости. Как бы то ни было, мы должны их предупредить!','Военные планы у тебя?','Вернитесь к вице-адмиралу Келлеру в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Военные планы клана Укротителей драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя мы мало что знаем о местонахождении Ингвара, нам точно известно, что Янис обитает в пещере рядом с воргской ямой в Деревне Драконьего Черепа.$B$BРазведданные, полученные от спасенных солдат, подтверждают, что Янис охраняет военные планы клана Укротителей драконов.$B$BТы $gдолжен:должна; вернуться в Деревню Драконьего Черепа и забрать эти планы. Убивай всех врайкулов, которые встретятся тебе на пути, включая Яниса!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде поручил вам достать военные планы клана Укротителей драконов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Вице-адмирал Келлер бегло проглядывает планы.>$B$BНевероятно! Судя по всему, в фьорде есть несколько поселений врайкулов. Еще одно племя планирует нападение на Крепость Западной Стражи. О боги, возможно, мы уже опоздали! Я уже несколько дней не получал известий из крепости. Как бы то ни было, мы должны их предупредить!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Военные планы у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вице-адмиралу Келлеру в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11291,'В Крепость Западной Стражи!','<Вице-адмирал Келлер сворачивает тактические планы.>$B$BС помощью этой информации мы укрепим оборону Валгарда. Отнеси эти военные планы в Крепость Западной Стражи, которая выстроена на западном обрыве фьорда. Поговори с помощницей распорядителя полетов, Эмиленой Зимний Ветер. Пусть она подыщет тебе грифона, знающего путь в Крепость.$B$BКак только прибудешь на место, найди капитана Адамса. Он командует крепостью и знает, что делать с этими планами.','Отнесите военные планы Укротителей драконов капитану Адамсу в Крепость Западной Стражи в Ревущем фьорде.','Валгард еще стоит на месте? Вот чудеса.$B$BСомневаюсь, что Келлер обошелся без твоей помощи.','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В Крепость Западной Стражи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Вице-адмирал Келлер сворачивает тактические планы.>$B$BС помощью этой информации мы укрепим оборону Валгарда. Отнеси эти военные планы в Крепость Западной Стражи, которая выстроена на западном обрыве фьорда. Поговори с помощницей распорядителя полетов, Эмиленой Зимний Ветер. Пусть она подыщет тебе грифона, знающего путь в Крепость.$B$BКак только прибудешь на место, найди капитана Адамса. Он командует крепостью и знает, что делать с этими планами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите военные планы Укротителей драконов капитану Адамсу в Крепость Западной Стражи в Ревущем фьорде.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Валгард еще стоит на месте? Вот чудеса.$B$BСомневаюсь, что Келлер обошелся без твоей помощи.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11292,'Слабое звено','Рад встрече, $n. Я пришел сюда с Седых холмов, чтобы вести дела с твоими союзниками. Мои люди раскинули огромный лагерь на севере, и я искренне рекомендую тебе заглянуть туда.$B$BКстати, по пути я расставил множество силков в лесах и на заснеженных полянах. Частенько в них попадаются зверьки, чей мех и мясо я обмениваю на всякие полезные товары.$B$BМогу предложить тебе долю от доходов, если ты согласишься время от времени приносить мою добычу. Только будь $gосторожен:осторожна; – мы здесь не единственные хищники.','Зверолов Джетан из крепости Вилдервар просит вас принести ему 8 пойманных зверьков.','<Зверолов Джетан осматривает пойманных зверьков.>$B$BЗа эту добычу я выручу хорошие деньги, но для торговли мне надо скопить побольше товара.','Вернитесь к зверолову Джетану в Крепость Вилдервар, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слабое звено',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рад встрече, $n. Я пришел сюда с Седых холмов, чтобы вести дела с твоими союзниками. Мои люди раскинули огромный лагерь на севере, и я искренне рекомендую тебе заглянуть туда.$B$BКстати, по пути я расставил множество силков в лесах и на заснеженных полянах. Частенько в них попадаются зверьки, чей мех и мясо я обмениваю на всякие полезные товары.$B$BМогу предложить тебе долю от доходов, если ты согласишься время от времени приносить мою добычу. Только будь $gосторожен:осторожна; – мы здесь не единственные хищники.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зверолов Джетан из крепости Вилдервар просит вас принести ему 8 пойманных зверьков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Зверолов Джетан осматривает пойманных зверьков.>$B$BЗа эту добычу я выручу хорошие деньги, но для торговли мне надо скопить побольше товара.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к зверолову Джетану в Крепость Вилдервар, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11293,'Пивоварня Ячменоваров ищет зазывалу!','Зазывайте посетителей на Хмельной фестиваль у флагов в Палатах Войны, в Зале Исследователей и в Палатах Магии.','Ты уже всем $gрассказал:рассказала; о Хмельном фестивале? И, что самое главное, о Ячменоварах?','Вернитесь к Бекану Ячменовару в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пивоварня Ячменоваров ищет зазывалу!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зазывайте посетителей на Хмельной фестиваль у флагов в Палатах Войны, в Зале Исследователей и в Палатах Магии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже всем $gрассказал:рассказала; о Хмельном фестивале? И, что самое главное, о Ячменоварах?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бекану Ячменовару в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11294,'Пивоварня Громоваров ищет зазывалу!','Зазывайте посетителей на Хмельной фестиваль у флагов в Палатах Войны, в Зале Исследователей и в Палатах Магии.','Ну как, все уже знают, что на Хмельной фестиваль прибыло семейство Громоваров?','Вернитесь к Дарану Громовару в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пивоварня Громоваров ищет зазывалу!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Зазывайте посетителей на Хмельной фестиваль у флагов в Палатах Войны, в Зале Исследователей и в Палатах Магии.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, все уже знают, что на Хмельной фестиваль прибыло семейство Громоваров?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дарану Громовару в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11295,'В наступление!','Мы практически ничего не знаем о врайкулах. За многие века они никак себя не проявляли, и потому не упомянуты в наших записях. Но стоило нам выступить против Артаса, как они появились на нашем пути. $B$BПринесенная тобой карта подтверждает, что мы сначала должны разделаться с ними, и только потом следовать вглубь материка. $B$BОдин из моих лучших сержантов, поганище по имени Горт, надзирает за баррикадой у подъемника, наверху. Окажи ему помощь в организации превентивного удара по Гибльхейму. Если врайкулы решат напасть на нас, то это произойдет именно там.','Поговорите с сержантом Гортом на баррикаде рядом с подъемником к западу от Лагеря Возмездия в Ревущем Фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В наступление!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы практически ничего не знаем о врайкулах. За многие века они никак себя не проявляли, и потому не упомянуты в наших записях. Но стоило нам выступить против Артаса, как они появились на нашем пути. $B$BПринесенная тобой карта подтверждает, что мы сначала должны разделаться с ними, и только потом следовать вглубь материка. $B$BОдин из моих лучших сержантов, поганище по имени Горт, надзирает за баррикадой у подъемника, наверху. Окажи ему помощь в организации превентивного удара по Гибльхейму. Если врайкулы решат напасть на нас, то это произойдет именно там.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с сержантом Гортом на баррикаде рядом с подъемником к западу от Лагеря Возмездия в Ревущем Фьорде.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11296,'Пленники терзающих вдов','Что-то беспокоит обитающих в этих краях существ – возможно, это живые мертвецы Плети.$B$BСопровождая ведуна, мы потеряли почти половину отряда из-за терзающих вдов – огромных и смертоносных пауков, населяющих Вырубки к северу отсюда.$B$BУвы, я не могу оставить оставшихся людей без защиты, но... ты ведь можешь узнать, что случилось с моими выносливыми гонцами? Возможно, терзающие вдовы не убили их, а только заключили в свои коконы.$B$BТы поможешь мне, $gнезнакомец:незнакомка;?','Ты совершил подвиг, |3-6($C). Я даже не представлял, что твой народ способен на такую жертвенность ради других.\n\nВ следующий раз я прислушаюсь к предостережениям старейшин и стану обходить Вырубки стороной. Чего и тебе советую.','Обрел ли ты покой в святилище? Смятение больше не беспокоит твою душу?','Вернитесь к выносливому гонцу Тученебу к Стальным воротам, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пленники терзающих вдов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Что-то беспокоит обитающих в этих краях существ – возможно, это живые мертвецы Плети.$B$BСопровождая ведуна, мы потеряли почти половину отряда из-за терзающих вдов – огромных и смертоносных пауков, населяющих Вырубки к северу отсюда.$B$BУвы, я не могу оставить оставшихся людей без защиты, но... ты ведь можешь узнать, что случилось с моими выносливыми гонцами? Возможно, терзающие вдовы не убили их, а только заключили в свои коконы.$B$BТы поможешь мне, $gнезнакомец:незнакомка;?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты совершил подвиг, |3-6($C). Я даже не представлял, что твой народ способен на такую жертвенность ради других.\n\nВ следующий раз я прислушаюсь к предостережениям старейшин и стану обходить Вырубки стороной. Чего и тебе советую.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обрел ли ты покой в святилище? Смятение больше не беспокоит твою душу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к выносливому гонцу Тученебу к Стальным воротам, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11297,'Слежка за нарушителями границ','Даже сама земля не в силах сдержать натиск смерти. Бродят по ней мертвецы, распространяя скверну с ужасающей скоростью. $B$BОдному небольшому исследовательскому отряду нежити удалось подняться по западным склонам и разбить лагерь возле Шепчущей теснины. Скажи мне, $n, сможешь ли ты понять их стремление и убедить их не отравлять наши земли? Отправляйся на юго-запад от заставы и следуй к обрывам, нависающим над западным побережьем. Ты найдешь их лагерь к западу от раскопок у Стальных ворот.','Поговорите с аптекарем Малтусом в Аптекарском поселке.','Обрел ли ты покой в святилище? Смятение больше не беспокоит твою душу?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слежка за нарушителями границ',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Даже сама земля не в силах сдержать натиск смерти. Бродят по ней мертвецы, распространяя скверну с ужасающей скоростью. $B$BОдному небольшому исследовательскому отряду нежити удалось подняться по западным склонам и разбить лагерь возле Шепчущей теснины. Скажи мне, $n, сможешь ли ты понять их стремление и убедить их не отравлять наши земли? Отправляйся на юго-запад от заставы и следуй к обрывам, нависающим над западным побережьем. Ты найдешь их лагерь к западу от раскопок у Стальных ворот.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с аптекарем Малтусом в Аптекарском поселке.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Обрел ли ты покой в святилище? Смятение больше не беспокоит твою душу?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11298,'Что они пьют?','К юго-востоку отсюда пролегает Шепчущая теснина. Ее захватили обезумевшие члены Лиги исследователей! Они напали на наш караван, который следовал через их территорию, и ограбили продовольственный отряд.$B$BЯ должен понять, что свело их с ума! Может быть, всему виной то варево в бочках, которые расставлены по всей теснине? Слушай, прикати мне несколько бочонков, пока эти дворфы будут заняты раскопками.','Аптекарь Малтус из Аптекарского поселка просит вас принести ему 5 дворфийских бочонков.','Так ты несешь мне бочки или нет?','Вернитесь к аптекарю Малтусу в Аптекарский поселок, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что они пьют?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К юго-востоку отсюда пролегает Шепчущая теснина. Ее захватили обезумевшие члены Лиги исследователей! Они напали на наш караван, который следовал через их территорию, и ограбили продовольственный отряд.$B$BЯ должен понять, что свело их с ума! Может быть, всему виной то варево в бочках, которые расставлены по всей теснине? Слушай, прикати мне несколько бочонков, пока эти дворфы будут заняты раскопками.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аптекарь Малтус из Аптекарского поселка просит вас принести ему 5 дворфийских бочонков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так ты несешь мне бочки или нет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Малтусу в Аптекарский поселок, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`) VALUES (11299,'Возможно, ты уже $gвидел:видела; комнату, в которой держат Дегарна – она находится рядом с тем коридором, где ты $gискал:искала; таблички. Спустись по ступенькам, и ты найдешь его в запертой камере у подножия лестницы. $B$BОтправляйся туда и отыщи его. Возможно, он хотя бы сможет сообщить тебе шифр.','Найдите Дегарна в Круге Правосудия. Он заперт в Катакомбах Утгард.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, ты уже $gвидел:видела; комнату, в которой держат Дегарна – она находится рядом с тем коридором, где ты $gискал:искала; таблички. Спустись по ступенькам, и ты найдешь его в запертой камере у подножия лестницы. $B$BОтправляйся туда и отыщи его. Возможно, он хотя бы сможет сообщить тебе шифр.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Дегарна в Круге Правосудия. Он заперт в Катакомбах Утгард.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11300,'Поражение на ринге','До Олуфа можно добраться только одним способом – перебить всех остальных гладиаторов. Иначе нам никогда не вернуть тайнопись. Так что не медли – ступай в Круг Правосудия. Если тебе удастся получить тайнопись, принеси ее Глоренфелду ко входу в эти катакомбы. $B$BА что я? Ты обо мне не беспокойся! Самое главное – найти связующее звено, которое откроет тайну происхождения всего человечества!','Победите гладиаторов в Круге Правосудия, сразитесь с Олуфом Неистовым и заберите у него древнюю тайнопись.$B$BОтнесите тайнопись Глоренфелду ко входу в Катакомбы Утгард.','Какое потрясающее приключение! Так значит, кто-то действительно вершит суд над этими несчастными созданиями? Но для чего?$B$BА, не обращай на меня внимания. Пусть с этим разбирается кто-нибудь другой. Главное, мы получили тайнопись и таблички – и потеряли всего двоих людей на этом пути.','Где Дегарн? А тайнопись?','Вернитесь к Глоренфелду в Катакомбы Утгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поражение на ринге',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','До Олуфа можно добраться только одним способом – перебить всех остальных гладиаторов. Иначе нам никогда не вернуть тайнопись. Так что не медли – ступай в Круг Правосудия. Если тебе удастся получить тайнопись, принеси ее Глоренфелду ко входу в эти катакомбы. $B$BА что я? Ты обо мне не беспокойся! Самое главное – найти связующее звено, которое откроет тайну происхождения всего человечества!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите гладиаторов в Круге Правосудия, сразитесь с Олуфом Неистовым и заберите у него древнюю тайнопись.$B$BОтнесите тайнопись Глоренфелду ко входу в Катакомбы Утгард.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какое потрясающее приключение! Так значит, кто-то действительно вершит суд над этими несчастными созданиями? Но для чего?$B$BА, не обращай на меня внимания. Пусть с этим разбирается кто-нибудь другой. Главное, мы получили тайнопись и таблички – и потеряли всего двоих людей на этом пути.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где Дегарн? А тайнопись?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глоренфелду в Катакомбы Утгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11301,'Мозги! Мозги!','Аптекарь Грик из Аптекарского поселка просит вас принести ему 12 мозгов спятивших исследователей.','Ты принес мне мозги? Нет? Тогда отдай пилу. Лучше тебе не разгуливать здесь с этой штукой.','Вернитесь к аптекарю Грику в Аптекарский поселок, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мозги! Мозги!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аптекарь Грик из Аптекарского поселка просит вас принести ему 12 мозгов спятивших исследователей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес мне мозги? Нет? Тогда отдай пилу. Лучше тебе не разгуливать здесь с этой штукой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Грику в Аптекарский поселок, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11302,'Загадочные ледяные нимфы','Впервые осматривая окрестности форта, мы заметили враждебно настроенных существ на двух полянах к северу отсюда. Когда мы проходили мимо заснеженной прогалины к югу от города, дриады с интересом наблюдали за нами, но не нападали. $B$BМестный климат порядком измотал моих людей, и они могли с легкостью уничтожить половину нашего отряда, но не стали. $B$BВозможно, эти дриады хотят стать нашими союзниками. Не желаешь ли ты отправиться на Заиндевевшую поляну и попытаться установить с ними контакт?','Поговорите с Луриэль на Заиндевевшей поляне.','<Луриэль внимательно слушает вас.>$B$BЯ рада наконец-то познакомиться с тобой, $N. Мы надеялись, что кто-нибудь из новоприбывших пришлет к нам своих представителей. Сами мы редко выходим за границы наших полян, особенно после того, как окружающий нас мир претерпел изменения.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загадочные ледяные нимфы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Впервые осматривая окрестности форта, мы заметили враждебно настроенных существ на двух полянах к северу отсюда. Когда мы проходили мимо заснеженной прогалины к югу от города, дриады с интересом наблюдали за нами, но не нападали. $B$BМестный климат порядком измотал моих людей, и они могли с легкостью уничтожить половину нашего отряда, но не стали. $B$BВозможно, эти дриады хотят стать нашими союзниками. Не желаешь ли ты отправиться на Заиндевевшую поляну и попытаться установить с ними контакт?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Луриэль на Заиндевевшей поляне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Луриэль внимательно слушает вас.>$B$BЯ рада наконец-то познакомиться с тобой, $N. Мы надеялись, что кто-нибудь из новоприбывших пришлет к нам своих представителей. Сами мы редко выходим за границы наших полян, особенно после того, как окружающий нас мир претерпел изменения.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11303,'Засада','Врайкулы в Гибльхейме повержены – в этом нет никаких сомнений. Но их предводители остались в городе и не собираются сдаваться.$B$BГорт послал Лиделла и его головорезов помахать кулаками на северо-западе. Иди, поговори с ним и выясни, как выманить врайкульского вождя и убить его. Смотри только, чтобы он помучился перед смертью!','Поговорите с Лиделлом в Засаде Лиделла.','Вечеринка в разгаре, но наш "почетный гость" предпочитает отсиживаться дома.','Все сжег? Проверь еще раз – вдруг что-нибудь осталось.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Врайкулы в Гибльхейме повержены – в этом нет никаких сомнений. Но их предводители остались в городе и не собираются сдаваться.$B$BГорт послал Лиделла и его головорезов помахать кулаками на северо-западе. Иди, поговори с ним и выясни, как выманить врайкульского вождя и убить его. Смотри только, чтобы он помучился перед смертью!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Лиделлом в Засаде Лиделла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вечеринка в разгаре, но наш "почетный гость" предпочитает отсиживаться дома.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все сжег? Проверь еще раз – вдруг что-нибудь осталось.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11304,'Новый Агамонд','Боюсь, что Лагерь Возмездия недостаточно хорошо оборудован. В конце концов, это всего лишь военная база.$B$BПожалуйста, отнеси этот штамм главному распространителю чумы Харрису в Новый Агамонд. Чтобы найти город, иди по южной дороге мимо Гибльхейма, а потом поверни на запад. Он располагает более совершенным оборудованием, и знает, что делать с этим штаммом. $B$BПоторопись, $n. Наши враги превосходят нас силой и числом. Нам надо создать оружие, с помощью которого мы одержим победу!','Отнесите штамм Лисандера главному распространителю чумы Харрису в Новый Агамонд на запад Ревущего фьорда.','Друг мой, это вполне эффективный штамм! Эти идиоты из Лагеря Возмездия чуть не проморгали все на свете!','Вернитесь к главному распространителю чумы Харрису в Новый Агамонд, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новый Агамонд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, что Лагерь Возмездия недостаточно хорошо оборудован. В конце концов, это всего лишь военная база.$B$BПожалуйста, отнеси этот штамм главному распространителю чумы Харрису в Новый Агамонд. Чтобы найти город, иди по южной дороге мимо Гибльхейма, а потом поверни на запад. Он располагает более совершенным оборудованием, и знает, что делать с этим штаммом. $B$BПоторопись, $n. Наши враги превосходят нас силой и числом. Нам надо создать оружие, с помощью которого мы одержим победу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите штамм Лисандера главному распространителю чумы Харрису в Новый Агамонд на запад Ревущего фьорда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Друг мой, это вполне эффективный штамм! Эти идиоты из Лагеря Возмездия чуть не проморгали все на свете!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному распространителю чумы Харрису в Новый Агамонд, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11305,'Идеальная формула','Мы уже несколько недель распространяем чуму в деревне врайкулов, Халгринде, а эти макаки по-прежнему живее всех живых! $B$BСкажу прямо, $n: на настоящий момент мы испытали штамм на людях, дворфах, собаках, домашнем скоте... на ком угодно. Но когда вирус приспосабливается к организму носителя, он изменяется и становится менее стабильным. Поэтому нам надо разработать штамм, идеально подходящий для организма врайкулов.$B$BНезадолго до того, как мы захватили Халгринд, из деревни бежал врайкульский вождь и укрылся к западу отсюда. А что может быть чище крови предводителя клана Укротителей драконов?','Добудьте кровь патриарха Укротителей драконов – вождя Торвальда, который укрылся в Лагере Торвальда, и принесите ее главному распространителю чумы Харрису в Новый Агамонд.','Вернитесь к главному распространителю чумы Харрису в Новый Агамонд, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Идеальная формула',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы уже несколько недель распространяем чуму в деревне врайкулов, Халгринде, а эти макаки по-прежнему живее всех живых! $B$BСкажу прямо, $n: на настоящий момент мы испытали штамм на людях, дворфах, собаках, домашнем скоте... на ком угодно. Но когда вирус приспосабливается к организму носителя, он изменяется и становится менее стабильным. Поэтому нам надо разработать штамм, идеально подходящий для организма врайкулов.$B$BНезадолго до того, как мы захватили Халгринд, из деревни бежал врайкульский вождь и укрылся к западу отсюда. А что может быть чище крови предводителя клана Укротителей драконов?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте кровь патриарха Укротителей драконов – вождя Торвальда, который укрылся в Лагере Торвальда, и принесите ее главному распространителю чумы Харрису в Новый Агамонд.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному распространителю чумы Харрису в Новый Агамонд, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11306,'Нагреть и перемешать','$n, ты уже многого $gдостиг:достигла; на нашем поприще. Теперь я хочу обучить тебя некоторым более сложным способам изготовления чумы.$B$BВозьми эту флягу и наполни ее кровью из котла слева от меня. Смешивай ее с образцами чумы, которые лежат справа, пока не получишь однородную смесь.','Наполните пустой аптекарский флакон кровью из котла с кровью врайкулов, после чего добавляйте во флакон с кровью врайкула образцы чумы Харисса, пока не получите равномерную смесь. $B$BКогда вы выполните это поручение, вернитесь к Главному распространителю чумы Харрису.','Вернитесь к главному распространителю чумы Харрису в Новый Агамонд, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нагреть и перемешать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты уже многого $gдостиг:достигла; на нашем поприще. Теперь я хочу обучить тебя некоторым более сложным способам изготовления чумы.$B$BВозьми эту флягу и наполни ее кровью из котла слева от меня. Смешивай ее с образцами чумы, которые лежат справа, пока не получишь однородную смесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните пустой аптекарский флакон кровью из котла с кровью врайкулов, после чего добавляйте во флакон с кровью врайкула образцы чумы Харисса, пока не получите равномерную смесь. $B$BКогда вы выполните это поручение, вернитесь к Главному распространителю чумы Харрису.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному распространителю чумы Харрису в Новый Агамонд, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11307,'Полевые испытания','Теперь, когда мы получили штамм чумы, адаптировавшийся к нашим врайкулам-переносчикам, настало время испытать его на подопытных особях в Халгринде. Если все пойдет по плану, они распадутся на части через секунду после того, как чума проникнет в их организм!$B$BХалгринд находится к северу отсюда. Ты найдешь его с легкостью – наши распространители чумы уже там поработали.','Отправляйтесь в Халгринд и заразите ассимилированным штаммом чумы 10 зачумленных врайкулов из клана Укротителей драконов, после чего вернитесь к главному распространителю чумы Харрису.','Ну, говори же! Чем завершился наш эксперимент?\n\nПротодракону понравилась закуска, которая расплавила его изнутри?','Вернитесь к главному распространителю чумы Харрису в Новый Агамонд, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полевые испытания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы получили штамм чумы, адаптировавшийся к нашим врайкулам-переносчикам, настало время испытать его на подопытных особях в Халгринде. Если все пойдет по плану, они распадутся на части через секунду после того, как чума проникнет в их организм!$B$BХалгринд находится к северу отсюда. Ты найдешь его с легкостью – наши распространители чумы уже там поработали.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Халгринд и заразите ассимилированным штаммом чумы 10 зачумленных врайкулов из клана Укротителей драконов, после чего вернитесь к главному распространителю чумы Харрису.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, говори же! Чем завершился наш эксперимент?\n\nПротодракону понравилась закуска, которая расплавила его изнутри?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному распространителю чумы Харрису в Новый Агамонд, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11308,'Пора заметать следы','Будучи человеком практичным, я могу заявить, что мы достигли успеха в наших исследованиях. В конце концов, любую армию можно остановить, если натравить ее рядовых солдат друг на друга.$B$BСкоро я доложу о наших успехах в Лагерь Возмездия. Но сначала мы должны замести следы.$B$BПопроси Дженни по прозвищу "Пила" сделать тебе базовое поганище. Пусть только она добавит в него побольше взрывчатки – если ты понимаешь, к чему я клоню.','Поговорите с Дженни по прозвищу "Пила" в Новом Агамонде.','Что тебе нужно? Не видишь – я очень занята!','Ну, говори же! Чем завершился наш эксперимент?\n\nПротодракону понравилась закуска, которая расплавила его изнутри?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пора заметать следы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Будучи человеком практичным, я могу заявить, что мы достигли успеха в наших исследованиях. В конце концов, любую армию можно остановить, если натравить ее рядовых солдат друг на друга.$B$BСкоро я доложу о наших успехах в Лагерь Возмездия. Но сначала мы должны замести следы.$B$BПопроси Дженни по прозвищу "Пила" сделать тебе базовое поганище. Пусть только она добавит в него побольше взрывчатки – если ты понимаешь, к чему я клоню.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Дженни по прозвищу "Пила" в Новом Агамонде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что тебе нужно? Не видишь – я очень занята!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, говори же! Чем завершился наш эксперимент?\n\nПротодракону понравилась закуска, которая расплавила его изнутри?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11309,'Запчасти для Дженни','Да, это вполне сгодится. Молодец!','Ты достал то, что я просила?','Вернитесь к Дженни по прозвищу "Пила" в Новый Агамонд, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запчасти для Дженни',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это вполне сгодится. Молодец!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал то, что я просила?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дженни по прозвищу "Пила" в Новый Агамонд, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11310,'Внимание: требуется сборка','А, вот ты где! Наш дружок получился немного... непредсказуемым. Я бы тебе порекомендовала собрать его на месте, в Халгринде.$B$BКак только доберешься туда, отправь поганище в толпу врайкулов, чтобы он уничтожил как можно больше этих тварей.$B$BКогда все закончится, подбери останки и принеси их сюда. Запчасти мне всегда пригодятся!','Воспользуйтесь набором для сборки поганища в Халгринде и сгоните в одно место как минимум 20 зачумленных врайкулов. Взорвите их с помощью поганища, после чего вернитесь к Дженни по прозвищу "Пила" в Новый Агамонд.','Ну что, зачистка в Халгринде закончена?','Вернитесь к Дженни по прозвищу "Пила" в Новый Агамонд, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Внимание: требуется сборка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, вот ты где! Наш дружок получился немного... непредсказуемым. Я бы тебе порекомендовала собрать его на месте, в Халгринде.$B$BКак только доберешься туда, отправь поганище в толпу врайкулов, чтобы он уничтожил как можно больше этих тварей.$B$BКогда все закончится, подбери останки и принеси их сюда. Запчасти мне всегда пригодятся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь набором для сборки поганища в Халгринде и сгоните в одно место как минимум 20 зачумленных врайкулов. Взорвите их с помощью поганища, после чего вернитесь к Дженни по прозвищу "Пила" в Новый Агамонд.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, зачистка в Халгринде закончена?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дженни по прозвищу "Пила" в Новый Агамонд, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11311,'Сопротивляясь стихиям','Если хочешь выжить в этом месте – научись приспосабливаться к изменениям, как это сделали мы. Количество элементалей в северных предгорьях неуклонно возрастает, что только подтверждает тот факт, что любая стихия может стать смертоносной, если мы не будем достаточно бдительны, чтобы предотвратить угрозу.$B$BПеред тем как покинуть это место, мы должны в последний раз сократить численность элементалей. Не хочешь ли ты помочь нам, пока мы завершаем подготовку к походу?$B$BУбивай всех осколочных ледяных элементалей и завывающих циклонов, которые встретятся тебе на снежных предгорьях, окружающих аванпост.','Влияние стихий уменьшилось, но элементали еще вернутся. К счастью, мы успели выиграть время для приготовлений к уходу.','Ты нашел пух гиппогрифов?','Вернитесь к укротителю ветра Кагану в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сопротивляясь стихиям',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хочешь выжить в этом месте – научись приспосабливаться к изменениям, как это сделали мы. Количество элементалей в северных предгорьях неуклонно возрастает, что только подтверждает тот факт, что любая стихия может стать смертоносной, если мы не будем достаточно бдительны, чтобы предотвратить угрозу.$B$BПеред тем как покинуть это место, мы должны в последний раз сократить численность элементалей. Не хочешь ли ты помочь нам, пока мы завершаем подготовку к походу?$B$BУбивай всех осколочных ледяных элементалей и завывающих циклонов, которые встретятся тебе на снежных предгорьях, окружающих аванпост.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Влияние стихий уменьшилось, но элементали еще вернутся. К счастью, мы успели выиграть время для приготовлений к уходу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел пух гиппогрифов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю ветра Кагану в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11312,'Заиндевевшая поляна','Многие поколения среди нашего народа ходили легенды о ледяных нимфах, прячущихся далеко в заснеженных чащах. Как-то ребенком я отправилась на их поиски вопреки запретам родителей, а в итоге едва не замерзла до смерти.$B$BИ вот настали дни, когда нам больше не надо прочесывать леса в поисках этих чудесных созданий. По неведомым причинам они решили открыться нам, и мы обязаны узнать, чем вызвано их появление. Отправляйся на юго-восток, к заиндевевшей поляне, и поговори с ледяными нимфами. Но будь $gосторожен:осторожна; – по пути тебе придется миновать Холмистую поляну.','Поговорите с Луриэль на Заиндевевшей поляне.','<Луриэль внимательно выслушивает вас.>\n\nПриятно познакомиться, $C. Мои сестры часто видели, как таунка искали нас в лесах, но наша королева запретила нам вступать в контакт с чужаками. Сегодня ты видишь нас только потому, что эти земли сильно изменились, и многие мои сестры ныне в опасности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заиндевевшая поляна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многие поколения среди нашего народа ходили легенды о ледяных нимфах, прячущихся далеко в заснеженных чащах. Как-то ребенком я отправилась на их поиски вопреки запретам родителей, а в итоге едва не замерзла до смерти.$B$BИ вот настали дни, когда нам больше не надо прочесывать леса в поисках этих чудесных созданий. По неведомым причинам они решили открыться нам, и мы обязаны узнать, чем вызвано их появление. Отправляйся на юго-восток, к заиндевевшей поляне, и поговори с ледяными нимфами. Но будь $gосторожен:осторожна; – по пути тебе придется миновать Холмистую поляну.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Луриэль на Заиндевевшей поляне.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Луриэль внимательно выслушивает вас.>\n\nПриятно познакомиться, $C. Мои сестры часто видели, как таунка искали нас в лесах, но наша королева запретила нам вступать в контакт с чужаками. Сегодня ты видишь нас только потому, что эти земли сильно изменились, и многие мои сестры ныне в опасности.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11313,'Духи льда','Ледяные элементали, охраняющие эту поляну, были нашими союзниками, но некая жестокая и разрушительная сила пронеслась по этим землям, изменяя их сущность. Теперь они обратились против нас!$B$BЭта одна из многих бед постигнувших меня и моих сестер. Мы явились к вам в надежде, что вы сможете помочь нам остановить скверну, проникшую в наши леса и отравляющую моих сестер!$B$BМы собираем ядра ледяных элементалей и складываем в безопасное место в надежде, что когда-нибудь сможем их возродить. Ты нам поможешь?','Луриэль с Заиндевевшей поляны просит вас принести ей 15 ледяных ядер.','Ты принес хоть несколько ядер?','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи льда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ледяные элементали, охраняющие эту поляну, были нашими союзниками, но некая жестокая и разрушительная сила пронеслась по этим землям, изменяя их сущность. Теперь они обратились против нас!$B$BЭта одна из многих бед постигнувших меня и моих сестер. Мы явились к вам в надежде, что вы сможете помочь нам остановить скверну, проникшую в наши леса и отравляющую моих сестер!$B$BМы собираем ядра ледяных элементалей и складываем в безопасное место в надежде, что когда-нибудь сможем их возродить. Ты нам поможешь?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Луриэль с Заиндевевшей поляны просит вас принести ей 15 ледяных ядер.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес хоть несколько ядер?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11314,'Падшие сестры','К юго-западу отсюда есть поляна, которая некогда была очень похожа на эту. Но странные силы и чужеродная магия изменили эту землю. Поляна исказилась, а жившие на ней сестры сошли с ума, ибо были не в состоянии принять произошедшие перемены.$B$BМы пытались воззвать к ним, но они напали на моих подручных. Боюсь, многих из моих несчастных сестер уже не спасти, но я не теряю надежды.$B$BВозьми мою подвеску, отправляйся на юго-запад, к Светлой поляне, и попытайся с ее помощью освободить моих сестер.','Луриэль с Заиндевевшей поляны попросила вас воспользоваться ее подвеской, чтобы освободить 7 морозных нимф.','Ты уже побывал на Светлой поляне?','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Падшие сестры',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К юго-западу отсюда есть поляна, которая некогда была очень похожа на эту. Но странные силы и чужеродная магия изменили эту землю. Поляна исказилась, а жившие на ней сестры сошли с ума, ибо были не в состоянии принять произошедшие перемены.$B$BМы пытались воззвать к ним, но они напали на моих подручных. Боюсь, многих из моих несчастных сестер уже не спасти, но я не теряю надежды.$B$BВозьми мою подвеску, отправляйся на юго-запад, к Светлой поляне, и попытайся с ее помощью освободить моих сестер.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Луриэль с Заиндевевшей поляны попросила вас воспользоваться ее подвеской, чтобы освободить 7 морозных нимф.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже побывал на Светлой поляне?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11315,'Дикие ветви','Сестры, жившие на Светлой поляне, что к юго-западу отсюда, любили проводить время в тени алого плюща, но та же сила, что свела их с ума, изменила и их возлюбленные цветы.$B$BОтныне ветви некогда мирных цветов хватают за ноги неосторожных путников и хлещут по лицу каждого, кто осмелится приблизиться к поляне. Если мы хотим исцелить эти земли, мы должны сначала усмирить и выкорчевать эти растения.$B$BУничтожь столько цветков алого плюща, сколько сможешь. Увы, у нас больше нет над ними власти.','Луриэль с Заиндевевшей поляны попросила вас уничтожить 8 цветков алого плюща.','Ты уже побывал на Светлой поляне?','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дикие ветви',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сестры, жившие на Светлой поляне, что к юго-западу отсюда, любили проводить время в тени алого плюща, но та же сила, что свела их с ума, изменила и их возлюбленные цветы.$B$BОтныне ветви некогда мирных цветов хватают за ноги неосторожных путников и хлещут по лицу каждого, кто осмелится приблизиться к поляне. Если мы хотим исцелить эти земли, мы должны сначала усмирить и выкорчевать эти растения.$B$BУничтожь столько цветков алого плюща, сколько сможешь. Увы, у нас больше нет над ними власти.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Луриэль с Заиндевевшей поляны попросила вас уничтожить 8 цветков алого плюща.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже побывал на Светлой поляне?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11316,'Порождения Холмистой поляны','Некогда чудесная поляна на западе превратилась в ужасное место, которое прозвали Холмистой поляной. Там, среди деревьев, камней и озер бродят чудовищные звери.$B$BЯ не могу даже представить себе, откуда взялись эти существа и какая омерзительная магия вдохнула в них жизнь, но мы должны что-то сделать с этими тварями!$B$BБоюсь, что если мы и дальше позволим им бродить по поляне, они отравят землю настолько, что мы уже не сможем ее возродить. Очисти поляну от существ, погубивших наших сестер.','Луриэль с Заиндевевшей поляны просит вас убить 10 терноплющей.','Ты нашел пух гиппогрифов?','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Порождения Холмистой поляны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Некогда чудесная поляна на западе превратилась в ужасное место, которое прозвали Холмистой поляной. Там, среди деревьев, камней и озер бродят чудовищные звери.$B$BЯ не могу даже представить себе, откуда взялись эти существа и какая омерзительная магия вдохнула в них жизнь, но мы должны что-то сделать с этими тварями!$B$BБоюсь, что если мы и дальше позволим им бродить по поляне, они отравят землю настолько, что мы уже не сможем ее возродить. Очисти поляну от существ, погубивших наших сестер.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Луриэль с Заиндевевшей поляны просит вас убить 10 терноплющей.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел пух гиппогрифов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11317,'Очищение','Ведун Странник Туманов у Стальных ворот посоветовал вам очиститься от внутреннего смятения путем медитации в святилище Ледяного Клинка.','Вернитесь к ведуну Страннику Туманов к Стальным воротам, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ведун Странник Туманов у Стальных ворот посоветовал вам очиститься от внутреннего смятения путем медитации в святилище Ледяного Клинка.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведуну Страннику Туманов к Стальным воротам, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11318,'А теперь гонки на баранах... Или вроде того.','У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.','Ну как, $gнаучился:научилась; переключать скорости?','Вернитесь к Нейлу Рамштайну в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','А теперь гонки на баранах... Или вроде того.',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, $gнаучился:научилась; переключать скорости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Нейлу Рамштайну в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11319,'Семена негодующих хранителей','Раньше на Холмистой поляне, к западу отсюда, обитали хранители рощи. Вместе с сестрами они ухаживали за ее обитателями.$B$BКогда поляна изменилась, все сестры погибли, но хранителям каким-то образом удалось выжить. Однако теперь они засеивают землю ядовитыми растениями, которые губят здоровые ростки.$B$BПриближаться к этим спорам опасно, но я дам тебе ядро одного из ледяных элементалей. Как только уничтожишь спору, заморозь ее с помощью кристалла, чтобы она больше не ожила.','Луриэль с Заиндевевшей поляны поручила вам заморозить 8 спор.','Ледяное ядро сработало? Хорошо. Боюсь, мне еще не раз придется его применить. Я уверена, что хранители не остановятся и будут продолжать засеивать поляну.','Ты нашел пух гиппогрифов?','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Семена негодующих хранителей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Раньше на Холмистой поляне, к западу отсюда, обитали хранители рощи. Вместе с сестрами они ухаживали за ее обитателями.$B$BКогда поляна изменилась, все сестры погибли, но хранителям каким-то образом удалось выжить. Однако теперь они засеивают землю ядовитыми растениями, которые губят здоровые ростки.$B$BПриближаться к этим спорам опасно, но я дам тебе ядро одного из ледяных элементалей. Как только уничтожишь спору, заморозь ее с помощью кристалла, чтобы она больше не ожила.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Луриэль с Заиндевевшей поляны поручила вам заморозить 8 спор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ледяное ядро сработало? Хорошо. Боюсь, мне еще не раз придется его применить. Я уверена, что хранители не остановятся и будут продолжать засеивать поляну.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты нашел пух гиппогрифов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11320,'[NYI] А теперь гонки на баранах... Или вроде того.','Описание задания','Краткая формулировка','Вернитесь к Дарану Громовару в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[NYI] А теперь гонки на баранах... Или вроде того.',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Описание задания',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Краткая формулировка',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дарану Громовару в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11321,'Кто сказал "сувениры"?','Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.$b$bВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.','Отоварьте свой купон на праздничную кружку у Белби Быстросмен в лагере Хмельного фестиваля.','Ой, это всего лишь ваучер на кружку... Может, ты просто играешь, чтобы их получить. Итак, вот тебе кружка этого года.$B$BНо я подозреваю, что увижу тебя гораздо раньше. В конце концов, если ты хочешь выкупить какие-либо жетоны Хмельного фестиваля, я твоя девушка...$B$BА может я его девушка...$B$BОоооо... или его...','Что происходит? Есть что-нибудь для меня?','Вернитесь к Белби Быстросмен в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто сказал "сувениры"?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Главное на Хмельном фестивале – не гонки на баранах, а выпивка! Улучи минутку и отдай свой купон Белби Быстросмен. Она стоит за поляной, на которой проходит Хмельной фестиваль. Если ты ее не увидишь, не беспокойся, она-то тебя всяко заметит.$b$bВ общем, отдай ей свой купон, и получишь бесплатную праздничную кружку. Кроме того, именно Белби занимается прочей праздничной торговлей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отоварьте свой купон на праздничную кружку у Белби Быстросмен в лагере Хмельного фестиваля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ой, это всего лишь ваучер на кружку... Может, ты просто играешь, чтобы их получить. Итак, вот тебе кружка этого года.$B$BНо я подозреваю, что увижу тебя гораздо раньше. В конце концов, если ты хочешь выкупить какие-либо жетоны Хмельного фестиваля, я твоя девушка...$B$BА может я его девушка...$B$BОоооо... или его...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что происходит? Есть что-нибудь для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Белби Быстросмен в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11322,'Очищение','Недавно мне приснился кошмарный сон про ворга по имени Улклык. Он звал меня на помощь! $n, ты $gдолжен:должна; его найти.$B$BК сожалению, ты не можешь ходить среди воргов и общаться с ними, но я могу тебя научить.$B$BСначала тебе придется изгнать свое внутреннее смятение путем медитации. $B$BДалеко на северо-востоке, на Вершине Ледяного Клинка есть святилище. К нему ведет единственная тропинка, начинающаяся от западного подножия горы.$B$BОтправляйся туда на медитацию, очисти свой дух и возвращайся ко мне.','Дозорная Лунный Лепесток у Стальных ворот посоветовала вам очиститься от внутреннего смятения путем медитации в святилище Ледяного Клинка.','Я чувствую произошедшие в тебе перемены.$B$B$GГотов:Готова; ли ты сделать следующий шаг?','Вы нашли душевный покой в ​​святыне? Ваша суматоха ушла?','Вернитесь к дозорной Лунный Лепесток к Стальным воротам, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно мне приснился кошмарный сон про ворга по имени Улклык. Он звал меня на помощь! $n, ты $gдолжен:должна; его найти.$B$BК сожалению, ты не можешь ходить среди воргов и общаться с ними, но я могу тебя научить.$B$BСначала тебе придется изгнать свое внутреннее смятение путем медитации. $B$BДалеко на северо-востоке, на Вершине Ледяного Клинка есть святилище. К нему ведет единственная тропинка, начинающаяся от западного подножия горы.$B$BОтправляйся туда на медитацию, очисти свой дух и возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дозорная Лунный Лепесток у Стальных ворот посоветовала вам очиститься от внутреннего смятения путем медитации в святилище Ледяного Клинка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я чувствую произошедшие в тебе перемены.$B$B$GГотов:Готова; ли ты сделать следующий шаг?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы нашли душевный покой в ​​святыне? Ваша суматоха ушла?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорной Лунный Лепесток к Стальным воротам, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11323,'В обличье ворга','Во сне я видел Улклыка в пещере на заснеженном краю Вырубок, где-то на северо-западе.$B$BЕму грозит страшная опасность!$B$BЯ сделал магическую личину, которая сделает тебя $gпохожим:похожей; на ворга. Это очень нестабильная личина, которая действует только в пределах Вырубок. Однако с ее помощью ты сможешь обмануть воргов и добраться до Улклыка.$B$BПрошу тебя, |3-6($c), отыщи Улклыка и помоги ему.','Ведун Странник Туманов попросил вас найти Улклыка в Вырубках и помочь ему.$B$BЕсли вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.','Ты как-то странно выглядишь, и запах у тебя необычный... ты не из моей стаи. Расскажи, что привело тебя сюда. Все равно мне больше нечем заняться, пока я заперт в этом месте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В обличье ворга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во сне я видел Улклыка в пещере на заснеженном краю Вырубок, где-то на северо-западе.$B$BЕму грозит страшная опасность!$B$BЯ сделал магическую личину, которая сделает тебя $gпохожим:похожей; на ворга. Это очень нестабильная личина, которая действует только в пределах Вырубок. Однако с ее помощью ты сможешь обмануть воргов и добраться до Улклыка.$B$BПрошу тебя, |3-6($c), отыщи Улклыка и помоги ему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ведун Странник Туманов попросил вас найти Улклыка в Вырубках и помочь ему.$B$BЕсли вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты как-то странно выглядишь, и запах у тебя необычный... ты не из моей стаи. Расскажи, что привело тебя сюда. Все равно мне больше нечем заняться, пока я заперт в этом месте.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11324,'Альфа-ворг','Теперь, когда ты $gсъел:съела; глаза Когтекрыла, ты сможешь увидеть Гарвала и вырвать его глотку!$B$BДитя |3-1($r), разыщи Гарвала в западных Вырубках и убей его. Когда он умрет, вернись к ведуну Страннику Туманов и сообщи ему, что я снова стал вожаком стаи воргов!','Улклык попросил вас убить Гарвала. После этого вы должны будете вернуть личину ворга ведуну Страннику Туманов в Стальные ворота.','Гарвал был не воргом! Судя по твоему рассказу, эта тварь больше похожа на воргена!\n\nНо Улклык вроде бы упоминал, что Гарвал явился с юга, из Седых холмов? Как странно. Воргены не водятся в тех местах...\n\nКак бы то ни было, я благодарю тебя за то, что ты помог Улклыку занять подобающее ему место в стае. Теперь мы оба можем спать спокойно. \n\nПожалуйста, не откажись принять этот дар в знак благодарности.','Вернитесь к ведуну Страннику Туманов к Стальным воротам, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альфа-ворг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты $gсъел:съела; глаза Когтекрыла, ты сможешь увидеть Гарвала и вырвать его глотку!$B$BДитя |3-1($r), разыщи Гарвала в западных Вырубках и убей его. Когда он умрет, вернись к ведуну Страннику Туманов и сообщи ему, что я снова стал вожаком стаи воргов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Улклык попросил вас убить Гарвала. После этого вы должны будете вернуть личину ворга ведуну Страннику Туманов в Стальные ворота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гарвал был не воргом! Судя по твоему рассказу, эта тварь больше похожа на воргена!\n\nНо Улклык вроде бы упоминал, что Гарвал явился с юга, из Седых холмов? Как странно. Воргены не водятся в тех местах...\n\nКак бы то ни было, я благодарю тебя за то, что ты помог Улклыку занять подобающее ему место в стае. Теперь мы оба можем спать спокойно. \n\nПожалуйста, не откажись принять этот дар в знак благодарности.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведуну Страннику Туманов к Стальным воротам, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11325,'В обличье ворга','Во сне я видела Улклыка в пещере на заснеженном краю Вырубок, где-то на северо-западе.$B$BЕму грозит страшная опасность!$B$BЯ сделала магическую личину, которая сделает тебя $gпохожим:похожей; на ворга. Это очень нестабильная личина, которая действует только в пределах Вырубок. Однако с ее помощью ты сможешь обмануть воргов и добраться до Улклыка.$B$BПрошу тебя, |3-6($c), отыщи Улклыка и помоги ему.','Дозорная Лунный Лепесток попросила вас найти Улклыка в Вырубках и помочь ему.$B$BЕсли вы потеряете личину ворга, вернитесь к дозорной Лунный Лепесток, и она даст вам новую.','Ты как-то странно выглядишь, и запах у тебя необычный... ты не из моей стаи. Расскажи, что привело тебя сюда. Все равно мне больше нечем заняться, пока я заперт в этом месте.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В обличье ворга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во сне я видела Улклыка в пещере на заснеженном краю Вырубок, где-то на северо-западе.$B$BЕму грозит страшная опасность!$B$BЯ сделала магическую личину, которая сделает тебя $gпохожим:похожей; на ворга. Это очень нестабильная личина, которая действует только в пределах Вырубок. Однако с ее помощью ты сможешь обмануть воргов и добраться до Улклыка.$B$BПрошу тебя, |3-6($c), отыщи Улклыка и помоги ему.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дозорная Лунный Лепесток попросила вас найти Улклыка в Вырубках и помочь ему.$B$BЕсли вы потеряете личину ворга, вернитесь к дозорной Лунный Лепесток, и она даст вам новую.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты как-то странно выглядишь, и запах у тебя необычный... ты не из моей стаи. Расскажи, что привело тебя сюда. Все равно мне больше нечем заняться, пока я заперт в этом месте.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11326,'Альфа-ворг','Теперь, когда ты $gсъел:съела; глаза Когтекрыла, ты сможешь увидеть Гарвала и вырвать его глотку!$B$BДитя |3-1($r), разыщи Гарвала в западных Вырубках и убей его. Когда он умрет, вернись к дозорной Лунный Лепесток и сообщи ей, что я снова стал вожаком стаи воргов!','Улклык попросил вас убить Гарвала. После этого вы должны будете вернуть личину ворга дозорной Лунный Лепесток в Стальные ворота.','Гарвал был не воргом! Судя по твоему рассказу, эта тварь больше похожа на воргена!$B$BНо Улклык вроде бы упоминал, что Гарвал пришел на юг из Седых холмов? Как странно. Воргены не водятся в тех местах...$B$BКак бы то ни было, я благодарю тебя за то, что ты $Gпомог:помогла; Улклыку занять подобающее ему место в стае. Теперь мы оба можем спать спокойно.$B$BПожалуйста, не откажись принять этот дар в знак благодарности.','$N! Какие новости об Улклыке?','Вернитесь к дозорной Лунный Лепесток к Стальным воротам, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Альфа-ворг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты $gсъел:съела; глаза Когтекрыла, ты сможешь увидеть Гарвала и вырвать его глотку!$B$BДитя |3-1($r), разыщи Гарвала в западных Вырубках и убей его. Когда он умрет, вернись к дозорной Лунный Лепесток и сообщи ей, что я снова стал вожаком стаи воргов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Улклык попросил вас убить Гарвала. После этого вы должны будете вернуть личину ворга дозорной Лунный Лепесток в Стальные ворота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Гарвал был не воргом! Судя по твоему рассказу, эта тварь больше похожа на воргена!$B$BНо Улклык вроде бы упоминал, что Гарвал пришел на юг из Седых холмов? Как странно. Воргены не водятся в тех местах...$B$BКак бы то ни было, я благодарю тебя за то, что ты $Gпомог:помогла; Улклыку занять подобающее ему место в стае. Теперь мы оба можем спать спокойно.$B$BПожалуйста, не откажись принять этот дар в знак благодарности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N! Какие новости об Улклыке?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к дозорной Лунный Лепесток к Стальным воротам, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11327,'Задание: найти сверток','Ох, как же нам нужны образцы этой чумы!$B$BА, придумал!$B$BПока ты $gуничтожал:уничтожала; резервуары, я проследил за одним из аптекарей из Нового Агамонда. Его утащили в Халгринд местные врайкулы. И поделом.$B$B$n, я могу поспорить, что у него были с собой какие-то вещи. Может быть, тебе стоит отправиться в Халгринд и достать его пожитки?','Разведчик Ноулс просит вас найти сверток аптекаря в Халгринде. Принесите его разведчику в Тлеющую башню.','Великий свет... это еще что?! Ты только посмотри!$B$BНам надо как можно скорее доставить этот сверток в крепость!','Вернитесь к разведчику Ноулсу в Тлеющую башню, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание: найти сверток',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ох, как же нам нужны образцы этой чумы!$B$BА, придумал!$B$BПока ты $gуничтожал:уничтожала; резервуары, я проследил за одним из аптекарей из Нового Агамонда. Его утащили в Халгринд местные врайкулы. И поделом.$B$B$n, я могу поспорить, что у него были с собой какие-то вещи. Может быть, тебе стоит отправиться в Халгринд и достать его пожитки?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разведчик Ноулс просит вас найти сверток аптекаря в Халгринде. Принесите его разведчику в Тлеющую башню.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Великий свет... это еще что?! Ты только посмотри!$B$BНам надо как можно скорее доставить этот сверток в крепость!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Ноулсу в Тлеющую башню, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11328,'Задание: чума Отрекшихся','Так вот; отнеси эту штуку обратно в крепость и отдай Пеппи Нетосопло. Она, конечно, не самый лучший алхимик, но другого у нас нет.$B$BТолько учти – она очень любит выпить, так что для начала загляни в таверну.$B$BВ общем, она знает, что делать с этой штукой.','Разведчик Ноулс просит вас отнести сверток аптекаря Пеппи Нетосопло в Крепость Западной Стражи.','А... это же совершенно меняет дело!$B$BЛадно, дай-ка взглянуть... Обожаю все эти алхимические штучки!$B$BНу-ка, ну-ка... Ага, знаю! Надо всего лишь смешать эту фигню вот с этой бурдой в равных пропорциях.$B$BИ, пожалуй, не будет лишним добавить кусочек гнилых внутренностей... ик!','Вернитесь к Пеппи Нетосопло в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание: чума Отрекшихся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так вот; отнеси эту штуку обратно в крепость и отдай Пеппи Нетосопло. Она, конечно, не самый лучший алхимик, но другого у нас нет.$B$BТолько учти – она очень любит выпить, так что для начала загляни в таверну.$B$BВ общем, она знает, что делать с этой штукой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Разведчик Ноулс просит вас отнести сверток аптекаря Пеппи Нетосопло в Крепость Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А... это же совершенно меняет дело!$B$BЛадно, дай-ка взглянуть... Обожаю все эти алхимические штучки!$B$BНу-ка, ну-ка... Ага, знаю! Надо всего лишь смешать эту фигню вот с этой бурдой в равных пропорциях.$B$BИ, пожалуй, не будет лишним добавить кусочек гнилых внутренностей... ик!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пеппи Нетосопло в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11329,'Я готов на все!','Как же мне надоели эти бочки с засоленной рыбой! Я набиваю их целыми днями, а работы еще непочатый край!$B$BАх, если бы только у меня осталась эта приманка Ната Пэгла! Вот уж действительно чудесная штука. Теперь же я радуюсь, если удается поймать за час хотя бы одну рыбку. $B$BСлышал я, что из северной рыбы-шипа получается неплохая приманка, но кто же в здравом уме полезет в ледяную воду и будет бултыхаться среди водорослей в поисках этой пронырливой рыбки? Не я, это точно... разве что тебя удастся уговорить...','Принесите Кристоферу Слоану из крепости Вилдервар 5 северных рыб-шипов.','Фу, какие мерзкие твари! Ладно, неважно, как они выглядят – лишь бы на них кто-нибудь клюнул. Скорее бы экспедиция убралась отсюда. Тогда я смогу рыбачить для собственного удовольствия.','Вернитесь к Кристоферу Слоану в Крепость Вилдервар, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я готов на все!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как же мне надоели эти бочки с засоленной рыбой! Я набиваю их целыми днями, а работы еще непочатый край!$B$BАх, если бы только у меня осталась эта приманка Ната Пэгла! Вот уж действительно чудесная штука. Теперь же я радуюсь, если удается поймать за час хотя бы одну рыбку. $B$BСлышал я, что из северной рыбы-шипа получается неплохая приманка, но кто же в здравом уме полезет в ледяную воду и будет бултыхаться среди водорослей в поисках этой пронырливой рыбки? Не я, это точно... разве что тебя удастся уговорить...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Кристоферу Слоану из крепости Вилдервар 5 северных рыб-шипов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фу, какие мерзкие твари! Ладно, неважно, как они выглядят – лишь бы на них кто-нибудь клюнул. Скорее бы экспедиция убралась отсюда. Тогда я смогу рыбачить для собственного удовольствия.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кристоферу Слоану в Крепость Вилдервар, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11330,'Это... точно сработает!','Ага, вакцина от чумы готова.$B$BПравда, я не собираюсь испытывать ее на себе. Могу предположить, что ты тоже не горишь желанием стать подопытным кроликом?$B$BО, точно!$B$BУ нас же есть врайкульский пленник в темнице под крепостью! Давай-ка ты отнесешь ему эту мешанину и заставишь его выпить...ик, до дна?','Пеппи Нетосопло предложила вам отнести ее особую смесь врайкулу-узнику из клана Укротителей драконов. Когда он выпьет смесь, вернитесь в Крепость Западной Стражи и расскажите Пеппи о результатах эксперимента.','Вернитесь к Пеппи Нетосопло в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это... точно сработает!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ага, вакцина от чумы готова.$B$BПравда, я не собираюсь испытывать ее на себе. Могу предположить, что ты тоже не горишь желанием стать подопытным кроликом?$B$BО, точно!$B$BУ нас же есть врайкульский пленник в темнице под крепостью! Давай-ка ты отнесешь ему эту мешанину и заставишь его выпить...ик, до дна?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пеппи Нетосопло предложила вам отнести ее особую смесь врайкулу-узнику из клана Укротителей драконов. Когда он выпьет смесь, вернитесь в Крепость Западной Стражи и расскажите Пеппи о результатах эксперимента.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Пеппи Нетосопло в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11331,'Ик... Ты ему и скажи!','Короче, так. Я не собираюсь идти к капитану с такими новостями! В мои обязанности это не входит, и вообще, у меня перерыв. $B$BОн же такая злюка... да ты не хуже меня его знаешь!$B$BВ общем, топай в крепость $gсам:сама;. Я уверена, он тебя выслушает, и все такое... ик! $B$B<Пеппи снова прикладывается к бутылке.>','Пеппи Нетосопло уговорила вас сообщить плохие новости о новой чуме Отрекшихся капитану Адамсу. Его можно найти в Крепости Западной Стражи.','Да, $N, что еще ты хочешь мне доложить?$B$BЧТО?! Отрекшиеся создали чуму, которая может в считанные мгновения превратить человека в лужу? И ты $Gрасплавил:расплавила; моего пленного врайкула?$B$B<Капитан огорченно смотрит по сторонам и презрительно сплевывает на пол.>$B$BНу, ладно. Я знаю, что нам делать. Точнее, не нам, а ТЕБЕ!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ик... Ты ему и скажи!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Короче, так. Я не собираюсь идти к капитану с такими новостями! В мои обязанности это не входит, и вообще, у меня перерыв. $B$BОн же такая злюка... да ты не хуже меня его знаешь!$B$BВ общем, топай в крепость $gсам:сама;. Я уверена, он тебя выслушает, и все такое... ик! $B$B<Пеппи снова прикладывается к бутылке.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Пеппи Нетосопло уговорила вас сообщить плохие новости о новой чуме Отрекшихся капитану Адамсу. Его можно найти в Крепости Западной Стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $N, что еще ты хочешь мне доложить?$B$BЧТО?! Отрекшиеся создали чуму, которая может в считанные мгновения превратить человека в лужу? И ты $Gрасплавил:расплавила; моего пленного врайкула?$B$B<Капитан огорченно смотрит по сторонам и презрительно сплевывает на пол.>$B$BНу, ладно. Я знаю, что нам делать. Точнее, не нам, а ТЕБЕ!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11332,'Задание: уничтожить чуму!','В Королевском фармацевтическом обществе собираются запустить новую чуму, которая может расплавить человека на месте?!$B$BТолько не во время моего дежурства!$B$BОтправляйся во внутренний двор и поговори с Гриром Рудомолотом. Он должен был уже приготовить для тебя грифона и несколько бомб. Я хочу, чтобы ты $gразнес:разнесла; в щепки резервуары с чумой в Новом Агамонде.','Капитан Адамс приказал вам сбросить 5 бомб на резервуары с чумой в Новом Агамонде. Вернитесь к нему в Крепость Западной Стражи, когда это поручение будет выполнено.','Молодец, $N, отличная работа!$B$B<Капитан чуть ли не пляшет от радости.>$B$BТеперь эти жалкие Отрекшиеся поймут, что с нами не стоит связываться!$B$BПожалуй, ты $Gзаслужил:заслужила; награду из нашей сокровищницы!','Эти чумные танки уже уничтожены? Эта новая чума нависла над нашими головами, как верная смерть, $C!','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Задание: уничтожить чуму!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Королевском фармацевтическом обществе собираются запустить новую чуму, которая может расплавить человека на месте?!$B$BТолько не во время моего дежурства!$B$BОтправляйся во внутренний двор и поговори с Гриром Рудомолотом. Он должен был уже приготовить для тебя грифона и несколько бомб. Я хочу, чтобы ты $gразнес:разнесла; в щепки резервуары с чумой в Новом Агамонде.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Адамс приказал вам сбросить 5 бомб на резервуары с чумой в Новом Агамонде. Вернитесь к нему в Крепость Западной Стражи, когда это поручение будет выполнено.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, $N, отличная работа!$B$B<Капитан чуть ли не пляшет от радости.>$B$BТеперь эти жалкие Отрекшиеся поймут, что с нами не стоит связываться!$B$BПожалуй, ты $Gзаслужил:заслужила; награду из нашей сокровищницы!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти чумные танки уже уничтожены? Эта новая чума нависла над нашими головами, как верная смерть, $C!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11333,'В мир духов','Пока Лига исследователей копается в земле в поисках осколков прошлого, а вице-адмирал пытается постигнуть суть настоящего путем грубой силы, истина скрывается от нас среди призраков.$B$BС помощью особых реагентов я могу заглянуть в мир духов, где мне откроется прошлое, настоящее и будущее Нордскола.$B$BЕсли хочешь узнать больше, принеси мне мой мешочек с реагентами. Я потерял его на корабле, который ныне покоится на дне Бухты Кинжалов, к востоку отсюда.','Торелий Мудрый в Валгарде просит вас найти его мешочек с реагентами.','М-да, носить ее уже не придется, но содержимое в целости и сохранности.$B$B<Торелий запускает руку в сумку и достает несколько причудливых корешков.>$B$BА теперь надо бросить их в огонь и вдохнуть дым!$B$B<Торелий кладет корешки в тлеющую жаровню.>$B$B<Он глубоко вдыхает, и тело его начинает корчиться в судорогах.>$B$BЧто...Что такое... Не может... Я не могу...','Где мой мешочек с реагентами?','Вернитесь к Торелию Мудрому в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В мир духов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока Лига исследователей копается в земле в поисках осколков прошлого, а вице-адмирал пытается постигнуть суть настоящего путем грубой силы, истина скрывается от нас среди призраков.$B$BС помощью особых реагентов я могу заглянуть в мир духов, где мне откроется прошлое, настоящее и будущее Нордскола.$B$BЕсли хочешь узнать больше, принеси мне мой мешочек с реагентами. Я потерял его на корабле, который ныне покоится на дне Бухты Кинжалов, к востоку отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торелий Мудрый в Валгарде просит вас найти его мешочек с реагентами.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','М-да, носить ее уже не придется, но содержимое в целости и сохранности.$B$B<Торелий запускает руку в сумку и достает несколько причудливых корешков.>$B$BА теперь надо бросить их в огонь и вдохнуть дым!$B$B<Торелий кладет корешки в тлеющую жаровню.>$B$B<Он глубоко вдыхает, и тело его начинает корчиться в судорогах.>$B$BЧто...Что такое... Не может... Я не могу...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Где мой мешочек с реагентами?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торелию Мудрому в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11334,'Кто стреляет, тот очки считает!','[PH] Попадите в отмеченную цель.','[PH] Ринлинг хочет, чтобы вы попали в отмеченную цель и вернули ему целевую винтовку.','Вернитесь к Ринлингу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто стреляет, тот очки считает!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[PH] Попадите в отмеченную цель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PH] Ринлинг хочет, чтобы вы попали в отмеченную цель и вернули ему целевую винтовку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ринлингу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11335,'Призыв к оружию: Низина Арати','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $n, и принеси нам победу. Мы не можем позволить Ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!','Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Прекрасная новость, $C! Если наши тактические действия будут и впредь столь же успешны, Орде очень скоро придется отступать по всем фронтам!','Победа в Низине Арати','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Низина Арати',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Низине Арати требуются отважные бойцы.$B$BИди, $n, и принеси нам победу. Мы не можем позволить Ордынским отродьям претендовать на ресурсы, которые по праву принадлежат нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасная новость, $C! Если наши тактические действия будут и впредь столь же успешны, Орде очень скоро придется отступать по всем фронтам!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа в Низине Арати',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11336,'Призыв к оружию: Альтеракская долина','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Альтеракской долине требуются отважные бойцы.$B$BСтупай прямо сейчас, $n, и помоги стражам Грозовой Вершины. Мы не можем допустить, чтобы клан Северного Волка ушел без возмездия после всего того зла, что они причинили нашим собратьям!','Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Победа в Альтеракской долине','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Альтеракская долина',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Беда битвы на несколько фронтов, $gпарень:подруга;, в том, что приходится рассредотачивать силы, и в результате мы рискуем потерять все!$B$BНам каждый день требуется подкрепление. Сегодня войскам в Альтеракской долине требуются отважные бойцы.$B$BСтупай прямо сейчас, $n, и помоги стражам Грозовой Вершины. Мы не можем допустить, чтобы клан Северного Волка ушел без возмездия после всего того зла, что они причинили нашим собратьям!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа в Альтеракской долине',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11337,'Призыв к оружию: Око Бури','Война с Ордой не ведает границ, $n. Даже в Запределье застарелая ненависть и территориальные претензии вынуждают нас воевать.$B$BИди в Око Бури и измени равновесие в Запределье в пользу Альянса, как в Азероте.','Победите на поле боя Ока Бури и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Мы на шаг приблизились к полной победе над Ордой! Мы не можем позволить врагу завоевать плацдарм ни в этом мире, ни в каком другом!','Победа на поле боя Ока Бури','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Око Бури',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Война с Ордой не ведает границ, $n. Даже в Запределье застарелая ненависть и территориальные претензии вынуждают нас воевать.$B$BИди в Око Бури и измени равновесие в Запределье в пользу Альянса, как в Азероте.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Ока Бури и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы на шаг приблизились к полной победе над Ордой! Мы не можем позволить врагу завоевать плацдарм ни в этом мире, ни в каком другом!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа на поле боя Ока Бури',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11338,'Призыв к оружию: Ущелье Песни Войны','Среброкрылые Часовые защищают лес в Ущелье Песни Войны. Мы помогаем им не из любви к деревьям, а потому, что этот лес является природным защитным барьером вокруг территории Альянса.$B$BСегодня им как никогда нужна помощь. Нам нужно подкрепление прямо сейчас, иначе Ясеневый лес постигнет судьба Степей!','Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.','Победа в Ущелье Песни Войны','Вернитесь к бригадному генералу Альянса.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призыв к оружию: Ущелье Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Среброкрылые Часовые защищают лес в Ущелье Песни Войны. Мы помогаем им не из любви к деревьям, а потому, что этот лес является природным защитным барьером вокруг территории Альянса.$B$BСегодня им как никогда нужна помощь. Нам нужно подкрепление прямо сейчас, иначе Ясеневый лес постигнет судьба Степей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат.',`objectives_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Победа в Ущелье Песни Войны',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к бригадному генералу Альянса.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`) VALUES (11340,'Нет высшей чести, чем изгнать захватчиков с земель Орды! Мы ныне славим твою великую отвагу в помощи нашим войскам!') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Нет высшей чести, чем изгнать захватчиков с земель Орды! Мы ныне славим твою великую отвагу в помощи нашим войскам!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11343,'Эхо Имирона','Мир духов пал под натиском Короля-лича. Ужасные существа, порождения кошмаров, ныне сторожат владения стихий. Я чувствую, что эти валь\'киры охраняют страшную тайну.$B$BЯ слишком стар и слаб, чтобы пережить еще одно путешествие, поэтому ты, $n, отправишься вместо меня.$B$BВозьми эту курительницу и отправляйся в Деревню Драконьего Черепа. Зажги ее, чтобы проникнуть в мир духов, и обыщи все здания в деревне на северо-востоке. Но будь $gосторожен:осторожна; – валь\'киры могут навсегда оставить тебя в своем мире!','Торелий Мудрый просит вас обыскать Деревню Драконьего Черепа в мире духов и найти информацию о тайнах Ниффлвара.','Не понимаю. Говоришь, эти существа были похожи на врайкулов, которые нападают на Валгард?','Что тебе удалось узнать?','Разгадать тайну Деревни Драконьего Черепа','Вернитесь к Торелию Мудрому в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Эхо Имирона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мир духов пал под натиском Короля-лича. Ужасные существа, порождения кошмаров, ныне сторожат владения стихий. Я чувствую, что эти валь\'киры охраняют страшную тайну.$B$BЯ слишком стар и слаб, чтобы пережить еще одно путешествие, поэтому ты, $n, отправишься вместо меня.$B$BВозьми эту курительницу и отправляйся в Деревню Драконьего Черепа. Зажги ее, чтобы проникнуть в мир духов, и обыщи все здания в деревне на северо-востоке. Но будь $gосторожен:осторожна; – валь\'киры могут навсегда оставить тебя в своем мире!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торелий Мудрый просит вас обыскать Деревню Драконьего Черепа в мире духов и найти информацию о тайнах Ниффлвара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не понимаю. Говоришь, эти существа были похожи на врайкулов, которые нападают на Валгард?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось узнать?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Разгадать тайну Деревни Драконьего Черепа',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торелию Мудрому в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11344,'Страдания Ниффлвара','Наши скромные познания о врайкулах позволяют сделать вывод, что они лишь недавно появились в Нордсколе. Почему же тогда мы видим их в пророчествах, сделанных 15,000 лет назад? Если бы врайкулы раньше обитали на этом континенте, мы бы об этом знали.$B$BТебе надо продолжить работу в Ниффлваре. Чтобы добраться туда, иди на северо-восток, через Деревню Драконьего Черепа, после чего сверни на дорогу, идущую через дамбу. Ниффлвар расположен на одном из обрывов фьорда. $B$BКак только прибудешь туда, зажги курительницу и осмотри все вокруг в поисках важной информации.','Торелий Мудрый поручил вам осмотреть Ниффлвар из мира духов и найти информацию о тайнах Ниффлвара.','От врайкулов рождались человеческие дети? И Имирон приказал убить всех полукровок?$B$B<На мгновение Торелий умолкает.>$B$BУвы, бессмысленно отрицать очевидное. Нет никакого "утерянного звена", ведущего к возникновению человека. Лига исследователей ошибалась – врайкулы и есть то самое недостающее звено. Они – прародители человечества.','Что тебе удалось узнать?','Разгадать тайну Ниффлвара','Вернитесь к Торелию Мудрому в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страдания Ниффлвара',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши скромные познания о врайкулах позволяют сделать вывод, что они лишь недавно появились в Нордсколе. Почему же тогда мы видим их в пророчествах, сделанных 15,000 лет назад? Если бы врайкулы раньше обитали на этом континенте, мы бы об этом знали.$B$BТебе надо продолжить работу в Ниффлваре. Чтобы добраться туда, иди на северо-восток, через Деревню Драконьего Черепа, после чего сверни на дорогу, идущую через дамбу. Ниффлвар расположен на одном из обрывов фьорда. $B$BКак только прибудешь туда, зажги курительницу и осмотри все вокруг в поисках важной информации.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торелий Мудрый поручил вам осмотреть Ниффлвар из мира духов и найти информацию о тайнах Ниффлвара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','От врайкулов рождались человеческие дети? И Имирон приказал убить всех полукровок?$B$B<На мгновение Торелий умолкает.>$B$BУвы, бессмысленно отрицать очевидное. Нет никакого "утерянного звена", ведущего к возникновению человека. Лига исследователей ошибалась – врайкулы и есть то самое недостающее звено. Они – прародители человечества.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что тебе удалось узнать?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Разгадать тайну Ниффлвара',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Торелию Мудрому в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11345,'Приз за попадание','[PH] Попадите в отмеченную цель.','[PH] Ринлинг хочет, чтобы вы попали в отмеченную цель и вернули ему целевую винтовку.','Вернитесь к Ринлингу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Приз за попадание',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[PH] Попадите в отмеченную цель.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PH] Ринлинг хочет, чтобы вы попали в отмеченную цель и вернули ему целевую винтовку.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ринлингу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11346,'Книга Рун','Геолог Белвар из крепости Вилдервар просит вас найти Книгу Рун.','<Геолог Белвар листает книгу Рун.>$B$BОго... здесь так много информации. Мне потребуется время, чтобы изучить эту книгу. Если мы постигнем смысл этих рун, то сможем воспользоваться ими в своих целях.','Вернитесь к геологу Белвару в Крепость Вилдервар, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Книга Рун',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Геолог Белвар из крепости Вилдервар просит вас найти Книгу Рун.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Геолог Белвар листает книгу Рун.>$B$BОго... здесь так много информации. Мне потребуется время, чтобы изучить эту книгу. Если мы постигнем смысл этих рун, то сможем воспользоваться ими в своих целях.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Белвару в Крепость Вилдервар, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11347,'<NYI>Расчистите место','Нам надо доставить в таверну Караноса кучу посылок. Причем быстро. Можешь взять моего скакового барана. Доставь хотя бы одну посылку. Времени у тебя немного – всего пять минут. Чем больше ты доставишь посылок, тем больше будет награда.','Доставьте в Каранос не меньше одной посылки. Чем больше доставить посылок, тем больше будет награда.','Вернитесь к ...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','<NYI>Расчистите место',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам надо доставить в таверну Караноса кучу посылок. Причем быстро. Можешь взять моего скакового барана. Доставь хотя бы одну посылку. Времени у тебя немного – всего пять минут. Чем больше ты доставишь посылок, тем больше будет награда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте в Каранос не меньше одной посылки. Чем больше доставить посылок, тем больше будет награда.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ...',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11348,'Руна подчинения','Чувствуешь силу, исходящую от рун, которые я вырезал на этой табличке? Это всего лишь уменьшенная версия тех символов, что используют железные дворфы. Мы же обернем эти руны против них самих. $B$BОтнеси эту табличку на Тропу Великанов и используй на каменном великане, которого еще не успели изменить дворфы. $B$BВеликан будет подчиняться тебе, но недолго. Видишь ли, я вырезал такую руну, которая со временем позволит ему стать самим собой. Пока же этот великан может стать ценным союзником в борьбе против Мурдиса, предводителя железных дворфов.','Геолог Белвар из крепости Вилдервар просит вас испытать руну подчинения и сразиться с Мурдисом-обуздателем.','Руна испытана?','Вернитесь к геологу Белвару в Крепость Вилдервар, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руна подчинения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чувствуешь силу, исходящую от рун, которые я вырезал на этой табличке? Это всего лишь уменьшенная версия тех символов, что используют железные дворфы. Мы же обернем эти руны против них самих. $B$BОтнеси эту табличку на Тропу Великанов и используй на каменном великане, которого еще не успели изменить дворфы. $B$BВеликан будет подчиняться тебе, но недолго. Видишь ли, я вырезал такую руну, которая со временем позволит ему стать самим собой. Пока же этот великан может стать ценным союзником в борьбе против Мурдиса, предводителя железных дворфов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Геолог Белвар из крепости Вилдервар просит вас испытать руну подчинения и сразиться с Мурдисом-обуздателем.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Руна испытана?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Белвару в Крепость Вилдервар, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11349,'Освоение рун','У меня есть с собой несколько молотков, отверток и рубильников, но обычные орудия не подходят для вырезания этих рун. Железные дворфы используют зачарованные инструменты. $B$BКаждый раз, когда они вырезают очередную руну с помощью этих инструментов, они придают словам новое, магическое значение. С помощью таких рун можно привязать к себе, изменить и подчинить любое существо. $B$BЕсли бы мне удалось получить набор магических инструментов, я бы смог вырезать руны, изображенные в книге. Поищи их возле палаток дворфов на Тропе Великанов.','<Белвар бережно берет инструменты.>$B$BЯ попробую ими воспользоваться. Если мы хотим понять логику действий Железных дворфов и победить их, мы должны знать, какое воздействие оказывают эти руны.','Неужели ты несешь мне инструменты?','Вернитесь к геологу Белвару в Крепость Вилдервар, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освоение рун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня есть с собой несколько молотков, отверток и рубильников, но обычные орудия не подходят для вырезания этих рун. Железные дворфы используют зачарованные инструменты. $B$BКаждый раз, когда они вырезают очередную руну с помощью этих инструментов, они придают словам новое, магическое значение. С помощью таких рун можно привязать к себе, изменить и подчинить любое существо. $B$BЕсли бы мне удалось получить набор магических инструментов, я бы смог вырезать руны, изображенные в книге. Поищи их возле палаток дворфов на Тропе Великанов.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Белвар бережно берет инструменты.>$B$BЯ попробую ими воспользоваться. Если мы хотим понять логику действий Железных дворфов и победить их, мы должны знать, какое воздействие оказывают эти руны.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели ты несешь мне инструменты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к геологу Белвару в Крепость Вилдервар, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11350,'Книга Рун','Ты достал книгу?','Вернитесь к выносливому гонцу Пембе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Книга Рун',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты достал книгу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к выносливому гонцу Пембе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11351,'Освоение рун','Кажется, я догадался, что делают Железные дворфы. Они используют зачарованные инструменты. $B$BКаждый раз, когда они вырезают очередную руну с помощью этих инструментов, они придают словам новое, магическое значение. С помощью таких рун можно привязать к себе, изменить и подчинить любое существо. $B$BЕсли бы мне удалось раздобыть набор магических инструментов, я бы смог вырезать руны, изображенные в книге. Мне удалось украсть ящик из палатки на Тропе Великанов, но он оказался пуст. Попробуй найти похожий ящик и принеси мне хранящийся в нем набор инструментов.','Неужели ты несешь мне инструменты?','Вернитесь к выносливому гонцу Пембе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Освоение рун',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кажется, я догадался, что делают Железные дворфы. Они используют зачарованные инструменты. $B$BКаждый раз, когда они вырезают очередную руну с помощью этих инструментов, они придают словам новое, магическое значение. С помощью таких рун можно привязать к себе, изменить и подчинить любое существо. $B$BЕсли бы мне удалось раздобыть набор магических инструментов, я бы смог вырезать руны, изображенные в книге. Мне удалось украсть ящик из палатки на Тропе Великанов, но он оказался пуст. Попробуй найти похожий ящик и принеси мне хранящийся в нем набор инструментов.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неужели ты несешь мне инструменты?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к выносливому гонцу Пембе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11352,'Руна подчинения','Чувствуешь силу, исходящую от рун, которые я вырезал на этой табличке? Это всего лишь уменьшенная версия тех символов, что используют железные дворфы. Мы же обернем эти руны против них самих. $B$BОтнеси эту табличку на Тропу Великанов и используй на каменном великане, которого еще не успели изменить дворфы. $B$BВеликан будет подчиняться тебе, но недолго. Видишь ли, я вырезал такую руну, которая со временем позволит ему стать самим собой. Пока же этот великан может стать ценным союзником в борьбе против Мурдиса, предводителя железных дворфов.','Ты испытал руну?','Вернитесь к выносливому гонцу Пембе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Руна подчинения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чувствуешь силу, исходящую от рун, которые я вырезал на этой табличке? Это всего лишь уменьшенная версия тех символов, что используют железные дворфы. Мы же обернем эти руны против них самих. $B$BОтнеси эту табличку на Тропу Великанов и используй на каменном великане, которого еще не успели изменить дворфы. $B$BВеликан будет подчиняться тебе, но недолго. Видишь ли, я вырезал такую руну, которая со временем позволит ему стать самим собой. Пока же этот великан может стать ценным союзником в борьбе против Мурдиса, предводителя железных дворфов.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты испытал руну?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к выносливому гонцу Пембе в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11353,'FLAG: есть рабочая рубашка') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','FLAG: есть рабочая рубашка',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11354,'Торговец ветром Зерим просит вас добыть ездовой хлыст Назана. Доставьте его ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.','Значит, еще один клиент вскоре будет удовлетворен. А вы будете вознаграждены.$B$BПриходите поутру, и я подберу вам новое дельце.','Прошу предъявить ездовой хлыст.','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торговец ветром Зерим просит вас добыть ездовой хлыст Назана. Доставьте его ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, еще один клиент вскоре будет удовлетворен. А вы будете вознаграждены.$B$BПриходите поутру, и я подберу вам новое дельце.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Прошу предъявить ездовой хлыст.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11356,'Переодетая попечительница сирот','Поговорите с переодетой попечительницей сирот в Златоземье, Караносе или на Лазурной заставе.','Вы пришли к детишкам! Замечательно! Они столько горя испытали за свою недолгую жизнь... Хорошо, что они посмотрят на настоящих героев, вроде вас. Это так поднимет их дух!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переодетая попечительница сирот',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с переодетой попечительницей сирот в Златоземье, Караносе или на Лазурной заставе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы пришли к детишкам! Замечательно! Они столько горя испытали за свою недолгую жизнь... Хорошо, что они посмотрят на настоящих героев, вроде вас. Это так поднимет их дух!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11357,'Попечительница сирот в маске','Детям нравится наблюдать за героями в деле. Надеюсь, что однажды эти сиротки станут сильными воителями Орды и погибнут в славной битве!$B$BАх, у меня все в глазах плывет от одной мысли о столь блистательной кончине...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Попечительница сирот в маске',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Детям нравится наблюдать за героями в деле. Надеюсь, что однажды эти сиротки станут сильными воителями Орды и погибнут в славной битве!$B$BАх, у меня все в глазах плывет от одной мысли о столь блистательной кончине...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11360,'Учения пожарной бригады','Пока Всадник без головы еще угрожает нам, герои Златоземья всегда готовы сформировать пожарные бригады. Не хотите ли помочь?$B$BК северу отсюда стражники организовали небольшой полигон для учений пожарных бригад. Идите туда и носите ведрами воду, чтобы тушить пожар. Воду можно черпать ведром из этих бочек с водой.$B$BУдачи, $n. Когда поучаствуете в учениях пожарной бригады, возвращайтесь к нам!','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.','Привет, $N. Вы совершенствовали свои методы пожаротушения? Не забывайте о тренировочной зоне на севере!','Вернитесь к переодетой попечительнице сирот в Златоземье, что в Элвиннском лесу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Учения пожарной бригады',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока Всадник без головы еще угрожает нам, герои Златоземья всегда готовы сформировать пожарные бригады. Не хотите ли помочь?$B$BК северу отсюда стражники организовали небольшой полигон для учений пожарных бригад. Идите туда и носите ведрами воду, чтобы тушить пожар. Воду можно черпать ведром из этих бочек с водой.$B$BУдачи, $n. Когда поучаствуете в учениях пожарной бригады, возвращайтесь к нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $N. Вы совершенствовали свои методы пожаротушения? Не забывайте о тренировочной зоне на севере!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к переодетой попечительнице сирот в Златоземье, что в Элвиннском лесу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11361,'Учения пожарной бригады','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Колючем Холме.','Вы затушили пожары, $N? Тренировочная зона находится к западу от западного выхода Колючего Холма.','Вернитесь к попечительнице сирот в маске в Колючий Холм, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Учения пожарной бригады',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Колючем Холме.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы затушили пожары, $N? Тренировочная зона находится к западу от западного выхода Колючего Холма.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к попечительнице сирот в маске в Колючий Холм, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11362,'Торговец ветром Зерим просит вас добыть украшенный перьями посох Кели\'дана. Принесите его ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.','Наверное, надо будет навязать на него новых перышек прежде, чем отдавать заказчику. Думаю, с таким количеством араккоа по соседству с перьями проблем не будет. Дело невеликое, и в любом случае ваша награда от этого меньше не станет.$B$BПриходите утром, и я вам новое дельце подберу.','Раз мы с вами снова беседуем... То посох у вас.','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торговец ветром Зерим просит вас добыть украшенный перьями посох Кели\'дана. Принесите его ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наверное, надо будет навязать на него новых перышек прежде, чем отдавать заказчику. Думаю, с таким количеством араккоа по соседству с перьями проблем не будет. Дело невеликое, и в любом случае ваша награда от этого меньше не станет.$B$BПриходите утром, и я вам новое дельце подберу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Раз мы с вами снова беседуем... То посох у вас.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11363,'Один мой очень богатый клиент сделал заказ на действительно уникальную вещь.$B$BВождь Каргат Острорук имеет личную печать, которой он заверяет официальные документы. Добудь ее для меня.$B$BТы найдешь Каргата в глубине Разрушенных залов. Тебе придется перебить немало орков, чтобы добраться до него, но ты справишься, я уверен.','Торговец ветром Зерим просит вас добыть печать Острорука. Принесите ее ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.','Воистину геройское деяние, достойное воспевания бардов! Вот, ты более чем $Gзаслужил:заслужила; эту награду.$B$BПриходи завтра – у меня найдется для тебя новое дельце.','Слышал я, что у вождя вместо на месте рук клинки... Это правда?','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один мой очень богатый клиент сделал заказ на действительно уникальную вещь.$B$BВождь Каргат Острорук имеет личную печать, которой он заверяет официальные документы. Добудь ее для меня.$B$BТы найдешь Каргата в глубине Разрушенных залов. Тебе придется перебить немало орков, чтобы добраться до него, но ты справишься, я уверен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торговец ветром Зерим просит вас добыть печать Острорука. Принесите ее ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Воистину геройское деяние, достойное воспевания бардов! Вот, ты более чем $Gзаслужил:заслужила; эту награду.$B$BПриходи завтра – у меня найдется для тебя новое дельце.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Слышал я, что у вождя вместо на месте рук клинки... Это правда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11364,'Ловчий Пустоты Ма\'дуун поручает вам убить 4 центурионов клана Изувеченной Длани. Вернитесь к нему в Нижний Город Шаттрата за наградой, как только перебьете их всех.','Очень хорошо. Ты $Gзаслужил:заслужила; свою награду.$B$BПриходи завтра, а ветер еще разок пошепчется с Мадууном.','Вы вернулись. Все центурионы мертвы?','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ловчий Пустоты Ма\'дуун поручает вам убить 4 центурионов клана Изувеченной Длани. Вернитесь к нему в Нижний Город Шаттрата за наградой, как только перебьете их всех.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень хорошо. Ты $Gзаслужил:заслужила; свою награду.$B$BПриходи завтра, а ветер еще разок пошепчется с Мадууном.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы вернулись. Все центурионы мертвы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11368,'У меня к тебе довольно необычная просьба, $n. Одна состоятельная госпожа, моя постоянная клиентка, желает приобрести довольно жуткий предмет.$B$BЭто сердце чудовища, именуемого Зыбуном.$B$BВообще-то, у твари три сердца, однако нам будет довольно одного. Полагаю, ты найдешь Зыбуна в глубоком пруду в Узилище.','Добудьте сердце Зыбуна и доставьте его торговцу ветром Зариму в Нижний Город Шаттрата за вознаграждение. $B$BЗадание можно выполнить только в режиме героической сложности.','Какая жалость, что я не догадался попросить тебя принести заодно и два других сердца... Может, в следующий раз. В любом случае, ты честно $Gзаслужил:заслужила; обещанную награду.$B$BЗаходи завтра – у меня найдется для тебя работа.','Надеюсь, ты знаешь, как сохранить сердце при транспортировке?','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У меня к тебе довольно необычная просьба, $n. Одна состоятельная госпожа, моя постоянная клиентка, желает приобрести довольно жуткий предмет.$B$BЭто сердце чудовища, именуемого Зыбуном.$B$BВообще-то, у твари три сердца, однако нам будет довольно одного. Полагаю, ты найдешь Зыбуна в глубоком пруду в Узилище.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте сердце Зыбуна и доставьте его торговцу ветром Зариму в Нижний Город Шаттрата за вознаграждение. $B$BЗадание можно выполнить только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какая жалость, что я не догадался попросить тебя принести заодно и два других сердца... Может, в следующий раз. В любом случае, ты честно $Gзаслужил:заслужила; обещанную награду.$B$BЗаходи завтра – у меня найдется для тебя работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Надеюсь, ты знаешь, как сохранить сердце при транспортировке?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11369,'Это великая праматерь болотоходов в Зангартопи. Она носит имя Черная Охотница. Умирая, она откладывает яйцо, из которого появляется новая Черная Охотница.$B$BОдин из моих клиентов желает приобрести такое яйцо. Вроде бы, он собирается держать тварь в частном зоопарке.$B$BЕсли хочешь получить вознаграждение, отправляйся в Нижетопь, убей Черную Охотницу и принеси мне ее яйцо.','Добудьте яйцо Черной Охотницы и доставьте его торговцу ветром Зариму в Нижний Город Шаттрата за вознаграждение. $B$BЗадание можно выполнить только в режиме героической сложности.','Неплохо! До тебя были и другие, кто надеялся получить награду, но они так и не вернулись за ней. Нетрудно представить, что с ними стало.$B$BЯ рад, что Муммаки и его ублюдки больше не будут нас тревожить.','Так ты хочешь получить награду за вождя Муммаки?','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это великая праматерь болотоходов в Зангартопи. Она носит имя Черная Охотница. Умирая, она откладывает яйцо, из которого появляется новая Черная Охотница.$B$BОдин из моих клиентов желает приобрести такое яйцо. Вроде бы, он собирается держать тварь в частном зоопарке.$B$BЕсли хочешь получить вознаграждение, отправляйся в Нижетопь, убей Черную Охотницу и принеси мне ее яйцо.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте яйцо Черной Охотницы и доставьте его торговцу ветром Зариму в Нижний Город Шаттрата за вознаграждение. $B$BЗадание можно выполнить только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Неплохо! До тебя были и другие, кто надеялся получить награду, но они так и не вернулись за ней. Нетрудно представить, что с ними стало.$B$BЯ рад, что Муммаки и его ублюдки больше не будут нас тревожить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так ты хочешь получить награду за вождя Муммаки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11370,'Многим известно, что полководец Калитреш по праву считался величайшим воином среди наг. Однако немногие знают, что он изложил свой военный опыт в трактате.$B$BСреди моих клиентов есть один господин, великолепно разбирающийся в военной истории. Он желает приобрести этот трактат.$B$BПрошу тебя отправиться в Паровое подземелье в Резервуар Кривого Клыка и найти для меня эту книгу.','Добудьте трактат полководца и доставьте его торговцу ветром Зариму в Нижний Город Шаттрата за вознаграждение. $B$BЗадание можно выполнить только в режиме героической сложности.','Да, это действительно весьма, весьма богатая работа – хорошо бы мой клиент смог поднять этот талмуд, не говоря уж о том, чтобы успеть детально изучить его, прежде чем враги пойдут на него с войной.$B$BЗаходи завтра – у меня найдется для тебя работа.','Мой клиент уже нервничает. Я думаю, он хочет самолично опробовать тактические уловки Калитреша на своих недругах как можно скорее.','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Многим известно, что полководец Калитреш по праву считался величайшим воином среди наг. Однако немногие знают, что он изложил свой военный опыт в трактате.$B$BСреди моих клиентов есть один господин, великолепно разбирающийся в военной истории. Он желает приобрести этот трактат.$B$BПрошу тебя отправиться в Паровое подземелье в Резервуар Кривого Клыка и найти для меня эту книгу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте трактат полководца и доставьте его торговцу ветром Зариму в Нижний Город Шаттрата за вознаграждение. $B$BЗадание можно выполнить только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это действительно весьма, весьма богатая работа – хорошо бы мой клиент смог поднять этот талмуд, не говоря уж о том, чтобы успеть детально изучить его, прежде чем враги пойдут на него с войной.$B$BЗаходи завтра – у меня найдется для тебя работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мой клиент уже нервничает. Я думаю, он хочет самолично опробовать тактические уловки Калитреша на своих недругах как можно скорее.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11371,'Я прошу твоей помощи.$B$BМне было поручено уничтожить наг-воинов племени Кривого Клыка. Отыщи их в сырых уголках Парового подземелья в Резервуаре Кривого Клыка.$B$BИмей в виду, требуется уничтожить всех до единого!','Ловчий Пустоты Ма\'дуун требует, чтобы вы убили 14 мирмидонов Резервуара Кривого Клыка. По исполнению задания возвращайтесь к Ма\'дууну в Нижний Город Шаттрата за вознаграждением.','Надеюсь, ты не $Gпожалел:пожалела;, что в это $Gввязался:ввязалась;. Принимай заслуженную награду.$B$BВозвращайся завтра – возможно, ветра подскажут мне, какую тебе дать работу.','Как твоя борьба с мирмидонами Резервуара Кривого Клыка?','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я прошу твоей помощи.$B$BМне было поручено уничтожить наг-воинов племени Кривого Клыка. Отыщи их в сырых уголках Парового подземелья в Резервуаре Кривого Клыка.$B$BИмей в виду, требуется уничтожить всех до единого!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ловчий Пустоты Ма\'дуун требует, чтобы вы убили 14 мирмидонов Резервуара Кривого Клыка. По исполнению задания возвращайтесь к Ма\'дууну в Нижний Город Шаттрата за вознаграждением.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Надеюсь, ты не $Gпожалел:пожалела;, что в это $Gввязался:ввязалась;. Принимай заслуженную награду.$B$BВозвращайся завтра – возможно, ветра подскажут мне, какую тебе дать работу.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как твоя борьба с мирмидонами Резервуара Кривого Клыка?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11372,'Недавно ко мне пришла тауренка, мужу которой предстоит стать вождем. Она хочет сделать особое украшение для его головного убора.$B$BДля этого ей нужны головные перья трусливого Короля воронов Айкисса.$B$BЕсли тебя интересует предложенная награда, Сетеккские залы в Аукиндоне и найди его.','Добудьте перья с головы Айкисса и вернитесь к торговцу Ветром Зариму, в Нижний Город Шаттрата.$B$BЭто задание может быть выполнено только в режиме героической сложности.','Я уверен, эти перья подойдут к головному убору вождя. Ты $Gзаработал:заработала; эти деньги, |3-6($C).$B$BВозвращайся завтра, у меня будет для тебя новое задание.','Церемония все ближе.','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Недавно ко мне пришла тауренка, мужу которой предстоит стать вождем. Она хочет сделать особое украшение для его головного убора.$B$BДля этого ей нужны головные перья трусливого Короля воронов Айкисса.$B$BЕсли тебя интересует предложенная награда, Сетеккские залы в Аукиндоне и найди его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте перья с головы Айкисса и вернитесь к торговцу Ветром Зариму, в Нижний Город Шаттрата.$B$BЭто задание может быть выполнено только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я уверен, эти перья подойдут к головному убору вождя. Ты $Gзаработал:заработала; эти деньги, |3-6($C).$B$BВозвращайся завтра, у меня будет для тебя новое задание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Церемония все ближе.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11373,'Добудьте заговоренный амулет Шаффара и вернитесь к торговцу Ветром Зариму, в Нижний Город Шаттрата.$B$BЭто задание может быть выполнено только в режиме героической сложности.','Я беспокоился о тебе. Надеюсь, ты не $Gоглох:оглохла; во время поединка с Бормотуном?$B$BВот твоя награда. Профессор будет очень доволен, хотя мне страшно представить, что он собирается с этим делать.$B$BВозвращайся завтра, у меня будет для тебя новое задание.','Немногие знают, что магические силы Шаффара напрямую связаны с его амулетом. Без него он бессилен.$B$BЕсли амулет у тебя, то Шаффар, очевидно, мертв.','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте заговоренный амулет Шаффара и вернитесь к торговцу Ветром Зариму, в Нижний Город Шаттрата.$B$BЭто задание может быть выполнено только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я беспокоился о тебе. Надеюсь, ты не $Gоглох:оглохла; во время поединка с Бормотуном?$B$BВот твоя награда. Профессор будет очень доволен, хотя мне страшно представить, что он собирается с этим делать.$B$BВозвращайся завтра, у меня будет для тебя новое задание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Немногие знают, что магические силы Шаффара напрямую связаны с его амулетом. Без него он бессилен.$B$BЕсли амулет у тебя, то Шаффар, очевидно, мертв.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11374,'В Аукенайских гробницах в Аукиндоне проводится множество сомнительных экспериментов в области некромантии. Там были замучены или уничтожены многие духи.$B$BОдин мой заказчик весьма заинтересован в освобождении одного из этих духов. Он заключен в камень, который носит не кто иной, как Экзарх Маладаар.$B$BКак можно скорее разыщи его в гробницах и принеси мне этот камень.','Ты $Gнастоящий:настоящая; $Gгерой:героиня;, $N. Я уверен, что мой клиент найдет способ освободить дух своего любимого человека из камня. За хорошую работу и плата полагается соответствующая.$B$BВозвращайся завтра, у меня будет для тебя новое задание.','Представляешь, каково это – быть навечно заключенным в камне.','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Аукенайских гробницах в Аукиндоне проводится множество сомнительных экспериментов в области некромантии. Там были замучены или уничтожены многие духи.$B$BОдин мой заказчик весьма заинтересован в освобождении одного из этих духов. Он заключен в камень, который носит не кто иной, как Экзарх Маладаар.$B$BКак можно скорее разыщи его в гробницах и принеси мне этот камень.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gнастоящий:настоящая; $Gгерой:героиня;, $N. Я уверен, что мой клиент найдет способ освободить дух своего любимого человека из камня. За хорошую работу и плата полагается соответствующая.$B$BВозвращайся завтра, у меня будет для тебя новое задание.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Представляешь, каково это – быть навечно заключенным в камне.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11375,'Когда я расскажу все до конца, ты можешь захотеть отказаться от этого задания.$B$BУ моего клиента весьма эксцентричное увлечение – он специализируется на погибших реальностях. Ходят слухи, что тот, кого мы знаем как Бормотуна, уничтожил мир, из которого он был вызван. Профессор хочет изучить его "шепот" – так он это называет, – чтобы понять, как Бормотуну это удалось.$B$BСможешь ли ты отправиться в Аукиндонский Темный лабиринт и добыть этот "шепот"?','Добудьте Шепот Бормотуна и вернитесь к торговцу Ветром Зариму, в Нижний Город Шаттрата.$B$BЭто задание может быть выполнено только в режиме героической сложности.','Не могу себе представить, как можно поймать шепот, но профессор заявил, что ты все поймешь, как только увидишь его.$B$BВозможно, тебе понадобится что-то вроде "бормотографа"...','Не могу себе представить, как можно поймать шепот, но профессор заявил, что ты все поймешь, как только увидишь его.$B$BВозможно, тебе понадобится что-то вроде "бормотографа"...','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда я расскажу все до конца, ты можешь захотеть отказаться от этого задания.$B$BУ моего клиента весьма эксцентричное увлечение – он специализируется на погибших реальностях. Ходят слухи, что тот, кого мы знаем как Бормотуна, уничтожил мир, из которого он был вызван. Профессор хочет изучить его "шепот" – так он это называет, – чтобы понять, как Бормотуну это удалось.$B$BСможешь ли ты отправиться в Аукиндонский Темный лабиринт и добыть этот "шепот"?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте Шепот Бормотуна и вернитесь к торговцу Ветром Зариму, в Нижний Город Шаттрата.$B$BЭто задание может быть выполнено только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не могу себе представить, как можно поймать шепот, но профессор заявил, что ты все поймешь, как только увидишь его.$B$BВозможно, тебе понадобится что-то вроде "бормотографа"...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не могу себе представить, как можно поймать шепот, но профессор заявил, что ты все поймешь, как только увидишь его.$B$BВозможно, тебе понадобится что-то вроде "бормотографа"...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11376,'Ма\'дуун слышал, будто нет никого злее шестируких демонесс из Темного лабиринта.$B$BОтправляйся в Аукиндон и убей их всех.$B$BЕсли ты не сможешь выполнить такое простое задание, то нам с тобой не о чем говорить.','Я доволен. И тот кто говорит со мной через Пустоту, тоже будет доволен. Ма\'дуун приготовил твою награду.$B$BПриходи завтра и ветра снова будут говорить с Ма\'дууном.','Инструкторы, они все мертвы? Нет?$B$BРазве я не говорил не возвращаться, если ты их всех не $Gубил:убила;?','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ма\'дуун слышал, будто нет никого злее шестируких демонесс из Темного лабиринта.$B$BОтправляйся в Аукиндон и убей их всех.$B$BЕсли ты не сможешь выполнить такое простое задание, то нам с тобой не о чем говорить.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я доволен. И тот кто говорит со мной через Пустоту, тоже будет доволен. Ма\'дуун приготовил твою награду.$B$BПриходи завтра и ветра снова будут говорить с Ма\'дууном.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Инструкторы, они все мертвы? Нет?$B$BРазве я не говорил не возвращаться, если ты их всех не $Gубил:убила;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11377,'Месть сладка','Сегодня я обслуживаю одну очень необычную вечеринку. Один тип летал в Скеттис, и его сбила чудовищная калири. У него тяжелый перелом ноги.$b$bОни заказали особое блюдо для вечеринки по случаю его выздоровления – похлебку из калири.$b$bЯ готов ссудить тебе мой кухонный котелок, так что можешь припасти немного похлебки для меня. Сам рецепт несложен, но тебе придется добыть крылышко гигантской калири и несколько готовых котлет из прыгуаны.','Скалл из Нижнего Города просит вас приготовить похлебку из калири в его кухонном котелке. По выполнении вернитесь к нему.','Какой восхитительный аромат! Неужто наяву?','Вернитесь к Скаллу в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть сладка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сегодня я обслуживаю одну очень необычную вечеринку. Один тип летал в Скеттис, и его сбила чудовищная калири. У него тяжелый перелом ноги.$b$bОни заказали особое блюдо для вечеринки по случаю его выздоровления – похлебку из калири.$b$bЯ готов ссудить тебе мой кухонный котелок, так что можешь припасти немного похлебки для меня. Сам рецепт несложен, но тебе придется добыть крылышко гигантской калири и несколько готовых котлет из прыгуаны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Скалл из Нижнего Города просит вас приготовить похлебку из калири в его кухонном котелке. По выполнении вернитесь к нему.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какой восхитительный аромат! Неужто наяву?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скаллу в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11378,'У моих клиентов вкусы – от самых простецких до самых экзотических. А иногда им желательна совершенно экзотическая вещь для самых простецких целей.$B$BНапример, последний заказ. Мой клиент, пожелавший остаться неизвестным, желает получить голову Охотника Вечности, дабы повесить ее на стене у себя дома.$B$B$C, не удастся ли вам найти способ вернуться в прошлое в старые Предгорья Хилсбрада и добыть искомую голову для моего клиента – любителя охотничьих трофеев?','Торговец ветром Зерим просит вас добыть для него голову Охотника Вечности. Доставьте ее ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.','Я вижу, ты $Gвернулся:вернулась; в настоящее время $Gцелым:целой; и $Gневредимым:невредимой;.$B$B<Торговец ветром оглядывается.>$B$BНе похоже, что что-то изменилось. Но опять же, откуда мне знать?$B$BЭто хороший разрез, мой клиент будет доволен. Вот ваша награда.$B$BПриходите завтра, и у меня будет еще одна просьба для вас, чтобы выполнить.','Голова охотника эпохи... как можно прийти к решению, что они хотят, чтобы он был установлен на их стене?$B$BИ даже тогда, чтобы самому не охотиться на зверя, что говорят своим друзьям, когда спрашивают, как прошел бой?$B$BНаверное, он соврет.','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У моих клиентов вкусы – от самых простецких до самых экзотических. А иногда им желательна совершенно экзотическая вещь для самых простецких целей.$B$BНапример, последний заказ. Мой клиент, пожелавший остаться неизвестным, желает получить голову Охотника Вечности, дабы повесить ее на стене у себя дома.$B$B$C, не удастся ли вам найти способ вернуться в прошлое в старые Предгорья Хилсбрада и добыть искомую голову для моего клиента – любителя охотничьих трофеев?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торговец ветром Зерим просит вас добыть для него голову Охотника Вечности. Доставьте ее ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я вижу, ты $Gвернулся:вернулась; в настоящее время $Gцелым:целой; и $Gневредимым:невредимой;.$B$B<Торговец ветром оглядывается.>$B$BНе похоже, что что-то изменилось. Но опять же, откуда мне знать?$B$BЭто хороший разрез, мой клиент будет доволен. Вот ваша награда.$B$BПриходите завтра, и у меня будет еще одна просьба для вас, чтобы выполнить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Голова охотника эпохи... как можно прийти к решению, что они хотят, чтобы он был установлен на их стене?$B$BИ даже тогда, чтобы самому не охотиться на зверя, что говорят своим друзьям, когда спрашивают, как прошел бой?$B$BНаверное, он соврет.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11379,'Очень горячая похлебка','Я пытаюсь изобрести что-нибудь такое, чтобы уж вштыривало, так вштыривало. Но, честно говоря, я уже не тот гоблин, что прежде. Я утратил вкус к приключениям.$b$bНо ты напоминаешь мне меня в юности. Тогда я готов был завоевать весь мир с мечом в одной руке и сковородкой в другой.$b$bВозьми мой любимый кухонный котелок и ступай в Острогорье. Брось туда немного ребрышек и поджаристых змеек – заранее приготовленных ради аромата – и свари их над трупом демона Бездны – на свете нет ничего горячее, чтобы сварить такую похлебку.','Скалл из Нижнего Города просит вас приготовить немного невероятной демонической похлебки в его кухонном котелке. Вернитесь, когда приготовите.','Ну, как, удался мой экспериментик?','Вернитесь к Скаллу в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очень горячая похлебка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я пытаюсь изобрести что-нибудь такое, чтобы уж вштыривало, так вштыривало. Но, честно говоря, я уже не тот гоблин, что прежде. Я утратил вкус к приключениям.$b$bНо ты напоминаешь мне меня в юности. Тогда я готов был завоевать весь мир с мечом в одной руке и сковородкой в другой.$b$bВозьми мой любимый кухонный котелок и ступай в Острогорье. Брось туда немного ребрышек и поджаристых змеек – заранее приготовленных ради аромата – и свари их над трупом демона Бездны – на свете нет ничего горячее, чтобы сварить такую похлебку.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Скалл из Нижнего Города просит вас приготовить немного невероятной демонической похлебки в его кухонном котелке. Вернитесь, когда приготовите.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как, удался мой экспериментик?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скаллу в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11380,'Мания','Если хочешь знать, по мне так мои припасы первый сорт, но вот приходит ко мне некто и желает странного: манаягодной услады.$b$bУвы, манаягоды растут только в заповедниках Пустоверти. Даже не пытайся искать вокруг Штормового утеса – даром время потратишь, там все обобрали.$b$bЯ могу доверить сбор лучших ягод только тому, кто сведущ в кулинарии, так что не подведи меня!','Скалл из Нижнего Города просит вас принести 15 манаягод из заповедников Пустоверти.','Ну как, повезло?','Вернитесь к Скаллу в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если хочешь знать, по мне так мои припасы первый сорт, но вот приходит ко мне некто и желает странного: манаягодной услады.$b$bУвы, манаягоды растут только в заповедниках Пустоверти. Даже не пытайся искать вокруг Штормового утеса – даром время потратишь, там все обобрали.$b$bЯ могу доверить сбор лучших ягод только тому, кто сведущ в кулинарии, так что не подведи меня!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Скалл из Нижнего Города просит вас принести 15 манаягод из заповедников Пустоверти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну как, повезло?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скаллу в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11381,'Супчик для души','В воздухе пахнет смертью. Никогда я не имел столько заказов на мой замечательный супчик – он поднимает дух и утешает душу.$b$bА собрата-повара я узнаю издалека! Не хочешь ли мне помочь – а выручку поделим! $b$bВот, бери мой кухонный котелок, бери мясо копытня, и я открою тебе один маленький секрет. Знаешь, отчего мой супчик так ублажает душу? Не из-за куриного бульона – я варю его в Землях Предков в Награнде, дабы он впитывал духовность!','Скалл из Нижнего Города просит вас приготовить суп предков в его кухонном котелке. По выполнении вернитесь к нему.','Судя по запаху – чудесный суп предков, не будь я Скалл! Добавить щепотку перчика – и готово.$B$BКак и обещал, вот твоя доля. И поскольку ты проделал такую славную работу, я добавлю туда немножко своих собственных специй.','Что за божественный запах?','Вернитесь к Скаллу в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Супчик для души',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В воздухе пахнет смертью. Никогда я не имел столько заказов на мой замечательный супчик – он поднимает дух и утешает душу.$b$bА собрата-повара я узнаю издалека! Не хочешь ли мне помочь – а выручку поделим! $b$bВот, бери мой кухонный котелок, бери мясо копытня, и я открою тебе один маленький секрет. Знаешь, отчего мой супчик так ублажает душу? Не из-за куриного бульона – я варю его в Землях Предков в Награнде, дабы он впитывал духовность!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Скалл из Нижнего Города просит вас приготовить суп предков в его кухонном котелке. По выполнении вернитесь к нему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Судя по запаху – чудесный суп предков, не будь я Скалл! Добавить щепотку перчика – и готово.$B$BКак и обещал, вот твоя доля. И поскольку ты проделал такую славную работу, я добавлю туда немножко своих собственных специй.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что за божественный запах?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Скаллу в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11382,'Торговец ветром Зерим просит вас добыть песочные часы Эонуса. Доставьте их ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.','Странно, что песок в этой штуке все еще падает вверх. Я думаю, что со всей возможной поспешностью доставлю его новому владельцу.$B$BЯ благодарю вас за хорошо выполненную работу, |3-6($C). Вы, конечно, заработали свои комиссионные.$B$BПриходите завтра, и у меня будет еще одна просьба для вас, чтобы выполнить.','На твоем месте я был бы очень осторожен с путешествиями во времени. Вы же не хотите случайно сделать что-то, например, убить одного из своих предков, а затем случайно стереть себя из настоящего!','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торговец ветром Зерим просит вас добыть песочные часы Эонуса. Доставьте их ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Странно, что песок в этой штуке все еще падает вверх. Я думаю, что со всей возможной поспешностью доставлю его новому владельцу.$B$BЯ благодарю вас за хорошо выполненную работу, |3-6($C). Вы, конечно, заработали свои комиссионные.$B$BПриходите завтра, и у меня будет еще одна просьба для вас, чтобы выполнить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','На твоем месте я был бы очень осторожен с путешествиями во времени. Вы же не хотите случайно сделать что-то, например, убить одного из своих предков, а затем случайно стереть себя из настоящего!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11383,'Ловчий Пустоты Ма\'дуун хочет, чтобы вы убили 4 повелителей временных разломов. Вернитесь к нему в Нижний Город Шаттрата за наградой, когда они будут убиты.','Я чувствую не все повелители разломов ещё мертвы. Вернись когда сделаешь, $C.','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ловчий Пустоты Ма\'дуун хочет, чтобы вы убили 4 повелителей временных разломов. Вернитесь к нему в Нижний Город Шаттрата за наградой, когда они будут убиты.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я чувствую не все повелители разломов ещё мертвы. Вернись когда сделаешь, $C.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11384,'Не так давно со мной связался калдорайский друид по одному щекотливому дельцу. И отвалит она за работу, конечно же, кучу золота!$B$BСдается, что силы Дарнаса намерены возродить ходячее древо тайной магии, известное под именем Узлодревень. Это гигантское дерево не то свихнулось, не то подверглось порче, точно сказать не могу, но найдете вы его в Ботанике в Крепости Бурь.$B$BОна сказала, что им всего-то надо маленький отросточек от него, чтобы вырастить древо заново.','Торговец ветром Зерим просит вас добыть отросток Узлодревня. Доставьте его ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.','Ах, так вы добыли его! Какой маленький. И все же, когда друиды закончат свое дело – а я слышал, что процесс займет очень много времени – Узлодревень вырастет заново.$B$BА вот и обещанная награда.$B$BПриходите утром – у меня будет для вас новое дельце.','Вы сбились с пути и не нашли Ботанику? Нет. Ее не заметить нельзя... Это же в Крепости Бурь на восточном краю Пустоверти.','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не так давно со мной связался калдорайский друид по одному щекотливому дельцу. И отвалит она за работу, конечно же, кучу золота!$B$BСдается, что силы Дарнаса намерены возродить ходячее древо тайной магии, известное под именем Узлодревень. Это гигантское дерево не то свихнулось, не то подверглось порче, точно сказать не могу, но найдете вы его в Ботанике в Крепости Бурь.$B$BОна сказала, что им всего-то надо маленький отросточек от него, чтобы вырастить древо заново.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торговец ветром Зерим просит вас добыть отросток Узлодревня. Доставьте его ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ах, так вы добыли его! Какой маленький. И все же, когда друиды закончат свое дело – а я слышал, что процесс займет очень много времени – Узлодревень вырастет заново.$B$BА вот и обещанная награда.$B$BПриходите утром – у меня будет для вас новое дельце.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы сбились с пути и не нашли Ботанику? Нет. Ее не заметить нельзя... Это же в Крепости Бурь на восточном краю Пустоверти.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11385,'Ветер нашептал Ма\'дууну, что заклинатели из военного подразделения под названием Солнечные охотники должны быть убиты непременно сегодня.$B$BИх можно найти в Ботанике в Крепости Бурь.$B$BХочешь получить награду – убей заклинателей.','Ловчий Пустоты Ма\'дуун хочет, чтобы вы убили 6 солнцеловов-чаротворцев. Вернитесь к нему в Нижний Город Шаттрата, когда перебьете их, чтобы забрать награду.','И теперь они мертвы. И тот кто говорит со мной через Пустоту, тоже будет доволен, вы заработали награду.$B$BПриходи завтра и ветра снова будут говорить с Мадууном.','О чем нам говорить, когда еще не все заклинатели мертвы?','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ветер нашептал Ма\'дууну, что заклинатели из военного подразделения под названием Солнечные охотники должны быть убиты непременно сегодня.$B$BИх можно найти в Ботанике в Крепости Бурь.$B$BХочешь получить награду – убей заклинателей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ловчий Пустоты Ма\'дуун хочет, чтобы вы убили 6 солнцеловов-чаротворцев. Вернитесь к нему в Нижний Город Шаттрата, когда перебьете их, чтобы забрать награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И теперь они мертвы. И тот кто говорит со мной через Пустоту, тоже будет доволен, вы заработали награду.$B$BПриходи завтра и ветра снова будут говорить с Мадууном.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О чем нам говорить, когда еще не все заклинатели мертвы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11386,'Я всегда думал, что Паталеон Вычислитель пользуется магией, чтобы передавать свой образ в Запределье. Очевидно, я ошибался.$B$BОдин из моих клиентов сказал, что этот проклятый эльф крови пользуется механическим прибором для связи с руководителями особых проектов принца Кель\'таса. Насколько я понимаю, он забрал его у одного из отступников из братства Заксис в Пустоверти.$B$BМой клиент желает получить этот прибор. Не желаешь ли ты нанести визит Паталеону? Его можно найти в Механаре, в Крепости Бурь.','Торговец ветром Зерим просит вас добыть проектор Паталеона. Доставьте его ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.','Технология проекции сама по себе не сложна, но мощность этой модели – настоящий прорыв!','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я всегда думал, что Паталеон Вычислитель пользуется магией, чтобы передавать свой образ в Запределье. Очевидно, я ошибался.$B$BОдин из моих клиентов сказал, что этот проклятый эльф крови пользуется механическим прибором для связи с руководителями особых проектов принца Кель\'таса. Насколько я понимаю, он забрал его у одного из отступников из братства Заксис в Пустоверти.$B$BМой клиент желает получить этот прибор. Не желаешь ли ты нанести визит Паталеону? Его можно найти в Механаре, в Крепости Бурь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торговец ветром Зерим просит вас добыть проектор Паталеона. Доставьте его ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Технология проекции сама по себе не сложна, но мощность этой модели – настоящий прорыв!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11387,'В Механаре есть механические создания которые Ма\'дууну поручено разобрать.$B$BОтправляйся в Крепость Бурь, найди разрушителей Бурегорна и разрушь их.$B$BПотом можешь вернуться за наградой.','Ловчий Пустоты Ма\'дуун хочет, чтобы вы уничтожили 5 разрушителей Бурегорна. Вернитесь к нему в Нижний Город Шаттрата, когда перебьете их, чтобы забрать награду.','Ма\'дууну нравятся боевые механизмы – они не такие непредсказуемые, как органические создания.$B$BНаграда твоя.$B$BВозвращайся утром, и ветер нашепчет Ма\'дууну что-нибудь еще.','<Преследователь пустоты смотрит в явном замешательстве.>$B$BЕще не все разрушители уничтожены.','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В Механаре есть механические создания которые Ма\'дууну поручено разобрать.$B$BОтправляйся в Крепость Бурь, найди разрушителей Бурегорна и разрушь их.$B$BПотом можешь вернуться за наградой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ловчий Пустоты Ма\'дуун хочет, чтобы вы уничтожили 5 разрушителей Бурегорна. Вернитесь к нему в Нижний Город Шаттрата, когда перебьете их, чтобы забрать награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ма\'дууну нравятся боевые механизмы – они не такие непредсказуемые, как органические создания.$B$BНаграда твоя.$B$BВозвращайся утром, и ветер нашепчет Ма\'дууну что-нибудь еще.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Преследователь пустоты смотрит в явном замешательстве.>$B$BЕще не все разрушители уничтожены.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11388,'Нынешний клиент хочет получить нечто воистину необычное.$B$BЕсть такой предвестник Скайрисс, слуга древних богов. Также говорят, что у него есть большой свиток, в котором содержатся их указания насчет того, как ему повелевать жизнью во вселенной от их имени.$B$BМой нынешний клиент желает заполучить этот свиток, хотя он – или она – даже прочесть его не сможет.$B$BТак что не будете ли любезны отправиться в Крепость Бурь в Аркатрац и добыть его для меня? Ну, по рукам, |3-6($c)?','Торговец ветром Зерим просит вас добыть свиток Скайрисса. Доставьте его ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.','Я не смею прикасаться к свитку, иначе рискну быть замеченным Старыми Богами. Один из моих помощников займется его доставкой.$B$BВы более чем заработали свою награду, |3-6($C), и я желаю вам удачи во всех известных мирах.$B$BВозвращайся завтра и у меня будет еще одна просьба для вас.','Должно быть, очень опасно вмешиваться непосредственно в дела Древних Богов.$B$BЛучше ты, чем я!','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нынешний клиент хочет получить нечто воистину необычное.$B$BЕсть такой предвестник Скайрисс, слуга древних богов. Также говорят, что у него есть большой свиток, в котором содержатся их указания насчет того, как ему повелевать жизнью во вселенной от их имени.$B$BМой нынешний клиент желает заполучить этот свиток, хотя он – или она – даже прочесть его не сможет.$B$BТак что не будете ли любезны отправиться в Крепость Бурь в Аркатрац и добыть его для меня? Ну, по рукам, |3-6($c)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торговец ветром Зерим просит вас добыть свиток Скайрисса. Доставьте его ему в Нижний Город Шаттрата и получите награду.$B$BЭто задание выполняется только в режиме героической сложности.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я не смею прикасаться к свитку, иначе рискну быть замеченным Старыми Богами. Один из моих помощников займется его доставкой.$B$BВы более чем заработали свою награду, |3-6($C), и я желаю вам удачи во всех известных мирах.$B$BВозвращайся завтра и у меня будет еще одна просьба для вас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Должно быть, очень опасно вмешиваться непосредственно в дела Древних Богов.$B$BЛучше ты, чем я!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11389,'Часовые Аркатраца вышли из строя. Заключенные взбунтовались, а часовые нападают на тех, кто бы мог помочь.$B$BМа\'дуун слышит шепот ветров Пустоты. Шепот велит уничтожить часовых.$B$BСделай это – и сегодняшняя награда твоя.','Ловчий Пустоты Ма\'дуун хочет, чтобы вы навсегда деактивировали 5 часовых Аркатраца. Вернитесь к нему в Нижний Город Шаттрата, когда выполните задание, чтобы забрать награду.','Раз стражи уничтожены, то возможно, Наару попросят консорциум заменить их? Ма\'дуун не знает и не ему все равно.$B$BВы заработали награду.$B$BПриходи завтра и ветра снова будут говорить с Ма\'дууном.','Вы не знаете, как добраться до Крепости Бурь и Аркатраца? На восток через Пустоверть, а затем взлетайте или падайте, выбор за вами.','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Часовые Аркатраца вышли из строя. Заключенные взбунтовались, а часовые нападают на тех, кто бы мог помочь.$B$BМа\'дуун слышит шепот ветров Пустоты. Шепот велит уничтожить часовых.$B$BСделай это – и сегодняшняя награда твоя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ловчий Пустоты Ма\'дуун хочет, чтобы вы навсегда деактивировали 5 часовых Аркатраца. Вернитесь к нему в Нижний Город Шаттрата, когда выполните задание, чтобы забрать награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Раз стражи уничтожены, то возможно, Наару попросят консорциум заменить их? Ма\'дуун не знает и не ему все равно.$B$BВы заработали награду.$B$BПриходи завтра и ветра снова будут говорить с Ма\'дууном.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы не знаете, как добраться до Крепости Бурь и Аркатраца? На восток через Пустоверть, а затем взлетайте или падайте, выбор за вами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11390,'У меня есть ветролет!','Ну, и чего ты ждешь? Работы невпроворот!$B$BВот ключи от ветролета. Хватай три мешка с реликвиями и вези их на платформы к северу и югу от Стальных ворот. Я отмечу на карте их местоположение.$B$BДа поторопись! У нас нет времени!','Главный археолог Стальных ворот просит вас отвезти 3 мешка с реликвиями из раскопа на платформы к северу и югу от Стальных ворот.$B$BДля этого вам надо будет воспользоваться погрузочным крюком ветролета.$B$BВыполнив задание, вернитесь к главному археологу.','А? Ты $Gзакончил:закончила; со всей этой перевозкой?','Вернитесь к главному археологу Стальных ворот к Стальным воротам, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','У меня есть ветролет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, и чего ты ждешь? Работы невпроворот!$B$BВот ключи от ветролета. Хватай три мешка с реликвиями и вези их на платформы к северу и югу от Стальных ворот. Я отмечу на карте их местоположение.$B$BДа поторопись! У нас нет времени!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Главный археолог Стальных ворот просит вас отвезти 3 мешка с реликвиями из раскопа на платформы к северу и югу от Стальных ворот.$B$BДля этого вам надо будет воспользоваться погрузочным крюком ветролета.$B$BВыполнив задание, вернитесь к главному археологу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А? Ты $Gзакончил:закончила; со всей этой перевозкой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному археологу Стальных ворот к Стальным воротам, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11391,'Патрулирование Стальных Ворот','А? Хочешь еще поработать?$B$BНу ладно, держи ключи. Таскать сегодня ничего не надо, так что просто смотри по сторонам – не заметишь ли чего подозрительного. $B$BЯ прикрутил к машине парочку ракет и пулемет – на всякий случай.','Теперь вы лучший пилот Стальных ворот, и главный археолог Стальных ворот поручил вам патрулировать раскопки.$B$BОтразите нападение агрессивных существ, после чего вернитесь к главному археологу.','Хорошо стреляешь! Сразу видно – профессионал.$B$BВот твоя доля. Приходи завтра за следующим заданием, ладно?','Горгульи ?! Я их там видел! Ты обо всех $Gпозаботился:позаботилась;?$B$BЧто ждет мир, если дварф не может даже копать будучи атакованным.','Вернитесь к главному археологу Стальных ворот к Стальным воротам, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Патрулирование Стальных Ворот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А? Хочешь еще поработать?$B$BНу ладно, держи ключи. Таскать сегодня ничего не надо, так что просто смотри по сторонам – не заметишь ли чего подозрительного. $B$BЯ прикрутил к машине парочку ракет и пулемет – на всякий случай.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Теперь вы лучший пилот Стальных ворот, и главный археолог Стальных ворот поручил вам патрулировать раскопки.$B$BОтразите нападение агрессивных существ, после чего вернитесь к главному археологу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошо стреляешь! Сразу видно – профессионал.$B$BВот твоя доля. Приходи завтра за следующим заданием, ладно?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Горгульи ?! Я их там видел! Ты обо всех $Gпозаботился:позаботилась;?$B$BЧто ждет мир, если дварф не может даже копать будучи атакованным.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к главному археологу Стальных ворот к Стальным воротам, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11392,'Вызов Всадника без головы','Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...','Принесите мрачную свечу к груде рыхлой вывороченной почвы.','Вернитесь на рыхлую вывороченную почву у Монастыря Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов Всадника без головы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мрачную свечу к груде рыхлой вывороченной почвы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на рыхлую вывороченную почву у Монастыря Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11393,'Куда пропал исследователь Джарен?','$n! Мой возлюбленный, Джарен, отправился на запад вместе с маленьким отрядом исследователей, которые хотели проверить слухи об артефактах на Берегу Стылой Межи. Но я слышала, что там водятся мурлоки, и потому боюсь даже предполагать, что могло случиться с моим любимым. $B$BТы ведь не откажешься узнать, все ли у него в порядке? К пляжу ведет юго-западная дорога, но она не безопасна – рядом с ней по лесу бродят ворги и прочие опасные твари.','Надзирательница Ирена Каменная Мантия попросила вас отыскать ее суженого, исследователя Джарена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Куда пропал исследователь Джарен?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n! Мой возлюбленный, Джарен, отправился на запад вместе с маленьким отрядом исследователей, которые хотели проверить слухи об артефактах на Берегу Стылой Межи. Но я слышала, что там водятся мурлоки, и потому боюсь даже предполагать, что могло случиться с моим любимым. $B$BТы ведь не откажешься узнать, все ли у него в порядке? К пляжу ведет юго-западная дорога, но она не безопасна – рядом с ней по лесу бродят ворги и прочие опасные твари.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Надзирательница Ирена Каменная Мантия попросила вас отыскать ее суженого, исследователя Джарена.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11394,'Думаешь, мурлоки – самые вонючие существа?','Вообще-то, я приехал сюда для того, чтобы проверить слухи о погребенных здесь артефактах. Я слышал, что на побережье встречаются мурлоки, но даже не мог себе представить, с чем мне предстоит столкнуться. $B$B<Исследователь осторожно высовывает голову из-за дерева и оглядывается по сторонам.>$B$BЗдесь повсюду солдаты Плети, и они что-то делают с мурлоками и прочими тварями, превращая их в ходячих мертвецов!$B$B$C, мне кажется, мы должны что-то предпринять. Как ты думаешь, тебе по плечу победить несколько солдат Плети?','Исследователь Джарен поручил вам убить 15 любых солдат Плети, которые встретятся вам вдоль Берега Стылой Межи. Когда вы выполните это задание, вернитесь к нему.','<Джарен очень рад вашим успехам, но старается выражать свои эмоции как можно тише.>$B$BТы $Gмолодец:умница;, $N! Правда, твои доспехи перепачканы в слизи. Может быть, тебе сходить искупаться в проливе? Вода там холодная, но зато ты быстро смоешь с себя эту пакость.','Не знаю, $C, похоже, ты их еще не $Gуничтожил:уничтожила;.','Вернитесь к исследователю Джарену на Берег Стылой Межи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Думаешь, мурлоки – самые вонючие существа?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вообще-то, я приехал сюда для того, чтобы проверить слухи о погребенных здесь артефактах. Я слышал, что на побережье встречаются мурлоки, но даже не мог себе представить, с чем мне предстоит столкнуться. $B$B<Исследователь осторожно высовывает голову из-за дерева и оглядывается по сторонам.>$B$BЗдесь повсюду солдаты Плети, и они что-то делают с мурлоками и прочими тварями, превращая их в ходячих мертвецов!$B$B$C, мне кажется, мы должны что-то предпринять. Как ты думаешь, тебе по плечу победить несколько солдат Плети?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследователь Джарен поручил вам убить 15 любых солдат Плети, которые встретятся вам вдоль Берега Стылой Межи. Когда вы выполните это задание, вернитесь к нему.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Джарен очень рад вашим успехам, но старается выражать свои эмоции как можно тише.>$B$BТы $Gмолодец:умница;, $N! Правда, твои доспехи перепачканы в слизи. Может быть, тебе сходить искупаться в проливе? Вода там холодная, но зато ты быстро смоешь с себя эту пакость.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не знаю, $C, похоже, ты их еще не $Gуничтожил:уничтожила;.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к исследователю Джарену на Берег Стылой Межи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11395,'Устройство Плети','В когтях у только что убитого вами существа Плети оказалось устройство, инкрустированное драгоценными камнями, которые очень похожи на те, что украшают вершину смертоносных кристаллов.$B$BИсследователю Джарену непременно захочется изучить этот прибор.','Отнесите устройство Плети исследователю Джарену на Берег Стылой Межи.','Я знаю, что это! $N, с помощью этого прибора можно управлять смертоносными кристаллами!$B$BСпорим на что угодно, эта штука может отключить окружающие их силовые поля. Хмм.$B$B<Исследователь смотрит на вас в задумчивости, прикидывая, справитесь ли вы с прибором.>','Какое странное устройство! Дай-ка я на него взгляну...','Вернитесь к исследователю Джарену на Берег Стылой Межи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Устройство Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В когтях у только что убитого вами существа Плети оказалось устройство, инкрустированное драгоценными камнями, которые очень похожи на те, что украшают вершину смертоносных кристаллов.$B$BИсследователю Джарену непременно захочется изучить этот прибор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите устройство Плети исследователю Джарену на Берег Стылой Межи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знаю, что это! $N, с помощью этого прибора можно управлять смертоносными кристаллами!$B$BСпорим на что угодно, эта штука может отключить окружающие их силовые поля. Хмм.$B$B<Исследователь смотрит на вас в задумчивости, прикидывая, справитесь ли вы с прибором.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какое странное устройство! Дай-ка я на него взгляну...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к исследователю Джарену на Берег Стылой Межи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11396,'Отключи защитное поле','Взгляни вот на эту кнопку сбоку пульта. Могу поспорить, если ты нажмешь на нее в непосредственной близости от смертоносных кристаллов, ты сможешь отключить защитное поле. Затем тебе останется только уничтожить кристалл до того, как защита будет восстановлена.$B$BЧто скажешь, $n? Справишься? Гарантирую, щедрая награда за уничтожение кристаллов тебе обеспечена. $B$BЭто меньшее, что мы можем сделать для того, чтобы предотвратить размножение Плети.','Исследователь Джарен поручил вам уничтожить 3 смертоносных кристалла.','Не знаю, $N. Я думаю, тебе нужно уничтожить еще несколько.','Вернитесь к исследователю Джарену на Берег Стылой Межи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отключи защитное поле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взгляни вот на эту кнопку сбоку пульта. Могу поспорить, если ты нажмешь на нее в непосредственной близости от смертоносных кристаллов, ты сможешь отключить защитное поле. Затем тебе останется только уничтожить кристалл до того, как защита будет восстановлена.$B$BЧто скажешь, $n? Справишься? Гарантирую, щедрая награда за уничтожение кристаллов тебе обеспечена. $B$BЭто меньшее, что мы можем сделать для того, чтобы предотвратить размножение Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследователь Джарен поручил вам уничтожить 3 смертоносных кристалла.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не знаю, $N. Я думаю, тебе нужно уничтожить еще несколько.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к исследователю Джарену на Берег Стылой Межи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11397,'Думаешь, мурлоки – самые вонючие существа?','Ходили слухи, что в этом месте видели солдат Плети – поэтому-то я сюда и приехала. Признаться, я ожидала встретить только мурлоков на побережье, и даже не могла себе представить, с чем мне предстоит столкнуться. $B$BЗдесь повсюду солдаты Плети, и они что-то делают с мурлоками и прочими тварями, превращая их в ходячих мертвецов!$B$B$C, мы не можем позволить им пополнить свою армию мурлоками! К северо-западу от лагеря есть обрыв, который ведет к побережью. Посмотрим, удастся ли тебе справиться с солдатами Плети!','Аптекарь Анастасия поручила вам убить 15 любых солдат Плети, которые встретятся вам вдоль Берега Стылой Межи. Когда вы выполните это задание, вернитесь к ней в Аптекарский поселок.','Так ты несешь мне бочки или нет?','Вернитесь к аптекарю Анастасии в Аптекарский поселок, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Думаешь, мурлоки – самые вонючие существа?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходили слухи, что в этом месте видели солдат Плети – поэтому-то я сюда и приехала. Признаться, я ожидала встретить только мурлоков на побережье, и даже не могла себе представить, с чем мне предстоит столкнуться. $B$BЗдесь повсюду солдаты Плети, и они что-то делают с мурлоками и прочими тварями, превращая их в ходячих мертвецов!$B$B$C, мы не можем позволить им пополнить свою армию мурлоками! К северо-западу от лагеря есть обрыв, который ведет к побережью. Посмотрим, удастся ли тебе справиться с солдатами Плети!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аптекарь Анастасия поручила вам убить 15 любых солдат Плети, которые встретятся вам вдоль Берега Стылой Межи. Когда вы выполните это задание, вернитесь к ней в Аптекарский поселок.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так ты несешь мне бочки или нет?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Анастасии в Аптекарский поселок, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11398,'Устройство Плети','В когтях у только что убитого вами существа Плети оказалось устройство, инкрустированное драгоценными камнями, которые очень похожи на те, что украшают вершину смертоносных кристаллов.$B$BАптекарю Анастасии непременно захочется изучить этот прибор.','Отнесите устройство Плети аптекарю Анастасии в Аптекарский поселок.','Какое странное устройство! Дай-ка я на него взгляну...','Вернитесь к аптекарю Анастасии в Аптекарский поселок, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Устройство Плети',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В когтях у только что убитого вами существа Плети оказалось устройство, инкрустированное драгоценными камнями, которые очень похожи на те, что украшают вершину смертоносных кристаллов.$B$BАптекарю Анастасии непременно захочется изучить этот прибор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите устройство Плети аптекарю Анастасии в Аптекарский поселок.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Какое странное устройство! Дай-ка я на него взгляну...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Анастасии в Аптекарский поселок, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11399,'Отключи защитное поле','Взгляни вот на эту кнопку сбоку пульта. Могу поспорить, если ты нажмешь на нее в непосредственной близости от смертоносных кристаллов, ты сможешь отключить защитное поле. Затем тебе останется только уничтожить кристалл до того, как защита будет восстановлена.$B$BЧто скажешь, $n? Справишься? Гарантирую, щедрая награда за уничтожение кристаллов тебе обеспечена. $B$BЭто меньшее, что мы можем сделать для того, чтобы предотвратить размножение Плети.','Аптекарь Анастасия поручила вам уничтожить 3 смертоносных кристалла.','По-моему, ты уничтожил еще не все кристаллы. Сначала выполни задание, а потом приходи за наградой.','Вернитесь к аптекарю Анастасии в Аптекарский поселок, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отключи защитное поле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Взгляни вот на эту кнопку сбоку пульта. Могу поспорить, если ты нажмешь на нее в непосредственной близости от смертоносных кристаллов, ты сможешь отключить защитное поле. Затем тебе останется только уничтожить кристалл до того, как защита будет восстановлена.$B$BЧто скажешь, $n? Справишься? Гарантирую, щедрая награда за уничтожение кристаллов тебе обеспечена. $B$BЭто меньшее, что мы можем сделать для того, чтобы предотвратить размножение Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Аптекарь Анастасия поручила вам уничтожить 3 смертоносных кристалла.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','По-моему, ты уничтожил еще не все кристаллы. Сначала выполни задание, а потом приходи за наградой.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к аптекарю Анастасии в Аптекарский поселок, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11400,'Скаковые бараны Хмельного фестиваля','Если ты покажешь этот штамп Дризу Неуклюге, начинающему наезднику на баранах, он позволит тебе купить скакового барана на Хмельном фестивале.','Покажите штамп Полу Янтарлену у входа на территорию Хмельного фестиваля в Дун Мороге.','Хорошая работа, $N ... Вы завоевали доверие пивоваров фестиваля, заработав право купить барана для верховой езды Хмельного фестиваля.','Это штамп «Почетный пивовар» уже в твоих руках?','Вернитесь к Полу Янтарлену в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скаковые бараны Хмельного фестиваля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты покажешь этот штамп Дризу Неуклюге, начинающему наезднику на баранах, он позволит тебе купить скакового барана на Хмельном фестивале.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите штамп Полу Янтарлену у входа на территорию Хмельного фестиваля в Дун Мороге.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $N ... Вы завоевали доверие пивоваров фестиваля, заработав право купить барана для верховой езды Хмельного фестиваля.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это штамп «Почетный пивовар» уже в твоих руках?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Полу Янтарлену в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11401,'Вызов всадника без головы','Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...','Принесите мрачную свечу к груде рыхлой вывороченной почвы.','Вернитесь на рыхлую вывороченную почву у Монастыря Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов всадника без головы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мрачную свечу к груде рыхлой вывороченной почвы.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на рыхлую вывороченную почву у Монастыря Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11402,'Clayton\'s Quest: Extreme!!','Clayton wants you to find and slay twenty Evil Squirrels.','Seriously, go slay those Evil Squirrels!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Clayton\'s Quest: Extreme!!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Clayton wants you to find and slay twenty Evil Squirrels.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Seriously, go slay those Evil Squirrels!',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11403,'Наконец, свободен!','Гнев был моей темницей, $n, а ты $Gосвободил:освободила; меня. Хотя я считал себя правым, душа моя ныне кровоточит от всех тех ужасов и смертей, которые обрушил я на жителей Азерота.$B$BБлагодарю тебя, что ты $gпривел:привела; меня к Свету. Да не сверну я с этого пути!$B$BОтнеси этот потрепанный молитвенник попечительнице сирот, чтобы дети узнали, что больше я их не потревожу.','Возьмите книгу Томаса Томсона и отнесите ее попечительнице сирот в маске в Дуротар, Брилл или на Площадь Соколиных Крыльев.','Что? Этот священный том когда-то принадлежал печально известному паладину альянса. Он и был всадником без головы? Означает ли это, что всадник побежден?$B$BЭто славный день, $N! Легенда о вас будет сиять очень ярко, и пусть она сияет вдвое дольше правления всадника страха.','Вернитесь к попечительнице сирот в маске.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наконец, свободен!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гнев был моей темницей, $n, а ты $Gосвободил:освободила; меня. Хотя я считал себя правым, душа моя ныне кровоточит от всех тех ужасов и смертей, которые обрушил я на жителей Азерота.$B$BБлагодарю тебя, что ты $gпривел:привела; меня к Свету. Да не сверну я с этого пути!$B$BОтнеси этот потрепанный молитвенник попечительнице сирот, чтобы дети узнали, что больше я их не потревожу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите книгу Томаса Томсона и отнесите ее попечительнице сирот в маске в Дуротар, Брилл или на Площадь Соколиных Крыльев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Этот священный том когда-то принадлежал печально известному паладину альянса. Он и был всадником без головы? Означает ли это, что всадник побежден?$B$BЭто славный день, $N! Легенда о вас будет сиять очень ярко, и пусть она сияет вдвое дольше правления всадника страха.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к попечительнице сирот в маске.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11404,'Вызов Всадника без головы','Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...','Принесите мрачную свечу к груде рыхлой вывороченной почвы.','Ты поставишь свечу и пробудишь Всадника без головы от его обреченного покоя?','Вернитесь на рыхлую вывороченную почву у Монастыря Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов Всадника без головы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мрачную свечу к груде рыхлой вывороченной почвы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты поставишь свечу и пробудишь Всадника без головы от его обреченного покоя?',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на рыхлую вывороченную почву у Монастыря Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11405,'Вызов Всадника без головы','Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...','Принесите мрачную свечу к груде рыхлой вывороченной почвы.','Ты поставишь свечу и пробудишь Всадника без головы от его обреченного покоя?','Эта земля совсем свежая. В ней ползают черви, пытаясь спрятаться поглубже.','Вернитесь на рыхлую вывороченную почву у Монастыря Алого ордена.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вызов Всадника без головы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это святилище тыквы озаряет множество мрачных свечей, и тыква насмешливо ухмыляется...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите мрачную свечу к груде рыхлой вывороченной почвы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты поставишь свечу и пробудишь Всадника без головы от его обреченного покоя?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эта земля совсем свежая. В ней ползают черви, пытаясь спрятаться поглубже.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь на рыхлую вывороченную почву у Монастыря Алого ордена.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11406,'Все должно быть готово','Скоро на север будут посланы несколько исследовательских отрядов, и капитан Адамс рассчитывает, что строительство крепости Вилдервар будет завершено к тому моменту. Разведчикам и ремесленникам было поручено подготовить обмундирование и припасы для наших людей, которые отправятся покорять скалы. $B$BКапитан известен своим буйным нравом, так что я хочу послать кого-нибудь вперед проверить ход подготовки. Крепость Вилдервар находится далеко на северо-востоке, за Скорном, рядом с Седыми холмами. Найди там Гила Гризерта и убедись, что все готово.','Поговорите с Гилом Гризертом в крепости Вилдервар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Все должно быть готово',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Скоро на север будут посланы несколько исследовательских отрядов, и капитан Адамс рассчитывает, что строительство крепости Вилдервар будет завершено к тому моменту. Разведчикам и ремесленникам было поручено подготовить обмундирование и припасы для наших людей, которые отправятся покорять скалы. $B$BКапитан известен своим буйным нравом, так что я хочу послать кого-нибудь вперед проверить ход подготовки. Крепость Вилдервар находится далеко на северо-востоке, за Скорном, рядом с Седыми холмами. Найди там Гила Гризерта и убедись, что все готово.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гилом Гризертом в крепости Вилдервар.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11407,'Пивоварня Дрона ищет зазывалу!','Ты уже всем $Gрассказал:рассказала; о Хмельном фестивале?','Вернитесь к Корту Горштейну в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пивоварня Дрона ищет зазывалу!',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже всем $Gрассказал:рассказала; о Хмельном фестивале?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Корту Горштейну в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11408,'Пивоварня Т\'чали Вуду ищет зазывалу!','Ты уже всем $Gрассказал:рассказала; о Хмельном фестивале? И, что самое главное, о чудесном тролльском пиве?','Вернитесь к Джа\'рону в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пивоварня Т\'чали Вуду ищет зазывалу!',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже всем $Gрассказал:рассказала; о Хмельном фестивале? И, что самое главное, о чудесном тролльском пиве?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джа\'рону в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11409,'А теперь гонки на баранах... Или вроде того.','У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.','Эй, не так-то плохо... Ты точно не дворф?$B$BГонок в округе хватает, и не только здесь. На Хмельном фестивале хорошие наездники на баранах в цене. Иди, найди себе работу.$B$BИ не забывай, эти бараны куплены совершенно законным путем. Помни про это.','Вернитесь к погонщику баранов Рэю на Хмельной фестиваль в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','А теперь гонки на баранах... Или вроде того.',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эй, не так-то плохо... Ты точно не дворф?$B$BГонок в округе хватает, и не только здесь. На Хмельном фестивале хорошие наездники на баранах в цене. Иди, найди себе работу.$B$BИ не забывай, эти бараны куплены совершенно законным путем. Помни про это.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к погонщику баранов Рэю на Хмельной фестиваль в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11410,'Та самая рыбка','Принесенная тобой рыба-шип подойдет в качестве наживки, но я, признаться, боюсь, что на нее клюнет настоящее чудовище! $B$BКогда я впервые забросил тут удочку Ната Пэгла с моей любимой наживкой, из воды высунулась огромная тварь с кошмарными зубами и сосульками на плавниках!$B$BЕсли бы я не обрезал леску, она утащила бы меня под лед. Нет, я не буду экспериментировать с новой наживкой, пока старина Ледяной Плавник плавает поблизости. Впрочем, если хочешь с ним повстречаться, забрось удочку в середине озера. Он не устоит перед такой рыбкой!','Кристофер Слоан из крепости Вилдервар просит вас победить Ледяного Плавника.','Наконец-то я могу рыбачить спокойно! Правда, к тому времени, как мы что-то поймаем, сюда прибудет экспедиция и заберет себе всю добычу.$B$BНо ты $Gмолодец:умница;, $N. Заходи еще, не стесняйся.','Мне не терпится опробовать новую приманку.$B$BТебе повезло с Ледяным Плавником?','Вернитесь к Кристоферу Слоану в Крепость Вилдервар, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Та самая рыбка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Принесенная тобой рыба-шип подойдет в качестве наживки, но я, признаться, боюсь, что на нее клюнет настоящее чудовище! $B$BКогда я впервые забросил тут удочку Ната Пэгла с моей любимой наживкой, из воды высунулась огромная тварь с кошмарными зубами и сосульками на плавниках!$B$BЕсли бы я не обрезал леску, она утащила бы меня под лед. Нет, я не буду экспериментировать с новой наживкой, пока старина Ледяной Плавник плавает поблизости. Впрочем, если хочешь с ним повстречаться, забрось удочку в середине озера. Он не устоит перед такой рыбкой!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Кристофер Слоан из крепости Вилдервар просит вас победить Ледяного Плавника.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то я могу рыбачить спокойно! Правда, к тому времени, как мы что-то поймаем, сюда прибудет экспедиция и заберет себе всю добычу.$B$BНо ты $Gмолодец:умница;, $N. Заходи еще, не стесняйся.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне не терпится опробовать новую приманку.$B$BТебе повезло с Ледяным Плавником?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кристоферу Слоану в Крепость Вилдервар, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11411,'Лагерь Заиндевевшего Копыта','Значит, Наник выполнил мое поручение? Но скажи мне, $N, как тебе удалось добраться сюда без его помощи? Никто не знает эти земли лучше самих таунка.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь Заиндевевшего Копыта',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Наник выполнил мое поручение? Но скажи мне, $N, как тебе удалось добраться сюда без его помощи? Никто не знает эти земли лучше самих таунка.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11413,'Кто сказал "сувениры"?','Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.$b$bПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.','Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.','Что это? Ваучер на кружку? Так ты любишь выпить? После того, как я дам тебе эту кружку, выпей! Потом еще несколько. Может быть, еще несколько после этого... А потом приходи ко мне.$B$BСлушай, я знаю, что ты когда-нибудь вернешься. Если ты хочешь выкупить билеты на Хмельный фестиваль или знаки тебе нужно будет поговорить со мной.$B$BВ любом случае, вот кружка, и не забудь поговорить со мной позже.','Что происходит? Есть что-нибудь для меня?','Вернитесь к Бликсу Чиништуксу в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кто сказал "сувениры"?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не только поим всех подряд, но и дарим пивные кружки! Красивые, памятные кружки, полученные совершенно законным образом! Вот тебе купон на такую кружку.$b$bПоговори с Бликсом рядом с лагерем Хмельного фестиваля. Он довольно странный тип, тем более, что очки эти никогда не снимает. Он и отоварит твой купон. Он же занимается прочей праздничной торговлей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отоварьте свой купон на праздничную кружку у Бликса Чиништукса в лагере Хмельного фестиваля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что это? Ваучер на кружку? Так ты любишь выпить? После того, как я дам тебе эту кружку, выпей! Потом еще несколько. Может быть, еще несколько после этого... А потом приходи ко мне.$B$BСлушай, я знаю, что ты когда-нибудь вернешься. Если ты хочешь выкупить билеты на Хмельный фестиваль или знаки тебе нужно будет поговорить со мной.$B$BВ любом случае, вот кружка, и не забудь поговорить со мной позже.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что происходит? Есть что-нибудь для меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бликсу Чиништуксу в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11414,'Братья-предатели','Дозорная Лунный Лепесток являлась мне во снах! Ее друг – и мой друг.$B$BДо последнего полнолуния я считался главным самцом в стае. Затем с севера пришел этот странный белый ворг, Гарвал, и с помощью моих бывших братьев встал во главе стаи. Но что-то в нем меня беспокоит.$B$BЕсли ты хочешь помочь мне, убей тех, кто предал меня. $B$BОдного из них зовут Бьомолф, и он охотится на северо-западе от места, которое вы называете Стальные ворота. Другой, Варг, обитает на юго-востоке, рядом с Западной башней.$B$BНо их ты не обманешь своим обличьем.','Улклык попросил вас убить воргов-предателей, Бьомолфа и Варга. Когда вы убьете их, вернитесь к нему в Вырубки в обличье ворга.$B$BЕсли вы потеряете личину ворга, возьмите другую у дозорной Лунный Лепесток.','Меня радует запах их крови на твоей морде. Братья не должны предавать друг друга.','Вернитесь к Улклыку в Вырубки, что в Ревущем фьорде. Вы должны быть в обличье ворга.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья-предатели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Дозорная Лунный Лепесток являлась мне во снах! Ее друг – и мой друг.$B$BДо последнего полнолуния я считался главным самцом в стае. Затем с севера пришел этот странный белый ворг, Гарвал, и с помощью моих бывших братьев встал во главе стаи. Но что-то в нем меня беспокоит.$B$BЕсли ты хочешь помочь мне, убей тех, кто предал меня. $B$BОдного из них зовут Бьомолф, и он охотится на северо-западе от места, которое вы называете Стальные ворота. Другой, Варг, обитает на юго-востоке, рядом с Западной башней.$B$BНо их ты не обманешь своим обличьем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Улклык попросил вас убить воргов-предателей, Бьомолфа и Варга. Когда вы убьете их, вернитесь к нему в Вырубки в обличье ворга.$B$BЕсли вы потеряете личину ворга, возьмите другую у дозорной Лунный Лепесток.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меня радует запах их крови на твоей морде. Братья не должны предавать друг друга.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Улклыку в Вырубки, что в Ревущем фьорде. Вы должны быть в обличье ворга.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11415,'Братья-предатели','Странник Туманов являлся мне во снах! Его друг – мой друг.$B$BДо последнего полнолуния я считался главным самцом в стае. Затем с севера пришел этот странный белый ворг, Гарвал, и с помощью моих бывших братьев встал во главе стаи. Но что-то в нем меня беспокоит.$B$BЕсли ты хочешь помочь мне, убей тех, кто предал меня. $B$BОдного из них зовут Бьомолф, и он охотится на северо-западе от места, которое вы, двуногие, называете Стальные ворота. Другой, Варг, обитает на юго-востоке, рядом с Западной башней.$B$BНо их ты не обманешь своим обличьем.','Улклык попросил вас убить воргов-предателей, Бьомолфа и Варга. Выполнив его просьбу, наденьте личину ворга и вернитесь к Улклыку.$B$BЕсли вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.','Меня радует запах их крови на твоей морде. Братья не должны предавать друг друга.','<Улклык негромко рычит.>\n\nБьомолф и Варг все еще живы!','Вернитесь к Улклыку в Вырубки, что в Ревущем фьорде. Вы должны быть в обличье ворга.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Братья-предатели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Странник Туманов являлся мне во снах! Его друг – мой друг.$B$BДо последнего полнолуния я считался главным самцом в стае. Затем с севера пришел этот странный белый ворг, Гарвал, и с помощью моих бывших братьев встал во главе стаи. Но что-то в нем меня беспокоит.$B$BЕсли ты хочешь помочь мне, убей тех, кто предал меня. $B$BОдного из них зовут Бьомолф, и он охотится на северо-западе от места, которое вы, двуногие, называете Стальные ворота. Другой, Варг, обитает на юго-востоке, рядом с Западной башней.$B$BНо их ты не обманешь своим обличьем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Улклык попросил вас убить воргов-предателей, Бьомолфа и Варга. Выполнив его просьбу, наденьте личину ворга и вернитесь к Улклыку.$B$BЕсли вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Меня радует запах их крови на твоей морде. Братья не должны предавать друг друга.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Улклык негромко рычит.>\n\nБьомолф и Варг все еще живы!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Улклыку в Вырубки, что в Ревущем фьорде. Вы должны быть в обличье ворга.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11416,'Глаза орлицы','Гарвал прячется под странным магическим покровом. Его невозможно увидеть, пока он сам этого не захочет. Но мы должны попытаться обойти эту защиту.$B$BГоворят, что мой старый враг, великая орлица Когтекрыл, может видеть сквозь любую магическую защиту. Если ты вырвешь ее глаза, то сможешь найти Гарвала.$B$BКогтекрыл свила гнездо у подножия водопада, к юго-западу от врайкульского поселения, которое называют Скорн. Если ты дотронешься до ее яиц, она спустится с небес, чтобы убить тебя. $B$BВырви ее глаза!','Улклык поручил вам вырвать глаза великой орлицы. Вернитесь к нему в Вырубки, когда это задание будет выполнено.$B$BЕсли вы потеряете личину ворга, вернитесь к дозорной Лунный Лепесток, и она выдаст вам новую.','<Улклык громко рычит, радуясь вашей победе над старым врагом.>$B$BЭта победа делает тебе честь. Хотел бы я лично сомкнуть свои зубы на ее шее!$B$BНо ее смерть не должна стать напрасной. Скорее, съешь ее глаза!','Ты $Gпринес:принесла; глаза орлицы?','Вернитесь к Улклыку в Вырубки, что в Ревущем фьорде. Вы должны быть в обличье ворга.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаза орлицы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гарвал прячется под странным магическим покровом. Его невозможно увидеть, пока он сам этого не захочет. Но мы должны попытаться обойти эту защиту.$B$BГоворят, что мой старый враг, великая орлица Когтекрыл, может видеть сквозь любую магическую защиту. Если ты вырвешь ее глаза, то сможешь найти Гарвала.$B$BКогтекрыл свила гнездо у подножия водопада, к юго-западу от врайкульского поселения, которое называют Скорн. Если ты дотронешься до ее яиц, она спустится с небес, чтобы убить тебя. $B$BВырви ее глаза!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Улклык поручил вам вырвать глаза великой орлицы. Вернитесь к нему в Вырубки, когда это задание будет выполнено.$B$BЕсли вы потеряете личину ворга, вернитесь к дозорной Лунный Лепесток, и она выдаст вам новую.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Улклык громко рычит, радуясь вашей победе над старым врагом.>$B$BЭта победа делает тебе честь. Хотел бы я лично сомкнуть свои зубы на ее шее!$B$BНо ее смерть не должна стать напрасной. Скорее, съешь ее глаза!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gпринес:принесла; глаза орлицы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Улклыку в Вырубки, что в Ревущем фьорде. Вы должны быть в обличье ворга.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11417,'Глаза орлицы','Гарвал прячется под странным магическим покровом. Его невозможно увидеть, пока он сам этого не захочет. Но мы должны попытаться обойти эту защиту.$B$BГоворят, что мой старый враг, великая орлица Когтекрыл, может видеть сквозь любую магическую пелену. Если ты вырвешь ее глаза, то сможешь найти Гарвала.$B$BКогтекрыл свила гнездо у подножия водопада, к юго-западу от врайкульского поселения, которое называют Скорн. Если ты дотронешься до ее кладки, она спустится с небес, чтобы убить тебя. $B$BВырви ее глаза!','Улклык поручил вам вырвать глаза великой орлицы. Вернитесь к нему в Вырубки, когда это задание будет выполнено.$B$BЕсли вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.','Ты принес глаза орлицы?','Вернитесь к Улклыку в Вырубки, что в Ревущем фьорде. Вы должны быть в обличье ворга.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Глаза орлицы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Гарвал прячется под странным магическим покровом. Его невозможно увидеть, пока он сам этого не захочет. Но мы должны попытаться обойти эту защиту.$B$BГоворят, что мой старый враг, великая орлица Когтекрыл, может видеть сквозь любую магическую пелену. Если ты вырвешь ее глаза, то сможешь найти Гарвала.$B$BКогтекрыл свила гнездо у подножия водопада, к юго-западу от врайкульского поселения, которое называют Скорн. Если ты дотронешься до ее кладки, она спустится с небес, чтобы убить тебя. $B$BВырви ее глаза!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Улклык поручил вам вырвать глаза великой орлицы. Вернитесь к нему в Вырубки, когда это задание будет выполнено.$B$BЕсли вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес глаза орлицы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Улклыку в Вырубки, что в Ревущем фьорде. Вы должны быть в обличье ворга.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11418,'Мы зовем его Стальное Перо','Я как-то видел одного наглого гиппогрифа, который охотился прямо над крепостью. Джетан пытался его сбить, но стрелы буквально отскакивают от его оперения!$B$BМы так и прозвали его – Стальное Перо. Хотелось бы еще понять, почему он кружит рядом с крепостью Вилдервар. Ведь обычно гиппогрифы опасаются людей.$B$BИсследователь Адеран сделал для нас амулет из пера этого существа. Он утверждает, что с его помощью можно взглянуть на мир глазами гиппогрифа.','Найдите Стальное Перо, который кружит над крепостью Вилдервар, и воспользуйтесь оперенным амулетом, чтобы разгадать тайну этого загадочного гиппогрифа. Расскажите Гилу Гризерту о вашей находке.','Подействовали ли чары Адерана?','Вернитесь к Гилу Гризерту в Крепость Вилдервар, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы зовем его Стальное Перо',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я как-то видел одного наглого гиппогрифа, который охотился прямо над крепостью. Джетан пытался его сбить, но стрелы буквально отскакивают от его оперения!$B$BМы так и прозвали его – Стальное Перо. Хотелось бы еще понять, почему он кружит рядом с крепостью Вилдервар. Ведь обычно гиппогрифы опасаются людей.$B$BИсследователь Адеран сделал для нас амулет из пера этого существа. Он утверждает, что с его помощью можно взглянуть на мир глазами гиппогрифа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Стальное Перо, который кружит над крепостью Вилдервар, и воспользуйтесь оперенным амулетом, чтобы разгадать тайну этого загадочного гиппогрифа. Расскажите Гилу Гризерту о вашей находке.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Подействовали ли чары Адерана?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гилу Гризерту в Крепость Вилдервар, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11419,'Скаковые бараны Хмельного фестиваля','Если ты покажешь этот штамп Дризу Неуклюге, начинающему наезднику на баранах, он позволит тебе купить скакового барана на Хмельном фестивале.','Покажите штамп Дризу Неуклюге у входа на территорию Хмельного фестиваля в Дуротаре.','Хорошая работа, $N ... Вы завоевали доверие пивоваров фестиваля, заработав право купить барана для верховой езды Хмельного фестиваля.','Это штамп «Почетный пивовар» уже в твоих руках?','Вернитесь к Дризу Неуклюге на Свиноферму, что в Дуротаре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Скаковые бараны Хмельного фестиваля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты покажешь этот штамп Дризу Неуклюге, начинающему наезднику на баранах, он позволит тебе купить скакового барана на Хмельном фестивале.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Покажите штамп Дризу Неуклюге у входа на территорию Хмельного фестиваля в Дуротаре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $N ... Вы завоевали доверие пивоваров фестиваля, заработав право купить барана для верховой езды Хмельного фестиваля.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это штамп «Почетный пивовар» уже в твоих руках?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дризу Неуклюге на Свиноферму, что в Дуротаре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11420,'Путь к отмщению','Две недели назад нашему главному инженеру удалось захватить врайкульскую гарпунную пушку. С помощью такого оружия эти мерзавцы топили наши корабли. Изучив ее, он смог составить подробное руководство по управлению этой штуковиной. $B$BК несчастью, его похитили и отвезли к северу отсюда, в Деревню Драконьего Черепа. Когда мы нашли его, едва живого, руководства при нем не оказалось. Из последних сил он поведал, что потерял свои записи в Катакомбах Утгард, находящихся к северо-западу от Деревни Драконьего Черепа. Ты $gдолжен:должна; вернуть это руководство!','Капитан стражи Зорек из Валгарда в Ревущем фьорде поручил вам вернуть руководство по управлению гарпунной пушкой.','Вернитесь к капитану стражи Зореку в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь к отмщению',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Две недели назад нашему главному инженеру удалось захватить врайкульскую гарпунную пушку. С помощью такого оружия эти мерзавцы топили наши корабли. Изучив ее, он смог составить подробное руководство по управлению этой штуковиной. $B$BК несчастью, его похитили и отвезли к северу отсюда, в Деревню Драконьего Черепа. Когда мы нашли его, едва живого, руководства при нем не оказалось. Из последних сил он поведал, что потерял свои записи в Катакомбах Утгард, находящихся к северо-западу от Деревни Драконьего Черепа. Ты $gдолжен:должна; вернуть это руководство!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан стражи Зорек из Валгарда в Ревущем фьорде поручил вам вернуть руководство по управлению гарпунной пушкой.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану стражи Зореку в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11421,'До упора...','Прекрасно, $N! Ты $Gубил:убила; множество драконьих наездников и серьезно разозлила их предводителей.$B$B$GГотов:Готова; вернуться в Валгард и сообщить хорошие новости Зореку? А то у меня появилась совершенно безумная идея!','Горит ли Драконий Череп?','Вернитесь к лейтенанту Ледяному Молоту в Ревущий фьорд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','До упора...',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, $N! Ты $Gубил:убила; множество драконьих наездников и серьезно разозлила их предводителей.$B$B$GГотов:Готова; вернуться в Валгард и сообщить хорошие новости Зореку? А то у меня появилась совершенно безумная идея!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Горит ли Драконий Череп?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Ледяному Молоту в Ревущий фьорд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11422,'Трезубец сына','<Он царапает на камне несколько символов, которые, очевидно, обозначают трезубец, мур\'далака, разбившийся корабль и кусок сыра. Рядом с этими рисунками вы различаете грубое изображение самого себя.>$B$B<Вам не сразу удается понять, что хочет от вас старый мурлок. Очевидно, он просит принести ему трезубец с Берега Стылой Межи, но последнее изображение вас озадачивает. Наконец, вы понимаете, что мурлок имел в виду не кусок сыра, а своего сына.>$B$B<Все ясно! Видимо, его сына превратили в мур\'далака! Он хочет, чтобы вы убили его и принесли трезубец.>','Старый Ледоспин просит вас принести ему трезубец Гниложабера. Он будет ждать вас на маленьком острове возле Берега Стылой Межи.','<Старый Ледоспин внимательно окидывает вас мутным взглядом. Очевидно, он ожидает увидеть в ваших руках трезубец его сына.>','Вернитесь к Старому Ледоспину на Берег Стылой Межи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трезубец сына',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Он царапает на камне несколько символов, которые, очевидно, обозначают трезубец, мур\'далака, разбившийся корабль и кусок сыра. Рядом с этими рисунками вы различаете грубое изображение самого себя.>$B$B<Вам не сразу удается понять, что хочет от вас старый мурлок. Очевидно, он просит принести ему трезубец с Берега Стылой Межи, но последнее изображение вас озадачивает. Наконец, вы понимаете, что мурлок имел в виду не кусок сыра, а своего сына.>$B$B<Все ясно! Видимо, его сына превратили в мур\'далака! Он хочет, чтобы вы убили его и принесли трезубец.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Старый Ледоспин просит вас принести ему трезубец Гниложабера. Он будет ждать вас на маленьком острове возле Берега Стылой Межи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Старый Ледоспин внимательно окидывает вас мутным взглядом. Очевидно, он ожидает увидеть в ваших руках трезубец его сына.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Старому Ледоспину на Берег Стылой Межи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11423,'Наследие врагов','Когда наши армии пройдут по Нордсколу, наши враги познают всю горечь поражения. Их дома будут сожжены, их тела будут разлагаться под воздействием нашей чумы, и сам след их существования будет стерт с лица земли. $B$BКак историк, я беспокоюсь лишь за сохранность знаний. Скоро наши войска из Лагеря Возмездия разрушат восточный город Ниффлвар. Я слышал, что этом городе жил врайкульский бард Хельгус, автор трех книг: "Саги о близнецах", "Саги о проклятии зимы" и "Саги о валькириях". Добудь эти произведения прежде, чем Ниффлвар будет разрушен.','Отправляйтесь к северу Заставы Призрачного Клинка, в Ниффлвар, и найдите три свитка: "Сагу о проклятии зимы", "Сагу о валькириях" и "Сагу о близнецах".','Вернитесь к переписчику Сегуину на Заставу Призрачного Клинка, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наследие врагов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда наши армии пройдут по Нордсколу, наши враги познают всю горечь поражения. Их дома будут сожжены, их тела будут разлагаться под воздействием нашей чумы, и сам след их существования будет стерт с лица земли. $B$BКак историк, я беспокоюсь лишь за сохранность знаний. Скоро наши войска из Лагеря Возмездия разрушат восточный город Ниффлвар. Я слышал, что этом городе жил врайкульский бард Хельгус, автор трех книг: "Саги о близнецах", "Саги о проклятии зимы" и "Саги о валькириях". Добудь эти произведения прежде, чем Ниффлвар будет разрушен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь к северу Заставы Призрачного Клинка, в Ниффлвар, и найдите три свитка: "Сагу о проклятии зимы", "Сагу о валькириях" и "Сагу о близнецах".',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к переписчику Сегуину на Заставу Призрачного Клинка, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11424,'Заградительный холм','Во время войны моя работа значительно упрощается – подходящие части тел валяются повсюду.$B$BПравда, их не так-то легко достать. Эти яйцеголовые болваны, изобретающие новые штаммы чумы и насылающие заразу на города противников, портят большую часть материалов.$B$BОднако я знаю место, где можно достать подходящие образцы. К югу отсюда есть Заградительный холм, на котором в древности врайкулы хоронили своих павших воинов. Чума не тронула эти земли – ни наша, ни Короля-лича. Принеси мне несколько костей, и я хорошо тебе заплачу за них.','Дженни по прозвищу "Пила" просит вас принести ей 5 древних врайкульских костей оживших мертвецов с Заградительного холма, который находится к югу от Нового Агамонда.','Ну, где мои косточки?','Вернитесь к Дженни по прозвищу "Пила" в Новый Агамонд, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заградительный холм',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время войны моя работа значительно упрощается – подходящие части тел валяются повсюду.$B$BПравда, их не так-то легко достать. Эти яйцеголовые болваны, изобретающие новые штаммы чумы и насылающие заразу на города противников, портят большую часть материалов.$B$BОднако я знаю место, где можно достать подходящие образцы. К югу отсюда есть Заградительный холм, на котором в древности врайкулы хоронили своих павших воинов. Чума не тронула эти земли – ни наша, ни Короля-лича. Принеси мне несколько костей, и я хорошо тебе заплачу за них.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дженни по прозвищу "Пила" просит вас принести ей 5 древних врайкульских костей оживших мертвецов с Заградительного холма, который находится к югу от Нового Агамонда.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, где мои косточки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дженни по прозвищу "Пила" в Новый Агамонд, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11425,'Испытательное задание – Крейг','Ступай выполнять задание!','Паразиты, ненавижу!','Вернитесь к тестовой белке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Испытательное задание – Крейг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ступай выполнять задание!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Паразиты, ненавижу!',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тестовой белке.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11426,'В поисках механизма','Не волнуйся, $n, нас ждет нечто потрясающее! НЕВЕРОЯТНОЕ! Ты просто слушай меня и делай так, как я тебе скажу. $B$BСначала нам надо достать механизм, упомянутый в этом руководстве. Сдается мне, что ты с легкостью обнаружишь его у одного из врайкулов, которые управляют гарпунными пушками в Деревне Драконьего Черепа. Эти пушки стоят в восточной части деревни, на террасах больших домов.','Капитан стражи Зорек из Валгарда в Ревущем фьорде просит вас принести механизм управления гарпуном.','Потрясающе! Скоро эти макаки-переростки поплатятся за то, что встали на пути Альянса!','Вернитесь к капитану стражи Зореку в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках механизма',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не волнуйся, $n, нас ждет нечто потрясающее! НЕВЕРОЯТНОЕ! Ты просто слушай меня и делай так, как я тебе скажу. $B$BСначала нам надо достать механизм, упомянутый в этом руководстве. Сдается мне, что ты с легкостью обнаружишь его у одного из врайкулов, которые управляют гарпунными пушками в Деревне Драконьего Черепа. Эти пушки стоят в восточной части деревни, на террасах больших домов.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан стражи Зорек из Валгарда в Ревущем фьорде просит вас принести механизм управления гарпуном.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Потрясающе! Скоро эти макаки-переростки поплатятся за то, что встали на пути Альянса!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану стражи Зореку в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11427,'Познакомьтесь с лейтенантом Ледяным Молотом','Видишь эти врайкульские постройки на северо-восточных склонах? Сами врайкулы называют это место Ниффлвар. Оттуда они обстреливают гарпунами наши фрегаты.$B$BЗнаешь, что? Нам это надоело, $n. Возьми этот механизм управления гарпуном и встреться с лейтенантом Ледяным Молотом, который прячется в одной из врайкульских хижин на северо-западе Ниффлвара.$B$BКогда будешь $gготов:готова;, я посажу тебя на грифона и отправлю тебя прямо к нему!','Капитан стражи Зорек просит вас отнести механизм управления гарпуном лейтенанту Ледяному Молоту, который укрывается недалеко от Ниффлвара.','<Лейтенант Ледяной Молот забирает у вас механизм управления гарпуном.>$B$BА, подарочки!','Это еще зачем? Я что, похож на няньку?','Вернитесь к лейтенанту Ледяному Молоту на Остров Колдрос, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Познакомьтесь с лейтенантом Ледяным Молотом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Видишь эти врайкульские постройки на северо-восточных склонах? Сами врайкулы называют это место Ниффлвар. Оттуда они обстреливают гарпунами наши фрегаты.$B$BЗнаешь, что? Нам это надоело, $n. Возьми этот механизм управления гарпуном и встреться с лейтенантом Ледяным Молотом, который прячется в одной из врайкульских хижин на северо-западе Ниффлвара.$B$BКогда будешь $gготов:готова;, я посажу тебя на грифона и отправлю тебя прямо к нему!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан стражи Зорек просит вас отнести механизм управления гарпуном лейтенанту Ледяному Молоту, который укрывается недалеко от Ниффлвара.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Лейтенант Ледяной Молот забирает у вас механизм управления гарпуном.>$B$BА, подарочки!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это еще зачем? Я что, похож на няньку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Ледяному Молоту на Остров Колдрос, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11428,'Хранитель Листопад','$n, ты $gстал нам добрым другом и верным союзником:стала нам доброй подругой и верной союзницей;. Поэтому я хочу обратиться к тебе еще с одной просьбой.$B$BТы собственными глазами $gвидел:видела; то, что случилось с Холмистой поляной, и какие жуткие твари населяют эти некогда мирные земли. Негодующие хранители не прекращают приманивать этих чудовищ, и вскоре они заполонят все земли и воды – если только мы не сможем им помешать.$B$BСамого могущественного негодующего хранителя зовут Хранитель Листопад. Убей его, $n, и дай этим землям шанс возродиться во всей былой красе.','Луриэль с Заиндевевшей поляны просит вас убить Хранителя Листопада.','Ты избавил Холмистую поляну от Хранителя Листопада?','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранитель Листопад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, ты $gстал нам добрым другом и верным союзником:стала нам доброй подругой и верной союзницей;. Поэтому я хочу обратиться к тебе еще с одной просьбой.$B$BТы собственными глазами $gвидел:видела; то, что случилось с Холмистой поляной, и какие жуткие твари населяют эти некогда мирные земли. Негодующие хранители не прекращают приманивать этих чудовищ, и вскоре они заполонят все земли и воды – если только мы не сможем им помешать.$B$BСамого могущественного негодующего хранителя зовут Хранитель Листопад. Убей его, $n, и дай этим землям шанс возродиться во всей былой красе.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Луриэль с Заиндевевшей поляны просит вас убить Хранителя Листопада.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты избавил Холмистую поляну от Хранителя Листопада?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Луриэли на Заиндевевшую поляну, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11429,'Защищай знамя до последнего!','Я не собираюсь доверять столь ответственное задание непроверенным людям.$B$BЕсли хочешь доказать мне, что ты обладаешь необходимыми качествами для выполнения этой миссии, делай так, как я тебе велю.$B$BВозьми это знамя и отправляйся в Гибльхейм, который находится на севере отсюда. Как только прибудешь на место, найди центр города и установи там этот флаг. Сразись с любым врайкулом, который осмелится прикоснуться к нашему великому знамени, после чего доложи мне о победе Альянса!','Слава Альянсу! А ты не робкого десятка, $N. Пожалуй, тебе хватит силенок, чтобы раскрошить парочку врайкульских черепов в Ниффлваре.','Ты смотри, на тебе ни царапинки. Можно подумать, ты ни с кем не $Gсражался:сражалась;!','Защитить знамя Альянса','Вернитесь к лейтенанту Ледяному Молоту в Ревущий фьорд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защищай знамя до последнего!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я не собираюсь доверять столь ответственное задание непроверенным людям.$B$BЕсли хочешь доказать мне, что ты обладаешь необходимыми качествами для выполнения этой миссии, делай так, как я тебе велю.$B$BВозьми это знамя и отправляйся в Гибльхейм, который находится на севере отсюда. Как только прибудешь на место, найди центр города и установи там этот флаг. Сразись с любым врайкулом, который осмелится прикоснуться к нашему великому знамени, после чего доложи мне о победе Альянса!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава Альянсу! А ты не робкого десятка, $N. Пожалуй, тебе хватит силенок, чтобы раскрошить парочку врайкульских черепов в Ниффлваре.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты смотри, на тебе ни царапинки. Можно подумать, ты ни с кем не $Gсражался:сражалась;!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Защитить знамя Альянса',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Ледяному Молоту в Ревущий фьорд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11430,'Мастер-гарпунщик Явус','Ты хорошо $gпроявил:проявила; себя в Гибльхейме, $n. Но прежде, чем ты начнешь задирать нос, я хочу поручить тебе настоящее задание в Ниффлваре.$B$BМы обнаружили врайкула, обстреливающего наши фрегаты из гарпунной пушки. Зовут этого мерзавца Явус. Его легко найти на главной гарпунной станции, выстроенной на склонах Ниффлвара к юго-востоку отсюда.$B$BВыследи его и накажи за все преступления, совершенные им против Альянса!$B$BНе подведи меня, $n!','Лейтенант Ледяной Молот из Ревущего фьорда поручил вам убить мастера-гарпунщика Явуса в Ниффлваре.','Им понадобится какое-то время, чтобы найти Явусу замену. Самое время осуществить план Зорека! Пока они будут пытаться вышвырнуть нас из Ниффлвара, ты обратишь их гарпунные пушки против них самих!','Вернитесь к лейтенанту Ледяному Молоту в Ревущий фьорд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мастер-гарпунщик Явус',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты хорошо $gпроявил:проявила; себя в Гибльхейме, $n. Но прежде, чем ты начнешь задирать нос, я хочу поручить тебе настоящее задание в Ниффлваре.$B$BМы обнаружили врайкула, обстреливающего наши фрегаты из гарпунной пушки. Зовут этого мерзавца Явус. Его легко найти на главной гарпунной станции, выстроенной на склонах Ниффлвара к юго-востоку отсюда.$B$BВыследи его и накажи за все преступления, совершенные им против Альянса!$B$BНе подведи меня, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Лейтенант Ледяной Молот из Ревущего фьорда поручил вам убить мастера-гарпунщика Явуса в Ниффлваре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Им понадобится какое-то время, чтобы найти Явусу замену. Самое время осуществить план Зорека! Пока они будут пытаться вышвырнуть нас из Ниффлвара, ты обратишь их гарпунные пушки против них самих!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лейтенанту Ледяному Молоту в Ревущий фьорд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11431,'Поймать дикого зайцелопа!','Что? Они действительно существуют!$B$BМне нужна минутка... и выпить...$B$B<Он делает глоток из своей кружки.>$B$BДумаю, я могу позволить тебе оставить одного...','Ты $Gбыл:была; достаточно $Gпьян:пьяна;, чтобы увидеть маленьких зайцелопов?','Вернитесь к Глодраку Меткому Охотнику в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поймать дикого зайцелопа!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что? Они действительно существуют!$B$BМне нужна минутка... и выпить...$B$B<Он делает глоток из своей кружки.>$B$BДумаю, я могу позволить тебе оставить одного...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gбыл:была; достаточно $Gпьян:пьяна;, чтобы увидеть маленьких зайцелопов?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глодраку Меткому Охотнику в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11432,'Спящие великаны','Я случайно услышал твой разговор с отцом Левариолом. Смею предположить, он не позволил тебе предпринять решительные действия.$B$BНо ты $gдолжен:должна; уничтожить врайкулов, спящих в глубине чертогов Пробуждения под Гьялерброном!$B$BЯ не сомневаюсь, что ритуалы, в которых они должны принять участие, могут иметь ужасные последствия! Скорее всего, у некролордов есть некое устройство, позволяющее пробудить их на время.$B$BУничтожь спящих – и врайкулы никогда оправятся от таких потерь.','Маг-лейтенант Малистер поручил вам уничтожить 5 спящих врайкулов. Когда задание будет выполнено, вернитесь к нему в Крепость Западной стражи.','Ты $Gсделал:сделала; то, что $Gдолжен:должна; $Gбыл:была; сделать. Хотя многие сочтут убийство беспомощных врайкулов бесчестным поступком, в нашем положении это был единственно верный выход.$B$BМы ведь не могли позволить, чтобы их пробудили в ходе неких ужасных ритуалов, верно?$B$BПоэтому ты можешь гордиться своей смелостью, $N.','$N, мне кажется неправдоподобным, что ты разобрался со спящими врайкулами. Вернись, когда сделаешь это.','Вернитесь к магу-лейтенанту Малистеру в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спящие великаны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я случайно услышал твой разговор с отцом Левариолом. Смею предположить, он не позволил тебе предпринять решительные действия.$B$BНо ты $gдолжен:должна; уничтожить врайкулов, спящих в глубине чертогов Пробуждения под Гьялерброном!$B$BЯ не сомневаюсь, что ритуалы, в которых они должны принять участие, могут иметь ужасные последствия! Скорее всего, у некролордов есть некое устройство, позволяющее пробудить их на время.$B$BУничтожь спящих – и врайкулы никогда оправятся от таких потерь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Маг-лейтенант Малистер поручил вам уничтожить 5 спящих врайкулов. Когда задание будет выполнено, вернитесь к нему в Крепость Западной стражи.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты $Gсделал:сделала; то, что $Gдолжен:должна; $Gбыл:была; сделать. Хотя многие сочтут убийство беспомощных врайкулов бесчестным поступком, в нашем положении это был единственно верный выход.$B$BМы ведь не могли позволить, чтобы их пробудили в ходе неких ужасных ритуалов, верно?$B$BПоэтому ты можешь гордиться своей смелостью, $N.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, мне кажется неправдоподобным, что ты разобрался со спящими врайкулами. Вернись, когда сделаешь это.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магу-лейтенанту Малистеру в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11433,'Спящие великаны','Ледяной змей и его хозяин мертвы?\n\nНо где же рог?','Вернитесь к Ахоте Белому Инею в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спящие великаны',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ледяной змей и его хозяин мертвы?\n\nНо где же рог?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ахоте Белому Инею в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11434,'Забытое сокровище','Я сколотил целое состояние на сокровищах, которыми не интересуются обычные пираты – предметы искусства, картины, антиквариат. $B$BНесколько лет назад к югу отсюда затонул флот Блэка Конрада. Ныряльщики давно уже растащили все золото и драгоценности, но два древних сокровища так и остались лежать на дне моря. Одно из них – аманийская ваза, музейная редкость, а второе – статуэтка орла. $B$BДобудь эти ценности, и я замолвлю за тебя словечко перед остальными пиратами. Я даже подброшу кое-что звонкое, чтобы твое морское приключение стало для тебя не только увлекательным, но и прибыльным.','Красавчик Терри из Лагеря Скалаваг просит вас достать аманийскую вазу и статуэтку орла с места кораблекрушения на юге.','Вернитесь к Красавчику Терри в Лагерь Скалаваг, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Забытое сокровище',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я сколотил целое состояние на сокровищах, которыми не интересуются обычные пираты – предметы искусства, картины, антиквариат. $B$BНесколько лет назад к югу отсюда затонул флот Блэка Конрада. Ныряльщики давно уже растащили все золото и драгоценности, но два древних сокровища так и остались лежать на дне моря. Одно из них – аманийская ваза, музейная редкость, а второе – статуэтка орла. $B$BДобудь эти ценности, и я замолвлю за тебя словечко перед остальными пиратами. Я даже подброшу кое-что звонкое, чтобы твое морское приключение стало для тебя не только увлекательным, но и прибыльным.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Красавчик Терри из Лагеря Скалаваг просит вас достать аманийскую вазу и статуэтку орла с места кораблекрушения на юге.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Красавчику Терри в Лагерь Скалаваг, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11435,'Собранные тыквы NYI','Привет, $n! Спасибо, что $Gпрогнал:прогнала; Всадника! Теперь попечительница говорит, что нам можно побегать по деревне!$B$BМы тут нашли тыквы, что Всадник побросал. Страшные такие... Может, возьмешь и покажешь нашей попечительнице?','Возьмите тыквы и переодетой попечительнице сирот.','Вернитесь к переодетой попечительнице сирот.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собранные тыквы NYI',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $n! Спасибо, что $Gпрогнал:прогнала; Всадника! Теперь попечительница говорит, что нам можно побегать по деревне!$B$BМы тут нашли тыквы, что Всадник побросал. Страшные такие... Может, возьмешь и покажешь нашей попечительнице?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возьмите тыквы и переодетой попечительнице сирот.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к переодетой попечительнице сирот.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11436,'Полетаем?','Как же нелегко путешествовать по крутым обрывам Ревущего фьорда! К счастью, мне пришла в голову идея, как облегчить эту задачу. Мое устройство сочетает в себе врайкульскую технологию и дворфийскую гениальность. Тут подкрутить, здесь припаять – и вот, позвольте продемонстрировать пульт управления гарпуном имени Ледяного Молота! Конечно, я его еще не испытывал, но ты вполне с этим справишься!$B$BОтнеси эту штуку к большой пушке в Ниффлваре и отправь себя в Валгард. Доложи о своем успехе Зореку. Кстати, пульт управления можешь оставить себе!','Воспользуйтесь большой врайкульской пушкой в Ниффлваре и запустите себя в Валгард. Доложите о победе над врайкулами капитану стражи Зореку.','Ты что, совсем с ума $Gсошел:сошла;, $N? Только полный идиот может выстрелить собой из гарпунной пушки, чтобы таким образом добраться до места назначения!$B$BНо, я полагаю, надо быть слега сумасшедшим, чтобы так сражаться на обрывах фьорда! Потрясающе! Мне доложили, что Ингвар, предводитель Укротителей драконов, в ярости от твоей выходки! Возможно, однажды именно тебе удастся втоптать его в грязь во славу Альянса!','<Зорек поднимает бровь, глядя на вас.>','Полет на гарпуне','Вернитесь к капитану стражи Зореку в Валгард, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полетаем?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как же нелегко путешествовать по крутым обрывам Ревущего фьорда! К счастью, мне пришла в голову идея, как облегчить эту задачу. Мое устройство сочетает в себе врайкульскую технологию и дворфийскую гениальность. Тут подкрутить, здесь припаять – и вот, позвольте продемонстрировать пульт управления гарпуном имени Ледяного Молота! Конечно, я его еще не испытывал, но ты вполне с этим справишься!$B$BОтнеси эту штуку к большой пушке в Ниффлваре и отправь себя в Валгард. Доложи о своем успехе Зореку. Кстати, пульт управления можешь оставить себе!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь большой врайкульской пушкой в Ниффлваре и запустите себя в Валгард. Доложите о победе над врайкулами капитану стражи Зореку.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты что, совсем с ума $Gсошел:сошла;, $N? Только полный идиот может выстрелить собой из гарпунной пушки, чтобы таким образом добраться до места назначения!$B$BНо, я полагаю, надо быть слега сумасшедшим, чтобы так сражаться на обрывах фьорда! Потрясающе! Мне доложили, что Ингвар, предводитель Укротителей драконов, в ярости от твоей выходки! Возможно, однажды именно тебе удастся втоптать его в грязь во славу Альянса!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Зорек поднимает бровь, глядя на вас.>',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Полет на гарпуне',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану стражи Зореку в Валгард, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11437,'[PH] Пивной сад A','[PH] Поговорите с зазывалой Хмельного фестиваля в Пивном саду рядом с Дарнасом, Экзодаром, Шаттратом или Штормградом и получите бесплатный соленый кренделек.','[PH] Поговорите с зазывалой Хмельного фестиваля в любом пивном саду и получите бесплатный кренделек.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[PH] Пивной сад A',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[PH] Поговорите с зазывалой Хмельного фестиваля в Пивном саду рядом с Дарнасом, Экзодаром, Шаттратом или Штормградом и получите бесплатный соленый кренделек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PH] Поговорите с зазывалой Хмельного фестиваля в любом пивном саду и получите бесплатный кренделек.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11438,'[PH] Пивной сад B','[PH] Поговорите с зазывалой Хмельного фестиваля в пивном саду рядом с Дарнасом, Экзодаром, Шаттратом или Штормградом и получите бесплатный соленый кренделек.','[PH] Поговорите с зазывалой Хмельного фестиваля в любом пивном саду и получите бесплатный кренделек.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[PH] Пивной сад B',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[PH] Поговорите с зазывалой Хмельного фестиваля в пивном саду рядом с Дарнасом, Экзодаром, Шаттратом или Штормградом и получите бесплатный соленый кренделек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PH] Поговорите с зазывалой Хмельного фестиваля в любом пивном саду и получите бесплатный кренделек.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11439,'Учения пожарной бригады','Отважные дворфы Караноса готовы в один момент сформировать пожарную бригаду, раз поблизости Всадник без головы. Не хотите ли помочь?$B$BК югу отсюда горные пехотинцы устроили небольшой полигон для учений пожарных бригад. Идите туда и носите ведрами воду, чтобы тушить пожар. Воду можно черпать ведром из этих бочек с водой.$B$BУдачи, $n. Когда поучаствуете в учениях пожарной бригады, возвращайтесь к нам!','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.','Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!\n\nОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!','Привет, $N. Вы совершенствовали свою технику пожаротушения? Не забывайте о тренировочной зоне на юге!','Вернитесь к переодетой попечительнице сирот в Каранос, что в Дун Мороге.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Учения пожарной бригады',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отважные дворфы Караноса готовы в один момент сформировать пожарную бригаду, раз поблизости Всадник без головы. Не хотите ли помочь?$B$BК югу отсюда горные пехотинцы устроили небольшой полигон для учений пожарных бригад. Идите туда и носите ведрами воду, чтобы тушить пожар. Воду можно черпать ведром из этих бочек с водой.$B$BУдачи, $n. Когда поучаствуете в учениях пожарной бригады, возвращайтесь к нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!\n\nОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $N. Вы совершенствовали свою технику пожаротушения? Не забывайте о тренировочной зоне на юге!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к переодетой попечительнице сирот в Каранос, что в Дун Мороге.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11440,'Учения пожарной бригады','Пока остается угроза нападений Всадника без головы, миротворцам придется сформировать там, где необходимо, пожарные бригады. Не хотите ли помочь?$B$BК западу отсюда, в направлении Экзодара, миротворцы организовали небольшой полигон для учений пожарных бригад. Отправляйтесь туда и упражняйтесь в тушении пожаров. Воду можете набирать из бочек прямо здесь.$B$BДо свидания, $n. Когда закончите учения, пожалуйста, возвращайтесь к нам!','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.','Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!$B$BОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!','Привет, $N. Вы совершенствовали свою технику пожаротушения? Не забывайте о тренировочной зоне на западе!','Вернитесь к переодетой попечительнице сирот на Лазурную заставу, что на острове Лазурной Дымки.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Учения пожарной бригады',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока остается угроза нападений Всадника без головы, миротворцам придется сформировать там, где необходимо, пожарные бригады. Не хотите ли помочь?$B$BК западу отсюда, в направлении Экзодара, миротворцы организовали небольшой полигон для учений пожарных бригад. Отправляйтесь туда и упражняйтесь в тушении пожаров. Воду можете набирать из бочек прямо здесь.$B$BДо свидания, $n. Когда закончите учения, пожалуйста, возвращайтесь к нам!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы вымокли до нитки и перемазались в саже! Вы наверняка боролись с огнем!$B$BОчень хорошо! Как почетного представителя Пожарной Бригады, прошу вас прийти нам на помощь, как только деревня окажется в беде!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Привет, $N. Вы совершенствовали свою технику пожаротушения? Не забывайте о тренировочной зоне на западе!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к переодетой попечительнице сирот на Лазурную заставу, что на острове Лазурной Дымки.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11441,'Хмельной фестиваль!','Поговорите с распорядителем Хмельного фестиваля на территории Хмельного фестиваля рядом со Стальгорном и получите бесплатное пиво.','Поговорите с распорядителем Хмельного фестиваля.','Хо-хо! Думаешь, бесплатное пиво вкуснее?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хмельной фестиваль!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Поговорите с распорядителем Хмельного фестиваля на территории Хмельного фестиваля рядом со Стальгорном и получите бесплатное пиво.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с распорядителем Хмельного фестиваля.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хо-хо! Думаешь, бесплатное пиво вкуснее?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11442,'Добро пожаловать на Хмельной фестиваль!','[PH] Поговорите с распорядителем Хмельного фестиваля на территории Хмельного фестиваля рядом со Стальгорном и получите бесплатное пиво.','[PH] Поговорите с распорядителем Хмельного фестиваля и получите бесплатное пиво.','Хо-хо! Думаешь, бесплатное пиво вкуснее?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать на Хмельной фестиваль!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[PH] Поговорите с распорядителем Хмельного фестиваля на территории Хмельного фестиваля рядом со Стальгорном и получите бесплатное пиво.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PH] Поговорите с распорядителем Хмельного фестиваля и получите бесплатное пиво.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хо-хо! Думаешь, бесплатное пиво вкуснее?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11443,'Подводное плавание в Бухте Кинжалов','Эй... ээ... Привет! А ты что тут делаешь?$B$BКто, я? А... Ну, понимаешь... Я... типа... обчищаю... ээ... Очищаю тут от обломков, вот что! Мне Келлер поручил! Ей-богу, так и сказал: "Гарри, я хочу, чтобы ты надел водолазный шлем и поискал наши вещички среди обломков кораблей в Бухте Кинжала..."$B$BНо я, если что, не откажусь от твоей помощи. Здесь, в бухте, полно всяких ценностей... то есть припасов. Так что, давай, тащи все, что найдешь мне. Только не забудь водолазный шлем – иначе задохнешься и умрешь!','Гарольд Лаграс из Бухты Кинжалов попросил вас найти 10 валгардских ящиков с припасами.','Ну, где припасы?','Вернитесь к Гарольду Лаграсу в Бухту Кинжалов, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подводное плавание в Бухте Кинжалов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй... ээ... Привет! А ты что тут делаешь?$B$BКто, я? А... Ну, понимаешь... Я... типа... обчищаю... ээ... Очищаю тут от обломков, вот что! Мне Келлер поручил! Ей-богу, так и сказал: "Гарри, я хочу, чтобы ты надел водолазный шлем и поискал наши вещички среди обломков кораблей в Бухте Кинжала..."$B$BНо я, если что, не откажусь от твоей помощи. Здесь, в бухте, полно всяких ценностей... то есть припасов. Так что, давай, тащи все, что найдешь мне. Только не забудь водолазный шлем – иначе задохнешься и умрешь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Гарольд Лаграс из Бухты Кинжалов попросил вас найти 10 валгардских ящиков с припасами.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, где припасы?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарольду Лаграсу в Бухту Кинжалов, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11444,'[PH] Пивной сад A','[PH] Поговорите с зазывалой Хмельного фестиваля в пивном саду рядом с Дарнасом, Экзодаром, Шаттратом или Штормградом и получите бесплатный соленый кренделек.','[PH] Поговорите с зазывалой Хмельного фестиваля в любом пивном саду и получите бесплатный кренделек.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[PH] Пивной сад A',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[PH] Поговорите с зазывалой Хмельного фестиваля в пивном саду рядом с Дарнасом, Экзодаром, Шаттратом или Штормградом и получите бесплатный соленый кренделек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PH] Поговорите с зазывалой Хмельного фестиваля в любом пивном саду и получите бесплатный кренделек.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11445,'[PH] Пивной сад B','[PH] Поговорите с зазывалой Хмельного фестиваля в пивном саду рядом с Дарнасом, Экзодаром, Шаттратом или Штормградом и получите бесплатный соленый кренделек.','[PH] Поговорите с зазывалой Хмельного фестиваля в любом пивном саду и получите бесплатный кренделек.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','[PH] Пивной сад B',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[PH] Поговорите с зазывалой Хмельного фестиваля в пивном саду рядом с Дарнасом, Экзодаром, Шаттратом или Штормградом и получите бесплатный соленый кренделек.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PH] Поговорите с зазывалой Хмельного фестиваля в любом пивном саду и получите бесплатный кренделек.',`objectives_loc8`);
