INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11447,'Добро пожаловать на Хмельной фестиваль!','[PH] Поговорите с распорядителем Хмельного фестиваля на территории Хмельного фестиваля рядом со Стальгорном и получите бесплатное пиво.','[PH] Поговорите с распорядителем Хмельного фестиваля и получите бесплатное пиво.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добро пожаловать на Хмельной фестиваль!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','[PH] Поговорите с распорядителем Хмельного фестиваля на территории Хмельного фестиваля рядом со Стальгорном и получите бесплатное пиво.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','[PH] Поговорите с распорядителем Хмельного фестиваля и получите бесплатное пиво.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11448,'Лагерь Лиги исследователей','<Станвад недовольно ворчит.>','Вернитесь к Станваду в Ревущий фьорд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лагерь Лиги исследователей',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Станвад недовольно ворчит.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Станваду в Ревущий фьорд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11449,'Учения пожарной бригады','Ловчие смерти устроили учебный полигон за стенами города. Мы не можем допустить, чтобы дома Брилла продолжали гореть. Выполняйте свой долг и ступайте на учения пожарной бригады.$B$BИдите по дороге на запад мимо кладбища. Там увидите полигон.','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Брилле.','Отличная работа, $N. Дети, посмотрите внимательно на |3-3($C). Пусть он будет для вас ярким примером.','Вы затушили пожары, $N? Тренировочная зона находится к западу от Брилла.','Вернитесь к попечительнице сирот в маске в Брилл, что в Тирисфальских лесах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Учения пожарной бригады',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ловчие смерти устроили учебный полигон за стенами города. Мы не можем допустить, чтобы дома Брилла продолжали гореть. Выполняйте свой долг и ступайте на учения пожарной бригады.$B$BИдите по дороге на запад мимо кладбища. Там увидите полигон.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Брилле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Дети, посмотрите внимательно на |3-3($C). Пусть он будет для вас ярким примером.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы затушили пожары, $N? Тренировочная зона находится к западу от Брилла.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к попечительнице сирот в маске в Брилл, что в Тирисфальских лесах.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11450,'Учения пожарной бригады','Стража устроила полигон для учений пожарных бригад за стенами города. Мы не дадим Всаднику разрушить все, что мы с таким трудом восстанавливали. Исполняйте ваш долг и примите участие в учениях пожарной бригады.$B$BСтупайте за ворота на юг и идите до перекрестка. Там найдете учебный полигон.','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске на Площади Соколиных Крыльев.','Отличная работа, $N. Дети, посмотрите внимательно на |3-3($C). Пусть он будет для вас ярким примером.','Вы затушили пожары, $N? Тренировочная зона находится к югу.','Вернитесь к попечительнице сирот в маске на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Учения пожарной бригады',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стража устроила полигон для учений пожарных бригад за стенами города. Мы не дадим Всаднику разрушить все, что мы с таким трудом восстанавливали. Исполняйте ваш долг и примите участие в учениях пожарной бригады.$B$BСтупайте за ворота на юг и идите до перекрестка. Там найдете учебный полигон.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске на Площади Соколиных Крыльев.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, $N. Дети, посмотрите внимательно на |3-3($C). Пусть он будет для вас ярким примером.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы затушили пожары, $N? Тренировочная зона находится к югу.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к попечительнице сирот в маске на Площадь Соколиных Крыльев, что в Лесах Вечной Песни.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11451,'Стишок Алисии','Привет, я тут написала стишок для моей подружки Кайли. Она любит гостить у Алдоров в Шаттрате. Ну, в Запределье, ты же знаешь?$b$bТы не отнесешь ей мои стишки? Моя мамочка говорит, что я еще слишком маленькая, чтобы ходить в Шаттрат!','Вас попросили отнести стишок Алисии Кайли Дак в Шаттрат в Запределье.','Какой трогательный стишок, спасибо!','Ой, стишок?','Вернитесь к Кайли Дак в Шаттрат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стишок Алисии',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, я тут написала стишок для моей подружки Кайли. Она любит гостить у Алдоров в Шаттрате. Ну, в Запределье, ты же знаешь?$b$bТы не отнесешь ей мои стишки? Моя мамочка говорит, что я еще слишком маленькая, чтобы ходить в Шаттрат!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вас попросили отнести стишок Алисии Кайли Дак в Шаттрат в Запределье.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Какой трогательный стишок, спасибо!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ой, стишок?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Кайли Дак в Шаттрат.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11452,'Спящий король','Из мертвой руки некровладыки падает листок пергамента, на котором описан процесс одного из ритуалов, проходящих в подземных катакомбах. $B$BИз этого свитка вы узнаете, что королева врайкулов, Ангербода, пытается пробудить короля Имирона. Ритуал проводится в огромной палате, известной как Зимняя терраса. Она находится на севере Гьялерброна.$B$BЕсли вы поспешите, то, возможно, успеете остановить Ангербоду до того, как будет слишком поздно.','Убейте королеву Ангербоду и прервите ритуал пробуждения короля Имирона. Если вам удастся сделать это, вернитесь в Крепость Западной Стражи и доложите о своей победе капитану Адамсу.','$N, какие новости ты $Gпринес:принесла;?','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спящий король',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из мертвой руки некровладыки падает листок пергамента, на котором описан процесс одного из ритуалов, проходящих в подземных катакомбах. $B$BИз этого свитка вы узнаете, что королева врайкулов, Ангербода, пытается пробудить короля Имирона. Ритуал проводится в огромной палате, известной как Зимняя терраса. Она находится на севере Гьялерброна.$B$BЕсли вы поспешите, то, возможно, успеете остановить Ангербоду до того, как будет слишком поздно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте королеву Ангербоду и прервите ритуал пробуждения короля Имирона. Если вам удастся сделать это, вернитесь в Крепость Западной Стражи и доложите о своей победе капитану Адамсу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','$N, какие новости ты $Gпринес:принесла;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Адамсу в Крепость Западной Стражи, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11453,'Спящий король','Из мертвой руки некровладыки падает листок пергамента, на котором описан процесс одного из ритуалов, проходящих в подземных катакомбах. $B$BИз этого свитка вы узнаете, что королева врайкулов, Ангербода, пытается пробудить короля Имирона. Ритуал проводится в огромной палате, известной как Зимняя терраса. Она находится на севере Гьялерброна.$B$BЕсли вы поспешите, то, возможно, успеете остановить Ангерброду до того, как будет слишком поздно.','Не нравится мне все это! Если Король-лич объединится с Имироном, это принесет нам одни неприятности. Какая жалость, что ты не прикончил его вместе с королевой.\n\nНо все же, тебе удалось значительно нарушить их планы, тем самым выиграв для нас время.\n\nКто знает – возможно, ты еще скрестишь клинки с королем Имироном. Могу поспорить, вашей следующей встречи он не переживет.','Ледяной змей и его хозяин мертвы?\n\nНо где же рог?','Вернитесь к вождю Прахтотему в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спящий король',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из мертвой руки некровладыки падает листок пергамента, на котором описан процесс одного из ритуалов, проходящих в подземных катакомбах. $B$BИз этого свитка вы узнаете, что королева врайкулов, Ангербода, пытается пробудить короля Имирона. Ритуал проводится в огромной палате, известной как Зимняя терраса. Она находится на севере Гьялерброна.$B$BЕсли вы поспешите, то, возможно, успеете остановить Ангерброду до того, как будет слишком поздно.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не нравится мне все это! Если Король-лич объединится с Имироном, это принесет нам одни неприятности. Какая жалость, что ты не прикончил его вместе с королевой.\n\nНо все же, тебе удалось значительно нарушить их планы, тем самым выиграв для нас время.\n\nКто знает – возможно, ты еще скрестишь клинки с королем Имироном. Могу поспорить, вашей следующей встречи он не переживет.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ледяной змей и его хозяин мертвы?\n\nНо где же рог?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Прахтотему в Лагерь Заиндевевшего Копыта, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11454,'Поиски диверсантов','Похоже, этот листок бумаги случайно оставили захватчики Черного Железа.$b$bХотя планы очень непростые и записаны особым дворфийским кодом, подпись в самом конце – "Корен Худовар" – разобрать легко. Упоминание "Угрюмого Обжоры" из Глубин Черной горы тоже. Найди виновника этого безобразия и положи конец набегам.','Найдите Худовара в "Угрюмом обжоре" в Глубинах Черной горы.','Это чертовски обидно, что ты много развлекаешься без лучшего из лучших сортов пива - нашего! Получили ли мы приглашение на конкурс? Конечно, нет. Ты сражаешься на какой-то войне,а вдруг твое пиво недостаточно хорошее! Так что, мы немного разбили твои бочонки, и это правильно!$B$BЭ... Вижу ты прорвал нашу оборону и все такое.$B$BМожет, ты сможешь что-нибудь для меня сделать...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски диверсантов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, этот листок бумаги случайно оставили захватчики Черного Железа.$b$bХотя планы очень непростые и записаны особым дворфийским кодом, подпись в самом конце – "Корен Худовар" – разобрать легко. Упоминание "Угрюмого Обжоры" из Глубин Черной горы тоже. Найди виновника этого безобразия и положи конец набегам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Худовара в "Угрюмом обжоре" в Глубинах Черной горы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Это чертовски обидно, что ты много развлекаешься без лучшего из лучших сортов пива - нашего! Получили ли мы приглашение на конкурс? Конечно, нет. Ты сражаешься на какой-то войне,а вдруг твое пиво недостаточно хорошее! Так что, мы немного разбили твои бочонки, и это правильно!$B$BЭ... Вижу ты прорвал нашу оборону и все такое.$B$BМожет, ты сможешь что-нибудь для меня сделать...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11455,'Запах денег','Мы, пираты, много что любим – ром и золото, паруса и мачты – но порядок и чистота не входят в этот список! На многих пиратских кораблях плавает в пять раз больше крыс, чем членов команды.$B$BНе удивительно, что все медведи на острове подхватили бешенство! Короче говоря, босс хочет от них избавиться.$B$BА тут еще такое дело... попал мне однажды в руки рецептик духов, за которые любая штормградская модница отдаст кошелек и поцелуй в придачу. И знаешь, какой ингредиент стоит там на первом месте? Медвежий мускус! Тебе не кажется, что на этом можно хорошо заработать?','Красавчик Терри из Лагеря Скалаваг в Ревущем фьорде просит вас добыть 4 мускусные железы бешеных бурых медведей, которые бродят по всему острову.','Ай, молодчина! Может быть, это не столь захватывающе, как грабить корабли, но я буду последней сухопутной крысой, если упущу возможность обогатиться.','Ты ведь несешь мне мускусные железы, правда?','Вернитесь к Красавчику Терри в Лагерь Скалаваг, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запах денег',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы, пираты, много что любим – ром и золото, паруса и мачты – но порядок и чистота не входят в этот список! На многих пиратских кораблях плавает в пять раз больше крыс, чем членов команды.$B$BНе удивительно, что все медведи на острове подхватили бешенство! Короче говоря, босс хочет от них избавиться.$B$BА тут еще такое дело... попал мне однажды в руки рецептик духов, за которые любая штормградская модница отдаст кошелек и поцелуй в придачу. И знаешь, какой ингредиент стоит там на первом месте? Медвежий мускус! Тебе не кажется, что на этом можно хорошо заработать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Красавчик Терри из Лагеря Скалаваг в Ревущем фьорде просит вас добыть 4 мускусные железы бешеных бурых медведей, которые бродят по всему острову.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ай, молодчина! Может быть, это не столь захватывающе, как грабить корабли, но я буду последней сухопутной крысой, если упущу возможность обогатиться.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты ведь несешь мне мускусные железы, правда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Красавчику Терри в Лагерь Скалаваг, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11456,'Мясо для выживших','Мы, клыкарры, живем в основном за счет рыбной ловли. Однако во времена большой нужды мы не гнушаемся охотой на животных. $B$BНедавно на близлежащую деревню Искаал напали пираты, и с тех пор оттуда не иссякает поток беженцев.$B$BНа этой неделе наш улов был скромен, но на острове полно черпорогов, чье мясо очень питательно.$B$BПожалуйста, помоги моим людям охотиться на этих огромных животных и принеси мне как можно больше мяса.','Ты принес нам мясо?','Вернитесь к старейшине Атуику в Камагуа, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мясо для выживших',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы, клыкарры, живем в основном за счет рыбной ловли. Однако во времена большой нужды мы не гнушаемся охотой на животных. $B$BНедавно на близлежащую деревню Искаал напали пираты, и с тех пор оттуда не иссякает поток беженцев.$B$BНа этой неделе наш улов был скромен, но на острове полно черпорогов, чье мясо очень питательно.$B$BПожалуйста, помоги моим людям охотиться на этих огромных животных и принеси мне как можно больше мяса.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес нам мясо?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Атуику в Камагуа, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11457,'Вооружая Камагуа','Мой народ изображает Иссилрука, духа войны, в виде серебряного орла. Легенды гласят, будто однажды Иссилрук сражался с сотней воргов, чтобы спасти своего детеныша.$B$BТеперь и нам пора вступить в бой с врагами, чтобы защитить наших братьев. Но нам нужно новое оружие. Острые рога ледокрылых химер, что обитают на заснеженных частях острова, легко превратить в наконечники копий. Принеси мне самые лучшие рога, которые тебе только удастся добыть.','Старейшина Атуик просит вас добыть 3 рога химеры.','Я рад видеть тебя снова, |3-6($r).','Вернитесь к старейшине Атуику в Камагуа, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вооружая Камагуа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой народ изображает Иссилрука, духа войны, в виде серебряного орла. Легенды гласят, будто однажды Иссилрук сражался с сотней воргов, чтобы спасти своего детеныша.$B$BТеперь и нам пора вступить в бой с врагами, чтобы защитить наших братьев. Но нам нужно новое оружие. Острые рога ледокрылых химер, что обитают на заснеженных частях острова, легко превратить в наконечники копий. Принеси мне самые лучшие рога, которые тебе только удастся добыть.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Старейшина Атуик просит вас добыть 3 рога химеры.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я рад видеть тебя снова, |3-6($r).',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Атуику в Камагуа, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11458,'Месть за Искаал','Тотем Иссилрука готов, $n, и я благодарю тебя за помощь в его изготовлении. В эти тревожные времена мы должны забыть о мирном пути и сразиться с теми, кто посягнул на наши земли и поднял руку на наш народ. $B$BПираты-работорговцы, совершившие налет на Искаал, сошли с ума и убили всех пленных. Отправляйся на восток, в Искаал, и выполни свой долг. Возьми с собой этот рог и призови на помощь моих братьев.','Старейшина Атуик просит вас отправиться в Искаал и убить 8 поработителей – пиратов Северных морей. Если вам понадобится помощь, воспользуйтесь Рогом Камагуа.','Вернитесь к старейшине Атуику в Камагуа, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть за Искаал',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тотем Иссилрука готов, $n, и я благодарю тебя за помощь в его изготовлении. В эти тревожные времена мы должны забыть о мирном пути и сразиться с теми, кто посягнул на наши земли и поднял руку на наш народ. $B$BПираты-работорговцы, совершившие налет на Искаал, сошли с ума и убили всех пленных. Отправляйся на восток, в Искаал, и выполни свой долг. Возьми с собой этот рог и призови на помощь моих братьев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Старейшина Атуик просит вас отправиться в Искаал и убить 8 поработителей – пиратов Северных морей. Если вам понадобится помощь, воспользуйтесь Рогом Камагуа.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Атуику в Камагуа, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11459,'Что сказал Зех\'ген','Трави концы, друг. Значит хочешь, чтобы я гарпунул ту скользкую салаку, которая вильнула меж лап нашей братвы?$B$BТогда тащи мне квакуху, морячок. Потом я подсеку тебе эту тухлятину. Не, не, квакуха подсечет. Сам узыришь, своими маяками, тутжещас.$B$BДа, и не забудь жилорезку, сухоход. Дуй по курсу, чайник.','Вернитесь к Красавчику Терри и попросите объяснить, что хотел от вас Зех\'ген.','Ты ведь несешь мне мускусные железы, правда?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что сказал Зех\'ген',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Трави концы, друг. Значит хочешь, чтобы я гарпунул ту скользкую салаку, которая вильнула меж лап нашей братвы?$B$BТогда тащи мне квакуху, морячок. Потом я подсеку тебе эту тухлятину. Не, не, квакуха подсечет. Сам узыришь, своими маяками, тутжещас.$B$BДа, и не забудь жилорезку, сухоход. Дуй по курсу, чайник.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь к Красавчику Терри и попросите объяснить, что хотел от вас Зех\'ген.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты ведь несешь мне мускусные железы, правда?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (11460,'Завоевание доверия','Прежде всего сокольничий должен установить связь между собой и своей птицей, завоевать ее доверие. $B$B<Идальго указывает на соколов в клетке, стоящей у его ног.>$B$BЕсли хочешь, чтобы птицы тебе доверяли – накорми их до отвала!$B$BКак тебе, должно быть, известно, скальные соколы фьорда питаются в основном червяками. По всему фьорду легко можно найти расшатанные камни, под которыми обитает множество личинок. Найди червячка и накорми им сокола в клетке.','Да, $N. Я уже чувствую дружескую связь между тобой и птицей. Она признала тебя хозяином.','Это важное упражнение, $N. Если ты хочешь стать сокольником, ты $Gдолжен:должна; научиться кормить свою птицу.','Накормить сокола фьорда') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Завоевание доверия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде всего сокольничий должен установить связь между собой и своей птицей, завоевать ее доверие. $B$B<Идальго указывает на соколов в клетке, стоящей у его ног.>$B$BЕсли хочешь, чтобы птицы тебе доверяли – накорми их до отвала!$B$BКак тебе, должно быть, известно, скальные соколы фьорда питаются в основном червяками. По всему фьорду легко можно найти расшатанные камни, под которыми обитает множество личинок. Найди червячка и накорми им сокола в клетке.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, $N. Я уже чувствую дружескую связь между тобой и птицей. Она признала тебя хозяином.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это важное упражнение, $N. Если ты хочешь стать сокольником, ты $Gдолжен:должна; научиться кормить свою птицу.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Накормить сокола фьорда',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11461,'ИСКЛЮЧЕНО') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','ИСКЛЮЧЕНО',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11462,'Красавчик Терри','Твои ребята хорошенько заплатили мне за то, чтобы я проторил тебе дорожку в шайку флибустьеров Северных морей.$B$BВ общем, я поговорил с одним парнем из Лагеря Скалаваг и сказал, что тебе можно доверять. Зовут его Красавчик Терри. $B$BНадевай этот маскарад и иди прямо к нему. Сейчас придет один из пиратов, который проводит тебя в лагерь.$B$BУчти, что тебе придется втереться к ним в доверие перед тем, как они решат представить тебя своим главарям. Теперь все зависит от тебя. Запомни, $n – в лагере ты можешь рассчитывать только на свои силы!','Наденьте костюм пирата и поговорите с Красавчиком Терри в Лагере Скалаваг.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Красавчик Терри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Твои ребята хорошенько заплатили мне за то, чтобы я проторил тебе дорожку в шайку флибустьеров Северных морей.$B$BВ общем, я поговорил с одним парнем из Лагеря Скалаваг и сказал, что тебе можно доверять. Зовут его Красавчик Терри. $B$BНадевай этот маскарад и иди прямо к нему. Сейчас придет один из пиратов, который проводит тебя в лагерь.$B$BУчти, что тебе придется втереться к ним в доверие перед тем, как они решат представить тебя своим главарям. Теперь все зависит от тебя. Запомни, $n – в лагере ты можешь рассчитывать только на свои силы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наденьте костюм пирата и поговорите с Красавчиком Терри в Лагере Скалаваг.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11463,'Пираты Северных морей','За последние несколько недель пираты совершили в два раза больше нападений на наши грузовые корабли. Нам пришлось нанять гоблинского шпиона, чтобы тот разведал путь внедрения нашего агента в шайку пиратов, которых мы подозреваем в этих злодеяниях.$B$BЯ говорю о банде флибустьеров Северных морей, которая обосновалась в Лагере Скалаваг на Рифе Гарвана. Про этих бандитов нам известно только одно: Сильвана хочет получить голову их предводителя. $B$BМне порекомендовали поручить это задание тебе, $n. Если ты справишься, мы сможем сосредоточить наши усилия на войне с Артасом. Так я могу на тебя рассчитывать?','Найдите Греззикса Иглохруста на северной части Рифа Гарвана. Риф находится на юго-западном побережье Ревущего фьорда.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пираты Северных морей',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','За последние несколько недель пираты совершили в два раза больше нападений на наши грузовые корабли. Нам пришлось нанять гоблинского шпиона, чтобы тот разведал путь внедрения нашего агента в шайку пиратов, которых мы подозреваем в этих злодеяниях.$B$BЯ говорю о банде флибустьеров Северных морей, которая обосновалась в Лагере Скалаваг на Рифе Гарвана. Про этих бандитов нам известно только одно: Сильвана хочет получить голову их предводителя. $B$BМне порекомендовали поручить это задание тебе, $n. Если ты справишься, мы сможем сосредоточить наши усилия на войне с Артасом. Так я могу на тебя рассчитывать?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Греззикса Иглохруста на северной части Рифа Гарвана. Риф находится на юго-западном побережье Ревущего фьорда.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11464,'Карточный долг','Говорят, ты работаешь на Терри. Я, признаться, ожидал увидеть кого-нибудь более благонадежного.$B$BВидишь ли, пираты обожают азартные игры. Правда, потом они очень не любят расплачиваться по долгам.$B$BЕсли ты не против стрясти кое с кого парочку звонких монет, то я с удовольствием отсыплю тебе твою долю.$B$BНачнем с чего-нибудь попроще – скажем, с Гарри "Луносвета". Эксцентричный парень, обожает всякие эльфийские побрякушки – но стоит ему увидеть меня, как он сразу прикидывается нищим и обделенным. Вытряси из него мое золото!','Тарук из Лагеря Скалаваг просит вас взыскать долг Гарри "Луносвета".','А, ты $gвернулся:вернулась;. Ну что, где мое золото?','Вернитесь к Таруку в Лагерь Скалаваг, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Карточный долг',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорят, ты работаешь на Терри. Я, признаться, ожидал увидеть кого-нибудь более благонадежного.$B$BВидишь ли, пираты обожают азартные игры. Правда, потом они очень не любят расплачиваться по долгам.$B$BЕсли ты не против стрясти кое с кого парочку звонких монет, то я с удовольствием отсыплю тебе твою долю.$B$BНачнем с чего-нибудь попроще – скажем, с Гарри "Луносвета". Эксцентричный парень, обожает всякие эльфийские побрякушки – но стоит ему увидеть меня, как он сразу прикидывается нищим и обделенным. Вытряси из него мое золото!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тарук из Лагеря Скалаваг просит вас взыскать долг Гарри "Луносвета".',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','А, ты $gвернулся:вернулась;. Ну что, где мое золото?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таруку в Лагерь Скалаваг, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11465,'Разграбленный караван','Я вел караван из Валгарда, когда на нас напали Укротители драконов. Выжить удалось только мне. К несчастью, я не смог довезти свой груз фьордовых индеек, но для тебя это будет легкой прогулкой!$B$B<Идальго протягивает вам клетку.>$B$BВот, возьми моего скального сокола и отправляйся на запад по дороге, ведущей из лагеря. Пусть сокол поймает сбежавших индеек, а ты принесешь их мне. $B$BТолько не забудь его покормить!','Хитрые мерзавцы! Но какие терпеливые! Мы должны перестать недооценивать нашего противника. Эти врайкулы – безжалостные убийцы!$B$BВпрочем, как бы то ни было, мы свое дело сделали. А тебе пора поохотиться на более ловкую дичь. Толстый индюк – разве это дело?','Всегда корми сокола до отвала перед охотой – иначе он съест всю добычу!','Вернитесь к сокольничему Идальго в Лагерь Лиги исследователей, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Разграбленный караван',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я вел караван из Валгарда, когда на нас напали Укротители драконов. Выжить удалось только мне. К несчастью, я не смог довезти свой груз фьордовых индеек, но для тебя это будет легкой прогулкой!$B$B<Идальго протягивает вам клетку.>$B$BВот, возьми моего скального сокола и отправляйся на запад по дороге, ведущей из лагеря. Пусть сокол поймает сбежавших индеек, а ты принесешь их мне. $B$BТолько не забудь его покормить!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хитрые мерзавцы! Но какие терпеливые! Мы должны перестать недооценивать нашего противника. Эти врайкулы – безжалостные убийцы!$B$BВпрочем, как бы то ни было, мы свое дело сделали. А тебе пора поохотиться на более ловкую дичь. Толстый индюк – разве это дело?',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Всегда корми сокола до отвала перед охотой – иначе он съест всю добычу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сокольничему Идальго в Лагерь Лиги исследователей, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11466,'Стаканчик для Джека','Наш следующий клиент, Джек Адамс, не такой простак, как Гарри. Он целыми днями выпивает в компании своих дружков – матерых пиратов. Силой тут действовать нельзя – можно пострадать. $B$BДавай лучше воспользуемся его пристрастием к бутылке. Рано или поздно он напьется так, что уже не сможет стоять на ногах. $B$BПоговори с девочками за стойкой – может быть, кто-нибудь из них тебе поможет. Как только он отрубится, запусти руку в его карман и забери то, что принадлежит мне.','Тарук из Лагеря Скалаваг просит вас взыскать долг Джека Адамса.','Ты $gзабрал:забрала; то, что принадлежит мне?','Вернитесь к Таруку в Лагерь Скалаваг, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Стаканчик для Джека',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наш следующий клиент, Джек Адамс, не такой простак, как Гарри. Он целыми днями выпивает в компании своих дружков – матерых пиратов. Силой тут действовать нельзя – можно пострадать. $B$BДавай лучше воспользуемся его пристрастием к бутылке. Рано или поздно он напьется так, что уже не сможет стоять на ногах. $B$BПоговори с девочками за стойкой – может быть, кто-нибудь из них тебе поможет. Как только он отрубится, запусти руку в его карман и забери то, что принадлежит мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тарук из Лагеря Скалаваг просит вас взыскать долг Джека Адамса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gзабрал:забрала; то, что принадлежит мне?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таруку в Лагерь Скалаваг, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11467,'Долг мертвеца','$gСлышал:Слышала; о Блэке Конраде? Он, пожалуй, самый знаменитый пират в наших краях.$B$BТак вот; повадился он делать ставки на моих боях, а потом не платить за проигрыш.$B$BХотел бы я стрясти с него должок, да вот только этот подлец взял и помер.$B$BЯ уж было забыл про это дельце, как вдруг мне в руки попала занятная штучка...$B$B<Тарук разворачивает карту острова Копий, помеченную крестиком на северо-восточном плато.>$B$BВидишь, какие дела? Этот забулдыга зарыл целый клад на земле клыкарров. Достань мне это сокровище! Смерть – еще не повод не возвращать мне долги!','Тарук из Лагеря Скалаваг просит вас выкопать сокровище Блэка Конрада с северо-восточного побережья острова Копий, что к северу от Искаала.','Конрад задолжал мне только золото - его-то я и заберу. Остальное можешь оставить себе.$B$BКстати, если тебе вдруг захочется подзаработать, обращайся ко мне. Пожалуй, я смогу найти для тебя дельце. Попутного тебе ветра, дружище!','Вернитесь к Таруку в Лагерь Скалаваг, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Долг мертвеца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$gСлышал:Слышала; о Блэке Конраде? Он, пожалуй, самый знаменитый пират в наших краях.$B$BТак вот; повадился он делать ставки на моих боях, а потом не платить за проигрыш.$B$BХотел бы я стрясти с него должок, да вот только этот подлец взял и помер.$B$BЯ уж было забыл про это дельце, как вдруг мне в руки попала занятная штучка...$B$B<Тарук разворачивает карту острова Копий, помеченную крестиком на северо-восточном плато.>$B$BВидишь, какие дела? Этот забулдыга зарыл целый клад на земле клыкарров. Достань мне это сокровище! Смерть – еще не повод не возвращать мне долги!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Тарук из Лагеря Скалаваг просит вас выкопать сокровище Блэка Конрада с северо-восточного побережья острова Копий, что к северу от Искаала.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конрад задолжал мне только золото - его-то я и заберу. Остальное можешь оставить себе.$B$BКстати, если тебе вдруг захочется подзаработать, обращайся ко мне. Пожалуй, я смогу найти для тебя дельце. Попутного тебе ветра, дружище!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Таруку в Лагерь Скалаваг, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11468,'Ястреб против сокола','Ты это чувствуешь, $n? Сейчас ты уже $gдолжен:должна; ощутить связь между собой и твоим соколом. Поверишь ли ты мне, если я скажу, что однажды ты сможешь взглянуть на мир глазами своей птицы? Да, это высшее мастерство, доступное лишь лучшим сокольничим. $B$BЧтобы достичь таких высот в нашем ремесле, надо много и упорно трудиться! Птица должна охотиться, оттачивать навыки и рефлексы. Выбери для нее более достойного противника! Скажем, ястребов фьорда, которые гнездятся на верхушках деревьев. Пусть они станут твоей следующей добычей!','Да, ястребы очень ревностно относятся к защите территорий и часто гнездятся большими стаями. Пожалуй, мне следовало предупредить тебя заранее.','Всегда корми сокола до отвала перед охотой – иначе он съест всю добычу!','Вернитесь к сокольничему Идальго в Лагерь Лиги исследователей, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ястреб против сокола',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты это чувствуешь, $n? Сейчас ты уже $gдолжен:должна; ощутить связь между собой и твоим соколом. Поверишь ли ты мне, если я скажу, что однажды ты сможешь взглянуть на мир глазами своей птицы? Да, это высшее мастерство, доступное лишь лучшим сокольничим. $B$BЧтобы достичь таких высот в нашем ремесле, надо много и упорно трудиться! Птица должна охотиться, оттачивать навыки и рефлексы. Выбери для нее более достойного противника! Скажем, ястребов фьорда, которые гнездятся на верхушках деревьев. Пусть они станут твоей следующей добычей!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, ястребы очень ревностно относятся к защите территорий и часто гнездятся большими стаями. Пожалуй, мне следовало предупредить тебя заранее.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Всегда корми сокола до отвала перед охотой – иначе он съест всю добычу!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сокольничему Идальго в Лагерь Лиги исследователей, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11469,'Мыло для чистки палуб','Ага, мне надо надраить палубу до того, как прибудет Безумный Иона. Только я не собираюсь ползать тут на четвереньках! $B$BУ меня, знаешь ли, мыло закончилось. Только это не моя проблема, а твоя, дружище. Ты у нас салага – так что тебе и бегать за припасами. $B$BНа северо-западном побережье острова полным-полно морских львов. Там, среди льдов, ты найдешь главного тюлева, Большого Роя. Принеси мне его сальник, и я сварганю нам лучшее мыло!','Побегушка Мерзлонос просит вас принести ей сальник Большого Роя, чтобы она могла сварить из него мыло для чистки палуб. Она ждет вас на восточном пиратском корабле в Лагере Скалаваг.','Вернитесь к Побегушке Мерзлонос в Лагерь Скалаваг, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мыло для чистки палуб',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ага, мне надо надраить палубу до того, как прибудет Безумный Иона. Только я не собираюсь ползать тут на четвереньках! $B$BУ меня, знаешь ли, мыло закончилось. Только это не моя проблема, а твоя, дружище. Ты у нас салага – так что тебе и бегать за припасами. $B$BНа северо-западном побережье острова полным-полно морских львов. Там, среди льдов, ты найдешь главного тюлева, Большого Роя. Принеси мне его сальник, и я сварганю нам лучшее мыло!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Побегушка Мерзлонос просит вас принести ей сальник Большого Роя, чтобы она могла сварить из него мыло для чистки палуб. Она ждет вас на восточном пиратском корабле в Лагере Скалаваг.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Побегушке Мерзлонос в Лагерь Скалаваг, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11470,'Птицы не знают о чести','Думаю, ты уже $gготов:готова; перейти на следующую ступень обучения соколиной охоте. $B$BОтнеси своего обученного сокола на восток, к Подъемнику Каменной стены, где гнездятся врайкульские ястребы. Они вьют гнезда в отдаленных расщелинах на обрыве. Найди, где они селятся, и поручи своему соколу украсть яйца из их гнезд.$B$BТолько остерегайся ястреба-матриарха фьорда. $n. Если она нападет на тебя, прикажи соколу подняться ввысь и беги!','$GМолодец:Умница;, $N! Браво! Ты чувствуешь, как окрепли узы, связывающие тебя с соколом? Возможно, вскоре мы сможем посылать вас на разведку врайкульских территорий!','Ты $Gхозяин:хозяйка; сокола, $N. Пошли его на добычу яиц.','Вернитесь к сокольничему Идальго в Лагерь Лиги исследователей, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Птицы не знают о чести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Думаю, ты уже $gготов:готова; перейти на следующую ступень обучения соколиной охоте. $B$BОтнеси своего обученного сокола на восток, к Подъемнику Каменной стены, где гнездятся врайкульские ястребы. Они вьют гнезда в отдаленных расщелинах на обрыве. Найди, где они селятся, и поручи своему соколу украсть яйца из их гнезд.$B$BТолько остерегайся ястреба-матриарха фьорда. $n. Если она нападет на тебя, прикажи соколу подняться ввысь и беги!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N! Браво! Ты чувствуешь, как окрепли узы, связывающие тебя с соколом? Возможно, вскоре мы сможем посылать вас на разведку врайкульских территорий!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gхозяин:хозяйка; сокола, $N. Пошли его на добычу яиц.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сокольничему Идальго в Лагерь Лиги исследователей, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11472,'Путь к его сердцу...','Пираты Cеверного моря убили вожака стаи рифовых буйволов, потому что им нужен был жир для варки мыла!$B$B<Ануниак грустно вздыхает.>$B$BТеперь морские львы не смогут размножаться. Помоги мне восстановить их численность.$B$BНа северном побережье Рифа Гарвана, что на юго-востоке отсюда, водится в изобилии рифовая смакрель. Поймай дюжину вкусных рыбин на восточных и западных берегах острова и подмани одного из буйволов прямо к рифовой корове.$B$BПоймать этих мальков просто – тебе даже не понадобится удочка.','Подкиньте несколько вкусных рифовых рыб рифовому буйволу, чтобы он последовал за вами к рифовой корове. Когда эти двое одиноких сердец найдут друг друга, вернитесь к Ануниаку в Камагуа.','Ну, сколько щенков можно было спасти за такое короткое время?','Сопроводить рифового буйвола к рифовой корове','Вернитесь к Ануниаку в Камагуа, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Путь к его сердцу...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пираты Cеверного моря убили вожака стаи рифовых буйволов, потому что им нужен был жир для варки мыла!$B$B<Ануниак грустно вздыхает.>$B$BТеперь морские львы не смогут размножаться. Помоги мне восстановить их численность.$B$BНа северном побережье Рифа Гарвана, что на юго-востоке отсюда, водится в изобилии рифовая смакрель. Поймай дюжину вкусных рыбин на восточных и западных берегах острова и подмани одного из буйволов прямо к рифовой корове.$B$BПоймать этих мальков просто – тебе даже не понадобится удочка.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Подкиньте несколько вкусных рифовых рыб рифовому буйволу, чтобы он последовал за вами к рифовой корове. Когда эти двое одиноких сердец найдут друг друга, вернитесь к Ануниаку в Камагуа.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, сколько щенков можно было спасти за такое короткое время?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Сопроводить рифового буйвола к рифовой корове',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ануниаку в Камагуа, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11473,'Предатель среди нас','В последнее время наша заместительница главаря, Энни Бонн, ударилась в паранойю. Всюду ей шпионы мерещатся, представляешь?$B$BА, впрочем, есть у нас давно испытанный метод выявления крыс на корабле. Видишь ли, дружище Зех\'ген – да, да, вон тот старикашка – настоящий колдун! Его предки обитали в самом Зул... как его там... неважно, в общем.$B$BИди, сообщи ему, что нам нужно воспользоваться его пророческим даром. Правда, должен тебя сразу предупредить – понять его непросто.','Поговорите с Зех\'геном в Лагере Скалаваг.','Ты ведь несешь мне мускусные железы, правда?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Предатель среди нас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В последнее время наша заместительница главаря, Энни Бонн, ударилась в паранойю. Всюду ей шпионы мерещатся, представляешь?$B$BА, впрочем, есть у нас давно испытанный метод выявления крыс на корабле. Видишь ли, дружище Зех\'ген – да, да, вон тот старикашка – настоящий колдун! Его предки обитали в самом Зул... как его там... неважно, в общем.$B$BИди, сообщи ему, что нам нужно воспользоваться его пророческим даром. Правда, должен тебя сразу предупредить – понять его непросто.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Зех\'геном в Лагере Скалаваг.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты ведь несешь мне мускусные железы, правда?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11474,'Беда на Крутых утесах','Ну, как всегда – вся тяжелая работа досталась мне и моим людям. К счастью, команда Максорфа погибла не напрасно. Шифр, который они обнаружили, поможет нам сделать перевод многих древних текстов, которые мы обнаружили во время раскопок – если, конечно, нам удастся до них добраться! Эти проклятые железные дворфы лезут, как вода из щелей, и пытаются забросать землей раскопы! Ты представляешь? Эти мерзавцы хотят закопать обратно все то, что мы с таким трудом подняли на поверхность!$B$BВ общем, иди и поговори с Уолтом. Он введет тебя в курс дела.','Поговорите с Уолтом.','Слушай, мелочь – мы и так уже лишились половины команды. Здесь, на крутых утесах остался наш последний оплот. Проклятые Железные дворфы захватили Руины Ивальда и раскопки Бейлгуна. Но у меня есть план, как вернуться обратно и отстоять наши находки до того, как они будут потеряны безвозвратно.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беда на Крутых утесах',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, как всегда – вся тяжелая работа досталась мне и моим людям. К счастью, команда Максорфа погибла не напрасно. Шифр, который они обнаружили, поможет нам сделать перевод многих древних текстов, которые мы обнаружили во время раскопок – если, конечно, нам удастся до них добраться! Эти проклятые железные дворфы лезут, как вода из щелей, и пытаются забросать землей раскопы! Ты представляешь? Эти мерзавцы хотят закопать обратно все то, что мы с таким трудом подняли на поверхность!$B$BВ общем, иди и поговори с Уолтом. Он введет тебя в курс дела.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Уолтом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слушай, мелочь – мы и так уже лишились половины команды. Здесь, на крутых утесах остался наш последний оплот. Проклятые Железные дворфы захватили Руины Ивальда и раскопки Бейлгуна. Но у меня есть план, как вернуться обратно и отстоять наши находки до того, как они будут потеряны безвозвратно.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11475,'Орудия труда','Я уже несколько дней изучаю это создание, $n. Пожалуй, я мог бы построить точную копию такого голема, но управлять им будет изнутри наш оператор. Думаю, так мы сможем обмануть Железных дворфов и проникнуть в Бейлгун.$B$BНо не могу же я собрать такую конструкцию с помощью молотка и кочерги! Мне нужны инструменты! Увы, мой набор остался в Руинах Ивальда, захваченных железными дворфами. Пожалуйста, верни мои инструменты!$B$BРуины Ивальда находятся далеко на северо-востоке.','Вот теперь я могу приступить к сборке. Ну, конечно, если у меня будут необходимые материалы. Полагаю, теперь ты займешься их поиском.','Этап первый: вернуть Уолту инструменты.','Вернитесь к Уолту в Лагерь Лиги исследователей, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орудия труда',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уже несколько дней изучаю это создание, $n. Пожалуй, я мог бы построить точную копию такого голема, но управлять им будет изнутри наш оператор. Думаю, так мы сможем обмануть Железных дворфов и проникнуть в Бейлгун.$B$BНо не могу же я собрать такую конструкцию с помощью молотка и кочерги! Мне нужны инструменты! Увы, мой набор остался в Руинах Ивальда, захваченных железными дворфами. Пожалуйста, верни мои инструменты!$B$BРуины Ивальда находятся далеко на северо-востоке.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот теперь я могу приступить к сборке. Ну, конечно, если у меня будут необходимые материалы. Полагаю, теперь ты займешься их поиском.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Этап первый: вернуть Уолту инструменты.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уолту в Лагерь Лиги исследователей, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11476,'Нож и лягушка','Знаешь, некоторые пираты... в общем, изъясняются на своем диалекте. Вот и Зех\'ген... скажем так, говорит на особом... языке.$B$BВ общем, насколько я понял, ему нужен нож и лягушка.$B$BУ Гарри "Луносвета" есть парочка дешевых ножей. Лягушек же легко найти в городе – так и прыгают повсюду. Хватай любую и тащи к Зех\'гену.$B$BЧестно говоря, не хотел бы я оказаться на месте этой несчастной твари.','Купите блестящий нож у Гарри "Луносвета" и поймайте скалавагскую лягушку. Отнесите все это Зех\'гену в Лагерь Скалаваг.','Ну, тащишь квакуху, салага?','Вернитесь к Зех\'гену в Лагерь Скалаваг, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нож и лягушка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Знаешь, некоторые пираты... в общем, изъясняются на своем диалекте. Вот и Зех\'ген... скажем так, говорит на особом... языке.$B$BВ общем, насколько я понял, ему нужен нож и лягушка.$B$BУ Гарри "Луносвета" есть парочка дешевых ножей. Лягушек же легко найти в городе – так и прыгают повсюду. Хватай любую и тащи к Зех\'гену.$B$BЧестно говоря, не хотел бы я оказаться на месте этой несчастной твари.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Купите блестящий нож у Гарри "Луносвета" и поймайте скалавагскую лягушку. Отнесите все это Зех\'гену в Лагерь Скалаваг.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, тащишь квакуху, салага?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зех\'гену в Лагерь Скалаваг, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11477,'Дворф другой породы','Тише, тише, |3-6($r). Эти железные дворфы такие вспыльчивые! Кстати, не думай, что они тут занимаются раскопками. Как раз наоборот! Эти железношкурые мерзавцы засыпают все наши находки землей! Похоже, они не хотят, чтобы кто-то обнаружил это место. $B$BНет, ну ты скажи мне – что это за дворф, который не интересуется археологическими находками? А я скажу тебе: увидишь такого дворфа – убей на месте! Иди, задай им трепку!','$GМолодец:Умница;, $N. Это их ненадолго замедлит.','Вернитесь к Донни на Руины Ивальда, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дворф другой породы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тише, тише, |3-6($r). Эти железные дворфы такие вспыльчивые! Кстати, не думай, что они тут занимаются раскопками. Как раз наоборот! Эти железношкурые мерзавцы засыпают все наши находки землей! Похоже, они не хотят, чтобы кто-то обнаружил это место. $B$BНет, ну ты скажи мне – что это за дворф, который не интересуется археологическими находками? А я скажу тебе: увидишь такого дворфа – убей на месте! Иди, задай им трепку!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','$GМолодец:Умница;, $N. Это их ненадолго замедлит.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Донни на Руины Ивальда, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11478,'На той заставе...','Да, это не то, что мы хотели знать. По крайней мере, Донни все еще жив.','Новости от Донни?','Вернитесь к Станваду в Ревущий фьорд.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На той заставе...',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Да, это не то, что мы хотели знать. По крайней мере, Донни все еще жив.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Новости от Донни?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Станваду в Ревущий фьорд.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11479,'"Хромой" Дэн','Квакша назвала предателя! Кракен ему в глотку, вонючей крысе. Это "Хромой" Дэн, который прячется вон там, на корабле.$B$BИди-ка, проучи этого сосунка. Пусть знает – с пиратами шутки плохи. Топай к Терри, как протащишь этого мерзавца под килем.','Проучите "Хромого" Дэна, который прячется на одном из кораблей в Лагере Скалаваг. Когда выполните это задание, поговорите с Красавчиком Терри.','Не могу поверить, что это был Дэн. Ты уже разобрался с ним?','Вернитесь к Красавчику Терри в Лагерь Скалаваг, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Хромой" Дэн',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Квакша назвала предателя! Кракен ему в глотку, вонючей крысе. Это "Хромой" Дэн, который прячется вон там, на корабле.$B$BИди-ка, проучи этого сосунка. Пусть знает – с пиратами шутки плохи. Топай к Терри, как протащишь этого мерзавца под килем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проучите "Хромого" Дэна, который прячется на одном из кораблей в Лагере Скалаваг. Когда выполните это задание, поговорите с Красавчиком Терри.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не могу поверить, что это был Дэн. Ты уже разобрался с ним?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Красавчику Терри в Лагерь Скалаваг, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11480,'Познакомьтесь с номером два','Проделанная тобой работа не осталась незамеченной, $n. Наш второй командир, несравненная Энни Бонн, глубоко впечатлена твоими достижениями и мечтает с тобой познакомиться.','Поговорите с Энни Бонн в Лагере Скалаваг.','Не могу поверить, что это был Дэн. Ты уже разобрался с ним?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Познакомьтесь с номером два',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Проделанная тобой работа не осталась незамеченной, $n. Наш второй командир, несравненная Энни Бонн, глубоко впечатлена твоими достижениями и мечтает с тобой познакомиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Энни Бонн в Лагере Скалаваг.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не могу поверить, что это был Дэн. Ты уже разобрался с ним?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11481,'Чрезвычайная ситуация у Солнечного Колодца','Еще подмога из Шаттрата? Радостное зрелище!$B$BХотелось бы, чтобы помощь была побольше, но будем обходиться тем, что есть. События ждать нас не будут.$B$BОглядись вокруг, $C. Здесь многое надо сделать. Подключайся и делай свое дело.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чрезвычайная ситуация у Солнечного Колодца',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Еще подмога из Шаттрата? Радостное зрелище!$B$BХотелось бы, чтобы помощь была побольше, но будем обходиться тем, что есть. События ждать нас не будут.$B$BОглядись вокруг, $C. Здесь многое надо сделать. Подключайся и делай свое дело.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11482,'Зов долга','Датрис Солнцесвет из Яруса Провидцев Шаттрата настаивает, чтобы вы отправлись в Азерот немедленно, и доложились Ларетору у Солнечного Колодца.','Добро пожаловать на плато Солнечного Колодца!$B$BПерейдем к делу. Тут надо кое-что привести в порядок. За этими стенами творятся непростые дела, и в интересах наших народов надо с ними разобраться. И поскольку в одиночку никто из нас не справится, мы будем трудиться ВМЕСТЕ. Понятно?$B$BНу, так начнем?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зов долга',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Датрис Солнцесвет из Яруса Провидцев Шаттрата настаивает, чтобы вы отправлись в Азерот немедленно, и доложились Ларетору у Солнечного Колодца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Добро пожаловать на плато Солнечного Колодца!$B$BПерейдем к делу. Тут надо кое-что привести в порядок. За этими стенами творятся непростые дела, и в интересах наших народов надо с ними разобраться. И поскольку в одиночку никто из нас не справится, мы будем трудиться ВМЕСТЕ. Понятно?$B$BНу, так начнем?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11483,'Мы тоже так можем!','Превосходно. Теперь мы покроем эту штуку кожей – и получим точную копию создания, которых используют Железные дворфы.','Вернитесь к Уолту в Лагерь Лиги исследователей, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы тоже так можем!',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходно. Теперь мы покроем эту штуку кожей – и получим точную копию создания, которых используют Железные дворфы.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уолту в Лагерь Лиги исследователей, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11484,'Мы знаем технологию','Как только механизм будет готов, я закончу работу над этим устройством.','Очень скоро мы снова займемся раскопками!','Вернитесь к Уолту в Лагерь Лиги исследователей, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы знаем технологию',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как только механизм будет готов, я закончу работу над этим устройством.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Очень скоро мы снова займемся раскопками!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уолту в Лагерь Лиги исследователей, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (11485,'Ну ладно, $n. Забирайся в эту штуковину – будем учить тебя основам управления. Как будешь $gготов:готова;, садись на верстак, и я помогу тебе занять место пилота внутри голема.$B$BДля начала попробуй понять принципы передвижения. Видишь вон те руны, которые железные дворфы вырезали вокруг раскопа? Големы используют их энергию, чтобы перелетать с места на место. Потренируйся вот на этой руне, которую я вырезал для тебя.','Скоро ты сможешь испытать эту штучку в деле, $N!','Не принимай близко слова этих скептиков!','Отработать "Реактивный прыжок"') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну ладно, $n. Забирайся в эту штуковину – будем учить тебя основам управления. Как будешь $gготов:готова;, садись на верстак, и я помогу тебе занять место пилота внутри голема.$B$BДля начала попробуй понять принципы передвижения. Видишь вон те руны, которые железные дворфы вырезали вокруг раскопа? Големы используют их энергию, чтобы перелетать с места на место. Потренируйся вот на этой руне, которую я вырезал для тебя.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Скоро ты сможешь испытать эту штучку в деле, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не принимай близко слова этих скептиков!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Отработать "Реактивный прыжок"',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11486,'Лучшее пиво','Правда же, $gумный мальчик:умная девочка; вроде тебя хочет положить конец вражде? Пусть хотя бы Хмельной фестиваль пройдет без сучка без задоринки. Предлагаю сделку.$b$bОтнеси эту бочку нашего лучшего пива распорядителю Хмельного фестиваля в Стальгорн, чтобы все попробовали и продукцию дворфов Черного Железа! Лучшие напитки Азерота варят в глубинах этой горы, не забывай!','Отнесите бочонок эля Черного Железа Ипфелькоферу Железному Бочонку в Дун Морог.','Итак, ты $Gпосетил:посетила; Черное Железо и $Gхотел:хотела; положить конец их вражде? Ранее они снова атаковали. Похоже, слово клана Черного Железа ничем не хуже его отвара, а?$B$BТем не менее, то, что ты $Gсделал:сделала;, чтобы помочь, мы ценим. Вот, возьми кружку «эля», которую ты $Gпринес:принесла; из глубин горы в награду. Победа над всем этим Черным Железом!','Что это?','Вернитесь к Ипфелькоферу Железному Бочонку в Дун Морог.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучшее пиво',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Правда же, $gумный мальчик:умная девочка; вроде тебя хочет положить конец вражде? Пусть хотя бы Хмельной фестиваль пройдет без сучка без задоринки. Предлагаю сделку.$b$bОтнеси эту бочку нашего лучшего пива распорядителю Хмельного фестиваля в Стальгорн, чтобы все попробовали и продукцию дворфов Черного Железа! Лучшие напитки Азерота варят в глубинах этой горы, не забывай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите бочонок эля Черного Железа Ипфелькоферу Железному Бочонку в Дун Морог.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, ты $Gпосетил:посетила; Черное Железо и $Gхотел:хотела; положить конец их вражде? Ранее они снова атаковали. Похоже, слово клана Черного Железа ничем не хуже его отвара, а?$B$BТем не менее, то, что ты $Gсделал:сделала;, чтобы помочь, мы ценим. Вот, возьми кружку «эля», которую ты $Gпринес:принесла; из глубин горы в награду. Победа над всем этим Черным Железом!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ипфелькоферу Железному Бочонку в Дун Морог.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11487,'Лучшее пиво','Правда же, $gумный мальчик:умная девочка; вроде тебя хочет положить конец вражде? Пусть хотя бы Хмельной фестиваль пройдет без сучка без задоринки. Предлагаю сделку.$b$bОтнеси эту бочку нашего лучшего пива распорядителю Хмельного фестиваля в Оргриммар, чтобы все попробовали и продукцию дворфов Черного Железа! Лучшие напитки Азерота варят в глубинах этой горы, не забывай!','Отнесите бочонок эля Черного Железа Слухарю Жмухли в Дуротар.','Итак, ты $Gпосетил:посетила; Черное Железо и $Gхотел:хотела; положить конец их вражде? Ранее они снова атаковали. Похоже, слово клана Черного Железа ничем не хуже его отвара, а?$B$BТем не менее, то, что ты $Gсделал:сделала;, чтобы помочь, мы ценим. Вот, возьми кружку «эля», которую ты $Gпринес:принесла; из глубин горы в награду. Нет, правда. Это меньшее, что я могу сделать.','Что это у тебя там?','Вернитесь к Слухарю Жмухли в Дуротар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Лучшее пиво',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Правда же, $gумный мальчик:умная девочка; вроде тебя хочет положить конец вражде? Пусть хотя бы Хмельной фестиваль пройдет без сучка без задоринки. Предлагаю сделку.$b$bОтнеси эту бочку нашего лучшего пива распорядителю Хмельного фестиваля в Оргриммар, чтобы все попробовали и продукцию дворфов Черного Железа! Лучшие напитки Азерота варят в глубинах этой горы, не забывай!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите бочонок эля Черного Железа Слухарю Жмухли в Дуротар.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Итак, ты $Gпосетил:посетила; Черное Железо и $Gхотел:хотела; положить конец их вражде? Ранее они снова атаковали. Похоже, слово клана Черного Железа ничем не хуже его отвара, а?$B$BТем не менее, то, что ты $Gсделал:сделала;, чтобы помочь, мы ценим. Вот, возьми кружку «эля», которую ты $Gпринес:принесла; из глубин горы в награду. Нет, правда. Это меньшее, что я могу сделать.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя там?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Слухарю Жмухли в Дуротар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11488,'Терраса Магистров','Добро пожаловать в Солнечный Колодец, |3-6($c). Устраивайся и помогай чем можешь – дел невпроворот!$b$bЯ? Да, у меня есть небольшое дело, но вряд ли ты за него возьмешься.$b$bМы внедрили на Террасу Магистров разведчика. В последний раз он не вышел на связь, и я начинаю тревожиться.$b$bТерраса находится вверх по склону на востоке. Информация просто необходима для нашей миссии.$b$bКак думаешь, ты справишься, |3-6($r)?','Экзарх Ларетор с подготовительного плацдарма Расколотого Солнца просит вас найти на Террасе Магистров своего разведчика – эльфа крови Тирита.','... Подойди ближе, $R... Слушай внимательно...','Я не помню, чтобы заказывал услуги по очистке ... ну да, я аптекарь Хаммел.$B$B... подождите, что это значит? Думаешь, эти бессмысленные бумаги могут меня остановить? Ха!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Терраса Магистров',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать в Солнечный Колодец, |3-6($c). Устраивайся и помогай чем можешь – дел невпроворот!$b$bЯ? Да, у меня есть небольшое дело, но вряд ли ты за него возьмешься.$b$bМы внедрили на Террасу Магистров разведчика. В последний раз он не вышел на связь, и я начинаю тревожиться.$b$bТерраса находится вверх по склону на востоке. Информация просто необходима для нашей миссии.$b$bКак думаешь, ты справишься, |3-6($r)?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Экзарх Ларетор с подготовительного плацдарма Расколотого Солнца просит вас найти на Террасе Магистров своего разведчика – эльфа крови Тирита.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','... Подойди ближе, $R... Слушай внимательно...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я не помню, чтобы заказывал услуги по очистке ... ну да, я аптекарь Хаммел.$B$B... подождите, что это значит? Думаешь, эти бессмысленные бумаги могут меня остановить? Ха!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11489,'Мало просто управлять этим големом – надо еще уметь собирать информацию. Вот, смотри – я кладу в тележку реликвию железных дворфов. Это такой парящий, мерцающий кристалл.$B$BСадись обратно на верстак, и я помогу тебе занять место пилота. Как только устроишься внутри, воспользуйся способностью "Сбор информации", чтобы поднять тренировочный образец.','Отлично! Это просто волшебство какое-то!','Вернитесь к Уолту в Лагерь Лиги исследователей, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мало просто управлять этим големом – надо еще уметь собирать информацию. Вот, смотри – я кладу в тележку реликвию железных дворфов. Это такой парящий, мерцающий кристалл.$B$BСадись обратно на верстак, и я помогу тебе занять место пилота. Как только устроишься внутри, воспользуйся способностью "Сбор информации", чтобы поднять тренировочный образец.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Это просто волшебство какое-то!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уолту в Лагерь Лиги исследователей, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (11491,'Запомни: всегда имей наготове "План Б" – на случай, если основной замысел не удастся! Вот почему я встроил в этого голема кое-какие оборонительные системы. $B$BТакое новенькое, сверкающее устройство может вызвать подозрения у дворфов раскопки Бейлгуна. Вот тут-то и пригодится твоя "Обманка"! Пользуйся этой способностью каждый раз, когда на тебя кто-то нападет, и ты избежишь неприятностей.$B$BИди, потренируйся на Лебронски – потопчись на его коврике. А когда он начнет возмущаться, воспользуйся "Обманкой"! $B$BДавай, садись на верстак.','Не беспокойся о нем, $N. Он переживет это ...','Применить "Обманку" на Лебронски') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Запомни: всегда имей наготове "План Б" – на случай, если основной замысел не удастся! Вот почему я встроил в этого голема кое-какие оборонительные системы. $B$BТакое новенькое, сверкающее устройство может вызвать подозрения у дворфов раскопки Бейлгуна. Вот тут-то и пригодится твоя "Обманка"! Пользуйся этой способностью каждый раз, когда на тебя кто-то нападет, и ты избежишь неприятностей.$B$BИди, потренируйся на Лебронски – потопчись на его коврике. А когда он начнет возмущаться, воспользуйся "Обманкой"! $B$BДавай, садись на верстак.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не беспокойся о нем, $N. Он переживет это ...',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Применить "Обманку" на Лебронски',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11492,'Страшный противник','Добро пожаловать к Солнечному Колодцу, смертные. Воистину, вовремя вы пришли.$b$bКак видите, силы Легиона неустанно трудились, управляя мощью Колодца, чтобы достичь своих злых целей.$b$bКель\'тас восстал из пепла поражения и вновь направляет их усилия. Найдите его, смертные. Его снова надо остановить.$b$bМеня зовут иные, не менее важные дела. Судьбу Кель\'таса поручаю вам. Не подведите.$b$bЕсли удача пребудет с нами, мы еще встретимся.','Калесгос велит вам уничтожить Кель\'таса на Террасе Магистров. Отрубите Келю голову и вернитесь с донесением к Ларетору на подготовительный плацдарм армии Расколотого Солнца.','<Ларетор внимательно слушает ваш рассказ о том, что произошло на Террасе Магистров.>$B$BНам будет очень не хватать Тирита. Славный был воин - и надежный товарищ. Но, благодаря тебе, его смерть не стала напрасной.','Да, $C, должен признаться, я не был уверен, что увижу тебя снова.','Вернитесь к экзарху Ларетору на Остров Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Страшный противник',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать к Солнечному Колодцу, смертные. Воистину, вовремя вы пришли.$b$bКак видите, силы Легиона неустанно трудились, управляя мощью Колодца, чтобы достичь своих злых целей.$b$bКель\'тас восстал из пепла поражения и вновь направляет их усилия. Найдите его, смертные. Его снова надо остановить.$b$bМеня зовут иные, не менее важные дела. Судьбу Кель\'таса поручаю вам. Не подведите.$b$bЕсли удача пребудет с нами, мы еще встретимся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Калесгос велит вам уничтожить Кель\'таса на Террасе Магистров. Отрубите Келю голову и вернитесь с донесением к Ларетору на подготовительный плацдарм армии Расколотого Солнца.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Ларетор внимательно слушает ваш рассказ о том, что произошло на Террасе Магистров.>$B$BНам будет очень не хватать Тирита. Славный был воин - и надежный товарищ. Но, благодаря тебе, его смерть не стала напрасной.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $C, должен признаться, я не был уверен, что увижу тебя снова.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к экзарху Ларетору на Остров Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11493,'UNUSED') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','UNUSED',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11494,'Заряженные молнией артефакты','Ну, все. Твой голем готов. Все механизмы смазаны, все программы проверены. Заодно я научил его понимать язык титанов.$B$BДавай, отведи его к раскопкам Бейлгуна, к югу отсюда, и собери данные о заряженных молнией артефактах, которые лежат по всему раскопу. Не забудь включать "Обманку" каждый раз, когда твой голем вызовет подозрение у Железных дворфов. Чтобы перепрыгивать с руны на руну, пользуйся "Реактивным прыжком". $B$BЗабирайся на верстак, когда будешь $gготов:готова; отправиться в путь!','И снова Уолт доказал, что он умнее всех дворфов! Ну, что ты теперь скажешь про моего голема, $N?$B$BСпасибо, $N. Эта информация чрезвычайно важна. Знать бы еще, как извлечь ее из этого механизма...','Вернитесь к Уолту в Лагерь Лиги исследователей, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заряженные молнией артефакты',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, все. Твой голем готов. Все механизмы смазаны, все программы проверены. Заодно я научил его понимать язык титанов.$B$BДавай, отведи его к раскопкам Бейлгуна, к югу отсюда, и собери данные о заряженных молнией артефактах, которые лежат по всему раскопу. Не забудь включать "Обманку" каждый раз, когда твой голем вызовет подозрение у Железных дворфов. Чтобы перепрыгивать с руны на руну, пользуйся "Реактивным прыжком". $B$BЗабирайся на верстак, когда будешь $gготов:готова; отправиться в путь!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','И снова Уолт доказал, что он умнее всех дворфов! Ну, что ты теперь скажешь про моего голема, $N?$B$BСпасибо, $N. Эта информация чрезвычайно важна. Знать бы еще, как извлечь ее из этого механизма...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Уолту в Лагерь Лиги исследователей, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (11495,'Нежный звук грома','Во время раскопок Бейлгуна мы наткнулись на пещеру, которую до сих пор обходят стороной даже самые отважные исследователи. Честно говоря, я их понимаю... Трудно остаться хладнокровным, когда из самого чрева пещеры доносятся ужасные раскаты грома!$B$BВ итоге мы прекратили раскопки в этом месте. Страшные беды постигли тех, кто отважился войти в пещеру – многие остались там навсегда.$B$BПрошу тебя, $n, осмотри это место, когда окажешься на раскопках, и расскажи мне о том, что тебе удастся обнаружить. Грохочущая пещера находится возле статуи титана.','Невероятно! Что же еще задумали эти железные существа? Что они делают на Грозовой Гряде? И кто такой Локен?! Надо незамедлительно передать эту информацию на центральную базу в Драконьем Погосте. Не волнуйся, $N, я не забуду упомянуть о твоих заслугах.','Ну, как успехи?','Грохочущая пещера исследована') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нежный звук грома',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время раскопок Бейлгуна мы наткнулись на пещеру, которую до сих пор обходят стороной даже самые отважные исследователи. Честно говоря, я их понимаю... Трудно остаться хладнокровным, когда из самого чрева пещеры доносятся ужасные раскаты грома!$B$BВ итоге мы прекратили раскопки в этом месте. Страшные беды постигли тех, кто отважился войти в пещеру – многие остались там навсегда.$B$BПрошу тебя, $n, осмотри это место, когда окажешься на раскопках, и расскажи мне о том, что тебе удастся обнаружить. Грохочущая пещера находится возле статуи титана.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Невероятно! Что же еще задумали эти железные существа? Что они делают на Грозовой Гряде? И кто такой Локен?! Надо незамедлительно передать эту информацию на центральную базу в Драконьем Погосте. Не волнуйся, $N, я не забуду упомянуть о твоих заслугах.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как успехи?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Грохочущая пещера исследована',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11496,'Охрана святилища','Важнейшая наша задача – захватить святилище Солнечного Края. Как только мы его захватим, мы сможем использовать его энергию для открытия портала из Шаттрата.$B$BСейчас святилище захвачено Презренными – бывшими эльфами крови, которые опустились до того, что стали тупыми подобиями себя прежних. Будь все в порядке, защитное поле колодца само не пустило бы их, но Презренные украли источник энергии защитного поля колодца.$B$BПеребей Презренных и собери с них клочки маны. Используй их для подпитки защитного поля святилища.','Капитан Терис Сердце Рассвета с подготовительного плацдарма Расколотого Солнца просит вас добыть 4 клочка маны у презренных-злобней и презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке.','Хорошая работа, $N. Палаты постепенно восстанавливают свою энергию. Святилище будет нашим в мгновение ока!','Вы активировали кристалл, $N?','Активировать защитное поле кристалла-хранителя.','Вернитесь к капитану Терису Рассветному Пламени на Подготовительный плацдарм Расколотого Солнца, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охрана святилища',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Важнейшая наша задача – захватить святилище Солнечного Края. Как только мы его захватим, мы сможем использовать его энергию для открытия портала из Шаттрата.$B$BСейчас святилище захвачено Презренными – бывшими эльфами крови, которые опустились до того, что стали тупыми подобиями себя прежних. Будь все в порядке, защитное поле колодца само не пустило бы их, но Презренные украли источник энергии защитного поля колодца.$B$BПеребей Презренных и собери с них клочки маны. Используй их для подпитки защитного поля святилища.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Терис Сердце Рассвета с подготовительного плацдарма Расколотого Солнца просит вас добыть 4 клочка маны у презренных-злобней и презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $N. Палаты постепенно восстанавливают свою энергию. Святилище будет нашим в мгновение ока!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы активировали кристалл, $N?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Активировать защитное поле кристалла-хранителя.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Терису Рассветному Пламени на Подготовительный плацдарм Расколотого Солнца, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11497,'Орлята учатся летать','Хотя в перспективе это может повредить моему бизнесу, у тебя прямо на лбу написана мечта о полете, о том, чтобы завести своего летуна, чтобы парить в небесах, а не так, чтобы тебя перевозили с места на место.$B$BПолностью тебя понимаю.$B$BТебе, дружок, надо пойти в цитадель Громового Молота на юго-западном краю Долины Призрачной Луны. Доберешься туда – поговори с Ильсой Бурное Варево по поводу обучения полетам. Учти – ее наставления стоят недешево. Но они того стоят.','Поговорите с Илсой Бурное Варево в цитадели Громового Молота в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орлята учатся летать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя в перспективе это может повредить моему бизнесу, у тебя прямо на лбу написана мечта о полете, о том, чтобы завести своего летуна, чтобы парить в небесах, а не так, чтобы тебя перевозили с места на место.$B$BПолностью тебя понимаю.$B$BТебе, дружок, надо пойти в цитадель Громового Молота на юго-западном краю Долины Призрачной Луны. Доберешься туда – поговори с Ильсой Бурное Варево по поводу обучения полетам. Учти – ее наставления стоят недешево. Но они того стоят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Илсой Бурное Варево в цитадели Громового Молота в Долине Призрачной Луны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11498,'Орлята учатся летать','Хотя в перспективе это может повредить моему бизнесу, у тебя прямо на лбу написана мечта о полете, о том, чтобы завести своего летуна, чтобы парить в небесах, а не так, чтобы тебя перевозили с места на место.$B$BПолностью тебя понимаю.$B$BТебе, дружок, надо пойти в Деревню Призрачной Луны на северо-западном краю Долины Призрачной Луны. Доберешься туда – поговори с Олрокком по поводу обучения полетам. Учти – его наставления стоят недешево. Но они того стоят.','Поговорите с Олрокком в Деревне Призрачной Луны в Долине Призрачной Луны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орлята учатся летать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хотя в перспективе это может повредить моему бизнесу, у тебя прямо на лбу написана мечта о полете, о том, чтобы завести своего летуна, чтобы парить в небесах, а не так, чтобы тебя перевозили с места на место.$B$BПолностью тебя понимаю.$B$BТебе, дружок, надо пойти в Деревню Призрачной Луны на северо-западном краю Долины Призрачной Луны. Доберешься туда – поговори с Олрокком по поводу обучения полетам. Учти – его наставления стоят недешево. Но они того стоят.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Олрокком в Деревне Призрачной Луны в Долине Призрачной Луны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11499,'Значит, на сей раз принц эльфов крови и правда мертв? Жаль, я всегда считал, что он умеет вести себя в обществе. Подумать только – такую личность могут убить за такую плевую сумму.$B$BНо, как говорится, дело есть дело. Вы заслужили свою награду, $Gискатель:искательница; приключений.$B$BВозвращайтесь завтра, и у меня найдется для вас другое порученьице','Терраса Магистров, наверное, очень опасное место – слишком уж близко оно к Солнечному Колодцу.$B$BНадеюсь, вы не передумали?','Вернитесь к торговцу ветром Зариму в лес Тероккар.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, на сей раз принц эльфов крови и правда мертв? Жаль, я всегда считал, что он умеет вести себя в обществе. Подумать только – такую личность могут убить за такую плевую сумму.$B$BНо, как говорится, дело есть дело. Вы заслужили свою награду, $Gискатель:искательница; приключений.$B$BВозвращайтесь завтра, и у меня найдется для вас другое порученьице',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Терраса Магистров, наверное, очень опасное место – слишком уж близко оно к Солнечному Колодцу.$B$BНадеюсь, вы не передумали?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к торговцу ветром Зариму в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11500,'Ловчий Пустоты Ма\'дуун хочет, чтобы вы убили 4 сестер Терзаний. Вернитесь к нему в Нижний Город Шаттрата, когда перебьете их, чтобы забрать награду.','Кто может сказать, зачем нужно было убивать демонических сестер? Тебе не все ли равно?$B$BМа\'дуун думает, что вы сделали достаточно, чтобы получить награду.$B$BВозвращайтесь завтра, и ветры снова прошепчут Ма\'дууну.','Вы еще не разобрались с сестрами.','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.') ON DUPLICATE KEY UPDATE `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Ловчий Пустоты Ма\'дуун хочет, чтобы вы убили 4 сестер Терзаний. Вернитесь к нему в Нижний Город Шаттрата, когда перебьете их, чтобы забрать награду.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кто может сказать, зачем нужно было убивать демонических сестер? Тебе не все ли равно?$B$BМа\'дуун думает, что вы сделали достаточно, чтобы получить награду.$B$BВозвращайтесь завтра, и ветры снова прошепчут Ма\'дууну.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы еще не разобрались с сестрами.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ловчему Пустоты Ма\'дууну в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11501,'Вести с востока','$n, я хочу, чтобы ты лично $gдоложил:доложила; капитану Адамсу из Крепости Западной Стражи о том, что здесь происходит.$B$BДай мне знать, когда ты будешь $gготов:готова; отправиться в путь, и я посажу тебя в голема. Он доставит тебя в Крепость Западной Стражи – если не развалится на полпути.$B$BБыло приятно с тобой работать...','Поговорите с капитаном Адамсом из Крепости Западной Стражи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вести с востока',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, я хочу, чтобы ты лично $gдоложил:доложила; капитану Адамсу из Крепости Западной Стражи о том, что здесь происходит.$B$BДай мне знать, когда ты будешь $gготов:готова; отправиться в путь, и я посажу тебя в голема. Он доставит тебя в Крепость Западной Стражи – если не развалится на полпути.$B$BБыло приятно с тобой работать...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Адамсом из Крепости Западной Стражи.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11502,'Защита Халаа','Мы не воинственная раса, |3-6($r). Но когда война приходит на наш порог, мы не бежим от нее.$B$BАльянс и Орда ведут войну в Халаа, на северо-западе отсюда. Мы не знаем, что затевают эти эльфы крови, но если победит Орда – это будет катастрофа. Между нами и орками старинная вражда, кровь и предательство.$B$BИди и убивай врагов в Халаа, и получишь золото, славу и честь!','Победите 10 игроков вражеской стороны в Халаа и вернитесь в Телаар к Лакууру.','Вернитесь к Лакууру в Телаар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Защита Халаа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не воинственная раса, |3-6($r). Но когда война приходит на наш порог, мы не бежим от нее.$B$BАльянс и Орда ведут войну в Халаа, на северо-западе отсюда. Мы не знаем, что затевают эти эльфы крови, но если победит Орда – это будет катастрофа. Между нами и орками старинная вражда, кровь и предательство.$B$BИди и убивай врагов в Халаа, и получишь золото, славу и честь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите 10 игроков вражеской стороны в Халаа и вернитесь в Телаар к Лакууру.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лакууру в Телаар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11503,'Враги старые и враги новые','Наши старинные враги, дренеи, вернулись с могущественными союзниками. Они ведут войну в Халаа, к юго-западу отсюда.$B$BМы не должны дать им победить, потому что потом они, вне всякого сомнения, ударят на Гарадар.$B$BИди и перебей тех, кто помогает нашим старинным врагам.','Победите 10 игроков вражеской стороны в Халаа и вернитесь в Гарадар к Карртогу.','Ты приносишь великую честь нашему народу. Прими нашу благодарность.','Твоя задача выполнена, $N?','Вернитесь к Карртогу в Гарадар, что в Награнде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враги старые и враги новые',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши старинные враги, дренеи, вернулись с могущественными союзниками. Они ведут войну в Халаа, к юго-западу отсюда.$B$BМы не должны дать им победить, потому что потом они, вне всякого сомнения, ударят на Гарадар.$B$BИди и перебей тех, кто помогает нашим старинным врагам.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Победите 10 игроков вражеской стороны в Халаа и вернитесь в Гарадар к Карртогу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты приносишь великую честь нашему народу. Прими нашу благодарность.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Твоя задача выполнена, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Карртогу в Гарадар, что в Награнде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11504,'Ожившие мертвецы','Клыкарры обычно охотятся на восточной дороге – во всяком случае, так было раньше...$B$BНедавно наши охотники вернулись из Камагуа с ужасной вестью – будто бы мертвецы восстали из могил и жаждут нашей крови! Старейшина Атуик поручил мне и моему сыну разобраться с этой проблемой.$B$BПротянешь ли ты нам руку помощи в час нужды? Я ищу героев, которые отважатся преступить границы Заградительного холма, что к юго-востоку отсюда. Осмотри раскопанные могилы и доложи мне о своих находках.','Орфус Камагуанский с Древнего подъемника просит вас принести ему улики из могил Фенгира, Родина, Исулдофа и Ветрана.','<Усы Орфуса гневно топорщатся.>$B$BПираты... Кто положит конец их бесчинствам?$B$BМы должны разыскать украденные артефакты и вернуть их на место. Только тогда мой народ будет в безопасности.','Клыкаррам нужна твоя помощь!','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ожившие мертвецы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клыкарры обычно охотятся на восточной дороге – во всяком случае, так было раньше...$B$BНедавно наши охотники вернулись из Камагуа с ужасной вестью – будто бы мертвецы восстали из могил и жаждут нашей крови! Старейшина Атуик поручил мне и моему сыну разобраться с этой проблемой.$B$BПротянешь ли ты нам руку помощи в час нужды? Я ищу героев, которые отважатся преступить границы Заградительного холма, что к юго-востоку отсюда. Осмотри раскопанные могилы и доложи мне о своих находках.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Орфус Камагуанский с Древнего подъемника просит вас принести ему улики из могил Фенгира, Родина, Исулдофа и Ветрана.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Усы Орфуса гневно топорщатся.>$B$BПираты... Кто положит конец их бесчинствам?$B$BМы должны разыскать украденные артефакты и вернуть их на место. Только тогда мой народ будет в безопасности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Клыкаррам нужна твоя помощь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (11505,'Духи Аукиндона','Духам Аукиндона нет дела до усобиц Альянса и Орды, но заслужив их расположение, наша сторона получит преимущество в этих краях.$B$BДревний обычай велит живым поклоняться Башням Духов в Костяных пустошах – но только в определенное время дня. Если ты поможешь удерживать башни в это время, то привлечешь духов на нашу сторону.$B$BЕсли мы добьемся благосклонности духов, они даруют нам покровительство, которое поможет нам в наших делах.','Помогите Альянсу удерживать башню Духов в Костяных пустошах.','Теперь духи ближе к умиротворению. Хорошо, что мы заслужили их благосклонность, тем более что воюем так близко к месту их упокоения.','Духи все никак не успокоятся, $n. Ты $Gвыполнил:выполнила; свое поручение?','Удержите Башню Духов') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи Аукиндона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Духам Аукиндона нет дела до усобиц Альянса и Орды, но заслужив их расположение, наша сторона получит преимущество в этих краях.$B$BДревний обычай велит живым поклоняться Башням Духов в Костяных пустошах – но только в определенное время дня. Если ты поможешь удерживать башни в это время, то привлечешь духов на нашу сторону.$B$BЕсли мы добьемся благосклонности духов, они даруют нам покровительство, которое поможет нам в наших делах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Альянсу удерживать башню Духов в Костяных пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь духи ближе к умиротворению. Хорошо, что мы заслужили их благосклонность, тем более что воюем так близко к месту их упокоения.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Духи все никак не успокоятся, $n. Ты $Gвыполнил:выполнила; свое поручение?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Удержите Башню Духов',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11506,'Духи Аукиндона','Да, мы враждуем с дренеями, но неупокоенные духи их предков в Аукиндоне не служат никому из мира живых.$B$BОбычай дренеев требует от них поклонения Башням духов несколько раз в течение дня в определенное время. Если ты поможешь удерживать башни в это время, ты поможешь духам обрести покой в Аукиндоне.$B$BАльянс попытается захватить башни, чтобы заслужить благоволение усопших. Но победа должна быть за нами.','Помогите Орде удерживать Башню Духов на Костяных пустошах.','Теперь духи стали ближе к умиротворению. Они благосклонны к нам.$B$BКакое унижение для наших врагов – знать, что души их предков обернулись против них, пусть и на время!','Вокруг нас духи Аукиндона. Даруют ли они нам свое покровительство?','Башня Духов захвачена','Вернитесь к экзорцисту Вайше в Форт Камнеломов, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Духи Аукиндона',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, мы враждуем с дренеями, но неупокоенные духи их предков в Аукиндоне не служат никому из мира живых.$B$BОбычай дренеев требует от них поклонения Башням духов несколько раз в течение дня в определенное время. Если ты поможешь удерживать башни в это время, ты поможешь духам обрести покой в Аукиндоне.$B$BАльянс попытается захватить башни, чтобы заслужить благоволение усопших. Но победа должна быть за нами.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Орде удерживать Башню Духов на Костяных пустошах.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь духи стали ближе к умиротворению. Они благосклонны к нам.$B$BКакое унижение для наших врагов – знать, что души их предков обернулись против них, пусть и на время!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вокруг нас духи Аукиндона. Даруют ли они нам свое покровительство?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Башня Духов захвачена',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к экзорцисту Вайше в Форт Камнеломов, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11507,'Старейшина Атуик из Камагуа','<Орфус тщательно сворачивает принесенные улики.>$B$BМой народ давно уже не воюет с флибустьерами Северных морей. Худой мир лучше доброй драки. Так что я знаю только одного клыкарра, который может помочь нам вытрясти правду из пиратов. Зовут его старейшина Атуик из Камагуа. Отнеси ему эти доказательства.$B$BЧтобы добраться до Камагуа, тебе надо воспользоваться подъемником, который находится позади меня. Он доставит тебя прямиком в деревню, где ты и найдешь старейшину Атуика.','Орфус Камагуанский из Ревущего фьорда просит вас отнести узелок старейшине Атуику из Камагуа.','Есть новости от Орфуса?','Вернитесь к старейшине Атуику в Камагуа, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Старейшина Атуик из Камагуа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Орфус тщательно сворачивает принесенные улики.>$B$BМой народ давно уже не воюет с флибустьерами Северных морей. Худой мир лучше доброй драки. Так что я знаю только одного клыкарра, который может помочь нам вытрясти правду из пиратов. Зовут его старейшина Атуик из Камагуа. Отнеси ему эти доказательства.$B$BЧтобы добраться до Камагуа, тебе надо воспользоваться подъемником, который находится позади меня. Он доставит тебя прямиком в деревню, где ты и найдешь старейшину Атуика.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Орфус Камагуанский из Ревущего фьорда просит вас отнести узелок старейшине Атуику из Камагуа.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть новости от Орфуса?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Атуику в Камагуа, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11508,'Греззикс Иглохруст','Воришки-пираты обосновались в Лагере Скалаваг, далеко на юге. К несчастью, их аванпост слишком хорошо охраняется.$B$BВпрочем, я знаю одного товарища, который может помочь нам туда проникнуть.$B$BНедавно в деревню пришел пират-наемник, Греззикс Иглохруст, и попросил у нас убежища. В обмен на пищу и кров он дает информацию о наших врагах и передает пиратам ложные сведения о наших планах. Его лодка находится к юго-западу от берега.','Поговорите с Греззиксом Иглохрустом.','Есть новости от Орфуса?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Греззикс Иглохруст',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воришки-пираты обосновались в Лагере Скалаваг, далеко на юге. К несчастью, их аванпост слишком хорошо охраняется.$B$BВпрочем, я знаю одного товарища, который может помочь нам туда проникнуть.$B$BНедавно в деревню пришел пират-наемник, Греззикс Иглохруст, и попросил у нас убежища. В обмен на пищу и кров он дает информацию о наших врагах и передает пиратам ложные сведения о наших планах. Его лодка находится к юго-западу от берега.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Греззиксом Иглохрустом.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть новости от Орфуса?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11509,'Чудак среди чудаков','Флибустьеры Северных морей боятся и уважают Греззикса. Наверное, они просто завидуют моему интеллекту и трепещут перед моим грозным кораблем. Так что ты просто сядь на хвост моему юнге Луи, и скоро станешь своим в доску. Доска – это для пирата все.$B$BКак будешь $gготов:готова; к отправлению – свистни Луи, и он отведет тебя в Скалаваг.$B$BАх да – сначала тебе стоит поболтать с Гарри "Луносветом". Он расскажет тебе про эти древние штучки, которые они стырили у врайкулов. Только следи за языком, когда будешь с ним разговаривать. Он такой чудак... совершенно помешался на эльфах крови.','Поговорите с Гарри "Луносветом" в Лагере Скалаваг и расспросите его о пропавших врайкульских артефактах.','Есть новости от Орфуса?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Чудак среди чудаков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Флибустьеры Северных морей боятся и уважают Греззикса. Наверное, они просто завидуют моему интеллекту и трепещут перед моим грозным кораблем. Так что ты просто сядь на хвост моему юнге Луи, и скоро станешь своим в доску. Доска – это для пирата все.$B$BКак будешь $gготов:готова; к отправлению – свистни Луи, и он отведет тебя в Скалаваг.$B$BАх да – сначала тебе стоит поболтать с Гарри "Луносветом". Он расскажет тебе про эти древние штучки, которые они стырили у врайкулов. Только следи за языком, когда будешь с ним разговаривать. Он такой чудак... совершенно помешался на эльфах крови.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гарри "Луносветом" в Лагере Скалаваг и расспросите его о пропавших врайкульских артефактах.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Есть новости от Орфуса?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (11510,'"Челюсти"','Вернитесь к Гарри "Луносвету" в Лагерь Скалаваг, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Челюсти"',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гарри "Луносвету" в Лагерь Скалаваг, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11511,'Эти артефакты прокляты, |3-6($r), и надо быть сумасшедшим, чтобы решиться на их поиски. Каждый, кто прикасался к ним, либо сходил с ума, либо умирал насильственной смертью. $B$BВозьмем, к примеру, этот посох. Перевозивший его корабль наткнулся на скалы и теперь гниет на побережье Острова Копий, к северу отсюда.$B$BЕсли тебе правда нужна эта штука, ищи ее в трюме.$B$BТолько не приноси этот посох сюда, если найдешь его! И держись подальше от Абдула. Попадешься ему – распрощаешься с жизнью.','Посох у тебя?','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти артефакты прокляты, |3-6($r), и надо быть сумасшедшим, чтобы решиться на их поиски. Каждый, кто прикасался к ним, либо сходил с ума, либо умирал насильственной смертью. $B$BВозьмем, к примеру, этот посох. Перевозивший его корабль наткнулся на скалы и теперь гниет на побережье Острова Копий, к северу отсюда.$B$BЕсли тебе правда нужна эта штука, ищи ее в трюме.$B$BТолько не приноси этот посох сюда, если найдешь его! И держись подальше от Абдула. Попадешься ему – распрощаешься с жизнью.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Посох у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11512,'Ледяное сердце Исулдофа','Кое-кто считает, что Иона всегда был сумасшедшим, но я-то знаю правду. Все дело в сердце! В этом проклятом ледяном сердце! В тот самый момент, когда он достал его из могилы, что-то в нем перемкнуло. Я буквально почувствовал, как кровь застыла в его жилах... Именно тогда безумие охватило его. $B$BОн покинул нас и скрылся в пещере на севере острова. Говорят, он забросил проклятый артефакт в глубину своей берлоги. Увы, слишком поздно...$B$BНо если ты только помыслишь притащить сюда это сердце, я лично убью тебя!','Найдите ледяное сердце Исулдофа и отнесите его Орфусу Камагуанскому в Ревущий фьорд.','Это... это Ледяное сердце Исулдофа?','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ледяное сердце Исулдофа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Кое-кто считает, что Иона всегда был сумасшедшим, но я-то знаю правду. Все дело в сердце! В этом проклятом ледяном сердце! В тот самый момент, когда он достал его из могилы, что-то в нем перемкнуло. Я буквально почувствовал, как кровь застыла в его жилах... Именно тогда безумие охватило его. $B$BОн покинул нас и скрылся в пещере на севере острова. Говорят, он забросил проклятый артефакт в глубину своей берлоги. Увы, слишком поздно...$B$BНо если ты только помыслишь притащить сюда это сердце, я лично убью тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ледяное сердце Исулдофа и отнесите его Орфусу Камагуанскому в Ревущий фьорд.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это... это Ледяное сердце Исулдофа?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11513,'Перехват контейнеров с маной','Я разработал план, согласно которому мы сможем добыть достаточно сильные источники энергии для создания нашего портала.$B$BЭфириалы в Лагере Баш\'ира, в горах у северо-западной оконечности Острогорья, контрабандой вывозят контейнеры с маной из Крепости Бурь и отправляют их Кель\'тасу к Солнечному Колодцу.$B$BОни прячут контейнеры, но их все же можно отыскать – эфириалы носят при себе синхронизаторы, при помощи которых можно увидеть контрабандный товар.$B$BОпасайся охраняющих контейнеры с маной синхзрозмей.','Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на Террасу Света в Шаттрат.','Эти контейнеры с маной имеют жизненно важное значение в наших планах. С ними мы сможем открыть портал на остров Солнечного Колодца в кратчайшие сроки!$B$BВозвращайся завтра и я отправлю тебя добыть больше контейнеров у наших друзей из Баш\'ира.','Ты $Gдобыл:добыла; контейнеры с маной?','Вернитесь к экзарху Назууну в Нижний Город, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перехват контейнеров с маной',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я разработал план, согласно которому мы сможем добыть достаточно сильные источники энергии для создания нашего портала.$B$BЭфириалы в Лагере Баш\'ира, в горах у северо-западной оконечности Острогорья, контрабандой вывозят контейнеры с маной из Крепости Бурь и отправляют их Кель\'тасу к Солнечному Колодцу.$B$BОни прячут контейнеры, но их все же можно отыскать – эфириалы носят при себе синхронизаторы, при помощи которых можно увидеть контрабандный товар.$B$BОпасайся охраняющих контейнеры с маной синхзрозмей.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на Террасу Света в Шаттрат.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Эти контейнеры с маной имеют жизненно важное значение в наших планах. С ними мы сможем открыть портал на остров Солнечного Колодца в кратчайшие сроки!$B$BВозвращайся завтра и я отправлю тебя добыть больше контейнеров у наших друзей из Баш\'ира.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gдобыл:добыла; контейнеры с маной?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к экзарху Назууну в Нижний Город, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11514,'Поддержка портала Солнечного Колодца','Мы должны постоянно снабжать энергией наш портал, иначе он уничтожится. Контейнеры с маной, которые Эфириум спрятал в Лагере Баш\'ира, помогут нам. Лагерь расположен в горах, на северо-западной оконечности Острогорья, что далеко на севере отсюда.$B$BЗапомни: надо добыть у одного из них синхронизатор и с его помощью определить, где находится контрабанда.$B$BОстерегайся синхрозмей, которых они держат как охрану возле контейнеров с маной.','Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на Террасу Света в Шаттрат.','Вернитесь к экзарху Назууну в Нижний Город, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поддержка портала Солнечного Колодца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны постоянно снабжать энергией наш портал, иначе он уничтожится. Контейнеры с маной, которые Эфириум спрятал в Лагере Баш\'ира, помогут нам. Лагерь расположен в горах, на северо-западной оконечности Острогорья, что далеко на севере отсюда.$B$BЗапомни: надо добыть у одного из них синхронизатор и с его помощью определить, где находится контрабанда.$B$BОстерегайся синхрозмей, которых они держат как охрану возле контейнеров с маной.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на Террасу Света в Шаттрат.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к экзарху Назууну в Нижний Город, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11515,'Кровь за кровь','Когда войска Келя отступили через этот портал, самые верные его приспешники получили мерзкий дар. Они остались здесь и много дней жадно пили кровь демонов.$B$BЭта кровь изменила их, дав им новую мощь. И эта кровь станет причиной их гибели.$B$BДобудь пробу крови у других демонов. Наполни ей этот конденсатор Скверны и лиши этих надменных глупцов новообретенной мощи. Они ослабнут – вот тогда ты убьешь их и вернешься ко мне!','Магистр Сейла у трона Кил\'джедена велит вам убить 4 истощенных сквернокровов при помощи конденсатора Скверны. Вам понадобится кровь демонов, которая течет по венам находящихся рядом зловещих глашатаев, чтобы наполнить конденсатор Скверны.','Эти уроды - позор для нашей расы. Уничтожь их, $N.','Вернитесь к магистру Сейле к Трону Кил\'джедена, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровь за кровь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда войска Келя отступили через этот портал, самые верные его приспешники получили мерзкий дар. Они остались здесь и много дней жадно пили кровь демонов.$B$BЭта кровь изменила их, дав им новую мощь. И эта кровь станет причиной их гибели.$B$BДобудь пробу крови у других демонов. Наполни ей этот конденсатор Скверны и лиши этих надменных глупцов новообретенной мощи. Они ослабнут – вот тогда ты убьешь их и вернешься ко мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Магистр Сейла у трона Кил\'джедена велит вам убить 4 истощенных сквернокровов при помощи конденсатора Скверны. Вам понадобится кровь демонов, которая течет по венам находящихся рядом зловещих глашатаев, чтобы наполнить конденсатор Скверны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти уроды - позор для нашей расы. Уничтожь их, $N.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Сейле к Трону Кил\'джедена, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11516,'Взрыв врат','Мы должны закрыть эти врата, чтобы не допустить подхода подкрепления Легиона на Кель\'Данас.$B$BВозьми эти угли, в них живет одно из моих созданий – живая вспышка. Она обладает мощной разрушительной силой, если ей хватает энергии.$B$BНайди искры Скверны, что летают в тех краях, и убивай их рядом с живой вспышкой. От каждой убитой искры Скверны живая вспышка будет напитываться силой, пока не станет нестабильной.$B$BКак только живая вспышка достигнет этого состояния, иди к вратам. А живая вспышка уже сделает все сама.','Магистр Сейла у трона Кил\'джедена велит вам взять раскаленные угли, чтобы вызвать живую вспышку и убивать рядом с ней раскаленных искр Скверны, пока она не станет нестабильной живой вспышкой. Вернитесь к вратам Легиона вместе с нестабильной живой вспышкой, чтобы уничтожить врата.','Готово, $N? Мы должны помешать дальнейшим силам Легиона усилить Кель\'тас.','Врата Легиона разрушены','Вернитесь к магистру Сейле к Трону Кил\'джедена, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взрыв врат',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны закрыть эти врата, чтобы не допустить подхода подкрепления Легиона на Кель\'Данас.$B$BВозьми эти угли, в них живет одно из моих созданий – живая вспышка. Она обладает мощной разрушительной силой, если ей хватает энергии.$B$BНайди искры Скверны, что летают в тех краях, и убивай их рядом с живой вспышкой. От каждой убитой искры Скверны живая вспышка будет напитываться силой, пока не станет нестабильной.$B$BКак только живая вспышка достигнет этого состояния, иди к вратам. А живая вспышка уже сделает все сама.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Магистр Сейла у трона Кил\'джедена велит вам взять раскаленные угли, чтобы вызвать живую вспышку и убивать рядом с ней раскаленных искр Скверны, пока она не станет нестабильной живой вспышкой. Вернитесь к вратам Легиона вместе с нестабильной живой вспышкой, чтобы уничтожить врата.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Готово, $N? Мы должны помешать дальнейшим силам Легиона усилить Кель\'тас.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Врата Легиона разрушены',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Сейле к Трону Кил\'джедена, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11517,'Встреча с Назууном','Я счастлив, что ты здесь, |3-6($c)! Теперь, когда мы захватили святилище, нам нужно срочно создать магический портал, который вел бы отсюда в Шаттрат, что в Запределье.$B$BМой господин, экзарх Назуун, возглавляет этот фронт работ наступательной группировки. Он просил меня посылать к нему любых многообещающих кандидатов, которые могли бы помочь в создании портала.$B$BПрошу тебя – отправляйся в Шаттрат и поговори с ним в чертоге А\'дала на Террасе Света.','Торговец Портануус просит вас поговорить с экзархом Назууном на Террасе Света в Шаттрате.','Так тебя прислал Портануус? Отлично, время не терпит!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с Назууном',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я счастлив, что ты здесь, |3-6($c)! Теперь, когда мы захватили святилище, нам нужно срочно создать магический портал, который вел бы отсюда в Шаттрат, что в Запределье.$B$BМой господин, экзарх Назуун, возглавляет этот фронт работ наступательной группировки. Он просил меня посылать к нему любых многообещающих кандидатов, которые могли бы помочь в создании портала.$B$BПрошу тебя – отправляйся в Шаттрат и поговори с ним в чертоге А\'дала на Террасе Света.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торговец Портануус просит вас поговорить с экзархом Назууном на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так тебя прислал Портануус? Отлично, время не терпит!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11518,'Еежедневный указатель портала Солнечного Колодца') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еежедневный указатель портала Солнечного Колодца',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`) VALUES (11519,'Прислушайся! Слышишь канонаду на северо-востоке? Это ведет бой корабль капитана Эллис. Штука в том, что Эллис и его команда погибли около месяца назад. Смекаешь?$B$B<Гарри качает головой.>$B$BДа, это корабль-призрак...$B$BИ на нем плавает тот самый человек, который мог бы рассказать тебе про этот щит.$B$BКаждые пять минут "Сестренка милосердия" пристает к маленькому острову напротив Берега Сорлофа. Там они пополняют свою команду призраков, и у них никогда не бывает недостатка в неупокоенных душах.','Поговорите с капитаном Эллис на борту "Сестренки милосердия".') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прислушайся! Слышишь канонаду на северо-востоке? Это ведет бой корабль капитана Эллис. Штука в том, что Эллис и его команда погибли около месяца назад. Смекаешь?$B$B<Гарри качает головой.>$B$BДа, это корабль-призрак...$B$BИ на нем плавает тот самый человек, который мог бы рассказать тебе про этот щит.$B$BКаждые пять минут "Сестренка милосердия" пристает к маленькому острову напротив Берега Сорлофа. Там они пополняют свою команду призраков, и у них никогда не бывает недостатка в неупокоенных душах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с капитаном Эллис на борту "Сестренки милосердия".',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11520,'Смотри в корень','Привет тебе, |3-6($r). $b$bБоюсь, мне мало есть что предложить тебе, пока не пополню запасов своих реагентов. $b$bИ прежде всего мне нужен корень Острого Шипа, который особенно трудно добывать.$b$bНо, к счасть, я знаю один секрет...$b$bПри помощи желез острошипа-живодера, можно контролировать разорителя и использовать его для выкапывания корней.$b$bЧтобы найти корень, надо отправиться в Запределье и полететь на северо-восток от Шаттрата, до уступа Острого Шипа.','Мар\'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа.','Отлично, |3-6($C).$B$BЯ благодарю вас за вашу помощь.','Честное слово, $N, мне не до разговоров.$B$BПросто дай мне знать, когда добудешь корни.','Вернитесь к Мар\'не в Гавань Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смотри в корень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет тебе, |3-6($r). $b$bБоюсь, мне мало есть что предложить тебе, пока не пополню запасов своих реагентов. $b$bИ прежде всего мне нужен корень Острого Шипа, который особенно трудно добывать.$b$bНо, к счасть, я знаю один секрет...$b$bПри помощи желез острошипа-живодера, можно контролировать разорителя и использовать его для выкапывания корней.$b$bЧтобы найти корень, надо отправиться в Запределье и полететь на северо-восток от Шаттрата, до уступа Острого Шипа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мар\'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично, |3-6($C).$B$BЯ благодарю вас за вашу помощь.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Честное слово, $N, мне не до разговоров.$B$BПросто дай мне знать, когда добудешь корни.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мар\'не в Гавань Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11521,'И опять – смотри в корень','Запасов мне пока хватает, но чтобы удовлетворять спрос, мне нужно много корня Острого Шипа.$b$bДобывать его нелегко Но я знаю особый способ его выкапывания.$b$bПри помощи желез острошипа-живодера, можно контролировать разорителя и использовать его для выкапывания корней.$b$bЧтобы найти корень, надо отправиться в Запределье и полететь на северо-восток от Шаттрата, до уступа Острого Шипа.$b$bКак только выкопаешь пять корней, $n, возвращайся.','Мар\'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа.','Честное слово, $N, мне не до разговоров.$B$BПросто дай мне знать, когда добудешь корни.','Вернитесь к Мар\'не в Гавань Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','И опять – смотри в корень',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Запасов мне пока хватает, но чтобы удовлетворять спрос, мне нужно много корня Острого Шипа.$b$bДобывать его нелегко Но я знаю особый способ его выкапывания.$b$bПри помощи желез острошипа-живодера, можно контролировать разорителя и использовать его для выкапывания корней.$b$bЧтобы найти корень, надо отправиться в Запределье и полететь на северо-восток от Шаттрата, до уступа Острого Шипа.$b$bКак только выкопаешь пять корней, $n, возвращайся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мар\'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Честное слово, $N, мне не до разговоров.$B$BПросто дай мне знать, когда добудешь корни.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мар\'не в Гавань Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11523,'Подпитка для силового поля','Нам удалось реактивировать кристаллы-хранители, создающие поле вокруг святилища, но зачем останавливаться на достигнутом? Мы окружим защитой и другие строения, но Презренные упрямы – они продолжают похищать силу из кристаллов-хранителей.$B$BПеребей их и забери у них клочки маны. При их помощи активируй защиту святилища – от этого зависит успех наших операций здесь.','Капитан Терис Рассветное Пламя с подготовительного плацдарма Расколотого Солнца просит вас добыть 4 клочка маны у Презренных-злобней и презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке.','Мне нужно столько очищенного металла Ата\'мала, |3-6($C), сколько я сумею переработать.','Зарядите кристалл-хранитель','Вернитесь к капитану Терису Рассветному Пламени на Подготовительный плацдарм Расколотого Солнца, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подпитка для силового поля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам удалось реактивировать кристаллы-хранители, создающие поле вокруг святилища, но зачем останавливаться на достигнутом? Мы окружим защитой и другие строения, но Презренные упрямы – они продолжают похищать силу из кристаллов-хранителей.$B$BПеребей их и забери у них клочки маны. При их помощи активируй защиту святилища – от этого зависит успех наших операций здесь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Терис Рассветное Пламя с подготовительного плацдарма Расколотого Солнца просит вас добыть 4 клочка маны у Презренных-злобней и презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно столько очищенного металла Ата\'мала, |3-6($C), сколько я сумею переработать.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Зарядите кристалл-хранитель',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Терису Рассветному Пламени на Подготовительный плацдарм Расколотого Солнца, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11524,'Хаотичное поведение','Нас слишком мало, чтобы захватить святилище в Солнечном Крае, но у меня есть план, который качнет чашку весов в нашу сторону.$B$BПросачивающаяся из Солнечного Колодца энергия привела к сбою в функционировании стражей, патрулирующих этот остров. Кристаллические сердечники, контролирующие их поведение, уже не подлежат ремонту.$B$BЯ сделала новые кристаллы, с помощью которых мы возьмем их под собственный контроль.Их надо поместить внутрь корпуса побежденного стража. Нам нужна любая помощь.','Поборница Зейанн на подготовительном плацдарме Расколотого Солнца просит, чтобы вы поместили настроенные кристаллы-сердечники в корпуса 5 побежденных магических стражей, чтобы перевести их в дружественный режим.','Хорошая работа, $N. Святилище будет нашим в мгновение ока!','Удалось перенастроить стражей, $N?','Вернитесь к воздаятельнице Ксаяне на Подготовительный плацдарм Расколотого Солнца, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хаотичное поведение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нас слишком мало, чтобы захватить святилище в Солнечном Крае, но у меня есть план, который качнет чашку весов в нашу сторону.$B$BПросачивающаяся из Солнечного Колодца энергия привела к сбою в функционировании стражей, патрулирующих этот остров. Кристаллические сердечники, контролирующие их поведение, уже не подлежат ремонту.$B$BЯ сделала новые кристаллы, с помощью которых мы возьмем их под собственный контроль.Их надо поместить внутрь корпуса побежденного стража. Нам нужна любая помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поборница Зейанн на подготовительном плацдарме Расколотого Солнца просит, чтобы вы поместили настроенные кристаллы-сердечники в корпуса 5 побежденных магических стражей, чтобы перевести их в дружественный режим.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $N. Святилище будет нашим в мгновение ока!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось перенастроить стражей, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятельнице Ксаяне на Подготовительный плацдарм Расколотого Солнца, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11525,'Дальнейшая перенастройка','Мой план заменить поврежденные кристаллы неуправляемых стражей увенчались успехом. Мы сумели с их помощью захватить святилище Солнечного Края.$B$BЯ создала новые кристаллы, которые помогут контролировать большее их количество. Помести их в корпуса побежденных стражей. Как только мы их переделаем, мы переведем их в другие места.','Воздаятельница Ксаяна на подготовительном плацдарме Расколотого Солнца просит вас поместить настроенные кристаллы-сердечники в корпуса 5 побежденных магических стражей, чтобы перевести их в дружественный режим.','Замечательно. Перенастроенные стражи помогут нам защитить наш периметр.','Вернитесь к воздаятельнице Ксаяне на Подготовительный плацдарм Расколотого Солнца, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дальнейшая перенастройка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мой план заменить поврежденные кристаллы неуправляемых стражей увенчались успехом. Мы сумели с их помощью захватить святилище Солнечного Края.$B$BЯ создала новые кристаллы, которые помогут контролировать большее их количество. Помести их в корпуса побежденных стражей. Как только мы их переделаем, мы переведем их в другие места.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воздаятельница Ксаяна на подготовительном плацдарме Расколотого Солнца просит вас поместить настроенные кристаллы-сердечники в корпуса 5 побежденных магических стражей, чтобы перевести их в дружественный режим.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Замечательно. Перенастроенные стражи помогут нам защитить наш периметр.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятельнице Ксаяне на Подготовительный плацдарм Расколотого Солнца, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11526,'Пропавший магистр','Мы послали одну из наших опытных сотрудниц обследовать портал Скверны посреди Рассветной площади, к югу отсюда. Она не вернулась.$B$BВозьми вот этот свиток – мы нашли его на одном из вражеских трупов. Мы уверены, что он даст тебе возможность пройти сквозь портал. Оказавшись там, найди магистра Сейлу и помоги ей, чем сумеешь.','При помощи захваченного свитка Легиона, пройдите сквозь портал на Рассветной площади. Как только пройдете сквозь портал, найдите магистра Сейлу.','Конечно, очень мило, что Терис заботится о моей шкуре, но у нас тут есть проблемы поважнее. И намного.','Тссс, |3-6($C). К югу от портала – сторожевой пост Легиона.','Вернитесь к магистру Сейле к Трону Кил\'джедена, что на Полуострове Адского Пламени.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пропавший магистр',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы послали одну из наших опытных сотрудниц обследовать портал Скверны посреди Рассветной площади, к югу отсюда. Она не вернулась.$B$BВозьми вот этот свиток – мы нашли его на одном из вражеских трупов. Мы уверены, что он даст тебе возможность пройти сквозь портал. Оказавшись там, найди магистра Сейлу и помоги ей, чем сумеешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи захваченного свитка Легиона, пройдите сквозь портал на Рассветной площади. Как только пройдете сквозь портал, найдите магистра Сейлу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Конечно, очень мило, что Терис заботится о моей шкуре, но у нас тут есть проблемы поважнее. И намного.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тссс, |3-6($C). К югу от портала – сторожевой пост Легиона.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Сейле к Трону Кил\'джедена, что на Полуострове Адского Пламени.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11527,'Бунт на корабле','Да, дружище, у нас проблемы. У меня пушкари взбунтовались! Я тут с остальными ребятами попробую надраить корму Сорлофу, но кому-то придется разобраться с этими бунтовщиками!$B$BИ, знаешь, что? Этим кем-то будешь ты! Топай в трюм, разберись с этими морскими волками-бунтарями, да притащи пороху для большой дуры на верхней палубе.$B$BЕсли ты зарядишь эту пушенцию, Сорлоф в штаны наложит от страха, и сам притащит сюда всю добычу!','Капитан Эллис на борту "Сестренки милосердия" в Ревущем фьорде просит вас принести 5 бочек с порохом из трюма корабля.','Тут слишком много великанов и морских волков-бунтарей!','Вернитесь к капитану Эллис на борт "Сестренки милосердия" в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бунт на корабле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, дружище, у нас проблемы. У меня пушкари взбунтовались! Я тут с остальными ребятами попробую надраить корму Сорлофу, но кому-то придется разобраться с этими бунтовщиками!$B$BИ, знаешь, что? Этим кем-то будешь ты! Топай в трюм, разберись с этими морскими волками-бунтарями, да притащи пороху для большой дуры на верхней палубе.$B$BЕсли ты зарядишь эту пушенцию, Сорлоф в штаны наложит от страха, и сам притащит сюда всю добычу!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Эллис на борту "Сестренки милосердия" в Ревущем фьорде просит вас принести 5 бочек с порохом из трюма корабля.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тут слишком много великанов и морских волков-бунтарей!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эллис на борт "Сестренки милосердия" в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11528,'Подарок к Зимнему Покрову') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подарок к Зимнему Покрову',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11529,'Сокровища Сорлофа','Ща, мои ребята начистят для тебя нашу большую дуру! Вон она валяется по другому борту. Иди, заряди пушку, да приготовься стрелять по Сорлофу!$B$BА как только мы пустим на дно эту сухопутную крысу, ты притащишь сюда всю добычу – нам-то с этого чертова корыта не сойти! Принесешь золотишко – получишь свою часть добычи. Тебе щит, нам все остальное...','Убейте Сорлофа из большой пушки и принесите капитану Эллис сокровища Сорлофа на борт "Сестренки милосердия".','Уговор есть уговор!','Не щелкай клювом, дорогуша!','Вернитесь к капитану Эллис на борт "Сестренки милосердия" в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сокровища Сорлофа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ща, мои ребята начистят для тебя нашу большую дуру! Вон она валяется по другому борту. Иди, заряди пушку, да приготовься стрелять по Сорлофу!$B$BА как только мы пустим на дно эту сухопутную крысу, ты притащишь сюда всю добычу – нам-то с этого чертова корыта не сойти! Принесешь золотишко – получишь свою часть добычи. Тебе щит, нам все остальное...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Сорлофа из большой пушки и принесите капитану Эллис сокровища Сорлофа на борт "Сестренки милосердия".',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Уговор есть уговор!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не щелкай клювом, дорогуша!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Эллис на борт "Сестренки милосердия" в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11530,'Вот твой щит. Надеюсь, на тебя не падет его проклятие, как на остальную команду. Только не оставляй его здесь! Могу поспорить, кто-то хочет забрать его. $B$BА теперь – убери эту штуковину с моего корабля!','Ты $gвернулся:вернулась;!','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот твой щит. Надеюсь, на тебя не падет его проклятие, как на остальную команду. Только не оставляй его здесь! Могу поспорить, кто-то хочет забрать его. $B$BА теперь – убери эту штуковину с моего корабля!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gвернулся:вернулась;!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11531,'Странная деталь мотора','Этот странный механизм никоим образом не напоминает паровой насос. Возможно, К. Ли Мелюзга сможет сказать о нем больше.','Отнесите странную деталь мотора к К. Ли Мелюзге в Терелдор.','<K. Ли смотрит на моторную часть и на мгновение смотрит вдаль.>$B$BЭто что-то особенное. Трудно сказать, откуда он, как будто он просто упал с неба. Я буду держаться за это и заплачу тебе за твои проблемы.$B$BХотя между тобой и мной, я думаю, было бы лучше, если бы мы никому не говорили об этом.$B$B<K. Ли надевает свою самую очаровательную улыбку.>','О мой Бог! Что у тебя там, $N?','Вернитесь к К. Ли Мелюзге в Телредор, что в Зангартопи.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Странная деталь мотора',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Этот странный механизм никоим образом не напоминает паровой насос. Возможно, К. Ли Мелюзга сможет сказать о нем больше.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите странную деталь мотора к К. Ли Мелюзге в Терелдор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<K. Ли смотрит на моторную часть и на мгновение смотрит вдаль.>$B$BЭто что-то особенное. Трудно сказать, откуда он, как будто он просто упал с неба. Я буду держаться за это и заплачу тебе за твои проблемы.$B$BХотя между тобой и мной, я думаю, было бы лучше, если бы мы никому не говорили об этом.$B$B<K. Ли надевает свою самую очаровательную улыбку.>',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','О мой Бог! Что у тебя там, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к К. Ли Мелюзге в Телредор, что в Зангартопи.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11532,'Отвлекающий маневр на Тропе Мертвых','Легион двинется на нас, как только его войска на юге освободятся. Пока силы Плети на Тропе Мертвых заняты. Но это ненадолго.$B$BЯ прошу тебя взять дракондора, пролететь над Тропой и устроить демонам прореживание при помощи этих чародейских зарядов.$B$BЕсли все пройдет хорошо, они даже не заметят, как мы отобьем оружейную у прихвостней Келя. Поговори с Айреном, укротителем дракондоров, в западной части гавани Солнечного Предела, когда будешь $Gготов:готова; к вылету.','Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов.','У тебя настоящий талант, $Gпарень:девочка;. Вы когда-нибудь думали о вступлении в Стражи?$B$BВы нужны нам здесь, если мы хотим взять доки в ближайшее время.','Ты $Gисполнил:исполнила; свое поручение, $N?','Вернитесь к боевому магу Аринне в Святилище Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвлекающий маневр на Тропе Мертвых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Легион двинется на нас, как только его войска на юге освободятся. Пока силы Плети на Тропе Мертвых заняты. Но это ненадолго.$B$BЯ прошу тебя взять дракондора, пролететь над Тропой и устроить демонам прореживание при помощи этих чародейских зарядов.$B$BЕсли все пройдет хорошо, они даже не заметят, как мы отобьем оружейную у прихвостней Келя. Поговори с Айреном, укротителем дракондоров, в западной части гавани Солнечного Предела, когда будешь $Gготов:готова; к вылету.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У тебя настоящий талант, $Gпарень:девочка;. Вы когда-нибудь думали о вступлении в Стражи?$B$BВы нужны нам здесь, если мы хотим взять доки в ближайшее время.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gисполнил:исполнила; свое поручение, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому магу Аринне в Святилище Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11533,'Воздушные атаки должны продолжаться!','Мы захватили у врага оружейную благодаря нашим атакам с воздуха на силы Легиона на Тропе Мертвых.$B$BСобственно говоря, они были столь удачны, что мы намерены продолжать бомбардировки. Возьми эти чародейские заряды и отбомби ими вражьи силы!$B$BПоговори с Айреном Ясное Небо в гавани Солнечного Края, когда будешь $Gготов:готова; к вылету.','Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов.','Если можешь убить демона сегодня, не откладывай на завтра. Продолжай в том же духе.','Вернитесь к боевому магу Аринне в Святилище Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воздушные атаки должны продолжаться!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы захватили у врага оружейную благодаря нашим атакам с воздуха на силы Легиона на Тропе Мертвых.$B$BСобственно говоря, они были столь удачны, что мы намерены продолжать бомбардировки. Возьми эти чародейские заряды и отбомби ими вражьи силы!$B$BПоговори с Айреном Ясное Небо в гавани Солнечного Края, когда будешь $Gготов:готова; к вылету.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Если можешь убить демона сегодня, не откладывай на завтра. Продолжай в том же духе.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к боевому магу Аринне в Святилище Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11534,'Встреча с Назууном','Я счастлив, что ты здесь, |3-6($c)! Теперь, когда мы отбили святилище у Презренных, нам нужно срочно создать магический портал, который вел бы отсюда в Шаттрат, что в Запределье.$B$BМой господин, экзарх Назуун, возглавляет работы наступательной группировки по созданию портала. Он просил меня посылать к нему любых многообещающих кандидатов, которые могли бы помочь добывать источники энергии для портала.$B$BПрошу тебя – отправляйся в Шаттрат и поговори с ним в чертоге А\'дала на Террасе Света.','Торговец Портануус просит вас поговорить с экзархом Назууном на Террасе Света в Шаттрате.','Так тебя прислал Портануус? Отлично, время не терпит!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Встреча с Назууном',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я счастлив, что ты здесь, |3-6($c)! Теперь, когда мы отбили святилище у Презренных, нам нужно срочно создать магический портал, который вел бы отсюда в Шаттрат, что в Запределье.$B$BМой господин, экзарх Назуун, возглавляет работы наступательной группировки по созданию портала. Он просил меня посылать к нему любых многообещающих кандидатов, которые могли бы помочь добывать источники энергии для портала.$B$BПрошу тебя – отправляйся в Шаттрат и поговори с ним в чертоге А\'дала на Террасе Света.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Торговец Портануус просит вас поговорить с экзархом Назууном на Террасе Света в Шаттрате.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Так тебя прислал Портануус? Отлично, время не терпит!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11535,'Подготовка к работе','Припасы уже на подходе, или, по крайней мере, мне так сказали.$b$bКак бы то ни было, мы не можем сидеть, сложа руки, надеясь, что помощь прибудет до того, как наше наступление завязнет. Будем обходиться тем, что есть.$b$bЛично мне нужна руда для ковки и наковальня, чтобы я могла начать совершенствовать наши оружие и доспех.$b$bНа побережье к востоку отсюда группа наг добывает руду и грузит в сундуки для отправки Легиону.$b$bЕсли мы избавим их от этой тяжести, это очень во многом поможет нам...','Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков.','Отлично! Мы подбираемся все ближе....$B$BCкоро я смогу изготовить наковальню, и тогда начнется настоящая работа.','Ты $Gсобрал:собрала; руду, которая мне нужна?','Вернитесь к кузнецу Хаутае на Залив Зеленожабрых, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подготовка к работе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Припасы уже на подходе, или, по крайней мере, мне так сказали.$b$bКак бы то ни было, мы не можем сидеть, сложа руки, надеясь, что помощь прибудет до того, как наше наступление завязнет. Будем обходиться тем, что есть.$b$bЛично мне нужна руда для ковки и наковальня, чтобы я могла начать совершенствовать наши оружие и доспех.$b$bНа побережье к востоку отсюда группа наг добывает руду и грузит в сундуки для отправки Легиону.$b$bЕсли мы избавим их от этой тяжести, это очень во многом поможет нам...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Мы подбираемся все ближе....$B$BCкоро я смогу изготовить наковальню, и тогда начнется настоящая работа.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gсобрал:собрала; руду, которая мне нужна?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кузнецу Хаутае на Залив Зеленожабрых, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11536,'Продолжаем...','Теперь, когда у меня есть наковальня, можно приступить к настоящей работе.$b$bКакие бы к нам ни поступили поставки, руда Черноспинов мне всегда пригодится. Нам нужны бесперебойные поставки оружия и доспехов, если мы хотим здесь добиться успеха.$b$bНа побережье к востоку отсюда группа наг добывает руду и грузит в сундуки для отправки Легиону.$b$bЕсли мы избавим их от этой тяжести, это очень во многом поможет нам...','Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков.','Ты добыл нужную мне руду?','Вернитесь к кузнецу Хаутае в Оружейную Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Продолжаем...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда у меня есть наковальня, можно приступить к настоящей работе.$b$bКакие бы к нам ни поступили поставки, руда Черноспинов мне всегда пригодится. Нам нужны бесперебойные поставки оружия и доспехов, если мы хотим здесь добиться успеха.$b$bНа побережье к востоку отсюда группа наг добывает руду и грузит в сундуки для отправки Легиону.$b$bЕсли мы избавим их от этой тяжести, это очень во многом поможет нам...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты добыл нужную мне руду?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кузнецу Хаутае в Оружейную Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11537,'Битва должна продолжаться!','Мы должны продолжать битву с армиями Легиона и лишать их боевого духа!$B$BПосланники Ненависти – это штормовики Легиона, развернутые для усиления тактических позиций. К ним стекаются враги, поскольку они боятся их больше, чем нас.$B$BСегодня мы переломим ситуацию. Возьми это знамя и повергни демонов Легиона. А когда столкнешься с Посланником Ненависти, срази его и пригвозди к земле.','Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара Ненависти на Рассветной площади. Пригвоздите к земле древком Знамени Расколотого Солнца труп Эмиссара Ненависти.','Вернитесь к предвестнику Иннуро в Святилище Солнечного Края, что на острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Битва должна продолжаться!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны продолжать битву с армиями Легиона и лишать их боевого духа!$B$BПосланники Ненависти – это штормовики Легиона, развернутые для усиления тактических позиций. К ним стекаются враги, поскольку они боятся их больше, чем нас.$B$BСегодня мы переломим ситуацию. Возьми это знамя и повергни демонов Легиона. А когда столкнешься с Посланником Ненависти, срази его и пригвозди к земле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара Ненависти на Рассветной площади. Пригвоздите к земле древком Знамени Расколотого Солнца труп Эмиссара Ненависти.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Иннуро в Святилище Солнечного Края, что на острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11538,'Сражение за оружейную Солнечного Края','Пылающий Легион удерживает оружейную Солнечного Края. Это – важный для наших операций пункт. Пока их боевой дух высок, нам не отбить у них это здание. $B$BЭмиссары Ненависти – это штормовики Легиона, развернутые для усиления тактических позиций. К ним стекаются враги, поскольку они боятся их больше, чем нас.$B$BСегодня мы переломим ситуацию. Возьми это знамя и повергни демонов Легиона. А когда столкнешься с эмиссаром ненависти, срази его и пригвозди к земле.','Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара Ненависти на Рассветной площади или в оружейной Солнечного Края. Пригвоздите к земле древком Знамени Расколотого Солнца труп Эмиссара Ненависти.','Твоя преданность образцовая, $N. Мы отобьем кузницу у Легиона в кратчайшие сроки!','Ты сделал то, о чем я тебя просил, $N?','Вернитесь к предвестнику Иннуро в Святилище Солнечного Края, что на острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сражение за оружейную Солнечного Края',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пылающий Легион удерживает оружейную Солнечного Края. Это – важный для наших операций пункт. Пока их боевой дух высок, нам не отбить у них это здание. $B$BЭмиссары Ненависти – это штормовики Легиона, развернутые для усиления тактических позиций. К ним стекаются враги, поскольку они боятся их больше, чем нас.$B$BСегодня мы переломим ситуацию. Возьми это знамя и повергни демонов Легиона. А когда столкнешься с эмиссаром ненависти, срази его и пригвозди к земле.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара Ненависти на Рассветной площади или в оружейной Солнечного Края. Пригвоздите к земле древком Знамени Расколотого Солнца труп Эмиссара Ненависти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя преданность образцовая, $N. Мы отобьем кузницу у Легиона в кратчайшие сроки!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты сделал то, о чем я тебя просил, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Иннуро в Святилище Солнечного Края, что на острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11539,'Захват гавани','Отборные войска Кель\'таса – Клинки Рассвета – расположились в гавани Солнечного Края и в Деревне Утренней Звезды.$B$BГавань чрезвычайно важна для наших планов, так что каждый убитый Клинок Рассвета – огромная помощь. Кель\'тас будет проклинать тот миг, когда обратился против собственного народа и заключил союз с Пылающим Легионом!','Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей и 3 метких стрелков из клана Клинка Рассвета.','Отличная работа, |3-6)$C). Армии Келя дрогнут, и как только мы захватим гавань, мы нанесем смертельный удар!','Задание выполнено, $N?','Вернитесь к магистру Иластару в Оружейную Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захват гавани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отборные войска Кель\'таса – Клинки Рассвета – расположились в гавани Солнечного Края и в Деревне Утренней Звезды.$B$BГавань чрезвычайно важна для наших планов, так что каждый убитый Клинок Рассвета – огромная помощь. Кель\'тас будет проклинать тот миг, когда обратился против собственного народа и заключил союз с Пылающим Легионом!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей и 3 метких стрелков из клана Клинка Рассвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отличная работа, |3-6)$C). Армии Келя дрогнут, и как только мы захватим гавань, мы нанесем смертельный удар!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Задание выполнено, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Иластару в Оружейную Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11540,'Клинки Рассвета должны быть сокрушены!','Мы вытеснили Клинок Рассвета из гавани Солнечного Края. Теперь Солнечный Край полностью наш. Но я почему-то не удовлетворен...$B$BПрошу тебя отправиться в Деревню Утренней Звезды, к западу отсюда, и перебить всех уцелевших бойцов Клинка Рассвета. Они сами обрекли себя, последовав сюда за Келем.','Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей и 3 метких стрелков из клана Клинка Рассвета.','Вернитесь к магистру Иластару в Оружейную Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клинки Рассвета должны быть сокрушены!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы вытеснили Клинок Рассвета из гавани Солнечного Края. Теперь Солнечный Край полностью наш. Но я почему-то не удовлетворен...$B$BПрошу тебя отправиться в Деревню Утренней Звезды, к западу отсюда, и перебить всех уцелевших бойцов Клинка Рассвета. Они сами обрекли себя, последовав сюда за Келем.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей и 3 метких стрелков из клана Клинка Рассвета.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к магистру Иластару в Оружейную Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11541,'Зачистить залив Зеленожабрых!','Наги захватили залив Зеленожабрых к юго-востоку отсюда. Их самки, сирены из клана Черноспинов, используют магию для подчинения местных мурлоков.$B$BЯ обязана следить за тем, чтобы любая высунувшаяся нага была уничтожена. И в этом мне нужна твоя помощь.$B$B$C, я прошу тебя добыть сферы управления у наг и разбросать их возле зеленожабрых-рабов, разбив сферы и освободив рабов.$B$BПодозреваю, что разъяренные мурлоки набросятся на своих хозяев.','Капитан Валиндрия просит вас освободить 10 зеленожабрых-рабов в Заливе Зеленожабрых. Вернитесь к ней на борт "Гордости Луносвета" в гавань Солнечного Края по выполнении задания.','Мне нужно столько очищенного металла Ата\'мала, |3-6($C), сколько я сумею переработать.','Вернитесь к капитану Валиндрии в Гавань Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Зачистить залив Зеленожабрых!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наги захватили залив Зеленожабрых к юго-востоку отсюда. Их самки, сирены из клана Черноспинов, используют магию для подчинения местных мурлоков.$B$BЯ обязана следить за тем, чтобы любая высунувшаяся нага была уничтожена. И в этом мне нужна твоя помощь.$B$B$C, я прошу тебя добыть сферы управления у наг и разбросать их возле зеленожабрых-рабов, разбив сферы и освободив рабов.$B$BПодозреваю, что разъяренные мурлоки набросятся на своих хозяев.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Капитан Валиндрия просит вас освободить 10 зеленожабрых-рабов в Заливе Зеленожабрых. Вернитесь к ней на борт "Гордости Луносвета" в гавань Солнечного Края по выполнении задания.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно столько очищенного металла Ата\'мала, |3-6($C), сколько я сумею переработать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к капитану Валиндрии в Гавань Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11542,'Перехватить подкрепление','Мы изо всех сил стараемся укрепить свой контроль над Солнечным Краем. Следующая наша цель – захват гавани. К несчастью, в гавань направляется флот резервистов из клана Клинка Рассвета на помощь войскам Келя.$B$BБери это масло и возьми дракондора у Айрена Ясное Небо. Тебе надо будет подлететь почти к самым парусам – как только окажешься достаточно близко, подожги их.$B$BВысадись на один из кораблей и атакуй резервистов. Когда паруса их корабля вспыхнут, они не особо будут сопротивляться.','Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясное Небо насчет полета до флота Клинка Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса кораблей, а приземлившись, убейте 6 резервистов из клана Клинка Рассвета.','Хорошая работа, $N. Нескоро теперь гавань получит подкрепление.','Задание выполнено, $N?','Вернитесь к воздаятелю Каалану в Оружейную Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перехватить подкрепление',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы изо всех сил стараемся укрепить свой контроль над Солнечным Краем. Следующая наша цель – захват гавани. К несчастью, в гавань направляется флот резервистов из клана Клинка Рассвета на помощь войскам Келя.$B$BБери это масло и возьми дракондора у Айрена Ясное Небо. Тебе надо будет подлететь почти к самым парусам – как только окажешься достаточно близко, подожги их.$B$BВысадись на один из кораблей и атакуй резервистов. Когда паруса их корабля вспыхнут, они не особо будут сопротивляться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясное Небо насчет полета до флота Клинка Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса кораблей, а приземлившись, убейте 6 резервистов из клана Клинка Рассвета.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Хорошая работа, $N. Нескоро теперь гавань получит подкрепление.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Задание выполнено, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Каалану в Оружейную Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11543,'Загнать врага в угол','Нам удалось полностью захватить Солнечный Край. К несчастью, в гавань направляется флот резервистов из клана Клинка Рассвета на помощь войскам Келя.$B$BБери это масло и возьми дракондора у Айрена Ясное Небо. Тебе надо будет подлететь почти к самым парусам – как только окажешься достаточно близко, подожги их.$B$BВысадись на один из кораблей и атакуй резервистов. Когда паруса их корабля вспыхнут, они не особо будут сопротивляться.','Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясное Небо насчет полета до флота Клинка Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса корабля, а приземлившись, убейте 6 резервистов из клана Клинка Рассвета.','Вернитесь к воздаятелю Каалану в Оружейную Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Загнать врага в угол',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нам удалось полностью захватить Солнечный Край. К несчастью, в гавань направляется флот резервистов из клана Клинка Рассвета на помощь войскам Келя.$B$BБери это масло и возьми дракондора у Айрена Ясное Небо. Тебе надо будет подлететь почти к самым парусам – как только окажешься достаточно близко, подожги их.$B$BВысадись на один из кораблей и атакуй резервистов. Когда паруса их корабля вспыхнут, они не особо будут сопротивляться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясное Небо насчет полета до флота Клинка Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса корабля, а приземлившись, убейте 6 резервистов из клана Клинка Рассвета.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятелю Каалану в Оружейную Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11544,'Оружие Ата\'мала','Терраса Ата\'мала на востоке Долины Призрачной Луны – священное место для дренеев, но ныне его захватили орки Скверны. Они добывают в тех местах особую руду, создают оружие и доспехи, полные порчи.$B$BМне нужно это вооружение, чтобы создать сплав с рудой наг. Наши анахореты благословили мою наковальню, и она может очистить их от скверны.$B$BДобудь оружие у избранных, душегубов и темнопрядов Долины Призрачной Луны. Принеси оружие сюда, раздроби его и очисти на моей наковальне и отдай мне то, что выйдет.','Кузнец Хаутаа просит вас сделать для нее 5 кусков очищенного металла Ата\'мала. Сделайте это, раздробив на ее наковальне оружие Ата\'мала в оружейной Солнечного Края на острове Кель\'Данас.','Благодарю тебя, мой друг. Теперь я смогу сделать больше специального сплава, который пойдет на изготовление оружия и доспехов для нашей армии.\n\nИ еще у меня осталось немного лишнего сплава, который наверняка пригодится тебе на оружие. Прошу – выбирай какой хочешь кусок.\n\nИ снова приходи поутру. Мне наверняка понадобится новая порция металла.','Мне нужно столько очищенного металла Ата\'мала, |3-6($C), сколько я сумею переработать.','Вернитесь к кузнецу Хаутае на Залив Зеленожабрых, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оружие Ата\'мала',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Терраса Ата\'мала на востоке Долины Призрачной Луны – священное место для дренеев, но ныне его захватили орки Скверны. Они добывают в тех местах особую руду, создают оружие и доспехи, полные порчи.$B$BМне нужно это вооружение, чтобы создать сплав с рудой наг. Наши анахореты благословили мою наковальню, и она может очистить их от скверны.$B$BДобудь оружие у избранных, душегубов и темнопрядов Долины Призрачной Луны. Принеси оружие сюда, раздроби его и очисти на моей наковальне и отдай мне то, что выйдет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Кузнец Хаутаа просит вас сделать для нее 5 кусков очищенного металла Ата\'мала. Сделайте это, раздробив на ее наковальне оружие Ата\'мала в оружейной Солнечного Края на острове Кель\'Данас.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Благодарю тебя, мой друг. Теперь я смогу сделать больше специального сплава, который пойдет на изготовление оружия и доспехов для нашей армии.\n\nИ еще у меня осталось немного лишнего сплава, который наверняка пригодится тебе на оружие. Прошу – выбирай какой хочешь кусок.\n\nИ снова приходи поутру. Мне наверняка понадобится новая порция металла.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно столько очищенного металла Ата\'мала, |3-6($C), сколько я сумею переработать.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к кузнецу Хаутае на Залив Зеленожабрых, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11545,'Никто не забыт...','Мы отбили гавань Солнечного Края у врага, и окончательная победа уже не за горами. Цену мы заплатили высокую, и многие отважные бойцы положили свои жизни ради этой победы.$B$BЯ хочу, чтобы никто из погибших не был забыт. Прошу вас подумать насчет того, чтобы внести пожертвования в мемориальный фонд. Все оставшееся золото пойдет вдовам и сиротам погибших.','Анахорет Оури из Солнечного Края острова Солнечного Колодца просит вас пожертвовать 10 золотых.','У вас благородная душа, $N. Среди грохота войны или ликования победы легко забыть о павших. Друзья и родственники погибших благодарят вас.','Вы хотите сделать пожертвование?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Никто не забыт...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы отбили гавань Солнечного Края у врага, и окончательная победа уже не за горами. Цену мы заплатили высокую, и многие отважные бойцы положили свои жизни ради этой победы.$B$BЯ хочу, чтобы никто из погибших не был забыт. Прошу вас подумать насчет того, чтобы внести пожертвования в мемориальный фонд. Все оставшееся золото пойдет вдовам и сиротам погибших.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Анахорет Оури из Солнечного Края острова Солнечного Колодца просит вас пожертвовать 10 золотых.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У вас благородная душа, $N. Среди грохота войны или ликования победы легко забыть о павших. Друзья и родственники погибших благодарят вас.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы хотите сделать пожертвование?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11546,'Взаимовыгодный бизнес','Добро пожаловать, $n.$b$bЯ много чем могу помочь тебе в твоих тутошних трудах.$b$bНапример, я недавно изобрела рецепт уникального эликсира.$b$bВо многих местах Азерота в изобилии растет дикая кровяника. Ее долгое время считали ни на что не годной. Но я узнала, что если подвергнуть это растение влиянию Солнечного Колодца, оно приобретает особые свойства. И если сделать из растения экстракт и выпить, оно будет усиливать твои способности.$b$bПринеси мне ягод с ближайшего куста, и я покажу тебе, что имела в виду.','Мар\'на из гавани Солнечного Края просит вас принести ей 5 ягод кровяники с кустов, которые можно найти на Кель\'Данасе.','Ну, как, принес ягод?','Вернитесь к Мар\'не в Гавань Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Взаимовыгодный бизнес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Добро пожаловать, $n.$b$bЯ много чем могу помочь тебе в твоих тутошних трудах.$b$bНапример, я недавно изобрела рецепт уникального эликсира.$b$bВо многих местах Азерота в изобилии растет дикая кровяника. Ее долгое время считали ни на что не годной. Но я узнала, что если подвергнуть это растение влиянию Солнечного Колодца, оно приобретает особые свойства. И если сделать из растения экстракт и выпить, оно будет усиливать твои способности.$b$bПринеси мне ягод с ближайшего куста, и я покажу тебе, что имела в виду.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Мар\'на из гавани Солнечного Края просит вас принести ей 5 ягод кровяники с кустов, которые можно найти на Кель\'Данасе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как, принес ягод?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мар\'не в Гавань Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11547,'Знай свою силовую линию!','Нахлебники!$b$bВам все сразу вынь да положь! Вы представления не имеете, сколько надо сил затратить, чтобы создать даже самый простенький портал!$b$bНу, ничего, я научу вас уважать мои труды!$b$bВозьми этот кристалл. Настрой его на Кровавый кристалл, что на западе, на Рассветную площадь, что к югу отсюда, и на святилище наг в заливе Зеленожабрых к юго-востоку.$b$bМожет, тогда ты начнешь больше ценить дар перемещений в пространстве...','Звездочет Дарнариан из святилища Солнечного Края просит вас при помощи кристалла звездочета настроить кровавый кристалл, портал на Рассветной площади и святилище наг в заливе Зеленожабрых.','Вернитесь к звездочету Дарнариану в Святилище Солнечного Края, что на Острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Знай свою силовую линию!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нахлебники!$b$bВам все сразу вынь да положь! Вы представления не имеете, сколько надо сил затратить, чтобы создать даже самый простенький портал!$b$bНу, ничего, я научу вас уважать мои труды!$b$bВозьми этот кристалл. Настрой его на Кровавый кристалл, что на западе, на Рассветную площадь, что к югу отсюда, и на святилище наг в заливе Зеленожабрых к юго-востоку.$b$bМожет, тогда ты начнешь больше ценить дар перемещений в пространстве...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Звездочет Дарнариан из святилища Солнечного Края просит вас при помощи кристалла звездочета настроить кровавый кристалл, портал на Рассветной площади и святилище наг в заливе Зеленожабрых.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к звездочету Дарнариану в Святилище Солнечного Края, что на Острове Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11548,'Щедрое пожертвование','Мы построили мемориал в честь погибших в этой битве. Хоть какое-то утешение для семей, потерявших своих любимых.$B$BЯ собираю пожертвования для сирот и вдов героев войны. Если вы можете пожертвовать немного денег, им хватит на жизнь.','Анахорет Оури из Солнечного Края острова Солнечного Колодца просит вас пожертвовать 10 золотых.','Вы хотите сделать пожертвование?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Щедрое пожертвование',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы построили мемориал в честь погибших в этой битве. Хоть какое-то утешение для семей, потерявших своих любимых.$B$BЯ собираю пожертвования для сирот и вдов героев войны. Если вы можете пожертвовать немного денег, им хватит на жизнь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Анахорет Оури из Солнечного Края острова Солнечного Колодца просит вас пожертвовать 10 золотых.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы хотите сделать пожертвование?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11549,'Великодушный благодетель','Вы столько сделали для нас, $n. Мы высоко ценим вашу помощь.$B$BНаверное, вы уже заметили анахорета Оури? Она великодушна и умеет убеждать, но пожертвования не так щедры, как она ожидала.$B$BЕсли вы пожертвуете внушительную сумму, я постараюсь, чтобы известия о вашем поступке разошлись широко и далеко. Что скажете?','У вас благородная душа, и вы – $Gдостойный:достойная; $Gсоюзник:союзница;. Отныне вас будут называть $N из Расколотого Солнца, и все, кто здесь сражается, узнают о ваших деяниях!','Вы готовы сделать пожертвование?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Великодушный благодетель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы столько сделали для нас, $n. Мы высоко ценим вашу помощь.$B$BНаверное, вы уже заметили анахорета Оури? Она великодушна и умеет убеждать, но пожертвования не так щедры, как она ожидала.$B$BЕсли вы пожертвуете внушительную сумму, я постараюсь, чтобы известия о вашем поступке разошлись широко и далеко. Что скажете?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У вас благородная душа, и вы – $Gдостойный:достойная; $Gсоюзник:союзница;. Отныне вас будут называть $N из Расколотого Солнца, и все, кто здесь сражается, узнают о ваших деяниях!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы готовы сделать пожертвование?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11550,'Входи, Искуситель...','Несмотря на все наши усилия, страшные планы Кель\'таса свершились. Солнечный Колодец снова вспыхнул, готовый к прибытию Искусителя.$B$BПредмет, находящийся передо мной и ниже А\'дала представляет собой нынешнее положение дел с обороной Солнечного Колодца. Вокруг него воздвигнуты мощные преграды, не дающие нам напасть на внутренние чертоги. Если когда нашему миру и была нужна помощь, так теперь.$B$BСообщи обо всем верховному магу Нет\'улу на остров Кель\'Данас, что к северу от Кель\'Таласа.','Отнесите сообщение верховному магу Нет\'улу на остров Кель\'Данас, к северу от Кель\'Таласа.$B$BЛюбой распорядитель полетов в Стальгорне или Луносвете доставит вас до места назначения.','Килджеден обрушивается на этот мир со всей силой Пылающего Легиона. Если призыв будет завершен, наш мир снова будет повергнут в муки хаоса. Ваша помощь на острове Кел\'Данас имеет решающее значение для нашего успеха против Пылающего Легиона.$B$BНаши маги работают над устранением барьеров, блокирующих доступ к Солнечному Колодцу. Примите участие в борьбе с силами Легиона, помогая Армии Расколотого Солнца.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Входи, Искуситель...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Несмотря на все наши усилия, страшные планы Кель\'таса свершились. Солнечный Колодец снова вспыхнул, готовый к прибытию Искусителя.$B$BПредмет, находящийся передо мной и ниже А\'дала представляет собой нынешнее положение дел с обороной Солнечного Колодца. Вокруг него воздвигнуты мощные преграды, не дающие нам напасть на внутренние чертоги. Если когда нашему миру и была нужна помощь, так теперь.$B$BСообщи обо всем верховному магу Нет\'улу на остров Кель\'Данас, что к северу от Кель\'Таласа.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите сообщение верховному магу Нет\'улу на остров Кель\'Данас, к северу от Кель\'Таласа.$B$BЛюбой распорядитель полетов в Стальгорне или Луносвете доставит вас до места назначения.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Килджеден обрушивается на этот мир со всей силой Пылающего Легиона. Если призыв будет завершен, наш мир снова будет повергнут в муки хаоса. Ваша помощь на острове Кел\'Данас имеет решающее значение для нашего успеха против Пылающего Легиона.$B$BНаши маги работают над устранением барьеров, блокирующих доступ к Солнечному Колодцу. Примите участие в борьбе с силами Легиона, помогая Армии Расколотого Солнца.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (11551,'Агамат, Первые врата','Вернитесь к верховному магу Нет\'улу на Остров Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Агамат, Первые врата',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Нет\'улу на Остров Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (11552,'Рохендор, Вторые врата','Вернитесь к верховному магу Нет\'улу на Остров Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рохендор, Вторые врата',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Нет\'улу на Остров Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (11553,'Архониус, Последние врата','Вернитесь к верховному магу Нет\'улу на Остров Кель\'Данас.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Архониус, Последние врата',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Нет\'улу на Остров Кель\'Данас.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11554,'Солдатская дружба','Твоя помощь наступательной группировке была замечена, $N. Объединенные силы Алдоров и Провидцев благодарят тебя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Солдатская дружба',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Твоя помощь наступательной группировке была замечена, $N. Объединенные силы Алдоров и Провидцев благодарят тебя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11555,'Уважение союзников','Ты непрестанно проявляешь себя в этой самой важной из битв, $N. Прошу – прими это в знак нашей великой благодарности.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уважение союзников',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты непрестанно проявляешь себя в этой самой важной из битв, $N. Прошу – прими это в знак нашей великой благодарности.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11556,'Почтение боевых друзей','Без тебя мы не смогли бы сделать того, что сделали, $N. Объединённых сил Алдоров и Провидцев недостаточно, чтобы сокрушить Легион и Келя. Мы рады, что у нас есть такие могучие союзники, как ты.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Почтение боевых друзей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Без тебя мы не смогли бы сделать того, что сделали, $N. Объединённых сил Алдоров и Провидцев недостаточно, чтобы сокрушить Легион и Келя. Мы рады, что у нас есть такие могучие союзники, как ты.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11557,'Восхищение всего войска','Ты – $Gодин:одна; из наших лучших бойцов, $N. Твое имя будут помнить среди нас еще долго.$B$BПрошу – прими этот небольшой подарок от имени всего войска.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Восхищение всего войска',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты – $Gодин:одна; из наших лучших бойцов, $N. Твое имя будут помнить среди нас еще долго.$B$BПрошу – прими этот небольшой подарок от имени всего войска.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11558,'Опасная любовь','И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.$b$bДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.$b$bОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.','Раздобудьте заплесневелую открытку Стража и отнесите ее Фенстаду Аргайлу в Подгород.','Вернитесь к Фенстаду Аргайлу в Подгород.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опасная любовь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','И все-таки что-то неладно с этой эпидемией любви. Это просто противно, а поскольку это ослабляет нашу защиту, то, ко всему прочему, может представлять угрозу для всех нас.$b$bДостаточно плохо уже то, что многие из нашего народа переняли это странное поведение. Но мне кажется, что эту заразу подхватили даже наши стражники, которые должны быть невосприимчивы к таким вещам.$b$bОтправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Раздобудьте заплесневелую открытку Стража и отнесите ее Фенстаду Аргайлу в Подгород.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Фенстаду Аргайлу в Подгород.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11559,'Торговля с Зимними Плавниками','Теперь, когда ты можешь говорить с Зимними Плавниками, самое время познакомиться с ними поближе. А один из лучших способов с ними познакомиться – это вступить с ними в деловые отношения.$b$bМурлоки больше всего ценят моллюсков, а торгует ими сейчас один только Ахлурглгр. На твоем месте я набрал бы моллюсков Зимних Плавников и подарил ему.$b$bМоллюсков можно набрать во рву, а также в деревне Зимних Плавников и в пещерах.','Соберите 5 моллюсков Зимних Плавников и отдайте их Ахлурглгру в Приюте Зимних Плавников.','Вернитесь к Ахлурглгру в Приют Зимних Плавников, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Торговля с Зимними Плавниками',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты можешь говорить с Зимними Плавниками, самое время познакомиться с ними поближе. А один из лучших способов с ними познакомиться – это вступить с ними в деловые отношения.$b$bМурлоки больше всего ценят моллюсков, а торгует ими сейчас один только Ахлурглгр. На твоем месте я набрал бы моллюсков Зимних Плавников и подарил ему.$b$bМоллюсков можно набрать во рву, а также в деревне Зимних Плавников и в пещерах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 5 моллюсков Зимних Плавников и отдайте их Ахлурглгру в Приюте Зимних Плавников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ахлурглгру в Приют Зимних Плавников, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11560,'О нет, наши бедные малыши!','Как хорошо, что ты снова здесь!$B$BКогда из-за оползня в деревне напротив, обнажились пещеры, из одной из них вылез злобный лангустин, которого называют Клаксимус, и похитил малышню Зимних Плавников.$B$BЧто-то странное произошло со всеми мурлоками, погнавшимися за ним, и когда они показались вновь, то оказались подвластны ему.$B$B$C, ты $gдолжен:должна; переплыть эти воды и спасти малышей Зимних Плавников в деревне и в пещерах.$B$BБудущее племени Зимних Плавников зависит от тебя!','По поручению короля Мргла-Мргла спасите 20 головастиков Зимних Плавников. Вернитесь к королю в Приют Зимних Плавников, когда выполните задание.','Теперь, что бы ни случилось, будущее Зимних Плавников обеспечено.$B$BТебя стоит похвалить и вознаградить за бескорыстную помощь, $N!','Если не спасти головастиков, все остальное не будет иметь значения: у мурлоков Зимних Плавников не останется шансов выжить!','Вернитесь к Королю Мргл-Мрглу в Приют Зимних Плавников, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','О нет, наши бедные малыши!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как хорошо, что ты снова здесь!$B$BКогда из-за оползня в деревне напротив, обнажились пещеры, из одной из них вылез злобный лангустин, которого называют Клаксимус, и похитил малышню Зимних Плавников.$B$BЧто-то странное произошло со всеми мурлоками, погнавшимися за ним, и когда они показались вновь, то оказались подвластны ему.$B$B$C, ты $gдолжен:должна; переплыть эти воды и спасти малышей Зимних Плавников в деревне и в пещерах.$B$BБудущее племени Зимних Плавников зависит от тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению короля Мргла-Мргла спасите 20 головастиков Зимних Плавников. Вернитесь к королю в Приют Зимних Плавников, когда выполните задание.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь, что бы ни случилось, будущее Зимних Плавников обеспечено.$B$BТебя стоит похвалить и вознаградить за бескорыстную помощь, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если не спасти головастиков, все остальное не будет иметь значения: у мурлоков Зимних Плавников не останется шансов выжить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Королю Мргл-Мрглу в Приют Зимних Плавников, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11561,'Они!','Наши сестры и братья по ту сторону стали нашими злейшими врагами. Они похитили наших малюток, выгнали нас из деревни, а убили стольких, что и не счесть.$B$BДокажи нам, чего ты стоишь, |3-6($r)! Переплыви расселину и убей их!$B$BНесмотря на расположение, выказанное тебе нашим новым королем, это единственное, чем ты можешь попытаться добиться нашего доверия. Если потерпишь неудачу – лучше не возвращайся!','По просьбе Брглмургла в Приюте Зимних Плавников убейте воинов, оракулов и гарпунеров Зимних Плавников – всего 15 мурлоков.','Если ты уже $Gубил:убила; так много этих предателей Зимних Плавников, почему же, когда я смотрю на ту сторону, я по-прежнему вижу их в таком количестве?','Вернитесь к Брглмурглу в Приют Зимних Плавников, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Они!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши сестры и братья по ту сторону стали нашими злейшими врагами. Они похитили наших малюток, выгнали нас из деревни, а убили стольких, что и не счесть.$B$BДокажи нам, чего ты стоишь, |3-6($r)! Переплыви расселину и убей их!$B$BНесмотря на расположение, выказанное тебе нашим новым королем, это единственное, чем ты можешь попытаться добиться нашего доверия. Если потерпишь неудачу – лучше не возвращайся!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Брглмургла в Приюте Зимних Плавников убейте воинов, оракулов и гарпунеров Зимних Плавников – всего 15 мурлоков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты уже $Gубил:убила; так много этих предателей Зимних Плавников, почему же, когда я смотрю на ту сторону, я по-прежнему вижу их в таком количестве?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Брглмурглу в Приют Зимних Плавников, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11562,'Меня хотят очернить!','Я должен сознаться в некоем... конфузе: меня шантажируют!$B$BМрмрглмр согласился почистить кое-какие мои вещи и захватил мой запасной костюм мурлока. И теперь угрожает раскрыть мою истинную природу всем остальным мурлокам.$B$BНет нужды объяснять, какой катастрофой это было бы! Кроме того, у меня есть один план, предполагающий, что костюм нам понадобится вернуть. $B$BПрошу тебя, $n, пойди к Мрмрглмр на другую сторону Приюта, к северу, и сделай все, что он от тебя потребует.','По просьбе короля Мргла-Мргла поговорите с Мрмрглмром на северо-западной стороне Приюта Зимних Плавников.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Меня хотят очернить!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я должен сознаться в некоем... конфузе: меня шантажируют!$B$BМрмрглмр согласился почистить кое-какие мои вещи и захватил мой запасной костюм мурлока. И теперь угрожает раскрыть мою истинную природу всем остальным мурлокам.$B$BНет нужды объяснять, какой катастрофой это было бы! Кроме того, у меня есть один план, предполагающий, что костюм нам понадобится вернуть. $B$BПрошу тебя, $n, пойди к Мрмрглмр на другую сторону Приюта, к северу, и сделай все, что он от тебя потребует.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе короля Мргла-Мргла поговорите с Мрмрглмром на северо-западной стороне Приюта Зимних Плавников.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11563,'Грммурглл Мрллглл Глрггл!','Если бы твои жалкие глазенки не были так подслеповаты, тебе не составило бы труда разглядеть, что нас истребляют косатки, живущие на севере бухты!$b$bРаз уж ваш ненаглядный король ночных эльфов желает получить обратно свой парадный костюмчик, думаю, ты согласишься оказать мне услугу и добыть голову короля косаток, Глрггла, того, кто плывет против течения судеб, губя при этом надежды тех, кто услышит песнь смерти над волнами!$b$bНе медли, |3-6($r), не медли: пока мы тратим время на болтовню, мурлоки Зимних Плавников гибнут один за другим!','Принесите Мрмрглмру в Приюте Зимних Плавников голову Глрггла.','Если у тебя нет головы Глрггла, мне с тобой говорить не о чем!','Вернитесь к Мрмрглмру в Приют Зимних Плавников, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грммурглл Мрллглл Глрггл!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если бы твои жалкие глазенки не были так подслеповаты, тебе не составило бы труда разглядеть, что нас истребляют косатки, живущие на севере бухты!$b$bРаз уж ваш ненаглядный король ночных эльфов желает получить обратно свой парадный костюмчик, думаю, ты согласишься оказать мне услугу и добыть голову короля косаток, Глрггла, того, кто плывет против течения судеб, губя при этом надежды тех, кто услышит песнь смерти над волнами!$b$bНе медли, |3-6($r), не медли: пока мы тратим время на болтовню, мурлоки Зимних Плавников гибнут один за другим!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мрмрглмру в Приюте Зимних Плавников голову Глрггла.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если у тебя нет головы Глрггла, мне с тобой говорить не о чем!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мрмрглмру в Приют Зимних Плавников, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11564,'Наваристая похлебка из косатки','Ходят слухи, $gчужеземный:чужеземная:r; |3-6($r), что ты, возможно, охотишься на короля косаток Глрггла.$B$BВсе это очень даже хорошо, но, если хочешь отведать похлебку, за которую можно полжизни отдать, принеси мне мясистых сальников косаток, что обитают в Мерцающей бухте.$B$BПоспеши... мне нужно будет долго обрезать мясо с костей, если ты захочешь насладиться плодами своих усилий.','По поручению Колуна Бмурглбрма добудьте и принесите 7 кусков мясистого сальника косатки. С мясом возвращайтесь к нему в Приют Зимних Плавников.','О-o да, эти куски отлично подойдут.$B$BПлюхни их тут где-нибудь. А пока можешь попробовать остатки моей вчерашней похлебки.','Вернитесь к Колуну Бмурглбрму в Приют Зимних Плавников, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наваристая похлебка из косатки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ходят слухи, $gчужеземный:чужеземная:r; |3-6($r), что ты, возможно, охотишься на короля косаток Глрггла.$B$BВсе это очень даже хорошо, но, если хочешь отведать похлебку, за которую можно полжизни отдать, принеси мне мясистых сальников косаток, что обитают в Мерцающей бухте.$B$BПоспеши... мне нужно будет долго обрезать мясо с костей, если ты захочешь насладиться плодами своих усилий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Колуна Бмурглбрма добудьте и принесите 7 кусков мясистого сальника косатки. С мясом возвращайтесь к нему в Приют Зимних Плавников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','О-o да, эти куски отлично подойдут.$B$BПлюхни их тут где-нибудь. А пока можешь попробовать остатки моей вчерашней похлебки.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Колуну Бмурглбрму в Приют Зимних Плавников, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11565,'Запасной комплект','Отлично, тайна твоего короля останется со мной до тех пор, пока он не перестанет помогать нам бороться с нашими врагами.$B$BВот это доставь ему. Я как следует отчистил эту штуку, хотя не понимаю, зачем ему понадобился второй маскировочный костюм.$B$BМожет быть, у него что-то на уме касательно тебя?','Верните запасной костюм короля Мргла-Мргла королю Мрглу-Мрглу в Приют Зимних Плавников.','<Увидев запасной костюм мурлока, король потирает принадлежности костюма.>$B$BОтлично. Теперь вернемся к неотложным делам. У меня есть к тебе дело чрезвычайной важности.','У тебя с собой мой запасной костюм, $N?','Вернитесь к Королю Мргл-Мрглу в Приют Зимних Плавников, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Запасной комплект',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отлично, тайна твоего короля останется со мной до тех пор, пока он не перестанет помогать нам бороться с нашими врагами.$B$BВот это доставь ему. Я как следует отчистил эту штуку, хотя не понимаю, зачем ему понадобился второй маскировочный костюм.$B$BМожет быть, у него что-то на уме касательно тебя?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Верните запасной костюм короля Мргла-Мргла королю Мрглу-Мрглу в Приют Зимних Плавников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Увидев запасной костюм мурлока, король потирает принадлежности костюма.>$B$BОтлично. Теперь вернемся к неотложным делам. У меня есть к тебе дело чрезвычайной важности.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','У тебя с собой мой запасной костюм, $N?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Королю Мргл-Мрглу в Приют Зимних Плавников, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11566,'Сдаться? Ни за что!','Настало время положить конец этой противоестественной ситуации, $n! Клаксимус должен умереть, иначе у Зимних Плавников нет будущего!$b$bВозьми мой запасной костюм мурлока и спустись в пещеры Зимних Плавников, делая вид, будто хочешь сдаться. Пока у тебя в руке будет белый флаг, мурлоки не нападут.$b$bТы найдешь Клаксимуса в самом дальнем юго-западном углу пещер. Подберись поближе и покончи с ним! И принеси мне его коготь в доказательство.','Принесите коготь Клаксимуса королю Мргл-Мргл в Приюте Зимних Плавников.','Печально, но необходимо. Я заберу этот коготь, $N.$B$BСпасибо тебе за оказанную нам помощь. Теперь, когда Клаксимус повержен, мы, возможно, сумеем воссоединить тех мурлоков, что остались в живых, и закрыть пещеры.$B$BПрошу тебя, прими вот это... это самое меньшее, чем я могу отблагодарить тебя за услуги!','Ну что, $C, дело сделано? Клаксимус мертв?','Вернитесь к Королю Мргл-Мрглу в Приют Зимних Плавников, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сдаться? Ни за что!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Настало время положить конец этой противоестественной ситуации, $n! Клаксимус должен умереть, иначе у Зимних Плавников нет будущего!$b$bВозьми мой запасной костюм мурлока и спустись в пещеры Зимних Плавников, делая вид, будто хочешь сдаться. Пока у тебя в руке будет белый флаг, мурлоки не нападут.$b$bТы найдешь Клаксимуса в самом дальнем юго-западном углу пещер. Подберись поближе и покончи с ним! И принеси мне его коготь в доказательство.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите коготь Клаксимуса королю Мргл-Мргл в Приюте Зимних Плавников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Печально, но необходимо. Я заберу этот коготь, $N.$B$BСпасибо тебе за оказанную нам помощь. Теперь, когда Клаксимус повержен, мы, возможно, сумеем воссоединить тех мурлоков, что остались в живых, и закрыть пещеры.$B$BПрошу тебя, прими вот это... это самое меньшее, чем я могу отблагодарить тебя за услуги!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, $C, дело сделано? Клаксимус мертв?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Королю Мргл-Мрглу в Приют Зимних Плавников, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11567,'Да, я работал на судне, перевозившем доспехи. Мы закончили погрузку и направились обратно в лагерь, но тут на нас напал эсминец Отрекшихся.$B$BОни взяли нас на абордаж, забрали всю добычу себе, а корабль потопили.$B$BС тех пор я эти доспехи не видел. Если хочешь, возьми мою лодку в лагере Скалаваг и отправляйся на остров, где пришвартован этот эсминец. Поговори с моей бабой, Аланией – пусть она посадит тебя на бомбардировщик.$B$BДа, если найдешь эти железяки – не вздумай притащить их сюда!','Ты $gнашел:нашла; доспехи?','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, я работал на судне, перевозившем доспехи. Мы закончили погрузку и направились обратно в лагерь, но тут на нас напал эсминец Отрекшихся.$B$BОни взяли нас на абордаж, забрали всю добычу себе, а корабль потопили.$B$BС тех пор я эти доспехи не видел. Если хочешь, возьми мою лодку в лагере Скалаваг и отправляйся на остров, где пришвартован этот эсминец. Поговори с моей бабой, Аланией – пусть она посадит тебя на бомбардировщик.$B$BДа, если найдешь эти железяки – не вздумай притащить их сюда!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $gнашел:нашла; доспехи?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11568,'Возвращение святынь','<Орфус протягивает вам сумку.>$B$BВ этой сумке находятся найденные тобой артефакты. Далеко на юго-востоке есть Заградительный холм. Найди там курганы, из которых были похищены эти святыни, и верни их на место. Надеюсь, этот благородный жест умиротворит неприкаянных духов, что бродят по нашим охотничьим угодьям.$B$BКрепись, $n...','Дело сделано? Духи упокоились с миром?','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение святынь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Орфус протягивает вам сумку.>$B$BВ этой сумке находятся найденные тобой артефакты. Далеко на юго-востоке есть Заградительный холм. Найди там курганы, из которых были похищены эти святыни, и верни их на место. Надеюсь, этот благородный жест умиротворит неприкаянных духов, что бродят по нашим охотничьим угодьям.$B$BКрепись, $n...',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дело сделано? Духи упокоились с миром?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Орфусу Камагуанскому к Древнему подъемнику, что в Ревущем фьорде.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11569,'Хранитель ключей Ургргрл','Мне нужно выбраться из этих пещер! Из Хладарры, сверху, просвечивается какая-то магическая энергия и сводит всех с ума.$B$BЯ не хочу, чтобы меня взяли под контроль, как остальных!$B$BТам, ниже и к югу, в пещере, находится хранитель ключей Ургргрл; ключ от моей клетки – у него. Забери у него ключ и принеси сюда, чтобы я мог отпереть клетку и выбраться отсюда.$B$BСкорее!','По просьбе Глрглрглра в пещерах Зимних Плавников раздобудьте ключ Ургргрла.','Дай же, дай мне его скорее!','Ну, где же ключ?$B$BНет, до других мне нет никакого дела. Я просто хочу убраться отсюда!','Вернитесь к Глрглрглру в Пещеры Зимних Плавников, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хранитель ключей Ургргрл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно выбраться из этих пещер! Из Хладарры, сверху, просвечивается какая-то магическая энергия и сводит всех с ума.$B$BЯ не хочу, чтобы меня взяли под контроль, как остальных!$B$BТам, ниже и к югу, в пещере, находится хранитель ключей Ургргрл; ключ от моей клетки – у него. Забери у него ключ и принеси сюда, чтобы я мог отпереть клетку и выбраться отсюда.$B$BСкорее!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Глрглрглра в пещерах Зимних Плавников раздобудьте ключ Ургргрла.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Дай же, дай мне его скорее!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, где же ключ?$B$BНет, до других мне нет никакого дела. Я просто хочу убраться отсюда!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Глрглрглру в Пещеры Зимних Плавников, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11570,'Бегство из пещер Зимних Плавников','Замок на моей клетке выглядит не особо прочным, но глупо было бы пытаться бежать без посторонней помощи.$b$bНе подсобишь ли мне выбраться из этих пещер? Нельзя терять ни минуты, |3-6($r)!$b$bКогда вернешься в приют, пожалуйста, дай королю знать, что со мной все в порядке. Он наверняка вознаградит тебя!','Проводите Лургглбра в безопасное место и вернитесь к королю Мргл-Мрглу в Приют Зимних Плавников, чтобы сообщить ему хорошую новость.','Превосходное известие! Так значит, Лургглбр обнаружил, что безумие вызывают испарения этих пещер?$B$BДолжно быть, магия Хладарры становится все сильнее… Война Нексуса… битва между синими и всеми прочими драконами все разгорается.$B$BСкоро нас всех в это втянут!','Да, $N? Чем могу служить?','Проводите Лургглбра в безопасное место','Вернитесь к Королю Мргл-Мрглу в Приют Зимних Плавников, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бегство из пещер Зимних Плавников',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Замок на моей клетке выглядит не особо прочным, но глупо было бы пытаться бежать без посторонней помощи.$b$bНе подсобишь ли мне выбраться из этих пещер? Нельзя терять ни минуты, |3-6($r)!$b$bКогда вернешься в приют, пожалуйста, дай королю знать, что со мной все в порядке. Он наверняка вознаградит тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите Лургглбра в безопасное место и вернитесь к королю Мргл-Мрглу в Приют Зимних Плавников, чтобы сообщить ему хорошую новость.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Превосходное известие! Так значит, Лургглбр обнаружил, что безумие вызывают испарения этих пещер?$B$BДолжно быть, магия Хладарры становится все сильнее… Война Нексуса… битва между синими и всеми прочими драконами все разгорается.$B$BСкоро нас всех в это втянут!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, $N? Чем могу служить?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Проводите Лургглбра в безопасное место',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Королю Мргл-Мрглу в Приют Зимних Плавников, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11571,'Обучение коммуникации','Чтобы помочь, тебе нужно научиться говорить на диалекте Зимних Плавников. В этом нам помогут силы природы и магии.$B$BВозьми эту пустую ракушку. На дне заполненного водой рва внизу обитает Скольдер – элементаль ярости воздуха и воды.$B$BКогда сразишь ее, воспользуйся ракушкой для того, чтобы уловить волшебный пар над ее останками. Принеси наполненную ракушку мне, и тогда я смогу передать тебе знание языка Зимних Плавников.$B$BТебе повезло – один друг научил меня заклинанию подводного дыхания, которое очень тебе пригодится.','Наполните ракушку, которую дал вам король Мргл-Мргл, над останками Скольдер. Верните наполненную ракушку короля Мрглу-Мрглу в Приют Зимних Плавников.','Вернитесь к Королю Мргл-Мрглу в Приют Зимних Плавников, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обучение коммуникации',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чтобы помочь, тебе нужно научиться говорить на диалекте Зимних Плавников. В этом нам помогут силы природы и магии.$B$BВозьми эту пустую ракушку. На дне заполненного водой рва внизу обитает Скольдер – элементаль ярости воздуха и воды.$B$BКогда сразишь ее, воспользуйся ракушкой для того, чтобы уловить волшебный пар над ее останками. Принеси наполненную ракушку мне, и тогда я смогу передать тебе знание языка Зимних Плавников.$B$BТебе повезло – один друг научил меня заклинанию подводного дыхания, которое очень тебе пригодится.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Наполните ракушку, которую дал вам король Мргл-Мргл, над останками Скольдер. Верните наполненную ракушку короля Мрглу-Мрглу в Приют Зимних Плавников.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Королю Мргл-Мрглу в Приют Зимних Плавников, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11572,'Возвращение к Атуику','Доставьте тревожные известия старейшине Атуику в Камагуа.','Дело сделано? Духи упокоились с миром?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к Атуику',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте тревожные известия старейшине Атуику в Камагуа.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Дело сделано? Духи упокоились с миром?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11573,'Орфус Камагуанский','Приветствую тебя, $gпутешественник:путешественница;. Я – Тупобивень из племени Калу\'ак. Твой народ зовет нашу расу "клыкарр". Недавно меня с помощником послали разведать причину странных явлений на одной из наших охотничьих троп. Но стоило нам приблизиться к западному кладбищу, известному как Заградительный холм, как на нас напали отряды нежити. Мне повезло – я смог добраться до этого лагеря, но судьба несчастного Орфуса мне не известна.$B$BНе $gмог:могла; бы ты отыскать его? Мы расстались возле Древнего подъемника, что к юго-востоку отсюда. Иди вдоль обрыва и убедись, что с ним все в порядке.','Найдите Орфуса Камагуанского на Древнем подъемнике в Ревущем фьорде.','Тупобивень жив? Ну, хоть одна хорошая новость за весь день...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орфус Камагуанский',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, $gпутешественник:путешественница;. Я – Тупобивень из племени Калу\'ак. Твой народ зовет нашу расу "клыкарр". Недавно меня с помощником послали разведать причину странных явлений на одной из наших охотничьих троп. Но стоило нам приблизиться к западному кладбищу, известному как Заградительный холм, как на нас напали отряды нежити. Мне повезло – я смог добраться до этого лагеря, но судьба несчастного Орфуса мне не известна.$B$BНе $gмог:могла; бы ты отыскать его? Мы расстались возле Древнего подъемника, что к юго-востоку отсюда. Иди вдоль обрыва и убедись, что с ним все в порядке.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Орфуса Камагуанского на Древнем подъемнике в Ревущем фьорде.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тупобивень жив? Ну, хоть одна хорошая новость за весь день...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`) VALUES (11574,'Переживания на грани','Я рассказала им все, что помню. Почему они мне не верят?$B$BЯ собирала травы у расселины. Они появились ниоткуда – темные волшебники с магическими зверями – и окружили меня!$B$BНадо мной возник волшебный ящик, он открылся и втянул меня внутрь. И когда он уже начал закрываться, тут-то и налетели мои спасители верхом на красных драконах. У меня аж дух захватило!$B$BЯ так и не поблагодарила их за спасение. Пожалуйста, |3-6($c), найди их и передай мою искреннюю признательность.','Ты завершил ритуал возвращения предков?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переживания на грани',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рассказала им все, что помню. Почему они мне не верят?$B$BЯ собирала травы у расселины. Они появились ниоткуда – темные волшебники с магическими зверями – и окружили меня!$B$BНадо мной возник волшебный ящик, он открылся и втянул меня внутрь. И когда он уже начал закрываться, тут-то и налетели мои спасители верхом на красных драконах. У меня аж дух захватило!$B$BЯ так и не поблагодарила их за спасение. Пожалуйста, |3-6($c), найди их и передай мою искреннюю признательность.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты завершил ритуал возвращения предков?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (11575,'Своевременное спасение','Я рассказала им все, что помню. Почему они мне не верят?$B$BЯ собирала травы у расселины. Они появились ниоткуда – темные волшебники с магическими зверями – и окружили меня!$B$BНадо мной возник волшебный ящик, он открылся и втянул меня внутрь. И когда он уже начал закрываться, тут-то и налетели мои спасители верхом на красных драконах. У меня аж дух захватило!$B$BЯ так и не поблагодарила их за спасение. Пожалуйста, |3-6($c), найди их и передай мою искреннюю признательность.','Можешь сказать своей подруге, что ее спасение было нашей обязанностью, и мы исполнили ее с радостью.$B$BЕе случай был лишь маленьким фрагментом большой головоломки.$B$BДаларан не жалеет усилий для раскрытия этой тайны, и, честно говоря, нам не помешала бы кое-какая помощь...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Своевременное спасение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я рассказала им все, что помню. Почему они мне не верят?$B$BЯ собирала травы у расселины. Они появились ниоткуда – темные волшебники с магическими зверями – и окружили меня!$B$BНадо мной возник волшебный ящик, он открылся и втянул меня внутрь. И когда он уже начал закрываться, тут-то и налетели мои спасители верхом на красных драконах. У меня аж дух захватило!$B$BЯ так и не поблагодарила их за спасение. Пожалуйста, |3-6($c), найди их и передай мою искреннюю признательность.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Можешь сказать своей подруге, что ее спасение было нашей обязанностью, и мы исполнили ее с радостью.$B$BЕе случай был лишь маленьким фрагментом большой головоломки.$B$BДаларан не жалеет усилий для раскрытия этой тайны, и, честно говоря, нам не помешала бы кое-какая помощь...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11576,'Наблюдения за расселиной: обнаружена аномалия','Приветствую тебя, |3-6($r). Я Гаррен, из Даларана.$B$BНе так давно Расселина была еще весьма мирным местом, по крайней мере, в геотермальном отношении.$B$BОднако недавно начались все учащающиеся землетрясения, появились разломы в земле, сквозь которые проглядывают необыкновенные поля хаотической энергии.$B$BМоя задача здесь – составить список аномалий и наблюдать за ними. Мои инструменты показывают, что еще одна аномалия появилась на утесе к юго-западу отсюда.$B$BВозьми с собой этот прибор и воспользуйся им, когда найдешь новый раскол.','По просьбе Гаррена с Янтарной гряды воспользуйтесь тайнометром у аномалии утеса Западной расселины.','Тебе удалось наполнить ракушку паром Скольдер?','Вернитесь к библиотекарю Гаррену на Янтарную гряду, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наблюдения за расселиной: обнаружена аномалия',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($r). Я Гаррен, из Даларана.$B$BНе так давно Расселина была еще весьма мирным местом, по крайней мере, в геотермальном отношении.$B$BОднако недавно начались все учащающиеся землетрясения, появились разломы в земле, сквозь которые проглядывают необыкновенные поля хаотической энергии.$B$BМоя задача здесь – составить список аномалий и наблюдать за ними. Мои инструменты показывают, что еще одна аномалия появилась на утесе к юго-западу отсюда.$B$BВозьми с собой этот прибор и воспользуйся им, когда найдешь новый раскол.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Гаррена с Янтарной гряды воспользуйтесь тайнометром у аномалии утеса Западной расселины.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось наполнить ракушку паром Скольдер?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к библиотекарю Гаррену на Янтарную гряду, что в Борейской тундре.',`completedtext_loc8`);
