INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11580,'Осквернение огня','Оскверните большой костер Орды в Серебряном бору!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернение огня',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Оскверните большой костер Орды в Серебряном бору!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11581,'Осквернение огня','Оскверните большой костер Альянса в Западном Крае!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернение огня',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Оскверните большой костер Альянса в Западном Крае!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11582,'Наблюдения за расселиной: Расколотая бездна','Чувствуешь? Это был уже последний толчок... а что тут творилось несколько минут назад!$B$BБоюсь, мне снова придется попросить тебя о помощи. Мои инструменты указывают, что неподалеку, к западу отсюда, глубоко под водой образовалась огромная расщелина.$B$BКак и раньше, мне нужно, чтобы ты $gвзял тайнометр и зафиксировал:взяла тайнометр и зафиксировала; данные этой аномалии.$B$BЯ применю заклинание, которое позволит тебе дышать под водой. Если срок действия заклинания истечет раньше, чем ты найдешь аномалию, возвращайся ко мне – я его обновлю.','По поручению Гаррена с Янтарной гряды воспользуйтесь тайнометром у Расколотой бездны и возвращайтесь к нему с полученными данными.','Ты смеешь приблизиться ко мне, смертное существо?\n\nРади твоих еще нерожденных детей – молись, чтобы твое дело стоило моего беспокойства.','Вернитесь к библиотекарю Гаррену на Янтарную гряду, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наблюдения за расселиной: Расколотая бездна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чувствуешь? Это был уже последний толчок... а что тут творилось несколько минут назад!$B$BБоюсь, мне снова придется попросить тебя о помощи. Мои инструменты указывают, что неподалеку, к западу отсюда, глубоко под водой образовалась огромная расщелина.$B$BКак и раньше, мне нужно, чтобы ты $gвзял тайнометр и зафиксировал:взяла тайнометр и зафиксировала; данные этой аномалии.$B$BЯ применю заклинание, которое позволит тебе дышать под водой. Если срок действия заклинания истечет раньше, чем ты найдешь аномалию, возвращайся ко мне – я его обновлю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Гаррена с Янтарной гряды воспользуйтесь тайнометром у Расколотой бездны и возвращайтесь к нему с полученными данными.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты смеешь приблизиться ко мне, смертное существо?\n\nРади твоих еще нерожденных детей – молись, чтобы твое дело стоило моего беспокойства.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к библиотекарю Гаррену на Янтарную гряду, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11583,'Поклонение огню','Поклонитесь огню Западного Края.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поклонение огню',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Поклонитесь огню Западного Края.',`offerrewardtext_loc8`);
