INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11585,'Бдение Адского Крика','Тром-ка, |3-6($r)! Добро пожаловать в крепость Песни Войны. Мое сердце поет от радости, что столь $gпрославленный герой Орды откликнулся:прославленная героиня Орды откликнулась; на призыв, вняв чувству долга!$B$BЭта неприступная крепость – свидетельство невероятной стойкости Орды. Через многие препятствия пришлось нам пройти, чтобы создать этот плацдарм на Нордсколе. Именно отсюда начнется наш поход к леднику Ледяной Короны, и сын Адского Крика приведет нас к успеху!$B$BГаррош ждет твоего прибытия там, внизу.$B$BЛок\'тар огар!','Поговорите с Гаррошем Адским Криком в крепости Песни Войны.','Герой Орды, ты?$B$B<Гаррош обнюхивает воздух вокруг вас.>$B$BСтрахом пахнет…$B$B<Гаррош презрительно сплевывает.>$B$BТы долго не продержишься.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бдение Адского Крика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тром-ка, |3-6($r)! Добро пожаловать в крепость Песни Войны. Мое сердце поет от радости, что столь $gпрославленный герой Орды откликнулся:прославленная героиня Орды откликнулась; на призыв, вняв чувству долга!$B$BЭта неприступная крепость – свидетельство невероятной стойкости Орды. Через многие препятствия пришлось нам пройти, чтобы создать этот плацдарм на Нордсколе. Именно отсюда начнется наш поход к леднику Ледяной Короны, и сын Адского Крика приведет нас к успеху!$B$BГаррош ждет твоего прибытия там, внизу.$B$BЛок\'тар огар!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гаррошем Адским Криком в крепости Песни Войны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Герой Орды, ты?$B$B<Гаррош обнюхивает воздух вокруг вас.>$B$BСтрахом пахнет…$B$B<Гаррош презрительно сплевывает.>$B$BТы долго не продержишься.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11586,'Бдение Адского Крика','Тром-ка, |3-6($r)! Добро пожаловать в крепость Песни Войны. Мое сердце поет от радости, что столь $gпрославленный герой Орды откликнулся:прославленная героиня Орды откликнулась; на призыв, вняв чувству долга!$B$BЭта неприступная крепость – свидетельство невероятной стойкости Орды. Через многие препятствия пришлось нам пройти, чтобы создать этот плацдарм на Нордсколе. Именно отсюда начнется наш поход к леднику Ледяной Короны, и сын Адского Крика приведет нас к успеху!$B$BГаррош ждет твоего прибытия там, внизу.$B$BЛок\'тар огар!','Поговорите с Гаррошем Адским Криком в крепости Песни Войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бдение Адского Крика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Тром-ка, |3-6($r)! Добро пожаловать в крепость Песни Войны. Мое сердце поет от радости, что столь $gпрославленный герой Орды откликнулся:прославленная героиня Орды откликнулась; на призыв, вняв чувству долга!$B$BЭта неприступная крепость – свидетельство невероятной стойкости Орды. Через многие препятствия пришлось нам пройти, чтобы создать этот плацдарм на Нордсколе. Именно отсюда начнется наш поход к леднику Ледяной Короны, и сын Адского Крика приведет нас к успеху!$B$BГаррош ждет твоего прибытия там, внизу.$B$BЛок\'тар огар!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Гаррошем Адским Криком в крепости Песни Войны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11587,'Побег из тюрьмы','Приветствую тебя, |3-6($c). Я – Донатан, верный слуга Даларана.$b$bИзвини, я сразу к делу. У нас крупные проблемы. По всему Азероту начали исчезать маги, и мне поручено привлекать любого, кто способен помочь разгадать эту тайну.$b$bНаше расследование начнется в лагере к югу отсюда. Я призываю тебя помочь освободить одного из пленных магов, которого там держат. Для этого надо добыть ключ от магической клетки у одного из охотников на магов...','По просьбе библиотекаря Донатана с Янтарной гряды добудьте берилловый магический ключ у охотника на магов в Берилловом лагере и используйте его, чтобы освободить пленного мага из магической клетки.','Ну, что, |3-6($C)?\n\nУдалось ли тебе обнаружить аномалию?','Вернитесь к библиотекарю Донатану на Янтарную гряду, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Побег из тюрьмы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Приветствую тебя, |3-6($c). Я – Донатан, верный слуга Даларана.$b$bИзвини, я сразу к делу. У нас крупные проблемы. По всему Азероту начали исчезать маги, и мне поручено привлекать любого, кто способен помочь разгадать эту тайну.$b$bНаше расследование начнется в лагере к югу отсюда. Я призываю тебя помочь освободить одного из пленных магов, которого там держат. Для этого надо добыть ключ от магической клетки у одного из охотников на магов...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе библиотекаря Донатана с Янтарной гряды добудьте берилловый магический ключ у охотника на магов в Берилловом лагере и используйте его, чтобы освободить пленного мага из магической клетки.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что, |3-6($C)?\n\nУдалось ли тебе обнаружить аномалию?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к библиотекарю Донатану на Янтарную гряду, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11588,'REUSE','Не дай Ахуну попасть в Азерот и развязать войну стихий!','Уничтожьте элементаля Ахуна в Непроглядной Пучине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REUSE',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не дай Ахуну попасть в Азерот и развязать войну стихий!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте элементаля Ахуна в Непроглядной Пучине.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11589,'REUSE','Не дай Ахуну попасть в Азерот и развязать войну стихий!','Уничтожьте элементаля Ахуна в Непроглядной Пучине.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','REUSE',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не дай Ахуну попасть в Азерот и развязать войну стихий!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте элементаля Ахуна в Непроглядной Пучине.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11590,'Похищение','$n, у нас тут возникла проблема.$B$BЯ только что узнал, что один из наших верховных магов по пути из Даларана пропал. Точнее, пропала. Естественно, мы полагаем, что за этим исчезновением стоят охотники на магов.$B$BВремя не ждет. Мы должны сейчас же разузнать, что случилось с леди Эванор, если хотим, чтобы у нас осталась надежда на ее спасение.$B$BВозьми этот прибор. Возвращайся в Берилловый лагерь и воздействуй этим прибором на одного из берилловых колдунов, когда он будет при смерти. Это должно связать его на достаточно долгий срок, чтобы привести его сюда для допроса.','Заключите в магические оковы раненого бериллового колдуна в Берилловом лагере и возвращайтесь вместе с ним к Донатану.','Вернитесь к библиотекарю Донатану на Янтарную гряду, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Похищение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, у нас тут возникла проблема.$B$BЯ только что узнал, что один из наших верховных магов по пути из Даларана пропал. Точнее, пропала. Естественно, мы полагаем, что за этим исчезновением стоят охотники на магов.$B$BВремя не ждет. Мы должны сейчас же разузнать, что случилось с леди Эванор, если хотим, чтобы у нас осталась надежда на ее спасение.$B$BВозьми этот прибор. Возвращайся в Берилловый лагерь и воздействуй этим прибором на одного из берилловых колдунов, когда он будет при смерти. Это должно связать его на достаточно долгий срок, чтобы привести его сюда для допроса.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Заключите в магические оковы раненого бериллового колдуна в Берилловом лагере и возвращайтесь вместе с ним к Донатану.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к библиотекарю Донатану на Янтарную гряду, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`) VALUES (11591,'Явиться в караван Стальной Челюсти','Поговорите с рубакой Десницей Гнева в караване Стальной Челюсти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Явиться в караван Стальной Челюсти',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с рубакой Десницей Гнева в караване Стальной Челюсти.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11592,'Мы ударим!','Один из ваших – орк по имени Стальная Челюсть – пытался сэкономить себе немного времени и срезать дорогу, пройдя по нашему кладбищу. Хорошо бы это был единичный случай, нетипичный для Орды, |3-6($r), а не то таунка покончат с вами!$B$BНо, как мне кажется, ты хочешь помочь исправить положение. Отлично!$B$BПроклятый дух Стальной Челюсти блуждает теперь там и беспокоит останки моих предков. Мы должны положить этому конец!$B$BЕсли мы с этим справимся, отправишься с рассказом к властителю Бор\'гороку на заставу к северу отсюда.$B$BНу что, $gсогласен:согласна;?','Ну что, |3-6($C), дело сделано? Клаксимус мертв?','Помощь выносливому гонцу Гордому Копыту успешно оказана','Вернитесь к властителю Бор\'горку на Заставу Бор\'горока, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мы ударим!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Один из ваших – орк по имени Стальная Челюсть – пытался сэкономить себе немного времени и срезать дорогу, пройдя по нашему кладбищу. Хорошо бы это был единичный случай, нетипичный для Орды, |3-6($r), а не то таунка покончат с вами!$B$BНо, как мне кажется, ты хочешь помочь исправить положение. Отлично!$B$BПроклятый дух Стальной Челюсти блуждает теперь там и беспокоит останки моих предков. Мы должны положить этому конец!$B$BЕсли мы с этим справимся, отправишься с рассказом к властителю Бор\'гороку на заставу к северу отсюда.$B$BНу что, $gсогласен:согласна;?',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, |3-6($C), дело сделано? Клаксимус мертв?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Помощь выносливому гонцу Гордому Копыту успешно оказана',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Бор\'горку на Заставу Бор\'горока, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11593,'Последние почести','Наши павшие заслуживают настоящего геройского погребения, но мы не можем похоронить их на священном кладбище таунка.$B$BЯ не буду просить тебя притащить сюда их тела, но – вот, возьми этот факел и отправляйся вглубь кладбища. Когда наткнешься на останки охранников и погонщиков, сожги их с помощью факела.$B$BПочти павших, |3-6($c)!','По просьбе рубаки Десницы Гнева близ каравана Стальной Челюсти используйте факел Десницы Гнева для сожжения мертвых стражей каравана и рабочих каравана (10 тел в любой комбинации).','Спасибо, |3-6($C). Мы – Орда, мы не оставляем наших мертвых лежать там, где их застигла смерть!\n\nНу, для начала, всего этого вообще не должно было понадобиться... Стальная Челюсть был глупцом!','Я просто смотрел на трупы наших павших,которые все ещё там.$B$BИсполни свой долг перед Ордой, $C!','Вернитесь к рубаке Десницы Гнева к Каравану Стальной Челюсти, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последние почести',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наши павшие заслуживают настоящего геройского погребения, но мы не можем похоронить их на священном кладбище таунка.$B$BЯ не буду просить тебя притащить сюда их тела, но – вот, возьми этот факел и отправляйся вглубь кладбища. Когда наткнешься на останки охранников и погонщиков, сожги их с помощью факела.$B$BПочти павших, |3-6($c)!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе рубаки Десницы Гнева близ каравана Стальной Челюсти используйте факел Десницы Гнева для сожжения мертвых стражей каравана и рабочих каравана (10 тел в любой комбинации).',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо, |3-6($C). Мы – Орда, мы не оставляем наших мертвых лежать там, где их застигла смерть!\n\nНу, для начала, всего этого вообще не должно было понадобиться... Стальная Челюсть был глупцом!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я просто смотрел на трупы наших павших,которые все ещё там.$B$BИсполни свой долг перед Ордой, $C!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рубаке Десницы Гнева к Каравану Стальной Челюсти, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11594,'Пусть обретут покой!','Это все из-за тупости командира соединения Стальной Челюсти! Хватило же ума потащить караван через погребальный курган таунка!$b$bНу что ж, сделанного не вернешь! Остается только разгребать последствия.$b$bВластитель Бор\'горок велел мне помогать выносливому гонцу Гордое Копыто, чем только можно. Гонец попросил меня помочь упокоить духов его предков.$b$bЧто скажешь, |3-6($c)? Хватит ли тебе сил на такое несложное задание?','Упокойте 20 духов таунка, фантомных ведунов либо восставших выносливых гонцов, и сообщите об этом рубаке Деснице Гнева, который ожидает в Караване Стальной Челюсти.','Молодец, |3-6($C)! Тебе, должно быть, не впервой сражаться с нежитью. Ну, а если для тебя это был первый раз, то теперь у тебя имеется ценный опыт!\n\nЭтот опыт пригодится тебе, если ты хочешь выжить в Нордсколе.','Если ты так хорошо потрудился, отчего же тогда их тут до сих пор так много?','Вернитесь к рубаке Деснице Гнева к Каравану Стальной Челюсти, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пусть обретут покой!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это все из-за тупости командира соединения Стальной Челюсти! Хватило же ума потащить караван через погребальный курган таунка!$b$bНу что ж, сделанного не вернешь! Остается только разгребать последствия.$b$bВластитель Бор\'горок велел мне помогать выносливому гонцу Гордое Копыто, чем только можно. Гонец попросил меня помочь упокоить духов его предков.$b$bЧто скажешь, |3-6($c)? Хватит ли тебе сил на такое несложное задание?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Упокойте 20 духов таунка, фантомных ведунов либо восставших выносливых гонцов, и сообщите об этом рубаке Деснице Гнева, который ожидает в Караване Стальной Челюсти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Молодец, |3-6($C)! Тебе, должно быть, не впервой сражаться с нежитью. Ну, а если для тебя это был первый раз, то теперь у тебя имеется ценный опыт!\n\nЭтот опыт пригодится тебе, если ты хочешь выжить в Нордсколе.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если ты так хорошо потрудился, отчего же тогда их тут до сих пор так много?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к рубаке Деснице Гнева к Каравану Стальной Челюсти, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11595,'Оборона крепости Песни Войны','Адский Крик в ответе за всю Орду, $n. Это тяжкая ноша. Так что не отказывайся от выполнения своих обязанностей из-за его дурного нрава.$b$b<Саурфанг кивает.>$b$bА ты думаешь, я мог забыть имя героя Оргриммара? Не каждый день приходится видеть голову Нефариана на пике!$b$bПлеть начала осаду этой крепости. Наши солдаты держат оборону, но мы отчаянно нуждаемся в подкреплении. Отправляйся к Разгору. Он находится под стеной крепости Песни Войны.','Явитесь к властителю Разгору в хижине у южной стены крепости Песни Войны.','<Властитель Разгор отдает вам честь.>$B$BВаша слава опережает вас, $N.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона крепости Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Адский Крик в ответе за всю Орду, $n. Это тяжкая ноша. Так что не отказывайся от выполнения своих обязанностей из-за его дурного нрава.$b$b<Саурфанг кивает.>$b$bА ты думаешь, я мог забыть имя героя Оргриммара? Не каждый день приходится видеть голову Нефариана на пике!$b$bПлеть начала осаду этой крепости. Наши солдаты держат оборону, но мы отчаянно нуждаемся в подкреплении. Отправляйся к Разгору. Он находится под стеной крепости Песни Войны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к властителю Разгору в хижине у южной стены крепости Песни Войны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Властитель Разгор отдает вам честь.>$B$BВаша слава опережает вас, $N.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11596,'Оборона крепости Песни Войны','Не позволяй Адскому Крику уговорить тебя пренебречь своими обязанностями в качестве воина Орды, |3-6($r). Здесь, на этих стылых пустошах, он несет свое тяжкое бремя, ведь неизвестно, чем все закончится – победой над Плетью или истреблением всего живого в Азероте. Именно поэтому нам требуются твоя сила и твоя мудрость.$B$BПлеть начала штурм этой крепости. Наши воины держат оборону, но отчаянно нуждаются в подмоге. Доложи Разгору. Он находится сразу за стенами крепости Песни Войны.','Доложитесь властителю Разгору, находящемуся в хижине на южной стороне крепости Песни Войны.','Как раз вовремя... Нерубы, кажется, удвоились в числе буквально за неделю. Мы ни от чьей помощи не откажемся.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона крепости Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не позволяй Адскому Крику уговорить тебя пренебречь своими обязанностями в качестве воина Орды, |3-6($r). Здесь, на этих стылых пустошах, он несет свое тяжкое бремя, ведь неизвестно, чем все закончится – победой над Плетью или истреблением всего живого в Азероте. Именно поэтому нам требуются твоя сила и твоя мудрость.$B$BПлеть начала штурм этой крепости. Наши воины держат оборону, но отчаянно нуждаются в подмоге. Доложи Разгору. Он находится сразу за стенами крепости Песни Войны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доложитесь властителю Разгору, находящемуся в хижине на южной стороне крепости Песни Войны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Как раз вовремя... Нерубы, кажется, удвоились в числе буквально за неделю. Мы ни от чьей помощи не откажемся.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11597,'Оборона крепости Песни Войны','Похоже, мы с тобой всегда встречаемся в самую лихую годину, $gПовелитель:Повелительница; Скарабеев! Ведь в последний раз, когда мы виделись, ты тоже $gспасал:спасала; мир от какой-то смертельной опасности?$b$b<Саурфанг усмехается.>$b$bТвоя помощь очень пригодится Нордсколу, что бы там ни говорил юный вождь!$b$bБудь у нас еще хоть десяток таких воинов, как ты, мы бы сейчас спокойно сидели в Оргриммаре, у жаркого очага.$b$bОтправляйся к властителю Разгору, он у главного входа в крепость Песни Войны, на юге.','Явитесь к властителю Разгору в хижине у южной стены крепости Песни Войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оборона крепости Песни Войны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Похоже, мы с тобой всегда встречаемся в самую лихую годину, $gПовелитель:Повелительница; Скарабеев! Ведь в последний раз, когда мы виделись, ты тоже $gспасал:спасала; мир от какой-то смертельной опасности?$b$b<Саурфанг усмехается.>$b$bТвоя помощь очень пригодится Нордсколу, что бы там ни говорил юный вождь!$b$bБудь у нас еще хоть десяток таких воинов, как ты, мы бы сейчас спокойно сидели в Оргриммаре, у жаркого очага.$b$bОтправляйся к властителю Разгору, он у главного входа в крепость Песни Войны, на юге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к властителю Разгору в хижине у южной стены крепости Песни Войны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11598,'Отвоевывание карьера Камня Силы','В то время как крепость Песни Войны защищает со всех сторон по три метра стали и камня, этот карьер – незащищен и является первой целью для атак нерубов.$B$B<Разгор указывает на запад.>$B$BЗа этим карьером стоят тысячи воинов Плети, только и ждущие приказа к атаке. Если нерубы уничтожат наши внутренние линии обороны, нас тут же сметут легионы нежити Артеса.$B$BМы не можем этого допустить – поэтому ты $gдолжен напасть первым:должна напасть первой; и перебить нерубов в карьере.$B$BКровь и гром, солдат! Пусть и то, и другое сопровождают тебя в бою.','По заданию властителя Разгора из крепости Песни Войны убейте 15 неруб\'арцев.','Ну, что там?..','Вернитесь к властителю Разгору в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отвоевывание карьера Камня Силы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В то время как крепость Песни Войны защищает со всех сторон по три метра стали и камня, этот карьер – незащищен и является первой целью для атак нерубов.$B$B<Разгор указывает на запад.>$B$BЗа этим карьером стоят тысячи воинов Плети, только и ждущие приказа к атаке. Если нерубы уничтожат наши внутренние линии обороны, нас тут же сметут легионы нежити Артеса.$B$BМы не можем этого допустить – поэтому ты $gдолжен напасть первым:должна напасть первой; и перебить нерубов в карьере.$B$BКровь и гром, солдат! Пусть и то, и другое сопровождают тебя в бою.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию властителя Разгора из крепости Песни Войны убейте 15 неруб\'арцев.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что там?..',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Разгору в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11599,'Тассариан, мой брат','Найти Вильяма Аллертона в шахте Далечья.','Труп подходит под описание Вильяма Аллертона, которое дала вам Лерисса. Как ни странно, на нем не заметно следов ни от когтей, ни от зубов…') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тассариан, мой брат',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найти Вильяма Аллертона в шахте Далечья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Труп подходит под описание Вильяма Аллертона, которое дала вам Лерисса. Как ни странно, на нем не заметно следов ни от когтей, ни от зубов…',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11600,'Последние новости о Вильяме Аллертоне','Горло Вильяма перерезано чем-то острым.$B$BПри дальнейшем осмотре тела нашлась лишь единственная зацепка для Лериссы – воинское удостоверение на имя Вильяма Аллертона.','Ты думаешь, Вильям стал случайной жертвой Плети? Все это выглядит весьма подозрительно.$B$BЧто-то происходит. Нам нужно найти Тассариана.','Вернитесь к Лериссе в Крепость Отваги, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Последние новости о Вильяме Аллертоне',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Горло Вильяма перерезано чем-то острым.$B$BПри дальнейшем осмотре тела нашлась лишь единственная зацепка для Лериссы – воинское удостоверение на имя Вильяма Аллертона.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты думаешь, Вильям стал случайной жертвой Плети? Все это выглядит весьма подозрительно.$B$BЧто-то происходит. Нам нужно найти Тассариана.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Лериссе в Крепость Отваги, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (11601,'Потерянный и обретенный','Возможно, бедный мистер Аллертон все-таки поможет нам отыскать моего пропавшего брата!$b$b<Лерисса достает объемистую книгу, смахивающую на ту, куда записывают рекрутов.>$b$bНу да, я ее позаимствовала, и что такого? Посмотрим, какого числа он поступил на службу?$b$bВильям видел Тассариана в списке рекрутов. Значит, они поступили почти одновременно... вот он!$b$bОн записался в... отряд С? Все прочие воинские подразделения носят названия городов Альянса...$b$bА кто еще состоит в этом отряде? Где они сражаются? Нужно разузнать. Может, хозяину таверны что-нибудь известно?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Потерянный и обретенный',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возможно, бедный мистер Аллертон все-таки поможет нам отыскать моего пропавшего брата!$b$b<Лерисса достает объемистую книгу, смахивающую на ту, куда записывают рекрутов.>$b$bНу да, я ее позаимствовала, и что такого? Посмотрим, какого числа он поступил на службу?$b$bВильям видел Тассариана в списке рекрутов. Значит, они поступили почти одновременно... вот он!$b$bОн записался в... отряд С? Все прочие воинские подразделения носят названия городов Альянса...$b$bА кто еще состоит в этом отряде? Где они сражаются? Нужно разузнать. Может, хозяину таверны что-нибудь известно?',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11602,'Прервать на корню','Воздушная рекогносцировка карьера показала, что нерубы откладывают свои яйца на возвышениях, окружающих основание. Хитрые твари... Яйца лежат высоко и в сухом месте, подальше от центра конфликта.$B$BТебе придется вернуться туда и отследить, где лежат яйца. Найди их, разбей и уничтожь.$B$BКаждое уничтоженное яйцо – это на двадцать меньше воинов Неруба, жирующих на наших трупах.','По поручению властителя Разгора, находящегося в крепости Песни Войны, уничтожьте 10 неруб\'арских яиц.','Он мертв?','Вернитесь к властителю Разгору в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Прервать на корню',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Воздушная рекогносцировка карьера показала, что нерубы откладывают свои яйца на возвышениях, окружающих основание. Хитрые твари... Яйца лежат высоко и в сухом месте, подальше от центра конфликта.$B$BТебе придется вернуться туда и отследить, где лежат яйца. Найди их, разбей и уничтожь.$B$BКаждое уничтоженное яйцо – это на двадцать меньше воинов Неруба, жирующих на наших трупах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению властителя Разгора, находящегося в крепости Песни Войны, уничтожьте 10 неруб\'арских яиц.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он мертв?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к властителю Разгору в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11603,'Истина в вине','Военная служба – это все, что было у старика Колберна. Когда он вышел в отставку, то продолжал живо интересоваться всем, что связано с армией, словно это было для него жизненно важно. Он знал имя каждого генерала, отряда, бригады, подразделения... буквально все. Он – человек, который тебе нужен.$B$BПроблема в том, что у него неладно с головой. Он ни с кем не станет разговаривать, пока не глотнет своего кул-тирасского вина. Тогда он тут же вспоминает о временах, когда был моряком.$B$BЯ уже давненько не получал от поставщиков этого вина. Последний торговый корабль из Кул-Тираса затонул к северо-востоку отсюда. Посмотри – может, тебе удастся раздобыть бутылку, чтобы принести ее Колберну?','М-мм... не слишком горькое... и не слишком сухое... Такое же, как мы пивали с ребятами в казармах в былые времена.','<Старик смотрит на вас с отсутствующим выражением лица.>','Вернитесь к старику Колберну в Крепость Отваги, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Истина в вине',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Военная служба – это все, что было у старика Колберна. Когда он вышел в отставку, то продолжал живо интересоваться всем, что связано с армией, словно это было для него жизненно важно. Он знал имя каждого генерала, отряда, бригады, подразделения... буквально все. Он – человек, который тебе нужен.$B$BПроблема в том, что у него неладно с головой. Он ни с кем не станет разговаривать, пока не глотнет своего кул-тирасского вина. Тогда он тут же вспоминает о временах, когда был моряком.$B$BЯ уже давненько не получал от поставщиков этого вина. Последний торговый корабль из Кул-Тираса затонул к северо-востоку отсюда. Посмотри – может, тебе удастся раздобыть бутылку, чтобы принести ее Колберну?',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','М-мм... не слишком горькое... и не слишком сухое... Такое же, как мы пивали с ребятами в казармах в былые времена.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Старик смотрит на вас с отсутствующим выражением лица.>',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старику Колберну в Крепость Отваги, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (11604,'Дезертир','Отряд С, отряд С... хм... ерунда какая-то... Отряды называются по городам.$b$bТемнолесцев отправили в Драконий Погост. Ребят из Златоземья послали во Фьорд. А где же я...$b$bАх, да! Дезертир! В тюрьме при казармах был перебежчик. Его засадили не так давно. Он все говорил, что "С" значит "самоубийство".$b$bОтыщи этого дезертира. Возможно, он знает что-то, что тебе пригодится!','Чего тебе надо? И без тебя тошно!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дезертир',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Отряд С, отряд С... хм... ерунда какая-то... Отряды называются по городам.$b$bТемнолесцев отправили в Драконий Погост. Ребят из Златоземья послали во Фьорд. А где же я...$b$bАх, да! Дезертир! В тюрьме при казармах был перебежчик. Его засадили не так давно. Он все говорил, что "С" значит "самоубийство".$b$bОтыщи этого дезертира. Возможно, он знает что-то, что тебе пригодится!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Чего тебе надо? И без тебя тошно!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11605,'Досточтимые предки','<Далекий голос эхом звучит в вашей голове, пока вы рассматриваете каменное изваяние.>$B$BНе удивляйся, $gчужеземец:чужестранка;. Я – старейшина Атканок, древний предок клыкаррского народа, прославленный в свое время мастер, уже сотни лет находящийся на страже этого карьера.$B$BКарьер был опустошен, многие статуи остались незавершенными, а духи предков стали скитальцами. Поможешь ли ты мне исправить неправильное?$B$BДля начала я должен узнать имена этих неприкаянных предков. Поищи обозначения возле статуй.','По просьбе старейшины Атканока, находящегося у карьера Ледяного Булыжника, отыщите статуи, предназначенные для старейшины Кесука, старейшины Сагани и старейшины Такрета.','<Вы снова слышите далекий голос.>\n\nУдалось ли тебе разузнать имена неприкаянных предков?','Вернитесь к старейшине Атканоку в Карьер Ледяного Булыжника, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Досточтимые предки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Далекий голос эхом звучит в вашей голове, пока вы рассматриваете каменное изваяние.>$B$BНе удивляйся, $gчужеземец:чужестранка;. Я – старейшина Атканок, древний предок клыкаррского народа, прославленный в свое время мастер, уже сотни лет находящийся на страже этого карьера.$B$BКарьер был опустошен, многие статуи остались незавершенными, а духи предков стали скитальцами. Поможешь ли ты мне исправить неправильное?$B$BДля начала я должен узнать имена этих неприкаянных предков. Поищи обозначения возле статуй.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе старейшины Атканока, находящегося у карьера Ледяного Булыжника, отыщите статуи, предназначенные для старейшины Кесука, старейшины Сагани и старейшины Такрета.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Вы снова слышите далекий голос.>\n\nУдалось ли тебе разузнать имена неприкаянных предков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Атканоку в Карьер Ледяного Булыжника, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11606,'Терпение – добродетель, в которой мы не нуждаемся','Мы можем перебить всех нерубов, каких только увидим, и передавить все их яйца, какие найдем, но эти твари не перестанут прибывать, пока мы не взорвем их туннели и проходы. Конечно, мы не сможем этого сделать, не имея в арсенале мощных боеприпасов. К сожалению, большая часть наших запасов используется гоблинами и кузнецами для изготовления осадных танков и оружия.$B$BНо к счастью, есть очень неплохой запас того, что нам нужно, в карьере Силы Камня – под всей этой нерубской чепухой. Тебе нужно просто пойти и принести мне запасы.','По поручению интенданта Холгота раздобудьте 15 ящиков с боеприпасами Песни Войны.','Вернитесь к интенданту Холготу в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Терпение – добродетель, в которой мы не нуждаемся',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы можем перебить всех нерубов, каких только увидим, и передавить все их яйца, какие найдем, но эти твари не перестанут прибывать, пока мы не взорвем их туннели и проходы. Конечно, мы не сможем этого сделать, не имея в арсенале мощных боеприпасов. К сожалению, большая часть наших запасов используется гоблинами и кузнецами для изготовления осадных танков и оружия.$B$BНо к счастью, есть очень неплохой запас того, что нам нужно, в карьере Силы Камня – под всей этой нерубской чепухой. Тебе нужно просто пойти и принести мне запасы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению интенданта Холгота раздобудьте 15 ящиков с боеприпасами Песни Войны.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Холготу в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11607,'Заблудшие духи','Во время нападения на карьер работавшие там шаманы и ремесленники были убиты. Насилие повергло мир духов в хаос, и мы не сможем отправить предков домой, если не найдем способа утихомирить духов убитых. $b$bСами враги не обращают внимания на духов, но их спутники, берилловые гончие, чуют духов и держат их в рабстве. $b$bУбей берилловых гончих и, используя высвободившуюся чистую энергию, отпусти невинные души на волю.','Освободите дух 3 ремесленников клана Каскала и 3 шаманов клана Каскала по просьбе старейшины Атканока в окрестностях карьера Ледяного Булыжника.','Ты уже покончил со смотрителем?','Вернитесь к старейшине Атканоку в Карьер Ледяного Булыжника, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заблудшие духи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Во время нападения на карьер работавшие там шаманы и ремесленники были убиты. Насилие повергло мир духов в хаос, и мы не сможем отправить предков домой, если не найдем способа утихомирить духов убитых. $b$bСами враги не обращают внимания на духов, но их спутники, берилловые гончие, чуют духов и держат их в рабстве. $b$bУбей берилловых гончих и, используя высвободившуюся чистую энергию, отпусти невинные души на волю.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободите дух 3 ремесленников клана Каскала и 3 шаманов клана Каскала по просьбе старейшины Атканока в окрестностях карьера Ледяного Булыжника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже покончил со смотрителем?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Атканоку в Карьер Ледяного Булыжника, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11608,'Засыпать тараканьи норы!','Север, юг, восток и запад. Вот направления, которыми тебе предстоит заняться. Вокруг крепости в карьере Камня Силы расположены 4 неруб\'арские воронки.$B$B<Холгот передает вам сверток.>$B$BОсторожнее с ними, $n. Стоит что-то сделать не так – и ты труп.$B$BВнутри этого свертка – глубинные сефориевые заряды. Сходи ко всем неруб\'арским воронкам и установи заряды в центре каждой из них. Если все пойдет как надо, туннели завалит.$B$BДавай, вперед!','По поручению интенданта Холгота используйте сверток с глубинными сефориевыми зарядами для уничтожения неруб\'арских воронок к югу, востоку, западу и северу от крепости Песни Войны.','Нужно уничтожить эти кладки!','Вернитесь к интенданту Холготу в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Засыпать тараканьи норы!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Север, юг, восток и запад. Вот направления, которыми тебе предстоит заняться. Вокруг крепости в карьере Камня Силы расположены 4 неруб\'арские воронки.$B$B<Холгот передает вам сверток.>$B$BОсторожнее с ними, $n. Стоит что-то сделать не так – и ты труп.$B$BВнутри этого свертка – глубинные сефориевые заряды. Сходи ко всем неруб\'арским воронкам и установи заряды в центре каждой из них. Если все пойдет как надо, туннели завалит.$B$BДавай, вперед!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению интенданта Холгота используйте сверток с глубинными сефориевыми зарядами для уничтожения неруб\'арских воронок к югу, востоку, западу и северу от крепости Песни Войны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нужно уничтожить эти кладки!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к интенданту Холготу в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11609,'Сбор ритуальных предметов','Теперь, когда духи убитых ремесленников и шаманов упокоились, мы можем завершить ритуал, прерванный нападением. Тебе придется выполнять роль, которая по традиции отводится шаману клыкарров – а для этого тебе нужно иметь все необходимые ритуальные предметы.$b$bИзготовлять новые нет времени, поэтому нужно раздобыть те, что остались от жертв нападения. Обращайся с этими вещами бережно, $n, ведь некоторым из них по несколько сотен лет! Возможно, тебе придется отвоевывать их у захватчиков...','Принесите 6 клыкаррских ритуальных предметов старейшине Атканоку, который стоит у карьера Ледяного Булыжника.','Все ли ритуальные предметы удалось тебе отыскать?','Вернитесь к старейшине Атканоку в Карьер Ледяного Булыжника, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сбор ритуальных предметов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда духи убитых ремесленников и шаманов упокоились, мы можем завершить ритуал, прерванный нападением. Тебе придется выполнять роль, которая по традиции отводится шаману клыкарров – а для этого тебе нужно иметь все необходимые ритуальные предметы.$b$bИзготовлять новые нет времени, поэтому нужно раздобыть те, что остались от жертв нападения. Обращайся с этими вещами бережно, $n, ведь некоторым из них по несколько сотен лет! Возможно, тебе придется отвоевывать их у захватчиков...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 6 клыкаррских ритуальных предметов старейшине Атканоку, который стоит у карьера Ледяного Булыжника.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Все ли ритуальные предметы удалось тебе отыскать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Атканоку в Карьер Ледяного Булыжника, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11610,'Возвращение предков','С твоей помощью духи предков смогут теперь направиться в достойные их обиталища – статуи, с любовью сделанные ремесленниками Каскалы и тамошним шаманом.$B$BРитуал возвращения предков был прерван во время нападения на карьер, и теперь тебе нужно будет завершить его. Возьми с собой предметы, добытые в карьере, встань перед наделенными именами статуями и продекламируй это.$B$B<Слова на странном, незнакомом языке наполняют ваше сознание, но вы запоминаете их без всякого труда.>','По просьбе старейшины Атканока проведите духов старейшины Кесука, старейшины Сагани и старейшины Такрета в их каменные изваяния.','Ты завершил ритуал возвращения предков?','Вернитесь к старейшине Атканоку в Карьер Ледяного Булыжника, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение предков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С твоей помощью духи предков смогут теперь направиться в достойные их обиталища – статуи, с любовью сделанные ремесленниками Каскалы и тамошним шаманом.$B$BРитуал возвращения предков был прерван во время нападения на карьер, и теперь тебе нужно будет завершить его. Возьми с собой предметы, добытые в карьере, встань перед наделенными именами статуями и продекламируй это.$B$B<Слова на странном, незнакомом языке наполняют ваше сознание, но вы запоминаете их без всякого труда.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе старейшины Атканока проведите духов старейшины Кесука, старейшины Сагани и старейшины Такрета в их каменные изваяния.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты завершил ритуал возвращения предков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Атканоку в Карьер Ледяного Булыжника, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11611,'Захваченные Плетью','<Мортий вздыхает.>$B$BБатраки... С таким же успехом можно поставить рекламный щит с предложением бесплатной еды для неруб\'аров.$B$BПонимаешь, с батраками есть проблемы: во-первых, они тупее комка глины, а во-вторых, они слабее лепрогнома. Конечно, Плеть должна была их первыми и захватить!$B$BВ этом для меня есть небольшое затруднение – должно быть, тебе понятно: если не будет батраков, кто будет заниматься тяжелым ручным трудом? Нет батраков – нет строительства.$B$BНайди и освободи моих батраков, |3-6($r). Если они живы, то ты найдешь их запеленатыми в паутину по всему карьеру Камня Силы.','Нет батраков – нет зданий. И – нет, мы не собираемся заменять их гоблинами. Это нам чертовски дорого обошлось бы…','Вернитесь к штейгеру Мортию в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Захваченные Плетью',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Мортий вздыхает.>$B$BБатраки... С таким же успехом можно поставить рекламный щит с предложением бесплатной еды для неруб\'аров.$B$BПонимаешь, с батраками есть проблемы: во-первых, они тупее комка глины, а во-вторых, они слабее лепрогнома. Конечно, Плеть должна была их первыми и захватить!$B$BВ этом для меня есть небольшое затруднение – должно быть, тебе понятно: если не будет батраков, кто будет заниматься тяжелым ручным трудом? Нет батраков – нет строительства.$B$BНайди и освободи моих батраков, |3-6($r). Если они живы, то ты найдешь их запеленатыми в паутину по всему карьеру Камня Силы.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нет батраков – нет зданий. И – нет, мы не собираемся заменять их гоблинами. Это нам чертовски дорого обошлось бы…',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к штейгеру Мортию в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11612,'Бой за карьер','Рад тебя видеть, |3-6($c). Меня зовут Этарук, и я был ремесленником здесь, в карьере Ледяного Булыжника.$B$BЯ и мои товарищи готовили новый комплект статуй для последней серии ритуалов, когда увидели, как эти таинственные синие платформы летят над плато.$B$BКогда они приземлились, карьер заполонили охотники на магов, прилетевшие на них, убивая моих товарищей и громя карьер. Если мы не остановим их, они уничтожат все наши статуи и сбегут с нашими артефактами. Поможешь ли ты мне одолеть захватчиков?','По просьбе Этарука, находящегося у входа в карьер Ледяного Булыжника, убейте 12 берилловых охотников за сокровищами.','Как там наши невинные души?','Вернитесь к Этаруку в Карьер Ледяного Булыжника, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бой за карьер',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Рад тебя видеть, |3-6($c). Меня зовут Этарук, и я был ремесленником здесь, в карьере Ледяного Булыжника.$B$BЯ и мои товарищи готовили новый комплект статуй для последней серии ритуалов, когда увидели, как эти таинственные синие платформы летят над плато.$B$BКогда они приземлились, карьер заполонили охотники на магов, прилетевшие на них, убивая моих товарищей и громя карьер. Если мы не остановим их, они уничтожат все наши статуи и сбегут с нашими артефактами. Поможешь ли ты мне одолеть захватчиков?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Этарука, находящегося у входа в карьер Ледяного Булыжника, убейте 12 берилловых охотников за сокровищами.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там наши невинные души?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Этаруку в Карьер Ледяного Булыжника, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11613,'Клятва Карука','Они называют себя квалдирами. В моем народе бытуют легенды о них; мы называем их тук-харик – "странники тумана".$B$BМоя деревня была разрушена этими гигантскими туманными существами. Были убиты все, кого я знал, погиб и мой отец Ариут.$B$BСогласно клыкаррским обычаям, я должен искать мести тем, кто пролил кровь моего рода.$B$BНо я всего лишь рыбак, к тому же я даже не прошел испытание совершеннолетия... Я не выстою лицом к лицу со злобными квалдирами.$B$BЕсли бы ты $gмог:могла; взыскать долг крови вместо меня, я был бы очень тебе обязан.','По просьбе Карука убейте 6 скадирских налетчиков и 5 скадирских лодочников.','Тебе сопутствовал успех, $N? Квалдиры - жестокие воины. От них пощады не жди.','Вернитесь к Каруку в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Клятва Карука',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они называют себя квалдирами. В моем народе бытуют легенды о них; мы называем их тук-харик – "странники тумана".$B$BМоя деревня была разрушена этими гигантскими туманными существами. Были убиты все, кого я знал, погиб и мой отец Ариут.$B$BСогласно клыкаррским обычаям, я должен искать мести тем, кто пролил кровь моего рода.$B$BНо я всего лишь рыбак, к тому же я даже не прошел испытание совершеннолетия... Я не выстою лицом к лицу со злобными квалдирами.$B$BЕсли бы ты $gмог:могла; взыскать долг крови вместо меня, я был бы очень тебе обязан.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Карука убейте 6 скадирских налетчиков и 5 скадирских лодочников.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе сопутствовал успех, $N? Квалдиры - жестокие воины. От них пощады не жди.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каруку в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11614,'Невысказанные истины','Отыщите тенелова Лютера в карьере Камня Силы.','Нужно уничтожить эти кладки!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невысказанные истины',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите тенелова Лютера в карьере Камня Силы.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нужно уничтожить эти кладки!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11615,'Неруб\'арские тайны','Вы листаете страницы книги в поисках чего-нибудь важного. На последней странице вы обнаруживаете нацарапанное диковинными каракулями:$B$BНекролорды. Как минимум дюжина, по моим подсчетам.$B$BФермы к западу используются как какие-то чудовищные инкубаторы Плети.$B$BЖертвы – ряд за рядом.$B$BДумаю, они теперь за мной идут. Бросился к крепости. Живым я не дамся.$B$BЖуткоядый гемотоксин. Если они решат меня погрызть, их ждет сюрприз.$B$BДоставьте эту информацию Бартусу.','Доставьте дневник Лютера тенелову Бартусу в Крепость Песни Войны.','Он мертв?','Вернитесь к тенелову Бартусу в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неруб\'арские тайны',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы листаете страницы книги в поисках чего-нибудь важного. На последней странице вы обнаруживаете нацарапанное диковинными каракулями:$B$BНекролорды. Как минимум дюжина, по моим подсчетам.$B$BФермы к западу используются как какие-то чудовищные инкубаторы Плети.$B$BЖертвы – ряд за рядом.$B$BДумаю, они теперь за мной идут. Бросился к крепости. Живым я не дамся.$B$BЖуткоядый гемотоксин. Если они решат меня погрызть, их ждет сюрприз.$B$BДоставьте эту информацию Бартусу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте дневник Лютера тенелову Бартусу в Крепость Песни Войны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Он мертв?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тенелову Бартусу в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11616,'Послание Адскому Крику','Отнесите записку Бартуса Гаррошу Адскому Крику в крепости Песни Войны.','Это еще что такое? Мне не до пустяков!','Поговорите с Гаррошем Адским Криком в Крепости Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Послание Адскому Крику',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите записку Бартуса Гаррошу Адскому Крику в крепости Песни Войны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Это еще что такое? Мне не до пустяков!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Гаррошем Адским Криком в Крепости Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11617,'Никто не должен уйти','Я уверен, что ты $gвидел:видела; эти синие и белые платформы, летающие над карьером. Эти транспортные средства охотники на магов использовали для переброски своих сил, а теперь они нагружают их нашими артефактами и фрагментами наших статуй!$B$BМы должны остановить их, пока они не покинули карьер.$B$BМаленькие создания, копающиеся в карьере, носят с собой взрывчатку. Возьми их и используй для того, чтобы уничтожить три плавающие в воздухе платформы. Их вожак наблюдает за происходящим с четвертой, приземлившейся платформы, но с ним мы разберемся потом.','По поручению Этарука из карьера Ледяного Булыжника уничтожьте Северную, Восточную и Западную платформы.','Охотники на магов поймут, что разорить наш карьер и разграбить наши артефакты не так просто, как они думали. С твоей помощью мы отвоюем карьер и все восстановим.','Как там наши невинные души?','Вернитесь к Этаруку в Карьер Ледяного Булыжника, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Никто не должен уйти',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уверен, что ты $gвидел:видела; эти синие и белые платформы, летающие над карьером. Эти транспортные средства охотники на магов использовали для переброски своих сил, а теперь они нагружают их нашими артефактами и фрагментами наших статуй!$B$BМы должны остановить их, пока они не покинули карьер.$B$BМаленькие создания, копающиеся в карьере, носят с собой взрывчатку. Возьми их и используй для того, чтобы уничтожить три плавающие в воздухе платформы. Их вожак наблюдает за происходящим с четвертой, приземлившейся платформы, но с ним мы разберемся потом.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Этарука из карьера Ледяного Булыжника уничтожьте Северную, Восточную и Западную платформы.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Охотники на магов поймут, что разорить наш карьер и разграбить наши артефакты не так просто, как они думали. С твоей помощью мы отвоюем карьер и все восстановим.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там наши невинные души?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Этаруку в Карьер Ледяного Булыжника, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11618,'Подкрепление на подходе...','<Адский Крик качает головой.>$b$bТы, возможно, не $gзаметил:заметила;, |3-6($r), но мы тут пытаемся выиграть войну. Все, кто способен сражаться, отправлены в ключевые точки. А это значит, что на такие мелкие вторжения бойцов у нас уже не осталось.$b$b<Адский Крик делает паузу, чтобы поразмыслить.>$b$bНо Бартус требует подкрепления на ферме...$b$b<Адский Крик хлопает себя по лбу.>$b$bИ он их получит! Ступай к убийцам Бартуса на фермах, к западу отсюда. И дай им знать, что подкрепление прибыло.','Отыщите тенелова Икориса на заставе у ферм Песни Войны к западу от крепости Песни Войны.','Ну? Что случилось?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подкрепление на подходе...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Адский Крик качает головой.>$b$bТы, возможно, не $gзаметил:заметила;, |3-6($r), но мы тут пытаемся выиграть войну. Все, кто способен сражаться, отправлены в ключевые точки. А это значит, что на такие мелкие вторжения бойцов у нас уже не осталось.$b$b<Адский Крик делает паузу, чтобы поразмыслить.>$b$bНо Бартус требует подкрепления на ферме...$b$b<Адский Крик хлопает себя по лбу.>$b$bИ он их получит! Ступай к убийцам Бартуса на фермах, к западу отсюда. И дай им знать, что подкрепление прибыло.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите тенелова Икориса на заставе у ферм Песни Войны к западу от крепости Песни Войны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну? Что случилось?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11619,'Геймел Жестокий','Моего отца убил предводитель этих разбойников, Геймел Жестокий. Он живет в пещере на берегу.$b$bС его людьми тебе покончить удалось. Доверши же начатое, $n! Отомсти за моего отца, и я поделюсь с тобой тем немногим, что у меня осталось.','Удалось ли тебе одолеть Геймела, $C?','Вернитесь к Каруку в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Геймел Жестокий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моего отца убил предводитель этих разбойников, Геймел Жестокий. Он живет в пещере на берегу.$b$bС его людьми тебе покончить удалось. Доверши же начатое, $n! Отомсти за моего отца, и я поделюсь с тобой тем немногим, что у меня осталось.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе одолеть Геймела, $C?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каруку в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11620,'Отцовские слова','Есть кое-кто, кто мог бы пролить свет на эту тайну, |3-6($r). Ходят слухи, что квалдиры держат живую жрицу-нагу в храме на западной стороне берега.$B$BОна-то, без сомнения, имеет все основания взъяриться на своих незваных квалдирских гостей. Возможно, моему отцу кажется, что она будет с тобой сотрудничать.','Поищите Вихью у святилища Чешуи на берегу Терзающего Бича.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Отцовские слова',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть кое-кто, кто мог бы пролить свет на эту тайну, |3-6($r). Ходят слухи, что квалдиры держат живую жрицу-нагу в храме на западной стороне берега.$B$BОна-то, без сомнения, имеет все основания взъяриться на своих незваных квалдирских гостей. Возможно, моему отцу кажется, что она будет с тобой сотрудничать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите Вихью у святилища Чешуи на берегу Терзающего Бича.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11621,'Табличка Левирота','Вы корпите над тем, что нацарапано на табличке, пытаясь найти хоть какой-то понятный текст. Наконец, вам удается прочесть следующий фрагмент:$B$B"Сыновья тумана востребуют тысячу душ для того, кто обитает во мраке глубин. И тогда пробудится его посланец."$B$BДолжно быть, это заинтересует Карука.','Возвращайтесь к Каруку с информацией, обнаруженной вами на табличке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Табличка Левирота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вы корпите над тем, что нацарапано на табличке, пытаясь найти хоть какой-то понятный текст. Наконец, вам удается прочесть следующий фрагмент:$B$B"Сыновья тумана востребуют тысячу душ для того, кто обитает во мраке глубин. И тогда пробудится его посланец."$B$BДолжно быть, это заинтересует Карука.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь к Каруку с информацией, обнаруженной вами на табличке.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (11622,'Тайны Терзающего Бича','Есть некто, кто способен пролить свет на эту тайну, |3-6($r). Ходят слухи, что квалдиры держали живыми в храме нескольких жриц-наг.$b$bИ верховная жрица, Вихья, явно имеет причины недолюбливать их за непрошеное гостеприимство. Быть может, она расскажет тебе, что означает надпись на табличке.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны Терзающего Бича',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Есть некто, кто способен пролить свет на эту тайну, |3-6($r). Ходят слухи, что квалдиры держали живыми в храме нескольких жриц-наг.$b$bИ верховная жрица, Вихья, явно имеет причины недолюбливать их за непрошеное гостеприимство. Быть может, она расскажет тебе, что означает надпись на табличке.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11623,'Визит к смотрителю','Силы охотников на магов возглавляет жуткое создание по имени смотритель Инзивиус. Бесчисленные поколения моего народа охотятся на морских тварей, но таких, как этот смотритель, мы никогда не видали. $B$BОн разместился на одном из летающих дисков на верхней кромке карьера и оттуда наблюдает за происходящим. $n, я могу только верить, что сами предки послали тебя мне в помощь, и надеюсь, ты поможешь мне выдворить охотников на магов из этого карьера раз и навсегда.','По заданию Этарука с края карьера Ледяного Булыжника убейте смотрителя Инзивиуса.','Ты завершил ритуал возвращения предков?','Вернитесь к Этаруку в Карьер Ледяного Булыжника, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Визит к смотрителю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Силы охотников на магов возглавляет жуткое создание по имени смотритель Инзивиус. Бесчисленные поколения моего народа охотятся на морских тварей, но таких, как этот смотритель, мы никогда не видали. $B$BОн разместился на одном из летающих дисков на верхней кромке карьера и оттуда наблюдает за происходящим. $n, я могу только верить, что сами предки послали тебя мне в помощь, и надеюсь, ты поможешь мне выдворить охотников на магов из этого карьера раз и навсегда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Этарука с края карьера Ледяного Булыжника убейте смотрителя Инзивиуса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты завершил ритуал возвращения предков?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Этаруку в Карьер Ледяного Булыжника, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11624,'Небо знает','Мне нужно выяснить, что случилось с моим наставником, предсказателем Печальным Путником!$b$bЕще недавно он наблюдал за магнатаврами у Магмота. Но только что вернулся один из его рубак, он говорит, что отряд разбит, а предсказателя утащили в недра Магмота.$b$bНо, чтобы не отправить тебя навстречу верной смерти, мне нужно посоветоваться с духами.$b$bВ руинах Элдра\'ната к западу отсюда обитает элементаль воздуха, которую зовут Империан. Она мудра и, возможно, сообщит тебе нужные сведения.','Поговорите с Империан в руинах Элдра\'ната.','Тебе удалось собрать нужные мне данные, |3-6($C)?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Небо знает',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужно выяснить, что случилось с моим наставником, предсказателем Печальным Путником!$b$bЕще недавно он наблюдал за магнатаврами у Магмота. Но только что вернулся один из его рубак, он говорит, что отряд разбит, а предсказателя утащили в недра Магмота.$b$bНо, чтобы не отправить тебя навстречу верной смерти, мне нужно посоветоваться с духами.$b$bВ руинах Элдра\'ната к западу отсюда обитает элементаль воздуха, которую зовут Империан. Она мудра и, возможно, сообщит тебе нужные сведения.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Империан в руинах Элдра\'ната.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать нужные мне данные, |3-6($C)?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (11625,'Трезубец Наз\'жана','Вернитесь к Вихье в Святилище Чешуи, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трезубец Наз\'жана',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вихье в Святилище Чешуи, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (11626,'Посланник','Вернитесь к Каруку в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Посланник',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Каруку в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11627,'Точка кипения','А, это информация, которая так тебе нужна: местонахождение и состояние твоего "предсказателя". Хорош предсказатель – не смог предвидеть поджидающей его самого беды.$B$BТем не менее я дам тебе средства, с помощью которых можно получить знание. Но сначала сделай кое-что для меня.$B$BБез сомнения, ты $gвидел:видела; битву огня и воды, что протекает к югу отсюда. Шкварчун не перестает нагревать пруд Вспеннера, и поэтому эти двое враждуют уже не первый век.$B$BОтправляйся на Обугленную вершину и Кипящий пруд и убеди каждого прекратить междоусобицу.','По просьбе Империан нанесите поражение Шкварчуну и Вспеннеру, а затем вернитесь к ней в руины Элдра\'ната.','Тебе еще нужно научить этих двоих уму-разуму.','Вернитесь к Империану на Руины Элдра\'ната, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Точка кипения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А, это информация, которая так тебе нужна: местонахождение и состояние твоего "предсказателя". Хорош предсказатель – не смог предвидеть поджидающей его самого беды.$B$BТем не менее я дам тебе средства, с помощью которых можно получить знание. Но сначала сделай кое-что для меня.$B$BБез сомнения, ты $gвидел:видела; битву огня и воды, что протекает к югу отсюда. Шкварчун не перестает нагревать пруд Вспеннера, и поэтому эти двое враждуют уже не первый век.$B$BОтправляйся на Обугленную вершину и Кипящий пруд и убеди каждого прекратить междоусобицу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Империан нанесите поражение Шкварчуну и Вспеннеру, а затем вернитесь к ней в руины Элдра\'ната.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе еще нужно научить этих двоих уму-разуму.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Империану на Руины Элдра\'ната, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11628,'Нечистое должно послужить чистому','К северо-востоку отсюда расположен храмовый город Эн\'кила – оплот Плети в Борейской тундре. Из-за его стен командующий силами Плети послал своих нерубов, чтобы окружить нас.$B$BОстаться в обороне означает смерть для моего народа, но мои советники разошлись во мнениях касательно стратегии. Дурм считает, что надо просто кинуться в атаку, а ведунья Эйри – что лучше сделать все скрытно.$B$BХрамовый город отравил окружающие земли и их обитателей. Эйри считает, что из шкур порабощенных Плетью мамонтов можно сделать плащ, который скроет от глаз Плети того, кто туда проберется.','Принесите вождю Зимней Стуже в деревню Таунка\'ле 5 оскверненных шкур мамонта.','Ты принес шкуры мамонта?','Вернитесь к вождю Зимней Стуже в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Нечистое должно послужить чистому',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К северо-востоку отсюда расположен храмовый город Эн\'кила – оплот Плети в Борейской тундре. Из-за его стен командующий силами Плети послал своих нерубов, чтобы окружить нас.$B$BОстаться в обороне означает смерть для моего народа, но мои советники разошлись во мнениях касательно стратегии. Дурм считает, что надо просто кинуться в атаку, а ведунья Эйри – что лучше сделать все скрытно.$B$BХрамовый город отравил окружающие земли и их обитателей. Эйри считает, что из шкур порабощенных Плетью мамонтов можно сделать плащ, который скроет от глаз Плети того, кто туда проберется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите вождю Зимней Стуже в деревню Таунка\'ле 5 оскверненных шкур мамонта.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты принес шкуры мамонта?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Зимней Стуже в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11629,'Назад, к говорящей с духами','Ты $gсделал:сделала; то, о чем тебя просили, и теперь я дам тебе то, чего ты желаешь.$B$BОтнеси эту изначальную сущность говорящей с духами на заставу Бор\'горока. Если она мудра, то знает, какой ритуал нужен, чтобы добыть информацию, которую ты ищешь.','Доставьте изначальную сущность Империан говорящей с духами Рычеклык на заставу Бор\'горока.','Империан дала тебе свою собственную изначальную сущность? Да, я слышу, как ревут ее ветры!\n\nЯ знаю ритуал, который нам поможет. Но надо спешить, пока ее изначальная сущность не взорвалась изнутри!','Вернитесь к говорящей с духами Рычеклык на Заставу Бор\'горока, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Назад, к говорящей с духами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gсделал:сделала; то, о чем тебя просили, и теперь я дам тебе то, чего ты желаешь.$B$BОтнеси эту изначальную сущность говорящей с духами на заставу Бор\'горока. Если она мудра, то знает, какой ритуал нужен, чтобы добыть информацию, которую ты ищешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте изначальную сущность Империан говорящей с духами Рычеклык на заставу Бор\'горока.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Империан дала тебе свою собственную изначальную сущность? Да, я слышу, как ревут ее ветры!\n\nЯ знаю ритуал, который нам поможет. Но надо спешить, пока ее изначальная сущность не взорвалась изнутри!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящей с духами Рычеклык на Заставу Бор\'горока, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11630,'Оскверненная Плетью земля','Ведунья Эйри считает, что после обработки шкур оскверненной Плетью землей из окрестностей храмового города она сделает плащ, который поможет тебе оставаться $gнезамеченным:незамеченной; для приспешников Плети. Ты просто сольешься с ландшафтом, так она говорит.$B$BХорошо бы, она оказалась права. Это наш единственный шанс добыть информацию и составить план контратаки.$B$BТы $gдолжен:должна; найти нужную ей землю, покопавшись в почве к югу и к западу от крепости. Принеси ее мне, когда соберешь столько, сколько нужно.','Принесите 8 комков оскверненной Плетью земли вождю Зимней Стуже в деревню Таунка\'ле.','Тебе удалось собрать землю, которая нужна ведунье Эйри для плаща?','Вернитесь к вождю Зимней Стуже в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Оскверненная Плетью земля',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ведунья Эйри считает, что после обработки шкур оскверненной Плетью землей из окрестностей храмового города она сделает плащ, который поможет тебе оставаться $gнезамеченным:незамеченной; для приспешников Плети. Ты просто сольешься с ландшафтом, так она говорит.$B$BХорошо бы, она оказалась права. Это наш единственный шанс добыть информацию и составить план контратаки.$B$BТы $gдолжен:должна; найти нужную ей землю, покопавшись в почве к югу и к западу от крепости. Принеси ее мне, когда соберешь столько, сколько нужно.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 комков оскверненной Плетью земли вождю Зимней Стуже в деревню Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось собрать землю, которая нужна ведунье Эйри для плаща?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Зимней Стуже в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11631,'Воздушные видения','Вот, $n, я настроила для тебя изначальную сущность.$B$BОткрой ей свою душу возле моего тотема воздуха и сконцентрируйся на судьбе предсказателя Печального Путника.$B$BДух ветра соприкасается со всем на свете. Если повезет, тебе будет даровано видение.','Воспользуйтесь изначальной сущностью Империан для проведения ритуала возле тотема говорящей с духами Рычеклык на заставе Бор\'горока, чтобы получить информацию о предсказателе Печальном Путнике.$B$BПосле этого поговорите с говорящей с духами Рычеклык.','Когда почувствуешь, что увиденного достаточно, верни мне изначальную сущность.','Вернитесь к говорящей с духами Рычеклык на Заставу Бор\'горока, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воздушные видения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот, $n, я настроила для тебя изначальную сущность.$B$BОткрой ей свою душу возле моего тотема воздуха и сконцентрируйся на судьбе предсказателя Печального Путника.$B$BДух ветра соприкасается со всем на свете. Если повезет, тебе будет даровано видение.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Воспользуйтесь изначальной сущностью Империан для проведения ритуала возле тотема говорящей с духами Рычеклык на заставе Бор\'горока, чтобы получить информацию о предсказателе Печальном Путнике.$B$BПосле этого поговорите с говорящей с духами Рычеклык.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда почувствуешь, что увиденного достаточно, верни мне изначальную сущность.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящей с духами Рычеклык на Заставу Бор\'горока, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11632,'Что несет холодный ветер?..','Что это у тебя?','Вернитесь к верховному правителю Саурфангу в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что несет холодный ветер?..',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному правителю Саурфангу в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11633,'Вписаться в ландшафт','Ведунья Эйри закончила накидку. Возьми ее с собой и отправляйся в храмовый город Эн\'кила. Накинь плащ, когда войдешь в город – он скроет тебя от большинства созданий Плети. Это будет наилучшей возможностью собрать информацию об укреплениях и военном руководстве противника.$B$BНе снимая плаща, обследуй три высоких шпиля на территории города. В то время как накидка защитит тебя от большинства созданий Плети, поганища заметят тебя, если окажешься слишком близко к ним.','По поручению вождя Зимней Стужи отправляйтесь в храмовый город Эн\'кила, наденьте прочную накидку Плети и исследуйте Шпиль Крови, Шпиль Боли и Шпиль Порчи.','Ты закончил исследование шпилей в крепости Плети?','Вернитесь к вождю Зимней Стуже в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вписаться в ландшафт',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ведунья Эйри закончила накидку. Возьми ее с собой и отправляйся в храмовый город Эн\'кила. Накинь плащ, когда войдешь в город – он скроет тебя от большинства созданий Плети. Это будет наилучшей возможностью собрать информацию об укреплениях и военном руководстве противника.$B$BНе снимая плаща, обследуй три высоких шпиля на территории города. В то время как накидка защитит тебя от большинства созданий Плети, поганища заметят тебя, если окажешься слишком близко к ним.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению вождя Зимней Стужи отправляйтесь в храмовый город Эн\'кила, наденьте прочную накидку Плети и исследуйте Шпиль Крови, Шпиль Боли и Шпиль Порчи.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты закончил исследование шпилей в крепости Плети?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Зимней Стуже в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11634,'Повелитель ветра То\'бор','Да, $n, $gотец:мать; из тебя чересчур $gсуровый:суровая;. Думаю, твои способности лучше пригодятся в другом деле – например, чтобы ликвидировать на корню саму эту проблему!$b$b<Разгор указывает на запад.>$b$bТысяча воинов Плети, минимум четыре полноразмерных машины смерти, и неизвестно что еще.$b$bВот ты-то и выяснишь, что именно. А потом постараешься совладать с этим... Да-да, я поручаю тебе задать перцу той самой армии, что сейчас задает жару нам.$b$bОтправляйся на вершину крепости Песни Войны и поговори с повелителем ветра То\'бором. Он ждет тебя.','Явитесь к повелителю ветра То\'бору в крепости Песни Войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Повелитель ветра То\'бор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Да, $n, $gотец:мать; из тебя чересчур $gсуровый:суровая;. Думаю, твои способности лучше пригодятся в другом деле – например, чтобы ликвидировать на корню саму эту проблему!$b$b<Разгор указывает на запад.>$b$bТысяча воинов Плети, минимум четыре полноразмерных машины смерти, и неизвестно что еще.$b$bВот ты-то и выяснишь, что именно. А потом постараешься совладать с этим... Да-да, я поручаю тебе задать перцу той самой армии, что сейчас задает жару нам.$b$bОтправляйся на вершину крепости Песни Войны и поговори с повелителем ветра То\'бором. Он ждет тебя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Явитесь к повелителю ветра То\'бору в крепости Песни Войны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11635,'Дух предсказателя Печального Путника','Иди к Магмоту на восток.$B$BСпустись в глубь тамошних пещер.$B$BПоговори с духом предсказателя Печального Путника!','Поговорите с духом предсказателя Печального Путника в глубинах Магмота.','Спасибо за отсрочку, |3-6($C). Ах, если бы столь же легко достижимой была моя истинная свобода!..','Лок\'тар, |3-6($C). Не может быть, чтобы тебе удалось убить всех в Магмоте за столь короткий срок!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дух предсказателя Печального Путника',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Иди к Магмоту на восток.$B$BСпустись в глубь тамошних пещер.$B$BПоговори с духом предсказателя Печального Путника!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с духом предсказателя Печального Путника в глубинах Магмота.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за отсрочку, |3-6($C). Ах, если бы столь же легко достижимой была моя истинная свобода!..',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Лок\'тар, |3-6($C). Не может быть, чтобы тебе удалось убить всех в Магмоте за столь короткий срок!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11636,'Полет на ковре-самолете') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полет на ковре-самолете',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11637,'Каганишу','Когда мой небольшой отряд пехотинцев был перебит, меня притащили сюда, вниз и совершили ритуальное убийство. Снобольд, который сделал это, известен под именем Каганишу.$B$BХотя ты уже $gсразил:сразила; его помощников-шаманов, мой дух по-прежнему привязан к этому месту. После того как он убил меня, он изготовил амулет из моего тела, который и держит меня здесь. Каганишу использует его, чтобы узнать все, что я знаю о шаманском искусстве.$B$BТы $gдолжен:должна; забрать у него амулет и воздействовать им на мой дух. Каганишу обитает здесь рядом, в пещерах.$B$BТолько тогда я буду по-настоящему свободен.','Добудьте амулет Каганишу и задействуйте его над останками предсказателя Печального Путника.$B$BВам нужно будет передать амулет предсказателю Печальному Путнику в Магмоте.','Поспеши, |3-6($C), используй амулет, пока не стало слишком поздно.','Разыщите дух предсказателя Печального Путника в Магмоте, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Каганишу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Когда мой небольшой отряд пехотинцев был перебит, меня притащили сюда, вниз и совершили ритуальное убийство. Снобольд, который сделал это, известен под именем Каганишу.$B$BХотя ты уже $gсразил:сразила; его помощников-шаманов, мой дух по-прежнему привязан к этому месту. После того как он убил меня, он изготовил амулет из моего тела, который и держит меня здесь. Каганишу использует его, чтобы узнать все, что я знаю о шаманском искусстве.$B$BТы $gдолжен:должна; забрать у него амулет и воздействовать им на мой дух. Каганишу обитает здесь рядом, в пещерах.$B$BТолько тогда я буду по-настоящему свободен.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте амулет Каганишу и задействуйте его над останками предсказателя Печального Путника.$B$BВам нужно будет передать амулет предсказателю Печальному Путнику в Магмоте.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поспеши, |3-6($C), используй амулет, пока не стало слишком поздно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Разыщите дух предсказателя Печального Путника в Магмоте, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11638,'Вернуть мои останки','$n, теперь, когда мой дух свободен, не окажешь ли ты мне честь, вернув мои останки говорящей с духами Рычеклык? Они лежат на земле подо мной.$b$bЯ чую, что говорящая с духами по-прежнему на заставе Бор\'горока на западе, где мы виделись с ней в последний раз.','Доставьте останки предсказателя Печального Путника, которые покоятся под его духом, говорящей с духами Рычеклык на заставу Бор\'горока.','Ты вернулся быстрее, чем я рассчитывала. Что тебе удалось выяснить?','Вернитесь к говорящей с духами Рычеклык на Заставу Бор\'горока, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вернуть мои останки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$n, теперь, когда мой дух свободен, не окажешь ли ты мне честь, вернув мои останки говорящей с духами Рычеклык? Они лежат на земле подо мной.$b$bЯ чую, что говорящая с духами по-прежнему на заставе Бор\'горока на западе, где мы виделись с ней в последний раз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Доставьте останки предсказателя Печального Путника, которые покоятся под его духом, говорящей с духами Рычеклык на заставу Бор\'горока.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся быстрее, чем я рассчитывала. Что тебе удалось выяснить?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к говорящей с духами Рычеклык на Заставу Бор\'горока, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11639,'Месть в Магмоте','Властитель отказывается позволить шаману исцелить мои раны. Он говорит, что это послужит мне хорошим уроком и даст мне время поразмыслить над моим провалом.$B$BНо ты можешь отомстить за меня и за тех, кто пал у Магмота!$B$BЯ знаю, что говорящая с духами хочет, чтобы ты $gотправился:отправилась; туда ради спасения предсказателя.$B$BЭто совсем недалеко, к востоку отсюда. Иди, |3-6($c)... иди, убей магнатавров и их прислужников-снобольдов. Восстанови честь заставы!','Убейте магмотов: 10 шаманов, 5 добытчиков, 3 сокрушителя и 3 жен Магмотрегара. Затем возвращайтесь к Орторошу на заставу Бор\'горока.','Поспеши, |3-6($C), используй амулет, пока не стало слишком поздно.','Вернитесь к Ортрошу на Заставу Бор\'горока, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Месть в Магмоте',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Властитель отказывается позволить шаману исцелить мои раны. Он говорит, что это послужит мне хорошим уроком и даст мне время поразмыслить над моим провалом.$B$BНо ты можешь отомстить за меня и за тех, кто пал у Магмота!$B$BЯ знаю, что говорящая с духами хочет, чтобы ты $gотправился:отправилась; туда ради спасения предсказателя.$B$BЭто совсем недалеко, к востоку отсюда. Иди, |3-6($c)... иди, убей магнатавров и их прислужников-снобольдов. Восстанови честь заставы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте магмотов: 10 шаманов, 5 добытчиков, 3 сокрушителя и 3 жен Магмотрегара. Затем возвращайтесь к Орторошу на заставу Бор\'горока.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Поспеши, |3-6($C), используй амулет, пока не стало слишком поздно.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ортрошу на Заставу Бор\'горока, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11640,'Слова могущества','В описанных вами башнях живут главные приспешники предводителя Плети – верховные жрецы. Они не только командуют войсками Плети: они стерегут вход в Некрополь, и к своему хозяину.$b$bНескончаемый поток порождений Плети захлестнет нас с головой, если мы не сумеем найти и обезвредить их предводителя. Я не могу оставить свой народ без защиты, как бы сильно Дурму ни хотелось перенести войну на территорию противника. Именно вам, $n, придется истребить верховных жрецов и забрать свитки, которые хранятся у них.','Принесите свиток верховного жреца Наферсета, свиток верховного жреца Талет-Ха и свиток верховного жреца Андората вождю Зимней Стуже в деревне Таунка\'ле.','Если мы хотим прорваться через Плеть и расчистить путь жителям деревни, нужно проникнуть в этот некрополь!','Вернитесь к вождю Зимней Стуже в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Слова могущества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В описанных вами башнях живут главные приспешники предводителя Плети – верховные жрецы. Они не только командуют войсками Плети: они стерегут вход в Некрополь, и к своему хозяину.$b$bНескончаемый поток порождений Плети захлестнет нас с головой, если мы не сумеем найти и обезвредить их предводителя. Я не могу оставить свой народ без защиты, как бы сильно Дурму ни хотелось перенести войну на территорию противника. Именно вам, $n, придется истребить верховных жрецов и забрать свитки, которые хранятся у них.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите свиток верховного жреца Наферсета, свиток верховного жреца Талет-Ха и свиток верховного жреца Андората вождю Зимней Стуже в деревне Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если мы хотим прорваться через Плеть и расчистить путь жителям деревни, нужно проникнуть в этот некрополь!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к вождю Зимней Стуже в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11641,'Смелость города берет!','С самого начала я советовал, чтобы вождь Зимняя Стужа собрал наших могучих воинов и напал на врага на его территории. Но он остался глух к моим советам и предпочел ходить вокруг да около, как предложила ведунья Эйри.$B$BЯ не собираюсь больше ждать. Если вождь Зимняя Стужа слишком труслив, чтобы отправить наших воинов в бой, может быть, ты покажешь ему, что лобовая атака может быть успешной. Ворвись в храмовый город Эн\'кила и сокруши все на своем пути, $n.','Убейте 15 вурдалаков и 5 некромантов из Эн\'кила и доложите об этом Дурму Ледяной Шкуре, который живет в деревне Таунка\'ле.','Как... как ты нашел меня?','Вернитесь к Дурму Ледяной Шкуре в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смелость города берет!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','С самого начала я советовал, чтобы вождь Зимняя Стужа собрал наших могучих воинов и напал на врага на его территории. Но он остался глух к моим советам и предпочел ходить вокруг да около, как предложила ведунья Эйри.$B$BЯ не собираюсь больше ждать. Если вождь Зимняя Стужа слишком труслив, чтобы отправить наших воинов в бой, может быть, ты покажешь ему, что лобовая атака может быть успешной. Ворвись в храмовый город Эн\'кила и сокруши все на своем пути, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 15 вурдалаков и 5 некромантов из Эн\'кила и доложите об этом Дурму Ледяной Шкуре, который живет в деревне Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как... как ты нашел меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дурму Ледяной Шкуре в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11642,'Танк сам собой не починится!','Поговорите с Мобу в лагере Гарроша.','А, так ты новый водитель танка, дружище? Сойдет! Нам нужно просто снова заставить эти штуковины ехать. Да уж, только попробуй забраться на равнины Назама без танка – и ты, считай, труп.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танк сам собой не починится!',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Мобу в лагере Гарроша.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, так ты новый водитель танка, дружище? Сойдет! Нам нужно просто снова заставить эти штуковины ехать. Да уж, только попробуй забраться на равнины Назама без танка – и ты, считай, труп.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11643,'Танковая пневматическая трансзажиматрица Мобу','Эти штуки бесполезны, дружище. Чтобы поставить на ход эти машинки, мне нужна моя танковая пневматическая трансзажиматрица! К сожалению, я оставил ее на прежнем месте, на другой стороне лагеря. В покосившемся домике рядом с конюшнями. Тебе придется пойти и принести мне инструмент, потому что меня хоть огнем демоническим жги – к туману я и близко не подойду.$B$BО да, дружище, берегись тумана. Это он исковеркал это побережье.','Принесите Мобу на берег Эха в Борейской тундре его танковую пневматическую трансзажиматрицу.','Ну, что, удалось найти мою Т.П.Т.?','Вернитесь к Мобу на Берег Эха, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танковая пневматическая трансзажиматрица Мобу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эти штуки бесполезны, дружище. Чтобы поставить на ход эти машинки, мне нужна моя танковая пневматическая трансзажиматрица! К сожалению, я оставил ее на прежнем месте, на другой стороне лагеря. В покосившемся домике рядом с конюшнями. Тебе придется пойти и принести мне инструмент, потому что меня хоть огнем демоническим жги – к туману я и близко не подойду.$B$BО да, дружище, берегись тумана. Это он исковеркал это побережье.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Мобу на берег Эха в Борейской тундре его танковую пневматическую трансзажиматрицу.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что, удалось найти мою Т.П.Т.?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мобу на Берег Эха, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11644,'Сверхпрочные металлические пластины!','Мне нужен металл, чтобы подлатать эти танки! Сверхпрочные металлические пластины раскиданы почти по всему лагерю Гарроша и на дне залива.$B$BТолько будь осторожнее, когда пойдешь их искать. Туман, он... ну... АГРЕССИВНЫЙ! Именно туман уничтожил лагерь и соседний городок клыкарров. Бедняжки клыкарры...','По заданию Мобу соберите 10 сверхпрочных металлических пластин и принесите ему на берег Эха в Борейской тундре.','Помни, туман – плохо!','Вернитесь к Мобу на Берег Эха, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сверхпрочные металлические пластины!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне нужен металл, чтобы подлатать эти танки! Сверхпрочные металлические пластины раскиданы почти по всему лагерю Гарроша и на дне залива.$B$BТолько будь осторожнее, когда пойдешь их искать. Туман, он... ну... АГРЕССИВНЫЙ! Именно туман уничтожил лагерь и соседний городок клыкарров. Бедняжки клыкарры...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Мобу соберите 10 сверхпрочных металлических пластин и принесите ему на берег Эха в Борейской тундре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Помни, туман – плохо!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мобу на Берег Эха, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11645,'Грязные, вонючие снобольды!','Грязные, вонючие снобольды! Они разворовали все мои припасы!$b$bТы спрашиваешь, что такое снобольды? Это те же кобольды, только они служат магнатаврам, вроде как заботятся о них. Странно, да, я знаю!$b$bНо это все неважно. Не согласишься ли ты мне помочь? Я знаю, куда эти мерзкие крысы уволокли все мое добро. Поделом мне: нечего было рассчитывать, будто на северном конце полосы припасы будут в безопасности.$b$bОкажи услугу, сходи на север, в их дурацкий Магмот! Если принесешь мое добро, я в долгу не останусь!','Добудьте 10 ящиков с вещами Умейки и верните их Умейке Шестеркрут на взлетной полосе Выкрутеня.','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Грязные, вонючие снобольды!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Грязные, вонючие снобольды! Они разворовали все мои припасы!$b$bТы спрашиваешь, что такое снобольды? Это те же кобольды, только они служат магнатаврам, вроде как заботятся о них. Странно, да, я знаю!$b$bНо это все неважно. Не согласишься ли ты мне помочь? Я знаю, куда эти мерзкие крысы уволокли все мое добро. Поделом мне: нечего было рассчитывать, будто на северном конце полосы припасы будут в безопасности.$b$bОкажи услугу, сходи на север, в их дурацкий Магмот! Если принесешь мое добро, я в долгу не останусь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 ящиков с вещами Умейки и верните их Умейке Шестеркрут на взлетной полосе Выкрутеня.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11646,'Борейские дознаватели','Слушай внимательно, $n, поскольку приходится дорожить каждой минутой.$B$BТвоего пленника готовят к допросу тут, в нашей башне. Если он не захочет откровенничать, может потребоваться твоя помощь.$B$BСходи туда, где его содержат, и скажи библиотекарю Нормантису, что я послал тебя ему в помощь.','По приказу Донатана пойдите к библиотекарю Нормантису в башню магов на Янтарной гряде и предложите ему свою помощь.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Борейские дознаватели',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Слушай внимательно, $n, поскольку приходится дорожить каждой минутой.$B$BТвоего пленника готовят к допросу тут, в нашей башне. Если он не захочет откровенничать, может потребоваться твоя помощь.$B$BСходи туда, где его содержат, и скажи библиотекарю Нормантису, что я послал тебя ему в помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По приказу Донатана пойдите к библиотекарю Нормантису в башню магов на Янтарной гряде и предложите ему свою помощь.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11647,'Обезвредить чумные котлы','Меня крайне тревожит существование чумных котлов в Храмовом городе Эн\'кила, $n. Очевидно, что вождь Зимняя Стужа доверяет твоему благоразумию и твоим знаниям о наших врагах. Не поможешь ли ты мне изничтожить котлы вместе с тем, что ты помогаешь вождю приводить в исполнение его планы касательно Храмового города?$b$bЯ приготовила тотем, который нападет на котлы и нейтрализует их содержимое. Тебе нужно только отыскать котлы и пустить в ход тотем возле каждого из них. Каждое орудие Плети, уничтоженное нами, – это еще один шаг к победе!','Как... как ты нашел меня?','Вернитесь к ведунье Эйри в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обезвредить чумные котлы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Меня крайне тревожит существование чумных котлов в Храмовом городе Эн\'кила, $n. Очевидно, что вождь Зимняя Стужа доверяет твоему благоразумию и твоим знаниям о наших врагах. Не поможешь ли ты мне изничтожить котлы вместе с тем, что ты помогаешь вождю приводить в исполнение его планы касательно Храмового города?$b$bЯ приготовила тотем, который нападет на котлы и нейтрализует их содержимое. Тебе нужно только отыскать котлы и пустить в ход тотем возле каждого из них. Каждое орудие Плети, уничтоженное нами, – это еще один шаг к победе!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как... как ты нашел меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведунье Эйри в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11648,'Искусство убеждения','Как удачно, что ты здесь, |3-6($r)!$b$bВидишь ли, кодекс чести Кирин-Тора не одобряет крайних мер, даже в таких отчаянных ситуациях, как теперь.$b$bНо ты – $gчужестранец:чужестранка;, тебя эти ограничения не касаются, так что тебе ничто не мешает предпринять действия, необходимые для получения информации.$b$bДелай все, что понадобится. Нам нужно немедленно узнать, где держат леди Эванор!$b$bА я пока приберусь на полочках... Да, и прихвати эту старую штуковину, она тебе может пригодиться!','Используйте генератор боли против закованного бериллового колдуна, пока тот не выдаст местонахождение леди Эванор, по просьбе библиотекаря Нормантиса с Янтарной гряды.','Ну что? Удалось тебе выяснить, где держат леди Эванор?','Вернитесь к библиотекарю Нормантису на Янтарную гряду, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Искусство убеждения',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как удачно, что ты здесь, |3-6($r)!$b$bВидишь ли, кодекс чести Кирин-Тора не одобряет крайних мер, даже в таких отчаянных ситуациях, как теперь.$b$bНо ты – $gчужестранец:чужестранка;, тебя эти ограничения не касаются, так что тебе ничто не мешает предпринять действия, необходимые для получения информации.$b$bДелай все, что понадобится. Нам нужно немедленно узнать, где держат леди Эванор!$b$bА я пока приберусь на полочках... Да, и прихвати эту старую штуковину, она тебе может пригодиться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте генератор боли против закованного бериллового колдуна, пока тот не выдаст местонахождение леди Эванор, по просьбе библиотекаря Нормантиса с Янтарной гряды.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что? Удалось тебе выяснить, где держат леди Эванор?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к библиотекарю Нормантису на Янтарную гряду, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11649,'Частицы разгневанных бурь','Теперь, когда эта небольшая ссора улажена, остается только помочь тебе и твоей знакомой, говорящей с духами.$B$BКак видишь, мои подданные разгневаны непрекращающейся войной между огнем и водой. Боюсь, эта битва утихнет еще не скоро, но ты сможешь извлечь из нее пользу.$B$BЯ знаю, что может тебе помочь. Отправляйся в руины и собери частицы бури.','Добудьте 5 частиц бури и принесите Империан в руины Элдра\'ната.','Когда ты принесешь частицы бурь, я смешаю с ними часть своей сущности. В результате получится как раз то, что тебе надо.','Вернитесь к Империану на Руины Элдра\'ната, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Частицы разгневанных бурь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда эта небольшая ссора улажена, остается только помочь тебе и твоей знакомой, говорящей с духами.$B$BКак видишь, мои подданные разгневаны непрекращающейся войной между огнем и водой. Боюсь, эта битва утихнет еще не скоро, но ты сможешь извлечь из нее пользу.$B$BЯ знаю, что может тебе помочь. Отправляйся в руины и собери частицы бури.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 5 частиц бури и принесите Империан в руины Элдра\'ната.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Когда ты принесешь частицы бурь, я смешаю с ними часть своей сущности. В результате получится как раз то, что тебе надо.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Империану на Руины Элдра\'ната, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11650,'Еще кое-что...','Найдите инструменты Умейки, перегруженный конденсатор и горсть песка Рокнара. Доставьте все это Умейке Шестеркрут на взлетную полосу Выкрутеня.','А, вот так-то лучше! Теперь остается только собрать все это вместе.$B$BНу да, конечно, можно подумать, ты мне чем-то поможешь!$B$BНе суетись: теперь, когда я заполучила свои инструменты, это займет всего пару секунд!','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Еще кое-что...',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите инструменты Умейки, перегруженный конденсатор и горсть песка Рокнара. Доставьте все это Умейке Шестеркрут на взлетную полосу Выкрутеня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А, вот так-то лучше! Теперь остается только собрать все это вместе.$B$BНу да, конечно, можно подумать, ты мне чем-то поможешь!$B$BНе суетись: теперь, когда я заполучила свои инструменты, это займет всего пару секунд!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11651,'Броня крепка, и танки наши...','При нынешнем состоянии наших кораблей и морских путей мы никак не могли доставить эту проклятую боевую машину в Песню Войны. Эти танки – все, что у нас осталось от первоначальной экспедиции. Теперь, когда они пригодны к работе, вы можете использовать их, чтобы стереть в порошок войска Плети на равнинах Назама.','Ну, что, удалось найти мою Т.П.Т.?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Броня крепка, и танки наши...',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','При нынешнем состоянии наших кораблей и морских путей мы никак не могли доставить эту проклятую боевую машину в Песню Войны. Эти танки – все, что у нас осталось от первоначальной экспедиции. Теперь, когда они пригодны к работе, вы можете использовать их, чтобы стереть в порошок войска Плети на равнинах Назама.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, что, удалось найти мою Т.П.Т.?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11652,'Равнины Назама','Как только будешь $gготов:готова;, запрыгивай в любой из танков и выезжай на равнины Назама, к юго-востоку отсюда.$b$bИспользуй вооружение танка, чтобы крушить войска Плети. Если танк застрянет, наш Фаршеватель порвет их в клочки, а мины прикончат тех, кто остался в живых! И последнее: баки с топливом стоят на равнине повсюду.$b$bПопытайся подобраться поближе к тому зданию в центре и выяснить, что там происходит.$b$bЕсли тебе удастся выполнить все это и остаться в живых, отправляйся к Адскому Крику!','Используйте ордынский осадный танк, чтобы уничтожить 100 солдат Плети и спасти 3 раненых солдата Песни Войны на равнинах Назама. Кроме того, выясните, кто возглавляет наступление Плети.$b$bВыполнив все это, отправляйтесь к Гаррошу Адскому Крику в крепость Песни Войны.','Так? Что произошло?','Предводитель Плети опознан','Вернитесь к Гаррошу Адскому Крику в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Равнины Назама',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как только будешь $gготов:готова;, запрыгивай в любой из танков и выезжай на равнины Назама, к юго-востоку отсюда.$b$bИспользуй вооружение танка, чтобы крушить войска Плети. Если танк застрянет, наш Фаршеватель порвет их в клочки, а мины прикончат тех, кто остался в живых! И последнее: баки с топливом стоят на равнине повсюду.$b$bПопытайся подобраться поближе к тому зданию в центре и выяснить, что там происходит.$b$bЕсли тебе удастся выполнить все это и остаться в живых, отправляйся к Адскому Крику!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте ордынский осадный танк, чтобы уничтожить 100 солдат Плети и спасти 3 раненых солдата Песни Войны на равнинах Назама. Кроме того, выясните, кто возглавляет наступление Плети.$b$bВыполнив все это, отправляйтесь к Гаррошу Адскому Крику в крепость Песни Войны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Так? Что произошло?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Предводитель Плети опознан',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гаррошу Адскому Крику в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11653,'Ха! Не такой уж ты и большой теперь!','Все будет отлично, шеф! Итак, вот что я хочу, чтобы ты сделал...$B$BВозьми мой самострел и отправляйся на север, к Магмоту. Если мы хотим иметь хоть какие-то шансы против этих монстров, то нам надо их, так сказать, подогнать под размер.$B$BДля калибровки самострела я хочу, чтобы ты убивал магнатавров, пока самострел еще действует на них. Подойдут любые сокрушители или супруги, а с мелкими не возись... малы слишком, чтобы о них беспокоиться.','Испробуйте прототип ультрасовременного укорачивающего излучателя Умейки на 5 магмотах-сокрушителях или женах Магмотрегара. Когда все будет сделано, вернитесь к Умейке на взлетную полосу Выкрутеня.','То ись как – не сработал?!$B$BНо... но…$B$B<Умейка начинает всхлипывать и готова разрыдаться.>$B$BЛадно, мы это переживем. Я уже большая девочка. Попробуем найти нестандартное решение!','Вы $Gуверен:уверена;, что $Gиспытал:испытала; бластер на этих чудовищных тварях?','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ха! Не такой уж ты и большой теперь!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Все будет отлично, шеф! Итак, вот что я хочу, чтобы ты сделал...$B$BВозьми мой самострел и отправляйся на север, к Магмоту. Если мы хотим иметь хоть какие-то шансы против этих монстров, то нам надо их, так сказать, подогнать под размер.$B$BДля калибровки самострела я хочу, чтобы ты убивал магнатавров, пока самострел еще действует на них. Подойдут любые сокрушители или супруги, а с мелкими не возись... малы слишком, чтобы о них беспокоиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Испробуйте прототип ультрасовременного укорачивающего излучателя Умейки на 5 магмотах-сокрушителях или женах Магмотрегара. Когда все будет сделано, вернитесь к Умейке на взлетную полосу Выкрутеня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То ись как – не сработал?!$B$BНо... но…$B$B<Умейка начинает всхлипывать и готова разрыдаться.>$B$BЛадно, мы это переживем. Я уже большая девочка. Попробуем найти нестандартное решение!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы $Gуверен:уверена;, что $Gиспытал:испытала; бластер на этих чудовищных тварях?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11654,'Шпиль Крови','Изучая взятую склянку с кровью, вы обнаруживаете, что ее содержимое еще теплое. Кровь у жертвы, должно быть, взяли совсем недавно, она может быть еще жива.$B$BНо зачем Плети кровь? Раньше захват пленных их никогда не интересовал. Может быть, если вам удастся установить, чья это кровь, вы сможете понять, что планируют создания Плети.','Поищите на Шпиле Крови информацию касательно склянки со свежей кровью.','<Снежный следопыт таунка плохо выглядит и еле-еле отвечает вам.>\n\nЯ не... долго. Может... может, ты сможешь остановить их... прежде чем...','Как... как ты нашел меня?','Вернитесь к снежному следопыту Грумму в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Шпиль Крови',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Изучая взятую склянку с кровью, вы обнаруживаете, что ее содержимое еще теплое. Кровь у жертвы, должно быть, взяли совсем недавно, она может быть еще жива.$B$BНо зачем Плети кровь? Раньше захват пленных их никогда не интересовал. Может быть, если вам удастся установить, чья это кровь, вы сможете понять, что планируют создания Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поищите на Шпиле Крови информацию касательно склянки со свежей кровью.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Снежный следопыт таунка плохо выглядит и еле-еле отвечает вам.>\n\nЯ не... долго. Может... может, ты сможешь остановить их... прежде чем...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как... как ты нашел меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к снежному следопыту Грумму в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11655,'В туман','Пройдя к северу через туман, ты доберешься до лагеря Гарроша. К югу – руины моего прежнего дома, Пал\'ии. Оба эти места были разорены древней силой, известной как квалдиры.$B$BЭти жуткие дикари безжалостно убили весь мой народ, а твой заставили уйти во внутренние земли.$B$BВсе, что осталось от клыкарров Пал\'ии – наши личные вещи, взятые квалдирами в качестве реликвий. Хотя мы не мстительная раса, справедливость должна быть восстановлена. Реликвии клыкарров должны быть возвращены мне. Войди в туман и найди их...','Убейте квалдиров, найдите 8 реликвий клыкарров и принесите их Вальтору из Пал\'ии на Берег Эха в Борейской тундре.','Ты должен служить кровью и честью... Верни реликвии клыкарров!','Вернитесь к Вальтору из Пал\'ии на Берег Эха, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В туман',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пройдя к северу через туман, ты доберешься до лагеря Гарроша. К югу – руины моего прежнего дома, Пал\'ии. Оба эти места были разорены древней силой, известной как квалдиры.$B$BЭти жуткие дикари безжалостно убили весь мой народ, а твой заставили уйти во внутренние земли.$B$BВсе, что осталось от клыкарров Пал\'ии – наши личные вещи, взятые квалдирами в качестве реликвий. Хотя мы не мстительная раса, справедливость должна быть восстановлена. Реликвии клыкарров должны быть возвращены мне. Войди в туман и найди их...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте квалдиров, найдите 8 реликвий клыкарров и принесите их Вальтору из Пал\'ии на Берег Эха в Борейской тундре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты должен служить кровью и честью... Верни реликвии клыкарров!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вальтору из Пал\'ии на Берег Эха, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11656,'Показательное сожжение','Клыкаррская магия очень похожа на то, что вы зовете шаманством. Правда, мы служим стихиям иначе, чем вы, но мощь, которую мы можем вызывать, огромна.$B$B<Вальтор помахивает перед вами похожим на факел жезлом.>$B$BЯ хочу, чтобы с помощью этого клыкаррского факела ты $gвернулся:вернулась; в туман и $gударил:ударила; по квалдирским судам. Три из них стоят за туманом у лагеря Гарроша, к северу отсюда, а еще один пришвартован у берегов Пал\'ии, на юге. Сожги их так, чтобы все видели!','Демонстрация нашего сопротивления квалдирским дикарям – может быть, именно это и нужно, чтобы спасти моих соплеменников в других лагерях. Может быть, квалдирцы пересмотрят свои действия, если уверятся, что возмездие неизбежно.','Орабуса нужно уничтожить!','Вернитесь к Вальтору из Пал\'ии на Берег Эха, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Показательное сожжение',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Клыкаррская магия очень похожа на то, что вы зовете шаманством. Правда, мы служим стихиям иначе, чем вы, но мощь, которую мы можем вызывать, огромна.$B$B<Вальтор помахивает перед вами похожим на факел жезлом.>$B$BЯ хочу, чтобы с помощью этого клыкаррского факела ты $gвернулся:вернулась; в туман и $gударил:ударила; по квалдирским судам. Три из них стоят за туманом у лагеря Гарроша, к северу отсюда, а еще один пришвартован у берегов Пал\'ии, на юге. Сожги их так, чтобы все видели!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Демонстрация нашего сопротивления квалдирским дикарям – может быть, именно это и нужно, чтобы спасти моих соплеменников в других лагерях. Может быть, квалдирцы пересмотрят свои действия, если уверятся, что возмездие неизбежно.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Орабуса нужно уничтожить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вальтору из Пал\'ии на Берег Эха, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11657,'Поймай факел!','Ну, факел ты теперь бросать умеешь, так посмотри, сможешь ли ты его еще и поймать!$B$BБери эту связку незажженных факелов. Ступай к костру и подбрось факел высоко в воздух. Поймай его прежде, чем он коснется земли... затем снова подбрось его в воздух! Поймай четыре факела подряд, затем возвращайся ко мне.$B$BОсторожнее! Они опасны при ударе о землю! И не пропусти ни одного! Если пропустишь, придется вернуться к костру и начать все с начала. Удачи!','Поймайте подряд 4 факела, затем поговорите с мастером-огнеглотателем.','Не $Gобжегся:обожглась;? Если да, то дважды подумай прежде, чем играть с огнем...$B$BШучу! Все вышло здорово! И это уже не шутка. Ты – отличный огненный жонглер! Теперь иди, веселись!','Поймайте 4 факела подряд.','Вернитесь к огнеглотателю-виртуозу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поймай факел!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, факел ты теперь бросать умеешь, так посмотри, сможешь ли ты его еще и поймать!$B$BБери эту связку незажженных факелов. Ступай к костру и подбрось факел высоко в воздух. Поймай его прежде, чем он коснется земли... затем снова подбрось его в воздух! Поймай четыре факела подряд, затем возвращайся ко мне.$B$BОсторожнее! Они опасны при ударе о землю! И не пропусти ни одного! Если пропустишь, придется вернуться к костру и начать все с начала. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте подряд 4 факела, затем поговорите с мастером-огнеглотателем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не $Gобжегся:обожглась;? Если да, то дважды подумай прежде, чем играть с огнем...$B$BШучу! Все вышло здорово! И это уже не шутка. Ты – отличный огненный жонглер! Теперь иди, веселись!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поймайте 4 факела подряд.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к огнеглотателю-виртуозу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11658,'План Б','Ладно, не паникуй! Ну не сработал самострел, но у нас есть и другие варианты.$B$B<Умейка щелкает пальцами.>$B$BМы собираемся отвлечь внимание от взлетной полосы! Чтобы это сделать, нам прежде всего понадобится несколько вещей.$B$B<Шестеркрут оценивающе оглядывает вас сверху вниз.>$B$BКараван Стальной Челюсти – прямо к западу отсюда – по глупости решил срезать дорогу через кладбище таунка и был уничтожен восставшими духами.$B$BОтправляйся-ка туда и стащи с мертвых орков какую-нибудь одежку. А заодно и одно из их знамен прихвати!','По просьбе Умейки Шестеркрут со взлетной полосы Выкрутеня соберите 10 комплектов одежды и знамя клана Песни Войны.','То, что нужно, но какая вонь!$B$BЯ лучше помру, чем надену такую дрянь. Но нам нужно порыться в этих тряпках и найти что-то что будет тебе к ли... впору.','Нам понадобится куча их одежд, если мы хотим, чтобы все сработало как надо. Я тебе не швея... нужно просто подобрать что-нибудь, что тебе подойдет!$B$BА потом я просто пройдусь прикосновением своего инженерного гения, и вуаля! – ты будешь выглядеть так, как и надо для твоей роли.','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План Б',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, не паникуй! Ну не сработал самострел, но у нас есть и другие варианты.$B$B<Умейка щелкает пальцами.>$B$BМы собираемся отвлечь внимание от взлетной полосы! Чтобы это сделать, нам прежде всего понадобится несколько вещей.$B$B<Шестеркрут оценивающе оглядывает вас сверху вниз.>$B$BКараван Стальной Челюсти – прямо к западу отсюда – по глупости решил срезать дорогу через кладбище таунка и был уничтожен восставшими духами.$B$BОтправляйся-ка туда и стащи с мертвых орков какую-нибудь одежку. А заодно и одно из их знамен прихвати!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Умейки Шестеркрут со взлетной полосы Выкрутеня соберите 10 комплектов одежды и знамя клана Песни Войны.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','То, что нужно, но какая вонь!$B$BЯ лучше помру, чем надену такую дрянь. Но нам нужно порыться в этих тряпках и найти что-то что будет тебе к ли... впору.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам понадобится куча их одежд, если мы хотим, чтобы все сработало как надо. Я тебе не швея... нужно просто подобрать что-нибудь, что тебе подойдет!$B$BА потом я просто пройдусь прикосновением своего инженерного гения, и вуаля! – ты будешь выглядеть так, как и надо для твоей роли.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11659,'Уничтожьте шары!','Они... выпускают кровь... из пленных... и вливают... в эти шары.$b$b<Глаза Грумма на миг закрываются, он роняет голову.>$b$bКровь... относят в Некрополь... кормить кровавого принца...$b$b<Грумм задыхается.>$b$bОб-бещай... что уничтожишь... кровавые... шары... сообщи Джунеку...$b$b<Снежный следопыт теряет сознание.>','Уничтожьте 5 кровавых сфер и сообщите о случившемся снежному следопыту Джунеку в деревне Таунка\'ле.','Как... как ты нашел меня?','Вернитесь к снежному следопыту Джунеку в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уничтожьте шары!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Они... выпускают кровь... из пленных... и вливают... в эти шары.$b$b<Глаза Грумма на миг закрываются, он роняет голову.>$b$bКровь... относят в Некрополь... кормить кровавого принца...$b$b<Грумм задыхается.>$b$bОб-бещай... что уничтожишь... кровавые... шары... сообщи Джунеку...$b$b<Снежный следопыт теряет сознание.>',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 5 кровавых сфер и сообщите о случившемся снежному следопыту Джунеку в деревне Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как... как ты нашел меня?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к снежному следопыту Джунеку в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11660,'Рог старого морехода','Квалдирский лейтенант по имени Орабус возглавлял первую волну нашествия на моих соплеменников в Пал\'ии. Под его руководством были разрушены обе наших деревни, после чего Орабус скрылся в тумане.$B$BВ те далекие дни ходили слухи о роге, который лейтенант передал ткачам тумана из племени Квалдир. С помощью этого рога можно было при необходимости призвать самого Орабуса.$B$BНам нужно заполучить этот рог, отобрав его у ткачей туманов, и провести этот ритуал. Если убить предводителя, может быть, эти дикари отступят.$B$BТкачей туманов ищи у Пал\'ии, к югу отсюда.','Принесите рог старого морехода Вальтору из Пал\'ии на берег Эха в Борейской тундре.','Ты должен призвать Орабуса с помощью рога старого морехода.','Найди рог старого морехода!','Вернитесь к Вальтору из Пал\'ии на Берег Эха, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рог старого морехода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Квалдирский лейтенант по имени Орабус возглавлял первую волну нашествия на моих соплеменников в Пал\'ии. Под его руководством были разрушены обе наших деревни, после чего Орабус скрылся в тумане.$B$BВ те далекие дни ходили слухи о роге, который лейтенант передал ткачам тумана из племени Квалдир. С помощью этого рога можно было при необходимости призвать самого Орабуса.$B$BНам нужно заполучить этот рог, отобрав его у ткачей туманов, и провести этот ритуал. Если убить предводителя, может быть, эти дикари отступят.$B$BТкачей туманов ищи у Пал\'ии, к югу отсюда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите рог старого морехода Вальтору из Пал\'ии на берег Эха в Борейской тундре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты должен призвать Орабуса с помощью рога старого морехода.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Найди рог старого морехода!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вальтору из Пал\'ии на Берег Эха, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11661,'Орабус Кормчий','Возьми рог и отправляйся на запад, к пристани Песни Войны. Доберись до конца пристани и протруби в рог. Этот звук должен пробудить Орабуса.$B$BУбей эту злобную тварь и возвращайся ко мне!','По заданию Вальтора из Пал\'ии с берега Эха в Борейской тундре протрубите в рог древнего моряка, чтобы призвать Орабуса Кормчего. Когда Орабус появится, убейте его.','Орабуса нужно уничтожить!','Вернитесь к Вальтору из Пал\'ии на Берег Эха, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Орабус Кормчий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Возьми рог и отправляйся на запад, к пристани Песни Войны. Доберись до конца пристани и протруби в рог. Этот звук должен пробудить Орабуса.$B$BУбей эту злобную тварь и возвращайся ко мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По заданию Вальтора из Пал\'ии с берега Эха в Борейской тундре протрубите в рог древнего моряка, чтобы призвать Орабуса Кормчего. Когда Орабус появится, убейте его.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Орабуса нужно уничтожить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Вальтору из Пал\'ии на Берег Эха, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11662,'Найти Карука','Еще один выживший из Пал\'ии – его зовут Карук – отправился на основную квалдирскую базу в Борейской тундре, далеко на юг, где когда-то было полно снега. Карук прячется в утесах, наблюдая за берегом Терзающего Бича.$B$BНайди Карука, и пусть он узнает о том, что $gсделал:сделала; ты ради моего народа здесь, на берегу Эха. Из крепости Песни Войны направляйся по дороге на юг и не сворачивай с нее, пока не доедешь до берега Терзающего Бича.','Найдите Карука на берегу Терзающего Бича.','Ты вернулся? Так быстро?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Найти Карука',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Еще один выживший из Пал\'ии – его зовут Карук – отправился на основную квалдирскую базу в Борейской тундре, далеко на юг, где когда-то было полно снега. Карук прячется в утесах, наблюдая за берегом Терзающего Бича.$B$BНайди Карука, и пусть он узнает о том, что $gсделал:сделала; ты ради моего народа здесь, на берегу Эха. Из крепости Песни Войны направляйся по дороге на юг и не сворачивай с нее, пока не доедешь до берега Терзающего Бича.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Карука на берегу Терзающего Бича.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся? Так быстро?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11663,'Передача сведений','Спасибо, |3-6($c)! Информация, которую тебе удалось извлечь, жизненно важна для Кирин-Тора.$B$BВозвращайся тотчас же к Донатану, пока мы составляем планы спасения леди Эванор.','По просьбе Нормантиса отчитайтесь библиотекарю Донатану на Янтарной гряде.','Ну что? Удалось тебе выяснить, где держат леди Эванор?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Передача сведений',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Спасибо, |3-6($c)! Информация, которую тебе удалось извлечь, жизненно важна для Кирин-Тора.$B$BВозвращайся тотчас же к Донатану, пока мы составляем планы спасения леди Эванор.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Нормантиса отчитайтесь библиотекарю Донатану на Янтарной гряде.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что? Удалось тебе выяснить, где держат леди Эванор?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11664,'Спастись из тумана','Я слышу снаружи тварей из тумана. Их вопли сводят меня с ума, но я не решаюсь бежать отсюда. Да и куда мне идти? Они догонят меня и казнят, как и остальных...$b$bСкажи, $gчужестранец:чужестранка;, далеко ли простирается туман? Может, он накрыл уже весь этот материк?$b$bБыть может, ты согласишься помочь мне вырваться из тумана? Думаю, я сумею найти дорогу обратно к моему отцу. Я все еще чувствую его живой дух. Он близко...','Выведите Муту Младшую из тумана. Если вам удастся спасти Муту Младшую, поговорите со старейшиной Муту.','Об этом шепчутся ветра, друг. Твое имя известно стихиям. Муту не забудут твоей услуги!','Найди рог старого морехода!','Муту спасена','Вернитесь к старейшине Муту на Берег Эха, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спастись из тумана',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышу снаружи тварей из тумана. Их вопли сводят меня с ума, но я не решаюсь бежать отсюда. Да и куда мне идти? Они догонят меня и казнят, как и остальных...$b$bСкажи, $gчужестранец:чужестранка;, далеко ли простирается туман? Может, он накрыл уже весь этот материк?$b$bБыть может, ты согласишься помочь мне вырваться из тумана? Думаю, я сумею найти дорогу обратно к моему отцу. Я все еще чувствую его живой дух. Он близко...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выведите Муту Младшую из тумана. Если вам удастся спасти Муту Младшую, поговорите со старейшиной Муту.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Об этом шепчутся ветра, друг. Твое имя известно стихиям. Муту не забудут твоей услуги!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Найди рог старого морехода!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Муту спасена',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Муту на Берег Эха, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11665,'Кроколиски в городе','Привет, $gпарень:девчушка;. Славно, что $Gостановился:остановилась; поболтать со старичком, у которого дома не все ладно.$b$bТут недавно один странствующий торговец продал партию детенышей кроколисков доверчивым детишкам. А кроколиски звери дикие, многие разбежались и теперь прячутся в городской канализации.$b$bБери-ка свою лучшую удочку и забрасывай леску в Штормграде или Оргриммаре. Притащи мне одну из этих тварюг. Уж очень посмотреть хочется.','Принесите старине Барло детеныша кроколиска. Он рыбачит на озере Силмир на северо-востоке от Шаттрата.','Вернитесь к старине Барло на озеро Силмир, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кроколиски в городе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $gпарень:девчушка;. Славно, что $Gостановился:остановилась; поболтать со старичком, у которого дома не все ладно.$b$bТут недавно один странствующий торговец продал партию детенышей кроколисков доверчивым детишкам. А кроколиски звери дикие, многие разбежались и теперь прячутся в городской канализации.$b$bБери-ка свою лучшую удочку и забрасывай леску в Штормграде или Оргриммаре. Притащи мне одну из этих тварюг. Уж очень посмотреть хочется.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите старине Барло детеныша кроколиска. Он рыбачит на озере Силмир на северо-востоке от Шаттрата.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старине Барло на озеро Силмир, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11666,'Поймай бандюгу','Наверное, тебе приходилось слыхать о золотом ерше – их полно в реках леса Тероккар, и жрецы любят ими полакомиться. Но вот об одной рыбине ты вряд ли $Gслыхал:слыхала; – о ерше чернопером.$b$bЭта рыба славится хитростью, и поймать ее нелегко. Приходится подсекать в последний момент, а то объест наживку – и поминай как звали.$b$bЗабрось удочку в одну из рек Тероккара и принеси мне черноперого ерша. В озерах ловить – пустое дело, он только в проточной воде живет.','Поймайте черноперого ерша и принесите его старине Барло. Он рыбачит к северо-востоку от Шаттрата на озере Силмир.','Вернитесь к старине Барло на озеро Силмир, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поймай бандюгу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наверное, тебе приходилось слыхать о золотом ерше – их полно в реках леса Тероккар, и жрецы любят ими полакомиться. Но вот об одной рыбине ты вряд ли $Gслыхал:слыхала; – о ерше чернопером.$b$bЭта рыба славится хитростью, и поймать ее нелегко. Приходится подсекать в последний момент, а то объест наживку – и поминай как звали.$b$bЗабрось удочку в одну из рек Тероккара и принеси мне черноперого ерша. В озерах ловить – пустое дело, он только в проточной воде живет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте черноперого ерша и принесите его старине Барло. Он рыбачит к северо-востоку от Шаттрата на озере Силмир.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старине Барло на озеро Силмир, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11667,'Та самая рыбка','Ильная рыба Фиглюстера – невероятная юркая придонная рыбка. Она водится в водах Награнда. Эти рыбы всю свою жизнь растут и так просто поймать себя не дадут.$b$bМного лет назад я поймал самую большую в мире ильную рыбу... ну, по моему мнению... но она перекусила леску и удрала.$b$b$GРыбак:Рыбачка; твоего уровня знает, что делать – твоя добыча ждет тебя в озерах Награнда.','Поймайте величайшую ильную рыбу в мире и принесите ее старине Барло. Он рыбачит к северо-востоку от Шаттрата на озере Силмир.','Она! Этот шрам я везде узнаю.$B$BНо, честно говоря, я думал, что она будет... побольше. Ладно. Отпущу-ка я ее и попытаюсь выловить в другой раз.','Вернитесь к старине Барло на озеро Силмир, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Та самая рыбка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ильная рыба Фиглюстера – невероятная юркая придонная рыбка. Она водится в водах Награнда. Эти рыбы всю свою жизнь растут и так просто поймать себя не дадут.$b$bМного лет назад я поймал самую большую в мире ильную рыбу... ну, по моему мнению... но она перекусила леску и удрала.$b$b$GРыбак:Рыбачка; твоего уровня знает, что делать – твоя добыча ждет тебя в озерах Награнда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте величайшую ильную рыбу в мире и принесите ее старине Барло. Он рыбачит к северо-востоку от Шаттрата на озере Силмир.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Она! Этот шрам я везде узнаю.$B$BНо, честно говоря, я думал, что она будет... побольше. Ладно. Отпущу-ка я ее и попытаюсь выловить в другой раз.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старине Барло на озеро Силмир, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11668,'Ловить креветок – это не жук чихнул','В озерах Зангартопи водится много крупной рыбы. Как думаешь, кого они там жрут?$b$bКреветок. Гигантских пресноводных креветок. Скалл говорил, что из креветок можно приготовить просто необъятное количество блюд.$b$bНо креветки слишком маленькие, их на крючок не наловишь. Так что тут надо применить одну уловку: распотроши колючеусую форель – и найдешь в ней пару креветок, если повезет.','Принесите 10 гигантских пресноводных креветок старине Барло. Он рыбачит на озере Силмир на северо-востоке от Шаттрата.','Ты и с крючком, и с ножом славно управляешься. Давай-ка сюда этих миленьких креветочек, и я дам тебе попробовать блюдо.','Вернитесь к старине Барло на озеро Силмир, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ловить креветок – это не жук чихнул',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В озерах Зангартопи водится много крупной рыбы. Как думаешь, кого они там жрут?$b$bКреветок. Гигантских пресноводных креветок. Скалл говорил, что из креветок можно приготовить просто необъятное количество блюд.$b$bНо креветки слишком маленькие, их на крючок не наловишь. Так что тут надо применить одну уловку: распотроши колючеусую форель – и найдешь в ней пару креветок, если повезет.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 10 гигантских пресноводных креветок старине Барло. Он рыбачит на озере Силмир на северо-востоке от Шаттрата.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты и с крючком, и с ножом славно управляешься. Давай-ка сюда этих миленьких креветочек, и я дам тебе попробовать блюдо.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старине Барло на озеро Силмир, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11669,'Филе сквернокровного луциана','Принесите старине Барло чудовищного сквернокровного луциана. Старик удит рыбу к северо-востоку от Шаттрата в озере Силмир.','Эти сквернокровики – чудо эволюции. Выживает в любых водах, даже в лаве, и единственным природным врагом этой рыбки является рыбак.$B$BНу, как, удалось рыбку поймать?','Вернитесь к старине Барло на озеро Силмир, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Филе сквернокровного луциана',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите старине Барло чудовищного сквернокровного луциана. Старик удит рыбу к северо-востоку от Шаттрата в озере Силмир.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эти сквернокровики – чудо эволюции. Выживает в любых водах, даже в лаве, и единственным природным врагом этой рыбки является рыбак.$B$BНу, как, удалось рыбку поймать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старине Барло на озеро Силмир, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11670,'Это были орки, честно!','Из всех этих одежек, что тебе удалось... э-э... раздобыть, я соорудила личину орка Песни Войны. Мне пришла в голову гениальная идея объединить это с кое-каким барахлом, завалявшимся с последнего Тыквовина, так, чтобы уж наверняка никто ни о чем не догадался!$b$bВот в этом мешке – личина и знамя, которое тебе удалось вернуть. Спустись в недра Магмота и убей вождя магнатавров, Магмотрегара.$b$bЕсли ты хочешь убедить их обратить свой гнев на орков Песни Войны, тебе нужно поднять это знамя, будучи в личине.','Переоденьтесь орком Песни Войны и водрузите знамя клана Песни Войны над трупом Магмотрегара. Затем вернитесь вместе с личиной к Умейке Шестеркрут на взлетную полосу Выкрутеня.','Ура-ура, все получилось!$B$BЛадненько, пусть теперь эти жуткие магнатавры и их прихвостни-снобольды сцепятся с Ордой!$B$BДаже не знаю, как тебя и отблагодарить, $N!','Ну, как? Ты $Gсделал:сделала; грязное дело и $Gподставил:подставила; орков с заставы Бор\'горока?','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Это были орки, честно!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из всех этих одежек, что тебе удалось... э-э... раздобыть, я соорудила личину орка Песни Войны. Мне пришла в голову гениальная идея объединить это с кое-каким барахлом, завалявшимся с последнего Тыквовина, так, чтобы уж наверняка никто ни о чем не догадался!$b$bВот в этом мешке – личина и знамя, которое тебе удалось вернуть. Спустись в недра Магмота и убей вождя магнатавров, Магмотрегара.$b$bЕсли ты хочешь убедить их обратить свой гнев на орков Песни Войны, тебе нужно поднять это знамя, будучи в личине.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Переоденьтесь орком Песни Войны и водрузите знамя клана Песни Войны над трупом Магмотрегара. Затем вернитесь вместе с личиной к Умейке Шестеркрут на взлетную полосу Выкрутеня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ура-ура, все получилось!$B$BЛадненько, пусть теперь эти жуткие магнатавры и их прихвостни-снобольды сцепятся с Ордой!$B$BДаже не знаю, как тебя и отблагодарить, $N!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну, как? Ты $Gсделал:сделала; грязное дело и $Gподставил:подставила; орков с заставы Бор\'горока?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11671,'Наперегонки со временем','Так значит, это правда. Она у них.$B$BЯсно, что надо сделать, |3-6($r). Она БУДЕТ спасена.$B$BЯ должен оставаться здесь и помочь в подготовке спасения. Я позову тебя снова – на сей раз, чтобы добыть ключ от тюрьмы. Все, что мы знаем о личности этой Салранд, так это то, что ей нельзя повредить до тех пор, пока действует ее щит.$B$BМы сделали специальное взрывчатое вещество, которое должно снять ее защиту, позволив тебе сделать то, что должно. Возвращайся ко мне, когда раздобудешь ключ.$B$BПоспеши, $n. Леди Эванор страдает!','По поручению Донатана с Янтарной гряды уничтожьте щит в Берилловом лагере, воспользовавшись разрушителем Бериллового щита. Затем сразите Салранд и заберите найденный у нее ключ.','Тебе удалось добыть ключ Салранд?','Вернитесь к библиотекарю Донатану на Янтарную гряду, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наперегонки со временем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так значит, это правда. Она у них.$B$BЯсно, что надо сделать, |3-6($r). Она БУДЕТ спасена.$B$BЯ должен оставаться здесь и помочь в подготовке спасения. Я позову тебя снова – на сей раз, чтобы добыть ключ от тюрьмы. Все, что мы знаем о личности этой Салранд, так это то, что ей нельзя повредить до тех пор, пока действует ее щит.$B$BМы сделали специальное взрывчатое вещество, которое должно снять ее защиту, позволив тебе сделать то, что должно. Возвращайся ко мне, когда раздобудешь ключ.$B$BПоспеши, $n. Леди Эванор страдает!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Донатана с Янтарной гряды уничтожьте щит в Берилловом лагере, воспользовавшись разрушителем Бериллового щита. Затем сразите Салранд и заберите найденный у нее ключ.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось добыть ключ Салранд?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к библиотекарю Донатану на Янтарную гряду, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (11672,'День зачисления','$GПришел:Пришла; зачисляться на службу, так? В обычном случае тебе пришлось бы встать в общую очередь, как всем новобранцам. В обычном случае тебе не повезло бы, потому что пропала книга регистрации новобранцев, а я не могу никого принять, пока не будет новых книг.$B$BК счастью для тебя, $n, я слышал о тебе и о твоих деяниях в Запределье. По правде говоря, ты – на порядок лучше этих бедолаг. Торчать в обороне – не для тебя.$B$BИди к казармам и поговори с генералом Арлосом. Он будет более чем доволен встретиться с такой масштабной личностью, как ты.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','День зачисления',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$GПришел:Пришла; зачисляться на службу, так? В обычном случае тебе пришлось бы встать в общую очередь, как всем новобранцам. В обычном случае тебе не повезло бы, потому что пропала книга регистрации новобранцев, а я не могу никого принять, пока не будет новых книг.$B$BК счастью для тебя, $n, я слышал о тебе и о твоих деяниях в Запределье. По правде говоря, ты – на порядок лучше этих бедолаг. Торчать в обороне – не для тебя.$B$BИди к казармам и поговори с генералом Арлосом. Он будет более чем доволен встретиться с такой масштабной личностью, как ты.',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11673,'Вытащите меня отсюда!','А я знал, что за мной рано или поздно кого-нибудь пришлют... разумеется, скорее поздно, чем рано.$b$bЯ прибыл сюда на переговоры со снобольдами, но их главный шаман, Каганишу, решил, что из меня выйдет лакомый кусочек для их Магмотрегара...$b$bПогодите... То есть как? Вас никто не присылал?!$b$bТак что, про меня просто забыли?!!$b$bНу ладно. Главное, что вы здесь.$b$bРазбейте немедленно эту цепь и идемте обратно к взлетной полосе. И можете сказать Выкрутеню, что я благополучно вернулся обратно.$b$bЕсли он, конечно, помнит, кто я такой.','Проводите Бонкера Тумблевольта в безопасное место и сообщите об этом Выкрутеню Разгоняйло со взлетной полосы Выкрутеня.','А? Что?$B$BБонкер? Какой Бонкер?$B$BНе знаю никакого Бонкера, но поверю вам на слово. Если вы спасли кого-то из ямы Магмота, вы, несомненно, заслуживаете награды.$B$BДайте взглянуть, у меня тут как раз валялась подходящая штуковина…','Что вы говорите?','Бонкер Тумблевольт теперь в безопасном месте.','Вернитесь к Выкрутеню Разгоняйло на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вытащите меня отсюда!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','А я знал, что за мной рано или поздно кого-нибудь пришлют... разумеется, скорее поздно, чем рано.$b$bЯ прибыл сюда на переговоры со снобольдами, но их главный шаман, Каганишу, решил, что из меня выйдет лакомый кусочек для их Магмотрегара...$b$bПогодите... То есть как? Вас никто не присылал?!$b$bТак что, про меня просто забыли?!!$b$bНу ладно. Главное, что вы здесь.$b$bРазбейте немедленно эту цепь и идемте обратно к взлетной полосе. И можете сказать Выкрутеню, что я благополучно вернулся обратно.$b$bЕсли он, конечно, помнит, кто я такой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Проводите Бонкера Тумблевольта в безопасное место и сообщите об этом Выкрутеню Разгоняйло со взлетной полосы Выкрутеня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','А? Что?$B$BБонкер? Какой Бонкер?$B$BНе знаю никакого Бонкера, но поверю вам на слово. Если вы спасли кого-то из ямы Магмота, вы, несомненно, заслуживаете награды.$B$BДайте взглянуть, у меня тут как раз валялась подходящая штуковина…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что вы говорите?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Бонкер Тумблевольт теперь в безопасном месте.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Выкрутеню Разгоняйло на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11674,'Ведунья Высокий Холм пропала!','В наших землях творятся все новые таинственные дела. Одна из наших ведуний, Высокий Холм, опрометчиво отправилась на север в сопровождении всего лишь одного выносливого гонца, чтобы выяснить, что происходит близ Келий Смерти.$b$bЧто за Кельи, говоришь? Это место, священное для магнатавров. Они уходят туда в старости, чтобы умереть. Так вот, Высокий Холм видела, как что-то упало с неба несколько дней тому назад.$b$bЕсли ты друг таунка, поди и отыщи ее. Она упряма, но не настолько, чтобы отвергнуть твою помощь.','Найдите ведунью Высокий Холм близ Келий Смерти.','Ну что, тотем заряжен?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ведунья Высокий Холм пропала!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В наших землях творятся все новые таинственные дела. Одна из наших ведуний, Высокий Холм, опрометчиво отправилась на север в сопровождении всего лишь одного выносливого гонца, чтобы выяснить, что происходит близ Келий Смерти.$b$bЧто за Кельи, говоришь? Это место, священное для магнатавров. Они уходят туда в старости, чтобы умереть. Так вот, Высокий Холм видела, как что-то упало с неба несколько дней тому назад.$b$bЕсли ты друг таунка, поди и отыщи ее. Она упряма, но не настолько, чтобы отвергнуть твою помощь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите ведунью Высокий Холм близ Келий Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, тотем заряжен?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11675,'Достойная смерть','Магнатавры в Кельях Смерти страдают от чумы. Мы должны выяснить причину заражения, но сначала нужно избавить их от страданий.$B$B$r, тебе нужно пойти на север, подняться по склонам, что впереди, и уничтожить как можно больше несчастных созданий.','Уничтожьте 10 чумных магнатавров и возвращайтесь к ведунье Высокий Холм, которая ждет вас к югу от Келий Смерти.','Я по-прежнему вижу, что их много – так что, по-моему, ты не приложил достаточных стараний. Настоящий |3-6($C) выполнил бы порученное полностью.','Вернитесь к ведунье Высокий Холм в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Достойная смерть',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Магнатавры в Кельях Смерти страдают от чумы. Мы должны выяснить причину заражения, но сначала нужно избавить их от страданий.$B$B$r, тебе нужно пойти на север, подняться по склонам, что впереди, и уничтожить как можно больше несчастных созданий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 10 чумных магнатавров и возвращайтесь к ведунье Высокий Холм, которая ждет вас к югу от Келий Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Я по-прежнему вижу, что их много – так что, по-моему, ты не приложил достаточных стараний. Настоящий |3-6($C) выполнил бы порученное полностью.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведунье Высокий Холм в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11676,'Наконец-то свобода!','Солдат, которых они не убили, держат в клетках, разбросанных по этому участку. Нам удалось украсть несколько ключей, но подобраться к пленным поближе так и не вышло: нас тут же атакуют.$b$bНам нужны твои "дарования", чтобы раздобыть все ключи и освободить пленников. Вышиби мозги некролордам и аберрациям и забери у них ключи. Открой ключами клетки и освободи пленников Плети.','Освободить 5 узников Плети по просьбе тенелова Канариуса с заставы у ферм Песни Войны.','Мне нужно больше времени! Не подпускай этих свиней к моим кодо!','Вернитесь к тенелову Канариусу на Заставу у ферм Песни войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Наконец-то свобода!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Солдат, которых они не убили, держат в клетках, разбросанных по этому участку. Нам удалось украсть несколько ключей, но подобраться к пленным поближе так и не вышло: нас тут же атакуют.$b$bНам нужны твои "дарования", чтобы раздобыть все ключи и освободить пленников. Вышиби мозги некролордам и аберрациям и забери у них ключи. Открой ключами клетки и освободи пленников Плети.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Освободить 5 узников Плети по просьбе тенелова Канариуса с заставы у ферм Песни Войны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно больше времени! Не подпускай этих свиней к моим кодо!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тенелову Канариусу на Заставу у ферм Песни войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11677,'Остановить чуму!','Я уверена, что чуму вызывает нечто, находящееся в тамошних пещерах.$b$b$C, возьми эти семена. Я обычно использую их как оберег против Плети, но, быть может, они помогут избавиться и от той напасти, что обитает в Кельях.$b$bОтыщи источник заразы и брось туда эти семена.','Используйте очистительные семена ведуньи Высокий Холм у чумного котла в Кельях Смерти, чтобы нейтрализовать его, по просьбе ведуньи Высокий Холм, стоящей к югу от Келий Смерти.','Входи в любую пещеру, |3-6($C). Быстрее, используй семена, чтобы положить конец чуме!','Вернитесь к ведунье Высокий Холм в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Остановить чуму!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уверена, что чуму вызывает нечто, находящееся в тамошних пещерах.$b$b$C, возьми эти семена. Я обычно использую их как оберег против Плети, но, быть может, они помогут избавиться и от той напасти, что обитает в Кельях.$b$bОтыщи источник заразы и брось туда эти семена.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте очистительные семена ведуньи Высокий Холм у чумного котла в Кельях Смерти, чтобы нейтрализовать его, по просьбе ведуньи Высокий Холм, стоящей к югу от Келий Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Входи в любую пещеру, |3-6($C). Быстрее, используй семена, чтобы положить конец чуме!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведунье Высокий Холм в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11678,'Поиски Торчащего Рога','Торчащий Рог давно уже должен был вернуться!$b$bЕще одна причина, по которой мы пришли сюда – это необходимость разведать, что это за сооружение на западе, принадлежащее Плети, свалилось с неба. А Торчащий Рог нетерпелив, и, скорее всего, попал в беду...$b$bПрошу тебя, $n, сходи туда и найди его.','Найти выносливого гонца Торчащего Рога в Талрамасе.','Вряд ли тебе удалось уничтожить так много созданий Плети за столь короткое время!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски Торчащего Рога',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Торчащий Рог давно уже должен был вернуться!$b$bЕще одна причина, по которой мы пришли сюда – это необходимость разведать, что это за сооружение на западе, принадлежащее Плети, свалилось с неба. А Торчащий Рог нетерпелив, и, скорее всего, попал в беду...$b$bПрошу тебя, $n, сходи туда и найди его.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найти выносливого гонца Торчащего Рога в Талрамасе.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вряд ли тебе удалось уничтожить так много созданий Плети за столь короткое время!',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11679,'Воссоздание ключа','Задержки, задержки... Это единственное, чего мы никак не можем позволить себе именно сейчас!$B$BХотя мне очень не хотелось бы беспокоить лорда Сурристраза, он и только он способен спасти нашу дорогую Эванор.$B$BПринеси ему фрагменты ключа и надейся, что он будет в хорошем расположении духа.$B$BИ не задерживайся, |3-6($c), наша штурмовая бригада уже готова.','По поручению Донатана поговорите с Сурристразом на Янтарной гряде.','Вернитесь к Сурристразу на Янтарную гряду, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воссоздание ключа',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Задержки, задержки... Это единственное, чего мы никак не можем позволить себе именно сейчас!$B$BХотя мне очень не хотелось бы беспокоить лорда Сурристраза, он и только он способен спасти нашу дорогую Эванор.$B$BПринеси ему фрагменты ключа и надейся, что он будет в хорошем расположении духа.$B$BИ не задерживайся, |3-6($c), наша штурмовая бригада уже готова.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По поручению Донатана поговорите с Сурристразом на Янтарной гряде.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Сурристразу на Янтарную гряду, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11680,'Полетаем?','Ключ воссоздан.$B$BА теперь внемли моему совету, |3-6($r). Добейся успеха или умри... потому что если хоть одна чешуйка упадет с любого из моих драконов, отвечать за это будешь лично ты. $B$B$gСвободен:Свободна;.','Отдайте ключ Салранд боевому магу Анзиму, когда будете готовы освободить Эванор.','Вот он! Ключ – наш!','Ты смеешь приблизиться ко мне, смертное существо?\n\nРади твоих еще нерожденных детей – молись, чтобы твое дело стоило моего беспокойства.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Полетаем?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ключ воссоздан.$B$BА теперь внемли моему совету, |3-6($r). Добейся успеха или умри... потому что если хоть одна чешуйка упадет с любого из моих драконов, отвечать за это будешь лично ты. $B$B$gСвободен:Свободна;.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отдайте ключ Салранд боевому магу Анзиму, когда будете готовы освободить Эванор.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот он! Ключ – наш!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты смеешь приблизиться ко мне, смертное существо?\n\nРади твоих еще нерожденных детей – молись, чтобы твое дело стоило моего беспокойства.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11681,'Спасение Эванор','Наконец-то мы атакуем!$b$bКак только очистим платформу, я использую ключ.$b$bА вы позаботьтесь о том, чтобы леди Эванор осталась цела и невредима после освобождения.$b$bВперед! Скорей!','Отправляйтесь с боевыми магами и освободите леди Эванор из Бериллового лагеря по просьбе Анзима с Янтарной гряды. Затем явитесь к ней в башню магов на Янтарной гряде.','Ты смеешь приблизиться ко мне, смертное существо?\n\nРади твоих еще нерожденных детей – молись, чтобы твое дело стоило моего беспокойства.','Поговорите с Леди Эванор на Янтарной гряде, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Спасение Эванор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Наконец-то мы атакуем!$b$bКак только очистим платформу, я использую ключ.$b$bА вы позаботьтесь о том, чтобы леди Эванор осталась цела и невредима после освобождения.$b$bВперед! Скорей!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь с боевыми магами и освободите леди Эванор из Бериллового лагеря по просьбе Анзима с Янтарной гряды. Затем явитесь к ней в башню магов на Янтарной гряде.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты смеешь приблизиться ко мне, смертное существо?\n\nРади твоих еще нерожденных детей – молись, чтобы твое дело стоило моего беспокойства.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Леди Эванор на Янтарной гряде, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11682,'Беседа с драконом','Мне известно о твоих деяниях, $n. Еще раз благодарю тебя.$b$bЧто касается местной угрозы, мы уже узнали от них все, что было нужно. Вскоре с ними будет покончено. Однако впереди более важные дела...$b$bТы $gнужен:нужна; Азероту. Землям к западу отсюда грозит серьезная опасность.$b$bПодробности тебе расскажет лорд Сурристраз. Тебе нужно срочно поговорить с ним.$b$bУдачи тебе, друг Даларана!','Поговорите с Сурристразом по приказу леди Эванор с Янтарной гряды.','Ты смеешь приблизиться ко мне, смертное существо?\n\nРади твоих еще нерожденных детей – молись, чтобы твое дело стоило моего беспокойства.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Беседа с драконом',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне известно о твоих деяниях, $n. Еще раз благодарю тебя.$b$bЧто касается местной угрозы, мы уже узнали от них все, что было нужно. Вскоре с ними будет покончено. Однако впереди более важные дела...$b$bТы $gнужен:нужна; Азероту. Землям к западу отсюда грозит серьезная опасность.$b$bПодробности тебе расскажет лорд Сурристраз. Тебе нужно срочно поговорить с ним.$b$bУдачи тебе, друг Даларана!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Сурристразом по приказу леди Эванор с Янтарной гряды.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты смеешь приблизиться ко мне, смертное существо?\n\nРади твоих еще нерожденных детей – молись, чтобы твое дело стоило моего беспокойства.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11683,'Упавший некрополь','Упавший некрополь к западу отсюда наверняка по-прежнему кишит созданиями Плети.$B$BБудешь рядом с Талрамасом, |3-6($r), пожалуйста, разберись с любыми прислужниками Короля-лича, которых только найдешь там и в окружающих место его падения прудах.','Уничтожьте 20 созданий Плети любого вида в Талрамасе и Гнойных прудах. Затем возвращайтесь к ведунье Высокий Холм, находящейся к югу от Келий Смерти.','Вряд ли тебе удалось уничтожить так много созданий Плети за столь короткое время!','Вернитесь к ведунье Высокий Холм в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Упавший некрополь',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Упавший некрополь к западу отсюда наверняка по-прежнему кишит созданиями Плети.$B$BБудешь рядом с Талрамасом, |3-6($r), пожалуйста, разберись с любыми прислужниками Короля-лича, которых только найдешь там и в окружающих место его падения прудах.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 20 созданий Плети любого вида в Талрамасе и Гнойных прудах. Затем возвращайтесь к ведунье Высокий Холм, находящейся к югу от Келий Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вряд ли тебе удалось уничтожить так много созданий Плети за столь короткое время!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведунье Высокий Холм в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11684,'Исследование воронок','Чувствуешь, как дрожит почва?$B$BЭто нерубы из Плети движутся глубоко под землей. Они показались к юго-западу отсюда, на Поле Гейзеров, и нападают на патрули, высланные вождем Зимней Стужей.$B$B<Старейшина таунка передает вам потрепанную карту.>$B$BМожет быть, одиночка сможет добиться успеха там, где потерпели неудачу патрули. Возьми с собой на Поле Гейзеров эту карту и отметь на ней воронки, через которые вылезают нерубы.','Ну что, все воронки отмечены на карте?','Вернитесь к Великому Отцу Махану в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование воронок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Чувствуешь, как дрожит почва?$B$BЭто нерубы из Плети движутся глубоко под землей. Они показались к юго-западу отсюда, на Поле Гейзеров, и нападают на патрули, высланные вождем Зимней Стужей.$B$B<Старейшина таунка передает вам потрепанную карту.>$B$BМожет быть, одиночка сможет добиться успеха там, где потерпели неудачу патрули. Возьми с собой на Поле Гейзеров эту карту и отметь на ней воронки, через которые вылезают нерубы.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, все воронки отмечены на карте?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Великому Отцу Махану в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11685,'Сердце стихий','Теперь, когда мы точно знаем местоположение нерубских воронок, мы можем их обрушить, чтобы остановить наступление Плети. Укротитель ветра Бара знает способ подчинить себе элементалей, чтобы уничтожить туннели, которыми пользуются воины Неруба. Но ей потребуется твоя помощь.$b$bК юго-востоку от деревни, близ побережья за Студеным пределом, найдешь местность, где владычествуют замороженные земляные элементали. Укротителю ветра Баре потребуются сердца этих стихий.','Принесите 5 сердец элементалей укротителю ветра Баре в деревне Таунка\'ле.','Этого должно хватить, чтобы создать основу для могущественного элементаля, однако одного камня недостаточно, чтобы вдохнуть в него жизнь…','Великий Отец Махан говорит мне, что ты согласился помочь обрушить туннели...','Вернитесь к укротителю ветра Баре в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сердце стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда мы точно знаем местоположение нерубских воронок, мы можем их обрушить, чтобы остановить наступление Плети. Укротитель ветра Бара знает способ подчинить себе элементалей, чтобы уничтожить туннели, которыми пользуются воины Неруба. Но ей потребуется твоя помощь.$b$bК юго-востоку от деревни, близ побережья за Студеным пределом, найдешь местность, где владычествуют замороженные земляные элементали. Укротителю ветра Баре потребуются сердца этих стихий.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 сердец элементалей укротителю ветра Баре в деревне Таунка\'ле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Этого должно хватить, чтобы создать основу для могущественного элементаля, однако одного камня недостаточно, чтобы вдохнуть в него жизнь…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Великий Отец Махан говорит мне, что ты согласился помочь обрушить туннели...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю ветра Баре в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11686,'Фермы Песни Войны','Мне нужно больше времени! Не подпускай этих свиней к моим кодо!','Вернитесь к тенелову Икорису на Заставу у ферм Песни войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Фермы Песни Войны',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно больше времени! Не подпускай этих свиней к моим кодо!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к тенелову Икорису на Заставу у ферм Песни войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11687,'Доктор и Лич-Лорд','Нужно... убить... двоих...$b$bДоктор и... лич-лорд... они наверху. Найди их... убей... пока...$b$bПока не поздно...','Убейте доктора Щербохмыла и Лич-Лорда Хладолюта. Затем вернитесь к ведунье Высокий Холм, которая ждет вас к югу от Келий Смерти.','Вряд ли тебе удалось уничтожить так много созданий Плети за столь короткое время!','Вернитесь к ведунье Высокий Холм в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доктор и Лич-Лорд',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно... убить... двоих...$b$bДоктор и... лич-лорд... они наверху. Найди их... убей... пока...$b$bПока не поздно...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте доктора Щербохмыла и Лич-Лорда Хладолюта. Затем вернитесь к ведунье Высокий Холм, которая ждет вас к югу от Келий Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вряд ли тебе удалось уничтожить так много созданий Плети за столь короткое время!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведунье Высокий Холм в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11688,'Проклятые грязные свиньи','Только погляди на них! Мои красавцы кодо беспомощны и не в состоянии защититься от этих грязных свиней! Мне нужно, чтобы ты $gпомог:помогла; мне выиграть время, |3-6($r). Я думаю, что смогу вылечить кодо от их болезни, но нужно держать этих неживых кабанов подальше от них, а то лечить будет уже некого!$B$BИди и отправь хряков в землю навечно!','По просьбе фермера Торпа с заставы у ферм Песни Войны убейте 10 неживых кабанов.','Мне нужно больше времени! Не подпускай этих свиней к моим кодо!','Вернитесь к фермеру Торпу на Заставу у ферм Песни войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Проклятые грязные свиньи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Только погляди на них! Мои красавцы кодо беспомощны и не в состоянии защититься от этих грязных свиней! Мне нужно, чтобы ты $gпомог:помогла; мне выиграть время, |3-6($r). Я думаю, что смогу вылечить кодо от их болезни, но нужно держать этих неживых кабанов подальше от них, а то лечить будет уже некого!$B$BИди и отправь хряков в землю навечно!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе фермера Торпа с заставы у ферм Песни Войны убейте 10 неживых кабанов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мне нужно больше времени! Не подпускай этих свиней к моим кодо!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Торпу на Заставу у ферм Песни войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11689,'Вестник печали') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вестник печали',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11690,'Верни их живыми!','Вот уздечка, $n. Внутри удил спрятан небольшой контейнер с лекарством. Это лекарство исцелит кодо, как только животное прикусит удила. Вылечив кодо, его нужно привести домой. На нем можно будет ехать верхом, но животное будет слабым после болезни, так что ехать надо медленно.$b$bПриведи моих малюток домой, $n!$b$bДа, и последнее: на все про все у тебя десять минут! После этого противоядие внутри удил потеряет силу.','Спасите 8 зараженных кодо по просьбе фермера Торпа с Заставы у ферм Песни Войны.','Убери их с полей, кишащих Плетью!','Вернитесь к фермеру Торпу на Заставу у ферм Песни войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Верни их живыми!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Вот уздечка, $n. Внутри удил спрятан небольшой контейнер с лекарством. Это лекарство исцелит кодо, как только животное прикусит удила. Вылечив кодо, его нужно привести домой. На нем можно будет ехать верхом, но животное будет слабым после болезни, так что ехать надо медленно.$b$bПриведи моих малюток домой, $n!$b$bДа, и последнее: на все про все у тебя десять минут! После этого противоядие внутри удил потеряет силу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Спасите 8 зараженных кодо по просьбе фермера Торпа с Заставы у ферм Песни Войны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Убери их с полей, кишащих Плетью!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к фермеру Торпу на Заставу у ферм Песни войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11691,'Призовите Ахуна','Мы с моими шаманами собрали все наши силы для борьбы с Повелителем Холода. $n, быть тебе $Gпоборником:поборницей; Матери Земли.$B$BВозьми этот Тотем магмы. Установи его напротив Камня Льда, к северо-востоку от него. Ахун при помощи этого камня тянет силу. Мы надеемся, что тотем разрушит камень и разорвет связь с тем миром, где затаился этот элементаль.$B$BЕсли судьба будет к нам благосклонна, то мы, наверное, сумеем победить его.$B$BГотовься к битве, $n. Если придется сражаться с Ахуном, то ярость его будет неизмерима.','Принесите Тотем магмы Служителей Земли к Камню Льда.','Тотем магмы распадается на три отдельных огня, когда он приближается к ледяному камню. Камень мерцает, потом исчезает...','Вернитесь к Камню Льда на Холм Дарроу, что в Предгорьях Хилсбрада.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Призовите Ахуна',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с моими шаманами собрали все наши силы для борьбы с Повелителем Холода. $n, быть тебе $Gпоборником:поборницей; Матери Земли.$B$BВозьми этот Тотем магмы. Установи его напротив Камня Льда, к северо-востоку от него. Ахун при помощи этого камня тянет силу. Мы надеемся, что тотем разрушит камень и разорвет связь с тем миром, где затаился этот элементаль.$B$BЕсли судьба будет к нам благосклонна, то мы, наверное, сумеем победить его.$B$BГотовься к битве, $n. Если придется сражаться с Ахуном, то ярость его будет неизмерима.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Тотем магмы Служителей Земли к Камню Льда.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Тотем магмы распадается на три отдельных огня, когда он приближается к ледяному камню. Камень мерцает, потом исчезает...',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Камню Льда на Холм Дарроу, что в Предгорьях Хилсбрада.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11692,'В поисках Бикси','У тебя репутация настоящего героя. А у меня опять проблема!$B$BМой начальник, Тинки, отправился с Бикси Винтодер на восток, а я не могу добиться, чтобы выхлоп на этой штуке шел как следует! Тинки – единственный, кто может это поправить, а нам обязательно нужно, чтобы все на сто процентов работало.$B$BКак думаешь, тебе удалось бы их найти? Бикси говорила что-то о следовании за какими-то старыми магнатаврами к месту под названием Кельи Смерти.$B$BПодозреваю, там-то ты их и найдешь.$B$BМожешь отправиться туда, поговорив с Карой Тризведкой у взлетной полосы.','Как и просил вас Мордл Шестеренок, отправляйтесь на поиски Бикси Винтодер к югу от Келий Смерти.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках Бикси',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У тебя репутация настоящего героя. А у меня опять проблема!$B$BМой начальник, Тинки, отправился с Бикси Винтодер на восток, а я не могу добиться, чтобы выхлоп на этой штуке шел как следует! Тинки – единственный, кто может это поправить, а нам обязательно нужно, чтобы все на сто процентов работало.$B$BКак думаешь, тебе удалось бы их найти? Бикси говорила что-то о следовании за какими-то старыми магнатаврами к месту под названием Кельи Смерти.$B$BПодозреваю, там-то ты их и найдешь.$B$BМожешь отправиться туда, поговорив с Карой Тризведкой у взлетной полосы.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Как и просил вас Мордл Шестеренок, отправляйтесь на поиски Бикси Винтодер к югу от Келий Смерти.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11693,'Только не чумной магнатавр!','Мы с Тинки пришли сюда, выслеживая старого магнатавра. Похоже, в эти пещеры они сходятся умирать.$b$bРазумеется, мы и понятия не имели, что, входя сюда, они заражаются какой-то болезнью. Нельзя допустить, чтобы заразные твари бродили на свободе. Это нездорово!$b$bПослушайте, может, вы уложите несколько штук этих тварей, пока я соображу, что нам делать дальше?','Убейте 10 чумных магнатавров и возвращайтесь к Бикси Винтодер к югу от Келий Смерти.','Вы отлично потрудились, но на вашем месте я бы приняла душ при первой же возможности!$B$BНу, а теперь давайте разберемся с проблемой всерьез.','Что-то маловато чумных магнатавров вы перебили, $C!$B$BМожет, уложите еще несколько штук, а?','Вернитесь к Бикси Винтодер в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Только не чумной магнатавр!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы с Тинки пришли сюда, выслеживая старого магнатавра. Похоже, в эти пещеры они сходятся умирать.$b$bРазумеется, мы и понятия не имели, что, входя сюда, они заражаются какой-то болезнью. Нельзя допустить, чтобы заразные твари бродили на свободе. Это нездорово!$b$bПослушайте, может, вы уложите несколько штук этих тварей, пока я соображу, что нам делать дальше?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 чумных магнатавров и возвращайтесь к Бикси Винтодер к югу от Келий Смерти.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы отлично потрудились, но на вашем месте я бы приняла душ при первой же возможности!$B$BНу, а теперь давайте разберемся с проблемой всерьез.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что-то маловато чумных магнатавров вы перебили, $C!$B$BМожет, уложите еще несколько штук, а?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бикси Винтодер в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11694,'В пещерах что-то происходит...','Пока ты там с этими чумными зверьми $gразбирался:разбиралась;, мне удалось заглянуть в те пещеры наверху.$B$BОказывается, там засели сектанты, которые и наводят чуму на зверей!$B$BОни готовят в котле какой-то ядовитый отвар. У меня есть порошок, который я обычно использую в качестве противоядия, и я подмешала к нему еще кое-что. Я думаю, это должно нейтрализовать отраву в котле!$B$BСходи с порошком в одну из пещер и посмотри, сработает ли.','По просьбе Бикси Винтодер, что прячется к югу от Келий Смерти, всыпьте лечебный порошок Бикси в чумной котел в Кельях Смерти, чтобы нейтрализовать отвар в нем.','Я знала, что у тебя получится. А теперь – есть кое-что еще, о чем я хотела бы тебя попросить.','Время не ждет, $C. Вот уж чего нам точно не нужно - так это встреча с чумным магнатавром.$B$BОни и здоровые-то - не подарок!','Вернитесь к Бикси Винтодер в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В пещерах что-то происходит...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Пока ты там с этими чумными зверьми $gразбирался:разбиралась;, мне удалось заглянуть в те пещеры наверху.$B$BОказывается, там засели сектанты, которые и наводят чуму на зверей!$B$BОни готовят в котле какой-то ядовитый отвар. У меня есть порошок, который я обычно использую в качестве противоядия, и я подмешала к нему еще кое-что. Я думаю, это должно нейтрализовать отраву в котле!$B$BСходи с порошком в одну из пещер и посмотри, сработает ли.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Бикси Винтодер, что прячется к югу от Келий Смерти, всыпьте лечебный порошок Бикси в чумной котел в Кельях Смерти, чтобы нейтрализовать отвар в нем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я знала, что у тебя получится. А теперь – есть кое-что еще, о чем я хотела бы тебя попросить.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Время не ждет, $C. Вот уж чего нам точно не нужно - так это встреча с чумным магнатавром.$B$BОни и здоровые-то - не подарок!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бикси Винтодер в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11695,'Рог неистовства стихий','Я могу изготовить подобие элементаля из этих кусков бездушного камня, однако вдохнуть в них жизнь – дело другое. Тут нам потребуется помощь и немного удачи.$b$bВ легендах говорится о древнем артефакте, который назывался рогом неистовства стихий. Я одолжу тебе свиток с текстом легенды. Не знаю, правда ли это, но больше нам рассчитывать не на что. Если легенда не лжет, части рога могут находиться на Затопленных равнинах, прилегающих к деревне с севера и с юго-запада.','Добудьте нижнюю половину рога и верхнюю половину рога у вождя Бурблгубля и вождя Гурглбугля и принесите их укротителю ветра Баре в деревне Таунка\'ле.','Удалось ли тебе отыскать рог? Правдива ли легенда?','Вернитесь к укротителю ветра Баре в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Рог неистовства стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я могу изготовить подобие элементаля из этих кусков бездушного камня, однако вдохнуть в них жизнь – дело другое. Тут нам потребуется помощь и немного удачи.$b$bВ легендах говорится о древнем артефакте, который назывался рогом неистовства стихий. Я одолжу тебе свиток с текстом легенды. Не знаю, правда ли это, но больше нам рассчитывать не на что. Если легенда не лжет, части рога могут находиться на Затопленных равнинах, прилегающих к деревне с севера и с юго-запада.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте нижнюю половину рога и верхнюю половину рога у вождя Бурблгубля и вождя Гурглбугля и принесите их укротителю ветра Баре в деревне Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе отыскать рог? Правдива ли легенда?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю ветра Баре в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11696,'Ахун явился!','Хвала благим силам, $n, что ты здесь. В этой пещере затаился Ахун, собирая силы для нападения. Силы Служителей Земли уже выступили, но в одиночку им не справиться.$B$BРазведай обстановку, $n. Найди наших шаманов из Служителей Земли и поговори с их предводительницей, Лумой Матерью Небес. Возможно, с твоей помощью мы разгромим Ахуна прежде, чем свершится непоправимое!','Найдите Луму Матерь Небес в Узилище.','Холод Ахуна распространяется по этим пещерам, $N; семя ледяной смерти, которая ждет нас, если он обретет полную силу. Я благодарю Мать-Землю за то, что она послала тебя.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ахун явился!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хвала благим силам, $n, что ты здесь. В этой пещере затаился Ахун, собирая силы для нападения. Силы Служителей Земли уже выступили, но в одиночку им не справиться.$B$BРазведай обстановку, $n. Найди наших шаманов из Служителей Земли и поговори с их предводительницей, Лумой Матерью Небес. Возможно, с твоей помощью мы разгромим Ахуна прежде, чем свершится непоправимое!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите Луму Матерь Небес в Узилище.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Холод Ахуна распространяется по этим пещерам, $N; семя ледяной смерти, которая ждет нас, если он обретет полную силу. Я благодарю Мать-Землю за то, что она послала тебя.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11697,'Тинки в некрополе!','Говорила я Тинки, чтоб не ходила одна, но нет, ей же надо было проверить этот разрушенный Некрополь к западу отсюда!$b$bЯ на сто процентов уверена, что те сектанты выползли из этого Некрополя. А это значит, я на сто процентов уверена, что Тинки в беде!$b$bА ведь она – лучший инженер у нас на взлетной полосе! Без нее нам кранты!$b$bЯ бы сама ее отыскала, но одна из этих тварей ранила меня в ногу прежде, чем я успела смыться. $n, если кто может ее выручить, то только ты!','Отыщите Тинки Свистопляс внутри Талрамаса.','Ау! Ты кто?$B$BТебя Бикси прислала? Отлично, давай вытащим меня отсюда!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тинки в некрополе!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Говорила я Тинки, чтоб не ходила одна, но нет, ей же надо было проверить этот разрушенный Некрополь к западу отсюда!$b$bЯ на сто процентов уверена, что те сектанты выползли из этого Некрополя. А это значит, я на сто процентов уверена, что Тинки в беде!$b$bА ведь она – лучший инженер у нас на взлетной полосе! Без нее нам кранты!$b$bЯ бы сама ее отыскала, но одна из этих тварей ранила меня в ногу прежде, чем я успела смыться. $n, если кто может ее выручить, то только ты!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Тинки Свистопляс внутри Талрамаса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ау! Ты кто?$B$BТебя Бикси прислала? Отлично, давай вытащим меня отсюда!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11698,'Может, проще уничтожить Плеть?','Если сектанты в этих пещерах пережили катастрофу, то приходится предположить, что и в упавшем некрополе на западе по-прежнему кишат воины Плети. Да и в прудах их, наверное, пруд пруди!$b$bБудешь рядом с Талрамасом, |3-6($c), пожалуйста, разберись с любыми прислужниками Короля-лича, которых только найдешь!','Уничтожьте 20 воинов Плети любого рода в Талрамасе и Гнойных прудах. Потом вернитесь к Бикси Винтодер к югу от Келий Смерти.','Не может быть, чтобы тебе удалось так быстро перебить столько воинов Плети!','Вернитесь к Бикси Винтодер в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Может, проще уничтожить Плеть?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если сектанты в этих пещерах пережили катастрофу, то приходится предположить, что и в упавшем некрополе на западе по-прежнему кишат воины Плети. Да и в прудах их, наверное, пруд пруди!$b$bБудешь рядом с Талрамасом, |3-6($c), пожалуйста, разберись с любыми прислужниками Короля-лича, которых только найдешь!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 20 воинов Плети любого рода в Талрамасе и Гнойных прудах. Потом вернитесь к Бикси Винтодер к югу от Келий Смерти.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не может быть, чтобы тебе удалось так быстро перебить столько воинов Плети!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Бикси Винтодер в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11699,'Я застряла в проклятой клетке... но ненадолго!','Сектанты с помощью магии засадили меня в эту клетку без дверей. Ха! Они не знают, что у себя на взлетной полосе я – главный инженер передачника!$b$bС твоей помощью, немного повозившись, я отсюда выберусь в два счета!$b$bМне потребуется кристалл энергетического ядра одного из здешних вурдалаков, магический гироскоп их доктора и направляющий камень Плети Лич-Лорда, там, наверху.$b$bС помощью всего этого добра я сумею изготовить телепортационное устройство, которое позволит смыться отсюда по-гномьи и вернуться к Выкрутеню.','Найдите кристалл энергетического ядра, магический гироскоп и направляющий камень Плети и отдайте их Тинки Свистопляс в Талрамасе.','Отлично! Так, сейчас тут подправим, тут подкрутим…','Ну что, все удалось собрать?','Вернитесь к Тинки Свистопляс в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Я застряла в проклятой клетке... но ненадолго!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Сектанты с помощью магии засадили меня в эту клетку без дверей. Ха! Они не знают, что у себя на взлетной полосе я – главный инженер передачника!$b$bС твоей помощью, немного повозившись, я отсюда выберусь в два счета!$b$bМне потребуется кристалл энергетического ядра одного из здешних вурдалаков, магический гироскоп их доктора и направляющий камень Плети Лич-Лорда, там, наверху.$b$bС помощью всего этого добра я сумею изготовить телепортационное устройство, которое позволит смыться отсюда по-гномьи и вернуться к Выкрутеню.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите кристалл энергетического ядра, магический гироскоп и направляющий камень Плети и отдайте их Тинки Свистопляс в Талрамасе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Так, сейчас тут подправим, тут подкрутим…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, все удалось собрать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Тинки Свистопляс в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11700,'Сообщение для Бикси','Моя темная сторона куда-то делась.$B$BЯ уверена, что она не вернулась на взлетную полосу. В общем, где бы она ни оказалась, там еще холоднее, чем здесь. Но я смогла "поймать" ее лишь на минутку.$B$BНу, да, я перенастрою эту штуку и перенесусь на взлетную полосу достаточно скоро. А пока... как думаешь, ты $gмог:могла; бы направиться на восток и дать Бикси знать, что я встречусь с ней там?$B$BДа? Спасибо, $n!','Поговорите с Бикси Винтодер, находящейся рядом с Кельями Смерти, к югу от них.','У Тинки есть темная сторона?!$B$BНу, если она говорит, что в полном порядке и сможет сама вскоре добраться до взлетной полосы, я спокойна.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сообщение для Бикси',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Моя темная сторона куда-то делась.$B$BЯ уверена, что она не вернулась на взлетную полосу. В общем, где бы она ни оказалась, там еще холоднее, чем здесь. Но я смогла "поймать" ее лишь на минутку.$B$BНу, да, я перенастрою эту штуку и перенесусь на взлетную полосу достаточно скоро. А пока... как думаешь, ты $gмог:могла; бы направиться на восток и дать Бикси знать, что я встречусь с ней там?$B$BДа? Спасибо, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Бикси Винтодер, находящейся рядом с Кельями Смерти, к югу от них.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У Тинки есть темная сторона?!$B$BНу, если она говорит, что в полном порядке и сможет сама вскоре добраться до взлетной полосы, я спокойна.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11701,'Возвращение к взлетной полосе','Ладно, думаю, мне пора возвращаться к взлетной полосе. Разумеется, теперь, с раненой ногой, я хожу несколько медленнее...$b$bПослушай, не трудно ли тебе будет отправиться вперед меня и сообщить старине Выкрутеню приятные новости? Могу поручиться чем угодно, что без награды тебя не отпустят!$b$bСпасибо, $n!','Поговорите с Выкрутенем Разгоняйло на взлетной полосе Выкрутеня в Борейской тундре.','Вот так история, $N! Тут столько проблем, что даже удивительно, как это наша взлетная полоса до сих пор не стерта с лица земли!$B$BНо теперь благодаря тебе у нас стало одним врагом меньше.$B$BУ меня тут припасены особые награды для особо отличившихся. Выбирай, что больше нравится!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Возвращение к взлетной полосе',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, думаю, мне пора возвращаться к взлетной полосе. Разумеется, теперь, с раненой ногой, я хожу несколько медленнее...$b$bПослушай, не трудно ли тебе будет отправиться вперед меня и сообщить старине Выкрутеню приятные новости? Могу поручиться чем угодно, что без награды тебя не отпустят!$b$bСпасибо, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Выкрутенем Разгоняйло на взлетной полосе Выкрутеня в Борейской тундре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вот так история, $N! Тут столько проблем, что даже удивительно, как это наша взлетная полоса до сих пор не стерта с лица земли!$B$BНо теперь благодаря тебе у нас стало одним врагом меньше.$B$BУ меня тут припасены особые награды для особо отличившихся. Выбирай, что больше нравится!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11702,'Король Мргл-Мргл','Странно это звучит, должно быть, |3-6($c), но тут один мурлок есть, и он типа о помощи нас просит!$B$BИмя его – король Мргл-Мргл, а его подданные – мурлоки Зимних плавников. Его вместе с подданными выгнали из деревни, и теперь они хотят, чтобы ты их $gспас:спасла;.$B$BКак направишься на запад да вниз по утесам – тут-то его и найдешь. Он обретается на южной стороне Приюта Зимних Плавников.','Поговорите с королем Мрглом-Мрглом в Приюте Зимних Плавников.','Ты вернулся быстрее, чем я рассчитывала. Что тебе удалось выяснить?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Король Мргл-Мргл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Странно это звучит, должно быть, |3-6($c), но тут один мурлок есть, и он типа о помощи нас просит!$B$BИмя его – король Мргл-Мргл, а его подданные – мурлоки Зимних плавников. Его вместе с подданными выгнали из деревни, и теперь они хотят, чтобы ты их $gспас:спасла;.$B$BКак направишься на запад да вниз по утесам – тут-то его и найдешь. Он обретается на южной стороне Приюта Зимних Плавников.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королем Мрглом-Мрглом в Приюте Зимних Плавников.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся быстрее, чем я рассчитывала. Что тебе удалось выяснить?',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11703,'Добраться до Гетри','Посланник Плети, присматривающий за похищением и превращением воинов Орды в монструозную нежить, использует для выведения своих кошмарных созданий северо-западную ферму. Тенелов Гетри шпионил за этой тварью всю последнюю неделю и собрал немало важной информации, которая может позволить нам справиться с ситуацией.$B$BДоберись до Гетри и узнай, не можешь ли ты ему помочь остановить этот жуткий конвейер Плети. Гетри можно найти в заброшенной башне на северо-западном краю этих ферм.','Найдите тенелова Гетри у ферм Песни Войны.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добраться до Гетри',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Посланник Плети, присматривающий за похищением и превращением воинов Орды в монструозную нежить, использует для выведения своих кошмарных созданий северо-западную ферму. Тенелов Гетри шпионил за этой тварью всю последнюю неделю и собрал немало важной информации, которая может позволить нам справиться с ситуацией.$B$BДоберись до Гетри и узнай, не можешь ли ты ему помочь остановить этот жуткий конвейер Плети. Гетри можно найти в заброшенной башне на северо-западном краю этих ферм.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите тенелова Гетри у ферм Песни Войны.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11704,'Король Мргл-Мргл','Я понимаю, это звучит странно, |3-6($c), но одному мурлоку нужна наша помощь!$B$BОн известен под именем короля Мргла-Мргла и возглавляет мурлоков племени Зимних Плавников. Похоже, он вместе с подданными был вынужден бежать из своей деревни, а теперь они хотят, чтобы кто-нибудь их спас.$B$BИ этот "кто-нибудь" – ты!$B$BТы найдешь Приют Зимних Плавников и короля, направившись на запад по дороге, не доходя утесов. Иди к береговой линии близ Кипящего пруда.','Поговорите с королем Мрглом-Мрглом у Приюта Зимних Плавников.','Наконец-то прибыла помощь! Судя по твоему виду, ты из Альянса.$B$BЭто неплохо… у вас умелые воины. Именно это нам и нужно, в больших количествах.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Король Мргл-Мргл',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я понимаю, это звучит странно, |3-6($c), но одному мурлоку нужна наша помощь!$B$BОн известен под именем короля Мргла-Мргла и возглавляет мурлоков племени Зимних Плавников. Похоже, он вместе с подданными был вынужден бежать из своей деревни, а теперь они хотят, чтобы кто-нибудь их спас.$B$BИ этот "кто-нибудь" – ты!$B$BТы найдешь Приют Зимних Плавников и короля, направившись на запад по дороге, не доходя утесов. Иди к береговой линии близ Кипящего пруда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с королем Мрглом-Мрглом у Приюта Зимних Плавников.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Наконец-то прибыла помощь! Судя по твоему виду, ты из Альянса.$B$BЭто неплохо… у вас умелые воины. Именно это нам и нужно, в больших количествах.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`) VALUES (11705,'Бесполезные старания','Это просто безумие. Неужели они думают, что мы справимся с некролордом Плети и всеми его приспешниками, которых там невесть сколько?$b$b<Гетри вздыхает.>$b$bРаз Икорис прислал тебя сюда, он, очевидно, полагает, будто ты $gспособен:способна; на великие подвиги. Может, ты и чудеса творить умеешь, а?$b$bЧто ж, когда будешь $gготов:готова;, мы спустимся вниз и сразимся с Варидусом.$b$bЕсли уцелеем в этой заварухе, возвращайся к Адскому Крику в крепость Песни Войны.','Помогите Гетри одолеть Варидуса Свежевателя у ферм Песни Войны.$b$bЕсли вам это удастся, явитесь к Гаррошу Адскому Крику.','<Адский Крик приподнимает бровь, глядя на вас.>$B$BЧто по Варидусу Свежевателю?','Варидус Свежеватель побежден') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Бесполезные старания',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это просто безумие. Неужели они думают, что мы справимся с некролордом Плети и всеми его приспешниками, которых там невесть сколько?$b$b<Гетри вздыхает.>$b$bРаз Икорис прислал тебя сюда, он, очевидно, полагает, будто ты $gспособен:способна; на великие подвиги. Может, ты и чудеса творить умеешь, а?$b$bЧто ж, когда будешь $gготов:готова;, мы спустимся вниз и сразимся с Варидусом.$b$bЕсли уцелеем в этой заварухе, возвращайся к Адскому Крику в крепость Песни Войны.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите Гетри одолеть Варидуса Свежевателя у ферм Песни Войны.$b$bЕсли вам это удастся, явитесь к Гаррошу Адскому Крику.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Адский Крик приподнимает бровь, глядя на вас.>$B$BЧто по Варидусу Свежевателю?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Варидус Свежеватель побежден',`endtext_loc8`);
INSERT INTO `locales_quest` (`id`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11706,'Для создания Аллювиуса использовался рог неистовства стихий. Протруби в этот рог, встав у самой южной воронки на Поле Гейзеров, и Аллювиус откликнется на зов.$b$bОн устроит землетрясение, от которого все нерубские туннели обрушатся. Это положит конец их наступлению. Не удивлюсь, если после землетрясения наружу появится сам командир воинов Неруба. И если обрушение туннелей их не остановит, то гибель командира – наверняка!','Обрушьте нерубские воронки с помощью рога неистовства стихий и уничтожьте лорда Криксиса по просьбе укротителя ветра Бары из деревни Таунка\'ле.','Удалось ли тебе выпустить Аллювиуса на волю и остановить наступление воинов Неруба?','Вернитесь к укротителю ветра Баре в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Для создания Аллювиуса использовался рог неистовства стихий. Протруби в этот рог, встав у самой южной воронки на Поле Гейзеров, и Аллювиус откликнется на зов.$b$bОн устроит землетрясение, от которого все нерубские туннели обрушатся. Это положит конец их наступлению. Не удивлюсь, если после землетрясения наружу появится сам командир воинов Неруба. И если обрушение туннелей их не остановит, то гибель командира – наверняка!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Обрушьте нерубские воронки с помощью рога неистовства стихий и уничтожьте лорда Криксиса по просьбе укротителя ветра Бары из деревни Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе выпустить Аллювиуса на волю и остановить наступление воинов Неруба?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к укротителю ветра Баре в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11707,'Просьба о помощи','О, как хорошо! Ты ведь $n, верно?$b$bНам нужна твоя помощь на севере, на взлетной полосе Выкрутеня, причем нужна была еще вчера! Магнатавры, Плеть... а теперь еще и насосная станция!$b$bЯ тебе говорю – это безумие, чистое безумие!$b$bСтупай туда и поговори со стариком Выкрутенем на его взлетном поле. Срочно!!!','Поговорите с Выкрутенем Разгоняйло на взлетной полосе Выкрутеня.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Просьба о помощи',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О, как хорошо! Ты ведь $n, верно?$b$bНам нужна твоя помощь на севере, на взлетной полосе Выкрутеня, причем нужна была еще вчера! Магнатавры, Плеть... а теперь еще и насосная станция!$b$bЯ тебе говорю – это безумие, чистое безумие!$b$bСтупай туда и поговори со стариком Выкрутенем на его взлетном поле. Срочно!!!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с Выкрутенем Разгоняйло на взлетной полосе Выкрутеня.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11708,'Механогномы','Теперь, когда ты здесь, пришла пора рассказать тебе, что к чему.$b$bА когда выслушаешь мой рассказ, ступай наружу и отыщи моего заместителя, Джинки Гайковорот. Впредь за это отвечает она.','Выслушайте рассказ Выкрутеня Разгоняйло и найдите на взлетной полосе Выкрутеня Джинки Гайковорот.','Что, старикан прислал тебя ко мне, да? А что к чему, объяснил?$B$BХорошо, тогда за дело!','Эй, привет!','Поговорите с Джинки Гайковорот на взлетной полосе Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Механогномы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Теперь, когда ты здесь, пришла пора рассказать тебе, что к чему.$b$bА когда выслушаешь мой рассказ, ступай наружу и отыщи моего заместителя, Джинки Гайковорот. Впредь за это отвечает она.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выслушайте рассказ Выкрутеня Разгоняйло и найдите на взлетной полосе Выкрутеня Джинки Гайковорот.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Что, старикан прислал тебя ко мне, да? А что к чему, объяснил?$B$BХорошо, тогда за дело!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эй, привет!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с Джинки Гайковорот на взлетной полосе Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11710,'Что такое с передачником?','На востоке повсюду валяются запчасти: у Жгучих прудов, на Поле Гейзеров... да они, наверное, даже на насосной станции валяются! Принеси мне их, да побольше. Может, мне все-таки удастся наладить телепорт отправки в этой штуковине, не говоря уже о том, чтобы состроить порты приема.$b$bНе хотелось бы новых несчастных случаев...','Соберите 15 запасных деталей Выкрутеня и доставьте их Мордлу Шестеренку на взлетную полосу Выкрутеня.','Понадобится много запчастей, чтобы заставить эту штуку работать!$B$BСкажите, вы ведь достали все, что нужно, да?','Вернитесь к Мордлу Шестеренку на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что такое с передачником?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На востоке повсюду валяются запчасти: у Жгучих прудов, на Поле Гейзеров... да они, наверное, даже на насосной станции валяются! Принеси мне их, да побольше. Может, мне все-таки удастся наладить телепорт отправки в этой штуковине, не говоря уже о том, чтобы состроить порты приема.$b$bНе хотелось бы новых несчастных случаев...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 запасных деталей Выкрутеня и доставьте их Мордлу Шестеренку на взлетную полосу Выкрутеня.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Понадобится много запчастей, чтобы заставить эту штуку работать!$B$BСкажите, вы ведь достали все, что нужно, да?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Мордлу Шестеренку на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11711,'Доставка дезертиров: от получаса ожидания – бесплатно!','Здесь появляется все больше дезертиров с каждым днем. У нас просто нет больше места – нам некуда сажать этих трусливых тварей. Особенно, если мы не хотим утеснять свиней.$B$B<Нок хохочет с фырканьем.>$B$BЯ хочу, чтобы ты сопроводил одного из этих трусов к востоку отсюда и выстрелил из этого светового ружья. Один из их командиров выйдет на свет выстрела и заберет дезертира у тебя.$B$BКогда доставишь его и вернешься, доложись разведчику Тунгоку на восточной дороге.','Отведите дезертира Альянса к перекрестку восточнее крепости Песни Войны и выстрелите из сигнального ружья Песни Войны, чтобы дать сигнал представителям Альянса.$B$BДоложитесь разведчику Тунгоку, когда успешно доставите дезертира Альянса по месту назначения.','<Тунгок ворчит.>\n\nС дезертиром уже все, разобрался?','Дезертир Альянса доставлен по месту назначения','Вернитесь к разведчику Тунгоку на Равнины Кровавых Спор, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Доставка дезертиров: от получаса ожидания – бесплатно!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Здесь появляется все больше дезертиров с каждым днем. У нас просто нет больше места – нам некуда сажать этих трусливых тварей. Особенно, если мы не хотим утеснять свиней.$B$B<Нок хохочет с фырканьем.>$B$BЯ хочу, чтобы ты сопроводил одного из этих трусов к востоку отсюда и выстрелил из этого светового ружья. Один из их командиров выйдет на свет выстрела и заберет дезертира у тебя.$B$BКогда доставишь его и вернешься, доложись разведчику Тунгоку на восточной дороге.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите дезертира Альянса к перекрестку восточнее крепости Песни Войны и выстрелите из сигнального ружья Песни Войны, чтобы дать сигнал представителям Альянса.$B$BДоложитесь разведчику Тунгоку, когда успешно доставите дезертира Альянса по месту назначения.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','<Тунгок ворчит.>\n\nС дезертиром уже все, разобрался?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Дезертир Альянса доставлен по месту назначения',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Тунгоку на Равнины Кровавых Спор, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11712,'Перепроклятие','Если ты $gвыслушал:выслушала; старика, то знаешь, что у нас тут есть гномы, которые изменились. Механизатор Механозод заразил их чем-то, что отменяет "Проклятие Плоти", и теперь они сделались роботами!$b$bМы думаем, что знаем способ перепроклясть их обратно, чтобы они снова стали нормальными. Возьми вот эту перепроклинальную передачниковую инъекцию и используй ее на трупах механогномов, которые тебе встретятся.$b$bМы надеемся, что эта штука их исцелит и позволит нам отправить их отсюда.$b$bЧто скажешь, а, $n?','Используйте перепроклинальную передачниковую инъекцию на 6 механогномах со станции Выкрутеня по просьбе Джинки Гайковорот со взлетной полосы Выкрутеня.','Получилось! Сработало!$B$BПросто не верится, что тебе удалось спасти столько гномов! Как удачно, что ты здесь!','Вернитесь к Джинки Гайковорот на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Перепроклятие',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Если ты $gвыслушал:выслушала; старика, то знаешь, что у нас тут есть гномы, которые изменились. Механизатор Механозод заразил их чем-то, что отменяет "Проклятие Плоти", и теперь они сделались роботами!$b$bМы думаем, что знаем способ перепроклясть их обратно, чтобы они снова стали нормальными. Возьми вот эту перепроклинальную передачниковую инъекцию и используй ее на трупах механогномов, которые тебе встретятся.$b$bМы надеемся, что эта штука их исцелит и позволит нам отправить их отсюда.$b$bЧто скажешь, а, $n?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте перепроклинальную передачниковую инъекцию на 6 механогномах со станции Выкрутеня по просьбе Джинки Гайковорот со взлетной полосы Выкрутеня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Получилось! Сработало!$B$BПросто не верится, что тебе удалось спасти столько гномов! Как удачно, что ты здесь!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джинки Гайковорот на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11713,'Исследование воронок','Выкрутень отправил воздушную топографическую разведку, чтобы они составили карту нерубских воронок в южной части Поля Гейзеров, но они до сих пор не вернулись. Я больше не могу дожидаться, пока они вернутся, придется мне отправить кого-нибудь на разведку пешком.$b$bЯ понимаю, насколько это опасно, и ты получишь соответствующее вознаграждение. Возьми с собой эту карту и запиши важные сведения обо всех воронках, которые тебе там встретятся.','Отметьте на карте Поля Гейзеров расположение Южной воронки, Северо-западной воронки и Северо-восточной воронки по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня.','<Абнер берет у вас карту и пристально разглядывает ее.>$B$BОтлично! Это все, чего нам не хватало, чтобы начать операцию!','Ну что, все воронки отмечены на карте?','Вернитесь к Абнеру Шипокруту на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Исследование воронок',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Выкрутень отправил воздушную топографическую разведку, чтобы они составили карту нерубских воронок в южной части Поля Гейзеров, но они до сих пор не вернулись. Я больше не могу дожидаться, пока они вернутся, придется мне отправить кого-нибудь на разведку пешком.$b$bЯ понимаю, насколько это опасно, и ты получишь соответствующее вознаграждение. Возьми с собой эту карту и запиши важные сведения обо всех воронках, которые тебе там встретятся.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отметьте на карте Поля Гейзеров расположение Южной воронки, Северо-западной воронки и Северо-восточной воронки по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Абнер берет у вас карту и пристально разглядывает ее.>$B$BОтлично! Это все, чего нам не хватало, чтобы начать операцию!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, все воронки отмечены на карте?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Абнеру Шипокруту на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11714,'Дератизация','Может быть, ты не откажешься помочь мне в расчистке этих полей? Они просто кишат мелкими крысюками! Кобольды-шмобольды, как их там... они тут повсюду, повсюду! Одна вонь мне жизнь отравляет! Не говоря уже обо всем остальном... $B$BРазберись ради меня с этими вредителями, а я заплачу тебе за труды, $n.','По просьбе разведчика Тунгока на равнинах Кровавых Спор в Борейской тундре убейте 8 жнецов, 5 поджигателей и 2 обжарщика из стаи Кровавых Спор.','Пыльца – ключ к разгадке!','Вернитесь к разведчику Тунгоку на Равнины Кровавых Спор, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дератизация',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Может быть, ты не откажешься помочь мне в расчистке этих полей? Они просто кишат мелкими крысюками! Кобольды-шмобольды, как их там... они тут повсюду, повсюду! Одна вонь мне жизнь отравляет! Не говоря уже обо всем остальном... $B$BРазберись ради меня с этими вредителями, а я заплачу тебе за труды, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе разведчика Тунгока на равнинах Кровавых Спор в Борейской тундре убейте 8 жнецов, 5 поджигателей и 2 обжарщика из стаи Кровавых Спор.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пыльца – ключ к разгадке!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к разведчику Тунгоку на Равнины Кровавых Спор, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11715,'В поисках топлива','Я планирую построить машину, способную обрушить туннели, по которым Плеть подсылает своих нерубов. Однако наша горная установка вышла из строя. Придется раздобыть топливо для машины другим способом.$b$bНа Поле Гейзеров к юго-востоку отсюда от главной горной установки растеклись лужи нефти. Если сумеешь набрать достаточно нефти из этих луж, я смогу сделать из нее какое-никакое топливо.$b$bПросто установи этот нефтесборник рядом с установкой, и он примется качать нефть в свой бак.','Соберите 8 баррелей нефти в портативный нефтесборник по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня.','<Абнер опорожняет бак собирателя.>$B$BКонечно, кустарная перегонка нефти – работа грязная, но я с этим быстро управлюсь. А пока что нам для постройки машины нужна еще одна вещь…','Ну что, удалось тебе набрать топлива?','Вернитесь к Абнеру Шипокруту на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','В поисках топлива',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я планирую построить машину, способную обрушить туннели, по которым Плеть подсылает своих нерубов. Однако наша горная установка вышла из строя. Придется раздобыть топливо для машины другим способом.$b$bНа Поле Гейзеров к юго-востоку отсюда от главной горной установки растеклись лужи нефти. Если сумеешь набрать достаточно нефти из этих луж, я смогу сделать из нее какое-никакое топливо.$b$bПросто установи этот нефтесборник рядом с установкой, и он примется качать нефть в свой бак.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 8 баррелей нефти в портативный нефтесборник по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Абнер опорожняет бак собирателя.>$B$BКонечно, кустарная перегонка нефти – работа грязная, но я с этим быстро управлюсь. А пока что нам для постройки машины нужна еще одна вещь…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось тебе набрать топлива?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Абнеру Шипокруту на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11716,'Удивительный кровоспор','Мы стоим на пороге изумительных открытий, |3-6($r)! Целый неисследованный мир живет и дышит всего в нескольких шагах от нас! И я подозреваю, что вся здешняя экология держится на растении под название "кровоспор".$b$bЯ собрала немного пыльцы с находящихся по соседству мужских растений, но никак не могу найти женских экземпляров. Набери мне побольше плодолистиков кровоспор. Ты найдешь их поблизости от более крупных растений, растущих вокруг.$b$bНо берегись! Кобольды их добром не отдадут!','Добудьте 10 кровоспоровых плодолистиков по просьбе волшебницы крови Лаурит с равнин Кровавых Спор в Борейской тундре.','Нужно продолжать эксперименты!','Вернитесь к волшебнице крови Лаурит на Равнины Кровавых Спор, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Удивительный кровоспор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы стоим на пороге изумительных открытий, |3-6($r)! Целый неисследованный мир живет и дышит всего в нескольких шагах от нас! И я подозреваю, что вся здешняя экология держится на растении под название "кровоспор".$b$bЯ собрала немного пыльцы с находящихся по соседству мужских растений, но никак не могу найти женских экземпляров. Набери мне побольше плодолистиков кровоспор. Ты найдешь их поблизости от более крупных растений, растущих вокруг.$b$bНо берегись! Кобольды их добром не отдадут!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 10 кровоспоровых плодолистиков по просьбе волшебницы крови Лаурит с равнин Кровавых Спор в Борейской тундре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нужно продолжать эксперименты!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Лаурит на Равнины Кровавых Спор, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11717,'Быстродействующая пыльца','Это же очевидно! Кровоспоровые мотыльки опыляют эти равнины. Должно быть, в организме мотылька что-то происходит, что действует на пыльцу как катализатор. Теперь все это начинает обретать смысл, $n. Теперь понятно, почему кобольды не убивают мотыльков, а наоборот, готовы на все, чтобы только защитить их! Эти маленькие крысы все поняли!$B$BЧто ж, нам нужно просто тоже достать себе пыльцу! Что скажешь? Принесешь мне немного – ради науки?','Принесите волшебнице крови Лаурит на равнины Кровавых Спор 5 щепоток пыльцы кровоспоровых мотыльков.','Пыльца – ключ к разгадке!','Вернитесь к волшебнице крови Лаурит на Равнины Кровавых Спор, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Быстродействующая пыльца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это же очевидно! Кровоспоровые мотыльки опыляют эти равнины. Должно быть, в организме мотылька что-то происходит, что действует на пыльцу как катализатор. Теперь все это начинает обретать смысл, $n. Теперь понятно, почему кобольды не убивают мотыльков, а наоборот, готовы на все, чтобы только защитить их! Эти маленькие крысы все поняли!$B$BЧто ж, нам нужно просто тоже достать себе пыльцу! Что скажешь? Принесешь мне немного – ради науки?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите волшебнице крови Лаурит на равнины Кровавых Спор 5 щепоток пыльцы кровоспоровых мотыльков.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Пыльца – ключ к разгадке!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Лаурит на Равнины Кровавых Спор, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11718,'Автомат в мамонтовой шкуре','Я иначе собрал корпус старого автомата, который мог бы произвести достаточно сильное землетрясение для обвала туннелей, но начинка машины очень хрупка и чувствительна к жалящему холоду Нордскола.$B$BЯ придумал средство защитить ее, используя толстенные шкуры здешних мамонтов. Они бродят по равнинам к югу от взлетной полосы и рядом с Полем Гейзеров. Принеси мне шкуры для защиты механизма, и тогда я смогу обрушить его мощь на нерубов!','Принесите Абнеру Шипокруту на взлетную полосу Выкрутеня 6 толстых шкур мамонта.','<Абнер осматривает шкуры, закашлявшись пылью, скопившейся в них.>$B$BРазве у этих животных нет никаких понятий о гигиене? Некоторые из шкур просто до безобразия грязные. Эх, думаю, надо мне самому начать их чистить. Вряд ли у кого-то найдется здесь время на это...','Неси шкуры как можно быстрее! Я не смогу без них закончить подготовку машины!','Вернитесь к Абнеру Шипокруту на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Автомат в мамонтовой шкуре',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я иначе собрал корпус старого автомата, который мог бы произвести достаточно сильное землетрясение для обвала туннелей, но начинка машины очень хрупка и чувствительна к жалящему холоду Нордскола.$B$BЯ придумал средство защитить ее, используя толстенные шкуры здешних мамонтов. Они бродят по равнинам к югу от взлетной полосы и рядом с Полем Гейзеров. Принеси мне шкуры для защиты механизма, и тогда я смогу обрушить его мощь на нерубов!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите Абнеру Шипокруту на взлетную полосу Выкрутеня 6 толстых шкур мамонта.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Абнер осматривает шкуры, закашлявшись пылью, скопившейся в них.>$B$BРазве у этих животных нет никаких понятий о гигиене? Некоторые из шкур просто до безобразия грязные. Эх, думаю, надо мне самому начать их чистить. Вряд ли у кого-то найдется здесь время на это...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Неси шкуры как можно быстрее! Я не смогу без них закончить подготовку машины!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Абнеру Шипокруту на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11719,'Подопытное животное','<Лаурит смотрит на вас, будто оценивая.>Итак, у нас есть опыленный цветок кровоспора, но никто не горит желанием испробовать его действие. Может, ты соблаговолишь стать участником эксперимента? Ну что, в конце концов, такого страшного может произойти?$B$BНе бойся, $n! Просто возьми образец и вотри его в кожу.','По просьбе волшебницы крови Лаурит, находящейся на Равнинах Кровавых Спор в Борейской тундре, используйте опыленный цветок кровоспора и позвольте ей изучить полученные результаты.','Не надо бояться.','Цветок кровоспора использован','Поговорите с волшебницей крови Лаурит на Равнинах Кровавых Спор, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подопытное животное',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<Лаурит смотрит на вас, будто оценивая.>Итак, у нас есть опыленный цветок кровоспора, но никто не горит желанием испробовать его действие. Может, ты соблаговолишь стать участником эксперимента? Ну что, в конце концов, такого страшного может произойти?$B$BНе бойся, $n! Просто возьми образец и вотри его в кожу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе волшебницы крови Лаурит, находящейся на Равнинах Кровавых Спор в Борейской тундре, используйте опыленный цветок кровоспора и позвольте ей изучить полученные результаты.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не надо бояться.',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Цветок кровоспора использован',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Поговорите с волшебницей крови Лаурит на Равнинах Кровавых Спор, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`) VALUES (11720,'Вторжение в Гаммот','Адский Крик дал Крутому Рогу и мне тяжелое задание – истребить магнатавров у южной стороны крепости Песни Войны. С нами отправился целый взвод закаленных воинов Орды. Наше первое наступление на ближайшие логова успеха не имело – защищающие логова магнатавры смели весь отряд. Остались только мы...$B$BМы не ученые, не исследователи. Мы воины Орды – такие же, как ты. Солдаты на задании, которое нельзя провалить...$B$BПоговори со старейшиной Крутым Рогом прямо сейчас.','Поговорите со старейшиной Крутым Рогом на равнинах Кровавых Спор в Борейской тундре.','Кровоспор, что ты собрал, должно как раз хватить, чтобы дать нам шанс против магнатавров Гаммота – конечно же, с твоей помощью.','Не надо бояться.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вторжение в Гаммот',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Адский Крик дал Крутому Рогу и мне тяжелое задание – истребить магнатавров у южной стороны крепости Песни Войны. С нами отправился целый взвод закаленных воинов Орды. Наше первое наступление на ближайшие логова успеха не имело – защищающие логова магнатавры смели весь отряд. Остались только мы...$B$BМы не ученые, не исследователи. Мы воины Орды – такие же, как ты. Солдаты на задании, которое нельзя провалить...$B$BПоговори со старейшиной Крутым Рогом прямо сейчас.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите со старейшиной Крутым Рогом на равнинах Кровавых Спор в Борейской тундре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Кровоспор, что ты собрал, должно как раз хватить, чтобы дать нам шанс против магнатавров Гаммота – конечно же, с твоей помощью.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не надо бояться.',`requestitemstext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11721,'Гаммотра Мучитель','Магнатавры живут прайдами, подобно львам: один-два самца-вожака, и несколько самок с детенышами. В Гаммоте, логове магнатавров к западу отсюда, вожаком является Гаммотра. Именно Гаммотра повелевает магнатаврами, и именно его следует убить, чтобы остановить их.$b$bОтнеси этот мешочек с растертыми кровоспорами в Гаммот. Используй этот порошок, чтобы ослабить Гаммотру, а потом убей его! Принеси мне его голову в доказательство того, что задание выполнено.','Убейте Гаммотру и вернитесь с головой Гаммотры к старейшине Крутому Рогу на равнинах Кровавых Спор в Борейской тундре.','Этот порошок можно использовать, чтобы ослабить всех магнатавров. Вот почему местные крысолюди так ревниво его берегут.','Вернитесь к старейшине Крутому Рогу на Равнины Кровавых Спор, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гаммотра Мучитель',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Магнатавры живут прайдами, подобно львам: один-два самца-вожака, и несколько самок с детенышами. В Гаммоте, логове магнатавров к западу отсюда, вожаком является Гаммотра. Именно Гаммотра повелевает магнатаврами, и именно его следует убить, чтобы остановить их.$b$bОтнеси этот мешочек с растертыми кровоспорами в Гаммот. Используй этот порошок, чтобы ослабить Гаммотру, а потом убей его! Принеси мне его голову в доказательство того, что задание выполнено.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте Гаммотру и вернитесь с головой Гаммотры к старейшине Крутому Рогу на равнинах Кровавых Спор в Борейской тундре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Этот порошок можно использовать, чтобы ослабить всех магнатавров. Вот почему местные крысолюди так ревниво его берегут.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Крутому Рогу на Равнины Кровавых Спор, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11722,'Трофеи из Гаммота','Мы не можем присвоить себе всю честь этой победы, $n. Ведь это ты $gрисковал:рисковала; жизнью, проверяя на себе кровавые споры, и именно ты, в конце концов, $gпокончил:покончила; с Гаммотрой!$b$bОкажи нам честь: отправляйся обратно в крепость Песни Войны и вручи голову Гаммотры лорду Адскому Крику!','Отнесите голову Гаммотры Гаррошу Адскому Крику в крепость Песни Войны.','Ты вернулся? Так быстро?','Вернитесь к Гаррошу Адскому Крику в Крепость Песни Войны, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Трофеи из Гаммота',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы не можем присвоить себе всю честь этой победы, $n. Ведь это ты $gрисковал:рисковала; жизнью, проверяя на себе кровавые споры, и именно ты, в конце концов, $gпокончил:покончила; с Гаммотрой!$b$bОкажи нам честь: отправляйся обратно в крепость Песни Войны и вручи голову Гаммотры лорду Адскому Крику!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите голову Гаммотры Гаррошу Адскому Крику в крепость Песни Войны.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты вернулся? Так быстро?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Гаррошу Адскому Крику в Крепость Песни Войны, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11723,'<Абнер жадно выслушивает ваш доклад о ваших собственных успехах и об успехах Страха-и-ужаса 5000.>$B$BТо-то Выкрутень обрадуется! И кто знает – может, мы еще сделаем из тебя механика!','Вернитесь к Абнеру Шипокруту на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Абнер жадно выслушивает ваш доклад о ваших собственных успехах и об успехах Страха-и-ужаса 5000.>$B$BТо-то Выкрутень обрадуется! И кто знает – может, мы еще сделаем из тебя механика!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Абнеру Шипокруту на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11724,'Для гигантского омлета?','Это яйцо, очевидно, было кому-то очень нужно, о чем свидетельствует лежащее рядом тело. Когда вы осматриваете яйцо, то замечаете, что оно уже помечено к отправке на равнины Кровавых Спор, для волшебницы крови Лаурит. Но это же совсем рядом, к востоку отсюда!$B$BВозьмите яйцо и отнесите его к ожидающей волшебнице крови.','Отнесите массивное светящееся яйцо волшебнице крови Лаурит на равнины Кровавых Спор в Борейской тундре.','Значит, Алкора больше нет... Жаль... Что касается яйца, оно нам сейчас уже ни к чему. У нас тут возникли куда более сложные и неотложные проблемы.','Приветствую!','Вернитесь к волшебнице крови Лаурит на Равнины Кровавых Спор, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Для гигантского омлета?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это яйцо, очевидно, было кому-то очень нужно, о чем свидетельствует лежащее рядом тело. Когда вы осматриваете яйцо, то замечаете, что оно уже помечено к отправке на равнины Кровавых Спор, для волшебницы крови Лаурит. Но это же совсем рядом, к востоку отсюда!$B$BВозьмите яйцо и отнесите его к ожидающей волшебнице крови.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отнесите массивное светящееся яйцо волшебнице крови Лаурит на равнины Кровавых Спор в Борейской тундре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Значит, Алкора больше нет... Жаль... Что касается яйца, оно нам сейчас уже ни к чему. У нас тут возникли куда более сложные и неотложные проблемы.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Приветствую!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к волшебнице крови Лаурит на Равнины Кровавых Спор, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11725,'Поиски пилота "Штопора"','Я должен был сам лететь на это задание. Не то чтобы я не доверял "Штопору". Вовсе нет. Черт, да он был лучшим ведомым, с которым я когда-либо летал!$B$BНет, все дело в том, что выполнение такого задания – моя обязанность.$B$BЯ послал "Штопора" с нашей самой быстрой разведгруппой, чтобы собрать информацию о деятельности нерубов в центре Поля Гейзеров.$B$BВ их последнем донесении значилось, что группа находится у прудов далеко на юг и чуть западнее нерубских воронок.$B$BНайди "Штопора", $n.','Отыщите Игги "Штопора" Шестероверта на Поле Гейзеров','Слава механическим богам... Это было ужасно.$B$BЯркая вспышка на земле, а потом следующее, что я помню – весь отряд валится наземь. Я довольно сильно расшибся, так что у меня не было даже возможности прочесать окрестности в поисках других выживших, но что-то мне подсказывает, что вряд ли их будет много, если вообще будут$B$B<Лицо Игги перекашивает гримаса боли.>$B$BТы поможешь мне завершить мою миссию?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поиски пилота "Штопора"',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я должен был сам лететь на это задание. Не то чтобы я не доверял "Штопору". Вовсе нет. Черт, да он был лучшим ведомым, с которым я когда-либо летал!$B$BНет, все дело в том, что выполнение такого задания – моя обязанность.$B$BЯ послал "Штопора" с нашей самой быстрой разведгруппой, чтобы собрать информацию о деятельности нерубов в центре Поля Гейзеров.$B$BВ их последнем донесении значилось, что группа находится у прудов далеко на юг и чуть западнее нерубских воронок.$B$BНайди "Штопора", $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите Игги "Штопора" Шестероверта на Поле Гейзеров',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Слава механическим богам... Это было ужасно.$B$BЯркая вспышка на земле, а потом следующее, что я помню – весь отряд валится наземь. Я довольно сильно расшибся, так что у меня не было даже возможности прочесать окрестности в поисках других выживших, но что-то мне подсказывает, что вряд ли их будет много, если вообще будут$B$B<Лицо Игги перекашивает гримаса боли.>$B$BТы поможешь мне завершить мою миссию?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11726,'Добавить специй по вкусу...','Волки рыщут здесь с самого крушения, и я боюсь, что они могли сожрать микропленку, на которую мы снимали весь процесс.$B$BУ меня есть идея, как найти эту микропленку, но мне нужна твоя помощь, чтобы идея сработала.$B$BК югу и востоку отсюда, на Затопленных равнинах, живут существа, которых называют горлоками. Они готовят себе пищу, используя ядовитые специи, которые отравили бы любое другое существо. Если ты сможешь собрать достаточно мешочков со специями, которые носят с собой горлоки-пародувы и горлоки-хромули, я смогу сделать приманку для волков.','По просьбе Игги "Штопора" Шестероверта, что стоит возле Жгучих прудов, соберите 4 мешочка с горлокскими специями.','<Игги зажимает нос, опустошая мешочки со специями, и обращается к вам гнусавым голосом.>$B$BТеперь, когда у нас есть все необходимое, я смешаю специи со своим аварийным пайком, чтобы сделать приманку для волков.','Удалось найти мешочки со специями?','Вернитесь к Игги "Штопору" Шестероверту на Жгучие пруды, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Добавить специй по вкусу...',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Волки рыщут здесь с самого крушения, и я боюсь, что они могли сожрать микропленку, на которую мы снимали весь процесс.$B$BУ меня есть идея, как найти эту микропленку, но мне нужна твоя помощь, чтобы идея сработала.$B$BК югу и востоку отсюда, на Затопленных равнинах, живут существа, которых называют горлоками. Они готовят себе пищу, используя ядовитые специи, которые отравили бы любое другое существо. Если ты сможешь собрать достаточно мешочков со специями, которые носят с собой горлоки-пародувы и горлоки-хромули, я смогу сделать приманку для волков.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Игги "Штопора" Шестероверта, что стоит возле Жгучих прудов, соберите 4 мешочка с горлокскими специями.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Игги зажимает нос, опустошая мешочки со специями, и обращается к вам гнусавым голосом.>$B$BТеперь, когда у нас есть все необходимое, я смешаю специи со своим аварийным пайком, чтобы сделать приманку для волков.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось найти мешочки со специями?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Игги "Штопору" Шестероверту на Жгучие пруды, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11727,'Время героев','Клянусь бородой Магни! Похоже, прибыла наша тяжелая артиллерия!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время героев',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Клянусь бородой Магни! Похоже, прибыла наша тяжелая артиллерия!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11728,'Собаки-каки','Главное, ни в коем случае не ешьте эту приманку сами! Просто выложите ее неподалеку от запятнанного нефтью волка. Если уж они такие голодные, что сожрали микропленку, то на приманку сбегутся как миленькие.$b$bА потом просто дождитесь, пока природа возьмет свое, и отыщите пленки в... э-э... побочном продукте пищеварения.$b$bЯ бы одолжил вам специальную усовершенствованную лопатку для собаки-каки, но она, увы, осталась на взлетной полосе. Боюсь, вам придется искать по старинке, дедовским способом...','Принесите 8 кусков микропленки Игги "Штопору" Шестероверту у Жгучих прудов.','<Игги, зажав нос, берет у вас пленку.>$B$BОй, фу! Ну что, параграф 2 раздела 8.2 инструкций по действиям в чрезвычайной ситуации выполнен. Вот она, пленка. Ну, а насчет того, что я обязан ее отчищать, в инструкциях ничего не сказано!','Ну что, нашли пленку?','Вернитесь к Игги "Штопору" Шестероверту на Жгучие пруды, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Собаки-каки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Главное, ни в коем случае не ешьте эту приманку сами! Просто выложите ее неподалеку от запятнанного нефтью волка. Если уж они такие голодные, что сожрали микропленку, то на приманку сбегутся как миленькие.$b$bА потом просто дождитесь, пока природа возьмет свое, и отыщите пленки в... э-э... побочном продукте пищеварения.$b$bЯ бы одолжил вам специальную усовершенствованную лопатку для собаки-каки, но она, увы, осталась на взлетной полосе. Боюсь, вам придется искать по старинке, дедовским способом...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 кусков микропленки Игги "Штопору" Шестероверту у Жгучих прудов.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Игги, зажав нос, берет у вас пленку.>$B$BОй, фу! Ну что, параграф 2 раздела 8.2 инструкций по действиям в чрезвычайной ситуации выполнен. Вот она, пленка. Ну, а насчет того, что я обязан ее отчищать, в инструкциях ничего не сказано!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, нашли пленку?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Игги "Штопору" Шестероверту на Жгучие пруды, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11729,'Ультразвуковая отвертка','В механических недрах машины, которую вы только что разобрали по винтику, лежала странная вещица.$B$BВыглядит довольно сложным приспособлением... ясное дело, кто-нибудь на взлетной полосе с удовольствием посмотрит на это. Может, Умейка Шестеркрут?','Принесите ультразвуковую отвертку Умейке Шестеркрут на взлетную полосу Выкрутеня.','Эй!','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ультразвуковая отвертка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','В механических недрах машины, которую вы только что разобрали по винтику, лежала странная вещица.$B$BВыглядит довольно сложным приспособлением... ясное дело, кто-нибудь на взлетной полосе с удовольствием посмотрит на это. Может, Умейка Шестеркрут?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите ультразвуковую отвертку Умейке Шестеркрут на взлетную полосу Выкрутеня.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Эй!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11730,'Хозяин и слуга','Ультразвуковая отвертка – это суперинструмент! С ее помощью с механизмами можно делать что угодно!$b$bВозвращайся к прудам и обезвредь несколько роботов Механозода. Затем поковыряйся в их останках нашей отверткой, и могу поручиться, что они перейдут на нашу сторону, хотя бы на короткое время.$b$bНа механогномов это почти наверняка не подействует, так что даже и не пробуй.$b$bДа, и если захочешь вытащить из роботов что-нибудь ценное, сделай это до того, как пустишь в ход отвертку!','Используйте ультразвуковую отвертку, чтобы перепрограммировать 15 роботов, затем вернитесь к Умейке Шестеркрут на взлетной полосе Выкрутеня.$b$bНе забудьте обыскать убитых роботов прежде, чем перепрограммировать их.','Ух ты! И отвертка тоже осталась целехонька?$B$BЭти перепрограммированные роботы будут нам чрезвычайно полезны в борьбе против Механозода! Полагаю, ты заслуживаешь за это небольшой награды…','Сколько роботов тебе удалось перепрограммировать?','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Хозяин и слуга',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ультразвуковая отвертка – это суперинструмент! С ее помощью с механизмами можно делать что угодно!$b$bВозвращайся к прудам и обезвредь несколько роботов Механозода. Затем поковыряйся в их останках нашей отверткой, и могу поручиться, что они перейдут на нашу сторону, хотя бы на короткое время.$b$bНа механогномов это почти наверняка не подействует, так что даже и не пробуй.$b$bДа, и если захочешь вытащить из роботов что-нибудь ценное, сделай это до того, как пустишь в ход отвертку!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Используйте ультразвуковую отвертку, чтобы перепрограммировать 15 роботов, затем вернитесь к Умейке Шестеркрут на взлетной полосе Выкрутеня.$b$bНе забудьте обыскать убитых роботов прежде, чем перепрограммировать их.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! И отвертка тоже осталась целехонька?$B$BЭти перепрограммированные роботы будут нам чрезвычайно полезны в борьбе против Механозода! Полагаю, ты заслуживаешь за это небольшой награды…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Сколько роботов тебе удалось перепрограммировать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Умейке Шестеркрут на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11731,'Жонглирование факелами','Значит, ты хочешь научиться жонглировать горящими факелами? А у тебя есть необходимые для этого качества? Ловкость? Быстрая реакция? Отвага? Если ты думаешь, что да, то давай попрактикуемся немного!$B$BБери эти факелы и беги к костру. Над ним увидишь жаровни, с горящими метками. Бросай факелы в отмеченные жаровни. И делать это надо быстро! До того, как метка погаснет, если хочешь получить очко за попадание!$B$BПопади в достаточное количество отмеченных жаровен прежде, чем выйдет время, затем возвращайся назад... для следующего урока.','Выиграйте игру в бросание факелов, затем поговорите с мастером-огнеглотателем.','Отлично! Ты научишься жонглировать факелами – не успеешь и глазом моргнуть! Ну, готовься. Следующее испытание будет погорячее...','Попадите в 8 жаровен.','Вернитесь к огнеглотателю-виртуозу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Жонглирование факелами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Значит, ты хочешь научиться жонглировать горящими факелами? А у тебя есть необходимые для этого качества? Ловкость? Быстрая реакция? Отвага? Если ты думаешь, что да, то давай попрактикуемся немного!$B$BБери эти факелы и беги к костру. Над ним увидишь жаровни, с горящими метками. Бросай факелы в отмеченные жаровни. И делать это надо быстро! До того, как метка погаснет, если хочешь получить очко за попадание!$B$BПопади в достаточное количество отмеченных жаровен прежде, чем выйдет время, затем возвращайся назад... для следующего урока.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выиграйте игру в бросание факелов, затем поговорите с мастером-огнеглотателем.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Ты научишься жонглировать факелами – не успеешь и глазом моргнуть! Ну, готовься. Следующее испытание будет погорячее...',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Попадите в 8 жаровен.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к огнеглотателю-виртуозу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11732,'Осквернение огня','Оскверните большой костер Альянса на нагорье Арати!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернение огня',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Оскверните большой костер Альянса на нагорье Арати!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`) VALUES (11733,'Переход через расселину','Мне известно о твоих стараниях, $gсмертный:смертная;. Не нужно притворяться, будто ты $gудивлен:удивлена;. Неужели ты не $gощущал:ощущала; на себе моего взгляда?$b$bПришло время сорвать завесу тьмы с твоего разума. Твоя душа созрела достаточно, чтобы принять некоторые суровые истины.$b$bНо прежде, чем выслушать эту историю, тебе следует воочию увидеть то, чему мы противостоим.$b$bПриведи свои дела в порядок, |3-6($c).','Отправляйтесь в Хладарру по распоряжению Сурристраза. Оказавшись там, поговорите с верховным магом Беринардом.','Ну что, |3-6($C), дело сделано? Клаксимус мертв?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Переход через расселину',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мне известно о твоих стараниях, $gсмертный:смертная;. Не нужно притворяться, будто ты $gудивлен:удивлена;. Неужели ты не $gощущал:ощущала; на себе моего взгляда?$b$bПришло время сорвать завесу тьмы с твоего разума. Твоя душа созрела достаточно, чтобы принять некоторые суровые истины.$b$bНо прежде, чем выслушать эту историю, тебе следует воочию увидеть то, чему мы противостоим.$b$bПриведи свои дела в порядок, |3-6($c).',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в Хладарру по распоряжению Сурристраза. Оказавшись там, поговорите с верховным магом Беринардом.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, |3-6($C), дело сделано? Клаксимус мертв?',`requestitemstext_loc8`);
