INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11788,'Смерть роботам!','Ладно, думаю, все готово к последнему и решительному бою... Но прежде чем уничтожить Механозода, тебе придется ликвидировать его помощников!$b$bИх зовут Шатунишка, ЕД-210, Макс Шмякс и Шлифовальщик, и находятся они, соответственно, на Западной станции, Северной станции, Средней станции и Южной станции.$b$bЧтобы выманить их наружу, просто открой клапаны на станциях, чтобы нарушить их работу. Найти их не трудно, там будут вращающиеся маячки.','Уничтожьте Шатунишку, ЕД-210, Макса Шмякса и Шлифовальщика, затем вернитесь к Джинки Гайковорот на взлетную полосу Выкрутеня.','Ух ты, тебе удалось выжить!$B$BНу что ж, насколько я понимаю, теперь осталось только разобраться с механизатором Механозодом.','Вернитесь к Джинки Гайковорот на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть роботам!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ладно, думаю, все готово к последнему и решительному бою... Но прежде чем уничтожить Механозода, тебе придется ликвидировать его помощников!$b$bИх зовут Шатунишка, ЕД-210, Макс Шмякс и Шлифовальщик, и находятся они, соответственно, на Западной станции, Северной станции, Средней станции и Южной станции.$b$bЧтобы выманить их наружу, просто открой клапаны на станциях, чтобы нарушить их работу. Найти их не трудно, там будут вращающиеся маячки.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Шатунишку, ЕД-210, Макса Шмякса и Шлифовальщика, затем вернитесь к Джинки Гайковорот на взлетную полосу Выкрутеня.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты, тебе удалось выжить!$B$BНу что ж, насколько я понимаю, теперь осталось только разобраться с механизатором Механозодом.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джинки Гайковорот на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (11789,'Солдат в беде','Эй, послушай! Мне нужна твоя помощь. Пожалуйста! Этот солдат станет жертвой яда могильщика, если не предпринять немедленных действий.$B$BМне удалось замедлить действие яда, но без хорошей порции антидота я не смогу устранить его.$B$BМне обещали противоядие, которое привезли на "Рассекателе туч" из последнего плавания на юг. Спустись в трюм "Рассекателя туч" и поищи там ящик со средствами оказания первой помощи.$B$BИ поспеши, |3-6($c)! Мы не можем позволить себе просто так терять людей.','Вернитесь к медику Хауторну в Пески Назама, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Солдат в беде',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Эй, послушай! Мне нужна твоя помощь. Пожалуйста! Этот солдат станет жертвой яда могильщика, если не предпринять немедленных действий.$B$BМне удалось замедлить действие яда, но без хорошей порции антидота я не смогу устранить его.$B$BМне обещали противоядие, которое привезли на "Рассекателе туч" из последнего плавания на юг. Спустись в трюм "Рассекателя туч" и поищи там ящик со средствами оказания первой помощи.$B$BИ поспеши, |3-6($c)! Мы не можем позволить себе просто так терять людей.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к медику Хауторну в Пески Назама, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (11790,'Сектанты среди нас','На этом алтаре полным-полно знаков Культа Проклятых. Похоже, фанатики с материка добрались уже и до Нордскола. Благоразумие требует сообщить об этом капитану корабля.$B$BВероятно, его можно найти на палубе.','Сектанты? Внизу?! Придется мне всю команду выпороть!$B$BПослушай... почему бы... почему бы адмиралу Кэнтлбри не разобраться с этой... с этой ситуацией?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сектанты среди нас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом алтаре полным-полно знаков Культа Проклятых. Похоже, фанатики с материка добрались уже и до Нордскола. Благоразумие требует сообщить об этом капитану корабля.$B$BВероятно, его можно найти на палубе.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сектанты? Внизу?! Придется мне всю команду выпороть!$B$BПослушай... почему бы... почему бы адмиралу Кэнтлбри не разобраться с этой... с этой ситуацией?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`) VALUES (11791,'Сообщить Арлосу','Нужно немедленно сообщить это генералу Арлосу! Я знаю этого командира уже давно, и, уж поверь, он никогда не бывал замечен в небрежности!$b$bКто знает, сколько еще сектантов проникло в наши поселения в Нордсколе на других кораблях? Это может привести к катастрофе!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сообщить Арлосу',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Нужно немедленно сообщить это генералу Арлосу! Я знаю этого командира уже давно, и, уж поверь, он никогда не бывал замечен в небрежности!$b$bКто знает, сколько еще сектантов проникло в наши поселения в Нордсколе на других кораблях? Это может привести к катастрофе!',`details_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`completedtext_loc8`) VALUES (11792,'Враги света','Стоп, не так быстро. Не знаю, как тебя, |3-6($c), а меня слова генерала не особо убедили. Они звучали так... неуверенно... как будто это не его собственное мнение.$B$BТут что-то происходит. Все наши попытки сотрудничества откладываются и блокируются. Пришло время занять более независимую позицию.$B$BЕсли мы хотим больше узнать о сектантах в крепости, может быть, стоит... порасспросить тех, кто за ее стенами?$B$BРазведка донесла о небольшой группе сектантов, помогающих силам Плети к северу отсюда. Узнай – может быть, у них найдется ключ к разгадке.','Вернитесь к предвестнику Вуренну в Крепость Отваги, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Враги света',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Стоп, не так быстро. Не знаю, как тебя, |3-6($c), а меня слова генерала не особо убедили. Они звучали так... неуверенно... как будто это не его собственное мнение.$B$BТут что-то происходит. Все наши попытки сотрудничества откладываются и блокируются. Пришло время занять более независимую позицию.$B$BЕсли мы хотим больше узнать о сектантах в крепости, может быть, стоит... порасспросить тех, кто за ее стенами?$B$BРазведка донесла о небольшой группе сектантов, помогающих силам Плети к северу отсюда. Узнай – может быть, у них найдется ключ к разгадке.',`details_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Вуренну в Крепость Отваги, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11793,'Дальнейшее расследование','Боюсь, мне придется поручить это дело кому-то из моих агентов... кому-то, кто умеет работать втайне. Улики забери с собой и передай их воздаятелю Яаале в таверне.$b$bСкажи ей, что ты от меня, и больше ни с кем это не обсуждай. Неизвестно, кто еще может работать на секту.','Тебя прислал предвестник Вуренн?','Вернитесь к воздаятельнице Яаале в Крепость Отваги, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Дальнейшее расследование',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Боюсь, мне придется поручить это дело кому-то из моих агентов... кому-то, кто умеет работать втайне. Улики забери с собой и передай их воздаятелю Яаале в таверне.$b$bСкажи ей, что ты от меня, и больше ни с кем это не обсуждай. Неизвестно, кто еще может работать на секту.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебя прислал предвестник Вуренн?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятельнице Яаале в Крепость Отваги, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`completedtext_loc8`) VALUES (11794,'Охота началась!','Вернитесь к воздаятельнице Яаале в Крепость Отваги, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота началась!',`title_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к воздаятельнице Яаале в Крепость Отваги, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11795,'"Действия в чрезвычайных ситуациях": раздел 8.2, параграф 3','Неважно, ранен я или нет, но я командир отряда, и я отвечаю за то, чтобы найти и вернуть знаки всех своих павших пилотов. Все эти годы, что я летал с ребятами Выкрутеня, мы никогда не упускали ни одного знака.$B$BМои раны не позволяют мне удаляться от сравнительной безопасности этих обломков, но, может быть, вы не отказались бы помочь мне найти знаки? А тем временем я подготовился бы к выполнению своих последних обязанностей как командира отряда.','Снимите 6 значков пилота станции Выкрутеня с тел пилотов-разведчиков станции Выкрутеня и верните их Игги "Штопору" Шестероверту, который находится у Жгучих Прудов.','Тебе удалось найти все знаки?','Вернитесь к Игги "Штопору" Шестероверту на Жгучие пруды, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Действия в чрезвычайных ситуациях": раздел 8.2, параграф 3',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Неважно, ранен я или нет, но я командир отряда, и я отвечаю за то, чтобы найти и вернуть знаки всех своих павших пилотов. Все эти годы, что я летал с ребятами Выкрутеня, мы никогда не упускали ни одного знака.$B$BМои раны не позволяют мне удаляться от сравнительной безопасности этих обломков, но, может быть, вы не отказались бы помочь мне найти знаки? А тем временем я подготовился бы к выполнению своих последних обязанностей как командира отряда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Снимите 6 значков пилота станции Выкрутеня с тел пилотов-разведчиков станции Выкрутеня и верните их Игги "Штопору" Шестероверту, который находится у Жгучих Прудов.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось найти все знаки?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Игги "Штопору" Шестероверту на Жгучие пруды, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11796,'"Действия в чрезвычайных ситуациях": раздел 8.2, параграф 4','Прежде чем я наконец смогу вернуться к взлетной полосе и отчитаться перед начальством, осталось еще одно дело. Параграф 4 раздела 8.2 инструкции по действиям в чрезвычайной ситуации требует с максимальной тщательностью уничтожить все обломки, чтобы наши секреты не доставались врагу.$b$bЯ дам тебе горелку, если ты согласишься мне помочь. Мне не хочется думать, что способны натворить гоблины, союзники Орды, если эти аппараты попадут к ним в лапы!','Уничтожьте обломки на восточном месте крушения, южном месте крушения и северо-западном месте крушения по просьбе Игги "Штопора" Шестероверта.','Вернитесь к Игги "Штопору" Шестероверту на Жгучие пруды, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','"Действия в чрезвычайных ситуациях": раздел 8.2, параграф 4',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде чем я наконец смогу вернуться к взлетной полосе и отчитаться перед начальством, осталось еще одно дело. Параграф 4 раздела 8.2 инструкции по действиям в чрезвычайной ситуации требует с максимальной тщательностью уничтожить все обломки, чтобы наши секреты не доставались врагу.$b$bЯ дам тебе горелку, если ты согласишься мне помочь. Мне не хочется думать, что способны натворить гоблины, союзники Орды, если эти аппараты попадут к ним в лапы!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте обломки на восточном месте крушения, южном месте крушения и северо-западном месте крушения по просьбе Игги "Штопора" Шестероверта.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Игги "Штопору" Шестероверту на Жгучие пруды, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11797,'Осада','Так-тааак. Хорошо, что Арлос вызвал сюда тяжелую артиллерию.$B$BНе пойми меня превратно – наши ребята делают все, что могут, но если столь знаменитый воин будет драться плечом к плечу с ними, это может повернуть ход всей войны. Я не знаю, сколько еще мы сможем продержаться против этой нерубской нежити.$B$BЧто скажешь – не против сделать вылазку и прибить по моему заданию несколько этих жучков-паучков? Покажи парням, как это делается!','Ты $Gвернулся:вернулась;. Надеюсь, ты $Gсократил:сократила; численность врага.','Вернитесь к сержанту Молотогору в Крепость Отваги, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осада',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Так-тааак. Хорошо, что Арлос вызвал сюда тяжелую артиллерию.$B$BНе пойми меня превратно – наши ребята делают все, что могут, но если столь знаменитый воин будет драться плечом к плечу с ними, это может повернуть ход всей войны. Я не знаю, сколько еще мы сможем продержаться против этой нерубской нежити.$B$BЧто скажешь – не против сделать вылазку и прибить по моему заданию несколько этих жучков-паучков? Покажи парням, как это делается!',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;. Надеюсь, ты $Gсократил:сократила; численность врага.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Молотогору в Крепость Отваги, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11798,'Механизатор','Механизатор Механозод сошел с ума! Он утверждает, будто дарит нам бессмертие, снимая с нас то, что он называет "Проклятием Плоти". Но на самом деле он превращает нас в рабов-роботов!$b$b$n, мы почти уверены, что он и сейчас находится на насосной станции среди прудов на востоке.$b$bВ последний раз его видели в командной рубке наверху. Сходи туда и исследуй его записи.$b$bТебе придется сразиться с Механозодом, чтобы гномы... да не только гномы, чтобы все разумные существа могли жить!','Изучите Руководство механизатора и принесите голову Механозода Выкрутеню Разгоняйло.','Джинки сказала мне, что ты придешь. Ну что, дело сделано?','Вернитесь к Выкрутеню Разгоняйло на взлетную полосу Выкрутеня, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Механизатор',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Механизатор Механозод сошел с ума! Он утверждает, будто дарит нам бессмертие, снимая с нас то, что он называет "Проклятием Плоти". Но на самом деле он превращает нас в рабов-роботов!$b$b$n, мы почти уверены, что он и сейчас находится на насосной станции среди прудов на востоке.$b$bВ последний раз его видели в командной рубке наверху. Сходи туда и исследуй его записи.$b$bТебе придется сразиться с Механозодом, чтобы гномы... да не только гномы, чтобы все разумные существа могли жить!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Изучите Руководство механизатора и принесите голову Механозода Выкрутеню Разгоняйло.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Джинки сказала мне, что ты придешь. Ну что, дело сделано?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Выкрутеню Разгоняйло на взлетную полосу Выкрутеня, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11799,'Осквернение огня','Оскверните большой костер Орды в Пустоверти!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Осквернение огня',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Оскверните большой костер Орды в Пустоверти!',`offerrewardtext_loc8`);
