INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`) VALUES (11864,'Вступление','В разное время этот демон был известен под разными именами. Подробности не имеют особого значения, главное, что столкновения с ним всегда бывали гибельными.$B$BНо теперь, почти пятьдесят лет спустя после того, как все началось, наш демон наконец-то встретит свою гибель.$B$BНа этот раз мы сумеем его повергнуть! Эрнестуэю не уйти!$B$BИ Нордскол станет полем нашей битвы. Начинается охота на охотника!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Вступление',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','В разное время этот демон был известен под разными именами. Подробности не имеют особого значения, главное, что столкновения с ним всегда бывали гибельными.$B$BНо теперь, почти пятьдесят лет спустя после того, как все началось, наш демон наконец-то встретит свою гибель.$B$BНа этот раз мы сумеем его повергнуть! Эрнестуэю не уйти!$B$BИ Нордскол станет полем нашей битвы. Начинается охота на охотника!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11865,'Им рано умирать','Прежде к югу от нас вольно бродили стада карибу. Но тут появился Эрнестуэй, и все изменилось. Теперь карибу не знают ни минуты покоя, они постоянно пребывают в панике. Их преследуют охотники, расставляющие в тундре свои ловушки...$b$bЭрнестуэевы палачи недостойны того, чтобы жить, но и умирать им еще рано. Пусть сперва на своей шкуре ощутят те страдания, на которые они обрекают карибу! $b$bВот, возьми эту охапку искусственных шкур и накрой ими ловушки для карибу, что расставлены на юге. Пусть охотники сами попадутся в свои смертельные капканы!','Ты исполняешь волю Матери-Земли, $n, но не стоит упиваться своей победой! Мы обнаружили логово предводителя звероловов.','Не надо их жалеть, |3-6($r)!','Вернитесь к Зазе в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Им рано умирать',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Прежде к югу от нас вольно бродили стада карибу. Но тут появился Эрнестуэй, и все изменилось. Теперь карибу не знают ни минуты покоя, они постоянно пребывают в панике. Их преследуют охотники, расставляющие в тундре свои ловушки...$b$bЭрнестуэевы палачи недостойны того, чтобы жить, но и умирать им еще рано. Пусть сперва на своей шкуре ощутят те страдания, на которые они обрекают карибу! $b$bВот, возьми эту охапку искусственных шкур и накрой ими ловушки для карибу, что расставлены на юге. Пусть охотники сами попадутся в свои смертельные капканы!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ты исполняешь волю Матери-Земли, $n, но не стоит упиваться своей победой! Мы обнаружили логово предводителя звероловов.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не надо их жалеть, |3-6($r)!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Зазе в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11866,'Уши мертвых врагов','Я буду носить их на шее! Пусть они слышат наше послание миру!','Да, уши отлично подойдут!','Вернитесь к верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уши мертвых врагов',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я буду носить их на шее! Пусть они слышат наше послание миру!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Да, уши отлично подойдут!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11867,'Коллекция ушей','Я буду носить их на шее! Пусть они слышат наше послание миру!','Будь то искатели сокровищ или кровожадные охотники с пустошей, любые существа, поддерживающие Эрнестуэя и осмеливающиеся губить нашу драгоценную природу, объявляются врагами Д.Э.Г.О.Ж. Если вам случится убить кого-то из этих грязных прихвостней Эрнестуэя, принесите мне доказательства их смерти, и получите в награду благословение друидов Д.Э.Г.О.Ж.!','Вернитесь к верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Коллекция ушей',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Я буду носить их на шее! Пусть они слышат наше послание миру!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Будь то искатели сокровищ или кровожадные охотники с пустошей, любые существа, поддерживающие Эрнестуэя и осмеливающиеся губить нашу драгоценную природу, объявляются врагами Д.Э.Г.О.Ж. Если вам случится убить кого-то из этих грязных прихвостней Эрнестуэя, принесите мне доказательства их смерти, и получите в награду благословение друидов Д.Э.Г.О.Ж.!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11869,'Судьба моллюсков','К западу от нас находится озеро Кум\'уа. Это, насколько нам известно, единственный пресный водоем в мире, где обитают гигантские моллюски.$B$BКонечно, прихвостни Эрнестуэя занялись там культивированием жемчуга. Их нужно остановить! Тем, кто покушается на жизнь целого вида, нужно преподать урок.$B$BОтправляйся к озеру Кум\'уа и найди этих загребущих ловцов жемчуга. Убивай их, пока воды озера не покраснеют от крови! Возвращайся, когда покажешь им, где раки зимуют!','Посмотрим-ка, как они будут держаться, когда увидят, что сталось с их товарищами!','Вернитесь к иерофанту Сениус в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Судьба моллюсков',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','К западу от нас находится озеро Кум\'уа. Это, насколько нам известно, единственный пресный водоем в мире, где обитают гигантские моллюски.$B$BКонечно, прихвостни Эрнестуэя занялись там культивированием жемчуга. Их нужно остановить! Тем, кто покушается на жизнь целого вида, нужно преподать урок.$B$BОтправляйся к озеру Кум\'уа и найди этих загребущих ловцов жемчуга. Убивай их, пока воды озера не покраснеют от крови! Возвращайся, когда покажешь им, где раки зимуют!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Посмотрим-ка, как они будут держаться, когда увидят, что сталось с их товарищами!',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к иерофанту Сениус в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11870,'Покинутый предел','Мы только что получили сообщение от Лиандры, что наемники, работающие на Эрнестуэя, переносят добро с берега на главный корабль Эрнестуэя. Несомненно, они рассчитывают разбогатеть на своем убийственном ремесле!$b$bЛиандра просит, чтобы мы отправили помощь в Покинутый предел, к югу отсюда, на побережье Борейской тундры.$b$bТоропись, Лиандра ждет тебя!','Найдите иерофанта Лиандру в Покинутом пределе.','Вы от Сениус? Как нельзя более вовремя!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Покинутый предел',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы только что получили сообщение от Лиандры, что наемники, работающие на Эрнестуэя, переносят добро с берега на главный корабль Эрнестуэя. Несомненно, они рассчитывают разбогатеть на своем убийственном ремесле!$b$bЛиандра просит, чтобы мы отправили помощь в Покинутый предел, к югу отсюда, на побережье Борейской тундры.$b$bТоропись, Лиандра ждет тебя!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите иерофанта Лиандру в Покинутом пределе.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Вы от Сениус? Как нельзя более вовремя!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11871,'Пока мы на страже','На берегу, среди обломков кораблекрушения, валяются ящики и мешки с частями тел животных. Похоже, Эрнестуэй в сговоре с флибустьерами Северных морей. Эти грязные пираты перевозят добычу, которую кровожадные прихвостни Эрнестуэя добывают на побережье. Несомненно, все это добро завершает свой путь на плечах не слишком щепетильных богатеев по всему Азероту!$b$bТак вот, не бывать этому! Во всяком случае, пока мы на страже! Принеси мне весь груз, какой найдешь на берегу. Они его не получат!','Добудьте 12 партий частей тел животных по просьбе иерофанта Лиандры из Покинутого предела в Борейской тундре.','Мы устроим этим животным достойное погребение...','Вернитесь к иерофанту Лиандре в Покинутый предел, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Пока мы на страже',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На берегу, среди обломков кораблекрушения, валяются ящики и мешки с частями тел животных. Похоже, Эрнестуэй в сговоре с флибустьерами Северных морей. Эти грязные пираты перевозят добычу, которую кровожадные прихвостни Эрнестуэя добывают на побережье. Несомненно, все это добро завершает свой путь на плечах не слишком щепетильных богатеев по всему Азероту!$b$bТак вот, не бывать этому! Во всяком случае, пока мы на страже! Принеси мне весь груз, какой найдешь на берегу. Они его не получат!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Добудьте 12 партий частей тел животных по просьбе иерофанта Лиандры из Покинутого предела в Борейской тундре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Мы устроим этим животным достойное погребение...',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к иерофанту Лиандре в Покинутый предел, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11872,'Гнусный специалист по моллюскам','Прекрасно, $N! Кольцо вокруг Эрнестуэя стягивается!','Несешь мне хорошие новости?','Вернитесь к иерофанту Сениус в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Гнусный специалист по моллюскам',`title_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Прекрасно, $N! Кольцо вокруг Эрнестуэя стягивается!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Несешь мне хорошие новости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к иерофанту Сениус в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11873,'Новости для Выкрутеня','Не будешь ли ты так $gлюбезен:любезна; отправиться на взлетную полосу и сообщить Выкрутеню, что я скоро появлюсь и доложу обо всем, как положено? Мой ветролет потерпел крушение, я прибуду, как только разберусь с этим.$b$bНе сомневайся, я позабочусь о том, чтобы Выкрутень знал, что я обязан тебе жизнью и спасением.$b$bХотел бы я знать, что сделал бы старик, если бы сам летел с нами, как в старые добрые времена. Мне его изрядно недостает...','Вернитесь на взлетную полосу Выкрутеня и поговорите с Выкрутенем Разгоняйло.','<Выкрутень слушает ваш доклад, и лицо его постепенно просветляется.>$B$BЭх, надо было мне полететь с ними! Может быть, мы сумели бы сделать дело, не потеряв ни одного пилота…$B$BОднако Штопор прав. Если хоть что-то удалось спасти, то благодаря тебе. Возможно, именно твои действия все-таки помогут нам взять верх над воинами Неруба.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Новости для Выкрутеня',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Не будешь ли ты так $gлюбезен:любезна; отправиться на взлетную полосу и сообщить Выкрутеню, что я скоро появлюсь и доложу обо всем, как положено? Мой ветролет потерпел крушение, я прибуду, как только разберусь с этим.$b$bНе сомневайся, я позабочусь о том, чтобы Выкрутень знал, что я обязан тебе жизнью и спасением.$b$bХотел бы я знать, что сделал бы старик, если бы сам летел с нами, как в старые добрые времена. Мне его изрядно недостает...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Вернитесь на взлетную полосу Выкрутеня и поговорите с Выкрутенем Разгоняйло.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Выкрутень слушает ваш доклад, и лицо его постепенно просветляется.>$B$BЭх, надо было мне полететь с ними! Может быть, мы сумели бы сделать дело, не потеряв ни одного пилота…$B$BОднако Штопор прав. Если хоть что-то удалось спасти, то благодаря тебе. Возможно, именно твои действия все-таки помогут нам взять верх над воинами Неруба.',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`) VALUES (11874,'Upper Deck Promo – Верховая ракета') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Upper Deck Promo – Верховая ракета',`title_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11875,'Обретение преимущества','Войска наступательной группировки Расколотого Солнца воспользуются любым преимуществом, чтобы разбить союзников Кил\'джедена. Мои коллеги из Штормграда создали масла, при помощи которых можно усиливать оружие и доспехи наших воинов.$B$BГлавный компонент – пыль Пустоты – изобилует в Запределье, если знать, где искать. Любой мастер-травник, специалист по снятию шкур или горняк, знающий приметы, может собирать ее по ходу дела. Она может найтись во всех травах, рудах и животных Запределья.','Принесите 8 горстей пыли Пустоты эмиссару Мордину в Шаттрат.','Вы добыли для меня пыли?','Вернитесь к эмиссару Мордину в лес Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Обретение преимущества',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Войска наступательной группировки Расколотого Солнца воспользуются любым преимуществом, чтобы разбить союзников Кил\'джедена. Мои коллеги из Штормграда создали масла, при помощи которых можно усиливать оружие и доспехи наших воинов.$B$BГлавный компонент – пыль Пустоты – изобилует в Запределье, если знать, где искать. Любой мастер-травник, специалист по снятию шкур или горняк, знающий приметы, может собирать ее по ходу дела. Она может найтись во всех травах, рудах и животных Запределья.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 8 горстей пыли Пустоты эмиссару Мордину в Шаттрат.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Вы добыли для меня пыли?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к эмиссару Мордину в лес Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11876,'Помоги тем, кто не может помочь себе сам','Какие величественные звери, правда?$B$B<Латориус указывает на мамонтов северной тундры.>$B$BДень ото дня их число уменьшается. Демоны, называющие себя охотниками, убивают их ради забавы и богатства.$B$B<Лицо Латориуса перекашивается от гнева.>$B$BА этот плач просто сводит меня с ума, $n. Эти звуки приносит ветер: к нам взывают малыши-мамонтенки, попавшие в жестокие ловушки охотников.$B$BВозьми этот молот и сокруши ловушки. Освободи детенышей!','<Верховный друид утирает слезы с глаз.>$B$BШансы их невелики. Осиротевшие, они все равно умрут...','Их нужно освободить!','Вернитесь к верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Помоги тем, кто не может помочь себе сам',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Какие величественные звери, правда?$B$B<Латориус указывает на мамонтов северной тундры.>$B$BДень ото дня их число уменьшается. Демоны, называющие себя охотниками, убивают их ради забавы и богатства.$B$B<Лицо Латориуса перекашивается от гнева.>$B$BА этот плач просто сводит меня с ума, $n. Эти звуки приносит ветер: к нам взывают малыши-мамонтенки, попавшие в жестокие ловушки охотников.$B$BВозьми этот молот и сокруши ловушки. Освободи детенышей!',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','<Верховный друид утирает слезы с глаз.>$B$BШансы их невелики. Осиротевшие, они все равно умрут...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Их нужно освободить!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11877,'План нападения клана Ярости Солнца','Развивая наступление на Кель\'Данасе, мы обнаружили, что прихвостни Кель\'таса планируют контратаку. Отдав приказ эльфам крови Ярости Солнца, что базируются в Пустоверти, напасть на нашу операционную группировку в Запределье, он надеется, что мы отвлечемся от Солнечного Колодца и оттянем войска.$B$BМы не должны этого допустить, $n. На передовой каждый клинок драгоценен.$B$BОтправляйся в Пустоверть и захвати их военные планы. Они могут оказаться у любого эльфа крови Ярости Солнца. Удачи, $n.','Лорд Торвос из Шаттрата хочет, чтобы вы захватили планы нападения клана Ярости Солнца.','Планы у тебя?','Вернитесь к лорду Торвосу в Шаттрат.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','План нападения клана Ярости Солнца',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Развивая наступление на Кель\'Данасе, мы обнаружили, что прихвостни Кель\'таса планируют контратаку. Отдав приказ эльфам крови Ярости Солнца, что базируются в Пустоверти, напасть на нашу операционную группировку в Запределье, он надеется, что мы отвлечемся от Солнечного Колодца и оттянем войска.$B$BМы не должны этого допустить, $n. На передовой каждый клинок драгоценен.$B$BОтправляйся в Пустоверть и захвати их военные планы. Они могут оказаться у любого эльфа крови Ярости Солнца. Удачи, $n.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Лорд Торвос из Шаттрата хочет, чтобы вы захватили планы нападения клана Ярости Солнца.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Планы у тебя?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к лорду Торвосу в Шаттрат.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11878,'Ку\'нок обо всем позаботится!','Ты $gпомог:помогла; освободить детенышей, попавших в ловушку, но многие из них все равно погибнут. Понимаешь, оставшись без матери, эти детеныши вынуждены будут заботиться о себе сами.$b$bНо выход есть! У них остается надежда на спасение!$b$bК северу отсюда, на равнинах у берегов Жгучих прудов, пасется Ку\'нок Чудовище, древний и мудрый мамонт. Возьми этого осиротевшего детеныша и отведи его к Ку\'ноку. Он обо всем позаботится!','Отведите мамонтенка-сироту к Ку\'ноку Чудовищу в Борейской тундре.','*Вы слышите внутри себя голос. Это говорит с вами Ку\'нок.*$b$bЯ услышал твое имя в шуме ветра, $n. Твоя помощь моим сородичам неоценима. Отныне ты – наш союзник. Увы, с нашими мучениями нельзя покончить без кровопролития и насилия.$b$bЦена мира и покоя для мамонтов – смерть Кау...','Мамонтенок-сирота передан Ку\'ноку','Вернитесь к Ку\'нку Чудовище в Борейскую тундру.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ку\'нок обо всем позаботится!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты $gпомог:помогла; освободить детенышей, попавших в ловушку, но многие из них все равно погибнут. Понимаешь, оставшись без матери, эти детеныши вынуждены будут заботиться о себе сами.$b$bНо выход есть! У них остается надежда на спасение!$b$bК северу отсюда, на равнинах у берегов Жгучих прудов, пасется Ку\'нок Чудовище, древний и мудрый мамонт. Возьми этого осиротевшего детеныша и отведи его к Ку\'ноку. Он обо всем позаботится!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отведите мамонтенка-сироту к Ку\'ноку Чудовищу в Борейской тундре.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','*Вы слышите внутри себя голос. Это говорит с вами Ку\'нок.*$b$bЯ услышал твое имя в шуме ветра, $n. Твоя помощь моим сородичам неоценима. Отныне ты – наш союзник. Увы, с нашими мучениями нельзя покончить без кровопролития и насилия.$b$bЦена мира и покоя для мамонтов – смерть Кау...',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Мамонтенок-сирота передан Ку\'ноку',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Ку\'нку Чудовище в Борейскую тундру.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11879,'Кау Гроза Мамонтов','Что случилось?','Вернитесь к верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кау Гроза Мамонтов',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что случилось?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж., что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`completedtext_loc8`) VALUES (11880,'Мультифазовый подход','Я уверен, что этот "гном-изобретатель" – чокнутый. Он все болтал о каких-то темных искажениях, что стали проявляться на Полях Духов вокруг Ошу\'гуна в Награнде.$B$BПо его словам эти, кхм, мультифазовые... кхм, спектрографические очки позволяют носителю видеть эти искажения и снимать с них данные. Он настаивал, что запись этих данных имеет фундаментальное значение для нашей кампании у Солнечного Колодца. Я думаю, он сумасшедший, но мне приказано исследовать все, что может помочь. Не хочешь ли провести считывание кое-каких данных?','Предвестник Харонем из Шаттрата просит вас при помощи мультифазовых спектрографических очков 6 раз провести считывание мультифазовых данных.','Спасибо за помощь. Ты понятия не имеешь, каково общаться с этим "Доктором" Ваффелем. Когда он не "проверяет", как идут у меня дела, он треплется о том или другом прибамбасе, который можно получить в результате его военно-технических изысканий.','Вернитесь к предвестнику Харонему на Террасу Света, что в Шаттрате.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Мультифазовый подход',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я уверен, что этот "гном-изобретатель" – чокнутый. Он все болтал о каких-то темных искажениях, что стали проявляться на Полях Духов вокруг Ошу\'гуна в Награнде.$B$BПо его словам эти, кхм, мультифазовые... кхм, спектрографические очки позволяют носителю видеть эти искажения и снимать с них данные. Он настаивал, что запись этих данных имеет фундаментальное значение для нашей кампании у Солнечного Колодца. Я думаю, он сумасшедший, но мне приказано исследовать все, что может помочь. Не хочешь ли провести считывание кое-каких данных?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Предвестник Харонем из Шаттрата просит вас при помощи мультифазовых спектрографических очков 6 раз провести считывание мультифазовых данных.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Спасибо за помощь. Ты понятия не имеешь, каково общаться с этим "Доктором" Ваффелем. Когда он не "проверяет", как идут у меня дела, он треплется о том или другом прибамбасе, который можно получить в результате его военно-технических изысканий.',`offerrewardtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к предвестнику Харонему на Террасу Света, что в Шаттрате.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11881,'Ценный груз','Доводилось ли тебе видеть в небе ветролеты? Любопытнейшая гномская новинка!$b$bДавненько мне хотелось наложить лапу на эти машинки, и вот, наконец, представился удобный случай это сделать! Один из их разведывательных отрядов потерпел катастрофу у Жгучих прудов, в юго-западной части Поля Гейзеров.$b$bСвистни в этот свисток у одной из разбившихся машин, и к тебе прибежит моя верная ослица Дженни. Она послушно пойдет за тобой следом и понесет на себе обломки, но тебе следует ее защищать. Если на нее нападут, она начнет ронять груз.','Помогите ослице Дженни добраться с места крушения к Феззиксу Штукельверту в деревню Таунка\'ле, не растеряв груз.','Не подведи! Я рассчитываю на тебя.','Вернитесь к Феззиксу Штукельверту в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ценный груз',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Доводилось ли тебе видеть в небе ветролеты? Любопытнейшая гномская новинка!$b$bДавненько мне хотелось наложить лапу на эти машинки, и вот, наконец, представился удобный случай это сделать! Один из их разведывательных отрядов потерпел катастрофу у Жгучих прудов, в юго-западной части Поля Гейзеров.$b$bСвистни в этот свисток у одной из разбившихся машин, и к тебе прибежит моя верная ослица Дженни. Она послушно пойдет за тобой следом и понесет на себе обломки, но тебе следует ее защищать. Если на нее нападут, она начнет ронять груз.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Помогите ослице Дженни добраться с места крушения к Феззиксу Штукельверту в деревню Таунка\'ле, не растеряв груз.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Не подведи! Я рассчитываю на тебя.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Феззиксу Штукельверту в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11882,'Игра с огнем','Хочешь научиться кое-чему новому?$b$bНе знаю, сумеешь ли ты когда-нибудь сравниться со мной в искусстве, но если будешь слушать внимательно, то пару-другую фокусов переймешь. Поговори с мастером-огнеглотателем в любой столице Альянса. Они тебя научат.','Поговорите с мастером-огнеглотателем в любой из столиц Альянса.','Привет. Хочешь научиться новым трюкам с огнем?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игра с огнем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь научиться кое-чему новому?$b$bНе знаю, сумеешь ли ты когда-нибудь сравниться со мной в искусстве, но если будешь слушать внимательно, то пару-другую фокусов переймешь. Поговори с мастером-огнеглотателем в любой столице Альянса. Они тебя научат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером-огнеглотателем в любой из столиц Альянса.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет. Хочешь научиться новым трюкам с огнем?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11883,'Танцы с огнем?','Хочешь научиться танцевать с огнем?$b$bЧто же, хорошо. Поговори с мастером огненного танца в любой из столиц Орды. Они тебе помогут.','Поговорите с мастером огненного танца в любой из столиц Орды.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Танцы с огнем?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь научиться танцевать с огнем?$b$bЧто же, хорошо. Поговори с мастером огненного танца в любой из столиц Орды. Они тебе помогут.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с мастером огненного танца в любой из столиц Орды.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11885,'Кровные враги','Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттиса, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра.','Вернитесь к Хаззику в лагерь Черного Ветра, что в лесу Тероккар.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Кровные враги',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттиса, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Хаззику в лагерь Черного Ветра, что в лесу Тероккар.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11886,'Необычная активность','Как говорится, потехе свой час, |3-6($c), но и делу время.$b$bКогда начался праздник, мы получили донесение с Зорамского взморья по поводу резкого усиления активности культа Сумеречного Молота. История праздника восходит к тем самым силам, которым эти безумцы поклоняются, так что это не совпадение. Отправляйся ко входу в Непроглядную Пучину – прямо к югу от него лежат руины. Посмотри, не сможешь ли ты получить какую информацию от этих фанатиков. Если понадобится – выбей ее силой. Когда понадобится помощь проводника, воспользуйся этим маячком.','Отправляйтесь в новый лагерь культа Сумеречного Молота к югу от входа в Непроглядную Пучину на Зорамском взморье, что в Ясеневом лесу, и добудьте сумеречную корреспонденцию, затем при помощи тотема-маяка свяжитесь с проводником из Служителей Земли.','Очень тревожные вести. Похоже, за смятением местных духов Огня и Воды стоит куда более опасный заговор, так что тут потребуется расследование...','Что удалось узнать?','Вернитесь к проводнику из Служителей Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Необычная активность',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Как говорится, потехе свой час, |3-6($c), но и делу время.$b$bКогда начался праздник, мы получили донесение с Зорамского взморья по поводу резкого усиления активности культа Сумеречного Молота. История праздника восходит к тем самым силам, которым эти безумцы поклоняются, так что это не совпадение. Отправляйся ко входу в Непроглядную Пучину – прямо к югу от него лежат руины. Посмотри, не сможешь ли ты получить какую информацию от этих фанатиков. Если понадобится – выбей ее силой. Когда понадобится помощь проводника, воспользуйся этим маячком.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь в новый лагерь культа Сумеречного Молота к югу от входа в Непроглядную Пучину на Зорамском взморье, что в Ясеневом лесу, и добудьте сумеречную корреспонденцию, затем при помощи тотема-маяка свяжитесь с проводником из Служителей Земли.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Очень тревожные вести. Похоже, за смятением местных духов Огня и Воды стоит куда более опасный заговор, так что тут потребуется расследование...',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что удалось узнать?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к проводнику из Служителей Земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11887,'Неприкосновенный запас','Роясь в вещах убитого гнома, вы находите небольшой мешок с припасами, инструментами и удобным рулончиком гномской клейкой ленты. Возможно, этот мешок пригодится Феззиксу Штукельверту, когда придется собирать из обломков гномские ветролеты.$b$bЕсли принести Феззиксу несколько таких мешков, можно получить приличную награду!','Соберите 7 гномских ремонтных наборов с тел погибших пилотов-разведчиков со станции Выкрутеня и принесите их Феззиксу Штукельверту в деревню Таунка\'ле.','Что это у тебя?..','Вернитесь к Феззиксу Штукельверту в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Неприкосновенный запас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Роясь в вещах убитого гнома, вы находите небольшой мешок с припасами, инструментами и удобным рулончиком гномской клейкой ленты. Возможно, этот мешок пригодится Феззиксу Штукельверту, когда придется собирать из обломков гномские ветролеты.$b$bЕсли принести Феззиксу несколько таких мешков, можно получить приличную награду!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 7 гномских ремонтных наборов с тел погибших пилотов-разведчиков со станции Выкрутеня и принесите их Феззиксу Штукельверту в деревню Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Что это у тебя?..',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Феззиксу Штукельверту в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11888,'Поездка в деревню Таунка\'ле','$R, вождь заставляет меня ждать... Время – это то, чего у Таунка\'ле нет!$B$BО твоем мастерстве ходят слухи. Чем ждать, пока Гаррош пошлет подкрепление, лучше я попрошу тебя пойти и помочь моим соплеменникам.$B$BДеревня Таунка\'ле находится далеко на северо-восток отсюда. Езжай по дороге на восток от крепости, поверни на север на перепутье. Немного погодя ты наткнешься на еще одно перепутье. Следуй по пути на восток, пройдя к югу, а затем к востоку от больших прудов вдоль Затопленных равнин.$B$BКогда прибудешь в деревню, поговори с ведуном земли и неба.','Поговорите с ведуном земли и неба в деревне Таунка\'ле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поездка в деревню Таунка\'ле',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','$R, вождь заставляет меня ждать... Время – это то, чего у Таунка\'ле нет!$B$BО твоем мастерстве ходят слухи. Чем ждать, пока Гаррош пошлет подкрепление, лучше я попрошу тебя пойти и помочь моим соплеменникам.$B$BДеревня Таунка\'ле находится далеко на северо-восток отсюда. Езжай по дороге на восток от крепости, поверни на север на перепутье. Немного погодя ты наткнешься на еще одно перепутье. Следуй по пути на восток, пройдя к югу, а затем к востоку от больших прудов вдоль Затопленных равнин.$B$BКогда прибудешь в деревню, поговори с ведуном земли и неба.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с ведуном земли и неба в деревне Таунка\'ле.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11889,'Смерть с небес','Мы неплохо держимся на передовых линиях против этих жуков. Правда, кое-кто из этих нахальных тварей может перелетать те самые передовые линии, и они сильно терзают наши внутренние оборонительные порядки.$b$bЯ реквизировал укрепленные рыболовецкие сети с наших гражданских кораблей. Если руки у тебя приспособлены для метания, с помощью этих сетей можно сдернуть врагов с неба. Нужно уменьшить их количество, чтобы наши силы сумели удержать крепость.','Мы перебьем их на земле и перебьем, если они повалят на нас с неба. А если эта безродная нежить явится с моря, мы отделаем их так, что мало не покажется.','Ты $Gвернулся:вернулась;. Надеюсь, хорошие новости?','Вернитесь к сержанту Молотогору в Крепость Отваги, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Смерть с небес',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы неплохо держимся на передовых линиях против этих жуков. Правда, кое-кто из этих нахальных тварей может перелетать те самые передовые линии, и они сильно терзают наши внутренние оборонительные порядки.$b$bЯ реквизировал укрепленные рыболовецкие сети с наших гражданских кораблей. Если руки у тебя приспособлены для метания, с помощью этих сетей можно сдернуть врагов с неба. Нужно уменьшить их количество, чтобы наши силы сумели удержать крепость.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Мы перебьем их на земле и перебьем, если они повалят на нас с неба. А если эта безродная нежить явится с моря, мы отделаем их так, что мало не покажется.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась;. Надеюсь, хорошие новости?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Молотогору в Крепость Отваги, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11890,'Что там с ними?','У гномов на прудах к западу отсюда возникли какие-то проблемы. Поделом им, конечно, ведь они всю землю уже изгадили своими так называемыми изобретениями.$B$BЯ хочу, чтобы ты $gотправился:отправилась; к их насосной станции и $gразузнал:разузнала;, что ж там с ними приключилось. А потом возвращайся, расскажешь.','Исследуйте область вокруг насосной станции Выкрутеня, а затем возвращайтесь к ведуну земли и неба в деревню Таунка\'ле.','Ну что, все воронки отмечены на карте?','Окрестности насосной станции Выкрутеня исследованы.','Вернитесь к ведуну земли и неба в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что там с ними?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','У гномов на прудах к западу отсюда возникли какие-то проблемы. Поделом им, конечно, ведь они всю землю уже изгадили своими так называемыми изобретениями.$B$BЯ хочу, чтобы ты $gотправился:отправилась; к их насосной станции и $gразузнал:разузнала;, что ж там с ними приключилось. А потом возвращайся, расскажешь.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Исследуйте область вокруг насосной станции Выкрутеня, а затем возвращайтесь к ведуну земли и неба в деревню Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, все воронки отмечены на карте?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Окрестности насосной станции Выкрутеня исследованы.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведуну земли и неба в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11891,'Невинный маскарад','Судя по всему, похоже, что к северо-западу от большого скопления служителей культа на Зорамском взморье есть еще один их лагерь, и они разговаривают... с гостями?$b$bЕсли подслушать эти разговоры, то многое можно узнать, |3-6($r). Возьми эту сферу. Она поможет тебе принять вид одного из крабов, которых полно на побережье. Подслушай разговоры служителей культа с этими "гостями" в северо-западном лагере и, если все пройдет удачно, вернись ко мне и расскажи, что удалось узнать.','При помощи сферы Краба проникните в новый Сумеречный лагерь к западу от входа в Непроглядную Пучину на Зорамском взморье в Ясеневом лесу, затем вызовите проводника из Служителей Земли при помощи тотема-маяка.','Они хотят призвать в наш мир повелителя холода? Нет! Не позволю им нарушить равновесие!','Удалось ли тебе узнать их тайны?','Подслушайте разговор сумеречных сектантов.','Вернитесь к проводнику из Служителей Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Невинный маскарад',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Судя по всему, похоже, что к северо-западу от большого скопления служителей культа на Зорамском взморье есть еще один их лагерь, и они разговаривают... с гостями?$b$bЕсли подслушать эти разговоры, то многое можно узнать, |3-6($r). Возьми эту сферу. Она поможет тебе принять вид одного из крабов, которых полно на побережье. Подслушай разговоры служителей культа с этими "гостями" в северо-западном лагере и, если все пройдет удачно, вернись ко мне и расскажи, что удалось узнать.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','При помощи сферы Краба проникните в новый Сумеречный лагерь к западу от входа в Непроглядную Пучину на Зорамском взморье в Ясеневом лесу, затем вызовите проводника из Служителей Земли при помощи тотема-маяка.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Они хотят призвать в наш мир повелителя холода? Нет! Не позволю им нарушить равновесие!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе узнать их тайны?',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Подслушайте разговор сумеречных сектантов.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к проводнику из Служителей Земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11893,'Сила стихий','Я все пытаюсь объяснить этому глупому гоблину, что его машины ненадежны.$b$bВот сила стихий – дело другое! И когда мое ученичество окончится, я овладею всей их мощью. Однако и того, что я уже знаю, будет достаточно, чтобы помочь нашему другу Феззиксу.$b$bВозьми этот тотем духа ветра и установи его вблизи одного из паровых яростней к западу от деревни. Тотем вберет в себя энергию убитых элементалей. Вернись ко мне с заряженным тотемом, остальное я беру на себя.','Дорейн Морозное Копыто из деревни Таунка\'ле просит вас использовать тотем духа ветра, чтобы собрать энергию 10 паровых яростней.','Тотем заряжен?','Вернитесь к Дорейну Морозному Копыту в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сила стихий',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я все пытаюсь объяснить этому глупому гоблину, что его машины ненадежны.$b$bВот сила стихий – дело другое! И когда мое ученичество окончится, я овладею всей их мощью. Однако и того, что я уже знаю, будет достаточно, чтобы помочь нашему другу Феззиксу.$b$bВозьми этот тотем духа ветра и установи его вблизи одного из паровых яростней к западу от деревни. Тотем вберет в себя энергию убитых элементалей. Вернись ко мне с заряженным тотемом, остальное я беру на себя.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Дорейн Морозное Копыто из деревни Таунка\'ле просит вас использовать тотем духа ветра, чтобы собрать энергию 10 паровых яростней.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тотем заряжен?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Дорейну Морозному Копыту в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11894,'Заплатки','Помнишь ту клейкую ленту, что ты мне $gпритащил:притащила;?$B$BНу вот, я нашел ей применение. Корпус этого ветролета пробит в стольких местах, что мне нужно обязательно укрепить его, если я хочу хоть когда-нибудь на нем полететь.$B$BДорейн – вон он, там стоит, – сказал мне, что таунка используют для изготовления водонепроницаемых контейнеров пропаренную кожу карибу. Болотные карибу тут в округе, возле деревни, повсюду живут, да и на Затопленных равнинах их хватает. Найди наилучшие шкуры и выделай их над паром на Полях Гейзеров.','Принесите 5 пропаренных шкур Феззиксу Штукельверту в деревню Таунка\'ле.','Фантастика! Еще несколько таких трюков – и я стану настоящим воздушно-десантным гоблином!','Как там дела с выделанными шкурами карибу?','Вернитесь к Феззиксу Штукельверту в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заплатки',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Помнишь ту клейкую ленту, что ты мне $gпритащил:притащила;?$B$BНу вот, я нашел ей применение. Корпус этого ветролета пробит в стольких местах, что мне нужно обязательно укрепить его, если я хочу хоть когда-нибудь на нем полететь.$B$BДорейн – вон он, там стоит, – сказал мне, что таунка используют для изготовления водонепроницаемых контейнеров пропаренную кожу карибу. Болотные карибу тут в округе, возле деревни, повсюду живут, да и на Затопленных равнинах их хватает. Найди наилучшие шкуры и выделай их над паром на Полях Гейзеров.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Принесите 5 пропаренных шкур Феззиксу Штукельверту в деревню Таунка\'ле.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Фантастика! Еще несколько таких трюков – и я стану настоящим воздушно-десантным гоблином!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Как там дела с выделанными шкурами карибу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Феззиксу Штукельверту в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11895,'Одолеть бурю','Из твоего описания следует, что с этими металлическими созданиями несложно будет справиться. Но сначала тебе нужно справиться с бурей.$B$BПозади меня на гряде есть тотем. Когда будешь $gготов:готова;, сосредоточь на нем свою волю – и грянет шторм. Ты $gдолжен:должна; одолеть шторм и таким образом вобрать в себя его сущность.$B$BЕсли там есть еще кто-нибудь, можете сражаться сообща, этого достаточно. А потом, |3-6($c), возвращайся ко мне.','Одолейте порыв шторма, затем возвращайтесь к ведуну земли и неба в деревне Таунка\'ле.','Удалось ли тебе повергнуть принца Валанара?','Вернитесь к ведуну земли и неба в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Одолеть бурю',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Из твоего описания следует, что с этими металлическими созданиями несложно будет справиться. Но сначала тебе нужно справиться с бурей.$B$BПозади меня на гряде есть тотем. Когда будешь $gготов:готова;, сосредоточь на нем свою волю – и грянет шторм. Ты $gдолжен:должна; одолеть шторм и таким образом вобрать в себя его сущность.$B$BЕсли там есть еще кто-нибудь, можете сражаться сообща, этого достаточно. А потом, |3-6($c), возвращайся ко мне.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Одолейте порыв шторма, затем возвращайтесь к ведуну земли и неба в деревне Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе повергнуть принца Валанара?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведуну земли и неба в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11896,'Уязвимы для молний','Ты теперь носишь в себе ярость шторма! Я научу тебя концентрировать эту силу, чтобы выводить из строя роботов в прудах.$b$bВот, возьми этот молниевый жезл. Используй его против роботов механогномов, которых найдешь среди прудов на западе. Против самих механогномов использовать его не трудись – у Великой матери Тайги другие планы на их счет.$b$bА когда сила бури ослабит роботов, разбери их полностью!','Уничтожьте 15 любых роботов, кроме механогномов, ослабленных воздействием ярости шторма, в области прудов вокруг насосной станции Выкрутеня.$b$bПосле этого вернитесь к ведуну земли и неба в деревне Таунка\'ле.','Если мы не будем заботиться о земле, она не станет долго нас терпеть!','Вернитесь к ведуну земли и неба в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Уязвимы для молний',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты теперь носишь в себе ярость шторма! Я научу тебя концентрировать эту силу, чтобы выводить из строя роботов в прудах.$b$bВот, возьми этот молниевый жезл. Используй его против роботов механогномов, которых найдешь среди прудов на западе. Против самих механогномов использовать его не трудись – у Великой матери Тайги другие планы на их счет.$b$bА когда сила бури ослабит роботов, разбери их полностью!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте 15 любых роботов, кроме механогномов, ослабленных воздействием ярости шторма, в области прудов вокруг насосной станции Выкрутеня.$b$bПосле этого вернитесь к ведуну земли и неба в деревне Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если мы не будем заботиться о земле, она не станет долго нас терпеть!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведуну земли и неба в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11897,'Заткнуть воронки!','Силы Плети и не собираются отступать, $n. Эти проклятые воронки: они соединены с туннелями на всем пути к леднику Ледяной Короны, насколько нам известно.$B$BЕсли годы занятий горным делом меня чему и научили, так это тому, что без опорных балок туннели легко обвалятся после взрыва.$B$BВозьми эту взрывчатку и установи заряды у входов в воронки на хребте над побережьем, к западу отсюда. Возвращайся, когда обвалишь туннели.','Нам нужно замедлить работу Плети, иначе Крепость Отваги будет захвачена.','Вернитесь к сержанту Молотогору в Крепость Отваги, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Заткнуть воронки!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Силы Плети и не собираются отступать, $n. Эти проклятые воронки: они соединены с туннелями на всем пути к леднику Ледяной Короны, насколько нам известно.$B$BЕсли годы занятий горным делом меня чему и научили, так это тому, что без опорных балок туннели легко обвалятся после взрыва.$B$BВозьми эту взрывчатку и установи заряды у входов в воронки на хребте над побережьем, к западу отсюда. Возвращайся, когда обвалишь туннели.',`details_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Нам нужно замедлить работу Плети, иначе Крепость Отваги будет захвачена.',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к сержанту Молотогору в Крепость Отваги, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11899,'Души распроклятых','Механогномы, живущие в прудах к западу отсюда, являются для нас полной загадкой. Они появились там вскоре после того, как с насосной станции и из ее окрестностей исчезли гномы.$b$bОни неестественны и опасны, и лучше, чтобы их не было вовсе.$b$bВозьми этот Ловец Душ и используй его на останках механогномов, чтобы взять их души в плен. Когда ты вернешься, мы выпустим их на волю и посмотрим, что будет.','Теперь освободим пойманные тобой души…','Ну что, с подручными покончено?','Вернитесь к Великой Матери Тайге в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Души распроклятых',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Механогномы, живущие в прудах к западу отсюда, являются для нас полной загадкой. Они появились там вскоре после того, как с насосной станции и из ее окрестностей исчезли гномы.$b$bОни неестественны и опасны, и лучше, чтобы их не было вовсе.$b$bВозьми этот Ловец Душ и используй его на останках механогномов, чтобы взять их души в плен. Когда ты вернешься, мы выпустим их на волю и посмотрим, что будет.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Теперь освободим пойманные тобой души…',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, с подручными покончено?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Великой Матери Тайге в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11900,'Что показывают приборы?','Я надеялся, что влияние Нексуса ограничивается этой местностью. Но недавно пошли сообщения со всего Азерота, что геологическая нестабильность растет лавинообразно!$B$BМне нужно постоянно наблюдать за Нексусом, поскольку я работаю над решением. $B$BЯ разместил в Хладарре чувствительные инструменты, замаскировав их под гадальные шары Малигоса. Один лежит во рве рядом с Нексусом, а еще три спрятаны в разных структурах по периметру долины. Посети все четыре места и принеси мне данные их измерений.','По просьбе верховного мага Беринанда из лагеря под Маскировочным щитом соберите показания его приборов в Хладарре.','Ты уже собрал образцы, что я просил?','Вернитесь к верховному магу Беринарду под Маскировочный щит, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Что показывают приборы?',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я надеялся, что влияние Нексуса ограничивается этой местностью. Но недавно пошли сообщения со всего Азерота, что геологическая нестабильность растет лавинообразно!$B$BМне нужно постоянно наблюдать за Нексусом, поскольку я работаю над решением. $B$BЯ разместил в Хладарре чувствительные инструменты, замаскировав их под гадальные шары Малигоса. Один лежит во рве рядом с Нексусом, а еще три спрятаны в разных структурах по периметру долины. Посети все четыре места и принеси мне данные их измерений.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе верховного мага Беринанда из лагеря под Маскировочным щитом соберите показания его приборов в Хладарре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже собрал образцы, что я просил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Беринарду под Маскировочный щит, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11901,'Военные? Какие военные?','По просьбе Джеральда Грина из Далечья отправляйтесь на север, в шахту, и выясните, что случилось с направленным туда воинским подразделением.','У вас буквально желудок начинает выворачивать, когда вы приближаетесь к зерну. Вонь от него идет почти невыносимая...') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Военные? Какие военные?',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Джеральда Грина из Далечья отправляйтесь на север, в шахту, и выясните, что случилось с направленным туда воинским подразделением.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','У вас буквально желудок начинает выворачивать, когда вы приближаетесь к зерну. Вонь от него идет почти невыносимая...',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11902,'Ужасное свидетельство','Мешки с зерном издают жуткое зловоние, которое наводит вас на мысли о Чуме. Вероятно, это объясняет, что случилось с пехотинцами, защищавшими рудник.$B$BЛучше бы сообщить об этом Джеральду Грину.','Возвращайтесь в Далечье к Джеральду Грину.','Бедняги... у них не было ни единого шанса!$B$BВсе выглядит так, будто это саботаж. Возможно, дело рук кого-то из Культа Проклятых. Чтоб они провалились со своим культом!') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ужасное свидетельство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мешки с зерном издают жуткое зловоние, которое наводит вас на мысли о Чуме. Вероятно, это объясняет, что случилось с пехотинцами, защищавшими рудник.$B$BЛучше бы сообщить об этом Джеральду Грину.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Возвращайтесь в Далечье к Джеральду Грину.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Бедняги... у них не было ни единого шанса!$B$BВсе выглядит так, будто это саботаж. Возможно, дело рук кого-то из Культа Проклятых. Чтоб они провалились со своим культом!',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11903,'Время действовать!','Итак, $n. Теперь, когда наши последние бойцы в Далечье или погибли, или их постигла еще худшая участь, нам остается только одно: самим сразиться с Плетью.$B$BМы развернули ополчение в том, что осталось от Далечья. Без твоей помощи у них практически нет надежды на победу. Иди и протяни им руку помощи. А я с ребятами останусь наблюдать за тропой. Мы не можем позволить Плети прорваться!','По просьбе Джеральда Грина из Далечья убейте 14 чумных падальщиков.','Вернитесь к Джеральду Грину в Далечье, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Время действовать!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Итак, $n. Теперь, когда наши последние бойцы в Далечье или погибли, или их постигла еще худшая участь, нам остается только одно: самим сразиться с Плетью.$B$BМы развернули ополчение в том, что осталось от Далечья. Без твоей помощи у них практически нет надежды на победу. Иди и протяни им руку помощи. А я с ребятами останусь наблюдать за тропой. Мы не можем позволить Плети прорваться!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Джеральда Грина из Далечья убейте 14 чумных падальщиков.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джеральду Грину в Далечье, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11904,'Плоды трудов наших','Отправляйтесь на шахту Далечья, добудьте ключ от повозки у капитана Якобса и используйте его для того, чтобы пустить повозку с рудой. По завершении задания вернитесь к Джеральду Грину в Далечье.','Вернитесь к Джеральду Грину в Далечье, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Плоды трудов наших',`title_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отправляйтесь на шахту Далечья, добудьте ключ от повозки у капитана Якобса и используйте его для того, чтобы пустить повозку с рудой. По завершении задания вернитесь к Джеральду Грину в Далечье.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Джеральду Грину в Далечье, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11906,'Очищение прудов','<По лицу шамана скатывается слеза.>$b$bЯ знаю, ты направляешься обратно к прудам, что на западе. Раз уж ты все равно там будешь, у меня есть для тебя поручение.$b$bГномы, которых не волнует судьба земли, загрязнили ее своей техникой. Я прошу тебя собрать валяющиеся на земле запчасти.$b$bПринеси их мне сюда. Я позабочусь о том, чтобы они были утилизованы должным образом прежде, чем мы уйдем отсюда навсегда.','Соберите 15 запасных деталей Выкрутеня и доставьте их Стальным Глазам в деревню Таунка\'ле.','Если мы не будем заботиться о земле, она не станет долго нас терпеть!','Вернитесь к Стальным глазам в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Очищение прудов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','<По лицу шамана скатывается слеза.>$b$bЯ знаю, ты направляешься обратно к прудам, что на западе. Раз уж ты все равно там будешь, у меня есть для тебя поручение.$b$bГномы, которых не волнует судьба земли, загрязнили ее своей техникой. Я прошу тебя собрать валяющиеся на земле запчасти.$b$bПринеси их мне сюда. Я позабочусь о том, чтобы они были утилизованы должным образом прежде, чем мы уйдем отсюда навсегда.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 15 запасных деталей Выкрутеня и доставьте их Стальным Глазам в деревню Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Если мы не будем заботиться о земле, она не станет долго нас терпеть!',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Стальным глазам в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11907,'Подручные Механозода','Известно, что у механизатора Механозода имеется четверо подручных, которые управляют роботами в прудах.$b$bИх необходимо уничтожить!$b$bНаши выносливые гонцы и снежные следопыты говорят, что, если открыть клапаны на Западной, Северной, Центральной и Южной станциях, то эти подручные тут же явятся, чтобы устранить помеху в работе.$b$bСтанции расположены вокруг вращающихся маячков в прудах вокруг насосной станции.$b$bТоропись, $n!','Уничтожьте Шатунишку, ЕД-210, Макса Шмякса и Шлифовальщика, затем вернитесь к Ведуну земли и неба в деревню Таунка\'ле.','Ну что, с подручными покончено?','Вернитесь к ведуну земли и неба в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Подручные Механозода',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Известно, что у механизатора Механозода имеется четверо подручных, которые управляют роботами в прудах.$b$bИх необходимо уничтожить!$b$bНаши выносливые гонцы и снежные следопыты говорят, что, если открыть клапаны на Западной, Северной, Центральной и Южной станциях, то эти подручные тут же явятся, чтобы устранить помеху в работе.$b$bСтанции расположены вокруг вращающихся маячков в прудах вокруг насосной станции.$b$bТоропись, $n!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Уничтожьте Шатунишку, ЕД-210, Макса Шмякса и Шлифовальщика, затем вернитесь к Ведуну земли и неба в деревню Таунка\'ле.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, с подручными покончено?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к ведуну земли и неба в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11908,'Справочные материалы','Я ведал уборочными големами – это была ответственная работа, пока Плеть не разорила большинство наших пахотных земель. У меня, впрочем, есть идея, как снова сделать големов полезными.$B$BЯ думаю, что могу переделать схему сборщиков урожая так, чтобы они помогли нам в войне с Плетью.$B$BЯ еще не большой специалист в этом, так что мне потребуется сверяться с руководством. Проблема в том, что я оставил его в мастерской... а моя мастерская, к несчастью, – вон то горящее здание рядом с шахтой. Как думаешь, удастся тебе вытащить оттуда руководство?','По просьбе Иеремии Хоунинга вынесите книгу "Поля, заводы и мастерские" из горящего здания рядом с рудником Далечья.','Отлично! Здесь должна быть нужная мне информация.','Тебе удалось вынести мою книгу?','Вернитесь к Иеремии Хоунингу в Далечье, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Справочные материалы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я ведал уборочными големами – это была ответственная работа, пока Плеть не разорила большинство наших пахотных земель. У меня, впрочем, есть идея, как снова сделать големов полезными.$B$BЯ думаю, что могу переделать схему сборщиков урожая так, чтобы они помогли нам в войне с Плетью.$B$BЯ еще не большой специалист в этом, так что мне потребуется сверяться с руководством. Проблема в том, что я оставил его в мастерской... а моя мастерская, к несчастью, – вон то горящее здание рядом с шахтой. Как думаешь, удастся тебе вытащить оттуда руководство?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Иеремии Хоунинга вынесите книгу "Поля, заводы и мастерские" из горящего здания рядом с рудником Далечья.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Отлично! Здесь должна быть нужная мне информация.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Тебе удалось вынести мою книгу?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Иеремии Хоунингу в Далечье, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11909,'Убить механизатора!','С ним покончено? Угроза, исходящая от механизатора Механозода, ликвидирована?','Вернитесь к Великой Матери Тайге в деревню Таунка\'ле, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Убить механизатора!',`title_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','С ним покончено? Угроза, исходящая от механизатора Механозода, ликвидирована?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Великой Матери Тайге в деревню Таунка\'ле, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11910,'Тайны Древних','Постепенно становится ясно, что нестабильность в этой местности оказывает воздействие и на обитающих тут существ.$B$BЯ особо заинтересовался ледовыми древами и их недавними изменениями. Подозреваю, что их трансформация в зачарованные древа поможет нам разобраться в наших затруднениях.$B$BДля моих исследований мне нужны образцы и с тех, и с других. Поторопись...','По просьбе верховного мага Беринарда из-под Маскировочного щита принесите 3 ледяных осколка и 3 щепки зачарованного древа, собранных с древ в Хладарре.','Ты уже собрал образцы, что я просил?','Вернитесь к верховному магу Беринарду под Маскировочный щит, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Тайны Древних',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Постепенно становится ясно, что нестабильность в этой местности оказывает воздействие и на обитающих тут существ.$B$BЯ особо заинтересовался ледовыми древами и их недавними изменениями. Подозреваю, что их трансформация в зачарованные древа поможет нам разобраться в наших затруднениях.$B$BДля моих исследований мне нужны образцы и с тех, и с других. Поторопись...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе верховного мага Беринарда из-под Маскировочного щита принесите 3 ледяных осколка и 3 щепки зачарованного древа, собранных с древ в Хладарре.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты уже собрал образцы, что я просил?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к верховному магу Беринарду под Маскировочный щит, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11912,'На подножном корму','О! Как приятно в кои-то веки увидеть новое лицо! А то уже такое ощущение, будто мы тут вообще отрезаны от мира.$b$bВо всяком случае от снабжения мы уже несколько дней как отрезаны, так что перспективы у нас, скажем так, мрачноватые. По правде говоря, мы с самого начала шли на верную смерть, если хочешь знать.$b$bА может, это просто не по мне, все это насилие, убийства – не говоря уже о здешних холодах! Эх, сидеть бы сейчас в Даларане, изучать древние тексты...$b$bНо ближе к делу. Наши припасы на исходе. Пожалуйста, постарайся раздобыть какой-нибудь пищи и принеси ее мне!','Соберите 10 ягод снежевики с кустов снежевики в Хладарре по просьбе библиотекаря Серры из лагеря под Маскировочным щитом.','Ну что, удалось раздобыть что-нибудь съедобное?','Вернитесь к библиотекарю Серре под Маскировочный щит, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','На подножном корму',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','О! Как приятно в кои-то веки увидеть новое лицо! А то уже такое ощущение, будто мы тут вообще отрезаны от мира.$b$bВо всяком случае от снабжения мы уже несколько дней как отрезаны, так что перспективы у нас, скажем так, мрачноватые. По правде говоря, мы с самого начала шли на верную смерть, если хочешь знать.$b$bА может, это просто не по мне, все это насилие, убийства – не говоря уже о здешних холодах! Эх, сидеть бы сейчас в Даларане, изучать древние тексты...$b$bНо ближе к делу. Наши припасы на исходе. Пожалуйста, постарайся раздобыть какой-нибудь пищи и принеси ее мне!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Соберите 10 ягод снежевики с кустов снежевики в Хладарре по просьбе библиотекаря Серры из лагеря под Маскировочным щитом.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ну что, удалось раздобыть что-нибудь съедобное?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к библиотекарю Серре под Маскировочный щит, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`completedtext_loc8`) VALUES (11913,'Надо действовать наверняка','Я слышала, что ты $gсказал:сказала; Джеральду, и мне это совсем не нравится. Если сектантам удалось отравить зерно в шахте этой своей чумой, они с легкостью могли отравить зерно и снаружи.$B$BУ нас нет времени перебирать зерно, отделяя хорошее от зараженного. Нужно действовать быстро, и придется сжечь все.$B$BВозьми этот факел и сожги все мешки с зерном, какие найдешь. Будет настоящей трагедией, если мы переживем эту атаку только для того, чтобы стать жертвами чумы...','По просьбе Венди Даррен сожгите 8 мешков с зерном Далечья, воспользовавшись факелом Венди.','Вернитесь к Венди Даррен в Далечье, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Надо действовать наверняка',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Я слышала, что ты $gсказал:сказала; Джеральду, и мне это совсем не нравится. Если сектантам удалось отравить зерно в шахте этой своей чумой, они с легкостью могли отравить зерно и снаружи.$B$BУ нас нет времени перебирать зерно, отделяя хорошее от зараженного. Нужно действовать быстро, и придется сжечь все.$B$BВозьми этот факел и сожги все мешки с зерном, какие найдешь. Будет настоящей трагедией, если мы переживем эту атаку только для того, чтобы стать жертвами чумы...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Венди Даррен сожгите 8 мешков с зерном Далечья, воспользовавшись факелом Венди.',`objectives_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Венди Даррен в Далечье, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11914,'Сохранение секретности','Само наше существование здесь зависит от нашей скрытности. Если щит падет, даже на мгновение, приспешники Малигоса будут тут как тут.$B$BОдной из моих обязанностей является возобновление и восполнение маны у боевых магов, чтобы не ослабела их сосредоточенность. Поскольку мы отрезаны от поставок, мне приходится импровизировать.$B$BТы можешь помочь мне, $n.$B$BСовсем рядом с Нексусом среди потоков магической энергии плавают волшебные змеи. Сраженный змей выделяет субстанцию маны, которая может мне пригодиться.','По просьбе библиотекаря Серры убейте волшебных змеев и принесите за Маскировочный щит 5 субстанций маны Нексуса.','Удалось собрать необходимое количество субстанций маны?','Вернитесь к библиотекарю Серре под Маскировочный щит, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сохранение секретности',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Само наше существование здесь зависит от нашей скрытности. Если щит падет, даже на мгновение, приспешники Малигоса будут тут как тут.$B$BОдной из моих обязанностей является возобновление и восполнение маны у боевых магов, чтобы не ослабела их сосредоточенность. Поскольку мы отрезаны от поставок, мне приходится импровизировать.$B$BТы можешь помочь мне, $n.$B$BСовсем рядом с Нексусом среди потоков магической энергии плавают волшебные змеи. Сраженный змей выделяет субстанцию маны, которая может мне пригодиться.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе библиотекаря Серры убейте волшебных змеев и принесите за Маскировочный щит 5 субстанций маны Нексуса.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось собрать необходимое количество субстанций маны?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к библиотекарю Серре под Маскировочный щит, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`) VALUES (11915,'Игра с огнем','Хочешь научиться кое-чему новому?$b$bНе знаю, сумеешь ли ты когда-нибудь сравниться со мной в искусстве, но если будешь слушать внимательно, то пару-другую фокусов переймешь. Поговори с пламеглотателем-виртуозом в любой столице Орды. Они тебя научат.','Поговорите с пламеглотателем-виртуозом в любой из столиц Орды.','Привет. Хочешь научиться новым трюкам с огнем?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Игра с огнем',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Хочешь научиться кое-чему новому?$b$bНе знаю, сумеешь ли ты когда-нибудь сравниться со мной в искусстве, но если будешь слушать внимательно, то пару-другую фокусов переймешь. Поговори с пламеглотателем-виртуозом в любой столице Орды. Они тебя научат.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поговорите с пламеглотателем-виртуозом в любой из столиц Орды.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Привет. Хочешь научиться новым трюкам с огнем?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`) VALUES (11916,'Воин Адского Крика','Ты встречаешь опасности лицом к лицу и сокрушаешь их железной рукой. Именно благодаря тебе, $n, Орда теперь надежно закрепилась в Нордсколе.$b$bНо наши труды здесь только начинаются. Наш путь лежит к Ледяной Короне! Мы должны сокрушить ее стены!$b$bСейчас же тебе следует отправиться на восток, в деревню Таунка\'ле. У наших союзников (таунка) большие неприятности, им нужна помощь. Добудь себе средство передвижения у Дуркота Брата Волка, смотрителя стойл. В Таунка\'ле отыщи вождя Зимнюю Стужу.','Отыщите вождя Зимнюю Стужу в деревне Таунка\'ле.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Воин Адского Крика',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ты встречаешь опасности лицом к лицу и сокрушаешь их железной рукой. Именно благодаря тебе, $n, Орда теперь надежно закрепилась в Нордсколе.$b$bНо наши труды здесь только начинаются. Наш путь лежит к Ледяной Короне! Мы должны сокрушить ее стены!$b$bСейчас же тебе следует отправиться на восток, в деревню Таунка\'ле. У наших союзников (таунка) большие неприятности, им нужна помощь. Добудь себе средство передвижения у Дуркота Брата Волка, смотрителя стойл. В Таунка\'ле отыщи вождя Зимнюю Стужу.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Отыщите вождя Зимнюю Стужу в деревне Таунка\'ле.',`objectives_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11917,'Ответный удар','Мы должны действовать! Мы должны сохранить равновесие. Время против нас.$b$bВозвращайся в лагерь на Зорамское взморье с большими Камнями Льда. Они пользуются ими для связи с элементалями, как в Силитусе. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...','Убейте лейтенанта Хладоволна, помощника Ахуна, вызвав его при помощи Камня Льда на Зорамском взморье в Ясеневом лесу, затем вернитесь к старейшине Служителей Земли в столицу.','Доброе дело. Оно может показаться малым, но даже это поможет великой битве. Прими это вместе с моим благословением, а потом возвращайся, ибо у меня найдется для тебя еще дело.','Ты $Gвернулся:вернулась; $Gпобедителем:победительницей;?','Вернитесь к старейшине Служителей Земли.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Ответный удар',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Мы должны действовать! Мы должны сохранить равновесие. Время против нас.$b$bВозвращайся в лагерь на Зорамское взморье с большими Камнями Льда. Они пользуются ими для связи с элементалями, как в Силитусе. Хотя мне ужасно не хочется этого делать, но духи поймут – тебе придется вызвать одного из помощников Ахуна и уничтожить его. Возможно, этого упреждающего удара будет достаточно...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте лейтенанта Хладоволна, помощника Ахуна, вызвав его при помощи Камня Льда на Зорамском взморье в Ясеневом лесу, затем вернитесь к старейшине Служителей Земли в столицу.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Доброе дело. Оно может показаться малым, но даже это поможет великой битве. Прими это вместе с моим благословением, а потом возвращайся, ибо у меня найдется для тебя еще дело.',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ты $Gвернулся:вернулась; $Gпобедителем:победительницей;?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к старейшине Служителей Земли.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11918,'Первое знакомство','Это война, $gсмертный:смертная;, и мы – в гуще схватки!$b$bВаши мелкие свары из-за земель или денег бледнеют перед этим конфликтом. Нас ждет встреча с Аспектом Малигосом и его синими драконами. Тебе достаточно знать, что, если Малигос одержит победу, этого мира больше не будет.$b$bНас тут мало, и мы сражаемся против многих. Можно считать, что мы обречены, и, если нам удастся хотя бы задержать врага, это уже будет успех.$b$bСтупай же. Найди себе какое-нибудь дело, пока я решу, что делать с тобой.','Убейте 10 чаровязов Хладарры по просьбе Релораза из лагеря под Маскировочным щитом.','Удалось собрать необходимое количество субстанций маны?','Вернитесь к Релоразу под Маскировочный щит, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Первое знакомство',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Это война, $gсмертный:смертная;, и мы – в гуще схватки!$b$bВаши мелкие свары из-за земель или денег бледнеют перед этим конфликтом. Нас ждет встреча с Аспектом Малигосом и его синими драконами. Тебе достаточно знать, что, если Малигос одержит победу, этого мира больше не будет.$b$bНас тут мало, и мы сражаемся против многих. Можно считать, что мы обречены, и, если нам удастся хотя бы задержать врага, это уже будет успех.$b$bСтупай же. Найди себе какое-нибудь дело, пока я решу, что делать с тобой.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Убейте 10 чаровязов Хладарры по просьбе Релораза из лагеря под Маскировочным щитом.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось собрать необходимое количество субстанций маны?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Релоразу под Маскировочный щит, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`requestitemstext_loc8`,`completedtext_loc8`) VALUES (11919,'Охота на драконов','Синие начали наносить на своих драконов таинственные руны. Я должен выяснить их значение.$B$B<Релораз протыкает руку копьем и смазывает кровью наконечник.>$B$BВозьми это копье и воздействуй им на одного из них. Подожди, пока он не подчинится, а затем принеси мне, пока не кончится действие крови.$B$BИх детеныши кормятся на северо-западном крае долины.','По просьбе Релораза используйте копье с окровавленным наконечником, чтобы подчинить детеныша дракона Нексуса, а затем принесите Релоразу копье назад за Маскировочный щит.','Удалось ли тебе встретиться с Керистразой?','Вернитесь к Релоразу под Маскировочный щит, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Охота на драконов',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Синие начали наносить на своих драконов таинственные руны. Я должен выяснить их значение.$B$B<Релораз протыкает руку копьем и смазывает кровью наконечник.>$B$BВозьми это копье и воздействуй им на одного из них. Подожди, пока он не подчинится, а затем принеси мне, пока не кончится действие крови.$B$BИх детеныши кормятся на северо-западном крае долины.',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','По просьбе Релораза используйте копье с окровавленным наконечником, чтобы подчинить детеныша дракона Нексуса, а затем принесите Релоразу копье назад за Маскировочный щит.',`objectives_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Удалось ли тебе встретиться с Керистразой?',`requestitemstext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к Релоразу под Маскировочный щит, что в Борейской тундре.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`offerrewardtext_loc8`) VALUES (11920,'Сектанты среди нас','На этом алтаре полным-полно знаков Культа Проклятых. Похоже, фанатики с материка добрались уже и до Нордскола. Благоразумие требует сообщить об этом капитану корабля.$B$BВероятно, его можно найти на палубе.','Сектанты? Внизу?! Придется мне всю команду выпороть!$B$BПослушай... почему бы... почему бы адмиралу Кэнтлбри не разобраться с этой... с этой ситуацией?') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Сектанты среди нас',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','На этом алтаре полным-полно знаков Культа Проклятых. Похоже, фанатики с материка добрались уже и до Нордскола. Благоразумие требует сообщить об этом капитану корабля.$B$BВероятно, его можно найти на палубе.',`details_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Сектанты? Внизу?! Придется мне всю команду выпороть!$B$BПослушай... почему бы... почему бы адмиралу Кэнтлбри не разобраться с этой... с этой ситуацией?',`offerrewardtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11921,'Опять бросаем факелы','Привет, $Gфакельный жонглер:факельная циркачка;! Нравится устраивать огненную неразбериху? Приятно слышать! Думаешь, ты так уж и $Gкрут:крута;?Давай проверим...$B$BПравила ты знаешь: бросаешь факел в отмеченные жаровни. Но на сей раз у тебя больше времени и НАМНОГО больше жаровен.$B$B$GГотов:Готова;?','Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом.','Ух ты! Ну ты и даешь! Может, на следующий год получишь работку на празднике!','Быстро! Нет времени чтобы терять его зря!','Попадите в 20 жаровен.','Вернитесь к огнеглотателю-виртуозу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опять бросаем факелы',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Привет, $Gфакельный жонглер:факельная циркачка;! Нравится устраивать огненную неразбериху? Приятно слышать! Думаешь, ты так уж и $Gкрут:крута;?Давай проверим...$B$BПравила ты знаешь: бросаешь факел в отмеченные жаровни. Но на сей раз у тебя больше времени и НАМНОГО больше жаровен.$B$B$GГотов:Готова;?',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Ух ты! Ну ты и даешь! Может, на следующий год получишь работку на празднике!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Быстро! Нет времени чтобы терять его зря!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Попадите в 20 жаровен.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к огнеглотателю-виртуозу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`requestitemstext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11923,'Поймай факел!','Ну, факел ты теперь бросать умеешь, так посмотри, сможешь ли ты его еще и поймать!$B$BБери эту связку незажженных факелов. Ступай к костру и подбрось факел высоко в воздух. Поймай его прежде, чем он коснется земли... затем снова подбрось его в воздух! Поймай четыре факела подряд, затем возвращайся ко мне.$B$BОсторожнее! Они опасны при ударе о землю! И не пропусти ни одного! Если пропустишь, придется вернуться к костру и начать все с начала. Удачи!','Поймайте подряд 4 факела, затем поговорите с пламеглотателем-виртуозом.','Не $Gобжегся:обожглась;? Если да, то дважды подумай прежде, чем играть с огнем...$B$BШучу! Все вышло здорово! И это уже не шутка. Ты – отличный огненный жонглер! Теперь иди, веселись!','Ловля факелов - это очень весело, тебе не кажется? Но будь $Gосторожен:осторожна;! Ты же не хочешь опалиться!','Поймать 4 факела подряд.','Вернитесь к пламеглотателю-виртуозу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Поймай факел!',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','Ну, факел ты теперь бросать умеешь, так посмотри, сможешь ли ты его еще и поймать!$B$BБери эту связку незажженных факелов. Ступай к костру и подбрось факел высоко в воздух. Поймай его прежде, чем он коснется земли... затем снова подбрось его в воздух! Поймай четыре факела подряд, затем возвращайся ко мне.$B$BОсторожнее! Они опасны при ударе о землю! И не пропусти ни одного! Если пропустишь, придется вернуться к костру и начать все с начала. Удачи!',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте подряд 4 факела, затем поговорите с пламеглотателем-виртуозом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не $Gобжегся:обожглась;? Если да, то дважды подумай прежде, чем играть с огнем...$B$BШучу! Все вышло здорово! И это уже не шутка. Ты – отличный огненный жонглер! Теперь иди, веселись!',`offerrewardtext_loc8`), `requestitemstext_loc8`=IF(`requestitemstext_loc8` IS NULL OR `requestitemstext_loc8`='','Ловля факелов - это очень весело, тебе не кажется? Но будь $Gосторожен:осторожна;! Ты же не хочешь опалиться!',`requestitemstext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поймать 4 факела подряд.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к пламеглотателю-виртуозу.',`completedtext_loc8`);
INSERT INTO `locales_quest` (`id`,`title_loc8`,`details_loc8`,`objectives_loc8`,`offerrewardtext_loc8`,`endtext_loc8`,`completedtext_loc8`) VALUES (11924,'Опять жонглирование факелами','При жонглировании факелами определенно приходится быть начеку. Как думаешь, долго продержишься?$B$BПосмотрим-ка...','Поймайте 10 факелов подряд, затем поговорите с пламеглотателем-виртуозом.','Не $Gобжегся:обожглась;? Если да, то дважды подумай прежде, чем играть с огнем...$B$BШучу! Все вышло здорово! И это уже не шутка. Ты – отличный огненный жонглер! Теперь иди, веселись!','Поймайте 10 факелов подряд.','Вернитесь к огнеглотателю-виртуозу.') ON DUPLICATE KEY UPDATE `title_loc8`=IF(`title_loc8` IS NULL OR `title_loc8`='','Опять жонглирование факелами',`title_loc8`), `details_loc8`=IF(`details_loc8` IS NULL OR `details_loc8`='','При жонглировании факелами определенно приходится быть начеку. Как думаешь, долго продержишься?$B$BПосмотрим-ка...',`details_loc8`), `objectives_loc8`=IF(`objectives_loc8` IS NULL OR `objectives_loc8`='','Поймайте 10 факелов подряд, затем поговорите с пламеглотателем-виртуозом.',`objectives_loc8`), `offerrewardtext_loc8`=IF(`offerrewardtext_loc8` IS NULL OR `offerrewardtext_loc8`='','Не $Gобжегся:обожглась;? Если да, то дважды подумай прежде, чем играть с огнем...$B$BШучу! Все вышло здорово! И это уже не шутка. Ты – отличный огненный жонглер! Теперь иди, веселись!',`offerrewardtext_loc8`), `endtext_loc8`=IF(`endtext_loc8` IS NULL OR `endtext_loc8`='','Поймайте 10 факелов подряд.',`endtext_loc8`), `completedtext_loc8`=IF(`completedtext_loc8` IS NULL OR `completedtext_loc8`='','Вернитесь к огнеглотателю-виртуозу.',`completedtext_loc8`);
